SET NAMES 'utf8';

UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제발, 제발 좀 도와주시오! 난 여기 갇혀 있소!', `MaleText_loc4`='救命啊！我动不了了！', `MaleText_loc5`='救命啊!我動不了了!', `MaleText_loc7`='¡Socorro! ¡Socorro! ¡Soy víctima de represión!' WHERE `ID`=1;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='중대.. 제자리에 서! ... 정렬!', `MaleText_loc4`='全队……立正！……集合！', `MaleText_loc5`='全體...立正!...集合!', `MaleText_loc7`='Compañía... ¡ALTO! ¡Formen FILAS!' WHERE `ID`=3;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앞으로... 가!', `MaleText_loc4`='前进……前进！', `MaleText_loc5`='起步...走!!', `MaleText_loc7`='Adelante... ¡¡MARCHEN!!' WHERE `ID`=4;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='덤벼! 문명인답게 주먹으로 싸우자고!', `MaleText_loc4`='来，让我们击掌为盟，就像文明人那样。', `MaleText_loc5`='來，讓我們像文明人那樣來場拳賽吧。', `MaleText_loc7`='Venga, liémonos a tortazos, como gente civilizada.' WHERE `ID`=5;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 고맙소!', `MaleText_loc4`='太感谢你了！', `MaleText_loc5`='太感謝你了!', `MaleText_loc7`='¡Muchas gracias!' WHERE `ID`=7;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 따라오쇼, $n. 데피아즈단의 은신처로 데려다 드리지. 하지만 내가 봉변을 당하지 않도록 잘 지켜 줘야 하오.', `MaleText_loc4`='跟着我，$n。我会把你带到迪菲亚兄弟会的老巢里。但是你最好能保护我，不然我就死定了。', `MaleText_loc5`='跟著我，$n。我會把你帶到迪菲亞兄弟會的藏身處。但你最好能保護我，不然我就死定了。', `MaleText_loc7`='Sígueme, $n. Te llevaré a la Ladronera Defias. Pero será mejor que me protejas o no saldré con vida.' WHERE `ID`=9;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='입구는 이곳 달빛시내 마을에 숨겨져 있소. 도적들이 없는지 잘 살피시오. 놈들은 날 없애고 싶어할 거요.', `MaleText_loc4`='入口就隐藏在月溪镇里。注意那些盗贼，他们想要我的命。', `MaleText_loc5`='入口就隱藏在月溪鎮裡。注意那些盜賊，他們想要我的命。', `MaleText_loc7`='La entrada está oculta aquí en Arroyo de la Luna. Mantén los ojos abiertos por si aparece algún ladrón. Quieren matarme.' WHERE `ID`=10;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스타우트맨틀 경에게 가서 바로 이곳에 데피아즈단이 숨어 있다고 전해주쇼.', `MaleText_loc4`='你可以去告诉斯托曼，这里就是迪菲亚盗贼的藏身之处，$n。', `MaleText_loc5`='你可以去告訴斯托曼，這裡就是迪菲亞盜賊的藏身之處，$n。', `MaleText_loc7`='Puedes ir a ver a Mantorrecio y decirle que aquí se esconde la banda Defias, $n.' WHERE `ID`=11;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일해, 이 쓰레기 같은 녀석!', `MaleText_loc4`='干活，你们这帮废物！', `MaleText_loc5`='工作，你們這些廢物!', `MaleText_loc7`='¡Trabajad, escoria!' WHERE `ID`=13;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크르르르! 이 바보 같은 놈들!', `MaleText_loc4`='啊啊啊啊！白痴！', `MaleText_loc5`='啊啊啊啊!白癡!', `MaleText_loc7`='¡Grrrr! ¡Idiotas!' WHERE `ID`=14;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무짝에도 쓸모없는 코볼트 놈들!', `MaleText_loc4`='毫无价值的废物！', `MaleText_loc5`='沒路用的狗頭人!', `MaleText_loc7`='¡No valéis para nada, kóbolds!' WHERE `ID`=15;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 모두 조심하도록!', `MaleText_loc4`='好了，伙计们，振作些！', `MaleText_loc5`='好了，夥計們，振作些!', `MaleText_loc7`='¡Vamos, señores, arriba ese ánimo!' WHERE `ID`=16;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자 자, 이보라고! 기상 시간이야!', `MaleText_loc4`='弟兄们，该起床了！', `MaleText_loc5`='弟兄們，該起來了!', `MaleText_loc7`='¡Ya está bien, chicos! Es hora de levantarse.' WHERE `ID`=17;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 날 따라와!', `MaleText_loc4`='嘿，跟着我！', `MaleText_loc5`='嘿，跟著我!', `MaleText_loc7`='¡Vamos, seguidme!' WHERE `ID`=19;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 한 무리를 데려왔군!', `MaleText_loc4`='又弄来了一头！', `MaleText_loc5`='又弄來了一頭!', `MaleText_loc7`='¡Otra manada que se pone en marcha!' WHERE `ID`=22;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저, 여기 있습니다. 다시 합류할 준비도 됐고...', `MaleText_loc4`='我来了，我准备重新加入……', `MaleText_loc5`='我來了，我準備好重新加入了...', `MaleText_loc7`='Aquí estoy. Listo para reincorporarme...' WHERE `ID`=23;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 그 누구와도 합류하지 못할 거다, 토르센..', `MaleText_loc4`='索尔森，你没机会加入任何组织了…', `MaleText_loc5`='托爾森，你沒機會去找別人了...', `MaleText_loc7`='Tú no vienes, Thorsen...' WHERE `ID`=24;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 심각한 부상을 입었습니다. 상처 때문에 더 빨리 걷는 건 무리이니 늦게 걷더라도 이해해 주십시오.', `MaleText_loc4`='我伤得很重。很抱歉我不能走得更快一些。', `MaleText_loc5`='我傷得很重。請原諒我步履蹣跚，但我的傷害我無法再走更快了。', `MaleText_loc7`='Mis heridas son graves. Disculpa mi paso lento, pero las heridas no me permiten caminar más rápido.' WHERE `ID`=25;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 드디어 신선한 공기를 마시게 되는군요! 잠시 쉬어야 할 것 같습니다.', `MaleText_loc4`='啊，新鲜的空气！我要休息一下。', `MaleText_loc5`='啊，終於能呼吸新鮮的空氣啦!我要休息片刻。', `MaleText_loc7`='¡Por fin, un poco de aire fresco! Necesito descansar un momento.' WHERE `ID`=26;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 지역에는 검은바위 부족이 자주 출몰합니다. 사력을 다해 따라가겠습니다. 어서 가십시오!', `MaleText_loc4`='黑石氏族的兽人在这一带部署了不少兵力，我会尽我所能跟上你。我们出发吧！', `MaleText_loc5`='黑石氏族的獸人在這一帶部署了不少兵力，我會盡我所能跟上你，$n。我們出發吧!', `MaleText_loc7`='Todo esto está plagado de Roca Negra. Haré todo lo que pueda para seguir el ritmo. ¡Vamos!' WHERE `ID`=27;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 축복받은 땅, 호숫골에 거의 다 왔습니다. 부디, 제 다리가 조금만 더 움직여 주기를...', `MaleText_loc4`='离湖畔镇很近了。以圣光的名义，让我坚持到那里吧！', `MaleText_loc5`='離湖畔鎮很近了。聖光保佑，讓我的雙腿能再多撐一會兒吧!', `MaleText_loc7`='Tan cerca de la bendita Villa del Lago. Por la Luz, ¡que mis piernas me lleven un poco más lejos!' WHERE `ID`=28;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='매리스 치안대장님, 제 12 기병 연대 소속 하사관 키샨, 전투에서 돌아와 보고드립니다!', `MaleText_loc4`='马瑞斯大人！第12军团的基沙恩下士从战场返回，前来报到！', `MaleText_loc5`='瑪瑞斯大人!第12軍團的基沙恩下士從戰場返回，前來報到!', `MaleText_loc7`='Alguacil Marris, señor. ¡Cabo Keeshan del 12.º Regimiento del Sable se presenta tras volver de la contienda!' WHERE `ID`=29;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용감한 여행자여, 구해 주셔서 정말 고맙습니다! 매리스 치안대장께서 분명히 당신의 친절한 행동에 대한 보상을 해주실 겁니다.', `MaleText_loc4`='勇敢的冒险者，谢谢你救了我！我保证马瑞斯大人会重赏你的。', `MaleText_loc5`='勇敢的冒險者，謝謝你救了我!我保證瑪瑞斯大人會因為你的善行賞賜你的。', `MaleText_loc7`='¡Gracias por rescatarme, valiente! Doy por seguro que el alguacil Marris sabrá recompensar tu noble acto.' WHERE `ID`=30;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안토니오 페렐리표 기적의 비약을 팝니다!', `MaleText_loc4`='出售安东尼奥·皮雷利的万能药！', `MaleText_loc5`='出售安東尼奧·皮雷利的萬能藥!', `MaleText_loc7`='¡Vendo los elixires milagrosos de Antonio Perelli!' WHERE `ID`=33;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 어서 오세요! 모두 와서 구경해 보세요! 페렐리표 비약을 보시면 깜짝 놀라실 겁니다!', `MaleText_loc4`='来看看吧！皮雷利的万能药会让你看得眼花缭乱的！', `MaleText_loc5`='來看看吧!皮雷利的萬能藥會讓你看得眼花繚亂的!', `MaleText_loc7`='¡Vamos! ¡Vamos! ¡Los elixires de Perelli os encantarán!' WHERE `ID`=35;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='석공... 에.. 그리고 데피아즈단은 주의하라. 오늘 밤 녹슨 닻이 내려질 것이다.', `MaleText_loc4`='石匠……呃，迪菲亚兄弟会的成员们请注意：今晚抛锚。', `MaleText_loc5`='石匠們...呃...迪菲亞兄弟會的成員們，請注意:今晚拋下生鏽的錨。', `MaleText_loc7`='Canteros... err... Que avisen a Defias: El ancla oxidada se hundirá esta noche.' WHERE `ID`=36;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두목께서 모두 만반의 태세를 갖추라고 하신다. 오늘 밤 녹슨 닻이 내려질 것이다.', `MaleText_loc4`='首领要求大家提高警惕。今晚抛锚。', `MaleText_loc5`='首領要求大家提高警惕。今晚拋下生鏽的錨。', `MaleText_loc7`='El jefe quiere que todos estén en máxima alerta. Esta noche hundimos la vieja ancla.' WHERE `ID`=37;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 금을 거두러 여기 온 것이다.', `MaleText_loc4`='我是来拿金子的。', `MaleText_loc5`='我是來拿金子的。', `MaleText_loc7`='He venido por oro.' WHERE `ID`=38;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사방에 도적들이 깔려 있네. 우리, 백성의 민병대는 반드시 이 땅을 농부들의 손에 되돌려 주어야 하네.', `MaleText_loc4`='这里到处都是盗贼。我们人民军必须把他们占据的土地还给农夫们。', `MaleText_loc5`='這裡到處都是盜賊。我們人民軍必須把他們佔據的土地還給農夫們。', `MaleText_loc7`='Veo ladrones por doquier. Nosotros, las Milicias del Pueblo, debemos devolver esta tierra a los agricultores.' WHERE `ID`=39;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='농장을 적의 손아귀에서 되찾아야 하네. 스톰윈드는 이들을 버렸을지 모르지만 난 절대 버리지 않을 걸세.', `MaleText_loc4`='我们必须解放这些农田。暴风城已经抛弃了这些人，但如果我们也这样做，那我会感到羞耻。', `MaleText_loc5`='我們必須解放這片農田。暴風城或許已經拋棄了這些人，但我是絕對不會放棄的!', `MaleText_loc7`='Hay que liberar las tierras. Ventormenta puede haber abandonado a esta gente, pero que me condenen si yo hago lo mismo.' WHERE `ID`=40;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='측면에서 데피아즈단의 활동이 보고되고 있습니다. 감시의 언덕은 이상 없습니다.', `FemaleText_loc4`='据报告，迪菲亚兄弟会正在海岸附近活动。哨兵岭警报解除。', `FemaleText_loc5`='據報告，迪菲亞兄弟會正在海岸附近活動。哨兵嶺警報解除。', `FemaleText_loc7`='Tenemos noticias de actividad de la Hermandad Defias a lo lejos en la costa. La Colina del Centinela está despejada.' WHERE `ID`=41;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황금해안 채석장과 장고로드 광산에서 놀의 활동이 다수 보고되고 있습니다.', `MaleText_loc4`='据报告，有大量豺狼人在金海岸矿洞和詹戈洛德矿洞地区活动。', `MaleText_loc5`='在金海岸礦坑和詹戈洛德礦坑地區有大量豺狼人活動。', `MaleText_loc7`='Han llegado informes de una intensa actividad gnoll en la Mina de la Costa de Oro y en la Mina de Jango.' WHERE `ID`=42;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감시의 언덕은 이상 없습니다, 스타우트맨틀 경. 그런데 달빛시내 마을에서 데피아즈단의 대규모 활동이 보고되고 있습니다.', `MaleText_loc4`='斯托曼大人，哨兵岭的警报已经解除。但有报告称月溪镇地区出现了大量的迪菲亚盗贼。', `MaleText_loc5`='斯托曼大人，哨兵嶺的警報已經解除。但有報告稱月溪鎮地區出現了大量的迪菲亞盜賊。', `MaleText_loc7`='La Colina del Centinela está despejada, Lord Mantorrecio. No obstante, se registra bastante movimiento de la Hermandad Defias en Arroyo de la Luna.' WHERE `ID`=43;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서부 몰락지대의 주민들은 자신들을 버린 스톰윈드를 결코 용서치 않을 것이다.', `MaleText_loc4`='暴风城背信弃义的行为永远也无法得到西部荒野人民的原谅。', `MaleText_loc5`='暴風城背信棄義的行為永遠也無法得到西部荒野人民的原諒。', `MaleText_loc7`='El abandono de Ventormenta no será olvidado por los habitantes de los Páramos de Poniente.' WHERE `ID`=44;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐 재미난 일 없을까...', `MaleText_loc4`='没有鱼上钩……', `MaleText_loc5`='沒有魚上鉤...', `MaleText_loc7`='No cae un solo pez...' WHERE `ID`=45;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 물고기야... 이리 와서 물어라...', `MaleText_loc4`='小鱼小鱼快上钩……', `MaleText_loc5`='小魚小魚快上鉤...', `MaleText_loc7`='Pececito, pececito... ven con papaíto.' WHERE `ID`=46;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 어서 한잔들 하세요!', `MaleText_loc4`='来这里坐坐，喝一杯！', `MaleText_loc5`='來這裡坐坐，喝一杯!', `MaleText_loc7`='¡Coge un taburete y tómate algo!' WHERE `ID`=47;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='술병은 먼지투성이지만 술맛은 호숫골에서 최고입니다!', `MaleText_loc4`='瓶子表面布满了灰尘，但是里面的酒却很纯净！', `MaleText_loc5`='瓶子雖然髒，但是裡面的酒是乾淨的!', `MaleText_loc7`='¡Las botellas están llenas de polvo, pero pronto las dejaremos limpias!' WHERE `ID`=48;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제발 스톰윈드에서 증원군이 빨리 와야 할 텐데...', `FemaleText_loc4`='希望暴风城的增援快点到来……', `FemaleText_loc5`='希望暴風城的增援快點到來...', `FemaleText_loc7`='Espero que aparezcan pronto los refuerzos procedentes de Ventormenta...' WHERE `ID`=49;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 이 다리는 반드시 복구해야 하니까 모두 힘내라고.', `MaleText_loc4`='快点，伙计们，我们要尽快重建这座桥。', `MaleText_loc5`='快點，兄弟們，我們要儘快重建這座橋。', `MaleText_loc7`='Vamos, chicos, tenemos que reconstruir este puente.' WHERE `ID`=50;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대체 스톰윈드에서 온다는 증원군은 어디 있는 거야? 동쪽 지역에서 검은바위 부족의 대규모 활동이 보고되고 있는 이 시점에...', `MaleText_loc4`='暴风城的增援在哪里？东边那些黑石兽人的活动越来越频繁了。', `MaleText_loc5`='暴風城的增援在哪裡?東邊那些黑石獸人的活動越來越頻繁了。', `MaleText_loc7`='¿Dónde están todos los refuerzos de Ventormenta? Se ha registrado gran actividad de los Roca Negra en el este.' WHERE `ID`=51;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드에서 오기로 한 제2 대대는 아직 아무 소식도 없고, 북동 지역에서 잿빛가죽 일족의 움직임이 보고되고 있으니...', `MaleText_loc4`='仍然没有暴风城第二军团会赶来增援的迹象，而东北方的暗皮豺狼人又在蠢蠢欲动。', `MaleText_loc5`='仍然沒有暴風城第二軍團會趕來增援的跡象，而東北方的影皮豺狼人又在蠢蠢欲動。', `MaleText_loc7`='Seguimos sin saber nada del segundo batallón procedente de Ventormenta. Recibimos noticias de que los Pielsombra están por el noreste.' WHERE `ID`=52;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='매리스 치안대장님은 곧 스톰윈드에서 예비 병력이 도착하기를 기다리고 계시는데...', `MaleText_loc4`='马瑞斯大人无时无刻不在期待着暴风城的增援……', `MaleText_loc5`='瑪瑞斯大人無時無刻不在期待著暴風城的增援...', `MaleText_loc7`='El alguacil Marris espera la llegada de las reservas de Ventormenta en cualquier momento...' WHERE `ID`=53;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='걱정하지 마, 블랑쉬. 곧 먹을 걸 찾아다 줄 테니...', `FemaleText_loc4`='不要担心，布兰契，我们很快就有东西给你吃了……', `FemaleText_loc5`='不要擔心，布蘭契，我們很快就有東西給你吃了...', `FemaleText_loc7`='No te preocupes, vieja Blanchy, pronto te traeremos algo de comer...' WHERE `ID`=54;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내가 고향 땅 서부 몰락지대를 떠나게 될 날이 올 줄은 꿈에도 생각 못 했는데...', `FemaleText_loc4`='我从来就没想过有一天我会离开西部荒野，离开我的家……', `FemaleText_loc5`='我從來就沒想過有一天我會離開西部荒野，離開我的家...', `FemaleText_loc7`='Nunca pensé que llegaría el día en que tuviese que abandonar mi querida tierra de los Páramos de Poniente...' WHERE `ID`=55;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='포세이큰 마차가 부서져 버리다니, 믿을 수가 없어. 이제 이 땅에서는 좋은 일이라고는 일어나지 않는군...', `MaleText_loc4`='这辆该死的马车居然坏了。倒霉啊……', `MaleText_loc5`='這輛該死的馬車居然壞了。倒楣啊...', `MaleText_loc7`='No puedo creer que se averiara el carro de los Renegados. No hay más que desgracia en esta tierra...' WHERE `ID`=56;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 마차를 수리하는 대로 이곳을 떠날 거요.', `MaleText_loc4`='当我把这辆马车修好后，咱们就马上离开这里……', `MaleText_loc5`='當我把這輛馬車修好後，咱們就馬上離開這裡...', `MaleText_loc7`='Saldremos de aquí tan pronto como consiga arreglar este vagón...' WHERE `ID`=57;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 대체 저 기계덩어리들을 어떻게 내 농장에서 몰아내야 할지...', `MaleText_loc4`='我怎么才能把这些机械怪物赶出我的农田啊？', `MaleText_loc5`='我怎麼才能把這些機械怪物趕出我的農田啊?', `MaleText_loc7`='¿Y ahora cómo se supone que voy a sacar a esos miserables seres mecánicos de mis campos?' WHERE `ID`=58;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살인자와 도적들 따위가 날 내 땅에서 쫓아낼 수는 없어!', `MaleText_loc4`='就凭你们这些歹徒和盗贼是不可能把我从自己的土地上赶走的！', `MaleText_loc5`='就憑你們這些歹徒和盜賊是不可能把我從自己的土地上趕走的!', `MaleText_loc7`='¡Una panda de matones y ladrones no me van a echar de mi tierra!' WHERE `ID`=59;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 다른 농부들을 모두 쫓아냈을지는 모르지만, 나 살딘은 절대 서부 몰락지대를 떠나지 않을 것이다!', `MaleText_loc4`='他们也许能赶走其他的农夫，但是萨丁一家是永远也不会离开西部荒野的。', `MaleText_loc5`='他們也許能趕走其他的農夫，但是薩丁一家是永遠也不會離開西部荒野的。', `MaleText_loc7`='Puede que todos los demás granjeros hayan salido huyendo, pero los Saldean nunca dejarán los Páramos de Poniente.' WHERE `ID`=60;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='숲에 온통 언데드가 들끓으니 길을 잘 따라가시기 바랍니다.', `FemaleText_loc4`='不要离开大路。森林里到处都是亡灵。', `FemaleText_loc5`='不要離開大路。森林裡到處都是亡靈。', `FemaleText_loc7`='Quedaos por los caminos. El bosque está invadido de no-muertos.' WHERE `ID`=61;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='두려워할 것 없어요. 어둠의 순찰대가 이 땅에서 이 사악한 세력을 곧 뿌리 뽑아 버릴 테니까요!', `FemaleText_loc4`='不要害怕。守夜人很快就会把这里的邪恶力量完全清除的。', `FemaleText_loc5`='不要害怕。守夜人很快就會把這裡的邪惡力量完全清除的。', `FemaleText_loc7`='No temas. La Guardia Nocturna pronto librará estas tierras de esta peste nauseabunda.' WHERE `ID`=62;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 땅 곳곳에 언데드가 득실거리고 있는데 도대체 스톰윈드 군대는 어디에 있는 것인가?', `MaleText_loc4`='亡灵在这里四处横行！但暴风城的军队在哪里？', `MaleText_loc5`='亡靈在這裡四處橫行!但暴風城的軍隊在哪裡?', `MaleText_loc7`='Los no-muertos se arrastran por toda esta tierra. ¿Dónde está el ejército de Ventormenta?' WHERE `ID`=63;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠의 순찰대만으로는 우릴 영원히 안전하게 지킬 수 없네. 스톰윈드 군대의 지원이 필요하네.', `MaleText_loc4`='仅仅依靠守夜人并不能永远地保护我们。我们需要暴风城军队的援助。', `MaleText_loc5`='僅僅依靠守夜人並不能永遠地保護我們。我們需要暴風城軍隊的援助。', `MaleText_loc7`='La Guardia Nocturna sola no puede protegernos eternamente. Necesitamos el apoyo del ejército de Ventormenta.' WHERE `ID`=64;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 땅에 어둠의 그림자를 드리운 악의 세력에 굴복할 수는 없네. 어둠의 순찰대는 반드시 승리할 것일세!', `MaleText_loc4`='我们决不向邪恶的势力屈服。守夜人一定会胜利的！', `MaleText_loc5`='我們決不向邪惡的勢力屈服。守夜人一定會勝利的!', `MaleText_loc7`='No debemos ceder ante el mal que ha ensombrecido nuestra tierra. ¡La Guardia Nocturna vencerá!' WHERE `ID`=65;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='숲에 늑대인간과 구울이 득실대고 있소. 어떤 조치든 취해야 하오!', `MaleText_loc4`='森林里到处都是狼人和食尸鬼。我们必须有所行动！', `MaleText_loc5`='森林裡到處都是狼人和食屍鬼。我們必須有所行動!', `MaleText_loc7`='El bosque está plagado de necrófagos y huargen. ¡Hay que hacer algo!' WHERE `ID`=66;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드에서 뭔가 조치를 취해줘야 하오. 우리의 터전이 언데드의 손아귀에 넘어가고 있소.', `MaleText_loc4`='我们需要暴风城更积极的反应和更多的支援，我们的家园正在遭到亡灵的进攻。', `MaleText_loc5`='我們需要暴風城更積極的反應和更多的支援，我們的家園正在遭到亡靈的進攻。', `MaleText_loc7`='Necesitamos una mayor presencia de Ventormenta. Nuestros hogares están cayendo en manos de los no-muertos.' WHERE `ID`=67;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그늘숲 의회는 조치를 취해야 합니다. 악의 세력이 퍼져 나가고 있습니다.', `MaleText_loc4`='暮色森林的议会必须行动起来了。这里已经充满了邪恶。', `MaleText_loc5`='暮色森林的議會必須行動起來，邪惡的氣息已經蔓延開來。', `MaleText_loc7`='El Consejo del Bosque del Ocaso debe tomar medidas. El mal flota en el aire.' WHERE `ID`=68;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠골의 주민들은 의회가 좀 더 적극적인 조치를 취하기를 바라고 있습니다. 우리를 괴롭히는 이 부정한 침략에 그들이 고통받도록 내버려 둘 순 없습니다.', `MaleText_loc4`='夜色镇的人民对议会充满了期望。我们不能让他们受到邪恶的伤害。', `MaleText_loc5`='夜色鎮的人民對議會充滿了期望。我們不能讓他們受到邪惡生物的傷害。', `MaleText_loc7`='La gente de Villa Oscura espera más del Consejo. No podemos dejar que padezcan esta Peste nefasta que nos asola.' WHERE `ID`=69;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='논쟁만 계속해서는 아무 소득도 없습니다! 행동을 해야 합니다.', `MaleText_loc4`='争吵不休对我们一点用都没有。我们需要的是实际行动。', `MaleText_loc5`='爭吵不休對我們一點用都沒有。我們需要的是實際行動。', `MaleText_loc7`='Nuestras eternas discusiones no nos llevarán a ninguna parte. Tenemos que actuar.' WHERE `ID`=70;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드에서 좋지 않은 소식이 왔습니다...', `MaleText_loc4`='从暴风城来的消息似乎不太妙……', `MaleText_loc5`='從暴風城來的消息似乎不太妙...', `MaleText_loc7`='Las noticias de Ventormenta no presagian nada bueno...' WHERE `ID`=71;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드의 저 두꺼운 돌 성벽 너머에 있는 귀머거리들은 우리의 뜻을 듣지도 않는군요.', `MaleText_loc4`='看来我们已经被暴风城完全抛弃了。', `MaleText_loc5`='看來我們已經被暴風城完全拋棄了。', `MaleText_loc7`='Nuestra causa es ignorada más allá de los gruesos muros de piedra de Ventormenta.' WHERE `ID`=72;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='악이 싹트고 있는 게 느껴져...', `FemaleText_loc4`='我感到邪恶的力量正在滋生……', `FemaleText_loc5`='我感到邪惡的力量正在滋生...', `FemaleText_loc7`='Se avecina algo malo, lo sé...' WHERE `ID`=73;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='별들이 내게 경고하고 있어.. 밤의 어둠 속에서 우릴 기다리고 있는 공포를...', `FemaleText_loc4`='星星告诉我，今晚会发生一些恐怖的事情。', `FemaleText_loc5`='星辰告訴我，恐怖的事情正在黑夜中靜候。', `FemaleText_loc7`='Oigo hablar a las estrellas. Murmuran los horrores que nos aguardan por la noche.' WHERE `ID`=74;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='과거와 다르지 않은 커다란 죽음과 불안이 우리 앞에 기다리고 있어.', `FemaleText_loc4`='未来充满了死亡和不确定性，和过去并无多少不同。', `FemaleText_loc5`='未來充滿了死亡和不確定性，和過去並無多少不同。', `FemaleText_loc7`='Como en el pasado, el futuro encierra incertidumbre y muerte.' WHERE `ID`=75;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='불안과 공포에 사로잡힌 정령들이 내 귀에 속삭이고 있어.', `FemaleText_loc4`='幽魂在我耳边细语，他们显得如此地焦躁不安。', `FemaleText_loc5`='幽魂在我耳邊細語，他們顯得如此地焦躁不安。', `FemaleText_loc7`='Los espíritus me lo dicen al oído. Están inquietos y llenos de angustia.' WHERE `ID`=76;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘은 별이 아름답겠군!', `MaleText_loc4`='今晚的星星会很美！', `MaleText_loc5`='今晚的星星會很美!', `MaleText_loc7`='¡Las estrellas brillan como nunca esta noche!' WHERE `ID`=77;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밤하늘엔 마법보다 더 위대한 무언가가 작용하고 있어. 언젠가 내 기도를 들어 주겠지...', `MaleText_loc4`='仰望夜空，你能感觉到一些比魔法还要神奇的东西。总有一天它们会听我的声音……', `MaleText_loc5`='仰望夜空，你能感覺到一些比魔法還要神奇的東西。總有一天它們會聽我的聲音...', `MaleText_loc7`='El cielo nocturno alberga mágicos presagios. Algún día me escucharán...' WHERE `ID`=79;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여보시오, 방금 밀주를 좀 구했는데...', `MaleText_loc4`='安静一些……月光洒进来了……', `MaleText_loc5`='噓...我們才剛弄了批私酒進來...', `MaleText_loc7`='Psssst. Tenemos una botella de licor...' WHERE `ID`=80;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='올라와서 목이나 축이세요.', `MaleText_loc4`='向上方走，吹吹口哨。', `MaleText_loc5`='來點東西解解渴吧。', `MaleText_loc7`='Anímate y échate un trago.' WHERE `ID`=81;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 사악한 놈들 때문에 사업에 영향이 많으니 원...', `MaleText_loc4`='这股黑暗而邪恶的势力显然会碍我们的事。', `MaleText_loc5`='這種不詳的氣氛對生意影響實在很大呀。', `MaleText_loc7`='Esta oscura plaga no nos trae nada bueno.' WHERE `ID`=82;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진홍 까마귀 선술집에 오신 걸 환영합니다. 요즘은 실내에 있는 게 제일 안전하지요.', `MaleText_loc4`='欢迎来到血鸦旅店。这种时候，你最好一直呆在屋子里。', `MaleText_loc5`='歡迎來到血鴉旅店。在這種時候，你最好還是待在屋裡別亂跑。', `MaleText_loc7`='Te doy la bienvenida al Cuervo Escarlata. Hoy en día lo mejor es estar bajo techo.' WHERE `ID`=83;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 잔을 채웠으면 다시 한번 건배!', `MaleText_loc4`='再来满饮一杯！', `MaleText_loc5`='再來滿飲一杯!', `MaleText_loc7`='¡Si tu copa está llena, llenémosla de nuevo!' WHERE `ID`=84;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사자무리 여관에 오신 걸 환영합니다. 편안히 쉬십시오!', `MaleText_loc4`='欢迎来到狮王之傲旅店。您会在这里找到家的感觉！', `MaleText_loc5`='歡迎來到獅王之傲旅店。您會在這裡找到家的感覺!', `MaleText_loc7`='Bienvenidos a la posada Orgullo de León. ¡Poneos cómodos!' WHERE `ID`=85;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으, 할 일이 너무 너무 많아!! 시간이 언제 이렇게 흘렀지?', `MaleText_loc4`='事情太多，时间太少！', `MaleText_loc5`='事情太多，時間太少!', `MaleText_loc7`='¡Siempre corriendo, siempre corriendo! ¿Adónde vamos a parar?' WHERE `ID`=86;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디 보자, 내가 찾던 나이트 엘프의 의복에 대한 책이 어디 있었더라...', `MaleText_loc4`='我要找的关于暗夜精灵习俗的书在哪里……', `MaleText_loc5`='我要找的關於夜精靈習俗的書在哪裡...', `MaleText_loc7`='¿Dónde estará el libro sobre las costumbres de los elfos de la noche que estaba buscando...?' WHERE `ID`=87;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 이런! 이 책들 상태 좀 보게. 누가 책을 보고는 이렇게 뒤죽박죽으로 꽂아 놓은 거지??', `MaleText_loc4`='哦，我的天啊！看看这一堆书！是谁把这些书没归类就胡乱地放回书架上的？', `MaleText_loc5`='哦，我的天啊!看看這一堆書!是誰把這些書沒歸類就胡亂地放回書架上的?', `MaleText_loc7`='¡Oh, vaya! ¡Mira el estado de estos libros! ¿¿Quién los puso sin ordenar alfabéticamente??' WHERE `ID`=88;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠골의 시민들이여, 일어나 전투 준비를 하십시오! 혐오스러운 언데드가 곧 쳐들어올 것입니다!', `MaleText_loc4`='夜色镇的居民们，拿起你们的武器！一只亡灵憎恶正沿着大道走过来，妄图进犯我们的家园！', `MaleText_loc5`='夜色鎮的居民們，拿起你們的武器!一隻亡靈憎惡體正沿著大道走過來，妄圖進犯我們的家園!', `MaleText_loc7`='¡Despertad y coged las armas, ciudadanos de Villa Oscura! ¡Una abominación de los no-muertos se aproxima por el camino!' WHERE `ID`=89;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혐오스러운 언데드가 어둠의 순찰대 야영지를 덮쳤습니다! 놈이 마을에 도착하기 전에 어서 저지해야 합니다!', `MaleText_loc4`='那个憎恶已经毁灭了我们守夜人的营地！快点，我们必须在它到达城镇之前阻止它！', `MaleText_loc5`='那隻憎惡體已經毀滅了我們守夜人的營地!快點，我們必須在它到達城鎮之前阻止它!', `MaleText_loc7`='¡La abominación ha arrasado el campamento de La Guardia Nocturna! ¡Rápido, debemos interceptarla antes de que llegue a la ciudad!' WHERE `ID`=90;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='병력이 부족합니다! 모든 수비대는 마을 중앙에 집결해 주십시오. 모두 다 함께 언데드에 맞서 싸웁시다!', `MaleText_loc4`='快一点！勇敢的卫士们，快到镇中心集合！我们要并肩击退亡灵！', `MaleText_loc5`='快一點!勇敢的防衛者們，快到鎮中心集合!我們要並肩擊退亡靈怪物!', `MaleText_loc7`='¡No es suficiente! Reuníos en el centro de la ciudad. ¡Juntos combatiremos al monstruo no-muerto!' WHERE `ID`=91;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈이 왔습니다! 전원 전투 태세를 갖추십시오!', `MaleText_loc4`='憎恶来了！冲啊！', `MaleText_loc5`='憎惡怪來了!衝啊!', `MaleText_loc7`='¡La abominación ha llegado! ¡Adelante!' WHERE `ID`=92;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='괴물이 죽었습니다! 이제 어둠골은 안전합니다!', `MaleText_loc4`='憎恶被杀死了！夜色镇安全了！', `MaleText_loc5`='憎惡怪被殺死了!夜色鎮安全了!', `MaleText_loc7`='¡Han matado a la bestia! ¡Todo va bien en Villa Oscura!' WHERE `ID`=93;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그가 결혼을 할 거라는 걸 몰랐소! 그가 여자를 만나고 있다는 사실조차 모르고 있었는데... 정말 끔찍하군! 그 친구가 더는 야간 근무를 할 수 없다니!', `MaleText_loc4`='我不知道他已经结婚了！我甚至不知道他的年龄！这太可怕了！他再也不能在晚上工作了！', `MaleText_loc5`='我根本不知道他有要結婚!我甚至不知道他有在約會!這太可怕了!他再也不能上晚班了!', `MaleText_loc7`='¡No sabía que iba a casarse! ¡Ni siquiera sabía que salía con alguien! ¡Eso es terrible! ¡Ya no podrá trabajar por las noches!' WHERE `ID`=94;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋소! 당신들이 이겼소, 훌륭하신 기계공학 박사님들! 어디 원하는 데다 마음대로 문을 달아 보시라고!', `MaleText_loc4`='好的！你说服了我，你是机械方面的专家！随你在哪里安装这个门！', `MaleText_loc5`='好的!你說服了我，你是機械方面的專家!隨你在哪裡安裝這個門!', `MaleText_loc7`='¡De acuerdo! ¡Tenéis mejores argumentos que yo, maestros en Ingeniería! ¡Colocad la puerta donde queráis!' WHERE `ID`=95;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맞아, 우린 어리석어. 여우처럼 어리석다고나 할까!', `MaleText_loc4`='是的，我们很愚蠢。和狐狸一样愚蠢！', `MaleText_loc5`='是的，我們很愚蠢。和狐狸一樣愚蠢!', `MaleText_loc7`='Es verdad, somos idiotas. ¡Idiotas a más no poder!' WHERE `ID`=96;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 베이컨이 어디 갔지?', `MaleText_loc4`='我的熏肉在哪里？', `MaleText_loc5`='我的燻肉在哪裡?', `MaleText_loc7`='¿Dónde está mi beicon?' WHERE `ID`=97;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너흰 너희 땅을 망가뜨렸지. 내 땅은 망가뜨리지 못할 거야.', `FemaleText_loc4`='你们已经毁掉了自己的土地，别想再毁掉我的。', `FemaleText_loc5`='你已經毀掉了你自己的土地，別想再毀掉我的。', `FemaleText_loc7`='Has arruinado tus propias tierras, pero no vas a arruinar las mías.' WHERE `ID`=98;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n!', `MaleText_loc4`='$n!', `MaleText_loc5`='$n!', `MaleText_loc7`='¡$n!' WHERE `ID`=99;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구해 줘서 고맙습니다!', `MaleText_loc4`='谢谢你救了我！', `MaleText_loc5`='謝謝你救了我!', `MaleText_loc7`='¡Gracias por salvarme!' WHERE `ID`=100;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽어라!', `MaleText_loc4`='去死吧！', `MaleText_loc5`='去死吧!', `MaleText_loc7`='¡Y ahora muere!' WHERE `ID`=101;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='순찰을 돌 시간이군. 금방 돌아오겠습니다.', `MaleText_loc4`='轮到我巡逻了。我很快就会回来的。', `MaleText_loc5`='輪到我巡邏了。我很快就會回來的。', `MaleText_loc7`='Tengo que hacer la ronda. En breve estaré de vuelta.' WHERE `ID`=102;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 해안은 이상이 없고...', `MaleText_loc4`='现在海岸清晰可见……', `MaleText_loc5`='現在海岸已經肅清了...', `MaleText_loc7`='Ahora que la costa está despejada...' WHERE `ID`=103;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 누구냐?', `MaleText_loc4`='谁在那儿？', `MaleText_loc5`='誰在那裡?', `MaleText_loc7`='¿Quién anda ahí?' WHERE `ID`=104;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 오랫동안 떠나 있었으니... 이제 돌아가는 게 좋을 것 같군.', `MaleText_loc4`='我已经离开很久了……最好动身回去。', `MaleText_loc5`='我已經離開很久了...最好動身回去。', `MaleText_loc7`='He estado ausente durante mucho tiempo... es hora de que regrese.' WHERE `ID`=105;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='병사 토르센, 순찰을 마치고 돌아왔습니다. 새로운 보고 사항은 없으며 그쪽 지역은 상당히 조용합니다...', `MaleText_loc4`='列兵索尔森巡逻归来。没有新的情况要报告——今天特别地平静……', `MaleText_loc5`='士兵托爾森巡邏歸來。沒什麼新東西好報告的，今天特別地平靜...', `MaleText_loc7`='Soldado Thorsen regresando de la patrulla. Sin novedades... Todo está bastante tranquilo ahí fuera...' WHERE `ID`=106;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그 썩어가는 몸으로는 우릴 막지 못한다!', `FemaleText_loc4`='妄图阻止我们的家伙必将付出惨痛的代价！', `FemaleText_loc5`='光靠一具爛屍體是阻止不了我們的!', `FemaleText_loc7`='¡Un cadáver putrefacto no va a detenernos!' WHERE `ID`=107;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋아. 이제 교대하십시오, 병사. 휴식을 취하되 너무 나태해져서는 안 됩니다. 쿠르젠이 언제까지나 조용히 있지는 않을 테니까 말입니다.', `FemaleText_loc4`='很好，你脱险了。休息一下，但不要太放松。库尔森的人随时可能出现。', `FemaleText_loc5`='很好，那沒事了，士兵。去休息一下，但是也別太鬆懈。庫爾森的人隨時可能出現。', `FemaleText_loc7`='Muy bien. Cede el relevo, Soldado. Descansa, pero no te pongas demasiado cómodo. Kurzen no nos dejará tranquilos durante demasiado tiempo.' WHERE `ID`=108;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일이지? 그 가루는 건드리지 마!', `MaleText_loc4`='这里发生了什么事情？不要碰那些东西！', `MaleText_loc5`='發生什麼事情?不要亂碰東西!', `MaleText_loc7`='¿Qué está pasando aquí? ¡No toques esa pólvora!' WHERE `ID`=109;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에이버? 당신이에요...? 아, 너무 배가 고파요, 에이버! 배고파 죽겠다고요!!', `MaleText_loc4`='亚伯？是你吗？啊……我很饿，亚伯！我饿啊！！', `MaleText_loc5`='亞伯?是你嗎?啊...我好餓啊，亞伯!我餓啊!!', `MaleText_loc7`='¿Aber? ¿Eres tú...? Oh... ¡qué hambre tengo, Aber! ¡¡TENGO MUCHA HAMBRE!!' WHERE `ID`=110;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐... 넌 우리 남편이 아니군. 하지만 분명 그가 보낸 걸 거야. 그리고...넌... 아주 맛있어 보이는군, 크아아!', `MaleText_loc4`='等等……你不是我的丈夫。但肯定是他派你来的。你看起来……很可口！', `MaleText_loc5`='等等...你不是我的丈夫。但肯定是他派你來的。你看起來很...好吃!', `MaleText_loc7`='Un momento... tú no eres mi marido. Pero seguro que te ha enviado. Y tú... ¡estás para comerte!' WHERE `ID`=111;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디 보자, 이번에는 명중할까?', `MaleText_loc4`='让我们看看这次我是否能正中靶心！', `MaleText_loc5`='讓我們看看這次我是否能正中靶心!', `MaleText_loc7`='Veamos si esta vez puedo dar en esa diana.' WHERE `ID`=112;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 더 연습해야겠군!', `MaleText_loc4`='看来我还需要更多的练习！', `MaleText_loc5`='看來我還需要更多的練習!', `MaleText_loc7`='¡Por lo visto necesito más práctica!' WHERE `ID`=113;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한번 쓱 돌아볼 시간이구먼.', `MaleText_loc4`='给我多点时间进行练习。', `MaleText_loc5`='該換我去巡邏了。', `MaleText_loc7`='''Creo que voy a ir a por unas cuantas rondas.' WHERE `ID`=114;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 지금 술 마시느라 바빠서 말이야, 젊은이.', `MaleText_loc4`='嘿，伙计，我可没有时间喝酒。', `MaleText_loc5`='嘿，夥計，我可沒有時間喝酒。', `MaleText_loc7`='No tengo tiempo para tomar una copa, $gchaval:chica;.' WHERE `ID`=115;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아! 차가운 맥주 좀 달라고, 벨름!', `MaleText_loc4`='嘿，伙计，给我来杯酒！', `MaleText_loc5`='嘿，夥計，給我來杯冰冰涼涼的麥酒!', `MaleText_loc7`='¡Eh! ¡Tírame una bien helada, Belm!' WHERE `ID`=117;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 맛 좋다... 이제 다시 일할 시간이군! 벨름, 진심으로 고맙네.', `MaleText_loc4`='嘿！给我回去工作！多谢你，贝尔姆。', `MaleText_loc5`='啊!該回去工作了!多謝你，貝爾姆。', `MaleText_loc7`='¡Aaaaaah! ¡Es hora de volver al trabajo! Muchas gracias, Belm.' WHERE `ID`=118;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 여기 당신이 제일 좋아하는 맥주요, 친구.', `MaleText_loc4`='嘿，伙计，你的酒。', `MaleText_loc5`='嘿，夥計，你的酒。', `MaleText_loc7`='Aquí tienes, chico, tu brebaje favorito.' WHERE `ID`=120;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 자네 친구 통구스에게 외상값을 갚지 않으면 내가 스틸헤드와 함께 찾아가겠다고 전하라고!', `MaleText_loc4`='告诉你的朋友，如果他不把他的债处理掉，我就和老钢手一起去找他麻烦！', `MaleText_loc5`='告訴你的朋友多格斯，如果他再不來付清他欠的酒債，我就和老鋼手一起去找他麻煩!', `MaleText_loc7`='Muy bien, dile a tu amigo Tongus que si no se encarga de su cuenta, ¡iré a verle con el viejo Cabeza de Acero!' WHERE `ID`=121;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벨름이 외상값을 갚지 않으면 자네 얼굴을 갈겨 버리겠다더군.', `MaleText_loc4`='贝尔姆叫你赶快付账，否则他就会揍扁你。', `MaleText_loc5`='貝爾姆叫你趕快付帳，否則他就會揍扁你。', `MaleText_loc7`='Belm dice que pagues tu cuenta o te romperá la cara.' WHERE `ID`=122;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이호! 늙고 약한 녀석들이야 얼마든지 상대해 주지!', `MaleText_loc4`='好啊！让那老家伙试试看啊！', `MaleText_loc5`='好啊!叫那老傢伙來試試看啊!', `MaleText_loc7`='¡Hala! ¡Deseo enfrentarme de ese viejo debilucho!' WHERE `ID`=123;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐든 당신이 요리해 주는 대로 먹지 뭐. 그리고 곁들일 술도 한 병 주시오!', `MaleText_loc4`='随便给我点什么吃的，外加一瓶酒！', `MaleText_loc5`='隨便給我點什麼吃的，外加一瓶酒!', `MaleText_loc7`='¡Me comeré cualquier cosa que estés cocinando! ¡Ah, y pon también una botella para que pase mejor!' WHERE `ID`=124;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 벨름! 나와 여기 내 친구 $n에게 썬더 에일 맥주 한 잔씩 주라고.', `MaleText_loc4`='贝尔姆，嘿！给我一杯雷酒，再给我的好朋友$n来一杯。', `MaleText_loc5`='貝爾姆，嘿!給我一杯雷霆麥芽酒，再給我的好朋友$n來一杯。', `MaleText_loc7`='¡Hola, Belm! Dame una jarra de Cerveza del Trueno y otra para mi $gbuen:buena; $gamigo:amiga; $n.' WHERE `ID`=125;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맥주통은 잘 지키고 있나...?', `MaleText_loc4`='看管酒桶的工作怎样了啊……？', `MaleText_loc5`='看管酒桶的工作怎樣了啊...?', `MaleText_loc7`='¿Qué tal se te da vigilar los barriles...?' WHERE `ID`=126;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 정말 최고군! 두어 잔 더 해야겠는데... 나 대신 이 맥주통들을 좀 봐 주겠어?', `MaleText_loc4`='啊，真妙！我想要再来两杯……你能帮我照看一下这些桶吗，$n？', `MaleText_loc5`='啊，真是痛快!我想要再多來兩杯...你能幫我看管一下這些酒桶嗎，$n?', `MaleText_loc7`='¡Ah, esta sí que dará en el blanco! Creo que iré a por unas cuantas más... ¿puedes echar un vistazo a estos barriles, $n?' WHERE `ID`=127;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠, 이제 다시 일하러 가야겠군. 역시 잠깐 쉬고 나니 좋구먼. 썬더 에일 맥주는 언제 마셔도 늘 맛있단 말이야!', `MaleText_loc4`='好吧，我要回去干活了。休息一下的感觉果然很不错，喝上一杯雷酒的感觉就更好了！', `MaleText_loc5`='好吧，我要回去幹活了。休息一下的感覺果然很不錯，尤其是喝上一杯雷霆麥芽酒啊!', `MaleText_loc7`='Bueno, debo volver a mi trabajo. Me ha venido de perlas este pequeño descanso... y ¡qué bien sienta beber un poco de Cerveza del Trueno!' WHERE `ID`=128;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 원래 있었던 곳으로 돌아왔군.', `MaleText_loc4`='我又回到原点了。', `MaleText_loc5`='我又回到原點了。', `MaleText_loc7`='Vuelvo al punto de partida.' WHERE `ID`=129;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 정도면 멀리 온 것 같군... 맥주통이 보이질 않는 걸 보니... 자, 독을 퍼뜨려 볼까!', `MaleText_loc4`='我现在离得太远了……所以我看不见桶。', `MaleText_loc5`='我現在離得夠遠了...所以我看不見桶子。下藥吧!', `MaleText_loc7`='Ya estoy lo suficientemente lejos... no puedo ver el barril. ¡Veneno fuera!' WHERE `ID`=130;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 안에 물고기가 있을까?', `MaleText_loc4`='想想这里会有鱼吗？', `MaleText_loc5`='覺得這裡會有魚嗎?', `MaleText_loc7`='¿Crees que aquí hay peces?', `FemaleText_loc1`='이 안에 물고기가 있을까?', `FemaleText_loc4`='想想这里会有鱼吗？', `FemaleText_loc5`='覺得這裡會有魚嗎?', `FemaleText_loc7`='¿Crees que aquí hay peces?' WHERE `ID`=131;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 지난주에 큰 물고기 하나 잡았는데, 눈이 세 개였어!', `MaleText_loc4`='我上个星期抓到一个大家伙，它居然有三只眼！', `MaleText_loc5`='我上個星期抓到一個大隻的，它居然有三隻眼!', `MaleText_loc7`='Yo pesqué uno enorme la semana pasada, ¡tenía tres ojos!', `FemaleText_loc1`='나 지난주에 큰 물고기 하나 잡았는데, 눈이 세 개였어!', `FemaleText_loc4`='我上个星期抓到一个大家伙，它居然有三只眼！', `FemaleText_loc5`='我上個星期抓到一個大隻的，它居然有三隻眼!', `FemaleText_loc7`='Yo pesqué uno enorme la semana pasada, ¡tenía tres ojos!' WHERE `ID`=132;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 아빠가 바다엔 배를 통째로 삼킬 만큼 큰 물고기가 있다고 하셨어.', `MaleText_loc4`='我爸爸说在大海里有一种很大很大的鱼，可以一口吞下一整条船。', `MaleText_loc5`='我爸爸說在大海裡有一種很大很大的魚，可以一口吞下一整條船。', `MaleText_loc7`='Mi papá dice que en el océano hay peces tan grandes que podrían engullir un barco entero.', `FemaleText_loc1`='우리 아빠가 바다엔 배를 통째로 삼킬 만큼 큰 물고기가 있다고 하셨어.', `FemaleText_loc4`='我爸爸说在大海里有一种很大很大的鱼，可以一口吞下一整条船。', `FemaleText_loc5`='我爸爸說在大海裡有一種很大很大的魚，可以一口吞下一整條船。', `FemaleText_loc7`='Mi papá dice que en el océano hay peces tan grandes que podrían engullir un barco entero.' WHERE `ID`=133;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 아빠가 너희 아빠보다 낚시 더 잘해!', `MaleText_loc4`='我爸爸能比你爸爸捕更多的鱼！', `MaleText_loc5`='我爸爸抓的魚比你爸爸抓的還多!', `MaleText_loc7`='¡Mi papá puede coger más peces que tu papá!', `FemaleText_loc1`='우리 아빠가 너희 아빠보다 낚시 더 잘해!', `FemaleText_loc4`='我爸爸能比你爸爸捕更多的鱼！', `FemaleText_loc5`='我爸爸抓的魚比你爸爸抓的還多!', `FemaleText_loc7`='¡Mi papá puede coger más peces que tu papá!' WHERE `ID`=134;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이것 봐! 내가 낚았어! 에이... 낡은 장화잖아. 어우, 냄새...', `MaleText_loc4`='快看！快看！我抓到鱼了！呃……这是谁的臭鞋？', `MaleText_loc5`='快看!快看!我抓到魚了!噢...這是誰的臭鞋?', `MaleText_loc7`='¡Mira! ¡Mira! ¡He pescado algo! Ufff, solo es una bota apestosa.', `FemaleText_loc1`='이것 봐! 내가 낚았어! 에이... 낡은 장화잖아. 어우, 냄새...', `FemaleText_loc4`='快看！快看！我抓到鱼了！呃……这是谁的臭鞋？', `FemaleText_loc5`='快看!快看!我抓到魚了!噢...這是誰的臭鞋?', `FemaleText_loc7`='¡Mira! ¡Mira! ¡He pescado algo! Ufff, solo es una bota apestosa.' WHERE `ID`=135;
