UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거짓말!', `MaleText_loc4`='骗子！', `MaleText_loc5`='騙子!', `MaleText_loc7`='¡Mentira!', `FemaleText_loc1`='거짓말!', `FemaleText_loc4`='骗子！', `FemaleText_loc5`='騙子!', `FemaleText_loc7`='¡Mentira!' WHERE `ID`=138;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='땅 위를 걸어다니면서 사냥하고 사람도 잡아먹는, 이렇게 큰 물고기가 있다고 들었어.', `MaleText_loc4`='我听说有种巨大的鱼会上岸吃人！', `MaleText_loc5`='我聽說有種巨大的魚會上岸吃人!', `MaleText_loc7`='¡Me han dicho que hay unos peces enormes que andan en tierra y cazan a la gente para comérsela!', `FemaleText_loc1`='땅 위를 걸어다니면서 사냥하고 사람도 잡아먹는, 이렇게 큰 물고기가 있다고 들었어.', `FemaleText_loc4`='我听说有种巨大的鱼会上岸吃人！', `FemaleText_loc5`='我聽說有種巨大的魚會上岸吃人!', `FemaleText_loc7`='¡Me han dicho que hay unos peces enormes que andan en tierra y cazan a la gente para comérsela!' WHERE `ID`=139;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한번은 야영지에서 나보다 더 큰 물고기를 잡았어!!', `MaleText_loc4`='有一次，在野营的时候，我抓住了一条比我还大的鱼！', `MaleText_loc5`='有一次，在野營的時候，我抓住了一條比我還大的魚!', `MaleText_loc7`='¡¡Y una vez, en el campamento, pesqué un pez que era más grande que yo!!', `FemaleText_loc1`='한번은 야영지에서 나보다 더 큰 물고기를 잡았어!!', `FemaleText_loc4`='有一次，在野营的时候，我抓住了一条比我还大的鱼！', `FemaleText_loc5`='有一次，在野營的時候，我抓住了一條比我還大的魚!', `FemaleText_loc7`='¡¡Y una vez, en el campamento, pesqué un pez que era más grande que yo!!' WHERE `ID`=140;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 이 금빛 물고기에 대한 얘기를 들은 적이 있어. 이걸 잡으면 세 가지 소원을 들어 준대!', `MaleText_loc4`='我听说如果你抓住一条金鱼，那么你就会得到三个许愿的机会！', `MaleText_loc5`='我聽說如果你釣到一條黃金魚，那麼你就會得到三個許願的機會!', `MaleText_loc7`='He oído una historia sobre este pez dorado, ¡y si lo pescaras te concedería tres deseos!', `FemaleText_loc1`='나 이 금빛 물고기에 대한 얘기를 들은 적이 있어. 이걸 잡으면 세 가지 소원을 들어 준대!', `FemaleText_loc4`='我听说如果你抓住一条金鱼，那么你就会得到三个许愿的机会！', `FemaleText_loc5`='我聽說如果你釣到一條黃金魚，那麼你就會得到三個許願的機會!', `FemaleText_loc7`='He oído una historia sobre este pez dorado, ¡y si lo pescaras te concedería tres deseos!' WHERE `ID`=141;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 떠드는 것만큼 낚시도 잘한다면 바다에 물고기가 하나도 안 남아 있을 거다, 뭐.', `MaleText_loc4`='如果你的钓鱼技术真的像你说的那么好，那么整个海里的鱼早就被你全钓光了。', `MaleText_loc5`='如果你釣魚的技術真的像你說的那麼厲害，整個海裡的魚早就被你全釣光了。', `MaleText_loc7`='Si pescaras tan bien como hablas, no quedaría un solo pez en el océano.', `FemaleText_loc1`='네가 떠드는 것만큼 낚시도 잘한다면 바다에 물고기가 하나도 안 남아 있을 거다, 뭐.', `FemaleText_loc4`='如果你的钓鱼技术真的像你说的那么好，那么整个海里的鱼早就被你全钓光了。', `FemaleText_loc5`='如果你釣魚的技術真的像你說的那麼厲害，整個海裡的魚早就被你全釣光了。', `FemaleText_loc7`='Si pescaras tan bien como hablas, no quedaría un solo pez en el océano.' WHERE `ID`=142;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쉿! 네가 물고기를 다 쫓아 버리고 있잖아.', `MaleText_loc4`='嘘！别把鱼给吓跑了。', `MaleText_loc5`='噓!別把魚給嚇跑了。', `MaleText_loc7`='¡Shhh! Estás ahuyentando a los peces.', `FemaleText_loc1`='쉿! 네가 물고기를 다 쫓아 버리고 있잖아.', `FemaleText_loc4`='嘘！别把鱼给吓跑了。', `FemaleText_loc5`='噓!別把魚給嚇跑了。', `FemaleText_loc7`='¡Shhh! Estás ahuyentando a los peces.' WHERE `ID`=143;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꾸며 낸 얘기야.', `MaleText_loc4`='你要把它拉起来。', `MaleText_loc5`='你在吹牛。', `MaleText_loc7`='Te lo estás inventando.', `FemaleText_loc1`='꾸며 낸 얘기야.', `FemaleText_loc4`='你要把它拉起来。', `FemaleText_loc5`='你在吹牛。', `FemaleText_loc7`='Te lo estás inventando.' WHERE `ID`=144;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 입만큼 큰 물고기를 잡을 수 있다면 다시는 배고플 일 없을걸...', `MaleText_loc4`='如果你的钓鱼水平有你说的那么好，那我们就不会在这里饿肚子了。', `MaleText_loc5`='如果你的釣魚水準有你說的那麼好，那我們就不會在這裡餓肚子了。', `MaleText_loc7`='Si pudieras pescar un pez que quepa en tu boca, ya no volveríamos a tener hambre.', `FemaleText_loc1`='네 입만큼 큰 물고기를 잡을 수 있다면 다시는 배고플 일 없을걸...', `FemaleText_loc4`='如果你的钓鱼水平有你说的那么好，那我们就不会在这里饿肚子了。', `FemaleText_loc5`='如果你的釣魚水準有你說的那麼好，那我們就不會在這裡餓肚子了。', `FemaleText_loc7`='Si pudieras pescar un pez que quepa en tu boca, ya no volveríamos a tener hambre.' WHERE `ID`=145;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다리로 가서 낚시하는 게 좋겠는데.', `MaleText_loc4`='也许我们应该到桥那边去钓鱼。', `MaleText_loc5`='也許我們應該到橋那邊去釣魚。', `MaleText_loc7`='Tal vez deberíamos ir al puente a pescar.', `FemaleText_loc1`='다리로 가서 낚시하는 게 좋겠는데.', `FemaleText_loc4`='也许我们应该到桥那边去钓鱼。', `FemaleText_loc5`='也許我們應該到橋那邊去釣魚。', `FemaleText_loc7`='Tal vez deberíamos ir al puente a pescar.' WHERE `ID`=146;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말?', `MaleText_loc4`='真的？', `MaleText_loc5`='真的?', `MaleText_loc7`='¿En serio?', `FemaleText_loc1`='정말?', `FemaleText_loc4`='真的？', `FemaleText_loc5`='真的?', `FemaleText_loc7`='¿En serio?' WHERE `ID`=147;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 로서 님은 그렇게 맨손으로 36명의 오크 아저씨들을 처치했어!', `MaleText_loc4`='洛萨就那样空手杀死了三十六个兽人！', `MaleText_loc5`='洛薩就那樣空手殺死了三十六個獸人!', `MaleText_loc7`='¡Y así es como Lothar mató a treinta y seis orcos con sus propias manos!', `FemaleText_loc1`='그리고 로서 님은 그렇게 맨손으로 36명의 오크 아저씨들을 처치했어!', `FemaleText_loc4`='洛萨就那样空手杀死了三十六个兽人！', `FemaleText_loc5`='洛薩就那樣空手殺死了三十六個獸人!', `FemaleText_loc7`='¡Y así es como Lothar mató a treinta y seis orcos con sus propias manos!' WHERE `ID`=149;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래서 기사들은 천 명의 사나운 호드 오크 아저씨들이 계곡으로 쳐들어오는데도 자리를 사수하고 공격에 맞서 싸웠어.', `MaleText_loc4`='当数以千计的狂暴兽人涌入山谷的时候，骑士们紧握手中的武器，巍然面对部落的冲锋。', `MaleText_loc5`='當數以千計的狂暴獸人湧入山谷的時候，騎士們緊握手中的武器，巍然面對衝殺而至的部落。', `MaleText_loc7`='Y así, los caballeros se levantaron ante la Horda y mantuvieron su posición, mientras miles de orcos frenéticos atravesaban el valle.', `FemaleText_loc1`='그래서 기사들은 천 명의 사나운 호드 오크 아저씨들이 계곡으로 쳐들어오는데도 자리를 사수하고 공격에 맞서 싸웠어.', `FemaleText_loc4`='当数以千计的狂暴兽人涌入山谷的时候，骑士们紧握手中的武器，巍然面对部落的冲锋。', `FemaleText_loc5`='當數以千計的狂暴獸人湧入山谷的時候，騎士們緊握手中的武器，巍然面對衝殺而至的部落。', `FemaleText_loc7`='Y así, los caballeros se levantaron ante la Horda y mantuvieron su posición, mientras miles de orcos frenéticos atravesaban el valle.' WHERE `ID`=150;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그는 때때로 까마귀로 변신할 수도 있다고 하더라.', `MaleText_loc4`='他们说他有时会变成乌鸦。', `MaleText_loc5`='他們說他有時會變成烏鴉。', `MaleText_loc7`='Dicen que él a veces puede convertirse en un cuervo.', `FemaleText_loc1`='그는 때때로 까마귀로 변신할 수도 있다고 하더라.', `FemaleText_loc4`='他们说他有时会变成乌鸦。', `FemaleText_loc5`='他們說他有時會變成烏鴉。', `FemaleText_loc7`='Dicen que él a veces puede convertirse en un cuervo.' WHERE `ID`=151;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오크의 눈이 왜 빨갛게 빛나는지 알아? 피를 마시기 때문이야.', `MaleText_loc4`='你知道为什么兽人的眼睛闪着红光？因为他们喝的是血！', `MaleText_loc5`='你知道為什麼獸人的眼睛閃著紅光?因為他們喝的是血!', `MaleText_loc7`='¿Sabes por qué los orcos tienen ojos de color rojo brillante? ¡Porque beben sangre!', `FemaleText_loc1`='오크의 눈이 왜 빨갛게 빛나는지 알아? 피를 마시기 때문이야.', `FemaleText_loc4`='你知道为什么兽人的眼睛闪着红光？因为他们喝的是血！', `FemaleText_loc5`='你知道為什麼獸人的眼睛閃著紅光?因為他們喝的是血!', `FemaleText_loc7`='¿Sabes por qué los orcos tienen ojos de color rojo brillante? ¡Porque beben sangre!' WHERE `ID`=152;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='숟가락이 없네.', `MaleText_loc4`='勺子并不存在。', `MaleText_loc5`='湯匙並不存在。', `MaleText_loc7`='No hay cucharas.', `FemaleText_loc1`='숟가락이 없네.', `FemaleText_loc4`='勺子并不存在。', `FemaleText_loc5`='湯匙並不存在。', `FemaleText_loc7`='No hay cucharas.' WHERE `ID`=153;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말이야. 실제로 사람들이 본 적 있데. 판다렌은 정말 있다고!', `MaleText_loc4`='我发誓，真的有人看到过他们。熊猫人是确实存在的！', `MaleText_loc5`='我發誓，真的有人看到過他們。熊貓人是確實存在的!', `MaleText_loc7`='Lo juro, algunos los han visto de verdad. ¡Los pandarines existen realmente!', `FemaleText_loc1`='정말이야. 실제로 사람들이 본 적 있데. 판다렌은 정말 있다고!', `FemaleText_loc4`='我发誓，真的有人看到过他们。熊猫人是确实存在的！', `FemaleText_loc5`='我發誓，真的有人看到過他們。熊貓人是確實存在的!', `FemaleText_loc7`='Lo juro, algunos los han visto de verdad. ¡Los pandarines existen realmente!' WHERE `ID`=154;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러고는 토끼가 그의 손가락을 물어뜯어 버렸어... 정말이라니까.', `MaleText_loc4`='然后那兔子就一下子咬掉了他的头……事情就是这样，我发誓。', `MaleText_loc5`='然後那兔子就一下子咬掉了他的頭...事情就是這樣，我發誓。', `MaleText_loc7`='Y luego el conejo le arrancó la cabeza de un mordisco... Lo juro.', `FemaleText_loc1`='그러고는 토끼가 그의 손가락을 물어뜯어 버렸어... 정말이라니까.', `FemaleText_loc4`='然后那兔子就一下子咬掉了他的头……事情就是这样，我发誓。', `FemaleText_loc5`='然後那兔子就一下子咬掉了他的頭...事情就是這樣，我發誓。', `FemaleText_loc7`='Y luego el conejo le arrancó la cabeza de un mordisco... Lo juro.' WHERE `ID`=155;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='운하에 악어가 있다는 거 알지? 누군가 애완동물로 삼으려고 늪에서 데려왔다가 버린 거래.', `MaleText_loc4`='我跟你说啊，运河里有鳄鱼。它们原本是沼泽地带的动物，但是被人当作宠物带了回来，然后又被抛弃在运河里了。', `MaleText_loc5`='你知道運河裡有鱷魚。牠們被人從沼澤抓回來當寵物，然後又被拋棄在運河裡。', `MaleText_loc7`='Sabes que hay crocoliscos en los Canales. Se trajeron del pantano para usarlos como mascotas, pero terminaron en los Canales.', `FemaleText_loc1`='운하에 악어가 있다는 거 알지? 누군가 애완동물로 삼으려고 늪에서 데려왔다가 버린 거래.', `FemaleText_loc4`='我跟你说啊，运河里有鳄鱼。它们原本是沼泽地带的动物，但是被人当作宠物带了回来，然后又被抛弃在运河里了。', `FemaleText_loc5`='你知道運河裡有鱷魚。牠們被人從沼澤抓回來當寵物，然後又被拋棄在運河裡。', `FemaleText_loc7`='Sabes que hay crocoliscos en los Canales. Se trajeron del pantano para usarlos como mascotas, pero terminaron en los Canales.' WHERE `ID`=156;
