UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 운하에는 물고기가 한 마리도 없는 것 같아.', `MaleText_loc4`='我想运河里是不会有鱼的。', `MaleText_loc5`='我想運河裡是不會有魚的。', `MaleText_loc7`='No creo que haya peces en estos canales.', `FemaleText_loc1`='이 운하에는 물고기가 한 마리도 없는 것 같아.', `FemaleText_loc4`='我想运河里是不会有鱼的。', `FemaleText_loc5`='我想運河裡是不會有魚的。', `FemaleText_loc7`='No creo que haya peces en estos canales.' WHERE `ID`=177;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벌레를 낚싯바늘에 끼우고, 낚싯바늘을 물에 담그면... 물속의 물고기는 우리 물고기.', `MaleText_loc4`='把蚯蚓放在鱼钩上，把鱼钩放到水里，这样我们就能钓到水里的鱼了。', `MaleText_loc5`='把蚯蚓放在魚鉤上，把魚鉤放到水裡，這樣我們就能釣到水裡的魚了。', `MaleText_loc7`='El gusano va en el anzuelo, el anzuelo va al agua. El pez está en el agua, nuestro pez.', `FemaleText_loc1`='벌레를 낚싯바늘에 끼우고, 낚싯바늘을 물에 담그면... 물속의 물고기는 우리 물고기.', `FemaleText_loc4`='把蚯蚓放在鱼钩上，把鱼钩放到水里，这样我们就能钓到水里的鱼了。', `FemaleText_loc5`='把蚯蚓放在魚鉤上，把魚鉤放到水裡，這樣我們就能釣到水裡的魚了。', `FemaleText_loc7`='El gusano va en el anzuelo, el anzuelo va al agua. El pez está en el agua, nuestro pez.' WHERE `ID`=178;
