UPDATE `locales_broadcast_text` SET `MaleText_loc1`='먹을 것 좀 사주시면 화요일에 꼭 갚겠습니다요.', `MaleText_loc4`='今天我会给你一个汉堡作为星期二那天的报酬。', `MaleText_loc5`='今天的漢堡我會很樂意在星期二那天付錢給你。', `MaleText_loc7`='Te prometo que el martes te pago lo que me des hoy para una hamburguesa.' WHERE `ID`=182;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 불쌍한 놈을 좀 도와주십쇼.', `MaleText_loc4`='帮帮我这个穷人吧？', `MaleText_loc5`='幫幫我這個窮人吧?', `MaleText_loc7`='Una ayuda para este pobre hombre...' WHERE `ID`=183;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앞 못 보는 이 불쌍한 자에게 동전 몇 닢만 적선해 줍쇼... 제가 눈이 멀지 않았다고요? 전 눈이 멀지 않았어요! 앞을 볼 수 있다고요!! 오, 기적이야!', `MaleText_loc4`='给我这个可怜的瞎子一点零钱吧？……你说我不是瞎子？……我真的不瞎了！我能看见了！！这真是一个奇迹！', `MaleText_loc5`='給我這個可憐的瞎子一點零錢吧?...你說我不是瞎子是什麼意思?...我真的不瞎了!我看得見了!!這真是奇蹟!', `MaleText_loc7`='¿Te sobra algo de morralla para un pobre ciego?... ¿Qué quieres decir con que no soy ciego?... ¡YA NO SOY CIEGO! ¡¡PUEDO VER!! ¡Es un milagro!' WHERE `ID`=184;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동전 한 닢에 갑옷을 닦아 드립죠.', `MaleText_loc4`='擦一件装甲只收一个铜板咯！', `MaleText_loc5`='擦亮一件裝甲只收一個銅板!', `MaleText_loc7`='Lustro tu armadura por un penique.' WHERE `ID`=185;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 모두 바보 같은 얼라이언스 군대 때문입죠. 내 농장 바로 뒤에 경비탑을 지어 버리다니...', `MaleText_loc4`='这都是他们的错，愚蠢的联盟军队。居然在我的农场背后修建他们的哨塔。', `MaleText_loc5`='這都是他們的錯，愚蠢的聯盟軍隊。非得把他們的哨塔蓋在我的農場後面。', `MaleText_loc7`='Todo es culpa del maldito ejército de la Alianza... Tenían que construir sus torres justo detrás de mi granja.' WHERE `ID`=186;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 모두 바보 같은 오크족 때문입죠. 내 농장을 모두 불태워 버리다니...', `MaleText_loc4`='这都是他们的错，愚蠢的兽人。居然放火烧我的农场。', `MaleText_loc5`='這都是他們的錯，愚蠢的獸人。居然放火燒我的農場。', `MaleText_loc7`='Todo es culpa de los estúpidos orcos. Tenían que quemar mi granja hasta los cimientos.' WHERE `ID`=187;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 소리가 들리오? 놈들이 점점 가까워지고 있는 것 같소...', `MaleText_loc4`='你听见了吗？我想他们正在靠近……', `MaleText_loc5`='你聽見了嗎?我想他們越來越近了...', `MaleText_loc7`='¿Has oído eso? Creo que se están acercando...' WHERE `ID`=188;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으... 난 경비 임무가 정말 싫어.', `MaleText_loc4`='又是警戒任务，我讨厌警戒任务。', `MaleText_loc5`='又是警戒任務，我討厭警戒任務。', `MaleText_loc7`='Servicio de guardia, odio el servicio de guardia.' WHERE `ID`=189;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그곳의 코볼트는 모두 죽었다고 들었소.', `MaleText_loc4`='有很多狗头人都去过那里……他们都死了。', `MaleText_loc5`='我聽說在那邊的狗頭人全部都死光了。', `MaleText_loc7`='He oído que todos los kóbolds que estaban ahí abajo están muertos.' WHERE `ID`=190;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미안하네, 훌다르... 내가 잘못된 길로 든 것 같군.', `MaleText_loc4`='对不起，胡达尔……但是似乎我骗了你。', `MaleText_loc5`='對不起，胡達爾...看來是我害了你。', `MaleText_loc7`='Lo siento, Huldar... Pero creo que te he confundido.' WHERE `ID`=192;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은무쇠 드워프의 짓이야. 뱃짐 중 일부를 약탈하기도 했었지.', `MaleText_loc4`='黑铁矮人的活动越发频繁，甚至已经开始掠夺我们的货物——', `MaleText_loc5`='黑鐵矮人的活動越發頻繁，甚至已經開始搶劫我們的貨物─', `MaleText_loc7`='Hay actividad entre los Hierro Negro. A pesar de que algunos cargamentos han sido robados...' WHERE `ID`=194;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일꾼 중 몇몇이 성실하지 않거나 부주의한 탓일 걸세.', `MaleText_loc4`='我相信这只是一些工人的疏忽。', `MaleText_loc5`='我相信這只是一些工人的疏忽。', `MaleText_loc7`='Seguro que ha sido simple descuido o incompetencia por parte de algunos de los trabajadores.' WHERE `ID`=195;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시민의 수호자 $n|1을;를; 향하여 모두 경례!', `MaleText_loc4`='为$n欢呼吧！人民的守护者！', `MaleText_loc5`='為$n歡呼吧!人民的防衛者!', `MaleText_loc7`='¡Salve, $n! ¡$gDefensor:Defensora; del Pueblo!' WHERE `ID`=197;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서부 몰락지대 주민들의 인사를 전하네, $n. 귀관은 용감하고 훌륭한 자유의 수호자일세.', `MaleText_loc4`='西部荒野的人民向勇敢的$n致敬！', `MaleText_loc5`='西部荒野的人民向$n致敬，英勇的自由鬥士!', `MaleText_loc7`='El Pueblo de los Páramos de Poniente saluda a $n, $gsoberbio:soberbia; y valiente $gdefensor:defensora; de la libertad.' WHERE `ID`=198;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='귀관에게 존경과 경의를 표하네, $n! 우린 이 땅을 반드시 되찾을 것이네!', `MaleText_loc4`='让我们为$n祝酒三杯！这块土地又回到我们手里了！', `MaleText_loc5`='讓我們為$n喝采三遍!這塊土地必定會重回我們手裡!', `MaleText_loc7`='¡Tres hurras para $n! ¡Esta tierra volverá a ser nuestra!' WHERE `ID`=199;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='술을 가져다 주어서 고맙네. 지금 바로 한 병 따서 맛 봐야겠구먼.', `MaleText_loc4`='谢谢你的这箱酒，$n。我现在就想打开一瓶尝尝！', `MaleText_loc5`='謝謝你的這箱酒，$n。我現在就想打開一瓶嘗嘗!', `MaleText_loc7`='Gracias por el barril de licor, $n. ¡Creo que abriré una botella ahora mismo!' WHERE `ID`=200;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='근본 요소의 흐름을 역전시킬 수 있다면 극성을 바꿀 수 있을 거예요.', `FemaleText_loc4`='如果我们改变魔法精华的流向，也许我们就可以改变其极性。', `FemaleText_loc5`='如果我們改變魔法精華的流向，也許我們就可以改變其極性。', `FemaleText_loc7`='Si invertimos los fluidos de la Esencia, tal vez podamos cambiar la polaridad.' WHERE `ID`=201;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그러면 일련의 마법이 양의 극성을 가진 에너지로 연쇄 반응을 일으키게 될 거예요.', `FemaleText_loc4`='然后，预设的魔法序列将产生链式反应，并最终使能量开始从正极输入。', `FemaleText_loc5`='然後，預設的魔法序列將產生連鎖反應，最終使能量開始從正極輸入。', `FemaleText_loc7`='Entonces, una cascada de hechizos provocaría una reacción en cadena de energías con carga positiva.' WHERE `ID`=203;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='차원문이 조금 움직일 테니 그때 봉인 주문을 사용하면 문을 제자리에 고정할 수 있죠.', `FemaleText_loc4`='传送门将会产生轻微的变化，此时如果你施展一个固化咒语，那么你就可以把它的变化固定下来。', `FemaleText_loc5`='傳送門將會產生輕微的偏移，但此時只要你施展一個固化咒語，那麼你就可以把它的變化固定下來。', `FemaleText_loc7`='El portal se desplazará ligeramente y si ahora le lanzas un hechizo, este se solidificará y no se moverá.' WHERE `ID`=204;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='양의 극성을 가진 에너지가 음의 극성을 가진 에너지와 충돌하더라도 서로 극성이 상쇄되지는 않아요.', `FemaleText_loc4`='当正极能量与负极能量相碰的时候，它们互不相容。', `FemaleText_loc5`='當正極能量與負極能量相碰的時候，它們並不會彼此抵銷。', `FemaleText_loc7`='Cuando las energías con carga positiva choquen contra las energías con carga negativa, no se anularán unas a otras.' WHERE `ID`=205;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='매기노르의 이론에 의하면 양의 에너지 교류 흐름을 왜곡시키면 실제로 보다 안정된 흐름을 얻을 수 있다고 해요.', `FemaleText_loc4`='玛吉诺曾指出，改变正极能量的流量会使其更加稳定。', `FemaleText_loc5`='瑪姬諾曾指出，改變正極能量的流量會使其更加穩定。', `FemaleText_loc7`='Maginor dice que una serie de flujos ondulatorios alternativos de energía positiva en realidad generan un flujo mucho más estable.' WHERE `ID`=206;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그러면 충분한 에너지가 유입되어 주문이 속박 대상을 유지할 만큼 충분하게 되죠.', `FemaleText_loc4`='该点的魔法屏障应该得到足够的能量支持，这样才能保持其稳定性。', `FemaleText_loc5`='該點的魔法屏障應該得到足夠的能量支援，這樣才能保持其穩定性。', `FemaleText_loc7`='En ese punto, el flujo de energía debería reforzar las salas mágicas para que alberguen la entidad.' WHERE `ID`=207;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='배열을 변경해서 유입되는 흐름의 변동을 보완할 수 있지 않을까요?', `FemaleText_loc4`='为什么我们不能通过改变魔法阵列的方法去补偿流量的变化呢？', `FemaleText_loc5`='為什麼我們不能通過改變魔法陣列的方法去補償流量的變化呢?', `FemaleText_loc7`='¿Por qué no podemos simplemente desplazar la matriz para compensar la desviación en el flujo?' WHERE `ID`=208;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='12개의 초점 중심을 만들면 마법의 힘이 보다 충만하게 되어 안정성을 충분히 확보할 수 있을 거예요.', `FemaleText_loc4`='加入十二个聚焦核心可以使魔法能量变得更加稳固。', `FemaleText_loc5`='加入十二個聚焦核心可以使魔法能量變得更加穩固。', `FemaleText_loc7`='Si añadimos doce centros focales, podrían formarse energías mágicas más sólidas, lo que se traduciría en una mayor estabilidad.' WHERE `ID`=209;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그러다 그에 따른 진동수 변경으로 흐름에 마법적인 영향을 미치면 어쩌죠?', `FemaleText_loc4`='但是如果频率转换的结果是将魔法流反馈回去，那会怎么样呢？', `FemaleText_loc5`='但是如果頻率轉換的結果是將魔法流回饋回去，那會怎麼樣呢?', `FemaleText_loc7`='Pero ¿qué ocurriría si el desplazamiento de frecuencia resultante enviase retroalimentación mágica a través de los fluidos?' WHERE `ID`=210;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그렇게 할 경우, 주문을 걸기 전에 제대로 고정하지 않으면 흐름의 구조가 해체되지 않을까요?', `FemaleText_loc4`='难道那不会使得法术程序在被激活之前就崩溃吗？', `FemaleText_loc5`='若是開始施術前沒有定好錨點，難道那不會使得能量網絡就此崩潰嗎?', `FemaleText_loc7`='¿Acaso eso no hizo que el tejido se deshiciera al no estar bien sujeto antes de lanzarlo?' WHERE `ID`=211;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하지만 흐름이 교차되지는 않을까요? 그러면 큰일 아닌가요?', `FemaleText_loc4`='你是说交叉魔法流？那就太糟糕了。', `FemaleText_loc5`='你是說交叉魔法流?那就太糟糕了。', `FemaleText_loc7`='Pero, en tal caso, ¿las corrientes no se cruzarían entre sí? ¿Acaso no sería catastrófico?' WHERE `ID`=212;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하지만 생성되는 힘이 소실될 수도 있고 몇 주 동안 두통을 일으킬 만한 힘의 유입을 유발할 수도 있어요.', `FemaleText_loc4`='那样能量流会崩溃，其魔法扰动的结果是让你在至少一周内都觉得浑身不舒服。', `FemaleText_loc5`='那樣能量流會崩潰，其魔法擾動的結果是會害你嚴重偏頭痛至少一個禮拜。', `FemaleText_loc7`='Las energías resultantes podrían neutralizarse, lo que generaría un flujo energético capaz de producirte un terrible dolor de cabeza durante semanas.' WHERE `ID`=213;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그것이 바로 실레리아 상급마법사님의 마법 공식에서 문제를 일으킨 주원인이 아니었나요?', `FemaleText_loc4`='那不就是让萨蕾莉亚的魔法方程出问题的原因么？', `FemaleText_loc5`='那不就是薩蕾莉亞的魔法方程式一開始出問題的原因嗎?', `FemaleText_loc7`='¿Pero no fue eso lo que causó los problemas iniciales con la fórmula mágica del Adepto Syleria?' WHERE `ID`=214;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아니라고 생각해요. 다시 폭발하는 일은 없을 거예요.', `FemaleText_loc4`='我不这么认为，我不想再被炸出实验室了。', `FemaleText_loc5`='我不這麼認為，我不想再被炸出實驗室了。', `FemaleText_loc7`='No lo creo, de hecho, no me apetece volver a saltar por los aires.' WHERE `ID`=215;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그건 마법 초점의 균형을 깨뜨려 공중에 역진동을 일으킬 거예요.', `FemaleText_loc4`='可是，那会使魔法聚焦失去平衡，并引起扭曲虚空中的异常波动。', `FemaleText_loc5`='可是，那會使魔法聚焦失去平衡，並引起扭曲虛空中的異常波動。', `FemaleText_loc7`='Sin embargo, esto generaría un desequilibrio en el centro mágico y causaría una vibración inversa en el éter.' WHERE `ID`=216;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='같이 주문을 시도할 사람 20명만 구하면 성공할 것 같군요.', `FemaleText_loc4`='我想如果有二十个人用魔法能量支持它，应该还是可以的。', `FemaleText_loc5`='應該行得通吧...只要有二十個人幫我們一起施法。', `FemaleText_loc7`='Supongo que funcionaría si tuviéramos a veinte personas para lanzarlo.' WHERE `ID`=217;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='타이리안 형태로 3개의 초점을 사용하는 게 어떨까요? 그러면 문제가 해결될 것 같은데...', `FemaleText_loc4`='如果我们在泰里安方程式中使用三个聚焦器会发生什么事呢？应该可以解决这个问题吧？', `FemaleText_loc5`='如果我們在泰里安方程式中使用三個聚焦器會發生什麼事呢?應該可以解決這個問題吧?', `FemaleText_loc7`='¿Qué pasaría si utilizásemos tres focos de acuerdo con el patrón tireano? Eso lo resolvería.' WHERE `ID`=218;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그렇지만 힘의 핵심을 정확하게 고정하면 성공할 것 같군요.', `FemaleText_loc4`='但是如果我们在恰当的能量点使用定位魔法来稳定它，那么它就可以正常运作了。', `FemaleText_loc5`='如果我們能在恰當的能量點使用定位魔法來穩定它，那麼它應該是行得通的。', `FemaleText_loc7`='Pero si lo estabilizamos con un hilo de ancla en el nudo energético apropiado, tendría que funcionar.' WHERE `ID`=219;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='항상 비관적이군요. 그럴 가능성은 전혀 없답니다.', `FemaleText_loc4`='别扯了，你那种方法成功的或然率小过零啊。', `FemaleText_loc5`='別扯了，你那種方法成功的或然率小過零啊。', `FemaleText_loc7`='Siempre tan negativo. Las probabilidades de que eso ocurra son nulas.' WHERE `ID`=220;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='올바른 과정을 따르면 괜찮을 거예요. 다만 시작하기 전에 신중하게 연구해 봐야겠어요.', `FemaleText_loc4`='如果我们按照正确的次序进行操作，那就应该不会有任何问题。所以我们在开始之前应该好好地研究一下。', `FemaleText_loc5`='如果我們按照正確的次序進行操作，那就應該不會有任何問題。所以我們在開始之前應該好好地研究一下。', `FemaleText_loc7`='Si usamos la secuencia adecuada, no debería de haber problemas. Estudiaremos seriamente el proceso antes de empezar.' WHERE `ID`=221;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='와! 이 모두 다 사랑의 물약을 위한 거로군요. 그가 그만한 가치가 있는 자라면 좋겠네요.', `FemaleText_loc4`='呵呵，所有的这一切都是为了一瓶爱情药水。希望他别辜负了那姑娘。', `FemaleText_loc5`='呵呵，所有的這一切都是為了一瓶愛情藥水。希望他別辜負了那姑娘。', `FemaleText_loc7`='Vaya, todo esto para una poción de amor. Espero que él lo valga.' WHERE `ID`=222;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='슈리안 이론을 사용하는 것은 좋지만 이세리안의 접근법을 사용해서는 안 돼요.', `FemaleText_loc4`='如果根据苏瑞亚的理论，那就是没错了，不过这样一来我们就必须采用伊瑟亚的魔法启动流程理论。', `FemaleText_loc5`='如果根據蘇瑞亞的理論，那就是沒錯了。但如果是用伊瑟亞的方法，那就難說了。', `FemaleText_loc7`='Si usamos la teoría suriana, sí, pero si aplicamos el enfoque y''seriano, entonces no.' WHERE `ID`=223;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='적어도 청소하기 위해 모일 필요는 없겠군요.', `FemaleText_loc4`='至少我们不用费神去打扫现场……', `FemaleText_loc5`='至少我們不用去收拾善後...', `FemaleText_loc7`='Al menos no estaríamos por aquí para tener que limpiarlo.' WHERE `ID`=224;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='올바른 초기화 절차를 따르지 않을 경우에만 그렇죠.', `FemaleText_loc4`='除非我们没有按照正确的初始步骤进行操作。', `FemaleText_loc5`='除非我們沒有按照正確的啟動步驟進行操作。', `FemaleText_loc7`='Solo ocurriría algo si no seguimos el procedimiento de inicialización adecuado.' WHERE `ID`=225;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 말이 맞는 것 같군.', `MaleText_loc4`='我想你是对的。', `MaleText_loc5`='你說的應該沒錯。', `MaleText_loc7`='Supongo que tienes razón.' WHERE `ID`=226;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자, 내 일상 용품 목록이에요, 켈드릭.', `FemaleText_loc4`='这是我的清单，凯德雷克。都是些常用的原料。', `FemaleText_loc5`='這是我的清單，凱德雷克。跟以前差不多。', `FemaleText_loc7`='Aquí tienes mi lista, Keldric. El material de siempre.' WHERE `ID`=227;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고마워요, 켈드릭. 다음에 봐요.', `FemaleText_loc4`='谢谢你，凯德雷克。再见。', `FemaleText_loc5`='謝謝你，凱德雷克。再見。', `FemaleText_loc7`='Gracias, Keldric. Hasta pronto.' WHERE `ID`=228;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지옥에나 떨어져라, $n! 언젠가 반드시 복수하고 말 테다!', `MaleText_loc4`='我要诅咒你，$n！总有一天我会复仇的。', `MaleText_loc5`='我要詛咒你，$n!總有一天我會復仇的。', `MaleText_loc7`='¡Te maldigo, $n! ¡Algún día, la venganza será mía!' WHERE `ID`=229;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 방금 텔사마에서 짐마차가 출발했다는 연락이 왔다. 행동을 개시할 때가 온 거야! 자, 가자!', `MaleText_loc4`='好了，我们刚得到消息，有一个商队已经从塞尔萨玛出发了。该行动了！出发！', `MaleText_loc5`='好了，我們剛得到消息，有一個商隊已經從塞爾薩瑪出發了。該行動了!出發!', `MaleText_loc7`='Vale, sabemos que una caravana parte desde Thelsamar. ¡Es hora de moverse! ¡Vamos, vamos, vamos!' WHERE `ID`=230;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발굴현장에 가까이 왔으니 조심해서 움직여야 한다. 수중 호흡 장치를 착용하도록.', `MaleText_loc4`='我们已经接近挖掘场了，注意小心行事。现在准备好你的水下呼吸装备……', `MaleText_loc5`='我們已經接近挖掘場了，注意小心行事。現在準備好你的水下呼吸裝備...', `MaleText_loc7`='De acuerdo, nos estamos acercando al lugar de la excavación, así que tenemos que proceder con cuidado. Usar el equipo de respiración subacuática...' WHERE `ID`=231;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐 스톤, 톤크렌트의 새로운 증기 엔진에 대해 들어봤나?', `MaleText_loc4`='嘿，伙计，你知道新的蒸汽坦克已经可以开出去了吗？', `MaleText_loc5`='嘿，夥計，你知道新的蒸汽坦克已經可以開出去了嗎?', `MaleText_loc7`='Eh, Roca, ¿has oído algo sobre el nuevo motor a vapor del viejo Tonkrend?' WHERE `ID`=232;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 그래. 그 쓰레기에 대한 얘기는 모두 들었지. 무게를 줄이려고 외장에서 보호재를 제거해 버리다니... 하! 말도 안 되지!', `MaleText_loc4`='嗯，我已经听到过关于那新东西的消息了。他们去掉了防弹装甲来减轻重量，简直是疯了！', `MaleText_loc5`='嗯，我已經聽到過關於那新東西的消息了。他們去掉了防彈裝甲來減輕重量，簡直是瘋了!', `MaleText_loc7`='Ah, sí. He oído todo acerca de esos nuevos cacharros. Les han quitado chapa de la carcasa para reducir su peso. ¡Bah! ¡Eso es un disparate!' WHERE `ID`=233;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='머릿속에는 경주 말고 다른 건 안 들어 있나? 자네 정도는 단숨에 쓰러뜨릴 수 있어!', `MaleText_loc4`='你除了打架还知道什么？我轻而易举就可以把你骗得团团转！', `MaleText_loc5`='你除了打架還知道什麼?我輕而易舉就可以把你騙得團團轉!', `MaleText_loc7`='¿Piensas alguna vez en algo que no sea luchar? ¡Podría detenerte en el trayecto!' WHERE `ID`=234;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흥! 이 트롤플로우의 사정거리에만 들어오는 순간, 자네는 산산조각날 줄 알라고!', `MaleText_loc4`='哈！只要你一进入我的射程，包你马上粉身碎骨！', `MaleText_loc5`='哈!只要你一進入我的射程，包你馬上粉身碎骨!', `MaleText_loc7`='¡Bah! ¡En cuanto te acerques a la vieja Potenciatrol, te reducirá a escombros!' WHERE `ID`=235;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 이봐, 날 이길 가망은 없어!', `MaleText_loc4`='啊哈！你没戏了！', `MaleText_loc5`='呃啊!你真是沒藥救了!', `MaleText_loc7`='¡Aagh! ¡Eres un inútil!' WHERE `ID`=236;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐 피즈, 내가 운하를 따라 내려가다가 날 벌목기로 무장하고 습격하려던 고블린들을 박살 내 버린 얘기를 안 해 줬던가?', `MaleText_loc4`='嘿，我说，我有没有跟你说过，那天当我骑马穿过运河的时候，有一些驾驶着伐木机的地精想要伏击我？', `MaleText_loc5`='嘿，我說，我有沒有跟你說過，那天我騎馬穿過運河的時候，有幾個駕駛伐木機的哥布林想要偷襲我?', `MaleText_loc7`='Oye, Fizzer, ¿te he hablado de la vez que atravesaba los canales cuando unos goblins con trajes cortados en tiras intentaron tenderme una emboscada?' WHERE `ID`=237;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 그 얘긴 벌써 백 번도 넘게 들었을 거야!', `MaleText_loc4`='嗯，让我看看。我敢打赌，足有一百次了！', `MaleText_loc5`='嗯，讓我想想。我敢打賭，足有一百次了!', `MaleText_loc7`='Ah, déjame ver. ¡Apostaría que ya van casi cien veces!' WHERE `ID`=238;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으하하! 트롤플로우의 포가 놈들을 공격했을 때 그 표정이란, 참 가관이더군! 벌목기의 톱은 내 발끝에도 닿지 않았다네!', `MaleText_loc4`='啊哈哈哈哈哈！我用枪指着他们鼻子的时候，那些家伙脸上的表情别提有多搞笑了！他们的锯子甚至都没能碰到我！', `MaleText_loc5`='啊哈哈哈哈哈!我用槍指著他們鼻子的時候，那些傢伙臉上的表情別提有多搞笑了!他們的鋸子根本沒能碰到我!', `MaleText_loc7`='¡Ja, ja, ja, ja! ¡Tenías que verles la cara, mientras el arma de la vieja Potenciatrol giraba de un lado a otro apuntando hacia ellos para darles! ¡Sus sierras no podían tocarme siquiera!' WHERE `ID`=239;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 전차도 에버샤인 술만 조금 넣으면 번개같이 달린다고!', `MaleText_loc4`='我应该往我的坦克里扔几瓶艾沃沙酒，然后在他们发现我之前赶紧回家！', `MaleText_loc5`='我應該往我的坦克裡扔幾瓶艾沃沙酒，然後在他們發現我之前趕緊回家!', `MaleText_loc7`='¡Me habría dado tiempo a echar un poco de combustible en el depósito y a estar de vuelta en casa antes de que ellos se dieran cuenta de que me había ido!' WHERE `ID`=240;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 웃기지도 않는 소리...', `MaleText_loc4`='呸！这一点都不好笑！', `MaleText_loc5`='呸!這一點都不好笑!', `MaleText_loc7`='¡Bah! ¡No tiene gracia!' WHERE `ID`=241;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 스톤! 언제 경주 한번 어때? 누가 이기는지 한번 해보자고. 난 몇 바퀴고 코스를 돌 자신이 있어.', `MaleText_loc4`='嘿，咱们来赛坦克吧。多跑几圈，看看谁会赢？', `MaleText_loc5`='嘿，阿石，我們找機會去環型跑道。跑個幾圈，看誰會贏?', `MaleText_loc7`='Oye, Roca, vamos a correr al circuito un día de estos. Podríamos correr unas cuantas vueltas y ver quién gana, ¿te hace?' WHERE `ID`=242;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그거 좋지. 경주를 끝낸 후에 바로 결투장으로 간다면 말이야!', `MaleText_loc4`='没问题，过一会咱们就去比一比！', `MaleText_loc5`='沒問題，只要比完了再去競技場一趟我就去!', `MaleText_loc7`='Claro que sí, ¡después de terminar nuestra tarea!' WHERE `ID`=244;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 아무리 그래 봐야 자네가 증기 전차라고 부르는 괴상한 기계를 가지고는 경주장에서 날 이길 수 없어!', `MaleText_loc4`='这世上根本就没有任何可以跟蒸汽坦克叫板的东西！', `MaleText_loc5`='不管你再怎麼說，我是不可能會跟你那個怪獸蒸汽坦克對戰的!', `MaleText_loc7`='¡Nada de lo que puedas decir me hará luchar contra esa monstruosidad de máquina a la que llamas tanque de vapor!' WHERE `ID`=245;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 내가 자네의 그 가소로운 경주용 기계를 부술까 봐 겁나나?', `MaleText_loc4`='哈！你害怕我会弄伤你那小不点赛车手？', `MaleText_loc5`='哈!你害怕我會弄壞你那輛娘砲小車?', `MaleText_loc7`='¡Ja! ¿Tienes miedo de que haga daño a tu pequeño y delicado corredor?' WHERE `ID`=246;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 오히려 자네의 구멍 난 고물 전차가 폭발을 일으켜 내가 파편에 맞지나 않을까 걱정일세!', `MaleText_loc4`='哈！我更加担心你那破烂不堪的东西会炸成一千块！', `MaleText_loc5`='哈!我是在擔心被你那輛破車爆炸的碎片給打到!', `MaleText_loc7`='¡Ja! ¡Me da más miedo que esos viejos agujeros y brechas lo hagan estallar y me alcance la lluvia de metralla!' WHERE `ID`=247;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하! 내 막강 트롤플로우에는 전투할 때 생긴 작은 흠집만 몇 개 있을 뿐이라고!', `MaleText_loc4`='哈哈！看看这些在战斗中留下的伤痕！', `MaleText_loc5`='哈哈!看看這些在戰鬥中留下的傷痕!', `MaleText_loc7`='¡Ja, ja! ¡La vieja y fuerte Potenciatrol tiene solo unas cuantas cicatrices de nada!' WHERE `ID`=248;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 엔진도 이중 기화 포크링 증기 엔진만한 건 없지! 순수한 내화 석재를 연료로 하거든.', `MaleText_loc4`='没有什么声音能比双缸蒸汽坦克开动时的动静更大了！', `MaleText_loc5`='沒有什麼聲音能比雙缸蒸汽坦克開動時的動靜更大了!', `MaleText_loc7`='¡Nada es comparable al sonido del motor de doble carburador de una moto con horquilla tuneada y el chirrido de unas buenas piedras de fuego!' WHERE `ID`=249;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 언제라도 기꺼이 운석포 XT로 포탄을 발사해 주지!', `MaleText_loc4`='哈！跟XT型火炮的声音比起来，那简直是蚊子叫！', `MaleText_loc5`='哈!跟XT型火砲的聲音比起來，那簡直是蚊子叫!', `MaleText_loc7`='¡Ja! ¡Prefiero mil veces el sonido de un Cañón Cráter XT soltando cañonazos!' WHERE `ID`=250;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흥! 자네가 사라지면 뛰어난 증기 엔진을 다시 볼 수도 없게 될 텐데!', `MaleText_loc4`='呸！你这没开过蒸汽坦克的乡巴佬懂什么！', `MaleText_loc5`='呸!你這沒開過蒸汽坦克的鄉巴佬懂什麼!', `MaleText_loc7`='¡Bah! ¡No sabrías reconocer una potente máquina de vapor aunque te diera justo en la cabeza!' WHERE `ID`=251;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럴지도 모르지. 하지만 자네 증기 엔진이 날 날려 버린다면, 그걸 산산조각내 버리는데 어떤 포를 써야하는지는 잘 알고 있다고.', `MaleText_loc4`='也许吧，但不管是什么型号的坦克，我都能用XT型火炮把它炸得稀巴烂！', `MaleText_loc5`='也許吧，但不管是什麼型號的坦克，我都能用XT型火砲把它炸得稀巴爛!', `MaleText_loc7`='Tal vez, pero si me diera justo en la cabeza, ¡sabría exactamente qué cañón usar para hacerla añicos!' WHERE `ID`=252;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여보. 할란 씨가 가능한 한 빨리 편물 셔츠와 바지 한 짐을 보내 달라는군요.', `FemaleText_loc4`='亲爱的科贝特，哈兰要我们尽快给他送些衬衣和短裤过去。', `FemaleText_loc5`='親愛的科貝特，哈蘭要我們儘快給他送些襯衣和束褲過去。', `FemaleText_loc7`='Corbett, cariño. Harlan necesita unas cuantas camisas y pantalones de punto cuanto antes.' WHERE `ID`=253;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='코베트, 듣고 있어요? 할란 씨가 편물 제품을 또 한 짐 부탁했어요. 좀 가져다줄래요?', `FemaleText_loc4`='科贝特，你在吗？哈兰还需要一些针织品。你能给他带一些过去吗？', `FemaleText_loc5`='科貝特，你在嗎?哈蘭還需要一些毛衣褲。你能給他帶一些過去嗎?', `FemaleText_loc7`='Corbett, ¿estás ahí? Harlan necesita otra carga de ropa de punto. ¿Puedes llevársela?' WHERE `ID`=254;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가고 말고, 여보. 금방 돌아오겠소.', `MaleText_loc4`='啊，我很荣幸，小甜心。我很快就回来……', `MaleText_loc5`='啊，我很榮幸，小甜心。我很快就回來...', `MaleText_loc7`='Es un placer, preciosa. Pronto volveré...' WHERE `ID`=255;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시장에서 장사가 잘 되나 보군. 지금 바로 배달을 다녀오리다.', `MaleText_loc4`='他的生意似乎挺火爆的！我马上就给他补充货物！', `MaleText_loc5`='市集的生意一定很棒!我馬上就給他補充貨物!', `MaleText_loc7`='El negocio debe de ir bien en el mercadillo. ¡Tengo que reabastecerlo inmediatamente!' WHERE `ID`=256;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠... 이걸 배달한 다음에 저 치즈 가게에 들러 뭘 좀 먹어야겠군.', `MaleText_loc4`='嗯……等搞定这些，我就要去奶酪店吃点东西。', `MaleText_loc5`='嗯...等貨送好，我就要去乳酪店吃點東西。', `MaleText_loc7`='Mmm... después de entregar esto, me iré a comer un tentempié en esa quesería.' WHERE `ID`=257;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돈이 좀 남았군. 이걸로 점심이나 사 먹어야겠어.', `MaleText_loc4`='卖完这些东西我也就能稍微挣点钱了，中午吃什么呢……', `MaleText_loc5`='賣完這批東西我也多賺了幾個錢，中午吃什麼呢...', `MaleText_loc7`='Creo que me sobran unas cuantas monedas de esta venta. A lo mejor me compro directamente la comida...' WHERE `ID`=258;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='할란 씨, 주문한 편물 옷 한 짐 가져왔습니다.', `MaleText_loc4`='嘿，哈兰，这是你要的衣服。', `MaleText_loc5`='嘿，哈蘭，這是你要的衣服。', `MaleText_loc7`='Toma, Harlan. Aquí tienes una carga de ropa de punto.' WHERE `ID`=259;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으쌰! 여기 물건 또 한 짐 가져왔습니다! 할란 씨, 장사가 잘 되시나 보네요.', `MaleText_loc4`='哈兰！这些是你要的另一批衣服，今天你生意真不错啊！', `MaleText_loc5`='哈蘭!這些是你要的另一批衣服，今天你生意真不錯啊!', `MaleText_loc7`='¡Ea! Aquí tienes otra carga, Harlan. ¡Tiene que venderse rápidamente!' WHERE `ID`=260;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 정말 고맙네, 코베트. 당장 진열해야겠어.', `MaleText_loc4`='太感谢你了，科贝特。我马上就把这些货物放到柜上出售。', `MaleText_loc5`='太感謝你了，科貝特。我馬上就把這些貨物放到櫃上出售。', `MaleText_loc7`='Ah, te lo agradezco mucho, Corbett. Los pondremos en los estantes inmediatamente.' WHERE `ID`=261;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 그래, 빨리도 왔군. 자네와 거래를 하면 언제나 유쾌하단 말이야.', `MaleText_loc4`='好的，马上发货。很高兴和你做生意，科贝特。', `MaleText_loc5`='啊，貨來得真快。很高興和你做生意，科貝特。', `MaleText_loc7`='Ah, sí, y la entrega ha sido rápida. Como de costumbre, es un placer hacer negocios contigo, Corbett.' WHERE `ID`=262;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 가보겠습니다. 잘 지내세요, 할란 씨!', `MaleText_loc4`='好的，那我走了。多多保重，哈兰。', `MaleText_loc5`='好的，那我走了。多多保重，哈蘭。', `MaleText_loc7`='Bueno, entonces me marcho. Cuídate, Harlan.' WHERE `ID`=263;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장사가 잘 되는 걸 보니 기쁘군요! 할란 씨, 곧 또 보게 되길 바라겠습니다.', `MaleText_loc4`='很高兴看到你干得这么好，哈兰。希望我们很快能再见面……', `MaleText_loc5`='很高興看到你生意這麼好，哈蘭。希望我們很快能再見面...', `MaleText_loc7`='Me alegra saber que te va bien, Harlan. Espero verte pronto de nuevo...' WHERE `ID`=264;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시장님! 정찰병의 보고에 따르면 서쪽에서 이상한 움직임이 있다고 포착되었다고 합니다.', `MaleText_loc4`='大人！我们的卫兵报告说西边有一些异常的情况。', `MaleText_loc5`='鎮長大人!我們的斥候回報西邊有一些異常的情況。', `MaleText_loc7`='¡Señor alcalde! Nuestros exploradores han registrado extraños movimientos en el oeste.' WHERE `ID`=265;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엘로 시장님! 묘지 정찰병이 심상치 않은 소식을 가지고 돌아왔습니다.', `MaleText_loc4`='艾尔罗大人！我们派去墓地的探子带来了一些坏消息……', `MaleText_loc5`='艾爾羅鎮長!我們派去墓地的斥候帶來了一些壞消息...', `MaleText_loc7`='¡Alcalde Ello! Los exploradores del cementerio regresan con siniestros informes...' WHERE `ID`=266;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 늙은 은둔자의 통나무집에서 끔찍한 포효와 으르렁거리는 소리가 들리고 있습니다!', `MaleText_loc4`='从那个老隐士的小屋里传出了可怕的咆哮声！', `MaleText_loc5`='從那個老隱士的小屋裡傳出了可怕的咆哮聲!', `MaleText_loc7`='¡Se escuchan espantosos bramidos y gruñidos procedentes de la choza del viejo ermitaño!' WHERE `ID`=267;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='늑대들이 무언가에 쫓기듯이 이쪽으로 도망치고 있습니다.', `MaleText_loc4`='狼群都在朝这边跑，好像是为了躲避……躲避什么东西……', `MaleText_loc5`='狼群都在朝這邊跑，好像是在逃避...什麼東西...', `MaleText_loc7`='Los lobos van en esa dirección, como si huyeran de... algo.' WHERE `ID`=268;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예, 시장님.', `MaleText_loc4`='遵命，大人。', `MaleText_loc5`='遵命，鎮長大人。', `MaleText_loc7`='Sí, señor alcalde.' WHERE `ID`=269;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 좋은 소식이군. 이것이 $n|1이;가; 장의사를 위해 한 일과 관련이 있는 것이 아닐까 우려되는군.', `MaleText_loc4`='这是一个可怕的消息，我担心这与$n为那个老隐士做的事情有关。', `MaleText_loc5`='這是一個可怕的消息，我擔心這與$n為那個藏屍者做的事情有關。', `MaleText_loc7`='Son malas noticias, y me temo que están relacionadas con los tratos que tuvo $n con el Embalsamador.' WHERE `ID`=270;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='순찰대원, 알시아 사령관에게 마을에 심각한 위협이 다가오고 있음을 보고 드리게. 어서 준비해야 하네!', `MaleText_loc4`='快派人去告诉阿尔泰娅，我们的小镇面临着巨大的危险。我们必须做好准备！', `MaleText_loc5`='快派人去告訴奧爾希雅，我們的小鎮面臨著巨大的危險。我們必須做好準備!', `MaleText_loc7`='Vigía, avisa a Althea que una siniestra amenaza se cierne sobre nuestra ciudad. ¡Debemos prepararnos!' WHERE `ID`=271;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알시아 님, 묘지에서 이상한 일들이 일어나고 있다는 보고가 들어왔습니다. 시장께서는 어둠골에 대한 공격의 전조라 믿고 계십니다.', `MaleText_loc4`='阿尔泰娅，有报告说墓地里有异常情况。艾尔罗认为这是夜色镇即将遭到攻击的前兆。', `MaleText_loc5`='奧爾希雅，有報告說墓地裡有異常情況。艾爾羅認為這是夜色鎮即將遭到攻擊的前兆。', `MaleText_loc7`='Althea, se dice que están ocurriendo cosas extrañas en el cementerio. Ello cree que esto presagia un posible ataque sobre Villa Oscura.' WHERE `ID`=272;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋지 않은 징조야. 순찰대원을 보내 정보를 수집하고 경계를 강화하게.', `FemaleText_loc4`='这不是个好兆头。马上派人去继续侦查，其他人保持警戒。', `FemaleText_loc5`='這不是個好兆頭。馬上派斥候前去繼續偵察，其他人保持警戒。', `FemaleText_loc7`='No es buena señal. Envía exploradores para que aumenten el equipo de inteligencia y manteneos alerta.' WHERE `ID`=273;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예, 사령관님!', `MaleText_loc4`='遵命，长官！', `MaleText_loc5`='遵命，長官!', `MaleText_loc7`='¡Sí, Comandante!' WHERE `ID`=275;
