UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, 코베트 씨! 자, 치즈 여기 있어요. 오늘 아침에 막 만든 거랍니다. 가게는 잘 되시고요?', `FemaleText_loc4`='你好，科贝特。这是今天早上刚做好的奶酪！你的商店生意还好么？', `FemaleText_loc5`='你好，科貝特。這是今天早上剛做好的乳酪!你的商店生意還好麼?', `FemaleText_loc7`='¡Buenos días, Corbett! ¡Aquí tienes tu queso, fresco de esta mañana! ¿Cómo van las cosas en tu tienda?' WHERE `ID`=286;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='코베트씨, 어서 오세요! 자, 여기 있어요. 옷 가게는 잘 되고 있죠?', `FemaleText_loc4`='你好啊，科贝特！拿着吧！你服装店的生意一定很不错吧？', `FemaleText_loc5`='你好啊，科貝特!拿著吧!你服裝店的生意一定很不錯吧?', `FemaleText_loc7`='¡Hola, Corbett! ¡Cómo vas! ¿El negocio va bien en tu tienda de ropa?' WHERE `ID`=287;
