UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바다에 폭풍이 몰아치고 있어. 바다 정령들이 정신없겠는걸... 딸꾹!', `MaleText_loc4`='波涛汹涌的海洋……看来海之精灵是永不疲倦的……嗝儿！', `MaleText_loc5`='風大浪大的...看來海之精靈又不平靜了...嗝兒!', `MaleText_loc7`='La mar está tormentosa. Los espíritus de la mar deben de estar inquietos..., ¡hip!' WHERE `ID`=318;
