UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밖으로 나가 저 놀들을 싹 쓸어 버리고 싶지만, 지금까지 너무 편하게 지내와서... 오히려 내가 당할까 봐 두렵다고.', `MaleText_loc4`='我要出去干掉几个豺狼人，但是这条腿刚好点，我担心这样冒冒失失地出去的话不会有好结果。', `MaleText_loc5`='我很想出去殺幾個豺狼人，但我這條腿已經不中用了，到時候恐怕連老命都不保。', `MaleText_loc7`='Iré allí fuera y acabaré con unos cuantos gnolls, pero me temo que he tenido días mejores y esta vez acabaré muerto.' WHERE `ID`=320;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 밖에서는 조심하는 게 좋을 거야. 많은 모험가들이 늪으로 갔다가 돌아오지 못했지. 딸꾹!', `MaleText_loc4`='在那里要千万小心，许多探险者都没能活着从沼泽地回来。嗝！', `MaleText_loc5`='在那裡要千萬小心，許多探險者都沒能活著從沼澤地回來。嗝!', `MaleText_loc7`='Cuida tus pasos ahí fuera. Muchos aventureros no regresaron del pantano. ¡Hip!' WHERE `ID`=321;
