UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왔군. 그래, 서부 몰락지대에서 어떤 소식을 가져왔나?', `MaleText_loc4`='你来啦，西部荒野那边有什么消息吗？', `MaleText_loc5`='你來啦，西部荒野那邊有什麼消息嗎?', `MaleText_loc7`='Aquí estás. ¿Traes noticias de los Páramos de Poniente?' WHERE `ID`=323;
