UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠.. 참견하기 좋아하는 쇼가 아닐까 싶군. 내 나름대로 알아보지. 우선 가보게나. 곧 다시 연락하지.', `MaleText_loc4`='嗯，可能就是那个爱管闲事的肖尔，我要去看看能找到些什么。回头再联系吧。', `MaleText_loc5`='嗯，可能就是那個愛管閒事的肖爾，我要去看看能找到些什麼。回頭再聯繫吧。', `MaleText_loc7`='Mmm, podría ser ese entrometido de Shaw. Veré lo que puedo descubrir. Y ahora, vete. Me pondré en contacto contigo pronto.' WHERE `ID`=326;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='*휴* 또 묘지를 둘러볼 시간이 됐군. 이봐, 몇 분 뒤에 돌아오지.', `MaleText_loc4`='唉，又是到墓地去巡逻的时间了——我很快就回来。', `MaleText_loc5`='唉，又是到墓地去巡邏的時間了─我很快就回來。', `MaleText_loc7`='*suspiro* Es hora de volver a comprobar el cementerio. Estaré de vuelta en unos minutos.' WHERE `ID`=327;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 울타리는 빨리 수리해야겠는걸.', `MaleText_loc4`='我们应该快点把那个篱笆修好。', `MaleText_loc5`='我們應該快點把那個籬笆修好。', `MaleText_loc7`='Deberíamos reparar esta cerca cuanto antes.' WHERE `ID`=328;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='브록이 말하길 그룸라르 총의 가늠쇠가 어긋나 있다고 했지. 한번 확인해 봐야겠소.', `MaleText_loc4`='维罗克说格鲁姆拉好像打中了什么东西，我想我应该去看看。', `MaleText_loc5`='維羅克說格魯姆拉的槍上面的準星歪了。我想我應該去檢查看看。', `MaleText_loc7`='Vrok ha dicho que la mira del arma de Grumlar está desviada. Supongo que tendré que revisarla.' WHERE `ID`=329;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런! 가만히 있는 표적조차 맞힐 수 없다니! 그 멍청한 드워프 놈이 또 총이 지팡이인줄 알았나 보군.', `MaleText_loc4`='该死！我没有击中目标！那个愚蠢的矮人可能又把枪当锤使了。', `MaleText_loc5`='該死!我沒有擊中目標!那個愚蠢的矮人可能又把槍當錘使了。', `MaleText_loc7`='¡Ajá! ¡Ni siquiera di en el blanco que ya está destrozado! Quizás ese enano cabezudo ha vuelto a usar el arma como garrote.' WHERE `ID`=330;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠... 저 시체는 어깨가 잘려 나갔군. 그룸라르가 옳았어. 가늠쇠가 약간 어긋나 있었군. 뭐, 그래도 그 정도면 내가 금방 조정할 수 있소.', `MaleText_loc4`='嗯……格鲁姆拉说对了，准心好像是有些偏，不过很容易就能修好。', `MaleText_loc5`='嗯...格魯姆拉說對了，準星好像是有些偏，不過很容易就能修好。', `MaleText_loc7`='Mmmm... Le di en el hombro. Grumlar estaba en lo cierto, la mira está ligeramente desajustada. No importa, la arreglaré.' WHERE `ID`=331;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 거의 완벽했는데! 약간 어긋나 있긴 하지만, 그룸라르는 저 넓은 헛간의 벽도 맞히지 못했을 게 뻔하오.', `MaleText_loc4`='完美的射击！格鲁姆拉根本就没这个准头，他就是用枪顶着目标也不一定能打中！', `MaleText_loc5`='完美的射擊!格魯姆拉根本就沒這個準頭，他就是用槍頂著目標也不一定能打中!', `MaleText_loc7`='¡Un tiro casi perfecto! Está un poco desajustada, pero yo sé por qué Grumlar ha fallado con ella. No es capaz de tirar a la parte más ancha de un establo.' WHERE `ID`=332;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명중이군! 그 괘씸한 드워프 놈은 아무것도 모른단 말이오. 그룸라르가 잘못 조준한 것뿐이었지.', `MaleText_loc4`='可笑！那个该死的矮人根本不知道他在说什么，格鲁姆拉的准头太差了。', `MaleText_loc5`='正中紅心!那個該死的矮人根本不知道自己在說什麼，問題就出在格魯姆拉的準頭太差了。', `MaleText_loc7`='¡Diana! Ese maldito enano no sabe de qué está hablando. El único problema con la pistola de Grumlar es la puntería de Grumlar.' WHERE `ID`=333;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크리스마스까지 $3658E분밖에 안 남았습니다! 잠깐, 크리스마스 맞나요? 그럼 파티까지 $3659E분밖에 안 남았습니다! 테스트 테스트 현지화 필요 없음', `MaleText_loc4`='Only $3658E shopping minutes before Christmas!  But wait, is it Christmas?  Well then, there are only $3659E minutes left to party!  TEST TEST DO NOT LOCALIZE', `MaleText_loc5`='Only $3658E shopping minutes before Christmas!  But wait, is it Christmas?  Well then, there are only $3659E minutes left to party!  TEST TEST DO NOT LOCALIZE', `MaleText_loc7`='Only $3658E shopping minutes before Christmas! But wait, is it Christmas? Well then, there are only $3659E minutes left to party! TEST TEST DO NOT LOCALIZE' WHERE `ID`=339;
