UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어이구! 너무 많이 먹은 것 같군. 허리띠를 좀 풀어야겠는걸.', `MaleText_loc4`='呃！我想我吃得太多了，得松松皮带……', `MaleText_loc5`='呼!我想我吃得太多了，得鬆鬆皮帶。', `MaleText_loc7`='¡Ufff! Creo que he comido demasiado. Tengo que aflojar mi cinturón unos cuantos agujeros.' WHERE `ID`=347;
