UPDATE `locales_broadcast_text` SET `MaleText_loc1`='낚시하기에 정말 좋은 날씨더라고, 카라. 빨리 나가봐야겠어.', `MaleText_loc4`='又是一个钓鱼的好日子，卡拉。我马上就出发。', `MaleText_loc5`='又是一個釣魚的好日子，卡拉。我馬上就出發。', `MaleText_loc7`='Me espera otro espléndido día de pesca, Khara. Será mejor que me vaya.' WHERE `ID`=349;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='낚시하기에 더할 나위 없이 좋은 날이군. 오늘은 많이 잡히겠는 걸!', `MaleText_loc4`='这种天气最适合钓鱼了！', `MaleText_loc5`='這種天氣最適合釣魚了!魚兒今天一定會上鉤!', `MaleText_loc7`='Vaya día para pescar.' WHERE `ID`=350;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='워그가 물때를 보기 위해 물속을 들여다봅니다.', `MaleText_loc4`='瓦格注视着水面，不知道他今天的运气会如何。', `MaleText_loc5`='瓦格注視著水面，評估他今天的釣運如何。', `MaleText_loc7`='Warg inspecciona el agua para ver qué suerte le depara hoy.' WHERE `ID`=352;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠... 쩝, 고기가 더 잡히지 않겠군. 돌아가서 오늘 잡은 고기나 손질해야겠다.', `MaleText_loc4`='唉，看来是钓不到鱼了，我看我还是回去刮鱼鳞吧。', `MaleText_loc5`='唉，看來是釣不到更多魚了，我看我還是回去刮魚鱗吧。', `MaleText_loc7`='Welp, no cae un solo pez, así que creo que me pondré a limpiar todo lo que pesqué hoy.' WHERE `ID`=353;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='집으로 가는 길은 언제나 즐거워. 내가 오기를 카라가 기다리고 있을 테니 내일 또 보자고.', `MaleText_loc4`='我想我最好现在就回去，卡拉也一定盼着我快点回去。明天见啦。', `MaleText_loc5`='我想我最好現在就回去，卡拉也一定盼著我快點回去。明天見啦。', `MaleText_loc7`='Será mejor que me vaya. Pronto me estará esperando Khara. Nos vemos mañana X.' WHERE `ID`=355;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 물결의 움직임을 좀 봐. 물속에 활발한 움직임이 있는 것 같으니 오늘은 꽤 많이 낚겠는걸.', `MaleText_loc4`='看看水面那些波纹……水里可真热闹，今天我一定能钓很多鱼。', `MaleText_loc5`='看看水面那些波紋...水裡可真熱鬧，今天我一定能釣很多魚。', `MaleText_loc7`='Mira todas esas olas. Hay mucha actividad en el agua, así que tal vez pesque muchos peces hoy.' WHERE `ID`=356;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠, 수면에 별다른 움직임이 없지만 태양의 위치가 좋으니 어쩌면 좀 낚을 수 있을지도 모르겠군.', `MaleText_loc4`='恩……水面上虽然看不出什么动静，但是今天天气不错，我的运气也应该不错。', `MaleText_loc5`='恩...水面上雖然看不出什麼動靜，但是今天天氣不錯，我的運氣也應該不錯。', `MaleText_loc7`='Mmm, veo poca actividad en la superficie, pero el sol está en el lugar correcto. Puede que la jornada mejore, al fin y al cabo.' WHERE `ID`=357;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠, 좋지 않은걸. 태양이 너무 일찍 솟고 햇빛이 강한데다 수면에는 아무런 움직임도 없으니...', `MaleText_loc4`='今天估计没戏。太阳早早地到了正中，而且阳光太耀眼了，水里也没有什么动静。', `MaleText_loc5`='今天看來沒什麼戲唱。太陽高照，陽光耀眼，而且水裡什麼動靜也沒有。', `MaleText_loc7`='La cosa no pinta demasiado bien hoy. El sol ya brilla a estas horas y no hay actividad en el agua.' WHERE `ID`=358;
