UPDATE `locales_broadcast_text` SET `MaleText_loc1`='베르테! 에발린! 날이 어두워지고 있어. 어서 들어오너라.', `MaleText_loc4`='波尔特！伊瓦琳！天黑了，快回屋里来。', `MaleText_loc5`='波爾特!伊瓦琳!天黑了，快回屋裡來。', `MaleText_loc7`='¡Berte! ¡Evalyn! Se está haciendo de noche. Venid adentro.' WHERE `ID`=360;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내일 또 놀러 나가면 되잖니. 얼른 집으로 들어와.', `MaleText_loc4`='明天再玩吧，现在快回屋里来。', `MaleText_loc5`='明天再玩吧，現在快回屋裡來。', `MaleText_loc7`='Mañana seguirás jugando. Ahora entra en casa.' WHERE `ID`=361;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알았다, 알았어. 대신 마을 안에서만 놀아라. 미치광이 워그와 카라 부부가 사는 물가에는 얼씬도 하지 마.', `MaleText_loc4`='好吧。你们两个可以去玩，但不许跑出镇子去。不要偷偷溜出去打扰水边的瓦格和卡拉。', `MaleText_loc5`='好吧。你們兩個可以去玩，但不許跑出鎮子去。不要偷偷溜出去打擾水邊的瓦格和卡拉。', `MaleText_loc7`='Muy bien, muy bien. Los dos podéis ir a jugar, pero quedaos en la ciudad. No se os ocurra ir a incordiar a Warg y Khara cerca del lago.' WHERE `ID`=362;
