UPDATE `locales_broadcast_text` SET `MaleText_loc1`='붉은십자군이 이 땅을 정화할 것이다!', `MaleText_loc4`='血色十字军将彻底净化这片土地！', `MaleText_loc5`='血色十字軍將徹底淨化這片土地!', `MaleText_loc7`='¡La Cruzada Escarlata dará una batida en estas tierras!' WHERE `ID`=372;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사악한 역병에 감염된 것들은 모조리 쓸어 버려라!', `MaleText_loc4`='彻底清除任何被污染的东西！', `MaleText_loc5`='徹底清除被瘟疫沾染到的任何東西!', `MaleText_loc7`='¡No dejéis que vivan aquellos que estén contaminados con la Peste nauseabunda!' WHERE `ID`=373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엄마! 우리 나가서 놀면 안 돼요? 제발요...제발... 응?', `MaleText_loc4`='妈妈！我们可以去玩吗？可以吗？好不好？妈妈？', `MaleText_loc5`='媽媽!我們可以去玩嗎?可以嗎?好不好?媽媽?', `MaleText_loc7`='¡Mamá! ¿Podemos salir a jugar? Porfi, porfi, porfi... ¿Nos dejas? ¿Nos dejas?' WHERE `ID`=374;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이들이 즐거워하며 펄쩍펄쩍 뜁니다.', `MaleText_loc4`='小孩充满活力地跳上跳下。', `MaleText_loc5`='小孩充滿活力地跳上跳下。', `MaleText_loc7`='Los chicos saltan y corretean con energía. (emotexto de PH )' WHERE `ID`=375;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우와아! 고마워요, 엄마!', `MaleText_loc4`='耶~~~谢谢妈妈！', `MaleText_loc5`='耶!謝謝媽媽!', `MaleText_loc7`='¡Bieeeen! ¡Gracias, mamá!' WHERE `ID`=376;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙습니다, 브라이트비어드 부인!', `MaleText_loc4`='谢谢叔叔！', `MaleText_loc5`='謝謝亮鬍太太!', `MaleText_loc7`='¡Gracias, señor Barbaclara!' WHERE `ID`=378;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밖이 추워지고 있군. 불을 쬐고 술로 몸도 좀 녹여야겠어.', `MaleText_loc4`='这里有点冷啊，我要烤烤火再喝点酒取暖。', `MaleText_loc5`='這裡有點冷啊，我要烤烤火再喝點酒取暖。', `MaleText_loc7`='Me está entrando algo de frío. Creo que me voy a calentar junto al fuego y a coger una pinta o doce.' WHERE `ID`=379;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 추운 밤에는 이글대는 불과 좋은 친구, 그리고 드워프 에일 맥주만큼 좋은 게 없지.', `MaleText_loc4`='喝着啤酒和好朋友围坐在火堆旁边可真是一件乐事。', `MaleText_loc5`='喝著矮人麥酒和好朋友圍坐在火堆旁邊可真是一件樂事。', `MaleText_loc7`='Nada como una buena fogata en una noche fría, rodeado de buenos amigos y cerveza de enanos.' WHERE `ID`=380;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='브록, 토렌. 난 안으로 들어가서 불을 쬐며 마실 맥주나 한 병 가지고 올게.', `MaleText_loc4`='布洛克，托瑞恩，我要进去喝杯麦酒，烤烤火暖暖身子。', `MaleText_loc5`='布洛克，托瑞恩，我要進去喝杯麥芽酒，烤烤火暖暖身子。', `MaleText_loc7`='Brock. Torren. Entraré a buscar un poco de birra y a calentarme junto al fuego.' WHERE `ID`=381;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음... 불가에서 마시는 맥주라... 멋진데. 나도 같이 마시겠어, 예른.', `MaleText_loc4`='嗯……围着火炉喝点麦酒，这个主意听上去很不错。我当然会和你一起去的，吉恩。', `MaleText_loc5`='嗯...圍著火爐喝點麥芽酒，這個主意聽起來很不錯。好啊，一起去，吉恩。', `MaleText_loc7`='Mmm, una cerveza junto al fuego... qué bien suena eso. Yo también me apunto, Jern.' WHERE `ID`=382;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나도! 나도 좀 주게!', `MaleText_loc4`='干杯！', `MaleText_loc5`='來來來!乾杯!', `MaleText_loc7`='¡Hala! ¡Hala! ¡Brindo por eso!' WHERE `ID`=383;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='응? 누가 에일 맥주 얘기를 꺼냈나? 이 토렌을 빼놓고 마시면 섭섭하지!', `MaleText_loc4`='什么？有人说到麦酒了？没有托瑞恩在场，哪能喝得爽快！', `MaleText_loc5`='什麼?有人說到麥酒嗎?沒有托瑞恩在場，哪能喝得爽快!', `MaleText_loc7`='¿Qué? ¿Alguien dijo cerveza? ¡No empecéis a repartir cervezas sin contar con el viejo Torren!' WHERE `ID`=384;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무튼 나도 건배!', `MaleText_loc4`='有什么就上什么！', `MaleText_loc5`='有什麼就上什麼!', `MaleText_loc7`='¡Me beberé lo que sea!' WHERE `ID`=385;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노마가 곧 저녁 식사를 내올 거요. 어서 와서 같이 드세요.', `MaleText_loc4`='诺玛已经快把中饭准备好了。也许最好还是head in。', `MaleText_loc5`='諾瑪已經快把晚飯準備好了。我們最好還是快去吧。', `MaleText_loc7`='Noma debería cenar pronto. Y ya podría entrar.' WHERE `ID`=386;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 검은발톱 스타우트 맥주는 상당히 독하지.', `MaleText_loc4`='啊，好来劲的酒啊！', `MaleText_loc5`='哇喔，這黑爪烈酒真帶勁!', `MaleText_loc7`='¡Caramba! ¡Esa birra Zarpanegra sí que pega fuerte!' WHERE `ID`=387;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 어지럽군. 여긴 왜... 이렇게... 더운 거야...', `MaleText_loc4`='我感到……头晕目眩。这里太热了……', `MaleText_loc5`='我覺得...頭暈暈的。這裡...太熱了...', `MaleText_loc7`='Siento... mareos. Hace... tanto calor... aquí...' WHERE `ID`=388;
