UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다들 오는군...', `MaleText_loc4`='每个人都正在赶来……', `MaleText_loc5`='每個人都正在趕來...', `MaleText_loc7`='Ya vienen todos...' WHERE `ID`=390;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그로서도 어찌할 도리가 없었지...', `MaleText_loc4`='他真的帮不上忙……', `MaleText_loc5`='他真的沒辦法...', `MaleText_loc7`='No pudo hacer nada...' WHERE `ID`=391;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누구나 언젠가는 결국 죽게 되지...', `MaleText_loc4`='没有人能长生不老……', `MaleText_loc5`='沒有人能長生不老...', `MaleText_loc7`='Nadie es eterno...' WHERE `ID`=393;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='김록! 김록! 당장 이리 들어와!', `FemaleText_loc4`='吉姆洛克！吉姆洛克！马上进来！', `FemaleText_loc5`='吉姆洛克!吉姆洛克!馬上給我進來!', `FemaleText_loc7`='¡Gimlok! ¡Gimlok! ¡Ven aquí dentro ahora mismo!' WHERE `ID`=394;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='얘가 지금 어디 있는 거지?', `FemaleText_loc4`='那小子去哪儿了？', `FemaleText_loc5`='那小子去哪兒了?', `FemaleText_loc7`='¿Y ahora adónde se ha ido el chico?' WHERE `ID`=395;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='김록, 밖에 나가서 옷을 더럽히고 오면 혼난다.', `FemaleText_loc4`='吉姆洛克，不要动，你把衣服全弄脏了。', `FemaleText_loc5`='吉姆洛克，不要玩得把衣服全弄髒了。', `FemaleText_loc7`='Gimlok, no vayas a ensuciarte la ropa para variar.' WHERE `ID`=396;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='욱... 욱... 우웨엑!', `MaleText_loc4`='快点……快点……', `MaleText_loc5`='嗝...呃...呃啊!', `MaleText_loc7`='¡Júuuuu... júuuuuu... bliiiiiiii!' WHERE `ID`=397;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나도 언젠간 훌륭한 경비병이 될 겁니다!', `MaleText_loc4`='我总有一天会成为卫兵的！', `MaleText_loc5`='我總有一天會成為守衛的!', `MaleText_loc7`='¡Algún día seré un guardia!' WHERE `ID`=398;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다나스가 스톰윈드의 모든 용병을 모아 전투를 위해 네더가드로 진격해 갔던 때를 기억하나?', `MaleText_loc4`='你还记得当年达纳斯聚集了暴风城的所有雇佣兵，然后开到守望堡去跟兽人大战的事情吗？', `MaleText_loc5`='你還記得當年達納斯聚集了暴風城的所有雇傭兵，然後揮軍守望堡展開大戰的事情嗎?', `MaleText_loc7`='¿Recuerdas cuando Danath reunió a todos los mercenarios de Ventormenta y marchamos a combatir a Nethergarde?' WHERE `ID`=399;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 대전쟁을 속속들이 다 겪었어. 우리가 다로우미어 호수에서 싸웠을 때가 생각나는군. 질퍽거리는 참호 속에서 밤을 꼬박 새웠었지.', `MaleText_loc4`='我跟你说，我参加了整场大战。我还记得当时我们在达隆米尔战斗的情景。整个晚上都是雾，我们就躺在满是泥泞的战壕里。', `MaleText_loc5`='我跟你說，我一點都不懷念那場大戰。我還記得當時我們在達隆米爾戰鬥的情景。整個晚上都是霧，我們就躺在滿是泥濘的戰壕裡。', `MaleText_loc7`='Ya te digo, yo no echo nada de menos la Gran Guerra. Recuerdo cuando luchamos en Darrowmere. Toda la noche en medio de la niebla, tendidos en una trinchera llena de lodo.' WHERE `ID`=400;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로데론의 그 여관에서 마시곤 했던 드워프 에일 맥주가 그리워. 자네, 거기서 시작된 우리의 전투를 기억하나?', `MaleText_loc4`='我真的很怀念洛丹伦的那个旅馆里的矮人麦酒。还记得我们在那里开始的战斗吗？', `MaleText_loc5`='我真的很懷念羅德隆的那個旅館裡的矮人麥酒。還記得我們在裡頭打的那一架嗎?', `MaleText_loc7`='Echo de menos la cerveza enana que nos daban en la taberna de Lordaeron. ¿Te acuerdas la pelea que iniciamos allí?' WHERE `ID`=401;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 백 명이 안 되고 오크 놈들은 천 명이 넘었지. 우리 중 몇 명만이 그 전투에서 살아 돌아올 수 있었어.', `MaleText_loc4`='我们不足百人，兽人却有上千个。区区百人怎么能够战胜他们？', `MaleText_loc5`='我們不足百人，獸人卻有上千個。最後我們只有少數人活著離開那個戰場。', `MaleText_loc7`='Éramos menos de un centenar y los orcos, más de un millar. Solo muy pocos conseguimos escapar de aquello.' WHERE `ID`=402;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최고의 순간은 우리 군대가 자기 집 문 앞에까지 진격해 가자 사색이 된 페레놀드의 표정을 보았을 때였지. 정말 대단한 전투였어!', `MaleText_loc4`='在我们的部队开到匹瑞诺德家门口的时候，你真该看看他的脸色。真是一场恶战！', `MaleText_loc5`='最精采的是我們的部隊進軍匹瑞諾德門口的時候，你真該看看他的臉色。真是精采啊!', `MaleText_loc7`='Lo mejor tuvo que ser la cara de Perenolde cuando nuestros ejércitos marchaban hacia su propia puerta. ¡Qué batalla!' WHERE `ID`=403;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 황혼의 망치단 무리와 습지대에서 싸웠었는데... 정말 끔찍한 전투였지.', `MaleText_loc4`='与沼泽中的暮光之锤信徒战斗，那感觉真是糟透了。', `MaleText_loc5`='與沼澤中的暮光之錘信徒戰鬥，那感覺真是糟透了。', `MaleText_loc7`='Luchar contra ese grupo del Martillo Crepuscular en las Ciénagas... se me ocurren mejores lugares para una guerra.' WHERE `ID`=405;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아 그래, 이제 생각나는군. 자네 결혼식 날밤 말이지?', `MaleText_loc4`='啊，对，现在我记起来了，是在你的新婚之夜吧？', `MaleText_loc5`='啊，對，現在我記起來了，是在你的新婚之夜吧?', `MaleText_loc7`='Ah, sí, ahora lo recuerdo, fue en tu noche de bodas, ¿no es así?' WHERE `ID`=406;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 그 글러스트웰트 쌍둥이!', `MaleText_loc4`='啊啊！', `MaleText_loc5`='啊啊，是克魯斯威特雙胞胎!', `MaleText_loc7`='¡Ahh, los gemelos Glustewelt!' WHERE `ID`=407;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그날 밤 입은 상처 자국이 아직 남아 있다고.', `MaleText_loc4`='那晚的伤痕依然留在我身上。', `MaleText_loc5`='那晚的傷痕依然留在我身上。', `MaleText_loc7`='Aún conservo cicatrices de aquella noche.' WHERE `ID`=408;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그날 밤 두 다리가 모두 부러졌었는데 어떻게 잊을 수 있겠나?', `MaleText_loc4`='那天晚上我断了两条腿。我怎么会忘记呢？', `MaleText_loc5`='那天晚上我斷了兩條腿。我怎麼會忘記呢?', `MaleText_loc7`='Esa noche me rompieron las dos piernas. ¿Cómo olvidarlo?' WHERE `ID`=409;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='3주 후에 북녘골의 침대 위에서 깨어났지. 하나도 기억이 나질 않더라고.', `MaleText_loc4`='三个星期之后，我在北郡醒来。但是我已经想不起任何事了。', `MaleText_loc5`='三個星期之後，我在北郡醒來。但是我已經想不起任何事了。', `MaleText_loc7`='Desperté en una cama en Villanorte tres semanas después. No recordaba nada en absoluto.' WHERE `ID`=410;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그날 밤에 내 반지를 주워서 자네 담배 주머니 안에 넣지 않았던가?', `MaleText_loc4`='是啊，那天晚上我们不得不捡起我的手指，然后把它放进你的烟袋里带了回来。', `MaleText_loc5`='那不就是我們得撿起我的大拇指，然後把它放進你的煙袋裡帶回來的那天晚上?', `MaleText_loc7`='¿No fue aquella la noche en que tuvimos que recoger mi pulgar y meterlo en tu bolsa de cigarrillos?' WHERE `ID`=411;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 등에 있는 상처가 아마 평생 그날 밤 일을 기억하게 할 걸세.', `MaleText_loc4`='我的后背里还有一小块铁片，这会让我永远记得那个晚上。', `MaleText_loc5`='我的背裡還有一小塊鐵片，提醒我永遠記得那晚上的事情。', `MaleText_loc7`='Tengo incrustado un trozo de hierro en la espalda, que me recordará esa noche durante el resto de mi vida.' WHERE `ID`=413;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론 그날 밤은 기억하지. 조금만 왼쪽으로 비켜 맞았어도 자네는 지금쯤 그 엘프 모리스와 함께 뒤틀린 황천에서 술을 마시고 있을 거야. 참, 그리고 그건 내가 가장 좋아하는 셔츠였다고.', `MaleText_loc4`='我当然记得那晚的情形。你就在我左边两英尺左右的地方，一直和那个名叫莫里斯的精灵在喝酒。那晚我还穿着我最好的衬衫哪。', `MaleText_loc5`='我當然記得那晚的情形。再往左邊偏個兩英吋，肯定就掛點了。那晚我還穿著我最好的襯衫呢。', `MaleText_loc7`='Claro que recuerdo aquella noche. De haber estado cinco centímetros más a la izquierda, ahora estarías bebiendo con ese elfo, Morris. Esa era también mi mejor camisa.' WHERE `ID`=414;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 그 정신 나간 묘기에 도전하다가 내가 복부에 크게 상처 입은 게 그때가 세 번째 아니면 네 번째였지, 아마?', `MaleText_loc4`='那是我第三次还是第四次呕吐了？你那些疯狂的烈酒……', `MaleText_loc5`='...那是第三次、還是第四次?你那些個瘋狂的舉動又害我差點肚破腸流了?', `MaleText_loc7`='¿No fue esa la tercera o cuarta vez que casi me destrozas probando una de tus locas proezas?' WHERE `ID`=415;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 그날 밤 내 손을 가지고 사제들에게 돌아갈 수 있도록 해 준 건 고맙게 생각하네.', `MaleText_loc4`='嗯，谢谢你那天晚上让我能把自己的手捡回去。', `MaleText_loc5`='嗯，謝謝你那天晚上讓我能把自己的手撿回去給牧師治療。', `MaleText_loc7`='Sí, y gracias por dejarme llevar mi propia mano a los sacerdotes esa noche.' WHERE `ID`=416;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헤헤, 소심하긴...', `MaleText_loc4`='呵呵，废物。', `MaleText_loc5`='呵呵，廢物。', `MaleText_loc7`='Je, je, chaval.' WHERE `ID`=417;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그때 자넨 어린 여자 아이처럼 비명을 질러댔지. 지금까지 내가 본 것 중 가장 우스운 광경이었어, 하하.', `MaleText_loc4`='你像个小女孩一般地尖叫，这真是我见过的最好笑的事。', `MaleText_loc5`='你叫得跟個小女孩一樣，真是我見過最好笑的事。', `MaleText_loc7`='Gritabas como una nena, fue lo más gracioso que he visto jamás.' WHERE `ID`=418;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='결국엔 다 잘 됐지.', `MaleText_loc4`='最后终于全搞定了。', `MaleText_loc5`='最後終於全搞定了。', `MaleText_loc7`='Al final todo salió bien.' WHERE `ID`=419;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투에서 입은 흉터를 비교하는 짓은 아예 시작도 하지 말자고, 친구.', `MaleText_loc4`='让我们不要再比较身上的伤痕了，朋友。', `MaleText_loc5`='讓我們不要再比較身上的傷痕了，朋友。', `MaleText_loc7`='Ay, amigo, no nos pongamos ahora a comparar nuestras cicatrices de guerra.' WHERE `ID`=420;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 지금껏 살면서 그렇게 빨리 움직이는 친구는 본 적이 없어.', `MaleText_loc4`='我从来没看到过有人逃得这么快。', `MaleText_loc5`='我從來沒看到過有人逃得這麼快。', `MaleText_loc7`='En mi vida vi a alguien moverse tan rápido.' WHERE `ID`=421;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네와 같이 지내다 보면 그 파란만장한 삶에 끊임없이 놀라게 된다니까.', `MaleText_loc4`='你真的令我感到非常惊讶，你居然活了下来。', `MaleText_loc5`='你真的令我感到非常驚訝，你居然活了下來。', `MaleText_loc7`='Constantemente me sorprendes con todo lo que una persona es capaz de soportar.' WHERE `ID`=422;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐, 우리가 아직 이렇게 살아 있다는 것만으로도 축배를 들 만한 일이 아닌가?', `MaleText_loc4`='好吧，你还好端端地坐在这里。我想说这里还是有些东西值得我们举杯庆贺的。', `MaleText_loc5`='好吧，你還好端端地坐在這裡。我想說這裡還是有些東西值得我們舉杯慶賀的。', `MaleText_loc7`='Bien, aquí sigues. Parece que hay algo bueno de beber.' WHERE `ID`=423;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 삶을 아주 흥미진진하게 만들어 준 내게 항상 감사하라고.', `MaleText_loc4`='你可以在任何时候感谢我，因为我令你的生活更加有趣。', `MaleText_loc5`='你可以在任何時候感謝我，因為我令你的生活更加有趣。', `MaleText_loc7`='Cuando quieras puedes agradecerme por hacer tu vida más interesante.' WHERE `ID`=424;
