UPDATE `locales_broadcast_text` SET `MaleText_loc1`='따뜻한 선술집과 차가운 맥주라... 더 바랄 게 없지.', `MaleText_loc4`='暖和的旅店，冰爽的麦酒。我们还能要求什么呢？', `MaleText_loc5`='溫暖的旅店，冰爽的麥芽酒。我們還能要求什麼呢?', `MaleText_loc7`='Una taberna caliente y una cerveza fría. ¿Qué más podemos pedir?' WHERE `ID`=432;
