UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뜻밖이군. 이 마법을 건 자가 내가 아는 자라니...', `MaleText_loc4`='这怎么可能……我对施展这个魔法的家伙太了解了……', `MaleText_loc5`='這怎麼可能...施展附魔的人...是我認識的...', `MaleText_loc7`='Esto es inesperado. El ser que encantó esto me resulta conocido...' WHERE `ID`=516;
