UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정복의 때가 임박했다.', `MaleText_loc4`='我们征服一切的时刻即将降临！', `MaleText_loc5`='我們征服一切的時刻即將降臨。', `MaleText_loc7`='La hora de la conquista se aproxima.' WHERE `ID`=519;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곧 너희의 파괴에 대한 갈증을 풀어 주겠다.', `MaleText_loc4`='你毁灭一切的欲望很快就会消失……', `MaleText_loc5`='你毀滅一切的欲望很快就會消失...', `MaleText_loc7`='Tu sed de destrucción pronto será satisfecha.' WHERE `ID`=520;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 안에 불타고 있는 그 분노를 곧 우리의 적에게 쏟아 부을 수 있을 것이다.', `MaleText_loc4`='你满腔的愤怒很快就可以倾泻在我们的敌人身上。', `MaleText_loc5`='你滿腔的憤怒很快就可以傾瀉在我們的敵人身上。', `MaleText_loc7`='La furia que os quema pronto encontrará combustible en nuestros enemigos.' WHERE `ID`=521;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 종족과 언데드 도둑떼의 전투에 관한 소식을 가져왔다.', `MaleText_loc4`='我有一些新的情报……关于我们与那些游荡的亡灵之间的战事。', `MaleText_loc5`='我有新的情報...關於和那個不受管控的亡靈的戰事。', `MaleText_loc7`='Traigo noticias de nuestra guerra contra los pícaros no-muertos.' WHERE `ID`=522;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로데론의 반역자들은 작고 나약하며 리치 왕을 섬기는 기쁨을 모르는 녀석들이다.', `MaleText_loc4`='洛丹伦的叛军相当弱小，而且他们居然不愿意效忠于巫妖王。', `MaleText_loc5`='羅德隆的反抗軍相當弱小，而且他們居然不願意效忠於巫妖王。', `MaleText_loc7`='Los rebeldes de Lordaeron son pequeños y débiles y desconocen la alegría de servir a nuestro Rey Exánime.' WHERE `ID`=523;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠의 여왕을 따르는 자들은 우리에게 대항할 수 있다고 생각할 만큼 우매한 자들이다.', `MaleText_loc4`='黑暗女王的追随者们都瞎了眼，竟然自以为他们能和我们对抗。', `MaleText_loc5`='黑暗女王的追隨者們都瞎了眼，竟然自以為他們能和我們對抗。', `MaleText_loc7`='Los seguidores de la Dama Oscura están ciegos si creen que pueden con nuestro poder.' WHERE `ID`=525;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 힘은 강해졌고, 우리의 적은 다른 적들에게 둘러싸여 계속되는 공격으로 약해졌다.', `MaleText_loc4`='我们越来越强大，而我们的敌人陷入了多线作战的困境，并且在持续的战事中变得越来越弱。', `MaleText_loc5`='我們越來越強大，而我們的敵人陷入了多線作戰的困境，並且在持續的戰事中變得越來越弱。', `MaleText_loc7`='Crecemos fuertes mientras nuestros adversarios están rodeados de enemigos y los debilitan ataques constantes.' WHERE `ID`=526;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폐하께서 전쟁 준비를 명하셨다!', `MaleText_loc4`='准备战斗！', `MaleText_loc5`='準備戰鬥!', `MaleText_loc7`='¡Nuestro Señor nos ordena que nos preparemos para la guerra!' WHERE `ID`=527;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곧 자칭 포세이큰이라는 자들에 대한 공격을 감행할 것이니 모두 준비하라.', `MaleText_loc4`='做好准备，我们马上就要对那些自称为被遗忘者的家伙发动一次进攻。', `MaleText_loc5`='做好準備，我們馬上就要對那些自稱為被遺忘者的傢伙發動一次進攻。', `MaleText_loc7`='Preparaos, porque pronto emprenderemos un asalto contra los que se hacen llamar "los Renegados."' WHERE `ID`=528;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나의 피조물들이여, 전투를 준비하라!', `MaleText_loc4`='准备作战吧，我的孩子们。', `MaleText_loc5`='準備作戰吧，我的孩子們。', `MaleText_loc7`='Preparaos para la batalla, mis creaciones.' WHERE `ID`=529;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 그분의 뜻을 행하는 군대이다. 따라서 우리는 그분의 적들을 무덤으로 이끌어야 한다!', `MaleText_loc4`='我们是他的意志的实施者，我们会把他的敌人送入坟墓！', `MaleText_loc5`='我們是他的意志的執行者，我們會把他的敵人送入墳墓!', `MaleText_loc7`='Somos el brazo de Su voluntad. ¡Y aplastaremos a Sus enemigos hasta convertirlos en polvo de sepultura!' WHERE `ID`=530;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 언데드 오합지졸들과 그들의 죽은 엘프 여왕은 파멸할 것이다!', `MaleText_loc4`='这些亡灵垃圾会和他们那死掉的精灵女王一起被毁灭！', `MaleText_loc5`='這些亡靈垃圾會和他們那死掉的精靈女王一起被毀滅!', `MaleText_loc7`='¡Esta chusma de no-muertos y su reina elfa muerta morirán!' WHERE `ID`=531;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은빛소나무 숲에서 적을 몰아낸 다음 적들의 수도에 총공격을 감행한다!', `MaleText_loc4`='我们要把敌人驱赶出银松森林，把战火烧到他们的首都！', `MaleText_loc5`='我們要把敵人驅趕出銀松森林，把戰火燒到他們的首都!', `MaleText_loc7`='¡Sacaremos a nuestros enemigos de Argénteos y luego haremos estallar la guerra en su propia capital!' WHERE `ID`=532;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음으로써 리치 왕을 찬양하라!', `MaleText_loc4`='为了巫妖王的荣耀而战！', `MaleText_loc5`='為了巫妖王的榮耀而戰!', `MaleText_loc7`='¡Muerte y alabanzas para el Rey Exánime!' WHERE `ID`=533;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='엘런드, 무사히 다시 보게 되니 반갑군요. 보고할 내용이 뭔가요?', `FemaleText_loc4`='埃兰德，很高兴又见到你。有什么要报告的？', `FemaleText_loc5`='埃蘭德，很高興又見到你。有什麼要報告的?', `FemaleText_loc7`='Me alegro de volver a verte, Erland. ¿Cuál es tu informe?' WHERE `ID`=534;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동쪽에 늑대 무리가 출몰하여 말덴의 과수원에 살던 이들이 모두 당했소.', `MaleText_loc4`='大量的狼都在往东边迁徙，而住在玛尔丁果园里的人也都跑光了。', `MaleText_loc5`='東邊有一大群的狼，而住在瑪爾丁果園裡的人都不見了。', `MaleText_loc7`='Hay masas de lobos en el Este, y quienquiera que viviera en la Huerta de Malden se ha ido.' WHERE `ID`=535;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='괜찮다면 퀸이 무사한지 좀 확인해 보고 싶은데...', `MaleText_loc4`='如果你没事的话，我要去看看奎恩……', `MaleText_loc5`='如果你沒事的話，我要去看看奎恩...', `MaleText_loc7`='Si se me permite, me gustaría ver a Quinn...' WHERE `ID`=536;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑네, 퀸. 어떻게 지내는가?', `MaleText_loc4`='你好，奎恩。你的伤势怎么样了？', `MaleText_loc5`='你好，奎恩。你的傷勢怎麼樣了?', `MaleText_loc7`='Hola, Quinn. ¿Qué tal te va?' WHERE `ID`=537;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='몸조심하는 게 좋을 걸세, 퀸. 이번엔 운이 좋았던 거야.', `MaleText_loc4`='好好保重，奎恩。这次你真的很幸运。', `MaleText_loc5`='好好保重，奎恩。這次你真的很幸運。', `MaleText_loc7`='Intenta tener más cuidado, Quinn. Esta vez has tenido suerte.' WHERE `ID`=538;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 나아지고 있네. 포악한 이바르한테 지다니...', `MaleText_loc4`='我好一些了。但伊瓦这个笨蛋过得比我还好……', `MaleText_loc5`='我好多了。邪惡的伊瓦打敗了我...', `MaleText_loc7`='He tenido momentos mejores. Ivar el Hediondo sacó lo mejor de mí...' WHERE `ID`=539;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하찮은 배신자 따위가 아이언밴드에 갈 화약을 막을 수는 없다!', `MaleText_loc4`='那些叛徒是不可能阻止我把炸药运到铁环挖掘场的！', `MaleText_loc5`='那些沒用的叛徒是阻止不了我把炸藥運到鐵環挖掘場的!', `MaleText_loc7`='¡Ningún traidor de pacotilla impedirá que el polvo llegue a Vetaferro!' WHERE `ID`=540;
