UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 저주받았어! 처음엔 배가 가라앉고, 이젠... 벌꿀술이 떨어져 버리다니!', `MaleText_loc4`='我真倒霉！先是船沉了，现在……又没酒喝了！', `MaleText_loc5`='我真倒楣!先是船沉了，現在...又沒酒喝了!', `MaleText_loc7`='¡Estoy maldito! Primero se hunde mi barco y ahora... ¡se termina el hidromiel!' WHERE `ID`=552;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 빌어먹을 할린도르! 당신이 우릴 죽음으로 내몰았어!', `MaleText_loc4`='哈林多尔，我诅咒你！你把厄运带给了我们！', `MaleText_loc5`='哈林多爾，我詛咒你!你會害死我們!', `MaleText_loc7`='¡Maldito seas, Halyndor! ¡Nos has llevado a la ruina!' WHERE `ID`=553;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 냄새에 신경 쓰지 말라고... 나한테서는 아무 냄새도 안 나니까!', `MaleText_loc4`='别介意我的气味……连我自己都不介意！', `MaleText_loc5`='別介意我的氣味...我自己是不介意的!', `MaleText_loc7`='¡No os preocupéis por mí, ni por mi olor... ya que a mí desde luego me da igual!' WHERE `ID`=554;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이언포지에서 최고의 벌꿀술이 있는 곳... 아, 아름다운 메네실 항구.', `MaleText_loc4`='啊，美丽的米奈希尔港，还有铁炉堡这边最好的蜂蜜酒！', `MaleText_loc5`='啊，美麗的米奈希爾港，還有鐵爐堡以北最好的蜜酒!', `MaleText_loc7`='Ah, bello puerto de Menethil, donde se consigue el mejor hidromiel a este lado de Forjaz.' WHERE `ID`=556;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 내 형제들이여! 저 물속의 무덤에서 편안히 잠들기를!', `MaleText_loc4`='唉，我的弟兄们！希望你们能够在潮湿的坟墓中得到安息！', `MaleText_loc5`='唉，我的弟兄們!希望你們能夠安息於水中!', `MaleText_loc7`='¡Oh, hermanos míos! ¡Encuentren la paz en sus tumbas marinas!' WHERE `ID`=557;
