UPDATE `locales_broadcast_text` SET `MaleText_loc1`='화약을 운반하는 일은 정말 위험한 일이야!$B$B미란은 방금 물건을 전달하러 갔으니 몇 분 후에 돌아올 걸세.', `MaleText_loc4`='这真是危险的营生！$B$B米兰刚刚去送东西了，他应该会马上回来。', `MaleText_loc5`='這真是危險的工作!$B$B米蘭剛剛去送東西了，他應該會馬上回來。', `MaleText_loc7`='¡Este negocio sí que es peligroso!$B$BMiran se acaba de ir con una entrega. Estará de vuelta en unos minutos.' WHERE `ID`=566;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 날 만만하게 봤던 게지. 하하!', `MaleText_loc4`='他们居然认为我很弱小。哈哈！！', `MaleText_loc5`='他們居然認為我很弱小。哈哈!!', `MaleText_loc7`='Se creían que yo era débil. ¡Ja, ja!' WHERE `ID`=567;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 바로 가장이란 말이다. 나, 내가 말이야!', `MaleText_loc4`='我才是家族的首领。是我，是我！！', `MaleText_loc5`='我才是家族的首領。是我，是我!!', `MaleText_loc7`='Yo soy el cabeza de familia. Yo. ¡¡¡YO!!!' WHERE `ID`=568;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님, 너무 춥습니다. 약속은 언제 지키실 겁니까?', `MaleText_loc4`='我很冷，大人。你什么时候才能兑现你的诺言？', `MaleText_loc5`='我很冷，大人。你什麼時候才能兌現你的諾言?', `MaleText_loc7`='Tengo frío, señor. ¿Cuándo cumplirás tu promesa?' WHERE `ID`=569;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가족들이 날 미워해. 전부 겁먹은 바보들이라고!', `MaleText_loc4`='我的家族非常恨我。胆小的白痴，他们都是胆小的白痴！', `MaleText_loc5`='我的家族非常恨我。膽小的白癡，他們都是膽小的白癡!', `MaleText_loc7`='Mi familia me odia. ¡Son todos unos cobardes, todos ellos!' WHERE `ID`=570;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아버지? 이제 제가 자랑스러우십니까? 하하!', `MaleText_loc4`='父亲？你现在为我感到骄傲了？哈哈！', `MaleText_loc5`='父親?你現在為我感到驕傲了?哈哈!', `MaleText_loc7`='¿Padre? ¿Ahora sí estás orgulloso de mí? ¡JA, JA!' WHERE `ID`=571;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어머니. 아, 내 어머니. 제 말을 들으셔야 했어요.', `MaleText_loc4`='妈妈，哦，妈妈。你早就应该听我的话……', `MaleText_loc5`='媽媽，哦，媽媽。你早就應該聽我的話...', `MaleText_loc7`='Madre mía... Tenías que haberme escuchado...' WHERE `ID`=572;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 동생 투르만... 결국 마지막 웃는 자는 누구지? 하!', `MaleText_loc4`='萨尔曼，我的兄弟，看看谁笑到了最后？哈哈哈哈！', `MaleText_loc5`='薩爾曼，我的兄弟，看看誰笑到了最後?哈哈哈哈!', `MaleText_loc7`='Thurman, hermano, ¿quién ríe ahora? ¡Ja!' WHERE `ID`=573;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 가족을 만나러 왔다고? 죽어라, 이 바보 같은 녀석!', `MaleText_loc4`='你是来这里拜访我的家族的吗？去死吧，蠢货！', `MaleText_loc5`='你是來這裡拜訪我的家族的嗎?去死吧，蠢貨!', `MaleText_loc7`='¿Vienes a ver a la familia? ¡Muere, idiota!' WHERE `ID`=574;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아가만드 제분소가 스컬지의 수중에 있다. $C, 우리와 함께 싸우자!', `MaleText_loc4`='阿加曼德磨坊由亡灵天灾控制着，$C。加入我们吧！', `MaleText_loc5`='阿加曼德磨坊由天譴軍團控制著，$C。加入我們吧!', `MaleText_loc7`='Los Molinos de Agamand están en manos de la Plaga, $c. ¡Únete a nosotros!' WHERE `ID`=575;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 이 잔을 들어 너희 족속들을 모두 없어지게 해 달라고 빌겠다! 자, 건배다! $n, 이 형편없는 악당!', `MaleText_loc4`='让我们为了你这种家伙早点死掉而干杯！为了你这个恶棍，$n！', `MaleText_loc5`='讓我們為了你這種傢伙早點死掉而乾杯!為了你這個惡棍，$n!', `MaleText_loc7`='¡Levanto mi cerveza y espero librarme de ti y tus semejantes! ¡Adiós, no eres más que $gun:una; miserable, $n!' WHERE `ID`=576;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 건배를 외칩니다!', `MaleText_loc4`='%s举杯祝酒！', `MaleText_loc5`='%s歡呼乾杯 !', `MaleText_loc7`='¡%s se pone a animar a la peña!' WHERE `ID`=577;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='물러서. 이 고약한 짐승아!', `FemaleText_loc4`='滚开，可恶的东西！', `FemaleText_loc5`='滾開，可惡的東西!', `FemaleText_loc7`='¡Atrás, viles criaturas!' WHERE `ID`=578;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='개굴!', `MaleText_loc4`='呱呱！', `MaleText_loc5`='呱呱!', `MaleText_loc7`='¡Cruac!' WHERE `ID`=579;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 비약의 냄새를 맡고는 게걸스럽게 먹습니다!', `MaleText_loc4`='%s嗅到了药剂的气味，兴奋地把它喝了下去。', `MaleText_loc5`='%s聞了聞藥劑便急切地打開藥水瓶!', `MaleText_loc7`='¡%s olfatea el elixir y luego lo apura con avidez!' WHERE `ID`=580;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마침내 자비를 베푸는군! 우리에게 마실 걸 주다니!', `MaleText_loc4`='最后他们终于表现出一丝仁慈！他们给了我一些喝的东西！', `MaleText_loc5`='他們總算表現出一絲仁慈!給了我們一些喝的東西!', `MaleText_loc7`='¡Finalmente muestran misericordia! ¡Nos han dado algo de beber!' WHERE `ID`=581;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='게다가 신디거 스타우트 맥주라니! 신이시여! 얼마나 목이 말랐었는지...', `MaleText_loc4`='还有美酒！感谢圣光！我几乎都要被烤干了！', `MaleText_loc5`='還有礦工烈酒!感謝聖光!我快要渴死了!', `MaleText_loc7`='¡Y cerveza negra Machacacanillas también! ¡Gracias a la Luz! ¡Tenía la garganta reseca!' WHERE `ID`=582;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언데드가 된다는 건 삶의 끝이 아니라 시작이지요. 이제 당신의 운명은 당신의 선택에 달렸습니다.', `MaleText_loc4`='这并不是你生命的结束，而是新的开始。现在是由你来决定自己命运的时候了。', `MaleText_loc5`='這並不是你生命的結束，而是新的開始。現在是由你來決定自己命運的時候了。', `MaleText_loc7`='Tu no muerte no es el final de tu vida sino el comienzo. Está en nuestras manos decidir dónde se encuentra ahora tu destino.' WHERE `ID`=583;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 당신은 리치 왕의 통제에서 벗어났습니다. 하등한 존재들에게 심판을 받겠지만, 적어도 스컬지들이 가지지 못한 기회를 얻은 것이지요.', `MaleText_loc4`='你摆脱了他的控制。虽然你会被一些低贱的生物指责，但你至少有亡灵天灾所没有的机会。', `MaleText_loc5`='你擺脫了他的控制。雖然你會被一些低賤的生物指責，但你至少有天譴軍團所沒有的機會。', `MaleText_loc7`='Estás libre de su control. ¡Y mientras seas juzgado por seres inferiores, al menos tendrás posibilidades de que la Plaga no lo haga!' WHERE `ID`=584;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공포, 암흑, 힘? 포세이큰은 이런 것들을 갈망하지 않습니다. 바로 포세이큰이 바로 공포, 암흑, 힘 그 자체니까 말입니다.', `MaleText_loc4`='恐惧，黑暗，还有力量？被遗忘者并不渴望这些东西，被遗忘者就是这些东西。', `MaleText_loc5`='恐懼，黑暗，還有力量?被遺忘者並不渴望這些東西，被遺忘者就是這些東西。', `MaleText_loc7`='¿Terror, oscuridad, poder? Los Renegados no ansían todo eso; los Renegados SON todo eso.' WHERE `ID`=585;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 뼈는 약하고, 눈은 암흑만을 볼 뿐이며, 몸은 고통만을 느낄 뿐이지요. 하지만 이런 것들은 중요하지 않답니다. 적어도 내 의지대로 살아갈 수 있으니까요.', `MaleText_loc4`='我的骨骼十分虚弱，我的双眼只能看到黑暗，我的身体只能感受到痛楚……但这一切都算不了什么，因为我的意志还是我的。', `MaleText_loc5`='我的骨骼變得脆弱，我的雙眼只能看到黑暗，我的身體只能感受到痛楚...但這一切都算不了什麼，因為我的意志還是我的。', `MaleText_loc7`='Mis huesos son débiles, mis ojos solo ven oscuridad y mi cuerpo solo siente el dolor, pero todo eso es bueno, porque mi voluntad me pertenece.' WHERE `ID`=586;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='반가워요, 차리스. 목록은 여기 있어요. 여기 적힌 걸 모두 구해 준다면 고맙겠는데... 특히 마지막 재료가 구하기 쉽지 않을 거 같아요.', `FemaleText_loc4`='你好，查瑞斯。这是我需要的货单，你能帮我弄到这些东西吗？尤其是最后一种材料。', `FemaleText_loc5`='你好，查瑞斯。這是我的貨單，你能幫我弄到這些東西嗎?尤其是最後一種材料。', `FemaleText_loc7`='Hola, Charys. He hecho una lista. ¿Podrías conseguirme todo esto, especialmente el último ingrediente?' WHERE `ID`=587;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='엄마? 삑삑이 키워도 되나요?', `FemaleText_loc4`='妈妈，我能养菲尔吗？', `FemaleText_loc5`='媽媽，我能拍拍菲爾嗎?', `FemaleText_loc7`='¿Mami? ¿Puedo acariciar a Fizzles?' WHERE `ID`=588;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그러렴, 아가야. 대신 잘 보살펴야 한다.', `FemaleText_loc4`='当然，派格。记得要表现得绅士一点。', `FemaleText_loc5`='當然，派格。但是要溫柔一點。', `FemaleText_loc7`='Claro, Paige. Pero hazlo con cuidado.' WHERE `ID`=589;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고마워요, 차리스. 페이지, 이리 오렴, 사랑스러운 내 딸.', `FemaleText_loc4`='谢谢你，查瑞斯。派格，小甜心，快过来。', `FemaleText_loc5`='謝謝你，查瑞斯。派格，小甜心，我們走了。', `FemaleText_loc7`='Gracias, Charys. Vamos, Paige, cariño.' WHERE `ID`=590;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 고대 언어를 읊기 시작하며 사악한 존재를 불러냅니다.', `MaleText_loc4`='%s用古老的语言开始吟唱魔法，召唤某种邪恶的东西。', `MaleText_loc5`='%s用古老的語言開始吟唱魔法，召喚某種極端邪惡的東西。', `MaleText_loc7`='%s empieza a cantar en una lengua antigua, invocando fuerzas malignas de la naturaleza.' WHERE `ID`=591;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 속박에서 자유로워지다니 정말 기쁘군! 토그타르는 아직 풀어 주지 않았소? 인간들은 우리를 서로 다른 곳에 가둬 놨소.', `MaleText_loc4`='哈，自由了，感觉真好！托格萨也被救出来了吗？在我们被俘后，人类就把我们给分开关押了。', `MaleText_loc5`='哈，自由了，感覺真好!托格薩也被救出來了嗎?在我們被俘後，人類就把我們給分開關押了。', `MaleText_loc7`='¡Ah, qué bien que estoy sin mis ataduras! ¿Ya liberaste a Tog''thar? Los humanos nos separaron después de capturarnos.' WHERE `ID`=592;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드럴은 아직 풀어 주지 않았소? 그가 어디에 갇혀 있는지는 나도 잘 모르오.', `MaleText_loc4`='你救出德鲁尔了吗？我不知道他被关在什么地方。', `MaleText_loc5`='你救出德盧爾了嗎??不知道他被關在什麼地方。', `MaleText_loc7`='¿Ya liberaste a Drull? No sé dónde le han retenido.' WHERE `ID`=593;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 그냥 두고 먼저 가시오! 난 내 힘으로 타렌 제분소까지 갈 수 있을 것이오.', `MaleText_loc4`='别管我，赶快去！我会自己走到塔伦米尔的。', `MaleText_loc5`='別管我，趕快去!我會自己走到塔倫米爾的。', `MaleText_loc7`='¡Seguid sin mí! Yo iré por mi propia cuenta al Molino Tarren.' WHERE `ID`=594;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 당신의 임무에 걸림돌이 될 지도 모르오. 난 저 분홍빛 인간들에게 잡히진 않을 것이니 걱정하지 말고 어서 가시오!', `MaleText_loc4`='粉皮肤的人类也许可以夺走我的生命，但他们不能夺走我的自由！', `MaleText_loc5`='我只會拖慢你的速度。但是那些粉紅皮膚的人類是奪不走我的自由的!', `MaleText_loc7`='Haré que vayáis más lentos, ¡pero ningún humano de piel rosada me privará de libertad!' WHERE `ID`=595;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 잔해들을 뒤져 봐라.', `MaleText_loc4`='在这块碎石下搜索。', `MaleText_loc5`='在這塊碎石下搜索。', `MaleText_loc7`='Buscad en estos escombros.' WHERE `ID`=596;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭔가 값어치 있는 걸 찾으란 말이다!', `MaleText_loc4`='给我找点吃的来，你们这些废物！', `MaleText_loc5`='給我找點好東西來，你們這些廢物!', `MaleText_loc7`='¡Encontrad algo, perros!' WHERE `ID`=597;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여길세! 방 안에 있네. 족쇄를 풀 열쇠는 찾았나? 열쇠는 볼후인이라는 인간에게 있네.', `MaleText_loc4`='在那里！在那间屋子里。你找到钥匙了吗？就在那个叫博胡恩的人类那里。', `MaleText_loc5`='在那裡!在那間屋子裡。你找到鑰匙了嗎?就在那個叫博胡恩的人類那裡。', `MaleText_loc7`='¡Por aquí! En la habitación. ¿Has encontrado la llave para soltar mis cadenas? El humano Borhuin tiene las llaves.' WHERE `ID`=598;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 복수를 위해 무덤에서 돌아왔다!', `MaleText_loc4`='我从墓地里爬出来的唯一目的就是复仇！', `MaleText_loc5`='我從墳墓裡爬出來就是為了要復仇!', `MaleText_loc7`='¡He vuelto de la tumba para consumar mi venganza!' WHERE `ID`=599;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠의 여왕님의 이름으로 너를 처단하겠다, $n.', `MaleText_loc4`='以黑暗女王的名义，你去死吧，$n！', `MaleText_loc5`='以黑暗女王的名義，你去死吧，$n!', `MaleText_loc7`='Muere en nombre de la Dama Oscura, $n.' WHERE `ID`=600;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언데드들이 네 영혼으로 잔치를 벌일 것이다, $n.', `MaleText_loc4`='亡灵将会以你的灵魂为食，$n。', `MaleText_loc5`='亡靈將會以你的靈魂為食，$n。', `MaleText_loc7`='Los no-muertos se darán un festín con tu alma, $n.' WHERE `ID`=601;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 부활했도다!', `MaleText_loc4`='我重生了！', `MaleText_loc5`='我重生了!', `MaleText_loc7`='¡Estoy en pie otra vez!' WHERE `ID`=602;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 복수를 하게 되었구나!', `MaleText_loc4`='我终于可以复仇了！', `MaleText_loc5`='我終於可以復仇了!', `MaleText_loc7`='¡La venganza será mía al fin!' WHERE `ID`=603;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='남녘해안은 피의 대가를 치를 것이다!', `MaleText_loc4`='南海镇将会付出血的代价！', `MaleText_loc5`='南海鎮將會付出血的代價!', `MaleText_loc7`='¡Costasur lo pagará con sangre!' WHERE `ID`=604;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음... 난 남녘해안 스타우트 맥주가 정말 좋아.', `MaleText_loc4`='嗯……我喜欢南海镇的美酒。', `MaleText_loc5`='嗯...我喜歡南海鎮的美酒。', `MaleText_loc7`='Mmm... Adoro la deliciosa cerveza de Costasur.' WHERE `ID`=605;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='남녘해안 스타우트 맥주를 얼마나 좋아하느냐고? 뭐라 해야 할까...', `MaleText_loc4`='你知道我多么喜欢南海镇的美酒吗？让我告诉你……', `MaleText_loc5`='你知道我多麼喜歡南海鎮的美酒嗎?讓我告訴你...', `MaleText_loc7`='Cerveza de Costasur, ¿de cuántas maneras te quiero? Déjame contarlas...' WHERE `ID`=606;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 수를 써서라도 본즈 현장감독을 보호하라!', `MaleText_loc4`='不惜一切代价，保护工头邦德斯！', `MaleText_loc5`='不惜一切代價，保護工頭邦德斯!', `MaleText_loc7`='¡Proteged al supervisor Bonds a toda costa!' WHERE `ID`=608;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경비병! 경비병!', `MaleText_loc4`='卫兵！卫兵！', `MaleText_loc5`='守衛!守衛!', `MaleText_loc7`='¡Guardias! ¡Guardias!' WHERE `ID`=609;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈들은 무례한 행동의 대가를 치를 것이다! 경비병!', `MaleText_loc4`='你要为此付出代价！来人啊!', `MaleText_loc5`='你要為此付出代價!來人啊!', `MaleText_loc7`='¡Vais a pagar por esta atrocidad! ¡Guardias!' WHERE `ID`=610;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 위치로! 어떠한 침략자도 남녘해안에 발을 들여놓지 못하게 하라!', `MaleText_loc4`='各就各位！不要让敌人进入南海镇！', `MaleText_loc5`='各就各位!不要讓敵人進入南海鎮!', `MaleText_loc7`='¡A sus puestos! ¡Que ningún invasor llegue a Costasur!' WHERE `ID`=611;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수상한 자는 즉시 처치하시오. 모두 신속히 제 위치로 돌아가야 하오!', `MaleText_loc4`='任何可疑的人都要迅速拿下。各就各位！', `MaleText_loc5`='任何可疑的人都要迅速拿下。各就各位!', `MaleText_loc7`='Capturar rápidamente a cualquier sospechoso. ¡A sus puestos cuanto antes!' WHERE `ID`=612;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 수를 써서라도 집정관님을 보호하시오. 놈들은 사방에서 달려들고 있소이다!', `MaleText_loc4`='全力保卫镇长！敌人可能会从任何一个方向突入！', `MaleText_loc5`='全力保衛鎮長!敵人可能會從任何一個方向突入!', `MaleText_loc7`='¡Proteged al magistrado a toda costa! ¡Podrían venir desde cualquier dirección!' WHERE `ID`=613;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 나무들... 모두 나처럼 말라죽어 버렸소.', `MaleText_loc4`='我的树……它们正在枯萎而死，就像我一样。', `MaleText_loc5`='我的樹...它們都枯萎死掉了，就像我一樣。', `MaleText_loc7`='Mis árboles... se han marchitado, al igual que yo.' WHERE `ID`=614;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 과수원은 썩어가는 내 모습처럼 메말라 생명을 잃었소. 한때 이 나무들에는 싱싱한 과일이 열렸지만 지금은 온통 썩은 것뿐이오.', `MaleText_loc4`='这座果园现在死气沉沉。这些树木曾经结满了果实，但是现在只剩下干枯的树枝。', `MaleText_loc5`='這座果園現在死氣沉沉，荒寂空盪有如我腐爛的軀殼一樣。這些樹木曾經結滿了果實，但是現在只剩下乾枯的樹枝。', `MaleText_loc7`='Este huerto está ahora tan yermo y triste como mi caparazón en descomposición. En otros tiempos, estos árboles estaban cargados de frutos, pero ahora solo hay podredumbre.' WHERE `ID`=615;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 이 나무들을 돌보는 데 일생을 바쳤소. 가지를 치고 비료를 주고... 이제 죽음까지 나와 함께하니 정말 잘 어울리지 않소?', `MaleText_loc4`='我耗尽毕生心血去照看这些树木，修剪它们，养育它们……能让它们给我陪葬也不错。', `MaleText_loc5`='我花費了我的一生去照看這些樹木，修剪它們，養育它們...所以它們如今也得繼續陪伴著我。', `MaleText_loc7`='Dediqué toda mi vida a cuidar de estos árboles. Podándolos y cuidándolos... preparándolos para que me hiciesen compañía en mi muerte.' WHERE `ID`=616;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='', `MaleText_loc4`='', `MaleText_loc5`='', `MaleText_loc7`='' WHERE `ID`=617;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하시오, 여러분! 곧 대세가 우리 쪽으로 기울어 이 재앙도 끝이 날 것이오!', `MaleText_loc4`='干得好！形势在朝对我们有利的方向发展，苦难终将结束！', `MaleText_loc5`='幹得好!形勢在朝對我們有利的方向發展，瘟疫終將結束!', `MaleText_loc7`='¡Saludos, ciudadanos! Quizás muy pronto la marea ondeará en nuestro favor y la Peste terminará.' WHERE `ID`=618;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와줘! 도와줘! 언덕에 암살자가 있다! 전투 준비! 전투 준비!', `MaleText_loc4`='救命啊！山上有刺客！帮帮我！帮帮我！', `MaleText_loc5`='救命啊!山上有刺客!拿武器!抄傢伙!', `MaleText_loc7`='¡Socorro! ¡Socorro! ¡Hay asesinos en las colinas! ¡Coged las armas! ¡Coged las armas!' WHERE `ID`=619;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 들으시오! 모두 들으시오! *헉헉* 남녘해안 주민은 귀를 기울이시오. 암살자들이 우리의 평화로운 마을을 향해 오고 있소!', `MaleText_loc4`='注意啦！注意啦！*喘息声*南海镇的居民们，有许多刺客正在向我们这里进发！', `MaleText_loc5`='注意啦!注意啦!*喘息聲*南海鎮的居民們，有許多刺客正在向我們這裡進發!', `MaleText_loc7`='¡Os oigo! ¡Os oigo! *jadeos* Estad alerta, ciudadanos de Costasur: ¡los asesinos vienen hacia nuestro pacífico poblado!' WHERE `ID`=620;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 위치를 사수하라! 놈들은 다시 집정관을 노릴 것이다. 집정관을 반드시 보호해야 한다! 놈들은 사방에서 달려들 것이다!', `MaleText_loc4`='坚守阵地！他们一定又是想要刺杀镇长，我们一定要保护他！刺客可能从任何方向发起攻击！', `MaleText_loc5`='堅守陣地!他們一定又是想要刺殺鎮長，我們一定要保護他!刺客可能從任何方向發起攻擊!', `MaleText_loc7`='¡Guardias, a sus puestos! Seguro que otra vez vienen a por el magistrado. ¡Hay que protegerlo! ¡Podrían venir desde cualquier dirección!' WHERE `ID`=621;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 지쳤어. *헉헉*', `MaleText_loc4`='累死我了……*喘气声*', `MaleText_loc5`='累死我了...*喘氣聲*', `MaleText_loc7`='Estoy agotado *jadeos*' WHERE `ID`=622;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='남녘해안 포고꾼이 자신의 목덜미를 잡고 눈이 크게 휘둥그레집니다.', `MaleText_loc4`='南海镇公告员挠着后脑勺，瞪圆了双眼。', `MaleText_loc5`='南海鎮公告員摸著他的後頸，眼睛睜得大大的。', `MaleText_loc7`='El pregonero de Costasur se lleva la mano a la nuca, con los ojos muy abiertos.' WHERE `ID`=623;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='암살자들... 집정관님을... 지...켜...', `MaleText_loc4`='有刺客……去救……镇长……', `MaleText_loc5`='有刺客...去救...鎮長...', `MaleText_loc7`='Asesinos... salvad al... Magistraaa...' WHERE `ID`=626;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 여기 있습니다! 놈들이 이쪽에 있어요! 도와주세요!', `MaleText_loc4`='他们在这里！他们过来了！救命啊！', `MaleText_loc5`='他們在這裡!他們過來了!救命啊!', `MaleText_loc7`='¡Están aquí! ¡Aquí están! ¡Socorro!' WHERE `ID`=627;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='암살자들이 여기 있습니다! 집정관님을 해하기 전에 서둘러 놈들을 막아주세요!', `MaleText_loc4`='刺客来了！快点阻止他们，在他们找到镇长之前干掉他们！', `MaleText_loc5`='刺客來了!快點阻止他們，在他們找到鎮長之前幹掉他們!', `MaleText_loc7`='¡Los asesinos están aquí! ¡Rápido, antes de que encuentren al magistrado!' WHERE `ID`=628;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아마도 비밀결사대의 다른 대원들일 걸! 넌 절대 알터랙이나 남녘해안으로 돌아가지 못해!', `MaleText_loc4`='我敢打赌还会有更多辛迪加的刺客跑来送死！你们永远也不可能得到奥特兰克和南海镇！', `MaleText_loc5`='我敢說，一定又是辛迪加的刺客跑來送死!你們永遠也不可能搶走奧特蘭克和南海鎮!', `MaleText_loc7`='¡Apuesto a que hay más agentes de la Hermandad! ¡Nunca recuperaréis Alterac... o Costasur!' WHERE `ID`=629;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='임무를 완수했다! 집정관을 사살했다. 동지들이여, 모두 어둠 속에 몸을 숨겨라.', `MaleText_loc4`='成功了！镇长已经被干掉了！弟兄们，撤退！', `MaleText_loc5`='成功了!鎮長已經被幹掉了!弟兄們，撤退!', `MaleText_loc7`='¡Lo han hecho! El magistrado está muerto. Id a las tinieblas, mis hermanos.' WHERE `ID`=630;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='집정관을 처치했다! 모두 퇴각하라, 형제들이여.', `MaleText_loc4`='镇长已经死了！快撤，弟兄们！', `MaleText_loc5`='鎮長已經死了!快撤，弟兄們!', `MaleText_loc7`='¡El Magistrado ha caído! Escapad, hermanos.' WHERE `ID`=631;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하! 집정관을 처치했으니 알터랙과 언덕마루는 다시 우리의 손에 들어올 것이다. 철수하라!', `MaleText_loc4`='哈哈！奥特兰和希尔斯布莱德将再次被我们捏在手心里，镇长已经死了，撤退！', `MaleText_loc5`='哈哈!鎮長已經死了，奧特蘭克和希爾斯布萊德將再度落入我們的統治!撤退!', `MaleText_loc7`='¡Ja, ja! Alterac y Trabalomas volverá a someterse a nuestro legítimo gobierno ahora que el magistrado ha caído. ¡Batíos en retirada!' WHERE `ID`=632;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저자들은 우리 일을 방해한 대가를 반드시 치르게 될 것이다. 어둠 속으로 철수하라!', `MaleText_loc4`='这就是多管闲事的下场！撤退！', `MaleText_loc5`='給我小心點，多管閒事傢伙!撤退，兄弟們!', `MaleText_loc7`='Los entrometidos deberán pagar por su injerencia. ¡Replegaos a las tinieblas!' WHERE `ID`=633;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='집정관에 대한 경호가 너무 삼엄하다. 철수!', `MaleText_loc4`='镇长身边戒备森严，撤退！', `MaleText_loc5`='鎮長身邊戒備森嚴，撤退!', `MaleText_loc7`='El magistrado está más que protegido. ¡Replegaos!' WHERE `ID`=634;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번에는 우리를 막을 수 있었을지 모르지만, 우리는 곧 반드시 돌아올 것이다!', `MaleText_loc4`='虽然你们这次成功地阻止了我们，但我们还会回来的——走着瞧吧！', `MaleText_loc5`='雖然你們這次成功地阻止了我們，但我們還會回來的!走著瞧吧!', `MaleText_loc7`='Quizás nos hayas podido detener esta vez, pero volveremos, ¡tenlo por seguro!' WHERE `ID`=635;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 녹색의 액체가 든 병을 하나 꺼내들고 단숨에 마십니다.', `FemaleText_loc4`='%s取出一只盛着绿色液体的瓶子，喝了一大口。', `FemaleText_loc5`='%s取出裝著奇怪的綠色液體的瓶子，然後喝了一大口。', `FemaleText_loc7`='%s saca una botella llena de un líquido de color verde y le da un buen trago.' WHERE `ID`=636;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 다이너마이트에 불을 붙이자 눈이 붉게 빛나며 미친 듯이 웃기 시작합니다.', `MaleText_loc4`='%s的眼睛变得通红，他狂笑着点燃了炸药！', `MaleText_loc5`='%s的眼睛變得通紅，一邊狂笑一邊點燃了火藥!', `MaleText_loc7`='¡Los ojos de %s brillan como rubíes al tiempo que enciende la dinamita y empieza a reír malévolamente!' WHERE `ID`=637;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우헤헤! 저승 가는 길동무로 삼겠다!', `MaleText_loc4`='哇哈哈哈哈哈！我要和你同归于尽！', `MaleText_loc5`='哇哈哈哈哈哈!我要和你同歸於盡!', `MaleText_loc7`='¡Ji, ji, ji! ¡Os venís conmigo!' WHERE `ID`=638;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 이 게으름뱅이들, 이제 일어나서 일할 시간이다. 다리가 저절로 건설되지는 않는단 말이다.', `MaleText_loc4`='好了，你们这些懒虫，该起床干活了。桥是不会自己造好的。', `MaleText_loc5`='好了，你們這些懶蟲，該起床幹活了。橋是不會自己造好的。', `MaleText_loc7`='¡Vamos, vamos, vaguetes, es hora de levantarse y empezar a trabajar! El puente no se va a construir solo.' WHERE `ID`=639;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자자, 어서 잠을 깨고 서둘러 일을 시작하라고.', `MaleText_loc4`='你得花几分钟时间才能起床，但是我们马上就要出发了。', `MaleText_loc5`='給你們幾分鐘賴床刷牙洗臉上廁所。動作快，我們馬上就要出發了。', `MaleText_loc7`='Tenéis unos cuantos minutos para despertar, pero pongámonos en marcha cuanto antes.' WHERE `ID`=640;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='후하, 후하, 숨 한번 크게 쉬고... 얼른 일어나 일을 시작하자고.', `MaleText_loc4`='嗨呦，嗨呦……加油干啊！', `MaleText_loc5`='嗨呦，嗨呦...加油幹啊!', `MaleText_loc7`='Un-dos, un-dos, ¡arriba!' WHERE `ID`=641;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자자, 쉬었다 하자고! 30분 휴식한 후에 다시 일을 시작하도록.', `MaleText_loc4`='休息一下，伙计们！休息半小时后回去工作。', `MaleText_loc5`='休息一下，夥計們!休息半小時後回去工作。', `MaleText_loc7`='¡Daos un respiro, tíos! Media hora y luego de vuelta al trabajo.' WHERE `ID`=642;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 훌륭한 다리야. 자, 이 속도로 계속 작업하면 첫 번째 점령군이 북쪽으로 진격할 수 있도록 때를 맞춰 완성될 거야.', `MaleText_loc4`='进度不错。只要我们继续保持现在的速度，那么第一支北上的军队就可以顺利通过它了！', `MaleText_loc5`='進度不錯。只要我們繼續保持現在的速度，那麼第一支北上的軍隊就可以順利通過它了!', `MaleText_loc7`='El puente tiene un aspecto excelente. Si mantenemos este ritmo, estará terminado para que las primeras fuerzas de expansión puedan dirigirse hacia el norte.' WHERE `ID`=643;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 점심 시간은 끝났다. 다시 일을 시작하자고. 오늘 남은 시간도 이렇게 순조롭게만 진행된다면 공사 기간을 단축할 수 있을 거야.', `MaleText_loc4`='好了，午饭时间结束了，伙计们。开始干活吧。如果今天接下来一切顺利的话，那么我们就可以早点收工。', `MaleText_loc5`='好了，午飯時間結束了，夥計們。開始幹活吧。如果今天接下來一切順利的話，那麼我們就可以早點收工。', `MaleText_loc7`='Vale, fin del descanso para comer, señores. Volvamos al trabajo. Si el resto del día marcha tan bien como hasta ahora, tal vez podremos acabar antes.' WHERE `ID`=645;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 좋아. 지금처럼만 계속하면 곧 다리가 완성될 거야.', `MaleText_loc4`='好，好。继续这么干，这座桥不久就会完工。', `MaleText_loc5`='好，好。繼續這麼幹，這座橋不久就會完工。', `MaleText_loc7`='Vale, vale. Manos a la obra y ese puente estará construido en un santiamén.' WHERE `ID`=646;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 오늘은 이만 끝내자고, 친구들!', `MaleText_loc4`='收工了，伙计们！', `MaleText_loc5`='收工了，夥計們!', `MaleText_loc7`='¡Dejadlo por hoy, muchachos!' WHERE `ID`=647;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날짜가 지연되고 있어. 어서 서두르자고.', `MaleText_loc4`='时间不早了，走吧。', `MaleText_loc5`='時間不早了，走吧。', `MaleText_loc7`='Se nos va el día. Vamos, vamos.' WHERE `ID`=648;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 다들 잘자고 푹 쉬라고.', `MaleText_loc4`='晚安，兄弟们。睡个好觉。', `MaleText_loc5`='晚安，兄弟們。睡個好覺。', `MaleText_loc7`='Buenas noches, caballeros. Felices sueños.' WHERE `ID`=649;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 잤나, 친구들.', `MaleText_loc4`='早安，我的朋友。', `MaleText_loc5`='朋友們，早安。', `MaleText_loc7`='Buenos días, amigos.' WHERE `ID`=650;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 배고파. 식사 시간이 다 됐군.', `MaleText_loc4`='啊……该吃饭了。', `MaleText_loc5`='啊...該吃飯了。', `MaleText_loc7`='Ahh... ya va siendo hora de ir a comer.' WHERE `ID`=651;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날씨가 참 좋지 않소? 이런 날 열심히 일하고 맛있는 음식을 먹으니... 이런 아름다운 날을 더 형편 없이 보낼 수도 있는데, 이 정도면 뭐...', `MaleText_loc4`='今天的天气真不错！努力地工作之后有丰盛的食物等着我们——在这么美好的一天，我们应该能做得更好！', `MaleText_loc5`='今天的天氣真不錯!努力地工作之後就有豐盛的食物等著我們。我們真的要心懷感激啊!', `MaleText_loc7`='Un buen día para disfrutar de la vida, ¿verdad? Trabajo duro y buena comida, en un día tan bonito podríamos estar haciendo cosas peores.' WHERE `ID`=652;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='*디미트리는 이마의 땀을 닦고 연장을 내려놓습니다.*', `MaleText_loc4`='*迪米特里放下工具，擦了擦前额的汗水*', `MaleText_loc5`='*迪米特里放下他的工具，擦了擦前額的汗水*', `MaleText_loc7`='*Dimitri se sacude el sudor de la frente y deja sus herramientas a un lado*' WHERE `ID`=654;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘도 날씨가 참 좋군.', `MaleText_loc4`='又是个好日子。', `MaleText_loc5`='又是個好日子。', `MaleText_loc7`='Ciertamente, la jornada ha sido muy buena.' WHERE `ID`=655;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 자라고, 친구들. 내일 보세나.', `MaleText_loc4`='晚安，我的朋友。明天见。', `MaleText_loc5`='晚安，朋友們。明天見。', `MaleText_loc7`='Buenas noches, amigos. Hasta mañana.' WHERE `ID`=656;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 조금만 더 자면 안 되나?', `MaleText_loc4`='我们就不能多睡一会儿吗？', `MaleText_loc5`='我們就不能多睡一會兒嗎?', `MaleText_loc7`='¿No podemos dormir un poco más?' WHERE `ID`=657;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 알았어... 일어난다고.', `MaleText_loc4`='好吧好吧……我起床了。', `MaleText_loc5`='好吧好吧...我起床了。', `MaleText_loc7`='Vale, vale... Me apunto.' WHERE `ID`=658;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='식사 시간이군. 한 시간 전부터 배가 고프던 참인데...', `MaleText_loc4`='差不多该吃饭了吧……我一个多小时前就饿了。', `MaleText_loc5`='差不多該吃飯了吧...我一個多小時前就餓了。', `MaleText_loc7`='''Ya va siendo hora. Tengo hambre desde hace una hora.' WHERE `ID`=659;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아 드디어 끝났군! 오늘 밤은 완전히 곯아떨어지겠는걸.', `MaleText_loc4`='终于可以躺下好好睡一觉了！', `MaleText_loc5`='終於可以躺下好好睡一覺了!', `MaleText_loc7`='¡Por fin! No puedo esperar a que se haga de noche para dormir un poco.' WHERE `ID`=660;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으! 하루종일 서서 일하는 직업은 할 만한 게 못돼. 재봉사나 될 걸 그랬어.', `MaleText_loc4`='啊！整日闲逛是没有前途的，我当年应该去学裁缝……', `MaleText_loc5`='啊!站著工作一整天實在是太累了，我當年應該去學裁縫的...', `MaleText_loc7`='¡Uf! Estar todo el día de pie no es una buena manera de ganarse el pan. Tenía que haber sido sastre.' WHERE `ID`=661;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 아침이 좋아. 정말 좋은 날이지 않나? 이 신선한 공기!', `MaleText_loc4`='我喜欢清晨！今天天气真好，不是吗？好好呼吸新鲜空气吧！', `MaleText_loc5`='我喜歡清晨!今天天氣真好，不是嗎?好好呼吸新鮮空氣吧!', `MaleText_loc7`='¡Me encantan las mañanas! Hace un día espléndido, ¿no crees? ¿Sientes el olor del aire?' WHERE `ID`=662;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘은 정말 허기지는걸. 다들 오늘 달시 봤나? 오늘 정말 예쁘더라고.', `MaleText_loc4`='以圣光的名义，我今天真的很饿。你们今天看到达希了吗？她看上去精神不错。', `MaleText_loc5`='以聖光之名，我今天真的很餓。你們今天看到達希了嗎?她看起來精神不錯。', `MaleText_loc7`='Por la Luz, hoy tengo mucha hambre. ¿Habéis visto a Darcy? Estaba muy guapa.' WHERE `ID`=664;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 다리는 우리 6명이 짓기에는 너무 커. 사람을 더 쓰는 게 어때?', `MaleText_loc4`='你知道，那座桥工程量很大，但只有我们六个人在工作。你应该雇用更多的工人来。', `MaleText_loc5`='你知道，那座橋其實還不小，但只有我們六個人在工作。你不覺得應該雇用更多的工人來嗎?', `MaleText_loc7`='Creo que este puente es demasiado grande como para que lo construyamos solo nosotros seis. Entonces crees que deberían contratar a más gente.' WHERE `ID`=665;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네들 달시 봤나? 보이질 않던데... 이 밤에 어딜 간 거지?', `MaleText_loc4`='你们看见达希了吗？我没看到她，不知道她今晚去哪里了。', `MaleText_loc5`='你們看見達希了嗎?我沒看到她，不知道她今晚去哪裡了。', `MaleText_loc7`='Chicos, ¿la veis? No he visto a Darcy. ¿Dónde estará esta noche?' WHERE `ID`=666;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 부두 위아래를 살핍니다.', `MaleText_loc4`='%s仔细搜查着码头。', `MaleText_loc5`='%s仔細打量著碼頭。', `MaleText_loc7`='%s echa varios vistazos por los muelles.' WHERE `ID`=667;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='글쎄, 좀 지나면 달시를 볼 수 있을 거야.', `MaleText_loc4`='哦，好吧，我相信她会回来的。', `MaleText_loc5`='哦，好吧，我相信她會回來的。', `MaleText_loc7`='Vaya, seguro que la veré por ahí más tarde.' WHERE `ID`=669;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다들 잘 자. 달시가 올지도 모르니까 난 좀 있다가 잘 거야.', `MaleText_loc4`='诸位，晚上好。我要在这里坐一会。达希可能会过来的。', `MaleText_loc5`='諸位，晚安。我要在這裡多等一會。達希可能會回來。', `MaleText_loc7`='Buenas noches a todos. Me voy a sentar un poco. Tal vez Darcy se pase por aquí.' WHERE `ID`=670;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어? 젠장, 벌써 점심 시간이잖아! 늦잠을 자 버렸어.', `MaleText_loc4`='啊！午饭！我睡过头了！', `MaleText_loc5`='啊!午飯!我睡過頭了!', `MaleText_loc7`='¡¿Eh?! ¡Maldición, es hora de comer! ¡Me he quedado dormido!' WHERE `ID`=671;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 헐레벌떡 다른 다리 공사 일꾼에게로 달려갑니다.', `MaleText_loc4`='%s喘着气向其他的造桥工跑去。', `MaleText_loc5`='%s喘著氣向其他的造橋工跑去。', `MaleText_loc7`='%s corre, jadeando, hacia los demás trabajadores del puente.' WHERE `ID`=672;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='늦어서 미안하네.', `MaleText_loc4`='对不起，我来晚了。', `MaleText_loc5`='對不起，我來晚了。', `MaleText_loc7`='Siento llegar tarde.' WHERE `ID`=674;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거, 다리가 영영 완성되지 않을 거 같은데?', `MaleText_loc4`='这座桥永远也建成不了吗？', `MaleText_loc5`='這座橋永遠也無法完工，是嗎?', `MaleText_loc7`='Este puente nunca se va a terminar, ¿verdad?' WHERE `ID`=675;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으, 오늘은 온몸이 쑤시는군.', `MaleText_loc4`='今天我的后背痛得几乎要了我的命。', `MaleText_loc5`='今天我的後背痛得幾乎要了我的命。', `MaleText_loc7`='La espalda me está matando hoy.' WHERE `ID`=676;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 지금 뭘 좀 먹을 수 있으면 좋으련만...', `MaleText_loc4`='现在能吃点东西的话该有多好啊。', `MaleText_loc5`='現在能吃點東西的話該有多好啊。', `MaleText_loc7`='Ahora mismo no vendría nada mal un poco de comida.' WHERE `ID`=677;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음... 잘 먹었어. 이제 다시 일하러 가 봐야지.', `MaleText_loc4`='嗯，不错，继续工作吧。', `MaleText_loc5`='嗯，不錯，繼續工作吧。', `MaleText_loc7`='Mmm, esto es bueno. Es hora de volver al trabajo.' WHERE `ID`=678;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 하루가 지나갔군.', `MaleText_loc4`='又一天过去了……', `MaleText_loc5`='又一天過去了...', `MaleText_loc7`='Otro día que se va...' WHERE `ID`=679;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밤이로구먼, 밤...', `MaleText_loc4`='晚安，晚安。', `MaleText_loc5`='晚安，晚安。', `MaleText_loc7`='Buenas noches.' WHERE `ID`=680;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 영혼의 보석을 보고 아연실색합니다!', `MaleText_loc4`='%s被灵魂宝石的力量震慑了！', `MaleText_loc5`='%s被靈魂寶石的力量鎮住了!', `MaleText_loc7`='¡%s enmudece ante la gema de almas!' WHERE `ID`=681;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s의 영혼이 해방됩니다.', `MaleText_loc4`='%s的灵魂自由了……', `MaleText_loc5`='%s的靈魂被釋放了...', `MaleText_loc7`='El espíritu de %s se libera...' WHERE `ID`=682;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 깊은 한숨을 내쉽니다.', `MaleText_loc4`='%s深深地叹了口气。', `MaleText_loc5`='%s發出了一長聲歎息。', `MaleText_loc7`='%s exhala un profundo suspiro.' WHERE `ID`=683;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이래서 내 직업이 싫다니까. 오, 그늘숲이여. 이 불쌍한 안토니오에게 자비를 좀 베풀어 달라고...', `MaleText_loc4`='我讨厌我的这份工作。啊，暮色森林啊，你就不能可怜可怜我么？', `MaleText_loc5`='我實在不喜歡這個地方...啊，暮色森林啊，請你可憐可憐我吧。', `MaleText_loc7`='Odio esta parte de mi trabajo. Oh, Bosque del Ocaso, sé generoso con el pobre Antonio.' WHERE `ID`=684;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고대의 유물, 전쟁에 사용된 무기, 갑옷, 아니면 귀중품! 자, 이번 주에 안토니오가 어떤 물건을 가져왔는지 어서 와서 보세요.', `MaleText_loc4`='古董，武器，装甲，还有很多别的稀罕的好东西！走过路过不要错过！', `MaleText_loc5`='古董，武器，裝甲，還有很多別的稀罕的好東西!走過路過不要錯過!', `MaleText_loc7`='Objetos de la antigüedad, armas de guerra, raras armaduras. ¿Cómo vas a saber lo que Antonio lleva encima esta semana si no vas a verlo?' WHERE `ID`=685;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 이번 주에 과연 이 안토니오가 뭘 가져왔는지 와서 보세요. 안 보면 후회할 겁니다. 안토니오가 뭘 가져왔을까요?', `MaleText_loc4`='这一周可能有蝾螈的眼睛出售，下一周又可能是一张藏宝图。除非你亲眼看到，否则你永远都不会知道安东尼奥在卖什么！赶快来看看吧！', `MaleText_loc5`='這一週可能有蠑螈的眼睛出售，下一週又可能是一張藏寶圖。除非你親眼看到，否則你永遠都不會知道安東尼奧在賣什麼!趕快來看看吧!', `MaleText_loc7`='Esta semana podría ser ojo de tritón o quizás un mapa del tesoro. Nunca se sabe hasta que no miras. ¿Qué será lo que tiene Antonio?' WHERE `ID`=686;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곳곳에서 온 모험가들이 안토니오의 고객이랍니다. 자, 안토니오가 이번 주에 여러분을 위해 준비한 작은 보물이 무엇인지 어서 와서 구경들 하세요.', `MaleText_loc4`='世界各地的冒险家都会给安东尼奥供货——快来看看本周的特价商品啦！', `MaleText_loc5`='世界各地的冒險家都會供貨給安東尼奧─快來看看本週的特價商品喔!', `MaleText_loc7`='Aventureros de todas partes venden objetos a Antonio—vengan a ver con sus propios ojos cuántos pequeños tesoros les ha traído esta semana.' WHERE `ID`=687;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여행자와 모험가 여러분! 어서 마을 광장으로 와서 이 안토니오가 파는 값 싼 물건들을 사세요! 얼마 없습니다요!', `MaleText_loc4`='旅游者和冒险家们，快到城镇中心来抢购吧！安东尼奥的货物实在是物美价廉！来吧，大家都来看看啊！', `MaleText_loc5`='旅遊者和冒險家們，快到城鎮中心來搶購吧!安東尼奧的貨物實在是物美價廉!來吧，大家都來看看啊!', `MaleText_loc7`='¡Viajeros y aventureros se apresuran en llegar a la periferia de esta aldea para aprovechar los maravillosos precios de Antonio! ¡Vamos, venid todos!' WHERE `ID`=688;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그늘숲의 여행자분들 반갑습니다! 어둠골에서 안토니오의 물건을 깜짝 공개합니다. 어서 서두르세요!', `MaleText_loc4`='暮色森林的旅行者们，大家好！现在我的商品全面特价，走过路过不要错过啦！', `MaleText_loc5`='暮色森林的旅人們，大家好!現在我在夜色鎮的商品全面特價，走過路過不要錯過啦!', `MaleText_loc7`='¡Bienvenidos, viajeros del Bosque del Ocaso! Mis mercancías estarán disponibles en Villa Oscura por muy poco tiempo. ¡Daos prisa!' WHERE `ID`=689;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투나 임무는 잠시 접어 두고 이 멋진 물건들 한번 보시라니까요! 이 안토니오가 어둠골에서 장사를 한다는 건 신께서 은혜를 베풀어 주신겁니다요!', `MaleText_loc4`='走一走看一看啦，来看看我的货啦！我不会在夜色镇待很久……好机会不要错过！', `MaleText_loc5`='走一走看一看啦，來看看我的貨啦!我不會在夜色鎮待很久...好機會不要錯過!', `MaleText_loc7`='¡Dejen por un momento sus batallas y misiones y echen un vistazo a mis increíbles mercancías! Solo en Villa Oscura y por poco tiempo... ¡Alabada sea la Luz por esta maravilla!' WHERE `ID`=690;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠골의 주민 여러분, 다시 만날 때까지 안녕히들 계십시오.', `MaleText_loc4`='再见啦，夜色镇的居民们。希望大家不要错过下一次的机会……', `MaleText_loc5`='再見啦，夜色鎮的居民們。希望大家不要錯過下一次的機會...', `MaleText_loc7`='Adiós, ciudadanos de Villa Oscura. Hasta la próxima.' WHERE `ID`=691;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 붉은마루 산맥에 도착했군. 그늘숲의 어둡고 차가운 안개에서 벗어나니 기분 좋구먼.', `MaleText_loc4`='呼，终于可以到赤脊山去了。离开这黑暗阴冷的暮色森林可真让人心情愉快。', `MaleText_loc5`='呼，終於到赤脊山了。離開黑暗陰冷的暮色森林可真讓人心情愉快。', `MaleText_loc7`='Crestagrana al fin. Un cambio agradable cuando se viene de la oscura y fría niebla del Bosque del Ocaso.' WHERE `ID`=692;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하! 타미는 나한테 있지롱!', `MaleText_loc4`='哈哈！我找到伊丽莎白了！', `MaleText_loc5`='哈哈!我拿到伊莉莎白了!', `MaleText_loc7`='¡Ja, ja! ¡Tengo a Betsy!' WHERE `ID`=693;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 인형 이리 내놔!', `FemaleText_loc4`='把我的洋娃娃还给我！！', `FemaleText_loc5`='把我的洋娃娃還給我!!', `FemaleText_loc7`='¡¡Dame mi muñeca!!' WHERE `ID`=694;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 타미! 타미를 돌려줘!', `FemaleText_loc4`='伊丽莎白！把我的伊丽莎白还给我！', `FemaleText_loc5`='伊莉莎白!把我的伊莉莎白還給我!', `FemaleText_loc7`='¡Betsy! ¡Devuélveme a Betsy!' WHERE `ID`=695;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='타미를 아프게 하지마!', `FemaleText_loc4`='不要伤害伊丽莎白，你这个坏蛋！', `FemaleText_loc5`='不要傷害伊莉莎白，你這個壞蛋!', `FemaleText_loc7`='¡No lastimes a Besty, bestia!' WHERE `ID`=696;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='으앙!!!', `FemaleText_loc4`='哇~~！！', `FemaleText_loc5`='哇!!!', `FemaleText_loc7`='¡¡¡BUAAAA!!!' WHERE `ID`=697;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='엄마한테 이를 거야!', `FemaleText_loc4`='我要告诉妈妈！', `FemaleText_loc5`='我要告訴媽媽!', `FemaleText_loc7`='¡Se lo diré a mi mamá!' WHERE `ID`=698;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='인형 머리 잡아 당기지 마!', `FemaleText_loc4`='不要拉她的头发！', `FemaleText_loc5`='不要拉她的頭髮!', `FemaleText_loc7`='¡Deja de tirarle del pelo!' WHERE `ID`=699;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='타미를 아프게 하지 마!', `FemaleText_loc4`='她都哭了！', `FemaleText_loc5`='不要傷害她!', `FemaleText_loc7`='¡Le estás haciendo daño!' WHERE `ID`=700;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그만해! 그러다 망가뜨리겠어!', `FemaleText_loc4`='住手！你将会把她的头都扯掉的！', `FemaleText_loc5`='住手!你將會把她的頭給扯掉的!', `FemaleText_loc7`='¡Basta! ¡Le vas a arrancar la cabeza!' WHERE `ID`=701;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에이미, 잘 있었소? 오, 내 사랑. 호숫골로 돌아와 당신을 보니 너무 좋군.', `MaleText_loc4`='您好啊，艾米小姐。很高兴能回湖畔镇，很高兴还能看到您的芳容，亲爱的小姐。', `MaleText_loc5`='您好啊，艾米小姐。很高興能回湖畔鎮並且看到您的芳容，親愛的小姐。', `MaleText_loc7`='Hola, hola, Amy. Es bueno volver a Villa del Lago y verte, mi señora.' WHERE `ID`=702;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어서 와요, 안토니오. 무사히 돌아와서 정말 다행이에요. 뭐든 필요한 게 있으면 말씀하세요.', `FemaleText_loc4`='你好，安东尼奥。很高兴能看到你平安无事地来到这里。如果有什么需要帮忙的话尽管说。', `FemaleText_loc5`='你好，安東尼奧。很高興能看到你平安無事地來到這裡。如果有什麼需要幫忙的話儘管說。', `FemaleText_loc7`='Hola, Antonio. Me alegro de que hayas vuelto sano y salvo. Dime si necesitas algo.' WHERE `ID`=703;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 이 안토니오가 호숫골에서 깜짝 세일에 들어갑니다! 어서 마을회관으로 오세요!', `MaleText_loc4`='大家听着！大家听着！我会在湖畔镇暂住一段时间来出售我的东西。快点到市政厅来啊！', `MaleText_loc5`='大家聽著!大家聽著!我會在湖畔鎮暫住一段時間來出售我的東西。快點到市政廳來啊!', `MaleText_loc7`='¡Atención, atención! He parado en Villa del Lago por poco tiempo para vender mis mercancías. ¡Venid al ayuntamiento deprisa!' WHERE `ID`=704;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 인형이 수영도 할 수 있을지 궁금한걸!', `MaleText_loc4`='你的洋娃娃会不会游泳啊？哈哈！', `MaleText_loc5`='你的洋娃娃會不會游泳啊?哈哈!', `MaleText_loc7`='¡Me pregunto si tu muñeca sabe nadar!' WHERE `ID`=705;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 인형 내가 갖고 있지롱! 케케!', `MaleText_loc4`='我拿到你的洋娃娃了！哈哈！', `MaleText_loc5`='我拿到你的洋娃娃了!哈哈!', `MaleText_loc7`='¡Tengo tu muñeca! ¡Chínchate!' WHERE `ID`=706;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 하면 어떻게 될까?', `MaleText_loc4`='你猜我这么弄的话，她会怎么样？', `MaleText_loc5`='你猜我這麼弄的話，她會怎麼樣?', `MaleText_loc7`='¡¿Qué pasa si hago esto?!' WHERE `ID`=707;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타미를 돌려 받고 싶으면 나한테 빌어봐!', `MaleText_loc4`='如果你想把她要回去，那你就得求我！', `MaleText_loc5`='如果你想把她要回去，那你就得求我!', `MaleText_loc7`='¡Si la quieres de vuelta, tendrás que rogármelo!' WHERE `ID`=708;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='울보래요! 울보래요!', `MaleText_loc4`='娇气包！娇气包！', `MaleText_loc5`='愛哭鬼!愛哭鬼!', `MaleText_loc7`='¡Llorica! ¡Llorica!' WHERE `ID`=709;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='울보가 인형 달라고 운대요!', `MaleText_loc4`='把洋娃娃还给她！', `MaleText_loc5`='愛哭鬼想要她的洋娃娃!', `MaleText_loc7`='¡La nena quiere su muñeca!' WHERE `ID`=710;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앗!', `MaleText_loc4`='啊！', `MaleText_loc5`='啊!', `MaleText_loc7`='¡Uy!' WHERE `ID`=711;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 호숫골에 도착했군... 자, 모두 이리 와서 안토니오 페렐리의 물건을 싼값에 사 가세요!', `MaleText_loc4`='我终于到湖畔镇了——大家都来啊，安东尼奥·皮雷利卖的可都是价廉物美的好东西啊。', `MaleText_loc5`='我終於到湖畔鎮了─大家都來啊，安東尼奧·皮雷利賣的可都是價廉物美的好東西啊。', `MaleText_loc7`='Por fin he llegado a Villa del Lago. Venid, venid todos, y aprovechad las maravillosas ofertas de Antonio Perelli.' WHERE `ID`=712;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 잠시만요. 여행자분. 그늘숲으로 여행하실 모양인데 도움이 될 튼튼한 방어구가 있습니다요. 자, 지금 안토니오 페렐리가 호숫골에서 장사를 합니다요. 어서들 오세요.', `MaleText_loc4`='安东尼奥·皮雷利卖的东西足以让你顺利在暮色森林旅行，湖畔镇现在就有卖了啊。', `MaleText_loc5`='安東尼奧·皮雷利賣的東西足以讓你順利在暮色森林旅行，湖畔鎮現在就有賣了啊。', `MaleText_loc7`='Son objetos muy poderosos, que servirán para facilitar tu viaje por el Bosque del Ocaso. Los artículos de Antonio Perelli ya están a la venta aquí en Villa del Lago.' WHERE `ID`=713;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에이미, 다시 보게 되어 기쁘군. 몸조심해요, 내 사랑. 이제 나는 황금골로 떠나오.', `MaleText_loc4`='艾米，能再看到你真的很高兴。要小心，亲爱的。我现在要去闪金镇了。', `MaleText_loc5`='艾米，能再看到你真的很高興。要小心，親愛的。我現在要去閃金鎮了。', `MaleText_loc7`='Me alegro de volver a verte, Amy. Cuídate. Tengo que ir a Villadorada ahora mismo.' WHERE `ID`=714;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='몸조심하세요, 안토니오 다음 주에 봐요.', `FemaleText_loc4`='安东尼奥，你自己要保重。我们以后会再见面的。', `FemaleText_loc5`='安東尼奧，你自己要保重。下禮拜再見。', `FemaleText_loc7`='Cuídate, Antonio.' WHERE `ID`=715;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여, 친구들 다시 보니 반갑구먼. 친구들 덕택에 국경 여행이 안전해. 고맙네.', `MaleText_loc4`='你好，我的朋友。很高兴又能见到你。看来你依然在守卫着我们的边境，安东尼奥对你的辛勤工作表示敬意。', `MaleText_loc5`='你好，我的朋友。很高興又能見到你。看來你依然在守衛著我們的邊境，安東尼奧對你的辛勤工作表示敬意。', `MaleText_loc7`='Hola, amigos míos. Me alegro de volver a verlos. Por lo que veo, siguen manteniendo libres nuestras fronteras. Antonio valora mucho su arduo trabajo.' WHERE `ID`=716;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 반가웠소! 난 내 갈 길이 바빠서 이만... 모두 몸조심하라고.', `MaleText_loc4`='非常感谢！我要上路了……大家都要多加小心啊！', `MaleText_loc5`='非常感謝!我要上路了...大家都要多加小心啊!', `MaleText_loc7`='¡No hay de qué! Tengo que seguir mi camino... cuidaos todos.' WHERE `ID`=717;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여어, 안토니오. 자네 가게에서 산 모자를 아내가 무척 맘에 들어 하더군.', `MaleText_loc4`='你好，安东尼奥。再次感谢你卖给我妻子的帽子，她非常喜欢。', `MaleText_loc5`='你好，安東尼奧。再次感謝你賣給我妻子的帽子，她非常喜歡。', `MaleText_loc7`='Hola, Antonio, otra vez. Gracias nuevamente por el sombrero para mi esposa. Le encantó.', `FemaleText_loc1`='여어, 안토니오. 자네 가게에서 산 모자를 아내가 무척 맘에 들어 하더군.', `FemaleText_loc4`='你好，安东尼奥。再次感谢你卖给我妻子的帽子，她非常喜欢。', `FemaleText_loc5`='你好，安東尼奧。再次感謝你賣給我妻子的帽子，她非常喜歡。', `FemaleText_loc7`='Hola, Antonio, otra vez. Gracias nuevamente por el sombrero para mi esposa. Le encantó.' WHERE `ID`=718;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='몸 조심하게, 안토니오.', `MaleText_loc4`='路上小心，安东尼奥。', `MaleText_loc5`='路上小心，安東尼奧。', `MaleText_loc7`='Cuídate, Antonio.', `FemaleText_loc1`='몸 조심하게, 안토니오.', `FemaleText_loc4`='路上小心，安东尼奥。', `FemaleText_loc5`='路上小心，安東尼奧。', `FemaleText_loc7`='Cuídate, Antonio.' WHERE `ID`=719;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헤헤, 그러리다. 조심할 테니 당신도 몸조심하라고.', `MaleText_loc4`='哦，我的朋友，我会的，我会保重的。你们自己也千万要保重！', `MaleText_loc5`='哦，朋友，我會的，我會保重的。你們自己也千萬要保重!', `MaleText_loc7`='Oh, lo haré, $gamigo mío:amiga mía;. Así será. Y tú, cuídate.' WHERE `ID`=720;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자 연금술에 필요한 약병 팝니다! 황금골 주민 여러분, 어서 와서 구경들 하세요.', `MaleText_loc4`='大甩卖啦！大甩卖啦！闪金镇的居民们快来看看啊，安东尼奥马上就要走了，好机会不要错过啊。', `MaleText_loc5`='大拍賣啦!大拍賣啦!閃金鎮的居民們快來看看啊，安東尼奧馬上就要走了，好機會不要錯過啊。', `MaleText_loc7`='¡Mercancías a la venta! ¡Mercancías a la venta! Venid a ver las mercancías de Antonio antes de que me marche, ciudadanos de Villadorada.' WHERE `ID`=721;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안토니오가 약병을 팝니다! 어서들 오세요. 이번에 가면 한동안 안 올 겁니다.', `MaleText_loc4`='大家都过来看啊！安东尼奥又开始卖他的宝贝啦。下次我再来就可能是很久之后的事情了，大家都过来看看啊。', `MaleText_loc5`='大家都過來看啊!安東尼奧又開始賣他的寶貝啦。下次我再來就可能是很久之後的事情了，大家都過來看看啊。', `MaleText_loc7`='¡Vamos, venid todos! Las mercancías de Antonio están a la venta. Tal vez no vuelva durante mucho tiempo, así que venid todos.' WHERE `ID`=722;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황금골의 주민 여러분, 흔치 않은 좋은 물건을 믿을 수 없을 만큼 싼값에 팝니다. 이번 기회를 놓치면 후회하실 겁니다!', `MaleText_loc4`='闪金镇的父老乡亲们，过来看看我这些价廉物美的好东西吧。我可能会有一段时间不再回来了！', `MaleText_loc5`='閃金鎮的父老鄉親們，過來看看我這些價廉物美的好東西吧。我可能會有一段時間不再回來了!', `MaleText_loc7`='Buena gente de Villadorada, venid y aprovechaos de mis precios increíbles y de la rareza de mis objetos. ¡No volveré en mucho tiempo!' WHERE `ID`=723;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황금골이여, 안녕. 일주일쯤 후에 다시 오지...', `MaleText_loc4`='再见了，闪金镇。我很快就会回来的——也许就只要一个星期。', `MaleText_loc5`='再見了，閃金鎮。我很快就會回來的─也許就只要一個星期。', `MaleText_loc7`='Adiós, Villadorada. Volveré muy pronto, tal vez en una semana.' WHERE `ID`=724;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 돌아왔어. 고향에 돌아왔다고.', `MaleText_loc4`='又回到家了，又回到家了。', `MaleText_loc5`='又回到家了，又回到家了。', `MaleText_loc7`='De nuevo en casa, de nuevo en casa.' WHERE `ID`=725;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 감시의 언덕에 이 유명한 안토니오 페렐리가 왔습니다. 곧 떠나야 하니 어서들 와서 구경들 하세요.', `MaleText_loc4`='世界闻名的安东尼奥·皮雷利现在要在哨兵岭出售他的货物了！', `MaleText_loc5`='世界聞名的安東尼奧·皮雷利現在要在哨兵嶺出售他的貨物了!我很快就要啟程前往下一個城鎮了，要買的要快喔。', `MaleText_loc7`='¡Conocidas en todas partes, las mercancías de Antonio Perelli están ahora a la venta cerca de la Colina del Centinela! Tengo que irme pronto, así que daos prisa.' WHERE `ID`=726;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언덕 근처에서 튼튼하고 질 좋은 물건을 팝니다! 모두 어서 오세요! 시간이 별로 없으니 서두르시라고요.', `MaleText_loc4`='哨兵岭附近有耐用的好东西在卖啊！都过来看看吧！时间不多了，大家赶快啊。', `MaleText_loc5`='哨兵嶺附近有耐用的好東西在賣啊!都過來看看吧!時間不多了，大家趕快啊。', `MaleText_loc7`='¡Artículos duraderos y bien confeccionados, a la venta cerca de la Colina! ¡Vamos, venid todos! El tiempo vuela, daos prisa.' WHERE `ID`=727;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감시의 언덕 근방을 여행하시는 분들을 위해 여행용품을 판매합니다! 한번 와보시라니까요!', `MaleText_loc4`='走过路过不要错过啊，我这里卖的都是价廉物美的好东西！大家都过来看看啊！', `MaleText_loc5`='我又再次回到哨兵嶺販賣物美價廉的好物品，各位旅客們快來撿便宜喔!大家都過來看看啊!', `MaleText_loc7`='¡Ha llegado el momento de volver a ofrecer mis mercancías a todos los que vayan a los alrededores de la Colina del Centinela! ¡Vamos, venid todos!' WHERE `ID`=728;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 고맙습니다. 일주일쯤 후에 다시 뵙죠.', `MaleText_loc4`='谢谢大家。我会在一周后回来。', `MaleText_loc5`='謝謝大家。我會在一週後回來。', `MaleText_loc7`='Gracias a todos. Volveré más o menos en una semana.' WHERE `ID`=729;
