UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭약을 실은 마지막 뱃짐은 왜 아직 소식이 없는거야?', `MaleText_loc4`='依然没有最后一批炸药的任何消息。', `MaleText_loc5`='依然沒有最後一批爆裂物的任何消息。', `MaleText_loc7`='Seguimos sin señales del cargamento final de explosivos.' WHERE `ID`=782;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서쪽으로 배달되어야 할 마지막 폭약도 소식이 없어. 이 게으름뱅이들이 어디서 뭘 하고 있는 거지?', `MaleText_loc4`='还是没有最后一批炸药的消息。那些东西究竟在哪里？', `MaleText_loc5`='還是沒有最後一批爆裂物的消息。那些懶鬼究竟在哪裡?', `MaleText_loc7`='Tampoco hay señales del cargamento final de explosivos que se dirige al este. ¿Dónde están esos holgazanes?' WHERE `ID`=783;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 다리는 지금쯤이면 이미 파괴되었어야 하는데... 도대체 저 게으른 녀석들은 아라시 고원에서 여기까지 오는 데 시간이 얼마나 걸리는 거야!', `MaleText_loc4`='这座桥早就该被摧毁了。那些懒东西从高地走到这里居然花了这么长时间！', `MaleText_loc5`='這座橋早就該被摧毀了。那些懶東西從高地走到這裡居然花了這麼長時間!', `MaleText_loc7`='A estas horas, este puente debería estar destruido. ¡Cuánto tiempo necesitan estos imbéciles para llegar hasta aquí desde las Tierras Altas!' WHERE `ID`=784;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와줘요! 저 좀 도와 주세요! 놈들이 날 잡아먹으려 해요!', `MaleText_loc4`='救命！救命！不要让它们吃了我！', `MaleText_loc5`='救命!救命!不要讓它們吃了我!', `MaleText_loc7`='¡Socorro! ¡Socorro! ¡No dejéis que me coman!' WHERE `ID`=785;
