UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일에서 벗어나 쉬어 본 게 언제인지 이제 기억도 잘 안 나는군.', `MaleText_loc4`='已经很久很久都没有人替我干这个苦差事了。', `MaleText_loc5`='已經很久很久沒有人過來接替我了。', `MaleText_loc7`='Ciertamente parece que ha pasado mucho tiempo desde que nadie me releva de mi puesto.' WHERE `ID`=790;
