UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 조각들 섬뜩한데... 이봐 그리비, 결정을 더 발견했나?', `MaleText_loc4`='这些碎片让我毛骨悚然。嘿，格雷比，你找到别的碎片了吗？', `MaleText_loc5`='這些裂片讓我毛骨悚然。嘿，格雷比，你找到別的裂片了嗎?', `MaleText_loc7`='Estos cascos me ponen los pelos de punta. Oye, Greeby, ¿has encontrado más pelusas?' WHERE `ID`=795;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='만약 그랬다면 자네에게 얘기 안 했을 걸! 내가 말하는 순간 이 수정들은 내 손을 떠나게 될 테니까...', `MaleText_loc4`='即使我找到了也不会告诉你！因为告诉你的话……我就弄不到水晶了……', `MaleText_loc5`='即使我找到了也不會告訴你!因為告訴你的話...我就弄不到水晶了...', `MaleText_loc7`='por suerte, el sello de Thoradin vuelve a estar intacto.' WHERE `ID`=796;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맞아, 미즈라엘이 깨어난다면 난 이곳에 있고 싶지 않아. 미즈라엘은 정말 성미가 고약하다고 하던데...', `MaleText_loc4`='当然，如果密斯莱尔醒来的话，我才不愿意待在这里。他们说她脾气很不好……', `MaleText_loc5`='當然，如果密斯賴爾醒來的話，我才不願意待在這裡。聽說她脾氣很不好...', `MaleText_loc7`='Eh, no quiero estar aquí si despierta Myzrael. Dicen que tiene mal carácter...' WHERE `ID`=797;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생각했던 것보다 쉽군... 소라딘의 인장이 다시 완전한 형태가 됐네.', `MaleText_loc4`='比我想象中的要简单……索拉丁封印又变成完整的了。', `MaleText_loc5`='比我想像中的要簡單...索拉丁符印已經再度合而為一了。', `MaleText_loc7`='Por suerte, el sello de Thoradin vuelve a estar intacto.' WHERE `ID`=798;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영원히 당신 그림자 안에 살겠습니다!', `MaleText_loc4`='请永远庇护我吧！', `MaleText_loc5`='請永遠庇護我吧!', `MaleText_loc7`='¡Deseo protegerme eternamente bajo tu sombra!' WHERE `ID`=799;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님, 당신의 지혜만큼 큰 것이 없습니다!', `MaleText_loc4`='主人，您的英明举世无双！', `MaleText_loc5`='主人，您的英明舉世無雙!', `MaleText_loc7`='¡Maestro, tu sabiduría solo es comparable con tu grandeza!' WHERE `ID`=800;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 위대한 공적만큼의 구리가 제게 있다면 아주 부유한 코볼트가 되겠나이다!', `MaleText_loc4`='如果我能从您的每次大买卖中提成一个铜币，那么我将会马上变成一个富有的狗头人！', `MaleText_loc5`='如果我能從您的每個偉大事蹟都領到一塊銅幣，我馬上就變成有錢的狗頭人!', `MaleText_loc7`='¡Si me dieran un cobre por cada una de tus grandes hazañas, sería un kóbold rico!' WHERE `ID`=801;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신께서 우리를 사악한 세력으로부터 안전하게 지켜 주시리라 믿습니다!', `MaleText_loc4`='没错，您一定能保护我们不受那个恶妇的伤害！', `MaleText_loc5`='沒錯，您一定能保護我們不受那個惡婦的傷害!', `MaleText_loc7`='¡Nos protegerás de la malvada maestra, sí!' WHERE `ID`=802;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 찬양을! 당신께서 지켜 주심으로 미즈라엘을 저 땅속 깊은 곳에 가두어 둘 수 있습니다!', `MaleText_loc4`='哦！太棒了！您的努力将使密斯莱尔长眠于地下！', `MaleText_loc5`='哦!太棒了!您的努力將使密斯賴爾長眠於地下!', `MaleText_loc7`='¡Alabado sea! ¡Tu vigilancia mantiene a Myzrael bien enterrada en su tumba!' WHERE `ID`=803;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저의 유일한 소망은 죽는 날까지 당신을 모시는 것입니다!', `MaleText_loc4`='我唯一的愿望只是希望能够服侍伟大的您，我愿为您赴汤蹈火！', `MaleText_loc5`='我唯一的願望只是希望能夠服侍偉大的您，我願為您赴湯蹈火!', `MaleText_loc7`='Mi único deseo es servirte, oh grande, ¡hasta que muera a tus pies!' WHERE `ID`=804;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 힘은 산과 같습니다. 그리고 당신의 은혜는 바람과 같습니다!', `MaleText_loc4`='您犹如高山一般强壮，而气质却又如微风一般优雅！', `MaleText_loc5`='您猶如高山一般強壯，而氣質卻又如微風一般優雅!', `MaleText_loc7`='Tienes la fuerza de una montaña. ¡Tienes la gracia del viento!' WHERE `ID`=805;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발 너무 아프다...', `MaleText_loc4`='我的脚有些疼……', `MaleText_loc5`='我的腳有些疼...', `MaleText_loc7`='Me duelen los pies...' WHERE `ID`=806;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽어라! 미즈라엘 구하지 못한다!', `MaleText_loc4`='去死吧！你不该放走密斯莱尔的！', `MaleText_loc5`='去死吧!你無法釋放密斯賴爾的!', `MaleText_loc7`='¡Muere! ¡No vas a liberar a Myzrael!' WHERE `ID`=807;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위대하신 분이 너 박살내 버리신다!', `MaleText_loc4`='你会被碾成粉末的！', `MaleText_loc5`='主人會把你碾成粉末的!', `MaleText_loc7`='¡El Magno os machacará!' WHERE `ID`=808;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 별로 크지 않군?', `MaleText_loc4`='您是不是有点太矮了？', `MaleText_loc5`='您是不是有點太矮了?', `MaleText_loc7`='¿Acaso no eres un poco $gbajito:bajita; para los de tu especie?' WHERE `ID`=809;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신성한 임무를 위해 기꺼이 목숨 바친다!', `MaleText_loc4`='我的性命并不重要！重要的是一定要完成我们神圣的使命！', `MaleText_loc5`='我的性命並不重要!重要的是一定要完成我們神聖的使命!', `MaleText_loc7`='¡Mi vida no importa nada! ¡Nuestra sagrada misión lo es todo!' WHERE `ID`=810;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미즈라엘을 구하려면 너 당할 거다!', `MaleText_loc4`='如果你想要释放密斯莱尔，那么你一定会后悔的！', `MaleText_loc5`='如果你想要釋放密斯賴爾，那麼你一定會後悔的!', `MaleText_loc7`='¡Si tienes la intención de liberar a Myzrael, lo lamentarás!' WHERE `ID`=811;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 더 크다. 코볼트 형제들! 나가 싸우자!', `MaleText_loc4`='站直了，弟兄们！不要怕！我们这里有大个的！', `MaleText_loc5`='站直了，弟兄們!不要怕!我們這裡有體型上的優勢!', `MaleText_loc7`='Manteneos firmes, hermanos. ¡Y no os preocupéis! ¡El tamaño nos favorece!' WHERE `ID`=812;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='받아라! 마른수염 일족이 이긴다!', `MaleText_loc4`='拿下那里！枯须狗头人必胜！', `MaleText_loc5`='嚐嚐這招!枯鬚狗頭人必勝!', `MaleText_loc7`='¡Toma! ¡Los Mostacho Seco vencerán!' WHERE `ID`=814;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 내버려 둬! 방해하지마!', `MaleText_loc4`='不！快走开！我们绝对不能失败！', `MaleText_loc5`='不!快走開!我們絕對不能失敗!', `MaleText_loc7`='¡No! ¡Dejadnos! ¡No podemos fracasar en nuestra tarea!' WHERE `ID`=815;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='흠, 그럼 시작해 볼까요? 우리가 여기서 오래 지체할수록 언데드가 언덕마루에 더 큰 피해를 줄 겁니다.', `FemaleText_loc4`='那么就尽快开始吧。我们在这里待得越久，亡灵重回希尔斯布莱德作恶的可能性就越大。', `FemaleText_loc5`='那麼就儘快開始吧。我們在這裡待得越久，亡靈重回希爾斯布萊德作惡的可能性就越大。', `FemaleText_loc7`='Entonces, empecemos. Cuanto más tiempo permanezcamos aquí, mayor daño harán los no-muertos en Trabalomas.' WHERE `ID`=816;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋아요, 여기서부터 오크들의 공격이 드세질 겁니다. 준비하세요!', `FemaleText_loc4`='好了，我们要在这儿真刀真枪地干一场。准备好！', `FemaleText_loc5`='好了，從這邊開始就要加倍小心。準備好!', `FemaleText_loc7`='Vale, aquí es donde debemos estar. ¡Preparaos!' WHERE `ID`=817;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 쓰레기 더미 속에 뭐가 있는지 살펴봐야겠으니... 뒤를 엄호하세요!', `FemaleText_loc4`='替我断后！我要看看在这些垃圾里能找到什么……', `FemaleText_loc5`='替我斷後!我要看看在這些垃圾裡能找到什麼...', `FemaleText_loc7`='¡Vigilad mi retaguardia! Veré qué puedo encontrar en toda esta basura...' WHERE `ID`=818;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 연금술사의 소지품을 샅샅이 뒤지기 시작합니다.', `FemaleText_loc4`='%s开始翻找药剂师的东西。', `FemaleText_loc5`='%s開始翻找藥劑師的東西。', `FemaleText_loc7`='%s empieza a hurgar en las pertenencias del boticario.' WHERE `ID`=819;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭔가... 찾은 것 같은데...', `FemaleText_loc4`='我想我找到了一些东西……', `FemaleText_loc5`='我想我找到了一些東西...', `FemaleText_loc7`='He encontrado algo... Al menos eso creo.' WHERE `ID`=820;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이건 아무래도 쿠에가 중요하게 생각할 것 같은데... 이런 것에 대해서는 쿠에가 잘 알죠. 전문가는 아니지만 아는 게 많다고요.', `FemaleText_loc4`='我猜奎艾会认为这个很重要。她应该对这些东西相当熟悉——虽然她不是这方面的专家，但也算得上是知识渊博。', `FemaleText_loc5`='我猜奎艾會認為這個很重要。她應該對這些東西相當熟悉─雖然還稱不上專家，但好歹也懂得不少。', `FemaleText_loc7`='Apuesto a que Quae cree que esto es importante. Sabe bastante de estas cosas. No es una experta, pero algo sabe.' WHERE `ID`=821;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋아요, 어서 서둘러 여기를 빠져나가요! 조금만 더 힘내요. 빠져나가서 쉬죠.', `FemaleText_loc4`='好，让我们赶快离开这里吧！你们继续跑。我要停一下。', `FemaleText_loc5`='好，讓我們趕快離開這裡吧!盡量跟上我。我要逃離這裡了。', `FemaleText_loc7`='¡Bueno, salgamos de aquí deprisa, deprisa! Esforzaos y animaos. Voy a hacer una pausa para esto.' WHERE `ID`=822;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성공했다고요?! 놀랍군요. 키넬로리와 함께했는데도 이렇게나 빨리 해내다니... 킨, 여기 네 양말이야. 자, 뭘 발견했는지 한번 볼까요.', `MaleText_loc4`='你们成功了？！我很惊讶基恩洛并没有让你慢下来。那么，给我看看你们找到的东西。', `MaleText_loc5`='你們成功了?!我很驚訝基恩洛並沒有讓你們慢下來。基恩洛，這是你的襪子。給我看看你們找到的東西。', `MaleText_loc7`='¡¿Lo has conseguido?! Me sorprende que Kinelory no te haya hecho ir más lento. Kin, aquí están tus calcetines. Dame lo que hayas encontrado dentro.' WHERE `ID`=823;
