UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멈춰라! 어리석은 $c 같으니, 네가 미즈라엘을 풀어주도록 내버려둘 순 없다!', `MaleText_loc4`='住手！愚蠢的$c，我们不能让你召唤密斯莱尔！', `MaleText_loc5`='住手!愚蠢的$c，我們不能讓你召喚密斯賴爾!', `MaleText_loc7`='¡Basta! $C idiota, no dejaremos que invoques a la criatura Myzrael!' WHERE `ID`=841;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='음? $n, 날 위해 큰일을 해 주었지만...', `FemaleText_loc4`='什么？$n，你做得很好，但……', `FemaleText_loc5`='什麼?$n，你做得很好，但...', `FemaleText_loc7`='¿Qué? $n, me has servido como es debido, pero...' WHERE `ID`=842;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='날 왜 이렇게 빨리 불러낸 거지? 아직 완전히 힘을 회복하지 못했단 말이야!', `FemaleText_loc4`='你为什么这样急于召唤了我？我还没恢复我所有的力量！', `FemaleText_loc5`='你為什麼這樣急於召喚我?我還沒恢復所有的力量!', `FemaleText_loc7`='¿Por qué me has convocado tan pronto? ¡Aún no he alcanzado todo mi poder!' WHERE `ID`=843;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='상관없어. 어리석은 녀석... 이제 그 대가를 치러라!', `FemaleText_loc4`='不过没关系。你真是个笨蛋，居然帮助了我，现在是该让你付出代价的时候了！', `FemaleText_loc5`='不過沒關係。你真是個笨蛋，居然幫助了我，現在是讓你付出代價的時候了!', `FemaleText_loc7`='Da igual. Fuiste idiota al ayudarme ¡y ahora vas a pagar!' WHERE `ID`=844;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아요, $n 님. 이제 동굴로 가서 마법석의 힘을 이 고글에 담아 보려고 하니 저를 따라오세요.', `MaleText_loc4`='好了，$n。跟我到那个洞里去一趟，我会试着把符石的能量注入到护目镜上。', `MaleText_loc5`='好了，$n。跟我到那個洞裡去一趟，我會試著把符石的能量注入到護目鏡上。', `MaleText_loc7`='Vale, $n. Sígueme a la cueva, en la que intentaré volcar el poder de la runa sobre estas gafas.' WHERE `ID`=845;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 이곳에 온 첫날 이 동굴을 발견했지요. 마법석의 힘을 유용하게 쓸 수 있을 거예요.', `MaleText_loc4`='我第一天来这里的时候就发现了这个洞穴。我相信这块石头里的能量对我们大有用处。', `MaleText_loc5`='我第一天來這裡的時候就發現了這個洞穴。我相信這塊石頭裡的能量對我們大有用處。', `MaleText_loc7`='Descubrí esta cueva el primer día que llegamos aquí. Creo que podemos usar la energía de la piedra en nuestro beneficio.' WHERE `ID`=846;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 마법석에서 힘을 끌어내 볼게요. 당신은 저를 보호해 주시면 돼요. 이곳은 저주받은 곳이에요... 정말이라니까요.', `MaleText_loc4`='我要开始将石头中的能量提取出来。$n，你的工作就是保护我。这个地方是被诅咒过的……相信我。', `MaleText_loc5`='我要開始將石頭中的能量提取出來。$n，你的工作就是保護我。這個地方是被詛咒過的...相信我。', `MaleText_loc7`='Comenzaré sacando energía de la piedra. Tu trabajo, $n, es defenderme. Este lugar está maldito... Creeme.' WHERE `ID`=847;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 마법석 앞에서 고글을 만지작거리기 시작합니다.', `MaleText_loc4`='%s开始在石头前修补护目镜。', `MaleText_loc5`='%s開始在魔法石前方調整護目鏡。', `MaleText_loc7`='%s ajusta las gafas para ver la piedra.' WHERE `ID`=848;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거의 다 됐어요! 조금만 더 하면 돼요!', `MaleText_loc4`='快完成了！再给我一点点时间！', `MaleText_loc5`='快完成了!再給我一點點時間!', `MaleText_loc7`='¡Ya casi está! ¡Solo un poco más!' WHERE `ID`=849;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='됐어요! 고글에 마법석의 힘을 집어넣었어요. 이제 이곳을 빠져나가죠!', `MaleText_loc4`='我完成了！我把石头的能量注入了护目镜！咱们赶快从这里出去吧！', `MaleText_loc5`='我完成了!我把石頭的能量注入了護目鏡!咱們趕快從這裡出去吧!', `MaleText_loc7`='¡Lo he conseguido! ¡He volcado el poder de la piedra sobre las gafas! ¡Salgamos de aquí!' WHERE `ID`=850;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='후유! 그 기분 나쁜 동굴을 빠져나오니 이제 살 것 같군요.', `MaleText_loc4`='呼……终于可以离开那个阴暗的洞穴了！', `MaleText_loc5`='呼...終於可以離開那個陰暗的洞穴了!', `MaleText_loc7`='¡Uf! Me alegro de haber salido de esa horrible cueva.' WHERE `ID`=851;
