UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 이 세계에서 추방되자 산산조각나고 맙니다.', `MaleText_loc4`='%s被撕裂了，消逝得无影无踪。', `MaleText_loc5`='%s被放逐驅離這個世界，並且被撕裂消滅了。', `MaleText_loc7`='%s se hace pedazos al tiempo que deja este mundo.' WHERE `ID`=853;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크르르르, 넌 너무 오랫동안 우리 보물을 약탈해 왔다. 이제 물고기 밥이 될 준비나 해라!', `MaleText_loc4`='一直以来你都在掠夺我们的财宝。这次准备葬身鱼腹吧！', `MaleText_loc5`='一直以來你都在掠奪我們的財寶。這次準備葬身水裡吧!', `MaleText_loc7`='Has saqueado nuestros tesoros demasiado tiempo. ¡Prepárate para visitar tu acuosa tumba!' WHERE `ID`=854;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크르르, 그 무엇도 우릴 막을 순 없다! 죽어라!', `MaleText_loc4`='没有什么可以阻止我们的！你死定了！', `MaleText_loc5`='沒有什麼可以阻止我們的!你死定了!', `MaleText_loc7`='¡Nada nos detendrá! ¡Morirás!' WHERE `ID`=855;
