UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐, 친구!!! 아무래도 여기 도움이 필요하게 될 것 같은데...', `MaleText_loc4`='等等，$n！！！看来我们有麻烦了……', `MaleText_loc5`='等等，$n!!!看來我們有麻煩了...', `MaleText_loc7`='¡¡¡Espera, $n!!! Parece que vamos a necesitar algo más de ayuda...' WHERE `ID`=857;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와줘요!! 이곳은 저주받은 곳이라고 했잖아요!', `MaleText_loc4`='救命啊！！我告诉过你这个地方是被诅咒过的！', `MaleText_loc5`='救命啊!!我告訴過你這個地方是被詛咒過的!', `MaleText_loc7`='¡¡¡Socorro!!! ¡Te dije que este lugar estaba maldito!' WHERE `ID`=858;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와줘요!!! 제가 일을 끝낼 수 있도록 이것들을 좀 떼어내 주세요!', `MaleText_loc4`='赶快！只有干掉这些东西，我才能完成我的工作！', `MaleText_loc5`='救命!幹掉這些東西，我才能完成我的工作!', `MaleText_loc7`='¡¡¡Socorro!!! ¡Quitadme estas cosas de encima para que pueda terminar mi trabajo!' WHERE `ID`=859;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 사라 발루의 탄원서 내용을 주의 깊게 읽어보고는 무겁고 긴 한숨을 내쉽니다.', `MaleText_loc4`='%s仔细翻看着萨拉·巴鲁的信，满怀忧郁地叹了口气。', `MaleText_loc5`='%s仔細地閱讀了薩拉·巴魯的信，然後長長地歎了口氣。', `MaleText_loc7`='%s analiza cuidadosamente la nota de Sara Balloo y emite un largo y solemne suspiro.' WHERE `ID`=860;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 몸에 흐르는 이 힘은 대체 뭐지? 이것이 토건이 말하던 주술의 힘인가...?', `MaleText_loc4`='这……这是什么？难道这就是托尔甘所说的萨满力量？', `MaleText_loc5`='在我體內流動的這是什麼力量?難道這就是托爾甘所說的...薩滿力量?', `MaleText_loc7`='¿Qué es este poder que fluye dentro de mí? ¿Se trata del poder chamánico del que habló Tor''gan...?' WHERE `ID`=861;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놀랍군! 이건 마치... 새로 태어난 느낌이야. 내 힘을 되찾았네!', `MaleText_loc4`='太神奇了！我感觉就如同获得了重生一般。我的力量又回来了！', `MaleText_loc5`='太神奇了!我感覺就像...獲得了重生一般。我的力量又回來了!', `MaleText_loc7`='¡Fascinante! Me siento... renovado. ¡Recobro mi fuerza!' WHERE `ID`=862;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 저들의 손아귀에서 살아남을 수만 있다면 우리는 틀림없이 안전해질 거야.', `MaleText_loc4`='只要我们现在能控制住他们，那就肯定能搞明白这件事情。', `MaleText_loc5`='只要我們現在能阻擋住他們，那就肯定能度過這次攻擊。', `MaleText_loc7`='Si conseguimos pararlos ahora, seguro que estaremos fuera de peligro.' WHERE `ID`=863;
