UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너무 많은 병사를 잃었는데... 이 전투가 끝날 때까지 또 이만큼의 병사들을 잃어야 하는 것인가...', `FemaleText_loc4`='已经有这么多勇敢的战士失去了生命，在这场战役结束之前，我们可能还会失去更多……', `FemaleText_loc5`='已經有這麼多勇敢的戰士失去了生命，在這場戰役結束之前，我們可能還會再失去更多...', `FemaleText_loc7`='Tantas pérdidas. Y tantos más que perderemos antes de que termine la batalla.' WHERE `ID`=883;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='휘장을 가져다줘서 고맙습니다, $n. 전사자의 가족들에게 소식을 전하겠습니다.', `FemaleText_loc4`='谢谢你帮忙找回这些徽章，$n。我将通知阵亡者的家属。', `FemaleText_loc5`='謝謝你幫忙找回這些徽章，$n。我將通知陣亡者的家屬。', `FemaleText_loc7`='Gracias por estas insignias, $n. Enviaré noticias de los muertos a sus familias.' WHERE `ID`=884;
