UPDATE `locales_broadcast_text` SET `MaleText_loc1`='개굴! 안 돼!! 감히 나한테 이럴... 개굴... 수가! 더러운 속임수로 날... 개굴... 속이다니! 개굴!', `MaleText_loc4`='呱呱！不！！这不可能……呱呱！你骗了我……呱呱……你这个骗子！呱呱！', `MaleText_loc5`='呱呱!不!!這不...呱呱...可能!你騙了我...呱呱...你這個騙子!呱呱!', `MaleText_loc7`='¡Croac! ¡¡No!! ¡Esto no puede ser, croac! ¡Me has embaucado con tus artimañas, croac! ¡Croac!' WHERE `ID`=886;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; $n|1을;를; 위해 매운 대머리수리 날개 요리 한 접시를 만듭니다.', `MaleText_loc4`='%s为$n烹制了美味的烤秃鹰翅膀。', `MaleText_loc5`='%s為$n烹製了一份香辣燒烤禿鷲翅膀。', `MaleText_loc7`='%s prepara un plato de alas picantes de halcón para $n.' WHERE `ID`=887;
