UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 발명가 드랙슬게이지에게 빛나는 고글을 건넵니다.', `MaleText_loc4`='%s把护目镜交给了德拉克里格博士。', `MaleText_loc5`='%s把護目鏡交給了德拉克里格博士。', `MaleText_loc7`='%s entrega las gafas resplandecientes al doctor Draxlegauge.' WHERE `ID`=889;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발명가 드랙슬게이지가 앞으로 할 일을 일러줄 거예요. 도와줘서 정말 고마워요!', `MaleText_loc4`='德拉克里格博士将会给你进一步的指示，$n。很感谢你的帮助！', `MaleText_loc5`='德拉克里格博士將會給你進一步的指示，$n。很感謝你的幫助!', `MaleText_loc7`='El doctor Draxlegauge te dará más instrucciones, $n. ¡Muchas gracias por tu ayuda!' WHERE `ID`=890;
