UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어휴, 여기서는 낚시를 못 하겠어. 통 물지를 않네? 아무래도 수정 호수로 가야겠어.', `MaleText_loc4`='呀，这里的鱼好像不咬钩。也许我该去水晶湖那边试试运气！', `MaleText_loc5`='呀，這裡的魚好像不上鉤。也許我該去水晶湖那邊試試運氣!', `MaleText_loc7`='Vaya, al parecer, no pica ningún pez. ¡Tal vez debería ir al Lago de Cristal para probar mi suerte allí!' WHERE `ID`=893;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제길! 여기서도 안 낚이네. 에잇, 낚시터에나 가야겠군!', `MaleText_loc4`='该死！这里的鱼也不上钩。我要回到原来的地方去。', `MaleText_loc5`='該死!這裡的魚也不上鉤。我要回到原來的地方去。', `MaleText_loc7`='¡Vaya! Aquí parece que tampoco pica ningún pez. ¡Volveré a mi viejo rincón de pesca!' WHERE `ID`=894;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='결코 포세이큰을 막을 수 없을 것이다, $r. 어둠의 여왕께서 널 처단하실 테니까!', `MaleText_loc4`='你无法阻止被遗忘者，$r。黑暗女王将会让你感受到痛苦和恐惧。', `MaleText_loc5`='你無法阻止被遺忘者，$r。黑暗女王將會讓你感受到痛苦和恐懼。', `MaleText_loc7`='Nunca detendrás a los Renegados, $r. La Dama Oscura te hará sufrir.' WHERE `ID`=895;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 약속하지. 네놈을 처치한 후 그 몸뚱어리를 요긴하게 사용해 주마, $r.', `MaleText_loc4`='你听好了，在我杀死你之后，你的身体将为我所用，$r。', `MaleText_loc5`='你聽好了，在我殺死你之後，你的身體將為我所用，$r。', `MaleText_loc7`='¡Tienes mi palabra de que daré un uso a tu cadáver después de que te mate, $r!' WHERE `ID`=896;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='덤벼 보시지, 이 오크들. 하지만 내가 쿠에에게 돌아가는 걸 막을 순 없을 걸!', `FemaleText_loc4`='你可以攻击我，但是你依然无法阻止我回到奎艾那里去。', `FemaleText_loc5`='你可以攻擊我，但是你依然無法阻止我回到奎艾那裡去。', `FemaleText_loc7`='Atácame si quieres, pero no vas a impedir que regrese con Quae.' WHERE `ID`=897;
