UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 더 뛰어나고, 더 강하고, 더 빠르게 만들 수 있습니다. 우리에겐 기술과 마법이 있으니까요.', `MaleText_loc4`='我们能让它变得更好，更强，更快。我们不仅拥有技术，而且拥有强大的魔法。', `MaleText_loc5`='我們能讓它變得更好，更強，更快。我們不僅擁有技術，而且擁有強大的魔法。', `MaleText_loc7`='Podemos hacerlo mejor, con mayor fuerza y más rápido. Disponemos de la tecnología. Tenemos la magia.' WHERE `ID`=901;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언젠가 전 진짜 사람이 될 겁니다.', `MaleText_loc4`='总有一天我要成为一个真正的男孩。', `MaleText_loc5`='總有一天我要成為一個真正的男孩。', `MaleText_loc7`='Un día seré un niño de verdad.' WHERE `ID`=902;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳 황야의 땅은 정말 뜨겁지만 습하지는 않답니다.', `MaleText_loc4`='荒芜之地真的很热，但至少还不潮湿。', `MaleText_loc5`='荒蕪之地真的很熱，但至少還不潮濕。', `MaleText_loc7`='Puede hacer mucho calor en las Tierras Inhóspitas. Pero al menos es un calor seco.' WHERE `ID`=903;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장치... 확인. 동작... 확인. 기능... 확인.', `MaleText_loc4`='检查完毕，一切正常。', `MaleText_loc5`='檢查完畢，一切正常。', `MaleText_loc7`='Comprobando aparatitos... Comprobando chismes... Comprobando timbres...' WHERE `ID`=904;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님, 이곳은 위험합니다. 제가 경비를 서겠습니다.', `MaleText_loc4`='主人，这里很危险。但我要去帮你站岗放哨。', `MaleText_loc5`='主人，這裡很危險。但我要去幫你站崗放哨。', `MaleText_loc7`='Esto es peligroso, maestro. Pero ayudaré a montar la guardia aquí.' WHERE `ID`=905;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 날개를 크게 펄럭이며 시끄럽게 울어대기 시작합니다. 놈의 다음 먹이가 될 거 같은 기분이 듭니다.', `MaleText_loc4`='%s疯狂地扑打着翅膀，发出刺耳的尖叫。你感到今天是劫数难逃了。', `MaleText_loc5`='%s開始瘋狂地撲打牠的翅膀，發出刺耳的尖叫。你有預感自己將成為牠的下一頓大餐。', `MaleText_loc7`='%s empieza a batir sus alas con fuerza y a graznar enérgicamente. Tienes la sensación de que estás a punto de convertirte en su próxima comida.' WHERE `ID`=906;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; $n의 시체를 다 먹고 나자 훨씬 더 조용해 진 것 같습니다.', `MaleText_loc4`='%s吃掉了$n的遗骸，因此它看上去平静了许多。', `MaleText_loc5`='%s在吃完$n的屍體後，看起來平靜了許多。', `MaleText_loc7`='%s parece mucho más tranquilo, ahora que se ha comido los restos de $n.' WHERE `ID`=907;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='숲의 정령들이 동요하고 있습니다...', `FemaleText_loc4`='森林的精魂们感到相当不安……', `FemaleText_loc5`='森林的精靈們感到相當不安...', `FemaleText_loc7`='Los espíritus del bosque están inquietos...' WHERE `ID`=908;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='검은나무 일족이 우리의 신성한 땅을 분열시키고 있어요.', `FemaleText_loc4`='黑木部族正在侵犯我们神圣的领土。', `FemaleText_loc5`='黑木部族正在侵犯我們神聖的領土。', `FemaleText_loc7`='La tribu Bosque Negro perturba nuestra tierra sagrada.' WHERE `ID`=909;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='검은나무 일족에 대해 조치를 취해야만 합니다.', `FemaleText_loc4`='我们必须采取行动来对付黑木部族。', `FemaleText_loc5`='我們必須採取一些行動來對付黑木部族。', `FemaleText_loc7`='Hay que hacer algo con la tribu Bosque Negro.' WHERE `ID`=910;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='부정한 세력이 우리의 신성한 숲을 더럽히고 있습니다.', `FemaleText_loc4`='一股堕落的力量正在玷污我们神圣的森林。', `FemaleText_loc5`='一股墮落的力量正在玷污我們神聖的森林。', `FemaleText_loc7`='Una peste invade nuestro bosque sagrado.' WHERE `ID`=911;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='검은나무 일족이 자연의 번성을 방해하도록 놔둬서는 안 됩니다.', `FemaleText_loc4`='我们绝不能允许黑木部族破坏神圣的大自然。', `FemaleText_loc5`='我們絕不能允許黑木部族破壞神聖的大自然。', `FemaleText_loc7`='No debemos permitir que la tribu Bosque Negro interfiera con el progreso de la naturaleza.' WHERE `ID`=912;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저 숲 깊은 곳에서 위험이 느껴지는군...', `FemaleText_loc4`='我感到树林中隐藏着极大的危险……', `FemaleText_loc5`='我感到樹林中隱藏著極大的危險...', `FemaleText_loc7`='Siento el peligro en el interior de la arboleda...' WHERE `ID`=913;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; $n|1이;가; 가져온 고대 문서를 읽습니다...', `MaleText_loc4`='%s读着$n交给他的古书……', `MaleText_loc5`='%s讀著$n交給他的古書...', `MaleText_loc7`='%s lee el texto antiguo que $n le trajo...' WHERE `ID`=914;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아하! 바로 이거야!', `MaleText_loc4`='哈！就是它了！', `MaleText_loc5`='哈!就是它了!', `MaleText_loc7`='¡Ajá! ¡Eso es!' WHERE `ID`=915;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 친구 카르닉, 살아서 자네를 직접 보고 싶지만 지금은 라그나로스에 대해 얘기해야겠네. 그의 영향력이 확장되고 있어.', `MaleText_loc4`='卡尼克，我的朋友，我真希望能活着再见你一次，但是我们需要讨论一下拉格纳罗斯的问题。他的影响力正在不断扩大。', `MaleText_loc5`='卡尼克，我的朋友，我真希望能活著再見你一次，但是我們需要討論一下拉格納羅斯的問題。他的影響力正在不斷擴大。', `MaleText_loc7`='Karnik, amigo, ojalá pudiera volver a verte con mis propios ojos, pero tenemos que hablar de Ragnaros. Su influencia se extiende.' WHERE `ID`=916;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해머토, 살아서나 죽어서나 자네의 그 명석함과 고집은 여전하구먼그래. 내 오랜 친구여, 내게 할 이야기는 뭔가?', `MaleText_loc4`='铁趾，无论生死，你都表现得一样坦然自若。你能告诉我些什么吗，老朋友？', `MaleText_loc5`='鐵趾，無論生死，你都表現得一樣坦然自若。你能告訴我些什麼嗎，老朋友?', `MaleText_loc7`='Piemartillo, eres tan listo como testarudo, estando vivo o muerto. ¿Qué puedes decirme, viejo amigo?' WHERE `ID`=917;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카르닉, 때가 되면 더 이야기해 주겠네. 우선 이 여행자를 벨그룸 님께 보내게. 그곳에 신경 써야 할 일들이 더 있네.', `MaleText_loc4`='我会尽快地告诉你更多内容，卡尼克。但是首先，请你让这位旅行者去找贝尔格拉姆——还有很多事情没做完呢。', `MaleText_loc5`='我會及時地告訴你更多內容，卡尼克。但是首先，請你把這位旅人送到貝爾格拉姆─那裡有更多事情要做。', `MaleText_loc7`='Te diré más cosas, Karnik, en su debido momento. Pero primero, envía a este viajero a Belgrum. Tienes que ocuparte de unas cuantas cosas más.' WHERE `ID`=918;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; $n에게 받은 물건들을 챙깁니다.', `MaleText_loc4`='%s把$n给他的物品一一放好。', `MaleText_loc5`='%s把$n給他的物品一一放好。', `MaleText_loc7`='%s guarda el objeto que $n le dio.' WHERE `ID`=919;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙습니다, $n. 이 물건들을 사용해 큰일을 할 내 동료는...', `MaleText_loc4`='感谢你，$n。我知道谁可以妥善地使用这个……', `MaleText_loc5`='感謝你，$n。我的朋友將可以妥善地使用這些東西...', `MaleText_loc7`='Gracias, $n. Mis socios harán maravillas con estos...' WHERE `ID`=920;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; $n에게 유물을 받습니다.', `MaleText_loc4`='%s从$n手中接过古代遗物。', `MaleText_loc5`='%s從$n那裡收下了聖物。', `MaleText_loc7`='%s acepta las reliquias de $n.' WHERE `ID`=921;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙소, $n. 이제 야그인의 법전은 당신 것이오.', `MaleText_loc4`='请接受我的谢意，$n。雅格因的笔记是你的了。', `MaleText_loc5`='請接受我的謝意，$n。雅格因的筆記是你的了。', `MaleText_loc7`='Acepta mi gratitud, $n. El diario de Yagyin será tuyo.' WHERE `ID`=922;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 웅크리고 앉아 야그인의 법전을 읽습니다...', `MaleText_loc4`='%s盘腿坐下，开始阅读雅格因的笔记……', `MaleText_loc5`='%s盤腿坐下，開始閱讀雅格因的筆記...', `MaleText_loc7`='%s se agacha para leer el Compendio de Yagyin...' WHERE `ID`=923;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 마법에 의해 피해를 입습니다!', `MaleText_loc4`='%s被魔法击中了！', `MaleText_loc5`='%s被釋放的魔法擊中了!', `MaleText_loc7`='¡%s recibe el influjo de la magia!' WHERE `ID`=924;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, $n. 이제부터 내가 그 신비한 화석을 두고 온 장소를 찾으러 가세나. 나를 따라오시게!', `MaleText_loc4`='好吧，$n，让我们去找找看我到底把那神秘的化石留在哪里了。跟着我！', `MaleText_loc5`='好吧，$n，讓我們去找找看我到底把那神秘的化石留在哪裡了。跟著我!', `MaleText_loc7`='Vale, $n, busquemos el lugar en el que encontré ese fósil misterioso. ¡Seguidme!' WHERE `ID`=925;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대체 내가 그 신비한 화석을 어디다 둔 게지? 아, 아마 저 위에 뒀을지도...', `MaleText_loc4`='我到底把那个神秘的化石放在哪里了？啊，也许在那上面……', `MaleText_loc5`='我到底把那個神秘的化石放在哪裡了?啊，也許在那上面...', `MaleText_loc7`='¿Dónde he puesto ese fósil misterioso? Ah, tal vez ahí...' WHERE `ID`=926;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흐음, 이 위엔 아무것도 없군.', `MaleText_loc4`='唉！上面什么都没有。', `MaleText_loc5`='唉!上面什麼都沒有。', `MaleText_loc7`='Mmm, aquí no hay nada.' WHERE `ID`=927;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여긴 신비한 화석은 없지만. 오... 훌륭한 소설, 가시덤불 골짜기의 푸른 언덕이 있군.', `MaleText_loc4`='这里没有那块神秘的化石……啊，但是有《荆棘谷的青山》的手抄本。多好的一本书啊！', `MaleText_loc5`='這裡沒有那塊神秘的化石...啊，但是有《荊棘谷的青山》的手抄本。多好的一本書啊!', `MaleText_loc7`='Aquí no hay ningún fósil misterioso... Ah, mi ejemplar de Las verdes colinas de Tuercespina. ¡Qué buen libro!' WHERE `ID`=928;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분명히 천막 안에 뒀을 게야!', `MaleText_loc4`='我敢和你打赌，我把那个东西留在帐篷里了！', `MaleText_loc5`='我敢和你打賭，我把那個東西留在帳篷裡了!', `MaleText_loc7`='¡Te apuesto a que lo he dejado en la tienda!' WHERE `ID`=929;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐, 이건 호올리가 머물던 천막인데... 안에 아무것도 없군.', `MaleText_loc4`='哦，等等，那是霍莉的帐篷……但它是空的。', `MaleText_loc5`='哦，等等，那是霍莉的帳篷...但它是空的。', `MaleText_loc7`='Oh, espera, esa es la tienda de Hollee... y está vacía.' WHERE `ID`=930;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흥미롭군... 이전에 이런 건 본 적 없는데...', `MaleText_loc4`='真有趣……之前我一直没有注意到这个……', `MaleText_loc5`='真有趣...之前我一直沒有注意到這個...', `MaleText_loc7`='Interesante... No me había dado cuenta de esto antes...' WHERE `ID`=931;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 이끼 낀 고대의 돌을 조사합니다.', `MaleText_loc4`='%s端详着那块长满苔藓的石头。', `MaleText_loc5`='%s端詳著那塊長滿苔蘚的古老石頭。', `MaleText_loc7`='%s examina la piedra antigua y recubierta de musgo.' WHERE `ID`=932;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아! 저게 바로 내가 찾던 신비한 화석인 것 같네!', `MaleText_loc4`='哦，不对！我是来寻找那块化石的！', `MaleText_loc5`='哦，不對!我是來尋找那塊化石的!', `MaleText_loc7`='¡Oh, espera! ¡Se supone que estoy buscando ese misterioso fósil!' WHERE `ID`=933;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오호, 대단하군.', `MaleText_loc4`='啊，真劲……', `MaleText_loc5`='啊，香料...', `MaleText_loc7`='Ay. Picante.' WHERE `ID`=934;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니야, 이렇게 구석에 화석을 놔두지는 않았지!', `MaleText_loc4`='不，我没有把化石留在这里！', `MaleText_loc5`='不，我沒有把化石留在這裡!', `MaleText_loc7`='No, no dejé el fósil aquí.' WHERE `ID`=935;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 이제야 기억 나는군! 신비한 화석을 호올리에게 줬네. 그녀를 만나 보게나.', `MaleText_loc4`='啊！现在我记起来了！我把那块神秘的化石交给霍莉了！去问问她吧。', `MaleText_loc5`='啊!現在我記起來了!我把那塊神秘的化石交給霍莉了!去問問她吧。', `MaleText_loc7`='¡Ah, ya lo recuerdo! ¡Di el fósil misterioso a Hollee! Pregúntale a ella.' WHERE `ID`=936;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 모든 것을 잊고 다시 일에 전념합니다.', `MaleText_loc4`='%s重拾工作，将周围的一切都抛诸脑后。', `MaleText_loc5`='%s扭頭回去工作，他似乎又忘卻了周圍所有的東西。', `MaleText_loc7`='%s vuelve a su trabajo, ignorando todo lo que le rodea.' WHERE `ID`=937;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 이런! 이게 뭐야? 도와줘!', `MaleText_loc4`='哦，天呀！这是什么？快来帮忙！', `MaleText_loc5`='哦，天呀!這是什麼?快來幫忙!', `MaleText_loc7`='¡Oh, Dios! ¿Qué es esto? ¡Socorro!' WHERE `ID`=938;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 때문에 이 $n|1이;가; 풀려난 것 같네. 놈을 처치하는 걸 도와줘!', `MaleText_loc4`='看来我们发现了这个名叫$n的家伙。帮我把它干掉！', `MaleText_loc5`='我們似乎發現了這個$n。現在幫我殺掉它!', `MaleText_loc7`='Al parecer, hemos descubierto a $n. ¡Ayudadme a $gmatarlo:matarla;!' WHERE `ID`=939;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와줘! 이 $n|1이;가; 날 놓아주지 않아!', `MaleText_loc4`='帮帮我！我甩不掉这个$n！', `MaleText_loc5`='幫幫我!我搞不定這個$n!', `MaleText_loc7`='¡Socorro! ¡$n no me va a soltar!' WHERE `ID`=940;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 $n 녀석도 신비한 화석을 찾고 있는 것 같군. 도와주게나!', `MaleText_loc4`='我感觉这个$n也想要这块神秘的化石。快来帮忙！', `MaleText_loc5`='我感覺這個$n也想要這塊神秘的化石。快來幫忙!', `MaleText_loc7`='Algo me dice que $n también quiere el fósil misterioso. ¡Socorro!' WHERE `ID`=941;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이다;다;! 도와줘!', `MaleText_loc4`='$n！帮帮我！', `MaleText_loc5`='$n!幫幫我!', `MaleText_loc7`='¡$n! ¡Socorro!' WHERE `ID`=942;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 귀찮은 $n 녀석을 내게서 좀 떼어내 주겠나?', `MaleText_loc4`='你能不能帮我搞定这个$n？', `MaleText_loc5`='你能不能幫我搞定這個$n?', `MaleText_loc7`='¿Puedes sacarme a $n de encima?' WHERE `ID`=943;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 땅속에서 힘을 끌어내기 시작합니다.', `MaleText_loc4`='%s开始从地下吸收能量', `MaleText_loc5`='%s開始從地下吸收能量', `MaleText_loc7`='%s comienza a extraer energía de la tierra' WHERE `ID`=944;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 북서쪽을 바라보며 긴 울음을 내지릅니다.', `MaleText_loc4`='%s盯着西北方，发出了一声怒吼。', `MaleText_loc5`='%s盯著西北方，發出了一聲長嘯。', `MaleText_loc7`='%s mira en dirección al noroeste y lanza un aullido interminable.' WHERE `ID`=945;
