UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$g형제:자매;가 가져다 준 재료들은 모두 순수한 재료들이었소. 때문에 이토록 강력한 정화 토템을 만들 수 있었소.', `MaleText_loc4`='你提供的材料非常纯净，$n。这根新的净化图腾相当强大。', `MaleText_loc5`='你提供的材料非常純淨，$n。這根新的淨化圖騰相當強大。', `MaleText_loc7`='Las ofrendas que has presentado fueron puras, $n. Este nuevo tótem de limpieza es fuerte.' WHERE `ID`=1010;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 부족의 불 앞에서 우물돌과 대지열매를 결합하면서 주문을 외우기 시작합니다.', `MaleText_loc4`='%s站在部族之火前，把井石与琥珀颗粒混合起来，然后开始咏唱咒语。', `MaleText_loc5`='%s在部族之火前，一面混合水井石與琥珀顆粒，一面詠唱咒語。', `MaleText_loc7`='%s comienza a cantar a la vez que mezcla las piedras del pozo con las bellotas ámbar ante el Fuego Tribal.' WHERE `ID`=1011;
