UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부름의 양초는 앞에 있는 상자에 있네, $n.', `MaleText_loc4`='从箱子里拿一根诱灵蜡烛，$n。', `MaleText_loc5`='從木箱裡拿一根誘靈蠟燭，$n。', `MaleText_loc7`='Coge una vela de señalización de este cajón, $n.' WHERE `ID`=1013;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살아생전에는 나의 검 아키우스가 아주 쓸모 있었지. 하지만 비참했던 삶에서 자유로워진 지금은 아무런 필요가 없네.', `MaleText_loc4`='我的佩剑阿契厄斯伴随了我一生，但是现在我的灵魂已经脱离了痛苦，我已经不再需要它了。', `MaleText_loc5`='我的佩劍阿契厄斯伴隨了我一生，但是現在我的靈魂已經脫離了痛苦，我已經不再需要它了。', `MaleText_loc7`='Mi espada Archeus me sirvió bien en vida, pero al abandonar mi espíritu esta infeliz existencia, ya no la necesito más.' WHERE `ID`=1014;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 딸에 대한 사랑과 추억은 절대 잊을 수 없을 것이야. 이젠 정의의 이름으로 내 죄를 용서 받을 수 있기를 바라네.', `MaleText_loc4`='我希望能得到我女儿的爱，也希望我犯下的罪恶能够得到宽恕。', `MaleText_loc5`='我希望能得到我女兒的愛，也希望我犯下的罪惡能夠得到寬恕。', `MaleText_loc7`='Me aferraré al amor de mi hija y espero encontrar el perdón bajo la Luz por mis pecados.' WHERE `ID`=1015;
