UPDATE `locales_broadcast_text` SET `MaleText_loc1`='후아!... 후아!... 아! 거의 다 됐었는데. 으윽!... 으, 고통스러워, 고통스럽다고!', `MaleText_loc4`='哇！……哇！……啊啊啊！真受不了。哎哟！……啊呀！你想杀了我么？！', `MaleText_loc5`='哇!...哇!...啊啊啊!真受不了。哎喲!...啊呀!你想殺了我嗎?!', `MaleText_loc7`='¡Uyyyyyy!' WHERE `ID`=1030;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알았다고, 알았어! 내가 이 대단한 물건의 작동 방법을 곧 알아낼 수 있단 말이야.', `MaleText_loc4`='好吧好吧！我想我能找出操作这个东西的办法……', `MaleText_loc5`='好吧好吧!我想我能找出操作這個東西的辦法...', `MaleText_loc7`='¡Está bien, está bien! Creo que sé cómo poner en marcha este cacharro...' WHERE `ID`=1031;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 이제 괜찮아진 것 같군. 날 따라오라고!', `MaleText_loc4`='嗯，我想我知道该怎么做了。跟我来，$n！', `MaleText_loc5`='嗯，我想我知道該怎麼做了。跟我來，$n!', `MaleText_loc7`='Bueno, creo que ahora sí lo he logrado. ¡Sígueme, $n!' WHERE `ID`=1032;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 굴착 현장에서 빠져 나온 것 같군, 그렇지? 그런데 대체 이건 어디다 쓰는 건지, 원...', `MaleText_loc4`='我们好像走出森林了？这到底是怎么一回事……', `MaleText_loc5`='我們好像走出森林了?這到底是怎麼一回事...', `MaleText_loc7`='Parece que hemos salido del bosque, ¿no es así? Me pregunto para qué sirve esto...' WHERE `ID`=1033;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이걸 꼭 톱니항으로 가져가야겠어. 그 무엇도 날 막을 순 없어!', `MaleText_loc4`='我要把这个带到棘齿城去，没有什么东西能阻止我！', `MaleText_loc5`='我要把這個帶到棘齒城去，沒有什麼東西能阻止我!', `MaleText_loc7`='Tengo que llevarlo a Trinquete ¡y nada podrá detenerme!' WHERE `ID`=1034;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐! 도와줘! 이 벌목기가 꼭 살아서 움직이는 것 같아!', `MaleText_loc4`='帮帮我！等等！这个东西好像有自己的思维！', `MaleText_loc5`='幫幫我!等等!這個東西好像有自己的思維!', `MaleText_loc7`='¡Socorro! ¡Espera! ¡Es como si esta cosa tuviera mente propia!' WHERE `ID`=1035;
