UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 죽을 거야, 죽게 될 거라고!', `MaleText_loc4`='我快要死了，我心里很清楚！', `MaleText_loc5`='我快要死了，我心裡很清楚!', `MaleText_loc7`='¡Voy a morir, lo sé!' WHERE `ID`=1037;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에잇! 받아라! 오... 단추를 잘못 누른 것 같은데... 잠깐, 이걸 한 번 눌러 볼까!', `MaleText_loc4`='拿着那个！哦……我肯定是按错了键……等等，试试这个！', `MaleText_loc5`='拿著那個!哦...我肯定是按錯了鍵...等等，試試這個!', `MaleText_loc7`='¡Toma eso! Oh... He debido pulsar el botón equivocado... Espera, ¡prueba este!' WHERE `ID`=1038;
