UPDATE `locales_broadcast_text` SET `MaleText_loc1`='큰일 날 뻔했군! 자, 계속 가자고. 거의 다 왔어.', `MaleText_loc4`='真玄啊！继续前进吧，我们就要到了。', `MaleText_loc5`='好險啊!繼續前進吧，我們就快到了。', `MaleText_loc7`='¡Eso estuvo cerca! Bueno, andando, que ya casi estamos.' WHERE `ID`=1041;
