UPDATE `locales_broadcast_text` SET `MaleText_loc1`='남쪽바다 해적단 놈들이 해안에 진지를 상당하게 구축해 놓은 것 같군. 좀 힘들게 됐구먼...', `MaleText_loc4`='好像有南海海盗在这附近出没，这样事情就有点麻烦了。', `MaleText_loc5`='好像有南海掠劫者在這附近出沒，這樣事情就有點麻煩了。', `MaleText_loc7`='Al parecer, los filibusteros de los Mares del Sur se han atrincherado fuertemente en la costa. La cosa podría ponerse difícil.' WHERE `ID`=1068;
