UPDATE `locales_broadcast_text` SET `MaleText_loc1`='브라이트썬 선장님, 여기 있는 $n|1이;가; 절 구해줬습니다. 당신의 용감한 행동에 선장님께서 보상을 해주실 거요.', `MaleText_loc4`='沙罗萨斯船长，这位$n帮助我重获了自由！$n，我相信船长会因你的勇敢而奖励你的。', `MaleText_loc5`='沙羅薩斯船長，這位$n幫助我重獲了自由!$n，我相信船長會因你的勇敢而獎勵你的。', `MaleText_loc7`='¡Capitán Solbrillante, $n me ha liberado! $n, estoy seguro de que el Capitán recompensará tu valentía.' WHERE `ID`=1071;
