UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠... $n. 이 등껍질로 많은 걸 알 수 있었지만, 의문점도 더 많이 생긴 것 같소...', `MaleText_loc4`='$n。这些甲壳告诉了我很多事情，但同时也带来了更多谜团……', `MaleText_loc5`='$n。這些甲殼告訴了我很多事情，但同時也帶來了更多謎團...', `MaleText_loc7`='$n, estos caparazones me dicen mucho, pero me temo que han surgido muchas más preguntas...' WHERE `ID`=1089;
