UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빌리가 얘기해 줬는데 삑삑이는 위대한 마법사였대요. 근데 주문이 잘못돼서 토끼로 변해 버렸대요.', `MaleText_loc4`='比利说费索曾是个伟大的巫师。但是当他的某一个法术失败了之后，他就被变成了一只兔子。', `MaleText_loc5`='比利說菲爾曾是個偉大的巫師。但是當他的某一個法術失敗了之後，他就被變成了一隻兔子。', `MaleText_loc7`='Billy dice que Fizzles era un gran mago. Pero se convirtió en un conejo cuando le salió mal uno de sus hechizos.', `FemaleText_loc1`='빌리가 얘기해 줬는데 삑삑이는 위대한 마법사였대요. 근데 주문이 잘못돼서 토끼로 변해 버렸대요.', `FemaleText_loc4`='比利说费索曾是个伟大的巫师。但是当他的某一个法术失败了之后，他就被变成了一只兔子。', `FemaleText_loc5`='比利說菲爾曾是個偉大的巫師。但是當他的某一個法術失敗了之後，他就被變成了一隻兔子。', `FemaleText_loc7`='Billy dice que Fizzles era un gran zahorí. Pero se convirtió en un conejo cuando le salió mal uno de sus hechizos. Pero se convirtió en un conejo cuando le salió mal uno de sus hechizos.' WHERE `ID`=1091;
