UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엄마 엄마, 나 쉬야 마려워요.', `MaleText_loc4`='我要上厕所。', `MaleText_loc5`='我要上廁所。', `MaleText_loc7`='Tengo que hacer pis.', `FemaleText_loc1`='엄마 엄마, 나 쉬야 마려워요.', `FemaleText_loc4`='我要上厕所。', `FemaleText_loc5`='我要上廁所。', `FemaleText_loc7`='Tengo que hacer pis.' WHERE `ID`=1095;
