UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진짜예요, 엄마? 운하에 진짜 악어가 살아요?', `MaleText_loc4`='真的吗？运河里真的有鳄鱼吗？', `MaleText_loc5`='真的嗎?運河裡真的有鱷魚嗎?', `MaleText_loc7`='¿Es cierto eso? ¿Es verdad que hay crocoliscos en los canales?', `FemaleText_loc1`='진짜예요, 엄마? 운하에 진짜 악어가 살아요?', `FemaleText_loc4`='真的吗？运河里真的有鳄鱼吗？', `FemaleText_loc5`='真的嗎?運河裡真的有鱷魚嗎?', `FemaleText_loc7`='¿Es cierto eso? ¿Es verdad que hay crocoliscos en los canales?' WHERE `ID`=1098;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엄마, 나 다리 아파.', `MaleText_loc4`='我腿疼！', `MaleText_loc5`='我腿疼!', `MaleText_loc7`='Me duelen los pies.', `FemaleText_loc1`='엄마, 나 다리 아파.', `FemaleText_loc4`='我腿疼！', `FemaleText_loc5`='我腿疼!', `FemaleText_loc7`='Me duelen los pies.' WHERE `ID`=1099;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 계속 같은 길로 가는 거예요?', `MaleText_loc4`='你说，为什么咱们总是沿着这条路线跑？', `MaleText_loc5`='你說，為什麼咱們總是沿著這條路線跑?', `MaleText_loc7`='¿Por qué siempre vamos por el mismo camino?', `FemaleText_loc1`='왜 계속 같은 길로 가는 거예요?', `FemaleText_loc4`='你说，为什么咱们总是沿着这条路线跑？', `FemaleText_loc5`='你說，為什麼咱們總是沿著這條路線跑?', `FemaleText_loc7`='¿Por qué siempre vamos por el mismo camino?' WHERE `ID`=1100;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신선한 빵 팔아요!', `MaleText_loc4`='新鲜的面包啦！', `MaleText_loc5`='新鮮的麵包啦!', `MaleText_loc7`='¡Vendo pan fresco!' WHERE `ID`=1101;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='따뜻하고 건강에 좋은 빵이 있습니다!', `MaleText_loc4`='热乎乎的新鲜面包啦！', `MaleText_loc5`='熱呼呼的新鮮麵包啦!', `MaleText_loc7`='¡Pan caliente y sano!' WHERE `ID`=1102;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='롤빵, 작은 롤빵, 식빵 있어요. 갓 구운 빵입니다!', `MaleText_loc4`='长面包，圆面包，各种各样的面包，都是新鲜出炉的啊！', `MaleText_loc5`='長麵包，圓麵包，各種各樣的麵包，都是新鮮出爐的啊!', `MaleText_loc7`='Panecillos, bollos y pan de toda clase. ¡Pan recién horneado!' WHERE `ID`=1103;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갓 구운 빵 팔아요!', `MaleText_loc4`='新鲜出炉的面包！', `MaleText_loc5`='新鮮出爐的麵包!', `MaleText_loc7`='¡Vendo pan recién horneado!' WHERE `ID`=1104;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='물은 어디에 있죠, 엠마? 물 가져왔어요, 엠마? 내가 아니었다면 저 작자는 물이 어떻게 생겼는지도 몰랐을 테지, 암.', `FemaleText_loc4`='有水吗，艾玛？去弄点水，艾玛？你要是再不去打水，我都快忘了水是什么样的了……', `FemaleText_loc5`='有水嗎，艾瑪?去弄點水，艾瑪?你要是再不去打水，我都快忘了水是什麼樣的了...', `FemaleText_loc7`='¿Dónde está el agua, Emma? Ve a por el agua, Emma. De no ser por mí, esos no sabrían qué aspecto tiene el agua.' WHERE `ID`=1105;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내가 늙어서 물통이나 나르는 것 외에는 할 일이 없는 것처럼 보이나 보군.', `FemaleText_loc4`='我这么多年来好像都没干过比打水更有意义的事情似的！', `FemaleText_loc5`='我這麼多年來好像都沒幹過比打水更有意義的事情似的!', `FemaleText_loc7`='Como si yo no tuviera cosas mejores que hacer a mi edad que llevar cubos de agua de un lado a otro.' WHERE `ID`=1106;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하루에 백 번은 우물까지 가서 물을 길어오는 것 같아. 웃어른을 전혀 공경하지 않는단 말이야.', `FemaleText_loc4`='我一天要走好多趟到水井那边去打水，现在的年轻人啊……', `FemaleText_loc5`='我一天要走好多趟到水井那邊去打水，現在的年輕人啊...', `FemaleText_loc7`='Siento como si fueran cien las caminatas diarias que debo hacer hasta el pozo para recoger agua. Ya no respetan a los mayores, te lo digo yo.' WHERE `ID`=1107;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='물론 혼잣말이야. 이 도시에서 점잖은 대화를 나눌 수 있는 유일한 방법이지.', `FemaleText_loc4`='我只是在自言自语罢了，和这里的其他人说话的时候，我总是得不到应有的尊重。', `FemaleText_loc5`='我只是在自言自語罷了，和這裡的其他人說話的時候，我總是得不到應有的尊重。', `FemaleText_loc7`='Por supuesto que hablo sola. Es la única manera de tener una conversación en esta ciudad.' WHERE `ID`=1108;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='언젠가 그 푸른 옷 입은 놈을 물에 빠뜨려 버릴 거야. 그의 빗자루도 모두 함께 말이지.', `FemaleText_loc4`='我总有一天要把他用那件蓝色的长袍裹起来，和他的扫帚一起扔到河里去。', `FemaleText_loc5`='我總有一天要把他用那件藍色的長袍裹起來，和他的掃帚一起扔到河裡去。', `FemaleText_loc7`='Uno de estos días lo ahogaré con ese ropaje azul. Junto con todas sus escobas.' WHERE `ID`=1109;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이봐, 나이 든 친구들! 여기서 물 길어 나르는 일은 다 내가 하고 있다고.', `FemaleText_loc4`='每天都要累死我！', `FemaleText_loc5`='每天都要累死我!', `FemaleText_loc7`='¡Ay, mi pobre y arrugado trasero! Yo soy la única que acarrea agua por aquí.' WHERE `ID`=1110;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='길에 깔린 이 돌들 때문에 내 발이 패이는 것 같아.', `FemaleText_loc4`='我要上路了。', `FemaleText_loc5`='我要上路了。', `FemaleText_loc7`='Creo que estoy empezando a dejar surcos en las losas.' WHERE `ID`=1111;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전에 이미 본 것 같은데... 난 잠시동안 내가 집에 돌아간 거라고 생각했었소... 역병 전에 집으로 말이지...', `FemaleText_loc4`='有那么一小会儿，我以为自己回家了……在亡灵天灾到来之前的那个家……', `FemaleText_loc5`='有那麼一小會兒，我以為自己回家了...在天譴軍團到來之前的那個家...', `FemaleText_loc7`='He tenido una visión. Por un momento, creí que estaba de nuevo en casa... antes de la peste...' WHERE `ID`=1112;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 네놈이 이제 사라져 나를 화나게 하는구나! 해일의 돌의 진정한 힘을 맛볼 차례다!', `MaleText_loc4`='你彻底地激怒了我！我要让你好好见识一下海潮之石的真正力量！', `MaleText_loc5`='你徹底地激怒了我!我要讓你好好見識一下海潮之石的真正力量!', `MaleText_loc7`='¡Oh, ahora vas y me enfadas! ¡Es hora de ver la verdadera fuerza de la Roca de las Mareas!' WHERE `ID`=1113;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; $n|1과;와; 조용히 대화를 나눈 후 작은 물건을 건넵니다.', `MaleText_loc4`='%s跟$n轻声说着什么，然后塞给$g他:她;一件小东西。', `MaleText_loc5`='%s小聲地和$n交談，然後塞給了$g他:她;一件小東西。', `MaleText_loc7`='%s intercambia unas palabras en voz baja con $n y le entrega un pequeño objeto.' WHERE `ID`=1114;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 탁자에 있는 마법석을 가져가게. 임무를 완수하려면 필요할 게야.', `MaleText_loc4`='从桌上拿一块石头，$n。你会需要它的。', `MaleText_loc5`='從桌上拿一塊石頭，$n。你會需要它的。', `MaleText_loc7`='Coge una losa de la mesa, $n. La necesitarás para tu misión.' WHERE `ID`=1115;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='땅의 기운과 폭풍의 힘, 그리고...', `FemaleText_loc4`='以大地和风暴的力量，以及……', `FemaleText_loc5`='以大地和風暴的力量，以及...', `FemaleText_loc7`='Por la Fuerza de la tierra, el poder de las tormentas y...' WHERE `ID`=1116;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아아아아아!', `FemaleText_loc4`='啊~~~！', `FemaleText_loc5`='啊～～～～!', `FemaleText_loc7`='¡ARRRRRGGGHHH!' WHERE `ID`=1117;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어떻게 된 겁니까, 대지모신이시여? 왜 주문이 실패한 겁니까?', `FemaleText_loc4`='发生什么事情了，大地母亲？为什么我的法术失败了？', `FemaleText_loc5`='發生什麼事情了，大地之母?為什麼我的法術失敗了?', `FemaleText_loc7`='¿Qué ha pasado, Madre Tierra? ¿Por qué ha fallado el hechizo?' WHERE `ID`=1118;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 직실이 왔소. 좋은 물건 다 나가기 전에 어서 와서 구입하라고. 어서 와서 이 물건들을 제일 먼저 둘러볼 수 있는 기회를 잡으라고.', `MaleText_loc4`='嗯，我来了，快过来买我的东西吧！你们不买，另一边那些家伙就要买了！', `MaleText_loc5`='嗯，我來了，快過來買我的東西吧!你們不買，另一邊那些傢伙就要買了!', `MaleText_loc7`='Ya estoy aquí. Venid a comprar mis mercancías y no desaprovechéis la ocasión. Os lo ofrezco antes que a nadie.' WHERE `ID`=1119;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='셀그라가 잠시 의식을 잃었다가 하늘을 올려다봅니다.', `FemaleText_loc4`='瑟格拉神情恍惚地发了会儿呆，然后看着天空。', `FemaleText_loc5`='瑟格拉發了一會兒呆，然後看著天空。', `FemaleText_loc7`='Sergra entra en trance por un momento y luego mira al cielo.' WHERE `ID`=1120;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='알겠습니다, 대지모신이시여.', `FemaleText_loc4`='我明白了，大地母亲。', `FemaleText_loc5`='我明白了，大地之母。', `FemaleText_loc7`='De acuerdo, Madre Tierra.' WHERE `ID`=1121;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에서 더 시간 낭비할 이유가 없군. 유령들한테 돈이 어딨어!', `MaleText_loc4`='别在这儿浪费更多的时间了。鬼魂都是穷鬼！', `MaleText_loc5`='在這浪費時間是沒意義的。鬼魂不會有任何的錢!', `MaleText_loc7`='No tiene sentido perder más tiempo aquí. ¡Los fantasmas no tienen dinero!' WHERE `ID`=1122;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 저질렀군. 여기 사람들이 남녘해안 사람들보다 나은 줄 알았는데... 아마 그들이라면 내 물건들을 다 사 줬을 거라고! 모두 죽어버려서 정말 안 됐군.', `MaleText_loc4`='你终于还是做了。我原以为你比南海镇的那帮家伙要好得多。他们会买走我所有的东西！可惜他们都死了。', `MaleText_loc5`='你竟然這麼做。我原本以為你比南海鎮的那幫傢伙好多了，他們會買走我所有的東西!可惜他們全死光了。', `MaleText_loc7`='Os habéis pasado. Pensé que erais mejores que la gente de Costasur. ¡Ellos habrían comprado todas mis mercancías! Lástima que estén todos muertos.' WHERE `ID`=1123;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대지모신이시여! 제게 이 피비린내 나는 재앙을 없애 버릴 수 있는 힘을 주소서!', `FemaleText_loc4`='大地母亲，请赐予我恢复自然平衡的力量吧！', `FemaleText_loc5`='大地之母，請賜予我恢復自然平衡的力量吧!', `FemaleText_loc7`='¡Madre Tierra, otórgame el poder para deshacer esta sangría!' WHERE `ID`=1124;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마침내 균형이 회복되었다!', `FemaleText_loc4`='平衡已经恢复了！', `FemaleText_loc5`='已經恢復平衡了!', `FemaleText_loc7`='¡Hemos recobrado el equilibrio!' WHERE `ID`=1125;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 이끼로 덮인 심장을 조사합니다...', `MaleText_loc4`='%s仔细检查着徽记……', `MaleText_loc5`='%s檢查著布滿苔蘚的心臟...', `MaleText_loc7`='%s examina el Corazón recubierto de Musgo...' WHERE `ID`=1126;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 이 이끼로 덮인 심장은 꼭 무슨 씨앗처럼 보이는구려!', `MaleText_loc4`='$n，看苔藓下面，这徽记看上去好像一颗种子！', `MaleText_loc5`='$n，看苔蘚下面，這顆心臟看起來好像一顆種子!', `MaleText_loc7`='¡$n, bajo el musgo, este Corazón parece una semilla!' WHERE `ID`=1127;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 준비한 특수한 토양에 이걸 한번 심어 보겠습니다.', `MaleText_loc4`='让我来把它种在我特制的土壤里……', `MaleText_loc5`='讓我來把它種在我特製的土壤裡...', `MaleText_loc7`='Intentemos sembrar en un poco de mi tierra especial, preparada para ello...' WHERE `ID`=1128;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이곳 빛의 대성당은 스톰윈드의 영혼 계몽의 중심이랍니다.', `FemaleText_loc4`='现在大家看到的是光明大教堂，暴风城的精神和宗教中心。', `FemaleText_loc5`='現在大家看到的是聖光大教堂，這裡是暴風城的精神和宗教中心。', `FemaleText_loc7`='Aquí tenemos la Catedral de la Luz, el centro de la iluminación espiritual de Ventormenta.' WHERE `ID`=1129;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이걸 왜 배워야 하나요?', `MaleText_loc4`='我们为什么一定要了解这些东西呢？', `MaleText_loc5`='我們為什麼一定要瞭解這些東西呢?', `MaleText_loc7`='¿Por qué tenemos que aprendernos todo esto?', `FemaleText_loc1`='이걸 왜 배워야 하나요?', `FemaleText_loc4`='我们为什么一定要了解这些东西呢？', `FemaleText_loc5`='我們為什麼一定要瞭解這些東西呢?', `FemaleText_loc7`='¿Por qué tenemos que aprendernos todo esto?' WHERE `ID`=1130;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우와! 역사책에 있는 그림들보다 멋져요.', `MaleText_loc4`='这比光看历史书上的图片要好多了。', `MaleText_loc5`='這比光看歷史書上的圖片要好多了。', `MaleText_loc7`='Es mejor que los dibujos de los libros de historia.', `FemaleText_loc1`='우와! 역사책에 있는 그림들보다 멋져요.', `FemaleText_loc4`='这比光看历史书上的图片要好多了。', `FemaleText_loc5`='這比光看歷史書上的圖片要好多了。', `FemaleText_loc7`='Es mejor que los dibujos de los libros de historia.' WHERE `ID`=1131;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='큰 도서관에 있는 용 해골 보고 싶어요.', `MaleText_loc4`='我要去大图书馆看龙骨。', `MaleText_loc5`='我要去大圖書館看龍骨。', `MaleText_loc7`='Quiero ver el esqueleto de dragón en la gran biblioteca.', `FemaleText_loc1`='큰 도서관에 있는 용 해골 보고 싶어요.', `FemaleText_loc4`='我要去大图书馆看龙骨。', `FemaleText_loc5`='我要去大圖書館看龍骨。', `FemaleText_loc7`='Quiero ver el esqueleto de dragón en la gran biblioteca.' WHERE `ID`=1132;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선생님, 반짝거리는 마법사의 탑은 언제 보러 가나요?', `MaleText_loc4`='老师，我们什么时候去看那个闪光的法师塔呀？', `MaleText_loc5`='老師，我們什麼時候去看那個閃閃發光的法師塔呀?', `MaleText_loc7`='¿Maestro, cuando veremos la centelleante Torre de los Magos?', `FemaleText_loc1`='선생님, 반짝거리는 마법사의 탑은 언제 보러 가나요?', `FemaleText_loc4`='老师，我们什么时候去看那个闪光的法师塔呀？', `FemaleText_loc5`='老師，我們什麼時候去看那個閃閃發光的法師塔呀?', `FemaleText_loc7`='¿Maestro, cuando veremos la centelleante Torre de los Magos?' WHERE `ID`=1133;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 밑에는 지금도 오크 아저씨들이 묻혀 있다고 들었어요.', `MaleText_loc4`='我听说这里还埋着些兽人。', `MaleText_loc5`='我聽說這裡還埋著些獸人。', `MaleText_loc7`='He oído que sigue habiendo orcos enterrados debajo.', `FemaleText_loc1`='그 밑에는 지금도 오크 아저씨들이 묻혀 있다고 들었어요.', `FemaleText_loc4`='我听说这里还埋着些兽人。', `FemaleText_loc5`='我聽說這裡還埋著些獸人。', `FemaleText_loc7`='He oído que sigue habiendo orcos enterrados debajo.' WHERE `ID`=1134;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선생님, 쉬 마려워요!', `MaleText_loc4`='老师，我要上厕所！', `MaleText_loc5`='老師，我要上廁所!', `MaleText_loc7`='¡Maestro, tengo que ir al baño!', `FemaleText_loc1`='선생님, 쉬 마려워요!', `FemaleText_loc4`='老师，我要上厕所！', `FemaleText_loc5`='老師，我要上廁所!', `FemaleText_loc7`='¡Maestro, tengo que ir al baño!' WHERE `ID`=1136;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선생님, 스톰윈드에 나이트 엘프들이 있나요? 나이트 엘프들은 한 번도 못 봤어요.', `MaleText_loc4`='老师，暴风城里有暗夜精灵吗？我以前从来没见过暗夜精灵。', `MaleText_loc5`='老師，暴風城裡有夜精靈嗎?我以前從來沒見過夜精靈。', `MaleText_loc7`='Maestro, ¿hay elfos de la noche en Ventormenta? Nunca he visto elfos de la noche.', `FemaleText_loc1`='선생님, 스톰윈드에 나이트 엘프들이 있나요? 나이트 엘프들은 한 번도 못 봤어요.', `FemaleText_loc4`='老师，暴风城里有暗夜精灵吗？我以前从来没见过暗夜精灵。', `FemaleText_loc5`='老師，暴風城裡有夜精靈嗎?我以前從來沒見過夜精靈。', `FemaleText_loc7`='Maestro, ¿hay elfos de la noche en Ventormenta? Nunca he visto elfos de la noche.' WHERE `ID`=1138;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선생님, 얘가 자꾸 꼬집어요!', `MaleText_loc4`='老师，他一直在戳我！', `MaleText_loc5`='老師，他一直在戳我!', `MaleText_loc7`='¡Profesora, sigue atizándome!', `FemaleText_loc1`='선생님, 얘가 자꾸 꼬집어요!', `FemaleText_loc4`='老师，他一直在戳我！', `FemaleText_loc5`='老師，他一直在戳我!', `FemaleText_loc7`='¡Profesora, sigue atizándome!' WHERE `ID`=1139;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여러분, 이곳이 스톰윈드 왕궁이랍니다. 1차 대전쟁 당시 호드에 의해 파괴된 스톰윈드 성의 폐허 위에 건설된 것이죠.', `FemaleText_loc4`='现在我们看到的是暴风要塞。在第一次兽人战争中，暴风城堡被部落夷为平地，后来人们在废墟上重建了暴风要塞。', `FemaleText_loc5`='現在我們看到的是暴風要塞。在第一次獸人戰爭中，原來的暴風城堡被夷為平地，後來人們在廢墟上重建了暴風要塞。', `FemaleText_loc7`='Aquí está la torre del homenaje del castillo de Ventormenta. Fue construido sobre las ruinas del castillo de Ventormenta, que fue destruido por la Horda durante la primera Gran Guerra.' WHERE `ID`=1140;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='테스트', `FemaleText_loc4`='TEST', `FemaleText_loc5`='TEST', `FemaleText_loc7`='PRUEBA' WHERE `ID`=1141;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 일들이나 해! 곧 배가 완성되어야만 한다.', `MaleText_loc4`='你们这些废物快给我干活去！这艘船必须马上建好。', `MaleText_loc5`='你們這些廢物快給我幹活去!這艘船必須馬上建好。', `MaleText_loc7`='Chusma, a trabajar. El barco tiene que estar listo en breve.' WHERE `ID`=1142;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자다! 놈들을 처치해라! 놈들이 방에 들어가지 못하도록 막아라!', `MaleText_loc4`='入侵者！杀死他们！不要让他们进入房间！', `MaleText_loc5`='入侵者!殺死他們!不要讓他們進入房間!', `MaleText_loc7`='¡Intrusos! ¡Acaben con ellos! ¡No dejen que entren en la habitación!' WHERE `ID`=1143;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음번에도 그렇게 빈둥거리고 있는 게 보이는 날엔, 월급도 없을 줄 알라고!', `MaleText_loc4`='再让我看到有人偷懒，我就剁了他的头！', `MaleText_loc5`='再讓我看到有人偷懶，我就剁了他的頭!', `MaleText_loc7`='¡La próxima vez que vea a alguno de ustedes sin trabajar, le diré a Zumbón que les corte la cabeza!' WHERE `ID`=1144;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서둘러 대포를 완성해야 한다.', `MaleText_loc4`='火炮必须马上完工。', `MaleText_loc5`='火砲必須馬上完工。', `MaleText_loc7`='Los cañones tienen que estar listos en breve.' WHERE `ID`=1145;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 부품들을 배로 옮겨라!', `MaleText_loc4`='把这些东西搬到船上去！', `MaleText_loc5`='把這些東西搬到船上去!', `MaleText_loc7`='¡Llevar esas piezas hacia el barco!' WHERE `ID`=1146;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쉬고 싶은 자가 있나? 아주 안됐군! 어서 일해, 이 멍청이들아!', `MaleText_loc4`='谁说要休息？想都别想！赶快去干活，你们这些蠢货！', `MaleText_loc5`='誰說要休息?想都別想!趕快去幹活，你們這些蠢貨!', `MaleText_loc7`='¿Alguien necesita un descanso? ¡Mala suerte! ¡Al trabajo, patanes!' WHERE `ID`=1147;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 너! 무슨 소린지 알아봐라!', `MaleText_loc4`='你们几个！去看看那边是怎么回事！', `MaleText_loc5`='你們幾個!去看看那邊是怎麼回事!', `MaleText_loc7`='¡Oye, tú! Mira a ver de dónde viene ese ruido.', `FemaleText_loc1`='거기 너! 무슨 소린지 알아봐라!', `FemaleText_loc4`='你们几个！去看看那边是怎么回事！', `FemaleText_loc5`='你們幾個!去看看那邊是怎麼回事!', `FemaleText_loc7`='¡Oye, tú! Mira a ver de dónde viene ese ruido.' WHERE `ID`=1148;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적의 공격이다! 모조리 쓸어 버리자!', `MaleText_loc4`='我们被攻击了！把他们都干掉！', `MaleText_loc5`='我們被攻擊了!把入侵者全都趕出去!', `MaleText_loc7`='¡Nos atacan! ¡A sus puestos, escoria! ¡Hay que rechazar al invasor!', `FemaleText_loc1`='적의 공격이다! 모조리 쓸어 버리자!', `FemaleText_loc4`='我们被攻击了！把他们都干掉！', `FemaleText_loc5`='我們被攻擊了!把入侵者全都趕出去!', `FemaleText_loc7`='¡Nos atacan! ¡A sus puestos, escoria! ¡Hay que rechazar al invasor!' WHERE `ID`=1149;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 겁을 먹고 도망치려고 합니다!', `MaleText_loc4`='%s充满恐惧地想要转身逃跑！', `MaleText_loc5`='%s充滿恐懼地想要轉身逃跑!', `MaleText_loc7`='¡%s intenta huir despavorido!', `FemaleText_loc1`='%s|1이;가; 겁을 먹고 도망치려고 합니다!', `FemaleText_loc4`='%s充满恐惧地想要转身逃跑！', `FemaleText_loc5`='%s充滿恐懼地想要轉身逃跑!', `FemaleText_loc7`='¡%s intenta huir despavorida!' WHERE `ID`=1150;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 전투에서 동료가 쓰러진 것을 보고 분노에 휩싸입니다.', `MaleText_loc4`='%s看到朋友在战斗中倒下，变得非常愤怒！', `MaleText_loc5`='%s看到朋友在戰鬥中倒下，變得非常憤怒!', `MaleText_loc7`='¡%s monta en cólera tras ver a su amigo caer en batalla!', `FemaleText_loc1`='%s|1이;가; 전투에서 동료가 쓰러진 것을 보고 분노에 휩싸입니다.', `FemaleText_loc4`='%s看到朋友在战斗中倒下，变得非常愤怒！', `FemaleText_loc5`='%s看到朋友在戰鬥中倒下，變得非常憤怒!', `FemaleText_loc7`='¡%s monta en cólera tras ver a su amigo caer en batalla!' WHERE `ID`=1151;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 토양에 이끼로 덮인 심장을 심습니다...', `MaleText_loc4`='%s种下了布满苔藓的徽记……', `MaleText_loc5`='%s種下了布滿苔蘚的心臟...', `MaleText_loc7`='%s planta el Corazón recubierto de Musgo...' WHERE `ID`=1152;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선생님, 성기사 분들이 정말로 여기서 훈련을 하나요?', `MaleText_loc4`='圣骑士是在这儿接受训练的吗？', `MaleText_loc5`='聖騎士是不是在這裡訓練的?', `MaleText_loc7`='¿Es cierto que los paladines se instruyen aquí?', `FemaleText_loc1`='선생님, 성기사 분들이 정말로 여기서 훈련을 하나요?', `FemaleText_loc4`='圣骑士是在这儿接受训练的吗？', `FemaleText_loc5`='聖騎士是不是在這裡訓練的?', `FemaleText_loc7`='¿Es cierto que los paladines se instruyen aquí?' WHERE `ID`=1153;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네, 그래요. 성기사와 사제들은 모두 대성당 안에서 기술을 익히고 위대한 진리를 연구하는 거랍니다.', `FemaleText_loc4`='没错，的确是这样的。圣骑士和牧师们就在大教堂里接受真知的洗礼。', `FemaleText_loc5`='沒錯，的確是這樣的。聖騎士和牧師們就在大教堂裡接受真知的洗禮。', `FemaleText_loc7`='Sí, es cierto. Tanto los paladines como los sacerdotes aprenden nuevas habilidades y desentrañan las verdades ocultas tras las paredes de la catedral.' WHERE `ID`=1154;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여러분, 이제 선생님을 따라서 바리안 린 국왕께서 왕좌에 앉아 계시는 왕궁을 보러 가요.', `FemaleText_loc4`='孩子们，跟上，我们马上就能看到瓦里安·乌瑞恩国王陛下和他的王座了。', `FemaleText_loc5`='孩子們，請跟我來，我們馬上就能看到瓦里安·烏瑞恩國王陛下和他的王座了。', `FemaleText_loc7`='Chicos, si me seguís, veremos la torre que alberga el trono en el que está sentado el propio Rey Varian Wrynn.' WHERE `ID`=1155;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 빛나는 과일에서 씨를 빼냅니다...', `MaleText_loc4`='%s从发光的水果中取出种子……', `MaleText_loc5`='%s從發光的水果中取出種子...', `MaleText_loc7`='%s quita las semillas del Fruto Resplandeciente...' WHERE `ID`=1156;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 준비한 토양에서 이 씨들이 잘 자라는지 한번 봅시다.', `MaleText_loc4`='让我们看看这些种子是如何在我准备的土壤里生长的……', `MaleText_loc5`='讓我們看看這些種子是如何在我準備的土壤裡生長的...', `MaleText_loc7`='Vamos a ver cómo crecen estas semillas en la tierra que he preparado...' WHERE `ID`=1157;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 과일에서 빼낸 씨앗을 심습니다.', `MaleText_loc4`='%s种下了水果种子。', `MaleText_loc5`='%s種下了種子。', `MaleText_loc7`='%s planta las semillas del fruto.' WHERE `ID`=1158;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 황급히 그의 화단으로 갑니다.', `MaleText_loc4`='%s快步来到培养槽前。', `MaleText_loc5`='%s很快地來到了他的花盆旁。', `MaleText_loc7`='%s corre hacia su maceta.' WHERE `ID`=1159;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싹이 트고 뿌리를 내려야 할 텐데...', `MaleText_loc4`='我希望这种植物可以顺利生根……', `MaleText_loc5`='我希望這種植物可以順利生根...', `MaleText_loc7`='Espero que esta planta eche raíces...' WHERE `ID`=1160;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='호드를 물리친 후, 인간들은 이곳으로 돌아와서 우리의 생존을 기념해 과거의 위대한 도시를 재건하기 시작했어요.', `FemaleText_loc4`='部落被击败之后，人们回到这里重建这座伟大的城市，纪念那些为保卫我们而献出生命的勇士。', `FemaleText_loc5`='部落被擊敗之後，人們回到這裡開始重建這座偉大的城市，以此來紀念那些為保衛我們而獻出生命的勇士。', `FemaleText_loc7`='Cuando la Horda fue destruida, los hombres regresaron aquí y empezaron a reconstruir la que antaño fuera una gran ciudad, como testamento de nuestra propia supervivencia.' WHERE `ID`=1161;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋아요, 음... 이제 두 차례의 대전쟁 당시 큰 공을 세웠던 영웅들을 기념하기 위해 만든 기념물을 보러 영웅의 계곡으로 가 보겠어요. 자, 선생님을 따라오세요.', `FemaleText_loc4`='好了……现在我们去英雄谷参观那儿的纪念碑，悼念在两次兽人战争中牺牲的英雄们。跟着我，孩子们。', `FemaleText_loc5`='好了，嗯...現在讓我們去參觀獻給在兩次獸人戰爭中的英雄們的紀念碑─英雄谷。跟我來吧。', `FemaleText_loc7`='De acuerdo, ahora vayamos al monumento dedicado a los héroes de las dos Grandes Guerras, el Valle de los Héroes. ¡Seguidme!' WHERE `ID`=1162;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여러분, 놀랍죠? 도시로 들어가는 이는 모두 이 땅의 위대한 영웅들이 위에서 지켜보고 있는 이 아래를 지나가야만 해요.', `FemaleText_loc4`='孩子们，这里是不是十分壮观？所有人都要在这些伟大的英雄的注视下进入暴风城。', `FemaleText_loc5`='孩子們，這裡是不是十分壯觀?所有人都要在這些偉大英雄們的注視下進入暴風城。', `FemaleText_loc7`='Chicos, ¿no os parece sorprendente? Todo aquel que entra en la ciudad debe caminar bajo la atenta mirada de los más grandes héroes de nuestra tierra.' WHERE `ID`=1163;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여러분, 잠시 쉬죠, 학교로 돌아가면 각자 이 전설적인 인물 중 한 명에 대해 발표해 보도록 하겠어요.', `FemaleText_loc4`='多么震撼人心啊！孩子们，回到学校以后，你们都要谈谈对这些英雄人物的看法。', `FemaleText_loc5`='多麼震撼人心啊!孩子們，當我們回到學校以後，你們每個人都要寫一份關於這些英雄人物的報告。', `FemaleText_loc7`='Impresionante. Chicos, cuando regresemos a la escuela, todos presentaréis un informe oral sobre uno de estos héroes legendarios.' WHERE `ID`=1165;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자, 마법사 지구와 빛의 대성당으로 가기 전에 다시 한번 천천히 잘 봐 두도록 하세요.', `FemaleText_loc4`='接下来，我们要去教堂广场看看光明大教堂。', `FemaleText_loc5`='現在，在我們前往神聖區和偉大的聖光大教堂前再好好看一眼。', `FemaleText_loc7`='Ahora echad un vistazo a todo antes de ir al Distrito Sagrado y a la gran Catedral de la Luz.' WHERE `ID`=1166;
