UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오, 이런... 미스트... 어떻게 된 거니...?', `FemaleText_loc4`='天哪……密斯特……发生了什么事情……？', `FemaleText_loc5`='天哪...密斯特...發生了什麼事情...?', `FemaleText_loc7`='Oh, no... Vaya, ¿qué ha pasado...?' WHERE `ID`=1169;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 흙을 뚫고 나옵니다!', `MaleText_loc4`='%s破土而出了！', `MaleText_loc5`='%s破土而出了!', `MaleText_loc7`='¡%s emerge de la tierra!' WHERE `ID`=1174;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 흙을 뚫고 나옵니다.', `MaleText_loc4`='%s破土而出了！', `MaleText_loc5`='%s破土而出了!', `MaleText_loc7`='¡%s emerge de la tierra!' WHERE `ID`=1175;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽여라!!!', `MaleText_loc4`='杀！！！', `MaleText_loc5`='殺!!!', `MaleText_loc7`='¡¡¡MATAR!!!' WHERE `ID`=1176;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; $n|1을;를; 기꺼이 새로운 수호자로 따릅니다.', `MaleText_loc4`='%s象幼兽追随父母般快乐地跟在$n身后。', `MaleText_loc5`='%s快樂地跟隨著$n。', `MaleText_loc7`='%s sigue con alegría a $n como su joven planta que es.' WHERE `ID`=1177;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 $n 보호할 거다!', `MaleText_loc4`='我会保护你的！', `MaleText_loc5`='我會保護你的!', `MaleText_loc7`='¡Te protegeré!' WHERE `ID`=1178;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두 개의 화석 위로 %s|1이;가; 렐루의 돌을 이리저리 맞춰 보기 시작합니다.', `MaleText_loc4`='%s开始摆弄两块化石上的雷鲁之石。', `MaleText_loc5`='%s開始在這兩具化石上調整雷魯之石。', `MaleText_loc7`='%s comienza a manipular la Piedra de Relu sobre los dos fósiles.' WHERE `ID`=1179;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='별의 힘으로! 아... 영혼이 소환되었소!', `MaleText_loc4`='以群星的名义！', `MaleText_loc5`='以群星的名義!靈魂已經被召喚了!', `MaleText_loc7`='¡Por las estrellas! ¡Se ha invocado a un espíritu!' WHERE `ID`=1180;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아까 우리가 본 것은 참으로 과거의 신비라 하지 않을 수 없소! 동시에 미래에 대한 중요한 열쇠이기도 하오!', `MaleText_loc4`='过去的事情谁也说不清，但重要的是我们的未来！', `MaleText_loc5`='過去的事情誰也說不清，但重要的是我們的未來!', `MaleText_loc7`='¡Está claro que es un misterio del pasado! ¡Pero también la llave de nuestro futuro!' WHERE `ID`=1181;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 아만을 이곳으로 부른 자가 누구인가?', `MaleText_loc4`='谁召唤了阿曼？', `MaleText_loc5`='誰召喚了阿曼?', `MaleText_loc7`='¿Quién ha invocado a Aman?' WHERE `ID`=1182;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대들은 과거의 비밀을 밝히려 애쓰고 있구나.', `MaleText_loc4`='啊，你终于带着那些古物回来了。', `MaleText_loc5`='啊，你終於帶著那些古物回來了。', `MaleText_loc7`='Ah, veo que trabajas arduamente con las reliquias del pasado.' WHERE `ID`=1183;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경고하건대 그대를 창조한 자도 잘못을 범할 수 있다.', `MaleText_loc4`='注意，即使是创物之神也可能犯错。', `MaleText_loc5`='注意，即使是創物之神也可能犯錯。', `MaleText_loc7`='Te advierto que incluso tus creadores pueden equivocarse.' WHERE `ID`=1184;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='과거를 너무 깊이 들추다 보면 앞날에 갑작스러운 최후를 맞이할 수도 있느니.', `MaleText_loc4`='对你的过去了解得越多，你的未来就越危险。', `MaleText_loc5`='對你的過去了解得越多，你的未來就越危險。', `MaleText_loc7`='Si escarbas demasiado en tu pasado, tu futuro puede tener un fin repentino.' WHERE `ID`=1185;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 덤불 속에 숨습니다.', `FemaleText_loc4`='%s躲藏在灌木丛中。', `FemaleText_loc5`='%s躲藏在灌木叢中。', `FemaleText_loc7`='%s se oculta entre los arbustos.' WHERE `ID`=1186;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 눈앞에서 사라집니다.', `MaleText_loc4`='%s在你眼前突然消失。', `MaleText_loc5`='%s在你眼前突然消失。', `MaleText_loc7`='%s se disipa ante tus ojos.' WHERE `ID`=1187;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='남은 길은 혼자서도 갈 수 있어요. 고마워요! $n.', `FemaleText_loc4`='我可以自己想办法回去了，$n。谢谢你！', `FemaleText_loc5`='我可以自己想辦法回去了，$n。謝謝你!', `FemaleText_loc7`='Puedo arreglármelas el resto del camino, $n. ¡GRACIAS!' WHERE `ID`=1188;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋아요, 어서 가요!', `FemaleText_loc4`='好的，我们走吧！', `FemaleText_loc5`='好的，我們走吧!', `FemaleText_loc7`='¡Vale, vámonos!' WHERE `ID`=1189;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 숲 속으로 사라집니다.', `FemaleText_loc4`='%s消失在森林中。', `FemaleText_loc5`='%s消失在森林中。', `FemaleText_loc7`='%s desaparece en el bosque.' WHERE `ID`=1190;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 광란 상태에 빠집니다!', `MaleText_loc4`='%s变得狂怒无比！', `MaleText_loc5`='%s變得狂暴起來!', `MaleText_loc7`='¡%s entra en frenesí!' WHERE `ID`=1191;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고독한 은둔자 선술집에서 공짜 술을 마시는 방법은 제게 물어 보십시오!', `MaleText_loc4`='快来问我怎样才能在蓝色隐士获得免费的饮料吧！', `MaleText_loc5`='快來問我怎樣才能在藍色隱士獲得免費的飲料吧!', `MaleText_loc7`='¡Pregúntame cómo conseguir una bebida gratis en El Ermitaño Taciturno!' WHERE `ID`=1192;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고독한 은둔자 선술집에서 공짜 술을 제공합니다!', `MaleText_loc4`='在蓝色隐士有免费的饮料！', `MaleText_loc5`='在藍色隱士有免費的飲料!', `MaleText_loc7`='¡Bebidas gratis en El Ermitaño Taciturno!' WHERE `ID`=1193;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고독한 은둔자 선술집으로 오십시오. 그곳에서는 모두 단골손님으로 대접한답니다!', `MaleText_loc4`='到蓝色隐士去，那里每个人都知道你的名字！', `MaleText_loc5`='到藍色隱士去，那裡每個人都知道你的名字!', `MaleText_loc7`='¡Ve a El Ermitaño Taciturno, allí donde todos saben tu nombre!' WHERE `ID`=1194;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드 최고의 술이 바로 여기 있습니다!', `MaleText_loc4`='暴风城最好的饮料！', `MaleText_loc5`='暴風城最好的飲料!', `MaleText_loc7`='¡Las mejores bebidas de Ventormenta!' WHERE `ID`=1195;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맥주를 마시러 왔다가 분위기에 취해 머물게 되는 곳!', `MaleText_loc4`='过来喝杯啤酒，享受一下这里的欢乐气氛！', `MaleText_loc5`='過來喝杯啤酒，享受一下這裡的歡樂氣氛!', `MaleText_loc7`='¡Venid a por la cerveza y quedaos por el ambiente!' WHERE `ID`=1196;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법 공부로 지치셨다고요? 그럴 때 고독한 은둔자 선술집에 가서 정신이 맑아지는 음료수 한잔 하시기 바랍니다!', `MaleText_loc4`='繁重的魔法研究让你身心疲惫吗？到蓝色隐士放松一下！', `MaleText_loc5`='繁重的魔法研究讓你身心疲憊嗎?到藍色隱士放鬆一下!', `MaleText_loc7`='¿Tus estudios de magia te estresan? ¡Relájate en El Ermitaño Taciturno!' WHERE `ID`=1197;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드에서 유일하게 마법과 영혼이 공존하는 곳, 고독한 은둔자 선술집으로 오십시오!', `MaleText_loc4`='到蓝色隐士来吧，暴风城唯一一个魔法和精神完美结合的地方！', `MaleText_loc5`='到藍色隱士來吧，暴風城唯一一個魔法和精神完美結合的地方!', `MaleText_loc7`='El único lugar de Ventormenta donde se mezclan la magia y el alcohol, ¡todo el mundo al Ermitaño Taciturno!' WHERE `ID`=1198;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기분이 우울하신가요? 그렇다면 고독한 은둔자 선술집으로 오셔서 즐거운 시간을 보내십시오!', `MaleText_loc4`='感到忧郁了？来蓝色隐士放松一下吧！', `MaleText_loc5`='感到憂鬱了?來藍色隱士放鬆一下吧!', `MaleText_loc7`='¿Estás triste? ¡Ven al Ermitaño Taciturno para pasar un buen rato!' WHERE `ID`=1199;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='더우신가요? 그렇다면 돼지와 휘파람 선술집에서 차가운 술로 몸을 식히세요!', `FemaleText_loc4`='天气太热吗？在猪和哨声旅店喝点东西凉快一下吧！', `FemaleText_loc5`='天氣太熱嗎?在豬和哨聲旅店喝點東西涼快一下吧!', `FemaleText_loc7`='¿Tienes calor? ¡Ven a tomar algo refrescante en El Cerdo Borracho!' WHERE `ID`=1200;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='떠들썩한 밤의 파티와 훌륭한 술! 돼지와 휘파람 선술집에서 이 모든 걸 경험해 보세요!', `FemaleText_loc4`='在猪和哨声旅店享受夜晚的喧闹和最好的啤酒！', `FemaleText_loc5`='在豬和哨聲旅店享受夜晚的喧鬧和最好的啤酒!', `FemaleText_loc7`='¡Peleas nocturnas y excelentes bebidas! ¡Todo ello en El Cerdo Borracho!' WHERE `ID`=1201;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='돼지와 휘파람 선술집에서 공짜 맥주를 마셔 보세요!', `FemaleText_loc4`='猪和哨声旅店有免费的啤酒供应！', `FemaleText_loc5`='豬和哨聲旅店有免費的啤酒供應!', `FemaleText_loc7`='¡Todo ello en El Cerdo Borracho!' WHERE `ID`=1202;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='돼지와 휘파람 선술집에서 공짜 술을 마시고 싶으신가요? 제가 안내해 드릴게요!', `FemaleText_loc4`='要想得到猪和哨声旅店的免费啤酒券的话，就赶快来找我！', `FemaleText_loc5`='要想得到豬和哨聲旅店的免費啤酒券的話，就趕快來找我!', `FemaleText_loc7`='¡Id a por una cerveza gratis en El Cerdo Borracho!' WHERE `ID`=1203;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='엘프의 머릿결보다 부드럽고 오크의 팔 보다 강하지요! 스톰윈드 어디에서도 이보다 더 좋은 술은 없답니다!', `FemaleText_loc4`='比精灵更聪慧！比兽人更强壮！暴风城没有比这更好的酒了！', `FemaleText_loc5`='比精靈更聰慧!比獸人更強壯!暴風城沒有比這更好的酒了!', `FemaleText_loc7`='¡Más suaves que un elfo, más fuertes que un orco! ¡No encontraréis mejores bebidas en todo Ventormenta!' WHERE `ID`=1205;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='약한 술은 이제 지겨우시다고요? 돼지와 휘파람 선술집에서 좀 더 독한 술을 마셔 보세요!', `FemaleText_loc4`='你厌倦了那些娘娘腔的法师才喜欢喝的水了？来猪和哨声旅店享受一下真正的男人该喝的酒！', `FemaleText_loc5`='你厭倦了那些娘娘腔的法師才喜歡喝的水了?來豬和哨聲旅店享受一下真正的男人該喝的酒!', `FemaleText_loc7`='¿Cansado de esas bebidas ligeritas para taumaturgos? ¡Prueba algo más fuerte en El Cerdo Borracho!' WHERE `ID`=1206;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오랜 여행에서 돌아오셨나요? 돼지와 휘파람 선술집에서 편안한 휴식을 맛보세요!', `FemaleText_loc4`='刚刚长途旅行归来？在猪和哨声旅店休息放松一下吧！', `FemaleText_loc5`='剛剛長途旅行歸來?在豬和哨聲旅店休息放鬆一下吧!', `FemaleText_loc7`='¿De vuelta de un viaje largo? ¡Descansa y relájate en El Cerdo Borracho!' WHERE `ID`=1207;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='스톰윈드 최고의 술이 있는 곳!', `FemaleText_loc4`='这里有暴风城最好的酒！', `FemaleText_loc5`='這裡有暴風城最好的酒!', `FemaleText_loc7`='¡Las mejores bebidas de Ventormenta!' WHERE `ID`=1208;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 배 고파합니다...', `MaleText_loc4`='%s饿了……', `MaleText_loc5`='%s餓了...', `MaleText_loc7`='%s tiene hambre...' WHERE `ID`=1209;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절벽 폭포는 산을 따라 동쪽, 그리고 약간 북쪽에 있소.', `MaleText_loc4`='峭壁之泉在东边和北边的山脉之间。', `MaleText_loc5`='壁泉瀑布在東邊和北邊的山脈之間。', `MaleText_loc7`='Salto de Fonroca se encuentra en las montañas al Este y Norte.' WHERE `ID`=1210;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙네, $n. 행운을 비네.', `MaleText_loc4`='谢谢你，$n。祝你好运。', `MaleText_loc5`='謝謝你，$n。祝你好運。', `MaleText_loc7`='Gracias, $n. Y suerte.' WHERE `ID`=1211;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불모의 땅에서 최고의 품질을 자랑하는 무기 있다고요!', `MaleText_loc4`='贫瘠之地最好的武器！', `MaleText_loc5`='貧瘠之地最好的武器!', `MaleText_loc7`='¡Aquí están las mejores armas de Los Baldíos!' WHERE `ID`=1212;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오시오! 잿빛 골짜기에서 가장 뛰어난 무기들이 준비돼 있다고요!', `MaleText_loc4`='快来看看！这里有灰谷最好的武器供你选择！', `MaleText_loc5`='快來看看!這裡有梣谷最好的武器供你選擇!', `MaleText_loc7`='¡Anímate! ¡La mejor selección de armas a este lado de Vallefresno!' WHERE `ID`=1213;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리자리크가 파는 물건 중에는 없는 물건이 없습니다. 이 리자리크가 원하시는 모든 무기를 준비했습니다!', `MaleText_loc4`='里扎雷克斯这里有利刃，里扎雷克斯这里有铁锤，里扎雷克斯这里有你需要的所有武器！', `MaleText_loc5`='里札雷克斯這裡有利刃，里札雷克斯這裡有鐵錘，里札雷克斯這裡有你需要的所有武器!', `MaleText_loc7`='Lizzarik tiene cuchillas. Lizzarik tiene mazas. ¡Lizzarik tiene aquí todo lo que tus armas necesitan!' WHERE `ID`=1214;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 서두르십시오! 팔리고 나면 다시는 구할 수 없습니다! 어서 와서 사 가세요!', `MaleText_loc4`='快点行动！限量发售，不要错过了！快来选购你的武器！', `MaleText_loc5`='快點行動!限量發售，不要錯過了!快來選購你的武器!', `MaleText_loc7`='¡Actuen rápido! ¡Cuando se acaben, no habrá más! ¡Adquieran sus armas aquí!' WHERE `ID`=1215;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 황혼의 마법책에서 얻은 양피지를 살펴봅니다...', `MaleText_loc4`='%s研究着从暮光之书上撕下来的羊皮纸……', `MaleText_loc5`='%s研究從暮光秘典上撕下來的羊皮紙...', `MaleText_loc7`='%s estudia el papiro procedente del Escrito Crepuscular...' WHERE `ID`=1216;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방출된 마법이 %s|1을;를; 강타합니다!', `MaleText_loc4`='%s被魔法击中了！', `MaleText_loc5`='%s被釋放的魔法擊中了!', `MaleText_loc7`='¡%s recibe el influjo de la magia!' WHERE `ID`=1217;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음...', `MaleText_loc4`='嗯……', `MaleText_loc5`='嗯...', `MaleText_loc7`='Mmm...' WHERE `ID`=1218;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 명상을 계속합니다...', `MaleText_loc4`='%s陷入了沉思……', `MaleText_loc5`='%s繼續冥想著...', `MaleText_loc7`='%s continúa meditando...' WHERE `ID`=1219;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 명중했는지 살펴보기 위해 과녁을 확인합니다.', `MaleText_loc4`='%s弯下身子仔细察看他的枪。', `MaleText_loc5`='%s彎下身子察看他的彈著點。', `MaleText_loc7`='%s se inclina para examinar su disparo.' WHERE `ID`=1221;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우스로크의 일격이 명중했습니다.', `MaleText_loc4`='阿瑟罗克展示货物', `MaleText_loc5`='亞瑟羅克展示貨物', `MaleText_loc7`='Uthrok disparar buen tiro' WHERE `ID`=1222;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='애스리쿠스가 분노에 가득 차 당신을 가리키며 고막이 찢어질 듯한 고함을 칩니다. 그 후 아무 소리도 들리지 않습니다.', `MaleText_loc4`='埃瑟里克斯指着你大声咆哮，言语实在是不堪入耳。这是你听到的最后的话。', `MaleText_loc5`='埃瑟里克斯指著你大聲咆哮，那些罵人的話實在是不堪入耳。', `MaleText_loc7`='Athrikus te señala mientras te destroza el oído con sus gritos. Es lo último que oyes.' WHERE `ID`=1223;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='드디어 내 영혼이 편히 쉴 수 있게 됐군요. 오, 사랑하는 세렐리안...', `FemaleText_loc4`='我的灵魂终于可以安息了……哦，亲爱的塞瑞利恩……', `FemaleText_loc5`='我的靈魂終於可以安息了...哦，親愛的塞瑞利恩...', `FemaleText_loc7`='Al fin mi alma podrá descansar... Oh, mi amado Cerellean...' WHERE `ID`=1224;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 남동쪽을 향해 흐느껴 운 다음 다시 당신을 쳐다봅니다.', `MaleText_loc4`='%s面朝东南方呜咽了几声后，转过来看着你。', `MaleText_loc5`='%s面向東南方，嗚咽了幾聲之後又轉過來看著你。', `MaleText_loc7`='%s mira al sudeste y lloriquea antes de volver a mirarte.' WHERE `ID`=1225;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 테렌디스의 주의를 끌기 위해 그를 향해 울부짖습니다.', `MaleText_loc4`='%s朝特伦希斯咆哮着，希望引起他的注意。', `MaleText_loc5`='%s朝特倫希斯咆哮著以引起他的注意。', `MaleText_loc7`='%s gruñe a Terenthis para atraer su atención.' WHERE `ID`=1226;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잔혹발톱?! 진정해... 너의 주인 볼코르는 어디 있지?', `MaleText_loc4`='锐爪？！放松点，我的朋友……你的主人沃科尔在哪里？', `MaleText_loc5`='銳爪?!放鬆點，我的朋友...你的主人沃科爾在哪裡?', `MaleText_loc7`='¡¿Zarpadura?! Ahí mismo $gamigo mío:amiga mía;... ¿dónde está tu maestro Volcor?' WHERE `ID`=1227;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 발로 땅을 구르면서 테렌디스를 향해 신음하며 울부짖기 시작합니다.', `MaleText_loc4`='%s朝特伦希斯发出悲鸣，咆哮着用力地刨着地面。', `MaleText_loc5`='%s朝特倫希斯發出悲鳴和咆哮，同時用熊掌跺著地面。', `MaleText_loc7`='%s comienza a gemir y a rugir a Terenthis, al tiempo que da fuertes pisadas con sus enormes patas.' WHERE `ID`=1228;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='워, 워, 진정하라고. 잠시만...', `MaleText_loc4`='放松，放松，我的朋友。等一下……', `MaleText_loc5`='放鬆，放鬆，我的朋友。等一下...', `MaleText_loc7`='¡Guau! Espera. Un momento...' WHERE `ID`=1229;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래... 그만하면 됐어. 이제 무슨 일이 있었는지 말해 봐, 잔혹발톱.', `MaleText_loc4`='很好。现在告诉我发生了什么，锐爪。', `MaleText_loc5`='這樣...應該可以了。很好，現在告訴我發生了什麼事，銳爪。', `MaleText_loc7`='Ahí está... esto deberá servir. Ahora dime qué ha pasado, Zarpadura.' WHERE `ID`=1230;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 테렌디스를 향해 계속 울부짖습니다. 이번에는 테렌디스가 잔혹발톱의 뜻을 알아듣는 것 같습니다.', `MaleText_loc4`='%s继续朝特伦希斯咆哮着，这次德鲁伊似乎理解了这头熊的意思。', `MaleText_loc5`='%s又朝特倫希斯發出咆哮，但這次德魯伊似乎理解了這頭熊的意思。', `MaleText_loc7`='%s ruge aún más a Terenthis, pero esta vez parece que el druida entiende al oso.' WHERE `ID`=1231;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알았어, 네 주인을 도와줄 이를 찾아보지. 이제 돌아가서 주인 곁을 지켜.', `MaleText_loc4`='我明白，朋友。我会找人去帮助你的主人。现在你要回到他那边去，至少离他近一点。', `MaleText_loc5`='我明白，朋友。我會找人去幫助你的主人。現在你要回到他那邊去，至少離他近一點。', `MaleText_loc7`='Ya entiendo, $gamigo mío:amiga mía;. Encontraré a alguien que ayude a tu maestro. Vuelve junto a él ahora, o al menos permanece cerca de él.' WHERE `ID`=1232;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 테렌디스에게 감사의 표시로 울부짖습니다.', `MaleText_loc4`='%s向特伦希斯发出感激的咆哮。', `MaleText_loc5`='%s向特倫希斯發出咆哮以示明白。', `MaleText_loc7`='%s ruge en reconocimiento de Terenthis.' WHERE `ID`=1233;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 당신을 향해 으르렁거린 다음 당신의 냄새를 맡습니다.', `MaleText_loc4`='%s对你咆哮，然后伸出鼻子嗅了嗅你。', `MaleText_loc5`='%s向你發出了咆哮，又仔細地嗅了嗅你。', `MaleText_loc7`='%s gruñe en dirección tuya, antes de olfatearte con calma.' WHERE `ID`=1234;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='플라곤구트가 언젠가는 그 화석을 찾기 위해 사람들을 보낼 거야.', `MaleText_loc4`='我就知道弗拉冈特最后会派人去寻找化石的。', `MaleText_loc5`='我就知道弗拉岡特最後會派人去尋找化石的。', `MaleText_loc7`='Supongo que Gargavino finalmente enviará a alguien a recoger ese fósil.' WHERE `ID`=1235;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 한번 감사하오, $n. 이제 난 길을 따라가겠소. 기회가 되면 테렌디스를 찾아 우리가 탈출했다는 사실을 알려 주시기 바라오.', `MaleText_loc4`='再次感谢你，$n。我现在要上路了。如果可以的话，请你去找特伦希斯，告诉他我已经安全逃脱了。', `MaleText_loc5`='再次感謝你，$n。我現在要上路了。如果可以的話，請你去找特倫希斯，告訴他我已經安全逃脫了。', `MaleText_loc7`='Gracias de nuevo, $n. Ahora me dirigiré al camino. Si puedes, encuentra a Terenthis y hazle saber que escapamos.' WHERE `ID`=1236;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠, 지금이 아니면 영원히 기회가 없을 거요. 일단 길까지 안전하게 다다르면 테렌디스에게 돌아가 우리가 탈출했다는 사실을 알려야 하오, 명심하시오.', `MaleText_loc4`='现在不走更待何时！记住，一旦我们安全地回到大路上，你就回特伦希斯那儿去，让他知道我们已经顺利逃脱了。', `MaleText_loc5`='現在不走更待何時!記住，一旦我們安全地回到大路上，你就回特倫希斯那兒去，讓他知道我們已經順利逃脫了。', `MaleText_loc7`='Bueno, supongo que es ahora o nunca. Recuerda, una vez que lleguemos hasta el camino sanos y salvos, ve a ver a Terenthis para contarle que hemos escapado.' WHERE `ID`=1237;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 모습을 바꾸고 우렁찬 포효와 함께 달려 나갑니다.', `MaleText_loc4`='%s大声咆哮着，变形跑了出去。', `MaleText_loc5`='%s一邊咆哮著，一邊變形然後跑了出去。', `MaleText_loc7`='%s gruñe mientras cambia su forma y sale corriendo.' WHERE `ID`=1238;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 이 귀한 흙을 내 화단에 넣읍시다.', `MaleText_loc4`='现在把这些稀土放到我的培养槽里去……', `MaleText_loc5`='現在把這些稀土放到我的培養槽裡去...', `MaleText_loc7`='Pongamos esta extraña tierra en mi maceta...' WHERE `ID`=1239;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 한번 고맙소, $n. 이 귀한 흙은 내 연구에 큰 도움이 될 거요.', `MaleText_loc4`='再次感谢你，$n。这些稀土对我的实验帮助很大。', `MaleText_loc5`='再次感謝你，$n。這些稀土對我的實驗幫助很大。', `MaleText_loc7`='Gracias de nuevo, $n. Esta extraña tierra me resultará muy útil para mis experimentos.' WHERE `ID`=1240;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 흥분하여 울부짖으며 볼코르에게 달려갑니다. 그의 주인에게 다다르자 얼굴을 핥습니다.', `MaleText_loc4`='%s激动地大声咆哮，快步奔向沃科尔。一跑到主人面前，它就迫不及待地伸出舌头去舔主人的脸。', `MaleText_loc5`='%s激動地大聲咆哮，快步奔向沃科爾。一跑到主人面前，牠就迫不及待地伸出舌頭去舔主人的臉。', `MaleText_loc7`='%s ruge agitado mientras ataca a Volcor. Cuando llega hasta donde está su maestro, Zarpadura lame su cara.' WHERE `ID`=1241;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 그만 가 보십시오, $n.', `MaleText_loc4`='解散，$n。', `MaleText_loc5`='解散，$n。', `MaleText_loc7`='Retírate, $n.' WHERE `ID`=1242;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 해냈소. 테렌디스를 찾아 우리가 무사하다는 사실을 알려 줘야 한다는 걸 잊지 마시오. 다시 한번 고맙소.', `MaleText_loc4`='我们成功了，朋友。请找到特伦希斯，告诉他我们安全了。再次感谢你。', `MaleText_loc5`='我們成功了，朋友。請找到特倫希斯，告訴他我們安全了。再次感謝你。', `MaleText_loc7`='Lo logramos, $gamigo mío:amiga mía;. No olvides buscar a Terenthis y hacerle saber que estamos a salvo. Gracias de nuevo.' WHERE `ID`=1243;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나도 널 보게 돼 기뻐! 낯선 자라고 해서 무조건 경계할 필요는 없는 것 같군. 당신에게 테렌디스가 보상을 해 줄 거요.', `MaleText_loc4`='锐爪，我也很高兴能见到你！看来并非所有陌生人都是有敌意的，对吧？特伦希斯一定会好好地奖赏这位冒险者的。', `MaleText_loc5`='銳爪，我也很高興能見到你!看來並非所有陌生人都是有敵意的，對吧?特倫希斯一定會好好地獎賞這位冒險者的。', `MaleText_loc7`='¡A mí también me alegra verte! Después de todo, no hay que temer a todos los extraños, ¿verdad, Grim? Terenthis recompensará a sus aventureros como es debido.' WHERE `ID`=1244;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 소리는 뭐였지? 울부짖는 소리 같았는데...', `MaleText_loc4`='那是什么声音？听起来像什么动物的吼叫声。', `MaleText_loc5`='那是什麼聲音?聽起來像什麼動物的吼叫聲。', `MaleText_loc7`='¿Qué ha sido ese ruido? Parecía un rugido.' WHERE `ID`=1245;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 잔혹발톱에게 주문을 걸기 시작합니다.', `MaleText_loc4`='%s开始对锐爪施放法术。', `MaleText_loc5`='%s開始對著銳爪施展一個法術。', `MaleText_loc7`='%s comienza a lanzar un hechizo a Zarpadura.' WHERE `ID`=1246;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 당장 시작해야겠소, $n.', `MaleText_loc4`='我马上就出发，$n。', `MaleText_loc5`='我馬上就出發，$n。', `MaleText_loc7`='Tengo que empezar ahora mismo, $n.' WHERE `ID`=1247;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠... 내 실패랑 바늘이 어디 있었던가? 아! 여기 있었군그래.', `MaleText_loc4`='嗯……我的针线在哪里？啊！在这里……', `MaleText_loc5`='嗯...我的針線在哪裡?啊!在這裡...', `MaleText_loc7`='Veamos... ¿dónde estaban el hilo y la aguja? ¡Ah! Aquí están...' WHERE `ID`=1248;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 망토를 건네 주면서 주문을 걸기 시작합니다.', `MaleText_loc4`='%s在你取走披风的同时开始施放法术。', `MaleText_loc5`='%s在你取走披風的同時開始施展一個法術。', `MaleText_loc7`='%s comienza a lanzar un hechizo mientras le quitas la capa.' WHERE `ID`=1249;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 온다!', `MaleText_loc4`='他们来了！', `MaleText_loc5`='他們來了!', `MaleText_loc7`='¡Aquí vienen!' WHERE `ID`=1250;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 사악한 놈들을 반드시 물리칠 것이오!', `MaleText_loc4`='我们一定可以战胜这些邪恶的生物！', `MaleText_loc5`='我們一定可以戰勝這些邪惡的生物!', `MaleText_loc7`='¡Podemos vencer a estas hediondas criaturas!' WHERE `ID`=1251;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전장에서 죽는 것은 두렵지 않소!', `MaleText_loc4`='即便是死，也要死得轰轰烈烈！', `MaleText_loc5`='即便是死，也要死得轟轟烈烈!', `MaleText_loc7`='¡Al menos nos ganaremos el derecho a morir!' WHERE `ID`=1252;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='포기하지 말고 목숨을 걸고 싸우시오!', `MaleText_loc4`='不要放弃！誓死奋战！', `MaleText_loc5`='不要放棄!誓死奮戰!', `MaleText_loc7`='¡No te rindas! ¡Lucha hasta la muerte!' WHERE `ID`=1253;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 돌진하여 공격합니다!', `MaleText_loc4`='%s发起了冲锋！', `MaleText_loc5`='%s發起了衝鋒!', `MaleText_loc7`='¡%s carga!', `FemaleText_loc1`='%s|1이;가; 돌진하여 공격합니다!', `FemaleText_loc4`='%s发起了冲锋！', `FemaleText_loc5`='%s發起了衝鋒!', `FemaleText_loc7`='¡%s carga!' WHERE `ID`=1254;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 분을 깨우는 의식을 시작하기 전에 준비가 필요하오. 당신이 날 지켜 줘야 하오!', `MaleText_loc4`='在唤醒仪式开始前我必须做好必要的准备。你要保护我！', `MaleText_loc5`='在喚醒儀式開始前我必須做好必要的準備。你要保護我!', `MaleText_loc7`='Debo realizar los preparativos necesarios antes de iniciar el ritual del despertar. ¡Debes protegerme!' WHERE `ID`=1255;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 동굴은 한때 불모의 땅의 재번영에 대한 약속의 신전이었소. 지금은 악몽의 소굴이지만...', `MaleText_loc4`='这些洞穴曾经是一座神殿，是贫瘠之地万物生长的保证。现在那里简直就是个地狱。', `MaleText_loc5`='這些洞穴曾經是一座神殿，是貧瘠之地萬物生長的保證。現在那裡簡直就是夢魘。', `MaleText_loc7`='Estas cavernas fueron en su día un templo de promisión para el resurgimiento en Los Baldíos. Ahora se han convertido en los corredores de las pesadillas.' WHERE `ID`=1256;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 가야 하오. 악몽에서 나랄렉스 님을 구하려면 해야 할 일이 많소.', `MaleText_loc4`='过来，我们一定要继续下去。在我们把纳拉雷克斯从噩梦中拯救出来之前还有很多事情要做。', `MaleText_loc5`='過來，我們一定要繼續下去。在我們把納拉雷克斯從夢魘中拯救出來之前還有很多事情要做。', `MaleText_loc7`='Ven. Debemos continuar. Hay mucho que hacer antes de poder sacar a Naralex de su pesadilla.' WHERE `ID`=1257;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 화염 마법진 안에서 살해당한 송곳니 드루이드의 영혼을 추방시킬 주문을 걸어야 하오.', `MaleText_loc4`='我必须在这个火焰法阵中使用法术来驱逐那些德鲁伊的灵魂。', `MaleText_loc5`='我必須在這個火焰法陣中使用法術來驅逐那些已故的毒牙之王靈魂。', `MaleText_loc7`='Con este círculo de fuego, lanzaré el hechizo para desterrar los espíritus de los Nobles del Colmillo fallecidos.' WHERE `ID`=1258;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동굴이 정화되었소. 이제 나랄렉스의 안식처로 갑시다!', `MaleText_loc4`='这些洞穴已经被净化了，现在我们得赶去纳拉雷克斯的藏身之地！', `MaleText_loc5`='這些洞穴已經被淨化了，現在我們得趕去納拉雷克斯的藏身之地!', `MaleText_loc7`='Las Cuevas han sido purificadas. ¡Nos vamos a la Cámara de Naralex!' WHERE `ID`=1259;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이쪽으로 내려가야 하오. 조심하시오, 친구. 나랄렉스께서 악몽 속에서 몸부림치고 계시는게 느껴지오.', `MaleText_loc4`='这边走。小心点，朋友。我感觉到纳拉雷克斯正在被噩梦折磨……', `MaleText_loc5`='這邊走。小心點，朋友。我感覺到納拉雷克斯正在被噩夢折磨...', `MaleText_loc7`='Por aquí. Tengan cuidado, amigos. Percibo cómo Naralex se agita en sueños...' WHERE `ID`=1260;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 샘에서 신성한 물을 길어 타락한 드루이드의 피와 섞어야 하오.', `MaleText_loc4`='我要从这里的喷泉中收集圣水，把它与那些堕落德鲁伊的血液混合起来。', `MaleText_loc5`='我要從這裡的噴泉中收集聖水，把它與那些墮落德魯伊的血液混合起來。', `MaleText_loc7`='A partir de esta primavera recogeré las aguas sagradas con las que mezclaré la sangre de los druidas caídos.' WHERE `ID`=1261;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 필요한 것이 준비되었으니, 계속합시다.', `MaleText_loc4`='现在我有了必需的东西，继续进行下一步吧。', `MaleText_loc5`='現在我有了必需的東西，繼續進行下一步吧。', `MaleText_loc7`='Ahora tengo lo que necesitaba. Continuemos.' WHERE `ID`=1262;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 복도 너머에 나랄렉스께서 발작을 일으키는 고통스러운 잠에 빠져 계시오. 너무 늦기 전에 그 분을 깨우러 갑시다.', `MaleText_loc4`='纳拉雷克斯就在这个走廊的尽头沉睡着。我们要赶快唤醒他，否则就太晚了。', `MaleText_loc5`='納拉雷克斯就在這個走廊的盡頭沉睡著。我們要趕快喚醒他，否則就太晚了。', `MaleText_loc7`='Tras este pasillo, Naralex yace en un sueño intermitente. Vamos a despertarle antes de que sea demasiado tarde.' WHERE `ID`=1263;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용감한 이들이여, 나랄렉스 님을 구하고 이 재앙을 끝내기 위해 에메랄드의 꿈으로 들어갈 때에 나를 지켜 주시오.', `MaleText_loc4`='在我进入翡翠梦境拯救纳拉雷克斯的时候，你一定要保护好我！', `MaleText_loc5`='勇敢的靈魂們，在我進入翡翠夢境拯救納拉雷克斯的時候，你一定要保護好我!', `MaleText_loc7`='¡Protegedme, almas valientes, mientras escarbo en el Sueño Esmeralda para rescatar a Naralex y acabar con esta corrupción!' WHERE `ID`=1264;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 나랄렉스에게 자각의 의식을 행하기 시작합니다.', `MaleText_loc4`='%s开始进行唤醒纳拉雷克斯的仪式。', `MaleText_loc5`='%s開始進行喚醒納拉雷克斯的儀式。', `MaleText_loc7`='%s comienza a realizar el ritual del despertar con Naralex.' WHERE `ID`=1265;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[PH] This is a placeholder action until i can cancel channeling my spell.', `MaleText_loc4`='[PH]这是一个占位符动作，直到我取消我的咒符。', `MaleText_loc5`='[PH]這是一個佔地者動作，直到我取消我的法術。', `MaleText_loc7`='[PH] This is a placeholder action until i can cancel channeling my spell.' WHERE `ID`=1266;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마침내! 나랄렉스께서 악몽에서 깨어나셨소.', `MaleText_loc4`='纳拉雷克斯终于从噩梦中醒过来了！', `MaleText_loc5`='納拉雷克斯終於從夢魘中醒過來了!', `MaleText_loc7`='¡Al fin! Naralex despierta de la pesadilla.' WHERE `ID`=1267;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 악몽 속에서 고통으로 몸부림칩니다.', `MaleText_loc4`='%s在噩梦中辗转反侧。', `MaleText_loc5`='%s在噩夢中輾轉反側。', `MaleText_loc7`='%s da vueltas intermitentemente en un sueño agitado.' WHERE `ID`=1268;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 고통으로 몸부림칩니다. 그의 신도가 꿈속으로 들어간 것 같습니다.', `MaleText_loc4`='%s痛苦地挣扎着。信徒们似乎快要打进来了。', `MaleText_loc5`='%s痛苦地扭動著。侍徒似乎快要喚醒他了。', `MaleText_loc7`='%s se retuerce de dolor. El Discípulo parece penetrar en la defensa enemiga.' WHERE `ID`=1269;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 끔찍한 꿈을 꿉니다. 어둠침침한 물속에서 무언가 꿈틀댑니다.', `MaleText_loc4`='%s梦见了可怕的场景，一些东西在黑暗的水下搅动着。', `MaleText_loc5`='%s夢見了可怕的場景，有些東西在混濁的水底攪動著。', `MaleText_loc7`='%s tiene en sueños una espantosa visión. Algo se mueve bajo las turbias aguas.' WHERE `ID`=1270;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마침내 내가 깨어났도다!', `MaleText_loc4`='我终于醒来了！', `MaleText_loc5`='我終於醒了!', `MaleText_loc7`='¡ESTOY DESPIERTO AL FIN!' WHERE `ID`=1271;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 드디어 끔찍한 악몽에서 풀려났구나! 고맙다, 내 충성스러운 신도여, 그리고 너의 용감한 동료에게도 감사를 전한다.', `MaleText_loc4`='啊，我终于从可怖的噩梦中被拉回来了！谢谢你，我忠诚的信徒，还有你勇敢的同伴。', `MaleText_loc5`='啊，我終於從恐怖的夢魘中被拉回來了!謝謝你，我忠誠的侍徒，還有你勇敢的同伴。', `MaleText_loc7`='¡Ah, al fin liberado de una pavorosa pesadilla! Te lo agradezco, mi leal Discípulo, a ti y a tus valientes compañeros.' WHERE `ID`=1272;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공격 받고 있소! 이 $n 놈을 막아주시오!', `MaleText_loc4`='上啊！帮我把这个$n干掉！', `MaleText_loc5`='上啊!幫我把這個$n幹掉!', `MaleText_loc7`='¡Me atacan! ¡Ayudadme a sacarme a $n de encima!' WHERE `ID`=1273;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 $n 놈을 처치해 주시오! 난 나랄렉스 님을 깨울 준비를 해야 하오!', `MaleText_loc4`='干掉这个该死的$n！我要准备唤醒纳拉雷克斯了！', `MaleText_loc5`='幹掉這個該死的$n!我要準備喚醒納拉雷克斯了!', `MaleText_loc7`='¡Encárgate de esto, $n! ¡Necesito prepararme para despertar a Naralex!' WHERE `ID`=1274;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 혼자서는 이 $n 놈을 상대할 수 없소! 도와주시오!', `MaleText_loc4`='我一个人解决不了这个$n！救命啊！', `MaleText_loc5`='我一個人解決不了這個$n!救命啊!', `MaleText_loc7`='¡No puedo con $n yo solo! ¡Socorro!' WHERE `ID`=1275;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 $n 놈은 나랄렉스 님의 악몽에서 나온 악마의 앞잡이가 분명하오!', `MaleText_loc4`='毫无疑问，这个$n是从纳拉雷克斯的噩梦里跑出来的！', `MaleText_loc5`='毫無疑問，這個$n是從納拉雷克斯的夢魘裡跑出來的!', `MaleText_loc7`='¡$n sin duda forma parte de la pesadilla de Naralex!' WHERE `ID`=1276;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와주시오!', `MaleText_loc4`='救命啊！', `MaleText_loc5`='救命啊!', `MaleText_loc7`='¡Socorro!' WHERE `ID`=1277;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아나야? 내가 지금 꿈을 꾸고 있는 건가? 정말 당신이오?', `MaleText_loc4`='安娜雅……？我的双眼没有欺骗我吗？真的是你吗？', `MaleText_loc5`='安娜雅...?我的雙眼沒有欺騙我嗎?真的是你嗎?', `MaleText_loc7`='¿Anaia?... ¿Me engañan mis ojos? ¿Eres tú de verdad?' WHERE `ID`=1278;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리에겐 지나간 세월이 너무 가혹했던 것 같아요. 내 사랑, 결국 이렇게 당신과 다시 마주하게 되었군요.', `FemaleText_loc4`='岁月对我和你都很残酷，我的爱人……但最后我们还是重逢了。', `FemaleText_loc5`='歲月對我和你都很殘酷，我的愛人...但最後我們還是重逢了。', `FemaleText_loc7`='Él ha sido cruel con nosotros, amor mío, pero ten por seguro que ahora sí permaneceremos unidos.' WHERE `ID`=1279;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천 년을 떨어져 지내고 난 후에도 이 정도밖에 허락하지 않다니... 가혹한 운명이 너무나 원망스럽구려.', `MaleText_loc4`='命运是如此残酷，它让我们在分别了数千年之后才能重逢……', `MaleText_loc5`='命運是如此殘酷，它讓我們在分別了數千年之後才能重逢...', `MaleText_loc7`='El destino ha sido muy cruel al permitirnos volver a estar juntos solo tras miles de años de separación...' WHERE `ID`=1280;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 미워하는 거요, 내 사랑? 그 고통스러운 불행의 속박에서 당신의 영혼을 풀어주기 위해서 다른 이의 손을 빌려 당신을 해칠 수밖에 없었던 나를...', `MaleText_loc4`='我的爱人，你恨我吗？我在万般无奈之下摧毁了你的躯壳，因为只有这样才能让你从痛苦中永久地解脱。', `MaleText_loc5`='我的愛人，你恨我嗎?我在萬般無奈之下摧毀了你的軀殼，因為只有這樣才能讓你從痛苦中永久地解脫。', `MaleText_loc7`='¿Me odias, amor mío? Por haber tenido que destruir tu forma viviente y por liberar tu espíritu de tan triste cautiverio...' WHERE `ID`=1281;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나 때문에 마음 아파하지 마세요, 내 사랑. 당신은 나를 속박에서 자유롭게 해주었고... 이제 저는 당신을 더욱 깊게 사랑하게 되었어요.', `FemaleText_loc4`='亲爱的，不要为此而感到内疚。你使我从无尽的苦楚和折磨中解脱了出来，我只会为此而更加爱你。', `FemaleText_loc5`='親愛的，不要為此而感到內疚。你使我從無盡的苦楚和折磨中解脫了出來，我只會為此而更加愛你。', `FemaleText_loc7`='No permitas que esto atormente tu corazón, amor mío. Me has liberado de la esclavitud y por ello te amo más aún.' WHERE `ID`=1282;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='슬프게도, 재회의 시간도 곧 끝나겠군요... 나를 이 세계에 묶고 있는 끈이 약해지고 있어요. 나를 먼 곳으로 데려 가려 하네요...', `FemaleText_loc4`='但是，即使是这经过数千年的分离才换来的重逢也是如此短暂……我和这个世界的联结正在逐渐减弱，我正在慢慢地离开它……离开你……', `FemaleText_loc5`='但是，即使是這經過數千年的分離才換來的重逢也是如此短暫...我和這個世界的聯結正在逐漸減弱，我正在慢慢地離開它...離開你...', `FemaleText_loc7`='Desafortunadamente, esto también debe interrumpirse... Los lazos que me atan a este mundo se debilitan y me arrastran...' WHERE `ID`=1283;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘 있어요, 세렐리안. 다시 만날 때까지...', `FemaleText_loc4`='再见了，塞瑞利恩，我的爱人。我们终能再见……', `FemaleText_loc5`='再見了，塞瑞利恩，我的愛人。我們終能再見...', `FemaleText_loc7`='Adiós, Cerellean, hasta que volvamos a reunirnos...' WHERE `ID`=1284;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 남긴 부드러운 목소리가 안갯속으로 사라집니다. "제가 언제나 당신만을 사랑한다는 사실을 잊지 마세요..."', `FemaleText_loc4`='%s柔和的声音在薄雾中轻轻回响，“我永远爱你……”', `FemaleText_loc5`='%s那柔和的聲音在薄霧中輕輕迴響，「你要知道我永遠愛你...」', `FemaleText_loc7`='La suave voz de %s se desvanece entre la niebla, "No olvides que siempre te amaré...""' WHERE `ID`=1285;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 아나야... 아나야! 나를 떠나지 마시오! 제발...', `MaleText_loc4`='不！安娜雅……安娜雅！请不要离开我！不……', `MaleText_loc5`='不!安娜雅...安娜雅!請不要離開我!不...', `MaleText_loc7`='¡No! Anaia... ¡Anaia! ¡No me abandones! Por favor...' WHERE `ID`=1286;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게... 나더러 당신 없이 이 세상을 살아가란 말이오, 내 사랑...', `MaleText_loc4`='怎么办，我的爱人？没有你，我怎么办……没有你……我如何有勇气在这个世界上生存……', `MaleText_loc5`='怎麼辦，我的愛人?沒有你，我怎麼辦...沒有你...我如何有勇氣在這個世界上生存...', `MaleText_loc7`='¿Cómo, amor mío? ¿Cómo encontraré fuerzas para enfrentarme a las edades del mundo sin ti a mi lado...?' WHERE `ID`=1287;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; $n에게 손을 흔듭니다.', `MaleText_loc4`='%s向$n挥了挥手。', `MaleText_loc5`='%s向$n揮了揮手。', `MaleText_loc7`='%s saluda con la mano a $n.' WHERE `ID`=1288;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 가시오, $n. 가서 볼코르를 찾으시오. 그리고 망토를 쓰면 대화만 할 수 있소. 누군가와 맞서 싸우게 될 경우 그대를 보호하는 마법이 사라진다는 사실을 명심하시오.', `MaleText_loc4`='现在出发，$n。去找沃科尔……记着，除了交谈以外，与任何人交流都会使你身上的魔法保护失效。', `MaleText_loc5`='現在出發，$n。去找沃科爾...記著，除了交談以外，與任何人交流都會使你身上的魔法保護失效。', `MaleText_loc7`='Ahora vete, $n. Encuentra a Volcor... y recuerda: la magia que te protege fallará si te mezclas con otros. Solo puedes hablar con ellos.' WHERE `ID`=1289;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 야영지의 방문자를 빤히 쳐다봅니다.', `MaleText_loc4`='%s仔细检查着营地的参观者。', `MaleText_loc5`='%s端詳著營地的訪客。', `MaleText_loc7`='%s inspecciona el campamento de los visitantes.' WHERE `ID`=1290;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 어서 오시오.', `MaleText_loc4`='啊，欢迎您，$g先生:我亲爱的女士;！', `MaleText_loc5`='啊，歡迎您，$g先生:我親愛的女士;!', `MaleText_loc7`='Ah. Recibid mi bienvenida, $gseñor:mi señora;' WHERE `ID`=1291;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서둘러 움직여야 하네. 아우버다인은 그리 멀지 않지만 많은 적들이 숲에서 잠복하고 있네.', `MaleText_loc4`='我们必须赶快行动。奥伯丁离这里不远，但是有很多敌人潜伏在森林里。', `MaleText_loc5`='我們必須趕快行動。奧伯丁離這裡不遠，但是有很多敵人潛伏在森林裡。', `MaleText_loc7`='Tenemos que desplazarnos rápidamente. Auberdine no está demasiado lejos, pero demasiados enemigos acechan en el bosque.' WHERE `ID`=1292;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='각오해라. 이 쓰레기 같은 성기사!', `MaleText_loc4`='准备去死吧，废物圣骑士！', `MaleText_loc5`='準備去死吧，廢物聖騎士!', `MaleText_loc7`='¡Prepárate para morir, escoria!' WHERE `ID`=1293;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 발견한 그 이교도 조직에서 보낸 암살자로군. 다른 놈들이 우리를 발견하기 전에 어서 가세나.', `MaleText_loc4`='刺客……最好在他们找到我们之前快点离开这里。', `MaleText_loc5`='刺客...最好在他們找到我們之前快點離開這裡。', `MaleText_loc7`='Asesinos de esa secta que habéis encontrado... Vámonos antes de que otro nos encuentre aquí.' WHERE `ID`=1294;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에체야키의 영혼의 힘이 그대 안에 흐르고 있네, $n.', `MaleText_loc4`='埃其亚基的灵魂之力在你身上流动，$n。', `MaleText_loc5`='埃其亞基的靈魂之力在你身上流動，$n。', `MaleText_loc7`='Te inunda el espíritu de Echeyakee, $n.' WHERE `ID`=1295;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 기지개를 켜며 크게 하품을 합니다.', `FemaleText_loc4`='%s伸了个懒腰，打了一个长长的哈欠。', `FemaleText_loc5`='%s伸了個懶腰，打了一個長長的哈欠。', `FemaleText_loc7`='%s se estira y suelta un gran bostezo.' WHERE `ID`=1296;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이샤무헤일의 분노가 자네 안에 흐르고 있네, $n.', `MaleText_loc4`='伊沙姆哈尔的愤怒流经你的身体，$n。', `MaleText_loc5`='伊沙姆哈爾的憤怒流經你的身體，$n。', `MaleText_loc7`='La furia de Ishamuhale te invade, $n.' WHERE `ID`=1297;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라코타마니가 자네 안에서 크게 외치고 있네, $n.', `MaleText_loc4`='拉克塔曼尼的力量与你同在，$n。', `MaleText_loc5`='拉克塔曼尼的力量與你同在，$n。', `MaleText_loc7`='Lakota''mani retumba en tu interior, $n.' WHERE `ID`=1298;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오와탄카의 속력이 자네와 함께할 것이네, $n.', `MaleText_loc4`='你具有了奥瓦坦卡的速度，$n。', `MaleText_loc5`='你具有了奧瓦坦卡的速度，$n。', `MaleText_loc7`='La rapidez de Owatanka está contigo, $n.' WHERE `ID`=1299;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='워시트 포우니의 결의가 자네와 함께할 것이니 이제 자네 앞길은 탄탄할 것일세.', `MaleText_loc4`='你将会坚定不移，$n，因为你已经具有了瓦希塔帕恩的决心。', `MaleText_loc5`='你將會堅定不移，$n，因為你已經具有了瓦希塔帕恩的決心。', `MaleText_loc7`='Tu senda es segura, $n, puesto que la determinación de Washte Pawne te acompaña.' WHERE `ID`=1300;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이샤 아와크의 영혼이 당신에게 힘을 주기를, $n.', `MaleText_loc4`='依沙瓦克的精神给了你力量，$n。', `MaleText_loc5`='依沙瓦克的精神給了你力量，$n。', `MaleText_loc7`='Que el espíritu de Isha Awak te dé fuerza, $n.' WHERE `ID`=1301;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='테렌디스 님과 레이네 님께서 당신을 찾기 위해 나를 보내셨습니다. 잿빛 골짜기의 파수꾼들이 도움을 필요로 하고 있습니다.', `FemaleText_loc4`='特伦希斯和莱恩派我来找你。灰谷的哨兵需要帮助。', `FemaleText_loc5`='特倫希斯，萊恩派我來找你。梣谷的哨兵需要幫助。', `FemaleText_loc7`='Terenthis, Raene me envió para encontrarte. Los Centinelas necesitan ayuda en Vallefresno.' WHERE `ID`=1302;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='감사합니다, 테렌디스 님. 가능한 한 오래 머물겠습니다.', `FemaleText_loc4`='谢谢你，特伦希斯。我会尽可能留在这里帮忙的。', `FemaleText_loc5`='謝謝你，特倫希斯。我會盡可能留在這裡幫忙的。', `FemaleText_loc7`='Gracias, Terenthis. Permaneceré aquí tanto como pueda.' WHERE `ID`=1303;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잿빛 골짜기와 파수대를 도울 수 있는 뛰어난 자들을 몇 명이라도 보낼 수 있었으면 합니다.', `FemaleText_loc4`='希望我能派一些人来帮助灰谷的哨兵部队。', `FemaleText_loc5`='希望我能派一些人來幫助梣谷的哨兵部隊。', `FemaleText_loc7`='Espero poder enviar a unos cuantos a Vallefresno para ayudar a los Centinelas.' WHERE `ID`=1304;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 있었나, 셀라린. 나는 지금 그대를 도울 수 없지만, 이곳 아우버다인에 있는 모험가들이라면 도와줄 수 있을지도 모르지...', `MaleText_loc4`='你好，塞拉伊。很遗憾此时我不能帮助你，但是在灰谷的一些探险者可能会……', `MaleText_loc5`='你好，塞拉伊。很遺憾此時我不能幫助你，但是在奧伯丁的一些探險者可能會...', `MaleText_loc7`='Hola, Selarin. Me temo que no puedo ayudarte por ahora, pero quizás sí pueda hacerlo alguno de los aventureros que están aquí en Auberdine.' WHERE `ID`=1305;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다시 한번 감사드립니다, 테렌디스 님. 도움이 더 필요하면 다시 오겠습니다. 그때까지 모험가들을 더 잿빛 골짜기로 보내 주시기 바랍니다.', `FemaleText_loc4`='再次感谢你，特伦希斯。如果你需要帮助，我会再次回来。在此之前，请派遣更多的冒险者到灰谷去。', `FemaleText_loc5`='再次感謝你，特倫希斯。如果你需要幫助，我會再次回來。在此之前，請派遣更多的冒險者到梣谷去。', `FemaleText_loc7`='Gracias nuevamente, Terenthis. Volveré si necesito más ayuda. Hasta entonces y, por favor, envía más aventureros a Vallefresno.' WHERE `ID`=1306;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 배스랜모초를 섞습니다...', `MaleText_loc4`='%s将巴斯兰的头发混合在一起……', `MaleText_loc5`='%s混合巴斯蘭之髮...', `MaleText_loc7`='%s mezcla el cabello de Bathran...' WHERE `ID`=1307;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='치료제가 완성됐소, $n. 이제 아이를 구해야 하오.', `MaleText_loc4`='混合物完成了，$n。现在我们要去救那个孩子。', `MaleText_loc5`='混合物完成了，$n。現在我們要去救那個孩子。', `MaleText_loc7`='La mezcla está terminada, $n. Ahora debemos salvar al niño.' WHERE `ID`=1308;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성기사다! 저놈을 처치해 주인님을 기쁘게 해 드리자. 공격!', `MaleText_loc4`='一个圣骑士！杀死他的话，主人会很高兴的。进攻！', `MaleText_loc5`='一個聖騎士!殺死他的話，主人會很高興的。進攻!', `MaleText_loc7`='¡Un paladín! Matarlo complacería al maestro. ¡Atacad!', `FemaleText_loc1`='성기사다! 저놈을 처치해 주인님을 기쁘게 해 드리자. 공격!', `FemaleText_loc4`='一个圣骑士！杀死他的话，主人会很高兴的。进攻！', `FemaleText_loc5`='一個聖騎士!殺死他的話，主人會很高興的。進攻!', `FemaleText_loc7`='¡Un paladín! Matarlo complacería al maestro. ¡Atacad!' WHERE `ID`=1309;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 목공 일을 끝내고 오던 놈들이군. 계속 이동하지 않으면 날 노리는 적을 더 많이 만나게 될 거야.', `MaleText_loc4`='我们继续前进吧，否则会碰到更多想要我命的东西。', `MaleText_loc5`='我們繼續前進吧，否則會碰到更多想要我命的東西。', `MaleText_loc7`='Están reapareciendo tras un largo periodo de inactividad. Vamos a seguir adelante o daremos con más seres que quieren verme muerto.' WHERE `ID`=1310;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='숨어 봐야 소용없다! 애송이 성기사!', `MaleText_loc4`='你躲不了的，小圣骑士！', `MaleText_loc5`='你躲不了的，小聖騎士!', `MaleText_loc7`='¡No puedes ocultarte de nosotros, pequeño caballero!' WHERE `ID`=1312;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수호자의 도움 없이는 자신이 없는 것 같군?', `MaleText_loc4`='净化者德尔格伦不在的时候你好像不太自信，不是吗？', `MaleText_loc5`='淨化者德爾葛蘭不在的時候你好像不太自信，不是嗎?', `MaleText_loc7`='¿No estás tan seguro de ti mismo sin el Purificador, eh?' WHERE `ID`=1313;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘밤, 너의 피로 제단이 붉게 물들 것이다!', `MaleText_loc4`='今晚，你的血将会染红我们祭坛的圣石。', `MaleText_loc5`='今晚，你的血將會染紅我們祭壇的聖石。', `MaleText_loc7`='Esta noche, tu sangre teñirá de rojo las piedras de nuestros altares.' WHERE `ID`=1314;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수고했네. 여기서부터는 혼자 가더라도 안전할 거야. 잿빛 골짜기의 마에스트라 주둔지로 가서 델그렌과 대화하는 걸 잊지 마시게.', `MaleText_loc4`='干得好！我应该可以自己离开这里了。记着到灰谷的梅伊瑟娜岗哨去和净化者德尔格伦谈谈。', `MaleText_loc5`='幹得好!我應該可以自己離開這裡了。記著到梣谷的邁斯特拉崗哨去和淨化者德爾葛蘭談談。', `MaleText_loc7`='¡Bien hecho! A partir de ahora podré arreglármelas solo. No olvidéis hablar con Delgren cuando regreséis a la Atalaya de Maestra en Vallefresno.' WHERE `ID`=1315;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음... 강력한 질병이로군. 정신에 타격을 주는구려.', `MaleText_loc4`='啊……这种疾病相当厉害。它会影响人的心智……', `MaleText_loc5`='啊...這種疾病相當厲害。它會影響人的心智...', `MaleText_loc7`='Vaya, la enfermedad es potente. Y ataca el cerebro...' WHERE `ID`=1316;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='독을 견뎌... 내야 해!', `MaleText_loc4`='我必须……抵抗！', `MaleText_loc5`='我必須...抵抗!', `MaleText_loc7`='Tengo que... ¡RESISTIR!' WHERE `ID`=1318;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 포세이큰의 독에도 살아남았소, $n. 그리고 지금 해야 할 일도 잘 알고 있소.', `MaleText_loc4`='我险些就被那些亡灵的毒药所害，$n，现在我知道必须要做什么了。', `MaleText_loc5`='我險些就被那些被遺忘者的毒藥所害，$n，現在我知道必須要做什麼了。', `MaleText_loc7`='He sobrevivido a los venenos de los Renegados, $n, y ahora sé qué es lo que hay que hacer.' WHERE `ID`=1319;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 이 비참한 감방에서 탈출하는군! 제가 안마당으로 안내해 드리겠습니다.', `MaleText_loc4`='终于从这个肮脏的房间逃了出来！让我带你到院子里去……', `MaleText_loc5`='終於從這個骯髒的房間逃了出來!讓我帶你到院子裡去...', `MaleText_loc7`='¡Por fin estoy fuera de esta maldita celda! Te acompañaré al patio...' WHERE `ID`=1320;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 진실로 이 문 너머에 있는 무시무시한 괴물들을 상대할 정도로 용감하신 분입니다.', `MaleText_loc4`='你居然想要对付这扇门后的那些怪物，你真的很勇敢。', `MaleText_loc5`='你居然想要對付這扇門後的那些怪物，你真的很勇敢。', `MaleText_loc7`='Realmente eres valiente por querer hacer frente a los horrores que se ocultan tras esta puerta.' WHERE `ID`=1321;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 안마당 문에 있는 녹슨 자물쇠를 만지작거립니다.', `MaleText_loc4`='%s在院子的门上摸索那把生锈的锁。', `MaleText_loc5`='%s在院子的門上摸索那把生鏽的鎖。', `MaleText_loc7`='%s manosea con torpeza el oxidado cerrojo de la puerta del patio.' WHERE `ID`=1322;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='됐습니다!', `MaleText_loc4`='我们这就出发！', `MaleText_loc5`='我們這就出發!', `MaleText_loc7`='¡Allá vamos!' WHERE `ID`=1323;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아루갈을 처치하길 바랍니다. 전 이제 서둘러 하드렉 님께 돌아가 봐야겠습니다.', `MaleText_loc4`='希望你能解决掉阿鲁高。我必须赶快回到哈德瑞克那里。', `MaleText_loc5`='希望你能解決掉阿魯高。我必須趕快回到哈德瑞克那裡。', `MaleText_loc7`='Buena suerte con Arugal. Tengo que volver deprisa a Hadrec.' WHERE `ID`=1324;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 조각상들에 틀림없이 숨겨진 뭔가가 있을 텐데...', `MaleText_loc4`='这些雕像一定有暗格……', `MaleText_loc5`='這些雕像一定有暗格...', `MaleText_loc7`='Estas estatuillas deben tener un compartimento secreto...' WHERE `ID`=1325;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 잠겨 있잖아! 안 돼!', `MaleText_loc4`='它被锁住了！不！！', `MaleText_loc5`='它們被鎖住了!不!!', `MaleText_loc7`='¡Están bloqueados! ¡¡NO!!' WHERE `ID`=1326;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 어둠 속에서 튀어나옵니다!', `MaleText_loc4`='%s从阴影中跳了出来！', `MaleText_loc5`='%s從陰影中跳了出來!', `MaleText_loc7`='¡%s emerge de un salto de las tinieblas!', `FemaleText_loc1`='%s|1이;가; 어둠 속에서 튀어나옵니다!', `FemaleText_loc4`='%s从阴影中跳了出来！', `FemaleText_loc5`='%s從陰影中跳了出來!', `FemaleText_loc7`='¡%s emerge de un salto de las tinieblas!' WHERE `ID`=1327;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누군가가 놈을 처치했군.', `MaleText_loc4`='有人杀死了那个可怜的家伙。', `MaleText_loc5`='有人殺死了那個可憐的傢伙。', `MaleText_loc7`='Ya era hora de que alguien acabara con el pobre infeliz.' WHERE `ID`=1328;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번만큼은 쓰레기 같은 네놈과 의견이 일치하는구나.', `MaleText_loc4`='就这一次我同意你的意见……垃圾。', `MaleText_loc5`='就這一次我同意你的意見...垃圾。', `MaleText_loc7`='Por una vez estoy de acuerdo contigo... canalla.' WHERE `ID`=1329;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='미스트! 다시는 못 보게 될까봐 두려웠어! 그래, 난 괜찮으니까 걱정하지 마. 하지만 너는 좀 쉬어서 건강을 회복해야 해.', `FemaleText_loc4`='密斯特！我担心再也看不到你了！嗯，我很好，不用担心我。你必须好好休息，恢复健康。', `FemaleText_loc5`='密斯特!我擔心再也看不到你了!嗯，我很好，不用擔心我。你必須好好休息，恢復健康。', `FemaleText_loc7`='¡Niebla! ¡Temí que no volvería a verte! Sí, estoy bien. No te preocupes por mí. Debes descansar y recuperar tu salud.' WHERE `ID`=1330;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 따라오십시오. 안마당 문을 열어 드리겠습니다.', `MaleText_loc4`='跟着我，我将会为你打开庭院的门。', `MaleText_loc5`='跟著我，我將會為你打開庭院的門。', `MaleText_loc7`='Sígueme y te abriré la puerta del patio.' WHERE `ID`=1331;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감방문들이 너무 복잡하게 잠겨 있어서 제게는 이 문을 여는 주문밖에 없습니다.', `MaleText_loc4`='我能打开这扇门。但是为什么正好我就没法打开监牢的门呢？', `MaleText_loc5`='我能打開這扇門。但是為什麼正好我就沒法打開監牢的門呢?', `MaleText_loc7`='Conozco el conjuro para abrir esta puerta. Es una pena que las puertas de la celda no hubieran sido cerradas aleatoriamente.' WHERE `ID`=1332;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다 됐습니다! 이제 문이 열렸습니다. 이 너머에 있는 것들을 물리치길 바랍니다. 난 즉시 키린 토로 돌아가 보고해야겠습니다.', `MaleText_loc4`='搞定了！祝你们好运。我必须马上回去向肯瑞托报告！', `MaleText_loc5`='搞定了!祝你們好運。我必須馬上回去向祈倫托報告!', `MaleText_loc7`='¡Ya está! Abierta de par en par. Buena suerte en la conquista del más allá. ¡Tengo que informar al Kirin Tor de inmediato!' WHERE `ID`=1334;
