UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='으음... 거기 계신 게 아빠에요? 렐라라 배고파요... 스튜 먹고 싶어요.', `FemaleText_loc4`='啊……爸爸……？你在那边吗？我很饿……我能吃点炖肉吗？', `FemaleText_loc5`='啊...爸爸...?你在那邊嗎?我很餓...我能吃點燉肉嗎?', `FemaleText_loc7`='Eh... ¿Padre...? ¿Estás ahí? Tengo hambre... ¿puedo comer un poco de estofado?' WHERE `ID`=1337;
