UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아가, 깨어난 거니? 그대의 치료제가 조금이라도 효과가 있었던 게 틀림없군요! 고맙습니다, $n.', `MaleText_loc4`='你醒了？？药水起作用了！谢谢你，$n。', `MaleText_loc5`='你醒了??藥水起作用了!謝謝你，$n。', `MaleText_loc7`='¿¿Estás despierta?? ¡Tu cura ha funcionado! Gracias, $n.' WHERE `ID`=1339;
