UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여신이시여, 자매들이 계속 당해 그 수가 점점 줄어들고 있어 곧 저의 힘만으로는 악령숲의 악마들을 막아내지 못하게 될 것입니다.', `FemaleText_loc4`='女神啊，我同伴的数量正在不断地减少，我的力量很快就不足以阻止费伍德森林的恶魔了。', `FemaleText_loc5`='女神啊，我同伴的數量正在不斷地減少，我的力量很快就不足以阻止費伍德森林的惡魔了。', `FemaleText_loc7`='El número de mis compañeros merma, diosa, y mi propio poder pronto será insuficiente para contener a los demonios de Frondavil.' WHERE `ID`=1356;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여신이시여, 적들을 물리칠 힘을 주소서! 제발, 정의를 위한 절박한 제 기도를 들어 주소서!', `FemaleText_loc4`='女神啊，赐予我战胜敌人的力量吧！女神啊，请听我说，我现在要拼死一搏了，我所做的一切都是为了正义！', `FemaleText_loc5`='女神啊，賜予我戰勝敵人的力量吧!女神啊，請聽我說，我現在要拼死一搏了，我所做的一切都是為了正義!', `FemaleText_loc7`='¡Diosa, otórgame el poder para vencer a mis enemigos! Escúchame, por favor. ¡Lo necesito desesperadamente y mi causa es justa!' WHERE `ID`=1357;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이... 이건 뭐지? 내 기도에 대한 답인가? 엘룬께서 악마를 물리칠 수 있도록 내게 이 낫을 무기로 주셨구나.', `FemaleText_loc4`='什么……这是什么？这就是女神对我祈祷的回应？艾露恩赐予我一件武器，一把镰刀，去打败那些恶魔！', `FemaleText_loc5`='什麼...這是什麼?這就是女神對我祈禱的回應?伊露恩賜予我一件武器，一把鐮刀，去打敗那些惡魔!', `FemaleText_loc7`='¿Qué... qué es esto? ¿Puede ser esta la respuesta a mis plegarias? Elune me ha otorgado este arma, esta guadaña, para derrotar a los demonios.' WHERE `ID`=1358;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='실패했어... 내 임무에 실패했고... 우리 주민을 지키지 못했어... 늑대인간들은 미쳐 날뛰고 있고 여신께서 주신 낫은 잃어버리고...', `FemaleText_loc4`='我失败了……我最终还是失败了……我愧对我的同胞……狼人肆虐，而女神赐予我的镰刀也丢失了。', `FemaleText_loc5`='我失敗了...我最終還是失敗了...我愧對我的同胞...狼人肆虐，而女神賜予我的鐮刀也丟失了。', `FemaleText_loc7`='He fallado... He fallado en mi deber... he fallado a mi gente... El huargen huyó veloz y la guadaña de mi diosa se ha perdido.' WHERE `ID`=1359;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내가 악마를 불러내고 말았어... 도대체 여신께서 내게 주신 힘은 지금 누구의 손에 있는 것이며... 누가 그 힘을 사용하고 있는 것이지?', `FemaleText_loc4`='我引来了这些邪恶的生物……当初女神赐予我的圣物到底在哪里……究竟是谁在主导这一切？', `FemaleText_loc5`='我引來了這些邪惡的生物...當初女神賜予我的聖物到底在哪裡...究竟是誰在主導這一切?', `FemaleText_loc7`='Este mal que he desatado... en cuya mano yace el poder que mi diosa me concedió... ¿Pero de quién es la mano que lo dirige?' WHERE `ID`=1360;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 수호 정령을 소환하기 시작합니다!', `MaleText_loc4`='%s开始召唤守卫！', `MaleText_loc5`='%s開始召喚守衛!', `MaleText_loc7`='¡%s comienza a invocar guardianes!' WHERE `ID`=1361;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='십자로로 가려면 길을 따라 동쪽으로 간 다음 다시 북쪽으로 가게.', `MaleText_loc4`='$n，如果你想要去十字路口，先沿着路向东然后朝北走。', `MaleText_loc5`='$n，如果你想要去十字路口，先沿著路向東然後朝北走。', `MaleText_loc7`='Para llegar al Cruce, $n, sigue el camino hacia el este y luego hacia el norte.' WHERE `ID`=1364;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='시드네가 늦네. 지금쯤 집에 돌아올 줄 알았는데...', `FemaleText_loc4`='悉尼迟到了。我原本以为现在他该到家了。', `FemaleText_loc5`='悉尼遲到了。我原本以為現在他該到家了。', `FemaleText_loc7`='Sidney llega tarde. Pensé que ya estaría de vuelta en casa.' WHERE `ID`=1365;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그는 네 남편이잖니, 아가. 그가 어디 있는지 내가 어떻게 알겠니?', `MaleText_loc4`='女士，他是你的丈夫，不是我的。你问我他在哪里干什么？', `MaleText_loc5`='女士，他是你的丈夫，不是我的。你問我他在哪裡幹什麼?', `MaleText_loc7`='Es tu marido, mujer. ¿Cómo he de saber dónde se encuentra?' WHERE `ID`=1366;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='수도원에 할 일이 너무 많아서 그럴 거예요. 그래도 지금쯤은 돌아와야 할 시간인데...', `FemaleText_loc4`='他一定被修道院的工作拖住了。但是不管怎么样，他现在也该回来了。', `FemaleText_loc5`='他一定被修道院的工作拖住了。但是不管怎麼樣，他現在也該回來了。', `FemaleText_loc7`='Debe de estar inundado de trabajo en el Monasterio. Pero, aun así, ya debería haber regresado.' WHERE `ID`=1367;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세상에서 지저분한 쓰레기를 없애는 건 쉬운 일이 아니다, 낸시. 그래도 누군가 하지 않으면 안 될 일이지.', `MaleText_loc4`='净化这个世界上的污秽并不是一件容易的事，南希。但是总是要有人去做这样的事情的。', `MaleText_loc5`='淨化這個世界上的污穢並不是一件容易的事，南茜。但是總是要有人去做這樣的事情的。', `MaleText_loc7`='Limpiar el mundo de escoria inmunda no es tarea fácil, Nancy. Alguien tiene que hacerlo.' WHERE `ID`=1368;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저, 밖에 나가서 살펴봐야겠어요. 뭔가 이상해요.', `FemaleText_loc4`='好吧，我要出去检查一下。似乎有些不对劲。', `FemaleText_loc5`='好吧，我要出去檢查一下。似乎有些不對勁。', `FemaleText_loc7`='Vaya, saldré a ver qué pasa. Algo ocurre.' WHERE `ID`=1369;
