UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갑자기 불길한 예감이 드는데... 조심해, 놈들이 왔다!', `MaleText_loc4`='似乎我们遇到麻烦了。打起精神来，他们来了！', `MaleText_loc5`='看起來我們有點麻煩。他們來了!', `MaleText_loc7`='Al parecer, tenemos problemas. ¡Anímate, aquí vienen!' WHERE `ID`=1372;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐! 뭔가 사악한 기운이 느껴지는데... 언데드다!', `MaleText_loc4`='小心！我感到附近有邪恶的存在……亡灵！', `MaleText_loc5`='小心!我感到附近有邪惡的存在...亡靈!', `MaleText_loc7`='¡Espera! Presiento una presencia maligna... ¡No-muertos!' WHERE `ID`=1373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런... 또 이 세 놈들이군.', `MaleText_loc4`='又是这三个？', `MaleText_loc5`='又是這三個?', `MaleText_loc7`='¿Otra vez estos tres?' WHERE `ID`=1374;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='결국, 놈이 대가를 치렀군요.', `MaleText_loc4`='这个混蛋终于得到了应有的报应。', `MaleText_loc5`='終於，那個怪物得到了他應得的報應。', `MaleText_loc7`='Por fin. El monstruo recibió su merecido.' WHERE `ID`=1376;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 안톤의 추천서의 봉인을 뜯고 읽기 시작합니다.', `MaleText_loc4`='%s揭开安东的信上的封印，开始仔细阅读信件。', `MaleText_loc5`='%s揭開安東的信上的封印，然後開始仔細閱讀信件。', `MaleText_loc7`='%s rompe el sello de la carta de Anton y empieza a leerla.' WHERE `ID`=1377;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신께 맹세코, 이건 좋지 않소. 당신이 이해하지 못하는 뭔가가 있소, $n.', `MaleText_loc4`='以圣光的名义！这绝不是个好消息。有些东西你可能不能理解，$n。', `MaleText_loc5`='以聖光之名!這絕不是個好消息。有些東西你可能不能理解，$n。', `MaleText_loc7`='¡Por la Luz! Esto no es nada bueno. Hay algo que no entiendes, $n.' WHERE `ID`=1378;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 안톤의 추천서를 탁자 위에 내려놓습니다.', `MaleText_loc4`='%s把安东的信扔在桌上。', `MaleText_loc5`='%s把安東的信扔在桌上。', `MaleText_loc7`='%s arroja la carta de Anton sobre la mesa.' WHERE `ID`=1379;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마법봉의 모양은 단순해요. 다르톨은 이 마법봉을 만들 때 그의 신비한 지식을 사용하지 않았거든요. 성격상 드루이드의 것에 더 가깝죠.', `FemaleText_loc4`='这根杖的设计很简单。达图尔在制造它的时候没有使用他的奥术知识……蕴含在其中的主要是德鲁伊的魔法。', `FemaleText_loc5`='這根魔棒的設計很簡單。達圖爾在製造它的時候沒有使用他的秘法知識...蘊含在其中的自然是德魯伊的魔法。', `FemaleText_loc7`='El diseño del cetro es sencillo. Dartol no utilizó su sabiduría arcana en su creación... su naturaleza es más propia de los druidas.' WHERE `ID`=1380;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='후훗... 말장난 같군요. 성격상 드루이드 것에 가깝다니... 정말 재미있네요.', `FemaleText_loc4`='呵呵……我语带双关，不是吗？都是德鲁伊的东西……我很幽默吧。', `FemaleText_loc5`='呵呵...我語帶雙關，不是嗎?自然是德魯伊的...我很幽默吧。', `FemaleText_loc7`='Je, je... He hecho un juego de palabras, ¿no es así? Soy una druida por naturaleza... Qué graciosa soy...' WHERE `ID`=1381;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그럼 이제, 이것들을 함께 제자리에 놓아 보죠.', `FemaleText_loc4`='嗯，现在我们可以把节杖组合起来了……要试试吗？', `FemaleText_loc5`='現在，還是讓我們來研究一下如何修復這根魔棒，好嗎?', `FemaleText_loc7`='Bueno, y ahora, la vara. Intentemos arreglarla, ¿de acuerdo?' WHERE `ID`=1382;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다 됐어요! 아주 나쁘지는 않네요. 당신과 레이네가 이걸로 뭘 하려고 했다고요? 정말 강력한데요!!', `FemaleText_loc4`='啊！这还不坏。你和莱恩打算拿这东西去做什么来着？这东西可真强力！', `FemaleText_loc5`='看!其實沒那麼糟。你說你跟萊恩要怎麼處理這個東西?它有強大的力量!', `FemaleText_loc7`='¡Ya está! No ha sido tan difícil. ¿Qué dijiste que Raene y tú ibais a hacer con esa cosa? ¡Es poderosa!' WHERE `ID`=1383;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잔혹발톱과 그의 주인 볼코르를 좀 도와주시오. 관심이 있다면 내 얘기를 좀 더 자세히 들어 보는 게 어떻겠소...', `MaleText_loc4`='如果你有时间，锐爪和他的主人沃科尔需要你的帮助。要是你感兴趣的话，就继续和我谈谈吧……', `MaleText_loc5`='如果你有時間，銳爪和他的主人沃科爾需要你的幫助。要是你感興趣的話，就繼續和我談談吧...', `MaleText_loc7`='Si dispones de tiempo, podrías ayudar a Zarpadura y a su maestro Volcor. Si te interesa, habla conmigo más adelante...' WHERE `ID`=1384;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 독이 묻은 단검을 부여 쥡니다!', `MaleText_loc4`='%s伸手去抓住他的毒匕首！', `MaleText_loc5`='%s伸手去抓住他的毒匕首!', `MaleText_loc7`='%s coge su puñal envenenado.', `FemaleText_loc1`='%s|1이;가; 독이 묻은 단검을 부여 쥡니다!', `FemaleText_loc4`='%s伸手去抓住他的毒匕首！', `FemaleText_loc5`='%s伸手去抓住她的毒匕首!', `FemaleText_loc7`='%s coge su puñal envenenado.' WHERE `ID`=1385;
