UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 마법의 힘이 동굴 안에 퍼지는 것 같군. 내 귀여운 엘프들... 음하하하하!', `MaleText_loc4`='啊，感受渗入洞穴的魔法之力吧，我的小精灵……木哈哈哈！', `MaleText_loc5`='啊，感受拂過洞穴的魔法之風吧，我的小精靈...哈哈!', `MaleText_loc7`='Ah, sentid cómo la magia se filtra hasta el interior de la cueva, mis pequeños elfos, ¡ja, ja, ja, ja, ja!' WHERE `ID`=1406;
