UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생각을 바꾸었다, 나의 충성스러운 부하들이여. 포로를 내 서재까지 데리고 올 것 없다. 여기서 지금 당장 해결하겠다.', `MaleText_loc4`='我改变了主意，忠诚的仆人们。你们不必把囚犯带到我面前来供我研究了，我现在就开始。', `MaleText_loc5`='我改變了主意，忠誠的僕人們。你們不必把囚犯帶到我面前來供我研究了，我現在就開始。', `MaleText_loc7`='He cambiado de parecer, mis leales sirvientes, no tenéis que traer al prisionero hasta mi estudio. Me ocuparé de él aquí y ahora.' WHERE `ID`=1456;
