UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; "그가 필요로 하는 모든 것을 도우라. 이 임무는 절대 실패해선 안 된다." 라고 읊조립니다.', `MaleText_loc4`='%s吟唱道：“尽你所能地帮助他，这项任务绝不能失败。”', `MaleText_loc5`='%s吟唱道，「盡你所能地幫助他，這個任務絕不能失敗。」', `MaleText_loc7`='%s entona, "Asístelo de todas las maneras necesarias. No falles en esta tarea."' WHERE `ID`=1461;
