UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 굶주림에 주위를 킁킁거리다가 신선한 사자 고기 냄새를 맡습니다...', `MaleText_loc4`='%s贪婪地呼吸着，空气中飘来新鲜的狮子肉香……', `MaleText_loc5`='%s飢腸轆轆地對著空中嗅著，聞到新鮮的獅子肉...', `MaleText_loc7`='%s olfatea hambriento, percibiendo carne de león fresca...' WHERE `ID`=1463;
