UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 눈 속으로 사라집니다.', `MaleText_loc4`='%s消失在茫茫大雪中。', `MaleText_loc5`='%s消失在茫茫大雪中。', `MaleText_loc7`='%s desaparece en la nieve.' WHERE `ID`=1465;
