UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠... $n, 정신이 혼란스러운 저의 도움이라도 필요하신가요? 잔질의 좀비에 대한 비밀이 당신에게 도움이 될지도 모르겠어요.', `MaleText_loc4`='嗯……如果你注意到这些细节问题，$n，那么隐藏在赞吉尔僵尸背后的秘密也许就是元凶！', `MaleText_loc5`='嗯...如果你注意到這些細節問題，$n，那麼隱藏在贊吉爾殭屍背後的秘密也許就是元兇!', `MaleText_loc7`='Mm... si lo que quieres es aguzar tu ingenio, $n, ¡podrías recurrir al secreto de los zombis de Zanzil!' WHERE `ID`=1468;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고마워요, $n.', `MaleText_loc4`='谢谢你，$n。', `MaleText_loc5`='謝謝你，$n。', `MaleText_loc7`='Gracias, $n.' WHERE `ID`=1469;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 혼합물은 틀림없이 유용하게 사용될 거예요...', `MaleText_loc4`='我相信我能找到这种混合剂的用途……', `MaleText_loc5`='我相信我能找到這種混合劑的用途...', `MaleText_loc7`='Estoy seguro de que puedo encontrarle utilidad a esta mezcla...' WHERE `ID`=1470;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대지를 감싸는 공포 속에서 아메스아란은 분리의 고통을 겪었어. 그 속에선 살아남을 수 있는 희망은 거의 없었지.', `MaleText_loc4`='在大灾变时，亚米萨兰正在大陆崩裂的边界，几乎没有什么幸存者逃过那次劫难。', `MaleText_loc5`='在大爆炸時，亞米薩蘭正在大陸崩裂的邊界，幾乎沒有什麼倖存者逃過那次劫難。', `MaleText_loc7`='En medio del Cataclismo, Ameth''Aran quedó a merced de la voluntad del terror que subyugaba la tierra. Había pocas esperanzas de que sobreviviera.' WHERE `ID`=1471;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그때 애스리쿠스가 왔어. 그는 우리를 고통에서 구해주겠다고 했지. 그러곤 보호의 마법을 시전했어.', `MaleText_loc4`='埃瑟里克斯来到我们面前，他声称能把我们从痛苦中解救出来。他给我们施了魔法，让我们免受伤害。', `MaleText_loc5`='埃瑟里克斯來到我們面前，他聲稱能把我們從痛苦中解救出來。他給我們施了魔法，讓我們免受傷害。', `MaleText_loc7`='Athrikus vino a vernos. Nos dijo que podía protegernos del peligro. Nos lanzó un hechizo para protegernos del peligro.' WHERE `ID`=1472;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 애스리쿠스 나라신을 처단해야 합니다. 영혼이여, 우리가 그의 마법을 풀 영혼의 보석을 발견할 수 있겠습니까?', `MaleText_loc4`='我们该与埃瑟里克斯·纳拉辛有个了断了。自然之灵啊，告诉我，去哪里才能找到其它的灵魂宝石来解除他的魔法？', `MaleText_loc5`='我們該與埃瑟里克斯·納拉辛有個了斷了。自然之靈啊，告訴我，去哪裡才能找到其他的靈魂寶石來解除他的魔法?', `MaleText_loc7`='Entonces tendremos que acabar con Athrikus Narassin. Dime, espíritu, ¿dónde podríamos encontrar las otras gemas de almas para deshacer esta magia?' WHERE `ID`=1473;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법의 진동이 멈추자 그의 숨겨진 목적이 밝혀졌어. 우린 함정에 빠졌고 그는 천천히 우리의 힘을 빼앗아갔어.', `MaleText_loc4`='当震动停下来的时候，他的真实目的暴露出来了。我们都被困住了，而他在慢慢地汲取我们的能量。', `MaleText_loc5`='當震動停下來的時候，他的真實目的暴露出來了。我們都被困住了，而他在慢慢地汲取我們的能量。', `MaleText_loc7`='Cuando acabaron las sacudidas, se revelaron sus verdaderos motivos. Quedamos atrapados y él poco a poco fue absorbiendo nuestros poderes.' WHERE `ID`=1474;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그의 부관인 일크루드 마그스룰은 남아있는 영혼의 보석의 위치를 나타내는 마법책을 지니고 있소.', `MaleText_loc4`='他的副官，伊克鲁德·玛格苏尔有一本书，里面也许记载着其它灵魂宝石的所在地。', `MaleText_loc5`='他的副官，伊克魯德·瑪格蘇爾有一本書，裡面也許記載著其他靈魂寶石的所在地。', `MaleText_loc7`='Su teniente, Ilkrud Magthrull, posee un libro que puede indicar la localización de las gemas de almas restantes.' WHERE `ID`=1475;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 안개 속으로 서서히 사라집니다.', `MaleText_loc4`='%s消失在迷雾之中……', `MaleText_loc5`='%s消失在迷霧之中...', `MaleText_loc7`='%s desaparece en la niebla...' WHERE `ID`=1476;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 부품을 집어 주머니에 넣습니다...', `MaleText_loc4`='%s抓了一个零件，把它放进口袋中……', `MaleText_loc5`='%s抓了一個零件，把它放進他的口袋中...', `MaleText_loc7`='%s coge una pieza y la guarda en el bolsillo...' WHERE `ID`=1477;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 이거면 될 거야...', `MaleText_loc4`='那里，应该就是那里……', `MaleText_loc5`='那裡，應該就是那裡...', `MaleText_loc7`='Ya está, esto deberá servir...' WHERE `ID`=1478;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 부품 상자를 바닥에 내려놓습니다.', `MaleText_loc4`='%s把箱子放在地上。', `MaleText_loc5`='%s把零件木箱放在地上。', `MaleText_loc7`='%s coloca el cajón con las piezas el suelo.' WHERE `ID`=1479;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 춤을 추기 시작합니다.', `MaleText_loc4`='%s开始跳舞。', `MaleText_loc5`='%s開始跳舞。', `MaleText_loc7`='%s comienza a bailar.' WHERE `ID`=1480;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하하! $n... 당신 춤 한번 잘 추는데!', `MaleText_loc4`='哈哈！$n，你真是一个好舞伴！', `MaleText_loc5`='哈哈!$n，你真是一個好舞伴!', `MaleText_loc7`='¡Ja, ja, ja! ¡$n, vaya $gcompañero:compañera; estás $ghecho:hecha;!' WHERE `ID`=1481;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야호! 마침내 여기서 나가는구먼. 하지만 쉽지는 않을 거야. 경계를 늦추지 말라고.', `MaleText_loc4`='喔，喔！终于出来了。不过接下来还有危险，所以要保持警惕。', `MaleText_loc5`='喔，喔!終於出來了。不過接下來還有危險，所以要保持警惕。', `MaleText_loc7`='¡Ju, ju! Al fin voy a salir de aquí. De todas maneras, no va a ser fácil. Mantened los ojos abiertos por si tenemos problemas.' WHERE `ID`=1482;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 위에 그 괘씸한 쭈그렁 할멈, 서슬깃 차를가가 살고 있지.', `MaleText_loc4`='那上面就是卡尔加·刺肋的住处。那个该死的又干又瘪的老太婆。', `MaleText_loc5`='那上面就是卡爾加·刺肋的住處。那個該死的又乾又癟的老太婆。', `MaleText_loc7`='Allí es donde reside Charlga Filonavaja. Maldita bruja vieja.' WHERE `ID`=1483;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에 청엽수 줄기가 있다고! 말하자면, 찾아주길 얌전히 기다리고 있는 황금 같은 거라고 할 수 있지!', `MaleText_loc4`='这个沟里就有蓝叶薯！它们可都是唾手可得的金子啊！', `MaleText_loc5`='這個溝裡就有藍葉薯!它們可都是唾手可得的金子啊!', `MaleText_loc7`='¡En algún lugar de esta trinchera hay una trufa hojazul! ¡Es como oro esperando a ser extraído, créeme!' WHERE `ID`=1484;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기는 곳곳에 위험이 도사리고 있는 곳이지.', `MaleText_loc4`='这里到处都潜伏着危险。', `MaleText_loc5`='這裡到處都潛伏著危險。', `MaleText_loc7`='Aquí acecha el peligro en cada esquina.' WHERE `ID`=1485;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에 어떻게 이런 고약한 짐승들이 사는지 모르겠다니까. 윽! 냄새!', `MaleText_loc4`='我不明白这些愚蠢的动物是怎么在这种地方生存的……闻起来真臭！', `MaleText_loc5`='我不明白這些愚蠢的動物是怎麼在這種地方生存的...聞起來真臭!', `MaleText_loc7`='No puedo entender que estos nauseabundos animales vivan en este lugar... ¡Puaj! ¡Apesta!' WHERE `ID`=1486;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 이 엄청난 가시덩굴 미로에서 빠져나갈 길을 발견한 것 같군.', `MaleText_loc4`='我想我看到了一条可以走出这片荆棘林的路。', `MaleText_loc5`='我想我看到了一條可以走出這片荊棘林的路。', `MaleText_loc7`='Creo que veo un modo de salir de este enorme y enredado zarzal.' WHERE `ID`=1487;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 고약한 곳에서 빠져 나와서 정말 다행이군. 하지만 이 위의 상황도 별로 나아 보이지는 않는구먼!', `MaleText_loc4`='能走出这条臭沟真好，尽管出去了也好不了多少。', `MaleText_loc5`='能走出這條臭溝真好，儘管出去了也好不了多少。', `MaleText_loc7`='Me alegro de haber salido de aquella espantosa trinchera. ¡Aunque aquí arriba tampoco se está mucho mejor!' WHERE `ID`=1488;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 스타우트 맥주 냄새 한번 톡 쏘는데그래!', `MaleText_loc4`='这酒闻起来真带劲！', `MaleText_loc5`='這酒聞起來真帶勁!', `MaleText_loc7`='¡Esta cerveza sí que tiene un olor fuerte!' WHERE `ID`=1489;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어! 이곳에서 나갈 수 있게 되어 정말 기쁘다니까!', `MaleText_loc4`='终于！我终于能走出这个地方了。', `MaleText_loc5`='終於!我終於能走出這個地方了。', `MaleText_loc7`='¡Por fin! Qué alegría cuando salgamos de este lugar.' WHERE `ID`=1490;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디, 조금 맛볼까...', `MaleText_loc4`='让我们来尝一小口……', `MaleText_loc5`='讓我們來嘗一小口...', `MaleText_loc7`='Vamos a darle una probadita...' WHERE `ID`=1491;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐! 내가 미쳤나?! 이건 녀석들에게 먹여야 하는데 말이야.', `MaleText_loc4`='等等！我到底在想什么！有正事要干哪。', `MaleText_loc5`='等等!我到底在想什麼!有正事要幹哪。', `MaleText_loc7`='¡Espera! ¿En qué estoy pensando? Tenemos que ponernos manos a la obra con esto.' WHERE `ID`=1492;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한숨 돌린 후에 톱니항으로 돌아가야겠군. 도와줘서 고맙다고!', `MaleText_loc4`='我想在回到棘齿城之前休息一下。谢谢你的帮助！', `MaleText_loc5`='我想在回到棘齒城之前休息一下。謝謝你的幫助!', `MaleText_loc7`='Creo que descansaré un momento y cogeré un poco de aire antes de regresar a Trinquete. ¡Gracias por tu ayuda!' WHERE `ID`=1493;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 그럼 난 톱니항으로 가겠네. 자네에게 행운이 함께하기를!', `MaleText_loc4`='好了，现在我要起身去棘齿城了！祝你好运！', `MaleText_loc5`='好了，現在我要起身去棘齒城了!祝你好運!', `MaleText_loc7`='¡Bueno, parto hacia Trinquete! ¡Que tengas mucha suerte!' WHERE `ID`=1494;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; $n|1이;가; 황야의 땅에서 겪은 모험담에 귀를 기울입니다.', `MaleText_loc4`='%s听$n讲述$g他:她;在荒芜之地的冒险经历。', `MaleText_loc5`='%s聽著$n訴說$g他:她;在荒蕪之地的冒險經歷。', `MaleText_loc7`='%s pone atención mientras $n le cuenta sus aventuras en las Tierras Inhóspitas.' WHERE `ID`=1495;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놀랍소! 그렇다면 인듀리움이 문제의 열쇠로군!', `MaleText_loc4`='难以想象！看来精铁才是关键！', `MaleText_loc5`='難以想像!看來精鐵才是關鍵!', `MaleText_loc7`='¡Increíble! ¡Entonces el indurium es la clave!' WHERE `ID`=1496;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수백 명이 그의 주문에 갇혀 버렸지. 하지만 이제 그의 주문에 속박된 자는 얼마 안 남게 됐지. 그래도 그는 가끔 우리에게 말을 걸곤 했어.', `MaleText_loc4`='曾经有数百人被他的法术困住。现在只有一小部分还被囚禁着。他有时也会和我们交谈。', `MaleText_loc5`='曾經有數百人被他的法術困住。現在只有一小部分還被囚禁著。他有時也會和我們交談。', `MaleText_loc7`='Cientos fueron encarcelados por obra de este hechizo. Ahora solo unos cuantos permanecen en sus prisiones. Él hablaba a veces con nosotros.' WHERE `ID`=1497;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그는 자신의 힘이 약해질까 봐 걱정했지. 그리고 자신에게 마지막으로 남은 귀중한 영혼의 보석인 우리마저 사라져 최후를 맞이할까 봐 걱정하고 있었어.', `MaleText_loc4`='他担心他的法力会减弱，那块宝贵的灵魂宝石也会消失和死亡。', `MaleText_loc5`='他擔心他的法力會減弱，那塊寶貴的靈魂寶石也會消失和死亡。', `MaleText_loc7`='Le preocupaba que su poder se debilitara, que el brillo de sus valiosas gemas de almas desapareciera para siempre.' WHERE `ID`=1498;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번에는 영원히 끝장내 주마!', `MaleText_loc4`='这次我会把你彻底干掉！', `MaleText_loc5`='這次我會把你徹底幹掉!', `MaleText_loc7`='¡Esta vez acabaré contigo de una vez por todas!' WHERE `ID`=1499;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 인듀리움 조각을 그의 가열로로 가져갑니다.', `MaleText_loc4`='%s把精铁碎片拿到锻炉前。', `MaleText_loc5`='%s把精鐵碎片拿到了鍛爐前。', `MaleText_loc7`='%s lleva las láminas de indurium a su fragua.' WHERE `ID`=1500;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 이 조각들을 달궈 볼까...', `MaleText_loc4`='现在让我们加热这些碎片……', `MaleText_loc5`='現在讓我們加熱這些碎片...', `MaleText_loc7`='Ahora vamos a calentar estas láminas.' WHERE `ID`=1501;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직까지는 그대로군. 온도를 더 올려 볼까...', `MaleText_loc4`='到目前为止它们还没有被融化。让我们把温度继续调高……', `MaleText_loc5`='到目前為止它們還沒有被融化。讓我們把溫度繼續調高...', `MaleText_loc7`='De momento aguantan. Vamos a calentarlas más...' WHERE `ID`=1502;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이럴 수가! 이 인듀리움은 엄청난 열에도 강하군!', `MaleText_loc4`='我的天啊！精铁居然可以承受如此高的温度！', `MaleText_loc5`='我的天啊!精鐵居然可以承受如此高的溫度!', `MaleText_loc7`='¡Por Orgrim! ¡Este indurium soporta las más altas temperaturas!' WHERE `ID`=1503;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실험은 성공적이야! $n, 이 인듀리움은 정말 놀라운 물질이군.', `MaleText_loc4`='试验很成功！$n，精铁真是一种神奇的原料。', `MaleText_loc5`='試驗很成功!$n，精鐵真是一種神奇的原料。', `MaleText_loc7`='¡Ha sido una prueba exitosa! $n, este indurium es un material maravilloso.' WHERE `ID`=1504;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 한번 고맙소, $n. 이제 이 인듀리움을 이용해 내 자동차의 성능을 높이는 작업을 시작해야겠소!', `MaleText_loc4`='再次感谢你，$n。现在我要用精铁来加固我的战车！', `MaleText_loc5`='再次感謝你，$n。現在我要用精鐵來加固我的戰車!', `MaleText_loc7`='Gracias de nuevo, $n. ¡Utilizaré el indurium para que mi coche sea aún más potente!' WHERE `ID`=1505;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쾅! 쾅! 쾅! 지금 자동차를 개조하는 중이오!!!', `MaleText_loc4`='哐！哐！哐！我正在加固我的战车！', `MaleText_loc5`='砰!砰!砰!我正在加固我的戰車!', `MaleText_loc7`='¡BANG! ¡BANG! ¡BANG! ¡¡¡Estoy potenciando mi coche!!!' WHERE `ID`=1506;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다 됐군!', `MaleText_loc4`='都完成了！', `MaleText_loc5`='都完成了!', `MaleText_loc7`='¡Ya está listo!' WHERE `ID`=1507;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 다음 경주에서는 내 자동차가 훨씬 더 빨리 달리게 될 거요!', `MaleText_loc4`='在下一次比赛中，这辆车将会比以前更快！', `MaleText_loc5`='在下一次比賽中，這輛車將會比以前更快!', `MaleText_loc7`='¡Y para la siguiente carrera los coches serán AÚN más rápidos que antes!' WHERE `ID`=1508;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경기 시작합니다! 척 보기에도 날렵한 고블린 자동차가 우승할 것이 분명합니다! 경주가 시작되기 전에 어서 어서 돈을 거십시오!', `MaleText_loc4`='开始下注啦！地精的车看上去很酷，它肯定能赢！趁比赛还没有开始赶快下注啦！', `MaleText_loc5`='開始下注啦!哥布林的車看起來很酷，它肯定能贏!趁比賽還沒有開始趕快下注啦!', `MaleText_loc7`='¡Listo para correr! ¡El coche de goblin tiene una pinta estupenda y seguro que ganará! ¡Hagan sus apuestas antes de que empiece la carrera!' WHERE `ID`=1509;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 자, 다음 경주에서 돈을 따려면 노움에게 거세요! 기회가 있을 때 어서 참여하세요!', `MaleText_loc4`='明智的人绝对会赌侏儒获胜的！快下注啦，比赛马上就要开始了！', `MaleText_loc5`='明智的人絕對會賭地精獲勝的!快下注啦，比賽馬上就要開始了!', `MaleText_loc7`='¡Si son listos, apostarán por los gnomos en la siguiente carrera! ¡Vengan, hagan sus apuestas!' WHERE `ID`=1510;
