UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오닉시아 일당이군!', `MaleText_loc4`='奥妮克希亚的血脉！', `MaleText_loc5`='奧妮克希亞的血脈!', `MaleText_loc7`='¡El linaje de Onyxia!' WHERE `ID`=1512;
