UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조그만 $r|1이;가; 감히 이 대군주 모크모로크와 싸우겠다고? 끝장내 주지! 나 이곳의 왕이다!', `MaleText_loc4`='弱小的$r要和莫格穆洛克大王决战？干掉你！我是这里的老大！', `MaleText_loc5`='弱小的$r要和莫格穆洛克主宰決戰?我要揍扁你!我才是這裡的老大!', `MaleText_loc7`='Enclenque $r ¿quieres luchar contra el señor supremo Mok''Morokk? ¡Yo machacarte! ¡Yo ser jefe aquí!' WHERE `ID`=1515;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 막 $n|1이;가; 첫 번째 바퀴를 돌았습니다!', `MaleText_loc4`='$n驶过来了，第一个进入弯角！', `MaleText_loc5`='現在$n衝了過來，第一個進入彎角!', `MaleText_loc7`='¡Y ahora el $n viene de dar la primera vuelta!' WHERE `ID`=1517;
