UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 그를 유쾌한 짐이라 부른다네...', `MaleText_loc4`='我们叫他微笑的吉姆……', `MaleText_loc5`='我們叫他微笑的吉姆...', `MaleText_loc7`='Le llamamos Jim Sonrisas...' WHERE `ID`=1635;
