UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 두 바퀴째입니다. 선두로 $n|1이;가; 모습을 드러내고 있습니다!', `MaleText_loc4`='现在$n领先！', `MaleText_loc5`='現在通過第2彎道的是$n!', `MaleText_loc7`='¡$n ha completado la segunda vuelta!' WHERE `ID`=1642;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 깨끗하고 멋진 시합을 원한다. 둘 다 정신 바짝 차리도록!', `MaleText_loc4`='好了，我要获得一次漂亮的胜利。准备好你们的剑和盾牌。', `MaleText_loc5`='好了，我要獲得一次漂亮的勝利。準備好你們的劍和盾牌。', `MaleText_loc7`='Muy bien, quiero un combate limpio. Recuerda mantener la espada firme y el escudo listo.' WHERE `ID`=1643;
