UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그늘 쉼터 여관으로 가서 흔적을 찾아보고 그 흔적이 어디로 이어지는지 확인한 후 돌아와서 내게 보고하시오.', `MaleText_loc4`='去树荫旅店，然后沿着足迹追踪。看看它们是到哪里去的，然后回来向我报告。', `MaleText_loc5`='去樹蔭旅店，然後沿著足跡追蹤。看看它們是到哪裡去的，然後回來向我報告。', `MaleText_loc7`='Dirígete a la Posada Reposo Umbrío y sigue las huellas. Mira adónde conducen y vuelve a informarme.' WHERE `ID`=1648;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠습니다. 곧 돌아오겠습니다.', `MaleText_loc4`='明白。我马上就回来。', `MaleText_loc5`='明白。我馬上就回來。', `MaleText_loc7`='De acuerdo. Regresaré pronto.' WHERE `ID`=1649;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 안개 속으로 사라집니다.', `MaleText_loc4`='%s消失在薄雾中。', `MaleText_loc5`='%s消失在薄霧中。', `MaleText_loc7`='%s desaparece en la niebla.' WHERE `ID`=1650;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저놈을 잡아라. 그리고 누구도 이 홀쭉이를 방해할 수 없다는 사실을 똑똑히 가르쳐 주라고!', `MaleText_loc4`='伙计们，给他们一点教训！没有人能阻挡我！', `MaleText_loc5`='夥計們，給他們一點教訓!沒有人能阻擋我!', `MaleText_loc7`='Tíos, vamos a por ellos. ¡Vamos a darles una lección! Nadie le toma el pelo a Slim.' WHERE `ID`=1651;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 메네실에서 마지막 순간이다. 실컷 즐겨라.', `MaleText_loc4`='在米奈希尔好好地休息一下，不久之后你就会精力充沛了。', `MaleText_loc5`='在米奈希爾好好地休息一下，不久之後你就會精力充沛了。', `MaleText_loc7`='Disfruta de lo que te queda de estancia en Menethil. No durará mucho más.' WHERE `ID`=1652;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기까지 와서 우리한테 뭘 훔쳐낼 수 있다고 생각한 거냐!?', `MaleText_loc4`='你认为自己能在这里来去自如？', `MaleText_loc5`='你以為你可以來這裡偷我們的東西嗎，嗯!?', `MaleText_loc7`='¡¿Crees que puedes venir aquí a robarnos, eh?!' WHERE `ID`=1653;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 네놈이 살아나갈 수 있는 방법은 없다!', `MaleText_loc4`='你绝不可能活着离开这里！', `MaleText_loc5`='你絕不可能活著離開這裡!', `MaleText_loc7`='¡No hay manera de salir vivos de aquí!', `FemaleText_loc1`='여기서 네놈이 살아나갈 수 있는 방법은 없다!', `FemaleText_loc4`='你绝不可能活着离开这里！', `FemaleText_loc5`='你絕不可能活著離開這裡!', `FemaleText_loc7`='¡No hay manera de salir vivos de aquí!' WHERE `ID`=1654;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맥주나 마시고 있을 시간 없다고! 경주가 곧 시작된단 말이야.', `MaleText_loc4`='没时间喝啤酒了！比赛马上就要开始了。', `MaleText_loc5`='沒時間喝啤酒了!比賽馬上就要開始了。', `MaleText_loc7`='¡No hay tiempo para cerveza! La carrera está a punto de empezar.' WHERE `ID`=1655;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='차가 잘 견뎌 주었군! 이제 다음 경주를 준비할 시간이야.', `MaleText_loc4`='车被撞了一下！我们得快点把它修好，准备下一场比赛。', `MaleText_loc5`='車被撞了一下!我們得快點把它修好，準備下一場比賽。', `MaleText_loc7`='¡El coche se llevó una buena paliza! Preparémoslo para la próxima carrera.' WHERE `ID`=1656;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 헨델. 자존심을 위해 자신의 왕국을 배신할 수 있는 친구를 만나게 되어 영광이군그래?', `MaleText_loc4`='啊，亨德尔下士。很高兴能与一个为了自尊而背叛了自己的国家的人见面。', `MaleText_loc5`='啊，士兵亨德爾。很高興能與一個為了自尊而背叛了自己的國家的人見面。', `MaleText_loc7`='Ah, soldado Hendel. Es un placer encontrar a uno de esos hombres que traicionarían su reino por orgullo.' WHERE `ID`=1657;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 어떻게 해야 한단 말인가?', `MaleText_loc4`='我要去干什么来着？', `MaleText_loc5`='我要去幹什麼來著?', `MaleText_loc7`='¿Qué voy a hacer?' WHERE `ID`=1658;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위에서 아는 날엔 난 죽은 목숨이야.', `MaleText_loc4`='如果被上尉发现，我就死定了。', `MaleText_loc5`='如果被上尉發現，我就死定了。', `MaleText_loc7`='Si el Capitán se entera, será mi fin.' WHERE `ID`=1659;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 이런 일이 일어날 수 있지?', `MaleText_loc4`='这到底怎么回事？', `MaleText_loc5`='這到底怎麼回事?', `MaleText_loc7`='¿Cómo pudo haber ocurrido?' WHERE `ID`=1660;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갑자기 사방에서 놈들이 뛰쳐나오다니...', `MaleText_loc4`='突然之间，到处都是那帮家伙了。', `MaleText_loc5`='突然之間，到處都是那幫傢伙了。', `MaleText_loc7`='De repente, estaban en todas partes.' WHERE `ID`=1661;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누군가 놈들의 뒤에서 돕고 있는 게 분명해.', `MaleText_loc4`='他们一定是得到了某些人的帮助。', `MaleText_loc5`='他們一定是得到了某些人的幫助。', `MaleText_loc7`='Alguien tuvo que ayudarles.' WHERE `ID`=1662;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헨델, 이제 자네 문제를 처리해야겠군. 프라우드무어 님께서 탑에서 자네에게 말씀하실 걸세.', `MaleText_loc4`='为什么我们不现在解决呢，亨德尔？普罗德摩尔女士将会很乐意在塔里接见你的。', `MaleText_loc5`='為什麼我們不現在解決呢，亨德爾?普勞德摩爾女士將會很樂意在塔裡接見你的。', `MaleText_loc7`='Hendel, ¿por qué no hacemos un trato contigo? Lady Valiente volverá a hablar contigo en la torre.' WHERE `ID`=1663;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저렇게 화가 나 있는 오크가 하려는 말이 뭔지 정말 궁금하군그래...', `MaleText_loc4`='我想知道这个愤怒的兽人想要说些什么……', `MaleText_loc5`='我想知道這個憤怒的獸人想要說些什麼...', `MaleText_loc7`='Estoy ansioso por saber lo que un orco tan enfadado tiene que decir...' WHERE `ID`=1664;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 마그의 가면을 가마솥 안에 넣습니다.', `MaleText_loc4`='%s把东西放进了锅里。', `MaleText_loc5`='%s把頭顱放進了鍋裡。', `MaleText_loc7`='%s coloca la cabeza de Marg en la caldera.' WHERE `ID`=1665;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가마솥 안을 들여다 보게. 마그의 영혼이 할 말이 있는 것 같으니...', `MaleText_loc4`='仔细看着锅，$n。他似乎有话要说……', `MaleText_loc5`='仔細看著鍋，$n。瑪格似乎有話要說...', `MaleText_loc7`='Mira dentro de la caldera, $n. Marg quiere hablar...' WHERE `ID`=1666;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='들었나, $n? 여관을 불태운 건 인간 탈영병 리테인 것 같다고 하는군!', `MaleText_loc4`='听到了吗？$n，他说可能是人类的背叛者帕瓦尔·雷瑟放火烧了那座旅店！', `MaleText_loc5`='聽到了嗎?$n，他說可能是人類的背叛者帕瓦爾·雷瑟放火燒了那座旅店!', `MaleText_loc7`='¿Has oído eso? ¡$n, aquí dice que Reethe, el desertor humano, puede haber sido el que quemó la posada!' WHERE `ID`=1667;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오그론이 그 분홍 피부인 녀석을 찾아서 녀석의 다리를 부러뜨렸으면 좋겠군. 녀석이 그런 늪지에서 어떻게 살아남을 수 있을지 한번 두고 보자고!', `MaleText_loc4`='我希望奥格隆能找到那个粉皮肤的家伙，并且打断他的腿。我倒想看看他如何在沼泽地里活下去！', `MaleText_loc5`='我希望奧格隆能找到那個粉紅皮膚的傢伙，並且打斷他的腿。我倒想看看他如何在沼澤地裡活下去!', `MaleText_loc7`='Espero que Ogron encuentre a ese paliducho y le rompa las piernas. ¡Mira cómo sobrevive en el pantano!' WHERE `ID`=1668;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기 있는 저 섬에서 불빛과 인간 그림자를 본 적이 있다. 가서 한번 확인해 보자, $n.', `MaleText_loc4`='我注意到岛那边有一些火光。还有一个人。让我们去那边看看，$n。', `MaleText_loc5`='我注意到島那邊有一些火光。還有一個人。讓我們去那邊看看，$n。', `MaleText_loc7`='He visto fuego en la isla que está allí. También a un humano. Vamos a comprobarlo, $n.' WHERE `ID`=1669;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저건 리테로군. 좋아. 가서 그가 뭐라고 하는지 들어 보자고.', `MaleText_loc4`='那是帕瓦尔·雷瑟。让我们过去看看他会说什么，如何？', `MaleText_loc5`='那是帕瓦爾·雷瑟。讓我們過去看看他會說什麼，如何?', `MaleText_loc7`='Es Reethe, de acuerdo. Veamos qué es lo que tiene que decir, ¿vale?' WHERE `ID`=1670;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 두루마리를 탁자 위에 내려놓고 읽습니다...', `MaleText_loc4`='%s把卷轴放到桌上，开始阅读……', `MaleText_loc5`='%s把卷軸放到了桌上，開始閱讀...', `MaleText_loc7`='%s coloca el pergamino sobre la mesa y lo lee...' WHERE `ID`=1671;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런! 그 괘씸한 밀정이 정말 위험한 녀석이었군! 녀석이 죽었다니 다행이네.', `MaleText_loc4`='以圣光的名义！这个该死的间谍的确厉害！我很高兴他死了！', `MaleText_loc5`='以聖光之名!這個該死的間諜的確厲害!我很高興他死了!', `MaleText_loc7`='¡Por la Luz! ¡Este maldito espía sí que era bueno! Me alegro de que esté muerto.' WHERE `ID`=1672;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보고서를 전해 줘서 고맙네, $n. 이제 테라모어 부근의 순찰을 강화해야겠군.', `MaleText_loc4`='谢谢你的报告，$n。很明显，我们要加强在塞拉摩附近的巡逻。', `MaleText_loc5`='謝謝你的報告，$n。很明顯，我們要加強在塞拉摩附近的巡邏。', `MaleText_loc7`='Gracias por el informe, $n. Está claro que tenemos que aumentar nuestras patrullas cerca de Theramore.' WHERE `ID`=1673;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='워... 원하는 게 뭐야? 그냥 날 내버려둬...', `MaleText_loc4`='你……你要干什么？离我远一点……', `MaleText_loc5`='你...你要幹什麼?離我遠一點...', `MaleText_loc7`='¿Q... qué es lo que quieres? ¡Déjame en paz!' WHERE `ID`=1674;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맹세해. 너에게선 아무것도 훔치지 않았다고! 자, 이걸 가지고 어서 사라져!', `MaleText_loc4`='我发誓，我没有偷你的任何东西！我的东西你可以随便拿，但是请快点离开！', `MaleText_loc5`='我發誓，我沒有偷你的任何東西!我的東西你可以隨便拿，但是請快點離開!', `MaleText_loc7`='¡Te juro que no te he robado nada! ¡Toma, aquí tienes algunas de mis provisiones, pero vete!' WHERE `ID`=1675;
