UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로서 경의 이름으로, 너희 데피아즈단 쓰레기들은 언젠가 대가를 치르게 될 것이다!', `MaleText_loc4`='以洛萨的名义，你们这些迪菲亚渣子会付出代价的！', `MaleText_loc5`='以洛薩的名義，你們這些迪菲亞渣子會付出代價的!', `MaleText_loc7`='¡Por Lothar, Defias, escoria, lo pagaréis!' WHERE `ID`=1703;
