UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그늘 쉼터 여관에 대해 알고 있는 걸 모두 말해! 그렇지 않으면 네놈의 정강이를 걷어차겠다.', `MaleText_loc4`='和我们讲讲你对树荫旅店的事情有什么了解，放心，我不会打你的。', `MaleText_loc5`='和我們講講你對樹蔭旅店瞭解多少，放心，我不會打你的。', `MaleText_loc7`='Solo dinos lo que sabes de la Posada Reposo Umbrío y no te cortaré la cabeza.' WHERE `ID`=1707;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내... 내가 그 여관에서 자잘한 물건을 한두 개 훔쳤던 것도 같지만... 그런데 오우거가 왜 그런 일에 신경 쓰는 거지?', `MaleText_loc4`='我……好吧，我也许从旅店里拿了一些东西……但是为什么食人魔要关心这个？', `MaleText_loc5`='我...好吧，我也許從旅店裡拿了一些東西...但是為什麼巨魔要關心這個?', `MaleText_loc7`='Yo... bueno, quizás haya cogido una cosita o dos de la posada... ¿pero qué le puede importar a un ogro?' WHERE `ID`=1708;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 어서 그 화재에 대해 말하지 않으면...', `MaleText_loc4`='看看这里，如果你不告诉我有关那次火灾的事情的话——', `MaleText_loc5`='看看這裡，如果你不告訴我有關那次火災的事情的話─', `MaleText_loc7`='Mira, si no me cuentas lo del fuego...' WHERE `ID`=1709;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 발자국도 더 가까이 오지 마, 이 오우거!', `MaleText_loc4`='不要过来，食人魔！', `MaleText_loc5`='不要過來，巨魔!', `MaleText_loc7`='¡No des un paso más, ogro!' WHERE `ID`=1710;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 네가 말하는 그 화재에 대해서는 아무것도 모른다고...', `MaleText_loc4`='我对你的这些火并不了解……', `MaleText_loc5`='況且我不懂你說的什麼火災...', `MaleText_loc7`='Si yo no sé nada sobre ese fuego del que hablas...' WHERE `ID`=1711;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 좋아! 싸움은 이제 그만. 누군가 하나가 다칠 필요는 없지.', `MaleText_loc4`='好了，好了！不要再打了！不要再有人受伤了。', `MaleText_loc5`='好了，好了!不要再打了!不要再有人受傷了。', `MaleText_loc7`='¡Muy bien, muy bien! Basta ya de combates. Nadie más tiene que resultar herido.' WHERE `ID`=1712;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만하자고, 친구. 물러서라고. 그만하면 충분하지 않나. 나중에 보자고.', `MaleText_loc4`='好了，伙计们，退后。你们做得够多了。我们以后再见！', `MaleText_loc5`='好了，夥計們，退後。你們做得夠多了。我們以後再見!', `MaleText_loc7`='Vale, chicos. Regresad. Habéis hecho suficiente. Os veré más tarde.' WHERE `ID`=1713;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파발 리테! 마침내 찾아냈군. 이젠 오우거들과 어울리고 있나? 두려워 말라고. 탈영병이나 배반자에게도 자비의 손길을 베풀 순 있으니까.', `MaleText_loc4`='帕瓦尔·雷瑟！终于找到你了。你现在和食人魔混在一起了？不要害怕，即便是背叛者也会得到宽恕。', `MaleText_loc5`='帕瓦爾·雷瑟!終於找到你了。你現在和巨魔混在一起了?不要害怕，即便是背叛者也會得到寬恕。', `MaleText_loc7`='¡Paval Reethe! Por fin te he encontrado. ¿Y ahora tratas con los ogros? No temas, incluso los desertores y traidores merecen algo de clemencia.' WHERE `ID`=1714;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예. 알겠습니다, 두목. 문제없다고요.', `MaleText_loc4`='好了，老板。没问题。', `MaleText_loc5`='好了，老闆。沒問題。', `MaleText_loc7`='Sí, vale, jefe. No hay problema.' WHERE `ID`=1715;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠습니다, 두목. 근데 정말로 그만할까요? 좋은 연습 상대인 것 같은데...', `MaleText_loc4`='好罢，老大。不过你确定吗？浪费了一个挺好的练习机会……', `MaleText_loc5`='都好了，老闆。不過你確定嗎?浪費了一個挺好練習機會...', `MaleText_loc7`='Está bien, jefe. Pero ¿seguro? Sería un desperdicio no aprovechar tanto talento.' WHERE `ID`=1716;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 손마디에서 우두둑 소리를 냅니다.', `MaleText_loc4`='%s捏着他的关节。', `MaleText_loc5`='%s捏著他的關節。', `MaleText_loc7`='%s hace crujir los nudillos.' WHERE `ID`=1717;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훌륭한 $c, $n에게 모두 만세!', `MaleText_loc4`='为$n欢呼吧，$g他:她;是一个如此出色的$c！', `MaleText_loc5`='為$n歡呼吧，$g他:她;是一個如此出色的$c!', `MaleText_loc7`='¡Ave $n, un $c de valor!' WHERE `ID`=1718;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 주목하시오! 고독한 은둔자 선술집에서는 $n|1을;를; 위한 잔치를 베풀 것이오!', `MaleText_loc4`='注意！蓝色隐士旅店正在举行一次聚会！', `MaleText_loc5`='注意!藍色隱士旅店正在舉行一次聚會!', `MaleText_loc7`='¡Mirad! ¡El Ermitaño Taciturno dará una fiesta en su honor!' WHERE `ID`=1719;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='할란 병사, 부관 리테에게 자비를 좀 베풀어 주어라!', `MaleText_loc4`='士兵，别对雷瑟中尉太狠了。', `MaleText_loc5`='士兵，別對雷瑟中尉太狠了。', `MaleText_loc7`='Soldado, muestre un poco de misericordia hacia el teniente Reethe.' WHERE `ID`=1720;
