UPDATE `locales_broadcast_text` SET `MaleText_loc1`='젠장! 내 앞에서 죽지 마, 인간!', `MaleText_loc4`='该死！你最好不要死在我手上！', `MaleText_loc5`='該死!你最好不要棄我而去，人類!', `MaleText_loc7`='¡Maldita sea! ¡Será mejor que no mueras aquí, humano!' WHERE `ID`=1724;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='운 좋은 날인 줄 알라고. 좋아, 말해 주지. 그러니 날 제발 좀 내버려둬. 이봐, 내 말이 믿기지 않겠지만, 그건... 으, 젠장, 할란이 쏜 게... 윽...', `MaleText_loc4`='今天一定是你幸运的一天。好吧，我会说的。先让我一个人呆一会。瞧，你还不相信我，但它……哦，天哪……', `MaleText_loc5`='今天一定是你幸運的一天。好吧，我會說的。只要別再來煩我就好。聽著，你不會相信我所說的，但這全都是...哦，那是聖光，看來那個女孩箭射得不錯...', `MaleText_loc7`='Debe ser tu día de suerte. Muy bien, hablaré. Pero déjame solo. Mira, no vas a creerme, pero era... oh, Luz, es como si la niña pudiera disparar...' WHERE `ID`=1725;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='괜찮나, 리테?', `MaleText_loc4`='雷瑟，你在干什么？', `MaleText_loc5`='雷瑟，你還好吧?', `MaleText_loc7`='¿Sigues aquí, Reethe?' WHERE `ID`=1726;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자다!', `MaleText_loc4`='入侵者！', `MaleText_loc5`='入侵者!', `MaleText_loc7`='¡Intrusos!' WHERE `ID`=1727;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 침입했다!', `MaleText_loc4`='他们在这里！', `MaleText_loc5`='他們在這裡!', `MaleText_loc7`='¡Están aquí!' WHERE `ID`=1728;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='숨이 끊어진 것 같다. 이래서는 우리에게 별 도움이 안 되지. 당신은 돌아가서 크로그에게 이 일에 대해 보고하는 게 좋겠다.', `MaleText_loc4`='好像是挂了，你最好回去告诉克罗格这里发生了什么。', `MaleText_loc5`='我看是掛了。這一來對我們毫無幫助。你最好回去告訴克羅格發生了什麼事。', `MaleText_loc7`='Me parece que ha muerto. Así nos servirá de poco. Será mejor que regreses y le digas a Krog lo que ha ocurrido.' WHERE `ID`=1729;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 날 엄호해 줘서 고맙다.', `MaleText_loc4`='顺便说一下，谢谢你帮我望风。', `MaleText_loc5`='順便說一下，謝謝你幫我望風。', `MaleText_loc7`='Por cierto, gracias por vigilar mi retaguardia.' WHERE `ID`=1730;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐지? 무슨 소리지?', `MaleText_loc4`='那是什么？你听到什么了吗？', `MaleText_loc5`='那是什麼?你聽到什麼了嗎?', `MaleText_loc7`='¿Qué ha sido eso? ¿Has oído algo?' WHERE `ID`=1731;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 가슴에 화살이 깊이 박히자 뒤로 비틀거립니다.', `MaleText_loc4`='%s被箭射中了胸膛，摇摇晃晃地向后退了几步。', `MaleText_loc5`='%s被箭射中了胸膛，搖搖晃晃地向後退了幾步。', `MaleText_loc7`='%s se tambalea hacia atrás mientras la flecha se hunde profundamente de su pecho.' WHERE `ID`=1732;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 만세!', `MaleText_loc4`='干得好，$n！', `MaleText_loc5`='幹得好，$n!', `MaleText_loc7`='¡Hurra, $n!' WHERE `ID`=1733;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1을;를; 위해 건배!', `MaleText_loc4`='为$n欢呼！', `MaleText_loc5`='為$n歡呼!', `MaleText_loc7`='¡Aclamemos a $n!' WHERE `ID`=1734;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='건배!', `MaleText_loc4`='耶！', `MaleText_loc5`='耶!', `MaleText_loc7`='¡Alabado sea!' WHERE `ID`=1735;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1을;를; 위하여!', `MaleText_loc4`='$n万岁！', `MaleText_loc5`='$n萬歲!', `MaleText_loc7`='¡Larga vida a $n!' WHERE `ID`=1736;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 펜던트를 조사할 자를 불러서 숨겨진 비밀을 밝혀야겠네.', `MaleText_loc4`='现在，我会找一些人去检查这个坠饰，看看其中有什么隐藏的东西……', `MaleText_loc5`='現在，我會找一些人去檢查這個墜飾，看看其中有什麼隱藏的東西...', `MaleText_loc7`='En este punto pediré a alguien que examine el colgante y que encuentre un compartimento secreto...' WHERE `ID`=1737;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 펜던트에 뭐가 들어 있을지는 아직 모르네. 우선 팻 네이글과 마이클 바커스와 상의해야겠군.', `MaleText_loc4`='我不知道这里面有什么。Pat Nagle和Michael Backus需要先就这个讨论一下……', `MaleText_loc5`='我不知道這裡面有什麼。派特·耐谷和麥可·貝可士需要先就這個討論一下...', `MaleText_loc7`='Todavía no sé que habrá dentro. Pat Nagle y Michael Backus tienen que hablar primero de ello...' WHERE `ID`=1740;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 그럼 나중에 보세!', `MaleText_loc4`='等他们完成再说吧……再见！', `MaleText_loc5`='等他們完成再說吧...再見!', `MaleText_loc7`='Así que, hasta que lo hagan... ¡adiós!' WHERE `ID`=1741;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 그만! 말하겠다. 무기를 거두라. 네가 싸워야 할 상대는 내가 아니다.', `MaleText_loc4`='够了！我会说的。收起你的武器，你不必用它来跟我争论……', `MaleText_loc5`='夠了!我會說的。收起你的武器，你不必用它來跟我爭論...', `MaleText_loc7`='¡Ya es suficiente! Hablaré. Aparta tus armas, no es conmigo con quien estás enfrentado.' WHERE `ID`=1742;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 좋아! 폭력은 빼고 얘기하지. 얘기한다고!', `MaleText_loc4`='好了，好了！不要动粗。我会说的，我会说的！', `MaleText_loc5`='好了，好了!不要動粗。我會說的，我會說的!', `MaleText_loc7`='¡Vale, vale! No es necesaria tanta violencia. Hablaré. ¡Hablaré!' WHERE `ID`=1743;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 거처에 그 일에 대한 메모가 좀 있으니 그걸 가지고 여관에서 다시 만나자고.', `MaleText_loc4`='我要回去拿点东西，然后再去旅店里见你。', `MaleText_loc5`='我要回去拿點東西，然後再去旅店裡見你。', `MaleText_loc7`='Tengo unas cuantas notas del trabajo en casa. Las cogeré y te volveré a encontrar en la posada.' WHERE `ID`=1744;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무 죄도 없는 그 불쌍한 사람을 좀 내버려두시오.', `MaleText_loc4`='把那个可怜人留在这里，你不应该为此浪费时间。', `MaleText_loc5`='把那個可憐人留在這裡，居民，你不應該為此浪費時間。', `MaleText_loc7`='Dejad al pobre hombre a solas, ciudadanos, no merece la pena.' WHERE `ID`=1745;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 잠시 나와 얘기를 했으면 합니다.', `MaleText_loc4`='$n，我有些话要和你说。', `MaleText_loc5`='$n，我有些話要和你說。', `MaleText_loc7`='$n, me gustaría hablar contigo.' WHERE `ID`=1748;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가서 일들 보시오. 내가 여기 온건 그대들과는 상관없소이다.', `MaleText_loc4`='去忙你自己的事情吧，这边的事情不需要你操心。', `MaleText_loc5`='去忙你自己的事情吧，這邊的事情不需要你操心。', `MaleText_loc7`='Métete en tus asuntos. Mi misión no es de tu interés.' WHERE `ID`=1749;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='차려엇!', `MaleText_loc4`='小心！', `MaleText_loc5`='小心!', `MaleText_loc7`='¡Atención!', `FemaleText_loc1`='차려엇!', `FemaleText_loc4`='小心！', `FemaleText_loc5`='小心!', `FemaleText_loc7`='¡Atención!' WHERE `ID`=1750;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 이제 당당히 나아가십시오. 프라우드무어 님의 마법이 당신을 보호할 것입니다.', `MaleText_loc4`='一路顺风，愿吉安娜女士的魔法保护你。', `MaleText_loc5`='一路順風，願珍娜女士的魔法保護你。', `MaleText_loc7`='Que la gracia te acompañe y que la magia de la Dama te proteja.' WHERE `ID`=1751;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='팰그런 해스틸입니다, 사령관님. 발굽 자국이 어디로 이어져 있는지 확인한 후 다시 보고 드리겠습니다.', `MaleText_loc4`='法格兰·哈斯迪尔前来报告，长官。我将会找出蹄印前往的地方，然后再回来向你报告。', `MaleText_loc5`='法格蘭·哈斯迪爾前來報告，長官。我將會找出蹄印前往的地方，然後再回來向你報告。', `MaleText_loc7`='Falgran Hastil se presenta, señor. Averiguaré hacia dónde llevan las huellas y traeré noticias.' WHERE `ID`=1752;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='테소렌! 그늘 쉼터 여관 부근에서 $n|1이;가; 발견한 발굽 자국 단서를 조사할 사람이 필요하다. 되도록이면 팰그런 해스틸이 맡았으면 좋겠군.', `MaleText_loc4`='泰索兰！我需要一些人，最好是法格兰·哈斯迪尔，到树荫旅店附近去调查一下$n发现的那些蹄印。', `MaleText_loc5`='泰索蘭!我需要一些人，最好是法格蘭·哈斯迪爾，到樹蔭旅店附近去調查一下$n發現的那些蹄印。', `MaleText_loc7`='¡Tesoran! Necesito a alguien, preferiblemente a Falgran Hastil, para que se ocupe de la dirección que llevan las huellas de $n cerca de la Posada Reposo Umbrío.' WHERE `ID`=1753;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠습니다, 사령관님.', `MaleText_loc4`='马上就去，长官。', `MaleText_loc5`='馬上就去，長官。', `MaleText_loc7`='Ahora mismo, señor.' WHERE `ID`=1754;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카고로, 어디 있나?', `MaleText_loc4`='卡古隆，过来！', `MaleText_loc5`='卡古隆，過來!', `MaleText_loc7`='Kagoro, ¡exijo tu presencia!' WHERE `ID`=1755;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아! 좋아! 항복하지... 협조할 테니 무기는 내려놓으라고!', `MaleText_loc4`='好了，好了！我们投降……不过请放下你的武器，我会合作的！', `MaleText_loc5`='好了，好了!我們投降...不過請放下你的武器，我會合作的!', `MaleText_loc7`='¡Está bien! ¡Está bien! Nos rendimos... solo bajad las armas, cooperaré...' WHERE `ID`=1756;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='설령 네가 나를 이긴다 하더라도 데피아즈단은 반드시 스톰윈드를 되찾을 것이다!', `MaleText_loc4`='你也许可以杀了我，但迪菲亚兄弟会必定夺回暴风城！', `MaleText_loc5`='你也許可以殺了我，但迪菲亞兄弟會必定奪回暴風城!', `MaleText_loc7`='Podréis cogerme, ¡pero los Defias RECUPERARÁN Ventormenta!' WHERE `ID`=1757;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='욱... 이거 안 좋은데.', `MaleText_loc4`='啊……这太糟糕了。', `MaleText_loc5`='啊...這太糟糕了。', `MaleText_loc7`='Oh-oh, tengo un mal presagio.' WHERE `ID`=1758;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부디... 제발... 프라우드무어 님. 그럴 뜻은 아니었습니다...', `MaleText_loc4`='求求你了……普罗德摩尔小姐。我并不是想要……', `MaleText_loc5`='求求你了...普勞德摩爾小姐。我並不是想要...', `MaleText_loc7`='Por favor... por favor... Señorita Valiente. No tenía la intención de...' WHERE `ID`=1759;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 싸웠다, 에드워드. 카힐이 홍팀을 이길 수 있을지 지켜보자.', `MaleText_loc4`='贾拉德，你在战斗中表现得十分英勇。让我们看看卡希尔是否能搞定他们。', `MaleText_loc5`='愛德華，你在戰鬥中表現得十分英勇。讓我們看看卡希爾是否能搞定他們。', `MaleText_loc7`='Luchas bien, Edward. Veremos si Kahil puede con ellos.' WHERE `ID`=1760;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 오는 데 너무 오래 걸려서 미안합니다. 프라우드무어 님께서도 함께하셔야 할 것 같아서 말입니다.', `MaleText_loc4`='真对不起，我花了这么多时间才到这里。我希望普罗德摩尔女士现在就能接见我。', `MaleText_loc5`='真對不起，我花了這麼多時間才到這裡，因為我希望普勞德摩爾女士也能在場。', `MaleText_loc7`='Pido disculpas por tardar tanto en llegar hasta aquí. Quería que Lady Valiente también estuviera presente.' WHERE `ID`=1761;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카힐, 수고 많았다. 나리샤가 결판을 내줄 테니 이리 와서 쉬도록.', `MaleText_loc4`='卡希尔，你干得很好。回来休息一下。娜里莎会帮我们清理这里的。', `MaleText_loc5`='卡希爾，你幹得很好。回來休息一下。娜莉莎會幫我們清理這裡的。', `MaleText_loc7`='Kahil, ha sido un enorme esfuerzo. Vuelve y descansa. Narrisha lo limpiará por nosotros.' WHERE `ID`=1762;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용감히 잘 싸웠다, 나리샤. 다음번에는 꼭 꺾고 말겠다, 홍팀!', `MaleText_loc4`='娜里莎战斗得很勇敢。我们下次肯定能打败你们红队！', `MaleText_loc5`='娜莉莎戰鬥得很勇敢。我們下次肯定能打敗你們紅隊!', `MaleText_loc7`='Has luchado muy bien, Narrisha. ¡La próxima vez os ganaremos, equipo rojo!' WHERE `ID`=1763;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 열심히 용감하게 잘 싸웠다. 제군들이 이렇게 훌륭한 전사가 된 것을 보니 마음이 뿌듯하군.', `MaleText_loc4`='你们在战斗中都表现得很勇敢。这令我十分骄傲，你们都已经成为了真正的战士。', `MaleText_loc5`='你們在戰鬥中都表現得很勇敢。這令我十分驕傲，你們都已經成為了真正的戰士。', `MaleText_loc7`='Todos luchasteis con ardor y valentía. Me enorgullece descubrir los guerreros en los que os habéis convertido.' WHERE `ID`=1764;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번엔 우리가 졌지만 너무 실망하지 마라. 공격에 집중하고 방패를 가까이, 높게 들어라. 그러면 다음엔 반드시 승리할 수 있다!', `MaleText_loc4`='我们这次输了，但大家不要气馁。专心攻击，把盾牌举高点，然后慢慢靠近对手。这样我们下次就可以取得胜利！', `MaleText_loc5`='我們這次輸了，但大家不要氣餒。專心攻擊，把盾牌舉高點，然後慢慢靠近對手。這樣我們下次就可以取得勝利!', `MaleText_loc7`='Esta vez hemos perdido, pero no quiero que eso les baje la moral. Concentrense en sus ataques especiales. Mantengan sus escudos en alto y cerca del cuerpo. ¡Hagan lo que les digo y la próxima vez, la victoria será nuestra!' WHERE `ID`=1765;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형편 없군, 제럴드. 다음엔 방패를 더 높게 들라고. 라나! 자네 차례야!', `MaleText_loc4`='贾拉德，下回把盾牌举高点。兰纳！你上！', `MaleText_loc5`='賈拉德，下回把盾牌舉高點。蘭納!你上!', `MaleText_loc7`='¡Menuda pelea, Jarad! La próxima vez tienes que levantar más ese escudo. ¡Lana! ¡Estás dentro!' WHERE `ID`=1766;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라나, 오늘 왜 그러나? 그것보다는 잘 하는 줄 알았더니. 다음에는 좀 더 잘하도록! 타크, 자네가 청팀에 쓴 맛을 보여줘!', `MaleText_loc4`='兰纳，我感觉你比以前更出色了！你下次会打赢的！塔克，过来，让他们见识见识！', `MaleText_loc5`='蘭納，我感覺你比以前更出色了!你下次會打贏的!塔克，過來，讓他們見識見識!', `MaleText_loc7`='¡Te he visto luchar mejor otras veces, Lana! ¡La próxima vez les ganaréis! ¡Tark, entra allí y hazles sufrir!' WHERE `ID`=1767;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타크, 대체 그게 뭔가! 자네 실력이 그것밖에 안 됐었나? 홍팀, 곧 오늘의 복수를 해 주겠다!', `MaleText_loc4`='塔克，怎么回事？你应该知道你比他们要厉害！蓝队，加油！', `MaleText_loc5`='塔克，怎麼回事?你知道你可以做的更好!藍隊，你們待會就可以知道我們的厲害!', `MaleText_loc7`='Tark ¿qué pasó allí dentro? ¡Tú sabes que puedes luchar mejor! ¡Equipo azul, pronto recibirán su merecido!' WHERE `ID`=1768;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 싸웠어! 내가 다 자랑스럽군. 지금처럼만 하면 오늘 밤 술은 내가 사지!', `MaleText_loc4`='干得漂亮！你们让一个老人感到骄傲。好好干，今晚我请大家喝啤酒来犒劳你们。', `MaleText_loc5`='幹得漂亮!你們讓一個老人感到驕傲。好好幹，今晚我請大家喝麥芽酒來犒勞你們。', `MaleText_loc7`='¡Excelente pelea! Has hecho que este viejo se enorgullezca de ustedes. Sigan así y la cerveza correrá de mi cuenta esta noche.' WHERE `ID`=1769;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 그렇게 형편없을 수가 있나? 너희처럼 쓸모없는 것들은 모조리, 아니 경비대에서 내쫓아 버려야지 안 되겠군!', `MaleText_loc4`='看看你们的比赛都打成什么样子了？你们这帮废物，我要把你们统统踢出队伍！', `MaleText_loc5`='看看你們的比賽都打成什麼樣子了?你們這幫廢物，我要把你們統統踢出隊伍!', `MaleText_loc7`='¿Qué clase de lucha ha sido esa? ¡Debería echaros a todos fuera del equipo y de la guardia, pellejos inservibles!' WHERE `ID`=1770;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부대장들은 첫 번째 부대원을 내보내 주게.', `MaleText_loc4`='队长，派出你的第一名队员吧。', `MaleText_loc5`='隊長，派出你的第一名隊員吧。', `MaleText_loc7`='Capitanes, envíen al frente a sus primeros combatientes.' WHERE `ID`=1771;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕히. 분명 다음에 다시 얘기할 기회가 있을 겁니다.', `MaleText_loc4`='再见，多保重。', `MaleText_loc5`='再見，多保重。', `MaleText_loc7`='Adiós. Volveremos a vernos, estoy seguro.' WHERE `ID`=1772;
