UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 생각엔 이놈이 마지막인 것 같군. 아주 때맞춰 잘 와 줬소. 얼마나 더 숨어 있을 수 있을지 모를 상황이었다오.', `MaleText_loc4`='我想那是最后一个。你来得真是时候……我不知道我还能躲多久。', `MaleText_loc5`='我想那是他們僅存的最後一個了。你來得真是時候...我不知道我還能躲多久。', `MaleText_loc7`='Creo que es el último que quedaba de ellos. Qué bien que hayas venido en el momento preciso... No estaba seguro de cuánto tiempo podía permanecer oculto.' WHERE `ID`=1838;
