UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은무쇠 드워프의 힘을 느껴봐라!', `MaleText_loc4`='感受一下黑铁矮人的力量吧！', `MaleText_loc5`='感受一下黑鐵矮人的力量吧!', `MaleText_loc7`='¡Siente el poder de los enanos Hierro Negro!', `FemaleText_loc1`='검은무쇠 드워프의 힘을 느껴봐라!', `FemaleText_loc4`='感受一下黑铁矮人的力量吧！', `FemaleText_loc5`='感受一下黑鐵矮人的力量吧!', `FemaleText_loc7`='¡Siente el poder de los enanos Hierro Negro!' WHERE `ID`=1936;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용아귀 부족을 위하여!', `MaleText_loc4`='为了龙喉氏族而战！', `MaleText_loc5`='為了龍喉氏族而戰!', `MaleText_loc7`='¡Por los Faucedraco!', `FemaleText_loc1`='용아귀 부족을 위하여!', `FemaleText_loc4`='为了龙喉氏族而战！', `FemaleText_loc5`='為了龍喉氏族而戰!', `FemaleText_loc7`='¡Por los Faucedraco!' WHERE `ID`=1937;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 놈을 기꺼이 혼내주마, $r!', `MaleText_loc4`='我要踩碎你的骨头，$R！', `MaleText_loc5`='你的骨頭將會在我的腳下碎裂，$r!', `MaleText_loc7`='¡Tus huesos se romperán bajo mi bota, $r!', `FemaleText_loc1`='네 놈을 기꺼이 혼내주마, $r!', `FemaleText_loc4`='我要踩碎你的骨头，$R！', `FemaleText_loc5`='你的骨頭將會在我的腳下碎裂，$r!', `FemaleText_loc7`='¡Tus huesos se romperán bajo mi bota, $r!' WHERE `ID`=1938;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용아귀 부족 만세! 죽어라, 이 쓸모없는 $r!', `MaleText_loc4`='龙喉氏族万岁！去死吧，没用的$c！', `MaleText_loc5`='龍喉氏族萬歲!去死吧，沒用的$r!', `MaleText_loc7`='¡Larga vida a los Faucedraco! ¡Muere, insignificante $r!', `FemaleText_loc1`='용아귀 부족 만세! 죽어라, 이 쓸모없는 $r!', `FemaleText_loc4`='龙喉氏族万岁！去死吧，没用的$c！', `FemaleText_loc5`='龍喉氏族萬歲!去死吧，沒用的$r!', `FemaleText_loc7`='¡Larga vida a los Faucedraco! ¡Muere, insignificante $r!' WHERE `ID`=1939;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신선한 냄새가 나는군...', `MaleText_loc4`='食物……', `MaleText_loc5`='腦子...', `MaleText_loc7`='Cerebros...', `FemaleText_loc1`='신선한 냄새가 나는군...', `FemaleText_loc4`='食物……', `FemaleText_loc5`='腦子...', `FemaleText_loc7`='Cerebros...' WHERE `ID`=1940;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살아 있는 $r|1이로군;로군;... 곧 나처럼 죽겠지만 말이야.', `MaleText_loc4`='一个活着的$R……不久就会变成一个像我这样的亡灵。', `MaleText_loc5`='一個活著的$r...不久就會變成一個像我這樣的亡靈。', `MaleText_loc7`='$gUn:Una; $r... viviente será pronto un muerto como yo.', `FemaleText_loc1`='살아 있는 $r|1이로군;로군;... 곧 나처럼 죽겠지만 말이야.', `FemaleText_loc4`='一个活着的$R……不久就会变成一个像我这样的亡灵。', `FemaleText_loc5`='一個活著的$R...不久就會變成一個像我這樣的亡靈。', `FemaleText_loc7`='$gUn:Una; $r... viviente será pronto un muerto como yo.' WHERE `ID`=1941;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리와 같은 운명을 맞을 때가 왔다, $c.', `MaleText_loc4`='加入我们吧，$C。', `MaleText_loc5`='加入我們吧，$C。', `MaleText_loc7`='Es hora de unirte a nosotros, $c.', `FemaleText_loc1`='우리와 같은 운명을 맞을 때가 왔다, $c.', `FemaleText_loc4`='加入我们吧，$C。', `FemaleText_loc5`='加入我們吧，$C。', `FemaleText_loc7`='Es hora de unirte a nosotros, $c.' WHERE `ID`=1942;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코마크! 맹세코 돈을 준비하겠소. 시간을 조금만 더 주시오.', `MaleText_loc4`='库马克！我发誓我会变得有钱的！只要多给我点时间！', `MaleText_loc5`='寇瑪克!我發誓我會變得有錢的!只要多給我點時間!', `MaleText_loc7`='¡Komak! ¡Juro que conseguiré el dinero! ¡Solo dame un poco más de tiempo!' WHERE `ID`=1943;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 헛기침을 합니다.', `MaleText_loc4`='%s清了清嗓子。', `MaleText_loc5`='%s清了清他的嗓子。', `MaleText_loc7`='%s se aclara la garganta.' WHERE `ID`=1944;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나와 내 친구 사로크에게 술이나 사시오.', `MaleText_loc4`='一杯酒给我的朋友萨洛克，另一杯给我自己。', `MaleText_loc5`='一杯酒給我的朋友薩洛克，另一杯給我自己。', `MaleText_loc7`='Un trago para el amigo Sarok y otro para mí.' WHERE `ID`=1945;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='괜한 문제 일으키지 마시오, 코마크.', `MaleText_loc4`='我不想惹麻烦，库马克。', `MaleText_loc5`='我不想惹麻煩，寇瑪克。', `MaleText_loc7`='No quiero problemas, Komak.' WHERE `ID`=1946;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사로크, 우리 사업 얘기 좀 하지?', `MaleText_loc4`='萨洛克，我们为什么不谈谈生意？', `MaleText_loc5`='薩洛克，我們為什麼不談談生意?', `MaleText_loc7`='Sarok, ¿por qué no hablamos de negocios?' WHERE `ID`=1947;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원하는 게 뭔가, 코마크?', `MaleText_loc4`='库马克，你想要什么？', `MaleText_loc5`='寇瑪克，你想要什麼?', `MaleText_loc7`='¿Qué quieres, Komak?' WHERE `ID`=1948;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 이 악마의 도구들을 파괴하러 왔다! 호드를 위해!', `MaleText_loc4`='我必须摧毁这些恶魔的工具！为了部落！', `MaleText_loc5`='我必須摧毀這些惡魔的工具!為了部落!', `MaleText_loc7`='¡Mediante este acto destruyo estos instrumentos del mal! ¡Por la Horda!' WHERE `ID`=1949;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼림도어 칵테일을 만들 시간이야! 딸꾹!', `MaleText_loc4`='来一杯卡利姆多鸡尾酒！嗝儿！', `MaleText_loc5`='來一杯卡林多雞尾茶!嗝兒!', `MaleText_loc7`='¡Es hora de preparar un cubata de Kalimdor! ¡Hip!' WHERE `ID`=1950;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이만하면 되겠군! 딸꾹!', `MaleText_loc4`='真棒！嗝儿！', `MaleText_loc5`='真棒!嗝兒!', `MaleText_loc7`='¡Con eso bastará! ¡Hip!' WHERE `ID`=1951;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 꿀꺽꿀꺽 소리를 내며 술을 마십니다.', `MaleText_loc4`='%s咕隆一口全喝了下去。', `MaleText_loc5`='%s喝下了飲料。', `MaleText_loc7`='%s se traga su bebida.' WHERE `ID`=1952;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='딸꾹!', `MaleText_loc4`='嗝儿！', `MaleText_loc5`='嗝兒!', `MaleText_loc7`='¡Hip!' WHERE `ID`=1953;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 누가 날 주저앉힌 거지? 당신이야? 누가 불 좀 다시 켜 봐. 딸꾹!', `MaleText_loc4`='嗯，谁把我推下去了？是你吗，$n？谁去把灯开一下啊？嗝儿！', `MaleText_loc5`='嗯，誰把我推下去了?是你嗎，$n?誰去把燈開一下啊?嗝兒!', `MaleText_loc7`='Vale, ¿quién me tiró al suelo? ¿Fuiste tú, $n? Que alguien encienda las luces, ¡hic!' WHERE `ID`=1954;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불같이 독한 이 술 한 모금만 더 마시고 얘기하지. 딸꾹! 자, 건배!', `MaleText_loc4`='再喝一口酒，我就可以发言了。嗝儿！干杯！', `MaleText_loc5`='再喝一口酒，我就可以發言了。嗝兒!乾杯!', `MaleText_loc7`='Un traguito más del viejo aguardiente y estaré listo para hablar. ¡Hip! ¡Salud!' WHERE `ID`=1955;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, $n. 이제 슬픔의 늪에서 있었던 일을 얘기해 줄 준비가 됐어. 딸꾹!', `MaleText_loc4`='那么，$n，我来告诉你在悲伤沼泽发生了什么。嗝儿！', `MaleText_loc5`='那麼，$n，我來告訴你在悲傷沼澤發生了什麼。嗝兒!', `MaleText_loc7`='Muy bien, $n, estoy listo para contarte lo que ocurrió en el Pantano de las Penas. ¡Hip!' WHERE `ID`=1956;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공격!', `MaleText_loc4`='出击！', `MaleText_loc5`='出擊!', `MaleText_loc7`='¡Ataquen!' WHERE `ID`=1957;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시작!', `MaleText_loc4`='战斗！', `MaleText_loc5`='戰鬥!', `MaleText_loc7`='¡Luchad!' WHERE `ID`=1958;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='홍팀 승리! 다음 대련을 준비하시오.', `MaleText_loc4`='红队赢了！准备好下一轮。', `MaleText_loc5`='紅隊贏了!準備好下一輪。', `MaleText_loc7`='¡El azul gana! Preparaos para la siguiente ronda.' WHERE `ID`=1959;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='청팀 승리! 다음 대련을 준비하시오.', `MaleText_loc4`='蓝队赢了！准备好下一轮。', `MaleText_loc5`='藍隊贏了!準備好下一輪。', `MaleText_loc7`='¡El azul gana! Preparaos para la siguiente ronda.' WHERE `ID`=1960;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 잘 알았겠지!', `MaleText_loc4`='现在你要好好了解一下了，$n！', `MaleText_loc5`='現在你要好好瞭解一下了，$n!', `MaleText_loc7`='¡Vas a recibir una buena, $n!' WHERE `ID`=1961;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='많이 화났나, 사로크? 그렇다고 과음은 하지는 말라고. 그냥 모사른에 대해 아는 대로 전부 얘기해 주면 돼.', `MaleText_loc4`='很生气吗，萨洛克？你不应该喝这么多……告诉我们，你对莫萨恩了解多少。', `MaleText_loc5`='很生氣嗎，薩洛克?你不應該喝這麼多...告訴我們，你對莫薩恩瞭解多少。', `MaleText_loc7`='¿Estás enfadado, Sarok? No deberías beber tanto... Solo dinos lo que sabes acerca de Mosarn.' WHERE `ID`=1962;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 말라깽이 친구들. 얼마나 잘 배웠는지 한번 볼까? 내가 멈추라고 할 때까지 계속 공격하도록.', `MaleText_loc4`='好了，你这堆可怜的烂骨头。让我们看看你有什么本事。攻击你的对手，我说停的时候你才能停止。', `MaleText_loc5`='好了，你這堆可憐的爛骨頭。讓我們看看你有什麼本事。攻擊你的對手，我說停的時候你才能停止。', `MaleText_loc7`='Bueno, lo lamentarán, sacos de huesos. Veamos lo que tienen. Golpeen a su oponente y no paren hasta que yo lo ordene.' WHERE `ID`=1963;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만! 너희 그걸 전투라고 하는 건가? 형편없군! 제대로 한번 싸워 보라고, 아니면 끝장날 줄 알아!', `MaleText_loc4`='停！你们把这个叫做战斗？真可怜！现在用心去战斗，好吧，你们其实已经没那东西了。', `MaleText_loc5`='停!你們把這個叫做戰鬥?真可憐!現在用心去戰鬥，好吧，你們其實已經沒那東西了。', `MaleText_loc7`='¡Basta! ¿Llamáis a eso pelear, gusanos? ¡Eso es patético! ¡Poned todo el corazón! ¡De todas maneras ya no os va a hacer falta!' WHERE `ID`=1964;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 꼴을 좀 보라고. 내가 본 것 중 가장 형편없는 검술이야!', `MaleText_loc4`='你们知道自己看起来有多烂吗？这是我见过的最可笑的战斗！', `MaleText_loc5`='你們知道自己看起來有多爛嗎?這是我見過的最可笑的戰鬥!', `MaleText_loc7`='¿No os estáis viendo? ¡Es la excusa más patética para blandir la espada que he visto nunca!' WHERE `ID`=1965;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희는 자신을 위해 싸우는 게 아니다! 이제 너희는 여왕님을 위해 싸우는 영예로운 전사다. 그러니 자격을 갖추었다는 것을 증명해 보이도록!', `MaleText_loc4`='你们不再是只为了自己而战斗，蠢货！你们现在是为希尔瓦娜斯女王而战，所以快点表现出你们的价值来！', `MaleText_loc5`='你們不再是只為了自己而戰鬥，蠢貨!你們現在是為希瓦娜斯女王而戰，所以快點表現出你們的價值來!', `MaleText_loc7`='¡Gusanos, ahora no luchan por ustedes! ¡Luchan por la Reina, así que muéstrenme algo digno de ella!' WHERE `ID`=1966;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이것들 봐라. 땅속에 묻히지만 않았지 완전히 죽은 녀석들 같군. 죽을 힘을 다해서 해 보란 말이야!', `MaleText_loc4`='你们是死了，但不是被埋了。现在让我看看你们的实力吧！', `MaleText_loc5`='你們是死了，但不是被埋了。現在讓我看看你們的實力吧!', `MaleText_loc7`='Estáis muertos, pero no enterrados. ¡Dad lo mejor que tenéis!' WHERE `ID`=1967;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이까짓 나무와 지푸라기로 만든 허수아비는 자비를 베풀지 몰라도 리치 왕은 절대 봐 주지 않는다!', `MaleText_loc4`='木头和稻草会显示出怜悯之心，但巫妖王不会！', `MaleText_loc5`='木頭和稻草會顯示出憐憫之心，但巫妖王不會!', `MaleText_loc7`='Puede que estos montones de madera y paja muestren clemencia, ¡pero el Rey Exánime no lo hará!' WHERE `ID`=1968;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 실력이 겨우 그 정도밖에 안 되는 건 아니겠지? 자, 증명해 봐!', `MaleText_loc4`='你们最好现在就能证明自己不是个废物！', `MaleText_loc5`='你們最好現在就能證明自己不是個廢物!', `MaleText_loc7`='Ustedes, sacos de carne de gusano, pueden dar mucho más que eso, ¡demuéstrenlo!' WHERE `ID`=1969;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은 단순한 도구가 아니야! 검은 네 몸의 일부다. 더 잘할 수 없나!', `MaleText_loc4`='剑不是工具，它是你的延伸。我希望你们能做得更好！', `MaleText_loc5`='劍不是工具，它是你的延伸。我希望你們能做得更好!', `MaleText_loc7`='La espada no es un instrumento, es una extensión de ustedes. ¡Estoy esperando a que lo hagan mejor!' WHERE `ID`=1970;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐하고 있는 건가? 그걸 전투라고 할 수 있겠나? 그게 전투면 난 로서다!', `MaleText_loc4`='你那也叫作战？如果那也叫战斗，那我就是战神了！', `MaleText_loc5`='你那也叫作戰?如果那也叫戰鬥，那我就是戰神了!', `MaleText_loc7`='¿Cómo llamáis a eso que hacéis? ¡Si eso es luchar, entonces yo soy el propio Lothar!' WHERE `ID`=1971;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 제군들. 휴식이다!', `MaleText_loc4`='好了，士兵们，休息一下！', `MaleText_loc5`='好了，士兵們，休息一下!', `MaleText_loc7`='¡Vale, Soldados, a descansar un rato!' WHERE `ID`=1972;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오랜만일세, 베소르, 내 친구여.', `MaleText_loc4`='比索，我的朋友，好久不见啊。', `MaleText_loc5`='比索，我的朋友，好久不見啊。', `MaleText_loc7`='Cuanto tiempo, mi querido amigo Bethor.' WHERE `ID`=1973;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언제 시간 날 때 더 얘기 나누세. 할 얘기가 너무 많다네.', `MaleText_loc4`='如果时间允许的话，我们得好好谈一下。因为我们有很多事情要讨论。', `MaleText_loc5`='如果時間允許的話，我們得好好談一下。因為我們有很多事情要討論。', `MaleText_loc7`='Si el tiempo lo permite tenemos que hablar con calma. Hay mucho que discutir.' WHERE `ID`=1974;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 고맙네, $n. 자네 도움이 없었다면 결코 포세이큰의 길로 접어들지 못했을 걸세.', `MaleText_loc4`='谢谢你，$n。没有你的帮助，我永远无法成为被遗忘者的一员。', `MaleText_loc5`='謝謝你，$n。沒有你的幫助，我永遠無法成為被遺忘者的一員。', `MaleText_loc7`='Y gracias, $n. Sin tu ayuda, jamás habría encontrado el camino hasta los Renegados.' WHERE `ID`=1975;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 가게, 친구.', `MaleText_loc4`='保重，我的朋友。', `MaleText_loc5`='保重，我的朋友。', `MaleText_loc7`='Adiós, $gamigo mío:amiga mía;.' WHERE `ID`=1976;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리스타, 포로를 소환하도록!', `MaleText_loc4`='利斯塔，把战俘带过来。', `MaleText_loc5`='利斯塔，把戰俘帶過來。', `MaleText_loc7`='Lysta, invoca a los cautivos.' WHERE `ID`=1977;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에드워드. 타일러. 첫 번째 시험을 준비하도록.', `MaleText_loc4`='爱德华，泰勒尔出来。准备接受你们的第一轮挑战。', `MaleText_loc5`='愛德華，泰勒爾出來。準備接受你們的第一輪挑戰。', `MaleText_loc7`='Edward. Tyler. Prepárense para su primer desafío.' WHERE `ID`=1978;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번 건 별로 어렵지 않았던 것 같군. 두 번째 시험은 어떻게 해내는지 한번 볼까? 리스타, 리치 왕의 앞잡이들을 데려오게.', `MaleText_loc4`='看来你们应付第一轮还是非常轻松的嘛。让我们看看你是怎样对付第二轮测试的。利斯塔，把巫妖王的爪牙带上来。', `MaleText_loc5`='看來你們應付第一輪還是非常輕鬆的嘛。讓我們看看你是怎樣對付第二輪測試的。利斯塔，把巫妖王的爪牙帶上來。', `MaleText_loc7`='No parece ser un desafío. Veamos cómo lo haces en la segunda prueba. Lysta, trae a los esbirros del Rey Exánime.' WHERE `ID`=1980;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 너희 실력을 증명해 봐라!', `MaleText_loc4`='现在是证明你们的价值的时候了！', `MaleText_loc5`='現在是證明你們的價值的時候了!', `MaleText_loc7`='¡Ahora demuestren su valía!' WHERE `ID`=1981;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실력이 약간 늘었군. 리스타, 우리 젊은 신병들을 위해서 깜짝 놀랄 만한 상대를 불러오지 그래.', `MaleText_loc4`='你们证明了自己的能力。看来利斯塔为我们带来了一些惊喜。', `MaleText_loc5`='你們證明了自己的能力。看來利斯塔為我們帶來了一些驚喜。', `MaleText_loc7`='Después de todo, has demostrado tu valía. Lysta, trae la sorpresa que tenemos preparada para nuestros jóvenes reclutas.' WHERE `ID`=1983;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='젊은 전사들이여, 마지막 시험을 치를 때가 왔다! 이제 가장 힘든 전투를 준비하도록.', `MaleText_loc4`='年轻的战士，面对你们最后一轮挑战吧！', `MaleText_loc5`='年輕的戰士，面對你們最後一輪挑戰吧!', `MaleText_loc7`='¡Guerreros, es hora de enfrentar su desafío final! Prepárense para su lucha final.' WHERE `ID`=1984;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에드워드, 타일러. 잘했다. 훈련 성과가 꽤 좋군. 얼마 후에 자네들의 기질을 다시 한번 시험해 볼 테니 준비하고 있도록.', `MaleText_loc4`='干得很好。现在站到旁边去，让其他的兄弟来试试。', `MaleText_loc5`='愛德華與泰勒爾，你們做得很好。你們在訓練的過程中穩定的成長。我們下次再來試試你們的近戰技巧。', `MaleText_loc7`='Bien hecho, Edward y Tyler. Sus avances en la instrucción son bastante buenos. Pronto volveremos a probar su entereza.' WHERE `ID`=1985;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 감히 공허의 힘을 소환하는 것인가?', `MaleText_loc4`='谁胆敢召唤了虚空的力量？', `MaleText_loc5`='誰膽敢召喚了虛無的力量?', `MaleText_loc7`='¿Quién se atreve a invocar el poder del vacío?' WHERE `ID`=1986;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이로 인해 넌 영원히 고통 속에 살게 될 것이다. 괘씸한 흑마법사 녀석!', `MaleText_loc4`='你将会因此永远生活在痛苦之中，可怜的术士。', `MaleText_loc5`='你將會因此永遠生活在痛苦之中，可憐的術士。', `MaleText_loc7`='Vivirás eternamente atormentado por esto que has hecho, brujo patético.' WHERE `ID`=1987;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 사람이 달린 포지라이트입니다. 그는 역병이 발생했을 때 사랑하는 이와 함께 로데론에서 도망쳐 왔지요.', `MaleText_loc4`='这是达林·弗治维特。当疾病开始流行的时候，他带着自己的爱人从洛丹伦逃了出来。', `MaleText_loc5`='這是達林·弗治維特。當瘟疫開始流行的時候，他帶著自己的愛人從羅德隆逃了出來。', `MaleText_loc7`='Este es Dalin Forjador. Huyó de Lordaeron cuando sobrevino la Peste, llevándose su amor con él.' WHERE `ID`=1988;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 이 사람은 코마 빌라드. 결혼한 지 2주 만에 그의 아내가 메네실 항구에서 행방불명되어 버렸지요.', `MaleText_loc4`='这位是科马·韦拉德。结婚不到两个星期，他的妻子就为了米奈希尔港的安全而献出了生命。', `MaleText_loc5`='這位是科馬·韋拉德。結婚不到兩個星期，他的妻子就為了米奈希爾港的安全而獻出了生命。', `MaleText_loc7`='Y este es Comar Villardo. Tras dos semanas de haberse casado, su mujer desapareció de la fortaleza del puerto de Menethil.' WHERE `ID`=1989;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바보 같은 녀석들 같으니.', `MaleText_loc4`='蠢货。', `MaleText_loc5`='蠢貨。', `MaleText_loc7`='Idiotas.' WHERE `ID`=1990;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='재미있군... 이거 기대 이상인걸. 좋아...', `FemaleText_loc4`='真有趣……现在比我所期望的还要好……', `FemaleText_loc5`='真有趣...現在比我所期望的還要好...', `FemaleText_loc7`='Interesante... Vaya, esto supera mis expectativas. Delicioso...' WHERE `ID`=1991;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그가 그레이메인 성벽의 피난처로 왔을 때 자신의 사명은 피난온 사람들을 구하는 것이라 생각하고는 사랑하는 여인을 언덕마루로 보냈습니다.', `MaleText_loc4`='当他在格雷迈恩之墙碰到那些难民的时候，他想要帮助他们，于是就把他的女人送到了希尔斯布莱德。', `MaleText_loc5`='當他在葛雷邁恩之牆碰到那些難民的時候，他想要幫助他們，於是就把他的女人送到了希爾斯布萊德。', `MaleText_loc7`='Cuando se encontró con los refugiados en la Muralla de Cringris, sintió que era su deber socorrerles, enviando su mujer a Trabalomas.' WHERE `ID`=1992;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아내는 미인도 아니었고 그의 아내가 되고 싶어하는 여자들도 많았는데도 5년이 지나고, 10년이 되도록 그는 여전히 아내를 찾아다니고 있습니다.', `MaleText_loc4`='十年过去了，虽然她不是个美丽的女人，而且有很多女人可以取代她的位置，但是他还是在苦苦地找寻她。', `MaleText_loc5`='十年過去了，雖然她不是個美麗的女人，而且有很多女人可以取代她的位置，但是他還是在苦苦地找尋她。', `MaleText_loc7`='Han pasado más de cinco años y él no ha dejado de buscarla, aunque ella no era precisamente guapa y muchas mujeres habrían estado encantadas de ocupar su lugar.' WHERE `ID`=1993;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 새 장난감 어떤가?', `MaleText_loc4`='你觉得我的新玩具怎么样？', `MaleText_loc5`='你覺得我的新玩具怎麼樣?', `MaleText_loc7`='Entonces, ¿qué te parece mi nuevo juguete?' WHERE `ID`=1994;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='테레사, 이걸 랭커스터 신부께 전해 줘.', `MaleText_loc4`='瑟里莎，把这个交给兰克斯特神父。', `MaleText_loc5`='泰瑞莎，把這個交給蘭克斯特神父。', `MaleText_loc7`='Theresa, lleva esto al padre Lankester.' WHERE `ID`=1995;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='', `MaleText_loc4`='', `MaleText_loc5`='', `MaleText_loc7`='' WHERE `ID`=1996;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제 주인 애버너시 님께서 이걸 전하라 하셨습니다.', `FemaleText_loc4`='我的主人阿博纳斯大人让我把这个交给你。', `FemaleText_loc5`='我的主人阿博納斯大人讓我把這個交給你。', `FemaleText_loc7`='Mi señor Abernathy te envía esto.' WHERE `ID`=1997;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='예, 알겠습니다.', `FemaleText_loc4`='遵命，大人。', `FemaleText_loc5`='遵命，大人。', `FemaleText_loc7`='Sí, mi señor.' WHERE `ID`=1998;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='주인님. 랭커스터 신부님께서 보내신 겁니다.', `FemaleText_loc4`='大人，这是兰克斯特神父给您的。', `FemaleText_loc5`='大人，這是蘭克斯特神父給您的。', `FemaleText_loc7`='Mi señor. Del padre Lankester.' WHERE `ID`=1999;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 애완동물 어떤가?', `MaleText_loc4`='你喜欢我的宠物吗？', `MaleText_loc5`='你喜歡我的寵物嗎?', `MaleText_loc7`='¿Te gusta mi mascota?' WHERE `ID`=2000;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 놀라운 창조물이지 않나?', `MaleText_loc4`='她难道不是最让人惊奇的小东西吗？', `MaleText_loc5`='她難道不是最讓人驚奇的小東西嗎?', `MaleText_loc7`='¿No es acaso la criaturilla más sorprendente?' WHERE `ID`=2001;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 새로운 지배 기술이 성공할 거라고 하지 않았던가?', `MaleText_loc4`='我不是告诉你新的控制技术会成功的吗？', `MaleText_loc5`='我不是告訴你新的控制技術會成功的嗎?', `MaleText_loc7`='¿No te dije que mis nuevas técnicas de dominación funcionarían?' WHERE `ID`=2002;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 말한 대로 멋지지 않나?', `MaleText_loc4`='和我告诉你的一样棒，是吗？', `MaleText_loc5`='和我告訴你的一樣棒，是嗎?', `MaleText_loc7`='Es tan buena como te dije que lo sería, ¿verdad?' WHERE `ID`=2003;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일단 그녀의 영혼을 파괴하고 나니 간단하더군.', `MaleText_loc4`='摧毁她的精神对我来说很容易。', `MaleText_loc5`='摧毀她的精神對我來說很容易。', `MaleText_loc7`='Fue sencillo, una vez que rompí su espíritu.' WHERE `ID`=2004;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 모든 비밀을 폭로하길 바라는 건 아니겠지?', `MaleText_loc4`='你不是想要让我把所有的秘密都告诉你吧？', `MaleText_loc5`='你不是想要讓我把所有的秘密都告訴你吧?', `MaleText_loc7`='No esperarás que te revele todos mis secretos, ¿verdad?' WHERE `ID`=2005;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='작은 의식을 통한 고문의 효과도 아주 오래갈 수 있지.', `MaleText_loc4`='一个小小的仪式就够你受的了。', `MaleText_loc5`='一個小小的折磨儀式就夠你受的了。', `MaleText_loc7`='Un pequeño ritual de tortura puede dar mucho de sí.' WHERE `ID`=2006;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='약간의 고문, 마법, 그리고 절개 수술의 조합에 의한 대단한 효과지. 물론 그녀는 의식이 없었다네.', `MaleText_loc4`='一点点小魔法，她当然非常关心这些……', `MaleText_loc5`='一點折磨，一絲魔法，她當然非常關心這些...', `MaleText_loc7`='Una pequeña tortura, un toque de magia y una gran dosis de cirugía invasiva. Estaba consciente, por supuesto.' WHERE `ID`=2007;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누구나 약점이 있게 마련이지만 찾아낼 수 있느냐의 문제라네.', `MaleText_loc4`='每个人都有弱点，关键是如何要找到它。', `MaleText_loc5`='每個人都有弱點，關鍵是如何要找到它。', `MaleText_loc7`='Todos tenemos un punto débil, solo es cuestión de encontrarlo.' WHERE `ID`=2008;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 제거하거나 자극을 하면 고분고분해지게 되는 뇌의 특정 부분을 발견해 냈다네.', `MaleText_loc4`='经过努力，我发现大脑中有这样一个特定的部位，如果你将其切除或者施加特定的刺激，就可以使得该生物变得更加温顺。', `MaleText_loc5`='經過努力，我發現大腦中有這樣一個特定的部位，如果你將其切除或者施加特定的刺激，就可以使得該生物變得更加溫順。', `MaleText_loc7`='Descubrí que cuando se extirpan o estimulan ciertas partes del cerebro, el sujeto se vuelve mucho más dócil.' WHERE `ID`=2009;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='', `MaleText_loc4`='', `MaleText_loc5`='', `MaleText_loc7`='' WHERE `ID`=2010;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙구나, 착한 것.', `MaleText_loc4`='谢谢你，我的宝贝。', `MaleText_loc5`='謝謝你，我的寶貝。', `MaleText_loc7`='Gracias, mascota mía.' WHERE `ID`=2011;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말 놀라워요, 제라드. 어떻게 한 거죠?', `FemaleText_loc4`='真是让人惊讶，杰勒德。你是怎么办到的？', `FemaleText_loc5`='真是讓人驚訝，傑勒德。你是怎麼辦到的?', `FemaleText_loc7`='Realmente sorprendente, Gerard. ¿Cómo lo conseguiste?' WHERE `ID`=2012;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='놀랍군요! 어떻게 영원히 지배 상태로 만들 수 있었죠?', `FemaleText_loc4`='真让人感到惊讶！你是怎么实现恒定控制的呢？', `FemaleText_loc5`='真讓人感到驚訝!你是怎麼實現恒定控制的呢?', `FemaleText_loc7`='¡Sorprendente! ¿Cómo conseguiste dominarla permanentemente?' WHERE `ID`=2013;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신의 실험이 썩 마음에 들지는 않지만 그 결과가 대단하단 건 인정할 수밖에 없군요. 그녀에게 정확히 어떻게 한 거죠?', `FemaleText_loc4`='杰勒德，我不赞成你的试验，但是我承认结果是令人印象深刻的。你到底对她作了什么？', `FemaleText_loc5`='傑勒德，我不贊成你的試驗，但是我承認結果是令人印象深刻的。你到底對她作了什麼?', `FemaleText_loc7`='No apruebo tus experimentos, Gerard, pero debo admitir que los resultados son impresionantes. ¿Qué le hiciste exactamente?' WHERE `ID`=2014;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말 놀라워요. 그녀를 지배하면서도 여전히 스스로 자기 의식과 기능을 유지하게 하다니... 어떻게 한 거죠?', `FemaleText_loc4`='真令人惊讶。你在控制她，但她还能保持自己的意识。你是怎么做到的？', `FemaleText_loc5`='真令人驚訝。你在控制她，但她還能保持自己的意識。你是怎麼做到的?', `FemaleText_loc7`='¡Impresionante! Lograste dominarla, sin embargo es consciente de sí misma y conserva sus funciones. ¿Cómo lo conseguiste?' WHERE `ID`=2015;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그녀는 지식과 언어 능력을 유지하고 있고, 당신을 위해 혼자 힘으로 임무를 수행할 수도 있어요. 정확히 어떻게 한 거예요?', `FemaleText_loc4`='她保留了她的知识和语言能力，同时还能为你出色地完成任务。你到底做了些什么？', `FemaleText_loc5`='她保留了她的知識和語言能力，同時還能為你出色地完成任務。你到底做了些什麼?', `FemaleText_loc7`='Ha conservado el conocimiento y el habla, e incluso la autonomía para realizar tareas para ti. ¿Exactamente qué hiciste?' WHERE `ID`=2016;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런 건 정말 처음 봐요. 지배하는 동안 대상은 집중하지 못하거나 의식을 잃게 마련인데... 그녀를 어떻게 한 거예요?', `FemaleText_loc4`='我从来没见过这样的情况。一个生物居然能够在没有失去自己意识的情况下被控制。你对她作了什么？', `FemaleText_loc5`='我從來沒見過這樣的情況。一個生物居然能夠在沒有失去自己意識的情況下被控制。你對她作了什麼?', `FemaleText_loc7`='Nunca he visto nada parecido. El sujeto dominado no pierde capacidad de concentración ni conciencia. ¿Qué le hiciste?' WHERE `ID`=2017;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='훌륭해요, 제라드. 한 단계 더 발전했군요.', `FemaleText_loc4`='妙极了，杰勒德，你们超越了自己，再来一次。', `FemaleText_loc5`='妙極了，傑勒德，你們超越了自己，再來一次。', `FemaleText_loc7`='Muy bien, Gerard, te has superado a ti mismo nuevamente.' WHERE `ID`=2018;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말 인상적이에요, 제라드. 말뿐인 줄만 알았는데, 내가 잘못 생각했었군요.', `FemaleText_loc4`='杰勒德，你给我留下了深刻的印象。我原本以为你只会夸夸其谈，但事实证明我错了。', `FemaleText_loc5`='傑勒德，你給我留下了深刻的印象。我原本以為你只會誇誇其談，但事實證明我錯了。', `FemaleText_loc7`='Estoy realmente impresionado, Gerard. Pensé que eras un charlatán, pero veo que estaba totalmente equivocado.' WHERE `ID`=2019;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='멋져요. 아주 훌륭하군요. 그녀가 묘기도 부릴 수 있나요?', `FemaleText_loc4`='太不可思议了。这里面到底有什么诀窍？', `FemaleText_loc5`='太不可思議了。這裡面到底有什麼訣竅?', `FemaleText_loc7`='Impresionante, realmente impresionante. ¿Acaso sabe hacer trucos?' WHERE `ID`=2020;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아주 멋져요, 제라드. 다음번엔 새끼를 낳을 수도 있겠군요.', `FemaleText_loc4`='很好，杰勒德。接下来，你要负责培养出更多这样的生物。', `FemaleText_loc5`='很好，傑勒德。接下來，你要負責培養出更多這樣的生物。', `FemaleText_loc7`='Muy bien, Gerard. Lo próximo será que críes más ejemplares como este.' WHERE `ID`=2022;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말 놀라운 발견을 했군요. 실패한 실험들도 모두 살펴보고 싶어요.', `FemaleText_loc4`='这绝对是一个令人惊讶的发现。我很想看看你失败了的那些试验品。', `FemaleText_loc5`='這絕對是一個令人驚訝的發現。我很想看看你失敗了的那些試驗品。', `FemaleText_loc7`='Has hecho un gran descubrimiento. Me encantaría tener la oportunidad de contemplar todos los experimentos fallidos.' WHERE `ID`=2023;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='일부 문제를 해결하기 위해 연금술을 사용한 것에는 동의할 수 없지만 결과는 인정해요. 정말 잘했어요.', `FemaleText_loc4`='我不同意你用炼金术去解决这些问题，但我对结果感到满意。你干得很好。', `FemaleText_loc5`='我不同意你用鍊金術去解決這些問題，但我對結果感到滿意。你幹得很好。', `FemaleText_loc7`='No estoy de acuerdo con que recurras a la alquimia para resolver algunos problemas, pero sí estoy de acuerdo con los resultados. Lo has hecho muy bien.' WHERE `ID`=2024;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신 애완동물은 정말 훌륭해요, 제라드. 하지만 목에 방울을 달아 놓아야 할 것 같은데...', `FemaleText_loc4`='你的宠物很不错，杰勒德，但我想她需要一个带着铃铛的项圈。', `FemaleText_loc5`='你的寵物很不錯，傑勒德，但我想她需要一個帶著鈴鐺的項圈。', `FemaleText_loc7`='Tu mascota es maravillosa, Gerard, pero creo que necesita un collar con una campanilla.' WHERE `ID`=2026;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='집안을 더럽히지 않도록 그녀를 훈련시켜야 했나요, 제라드?', `FemaleText_loc4`='杰勒德，你有训练她的场地吗？', `FemaleText_loc5`='傑勒德，你有訓練她的場地嗎?', `FemaleText_loc7`='¿Tuviste que educarla, Gerard?' WHERE `ID`=2027;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='윽! 저놈이 뭘 하는 거야. 해충을 내게 보내? 목숨을 부지하고 싶다면 어서 이거 가지고 내 눈앞에서 사라져!', `MaleText_loc4`='啊！那个无赖派他的人来找我吗？在我动手杀了你之前滚出我的视线，还有，拿上这个。', `MaleText_loc5`='啊!那個無賴派他的人來找我嗎?在我動手殺了你之前滾出我的視線，還有，拿上這個。', `MaleText_loc7`='¡Aj! ¿Por qué me manda ese canalla a su chusma? Sal de mi vista antes de que te quite la vida. Y llévate también esto.' WHERE `ID`=2028;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 저기 있군.', `FemaleText_loc4`='啊，在这里。', `FemaleText_loc5`='啊，在這裡。', `FemaleText_loc7`='Ahh, ahí está.' WHERE `ID`=2029;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='"마법의 순환이 세계에 미치는 영향", 마지노르 뒤마 지음. 이게 바로 내가 찾던 책이야.', `FemaleText_loc4`='《不可思议的魔法流动及它是如何影响这个世界的》，玛吉诺·仲马著。我在一直寻找这本书。', `FemaleText_loc5`='《不可思議的魔法流動及它是如何影響這個世界的》，瑪姬諾·仲馬著。我在一直尋找這本書。', `FemaleText_loc7`='"Efluvios mágicos y cómo afectan al mundo", por Maginor Dumas. Este es el que estaba buscando.' WHERE `ID`=2030;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 책들을 좀 더 체계적으로 정리할 필요가 있겠군. 아, 저기 내가 원하던 책이 있네.', `FemaleText_loc4`='看来我真的需要一个更好的图书分类系统了。啊，就是这本！', `FemaleText_loc5`='看來我真的需要一個更好的圖書分類系統了。啊，就是這本!', `FemaleText_loc7`='En realidad necesito un sistema más eficaz para archivar estos libros. Ahh, ese es el que quería.' WHERE `ID`=2031;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='"카드가의 비법서, 제8권." 이게 내가 찾던 책 같은데...', `FemaleText_loc4`='《卡德加的魔法日记，第八卷》，我要的是这一本。', `FemaleText_loc5`='《卡德加的魔法日記，第八卷》，我要的是這一本。', `FemaleText_loc7`='"Revista Mística de Khadgar, volumen 8." Creo que esto es lo que buscaba.' WHERE `ID`=2032;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, "달라란 대마법사의 신비한 창조 마법". 아주 좋아.', `FemaleText_loc4`='哈，《达拉然大法师的神秘咒术》，太棒了。', `FemaleText_loc5`='哈，《達拉然大法師的神秘咒術》，太棒了。', `FemaleText_loc7`='Ahh, "Conjuros místicos de los archimagos de Dalaran." Perfecto.' WHERE `ID`=2033;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='"주문과 마력의 길"을 찾아야 하는데... 아, 여기 있군. 이게 왜 여기에 있지?', `FemaleText_loc4`='不知道我能不能找到《魔法和能量的守则》这本书。啊哈，在这里，它怎么会在这里？', `FemaleText_loc5`='不知道我能不能找到《魔法和能量的守則》這本書。啊哈，在這裡，它怎麼會在這裡?', `FemaleText_loc7`='Si pudiera encontrar Magia y los caminos del poder". ¡Ah, aquí está! ¿Qué estaría haciendo aquí?"' WHERE `ID`=2034;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='"마법 비술", 아니야. "마법 비행", 이것도 아니야. 아, 여기 있군. "마법 비전".', `FemaleText_loc4`='《魔法致病学》，不对不对。《魔法矩阵》，也不对。啊，就是这个，《魔法神秘学》。', `FemaleText_loc5`='《魔法致病學》，不對不對。《魔法矩陣》，也不對。啊，就是這個，《魔法神秘學》。', `FemaleText_loc7`='"Enfermedades mágicas", no. "Matrices mágicas", no. Ah, esto sí, "Misterios mágicos".' WHERE `ID`=2035;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저기 내가 찾던 비전서가 있군.', `FemaleText_loc4`='这就是我要寻找的魔法书。', `FemaleText_loc5`='這就是我要尋找的魔法書。', `FemaleText_loc7`='Este es el libro místico que estaba buscando.' WHERE `ID`=2036;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그래, 그래. 흠, 다른 학술서도 참고해야겠는걸. 저것도 찾아봐야겠어.', `FemaleText_loc4`='没错。嗯，这本书参考了另外一本书的内容。看来我还要去找那一本书。', `FemaleText_loc5`='沒錯。嗯，這本書參考了另外一本書的內容。看來我還要去找那一本書。', `FemaleText_loc7`='Sí, sí. Mmm, parece que remite a otro libro. Creo que también tendré que encontrarlo.' WHERE `ID`=2037;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='음, 저건 별로 도움이 되지 않는군. 다른 걸 한번 살펴봐야겠어.', `FemaleText_loc4`='这一本不是很有用。让我看一下另外一本。', `FemaleText_loc5`='這一本不是很有用。讓我看一下另外一本。', `FemaleText_loc7`='Este no ha resultado ser demasiado útil. Voy a revisar el otro.' WHERE `ID`=2038;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그래, 이게 바로 내가 알고 싶었던 거야. 이제 흐름의 변동에 대한 내용이 어디에 나와 있는지만 찾으면 되는데...', `FemaleText_loc4`='那就是我想要知道的东西。现在我要知道书中的哪个章节讨论的是魔法流量的变化问题。', `FemaleText_loc5`='那就是我想要知道的東西。現在我要知道書中的哪個章節討論的是魔法流量的變化問題。', `FemaleText_loc7`='Esto es lo que quería saber. Ahora solo tengo que buscar el apartado que trata acerca de la desviación del flujo.' WHERE `ID`=2039;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아주 흥미로군. 하지만 이게 맞는다면 내 이론이 잘못된 거로군. 내가 뭘 빠뜨렸는지 다른 부분들도 다시 읽어 봐야겠어.', `FemaleText_loc4`='非常有趣。但如果确实是这样的话，那我的理论就是错误的。我要重新去读另一部分，看看我究竟错过了什么。', `FemaleText_loc5`='非常有趣。但如果確實是這樣的話，那我的理論就是錯誤的。我要重新去讀另一部分，看看我究竟錯過了什麼。', `FemaleText_loc7`='Muy interesante.' WHERE `ID`=2040;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그래, 역시 힘에 대한 내 생각이 맞았어. 이 주제에 대해 다른 학술서에는 뭐라고 쓰여 있는지 한번 볼까?', `FemaleText_loc4`='看来我对于能量的理解是正确的。让我们去看看另一本书讲了些什么。', `FemaleText_loc5`='看來我對於能量的理解是正確的。讓我們去看看另一本書講了些什麼。', `FemaleText_loc7`='Entonces tenía razón acerca de las energías. Veamos qué dice el otro libro sobre el tema.' WHERE `ID`=2041;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이게 맞는다면 훨씬 더 많은 연구를 해야겠는걸.', `FemaleText_loc4`='如果这个理论是正确的，那我就得做很多研究了。', `FemaleText_loc5`='如果這個理論是正確的，那我就得做很多研究了。', `FemaleText_loc7`='Si esto es así, entonces tengo que investigar mucho más.' WHERE `ID`=2042;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이게 맞을 리가 없어. 내가 다른 책을 어디에 뒀더라?', `FemaleText_loc4`='但这个肯定不对。我把那本大书放哪里去了？', `FemaleText_loc5`='但這個肯定不對。我把那本大書放哪裡去了?', `FemaleText_loc7`='Pero esto no puede ser. ¿Dónde he puesto el otro libro?' WHERE `ID`=2043;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='처음부터 다시 해봐야겠어.', `FemaleText_loc4`='从头再来一遍。', `FemaleText_loc5`='回到書藉前面。', `FemaleText_loc7`='Volvamos a la mesa de dibujo.' WHERE `ID`=2044;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 나무 인간이 손 흔드는 걸 한번 보자고!', `MaleText_loc4`='哈！让我们看看这个木头人！', `MaleText_loc5`='哈!讓我們看看這個木頭人!', `MaleText_loc7`='¡Ja! ¡Mira cómo saluda el humano de palo!' WHERE `ID`=2045;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하! 정말 재미있군! 재미있는 나무 인간이야!', `MaleText_loc4`='哈哈！真有趣！真有趣！', `MaleText_loc5`='哈哈!真有趣!真有趣!真是個有趣的木頭人!', `MaleText_loc7`='¡Ja, ja, ja! ¡Eso tuvo gracia! ¡Un humano de palo!' WHERE `ID`=2046;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 웃습니다.', `MaleText_loc4`='%s笑了。', `MaleText_loc5`='%s大笑。', `MaleText_loc7`='%s ríe.' WHERE `ID`=2047;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐! $n. 전 맥주통을 지키고 있어요. 살펴보는 건 좋지만 만지지는 말라고요!', `MaleText_loc4`='站住，$n！我在看守这些桶，所以……不要碰它们！', `MaleText_loc5`='站住，$n!我在看守這些桶，所以...不要碰它們!', `MaleText_loc7`='¡Espera, $n! ¡Estoy vigilando estos barriles, así que puedes mirar, pero no tocar!' WHERE `ID`=2048;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기 온 걸 보니 악의 무리를 소환하여 부리는 법을 공부할 준비가 됐나 보군. 자네가 부를 수 있을 만한 가장 저급한 생물부터 시작하지. 자, 시작해 볼까?', `FemaleText_loc4`='如果你在这里，那就表明你已经准备好去研究召唤恶魔的方法了。我们将从最低级的生物召唤开始，然后再慢慢进阶。让我们开始吧。', `FemaleText_loc5`='如果你在這裡，那就表明你已經準備好去研究召喚惡魔的方法了。我們將從最低級的生物召喚開始，然後再慢慢進階。讓我們開始吧。', `FemaleText_loc7`='Si estás aquí, significa que ya puedes empezar a estudiar la invocación de cohortes demoníacas para hacer lo que te plazca. Empezaremos por las criaturas más humildes que podrás invocar y continuaremos a partir de ahí. Comencemos.' WHERE `ID`=2049;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가장 소환하기 쉬운 생물은 임프라네. 자네도 이미 임프 정도는 소환할 줄 알겠지만, 빠진 것이 없도록 이놈부터 설명하겠네.', `FemaleText_loc4`='最容易召唤的是小鬼。你的能力也许已经远远超过召唤小鬼的水平，但是我们为了保证召唤教学的完整性，所以还是从召唤它开始吧。', `FemaleText_loc5`='最容易召喚的是小鬼。你的能力也許已經遠遠超過召喚小鬼的水準，但是我們為了保證召喚教學的完整性，所以還是從召喚它開始吧。', `FemaleText_loc7`='La criatura más fácil de invocar para ti es el diablillo. A estas alturas, ya deberías ser capaz de crear al esbirro, pero por razones de complejidad, empezaré por él.' WHERE `ID`=2050;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 사악하고 작은 짐승이 바로 임프지. 작고 약해서 고기 방패처럼 거의 쓸모가 없어. 물론 공격력도 보잘것없고. 이 짐승은 파티를 지원하는 정도의 용도로 사용하는 게 가장 좋지.', `FemaleText_loc4`='这些邪恶的小家伙就是小鬼。它很小而且很瘦弱，显然是不能做为肉盾使用的，而它的威力也不大。这种召唤生物最好是在多人组队的时候作为支援力量使用。', `FemaleText_loc5`='這些邪惡的小傢伙就是小鬼。它很小而且很瘦弱，顯然是不能做為肉盾使用的，而它的威力也不大。這種召喚生物最好是在多人組隊的時候作為支援力量使用。', `FemaleText_loc7`='Esta pequeña bestia hedionda es el diablillo. Es pequeño y débil, lo que lo convierte en un ser prácticamente inútil como escudo de carne y hueso y su capacidad de destrucción es realmente mediocre. Esta criatura resulta más útil como apoyo de un grupo más grande.' WHERE `ID`=2051;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='임프는 공부했으니 이제 다음 소환수를 소환해 보지. 다음은 공허방랑자라네.', `FemaleText_loc4`='现在你已经了解了小鬼的特性，那么让我们继续研究下一种你可以召唤的生物：虚空行者。', `FemaleText_loc5`='現在你已經瞭解了小鬼的特性，那麼讓我們繼續研究下一種你可以召喚的生物:虛無行者。', `FemaleText_loc7`='Ahora que has podido estudiar el diablillo, pasemos al siguiente esbirro que podrás invocar, el abisario.' WHERE `ID`=2052;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 악마는 공허방랑자라고 알려져 있지. 힘과 맷집이 대단해서 방어용으로 이상적이야. 공허방랑자가 먼저 적을 공격하게 한 뒤, 녀석을 방패 삼아 자네의 주문이나 능력을 사용하게.', `FemaleText_loc4`='这种恶魔被称为虚空行者。它的力量和耐力都非常惊人，可以出色地胜任防御任务。首先控制它来攻击你的敌人，这样就能保证你在有肉盾保护的情况下安全地使用法术和技能。', `FemaleText_loc5`='這種惡魔被稱為虛無行者。它的力量和耐力都非常驚人，可以出色地勝任防禦任務。首先控制它來攻擊你的敵人，這樣就能保證你在有肉盾保護的情況下安全地使用法術和技能。', `FemaleText_loc7`='Este ente demoníaco se conoce como abisario. Si fuerza y resistencia son importantes, resultando ideal para la defensa. Envíalo al frente para atacar a tu enemigo y luego úsalo como escudo mientras utilizas tus encantamientos y habilidades para extinguir la vida de tu oponente.' WHERE `ID`=2053;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자, 한 번도 본 적이 없다면 잘 봐 두라고. 전장 안팎에서 모두 아주 유용한 녀석이니까 말이야. 다음은 남성들이라면 모두 기대하고 있을 서큐버스를 소환해 보지.', `FemaleText_loc4`='如果你还没有看见过虚空行者，那你一定要去看看。这种生物看上去就极具气势，而且在战场上也能发挥很强的作用。接下来，让我们看看所有男性学员都在热切期盼的召唤生物：魅魔。', `FemaleText_loc5`='如果你還沒有看見過虛空行者，那你一定要去看看。這種生物看起來就極具氣勢，而且在戰場上也能發揮很強的作用。接下來，讓我們看看所有男性學員都在熱切期盼的召喚生物:魅魔。', `FemaleText_loc7`='Merece la pena contemplarlo, por si no lo has visto antes. Se trata de una criatura realmente impresionante dentro como fuera del campo de batalla. Ahora, echemos un vistazo a lo que estoy seguro que todos ustedes, alumnos varones, han estado esperando. El súcubo.' WHERE `ID`=2054;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋아. 서큐버스는 남성 적들을 매혹시켜 교란을 유도할 수 있을 뿐만 아니라 상당한 타격도 입힐 수 있지. 하지만 방어력이 약해서 방패로는 거의 쓸모가 없어.', `FemaleText_loc4`='好了。除了和前面那两种召唤生物的外形有着明显的差异之外，魅魔的攻击能力也非常可观。然而，她的防御力很差，所有很难作为肉盾来使用。', `FemaleText_loc5`='好了。除了和前面那兩種召喚生物的外形有著明顯的差異之外，魅魔的攻擊能力也非常可觀。然而，她的防禦力很差，所有很難作為肉盾來使用。', `FemaleText_loc7`='Muy bien. Además de la distracción evidente que un esbirro como este supondrá para sus enemigos masculinos, ella también tiene una capacidad de destrucción impresionante. No obstante, su frágil resistencia la hace casi inservible como escudo.' WHERE `ID`=2055;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='열심히 공부하다 보면 언젠가 직접 소환할 수 있을 걸세. 하지만 지금은 우선 지옥사냥개로 넘어가 보지.', `FemaleText_loc4`='努力学习，总有一天你们也可以召唤魅魔的，但现在我们要继续课程了，下一讲是地狱猎犬。', `FemaleText_loc5`='努力學習，總有一天你們也可以召喚魅魔的，但現在我們要繼續課程了，下一講是惡魔獵犬。', `FemaleText_loc7`='Estudia mucho y quizás algún día podrás invocar a tu propio esbirro, pero ahora pasaremos a estudiar al manáfago.' WHERE `ID`=2056;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='앞에 보이는 것이 지옥사냥개일세. 이 야수는 주문 잠금을 비롯한 여러 가지 능력을 타고났기 때문에, 마법을 사용하는 적을 상대하는 데 탁월하지.', `FemaleText_loc4`='现在你们看到的就是地狱猎犬。这种生物拥有法力燃烧等多种技能，这些技能在对付施法型的敌人时是十分有用的。', `FemaleText_loc5`='現在你們看到的就是惡魔獵犬。這種生物擁有法力燃燒等多種技能，這些技能在對付施法型的敵人時是十分有用的。', `FemaleText_loc7`='Lo que tenéis delante es un manáfago. Entre los talentos naturales de esta criatura está la capacidad de neutralizar encantamientos y otras habilidades, convirtiéndola en un ser inigualable a la hora de enfrentarse a un oponente con poderes mágicos.' WHERE `ID`=2057;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마법을 사용하는 모든 적들을 상대할 때는 이 무시무시한 짐승이 가장 유용할 거야. 이제 약간 다른 녀석을 살펴볼까? 자네의 여행을 도와주고 앞으로 여정을 훨씬 편하게 해줄 친구지. 자, 지옥마를 살펴보자고.', `FemaleText_loc4`='当遇见施法者的时候，这种恶魔是你最好的朋友。现在，让我们进行一下讲的课程。这种召唤生物主要被用来帮助你更快地旅行。它就是地狱战马，有时也被称为梦魇。', `FemaleText_loc5`='當遇見施法者的時候，這種惡魔是你最好的朋友。現在，讓我們進行一下講的課程。這種召喚生物主要被用來幫助你更快地旅行。它就是惡魔戰馬。', `FemaleText_loc7`='A la hora de enfrentarse a cualquier taumaturgo, esta bestia salvaje será tu mejor amigo. Veamos ahora algo ligeramente distinto. La siguiente criatura te ayudará en tus viajes y hará más agradables tus viajes futuros. Vamos a echar un vistazo a un corcel vil.' WHERE `ID`=2058;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런 녀석을 볼 기회가 있었나 모르겠군그래. 이 악마의 말을 제어할 수만 있다면 훨씬 빠르게 여행할 수 있지. 하지만 제어하기가 어렵기 때문에 시도하기 전에 확실히 준비가 되어 있어야 하네.', `FemaleText_loc4`='我怀疑你已经看过很多次这个生物了。这些恶魔马能让你的旅行速度加快，只要你召唤出它们来，就可以把它们当作自己的坐骑。但是地狱战马是非常难以驯服的，所以在尝试之前，你最好确定自己准备充足。', `FemaleText_loc5`='我懷疑你已經看過很多次這個生物了。這些惡魔馬能讓你的旅行速度加快，只要你召喚出它們來，就可以把它們當作自己的坐騎。但是惡魔戰馬是非常難以馴服的，所以在嘗試之前，你最好確定自己準備充足。', `FemaleText_loc7`='Dudo que hayas tenido ocasión de ver una criatura semejante. Estos equinos demoníacos te permitirán ir más rápido, actuando como tu medio de transporte siempre y cuando puedas controlarlos. No obstante, son difíciles de controlar, así que asegúrate de que estés preparado antes de intentarlo.' WHERE `ID`=2059;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자, 이것으로 소환에 대한 수업은 모두 마치도록 하겠네. 곧 다음 수업이 시작될 테니, 복습하고 싶다면 여기 계속 머물러 있어도 좋네.', `FemaleText_loc4`='所有的召唤生物都介绍完毕了。召唤课程已经结束。新的课程将会很快开始，如果你要想要得到进一步的提高，那就请不要走远，先在周围转转。', `FemaleText_loc5`='所有的召喚生物都介紹完畢了。召喚課程已經結束。新的課程將會很快開始，如果你要想要得到進一步的提高，那就請不要走遠，先在周圍轉轉。', `FemaleText_loc7`='Aquí lo tenéis. Nuestra lección sobre las invocaciones ha llegado a su fin. En breve iniciaremos otra clase, así que si queréis poneros al día, os podéis quedar por aquí.' WHERE `ID`=2060;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠, 이 키버에게 새로운 연구 주제가 필요할 것 같군. 그 바보 애버너시가 계속 이 키버의 주제를 가로챈다면 키버가 그에게 한마디 할 수밖에 없지.', `MaleText_loc4`='嗯，看来基佛需要一个新的项目。如果那个笨蛋阿博纳斯继续从基佛手里抢项目，基佛肯定会对他有意见的。', `MaleText_loc5`='嗯，看來基佛需要一個新的專案。如果那個笨蛋阿博納斯繼續從基佛手裡搶專案，基佛肯定會對他有意見的。', `MaleText_loc7`='Mmm, al parecer, Keever necesita un nuevo sujeto. Si el idiota de Abernathy sigue quitándole los sujetos a Keever, este tendrá que ponerlo en su sitio.' WHERE `ID`=2061;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 이게 있었지. 이제 이 약병이 효과가 있는지 시험해 봐야겠어.', `MaleText_loc4`='嗯，搞定了。现在让基佛试试看。', `MaleText_loc5`='嗯，搞定了。現在讓基佛試試看。', `MaleText_loc7`='Ah, bueno, vamos allá. Ahora Keever debe experimentar con este vial y ver si funciona.' WHERE `ID`=2062;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 키버가 원하던 게 아닌데... 뱀뿌리를 너무 많이 넣었나 보군. 두 번째 물약은 키버가 원하는 효과가 있을지 한번 봐야겠어.', `MaleText_loc4`='不是基佛想要的结果。基佛可能加了太多的地根草。我们来看一下第二份药水是不是基佛所需要的。', `MaleText_loc5`='這不是基佛所期望得到的結果，基佛使用了太多的地根草。讓我們看看第二瓶血清會不會符合基佛的需求。', `MaleText_loc7`='No es lo que Keever estaba esperando. Quizás Keever haya agregado demasiada raíz de tierra. Veamos si el segundo suero cumple su función.' WHERE `ID`=2063;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 작은 두꺼비를 찔러 봅니다.', `MaleText_loc4`='%s戳了戳那只小蛤蟆。', `MaleText_loc5`='%s戳了戳那隻小蟾蜍。', `MaleText_loc7`='%s pincha al pequeño sapo.' WHERE `ID`=2064;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 두꺼비에게 이상한 액체를 조금 먹입니다.', `MaleText_loc4`='%s给蛤蟆喂了一些奇怪的液体。', `MaleText_loc5`='%s給那隻蟾蜍餵了一些奇怪的液體。', `MaleText_loc7`='%s da de beber al sapo un poco del líquido extraño.' WHERE `ID`=2065;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 실망한 듯 작은 털북숭이 다람쥐를 찔러 봅니다.', `MaleText_loc4`='%s失望地戳了戳那只小松鼠。', `MaleText_loc5`='%s失望地戳了戳那隻小松鼠。', `MaleText_loc7`='%s pincha la pequeña y peluda ardilla claramente decepcionado.' WHERE `ID`=2066;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠, 뭔가 잘못됐어. 짐승이 너무 작아. 이 키버의 세 번째 시도는 어떨지 한번 볼까?', `MaleText_loc4`='好吧，失败了。这种生物太小了。让我们看看基佛的第三批药剂效果如何。', `MaleText_loc5`='好吧，失敗了。這種生物太小了。讓我們看看基佛的第三批藥劑效果如何。', `MaleText_loc7`='Bueno, esto no está bien. La criatura es demasiado pequeña. Veamos lo que hará el tercer lote de Keever.' WHERE `ID`=2067;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 다람쥐에게 끈적끈적한 액체를 조금 먹입니다.', `MaleText_loc4`='%s给松鼠喂了一些粘粘的液体。', `MaleText_loc5`='%s給那隻松鼠餵了一些黏稠的液體。', `MaleText_loc7`='%s da de beber a la ardilla parte del viscoso fluido.' WHERE `ID`=2068;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 겁먹은 토끼를 찔러 봅니다.', `MaleText_loc4`='%s戳了戳那只野兔。', `MaleText_loc5`='%s戳了戳那隻膽小的野兔。', `MaleText_loc7`='%s pincha al conejo asustadizo.' WHERE `ID`=2069;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 키버를 실망시키는군. 물약의 양을 늘려서 해보면 문제가 해결될지도 모르겠어.', `MaleText_loc4`='基佛对这个结果不太满意。也许如果基佛尝试一下大剂量的话，效果会好一些。', `MaleText_loc5`='基佛對這個結果不太滿意。也許如果基佛嘗試一下大劑量的話，效果會好一些。', `MaleText_loc7`='Keever no está contento con esto. Quizás si Keever probase una dosis más grande, el dilema se resolvería.' WHERE `ID`=2070;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 토끼를 잡고 목으로 액체를 쏟아 붓습니다. 그런 다음 우리 안에 다시 넣습니다.', `MaleText_loc4`='%s抓住野兔，把那瓶液体全数灌入野兔腹中，然后把它塞回笼子。', `MaleText_loc5`='%s抓住那隻野兔，把那瓶液體灌進了牠的喉嚨裏，然後把牠塞回籠子。', `MaleText_loc7`='%s coge el conejo, vierte el líquido en su garganta y luego lo vuelve a meter en su jaula.' WHERE `ID`=2071;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 뭐야? 이 키버는 양을 원한 적이 없는데? 강한 힘을 가진 무기를 원했건만 고작 이런 양이 되다니. 정말 실망이야.', `MaleText_loc4`='这是什么？基佛要的是一只绵羊？基佛想要一件强力的武器，但他现在得到的就是这只绵羊。基佛非常失望。', `MaleText_loc5`='這是什麼?基佛要的是一隻綿羊?基佛想要一件強力的武器，但他現在得到的就是這只綿羊。基佛非常失望。', `MaleText_loc7`='¿Qué es esto? ¿Ha pedido Keever una oveja? Keever quería un arma muy potente y lo único que consiguió fue esta oveja. Keever está muy decepcionado.' WHERE `ID`=2072;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 털이 난 양을 계속 찔러 봅니다.', `MaleText_loc4`='%s反复地戳那只绵羊。', `MaleText_loc5`='%s反覆地戳那隻綿羊。', `MaleText_loc7`='%s pincha varias veces a la mullida oveja.' WHERE `ID`=2073;
