UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 완벽한 상태로 보존된 걸 찾을 거라고는 기대도 하지 않았는데...', `MaleText_loc4`='我从来没想过居然能找到如此符合我要求的东西。', `MaleText_loc5`='我從來沒想過居然能找到如此符合我要求的東西。', `MaleText_loc7`='Nunca esperé encontrar algo en tan perfectas condiciones.' WHERE `ID`=2133;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='약간 흠이 나긴 했지만 이것만으로도 아주 유용한 정보를 얻을 수 있겠군.', `MaleText_loc4`='虽然有点破损，但我还是能从其中获得一些有用的信息。', `MaleText_loc5`='雖然有點破損，但我還是能從其中獲得一些有用的資訊。', `MaleText_loc7`='Está un poco dañado pero aún debería poder sacar algo de información.' WHERE `ID`=2134;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 정말 큰 도움을 줬소! 이 화석 뼈로 수많은 정보를 새로 얻어내 연구가 큰 진전을 이루게 될 거요.', `MaleText_loc4`='你们真是帮了我的大忙！这些骨头包含了很多新的信息，这对我将来的研究有很大的帮助！', `MaleText_loc5`='你們真是幫了我的大忙!這些骨頭包含了很多新的資訊，這對我將來的研究有很大的幫助!', `MaleText_loc7`='¡Has sido de gran ayuda! Estos huesos van a darnos mucha información nueva y me ayudarán a avanzar en mi investigación.' WHERE `ID`=2135;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신을 따라 다시 야영지까지 돌아가도록 하겠소. 내 조수인 호르니즈에게 얘기를 하면 보수를 지불해 줄 것이오.', `MaleText_loc4`='我会跟着你回到营地，然后你就可以去向我的助手霍恩尼兹要报酬啦。', `MaleText_loc5`='我會跟著你回到營地，然後你就可以去向我的助手霍恩尼茲要報酬啦。', `MaleText_loc7`='Te seguiré de regreso al campamento. Si hablas con Hornizz, mi asistente, él te pagará.' WHERE `ID`=2136;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 사랑 토르타! 내가 돌아왔소!', `MaleText_loc4`='我亲爱的托尔塔！我终于回来了。', `MaleText_loc5`='我親愛的托爾塔!我終於回來了。', `MaleText_loc7`='Thorta, ¡amor mío! Por fin he vuelto.' WHERE `ID`=2137;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼마나 오래 기다렸는지 알기나 해요? 그리고 저녁거리는 어디 있는 거예요? 그렇게 오랜 시간을 밖에서 보냈으면서 아무것도 안 가져왔단 말이에요?', `MaleText_loc4`='你知不知道我在这里等了很久？晚饭在哪里？那么晚了还没有晚饭的影子？', `MaleText_loc5`='你知不知道我在這裡等了很久?晚飯在哪裡?那麼晚了還沒有晚飯的影子?', `MaleText_loc7`='¿Te haces una idea del tiempo que llevo esperando aquí? ¿Y dónde está la cena? ¿Tanto tiempo fuera y no me tienes nada preparado?' WHERE `ID`=2138;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 세상에서 제일 많이 사랑하는 토르타. 그렇게 오랫동안 떨어져 있다가 이제야 다시 만났구려. 마침내 우리 사랑이 다시 꽃필 수 있게 되었소.', `MaleText_loc4`='亲爱的托尔塔，在别离那么长时间之后我们终于再次相见了。我们之间的爱还会更加热烈。', `MaleText_loc5`='親愛的托爾塔，在別離那麼長時間之後我們終於再次相見了。我們之間的愛還會更加熱烈。', `MaleText_loc7`='Mi adorada Thorta, he estado ausente durante tanto tiempo. Por fin volvemos a estar juntos. Nuestro amor renacerá al fin.' WHERE `ID`=2139;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말도 안 되는 소린 그만해요. 배고파 죽겠다고요! 얼른 바다에 들어가서 먹을 거나 좀 잡아와요.', `MaleText_loc4`='少废话，我肚子饿了！现在去海里给我找点吃的来！', `MaleText_loc5`='少廢話，我肚子餓了!現在去海裡給我找點吃的來!', `MaleText_loc7`='¡Bueno, ya basta! ¡Estoy hambrienta! Mete ese polvoriento caparazón en el mar y trae a mamá algo rico.' WHERE `ID`=2140;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래야지, 토르타. 당신이 원하는 거라면 뭐든지...', `MaleText_loc4`='好吧，托尔塔。你要什么我就给你找什么……', `MaleText_loc5`='好吧，托爾塔。你要什麼我就給你找什麼...', `MaleText_loc7`='Sí, Thorta. Lo que tu corazón desee.' WHERE `ID`=2141;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 영원의 불로 다시 태어나 혹한에도 너를 이끌어 줄 빛이 되리니...', `MaleText_loc4`='我是永不熄灭的。我永生不老，我在寒冷中给你带来温暖。', `MaleText_loc5`='我是永不熄滅的。我永生不老，我在寒冷中給你帶來溫暖。', `MaleText_loc7`='Soy fuego eterno. He renacido para siempre y seré la luz que te guiará en el más crudo invierno.' WHERE `ID`=2142;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='엘룬께서 우리와 함께하시기를! 자, 어서 이 사악한 요새를 떠나요.', `FemaleText_loc4`='月神与我们同在！让我们赶快逃出这座魔堡。', `FemaleText_loc5`='伊露恩與我們同在!讓我們趕快逃出這座魔堡。', `FemaleText_loc7`='¡Elune, permanece con nosotros! Salgamos rápido de esta fortaleza maligna.' WHERE `ID`=2143;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 서둘러 발라리엘에게 돌아가겠어요. 여기서부터는 저 혼자서도 충분하니 해치울 수 있는 녀석들은 마저 해치워 주세요.', `FemaleText_loc4`='我会尽快返回瓦拉里尔那里去。干掉那些你能对付得了的敌人，我自己过去应该没什么问题。', `FemaleText_loc5`='我會儘快返回瓦拉里爾那裡去。幹掉那些你能對付得了的敵人，我自己過去應該沒什麼問題。', `FemaleText_loc7`='Volveré rápidamente a Vahlarriel. Acabad con todos los que podáis, yo estaré bien sola a partir de aquí.' WHERE `ID`=2144;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 이번에는 제발 길을 잃지 마세요...', `MaleText_loc4`='这次不要再迷路了……', `MaleText_loc5`='這次不要再迷路了...', `MaleText_loc7`='E intentad no perderos esta vez...' WHERE `ID`=2145;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 멋진 표본들을 구해 왔네, 호르니즈. 이제 나는 이 표본들을 연구할 테니 나머지 일들은 자네가 맡아 주겠나?', `MaleText_loc4`='霍恩尼兹，我得到了一些样本。我要开始研究它们了，你能去研究剩余的那些吗？', `MaleText_loc5`='霍恩尼茲，我得到了一些樣本。我要開始研究它們了，你能去研究剩餘的那些嗎?', `MaleText_loc7`='Tengo unas muestras excelentes, Hornizz. Voy a ponerme a trabajar en ellos. ¿Puedes ocuparte del resto?' WHERE `ID`=2161;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런! 도구들을 다 써 버렸군. 처음부터 다시 시작해야겠어...', `MaleText_loc4`='啊！我的工具用完了。我们不得不重新开始……', `MaleText_loc5`='啊!我的工具用完了。我們不得不重新開始...', `MaleText_loc7`='¡Oh, no! Me he quedado sin herramientas. Vamos a tener que volver a empezar...' WHERE `ID`=2162;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네의 영혼이 밝게 타오르기를...', `MaleText_loc4`='愿你永远精神抖擞，$n。', `MaleText_loc5`='願你永遠精神抖擻，$n。', `MaleText_loc7`='Que tu espíritu brille intensamente, $n.' WHERE `ID`=2181;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신의 영혼은 순수하군요, $n.', `FemaleText_loc4`='你的灵魂很纯洁，$n。', `FemaleText_loc5`='你的靈魂很純潔，$n。', `FemaleText_loc7`='Tu espíritu es puro, $n.' WHERE `ID`=2182;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘과 끈기, 그리고 지혜와 인내심... 이것들을 항상 명심하게, $n.', `MaleText_loc4`='力量和忍耐，耐心和智慧——永远记住这些，$n。', `MaleText_loc5`='力量和忍耐，耐心和智慧─永遠記住這些，$n。', `MaleText_loc7`='Fuerza y resistencia, paciencia y sabiduría: recuérdalo siempre, $n.' WHERE `ID`=2183;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n, 평화와 인내가 그대와 함께하기를. 항상 강함을 유지하시기 바랍니다.', `FemaleText_loc4`='愿安宁和耐心永远与你同在，$n。', `FemaleText_loc5`='願安寧和耐心永遠與你同在，$n。', `FemaleText_loc7`='Que la paz y la paciencia te acompañen, $n. Permanece siempre fuerte.' WHERE `ID`=2184;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만, 그만! 내가 졌소!', `MaleText_loc4`='好吧，够了！我放弃！', `MaleText_loc5`='好吧，夠了!我放棄!', `MaleText_loc7`='¡Muy bien, ya basta! ¡Me rindo!' WHERE `ID`=2201;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하! 운이 더 좋은 날 다시 도전하시오, $n.', `MaleText_loc4`='祝你下次好运，$n。', `MaleText_loc5`='祝你下次好運，$n。', `MaleText_loc7`='Más suerte la próxima vez, $n.' WHERE `ID`=2202;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 당신이 이겼소. 내가 졌다고!', `MaleText_loc4`='你赢了，$n。你赢了！', `MaleText_loc5`='你贏了，$n。你贏了!', `MaleText_loc7`='Has ganado, $n. ¡Has ganado!' WHERE `ID`=2203;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 한참 더 가야 하나요?', `MaleText_loc4`='我们还要走更远吗？', `MaleText_loc5`='我們還要走更遠嗎，$n?', `MaleText_loc7`='¿Tenemos que ir mucho más lejos?' WHERE `ID`=2221;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='목이 말라요.', `MaleText_loc4`='我很渴。', `MaleText_loc5`='我很渴。', `MaleText_loc7`='Tengo sed.' WHERE `ID`=2222;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직도 멀었나요?', `MaleText_loc4`='还没到吗？', `MaleText_loc5`='還沒到嗎?', `MaleText_loc7`='¿Falta mucho?' WHERE `ID`=2223;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발가락 사이로 자꾸 모래가 들어온단 말이에요.', `MaleText_loc4`='沙子灌进鞋里了……', `MaleText_loc5`='沙子灌進鞋裡了...', `MaleText_loc7`='Tengo arena en los pies.' WHERE `ID`=2224;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼마나 더 가야 되는 거예요?', `MaleText_loc4`='要走多远？', `MaleText_loc5`='要走多遠?', `MaleText_loc7`='¿Cuánto nos queda para llegar?' WHERE `ID`=2225;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='업혀 가면 편할 텐데...', `MaleText_loc4`='你能背我走一段吗？', `MaleText_loc5`='你能背我走一段嗎?', `MaleText_loc7`='Ojalá pudieras cogerme y cargar conmigo.' WHERE `ID`=2226;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혹시 오우거, 고블린, 그리고 지옥의 군주에 대해서 들어본 적이 있으세요?', `MaleText_loc4`='你听说过食人魔、地精和深渊领主的故事吗？', `MaleText_loc5`='你聽過巨魔、哥布林和深淵領主的故事嗎?', `MaleText_loc7`='¿Conoces el chiste del ogro, el goblin y el señor del foso?' WHERE `ID`=2227;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='토르타가 많이 걱정하겠는걸.', `MaleText_loc4`='托尔塔肯定很担心。', `MaleText_loc5`='托爾塔肯定很擔心。', `MaleText_loc7`='Thorta tiene que estar muy preocupada.' WHERE `ID`=2228;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네 머리는 내 전리품 목록에 추가될 것이다, $R.', `FemaleText_loc4`='这是个很好的战利品，$c。', `FemaleText_loc5`='你的頭顱將是個很好的戰利品，$r。', `FemaleText_loc7`='Tu cabeza será un excelente trofeo, $r.' WHERE `ID`=2229;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 발톱으로 그 연약한 몸뚱이를 갈가리 찢어 주지!', `FemaleText_loc4`='我的爪子将把你撕得粉碎，$R。', `FemaleText_loc5`='我的爪子將把你撕得粉碎，$R。', `FemaleText_loc7`='Mis garras destrozarán tu raquítico cuerpo, $r.' WHERE `ID`=2230;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아주 우습게 처치할 수 있겠군.', `FemaleText_loc4`='你死定了，$C。', `FemaleText_loc5`='你死定了，$C。', `FemaleText_loc7`='Serás presa fácil, $c.' WHERE `ID`=2231;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아쿠마이 님께서 순결한 제물을 더 많은 원하십니다.', `MaleText_loc4`='阿库麦尔需要更多的祭品。', `MaleText_loc5`='阿庫麥爾需要更多的祭品。', `MaleText_loc7`='Aku''mai necesita más inocentes para estar satisfecho.', `FemaleText_loc1`='아쿠마이 님께서 순결한 제물을 더 많은 원하십니다.', `FemaleText_loc4`='阿库麦尔需要更多的祭品。', `FemaleText_loc5`='阿庫麥爾需要更多的祭品。', `FemaleText_loc7`='Aku''mai necesita más inocentes para estar satisfecho.' WHERE `ID`=2241;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='순결한 피만이 아쿠마이 님의 굶주림을 채울 수 있습니다.', `MaleText_loc4`='只有无辜者的鲜血才能平息阿库麦尔的愤怒。', `MaleText_loc5`='只有無辜者的鮮血才能平息阿庫麥爾的憤怒。', `MaleText_loc7`='Solo sangre inocente podrá saciar el apetito de Aku''mai.', `FemaleText_loc1`='순결한 피만이 아쿠마이 님의 굶주림을 채울 수 있습니다.', `FemaleText_loc4`='只有无辜者的鲜血才能平息阿库麦尔的愤怒。', `FemaleText_loc5`='只有無辜者的鮮血才能平息阿庫麥爾的憤怒。', `FemaleText_loc7`='Solo sangre inocente podrá saciar el apetito de Aku''mai.' WHERE `ID`=2242;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='머지않아 고대 신들이 부활할 것입니다.', `MaleText_loc4`='不久我们就可以迎回上古之神了。', `MaleText_loc5`='不久我們就可以迎回上古諸神了。', `MaleText_loc7`='Pronto propiciaremos el retorno de los dioses antiguos.', `FemaleText_loc1`='머지않아 고대 신들이 부활할 것입니다.', `FemaleText_loc4`='不久我们就可以迎回上古之神了。', `FemaleText_loc5`='不久我們就可以迎回上古諸神了。', `FemaleText_loc7`='Pronto propiciaremos el retorno de los dioses antiguos.' WHERE `ID`=2243;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아쿠마이 님께서 분명 우릴 위해 고대 신들을 부활시켜 주실 겁니다. 순결한 제물을 충분히 바쳐 그분의 굶주림을 채워 드릴 수만 있다면...', `MaleText_loc4`='阿库麦尔肯定会为我们召唤上古之神的，只要我们能够提供足够多的祭品！', `MaleText_loc5`='阿庫麥爾肯定會為我們召喚上古諸神的，只要我們能夠提供足夠多的祭品!', `MaleText_loc7`='Aku''mai podrá invocar para nosotros a los dioses antiguos. Siempre que podamos entregarle suficientes inocentes para calmar su apetito.', `FemaleText_loc1`='아쿠마이 님께서 분명 우릴 위해 고대 신들을 부활시켜 주실 겁니다. 순결한 제물을 충분히 바쳐 그분의 굶주림을 채워 드릴 수만 있다면...', `FemaleText_loc4`='阿库麦尔肯定会为我们召唤上古之神的，只要我们能够提供足够多的祭品！', `FemaleText_loc5`='阿庫麥爾肯定會為我們召喚上古諸神的，只要我們能夠提供足夠多的祭品!', `FemaleText_loc7`='Aku''mai podrá invocar para nosotros a los dioses antiguos. Siempre que podamos entregarle suficientes inocentes para calmar su apetito.' WHERE `ID`=2244;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마침 딱 좋아보이는 자가 나타나다니!', `MaleText_loc4`='你穿得真不错。', `MaleText_loc5`='你穿得真不錯。', `MaleText_loc7`='Qué conjunto más estupendo llevas puesto.', `FemaleText_loc1`='마침 딱 좋아보이는 자가 나타나다니!', `FemaleText_loc4`='你穿得真不错。', `FemaleText_loc5`='你穿得真不錯。', `FemaleText_loc7`='Qué conjunto más estupendo llevas puesto.' WHERE `ID`=2245;
