UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙소, 젊은이. 정말로 고맙소이다.', `MaleText_loc4`='谢谢你，$G小伙子:姑娘;。非常感谢。', `MaleText_loc5`='謝謝你，$G小夥子:姑娘;。非常感謝。', `MaleText_loc7`='Gracias, $gmuchacho:muchacha;. Muchísimas gracias.' WHERE `ID`=2281;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='햄혹에게 큰일이 났다! 햄혹을 좀 도와줘!', `MaleText_loc4`='哈姆霍克有麻烦了！哈姆霍克需要帮助！', `MaleText_loc5`='哈姆霍克有麻煩了!哈姆霍克需要幫助!', `MaleText_loc7`='¡Hamhock tener problemas! ¡Hamhock necesita ayuda!' WHERE `ID`=2282;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙소. 정말로 고맙소이다.', `MaleText_loc4`='谢谢你，$G小伙子:姑娘;。非常感谢。', `MaleText_loc5`='謝謝你，$G小夥子:姑娘;。非常感謝。', `MaleText_loc7`='Gracias, $gmuchacho:muchacha;. Muchísimas gracias.' WHERE `ID`=2283;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙소, $n.', `MaleText_loc4`='谢谢你，$n。', `MaleText_loc5`='謝謝你，$n。', `MaleText_loc7`='Gracias a ti, $n.' WHERE `ID`=2284;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성스러운 빛이 당신과 함께하기를, $n.', `MaleText_loc4`='愿圣光与你同在，$n。', `MaleText_loc5`='願聖光與你同在，$n。', `MaleText_loc7`='Que la Luz te acompañe, $n.' WHERE `ID`=2285;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 분명 우리를 위한 축복이오, $n. 고맙소이다.', `MaleText_loc4`='祝福你，$n。谢谢你。', `MaleText_loc5`='祝福你，$n。謝謝你。', `MaleText_loc7`='Eres muy amable, $n. Gracias.' WHERE `ID`=2286;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='격투가 시작됐소. $n, 싸울 준비를 하시오!', `MaleText_loc4`='$n，准备战斗！', `MaleText_loc5`='喧鬧開始了。$n，準備戰鬥!', `MaleText_loc7`='La Reyerta ha comenzado. ¡$n, prepárate para luchar!' WHERE `ID`=2301;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 가시게, $n. 그리고 전사는 절대로 적에게 등을 보여선 안 된다는 것을 잊지 말게나!', `MaleText_loc4`='再见，$n。记住，一名真正的战士是永远不会逃跑的！', `MaleText_loc5`='再見，$n。記住，一名真正的戰士是永遠不會逃跑的!', `MaleText_loc7`='Adiós, $n. Y recuerda: ¡un guerrero nunca da la espalda a su enemigo!' WHERE `ID`=2302;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 작업을 시작합니다...', `MaleText_loc4`='%s开始工作……', `MaleText_loc5`='%s開始工作...', `MaleText_loc7`='%s comienza a trabajar...' WHERE `ID`=2303;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 다 되었소! $n.', `MaleText_loc4`='$n！我搞定了！', `MaleText_loc5`='$n!我搞定了!', `MaleText_loc7`='¡$n! ¡He terminado!' WHERE `ID`=2304;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙소, $n. 행운을 빌겠소!', `MaleText_loc4`='谢谢你，$n。祝你好运！', `MaleText_loc5`='謝謝你，$n。祝你好運!', `MaleText_loc7`='Gracias, $n. ¡Y suerte!' WHERE `ID`=2305;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 무기를 만들기 시작합니다...', `MaleText_loc4`='%s开始打造……', `MaleText_loc5`='%s開始打造...', `MaleText_loc7`='%s comienza a trabajar...' WHERE `ID`=2306;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다 됐소, $n. 그대의 무기가 드디어 다 만들어졌소.', `MaleText_loc4`='你的武器做好了，$n。', `MaleText_loc5`='你的武器做好了，$n。', `MaleText_loc7`='Está hecho. Tu arma ya está lista, $n.' WHERE `ID`=2307;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 도전을 마쳤소! $n|1을;를; 위해 만세 삼창!', `MaleText_loc4`='$n成功了！为$n欢呼三声！', `MaleText_loc5`='$n成功了!為$n歡呼三聲!', `MaleText_loc7`='¡$n superó el reto! ¡Tres hurras para $n!' WHERE `ID`=2308;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='만세! 만세! 만세!', `MaleText_loc4`='一，二——三！', `MaleText_loc5`='喝哈，萬歲!', `MaleText_loc7`='¡Hip, hip, hurra!' WHERE `ID`=2309;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천 년 전에 숲의 반신인 불멸의 엘프와 용이 하이잘 산 중턱에서 불타는 군단과 전투를 벌였소.', `MaleText_loc4`='一千年以前，不朽的暗夜精灵、森林中的半神和巨龙曾并肩在海加尔山上对抗燃烧军团。', `MaleText_loc5`='一千年以前，不朽的夜精靈、森林中的半神和巨龍曾並肩在海加爾山上對抗燃燒軍團。', `MaleText_loc7`='Hace mil años, los elfos inmortales, los semidioses del bosque y los dragones lucharon contra la Legión en las laderas de Hyjal.' WHERE `ID`=2310;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아나테라와 라테리온은 가장 격렬했던 전투 속에서 서로 등을 맞대고 싸웠지. 그 두 연인은 함께 살아남으리라 굳게 다짐했소.', `MaleText_loc4`='在战斗最激烈的时候，安娜瑟拉和拉瑟里安背靠背地战斗着。两个恋人决心在这场战争中一起活下来。', `MaleText_loc5`='在戰鬥最激烈的時候，安娜瑟拉和拉瑟里安背靠背地戰鬥著。兩個戀人決心在這場戰爭中一起活下來。', `MaleText_loc7`='Anathera y Latherion lucharon hombro con hombro en el fragor de la batalla. Dos amantes decididos a sobrevivir juntos a la guerra.' WHERE `ID`=2311;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 엘룬은 그 사랑을 허락하지 않았소. 악마의 오염된 칼날이 아나테라의 갑옷을 뚫고 들어왔지. 격렬한 전장에서 누구도 그녀를 구할 수 없었소.', `MaleText_loc4`='但事实却是残酷的。在与敌人作战时，安娜瑟拉的护甲被恶魔的利刃穿透了。在如此激烈的战争中，没有什么能拯救她。', `MaleText_loc5`='但事實卻是殘酷的。在與敵人作戰時，安娜瑟拉的護甲被惡魔的利刃穿透。在如此激烈的戰爭中，沒有什麼能拯救她。', `MaleText_loc7`='Pero no pudo ser. Cuando sus adversarios les acorralaron, la impía espada de un demonio atravesó la armadura de Anathera. En el fragor de la batalla nada pudo hacerse para salvarla.' WHERE `ID`=2312;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아나테라!', `MaleText_loc4`='安娜瑟拉！', `MaleText_loc5`='安娜瑟拉!', `MaleText_loc7`='¡Anathera!' WHERE `ID`=2313;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아나테라가 쓰러지자 라테리온은 주위에서 일어나는 전투는 잊은 채 사랑하는 연인을 품에 안았지. 악마들은 그 아름다운 모습에도 아랑곳하지 않고 라테리온마저 죽여버렸소.', `MaleText_loc4`='拉瑟里安不顾正在进行的激烈战斗，放下了自己的武器，紧紧地抱着他死去的爱人。但是恶魔没有停止攻击，很快就将他无情地杀死了。', `MaleText_loc5`='拉瑟里安不顧正在進行的激烈戰鬥，放下了自己的武器，緊緊地抱著他死去的愛人。但是惡魔沒有停止攻擊，很快就將他無情地殺死了。', `MaleText_loc7`='Ignorando la batalla que se cernía sobre él, Latherion bajó la guardia para tomar a su amor en brazos mientras exhalaba su último suspiro. Pero nos demonios no tuvieron clemencia con él y rápidamente lo aniquilaron.' WHERE `ID`=2314;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아나테라... 난 당신 없인 이 영원한 삶을 견뎌낼 수가 없소... 당신이 떠난다면 나도 당신을 따라 흙으로 되돌아 갈 것이오.', `MaleText_loc4`='安娜瑟拉……没有你，我怎么能独自忍受永生的煎熬……如果你就此离去，那么就让我也魂归大地吧……', `MaleText_loc5`='安娜瑟拉...沒有你，我怎麼能獨自忍受永生的煎熬...如果你就此離去，那麼就讓我也魂歸大地吧...', `MaleText_loc7`='Anathera... No puedo soportar el resto de la eternidad sin ti a mi lado... Si te vas de mi lado, que sea este el día en que yo también vuelva a la tierra...' WHERE `ID`=2315;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그러니까 이... 이게 우리의 마지막이로군요, 내 사랑...', `FemaleText_loc4`='就这样结束了……我的爱人……', `FemaleText_loc5`='就這樣結束了...我的愛人...', `FemaleText_loc7`='Así... así es como acaba nuestra historia, amor mío...' WHERE `ID`=2316;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 두 연인이 숨을 거둔 곳에 나무 한 그루가 자랐소. 엘프들은 그 나무를 사랑나무라고 부르지. 분명 서큐버스를 불러내는 자극제가 될 것이오.', `MaleText_loc4`='在他们倒下去的地方长出了一棵树，暗夜精灵将其称为同心树。它就是你要寻找的东西。', `MaleText_loc5`='在他們倒下去的地方長出了一棵樹，夜精靈將其稱為同心樹。它就是你要尋找的東西。', `MaleText_loc7`='Donde cayeron los dos amantes florece un árbol. Los elfos lo llaman Madera de Corazón. Seguramente servirá a tus propósitos.' WHERE `ID`=2317;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기! 당신 차례요!', `MaleText_loc4`='你！快加入战斗！', `MaleText_loc5`='你!快加入戰鬥!', `MaleText_loc7`='¡Eh, tú! ¡Entra en combate!' WHERE `ID`=2318;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='첫 번째 단계가 끝났소. 싸움꾼 윌... 이리 내려오라고!', `MaleText_loc4`='第一阶段结束了。比格维尔……该你上了！', `MaleText_loc5`='第一階段結束了。比格維爾...該你上了!', `MaleText_loc7`='La primera etapa ha terminado. Will el Grande... ¡desciende!' WHERE `ID`=2319;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='격투가 끝났소!', `MaleText_loc4`='战斗结束了！', `MaleText_loc5`='戰鬥結束了!', `MaleText_loc7`='¡La Reyerta ha terminado!' WHERE `ID`=2320;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 우두머리가 죽는 것을 보고는 겁에 질려 줄행랑을 칩니다!', `MaleText_loc4`='%s眼见监工死去，便害怕地逃走了！', `MaleText_loc5`='%s看到監督者死亡便害怕地逃走了!', `MaleText_loc7`='¡%s ve cómo muere el supervisor y huye despavorido!' WHERE `ID`=2321;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 작업을 시작합니다...', `MaleText_loc4`='%s开始工作……', `MaleText_loc5`='%s開始工作...', `MaleText_loc7`='%s comienza a trabajar...' WHERE `ID`=2341;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끝났네! 결과가 놀랍군. 내 동료인 그리만트와 메시엘, 클락몰트에게 반드시 이걸 보여줘야겠구먼.', `MaleText_loc4`='结束了！结果真是令人惊讶。我必须把它们转达给我的同伙格瑞曼德、玛希尔和科劳莫特！', `MaleText_loc5`='結束了!結果真是令人驚訝。我必須把它們轉達給我的同夥格瑞曼德、瑪希爾和科勞莫特!', `MaleText_loc7`='¡Listo! Y los resultados son sorprendentes. ¡Tengo que transmitírselos a mis socios Grimand, Mathiel y Klockmort!' WHERE `ID`=2342;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갑옷이 준비됐네, $n.', `MaleText_loc4`='你的护甲已经准备好了，$n。', `MaleText_loc5`='你的護甲已經準備好了，$n。', `MaleText_loc7`='Tu armadura está lista, $n.' WHERE `ID`=2343;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 작업을 시작합니다...', `MaleText_loc4`='%s开始工作……', `MaleText_loc5`='%s開始工作...', `MaleText_loc7`='%s comienza a trabajar...' WHERE `ID`=2344;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야호, 야호! 다 끝났어요! $n.', `MaleText_loc4`='万岁！$n！完成了！', `MaleText_loc5`='萬歲!$n!完成了!', `MaleText_loc7`='¡Hurra! ¡$n! ¡Está lista!' WHERE `ID`=2345;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 작업을 시작합니다...', `MaleText_loc4`='%s开始工作……', `MaleText_loc5`='%s開始工作...', `MaleText_loc7`='%s comienza a trabajar...' WHERE `ID`=2346;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놀랍군! 효과가 있어! 이보라고 친구, 갑옷이 완성됐소.', `MaleText_loc4`='太令人惊讶了！成功了！$n，你的护甲做好了。', `MaleText_loc5`='太令人驚訝了!成功了!$n，你的護甲做好了。', `MaleText_loc7`='¡Sorprendente! ¡Ha funcionado! $n, ya tengo tu armadura.' WHERE `ID`=2347;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 작업을 시작합니다...', `MaleText_loc4`='%s开始工作……', `MaleText_loc5`='%s開始工作...', `MaleText_loc7`='%s comienza a trabajar...' WHERE `ID`=2348;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='완성했소, $n. 그대의 갑옷을 다 만들었소.', `MaleText_loc4`='完成了。$n，你的护甲准备好了。', `MaleText_loc5`='完成了。$n，你的護甲準備好了。', `MaleText_loc7`='Está lista. Tu armadura está lista, $n.' WHERE `ID`=2349;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='행운을 빌겠소, $n. 임무를 마친 후에는 뮈레돈을 찾아가는 것을 잊지 마시오.', `MaleText_loc4`='祝你好运，$n。记住，完成任务之后就去找穆里顿。', `MaleText_loc5`='祝你好運，$n。記住，完成任務之後就去找穆里頓。', `MaleText_loc7`='Suerte, $n. Y recuerda, encuentra a Muiredon cuando hayas terminado la tarea.' WHERE `ID`=2351;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 행운을 빌겠소. 그리고 가쟁을 찾아가기 전에 그 문서부터 꼭 손에 넣도록 하시오.', `MaleText_loc4`='祝你好运，$n。不要忘记……找到手稿之后就去找贾森。', `MaleText_loc5`='祝你好運，$n。不要忘記...找到手稿之後就去找傑生。', `MaleText_loc7`='Suerte para ti, $n. Y no lo olvides: encuentra el escrito antes de ir a buscar a Gazin.' WHERE `ID`=2353;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 만세! 격투장의 새로운 영웅이여!', `MaleText_loc4`='为$n欢呼！新的冠军诞生了！', `MaleText_loc5`='為$n歡呼!新的勇士誕生了!', `MaleText_loc7`='¡Ave $n! ¡$gEl nuevo campeón:La nueva campeona; de La Reyerta!' WHERE `ID`=2354;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도전자가 쓰러졌소!', `MaleText_loc4`='挑战者输了！', `MaleText_loc5`='挑戰者輸了!', `MaleText_loc7`='¡Ha caído el oponente!' WHERE `ID`=2355;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 사기가 꺾여 도망을 칩니다!', `MaleText_loc4`='%s士气受挫，转身逃走了！', `MaleText_loc5`='%s士氣受挫，轉身逃走了!', `MaleText_loc7`='%s se desmoraliza y huye.' WHERE `ID`=2356;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오, 여보 어디 있어요! 싫어! 당신 없이 혼자 죽을 순 없어...', `FemaleText_loc4`='啊，我的爱人！不！让我临死之前再见你一面吧……', `FemaleText_loc5`='啊，我的愛人!不!讓我臨死之前再見你一面吧...', `FemaleText_loc7`='¡Oh, amor mío! ¡No! No dejes que muera sin ti...' WHERE `ID`=2357;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='해냈어요! 우리가 이겼어!', `FemaleText_loc4`='我们成功了！我们赢了！', `FemaleText_loc5`='我們成功了!我們贏了!', `FemaleText_loc7`='¡Lo hemos conseguido! ¡Hemos ganado!' WHERE `ID`=2358;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너희가 내 땅을 망가뜨릴 순 없을 거다, 이 더러운 놈들!', `FemaleText_loc4`='别想毁了我的地盘，你这个人渣！', `FemaleText_loc5`='別想毀了我的地盤，你這個人渣!', `FemaleText_loc7`='¡No vais a destruir mis tierras, escoria!' WHERE `ID`=2359;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='집으로 가요! 무슨 일이 있어도 내 옆에 가까이 붙어 있어요! 집 안에 총과 탄약이 있어요!', `FemaleText_loc4`='到房子那边去！无论如何都要紧跟着我！那里有枪和弹药！', `FemaleText_loc5`='到房子那邊去!無論如何都要緊跟著我!那裡有槍和彈藥!', `FemaleText_loc7`='¡A la casa! ¡Permaneced cerca de mí, pase lo que pase! ¡Mi arma y las municiones están allí!' WHERE `ID`=2360;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 점령하기 안성맞춤인 곳이군! 나머지도 불러와.', `MaleText_loc4`='这个地方对迪菲亚兄弟会来说很安全！叫其他兄弟过来。', `MaleText_loc5`='這個地方對迪菲亞兄弟會來說很安全!叫其他兄弟過來。', `MaleText_loc7`='¡Este lugar está a salvo de la invasión de los Defias! Id a por los demás.', `FemaleText_loc1`='우리가 점령하기 안성맞춤인 곳이군! 나머지도 불러와.', `FemaleText_loc4`='这个地方对迪菲亚兄弟会来说很安全！叫其他兄弟过来。', `FemaleText_loc5`='這個地方對迪菲亞兄弟會來說很安全!叫其他兄弟過來。', `FemaleText_loc7`='¡Este lugar está a salvo de la invasión de los Defias! Id a por los demás.' WHERE `ID`=2361;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서부 몰락지대를 점령한 후 스톰윈드로 나아가자!', `MaleText_loc4`='首先西部荒野，然后是整个暴风城！', `MaleText_loc5`='首先西部荒野，然後是整個暴風城!', `MaleText_loc7`='¡Primero los Páramos de Poniente y después todo Ventormenta!', `FemaleText_loc1`='서부 몰락지대를 점령한 후 스톰윈드로 나아가자!', `FemaleText_loc4`='首先西部荒野，然后是整个暴风城！', `FemaleText_loc5`='首先西部荒野，然後是整個暴風城!', `FemaleText_loc7`='¡Primero los Páramos de Poniente y después todo Ventormenta!' WHERE `ID`=2362;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 너 따위가 우리 데피아즈단을 상대하려 들다니!', `MaleText_loc4`='一个小小的农妇是无法对抗迪菲亚的！', `MaleText_loc5`='一個小小的農婦是無法對抗迪菲亞的!', `MaleText_loc7`='¡Ninguna granjera puede enfrentarse a los Defias!', `FemaleText_loc1`='감히 너 따위가 우리 데피아즈단을 상대하려 들다니!', `FemaleText_loc4`='一个小小的农妇是无法对抗迪菲亚的！', `FemaleText_loc5`='一個小小的農婦是無法對抗迪菲亞的!', `FemaleText_loc7`='¡Ninguna granjera puede enfrentarse a los Defias!' WHERE `ID`=2363;
