UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너무 멀리 돌아다니지는 마세요. 틀림없이 숨어있는 다른 녀석들이 더 있을 거예요.', `FemaleText_loc4`='不要走得太远。我相信他们大部分人都在那里。', `FemaleText_loc5`='不要走得太遠。我相信他們來了更多敵人。', `FemaleText_loc7`='No vayáis demasiado lejos. Estoy seguro que por aquí cerca hay más.' WHERE `ID`=2368;
