UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지난번에는 놈들이 단 한 번만 공격했었지만 이번엔 여러 차례 공격이 있을 거예요.', `FemaleText_loc4`='上回他们只发动了一轮攻击，如果这次他们进行多次攻击，我并不会感到惊讶。', `FemaleText_loc5`='上回他們只發動了一輪攻擊，如果這次他們進行多次攻擊，我並不會感到驚訝。', `FemaleText_loc7`='La última vez que atacaron, solo lo hicieron una vez. No me sorprendería que ahora hubiera más ataques.' WHERE `ID`=2373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 수행사제들이여. 정신 집중의 마법봉을 사용하여 더 거대한 소환 마법진을 만들도록.', `MaleText_loc4`='过来，我的侍僧。拿好法杖，准备创建召唤法阵。', `MaleText_loc5`='過來，我的侍僧。拿好法杖，準備創建召喚法陣。', `MaleText_loc7`='Venid, mis acólitos. Traed los cetros de canalización y ampliad el círculo de invocación.' WHERE `ID`=2374;
