UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 분노에 휩싸입니다!', `MaleText_loc4`='%s变得愤怒了！', `MaleText_loc5`='%s暴怒了起來!', `MaleText_loc7`='¡%s entra en frenesí!', `FemaleText_loc1`='%s|1이;가; 분노에 휩싸입니다!', `FemaleText_loc4`='%s变得愤怒了！', `FemaleText_loc5`='%s暴怒了起來!', `FemaleText_loc7`='¡%s entra en frenesí!' WHERE `ID`=2384;
