UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드의 아이들을 도와주세요... 전쟁과 질병에 희생된 불쌍한 아이들입니다!', `MaleText_loc4`='帮帮暴风城的孩子们吧……他们是战争的受害者！', `MaleText_loc5`='幫幫暴風城的孩子們吧...他們是戰爭和瘟疫的受害者!', `MaleText_loc7`='¡Ayudad a los niños de Ventormenta... víctimas de la guerra y la Peste!' WHERE `ID`=2402;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 험난한 시대의 희생양들을 도웁시다. 조금만 자선을 베풀어 주세요! 제발 부탁드립니다.', `MaleText_loc4`='请多捐助点东西给慈善机构吧，我们必须帮助那些无依无靠的人！', `MaleText_loc5`='請多捐助點東西給慈善機構吧，我們必須幫助那些無依無靠的人!', `MaleText_loc7`='¡Ayudad a las organizaciones benéficas que ayudan a las víctimas en estos tiempos difíciles! Por favor.' WHERE `ID`=2403;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='따뜻한 마음을 나눠 주세요! 부모 잃은 스톰윈드의 아이들에게 도움을 부탁 드립니다!', `MaleText_loc4`='献出您的爱心和金钱吧！帮助失去双亲的暴风城孤儿们！', `MaleText_loc5`='獻出您的愛心和金錢吧!幫助失去雙親的暴風城孤兒們!', `MaleText_loc7`='¡Sean generosos con sus corazones y sus bolsillos! Cooperen con los niños de Ventormenta que han perdido a sus padres.' WHERE `ID`=2404;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아쿠마이 님께서 제물을 더 원하신다. 이제 너를 순결한 제물로 바쳐야겠다!', `MaleText_loc4`='阿库麦尔需要更多的祭品，所以你现在必须死！', `MaleText_loc5`='阿庫麥爾需要更多的祭品，所以你現在必須死!', `MaleText_loc7`='¡Aku''mai exige más sacrificios, así que ahora tienes que morir!', `FemaleText_loc1`='아쿠마이 님께서 제물을 더 원하신다. 이제 너를 순결한 제물로 바쳐야겠다!', `FemaleText_loc4`='阿库麦尔需要更多的祭品，所以你现在必须死！', `FemaleText_loc5`='阿庫麥爾需要更多的祭品，所以你現在必須死!', `FemaleText_loc7`='¡Aku''mai exige más sacrificios, así que ahora tienes que morir!' WHERE `ID`=2406;
