UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고대 신들은 반드시 부활해야 한다. 네놈이 방해할 수는 없을 것이다!', `MaleText_loc4`='上古之神将会重生，你别想阻止这一切！', `MaleText_loc5`='上古諸神將會重生，你別想阻止這一切!', `MaleText_loc7`='Los dioses antiguos serán restituidos. ¡No podréis interferir!', `FemaleText_loc1`='고대 신들은 반드시 부활해야 한다. 네놈이 방해할 수는 없을 것이다!', `FemaleText_loc4`='上古之神将会重生，你别想阻止这一切！', `FemaleText_loc5`='上古諸神將會重生，你別想阻止這一切!', `FemaleText_loc7`='Los dioses antiguos serán restituidos. ¡No podréis interferir!' WHERE `ID`=2408;
