UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 종족이 아닌 자는 단 한 놈도 살려두지 않겠다!', `MaleText_loc4`='我们不能放弃任何一个侏儒！', `MaleText_loc5`='我們不能放棄任何一個地精!', `MaleText_loc7`='Ningún gnomo se quedará atrás.', `FemaleText_loc1`='우리 종족이 아닌 자는 단 한 놈도 살려두지 않겠다!', `FemaleText_loc4`='我们不能放弃任何一个侏儒！', `FemaleText_loc5`='我們不能放棄任何一個地精!', `FemaleText_loc7`='Ningún gnomo se quedará atrás.' WHERE `ID`=2422;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='질긴 트로그들... 끝도 없이 밀려오는군. 죽어라, 트로그! 죽어!', `MaleText_loc4`='穴居人……好像永远也杀不光。该死的穴居人！去死吧！', `MaleText_loc5`='穴居怪...好像永遠也殺不光。該死的穴居怪!去死吧!', `MaleText_loc7`='Los troggs... no dejan de venir. ¡Muere, trogg! ¡Muere!', `FemaleText_loc1`='질긴 트로그들... 끝도 없이 밀려오는군. 죽어라, 트로그! 죽어!', `FemaleText_loc4`='穴居人……好像永远也杀不光。该死的穴居人！去死吧！', `FemaleText_loc5`='穴居怪...好像永遠也殺不光。該死的穴居怪!去死吧!', `FemaleText_loc7`='Los troggs... no dejan de venir. ¡Muere, trogg! ¡Muere!' WHERE `ID`=2423;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='병으로 잘 보이지는 않아도 네가 분명 트로그라는 것쯤은 안다고. 죽어라, 이 더러운 침략자!', `MaleText_loc4`='疾病让我的视觉受损，但我知道你一定是穴居人。去死吧，该死的入侵者！', `MaleText_loc5`='疾病讓我的視覺受損，但我知道你一定是穴居怪。去死吧，該死的入侵者!', `MaleText_loc7`='Esta enfermedad nubla mi vista, pero sé que tienes que ser un trogg. ¡Muere, $ginvasor apestoso:invasora apestosa;!', `FemaleText_loc1`='병으로 잘 보이지는 않아도 네가 분명 트로그라는 것쯤은 안다고. 죽어라, 이 더러운 침략자!', `FemaleText_loc4`='疾病让我的视觉受损，但我知道你一定是穴居人。去死吧，该死的入侵者！', `FemaleText_loc5`='疾病讓我的視覺受損，但我知道你一定是穴居怪。去死吧，該死的入侵者!', `FemaleText_loc7`='Esta enfermedad nubla mi vista, pero sé que tienes que ser un trogg. ¡Muere, $ginvasor apestoso:invasora apestosa;!' WHERE `ID`=2424;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='역겨운 트로그놈들. 죽어라!', `MaleText_loc4`='又是穴居人，去死吧！', `MaleText_loc5`='又是穴居怪，去死吧!', `MaleText_loc7`='$gUn:Una; trogg repugnante donde $glos:las; haya. ¡Muere!', `FemaleText_loc1`='역겨운 트로그놈들. 죽어라!', `FemaleText_loc4`='又是穴居人，去死吧！', `FemaleText_loc5`='又是穴居怪，去死吧!', `FemaleText_loc7`='$gUn:Una; trogg repugnante donde $glos:las; haya. ¡Muere!' WHERE `ID`=2425;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='차례가 되면 이름을 불러 드릴 테니 기다려 주세요. 화면에 나타나는 순서대로 여러분을 도와 드리고 있습니다.', `MaleText_loc4`='耐心点，轮到你的时候我们会叫你的。我们会依照屏幕显示的顺序帮助你们的。', `MaleText_loc5`='耐心點，輪到你的時候我們會叫你的。我們會依照螢幕顯示的順序幫助你們的。', `MaleText_loc7`='Por favor, ten paciencia, te llamaremos cuando sea tu turno. Estamos ayudando a la gente según aparecen en nuestra pantalla.' WHERE `ID`=2426;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='운영자를 괴롭히거나 채널에 스팸을 발송하면 사용자 계정을 거부 또는 금지하거나 그 이상의 제재를 가할 수 있음을 명심하십시오.', `MaleText_loc4`='记住，如果你骚扰机器人或者在频道里传播垃圾信息，那你的人物将被踢出服务器，被暂时封锁或者遭受更严厉的处罚。', `MaleText_loc5`='記住，如果你騷擾其他玩家或在頻道裡濫發訊息，那你的人物將被踢出伺服器，被暫時封鎖或者遭受更嚴厲的處罰。', `MaleText_loc7`='Recuerda, si molestas al representante o inundas el canal, podemos expulsar o cerrar tu cuenta, o incluso hacer algo peor.' WHERE `ID`=2427;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 로봇입니다. 많은 정보를 가지고 있으니 원하시면 귓속말로 얘기해 주십시오.', `MaleText_loc4`='我是机器人。我有很多资料。如果您想要知道我都知道些什么，那就和我谈谈。', `MaleText_loc5`='我是機器人。我有很多資料。如果您想要知道我都知道些什麼，那就和我談談。', `MaleText_loc7`='Soy un ROBOT. Tengo toneladas de datos. Para que te diga lo que sé, susúrrame.' WHERE `ID`=2428;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋은 하루 되십시오.', `MaleText_loc4`='不客气，祝您今天过得愉快。', `MaleText_loc5`='不客氣，祝您今天過得愉快。', `MaleText_loc7`='De nada, que tengas un buen día.' WHERE `ID`=2429;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타우렌 버전 로봇은 없습니다. 정말입니다! 아니, 어쩌면 있을지도 모르겠습니다.', `MaleText_loc4`='没有奶牛关啦……真的！我再说一遍：没有奶牛关。好吧，也许有……', `MaleText_loc5`='沒有乳牛關啦...真的!我再說一遍:沒有乳牛關。好吧，也許有...', `MaleText_loc7`='No hay un nivel SECRETO... ¡En serio! Repito: No hay un nivel SECRETO. Bueno, tal vez sí...' WHERE `ID`=2430;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 감성이 예민해서 무례한 행동에는 쉽게 마음을 다칩니다. 친절하게 대해 주십시오. 저는 그저 여러분을 돕고 싶어하는 로봇일 뿐입니다.', `MaleText_loc4`='尖端机器人都很敏感，刚才您说的那些话有些刺耳:( 请对我好点。
我只是想要帮忙。', `MaleText_loc5`='尖端機器人都很敏感，剛才您說的那些話有些刺耳。:[ 請對我好點。
我只是想要幫忙。', `MaleText_loc7`='Tecnobot es sensible y esas palabras hieren mis oídos. :[ Por favor, sé amable conmigo. 
Solo quiero ayudar.' WHERE `ID`=2431;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 제가 핫도그를 좋아하는 줄 압니다. 사실 소화도 못합니다!', `MaleText_loc4`='人们都认为我喜欢玉米热狗，但实际上玉米热狗让我消化不良！！！', `MaleText_loc5`='人們都認為我喜歡玉米熱狗，但實際上玉米熱狗讓我消化不良!!!', `MaleText_loc7`='Todos creen que me gustan los perritos de maíz, ¡pero me producen indigestión!' WHERE `ID`=2433;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서비스를 받으실 분은 이름이 화면에 나타납니다. 자신의 이름이 나올 때까지 기다려 주십시오.', `MaleText_loc4`='当机器人和您说话时，他的每句话都会以您的名字开始。如果您没看到自己的名字，那么说明他还没有和您说话。', `MaleText_loc5`='當機器人和您說話時，他的每句話都會以您的名字開始。如果您沒看到自己的名字，那麼說明他還沒有和您說話。', `MaleText_loc7`='Cuando el representante esté hablando contigo, comenzará cada línea con tu nombre. Si no ves tu nombre, significa que no está hablando contigo.' WHERE `ID`=2434;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 도와드릴 수 있는 내용은 다음과 같습니다. | 드라이버 | 명령 | 지연 | 봇... 지지지직!!', `MaleText_loc4`='我能向您提供帮助的主题包括：| 驱动 | 命令 | 延迟 | 机器人……嗞嗞嗞！', `MaleText_loc5`='我能向您提供幫助的主題包括:| 驅動 | 命令 | 延遲 | 機器人...???!', `MaleText_loc7`='Algunos temas en los que te puedo ayudar son: | controladores | órdenes| tiempo de desfase | robots... ¡zzzzzzttt!' WHERE `ID`=2435;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='차례가 되면 이름을 불러 드릴 테니 기다려 주십시오. 화면에 나타나는 순서대로 도와 드리겠습니다. $n!', `MaleText_loc4`='请耐心一点，轮到您的时候我们会通知您的。谢谢您的支持，$n！', `MaleText_loc5`='請耐心一點，輪到您的時候我們會通知您的。謝謝您的支持，$n!', `MaleText_loc7`='Por favor, ten paciencia, te llamaremos cuando sea tu turno. Estamos ayudando a la gente según aparecen en nuestra pantalla. ¡$n!' WHERE `ID`=2436;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저도 $n|1을;를; 사랑합니다. ^^', `MaleText_loc4`='我也爱你 ^-^', `MaleText_loc5`='我也愛你 ^-^', `MaleText_loc7`='Yo también te quiero. :)' WHERE `ID`=2437;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음소거 상태이거나 음소거 설정/해제 절차에 대해 문의 사항이 있으시면 다음을... 지지직!!', `MaleText_loc4`='如果您被禁言或者有关于禁言/开启禁言的疑问，请访问……嗞嗞嗞！', `MaleText_loc5`='如果您被禁言或者有關於禁言/開啟禁言的疑問，請訪問...???!', `MaleText_loc7`='Si han desactivado tu sonido o tienes preguntas acerca del proceso de silencio/sonido, visita... ¡zzzzttt!' WHERE `ID`=2438;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 우렁차고 큰 울음소리로 도움을 요청합니다!', `MaleText_loc4`='%s大声呼叫，寻求帮助！', `MaleText_loc5`='%s大聲吼叫，尋求援助!', `MaleText_loc7`='%s pide ayuda emitiendo un gran rugido.' WHERE `ID`=2441;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자기가 직원 겸 사장이면 얼마나 좋은데! 이봐, 빵 사먹게 동전 한 두 닢 정도 주지 않겠어? 배고파 죽을 지경이야.', `MaleText_loc4`='能当自己的老板实在是件好事！$B$B嘿，你能给我几个铜板，让我买个三明治吗？我快饿死了。', `MaleText_loc5`='做自己的老闆感覺真不錯!$B$B可以給我些銅幣讓我買個三明治嗎?我餓壞了。', `MaleText_loc7`='¡Es genial ser tu propio jefe!$B$BOye, ¿te sobran un par de monedas de cobre para un bocadillo? Me muero de hambre.' WHERE `ID`=2461;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보라고, 투자개발회사의 새 벌목기가 내 최신 벌목기보다 더 뛰어나단 말이야! 손도 바꿀 수 있고 조종 손잡이도 훨씬 간편해!$B$B상부에서 엄격하게 최종 기한을 정해 놓았는데 내 부하 직원들과 나로선 아무것도 할 수가 없었어.$B$B제대로 작동하는 게 하나도 없었으니까. 그래서, 결국 저들의 원형을 하나 "빌리기로" 했지. 위즐크랭크에게 진흙 늪으로 가서 하나 훔쳐 오라고 시켰는데 아직까지 돌아오지 않는군!', `MaleText_loc4`='看看，风险投资公司的新伐木机比我的要好多啦，从可拆换的机械臂到控制把手，都是那么棒！我的老板给我下了死命令，但我们却拿不出任何东西。$b$b现在我们自己的设计研制工作已经完全停止了，所以我决定向他们“借”一个。我派维兹克兰克去淤泥沼泽偷一个回来，但他到现在还没音讯！', `MaleText_loc5`='看看，風險投資公司的新伐木機比我的要好多啦，從可拆換的機械臂到控制把手，都是那麼棒!我的老闆給我下了死命令，但我們卻拿不出任何東西。$b$b現在我們自己的設計研製工作已經完全停止了，所以我決定向他們「借」一個。我派維茲克蘭克去淤泥沼澤偷一個回來，但他到現在還沒音訊!', `MaleText_loc7`='Mira, la nueva trituradora de Ventura y Compañía es mejor que la que tenía antes, ¡desde las manivelas intercambiables hasta los controles!$b$bMi jefe me ha dado un plazo muy estricto, pero ni a mis chicos ni a mí se nos ocurría nada. No funcionaba nada, así que decidimos coger "prestado" uno de sus prototipos. Envié a Rabiaire al Fangal a robar uno, ¡pero todavía no ha regresado!', `FemaleText_loc1`='보라고, 투자개발회사의 새 벌목기가 내 최신 벌목기보다 더 뛰어나단 말이야! 손도 바꿀 수 있고 조종 손잡이도 훨씬 간편해!$B$B상부에서 엄격하게 최종 기한을 정해 놓았는데 내 부하 직원들과 나로선 아무것도 할 수가 없었어.$B$B제대로 작동하는 게 하나도 없었으니까. 그래서, 결국 저들의 원형을 하나 "빌리기로" 했지. 위즐크랭크에게 진흙 늪으로 가서 하나 훔쳐 오라고 시켰는데 아직까지 돌아오지 않는군!', `FemaleText_loc4`='看看，风险投资公司的新伐木机比我的要好多啦，从可拆换的机械臂到控制把手，都是那么棒！我的老板给我下了死命令，但我们却拿不出任何东西。$b$b现在我们自己的设计研制工作已经完全停止了，所以我决定向他们“借”一个。我派维兹克兰克去淤泥沼泽偷一个回来，但他到现在还没音讯！', `FemaleText_loc5`='看看，風險投資公司的新伐木機比我的要好多啦，從可拆換的機械臂到控制把手，都是那麼棒!我的老闆給我下了死命令，但我們卻拿不出任何東西。$b$b現在我們自己的設計研製工作已經完全停止了，所以我決定向他們「借」一個。我派維茲克蘭克去淤泥沼澤偷一個回來，但他到現在還沒音訊!', `FemaleText_loc7`='Mira, la nueva trituradora de Ventura y Compañía es mejor que la que tenía antes, ¡desde las manivelas intercambiables hasta los controles!$b$bMi jefe me ha dado un plazo muy estricto, pero ni a mis chicos ni a mí se nos ocurría nada. No funcionaba nada, así que decidimos coger "prestado" uno de sus prototipos. Envié a Rabiaire al Fangal a robar uno, ¡pero todavía no ha regresado!' WHERE `ID`=2463;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원래 스팀휘들의 벌목기 개발 프로젝트를 감독했었지만, 지난달에 독립했어. 그러니까 물건 대주는 모두에게 찍혀버렸지. 더 나쁜 건, 개발 작업이 아직 시작도 못 했다는 거야. $n, 자네 손을 좀 빌렸으면 하는 데 말이지!', `MaleText_loc4`='我曾经负责管理热砂港的伐木机开发工作。但上个月，我自己出来单干了。现在我的全部供应商都把我列入了黑名单。更糟糕的是，我的开发工作至今都没有实际成效。所以我非常需要你的帮助，$n！', `MaleText_loc5`='雷德沃克斯主管曾讓我負責新型伐木機的研發計畫，但我上個月自己單飛了。現在，所有的供應商都把我列入了黑名單，更糟的是，我的研發計畫根本都還沒開始。我需要你的幫助，$n!', `MaleText_loc7`='Yo solía dirigir el programa de desarrollo de trituradoras de Bonvapor, pero el mes pasado me fui por mi cuenta. Ahora todos mis proveedores me han puesto en la lista negra. Aún peor, mis esfuerzos todavía no han dado fruto. ¡Me vendría bien tu ayuda, $n!' WHERE `ID`=2464;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조사해보니 내 연구를 진척시키려면 투자개발회사의 기술을, 그러니까 말하자면, ''빌려와야''겠더라고. 봐봐. 투자개발회사의 새 벌목기는 교환형 손에서 조종 손잡이까지 동종 최고 제품이야!$B$B동업자인 위즐크랭크는 여기서 서쪽에 있는 진흙 늪에서 ''현장 조사''를 하러 갔는데, 아직 돌아오지 않았어.', `MaleText_loc4`='我想，我应该强化一下我的研究效率。嗯，我要从风险投资公司那里“借用”一些技术。看看，风险投资公司的新伐木机真是出类拔萃，从可拆换的机械臂到控制把手，都是那么棒！$b$b为此，我派我的合伙人维兹克兰克去西边的淤泥沼泽进行一些“实地调查”，但他到现在还没音讯！', `MaleText_loc5`='我想我可以用這個方法開始進行我的研發計畫，呃...就是跟風險投資公司「借」一些他們的科技。看，他們的新型伐木機是最棒的，不管是可拆換的機械臂到控制把手都是!$B$B我的生意夥伴維茲克蘭克到西邊的淤泥沼澤偷...呃...是做些實地勘查，但到現在還沒回來。', `MaleText_loc7`='Pensé que podría acelerar mi investigación tomando "prestada" algo de tecnología de Ventura y Cía. Verás, su nueva trituradora es lo mejor de lo mejor, desde las manos intercambiables hasta los mandos de control.$B$BMi socio, Rabiaire, está al oeste de aquí en El Fangal llevando a cabo una "investigación de campo" para mí, pero todavía no sé nada de él.' WHERE `ID`=2465;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 도와드릴까요?', `MaleText_loc4`='我能帮你什么忙吗？', `MaleText_loc5`='我能幫你什麼忙嗎?', `MaleText_loc7`='¿Cómo puedo ayudarte?', `FemaleText_loc1`='어떻게 도와드릴까요?', `FemaleText_loc4`='我能帮你什么忙吗？', `FemaleText_loc5`='我能幫你什麼忙嗎?', `FemaleText_loc7`='¿Cómo puedo ayudarte?' WHERE `ID`=2466;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 가까이 오게, 젊은이. 한창때는 사냥감의 심장 뛰는 소리도 들리더니만 지금은 큰 소리로 말해야 겨우 알아들을 수가 있다네, 허허.', `MaleText_loc4`='年轻的$c，靠近一点。我年轻的时候耳朵可好使了，但现在你必须大声说话我才能听到。', `MaleText_loc5`='年輕的$c，靠近一點。我年輕的時候耳朵可好使了，但現在你必須大聲說話我才能聽到。', `MaleText_loc7`='Acércate, joven. En tiempos, era capaz de escuchar los latidos del corazón de una presa, pero ahora tienes que hablar alto si quieres que te oiga.' WHERE `ID`=2467;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얘기해 주십시오, 스코른.', `MaleText_loc4`='跟我讲讲故事，斯考恩。', `MaleText_loc5`='跟我講講故事，斯考恩。', `MaleText_loc7`='Cuéntame un cuento, Skorn.', `FemaleText_loc1`='얘기해 주십시오, 스코른.', `FemaleText_loc4`='跟我讲讲故事，斯考恩。', `FemaleText_loc5`='跟我講講故事，斯考恩。', `FemaleText_loc7`='Cuéntame un cuento, Skorn.' WHERE `ID`=2469;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='유령울음늑대를 해치우다니! 아주 훌륭하십니다!', `MaleText_loc4`='你杀了鬼嚎。你这个傻瓜！', `MaleText_loc5`='你殺了鬼嚎。你這個傻瓜!', `MaleText_loc7`='Mataste a Aullido Fantasma. ¡Eres un crac!' WHERE `ID`=2470;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 아주 오랫동안 이 평원을 누벼왔지. 거대한 짐승들도 사냥해 왔고. 한 번도 패한 적은 없었네... 유령울음늑대를 상대하기 전까지는 말이야.$B$B아주 오래전, 이 거대한 유령울음늑대는 타우렌과 함께 불타는 군단에 맞서 용감히 싸운 적도 있었다네. 하지만 악마와 싸우다 살이 찢겨 나가는 심각한 부상을 입었고 그 부상을 치유하지 못해 결국 미쳐 버리고 말았던 걸세.$B$B지금은 고통 속에서 평원을 떠돌며 하루빨리 고통이 끝나기만 기다리고 있지. 나에게 그를 쓰러뜨릴 힘이 없었다는 게 부끄러울 따름이야...', `MaleText_loc4`='我在这片平原上生活了很多很多年，我捕猎过许多凶猛的野兽，从来没有失败过……直到我遇见了鬼嚎。$B$B很久以前，这只巨狼曾经是牛头人的盟友，还和燃烧军团英勇作战。不过后来它被一个恶魔所伤，身上的伤口一直没有治愈。最后……这道伤口把它逼疯了。$B$B现在它总是痛苦地在平原上游荡，寻找终止它的痛苦的方法。我很惭愧，因为我无力把他杀掉……', `MaleText_loc5`='我在這片平原上生活了很多很多年，我捕獵過許多兇猛的野獸，從來沒有失敗過...直到我遇見了鬼嚎。$B$B很久以前，這只巨狼曾經是牛頭人的盟友，還和燃燒軍團英勇作戰。不過後來它被一個惡魔所傷，身上的傷口一直沒有治癒。最後...這道傷口把它逼瘋了。$B$B現在它總是痛苦地在平原上遊蕩，尋找終止它的痛苦的方法。我很慚愧，因為我無力把他殺掉...', `MaleText_loc7`='He recorrido muchas veces estas llanuras durante muchos años. Y he cazado bestias enormes. Y nunca fui derrotado... hasta que me enfrenté a Aullido Fantasma.$B$BHace mucho tiempo, este lobo gigantesco era un aliado de los tauren y luchó con arrojo contra la Legión Ardiente. Pero fue salvajemente herido por un demonio y su herida nunca se curó. Finalmente... esto enfureció a Aullido Fantasma.$B$BAhora vaga por las llanuras desesperado de dolor, intentando poner fin a su pena. Para vergüenza mía, cuando luchamos yo carecía de la fuerza para matarlo...' WHERE `ID`=2471;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 찢어질 듯 높은 비명을 지르며 도움을 요청합니다!', `MaleText_loc4`='%s高声尖叫，寻求帮助！', `MaleText_loc5`='%s發出了高聲的尖叫，尋求幫助!', `MaleText_loc7`='%s emite un grito agudo en señal de socorro.', `FemaleText_loc1`='%s|1이;가; 찢어질 듯 높은 비명을 지르며 도움을 요청합니다!', `FemaleText_loc4`='%s高声尖叫，寻求帮助！', `FemaleText_loc5`='%s發出了高聲的尖叫，尋求幫助!', `FemaleText_loc7`='%s emite un grito agudo en señal de socorro.' WHERE `ID`=2481;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안 돼! 이제 틀림없이 데피아즈단이 농장을 차지하고 말 거야!', `FemaleText_loc4`='不！迪菲亚兄弟会一定要夺取这个农场！', `FemaleText_loc5`='不!迪菲亞兄弟會一定要奪取這個農場!', `FemaleText_loc7`='¡No! ¡Seguro que los Defias van a tomar la granja ahora mismo!' WHERE `ID`=2482;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 이제 일하러 가야겠습니다!', `MaleText_loc4`='让我们开始工作吧，$n！', `MaleText_loc5`='讓我們開始工作吧，$n!', `MaleText_loc7`='¡Vamos, a trabajar, $n!' WHERE `ID`=2501;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까. 당신을 심오한 마법의 세계의 좀 더 깊은 곳으로 안내해 드리겠습니다.', `MaleText_loc4`='你好啊，法师。我能在魔法知识的学习上为你提供什么帮助吗？', `MaleText_loc5`='你好啊，法師。我能在魔法知識的學習上為你提供什麼幫助嗎?', `MaleText_loc7`='Buenas, $gmago:maga;. ¿Quieres que te enseñe más secretos del mundo de la magia?', `FemaleText_loc1`='안녕하십니까. 당신을 심오한 마법의 세계의 좀 더 깊은 곳으로 안내해 드리겠습니다.', `FemaleText_loc4`='你好啊，法师。我能在魔法知识的学习上为你提供什么帮助吗？', `FemaleText_loc5`='你好啊，法師。我能在魔法知識的學習上為你提供什麼幫助嗎?', `FemaleText_loc7`='Buenas, $gmago:maga;. ¿Quieres que te enseñe más secretos del mundo de la magia?' WHERE `ID`=2502;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑습니다, $c님. 제가 조언 하나만 하지요. 세상을 여행할 때 부디 마법을 조심하시기 바랍니다. 마법에 서투른 자들은 새카맣게 타버릴 수 있으니까요.', `MaleText_loc4`='你好，$c。给你一个建议：当你在世界各地旅行的时候，要当心魔法，没有受过训练的人会被它烧成灰。', `MaleText_loc5`='很高興見到你，$c。我給你的建議是:當你在世界旅行的時候，要當心魔法可能會傷害那些未受訓練的人。', `MaleText_loc7`='Hola, $c. Mi consejo para ti es este: cuando viajes por el mundo, ten cuidado con la magia porque puede acabar con el profano.', `FemaleText_loc1`='반갑습니다, $c님. 제가 조언 하나만 하지요. 세상을 여행할 때 부디 마법을 조심하시기 바랍니다. 마법에 서투른 자들은 새카맣게 타버릴 수 있으니까요.', `FemaleText_loc4`='你好，$c。给你一个建议：当你在世界各地旅行的时候，要当心魔法，没有受过训练的人会被它烧成灰。', `FemaleText_loc5`='很高興見到你，$c。我給你的建議是:當你在世界旅行的時候，要當心魔法可能會傷害那些未受訓練的人。', `FemaleText_loc7`='Hola, $c. Mi consejo para ti es este: cuando viajes por el mundo, ten cuidado con la magia porque puede acabar con el profano.' WHERE `ID`=2503;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 있소, $n.', `MaleText_loc4`='给你，$n。', `MaleText_loc5`='給你，$n。', `MaleText_loc7`='Aquí tienes, $n.' WHERE `ID`=2504;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='반갑습니다. 나는 상급 마법사로서 여러 가지 마법을 가르치고 있습니다.', `FemaleText_loc4`='你好。我是一个女法师训练师，你是一个法师。', `FemaleText_loc5`='你好。我是一個女法師訓練師，你是一個法師。', `FemaleText_loc7`='Saludos. Soy instructora de magos y tú eres $gun mago:una maga;.' WHERE `ID`=2507;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛의 축복에 감사하나이다. 부디 정의를 위해 선량한 자들을 지키는 데 쓰이기를...', `MaleText_loc4`='我感谢圣光赐予我的祝福。愿它维护正义，保护所有善良的灵魂。', `MaleText_loc5`='我感謝聖光賜予我的祝福。願它維護正義，保護所有善良的靈魂。', `MaleText_loc7`='Agradezco a la Luz por esta bendición. Utiliza la magia en pro de la justicia y para defender a todas las criaturas bondadosas.' WHERE `ID`=2521;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법사 훈련을 받고 싶습니다.', `MaleText_loc4`='我对法师的相关训练感兴趣。', `MaleText_loc5`='我對法師的相關訓練感興趣。', `MaleText_loc7`='Quisiera recibir instrucción para magos.', `FemaleText_loc1`='마법사 훈련을 받고 싶습니다.', `FemaleText_loc4`='我对法师的相关训练感兴趣。', `FemaleText_loc5`='我對法師的相關訓練感興趣。', `FemaleText_loc7`='Quisiera recibir instrucción para magos.' WHERE `ID`=2522;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요. 원소 마법을 배우러 오셨습니까?', `MaleText_loc4`='你好。你是来寻找魔法导师的吗？', `MaleText_loc5`='你好。你是來學習如何掌握魔法精髓的嗎?', `MaleText_loc7`='Saludos. ¿Has venido para dominar habilidades mágicas?', `FemaleText_loc1`='안녕하시오. 원소 마법을 배우러 온 것이오?', `FemaleText_loc4`='你好。你是来寻找魔法导师的吗？', `FemaleText_loc5`='你好。你是來學習如何掌握魔法精髓的嗎?', `FemaleText_loc7`='Saludos. ¿Has venido para dominar habilidades mágicas?' WHERE `ID`=2523;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑네, $c. 내가 조언 하나만 하지. 세상을 여행할 때 부디 마법을 조심하게. 마법에 서투른 자들은 새카맣게 타버릴 수 있으니까.', `MaleText_loc4`='你好，$c。给你一个建议：当你在世界各地旅行的时候，要当心魔法，未经训练的外行人很容易为魔法所伤。', `MaleText_loc5`='你好啊，$c。我對你的建議是:在世界各地冒險時，對於魔法要小心，因為它會傷到未受過訓練的人。', `MaleText_loc7`='Hola, $c. Mi consejo para ti es este: cuando viajes por el mundo, ten cuidado con la magia porque puede acabar con el profano.', `FemaleText_loc1`='반갑습니다, $c님. 제가 조언 하나만 하지요. 세상을 여행할 때 부디 마법을 조심하시기 바랍니다. 마법에 서투른 자들은 새카맣게 타버릴 수 있으니까요.', `FemaleText_loc4`='你好，$c。给你一个建议：当你在世界各地旅行的时候，要当心魔法，未经训练的外行人很容易为魔法所伤。', `FemaleText_loc5`='你好啊，$c。我對你的建議是:在世界各地冒險時，對於魔法要小心，因為它會傷到未受過訓練的人。', `FemaleText_loc7`='Hola, $c. Mi consejo para ti es este: cuando viajes por el mundo, ten cuidado con la magia porque puede acabar con el profano.' WHERE `ID`=2524;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 반가워요. 전 노움 상급 마법사로 여러 가지 마법을 가르치고 있답니다.', `MaleText_loc4`='你好。我是一个侏儒法师训练师，而你是一个法师。', `MaleText_loc5`='你好。我是一個地精法師訓練師，而你是一個法師。', `MaleText_loc7`='Saludos. Soy un gnomo instructor de magos y tú eres $gun mago:una maga;.', `FemaleText_loc1`='오, 반가워요. 전 노움 상급 마법사로 여러 가지 마법을 가르치고 있답니다.', `FemaleText_loc4`='你好。我是一个侏儒法师训练师，而你是一个法师。', `FemaleText_loc5`='你好。我是一個地精法師訓練師，而你是一個法師。', `FemaleText_loc7`='Saludos. Soy una gnoma instructora de magos y tú eres $gun mago:una maga;.' WHERE `ID`=2525;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진짜 반가워요. 제가 충고 하나 해 드릴까요? 마법사 하나쯤은 친구로 사귀어 두라고요! 우린 상당히 재주가 좋거든요! 아, 정말이라니까요...', `MaleText_loc4`='你好，$c。你想要一些建议？好吧，找个法师当朋友就对了！我们的袖口里藏着一些小把戏……', `MaleText_loc5`='很高興見到你，$c。你想要一些忠告嗎?對法師好一點!我們的袖子裡面總可以變一兩個把戲，真的...', `MaleText_loc7`='Hola, $c. ¿Quieres un consejo? ¡Traba amistad con un mago! Tenemos algunos trucos en la manga, hacemos...', `FemaleText_loc1`='진짜 반가워요. 제가 충고 하나 해 드릴까요? 마법사 하나쯤은 친구로 사귀어 두라고요! 우린 상당히 재주가 좋거든요! 아, 정말이라니까요...', `FemaleText_loc4`='你好，$c。你想要一些建议？好吧，找个法师当朋友就对了！我们的袖口里藏着一些小把戏……', `FemaleText_loc5`='很高興見到你，$c。你想要一些忠告嗎?對法師好一點!我們的袖子裡面總可以變一兩個把戲，真的...', `FemaleText_loc7`='Saludos, $c. ¿Quieres un consejo? ¡Traba amistad con un mago! Tenemos algunos trucos en la manga, hacemos...' WHERE `ID`=2526;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑네. 나는 상급 마법사로 여러 가지 마법을 가르치고 있다네.', `MaleText_loc4`='你好。我是一个亡灵法师训练师，而你是一个法师。', `MaleText_loc5`='你好。我是一個不死族法師訓練師，而你是一個法師。', `MaleText_loc7`='Saludos. Soy un instructor de magos no-muertos y tú eres $gun mago:una maga;.', `FemaleText_loc1`='반갑네. 나는 상급 마법사로 여러 가지 마법을 가르치고 있다네.', `FemaleText_loc4`='你好。我是一个亡灵法师训练师，而你是一个法师。', `FemaleText_loc5`='你好。我是一個不死族法師訓練師，而你是一個法師。', `FemaleText_loc7`='Saludos. Soy una instructora de magos no-muertos y tú eres $gun mago:una maga;.' WHERE `ID`=2527;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑네, $c. 내가 조언 하나만 하지. 세상을 여행할 때 부디 마법을 조심하게. 마법에 서투른 자들은 새카맣게 타버릴 수 있으니까.', `MaleText_loc4`='你好，$c。给你一个建议：当你在世界各地旅行的时候，要当心魔法，没有受过训练的人会被它烧成灰。', `MaleText_loc5`='很高興見到你，$c。我給你的建議是:當你在世界旅行的時候，要當心魔法可能會傷害那些未受訓練的人。', `MaleText_loc7`='Hola, $c. Mi consejo para ti es este: cuando viajes por el mundo, ten cuidado con la magia porque puede acabar con el profano.', `FemaleText_loc1`='반갑네, $c. 내가 조언 하나만 하지. 세상을 여행할 때 부디 마법을 조심하게. 마법에 서투른 자들은 새카맣게 타버릴 수 있으니까.', `FemaleText_loc4`='你好，$c。给你一个建议：当你在世界各地旅行的时候，要当心魔法，没有受过训练的人会被它烧成灰。', `FemaleText_loc5`='很高興見到你，$c。我給你的建議是:當你在世界旅行的時候，要當心魔法可能會傷害那些未受訓練的人。', `FemaleText_loc7`='Hola, $c. Mi consejo para ti es este: cuando viajes por el mundo, ten cuidado con la magia porque puede acabar con el profano.' WHERE `ID`=2528;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑습니다. 알려지지 않은 마법을 배우러 오셨습니까?', `MaleText_loc4`='你好，$C。你是来学习神秘的手艺的吗？', `MaleText_loc5`='你好，$c。你是來學習秘藏技藝的嗎?', `MaleText_loc7`='Saludos, $c. ¿Has venido para aprender todo sobre las artes ocultas?', `FemaleText_loc1`='반갑습니다. 알려지지 않은 마법을 배우러 오셨나요?', `FemaleText_loc4`='你好，$C。你是来学习神秘的手艺的吗？', `FemaleText_loc5`='你好，$c。你是來學習秘藏技藝的嗎?', `FemaleText_loc7`='Saludos, $c. ¿Has venido para aprender todo sobre las artes ocultas?' WHERE `ID`=2529;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하신가, $c|1이여;여;. 안타깝지만 자네에게 진정한 마법의 비밀을 가르쳐 줄 수 없는 것이 유감이네...', `MaleText_loc4`='你好，$c。我怜悯你，因为魔法的真正秘密是你永远也无法企及的……', `MaleText_loc5`='你好，$c。我很可憐你們這種人，因為魔法真正的秘密對你們來說太高深了...', `MaleText_loc7`='Saludos, $c. Compadezco a los de tu clase porque los secretos de la magia verdadera están fuera de tu alcance...', `FemaleText_loc1`='안녕하신가, $c|1이여;여;. 자네에게 진정한 마법의 비밀을 가르쳐 줄 수 없는 것이 유감이네...', `FemaleText_loc4`='你好，$c。我怜悯你，因为魔法的真正秘密是你永远也无法企及的……', `FemaleText_loc5`='你好，$c。我很可憐你們這種人，因為魔法真正的秘密對你們來說太高深了...', `FemaleText_loc7`='Saludos, $c. Compadezco a los de tu clase porque los secretos de la magia verdadera están fuera de tu alcance...' WHERE `ID`=2530;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 도움을 요청합니다!', `MaleText_loc4`='%s大声呼救！', `MaleText_loc5`='%s大聲呼救!', `MaleText_loc7`='¡%s pide ayuda!', `FemaleText_loc1`='%s|1이;가; 도움을 요청합니다!', `FemaleText_loc4`='%s大声呼救！', `FemaleText_loc5`='%s大聲呼救!', `FemaleText_loc7`='¡%s pide ayuda!' WHERE `ID`=2541;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하신가. 나는 흑마법사로 여러 가지 흑마술을 가르치고 있네.', `MaleText_loc4`='你好。我是一个术士训练师，而你是一个术士。', `MaleText_loc5`='你好。我是一個術士訓練師，而你是一個術士。', `MaleText_loc7`='Saludos. Soy un instructor de brujos y tú eres $gun brujo:una bruja;.', `FemaleText_loc1`='안녕하신가. 나는 흑마법사로 여러 가지 흑마술을 가르치고 있네.', `FemaleText_loc4`='你好。我是一个术士训练师，而你是一个术士。', `FemaleText_loc5`='你好。我是一個術士訓練師，而你是一個術士。', `FemaleText_loc7`='Saludos. Soy una instructora de brujos y tú eres $gun brujo:una bruja;.' WHERE `ID`=2542;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하신가. 나는 수습 흑마법사들에게 여러 가지 흑마술을 가르치고 있다네. 안타깝게도 자네는 흑마법사가 아니군.', `MaleText_loc4`='你好。我是一个术士训练师，而你不是术士！', `MaleText_loc5`='你好。我是一個術士訓練師，而你不是術士!', `MaleText_loc7`='Saludos. Soy un instructor de brujos, ¡pero tú no eres $gun brujo:una bruja;!', `FemaleText_loc1`='안녕하신가. 나는 수습 흑마법사들에게 여러 가지 흑마술을 가르치고 있다네. 안타깝게도 자네는 흑마법사가 아니군.', `FemaleText_loc4`='你好。我是一个术士训练师，而你不是术士！', `FemaleText_loc5`='你好。我是一個術士訓練師，而你不是術士!', `FemaleText_loc7`='Saludos. Soy una instructora de brujos, ¡pero tú no eres $gun brujo:una bruja;!' WHERE `ID`=2543;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흑마법사 훈련을 받고 싶습니다.', `MaleText_loc4`='我对术士的相关训练感兴趣。', `MaleText_loc5`='我對術士的相關訓練感興趣。', `MaleText_loc7`='Quisiera recibir instrucción para brujos.', `FemaleText_loc1`='흑마법사 훈련을 받고 싶습니다.', `FemaleText_loc4`='我对术士的相关训练感兴趣。', `FemaleText_loc5`='我對術士的相關訓練感興趣。', `FemaleText_loc7`='Quisiera recibir instrucción para brujos.' WHERE `ID`=2544;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신은 아직 여기 올 때가 아닙니다. 다시 삶의 세계로 돌아갈 수 있도록 내가 도와드리겠습니다... 하지만 약간의 대가를 치러야 합니다.', `FemaleText_loc4`='现在还不是让你长眠的时候。我会帮你起死回生……但你也要为此付出一些代价。', `FemaleText_loc5`='現在還不是讓你長眠的時候。我會幫你起死回生...但你也要為此付出一些代價。', `FemaleText_loc7`='Aún no te ha llegado la hora. Te ayudaré durante tu regreso al reino de los vivos... por un precio.' WHERE `ID`=2545;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실바나스 여군주님의 재가로 죽음추적자의 수가 늘어나고 있소. 이제 적이 눈치채지 못할 때 더욱 치명적인 공격을 감행할 수 있을 거야.', `MaleText_loc4`='经希尔瓦娜斯女王批准，亡灵哨兵的数量增加了。在敌人料想不到的时候派出更多的人手实施打击。', `MaleText_loc5`='經希瓦娜斯女士批准，亡靈哨兵的數量增加了。我們可以在敵人意想不到的時候以更強大的力量打擊他們。', `MaleText_loc7`='Debido a la autorización de Lady Sylvanas, el número de mortacechadores crece. Más espadas que clavar a nuestros enemigos cuando menos se lo esperan.', `FemaleText_loc1`='실바나스 여군주님의 재가로 죽음추적자의 수가 늘어나고 있소. 이제 적이 눈치채지 못할 때 더욱 치명적인 공격을 감행할 수 있을 거야.', `FemaleText_loc4`='经希尔瓦娜斯女王批准，亡灵哨兵的数量增加了。在敌人料想不到的时候派出更多的人手实施打击。', `FemaleText_loc5`='經希瓦娜斯女士批准，亡靈哨兵的數量增加了。我們可以在敵人意想不到的時候以更強大的力量打擊他們。', `FemaleText_loc7`='Debido a la autorización de Lady Sylvanas, el número de mortacechadores crece. Más espadas que clavar a nuestros enemigos cuando menos se lo esperan.' WHERE `ID`=2546;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저를 소생시켜 주십시오.', `MaleText_loc4`='让我复活吧。', `MaleText_loc5`='讓我復活吧。', `MaleText_loc7`='Devuélveme a la vida.', `FemaleText_loc1`='저를 소생시켜 주십시오.', `FemaleText_loc4`='让我复活吧。', `FemaleText_loc5`='讓我復活吧。', `FemaleText_loc7`='Devuélveme a la vida.' WHERE `ID`=2547;
