UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아스토르라고 했소? 예까지 오느라 귀중한 시간을 소비했을 테니, 더는 시간 낭비하지 않는 것이 좋겠소.', `MaleText_loc4`='阿斯托？你来一趟真不容易啊，那我们就不要浪费时间了，好吧？', `MaleText_loc5`='阿斯托?你來一趟真不容易啊，那我們就不要浪費時間了，好吧?', `MaleText_loc7`='¿Astor? Te he hecho perder tu maldito tiempo para venir hasta aquí, así que no perdamos más el tiempo, ¿de acuerdo?' WHERE `ID`=2566;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음, 그걸 여기 어디다 넣어뒀더라...', `MaleText_loc4`='我刚才把哪个放进去了……', `MaleText_loc5`='我剛才把哪個放進去了...', `MaleText_loc7`='En cuál de estos lo metí...' WHERE `ID`=2567;
