UPDATE `locales_broadcast_text` SET `MaleText_loc1`='결국은 죄다 불게 될 텐데... 차라리 지금 털어놓는 게 어때?', `MaleText_loc4`='你终究是要说的，还不如现在就说了。', `MaleText_loc5`='你終究是要說的，還不如現在就說了。', `MaleText_loc7`='Finalmente hablarás. Puedes soltarlo ahora.', `FemaleText_loc1`='결국은 죄다 불게 될 텐데... 차라리 지금 털어놓는 게 어때?', `FemaleText_loc4`='你终究是要说的，还不如现在就说了。', `FemaleText_loc5`='你終究是要說的，還不如現在就說了。', `FemaleText_loc7`='Finalmente hablarás. Puedes soltarlo ahora.' WHERE `ID`=2569;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 나가고 싶으면 어서 자백하시지.', `MaleText_loc4`='坦白交待了，我们就放你走。', `MaleText_loc5`='坦白交代了，我們就放你走。', `MaleText_loc7`='Confiesa y te dejaremos en libertad.', `FemaleText_loc1`='여기서 나가고 싶으면 어서 자백하시지.', `FemaleText_loc4`='坦白交待了，我们就放你走。', `FemaleText_loc5`='坦白交代了，我們就放你走。', `FemaleText_loc7`='Confiesa y te dejaremos en libertad.' WHERE `ID`=2570;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐라고? 사실.. 난 자백 따위엔 관심이 없었어. 단지 고문을 즐길 뿐이지, 하하하.', `MaleText_loc4`='什么？哦，好吧，我不在乎你说什么。我只是喜欢这样。', `MaleText_loc5`='什麼?哦，好吧，我不在乎你說什麼。我只是喜歡虐待你。', `MaleText_loc7`='¿Qué? Oh, no, no me importa lo que tienes que decir. Solo disfruto haciendo daño.', `FemaleText_loc1`='뭐라고? 사실.. 난 자백 따위엔 관심이 없었어. 단지 고문을 즐길 뿐이지, 하하하.', `FemaleText_loc4`='什么？哦，好吧，我不在乎你说什么。我只是喜欢这样。', `FemaleText_loc5`='什麼?哦，好吧，我不在乎你說什麼。我只是喜歡虐待你。', `FemaleText_loc7`='¿Qué? Oh, no, no me importa lo que tienes que decir. Solo disfruto haciendo daño.' WHERE `ID`=2571;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까? 촉감이 좋은 로브를 찾으신다면 말씀만 하십시오.', `MaleText_loc4`='我是一个卖布的，这是我默认的见面打招呼的话。', `MaleText_loc5`='我是一個賣布的，這是我原始設定的見面打招呼的話。', `MaleText_loc7`='Soy vendedor de telas y este es mi saludo habitual.', `FemaleText_loc1`='안녕하세요? 촉감이 좋은 로브를 찾으신다면 말씀만 하세요.', `FemaleText_loc4`='我是一个卖布的，这是我常用的见面打招呼的话。', `FemaleText_loc5`='我是一個賣布的，這是我原始設定的見面打招呼的話。', `FemaleText_loc7`='Soy vendedora de telas y este es mi saludo habitual.' WHERE `ID`=2582;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물건을 구입하고 싶습니다.', `MaleText_loc4`='我想从你这里买点东西。', `MaleText_loc5`='我想從你這裡買點東西。', `MaleText_loc7`='Me gustaría comprarte algo.', `FemaleText_loc1`='물건을 구입하고 싶습니다.', `FemaleText_loc4`='我想从你这里买点东西。', `FemaleText_loc5`='我想從你這裡買點東西。', `FemaleText_loc7`='Me gustaría comprarte algo.' WHERE `ID`=2583;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑소. 난 위대한 포세이큰제 헝겊 방어구 상인이오. 찾는 물건이라도 있으신가?', `MaleText_loc4`='我是亡灵卖布商人，这是我的见面打招呼的话。', `MaleText_loc5`='我是亡靈賣布商人，這是我的見面打招呼的話。', `MaleText_loc7`='Soy vendedor de telas no-muerto y este es mi saludo habitual.', `FemaleText_loc1`='반가워요. 전 위대한 포세이큰제 헝겊 방어구 상인이지요. 찾는 물건이라도 있으신가요?', `FemaleText_loc4`='我是亡灵卖布商人，这是我的见面打招呼的话。', `FemaleText_loc5`='我是亡靈賣布商人，這是我的見面打招呼的話。', `FemaleText_loc7`='Soy vendedora de telas no-muerto y este es mi saludo habitual.' WHERE `ID`=2584;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하신가. 난 뛰어난 재봉사라네. 잘만 보이면 여러 가지 의복을 만드는 방법을 알려줄 수도 있지.', `MaleText_loc4`='欢迎你，请随意看看。除了味道有些诡异之外，我卖的东西都是最棒的。', `MaleText_loc5`='歡迎你，請隨意看看。除了味道有些詭異之外，我賣的東西都是最棒的。', `MaleText_loc7`='Te doy la bienvenida. Puedes examinar mis artículos con total libertad. Exceptuando su olor a moho, están en perfectas condiciones.', `FemaleText_loc1`='안녕하신가. 난 뛰어난 재봉사라네. 잘만 보이면 여러 가지 의복을 만드는 방법을 알려줄 수도 있지.', `FemaleText_loc4`='欢迎你，请随意看看。除了味道有些诡异之外，我卖的东西都是最棒的。', `FemaleText_loc5`='歡迎你，請隨意看看。除了味道有些詭異之外，我賣的東西都是最棒的。', `FemaleText_loc7`='Te doy la bienvenida. Puedes examinar mis artículos con total libertad. Exceptuando su olor a moho, están en perfectas condiciones.' WHERE `ID`=2585;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='재봉술을 배우고 싶습니다.', `MaleText_loc4`='我对裁缝技能的训练感兴趣。', `MaleText_loc5`='我對裁縫技能的訓練感興趣。', `MaleText_loc7`='Quisiera recibir instrucción para sastres.', `FemaleText_loc1`='재봉술을 배우고 싶습니다.', `FemaleText_loc4`='我对裁缝技能的训练感兴趣。', `FemaleText_loc5`='我對裁縫技能的訓練感興趣。', `FemaleText_loc7`='Quisiera recibir instrucción para sastres.' WHERE `ID`=2586;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하신가. 난 위대한 트롤의 재봉사로서 여러 가지 의복을 만드는 방법을 알려주고 있지.', `MaleText_loc4`='我是巨魔裁缝，这是我默认的见面打招呼的话。', `MaleText_loc5`='我是食人妖裁縫訓練師，這是我原始設定的見面打招呼的話。', `MaleText_loc7`='Soy instructor de sastres trol y este es mi saludo habitual.', `FemaleText_loc1`='안녕하신가. 난 위대한 트롤의 재봉사로서 여러 가지 의복을 만드는 방법을 알려주고 있지.', `FemaleText_loc4`='我是巨魔裁缝，这是我默认的见面打招呼的话。', `FemaleText_loc5`='我是食人妖裁縫訓練師，這是我原始設定的見面打招呼的話。', `FemaleText_loc7`='Soy instructora de sastres trol y este es mi saludo habitual.' WHERE `ID`=2587;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원하는 게 뭐요, $c? 난 너무 늦었다고. 내 고용주는 일 처리를 굼뜨게 하는 걸 절대 달가워하지 않을 거란 말이오.', `MaleText_loc4`='你要做什么，$c？我要迟到了，而我的雇主不喜欢拖沓。', `MaleText_loc5`='你要做什麼，$c?我快要遲到了，我的雇主不會給遲到的人好臉色看的。', `MaleText_loc7`='¿Qué deseas, $c? Llego tarde y a mi jefe no le gusta nada la impuntualidad.' WHERE `ID`=2588;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 아스토르 하드렌. 맞습니까?', `MaleText_loc4`='你是阿斯托·哈德恩，对吗？', `MaleText_loc5`='你是阿斯托·哈德恩，對嗎?', `MaleText_loc7`='Eres Astor Hadren, ¿verdad?', `FemaleText_loc1`='당신이 아스토르 하드렌. 맞습니까?', `FemaleText_loc4`='你是阿斯托·哈德恩，对吗？', `FemaleText_loc5`='你是阿斯托·哈德恩，對嗎?', `FemaleText_loc7`='Eres Astor Hadren, ¿verdad?' WHERE `ID`=2589;
