UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 내가 필요한 걸 가지고 있습니다, 아스토르. 이제 그걸 내가 취하게 될 겁니다.', `MaleText_loc4`='你有我所要的东西，阿斯托。我现在要拿走它。', `MaleText_loc5`='你有我所要的東西，阿斯托。我現在要拿走它。', `MaleText_loc7`='Tienes algo que necesito, Astor. Y me lo llevaré ahora.', `FemaleText_loc1`='당신은 내가 필요한 걸 가지고 있습니다, 아스토르. 이제 그걸 내가 취하게 될 겁니다.', `FemaleText_loc4`='你有我所要的东西，阿斯托。我现在要拿走它。', `FemaleText_loc5`='你有我所要的東西，阿斯托。我現在要拿走它。', `FemaleText_loc7`='Tienes algo que necesito, Astor. Y me lo llevaré ahora.' WHERE `ID`=2591;
