UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으악! 방금 뭐였지? 이러면 안 되는데!', `MaleText_loc4`='啊！那是什么？它不应该像这样运作的！', `MaleText_loc5`='啊!那是什麼?它不應該像這樣運作的!', `MaleText_loc7`='¡Argg! ¿Qué ha sido eso? ¡No tendría que funcionar así!' WHERE `ID`=2601;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으스러진 손은 영광스러웠던 호드의 시대를 열 것이다.', `MaleText_loc4`='碎手氏族将会见证部落重铸荣耀。', `MaleText_loc5`='破碎之手將會帶領部落重返昔日的榮耀。', `MaleText_loc7`='Los Mano Destrozada recuperarán la antigua gloria de la Horda.', `FemaleText_loc1`='으스러진 손은 영광스러웠던 호드의 시대를 열 것이다.', `FemaleText_loc4`='碎手氏族将会见证部落重铸荣耀。', `FemaleText_loc5`='破碎之手將會帶領部落重返昔日的榮耀。', `FemaleText_loc7`='Los Mano Destrozada recuperarán la antigua gloria de la Horda.' WHERE `ID`=2602;
