UPDATE `locales_broadcast_text` SET `MaleText_loc1`='메넷이 도둑 도구를 마련하기 위해선 당신에게 물어봐야 한다고 했습니다.', `MaleText_loc4`='米奈特说我应该向你要一套盗贼工具。', `MaleText_loc5`='米奈特說我應該向你要一套盜賊工具。', `MaleText_loc7`='Mennet me dijo que te pidiera un juego de herramientas para ladrones.', `FemaleText_loc1`='메넷이 도둑 도구를 마련하기 위해선 당신에게 물어봐야 한다고 했습니다.', `FemaleText_loc4`='米奈特说我应该向你要一套盗贼工具。', `FemaleText_loc5`='米奈特說我應該向你要一套盜賊工具。', `FemaleText_loc7`='Mennet me dijo que te pidiera un juego de herramientas para ladrones.' WHERE `ID`=2621;
