UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타락한 스컬지의 냄새가 나는군. 뒤틀린 황천에 갈 준비나 해라!', `MaleText_loc4`='你受到了天灾军团的污染。准备进入扭曲虚空。', `MaleText_loc5`='你身上有天譴軍團的邪惡氣息，準備墜入扭曲虛空吧!', `MaleText_loc7`='Tú llevas la peste de la Plaga. Prepárate para entrar en El Vacío Abisal.', `FemaleText_loc1`='타락한 스컬지의 냄새가 나는군. 뒤틀린 황천에 갈 준비나 해라!', `FemaleText_loc4`='你受到了天灾军团的污染。准备进入扭曲虚空。', `FemaleText_loc5`='你身上有天譴軍團的邪惡氣息，準備墜入扭曲虛空吧!', `FemaleText_loc7`='Tú llevas la peste de la Plaga. Prepárate para entrar en El Vacío Abisal.' WHERE `ID`=2625;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도망칠 곳은 없다! 붉은십자군은 타락한 스컬지 녀석들을 모두 없애버릴 것이다.', `MaleText_loc4`='你无处可逃。十字军将消灭所有携带天灾病毒的人。', `MaleText_loc5`='你是無法逃走的，十字軍將會清除被天譴軍團玷污過的一切。', `MaleText_loc7`='No tienes escapatoria. La Cruzada destruirá a todo aquel que lleve la peste de la Plaga.', `FemaleText_loc1`='도망칠 곳은 없다! 붉은십자군은 타락한 스컬지 녀석들을 모두 없애버릴 것이다.', `FemaleText_loc4`='你无处可逃。十字军将消灭所有携带天灾病毒的人。', `FemaleText_loc5`='你是無法逃走的，十字軍將會清除被天譴軍團玷污過的一切。', `FemaleText_loc7`='No tienes escapatoria. La Cruzada destruirá a todo aquel que lleve la peste de la Plaga.' WHERE `ID`=2626;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너같이 악을 일삼는 자는 빛의 심판을 받아 죽게 될 것이다!', `MaleText_loc4`='圣光将会惩罚所有心怀不轨的人。你死定了！', `MaleText_loc5`='聖光要懲罰所有邪惡的力量。立刻去死吧!', `MaleText_loc7`='La luz condena a todo aquel que alberga el mal. ¡Ahora morirás!', `FemaleText_loc1`='너같이 악을 일삼는 자는 빛의 심판을 받아 죽게 될 것이다!', `FemaleText_loc4`='圣光将会惩罚所有心怀不轨的人。你死定了！', `FemaleText_loc5`='聖光要懲罰所有邪惡的力量。立刻去死吧!', `FemaleText_loc7`='La luz condena a todo aquel que alberga el mal. ¡Ahora morirás!' WHERE `ID`=2627;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='붉은십자군은 사악한 자들을 쳐부수고, 이 땅에서 악마를 몰아낼 것이다!', `MaleText_loc4`='血色十字军将会消灭一切邪恶的力量，把它们彻底赶出这片领地！', `MaleText_loc5`='血色十字軍將會消滅一切邪惡的力量，把它們徹底趕出這片領地!', `MaleText_loc7`='¡La Cruzada Escarlata azotará al perverso y expulsará al demonio de estas tierras!', `FemaleText_loc1`='붉은십자군은 사악한 자들을 쳐부수고, 이 땅에서 악마를 몰아낼 것이다!', `FemaleText_loc4`='血色十字军将会消灭一切邪恶的力量，把它们彻底赶出这片领地！', `FemaleText_loc5`='血色十字軍將會消滅一切邪惡的力量，把它們徹底趕出這片領地!', `FemaleText_loc7`='¡La Cruzada Escarlata azotará al perverso y expulsará al demonio de estas tierras!' WHERE `ID`=2628;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 보주 안에 있는 악마는 잔인하기 그지없으니 조심하도록 하세요, $n.', `FemaleText_loc4`='别轻举妄动，$n，这颗宝珠中的恶魔是个相当可怕的野兽。', `FemaleText_loc5`='做好準備，$n，這顆寶珠中的惡魔是個非常可怕的野獸。', `FemaleText_loc7`='Prepárate, $n, ya que el demonio que hay en este orbe es una bestia maligna.' WHERE `ID`=2629;
