UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하하! 저주받은 아가만드에 영원한 언데드의 고통을!', `MaleText_loc4`='哈！被诅咒的阿加曼德家族变成了亡灵！', `MaleText_loc5`='哈!被詛咒的阿加曼德家族變成了亡靈!', `MaleText_loc7`='¡Ja! ¡Eterno no-muerto de los malditos Agamand!' WHERE `ID`=2631;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙습니다, $n. 덕분에 제 가슴 속의 차디찬 분노가 가라앉았습니다.', `MaleText_loc4`='谢谢你，$n。你平息了我心中的怒火。', `MaleText_loc5`='謝謝你，$n。你平息了我心中的怒火。', `MaleText_loc7`='Gracias, $n. Has aplacado la furia que consumía mi corazón.' WHERE `ID`=2632;
