UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 같은 젊은 $c|1이;가; 이 늙은 농부에겐 무슨 일로 오셨소?', `MaleText_loc4`='看啊，竟然有个年轻的$c来看像我这样的老农夫？', `MaleText_loc5`='看啊，竟然有個年輕的$c來看像我這樣的老農夫?', `MaleText_loc7`='¿Qué hace $gun:una; joven $c visitando a un viejo granjero como yo?' WHERE `ID`=2641;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='테르조크가 보낸 거라면, 아무리 사정해도 그를 위해 일하러 돌아가지 않겠다고 똑똑히 전하시오.', `MaleText_loc4`='如果是瑟祖克派你来的，那么告诉他死了这条心吧。我是不会回去为他工作的，不管他怎么求我。', `MaleText_loc5`='如果是瑟祖克派你來的，那麼告訴他死了這條心吧。我是不會回去為他工作的，不管他怎麼求我。', `MaleText_loc7`='Si te ha enviado Therzok dile que no, que nunca volveré a trabajar para él, da igual cuantas veces me lo pida.' WHERE `ID`=2642;
