UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하로크. $n에게 도둑 도구 한 상자를 갖다 주게.', `MaleText_loc4`='哈洛克，给$n一个工具盒。', `MaleText_loc5`='哈洛克，給$n一個工具盒。', `MaleText_loc7`='Harroc, trae una caja de herramientas para $n.' WHERE `ID`=2652;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠습니다, 로카르 님.', `MaleText_loc4`='快点，哈洛克。', `MaleText_loc5`='快點，哈洛克。', `MaleText_loc7`='Ahora mismo, Rokar.' WHERE `ID`=2653;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 있습니다. 게으름을 피운다고 로카르 님께 또 혼나기 전에 얼른 일하러 가봐야겠습니다. 그럼 이만!', `MaleText_loc4`='就这样吧。我要回去工作了，否则哈洛克又要埋怨我偷懒了。', `MaleText_loc5`='就這樣吧。我要回去工作了，否則哈洛克又要埋怨我偷懶了。', `MaleText_loc7`='Ya estás $glisto:lista;. Tengo que volver al trabajo antes de que Rokar me dé otra torta por estar vagueando.' WHERE `ID`=2654;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얘들아, 놈들을 처치해라!', `MaleText_loc4`='关门，放狗！', `MaleText_loc5`='關門，放狗!', `MaleText_loc7`='¡Suelten a los perros!' WHERE `ID`=2655;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='한가지 더 확인해 볼 게 있는데...', `FemaleText_loc4`='只剩一个环节要检查了……', `FemaleText_loc5`='只剩一個環節要檢查了...', `FemaleText_loc7`='Solo tengo que comprobar una cosa...' WHERE `ID`=2656;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='바로 이거로군! 드디어 성공했어요!', `FemaleText_loc4`='就是它了！成功了！', `FemaleText_loc5`='就是它了!成功了!', `FemaleText_loc7`='¡Eso es! ¡Ha funcionado!' WHERE `ID`=2657;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='끝까지 기다려줘서 고맙군요, $n.', `FemaleText_loc4`='谢谢你的耐心，$n。', `FemaleText_loc5`='謝謝你的耐心，$n。', `FemaleText_loc7`='Gracias por tu paciencia, $n.' WHERE `ID`=2658;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='필요할 때 쓸 수 있게 여기다 두도록 하죠...', `FemaleText_loc4`='我会一直把它留在这里，直到我们需要它……', `FemaleText_loc5`='我會一直把它留在這裡，直到我們需要它...', `FemaleText_loc7`='Mantendré esto aquí hasta que lo necesitemos...' WHERE `ID`=2659;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나랄렉스 님께서 또 잠이 드셨소!$B$B아주 오래전, 나랄렉스 님께서는 에메랄드의 꿈속으로 들어가 불모의 땅을 울창한 숲으로 만들겠다는 고귀한 뜻을 품고 이 동굴로 먼 길을 오셨소. 하지만 나랄렉스 님의 집중력이 약해지면서 뱀의 형상이 에메랄드의 꿈을 더럽히게 되었소.$B$B나랄렉스 님을 괴롭히는 그 파충류들이 이제는 이 땅까지 스며나오고 있소. 나랄렉스 님께서 악몽에서 깨어나지 않으면, 영원히 그분을 잃게 될 거요. 그러면 엄청난 악의 힘이 풀려나게 되겠지.$B$B나랄렉스 님을 반드시 깨워야 해! 하지만, 먼저 나랄렉스 님의 타락한 신하, 송곳니 군주들을 물리친 다음에야 그분을 깨우는 의식을 치를 수 있소.', `MaleText_loc4`='纳拉雷克斯又陷入了沉睡！$b$b很久以前，纳拉雷克斯曾满怀着进入翡翠梦境、让贫瘠之地重新变成茂密森林的伟大理想而来到了这处洞穴中。但他的执着却逐渐消退了，而他的思想也被脑海蜿蜒的影象所侵染。$b$b现在，那些奇怪的爬虫正从他的梦境中爬到这片土地上来，我们必须把他从梦魇中唤醒过来，否则他就将永远失落于其中，并继续给这片大地带来邪恶的力量！$b$b不过，只有杀死他那些堕落的仆人——毒牙之王，我才能开始进行唤醒仪式。', `MaleText_loc5`='納拉雷克斯又陷入了沉睡!$b$b很久以前，納拉雷克斯曾滿懷著進入翡翠夢境、讓貧瘠之地重新變成茂密森林的偉大理想而來到了這處洞穴中。但他的執著卻逐漸消退了，而他的思想也被腦海蜿蜒的幻象所侵染。$b$b現在，那些奇怪的爬蟲正從他的夢境中爬到這片土地上來，我們必須把他從夢魘中喚醒過來，否則他就將永遠失落於其中，並繼續給這片大地帶來邪惡的力量!$b$b不過，只有殺死他那些墮落的僕人─毒牙之王，我才能開始進行喚醒儀式。', `MaleText_loc7`='¡Naralex duerme nuevamente!$b$bHace tiempo, Naralex vino hasta esta caverna con el honorable fin de entrar en el Sueño Esmeralda y convertir los Baldíos en un bosque frondoso. Se le nubló la vista y sus pensamientos dieron paso a visiones serpenteantes.$b$bAhora, bestias reptiles descienden de sus sueños para penetrar en la tierra. Hay que despertarlo de la pesadilla o lo perderemos para siempre y se desatará un mal terrible.$b$bSolo después de matar a sus corruptos sirvientes, los Nobles del Colmillo, podré iniciar el ritual del despertar.' WHERE `ID`=2660;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='송곳니 군주들이 죽었소! 아직 희망이 모두 사라진 건 아니오! 하지만 자각의 의식은 꽤 복잡하여 혼자서는 할 수 없소.$B$B필요한 준비는 내가 모두 할 테니 당신은 나를 지켜주어야 하오. 에메랄드의 꿈을 통해 나랄렉스 님의 여행에서 소환된 몽마들은 상당히 위협적이오. 당신이 도와주지 않는다면 이 임무는 실패할 거요.$B$B나를 지켜줄 줄 준비가 되거든 말해주시오. 그러면 나랄렉스 님의 안식처로 안내하겠소.', `MaleText_loc4`='毒牙之王死了！我们还有希望！$b$b然而，整个唤醒仪式是非常复杂的，我无法独自完成它。$b$b我现在就开始着手完成所有必要的准备工作，但与此同时，我需要你保护好我。从纳拉雷克斯的噩梦中召唤出的怪物确实非常难缠。如果没有你的帮助，这个任务对我来说会非常可怕。$b$b当你准备好要保护我的时候，就过来跟我说一声，我会带你到纳拉雷克斯的房间去。', `MaleText_loc5`='毒牙之王死了!我們還有希望!$b$b然而，整個喚醒儀式是非常複雜的，我無法獨自完成它。$b$b我現在就開始著手完成所有必要的準備工作，但與此同時，我需要你保護好我。通過翡翠夢境，在納拉雷克斯的夢魘中召喚出的怪物確實非常難纏。如果沒有你的幫助，這個任務對我來說會非常可怕。$b$b當你準備好要保護我的時候，就過來跟我說一聲，我會帶你到納拉雷克斯的房間去。', `MaleText_loc7`='¡Los Nobles del Colmillo están muertos! ¡No se han perdido todas las esperanzas!$b$bNo obstante, el ritual del despertar es una tarea compleja. No puedo hacerlo solo.$b$bMe ocuparé de todos los preparativos necesarios, pero necesito que me protejas. Las pesadillas invocadas desde el viaje de Naralex por el Sueño Esmeralda han demostrado ser formidables. Sin tu ayuda, esta misión está condenada al fracaso.$b$bAvísame cuando estés $glisto:lista; para defenderme y yo te conduciré hacia la cámara de Naralex.' WHERE `ID`=2661;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='의식을 시작하겠소!', `MaleText_loc4`='活动开始了！', `MaleText_loc5`='活動開始了!', `MaleText_loc7`='¡Que empiece la sesión!', `FemaleText_loc1`='의식을 시작하겠소!', `FemaleText_loc4`='活动开始了！', `FemaleText_loc5`='活動開始了!', `FemaleText_loc7`='¡Que empiece la sesión!' WHERE `ID`=2662;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자, 보주를 만들어보도록 할까요?', `FemaleText_loc4`='好的，让我们来制作这颗宝珠吧……', `FemaleText_loc5`='好的，讓我們來製作這顆寶珠吧...', `FemaleText_loc7`='Vale, creemos este orbe...' WHERE `ID`=2663;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='됐어요. 드디어 완성됐군요!', `FemaleText_loc4`='好了。搞定了！', `FemaleText_loc5`='好了。搞定了!', `FemaleText_loc7`='De acuerdo. ¡Está lista!' WHERE `ID`=2664;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 로브를 만들겠습니다.', `MaleText_loc4`='我现在就开始制作长袍……', `MaleText_loc5`='我現在就開始製作長袍...', `MaleText_loc7`='Empezaré a crear la túnica...' WHERE `ID`=2665;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 당신의 로브가 완성되었습니다.', `MaleText_loc4`='你的长袍做好了，$n。', `MaleText_loc5`='你的長袍做好了，$n。', `MaleText_loc7`='Tu túnica está lista, $n.' WHERE `ID`=2666;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자, 이 탁자 위에서 속박의 상자와 현신의 주문서를 집으세요, $n. 임무를 수행하는 데 필요할 겁니다.', `FemaleText_loc4`='过来，$n。拿一根显形卷轴以及一盒封灵箱。你需要使用这些东西才能完成任务。', `FemaleText_loc5`='過來，$n。拿一根顯形卷軸以及一盒封靈箱。你需要使用這些東西才能完成任務。', `FemaleText_loc7`='Aquí tienes, $n. Coge este arcón con cofres de contención y un canto de manifestación. Los necesitarás para tu misión.' WHERE `ID`=2681;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n, 속박의 상자와 현신의 주문서를 받으세요. 임무를 수행하는 데 필요할 겁니다.', `FemaleText_loc4`='过来，$n。拿一根显形卷轴以及一盒封灵箱。你需要使用这些东西才能完成任务。', `FemaleText_loc5`='過來，$n。拿一根顯形卷軸以及一盒封靈箱。你需要使用這些東西才能完成任務。', `FemaleText_loc7`='Coge este arcón con cofres de contención y un canto de manifestación, $n. Los necesitarás para tu misión.' WHERE `ID`=2682;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 다듬어진 나무판자를 내려놓습니다.', `MaleText_loc4`='%s把精制的厚木板放了下来。', `MaleText_loc5`='%s把精製的厚木板放了下來。', `MaleText_loc7`='%s coloca las tablas de madera lisa en el suelo.' WHERE `ID`=2701;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기계가 이쪽을 돌아봅니다.$B$B기계 뒷면에는 이상한 형태로 뒤틀린 홈이 있고 ''겔카크 자이로마스트 선장의 물건''이라는 글귀가 새겨져 있습니다.', `MaleText_loc4`='机器转过来面对着你。$B$B它的背后有一个奇怪的凹槽，上面刻着一行字：“基尔卡克·旋杆的财产”', `MaleText_loc5`='機器調整了一下，面對著你。$B$B它的背後是空的，但是有一個奇怪的凹槽，上面寫著:「基爾卡克·旋杆的財產」', `MaleText_loc7`='La máquina se ajusta a tu altura.$B$BEn la parte trasera de la máquina encontrarás una ranura deforme con el siguiente rótulo grabado: "Propiedá del capitán Gelkak Gyromast"' WHERE `ID`=2702;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='열쇠를 돌려 기계를 작동합니다.', `MaleText_loc4`='转动钥匙，启动了机器。', `MaleText_loc5`='轉動鑰匙，啟動了機器。', `MaleText_loc7`='Gira la llave para poner en marcha la máquina.', `FemaleText_loc1`='열쇠를 돌려 기계를 작동합니다.', `FemaleText_loc4`='转动钥匙，启动了机器。', `FemaleText_loc5`='轉動鑰匙，啟動了機器。', `FemaleText_loc7`='Gira la llave para poner en marcha la máquina.' WHERE `ID`=2703;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끄아악! 바보 같으니라고! 무슨 짓을 한 거야?! 저 녀석 미쳤군! 해치를 닫아라! 돛대를 올려! 아아아악! 모두 자기 위치로!', `MaleText_loc4`='啊呀！你都干了些什么？他疯了！快关上舱门！把操纵杆往上拉！啊啊啊啊啊！赶快！', `MaleText_loc5`='啊呀!你都幹了些什麼?他瘋了!快關上艙門!把操縱杆往上拉!啊啊啊啊啊!趕快!', `MaleText_loc7`='¡YARRR! ¡¿Swabie, qué has hecho?! ¡Se ha vuelto loco! ¡Preparaos para la tormenta! ¡Izad el mástil! ¡ARRRR! ¡Cada uno que se las arregle como pueda!' WHERE `ID`=2704;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 "씩씩이" 존슨이라고 하오. 만나서 반갑소이다.', `MaleText_loc4`='我是“勇敢的”约翰森，这是我默认见面打招呼的话。', `MaleText_loc5`='我是大膽的強森，這是我原始設定見面打招呼的話。', `MaleText_loc7`='Soy Johnson el "Desplumado" y este es mi saludo habitual.' WHERE `ID`=2705;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이보시오! 틸스의 심부름을 온 거요? 내가 당신이라면 그자를 가까이하지 않을 거요. 술에 절어 제정신이 아니지... 하지만 마법만은 여전히 강력하다오!', `MaleText_loc4`='嘿！你在为提尔斯干活吗？如果我是你的话，我会离他远远的！酒精把他的大脑麻痹了，但是他的魔法还是和以前一样厉害！', `MaleText_loc5`='嘿!你在為提爾斯幹活嗎?如果我是你的話，我會離他遠遠的!酒精把他的大腦麻痺了，但是他的魔法還是和以前一樣厲害!', `MaleText_loc7`='¡Eh! ¿Estás haciéndole un recado a Tirth? ¡Yo, en tu lugar, me alejaría de él todo lo que pudiera! ¡Sus neuronas están embriagadas con tanto alcohol, pero su magia sigue tan poderosa como siempre!' WHERE `ID`=2706;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='틸스의 금고를 여는 주문을 알려주십시오.', `MaleText_loc4`='告诉我提尔斯保险箱的密码。', `MaleText_loc5`='告訴我提爾斯帶鎖箱的密碼。', `MaleText_loc7`='Dime una frase para abrir la caja fuerte de Tirth.', `FemaleText_loc1`='틸스의 금고를 여는 주문을 알려주십시오.', `FemaleText_loc4`='告诉我提尔斯保险箱的密码。', `FemaleText_loc5`='告訴我提爾斯帶鎖箱的密碼。', `FemaleText_loc7`='Dime una frase para abrir la caja fuerte de Tirth.' WHERE `ID`=2707;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뒤로 물러서세요... 그리고 숨을 참으세요. 난 이 의식을 오랫 동안 하지 못했답니다.', `FemaleText_loc4`='往后站一点……摒住呼吸。我很久没这么做过了。', `FemaleText_loc5`='往後站一點...摒住呼吸。我很久沒這麼做過了。', `FemaleText_loc7`='Retrocede y... aguanta la respiración. Hace mucho tiempo que no hago esto.' WHERE `ID`=2708;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='의식이 끝났어요! 정말 멋져요! 아직 내 실력이 줄지는 않은 것 같군요...', `FemaleText_loc4`='成功了！真让人惊讶……', `FemaleText_loc5`='成功了!真讓人驚訝...', `FemaleText_loc7`='¡Ha funcionado! ¡Sorprendente! Creo que no he perdido mis habilidades...' WHERE `ID`=2709;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋소. 말해 주겠소. 대신 나를 틸스에게 데려가지 않는다면 말이오!', `MaleText_loc4`='当然了，我会告诉你密码的。只要你不让提尔斯抓到我就行了！', `MaleText_loc5`='當然了，我會告訴你密碼的。只要你不讓提爾斯抓到我就行了!', `MaleText_loc7`='Claro, te diré la frase. ¡Siempre y cuando no tenga que acercarme a Tirth!' WHERE `ID`=2721;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='틸스에게 내가 여기 있더라고 말하지 마시오. 아직까지 소금 평원을 떠나지 않았다는 걸 알면 난 평생을 그 인간 잔심부름에다 빨래나 하면서 살게 될 거야!', `MaleText_loc4`='不要告诉提尔斯我还在这里。如果他发现我还没离开闪光平原，我就要永远帮他洗衣服了！', `MaleText_loc5`='不要告訴提爾斯我還在這裡。如果他發現我還沒離開閃光平原，我就要永遠幫他洗衣服了!', `MaleText_loc7`='No le digas a Tirth que sigo aquí. Si se da cuenta que no me he ido del Desierto de Sal, ¡tendré que hacerle los recados y lavar su ropa para siempre!' WHERE `ID`=2722;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겔카크의 열쇠를 빈 홈에 넣으니 꼭 들어맞습니다.', `MaleText_loc4`='基尔卡克的钥匙滑到了缝隙中。', `MaleText_loc5`='基爾卡克的鑰匙滑到了縫隙中。', `MaleText_loc7`='La llave de Gelkak se desliza por la ranura vacía.' WHERE `ID`=2741;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='철 족쇄에 묶여 꼼짝도 못하는 나를 조롱하는 것인가?', `MaleText_loc4`='当我因为绑着这个大铁球而不能保护自己的时候，你会嘲笑我吗？', `MaleText_loc5`='當我因為綁著這個大鐵球而不能保護自己的時候，你會嘲笑我嗎?', `MaleText_loc7`='¿Te burlas de mí ahora que no puedo defenderme, atado a esta bola de hierro?' WHERE `ID`=2742;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 하면 자유로워질 수 있습니까?', `MaleText_loc4`='我怎样才能释放你？', `MaleText_loc5`='我怎樣才能釋放你?', `MaleText_loc7`='¿Cómo puedo liberarte?', `FemaleText_loc1`='어떻게 하면 자유로워질 수 있습니까?', `FemaleText_loc4`='我怎样才能释放你？', `FemaleText_loc5`='我怎樣才能釋放你?', `FemaleText_loc7`='¿Cómo puedo liberarte?' WHERE `ID`=2743;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='인간 중 한 명에게 이 고약한 장치의 열쇠가 있소. 여기 있는 자들이 그를 에스턴이라고 부르는 것 같더군.', `MaleText_loc4`='有个人类手中有能打开这个装置的钥匙。我想他的名字叫埃斯顿。', `MaleText_loc5`='有個人類手中有能打開這個裝置的鑰匙。我想他的名字叫埃斯頓。', `MaleText_loc7`='Uno de los humanos tiene la llave de este artilugio infernal. Creo haber escuchado que su nombre era Eston.' WHERE `ID`=2744;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 나가시오, $c 친구. 아니면 저들이 당신을 족쇄로 묶어버릴 거요.', `MaleText_loc4`='从这里离开，$c，不然他们也会把你锁住的。', `MaleText_loc5`='從這裡離開，$c，不然他們也會把你鎖住的。', `MaleText_loc7`='Sal de aquí, $c, o también te encadenarán a ti.' WHERE `ID`=2745;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 족쇄를 푸는 열쇠는 어디에 있습니까?', `MaleText_loc4`='这把锁的钥匙呢？', `MaleText_loc5`='這把鎖的鑰匙呢?', `MaleText_loc7`='¿Dónde está la llave de esta cerradura?', `FemaleText_loc1`='이 족쇄를 푸는 열쇠는 어디에 있습니까?', `FemaleText_loc4`='这把锁的钥匙呢？', `FemaleText_loc5`='這把鎖的鑰匙呢?', `FemaleText_loc7`='¿Dónde está la llave de esta cerradura?' WHERE `ID`=2746;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말겐... 교도관 중에 한 명이지. 그 녀석에게 내 족쇄 열쇠가 있소.', `MaleText_loc4`='玛尔根……他是一个狱卒。他应该有那把钥匙。', `MaleText_loc5`='瑪爾根...他是一個獄卒。他應該有那把鑰匙。', `MaleText_loc7`='Marlgen... uno de los carceleros. Él tiene la llave de mis grilletes.' WHERE `ID`=2747;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엘윈의 시민이여, 반갑습니다. 제가 도와드릴 일이 있습니까?', `MaleText_loc4`='你好，我能帮你什么忙吗？', `MaleText_loc5`='你好，我能幫你什麼忙嗎?', `MaleText_loc7`='Buenos días, $gciudadano:ciuidadana;. ¿Cómo puedo ayudarte?', `FemaleText_loc1`='엘윈의 시민이여, 반갑습니다. 제가 도와드릴 일이 있습니까?', `FemaleText_loc4`='你好，我能帮你什么忙吗？', `FemaleText_loc5`='你好，我能幫你什麼忙嗎?', `FemaleText_loc7`='Buenos días, $gciudadano:ciuidadana;. ¿Cómo puedo ayudarte?' WHERE `ID`=2748;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드 은행', `MaleText_loc4`='暴风城银行', `MaleText_loc5`='暴風城銀行', `MaleText_loc7`='Banco de Ventormenta', `FemaleText_loc1`='스톰윈드 은행', `FemaleText_loc4`='暴风城银行', `FemaleText_loc5`='暴風城銀行', `FemaleText_loc7`='Banco de Ventormenta' WHERE `ID`=2749;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은행은 성문의 북서쪽 상업 지구에 있습니다. 지도를 통해 위치를 알려드리겠습니다.', `MaleText_loc4`='银行坐落在贸易区，就在城门的西北面。来，让我在地图上指给你看。', `MaleText_loc5`='暴風城銀行坐落在貿易區，就在城門的西北面。來，讓我在地圖上指給你看。', `MaleText_loc7`='El banco está ubicado en el Distrito de Mercaderes, exactamente al noroeste de las puertas de la ciudad. Mira, te lo muestro en el mapa.', `FemaleText_loc1`='은행은 성문의 북서쪽 상업 지구에 있습니다. 지도를 통해 위치를 알려드리겠습니다.', `FemaleText_loc4`='银行坐落在贸易区，就在城门的西北面。来，让我在地图上指给你看。', `FemaleText_loc5`='暴風城銀行坐落在貿易區，就在城門的西北面。來，讓我在地圖上指給你看。', `FemaleText_loc7`='El banco está ubicado en el Distrito de Mercaderes, exactamente al noroeste de las puertas de la ciudad. Mira, te lo muestro en el mapa.' WHERE `ID`=2750;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='던 모로에 쌓인 눈이 모두 녹아 없어져 버렸으면 좋겠다오. 항상 내 로브 자락을 적실뿐더러 모든 걸 지저분하게 만든단 말이지!', `MaleText_loc4`='我希望雪融化掉。它总是把我的长袍弄湿，把一切都搞得乱糟糟的！', `MaleText_loc5`='我希望雪融化掉。它總是把我的長袍弄濕，把一切都搞得亂糟糟的!', `MaleText_loc7`='Espero que la nieve se haya derretido ya. ¡Siempre moja mi túnica y lo ensucia todo!' WHERE `ID`=2751;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이고, 지겨운 눈 같으니... 거기, 당신 $n 아니신가? 당신에게 전할 말이 있다오.', `MaleText_loc4`='该死的雪……哦，你是……$n，是吗？刚刚还有人跟我打听你的事情呢。', `MaleText_loc5`='該死的雪...哦，你是...$n，是嗎?剛剛還有人跟我打聽你的事情呢。', `MaleText_loc7`='Qué pesadez de nieve... Oye, tú eres, $n, ¿verdad? Acabo de recibir un mensaje en el que preguntaban por ti.' WHERE `ID`=2752;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전할 말이 무엇입니까?', `MaleText_loc4`='什么消息？', `MaleText_loc5`='什麼消息?', `MaleText_loc7`='¿Qué mensaje?', `FemaleText_loc1`='전할 말이 무엇입니까?', `FemaleText_loc4`='什么消息？', `FemaleText_loc5`='什麼消息?', `FemaleText_loc7`='¿Qué mensaje?' WHERE `ID`=2753;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이언포지의 최고 흑마법사이신 라고 블랙렌치께서 당신을 찾고 계시오. 즉시 그분께 가서 보고를 드리는 게 좋겠소. 아이언포지의 쓸쓸한 뒷골목에 가면 그분을 만날 수 있을 거요.', `MaleText_loc4`='铁炉堡的术士拉戈·黑钳在找你，你要立刻到他那里向他报告。你可以在铁炉堡的荒弃的洞穴里找到他。', `MaleText_loc5`='鐵爐堡的術士拉戈·黑鉗在找你，你要立刻到他那裡向他報告。你可以在鐵爐堡的荒棄的洞穴裡找到他。', `MaleText_loc7`='Has sido invocado por Yago Llavenegra, maestro de brujos de Forjaz. Harías bien en presentarte ante él inmediatamente. Lo encontrarás en el distrito Caverna Abandonada de esta ciudad.' WHERE `ID`=2754;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$C|1이여;여;, 만나서 반갑소. 나는 타나리운 트리텐더라 하오.', `MaleText_loc4`='你好，$c，我是萨纳瑞恩·绿树。', `MaleText_loc5`='你好，$R，我是薩納瑞恩·綠樹。', `MaleText_loc7`='Saludos, $r, soy Tharnariun Espinarbolado.' WHERE `ID`=2755;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련이 필요합니다.', `MaleText_loc4`='我要接受训练。', `MaleText_loc5`='我要接受訓練。', `MaleText_loc7`='Necesito instrucción.', `FemaleText_loc1`='훈련이 필요합니다.', `FemaleText_loc4`='我要接受训练。', `FemaleText_loc5`='我要接受訓練。', `FemaleText_loc7`='Necesito instrucción.' WHERE `ID`=2756;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곰이 당황한 것 같이 보입니다.', `MaleText_loc4`='这只动物看上去有点困惑。', `MaleText_loc5`='這隻動物看起來有點困惑。', `MaleText_loc7`='Los animales parecen confusos.' WHERE `ID`=2757;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이걸 꿰매는 동안 잠시만 기다려주십시오...', `MaleText_loc4`='稍等片刻，我要把这些缝在一起……', `MaleText_loc5`='稍等片刻，我要把這些縫在一起...', `MaleText_loc7`='Un momento, mientras coso esto...' WHERE `ID`=2761;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='됐어요, $n. 로브가 완성되었습니다.', `MaleText_loc4`='嗯，你的长袍做完了，$n。', `MaleText_loc5`='嗯，你的長袍做完了，$n。', `MaleText_loc7`='Ya está. He terminado tu túnica, $n.' WHERE `ID`=2762;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; $n에게 귓속말을 합니다.', `MaleText_loc4`='%s对$n窃窃私语。', `MaleText_loc5`='%s對$n竊竊私語。', `MaleText_loc7`='%s susurra algo en el oído de $n.' WHERE `ID`=2763;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앞으로 경주를 어떻게 예상하느냐고요? 물론 우리 고블린이 한 발 앞서 있죠. 멋진 도구와 뛰어난 재능이 있으니까요!', `MaleText_loc4`='如果你问我，那我要说，地精的科技更加先进。我们有工具，我们还有天赋！', `MaleText_loc5`='如果你問我，那我要說，哥布林的科技更加先進。我們有工具，我們還有天賦!', `MaleText_loc7`='Si me preguntas, creo que los goblins son los mejores. ¡Tenemos las herramientas y tenemos el talento!', `FemaleText_loc1`='앞으로 경주를 어떻게 예상하느냐고요? 물론 우리 고블린이 한 발 앞서 있죠. 멋진 도구와 뛰어난 재능이 있으니까요!', `FemaleText_loc4`='如果你问我，那我要说，地精的科技更加先进。我们有工具，我们还有天赋！', `FemaleText_loc5`='如果你問我，那我要說，哥布林的科技更加先進。我們有工具，我們還有天賦!', `FemaleText_loc7`='Si me preguntas, creo que los goblins son los mejores. ¡Tenemos las herramientas y tenemos el talento!' WHERE `ID`=2764;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노움들의 그 빌어먹을 행운만 아니라면 절대 우리를 이기지 못할 거예요!', `MaleText_loc4`='要不是侏儒的狗屎运，他们就永远不会赢！', `MaleText_loc5`='要不是地精的狗屎運，他們就永遠不會贏!', `MaleText_loc7`='¡Si no fuera por la maldita suerte de los gnomos, jamás ganarían una carrera!', `FemaleText_loc1`='노움들의 그 빌어먹을 행운만 아니라면 절대 우리를 이기지 못할 거예요!', `FemaleText_loc4`='要不是侏儒的狗屎运，他们就永远不会赢！', `FemaleText_loc5`='要不是地精的狗屎運，他們就永遠不會贏!', `FemaleText_loc7`='¡Si no fuera por la maldita suerte de los gnomos, jamás ganarían una carrera!' WHERE `ID`=2765;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나라면 고블린 상품 교환권을 사겠어요. 다른 팀에 거는 건 생돈 날리는 일이라고요.', `MaleText_loc4`='如果我是你，我就赌地精赢。压其他车队都是在浪费时间。', `MaleText_loc5`='如果我是你，我就賭哥布林贏。壓其他車隊都是在浪費時間。', `MaleText_loc7`='Yo en tu lugar, compraría un vale de carreras para goblins. Animar al otro equipo constituye una pérdida de tiempo.', `FemaleText_loc1`='나라면 고블린 상품 교환권을 사겠어요. 다른 팀에 거는 건 생돈 날리는 일이라고요.', `FemaleText_loc4`='如果我是你，我就赌地精赢。压其他车队都是在浪费时间。', `FemaleText_loc5`='如果我是你，我就賭哥布林贏。壓其他車隊都是在浪費時間。', `FemaleText_loc7`='Yo, en tu lugar, compraría un vale de carreras para goblins. Animar al otro equipo constituye una pérdida de tiempo.' WHERE `ID`=2766;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 우리 고블린이 이긴다에 전 재산을 걸겠어요! 당신도 생각이 있다면 나처럼 하겠지요?', `MaleText_loc4`='我已经把钱压在地精身上了！如果你够聪明的话也应该赌地精获胜！', `MaleText_loc5`='我已經把錢壓在哥布林身上了!如果你夠聰明的話也應該賭哥布林獲勝!', `MaleText_loc7`='¡He apostado dinero por los goblins! ¡Y si tienes algo de sentido común, deberías apostar por ellos también!', `FemaleText_loc1`='난 우리 고블린이 이긴다에 전 재산을 걸겠어요! 당신도 생각이 있다면 나처럼 하겠지요?', `FemaleText_loc4`='我已经把钱压在地精身上了！如果你够聪明的话也应该赌地精获胜！', `FemaleText_loc5`='我已經把錢壓在哥布林身上了!如果你夠聰明的話也應該賭哥布林獲勝!', `FemaleText_loc7`='¡He apostado dinero por los goblins! ¡Y si tienes algo de sentido común, deberías apostar por ellos también!' WHERE `ID`=2767;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음 경주에서는 노움의 차를 날려버릴 거라고 그러더군요! 농담이든 진담이든 간에 나 같으면 멀찌감치 떨어져 있을 거예요.', `MaleText_loc4`='我听说下一场比赛的时候他们要把地精的车炸掉！不管是真是假，我会待在安全的地方。', `MaleText_loc5`='我聽說下一場比賽的時候他們要把地精的車炸掉!不管是真是假，我會待在安全的地方。', `MaleText_loc7`='¡He oído que iban a intentar hacer estallar el coche de los gnomos en la siguiente carrera! Sea esto verdad o no, yo me mantendría alejado de sus boxes.', `FemaleText_loc1`='다음 경주에서는 노움의 차를 날려버릴 거라고 그러더군요! 농담이든 진담이든 간에 나 같으면 멀찌감치 떨어져 있을 거예요.', `FemaleText_loc4`='我听说下一场比赛的时候他们要把地精的车炸掉！不管是真是假，我会待在安全的地方。', `FemaleText_loc5`='我聽說下一場比賽的時候他們要把地精的車炸掉!不管是真是假，我會待在安全的地方。', `FemaleText_loc7`='¡He oído que iban a intentar hacer estallar el coche de los gnomos en la siguiente carrera! Sea esto verdad o no, yo me mantendría alejado de sus boxes.' WHERE `ID`=2768;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='틸스의 조수는 어디 있습니까?', `MaleText_loc4`='提尔斯的助手在哪里？', `MaleText_loc5`='提爾斯的助手在哪裡?', `MaleText_loc7`='¿Dónde está el asistente de Tirth?', `FemaleText_loc1`='틸스의 조수는 어디 있습니까?', `FemaleText_loc4`='提尔斯的助手在哪里？', `FemaleText_loc5`='提爾斯的助手在哪裡?', `FemaleText_loc7`='¿Dónde está el asistente de Tirth?' WHERE `ID`=2769;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 존슨 말입니까? 어딘가 숨어있다고 들었는데...', `MaleText_loc4`='哦，你说的是约翰森？我听说他躲起来了。', `MaleText_loc5`='哦，你說的是強森?我聽說他躲起來了。', `MaleText_loc7`='¿Te refieres a Johnson? Creo que se ha escondido.', `FemaleText_loc1`='아, 존슨 말입니까? 어딘가 숨어있다고 들었는데...', `FemaleText_loc4`='哦，你说的是约翰森？我听说他躲起来了。', `FemaleText_loc5`='哦，你說的是強森?我聽說他躲起來了。', `FemaleText_loc7`='¿Te refieres a Johnson? Creo que se ha escondido.' WHERE `ID`=2773;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고블린 녀석들의 그 믿을 수 없는 행운만 아니었으면 경주 때마다 차가 완전히 박살났을 텐데!', `MaleText_loc4`='要不是地精的狗屎运，他们每次都会把车撞进山里去！', `MaleText_loc5`='要不是哥布林的狗屎運，他們每次都會把車撞進山裡去!', `MaleText_loc7`='¡Si no fuera por la increíble y estúpida suerte de los goblins se habrían estrellado en todas las carreras!', `FemaleText_loc1`='고블린 녀석들의 그 믿을 수 없는 행운만 아니었으면 경주 때마다 차가 완전히 박살났을 텐데!', `FemaleText_loc4`='要不是地精的狗屎运，他们每次都会把车撞进山里去！', `FemaleText_loc5`='要不是哥布林的狗屎運，他們每次都會把車撞進山裡去!', `FemaleText_loc7`='¡Si no fuera por la inconcebible y estúpida suerte de los goblins, se habrían estrellado en todas las carreras!' WHERE `ID`=2774;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 경주는 우리 노움의 뛰어난 창의력을 만천하에 보여줄 좋은 기회야!', `MaleText_loc4`='这种车赛是展现我们高新科技的大好机会！', `MaleText_loc5`='這種車賽是展現我們高新科技的大好機會!', `MaleText_loc7`='¡Estas carreras son una gran oportunidad para probar nuestro ingenio!', `FemaleText_loc1`='이 경주는 우리 노움의 뛰어난 창의력을 만천하에 보여줄 좋은 기회야!', `FemaleText_loc4`='这种车赛是展现我们高新科技的大好机会！', `FemaleText_loc5`='這種車賽是展現我們高新科技的大好機會!', `FemaleText_loc7`='¡Estas carreras son una gran oportunidad para probar nuestro ingenio!' WHERE `ID`=2775;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 경주차의 행렬 열도계에 새로운 장치를 설치했소. 마하 15는 거뜬히 나올 거요!', `MaleText_loc4`='我给我们的车里安装了新的矩阵式调节器，它可以使赛车的引擎转速提高至少百分之十五！', `MaleText_loc5`='我給我們的車裡安裝了新的矩陣式調節器，它可以使賽車的引擎轉速提高至少百分之十五!', `MaleText_loc7`='He instalado un nuevo dispositivo en el regulómetro de la matriz de nuestro coche. ¡Debería aumentar su velocidad más de quince veces!', `FemaleText_loc1`='우리 경주차의 행렬 열도계에 새로운 장치를 설치했소. 마하 15는 거뜬히 나올 거요!', `FemaleText_loc4`='我给我们的车里安装了新的矩阵式调节器，它可以使赛车的引擎转速提高至少百分之十五！', `FemaleText_loc5`='我給我們的車裡安裝了新的矩陣式調節器，它可以使賽車的引擎轉速提高至少百分之十五!', `FemaleText_loc7`='He instalado un nuevo dispositivo en el regulómetro de la matriz de nuestro coche. ¡Debería aumentar su velocidad más de quince veces!' WHERE `ID`=2776;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 세 살배기 아들 녀석도 저 투박하고 엉성한 고블린 경주차보다는 더 빠른 차를 만들 수 있을 거요!', `MaleText_loc4`='我那两岁的儿子设计的赛车都比那些可笑的地精造出来的破烂跑得更快！', `MaleText_loc5`='我那兩歲的兒子設計的賽車都比那些可笑的哥布林造出來的破銅爛鐵跑得更快!', `MaleText_loc7`='¡Mi hijo podría diseñar un coche más rápido que ese montón de chatarra destartalada goblin!', `FemaleText_loc1`='내 세 살배기 아들 녀석도 저 투박하고 엉성한 고블린 경주차보다는 더 빠른 차를 만들 수 있을 거요!', `FemaleText_loc4`='我那两岁的儿子设计的赛车都比那些可笑的地精造出来的破烂跑得更快！', `FemaleText_loc5`='我那兩歲的兒子設計的賽車都比那些可笑的哥布林造出來的破銅爛鐵跑得更快!', `FemaleText_loc7`='¡Mi hijo podría diseñar un coche más rápido que ese montón de chatarra destartalada goblin!' WHERE `ID`=2777;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 태엽 점성장치에 의하면 지난 시합 때보다 20초는 더 빨리 고블린을 이길 수 있을 것 같소!', `MaleText_loc4`='我的数据分析师认为这次我们会比上次的纪录提高二十秒！', `MaleText_loc5`='我的資料分析師認為這次我們會比上次的紀錄提高二十秒!', `MaleText_loc7`='Mi Gizmotic Almanacotron dice que deberíamos vencer a los goblins por veinte segundos más que la vez pasada.', `FemaleText_loc1`='내 태엽 점성장치에 의하면 지난 시합 때보다 20초는 더 빨리 고블린을 이길 수 있을 것 같소!', `FemaleText_loc4`='我的数据分析师认为这次我们会比上次的纪录提高二十秒！', `FemaleText_loc5`='我的資料分析師認為這次我們會比上次的紀錄提高二十秒!', `FemaleText_loc7`='Mi Gizmotic Almanacotron dice que deberíamos vencer a los goblins por veinte segundos más que la vez pasada.' WHERE `ID`=2778;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='틸스의 조수는 어디 있습니까?', `MaleText_loc4`='提尔斯的助手在哪里？', `MaleText_loc5`='提爾斯的助手在哪裡?', `MaleText_loc7`='¿Dónde está el asistente de Tirth?', `FemaleText_loc1`='틸스의 조수는 어디 있습니까?', `FemaleText_loc4`='提尔斯的助手在哪里？', `FemaleText_loc5`='提爾斯的助手在哪裡?', `FemaleText_loc7`='¿Dónde está el asistente de Tirth?' WHERE `ID`=2779;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='틸스가 요즘 제정신이 아니라더니 그 조수도 마찬가지군.', `MaleText_loc4`='这些天提尔斯和他的助手都变得怪怪的。', `MaleText_loc5`='這些天提爾斯和他的助手都變得怪怪的。', `MaleText_loc7`='A Tirth le pasa algo estos días y lo mismo le ocurre a su asistente.', `FemaleText_loc1`='틸스가 요즘 제정신이 아니라더니 그 조수도 마찬가지군.', `FemaleText_loc4`='这些天提尔斯和他的助手都变得怪怪的。', `FemaleText_loc5`='這些天提爾斯和他的助手都變得怪怪的。', `FemaleText_loc7`='A Tirth le pasa algo estos días y lo mismo le ocurre a su asistente.' WHERE `ID`=2780;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='존슨? 이 근처 어딘가에 있을 텐데...', `MaleText_loc4`='约翰森？我认为他在附近的某个地方……', `MaleText_loc5`='強森?我認為他在附近的某個地方...', `MaleText_loc7`='¿Johnson? Creo que anda por aquí...', `FemaleText_loc1`='존슨? 이 근처 어딘가에 있을 텐데...', `FemaleText_loc4`='约翰森？我认为他在附近的某个地方……', `FemaleText_loc5`='強森?我認為他在附近的某個地方...', `FemaleText_loc7`='¿Johnson? Creo que anda por aquí...' WHERE `ID`=2781;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='며칠째 틸스가 존슨을 찾고 있는데 도무지 모습을 드러내지 않고 있지요. 바로 저기 저 닭이에요!', `MaleText_loc4`='哈！提尔斯这段时间以来都在找他，但是他不想被找到。他是一只小鸡。', `MaleText_loc5`='哈!提爾斯這段時間以來都在找他，但是他不想被找到。他是一隻小雞。', `MaleText_loc7`='¡Ja! Tirth lo ha estado buscando durante días, pero él no quiere que lo encuentren. ¡Es un gallina!', `FemaleText_loc1`='며칠째 틸스가 존슨을 찾고 있는데 도무지 모습을 드러내지 않고 있지요. 바로 저기 저 닭이에요!', `FemaleText_loc4`='哈！提尔斯这段时间以来都在找他，但是他不想被找到。他是一只小鸡。', `FemaleText_loc5`='哈!提爾斯這段時間以來都在找他，但是他不想被找到。他是一隻小雞。', `FemaleText_loc7`='¡Ja! Tirth lo ha estado buscando durante días, pero él no quiere que lo encuentren. ¡Es un gallina!' WHERE `ID`=2782;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곰??', `MaleText_loc4`='熊？？', `MaleText_loc5`='熊??', `MaleText_loc7`='¿¿Osos??', `FemaleText_loc1`='곰??', `FemaleText_loc4`='熊？？', `FemaleText_loc5`='熊??', `FemaleText_loc7`='¿¿Osos??' WHERE `ID`=2783;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 이 감옥에서 해방이 됐군!$B$B나는 이곳 은빛소나무 숲에서 아루갈이 언데드를 어떻게 상대하고 있는지 조사하라는 키린 토의 지시를 받고 달라란에서 왔습니다. 아루갈이 미쳐버린 줄은 아무도 몰랐지요.$B$B즉시 이 사태에 대해 보고를 해야 합니다! 하지만 떠나기 전에 안마당 문에 걸린 마법 자물쇠를 풀어 드리지요.$B$B당신은 레실고어를 물리쳤으니 아마 이 문 너머 세상에서도 살아남을 수 있을 겁니다.', `MaleText_loc4`='终于！终于从这破牢房里逃出来了！$b$b肯瑞托将我从达拉然派到这个银松森林里来，要我调查阿鲁高和他的亡灵仆从们的活动，可我们却一点也不知道那个巫师已经完全失去了理智。$b$b我必须立刻把这个消息汇报上去！可在我离开之前，让我先把庭院门上的魔法锁给打开。$b$b既然你能击败雷希戈尔，或许也能从前面的层层埋伏中杀出一条血路……', `MaleText_loc5`='終於!終於從這破牢房裡逃出來了!$b$b祈倫托將我從達拉然派到這個銀松森林裡來，要我調查阿魯高和他的亡靈僕從們的活動，可我們卻一點也不知道那個巫師已經完全失去了理智。$b$b我必須立刻把這個消息彙報上去!可在我離開之前，讓我先把庭院門上的魔法鎖給打開。$b$b既然你能擊敗雷希戈爾，或許也能從前面的層層埋伏中殺出一條血路...', `MaleText_loc7`='¡Al fin! ¡Al fin he salido de esta celda!$b$bEl Kirin Tor me envió desde Dalaran para investigar los avances de Arugal con los no-muertos aquí en el Bosque de Argénteos. No teníamos ni idea de que el zahorí había perdido la cordura.$b$b¡Tengo que informar de inmediato acerca de este desaguisado! Pero antes de que me vaya, deja que abra la cerradura mágica.$b$bVenciste a Rethilgore, así que quizás sobrevivas a lo que te espera más allá...' WHERE `ID`=2801;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안마당 문을 열어주십시오.', `MaleText_loc4`='请打开庭院的大门。', `MaleText_loc5`='請打開庭院的大門。', `MaleText_loc7`='Por favor, abre la cerradura de la puerta del patio.', `FemaleText_loc1`='안마당 문을 열어주십시오.', `FemaleText_loc4`='请打开庭院的大门。', `FemaleText_loc5`='請打開庭院的大門。', `FemaleText_loc7`='Por favor, abre la cerradura de la puerta del patio.' WHERE `ID`=2802;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어! 저를 이 감옥에서 구해줄 분이 오셨군요! 오, 여왕이시여! 감사합니다!$B$B우리는 아루갈을 일망타진할 계획을 세울 수 있도록 성채에 관한 정보를 모아오라는 고위집행관 하드렉의 지시를 받고 왔습니다.$B$B하지만 그 늙은 마법사가 많은 계략을 숨겨놓는 바람에 우리는 마법 감시망에 걸려 들켜버리고 말았지요. 저는 살아남아 이 감옥에라도 갇혔지만 빈센트는 운이 좋지 않았습니다.$B$B즉시 하드렉에게 돌아가 이 일을 보고해야 합니다. 그 전에 먼저 안마당 문에 걸린 자물쇠를 열어 드리도록 하지요. 문 너머에 숨어 있는 적들에게 당신의 행운을 시험해 볼 수 있을 겁니다.', `MaleText_loc4`='终于！终于有人把我从这破牢房里给救出来了！$b$b高级执行官哈德瑞克大人派我们来这儿收集这座要塞里的信息，以便制定一个能永久消灭铲除阿鲁高的计划。$b$b但那个老不死的巫师还真有点能耐，我们很快就被他的魔法结界给发现了。我被抓来关在这里，不过文森特可就没这么走运了。$b$b我得马上回去向哈德瑞克大人汇报。首先我会把庭院里的锁给你打开，或许你这么强悍的$c能从前面的一大堆伏兵里杀出一条血路……', `MaleText_loc5`='終於!終於有人把我從這破牢房裡給救出來了!$b$b高階執行官哈德瑞克大人派我們來這兒收集這座要塞裡的資訊，以便制定一個能永久消滅剷除阿魯高的計畫。$b$b但那個老不死的巫師還真有點能耐，我們很快就被他的魔法結界給發現了。我被抓來關在這裡，不過文森可就沒這麼走運了。$b$b我得馬上回去向哈德瑞克大人彙報。首先我會把庭院裡的鎖給你打開，或許你這麼強悍的$c能從前面的一大堆伏兵裡殺出一條血路...', `MaleText_loc7`='¡Al fin! ¡Que alguien me saque de esta celda!$b$bEl sumo ejecutor Hadrec nos envió para recoger información sobre la fortaleza, así que se podría idear un plan para derrocar a Arugal de una vez por todas.$b$bNo obstante, este viejo zahorí tiene muchos trucos ocultos y nos ha detectado a través de una sala mágica. Me confinaron en esta prisión. Vincent no tuvo tanta suerte.$b$bTengo que volver con Hadrec para rendirle informe de inmediato. Pero antes te abriré el cerrojo de la puerta del patio. Quizás puedas probar suerte contra los enemigos que acechan desde el otro lado.' WHERE `ID`=2803;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='치유 주문에 실패했습니다. 불행히도 이 짐승의 혈액에 혈청을 주입하면 곧 목숨을 잃을 것입니다.', `MaleText_loc4`='治疗法术失败了。不幸的是，注入那只野兽血管中的血清不久之后就会要了它的命。', `MaleText_loc5`='治療法術失敗了。不幸的是，注入那隻野獸血管中的血清不久之後就會要了它的命。', `MaleText_loc7`='El conjuro curativo ha fallado. Desafortunadamente, la inyección del suero en el torrente sanguíneo de la bestia pronto acabará con su vida.' WHERE `ID`=2804;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타나리운에게 광포한 엉겅퀴곰을 풀어줍니다.', `MaleText_loc4`='把狂暴蓟熊交给萨纳瑞恩接管。', `MaleText_loc5`='把狂暴薊熊交給薩納瑞恩接管。', `MaleText_loc7`='Libera al oso cardo rabioso para Tharnariun.', `FemaleText_loc1`='타나리운에게 광포한 엉겅퀴곰을 풀어줍니다.', `FemaleText_loc4`='把狂暴蓟熊交给萨纳瑞恩接管。', `FemaleText_loc5`='把狂暴薊熊交給薩納瑞恩接管。', `FemaleText_loc7`='Libera al oso cardo rabioso para Tharnariun.' WHERE `ID`=2805;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘했소. 이제 그 곰을 풀어주면 내가 치유 주문을 걸 수 있소.', `MaleText_loc4`='干得好。让我接管这头熊，然后我就可以施展治疗法术了。', `MaleText_loc5`='幹得好。讓我接管這頭熊，然後我就可以施展治療法術了。', `MaleText_loc7`='Bien hecho. Libera al oso para ocuparme de su custodia y pueda aplicarle el conjuro curativo.' WHERE `ID`=2806;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 한때 황혼의 망치단을 따랐었소. 고대 신들을 환생시키는 데 집착했던 나는 그 몹쓸 짐승 아쿠마이의 힘을 얻기 위해 이 깊은 굴속으로 들어왔지.$B$B수많은 무고한 생명이 제물로 바쳐지는 것을 보고서야 정신을 차리게 되었소.$B$B이제는 덫에서 풀려나 자유의 몸이 되었소! 하지만 고향인 카즈 모단은 너무나 멀리 있군.$B$B용감한 모험가여, 아쿠마이를 처치해 준 답례로 아주 특별한 땅으로 가는 길을 알려주겠소. 원한다면 다르나서스로 이동시켜주리다.', `MaleText_loc4`='我以前曾经追寻过墓光之锤的道路。为了找到复活上古之神的方法，我只身深入这座巢穴，想要找到从那个该死的恶魔阿库麦尔身上抽取能量的方法。$B$B在看到无数无辜人白白地牺牲之后，我慢慢恢复了理智。$B$B我被困住了一段时间，但是现在我自由了！不幸的是，这里离我的家乡卡兹莫丹太远了！$B$B勇敢的冒险者，我现在可以将你传送到一个特别的地方，然后回来干掉阿库麦尔。如果你愿意的话，我现在就送你到达纳苏斯去。', `MaleText_loc5`='我以前曾經追尋過暮光之錘的道路。為了找到復活上古諸神的方法，我隻身深入這座巢穴，想要找到從那個該死的惡魔阿庫麥爾身上抽取能量的方法。$B$B在看到無數無辜人白白地犧牲之後，我慢慢恢復了理智。$B$B我被困住了一段時間，但是現在我自由了!不幸的是，這裡離我的家鄉卡茲莫丹太遠了!$B$B勇敢的冒險者，我現在可以將你傳送至一個特別的地方，然後回來幹掉阿庫麥爾。如果你願意的話，我現在就送你到達納蘇斯去。', `MaleText_loc7`='Una vez seguí la senda del Martillo Crepuscular. Obsesionado con resucitar a los dioses antiguos, me interné en las profundidades de esta guarida para intentar absorber el poder de Aku''mai, ¡bestia maldita!$b$bTras presenciar el sacrificio de incontables inocentes, recuperé el sentido.$b$b¡Estaba atrapado, pero ahora soy libre! ¡Y ahora estoy tan lejos de mi tierra natal Khaz Modan!$b$bValiente $gaventurero:aventurera;, te enseñaré el camino a una tierra muy especial a cambio de que mates a Aku''mai. Si lo deseas, puedo transportarte a la ciudad de Darnassus.' WHERE `ID`=2807;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여행으로 지치신 분이시여, 저희 여관에 오신것을 환영합니다! 무엇을 도와 드릴까요?', `MaleText_loc4`='欢迎来到我的旅店，疲惫的旅行者。我能为您做点什么吗？', `MaleText_loc5`='歡迎來到我的旅店，疲憊的旅人。我能為你效勞嗎?', `MaleText_loc7`='Te doy la bienvenida a mi taberna, $gfatigado viajero:fatigada viajera;. ¿En qué puedo ayudarte?', `FemaleText_loc1`='여행으로 지치신 분이시여, 저희 여관에 오신것을 환영합니다! 무엇을 도와 드릴까요?', `FemaleText_loc4`='欢迎来到我的旅店，疲惫的旅行者。我能为您做点什么吗？', `FemaleText_loc5`='歡迎來到我的旅店，疲憊的旅人。我能為你效勞嗎?', `FemaleText_loc7`='Te doy la bienvenida a mi taberna, $gfatigado viajero:fatigada viajera;. ¿En qué puedo ayudarte?' WHERE `ID`=2821;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 여관을 귀환 장소로 사용합니다.', `MaleText_loc4`='将这座旅店设为你的家。', `MaleText_loc5`='將這座旅店設為你的家。', `MaleText_loc7`='Fija tu hogar en esta taberna.', `FemaleText_loc1`='이 여관을 귀환 장소로 사용합니다.', `FemaleText_loc4`='将这座旅店设为你的家。', `FemaleText_loc5`='將這座旅店設為你的家。', `FemaleText_loc7`='Fija tu hogar en esta taberna.' WHERE `ID`=2822;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물건을 살펴보고 싶습니다.', `MaleText_loc4`='让我看看你出售的货物。', `MaleText_loc5`='讓我看看你出售的貨物。', `MaleText_loc7`='Deja que eche un vistazo a tus mercancías.', `FemaleText_loc1`='물건을 살펴보고 싶습니다.', `FemaleText_loc4`='让我看看你出售的货物。', `FemaleText_loc5`='讓我看看你出售的貨物。', `FemaleText_loc7`='Deja que eche un vistazo a tus mercancías.' WHERE `ID`=2823;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여관에서 푹 쉬시면서 지친 몸을 달래시기 바랍니다.', `MaleText_loc4`='放松一下自己疲倦的身心。', `MaleText_loc5`='放鬆一下自己疲倦的身心。', `MaleText_loc7`='Descansa un rato.', `FemaleText_loc1`='여관에서 푹 쉬시면서 지친 몸을 달래시기 바랍니다.', `FemaleText_loc4`='放松一下自己疲倦的身心。', `FemaleText_loc5`='放鬆一下自己疲倦的身心。', `FemaleText_loc7`='Descansa un rato.' WHERE `ID`=2824;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희 여관을 찾아주시는 분은 초원에서 불어오는 시원한 바람처럼 언제나 대환영이랍니다.', `MaleText_loc4`='我们一直欢迎你的到来，就像我们欢迎平原上吹过的风。', `MaleText_loc5`='我們一直歡迎你的到來，就像我們歡迎平原上吹過的風。', `MaleText_loc7`='Al igual que el viento de las llanuras, siempre eres $gbienvenido:bienvenida; aquí.', `FemaleText_loc1`='저희 여관을 찾아주시는 분은 초원에서 불어오는 시원한 바람처럼 언제나 대환영이랍니다.', `FemaleText_loc4`='我们一直欢迎你的到来，就像我们欢迎平原上吹过的风。', `FemaleText_loc5`='我們一直歡迎你的到來，就像我們歡迎平原上吹過的風。', `FemaleText_loc7`='Al igual que el viento de las llanuras, siempre eres $gbienvenido:bienvenida; aquí.' WHERE `ID`=2825;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='손님, 맥주잔을 가득 채워드리겠습니다. 의자를 당겨 편히 앉으세요. 저희 여관에는 언제나 술이 찰랑거리는 맥주통과 정다운 이야기들이 있답니다.', `MaleText_loc4`='满上一杯啤酒，拉一张凳子过来坐坐。我们要畅饮一番，同时还要分享我们的故事。', `MaleText_loc5`='滿上一杯啤酒，拉一張凳子過來坐坐。我們要暢飲一番，同時還要分享我們的故事。', `MaleText_loc7`='Llena tu jarra y coge una silla. Tenemos historias que contar y barriles que vaciar.', `FemaleText_loc1`='손님, 맥주잔을 가득 채워드리겠습니다. 의자를 당겨 편히 앉으세요. 저희 여관에는 언제나 술이 찰랑거리는 맥주통과 정다운 이야기들이 있답니다.', `FemaleText_loc4`='满上一杯啤酒，拉一张凳子过来坐坐。我们要畅饮一番，同时还要分享我们的故事。', `FemaleText_loc5`='滿上一杯啤酒，拉一張凳子過來坐坐。我們要暢飲一番，同時還要分享我們的故事。', `FemaleText_loc7`='Llena tu jarra y coge una silla. Tenemos historias que contar y barriles que vaciar.' WHERE `ID`=2826;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='손님의 얼굴과 영혼은 지치고 힘들어 보이는군요. 저희 여관에서 지친 몸을 편히 뉘이시고 꿈속에서 엘룬께 조언을 구하시기 바랍니다.', `MaleText_loc4`='你看上去很疲惫。在我们的屋里休息一会儿吧，让艾露恩引领你进入甜美的梦乡。', `MaleText_loc5`='你看起來很疲憊。在我們的屋裡休息一會兒吧，讓伊露恩引領你進入甜美的夢鄉。', `MaleText_loc7`='Tu cuerpo parece desfallecido y tu espíritu agotado. Descansa bajo nuestro techo y deja que Elune inspire tus sueños.', `FemaleText_loc1`='손님의 얼굴과 영혼은 지치고 힘들어 보이는군요. 저희 여관에서 지친 몸을 편히 뉘이시고 꿈속에서 엘룬께 조언을 구하시기 바랍니다.', `FemaleText_loc4`='你看上去很疲惫。在我们的屋里休息一会儿吧，让艾露恩引领你进入甜美的梦乡。', `FemaleText_loc5`='你看起來很疲憊。在我們的屋裡休息一會兒吧，讓伊露恩引領你進入甜美的夢鄉。', `FemaleText_loc7`='Tu cuerpo parece desfallecido y tu espíritu agotado. Descansa bajo nuestro techo y deja que Elune inspire tus sueños.' WHERE `ID`=2827;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 자, 어서 들어오세요. 난로에는 너무 가까이 앉지 않는 게 좋습니다요, 손님. 오늘은 아직 불이 나지 않았지만 제 생각엔 다른 곳에 앉으시는 게 안전할 거 같습니다.', `MaleText_loc4`='请进，请进！不要坐得离火炉太近。它今天还没爆炸，但是为了安全起见，我想你还是坐在别的地方比较好。', `MaleText_loc5`='請進，請進!不要坐得離火爐太近。它今天還沒爆炸，但是為了安全起見，我想你還是坐在別的地方比較好。', `MaleText_loc7`='Pasa, pasa. Pero no te sientes demasiado cerca de la estufa. Hoy todavía no ha explotado pero es más seguro que te sientes en otro sitio.', `FemaleText_loc1`='자, 자, 어서 들어오세요. 난로에는 너무 가까이 앉지 않는 게 좋습니다요, 손님. 오늘은 아직 불이 나지 않았지만 제 생각엔 다른 곳에 앉으시는 게 안전할 거 같습니다.', `FemaleText_loc4`='请进，请进！不要坐得离火炉太近。它今天还没爆炸，但是为了安全起见，我想你还是坐在别的地方比较好。', `FemaleText_loc5`='請進，請進!不要坐得離火爐太近。它今天還沒爆炸，但是為了安全起見，我想你還是坐在別的地方比較好。', `FemaleText_loc7`='Pasa, pasa. Pero no te sientes demasiado cerca de la estufa. Hoy todavía no ha explotado pero es más seguro que te sientes en otro sitio.' WHERE `ID`=2828;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 부글거리기 시작합니다!', `MaleText_loc4`='%s开始冒泡！', `MaleText_loc5`='%s開始起泡!', `MaleText_loc7`='%s comienza a burbujear.', `FemaleText_loc1`='%s|1이;가; 부글거리기 시작합니다!', `FemaleText_loc4`='%s开始冒泡！', `FemaleText_loc5`='%s開始起泡!', `FemaleText_loc7`='%s empieza a burbujear.' WHERE `ID`=2829;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여관은 모험을 끝낸 후 휴식을 취할 수 있는 곳입니다. 다시 모험을 떠나기 전에 여관에 머물면서 충분한 휴식을 취하도록 하십시오.$B$B모든 여관에서는 귀환석을 얻을 수 있는데 여관에서 휴식을 취하고 싶을 때 이 귀환석을 사용하면 자신이 머물렀던 여관으로 다시 돌아갈 수 있습니다.', `MaleText_loc4`='旅店是供你在冒险后休息的地方。如果你不待在旅店中，那么当你重新开始冒险时候就得不到很好的休息。$B$B你可以在任何一家旅馆中免费得到一块炉石，当你准备休息时，就可以使用炉石传送回你所绑定的旅店中。', `MaleText_loc5`='旅店是供你在冒險後休息的地方。如果你不待在旅店中，那麼當你重新開始冒險時候就得不到很好的休息。$B$B你可以在任何一家旅館中免費得到一塊爐石，當你準備休息時，就可以使用爐石傳送回你所綁定的旅店中。', `MaleText_loc7`='Las tabernas son lugares en los que puedes descansar después de tus aventuras. Si no te quedas en una taberna como esta, no estarás totalmente descansado para cuando vuelvas a internarte en el bosque.$B$BTambién puedes adquirir una piedra de hogar en cualquier taberna y, más adelante, cuando quieras descansar, la piedra te llevará de vuelta al lugar en el que la adquiriste.', `FemaleText_loc1`='여관은 모험을 끝낸 후 휴식을 취할 수 있는 곳입니다. 다시 모험을 떠나기 전에 여관에 머물면서 충분한 휴식을 취하도록 하십시오.$B$B모든 여관에서는 귀환석을 얻을 수 있는데 여관에서 휴식을 취하고 싶을 때 이 귀환석을 사용하면 자신이 머물렀던 여관으로 다시 돌아갈 수 있습니다.', `FemaleText_loc4`='旅店是供你在冒险后休息的地方。如果你不待在旅店中，那么当你重新开始冒险时候就得不到很好的休息。$B$B你可以在任何一家旅馆中免费得到一块炉石，当你准备休息时，就可以使用炉石传送回你所绑定的旅店中。', `FemaleText_loc5`='旅店是供你在冒險後休息的地方。如果你不待在旅店中，那麼當你重新開始冒險時候就得不到很好的休息。$B$B你可以在任何一家旅館中免費得到一塊爐石，當你準備休息時，就可以使用爐石傳送回你所綁定的旅店中。', `FemaleText_loc7`='Las tabernas son lugares en los que puedes descansar después de tus aventuras. Si no te quedas en una taberna como esta, no estarás totalmente descansado para cuando vuelvas a internarte en el bosque.$B$BTambién puedes adquirir una piedra de hogar en cualquier taberna y, más adelante, cuando quieras descansar, la piedra te llevará de vuelta al lugar en el que la adquiriste.' WHERE `ID`=2841;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대장님이 쓰러지셨다! 형제들이여, 복수하라!', `MaleText_loc4`='主人倒下了！我们要为他复仇！', `MaleText_loc5`='主人倒下了!為他報仇，我的兄弟們!', `MaleText_loc7`='¡El maestro ha caído! ¡Vengadle, hermanos!', `FemaleText_loc1`='대장님이 쓰러지셨다! 형제들이여, 복수하라!', `FemaleText_loc4`='主人倒下了！我们要为他复仇！', `FemaleText_loc5`='主人倒下了!我們要為他復仇!', `FemaleText_loc7`='¡El maestro ha caído! ¡Venguémoslo, hermanos!' WHERE `ID`=2842;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$r|1이여;여;. 만나서 반갑습니다.', `FemaleText_loc4`='你好，$c，很高兴认识你。', `FemaleText_loc5`='你好，$r，很高興認識你。', `FemaleText_loc7`='Hola, $r, encantada de conocerte.' WHERE `ID`=2843;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 타조를 훈련시키고 싶습니다.', `MaleText_loc4`='我的陆行鸟需要接受训练。', `MaleText_loc5`='我的陸行鳥需要接受訓練。', `MaleText_loc7`='Mi zancudo necesita instrucción.', `FemaleText_loc1`='제 타조를 훈련시키고 싶습니다.', `FemaleText_loc4`='我的陆行鸟需要接受训练。', `FemaleText_loc5`='我的陸行鳥需要接受訓練。', `FemaleText_loc7`='Mi zancudo necesita instrucción.' WHERE `ID`=2844;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, $n. 고향 마을 떠나 거친 들판에서도 생존할 수 있는 방법이 알고 싶으신가요? 이 땅의 동식물을 이용해 생명을 이어가는 기술 말입니다!$B$B관심이 있다면 제가 한두 가지 가르쳐드릴 수 있답니다.', `FemaleText_loc4`='你好，$n。你对野外生存感兴趣吗？和大自然间的动植物共同生活！$B$B如果你感兴趣的话，你可以从我这里学到一些东西。', `FemaleText_loc5`='你好，$n。你對野外生存感興趣嗎?和大自然間的動植物共同生活!$B$B如果你感興趣的話，你可以從我這裡學到一些東西。', `FemaleText_loc7`='Hola, $n. ¿Te interesa la supervivencia en el exterior? El sustento a partir de la flora y fauna de las tierras.$B$BPodrías aprender un par de cosas de mí, bueno, si te interesa.' WHERE `ID`=2845;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다르나서스로 이동시켜주십시오.', `MaleText_loc4`='请把我传送到达纳苏斯。', `MaleText_loc5`='請把我傳送至達納蘇斯。', `MaleText_loc7`='Transpórtame hasta Darnassus.', `FemaleText_loc1`='다르나서스로 이동시켜주십시오.', `FemaleText_loc4`='请把我传送到达纳苏斯。', `FemaleText_loc5`='請把我傳送至達納蘇斯。', `FemaleText_loc7`='Transpórtame hasta Darnassus.' WHERE `ID`=2846;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이단자들! 성스러운 칼을 받아라!', `MaleText_loc4`='异教徒， 净化他们！', `MaleText_loc5`='異教徒!淨化他們!', `MaleText_loc7`='¡Infieles! ¡Hay que purificarlos!' WHERE `ID`=2847;
