UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 여행을 떠나시려는가 보군요. 영웅의 계곡이 내려다보이는 북동쪽 성벽에 가시면 그리핀 조련사를 만나실 수 있습니다.', `MaleText_loc4`='你可以在英雄谷东北边的那个城堡平台上找到狮鹫管理员。', `MaleText_loc5`='你可以在英雄谷東北邊的那個城堡平臺上找到獅鷲獸管理員。', `MaleText_loc7`='Encontrarás al maestro de grifos en la muralla del noreste, con vista al Valle de los Héroes.', `FemaleText_loc1`='오, 여행을 떠나시려는가 보군요. 영웅의 계곡이 내려다보이는 북동쪽 성벽에 가시면 그리핀 조련사를 만나실 수 있습니다.', `FemaleText_loc4`='你可以在英雄谷东北边的那个城堡平台上找到狮鹫管理员。', `FemaleText_loc5`='你可以在英雄谷東北邊的那個城堡平臺上找到獅鷲獸管理員。', `FemaleText_loc7`='Encontrarás al maestro de grifos en la muralla del noreste, con vista al Valle de los Héroes.' WHERE `ID`=2864;
