UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대성당 광장에 있는 빛의 대성당은 스톰윈드 사제들에게 안식처와 같은 곳이랍니다. 그곳에서 대여사제 로레나 님을 만나보도록 하십시오.', `MaleText_loc4`='教堂广场的光明大教堂是暴风城神职人员的住所，你可以在那里找到高阶牧师劳瑞娜。', `MaleText_loc5`='教堂廣場的聖光大教堂是暴風城神職人員的住所，你可以在那裡找到高階牧師勞瑞娜。', `MaleText_loc7`='La Catedral de la Luz, en la Plaza de la Catedral, es el hogar de los sacerdotes de Ventormenta. Allí encontrarás a la suma sacerdotisa Laurena.', `FemaleText_loc1`='대성당 광장에 있는 빛의 대성당은 스톰윈드 사제들에게 안식처와 같은 곳이랍니다. 그곳에서 대여사제 로레나 님을 만나보도록 하십시오.', `FemaleText_loc4`='教堂广场的光明大教堂是暴风城神职人员的住所，你可以在那里找到高阶牧师劳瑞娜。', `FemaleText_loc5`='教堂廣場的聖光大教堂是暴風城神職人員的住所，你可以在那裡找到高階牧師勞瑞娜。', `FemaleText_loc7`='La Catedral de la Luz, en la Plaza de la Catedral, es el hogar de los sacerdotes de Ventormenta. Allí encontrarás a la suma sacerdotisa Laurena.' WHERE `ID`=2919;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드의 대여사제 로레나 님을 만나보시기 바랍니다. 대성당 광장의 빛의 대성당으로 가시면 그분을 뵐 수 있습니다.', `MaleText_loc4`='劳瑞娜是暴风城的高阶牧师，你可以在教堂广场上的光明大教堂里找到她。', `MaleText_loc5`='勞瑞娜是暴風城的高階牧師，你可以在教堂廣場上的光明大教堂裡找到她。', `MaleText_loc7`='Laurena es la suma sacerdotisa de Ventormenta. La encontrarás en la Catedral de la Luz, en la Plaza de la Catedral.', `FemaleText_loc1`='스톰윈드의 대여사제 로레나 님을 만나보시기 바랍니다. 대성당 광장의 빛의 대성당으로 가시면 그분을 뵐 수 있습니다.', `FemaleText_loc4`='劳瑞娜是暴风城的高阶牧师，你可以在教堂广场上的光明大教堂里找到她。', `FemaleText_loc5`='勞瑞娜是暴風城的高階牧師，你可以在教堂廣場上的光明大教堂裡找到她。', `FemaleText_loc7`='Laurena es la suma sacerdotisa de Ventormenta. La encontrarás en la Catedral de la Luz, en la Plaza de la Catedral.' WHERE `ID`=2920;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대성당 광장에 있는 빛의 대성당으로 가서 상급 사제들을 만나보시는 게 좋겠습니다.', `MaleText_loc4`='我建议你去教堂广场上的光明大教堂里找一找。', `MaleText_loc5`='我建議你去教堂廣場上的聖光大教堂裡找一找。', `MaleText_loc7`='Sugeriría que buscaras en la Catedral de la Luz, en la Plaza de la Catedral.', `FemaleText_loc1`='대성당 광장에 있는 빛의 대성당으로 가서 상급 사제들을 만나보시는 게 좋겠습니다.', `FemaleText_loc4`='我建议你去教堂广场上的光明大教堂里找一找。', `FemaleText_loc5`='我建議你去教堂廣場上的聖光大教堂裡找一找。', `FemaleText_loc7`='Sugeriría que buscaras en la Catedral de la Luz, en la Plaza de la Catedral.' WHERE `ID`=2921;
