UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강인한 성기사가 되기 위한 가르침을 받으려면 그레이슨 섀도브레이커 경만한 스승도 없을 겁니다. 그분은 대성당 광장에 있는 빛의 대성당에서 만나실 수 있습니다.', `MaleText_loc4`='如果你想变成强大的圣骑士，那么格雷森·沙东布瑞克公爵是你最好的导师。你可以在教堂广场上的光明大教堂中找到他。', `MaleText_loc5`='如果你想變成強大的聖騎士，那麼格雷森·破影者領主是你最好的導師。你可以在教堂廣場上的聖光大教堂中找到他。', `MaleText_loc7`='Si quieres convertirte en un poderoso paladín, no encontrarás mejor maestro que Lord Grisillo Quiebrasombras. Lo encontrarás en la Catedral de la Luz, en la Plaza de la Catedral.', `FemaleText_loc1`='강인한 성기사가 되기 위한 가르침을 받으려면 그레이슨 섀도브레이커 경만한 스승도 없을 겁니다. 그분은 대성당 광장에 있는 빛의 대성당에서 만나실 수 있습니다.', `FemaleText_loc4`='如果你想变成强大的圣骑士，那么格雷森·沙东布瑞克公爵是你最好的导师。你可以在教堂广场上的光明大教堂中找到他。', `FemaleText_loc5`='如果你想變成強大的聖騎士，那麼格雷森·破影者領主是你最好的導師。你可以在教堂廣場上的聖光大教堂中找到他。', `FemaleText_loc7`='Si quieres convertirte en un poderoso paladín, no encontrarás mejor maestro que Lord Grayson Quiebrasombras. Lo encontrarás en la Catedral de la Luz, en la Plaza de la Catedral.' WHERE `ID`=2923;
