UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에서 어둠과 그림자는 마음대로 쓰고 버리는 도구와 같은 것들이오.', `MaleText_loc4`='在这里，黑暗和阴影是随你的意志而变化的工具。', `MaleText_loc5`='在這裡，黑暗和陰影是隨你的意志而變化的工具。', `MaleText_loc7`='En este lugar, la oscuridad y las sombras son herramientas que puedes usar a tu voluntad.' WHERE `ID`=3041;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='데피아즈 결사단의 손에 어리석은 녀석 하나가 쓰러지는군.', `MaleText_loc4`='又一个笨蛋在迪菲亚兄弟会面前倒下了。', `MaleText_loc5`='又一個笨蛋在迪菲亞兄弟會面前倒下了。', `MaleText_loc7`='Otro idiota sucumbe ante la Hermandad Defias.' WHERE `ID`=3042;
