UPDATE `locales_broadcast_text` SET `MaleText_loc1`='역시 생각했던 대로군. 이 보석과 목걸이는 그다지 중요한 게 아니오. 중요한 건 마력원천이오.', `MaleText_loc4`='正如我所想的那样，宝石和项链没有问题，问题在于能量之源。', `MaleText_loc5`='正如我所想的那樣，寶石和項鍊沒有問題，問題在於能量之源。', `MaleText_loc7`='Tal y como imaginé: las gemas y el collar no importan. Lo que importa es la fuente de alimentación.' WHERE `ID`=3091;
