UPDATE `locales_broadcast_text` SET `MaleText_loc1`='참으로 기막힌 아이러니군. 도시를 지키다 쓰러져간 스톰윈드의 군대가 다시 일어나 결사단 편에서 파괴의 앞잡이가 되어 싸우다니.', `MaleText_loc4`='真是讽刺——暴风城在紧缩防御，仅仅是为了对付小小的迪菲亚兄弟会。', `MaleText_loc5`='多甜美的諷刺─暴風城在緊縮城市的防禦，因為那些死去的守衛全都爬起來與迪菲亞兄弟會一同作戰，成為毀滅的工具。', `MaleText_loc7`='Qué ironía: Las fuerzas de Ventormenta han sido diezmadas durante la defensa de su ciudad, para después levantarse y luchar junto a la hermandad como instrumentos de destrucción.' WHERE `ID`=3095;
