UPDATE `locales_broadcast_text` SET `MaleText_loc1`='루시우스는 라벤홀트 장원의 오랜 친구로 믿을 수 있는 사람이지. 루시우스와 난 할 얘기가 많소. 내 도움이나 조언이 필요하거든 호숫골의 부두로 날 찾아오시오.', `MaleText_loc4`='卢修斯是拉文霍德庄园的老朋友了——我和他有很多事情要说。如果你需要我的帮助，那就去湖畔镇的码头找我。', `MaleText_loc5`='盧修斯是拉文霍德莊園的老朋友了─我和他有很多事情要說。如果你需要我的幫助，那就去湖畔鎮的碼頭找我。', `MaleText_loc7`='Lucius es un viejo amigo de la Casa Ravenholdt, tengo mucho que hablar con él. Si alguna vez necesitas de mi ayuda o consejo, me encontrarás en los muelles de Villa del Lago.' WHERE `ID`=3132;
