UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으스러진 손의 잔도잔이라고 하오. 나, 잔도잔이 뭘 도와주면 되겠소? 솔직히 이 잔도잔 할까 말까 고민 중이오!', `MaleText_loc4`='碎手氏族的赞杜沙。赞杜沙怎么会帮你？他不能！也绝对不会！', `MaleText_loc5`='破碎之手氏族的贊杜沙。贊杜沙怎麼可以幫你?他不能!也絕對不會!', `MaleText_loc7`='Zando''zan de los Mano Destrozada. ¿En qué puede ayudarte Zando''zan? ¡No puede! ¡No lo hará!' WHERE `ID`=3144;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요, 잔도잔. 자물쇠 따기 기술을 배우고 싶습니다.', `MaleText_loc4`='你好，赞杜沙，我想要学习开锁技能。', `MaleText_loc5`='你好，贊杜沙，我想要學習開鎖技能。', `MaleText_loc7`='Hola, Zando''zan, quiero aprender a forzar cerraduras.', `FemaleText_loc1`='안녕하세요, 잔도잔. 자물쇠 따기 기술을 배우고 싶습니다.', `FemaleText_loc4`='你好，赞杜沙，我想要学习开锁技能。', `FemaleText_loc5`='你好，贊杜沙，我想要學習開鎖技能。', `FemaleText_loc7`='Hola, Zando''zan, quiero aprender a forzar cerraduras.' WHERE `ID`=3145;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련을 받으러 온 것인가? 아니면 여기서 전사의 귀중한 시간을 허비하러 온 것인가?', `MaleText_loc4`='你是来接受训练，还是来浪费一个战士的时间的？', `MaleText_loc5`='你是來接受訓練，還是來浪費一個戰士的時間的?', `MaleText_loc7`='¿Has venido para recibir instrucción? ¿O solo has venido para hacer perder el tiempo a un guerrero?', `FemaleText_loc1`='훈련을 받으러 온 것인가? 아니면 여기서 전사의 귀중한 시간을 허비하러 온 것인가?', `FemaleText_loc4`='你是来接受训练，还是来浪费一个战士的时间的？', `FemaleText_loc5`='你是來接受訓練，還是來浪費一個戰士的時間的?', `FemaleText_loc7`='¿Has venido para recibir instrucción? ¿O solo has venido para hacer perder el tiempo a una guerrera?' WHERE `ID`=3146;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전사 훈련을 받고 싶습니다.', `MaleText_loc4`='我需要进行战士技能的训练。', `MaleText_loc5`='我需要進行戰士技能的訓練。', `MaleText_loc7`='Necesito instrucción en el arte de la guerra.', `FemaleText_loc1`='전사 훈련을 받고 싶습니다.', `FemaleText_loc4`='我需要进行战士技能的训练。', `FemaleText_loc5`='我需要進行戰士技能的訓練。', `FemaleText_loc7`='Necesito instrucción en el arte de la guerra.' WHERE `ID`=3147;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='손을 대자 기계가 살아난 듯이 움직입니다.', `MaleText_loc4`='这台机器开始运转了。', `MaleText_loc5`='這台機器開始運轉了。', `MaleText_loc7`='La máquina cobra vida en cuanto la tocas.' WHERE `ID`=3148;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='''도둑 도구''라고 쓰인 노란 단추를 누르십시오.', `MaleText_loc4`='按下贴着“盗贼工具”标签的黄色按钮。', `MaleText_loc5`='按下貼著「盜賊工具」標籤的黃色按鈕。', `MaleText_loc7`='Pulsa el botón amarillo con el rótulo ‘Herramientas de ladrones’.', `FemaleText_loc1`='''도둑 도구''라고 쓰인 노란 단추를 누르십시오.', `FemaleText_loc4`='按下贴着“盗贼工具”标签的黄色按钮。', `FemaleText_loc5`='按下貼著「盜賊工具」標籤的黃色按鈕。', `FemaleText_loc7`='Pulsa el botón amarillo con el rótulo ‘Herramientas de ladrones’.' WHERE `ID`=3149;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그가 벌꿀술도 갖다 주고$B맥주도 갖다 줄 것이라네.$B입이 귀에 걸리도록 히죽대고 있는 얼굴$B해마다 변함없이 우리를 기쁘게 한다네.$B우리는 그를 유쾌한 짐이라 부른다네.', `MaleText_loc4`='他给你蜂蜜酒$b$b他给你啤酒$b$b他总是过着快乐的生活$b$b这么多年他为我们每个人都服务过$b我们叫他微笑的吉姆。', `MaleText_loc5`='他給你蜂蜜酒$b$b他給你啤酒$b$b他總是過著快樂的生活$b$b這麼多年他為我們每個人都服務過$b我們叫他微笑的吉姆。', `MaleText_loc7`='Te traerá hidromiel$bTe traerá cerveza$bUna sonrisa de oreja a oreja$bNos ha servido de año en año$bLo llamamos Jim Sonrisas.' WHERE `ID`=3161;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='텔드랏실의 다른 곳에서는 볼 수 없는 아주 특이한 식물입니다.', `MaleText_loc4`='这是一种非常奇怪的植物，你从未在泰达希尔的其它地方见过。', `MaleText_loc5`='這是一種非常奇怪的植物，你從未在泰達希爾的其他地方見過。', `MaleText_loc7`='He aquí un ejemplar exótico de nuestra flora, desconocido en otros lugares de Teldrassil.' WHERE `ID`=3162;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 식물은 신기한 보라색 광채를 내뿜기 때문에 텔드랏실의 다른 식물들보다 눈에 잘 띄고 있습니다.', `MaleText_loc4`='这个植物矗立在泰达希尔的普通植物之间，散发着奇异的紫色光芒。', `MaleText_loc5`='這個植物矗立在泰達希爾的普通植物之間，散發著奇異的紫色光芒。', `MaleText_loc7`='Esta planta destaca entre la flora normal de Teldrassil y emite un extraño brillo violáceo.' WHERE `ID`=3163;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꽥꽥! 나 앵무새, 너 쪼아줄 거야!', `MaleText_loc4`='哇！波利要捏碎你！', `MaleText_loc5`='哇!波利要捏碎你!', `MaleText_loc7`='¡KRUAAAAC! ¡Polly quiere partirte en dos!' WHERE `ID`=3164;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 뭐야? 꽥꽥? 꽥꽥, 꽥꽥, 꽥꽥? 꽤애액!', `MaleText_loc4`='哇！哇哇！哇！', `MaleText_loc5`='哇!哇哇!哇!', `MaleText_loc7`='¿¿K.. kruaac?? ¿Kruaaac, kruaaac, kruaaac? ¡KRUAAAAC!' WHERE `ID`=3165;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='''E.C.A.C.''라고 쓰인 빨간 단추를 누르십시오.', `MaleText_loc4`='按下贴着“大饼干”标签的红色按钮。', `MaleText_loc5`='按下貼著「大餅乾」標籤的紅色按鈕。', `MaleText_loc7`='Pulsa el botón rojo con el rótulo ‘G.E.A.Q.’.', `FemaleText_loc1`='''E.C.A.C.''라고 쓰인 빨간 단추를 누르십시오.', `FemaleText_loc4`='按下贴着“大饼干”标签的红色按钮。', `FemaleText_loc5`='按下貼著「大餅乾」標籤的紅色按鈕。', `FemaleText_loc7`='Pulsa el botón rojo con el rótulo ‘G.E.A.Q.’.' WHERE `ID`=3166;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음, 음... 막대한 화학 조미료가 첨가된 과자...', `MaleText_loc4`='嗯……大量的化学变化……', `MaleText_loc5`='嗯...大量的化學變化...', `MaleText_loc7`='Mmmmm. Mmmmm... Enorme galleta químicamente alterada...' WHERE `ID`=3167;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s 안에 부서진 뼛조각과 과자 부스러기가 버려져 있습니다.', `MaleText_loc4`='%s血肉模糊。', `MaleText_loc5`='%s被碎骨和餅乾屑弄得亂七八糟。', `MaleText_loc7`='%s está mezclada con huesos molidos y migajas de galleta.' WHERE `ID`=3168;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='과자 부스러기 몇 조각과 커다란 녹색 깃털을 빼고 %s 안이 텅 비어 있습니다.', `MaleText_loc4`='%s中除了一些碎屑和一根巨大的绿色羽毛之外别无他物。', `MaleText_loc5`='%s完全空了，只剩下一些碎屑，還有一根巨大的綠色羽毛。', `MaleText_loc7`='%s está vacía, exceptuando unas cuantas migajas y una pluma verde gigantesca.' WHERE `ID`=3169;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꽥!', `MaleText_loc4`='哇！', `MaleText_loc5`='哇!', `MaleText_loc7`='¡¡¡KRUAAAAC!!!' WHERE `ID`=3170;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잊지 말고 레닉스의 기계장치에서 도둑 도구와 E.C.A.C.를 받아가시오. 임무를 완수하는 데 꼭 필요할 거요.', `MaleText_loc4`='别忘了在我的机械设备中拿取一份大饼干和盗贼工具，你的任务需要使用这两件东西！', `MaleText_loc5`='別忘了在我的機械設備中拿取一份大餅乾和盜賊工具，你的任務需要使用這兩件東西!', `MaleText_loc7`='Asegúrate de visitar el Gizmotronic Apparatus para coger una ganzúa y una G.E.A.Q. ¡Definitivamente necesitarás ambas cosas para completar tu misión!' WHERE `ID`=3171;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까. 저의 역할은 아제로스 세계에 창조주가 행한 토석인 합성에 대한 정보를 이용할 수 있게 해주는 일과 권한이 허용된 분에게 이 정보에 대한 지식을 제공하는 것입니다. 원하면 언제든지 정보를 이용할 수 있습니다.', `MaleText_loc4`='你好。我的职责在得到允许的情况下，根据艾泽拉斯的造物者对于土灵的分析，向来访者提供相关的信息。我随时都可以与你分享这些信息。', `MaleText_loc5`='你好。我的職責在得到允許的情況下，根據艾澤拉斯的造物者對於土靈的分析，向來訪者提供相關的資訊。我隨時都可以與你分享這些資訊。', `MaleText_loc7`='Saludos. Mi función consiste en proporcionar acceso y, si es admisible, explicaciones sobre la síntesis de terráneos por parte de los Creadores del lugar conocido como Azeroth. Esto listo para compartir esta información contigo cuando lo desees.' WHERE `ID`=3172;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='토석인이란 창조주가 합성한 종족의 하나로서 아제로스 세계의 초기 모태 종족 중 하나였습니다. 창조주는 이 세계의 기반을 만들 때 자신의 수고를 덜기 위하여 토석인을 창조했습니다.$B$B토석인은 창조주가 다른 세계에서 종족을 퍼뜨릴 때 사용한 지하 생물의 모형을 수정한 것입니다. 이들 원형 종족이 최초로 합성된 이후 다양한 변종이 태어났습니다.', `MaleText_loc4`='土灵是造物者设计的综合产物，并作为艾泽拉斯开始的几个种族之一。土灵被用于帮助造物者改善这个世界。$B$B他们是造物者在其它世界中设计的标准地下生物的改良型态。在最初的结构得以确定之后，这种原型产生了很多的变化。', `MaleText_loc5`='土靈是造物者設計的綜合產物，並作為艾澤拉斯開始的幾個種族之一。土靈被用於幫助造物者改善這個世界。$B$B他們是造物者在其他世界中設計的標準地下生物的改良形態。在最初的結構得以確定之後，這種原型產生了很多的變化。', `MaleText_loc7`='Los terráneos son una raza sintética que ha sido diseñada por los Creadores y que actúa como una de las razas originales que poblaron el mundo conocido como Azeroth. Los terráneos fueron creados para ayudar a los Creadores en la colonización de las regiones más recónditas de este mundo.$B$BSon una variante de matriz de ente subterráneo utilizado en otros mundos fundados por los Creadores. La construcción de esta raza prototipo produjo varias anomalías que se manifestaron tras la síntesis inicial.' WHERE `ID`=3173;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지하 생물 모형이란 창조주께서 이 세계에 종족을 퍼뜨릴 때 사용했던 합성 모형 중 하나입니다. 각각의 합성 모형을 사용해, 창조주는 자신의 목표를 이루었습니다. 아제로스의 경우 지하 생물 모형을 개조하여 내구력이 뛰어나고 지하 건설 작업에 적합한 생물을 창조했습니다. 토석인이 바로 이러한 모형 개조의 결과물입니다.$B$B그런데 이 토석인이 창조주를 위한 작업에 투입된 이후, 극한 환경의 영향으로 인해 그 합성 모형에 예상하지 못한 부작용들이 나타났습니다.', `MaleText_loc4`='它是造物者在开创世界的时候创建的最早的一个物种。造物者所创建的每种生物都肩负了一定的使命。对于艾泽拉斯来说，必须改造原有的标准地下生物构造，使其适应地下深处的生活，土灵就是这种改造的产品。$B$B在土灵被创造出来之后，由于巨大的环境压力，它们出现了许多事先无法预见的变化。', `MaleText_loc5`='它是造物者在開創世界的時候創建的最早的一個物種。造物者所創建的每種生物都肩負了一定的使命。對於艾澤拉斯來說，必須改造原有的標準地下生物構造，使其適應地下深處的生活，土靈就是這種改造的產品。$B$B在土靈被創造出來之後，由於巨大的環境壓力，它們出現了許多事先無法預見的變化。', `MaleText_loc7`='Se trata de una de las matrices de síntesis que los Creadores usaron durante la creación de uno de los mundos. Cada matriz de síntesis sirve para lograr los objetivos de los Creadores. En el caso de Azeroth, se modificó una matriz de ente subterráneo para crear un ser con una mayor durabilidad, compatible con la configuración profunda de las regiones. Los terráneos son el producto de esta modificación.$B$BCuando los terráneos fueron activados por los Creadores, presentaron anomalías no previstas que afectaron a sus matrices de síntesis debido al efecto de entornos de tensión excesiva.' WHERE `ID`=3174;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 질문에 대답하려면 먼저 토석인에 대한 자세한 설명이 필요할 것 같습니다.$B$B처리 중...$B$B토석인에게 나타난 부작용을 이해하기 위해서는 먼저 토석인의 설계 목적을 이해하는 것이 중요합니다. 토석인은 지하 생물 모형의 생존 능력을 향상시키고자 하는 창조주의 뜻에 따라 설계된 것이며, 아제로스에 함유된 탄력적인 조성 물질을 지하 생물 모형에 더해 만들었습니다.', `MaleText_loc4`='在正确回答这个问题之前，需要向你介绍更多关于土灵的背景资料。$B$B资料处理中。$B$B为了理解土灵的变化，首先要了解土灵的设计特征。创世者的目的是要提高标准地下生物母体的存活性，因此他们把与整个世界相联系的弹性构造基础整合在其中，土灵的出现正是为了达到这一目的。', `MaleText_loc5`='在正確回答這個問題之前，需要向你介紹更多關於土靈的背景資料。$B$B資料處理中。$B$B為了理解土靈的變化，首先要瞭解土靈的設計特徵。創世者的目的是要提高標準地下生物母體的存活性，因此他們把與整個世界相聯繫的彈性構造基礎整合在其中，土靈的出現正是為了達到這一目的。', `MaleText_loc7`='Antes de poder responder adecuadamente a esta pregunta, recibirás información adicional sobre los terráneos.$B$BProcesando.$B$BPara comprender las anomalías de los terráneos, antes hay que entender lo que ellos representaron en la fase de diseño. Los terráneos representan el intento de los Creadores de mejorar el paradigma de supervivencia estándar de la matriz de ente subterráneo. Esto se llevó a cabo incorporando bases resistentes de construcción inherentes al mundo en la mencionada matriz.' WHERE `ID`=3175;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탄력적인 조성 물질이란 종족 합성 시 사용되는 기본 성분을 말합니다. 창조주는 토석인을 합성하고자 일반적인 유기 조성 물질 대신 아제로스 지반을 구성하는 물질을 사용했습니다.$B$B창조주는 아제로스의 조성에 대해 연구한 끝에, 아제로스 본질의 탄력적인 전형이 될 수 있는 고급 생명체를 합성할 수 있다는 이론을 세웠습니다. 창조주는 그 이론에 따라 아제로스에 있는 다양한 바위의 핵심 성분을 기초로 하여 더욱 향상된 생명체를 만들었습니다.', `MaleText_loc4`='所谓弹性构造基础就是指用于种族合成的基本材料。造物者在创造土灵的时候放弃了以前创造世界时一直使用的基础材料，转而使用这种常见于艾泽拉斯的材料。$B$B通过对世界组成成分的分析，造物者认为可以合成一种加强型的生物，将它作为世界本质的缩影。造物者最终通过混合艾泽拉斯大陆上各种不同的石头成分，最后组成了这样一种生物的构造基础。', `MaleText_loc5`='所謂彈性構造基礎就是指用於種族合成的基本材料。造物者在創造土靈的時候放棄了以前創造世界時一直使用的基礎材料，轉而使用這種常見於艾澤拉斯的材料。$B$B通過對世界組成成分的分析，造物者認為可以合成一種加強型的生物，將它作為世界本質的縮影。造物者最終通過混合艾澤拉斯大陸上各種不同的石頭成分，最後組成了這樣一種生物的構造基礎。', `MaleText_loc7`='Se trata del material básico utilizado en la síntesis de razas. Se empleó un corte transversal de la corteza de Azeroth como base de síntesis de los terráneos, en lugar de la base de construcción de biomasa típica utilizada por los Creadores.$B$BUna investigación sobre la composición del mundo permitió a los Creadores formular la teoría de que se podía sintetizar un ser mejorado que pudiera personificar la resistencia esencial de este mundo. Esto se logró eligiendo como base una mezcla de varios compuestos de núcleo mineral de Azeroth.' WHERE `ID`=3176;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='단순하게 말하자면 그렇습니다.$B$B토석인의 신체는 신장이 작은 인간형 생물과 비슷하지만, 토석인을 이루고 있는 것은 아제로스에 있는 여러 가지 바위의 핵심 성분입니다. 토석인은 지적 처리 능력을 크게 떨어뜨리지 않고도 체력을 극대화하는 방식으로 설계되었습니다. 피부와 근육조직은 물리적 손상에 거의 영향을 받지 않으며, 아주 사소한 개조 단계만 거치면 마력에 대해 놀라운 저항 능력을 보입니다.', `MaleText_loc4`='简单地说，事实确实如此。$B$B虽然土灵的外表看上去像是一个小型的人型生物，但它们包含了艾泽拉斯大陆上各种石头的成分。它们在得到了力量和耐力最大化的同时也没有牺牲敏锐的感觉。它们的皮肤和肌肉的设计使其几乎完全免疫物理伤害，而且只需进行非常小的改动，土灵就可以展现出惊人的魔法抗性。', `MaleText_loc5`='簡單地說，事實確實如此。$B$B雖然土靈的外表看起來像是一個小型的人形生物，但它們包含了艾澤拉斯大陸上各種石頭的成分。它們在得到了力量和耐力最大化的同時也沒有犧牲敏銳的感覺。它們的皮膚和肌肉的設計使其幾乎完全免疫物理傷害，而且只需進行非常小的改造，土靈就可以展現出驚人的魔法抗性。', `MaleText_loc7`='En otras palabras, esto es correcto.$B$BLas características físicas de los terráneos son las de un humanoide de menor estatura, si bien su composición es la de varios compuestos de núcleo mineral de Azeroth. Su diseño potencia la fuerza y la energía sin sacrificar la capacidad de procesamiento cognitivo. Su piel y musculatura son prácticamente inmunes al daño físico y, una vez sometidos a cualquier modificación insignificante, los terráneos muestran una notable resistencia a fuerzas mágicas no deseadas.' WHERE `ID`=3177;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 정보를 완전히 이해하기 위해서는 먼저 알아두어야 할 사실이 있습니다. 창조주는 자신이 떠난 후에도 오랫동안 이 세계의 발전에 중요한 역할을 해줄 종족을 창조하고자 했습니다. 그래서 장기적으로 아제로스 발전에 중요한 존재가 될 종족을 만들었습니다.$B$B참고로 "토석인"이라는 이름은 창조주가 토석인을 만들 때 사용한 구성 물질을 고려하여, 이 종족에게 적절하다고 판단되는 명칭을 직접 붙인 것입니다.', `MaleText_loc4`='以上这些内容是用来帮助你理解创世者的动机。他们创造出土灵这样一个物种是为了在他们离开之后，土灵可以成为这个世界中的一个重要部分，并保障创世者在艾泽拉斯世界的宏大计划得以继续实施。$B$B创世者对于“土灵”这个名字十分满意，因为它很好地体现了这个种族的基本特性。', `MaleText_loc5`='以上這些內容是用來幫助你理解創世者的動機。他們創造出土靈這樣一個物種是為了在他們離開之後，土靈可以成為這個世界中的一個重要部分，並保障創世者在艾澤拉斯世界的宏大計畫得以繼續執行。$B$B創世者對於「土靈」這個名字十分滿意，因為它很好地體現了這個種族的基本特性。', `MaleText_loc7`='Para asimilar esta información, es preciso comprender que los Creadores querían sintetizar una raza que, tras su partida, constituyera por mucho tiempo una parte integral del ciclo de desarrollo de este mundo. Esta raza constituiría un instrumento para alcanzar los objetivos de desarrollo a largo plazo que los Creadores tenían en relación con Azeroth. $B$BCabría añadir que la denominación "terráneo" fue considerada adecuada por los Creadores, ya que hacía referencia a su composición.' WHERE `ID`=3178;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='토석인 창조 시 나타난 유일한 부작용은 극도로 극한 환경에 처할 경우, 모형이 불안정해지는 경향이 있다는 것입니다.$B$B참고로 새로운 모형을 설계할 때, 지반 건설 작업은 극도로 긴장되는 환경을 복제하는 데 필요한 요구 사항을 충족시키지 못했습니다. 그러므로 초기에 부작용을 예상하지 못한 것은 당연합니다.$B$B불안정화 경향이 발견된 것은 토석인을 본격적으로 투입한 훨씬 다음의 일이었습니다. 창조주는 불안정화 경향이 나타나는 토석인을 모아 다시 합성하지 않았고, 합성 후 수정이라는 방식으로 토석인을 수정하기 시작했습니다.', `MaleText_loc4`='土灵唯一的异常变化是在高压环境下对于母体扰动的趋向。$B$B附录：设计的目的是让该物种能够适合地下深处的生活，从而无法满足高压环境下的适应性要求。$B$B这种扰动直到土灵按照计划进入世界的主循环之后才被发现。造物者并没有将土灵召回再重新进行改造，而是直接对其进行了实时的改造。', `MaleText_loc5`='土靈唯一的異常變化是在高壓環境下使用時容易使基質失序。$B$B附錄:原基質的設記是適合地底雕塑，因此從未進行高壓環境複製測試。$B$B這種失序直到土靈首度進入服務循環之後才被發現。造物者開始對土靈進行成體改造，而非將之召回並重新設計。', `MaleText_loc7`='La única anomalía en la síntesis de los terráneos es la tendencia a la desestabilización de la matriz cuando se los utiliza en entornos sometidos a grandes dosis de tensión.$B$BApéndice: la escultura profunda en barro resultaba adecuada al nuevo diseño de matriz y nunca se ajustó a los requerimientos de duplicación de un entorno sometido a altos niveles de tensión.$B$BLa desestabilización no se detectó sino hasta bien avanzado el ciclo primario de funcionamiento de los terráneos. Los Creadores empezaron a trabajar en modificaciones post síntesis, en lugar de proceder a la retirada y a la resíntesis.' WHERE `ID`=3179;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[질문을 한 후 꽤 오래 시간이 지난 후...]$B$B현재 요청하신 정보는 본 정보 저장소의 자료에서 찾을 수 없습니다. 원하시는 정보를 제공하지 못한 데 대해 진심으로 사과 드립니다.$B$B본 정보 저장소의 자료 주기가 경신된 후에 요청하십시오. 아제로스에 있는 다른 정보 저장소에서 요청하실 수도 있습니다.', `MaleText_loc4`='[当你问了这个问题之后，它明显地停顿了一会儿]$B$B你需要的信息无法在该数据库中获取。对此我表示歉意。$B$B你可以在数据更新之后再次查询该信息，或者从艾泽拉斯的其它信息数据库处获得更多信息。', `MaleText_loc5`='[當你問了這個問題之後，它明顯地停頓了一會兒]$B$B你需要的資訊無法在該資料庫中獲取。對此我表示歉意。$B$B你可以在資料更新之後再次查詢該資訊，或者從艾澤拉斯的其他資訊資料庫處獲得更多資訊。', `MaleText_loc7`='[Se produce una pausa evidente tras formular esta pregunta.]$B$BLa información que solicitas no está actualmente disponible en este ciclo del depósito de datos. Realmente lamentamos esta omisión.$B$BSolicita esta información una vez que se haya realizado la actualización del ciclo de datos en este depósito de información. También puede solicitar esta información en otro depósito de información situado en Azeroth.' WHERE `ID`=3180;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='토석인의 합성 모형이 불안정해지면 두 가지 결과가 나타날 수 있습니다. 시청각 자료 1번의 설명을 시작합니다...$B$B부작용의 결과, 첫 번째로 변형된 모형은 조합의 퇴행적 산물입니다. 일반적으로 "트로그"라는 명칭으로 불립니다. 이 변형체는 체력이 토석인과 비슷하나 지적 처리 능력은 거의 없는 것으로 판단됩니다. 따라서 트로그의 정신을 움직이는 것은 욕심, 의지, 그리고 교활함 뿐입니다.', `MaleText_loc4`='当土灵的合成母体不稳定的时候，产生了两个变种。一号教程图像正在初始化。$B$B第一类变种被称为“穴居人”。这个变种保留了土灵的力量和耐力，但是它的感知力量完全丧失。欲望和狡诈成为了穴居人的本能。', `MaleText_loc5`='當土靈的合成母體不穩定的時候，產生了兩個變種。一號教程圖像正在初始化。$B$B第一類變種被稱為「穴居怪」。這個變種保留了土靈的力量和耐力，但是它的感知力量完全喪失。欲望和狡詐成為了穴居怪的本能。', `MaleText_loc7`='"Existen dos resultados potenciales cuando la matriz de síntesis de terráneos se desestabiliza. Iniciando representación de ayuda visual número uno.$B$BLa primera matriz de variante es un producto degenerativo de síntesis, denominada en este caso con la nomenclatura común de "trogg". Esta variante mantiene una fuerza y una resistencia comparables a las de los terráneos, pero su potencia de procesamiento cognitivo ha experimentado serios problemas. La fuerza de voluntad y una notable astucia son los únicos factores que mueven la psique de un trogg."' WHERE `ID`=3181;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사용자의 연대기적 발언을 본 자료의 기록에 비교하여 실행할 수 없습니다. 죄송합니다.$B$B트로그의 구성 성분 중에도 아제로스의 여러 가지 바위에서 추출한 핵심 성분이 일부 들어 있으나, 지적 처리 능력의 부족으로 인해 이 변형체는 창조주를 만족시키지 못했습니다.$B$B트로그는 표준적인 생물로 번식했습니다. 하지만, 트로그는 기본적으로 다른 트로그를 포함해 바위와 손에 잡을 수 있는 건 무엇이든 먹어 치웁니다. 창조주는 동족을 잡아먹는다는 점을 받아들일 수 없었던 것입니다.', `MaleText_loc4`='抱歉，我无法将现有记录数据按照时间顺序进行排序。$B$B虽然穴居人仍然包含了艾泽拉斯的各种石头的核心成分，但是它们感知能力的丧失是造物者无法接受的。$B$B穴居人可以进行单体繁殖。它们会把所有的东西当作食物，包括石头，甚至是另外一个穴居人。这样的同类相残是造物者极度反感的。', `MaleText_loc5`='抱歉，我無法將現有記錄資料按照時間順序進行排序。$B$B雖然穴居怪仍然包含了艾澤拉斯的各種石頭的核心成分，但是它們感知能力的喪失是造物者無法接受的。$B$B穴居怪可以進行單體繁殖。它們會把所有的東西當作食物，包括石頭，甚至是另外一個穴居怪。這樣的同類相殘是造物者極度反感的。', `MaleText_loc7`='Me resulta imposible procesar su referencia cronológica en comparación con el registro de este dato, acepte mis disculpas.$B$BEl trogg retiene parte de la composición de los diferentes compuestos del centro de la piedra de Azeroth, pero la pérdida de poder cognitivo convierte a esta variante en inaceptable para los Creadores.$B$BEl trogg se procrea según una biomasa estándar. Por defecto consume piedra y cualquier otra cosa que pueda conseguir, incluyendo otros troggs. Los Creadores consideran inaceptable el canibalismo.' WHERE `ID`=3182;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시청각 자료 2번의 설명을 시작하겠습니다...$B$B토석인 모형에서 변형된 두 번째 생물은 표준 지하 생물 모형과 비교해 볼 때 바람직한 요소를 많이 지니고 있습니다. 이 변형 생물의 일반 명칭은 "드워프"입니다.$B$B드워프는 토석인 고유의 체력을 지니고 있습니다. 어떤 경우 토석인 모형의 지적 처리 능력을 능가하기도 합니다. 그러나 드워프에게는 아제로스의 여러 가지 바위에서 추출한 핵심 성분이 전혀 없습니다.', `MaleText_loc4`='二号教程图像正在初始化。$B$B土灵母体的第二个变种和标准的地下生物母体相比较而言，保留了很多必要的元素。这个种族被称作“矮人”。$B$B这个变种同样保留了土灵的力量和耐力。在某些方面，矮人甚至超过了土灵母体所具有的感知能力。但是，矮人这个变种的身体结构中已经完全没有了石质成分的踪迹。', `MaleText_loc5`='二號教程圖像正在初始化。$B$B土靈母體的第二個變種和標準的地下生物母體相比較而言，保留了很多必要的元素。這個種族被稱作「矮人」。$B$B這個變種同樣保留了土靈的力量和耐力。在某些方面，矮人甚至超過了土靈母體所具有的感知能力。但是，矮人這個變種的身體結構中已經完全沒有了石質成分的蹤跡。', `MaleText_loc7`='Iniciando representación de ayuda visual número dos.$B$BLa segunda variante de resultado de la matriz de terráneos retiene numerosos elementos deseados cuando se los compara con la matriz subterránea estándar. La nomenclatura común para esta variante es "Enano".$B$BEsta variante conserva la fortaleza y la resistencia inherente a los terráneos. En algunos casos, el enano presenta incluso poderes cognitivos superiores a los de la matriz de los terráneos. No obstante, el enano no presenta la composición física de los compuestos del núcleo mineral de Azeroth."' WHERE `ID`=3183;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='본 정보 저장소에 보관된 자료 내용과 방금 말씀하신 예리한 발언은 분명히 유효한 상관관계가 있습니다.$B$B드워프를 이루는 구성 성분은 아제로스의 돌과 관련이 있습니다. 그러나 극한 환경에 처하면 토석인의 조합 모형 내에서 부작용이 발생해 표준 지하 생물 모형에서 볼 수 있는 기본적인 생물 자원으로 퇴화하게 됩니다.$B$B그러므로 미루어 짐작하고 계셨듯이, 드워프 변형체는 토석인 합성 모형이 퇴화한 결과물입니다.', `MaleText_loc4`='你的问题在数据库中有相关联接。$B$B矮人依然和艾泽拉斯的各种石头有着密切的关系，但是由于土灵在高压环境下的变异，矮人的结构与标准地下生物母体的结构保持了一致。$B$B因此，正如你所猜想的那样，矮人确实是从母体中变异出来的。', `MaleText_loc5`='你的問題在資料庫中有相關聯接。$B$B矮人依然和艾澤拉斯的各種石頭有著密切的關係，但是由於土靈在高壓環境下的變異，矮人的結構與標準地下生物母體的結構保持了一致。$B$B因此，正如你所猜想的那樣，矮人確實是從母體中變異出來的。', `MaleText_loc7`='Los datos almacenados en este depósito efectivamente se relacionan con tu astuta afirmación.$B$BEl enano guarda afinidad con la composición mineral de Azeroth, pero debido a anomalía medioambiental relacionada con las tensiones elevadas de la matriz de síntesis de los terráneos, el enano vuelve a una composición de biomasa predeterminada como la que se observa en la matriz subterránea estándar.$B$BPor esta razón, la variante de enano se sintetiza a partir de la degeneración de la matriz de creación de terráneos, tal y como has deducido en tu consulta.' WHERE `ID`=3184;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사용자의 연대기적 발언을 본 자료의 기록에 비교하여 실행할 수 없습니다. 죄송합니다.$B$B드워프의 정신적인 부분은 아제로스의 돌 구성에 거의 비슷하게 맞추어져 있습니다. 그러나 살아 있는 생물 자원으로 퇴행한 결과, 퇴화한 모형이 주된 부분을 이루고 있습니다. 드워프는 다른 표준 생물에서 흔히 볼 수 있는 방법으로 영양분을 섭취하여 번식합니다.$B$B창조주는 나름대로 가치가 있는 만족스러운 변형체로 드워프를 인식하고 있습니다.', `MaleText_loc4`='抱歉，我无法将现有记录数据按照时间顺序进行排序。$B$B虽然矮人还是和艾泽拉斯的各种石头有着某种联系，但是他们更多的是向普通的地下物种发展。矮人的生活习性和繁衍方式都和其它的标准生物完全一致。$B$B造物者认为矮人是一种可以接受的变种，可以让其继续发展下去。', `MaleText_loc5`='抱歉，我無法將現有記錄資料按照時間順序進行排序。$B$B雖然矮人還是和艾澤拉斯的各種石頭有著某種聯繫，但是他們更多的是向普通的地下物種發展。矮人的生活習性和繁衍方式都和其他的標準生物完全一致。$B$B造物者認為矮人是一種可以接受的變種，可以讓其繼續發展下去。', `MaleText_loc7`='No puedo procesar tu referencia cronológica en comparación con el registro de estos datos. Lo siento mucho.$B$BA pesar de que el enano conserva gran parte de la afinidad mental de los terráneos con la composición mineral de Azeroth, el retorno a la biomasa viviente constituye la mayor degeneración de la matriz. Los enanos se alimentan y procrean utilizando los medios típicos de otras biomasas estándar.$B$BLos Creadores ven al enano como variante aceptable, con su propio derecho de génesis.' WHERE `ID`=3185;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='창조주는... 말 그대로 창조주입니다.$B$B창조주는 자신이 계획하고 설계한 그대로 이 세계를 만들고 종족을 퍼뜨렸습니다. 이 세계가 존재하는 근원은 창조주입니다. 물론 다른 수많은 세계가 존재하게 한 장본인이기도 합니다. 즉 아제로스를 창조한 근원인 것입니다.', `MaleText_loc4`='造物者就是……造物者。$B$B他们根据自己的设计来创造和改变这个世界。他们是这个世界出现的原因，他们是艾泽拉斯的创造者。', `MaleText_loc5`='造物者就是...造物者。$B$B他們根據自己的設計來創造和改變這個世界。他們是這個世界出現的原因，他們是艾澤拉斯的創造者。', `MaleText_loc7`='Los Creadores son... los Creadores.$B$BSon los seres que fundaron y configuraron este mundo de acuerdo con su propio diseño. Son la razón de la existencia de este mundo, así como la de muchos otros mundos. Son la fuente desde la cual fluye Azeroth.' WHERE `ID`=3186;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='창조주 또한 본 저장소에 보관된 정보가 방대하다는 사실을 인식하고 있습니다. 노르간논의 원반만 맞춘다면 이곳에 저장된 자료의 복사본을 이용하실 수 있습니다.$B$B이제 당신은 본 정보를 이해하기 위한 최소한의 요구 사항은 모두 갖추었습니다. 원하시는 때 노르간논의 원반에 접속해 원반을 조합하기만 하면 됩니다.', `MaleText_loc4`='造物者也知道这个数据库中汇集了大量的信息。所以，如果你拥有诺甘农圆盘的话，便可以得到一份所有信息的拷贝。$B$B请确认你现在没有关于这方面信息的问题了。当你找到诺甘农圆盘之后，可以随时过来制作拷贝。', `MaleText_loc5`='造物者也知道這個資料庫中彙集了大量的資訊。所以，如果你擁有諾甘農圓盤的話，便可以得到一份所有資訊的拷貝。$B$B請確認你現在沒有關於這方面資訊的問題了。當你找到諾甘農圓盤之後，可以隨時過來製作拷貝。', `MaleText_loc7`='Los Creadores conocen la magnitud de la información alojada en este depósito. A continuación, dispondrás de una copia portátil de los datos almacenados aquí una vez que entres en sintonía con los Discos de Norgannon.$B$BTen en cuenta los requisitos que deberás cumplir para garantizar la total asimilación de este conocimiento. Cuando te resulte cómodo, accede a los Discos de Norgannon para iniciar la síntesis de tus discos.' WHERE `ID`=3187;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='토석인은 누구입니까?', `MaleText_loc4`='土灵到底是什么？', `MaleText_loc5`='土靈到底是什麼?', `MaleText_loc7`='¿Quiénes son los terráneos?', `FemaleText_loc1`='토석인은 누구입니까?', `FemaleText_loc4`='土灵到底是什么？', `FemaleText_loc5`='土靈到底是什麼?', `FemaleText_loc7`='¿Quiénes son los terráneos?' WHERE `ID`=3188;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"지하 생물 모형"이란 무엇입니까?', `MaleText_loc4`='什么是“地下生物母体”？', `MaleText_loc5`='什麼是「地下生物母體」?', `MaleText_loc7`='¿Qué es una "matriz de ente subterráneo"?', `FemaleText_loc1`='"지하 생물 모형"이란 무엇입니까?', `FemaleText_loc4`='什么是“地下生物母体”？', `FemaleText_loc5`='什麼是「地下生物母體」?', `FemaleText_loc7`='¿Qué es una "matriz de ente subterráneo"?' WHERE `ID`=3189;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앞에서 말한 부작용이란 무엇입니까?', `MaleText_loc4`='你所说的变化是什么？', `MaleText_loc5`='你所說的變化是什麼?', `MaleText_loc7`='¿Cuáles son las anomalías a las que te refieres?', `FemaleText_loc1`='앞에서 말한 부작용이란 무엇입니까?', `FemaleText_loc4`='你所说的变化是什么？', `FemaleText_loc5`='你所說的變化是什麼?', `FemaleText_loc7`='¿Cuáles son las anomalías a las que se refiere?' WHERE `ID`=3190;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"탄력적인 조성 물질"이란 무엇입니까?', `MaleText_loc4`='什么是“弹性构造基础”？', `MaleText_loc5`='什麼是「彈性構造基礎」?', `MaleText_loc7`='¿Qué es una "una base resistente de construcción"?', `FemaleText_loc1`='"탄력적인 조성 물질"이란 무엇입니까?', `FemaleText_loc4`='什么是“弹性构造基础”？', `FemaleText_loc5`='什麼是「彈性構造基礎」?', `FemaleText_loc7`='¿Qué es una "una base resistente de construcción"?' WHERE `ID`=3191;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇다면... 토석인이란 돌로 만든 존재입니까?', `MaleText_loc4`='难道……土灵是用石头做出来的？', `MaleText_loc5`='難道...土靈是用石頭做出來的?', `MaleText_loc7`='Entonces... ¿los terráneos estaban hechos de piedra?', `FemaleText_loc1`='그렇다면... 토석인이란 돌로 만든 존재인가요?', `FemaleText_loc4`='难道……土灵是用石头做出来的？', `FemaleText_loc5`='難道...土靈是用石頭做出來的?', `FemaleText_loc7`='Entonces... ¿los terráneos estaban hechos de piedra?' WHERE `ID`=3192;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='토석인에 대해 더 알아야 할 것이 있습니까?', `MaleText_loc4`='还有关于土灵的其它信息吗？', `MaleText_loc5`='還有關於土靈的其他資訊嗎?', `MaleText_loc7`='¿Hay algo más que yo debería saber acerca de los terráneos?', `FemaleText_loc1`='토석인에 대해 더 알아야 할 것이 있습니까?', `FemaleText_loc4`='还有关于土灵的其它信息吗？', `FemaleText_loc5`='還有關於土靈的其他資訊嗎?', `FemaleText_loc7`='¿Hay algo más que yo debería saber acerca de los terráneos?' WHERE `ID`=3193;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 창조주께서 토석인을 창조한 의도를 이해할 것 같습니다. 그런데 앞에서 말한 토석인의 부작용이란 무엇입니까?', `MaleText_loc4`='我想我现在明白造物者设计土灵的意图了。你之前说的土灵的变化是指什么？', `MaleText_loc5`='我想我現在明白造物者設計土靈的意圖了。你之前說的土靈的變化是指什麼?', `MaleText_loc7`='Ahora sí creo comprender el intento de diseño de los Creadores en relación con los terráneos. ¿Cuáles son las anomalías de los terráneos a los que se refirió anteriormente?', `FemaleText_loc1`='이제 창조주께서 토석인을 창조한 의도를 이해할 것 같습니다. 그런데 앞에서 말한 토석인의 부작용이란 무엇입니까?', `FemaleText_loc4`='我想我现在明白造物者设计土灵的意图了。你之前说的土灵的变化是指什么？', `FemaleText_loc5`='我想我現在明白造物者設計土靈的意圖了。你之前說的土靈的變化是指什麼?', `FemaleText_loc7`='Ahora sí creo comprender el intento de diseño de los Creadores en relación con los terráneos. ¿Cuáles son las anomalías de los terráneos a los que se refirió anteriormente?' WHERE `ID`=3194;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='토석인의 불안정화를 일으키는, 극도로 긴장된 환경이란 어떤 것입니까?', `MaleText_loc4`='为什么高压环境会引起土灵的不稳定性？', `MaleText_loc5`='為什麼高壓環境會引起土靈的不穩定性?', `MaleText_loc7`='¿Qué entornos de tensión elevada podrían causar la desestabilización de los terráneos?', `FemaleText_loc1`='토석인의 불안정화를 일으키는, 극도로 긴장된 환경이란 어떤 것입니까?', `FemaleText_loc4`='为什么高压环境会引起土灵的不稳定性？', `FemaleText_loc5`='為什麼高壓環境會引起土靈的不穩定性?', `FemaleText_loc7`='¿Qué entornos de tensión elevada podrían causar la desestabilización de los terráneos?' WHERE `ID`=3195;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='토석인이 불안정해지면 어떤 일이 발생합니까?', `MaleText_loc4`='土灵不稳定时会发生什么？', `MaleText_loc5`='土靈不穩定時會發生什麼?', `MaleText_loc7`='¿Qué ocurre cuando los terráneos se desestabilizan?', `FemaleText_loc1`='토석인이 불안정해지면 어떤 일이 발생합니까?', `FemaleText_loc4`='土灵不稳定时会发生什么？', `FemaleText_loc5`='土靈不穩定時會發生什麼?', `FemaleText_loc7`='¿Qué ocurre cuando los terráneos se desestabilizan?' WHERE `ID`=3196;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='트로그라고요? 혹시 그 트로그가 현재 아제로스에서 찾아볼 수 있는 놈들과 같습니까?', `MaleText_loc4`='穴居人？！你说的穴居人难道就是现在的那种穴居人？', `MaleText_loc5`='穴居怪?!你說的穴居怪難道就是現在的那種穴居怪?', `MaleText_loc7`='¡¿Troggs?! ¿Los troggs que mencionas son los mismos que los que habitan el mundo hoy?', `FemaleText_loc1`='트로그라고요? 혹시 그 트로그가 현재 아제로스에서 찾아볼 수 있는 놈들과 같습니까?', `FemaleText_loc4`='穴居人？！你说的穴居人难道就是现在的那种穴居人？', `FemaleText_loc5`='穴居怪?!你說的穴居怪難道就是現在的那種穴居怪?', `FemaleText_loc7`='¡¿Troggs?! ¿Los troggs que mencionas son los mismos que los que habitan el mundo hoy?' WHERE `ID`=3197;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='토석인이 불안정해지면 두 가지 결과가 나타난다고 했는데 그렇다면, 그 두 번째는 무엇입니까?', `MaleText_loc4`='你提到当土灵不稳定的时候出现了两个变种。那第二个是什么？', `MaleText_loc5`='你提到當土靈不穩定的時候出現了兩個變種。那第二個是什麼?', `MaleText_loc7`='Mencionaste dos resultados que tienen lugar cuando los terráneos se desestabilizan. ¿Cuál es el segundo?', `FemaleText_loc1`='토석인이 불안정해지면 두 가지 결과가 나타난다고 했는데 그렇다면, 그 두 번째는 무엇입니까?', `FemaleText_loc4`='你提到当土灵不稳定的时候出现了两个变种。那第二个是什么？', `FemaleText_loc5`='你提到當土靈不穩定的時候出現了兩個變種。那第二個是什麼?', `FemaleText_loc7`='Mencionaste dos resultados que tienen lugar cuando los terráneos se desestabilizan. ¿Cuál es el segundo?' WHERE `ID`=3198;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드워프라고요!! 그렇다면 드워프의 조상이 토석인이라는 말입니까?', `MaleText_loc4`='矮人！！难道矮人是起源于土灵的？！', `MaleText_loc5`='矮人!!難道矮人是起源於土靈的?!', `MaleText_loc7`='¡¡¡Enanos!!! ¡¿Ahora dices que los enanos proceden originalmente de los terráneos?!', `FemaleText_loc1`='드워프라고요!! 그렇다면 드워프의 조상이 토석인이라는 말입니까?', `FemaleText_loc4`='矮人！！难道矮人是起源于土灵的？！', `FemaleText_loc5`='矮人!!難道矮人是起源於土靈的?!', `FemaleText_loc7`='¡¡¡Enanos!!! ¡¿Ahora dices que los enanos proceden originalmente de los terráneos?!' WHERE `ID`=3199;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 드워프가 현세의 드워프와 같은 종족이지요? 이 외에 드워프와 토석인 사이에 다른 연관성이 있습니까?', `MaleText_loc4`='这些矮人和现在的矮人是同一种生物吗？矮人还和土灵有其它的联系吗？', `MaleText_loc5`='這些矮人和現在的矮人是同一種生物嗎?矮人和土靈還有其他的關聯嗎?', `MaleText_loc7`='Aquellos enanos son los mismos que los que conocemos hoy, ¿no es así? ¿Los enanos mantienen algún otro vínculo con los terráneos?', `FemaleText_loc1`='이 드워프가 현세의 드워프와 같은 종족이지요? 이 외에 드워프와 토석인 사이에 다른 연관성이 있습니까?', `FemaleText_loc4`='这些矮人和现在的矮人是同一种生物吗？矮人还和土灵有其它的联系吗？', `FemaleText_loc5`='這些矮人和現在的矮人是同一種生物嗎?矮人和土靈還有其他的關聯嗎?', `FemaleText_loc7`='Aquellos enanos son los mismos que los que conocemos hoy, ¿no es así? ¿Los enanos mantienen algún otro vínculo con los terráneos?' WHERE `ID`=3200;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='창조주란 누구입니까?', `MaleText_loc4`='造物者是谁？', `MaleText_loc5`='造物者是誰?', `MaleText_loc7`='¿Quiénes son los Creadores?', `FemaleText_loc1`='창조주란 누구입니까?', `FemaleText_loc4`='造物者是谁？', `FemaleText_loc5`='造物者是誰?', `FemaleText_loc7`='¿Quiénes son los Creadores?' WHERE `ID`=3201;
