UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 기계장치를 가리킵니다.', `MaleText_loc4`='%s指了指他的机械设备。', `MaleText_loc5`='%s給你指了指他的機械設備。', `MaleText_loc7`='%s esto te conduce al Gizmotronic Apparatus.' WHERE `ID`=3203;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 폭발해서 하늘에 눈부신 불꽃놀이가 펼쳐진 듯합니다! 마치 당신에게 오라고 손짓을 하는 것 같습니다.', `MaleText_loc4`='%s发生爆炸，绚丽的焰火表演照亮了整个天空！这场景真是令人侧目啊，潜行者。', `MaleText_loc5`='%s發生爆炸，整個天空都被煙火照亮了!看起來像在對你招手，盜賊。', `MaleText_loc7`='%s explota, iluminando el cielo con el brillo de los fuegos artificiales. Es como si te estuviera llamando, pícaro.' WHERE `ID`=3204;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 열립니다. 안에는 엄청난 새의 배설물과 혈액으로 보이는 것이 들어있으며, 감각을 마비시킬 정도로 매우 고약한 악취를 풍깁니다.', `MaleText_loc4`='%s打开了，一股刺激性的恶臭扑鼻而来，你发现里面装着大量的鸟粪和鲜血。', `MaleText_loc5`='%s打開了，一股異味撲鼻而來，裡面是許多鳥糞和鮮血。', `MaleText_loc7`='%s se abre. El contenido agrede sus sentidos con un olor nauseabundo. En el interior observa lo que parecen ser enormes excrementos de pájaro y una gran cantidad de sangre.' WHERE `ID`=3205;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s 안에 곰쥐의 사체가 가득합니다. 흠...', `MaleText_loc4`='%s满是死老鼠。嗯……', `MaleText_loc5`='%s裝滿了死老鼠。嗯...', `MaleText_loc7`='%s está lleno de ratas negras muertas. Mmmm...' WHERE `ID`=3206;
