UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 원반에 접속하겠습니다.', `MaleText_loc4`='我现在就去找那张碟片。', `MaleText_loc5`='我現在就去找那張碟片。', `MaleText_loc7`='Voy a acceder a los discos ahora.', `FemaleText_loc1`='지금 원반에 접속하겠습니다.', `FemaleText_loc4`='我现在就去找那张碟片。', `FemaleText_loc5`='我現在就去找那張碟片。', `FemaleText_loc7`='Voy a acceder a los discos ahora.' WHERE `ID`=3221;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='SI:7 금고가 열리자 경보음이 울립니다.', `MaleText_loc4`='军情七处保险箱被打开了，顿时响起了警报声。', `MaleText_loc5`='軍情七處帶鎖箱打開了，然後就響起了警報聲。', `MaleText_loc7`='IV:7 la caja fuerte se abre y luego suena una alarma audible.' WHERE `ID`=3222;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='SI:7 금고에서 진동과 함께 윙윙거리는 소리가 납니다. 북쪽에서 바삭거리는 소리가 커다랗게 들립니다.', `MaleText_loc4`='军情七处保险箱开始振动，发出嗡嗡声。从北边传来了一声巨响。', `MaleText_loc5`='軍情七處帶鎖箱開始振動，發出嗡嗡的叫聲。從北邊傳來了一聲巨響。', `MaleText_loc7`='IV:7 la caja fuerte empieza a vibrar y a zumbar. Se escucha un sonido ensordecedor procedente del norte.' WHERE `ID`=3223;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='SI:7 금고가 부서지면서 열립니다. 먼 곳에서 투덜거리는 목소리가 들려옵니다.', `MaleText_loc4`='军情七处保险箱被打开了。从很远处就能听到这巨大的响动。', `MaleText_loc5`='軍情七處帶鎖箱被打開了。從很遠處就能聽到這巨大的響動。', `MaleText_loc7`='IV:7 la caja fuerte se abre estrepitosamente. Se escuchan gruñidos y voces en la distancia.' WHERE `ID`=3224;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='SI:7 금고가 삐걱 소리를 내며 열립니다. 요란하게 윙윙거리는 소리가 들립니다. 말을 겨우 알아들을 수 있을 정도입니다. ''떠나... 어둠을... 찾아...''', `MaleText_loc4`='军情七处保险箱被打开了。一阵隆隆的巨响传入你的耳际。你只能听清几个字：“去……搜查……阴影……”', `MaleText_loc5`='軍情七處帶鎖箱被打開了。一股隆隆的巨響傳入你的耳際。你只能聽清幾個字:「去...搜查...陰影...」', `MaleText_loc7`='IV:7 la caja fuerte se abre con un chirrido. Se escucha una voz atronadora. Se pueden descifrar las palabras: ''Ve... a buscar... sombras...''' WHERE `ID`=3225;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오라. 이것이 내 글이다.', `MaleText_loc4`='嗨这是我的文书。', `MaleText_loc5`='嗨這是我的文書。', `MaleText_loc7`='Hola, este es mi texto.', `FemaleText_loc1`='어서 오라. 이것이 내 글이다.', `FemaleText_loc4`='嗨这是我的文书。', `FemaleText_loc5`='嗨這是我的文書。', `FemaleText_loc7`='Hola, este es mi texto.' WHERE `ID`=3241;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그 누구도 창조자의 비밀을 훔칠 수 없다!', `FemaleText_loc4`='没人可以窃取造物者的秘密！', `FemaleText_loc5`='沒有人可以盜取造物之神的秘密!', `FemaleText_loc7`='¡Nadie puede robar los secretos de los Creadores!' WHERE `ID`=3261;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='감히 이 고대 성지를 더럽히다니!', `FemaleText_loc4`='你怎敢亵渎这个神圣的地方？', `FemaleText_loc5`='你怎敢褻瀆這個神聖的地方?', `FemaleText_loc7`='¡Cómo te atreves a profanar este antiguo lugar!' WHERE `ID`=3262;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 깨져서 쪼개집니다!', `MaleText_loc4`='%s裂成了碎片！', `MaleText_loc5`='%s碎裂了!', `MaleText_loc7`='%s se astilla.', `FemaleText_loc1`='%s|1이;가; 깨져서 쪼개집니다!', `FemaleText_loc4`='%s裂成了碎片！', `FemaleText_loc5`='%s碎裂了!', `FemaleText_loc7`='%s se astilla.' WHERE `ID`=3263;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='보고서에 적힌 내용을 잘 읽어보세요, $n. 탑의 방어를 뚫는 데 아주 큰 도움이 될 거예요.', `FemaleText_loc4`='$n，你一定要读读我的日记。里面的内容对于你攻破那座塔的防御体系非常有帮助。', `FemaleText_loc5`='$n，你一定要讀讀我的日記。裡面的內容對於你攻破那座塔的防禦體系非常有幫助。', `FemaleText_loc7`='Asegúrate de volver a leer las notas de mi revista, $n. Te darás cuenta de lo valiosos que son a la hora de franquear las defensas de la torre.' WHERE `ID`=3264;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 대장장이가 되고 싶습니까? 저기 있는 장갑과 망치를 집으십시오. 실력이 어떤지 한번 보겠습니다.', `MaleText_loc4`='那么说来你想要成为一名铁匠？$g小伙子:小姑娘;，扎好围裙，拿上铁锤，让我们开始吧。', `MaleText_loc5`='那麼說來你想要成為一名鐵匠?紮好圍裙，拿起鐵錘$g小夥子:小姑娘;，讓我們開始吧。', `MaleText_loc7`='¿Así que quieres ser un herrero? Coge un mandil y un martillo, $gmuchacho:muchacha; y veamos qué sabes hacer.' WHERE `ID`=3265;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련을 받고 싶습니다.', `MaleText_loc4`='请让我接受训练。', `MaleText_loc5`='請讓我接受訓練。', `MaleText_loc7`='Instrúyeme.', `FemaleText_loc1`='훈련을 받고 싶습니다.', `FemaleText_loc4`='请让我接受训练。', `FemaleText_loc5`='請讓我接受訓練。', `FemaleText_loc7`='Instrúyeme.' WHERE `ID`=3266;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갑옷 제작에 대해 더 듣고 싶습니다.', `MaleText_loc4`='请传授我更多关于锻造护甲的知识。', `MaleText_loc5`='請傳授我更多關於鍛造護甲的知識。', `MaleText_loc7`='Cuéntame más acerca del arte de forjar armaduras.', `FemaleText_loc1`='갑옷 제작에 대해 더 듣고 싶습니다.', `FemaleText_loc4`='请传授我更多关于锻造护甲的知识。', `FemaleText_loc5`='請傳授我更多關於鍛造護甲的知識。', `FemaleText_loc7`='Cuéntame más acerca del arte de forjar armaduras.' WHERE `ID`=3267;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 훌륭한 방어구를 본 게 실로 몇 년만인지 모르겠소, $n. 대용광로에서 그룸누스 스틸셰이퍼의 수습 대장장이로 일할 때 이후로는 처음이오. 그라면 분명 방어구 제작에 대해서 당신의 흥미를 끌 만한 기술을 가르쳐줄 수 있을 거요.', `MaleText_loc4`='$n，我已经许久没有看见过有上好的护甲被锻造出来了。我以前曾经在大锻炉的格鲁努斯·削钢那里接受过训练。我相信如果你去他那里的话，肯定可以学到很多东西。', `MaleText_loc5`='$n，我已經許久沒有看見過有上好的護甲被鍛造出來了。我以前曾經在大鍛爐的格魯努斯·削鋼那裡接受過訓練。我相信如果你去他那裡的話，肯定可以學到很多東西。', `MaleText_loc7`='No había visto una armadura tan bien hecha en muchos años, $n. No hasta que recibí instrucción de Grumnus Forjacero en la Gran Fundición. Sé que él podría enseñarte muchas cosas interesantes acerca de cómo fabricar armaduras.' WHERE `ID`=3268;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='길을 좀 가르쳐주시겠습니까?', `MaleText_loc4`='你能帮我指指路吗？', `MaleText_loc5`='你能幫我指指路嗎?', `MaleText_loc7`='¿Me podrás dar las señas?', `FemaleText_loc1`='길을 좀 가르쳐주시겠습니까?', `FemaleText_loc4`='你能帮我指指路吗？', `FemaleText_loc5`='你能幫我指指路嗎?', `FemaleText_loc7`='¿Me podrás dar las señas?' WHERE `ID`=3269;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그룸누스를 만나고 싶으면 먼저 아이언포지로 가십시오. 그 도시 한복판으로 가서 대용광로를 둘러보면 그를 찾을 수 있을 거요.', `MaleText_loc4`='如果你想要找格鲁努斯的话，那么首先要到铁炉堡去，然后去城市中心的大锻炉，在那里你就可以找到格鲁努斯。', `MaleText_loc5`='如果你想要找格魯努斯的話，那麼首先要到鐵爐堡去，然後去城市中心的大鍛爐，在那裡你就可以找到格魯努斯。', `MaleText_loc7`='Si quieres encontrar a Grumnus, lo primero que tienes que hacer es dirigirte a Forjaz. Dirígete al centro de la ciudad y pregunta por la Gran Fundición. Allí lo encontrarás.' WHERE `ID`=3270;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무기 제작에 대해 더 듣고 싶습니다.', `MaleText_loc4`='请传授我更多关于锻造武器的知识。', `MaleText_loc5`='請傳授我更多關於鍛造武器的知識。', `MaleText_loc7`='Cuéntame más acerca del arte de forjar armas.', `FemaleText_loc1`='무기 제작에 대해 더 듣고 싶습니다.', `FemaleText_loc4`='请传授我更多关于锻造武器的知识。', `FemaleText_loc5`='請傳授我更多關於鍛造武器的知識。', `FemaleText_loc7`='Cuéntame más acerca del arte de forjar armas.' WHERE `ID`=3271;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 당신의 솜씨는 아주 훌륭하군. 인정하긴 싫지만 당신이 만드는 검과 도끼가 내 것보다도 우수한 것은 사실이오. 내가 만난 이들 중에 당신보다 더 기술이 좋은 자는 보르구스 스틸핸드 밖에 없소. 그라면 분명 당신에게 한 수 가르쳐 줄 수 있을 거요.', `MaleText_loc4`='$n，你已经拥有了惊人的锻造技能。我不得不承认你锻造出的武器已经超过了我的水平。我所认识的水平高过你的铁匠只有博古斯·钢拳，我相信你可以从他那里学到不少东西。', `MaleText_loc5`='$n，你已經擁有了驚人的鍛造技能。我不得不承認你鍛造出的武器已經超過了我的水準。我所認識的水準高過你的鐵匠只有博古斯·鋼拳，我相信你可以從他那裡學到不少東西。', `MaleText_loc7`='Ese sí que es un arte impresionante, $n. Las hojas y los martillos que fabrican algunos son incluso superiores a los míos, por difícil que resulte admitirlo. La única persona que he conocido con esta gran habilidad es Borgus Mano de Acero. Estoy seguro que con él aprenderías unas cuantas cosas.' WHERE `ID`=3272;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보르구스에게 훈련을 받고 싶다고요? 어디 있는지 가르쳐 드리겠어요. 내 대장간에서 북서쪽에 있는 사거리를 지나 서쪽 길로 가십시오. 오른쪽 두 번째 건물에 있을 거요.', `MaleText_loc4`='你想要接受博古斯的训练？当然，我可以告诉你在什么地方能够找到他。往西北方向穿过广场，然后再顺着西面的路走，在右手边的第二座建筑??可以找到他。', `MaleText_loc5`='你想要接受博古斯的訓練?當然，我可以告訴你在什麼地方能夠找到他。往西北方向穿過廣場，然後再順著西面的路走，在右手邊的第二座建築物中可以找到他。', `MaleText_loc7`='¿Quieres recibir instrucción de Borgus? Vale, yo puedo decirte dónde encontrarlo. Atraviesa la plaza al noroeste de mi fragua y luego coge el camino que conduce al oeste. Lo encontrarás en el segundo edificio a tu derecha.' WHERE `ID`=3273;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무기 제작 솜씨가 꽤 괜찮군. 아주 훌륭해. 자, 마음에 드는 망치를 하나 들게. 진짜 제대로 된 무기를 만들 수 있는지 한번 보세.', `MaleText_loc4`='$g小伙子:小姑娘;，你已经具备了相当高超的武器锻造水平，这让我非常吃惊。现在拿起铁锤，让我们看看你是否能够锻造出一把真正的武器吧。', `MaleText_loc5`='$g小夥子:小姑娘;，你已經具備了相當高超的武器鑄造水準，這讓我非常吃驚。現在拿起鐵錘，讓我們看看你是否能夠鍛造出一把真正的武器吧。', `MaleText_loc7`='Se te da bastante bien fabricar armas, $gmuchacho:muchacha;,muy impresionante. Ahora, coge un martillo y veamos si puedes fabricar una de verdad.' WHERE `ID`=3274;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 땅은 으스러진 손이 지배한다. 우리는 섭정, 치안대, 재판관, 배심원, 그리고 사형 집행자로서 칼림도어를 뒤덮고 있다. 으스러진 손은 모든 것을 볼 수 있고 모든 것을 알고 있다.$B$B당신은 으스러진 손에 봉사하면서 많이 성장했으니 이제 실전 경험을 쌓을 때가 됐다.$B$B다음 임무를 맡을 준비는 되었나?', `MaleText_loc4`='碎手氏族的影响遍布这一地区。我们已经统治了整个卡利姆多——法律，政治，军事，一切的一切。我们无所不知，我们目及一切。$B$B你现在已经成长到能够为我们效力的时候了，$n。是时候让你投入战斗了。$B$B你做好接受下一个任务的准备了吗？', `MaleText_loc5`='破碎之手氏族的影響遍佈這一地區。我們已經統治了整個卡林多─法律，政治，軍事，一切的一切。我們無所不知，我們目及一切。$B$B你現在已經成長到能夠為我們效力的時候了，$n。是時候讓你投入戰鬥了。$B$B你做好接受下一個任務的準備了嗎?', `MaleText_loc7`='La influencia de los Mano Destrozada se deja sentir en estas tierras. Somos el velo que cubre Kalimdor: Los protectorados, la policía, los jueces, el jurado y, finalmente, los verdugos. Los vemos a todos, los conocemos a todos.$B$BHas crecido mucho durante el tiempo que has prestado servicio a los Mano Destrozada, $n. Ha llegado el momento de enviarte al campo de batalla.$B$B¿Estás $gpreparado:preparada; para acometer tu siguiente misión?' WHERE `ID`=3275;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 일하느라 바쁜 게 안 보이나? 내 시간을 뺏으려면 그럴듯한 이유를 대야 할 걸세.', `MaleText_loc4`='难道你看不出我现在很忙吗？有什么事？', `MaleText_loc5`='難道你看不出我現在很忙嗎?有什麼事?', `MaleText_loc7`='¿No ves que estoy ocupado? Será mejor que eso que tienes que decir sea importante.' WHERE `ID`=3276;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정신이 제대로 박힌 건가? 그게 무슨 무기라고 만들고 있나? 배추나 다듬을 수 있겠구먼. 나는 초보자는 가르치지 않네.', `MaleText_loc4`='你真的那么笨吗？你锻造出来的是什么东西？那最多算得上是一把水果刀罢了。我可不会花时间来训练一个菜鸟。', `MaleText_loc5`='你真的那麼笨嗎?你鍛造出來的是什麼東西?那最多算得上是一把水果刀罷了。我可不想浪費時間訓練菜鳥。', `MaleText_loc7`='¿Eres $gtonto:tonta;? Eso no es un arma, es un cuchillo de cocina. No instruyo a principiantes.' WHERE `ID`=3277;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 내가 하는 것을 잘 보고 내 지시를 그대로 따르도록. 명령에 따르지 않는 것은 무덤자리를 스스로 파는 것과 마찬가지다. 감독관 피줄은 뛰어난 전사에다 암살에도 아주 능통하니까.', `MaleText_loc4`='$n，仔细看我是怎么做的，然后严格按照我的指示办事。否则你只有死路一条，费苏勒可是非常出色的战士和刺客。', `MaleText_loc5`='$n，仔細看我是怎麼做的，然後嚴格按照我的指示辦事。否則你只有死路一條，監工費蘇勒可是非常出色的戰士和刺客。', `MaleText_loc7`='$n, pon mucha atención a lo que hago y sigue mis instrucciones con precisión. No prestar atención a mis palabras supone firmar tu sentencia de muerte, ya que el Capataz Fizzule conoce MUY BIEN los secretos de los guerreros y los asesinos.' WHERE `ID`=3278;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그의 시선을 끈 다음, 그러니까 탑 주변에 있는 당신을 보면 분명 관심을 보일 테니까, 그때 그를 바라 보면서 으스러진 손 /경례를 하도록. 내가 시범을 보이지...', `MaleText_loc4`='如果你在塔的周围活动的话，一定会引起他的注意，这时你就可以实施碎手军礼了。让我们来练习一下……', `MaleText_loc5`='只要你在塔的周圍活動的話，一定會引起他的注意，這時你就要面對他，然後執行碎手軍禮。讓我們來練習一下...', `MaleText_loc7`='Una vez que has llamado su atención - y puedes estar seguro de que si te ve cerca de la torre, acapararás su atención - deberás enfrentarlo y realizar el /Saludo de los Mano Destrozada. Déjame demostrártelo...' WHERE `ID`=3279;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 으스러진 손에 /경례를 할 준비를 합니다! *차려!*', `MaleText_loc4`='%s准备进行碎手军礼！*注意！*', `MaleText_loc5`='%s準備進行碎手軍禮!*注意!*', `MaleText_loc7`='%s prepara el saludo de los Mano Destrozada! *¡PRESTA ATENCIÓN!*' WHERE `ID`=3280;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='봤나? 아직도 /경례를 어떻게 하는지 잘 모르겠거든 나한테 연습 삼아 해보도록. 으스러진 손 /경례를 제대로 했다 싶으면 얘기해 주지.', `MaleText_loc4`='看到我是怎么做的了吗？如果你对如何使用碎手军礼还不太明白的话，那么就按照我的方式进行练习吧。如果你正确地实施了碎手军礼（使用/Salute指令），我就会给出相应的回应。', `MaleText_loc5`='看到我是怎麼做的了嗎?如果你對如何使用碎手軍禮還不太明白的話，那就對著我多練習幾下。只要你正確地執行了碎手軍禮(使用:/敬禮)，我就會給出相應的回應。', `MaleText_loc7`='¿Has visto lo que yo? Si dudas de las técnicas utilizadas en el /saludo, practica conmigo. Si efectúas el /Saludo de los Mano destrozada, te daré la respuesta adecuada.' WHERE `ID`=3281;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대용광로에 온 것을 환영하오. 바깥은 추워도 여기는 항상 따뜻하고 편안하지. 망치를 들고 저 모루를 한번 때려보시오. 대용광로의 대장장이가 될만한 소질이 있나 보겠소이다!', `MaleText_loc4`='欢迎来到大锻炉，$g小伙子:姑娘;。外面虽然非常寒冷，但是这里确实热火朝天。拿起锤子开工吧，让我看看你到底有些什么能耐！', `MaleText_loc5`='歡迎來到大鍛爐，$g小夥子:姑娘;。外面雖然非常寒冷，但是這裡確實熱火朝天。拿起錘子開工吧，讓我看看你到底有些什麼能耐!', `MaleText_loc7`='Te doy la bienvenida a la Gran Fundición, $gmuchacho:muchacha;. Fuera hace frío, pero aquí dentro estaremos a gusto con el calor que hace. ¡Coge un martillo, golpea el yunque y muéstrame si tienes lo que hay que tener para ser un herrero de la Gran Fundición!' WHERE `ID`=3282;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모양이 제대로 잡힌 걸 보니, 분명 기능도 괜찮을 거야. 술 내기를 해도 좋아. 브루크의 모퉁이 선술집에서 말이오. $n, 이제 미올로 선더퓨리를 찾아가 보시오. 당신에게 뭔가 가르쳐 줄 거요.', `MaleText_loc4`='干得好，$n，我打赌你做的东西和布鲁克的酒一样正点。你应该去和米洛尔·怒斩谈谈，他会给你更多指引的。', `MaleText_loc5`='幹得好，$n，我敢在布魯克小店賭一杯酒，你做的東西的確正點。你應該去和米洛爾·怒斬談談，他會給你更多指引的。', `MaleText_loc7`='Buena técnica, $n. Te apuesto una jarra de cerveza en la Esquina de Bruuk que la pieza es igualmente sólida. Sabes, creo que deberías ir a hablar con Myolor Furiahendida. Te recibirá de inmediato.' WHERE `ID`=3283;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미올로가 어디 있는지 당연히 가르쳐 드려야죠. 대용광로의 모루 근처에서 일하고 있어요. 그만한 솜씨를 가진 사람도 없으니 미올로의 말을 귀담아 들으세요.', `MaleText_loc4`='当然，我会告诉你怎么才能找到米洛尔的。他就在大锻炉的铁砧旁。仔细聆听他的教导吧，米洛尔绝对是名不虚传！', `MaleText_loc5`='當然，我可以告訴你怎麼才能找到米洛爾。他就在大鍛爐的鐵砧旁邊工作。仔細聆聽他的教導吧，$g小夥子:小姑娘;，米洛爾絕對名不虛傳!', `MaleText_loc7`='Por supuesto que te puedo decir dónde encontrar a Myolor. Justo allí, cerca del yunque de la Gran Fundición, ahí es donde trabaja. Pon mucha atención a lo que dice $gmuchacho:muchacha;, Myolor es un gran experto.' WHERE `ID`=3284;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 맘에 드는 친구로군. 내가 가르친 사람 중에 이렇게 칼을 잘 만드는 사람은 정말 오랜만이오. 하지만 진짜 무기를 만들고 싶거든 미올로 선더퓨리를 찾아가 보시오. 그 드워프라면 당신에게 칼 만드는 법 하나는 제대로 가르쳐줄 수 있을게요.', `MaleText_loc4`='$n，你已经得到了我的认可，你是我这些年来带过的最好的徒弟。如果你想要铸造一把真正的武器，那么你一定要去和米洛尔·怒斩谈谈。那个矮人能够教你铸造出一把真真正正的绝世好剑。', `MaleText_loc5`='$n，你已經得到了我的認可，你是我這些年來帶過的最好的徒弟。如果你想要鑄造一把真正的武器，那麼你一定要去和米洛爾·怒斬談談。那個矮人能夠教你鑄造出一把真真正正的絕世好劍。', `MaleText_loc7`='Tienes mi aprobación, $n. Puedes forjar hojas mejor que cualquier otro al que haya instruido en años. No obstante, si quieres fabricar un arma de verdad, tienes que hablar con Myolor Furiahendida. Ese enano te guiará por el buen camino.' WHERE `ID`=3285;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미올로를 보러 가겠다고? 바로 저기 있소. 당신 뒤에 말이오! 아니... 당신 앞이라고 해야 하나? 어쨌든 거대한 모루 근처에 있소!', `MaleText_loc4`='你要找米洛尔·怒斩？他就在那儿，你瞧，就在你身后！呃，好吧，也许在你前面！反正就在大锻炉附近！', `MaleText_loc5`='你要找米洛爾?他就在那兒，你瞧，就在你身後!呃，好吧，也許在你前面!反正就在大鍛砧附近!', `MaleText_loc7`='Así que, vete a ver a Myolor, ¿vale? Está justo ahí... ¡detrás de ti! O, quizás, ¡delante de ti! ¡Cerca del Gran Yunque!' WHERE `ID`=3286;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘했다!', `MaleText_loc4`='干得好！', `MaleText_loc5`='幹得好﹗', `MaleText_loc7`='¡Bien hecho!' WHERE `ID`=3287;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무언가 이 탑에 역병을 퍼뜨리고 있소. 탑 안은 물론이고 근처에서 일하던 다른 투자개발회사 일꾼들도 병에 걸렸소이다. 지난주에만 감시관 둘이 숨졌지. 그런데 글쎄, 죽은 직후 넋 나간 돌연변이로 되살아나지 뭐요!$B$B내 몸에서도 생명력이 빠져나가고 있소. 통제력도 점점 잃어가고. 사악한 충동이 나를 지배... 나쁜 충동이... *피줄이 자신의 따귀를 때립니다* 아직은 안 돼. 잘 들으시오... 나는 이 탑을 감독하는 자요. 이 정도 자리에 있으면 민감한 정보를 알게 되지.', `MaleText_loc4`='厄运袭击了这座塔。这附近的所有风险投资公司雇员，包括我，都病倒了。$B$B就在上个星期，我们巡逻队的两个人死掉了，然后就变成了两具没有思想的行尸！$B$B我感到自己的生命力正在慢慢地被抽干……我已经渐渐丧失对自己的控制力。快让这样的痛苦结束吧……求求你了……*费苏勒开始重重地抽打自己的脸*我还没有死……听着……作为风险投资公司的高级成员，我知道很多敏感的信息。', `MaleText_loc5`='瘟疫襲擊了這座塔。這附近的所有風險投資公司雇員，包括我，都病倒了。$B$B就在上個星期，我們巡邏隊的兩個人死掉了，然後就變成了兩具沒有思想的行屍!$B$B我感到自己的生命力正在慢慢地被抽乾...我已經漸漸喪失對自己的控制力。快讓這樣的痛苦結束吧...求求你了...*費蘇勒開始重重地抽打自己的臉*我還沒有死...聽著...作為風險投資公司的高級成員，我知道很多敏感的資訊。', `MaleText_loc7`='Cierto mal asola esta torre. Yo he caído enfermo y los otros empleados de Ventura y Cía. que trabajan cerca o en la torre también lo han hecho.$B$BPrecisamente la semana pasada murieron dos de nuestros patrulleros para luego volver a la vida instantáneamente, ¡pero como esclavos autómatas!$B$BLa fuerza vital abandona mi cuerpo. Siento cómo pierdo el control. Me invaden impulsos... Malos impulsos... *Burbujita se abofetea la cara* Aún no... Escucha... disfruto de una posición de poder. Esta posición pone a mi alcance información confidencial.' WHERE `ID`=3288;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일로 왔소?', `MaleText_loc4`='我能为你做什么？', `MaleText_loc5`='我能為你做什麼?', `MaleText_loc7`='¿En qué puedo ayudarte?' WHERE `ID`=3289;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고작 이것 때문에 날 성가시게 한 거요? 이 쓰레기를 입고 다니느니 토끼 가죽을 걸치고 트롤의 소굴을 뛰어다니는 것이 낫겠군.', `MaleText_loc4`='你打扰我就是为了这个？你穿得真是跟垃圾一样，你还不如背着个死兔子到巨魔的洞里去跑一圈哪！', `MaleText_loc5`='你打擾我就是為了這個?你穿得真是跟垃圾一樣，你還不如背隻死兔子到食人妖的洞裡去跑一圈!', `MaleText_loc7`='¿Vienes a molestarme para eso? Estarías mejor corriendo por la guarida de un trol con un conejo muerto atado a la espalda, que vistiendo esa basura que llevas encima.' WHERE `ID`=3290;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이라;라; 했소? 아주 강하고 훌륭한 걸 걸치고 있군그래. 훈련을 시켜주지. 마그니 왕께서 몸소 걸칠 만큼 훌륭한 갑옷을 만드는 법을 가르쳐주겠소.', `MaleText_loc4`='$n，这真是你做的吗？真是一件精美的作品。我会继续训练你的，相信总有一天你可以达到皇家铸甲匠的水准。', `MaleText_loc5`='$n，這真是你做的嗎?真是一件精美的作品。我會繼續訓練你的，相信總有一天你可以達到皇家鑄甲匠的水準。', `MaleText_loc7`='Tu nombre es $n, ¿no? Ahí tienes una pieza muy bien hecha. Me haré cargo de ti y te instruiré en el oficio para que puedas crear una armadura de tal calidad, que hasta el propio rey Magni pueda ponérsela.' WHERE `ID`=3291;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무언가 이 탑에 역병을 퍼뜨리고 있소. 탑 안은 물론이고, 근처에서 일하던 다른 투자개발회사 일꾼들도 병에 걸렸소이다. 지난주에만 감시관 둘이 숨졌지. 그런데 글쎄, 죽은 직후 넋 나간 돌연변이로 되살아나지 뭐요! 내 몸에서도 생명력이 빠져나가고 있소. 통제력도 점점 잃어가고 있고. 사악한 충동이.. 머리를 지배... 나쁜 충동이... 아직은 안 돼... 잘 들으시오... 나는 이 탑을 감독하는 자요. 이 정도 자리에 있으면 민감한 정보를 알게 되지.', `MaleText_loc4`='厄运袭击了这座塔。这附近的所有风险投资公司雇员，包括我，都病倒了。$B$B就在上个星期，我们巡逻队的两个人死掉了，然后就变成了两具没有思想的行尸！$B$B我感到自己的生命力正在慢慢地被抽干……我已经渐渐丧失对自己的控制力。快让这样的痛苦结束吧……求求你了……*费苏勒开始重重地抽打自己的脸*我还没有死……听着……作为风险投资公司的高级成员，我知道很多敏感的信息。', `MaleText_loc5`='瘟疫襲擊了這座塔。這附近的所有風險投資公司雇員，包括我，都病倒了。$B$B就在上個星期，我們巡邏隊的兩個人死掉了，然後就變成了兩具沒有思想的行屍!$B$B我感到自己的生命力正在慢慢地被抽幹...我已經漸漸喪失對自己的控制力。快讓這樣的痛苦結束吧...求求你了...*費蘇勒開始重重地抽打自己的臉*我還沒有死...聽著...作為風險投資公司的高級成員，我知道很多敏感的資訊。', `MaleText_loc7`='Cierto mal asola esta torre. Yo he caído enfermo y los otros empleados de Ventura y Cía. que trabajan cerca o en la torre también lo han hecho. Precisamente la semana pasada murieron dos de nuestros patrulleros para luego volver a la vida instantáneamente, ¡pero como esclavos autómatas! La fuerza vital abandona mi cuerpo. Siento cómo pierdo el control. Me invaden impulsos... Malos impulsos... Todavía no... Escucha... Disfruto de una posición de poder. Esta posición pone a mi alcance información confidencial.' WHERE `ID`=3292;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좀 더 자세히 얘기해 주십시오.', `MaleText_loc4`='告诉我更多的信息。', `MaleText_loc5`='告訴我更多的資訊。', `MaleText_loc7`='Cuéntame más.', `FemaleText_loc1`='좀 더 자세히 얘기해 주십시오.', `FemaleText_loc4`='告诉我更多的信息。', `FemaleText_loc5`='告訴我更多的資訊。', `FemaleText_loc7`='Cuéntame más.' WHERE `ID`=3293;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='약 5개월 전, 투자개발회사의 가시덤불 지부에서는 무법항에 있는 크랭크 피즐버브라는 수상한 상인에게 특수한 독을 받기로 계약을 했소. 피즐버브는 잔질에게 독을 훔쳐온 게 분명하오!$B$B그래, 추방자 잔질 말이오. 그 트롤은 강령술 실험을 하곤 했는데, 그 때문에 부족에서 영원히 추방당하고 말았소.$B$B그들은 독을 받은 후 서로 시험해 보기 시작했고 그 결과는 실로 참담했소.', `MaleText_loc4`='大约五个月之前，风险投资公司荆棘谷分公司从藏宝海湾的一个名叫克兰克·菲兹巴布的神秘商人那里买了一瓶特别的毒药。显然，那是从赞吉尔手中偷来的！$B$B没错，我说的就是那个被流放的赞吉尔，他因为研究亡灵巫术而被他的部族赶了出去。$B$B那帮荆棘谷分公司的家伙拿到毒药之后就开始互相实验，结果可想而知。', `MaleText_loc5`='大約五個月之前，風險投資公司荊棘谷分公司從藏寶海灣的一個名叫克蘭克·菲茲巴布的神秘商人那裡買了一瓶特別的毒藥。顯然，那是從贊吉爾手中偷來的!$B$B沒錯，我說的就是那個『流亡者』贊吉爾，他因為研究亡靈巫術而被他的部族趕了出去。$B$B那幫荊棘谷分公司的傢伙拿到毒藥之後就開始互相實驗，結果可想而知。', `MaleText_loc7`='Hace unos meses, cayó en manos de la división Tuercespina de Ventura y Cía. un veneno que les proporcionó en la Bahía del Botín un turbio mercader llamado Loquillo Pinchabujas. Aparentemente, Pinchabujas había robado el veneno de Zanzil.$B$BSí, Zanzil el Desterrado - el trol que fue desterrado de su propia tribu debido a la naturaleza de sus ‘experimentos’ en nigromancia.$B$BNaturalmente, una vez que se hicieron con el veneno, empezaron a probarlo entre ellos. Los resultados fueron desastrosos.' WHERE `ID`=3294;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 얘기해 주세요. 아주 흥미롭군요.', `MaleText_loc4`='请继续，这个故事听上去很有意思。', `MaleText_loc5`='請繼續，這個故事聽起來很有意思。', `MaleText_loc7`='Continúa, por favor, esta historia es fascinante.', `FemaleText_loc1`='계속 얘기해 주세요. 아주 흥미롭군요.', `FemaleText_loc4`='请继续，这个故事听上去很有意思。', `FemaleText_loc5`='請繼續，這個故事聽起來很有意思。', `FemaleText_loc7`='Continúa, por favor, esta historia es fascinante.' WHERE `ID`=3296;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='결국, 총감독 푸직 갤리윅스가 끼어들었고 그 나머지 독을 이곳 진흙 늪에 있는 자기 탑으로 가져왔소. 독의 불안정한 성질을 연구하기 위해서라고 둘러대고서 말이지. 그는 데피아즈 결사단에게 그 독의 비밀을 알려주는 대가로, 안정적인 독을 대량 공급받기로 결정했지.$B$B데피아즈 결사단에서는 클라벤 몰트웨이크가 잔질의 혼합물이 지닌 화학적 성질을 바꾸는 일을 맡게 되었소.', `MaleText_loc4`='大工头普兹克·加里维克斯在那件事情发生之后就把剩余的毒药带到了他在淤泥沼泽的塔中继续进行研究，主要是想要解决毒药的不稳定性。最后他决定和迪菲亚兄弟会达成协议，共同研制开发这种毒药，代价是由迪菲亚兄弟会提供批量的成品毒药。$B$B迪菲亚兄弟会的克拉文·摩特维克负责对赞吉尔的毒药进行改良。', `MaleText_loc5`='大工頭普茲克·加里維克斯在那件事情發生之後就把剩餘的毒藥帶到了他在淤泥沼澤的塔中繼續進行研究，主要是想要解決毒藥的不穩定性。最後他決定和迪菲亞兄弟會達成協議，共同研製開發這種毒藥，代價是由迪菲亞兄弟會提供批量的成品毒藥。$B$B迪菲亞兄弟會的克拉文·摩特維克負責對贊吉爾的毒藥進行改良。', `MaleText_loc7`='El gran supervisor Puzik Gallywix finalmente intervino, llevando los restos de veneno a su torre, aquí en El Fangal, con el propósito de estudiar e investigar la naturaleza inestable de las toxinas. Finalmente, se tomó la decisión de compartir el secreto del veneno con la Hermandad Defias, a cambio de una gran cantidad de veneno estable y utilizable.$B$BA Klaven Mortoalerta, de la Hermandad Defias, se le encomendó la tarea de alterar las propiedades químicas de la mezcla de Zanzil.' WHERE `ID`=3301;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='중간은 생략하고... 그 결과 얻게 된 제조법은 꽤 효과가 있어서 일꾼들을 좀 더 잘 조종할 수 있게 됐지만, 부작용은 여전히 있었다오. 비활성 혼합물의 휘발성이 너무 높았지...$B$B갤리윅스와 탑 안팎에 있는 자들은 모두 독에 감염되어 버렸소. 그 독은 우리의 신체와 정신에 영향을 미치지. 그 때문에 내부 기관이 극도로 약해져 버렸소. 이게 당신의 기회요, $n. 나는 더는 버틸 기운이 없소. 곧 ''그들''과 한패가 돼버릴 것 같소.', `MaleText_loc4`='接下来就是你看到的情况了：毒药发挥了预期的作用，喝下毒药的人都变成了被人控制的行尸走人，然而，这种毒药非常不稳定。$B$B加里维克斯，还有这座塔里里外外的人都已经感染了这种毒药。我们的意志和身体都在不断被侵袭。我们的器官变得越来越脆弱。$n，我已经无力去拯救这里的人了，而且我感觉自己马上要变成他们的一份子了。', `MaleText_loc5`='接下來就是你看到的情況了:毒藥發揮了預期的作用，喝下毒藥的人都變成了被人控制的行屍走人，然而，這種毒藥非常不穩定。$B$B加里維克斯，還有這座塔裡裡外外的人都已經感染了這種毒藥。我們的意志和身體都在不斷被侵襲。我們的器官變得越來越脆弱。$n，我已經無力去拯救這裡的人了，而且我感覺自己馬上要變成他們的一份子了。', `MaleText_loc7`='Avance rápido hacia el presente: La fórmula resultante funciona, haciendo posible la creación de un esclavo autómata más controlado. No obstante, la desventaja está en el hecho de que el compuesto inactivo es extremadamente volátil.$B$BGallywix, todos los que están en esta torre y fuera de ella están infectados con el veneno. Nos está afectando la mente y el cuerpo. Nuestros órganos internos se han reblandecido y son extremadamente frágiles. Esta es tu oportunidad, $n. No tengo la fuerza para seguir adelante y tengo la sensación de que pronto me convertiré en uno de ‘ellos’.' WHERE `ID`=3302;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='데피아즈단이라고요? 좋지 않은 소식이군요. 계속 말해 보세요.', `MaleText_loc4`='迪菲亚兄弟会？这可不是个好消息。简直是太糟了！请继续说下去。', `MaleText_loc5`='迪菲亞兄弟會?這可不是個好消息。簡直是太糟了!請繼續說下去。', `MaleText_loc7`='¿Defias? Esto no está bien. No está bien en absoluto. Continúa, por favor.', `FemaleText_loc1`='데피아즈단이라고요? 좋지 않은 소식이군요. 계속 말해 보세요.', `FemaleText_loc4`='迪菲亚兄弟会？这可不是个好消息。简直是太糟了！请继续说下去。', `FemaleText_loc5`='迪菲亞兄弟會?這可不是個好消息。簡直是太糟了!請繼續說下去。', `FemaleText_loc7`='¿Defias? Esto no está bien. No está bien en absoluto. Continúa, por favor.' WHERE `ID`=3303;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘내세요, 피줄!', `MaleText_loc4`='坚强一点，费苏勒！', `MaleText_loc5`='堅強一點，費蘇勒!', `MaleText_loc7`='¡Sé fuerte, Burbujita!', `FemaleText_loc1`='힘내세요, 피줄!', `FemaleText_loc4`='坚强一点，费苏勒！', `FemaleText_loc5`='堅強一點，費蘇勒!', `FemaleText_loc7`='¡Sé fuerte, Burbujita!' WHERE `ID`=3304;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 탑의 방어력은 매우 약해져 있소. 투자개발회사 순찰대원, 보초, 망꾼은 물론이고 갤리윅스마저 감염되었기 때문에 당신의 공격에 힘없이 무너질 거요.$B$B탑 안으로 들어가시오. 적을 모두 처치하고 나올 때는 잊지 말고 가방에 총감독 푸직 갤리윅스의 머리카락과 남아있는 혼합물을 담아오시오. 그것을 셴툴에게 가져다주시오. 아마도... 그라면 무엇을 해야 할지 알 것이오.', `MaleText_loc4`='现在，这座塔的防御力量正处于最薄弱的时刻。包括加里维克斯在内的所有人都感染了疾病，你的攻击一定可以对他们造成致命打击！$B$B我想让你进塔拿到大工头普兹克·加里维克斯的徽记，还有最后一瓶药，把这些东西都交给申苏尔。他会知道接下来该怎么办的……我希望如此。', `MaleText_loc5`='現在，這座塔的防禦力量正處於最薄弱的時刻。包括加里維克斯在內的所有人都感染了疾病，你的攻擊一定可以對他們造成致命打擊!$B$B我想要看到你血洗那座塔，你要拿到大工頭普茲克·加里維克斯的腦袋，還有最後一瓶毒藥，把這些東西都交給申蘇爾。他會知道接下來該怎麼辦的...我希望如此。', `MaleText_loc7`='Las defensas de la torre están en su momento más bajo ahora mismo. Los patrulleros, los centinelas, los oteadores e incluso el propio Gallywix están infectados y son altamente vulnerables a tus habilidades especiales y ataques.$B$BQuiero ver cómo entras en esa torre y, cuando salgas, quiero verte cubierto con la sangre de tus enemigos, la cabeza del gran supervisor Puzik Gallywix, en tus manos y lo que queda de ese veneno en tu mochila. Lleva a Shenthul lo que recuperes. Él sabrá qué hacer... Eso espero.' WHERE `ID`=3305;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실망시키지 않겠습니다!', `MaleText_loc4`='我不会让你倒下的！', `MaleText_loc5`='我不會讓你失望的!', `MaleText_loc7`='¡No te defraudaré!', `FemaleText_loc1`='실망시키지 않겠습니다!', `FemaleText_loc4`='我不会让你倒下的！', `FemaleText_loc5`='我不會讓你失望的!', `FemaleText_loc7`='¡No te defraudaré!' WHERE `ID`=3306;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='버섯 가까이 다가갔다가 몸에 포자 송이의 독이 퍼진 것 같습니다!', `MaleText_loc4`='你撞破了蘑菇丛，并且被孢子感染了!', `MaleText_loc5`='你推擠了蘑菇叢，並且被孢子感染了!', `MaleText_loc7`='¡Has irritado el racimo y las esporas te han hecho enfermar!', `FemaleText_loc1`='버섯 가까이 다가갔다가 몸에 포자 송이의 독이 퍼진 것 같습니다!', `FemaleText_loc4`='你撞破了蘑菇丛，并且被孢子感染了!', `FemaleText_loc5`='你推擠了蘑菇叢，並且被孢子感染了!', `FemaleText_loc7`='¡Has irritado el racimo y las esporas te han hecho enfermar!' WHERE `ID`=3307;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영생을 누리지 못하는 불쌍한 이여, 반갑습니다. 저는 당신을 돕기 위해 노르간논의 원반에 의해 가동되었습니다.', `MaleText_loc4`='你好，凡人！我已被诺甘农圆盘激活，愿意为你提供帮助！', `MaleText_loc5`='你好，凡人!諾甘農圓盤啟動了我，我將提供你協助!', `MaleText_loc7`='¡Saludos, mortales! ¡He sido activado por los Discos de Norgannon para asistiros!' WHERE `ID`=3308;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='콜록, 거기 누구냐? 콜록...', `MaleText_loc4`='*咳嗽* 谁在那儿？ *咳嗽*', `MaleText_loc5`='*咳嗽* 誰在那兒? *咳嗽*', `MaleText_loc7`='*tose* ¿qué pasa ahí? *tose*' WHERE `ID`=3321;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어리석은 놈이로구나. 감히 이 푸직 갤리윅스 님의 탑에 들어오다니?', `MaleText_loc4`='哪个蠢货胆敢闯入大工头的塔？', `MaleText_loc5`='哪個蠢貨膽敢闖入大工頭的塔?', `MaleText_loc7`='¿Quién sería lo suficientemente idiota como para entrar en la torre del gran supervisor?' WHERE `ID`=3322;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 저 꽥꽥거리는 소리와 악마 같은 웃음소리를 참을 수가 없을 지경입니다. 라이던이 한 번만 더 ''크하하하''하고 웃으면 집이고 뭐고 몽땅 날려버릴 겁니다!', `MaleText_loc4`='那些嘲笑简直让我没法忍。如果林度恩再发出那种愚蠢的“哈哈哈”的声音，我就把他炸上天。', `MaleText_loc5`='那些嘲笑簡直讓我沒法忍。如果林度恩再發出那種愚蠢的「哈哈哈」的聲音，我就把他炸上天。', `MaleText_loc7`='No soporto todas esas carcajadas diabólicas. Como vuelva a escuchar a Lydon reírse de esa manera, haré que todo estalle.' WHERE `ID`=3324;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연금술을 배우고 싶습니다, 서지.', `MaleText_loc4`='瑟尔格，我要学习炼金术。', `MaleText_loc5`='瑟爾格，我要學習鍊金術。', `MaleText_loc7`='Me gustaría aprender alquimia, Serge.', `FemaleText_loc1`='연금술을 배우고 싶습니다, 서지.', `FemaleText_loc4`='瑟尔格，我要学习炼金术。', `FemaleText_loc5`='瑟爾格，我要學習鍊金術。', `FemaleText_loc7`='Me gustaría aprender alquimia, Serge.' WHERE `ID`=3325;
