UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헤헤! 몸을 숨기기엔 그만이군.', `MaleText_loc4`='呵呵！这里是个不错的藏身之地。', `MaleText_loc5`='呵呵!這裡是個不錯的藏身之地。', `MaleText_loc7`='¡Je, je! Este será un buen escondite.' WHERE `ID`=3329;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방금 무슨 소리였지?', `MaleText_loc4`='那是什么声音？', `MaleText_loc5`='那是什麼聲音?', `MaleText_loc7`='¿Qué ha sido eso?' WHERE `ID`=3330;
