UPDATE `locales_broadcast_text` SET `MaleText_loc1`='냄새가 나. 도둑놈 냄새...', `MaleText_loc4`='我感觉有盗贼在附近。', `MaleText_loc5`='我感覺有盜賊在附近。', `MaleText_loc7`='Huelo a pícaro.' WHERE `ID`=3332;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무엇을 도와드릴까요?', `MaleText_loc4`='$g先生:女士;，我能帮你什么忙吗？', `MaleText_loc5`='$g先生:女士;，我能幫你什麼忙嗎?', `MaleText_loc7`='¿En qué puedo ayudarte, $gseñor:señora;?', `FemaleText_loc1`='무엇을 도와드릴까요?', `FemaleText_loc4`='$g先生:女士;，我能帮你什么忙吗？', `FemaleText_loc5`='$g先生:女士;，我能幫你什麼忙嗎?', `FemaleText_loc7`='¿En qué puedo ayudarte, $gseñor:señora;?' WHERE `ID`=3333;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오십시오. 편히 둘러보세요. 이 넓은 스톰윈드에서 또 다른 마법부여사를 보게 되다니 정말 반갑습니다. 혹시 더 배우고 싶은 것이라도 있습니까?', `MaleText_loc4`='欢迎来到我的商店，很高兴在暴风城又遇见有人想要学附魔的了。你来这里是想要学点东西的吗？', `MaleText_loc5`='歡迎來到我的商店，很高興在暴風城又遇見有人想要學附魔的了。你來這裡是想要學點東西的嗎?', `MaleText_loc7`='$gBienvenido:Bienvenida; a mi tienda para ver a otro encantador aquí en Ventormenta. ¿Has venido para recibir instrucción?', `FemaleText_loc1`='어서 오십시오. 편히 둘러보세요. 이 넓은 스톰윈드에서 또 다른 마법부여사를 보게 되다니 정말 반갑습니다. 혹시 더 배우고 싶은 것이라도 있습니까?', `FemaleText_loc4`='欢迎来到我的商店，很高兴在暴风城又遇见有人想要学附魔的了。你来这里是想要学点东西的吗？', `FemaleText_loc5`='歡迎來到我的商店，很高興在暴風城又遇見有人想要學附魔的了。你來這裡是想要學點東西的嗎?', `FemaleText_loc7`='$gBienvenido:Bienvenida; a mi tienda para ver a otro encantador aquí en Ventormenta. ¿Has venido para recibir instrucción?' WHERE `ID`=3334;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 연금술사로군요. 흠, 당신의 연금술은 아직 나만큼 물이 오르지 않은 것 같군요. 제가 연금술의 참맛을 알 수 있는 기술을 몇 가지 가르쳐 드리죠.', `MaleText_loc4`='关于炼金术，嗯……我认为你现在和我的水平已经差不多了，也许我只能在个别细节上给你一些点拨。', `MaleText_loc5`='又是一個鍊金師，嗯...我認為你現在和我的水準已經差不多了，也許我只能在個別細節上給你一些點撥。', `MaleText_loc7`='$gOtro:Otra; alquimista, mmm... Dudo que tus habilidades sean tan buenas como las mías, así que tal vez pueda instruirte en unas cuantas técnicas.', `FemaleText_loc1`='오, 연금술사로군요. 흠, 당신의 연금술은 아직 나만큼 물이 오르지 않은 것 같군요. 제가 연금술의 참맛을 알 수 있는 기술을 몇 가지 가르쳐 드리죠.', `FemaleText_loc4`='关于炼金术，嗯……我认为你现在和我的水平已经差不多了，也许我只能在个别细节上给你一些点拨。', `FemaleText_loc5`='又是一個鍊金師，嗯...我認為你現在和我的水準已經差不多了，也許我只能在個別細節上給你一些點撥。', `FemaleText_loc7`='$gOtro:Otra; alquimista, mmm... Dudo que tus habilidades sean tan buenas como las mías, así que tal vez pueda instruirte en unas cuantas técnicas.' WHERE `ID`=3335;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런... 중요한 일을 하던 중이었는데... 날 방해할 만큼 중요한 일이겠지요? 그래, 무슨 일이십니까?', `MaleText_loc4`='我希望你是因为好事才打断我的，我正在做一些重要的工作。', `MaleText_loc5`='我希望你是因為好事才打斷我的，我正在做一些重要的工作。', `MaleText_loc7`='Espero que tu interrupción obedezca a una buena causa. Justo estaba haciendo algo muy importante.', `FemaleText_loc1`='이런... 중요한 일을 하던 중이었는데... 날 방해할 만큼 중요한 일이겠지요? 그래, 무슨 일이십니까?', `FemaleText_loc4`='我希望你是因为好事才打断我的，我正在做一些重要的工作。', `FemaleText_loc5`='我希望你是因為好事才打斷我的，我正在做一些重要的工作。', `FemaleText_loc7`='Espero que tu interrupción obedezca a una buena causa. Justo estaba haciendo algo muy importante.' WHERE `ID`=3336;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 약초채집가로군요. 흠, 보아하니 당신은 아직 잡초나 캐고 있을 것 같으니, 내 제대로 된 약초채집 기술을 몇 가지 가르쳐 주도록 하겠소.', `MaleText_loc4`='关于草药学，嗯……我认为你现在和我的水平已经差不多了，也许我只能在个别细节上给你一些点拨。', `MaleText_loc5`='你也是草藥師嗎，嗯...我想你的水準應該還沒有我這麼棒，那讓我來教你一點專業的技巧吧。', `MaleText_loc7`='$gOtro:Otra; herborista, mmm... Dudo que tus habilidades sean tan buenas como las mías, así que tal vez pueda instruirte en unas cuantas técnicas.', `FemaleText_loc1`='오, 약초채집가로군요. 흠, 보아하니 당신은 아직 잡초나 캐고 있을 것 같으니, 내 제대로 된 약초채집 기술을 몇 가지 가르쳐 주도록 하겠소.', `FemaleText_loc4`='关于草药学，嗯……我认为你现在和我的水平已经差不多了，也许我只能在个别细节上给你一些点拨。', `FemaleText_loc5`='你也是草藥師嗎，嗯...我想你的水準應該還沒有我這麼棒，那讓我來教你一點專業的技巧吧。', `FemaleText_loc7`='$gOtro:Otra; herborista, mmm... Dudo que tus habilidades sean tan buenas como las mías, así que tal vez pueda instruirte en unas cuantas técnicas.' WHERE `ID`=3337;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오십시오. 이 넓은 스톰윈드에서 또 다른 재봉사를 보게 되다니 무척 반갑습니다. 그런데 혹시 재봉술을 배우려고 오셨습니까?', `MaleText_loc4`='欢迎来到我的商店，很高兴在暴风城又遇见有人想要学裁缝的了。你来这里是想要学点东西的吗？', `MaleText_loc5`='歡迎來到我的商店，很高興在暴風城又遇見有人想要學裁縫的了。你來這裡是想要學點東西的嗎?', `MaleText_loc7`='Te doy la bienvenida a mi tienda, es bueno ver a otro sastre por aquí en Ventormenta. ¿Has venido tal vez para recibir instrucción?', `FemaleText_loc1`='어서 오세요. 이 넓은 스톰윈드에서 또 다른 재봉사를 보게 되다니 정말이지 반갑네요. 그런데 혹시 재봉술을 배우려고 오셨나요?', `FemaleText_loc4`='欢迎来到我的商店，很高兴在暴风城又遇见有人想要学裁缝的了。你来这里是想要学点东西的吗？', `FemaleText_loc5`='歡迎來到我的商店，很高興在暴風城又遇見有人想要學裁縫的了。你來這裡是想要學點東西的嗎?', `FemaleText_loc7`='Te doy la bienvenida a mi tienda, es bueno ver a otro sastre por aquí en Ventormenta. ¿Has venido tal vez para recibir instrucción?' WHERE `ID`=3338;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여어, 낚시꾼 친구로군. 혹시 훈련이 필요한 게 아니오? 내게 기술을 좀 배워보는 게 어떻겠소?', `MaleText_loc4`='啊，一个渔夫。你想要接受训练吗？也许我能教你些东西？', `MaleText_loc5`='啊，一個漁夫。你想要接受訓練嗎?也許我能教你些東西?', `MaleText_loc7`='Ah, $gun compañero pescador:una compañera pescadora;. ¿Necesitas tal vez un poco de instrucción? Quizás pueda enseñarte un par de cosas.', `FemaleText_loc1`='여어, 낚시꾼 친구로군. 혹시 훈련이 필요한 게 아니오? 내게 기술을 좀 배워보는 게 어떻겠소?', `FemaleText_loc4`='啊，一个渔夫。你想要接受训练吗？也许我能教你些东西？', `FemaleText_loc5`='啊，一個漁夫。你想要接受訓練嗎?也許我能教你些東西?', `FemaleText_loc7`='Ah, $gun compañero pescador:una compañera pescadora;. ¿Necesitas tal vez un poco de instrucción? Quizás pueda enseñarte un par de cosas.' WHERE `ID`=3339;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드에 오신 걸 환영합니다. 이 요새를 재건하는 데 오랜 세월이 걸리긴 했지만, 충분히 가치가 있었습니다. 이 장대한 요새에 관광차 온 것입니까? 아니면 따로 볼일이 있어 온 것입니까?', `MaleText_loc4`='欢迎来暴风城。我们可是花了很长时间才将它重建起来的，但是这些工作都很值得。那么，你是来参观的还是有任务在身？', `MaleText_loc5`='歡迎來暴風城。我們可是花了很長時間才將它重建起來的，但是這些工作都很值得。那麼，你是來參觀的還是有任務在身?', `MaleText_loc7`='Te doy la bienvenida a Ventormenta Me llevó mucho tiempo reconstruirla, pero mereció la pena con creces. ¿Estás de visita o has venido por motivos de negocios?', `FemaleText_loc1`='스톰윈드에 오신 걸 환영합니다. 이 요새를 재건하는 데 오랜 세월이 걸리긴 했지만, 충분히 가치가 있었습니다. 이 장대한 요새에 관광차 온 것입니까? 아니면 따로 볼일이 있어 온 것입니까?', `FemaleText_loc4`='欢迎来暴风城。我们可是花了很长时间才将它重建起来的，但是这些工作都很值得。那么，你是来参观的还是有任务在身？', `FemaleText_loc5`='歡迎來暴風城。我們可是花了很長時間才將它重建起來的，但是這些工作都很值得。那麼，你是來參觀的還是有任務在身?', `FemaleText_loc7`='Te doy la bienvenida a Ventormenta Me llevó mucho tiempo reconstruirla, pero mereció la pena con creces. ¿Estás de visita o has venido por motivos de negocios?' WHERE `ID`=3340;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요리사 수련을 받으러 이곳까지 날 찾아오는 이들은 드물지만, 당신이 준비가 되었다면 요리의 기본 정도는 가르쳐드릴 수 있을 듯싶습니다.', `MaleText_loc4`='找我学习烹饪的学徒并不多，如果你准备好了的话，我马上就可以教你一些烹饪技巧。', `MaleText_loc5`='找我學習烹飪的學徒並不多，如果你準備好了的話，我馬上就可以教你一些烹飪技巧。', `MaleText_loc7`='Aquí no vienen demasiados cocineros para recibir instrucción, pero supongo que puedo enseñarte algo si estás $gpreparado:preparada;.', `FemaleText_loc1`='요리사 수련을 받으러 이곳까지 날 찾아오는 이들은 드물지만, 당신이 준비가 되었다면 요리의 기본 정도는 가르쳐드릴 수 있을 듯싶습니다.', `FemaleText_loc4`='找我学习烹饪的学徒并不多，如果你准备好了的话，我马上就可以教你一些烹饪技巧。', `FemaleText_loc5`='找我學習烹飪的學徒並不多，如果你準備好了的話，我馬上就可以教你一些烹飪技巧。', `FemaleText_loc7`='Aquí no vienen demasiados cocineros para recibir instrucción, pero supongo que puedo enseñarte algo si estás $gpreparado:preparada;.' WHERE `ID`=3341;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳을 드나드는 관광객들을 모두 돌봐줄 정도로 제가 시간과 정력이 남아도는 줄 아십니까? 어서 용건만 간단히 말씀해 보십시오.', `MaleText_loc4`='我看上去像是那种闲得可以招待每个旅行者的人吗？快点告诉我你需要什么，我可没有时间和你慢慢磨蹭。', `MaleText_loc5`='我看起來像是那種閑得可以招待每個旅行者的人嗎?快點告訴我你需要什麼，我可沒有時間和你慢慢磨蹭。', `MaleText_loc7`='¿Acaso doy la impresión de tener el tiempo o la energía para agasajar a todo turista que entra por mi puerta? Dime qué necesitas y lo haré rápido.', `FemaleText_loc1`='이곳을 드나드는 관광객들을 모두 돌봐줄 정도로 제가 시간과 정력이 남아도는 줄 아십니까? 어서 용건만 간단히 말씀해 보십시오.', `FemaleText_loc4`='我看上去像是那种闲得可以招待每个旅行者的人吗？快点告诉我你需要什么，我可没有时间和你慢慢磨蹭。', `FemaleText_loc5`='我看起來像是那種閑得可以招待每個旅行者的人嗎?快點告訴我你需要什麼，我可沒有時間和你慢慢磨蹭。', `FemaleText_loc7`='¿Acaso doy la impresión de tener el tiempo o la energía para agasajar a todo turista que entra por mi puerta? Dime qué necesitas y lo haré rápido.' WHERE `ID`=3342;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가죽세공 수련을 받으러 이곳까지 날 찾아오는 일은 드문데... 그래도 당신이 준비가 되었다면 쓸만한 기술은 몇 가지 가르쳐줄 수도 있을 것 같군요.', `MaleText_loc4`='找我学习制皮的学徒并不多，如果你准备好了，我马上就可以教你一些东西。', `MaleText_loc5`='找我學習製皮的學徒並不多，如果你準備好了，我馬上就可以教你一些東西。', `MaleText_loc7`='Aquí no vienen demasiados peleteros para recibir instrucción, pero supongo que puedo enseñarte algo si estás $gpreparado:preparada;.', `FemaleText_loc1`='가죽세공 수련을 받으러 이곳까지 날 찾아오는 일은 드문데... 그래도 당신이 준비가 되었다면 쓸만한 기술은 몇 가지 가르쳐줄 수도 있을 것 같군요.', `FemaleText_loc4`='找我学习制皮的学徒并不多，如果你准备好了，我马上就可以教你一些东西。', `FemaleText_loc5`='找我學習製皮的學徒並不多，如果你準備好了，我馬上就可以教你一些東西。', `FemaleText_loc7`='Aquí no vienen demasiados peleteros para recibir instrucción, pero supongo que puedo enseñarte algo si estás $gpreparado:preparada;.' WHERE `ID`=3343;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무두질을 배우러 이곳까지 날 찾아오는 일은 드문데... 그래도 당신이 준비가 되었다면 쓸만한 기술은 몇 가지 가르쳐줄 수도 있을 것 같군요.', `MaleText_loc4`='找我学习剥皮的学徒并不多，如果你准备好了，我马上就可以教你一些东西。', `MaleText_loc5`='找我學習剝皮的學徒並不多，如果你準備好了，我馬上就可以教你一些東西。', `MaleText_loc7`='No suelo recibir a muchos desolladores aquí buscando instrucción, pero supongo que puedo enseñarte algo si estás $gpreparado:preparada;.', `FemaleText_loc1`='무두질을 배우러 이곳까지 날 찾아오는 일은 드문데... 그래도 당신이 준비가 되었다면 쓸만한 기술은 몇 가지 가르쳐줄 수도 있을 것 같군요.', `FemaleText_loc4`='找我学习剥皮的学徒并不多，如果你准备好了，我马上就可以教你一些东西。', `FemaleText_loc5`='找我學習剝皮的學徒並不多，如果你準備好了，我馬上就可以教你一些東西。', `FemaleText_loc7`='No suelo recibir a muchos desolladores aquí buscando instrucción, pero supongo que puedo enseñarte algo si estás $gpreparado:preparada;.' WHERE `ID`=3344;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 자물쇠 따기 기술을 사용하면 이곳 주민들은 불쾌한 눈초리로 쳐다보곤 한답니다. 아직 저도 초보일 뿐이지만, 제가 배운 몇 가지 요령을 가르쳐 드릴게요.', `MaleText_loc4`='大多数人似乎都对开锁技巧有一些偏见。让我给你露两手看看吧。', `MaleText_loc5`='大多數人似乎都對開鎖技巧有一些偏見。讓我給你露兩手看看吧。', `MaleText_loc7`='La mayor parte de la gente de por aquí frunce el ceño cuando se les habla de forzar cerraduras. A modo de cortesía profesional, te enseñaré unos cuantos trucos que he aprendido.', `FemaleText_loc1`='제가 자물쇠 따기 기술을 사용하면 이곳 주민들은 불쾌한 눈초리로 쳐다보곤 한답니다. 아직 저도 초보일 뿐이지만, 제가 배운 몇 가지 요령을 가르쳐 드릴게요.', `FemaleText_loc4`='大多数人似乎都对开锁技巧有一些偏见。让我给你露两手看看吧。', `FemaleText_loc5`='大多數人似乎都對開鎖技巧有一些偏見。讓我給你露兩手看看吧。', `FemaleText_loc7`='La mayor parte de la gente de por aquí frunce el ceño cuando se les habla de forzar cerraduras. A modo de cortesía profesional, te enseñaré unos cuantos trucos que he aprendido.' WHERE `ID`=3345;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용건만 간단히 말해 주세요.', `MaleText_loc4`='你需要什么？有话快说。', `MaleText_loc5`='你需要什麼?有話快說。', `MaleText_loc7`='Dime qué quieres y hazlo rápido.', `FemaleText_loc1`='용건만 간단히 말해 주세요.', `FemaleText_loc4`='你需要什么？有话快说。', `FemaleText_loc5`='你需要什麼?有話快說。', `FemaleText_loc7`='Dime qué quieres y hazlo rápido.' WHERE `ID`=3346;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제게 연금술을 배우시려고요?', `FemaleText_loc4`='你要接受炼金术训练，是吗？', `FemaleText_loc5`='你要接受鍊金術訓練，是嗎?', `FemaleText_loc7`='Requieres mis habilidades como alquimista, ¿verdad?' WHERE `ID`=3347;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연금술을 배우고 싶습니다.', `MaleText_loc4`='我希望接受炼金术训练。', `MaleText_loc5`='我希望接受鍊金術訓練。', `MaleText_loc7`='Quisiera recibir instrucción en alquimia.', `FemaleText_loc1`='연금술을 배우고 싶습니다.', `FemaleText_loc4`='我希望接受炼金术训练。', `FemaleText_loc5`='我希望接受鍊金術訓練。', `FemaleText_loc7`='Quisiera recibir instrucción en alquimia.' WHERE `ID`=3349;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오시오. 반갑소이다. 내게 연금술을 배우고자 온 것 아니오?', `MaleText_loc4`='你要接受炼金术训练，是吗？', `MaleText_loc5`='你要接受鍊金術訓練，是嗎?', `MaleText_loc7`='Requieres mis habilidades como alquimista, ¿verdad?' WHERE `ID`=3350;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='큰 전쟁은 끝났을지 모르지만 전사로서 기술 연마를 게을리해서는 안 돼!', `MaleText_loc4`='虽然现在是和平时期，但是我们可不能荒废了我们的战斗技能！', `MaleText_loc5`='雖然現在是和平時期，但是我們可不能荒廢了我們的戰鬥技能!', `MaleText_loc7`='Quizás las grandes guerras hayan acabado por el momento, ¡pero seguimos teniendo que mantener nuestras habilidades a punto!', `FemaleText_loc1`='큰 전쟁은 끝났을지 모르지만 전사로서 기술 연마를 게을리해서는 안 돼!', `FemaleText_loc4`='虽然现在是和平时期，但是我们可不能荒废了我们的战斗技能！', `FemaleText_loc5`='雖然現在是和平時期，但是我們可不能荒廢了我們的戰鬥技能!', `FemaleText_loc7`='Quizás las grandes guerras hayan acabado por el momento, ¡pero seguimos teniendo que mantener nuestras habilidades a punto!' WHERE `ID`=3351;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드는 우리 인간 종족의 요지로서, 용감한 우리 전사들의 굳건한 의지와 힘으로 지켜내고 있소.', `MaleText_loc4`='暴风城是人类的支柱，它是建立在钢铁的意志和锋利的刀刃上的。', `MaleText_loc5`='暴風城是人類的支柱，它是建立在鋼鐵的意志和鋒利的刀刃上的。', `MaleText_loc7`='Ventormenta es el pilar de la raza humana, y se mantiene gracias a la fuerza de voluntad y al filo de una fuerte espada.', `FemaleText_loc1`='스톰윈드는 우리 인간 종족의 요지로서, 용감한 우리 전사들의 굳건한 의지와 힘으로 지켜내고 있답니다.', `FemaleText_loc4`='暴风城是人类的支柱，它是建立在钢铁的意志和锋利的刀刃上的。', `FemaleText_loc5`='暴風城是人類的支柱，它是建立在鋼鐵的意志和鋒利的刀刃上的。', `FemaleText_loc7`='Ventormenta es el pilar de la raza humana, y se mantiene gracias a la fuerza de voluntad y al filo de una fuerte espada.' WHERE `ID`=3352;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엘룬의 축복을 그대에게... 전투 기술도 잘만 배우면 예술의 경지에 이를 수 있답니다.', `MaleText_loc4`='你好。你想要学一些战斗技巧吗？', `MaleText_loc5`='你好。你想要學一些戰鬥技巧嗎?', `MaleText_loc7`='Saludos. ¿Buscas instrucción en el arte de la guerra?', `FemaleText_loc1`='엘룬의 축복을 그대에게... 전투 기술도 잘만 배우면 예술의 경지에 이를 수 있답니다.', `FemaleText_loc4`='你好。你想要学一些战斗技巧吗？', `FemaleText_loc5`='你好。你想要學一些戰鬥技巧嗎?', `FemaleText_loc7`='Saludos. ¿Buscas instrucción en el arte de la guerra?' WHERE `ID`=3353;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배움의 길은 끝이 없는 법이지요... 꾸준히 정진해 나가길 바랍니다.', `MaleText_loc4`='活到老，学到老。', `MaleText_loc5`='活到老，學到老。', `MaleText_loc7`='No importa cuánto aprendamos, siempre queda más por saber.', `FemaleText_loc1`='배움의 길은 끝이 없는 법이지요... 꾸준히 정진해 나가길 바랍니다.', `FemaleText_loc4`='活到老，学到老。', `FemaleText_loc5`='活到老，學到老。', `FemaleText_loc7`='No importa cuánto aprendamos, siempre queda más por saber.' WHERE `ID`=3354;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전사의 역할 중 하나는 보호일세. 전장에서 전우를 보호하듯이 우리는 포세이큰의 이권을 보호해야만 하는 것이지.', `MaleText_loc4`='战士的任务之一就是保护。正如我们在战场上保护自己的同伴一样，我们要时刻保护被遗忘者的利益。', `MaleText_loc5`='戰士的任務之一就是保護。正如我們在戰場上保護自己的同伴一樣，我們要時刻保護被遺忘者的利益。', `MaleText_loc7`='El papel del guerrero es el de proteger. Así como protegemos a nuestros compatriotas en la batalla, también debemos proteger los intereses de los Renegados.', `FemaleText_loc1`='전사의 역할 중 하나는 보호일세. 전장에서 전우를 보호하듯이 우리는 포세이큰의 이권을 보호해야만 하는 것이지.', `FemaleText_loc4`='战士的任务之一就是保护。正如我们在战场上保护自己的同伴一样，我们要时刻保护被遗忘者的利益。', `FemaleText_loc5`='戰士的任務之一就是保護。正如我們在戰場上保護自己的同伴一樣，我們要時刻保護被遺忘者的利益。', `FemaleText_loc7`='El papel del guerrero es el de proteger. Así como protegemos a nuestros compatriotas en la batalla, también debemos proteger los intereses de los Renegados.' WHERE `ID`=3355;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 응급치료사 친구로군요. 당신의 여행에 도움이 된다면 무엇이든 기꺼이 가르쳐드리도록 하지요.', `MaleText_loc4`='哦，一个医师。我愿意传授给你一些能够在你旅途中对你有所帮助的东西。', `MaleText_loc5`='哦，一個同夥的治療師。我願意傳授任何能幫助你旅途的東西。', `MaleText_loc7`='Oh, un compañero médico. Será un placer para mí enseñarte cualquier cosa que pueda servirte en tus viajes.', `FemaleText_loc1`='오, 응급치료사 친구로군요. 당신의 여행에 도움이 된다면 무엇이든 기꺼이 가르쳐드리도록 하지요.', `FemaleText_loc4`='哦，一个医师。我愿意传授给你一些能够在你旅途中对你有所帮助的东西。', `FemaleText_loc5`='哦，一個同夥的治療師。我願意傳授任何能幫助你旅途的東西。', `FemaleText_loc7`='Oh, un compañero médico. Será un placer para mí enseñarte cualquier cosa que pueda servirte en tus viajes.' WHERE `ID`=3356;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일이십니까? 도와드릴 일이 있습니까?', `MaleText_loc4`='怎么了，$g小伙子:姑娘;？我能帮你什么忙吗？', `MaleText_loc5`='怎麼了，$g小夥子:姑娘;?我能幫你什麼忙嗎?', `MaleText_loc7`='¿Sí, $ghijo:hija; mía? ¿En qué puedo ayudarte?', `FemaleText_loc1`='무슨 일이십니까? 도와드릴 일이 있습니까?', `FemaleText_loc4`='怎么了，$g小伙子:姑娘;？我能帮你什么忙吗？', `FemaleText_loc5`='怎麼了，$g小夥子:姑娘;?我能幫你什麼忙嗎?', `FemaleText_loc7`='¿Sí, $ghijo:hija; mía? ¿En qué puedo ayudarte?' WHERE `ID`=3357;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 또 다른 야영 전문가로군... 흠, 당신은 아직 나만큼 경지에 이르지는 못한 것 같군요. 제대로 된 기술을 몇 가지 가르쳐 드리겠습니다.', `MaleText_loc4`='另一个生存技能专家，嗯……我认为你的水平已经和我差不多了，也许我只能在个别细节上给你一些点拨。', `MaleText_loc5`='另一個生存技能專家，嗯...我認為你的水準已經和我差不多了，也許我只能在個別細節上給你一些點撥。', `MaleText_loc7`='$gOtro:Otra; superviviente, mmm... Dudo mucho que tus habilidades sean tan magníficas como las mías, así que quizás pueda entrenarte para que aprendas algunas técnicas en condiciones.', `FemaleText_loc1`='오, 또 다른 야영 전문가로군... 흠, 당신은 아직 나만큼 경지에 이르지는 못한 것 같군요. 제대로 된 기술을 몇 가지 가르쳐 드리겠습니다.', `FemaleText_loc4`='另一个生存技能专家，嗯……我认为你的水平已经和我差不多了，也许我只能在个别细节上给你一些点拨。', `FemaleText_loc5`='另一個生存技能專家，嗯...我認為你的水準已經和我差不多了，也許我只能在個別細節上給你一些點撥。', `FemaleText_loc7`='$gOtro:Otra; superviviente, mmm... Dudo mucho que tus habilidades sean tan magníficas como las mías, así que quizás pueda entrenarte para que aprendas algunas técnicas en condiciones.' WHERE `ID`=3358;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 추적 기술을 배우러 오셨군요?! 배울 것이 많아 보이니 제대로 된 기술을 몇 가지 가르쳐 드리겠습니다.', `MaleText_loc4`='又一个追踪者，嗯……我认为你的水平已经和我差不多了，也许我只能在个别细节上给你一些点拨。', `MaleText_loc5`='又一個追蹤者，嗯...我認為你的水準已經和我差不多了，也許我只能在個別細節上給你一些點撥。', `MaleText_loc7`='$gOtro rastreador:Otra rastreadora;, mmm... Dudo mucho que tus habilidades sean tan magníficas como las mías, así que quizás pueda entrenarte para que aprendas algunas técnicas en condiciones.', `FemaleText_loc1`='오, 추적 기술을 배우러 오셨군요?! 배울 것이 많아 보이니 제대로 된 기술을 몇 가지 가르쳐 드리겠습니다.', `FemaleText_loc4`='又一个追踪者，嗯……我认为你的水平已经和我差不多了，也许我只能在个别细节上给你一些点拨。', `FemaleText_loc5`='又一個追蹤者，嗯...我認為你的水準已經和我差不多了，也許我只能在個別細節上給你一些點撥。', `FemaleText_loc7`='$gOtro rastreador:Otra rastreadora;, mmm... Dudo mucho que tus habilidades sean tan magníficas como las mías, así que quizás pueda entrenarte para que aprendas algunas técnicas en condiciones.' WHERE `ID`=3359;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='솔직히 말씀드리면 저는 돌과 철로 만든 이 인간들의 도시가 별로 마음에 들지 않아요. 들짐승들을 맘껏 추적할 수 있는 잿빛 골짜기의 드넓은 숲이 훨씬 낫지요. 캘브루스 오빠는 우리의 방식으로 인간들을 길들이면 좋을 거라고 하죠. 오빠의 말이니까 존중하고 도와야 하겠지만, 그렇다고 그 사고방식에 찬성한다는 건 아니에요.', `MaleText_loc4`='说老实话，我并不喜欢人类的那种用冰冷的石头和钢铁铸造起来的城市。我还是喜欢待在灰谷，过着自由自在的生活。但是我亲爱的兄弟凯尔布鲁斯认为向人类传授我们的追踪技巧对大家都有好处。所以，你瞧，我在这里为人类提供训练服务，但这并不意味着我就得喜欢这份工作。', `MaleText_loc5`='說老實話，我並不喜歡人類的那種用冰冷的石頭和鋼鐵鑄造起來的城市。我還是喜歡待在梣谷，過著自由自在的生活。但是我親愛的兄弟凱爾布魯斯認為向人類傳授我們的追蹤技巧對大家都有好處。所以，你瞧，我在這裡為人類提供訓練服務，但這並不意味著我就得喜歡這份工作。', `MaleText_loc7`='No me gustan estas ciudades humanas de piedra y acero. Prefiero los bosques de Vallefresno, en donde puedo rastrear grandes bestias. Pero mi querido hermano, Kaerbrus, pensó que podía ser positivo instruir a humanos en nuestras habilidades. Así que, aunque le honre y ofrezca mis servicios, no tiene por qué gustarme.', `FemaleText_loc1`='솔직히 말씀드리면 저는 돌과 철로 만든 이 인간들의 도시가 별로 마음에 들지 않아요. 들짐승들을 맘껏 추적할 수 있는 잿빛 골짜기의 드넓은 숲이 훨씬 낫지요. 캘브루스 오빠는 우리의 방식으로 인간들을 길들이면 좋을 거라고 하죠. 오빠의 말이니까 존중하고 도와야 하겠지만, 그렇다고 그 사고방식에 찬성한다는 건 아니에요.', `FemaleText_loc4`='他不是一只鸡，所以你不能把他当作宠物。该干什么干什么去，不然我就给你点颜色看看。', `FemaleText_loc5`='我不喜歡這些人類城市裡面的石材與鋼鐵。我還是喜歡梣谷的森林，追蹤那些巨大的野獸。但是我的兄弟，凱爾布魯斯，覺得如果人類能按照我們的方式訓練的話可以增加一些優勢。所以儘管我只是為了他的榮耀而提供我的服務，並不代表我得喜歡這麼做。', `FemaleText_loc7`='No me gustan estas ciudades humanas de piedra y acero. Prefiero los bosques de Vallefresno, en donde puedo rastrear grandes bestias. Pero mi querido hermano, Kaerbrus, pensó que podía ser positivo instruir a humanos en nuestras habilidades. Así que, aunque le honre y ofrezca mis servicios, no tiene por qué gustarme.' WHERE `ID`=3360;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 스톰윈드의 재건 사업을 도우러 아이언포지에서 왔지만 우리 얼라이언스 친구들에게 내 기술을 충분히 전수하고 난 후에는 이곳 일을 맡겨버리고 고향으로 돌아가고 싶어...', `MaleText_loc4`='我从铁炉堡来到这里协助进行重建工作。我希望能向你传授尽可能多的本领，然后我就能回家去，把这堆事情丢给你来做。', `MaleText_loc5`='我從鐵爐堡來到這裡協助進行重建工作。我希望能向你傳授盡可能多的本領，然後我就能回家去，把這堆事情丟給你來做。', `MaleText_loc7`='He venido desde Forjaz para contribuir en las tareas de reconstrucción. Si logro enseñaros gran parte de mis conocimientos, tal vez entonces pueda dejaros y volver a casa.', `FemaleText_loc1`='난 스톰윈드의 재건 사업을 도우러 아이언포지에서 왔지만 우리 얼라이언스 친구들에게 내 기술을 충분히 전수하고 난 후에는 이곳 일을 맡겨버리고 고향으로 돌아가고 싶어...', `FemaleText_loc4`='我从铁炉堡来到这里协助进行重建工作。我希望能向你传授尽可能多的本领，然后我就能回家去，把这堆事情丢给你来做。', `FemaleText_loc5`='我從鐵爐堡來到這裡協助進行重建工作。我希望能向你傳授盡可能多的本領，然後我就能回家去，把這堆事情丟給你來做。', `FemaleText_loc7`='He venido desde Forjaz para contribuir en las tareas de reconstrucción. Si logro enseñaros gran parte de mis conocimientos, tal vez entonces pueda dejaros y volver a casa.' WHERE `ID`=3361;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런, 한창 작업 중이었는데... 그래, 무슨 일이신지? 설마 아무 이유도 없이 그냥 한번 불러본 건 아닐테고...', `MaleText_loc4`='什么？你打扰我了，你最好赶快找到一个说得过去的理由。', `MaleText_loc5`='什麼?你打擾我了，你最好趕快找到一個說得過去的理由。', `MaleText_loc7`='¿Sí? Me has interrumpido, así que espero que tengas una buena razón para ello.', `FemaleText_loc1`='이런, 한창 작업 중이었는데... 그래, 무슨 일이신지? 설마 아무 이유도 없이 그냥 한번 불러본 건 아닐테고...', `FemaleText_loc4`='什么？你打扰我了，你最好赶快找到一个说得过去的理由。', `FemaleText_loc5`='什麼?你打擾我了，你最好趕快找到一個說得過去的理由。', `FemaleText_loc7`='¿Sí? Me has interrumpido, así que espero que tengas una buena razón para ello.' WHERE `ID`=3362;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타조를 애완동물로 기른다면 비웃을 이들도 많겠지만, 타조는 영리한데다 충성스럽기까지 하다고요. 여러 면에서 이만한 동물이 없다니까요. 혹시 관심이 있다면 제가 수년에 걸쳐 익힌 기술을 몇 가지, 그대와 그대의 야수에게 가르쳐 드리겠습니다.', `MaleText_loc4`='许多人也许会告诉你把陆行鸟作为宠物是一件可笑的事情。但是它的智力和忠诚度使其可以成为你最好的伙伴。如果你对它感兴趣的话，我可以向你和你的宠物传授一些技能。', `MaleText_loc5`='許多人也許會告訴你把陸行鳥作為寵物是一件可笑的事情。但是它的智力和忠誠度使其可以成為你最好的夥伴。如果你對它感興趣的話，我可以向你和你的寵物傳授一些技能。', `MaleText_loc7`='Muchos dirían que el zancaalta es una mascota ridícula. Pero su inteligencia y lealtad la convierten en una criatura insustituible en muchas situaciones. Si te interesa esta variedad, tal vez pueda enseñaros a ti y a tu mascota algunas habilidades que he aprendido con los años.', `FemaleText_loc1`='타조를 애완동물로 기른다면 비웃을 이들도 많겠지만, 타조는 영리한데다 충성스럽기까지 하다고요. 여러 면에서 이만한 동물이 없다니까요. 혹시 관심이 있다면 제가 수년에 걸쳐 익힌 기술을 몇 가지, 그대와 그대의 야수에게 가르쳐 드리겠습니다.', `FemaleText_loc4`='许多人也许会告诉你把陆行鸟作为宠物是一件可笑的事情。但是它的智力和忠诚度使其可以成为你最好的伙伴。如果你对它感兴趣的话，我可以向你和你的宠物传授一些技能。', `FemaleText_loc5`='許多人也許會告訴你把陸行鳥作為寵物是一件可笑的事情。但是它的智力和忠誠度使其可以成為你最好的夥伴。如果你對它感興趣的話，我可以向你和你的寵物傳授一些技能。', `FemaleText_loc7`='Muchos dirían que el zancaalta es una mascota ridícula. Pero su inteligencia y lealtad la convierten en una criatura insustituible en muchas situaciones. Si te interesa esta variedad, tal vez pueda enseñaros a ti y a tu mascota algunas habilidades que he aprendido con los años.' WHERE `ID`=3363;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 녀석은 닭이 아닙니다. 야수로 삼을 수도 없을 겁니다. 어서 떠나지 않으면 이 녀석의 커다란 부리 맛을 호되게 보게 될 것이니 가던 길이나 가십시오.', `MaleText_loc4`='他不是一只鸡，所以你不能把他当作宠物。该干什么干什么去，不然我就给你点颜色看看。', `MaleText_loc5`='他不是一隻雞，所以你不能把他當作寵物。該幹什麼幹什麼去，不然我就給你點顏色看看。', `MaleText_loc7`='No es un pollo y tampoco se lo puede acariciar. Vete antes de que le eche un vistazo más de cerca en el pico.', `FemaleText_loc1`='이 녀석은 닭이 아닙니다. 야수로 삼을 수도 없을 겁니다. 어서 떠나지 않으면 이 녀석의 커다란 부리 맛을 호되게 보게 될 것이니 가던 길이나 가십시오.', `FemaleText_loc4`='他不是一只鸡，所以你不能把他当作宠物。该干什么干什么去，不然我就给你点颜色看看。', `FemaleText_loc5`='他不是一隻雞，所以你不能把他當作寵物。該幹什麼幹什麼去，不然我就給你點顏色看看。', `FemaleText_loc7`='No es un pollo y tampoco se lo puede acariciar. Vete antes de que le eche un vistazo más de cerca en el pico.' WHERE `ID`=3364;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날카로운 이빨, 쇠밧줄같이 튼튼한 근육, 강철과 같이 냉혹한 성격... 이 녀석은 지금까지 내가 본 야수 중 최고예요. 혹시 흥미가 있다면, 몇 가지 기술을 가르쳐 드리죠. 아무리 약한 녀석이라도 강인한 랩터로 훈련할 수 있어요.', `MaleText_loc4`='锋利的牙齿，坚实的肌肉，还有钢铁般的意志。这可是难得的宠物啊。如果你有兴趣，我可以告诉你如何把最弱的迅猛龙变成你在战斗中最好的伙伴。', `MaleText_loc5`='鋒利的牙齒，堅實的肌肉，還有鋼鐵般的意志。這可是難得的寵物啊。如果你有興趣，我可以告訴你如何把最弱的迅猛龍變成你在戰鬥中最好的夥伴。', `MaleText_loc7`='Dientes afilados, músculos como cables y una mente ágil. Este ejemplar es una de las mascotas más finas que he visto nunca. Ahora bien, si te interesa, puedo enseñarte unas cuantas cosas para convertir incluso al más débil de los raptores en un oponente difícil.', `FemaleText_loc1`='날카로운 이빨, 쇠밧줄같이 튼튼한 근육, 강철과 같이 냉혹한 성격... 이 녀석은 지금까지 내가 본 야수 중 최고예요. 혹시 흥미가 있다면, 몇 가지 기술을 가르쳐 드리죠. 아무리 약한 녀석이라도 강인한 랩터로 훈련할 수 있어요.', `FemaleText_loc4`='锋利的牙齿，坚实的肌肉，还有钢铁般的意志。这可是难得的宠物啊。如果你有兴趣，我可以告诉你如何把最弱的迅猛龙变成你在战斗中最好的伙伴。', `FemaleText_loc5`='鋒利的牙齒，堅實的肌肉，還有鋼鐵般的意志。這可是難得的寵物啊。如果你有興趣，我可以告訴你如何把最弱的迅猛龍變成你在戰鬥中最好的夥伴。', `FemaleText_loc7`='Dientes afilados, músculos como cables y una mente ágil. Este ejemplar es una de las mascotas más finas que he visto nunca. Ahora bien, si te interesa, puedo enseñarte unas cuantas cosas para convertir incluso al más débil de los raptores en un oponente difícil.' WHERE `ID`=3365;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 가던 길이나 가시는 게 좋겠어요. 이 녀석이 배가 고픈데다 $R 냄새를 맡으니 식욕이 동하는 모양이군요.', `MaleText_loc4`='你最好离远点，$g小伙子:姑娘;。我的宠物肚子饿了，显然它对你垂涎欲滴。', `MaleText_loc5`='你最好離遠點，$g小夥子:姑娘;。我的寵物肚子餓了，顯然它對你垂涎欲滴。', `MaleText_loc7`='Debes marcharte, $gmuchacho:muchacha;. Mi mascota está hambrienta y le gusta tu olor.', `FemaleText_loc1`='어서 가던 길이나 가시는 게 좋겠어요. 이 녀석이 배가 고픈데다 $R 냄새를 맡으니 식욕이 동하는 모양이군요.', `FemaleText_loc4`='你最好离远点，$g小伙子:姑娘;。我的宠物肚子饿了，显然它对你垂涎欲滴。', `FemaleText_loc5`='你最好離遠點，$g小夥子:姑娘;。我的寵物肚子餓了，顯然它對你垂涎欲滴。', `FemaleText_loc7`='Debes marcharte, $gmuchacho:muchacha;. Mi mascota está hambrienta y le gusta tu olor.' WHERE `ID`=3366;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 피에 젖은 채 광선에 휩싸입니다!', `MaleText_loc4`='%s浑身是血，变得异常狂暴！', `MaleText_loc5`='%s濺了滿身的血，變得異常狂暴!', `MaleText_loc7`='%s recibe salpicaduras de sangre y se pone radiante de felicidad.', `FemaleText_loc1`='%s|1이;가; 피에 젖은 채 광선에 휩싸입니다!', `FemaleText_loc4`='%s浑身是血，变得异常狂暴！', `FemaleText_loc5`='%s濺了滿身的血，變得異常狂暴!', `FemaleText_loc7`='%s recibe salpicaduras de sangre y se pone radiante de felicidad.' WHERE `ID`=3367;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달라란이 몰락하고 쿠엘탈라스가 멸망한 후로 이런 종류의 물건을 손에 넣기가 매우 어려웠습니다. 하지만 루칸 코르델과 다른 직업용품 상인들이 우리 주문에 따라 아주 질 좋은 물건들을 잘 공급해 주고 있답니다. 특별히 찾으시는 물건이 있으십니까?', `MaleText_loc4`='在达拉然陷落和奎尔萨拉斯被摧毁之后，这样的东西就很难在世面上看到了。但是鲁坎·考迪尔和我的其他一些商业伙伴很好的完成了我的订单。', `MaleText_loc5`='在達拉然陷落和奎爾薩拉斯被摧毀之後，這樣的東西就很難在世面上看到了。但是魯坎·考迪爾和我的其他一些商業夥伴很好的完成了我的訂單。', `MaleText_loc7`='Desde la caída de Dalaran y la destrucción de Quel''Thalas, es difícil conseguir mercancía de este tipo. Sin embargo, Lucan Cordell y otros de nuestros mercaderes llevan tiempo satisfaciendo nuestros pedidos con mercancía de gran calidad.', `FemaleText_loc1`='달라란이 몰락하고 쿠엘탈라스가 멸망한 후로 이런 종류의 물건을 손에 넣기가 매우 어려웠습니다. 하지만 루칸 코르델과 다른 직업용품 상인들이 우리 주문에 따라 아주 질 좋은 물건들을 잘 공급해 주고 있답니다. 특별히 찾으시는 물건이 있으십니까?', `FemaleText_loc4`='在达拉然陷落和奎尔萨拉斯被摧毁之后，这样的东西就很难在世面上看到了。但是鲁坎·考迪尔和我的其他一些商业伙伴很好的完成了我的订单。', `FemaleText_loc5`='在達拉然陷落和奎爾薩拉斯被摧毀之後，這樣的東西就很難在世面上看到了。但是魯坎·考迪爾和我的其他一些商業夥伴很好的完成了我的訂單。', `FemaleText_loc7`='Desde la caída de Dalaran y la destrucción de Quel''Thalas, es difícil conseguir mercancía de este tipo. Sin embargo, Lucan Cordell y otros de nuestros mercaderes llevan tiempo satisfaciendo nuestros pedidos con mercancía de gran calidad.' WHERE `ID`=3368;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 이곳 스톰윈드의 장인과 마법사가 만든 최고의 마법 장비만을 팔고 있습니다. 원하시는 물건이 있으시면 말씀해 주시기 바랍니다.', `MaleText_loc4`='我这里卖的可都是由暴风城最好的工匠和法师制作东西，世上最好的魔法装备！', `MaleText_loc5`='我這裡賣的可都是由暴風城最好的工匠和法師製作東西，世上最好的魔法裝備!', `MaleText_loc7`='Yo solo vendo equipamiento arcano de la mayor calidad, fabricado por los artesanos y magos de Ventormenta.', `FemaleText_loc1`='저는 이곳 스톰윈드의 장인과 마법사가 만든 최고의 마법 장비만을 팔고 있습니다. 원하시는 물건이 있으시면 말씀해 주시기 바랍니다.', `FemaleText_loc4`='我这里卖的可都是由暴风城最好的工匠和法师制作东西，世上最好的魔法装备！', `FemaleText_loc5`='我這裡賣的可都是由暴風城最好的工匠和法師製作東西，世上最好的魔法裝備!', `FemaleText_loc7`='Yo solo vendo equipamiento arcano de la mayor calidad, fabricado por los artesanos y magos de Ventormenta.' WHERE `ID`=3369;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물건을 보고 싶습니다.', `MaleText_loc4`='我想要看看你卖的货物。', `MaleText_loc5`='我想要看看你賣的貨物。', `MaleText_loc7`='Quiero ver tus mercancías.', `FemaleText_loc1`='물건을 보고 싶습니다.', `FemaleText_loc4`='我想要看看你卖的货物。', `FemaleText_loc5`='我想要看看你賣的貨物。', `FemaleText_loc7`='Quiero ver tus mercancías.' WHERE `ID`=3370;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달라란이 몰락하고 쿠엘탈라스가 멸망한 후로 이런 종류의 물건을 손에 넣기가 매우 어려웠답니다. 하지만 루칸 코르델과 다른 직업용품 상인들이 우리 주문에 따라 아주 질 좋은 물건들을 잘 공급해 주고 있답니다. 찾는 물건이 있으면 언제든지 말씀해 주시기 바랍니다.', `MaleText_loc4`='在达拉然陷落和奎尔萨拉斯被摧毁之后，这样的东西就很难在世面上看到了。但是鲁坎·考迪尔和我的其他一些商业伙伴很好的完成了我的订单。', `MaleText_loc5`='在達拉然陷落和奎爾薩拉斯被摧毀之後，這樣的東西就很難在世面上看到了。但是魯坎·考迪爾和我的其他一些商業夥伴很好的完成了我的訂單。', `MaleText_loc7`='Desde la caída de Dalaran y la destrucción de Quel''Thalas, es difícil conseguir mercancía de este tipo. Sin embargo, Lucan Cordell y otros de nuestros mercaderes llevan tiempo satisfaciendo nuestros pedidos con mercancía de gran calidad.', `FemaleText_loc1`='달라란이 몰락하고 쿠엘탈라스가 멸망한 후로 이런 종류의 물건을 손에 넣기가 매우 어려웠답니다. 하지만 루칸 코르델과 다른 직업용품 상인들이 우리 주문에 따라 아주 질 좋은 물건들을 잘 공급해 주고 있답니다. 찾는 물건이 있으면 언제든지 말씀해 주시기 바랍니다.', `FemaleText_loc4`='在达拉然陷落和奎尔萨拉斯被摧毁之后，这样的东西就很难在世面上看到了。但是鲁坎·考迪尔和我的其他一些商业伙伴很好的完成了我的订单。', `FemaleText_loc5`='在達拉然陷落和奎爾薩拉斯被摧毀之後，這樣的東西就很難在世面上看到了。但是魯坎·考迪爾和我的其他一些商業夥伴很好的完成了我的訂單。', `FemaleText_loc7`='Desde la caída de Dalaran y la destrucción de Quel''Thalas, es difícil conseguir mercancía de este tipo. Sin embargo, Lucan Cordell y otros de nuestros mercaderes llevan tiempo satisfaciendo nuestros pedidos con mercancía de gran calidad.' WHERE `ID`=3371;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 스톰윈드 최고의 장인들과 마법사가 만든 최고의 물건만을 팔고 있습니다. 천천히 둘러보시기 바랍니다.', `MaleText_loc4`='我这里卖的可都是由暴风城最好的工匠和法师制作东西，世上最好的魔法装备！', `MaleText_loc5`='我這裡賣的可都是由暴風城最好的工匠和法師製作東西，世上最好的魔法裝備!', `MaleText_loc7`='Yo solo vendo equipamiento arcano de la mayor calidad, fabricado por los artesanos y magos de Ventormenta.', `FemaleText_loc1`='저는 스톰윈드 최고의 장인들과 마법사가 만든 최고의 물건만을 팔고 있습니다. 천천히 둘러보시기 바랍니다.', `FemaleText_loc4`='我这里卖的可都是由暴风城最好的工匠和法师制作东西，世上最好的魔法装备！', `FemaleText_loc5`='我這裡賣的可都是由暴風城最好的工匠和法師製作東西，世上最好的魔法裝備!', `FemaleText_loc7`='Yo solo vendo equipamiento arcano de la mayor calidad, fabricado por los artesanos y magos de Ventormenta.' WHERE `ID`=3372;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 상점의 물건들은 텔드랏실에서 가장 솜씨 좋은 장인들이 만든 것들로, 세계수의 나이트 엘프들과 이 땅의 인간들이 영광스러운 얼라이언스의 동맹으로서 관계가 발전함에 따라 그 우호의 표시로 칼림도어에서 아제로스까지 직접 수송한 것들입니다. 둘러보시다가 필요한 게 있으시면 주저 말고 말씀하시기 바랍니다.', `MaleText_loc4`='为了增进暗夜精灵和人类的联盟关系，我千里迢迢带来了由泰达希尔最好的工匠制作的东西。我这里的东西应有尽有，请随意挑选。', `MaleText_loc5`='為了增進夜精靈和人類的聯盟關係，我千里迢迢帶來了由泰達希爾最好的工匠製作的東西。我這裡的東西應有盡有，請隨意挑選。', `MaleText_loc7`='Realizado por los más finos artesanos de todo Teldrassil, cuidadosamente transportado de Kalimdor a Azeroth en señal de la creciente alianza entre la gente del Gran Árbol y los humanos de esta tierra. Si necesitas algo, solo tienes que pedirlo.', `FemaleText_loc1`='우리 상점의 물건들은 텔드랏실에서 가장 솜씨 좋은 장인들이 만든 것들로, 세계수의 나이트 엘프들과 이 땅의 인간들이 영광스러운 얼라이언스의 동맹으로서 관계가 발전함에 따라 그 우호의 표시로 칼림도어에서 아제로스까지 직접 수송한 것들입니다. 둘러보시다가 필요한 게 있으시면 주저 말고 말씀하시기 바랍니다.', `FemaleText_loc4`='为了增进暗夜精灵和人类的联盟关系，我千里迢迢带来了由泰达希尔最好的工匠制作的东西。我这里的东西应有尽有，请随意挑选。', `FemaleText_loc5`='為了增進夜精靈和人類的聯盟關係，我千里迢迢帶來了由泰達希爾最好的工匠製作的東西。我這裡的東西應有盡有，請隨意挑選。', `FemaleText_loc7`='Realizado por los más finos artesanos de todo Teldrassil, cuidadosamente transportado de Kalimdor a Azeroth en señal de la creciente alianza entre la gente del Gran Árbol y los humanos de esta tierra. Si necesitas algo, solo tienes que pedirlo.' WHERE `ID`=3373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달라란이 몰락하고 쿠엘탈라스가 멸망한 후로 이런 종류의 물건을 손에 넣기가 매우 어려웠죠. 하지만 루칸 코르델과 다른 직업용품 상인들이 우리 주문에 따라 아주 질 좋은 물건들을 잘 공급해 주고 있답니다. 오늘은 무슨 일로 오셨나요?', `MaleText_loc4`='在达拉然陷落和奎尔萨拉斯被摧毁之后，这样的东西就很难在世面上看到了。但是鲁坎·考迪尔和我的其他一些商业伙伴很好的完成了我的订单。', `MaleText_loc5`='在達拉然陷落和奎爾薩拉斯被摧毀之後，這樣的東西就很難在世面上看到了。但是魯坎·考迪爾和我的其他一些商業夥伴很好的完成了我的訂單。', `MaleText_loc7`='Desde la caída de Dalaran y la destrucción de Quel''Thalas, es difícil conseguir mercancía de este tipo. Sin embargo, Lucan Cordell y otros de nuestros mercaderes llevan tiempo satisfaciendo nuestros pedidos con mercancía de gran calidad.', `FemaleText_loc1`='달라란이 몰락하고 쿠엘탈라스가 멸망한 후로 이런 종류의 물건을 손에 넣기가 매우 어려웠죠. 하지만 루칸 코르델과 다른 직업용품 상인들이 우리 주문에 따라 아주 질 좋은 물건들을 잘 공급해 주고 있답니다. 오늘은 무슨 일로 오셨나요?', `FemaleText_loc4`='在达拉然陷落和奎尔萨拉斯被摧毁之后，这样的东西就很难在世面上看到了。但是鲁坎·考迪尔和我的其他一些商业伙伴很好的完成了我的订单。', `FemaleText_loc5`='在達拉然陷落和奎爾薩拉斯被摧毀之後，這樣的東西就很難在世面上看到了。但是魯坎·考迪爾和我的其他一些商業夥伴很好的完成了我的訂單。', `FemaleText_loc7`='Desde la caída de Dalaran y la destrucción de Quel''Thalas, es difícil conseguir mercancía de este tipo. Sin embargo, Lucan Cordell y otros de nuestros mercaderes llevan tiempo satisfaciendo nuestros pedidos con mercancía de gran calidad.' WHERE `ID`=3374;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 스톰윈드 최고의 장인들과 마법사가 만든 최고의 장비만을 팔고 있어요. 천천히 둘러보도록 하세요.', `MaleText_loc4`='我这里卖的可都是由暴风城最好的工匠和法师制作东西，世上最好的魔法装备！', `MaleText_loc5`='我這裡賣的可都是由暴風城最好的工匠和法師製作東西，世上最好的魔法裝備!', `MaleText_loc7`='Yo solo vendo equipamiento arcano de la mayor calidad, fabricado por los artesanos y magos de Ventormenta.', `FemaleText_loc1`='저는 스톰윈드 최고의 장인들과 마법사가 만든 최고의 장비만을 팔고 있어요. 천천히 둘러보도록 하세요.', `FemaleText_loc4`='我这里卖的可都是由暴风城最好的工匠和法师制作东西，世上最好的魔法装备！', `FemaleText_loc5`='我這裡賣的可都是由暴風城最好的工匠和法師製作東西，世上最好的魔法裝備!', `FemaleText_loc7`='Yo solo vendo equipamiento arcano de la mayor calidad, fabricado por los artesanos y magos de Ventormenta.' WHERE `ID`=3375;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희 상점은 스톰윈드에서 최고의 품질과 가격을 자랑합니다. 손님, 무엇을 도와드릴까요?', `MaleText_loc4`='暴风城最好的货物啊，朋友，你绝对不应该错过。看看有什么你需要的东西吗？', `MaleText_loc5`='暴風城最好的貨物啊，朋友，你絕對不應該錯過。看看有什麼你需要的東西嗎?', `MaleText_loc7`='Los mejores precios en todo Ventormenta, no encontrarás mejores precios. Y bien, ¿en qué puedo ayudarte?', `FemaleText_loc1`='저희 상점은 스톰윈드에서 최고의 품질과 가격을 자랑합니다. 손님, 무엇을 도와드릴까요?', `FemaleText_loc4`='暴风城最好的货物啊，朋友，你绝对不应该错过。看看有什么你需要的东西吗？', `FemaleText_loc5`='暴風城最好的貨物啊，朋友，你絕對不應該錯過。看看有什麼你需要的東西嗎?', `FemaleText_loc7`='Los mejores precios en todo Ventormenta, no encontrarás mejores precios. Y bien, ¿en qué puedo ayudarte?' WHERE `ID`=3376;
