UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크룸이란 타우렌을 찾아가 보시는 게 좋겠습니다. 썬더 블러프 봉우리 하층 길드사무소에 가면 그를 찾을 수 있을 겁니다.', `MaleText_loc4`='去找克拉姆吧。你可以在中心高地上的雷霆崖咨询处里找到他。', `MaleText_loc5`='去找克拉姆吧。你可以在中心高地上的雷霆崖諮詢處裡找到他。', `MaleText_loc7`='Krumn es el toro que estás buscando. Lo encontrarás en la pequeña pendiente, en el Servicio de información al ciudadano de Cima del Trueno.', `FemaleText_loc1`='크룸이란 타우렌을 찾아가 보시는 게 좋겠습니다. 썬더 블러프 봉우리 하층 길드사무소에 가면 그를 찾을 수 있을 겁니다.', `FemaleText_loc4`='去找克拉姆吧。你可以在中心高地上的雷霆崖咨询处里找到他。', `FemaleText_loc5`='去找克拉姆吧。你可以在中心高地上的雷霆崖諮詢處裡找到他。', `FemaleText_loc7`='Krumn es el toro que estás buscando. Lo encontrarás en la pequeña pendiente, en el Servicio de información al ciudadano de Cima del Trueno.' WHERE `ID`=3443;
