UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마을 중앙에 있는 토템 모양 건물의 계단 꼭대기로 올라가면 와이번 횃대를 찾을 수 있습니다.', `MaleText_loc4`='双足飞龙巢穴就在城镇中心的图腾柱顶部。', `MaleText_loc5`='雙足飛龍棲息處就在城鎮中心的圖騰柱頂部。', `MaleText_loc7`='La alcándara de jinete del viento está encima de la escalinata del tótem, en el centro de la ciudad.', `FemaleText_loc1`='마을 중앙에 있는 토템 모양 건물의 계단 꼭대기로 올라가면 와이번 횃대를 찾을 수 있습니다.', `FemaleText_loc4`='双足飞龙巢穴就在城镇中心的图腾柱顶部。', `FemaleText_loc5`='雙足飛龍棲息處就在城鎮中心的圖騰柱頂部。', `FemaleText_loc7`='La alcándara de jinete del viento es un está encima de la escalinata del tótem, en el centro de la ciudad.' WHERE `ID`=3445;
