UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장로의 봉우리에 있는 장로의 전당에서 투락 룬토템을 찾아가 보시기 바랍니다.', `MaleText_loc4`='去长者高地的长者大厅找图拉克·符文图腾吧。', `MaleText_loc5`='去長者高地的長者大廳找圖拉克·符文圖騰吧。', `MaleText_loc7`='Busca a Turak Tótem de Runa en la Sala de los Ancestros, que está en el Alto de los Ancestros.', `FemaleText_loc1`='장로의 봉우리에 있는 장로의 전당에서 투락 룬토템을 찾아가 보시기 바랍니다.', `FemaleText_loc4`='去长者高地的长者大厅找图拉克·符文图腾吧。', `FemaleText_loc5`='去長者高地的長者大廳找圖拉克·符文圖騰吧。', `FemaleText_loc7`='Busca a Turak Tótem de Runa en la Sala de los Ancestros, que está en el Alto de los Ancestros.' WHERE `ID`=3452;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 사냥꾼의 전당 쪽으로 가 보셔야 하겠군요. 수렵의 봉우리로 가시면 홀트 썬더혼과 같은 훌륭한 사냥꾼들을 만나볼 수 있을 겁니다.', `MaleText_loc4`='啊，那你就要去猎人高地上的猎手大厅了。你可以在那里找到像浩特·雷角那样伟大的猎人。', `MaleText_loc5`='啊，那你就要去獵人高地上的獵人大廳了。你可以在那裡找到像浩特·雷角那樣偉大的獵人。', `MaleText_loc7`='Ah, entonces tendrás que pasar por la Sala del Cazador. En el Alto de los Cazadores verás a grandes cazadores como Holt Tronacuerno.', `FemaleText_loc1`='아, 사냥꾼의 전당 쪽으로 가 보셔야 하겠군요. 수렵의 봉우리로 가시면 홀트 썬더혼과 같은 훌륭한 사냥꾼들을 만나볼 수 있을 겁니다.', `FemaleText_loc4`='啊，那你就要去猎人高地上的猎手大厅了。你可以在那里找到像浩特·雷角那样伟大的猎人。', `FemaleText_loc5`='啊，那你就要去獵人高地上的獵人大廳了。你可以在那裡找到像浩特·雷角那樣偉大的獵人。', `FemaleText_loc7`='Ah, entonces tendrás que pasar por la Sala del Cazador. En el Alto de los Cazadores verás a grandes cazadores como Holt Tronacuerno.' WHERE `ID`=3453;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신비로운 마법의 추종자시로군요?! 흠, 그렇다면... 정기의 봉우리 아래 있는 예언의 웅덩이 근처로 가 보십시오.', `MaleText_loc4`='你是魔法的研习者？嗯，好吧……你可以在灵魂高地下的预见之池中找到他们。', `MaleText_loc5`='你是魔法的研習者?嗯，好吧...你可以在靈魂高地下的預見之池中找到他們。', `MaleText_loc7`='¿Eres devoto del arcano? ¡Ajá! Muy bien pues... puedes encontrarlos por las Pozas de las Visiones bajo el Alto de los Espíritus.', `FemaleText_loc1`='신비로운 마법의 추종자시로군요?! 흠, 그렇다면... 정기의 봉우리 아래 있는 예언의 웅덩이 근처로 가 보십시오.', `FemaleText_loc4`='你是魔法的研习者？嗯，好吧……你可以在灵魂高地下的预见之池中找到他们。', `FemaleText_loc5`='你是魔法的研習者?嗯，好吧...你可以在靈魂高地下的預見之池中找到他們。', `FemaleText_loc7`='¿Eres devoto del arcano? ¡Ajá! Muy bien pues... puedes encontrarlos por las Pozas de las Visiones bajo el Alto de los Espíritus.' WHERE `ID`=3454;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신부 콥을 만나보셔야 하겠군요. 정기의 봉우리 아래 예언의 웅덩이 동굴에 있습니다.', `MaleText_loc4`='你应该找柯布神父谈谈，到灵魂高地下的预见之池去找他吧。', `MaleText_loc5`='你應該找柯布神父談談，到靈魂高地下的預見之池去找他吧。', `MaleText_loc7`='El padre Cobb es a quien buscas. Está debajo del Alto de los Espíritus en la caverna de las Pozas de las Visiones.', `FemaleText_loc1`='신부 콥을 만나보셔야 하겠군요. 정기의 봉우리 아래 예언의 웅덩이 동굴에 있습니다.', `FemaleText_loc4`='你应该找柯布神父谈谈，到灵魂高地下的预见之池去找他吧。', `FemaleText_loc5`='你應該找柯布神父談談，到靈魂高地下的預見之池去找他吧。', `FemaleText_loc7`='El padre Cobb es a quien buscas. Está debajo del Alto de los Espíritus en la caverna de las Pozas de las Visiones.' WHERE `ID`=3455;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정기의 봉우리에 있는 정기의 전당은 주술사에게는 집과 같은 곳입니다. 그곳으로 가시면 훌륭한 주술사들을 만나실 수 있을 겁니다. 선조님의 보살핌이 있으시길.', `MaleText_loc4`='灵魂大厅是萨满祭司的家园，它坐落在灵魂高地上。愿你的先祖保佑你。', `MaleText_loc5`='靈魂大廳是薩滿的家園，它坐落在靈魂高地上。願你的先祖保佑你。', `MaleText_loc7`='Nuestros chamanes consideran la Sala de los Espíritus su hogar. Lo encontrarás en el Alto de los Espíritus. Que tus antepasados cuiden de ti.', `FemaleText_loc1`='정기의 봉우리에 있는 정기의 전당은 주술사에게는 집과 같은 곳입니다. 그곳으로 가시면 훌륭한 주술사들을 만나실 수 있을 겁니다. 선조님의 보살핌이 있으시길.', `FemaleText_loc4`='灵魂大厅是萨满祭司的家园，它坐落在灵魂高地上。愿你的先祖保佑你。', `FemaleText_loc5`='靈魂大廳是薩滿的家園，它坐落在靈魂高地上。願你的先祖保佑你。', `FemaleText_loc7`='Nuestros chamanes consideran la Sala de los Espíritus su hogar. Lo encontrarás en el Alto de los Espíritus. Que tus antepasados cuiden de ti.' WHERE `ID`=3456;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리처럼 제대로 된 전사 훈련을 받고 싶으신가요? 사냥꾼의 전당에 있는 사크 레이지토템을 만나면 도움을 받을 수 있을 겁니다.', `MaleText_loc4`='想要加入我们的行列？萨尔克·暴怒图腾可以指引你，他就在猎手大厅里。', `MaleText_loc5`='想要加入我們的行列?薩爾克·狂暴圖騰可以指引你，他就在獵人大廳裡。', `MaleText_loc7`='¿Aspiras a alcanzar nuestro rango algún día? Sark Tótem de Ira puede ayudarte a conseguirlo. Está en la Sala de los Cazadores.', `FemaleText_loc1`='우리처럼 제대로 된 전사 훈련을 받고 싶으신가요? 사냥꾼의 전당에 있는 사크 레이지토템을 만나면 도움을 받을 수 있을 겁니다.', `FemaleText_loc4`='想要加入我们的行列？萨尔克·暴怒图腾可以指引你，他就在猎手大厅里。', `FemaleText_loc5`='想要加入我們的行列?薩爾克·狂暴圖騰可以指引你，他就在獵人大廳裡。', `FemaleText_loc7`='¿Aspiras a alcanzar nuestro rango algún día? Sark Tótem de Ira puede ayudarte a conseguirlo. Está en la Sala de los Cazadores.' WHERE `ID`=3457;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 직업의 상급자를 찾으십니까? 찾으시는 상급자를 알려주시면 지도에 안내해 드리도록 하겠습니다.', `MaleText_loc4`='你要找哪一类型的训练师？', `MaleText_loc5`='你要找哪一類型的訓練師?', `MaleText_loc7`='¿A qué instructor buscas?', `FemaleText_loc1`='어떤 직업의 상급자를 찾으십니까? 찾으시는 상급자를 알려주시면 지도에 안내해 드리도록 하겠습니다.', `FemaleText_loc4`='你要找哪一类型的训练师？', `FemaleText_loc5`='你要找哪一類型的訓練師?', `FemaleText_loc7`='¿A qué instructor buscas?' WHERE `ID`=3458;
