UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 터집니다!', `MaleText_loc4`='%s已经安装完毕！', `MaleText_loc5`='%s已經安裝完畢!', `MaleText_loc7`='%s ya está armada.' WHERE `ID`=3543;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='드라지알 오빠는 저주받은 땅에 서식하는 야생동물들의 육체적 특성을 주로 분석하지만, 저는 지적이고 영적인 면을 더 집중적으로 연구합니다.$B$B그 짐승들이 보기 드물게 강한 힘과 민첩성, 체력을 가진 것은 사실이지만 그중 일부는 육체에 구속되지 않은 높은 지능과 재생 능력도 보유하고 있답니다.$B$B$R|1이여;여;, 혹시 제 연구에 도움을 주실 생각은 없나요?', `FemaleText_loc4`='我的兄弟德拉吉亚专注于研究诅咒之地上的这些野兽的生理特点，而我则倾向于研究它们的精神特点。$B$B那些野兽确实具有相当惊人的力量、敏捷和耐力，而且还拥有惊人的智力和重生能力，这和它们的外表显得不太符合。$B$B$n，你是不是有兴趣来协助我进行研究呢？', `FemaleText_loc5`='我的兄弟德拉吉亞專注於研究詛咒之地上的這些野獸的生理特點，而我則傾向於研究它們的精神特點。$B$B那些野獸確實具有相當驚人的力量、敏捷和耐力，而且還擁有驚人的智力和重生能力，這和它們的外表顯得不太符合。$B$B$r，你是不是有興趣來協助我進行研究呢?', `FemaleText_loc7`='Mientras que mi hermano Drazial concentra sus análisis en la naturaleza física de las bestias de Las Tierras Devastadas, yo me centro más en los aspectos psíquicos y espirituales de la fauna.$B$BCierto es que las bestias demuestran tener una inusual fuerza, agilidad y resistencia pero, algunas de ellas, también poseen una increíble inteligencia y habilidad de regeneración, que no van unidas a su ser físico.$B$B¿Quizás te pueda interesar ayudarme en mi investigación, $r?' WHERE `ID`=3561;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런! 잊을 뻔했군! 내가 살짝 도둑 도구를 당신 가방에 넣어두었소. 당신이 가는 곳에는 그게 필요할 거요.', `MaleText_loc4`='哦！我差点忘记了！我会给你一套盗贼工具。它会对你有很大帮助的。', `MaleText_loc5`='哦!我差點忘記了!我會給你一套盜賊工具。它會對你有很大幫助的。', `MaleText_loc7`='¡Oh! ¡Casi lo olvidaba! Te he apartado un juego de herramientas para ladrones. Las necesitarás cuando te vayas.' WHERE `ID`=3562;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 주사기를 준비합니다.', `MaleText_loc4`='%s准备着注射器。', `MaleText_loc5`='%s準備他的注射器。', `MaleText_loc7`='%s prepara su jeringa.' WHERE `ID`=3563;
