UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 다람쥐와 석상하고 얘기를 나눕니다. 얘기 도중에 간혹 뒤를 돌아보며 이쪽을 가리킵니다.', `MaleText_loc4`='%s好像在对松鼠和石像说话，还不时地向你这个方向指指点点。', `MaleText_loc5`='%s好像在對松鼠和雕像說話，並不時地對你這個方向指指點點。', `MaleText_loc7`='%s parece hablar con la ardilla y la estatua. Periódicamente apunta en tu dirección.' WHERE `ID`=3566;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무데나 /누워 주시오, $n. 절대 아프지 않다니까!', `MaleText_loc4`='$n，随便找个什么地方躺下。我保证你不会受到伤害的！', `MaleText_loc5`='$n，隨便找個什麼地方躺下。我保證你不會受到傷害的!', `MaleText_loc7`='Solo túmbate en cualquier parte, $n. ¡Te prometo que esto no te va a doler nada!' WHERE `ID`=3567;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거 상황이 좋지 않은걸!', `MaleText_loc4`='看上去不太妙！', `MaleText_loc5`='看起來不太妙!', `MaleText_loc7`='¡Esto no tiene buena pinta!' WHERE `ID`=3568;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇게 작은 지역에 그토록 많은 죽음과 절망이 도사리고 있다는 게 상상조차 안 되겠지만, 저 늪에서 한 발짝만 넘어서도 혼돈과 파괴로 물든 땅이 있지.$B$B모험가 친구, 발밑을 조심하시오. 저주받은 땅은 당신보다 훨씬 강한 자들의 마지막 안식처니까 말이오.', `MaleText_loc4`='很难想象如此多的死亡和恐惧会汇集在那么小的一块地区中。在这些门后是一块充斥着混乱和毁灭的大陆。$B$B冒险者，你要非常小心谨慎才行。诅咒之地中到处都是可以让你丧命的强大生物。', `MaleText_loc5`='很難想像如此多的死亡和恐懼會彙集在那麼小的一塊地區中。在這些門後是一塊充斥著混亂和毀滅的大陸。$B$B冒險者，你要非常小心謹慎才行。詛咒之地中到處都是可以讓你喪命的強大生物。', `MaleText_loc7`='Es difícil imaginar tanta muerte y desesperación en una zona tan pequeña; y, aun así, más allá del pantano se extiende una tierra apestada de caos y destrucción.$B$BVe con mucho cuidado, aventurero. Las Tierras Devastadas son el lugar de descanso final de seres muy superiores a ti.' WHERE `ID`=3581;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 여기에 계십니까?', `MaleText_loc4`='你为什么来这里？', `MaleText_loc5`='你為什麼來這裡?', `MaleText_loc7`='¿Qué haces aquí?', `FemaleText_loc1`='왜 여기에 계십니까?', `FemaleText_loc4`='你为什么来这里？', `FemaleText_loc5`='你為什麼來這裡?', `FemaleText_loc7`='¿Qué haces aquí?' WHERE `ID`=3582;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스랄 직속 부대... 사람들은 우리를 이렇게 불렀지. 스랄 님의 병사 중 가장 실력이 뛰어나고 충성스러운 스무 명의 병사로 이뤄진 최정예부대였소.$B$B오그리마에서 명령서가 오기를 기다리는 동안 나는 저주받은 땅의 경계인 이곳에 야영지를 지으라고 지시했소. 몇 주가 지나도록 대족장님에게 아무런 소식이 없어 모두 불안해했지.$B$B나는 벌을 받은 거요, $n. 젊고 의욕에 넘쳤던 나는 아무것도 두려울 게 없었지. 대대를 이끌고 저주받은 땅으로 행군하기로 결정했소.$B$B하지만 후회하게 될 결정이었지.', `MaleText_loc4`='作为萨尔手下最强大的二十名战士，我们被称为萨尔近卫军。$B$B在等待奥格瑞玛的命令时，我要求在诅咒之地边境建立一座营地。但是数星期过去了，酋长那里还是没有任何消息传来，我们开始变得有些焦躁不安了。$B$B$n，那是个错误的决定。我曾经年轻而又雄心勃勃，无所畏惧。这支部队在我的指挥下开进了诅咒之地。$B$B不久之后我就开始后悔了。', `MaleText_loc5`='作為索爾手下最強大的二十名戰士，我們被稱為索爾近衛軍。$B$B在等待奧格瑪的命令時，我要求在詛咒之地邊境建立一座營地。但是數星期過去了，大酋長那裡還是沒有任何消息傳來，我們開始變得有些焦躁不安了。$B$B$n，那是個錯誤的決定。我曾經年輕而又雄心勃勃，無所畏懼。這支部隊在我的指揮下開進了詛咒之地。$B$B不久之後我就開始後悔了。', `MaleText_loc7`='Nos llaman la garra de Thrall: Veinte de los Soldados de Thrall más preparados y honorables. $B$BOrdené al regimiento que construyera un campamento aquí, en la frontera de Las Tierras Devastadas, mientras esperábamos órdenes desde Orgrimmar. Pasaron semanas sin tener noticias del Jefe de Guerra, así que los hombres se impacientaron.$B$BFue una decisión personal, $n. Yo era joven y ambicioso, no tenía miedo de nada. El batallón se adentró en Las Tierras Devastadas bajo mis órdenes.$B$BFue una decisión que lamenté más adelante.' WHERE `ID`=3583;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야기를 계속하십시오.', `MaleText_loc4`='请继续你的故事。', `MaleText_loc5`='請繼續你的故事。', `MaleText_loc7`='Continúa con tu historia.', `FemaleText_loc1`='이야기를 계속하십시오.', `FemaleText_loc4`='请继续你的故事。', `FemaleText_loc5`='請繼續你的故事。', `FemaleText_loc7`='Continúa con tu historia.' WHERE `ID`=3601;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='후회... 그것이 지금 내게 남은 전부요. 잘못된 판단 하나가 끔찍한 결과를 낳고 말았소. 명령서를 기다렸더라면 좋았을 것을. 그랬더라면 저주받은 땅에서 우리를 기다리고 있던 공포에 대해 알 수도 있었을 텐데! 어쩌면 다른 곳으로 파견되었을지도 모르지. 결국 내 잘못이었소. 모든 게 내 잘못이었소.', `MaleText_loc4`='后悔。这就是现在我所能感受到的一切。一个错误的决定导致了如此灾难性的后果。我多么希望当时能多等几天，直到命令传来。也许那样我们就能事先知道这片被诅咒的土地上到底有多少恐怖的东西等着我们！也许这一条命令就能指引我们去另外一个方向！无论怎么样，这都是我的错。所有的一切都是我造成的。', `MaleText_loc5`='後悔。這就是現在我所能感受到的一切。一個錯誤的決定導致了如此災難性的後果。我多麼希望當時能多等幾天，直到命令傳來。也許那樣我們就能事先知道這片被詛咒的土地上到底有多少恐怖的東西等著我們!也許這一條命令就能指引我們去另外一個方向!無論怎麼樣，這都是我的錯。所有的一切都是我造成的。', `MaleText_loc7`='Arrepentimiento. Eso es todo lo que me queda ahora. Una mala decisión que tuvo como resultado unas consecuencias espantosas. Si tan solo hubiera esperado a recibir las órdenes... ¡quizás habría tenido más información sobre los horrores que nos esperaban en esas tierras malditas! ¿O quizás nos iban a redirigir a otro destacamento? En última instancia, todo fue por mi culpa. Soy el único culpable.' WHERE `ID`=3602;
