UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자아아아아아아유우우우우!', `MaleText_loc4`='自~~~~~~由~~~~~~！', `MaleText_loc5`='自～～～～由～～～～!', `MaleText_loc7`='¡LIBERTAAAAAAAAAAAAD!' WHERE `ID`=3641;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 약해졌습니다. 가까이 있는 봉인석이 빛납니다! 지금 공격하십시오!', `MaleText_loc4`='%s的实体形态变得越来越虚幻。你注意到这个仆从身边的禁锢之石开始闪闪发光！赶快攻击它！', `MaleText_loc5`='%s的實體形態變得越來越虛弱。你注意到這個僕從身邊的禁錮之石開始閃閃發光!趕快攻擊它!', `MaleText_loc7`='La forma física de %s se debilita. ¡Notas cómo resplandece la Piedra de Vínculo que está junto a la criatura! ¡Ataca ahora!' WHERE `ID`=3642;
