UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요사이 사막에서 수상한 자를 목격한 적 있습니까?', `MaleText_loc4`='最近在沙漠中有发现什么奇怪的东西吗？', `MaleText_loc5`='最近在沙漠中有發現什麼奇怪的東西嗎?', `MaleText_loc7`='¿Has visto últimamente algo extraño en el desierto?', `FemaleText_loc1`='요사이 사막에서 수상한 자를 목격한 적 있습니까?', `FemaleText_loc4`='最近在沙漠中有发现什么奇怪的东西吗？', `FemaleText_loc5`='最近在沙漠中有發現什麼奇怪的東西嗎?', `FemaleText_loc7`='¿Has visto últimamente algo extraño en el desierto?' WHERE `ID`=3662;
