UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그의 잘못이 아니었소. 그에게 전하시오...', `MaleText_loc4`='告诉他，这不是他的错……', `MaleText_loc5`='告訴他，這不是他的錯...', `MaleText_loc7`='No fue culpa suya. Dile que...' WHERE `ID`=3684;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 이 저주받은 구속에서 풀려났습니다. 아버지, 제가 갑니다...', `MaleText_loc4`='终于从他的诅咒中解脱出来了。父亲，我来了……', `MaleText_loc5`='終於從他的詛咒中解脫出來了。父親，我來了...', `MaleText_loc7`='¡Por fin libre de este maldito encierro! Padre, allá voy...' WHERE `ID`=3685;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='녀석들을 잡아와라, 어여쁜 것들아... 녀석들의 조그만 애완동물까지도 모조리 잡아와!', `MaleText_loc4`='干掉他们……还有他们的走狗！', `MaleText_loc5`='幹掉他們...還有他們的走狗!', `MaleText_loc7`='¡A por ellos, mis niños... y a por sus pequeños perros también!!' WHERE `ID`=3686;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흥! 이제 내 애완동물이 널 먹는다!', `MaleText_loc4`='哈！我的宠物要吃了你！', `MaleText_loc5`='哈!我的寵物要吃了你!', `MaleText_loc7`='¡Bah! ¡Ahora mascota comerte!' WHERE `ID`=3687;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 내가 직접 너를 뭉개주마!', `MaleText_loc4`='现在我要亲自解决你！', `MaleText_loc5`='現在我要親自解決你!', `MaleText_loc7`='¡Ahora yo solito aplastarte!' WHERE `ID`=3688;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혼돈의 불길이 너를 집어삼킬 것이다!', `MaleText_loc4`='让混沌之火将你吞噬吧！', `MaleText_loc5`='讓混沌之火將你吞噬吧!', `MaleText_loc7`='¡Que las llamas del caos te devoren!' WHERE `ID`=3689;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 알겠습니다!', `MaleText_loc4`='是，长官！', `MaleText_loc5`='是，長官!', `MaleText_loc7`='¡Sí, señor!', `FemaleText_loc1`='네, 알겠습니다!', `FemaleText_loc4`='是，长官！', `FemaleText_loc5`='是，長官!', `FemaleText_loc7`='¡Sí, señor!' WHERE `ID`=3690;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일리파르! 네 주인이 부르는 소리가 들리지 않으냐!', `MaleText_loc4`='伊利法尔，你的主人在召唤你！', `MaleText_loc5`='伊利法爾，你的主人在召喚你!', `MaleText_loc7`='¡Ilifar, tu maestro te llama!' WHERE `ID`=3691;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나의 전사와 맞서보아라, 하찮은 $R!', `MaleText_loc4`='面对我的勇士吧，凡人！', `MaleText_loc5`='面對我的勇士吧，凡人!', `MaleText_loc7`='¡Enfrentaos a mi campeón, mortales!' WHERE `ID`=3692;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영원한 고통을 맛보게 해주마. 복수는 나의 것이니...', `MaleText_loc4`='准备坠入无限的痛苦深渊吧……我要复仇……', `MaleText_loc5`='準備墜入無限的痛苦深淵吧...我要復仇...', `MaleText_loc7`='Preparaos por una eternidad de angustia y tortura... la venganza será mía...' WHERE `ID`=3693;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 생애에서 절정을 달리던 시기에 실패를 했다면 믿으시겠소? 그때가 내 평생 가장 눈부셨던 동시에 어두웠던 때라오.$B$B우리를 무자비하게 침략했던 세력으로부터 도망쳐 나올 때 내 귀에는 우리 병사들의 참혹한 비명 소리와 세차게 뛰는 내 심장의 빠른 고동소리만 들렸소.$B$B얼마 후 부하들을 구하고 명예를 회복하겠다는 기대를 안고 저주받은 땅으로 되돌아왔소. 하지만 붙잡혀서 구타당하다 죽고 말았지.$B$B그때 고문을 받으면서 알게 된 사실은 정말이지 끔찍했소.', `MaleText_loc4`='你能相信作为精英战士的我居然失败了吗？$B$B我们的部队被无法抗拒的力量彻底摧毁，我所记得的一切就是不顾一切地逃跑，我所听到的一切只有我的战友撕心裂肺的惨叫和我自己的心跳。$B$B过了不久，我又回到了诅咒之地，希望能拯救我的伙伴。但是我被抓住了，最后被活活打死。$B$B这段日子中，我所能感受到的只有恐惧。', `MaleText_loc5`='你能相信作為精英戰士的我居然失敗了嗎?$B$B我們的部隊被無法抗拒的力量徹底摧毀，我所記得的一切就是不顧一切地逃跑，我所聽到的一切只有我的戰友撕心裂肺的慘叫和我自己的心跳。$B$B過了不久，我又回到了詛咒之地，希望能拯救我的夥伴。但是我被抓住了，最後被活活打死。$B$B這段日子中，我所能感受到的只有恐懼。', `MaleText_loc7`='¿Podrás creer que fallé en mi hora más oscura, en la cúspide de mi vida?$B$BCuando huí de la destrucción fortuita de las fuerzas que nos aplastaron, los únicos sonidos que escuché fueron los gritos de mis soldados y los rápidos latidos de mi corazón.$B$BPoco tiempo después, regresé a Las Tierras Devastadas con la esperanza de rescatar a mis hombres y recuperar mi honor. Por el contrario, me capturaron y me hirieron hasta morir.$B$BLo que descubrí durante mi interrogatorio y posterior tortura fue horripilante.' WHERE `ID`=3701;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드 영웅이시여, 계속 말씀하시죠.', `MaleText_loc4`='请继续，英雄……', `MaleText_loc5`='請繼續，英雄...', `MaleText_loc7`='Héroe, continúa, por favor...', `FemaleText_loc1`='호드 영웅이시여, 계속 말씀하시죠.', `FemaleText_loc4`='请继续，英雄……', `FemaleText_loc5`='請繼續，英雄...', `FemaleText_loc7`='Héroe, continúa, por favor...' WHERE `ID`=3702;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나를 붙잡은 녀석들은 차마 말로는 표현하지 못할 정도로 잔인했소. 부관 키리스와 나를 번갈아 고문하면서 괴로워하는 모습을 서로 강제로 지켜보게 하였소. 유독 고문이 심했던 어느 날인가 키리스는 잠잠한 틈을 타 우리 부하들에게 벌어진 끔찍한 사건과 그들을 해방시키기 위해 그가 세운 계획을 말해주었소.$B$B나의 부하들은 키리스와 내가 겪었던 고통보다, 아니 죽음보다도 더 끔찍한 운명에 괴로워했더군...', `MaleText_loc4`='我被抓之后遭受了非人的虐待，$n。他们轮番拷打我和基利斯中尉，而且在虐待一方的同时让另外一个在旁边看着。我们不断被折磨，直到有一天基利斯把战友们的遭遇告诉了我，还有他的拯救计划。$B$B他们所遭受的痛苦比我和基利斯所遭受的还要多，他们真的是生不如死。', `MaleText_loc5`='我被抓之後遭受了非人的虐待，$n。他們輪番拷打我和基利斯中尉，而且在虐待一方的同時讓另外一個在旁邊看著。我們不斷被折磨，直到有一天基利斯告訴把戰友們的遭遇告訴了我，還有他的拯救計畫。$B$B他們所遭受的痛苦比我和基利斯所遭受的還要多，他們真的是生不如死。', `MaleText_loc7`='Mis captores fueron de una crueldad imposible imaginar, $n. Nos alternaban al teniente Kirith y a mí, torturando a uno mientras el otro miraba. En un momento de calma tras un día brutal, Kirith me contó lo que les había ocurrido a mis hombres y el plan que había ideado para liberarlos de sus maestros.$B$BSu destino fue mucho peor que la muerte, o incluso peor que el martirio que Kirith y yo padecimos.' WHERE `ID`=3703;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음보다 끔찍하다면 어떤 것을 말하는지요?', `MaleText_loc4`='有什么比死亡还要痛苦？', `MaleText_loc5`='有什麼比死亡還要痛苦?', `MaleText_loc7`='¿Qué puede ser peor que la muerte?', `FemaleText_loc1`='죽음보다 끔찍하다면 어떤 것을 말하는지요?', `FemaleText_loc4`='有什么比死亡还要痛苦？', `FemaleText_loc5`='有什麼比死亡還要痛苦?', `FemaleText_loc7`='¿Qué puede ser peor que la muerte?' WHERE `ID`=3704;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이나 나나 영혼이 육체에서 억지로 찢겨나갈 때의 고통은 상상도 할 수 없을 거요. 우리 병사들은 완전히 죽은 것도, 살아있는 것도 아닌 상태... 그 상태로 이 세계에 그들을 묶어둔 자들의 노예로 살아가야 했던 거요.$B$B바로 이 땅을 지배하는 악마 군주 라젤리크의 노예가 돼버린 것이오. 라젤리크는 그중 아홉 명을 어둠의 문 근처 봉인석에 배치하고 있소. 그리고 나머지 아홉은 자기 부하들에게 나눠주었소.', `MaleText_loc4`='你和我都无法想象当他们的灵魂被强行从躯体中剥离出来的时候有多么痛苦。他们没有死，但是他们也不是活着的。他们成为了一具具行尸，只会听从主人发号施令。$B$B干出这些惨绝人寰的事情的就是这里的恶魔首领拉瑟莱克，他把我的战友都变成了奴隶。其中的九个被他绑定在黑暗之门附近，其余的九个则被他的爪牙们瓜分。', `MaleText_loc5`='你和我都無法想像當他們的靈魂被強行從軀體中剝離出來的時候有多麼痛苦。他們沒有死，但是他們也不是活著的。他們成為了一具具行屍，只會聽從主人發號施令。$B$B幹出這些慘絕人寰的事情的就是這裡的惡魔領主拉瑟萊克，他把我的戰友都變成了奴隸。其中的九個被他綁定在黑暗之門附近，其餘的九個則被他的爪牙們瓜分。', `MaleText_loc7`='Ni tú ni yo podríamos habernos imaginado el dolor atroz que se siente cuando te arrancan el alma del cuerpo. No están muertos, pero tampoco están vivos. Vagan por la tierra, siervos de aquellos que les tienen atados a este mundo.$B$BLord Razelikh, señor supremo demoníaco de estas tierras, los ha esclavizado a todos. Se quedó con nueve y colocó Piedras de Vínculo cerca del Portal Oscuro. Los otros nueve fueron repartidos entre sus subordinados.' WHERE `ID`=3705;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악마 군주의 부하들에게요?', `MaleText_loc4`='手下？', `MaleText_loc5`='手下?', `MaleText_loc7`='¿Subordinados?', `FemaleText_loc1`='악마 군주의 부하들에게요?', `FemaleText_loc4`='手下？', `FemaleText_loc5`='手下?', `FemaleText_loc7`='¿Subordinados?' WHERE `ID`=3706;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠혈맹 대마법사 알리스타즈에게 세 명, 어둠혈맹 흑마법사인 여군주 세바인에게 세 명, 그리고 이 저주받은 땅의 우레망치 오우거를 다스리는 파괴자 그롤에게 나머지 세 명을 주었소.$B$B당신도 이미 알고 있겠지만, 영혼이 없는 육체는 죽일 수 없소. 이제 내 부하들은 불로불사의 전투 부대가 되어 악의 명령에 따르고 있소. 그나마 다행인 것은 봉인석으로 이동할 수 있는 거리 내에서만 움직일 수 있다는 거요.', `MaleText_loc4`='大法师奥利斯塔，术士瑟温妮，还有食人魔戈洛尔，他们各自分配到了三个。$B$B$n，你要知道，如果没有灵魂，我的战友是无法被杀死的。他们现在都处于一种无敌的状态。幸好的是，他们不能离开禁锢之石太远的距离。', `MaleText_loc5`='影誓大法師奧利斯塔、影誓術士瑟溫妮女士、還有巨槌部落的巨魔『毀滅者』戈洛爾，他們各自分配到了三個。$B$B$n，你要知道，如果沒有靈魂，我的戰友是無法被殺死的。他們現在都處於一種無敵的狀態。幸好的是，他們不能離開禁錮之石太遠的距離。', `MaleText_loc7`='El archimago Allistarj de los Sombra Jurada tenía tres. Lady Sevine, bruja de los Sombra Jurada, también tenía asignados a tres. Los tres restantes fueron asignados a Grol el Destructor, señor de los ogros Machacamiedo de estas tierras malditas.$B$BSabes, $n, no se puede matar al cuerpo si no tiene alma. Los restos de mis hombres son ahora indestructibles unidades de lucha. Afortunadamente, la distancia que pueden recorrer está limitada por las Piedras de Vínculo.' WHERE `ID`=3707;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='봉인석이란 무엇입니까?', `MaleText_loc4`='禁锢之石是什么？', `MaleText_loc5`='禁錮之石是什麼?', `MaleText_loc7`='¿Qué son las Piedras de Vínculo?', `FemaleText_loc1`='봉인석이란 무엇입니까?', `FemaleText_loc4`='禁锢之石是什么？', `FemaleText_loc5`='禁錮之石是什麼?', `FemaleText_loc7`='¿Qué son las Piedras de Vínculo?' WHERE `ID`=3708;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 그 봉인석을 파괴해야 우리 부하들을 해방킬 수 있소! 아까도 말했지만 키리스에게는 계획이 있었소.$B$B라젤리크의 하수인에겐 모두 약점이 있소. 봉인석 근처에 있는 육신을 계속 공격하면 하수인들이 분열 상태에 가까워진다오. 바로 그때 봉인석을 공격해야 하오. 하수인들이 다시 깨어나면 아무리 공격해도 소용이 없으니 서둘러서 봉인석을 파괴해야 하오.', `MaleText_loc4`='那些禁锢之石就是你要去摧毁的东西！正如我刚刚所说的，基利斯有一个完整的计划。$B$B每个被奴役的战士都有一个弱点，你必须尽量攻击他们，直到他们的实体形态几近瓦解。这时禁锢之石就会变得非常脆弱。你一定要抓紧时间摧毁禁锢之石，否则不久之后，那些奴隶又将获得新的力量，并再次变得刀枪不入了。', `MaleText_loc5`='那些禁錮之石就是你要去摧毀的東西!正如我剛剛所說的，基利斯有一個完整的計畫。$B$B每個被奴役的戰士都有一個弱點，你必須盡量攻擊他們，直到他們的實體形態幾近瓦解。這時禁錮之石就會變得非常脆弱。你一定要抓緊時間摧毀禁錮之石，否則不久之後，那些奴隸又將獲得新的力量，並再次變得刀槍不入了。', `MaleText_loc7`='¡Son exactamente lo que tienes que destruir para liberar al regimiento! Como te dije anteriormente, Kirith tenía un plan.$B$BCada uno de los sirvientes tiene una debilidad. Es preciso atacar su parte física cerca las piedras hasta que alcancen un nivel próximo a la desintegración. En ese punto, y solo en ese punto, en el que las Piedras de Vínculo resultan vulnerables al ataque. No obstante, tienes que darte prisa en destruir las piedras, ya que una vez que los esclavos recuperen su estado original, volverán a ser invulnerables a cualquier tipo de daño.' WHERE `ID`=3709;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드 영웅이시여, 절 믿으십시오.', `MaleText_loc4`='英雄，你可以信赖我。', `MaleText_loc5`='英雄，你可以信賴我。', `MaleText_loc7`='Puedes contar conmigo, héroe.', `FemaleText_loc1`='호드 영웅이시여, 절 믿으십시오.', `FemaleText_loc4`='英雄，你可以信赖我。', `FemaleText_loc5`='英雄，你可以信賴我。', `FemaleText_loc7`='Puedes contar conmigo, héroe.' WHERE `ID`=3710;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말로 당신 혼자서 해낼 수 있다면 얼마나 좋겠소. 하지만 혼자 힘으로 라젤리크와 그 부하들을 상대한다는 것은 무리요.$B$B영웅이 되고자 모험을 하는 이들을 모아 우리 부하들을 끝이 없는 고통에서 해방시켜 주시오! 모두 18개의 돌을 부수어야만 하오.$B$B용맹스럽게 싸우다 명예롭게 죽으시오.', `MaleText_loc4`='我想你真的可以帮我，$n，但是单凭你的力量是无法和拉瑟莱克以及他的爪牙抗衡的。$B$B你一定要找到一支足够强大的队伍来解救我的战友，让他们脱离无尽的痛苦！你总共要摧毁十八块石头。$B$B努力地去战斗吧，$n。', `MaleText_loc5`='我想你真的可以幫我，$n，但是單憑你的力量是無法和拉瑟萊克以及他的爪牙抗衡的。$B$B你一定要找到一支足夠強大的隊伍來解救我的戰友，讓他們脫離無盡的痛苦!你總共要摧毀十八塊石頭。$B$B努力地去戰鬥吧，$n。', `MaleText_loc7`='Me gustaría creer que es cierto, $n, pero tú solo no serás suficiente para combatir a Razelikh y a sus subordinados.$B$B¡Reúne un buen grupo de aventureros dispuestos a dejarse la piel y libera a mis hombres de su eterna tortura! Tienes que romper en pedazos dieciocho piedras.$B$BLucha a muerte y muere con honor, $n.' WHERE `ID`=3711;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='먼저 내 얘기부터 들어보시오, $n. 훗날 아주 큰 도움이 될 거요.', `MaleText_loc4`='在我们继续之前，你必须先听一下我的故事，$n。这会对你很有帮助。', `MaleText_loc5`='在我們繼續之前，你必須先聽一下我的故事，$n。這會對你很有幫助。', `MaleText_loc7`='Tienes que oír mi historia antes de que sigamos, $n. Te resultará muy útil en el futuro.' WHERE `ID`=3712;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 최후의 일격으로 희생자에게 독침을 쏘려고 합니다!', `MaleText_loc4`='%s准备拼尽全力刺它的敌人！', `MaleText_loc5`='%s準備用刺對牠的敵人作捨命的最後一擊!', `MaleText_loc7`='¡%s se prepara para torturar a su víctima como último recurso!' WHERE `ID`=3713;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 경비병들이 보이지 않을 때까지 기다립니다.', `MaleText_loc4`='%s等待卫兵消失在视野中。', `MaleText_loc5`='%s等待守衛消失在視野之外。', `MaleText_loc7`='%s espera hasta perder de vista a los guardias.' WHERE `ID`=3721;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 서쪽을 가리킵니다.', `MaleText_loc4`='%s指了指西方。', `MaleText_loc5`='%s指向西方。', `MaleText_loc7`='%s apunto al oeste.' WHERE `ID`=3741;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연금술 재료가 필요하시군요? 아니면 다른 볼일로 오셨나요?', `MaleText_loc4`='需要一些炼金术的材料吗？或者你有别的什么事情？', `MaleText_loc5`='需要一些鍊金術的材料嗎?或者你有別的什麼事情?', `MaleText_loc7`='¿Necesitas suministros de alquimia? ¿O quieres tratar otros asuntos conmigo?' WHERE `ID`=3742;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원반이 완성되었습니다! 원반을 받으려면 노르간논의 원반을 한 번 더 조작하십시오!', `MaleText_loc4`='你已经得到圆盘了！再次插入诺甘农圆盘来获取资料！', `MaleText_loc5`='你已經得到圓盤了!再次插入諾甘農圓盤來獲取資料!', `MaleText_loc7`='¡Tus discos ya están preparados! Vuelve a engranar los Discos de Norgannon para recuperarlos!' WHERE `ID`=3743;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런! 젠장, 놈들이 온다!', `MaleText_loc4`='啊，注意！', `MaleText_loc5`='啊，注意!', `MaleText_loc7`='¡Oh, no! ¡Aquí vienen!' WHERE `ID`=3744;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 전진!', `MaleText_loc4`='前进！', `MaleText_loc5`='前進!', `MaleText_loc7`='¡Venga, en marcha!' WHERE `ID`=3745;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='첩보로봇이 녀석을 나오게 할 테니까 여기서 기다리라고, $n. 단단히 준비하라고! 그들의 대화를 엿들은 후에 공격해야 해!', `MaleText_loc4`='$n，等在这里。间谍机器人会尽快让他们出来的。准备好！在听完他们的对话之后再发起攻击。', `MaleText_loc5`='$n，在這裡等著。間諜機器人會儘快讓他們出來的。準備好!在聽完他們的對話之後再發起攻擊。', `MaleText_loc7`='Espera aquí, $n. El robot espía hará salir a Lescovar lo antes posible. ¡Prepárate! Ataca solo después de escuchar su conversación.', `FemaleText_loc1`='첩보로봇이 녀석을 나오게 할 테니까 여기서 기다리라고, $n. 단단히 준비하라고! 그들의 대화를 엿들은 후에 공격해야 해!', `FemaleText_loc4`='$n，等在这里。间谍机器人会尽快让他们出来的。准备好！在听完他们的对话之后再发起攻击。', `FemaleText_loc5`='$n，在這裡等著。間諜機器人會儘快讓他們出來的。準備好!在聽完他們的對話之後再發起攻擊。', `FemaleText_loc7`='Espera aquí, $n. El robot espía hará salir a Lescovar lo antes posible. ¡Prepárate! Ataca solo después de escuchar su conversación.' WHERE `ID`=3761;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라스코발 경. 경을 만나기 위해 손님이 기다리고 계십니다.', `MaleText_loc4`='大人，您的客人到了。他正在等你。', `MaleText_loc5`='大人，您的客人到了。他正在等你。', `MaleText_loc7`='Señor, el invitado ha llegado. Te está esperando.', `FemaleText_loc1`='라스코발 경. 경을 만나기 위해 손님이 기다리고 계십니다.', `FemaleText_loc4`='大人，您的客人到了。他正在等你。', `FemaleText_loc5`='大人，您的客人到了。他正在等你。', `FemaleText_loc7`='Señor, su invitado ha llegado. Le está esperando.' WHERE `ID`=3762;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드 영웅이시여, 전 하사관 선드 스플릿후프에게 급한 용무가 있습니다.', `MaleText_loc4`='英雄，我有紧急的事情要和桑德·裂蹄商讨。', `MaleText_loc5`='英雄，我有緊急的事情要和裂蹄下士商量。', `MaleText_loc7`='Héroe, tengo que discutir ciertas cosas urgentemente con el cabo Pezuña Quebrada.', `FemaleText_loc1`='호드 영웅이시여, 전 하사관 선드 스플릿후프에게 급한 용무가 있습니다.', `FemaleText_loc4`='英雄，我有紧急的事情要和桑德·裂蹄商讨。', `FemaleText_loc5`='英雄，我有緊急的事情要和裂蹄下士商量。', `FemaleText_loc7`='Héroe, tengo que discutir ciertas cosas urgentemente con el cabo Pezuña Quebrada.' WHERE `ID`=3763;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 요청대로 하사관 선드 스플릿후프가 도착했소, $n.', `MaleText_loc4`='$n，桑德·裂蹄已经来了。', `MaleText_loc5`='應你要求，$n，裂蹄下士已經來了。', `MaleText_loc7`='Conforme a tu petición, ha llegado el cabo Pezuña Quebrada, $n.' WHERE `ID`=3764;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두 분 수고하십니다. 전 라스코발 경을 만나 뵈려고 왔습니다.', `MaleText_loc4`='你们好。我要找莱斯科瓦公爵谈谈。', `MaleText_loc5`='你們好。我要找萊斯科瓦大人談談。', `MaleText_loc7`='Que tengáis los dos un buen día. Me gustaría hablar con el señor Lescovar.', `FemaleText_loc1`='두 분 수고하십니다. 전 라스코발 경을 만나 뵈려고 왔습니다.', `FemaleText_loc4`='你们好。我要找莱斯科瓦公爵谈谈。', `FemaleText_loc5`='你們好。我要找萊斯科瓦大人談談。', `FemaleText_loc7`='Que tengáis los dos un buen día. Me gustaría hablar con el señor Lescovar.' WHERE `ID`=3781;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다. 빛의 영광이 함께하시길.', `MaleText_loc4`='谢谢，愿圣光与你们同在。', `MaleText_loc5`='謝謝，願聖光與你們同在。', `MaleText_loc7`='Gracias. Que la Luz os acompañe a los dos.', `FemaleText_loc1`='감사합니다. 빛의 영광이 함께하시길.', `FemaleText_loc4`='谢谢，愿圣光与你们同在。', `FemaleText_loc5`='謝謝，願聖光與你們同在。', `FemaleText_loc7`='Gracias. Que la Luz os acompañe a los dos.' WHERE `ID`=3782;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 들어가십시오. 경께서는 도서관에 기다리고 계십니다.', `MaleText_loc4`='当然，他在图书馆等您。', `MaleText_loc5`='當然，他在圖書館等您。', `MaleText_loc7`='Claro. Él te espera en la biblioteca.', `FemaleText_loc1`='어서 들어가십시오. 경께서는 도서관에 기다리고 계십니다.', `FemaleText_loc4`='当然，他在图书馆等您。', `FemaleText_loc5`='當然，他在圖書館等您。', `FemaleText_loc7`='Claro. Él te espera en la biblioteca.' WHERE `ID`=3783;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 친절에 감사드리오. 내가 잠시 볼 일을 볼 동안 도서관에서 기다려 주시겠소?', `MaleText_loc4`='啊，非常感谢。当我料理好这件小事之后就去图书馆。', `MaleText_loc5`='啊，非常感謝。當我料理好這件小事之後就去圖書館。', `MaleText_loc7`='Ah, muchas gracias. Te acompaño hasta la biblioteca mientras me ocupo de este asuntillo.' WHERE `ID`=3784;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 그럼 시작해볼까?', `MaleText_loc4`='好了，我这就去！', `MaleText_loc5`='好了，我這就去!', `MaleText_loc7`='¡Vale, allá voy!' WHERE `ID`=3785;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 여기 있다는 사실만으로도 당장 폭발할 것 같으니까 내 눈앞에서 썩 꺼져.', `MaleText_loc4`='滚远点，渺小的$r。我看见你就烦。', `MaleText_loc5`='滾遠點，渺小的$r。我看見你就煩。', `MaleText_loc7`='Sal de mi vista, mortal. Tu sola presencia es suficiente para desatar mi ira.' WHERE `ID`=3786;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='린지는 자유다!', `MaleText_loc4`='林吉自由了！', `MaleText_loc5`='林吉自由了!', `MaleText_loc7`='¡Rin''ji es libre!' WHERE `ID`=3787;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칠흑의 어둠을 틈타...', `MaleText_loc4`='在夜色的掩护下。', `MaleText_loc5`='在夜色的掩護下。', `MaleText_loc7`='En la protección de la oscuridad.', `FemaleText_loc1`='칠흑의 어둠을 틈타...', `FemaleText_loc4`='在夜色的掩护下。', `FemaleText_loc5`='在夜色的掩護下。', `FemaleText_loc7`='En la protección de la oscuridad.' WHERE `ID`=3788;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음의 날개를 타고 날리라.', `MaleText_loc4`='我骑乘着死亡的双翼。', `MaleText_loc5`='我騎乘著死亡的雙翼。', `MaleText_loc7`='Cabalgaré sobre las alas de la muerte.' WHERE `ID`=3789;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 이제 길이 보이는군. 여기서부턴 집으로 가는 길을 알고 있소.', `MaleText_loc4`='林吉现在可以看到路了，$n。林吉认识回家的路。', `MaleText_loc5`='林吉現在可以看到路了，$n。林吉認識回家的路。', `MaleText_loc7`='Rin''ji puede ver el camino ahora, $n. Rin''ji conoce el camino a casa.' WHERE `ID`=3790;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번 기회에 소양에 힘쓰도록 하겠습니다, 라스코발 경. 감사합니다.', `MaleText_loc4`='阁下，我会善用时间的。谢谢您。', `MaleText_loc5`='閣下，我會善用時間的。謝謝您。', `MaleText_loc7`='Emplearé el tiempo sabiamente, señor. Gracias.', `FemaleText_loc1`='이번 기회에 소양에 힘쓰도록 하겠습니다, 라스코발 경. 감사합니다.', `FemaleText_loc4`='阁下，我会善用时间的。谢谢您。', `FemaleText_loc5`='閣下，我會善用時間的。謝謝您。', `FemaleText_loc7`='Emplearé el tiempo sabiamente, señor. Gracias.' WHERE `ID`=3791;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사막에서 산다는 것은 참 고된 일이야! 이런 찌는 듯한 날씨에 횃불까지 들고 서 있으려니 정말 덥고 목이 마르는군.', `MaleText_loc4`='这沙漠可真不是人呆的地方！在这种高温下还得站在外面，我都快渴死啦！', `MaleText_loc5`='在這片沙漠中生活可是很艱辛!在這種熱度之下我口渴得要命。', `MaleText_loc7`='¡Es duro vivir aquí en el desierto! Me entra tanta sed con tanto calor.' WHERE `ID`=3792;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 굉장한 노겐포저의 비약이 좀 더 필요합니다!', `MaleText_loc4`='嗯！我还想买一些诺格弗格药剂！', `MaleText_loc5`='嗯!我還想買一些諾格弗格藥劑!', `MaleText_loc7`='¡Sí! ¡Quiero más de ese fantástico elixir de Tragonublo!', `FemaleText_loc1`='그 굉장한 노겐포저의 비약이 좀 더 필요합니다!', `FemaleText_loc4`='嗯！我还想买一些诺格弗格药剂！', `FemaleText_loc5`='嗯!我還想買一些諾格弗格藥劑!', `FemaleText_loc7`='¡Sí! ¡Quiero más de ese fantástico elixir de Tragonublo!' WHERE `ID`=3793;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비상 동력 가동 완료! 이동식 발동기 초기화 중! 꼬꼬댁!', `MaleText_loc4`='备用动力启动！启动流动电机！咯咯嗒！', `MaleText_loc5`='備用動力啟動!啟動流動電機!咯咯嗒!', `MaleText_loc7`='¡Alimentación de emergencia activada! ¡Inicializando motor ambulatorio! ¡CLUC!' WHERE `ID`=3794;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물리적 위험 감지! 경로 이동 실시! 꼬꼬댁!', `MaleText_loc4`='侦测到威胁！实施躲避动作！咯咯嗒！', `MaleText_loc5`='偵測到威脅!執行閃避動作!咯咯嗒!', `MaleText_loc7`='¡Amenaza física detectada! ¡Acción evasiva! ¡CLUC!' WHERE `ID`=3795;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위험 분석 완료! 전투 계획 베타 시동 중! 꼬꼬댁!', `MaleText_loc4`='威胁分析！启动二号战斗计划！咯咯嗒！', `MaleText_loc5`='威脅分析!啟動戰鬥計畫B!咯咯嗒!', `MaleText_loc7`='¡Amenaza analizada! ¡Activando plan beta de combate! ¡CLUC!' WHERE `ID`=3796;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꼬꼬댁! 공간 형태 이상 감지 -- 위험 임박! 꼬꼬댁!', `MaleText_loc4`='咯咯嗒！探测到空间异常——危险临近！咯咯嗒！', `MaleText_loc5`='咯咯嗒!探測到空間異常─危險臨近!咯咯嗒!', `MaleText_loc7`='¡CLUC! ¡Los sensores detectan una anomalía espacial - peligro inminente! ¡CLUC!' WHERE `ID`=3797;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 주목! 오모쉬의 환상적인 춤솜씨를 감상하라고!', `MaleText_loc4`='停止！沃姆什来了！', `MaleText_loc5`='停止!沃姆什來了!', `MaleText_loc7`='¡Alto! ¡Es la hora de Omosh!' WHERE `ID`=3798;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어린 친구, 저 바보 같은 늙은이 얘긴 듣지 말라고. 누구에게든 늘 저러니까. 그런데 자네는 진짜 재주가 있어 보이는군. 잠시 나랑 얘기나 나누세.', `MaleText_loc4`='不要听那个傻瓜的话，孩子。他对所有人都这样。我一直都在观察你，你是一个真正的天才。过来和我谈谈。', `MaleText_loc5`='不要聽那個傻瓜的話，孩子。他對所有人都這樣。我一直都在觀察你，你是一個真正的天才。過來和我談談。', `MaleText_loc7`='No escuches a ese viejo idiota, $gniño:niña;. Es así con todo el mundo. Pero te he estado observando y tienes auténtico talento. Ven a hablar conmigo.' WHERE `ID`=3799;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와줘!$B$B날 여기서 빠져나가게 해주면 줄파락의 두목이 있는 곳으로 통하는 문을 폭파해 버릴 수 있다고!', `MaleText_loc4`='救命！$B$B如果你能帮我离开这里，我就帮你炸开通向祖尔法拉克酋长所在地的那扇门！', `MaleText_loc5`='救命!$B$B如果你能幫我離開這裡，我就幫你炸開通向祖爾法拉克酋長所在地的那扇門!', `MaleText_loc7`='¡Socorro!$B$B¡Si me sacas de aquí puedo volar la puerta que conduce al jefe de Zul''Farrak!' WHERE `ID`=3801;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='Zul''Farrak - Weegli Blastfuse - Greeting default.', `MaleText_loc4`='Zul''Farrak——Weegli Blastfuse——默认问候语。', `MaleText_loc5`='祖爾法拉克─維格利─原始設定問候語。', `MaleText_loc7`='Zul''Farrak - Weegli Plomofundido - saludo habitual.' WHERE `ID`=3802;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='트롤을 더 많이 처치해야 해! 충분히 처치하면 트롤 두목에게로 통하는 문을 폭파해 주겠어!', `MaleText_loc4`='我们要杀掉更多的巨魔！杀了足够的巨魔，我就炸开巨魔酋长的门！', `MaleText_loc5`='我們要殺掉更多的食人妖!殺了足夠的食人妖，我就炸開食人妖酋長的門!', `MaleText_loc7`='¡Tenemos que matar más trols! ¡Mata los suficientes y derribaré la puerta para encontrar al jefe de los trols!' WHERE `ID`=3803;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고마워, $n. 자네가 나타나지 않았더라면 난 분명 이미 죽은 목숨이었을 거야! 이제 우리 앞에 있는 저 문만 날려 버리면 트롤 두목이 기다리고 있을 거라고...', `MaleText_loc4`='谢谢你，$n。你出现的真是时候，我差一点就死于非命了！现在我们只差打破这扇门就能面对巨魔酋长了……', `MaleText_loc5`='謝謝你，$n。你出現的真是時候，我差一點就死於非命了!現在我們只差打破這扇門就能面對食人妖酋長了...', `MaleText_loc7`='Gracias, $n. Si no hubieras aparecido, ¡estoy seguro de que habríamos acabado muertos! Ahora lo único que hay entre nosotros y el jefe trol es esa puerta de allí...' WHERE `ID`=3804;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 문을 지금 폭파해 주겠어요?', `MaleText_loc4`='你现在可以炸开那扇门了吗？', `MaleText_loc5`='你現在可以炸開那扇門了嗎?', `MaleText_loc7`='¿Vas a derribar esa puerta ahora?', `FemaleText_loc1`='저 문을 지금 폭파해 주겠어요?', `FemaleText_loc4`='你现在可以炸开那扇门了吗？', `FemaleText_loc5`='你現在可以炸開那扇門了嗎?', `FemaleText_loc7`='¿Vas a derribar esa puerta ahora?' WHERE `ID`=3805;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와주시오! 나는 일행과 함께 트롤들에게 붙잡혔소. 놈들은 우리를 희생 제물로 바치려 하고 있소!$B$B여기서 빠져나가게 해주면 당신이 원하는 것은 뭐든지 해주겠소.', `MaleText_loc4`='救命啊！我的队伍被巨魔俘虏了，他们准备杀了我们！$B$B只要你能救我们出去，我会答应你的任何条件！', `MaleText_loc5`='救命啊!我的隊伍被食人妖俘虜了，他們準備殺了我們!$B$B只要你能救我們出去，我會答應你的任何條件!', `MaleText_loc7`='¡Socorro! ¡Mis hombres y yo hemos sido capturados por trols y nos van a sacrificar!$B$BSácanos de aquí y te daré lo que quieras.' WHERE `ID`=3806;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='떠들고 있을 시간이 없소! 저 트롤 녀석들을 처치해야 탈출할 수 있단 말이오.', `MaleText_loc4`='没有时间聊天了！我们必须马上想办法对付那些巨魔！', `MaleText_loc5`='沒有時間聊天了!我們必須馬上想辦法對付那些食人妖!', `MaleText_loc7`='¡No tenemos tiempo de hablar! ¡Tenemos que pensar en esos trols!' WHERE `ID`=3807;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙소, $n. 당신 없이는 빠져나오지 못했을 거요. 아, 전에 구해주면 보답을 하겠다고 했던가? 뭐... 그런 건 없었던 일로 하죠!', `MaleText_loc4`='$n，非常感谢你。没有你，我们绝对没办法逃离魔爪。哦，如果我刚才说过要报答你之类的话……忘掉它吧！', `MaleText_loc5`='$n，非常感謝你。沒有你，我們絕對沒辦法逃離魔爪。哦，如果我剛才說過要報答你之類的話...忘掉它吧!', `MaleText_loc7`='Muchas gracias, $n. No podríamos haberlo hecho sin tu ayuda. Oh, y si antes dije algo sobre una recompensa por salvarnos, bien... ¡puedes olvidarlo!' WHERE `ID`=3808;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 블라이! 빌지위즐이 자기 자동 탐사막대를 되찾고 싶다는데!', `MaleText_loc4`='嘿，布莱！比格维兹想要要回他的探水棒！', `MaleText_loc5`='嘿，布萊!比格維茲想要回他的探水棒!', `MaleText_loc7`='¡Eh, Bly! ¡Silvaina quiere que le devuelvas su vara divinomática!', `FemaleText_loc1`='이봐, 블라이! 빌지위즐이 자기 자동 탐사막대를 되찾고 싶다는데!', `FemaleText_loc4`='嘿，布莱！比格维兹想要要回他的探水棒！', `FemaleText_loc5`='嘿，布萊!比格維茲想要回他的探水棒!', `FemaleText_loc7`='¡Eh, Bly! ¡Silvaina quiere que le devuelvas su vara divinomática!' WHERE `ID`=3809;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='Zul''Farrak - Sergeant Bly - Greeting default.', `MaleText_loc4`='Zul''Farrak——Sergernt Bly——默认问候语。', `MaleText_loc5`='祖爾法拉克─布萊中士─原始設定問候語。', `MaleText_loc7`='Zul''Farrak - Sargento Bly - saludo habitual.' WHERE `ID`=3810;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 이만!', `MaleText_loc4`='我终于逃出来了！', `MaleText_loc5`='我終於逃出來了!', `MaleText_loc7`='¡Me voy de aquí!' WHERE `ID`=3811;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 누구도 사막유랑단 유목민에게 덤비지 못해. 제아무리 날고 기는 닭 로봇이라 해도 말이야! 공격!', `MaleText_loc4`='没人敢挑战废土强盗团——机械小鸡也不行！进攻！', `MaleText_loc5`='沒人敢挑戰廢土強盜團─機械小雞也不行!進攻!', `MaleText_loc7`='¡Nadie osa desafiar a los nómadas Vagayermos! ¡Ni siquiera unos pollos robotizados! ¡ATACAD!', `FemaleText_loc1`='그 누구도 사막유랑단 유목민에게 덤비지 못해. 제아무리 날고 기는 닭 로봇이라 해도 말이야! 공격!', `FemaleText_loc4`='没人敢挑战废土强盗团——机械小鸡也不行！进攻！', `FemaleText_loc5`='沒人敢挑戰廢土強盜團─機械小雞也不行!進攻!', `FemaleText_loc7`='¡Nadie osa desafiar a los nómadas Vagayermos! ¡Ni siquiera unos pollos robotizados! ¡ATACAD!' WHERE `ID`=3812;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요! 모험을 즐기시는 분이시군요. 혹시 도전할 만한 일을 찾고 있다면 한 가지 제안이 있어요.$B$B지금 저는 열심히 드루이드들을 돕고 있어요. 제가 발명한 고성능 자동부화기로 히포그리프들을 구하려고요. 히포그리프들에게 페랄라스의 폐허에 사는 골두니 오우거들이 나쁜 영향을 미치고 있습니다. 때문에 그 수가 점점 줄어들고 있어요.$B$B그래서 저는 여러 종류의 알을 모은답니다. 저를 도와 알을 좀 찾아주시겠습니까?', `FemaleText_loc4`='你好！如果你想要接受一些挑战的话，我这里有个建议给你！$B$B我正在利用我发明的超级测蛋器帮助暗夜精灵的德鲁伊们拯救鹰角兽。由于菲拉斯废墟中的戈杜尼食人魔，这种生物的数量正在迅速减少。$B$B我收集各种不同类型的蛋。', `FemaleText_loc5`='你好!如果你想要接受一些挑戰的話，我這裡有個建議給你!$B$B我正在利用我發明的超級測蛋器幫助夜精靈的德魯伊們拯救鷹角獸。他們受到菲拉斯廢墟中的戈杜尼巨魔影響，數量正在迅速減少。$B$B我收集各種不同類型的蛋。你能幫我找到一些嗎?', `FemaleText_loc7`='Eh, hola. Tengo una propuesta para alguien que esté sediento de aventuras como tú, si estás a la altura del desafío.$B$BJunto con mi invento, el Superhuevomático, estoy muy ocupado ayudando a los druidas en su campaña para salvar a los hipogrifos. Estas aves se ven afectadas por los efectos nocivos que supone la presencia de los ogros Gordunni en las ruinas de Feralas, y se están extinguiendo.$B$BYo recojo muchas clases distintas de huevos. ¿Podrías ayudarme a encontrar unos cuantos?' WHERE `ID`=3813;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='히포그리프에 대해 더 자세히 얘기해 주세요.', `MaleText_loc4`='请告诉我更多关于角鹰兽的信息。', `MaleText_loc5`='請告訴我更多關於角鷹獸的資訊。', `MaleText_loc7`='Háblame más sobre los hipogrifos.', `FemaleText_loc1`='히포그리프에 대해 더 자세히 얘기해 주세요.', `FemaleText_loc4`='请告诉我更多关于角鹰兽的信息。', `FemaleText_loc5`='請告訴我更多關於角鷹獸的資訊。', `FemaleText_loc7`='Háblame más sobre los hipogrifos.' WHERE `ID`=3814;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='서쪽에 있는 페랄라스라는 곳에서 나이트 엘프들의 오랜 친구인 히포그리프들이 위험에 처해있다고 들었어요.$B$B남쪽의 이실디엔 폐허에서 알을 구해 오세요. 가져온 알은 고성능 자동부화기에 넣어 보면 부화할 수 있는지 알 수 있답니다. 제가 부화할 수 있는 알들만 드루이드들에게 보낼 거예요. 골두니 오우거의 사악한 마법을 피해 건강한 히포그리프로 자랄 수 있도록 말이지요.$B$B구해 온 알들 중 일부는 상태가 좋지 않아서 절대 부화하지 않는다는 걸 알아두세요.', `FemaleText_loc4`='这里西边有一处叫做菲拉斯的地方，那一带的鹰角兽正处于危险的境地中。$B$B我需要你从菲拉斯南部的伊斯迪尔废墟中给我带回鹰角兽的蛋，超级测蛋器会分析你带回来的蛋，并判断它是否可以孵化。然后我可以把蛋送到达纳苏斯去孵化，避免它们受到戈杜尼食人魔的黑暗魔法的影响！$B$B$n，你要知道，有些蛋即使完整无缺也是不可能孵化出来的。', `FemaleText_loc5`='這裡西邊有一處叫做菲拉斯的地方，那一帶的角鷹獸是夜精靈長久以來的同伴，他們正處於危險的境地中。$B$B我需要你從菲拉斯南部的伊斯迪爾廢墟中給我帶回角鷹獸的蛋，超級測蛋器會分析你帶回來的蛋，並判斷它是否可以孵化。然後我可以把蛋送給德魯伊們，避免它們受到戈杜尼巨魔的黑暗魔法影響。$B$B請記得一點，$n，有些被拯救的蛋是壞掉的，永遠也不會孵化。', `FemaleText_loc7`='En un lugar llamado Feralas, situado al oeste de aquí, los hipogrifos, viejos compañeros de los elfos de la noche, están en peligro.$B$BNecesito que rescates un huevo de las ruinas de Isildien, en el sur, allí. El Superhuevomático puede analizar cualquier huevo y evalúa si es apto para empollar. Luego envío los huevos a los druidas, a salvo de la magia negra de los ogros Gordunni.$B$BTienes que tener en cuenta, $n, que algunos de los huevos rescatados no están en buen estado, por lo que nunca incubarán cría alguna.' WHERE `ID`=3815;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비행 시스템 가동! 꼬꼬댁! 무법항으로 이동을 위해 로켓 가동 중!', `MaleText_loc4`='飞行系统启动！咯咯嗒！发动火箭并准备传送到藏宝海湾！', `MaleText_loc5`='飛行系統啟動!咯咯嗒!火箭運作中，準備傳送至藏寶海灣!', `MaleText_loc7`='¡Sistemas de vuelo en línea! ¡CLUC! ¡Activando cohetes para transporte a Bahía del Botín!' WHERE `ID`=3816;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 비밀을 말해 주겠소... 전망대 절벽으로 가시오. 이 린지가 그곳 섬에 뭔가 숨겨 놨소.', `MaleText_loc4`='林吉现在可以告诉你我的秘密了……$n应该去望海崖。林吉在那里的小岛上藏了一点东西。', `MaleText_loc5`='林吉現在可以告訴你我的秘密了...$n應該去望海崖。林吉在那裡的小島上藏了一點東西。', `MaleText_loc7`='Rin''ji te va a contar un secreto... $n debería ir a los Precipicios del Horizonte. Rin''ji escondió algo en la isla que hay allí.' WHERE `ID`=3817;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 그걸 찾아서 가지시오! 아무에게도 내가 말해 줬다고 얘기하면 안 된다오!', `MaleText_loc4`='你找到它，它就是你的了！不要把林吉告诉你的秘密告诉任何人！', `MaleText_loc5`='你找到它，它就是你的了!不要把林吉告訴你的秘密告訴任何人!', `MaleText_loc7`='¡Si lo encuentras, es tuyo! ¡No le digas a nadie que Rin''ji habló contigo!' WHERE `ID`=3818;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비상 동력 가동 완료! 이동식 발동기 초기화 중! 꼬꼬댁!', `MaleText_loc4`='备用动力启动！流动电机启动！咯咯嗒！', `MaleText_loc5`='備用動力啟動!流動電機啟動!咯咯嗒!', `MaleText_loc7`='¡Alimentación de emergencia activada! ¡Inicializando motor ambulatorio! ¡CLUC!' WHERE `ID`=3819;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비행 시스템 가동! 꼬꼬댁! 무법항으로 이동을 위해 로켓 가동 중!', `MaleText_loc4`='飞行系统启动！咯咯嗒！发动火箭并准备传送到藏宝海湾！', `MaleText_loc5`='飛行系統啟動!咯咯嗒!火箭運作中，準備傳送至藏寶海灣!', `MaleText_loc7`='¡Sistemas de vuelo en línea! ¡CLUC! ¡Activando cohetes para transporte a Bahía del Botín!' WHERE `ID`=3820;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꼬꼬댁! 이상 공간 형태 감지 -- 위험 임박! 꼬꼬댁!', `MaleText_loc4`='咯咯嗒！探测到空间异常——危险临近！咯咯嗒！', `MaleText_loc5`='咯咯嗒!探測到空間異常─危險臨近!咯咯嗒!', `MaleText_loc7`='¡CLUC! ¡Los sensores detectan una anomalía espacial - peligro inminente! ¡CLUC!' WHERE `ID`=3821;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꼬꼬댁! 공간 형태 이상 감지 -- 위험 임박! 꼬꼬댁!', `MaleText_loc4`='咯咯嗒！探测到空间异常——危险临近！咯咯嗒！', `MaleText_loc5`='咯咯嗒!探測到空間異常─危險臨近!咯咯嗒!', `MaleText_loc7`='¡CLUC! ¡Los sensores detectan una anomalía espacial - peligro inminente! ¡CLUC!' WHERE `ID`=3822;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비행 시스템 가동! 꼬꼬댁! 무법항으로 이동을 위해 로켓 가동 중!', `MaleText_loc4`='飞行系统启动！咯咯嗒！发动火箭并准备传送到藏宝海湾！', `MaleText_loc5`='飛行系統啟動!咯咯嗒!火箭運作中，準備傳送至藏寶海灣!', `MaleText_loc7`='¡Sistemas de vuelo en línea! ¡CLUC! ¡Activando cohetes para transporte a Bahía del Botín!' WHERE `ID`=3823;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비상 동력 가동 완료! 이동식 발동기 초기화 중! 꼬꼬댁!', `MaleText_loc4`='备用动力启动！流动电机启动！咯咯嗒！', `MaleText_loc5`='備用動力啟動!流動電機啟動!咯咯嗒!', `MaleText_loc7`='¡Alimentación de emergencia activada! ¡Inicializando motor ambulatorio! ¡CLUC!' WHERE `ID`=3824;
