UPDATE `locales_broadcast_text` SET `MaleText_loc1`='결국 예상대로인가? 어쨌거나 나도 널 싫어한다고!', `MaleText_loc4`='我们就此结束了？好吧，我一点都不喜欢你！！', `MaleText_loc5`='我們就此結束了?好吧，我一點都不喜歡你!!', `MaleText_loc7`='¿Después de todo lo que hemos pasado juntos? ¡Si al fin y al cabo no me gustabas!' WHERE `ID`=3884;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요, 노그 씨! 훈련이 필요합니다.', `MaleText_loc4`='你好，诺格！我需要接受训练。', `MaleText_loc5`='你好，諾格!我需要接受訓練。', `MaleText_loc7`='¡Que tengas buen día, Nogg! Necesito instrucción.', `FemaleText_loc1`='안녕하세요, 노그 씨! 훈련이 필요합니다.', `FemaleText_loc4`='你好，诺格！我需要接受训练。', `FemaleText_loc5`='你好，諾格!我需要接受訓練。', `FemaleText_loc7`='¡Que tengas buen día, Nogg! Necesito instrucción.' WHERE `ID`=3885;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요! 찾고 계신 물건이 제 가게에서 안 보이시나요? 말씀만 하시면 제가 꼭 구해다 드리겠습니다!', `MaleText_loc4`='你好，$n！如果你需要的东西在我店里找不到，那么我可以专门去帮你找一下！', `MaleText_loc5`='你好，$n!如果你需要的東西在我店裡找不到，那麼我可以專門去幫你找一下!', `MaleText_loc7`='¡Hola, $n! ¡Si no encuentras eso que quieres en mi tienda, puedo conseguirlo con toda probabilidad!' WHERE `ID`=3901;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요, 소빅 씨! 물건을 좀 보고 싶습니다.', `MaleText_loc4`='你好，索维克，我想要看看你的货物。', `MaleText_loc5`='你好，索維克，我想要看看你的貨物。', `MaleText_loc7`='Hola, Sovik, me gustaría ver tus mercancías.', `FemaleText_loc1`='안녕하세요, 소빅 씨! 물건을 좀 보고 싶습니다.', `FemaleText_loc4`='你好，索维克，我想要看看你的货物。', `FemaleText_loc5`='你好，索維克，我想要看看你的貨物。', `FemaleText_loc7`='Hola, Sovik, me gustaría ver tus mercancías.' WHERE `ID`=3902;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈리건으로 갈 생각이면 잠깐만 이리 와서 저와 얘기나 나누시죠, $n.', `MaleText_loc4`='$n，如果你想去诺莫瑞根，那就和我谈谈。', `MaleText_loc5`='$n，如果你想去諾姆瑞根，那就和我談談。', `MaleText_loc7`='¡Ven a charlar conmigo cuando vayas a Gnomeregan, $n!' WHERE `ID`=3903;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='응답장치를 당신 키와 체중에 맞게 조절할 테니 잠시 기다려 주시오, $n.', `MaleText_loc4`='$n，给我点时间来根据你的身高体重调整传送器。', `MaleText_loc5`='$n，給我點時間來根據你的身高體重調整傳送器。', `MaleText_loc7`='Dame un segundo mientras calibro el transpondedor según tu altura y tu peso, $n.' WHERE `ID`=3904;
