UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 정말 제대로 가고 있는 건가요? 어쩌면 이쪽 길로 가야 하는 것 아닌지...', `FemaleText_loc4`='你确定这条路正确吗？也许我们该走那条路……', `FemaleText_loc5`='你確定這條路正確嗎?也許我們該走那條路...', `FemaleText_loc7`='¿Seguro que vamos por el camino correcto? Quizás debamos mejor ir por aquí...' WHERE `ID`=3909;
