UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런, 또 멋대로 길을 벗어나 버렸네요. 죄송해요.', `FemaleText_loc4`='哦，我又迷路了，抱歉。', `FemaleText_loc5`='哦，我又迷路了，抱歉。', `FemaleText_loc7`='Oh, me he vuelto a desviar. Lo siento.' WHERE `ID`=3913;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말 신나는 모험이로군요!', `FemaleText_loc4`='这真是一段有趣的旅程！', `FemaleText_loc5`='這真是一段有趣的旅程!', `FemaleText_loc7`='¡Vaya aventura!' WHERE `ID`=3914;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말 못 참겠어요. 이곳은 정말 너무 아름다워요.', `FemaleText_loc4`='我有点情不自禁了，这真是个漂亮的地方。', `FemaleText_loc5`='我有點情不自禁了，這真是個漂亮的地方。', `FemaleText_loc7`='No puedo evitarlo, de verdad. Este es un lugar realmente maravilloso.' WHERE `ID`=3915;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='또 종소리가 들리네요. 너무나 아름다운 소리예요.', `FemaleText_loc4`='又听到铃声了，真好听。', `FemaleText_loc5`='又聽到鈴聲了，真好聽。', `FemaleText_loc7`='Otra vez la campana, qué sonido más hermoso.' WHERE `ID`=3916;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어머, 여기 있었군요, 무쇠이빨 아저씨! 미안해요. 멋대로 돌아다니면 안 되는 거 알고 있어요.', `FemaleText_loc4`='啊，你在这里啊，罗克比特！对不起，我知道我不该到处乱跑。', `FemaleText_loc5`='啊，你在這裡啊，羅克比特!對不起，我知道我不該到處亂跑。', `FemaleText_loc7`='¡Vaya, aquí estás, Muerdepiedras! Lo siento, sé que no debería desviarme de la ruta.' WHERE `ID`=3917;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 길을 벗어납니다.', `FemaleText_loc4`='%s开始到处乱跑。', `FemaleText_loc5`='%s開始到處亂跑。', `FemaleText_loc7`='%s empieza a desviarse.' WHERE `ID`=3918;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 다르나서스에 오신 걸 환영합니다. 저는 가죽세공을 가르치고 있습니다. 무엇을 도와드리면 될까요?', `MaleText_loc4`='$c，你好，我是达纳苏斯的制皮训练师。我能帮你什么忙吗？', `MaleText_loc5`='$c，你好，我是達納蘇斯的製皮訓練師。我能幫你什麼忙嗎?', `MaleText_loc7`='Hola, $c, soy el instructor de peletería de Darnassus. ¿En qué puedo ayudarte?' WHERE `ID`=3919;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요 $c. 저는 썬더 블러프에서 근무하는 전문 가죽세공인입니다. 무엇을 도와드릴까요?', `FemaleText_loc4`='$c，你好，我是达纳苏斯的制皮训练师。我能帮你什么吗？', `FemaleText_loc5`='$c，你好，我是雷霆崖的製皮訓練師。我能幫你什麼嗎?', `FemaleText_loc7`='Hola, $c, soy la instructora de peletería de Cima del Trueno. ¿En qué puedo ayudarte?' WHERE `ID`=3920;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기 궤짝에서 종을 꺼내는 것을 잊지 마세요. 그리고 $n 님, 만약 제가 길을 벗어나 엉뚱한 쪽으로 가면 종을 울리는 것을 잊지 마세요. 그럼 제가 당신을 다시 찾아가게 될 테니까요.', `FemaleText_loc4`='不要忘了从箱子里拿上我的铃铛。记住，如果我迷路了，你就摇响铃铛，这样我就能找到你了。', `FemaleText_loc5`='不要忘了從箱子裡拿上我的鈴鐺。記住，如果我迷路了，你就搖響鈴鐺，這樣我就能找到你了。', `FemaleText_loc7`='No olvides sacar mi campana del cofre. Y recuerda, si me desvío, tócala y te volveré a encontrar.' WHERE `ID`=3921;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌아와서 정말 다행이다, 샤이. 제발 그렇게 엉뚱한 곳으로 가버리지 마라! 널 잃어버리면 네 부모님에게 어떻게 말하라는 거냐?', `MaleText_loc4`='很高兴你回来了，沙恩。以后请不要再这样了！如果你真的不见了，我怎么向你父母交待？', `MaleText_loc5`='很高興你回來了，沙恩。以後請不要再這樣了!如果你真的不見了，我怎麼向你父母交代?', `MaleText_loc7`='Qué bien que hayas vuelto, Shay. ¡Por favor, no vuelvas a irte corriendo! ¿Qué dirán tus padres si te pierdo?' WHERE `ID`=3922;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='골두니 오우거에 대해 더 자세히 얘기해 주세요.', `MaleText_loc4`='请告诉我更多关于戈杜尼食人魔的信息。', `MaleText_loc5`='請告訴我更多關於戈杜尼巨魔的資訊。', `MaleText_loc7`='Háblame más sobre los ogros Gordunni.', `FemaleText_loc1`='골두니 오우거에 대해 더 자세히 얘기해 주세요.', `FemaleText_loc4`='请告诉我更多关于戈杜尼食人魔的信息。', `FemaleText_loc5`='請告訴我更多關於戈杜尼巨魔的資訊。', `FemaleText_loc7`='Háblame más sobre los ogros Gordunni.' WHERE `ID`=3923;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='골두니 오우거 부족은 페랄라스의 숲 상당 부분을 지배하고 있습니다. 그들의 사악한 마법이 주위의 자연에 스며들어 주변 환경은 물론 그곳에 사는 생명체들에게도 해를 끼치고 있답니다.$B$B혹시 페랄라스로 갈 생각이라면 이 오우거들을 조심하세요. 상당히 간악한 데다 강력한 어둠의 마법을 부릴 줄 아는 녀석들이 많으니까요.', `FemaleText_loc4`='庞大的戈杜尼食人魔部落控制了菲拉斯森林的很大一块区域。他们的黑暗魔法已经渗透了周围的环境，从而直接对那里的其它生物造成了毁灭性的打击。$B$B如果你去菲拉斯的话，可得小心那些食人魔——他们非常肮脏，而且很多都会使用强大的黑暗魔法。', `FemaleText_loc5`='龐大的戈杜尼巨魔部族控制了菲拉斯森林的很大一塊區域。他們的黑暗魔法已經滲透了周圍的環境，從而直接對那裡的其他生物造成了毀滅性的打擊。$B$B如果你去菲拉斯的話，可得小心那些巨魔─他們非常骯髒，而且很多都會使用強大的黑暗魔法。', `FemaleText_loc7`='Los Gordunni son una extensa tribu de ogros que ejerce el control sobre áreas considerables de bosque en Feralas. Su magia negra impregna los elementos circundantes, dañando tanto el entorno como las criaturas que lo habitan.$B$BSi decides viajar a Feralas, ten siempre en cuenta a estos ogros. Son asquerosos y muchos utilizan grandes poderes de magia negra.' WHERE `ID`=3924;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼른 일해, 이 애송이들아!', `MaleText_loc4`='你们这些笨蛋，快点工作！', `MaleText_loc5`='你們這些笨蛋，快點工作!', `MaleText_loc7`='¡A trabajar, holgazanes!' WHERE `ID`=3925;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 가동됩니다!', `MaleText_loc4`='%s活动起来！', `MaleText_loc5`='%s啟動了!', `MaleText_loc7`='¡%s se activa!' WHERE `ID`=3926;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자폭 절차 가동 완료!', `MaleText_loc4`='自毁系统程序启动。', `MaleText_loc5`='自毀程序已啟動。', `MaleText_loc7`='Secuencia de autodestrucción activada.' WHERE `ID`=3927;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 환호합니다!', `MaleText_loc4`='%s开心地欢呼了起来！', `MaleText_loc5`='%s開心地歡呼!', `MaleText_loc7`='¡%s aplaude!' WHERE `ID`=3928;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구해줘서 고마워요! 당신이 한 일에 대한 얘기가 널리 퍼질 거예요.', `MaleText_loc4`='感谢你救了我！你的事迹一定会被广为流传的。', `MaleText_loc5`='感謝你救了我!你的事蹟一定會被廣為流傳的。', `MaleText_loc7`='¡Gracias por rescatarme! Tus actos no pasarán inadvertidos.' WHERE `ID`=3929;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 모두에게 손을 흔들며 작별 인사를 합니다.', `MaleText_loc4`='%s向所有人挥手道别。', `MaleText_loc5`='%s向所有人揮手道別。', `MaleText_loc7`='%s se despide de todos con la mano.' WHERE `ID`=3930;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐! 우리 보물에서 손 떼라고!', `MaleText_loc4`='嘿！离我们的财宝远一点！', `MaleText_loc5`='嘿!離我們的財寶遠一點!', `MaleText_loc7`='¡Eh! ¡Apártate de nuestro tesoro!', `FemaleText_loc1`='이봐! 우리 보물에서 손 떼라고!', `FemaleText_loc4`='嘿！离我们的财宝远一点！', `FemaleText_loc5`='嘿!離我們的財寶遠一點!', `FemaleText_loc7`='¡Eh! ¡Apártate de nuestro tesoro!' WHERE `ID`=3931;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그건 우리 보물이야, 이 애송이 녀석!', `MaleText_loc4`='你这个笨蛋，那些是我们的财宝！', `MaleText_loc5`='你這個笨蛋，那些是我們的財寶!', `MaleText_loc7`='¡Ese es nuestro tesoro, pelele!', `FemaleText_loc1`='그건 우리 보물이야, 이 애송이 녀석!', `FemaleText_loc4`='你这个笨蛋，那些可是我的财宝！', `FemaleText_loc5`='你這個笨蛋，那些可是我的財寶!', `FemaleText_loc7`='¡Ese es nuestro tesoro, pelele!' WHERE `ID`=3932;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈더러 훔쳐 가라고 숨겨놓은 줄 알아?', `MaleText_loc4`='别以为你可以拿走我们的财宝！', `MaleText_loc5`='別以為你可以拿走我們的財寶!', `MaleText_loc7`='¡No escondimos todo esto para que pudieras venir a robarlo sin más!', `FemaleText_loc1`='네놈더러 훔쳐 가라고 숨겨놓은 줄 알아?', `FemaleText_loc4`='别以为你可以拿走我们的财宝！', `FemaleText_loc5`='別以為你可以拿走我們的財寶!', `FemaleText_loc7`='¡No escondimos todo esto para que pudieras venir a robarlo sin más!' WHERE `ID`=3933;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='웬 놈이냐?! 감히 네놈이 엿듣다니!', `MaleText_loc4`='什么？！大胆！', `MaleText_loc5`='什麼?!大膽!', `MaleText_loc7`='¡¿Qué?! ¡Cómo te atreves!' WHERE `ID`=3934;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이언포지에서 이렇게 멀리 떨어진 곳에서는 대장장이를 보는 일이 드문데... 뭘 도와주면 좋겠습니까?', `MaleText_loc4`='铁匠？真少见啊。我能为你做什么吗？', `MaleText_loc5`='在離鐵爐堡這麼遠的地方鐵匠是很少見的。我能為你做什麼嗎?', `MaleText_loc7`='No hay demasiados herreros en un lugar tan distante de Forjaz como este. ¿Qué puedo hacer por ti?' WHERE `ID`=3935;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='데피아즈단은 반드시 성공할 것이다! 떠돌이 녀석 따위가 감히 우리를 막으려고 하느냐!', `MaleText_loc4`='迪菲亚兄弟会必胜！没有人能阻止我们！', `MaleText_loc5`='迪菲亞兄弟會必勝!沒有人能阻止我們!', `MaleText_loc7`='¡Los Defias vencerán! ¡Ningún aventurero enclenque nos detendrá!' WHERE `ID`=3936;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 머리 위에 튼튼한 화강암 천장이 없으면 편히 쉴 수가 없답니다. 머리 위에 별이 어찌나 많은지 등골이 서늘할 정도라니까요.', `MaleText_loc4`='如果不住在有大理石天花板的房间里，我就浑身不舒服。天上的星星让我觉得很烦燥……', `MaleText_loc5`='如果不住在有大理石天花板的房間裡，我就渾身不舒服。天上的星星讓我覺得很煩燥...', `MaleText_loc7`='Al parecer, no puedo ponerme cómodo si no es con un sólido techo de granito sobre mi cabeza. Todas esas estrellas allí arriba bastan para darte escalofríos.' WHERE `ID`=3937;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 정도는 돼야 입을 만한 쇳덩어리라고 할 수 있지. 모양새에 기능까지 골고루 갖추다니 놀랐습니다. 이만한 건 예전에 딱한 번 본 적이 있는데 대용광로에 있는 장인인 그룸누스 스틸셰이퍼가 만든 것이었지요. 분명 그 친구는 그때보다 솜씨가 더 늘었을 거요. 당신에게 한 수 가르쳐 줄 수도 있겠군요.', `MaleText_loc4`='这确实是一件上好的护甲，它给我留下了深刻的印象。我只知道谁可以打造出同样品质的护甲，他叫格鲁努斯·削钢，就在铁炉堡的大煅炉那里。我相信那位锻造大师一定可以教你不少东西。', `MaleText_loc5`='這確實是一件上好的護甲，它給我留下了深刻的印象。我只知道誰可以打造出同樣品質的護甲，他叫格魯努斯·削鋼，就在鐵爐堡的大鍛爐那裡。我相信那位鍛造大師一定可以教你不少東西。', `MaleText_loc7`='¡Ese es un acero que sí merece la pena llevar encima! Forma y función, $gmuchacho:muchacha;. Estoy impresionado. Solo he visto a alguien capaz de superarlo, un maestro de la Gran Fundición llamado Grumnus Forjacero. Y apuesto a que ha aprendido algunos trucos desde entonces. Probablemente podría enseñarte un par de cosas.' WHERE `ID`=3938;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이언포지 한복판에 있는 대용광로로 가 보십시오. 그는 그곳에서 우리 종족의 다른 훌륭한 장인들과 함께 일하고 있습니다.', `MaleText_loc4`='大煅炉在铁炉堡的最中心。他就在那里和其他的铸造大师一起工作。', `MaleText_loc5`='大鍛爐在鐵爐堡的最中心。他就在那裡和其他的鑄造大師一起工作。', `MaleText_loc7`='Ve a la Gran Fundición. Está justo en el centro de Forjaz. Trabaja allí, junto con otros maestros de nuestra hermandad.' WHERE `ID`=3939;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이것 참, 이렇게나 훌륭한 칼날은 프라우드무어 님과 그분의 부하들과 함께 로데론을 떠나온 뒤로 처음 보았군. 나는 당신에게 많은 것을 가르칠 수 있을 것 같지 않지만 보르구스 스틸핸드를 찾아간다면 그가 분명 한 수 가르쳐 줄 수 있을 거요. 그는 내가 본 최고의 무기 제작자니까 말이야.', `MaleText_loc4`='自从跟随普罗德摩尔以及她的人民一起离开洛丹伦以来，我就没有见过铸造得如此精良的武器。看来我没有什么可以教你的了，但是如果你去找博古斯·钢拳的话，他一定会向你展示一些华丽的技艺，他是我遇见过的最好的铁匠。', `MaleText_loc5`='自從跟隨普勞德摩爾以及她的人民一起離開羅德隆以來，我就沒有見過鑄造得如此精良的武器。看來我沒有什麼可以教你的了，但是如果你去找博古斯·鋼拳的話，他一定會向你展示一些華麗的技藝，他是我遇見過的最好的武器鍛造師。', `MaleText_loc7`='Vaya, no había visto hojas tan finas desde que me fui de Lordaeron con Valiente y su gente. Al parecer, ya no puedo enseñarte más, pero si buscamos a Borgus Mano de Acero, estoy seguro de que te enseñará unas cuantas cosas. Es el mejor forjador de armas que he conocido jamás.' WHERE `ID`=3940;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보르구스는 한때 대용광로에서 일을 했었지만 스톰윈드 재건이 완료되자 그리로 갔다고 들었소. 카스룸 액스핸드라는 자와 드워프 지구에서 가게를 열었다는 소문이 있소.', `MaleText_loc4`='博古斯以前据说是在大煅炉旁边工作的，但是当暴风城的重建工作完成之后，他就搬到了暴风城。有传言说他和一个叫卡斯鲁姆·斧拳的家伙一起在暴风城的矮人区开了一家店。', `MaleText_loc5`='博古斯以前據說是在大鍛爐旁邊工作的，但是當暴風城的重建工作完成之後，他就搬到了暴風城。有傳言說他和一個叫卡斯魯姆·斧拳的傢伙一起在暴風城的矮人區開了一家店。', `MaleText_loc7`='Borgus solía trabajar en la Gran Fundición, pero me contaron que se fue a Ventormenta cuando terminaron la reconstrucción. Dicen por ahí que abrió una tienda en el Distrito de los Enanos con un hombre llamado Kathrum Mano de Hacha.' WHERE `ID`=3941;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='젊은이, 눈이 멀었나? 바로 밖에 샤이스가 서 있지 않나.', `MaleText_loc4`='嘿，难道你的眼睛不好使吗？莎伊斯就站在外面啊。', `MaleText_loc5`='嘿，難道你的眼睛不好使嗎?莎伊斯就站在外面啊。', `MaleText_loc7`='¿Estás $gciego:ciega;, joven? Shayis está ahí fuera.' WHERE `ID`=3942;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강철은 단단하고 기술은 더 탄탄하군. 그 강철과 강한 힘을 가지고 내 아내 샤이스 스틸퓨리를 찾아가 보시오. 방어구 제작술이라면 나보다 더 뛰어나니까.', `MaleText_loc4`='你的锻造技术非常高超。你应该去找我的妻子莎伊斯·钢怒，她锻造盔甲的技术天下无双，即便是我也比不上她。', `MaleText_loc5`='你的鍛造技術非常高超。你應該去找我的妻子莎伊斯·鋼怒，她鍛造盔甲的技術天下無雙，即便是我也比不上她。', `MaleText_loc7`='Tu temple es de acero y tus habilidades más fuertes aún. Ve con tu temple y tu fuerza a ver a mi compañera Shayis Furiacerada. Su talento en el arte de fabricar armaduras es insuperable y es decididamente mejor que yo.' WHERE `ID`=3943;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 작업장에 온 걸 환영하네, 대장장이 친구. 한 가지 작은 비밀을 가르쳐 주지. 이 세상에 어느 누구도 믿을 자가 없다는 거야. 남자든, 여자든, 동물이든지 할 것 없이 모두... 하지만 단 한 가지 믿을 게 있다면, 바로... 강철이라네.', `MaleText_loc4`='欢迎你，铁匠。让我和你分享一些秘密吧。在这世界上，你不能相信任何人。任何人……你能相信的只有钢铁。', `MaleText_loc5`='歡迎你，鐵匠。讓我和你分享一些秘密吧。在這世界上，你不能相信任何人。任何人...你能相信的只有鋼鐵。', `MaleText_loc7`='Te doy la bienvenida a mi fragua, $gherrero:herrera;. Déjame compartir contigo un pequeño secreto. No puedes confiar en nadie, en nadie, ¿me oyes? No puedes confiar en ningún hombre, en ninguna mujer, en ninguna bestia... pero sí puedes confiar en el acero.' WHERE `ID`=3944;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 작업장에 뭘 찾으러 온 건가? 훈련을 받고 싶나? 아니면 강철의 비밀이라도 캐러 왔나? 아니면 가열로의 신비를 파헤치러? 어서 말해 보게나!', `MaleText_loc4`='你有什么事？你是来接受训练的吗？你是来寻找钢铁的秘密的吗？还是要学习锻造的技巧？快说！', `MaleText_loc5`='你有什麼事?你是來接受訓練的嗎?你是來尋找鋼鐵的秘密的嗎?還是要學習鍛造的技巧?快說!', `MaleText_loc7`='¿Qué buscas en mi herrería? ¿Acaso buscas instrucción? ¿Acaso deseas conocer los secretos del acero? ¿Los misterios de la forja? ¡Habla, Bruto!' WHERE `ID`=3945;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디 있는고 하니, 옆집 전설의 무기점으로 가보게. 그는 위대한 영웅들을 위해 특별한 무기를 만든다네. 경의를 표하면 전설의 무기를 만드는 법을 가르쳐줄지도 몰라.', `MaleText_loc4`='他在哪里？去隔壁的“传说中的装备”店里找他吧，他在那里为伟大的英雄铸造武器。向他证明你的能力，然后他才会给你展示他那神乎其技的手艺。', `MaleText_loc5`='他在哪裡?去隔壁的「傳說中的裝備」店裡找他吧，他在那裡為偉大的英雄鑄造武器。向他證明你的能力，然後他才會給你展示他那神乎其技的手藝。', `MaleText_loc7`='¿Dónde está? Dirígete a la puerta siguiente, donde encontrarás las armas de leyenda. El herrero que trabaja ahí fabrica armas especiales para grandes héroes. Hónralo y seguramente te enseñará cómo fabricar armas legendarias.' WHERE `ID`=3946;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훌륭한 칼날에 튼튼한 도끼라... 이제 무기 제작에 대해서라면 더는 가르칠 게 없군, $n. 그 자부심과 용기를 그대로 가지고 켈그룩 블러드액스에게 가게. 그가 자네가 필요로 할 기술을 잘 가르쳐 줄 걸세.', `MaleText_loc4`='多么锋利的刀刃啊，这绝对是一把精品战斧。$n，在武器锻造方面我已经没有什么可以教你的了。去向克尔格鲁克·血斧展示你的勇气和荣耀吧，他会帮你将这些融入你的技巧中，使你获得更大的提升。', `MaleText_loc5`='多麼鋒利的刀刃啊，這絕對是一把精品戰斧。$n，在武器鑄造方面我已經沒有什麼可以教你的了。去向克爾格魯克·血斧展示你的勇氣和榮耀吧，他會幫你將這些融入你的技巧中，使你獲得更大的提升。', `MaleText_loc7`='Buenas hojas, hachas sólidas. No me queda más que enseñarte en la fabricación de armas, $n. Muestra tu orgullo y tu valor a Kelgruk Hacha de Sangre, que él los transformará en las habilidades que vas a necesitar.' WHERE `ID`=3947;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기 출구가 있군! 서둘러요, 어서!', `MaleText_loc4`='我看到出口了！快点，快点！', `MaleText_loc5`='我看到出口了!快點，快點!', `MaleText_loc7`='¡Veo la salida! ¡Deprisa, deprisa!' WHERE `ID`=3948;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탈출 방지 장치 가동 완료... 자폭까지 20초...', `MaleText_loc4`='反逃脱系统激活。自毁系统将在20秒后启动……', `MaleText_loc5`='反逃脫系統啟動。自毀系統將在20秒後啟動...', `MaleText_loc7`='Compuertas antiescape activadas. Autodestrucción en menos 20 segundos...' WHERE `ID`=3949;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경보폭탄 2600 고장. 자폭 절차 무효화. 작동 정지.', `MaleText_loc4`='警报炸弹2600型失效。自毁系统过载[激活]。冷却中[激活]。', `MaleText_loc5`='警報炸彈2600型失效。自毀系統超載[啟動]。冷卻中[啟動]。', `MaleText_loc7`='La unidad de alarma de la bomba 2600 ha fallado. Anular autodestrucción [ACTIVO]. Enfriamiento [ACTIVO].' WHERE `ID`=3950;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오그리마에 있는 명예의 골짜기로 가시오. 그곳에서 그녀는 남편과 두 딸이 함께 살고 있소. 실력이 뛰어난 대장장이는 많지만, 정령들이 말하길 당신을 가장 잘 지도할 사람은 그녀뿐이라는군.', `MaleText_loc4`='到奥格瑞玛的荣誉谷去找她。她和她的丈夫还有两个孩子都住在那里。他们都是出色的铁匠，而她将会是你最好的导师。', `MaleText_loc5`='到奧格瑪的榮譽谷去找她。她和她的丈夫還有兩個孩子都住在那裡。他們都是出色的鐵匠，而她將會是你最好的導師。', `MaleText_loc7`='Viaja a Orgrimmar, al Valle del Honor. Allí vive ella con su marido y dos hijas. Todos ellos son herreros de grandes cualidades, pero los espíritus me indican que ella será quien mejor te guíe en tu aprendizaje.' WHERE `ID`=3951;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 솜씨는 내가 결코 따라갈 수가 없구려. 강철에 영혼의 숨결을 불어넣어 자신을 보호할 수 있으니 말이오. 제자가 스승을 능가했으니 이제는 더 가르칠 것이 없소이다. 계속 가르침을 받을 수 있는 곳으로 보내겠소. 오그리마에 있는 샤이스 스틸퓨리를 찾아가시오. 그는 내가 아는 최고의 방어구제작자이니까.', `MaleText_loc4`='你已经在锻造方面有了相当的造诣，可以把钢铁变成护身的铠甲。你的技艺已经超过了我，我必须让你去更好的锻造训练师那里深造。$n，你应该去奥格瑞玛找莎伊斯·钢怒，她是我所知道的最好的铸甲师，她应该能教你很多东西。', `MaleText_loc5`='你已經在鍛造方面有了相當的造詣，可以把鋼鐵變成護身的鎧甲。你的技藝已經超越了我，我必須讓你去更好的鍛造訓練師那裡深造。$n，你應該去奧格瑪找莎伊斯·鋼怒，她是我所知道最好的護甲鍛造師，她應該能教你很多東西。', `MaleText_loc7`='Tú guías a los espíritus en el arte del acero para proteger y defender con mucha mayor habilidad que la que puedo tener yo. El estudiante ha superado al maestro y ahora tengo que enviarte allí donde puedas continuar cultivándote. $n, tienes que buscar a Shayis Furiacerada en Orgrimmar. Ella es la mejor forjadora de armaduras que jamás he conocido y puede enseñarte mucho.' WHERE `ID`=3952;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런...', `MaleText_loc4`='啊呀……', `MaleText_loc5`='啊呀...', `MaleText_loc7`='Oh, oh...' WHERE `ID`=3953;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모든 것에는 영혼이 있소. 영혼의 소리에 귀 기울이는 법을 배우면 사물의 모습을 당신이 원하는 대로 바꿀 수 있지. 대장장이 일이란 금속을 쳐서 당신이 원하는 모양을 억지로 만들어 내는 게 아니오. 강철 속에 살아 숨 쉬는 영혼의 소리에 귀를 기울여 그 영혼이 취하려는 모습으로 인도하는 것이지...', `MaleText_loc4`='所有东西都有灵魂，如果学会聆听它们的声音，你就可以随心所欲地使用它们的力量。锻造并不是击打金属并将其改变成自己想要的形状那么简单，你必须倾听钢铁的声音，然后指引它，让它为你所用。', `MaleText_loc5`='所有東西都有靈魂，如果學會聆聽它們的聲音，你就可以隨心所欲地使用它們的力量。鍛造並不是擊打金屬並將其改變成自己想要的形狀那麼簡單，你必須傾聽鋼鐵的聲音，然後指引它，讓它為你所用。', `MaleText_loc7`='Todo tiene un espíritu y si aprendes a escucharlo, podrás cogerlo y darle la forma que quieras. La herrería no solo consiste en golpear el metal. Se trata de obligarlo a que se ciña a tu voluntad. Se trata de escuchar al espíritu que vive en el acero y guiarlo para que adquiera la forma que sabes que quiere alcanzar.' WHERE `ID`=3954;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 지식을 갈구하는 자로 보이는군. 가열로와 망치 다루는 법을 배우고 싶은 것이겠지. 대장장이의 길을 걸어가는 데 내가 도움을 줄 수 있을 것 같소. 하지만 먼저 영혼의 존재를 인정하고 그 부름에 귀를 기울여야 하오.', `MaleText_loc4`='你似乎正在寻求知识。也许你在找寻锻造之道，也许我能在这条道路上指引你。但是一旦你决定从事铁匠这个职业，你就应该学会聆听钢铁中的那些灵魂的呼喊。', `MaleText_loc5`='你似乎正在尋求知識。也許你在找尋鍛造之道，也許我能在這條道路上指引你。但是一旦你決定從事鐵匠這個職業，你就應該學會聆聽鋼鐵中的那些靈魂的呼喊。', `MaleText_loc7`='Pareces $ghombre:mujer; con sed de conocimiento. Quizás busques la enseñanza de la forja, así como del martillo. Tal vez yo pueda ayudarte a recorrer ese camino. Pero solo cuando hayas aceptado a los espíritus y hayas escuchado su llamada.' WHERE `ID`=3955;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오그리마로 가서 명예의 골짜기에 있는 그를 찾으시오. 그는 전설의 무기점이라는 가게에서 일하고 있소.', `MaleText_loc4`='到奥格瑞玛的荣誉谷去找他。他在那里有一家名叫“传说中的装备”的小店。', `MaleText_loc5`='到奧格瑪的榮譽谷去找他。他在那裡有一家名叫「傳說中的裝備」的小店。', `MaleText_loc7`='Viaja hasta Orgrimmar y búscalo en el Valle del Honor. Trabaja en una tienda llamada Armas de Leyenda.' WHERE `ID`=3956;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 훌륭한 무기로군. 당신처럼 영혼을 잘 인도하는 사람은 본 적이 없소. 그들의 소리에 귀를 기울이시오. 당신이 그들을 인도한 대로 그들도 당신을 인도할 거요. 가서 켈그룩 블러드액스라는 이름의 오크를 찾아보시오. 영혼들에게 말을 걸지는 못하지만 들을 줄은 알고, 그가 만든 무기는 내가 본 것들 중 최고였소.', `MaleText_loc4`='$n，你制作的这件武器确实很不错。你对指引钢铁灵魂的方法也已经非常精通了。聆听它们的呼声，它们就会像你指引它们一样指引你。去吧，去找那个名叫克尔格鲁克·血斧的兽人。他没有和钢铁的灵魂交谈过，但是他很善于倾听，他制作的武器是我见过的最好的武器。', `MaleText_loc5`='$n，你製作的這件武器確實很不錯。你對指引鋼鐵靈魂的方法也已經非常精通了。聆聽它們的呼聲，它們就會像你指引它們一樣指引你。去吧，去找那個名叫克爾格魯克·血斧的獸人。他沒有和鋼鐵的靈魂交談過，但是他很善於傾聽，他製作的武器是我見過的最好的武器。', `MaleText_loc7`='Ciertamente, se trata de un arma excelente, $n. Guías a los espíritus como nadie que yo conozca. Escúchalos y ellos te guiarán como los has guiado. Ve a buscar al orco conocido como Kelgruk Hacha de Sangre. No habla con los espíritus, pero sí los escucha, y sus armas son las mejores que jamás he visto.' WHERE `ID`=3957;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명예의 골짜기에서 그녀와 그녀의 일족을 만날 수 있을 테니 오그리마로 가게.', `MaleText_loc4`='到奥格瑞玛去，你可以在荣誉谷找到她和她的家人。', `MaleText_loc5`='到奧格瑪去，你可以在榮譽谷找到她和她的家人。', `MaleText_loc7`='Ve a Orgrimmar. Allí la encontrarás y a los de su especie en el Valle del Honor.' WHERE `ID`=3958;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 자네가 만드는 방어구라면 아무리 날카로운 도끼날이라도 모두 받아 낼 수 있을 거야. 흔하게 볼 수 있는 솜씨가 아니라 정말 놀랍군. 샤이스 스틸퓨리라는 오크를 찾아가 보게. 지금 천벌이나 받을 드워프들의 요새 바깥에 머물고 있지만, 방어구 하나는 최고로 훌륭하지.', `MaleText_loc4`='你所锻造的护甲能够抵挡最锋利的刀刃。$n你给我留下了深刻的印象，这可不容易。去找一个名叫莎伊斯·钢怒的兽人吧，她是除了那些该死的矮人之外最好的铸甲匠。', `MaleText_loc5`='你所鍛造的護甲能夠抵擋最鋒利的刀刃。$n你給我留下了深刻的印象，這可不容易。去找一個名叫莎伊斯·鋼怒的獸人吧，她是除了那些該死的矮人之外最好的鑄甲匠。', `MaleText_loc7`='Una armadura como la que fabricas podría detener el impacto del hacha más afilada. Me impresionas, $n, esto no ocurre a menudo. Busca a una orco llamada Shayis Furiacerada. Ella fabrica las mejores armaduras fuera de esta maldita fortaleza de enanos.' WHERE `ID`=3959;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 만드는 검날이 적의 복부를 꿰뚫기에 부족함이 없겠나? 무기의 날을 더욱 날카롭게 다듬는 법을 가르쳐주지.', `MaleText_loc4`='你铸造的武器怎么样？你认为它能轻易击败敌人吗？让我来告诉你如何把它变得更加锋利吧。', `MaleText_loc5`='你鑄造的武器怎麼樣?你認為它能輕易斬下敵人的頭顱嗎?讓我來告訴你如何把它變得更加鋒利吧。', `MaleText_loc7`='¿Cómo está el filo de tu espada? ¿Aún puede cortar la barriga de tus enemigos? Deja que te enseñe algunas cosas para que tenga aún mayor filo.' WHERE `ID`=3960;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대장장이가 되고 싶나? 단숨에 적을 가를 만큼 날카로운 검을 만들고 싶은가? 살짝 대기만 해도 목표물을 완전히 부숴 버릴 망치를 만들고 싶은 게로군. 도와주지. 그 무기로 갚아야 할 원한이 있다면 더더욱!', `MaleText_loc4`='想要成为一名铁匠？想要锻造出最好的武器？我可以帮你，希望你能对这门手艺投入最大的热情。', `MaleText_loc5`='想要成為一名鐵匠?想要鍛造出最好的武器?我可以幫你，希望你能對這門手藝投入最大的熱情。', `MaleText_loc7`='¿Quieres ser un herrero? ¿Quieres fabricar hojas de espada para destripar a tu enemigo? ¿Quieres martillos para partirle el cráneo? Pues yo puedo ayudarte, y con gusto si se trata de derramar sangre con ellos.' WHERE `ID`=3961;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오크의 도시, 오그리마로 가게. 명예의 골짜기에 전설의 무기점이라는 곳이 있다네. 그곳에서 그를 찾아보도록 하게.', `MaleText_loc4`='到兽人城市奥格瑞玛去，他就在荣誉谷的“传说中的装备”那家店里。', `MaleText_loc5`='到獸人城市奧格瑪去，他就在榮譽谷的「傳說中的裝備」那家店裡。', `MaleText_loc7`='Ve a la ciudad orca de Orgrimmar, búscale en el Valle del Honor, en una tienda llamada Armas de Leyenda.' WHERE `ID`=3962;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 아주 날카로운 검을 만들 줄 아는군. 바위라도 베어낼 수 있을 정도로 날카로운... 하지만 그보다 더 나은 것들을 본 적이 있다네. 바로 켈그룩 블러드액스라는 오크가 만든 것. 가서 그가 가르쳐 주는 건 모두 배우도록.', `MaleText_loc4`='$n，你铸造的武器很不错，已经达到切金断玉的水准了。但是我还认识比你的技艺更加精湛的铁匠，那是一个名叫克尔格鲁克·血斧的兽人，去找他继续学习吧！', `MaleText_loc5`='$n，你鑄造的武器很不錯，已經達到切金斷玉的水準了。但是我還認識比你的技藝更加精湛的鐵匠，那是一個名叫克爾格魯克·血斧的獸人，去找他繼續學習吧!', `MaleText_loc7`='Haces buenas espadas, $n. Parten una piedra y siguen tan afiladas como para cortar una garganta. Aunque he visto cosas mejores, un orco llamado Kelgrum Sangracha las hace, ve con él y aprende todo lo que pueda enseñarte.' WHERE `ID`=3963;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n! 그동안 어떻게 지냈나? 지난번 만났을 때 이후 얼마나 많이 배웠는지 한번 보세. 자네에게 내가 더 가르쳐 줄 것이 있을지 생각해 봐야겠어.', `MaleText_loc4`='$n！真高兴再见到你！让我看看自从上次见面到现在你都学了点什么本事，没准我还能再教你些东西。', `MaleText_loc5`='$n!真高興再見到你!讓我看看自從上次見面到現在你都學了點什麼本事，說不定還能再教你些東西。', `MaleText_loc7`='¡$n! ¿Cómo has estado, $gmuchacho:muchacha;? Muéstrame lo que te enseñé la última vez que te vi. Veremos si hay algo nuevo que pueda enseñarte.' WHERE `ID`=3964;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대용광로에 또 왔군, $n. 반갑소. 이 늙은 드워프를 보러 온 건가, 아니면 다음 훈련을 받을 준비가 되어서 온 것이오?', `MaleText_loc4`='$n，欢迎回到大锻炉。你是来拜访我的，还是准备进行下一阶段的训练？', `MaleText_loc5`='$n，歡迎回到大鍛爐。你是來拜訪我的，還是準備進行下一階段的訓練?', `MaleText_loc7`='Te doy la bienvenida nuevamente a la Gran Fundición, $n. ¿Vienes a visitar a un viejo enano o crees que ya puedes continuar con el siguiente nivel de tu instrucción?' WHERE `ID`=3979;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋은 강철이군, $n. 망치를 들고 이리 와 보게. 전설의 무기를 만드는 비법을 가르쳐 줄 테니까.', `MaleText_loc4`='$n，这些金属真不错。拿把铁锤过来，让我指导你如何锻造一把绝世的利器。', `MaleText_loc5`='$n，這些金屬真不錯。拿把鐵錘過來，讓我指導你如何鍛造一把絕世的利器。', `MaleText_loc7`='Buen acero, $n. Coge un martillo y ven aquí, déjame enseñarte los secretos de la forja de un arma legendaria.' WHERE `ID`=3980;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 배우러 온 건가, $n? 더 가까이 와보게. 준비가 되었나 보겠어.', `MaleText_loc4`='$n，你是回来学更多东西的吗？那么当你准备好的时候，我们就继续吧。', `MaleText_loc5`='$n，你是回來學更多東西的嗎?那麼當你準備好的時候，我們就繼續吧。', `MaleText_loc7`='¿Has vuelto para aprender más cosas, $n? Ven aquí y demuéstrame que estás $glisto:lista;.' WHERE `ID`=3981;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일인가? 지금은 일하느라 조금 바쁜데.', `MaleText_loc4`='什么事？你没有看到我很忙吗？', `MaleText_loc5`='什麼事?你沒有看到我很忙嗎?', `MaleText_loc7`='¿Qué pasa? ¿No ves que estoy ocupado?' WHERE `ID`=3982;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭔가? 일하느라 바쁜 거 모르겠나?', `MaleText_loc4`='什么事？你没有看到我很忙吗？', `MaleText_loc5`='什麼事?你沒有看到我很忙嗎?', `MaleText_loc7`='¿Qué pasa? ¿No ves que estoy ocupado?' WHERE `ID`=3983;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여행은 어땠나요, $n? $g수미와 투미가 당신을 보고 싶어 했어요. 다 배우면 가서 인사라도 나누세요:당신의 모험 얘기를 전해 들었어요. 꽤 바쁜 나날을 보낸 것 같더군요;. 자, 이곳을 떠나 있던 동안 뭘 배웠는지 한번 볼까요?', `FemaleText_loc4`='$n，你的旅行怎么样？$g苏米和图米都很想念你，在你结束训练之后应该去拜访他们:我听说了一些关于你的故事，你似乎一直都很忙;。现在让我们来看看在你离开的这段时间里，你都学了些什么。', `FemaleText_loc5`='$n，你的旅行怎麼樣?$g蘇米和圖米都很想念你，在你結束訓練之後應該去拜訪他們:我聽說了一些關於你的故事，你似乎一直都很忙;。現在讓我們來看看在你離開的這段時間裡，你都學了些什麼。', `FemaleText_loc7`='¿Qué tal tus viajes, $n? Sumi y Tumi te han echado de menos, deberías saludarlas después de la lección. He escuchado historias relatando tus aventuras. Al parecer, has estado ocupado. Veamos qué has aprendido durante tu ausencia.' WHERE `ID`=3984;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무슨 일이죠? 지금 완성해야 할 가슴보호갑이 있으니까 시간 낭비는 아니었으면 좋겠는데요.', `FemaleText_loc4`='什么事？我正好在制作一件护胸甲，没要紧事就别打扰我。', `FemaleText_loc5`='什麼事?我正好在製作一件胸甲甲，沒要緊事就別打擾我。', `FemaleText_loc7`='¿Sí? Tengo que terminar un peto, así que será mejor que sea bueno lo que tienes que decirme.' WHERE `ID`=3985;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='재능이 있군요, $n. 자, 연습이 많이 필요하니 망치와 그 조각들을 좀 가지고 오세요.', `FemaleText_loc4`='$n，我已经看到了你的潜力。现在拿上锤子准备开工吧，你需要大量的练习才能提高自己的水平。', `FemaleText_loc5`='$n，我已經看到了你的潛力。現在拿上錘子準備開工吧，你需要大量的練習才能提高自己的水準。', `FemaleText_loc7`='Veo que tienes potencial, $n. Ahora coge un y algunos restos de metal, ya que tienes que practicar mucho.' WHERE `ID`=3986;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='난 실력이 없는 대장장이들은 훈련시키지 않는답니다. 쓸 만한 물건을 만들 실력을 갖췄다 싶을 때 다시 오도록 하세요.', `FemaleText_loc4`='我不会训练一点水平都没有的铁匠，等你觉得自己达到我的要求之后再回来找我。', `FemaleText_loc5`='我不會訓練一點水準都沒有的鐵匠，等你覺得自己達到我的要求之後再回來找我。', `FemaleText_loc7`='No instruyo a herreros primerizos. Regresa cuando tengas algo decente que mostrarme.' WHERE `ID`=3987;
