UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좀비라던가, 일꾼이라고 하던가...? 어쨌든 그런 놈들을 상대한다고 해서 클라벤이 보수를 넉넉히 주는 것도 아니고.', `MaleText_loc4`='克拉文付我的钱可不够让我卖命去对付僵尸之类的东西。', `MaleText_loc5`='克拉文付我的錢可不夠讓我賣命去對付殭屍之類的東西。', `MaleText_loc7`='Klaven no me paga lo suficiente como para tratar con zombis, esclavos autómatas o entes similares.', `FemaleText_loc1`='좀비라던가, 일꾼이라고 하던가...? 어쨌든 그런 놈들을 상대한다고 해서 클라벤이 보수를 넉넉히 주는 것도 아니고.', `FemaleText_loc4`='克拉文付我的钱可不够让我卖命去对付僵尸之类的东西。', `FemaleText_loc5`='克拉文付我的錢可不夠讓我賣命去對付殭屍之類的東西。', `FemaleText_loc7`='Klaven no me paga lo suficiente como para tratar con zombis, esclavos autómatas o entes similares.' WHERE `ID`=4018;
