UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자, $n. 둘러보도록 하세요. 아마 그대라면 제가 놓쳐 버린 것을 찾을 수 있을지도 모르겠군요.', `FemaleText_loc4`='去四周看看，$n。也许你能找到一些我忽略掉的东西。', `FemaleText_loc5`='去四周看看，$n。也許你能找到一些我忽略掉的東西。', `FemaleText_loc7`='Echa un vistazo por aquí, $n. Tal vez encuentres algo que yo no haya advertido.' WHERE `ID`=4042;
