UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잠깐만요, $n. 킨달이 저 아래 그림토템 야영지에서 요정용을 풀어주려고 하고 있어요. 제때 도움을 받을 수 있어서 다행이었어요. 저 악독한 타우렌 녀석들이 무슨 짓을 했을지 어떻게 알겠어요?', `FemaleText_loc4`='请等一下，$n。辛达尔在想办法把精灵龙从恐怖图腾营地中救出来。我们正巧路过这里，谁知道那些邪恶的牛头人对它们做了些什么。', `FemaleText_loc5`='請等一下，$n。辛達爾在想辦法把精靈龍從恐怖圖騰營地中救出來。我們正巧路過這裡，誰知道那些邪惡的牛頭人對它們做了些什麼。', `FemaleText_loc7`='Un momento, $n. Kindal está en el campamento de los Tótem Siniestro intentando liberar a los dragones fantásticos de su cautiverio. Tuvimos suerte de recibir ayuda en el momento oportuno. Quién sabe lo que esos malditos tauren les habrán hecho.' WHERE `ID`=4045;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런! 붙잡힌 화살요정용들이 빠져 나오지 못했어요. 어떡하죠?', `FemaleText_loc4`='啊！那些精灵龙没能逃脱，我们该怎么办？', `FemaleText_loc5`='啊!那些精靈龍沒能逃脫，我們該怎麼辦?', `FemaleText_loc7`='¡Ay! Los duendecillos lanzadores de dardos que habían sido capturados no sobrevivieron. ¿Qué haremos?' WHERE `ID`=4046;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='됐어요! 드디어 해냈군요! 붙잡힌 화살요정용들이 빠져 나왔어요!', `FemaleText_loc4`='太好了！精灵龙都逃脱了！我们成功了！', `FemaleText_loc5`='太好了!精靈龍都逃脫了!我們成功了!', `FemaleText_loc7`='¡Sí! ¡Lo han conseguido! ¡Los duendecillos lanzadores de dardos que habían sido capturados lo han conseguido!' WHERE `ID`=4047;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주요 상호 작용이 완료되었습니다. 앞으로 10분 안에 제 형상은 소멸하게 됩니다.', `MaleText_loc4`='主要交互完成。图像将在十分钟内消失。', `MaleText_loc5`='主要交互完成。圖像將在十分鐘內消失。', `MaleText_loc7`='Interacción principal terminada. Disipación de imagen en diez minutos.' WHERE `ID`=4048;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까! 저는 입구를 지키는 문지기입니다. 올바른 원반을 사용해야 울둠에 들어갈 수 있습니다.', `MaleText_loc4`='向你致敬！我是这个入口的守卫。请使用正确的圆盘进入奥丹姆。', `MaleText_loc5`='向你致敬!我是這個入口的守護者。請使用正確的圓盤進入奧丹姆。', `MaleText_loc7`='¡Saludos! Soy un guardián de la entrada. Usa los discos adecuados para acceder a Uldum.' WHERE `ID`=4049;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 도와주시면 이 지하도를 좀 살펴볼 수 있겠는데요.', `FemaleText_loc4`='有了你的帮助，我就可以测量这些通道了。', `FemaleText_loc5`='有了你的幫助，我就可以評估這些通道了。', `FemaleText_loc7`='Con tu ayuda, podré evaluar estos túneles.' WHERE `ID`=4050;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='트로그 녀석들이 어디서 들어오는 건지 한번 알아보죠. 더 이상 침략하지 못하게 끝장을 내야겠어요!', `FemaleText_loc4`='让我们看看能否发现这些穴居人是从哪里来的……然后想办法阻止他们！', `FemaleText_loc5`='讓我們看看能否發現這些穴居怪是從哪裡來的...然後想辦法阻止牠們!', `FemaleText_loc7`='Veamos si podemos descubrir de dónde vienen estos troggs... ¡y detener esta invasión!' WHERE `ID`=4051;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='완전히 폐허로군요... 이런 난장판이 또 있을까...', `FemaleText_loc4`='太混乱了……简直一团糟……', `FemaleText_loc5`='太混亂了...簡直一團糟...', `FemaleText_loc7`='Qué devastación... qué desastre espantoso...' WHERE `ID`=4052;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까. 저는 입구를 지키는 문지기입니다. 원반 세트에 울둠의 원반을 결합하지 않으면 울둠으로 들어갈 수 없습니다.', `MaleText_loc4`='向你致敬。我是这个入口的守卫。除非你的圆盘中包括奥丹姆圆盘，否则我是不会让你进入奥丹姆的。', `MaleText_loc5`='向你致敬。我是這個入口的守護者。除非你的圓盤中包括奧丹姆圓盤，否則我是不會讓你進入奧丹姆的。', `MaleText_loc7`='Saludos. Soy un guardián de la entrada. A menos que tengas las placas de Uldum integradas en tus discos, no estás $gautorizado:autorizada; para entrar en el dominio de Uldum.' WHERE `ID`=4053;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 역할은 무엇입니까?', `MaleText_loc4`='你的职责是什么？', `MaleText_loc5`='你的職責是什麼?', `MaleText_loc7`='¿Cuál es tu función?', `FemaleText_loc1`='당신의 역할은 무엇입니까?', `FemaleText_loc4`='你的职责是什么？', `FemaleText_loc5`='你的職責是什麼?', `FemaleText_loc7`='¿Cuál es tu función?' WHERE `ID`=4054;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 임무는 창조주를 위해 울둠 단지의 출입을 통제하는 것입니다. 이 문을 두드리는 자에게 적합한 원반 세트가 있을 때만 출입이 허가됩니다.$B$B현재 당신의 원반 세트에는 울둠의 원반이 포함되어 있지 않습니다. 울둠의 원반이 없으면 출입이 허가되지 않습니다.', `MaleText_loc4`='我的职责是为造物者守卫奥丹姆的入口。只有拥有正确的圆盘才能进入其中。$B$B你的圆盘中没有包含奥丹姆圆盘，所以你不具备进入奥丹姆的基本条件。除非奥丹姆圆盘存在，否则你无法进入。', `MaleText_loc5`='我的職責是為造物者守衛奧丹姆的入口。只有擁有正確的圓盤才能進入其中。$B$B你的圓盤中沒有包含奧丹姆圓盤，所以你不具備進入奧丹姆的基本條件。除非奧丹姆圓盤存在，否則你無法進入。', `MaleText_loc7`='Mi propósito es regular el acceso al dominio de Uldum en servicio de los Creadores. Permito la entrada a este dominio cuando el aspirante muestra los discos de acceso en la secuencia adecuada.$B$BTu conjunto de discos no incluye las placas de Uldum, requisito principal para entrar. No se permite el acceso a menos que las placas de Uldum estén presentes.' WHERE `ID`=4055;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='울둠의 원반이란 무엇입니까?', `MaleText_loc4`='什么是奥丹姆圆盘？', `MaleText_loc5`='什麼是奧丹姆圓盤?', `MaleText_loc7`='¿Qué son las placas de Uldum?', `FemaleText_loc1`='울둠의 원반이란 무엇입니까?', `FemaleText_loc4`='什么是奥丹姆圆盘？', `FemaleText_loc5`='什麼是奧丹姆圓盤?', `FemaleText_loc7`='¿Qué son las placas de Uldum?' WHERE `ID`=4056;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='울둠의 원반은 어디에 있습니까?', `MaleText_loc4`='奥丹姆圆盘在哪里？', `MaleText_loc5`='奧丹姆圓盤在哪裡?', `MaleText_loc7`='¿Dónde están las placas de Uldum?', `FemaleText_loc1`='울둠의 원반은 어디에 있습니까?', `FemaleText_loc4`='奥丹姆圆盘在哪里？', `FemaleText_loc5`='奧丹姆圓盤在哪裡?', `FemaleText_loc7`='¿Dónde están las placas de Uldum?' WHERE `ID`=4057;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네? "방문 일정 변경"이라고요? 그게 무슨 뜻입니까?!', `MaleText_loc4`='什么？我们的世界“被安排了新的探访计划”？这是什么意思？！', `MaleText_loc5`='什麼?我們的世界「被安排了新的探訪計畫」?這是什麼意思?!', `MaleText_loc7`='¿Dime? Nos han reprogramado para la aparición"? ¡¿Eso qué quiere decir?!"', `FemaleText_loc1`='네? "방문 일정 변경"이라고요? 그게 무슨 뜻입니까?!', `FemaleText_loc4`='什么？我们的世界“被安排了新的探访计划”？这是什么意思？！', `FemaleText_loc5`='什麼?我們的世界「被安排了新的探訪計畫」?這是什麼意思?!', `FemaleText_loc7`='¿Dime? Nos han reprogramado para la aparición"? ¡¿Eso qué quiere decir?!"' WHERE `ID`=4058;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇다면... 울둠 안에는 무엇이 있습니까?', `MaleText_loc4`='那么……奥丹姆里面到底有些什么？', `MaleText_loc5`='那麼...奧丹姆裡面到底有些什麼?', `MaleText_loc7`='Y bien... ¿qué hay en el interior de Uldum?', `FemaleText_loc1`='그렇다면... 울둠 안에는 무엇이 있습니까?', `FemaleText_loc4`='那么……奥丹姆里面到底有些什么？', `FemaleText_loc5`='那麼...奧丹姆裡面到底有些什麼?', `FemaleText_loc7`='Y bien... ¿qué hay en el interior de Uldum?' WHERE `ID`=4059;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='울둠의 원반이 있을 때 다시 오겠습니다.', `MaleText_loc4`='我找到奥丹姆圆盘之后会回来的。', `MaleText_loc5`='我找到奧丹姆圓盤之後會回來的。', `MaleText_loc7`='Regresaré cuando tenga las placas de Uldum.', `FemaleText_loc1`='울둠의 원반이 있을 때 다시 오겠습니다.', `FemaleText_loc4`='我找到奥丹姆圆盘之后会回来的。', `FemaleText_loc5`='我找到奧丹姆圓盤之後會回來的。', `FemaleText_loc7`='Regresaré cuando tenga las placas de Uldum.' WHERE `ID`=4060;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='울둠의 원반이란 울둠 단지의 출입을 허가하기 위해 창조주가 만들어낸 것입니다. 이 원반에는 이 안에서 진행되는 창조주의 활동과 관련된 자세한 자료가 저장되어 있습니다.$B$B겉모양이나 크기는 지금 당신이 가지고 있는 원반 세트와 거의 동일하지만 울둠의 원반에 있는 표식들은 울다만이 아닌 울둠에 관한 정보와 직접적인 관련이 있습니다.', `MaleText_loc4`='拥有奥丹姆圆盘才能够进入奥丹姆。这些圆盘中储存了造物者在这里的所有活动的纪录。$B$B从组成上来看，这些圆盘各不相同。它们的标注则只和奥丹姆信息相关，与奥达曼圆盘截然不同。', `MaleText_loc5`='擁有奧丹姆圓盤才能夠進入奧丹姆。這些圓盤中儲存了造物者在這裡的所有活動的紀錄。$B$B從組成上來看，這些圓盤各不相同。它們的標注則只和奧丹姆資訊相關，與奧達曼圓盤截然不同。', `MaleText_loc7`='Las placas de Uldum son discos sintetizados por los Creadores que permiten el acceso al dominio de Uldum. Estos discos almacenan datos específicos relacionados con las actividades de los Creadores en este lugar.$B$BFísicamente, son casi idénticos en circunferencia al conjunto de discos que posees en estos momentos. No obstante, sus marcas contienen datos directamente relacionados con Uldum, a diferencia del complejo de Uldaman.' WHERE `ID`=4061;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='창조주들은 자신들이 사용할 목적으로 울둠의 원반을 여러 개 만들어두었습니다. 원반을 세계 각지에 배포하는 건 그들의 일입니다. 아제로스 방문 일정이 변경되었고 결과적으로 그때 원반이 추가로 배포될 수 있는 것입니다.$B$B기존 원반은 보안 권한이 있는 자들에게 이미 모두 배포된 상태입니다.', `MaleText_loc4`='造物者制造了若干张奥丹姆圆盘以供使用。他们控制着向整个世界分配奥丹姆圆盘的工作。同样，艾泽拉斯已经被安排了新的探访计划，到那时，未来的奥丹姆圆盘也许会重新开始流通。$B$B现有的奥丹姆圆盘已经被全部分给了具有一定忠诚度的种族。', `MaleText_loc5`='造物者製造了若干張奧丹姆圓盤以供使用。他們控制著向整個世界分配奧丹姆圓盤的工作。同樣，艾澤拉斯已經被安排了新的探訪計畫，到那時，未來的奧丹姆圓盤也許會重新開始流通。$B$B現有的奧丹姆圓盤已經被全部分給了具有一定忠誠度的種族。', `MaleText_loc7`='Numerosos conjuntos de placas de Uldum han sido sintetizados por los Creadores para un uso específico. Los Creadores controlan la distribución de dichos discos para todos los dominios de este mundo. Por su parte, Azeroth ha sido reprogramado para la aparición de los Creadores y, por esta razón, ese momento será cuando los discos del futuro entren en circulación.$B$BLos discos existentes se han distribuido ampliamente entre aquellos que disponen de la autorización debida.' WHERE `ID`=4062;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내부와 외부의 세력이 세계의 원동력을 파괴하면 창조주들은 이 세계를 방문해 그들이 씨를 뿌린 세계에 대한 지배력을 회복하려고 할 것입니다. 이때를 가볍게 보고 넘겨서는 안 됩니다.$B$B이 세계의 방문 예정에 관한 정보는 해당 자료 저장소를 찾아보시기 바랍니다. 이곳에서 창조주의 방문 일정을 계획할 때 고려하는 사항이 처리되고 있습니다.', `MaleText_loc4`='当外部势力和内部势力相互冲突，以至于扰乱整个世界的时候，造物者将探访计划作为重新控制世界的手段，不过执行这样的策略并不容易。$B$B关于预先安排的探访计划的更多信息，请查询所有与造物者相关的数据库。', `MaleText_loc5`='當外部勢力和內部勢力相互衝突，以至於擾亂整個世界的時候，造物者將探訪計畫作為重新控制世界的手段，不過執行這樣的策略並不容易。$B$B關於預先安排的探訪計畫的更多資訊，請查詢所有與造物者相關的資料庫。', `MaleText_loc7`='Los Creadores utilizan la aparición como medio para restablecer el control sobre los mundos creados cada vez que las fuerzas, tanto externas como internas, desestabilizan la dinámica de la matriz relacionada con ellos. Dichas tácticas no deben subestimarse cuando las ejecutan los Creadores.$B$BPara obtener información adicional sobre la aparición programada para este mundo, consulta el banco de datos adecuado que contiene todas las consideraciones de planificación relacionadas con los Creadores.' WHERE `ID`=4063;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='울둠은 창조주의 연구 시설로서 아제로스의 생활 수준을 향상시키기 위한 노력의 일환으로 만들어졌습니다. 울둠의 작업에 대한 자세한 내용은 울둠의 원반이 있는 분에게만 공개하도록 제한되어 있습니다.$B$B울둠 내 정보 저장소는 특수한 실험 결과를 처리하도록 프로그램되어 있습니다. 자세한 내용은 이 정보 저장소를 참조하시기 바랍니다.', `MaleText_loc4`='奥丹姆是一座为维系艾泽拉斯的自然体系而建造的研究工厂。只有那些拥有奥丹姆圆盘的人知道创世者在奥丹姆所进行的研究工作的详细情况。$B$B奥丹姆中的数据库被用于进行特殊的试验和数据编辑，更多详细信息，请查询数据库。', `MaleText_loc5`='奧丹姆是一座為維繫艾澤拉斯的自然體系而建造的研究工廠。只有那些擁有奧丹姆圓盤的人知道創世者在奧丹姆所進行的研究工作的詳細情況。$B$B奧丹姆中的資料庫被用於進行特殊的試驗和資料編輯，更多詳細資訊，請查詢資料庫。', `MaleText_loc7`='Uldum es un complejo de investigación para los Creadores en sus esfuerzos constantes de mejorar la biosfera de Azeroth. La información específica relacionada con su trabajo y, en concreto, con Uldum, se restringe a aquellos individuos que poseen las placas de Uldum en sus conjuntos de discos.$B$BLos bancos de datos guardados en el dominio de Uldum han sido programados para abordar experimentos específicos y compilaciones de datos determinadas. Consúltalos para obtener información detallada.' WHERE `ID`=4064;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대좌를 건드리시면 원반을 되돌려 드리겠습니다.', `MaleText_loc4`='当你再次触碰底座的时候，圆盘会重新回到你的手中。', `MaleText_loc5`='當你再次觸碰底座的時候，圓盤會重新回到你的手中。', `MaleText_loc7`='Los discos te serán devueltos una vez que accedas al pedestal.' WHERE `ID`=4065;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='난 준비 됐어요, $n 님. 앞장 서세요!', `FemaleText_loc4`='$n，我准备好了。带路吧！', `FemaleText_loc5`='$n，我準備好了。帶路吧!', `FemaleText_loc7`='Estoy listo. Cuando tú digas, $n. ¡Guíame!' WHERE `ID`=4079;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='해냈군요! 그림토템 야영지 위에 있는 제르카이 옆에서 다시 만나요.', `FemaleText_loc4`='我们成功了！到恐怖图腾营地外面去跟我和耶尔卡会合吧。', `FemaleText_loc5`='我們成功了!到恐怖圖騰營地外面去跟我和耶爾卡會合吧。', `FemaleText_loc7`='¡Lo hemos conseguido! Nos vemos junto a Jer''kai, cerca del campamento del Tótem Siniestro.' WHERE `ID`=4080;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런! 요정용들이 빠져 나가지 못할 것 같아요, $n! 나는 제르카이에게 돌아가서 들키지 않았는지 확인해야겠어요. 엘룬이 함께하시길.', `FemaleText_loc4`='不！精灵龙没能逃脱出来，$n！我必须回到耶尔卡那里去，以确保她没有被发现。愿艾露恩与你同在。', `FemaleText_loc5`='不!精靈龍沒能逃脫出來，$n!我必須回到耶爾卡那裡去，以確保她沒有被發現。願伊露恩與你同在。', `FemaleText_loc7`='¡No! ¡Los dragones fantásticos no lo están consiguiendo, $n! Debo regresar a Jer''kai para asegurarme de que no la han encontrado. Que Elune esté contigo.' WHERE `ID`=4081;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='와줘서 정말 고마워요! 지금은 머리가 둘 달린 오우거에게라도 도움을 받고 싶은 심정이에요.

도시가 트로그에게 점령당했어요! 녀석들을 몰아내려다가 심하게 오염돼 버렸지만 아직 희망은 있어요.

아이언포지로 피신한 우리 과학자들이 지금 방사성 질병 치료제를 연구하고 있어요. 그동안 당신이 트로그의 침략을 막을 수 있도록 도와준다면 도시를 되찾을 수 있을지도 몰라요.', `FemaleText_loc4`='感谢圣光！现在情况十分紧急，即使有一个双头食人魔愿意施以援手，我也会欣然接受的。

这座城市里到处都是穴居人！为了把它们赶出这里，我们采取了一些行动，但是却导致这一地区遭受了大面积的污染。幸好我们还有希望！

我们疏散到铁炉堡的科学家正在研究对付辐射疾病的方法。同时，如果你能帮我阻止穴居人的入侵，那也许我们就能够夺回我们的城市！', `FemaleText_loc5`='感謝聖光!現在情況十分緊急，即使有一個雙頭巨魔願意施以援手，我也會欣然接受的。

這座城市裡到處都是穴居怪!為了把它們趕出這裡，我們採取了一些行動，但是卻導致這一地區遭受了大面積的污染。幸好我們還有希望!

我們疏散到鐵爐堡的科學家正在研究對付輻射疾病的方法。同時，如果你能幫我阻止穴居怪的入侵，那也許我們就能夠奪回我們的城市!', `FemaleText_loc7`='¡Gracias a la Luz que estás aquí! En estos momentos aceptaría ayuda de un ogro de dos cabezas.

¡La ciudad está invadida por troggs! Los intentos por eliminarlos provocó una contaminación masiva. Pero hay esperanzas.

Nuestros científicos que fueron evacuados a Forjaz están trabajando en curar las enfermedades producidas por la lluvia radiactiva. Mientras tanto, si puedes ayudarme a detener la invasión de los troggs, quizás entonces podamos recuperar la ciudad.' WHERE `ID`=4083;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시작할 준비가 되었습니다.', `MaleText_loc4`='我准备好了。', `MaleText_loc5`='我準備好了。', `MaleText_loc7`='Estoy listo para empezar.', `FemaleText_loc1`='시작할 준비가 되었습니다.', `FemaleText_loc4`='我准备好了。', `FemaleText_loc5`='我準備好了。', `FemaleText_loc7`='Estoy lista para empezar.' WHERE `ID`=4084;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='몇 분만 시간을 주십시오. 조금 전 여기서 소동이 있었는데 이제는 좀 잠잠해졌는지 확인해보고 싶군요. 곧 다시 얘기를 하도록 하지요.', `MaleText_loc4`='$n，给我几分钟时间。这里刚刚发生了一些事情，我要去确定一切都已经搞定了。我会马上会来继续和你谈谈的。', `MaleText_loc5`='$n，給我幾分鐘時間。這裡剛剛發生了一些事情，我要去確定一切都已經搞定了。我會馬上會來繼續和你談談的。', `MaleText_loc7`='Dame un par de minutos, $n. Hace un momento, todos estaban muy alterados por aquí. Solo quiero asegurarme de que la calma ha vuelto. Pronto hablaremos.' WHERE `ID`=4102;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='서둘러요! $n|1이;가; 공격해 와요!', `FemaleText_loc4`='快点！$n来了！', `FemaleText_loc5`='快點!$n來了!', `FemaleText_loc7`='¡Rápido! ¡$n, ataca!' WHERE `ID`=4122;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='죽어라, $n. 엘룬께서 더 이상 그분의 창조물이 해를 입는 것을 보고만 계시지는 않을 것이다!', `FemaleText_loc4`='去死吧，$n。月神不会容忍你再伤害那些她庇护着的生物！', `FemaleText_loc5`='去死吧，$n。伊露恩不會容忍你再傷害那些她庇護著的生物!', `FemaleText_loc7`='Muere, $n. ¡Elune no permitirá que vuelvas a hacer daño a sus criaturas!' WHERE `ID`=4123;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='죽어라, $n. 감히 내 활 솜씨를 만만히 보다니!', `FemaleText_loc4`='去死吧，$n。你怎敢进入我的射程！', `FemaleText_loc5`='去死吧，$n。你怎敢進入我的射程!', `FemaleText_loc7`='Muere, $n. ¿Cómo te atreves a acercarte a mí a tiro de arco?' WHERE `ID`=4124;
