UPDATE `locales_broadcast_text` SET `MaleText_loc1`='점을 치는 동안에는 아무 소리도 내지 말아야 해. 조금만 실수해도 우리 운명이 어찌될지 알 수 없으니...', `MaleText_loc4`='在仪式上要小心谨慎。一不小心就可能导致全盘皆错……', `MaleText_loc5`='在儀式上要小心謹慎。一不小心就可能導致全盤皆錯...', `MaleText_loc7`='No hagas ruido durante el ritual. Un paso en falso podría significar nuestra ruina...' WHERE `ID`=4126;
