UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기는 조용하네요...', `FemaleText_loc4`='这里很安静……', `FemaleText_loc5`='這裡很安靜...', `FemaleText_loc7`='Casi hemos llegado...' WHERE `ID`=4129;
