UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저기! 지하도 벽 쪽을 보세요!', `FemaleText_loc4`='看！在隧道那边！', `FemaleText_loc5`='看!在隧道那邊!', `FemaleText_loc7`='¡Mira! ¡Allí, en la pared del túnel!' WHERE `ID`=4131;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='트로그가 침입했어요! 이 구멍을 폭파시켜 막아버릴 테니 그동안 절 엄호해 주세요!', `FemaleText_loc4`='穴居人过来了！保护我，我要把这个洞炸掉！', `FemaleText_loc5`='穴居怪過來了!保護我，我要把這個洞炸掉!', `FemaleText_loc7`='¡Una incursión de troggs! ¡Defiéndeme mientras tapo el agujero con una explosión!' WHERE `ID`=4132;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='폭약 하나로는 안 되겠어요. 계속 녀석들이 접근하지 못하게 해주세요!', `FemaleText_loc4`='一发炸弹还搞不定，继续保护我！', `FemaleText_loc5`='一發炸藥還搞不定，繼續保護我!', `FemaleText_loc7`='No creo que una carga baste para bloquearlo. ¡Sigue combatiéndolos!' WHERE `ID`=4133;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='폭약이 설치됐어요. 터지기 전에 물러서요!', `FemaleText_loc4`='炸弹安放好了。向后撤，炸弹马上要爆炸了！', `FemaleText_loc5`='炸藥安放好了。向後撤，炸藥馬上要爆炸了!', `FemaleText_loc7`='Las cargas están colocadas. ¡Retrocede antes de que estallen!' WHERE `ID`=4134;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='10초 후 폭발할 거예요!', `FemaleText_loc4`='炸弹将在10秒内爆炸！', `FemaleText_loc5`='炸彈將在10秒內爆炸!', `FemaleText_loc7`='¡Explosión prevista en 10 segundos!' WHERE `ID`=4135;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='5초 남았어요! 지하도에서 나가요! 물러서요!', `FemaleText_loc4`='炸弹将在5秒内爆炸。清理通道！向后撤！', `FemaleText_loc5`='炸彈將在5秒內爆炸。淨空通道!向後撤!', `FemaleText_loc7`='¡Explosión prevista en 5 segundos! ¡Despejad el túnel! ¡Atrás!' WHERE `ID`=4136;
