UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 작별 인사를 하려는 듯이 $n에게 짹짹거립니다.', `FemaleText_loc4`='%s向$n开心地道别。', `FemaleText_loc5`='%s向$n吱吱地道別。', `FemaleText_loc7`='%s se despide de $n con un gorjeo.' WHERE `ID`=4138;
