UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경계 태세를 취하도록. 침략자들이 가까이 왔다.', `MaleText_loc4`='保持阵形——入侵者正在靠近。', `MaleText_loc5`='保持陣形─入侵者正在靠近。', `MaleText_loc7`='Estate en guardia, los intrusos están cerca.', `FemaleText_loc1`='경계 태세를 취하도록. 침략자들이 가까이 왔다.', `FemaleText_loc4`='保持阵形——入侵者正在靠近。', `FemaleText_loc5`='保持陣形─入侵者正在靠近。', `FemaleText_loc7`='Estate en guardia, los intrusos están cerca.' WHERE `ID`=4163;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이젠 됐어! 널 돕는 것도 이젠 진절머리가 난다고. 이제 전장에서 결판을 내야 할 때다!', `MaleText_loc4`='就这么办吧！我实在是厌倦了事事都帮你。我们到战场上去解决问题吧！', `MaleText_loc5`='就這麼辦吧!我實在是厭倦了事事都幫你。我們到戰場上去解決問題吧!', `MaleText_loc7`='¡Eso es! Estoy cansado de ayudarte todo el tiempo a salir. ¡Es hora de poner las cosas claras en el campo de batalla!', `FemaleText_loc1`='이젠 됐어! 널 돕는 것도 이젠 진절머리가 난다고. 이제 전장에서 결판을 내야 할 때다!', `FemaleText_loc4`='就这么办吧！我实在是厌倦了事事都帮你。我们到战场上去解决问题吧！', `FemaleText_loc5`='就這麼辦吧!我實在是厭倦了事事都幫你。我們到戰場上去解決問題吧!', `FemaleText_loc7`='¡Eso es! Estoy cansado de ayudarte todo el tiempo a salir. ¡Es hora de poner las cosas claras en el combate de batalla!' WHERE `ID`=4165;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='점심식사가 도착했단다, 내 귀여운 아이들아. 갈가리 찢어 먹어라!', `MaleText_loc4`='你们的午饭来了，孩子们。把它们全部吃光吧！', `MaleText_loc5`='你們的午飯來了，孩子們。把它們全部吃光吧!', `MaleText_loc7`='Ha llegado el almuerzo, mis bellos niños. ¡Hacedlos añicos!' WHERE `ID`=4166;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='접근: 유전자 역결합 광선', `MaleText_loc4`='获得：退化射线', `MaleText_loc5`='獲得:退化射線', `MaleText_loc7`='Acceso: Rayo Descombobulador', `FemaleText_loc1`='접근: 유전자 역결합 광선', `FemaleText_loc4`='获得：退化射线', `FemaleText_loc5`='獲得:退化射線', `FemaleText_loc7`='Acceso: Rayo Descombobulador' WHERE `ID`=4167;
