UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 재료를 한데 모아 일을 시작합니다.', `MaleText_loc4`='%s收集好材料，开始工作。', `MaleText_loc5`='%s把材料都收集起來，然後開始工作。', `MaleText_loc7`='%s reúne los materiales y comienza a trabajar.' WHERE `ID`=4175;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무기를 다 완성했네, $n.', `MaleText_loc4`='$n，我已经把武器制作完成了。', `MaleText_loc5`='$n，我已經把武器製作完成了。', `MaleText_loc7`='Ya he terminado las armas, $n.' WHERE `ID`=4176;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일어나라... 네 주인을 지켜라!', `MaleText_loc4`='保护你们的主人！', `MaleText_loc5`='保護你們的主人!', `MaleText_loc7`='¡Álzate y defiende a tu maestro!' WHERE `ID`=4177;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='술트라제의 자손들이여, 네 주인을 보호하라. 술리투즈여, 다시 한번 일어나다오!', `MaleText_loc4`='苏利萨斯的子嗣会保护他们的主人……', `MaleText_loc5`='蘇薩斯的子嗣會保護他們的主人...', `MaleText_loc7`='Los hijos de Sul protegerán a su maestro. ¡Álzate otra vez, Sul''lithuz!' WHERE `ID`=4178;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 맞서 싸우는 생물체의 영혼, 즉 "뮤세크"에는 엄청난 힘이 담겨져 있지.$B$B자신을 돌아보고 자신의 고유한 영혼의 힘을 다루는 방법을 익히도록 하게. 그러면 자네는 자네가 상상했던 것 이상의 힘을 갖게 될 것이야.', `MaleText_loc4`='和我们战斗的那些生物的灵魂，或者说“灵魂精华”中存在着不可思议的力量。$B$B看清你的内心；学着驾驭你的灵魂之力吧，你将获得超乎想象的强大力量。', `MaleText_loc5`='和我們戰鬥的那些生物的靈魂，或者說「靈魂精華」中存在著不可思議的力量。$B$B這個地區的許多生物都是夜精靈的盟友，夜精靈可以隨時利用它們的力量。部落也應該享受到同樣的權利，我相信一定有辦法可以掌握這些力量，使其為我們所用。$B$B我說的都是事實，$n。幫助我，你會發現自己獲得了不可思議的力量。', `MaleText_loc7`='Se puede encontrar un increíble poder en los espíritus o "muisek" de las criaturas contra las que luchamos.$B$BMira en tu interior, aprende a canalizar el poder de tu propio espíritu y serás más $gpoderoso:poderosa; de lo que jamás hayas podido imaginar.' WHERE `ID`=4179;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뮤세크 단지가 준비됐네, $n.', `MaleText_loc4`='灵魂精华容器已经准备好了，$n。', `MaleText_loc5`='靈魂精華容器已經準備好了，$n。', `MaleText_loc7`='Las vasijas de muisek están listas, $n.' WHERE `ID`=4180;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 의식을 시작합니다.', `MaleText_loc4`='%s开始进行仪式。', `MaleText_loc5`='%s開始進行儀式。', `MaleText_loc7`='%s inicia el ritual.' WHERE `ID`=4181;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='술트라제... 처음으로 이 말을 들은 게 아마 그대 나이쯤이었을 것입니다. 지금 이 말이 그대에게 아무 의미가 없듯이 그때는 내게도 어떤 의미도 없었지요. 줄파락에서 온 트롤 부대가 이 땅을 파괴한 후에야 그 이름을... 두려워하게 됐습니다.$B$B아마 많은 이들은 고통의 영검 같은 건 존재하지 않는다고 말할 것입니다. 우는 아이를 달래기 위해 만들어낸 이야기라면서 말이지요. 하지만 고통의 영검은 정말로 존재합니다. 저를 믿으십시오.$B$B<갑자기 멍한 표정을 짓더니 얼굴에 난 흉터를 손으로 쓰다듬는 트렌튼>', `MaleText_loc4`='苏萨斯……第一次听到这个词的时候，我还和你一样大。那个时候这个词对我来说没有什么意义，就好像现在它对你没有什么意义一样。但是当一群巨魔从祖尔法拉克来到这里肆意妄为之后，这个词就变成了恐惧的代名词。$B$B这里的人都会告诉你痛苦双刃并不存在，那只是一个神话，一个用来吓唬小孩子的故事。但是，$r，请相信我，它确实存在。$B$B<说到这里，特伦顿不禁开始用手抚摸自己脸上累累的伤疤。>', `MaleText_loc5`='蘇薩斯...第一次聽到這個詞的時候，我還和你一樣大。那個時候這個詞對我來說沒有什麼意義，就好像現在它對你沒有什麼意義一樣。但是當一群食人妖從祖爾法拉克來到這裡肆意妄為之後，這個詞就變成了恐懼的代名詞。$B$B這裡的人都會告訴你苦難裂劍並不存在，那只是一個神話，一個用來嚇唬小孩子的故事。但是，$r，請相信我，它確實存在。$B$B<說到這裡，特倫頓不禁開始用手撫摸自己臉上累累的傷疤。>', `MaleText_loc7`='Sul''thraze... la primera vez que escuché esa palabra tenía más o menos tu edad. Entonces no significaba nada para mí, así como tampoco significa nada para ti. No fue sino hasta que una banda de guerreros trol procedente de Zul''Farrak arrasó con la tierra que yo conocía... y temía.$B$BMuchos te dirán que el Acero Partido del Sufrimiento no existe. Que es un mito, un rumor desatado para asustar a los niños. Pero créeme, $r, existe.$B$B<Trenton permanece en silencio mientras recorre con la mano la herida en zigzag que cruza su rostro.>' WHERE `ID`=4182;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 얘기해 주십시오, 트렌튼.', `MaleText_loc4`='请继续说下去，特伦顿。', `MaleText_loc5`='請繼續說下去，特倫頓。', `MaleText_loc7`='Cuéntame más cosas, Trenton.', `FemaleText_loc1`='더 얘기해 주십시오, 트렌튼.', `FemaleText_loc4`='请继续说下去，特伦顿。', `FemaleText_loc5`='請繼續說下去，特倫頓。', `FemaleText_loc7`='Cuéntame más cosas, Trenton.' WHERE `ID`=4183;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='둘로 갈라졌지만 모이면 하나가 되지요. 이 쌍둥이 검은 줄파락에 묶여 있습니다.$B$B이 두 검을 찾으면 술트라제가 부활할 것입니다.', `MaleText_loc4`='分久必合，合久必分。那两把剑被隐藏在祖尔法拉克城中。$B$B苏萨斯会在两把剑都被发现时重生。', `MaleText_loc5`='它是兩把劍，但也是一把劍。那兩把劍被隱藏在祖爾法拉克中。$B$B蘇薩斯會在兩把劍都被發現時重生。', `MaleText_loc7`='Partida en dos, formando una sola. Las hojas gemelas están ligadas a Zul''Farrak.$B$BSul''thraze renacerá cuando se encuentren las dos mitades.' WHERE `ID`=4184;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 해골을 내게 주면 잘 받아서 고이 모셔주겠어...', `MaleText_loc4`='我是不会放过你的！', `MaleText_loc5`='你的腦袋我是要定了。', `MaleText_loc7`='Me darás cráneos y me llevaré cráneos.' WHERE `ID`=4185;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 귀염둥이들아! 어서 일어나라...', `MaleText_loc4`='快点痊愈吧，我的宠物！', `MaleText_loc5`='快點痊癒吧，我的寵物!', `MaleText_loc7`='¡Curaos, mascotas mías!' WHERE `ID`=4186;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='수고했어요! 당신의 도움이 없었으면 트로그 침략 부대를 절대 막을 수 없었을 거예요.', `FemaleText_loc4`='干得好！没有你的帮助，我是无法抵挡穴居人的！', `FemaleText_loc5`='幹得好!沒有你的幫助，我是無法抵擋穴居怪的!', `FemaleText_loc7`='¡Bien hecho! Sin tu ayuda jamás habría podido burlar la horda de troggs.' WHERE `ID`=4206;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무슨 소리 들리지 않았어요?', `FemaleText_loc4`='你听到什么声音没有？', `FemaleText_loc5`='你聽到什麼聲音沒有?', `FemaleText_loc7`='¿Has oído algo?' WHERE `ID`=4207;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저쪽에서 무슨 소리가 난 것 같은데...', `FemaleText_loc4`='我听到那里有点动静。', `FemaleText_loc5`='我聽到那裡有點動靜。', `FemaleText_loc7`='Yo he oído algo por allí.' WHERE `ID`=4208;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='트로그가 더 있어요! 폭탄을 준비하는 동안 녀석들을 막아주세요!', `FemaleText_loc4`='穴居人！挡住它们，我要准备爆破了！', `FemaleText_loc5`='穴居怪!擋住他們，我要準備爆破了!', `FemaleText_loc7`='¡Más troggs! ¡Recházalos mientras preparo los explosivos!' WHERE `ID`=4209;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='술트라제의 쌍둥이 검은 절대로 찾지 못하리라.', `MaleText_loc4`='你永远也不会发现苏萨斯双剑。', `MaleText_loc5`='你永遠也不會發現蘇薩斯雙劍。', `MaleText_loc7`='Nunca encontrarás las hojas gemelas de Sul.' WHERE `ID`=4210;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 손아귀에서 절대로 벗어날 수 없다!', `MaleText_loc4`='你逃不掉了！', `MaleText_loc5`='你逃不掉了!', `MaleText_loc7`='¡No hay salida!' WHERE `ID`=4211;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='결국엔 스러져 죽음을 맞이할 운명이여, 나의 눈빛에 굴복하라!', `MaleText_loc4`='去死吧，凡人！', `MaleText_loc5`='死吧，渺小的凡人!', `MaleText_loc7`='¡Sucumbid a la mirada, mortales!' WHERE `ID`=4212;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대가를 반드시 치르게 해주마...', `MaleText_loc4`='你会为此付出代价的……', `MaleText_loc5`='你會為此付出代價的...', `MaleText_loc7`='Pagaréis por ello...' WHERE `ID`=4213;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='술트라제의 부하들이 오늘 네 살로 진수성찬을 차릴 것이니라.', `MaleText_loc4`='苏萨斯的奴仆会将你生吞活剥。', `MaleText_loc5`='蘇薩斯的奴僕會將你生吞活剝。', `MaleText_loc7`='Los sirvientes de Sul danzarán sobre sus tumbas.' WHERE `ID`=4214;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음이란 환생의 문턱일 뿐... 우리는 다시 일어서리라.', `MaleText_loc4`='死亡是通往重生的途径，现在，让这个循环开始吧。', `MaleText_loc5`='死亡是通往重生的途徑，現在，讓這個迴圈開始吧。', `MaleText_loc7`='La muerte es tan solo la entrada al renacimiento. Nuestro linaje recuperará su esplendor.' WHERE `ID`=4215;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='', `MaleText_loc4`='', `MaleText_loc5`='', `MaleText_loc7`='' WHERE `ID`=4216;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='테라모어 경비병들은 칼림도어에 주둔하고 있는 얼라이언스 병사 중 가장 뛰어난 집단이지. 우리 고향에서 이렇게 멀리 떨어진 곳에서도 얼라이언스의 법을 수호하는 것이 우리의 임무라네.', `MaleText_loc4`='塞拉摩的卫兵都是原本驻扎在卡利姆多的联盟精英力量。即使远离了家园，但我们还是会努力维护联盟的律法。', `MaleText_loc5`='塞拉摩的守衛都是原本駐紮在卡林多的聯盟精英力量。即使遠離了家園，但我們還是會努力維護聯盟的律法。', `MaleText_loc7`='Los guardias de Theramore son el grupo de soldados más aguerrido de la Alianza con base en Kalimdor. Nuestro deber es defender las leyes de la Alianza incluso lejos de nuestros hogares.' WHERE `ID`=4225;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 제임스 하이얄의 아내와 아이가 빠져나오지 못했다는 것 외에는 그늘 쉼터 여관의 화재에 대해선 아는 바가 없네.$B$B우린 제임스를 겨우 구해 내긴 했지만 그 후로 그는 영 딴 사람이 되어 버렸어.$B$B심증이 가는 것이 여러 가지 있지만 이렇다 할 만한 증거가 없단 말이야. 우린 테라모어 주민들의 끊임없는 도움과 경비병들의 노력으로 이 끔찍한 범죄의 전말을 파헤쳐 내게 되기를 바라고 있다네.$B$B사건 조사를 돕고 싶다면 불모의 땅 경계로 가서 타고 남은 여관의 잔해가 있는지 찾아보게.', `MaleText_loc4`='我们对于树荫旅店被焚烧以及詹姆斯·海厄尔的妻子和孩子没能及时逃脱这些事情了解得并不多。$B$B我们想要找到詹姆斯的尸体，但是他却根本不在那堆废墟中。$B$B我们有一些线索，但是证据仍然很缺乏。我们希望能通过卫兵和塞拉摩人民的帮助让这件惨案得以大白天下。$B$B如果你也想帮忙的话，可以到贫瘠之地的边境那里调查一下旅店的废墟。', `MaleText_loc5`='我們對於樹蔭旅店被焚燒以及詹姆士·海爾的妻子和孩子沒能及時逃脫這些事情瞭解得並不多。$B$B我們想要找到詹姆士的屍體，但是他卻根本不在那堆廢墟中。$B$B我們有一些線索，但是證據仍然很缺乏。我們希望能通過守衛和塞拉摩人民的幫助讓這件慘案得以大白天下。$B$B如果你也想幫忙的話，可以到貧瘠之地的邊境那裡調查一下旅店的廢墟。', `MaleText_loc7`='No sabemos mucho acerca del incendio de la posada Reposo Umbrío, salvo que la mujer y el hijo de James Hyal no pudieron escapar.$b$bConseguimos sacar a James, pero él no ha vuelto a ser el mismo desde entonces.$b$bTenemos muchas pistas, pero pocas pruebas. Esperamos que gracias al esfuerzo de la guardia y de la ayuda atenta de la gente de Theramore podamos desentrañar este terrible crimen.$b$bSi deseas ayudarnos en la investigación, los restos de la posada están en la frontera de los Baldíos.' WHERE `ID`=4226;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그늘 쉼터 여관에 대해 들은 소식이 있습니까?', `MaleText_loc4`='关于绿荫旅店，你都听说过些什么？', `MaleText_loc5`='關於樹蔭旅店，你都聽說過些什麼?', `MaleText_loc7`='¿Qué has oído acerca de la posada Reposo Umbrío?', `FemaleText_loc1`='그늘 쉼터 여관에 대해 들은 소식이 있습니까?', `FemaleText_loc4`='关于绿荫旅店，你都听说过些什么？', `FemaleText_loc5`='關於樹蔭旅店，你都聽說過些什麼?', `FemaleText_loc7`='¿Qué has oído acerca de la posada Reposo Umbrío?' WHERE `ID`=4227;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 키리스를 고통에서 해방시켰다고? 믿을 수가 없군. 게다가 지금 트레보르가 악마와 그 부하들에 관해 알아오라고 자네를 여기로 보냈단 말이지?$B$B<웃으며>$B$B$R|1이여;여;, 사악한 마법의 고통이 마침내 사라지게 된 것이니, 감사히 여기게.', `MaleText_loc4`='你终于帮助基利斯解脱了？真是难以想象——现在特雷博派你来到我这里，想要学习关于恶魔的知识？$B$B<洛拉姆斯大笑了起来。>$B$B魔法所带来的痛苦最终还是消散了。', `MaleText_loc5`='你終於幫助基利斯解脫了?真是難以想像─現在特雷博派你來到我這裡，想要學習關於惡魔的知識?$B$B<洛拉姆斯大笑了起來。>$B$B魔法所帶來的痛苦最終還是消散了，$r。', `MaleText_loc7`='¿Liberaste a Kirith de su sufrimiento? Inconcebible. ¿Y ahora Trebor te ha enviado aquí para aprender sobre demonios y sus esbirros?$B$B<Loramus ríe.>$B$BAgradece que los dolores arcanos por fin hayan desaparecido, $r.' WHERE `ID`=4228;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들이 보이는가? 그래, 안 보일 줄 알았네. 멀쩡한 두 눈으로도 보이지 않는 세계가 있지. 축복이자 저주야.', `MaleText_loc4`='你看到他们了吗？当然没有……我认为你是看不到的。以你的资质，即使有眼睛也和瞎了没有什么区别。', `MaleText_loc5`='你看到他們了嗎?當然沒有...我認為你是看不到的。以你的資質，即使有眼睛也和瞎了沒有什麼區別。', `MaleText_loc7`='¿Puedes verlos, mortal? No... No creo que puedas. Vidente, pero ciego - son tu don y tu maldición.' WHERE `ID`=4229;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, 로라무스. 저주받은 땅에서 가져온 소식이 있습니다.', `MaleText_loc4`='嘿，洛拉姆斯，我从诅咒之地给你带来了一些消息。', `MaleText_loc5`='嘿，洛拉姆斯，我從詛咒之地給你帶來了一些消息。', `MaleText_loc7`='Buenas, Loramus. Traigo noticias de Las Tierras Devastadas.', `FemaleText_loc1`='안녕하십니까, 로라무스. 저주받은 땅에서 가져온 소식이 있습니다.', `FemaleText_loc4`='嘿，洛拉姆斯，我从诅咒之地给你带来了一些消息。', `FemaleText_loc5`='嘿，洛拉姆斯，我從詛咒之地給你帶來了一些消息。', `FemaleText_loc7`='Buenas, Loramus. Traigo noticias de Las Tierras Devastadas.' WHERE `ID`=4230;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와주시겠습니까?', `MaleText_loc4`='你能帮个忙吗？', `MaleText_loc5`='你能幫個忙嗎?', `MaleText_loc7`='¿Ayudarás?', `FemaleText_loc1`='도와주시겠습니까?', `FemaleText_loc4`='你能帮个忙吗？', `FemaleText_loc5`='你能幫個忙嗎?', `FemaleText_loc7`='¿Ayudarás?' WHERE `ID`=4245;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파멸자 라젤리크는 대전쟁 당시 군주 카자크의 부관 중 가장 두려운 존재였지. 불타는 군단이 패하고 카자크가 타락의 흉터로 밀려났을 때 라젤리크는 카자크로부터 저주받은 땅을 확보하라는 임무를 받았네.$B$B얼라이언스와 호드가 저주받은 땅 밖의 영토를 놓고 사소한 싸움을 벌이고 있을 때, 라젤리크는 어둠의 의회를 결속시키고 흉포한 우레망치 오우거들을 모으고 있었네.', `MaleText_loc4`='在抵抗燃烧军团时期，污染者拉瑟莱克是卡扎克麾下最强大的将领之一。当燃烧军团被击退，卡扎克的势力被压制之后，拉瑟莱克接受了诅咒之地的事务。$B$B当联盟和部落在诅咒之地以外的地方打得天昏地暗的时候，拉瑟莱克则在召集阴影议会的教徒，以及野蛮的巨槌食人魔。', `MaleText_loc5`='在抵抗燃燒軍團時期，『污染者』拉瑟萊克是卡札克領主麾下最強大的副官之一。當燃燒軍團被擊退，卡札克的勢力被壓制之後，拉瑟萊克接受了詛咒之地的事務。$B$B當聯盟和部落在詛咒之地以外的地方打得天昏地暗的時候，拉瑟萊克則在召集暗影議會的教徒，以及野蠻的巨槌巨魔。', `MaleText_loc7`='En tiempos de guerra, Razelikh el Rapiñador sirvió como uno de los más temibles tenientes de Lord Kazzak. Cuando la legión fue derrotada y Kazzak obligado a volver a la Escara Impía, su maestro encargó a Razelikh proteger las Tierras Devastadas.$B$BMientras la Alianza emprendía insignificantes batallas con la Horda fuera de Las Tierras Devastadas, Razelikh unificaba las distintas sectas del Consejo Sombrío y a los brutales ogros Machacamiedo del país.' WHERE `ID`=4246;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 말씀하십시오.', `MaleText_loc4`='请继续说下去。', `MaleText_loc5`='請繼續說下去。', `MaleText_loc7`='Por favor, continúa.', `FemaleText_loc1`='계속 말씀하십시오.', `FemaleText_loc4`='请继续说下去。', `FemaleText_loc5`='請繼續說下去。', `FemaleText_loc7`='Por favor, continúa.' WHERE `ID`=4247;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비극적이게도, 악마의 군주와 그 부하들의 결속을 봉해버린 것은 스랄의 지혜였지. 여기에 트레보르의 군대가 악마의 군주와 어둠혈맹, 그리고 오우거들을 단결시키는 역할을 했어. 스랄은 지도자들에게 무한한 힘과 불멸의 습격 부대를 주겠다는 것을 미끼로 삼아 거래를 피로 봉했다네.', `MaleText_loc4`='可悲的是，正是因为萨尔的智慧才导致了恶魔之王和其它势力联合起来，特雷博的军队促成了恶魔之王、阴影议会和巨槌食人魔之间的联合。对于力量的无尽渴求使得他们签下了血契，对恶魔效忠。', `MaleText_loc5`='可悲的是，正是因為索爾的智慧才導致了惡魔領主和其他勢力聯合起來，特雷博的軍隊促成了惡魔領主、影誓教派和巨槌巨魔之間的聯合。對於力量的無盡渴求使得他們簽下了血契，對惡魔效忠。', `MaleText_loc7`='Trágicamente, la sabiduría de Thrall finalmente selló el vínculo entre el señor demoníaco y sus esbirros. Fue el regimiento de Trebor el que sirvió como catalizador para unir al señor demoníaco con las sectas Sombra Jurada y los ogros. La idea de un poder casi ilimitado y la concesión de tropas de impacto inmortales para cada líder les hizo sellar un pacto de sangre.' WHERE `ID`=4248;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이해가 가지 않습니다.', `MaleText_loc4`='我不明白。', `MaleText_loc5`='我不明白。', `MaleText_loc7`='No entiendo.', `FemaleText_loc1`='이해가 가지 않습니다.', `FemaleText_loc4`='我不明白。', `FemaleText_loc5`='我不明白。', `FemaleText_loc7`='No entiendo.' WHERE `ID`=4249;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세바인, 알리스타즈, 그리고 그롤은 그들의 부하들처럼 땅에 묶일 수도 있단 사실을 깨닫지 못했고... 라젤리크는 그들에게 불멸을 선물한 대가로 구속시켜 영원히 봉사할 것을 명했네. 라젤리크의 잔인한 교활함이 다시 한번 승리를 거둔 셈이지.', `MaleText_loc4`='瑟温妮、奥利斯塔和戈洛尔都没有意识到，其实他们和那些奴仆一样，都被永远禁锢在这片土地上了。他们所获得的不朽之力其实就是要永远为拉瑟莱克卖命。狡猾的拉瑟莱克又一次获得了胜利。', `MaleText_loc5`='瑟溫妮、奧利斯塔和戈洛爾都沒有意識到，其實他們和那些奴僕一樣，都被永遠禁錮在這片土地上了。他們所獲得的不朽之力其實就是要永遠為拉瑟萊克賣命。狡猾的拉瑟萊克又一次獲得了勝利。', `MaleText_loc7`='Lo que no entendieron Sevine, Allistarj y Grol fue que, al igual que sus sirvientes, también ellos estarían ligados a la tierra... Como ves, el precio de su inmortalidad fue a su vez el cautiverio y eterna servidumbre a las órdenes de Razelikh. La cruel astucia de Razelikh ha vuelto a alzarse victoriosa.' WHERE `ID`=4250;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그랬군요...', `MaleText_loc4`='确实如此。', `MaleText_loc5`='確實如此。', `MaleText_loc7`='Por supuesto.', `FemaleText_loc1`='그랬군요...', `FemaleText_loc4`='确实如此。', `FemaleText_loc5`='確實如此。', `FemaleText_loc7`='Por supuesto.' WHERE `ID`=4251;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들의 정신은 이제 타락했어. 그래, 전보다 훨씬 타락했지. 이제 그들은 오직 라젤리크를 섬기고 보호하기 위해서만 산다네. 그들이 하나씩 지니고 있는 아뮬렛 조각은 이 악마의 군주를 소환하는 열쇠라네. 자네가 정말로 이해하지 못하는 건 기존의 방법으로는 그것들을 파괴할 수가 없다는 거야.', `MaleText_loc4`='$n，他们的意识已经被污染了。是的，情况越来越严重。他们现在只会为拉瑟莱克而活。他们手中的护符碎片就是召唤恶魔之王的钥匙。但问题是，他们已经对于常规的攻击方式完全免疫了。', `MaleText_loc5`='$r，他們的意識已經受污染了。是的，情況越來越嚴重。他們現在只會為拉瑟萊克而活。他們手中的護符碎片就是召喚惡魔領主的鑰匙。但問題是，他們已經對於常規的攻擊方式完全免疫了。', `MaleText_loc7`='Ahora sus mentes están contaminadas, $r. Sí, incluso más que antes. Viven solo para servir y proteger a Razelikh. Los fragmentos de amuleto que cada uno lleva son la clave para invocar al señor demoníaco. Lo que no entiendes es que ninguno de ellos es susceptible al ataque por medios convencionales.' WHERE `ID`=4252;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 그들의 정신은 타락했어. 전보다 훨씬 더러워졌지... 오직 라젤리크만을 섬기기 위해서 사는 노예나 다름없지. 그들이 하나씩 지니고 있는 아뮬렛 조각이 악마의 군주를 소환할 열쇠라네. 그런데 기존의 방법으로는 그것들을 파괴할 수가 없다네. 자네에게는 정말로 이해가 가지 않을 거야.', `MaleText_loc4`='$n，他们的意识已经被污染了。是的，情况越来越严重。他们现在只会为拉瑟莱克而活。他们手中的护符碎片就是召唤恶魔之王的钥匙。但问题是，他们已经对于常规的攻击方式完全免疫了。', `MaleText_loc5`='$r，他們的意識已經受污染了。是的，情況越來越嚴重。他們現在只會為拉瑟萊克而活。他們手中的護符碎片就是召喚惡魔領主的鑰匙。但問題是，他們已經對於常規的攻擊方式完全免疫了。', `MaleText_loc7`='Ahora sus mentes están contaminadas, $r. Sí, incluso más que antes. Viven solo para servir y proteger a Razelikh. Los fragmentos de amuleto que cada uno lleva son la clave para invocar al señor demoníaco. Lo que no entiendes es que ninguno de ellos es susceptible al ataque por medios convencionales.' WHERE `ID`=4253;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 도와주든 도와주지 않든 이 일을 할 겁니다, 로라무스.', `MaleText_loc4`='洛拉姆斯，无论你是否帮忙，我都会去做的。', `MaleText_loc5`='洛拉姆斯，無論你是否幫忙，我都會去做的。', `MaleText_loc7`='Lo haré con o sin tu ayuda, Loramus.', `FemaleText_loc1`='당신이 도와주든 도와주지 않든 이 일을 할 겁니다, 로라무스.', `FemaleText_loc4`='洛拉姆斯，无论你是否帮忙，我都会去做的。', `FemaleText_loc5`='洛拉姆斯，無論你是否幫忙，我都會去做的。', `FemaleText_loc7`='Lo haré con o sin tu ayuda, Loramus.' WHERE `ID`=4254;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇다면, 자네가 그 아뮬렛 조각 세 개에 부여된 악마의 보호막을 제거할 무기를 만들기 위한 길고 험난한 임무를 수행한다고 치세. 그다음에는 어쩔 셈인가? 파멸자의 은신처에서 그와 맞서기라도 할 텐가?$B$B<큰 소리로 비웃습니다.>', `MaleText_loc4`='那么让我们假设你即将开始这段漫长而又艰辛的任务，你要做的是就是想办法摧毁这三个家伙的防御结界。然后呢？去污染者拉瑟莱克的巢穴挑战他？$B$B<洛拉姆斯大笑着。>', `MaleText_loc5`='那麼讓我們假設你即將開始這段漫長而又艱辛的任務，你要做的是就是想辦法摧毀這三個傢伙的防禦結界。然後呢?去污染者拉瑟萊克的巢穴挑戰他?$B$B<洛拉姆斯大笑著。>', `MaleText_loc7`='Entonces supongamos que acometes la larga y ardua tarea de dar toda la guerra necesaria para penetrar en las salas demoníacas de la tríada. ¿Cuál sería tu siguiente estrategia? ¿Enfrentarte al Rapiñador en su guarida?$B$B<Loramus se ríe.>' WHERE `ID`=4255;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇게 하겠습니다.', `MaleText_loc4`='是的。', `MaleText_loc5`='是的。', `MaleText_loc7`='Sí.', `FemaleText_loc1`='그렇게 하겠습니다.', `FemaleText_loc4`='是的。', `FemaleText_loc5`='是的。', `FemaleText_loc7`='Sí.' WHERE `ID`=4256;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 이야기를 들려주십시오.', `MaleText_loc4`='我想要听听你的故事。', `MaleText_loc5`='我想要聽聽你的故事。', `MaleText_loc7`='Me gustaría oír tu historia.', `FemaleText_loc1`='당신의 이야기를 들려주십시오.', `FemaleText_loc4`='我想要听听你的故事。', `FemaleText_loc5`='我想要聽聽你的故事。', `FemaleText_loc7`='Me gustaría oír tu historia.' WHERE `ID`=4257;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='인간들이 먼지진흙 습지대의 많은 부분을 점령했지만 돌망치 일족은 우리의 도움으로 그들을 몰아낼 수 있었소.', `MaleText_loc4`='人类宣称尘泥沼泽是他们的领地，但是石槌部族在我们的帮助下将他们赶了回去。', `MaleText_loc5`='人類宣稱塵泥沼澤是他們的領地，但是石槌氏族在我們的幫助下將他們趕了回去。', `MaleText_loc7`='Los humanos reclamaban para sí gran parte del Marjal Revolcafango, pero el clan Quebrantarrocas, con nuestra ayuda, ha logrado hacerles retroceder.' WHERE `ID`=4258;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불타는 여관', `MaleText_loc4`='烧毁的旅店。', `MaleText_loc5`='燒毀的旅店。', `MaleText_loc7`='La Posada Ardiente.', `FemaleText_loc1`='불타는 여관', `FemaleText_loc4`='烧毁的旅店。', `FemaleText_loc5`='燒毀的旅店。', `FemaleText_loc7`='La Posada Ardiente.' WHERE `ID`=4259;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불모의 땅 변두리에 인간들이 그늘 쉼터라는 이름의 여관을 하나 지었지만 몇 주 전에 불타 버렸소.$B$B내가 왜 신경 쓰냔 말이오? 신경쓰지 않소. 인간들에 대해서는 신경도 쓰지 않는단 말이오. 그 여관에 심어놓은 첩자가 있소. 난 그의 죽음이 대답 없는 일로 묻히도록 두진 않을 것이오. 누가 이런 일을 했는지 알아야 하오$B$B도울 의사가 있다면 타고 남은 그늘 쉼터 여관으로 가 보고 뭔가 단서를 찾으면 내게 알려 주시오.', `MaleText_loc4`='人类在贫瘠之地的边界处建了一座旅店，他们叫它树荫旅店。几个星期前，这家旅店被烧掉了。$b$b为什么我会在意这种事？当然，我并不关心人类的死活。但我在那家旅店里安插了一名间谍。我不会让他就这样白白死掉。我要知道这是谁干的。$B$B如果你想帮忙的话，就去查看一下树荫旅店的废墟，把你能找到的线索都给我带回来。', `MaleText_loc5`='人類在貧瘠之地的邊界處建了一座旅店，他們叫它樹蔭旅店。幾個星期前，這家旅店被燒掉了。$b$b關我什麼事?我對人類不太瞭解，但我派了一個間諜在旅店內，我不會讓他死的不明不白。我需要知道是誰幹的。$B$B如果你想幫忙，就到樹蔭旅店的廢墟查看，把任何你能找到的線索給帶回來。', `MaleText_loc7`='Los humanos construyeron una posada en la frontera de Los Baldíos. La llamaron Reposo Umbrío. Hace unas semanas, se incendió.$b$b¿Por qué me importa? Es que no me importa, al menos no me preocupan los humanos, pero en esa posada tenía apostado un espía, y no permitiré que su muerte sea en vano. Debo saber quién fue el culpable.$b$bSi quieres serme de ayuda, examina los restos de la Posada Reposo Umbrío y regresa con cualquier pista que encuentres.' WHERE `ID`=4260;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리테 찾기', `MaleText_loc4`='寻找帕瓦尔·雷瑟。', `MaleText_loc5`='尋找帕瓦爾·雷瑟。', `MaleText_loc7`='Encontrando a Reethe.', `FemaleText_loc1`='리테 찾기', `FemaleText_loc4`='寻找帕瓦尔·雷瑟。', `FemaleText_loc5`='尋找帕瓦爾·雷瑟。', `FemaleText_loc7`='Encontrando a Reethe.' WHERE `ID`=4261;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리테가 그늘 쉼터 여관의 화재와 무슨 관련이 있다면 그를 찾아서 심문해 봐야 할 거요.$B$B내가 오그론을 보내 그를 추적하도록 했는데 말이야. 그는 남동쪽으로 습지대를 가로지르는 주 도로쪽으로 갔으니 오그론과 만나 리테를 찾아보시오.', `MaleText_loc4`='如果雷瑟和树荫旅店被烧毁的事有某种联系的话，你就得找到他，问个清楚。$b$b我派了奥格隆去追他，应该是朝东南方向去了。去跟奥格隆会合，然后一起去找雷瑟吧。', `MaleText_loc5`='如果雷瑟和樹蔭旅店被燒毀的事有某種聯繫的話，你就得找到他，問個清楚。$b$b我派了奧格隆去追他。他往東南方向去了，由主要道路穿過了沼澤。去跟奧格隆會合，然後一起去找雷瑟吧。', `MaleText_loc7`='Si Reethe está implicado de alguna manera en el incendio de la Posada Reposo Umbrío, tendrás que encontrarlo y sacarle información.$b$bHe enviado a Ogron para seguirle la pista. Se dirigió hacia el sudeste, hacia la carretera principal que atraviesa la marisma. Reúnete con Ogron y luego busca a Reethe.' WHERE `ID`=4262;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n, 절대로 당신을 이글거리는 협곡에 들여보낼 수는 없습니다. 불가능해요. 절대 안 돼요. 몇 번이나 얘기해야 합니까? 못 들여보낸다니까요! 이해 못 하시겠습니까? 설마 당신 원래 오크인데, 변장이라도 한 건가요? 안 됩니다. 안 된다고요!$B$B당신을 들여보내면 모두 다 들여보내야 한단 말입니다. 당신 친구들도 들어가려 할 테고 그다음에는 먼 친척, 그다음에는 그 친척의 친척, 그렇게 계속될 겁니다. 전에도 한 번 그런 일이 터졌는데... 뭐, 지난 얘기는 할 필요 없겠지요.', `FemaleText_loc4`='$n，我不介意听到这个。不，你绝不能进入灼热峡谷，决不可能。我告诉你多少次了——我绝对不会让你进去的！你难道听不懂吗？你难道是兽人假扮成的？看我口型，不！$B$B如果我让你进去，那么每个人都会想要进去。不久之后，你最好的朋友，你的远房亲戚，然后你远房亲戚的朋友，然后所有的人就会来我这里想要进去。以前发生过这样的事情……好吧，我们不谈以前的事情。', `FemaleText_loc5`='$n，我不介意聽到這個。不，你絕不能進入灼熱峽谷，決不可能。我告訴你多少次了─我絕對不會讓你進去的!你難道聽不懂嗎?你難道是獸人假扮成的?看我口型，不!$B$B如果我讓你進去，那麼每個人都會想要進去。不久之後，你最好的朋友，你的遠房親戚，然後你遠房親戚的朋友，然後所有的人就會來我這裡想要進去。以前發生過這樣的事情...好吧，我們不談以前的事情。', `FemaleText_loc7`='No me importa lo que digas, $n. Nada de eso, de ninguna manera te dejaré entrar en la Garganta de Fuego. Es imposible, Ni hablar. ¿Cuántas veces te lo tengo que decir? ¡No puedo dejar que entres allí! ¿No entiendes mi idioma? ¿Eres un orco disfrazado? N-O. ¡NO!$B$BSi te dejo entrar, entonces tendré que dejarlos entrar a todos. Muy pronto tus amigos más cercanos querrán entrar, luego tus familiares lejanos, sus amigos etc., etc. La última vez que eso ocurrió... bueno, mejor no hablar de la última vez que ocurrió.' WHERE `ID`=4265;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최악의 경우 무슨 일이 일어납니까?', `MaleText_loc4`='会发生什么糟糕的事情？', `MaleText_loc5`='會發生什麼糟糕的事情?', `MaleText_loc7`='¿Qué es lo peor que podría pasar?', `FemaleText_loc1`='최악의 경우 무슨 일이 일어납니까?', `FemaleText_loc4`='会发生什么糟糕的事情？', `FemaleText_loc5`='會發生什麼糟糕的事情?', `FemaleText_loc7`='¿Qué es lo peor que podría pasar?' WHERE `ID`=4266;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그곳에 어떤 괴물이 사는지 알기나 하십니까? 최악의 경우에는 우리가 당신의 유해를 삽으로 퍼서 회수해내는 일이 생긴다고요. 벌써 그 끔찍한 괴물들에게 우리 착하디 착한 드워프 친구들을 얼마나 잃었는지 모릅니다.$B$B내 대답은 "절대 안 된다"예요. 이글거리는 협곡에 그렇게 들어가고 싶거든 다른 길을 찾아보도록 하십시오.', `FemaleText_loc4`='你疯了吗？你难道不知道那里都是些凶残无比的野兽？我们可能得使用铲子才能挖出你的尸体。我们已经在那里损失了太多生命了。$B$B我的答案是，不行。如果你想要去灼热峡谷，那么我只能说抱歉了，此路不通。', `FemaleText_loc5`='你瘋了嗎?你難道不知道那裡都是些兇殘無比的野獸?我們可能得使用鏟子才能挖出你的屍體。我們已經在那裡損失了太多生命了。$B$B我的答案是，不行。如果你想要去灼熱峽谷，那麼我只能說抱歉了，此路不通。', `FemaleText_loc7`='¿Has perdido la cabeza? ¿Sabes qué clase de bestia vive en ese lugar? Lo peor que puede pasar es que tengamos que recoger tus restos con una pala. Hemos perdido a excelentes enanos en las garras de aquellos terribles monstruos.$B$BAsí que la respuesta es no. Si estás $gdecidido:decidida; a entrar en la Garganta de Fuego, tendrás que ir por otro camino.' WHERE `ID`=4267;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 길요? 그 길이 어디죠?', `MaleText_loc4`='此路不通？那还有别的路吗……', `MaleText_loc5`='此路不通?那還有別的路嗎...', `MaleText_loc7`='¿Otro camino? Dime...', `FemaleText_loc1`='다른 길요? 그 길이 어디죠?', `FemaleText_loc4`='此路不通？那还有别的路吗……', `FemaleText_loc5`='此路不通?那還有別的路嗎...', `FemaleText_loc7`='¿Otro camino? Dime...' WHERE `ID`=4268;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 얘기도 하면 안 되는 건데, 황야의 땅에 있는 짐승과 괴물을 모조리 물리칠 수만 있다면 이글거리는 협곡에 갈 수 있습니다.$B$B맞아요! 황야의 땅 말입니다. 카르가스 근처에 오크들이 닦아놓은 뒷길 같은 게 있어요. 우리가 상대하는 적이 얼마나 바보인지 아시겠죠! 지옥으로 들어가는 뒷문이라니? 도대체 생각이란 게 있는 족속들인지...', `FemaleText_loc4`='我原本不想告诉你的：如果你能够穿过荒芜之地的话，那么你也许可以找到通往灼热峡谷的另外一条路。$B$B没错，我说的是荒芜之地。在卡加斯营地那里，兽人铺了一条通向灼热峡谷的小路。你说说他们有多蠢吧！那帮家伙居然造了一条通向地狱的道路？他们到底在想什么啊？', `FemaleText_loc5`='我原本不想告訴你的:如果你能夠穿過荒蕪之地的話，那麼你也許可以找到通往灼熱峽谷的另外一條路。$B$B沒錯，我說的是荒蕪之地。在卡加斯營地那裡，獸人鋪了一條通向灼熱峽谷的小路。你說說他們有多蠢吧!那幫傢伙居然造了一條通向地獄的道路?他們到底在想什麼啊?', `FemaleText_loc7`='No debería contarte esto, pero si puedes vencer a todos los bichos y bestias que hay en las Tierras Inhóspitas, entonces tal vez puedas llegar hasta la Garganta de Fuego.$B$BSí, las Tierras Inhóspitas. Ahí hay un camino alternativo que los orcos construyeron cerca de Kargath. ¡Esto es solo para que veas con qué clase de tontos estamos lidiando! ¿Una puerta trasera al infierno? ¿En qué estarían pensando?' WHERE `ID`=4269;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오크? 황야의 땅? 전 무적이라고요!', `MaleText_loc4`='兽人？荒芜之地？小意思！', `MaleText_loc5`='獸人?荒蕪之地?小意思!', `MaleText_loc7`='¿Orcos? ¿Las Tierras Inhóspitas? ¡Soy invulnerable!', `FemaleText_loc1`='오크? 황야의 땅? 전 무적이라고요!', `FemaleText_loc4`='兽人？荒芜之地？小意思！', `FemaleText_loc5`='獸人?荒蕪之地?小意思!', `FemaleText_loc7`='¿Orcos? ¿Las Tierras Inhóspitas? ¡Soy invulnerable!' WHERE `ID`=4270;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무적이라고요?', `FemaleText_loc4`='小意思？', `FemaleText_loc5`='小意思?', `FemaleText_loc7`='¿Invulnerable?' WHERE `ID`=4271;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당연하죠!', `MaleText_loc4`='当然！', `MaleText_loc5`='當然!', `MaleText_loc7`='¡Desde luego!', `FemaleText_loc1`='당연하죠!', `FemaleText_loc4`='当然！', `FemaleText_loc5`='當然!', `FemaleText_loc7`='¡Desde luego!' WHERE `ID`=4272;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말 어리석군요. 내 경고를 무시하지 마십시오. 이 세상에 완벽한 자는 아무도 없답니다. 제 조언을 조금이라도 새겨 듣는 것이 신상에 좋을 겁니다.', `FemaleText_loc4`='不听我的劝告，你就等着有人来给你收尸吧！别以为你自己无所不能，小心使得万年船！', `FemaleText_loc5`='不聽我的勸告，你就等著有人來給你收屍吧!別以為你自己無所不能，小心使得萬年船!', `FemaleText_loc7`='Eres idiota si no haces caso a mis advertencias. Nadie es invulnerable. Serías $gsensato:sensata; si recordaras mi consejo.' WHERE `ID`=4273;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사과 드리죠, 페블비티...', `MaleText_loc4`='对不起，贝波蒂。', `MaleText_loc5`='對不起，貝波蒂。', `MaleText_loc7`='Lo siento mucho, Guijarro.', `FemaleText_loc1`='사과 드리죠, 페블비티...', `FemaleText_loc4`='对不起，贝波蒂。', `FemaleText_loc5`='對不起，貝波蒂。', `FemaleText_loc7`='Lo siento mucho, Guijarro.' WHERE `ID`=4274;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='한 가지만 더 말씀드리겠습니다. 자신을 영웅이라고 생각하는 것 같은데, 그렇다면 황야의 땅을 지나 그렇게 소원하는 이글거리는 협곡으로 들어가십시오. 단, 당신의 용맹함을 입증할 증거를 가지고 오도록 하세요. 그러면 생각해보고 당신에게 열쇠를 드릴 수도 있죠.$B$B이글거리는 협곡의 남동쪽 구석에 나만큼이나 힘센 여자가 있어요. 난폭한 마르골이라고 하는데, 가서 한번 만나 보세요.', `FemaleText_loc4`='你猜怎么着，既然你觉得自己是个英雄，那么就穿过荒芜之地到灼热峡谷去，拿回一些能证明你的实力的东西，这样我也许能想办法帮你搞到一把钥匙。$B$B在灼热峡谷的最西南角有一个强壮的女士，嗯，几乎跟我一样强壮，她的名字叫狂暴的玛尔戈。也许你应该先去找她谈谈……', `FemaleText_loc5`='你猜怎麼著，既然你覺得自己是個英雄，那麼就穿過荒蕪之地到灼熱峽谷去，拿回一些能證明你的實力的東西，這樣我也許能想辦法幫你搞到一把鑰匙。$B$B在灼熱峽谷的最東南角有一個強壯的女士，嗯，幾乎跟我一樣強壯，她的名字叫狂暴的瑪爾戈。也許你應該先去找她談談...', `FemaleText_loc7`='Mira. Ya que te crees un héroe, si eres capaz de cruzar las Tierras Inhóspitas hasta la Garganta de Fuego y traerme algo como prueba de tus heroicidades, veré si puedo conseguirte una llave.$B$BEn la parte sudeste de la Garganta de Fuego hay una mujer tan exigente como yo, Margol la Furibunda. Quizás deberías indagar un poco.' WHERE `ID`=4275;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠어요. 알겠다고요.', `MaleText_loc4`='完成了，全部完成了。', `MaleText_loc5`='完成了，全部完成了。', `MaleText_loc7`='Hecho, hecho, y hecho.', `FemaleText_loc1`='알겠어요. 알겠다고요.', `FemaleText_loc4`='完成了，全部完成了。', `FemaleText_loc5`='完成了，全部完成了。', `FemaleText_loc7`='Hecho, hecho, y hecho.' WHERE `ID`=4276;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 유물 바닥에서 먼지를 털어냅니다.', `MaleText_loc4`='%s抹去神器底座上的灰尘。', `MaleText_loc5`='%s把神器底座上的灰塵掃除乾淨。', `MaleText_loc7`='%s quita el polvo a la base del artefacto.' WHERE `ID`=4285;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 큰 꽃병을 꼼꼼히 관찰합니다.', `MaleText_loc4`='%s小心翼翼地查看着大花瓶。', `MaleText_loc5`='%s小心翼翼地查看著大花瓶。', `MaleText_loc7`='%s examina meticulosamente el gran jarrón.' WHERE `ID`=4286;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불쌍한 도리우스... 망할 검은무쇠 놈들, 내 손에 걸리기만 해봐. 날 좀 도와...', `MaleText_loc4`='可怜的杜里奥斯。那些黑铁矮人真是该死，帮帮我吧……', `MaleText_loc5`='可憐的杜里奧斯。那些黑鐵矮人真是該死，幫幫我吧...', `MaleText_loc7`='Pobre Dorius. Si alguna vez pongo mis manos encima de esos Hierro Negro, que la Luz me asista.' WHERE `ID`=4287;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 뿔을 놓기 딱 좋은 자리가 하나 있지!', `MaleText_loc4`='这里正好有个地方可以摆放这支角！', `MaleText_loc5`='這裡正好有個地方可以擺放這支角!', `MaleText_loc7`='¡He encontrado el lugar perfecto para este cuerno!' WHERE `ID`=4305;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여태 이 자리는 특별한 걸 놓으려고 비워두고 있었소. 이 자리의 주인이 이제야 나타난 것 같군.', `MaleText_loc4`='我一直把这个地方空着，希望有一些特殊的东西能放在这里。我不认为能有什么比这个更特殊了，$n。', `MaleText_loc5`='我一直把這個地方空著，希望有一些特殊的東西能放在這裡。我不認為能有什麼比這個更特殊了，$n。', `MaleText_loc7`='He estado guardando este sitio para algo especial. No creo que haya nada más especial que esto, $n.' WHERE `ID`=4306;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 다 됐소! 훌륭하군.', `MaleText_loc4`='就是这样，全部搞定了！', `MaleText_loc5`='就是這樣，全部搞定了!', `MaleText_loc7`='Allá vamos. ¡Listo!' WHERE `ID`=4307;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여관에서는 무엇을 할 수 있습니까?', `MaleText_loc4`='我能在旅店里干些什么？', `MaleText_loc5`='我能在旅店裡幹些什麼?', `MaleText_loc7`='¿Qué puedo hacer en una posada?', `FemaleText_loc1`='여관에서는 무엇을 할 수 있습니까?', `FemaleText_loc4`='我能在旅店里干些什么？', `FemaleText_loc5`='我能在旅店裡幹些什麼?', `FemaleText_loc7`='¿Qué puedo hacer en una posada?' WHERE `ID`=4308;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여관에서 무엇을 할 수 있느냐고요?$B$B여관에서는 아주 편하게 쉴 수 있기 때문에 야외에서 보다 훨씬 빠르게 피로를 회복할 수 있답니다. 피로를 회복한 상태에서 사냥을 하면 경험치를 더 많이 얻을 수 있답니다.$B$B또한 여관주인에게 귀환석을 받을 수도 있는데 이 귀환석을 사용하면 필요할 때 여관으로 되돌아올 수 있습니다.', `MaleText_loc4`='当你待在旅店里的时候，你就可以好好地休息。因此,你可以比留在野外更快地恢复到精力充沛的状态，这样就可以获得更多的经验值。$B$B另外你还可以通过和旅店老板交谈来获得一块炉石，以后就可以使用这块炉石快速回到你绑定的旅店里了。', `MaleText_loc5`='當你待在旅店裡的時候，你就可以好好地休息。因此，你可以比留在野外更快地恢復到「充分休息」的狀態，這樣就可以獲得更多的經驗值。$B$B另外你還可以通過和旅店老闆交談來獲得一塊爐石，以後就可以使用這塊爐石快速回到你綁定的旅店裡了。', `MaleText_loc7`='Cuando te quedas en una posada, descansas cómodamente. Por esta razón, estarás "más descansado" en mucho menos tiempo que si lo haces en el bosque. Cuando descansas bien, aprendes más de la experiencia.$B$BAsimismo, puedes pedirle al tabernero que te consiga una piedra de hogar para luego usarla con el fin de regresar rápidamente a la posada.', `FemaleText_loc1`='여관에서 무엇을 할 수 있느냐고요?$B$B여관에서는 아주 편하게 쉴 수 있기 때문에 야외에서 보다 훨씬 빠르게 피로를 회복할 수 있답니다. 피로를 회복한 상태에서 사냥을 하면 경험치를 더 많이 얻을 수 있답니다.$B$B또한 여관주인에게 귀환석을 받을 수도 있는데 이 귀환석을 사용하면 필요할 때 여관으로 되돌아올 수 있습니다.', `FemaleText_loc4`='当你待在旅店里的时候，你就可以好好地休息。因此,你可以比留在野外更快地恢复到精力充沛的状态，这样就可以获得更多的经验值。$B$B另外你还可以通过和旅店老板交谈来获得一块炉石，以后就可以使用这块炉石快速回到你绑定的旅店里了。', `FemaleText_loc5`='當你待在旅店裡的時候，你就可以好好地休息。因此，你可以比留在野外更快地恢復到「充分休息」的狀態，這樣就可以獲得更多的經驗值。$B$B另外你還可以通過和旅店老闆交談來獲得一塊爐石，以後就可以使用這塊爐石快速回到你綁定的旅店裡了。', `FemaleText_loc7`='Cuando te quedas en una posada, descansas cómodamente. Por esta razón, estarás "más descansado" en mucho menos tiempo que si lo haces en el bosque. Cuando descansas bien, aprendes más de la experiencia.$B$BAsimismo, puedes pedirle al tabernero que te consiga una piedra de hogar para luego usarla con el fin de regresar rápidamente a la posada.' WHERE `ID`=4309;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마지막 폭탄이 설치됐어요. 물러서요!', `FemaleText_loc4`='全部准备就绪。后退！', `FemaleText_loc5`='全部準備就緒。後退!', `FemaleText_loc7`='La carga final está colocada. ¡Atrás!' WHERE `ID`=4325;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='폭파 10초 전! 물러서요!', `FemaleText_loc4`='10秒钟后爆炸！退后！', `FemaleText_loc5`='10秒鐘後爆炸!退後!', `FemaleText_loc7`='¡10 segundos para la explosión! ¡¡¡Atrás!!!' WHERE `ID`=4326;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='폭파까지 앞으로 5초!', `FemaleText_loc4`='5秒钟后爆炸！！！！', `FemaleText_loc5`='5秒鐘後爆炸!!!!', `FemaleText_loc7`='¡¡¡5 segundos para la explosión!!!' WHERE `ID`=4327;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 저 밑바닥부터 올라왔어! 우릴 막을 수는 없다!', `MaleText_loc4`='我们从地底而来！你们无法阻止我们！', `MaleText_loc5`='我們從地底而來!你們無法阻止我們!', `MaleText_loc7`='¡Venimos de abajo! ¡Nunca nos podrás detener!' WHERE `ID`=4328;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='성공이에요! 폭탄을 터뜨려서 트로그가 더 이상 위로 올라오지 못하게 만들어야겠어요.', `FemaleText_loc4`='干得漂亮！我会组织人手发动进攻，以防止更多穴居人到达地表。', `FemaleText_loc5`='幹得漂亮!我會組織人手發動進攻，以防止更多穴居怪到達地表。', `FemaleText_loc7`='¡Buen trabajo! Activaré las cargas para evitar que más troggs lleguen a la superficie.' WHERE `ID`=4329;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헉헉... 잠깐... 숨 좀... 돌리고...', `MaleText_loc4`='停下来……我要喘……喘口气……', `MaleText_loc5`='停下來...我要喘...喘口氣...', `MaleText_loc7`='Alto... tengo que recuperar... la respiración.' WHERE `ID`=4345;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선타라의 비밀은 이 땅을 벗어날 수 없다.', `MaleText_loc4`='苏塔拉的秘密将永远留在这片土地上。', `MaleText_loc5`='桑塔拉的秘密將永遠留在這片土地上。', `MaleText_loc7`='Los secretos de Suntara no dejarán estas tierras.' WHERE `ID`=4346;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라그나로스 님은 모든 것을 보신다.', `MaleText_loc4`='拉格纳罗斯无所不知，凡人。', `MaleText_loc5`='拉格納羅斯無所不知，凡人。', `MaleText_loc7`='Ragnaros lo ve todo, mortal.' WHERE `ID`=4347;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 어디로 가야 합니까, 조른?', `MaleText_loc4`='我们现在去哪里，乔恩？', `MaleText_loc5`='我們現在去哪裡，喬恩?', `MaleText_loc7`='¿Adónde me lleva ahora mi camino, Jorn?', `FemaleText_loc1`='이제 어디로 가야 합니까, 조른?', `FemaleText_loc4`='我们现在去哪里，乔恩？', `FemaleText_loc5`='我們現在去哪裡，喬恩?', `FemaleText_loc7`='¿Adónde me lleva ahora mi camino, Jorn?' WHERE `ID`=4348;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자신의 길을 당당히 가고 있군, $n. 하지만 자네는 아직도 배울 게 많다네. 불모의 땅 남부에서 다음 훈련을 받을 수 있을 걸세.', `MaleText_loc4`='你现在进展顺利，$n。但是你还有很多东西要学的，南贫瘠之地将是你获得进一步发展的地方。', `MaleText_loc5`='你現在進展順利，$n。但是你還有很多東西要學的，南貧瘠之地將是你獲得進一步發展的地方。', `MaleText_loc7`='Estás en el buen camino, $n. Pero todavía tienes mucho que aprender. Puede que tu siguiente lección se encuentre en Los Baldíos del Sur.' WHERE `ID`=4349;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 광활한 대지를 불모의 땅이라고 부르긴 하지만, 대지의 참모습을 볼 줄 아는 이에게는 생명으로 가득 찬 곳이지.', `MaleText_loc4`='虽然我们把这块土地称作贫瘠之地，但对于睿智者来说，这里到处都是生命。', `MaleText_loc5`='雖然我們把這塊土地稱作貧瘠之地，但對於睿智者來說，這裡到處都是生命。', `MaleText_loc7`='Aunque llamamos a esta tierra Los Baldíos, si se sabe donde mirar se descubre que el lugar rebosa de vida.' WHERE `ID`=4350;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 $n|1이라는;라는; 녀석에게 본때를 보여줘야겠군.', `MaleText_loc4`='我要让这个$n头上开天窗！', `MaleText_loc5`='我要讓這個$n頭上開天窗!', `MaleText_loc7`='Voy a abrir una lata encima de $n.' WHERE `ID`=4351;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부상당한 드워프에게 싸움을 다 떠맡길 작정이오?', `MaleText_loc4`='你难道要让一个受伤的矮人把一切都给你搞定么？', `MaleText_loc5`='你難道要讓一個受傷的矮人把一切都給你搞定麼?', `MaleText_loc7`='¿Vas a dejar que un enano herido te haga todo el trabajo?' WHERE `ID`=4352;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시작해보지! $n 녀석, 내 주먹 맛 좀 보라고. 주먹아, 너도 $n에게 인사해 줘야지!', `MaleText_loc4`='去死吧！$n，尝尝我的拳头！', `MaleText_loc5`='去死吧!$n，嘗嘗我的拳頭!', `MaleText_loc7`='¡Está encendido! $n, mira mis puños. Primero, di hola a mis puños, $n.' WHERE `ID`=4353;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 여기요, $n. 용광로! 지도에 표시를 하던가 해서 잊어 버리지 않도록 하시오. 나한테 무슨 일이라도 생기면 동료가 저 광산에 영원히 갇히게 될 테니까.', `MaleText_loc4`='就是这里了，$c，大熔炉！把它标在你的地图上或者做些别的事情来保证你不会忘记这个地方。如果我出了什么意外的话，那我的队伍会永远被困在矿洞里面。', `MaleText_loc5`='就是這裡了，$r，大熔爐!把它標在你的地圖上或者做些別的事情來保證你不會忘記這個地方。如果我出了什麼意外的話，那我的隊伍會永遠被困在礦坑裡面。', `MaleText_loc7`='Aquí es, $r: ¡La Caldera! Márcalo en un mapa o haz algo para no olvidarlo. Si me ocurriera algo, mi equipo quedaría atrapado para siempre en esa mina.' WHERE `ID`=4354;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앞장서시오! 이번에는 정신 바짝 차리쇼! 더 이상 혼자서 싸움을 떠맡기는 싫으니까.', `MaleText_loc4`='继续前进！现在开始要加倍小心！我不想再进行任何战斗了。', `MaleText_loc5`='繼續前進!現在開始要加倍小心!我不想再進行任何戰鬥了。', `MaleText_loc7`='¡Adelante! ¡Y esta vez estate en guardia! No quiero más combates.' WHERE `ID`=4355;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거 원, 담배를 끊던가 해야지! 잠시 숨 좀 돌립시다.', `MaleText_loc4`='我真该戒烟了！稍等片刻，让我喘口气……', `MaleText_loc5`='我真該戒煙了!稍等片刻，讓我喘口氣...', `MaleText_loc7`='¡Tengo que dejar de fumar! Necesito un momento para coger aire...' WHERE `ID`=4356;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안전한 곳에 거의 다 왔소. 여기서부터는 달려가도록 합시다. 너무 뒤처지지 마시오! 자, 갑시다!', `MaleText_loc4`='我们基本安全了。从这里开始，我们要加速跑出去。不要落在后面了！出发！', `MaleText_loc5`='我們基本安全了。從這裡開始，我們要加速跑出去。不要落在後面了!出發!', `MaleText_loc7`='Ya casi estamos a salvo. Desde aquí echamos a correr. ¡Intenta no quedarte demasiado atrás! ¡Vamos!' WHERE `ID`=4357;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저놈은 내가 처리하지...', `MaleText_loc4`='他是我的……', `MaleText_loc5`='他是我的...', `MaleText_loc7`='Es mío...' WHERE `ID`=4358;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아악! 당했다!', `MaleText_loc4`='啊~~~！他打败我了！', `MaleText_loc5`='啊～～!他打敗我了!', `MaleText_loc7`='¡ARRRRRGH! ¡Me ha atrapado!' WHERE `ID`=4359;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 냄새를 맡습니다...', `MaleText_loc4`='%s深深吸了一口气……', `MaleText_loc5`='%s對空中嗅了一嗅...', `MaleText_loc7`='%s olfatea el aire...' WHERE `ID`=4360;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 얼룩말 시체를 게걸스럽게 먹습니다!', `MaleText_loc4`='%s狼吞虎咽起来！', `MaleText_loc5`='%s大嚼大嚥了起來!', `MaleText_loc7`='¡%s devora!' WHERE `ID`=4361;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 자욱한 먼지 속으로 사라집니다.', `MaleText_loc4`='%s在云雾中消失。', `MaleText_loc5`='%s消失在煙霧中。', `MaleText_loc7`='%s desaparece en una nube de polvo.' WHERE `ID`=4362;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='문이 보이오! 이제 나갈 수 있겠군! 한데, 먼저 한숨 돌리고 갑시다. 너무 힘들군.', `MaleText_loc4`='大门就在眼前！我们就要成功了！但是首先，我真想要个呼吸器……', `MaleText_loc5`='大門就在眼前!我們就要成功了!但是首先，我要喘口氣先。', `MaleText_loc7`='¡La puerta ya está a la vista! ¡Vamos a lograrlo! Pero antes necesito un respiro.' WHERE `ID`=4363;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 네가 무슨 짓을 저지르고 있는지 알고나 있느냐! 네 운명을 위해서라도 우리가 널 처치해야겠다.', `MaleText_loc4`='你不知道你干了什么！我们要为了你的利益而毁灭你。', `MaleText_loc5`='你不知道你幹了什麼!我們要為了你的利益而毀滅你。', `MaleText_loc7`='¡No sabes lo que estás haciendo! Debemos destruirte por tu propio bien.' WHERE `ID`=4364;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타나리스의 주민들이여, 들으시오! $n|1이;가; 영광스러운 미스릴 대장조합의 일원이 되었소. 명예와 헌신, 그리고 무한한 인내심을 지닌 대장장이 $n|1을;를; 위해 우리 모두 만세를 외칩시다!', `MaleText_loc4`='听着，塔纳利斯的居民！我宣布$n已经成为秘银会的成员之一。他是一个光荣而且极具耐心的铁匠。为$n欢呼吧！', `MaleText_loc5`='聽著，塔納利斯的居民!我宣佈$n已經成為秘銀會的成員之一。他是一個光榮而且極具耐心的鐵匠。為$n歡呼吧!', `MaleText_loc7`='¡Escuchad, habitantes de Tanaris! Se hace saber que $n es miembro de la Orden del mitril. $gHerrero:Herrera; de honor, dedicación e infinita paciencia. ¡Tres hurras por $n!' WHERE `ID`=4365;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='들어갔다! 들어갔어!', `MaleText_loc4`='它在洞里！它在洞里！', `MaleText_loc5`='它在洞裡!它在洞裡!', `MaleText_loc7`='¡Está en el hoyo! ¡Está en el hoyo!' WHERE `ID`=4366;
