UPDATE `locales_broadcast_text` SET `MaleText_loc1`='슛! 오늘은 일이 잘 풀리는걸...', `MaleText_loc4`='精神抖擞一些！快一点！', `MaleText_loc5`='精神抖擻一些!快一點!', `MaleText_loc7`='¡Fuiu! La cosa está que arde, amigos.' WHERE `ID`=4372;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고오오오올인!', `MaleText_loc4`='成功了！！！！', `MaleText_loc5`='成功了!!!!', `MaleText_loc7`='¡GOOOOOOOOOOOOOOOOOOOOOL!' WHERE `ID`=4373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다섯씩 투입!', `MaleText_loc4`='五个五个地来！', `MaleText_loc5`='五個五個地來!', `MaleText_loc7`='¡En el poste, 5 a 5!' WHERE `ID`=4374;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘은 정말로 춥군. 하지만 아무리 추워도 나는 이 멋진 물건들을 팔러 나오지!', `MaleText_loc4`='啊，今天好冷啊，但是无论多么寒冷的天气都无法驱散我款待你的热情！', `MaleText_loc5`='啊，今天好冷啊，但是無論多麼寒冷的天氣都無法驅散我款待你的熱情!', `MaleText_loc7`='Vaya, qué frío hace hoy, pero no importa, ¡aquí estoy yo con mis estupendas mercancías!' WHERE `ID`=4375;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 이 지역에서 최고급 원단의 천과 가죽 옷을 팔고 있소이다!', `MaleText_loc4`='我出售山谷这一边最好的布料和皮革服饰！', `MaleText_loc5`='我出售山谷這一邊最好的布料和皮革服飾!', `MaleText_loc7`='¡He vendido las mejores prendas de género y cuero a este lado del valle!' WHERE `ID`=4376;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='던 모로에서 쌀쌀한 하루를 잘 시작하려면 뜨거운 새벽주 만한 게 없소이다!', `MaleText_loc4`='在丹莫罗寒冷的日子里，没有什么比热酒更好的东西了！', `MaleText_loc5`='在丹莫洛寒冷的日子裡，沒有什麼比熱酒更好的東西了!', `MaleText_loc7`='¡No hay nada como un poco de albaza hirviendo en un día helado de Dun Morogh para empezar el día con buen pie!' WHERE `ID`=4377;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앗.. 뜨뜨뜨거워! 이걸 마시고도 정신이 들지 않는다는 건 말이 안 되지!', `MaleText_loc4`='哦，热啊热！如果这样的热度都不能让你跳起来，那你简直就是块石头了！', `MaleText_loc5`='哦，熱啊熱!如果這樣的熱度都不能讓你跳起來，那你簡直就是塊石頭了!', `MaleText_loc7`='¡Ufffff, qué caliente está! ¡Si esto no te pone las pilas, no sé que lo hará!' WHERE `ID`=4378;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 가볼 때가 된 것 같군, $n. 언젠가 꼭 다시 만나게 될 거요. 행운을 빌겠소!', `MaleText_loc4`='我在这里已经待够了，$n。我相信我们会再见的。祝你好运！', `MaleText_loc5`='我在這裡已經待夠了，$n。我相信我們會再見的。祝你好運!', `MaleText_loc7`='Hemos estado aquí bastante tiempo, $n. Seguro que nos volveremos a ver. ¡Suerte!' WHERE `ID`=4379;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이단자!', `FemaleText_loc4`='异教徒！', `FemaleText_loc5`='異教徒!', `FemaleText_loc7`='¡Infieles!' WHERE `ID`=4380;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='감히 우리의 기도를 방해하다니! 처형하겠다!', `FemaleText_loc4`='你敢打断我们的祈祷？处决他们！', `FemaleText_loc5`='你敢打斷我們的祈禱?處決他們!', `FemaleText_loc7`='¿Osáis interrumpir nuestras plegarias? ¡Ejecutadlos!' WHERE `ID`=4381;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='라그나로스 님께서 좋아하실 제물이로군.', `FemaleText_loc4`='你的死将是对拉格纳罗斯的一次献祭。', `FemaleText_loc5`='你的死將是對拉格納羅斯的一次獻祭。', `FemaleText_loc7`='Seréis el sacrificio perfecto para Ragnaros.' WHERE `ID`=4382;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘 됐어. 신선한 피를 제물로 올릴 수 있겠어.', `FemaleText_loc4`='太好了，终于有新鲜的血了。', `FemaleText_loc5`='太好了，終於有新鮮的血了。', `FemaleText_loc7`='Excelente, ha llegado sangre fresca.' WHERE `ID`=4383;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛나는 조각에 대해 얘기해주세요.', `MaleText_loc4`='告诉我关于发光的碎片的事情。', `MaleText_loc5`='告訴我關於發光的裂片的事情。', `MaleText_loc7`='Háblame del fragmento resplandeciente.', `FemaleText_loc1`='빛나는 조각에 대해 얘기해주세요.', `FemaleText_loc4`='告诉我关于发光的碎片的事情。', `FemaleText_loc5`='告訴我關於發光的裂片的事情。', `FemaleText_loc7`='Háblame del fragmento resplandeciente.' WHERE `ID`=4384;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n, 당신은 다른 이들에 비해 많이 배운 편이랍니다. 이 세계의 모든 원소들을 존중하세요. 그러면 당신의 눈은 더욱 위대한 것을 볼 수 있게 될 거예요.', `FemaleText_loc4`='你已经比许多人都走得更远了，$n。敬畏大自然的力量，你就会取得比大多数人都要伟大的成就。', `FemaleText_loc5`='你已經比許多人都走得更遠了，$n。敬畏大自然的力量，你就會取得比大多數人都要偉大的成就。', `FemaleText_loc7`='Has llegado más lejos que nadie, $n. Respeta los elementos que te rodean y te irá mejor que a nadie.' WHERE `ID`=4385;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일을 마무리 지으러 돌아왔다고? <비웃으며> 흑요암, 일어나서 저자를 처치하라!', `MaleText_loc4`='你回来了？<拉索里克笑了起来。>奥比斯顿，消灭他们！', `MaleText_loc5`='你回來了?<拉索裡克笑了起來。>奧比斯頓，消滅他們!', `MaleText_loc7`='¿Has vuelto para terminar el trabajo? <Lathoric se ríe.> ¡Obsidion, álzate y aniquílalos!' WHERE `ID`=4390;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 할 일은 끝났다. 운명을 맞이할 준비나 해라!', `MaleText_loc4`='你的任务完成了。准备受死吧。', `MaleText_loc5`='你的任務完成了。準備受死吧。', `MaleText_loc7`='Has terminado tu tarea. ¡Prepárate para morir!' WHERE `ID`=4391;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흑요암이여, 일어나서 너의 주인을 모시거라!', `MaleText_loc4`='出来吧，奥比斯顿，保护你的主人！', `MaleText_loc5`='出來吧，奧比斯頓，保護你的主人!', `MaleText_loc7`='¡Obsidion, álzate y aniquílalos!' WHERE `ID`=4392;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='박수! 박수! 아주 재미있는 연극이군. 내가 죽은 줄 알았나?', `MaleText_loc4`='太好了！太棒了！完美的演出。你说什么？你以为我死了？', `MaleText_loc5`='太好了!太棒了!完美的演出。你說什麼?你以為我死了?', `MaleText_loc7`='¡Bravo! ¡Bravo! Un buen espectáculo. ¿Qué? ¿Creías que estaba muerto?' WHERE `ID`=4393;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청한 놈들... 동생의 나약한 감정을 이용하면 구조 대원을 보낼 줄 알았지.', `MaleText_loc4`='笨蛋，如果我拿我兄弟脆弱的感情开玩笑，他会被送去急救的。', `MaleText_loc5`='笨蛋，如果我拿我兄弟脆弱的感情開玩笑，他會被送去急救的。', `MaleText_loc7`='Idiotas, sabía que si tocaba la fibra sensible de mi hermano, traería ‘rescatadores’.' WHERE `ID`=4394;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너를 이용해 어리석은 황혼의 망치단 녀석들에게 마지막 선타라 비석을 가지고 오게 하는 건 식은 죽 먹기였어.', `MaleText_loc4`='我轻松地让你从暮光之锤的那群笨蛋手里得到了最后一块苏塔拉之石。', `MaleText_loc5`='我輕輕鬆鬆就設計你從暮光之錘的那群笨蛋手裡得到了最後一塊桑塔拉之石。', `MaleText_loc7`='Qué fácil fue manipularos hasta recobrar la última piedra de Suntara de esos imbéciles del Martillo Crepuscular.' WHERE `ID`=4395;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검댕가루 작업현장에서 우연히 선타라 비석을 찾았을 때 라그나로스 님의 힘이 내 온몸과 마음을 휘감았지. 라그나로스께서 내 삶에 의미를 주신 거야.', `MaleText_loc4`='当我偶然发现苏塔拉之石的时候，拉格纳罗斯的力量从我身体中澎湃而过。正是拉格纳罗斯给了我方向。', `MaleText_loc5`='當我偶然在煤渣挖掘場發現桑塔拉之石的時候，拉格納羅斯的力量從我身體中澎湃而過。正是拉格納羅斯給了我方向。', `MaleText_loc7`='Cuando me topé con las piedras de Suntara en la excavación de Limugre, el poder de Ragnaros me poseyó. Fue Ragnaros quien me dio un propósito.' WHERE `ID`=4396;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흑요암을 만든다는 것은 라그나로스 님의 뜻이었지. 흑요암이 검은바위 첨탑에서 검은바위 오크를 쳐부수면, 우리 동지들은 불타오르는 심연에서 하나가 될 수 있어.', `MaleText_loc4`='拉格纳罗斯按照自己的意愿创造了奥比斯顿。奥比斯顿会毁掉黑石塔的黑石兽人，将我们和那些处于火热深渊中的兄弟们联合起来。', `MaleText_loc5`='拉格納羅斯按照自己的意願創造了奧比斯頓。奧比斯頓會毀掉黑石塔的黑石獸人，將我們和那些處於火熱深淵中的兄弟們聯合起來。', `MaleText_loc7`='Gracias a la voluntad de Ragnaros construimos a Obsidion. Obsidion destruirá a los orcos Roca Negra de la cumbre de Roca Negra, uniéndonos con nuestros hermanos en las profundidades ardientes.' WHERE `ID`=4397;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 마침내 내가 불의 수행사제로 다시 태어났을 때 라그나로스께서 내게 이름을 하사하셨지. 라소릭... 검은 라소릭이라고 말이야.', `MaleText_loc4`='最终，是拉格纳罗斯在我重生的时候为我命名，我是火焰的侍奉者，黑衣拉索里克。', `MaleText_loc5`='最終，是拉格納羅斯在我重生的時候為我命名，我是火焰的侍奉者，黑衣拉索里克。', `MaleText_loc7`='Y finalmente, fue Ragnaros quien me nombró cuando renací como acólito de fuego: Lathoric... Lathoric el Negro.' WHERE `ID`=4398;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 내는 웃음소리가 멀어져 갑니다...', `MaleText_loc4`='%s的笑声渐渐远去……', `MaleText_loc5`='%s的笑聲漸遠漸去...', `MaleText_loc7`='La risa de %s se desvanece...' WHERE `ID`=4399;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 제단은 마치 살아있는 듯, 당신에게 손짓을 하는 느낌이 듭니다.', `MaleText_loc4`='祭坛似乎在召唤你，好像它具有生命一样。', `MaleText_loc5`='祭壇似乎在召喚你，好像它具有生命一樣。', `MaleText_loc7`='El altar parece hacerte señas como si estuviera vivo.' WHERE `ID`=4400;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선타라 비석에 손을 대고 검은 라소릭과 그의 수호자 흑요암을 불러냅니다.', `MaleText_loc4`='触摸苏塔拉之石，召唤黑衣拉索里克和他的守卫者奥比斯顿。', `MaleText_loc5`='觸摸桑塔拉之石，召喚黑衣拉索里克和他的守護者奧比斯頓。', `MaleText_loc7`='Toca la piedra de Suntara e invoca a Lathoric el Negro y a su guardián, Obsidion.', `FemaleText_loc1`='선타라 비석에 손을 대고 검은 라소릭과 그의 수호자 흑요암을 불러냅니다.', `FemaleText_loc4`='触摸苏塔拉之石，召唤黑衣拉索里克和他的守卫者奥比斯顿。', `FemaleText_loc5`='觸摸桑塔拉之石，召喚黑衣拉索里克和他的守護者奧比斯頓。', `FemaleText_loc7`='Toca la piedra de Suntara e invoca a Lathoric el Negro y a su guardián, Obsidion.' WHERE `ID`=4401;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n, 제가 아는 드루이드라면 당신이 찾은 이 조각에 대해 좀 더 자세히 알고 있을 거예요. 통곡의 동굴 위에 있는 언덕 꼭대기에서 살고 있으니, 그녀를 찾아가 보십시오.', `FemaleText_loc4`='我认识一个住在哀嚎洞穴山顶的德鲁伊，$n。她也许告诉你更多关于这块碎片的信息。', `FemaleText_loc5`='我認識一個住在哀嚎洞穴山頂的德魯伊，$n。她也許告訴你更多關於這塊裂片的資訊。', `FemaleText_loc7`='Sé de un druida que vive en la cima de la colina que está encima de las Cuevas de los Lamentos, $n. Tal vez pueda decirte algo más sobre este fragmento que has encontrado.' WHERE `ID`=4402;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경비병! 도와줘요!', `MaleText_loc4`='卫兵！救救我！', `MaleText_loc5`='守衛!救救我!', `MaleText_loc7`='¡Guardias! ¡Ayudadme!', `FemaleText_loc1`='경비병! 도와줘요!', `FemaleText_loc4`='卫兵！救救我！', `FemaleText_loc5`='守衛!救救我!', `FemaleText_loc7`='¡Guardias! ¡Ayudadme!' WHERE `ID`=4403;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, $n. 엘룬의 지혜가 그대의 마음을 인도하시길. 제가 도와드릴 일이라도 있습니까?', `FemaleText_loc4`='你好，$n。愿月神的智慧指引你的心灵。我能帮你做些什么吗？', `FemaleText_loc5`='你好，$n。願伊露恩的智慧指引你的心靈。我能幫你做些什麼嗎?', `FemaleText_loc7`='Buenas, $n. Que la sabiduría de Elune guíe tu mano y tu corazón. ¿Cómo puedo ayudarte hoy?' WHERE `ID`=4404;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, 아스타리. 훈련을 받고 싶습니다.', `MaleText_loc4`='向你致敬，阿斯塔利。我需要接受训练。', `MaleText_loc5`='向你致敬，阿斯塔利。我需要接受訓練。', `MaleText_loc7`='Saludos Astarii. Necesito instrucción.', `FemaleText_loc1`='안녕하십니까, 아스타리. 훈련을 받고 싶습니다.', `FemaleText_loc4`='向你致敬，阿斯塔利。我需要接受训练。', `FemaleText_loc5`='向你致敬，阿斯塔利。我需要接受訓練。', `FemaleText_loc7`='Saludos, Astarii. Necesito instrucción.' WHERE `ID`=4405;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기다리고 있었소, $n. 끝까지 해내서 다행이로군. 물건은 가지고 있소?', `MaleText_loc4`='我一直在等你，$n。很高兴看到你。你把货带来了吗？', `MaleText_loc5`='我一直在等你，$n。很高興看到你。你把貨帶來了嗎?', `MaleText_loc7`='Te he estado esperando, $n. Me alegro de que lo hayas logrado. ¿Tienes el cargamento?' WHERE `ID`=4406;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엘룬이시여, 감사합니다! 누가 저를 찾아온 게 얼마 만인지 모르겠군요.', `MaleText_loc4`='赞美艾露恩！好些年都没有人来拜访我了。', `MaleText_loc5`='讚美伊露恩!好些年都沒有人來拜訪我了。', `MaleText_loc7`='¡Alabada sea Elune! Hace muchos años que no recibo visitantes.' WHERE `ID`=4407;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얘기를 듣고 싶습니다.', `MaleText_loc4`='我想要听听你的故事。', `MaleText_loc5`='我想要聽聽你的故事。', `MaleText_loc7`='Me gustaría oír tu relato.', `FemaleText_loc1`='얘기를 듣고 싶습니다.', `FemaleText_loc4`='我想要听听你的故事。', `FemaleText_loc5`='我想要聽聽你的故事。', `FemaleText_loc7`='Me gustaría oír tu relato.' WHERE `ID`=4408;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠해안의 젊은 나이트 엘프였던 시절, 저는 황혼의 망치단이라는 불미스러운 작자들과 만나게 되었습니다. 그들과 어떻게 어울리다 보니 친해졌고, 젊은 혈기에 부끄럽게도 엘룬에 대한 신앙을 저버리고 황혼의 망치단을 따르게 되었지요.$B$B꿈속에서 엘룬 여신님의 환영을 만나고서야 스스로 그릇된 길을 가고 있음을 깨달았습니다. 그 이후, 저는 고대 신을 섬기는 자로 다시 태어났습니다.$B$B그리고 회개의 뜻으로 엘룬께 올리는 기도문을 만들기 시작했습니다.', `MaleText_loc4`='作为黑海岸的一名年轻的暗夜精灵，我遇到了一队暮光之锤的成员。他们待我如同亲人，因此我背叛了对艾露恩的信仰，听信了他们的蛊惑之言。$B$B直到艾露恩的幻影从我眼前闪过，我才幡然省悟。$B$B我满怀悔恨，开始向艾露恩祈祷。', `MaleText_loc5`='作為黑海岸的一名年輕的夜精靈，我遇到了一隊暮光之錘的成員。他們待我如同親人，因此我背叛了對伊露恩的信仰，聽信了暮光之錘的蠱惑之言。$B$B直到伊露恩的預兆顯露在我眼前，我才幡然省悟，驚覺自己已經墮落成上古諸神的追隨者。$B$B我滿懷悔恨，開始向伊露恩祈禱。', `MaleText_loc7`='Cuando era un joven elfo de la noche en Costa Oscura, me crucé con un grupo de individuos desagradables conocidos como el Martillo Crepuscular. Unos cuantos de ellos entablaron amistad conmigo y, vergonzosamente, terminé perdiendo la fe en Elune y abrazando el rencor del Martillo Crepuscular.$B$BNo fue sino hasta que tuve una visión procedente de Elune, que desperté del malestar en que había caído como seguidor de dioses antiguos.$B$BArrepentido, empecé a rezar invocando a Elune.' WHERE `ID`=4409;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 말씀하십시오, 잠마엘.', `MaleText_loc4`='萨麦尔，请继续。', `MaleText_loc5`='薩麥爾，請繼續。', `MaleText_loc7`='Zamael, continúa, por favor.', `FemaleText_loc1`='계속 말씀하십시오, 잠마엘.', `FemaleText_loc4`='萨麦尔，请继续。', `FemaleText_loc5`='薩麥爾，請繼續。', `FemaleText_loc7`='Zamael, continúa, por favor.' WHERE `ID`=4410;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 순금 서판에다 양심의 가책, 부끄러움, 후회, 그리고 슬픔을 새겼습니다. 그런데 그 서판을 발견한 황혼의 망치단은 제게 신성 모독자라는 낙인을 찍었습니다. 엘룬께 올리는 기도문을 완성하지도 못한 채 그 자리에서 처형되고 만 것이지요. 이제는 영혼이 이 세계에 구속되어 황천으로 갈 수도 없게 되었습니다. 황혼의 망치단을 배신하는 자들에 대한 경고로 이 우리에 갇히게 되었습니다.', `MaleText_loc4`='我的自责、羞愧、懊悔和悲伤全都刻在这块纯金石板上。不幸的是，暮光之锤找到了石板，并认定我是诅咒者。我被立即处死，而那时我对艾露恩的祷告还没有做完。现在我已经成为了一个游荡的幽灵，无法降入扭曲虚空；我被关在笼子里，用来警告那些试图背叛暮光之锤的人。', `MaleText_loc5`='我的自責、羞愧、懊悔和悲傷全都刻在這塊純金石板上。不幸的是，暮光之錘找到了石板，並認定我是詛咒者。我被立即處死，而那時我對伊露恩的禱告還沒有做完。現在我已經成為了一個遊蕩的幽靈，無法降入扭曲虛空;我被關在籠子裡，用來警告那些試圖背叛暮光之錘的人。', `MaleText_loc7`='Grabada en una tablilla de oro puro quedó la prueba de mi arrepentimiento, vergüenza y tristeza. Desafortunadamente, los miembros del Martillo Crepuscular encontraron la tablilla y me llamaron blasfemo. Me ejecutaron inmediatamente y no pude terminar mis plegarias a Elune. Ahora estoy unido a este mundo como espíritu, incapaz de bajar al Infierno; atrapado en esta jaula como advertencia para todo aquel que ose traicionar la fe del Martillo Crepuscular.' WHERE `ID`=4411;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠시 생각을 좀 해보겠습니다, 잠마엘.', `MaleText_loc4`='让我考虑一下，萨麦尔。', `MaleText_loc5`='讓我考慮一下，薩麥爾。', `MaleText_loc7`='Déjame pensar en ello, Zamael.', `FemaleText_loc1`='잠시 생각을 좀 해보겠습니다, 잠마엘.', `FemaleText_loc4`='让我考虑一下，萨麦尔。', `FemaleText_loc5`='讓我考慮一下，薩麥爾。', `FemaleText_loc7`='Déjame pensar en ello, Zamael.' WHERE `ID`=4412;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라제는 집에 갈 시간이다. 안녕, $R.', `MaleText_loc4`='拆毁者现在要回家了。再见，$c。', `MaleText_loc5`='拆毀者現在要回家了。再見，$r。', `MaleText_loc7`='Arrasa tener que ir a casa. Hasta la vista, $r.' WHERE `ID`=4413;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그늘거미 밀렵꾼이 가까이 있을 때 이 지휘의 지팡이를 라제에게 사용하십시오. 녀석들, 이 땅을 침범하기로 결정한 날을 후회하게 될 겁니다.', `FemaleText_loc4`='当你靠近暗影蛛丝偷猎者的时候，对拆毁者使用命令法杖，这些盗贼会为自己的行为感到后悔的。', `FemaleText_loc5`='當你靠近暗影蛛絲盜獵者的時候，對拆毀者使用命令法杖，這些盜賊會為自己的行為感到後悔的。', `FemaleText_loc7`='Utiliza este Bastón de mando con Arrasa cuando estés cerca de los Cazadores de Sedaumbría y él hará que lamenten el día que decidieron entrar en estas tierras.' WHERE `ID`=4414;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='작고 귀여운 $r|1아;야;, 안녕. 라제 이제 그만 갈래!', `MaleText_loc4`='再见，小$c。拆毁者现在就要走了。', `MaleText_loc5`='再見，小$r。拆毀者現在就要走了。', `MaleText_loc7`='Adiós, $gpequeño:pequeña; $r. Arrasa irse ahora.' WHERE `ID`=4415;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고대의 학카르 제단이 방 입구 가까이 놓여 있습니다.$B$B제단 위를 살펴보니 커다란 뱀 모양의 석상이 놓여 있고 그 모양은 제단 위에 있는 모양과 굉장히 흡사합니다. 그 둘에는 뭔가 관련이 있는 듯해 보입니다.', `MaleText_loc4`='古老的哈卡祭坛静静地矗立在房间的入口处。$B$B你注意到阳台上有一尊巨大的毒蛇雕像立在那儿。它看上去跟祭坛上的雕像非常相似。它们之间一定有什么联系……', `MaleText_loc5`='古老的哈卡祭壇靜靜地矗立在房間的入口處。$B$B你注意到陽臺上有一尊巨大的毒蛇雕像立在那兒。它看起來跟祭壇上的雕像非常相似。它們之間一定有什麼聯繫...', `MaleText_loc7`='El antiguo altar de Hakkar permanece en silencio junto a la entrada del recinto.$B$BSi observas los balcones que están encima, advertirás que una gran estatua con forma de serpiente descansa en cada uno de ellos. Las estatuas son muy similares a las que están en el altar que tienes delante. Guardan algún tipo de relación...', `FemaleText_loc1`='고대의 학카르 제단이 방 입구 가까이 놓여 있습니다.$B$B제단 위를 살펴보니 커다란 뱀 모양의 석상이 놓여 있고 그 모양은 제단 위에 있는 모양과 굉장히 흡사합니다. 그 둘에는 뭔가 관련이 있는 듯해 보입니다.', `FemaleText_loc4`='古老的哈卡祭坛静静地矗立在房间的入口处。$B$B你注意到阳台上有一尊巨大的毒蛇雕像立在那儿。它看上去跟祭坛上的雕像非常相似。它们之间一定有什么联系……', `FemaleText_loc5`='古老的哈卡祭壇靜靜地矗立在房間的入口處。$B$B你注意到陽臺上有一尊巨大的毒蛇雕像立在那兒。它看起來跟祭壇上的雕像非常相似。它們之間一定有什麼聯繫...', `FemaleText_loc7`='El antiguo altar de Hakkar permanece en silencio junto a la entrada del recinto.$B$BSi observas los balcones que están encima, advertirás que una gran estatua con forma de serpiente descansa en cada uno de ellos. Las estatuas son muy similares a las que están en el altar que tienes delante. Guardan algún tipo de relación...' WHERE `ID`=4416;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제단과 석상은 어떻게 관련되어 있습니까?', `MaleText_loc4`='祭坛和雕像会有什么联系？', `MaleText_loc5`='祭壇和雕像會有什麼聯繫?', `MaleText_loc7`='¿De qué manera podrían estar relacionados el altar y las estatuas?', `FemaleText_loc1`='제단과 석상은 어떻게 관련되어 있습니까?', `FemaleText_loc4`='祭坛和雕像会有什么联系？', `FemaleText_loc5`='祭壇和雕像會有什麼聯繫?', `FemaleText_loc7`='¿De qué manera podrían estar relacionados el altar y las estatuas?' WHERE `ID`=4417;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수수께끼를 시작하고 싶습니다.', `MaleText_loc4`='我想着手解开雕像之谜。', `MaleText_loc5`='我想著手解開雕像之謎。', `MaleText_loc7`='Quiero empezar con el rompecabezas de la estatua.', `FemaleText_loc1`='수수께끼를 시작하고 싶습니다.', `FemaleText_loc4`='我想着手解开雕像之谜。', `FemaleText_loc5`='我想著手解開雕像之謎。', `FemaleText_loc7`='Quiero empezar con el rompecabezas de la estatua.' WHERE `ID`=4418;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뮤세크에 대해 더 얘기해 주십시오.', `MaleText_loc4`='告诉我更多关于灵魂精华的东西。', `MaleText_loc5`='告訴我更多關於靈魂精華的東西。', `MaleText_loc7`='Háblame más sobre el muisek.', `FemaleText_loc1`='뮤세크에 대해 더 얘기해 주십시오.', `FemaleText_loc4`='告诉我更多关于灵魂精华的东西。', `FemaleText_loc5`='告訴我更多關於靈魂精華的東西。', `FemaleText_loc7`='Háblame más sobre el muisek.' WHERE `ID`=4419;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 지역에는 나이트 엘프의 동맹족으로 보이는 많은 생물들이 살고 있네. 엘프는 이 생물들의 내면에 숨겨진 힘을 이용해 왔는데 이제는 호드도 이를 실현할 때일세. 나는 이 힘을 모아 우리 동족에게 유리하게 사용하는 방법을 알아냈네.$B$B내 말을 의심하지 말게, $n. 날 도와주면 내 말이 사실이라는 것을 알게 될 것일세.', `MaleText_loc4`='这个地区有许多生物都是暗夜精灵的同盟。精灵们可以借助这些生物的能量来为自己效劳。部落也应该拥有这种能力。我想到一个方法，可以捕捉到这种能量并为我们所用。$B$B不要怀疑我告诉你的事情，$n。帮助我，你就会知道我所说的都是实话。', `MaleText_loc5`='這個地區有許多生物都是夜精靈的同盟。精靈們可以借助這些生物的能量來為自己效勞。部落也應該擁有這種能力。我想到一個方法，可以捕捉到這種能量並為我們所用。$B$B不要懷疑我告訴你的事情，$n。幫助我，你就會知道我所說的都是實話。', `MaleText_loc7`='En esta área existen muchas criaturas consideradas aliadas de los elfos de la noche. Los elfos han tenido acceso al poder que alberga cada una de estas criaturas. Es hora de que la Horda disfrute con el mismo privilegio. He ideado un modo de hacernos con este poder y usarlo en beneficio propio.$B$BNo dudes de lo que te digo, $n. Ayúdame y verás que digo la verdad.' WHERE `ID`=4420;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네의 몸은 이제 새로운 물건으로 만들어질 것이오, $n. 우리 암거래상단에서는 그걸 "신체 공예"라고 부르지, 하하!', `MaleText_loc4`='我们会对你的尸体上进行妥善处理的，$n。我们称其为“分尸”。', `MaleText_loc5`='我們會對你的屍體上進行妥善處理的，$n。我們稱其為「分屍」。', `MaleText_loc7`='Van a iniciar un nuevo oficio en torno a tus restos, $n. La llamaremos ‘trabajar la carne’.' WHERE `ID`=4421;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 그냥 사냥과 채집을 좀 하는 것뿐이라고. 그게 뭐가 잘못됐다는 거요?', `MaleText_loc4`='他们所做的一切只是打打猎，收集些东西。他们究竟做错了什么？？', `MaleText_loc5`='他們所做的一切只是打打獵，收集些東西。他們究竟做錯了什麼??', `MaleText_loc7`='Todo lo que han hecho es cazar y recolectar algo. ¿¿Qué hay de malo??' WHERE `ID`=4422;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='재봉술을 익힌 친구인가? 이 비즈클릭이 당신에게 필요한 물건을 거의 다 가지고 있을걸. 한번 훑어보고 사고 싶은 게 있거든 말만 하라고, $n.', `MaleText_loc4`='如果你是个裁缝，维兹格里克肯定有你想要的东西！随便看看，$n，想要买什么东西就和我说！', `MaleText_loc5`='如果你是個裁縫，維茲格里克肯定有你想要的東西!隨便看看，$n，想要買什麼東西就和我說!', `MaleText_loc7`='Si la sastrería es lo que te gusta, Vizzklick tiene definitivamente todo lo que necesitas para ello. Echa un vistazo a tu alrededor, $n, y dime si deseas comprar algo.' WHERE `ID`=4423;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물건을 보여주십시오.', `MaleText_loc4`='我想要看看你出售的东西。', `MaleText_loc5`='我想要看看你出售的東西。', `MaleText_loc7`='Me gustaría echar un vistazo a tus mercancías.', `FemaleText_loc1`='물건을 보여주십시오.', `FemaleText_loc4`='我想要看看你出售的东西。', `FemaleText_loc5`='我想要看看你出售的東西。', `FemaleText_loc7`='Me gustaría echar un vistazo a tus mercancías.' WHERE `ID`=4424;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='짐을 챙기시오, $n! 이글거리는 협곡에 있는 닐리스 로크라브에게서 방금 전갈이 왔는데 암거래상단이 용광로 중심에 사업 본부를 세웠다고 하오. 이글거리는 협곡에서 닐리스 로크라브를 찾아 자세히 알아보시오!', `MaleText_loc4`='收拾你的行装，$n！我从灼热峡谷那边的尼莉丝·洛克拉夫收到消息说，有个被称作“黑市组织”的团体正在大熔炉一带运作。到灼热峡谷去找到尼莉丝·洛克拉夫，然后把那个黑市组织连窝端掉。', `MaleText_loc5`='收拾你的行裝，$n!我從灼熱峽谷那邊的尼莉絲·洛克拉夫收到消息說，有個被稱作「暗黑拍賣會」的組織正在大熔爐一帶運作。到灼熱峽谷去找到尼莉絲·洛克拉夫，然後把那個暗黑拍賣會一網打盡。', `MaleText_loc7`='¡Coge tus cosas, $n! Nilith Lokrak de la Garganta de Fuego acaba de comunicarme que el Mercado Negro ha establecido sus operaciones en el corazón de La Caldera. ¡Encuentra a Nilith Lokrav en La Garganta de Fuego y entérate de todo!' WHERE `ID`=4425;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방 안에 한 줄기 밝은 빛이 나타나더니 곧 사라집니다. 또 다른 빛 줄기가 나타났다 사라지기를 반복합니다.$B$B어떤 순서를 보여주고 있는 듯합니다.', `MaleText_loc4`='房间中出现一道明亮的光束，随即消失了。然后你注意到了另一道光束……又一道光束。$B$B它们似乎拼接出了某种图案。', `MaleText_loc5`='房間中出現一道明亮的光束，隨即消失了。然後你注意到了另一道光束...又一道光束。$B$B它們似乎拼接出了某種圖案。', `MaleText_loc7`='Una luz brillante aparece en la habitación y luego vuelve a desaparecer. Luego adviertes otro rayo... y luego otro.$B$BAl parecer, te quieren mostrar algo utilizando un patrón.', `FemaleText_loc1`='방 안에 한 줄기 밝은 빛이 나타나더니 곧 사라집니다. 또 다른 빛 줄기가 나타났다 사라지기를 반복합니다.$B$B어떤 순서를 보여주고 있는 듯합니다.', `FemaleText_loc4`='房间中出现一道明亮的光束，随即消失了。然后你注意到了另一道光束……又一道光束。$B$B它们似乎拼接出了某种图案。', `FemaleText_loc5`='房間中出現一道明亮的光束，隨即消失了。然後你注意到了另一道光束...又一道光束。$B$B它們似乎拼接出了某種圖案。', `FemaleText_loc7`='Una luz brillante aparece en la habitación y luego vuelve a desaparecer. Luego adviertes otro rayo... y luego otro.$B$BAl parecer, te quieren mostrar algo utilizando un patrón.' WHERE `ID`=4426;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='석상이 모두 제자리에 있습니다. 수수께끼를 풀어 보십시오.', `MaleText_loc4`='所有的雕像都已经就位，你可以开始解谜了。', `MaleText_loc5`='所有的雕像都已經就位，你可以開始解謎了。', `MaleText_loc7`='Todas las estatuas están en su sitio, puedes comenzar el rompecabezas.', `FemaleText_loc1`='석상이 모두 제자리에 있습니다. 수수께끼를 풀어 보십시오.', `FemaleText_loc4`='所有的雕像都已经就位，你可以开始解谜了。', `FemaleText_loc5`='所有的雕像都已經就位，你可以開始解謎了。', `FemaleText_loc7`='Todas las estatuas están en su sitio, puedes comenzar el rompecabezas.' WHERE `ID`=4427;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 분노에 휩싸여 광폭해집니다!', `MaleText_loc4`='%s变得狂暴了！', `MaleText_loc5`='%s變得狂暴盛怒了!', `MaleText_loc7`='¡%s monta en cólera!', `FemaleText_loc1`='%s|1이;가; 분노에 휩싸여 광폭해집니다!', `FemaleText_loc4`='%s变得狂暴了！', `FemaleText_loc5`='%s變得狂暴盛怒了!', `FemaleText_loc7`='¡%s monta en cólera!' WHERE `ID`=4428;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반드시 복수하고 말겠소.', `MaleText_loc4`='我要复仇。', `MaleText_loc5`='你不知道自己在做什麼，石臟!把我銬在這裡，你會害死地深之源和我們所有人!', `MaleText_loc7`='La venganza será mía.' WHERE `ID`=4429;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 그토록 복수를 열망하고 계십니까?', `MaleText_loc4`='可以告诉我究竟是什么在驱使你去复仇吗？', `MaleText_loc5`='可以告訴我究竟是什麼在驅使你去復仇嗎?', `MaleText_loc7`='Dime, ¿qué impulsa esta venganza?', `FemaleText_loc1`='왜 그토록 복수를 열망하고 계십니까?', `FemaleText_loc4`='可以告诉我究竟是什么在驱使你去复仇吗？', `FemaleText_loc5`='可以告訴我究竟是什麼在驅使你去復仇嗎?', `FemaleText_loc7`='Dime, ¿qué te impulsa esta venganza?' WHERE `ID`=4430;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 아버지께서 용광로에 사는 그 쓰레기 같은 것들에게 살해되셨소. 스톰윈드의 집정관들에게 도와 달라고 간청했지만 들은 척도 않더군. 자기네들의 귀한 군대를 보내려고 하지 않는 것 같았소. 아니, 아예 그런 곳이 존재한다는 사실 자체를 무시하고 싶어 했지.$B$B그래서 이토록 복수를 원하는 거요, $n. 아주 간단한 이유지. 세상에 이보다 더 확고한 이유가 있겠소?', `MaleText_loc4`='我父亲被大熔炉中的恶棍杀害了。我恳求暴风城给予援助，但是他们根本没有理睬。不仅如此，他们甚至不愿意承认这个地区的存在，更不要说派遣军队来匡扶正义了。$B$B我要报仇，$c。这世界上还有比这更强烈的理由吗？', `MaleText_loc5`='我父親被大熔爐中的惡棍殺害了。我懇求暴風城給予援助，但是他們根本沒有理睬。不僅如此，他們甚至不願意承認這個地區的存在，更不要說派遣軍隊來匡扶正義了。$B$B我要報仇，$r。這世界上還有比這更強烈的理由嗎?', `MaleText_loc7`='La escoria que vive en la Caldera asesinó a mi padre. El Magistrado de Ventormenta hizo oídos sordos a mis súplicas de ayuda. No, no quieren admitir que esta parte del mundo existe y mucho menos enviar a su valiosa milicia para administrar justicia.$B$BBusco venganza, $r, llanamente. ¿Existe una causa más apasionada en este mundo?' WHERE `ID`=4431;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말씀 계속하십시오.', `MaleText_loc4`='请继续。', `MaleText_loc5`='請繼續。', `MaleText_loc7`='Continúa, por favor.', `FemaleText_loc1`='말씀 계속하십시오.', `FemaleText_loc4`='请继续。', `FemaleText_loc5`='請繼續。', `FemaleText_loc7`='Continúa, por favor.' WHERE `ID`=4432;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보다시피 난 덩치만 좋고 실력은 부족한 수습기사일 뿐이오. 라그나로스가 지배하는 검은무쇠 드워프와 그 야수들을 나 혼자 무찌른다는 것은 말도 안 되는 일이지. 하지만 당신처럼 용감하고 야심 찬 분이라면 용광로의 적을 문제없이 처치할 수 있을 거라는 확신이 드는군. 날 도와주면 꿈에서도 얻지 못할 부와 명예를 얻게 해주겠소.', `MaleText_loc4`='正如你所见的一样，我只不过是单枪匹马。黑铁矮人和拉格纳罗斯的爪牙可以轻松把我摆平，但是我对于像你这样勇敢的冒险者充满了信心，你一定可以把大熔炉里的那些东西全部搞定的。如果你愿意帮助我，我会给予你丰富的奖励，那些奖励将是你做梦也想不到的。', `MaleText_loc5`='正如你所見的一樣，我只不過是單槍匹馬。黑鐵矮人和拉格納羅斯的爪牙可以輕鬆把我擺平，但是我對於像你這樣勇敢的冒險者充滿了信心，你一定可以把大熔爐裡的那些東西全部搞定的。如果你願意幫助我，我會給予你豐富的獎勵，那些獎勵將是你做夢也想不到的。', `MaleText_loc7`='Como puedes ver, solo soy un hombre con un escudero medio idiota. El poder de los enanos Hierro Negro y las bestias en manos de Ragnaros seguramente me aplastarían si me encontrasen solo, pero confío plenamente en que un aventurero tan valiente y ambicioso como tú no tendría ningún problema para enfrentarse a los moradores de la caldera. En el caso de que decidieras ayudarme, te recompensaré con las riquezas que jamás hayas podido imaginar.' WHERE `ID`=4433;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동료와 상의해 보겠습니다.', `MaleText_loc4`='让我跟同伴交换一下意见。', `MaleText_loc5`='讓我跟同伴交換一下意見。', `MaleText_loc7`='Déjame consultar con mis colegas.', `FemaleText_loc1`='동료와 상의해 보겠습니다.', `FemaleText_loc4`='让我跟同伴交换一下意见。', `FemaleText_loc5`='讓我跟同伴交換一下意見。', `FemaleText_loc7`='Déjame consultar con mis colegas.' WHERE `ID`=4434;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언젠가는 저 가시멧돼지 놈들을 굴복시키리라!', `MaleText_loc4`='我们要奴役野猪人！', `MaleText_loc5`='我們要奴役野豬人!', `MaleText_loc7`='¡Esclavizaremos a los jabaespines!' WHERE `ID`=4435;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 이 황량한 땅을 지배하리라!', `MaleText_loc4`='我们要统治这片贫瘠之地！', `MaleText_loc5`='我們將統治整個貧瘠之地!', `MaleText_loc7`='¡Nos extenderemos por esta tierra yerma!' WHERE `ID`=4436;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스컬지가 이 세계를 정복할 것이다!', `MaleText_loc4`='亡灵天灾很快就将统治世界！', `MaleText_loc5`='很快，天譴軍團就會統治整個世界!', `MaleText_loc7`='¡Pronto, la Plaga dominará el mundo!' WHERE `ID`=4437;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 눈! 불에 타는구나... 불에 타는구나...', `MaleText_loc4`='我的眼睛！它在燃烧……它在燃烧……', `MaleText_loc5`='我的眼睛!它在燃燒...它在燃燒...', `MaleText_loc7`='¡Mis ojos! Arden... arden...' WHERE `ID`=4438;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 이상 고통스럽게 하지 마라! 나를 해방시켜 다오! 슬픔의 늪... 제발...', `MaleText_loc4`='不要再烦我了！放了我吧，凡人！悲伤沼泽……凡人……求你了……', `MaleText_loc5`='不要再折磨我了!放了我吧，凡人!悲傷沼澤...凡人...求你了...', `MaleText_loc7`='¡No más torturas! ¡Suéltame, mortal! El Pantano de las Penas... mortal... por favor...' WHERE `ID`=4439;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바보 같으니! 내가 풀려나면 네 영혼을 갈기갈기 찢어놓겠다!', `MaleText_loc4`='愚蠢的凡人，只要我被释放出来，我就要撕碎你的灵魂！', `MaleText_loc5`='愚蠢的凡人，只要我被釋放出來，我就要撕碎你的靈魂!', `MaleText_loc7`='¡Iluso mortal, partiré tu alma en dos en cuanto me libere!' WHERE `ID`=4440;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들의 사악한 신을 섬기는군. 어리석은 것. 널 없애버리고 말겠다!', `MaleText_loc4`='你是邪恶之神的奴仆，愚蠢的家伙。我要见证你的毁灭！', `MaleText_loc5`='你是邪惡之神的奴僕，愚蠢的傢伙。我要見證你的毀滅!', `MaleText_loc7`='No eres $gun:una; representante de su malvado dios, idiota. ¡Contemplaré tu destrucción!' WHERE `ID`=4441;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나의 영혼은 장신구가 아니다! 이 구속에서 날 풀어다오!', `MaleText_loc4`='我的灵魂不是用来当装饰品的！凡人，你必须将我从枷锁中释放出来！', `MaleText_loc5`='我的靈魂至關重要!你必須將我從枷鎖中釋放出來!', `MaleText_loc7`='¡Mi alma no es ninguna baratija! Mortal, ¡tienes que liberarme de estas cadenas!' WHERE `ID`=4442;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 고통스럽구나... 이타리우스, 내 오랜 벗이여... 날 도와주게...', `MaleText_loc4`='这对我的伤害太深了……伊萨里奥斯，我的老朋友……请帮帮我……', `MaleText_loc5`='這對我的傷害太深了...伊薩里奧斯，我的老朋友...請幫幫我...', `MaleText_loc7`='Duele tanto... Itharius, viejo amigo... por favor, ayúdame...' WHERE `ID`=4443;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악몽은 끝나지 않을 것인가?! 깨어날 수가 없구나!', `MaleText_loc4`='什么时候噩梦才能结束？！我不能强迫自己醒过来！', `MaleText_loc5`='什麼時候夢魘才能結束?!我不能強迫自己醒過來!', `MaleText_loc7`='¡¿Acaso esta pesadilla tendrá fin en algún momento?! ¡No puedo obligarme a estar despierto!' WHERE `ID`=4444;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신전을 지키는 임무에는 실패하고... 내 타락한 영혼은 편히 쉴 수가 없구나...', `MaleText_loc4`='我没能守护好神殿……我堕落的灵魂将永远无法平静……', `MaleText_loc5`='我沒能守護好神殿...我墮落的靈魂將永遠無法平靜...', `MaleText_loc7`='No he cumplido mi cometido de proteger el templo... mi corrupta alma no tiene paz...' WHERE `ID`=4445;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋았어요! 당신의 도움으로 우리 종족이 아끼는 도시를 다시 되찾을 수 있을 것 같아요. 너무 감사드려요!', `FemaleText_loc4`='太棒了！在你的帮助下，我们又有机会夺回我们挚爱的城市了。让我们为你大声为你喝彩吧！', `FemaleText_loc5`='太棒了!在你的幫助下，我們又有機會奪回我們摯愛的城市了。讓我們為你大聲為你喝彩吧!', `FemaleText_loc7`='¡Excelente! Gracias a tu ayuda, mi gente tiene una oportunidad de recuperar su amada ciudad. ¡Tres hurras para ti!' WHERE `ID`=4446;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 알 수 없는 언어를 읊조립니다.', `MaleText_loc4`='%s开始用一种你无法理解的语言吟唱。', `MaleText_loc5`='%s開始用一種你無法理解的語言吟唱。', `MaleText_loc7`='%s entona un cántico en una lengua desconocida.' WHERE `ID`=4447;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='참고 기다리시오, $n. 횃불이 거의 완성됐소.', `MaleText_loc4`='耐心一点，$n。火炬就要完成了。', `MaleText_loc5`='耐心一點，$n。火炬就要完成了。', `MaleText_loc7`='Ten paciencia, $n. La antorcha está casi terminada.' WHERE `ID`=4448;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 한쪽 무릎을 꿇습니다. 지친 듯 보입니다.', `MaleText_loc4`='%s跪倒在地。他看上去已经精疲力尽了。', `MaleText_loc5`='%s跪了下來，看起來已經精疲力盡了。', `MaleText_loc7`='%s hinca una rodilla. Parece exhausto.' WHERE `ID`=4449;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='휴, 다 됐소.', `MaleText_loc4`='完成了……', `MaleText_loc5`='完成了...', `MaleText_loc7`='Ya está hecho...' WHERE `ID`=4450;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 잠깐만 기다리시오, $n. 한 가지 빠뜨린 게 있소! 돌아오시오!', `MaleText_loc4`='哦，$n，等一下！还有一件事！快回来！', `MaleText_loc5`='哦，$n，等一下!還有一件事!快回來!', `MaleText_loc7`='¡Oh, $n, espera un minuto! ¡Hay algo más! ¡Vuelve!' WHERE `ID`=4451;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='응보의 횃불을 완성하십시오, 칼라란.', `MaleText_loc4`='制作惩戒火炬吧，卡拉然。', `MaleText_loc5`='製作懲戒火炬吧，卡拉然。', `MaleText_loc7`='Invoca la antorcha de reprensión, Kalaran.', `FemaleText_loc1`='응보의 횃불을 완성하십시오, 칼라란.', `FemaleText_loc4`='制作惩戒火炬吧，卡拉然。', `FemaleText_loc5`='製作懲戒火炬吧，卡拉然。', `FemaleText_loc7`='Invoca la antorcha de reprensión, Kalaran.' WHERE `ID`=4452;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 마법에서 풀려나 이제 $n, 당신에게 결속되었습니다!', `MaleText_loc4`='%s被释放了，现在它与你是一体的，$n。', `MaleText_loc5`='%s被釋放了，現在它與你是一體的，$n。', `MaleText_loc7`='%s ha sido liberado y ahora se dirige a ti, $n.' WHERE `ID`=4453;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 감시탑에 불을 지릅니다. 탑이 불길에 휩싸입니다.', `MaleText_loc4`='%s吞噬了整个哨岗。哨岗着火了！', `MaleText_loc5`='%s席捲了崗哨。崗哨著火了!', `MaleText_loc7`='%s devora la torre del centinela. ¡La torre arde en llamas!' WHERE `ID`=4454;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$r|1이여;여;, 진심으로 환영합니다. 동굴에 숨어 사는 저 같은 이와 대화하려고 잘 알지도 못하는 길을 찾아서 왔군요. 갑작스럽긴 하지만 예측하지 못한 방문은 아닙니다. 분명 그럴만한 이유가 있을 테지요. 안 그렇습니까?', `MaleText_loc4`='我热烈欢迎你的到来，$c。你远道而来仅仅是为了找一个住在洞里的家伙，我相信你的这次旅程一定是有重要的事情，对吗？', `MaleText_loc5`='我熱烈歡迎你的到來，$r。你遠道而來僅僅是為了找一個住在洞裡的傢伙，我相信你的這次旅程一定是有重要的事情，對嗎?', `MaleText_loc7`='Te hago partícipe de mi cordial bienvenida, $r. Te has alejado mucho del camino solo para hablar con alguien que mora en una cueva. Confío en que habrá una razón para tu extraña, aunque no imprevista, visita. ¿Es así?' WHERE `ID`=4455;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말로 대단하군, 몰트레이크. 내 계획이 완벽하게 진행된 것 같아. 안 그런가, 나약한 $R|1이여;여;?', `MaleText_loc4`='确实很不错，玛特拉克。看起来我的计划运行良好。你说是吗，$c？', `MaleText_loc5`='確實很不錯，瑪特拉克。看起來我的計畫運行良好。你說是嗎，$c?', `MaleText_loc7`='Ciertamente es fabuloso, Maltrake. Al parecer, mi plan ha funcionado perfectamente. ¿Estás de acuerdo conmigo, mortal?' WHERE `ID`=4456;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 단순히 지원을 해달라고 요청했다면 자네는 아마 검은바위 부족을 도우려고 하지 않았겠지?', `MaleText_loc4`='如果黑石军团要求你帮忙的话，你是不会帮助他们的，对吗？', `MaleText_loc5`='如果黑石軍團要求你幫忙的話，你是不會幫助他們的，對嗎?', `MaleText_loc7`='Nos habrías ayudado a la legión de los Roca Negra en caso de haberte pedido ayuda, ¿no es así?' WHERE `ID`=4457;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 파충류와 비슷한 소리를 냅니다... 웃음소리인 것 같습니다.', `MaleText_loc4`='%s露出卑鄙的笑容……至少你认为他在发笑。', `MaleText_loc5`='%s讓我們偷笑一下吧...如果你認為這可以稱作「笑」的話。', `MaleText_loc7`='%s suelta una carcajada de reptil... al menos parece una carcajada.' WHERE `ID`=4458;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 처리할까요, 주인님? 이제 이용할 가치가 없는 것 같습니다.', `MaleText_loc4`='我们该怎么处置他们？他们现在对我们没有什么用了。', `MaleText_loc5`='我們該怎麼處置他們?他們現在對我們沒有什麼用了。', `MaleText_loc7`='¿Qué harás con ellos, maestro? Ya no nos sirven para nada.' WHERE `ID`=4459;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조용해, 멍청한 것!', `MaleText_loc4`='闭嘴，笨蛋！', `MaleText_loc5`='閉嘴，笨蛋!', `MaleText_loc7`='¡SILENCIO, LOCO!' WHERE `ID`=4460;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자신이 노력한 결실은 볼 수 있도록 살려둬야지. 검은바위 부족이 이 협곡을 침략하면서 일어날 파괴와 혼돈을 똑똑히 보도록 말이야.', `MaleText_loc4`='让他们活着，这样他们就可以看到他们都做了些什么——在黑石军团入侵灼热峡谷之后，毁灭和混乱将接踵而至。', `MaleText_loc5`='讓他們活著，這樣他們就可以看到他們都做了些什麼─在黑石軍團入侵灼熱峽谷之後，毀滅和混亂將接踵而至。', `MaleText_loc7`='Vivirán, aun cuando solo sea para ver el fruto de su trabajo: la destrucción y el caos que con toda seguridad reinarán en cuanto la legión de los Roca Negra invada la garganta.' WHERE `ID`=4461;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 나는 가겠다, 나약한 $r|1이여;여;. 목숨만은 살려주지. 몰트레이크! 만물 상자를 주도록 하여라!', `MaleText_loc4`='我饶了你们的性命，你得活着，拿好这些饰品！玛特拉克，把饰品交给他们！', `MaleText_loc5`='我饒了你們的性命，你得活著，拿好這些飾品!瑪特拉克，把飾品交給他們!', `MaleText_loc7`='Ahora os dejo, mortales. Vivos y con estas baratijas. ¡Maltrake! ¡Muéstrales las baratijas!' WHERE `ID`=4462;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 그 허물은 잃어버리지 마라. 불타는 평원에는 검은용군단의 허물로 강력한 물건을 만드는 종족이 있다고 하니까.', `MaleText_loc4`='哦，当然，龙皮——可别弄丢了。我们家族的一些成员所制造的东西必须用黑龙皮来强化。', `MaleText_loc5`='哦，當然，龍皮─可別弄丟了。我們家族的一些成員所製造的東西必須用黑龍軍團之皮來強化。', `MaleText_loc7`='Ah, sí, la piel - no la pierdas. Tengo parientes en las Estepas Ardientes que confeccionan objetos que solo la piel del Vuelo Negro podría fortalecer.' WHERE `ID`=4463;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 날개를 점점 더 빨리 퍼덕이기 시작하며 날아갈 준비를 합니다.', `MaleText_loc4`='%s开始扇动他巨大的翅膀，速度越来越快。他准备起飞了。', `MaleText_loc5`='%s開始搧動他巨大的翅膀，速度越來越快。他已經準備起飛了。', `MaleText_loc7`='%s comienza a agitar sus enormes alas cada vez con mayor rapidez. Se prepara para volar.' WHERE `ID`=4464;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드워프들이여! 검은바위 부족의 군대가 온다. 우리는 대지와 하늘을 불태울 것이다. 아무도 살아남지 못하리라.', `MaleText_loc4`='黑石军团就要来了！我们要夷平这片土地，让熊熊大火直冲云霄。没有人可以活下来……', `MaleText_loc5`='黑石軍團就要來了!我們要夷平這片土地，讓熊熊大火直沖雲霄。沒有人可以活下來...', `MaleText_loc7`='¡Ya viene la legión de los Roca Negra, enanitos! Chamuscaremos la tierra y los cielos arderán en llamas. Nadie sobrevivirá...' WHERE `ID`=4465;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 방 안의 모든 석상을 원위치로 되돌려 놓습니다.', `MaleText_loc4`='将这间房间里的雕像全部重置。', `MaleText_loc5`='將這間房間裡的雕像全部重置。', `MaleText_loc7`='Vuelve a poner aquí todas las estatuas.', `FemaleText_loc1`='이 방 안의 모든 석상을 원위치로 되돌려 놓습니다.', `FemaleText_loc4`='将这间房间里的雕像全部重置。', `FemaleText_loc5`='將這間房間裡的雕像全部重置。', `FemaleText_loc7`='Vuelve a poner aquí todas las estatuas.' WHERE `ID`=4466;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='석상들이 모두 원위치로 되돌아갑니다.$B$B처음부터 다시 순서대로 시작해야 합니다.', `MaleText_loc4`='所有的雕像都已经回归了原来的位置。$B$B你必须重新对它们进行排列。', `MaleText_loc5`='所有的雕像都已經回歸了原來的位置。$B$B你必須重新對它們進行排列。', `MaleText_loc7`='Todas las estatuas regresan a sus puestos originales.$B$BHay que repetir la frase nuevamente, desde el comienzo.', `FemaleText_loc1`='석상들이 모두 원위치로 되돌아갑니다.$B$B처음부터 다시 순서대로 시작해야 합니다.', `FemaleText_loc4`='所有的雕像都已经回归了原来的位置。$B$B你必须重新对它们进行排列。', `FemaleText_loc5`='所有的雕像都已經回歸了原來的位置。$B$B你必須重新對它們進行排列。', `FemaleText_loc7`='Todas las estatuas regresan a sus puestos originales.$B$BHay que repetir la frase nuevamente, desde el comienzo.' WHERE `ID`=4467;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠습니다, 주인님!', `MaleText_loc4`='马上，主人！', `MaleText_loc5`='馬上，主人!', `MaleText_loc7`='¡Ahora mismo, maestro!' WHERE `ID`=4468;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까. 저는 대마법사 실렘님의 수습마법사인 니릴이라고 합니다. 문제가 있으면 주저하지 말고 저희 주인님께 말씀 드리도록 하시기 바랍니다.$B$B저는 여기 있다가 당신이 산 밑으로 내려갈 준비가 되면 보내드리도록 하겠습니다.', `MaleText_loc4`='你好，$G先生:小姐;。我是克希雷姆大人的学徒尼瑞尔。如果你们有任何问题，请随意向主人询问。$B$B当你准备下山的时候，就过来找我吧。', `MaleText_loc5`='你好，$G先生:小姐;。我是克希雷姆大人的學徒尼瑞爾。如果你們有任何問題，請隨意向主人詢問。$B$B當你準備下山的時候，就過來找我吧。', `MaleText_loc7`='Saludos, $Gseñor:señorita;. Soy el aprendiz Nyrill del maestro Xylem. Si tienes algún problema, no dudes en consultar con el maestro.$B$BÉl sin duda vendrá a ayudarte cuando se disponga a regresar a la base en la montaña.' WHERE `ID`=4469;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 누군지 압니다, $n 님. 운명과 그 너머의 힘이 어떤 이유 때문에 당신을 저에게 인도한 것이지요. 그 목적에 제가 연관되어 있다는 것이 그다지 기쁘지는 않습니다. 당신은 앞으로 많은 결정을 하게 될 것입니다. 당신이 옳은 결정을 내릴 만큼 현명하다면 좋겠군요.$B$B제 말을 믿으십시오, $R|1이여;여;. 진정 옳은 결정이란 존재하는 법입니다.', `MaleText_loc4`='我知道你是谁，$n。由于某种原因，命运将你带到我面前，而且我对此并不感到高兴。在未来的日子里，你将做出很多抉择，我希望你拥有足够的智慧来做出正确的抉择。$B$B相信我吧，$c——总有正确的抉择。', `MaleText_loc5`='我知道你是誰，$n。由於某種原因，命運將你帶到我面前，而且我對此並不感到高興。在未來的日子裡，你將做出很多抉擇，我希望你擁有足夠的智慧來做出正確的抉擇。$B$B相信我吧，$r，─總有正確的抉擇。', `MaleText_loc7`='Sé quién eres, $n. El destino y otras fuerzas te han traído hasta me por un motivo del cual no me complace formar parte. Tendrás que tomar muchas decisiones a partir de ahora y espero que seas lo suficientemente inteligente para hacerlo con acierto.$B$B$R, créeme cuando te digo que es posible.' WHERE `ID`=4470;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 같은 엘프가 이런 외딴 동굴에서 무얼 하고 계십니까?', `MaleText_loc4`='像你这样的精灵待在这种洞穴里干什么？', `MaleText_loc5`='像你這樣的精靈待在這種洞穴裡幹什麼?', `MaleText_loc7`='¿Qué hace un elfo como tú en una cueva como esta?', `FemaleText_loc1`='당신 같은 엘프가 이런 외딴 동굴에서 무얼 하고 계십니까?', `FemaleText_loc4`='像你这样的精灵待在这种洞穴里干什么？', `FemaleText_loc5`='像你這樣的精靈待在這種洞穴裡幹什麼?', `FemaleText_loc7`='¿Qué hace un elfo como tú en una cueva como esta?' WHERE `ID`=4471;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 호기심이 아주 강하군요. 보통 그런 호기심은 이해력의 부족에서 오는 것이긴 하지만 말입니다. 이곳에 오는 데 뚜렷한 목적이 있었다면 그런 질문은 애당초 하지 않았을 테지요.$B$B당신의 갈 길이나 가보도록 하십시오.', `MaleText_loc4`='你很好奇，这种好奇掩饰了你在理解能力上的缺乏。我说这些是因为，如果你来此有一个确定的目的，你要提的问题就会显得毫无意义。$B$B因为这个原因，我只好对你说再见。', `MaleText_loc5`='你很好奇，這種好奇掩飾了你在理解能力上的缺乏。我說這些是因為，如果你來此有一個確定的目的，你要提的問題就會顯得毫無意義。$B$B因為這個原因，我只好對你說再見。', `MaleText_loc7`='Te gusta saber y, esa curiosidad, deja traslucir una carencia general de conocimiento. Te lo digo porque si tu presencia aquí tuviera un propósito definido, tu pregunta carecería de sentido. $B$BCon eso, te deseo un buen día.' WHERE `ID`=4472;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='', `MaleText_loc4`='', `MaleText_loc5`='', `MaleText_loc7`='' WHERE `ID`=4473;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혹시 에라니쿠스라는 이름을 가진 존재... 를 아십니까?', `MaleText_loc4`='你知道有关伊兰尼库斯的事吗？', `MaleText_loc5`='你知道有關伊蘭尼庫斯的事嗎?', `MaleText_loc7`='¿Conoces a alguien... o algo, quizás, llamado Eranikus?', `FemaleText_loc1`='혹시 에라니쿠스라는 이름을 가진 존재... 를 아십니까?', `FemaleText_loc4`='你知道有关伊兰尼库斯的事吗？', `FemaleText_loc5`='你知道有關伊蘭尼庫斯的事嗎?', `FemaleText_loc7`='¿Conoces a alguien... o algo, quizás, llamado Eranikus?' WHERE `ID`=4474;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신도 알고 있지 않습니까. 제가 알고 있다는 걸... 지금 저는 쓸데없는 말을 하고 싶지 않으니 당신도 그렇게 하는 게 좋을 것입니다.$B$B당신이 여기 온 이유는 분명 아탈라이의 가라앉은 사원에서 얻은 그 물건이겠지요. 그게 어떤 이유로 당신을 여기로 이끌었는지 궁금하겠지요. 그건 바로 저의 동지이자... 형제에게 안식을 주기 위해서입니다. 그는 에메랄드의 꿈속에서... 악몽에... 갇혀 혼자서는 빠져나올 수 없으니 말이지요.', `MaleText_loc4`='你很清楚我知道这些，$r。我们坦率地说吧。$B$B很明显你来这里是因为你知道自己拿着什么样的东西，你在哈卡的神庙中得到的这件东西使你身负着一件使命来到我面前。这个使命就是让我的伙伴……我的兄弟，得到安息。他被困在翡翠梦境的噩梦中，他自己无法解脱出来。', `MaleText_loc5`='你很清楚我知道這些，$r。我們坦率地說吧。$B$B很明顯你來這裡是因為你知道自己拿著什麼樣的東西，你在哈卡的神廟中得到的這件東西使你身負著一件使命來到我面前。這個使命就是讓我的夥伴...我的兄弟，得到安息。他被困在翡翠夢境的夢魘中，他自己無法解脫出來。', `MaleText_loc7`='Sabes que sí, mortal. Dejaré de mentir y te recomiendo que hagas lo mismo.$B$BHas venido aquí claramente porque sabes que lo que posees, fruto de tus obras en el Templo Sumergido de los Atal''ai, te ha traído hasta mí por alguna razón. Esta razón es lograr que mi socio... mi hermano, logre descansar. Está atrapado en una pesadilla dentro del propio Sueño. No puede escapar solo.' WHERE `ID`=4475;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='애초에 무슨 일이 있었던 겁니까? 처음... 만났을 때 그는 참 포악했습니다.', `MaleText_loc4`='他究竟怎么了？当我……当我遇到他的时候，他显得非常邪恶。', `MaleText_loc5`='他究竟怎麼了?當我...當我遇到他的時候，他顯得非常邪惡。', `MaleText_loc7`='¿Qué le pasó en primer lugar? Cuando... lo encontré, era más bien malicioso.', `FemaleText_loc1`='애초에 무슨 일이 있었던 겁니까? 처음... 만났을 때 그는 참 포악했습니다.', `FemaleText_loc4`='他究竟怎么了？当我……当我遇到他的时候，他显得非常邪恶。', `FemaleText_loc5`='他究竟怎麼了?當我...當我遇到他的時候，他顯得非常邪惡。', `FemaleText_loc7`='¿Qué le pasó en primer lugar? Cuando... lo encontré, era más bien malicioso.' WHERE `ID`=4476;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아탈라이 트롤들이 불러낸 신 때문입니다. 저희는 그 신의 육체를 파괴하고 신전을 가라앉혔지만, 그는 예상보다 훨씬 강했지요. 타락의 씨앗이 깊이 파고들어 그곳을 지나가는 모든 것을 뒤틀리게 했으니까요.$B$B에라니쿠스는 그 가라앉은 신전을 감시하며 아탈라이 부족과 그들의 신이 다시 일어나지 못하게 하는 임무를 맡았습니다. 그런데 자신도 모르는 사이 타락의 피해자가 된 것이지요. 그리고 저희도 마찬가지로, 피해를 입게 되었습니다. 타락의 힘을 과소평가한 대가이지요.', `MaleText_loc4`='阿塔莱巨魔所崇拜的神灵曾经受到惩罚。我们毁掉了他的肉身并把神庙沉入水中，但是他比我们预料中的要强大得多。堕落的种子散播开来，腐化了它所接触的一切。$B$B伊兰尼库斯负责看守沉没的神庙，以确保阿塔莱巨魔或是阿塔莱神灵都不会再死灰复燃。他是个无辜的受害者，我们低估了堕落的力量。', `MaleText_loc5`='阿塔萊食人妖所崇拜的神靈曾經受到懲罰。我們毀掉了他的肉身並把神廟沉入水中，但是他比我們預料中的要強大得多。墮落的種子散播開來，腐化了它所接觸的一切。$B$B伊蘭尼庫斯負責看守沉沒的神廟，以確保阿塔萊食人妖或是阿塔萊神靈都不會再死灰復燃。他是個無辜的受害者，我們低估了墮落的力量。', `MaleText_loc7`='El dios que trajeron los trols Atal''ai tiene la culpa de esto. Destruimos la manifestación física del dios y sumergimos el templo, pero el dios era mucho más fuerte de lo que creíamos. Su semilla de corrupción prendió con fuerza, torciendo todo lo que encontraba a su paso.$B$BEranikus tenía encomendada la tarea de vigilar el templo sumergido para garantizar que ni los simples Atal’ai ni el dios volvieran a alzarse. Él fue una víctima involuntaria de esta descomposición y nosotros fuimos ilusos al subestimar su potencia.' WHERE `ID`=4477;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제게 에라니쿠스의 정수가 있는데 어떻게 해야 합니까?', `MaleText_loc4`='我拥有一部分伊兰尼库斯的精华。你想用它来做什么……或者要我做什么？', `MaleText_loc5`='我擁有一部分伊蘭尼庫斯的精華。你想用它來做什麼...或者要我做什麼?', `MaleText_loc7`='Poseo parte de la esencia de Eranikus. ¿Qué pretendes hacer con ella... o conmigo?', `FemaleText_loc1`='제게 에라니쿠스의 정수가 있는데 어떻게 해야 합니까?', `FemaleText_loc4`='我拥有一部分伊兰尼库斯的精华。你想用它来做什么……或者要我做什么？', `FemaleText_loc5`='我擁有一部分伊蘭尼庫斯的精華。你想用它來做什麼...或者要我做什麼?', `FemaleText_loc7`='Poseo parte de la esencia de Eranikus. ¿Qué pretendes hacer con ella... o conmigo?' WHERE `ID`=4478;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 여기 왔다는 것이 첫 번째 발을 내디딘 것입니다... 말하자면, 이세라용군단을 돕는다는 것은 옳은 결정이라는 뜻이지요.$B$B당신은 순전히 개인적인 욕심 때문에 이곳에 왔을 수도 있고, 도덕적 의무감에서 온 것일 수도 있습니다. 이유 자체는 중요하지 않습니다. 지금의 결과를 낳았다는 것이 중요하지요. 에라니쿠스가 받는 고통 때문에 나도 에메랄드의 꿈에서 깨어나게 되었습니다. 이제 그의 고통을 끝내는 것이 제 임무입니다. 그리고 이것을 당신이 도와줘야 하는 것이지요.', `MaleText_loc4`='你来到此地仅仅是第一步……如果你想帮助伊瑟拉的绿龙军团，这是个正确的选择。$B$B你到这儿来也许只是受到个人利益的驱使，也许是受到良心的谴责。什么缘由并不重要，重要的是结果：伊兰尼库斯所经受的痛苦令我从梦中惊醒，现在我要终止他的痛苦。我想请你帮助我完成这项任务。', `MaleText_loc5`='你來到此地僅僅是第一步...如果你想幫助伊瑟拉的綠龍軍團，這是個正確的選擇。$B$B你到這兒來也許只是受到個人利益的驅使，也許是受到良心的譴責。什麼緣由並不重要，重要的是結果:伊蘭尼庫斯所經受的痛苦令我從夢中驚醒，現在我要終止他的痛苦。我想請你幫助我完成這項任務。', `MaleText_loc7`='El hecho de que estés aquí es el primer paso... se trata de una elección acertada, si quieres, si se trata de ayudar al Vuelo de Ysera.$B$BTal vez estés aquí atraído por el mérito personal, o bien porque te sientes moralmente obligado. Ninguna de estas razones es importante por sí misma, pero ambas son ciertamente primordiales para lo que nos ocupa: La agonía que padece Eranikus es lo que me despertó de mi Sueño, y ahora tengo que encargarme de poner fin a su tormento. Ahora te pido que me ayudes en mi misión.' WHERE `ID`=4479;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 생각해보겠습니다.', `MaleText_loc4`='我会认真考虑你所告诉我的事情。', `MaleText_loc5`='我會認真考慮你所告訴我的事情。', `MaleText_loc7`='Tendré en cuenta lo que me has dicho.', `FemaleText_loc1`='잘 생각해보겠습니다.', `FemaleText_loc4`='我会认真考虑你所告诉我的事情。', `FemaleText_loc5`='我會認真考慮你所告訴我的事情。', `FemaleText_loc7`='Tendré en cuenta lo que me has dicho.' WHERE `ID`=4480;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신에게 이세라용군단의 서약의 돌을 주었습니다. 저희를 도울 준비가 되거든 서약의 돌을 사용하십시오.', `MaleText_loc4`='我已经把一块伊瑟拉巨龙军团的誓言石交给你了，$n。如果你决定帮助我们，就使用它，然后我们就可以开始了。', `MaleText_loc5`='我已經把一塊伊瑟拉巨龍軍團的誓言石交給你了，$n。如果你決定幫助我們，就使用它，然後我們就可以開始了。', `MaleText_loc7`='Te he dado una piedra de juramento del Vuelo de Ysera, $n. Cuando creas que estás $gpreparado:preparada; para ayudarnos, úsala y podremos empezar.' WHERE `ID`=4481;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='행운을 빌겠소. 같이 데리고 가지 못해서 미안하오!', `MaleText_loc4`='祝你好运。很抱歉我不能和你一起去！', `MaleText_loc5`='祝你好運。很抱歉我不能和你一起去!', `MaleText_loc7`='Buena suerte. ¡Siento no poder llevarte conmigo!' WHERE `ID`=4482;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 얼어붙을 정도로 차가운 숨결을 내뿜으며 망령을 소환하기 시작합니다!', `MaleText_loc4`='%s开始从冰冷的空气中召唤鬼魂！', `MaleText_loc5`='%s開始從冰冷的空氣中召喚怨靈!', `MaleText_loc7`='¡%s comienza a invocar ánimas del aire gélido!' WHERE `ID`=4483;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자다! 공격하라!', `MaleText_loc4`='入侵者！攻击入侵者！', `MaleText_loc5`='入侵者!攻擊入侵者!', `MaleText_loc7`='¡Intrusos! ¡Atacad a los intrusos!', `FemaleText_loc1`='침입자다! 공격하라!', `FemaleText_loc4`='入侵者！攻击入侵者！', `FemaleText_loc5`='入侵者!攻擊入侵者!', `FemaleText_loc7`='¡Intrusos! ¡Atacad a los intrusos!' WHERE `ID`=4484;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 자유다! 피의 복수를 해 주겠다!', `MaleText_loc4`='我的流放生涯结束了！让鲜血尽情流淌吧！', `MaleText_loc5`='我所遭受的懲罰終於結束了!讓鮮血在大地上流淌吧!', `MaleText_loc7`='¡Mi destierro ha terminado! ¡Que corra la sangre!' WHERE `ID`=4485;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='재밌군, 아주 재미있어... 내가 통곡의 동굴 위 언덕 꼭대기에 사는 드루이드를 하나 알고 있네. 그녀라면 자네가 찾은 이 조각에 대해 더 자세히 말해줄 수 있을 거야.$B$B자, 그럼 난 계속 일이나 해야겠어!', `MaleText_loc4`='有趣，真有趣……我知道有个德鲁伊居住在哀嚎洞穴上方的山顶，$n。她也许能告诉你有关这块碎片的更多信息。$B$B现在，我必须工作了！', `MaleText_loc5`='有趣，真有趣...我知道有個德魯伊居住在哀嚎洞穴上方的山頂，$n。她也許能告訴你有關這塊裂片的更多資訊。$B$B現在，我必須工作了!', `MaleText_loc7`='Interesante, muy interesante... Conozco a una druida que vive en la cumbre de la colina que está encima de las Cuevas de los Lamentos, $n. Quizás pueda decirte algo más sobre este fragmento que has encontrado.$B$B¡Y ahora, he de volver al trabajo!' WHERE `ID`=4486;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 비틀거립니다.', `MaleText_loc4`='%s步履蹒跚。', `MaleText_loc5`='%s蹣跚著。', `MaleText_loc7`='%s se tambalea.' WHERE `ID`=4489;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보호막이 무너졌다. 일어나라, 아탈라이여! 일어나라!', `MaleText_loc4`='防御结界被摧毁了！醒来吧，阿塔莱！醒来吧！', `MaleText_loc5`='防護盾消失了!起來吧，阿塔萊!起來吧!', `MaleText_loc7`='¡El escudo está bajo! ¡Levántense Atal''ai! ¡Levántense!' WHERE `ID`=4490;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님!! 녀석들이 주인님의 업적을 파괴하려고 합니다!!', `MaleText_loc4`='夫人！他们正在毁掉你的心血！', `MaleText_loc5`='夫人!!他們想要毀掉你的工作!!', `MaleText_loc7`='¡Maestra! ¡Intentan destruir tu trabajo!', `FemaleText_loc1`='주인님!! 녀석들이 주인님의 업적을 파괴하려고 합니다!!', `FemaleText_loc4`='夫人！他们正在毁掉你的心血！', `FemaleText_loc5`='夫人!!他們想要毀掉你的工作!!', `FemaleText_loc7`='¡Maestra! ¡Intentan destruir tu trabajo!' WHERE `ID`=4491;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 넌 이제 꼼짝없이 죽게 되었구나!', `MaleText_loc4`='哈！现在你死定了！', `MaleText_loc5`='哈!現在你死定了!', `MaleText_loc7`='¡Ja! ¡Tu muerte ya es segura!', `FemaleText_loc1`='하! 넌 이제 꼼짝없이 죽게 되었구나!', `FemaleText_loc4`='哈！现在你死定了！', `FemaleText_loc5`='哈!現在你死定了!', `FemaleText_loc7`='¡Ja! ¡Tu muerte ya es segura!' WHERE `ID`=4492;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 방심하지 마시고 가까이 붙어 있으세요. 당장에라도 어둠 속에서 가시멧돼지들이 튀어나올지 모릅니다.', `MaleText_loc4`='准备好，靠近点。要是你放松戒备的话，那些恶魔会从暗处跳出来偷袭你的。', `MaleText_loc5`='好吧，靠近點。要是你放鬆戒備的話，那些惡魔會從暗處跳出來偷襲你的。', `MaleText_loc7`='De acuerdo, quédate por aquí. Estos demonios te asaltarán desde las tinieblas si bajas la guardia.' WHERE `ID`=4493;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네가 감히! 내 분노를 느껴보아라!', `FemaleText_loc4`='大胆！让我的愤怒将你淹没吧！', `FemaleText_loc5`='大膽!讓我的憤怒將你淹沒吧!', `FemaleText_loc7`='¡Cómo te atreves! ¡Ahora enfréntate a mi ira!' WHERE `ID`=4495;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳 아즈샤라에서 보낸 날들이 그렇게 영광스럽고 좋았던 것만은 아니지만, 우린 아직 젊고 몸속에는 아직도 뜨거운 피가 흐르고 있소. 그러니 우리는 꼭 승리할 수 있을 거요. 승리는 시간문제일 뿐이오.', `MaleText_loc4`='我们在艾萨拉度过的这段日子并不是辉煌而又灿烂的，但是我们仍然年轻而且热血沸腾——我们最终会获得胜利，这只是一个时间问题。', `MaleText_loc5`='我們在艾薩拉度過的這段日子並不是輝煌而又燦爛的，但是我們仍然年輕而且熱血沸騰─我們最終會獲得勝利，這只是一個時間問題。', `MaleText_loc7`='Los días que hemos pasado aquí en Azshara no son nuestros mejores días ni los más gloriosos, pero aún somos jóvenes y la sangre aún corre por nuestras venas, aquí alcanzaremos la victoria. Solo es cuestión de tiempo.' WHERE `ID`=4496;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벨그롬이 이 어리석은 동맹을 유지할 수 있도록 도와달라며 오그리마에 있는 우리를 이곳으로 보냈소. 하지만 그의 도박이 성공한다면 모든 호드에게 득이 될 거요.$B$B여자들을 즐겁게 해주려는 그의 욕심 때문에 이미 많은 오크들이 죽었지만, 그는 여전히 우리의 지휘관이고, 우린 명예 때문에 주어진 상황에서 최선을 다하는 수밖에 없는 거요.', `MaleText_loc4`='贝尔戈洛姆派我们从奥格瑞玛到这里来帮助他，不过如果他成功了，那样整个部落就有了希望。$B$B虽然由于他一直以来都喜欢取悦女人，无数的兽人已经因此而丧生，但是他仍然是我们的指挥官，为了荣耀，我们只能尽力去做好。', `MaleText_loc5`='貝爾戈洛姆派我們從奧格瑪到這裡來幫助他，不過如果他成功了，那樣整個部落就有了希望。$B$B雖然由於他一直以來都喜歡取悅女人，無數的獸人已經因此而喪生，但是他仍然是我們的指揮官，為了榮耀，我們只能盡力去做好。', `MaleText_loc7`='Belgrom nos envió hasta aquí desde Orgrimmar para ayudarle en una Alianza poco sensata, pero si nos compensa, entonces toda la Horda se verá beneficiada.$B$BDemasiados orcos han perecido por su deseo de complacer a las mujeres, pero él sigue siendo nuestro jefe, y el honor nos dice que debemos sacar partido de esta situación.' WHERE `ID`=4497;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내가 여기 있는 건 명예 때문이 아니에요. 한 오크의 자존심 때문이죠.$B$B내가 벨그롬의 제안을 거절하지 않았던들 아직도 오그리마에 남아 진짜 일을 하고 있었을 거예요.$B$B여성에 대한 벨그롬의 탐욕을 듀로타의 많은 여전사들도 모르는 게 아니지만 여전히 벨그롬의 탐욕스러운 태도는 사라지질 않고 있어요.$B$B그 녀석 내게 치근덕거리는 걸 일찌감치 그만두길 잘했죠. 안 그랬으면 손가락이 날아가는 것으로 끝나지 않았을 테니까요.', `FemaleText_loc4`='我不是为了荣耀而来这里的，$n。我来这里是为了兽人的骄傲。$B$B如果我没有拒绝贝尔戈洛姆的提议，那我肯定现在还在奥格瑞玛料理真正的生意。$B$B他对女人的渴望在杜隆塔尔的女性战士中尽人皆知，但是那仍然没有影响他成为大众情人。$B$B很幸运他并没有骚扰我太长时间——否则他会被砍成肉酱的。', `FemaleText_loc5`='我不是為了榮耀而來這裡的，$n。我來這裡是為了獸人的驕傲。$B$B如果我沒有拒絕貝爾戈洛姆的提議，那我肯定現在還在奧格瑪料理真正的生意。$B$B他對女人的渴望在杜洛塔的女性戰士中盡人皆知，但是那仍然沒有影響他成為大眾情人。$B$B很幸運他並沒有騷擾我太長時間─否則他會被砍成肉醬的。', `FemaleText_loc7`='No estoy aquí por el honor, $n. Estoy aquí por el orgullo de un orco.$B$BSi no hubiera rechazado las ofertas de Belgrom, con seguridad seguiría en Orgrimmar, ocupándome de asuntos realmente importantes.$B$BSu pasión por las mujeres no resulta desconocida entre muchas de las guerreras de Durotar, pero eso no le impide ser todo lo encantador que sabe.$B$BNo obstante, tiene suerte de no haber dado rienda suelta a sus deseos por mí, si no lo habría dejado más chato que un sello.' WHERE `ID`=4498;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요. 오그리마에서 우리를 도우러 오셨군요. 다행입니다. 아, 이 끔찍한 숲에서 빨리 벗어나고 싶어요. 하루라도 빨리 오그리마에 가서 맛 좋은 맥주나 마시면서 지내고 싶거든요.$B$B벨그롬에게 무슨 얘기를 들었기에 당신이 이곳까지 왔는지 궁금하군요.', `FemaleText_loc4`='你好，$n。你是从奥格瑞玛来帮助我们的吧？很高兴见到你。我想尽快离开这片亡灵的森林，回到奥格瑞玛去喝酒度日。$B$B不过，我很想知道贝尔戈洛姆是如何说服你来这儿的。', `FemaleText_loc5`='你好，$n。你是從奧格瑪來幫助我們的吧?很高興見到你。我想儘快離開這片亡靈的森林，回到奧格瑪去喝麥芽酒度日。$B$B不過，我很想知道貝爾戈洛姆是如何說服你來這兒的。', `FemaleText_loc7`='Saludos, $n. Veo que has venido desde Orgrimmar para ayudarnos. Me complace. Quiero salir del bosque de los Renegados tan rápido como sea posible. Preferiría pasar el tiempo en Orgrimmar con una buena cerveza en la mano.$B$BSi bien no puedo esperar a oír cómo me cuentas cómo Belgrom te convenció de que vinieras hasta aquí.' WHERE `ID`=4499;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해냈군! <이상하게 낯익은 목소리가 채집병에서 들려옵니다!> 서둘러 돌아오시오! 30분이 지나면 그 폐기물의 상태가 불안정해져 버린다오.', `MaleText_loc4`='你成功了，$n！<这奇怪而熟悉的声音似乎是从瓶子中传出来的！>快回来！辐射尘的稳定期只有三十分钟。', `MaleText_loc5`='你成功了，$n!<這奇怪而熟悉的聲音似乎是從瓶子中傳出來的!>快回來!輻射塵的穩定期只有三十分鐘。', `MaleText_loc7`='¡Lo has conseguido, $n! <Parece que la voz extrañamente familiar sale de la ampolla.> ¡Rápido, atrás! El efecto solo permanecerá estable durante treinta minutos.' WHERE `ID`=4500;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 시작하겠습니다. 진화 의식은 한 5분 정도 걸릴 겁니다. 제가 시작하면 졸개 녀석들이 접근하지 못하게 막아주십시오. 안 그러면 우리 모두 끝장입니다!', `MaleText_loc4`='嗯，我大约需要5分钟的时间来完成关闭它的仪式。在我开始之后，你一定要好好保护我，否则我们都会没命的！', `MaleText_loc5`='好吧，我大約需要5分鐘的時間來完成關閉它的儀式。在我開始之後，你一定要好好保護我，否則我們倆都會沒命的!', `MaleText_loc7`='De acuerdo, allá vamos. Vamos a tardar unos cinco minutos hasta conseguir cerrar esta cosa durante el ritual. ¡Cuando empiece, quitadme las alimañas de encima o será el fin de todos nosotros!' WHERE `ID`=4501;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 어떤 녀석이냐! 내 너를 죽여주마!', `MaleText_loc4`='谁这么大胆？！我要毁灭你！', `MaleText_loc5`='誰這麼大膽?!我要毀滅你!', `MaleText_loc7`='¡¿Quién se atreve a..?! ¡Te destruiré!', `FemaleText_loc1`='감히 어떤 녀석이냐! 내 너를 죽여주마!', `FemaleText_loc4`='谁这么大胆？！我要毁灭你！', `FemaleText_loc5`='誰這麼大膽?!我要毀滅你!', `FemaleText_loc7`='¡¿Quién se atreve a..?! ¡Te destruiré!' WHERE `ID`=4502;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시험용 메시지', `MaleText_loc4`='DUMMY SPELL TEST MESSAGE', `MaleText_loc5`='DUMMY SPELL TEST MESSAGE', `MaleText_loc7`='MENSAJE DE PRUEBA DE HECHIZO' WHERE `ID`=4503;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='3분 남았소. 마력이 차오르는 게 느껴집니다! 부디 계속해서 녀석들을 막아주십시오!', `MaleText_loc4`='还剩三分钟——我感觉到能量正在不断汇集！继续保护我！', `MaleText_loc5`='還剩三分鐘─我感覺到能量正在不斷彙集!繼續保護我!', `MaleText_loc7`='Quedan tres minutos. ¡Empiezo a sentir cómo se acumula la energía! ¡Mantened fuertes las defensas!' WHERE `ID`=4504;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='2분만 더! 절반은 해냈지만 아직 방심하면 안 되오!', `MaleText_loc4`='只有两分钟时间了！我们只完成了一半，不要放松警惕！', `MaleText_loc5`='只有兩分鐘時間了!我們只完成了一半，不要放鬆警惕!', `MaleText_loc7`='¡Faltan dos minutos para irnos! ¡Estamos a medio camino, pero no bajéis la guardia!' WHERE `ID`=4505;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='1분만 더! 이제 곧 의식이 끝날 테니 조금만 더 버텨주십시오!', `MaleText_loc4`='再坚持一分钟！坚持住，仪式就要完成了！', `MaleText_loc5`='再堅持一分鐘!堅持住，儀式就要完成了!', `MaleText_loc7`='¡Un minuto más! Aguanta un poco, ¡el ritual está cobrando fuerza!' WHERE `ID`=4506;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다 됐군요, 우리가 해냈습니다! 이 우상의 불은 이제 영원히 타오르지 못할 것입니다! 역시 당신은 내가 기대했던 영웅이시로군요!', `MaleText_loc4`='很好——我们成功了！雕像中的火焰即将永远熄灭！我就知道你能行的！', `MaleText_loc5`='很好─我們成功了!塑像中的火焰即將永遠熄滅!我就知道你能行的!', `MaleText_loc7`='¡Ya está! ¡Lo hemos conseguido! ¡El ritual está en marcha y los fuegos ídolos están a punto de desaparecer para siempre! ¡Sois verdaderos héroes, como yo pensaba!' WHERE `ID`=4507;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 채집병을 후려칩니다. 녹색 폐기물을 뒤집어 써 아주 우스운 꼴이 되었습니다.', `MaleText_loc4`='%s急速甩动着你收集的瓶子。绿色的光芒照耀着你。你看上去挺不寻常的，朋友。', `MaleText_loc5`='%s拍打著你的採樣之瓶。綠色的光芒籠罩著你。你看起來不是很美，朋友。', `MaleText_loc7`='%s golpea tu vial de coleccionista. Te cubre el resplandor verdoso. Ahora no pareces tan duro, amigo.' WHERE `ID`=4508;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 세나리온 의회에는 무슨 일인가요?', `MaleText_loc4`='你找塞纳里奥议会有什么事，$n？', `MaleText_loc5`='你找塞納里奧議會有什麼事，$n?', `MaleText_loc7`='¿Qué te trae al Círculo Cenarion, $n?', `FemaleText_loc1`='$n, 세나리온 의회에는 무슨 일인가요?', `FemaleText_loc4`='你找塞纳里奥议会有什么事，$n？', `FemaleText_loc5`='你找塞納里奧議會有什麼事，$n?', `FemaleText_loc7`='¿Qué te trae al Círculo Cenarion, $n?' WHERE `ID`=4509;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련을 받으러 왔습니다.', `MaleText_loc4`='我准备接受训练。', `MaleText_loc5`='我準備接受訓練。', `MaleText_loc7`='He venido para recibir instrucción.', `FemaleText_loc1`='훈련을 받으러 왔습니다.', `FemaleText_loc4`='我准备接受训练。', `FemaleText_loc5`='我準備接受訓練。', `FemaleText_loc7`='He venido para recibir instrucción.' WHERE `ID`=4510;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 내가 외딴 곳에 있다는 건 나도 알고 있소. 알고 있다니까!$B$B사실 내 집은 톱니항에 있는데 비행선이 이곳에 불시착해버린 거요. 여기 떨어진 김에 눌러앉아 그동안 해보고 싶던 연구나 해 볼까 하오!', `MaleText_loc4`='我知道，我知道，我知道我根本不知道自己在哪里！$B$B我的家在棘齿城，不过既然我的飞艇在这儿坠落了，那我不如现在就开始进行我的研究项目了！', `MaleText_loc5`='我知道，我知道，我知道我根本不知道自己在哪裡!$B$B我的家在棘齒城，不過既然我的飛艇在這兒墜落了，那我不如現在就開始進行我的研究項目了!', `MaleText_loc7`='¡Lo sé, lo sé, estoy aquí en medio de la nada!$B$BMi hogar está en realidad en Trinquete, pero después de que choqué mi zepelín allí, pensé que podía también empezar la investigación que vine a realizar aquí.' WHERE `ID`=4511;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시체 위에 홀연히 천둥매의 영혼이 나타납니다. 희미한 두 눈이 당신 너머의 뭔가를 응시하듯이 당신을 꿰뚫어 봅니다.', `MaleText_loc4`='灵魂还在尸体旁徘徊。它那可怕的眼睛死死地盯着你……', `MaleText_loc5`='靈魂還在屍體旁徘徊。它那鬼魅般的眼睛死死地盯著你...', `MaleText_loc7`='El espíritu flota sobre su cuerpo caído. Sus fantasmales ojos te atraviesan mientras mira, absorto, más allá...' WHERE `ID`=4512;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='페랄라스 - 계곡천둥매의 영혼 - 임무 수행 중 기본 인사말', `MaleText_loc4`='Feralas - Screecher Spirit - On Quest Default Greeting', `MaleText_loc5`='Feralas - Screecher Spirit - On Quest Default Greeting', `MaleText_loc7`='Feralas - espíritu estridador - saludo habitual durante la misión' WHERE `ID`=4514;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 정말로 배고픈 것 같습니다!', `MaleText_loc4`='%s感到饥饿难耐！', `MaleText_loc5`='%s變得非常餓!', `MaleText_loc7`='¡%s se está poniendo muy hambriento!' WHERE `ID`=4515;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 굉장히 고픈 듯 침을 흘려 댑니다!', `MaleText_loc4`='%s饥饿难耐！', `MaleText_loc5`='%s非常餓!', `MaleText_loc7`='¡%s está MUY HAMBRIENTO!' WHERE `ID`=4516;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n, 페랄라스에는 많은 일이 있었답니다. 대지와 나무, 생물이... 모두 페랄라스의 현재와 미래를 바꿔놓고 있습니다.$B$B하지만 저 위의 쌍둥이 바위산 만큼은 언제나 한결같지요.', `FemaleText_loc4`='菲拉斯的土地经历了岁月的洗礼，$r。大地、树木和生物，它们改变着菲拉斯的现状和未来。$B$B跟这儿所发生的一切相比，双塔山可以算是亘古不变的了……', `FemaleText_loc5`='菲拉斯的土地經歷了歲月的洗禮，$r。大地、樹木和生物，它們改變著菲拉斯的現狀和未來。$B$B跟這兒所發生的一切相比，雙塔山可以算是亙古不變的了...', `FemaleText_loc7`='La tierra de Feralas ha pasado por muchas cosas, $r. La tierra, los árboles, las criaturas, todos se ven afectados por lo que Feralas es y será.$B$BLos Dos Colosos que están sobre nosotros son una constante, no obstante, todo lo que ha pasado aquí...' WHERE `ID`=4517;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쌍둥이 바위산의 멋진 자연 경관을 구경하셨나요? 무사히 아래로 내려갈 수 있도록 필요한 분께 낙하산을 팔고 있습니다.', `MaleText_loc4`='为了让上来观光的旅行者安全地下去，我可以为你提供翅膀。', `MaleText_loc5`='為了讓上來觀光的旅行者安全地下去，我可以為你提供翅膀。', `MaleText_loc7`='Para bajar con seguridad daré alas a quien las necesite.' WHERE `ID`=4518;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내려가도록 도와줄 수 있습니까?', `MaleText_loc4`='你能帮我下去吗？', `MaleText_loc5`='你能幫我下去嗎?', `MaleText_loc7`='¿Puedes ayudarme a bajar?', `FemaleText_loc1`='내려가도록 도와줄 수 있습니까?', `FemaleText_loc4`='你能帮我下去吗？', `FemaleText_loc5`='你能幫我下去嗎?', `FemaleText_loc7`='¿Puedes ayudarme a bajar?' WHERE `ID`=4519;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러고 보니 어제 오후 뭔가 이상한 걸 본 것 같소.$B$B어제 여기서 남동쪽에 있는 고대 트롤 유적지를 달려가고 있었는데... 뭐, 달렸다기보다 팔짝거렸다고 해야 하나... 모래가 워낙 뜨거워서 말이오!$B$B어쨌든 유적지를 지나 뛰어가고 있었는데 그곳에 야영지가 하나 있었소이다. 야영을 하기에는 좀 이상한 장소였지... 그 미친 독수리 하나만 없었어도 좀 더 살펴볼 수 있었는데 말이오.', `MaleText_loc4`='嗯，既然你提及了这一点，不错，昨天下午我确实看见了奇怪的事情！$B$B当我从东南方的巨魔废墟处跑过时……好吧，我其实不是跑过去的，应该说是跳过去的……沙地真是太烫了！$B$B总之，当我从废墟旁跳过的时候，我注意到那儿有一座营帐。我不得不说，在那儿设立营帐是件可笑的事儿……我本来要到那里去看看的，但是一只疯狂的大秃鹫把我赶走了。', `MaleText_loc5`='嗯，既然你提及了這一點，不錯，昨天下午我確實看見了奇怪的事情!$B$B當我從東南方的食人妖廢墟處跑過時...好吧，我其實不是跑過去的，應該說是跳過去的...沙地真是太燙了!$B$B總之，當我從廢墟旁跳過的時候，我注意到那兒有一座營帳。我不得不說，在那兒設立營帳是件可笑的事兒...我本來要到那裡去看看的，但是一隻瘋狂的大禿鷹把我趕走了。', `MaleText_loc7`='Bueno, ahora que lo mencionas, sí, vi algo que consideré un poco extraño ayer por la tarde.$B$BPasaba cerca de unas antiguas ruinas trol al sudeste de aquí. Bueno, en realidad no estaba corriendo, estaba saltando... ¡La arena está ardiendo!$B$BEn cualquier caso, iba saltando mientras pasaba junto a las ruinas, cuando descubrí un campamento instalado en ese lugar. En realidad, parece un lugar extraño para montar un campamento, si quieres saber mi opinión. Habría husmeado un poco más por la zona, pero uno de esos buitres grandes y peligrosos empezó a perseguirme.' WHERE `ID`=4520;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라제는 $n 따라간다! 라제는 침입자 쳐부순다! 쳐부순다! 쳐부순다! 쳐부순다! 지팡이로 라제한테 시키면 돼! 쳐부순다!', `MaleText_loc4`='拆毁者跟着$n！把偷猎者碾成粉！毁灭他们！告诉拆毁者什么时候出击！碾碎一切！', `MaleText_loc5`='拆毀者跟著$n!把盜獵者碾成粉!毀滅他們!告訴拆毀者什麼時候出擊!碾碎一切!', `MaleText_loc7`='¡Arrasa seguir a $n! ¡Arrasa MACHACAR cazadores! ¡MACHACAR, MACHACAR, MACHACAR! ¡Dile a Arrasa que juegue a MACHACAR jugando con un palo! ¡MACHACAR!' WHERE `ID`=4521;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오! 다 됐소!', `MaleText_loc4`='嘿，搞定了。', `MaleText_loc5`='嘿，搞定了。', `MaleText_loc7`='¡Ya está! Terminado.' WHERE `ID`=4522;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='걱정 마. 야옹아! 좋은 주인을 찾아줄게.', `MaleText_loc4`='不要担心，我会给你找个好心人的。', `MaleText_loc5`='不要擔心，我會給你找個好心人的。', `MaleText_loc7`='No te preocupes, te encontraré un buen hogar.' WHERE `ID`=4523;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누구... 제 귀여운 냐옹이 길러주실 분?', `MaleText_loc4`='谁能收养我可爱的小猫咪啊？', `MaleText_loc5`='誰能收養我可愛的小貓咪啊?', `MaleText_loc7`='¿Alguien puede darle un hogar a mi adorable gatito?' WHERE `ID`=4524;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말도 안 돼. 아빠가 우리 냐옹이 못 키우게 해요.', `MaleText_loc4`='我不敢相信我爸爸居然不让我养它。', `MaleText_loc5`='我不敢相信我爸爸居然不讓我養它。', `MaleText_loc7`='No puedo creer que papá no me deje conservar a tu hermana.' WHERE `ID`=4525;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='귀여운 새끼 고양이 팔아요! 좋은 주인이 돼주실 분 찾습니다!', `MaleText_loc4`='卖猫咪啦，我要给它找个好人家。', `MaleText_loc5`='賣貓咪啦，我要給它找個好人家。', `MaleText_loc7`='Gatitos en venta, estamos buscándoles un buen hogar.' WHERE `ID`=4526;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대체 알레르기는 뭐예요? 그게 우리 야옹이랑 무슨 상관이 있다는 거지?', `MaleText_loc4`='过敏症究竟意味着什么？这对我的两只小猫有什么影响？', `MaleText_loc5`='過敏症究竟意味著什麼?這對我的兩隻小貓有什麼影響?', `MaleText_loc7`='¿Pero qué quiere decir "alérgico"? ¿Y qué tiene que ver eso con mis gatitos?' WHERE `ID`=4527;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 우리 야옹이 좀 입양해 주세요! 털도 별로 안 빠져요.', `MaleText_loc4`='有没有人愿意给我的小猫一个温暖的家?', `MaleText_loc5`='有沒有人願意給我的小貓一個溫暖的家?', `MaleText_loc7`='¿Alguien podría proporcionar un buen hogar a mi gatito?' WHERE `ID`=4528;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안 돼! 학카르를 소환하게 놔둘 수는 없다!', `FemaleText_loc4`='不！我们决不能让你召唤哈卡！', `FemaleText_loc5`='不!我們決不能讓你召喚哈卡!', `FemaleText_loc7`='¡No! ¡No podemos permitir que invoques a Hakkar!' WHERE `ID`=4529;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='절대로 우리의 신을 불러낼 수는 없다!', `FemaleText_loc4`='你不能召唤我们的神！', `FemaleText_loc5`='你不能召喚我們的神!', `FemaleText_loc7`='¡No puedes invocar a nuestro dios!' WHERE `ID`=4530;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안 돼! 그래서는 안 된다!', `FemaleText_loc4`='不！你不能这样做！', `FemaleText_loc5`='不!你不能這樣做!', `FemaleText_loc7`='¡No! ¡No debes hacer eso!' WHERE `ID`=4531;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='멈춰라, 이 침략자!', `FemaleText_loc4`='住手！异教徒！', `FemaleText_loc5`='住手!異教徒!', `FemaleText_loc7`='¡Basta! ¡Infieles!' WHERE `ID`=4532;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어... 왜 이러지?', `FemaleText_loc4`='发……发生了什么事？', `FemaleText_loc5`='發...發生了什麼事?', `FemaleText_loc7`='¿Q... qué está pasando?' WHERE `ID`=4533;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구해주셔서 감사합니다!$B$B저는 스톰윈드에서 온 요리사 겸 연금술사예요. 앵거스 삼촌에게 갖다 드리려고 이 지방에서 나는 약초와 조리법을 찾다가 이 가시멧돼지들에게 붙잡혔답니다. 당신이 오지 않았다면 분명 녀석들의 스튜 냄비 속에서 끝장났을 거예요!', `MaleText_loc4`='谢谢你救了我！$B$B我是一名来自暴风城的厨师兼炼金师。我到这儿来是要帮我叔叔安古斯寻找草药和食物的，但是这些野猪人将我抓了起来。要不是你赶过来的话，我想我已经被它们煮着吃了。', `MaleText_loc5`='謝謝你救了我!$B$B我是一名來自暴風城的廚師兼鍊金師。我到這兒來是要幫我叔叔安古斯尋找草藥和食物的，但是這些野豬人將我抓了起來。要不是你趕過來的話，我想我已經被它們煮著吃了。', `MaleText_loc7`='¡Gracias por salvarme!$B$BSoy cocinero y alquimista de Ventormenta. Vine aquí buscando hierbas de la zona y recetas locales para mi tío Angus cuando me capturaron esos jabaespines. ¡Si no hubieras acudido en mi ayuda, seguramente habría terminado en su olla de potajes!' WHERE `ID`=4534;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요리사란 말입니까? 저도 요리를 조금 하는데... 혹시 제게 가르쳐줄 조리법이 있나요?', `MaleText_loc4`='你会烹饪？我也会！你有什么独门菜谱可以传授给我吗？', `MaleText_loc5`='你會烹飪?我也會!你有什麼獨門食譜可以傳授給我嗎?', `MaleText_loc7`='¿Sabes cocinar? ¡¡Claro que sí!! ¿Tienes una receta que puedas enseñarme?', `FemaleText_loc1`='요리사란 말입니까? 저도 요리를 조금 하는데... 혹시 제게 가르쳐줄 조리법이 있나요?', `FemaleText_loc4`='你会烹饪？我也会！你有什么独门菜谱可以传授给我吗？', `FemaleText_loc5`='你會烹飪?我也會!你有什麼獨門食譜可以傳授給我嗎?', `FemaleText_loc7`='¿Sabes cocinar? ¡¡Claro que sí!! ¿Tienes una receta que puedas enseñarme?' WHERE `ID`=4535;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네. 쓸만한 조리법이 하나 있긴 합니다. 가르쳐드리지요!', `MaleText_loc4`='嗯……对，我这里确实有一些挺有用的菜谱。让我来教你吧！', `MaleText_loc5`='嗯...對，我這裡確實有一些挺有用的食譜。讓我來教你吧!', `MaleText_loc7`='Um... sí, tengo una receta que te podría ser útil. ¡Deja que te la enseñe!' WHERE `ID`=4536;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연금술사란 말입니까? 저도 연금술을 조금 익혔는데... 혹시 제게 가르쳐줄 만한 거라도 있습니까?', `MaleText_loc4`='你是个炼金师？我也是。也许你可以教我些东西……', `MaleText_loc5`='你是個鍊金師?我也是。也許你可以教我些東西...', `MaleText_loc7`='¿Eres alquimista? Yo también. Quizás puedas enseñarme lo que sabes...', `FemaleText_loc1`='연금술사란 말입니까? 저도 연금술을 조금 익혔는데... 혹시 제게 가르쳐줄 만한 거라도 있습니까?', `FemaleText_loc4`='你是个炼金师？我也是。也许你可以教我些东西……', `FemaleText_loc5`='你是個鍊金師?我也是。也許你可以教我些東西...', `FemaleText_loc7`='¿Eres alquimista? Yo también. Quizás puedas enseñarme lo que sabes...' WHERE `ID`=4537;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 희귀한 연금술을 하나 압니다. 제가 가르쳐드리죠!', `MaleText_loc4`='不错，我确实知道一种罕见的炼金术配方。让我来教你吧！', `MaleText_loc5`='不錯，我確實知道一種罕見的鍊金術配方。讓我來教你吧!', `MaleText_loc7`='Bueno, sí, conozco una receta alquímica extraña. ¡Déjame enseñártela!' WHERE `ID`=4538;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 눈에 띄게 약해졌습니다. 퇴마 저주가 효과를 보이고 있습니다!', `MaleText_loc4`='%s的力量明显被削弱了。恶魔诅咒起作用了！', `MaleText_loc5`='%s明顯地衰弱了。惡魔詛咒起作用了!', `MaleText_loc7`='%s está claramente debilitado. ¡La maldición está funcionando!' WHERE `ID`=4539;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 훨씬 약해져 공격을 거의 막아내지 못하고 있습니다. 퇴마 저주가 효과를 보이고 있습니다!', `FemaleText_loc4`='%s渐渐招架不住你的攻势，恶魔诅咒生效了！', `FemaleText_loc5`='%s對你的攻擊產生了反應，惡魔詛咒生效了!', `FemaleText_loc7`='%s es fundamentalmente más susceptible a tus ataques. ¡El Vilhechizo funciona!' WHERE `ID`=4540;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 더는 어떤 마법이나 저주도 걸지 못하고 있습니다. 퇴마 저주의 효과가 나타나고 있습니다!', `MaleText_loc4`='%s似乎再也不能施放法术了。恶魔诅咒起作用了！', `MaleText_loc5`='%s似乎再也不能施展法術了。惡魔詛咒已經起作用了!', `MaleText_loc7`='%s tiene aspecto de no poder lanzar más hechizos. ¡El Vilhechizo funciona!' WHERE `ID`=4541;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 마력이 깃든 무기가 준비됐네, $n.', `MaleText_loc4`='你的武器完成了，$n。', `MaleText_loc5`='你的武器完成了，$n。', `MaleText_loc7`='Tu arma vil está lista, $n.' WHERE `ID`=4542;
