UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 마법의 힘을 반사하기 시작합니다...', `FemaleText_loc4`='%s开始施放一个反制法术……', `FemaleText_loc5`='%s開始施展一個反制法術...', `FemaleText_loc7`='%s comienza a lanzar un contrahechizo.' WHERE `ID`=4547;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 조심해서 섞어야 하... 아이쿠! 이런, 좀 쏟아버렸군. 하지만 다 만들었소!', `MaleText_loc4`='我要小心地配制这种——啊！……嗯，洒了一些出来，但是已经做好了！', `MaleText_loc5`='我要小心地配製這種─啊!...嗯，灑了一些出來，但是已經做好了!', `MaleText_loc7`='¡¡Voy a mezclar esto con cuidado, vaya!!... Se me ha derramado un poco, ¡pero está listo!' WHERE `ID`=4548;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 누가 나를 부른 것이냐?', `MaleText_loc4`='谁胆敢召唤我？', `MaleText_loc5`='誰膽敢召喚我?', `MaleText_loc7`='¿Quién osa invocarme?' WHERE `ID`=4549;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오게나! 고블린 기계공학 설계도는 허가 받은 고블린 기술자만이 이용할 수 있다네.', `MaleText_loc4`='你好！如果你是来购买地精工程学图纸的，那你一定要知道，我们只为注册地精工程师服务。', `MaleText_loc5`='你好!如果你是來學習哥布林工程學結構圖的話，請了解我們只接受合格的哥布林工程師。', `MaleText_loc7`='¡Saludos! Si has venido para acceder a los sistemas de ingeniería goblin, debes saber que solo tratamos con ingenieros goblins certificados.' WHERE `ID`=4550;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고블린 기계공학 비밀 설계도를 이용합니다!', `MaleText_loc4`='获取秘密的地精工程学结构图！', `MaleText_loc5`='獲取秘密的哥布林工程學結構圖!', `MaleText_loc7`='¡Accede a los sistemas secretos de ingeniería goblin!', `FemaleText_loc1`='고블린 기계공학 비밀 설계도를 이용합니다!', `FemaleText_loc4`='获取秘密的地精工程学结构图！', `FemaleText_loc5`='獲取秘密的哥布林工程學結構圖!', `FemaleText_loc7`='¡Accede a los esquemas secretos de ingeniería goblin!' WHERE `ID`=4551;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오세요! 노움 기계공학 설계도를 이용하려고 오셨다면, 잘 오신 겁니다. 우리 측정기 결과로는 당신이 인증된 노움 기술자시니까요!', `MaleText_loc4`='你好！欢迎你来购买侏儒工程学图纸。我们的扫描仪已经确认，你是注册侏儒工程师！', `MaleText_loc5`='你好!如果你是來學習地精工程學結構圖的話，我們非常歡迎你。我們的掃瞄器顯示你是一名合格的地精工程師。', `MaleText_loc7`='¡Saludos! Si has venido para acceder a los sistemas de ingeniería gnómica, te damos la bienvenida. ¡Nuestros escáneres nos informan de que eres un ingeniero gnómico certificado!' WHERE `ID`=4552;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노움 기계공학 비밀 설계도를 이용합니다!', `MaleText_loc4`='获取秘密的侏儒工程学结构图！', `MaleText_loc5`='獲取秘密的地精工程學結構圖!', `MaleText_loc7`='¡Accede a los sistemas secretos de ingeniería gnómica!', `FemaleText_loc1`='노움 기계공학 비밀 설계도를 이용합니다!', `FemaleText_loc4`='获取秘密的侏儒工程学结构图！', `FemaleText_loc5`='獲取秘密的地精工程學結構圖!', `FemaleText_loc7`='¡Accede a los esquemas secretos de ingeniería gnómica!' WHERE `ID`=4553;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요. 나는 오글소프라고 하는데 당신이 가지고 있을지도 모르는 멋진 노움 기계 장치를 내가 만들었습니다! 장치가 폭발했어도 제 잘못이 아닙니다. 혹시 장치 덕분에 돈을 많이 벌었다면 사용료에 대해 얘기 좀 해야겠군요!$B$B아, 만약 당신이 놈리건에서 온 거라면 90도씩 두 번 돌아 그 장치를 부숴버리고 가세요. 당신한테 더 할 말 없습니다.', `MaleText_loc4`='你好，$g小伙子:姑娘;……我是奥格索普，你拥有的某件侏儒设备很可能就是我发明的！如果它爆炸了，那它就不是我发明的；如果它给你带来了财富，那我们可以讨论一下版权金的问题！$B$B哦，对了，如果你来自诺莫瑞根，那你可以走了。我没有什么跟你好说的。', `MaleText_loc5`='你好，$g小夥子:姑娘;...我是奧格索普，你擁有的某件地精設備很可能就是我發明的!如果它爆炸了，那它就不是我發明的;如果它給你帶來了財富，那我們可以討論一下版權金的問題!$B$B哦，對了，如果你來自諾姆瑞根，那你可以走了。我沒有什麼跟你好說的。', `MaleText_loc7`='Hola, $gmuchacho:muchacha;... mi nombre es Oglethorpe y es posible que sea el creador del aparato más fascinante que nunca hayas tenido en tu poder. Si te ha explotado, no soy responsable. Si por el contrario te ha hecho rico, ¡podemos empezar a hablar de los derechos de autor!$B$BAh, y si eres de Gnomeregan no tengo nada que hablar contigo.' WHERE `ID`=4554;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이고, 저의 은인이 아니신가요! 또 만나서 반가와요. 지금까지 저와 제 발명 작업을 도와준 데 대해 뭐라고 감사해야 할지 모르겠네요.$B$B뭐 도와드릴 일이라도 있나요?', `MaleText_loc4`='哦，这不是$n嘛！很高兴再见到你，我无法表达我对你的感激之情，你帮我及时完成了发明。$B$B我能为你做什么事吗？', `MaleText_loc5`='哦，這不是$n嘛!很高興再見到你，我無法表達我對你的感激之情，你幫我及時完成了發明。$B$B我能為你做什麼事嗎?', `MaleText_loc7`='¡Pero si es $n! Me alegro de verte otra vez. Apenas puedo expresar mi gratitud por la ayuda que nos has brindado hasta hoy a mí y a mi trabajo de inventor.$B$B¿Qué puedo hacer por ti hoy?' WHERE `ID`=4555;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 수석땜장이 오버스파크라고 하오. 현대 노움 기계공학 원리를 설계한 중심 인물이라고 할 수 있지. 내 임무는 노움의 만능 스패너를 이용해 발명의 역사에 길이 남을 눈부신 기계를 만드는 거요.$B$B혹시 쓸만한 방사선 제거용 설계도를 찾게 되거든 우리에게 가져와 주시오. 요새 그게 필요하거든.', `MaleText_loc4`='我是大工匠欧沃斯巴克，现代侏儒工程学领域的顶级设计师。我的工作就是用我们的闪亮崭新的扳手确保新的发明能够付诸实施！$B$B要是你碰巧懂得制造消除辐射污染的装置，那你算是来对地方啦……', `MaleText_loc5`='我是技工大師歐沃斯巴克，現代地精工程學領域的頂級設計師。我的工作就是用我們的閃亮嶄新的扳手確保新的發明能夠付諸執行!$B$B要是你碰巧懂得製造消除輻射污染的裝置，那你算是來對地方啦...', `MaleText_loc7`='Soy el maestro manitas Sobrechispa y soy el arquitecto jefe encargado de desarrollar los principios actuales de ingeniería gnómica del mundo. Mi trabajo es garantizar que el poder de la invención continúe brillando con mayor intensidad desde nuestras llaves de tuerca arcoluz que desde cualquier otro lugar.$B$BAsimismo, si de casualidad conoces un buen sistema de eliminación de radiaciones, estamos buscando uno en el mercado ahora mismo...' WHERE `ID`=4556;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알기 쉽게 수학적으로 가르쳐드리지. 고블린 + 기계공학 = 전문 지식이란 말이오, 젊은 친구. 그걸 부인하는 자는 덧셈도 할 줄 모르는 거라고.', `MaleText_loc4`='宝贝，让我来教你一个简单的加法守则：“地精”+“工程学”=“万事通”。告诉你其它算法的家伙肯定数学不及格。', `MaleText_loc5`='寶貝，讓我來教你一個簡單的加法守則:「哥布林」+「工程學」=「萬事通」。告訴你其他演算法的傢伙肯定數學不及格。', `MaleText_loc7`='Déjame enseñarte algo de mates: "goblin" más "ingeniería" igual a SABER. Si alguien te dice otra cosa es que no tiene ni idea de sumar.' WHERE `ID`=4557;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런트여, 공격이다!', `MaleText_loc4`='步兵！进攻！', `MaleText_loc5`='蠻兵!進攻!', `MaleText_loc7`='¡Brutos! ¡Ataquen!', `FemaleText_loc1`='그런트여, 공격이다!', `FemaleText_loc4`='步兵！进攻！', `FemaleText_loc5`='蠻兵!進攻!', `FemaleText_loc7`='¡Brutos! ¡Ataquen!' WHERE `ID`=4558;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수호병! 센진 마을을 지켜주세요!', `MaleText_loc4`='卫兵！保护森金！', `MaleText_loc5`='守護者!保護森金!', `MaleText_loc7`='¡Guardianes! ¡Defended a Sen''jin!', `FemaleText_loc1`='수호병! 센진 마을을 지켜주세요!', `FemaleText_loc4`='卫兵！保护森金！', `FemaleText_loc5`='守護者!保護森金!', `FemaleText_loc7`='¡Guardianes! ¡Defended a Sen''jin!' WHERE `ID`=4559;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 신성한 땅을 더럽히지는 못할 것이다!', `MaleText_loc4`='你不能玷污我们的圣地！', `MaleText_loc5`='你不能玷污我們的聖地!', `MaleText_loc7`='¡No profanarás nuestra tierra sagrada!', `FemaleText_loc1`='우리의 신성한 땅을 더럽히지는 못할 것이다!', `FemaleText_loc4`='你不能玷污我们的圣地！', `FemaleText_loc5`='你不能玷污我們的聖地!', `FemaleText_loc7`='¡No profanarás nuestra tierra sagrada!' WHERE `ID`=4560;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경비병!', `MaleText_loc4`='卫兵！', `MaleText_loc5`='守衛!', `MaleText_loc7`='¡Guardias!', `FemaleText_loc1`='경비병!', `FemaleText_loc4`='卫兵！', `FemaleText_loc5`='守衛!', `FemaleText_loc7`='¡Guardias!' WHERE `ID`=4561;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파수꾼이여, 도와주시오!', `MaleText_loc4`='哨兵部队，来保护我！', `MaleText_loc5`='哨兵部隊，來保護我!', `MaleText_loc7`='¡Centinelas, venid en mi defensa!', `FemaleText_loc1`='파수꾼이여, 도와주시오!', `FemaleText_loc4`='哨兵部队，来保护我！', `FemaleText_loc5`='哨兵部隊，來保護我!', `FemaleText_loc7`='¡Centinelas, venid en mi defensa!' WHERE `ID`=4562;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나름대로 조사를 해보니, 자네가 학카르의 화신을 물리친 것이 그를 약하게 만든 모양이오. 하지만 머나 먼 뒤틀린 황천 구석에는 그의 힘이 아직도 많이 남아있소.$B$B당신은 이미 학카르의 화신을 한번 쓰러뜨렸소. 한 번 더 그를 쓰러뜨린다면 그의 힘이 더욱 약해져 언젠가는 화신이 아니라, 그 진짜 모습을 드러낼지 모르오.$B$B죽은 신의 성소에서 학카르의 화신을 다시 소환할 수 있는 마법을 내가 준비해놓았소. 한 번 더 싸워보겠소?', `MaleText_loc4`='通过研究，我发现在哈卡的化身被击败之后，他的力量也会随之减弱。但是哈卡的大部分力量仍保留在扭曲虚空的深处。$B$B你曾经击败过哈卡的化身，$n。或许再次击败他的话就可以进一步削弱他的力量，也许有一天我们就将面对他的真身。$B$B我为你准备了一张卷轴，你可以用它在堕神圣地中再次召唤哈卡的化身。你敢再次迎接哈卡的挑战吗？', `MaleText_loc5`='通過研究，我發現在哈卡的化身被擊敗之後，他的力量也會隨之減弱。但是哈卡的大部分力量仍保留在扭曲虛空的深處。$B$B你曾經擊敗過哈卡的化身，$n。或許再次擊敗他的話就可以進一步削弱他的力量，也許有一天我們就將面對他的真身。$B$B我為你準備了一張卷軸，你可以用它在墮神聖地中再次召喚哈卡的化身。你敢再次迎接哈卡的挑戰嗎?', `MaleText_loc7`='A través de mis estudios he podido establecer que el hecho de vencer al avatar del dios Hakkar lo ha debilitado. Pero conserva la mayor parte de su fuerza, acechando en el fondo del Averno.$B$BHas vencido a su avatar una vez, $n. Tal vez si lo vuelves a derrotar lograrás debilitar al dios hasta tal punto que, un día, podamos enfrentarnos a su verdadero ser.$B$BHe preparado un encantamiento que puedes usar para volver a invocar un avatar de Hakkar en el Sagrario del Dios Caído. ¿Quieres volver a enfrentarte a él?' WHERE `ID`=4563;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파수꾼이여, 도와주시오!', `MaleText_loc4`='哨兵部队，来保护我！', `MaleText_loc5`='哨兵部隊，來保護我!', `MaleText_loc7`='¡Centinelas, venid en mi defensa!', `FemaleText_loc1`='파수꾼이여, 도와주시오!', `FemaleText_loc4`='哨兵部队，来保护我！', `FemaleText_loc5`='哨兵部隊，來保護我!', `FemaleText_loc7`='¡Centinelas, venid en mi defensa!' WHERE `ID`=4564;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하시오. 술로 세월을 보내다보니 감각은 둔해졌지만 아직도 내면의 눈은 밝다오.', `MaleText_loc4`='你好，$c。虽然长期饮用烈酒已经让我的感觉变得迟钝了，但我的心灵之眼依然十分强大。', `MaleText_loc5`='你好，$c。雖然長期飲用烈酒已經讓我的感覺變得遲鈍了，但我的心靈之眼依然十分強大。', `MaleText_loc7`='Saludos, $c. Aunque el tiempo y la bebida han embotado mis sentidos, mis ojos interiores continúan siendo fuertes.' WHERE `ID`=4565;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경비병! 도와줘요!', `MaleText_loc4`='卫兵！救救我！', `MaleText_loc5`='守衛!救救我!', `MaleText_loc7`='¡Guardias! ¡Ayudadme!', `FemaleText_loc1`='경비병! 도와줘요!', `FemaleText_loc4`='卫兵！救救我！', `FemaleText_loc5`='守衛!救救我!', `FemaleText_loc7`='¡Guardias! ¡Ayudadme!' WHERE `ID`=4566;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='화신을 소환할 마법을 주십시오.', `MaleText_loc4`='好的，请教我召唤哈卡化身的法术。', `MaleText_loc5`='好的，請教我召喚哈卡化身的法術。', `MaleText_loc7`='Sí. Dame el hechizo para invocar el avatar.', `FemaleText_loc1`='화신을 소환할 마법을 주십시오.', `FemaleText_loc4`='好的，请教我召唤哈卡化身的法术。', `FemaleText_loc5`='好的，請教我召喚哈卡化身的法術。', `FemaleText_loc7`='Sí. Dame el hechizo para invocar el avatar.' WHERE `ID`=4567;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경비병!', `MaleText_loc4`='卫兵！', `MaleText_loc5`='守衛!', `MaleText_loc7`='¡Guardias!', `FemaleText_loc1`='경비병!', `FemaleText_loc4`='卫兵！', `FemaleText_loc5`='守衛!', `FemaleText_loc7`='¡Guardias!' WHERE `ID`=4568;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자다! 침입자를 공격하라!', `MaleText_loc4`='入侵者！攻击入侵者！', `MaleText_loc5`='入侵者!攻擊入侵者!', `MaleText_loc7`='¡Intrusos! ¡Atacad a los intrusos!', `FemaleText_loc1`='침입자다! 침입자를 공격하라!', `FemaleText_loc4`='入侵者！攻击入侵者！', `FemaleText_loc5`='入侵者!攻擊入侵者!', `FemaleText_loc7`='¡Intrusos! ¡Atacad a los intrusos!' WHERE `ID`=4569;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 아즈샤리트의 힘이 흘러나오는 곳을 찾습니다.', `MaleText_loc4`='%s搜寻着魔法能量的源头。', `MaleText_loc5`='%s搜尋著魔法能量的源頭。', `MaleText_loc7`='%s busca una fuente de energía arcana.' WHERE `ID`=4570;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 으르렁거립니다.', `MaleText_loc4`='%s咆哮着。', `MaleText_loc5`='%s低吼著。', `MaleText_loc7`='%s gruñe.' WHERE `ID`=4571;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하시오, $n. 나는 여기서 어린 히포그리프들을 조련하며 돌보고 있소. 마음 편히 둘러보시오.', `MaleText_loc4`='你好，$n。我在这里训练和照料年轻的角鹰兽，你可以随意看看。', `MaleText_loc5`='你好，$n。我在這裡訓練和照料年輕的角鷹獸，你可以隨意看看。', `MaleText_loc7`='Hola, $n. Me encargo de entrenar y cuidar a los jóvenes hipogrifos; echa un vistazo tranquilamente.' WHERE `ID`=4572;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='히포그리프에 대해 더 말씀해주십시오.', `MaleText_loc4`='请告诉我更多关于角鹰兽的事情。', `MaleText_loc5`='請告訴我更多關於角鷹獸的事情。', `MaleText_loc7`='Háblame más sobre esos hipogrifos.', `FemaleText_loc1`='히포그리프에 대해 더 말씀해주십시오.', `FemaleText_loc4`='请告诉我更多关于角鹰兽的事情。', `FemaleText_loc5`='請告訴我更多關於角鷹獸的事情。', `FemaleText_loc7`='Háblame más sobre esos hipogrifos.' WHERE `ID`=4573;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드루이드는 이 세계에서 곤경에 처한 생명체가 있으면 금방 알아차린다오. 히포그리프들이 위기에 처했다는 것을 알고 페랄라스의 타락으로부터 보호하기 위한 대책을 마련했소.$B$B커글 크랭크홉이라는 노움이 그 일을 주도하고 있는데, 그녀가 알을 모아서 이곳으로 보내면 내가 알을 돌본다오.$B$B우리는 이 소명을 위해 도움은 언제라도 환영이오, $n. 가젯잔으로 가서 커글을 한번 찾아보시오.', `MaleText_loc4`='德鲁伊对世界上所有生物的生存状况都非常敏感。当我们知道这些鸟处于危险之中时，便设立了一套营救系统，防止它们遭受菲拉斯的堕落气息的影响。$B$B一个名叫克格尔·曲藤的侏儒负责这项工作，她收集鸟蛋并将其交给我照顾。$B$B我们总是在寻求更多的帮助，$n。或许你该前往加基森找克格尔谈一谈。', `MaleText_loc5`='德魯伊對世界上所有生物的生存狀況都非常敏感。當我們知道這些鳥處於危險之中時，便設立了一套營救系統，防止它們遭受菲拉斯的墮落氣息的影響。$B$B一個名叫克格爾·曲藤的地精負責這項工作，她收集鳥蛋並將其交給我照顧。$B$B我們總是在尋求更多的幫助，$n。或許你該前往加基森找克格爾談話。', `MaleText_loc7`='Los druidas son muy sensibles a las dificultades que padecen todas las criaturas del mundo. Cuando se descubrió que estas aves corrían peligro, ideamos un sistema para rescatarlas de la descomposición de Feralas.$B$BUna gnoma llamada Curgle Saltamanivela se ocupa del asunto. Recoge los huevos y los envía hasta aquí y yo me encargo de cuidarlos.$B$BPodríamos buscar más ayuda para nuestra causa, $n. Tal vez deberías dirigirte a Gadgetzan y buscar a Curgle.' WHERE `ID`=4574;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 한번 감사드립니다, $n. 여기서 기다렸다가 좀 더 잠잠해지면 그때 떠나야겠어요.', `MaleText_loc4`='$n，我要再次对你表示感谢。现在我会留在这里，等安全了再离开。', `MaleText_loc5`='$n，我要再次對你表示感謝。現在我會留在這裡，等安全了再離開。', `MaleText_loc7`='Gracias de nuevo, $n. Esperaré aquí hasta que sea seguro partir.' WHERE `ID`=4575;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='추적용 지옥사냥개 장비를 열고 사용 설명서를 읽어봐야 할 걸세. 여기서 남쪽에 있는 절벽거인의 반도가 가까워지면 그 야수를 소환하게나.', `MaleText_loc4`='你必须打开地狱寻踪犬工具箱，并阅读一下使用说明书。当你接近南面那个满是峭壁巨人的半岛时，就开始召唤地狱寻踪犬吧。', `MaleText_loc5`='你必須打開惡魔尋蹤犬工具箱，並閱讀一下使用說明書。當你接近南面那個滿是峭壁巨人的半島時，就開始召喚惡魔尋蹤犬吧。', `MaleText_loc7`='Tienes que abrir el equipo de rastreo del can manáfago y leer el manual de instrucciones. Invoca a la bestia cuando estés cerca de la península de los gigantes del precipicio, al sur de aquí.' WHERE `ID`=4576;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙소, 작은 $r 친구!', `MaleText_loc4`='谢谢你，小$c！', `MaleText_loc5`='謝謝你，小$r!', `MaleText_loc7`='¡Gracias, $gpequeño:pequeña; $r!' WHERE `ID`=4577;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직은 요리 솜씨가 좀 부족하군요. 손에 물 좀 더 묻히고 오셔야 제가 아는 요리법을 가르쳐드릴 수 있겠네요.', `MaleText_loc4`='你的烹饪水平实在是太低了。再去训练一段时间，也许我就可以教你一些我所知道的东西。', `MaleText_loc5`='你的烹飪水準實在是太低了。再去訓練一段時間，也許我就可以教你一些我所知道的東西。', `MaleText_loc7`='Tu talento en el arte culinario es un poco escaso. Quizás cuando tengas un poco de práctica pueda enseñarte lo que sé.' WHERE `ID`=4578;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저한테 배우기에는 당신의 연금술은 아직 좀 부족합니다. 혹시 나중에 다시 오시면...', `MaleText_loc4`='你的炼金技能还不足以理解我所传授的知识。也许你应该晚些时候再来找我谈谈……', `MaleText_loc5`='你的鍊金技能還不足以理解我所傳授的知識。也許你應該晚些時候再來找我談談...', `MaleText_loc7`='Tus habilidades en alquimia aún no son tan buenas como para que puedas aprovechar mis enseñanzas. Tal vez si me vuelves a buscar más adelante...' WHERE `ID`=4579;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선장님! 놈들이 옵니다! 나가들이 쳐들어오고 있어요!', `MaleText_loc4`='船长，他们来了！纳迦来了！', `MaleText_loc5`='船長，他們來了!納迦來了!', `MaleText_loc7`='Capitán, ¡aquí vienen! ¡Los nagas se acercan!', `FemaleText_loc1`='선장님! 놈들이 옵니다! 나가들이 쳐들어오고 있어요!', `FemaleText_loc4`='船长，他们来了！纳迦来了！', `FemaleText_loc5`='船長，他們來了!納迦來了!', `FemaleText_loc7`='Capitán, ¡aquí vienen! ¡Los nagas se acercan!' WHERE `ID`=4580;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정신이 나약한 자들이나 비전 마법에 압도되어 타락하는 거랍니다. 당신이 흑마법사의 길을 가지는 않을지라도 항상 이것을 기억하도록 하세요.', `MaleText_loc4`='魔法只会腐蚀那些意志薄弱的人。即便你不是术士，最好也牢记这一点。', `MaleText_loc5`='魔法只會腐蝕那些意志薄弱的人。即便你不是術士，最好也牢記這一點。', `MaleText_loc7`='Lo arcano solo corrompe a los débiles. Aunque no sigas la senda del brujo, harías bien en recordarlo.', `FemaleText_loc1`='정신이 나약한 자들이나 비전 마법에 압도되어 타락하는 거랍니다. 당신이 흑마법사의 길을 가지는 않을지라도 항상 이것을 기억하도록 하세요.', `FemaleText_loc4`='魔法只会腐蚀那些意志薄弱的人。即便你不是术士，最好也牢记这一点。', `FemaleText_loc5`='魔法只會腐蝕那些意志薄弱的人。即便你不是術士，最好也牢記這一點。', `FemaleText_loc7`='El poder arcano solo corrompe a los débiles. Aun cuando no sigas el camino de los brujos, harías bien en recordar esto.' WHERE `ID`=4581;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='만나서 반갑네, $n. 내가 도울 일이라도 있나?', `MaleText_loc4`='这是我的荣幸，$n。我能为你做些什么吗？', `MaleText_loc5`='這是我的榮幸，$n。我能為你做些什麼嗎?', `MaleText_loc7`='Un placer, $n. ¿Qué puedo hacer por ti?' WHERE `ID`=4582;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='산악경비대! 도와주세요!', `MaleText_loc4`='卫兵！', `MaleText_loc5`='守衛!', `MaleText_loc7`='¡Guardias!', `FemaleText_loc1`='산악경비대! 도와주세요!', `FemaleText_loc4`='卫兵！', `FemaleText_loc5`='守衛!', `FemaleText_loc7`='¡Guardias!' WHERE `ID`=4583;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나약한 자들이나 마법으로 타락하게 되지. 수련을 계속 쌓지 않으면 제아무리 용맹스러운 당신이라도 운명을 피할 수 없게 마련이라오.', `MaleText_loc4`='魔法只会使弱者堕落。继续你的训练吧，不然你的命运就跟那些家伙相差无几了。', `MaleText_loc5`='魔法只會使弱者墮落。繼續你的訓練吧，不然你的命運就跟那些傢伙相差無幾了。', `MaleText_loc7`='El poder arcano solo corrompe a los débiles. Sigue con tu instrucción, o podrías acabar encontrando un destino similar.', `FemaleText_loc1`='나약한 자들이나 마법으로 타락하게 되지. 수련을 계속 쌓지 않으면 제아무리 용맹스러운 당신이라도 운명을 피할 수 없게 마련이라오.', `FemaleText_loc4`='魔法只会使弱者堕落。继续你的训练吧，不然你的命运就跟那些家伙相差无几了。', `FemaleText_loc5`='魔法只會使弱者墮落。繼續你的訓練吧，不然你的命運就跟那些傢伙相差無幾了。', `FemaleText_loc7`='El poder arcano solo corrompe a los débiles. Sigue con tu instrucción, o podrías acabar encontrando un destino similar.' WHERE `ID`=4584;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙소.', `MaleText_loc4`='谢谢你。', `MaleText_loc5`='謝謝你。', `MaleText_loc7`='Gracias.', `FemaleText_loc1`='고맙소.', `FemaleText_loc4`='谢谢你。', `FemaleText_loc5`='謝謝你。', `FemaleText_loc7`='Gracias.' WHERE `ID`=4590;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전, 이 저주받은 세상에 영원히 매인 몸이랍니다. 필멸의 존재여, 무엇을 원하시나요?', `MaleText_loc4`='要是你想去污染者高地的话，只管找我就行了。', `MaleText_loc5`='我註定永遠被束縛在這個受詛咒的世界。你的慾望是什麼，凡人?', `MaleText_loc7`='Estoy atado a este maldito mundo para toda la eternidad. ¿Cuál es tu deseo, mortal?' WHERE `ID`=4591;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파멸자와 겨루어 보고 싶소.', `MaleText_loc4`='我想要挑战污染者。', `MaleText_loc5`='我想挑戰污染者。', `MaleText_loc7`='Me gustaría enfrentarme al rapiñador.', `FemaleText_loc1`='파멸자와 겨루어 보고 싶소.', `FemaleText_loc4`='我想要挑战污染者。', `FemaleText_loc5`='我想挑戰污染者。', `FemaleText_loc7`='Me gustaría enfrentarme al rapiñador.' WHERE `ID`=4592;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명령을 수행하겠습니다!', `MaleText_loc4`='听你的！', `MaleText_loc5`='聽你的!', `MaleText_loc7`='¡A tus órdenes!', `FemaleText_loc1`='명령을 수행하겠습니다!', `FemaleText_loc4`='听你的！', `FemaleText_loc5`='聽你的!', `FemaleText_loc7`='¡A tus órdenes!' WHERE `ID`=4593;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳을 떠나라... <유물이 희뿌옇고 뜨거운 불길을 내뿜습니다. 머릿속에 환영이 나타납니다. 검은무쇠 드워프 하나가 일곱 개의 시체에 둘러싸여 불타는 비석 앞에 무릎을 꿇고 있습니다.>', `MaleText_loc4`='离开这儿。<废墟中冒出了一道白热的拱形火焰。你的脑海中浮现出一段过去的回忆：七具尸体环绕着一个孤单的黑铁矮人，他在一团巨大的火焰面前跪了下来。>', `MaleText_loc5`='離開這裡。<聖物放射出一道白熱的拱形火焰。一段記憶浮現在你的腦中:七具屍體環繞著一個孤單的黑鐵矮人，他在一團巨大的火焰面前跪了下來。>', `MaleText_loc7`='Abandona este lugar. <La reliquia emite un una llama blanca en forma de arco. Se ha adquirido un recuerdo: Un enano solitario del clan Hierro Negro se encuentra rodeado por siete cadáveres, arrodillado frente a un monolito de fuego.>' WHERE `ID`=4594;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너는 여기서 소멸되리라... <머릿속이 혼돈과 파괴의 환영으로 가득 찹니다.>', `MaleText_loc4`='你会葬身于此。<你的脑海中浮现出混乱和毁灭的情景。>', `MaleText_loc5`='你將被毀滅。<你的意識中充滿了混亂和毀滅的情景。>', `MaleText_loc7`='Morirás aquí. <Tu mente tiene visiones de caos y destrucción.>' WHERE `ID`=4595;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언젠가는 생명이 다할 나약한 존재여, 이 폐허를 더럽히지 말라. <눈부신 빛이 온몸을 둘러쌉니다. 기억나는 것이라고는 온통 화염으로 이루어진 어떤 생명체를 본 것뿐입니다.>', `MaleText_loc4`='凡人，不要玷污这些遗迹。<你全身笼罩在炫目的光芒中。你只记得自己看到了一只完全由火焰组成的生物。>', `MaleText_loc5`='不要玷污這些遺跡，凡人。<你全身籠罩在炫目的光芒中。你只記得自己看到一隻完全由火焰組成的生物。>', `MaleText_loc7`='No mancilles estas ruinas, mortal. <Un destello de luz cegadora te envuelve. Una criatura compuesta totalmente por una llama es lo único que recuerdas haber visto.>' WHERE `ID`=4596;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이방인이여, 도와 다오. <유물이 산산이 부서집니다. 여덟 명의 검은무쇠 드워프들이 어떤 의식을 치르는 환영이 머릿속을 가득 메웁니다.>', `MaleText_loc4`='陌生人，帮帮我们……<古物化为乌有。你脑海中浮现出八个黑铁矮人进行仪式的画面。>', `MaleText_loc5`='幫幫我們，外來人。<聖物化為塵埃。你腦海中浮現出八個黑鐵矮人進行儀式的畫面。>', `MaleText_loc7`='Ayúdanos forastero. <La reliquia se desmorona y se convierte en polvo. Viene a tu mente la visión de ocho enanos Hierro Negro realizando una especie de ritual.>' WHERE `ID`=4597;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그를 이길 수는 없다. <유물이 완전히 타서 사그라집니다. 유물에 담겨 있던 기억을 고스란히 물려받았습니다. 이 도시는 이 세계에 속하지 않는 존재에 의해 파괴되었습니다.>', `MaleText_loc4`='他是无法被打败的。<古物燃烧起来，化为灰烬。你获悉了古物中蕴藏的秘密：这座城市是被一个不属于这个世界的生物摧毁的。>', `MaleText_loc5`='他是無法被打敗的。<聖物被燃燒殆盡。其中的記憶如今只屬於你一人。這座城市是被一個不存在於這個世界的生物所毀滅的。>', `MaleText_loc7`='No se le puede derrotar. <La reliquia arde y se desmorona. Los recuerdos que encierra ahora te pertenecen. Esta ciudad fue destruida por un ser que no es de este mundo.>' WHERE `ID`=4598;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너의 존재는 인정하는 바이다. <유물이 먼지로 변해 버립니다. 새로 얻은 지혜로 인해 머리가 고동칩니다. 이 산의 정수에 사악한 무언가 잠재해 있다는 것이 느껴집니다.>', `MaleText_loc4`='我们都知道你的到来。<古物化为灰烬。你的头脑中充斥着新生的智慧。某种邪恶的东西潜藏在山脉的深处。>', `MaleText_loc5`='我們記住你了。<聖物變成了灰塵。你的腦子充斥著新生的智慧。有某種邪惡的東西潛藏在山脈的深處。>', `MaleText_loc7`='Tu existencia es reconocida <La reliquia se transforma en polvo. Tu cabeza vibra al recibir conocimiento nuevo. Algo maligno acecha en el corazón de la montaña.>' WHERE `ID`=4599;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파멸자... 너는 대가를 치르게 될 것이다. <유물에서 화염의 상징이 뿜어져 나오더니 땅속으로 허물어져 버립니다.>', `MaleText_loc4`='污染者……你会因贸然入侵而遭受惩罚。<一团火焰印记从古物里放射出来，然后消失在大地之中。>', `MaleText_loc5`='污染者...你將會因為你的冒犯而受到懲罰。<一團火焰印記從聖物裡射出，粉碎在大地上。>', `MaleText_loc7`='Corrupto... serás castigado por esta incursión. <Un símbolo en forma de llama irradia desde la reliquia antes de desmoronarse en el suelo.>' WHERE `ID`=4600;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어서 오세요, $n. 아이언포지의 역사에 대해 배우러 오셨습니까?', `FemaleText_loc4`='你好，$n 。你是来学习铁炉堡的历史的？', `FemaleText_loc5`='你好，$n。你是來學習鐵爐堡的歷史的?', `FemaleText_loc7`='Saludos, $n. ¿Has venido a conocer la historia de Forjaz?' WHERE `ID`=4601;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자세한 얘기를 들을 준비가 되면 알려 주시기 바랍니다.', `FemaleText_loc4`='当你准备听我讲述故事的时候就告诉我。', `FemaleText_loc5`='當你準備聽我講述故事的時候就告訴我。', `FemaleText_loc7`='Avísame cuando estés $gpreparado:preparada; para oír la historia.' WHERE `ID`=4602;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아케소누스, 얘기를 들을 준비가 됐습니다.', `MaleText_loc4`='我准备好了，阿克瑟努斯。', `MaleText_loc5`='我準備好了，歷史學家阿克瑟努斯。', `MaleText_loc7`='Estoy preparado, historiadora Archesonus.', `FemaleText_loc1`='아케소누스, 얘기를 들을 준비가 됐습니다.', `FemaleText_loc4`='我准备好了，阿克瑟努斯。', `FemaleText_loc5`='我準備好了，歷史學家阿克瑟努斯。', `FemaleText_loc7`='Estoy preparada, historiadora Archesonus.' WHERE `ID`=4603;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='수백 년 전, 타우릿산의 위대한 도시는 초목이 무성했지만 이젠 황폐해져 먼 옛날의 당당한 위용을 흔적처럼 안고 불타는 평원에 서 있답니다.$B$B타우릿산은 검은무쇠 드워프들의 수도였고, 당시 전체적으로 내란이 벌어지던 중이었어요.$B$B그 지역은 한때 붉은마루 산맥의 일부였는데 거대한 폭발이 일어나 도시는 폐허가 되어 버리고 그 일대는 재로 가득한 황무지가 되어 버렸답니다.', `FemaleText_loc4`='数百年前，伟大的索瑞森城骄傲地矗立在富饶的大地之上，那里现在已经变成了荒芜的燃烧平原。$B$B索瑞森城是黑铁矮人的家乡，它那时正处于一场矮人的内战中。$B$B你知道，那片土地曾是赤脊山的一部分——直到有一天，索瑞森被一场大爆炸吞噬。城市变成一片废墟，周围的地区也被夷为平地。', `FemaleText_loc5`='數百年前，偉大的索瑞森城驕傲地矗立在富饒的大地之上，那裡現在已經變成了荒蕪的燃燒平原。$B$B索瑞森城是黑鐵矮人的家鄉，它那時正處於一場矮人的內戰中。$B$B你知道，那片土地曾是赤脊山的一部分─直到有一天，索瑞森被一場大爆炸吞噬。城市變成一片廢墟，周圍的地區也被夷為平地。', `FemaleText_loc7`='Hace cientos de años, la gran ciudad de Thaurissan se erguía orgullosa en un terreno exuberante, convertido hoy en las ruinosas Estepas Ardientes.$B$BEn aquel tiempo, Thaurissan era el hogar de los enanos Hierro Negro, en medio de una guerra civil que asolaba a la nación de los enanos.$B$BMira, esa parte del mundo en algún momento formó parte de las montañas Crestagrana, hasta el día en que Thaurissan sucumbió por una gigantesca explosión. La cuidad acabó en la ruina y las zonas aledañas quedaron reducidas a páramos de ceniza.' WHERE `ID`=4604;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비극적인 일이로군요. 어떻게 그런 일이 일어났죠?', `MaleText_loc4`='真惨。这是怎么发生的？', `MaleText_loc5`='真慘。這是怎麼發生的?', `MaleText_loc7`='Eso es trágico. ¿Cómo ocurrió esto?', `FemaleText_loc1`='비극적인 일이로군요. 어떻게 그런 일이 일어났죠?', `FemaleText_loc4`='真惨。这是怎么发生的？', `FemaleText_loc5`='真慘。這是怎麼發生的?', `FemaleText_loc7`='Eso es trágico. ¿Cómo ocurrió esto?' WHERE `ID`=4605;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그건 모릅니다.$B$B하지만 살아남은 검은무쇠 드워프들은 산으로 올라가 그들의 도시를 재건하기 시작했습니다.$B$B타우릿산의 잿더미 위에 검은바위 첨탑이 세워지고 새로운 검은무쇠 제국이 탄생한 것이죠. 이글거리는 협곡 내에서 용광로라는 곳의 방비를 더욱 강화했답니다.$B$B그런데 그때부터 검은무쇠 제국을 지배한 고대 악령에 대한 이야기가 나돌기 시작했어요.', `FemaleText_loc4`='我们不知道。$B$B活下来的黑铁矮人们躲入深山，并开始重建他们的城市。$B$B索瑞森的废墟上又出现了黑石塔和新的黑铁王国。他们在灼热峡谷内建立了新的防御工事，就在众所周知的大熔炉地区。$B$B一个关于远古邪恶力量控制黑铁王国的故事开始流传。', `FemaleText_loc5`='我們不知道。$B$B活下來的黑鐵矮人們躲入深山，並開始重建他們的城市。$B$B索瑞森的廢墟上又出現了黑石塔和新的黑鐵王國。他們在灼熱峽谷內建立了新的防禦工事，就在眾所周知的大熔爐地區。$B$B一個關於遠古邪惡力量控制黑鐵王國的故事開始流傳。', `FemaleText_loc7`='No lo sabemos.$B$BLos Hierro Negro que sobrevivieron se dirigieron al interior de la montaña y allí reconstruyeron su ciudad.$B$BDe las cenizas de Thaurissan emergieron la Cumbre de Roca Negra y la nueva nación Roca Negra. Se construyeron fortificaciones adicionales dentro de la Garganta de Fuego, en el área conocida como la Caldera.$B$BEmpezaron a circular historias de un antiguo ser maligno que controlaba el reino de los Hierro Negro.' WHERE `ID`=4606;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='재미있군요. 계속 얘기해 주십시오.', `MaleText_loc4`='很有意思，请继续。', `MaleText_loc5`='很有意思，請繼續。', `MaleText_loc7`='Interesante... continúa, por favor.', `FemaleText_loc1`='재미있군요. 계속 얘기해 주십시오.', `FemaleText_loc4`='很有意思，请继续。', `FemaleText_loc5`='很有意思，請繼續。', `FemaleText_loc7`='Interesante... continúa, por favor.' WHERE `ID`=4607;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='최근, 검은무쇠 드워프들을 목격하는 사례가 늘어나고 있어요. 황야의 땅 곳곳에 요새를 세우고, 고대 지식을 구하기 위해 울다만 깊숙한 곳으로 대규모 탐색 부대를 보내고 있답니다. 심지어는 우리 본국에까지 침입해 모단 호수 근처 댐을 공격하기도 했답니다.', `FemaleText_loc4`='最近，黑铁矮人更加频繁地出现在地表上。他们在荒芜之地建造了堡垒，并派遣了庞大的探险队到奥达曼深处寻找古代的知识，他们甚至侵入了我们的祖国，攻击我们的巨石水坝。', `FemaleText_loc5`='最近，黑鐵矮人更加頻繁地出現在地表上。他們在荒蕪之地建造了堡壘，並派遣了龐大的探險隊到奧達曼深處尋找古代的知識，他們甚至侵入了我們的祖國，攻擊我們的巨石水壩。', `FemaleText_loc7`='Recientemente, se ha visto a los Hierro Negro en la superficie del mundo cada vez con mayor regularidad. Se han construido fortalezas en las Tierras Inhóspitas. Se han enviado numerosas fuerzas de exploración a las profundidades de Uldaman en busca de un conocimiento arcano. Incluso han invadido nuestra propia tierra, atacando nuestro embalse cerca del Loch.' WHERE `ID`=4608;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='믿을 수가 없군요! 어떻게 감히 그럴 수가 있죠?', `MaleText_loc4`='不可思议！他们怎么如此大胆？？', `MaleText_loc5`='不可思議!他們怎麼如此大膽??', `MaleText_loc7`='¡Increíble! ¡Cómo se atreven!', `FemaleText_loc1`='믿을 수가 없군요! 어떻게 감히 그럴 수가 있죠?', `FemaleText_loc4`='不可思议！他们怎么如此大胆？？', `FemaleText_loc5`='不可思議!他們怎麼如此大膽??', `FemaleText_loc7`='¡Increíble! ¡Cómo se atreven!' WHERE `ID`=4609;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리는 도움이 절실히 필요합니다. 당신이 도와주시겠습니까?', `FemaleText_loc4`='我们需要一些冒险者的帮助，$n。你能帮我吗？', `FemaleText_loc5`='我們需要一些冒險者的幫助，$n。你能幫我嗎?', `FemaleText_loc7`='Necesitamos aventureros que nos ayuden, $n. ¿Nos ayudarás?' WHERE `ID`=4610;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당연히 도와 드려야지요!', `MaleText_loc4`='我当然会帮忙的！', `MaleText_loc5`='我當然會幫忙的!', `MaleText_loc7`='¡Por supuesto que ayudaré!', `FemaleText_loc1`='당연히 도와 드려야지요!', `FemaleText_loc4`='我当然会帮忙的！', `FemaleText_loc5`='我當然會幫忙的!', `FemaleText_loc7`='¡Por supuesto que ayudaré!' WHERE `ID`=4611;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수고했다, 첩보로봇! 네가 돌아와서 정말 기쁘구나!', `MaleText_loc4`='你干得很好，间谍机器人！很高兴你回到我这里！', `MaleText_loc5`='你幹得很好，間諜機器人!很高興你回到我這裡!', `MaleText_loc7`='¡Has hecho un gran trabajo, robot espía! ¡Me alegro de volver a tenerte aquí conmigo!', `FemaleText_loc1`='수고했다, 첩보로봇! 네가 돌아와서 정말 기쁘구나!', `FemaleText_loc4`='你干得很好，间谍机器人！很高兴你回到我这里！', `FemaleText_loc5`='你幹得很好，間諜機器人!很高興你回到我這裡!', `FemaleText_loc7`='¡Has hecho un gran trabajo, robot espía! ¡Me alegro de volver a tenerte aquí conmigo!' WHERE `ID`=4612;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇지! 바로 그걸 기다리고 있었던 거야! 처치해 버려!', `MaleText_loc4`='很好！这就是你等待的机会！杀了他们！', `MaleText_loc5`='很好!這就是你等待的機會!殺了他們!', `MaleText_loc7`='¡Eso es! ¡Eso es lo que estabas esperando! ¡MÁTALOS!', `FemaleText_loc1`='그렇지! 바로 그걸 기다리고 있었던 거야! 처치해 버려!', `FemaleText_loc4`='很好！这就是你等待的机会！杀了他们！', `FemaleText_loc5`='很好!這就是你等待的機會!殺了他們!', `FemaleText_loc7`='¡Eso es! ¡Eso es lo que estabas esperando! ¡MÁTALOS!' WHERE `ID`=4613;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어? 음... 안녕하세요! 돈을 받으러 왔거나 뭔가를 소환하러 온 거라면 잘못 찾아오셨어요. 죄송하게 됐네요!', `MaleText_loc4`='嗯，你好！如果你是来征收费用或者投递传票的，那你一定是将我认作别人了。非常抱歉！', `MaleText_loc5`='嗯，你好!如果你是來徵收費用或者投遞傳票的，那你一定是將我認作別人了。非常抱歉!', `MaleText_loc7`='Um, ¡hola! Si estás aquí para el cobro de honorarios y/o una citación judicial, me has confundido con otro. ¡Lo siento muchísimo!' WHERE `ID`=4614;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제 목걸이를 호수에 빠뜨린 거 같아요. 아빠가 주신 건데 이걸 아시면 무지 화내실 거예요.', `FemaleText_loc4`='我想我的项链掉到湖里去了。那是我爸爸送给我的，他要是知道我弄丢了项链，肯定会气疯的。', `FemaleText_loc5`='我想我的項鍊掉到湖裡去了。那是我爸爸送給我的，他要是知道我弄丟了項鍊，肯定會氣瘋的。', `FemaleText_loc7`='Creo que mi collar cayó en el lago. Mi papá me lo regaló y ahora se va a enfadar conmigo.' WHERE `ID`=4615;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='목걸이를 찾아 주셔서 고맙습니다! 와! 정말 최고예요!', `FemaleText_loc4`='谢谢你，$g先生:小姐;，你找到了我的项链！你是最棒的！', `FemaleText_loc5`='謝謝你，$g先生:小姐;，你找到了我的項鍊!你是最棒的!', `FemaleText_loc7`='¡Gracias, $gseñor:señorita; por encontrar mi collar! ¡Eres lo mejor!' WHERE `ID`=4616;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밖에 있는 그런트들뿐만 아니라 내 형제들과 나도 하이잘 산 전투에 참가했었습니다. 은행에서 돈을 훔치려는 자들은 먼저 우리를 쓰러뜨려야 할 겁니다.', `MaleText_loc4`='先不说外面的那些卫兵，我和我的兄弟们可都参加过海加尔山之战。谁想要在银行里面行窃，那就先过我们这一关。', `MaleText_loc5`='先不說外面的那些蠻兵，我和我的兄弟們可都參加過海加爾山之戰。誰想要在銀行裡面行竊，那就先過我們這一關。', `MaleText_loc7`='Además de los Brutos, mis hermanos y yo luchamos en la batalla de Hyjal. Y el que intente robar el banco tendrá que vérselas primero con nosotros.', `FemaleText_loc1`='밖에 있는 그런트들뿐만 아니라 내 형제들과 나도 하이잘 산 전투에 참가했었습니다. 은행에서 돈을 훔치려는 자들은 먼저 우리를 쓰러뜨려야 할 겁니다.', `FemaleText_loc4`='先不说外面的那些卫兵，我和我的兄弟们可都参加过海加尔山之战。谁想要在银行里面行窃，那就先过我们这一关。', `FemaleText_loc5`='先不說外面的那些蠻兵，我和我的兄弟們可都參加過海加爾山之戰。誰想要在銀行裡面行竊，那就先過我們這一關。', `FemaleText_loc7`='Además de los Brutos, mis hermanos y yo luchamos en la batalla de Hyjal. Y el que intente robar el banco tendrá que vérselas primero con nosotros.' WHERE `ID`=4617;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요... 잠깐만 시간을 내셔서 저희를 좀 도와주시지 않으시겠어요? 제발...', `MaleText_loc4`='你好，$g先生:夫人;……你能花点时间帮帮我吗？求你了。', `MaleText_loc5`='你好，$g先生:夫人;...你能花點時間幫幫我嗎?求你了。', `MaleText_loc7`='Hola, $gseñor:señora;... ¿tienes algo de tiempo para echarnos una mano? ¿Por favor?' WHERE `ID`=4618;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 은행의 안전은 제 목숨을 걸고 보장하겠습니다. 그 정도면 믿고 물건을 맡기시겠습니까?', `MaleText_loc4`='我会用我的鲜血来保证这座银行的安全，你觉得很放心吧？', `MaleText_loc5`='我會用我的鮮血來保證這座銀行的安全，你覺得很放心吧?', `MaleText_loc7`='Protejo la seguridad de este banco con mi propia sangre, ¿es eso suficiente para ti?', `FemaleText_loc1`='이 은행의 안전은 제 목숨을 걸고 보장하겠습니다. 그 정도면 믿고 물건을 맡기시겠습니까?', `FemaleText_loc4`='我会用我的鲜血来保证这座银行的安全，你觉得很放心吧？', `FemaleText_loc5`='我會用我的鮮血來保證這座銀行的安全，你覺得很放心吧?', `FemaleText_loc7`='Protejo la seguridad de este banco con mi propia sangre, ¿es eso suficiente para ti?' WHERE `ID`=4619;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='니다를 도와주셔서 감사해요. 저도 나중에 커서 $n 님 같은 $C|1이;가; 되고 싶어요!', `MaleText_loc4`='再次感谢你帮助希拉里，$g先生:小姐;！我长大了也要成为你这样的英雄！', `MaleText_loc5`='再次感謝你幫助尼達，$g先生:小姐;!我長大了也要成為你這樣的英雄!', `MaleText_loc7`='¡Gracias nuevamente por ayudar a Nida, $gseñor:señorita;! ¡Cuando crezca quiero ser un héroe igual que tú!' WHERE `ID`=4620;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하찮은 고블린 녀석들에게 당신의 소중한 물건을 맡기시겠습니까? 용맹스러운 오그리마 그런트들이 수호하는 저희 은행을 이용해주십시오.', `MaleText_loc4`='你宁愿把你的货物交给一个地精吗?', `MaleText_loc5`='你寧願把你的貨物交給一個哥布林嗎?', `MaleText_loc7`='¿Preferirías confiar tus cosas a un goblin?', `FemaleText_loc1`='하찮은 고블린 녀석들에게 당신의 소중한 물건을 맡기시겠습니까? 용맹스러운 오그리마 그런트들이 수호하는 저희 은행을 이용해주십시오.', `FemaleText_loc4`='你宁愿把你的货物交给一个地精吗?', `FemaleText_loc5`='你寧願把你的貨物交給一個哥布林嗎?', `FemaleText_loc7`='¿Preferirías confiar tus cosas a un goblin?' WHERE `ID`=4621;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오랜 세월 전투와 노예 생활에 지쳤는데, 다시 고향이란 걸 갖게 되니 기분이 좋군요.', `MaleText_loc4`='经历了多年的战乱和奴役生活，再次拥有一个家园的感觉真好。', `MaleText_loc5`='經歷了多年的戰亂和奴役生活，再次擁有一個家園的感覺真好。', `MaleText_loc7`='Tantos años de batallas y esclavitud... es estupendo volver a tener un hogar.', `FemaleText_loc1`='오랜 세월 전투와 노예 생활에 지쳤는데, 다시 고향이란 걸 갖게 되니 기분이 좋군요.', `FemaleText_loc4`='经历了多年的战乱和奴役生活，再次拥有家园的感觉真好。', `FemaleText_loc5`='經歷了多年的戰亂和奴役生活，再次擁有家園的感覺真好。', `FemaleText_loc7`='Tantos años de batallas y esclavitud... es estupendo volver a tener un hogar.' WHERE `ID`=4622;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필요한 게 있거든 빨리 말씀하십시오.', `MaleText_loc4`='告诉我你要什么，别磨磨蹭蹭的。', `MaleText_loc5`='告訴我你要什麼，別磨磨蹭蹭的。', `MaleText_loc7`='Dime qué quieres y hazlo rápido.', `FemaleText_loc1`='필요한 게 있거든 빨리 말씀하십시오.', `FemaleText_loc4`='告诉我你要什么，别磨磨蹭蹭的。', `FemaleText_loc5`='告訴我你要什麼，別磨磨蹭蹭的。', `FemaleText_loc7`='Dime qué quieres y hazlo rápido.' WHERE `ID`=4623;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 몸은 주인님을 섬기기 위해 살 뿐입니다.', `MaleText_loc4`='我活着的目的就是为主人服务。', `MaleText_loc5`='我活著的目的就是為主人服務。', `MaleText_loc7`='Vivo para servir al maestro.' WHERE `ID`=4624;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='만물 상자를 주십시오, 몰트레이크.', `MaleText_loc4`='呈上饰物，玛特拉克。', `MaleText_loc5`='呈上飾物，瑪特拉克。', `MaleText_loc7`='Saca los adornos, Maltrake.', `FemaleText_loc1`='만물 상자를 주십시오, 몰트레이크.', `FemaleText_loc4`='呈上饰物，玛特拉克。', `FemaleText_loc5`='呈上飾物，瑪特拉克。', `FemaleText_loc7`='Saca los adornos, Maltrake.' WHERE `ID`=4625;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필요한 게 있거든 빨리 말씀하십시오.', `MaleText_loc4`='告诉我你要什么，别磨磨蹭蹭的。', `MaleText_loc5`='告訴我你要什麼，別磨磨蹭蹭的。', `MaleText_loc7`='Dime qué quieres y hazlo rápido.', `FemaleText_loc1`='필요한 게 있거든 빨리 말씀하십시오.', `FemaleText_loc4`='告诉我你要什么，别磨磨蹭蹭的。', `FemaleText_loc5`='告訴我你要什麼，別磨磨蹭蹭的。', `FemaleText_loc7`='Dime qué quieres y hazlo rápido.' WHERE `ID`=4626;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='냐옹!', `MaleText_loc4`='喵！', `MaleText_loc5`='喵!', `MaleText_loc7`='¡Miau!' WHERE `ID`=4627;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 고양이 말을 알아듣거든요. 나비가요 고맙다고 하는 거예요.', `FemaleText_loc4`='我知道怎么跟小猫说话，喵喵说谢谢你。', `FemaleText_loc5`='我知道怎麼跟小貓說話，喵喵說謝謝你。', `FemaleText_loc7`='Entiendo el lenguaje de los gatos; Effsee te da las gracias.' WHERE `ID`=4628;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘이 평화로워 보여도 전쟁은 계속되고 있습니다. 아직도 여러 부족이 대족장님의 깃발 아래 싸우고 있습니다. 당신도 친구들과 함께 오그리마를 위한 전투에 가담할 생각입니까?', `MaleText_loc4`='即使在和平时期仍然会有战争，而许多氏族仍在酋长的领导下奋勇作战。你是来为奥格瑞玛而战的吗？', `MaleText_loc5`='即使在和平時?仍然會有戰爭，而許多氏族仍在大酋長的領導下奮勇作戰。你是來為奧格瑪而戰的嗎?', `MaleText_loc7`='Aun cuando estemos en tiempos de paz, sigue habiendo guerra. De hecho, muchos clanes siguen luchando bajo la bandera del Jefe de Guerra. ¿Estás aquí para sumar tu clan a los que luchan por Orgrimmar?', `FemaleText_loc1`='오늘이 평화로워 보여도 전쟁은 계속되고 있습니다. 아직도 여러 부족이 대족장님의 깃발 아래 싸우고 있습니다. 당신도 친구들과 함께 오그리마를 위한 전투에 가담할 생각입니까?', `FemaleText_loc4`='即使在和平时期仍然会有战争，而许多氏族仍在酋长的领导下奋勇作战。你是来为奥格瑞玛而战的吗？', `FemaleText_loc5`='即使在和平時期仍然會有戰爭，而許多氏族仍在大酋長的領導下奮勇作戰。你是來為奧格瑪而戰的嗎?', `FemaleText_loc7`='Aun cuando estemos en tiempos de paz, sigue habiendo guerra. De hecho, muchos clanes siguen luchando bajo la bandera del Jefe de Guerra. ¿Estás aquí para sumar tu clan a los que luchan por Orgrimmar?' WHERE `ID`=4629;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='평화롭다 해도 전쟁은 있게 마련이오. 아직도 여러 부족이 대족장님의 깃발 아래서 싸우고 있소이다. 당신의 부족도 오그리마를 위한 전투에 가담할 생각이오?', `MaleText_loc4`='即使在和平时期仍然会有战争，而许多部落仍在酋长的领导下并肩奋战。你是来为奥格瑞玛而战的吗？', `MaleText_loc5`='即使在和平時期仍然會有戰爭，而許多氏族仍在大酋長的領導下奮勇作戰。你是來為奧格瑪而戰的嗎?', `MaleText_loc7`='Aun cuando estemos en tiempos de paz, sigue habiendo guerra. De hecho, muchos clanes siguen luchando bajo la bandera del Jefe de Guerra. ¿Estás aquí para sumar tu clan a los que luchan por Orgrimmar?', `FemaleText_loc1`='평화롭다 해도 전쟁은 있게 마련이오. 아직도 여러 부족이 대족장님의 깃발 아래서 싸우고 있소이다. 당신의 부족도 오그리마를 위한 전투에 가담할 생각이오?', `FemaleText_loc4`='即使在和平时期仍然会有战争，而许多部落仍在酋长的领导下并肩奋战。你是来为奥格瑞玛而战的吗？', `FemaleText_loc5`='即使在和平時期仍然會有戰爭，而許多氏族仍在大酋長的領導下奮勇作戰。你是來為奧格瑪而戰的嗎?', `FemaleText_loc7`='Aun cuando estemos en tiempos de paz, sigue habiendo guerra. De hecho, muchos clanes siguen luchando bajo la bandera del Jefe de Guerra. ¿Estás aquí para sumar tu clan a los que luchan por Orgrimmar?' WHERE `ID`=4630;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제대로 찾아왔소. 나는 특수한 훈련을 제공하고 있소. 하지만 비용이 꽤 드는데...', `MaleText_loc4`='嗯，我可以训练你，但费用并不便宜。', `MaleText_loc5`='嗯，我可以訓練你，但費用並不便宜。', `MaleText_loc7`='Sí, ofrezco instrucción. Pero no es barata.', `FemaleText_loc1`='제대로 찾아왔소. 나는 특수한 훈련을 제공하고 있소. 하지만 비용이 꽤 드는데...', `FemaleText_loc4`='嗯，我可以训练你，但费用并不便宜。', `FemaleText_loc5`='嗯，我可以訓練你，但費用並不便宜。', `FemaleText_loc7`='Sí, ofrezco instrucción. Pero no es barata.' WHERE `ID`=4631;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하시오, $n! 나는 선임기술자 스쿠티라고 하오.', `MaleText_loc4`='你好，$n！我是一名熟练的技师，我叫斯库提。', `MaleText_loc5`='你好，$n!我是一名工程大師，我叫斯庫提。', `MaleText_loc7`='¡Hola, $n! Soy el maestro en ingeniería, Scooty.' WHERE `ID`=4632;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론, 나는 마법부여를 가르치는 일을 하오. 하지만 기본기는 닦여 있어야 더 큰 배움을 얻을 수 있소이다.', `MaleText_loc4`='如果你准备好了，我会向你传授附魔的知识。', `MaleText_loc5`='如果你準備好了，我會向你傳授附魔的知識。', `MaleText_loc7`='Por supuesto que ofrezco lecciones a otros encantadores, siempre y cuando estés $gpreparado:preparada;.', `FemaleText_loc1`='물론, 나는 마법부여를 가르치는 일을 하오. 하지만 기본기는 닦여 있어야 더 큰 배움을 얻을 수 있소이다.', `FemaleText_loc4`='如果你准备好了，我会向你传授附魔的知识。', `FemaleText_loc5`='如果你準備好了，我會向你傳授附魔的知識。', `FemaleText_loc7`='Por supuesto que ofrezco lecciones a otros encantadores, siempre y cuando estés $gpreparado:preparada;.' WHERE `ID`=4633;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스쿠티, 응답장치를 잃어버렸습니다. 새로 하나 필요합니다.', `MaleText_loc4`='我的传送器被我弄丢了，现在我需要另外一个传送器，斯库提。', `MaleText_loc5`='我的傳送器被我弄丟了，現在我需要另外一個傳送器，斯庫提。', `MaleText_loc7`='Perdí mi transpondedor y necesito otro, Scooty.', `FemaleText_loc1`='스쿠티, 응답장치를 잃어버렸습니다. 새로 하나 필요합니다.', `FemaleText_loc4`='我的传送器被我弄丢了，现在我需要另外一个传送器，斯库提。', `FemaleText_loc5`='我的傳送器被我弄丟了，現在我需要另外一個傳送器，斯庫提。', `FemaleText_loc7`='Perdí mi transpondedor y necesito otro, Scooty.' WHERE `ID`=4634;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대지는 많은 비밀을 간직하고 있다네. 아제로스의 모든 종족들을 위해 비밀로 남아야만 할 것들을 지키는 것은 우리의 임무지.', `MaleText_loc4`='大地中蕴藏着许多秘密，$c。保护这些秘密是我们永远的职责。', `MaleText_loc5`='大地中蘊藏著許多秘密，$c。保護這些秘密是我們永遠的職責。', `MaleText_loc7`='La tierra oculta muchos secretos, $c; nuestro deber es garantizar que los que tengan que seguir permaneciendo ocultos continúen siendo un misterio por el bien de todos.' WHERE `ID`=4635;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대가 여기서 나의 시간을 뺏는다면 세나리온 의회 전체의 시간을 빼앗는 것과 같아. 무슨 일로 왔는지는 모르겠네만, 그대가 귀중한 시간을 축낼 만큼 어리석지 않다는 희망을 주게.', `MaleText_loc4`='如果你是来浪费我的时间，那你就是在浪费整个塞纳里奥议会的时间。为你自己着想，希望你不至于那么蠢。', `MaleText_loc5`='如果你是來浪費我的時間，那你就是在浪費整個塞納里奧議會的時間。為你自己著想，希望你不至於那麼蠢。', `MaleText_loc7`='Si has venido a hacerme perder el tiempo, estarás perdiendo el tiempo del Círculo Cenarion al completo. Así que por tu bien, esperemos que no seas tan imbécil como para estar haciendo eso.' WHERE `ID`=4636;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드 장교들이 대부분의 병력을 외부로 파견했다니 믿을 수가 없습니다. 지금 고향 땅의 전선이 이처럼 위험한데 말입니다.$B$B서부 몰락지대에서 도적떼가 몰려오고 동쪽, 서쪽에서 놀의 무리가 침입해 오고 있습니다. 그런데도 스톰윈드가 아직 포위되지 않았다는 게 놀라울 정도입니다.', `MaleText_loc4`='在我们的家园面临重重危机的情况下……暴风城的官员们竟然将大批军队派往别处，我真不敢相信！$B$B来自西部荒野的盗贼和来自东西两面的豺狼人蜂拥而至，暴风城没有受到围攻可真是个奇迹。', `MaleText_loc5`='在我們的家園面臨重重危機的情況下...暴風城的官員們竟然將大批軍隊派往別處，我真不敢相信!$B$B來自西部荒野的強盜與東邊和西邊來的豺狼人蜂擁而至，暴風城沒有受到圍攻可真是個奇蹟。', `MaleText_loc7`='No puedo creer en los funcionarios de Ventormenta, enviando a la mayor parte de nuestro ejército al extranjero... ¡cuando el frente interno está sometido a tanta presión!$B$BCon ladrones que vienen desde los Páramos de Poniente y gnolls invadiéndonos desde el este y el oeste, es increíble que Ventormenta no esté sitiado a estas alturas.' WHERE `ID`=4637;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, $C님. 부디 우리 병력에 힘을 보태 주기 위해 오셨기를 바랍니다. 사랑하는 고향 땅 엘윈에 짐승과 도적들이 쏟아져 들어오고 있습니다. 그런데 우리는 길가를 안전하게 지켜 줄 병력조차 모자랄 지경입니다!$B$B그리고 들창코 녀석에 대한 수배령을 보지 못했다면 가서 읽어 보시기 바랍니다. 들창코는 저쪽 숲에 사는 짐승인데 꼭 처리해야 할 녀석입니다.', `MaleText_loc4`='你好，$C。希望你是来支持我们的。野兽和盗贼在艾尔文森林肆意妄为，我们的人手不够，无法维持治安！$B$B如果你没有做过这样的工作，就去看看关于霍格的告示。他是森林中的一只野兽，我们一定要干掉他！', `MaleText_loc5`='你好，$C。希望你是來支援我們的。野獸和盜賊在艾爾文森林肆意妄為，我們的人手不夠，無法維持治安!$B$B如果你沒有做過這樣的工作，就去看看關於霍格的告示。他是森林中的一隻野獸，我們一定要幹掉他!', `MaleText_loc7`='Hola, $c. Espero que hayas venido a reforzar nuestras filas. ¡Las bestias y los ladrones invaden nuestra querida Elwynn y apenas tenemos hombres para mantener los caminos a salvo!$B$BY si no has venido a eso, entonces lee la nota sobre Hogger. Es una bestia que habita en el bosque y tenemos que neutralizarla.' WHERE `ID`=4638;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하시오, $n. 텔사마에 온 걸 환영하오. 여기 머무르는 동안 꼭 이곳 양조장에 들러 보시오!', `MaleText_loc4`='你好，$n。欢迎来到塞尔萨玛，别忘了去本地的酿酒厂看看！', `MaleText_loc5`='你好，$n。歡迎來到塞爾薩瑪，你在這裡的逗留期間別忘了參觀一下本地的釀酒廠!', `MaleText_loc7`='Hola, $n. Te doy la bienvenida a Thelsamar y, mientras estés aquí, no olvides visitar nuestra cervecería local.' WHERE `ID`=4639;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='텔사마에 온 것을 환영합니다! 모단 호수에서 집처럼 편히 지낼 수 있는 유일한 곳이지요.$B$B텔사마는 좋은 곳이지만 임무를 수행하고자 부름을 받은 자에게 항상 좋은 것만 있는 건 아니랍니다! 얼라이언스의 이름으로 목숨을 걸 생각이 있다면 탐험가 연맹 텔사마 지부 건물의 바깥에 있는 전단을 읽어 보시기 바랍니다.', `MaleText_loc4`='欢迎来到塞尔萨玛，这儿是你在洛克莫丹的家！$B$B塞尔萨玛是个好地方，但是对那些相应召唤来到这儿的勇士来说，这里可不是个吃喝玩乐的地方！如果你想以联盟的名义挑战危险的话，就去读读贴在探险者协会塞尔萨玛分部外面的海报吧。', `MaleText_loc5`='歡迎來到塞爾薩瑪，這兒是你在洛克莫丹的家!$B$B塞爾薩瑪是個好地方，但是對那些相應召喚來到這兒的勇士來說，這裡可不是個吃喝玩樂的地方!如果你想以聯盟的名義挑戰危險的話，就去讀讀貼在探險者協會塞爾薩瑪分部外面的海報吧。', `MaleText_loc7`='¡Te doy la bienvenida a Thelsamar, tu hogar lejos de tu hogar en Loch Modan!$B$BThelsamar es un lugar agradable, ¡pero no todo es cerveza y carne en salazón para aquellos que responden a la llamada del deber! Si estás $gdispuesto:dispuesta; a afrontar el peligro en nombre de la Alianza, entonces lee el cartel que está fuera de la rama de Thelsamar de la Liga de Expedicionarios.' WHERE `ID`=4640;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$c|1이여;여;, 마침 잘 오셨어요! 그리 보기 좋은 광경은 아니죠?$B$B지평선 정찰함은 바다 밑바닥으로 가라앉아 버렸고, 살아남은 선원들은 모두 녹초가 돼버렸어요. 거기다 승객들의 짐과 화물의 잔해가 잔뜩 널려 있으니 꼭 축제가 끝난 뒤 너저분한 스톰윈드의 운하를 바라보는 듯한 기분이 들 거예요.$B$B게다가 위험천만한 일이 또 남아 있으니...', `FemaleText_loc4`='嘿，$n！这场景不甚美观，是吧？地平线轻帆号沉在海底，我的手下狼狈不堪，我们的货物和乘客如同碎片一般到处都是，你也许会认为暴风城曾在这儿举办过节日庆典。$B$B麻烦事儿还不止这么点……', `FemaleText_loc5`='嘿，$n!這場景不甚美觀，是吧?地平線輕帆號沉在海底，我的手下狼狽不堪，我們的貨物和乘客如同碎片一般到處都是，你也許會認為暴風城曾在這兒舉辦過節日慶典。$B$B麻煩事兒還不止這麼點...', `FemaleText_loc7`='¡Ah del barco, $n! ¿A que la imagen no es muy buena?$B$BEl Explorador del horizonte en el fondo del mar, mis hombres arrastrándose y nuestra carga y los pasajeros desperdigados por todas partes, que cualquiera diría que esto es uno de los canales de Ventormenta después de un festival.$B$BY aquí no es donde terminan los problemas...' WHERE `ID`=4641;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 도전적인 포효를 내지릅니다!', `MaleText_loc4`='%s发出了一声怒吼！', `MaleText_loc5`='%s發出了一聲怒吼!', `MaleText_loc7`='%s emite un rugido desafiante.' WHERE `ID`=4642;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 다 음모야. 내가 하는 일이 어떤 것인지 제대로 파악할 재량도 없으면서 날 어둠 속에 가둬 놓으려는 자들이 있단 말이오!$B$B아! 거기 흙 밟지 않게 조심하시오.', `MaleText_loc4`='我感觉到处都是阴谋。还有那些对我所做的事情缺乏理解的家伙，他们想要把我关起来！$B$B你最好不要牵扯进来。', `MaleText_loc5`='我感覺到處都是陰謀。還有那些對我所做的事情缺乏理解的傢伙，他們想要把我關起來!$B$B你最好不要牽扯進來。', `MaleText_loc7`='Hay conjuras por doquier. ¡Hay quien es incapaz de comprender lo que hago y que haría todo lo posible por mantenerme atado a las sombras!$B$BNo pises la mugre.' WHERE `ID`=4643;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 곳에서 뭘 하는 건가요?', `MaleText_loc4`='你在这儿做什么？', `MaleText_loc5`='你在這兒做什麼?', `MaleText_loc7`='¿Qué estás haciendo ahí?', `FemaleText_loc1`='이런 곳에서 뭘 하는 건가요?', `FemaleText_loc4`='你在这儿做什么？', `FemaleText_loc5`='你在這兒做什麼?', `FemaleText_loc7`='¿Qué estás haciendo ahí?' WHERE `ID`=4644;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 하는 거냐고? 안 보인단 말이오? 나는 공상가올시다. 우리 모두에게 훨씬 더 나은 미래가 올 것을 꿈꾸고 있지. 그래요. 나는 분명 공상가요.$B$B하지만 세상은 늘 진부함을 강요하지. 대드루이드 스태그헬름께 내가 공상가라는 걸 말씀드렸더니 하시는 말씀이 "세상에는 땅을 파는 자들도 필요할 게 아닌가?"라고 하시더군.$B$B우리의 발목을 매고 있는 진부함의 족쇄가 완전히 풀려날 때까지 나는 세나리온 의회를 도와 이 흙더미나 옮기고 있을 참이오.', `MaleText_loc4`='什么？我在干什么？你眼睛不好使吗？我是一个梦想家，亲爱的$g先生:女士;，我梦想我们的将来会更加美好。很明显，我是个梦想家。$B$B然而，有些人却在想尽办法把我们困在平庸的泥沼里。我告诉过他，我是一个梦想家，而范达尔却回答说，“哦，我们似乎还缺一些挖水沟的。”$B$B我会帮助塞纳里奥议会弄走周围的泥堆，直到平庸的枷锁从我们身上卸下的那一天。', `MaleText_loc5`='什麼?我在幹什麼?你眼睛不好是嗎?我是一個夢想家，親愛的$g先生:女士;，我夢想我們的將來會更加美好。很明顯，我是個夢想家。$B$B然而，有些人卻在想盡辦法把我們困在平庸的泥沼裡。我告訴過他，我是一個夢想家，而大德魯伊鹿盔卻回答說，「哦，我們似乎還缺一些挖水溝的。」$B$B我會幫助塞納里奧議會弄走周圍的泥堆，直到平庸的枷鎖從我們身上卸下的那一天。', `MaleText_loc7`='¿Qué estoy haciendo? ¿No tienes vista? Soy un soñador, $gseñor:señora;, y sueño con un futuro mejor para todos. Está claro que soy vidente.$B$BNo obstante, algunos quieren mantenernos sumidos en un mundo banal. Yo le dije que era un soñador y archidruida Corzocelada contestó: "Bueno, el mundo también necesita cavadores de zanjas."$B$BHasta entonces, cuando nos hayamos librado de los grilletes de la banalidad, ayudaré al Círculo Cenarion a sacar estas pilas de basura de aquí."' WHERE `ID`=4645;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하시오, $r 친구. 나는 프랑클론 포지라이트라고 하오. 검은바위 첨탑과 검은무쇠 부족에 대해 배우고 싶어 온 거요?', `MaleText_loc4`='你好，$r。我是弗兰克罗恩·铸铁。你是来了解黑石塔和黑铁矮人的吗？', `MaleText_loc5`='你好，$r。我是弗蘭克羅恩·鑄鐵。你是來瞭解黑石塔和黑鐵矮人的嗎?', `MaleText_loc7`='Saludos, $r. Soy Franclorn Forjador. ¿Has venido para aprender de la Cumbre y de los Hierro Negro?' WHERE `ID`=4646;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='', `MaleText_loc4`='', `MaleText_loc5`='', `MaleText_loc7`='' WHERE `ID`=4647;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='굉장해요! 유령과 이야기를 해 본 건 난생처음이거든요. 그래요, 거기에 대해 알고 싶습니다!', `MaleText_loc4`='不可思议！我从未跟鬼魂交谈过。我想要了解一下！', `MaleText_loc5`='不可思議!我從未跟鬼魂交談過。我想要瞭解一下!', `MaleText_loc7`='¡Sorprendente! Nunca había hablado con un fantasma. ¡Deseo aprender!', `FemaleText_loc1`='굉장해요! 유령과 이야기를 해 본 건 난생처음이거든요. 그래요, 거기에 대해 알고 싶습니다!', `FemaleText_loc4`='不可思议！我从未跟鬼魂交谈过。我想学！', `FemaleText_loc5`='不可思議!我從未跟鬼魂交談過。我想學!', `FemaleText_loc7`='¡Sorprendente! Nunca había hablado con un fantasma. ¡Deseo aprender!' WHERE `ID`=4648;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게는 선택의 여지가 없었소. 아니, 적어도 그렇게 생각했었지. 타우릿산이 파괴되는 것을 참고 견디며 우리 국왕 폐하와 그의 백성의 곁을 지키려고 했었소.$B$B라그나로스의 지배를 받은 제왕 다그란 타우릿산은 이 산의 중심부를 뜯어내 버리고 검은바위 첨탑을 세웠소. 우리는 과거 또는... 미래의 그 어느 도시나 요새보다도 강한 드워프 도시를 짓기 위해 쉬지 않고 일했소.', `MaleText_loc4`='我没有选择，至少我是这么认为的。我会忍受索瑞森的毁灭并与我的国王和同胞站在一起。$B$B在拉格纳罗斯的统治下，达格兰·索瑞森国王开凿了山脉的中央，并建立了黑石塔。我们不知疲倦地工作着，发誓要建立一座比以前的任何城市或堡垒都要坚固的矮人城堡……甚至将来也不会有能与之媲美的建筑。', `MaleText_loc5`='我沒有選擇，至少我是這麼認為的。我會忍受索瑞森的毀滅並與我的國王和同胞站在一起。$B$B在拉格納羅斯的統治下，達格蘭·索瑞森國王開鑿了山脈的中央，並建立了黑石塔。我們不知疲倦地工作著，發誓要建立一座比以前的任何城市或堡壘都要堅固的矮人城堡...甚至將來也不會有能與之媲美的建築。', `MaleText_loc7`='No tenía otra opción, o al menos eso creía. Soporté la destrucción de Thaurissan y permanecí junto a mi rey y su gente.$B$BBajo el control de Ragnaros, el rey Dagran Thaurissan rasgó el corazón de esta montaña y erigió la Cumbre de Roca Negra. Trabajamos incansablemente para construir una ciudad de enanos que fuese más fuerte que cualquier otra ciudad o fortaleza anterior... o posterior.' WHERE `ID`=4649;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 말씀하십시오.', `MaleText_loc4`='请继续。', `MaleText_loc5`='請繼續。', `MaleText_loc7`='Continúa, por favor.', `FemaleText_loc1`='계속 말씀하십시오.', `FemaleText_loc4`='请继续。', `FemaleText_loc5`='請繼續。', `FemaleText_loc7`='Continúa, por favor.' WHERE `ID`=4650;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 곁에서 라그나로스의 타락이 검은무쇠 제국의 가슴과 정신에 스며드는 것을 지켜보았소. 한때는 명예로웠던 검은무쇠 부족은 이제 광기와... 악으로 치달아 버리고 만 거요.$B$B검은바위 첨탑 건설이 끝나자 나는 내 종족과 함께 더 이상 살고 싶은 생각이 없어졌지. 나는 새로운 검은무쇠 제국에서 영웅으로 떠올랐고 사람들은 내가 계획하고 건설한 도시의 입구인 이곳에 무덤을 지어 내 노고를 칭송한 거요.', `MaleText_loc4`='我眼睁睁地看着拉格纳罗斯的堕落渗透了整个黑铁矮人社会，使这个曾经荣耀的民族变得疯狂……变得邪恶。$B$B当黑石塔建造完毕时，我与同胞们共同生存下去的意愿也消失殆尽了。我作为新的黑铁矮人的英雄而死去。这座坟墓就在我亲手建造的城门处，作为对我的成就的敬意。', `MaleText_loc5`='我眼睜睜地看著拉格納羅斯的墮落滲透了整個黑鐵矮人社會，使這個曾經榮耀的民族變得瘋狂...變得邪惡。$B$B當黑石塔建造完畢時，我與同胞們共同生存下去的意願也消失殆盡了。我作為新的黑鐵矮人的英雄而死去。這座墳墓就在我親手建造的城門處，作為對我的成就的敬意。', `MaleText_loc7`='Me mantuve firme y vi cómo la corrupción de Ragnaros se instaló en los corazones y las mentes de los habitantes de Hierro Negro. Esta raza, que en su día había sido honorable, era presa de la demencia... del mal.$B$BCuando finalizó la construcción de la Cumbre, se impuso mi deseo de vivir entre esta gente. Me convertí en un héroe de la nueva nación de los Hierro Negro. Colocaron esta tumba, en la entrada de la ciudad que yo planifiqué y construí, en honor a mis esfuerzos.' WHERE `ID`=4651;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 흥미롭군요. 더 얘기해 주십시오.', `MaleText_loc4`='请继续。', `MaleText_loc5`='請繼續。', `MaleText_loc7`='Fascinante. Sigue contando, por favor.', `FemaleText_loc1`='아주 흥미롭군요. 더 얘기해 주십시오.', `FemaleText_loc4`='请继续。', `FemaleText_loc5`='請繼續。', `FemaleText_loc7`='Fascinante. Sigue contando, por favor.' WHERE `ID`=4652;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 훌륭한 망치, 무쇠지옥은 파이너스 다크바이어라는 새로운 수석 건축가에게 전해 받았지. 파이너스는 비열한 마음을 품고 있을 뿐 아니라 재능이라곤 거의 없는 녀석이지.$B$B바로 여기서 당신이 날 도와 주는 거요. 녀석을 제지해야 하오. 녀석은 너무 서툴러서 무쇠지옥의 진정한 힘을 이용하지 못하지만, 만약 무쇠지옥의 잠재력을 최대한으로 끌어낼 수 있을 만한 재능을 가진 자가 나타난다면 검은무쇠 부족이 만들어 낸 물건들로 인해 이 세계에 재앙이 닥쳐오게 될 거요.', `MaleText_loc4`='我那柄巨大的战锤——铁胆之锤，被交给了新的建筑大师弗诺斯·达克维尔。这个家伙人品低劣，才疏学浅。$B$B这点就是你需要知道的，$n。我想阻止他。他无法将铁胆之锤的力量发挥到极致，但是如果他的后续者有这个能力的话，他们就会毁掉一切的，而这必将带来灾难性的后果。', `MaleText_loc5`='我那柄巨大的戰錘─鐵膽之錘，被交給了新的建築大師弗諾斯·達克維爾。這個傢伙人品低劣，才疏學淺。$B$B這點就是你需要知道的，$n。我想阻止他。他無法將鐵膽之錘的力量發揮到極致，但是如果他的後續者有這個能力的話，他們就會毀掉一切的，而這必將帶來災難性的後果。', `MaleText_loc7`='Mi gran martillo, Ferrovil, pasó a manos del nuevo arquitecto jefe, Fineous Virunegro: un hombre de voluntad despreciable y escaso talento.$B$BAhí es donde apareces tú, $n. Quiero detenerlo. Es demasiado inepto como para ejercer el poder de Ferrovil, pero si su sucesor tiene la capacidad de usar el martillo en todo su potencial, la destrucción que podría ocasionar con sus creaciones podría ser de una magnitud incalculable.' WHERE `ID`=4653;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가는 길을 가르쳐 주십시오, 프랑클론.', `MaleText_loc4`='弗兰克罗恩，告诉我该怎么做。', `MaleText_loc5`='弗蘭克羅恩，告訴我該怎麼做。', `MaleText_loc7`='Solo muéstrame cómo, Franclorn.', `FemaleText_loc1`='가는 길을 가르쳐 주십시오, 프랑클론.', `FemaleText_loc4`='弗兰克罗恩，告诉我该怎么做。', `FemaleText_loc5`='弗蘭克羅恩，告訴我該怎麼做。', `FemaleText_loc7`='Solo muéstrame cómo, Franclorn.' WHERE `ID`=4654;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장인의 전당의 법의 심판장 너머에서 파이너스 다크바이어를 찾을 수 있을 거요. 그 저주 받을 놈을 처치하고 무쇠지옥을 회수해 오시오.$B$B무쇠지옥을 타우릿산의 제단으로 가져가서 나를 기리는 뜻에서 세워놓은 석상의 손 안에 놓아 주시오. 무쇠지옥이 있어야 할 마땅한 곳이지.$B$B이 일을 마치면 내가 만능 열쇠를 넣어 둔 부분이 열릴 거요. 더 중요한 건, 무쇠지옥이 내 손 안에 영원히 남아 있게 된다는 것이지. 녀석들이 그 망치를 빼내려고 하면 석상과 망치가 모두 산산조각이나 영원히 되찾을 수 없게 될 것이오.', `MaleText_loc4`='你可以在秩序竞技场外侧的工艺之厅里找到弗诺斯·达克维尔。杀死那无耻的杂种，找回铁胆之锤。$B$B把铁胆之锤带到索瑞森神殿去，放在适当的地方——就放在我的雕像的手中。$B$B然后，我存放钥匙的小隔间就会打开。更重要的是，铁胆之锤将会永远都掌握在我手中。如果他们试图拿走战锤，雕塑和战锤就都会粉碎，并永远消失。', `MaleText_loc5`='你可以在秩序競技場外側的工匠大廳裡找到弗諾斯·達克維爾。殺死那無恥的雜種，找回鐵膽之錘。$B$B把鐵膽之錘帶到索瑞森神殿去，放在適當的地方─就放在我的雕像的手中。$B$B然後，我存放鑰匙的小隔間就會打開。更重要的是，鐵膽之錘將會永遠都掌握在我手中。如果他們試圖拿走戰錘，雕塑和戰錘就都會粉碎，並永遠消失。', `MaleText_loc7`='Encontrarás a Fineous Virunegro más allá del Círculo de la Ley, en la Sala de los Oficios. Mata a ese bellaco miserable y recupera Ferrovil.$B$BLleva a Ferrovil al Santuario de Thaurissan y coloca el martillo en el lugar que le corresponde: las manos de la estatua erigida en mi honor.$B$BUna vez hecho esto, se abrirá el compartimento en el que guardé la llave maestra. Y lo que es más importante, Ferrovil permanecerá para siempre en mis manos. En el caso de que hicieran el intento de quitar el martillo, tanto la estatua como él se harán añicos y se perderán para siempre.' WHERE `ID`=4655;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇다네. 자네가 약초채집 기술이 있다면 더 큰 보람을 얻을 수 있을 걸세. 귀한 씨앗을 기르고 재배하는 일은 도끼나 휘두르고 지나가는 그림자에 대고 손짓 발짓하는 일과는 다르거든. 늘푸른 주머니만 있으면 아무리 둔한 자라도 뭔가 길러낼 수 있긴 하지만, 약초학에 소질이 좀 있다면 더욱 풍성한 수확을 거둘 수 있을걸세.', `MaleText_loc4`='没错，但是如果你精通草药学的话，你会发现它非常有用！你要做的是用特别的种子来细心培育药草——而不是一遇到风吹草动就挥斧乱砍。虽然你即将得到的常青袋能让最没有经验的新手轻松进行种植工作，但那些对草药学有天资的冒险者将会得到更丰硕的成果。', `MaleText_loc5`='沒錯，但是如果你精通草藥學的話，你會發現它非常有用!你要做的是用特別的種子來細心培育藥草─而不是一遇到風吹草動就揮斧亂砍。雖然你即將得到的常青袋能讓最沒有經驗的新手輕鬆進行種植工作，但那些對草藥學有天資的冒險者將會得到更豐碩的成果。', `MaleText_loc7`='¡Sí, pero te resultará más gratificante si tienes conocimientos de herboristería! Se te pedirá que cultives semillas especiales, no que blandas un hacha a ciegas o que gesticules salvajemente ante una sombra. Mientras que la bolsa de siempreverde que recibas permitirá incluso al más bruto a cultivar cualquier cosa, aquellos que presenten alguna cualidad alcanzarán resultados más llamativos.' WHERE `ID`=4656;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 중급 약초채집가가 아닙니다. 그래도 도움이 될 수 있을까요?', `MaleText_loc4`='我不是个熟练的草药师，那么我还能帮上忙吗？', `MaleText_loc5`='我不是個熟練的草藥師，那麼我還能幫上忙嗎?', `MaleText_loc7`='No soy un oficial herborista, pero ¿puedo ayudarte en tu tarea?', `FemaleText_loc1`='저는 중급 약초채집가가 아닙니다. 그래도 도움이 될 수 있을까요?', `FemaleText_loc4`='我不是个熟练的草药师，那么我还能帮上忙吗？', `FemaleText_loc5`='我不是個熟練的草藥師，那麼我還能幫上忙嗎?', `FemaleText_loc7`='No soy un oficial herborista, pero ¿puedo ayudarte en tu tarea?' WHERE `ID`=4657;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='단단히 준비하세요! 나가들이 우리가 살아 있다는 걸 알면 곧 다시 공격하려 올 겁니다.', `FemaleText_loc4`='做好准备！若是纳迦知道我们还活着，他们就会马上进攻的。', `FemaleText_loc5`='做好準備!若是納迦知道我們還活著，他們就會馬上進攻的。', `FemaleText_loc7`='¡Mantente alerta! Los nagas no esperarán demasiado para aventajarnos una vez que sepan que estamos vivos.' WHERE `ID`=4658;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 들어 두시오. 난 지금 당신 농담이나 들어줄 기분이 아니오. 대드루이드님의 연구가 계획대로 진행되도록 하는 것이 내 임무요. 내 명령은 나의 사랑하는 세나리온 의회를 위해 땀 한 방울 흘릴 생각조차 없는 녀석들을 모조리 뽑아내 버리는 것이오.', `MaleText_loc4`='考虑清楚，$g小子:姑娘;——我可没心情听你废话。我在这里的工作是确认大德鲁伊的研究工作正在按计划进行，而不是跟那些不愿为塞纳里奥议会效劳的家伙聊天。', `MaleText_loc5`='考慮清楚，$g小子:姑娘;─我可沒心情聽你廢話。我在這裡的工作是確認大德魯伊的研究工作正在按計畫進行，而不是跟那些不願為塞納里奧議會效勞的傢伙聊天。', `MaleText_loc7`='Te lo advierto, $gjovencito:princesa;, no estoy de humor para escuchar ningún comentario que consideres amable o gracioso. Estoy aquí para asegurarme de que la investigación del archidruida avanza según los planes y mis órdenes son las de eliminar a todos los impostores que no lleven encima el equipo necesario para servir a mi amado Círculo Cenarion.' WHERE `ID`=4659;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, 고귀한 $c|1이여;여;. 세나리온 의회의 이 미천한 종이 당신의 종족 $R|1을;를; 위해 축복을 빕니다.', `FemaleText_loc4`='您好，尊贵的$c。我这个塞纳里奥议会的谦卑的仆从愿祝福与您同在。', `FemaleText_loc5`='您好，尊貴的$c。我這個塞納里奧議會的謙卑的僕從願祝福與您同在。', `FemaleText_loc7`='Saludos, noble $c. Esta humilde sierva del Círculo Cenarion desea consagrar sus bendiciones y obsequios a ti y a los tuyos.' WHERE `ID`=4660;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이보게, 아마카르. 고어투스 장군께서 우리를 어디로 보낼 것 같은가? 불타는 평원에는 또 갈 자신이 없는데 말이야.', `MaleText_loc4`='阿玛卡尔，你认为高图斯会把我们派到哪儿去？我可不想再去燃烧平原了。', `MaleText_loc5`='阿瑪卡，你認為督軍高圖斯會把我們派到哪兒去?我可不想再去燃燒平原了。', `MaleText_loc7`='Amakkar, ¿adónde crees que el señor de la guerra Dientegore va a enviarnos? No creo que pueda soportar otra incursión en las Estepas.' WHERE `ID`=4661;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흐음...', `MaleText_loc4`='嗯……', `MaleText_loc5`='嗯...', `MaleText_loc7`='Mmm...' WHERE `ID`=4662;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만 좀 징징대라고, 라잘블레이드. 이제는 대족장님의 정예군 일원답게 행동할 때라고. 가르갈 같은 꼴이 되고 싶지는 않겠지?', `MaleText_loc4`='别那么孩子气，拉扎布雷德。现在你要以酋长的精英部队的身份参与战斗了。你不想像加戈尔那样死掉，对吧？', `MaleText_loc5`='別那麼孩子氣，拉札布雷德。現在你的言行舉止要像一個大酋長精英部隊的隊員。你不想變成跟加戈爾一樣的下場，對吧?', `MaleText_loc7`='Deja de comportarte como un bebé, Razal''filo. Ya es hora de que empieces a actuar como un miembro de las tropas de élite del Jefe. ¿No querrás acabar como Gargal, no?' WHERE `ID`=4663;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 근처의 말소리를 듣지 못하는 것 같습니다.', `MaleText_loc4`='%s似乎忽略了周围的一切。', `MaleText_loc5`='%s似乎忽略了周圍的一切。', `MaleText_loc7`='%s parece ajeno al comentario cercano.' WHERE `ID`=4664;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='프라우드터스크!', `MaleText_loc4`='萨特拉克！', `MaleText_loc5`='長齒!', `MaleText_loc7`='¡Colmillo Orgulloso!' WHERE `ID`=4665;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼, 가르갈. 안 된다고.', `MaleText_loc4`='不，加戈尔。不可能。', `MaleText_loc5`='不，加戈爾。不可能。', `MaleText_loc7`='No, Gargal. He dicho que no.' WHERE `ID`=4666;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇지만...', `MaleText_loc4`='但是……', `MaleText_loc5`='但是...', `MaleText_loc7`='Pero...' WHERE `ID`=4667;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 된다니까! 쉬잇! 입 다물어. 고어투스가 오고 있어!', `MaleText_loc4`='嘘！闭嘴。高图斯来了！', `MaleText_loc5`='噓!閉嘴。高圖斯來了!', `MaleText_loc7`='¡NO! ¡Shhhh! Cierra el pico. ¡Dientegore se acerca!' WHERE `ID`=4668;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 웃습니다.', `MaleText_loc4`='%s笑了。', `MaleText_loc5`='%s大笑。', `MaleText_loc7`='%s ríe.' WHERE `ID`=4669;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서투른 호기로 함부로 까불지 말게. 여차하면 변이 마법을 걸어 버릴 테니까 말일세.', `MaleText_loc4`='小心一点，$c，我有一个为你准备的变形术……', `MaleText_loc5`='小心一點，$c，我有一個為你準備的變形術...', `MaleText_loc7`='Mira por dónde pisas, $c, porque tengo un encantamiento polimorfo con tu nombre inscrito en él...' WHERE `ID`=4670;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전원 출석입니다, 장군님!', `MaleText_loc4`='集合完毕，长官！', `MaleText_loc5`='集合完畢，長官!', `MaleText_loc7`='¡Todos están presentes, SEÑOR!' WHERE `ID`=4672;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정렬하지 못해, 이 쓰레기들아!', `MaleText_loc4`='集合！', `MaleText_loc5`='集合!', `MaleText_loc7`='¡DENTRO, GUSANOS!' WHERE `ID`=4673;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 파이가 세상에서 제일 좋아요.', `MaleText_loc4`='我喜欢馅饼。', `MaleText_loc5`='我喜歡餡餅。', `MaleText_loc7`='Me encanta la tarta.', `FemaleText_loc1`='저는 파이가 세상에서 제일 좋아요.', `FemaleText_loc4`='我喜欢馅饼。', `FemaleText_loc5`='我喜歡餡餅。', `FemaleText_loc7`='Me encanta la tarta.' WHERE `ID`=4674;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 세상에 집에서 갓 구운, 따뜻하고 바삭바삭한 체리 파이만큼 맛있는 게 또 있을까요?!', `MaleText_loc4`='奶奶总是说世界上没有比一块自制的、鲜美的樱桃馅饼更好的东西了。', `MaleText_loc5`='奶奶總是說世界上沒有比一塊自製的、鮮美的櫻桃餡餅更好的東西了。', `MaleText_loc7`='Nana siempre decía que no había nada mejor en el mundo que una porción de tarta de cerezas recién horneada, crujiente y casera.', `FemaleText_loc1`='이 세상에 집에서 갓 구운, 따뜻하고 바삭바삭한 체리 파이만큼 맛있는 게 또 있을까요?!', `FemaleText_loc4`='奶奶总是说世界上没有比一块自制的、鲜美的樱桃馅饼更好的东西了。', `FemaleText_loc5`='奶奶總是說世界上沒有比一塊自製的、鮮美的櫻桃餡餅更好的東西了。', `FemaleText_loc7`='Nana siempre decía que no había nada mejor en el mundo que una porción de tarta de cerezas recién horneada, crujiente y casera.' WHERE `ID`=4675;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이번에 나온 새로운 역병은 뭐지?', `FemaleText_loc4`='那么，这次新的瘟疫是怎么回事？', `FemaleText_loc5`='那麼，這次新的瘟疫是怎麼回事?', `FemaleText_loc7`='Bien, ¿de qué trata esta Nueva Peste?' WHERE `ID`=4676;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파이 맛이 정말 죽인답니다. 한입 드셔 보시겠어요?', `MaleText_loc4`='这馅饼真好吃，你要尝尝吗？', `MaleText_loc5`='這餡餅真好吃，你要嘗嘗嗎?', `MaleText_loc7`='¡Qué buena está esta tarta! ¿Quieres un poco?', `FemaleText_loc1`='파이 맛이 정말 죽인답니다. 한입 드셔 보시겠어요?', `FemaleText_loc4`='这馅饼真好吃，你要尝尝吗？', `FemaleText_loc5`='這餡餅真好吃，你要嘗嘗嗎?', `FemaleText_loc7`='¡Qué buena está esta tarta! ¿Quieres un poco?' WHERE `ID`=4677;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기분이 별로 안 좋으세요? 체리 파이 좀 들어보세요. 금방 기분이 좋아질 거예요.', `MaleText_loc4`='今天不太开心？尝尝这些樱桃馅饼吧。', `MaleText_loc5`='今天不太開心?嘗嘗這些櫻桃餡餅吧。', `MaleText_loc7`='¿Un mal día? Prueba la tarta de cerezas.', `FemaleText_loc1`='기분이 별로 안 좋으세요? 체리 파이 좀 들어보세요. 금방 기분이 좋아질 거예요.', `FemaleText_loc4`='今天不太开心？尝尝这些樱桃馅饼吧。', `FemaleText_loc5`='今天不太開心?嘗嘗這些櫻桃餡餅吧。', `FemaleText_loc7`='¿Un mal día? Prueba la tarta de cerezas.' WHERE `ID`=4678;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오, 정말 얼마나 끔찍한지 말이야, 보면 아마 좋아 죽을 걸, 비비안.', `FemaleText_loc4`='哦，这真可怕，真是太可怕了！薇薇安，你也许刚看到它就会死掉。', `FemaleText_loc5`='哦，這真可怕，真是太可怕了!薇薇安，你也許剛看到它就會死掉。', `FemaleText_loc7`='¡Oh, es terrible, terrible, espantoso! Te vas a MORIR cuando la veas, Vivian.' WHERE `ID`=4679;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='체리 파이는 너무 맛있어서 노움 둘이 먹다가 하나가 죽어도 모를 정도랍니다.', `MaleText_loc4`='这块美味的樱桃馅饼能让小侏儒喜极而泣。', `MaleText_loc5`='這塊櫻桃餡餅真美味，它可以讓長大的地精喜極而泣。', `MaleText_loc7`='Esta tarta de cerezas está tan buena que podría hacer llorar a un gnomo adulto.', `FemaleText_loc1`='체리 파이는 너무 맛있어서 노움 둘이 먹다가 하나가 죽어도 모를 정도랍니다.', `FemaleText_loc4`='这块美味的樱桃馅饼能让小侏儒喜极而泣。', `FemaleText_loc5`='這塊櫻桃餡餅真美味，它可以讓長大的地精喜極而泣。', `FemaleText_loc7`='Esta tarta de cerezas está tan buena que podría hacer llorar a un gnomo adulto.' WHERE `ID`=4680;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='체리 파이 좀 드셔 보세요. 입이 귀 밑까지가 아니라 15km 정도 좍 찢어질 겁니다.', `MaleText_loc4`='尝尝樱桃馅饼吧，它会令你开怀大笑的。', `MaleText_loc5`='嘗嘗櫻桃餡餅吧，它會令你開懷大笑的。', `MaleText_loc7`='Probad un poco de tarta de cerezas, os hará sonreír de oreja a oreja.', `FemaleText_loc1`='체리 파이 좀 드셔 보세요. 입이 귀 밑까지가 아니라 15km 정도 좍 찢어질 겁니다.', `FemaleText_loc4`='尝尝樱桃馅饼吧，它会令你开怀大笑的。', `FemaleText_loc5`='嘗嘗櫻桃餡餅吧，它會令你開懷大笑的。', `FemaleText_loc7`='Probad un poco de tarta de cerezas, os hará sonreír de oreja a oreja.' WHERE `ID`=4681;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신선한 체리 파이 팔아요. 한입 먹으면 너무 맛있어서 눈물이 다 고일 겁니다.', `MaleText_loc4`='新鲜的樱桃馅饼！香味扑鼻，让你的眼睛发直！', `MaleText_loc5`='新鮮的櫻桃餡餅!香味撲鼻，讓你的眼睛發直!', `MaleText_loc7`='Vendo tarta de cerezas recién hecha. Está tan buena, que os hará llorar de emoción.', `FemaleText_loc1`='신선한 체리 파이 팔아요. 한입 먹으면 너무 맛있어서 눈물이 다 고일 겁니다.', `FemaleText_loc4`='新鲜的樱桃馅饼！香味扑鼻，让你的眼睛发直！', `FemaleText_loc5`='新鮮的櫻桃餡餅!香味撲鼻，讓你的眼睛發直!', `FemaleText_loc7`='Vendo tarta de cerezas recién hecha. Está tan buena, que os hará llorar de emoción.' WHERE `ID`=4682;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어서 말해 봐! 긴장돼서 비명이라도 지를 판이니까!', `FemaleText_loc4`='哦，快说吧！这悬念本身就足以让一个女孩尖叫了！', `FemaleText_loc5`='哦，快說吧!這懸念本身就足以讓一個女孩尖叫了!', `FemaleText_loc7`='¡Cuenta, cuenta! ¡El suspense por sí mismo basta para poner a una chica de los nervios!' WHERE `ID`=4683;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='체리 파이는 아제로스에서 제가 가장 좋아하는 음식이랍니다.', `MaleText_loc4`='樱桃馅饼是我在整个艾泽拉斯最喜欢的食物。', `MaleText_loc5`='櫻桃餡餅是我在整個艾澤拉斯最喜歡的食物。', `MaleText_loc7`='La tarta de cereza es mi plato favorito entre todos los que he probado en Azeroth.', `FemaleText_loc1`='체리 파이는 아제로스에서 제가 가장 좋아하는 음식이랍니다.', `FemaleText_loc4`='樱桃馅饼是我在整个艾泽拉斯最喜欢的食物。', `FemaleText_loc5`='櫻桃餡餅是我在整個艾澤拉斯最喜歡的食物。', `FemaleText_loc7`='La tarta de cereza es mi plato favorito entre todos los que he probado en Azeroth.' WHERE `ID`=4684;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내가 듣기론 말이야, 이 새로운 역병은 지난 역병의 풍미는 다 갖추고 있는데 칼로리나 탄수화물은 쏙 빼 버렸다지 뭐야!', `FemaleText_loc4`='哦，据我所知，这次的新瘟疫有着上次瘟疫的全部风味，但是却不包含上次瘟疫的卡路里或是碳水化合物！', `FemaleText_loc5`='哦，據我所知，這次的新瘟疫有著上次瘟疫的全部風味，但是卻不包含上次瘟疫的卡路里或是碳水化合物!', `FemaleText_loc7`='Bueno, según he oído, la Nueva Peste tiene TODO el sabor de la Antigua Peste, ¡pero sin las calorías o los carbohidratos de esta!' WHERE `ID`=4685;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어머. 그거 대단한데!', `FemaleText_loc4`='哦，多么欢欣鼓舞！', `FemaleText_loc5`='哦，多麼歡欣鼓舞!', `FemaleText_loc7`='¡Oh, qué fantástico!' WHERE `ID`=4686;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 손뼉을 치며 좋아합니다.', `FemaleText_loc4`='%s兴奋地鼓掌。', `FemaleText_loc5`='%s興奮地鼓掌。', `FemaleText_loc7`='%s aplaude con entusiasmo.' WHERE `ID`=4687;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋다, 프라우드터스크. 행군을 시작하라. 실시!', `MaleText_loc4`='很好，萨特拉克，你可以出发了。', `MaleText_loc5`='很好，長齒，你可以出發了。', `MaleText_loc7`='Muy bien, Colmillo Orgulloso, puedes empezar a caminar. ¡Continúa!' WHERE `ID`=4688;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 숙녀분들. 새로운 역병에 대해서는 들어 보셨나?', `MaleText_loc4`='那边的女士们，你们好。你们听说最近的新闻了吗？', `MaleText_loc5`='那邊的女士們，你們好。你們聽說新的瘟疫了嗎?', `MaleText_loc7`='Muy bien, buenos días, señoritas. ¿Habéis oído hablar de la Nueva Peste?' WHERE `ID`=4689;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 알겠습니다!', `MaleText_loc4`='遵命，阁下！', `MaleText_loc5`='遵命，閣下!', `MaleText_loc7`='¡SEÑOR, SÍ, SEÑOR!' WHERE `ID`=4690;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장군님의 명령이다, 병사들! 전진하라!', `MaleText_loc4`='你们听到督军的话了，废物！前进！', `MaleText_loc5`='你們聽到督軍的話了，廢物!前進!', `MaleText_loc7`='¡Ya habéis oído al Señor de la Guerra, gusanos! ¡MARCHAD!' WHERE `ID`=4691;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘했다, 제군들! 편히 쉬도록!', `MaleText_loc4`='士兵们，干得好！轻松一下吧！', `MaleText_loc5`='士兵們，幹得好!輕鬆一下吧!', `MaleText_loc7`='¡Bien hecho, Soldados! ¡Descansad!' WHERE `ID`=4692;
