UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='으으... 칼림도어에서 다른 오크들이 다 죽었어도 넌 안 돼, 이 멍청이.', `FemaleText_loc4`='呃……除非你是卡利姆多大陆上的最后一个兽人，隆克。', `FemaleText_loc5`='噁...除非你是卡林多大陸上的最後一個獸人，郎克。', `FemaleText_loc7`='Ehhh... no lo harías si fueras el último orco de Kalimdor, Lunk.' WHERE `ID`=4694;
