UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런, 벌써 시간이 이렇게 됐군! 나는 이제 기지로 돌아가야 할 시간이다... 저 위쪽으로 이동하라.', `MaleText_loc4`='啊，看看时间！我必须返回那边的哨岗去了……', `MaleText_loc5`='啊，看看時間!我必須返回那邊的崗哨去了...', `MaleText_loc7`='¡Qué hora se ha hecho! Tengo que regresar a mi puesto... está justo allí.' WHERE `ID`=4696;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 이만 실례하지, 숙녀님들. 좋은 하루 되길.', `MaleText_loc4`='请原谅，我必须得走了。再见，女士们。', `MaleText_loc5`='請原諒，我必須得走了。再見，女士們。', `MaleText_loc7`='Con su permiso, tengo que irme. Buenos días, señoritas.' WHERE `ID`=4697;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 벽 너머에는 크나큰 위험이 도사리고 있소, $n. 전투에 좀 더 능숙해질 때까지는 가지 마시오.', `MaleText_loc4`='这些墙的另一面存在着巨大的危险，$n。等你的战斗经验更丰富之后再回来吧。', `MaleText_loc5`='這些牆的另一面存在著巨大的危險，$n。等你的戰鬥經驗更豐富之後再回來吧。', `MaleText_loc7`='Grandes peligros acechan detrás de esas paredes, $n. Regresad cuando estéis más curtidos en el combate.' WHERE `ID`=4698;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 녀석들의 공포의 지배는 이제 끝이다! 죽음을 맛보라!', `MaleText_loc4`='你的恐怖统治现在结束了！面对你的末日吧！', `MaleText_loc5`='你的恐怖統治現在結束了!面對你的末日吧!', `MaleText_loc7`='¡Su reino del terror acaba aquí! ¡Enfrentense a su fin, mortales!' WHERE `ID`=4699;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 황야의 땅을 어슬렁거리고 있을 만큼 강한가 보지, $c 친구. 나만큼이나 말이야.$B$B아니면 제정신이 아니라서 이곳에 온 건가? 나처럼 말이지.', `MaleText_loc4`='你在这荒芜之地到处游荡，一定是因为缺钱花了，$c。一定是像我一样缺钱。$B$B要么就是因为你疯了。疯了，像我一样。', `MaleText_loc5`='你在這荒蕪之地到處遊蕩，一定是因為缺錢花了，$c。一定是像我一樣缺錢。$B$B要麼就是因為你瘋了。瘋了，像我一樣。', `MaleText_loc7`='Debes de estar muy mal para vagar por estas Tierras Inhóspitas, $c. Tan mal como yo.$B$BO quizás estás aquí porque estás $gloco:loca;. Tan $gloco:loca; como yo.' WHERE `ID`=4700;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 목숨을 건지기 위해 도망칩니다!', `MaleText_loc4`='%s没命地逃开了！', `MaleText_loc5`='%s沒命地逃開了!', `MaleText_loc7`='%s corre para salvar su vida.' WHERE `ID`=4701;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 벨티스 선장에게 손을 뻗치면서 쓰러집니다.', `MaleText_loc4`='%s在贝迪斯掉下去之前伸手拉住了他。', `MaleText_loc5`='%s在貝迪斯掉下去之前伸手拉住了他。', `MaleText_loc7`='%s extiende la mano hacia el Capitán Beltis mientras cae.', `FemaleText_loc1`='%s|1이;가; 벨티스 선장에게 손을 뻗치면서 쓰러집니다.', `FemaleText_loc4`='%s在贝迪斯掉下去之前伸手拉住了他。', `FemaleText_loc5`='%s在貝迪斯掉下去之前伸手拉住了他。', `FemaleText_loc7`='%s extiende la mano hacia el Capitán Beltis mientras cae.' WHERE `ID`=4702;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악의 세력이 이 세계에 발을 들여놓게 해서는 안 된다! 싸워라, 나의 아이들아!', `MaleText_loc4`='绝不能让邪恶力量侵袭这个世界！来吧，孩子们！', `MaleText_loc5`='絕不能讓邪惡力量侵襲這個世界!來吧，孩子們!', `MaleText_loc7`='¡No podemos permitir que el mal entre en este mundo! ¡Venid, hijos míos!' WHERE `ID`=4703;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기서 떨어져!', `MaleText_loc4`='离开那儿！', `MaleText_loc5`='離開那兒!', `MaleText_loc7`='¡Apartaos de ahí!', `FemaleText_loc1`='거기서 떨어져!', `FemaleText_loc4`='离开那儿！', `FemaleText_loc5`='離開那兒!', `FemaleText_loc7`='¡Apartaos de ahí!' WHERE `ID`=4704;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쩝, 내 앞을 가릴 나뭇가지만 있어도 경비병들이 절대 날 보지 못할 텐데...', `MaleText_loc4`='嗯，如果我能用树枝做掩护的话，那些守卫是看不见我的。', `MaleText_loc5`='嗯，如果我能用樹枝做掩護的話，那些守衛是看不見我的。', `MaleText_loc7`='Oh, si tan solo tuviera una rama para ponérmela delante. Así los guardias nunca me verían.' WHERE `ID`=4705;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내부에서 첩보로봇이 아주 세심한 주의를 요하는 작업을 하고 있는 중이니까 조금만 참고 기다리라고. 곧 끝날 테니까 말이야.$B$B아, 그리고 한가지 부탁이 있는데, 라스코발 녀석에게 들키지 않도록 하시오... 우린 곧 그를 습격하려고 하니까 말이오.', `MaleText_loc4`='你必须耐心一些，$n。我的间谍机器人正在进行非常精密的操作，马上就帮你搞定。$B$B哦，帮我个忙，尽量不要让莱斯科瓦看到你……我们要伏击他。', `MaleText_loc5`='你必須耐心一些，$n。我的間諜機器人正在進行非常精密的操作，馬上就幫你搞定。$B$B哦，幫我個忙，盡量不要讓萊斯科瓦看到你...我們要伏擊他。', `MaleText_loc7`='Tienes que ser paciente conmigo, $n. Mi robot espía está ahí dentro, trabajando en un asunto muy delicado. Volveré contigo en un segundo.$B$BAh, y hazme un favor, intenta que Lescovar no te vea... estamos a punto de tenderle una emboscada.' WHERE `ID`=4706;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고르테쉬 죽었다고?!?!', `MaleText_loc4`='戈泰什死了？？！', `MaleText_loc5`='戈泰什死了??!', `MaleText_loc7`='¡¿¡¿GOR''TESH MUERTO?!?!' WHERE `ID`=4707;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도망가! 언덕으로 도망가!', `MaleText_loc4`='快跑！快离开这座山！', `MaleText_loc5`='快跑!快離開這座山!', `MaleText_loc7`='¡CORRED! ¡CORRED HACIA COLINAS!' WHERE `ID`=4708;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 고르테쉬 님 죽인 거야!?!? 누가 그런 거야?!', `MaleText_loc4`='谁杀了戈泰什！？！？谁干的？！', `MaleText_loc5`='誰殺了戈泰什!?!?誰幹的?!', `MaleText_loc7`='¡¿¡¿QUIÉN MATAR A GOR''TESH?!?! ¡¿QUIÉN HACER ESTO?!' WHERE `ID`=4709;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요즘은 무척 힘든 시기랍니다, 안 그렇습니까? 어디를 가도 도움을 필요로 하는 이가 꼭 있다니 말입니다. 저와 제 집사람도 예외는 아니죠.', `MaleText_loc4`='艰难时期，嗯，$n？谁都需要帮助，我和我妻子也不例外。', `MaleText_loc5`='艱難時期，嗯，$n?誰都需要幫助，我和我妻子也不例外。', `MaleText_loc7`='Son tiempos difíciles, ¿verdad, $n? Mires a donde mires, siempre hay alguien que necesita ayuda, y mi mujer y yo no somos ninguna excepción.' WHERE `ID`=4710;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 죽인다! $n|1이;가; 지금 너 죽인다! 도망가! 도망가!', `MaleText_loc4`='$n杀的！$G他:她;现在就要杀了你！快跑！快跑！', `MaleText_loc5`='$n殺的!$G他:她;現在就要殺了你!快跑!快跑!', `MaleText_loc7`='¡$n MATA! ¡$gÉl:Ella; te matará ahora! ¡CORRE! ¡CORRE!' WHERE `ID`=4711;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언덕으로 도망쳐! 잠깐, 여기가 언덕이잖아?!', `MaleText_loc4`='跑到小山那边去！等等！我们已经在山里了！', `MaleText_loc5`='跑到小山那邊去!等等!我們已經在山裡了!', `MaleText_loc7`='¡Corred hacia las colinas! ¡Esperad! ¡Ya estamos en colinas!' WHERE `ID`=4712;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물건을 보고 싶습니다.', `MaleText_loc4`='我想看看你出售的货物。', `MaleText_loc5`='我想看看你出售的貨物。', `MaleText_loc7`='Me gustaría ver lo que tienes a la venta.', `FemaleText_loc1`='물건을 보고 싶습니다.', `FemaleText_loc4`='我想看看你出售的货物。', `FemaleText_loc5`='我想看看你出售的貨物。', `FemaleText_loc7`='Me gustaría ver lo que tienes a la venta.' WHERE `ID`=4713;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 아리송하다는 듯이 당신을 올려다봅니다. 자세히 살펴봐야 하지 않을까요?', `MaleText_loc4`='%s疑惑地看着你。或许你该仔细看看？', `MaleText_loc5`='%s疑惑地看著你。或許你該仔細看看?', `MaleText_loc7`='%s te mira socarronamente. ¿Tal vez deberías examinarlo?' WHERE `ID`=4714;
