UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신은 정말 강하군요, $n. 할 일을 더 찾고 있다면 날 찾아오도록 하세요.', `FemaleText_loc4`='你确实很强大，$n。如果你想要找活干，就来找我吧。', `FemaleText_loc5`='你確實很強大，$n。如果你想要找活幹，就來找我吧。', `FemaleText_loc7`='Ciertamente, eres $gpoderoso:poderosa;, $n. Ven a verme si es más trabajo lo que buscas.' WHERE `ID`=4717;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 눈은 틀림없소. 당신에게서 우리의 대의를 더 깊이 이루어내기에 충분할 만한 크나큰 힘을 볼 수 있소. 탑 꼭대기로 날 찾아오시오.', `MaleText_loc4`='我的眼睛从不欺骗我，$r。你身上蕴涵着巨大的能量——足够的能量，或许能对我们有所帮助。来塔顶找我吧。', `MaleText_loc5`='我的眼睛從不欺騙我，$r。你身上蘊涵著巨大的能量─足夠的能量，或許能對我們有所幫助。來塔頂找我吧。', `MaleText_loc7`='Mis ojos nunca me engañan, $r. Veo mucho poder en ti, suficiente tal vez, como para promover nuestra causa. Búscame en lo alto de la torre.' WHERE `ID`=4718;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 두 눈으로 마크루라를 봤단 말이오! 산악거인 손가락보다 더 큰, 본 중에 가장 큰 마크루라가 쌍둥이 바위산 중에서 저기 한쪽 위로 길을 내면서 올라갔소이다. 당신이 저길 어떻게 올라가려는지 모르겠소만, 그 마크루라가 분명히 보물을 한 짐 가지고 있을 거요.', `MaleText_loc4`='我亲眼看见的！你这辈子所见过最巨大的Makura，比高山巨人的拳头还要大。那时它正在攀爬双塔山。我不知道你想怎么上去，但如果你成功了，一定不会空手而归。', `MaleText_loc5`='我親眼看到的!絕對是有始以來最大的龍蝦人，比山丘巨人的拳頭還大!它用自己的鉗子爬上了雙塔山的其中一座。我不知道你要怎樣才能上去那，但那野獸對你來說一定價值連城。', `MaleText_loc7`='¡Lo vi con mis propios ojos! El makura más grande que hayas visto jamás, más grande que el puño de un gigante montés, aferrado con sus garras al costado de uno de los colosales gemelos. No sé cómo planeas subir allí, pero si lo haces, seguro que conseguirás un buen tesoro de esa bestia.' WHERE `ID`=4719;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐든 좀 사 주지 않겠소?', `MaleText_loc4`='我想买点东西，行吗？', `MaleText_loc5`='你買東西嗎?', `MaleText_loc7`='¿Cómprame algo, vale?', `FemaleText_loc1`='뭐든 좀 사 주지 않겠소?', `FemaleText_loc4`='我想买点东西，行吗？', `FemaleText_loc5`='你買東西嗎?', `FemaleText_loc7`='¿Cómprame algo, vale?' WHERE `ID`=4720;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앞날의 비약 만드는 법을 가르쳐 주시겠습니까?', `MaleText_loc4`='你能告诉我怎样才能得到一份视灵药剂吗？', `MaleText_loc5`='你能告訴我怎樣才能得到一份視靈藥劑嗎?', `MaleText_loc7`='¿Puedes decirme cómo conseguir un Elixir de Videre?', `FemaleText_loc1`='앞날의 비약 만드는 법을 가르쳐 주시겠습니까?', `FemaleText_loc4`='你能告诉我怎样才能得到一份视灵药剂吗？', `FemaleText_loc5`='你能告訴我怎樣才能得到一份視靈藥劑嗎?', `FemaleText_loc7`='¿Puedes decirme cómo conseguir un Elixir de Videre?' WHERE `ID`=4721;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론이지. 당신은 신뢰할 수 있는 사람 같으니... 신뢰말이야! 그거야 금방 알아볼 수 있지.$B$B그건 그렇고, 하던 얘기를 계속합시다. 앞날의 비약을 만들려면 에보뿌리 식물 하나가 있어야 하오. 나머지 재료는 정말 흔한 것들이지만, 그게, 에보뿌리는 구하기가 좀 까다롭소.', `MaleText_loc4`='当然，$n。看起来你是个值得信任的$r！我在一里开外就发现了……$B$B总之，说正经事。我需要一株灵根草才能制作视灵药剂。药剂所需的其它成分都是小菜一碟，但是灵根草就不是那么容易得到了。', `MaleText_loc5`='當然，$n。看起來你是個值得信任的$r!我在一裡開外就發現了...$b$b總之，說正經事。我需要一株靈根草才能製作視靈藥劑。藥劑所需的其他成分都是小菜一碟，但是靈根草就不是那麼容易得到了。', `MaleText_loc7`='Claro, $n. Pareces de fiar... ¡$gdigno:digna; de confianza! Puedo detectarlo a un kilómetro de distancia...$B$BDe todas maneras, vuelvo a lo que iba. Para fabricar el Elixir de Videre es necesaria una planta de raíz del mal. Los demás ingredientes son prácticamente irrelevantes, pero la raíz del mal, esa sí que cuesta conseguirla.' WHERE `ID`=4722;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='열쇠... 열쇠를 구해야... 게르스탄이 갖고 있...소.', `MaleText_loc4`='钥匙……拿到钥匙……格斯塔恩有……钥匙。', `MaleText_loc5`='鑰匙...拿到鑰匙...格斯塔恩有...鑰匙。', `MaleText_loc7`='Llave... encontrar llave... Gerstahn tener... llave.' WHERE `ID`=4723;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쓸모 있는 일을 좀 해 보시오. 날 여기서 꺼내 달란 말이오! 대심문관이 열쇠를 가지고 있소.', `MaleText_loc4`='你就不能有点出息么，$c？带我离开这儿！钥匙在审讯官那儿。', `MaleText_loc5`='你就不能有點出息嗎，$r?帶我離開這兒!鑰匙在審問者那兒。', `MaleText_loc7`='Intenta ser útil, $r. ¡SÁCAME DE AQUÍ! El gran interrogador tiene la llave.' WHERE `ID`=4724;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐! 이봐, 당신! $r 친구! 날 여기서 좀 꺼내 주시오!', `MaleText_loc4`='嘿！嘿！叫你呢！$c！帮我离开这儿！', `MaleText_loc5`='嘿!嘿!叫你呢!$R!幫我離開這兒!', `MaleText_loc7`='¡EH! ¡EH, TÚ! ¡$R! ¡Sácame de aquí!' WHERE `ID`=4725;
