UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 어디 한번 볼까...', `MaleText_loc4`='好吧，让我好好看看这东西……', `MaleText_loc5`='好吧，讓我好好看看這東西...', `MaleText_loc7`='Bueno, echemos un vistazo a esto...' WHERE `ID`=4727;
