UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽이려면 어서 죽여, 이 망나니 같은 $r|1아;야;.$B$B<고개를 숙이며 짧은 목을 드러내는 카란>', `MaleText_loc4`='快动手吧，肮脏的$r。$B$B<卡兰低下头，露出他粗壮的脖子。>', `MaleText_loc5`='快動手吧，骯髒的$r。$B$B<卡蘭低下頭，露出他粗壯的脖子。>', `MaleText_loc7`='Acaba ya con eso, $gasqueroso:asquerosa; $r.$B$B<Kharan inclina la cabeza, mostrando su cuello regordete.>' WHERE `ID`=4731;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신을 해치려고 온 게 아닙니다, 카란. 고르샤크가 보냈습니다. 당신이 공주에 대해 말해 줄 거라더군요.', `MaleText_loc4`='我不是来伤害你的，卡兰。哥沙克派我来找你。他说你会告诉我关于公主的事情。', `MaleText_loc5`='我不是來傷害你的，卡蘭。哥沙克派我來找你。他說你會告訴我關於公主的事情。', `MaleText_loc7`='No he venido a hacerte daño, Kharan. Gor''shak me ha enviado. Me dijo que me hablarías sobre la princesa.', `FemaleText_loc1`='당신을 해치려고 온 게 아닙니다, 카란. 고르샤크가 보냈습니다. 당신이 공주에 대해 말해 줄 거라더군요.', `FemaleText_loc4`='我不是来伤害你的，卡兰。哥沙克派我来找你。他说你会告诉我关于公主的事情。', `FemaleText_loc5`='我不是來傷害你的，卡蘭。哥沙克派我來找你。他說你會告訴我關於公主的事情。', `FemaleText_loc7`='No he venido a hacerte daño, Kharan. Gor''shak me ha enviado. Me dijo que me hablarías sobre la princesa.' WHERE `ID`=4732;
