UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇지 않습니다, 카란!', `MaleText_loc4`='我们还没有失去一切，卡兰！', `MaleText_loc5`='我們還沒有失去一切，卡蘭!', `MaleText_loc7`='¡No todo se ha perdido, Kharan!', `FemaleText_loc1`='그렇지 않습니다, 카란!', `FemaleText_loc4`='我们还没有失去一切，卡兰！', `FemaleText_loc5`='我們還沒有失去一切，卡蘭!', `FemaleText_loc7`='¡No todo se ha perdido, Kharan!' WHERE `ID`=4734;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 바보로 아는 거요? 내가 공주를 죽이는 거나 마찬가지라고! 내가 왜 당신을 믿어야 하지?', `MaleText_loc4`='你看我像个傻子吗，$r？我可以签署她的死亡证明书！我为什么要信任你呢？', `MaleText_loc5`='你看我像個傻子嗎，$r?我可以簽署她的死亡證明書!我為什麼要信任你呢?', `MaleText_loc7`='¿Te parezco idiota, $r? ¡Podría firmar su sentencia de muerte! ¿Por qué debería confiar en ti?' WHERE `ID`=4735;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 아직 살아 있고 내가 당신을 죽이려고 하지 않기 때문이죠.', `MaleText_loc4`='因为你还活着，我的手也没有卡在你结实的短脖子上。', `MaleText_loc5`='因為你還活著，我的手也沒有卡在你結實的短脖子上。', `MaleText_loc7`='Porque tú sigues vivo y mis manos no aprietan tu pequeño y grueso cuello.', `FemaleText_loc1`='당신은 아직 살아 있고 내가 당신을 죽이려고 하지 않기 때문이죠.', `FemaleText_loc4`='因为你还活着，我的手也没有卡在你结实的短脖子上。', `FemaleText_loc5`='因為你還活著，我的手也沒有卡在你結實的短脖子上。', `FemaleText_loc7`='Porque tú sigues vivo y mis manos no aprietan tu pequeño y grueso cuello.' WHERE `ID`=4736;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<한숨을 쉬는 카란>$B$B그... 그건 맞는 말인 것 같군.$B$B고르샤크가 말하기를 당신네 대족장이 어떤 큰 계획을 세우고 있다고 하더군. 얼라이언스와 호드 간의 관계를 바꿔 놓을 그런 계획 말이오. 혹시 당신은 알고 있소?', `MaleText_loc4`='<卡兰叹了口气。>$B$B我想……我想你是对的。$B$B哥沙克告诉我你的酋长有个大计划，一个可能会改变联盟和部落关系的计划。关于这点你知道些什么？', `MaleText_loc5`='<卡蘭歎了口氣。>$B$B我想...我想你是對的。$B$B哥沙克告訴我你的大酋長有個龐大計畫，一個可能會改變聯盟和部落關係的計畫。關於這點你知道些什麼?', `MaleText_loc7`='<Kharan suspira.>$B$BSupongo... supongo que estás en lo cierto.$B$BGor''shak me dijo que tu Jefe de Guerra tenía grandes planes. Planes que pueden cambiar la forma en que la Alianza y la Horda interactúan. ¿Qué sabes acerca de esto?' WHERE `ID`=4737;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전혀 모릅니다. 내가 받은 명령은 당신과 얘기를 나누고 스랄 님을 만나러 가라는 것이었습니다. 아는 거라곤 스랄 님이 당신네 공주를 구하고 싶어한다는 것뿐입니다.', `MaleText_loc4`='没什么。我的任务是跟你谈谈，然后回去找萨尔。萨尔对营救公主的事情很有兴趣。', `MaleText_loc5`='沒什麼。我的任務是跟你談談，然後回去找索爾。索爾對營救公主的事情很有興趣。', `MaleText_loc7`='Nada. Mis órdenes eran hablar contigo y luego hablar con Thrall. Todo lo que sé es que Thrall está interesado en salvar a tu princesa.', `FemaleText_loc1`='전혀 모릅니다. 내가 받은 명령은 당신과 얘기를 나누고 스랄 님을 만나러 가라는 것이었습니다. 아는 거라곤 스랄 님이 당신네 공주를 구하고 싶어한다는 것뿐입니다.', `FemaleText_loc4`='没什么。我的任务是跟你谈谈，然后回去找萨尔。萨尔对营救公主的事情很有兴趣。', `FemaleText_loc5`='沒什麼。我的任務是跟你談談，然後回去找索爾。索爾對營救公主的事情很有興趣。', `FemaleText_loc7`='Nada. Mis órdenes eran hablar contigo y luego hablar con Thrall. Todo lo que sé es que Thrall está interesado en salvar a tu princesa.' WHERE `ID`=4738;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러면 잘 들어 두시오.$B$B몇 달 전에 호숫골의 집정관이 아이언포지로 사절을 보내 붉은마루 산맥과 불타는 평원에서 검은바위 부족이 침입하고 있으니 도와 달라고 국왕께 요청을 했소이다.$B$B모이라 공주는 내 반대에도 불구하고 그들을 도와주는 일을 자청했소. 나는 모단 호수에서 호숫골로 가는 위험한 여정에 공주를 보호하도록 정예 경비병 스무 명을 배치 받았소이다.', `MaleText_loc4`='那么听好了，$c。$B$B几个月前，湖畔镇的镇长派遣特使来到铁炉堡，恳求国王一同抵抗入侵赤脊山的黑石兽人。$B$B铁炉堡公主茉艾拉自愿前去援助，于是国王就指派了20个精英守卫，确保公主由洛克湖前往湖畔镇的途中一路平安，我也在卫队中。', `MaleText_loc5`='那麼聽好了，$r。$B$B幾個月前，湖畔鎮的鎮長派遣特使來到鐵爐堡，懇求國王一同抵抗入侵赤脊山的黑石獸人。$B$B鐵爐堡公主茉艾拉自願前去援助，於是國王就指派了20個精英守衛，確保公主由洛克湖前往湖畔鎮的途中一路平安，我也在衛隊中。', `MaleText_loc7`='Pues escucha atentamente, $r.$B$BUnos meses atrás, el magistrado de Villa del Lago envió mensajeros a Forjaz, para pedir ayuda al rey con las incursiones de los Roca Negra que venían de Crestagrana y de las Estepas Ardientes.$B$BLa princesa Moira se ofreció a ayudar, desoyendo mis súplicas. Me asignaron veinte guardias de élite para proteger a la princesa durante el peligroso viaje desde Loch hasta Villa del Lago.' WHERE `ID`=4739;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런데도 산 밑바닥의 감옥에 들어앉아 있게 되었단 말입니까?', `MaleText_loc4`='这就解释了你被关在黑石山下的囚房里的原因，是吧，矮人？', `MaleText_loc5`='這就解釋了你被關在黑石山下的囚房裡的原因，是吧，矮人?', `MaleText_loc7`='Lo que explicaría por qué estás recluido en la celda de una prisión en el interior de una montaña, ¿verdad, enano?', `FemaleText_loc1`='그런데도 산 밑바닥의 감옥에 들어앉아 있게 되었단 말입니까?', `FemaleText_loc4`='这就解释了你被关在黑石山下的囚房里的原因，是吧，矮人？', `FemaleText_loc5`='這就解釋了你被關在黑石山下的囚房裡的原因，是吧，矮人?', `FemaleText_loc7`='Lo que explicaría por qué estás recluido en la celda de una prisión en el interior de una montaña, ¿verdad, enano?' WHERE `ID`=4740;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<목을 가다듬는 카란>$B$B우린 이글거리는 협곡의 지하도를 지나 파괴된 황무지로 들어섰었소. 지금 생각해 보면 소름이 돋을 정도로 조용했소이다. 지나가는 길에 부닥친 것이라고는 그 지역의 야생동물들뿐이었고 내 부하들이 손쉽게 해치웠지.$B$B우리는 그나마 쉽게 검은바위 산에 이르러 아무런 일도 없이 돌다지 건물들을 지나갔소.', `MaleText_loc4`='<卡兰清了清喉咙。>$B$B我们艰难地穿过灼热峡谷的隧道，进入了这片饱经蹂躏的荒地。现在回想起来，这事情十分蹊跷。我们所遇到的危险只不过是在这个地区生存的一些野生动物，我们很容易就赶走了它们。$B$B我们轻松地抵达了黑石山，并毫不费力地穿过了这座由巨石砌成的堡垒。', `MaleText_loc5`='<卡蘭清了清喉嚨。>$B$B我們艱難地穿過灼熱峽谷的隧道，進入了這片飽經蹂躪的荒地。現在回想起來，這事情十分蹊蹺。我們所遇到的危險只不過是在這個地區生存的一些野生動物，我們很容易就趕走了它們。$B$B我們輕鬆地抵達了黑石山，並毫不費力地穿過了這座由巨石砌成的堡壘。', `MaleText_loc7`='<Kharan carraspea.>$B$BAtravesamos el túnel de la Garganta de Fuego y los páramos que la rodean. Visto ahora, todo estaba sospechosamente tranquilo. Los únicos peligros con que nos topamos fueron la flora y la fauna de la región, criaturas que mis hombres despacharon sin esfuerzo.$B$BLlegamos a la montaña Roca Negra con relativa facilidad y nos movimos por ella sin demasiada dificultad.' WHERE `ID`=4741;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래서 무슨 일이 있었던 겁니까?', `MaleText_loc4`='接下来发生了什么事？', `MaleText_loc5`='接下來發生了什麼事?', `MaleText_loc7`='¿Y qué ocurrió?', `FemaleText_loc1`='그래서 무슨 일이 있었던 겁니까?', `FemaleText_loc4`='接下来发生了什么事？', `FemaleText_loc5`='接下來發生了什麼事?', `FemaleText_loc7`='¿Y qué ocurrió?' WHERE `ID`=4742;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불타는 평원을 지나갈 때 습격을 받았소. 족히 백 명은 되어 보이는 검은무쇠 드워프들이 달려든 거요! 불타는 평원의 바위, 벽 가릴 것 없이 온갖 틈과 구석에서 기어 나왔소. 우리에게 몰려들어 경비병들은 물론 이번 임무에 우리를 도와 주기로 했던 몇몇 용감한 영웅들도 제압해 버렸소.$B$B단 한 가지 확실했던 건 아주 철저히 준비된 습격이었단 사실이오. 마치 우리가 움직이기도 전에 녀석들이 우리의 행동을 다 꿰뚫어보고 있기라도 한 것처럼...', `MaleText_loc4`='在我们穿越燃烧平原时遭到了敌人的伏击，有上百个黑铁矮人！他们从城墙内、平原上的岩石后面、还有岩石的裂缝中突然出现。他们包围了我们，很快就解决了那些答应帮助我们完成任务的英雄和守卫。$B$B很明显：这是一次早有预谋的伏击。他们似乎知道我们的每一步计划……', `MaleText_loc5`='在我們穿越燃燒平原時遭到了敵人的伏擊，有上百個黑鐵矮人!他們從城牆內、平原上的岩石後面、還有岩石的裂縫中突然出現。他們包圍了我們，很快就解決了那些答應幫助我們完成任務的英雄和守衛。$B$B很明顯:這是一次早有預謀的伏擊。他們似乎知道我們的每一步計畫...', `MaleText_loc7`='Cuando atravesábamos las Estepas Ardientes, nos tendieron una emboscada. Debieron de ser cientos... ¡Enanos Hierro Negro! Salían de las paredes, de las rocas de las Estepas, de cualquier grieta, rincón o ranura. Cayeron sobre nosotros como un enjambre, aplastando a los guardias y a los pocos héroes que habían aceptado ayudarnos en esta misión.$B$BUna cosa estaba clara: Había sido una emboscada muy bien organizada. Parecía como si supieran de antemano qué movimiento íbamos a hacer en cada momento...' WHERE `ID`=4743;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 정보 유출과 같은 내부 소행일지도 모른다는 겁니까?', `MaleText_loc4`='你怀疑某个内部人员与此有关？向敌方泄密？', `MaleText_loc5`='你懷疑某個內部人員與此有關?向敵方洩密?', `MaleText_loc7`='¿Así que sospechas que alguien de dentro estaba implicado? ¿Crees que les dieron el chivatazo?', `FemaleText_loc1`='그럼 정보 유출과 같은 내부 소행일지도 모른다는 겁니까?', `FemaleText_loc4`='你怀疑某个内部人员与此有关？向敌方泄密？', `FemaleText_loc5`='你懷疑某個內部人員與此有關?向敵方洩密?', `FemaleText_loc7`='¿Así que sospechas que alguien de dentro estaba implicado? ¿Crees que les dieron el chivatazo?' WHERE `ID`=4744;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니면 어떻게 그런 일이 있을 수 있었겠소? 누군가가 검은무쇠 녀석들에게 정보를 흘린 게 분명하오.$B$B<주먹을 흔들어 보이는 카란>$B$B그러니 날 도와주시오. 여기서 빠져나가면 내 나머지 일생을 그 배신자를 찾으며 보낼 참이오.', `MaleText_loc4`='还会有别的原因导致这种结果吗？一定是有人向黑铁矮人告密了。$B$B<卡兰在你面前挥舞着拳头。>$B$B帮帮我吧，如果我能离开这里，我发誓一定会把那个叛徒抓出来的。', `MaleText_loc5`='還會有別的原因導致這種結果嗎?一定是有人向黑鐵矮人告密了。$B$B<卡蘭在你面前揮舞著拳頭。>$B$B幫幫我吧，如果我能離開這裡，我發誓一定會把那個叛徒抓出來的。', `MaleText_loc7`='¿De qué otra manera pudo haber ocurrido? Alguien tuvo que dar el soplo a los Hierro Negro.$B$B<Kharan agita su puño frente a ti.>$B$BPor eso te pido que me ayudes, ya que si consigo salir de aquí, pasaré el resto de mis días buscando al traidor.' WHERE `ID`=4745;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 얘기해 주십시오.', `MaleText_loc4`='请继续讲你的故事。', `MaleText_loc5`='請繼續講你的故事。', `MaleText_loc7`='Continúa con tu historia, por favor.', `FemaleText_loc1`='계속 얘기해 주십시오.', `FemaleText_loc4`='请继续讲你的故事。', `FemaleText_loc5`='請繼續講你的故事。', `FemaleText_loc7`='Continúa con tu historia, por favor.' WHERE `ID`=4746;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디까지 얘기를 했더라? 아, 그렇지. 그래서 체포당하게 되었소. 내 정예 경비병 부하들은 그 자리에서 처형당했고, 그들은 날 살려 두고 공주는 숫양에 태워 데려가 버렸소. 나는 잿가루 채석장의 유치소로 끌고 가더니 이 감옥으로 이감시킵디다.$B$B내 처량한 목숨으로 몸값이나 받으려고 날 살려 둔 게 아닌가 하고 생각할 수밖에 없소. 아니면 자신들의 잔인함에 내가 여기 앉아서 죽을 때까지 지난 일이나 되새기도록 만들려고 한 것이든지. 후회란 세상에서 가장 잔인한 간수라오, $r.', `MaleText_loc4`='我说到哪里了？哦，对，我们被抓住了。我的伙伴被当场处死。他们没有杀我，但用山羊把公主带走了。我被带到了熔渣之池的拘留所，然后又被转送到了这座监狱里。$B$B也许他们是想用我这条可怜的小命勒索一笔赎金。或者他们只是想让我永远回忆那些缭绕在我脑海里的残酷事件。悔恨是最残忍的狱卒，$c。', `MaleText_loc5`='我說到哪裡了?哦，對，我們被抓住了。我的夥伴被當場處死。他們沒有殺我，但用山羊把公主帶走了。我被帶到了熔渣之池的拘留所，然後又被轉送到了這座監獄裡。$B$B也許他們是想用我這條可憐的小命勒索一筆贖金。或者他們只是想讓我永遠回憶那些繚繞在我腦海裡的殘酷事件。悔恨是最殘忍的獄卒，$r。', `MaleText_loc7`='¿En dónde me quedé? Ah, sí, te quedaste en que te habían capturado. Mis guardias de élite fueron ejecutados ahí mismo. A mí me perdonaron y a la princesa se la llevaron a golpes. Me llevaron a los corredores de detenidos de la Fosa de la Escoria y luego me trajeron a esta prisión.$B$BSolo puedo pensar que aún sigo vivo porque desean obtener un rescate por mi miserable vida. O tal vez por pura crueldad, para que recordara una y otra vez los hechos que me atormentaban. El arrepentimiento es la peor de las cárceles, $r.' WHERE `ID`=4747;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 그렇군요.', `MaleText_loc4`='确实如此。', `MaleText_loc5`='確實如此。', `MaleText_loc7`='Estoy de acuerdo.', `FemaleText_loc1`='정말 그렇군요.', `FemaleText_loc4`='确实如此。', `FemaleText_loc5`='確實如此。', `FemaleText_loc7`='Estoy de acuerdo.' WHERE `ID`=4748;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모이라 공주는 이제 제왕 타우릿산 옆에서 지내고 있소. 무슨 세뇌 마법을 걸어 놓은 것 같은데... 그런데도 난 여기 앉아서 아무런 일도 할 수가 없으니.', `MaleText_loc4`='她现在就在索瑞森大帝身边。他对她施加了某种可以改变思维的强大法术……而我只能待在这儿，束手无策。', `MaleText_loc5`='她現在就在索瑞森大帝身邊。他對她施加了某種可以改變思維的強大法術...而我只能待在這兒，束手無策。', `MaleText_loc7`='Ella vive ahora junto al emperador Thaurissan. Él la tiene sometida a una suerte de encantamiento que altera la mente... y aquí estoy yo, totalmente indefenso.' WHERE `ID`=4749;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위로가 될지는 모르겠지만 감옥 문을 열어 드리도록 하겠습니다. 여기서 빠져 나가는 건 당신이 알아서 하십시오. 잘 가세요, 카란.', `MaleText_loc4`='我会把门开着的，你怎么逃出去是你的问题。再见，卡兰。', `MaleText_loc5`='我會把門開著的，你怎麼逃出去是你的問題。再見，卡蘭。', `MaleText_loc7`='Si te sirve de consuelo, dejaré abierta la puerta de la celda. Como salgas es tu problema. Adiós, Kharan.', `FemaleText_loc1`='위로가 될지는 모르겠지만 감옥 문을 열어 드리도록 하겠습니다. 여기서 빠져 나가는 건 당신이 알아서 하십시오. 잘 가세요, 카란.', `FemaleText_loc4`='我会把门开着的，你怎么逃出去是你的问题。再见，卡兰。', `FemaleText_loc5`='我會把門開著的，你怎麼逃出去是你的問題。再見，卡蘭。', `FemaleText_loc7`='Si te sirve de consuelo, dejaré abierta la puerta de la celda. Como salgas es tu problema. Adiós, Kharan.' WHERE `ID`=4750;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 그녀 앞에 있는 탈출의 룬을 거머쥡니다.', `FemaleText_loc4`='%s在她面前握紧逃脱符文。', `FemaleText_loc5`='%s在她面前握緊逃脫符文。', `FemaleText_loc7`='%s sostiene la runa de escape delante de ella.' WHERE `ID`=4751;
