UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠자리에 든 나를 방해하는 건 바보들뿐이다.', `MaleText_loc4`='只有傻子才敢侵犯我的巢穴。', `MaleText_loc5`='只有傻子才敢侵犯我的巢穴。', `MaleText_loc7`='Solo un idiota se atreve a molestarme en mi guarida.' WHERE `ID`=4753;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='증거물을 가져왔습니다, 키루스.', `MaleText_loc4`='我让你看看我的能力的证明，塞勒斯。', `MaleText_loc5`='我讓你看看我的能力的證明，塞勒斯。', `MaleText_loc7`='Vengo a presentaros pruebas de mis hechos, Cyrus.', `FemaleText_loc1`='증거물을 가져왔습니다, 키루스.', `FemaleText_loc4`='我让你看看我的能力的证明，塞勒斯。', `FemaleText_loc5`='我讓你看看我的能力的證明，塞勒斯。', `FemaleText_loc7`='Vengo a presentaros pruebas de mis hechos, Cyrus.' WHERE `ID`=4754;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 증거물을 가져오지 않았습니다, 키루스.', `MaleText_loc4`='塞勒斯，我没有任何证据。', `MaleText_loc5`='塞勒斯，我沒有任何證據。', `MaleText_loc7`='No poseo prueba alguna, Cyrus.', `FemaleText_loc1`='아직 증거물을 가져오지 않았습니다, 키루스.', `FemaleText_loc4`='塞勒斯，我没有任何证据。', `FemaleText_loc5`='塞勒斯，我沒有任何證據。', `FemaleText_loc7`='No poseo prueba alguna, Cyrus.' WHERE `ID`=4755;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<눈이 번쩍이며 빛나는 키루스>$B$B너를 통째로 집어삼킬까? 아니면 좀 더 살려 둘까?$B$B아직 쓸모가 있을지도 모르겠군...$B$B내 부하와 맞서 싸워. 살아남아서 네가 승리한 증거를 가져와.', `MaleText_loc4`='<塞勒斯的眼睛熠熠生辉>$B$B我是囫囵吞了你呢，还是放你一条生路？$B$B或许你还有些用处……$B$B向我的奴仆发出挑战吧，$c。生存下来，并把你获胜的证据交给我。', `MaleText_loc5`='<塞勒斯的眼睛熠熠生輝>$B$B我是囫圇吞了你呢，還是放你一條生路?$B$B或許你還有些用處...$b$b向我的奴僕發出挑戰吧，$r。生存下來，並把你獲勝的證據交給我。', `MaleText_loc7`='<Los ojos de Cyrus brillan con intensidad>$B$B¿Te devoro o te dejo vivir?$B$BQuizás aún puedas resultar de utilidad... $B$BDesafía a mi esbirro, $r. Sobrevive y tráeme una prueba de tu victoria.' WHERE `ID`=4756;
