UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 날 찾아오는 일은 아주 드문데... 무슨 일로 왔나?', `MaleText_loc4`='很少有人能找到我……我能为你做什么吗？', `MaleText_loc5`='很少有人能找到我...我能為你做什麼嗎?', `MaleText_loc7`='Muy pocos me buscan... ¿En qué puedo ayudarte?' WHERE `ID`=4825;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 가르칠 수 있는 건 모두 가르쳤네, $n. 행운이 자네와 함께하기를.', `MaleText_loc4`='我已经把我所有的知识都教给你了，$n。祝你好运。', `MaleText_loc5`='我已經把我所有的知識都教給你了，$n。祝你好運。', `MaleText_loc7`='Te he enseñado todo lo que sé, $n. Que la suerte te acompañe.' WHERE `ID`=4826;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에보뿌리는 어떻게 구할 수 있습니까?', `MaleText_loc4`='我要怎样才能得到灵根草呢？', `MaleText_loc5`='我要怎樣才能得到靈根草呢?', `MaleText_loc7`='¿Cómo puedo conseguir la raíz del mal?', `FemaleText_loc1`='에보뿌리는 어떻게 구할 수 있습니까?', `FemaleText_loc4`='我要怎样才能得到灵根草呢？', `FemaleText_loc5`='我要怎樣才能得到靈根草呢?', `FemaleText_loc7`='¿Cómo puedo conseguir la raíz del mal?' WHERE `ID`=4827;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헤헤... 호기심이 강한 친구로구먼. 에보뿌리를 구하는 방법을 가르쳐 주지.$B$B여기서 북쪽에 있는 오래된 폐허에는 미블론 스날투스라는 아주 재수없는 놀이 한 마리 살고 있소. 내가 알기에는 유일하게 자라고 있는 에보뿌리를 지키고 있는데, 불철주야로 지키지 않겠소! 잠도 자지 않는 것 같소이다!$B$B할 수 있는 건 매수하는 방법밖에 없겠는데, 그 녀석이 좋아할 미끼를 내가 좀 주겠소. 그 녀석 옆에 그냥 두기만 하면 당신이 에보뿌리를 따올 수 있을 만큼 시간을 벌 수 있을 거요. 행운을 빌겠소!', `MaleText_loc4`='呵呵呵呵……你是个相当好奇的家伙，不是吗，$n？嗯，我来告诉你该怎么做。$B$B在此地以北的古老废墟中居住着一个名叫米布隆·乱齿的令人厌恶的豺狼人。他日夜守护着灵根草，好像从不睡觉似的！$B$B你必须把他引开才行。我可以卖给你一些他喜欢吃的东西——把食物放在他附近，引他过来，然后你就可以趁机拿走灵根草啦。祝你好运！', `MaleText_loc5`='呵呵呵呵...你是個相當好奇的傢伙，不是嗎，$n?嗯，我來告訴你該怎麼做。$B$B在此地以北的古老廢墟中居住著一個名叫米布隆·亂齒的令人厭惡的豺狼人。他日夜守護著靈根草，好像從不睡覺似的!$B$B你必須把他引開才行。我可以賣給你一些他喜歡吃的東西─把食物放在他附近，引他過來，然後你就可以趁機拿走靈根草啦。祝你好運!', `MaleText_loc7`='Je, je... Te gusta saber, ¿verdad, $n? Vale, esto es lo que tienes que hacer.$B$BAl norte de aquí, en las viejas ruinas, vive un gnoll muy desagradable llamado Miblon Gruñediente. Él custodia la única raíz del mal que conozco, ¡pero la vigila día y noche! ¡Parece como si nunca durmiera!$B$BLo que podéis hacer es sobornarlo. Puedo venderte un poco de cebo que pueda resultarle apetitoso. Solo déjalo junto a él y eso lo distraerá el tiempo suficiente para que puedas coger la raíz del mal. ¡Suerte!' WHERE `ID`=4828;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디 한번 덤벼 보시지!', `MaleText_loc4`='来试试看吧！', `MaleText_loc5`='來試試看吧!', `MaleText_loc7`='¡¡Enfréntate a mí si te atreves!!' WHERE `ID`=4829;
