UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 문턱에서 들고 있던 돌덩이를 버리고 미끼 쪽을 바라봅니다.', `MaleText_loc4`='%s丝毫不理会门口的障碍物，眼睛直勾勾地盯着诱饵。', `MaleText_loc5`='%s離開了他在門前阻攔的位置，朝誘餌看了過去。', `MaleText_loc7`='%s abandona el bloque que sostenía en la entrada y mira hacia el cebo.' WHERE `ID`=4836;
