UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 중급 약초채집가가 아닙니다. 그래도 도움이 될 수 있습니까?', `MaleText_loc4`='我对草药学没什么了解，那么我还能帮上忙吗？', `MaleText_loc5`='我對草藥學沒什麼瞭解，那麼我還能幫上忙嗎?', `MaleText_loc7`='No soy un oficial herborista, pero ¿puedo ayudarte en tu tarea?', `FemaleText_loc1`='저는 중급 약초채집가가 아닙니다. 그래도 도움이 될 수 있습니까?', `FemaleText_loc4`='我对草药学没什么了解，那么我还能帮上忙吗？', `FemaleText_loc5`='我對草藥學沒什麼瞭解，那麼我還能幫上忙嗎?', `FemaleText_loc7`='No soy una oficial herborista, pero ¿puedo ayudarte en tu tarea?' WHERE `ID`=4848;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래... 자네가 약초채집 기술을 익히면 좀 더 큰 보람을 얻을 수 있을 걸세. 조금 특별한 씨앗을 기르고 재배해야 해. 이 늘푸른 주머니만 있으면 아무리 초보자라도 뭔가 길러낼 수 있긴 하지만 약초학에 소질이 좀 있다면 더욱 풍성한 수확을 거둘 수 있을 걸세.', `MaleText_loc4`='没错，但是如果你精通草药学的话，你会发现它更有用！你可以培育出特别的草药来。虽然常青袋是个连新手都能轻松使用的工具，但那些对草药学有天资的冒险者将会得到更丰硕的报酬。', `MaleText_loc5`='沒錯，但是如果你精通草藥學的話，你會發現它更有用!你可以培育出特別的草藥來。雖然常青袋是個連新手都能輕鬆使用的工具，但那些對草藥學有天資的冒險者將會得到更豐碩的報酬。', `MaleText_loc7`='¡Sí, pero te resultará más gratificante si tienes conocimientos de herboristería! Estarás cultivando y cuidando semillas especiales. Si bien la bolsa de siempreverde que te daré sirve hasta al más inexperto para cultivar cualquier cosa, los estudiosos en botánica obtienen mejores resultados.' WHERE `ID`=4849;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하시오. 페더문 요새의 이 변변찮은 자가 오늘은 뭘 도와 드리오리까?', `MaleText_loc4`='你好，$c。我这个羽月要塞的仆人可以为你做些什么呢？', `MaleText_loc5`='你好，$c。我這個羽月要塞的僕人可以為你做些什麼呢?', `MaleText_loc7`='Saludos, $c. ¿Qué puede hacer este humilde sirviente del Bastión Plumaluna hacer por ti hoy?' WHERE `ID`=4850;
