UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='육체의 죽음은 영혼과 성스러운 임무의 탄생을 의미한 것이오.', `FemaleText_loc4`='我们肉体的死亡标志着我们灵魂和神圣使命的重生。', `FemaleText_loc5`='我們肉體的死亡標誌著我們靈魂和神聖使命的重生。', `FemaleText_loc7`='La muerte de nuestra carne marcó el nacimiento de nuestro espíritu y nuestra misión sagrada.' WHERE `ID`=4873;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 일곱 현자 중 한 명이오. 우리의 운명은 영원히 이곳을 지키는 것이오.', `MaleText_loc4`='我是七贤中的一个，而守护这里是我们永远的诅咒。永远。', `MaleText_loc5`='我是七賢中的一個，而守護這裡是我們永遠的詛咒。永遠。', `MaleText_loc7`='Soy uno de los Siete y es nuestro sino ser centinelas. Para siempre.' WHERE `ID`=4874;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 지도자, 운명의 문지기는 도전이라면 귀가 솔깃할거요.', `MaleText_loc4`='去找我们的领袖杜姆雷尔发出挑战吧。', `MaleText_loc5`='去找我們的領袖杜姆雷爾發出挑戰吧。', `MaleText_loc7`='Nuestro líder, Condena''rel, siempre está dispuesto a aceptar un desafío.' WHERE `ID`=4875;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 영원히 돌을 만질 수 없게 되었소. 두 번 다시는 무쇠를 가꾸는 영광을 알지 못할 것이오...', `MaleText_loc4`='我永远都不能再触摸石头了。我永远都无法再体会钢铁的荣誉了……', `MaleText_loc5`='我永遠都不能再觸摸石頭了。我永遠都無法再體會鋼鐵的榮譽了...', `MaleText_loc7`='Se me ha prohibido para siempre tocar la piedra. Jamás volveré a saborear la gloria del hierro forjado...' WHERE `ID`=4876;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신은 우리의 동족도 아니고 도전장을 낸 것도 아니니 이곳을 지나갈 수 없습니다.', `FemaleText_loc4`='你不能通过。你不是我们的人，也没有发出过挑战。', `FemaleText_loc5`='你不能通過。你不是我們的人，也沒有發出過挑戰。', `FemaleText_loc7`='No puedes pasar. No eres de los nuestros y tampoco has formulado el desafío.' WHERE `ID`=4877;
