UPDATE `locales_broadcast_text` SET `MaleText_loc1`='운명의 문지기여, 당신의 속박도 끝입니다. 내가 도전하겠습니다!', `MaleText_loc4`='你的奴役结束了，杜姆雷尔。我向你挑战！', `MaleText_loc5`='你的奴役結束了，杜姆雷爾。我向你挑戰!', `MaleText_loc7`='Tu cautiverio ha llegado a su fin, Condena’rel. ¡Te desafío!', `FemaleText_loc1`='운명의 문지기여, 당신의 속박도 끝입니다. 내가 도전하겠습니다!', `FemaleText_loc4`='你的奴役结束了，杜姆雷尔。我向你挑战！', `FemaleText_loc5`='你的奴役結束了，杜姆雷爾。我向你挑戰!', `FemaleText_loc7`='Tu cautiverio ha llegado a su fin, Condena’rel. ¡Te desafío!' WHERE `ID`=4892;
