UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그늘의 문지기, 비밀을 말해 주십시오!', `MaleText_loc4`='杜姆雷尔，告诉我你的秘密！', `MaleText_loc5`='格魯雷爾，告訴我你的秘密!', `MaleText_loc7`='¡Gloom''rel, cuéntame tus secretos!', `FemaleText_loc1`='그늘의 문지기, 비밀을 말해 주십시오!', `FemaleText_loc4`='杜姆雷尔，告诉我你的秘密！', `FemaleText_loc5`='格魯雷爾，告訴我你的秘密!', `FemaleText_loc7`='¡Gloom''rel, cuéntame tus secretos!' WHERE `ID`=4897;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고대 기술을 배우고 싶소? 아니면 검은 무쇠를 녹이고 싶은 거요?$B$B내 부탁을 들어주시오. 내게 희생 정신을 보여주시오. 그러면 한번 생각해 보지!', `MaleText_loc4`='你想要学习这项古老的手艺？你希望冶炼黑铁？$B$B给我一样祭品我就会考虑的！', `MaleText_loc5`='你想要學習這項古老的手藝?你希望冶煉黑鐵?$B$B取悅我，$r。給我一樣祭品我就會考慮的!', `MaleText_loc7`='¿Deseas aprender el antiguo oficio? ¿Quieres fundir hierro negro?$B$BApacíguame, $r. ¡Ofréceme un sacrificio y lo consideraré!' WHERE `ID`=4898;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 의지가 강하고 목적이 뚜렷하군.$B$B당신이라면 자격이 있을지도 모르겠군.', `MaleText_loc4`='你的意志很坚强，而且你的意图很明显。$B$B可能你的确有资格……', `MaleText_loc5`='你的意志很堅強，而且你的意圖很明顯。$B$B可能你的確有資格...', `MaleText_loc7`='Tu voluntad es férrea y tus intenciones son claras.$B$BQuizás seas digno...' WHERE `ID`=4899;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 말한 대가를 치렀으니 이제 그 비밀을 가르쳐주십시오, 그늘의 문지기!', `MaleText_loc4`='我已经把你要的都给你了，格鲁雷尔。现在，告诉我你的秘密！', `MaleText_loc5`='我已經把你要的給你了，格魯雷爾。現在，告訴我你的秘密!', `MaleText_loc7`='He pagado tu precio, Gloom''rel. ¡Ahora enséñame tus secretos!', `FemaleText_loc1`='당신이 말한 대가를 치렀으니 이제 그 비밀을 가르쳐주십시오, 그늘의 문지기!', `FemaleText_loc4`='我已经把你要的都给你了，格鲁雷尔。现在，告诉我你的秘密！', `FemaleText_loc5`='我已經把你要的給你了，格魯雷爾。現在，告訴我你的秘密!', `FemaleText_loc7`='He pagado tu precio, Gloom''rel. ¡Ahora enséñame tus secretos!' WHERE `ID`=4900;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 원하는 게 무언지 알았고 값진 보석을 대가로 지급했으니 가르쳐주겠소...', `MaleText_loc4`='你表明了自己的愿望，也支付了珍贵的石头。我会教你的……', `MaleText_loc5`='你已經表明了你的願望，也支付了珍貴的石頭。我會教你的...', `MaleText_loc7`='Me has mostrado lo que deseas y has pagado con una piedra preciosa. Te enseñaré...' WHERE `ID`=4901;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자다! 침입자를 공격하라!', `MaleText_loc4`='入侵者！攻击入侵者！', `MaleText_loc5`='入侵者!攻擊入侵者!', `MaleText_loc7`='¡Intrusos! ¡Atacad a los intrusos!', `FemaleText_loc1`='침입자다! 침입자를 공격하라!', `FemaleText_loc4`='入侵者！攻击入侵者！', `FemaleText_loc5`='入侵者!攻擊入侵者!', `FemaleText_loc7`='¡Intrusos! ¡Atacad a los intrusos!' WHERE `ID`=4902;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가는 길은 나도 안다고, 벌레 같은 녀석아. 소처럼 밀고 갈 필요는 없어.', `MaleText_loc4`='我知道怎么走，蠢货，你没必要像赶牛那样鞭打我吧？', `MaleText_loc5`='我知道怎麼走，蠢貨，你沒必要像趕牛那樣鞭打我吧?', `MaleText_loc7`='Conozco el camino, gusano. No tienes que empujarme como si fuera una res.' WHERE `ID`=4903;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 해서 빠져나갈 수 있을 것 같아? 동지들이 날 구하러 오면 네 자만심에 대한 대가를 치르게 될 것이다.', `MaleText_loc4`='你显然很明白自己无法从这场袭击中逃生。他们是冲我而来的，你将为自己的傲慢付出代价。', `MaleText_loc5`='你顯然很明白自己無法從這場襲擊中逃生。他們是衝我而來的，你將為自己的傲慢付出代價。', `MaleText_loc7`='No pienses que te vas a salir con la tuya con esta incursión. Vendrán a buscarme y pagarás por tu insolencia.' WHERE `ID`=4904;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 녀석들을 죽이시오, 동지들이여!', `MaleText_loc4`='兄弟们，超过他们！', `MaleText_loc5`='兄弟們，超過他們!', `MaleText_loc7`='¡ATRAVESADLOS CON LAS ESPADAS, HERMANOS!' WHERE `ID`=4905;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음에 또 동지들을 만나면, 이번만큼 운이 따라 주진 않을 거야.', `MaleText_loc4`='我想下次你遇到我的兄弟时可能就没这么幸运啦。', `MaleText_loc5`='我想下次你遇到我的兄弟時可能就沒這麼幸運啦。', `MaleText_loc7`='Dudo que tengáis tanta suerte la próxima vez que te encuentres a mis hermanos.' WHERE `ID`=4906;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='널 잡으러 오고 있다, 멍청아!', `MaleText_loc4`='他们是冲你而来的，蠢货！', `MaleText_loc5`='他們是衝你而來的，蠢貨!', `MaleText_loc7`='¡Vienen a por ti, idiota!' WHERE `ID`=4907;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 어쩌자는 거냐? 지금도 검은바위 부족의 군대는 세계를 파괴할 준비를 착실히 해나가고 있다.', `MaleText_loc4`='蠢货，你们还以为自己成功了吗？即使在现在，黑石军队也在准备着摧毁你们的世界。', `MaleText_loc5`='蠢貨，你們還以為自己成功了嗎?即使在現在，黑石軍隊也在準備著摧毀你們的世界。', `MaleText_loc7`='¿Qué crees que vas a lograr con esto, idiota? Incluso ahora, los ejércitos Roca Negra están preparándose para destruir tu mundo.' WHERE `ID`=4908;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비룡아, 불타는 검은 날개를 활짝 펼쳐라. 이봐, 넌 죽을 준비나 해.', `MaleText_loc4`='黑龙来了，准备受死吧！', `MaleText_loc5`='黑龍來了，準備受死吧!', `MaleText_loc7`='Su vuelo es el más oscuro. ¡Prepárate para tu final!' WHERE `ID`=4909;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 신성한 대지를 더럽힐 수 없을 것이다!', `MaleText_loc4`='你不能玷污我们的圣地！', `MaleText_loc5`='你不能玷污我們的聖地!', `MaleText_loc7`='¡No vais a profanar nuestra tierra sagrada!', `FemaleText_loc1`='우리의 신성한 대지를 더럽힐 수 없을 것이다!', `FemaleText_loc4`='你不能玷污我们的圣地！', `FemaleText_loc5`='你不能玷污我們的聖地!', `FemaleText_loc7`='¡No vais a profanar nuestra tierra sagrada!' WHERE `ID`=4910;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흥, 이게 다는 아니다. 각오해!', `MaleText_loc4`='最可怕的噩梦还没降临呢！', `MaleText_loc5`='最可怕的噩夢還沒降臨呢!', `MaleText_loc7`='¡Aún falta lo peor!' WHERE `ID`=4911;
