UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 이걸로 너도 마지막이다, 이 바퀴벌레야.', `MaleText_loc4`='蠢货，等死吧。', `MaleText_loc5`='蠢貨，等死吧。', `MaleText_loc7`='Es hora de hacer tu última aparición, miserable.' WHERE `ID`=4913;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='콜카르 일족이 세계를 지배할 것이다!', `MaleText_loc4`='科卡尔部族将统治世界！', `MaleText_loc5`='科卡爾部族將統治世界!', `MaleText_loc7`='¡Los Kolkar reinarán!' WHERE `ID`=4914;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 콜카르 일족에게 너희 호드는 아무것도 아니다!', `MaleText_loc4`='你们$r对于科卡尔部族来说什么都不是！', `MaleText_loc5`='你們$r對於科卡爾部族來說什麼都不是!', `MaleText_loc7`='¡Tu Horda no significa nada para los Kolkar!' WHERE `ID`=4915;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하룻강아지들아! 내가 왔노라! 두려움에 벌벌 떨어라!', `MaleText_loc4`='颤抖吧！我来了！', `MaleText_loc5`='顫抖吧!我來了!', `MaleText_loc7`='¡Temblad de miedo, perros! ¡Aquí estoy!' WHERE `ID`=4916;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='콜카르 일족의 힘이야말로 세계 최강이다!', `MaleText_loc4`='科卡尔部族是最强大的！', `MaleText_loc5`='科卡爾部族是最強大的!', `MaleText_loc7`='¡Los Kolkar son los más fuertes!' WHERE `ID`=4917;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 항복합니다.', `MaleText_loc4`='%s屈服了。', `MaleText_loc5`='%s投降了。', `MaleText_loc7`='%s se somete.' WHERE `ID`=4918;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두 발로 아장아장 걷는 네놈들쯤은, 콜카르의 어린이에게 상대하도록 하겠다!', `MaleText_loc4`='你们这些两条腿的蠢货！我的孩子都可以打败你们！', `MaleText_loc5`='你們這些兩條腿的蠢貨!我的孩子都可以打敗你們!', `MaleText_loc7`='¡Los humanos no valéis para nada! ¡Incluso mis hijos podrían contigo!' WHERE `ID`=4919;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 왔노라! 이 땅에 활개치는 것도 이제는 끝인 줄 알아라!', `MaleText_loc4`='我在这儿！你对这片大地的统治已经结束了！', `MaleText_loc5`='我在這兒!你對這片大地的統治已經結束了!', `MaleText_loc7`='¡Aquí estoy! ¡Tu reinado en esta tierra ha llegado a su fin!' WHERE `ID`=4920;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드 만세!', `MaleText_loc4`='为了部落！', `MaleText_loc5`='為了部落!', `MaleText_loc7`='¡Por la Horda!', `FemaleText_loc1`='호드 만세!', `FemaleText_loc4`='为了部落！', `FemaleText_loc5`='為了部落!', `FemaleText_loc7`='¡Por la Horda!' WHERE `ID`=4921;
