UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침략자가 나타났다!', `MaleText_loc4`='入侵者在这儿！', `MaleText_loc5`='入侵者在這兒!', `MaleText_loc7`='¡Los invasores están aquí!', `FemaleText_loc1`='침략자가 나타났다!', `FemaleText_loc4`='入侵者在这儿！', `FemaleText_loc5`='入侵者在這兒!', `FemaleText_loc7`='¡Los invasores están aquí!' WHERE `ID`=4923;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하라! 콜카르 일족이 공격한다!', `MaleText_loc4`='小心！科卡尔半人马开始攻击了！', `MaleText_loc5`='小心!科卡爾半人馬開始攻擊了!', `MaleText_loc7`='¡Cuidado! ¡Los Kolkar atacan!', `FemaleText_loc1`='조심하라! 콜카르 일족이 공격한다!', `FemaleText_loc4`='小心！科卡尔半人马开始攻击了！', `FemaleText_loc5`='小心!科卡爾半人馬開始攻擊了!', `FemaleText_loc7`='¡Cuidado! ¡Los Kolkar atacan!' WHERE `ID`=4924;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 적은 쓰러지리라!', `MaleText_loc4`='我们的敌人必将败北！', `MaleText_loc5`='我們的敵人必將敗北!', `MaleText_loc7`='¡Nuestros enemigos caerán!', `FemaleText_loc1`='우리의 적은 쓰러지리라!', `FemaleText_loc4`='我们的敌人必将败北！', `FemaleText_loc5`='我們的敵人必將敗北!', `FemaleText_loc7`='¡Nuestros enemigos caerán!' WHERE `ID`=4925;
