UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놀러 온 건가? 그럼 같이 한번 놀아 보자고!', `MaleText_loc4`='你想玩玩吗？那就来吧！', `MaleText_loc5`='你想玩玩嗎?那就來吧!', `MaleText_loc7`='¿Has venido a jugar? ¡Juguemos, pues!' WHERE `ID`=4927;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무릎을 꿇어라, 그랄크.', `MaleText_loc4`='跪下，格拉克。', `MaleText_loc5`='跪下，格拉克。', `MaleText_loc7`='Arrodíllate, Grark.,' WHERE `ID`=4928;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그랄크 로크럽! 너는 호드에 대한 반역죄로 기소되었고 이미 유죄로 판결이 났다. 네 변명이나 주장 따위는 아무런 의미가 없다. 대집행자 누즈라크, 앞으로 나오시오.', `MaleText_loc4`='格拉克·洛克鲁布，你被判对部落犯有叛国罪。你如何辩护并不重要。大执行官努兹拉克，站出来。', `MaleText_loc5`='格拉克·洛克魯布，你被判對部落犯有叛國罪。你如何辯護並不重要。高階劊子手努茲拉克，站出來。', `MaleText_loc7`='Grark Lorkrub, se te acusa y eres culpable de traicionar a la Horda. Tus plegarias no surtirán efecto. Sumo verdugo Nuzrak, da un paso adelante.' WHERE `ID`=4929;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 그랄크 위로 거대한 도끼를 치켜듭니다.', `MaleText_loc4`='%s对着格拉克扬起巨大的斧头。', `MaleText_loc5`='%s對著格拉克揚起巨大的斧頭。', `MaleText_loc7`='%s eleva su hacha gigantesca sobre Grark.' WHERE `ID`=4930;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 끝이로군...', `MaleText_loc4`='了结他……', `MaleText_loc5`='了結他...', `MaleText_loc7`='¡Acaba con él!' WHERE `ID`=4931;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 손을 번쩍 들어올렸다가 내리칩니다.', `MaleText_loc4`='%s举起斧头砍了下去。', `MaleText_loc5`='%s舉起斧頭，然後砍了下去。', `MaleText_loc7`='%s levanta la mano y luego la baja.' WHERE `ID`=4932;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐! 지금 즉시 카르가스로 가서 이 사실을 보고하게!', `MaleText_loc4`='你，立刻去卡加斯报告！', `MaleText_loc5`='你，立刻去卡加斯報告!', `MaleText_loc7`='¡Tú, Soldado, preséntate ante Kargath de inmediato!' WHERE `ID`=4933;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 술통에서 떨어져!', `MaleText_loc4`='离那些酒桶远一点！', `MaleText_loc5`='離那些酒桶遠一點!', `MaleText_loc7`='¡Apártate de esos barriles!' WHERE `ID`=4934;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어... 어떻게 해서 여기로 오게 됐는지 잘 모르겠어요...$B$B뗏목...을 타고 돌아다닌 거 같은데...$B$B', `MaleText_loc4`='我……我真的不知道自己是怎么到那儿的……$B$B我依稀记得用的是……木筏……$B$B', `MaleText_loc5`='我...我真的不知道自己是怎麼到那兒的...$b$b我依稀記得用的是...木筏...$b$b', `MaleText_loc7`='Yo... no estoy seguro de cómo llegué hasta aquí...$B$BCreo recordar que iba... en una balsa...$B$B' WHERE `ID`=4935;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 이제 죽은 몸이야!', `MaleText_loc4`='你会为此付出代价的！', `MaleText_loc5`='你會為此付出代價的!', `MaleText_loc7`='¡Pagarás por eso!' WHERE `ID`=4936;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일단 돈을 좀 내면 제 이야기를 해드리죠.$B$B아, 당신 $n|1이로군요;로군요;? 하하... 농담이었어요.', `MaleText_loc4`='付钱给我，我就说……$B$B哦，是你，$n！别介意……', `MaleText_loc5`='付錢給我，我就說...$b$b哦，是你，$n!別介意...', `MaleText_loc7`='Págame y hablaré...$B$B¡Ah, oye, eres tú, $n! No te preocupes por eso...' WHERE `ID`=4937;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 이름이 낯익지 않나요? 어쩌면 우린 오래전에 알고 지냈을지도 몰라요...$B$B내 이름은 아주 중요한 인물의 이름을 딴 것 같은데...', `MaleText_loc4`='你听说过我的名字吗？或许我们俩很早就相识了……$B$B我认为我得名于某个重要人物……', `MaleText_loc5`='你聽說過我的名字嗎?或許我們倆很早就相識了...$b$b我認為我得名於某個重要人物...', `MaleText_loc7`='¿Te suena mi nombre? Quizás nos conocimos mucho tiempo atrás...$B$BCreo que hay alguien importante que se llama como yo...' WHERE `ID`=4938;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요! 돌아와 줘서 기뻐요, $n. 내가 드린 첫 임무는 완수하셨나요? 그렇다면 다시 부탁드릴 임무가 있어요...', `MaleText_loc4`='嗨！很高兴你回来啦，$n。告诉我，你完成我给你的第一项任务了吗？如果完成了，我会给你第二项任务的……', `MaleText_loc5`='嗨!很高興你回來啦，$n。告訴我，你完成我給你的第一項任務了嗎?如果完成了，我會給你第二項任務的...', `MaleText_loc7`='¡Hola! Me alegra que hayas vuelto, $n. Dime, ¿has terminado la primera misión que te asigné? Si es así, puede que tenga una segunda misión para ti...' WHERE `ID`=4939;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기에 불시착한 후로 분화구를 돌아다니고 있었는데 전에 누가 말한 게 기억이 나더군요... "위로 가! 앞에 있는 산 위로!" 머릿속에서 계속 이 말이 들렸어요.$B$B그 말을 듣고 여기로 오게 된 거랍니다!', `MaleText_loc4`='我在火山口游荡了许久，后来我想起曾有人告诉我……“继续往前，到山上去。”这个声音在我的脑海中出现。$B$B听了这话之后我就来到了这里，$n！', `MaleText_loc5`='我在火山口遊蕩了許久，後來我想起曾有人告訴我...「繼續往前，到山上去。」這個聲音在我的腦海中出現。$B$B聽了這話之後我就來到了這裡，$n!', `MaleText_loc7`='Cuando caminaba por el cráter después de estrellarme aquí, recordé algo que me dijeron una vez... "Sube por la montaña," dijo la voz en mi cabeza.$B$B¡Escuchando esa voz es como acabé aquí, $n!' WHERE `ID`=4940;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 오래전에 여행을 다니다가 누군가를 만났는데 그 사람이 이런 말을 했었어요. "그걸 사용하는 법을 통달하면 이걸 주겠소"라고.$B$B그게 무슨 뜻인 것 같아요? 그때 나는 몰랐어요. 실은 지금도 여전히 모르겠고요...', `MaleText_loc4`='很久之前，在我的旅途之中，我遇到了一个人，他告诉我：“掌握它的使用方法，你就可以拥有它。”$B$B你觉得那是什么意思？那时我还不知道，而且现在我还是不知道，真的……', `MaleText_loc5`='很久之前，在我的旅途之中，我遇到了一個人，他告訴我:「掌握它的使用方法，你就可以擁有它。」$B$B你覺得那是什麼意思?那時我還不知道，而且現在我還是不知道，真的...', `MaleText_loc7`='Hace mucho tiempo, durante mis viajes, conocí a un hombre que me dijo: "Aprende a usarlo y podrás tenerlo."$B$B¿Qué crees que puede significar? Entonces no lo sabía y ahora sigo sin saberlo, en realidad...' WHERE `ID`=4941;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 모두에게 비밀로 해야 해요. 나까지 포함해서 말이에요!$B$B날 찾아줘서 기뻐요. 내가 수풀 속이나 바위 밑에 숨어 있지 않아서 다행이지 않나요?', `MaleText_loc4`='对任何人而言……包括我，这都是一个秘密！$B$B很高兴你找到了我——我没躲藏在树丛中或是岩石下，挺幸运的，是吧？', `MaleText_loc5`='對任何人而言...包括我，這都是一個秘密!$B$B很高興你找到了我─我沒躲藏在樹叢中或是岩石下，挺幸運的，是吧?', `MaleText_loc7`='Es un misterio para todos... ¡incluso para mí!$B$B¡Me alegro de que me hayas encontrado. Menos mal que no tengo que ocultarme detrás de un arbusto o debajo de una roca, ¿verdad?' WHERE `ID`=4942;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고마워요, $n! 당신이야말로 운고로 분화구의 영웅이세요!', `MaleText_loc4`='谢谢你，$n！你是安戈洛环形山的英雄！', `MaleText_loc5`='謝謝你，$n!你是安戈洛環形山的英雄!', `MaleText_loc7`='¡Gracias, $n! ¡Eres $gel héroe:la heroína; del cráter de Un''Goro!' WHERE `ID`=4943;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라그나로스 님이 최고 지배자가 될 것이다!', `MaleText_loc4`='拉格纳罗斯将拥有至高无上的统治权！', `MaleText_loc5`='拉格納羅斯將擁有至高無上的統治權!', `MaleText_loc7`='¡Ragnaros reinará para siempre!', `FemaleText_loc1`='라그나로스 님이 최고 지배자가 될 것이다!', `FemaleText_loc4`='拉格纳罗斯将拥有至高无上的统治权！', `FemaleText_loc5`='拉格納羅斯將擁有至高無上的統治權!', `FemaleText_loc7`='¡Ragnaros reinará para siempre!' WHERE `ID`=4944;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 잔 드시오, $c 친구. 이게 마지막 술잔일 수도 있으니!', `MaleText_loc4`='喝点东西吧，$c。这可能是你最后一次喝东西啦！', `MaleText_loc5`='喝點東西吧，$c。這可能是你最後一次喝東西啦!', `MaleText_loc7`='Toma una copa, $c. ¡Puede que sea la última!', `FemaleText_loc1`='한 잔 드시오, $c 친구. 이게 마지막 술잔일 수도 있으니!', `FemaleText_loc4`='喝点东西吧，$c。这可能是你最后一次喝东西啦！', `FemaleText_loc5`='喝點東西吧，$c。這可能是你最後一次喝東西啦!', `FemaleText_loc7`='Toma una copa, $c. ¡Puede que sea la última!' WHERE `ID`=4945;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='험상궂은 주정뱅이 선술집이 아니었으면 여가 시간에 새끼용 날개나 뜯으면서 지냈을 거요.', `MaleText_loc4`='要不是因为这酒吧，我的空闲时间就只能用来剥龙鳞啦。', `MaleText_loc5`='要不是因為黑鐵酒吧，我大概會用我的空閒時間來剝龍鱗。', `MaleText_loc7`='De no ser por el Tragapenas, pasaría mi tiempo libre arrancando alas de crías de dragón.', `FemaleText_loc1`='험상궂은 주정뱅이 선술집이 아니었으면 여가 시간에 새끼용 날개나 뜯으면서 지냈을 겁니다.', `FemaleText_loc4`='要不是因为这酒吧，我的空闲时间就只能用来剥龙鳞啦。', `FemaleText_loc5`='要不是因為黑鐵酒吧，我大概會用我的空閒時間來剝龍鱗。', `FemaleText_loc7`='De no ser por el Tragapenas, pasaría mi tiempo libre arrancando alas de crías de dragón.' WHERE `ID`=4946;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='험상궂은 주정뱅이 선술집이 아니었으면 쉬는 시간에 새끼용 날개나 뜯으면서 지냈을 겁니다.', `MaleText_loc4`='要不是因为这酒吧，我的空闲时间就只能用来剥龙鳞啦。', `MaleText_loc5`='要不是因為黑鐵酒吧，我大概會用我的空閒時間來剝龍鱗。', `MaleText_loc7`='De no ser por el Tragapenas, quizás pasaría mi tiempo libre arrancando alas de crías de dragón.', `FemaleText_loc1`='험상궂은 주정뱅이 선술집이 아니었으면 쉬는 시간에 새끼용 날개나 뜯으면서 지냈을 거예요.', `FemaleText_loc4`='要不是因为这酒吧，我的空闲时间就只能用来剥龙鳞啦。', `FemaleText_loc5`='要不是因為黑鐵酒吧，我大概會用我的空閒時間來剝龍鱗。', `FemaleText_loc7`='De no ser por el Tragapenas, quizás pasaría mi tiempo libre arrancando alas de crías de dragón.' WHERE `ID`=4947;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물의 정령들이 불의 정령들과 전쟁을 치르고 있는데, 그렇게 따지고 보면 우리하고도 전쟁을 치르고 있는 셈이지. 녀석들의 우두머리 중 하나인 히드락시스가 요원들을 끌어 모으고 있다던데...', `MaleText_loc4`='水元素正在跟火元素交战，也就是说他们也在跟我们作战。他们的领袖之一的海达克希斯正在召集士兵……', `MaleText_loc5`='水元素正在跟火元素交戰，也就是說他們也在跟我們作戰。他們的領袖之一，海達克西斯正在召集士兵...', `MaleText_loc7`='Los elementales de agua están en guerra con los elementales de fuego, lo que en cierta medida significa que están en guerra con nosotros. Uno de sus líderes, Hydraxis, está reclutando agentes para su causa...', `FemaleText_loc1`='물의 정령들이 불의 정령들과 전쟁을 치르고 있는데, 그렇게 따지고 보면 우리하고도 전쟁을 치르고 있는 셈이죠. 녀석들의 우두머리 중 하나인 히드락시스가 요원들을 끌어 모으고 있다던데...', `FemaleText_loc4`='水元素正在跟火元素交战，也就是说他们也在跟我们作战。他们的领袖之一的海达克希斯正在召集士兵……', `FemaleText_loc5`='水元素正在跟火元素交戰，也就是說他們也在跟我們作戰。他們的領袖之一，海達克西斯正在召集士兵...', `FemaleText_loc7`='Los elementales de agua están en guerra con los elementales de fuego, lo que en cierta medida significa que están en guerra con nosotros. Uno de sus líderes, Hydraxis, está reclutando agentes para su causa...' WHERE `ID`=4948;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 정말 죽은 줄 알았습니다. 음...아직도 어질어질하네...', `MaleText_loc4`='啊，真悬，我以为自己这次铁定玩完了。呃……还是有点晕……', `MaleText_loc5`='喔...天啊，我以為我死定了。呃...頭還是很暈...', `MaleText_loc7`='Vaya, creí que había muerto. Ayy... qué mareos tengo todavía...' WHERE `ID`=4949;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물의 정령들 사이에서 히드락시스라는 군주가 불의 종들과 전쟁을 치르고 있다고 하더군. 그 녀석이 지기를 바랍시다!', `MaleText_loc4`='我听说水元素中的贵族海达克希斯发动了对火元素的战争。真希望他战败！', `MaleText_loc5`='我聽說水元素中的貴族海達克西斯發動了對火元素的戰爭。真希望他戰敗!', `MaleText_loc7`='He oído que un noble entre los elementales del agua, Hydraxis, está en guerra contra los siervos del fuego. ¡Esperemos que pierda!', `FemaleText_loc1`='물의 정령들 사이에서 히드락시스라는 군주가 불의 종들과 전쟁을 치르고 있다고 하더군요. 그 녀석이 지기를 바랍시다!', `FemaleText_loc4`='我听说水元素中的贵族海达克希斯发动了对火元素的战争。真希望他战败！', `FemaleText_loc5`='我聽說水元素中的貴族海達克西斯發動了對火元素的戰爭。真希望他戰敗!', `FemaleText_loc7`='He oído que un noble entre los elementales del agua, Hydraxis, está en guerra contra los siervos del fuego. ¡Esperemos que pierda!' WHERE `ID`=4950;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물의 군주 히드락시스는 아즈샤라의 폭풍의 만에 있는 어떤 섬에서 숨어 지낸다고 합디다. 그 바보 같은 녀석이 그곳에서 대체 무슨 음모를 꾸미고 있는 건지...', `MaleText_loc4`='海达克西斯公爵躲到了艾萨拉风暴海湾的某个岛屿上。那些家伙能有什么威胁？', `MaleText_loc5`='水領主海達克西斯躲到了艾薩拉風暴海灣的某個島嶼上。那些傢伙能從那裡聚集什麼威脅?', `MaleText_loc7`='El Señor del Agua Hydraxis se oculta en Azshara, en una isla en la Bahía de la Tempestad. ¿Qué clase de amenaza puede estar urdiendo este idiota?', `FemaleText_loc1`='물의 군주 히드락시스는 아즈샤라의 폭풍의 만에 있는 어떤 섬에서 숨어 지낸다고 하더군요. 그 바보 같은 녀석이 그곳에서 대체 무슨 음모를 꾸미고 있는 건지...', `FemaleText_loc4`='海达克西斯公爵躲到了艾萨拉风暴海湾的某个岛屿上。那些家伙能有什么威胁？', `FemaleText_loc5`='水領主海達克西斯躲到了艾薩拉風暴海灣的某個島嶼上。那些傢伙能從那裡聚集什麼威脅?', `FemaleText_loc7`='El Señor del Agua Hydraxis se oculta en Azshara, en una isla en la Bahía de la Tempestad. ¿Qué clase de amenaza puede estar urdiendo este idiota?' WHERE `ID`=4951;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 사고방식 마음에 드는군! 어서 이곳을 빠져 나갑시다!', `MaleText_loc4`='我喜欢你思考的方式！我们走吧！', `MaleText_loc5`='我喜歡你思考的方式!我們走吧!', `MaleText_loc7`='¡Me gusta como piensas! ¡Salgamos de aquí!' WHERE `ID`=4952;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='히드락시스가 이번 전쟁에 더 많은 병력을 끌어 모은다면 힘의 균형이 뒤바뀔지도 모르지...', `MaleText_loc4`='要是海达克西斯招募了新兵，就可能使双方的力量对比发生变化……', `MaleText_loc5`='要是海達克西斯招募了新兵，就可能使力量的平衡發生變化...', `MaleText_loc7`='Si Hydraxis recluta a más gente en su guerra, quizás cambie el equilibrio de fuerzas...', `FemaleText_loc1`='히드락시스가 이번 전쟁에 더 많은 병력을 끌어 모은다면 힘의 균형이 뒤바뀔지도 모르지요...', `FemaleText_loc4`='要是海达克西斯招募了新兵，就可能使双方的力量对比发生变化……', `FemaleText_loc5`='要是海達克西斯招募了新兵，就可能使力量的平衡發生變化...', `FemaleText_loc7`='Si Hydraxis recluta a más gente en su guerra, quizás cambie el equilibrio de fuerzas...' WHERE `ID`=4953;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='총기류와 불을 가지고 장난 치다가 결국 누군가 죽게 되는 거라니까, 딸꾹.', `MaleText_loc4`='枪炮与硝烟弥漫，直到某一方被摧毁。', `MaleText_loc5`='槍砲與硝煙彌漫，直到某一方被摧毀。', `MaleText_loc7`='Todo son armas y destellos hasta que alguien pierde y muere.', `FemaleText_loc1`='총기류와 불을 가지고 장난 치다가 결국 누군가 죽게 되는 거라니까, 딸꾹.', `FemaleText_loc4`='枪炮与硝烟弥漫，直到某一方被摧毁。', `FemaleText_loc5`='槍砲與硝煙彌漫，直到某一方被摧毀。', `FemaleText_loc7`='Todo son armas y destellos hasta que alguien pierde y muere.' WHERE `ID`=4954;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 여기서부터는 혼자서 갈 수 있겠군. 당신이 누군지는 모르겠지만 큰 빚을 졌소이다. 고맙소!', `MaleText_loc4`='好吧，我想我自己可以照顾自己了。我不认识你……但是我欠你一个人情。谢谢你！', `MaleText_loc5`='好吧，我想我自己可以照顧自己了。我不認識你...但是我欠你一個人情。謝謝你!', `MaleText_loc7`='De acuerdo, creo que puedo lograrlo yo solo desde aquí. No sé quién eres... pero te debo una. ¡Gracias!' WHERE `ID`=4955;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아버지께서 이런 날들이 올 것이라고 말씀하셨지. 웬 낯선 사람이 다가와서 말을 걸면 그 사람을 죽이지 않으려고 꾹 참아야 한다고 말이야.', `MaleText_loc4`='我父亲告诉我：有一天，会有一个陌生人跟我交谈，我必须控制住自己，不能杀了$g他:她;。', `MaleText_loc5`='我父親告訴我:有一天，會有一個陌生人跟我交談，我必須控制住自己，不能殺了$g他:她;。', `MaleText_loc7`='Mi padre me dijo que habría días como este, en los que una persona extraña hablaría conmigo y yo tendría que dominarme para no matar$glo:la;.', `FemaleText_loc1`='아버지께서 이런 날들이 올 것이라고 말씀하셨지. 웬 낯선 사람이 다가와서 말을 걸면 그 사람을 죽이지 않으려고 꾹 참아야 한다고 말이야.', `FemaleText_loc4`='我父亲告诉我：有一天，会有一个陌生人跟我交谈，我必须控制住自己，不能杀了$g他:她;。', `FemaleText_loc5`='我父親告訴我:有一天，會有一個陌生人跟我交談，我必須控制住自己，不能殺了$g他:她;。', `FemaleText_loc7`='Mi padre me dijo que habría días como este, en los que una persona extraña hablaría conmigo y yo tendría que dominarme para no matar$glo:la;.' WHERE `ID`=4956;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌망치 요새에 온 걸 환영하네, $c 친구. 내가 도와 줄 일이라도 있나?', `MaleText_loc4`='勇敢的$c，欢迎来到石槌要塞。我能帮助你吗？', `MaleText_loc5`='勇敢的$c，歡迎來到石槌堡。我能幫你什麼忙嗎?', `MaleText_loc7`='Te doy la bienvenida al Bastión Quebrantarrocas, valiente $c. ¿De qué manera puedo ayudarte hoy?' WHERE `ID`=4957;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까. 가죽 용품이나 가죽세공 보급품을 찾고 있다면 반쯤은 퇴직했다고 할 수 있는 이 성기사를 잘 찾아오신 겁니다.', `MaleText_loc4`='你好，$c。如果你在寻找皮革制品和制皮物资的话，来问我这个半退休的圣骑士就算是找对人了。', `MaleText_loc5`='你好，$c。如果你在尋找皮製品和製皮物資的話，來問我這個半退休的聖騎士就算是找對人了。', `MaleText_loc7`='Saludos, $c. Si buscas artículos de cuero y suministros de peletería, has venido a ver a la persona adecuada, un paladín casi retirado.' WHERE `ID`=4958;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대해를 건너야 하나 본데, 제대로 찾아오셨군. 여기는 처녀의 몽상호가 정박하는 곳이거든. 이 망망대해를 건너기에는 가장 편리한 여객선이지. 배가 도착하면 그냥 올라타기만 하면 돼. 언제 그 넓은 바다를 건넜는지도 모르게, 가시덤불 골짜기의 해변에 도착해 있을 거라네.', `MaleText_loc4`='看来你需要通过无尽之海的通道。那你算来对地方了，这儿就是少女之爱号的停泊处，她是这片水域上最好的客船。当船到达后，你就登上甲板，然后用不了多久你就可以躺在荆棘谷的沙滩上晒太阳了。', `MaleText_loc5`='看來你需要通過無盡之海的通道。那你算來對地方了，這兒就是少女之愛號的停泊處，她是這片水域上最好的客船。當船到達後，你就登上甲板，然後用不了多久你就可以躺在荊棘谷的沙灘上曬太陽了。', `MaleText_loc7`='Parece como si necesitases atravesar el Mare Magnum. Pues has venido al lugar adecuado. Este es el atracadero de La Fantasía de la Doncella, el mejor barco de pasajeros que existe para navegar por estas aguas. Cuando llegue, simplemente sube a bordo y en un abrir y cerrar de ojos estarás disfrutando de las suaves playas de Tuercespina.', `FemaleText_loc1`='대해를 건너야 하나 본데, 제대로 찾아오셨군. 여기는 처녀의 몽상호가 정박하는 곳이거든. 이 망망대해를 건너기에는 가장 편리한 여객선이지. 배가 도착하면 그냥 올라타기만 하면 돼. 언제 그 넓은 바다를 건넜는지도 모르게, 가시덤불 골짜기의 해변에 도착해 있을 거라네.', `FemaleText_loc4`='看来你需要通过无尽之海的通道。那你算来对地方了，这儿就是少女之爱号的停泊处，她是这片水域上最好的客船。当船到达后，你就登上甲板，然后用不了多久你就可以躺在荆棘谷的沙滩上晒太阳了。', `FemaleText_loc5`='看來你需要通過無盡之海的通道。那你算來對地方了，這兒就是少女之愛號的停泊處，她是這片水域上最好的客船。當船到達後，你就登上甲板，然後用不了多久你就可以躺在荊棘谷的沙灘上曬太陽了。', `FemaleText_loc7`='Parece como si necesitases atravesar el Mare Magnum. Pues has venido al lugar adecuado. Este es el atracadero de La Fantasía de la Doncella, el mejor barco de pasajeros que existe para navegar por estas aguas. Cuando llegue, simplemente sube a bordo y en un abrir y cerrar de ojos estarás disfrutando de las suaves playas de Tuercespina.' WHERE `ID`=4959;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='확실히 남쪽 바다 어디에서도 무법항에서 먹을 수 있는 조개 수프만한 게 없지. 아, 요리에는 관심이 없나 보군? 아무튼 처녀의 몽상호 정박장에 온 것을 환영하오. 이 처녀의 몽상호로 말하자면 동부 왕국과 칼림도어를 왕래하는 가장 빠른 여객선이지. 이 배를 타면 톱니항으로 금방 갈 수 있소. 그러니 배가 도착할 때까지 편히 기다리시오.', `MaleText_loc4`='我必须承认，藏宝海湾有南海最好的杂烩蚌肉。哦，对烹饪不感兴趣？那么欢迎你投宿少女之爱号——在东部王国和卡利姆多之间航行的最好的客船。很快她将驰往棘齿城，在她到达之前好好享受吧。', `MaleText_loc5`='我必須承認，藏寶海灣有南海最好的蚌肉雜燴。哦，對烹飪不感興趣?那麼歡迎你投宿少女之愛號─在東部王國和卡林多之間航行的最好的客船。很快她將馳往棘齒城，在她到達之前好好享受吧。', `MaleText_loc7`='Tengo que decir que la Bahía del Botín tiene la mejor sopa de almejas que se pueda probar en los Mares del Sur. Ah, ¿no te interesa la cocina? Pues deja que sea el primero en darte la bienvenida al atracadero de La Fantasía de la Doncella, el mejor barco de pasajeros que hay para navegar entre los Reinos del Este y Kalimdor. Pronto volverá para realizar otro viaje a Trinquete, así que ponte cómodo hasta que llegue.', `FemaleText_loc1`='확실히 남쪽 바다 어디에서도 무법항에서 먹을 수 있는 조개 수프만한 게 없죠. 아, 요리에는 관심이 없나 보군요. 아무튼 처녀의 몽상호 정박지에 온 것을 환영해요. 이 처녀의 몽상호로 말하자면 동부 왕국과 칼림도어를 왕래하는 가장 빠른 여객선이죠. 이 배를 타면 톱니항으로 금방 갈 수 있소. 그러니 배가 도착할 때까지 편히 기다리시오.', `FemaleText_loc4`='我必须承认，藏宝海湾有南海最好的杂烩蚌肉。哦，对烹饪不感兴趣？那么欢迎你投宿少女之爱号——在东部王国和卡利姆多之间航行的最好的客船。很快她将驰往棘齿城，在她到达之前好好享受吧。', `FemaleText_loc5`='我必須承認，藏寶海灣有南海最好的蚌肉雜燴。哦，對烹飪不感興趣?那麼歡迎你投宿少女之愛號─在東部王國和卡林多之間航行的最好的客船。很快她將馳往棘齒城，在她到達之前好好享受吧。', `FemaleText_loc7`='Tengo que decir que la Bahía del Botín tiene la mejor sopa de almejas que se pueda probar en los Mares del Sur. Ah, ¿no te interesa la cocina? Pues deja que sea el primero en darte la bienvenida al atracadero de La Fantasía de la Doncella, el mejor barco de pasajeros que hay para navegar entre los Reinos del Este y Kalimdor. Pronto volverá para realizar otro viaje a Trinquete, así que ponte cómodo hasta que llegue.' WHERE `ID`=4960;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자다!!', `MaleText_loc4`='入侵者！！', `MaleText_loc5`='入侵者!!', `MaleText_loc7`='¡¡Intrusos!!' WHERE `ID`=4961;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자다!! 뭐하고 있는 거냐?', `MaleText_loc4`='你在干什么？你这个入侵者！！', `MaleText_loc5`='你在幹什麼?你這個入侵者!!', `MaleText_loc7`='¿Qué estáis haciendo? ¡¡Intrusos!!' WHERE `ID`=4962;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거라면 어떤 배보다도 더 빨리 언더시티에 갈 수 있습니다. 경치는 또 숨이 막힐 정도로 아름답지요. 숨 얘기가 나와서 말인데, 비행선에서는 금연입니다. 화염 마법도 금지고... 사고라도 나면 헬륨 폭탄이 터지는 것에 비길 바가 아니니까요.', `MaleText_loc4`='氦弹点火和爆炸的过程是没有危险的。跟船只相比，这宝贝能更为快速安全地将你送达幽暗城，途中的景色真是惊心动魄。说到这，在地精飞艇上是不允许吸烟的，旅途中也不允许使用火的法术。', `MaleText_loc5`='氦彈點火和爆炸的過程是沒有危險的。跟船隻相比，這寶貝能更為快速安全地將你送達幽暗城，途中的景色真是驚心動魄。說到這，在地精飛艇上是不允許吸煙的，旅途中也不允許使用火的法術。', `MaleText_loc7`='Por supuesto que no existe el peligro de que todo arda en llamas y explote como una gran bomba de helio. Esta belleza te llevará hasta Entrañas más rápido y más seguro que cualquier otro barco. Además, el paisaje corta la respiración. Hablando de respiración, no está permitido fumar a bordo durante el viaje en zepelín y los encantamientos de fuego están prohibidos durante el trayecto.', `FemaleText_loc1`='이거라면 어떤 배보다도 더 빨리 언더시티에 갈 수 있답니다. 경치는 또 숨이 막힐 정도로 아름답지요. 숨 얘기가 나와서 말인데, 비행선에서는 금연이에요. 화염 마법도 금지고... 사고라도 나면 헬륨 폭탄이 터지는 것에 비길 바가 아니니까요.', `FemaleText_loc4`='氦弹点火和爆炸的过程是没有危险的。跟船只相比，这宝贝能更为快速安全地将你送达幽暗城，途中的景色真是惊心动魄。说到这，在地精飞艇上是不允许吸烟的，旅途中也不允许使用火的法术。', `FemaleText_loc5`='氦彈點火和爆炸的過程是沒有危險的。跟船隻相比，這寶貝能更為快速安全地將你送達幽暗城，途中的景色真是驚心動魄。說到這，在地精飛艇上是不允許吸煙的，旅途中也不允許使用火的法術。', `FemaleText_loc7`='Por supuesto que no existe el peligro de que todo arda en llamas y explote como una gran bomba de helio. Esta belleza te llevará hasta Entrañas más rápido y más seguro que cualquier otro barco. Además, el paisaje corta la respiración. Hablando de respiración, no está permitido fumar a bordo del zepelín.' WHERE `ID`=4963;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하신가! 바로 당신 같은 이를 찾고 있었지. 자, 앉아서 잘 들어보라고. 우리 둘 다 떼부자가 될 수 있는 계획이 있으니까 말이야!', `MaleText_loc4`='你好！你正是我要找的人。坐下来听我说，我有个可以让咱们两个都发家致富的计划！', `MaleText_loc5`='你好!你正是我要找的人。坐下來聽我說，我有個可以讓咱們兩個都發家致富的計畫!', `MaleText_loc7`='¡Hola! Eres exactamente la persona que estaba buscando. ¡Siéntate y escucha, porque tengo un plan que nos hará ricos a los dos!' WHERE `ID`=4964;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희 형이 이 무역로를 통해 돈을 많이 벌 수 있다는 말은 해 줬지만, 여기에서 살아야 한다는 얘기는 안 해 줬답니다. 비행선을 타고 행여 여기 다시 들르면 먹을 걸 좀 가져다주지 않으시겠습니까? 오그리마에서 아주 먹음직한 고기를 판다는데 한번 맛보고 싶거든요.', `MaleText_loc4`='我兄弟说我们能在这条商贸路线上赚到更多的钱的，但是他没告诉我要独自应对。要是你乘坐地精飞艇沿着这条路返回的话，你能帮我带点吃的吗？在奥格瑞玛，有人出售最好的肉类，当然我还能以那些苟延残喘的动物为食的。', `MaleText_loc5`='我兄弟說我們能在這條商貿路線上賺到更多的錢的，但是他沒告訴我要獨自應對。要是你乘坐地精飛艇沿著這條路返回的話，你能幫我帶點吃的嗎?在奧格瑪，有人出售最好的肉類，當然我還能以那些苟延殘喘的動物為食的。', `MaleText_loc7`='Mi hermano dijo que podíamos hacer mucho dinero con esta ruta comercial, pero no me dijo que yo sería el que viviría a este lado. Si vuelves por este camino en el zepelín, ¿podrías traerme algo de comer? Ellos venden algunas de las mejores piezas de carne de todo Orgrimmar y estoy seguro de que podría aprovechar algo que no lleve muerto varias semanas.', `FemaleText_loc1`='저희 오빠가 이 무역로를 통해 돈을 많이 벌 수 있다는 말은 해 줬지만, 여기에서 살아야 한다는 얘기는 안 해 줬거든요. 비행선을 타고 행여 여기 다시 들르면 먹을 걸 좀 가져다주지 않겠어요? 오그리마에서 아주 먹음직한 고기를 판다는데 한번 맛보고 싶거든요.', `FemaleText_loc4`='我兄弟说我们能在这条商贸路线上赚到更多的钱的，但是他没告诉我要独自应对。要是你乘坐地精飞艇沿着这条路返回的话，你能帮我带点吃的吗？在奥格瑞玛，有人出售最好的肉类，当然我还能以那些苟延残喘的动物为食的。', `FemaleText_loc5`='我兄弟說我們能在這條商貿路線上賺到更多的錢的，但是他沒告訴我要獨自應對。要是你乘坐地精飛艇沿著這條路返回的話，你能幫我帶點吃的嗎?在奧格瑪，有人出售最好的肉類，當然我還能以那些苟延殘喘的動物為食的。', `FemaleText_loc7`='Mi hermano dijo que podíamos hacer mucho dinero con esta ruta comercial, pero no me dijo que yo sería el que viviría a este lado. Si vuelves por este camino en el zepelín, ¿podrías traerme algo de comer? Ellos venden algunas de las mejores piezas de carne de todo Orgrimmar y estoy seguro de que podría aprovechar algo que no lleve muerto varias semanas.' WHERE `ID`=4965;
