UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 붉은꽃잎덩굴손 씨눈에 아지랑이를 더합니다.', `MaleText_loc4`='%s把薄雾喷到了血瓣花的萌芽上。', `MaleText_loc5`='%s把薄霧噴到了血瓣花苗上。', `MaleText_loc7`='%s agrega la niebla a los brotes Sangrepétalo.' WHERE `ID`=4967;
