UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 잡초들이 도망가는 것을 지켜보며 웃습니다.', `MaleText_loc4`='%s看到那些家伙仓惶逃走，大笑起来。', `MaleText_loc5`='%s看到那些害蟲逃走，大笑了起來。', `MaleText_loc7`='%s ríe mientras ve cómo huyen las ratas.' WHERE `ID`=4969;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽어야 할 시간이군! 덤벼 볼 테냐!', `MaleText_loc4`='到出发的时间了！来吧！<替换这个>', `MaleText_loc5`='到出發的時間了!來吧!<替換這個>', `MaleText_loc7`='¡Es HORA DE IRSE! ¡Venid a por un poco de esto! <sustituye esto>' WHERE `ID`=4970;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너의 가족들이 안부를 전하더군, 리블리. 그리고 너의 목숨을 원했어!', `MaleText_loc4`='你的族人问了声好，雷布里。他们想要你彻底失败！', `MaleText_loc5`='你的族人問了聲好，雷布里。他們想要你的腦袋!', `MaleText_loc7`='Tu familia te saluda, Ribbly. ¡Y quieren tu cabeza!', `FemaleText_loc1`='너의 가족들이 안부를 전하더군, 리블리. 그리고 너의 목숨을 원했어!', `FemaleText_loc4`='你的族人问了声好，雷布里。他们想要你彻底失败！', `FemaleText_loc5`='你的族人問了聲好，雷布里。他們想要你的腦袋!', `FemaleText_loc7`='Tu familia te saluda, Ribbly. ¡Y quieren tu cabeza!' WHERE `ID`=4971;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 아무짝에도 쓸모가 없는 녀석이야, 리블리. 버릇없는 행동의 대가를 치를 때다!', `MaleText_loc4`='你干什么都不成，雷布里。现在该为你的邪恶付出代价了！', `MaleText_loc5`='你這個廢物，雷布里。現在該為你的邪惡付出代價了!', `MaleText_loc7`='No sirves para nada, Ribbly. ¡Ha llegado la hora de que pagues por tu perversidad!', `FemaleText_loc1`='넌 아무짝에도 쓸모가 없는 녀석이야, 리블리. 버릇없는 행동의 대가를 치를 때다!', `FemaleText_loc4`='你干什么都不成，雷布里。现在该为你的邪恶付出代价了！', `FemaleText_loc5`='你這個廢物，雷布里。現在該為你的邪惡付出代價了!', `FemaleText_loc7`='No sirves para nada, Ribbly. ¡Ha llegado la hora de que pagues por tu perversidad!' WHERE `ID`=4972;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싫어! 비키란 말이야! 도와줘!!', `MaleText_loc4`='不！滚开！帮帮我！！', `MaleText_loc5`='不!滾開!幫幫我!!', `MaleText_loc7`='¡No! ¡Apartaos de mí! ¡¡¡Socorro!!!' WHERE `ID`=4973;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='붉은협곡 광부조합에서 북동쪽에 있는 명예의 골짜기에서 노그의 작업소를 찾게.', `MaleText_loc4`='去红石谷矿业工会东北部的荣誉谷找诺格机械店。', `MaleText_loc5`='去紅石谷礦業工會東北部的榮譽谷找諾格機械店。', `MaleText_loc7`='Busca el Rincón de la Maquinaria de Nogg en el Valle del Honor, al noreste de la minería El Cañón Rojo.', `FemaleText_loc1`='붉은협곡 광부조합에서 북동쪽에 있는 명예의 골짜기에서 노그의 작업소를 찾게.', `FemaleText_loc4`='去红石谷矿业工会东北部的荣誉谷找诺格机械店。', `FemaleText_loc5`='去紅石谷礦業工會東北部的榮譽谷找諾格機械店。', `FemaleText_loc7`='Busca el Rincón de la Maquinaria de Nogg en el Valle del Honor, al noreste de la minería El Cañón Rojo.' WHERE `ID`=4974;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장난감 가게 같은 걸 운영하는 고블린말이군. 명예의 골짜기로 가 보게.', `MaleText_loc4`='你会在荣誉谷找到那个地精和他的玩具商店的。', `MaleText_loc5`='你會在榮譽谷找到那個哥布林和他的玩具商店的。', `MaleText_loc7`='Encontrarás a ese goblin y su tienda de juguetes en el Valle del Honor.', `FemaleText_loc1`='장난감 가게 같은 걸 운영하는 고블린말이군. 명예의 골짜기로 가 보게.', `FemaleText_loc4`='你会在荣誉谷找到那个地精和他的玩具商店的。', `FemaleText_loc5`='你會在榮譽谷找到那個哥布林和他的玩具商店的。', `FemaleText_loc7`='Encontrarás a ese goblin y su tienda de juguetes en el Valle del Honor.' WHERE `ID`=4975;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기계공학', `MaleText_loc4`='工程学', `MaleText_loc5`='工程學', `MaleText_loc7`='Ingeniería', `FemaleText_loc1`='기계공학', `FemaleText_loc4`='工程学', `FemaleText_loc5`='工程學', `FemaleText_loc7`='Ingeniería' WHERE `ID`=4976;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='현명한 선택을 할 수 있도록 도와주십시오.', `MaleText_loc4`='帮我挑选一下吧。', `MaleText_loc5`='幫我挑選一下吧。', `MaleText_loc7`='Ayúdame a elegir sabiamente.', `FemaleText_loc1`='현명한 선택을 할 수 있도록 도와주십시오.', `FemaleText_loc4`='帮我挑选一下吧。', `FemaleText_loc5`='幫我挑選一下吧。', `FemaleText_loc7`='Ayúdame a elegir sabiamente.' WHERE `ID`=4977;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 뛰어난 능력을 지닌 마법사요. 새로운 것을 배우고, 그 능력을 유지하는 데 있어 정신력과 기억력이 어떤 관련이 있는지 연구하며 하루하루를 보내왔었지. 한밤중에 내 도움이 필요하다는 엄청난 목소리를 듣지 않았다면 지금 이 순간에도 연구를 하고 있었을 거요. 나는 아주 잠깐만 여기에 머물면서, 당신만의 재능을 갈고 닦을 수 있도록 여러 가지를 알려줄 것이오. 아무런 대가도 없이 말이오. 그러고는 다시 떠날 것이니, 당신은 자신의 선택에 신중하고 충실해야 할 것이오.', `MaleText_loc4`='我是一名拥有强大力量的法师，一直以来，我都潜心研究精神和记忆，这有利于学习知识和保持学会的知识。要不是我在夜晚听到一个巨大的声音说需要我的帮助，我的研究一定已经完成啦。我只在这儿呆一会儿，免费为你重修天赋。接着我就得离开，而你也要选择自己的道路。', `MaleText_loc5`='我是一名擁有強大力量的法師，一直以來，我都潛心研究精神和記憶，這有利於學習知識和保持學會的知識。要不是我在夜晚聽到一個巨大的聲音說需要我的幫助，我的研究一定已經完成啦。我只在這兒待一會兒，免費為你重修天賦。接著我就得離開，而你也要選擇自己的道路。', `MaleText_loc7`='Soy un mago con grandes poderes. He pasado días estudiando la mente y la memoria en aspectos relacionados con el aprendizaje y la retención de facultades aprendidas. Incluso ahora estaría perfeccionando mis conocimientos, de no ser por las voces que escuché por la noche, diciéndome que requerían de mis servicios. Solo estaré aquí durante poco tiempo, ofreciendo mi capacidad para pulir tus talentos sin cobrar nada a cambio. Pronto volveré a marcharme y, una vez más, tendrás problemas con las decisiones que tomes.', `FemaleText_loc1`='나는 뛰어난 능력을 지닌 마법사요. 새로운 것을 배우고, 그 능력을 유지하는 데 있어 정신력과 기억력이 어떤 관련이 있는지 연구하며 하루하루를 보내왔었지. 한밤중에 내 도움이 필요하다는 엄청난 목소리를 듣지 않았다면 지금 이 순간에도 연구를 하고 있었을 거요. 나는 아주 잠깐만 여기에 머물면서, 당신만의 재능을 갈고 닦을 수 있도록 여러 가지를 알려줄 것이오. 아무런 대가도 없이 말이오. 그러고는 다시 떠날 것이니, 당신은 자신의 선택에 신중하고 충실해야 할 것이오.', `FemaleText_loc4`='我是一名拥有强大力量的法师，一直以来，我都潜心研究精神和记忆，这有利于学习知识和保持学会的知识。要不是我在夜晚听到一个巨大的声音说需要我的帮助，我的研究一定已经完成啦。我只在这儿呆一会儿，免费为你重修天赋。接着我就得离开，而你也要选择自己的道路。', `FemaleText_loc5`='我是一名擁有強大力量的法師，一直以來，我都潛心研究精神和記憶，這有利於學習知識和保持學會的知識。要不是我在夜晚聽到一個巨大的聲音說需要我的幫助，我的研究一定已經完成啦。我只在這兒待一會兒，免費為你重修天賦。接著我就得離開，而你也要選擇自己的道路。', `FemaleText_loc7`='Soy una maga con grandes poderes. He pasado días estudiando la mente y la memoria en aspectos relacionados con el aprendizaje y la retención de facultades aprendidas. Incluso ahora estaría perfeccionando mis conocimientos, de no ser por las voces que escuché por la noche, diciéndome que requerían de mis servicios. Solo estaré aquí durante poco tiempo, ofreciendo mi capacidad para pulir tus talentos sin cobrar nada a cambio. Pronto volveré a marcharme y, una vez más, tendrás problemas con las decisiones que tomes.' WHERE `ID`=4978;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='알겠어요!', `FemaleText_loc4`='没问题！', `FemaleText_loc5`='沒問題!', `FemaleText_loc7`='¡Lo has conseguido!' WHERE `ID`=4979;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='곧 가겠어요!', `FemaleText_loc4`='马上就来了！', `FemaleText_loc5`='馬上就來了!', `FemaleText_loc7`='¡Ahora mismo voy!' WHERE `ID`=4980;
