UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 나그마라! 검은무쇠 맥주 한 잔 갖다 주지 않겠어?', `MaleText_loc4`='嘿，娜玛拉！来一杯黑铁啤酒怎么样？', `MaleText_loc5`='嘿，娜瑪拉!來一杯黑鐵麥芽酒怎麼樣?', `MaleText_loc7`='¡Eh, Nagmara! ¿Qué te parece una jarra de cerveza Hierro Negro?', `FemaleText_loc1`='이봐, 나그마라! 검은무쇠 맥주 한 잔 갖다 주지 않겠어?', `FemaleText_loc4`='嘿，娜玛拉！来一杯黑铁啤酒怎么样？', `FemaleText_loc5`='嘿，娜瑪拉!來一杯黑鐵麥芽酒怎麼樣?', `FemaleText_loc7`='¡Eh, Nagmara! ¿Qué te parece una jarra de cerveza Hierro Negro?' WHERE `ID`=4984;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나그마라! 양고기는 아직 남았나?', `MaleText_loc4`='娜玛拉！还有羊肉吗？', `MaleText_loc5`='娜瑪拉!還有羊肉嗎?', `MaleText_loc7`='¡Nagmara! ¿Te queda algo de cordero?', `FemaleText_loc1`='나그마라! 양고기는 아직 남았나?', `FemaleText_loc4`='娜玛拉！还有羊肉吗？', `FemaleText_loc5`='娜瑪拉!還有羊肉嗎?', `FemaleText_loc7`='¡Nagmara! ¿Te queda algo de cordero?' WHERE `ID`=4985;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 플러거한테 맥주가 더 필요하다고 전해주게. 아무리 마셔도 모자라다니까!', `MaleText_loc4`='小姐，请你告诉普拉格，我想要更多的啤酒。这些远远不够！', `MaleText_loc5`='小姐，請你告訴普拉格，我想要更多的麥芽酒。這些遠遠不夠!', `MaleText_loc7`='Coima, dile a Plugger que quiero más cerveza de esta. ¡Me encanta!', `FemaleText_loc1`='이봐, 플러거한테 맥주가 더 필요하다고 전해주게. 아무리 마셔도 모자라다니까!', `FemaleText_loc4`='小姐，请你告诉普拉格，我想要更多的啤酒。这些远远不够！', `FemaleText_loc5`='小姐，請你告訴普拉格，我想要更多的麥芽酒。這些遠遠不夠!', `FemaleText_loc7`='Coima, dile a Plugger que quiero más cerveza de esta. ¡Me encanta!' WHERE `ID`=4986;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 나그마라. 그거 한 조각 나눠주는 게 어때...', `MaleText_loc4`='嘿，我说，娜玛拉，你能切给我一块吗……', `MaleText_loc5`='嘿，我說，納格，你能切給我一塊嗎...', `MaleText_loc7`='Oye, Nag, qué tal si me cortas una rebanada de eso...', `FemaleText_loc1`='이봐, 나그마라. 그거 한 조각 나눠주는 게 어때...', `FemaleText_loc4`='嘿，我说，娜玛拉，你能切给我一块吗……', `FemaleText_loc5`='嘿，我說，納格，你能切給我一塊嗎...', `FemaleText_loc7`='Oye, Nag, qué tal si me cortas una rebanada de eso...' WHERE `ID`=4987;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요리를 배우고 싶습니다.', `MaleText_loc4`='我想进行烹饪训练。', `MaleText_loc5`='我想進行烹飪訓練。', `MaleText_loc7`='Me gustaría recibir instrucción en el arte de cocinar.', `FemaleText_loc1`='요리를 배우고 싶습니다.', `FemaleText_loc4`='我想进行烹饪训练。', `FemaleText_loc5`='我想進行烹飪訓練。', `FemaleText_loc7`='Me gustaría recibir instrucción en el arte de cocinar.' WHERE `ID`=4988;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하시오, $n. 요리에 대해 배우고 싶거든 언제든 날 찾아오시오.', `MaleText_loc4`='你好，$n。如果你想学习烹饪技巧的话，可以随时来找我。', `MaleText_loc5`='你好，$n。如果你想學習烹飪技巧的話，可以隨時來找我。', `MaleText_loc7`='Hola, $n. Si te interesa aprender algún truco de cocina, ven a verme cuando quieras.' WHERE `ID`=4989;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='<여군주 프레스톨이 노려봅니다.>', `FemaleText_loc4`='<普瑞斯托女士怒视着你。>', `FemaleText_loc5`='<普瑞斯托女士怒視著你。>', `FemaleText_loc7`='<Lady Prestor te mira.>' WHERE `ID`=4990;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무례함을 용서해주십시오, 프레스톨 님. 하지만 볼바르 님께서 당신의 조언을 구하라 하셨습니다.', `MaleText_loc4`='普瑞斯托女士，请原谅我的冒昧，但是伯瓦尔·弗塔根公爵让我来寻求您的建议。', `MaleText_loc5`='普瑞斯托女士，請原諒我的冒昧，但是大領主伯瓦爾·弗塔根讓我來尋求您的建議。', `MaleText_loc7`='Perdón por la intromisión, Lady Prestor, pero el alto señor Bolvar me sugirió que pidiera su consejo.', `FemaleText_loc1`='무례함을 용서해주십시오, 프레스톨 님. 하지만 볼바르 님께서 당신의 조언을 구하라 하셨습니다.', `FemaleText_loc4`='普瑞斯托女士，请原谅我的冒昧，但是伯瓦尔·弗塔根公爵让我来寻求您的建议。', `FemaleText_loc5`='普瑞斯托女士，請原諒我的冒昧，但是大領主伯瓦爾·弗塔根讓我來尋求您的建議。', `FemaleText_loc7`='Perdón por la intromisión, Lady Prestor, pero el alto señor Bolvar me sugirió que pidiera su consejo.' WHERE `ID`=4991;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='난 바로 그대 곁에 서 있었습니다, 어리석기는... 그대가 찾는 게 뭔지 알고 있단 말입니다.', `FemaleText_loc4`='我就站在你旁边，笨蛋。我知道你在找什么。', `FemaleText_loc5`='我就站在你旁邊，笨蛋。我知道你在找什麼。', `FemaleText_loc7`='Estaba justo al lado tuyo, imbécil. Sé lo que buscas.' WHERE `ID`=4992;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용서하십시오, 프레스톨 님.', `MaleText_loc4`='很抱歉，普瑞斯托女士。', `MaleText_loc5`='很抱歉，普瑞斯托女士。', `MaleText_loc7`='Discúlpame, Lady Prestor.', `FemaleText_loc1`='용서하십시오, 프레스톨 님.', `FemaleText_loc4`='很抱歉，普瑞斯托女士。', `FemaleText_loc5`='很抱歉，普瑞斯托女士。', `FemaleText_loc7`='Discúlpame, Lady Prestor.' WHERE `ID`=4993;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그댄 망상에 빠진 집정관과 대다수가 더위로 고생하고 있을 하층민 야영지를 달래기 위해 우리의 전체적인 방어력을 낮추려는 것이겠지요.', `FemaleText_loc4`='你是说为了满足一个妄想狂的地方官和一群没准正在遭受中暑之苦的乌合之众的愿望，我们就得把世界各地的部队都调回来，然后给他派过去吗？', `FemaleText_loc5`='你是說為了滿足一個妄想狂的地方官和一群沒准正在遭受中暑之苦的烏合之眾的願望，我們就得把世界各地的部隊都調回來，然後給他派過去嗎?', `FemaleText_loc7`='Intentas reducir nuestras defensas globales para apaciguar a un magistrado paranoico y un campamento de gentuza que probablemente está padeciendo insolación.' WHERE `ID`=4994;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='송구스러운 말씀입니다만 결코 그런 의도가 아니었습니다, 프레스톨 님.', `MaleText_loc4`='普瑞斯托女士，请你原谅。这并非我的本意。', `MaleText_loc5`='普瑞斯托女士，請你原諒。這並非我的本意。', `MaleText_loc7`='Pido que me disculpes, Lady Prestor. Esa no era mi intención.', `FemaleText_loc1`='송구스러운 말씀입니다만 결코 그런 의도가 아니었습니다, 프레스톨 님.', `FemaleText_loc4`='普瑞斯托女士，请你原谅。这并非我的本意。', `FemaleText_loc5`='普瑞斯托女士，請你原諒。這並非我的本意。', `FemaleText_loc7`='Pido que me disculpes, Lady Prestor. Esa no era mi intención.' WHERE `ID`=4995;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당연히 아니겠지요. 그대와 같은 "모험가"라는 자들은 백성과 왕실 사이에 벌어지는 정치 드라마의 피해자인 경우가 많으니까 말입니다.$B$B내가 해 줄 말이라곤 다른 걸 찾아보라는 것입니다. 더 정확히 말해서 직업을 바꾸어보라는 겁니다.$B$B이 세계에는 지금도 영웅이 충분하답니다.', `FemaleText_loc4`='当然不是，亲爱的$g小伙子:姑娘;。你这种“冒险者”类型的$c经常成为政治的牺牲品，被政治家玩弄于股掌之间而毫无察觉。$B$B我给你的建议，就是去做一些更加具体的事情：找份新工作。$B$B这个世界已经有太多的英雄了。', `FemaleText_loc5`='當然不是，親愛的$g小夥子:姑娘;。你這種「冒險者」類型的$c經常成為政治的犧牲品，被政治家玩弄於股掌之間而毫無察覺。$B$B我給你的建議，就是去做一些更加具體的事情:找份新工作。$B$B這個世界已經有太多的英雄了。', `FemaleText_loc7`='Por supuesto que no, $gchico:chica;. Ustedes, los aventureros, a menudo sois víctimas de las circunstancias; sujetos al drama político que suele desarrollarse entre los ciudadanos y la realeza.$B$BMi consejo es que busques algo más, específicamente, una nueva profesión.$B$BEste mundo ya tiene suficientes héroes.' WHERE `ID`=4996;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠, 시간을 내주셔서 감사합니다, 프레스톨 님.', `MaleText_loc4`='普瑞斯托女士您费时了，谢谢你。', `MaleText_loc5`='普瑞斯托女士您費時了，謝謝你。', `MaleText_loc7`='Gracias por tu tiempo, Lady Prestor.', `FemaleText_loc1`='흠, 시간을 내주셔서 감사합니다, 프레스톨 님.', `FemaleText_loc4`='普瑞斯托女士您费时了，谢谢你。', `FemaleText_loc5`='普瑞斯托女士您費時了，謝謝你。', `FemaleText_loc7`='Gracias por tu tiempo, Lady Prestor.' WHERE `ID`=4997;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 굉장히 어지러워 합니다!', `MaleText_loc4`='%s变得晕乎乎的！', `MaleText_loc5`='%s感到頭昏眼花!', `MaleText_loc7`='¡%s experimenta fuertes mareos!', `FemaleText_loc1`='%s|1이;가; 굉장히 어지러워 합니다!', `FemaleText_loc4`='%s变得晕乎乎的！', `FemaleText_loc5`='%s感到頭昏眼花!', `FemaleText_loc7`='¡%s experimenta fuertes mareos!' WHERE `ID`=4998;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 술에 만취한 나머지 어둠의 화살을 잘못 시전합니다!', `MaleText_loc4`='%s喝醉了酒，射偏了一发暗影箭！', `MaleText_loc5`='%s喝醉了酒，射偏了一發暗影箭!', `MaleText_loc7`='¡En su ebriedad, %s lanza una descarga de las Sombras!', `FemaleText_loc1`='%s|1이;가; 술에 만취한 나머지 어둠의 화살을 잘못 시전합니다!', `FemaleText_loc4`='%s喝醉了酒，射偏了一发暗影箭！', `FemaleText_loc5`='%s喝醉了酒，射偏了一發暗影箭!', `FemaleText_loc7`='¡En su ebriedad, %s lanza una descarga de las Sombras!' WHERE `ID`=4999;
