UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 연인에게 입을 맞춥니다.', `FemaleText_loc4`='%s吻着她的情人。', `FemaleText_loc5`='%s吻她的情人。', `FemaleText_loc7`='%s besa a su amante.' WHERE `ID`=5002;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 지배인 나그마라에게 입을 맞춥니다.', `MaleText_loc4`='%s亲吻着娜玛拉小姐', `MaleText_loc5`='%s親吻娜瑪拉小姐', `MaleText_loc7`='%s besa a la coima Nagmara.' WHERE `ID`=5003;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$r|1이여;여;, 이 저주받은 숲을 빠져나가도록 부디 도와주게.', `MaleText_loc4`='请帮助我穿越这片被诅咒的森林，$r。', `MaleText_loc5`='請幫助我到達梣谷，在那兒，我的靈魂才能得到最終的安息，$r。', `MaleText_loc7`='Por favor, ayúdame a atravesar este bosque maldito, $r.' WHERE `ID`=5004;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악령숲에 퍼진 타락이 숲에 사는 모든 생물들에게 사악한 영향을 미치고 있네, $n. 부디 몸조심 하길...', `MaleText_loc4`='这个地区的堕落使得森林中的所有生物都受到了影响，$n。请做好战斗准备。', `MaleText_loc5`='這個地區的墮落使得費伍德森林中的所有生物都受到了感染，$n。請做好戰鬥準備。', `MaleText_loc7`='La corrupción de la energía vil ha tocado a las criaturas de Frondavil, $n. Por favor, permanece en guardia.' WHERE `ID`=5005;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일이지? *딸꾹*', `MaleText_loc4`='你想要什么？*嗝儿*', `MaleText_loc5`='你想要什麼?*嗝兒*', `MaleText_loc7`='¿Qué vas a querer? *hip*' WHERE `ID`=5006;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공무 때문에 왔습니다, 존. 치안대장 윈저에 대한 정보가 필요한데, 마지막으로 그를 본 게 언제인지 말씀해주십시오.', `MaleText_loc4`='约翰，我有公务在身。我需要一切有关温德索尔元帅的信息。你最后一次见他是什么时候？', `MaleText_loc5`='約翰，我有公務在身。我需要一切有關溫德索爾元帥的資訊。你最後一次見他是什麼時候?', `MaleText_loc7`='Asuntos oficiales, John. Necesito cierta información sobre el mariscal Windsor. Háblame de la última vez que lo viste.', `FemaleText_loc1`='공무 때문에 왔습니다, 존. 치안대장 윈저에 대한 정보가 필요한데, 마지막으로 그를 본 게 언제인지 말씀해주십시오.', `FemaleText_loc4`='约翰，我有公务在身。我需要一切有关温德索尔元帅的信息。你最后一次见他是什么时候？', `FemaleText_loc5`='約翰，我有公務在身。我需要一切有關溫德索爾元帥的資訊。你最後一次見他是什麼時候?', `FemaleText_loc7`='Asuntos oficiales, John. Necesito cierta información sobre el mariscal Windsor. Háblame de la última vez que lo viste.' WHERE `ID`=5007;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한때는 동료였던 정령들과 숲의 친구들과 싸워야 한다는 사실이 너무나도 슬프군.', `MaleText_loc4`='我必须跟同族作战，这令我非常伤心。', `MaleText_loc5`='我必須跟同族作戰，這令我非常傷心。', `MaleText_loc7`='Tener que luchar contra los míos me entristece profundamente.' WHERE `ID`=5008;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그날따라 윈저 님은 완고했소. 그 정도도 아주 대단한 성과였지, 정말이오. 윈저 님께서는 계속 "뭔가 느낌이 좋지 않다"라고 말씀하셨는데 그 말이 맞아떨어진 거요!$B$B검은바위 산 중턱에 있을 때 끔찍한 짐승들에게 습격을 당한 거요. 그 짐승이란 물론 오크를 말하는 거요. 내 말에 집중 좀 해주겠소? 녀석들이 돌진해 오는데, 으르렁대는 소리와 쇠 부딪히는 소리 때문에 바람도 잠잠해질 지경이었다오.', `MaleText_loc4`='温德索尔那天特别爱跟人争吵——相信我，对温德索尔来说，那是一个有纪念意义的伟大成就。他一直在跟我说“感觉有些怪异”。他不是在开玩笑！$B$B当那些肮脏的野兽出击时，我们还在黑石山脉的中央。当然，我指的是兽人。你别分神，好吗？一时之间，叫喊声和铁器的敲击声四起。', `MaleText_loc5`='溫德索爾那天特別愛跟人爭吵─相信我，對溫德索爾來說，那是一個有紀念意義的偉大成就。他一直在跟我說「感覺有些怪異」。他不是在開玩笑!$B$B當那些骯髒的野獸出擊時，我們還在黑石山脈的中央。當然，我指的是獸人。你別分神，好嗎?一時之間，叫喊聲和鐵器的敲擊聲四起。', `MaleText_loc7`='Windsor estaba especialmente malhumorado ese día, y créeme, para Windsor eso es un logro increíble. Todo el tiempo estuvo diciéndome que ‘sentía que algo iba mal’. ¡Pues no estaba bromeando!$B$BEstábamos en medio de la Montaña Roca Negra, cuando unos asquerosos animales nos atacaron. Estoy hablando de los orcos, por supuesto. ¿Escúchame cuando te hablo, vale? Lo único que se oía eran gruñidos y el estruendo del acero cuando se abalanzaron sobre nosotros.' WHERE `ID`=5009;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래서 어떻게 됐나요?', `MaleText_loc4`='你干了些什么？', `MaleText_loc5`='你幹了些什麼?', `MaleText_loc7`='¿Entonces qué hicisteis?', `FemaleText_loc1`='그래서 어떻게 됐나요?', `FemaleText_loc4`='你干了些什么？', `FemaleText_loc5`='你幹了些什麼?', `FemaleText_loc7`='¿Entonces qué hicisteis?' WHERE `ID`=5010;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 그 더러운 오크 녀석들과 맞섰을 것 같소? 나는 바보가 아니외다. 우리 아버지께서 늘 삼십육계 줄행랑이 최고라고 그러셨소. 난 아버지 말씀을 잘 알아들었던 거지.', `MaleText_loc4`='我单挑50个兽人？我可不是傻子，$n。我爸爸常说“卑鄙是卑鄙者的通行证”这类的话，我突然之间就明白了那是什么意思。', `MaleText_loc5`='我單挑50個獸人?我可不是傻子，$n。我爸爸常說「卑鄙是卑鄙者的通行證」這類的話，我突然之間就明白了那是什麼意思。', `MaleText_loc7`='¿Yo contra cincuenta orcos? No soy idiota, $n. Mi papá siempre me dijo ‘La incredulidad es la mejor parte del pastel’ o algo así, y ahí me di cuenta de lo que quería decir.' WHERE `ID`=5012;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알아들을 수 있게 설명해 주세요. 삼십육계 줄행랑이나 당신 아버지에게는 관심 없습니다.', `MaleText_loc4`='矮人，脑子放清醒点。我可没问你什么老爹啊名誉啊之类的事儿。', `MaleText_loc5`='矮人，腦子放清醒點。我可沒問你什麼老爹啊名譽啊之類的事兒。', `MaleText_loc7`='Empieza a tener sentido, enano. No quiero tener nada que ver con tu pastel, tu papá o con cualquier clase de incredulidad.', `FemaleText_loc1`='알아들을 수 있게 설명해 주세요. 삼십육계 줄행랑이나 당신 아버지에게는 관심 없습니다.', `FemaleText_loc4`='矮人，脑子放清醒点。我可没问你什么老爹啊名誉啊之类的事儿。', `FemaleText_loc5`='矮人，腦子放清醒點。我可沒問你什麼老爹啊名譽啊之類的事兒。', `FemaleText_loc7`='Empieza a tener sentido, enano. No quiero tener nada que ver con tu pastel, tu papá o con cualquier clase de incredulidad.' WHERE `ID`=5013;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 알겠소. 알았다고. 어쨌든 난 어두운 곳으로 살짝 빠져나갔지.$B$B윈저 님께서는 그렇지 않아도 화가 잔뜩 나있던 마당에, 그게 부아가 더욱 치미셨던 모양이오. 무쇠폭군을 마구 휘두르면서 오크 녀석들에게 미친 듯이 소리를 질러댔소.', `MaleText_loc4`='好吧，好吧。总之，从某种意义上说，我退到了一个不起眼的角落里。$B$B温德索尔似乎并不安分，看看他那歇斯底里的样儿。他拿着反对者战锤没命地乱挥，像发了疯一样对兽人咆哮着。', `MaleText_loc5`='好吧，好吧。總之，從某種意義上說，我退到了一個不起眼的角落裡。$B$B溫德索爾似乎並不安分，看看他那歇斯底里的樣兒。他拿著反對者戰錘沒命地亂揮，像發了瘋一樣對獸人咆哮著。', `MaleText_loc7`='Vale, está bien. Bueno, pues resulta que logré escabullirme en la oscuridad.$B$BEsto no le gustó demasiado a Windsor, tal y como estaba de enfadado. Empezó a hacer girar el viejo Ferromazo y a gritar como un loco a los orcos.' WHERE `ID`=5014;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무쇠폭군이라고요?', `MaleText_loc4`='反对者？', `MaleText_loc5`='反對者?', `MaleText_loc7`='¿Ferromazo?', `FemaleText_loc1`='무쇠폭군이라고요?', `FemaleText_loc4`='反对者？', `FemaleText_loc5`='反對者?', `FemaleText_loc7`='¿Ferromazo?' WHERE `ID`=5015;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇소. 오크를 무찌르는 전설적인 망치, 무쇠폭군이라고 들어본 적 없소? 그래. 그건 윈저 님의 망치였소. 프랑클론 포지라이트가 직접 윈저 님의 고조 할아버지를 위해 만들어줬다고 들었소. 프랑클론 포지라이트란 자는 돌다지 건축물이라던가... 구조물인가를 만들었지. 윈저 님께 듣기로는 프랑클론이 무쇠폭군과 똑같은 망치를 하나 더 가지고 있다고 하오. 이름이 뭐라던가... 무쇠지옥이라던가 그랬소.', `MaleText_loc4`='嗯。你从来没有听说过反对者？那把传说中的令兽人闻风丧胆的战锤？对，对，那是温德索尔的锤子。他说是弗兰克罗恩·铸铁亲自为他伟大的父亲制造了那把锤。弗兰克罗恩·铸铁，就是那个建造了巨石水坝之类的……黑铁矮人。他还说有一把与反对者一起铸造出来的战锤被弗兰克罗恩自己留着用了。他好像叫它铁胆之锤什么的。', `MaleText_loc5`='嗯。你從來沒有聽說過反對者?那把傳說中的令獸人聞風喪膽的戰錘?對，對，那是溫德索爾的錘子。他說是弗蘭克羅恩·鑄鐵親自為他偉大的父親製造了那把錘。弗蘭克羅恩·鑄鐵，就是那個建造了巨石水壩之類的...黑鐵矮人。他還說有一把與反對者一起鑄造出來的戰錘被弗蘭克羅恩自己留著用了。他好像叫它鐵膽之錘什麼的。', `MaleText_loc7`='Sí. ¿Nunca has oído hablar de Ferromazo? ¿El legendario martillo para matar orcos? Sí, pues sí, ese era el martillo del viejo Windsor. Me dijo que Franclorn Forjador en persona había fabricado ese martillo para su tatarabuelo. El famoso Franclorn Forjador: el Hierro Negro responsable de la arquitec... fraguapiedra, vamos eso. También dijo que el martillo tenía una réplica que Franclorn guardaba para sí. Creo que la llamó Ferrovil o algo así.' WHERE `ID`=5016;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='재미있는 얘기로군요. 계속 해주십시오, 존.', `MaleText_loc4`='真有趣……继续。', `MaleText_loc5`='真有趣...繼續，約翰。', `MaleText_loc7`='Interesante... continúa, John.', `FemaleText_loc1`='재미있는 얘기로군요. 계속 해주십시오, 존.', `FemaleText_loc4`='真有趣……继续。', `FemaleText_loc5`='真有趣...繼續，約翰。', `FemaleText_loc7`='Interesante... continúa, John.' WHERE `ID`=5017;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디까지 얘기했더라? 아, 맞아. 그 오크 녀석들이 윈저 님께 달려들었소. 윈저 님은 어땠느냐고? 그분은 그 자리에서 한 발짝도 움직이지 않았소. 오크 녀석들이 한꺼번에 열 놈씩이나 덤벼드는데도 홀로 우뚝 서 계시더군. 내 눈앞에 보이는 것이라고는 무쇠폭군에서 번득이는 불빛과 난무하는 선혈뿐이었소. 몇 시간, 아니 수일 동안 계속된 싸움으로 기억하오. 그랬을 거요. 기억도 잘 나지 않는군. 어쨌든, 결국에 가서 싸움은 멈췄지만...', `MaleText_loc4`='我说到哪里了？哦，兽人突袭了温德索尔，温德索尔呢？他是山崩于前而面不改色，从容应对。只见反对者击起冲天血光，鲜血四溅，持续了数个小时，没准是数天。我记不得了。但是最终，杀戮停止了。', `MaleText_loc5`='我說到哪裡了?哦，沒錯，獸人突襲了溫德索爾，這個溫德索爾呢，他動也不動。獸人朝他衝過去，大約有十來個。他卻昂然而立。只見反對者的光芒萬丈，和四濺的鮮血。戰鬥持續了數個小時，還是好幾天，我記不得。總之，最後，戰鬥停止了。', `MaleText_loc7`='¿Dónde estaba? Ah, sí, pues eso, los orcos corrieron hacia Windsor y Windsor no se movió ni un ápice. Permaneció erguido mientras le atacaban, diez a la vez. Lo único que podía ver era el resplandor de Ferromazo y mucha sangre. Y todo esto duró horas, quizás días. No lo recuerdo. Y, FINALMENTE, paró.' WHERE `ID`=5018;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇게 해서 윈저가 죽은 것이로군요...', `MaleText_loc4`='温德索尔就那样死了……', `MaleText_loc5`='溫德索爾就那樣死了...', `MaleText_loc7`='Entonces así es como murió Windsor...', `FemaleText_loc1`='그렇게 해서 윈저가 죽은 것이로군요...', `FemaleText_loc4`='温德索尔就那样死了……', `FemaleText_loc5`='溫德索爾就那樣死了...', `FemaleText_loc7`='Entonces así es como murió Windsor...' WHERE `ID`=5019;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽었다고? 무슨 소리요? 윈저 님의 실력은 역겨운 오크 녀석들에게 당할 만큼 형편없지는 않소. 텔사마 선지 소시지가 이 세상에서 제일 맛있는 음식이라는 사실만큼이나 분명하지. 그분은 그냥 그렇게 서 계셨소. 머리에서 발끝까지 오크의 피와 찢겨나간 살점을 겹겹이 뒤집어 쓴 채 말이오. 하지만 확실히 살아 계셨고 정말이지 엄청난 분노가 그분을 휩싸고 있었소.', `MaleText_loc4`='死了？你在开玩笑吧，$n？搞清楚，$n$g先生:小姐;！温德索尔绝对不会死于区区50个兽人之手，这就跟塞尔萨玛血肠是世界上最美味的食物一样不容置疑，他被兽人层层包围，但是他确实还活着……而且他非常非常愤怒。', `MaleText_loc5`='死了?你在開玩笑吧，$n?搞清楚，$n$g先生:小姐;$n!溫德索爾絕對不會死於區區50個獸人之手，這就跟塞爾薩瑪血腸是世界上最美味的食物一樣不容置疑，他被獸人層層包圍，但是他確實還活著...而且他非常非常憤怒。', `MaleText_loc7`='¿Morir? ¿Qué dices, $n? ¿Estás $gloco:loca;, $n? Discúlpame, pero Windsor jamás moriría por ser atacado por cincuenta orcos de nada. Tan seguro como estoy de que las morcillas de Thelsamar son la comida más sabrosa del mundo, ahí estaba él: cubierto de trozos de orco de pies a cabeza, sepultado por dieciocho capas de sangre de orco, pero estaba definitivamente vivo... y muy, pero que muy enfadado.' WHERE `ID`=5020;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇다면 어떻게 해서 죽은 겁니까?', `MaleText_loc4`='他是怎么死的？', `MaleText_loc5`='他是怎麼死的?', `MaleText_loc7`='¿Entonces cómo murió?', `FemaleText_loc1`='그렇다면 어떻게 해서 죽은 겁니까?', `FemaleText_loc4`='他是怎么死的？', `FemaleText_loc5`='他是怎麼死的?', `FemaleText_loc7`='¿Entonces cómo murió?' WHERE `ID`=5021;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 자꾸 죽었다고 하는 거요? 죽었다고 누가 그랬소? 난 그분이 죽었다고 말한 적 없소이다. 실종된 것뿐이오.$B$B우리는 분명 오크와 검은무쇠 드워프 간에 벌어진 전쟁에 휘말려 든 것 같았소. 그 망할 놈의 오크 녀석들은 일찌감치 당신도, 나도 이해하지 못할 덫을 놓고 사악한 함정을 파고 있었던 거요.', `MaleText_loc4`='你为什么总说他死了？谁告诉你他死了？我从来都没那么说过。$B$B他只是不知去向而已。$B$B你看，很明显，我们已经卷入了某个兽人对抗黑铁矮人的战争中。兽人是一群肮脏又卑劣的杂种，他们设计了一些圈套和你可能永远搞不明白的邪恶装置！', `MaleText_loc5`='你為什麼總說他死了?誰告訴你他死了?我從來都沒那麼說過。$B$B他只是不知去向而已。$B$B你看，很明顯，我們已經捲入了某個獸人對抗黑鐵矮人的戰爭中。獸人是一群骯髒又卑劣的雜種，他們設計了一些圈套和你可能永遠搞不明白的邪惡裝置!', `MaleText_loc7`='¿Por qué no dejas de decir que murió? ¿Quién te dijo que había muerto? Nunca dije que hubiera muerto.$B$BSimplemente desapareció, eso es todo.$B$BSabes, al parecer, de repente nos vimos en medio de una batalla entre grandes orcos y enanos Hierro Negro. Los orcos, bellacos asquerosos y miserables como son, se habían levantado pronto y estaban instalando unas trampas y otros artefactos diabólicos que tal vez no comprenderías.' WHERE `ID`=5022;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 알겠어. $n, 바로 이 길을 따라가면 잿빛 골짜기야.', `MaleText_loc4`='我现在能看到了，$n。灰谷就在前方！', `MaleText_loc5`='我現在能看到啦，$n。梣谷就在前方!', `MaleText_loc7`='Puedo sentirlo ahora, $n. Vallefresno está por este camino.' WHERE `ID`=5023;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아요. 그렇다면 대체 윈저는 어디에 있는 겁니까? 가만! 지금 당신 술 취했어요?', `MaleText_loc4`='好吧，他到底在哪儿？等一会！你喝醉了吗？', `MaleText_loc5`='好吧，他到底在哪兒?等一會!你喝醉了嗎?', `MaleText_loc7`='Vale, ¿entonces dónde diablos está? ¡Espera un momento! ¿Has bebido?', `FemaleText_loc1`='좋아요. 그렇다면 대체 윈저는 어디에 있는 겁니까? 가만! 지금 당신 술 취했어요?', `FemaleText_loc4`='好吧，他到底在哪儿？等一会！你喝醉了吗？', `FemaleText_loc5`='好吧，他到底在哪兒?等一會!你喝醉了嗎?', `FemaleText_loc7`='Vale, ¿entonces dónde diablos está? ¡Espera un momento! ¿Has bebido?' WHERE `ID`=5024;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하, 드워프들은 결코 술에 취하는 법이 없지. 그냥 조금 나른한 것뿐이오.$B$B어쨌든, 윈저님 말이오? 아마도 검은바위 나락 어딘가에 계실 거요. 당신과 같이 무지한 자에게는 검은무쇠 부족의 도시라고 해야 알아듣겠군.', `MaleText_loc4`='矮人可不会喝醉，$g先生:小姐;。我只是有些邋遢。$B$B无论如何，温德索尔？我猜他在黑石深渊的某处。对你们这些未受教化的家伙来说，就是一座黑铁矮人的城市。', `MaleText_loc5`='矮人可不會喝醉，$g先生:小姐;。我只是有些邋遢。$B$B無論如何，溫德索爾?我猜他在黑石深淵的某處。對你們這些未受教化的傢伙來說，就是一座黑鐵矮人的城市。', `MaleText_loc7`='Los enanos no se emborrachan, $gseñor:señorita;. Solo estoy un poco sentimental.$B$BBueno, ¿y Windsor? Creo que está en algún lugar de las Profundidades de Roca Negra. Vamos, la ciudad de Hierro Negro, para ustedes incultos.' WHERE `ID`=5025;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭔가... 이상한 기운이 감돌고 있군...', `MaleText_loc4`='我觉得……有些奇怪……', `MaleText_loc5`='我覺得...有些奇怪...', `MaleText_loc7`='Me siento... un poco extraño...' WHERE `ID`=5026;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도대체 어째서 윈저가 검은바위 나락에 있는 겁니까?', `MaleText_loc4`='他为什么在黑石深渊？', `MaleText_loc5`='他為什麼在黑石深淵?', `MaleText_loc7`='¿POR QUÉ está en las Profundidades de Roca Negra?', `FemaleText_loc1`='도대체 어째서 윈저가 검은바위 나락에 있는 겁니까?', `FemaleText_loc4`='他为什么在黑石深渊？', `FemaleText_loc5`='他為什麼在黑石深淵?', `FemaleText_loc7`='¿POR QUÉ está en las Profundidades de Roca Negra?' WHERE `ID`=5027;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 아, 거 참 서두르지 마시오! 방금 얘기하려던 참이었단 말이지!$B$B그렇게 그분이 오크 핏덩어리를 뒤집어 쓰고 서 있는데 누군가 나타났소...$B$B바로, 검은무쇠 부족이었지! 내 얘기를 듣기는 한 거요?$B$B뭐, 어쨌든 검은무쇠 녀석들은 검은바위 부족보다 지략이 좀 뛰어난 편이오. 정렬이 잘 맞춰진 300명의 부대가 몰려왔지. *딸꾹* 실례...', `MaleText_loc4`='放慢速度！就快接近了！$B$B他在那儿，全身血肉模糊，连内脏都流出来了，是谁把他弄成这样的？$B$B黑铁矮人！你记得我说过的话吗？？$B$B嗯，黑铁矮人比黑石兽人更为狡猾。他们是有备而来的。人数有300之多……*嗝尔*。', `MaleText_loc5`='放慢速度!就快接近了!$B$B他在那兒，全身血肉模糊，連內臟都流出來了，是誰把他弄成這樣的?$B$B黑鐵矮人!你記得我說過的話嗎??$B$B嗯，黑鐵矮人比黑石獸人更為狡猾。他們是有備而來的。人數有300之多...*嗝爾*。', `MaleText_loc7`='¡Despacio! ¡Estaba llegando ahí!$B$BY ahí estaba él, alto y erguido, embadurnado en sangre y con las tripas colgando cuando, ¿quién aparece?$B$B¡Los Hierro Negro! ¿¿Pero no has oído nada de lo que he dicho??$B$BBueno, los Hierro Negro son algo más astutos que esos orcos Roca Negra. Vinieron preparados. Y, por preparados, me refiero a que había unos 300... *hip* perdón.' WHERE `ID`=5028;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 내 모습이 바뀐 것이 보이는가? 영혼의 진정한 힘이 내게 되돌아오고 있어... 숲을 쥐고 흔들던 저주가 마침내 나를 떠나고 있어.', `MaleText_loc4`='$n，我的体形改变了！我的灵魂力量正在回到我的体内……这座森林的诅咒正在从我身上消失……', `MaleText_loc5`='$n，我的體形改變了!我的靈魂力量正在回到我的體內...', `MaleText_loc7`='¡$n, mi forma ha cambiado! La verdadera fuerza de mi espíritu ha vuelto a mí... La maldición del bosque me está abandonando.' WHERE `ID`=5029;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='300명이라고요? 검은무쇠 녀석들이 윈저를 죽이고 검은바위 나락으로 끌고 간 겁니까?', `MaleText_loc4`='300？那么说黑铁矮人杀死了他，并把他拖到了深渊里？', `MaleText_loc5`='300?那麼說黑鐵矮人殺死了他，並把他拖到了深淵裡?', `MaleText_loc7`='¿300? ¿Así que los Hierro Negro lo mataron y lo arrojaron a las Profundidades?', `FemaleText_loc1`='300명이라고요? 검은무쇠 녀석들이 윈저를 죽이고 검은바위 나락으로 끌고 간 겁니까?', `FemaleText_loc4`='300？那么说黑铁矮人杀死了他，并把他拖到了深渊里？', `FemaleText_loc5`='300?那麼說黑鐵矮人殺死了他，並把他拖到了深淵裡?', `FemaleText_loc7`='¿300? ¿Así que los Hierro Negro lo mataron y lo arrojaron a las Profundidades?' WHERE `ID`=5030;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 이 답답한 친구야... 당신 사실은 $R|1이;가; 아니라 그 "특이한" 종족 아니오? 우리는 트로그라고 부르는 멍청한 놈들 말이지.$B$B윈저 님과 검은무쇠 부족의 사이는 나쁘지 않았소. 고조 할아버지의 죽마고우가 바로 검은무쇠 드워프였으니까. 아마 그래서 검은무쇠 부족에서 윈저 님을 보고도 즉시 사살하지 않았던 것 같소.', `MaleText_loc4`='$n$g先生:女士;，如果我不是很了解你的话，我就会以为你也是那些穴居人中的一员。$B$B黑铁矮人没有把温德索尔怎么样，毕竟他的老祖父的最好最好的朋友就是一个黑铁矮人，这可能也就是黑铁军队到现在还没把他干掉的原因。', `MaleText_loc5`='$n$g先生:女士;，如果我不是很瞭解你的話，我就會以為你也是那些穴居怪中的一員。$B$B黑鐵矮人沒有把溫德索爾怎麼樣，畢竟他的老祖父的最好最好的朋友就是一個黑鐵矮人，這可能也就是黑鐵軍隊到現在還沒把他幹掉的原因。', `MaleText_loc7`='$gSeñor:Señorita;, si no fuera tan cabal como soy, pensaría que eres una de esa gente ‘especial’. La llamamos troggs.$B$BWindsor no tenía problemas con los Hierro Negro. Después de todo, el mejor amigo de su tatarabuelo era un Hierro Negro. Lo que probablemente también explica por qué ese ejército Hierro Negro no lo mató en cuanto lo vio.' WHERE `ID`=5031;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말이지 당신은 아는 게 없군. 제련 기술이 좀 더 늘거든 다시 찾아오도록 하시오!', `MaleText_loc4`='你的知识太缺乏了。当你熔炼技术更成熟些时再来找我！', `MaleText_loc5`='你的知識太缺乏了。當你熔煉技術更成熟些時再來找我!', `MaleText_loc7`='No sabes nada. ¡Vuelve cuando tus conocimientos sobre la fundición de metales hayan aumentado!' WHERE `ID`=5032;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 여기에 그냥 두고 가게. 마지막 순간에는 혼자 있고 싶으니...', `MaleText_loc4`='你可以走了……我希望在我生命的最后一刻独自待着。', `MaleText_loc5`='你可以走了...我希望在我生命的最後一刻獨自待著。', `MaleText_loc7`='Puedes dejarme aquí... Me gustaría estar a solas en mi momento final.' WHERE `ID`=5033;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 무쇠폭군말이로군요.', `MaleText_loc4`='啊……反对者。', `MaleText_loc5`='啊...反對者。', `MaleText_loc7`='Ahhh... Ferromazo.', `FemaleText_loc1`='아, 무쇠폭군말이로군요.', `FemaleText_loc4`='啊……反对者。', `FemaleText_loc5`='啊...反對者。', `FemaleText_loc7`='Ahhh... Ferromazo.' WHERE `ID`=5034;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제야 말귀를 좀 알아듣는구먼. 귀라도 좀 후비지 그러쇼. 거 답답해서 무슨 얘길 하겠소?!$B$B그래서, 검은무쇠 녀석들은 윈저님을 생포해갔지. 콧대가 하늘을 찌를 만큼 거만한 우두머리, 타우릿산인가 뭔가 하는 녀석이 무쇠폭군을 빼앗아 가져갔소. 내가 마지막으로 윈저 님을 본 게 그때요. *딸꾹* 쩝, 실례...', `MaleText_loc4`='最后！用手指堵住你的耳朵，你的脑子有可能会变得有五倍大，事实上，我甚至担心你的脑子会泄出来。$B$B那么，黑铁矮人们饶了他的性命，但把他囚禁了起来。他们的首领，某个叫做索什么森的妄自尊大的，愚蠢的，自负的家伙，把反对者留作己用。那是我最后一次见到温德索尔了……*嗝儿*', `MaleText_loc5`='最後!用手指堵住你的耳朵，你的腦子有可能會變得有五倍大，事實上，我甚至擔心你的腦子會泄出來。$B$B那麼，黑鐵矮人們饒了他的性命，但把他囚禁了起來。他們的首領，某個叫做索什麼森的妄自尊大的，愚蠢的，自負的傢伙，把反對者留作己用。那是我最後一次見到溫德索爾了...*嗝兒*', `MaleText_loc7`='¡Por fin! Tápate los oídos, porque tu cerebro va a aumentar unas cinco veces de tamaño y me preocupa que se salga por ahí.$B$BComo iba diciendo, los Hierro Negro le perdonaron la vida y lo hicieron prisionero. Su líder, un engreído con aires de superioridad llamado Thauris-no sé qué, cogió Ferromazo y se lo quedó. Y eso es lo último que supe del viejo Windsor... *hip* perdón.' WHERE `ID`=5035;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙네, $n. 이제야 내 영혼이 편히 쉴 수 있겠군.', `MaleText_loc4`='谢谢你，$n。我的灵魂终于得到了安宁。', `MaleText_loc5`='謝謝你，$n。我的靈魂終於得到了安寧。', `MaleText_loc7`='Gracias, $n. Ahora mi espíritu podrá descansar en paz.' WHERE `ID`=5036;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악령숲의 타락이 나를 이곳에 가두어 버렸네... 나의 영혼은 쉴 수가 없네...', `MaleText_loc4`='费伍德森林的堕落禁锢了我的灵魂……我也许永远都得不到安宁……', `MaleText_loc5`='費伍德森林的墮落禁錮了我的靈魂...我也許永遠都得不到安寧...', `MaleText_loc7`='La corrupción de Frondavil ha atrapado mi espíritu aquí... Jamás podré descansar...' WHERE `ID`=5037;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고마워요, 털보 존. 당신의 이야기를 듣고 나니 용기가 생기는 듯하군요. 매우 알찬 정보였습니다.', `MaleText_loc4`='谢谢你，约翰。你的故事振奋人心，使我受益匪浅。', `MaleText_loc5`='謝謝你，約翰。你的故事振奮人心，使我受益匪淺。', `MaleText_loc7`='Gracias, John Andrajoso. Tu historia me ha elevado el espíritu y me ha proporcionado mucha información.', `FemaleText_loc1`='고마워요, 털보 존. 당신의 이야기를 듣고 나니 용기가 생기는 듯하군요. 매우 알찬 정보였습니다.', `FemaleText_loc4`='谢谢你，约翰。你的故事振奋人心，使我受益匪浅。', `FemaleText_loc5`='謝謝你，約翰。你的故事振奮人心，使我受益匪淺。', `FemaleText_loc7`='Gracias, John Andrajoso. Tu historia me ha elevado el espíritu y me ha proporcionado mucha información.' WHERE `ID`=5038;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='험상궂은 주정뱅이 선술집에 오신 것을 환영합니다!', `FemaleText_loc4`='欢迎来到我们的酒店！', `FemaleText_loc5`='歡迎來到我們的酒店!', `FemaleText_loc7`='¡Bienvenidos a Tragapenas!' WHERE `ID`=5039;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='차라리 락노트와 함께 어디 조용한 곳을 찾아보지 그래요...', `MaleText_loc4`='为什么你跟罗克诺特不去找个二人天地呢……', `MaleText_loc5`='為什麼你跟羅克諾特不去找個二人天地呢...', `MaleText_loc7`='¿Por qué tú y Sinroca no buscáis un lugar más tranquilito...?', `FemaleText_loc1`='차라리 락노트와 함께 어디 조용한 곳을 찾아보지 그래요...', `FemaleText_loc4`='为什么你跟罗克诺特不去找个二人天地呢……', `FemaleText_loc5`='為什麼你跟羅克諾特不去找個二人天地呢...', `FemaleText_loc7`='¿Por qué tú y Sinroca no buscáis un lugar más tranquilito...?' WHERE `ID`=5040;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋은 생각이네요!', `FemaleText_loc4`='好主意！', `FemaleText_loc5`='好主意!', `FemaleText_loc7`='¡Buena idea!' WHERE `ID`=5041;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다시 한번 고마워요, $n. 락노트랑은 정말로 잘 되가고 있어요!', `FemaleText_loc4`='再次感谢你，$n。罗克诺特和我非常合得来！', `FemaleText_loc5`='再次感謝你，$n。羅克諾特和我非常合得來!', `FemaleText_loc7`='Gracias nuevamente, $n. ¡Sinrroca y yo en realidad nos íbamos!' WHERE `ID`=5042;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기술자가 또 왔군! 이번이야말로 지금까지 만들어 온 새로운 장치들을 선보일 좋은 기회야!', `MaleText_loc4`='原来是同道中人！嘿，我正好可以向你展示一下我的一些新发明！', `MaleText_loc5`='原來是同道中人!嘿，我正好可以向你展示一下我的一些新發明!', `MaleText_loc7`='¡$gOtro ingeniero:Otra ingeniera;! Oh, se me presenta una gran oportunidad de presumir de los nuevos aparatos que he construido.', `FemaleText_loc1`='기술자가 또 왔군! 이번이야말로 지금까지 만들어 온 새로운 장치들을 선보일 좋은 기회야!', `FemaleText_loc4`='原来是同道中人！嘿，我正好可以向你展示一下我的一些新发明！', `FemaleText_loc5`='原來是同道中人!嘿，我正好可以向你展示一下我的一些新發明!', `FemaleText_loc7`='¡$gOtro ingeniero:Otra ingeniera;! Oh, se me presenta una gran oportunidad de presumir de los nuevos aparatos que he construido.' WHERE `ID`=5043;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='검은바위 나락으로 가실 생각이라면 저를 찾아오세요. 당신에게 드릴 일거리가 있습니다.', `FemaleText_loc4`='如果你要到黑石深渊去，就来找我谈谈。或许我会有些工作要交给你。', `FemaleText_loc5`='如果你要到黑石深淵去，就來找我談談。或許我會有些工作要交給你。', `FemaleText_loc7`='Si vas a adentrarte en las Profundidades de Roca Negra, ven a hablar conmigo. Puede que tenga trabajo para ti.' WHERE `ID`=5044;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 피곤해 보입니다. 하품을 하더니 에이미 01 옆에 눕습니다.', `MaleText_loc4`='%s看上去很疲倦。他打着哈欠，躺在A-Me 01旁边。', `MaleText_loc5`='%s看起來很疲倦。他打著哈欠，躺在艾米01旁邊。', `MaleText_loc7`='%s parece cansado. Luego bosteza y se tiende junto a Memo 01' WHERE `ID`=5045;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 에이미 01 옆에 바짝 붙어 큰 소리로 코를 골며 잡니다.', `MaleText_loc4`='%s在A-Me 01旁边蜷缩着睡去，大声打鼾。', `MaleText_loc5`='%s在艾米01旁邊蜷縮著睡去，開始大聲打鼾。', `MaleText_loc7`='%s ronca con fuerza y se acurruca contra Memo 01.' WHERE `ID`=5046;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='운고로 분화구에 있는 멋진 것들은 다 보셨나요, $n? 정말 놀랍죠. 저의 기계공학 기술로 만들 수 있는 것들에 비하면 좀 덜하지만 여기 있는 것이 모두 자연 그대로의 것이라는 걸 생각한다면... 그리 나쁘지도 않죠.$B$B렘트래블 삼촌은 이렇게 고풍스러운 곳을 좋아하신답니다. 저도 삼촌의 뒤를 따르면서 잃어버린 문화에서 새로운 것들을 발견하고 싶거든요!', `FemaleText_loc4`='你见过安戈洛环形山的所有奇景了吗，$n？真是令人惊讶。虽然它们没有我制造出的东西那样精密，但这里所有的东西都是天然而成的……这就真是太奇特了。$B$B我的叔叔雷塔维就喜欢这样的地方。我正沿着他的脚步前进——我还想从灭绝的文明中找到新的知识！', `FemaleText_loc5`='你見過安戈洛環形山的所有奇景了嗎，$n?真是令人驚訝。雖然它們沒有我製造出的東西那樣精密，但這裡所有的東西都是天然而成的...這就真是太奇特了。$B$B我的叔叔雷姆塔維爾就喜歡這樣的地方。我正沿著他的腳步前進─我還想從滅絕的文明中找到新的知識!', `FemaleText_loc7`='¿Has visto todas las cosas maravillosas que hay en el cráter de Un’Goro, $n? Es sencillamente asombroso. No tanto como algunas cosas que podría hacer yo con mis conocimientos de ingeniería, pero para ser todo natural aquí... no está mal.$B$BA mi tío Tripirrem le encanta todo lo antiguo, como este lugar. Yo sigo sus pasos... ¡También quiero conocer cosas nuevas de culturas perdidas!' WHERE `ID`=5047;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='흠. 미스릴 형틀은 다 떨어져서 하나도 없어요. 에이미를 고치는 데 그것만 있으면 되나요? 아, 그러면 정말 좋겠네요!$B$B문명이 발달한 곳에서라면 미스릴 형틀을 그리 어렵지 않게 구할 수 있답니다. 솜씨 좋은 기술자에게 하나 만들어 달라고 해보세요. 미스릴 주괴가 몇 개 필요할 테지만 절 도와주신다면 아주 후하게 보상해 드리겠어요!', `FemaleText_loc4`='嗯，我没有任何秘银外壳。我尽力了。只要有那个就可以修理A-Me 01了吗？哦，太好了！$B$B秘银外壳并不是很难找到。只需请一个技艺高超的技师为你制造一个就可以了。我想那可能需要几块秘银，但是如果你能帮我，我保证你会得到丰厚奖赏的！', `FemaleText_loc5`='嗯，我沒有任何秘銀外殼。我盡力了。只要有那個就可以修理艾米01了嗎?哦，太好了!$B$B秘銀外殼並不是很難找到。只需請一個技藝高超的工程師為你製造一個就可以了。我想那可能需要幾塊秘銀，但是如果你能幫我，我保證你會得到豐厚獎賞的!', `FemaleText_loc7`='Mmm, no tengo cajas de mitril. Se me terminaron. ¿Eso es todo lo que necesitas para reparar a Memo? ¡Sería fantástico!$B$BLas cajas de mitril no son difíciles de conseguir en el mundo civilizado. Solo tienes que pedir a un ingeniero capaz que te haga una. Creo que hacen falta unas cuantas barras de mitril, pero si me ayudas a conseguirlas, ¡te recompensaré con creces!' WHERE `ID`=5048;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혹시 미스릴 형틀 있습니까?', `MaleText_loc4`='你有秘银外壳吗？', `MaleText_loc5`='你有秘銀外殼嗎?', `MaleText_loc7`='¿Tienes alguna caja de mitril?', `FemaleText_loc1`='혹시 미스릴 형틀 있습니까?', `FemaleText_loc4`='你有秘银外壳吗？', `FemaleText_loc5`='你有秘銀外殼嗎?', `FemaleText_loc7`='¿Tienes alguna caja de mitril?' WHERE `ID`=5049;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='검은무쇠 맥주를 꼭 한번 마셔보세요. 이 부근의 드워프들은 질리지도 않을 만큼 좋아한다고 하더군요.', `FemaleText_loc4`='你一定要尝一下我们的黑铁啤酒。我听说附近的矮人总是有多少喝多少。', `FemaleText_loc5`='你一定要嘗一下我們的黑鐵麥芽酒。我聽說附近的矮人總是有多少喝多少。', `FemaleText_loc7`='No dejes de probar nuestra cerveza Hierro Negro. He oído que aquí los enanos nunca se cansan de beberla.' WHERE `ID`=5050;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='플러거 스패즈링 님은 참 좋은 분이세요. 게다가 주머니가 찢어질 정도로 돈도 아주 많이 버시죠.', `FemaleText_loc4`='我的主人普拉格是个不错的老板，而且他赚了很多钱。他的钱包都快要被撑破了！', `FemaleText_loc5`='我的主人普拉格·史帕齊林是個不錯的老闆，而且他賺了很多錢。他的錢包都快要被撐破了!', `FemaleText_loc7`='Mi Maestro, Plugger Aropatoso, es un buen jefe. Y gana un montón de dinero. ¡Tiene los bolsillos a reventar!' WHERE `ID`=5051;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거야말로 세계 최고이자 최신식 운송 수단이라고 할 수 있죠. 뭐? 노움이 만든 깊은굴 지하철이라고요? 이봐요, 잘 들으세요. 그따위 쓰레기를 믿느니, 차라리 가시덤불 골짜기에 날 기리는 동상을 세웠다는 말을 믿으시죠. 자, 그롬골까지 걸어서 가시겠습니까? 아니면 저희 최신식 비행선을 타고 가시겠습니까? 선택은 당신에게 달렸습니다.', `MaleText_loc4`='这是用钱能够建造出的最好最先进的交通工具。什么？矿道地铁？侏儒？听着，朋友，如果你相信那种废物的话，我就把荆棘谷中的那尊雕像卖给你。那么，你到底是要走着去格罗姆高营地，还是乘坐这架精美的飞行机器？你选吧。', `MaleText_loc5`='這是用錢能夠建造出的最好最先進的交通工具。什麼?礦道地鐵?地精?聽著，朋友，如果你相信那種廢物的話，我就把荊棘谷中的那尊雕像賣給你。那麼，你到底是要走著去格羅姆高營地，還是乘坐這架精美的飛行機器?你選吧。', `MaleText_loc7`='Este es el sistema de transporte más moderno y sofisticado que el dinero permite construir. ¿Qué? ¿El Tranvía Subterráneo? ¿Gnomos? Escucha, $gamigo:amiga;, si te crees esa basura, entonces puedo venderte una estatua que hay en Tuercespina. ¿Vas a ir andando hasta Grom''gol o vas a montar en esta sofisticada máquina voladora? Tú verás.' WHERE `ID`=5052;
