UPDATE `locales_broadcast_text` SET `MaleText_loc1`='팔랑크스, 이 양반에게 따끔한 맛 좀 보여주게.', `MaleText_loc4`='法拉克斯，我想你需要好好教训一下这些家伙。', `MaleText_loc5`='法拉克斯，我想你需要好好教訓一下這些傢伙。', `MaleText_loc7`='Phalanx, creo que tienes que dar una lección a esa gente.' WHERE `ID`=5057;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 위험한 녀석이군!', `MaleText_loc4`='你是一个威胁！', `MaleText_loc5`='你是一個威脅!', `MaleText_loc7`='¡Te consideran una amenaza!' WHERE `ID`=5058;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 꼭 다시 태어날 것이다! 인센디우스 님이 이 재에서 나를 다시 일으켜줄 것이다!', `MaleText_loc4`='我会重生的！伊森迪奥斯会从这些灰烬中将我复活的！', `MaleText_loc5`='我會重生的!伊森迪奧斯會從這些灰燼中將我復活的!', `MaleText_loc7`='¡Resurgiré, mortales! ¡Incendius me hará resurgir de las cenizas!' WHERE `ID`=5059;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 끝났어! 넌 끝장이라고!', `MaleText_loc4`='你完了！', `MaleText_loc5`='你完了!', `MaleText_loc7`='¡Ya está bien! ¡Estás $gacabado:acabada;!' WHERE `ID`=5060;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나를 파멸시킬 수는 없어! 라그나로스 님의 의지로 나는 다시 환생하리라!', `MaleText_loc4`='我不会死掉！以拉格纳罗斯的意愿为名，我会重生的！', `MaleText_loc5`='我不會死掉!以拉格納羅斯的意願為名，我會重生的!', `MaleText_loc7`='¡Soy indestructible! ¡Renaceré por el poder de Ragnaros!' WHERE `ID`=5061;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에이미 작동 개시. 에이미 집에 간다. 에이미에게 말을 걸어 이동 시스템 설정을 변경해라.', `MaleText_loc4`='A-Me操作。A-Me回家。你对A-Me说，要他改变运动设置。', `MaleText_loc5`='艾米可以動。艾米回家。你跟艾米說話來改變行進方向的設定。', `MaleText_loc7`='Memo operativo. Memo ir a casa. Hablar con Memo para cambiar ajustes de locomoción.' WHERE `ID`=5062;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='착해... 착해, 에이미. 에이미 착해. 집. 집 찾아.', `MaleText_loc4`='好……很好，A-Me。A-Me好。家。找到家。', `MaleText_loc5`='好...很好，艾米。艾米好。家。找到家。', `MaleText_loc7`='Bueno... bueno, Memo. Memo bueno. Casa. Encontrar casa.' WHERE `ID`=5063;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와줘! $n|1이;가; 가까이 왔다!!!', `MaleText_loc4`='帮帮我！$n过来了！', `MaleText_loc5`='幫幫我!$n過來了!', `MaleText_loc7`='¡Ayuda! ¡$n se acerca!' WHERE `ID`=5064;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 $n|1을;를; 처치해줘!', `MaleText_loc4`='帮我对付这个$n！', `MaleText_loc5`='幫我對付這個$n!', `MaleText_loc7`='¡Ayúdame con esto, $n!' WHERE `ID`=5065;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='썬더브루 맥주를 들어보셨소? 아주 좋은 술이지! 딸꾹!', `MaleText_loc4`='你喝过雷霆啤酒吗？那可是好东西！', `MaleText_loc5`='你喝過雷霆啤酒嗎?那可是好東西!', `MaleText_loc7`='¿Has probado la cerveza Cebatruenos? ¡Es muy buena!', `FemaleText_loc1`='썬더브루 맥주를 들어보셨소? 아주 좋은 술이지! 딸꾹!', `FemaleText_loc4`='你喝过雷霆啤酒吗？那可是好东西！', `FemaleText_loc5`='你喝過雷霆啤酒嗎?那可是好東西!', `FemaleText_loc7`='¿Has probado la cerveza Cebatruenos? ¡Es muy buena!' WHERE `ID`=5066;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 시간 후에는 일을 해야 하지만 그때까지는 쭉 들이켜야지, 암!', `MaleText_loc4`='我一个小时以后还要去值班，但在那之前……干杯！', `MaleText_loc5`='我一個小時以後還要去值班，但在那之前...喝個過癮吧!', `MaleText_loc7`='Dentro de una hora volveré a estar de servicio... pero hasta entonces, ¡a beber!', `FemaleText_loc1`='한 시간 후에는 일을 해야 하지만 그때까지는 쭉 들이켜야지, 암!', `FemaleText_loc4`='我一个小时以后还要去值班，但在那之前……干杯！', `FemaleText_loc5`='我一個小時以後還要去值班，但在那之前...喝個過癮吧!', `FemaleText_loc7`='Dentro de una hora volveré a estar de servicio... pero hasta entonces, ¡a beber!' WHERE `ID`=5067;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 지금 날 보고 있나?', `MaleText_loc4`='你在看我吗，$g小伙子:姑娘;？', `MaleText_loc5`='你在看我嗎，$g小夥子:姑娘;?', `MaleText_loc7`='¿Me estás mirando, $gjovencito:jovencita;?', `FemaleText_loc1`='이봐, 지금 날 보고 있나?', `FemaleText_loc4`='你在看我吗，$g小伙子:姑娘;？', `FemaleText_loc5`='你在看我嗎，$g小夥子:姑娘;?', `FemaleText_loc7`='¿Me estás mirando, $gjovencito:jovencita;?' WHERE `ID`=5068;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기, 검은무쇠 맥주 한잔이요. 아, 이런. 당신은 종업원이 아니군.', `MaleText_loc4`='我要来一杯黑铁啤酒。哦，你不是侍者？', `MaleText_loc5`='我要來一杯黑鐵麥芽酒。哦，你不是侍者?', `MaleText_loc7`='Yo quiero una caña de Hierro Negro. ¿Ah, no eres $gcamarero:camarera;?', `FemaleText_loc1`='여기, 검은무쇠 맥주 한잔이요. 아, 이런. 당신은 종업원이 아니군.', `FemaleText_loc4`='我要来一杯黑铁啤酒。哦，你不是侍者？', `FemaleText_loc5`='我要來一杯黑鐵麥芽酒。哦，你不是侍者?', `FemaleText_loc7`='Yo quiero una caña de Hierro Negro. ¿Ah, no eres $gcamarero:camarera;?' WHERE `ID`=5069;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='플러거 그 친구가 맥주통 하나를 너무 채운 모양이야. 곧 터질 것 같아!', `MaleText_loc4`='我认为普拉格把桶装得太满了。你瞧，简直都要炸开了！', `MaleText_loc5`='我認為普拉格把桶裝得太滿了。你瞧，簡直都要炸開了!', `MaleText_loc7`='Creo que Plugger llenó demasiado uno de estos barriles. ¡Parece que va a explotar!', `FemaleText_loc1`='플러거 그 친구가 맥주통 하나를 너무 채운 모양이야. 곧 터질 것 같아!', `FemaleText_loc4`='我认为普拉格把桶装得太满了。你瞧，简直都要炸开了！', `FemaleText_loc5`='我認為普拉格把桶裝得太滿了。你瞧，簡直都要炸開了!', `FemaleText_loc7`='Creo que Plugger llenó demasiado uno de estos barriles. ¡Parece que va a explotar!' WHERE `ID`=5070;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한참 즐기는 중인데 귀찮게 하지 마시오...', `MaleText_loc4`='在我参加聚会时别骚扰我……', `MaleText_loc5`='在我參加聚會時別騷擾我...', `MaleText_loc7`='No me molestes mientras estoy de fiesta...', `FemaleText_loc1`='한참 즐기는 중인데 귀찮게 하지 마시오...', `FemaleText_loc4`='在我参加聚会时别骚扰我……', `FemaleText_loc5`='在我參加聚會時別騷擾我...', `FemaleText_loc7`='No me molestes mientras estoy de fiesta...' WHERE `ID`=5071;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='길을 찾고 계십니까?', `MaleText_loc4`='你需要指引吗，$g小伙子:姑娘;？', `MaleText_loc5`='你需要指引嗎，$g小夥子:姑娘;?', `MaleText_loc7`='¿Necesitas que te guíen, $gmuchacho:muchacha;?', `FemaleText_loc1`='길을 찾고 계십니까?', `FemaleText_loc4`='你需要指引吗，$g小伙子:姑娘;？', `FemaleText_loc5`='你需要指引嗎，$g小夥子:姑娘;?', `FemaleText_loc7`='¿Necesitas que te guíen, $gmuchacho:muchacha;?' WHERE `ID`=5072;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이언포지의 아침 공기는 너무나 상쾌합니다! 뭐... 필요한 거라도 있으십니까?', `MaleText_loc4`='我喜欢清晨的铁炉堡的气息！嗯？你需要什么吗，$c？', `MaleText_loc5`='我喜歡清晨的鐵爐堡的氣息!嗯?你需要什麼嗎，$c?', `MaleText_loc7`='¡Me encanta el olor de Forjaz por la mañana! ¿Eh? ¿Y qué podrías necesitar, $c?', `FemaleText_loc1`='아이언포지의 아침 공기는 너무나 상쾌합니다! 뭐... 필요한 거라도 있으십니까?', `FemaleText_loc4`='我喜欢清晨的铁炉堡的气息！嗯？你需要什么吗，$c？', `FemaleText_loc5`='我喜歡清晨的鐵爐堡的氣息!嗯?你需要什麼嗎，$c?', `FemaleText_loc7`='¡Me encanta el olor de Forjaz por la mañana! ¿Eh? ¿Y qué podrías necesitar, $c?' WHERE `ID`=5073;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일이십니까?', `MaleText_loc4`='你需要什么？', `MaleText_loc5`='你需要什麼?', `MaleText_loc7`='¿Qué necesitas?', `FemaleText_loc1`='무슨 일이십니까?', `FemaleText_loc4`='你需要什么？', `FemaleText_loc5`='你需要什麼?', `FemaleText_loc7`='¿Qué necesitas?' WHERE `ID`=5074;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언제나 만약, 만약이라고들 하지요! 아이언포지 사전에 ''만약''은 없습니다! 뭐가 궁금한 겁니까?', `MaleText_loc4`='假如他们说……假如！对铁炉堡来说没有假如！嗯？现在情况如何？', `MaleText_loc5`='假如他們說...假如!對鐵爐堡來說沒有假如!嗯?現在情況如何?', `MaleText_loc7`='SI dicen... ¡Solo SI lo hacen! ¡No cabe hacer suposiciones cuando se trata de Forjaz! ¿Eh? ¿Y ahora qué?', `FemaleText_loc1`='언제나 만약, 만약이라고들 하지요! 아이언포지 사전에 ''만약''은 없습니다! 뭐가 궁금한 겁니까?', `FemaleText_loc4`='假如他们说……假如！对铁炉堡来说没有假如！嗯？现在情况如何？', `FemaleText_loc5`='假如他們說...假如!對鐵爐堡來說沒有假如!嗯?現在情況如何?', `FemaleText_loc7`='SI dicen... ¡Solo SI lo hacen! ¡No cabe hacer suposiciones cuando se trata de Forjaz! ¿Eh? ¿Y ahora qué?' WHERE `ID`=5075;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='길을 좀 가르쳐주시겠습니까?', `MaleText_loc4`='你能帮我指一下路吗？', `MaleText_loc5`='你能幫我指一下路嗎?', `MaleText_loc7`='¿Puedes ayudarme con algunas señas?', `FemaleText_loc1`='길을 좀 가르쳐주시겠습니까?', `FemaleText_loc4`='你能帮我指一下路吗？', `FemaleText_loc5`='你能幫我指一下路嗎?', `FemaleText_loc7`='¿Puedes ayudarme con algunas señas?' WHERE `ID`=5076;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디로 가는 길을 찾으십니까?', `MaleText_loc4`='你想去哪里？', `MaleText_loc5`='你想去哪裡?', `MaleText_loc7`='¿Adónde deseas ir?', `FemaleText_loc1`='어디로 가는 길을 찾으십니까?', `FemaleText_loc4`='你想去哪里？', `FemaleText_loc5`='你想去哪裡?', `FemaleText_loc7`='¿Adónde deseas ir?' WHERE `ID`=5077;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이언포지 은행', `MaleText_loc4`='铁炉堡银行', `MaleText_loc5`='鐵爐堡銀行', `MaleText_loc7`='Banco de Forjaz', `FemaleText_loc1`='아이언포지 은행', `FemaleText_loc4`='铁炉堡银行', `FemaleText_loc5`='鐵爐堡銀行', `FemaleText_loc7`='Banco de Forjaz' WHERE `ID`=5078;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안전하게 보관해야 할 보물이라도 찾으신 겁니까? 스톤맨틀 집안에서 운영하는 사설금고에 보관하는 게 좋겠군요.

아이언포지 입구에서 북동쪽으로 망치 하나 던지면 닿을 거리에 사설금고가 있습니다.', `MaleText_loc4`='你有需要保管的财宝吗？去找铁炉堡银行的石衣兄弟吧。

从铁炉堡的入口往东北方向走，银行就在那边。', `MaleText_loc5`='你有需要保管的財寶嗎?去找鐵爐堡銀行的石衣兄弟吧。

從鐵爐堡的入口往東北方向走，銀行就在那邊。', `MaleText_loc7`='¿Tienes nuevos tesoros que desees conservar sanos y salvos? De ser así debes guardarlos en Las Arcas con los mantopétreos. 

Las Arcas se encuentran a un tiro de martillo en dirección nordeste desde la entrada de Forjaz.', `FemaleText_loc1`='안전하게 보관해야 할 보물이라도 찾으신 겁니까? 스톤맨틀 집안에서 운영하는 사설금고에 보관하는 게 좋겠군요.

아이언포지 입구에서 북동쪽으로 망치 하나 던지면 닿을 거리에 사설금고가 있습니다.', `FemaleText_loc4`='你有需要保管的财宝吗？去找铁炉堡银行的石衣兄弟吧。

从铁炉堡的入口往东北方向走，银行就在那边。', `FemaleText_loc5`='你有需要保管的財寶嗎?去找鐵爐堡銀行的石衣兄弟吧。

從鐵爐堡的入口往東北方向走，銀行就在那邊。', `FemaleText_loc7`='¿Tienes nuevos tesoros que desees conservar sanos y salvos? Debes guardarlos en Las Arcas con los Mantopétreo. Las Arcas se encuentran a un tiro de martillo en dirección nordeste desde la entrada de Forjaz.' WHERE `ID`=5079;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은행 말입니까? 아, 사설금고 말씀이시지요? 귀중품을 보관할 장소로 그 만한 데가 없지요. 아이언포지 입구에서 북동쪽으로 가면 있습니다.', `MaleText_loc4`='银行？哦，你是说银行！说到存储贵重物品的话，没有什么比银行更安全的地方了。它就在铁炉堡大门的东北方。', `MaleText_loc5`='銀行?哦，你是說銀行!說到存儲貴重物品的話，沒有什麼比銀行更安全的地方了。它就在鐵爐堡大門的東北方。', `MaleText_loc7`='¿El banco? ¡Querrás decir Las Arcas! No hay un lugar más seguro para guardar tus objetos valiosos que Las Arcas. Las encontrarás al noreste de la entrada de Forjaz.', `FemaleText_loc1`='은행 말입니까? 아, 사설금고 말씀이시지요? 귀중품을 보관할 장소로 그 만한 데가 없지요. 아이언포지 입구에서 북동쪽으로 가면 있습니다.', `FemaleText_loc4`='银行？哦，你是说银行！说到存储贵重物品的话，没有什么比银行更安全的地方了。它就在铁炉堡大门的东北方。', `FemaleText_loc5`='銀行?哦，你是說銀行!說到存儲貴重物品的話，沒有什麼比銀行更安全的地方了。它就在鐵爐堡大門的東北方。', `FemaleText_loc7`='¿El banco? ¡Querrás decir Las Arcas! No hay un lugar más seguro para guardar tus objetos valiosos que Las Arcas. Las encontrarás al noreste de la entrada de Forjaz.' WHERE `ID`=5080;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리핀 조련사', `MaleText_loc4`='狮鹫管理员', `MaleText_loc5`='獅鷲獸管理員', `MaleText_loc7`='Maestro de grifos', `FemaleText_loc1`='그리핀 조련사', `FemaleText_loc4`='狮鹫管理员', `FemaleText_loc5`='獅鷲獸管理員', `FemaleText_loc7`='Maestro de grifos' WHERE `ID`=5081;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리핀을 타시려고요? 그렇다면 그리스 서든을 찾아가보세요.

아이언포지 중앙에 있는 대용광로 동쪽으로 가면 그 친구를 찾을 수 있을 겁니다.', `MaleText_loc4`='想要乘坐狮鹫，是吗？你得去找格莱斯·瑟登。

你可以在铁炉堡中心的大锻炉东边找到他。', `MaleText_loc5`='想要乘坐獅鷲獸，是嗎?你得去找格萊斯·瑟登。

你可以在鐵爐堡中心的大鍛爐東邊找到他。', `MaleText_loc7`='Quieres dar una vuelta en grifo, ¿verdad? Gryth Thurden es quien puede ayudarte. 

Puedes encontrarlo en la parte oriental de La Gran Fundición en el centro de Forjaz.', `FemaleText_loc1`='그리핀을 타시려고요? 그렇다면 그리스 서든을 찾아가보세요.

아이언포지 중앙에 있는 대용광로 동쪽으로 가면 그 친구를 찾을 수 있을 겁니다.', `FemaleText_loc4`='想要乘坐狮鹫，是吗？你得去找格莱斯·瑟登。

你可以在铁炉堡中心的大锻炉东边找到他。', `FemaleText_loc5`='想要乘坐獅鷲獸，是嗎?你得去找格萊斯·瑟登。

你可以在鐵爐堡中心的大鍛爐東邊找到他。', `FemaleText_loc7`='Quieres dar una vuelta en grifo, ¿verdad? Gryth Thurden es quien puede ayudarte. 

Puedes encontrarlo en la parte oriental de La Gran Fundición en el centro de Forjaz.' WHERE `ID`=5083;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리핀을 타는 것만큼 재미난 일도 없지요. 나이트 엘프들은 히포그리프나 실컷 타라고 해요! 전 그리핀을 타고 훨훨 날아갈 수만 있으면 그걸로 대만족이니까요!

흠, 잡담이 너무 길어졌군요. 대용광로 동쪽에 있는 그리스 서든을 찾아가세요. 그자가 안내할 겁니다.', `MaleText_loc4`='啊，没有什么比狮鹫更好的坐骑了。暗夜精灵偏爱可笑的角鹰兽，而我只需一头狮鹫就可以穿梭在云端！

好吧，我不跟你唠叨了，到大锻炉东边的格莱斯·瑟登那儿去吧，他会向你出租狮鹫的。', `MaleText_loc5`='啊，沒有什麼比獅鷲獸更好的坐騎了，對吧?夜精靈偏愛角鷹獸，而我還是喜歡乘一隻獅鷲獸穿梭雲端!

好吧，我不跟你嘮叨了，到大鍛爐東邊的格萊斯·瑟登那兒去吧，他會幫你上路的。', `MaleText_loc7`='Ah, nada como un paseo en grifo, ¿verdad? Los elfos de la noche pueden quedarse con sus hipogrifos. ¡Yo solo quiero un grifo y el viento rozando mi pelo! 

Bueno, vale, no te entretengo más. Ve a ver a Gryth Thurden, que está en la zona este de La Gran Fundición y él te ayudará a llegar a tu destino.', `FemaleText_loc1`='그리핀을 타는 것만큼 재미난 일도 없지요. 나이트 엘프들은 히포그리프나 실컷 타라고 해요! 전 그리핀을 타고 훨훨 날아갈 수만 있으면 그걸로 대만족이니까요!

흠, 잡담이 너무 길어졌군요. 대용광로 동쪽에 있는 그리스 서든을 찾아가세요. 그자가 안내할 겁니다.', `FemaleText_loc4`='啊，没有什么比狮鹫更好的坐骑了。暗夜精灵偏爱可笑的角鹰兽，而我只需一头狮鹫就可以穿梭在云端！

好吧，我不跟你唠叨了，到大锻炉东边的格莱斯·瑟登那儿去吧，他会向你出租狮鹫的。', `FemaleText_loc5`='啊，沒有什麼比獅鷲獸更好的坐騎了，對吧?夜精靈偏愛角鷹獸，而我還是喜歡乘一隻獅鷲獸穿梭雲端!

好吧，我不跟你嘮叨了，到大鍛爐東邊的格萊斯·瑟登那兒去吧，他會幫你上路的。', `FemaleText_loc7`='Ah, nada como un paseo en grifo, ¿verdad? Los elfos de la noche pueden quedarse con sus hipogrifos. ¡Yo solo quiero un grifo y el viento rozando mi pelo! 

Bueno, vale, no te entretengo más. Ve a ver a Gryth Thurden, que está en la zona este de La Gran Fundición y él te ayudará a llegar a tu destino.' WHERE `ID`=5085;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='길드 사무관과 상인', `MaleText_loc4`='公会注册员及公会商人', `MaleText_loc5`='公會註冊員和商人', `MaleText_loc7`='Maestro de hermandad y vendedor', `FemaleText_loc1`='길드 사무관과 상인', `FemaleText_loc4`='公会注册员及公会商人', `FemaleText_loc5`='公會註冊員和商人', `FemaleText_loc7`='Maestro de hermandad y vendedor' WHERE `ID`=5086;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='길드를 창설할 생각이라면 아이언포지 사무소에 있는 욘도르 스틸브라우를 찾아가세요. 아이언포지 성문에서 남동쪽으로 가면 됩니다.', `MaleText_loc4`='要是你想组建公会的话，那你首先需要通过铁炉堡访客中心的乔多·钢眉的认同。穿过铁炉堡大门往东南方向走，你就能找到他。', `MaleText_loc5`='要是你想組建公會的話，那你首先需要通過鐵爐堡訪客中心的喬多·鋼眉的認同。穿過鐵爐堡大門往東南方向走，你就能找到他。', `MaleText_loc7`='Si piensas formar una hermandad, tendrás que ir a buscar a Jondor Frenteacerada, en el Centro del Viajero de Forjaz. Cuando estés en las puertas de Forjaz, ve hacia el sudeste y lo encontrarás.', `FemaleText_loc1`='길드를 창설할 생각이라면 아이언포지 사무소에 있는 욘도르 스틸브라우를 찾아가세요. 아이언포지 성문에서 남동쪽으로 가면 됩니다.', `FemaleText_loc4`='要是你想组建公会的话，那你首先需要通过铁炉堡访客中心的乔多·钢眉的认同。穿过铁炉堡大门往东南方向走，你就能找到他。', `FemaleText_loc5`='要是你想組建公會的話，那你首先需要通過鐵爐堡訪客中心的喬多·鋼眉的認同。穿過鐵爐堡大門往東南方向走，你就能找到他。', `FemaleText_loc7`='Si piensas formar una hermandad, tendrás que ir a buscar a Jondor Frenteacerada, en el Centro del Viajero de Forjaz. Cuando estés en las puertas de Forjaz, ve hacia el sudeste y lo encontrarás.' WHERE `ID`=5087;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='직업 상급자', `MaleText_loc4`='职业训练师', `MaleText_loc5`='職業訓練師', `MaleText_loc7`='Instructor de clase', `FemaleText_loc1`='직업 상급자', `FemaleText_loc4`='职业训练师', `FemaleText_loc5`='職業訓練師', `FemaleText_loc7`='Instructor de clase' WHERE `ID`=5088;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 직업 상급자를 찾으십니까?', `MaleText_loc4`='你想找哪类职业训练师？', `MaleText_loc5`='你想找哪類職業訓練師?', `MaleText_loc7`='¿Qué instructor de clase estás buscando?', `FemaleText_loc1`='어떤 직업 상급자를 찾으십니까?', `FemaleText_loc4`='你想找哪类职业训练师？', `FemaleText_loc5`='你想找哪類職業訓練師?', `FemaleText_loc7`='¿Qué instructor de clase estás buscando?' WHERE `ID`=5089;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여관', `MaleText_loc4`='旅店', `MaleText_loc5`='旅店', `MaleText_loc7`='La posada', `FemaleText_loc1`='여관', `FemaleText_loc4`='旅店', `FemaleText_loc5`='旅店', `FemaleText_loc7`='La posada' WHERE `ID`=5090;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여관이요? 아, 아이언포지에서 최고로 맛 좋은 맥주를 한잔 걸치고 싶은 거로군요. 그렇다면 부싯돌 선술집으로 가보십시오.$B$B오시는 길이라면 아이언포지 정문에서 왼쪽, 가시는 길이라면 오른쪽에 있습니다.', `MaleText_loc4`='旅馆？啊，你是来寻找铁炉堡出产的美酒的？你该去石火旅店。$B$B如果你在铁炉堡之外，它就在铁炉堡大门的左边；反之，则在大门右边。', `MaleText_loc5`='旅館?啊，你是來尋找鐵爐堡出產的美味麥芽酒的?你該去石火旅店。$B$B如果你在鐵爐堡之外，它就在鐵爐堡大門的左邊;反之，則在大門右邊。', `MaleText_loc7`='¿La posada? Ah, ¿quieres tomarte unas cañas, de las mejores que hay en Forjaz? La Taberna Roca de Fuego es el lugar apropiado. $B$BLo encontrarás a la izquierda de la entrada de Forjaz cuando vienes desde fuera, o a la derecha si vas a salir.', `FemaleText_loc1`='여관이요? 아, 아이언포지에서 최고로 맛 좋은 맥주를 한잔 걸치고 싶은 거로군요. 그렇다면 부싯돌 선술집으로 가보십시오.$B$B오시는 길이라면 아이언포지 정문에서 왼쪽, 가시는 길이라면 오른쪽에 있습니다.', `FemaleText_loc4`='旅馆？啊，你是来寻找铁炉堡出产的美酒的？你该去石火旅店。$B$B如果你在铁炉堡之外，它就在铁炉堡大门的左边；反之，则在大门右边。', `FemaleText_loc5`='旅館?啊，你是來尋找鐵爐堡出產的美味麥芽酒的?你該去石火旅店。$B$B如果你在鐵爐堡之外，它就在鐵爐堡大門的左邊;反之，則在大門右邊。', `FemaleText_loc7`='¿La posada? Ah, ¿quieres tomarte unas cañas, de las mejores que hay en Forjaz? La Taberna Roca de Fuego es el lugar apropiado. $B$BLo encontrarás a la izquierda de la entrada de Forjaz cuando vienes desde fuera, o a la derecha si vas a salir.' WHERE `ID`=5091;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여관을 찾고 계신다면 부싯돌 선술집으로 가보십시오. 오시는 길이라면 아이언포지의 왼쪽, 나가시는 길이라면 오른쪽에 있습니다.$B$B아, 가시는 김에 제가 갈 테니 맥주나 한 통 준비해두라고 일러두십시오.', `MaleText_loc4`='要是你要找旅馆的话，石火旅店是个不错的选择。若是你前往铁炉堡的话，会在城门的左边找到这个旅馆；要是在铁炉堡里面的话，它就在城门的右边。$B$B哦，要是你现在就去那里的话，告诉他们为我准备好啤酒吧。', `MaleText_loc5`='要是你要找旅館的話，石火旅店是個不錯的選擇。若是你前往鐵爐堡的話，會在城門的左邊找到這個旅館;要是在鐵爐堡裡面的話，它就在城門的右邊。$B$B哦，要是你現在就去那裡的話，告訴他們為我準備好啤酒吧。', `MaleText_loc7`='Si buscas una posada, la Taberna Roca de Fuego es el lugar indicado. Lo encontrarás a la izquierda de la entrada de Forjaz cuando vienes desde fuera, o a la derecha si vas a salir. $B$BOh, y si vas allí, diles que me tengan preparada una jarra.', `FemaleText_loc1`='여관을 찾고 계신다면 부싯돌 선술집으로 가보십시오. 오시는 길이라면 아이언포지의 왼쪽, 나가시는 길이라면 오른쪽에 있습니다.$B$B아, 가시는 김에 제가 갈 테니 맥주나 한 통 준비해두라고 일러두십시오.', `FemaleText_loc4`='要是你要找旅馆的话，石火旅店是个不错的选择。若是你前往铁炉堡的话，会在城门的左边找到这个旅馆；要是在铁炉堡里面的话，它就在城门的右边。$B$B哦，要是你现在就去那里的话，告诉他们为我准备好啤酒吧。', `FemaleText_loc5`='要是你要找旅館的話，石火旅店是個不錯的選擇。若是你前往鐵爐堡的話，會在城門的左邊找到這個旅館;要是在鐵爐堡裡面的話，它就在城門的右邊。$B$B哦，要是你現在就去那裡的話，告訴他們為我準備好啤酒吧。', `FemaleText_loc7`='Si buscas una posada, la Taberna Roca de Fuego es el lugar indicado. Lo encontrarás a la izquierda de la entrada de Forjaz cuando vienes desde fuera, o a la derecha si vas a salir. $B$BOh, y si vas allí, diles que me tengan preparada una jarra.' WHERE `ID`=5092;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우체통', `MaleText_loc4`='邮箱', `MaleText_loc5`='郵箱', `MaleText_loc7`='Buzón', `FemaleText_loc1`='우체통', `FemaleText_loc4`='邮箱', `FemaleText_loc5`='郵箱', `FemaleText_loc7`='Buzón' WHERE `ID`=5093;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우체통은 부싯돌 선술집 옆에 있습니다. 아이언포지 성문에서 북쪽으로 조금만 가면 됩니다.', `MaleText_loc4`='你会在那边的石火旅店旁边找到一个邮箱。那就在铁炉堡大门的北面。', `MaleText_loc5`='你會在那邊的石火旅店旁邊找到一個郵箱。那就在鐵爐堡大門的北面。', `MaleText_loc7`='Encontrarás un buzón al lado de la Taberna Roca de Fuego. Está justo al norte de las puertas de Forjaz.', `FemaleText_loc1`='우체통은 부싯돌 선술집 옆에 있습니다. 아이언포지 성문에서 북쪽으로 조금만 가면 됩니다.', `FemaleText_loc4`='你会在那边的石火旅店旁边找到一个邮箱。那就在铁炉堡大门的北面。', `FemaleText_loc5`='你會在那邊的石火旅店旁邊找到一個郵箱。那就在鐵爐堡大門的北面。', `FemaleText_loc7`='Encontrarás un buzón al lado de la Taberna Roca de Fuego. Está justo al norte de las puertas de Forjaz.' WHERE `ID`=5094;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사냥꾼', `MaleText_loc4`='猎人', `MaleText_loc5`='獵人', `MaleText_loc7`='Cazador', `FemaleText_loc1`='사냥꾼', `FemaleText_loc4`='猎人', `FemaleText_loc5`='獵人', `FemaleText_loc7`='Cazador' WHERE `ID`=5095;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요전 날 전투의 전당에 갔다가 레그누스 썬더그래니트가 자신의 동굴에 박제해서 놓을 새로운 전리품을 잡아왔다고 자랑을 늘어놓더군. 솜씨 있는 사냥꾼에게서 훈련을 받을 생각이라면 레그누스를 찾아가보시죠.', `MaleText_loc4`='几天前，我无意中听雷格努斯·雷石在武器大厅中吹嘘他兽穴中的一件新饰品。要是你想成为一名技艺纯熟的猎人，就去找他吧。', `MaleText_loc5`='幾天前，我無意中聽雷格努斯·雷岩在武器大廳中吹噓他獸穴中的一件新飾品。要是你想成為一名技藝純熟的獵人，就去找他吧。', `MaleText_loc7`='El otro día escuché por casualidad a Regnus Tronagranito en la Sala de Armas, jactándose de haber ganado un nuevo trofeo para su grupo. Si quieres instrucción de un cazador experto, Regnus es a quien tienes que ir a ver.', `FemaleText_loc1`='요전 날 전투의 전당에 갔다가 레그누스 썬더그래니트가 자신의 동굴에 박제해서 놓을 새로운 전리품을 잡아왔다고 자랑을 늘어놓더군. 솜씨 있는 사냥꾼에게서 훈련을 받을 생각이라면 레그누스를 찾아가보시죠.', `FemaleText_loc4`='几天前，我无意中听雷格努斯·雷石在武器大厅中吹嘘他兽穴中的一件新饰品。要是你想成为一名技艺纯熟的猎人，就去找他吧。', `FemaleText_loc5`='幾天前，我無意中聽雷格努斯·雷岩在武器大廳中吹噓他獸穴中的一件新飾品。要是你想成為一名技藝純熟的獵人，就去找他吧。', `FemaleText_loc7`='El otro día escuché por casualidad a Regnus Tronagranito en la Sala de Armas, jactándose de haber ganado un nuevo trofeo para su grupo. Si quieres instrucción de un cazador experto, Regnus es a quien tienes que ir a ver.' WHERE `ID`=5096;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법사', `MaleText_loc4`='法师', `MaleText_loc5`='法師', `MaleText_loc7`='Mago', `FemaleText_loc1`='마법사', `FemaleText_loc4`='法师', `FemaleText_loc5`='法師', `FemaleText_loc7`='Mago' WHERE `ID`=5097;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빙크라고 하는 자그마한 여자 마법사 하나가 신비의 전당에 있는데 마법의 도움이 필요하다면 그녀를 찾아가 보십시오.

신비의 전당은 아이언포지 성문 바로 북쪽에 있습니다.', `MaleText_loc4`='秘法大厅的法师彬克也许能帮忙解决你的一些魔法需求。

秘法大厅就在铁炉堡的北部。', `MaleText_loc5`='秘法大廳的巫師彬克也許能幫忙解決你的一些魔法需求。

秘法大廳就在鐵爐堡的北部。', `MaleText_loc7`='El pequeño encantador Bink, que está en la Sala de los Misterios, podría ayudarte en asuntos relacionados con la magia. 

La Sala de los Misterios está al norte de las puertas de Forjaz.', `FemaleText_loc1`='빙크라고 하는 자그마한 여자 마법사 하나가 신비의 전당에 있는데 마법의 도움이 필요하다면 그녀를 찾아가 보십시오.

신비의 전당은 아이언포지 성문 바로 북쪽에 있습니다.', `FemaleText_loc4`='秘法大厅的法师彬克也许能帮忙解决你的一些魔法需求。

秘法大厅就在铁炉堡的北部。', `FemaleText_loc5`='秘法大廳的法巫師彬克也許能幫忙解決你的一些魔法需求。

秘法大廳就在鐵爐堡的北部。', `FemaleText_loc7`='El pequeño encantador Bink, que está en la Sala de los Misterios, podría ayudarte en asuntos de magia.

La Sala de los Misterios está al norte de las puertas de Forjaz.' WHERE `ID`=5098;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이언포지 성문 북쪽의 신비의 전당에 가면 마법 기술을 배울 수 있습니다. 그곳에서 늘 책 속에 파묻혀 사는 율리 스톰케틀을 찾으십시오.', `MaleText_loc4`='去铁炉堡大门以北的神秘大厅，你会在那儿受到魔法训练的。朱莉·雷线总是在那儿埋头苦读。', `MaleText_loc5`='去鐵爐堡大門以北的秘法大廳，你會在那兒受到魔法訓練的。朱莉·雷線總是在那兒埋頭苦讀。', `MaleText_loc7`='Bueno, seguro que recibes instrucción en las artes mágicas en la Sala de los Misterios, al norte de las puertas de Forjaz. Juli Tormentacaldera siempre está allí inmersa en un libro.', `FemaleText_loc1`='아이언포지 성문 북쪽의 신비의 전당에 가면 마법 기술을 배울 수 있습니다. 그곳에서 늘 책 속에 파묻혀 사는 율리 스톰케틀을 찾으십시오.', `FemaleText_loc4`='去铁炉堡大门以北的神秘大厅，你会在那儿受到魔法训练的。朱莉·雷线总是在那儿埋头苦读。', `FemaleText_loc5`='去鐵爐堡大門以北的秘法大廳，你會在那兒受到魔法訓練的。朱莉·雷線總是在那兒埋頭苦讀。', `FemaleText_loc7`='Bueno, seguro que recibes instrucción en las artes mágicas en la Sala de los Misterios, al norte de las puertas de Forjaz. Juli Tormentacaldera siempre está allí inmersa en un libro.' WHERE `ID`=5099;
