UPDATE `locales_broadcast_text` SET `MaleText_loc1`='핌블 파인스핀들이 대용광로 북서쪽에 가게를 차렸습니다. 그 친구라면 가죽으로 제법 쓸만한 방어구를 만드는 방법을 알려줄 겁니다.', `MaleText_loc4`='费布·钢轴在大熔炉西北面开了一家商店。我打赌他能教你学会制作精良的装甲。', `MaleText_loc5`='費布·鋼軸在大鍛爐西北邊開了一家商店。我打賭他能教你學會製作精良的護甲。', `MaleText_loc7`='Fimble Bueneje tiene una tienda en la parte norte de la Gran Fundición. Apuesto lo que quieras a que podrá enseñarte cómo fabricar una buena armadura.', `FemaleText_loc1`='핌블 파인스핀들이 대용광로 북서쪽에 가게를 차렸습니다. 그 친구라면 가죽으로 제법 쓸만한 방어구를 만드는 방법을 알려줄 겁니다.', `FemaleText_loc4`='费布·钢轴在大熔炉西北面开了一家商店。我打赌他能教你学会制作精良的装甲。', `FemaleText_loc5`='費布·鋼軸在大鍛爐西北邊開了一家商店。我打賭他能教你學會製作精良的護甲。', `FemaleText_loc7`='Fimble Bueneje tiene una tienda en la parte norte de la Gran Fundición. Apuesto lo que quieras a que podrá enseñarte cómo fabricar una buena armadura.' WHERE `ID`=5135;
