UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자물쇠 따기 기술이라면 쓸쓸한 뒷골목에 사는 두르탐 그렐던이 상세히 가르쳐줄 겁니다. 단 아이언포지에서는 절대 연습하지 마십시오. 무슨 뜻인지 아시겠죠?', `MaleText_loc4`='荒弃的洞穴的杜尔萨姆·格雷顿能教你开锁的种种技能。要是你明白我的意思，就别在铁炉堡练习这些技能。', `MaleText_loc5`='荒棄的洞穴的杜爾薩姆·格雷頓能教你開鎖的種種技能。要是你明白我的意思，就別在鐵爐堡練習這些技能。', `MaleText_loc7`='Durtham Greldon, en La Caverna Abandonada, puede instruirte en el arte de la cerrajería. No deberás practicar este arte aquí en Forjaz, sabes a qué me refiero, ¿no?', `FemaleText_loc1`='자물쇠 따기 기술이라면 쓸쓸한 뒷골목에 사는 두르탐 그렐던이 상세히 가르쳐줄 겁니다. 단 아이언포지에서는 절대 연습하지 마십시오. 무슨 뜻인지 아시겠죠?', `FemaleText_loc4`='荒弃的洞穴的杜尔萨姆·格雷顿能教你开锁的种种技能。要是你明白我的意思，就别在铁炉堡练习这些技能。', `FemaleText_loc5`='荒棄的洞穴的杜爾薩姆·格雷頓能教你開鎖的種種技能。要是你明白我的意思，就別在鐵爐堡練習這些技能。', `FemaleText_loc7`='Durtham Greldon, en La Caverna Abandonada, puede instruirte en el arte de la cerrajería. No deberás practicar este arte aquí en Forjaz, sabes a qué me refiero, ¿no?' WHERE `ID`=5137;
