UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무두질을 배우고 싶은 거라면 발투스 스톤플레이어를 찾아가십시오. 가죽을 깔끔하게 벗겨내는 방법이라면 그 친구가 잘 가르쳐줄 겁니다. 대용광로 북쪽에 있는 파인스핀들의 가죽 상점으로 가면 됩니다.', `MaleText_loc4`='巴尔萨斯·裂石是一名剥皮师，他会教你如何剥皮的。去大熔炉北边的皮甲用品店找他吧。', `MaleText_loc5`='巴爾薩斯·剝石是一名剝皮師，他會教你如何剝皮的。去大鍛爐北邊的皮甲用品店找他吧。', `MaleText_loc7`='Balthus Cazarrocas es la persona indicada para instruirte en el oficio del desuello. Si tu presa puede desollarse, él te enseñará cómo hacerlo. Ve a Artículos de Cuero Bueneje, al noreste de La Gran Fundición.', `FemaleText_loc1`='무두질을 배우고 싶은 거라면 발투스 스톤플레이어를 찾아가십시오. 가죽을 깔끔하게 벗겨내는 방법이라면 그 친구가 잘 가르쳐줄 겁니다. 대용광로 북쪽에 있는 파인스핀들의 가죽 상점으로 가면 됩니다.', `FemaleText_loc4`='巴尔萨斯·裂石是一名剥皮师，他会教你如何剥皮的。去大熔炉北边的皮甲用品店找他吧。', `FemaleText_loc5`='巴爾薩斯·剝石是一名剝皮師，他會教你如何剝皮的。去大鍛爐北邊的皮甲用品店找他吧。', `FemaleText_loc7`='Balthus Cazarrocas es la persona indicada para instruirte en el oficio del desuello. Si tu presa puede desollarse, él te enseñará cómo hacerlo. Ve a Artículos de Cuero Bueneje, al noreste de La Gran Fundición.' WHERE `ID`=5141;
