UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 힘을 이 칼에 집중시켜야 하오. 그러면 이 칼과 관련된 영상을 더욱 확실하게 볼 수 있을 것이오.', `MaleText_loc4`='我要将我的精力集中在这把刀上。这样就能捕获与刀关联的更强的精神印象。', `MaleText_loc5`='我要將我的精力集中在這把刀上。這樣就能捕獲與刀關聯的更強的精神印象。', `MaleText_loc7`='Tendré que concentrar mis energías en este cuchillo. De este modo, podré percibir las impresiones psíquicas asociadas a él.' WHERE `ID`=5148;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이... 이제 충분히 본 것 같소... 정말 지치는군...', `MaleText_loc4`='我……我觉得我看够了……我已经筋疲力尽……', `MaleText_loc5`='我...我覺得我看夠了...我已經筋疲力盡...', `MaleText_loc7`='Yo... creo que ya he visto bastante... demasiado agotador...' WHERE `ID`=5149;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금까지 나는 고통에 시달려왔지만 이제 그 고통이 천천히 사라져가는 것 같구먼. 마치... 자유가 찾아온 듯해...', `MaleText_loc4`='我经受过痛苦，但是现在我能感觉到它正从我身上消退。我感到……自由了。', `MaleText_loc5`='我經受過痛苦，但是現在我能感覺到它正從我身上消退。我感到...自由了。', `MaleText_loc7`='He sufrido, pero ahora, puedo sentir cómo se va lentamente de mí. Me siento... libre.' WHERE `ID`=5150;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='운고로의 수정탑들은 모두에게 수수께끼 같은 존재입니다. 이곳의 몇 안 되는 거주자에게 수정탑은 전설의 근원으로, 그 용도에 관해서는 많은 추측이 있습니다.', `MaleText_loc4`='安戈洛的水晶塔相当神秘。对这里少数的居住者来说，它们代表某种传奇，而其建造目的则更值得深思了。', `MaleText_loc5`='安戈洛的水晶塔相當神秘。對這裡少數的居住者來說，它們代表某種傳奇，而其建造目的則更值得深思了。', `MaleText_loc7`='La Torre de cristal de Un''Goro es un misterio para todos. Para sus escasos habitantes, se trata de una suerte de leyenda, especulándose mucho acerca de su origen.' WHERE `ID`=5151;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수정탑 조사', `MaleText_loc4`='检查这座水晶塔。', `MaleText_loc5`='檢查這座水晶塔。', `MaleText_loc7`='Examina la torre.', `FemaleText_loc1`='수정탑 조사', `FemaleText_loc4`='检查这座水晶塔。', `FemaleText_loc5`='檢查這座水晶塔。', `FemaleText_loc7`='Examina la torre.' WHERE `ID`=5152;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수정탑은 자료를 다른 곳으로 전송하는 것처럼 보입니다.$b$b수정탑을 더 자세히 조사해보니 작은 탁자에 푸른, 노란, 녹색 수정이 일정한 구조를 이룬 듯 배열되어 있습니다.$B$B커다란 원형을 이룬 푸른 수정의 양쪽으로는 노란 수정과 녹색 수정이 각각 작은 원 모양으로 배열되어 있습니다.$B$B당신은 조심스럽게 눈앞의 광경을 적으며, 이 발견을 매우 흥미로워할 어떤 사람을 떠올립니다.', `MaleText_loc4`='这座水晶塔似乎正在向另外某个地方传输数据。$b$b仔细地检查了这座塔之后，你发现了一个由蓝色、黄色和绿色水晶组成的图样，它们以一种特殊的形态排列着。$B$B一大圈蓝色水晶两侧分别有一小圈黄色水晶和另一圈绿色水晶。$B$B你仔细观察水晶的颜色，一定会有人对你的发现很感兴趣。', `MaleText_loc5`='水晶塔似乎正在傳送什麼資料。$b$b仔細地檢查了這座塔之後，你發現了一個由藍色、黃色和綠色水晶組成的圖樣，它們以一種特殊的形態排列著。$B$B一大圈藍色水晶兩側分別有一小圈黃色水晶和另一圈綠色水晶。$B$B你仔細觀察水晶的顏色，知道有人一定會對你所發現的很感興趣。', `MaleText_loc7`='Parece que la torre está transmitiendo datos a algún lugar.$B$BUna inspección más detallada de la torre te permite encontrar una pequeña mesa con cristales amarillos, rojos y verdes dispuestos en una formación específica.$B$BUn gran círculo de cristales azules está flanqueado a cada lado por un círculo más pequeño de cristales amarillos y otro de cristales verdes.$B$BToma nota cuidadosamente de lo que ves, teniendo en cuenta que alguien podría estar muy interesado en escuchar lo que has descubierto.' WHERE `ID`=5153;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수정탑은 자료를 다른 곳으로 전송하는 것처럼 보입니다.$b$b수정탑을 더 자세히 조사해보니 작은 탁자에 노란, 붉은, 녹색 수정이 일정한 구조를 이룬 듯 배열되어 있습니다.$B$B커다란 원형을 이룬 노란 수정의 양쪽으로는 붉은 수정과 녹색 수정이 각각 작은 원 모양으로 배열되어 있습니다.$B$B당신은 조심스럽게 눈앞의 광경을 적으며, 이 발견을 매우 흥미로워할 어떤 사람을 떠올립니다.
', `MaleText_loc4`='这座水晶塔似乎正在向另外某个地方传输数据。$b$b仔细地检查了这座塔之后，你发现了一个由黄色、红色和绿色水晶组成的图样，它们以一种特殊的形态排列着。$B$B一大圈黄色水晶两侧分别有一小圈红色水晶和另一圈绿色水晶。$B$B你仔细观察水晶的颜色，一定会有人对你的发现很感兴趣。', `MaleText_loc5`='水晶塔似乎正在傳送什麼資料。$b$b仔細地檢查了這座塔之後，你發現了一個由黃色、紅色和綠色水晶組成的圖樣，它們以一種特殊的形態排列著。$B$B一大圈黃色水晶兩側分別有一小圈紅色水晶和另一圈綠色水晶。$B$B你仔細觀察水晶的顏色，知道有人一定會對你所發現的很感興趣。', `MaleText_loc7`='Parece que la torre está transmitiendo datos a algún lugar.$B$BUn examen detallado de la torre te permitirá encontrar una pequeña mesa con cristales amarillos, rojos y verdes, dispuestos en una formación específica.$B$BUn gran círculo de cristales amarillos está flanqueado a cada lado por un círculo más pequeño de cristales rojos y otro de cristales verdes.$B$BToma nota cuidadosamente de los colores de los cristales, teniendo en cuenta que alguien podría estar muy interesado en escuchar lo que has descubierto.' WHERE `ID`=5154;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수정탑은 자료를 다른 곳으로 전송하는 것처럼 보입니다.$b$b수정탑을 더 자세히 조사해보니 작은 탁자에 붉은, 푸른, 녹색 수정이 일정한 구조를 이룬 듯 배열되어 있습니다.$B$B커다란 원형을 이룬 붉은 수정의 양쪽으로는 푸른 수정과 녹색 수정이 각각 작은 원 모양으로 배열되어 있습니다.$B$B당신은 조심스럽게 눈앞의 광경을 적으며, 이 발견을 매우 흥미로워할 어떤 사람을 떠올립니다.', `MaleText_loc4`='这座水晶塔似乎正在向另外某个地方传输数据。$b$b仔细地检查了这座塔之后，你发现了一个由红色、蓝色和绿色水晶组成的图样，它们以一种特殊的形态排列着。$B$B一大圈红色水晶两侧分别有一小圈蓝色水晶和另一圈绿色水晶。$B$B你仔细观察水晶的颜色，一定会有人对你的发现很感兴趣。', `MaleText_loc5`='水晶塔似乎正在傳送什麼資料。$b$b仔細地檢查了這座塔之後，你發現了一個由紅色、藍色和綠色水晶組成的圖樣，它們以一種特殊的形態排列著。$B$B一大圈紅色水晶兩側分別有一小圈藍色水晶和另一圈綠色水晶。$B$B你仔細觀察水晶的顏色，知道有人一定會對你所發現的很感興趣。', `MaleText_loc7`='Parece que la torre está transmitiendo datos a algún lugar.$B$BUn examen detallado de la torre te permitirá encontrar una pequeña mesa con cristales rojos, azules y verdes, dispuestos en una formación específica.$B$BUn gran círculo de cristales rojos está flanqueado a cada lado por un círculo más pequeño de cristales azules y otro de cristales verdes.$B$BToma nota cuidadosamente de los colores de los cristales, teniendo en cuenta que alguien podría estar muy interesado en escuchar lo que has descubierto.' WHERE `ID`=5155;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에이미 집에 왔다! 에이미, 착해! 착해, 에이미. 집, 집, 집이다.', `MaleText_loc4`='A-Me回家！A-Me，好！回家。回家。回家。', `MaleText_loc5`='艾米回家!艾米，好!回家。回家。回家。', `MaleText_loc7`='¡Memo a casa! ¡Memo bueno! Memo bueno. Casa. Casa. Casa.' WHERE `ID`=5156;
