UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전 J.D.라고 해요. 어떻게 이곳에 오게 됐는가는 자세히 말 못하겠지만 이제 이 야영지가 제 집이라는 것만은 확실해요!$B$B전 분화구 주변에 널려 있는 신기한 수정들을 조사하면서 지낸답니다. 이곳으로 오는 길에 분명 뭔가를 본 듯하신데요. 대체 뭘 보신 건가요?', `FemaleText_loc4`='我叫科琳，我实在没法告诉你我是怎么到这儿来的，但是我可以告诉你，这个营地现在就是我家了！$B$B我在这儿研究环形山里随处可见的奇怪水晶。你在来这里的路上一定已经看见不少这样的水晶了。你有没有拾取一些水晶？', `FemaleText_loc5`='我叫科琳，我實在沒法告訴你我是怎麼到這兒來的，但是我可以告訴你，這個營地現在就是我家了!$B$B我在這兒研究環形山裡隨處可見的奇怪水晶。你在來這裡的途中一定看到過了吧。嘿，你有收集任何樣本嗎?', `FemaleText_loc7`='Me llamo J.D. y en realidad no puedo decirte cómo llegué hasta aquí, ¡pero lo que sí te puedo decir es que este campamento es ahora mi hogar!$B$BMe paso la vida estudiando los extraños cristales que se pueden encontrar por todo el cráter. Has tenido que ver algunas muestras en tu camino hacia aquí. Dime, ¿por casualidad has recogido alguna?' WHERE `ID`=5171;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아. 바로 이 맛이야!', `MaleText_loc4`='啊，太棒了！', `MaleText_loc5`='啊，太棒了!', `MaleText_loc7`='¡Ah, ha dado en el blanco!' WHERE `ID`=5172;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='존경해 마지않는 엘룬이시여. 저... 저 흉측한 곳에서 절 꺼내주셔서 감사합니다!', `MaleText_loc4`='亲爱的艾露恩，感谢你让我摆脱了……那个！', `MaleText_loc5`='親愛的伊露恩，感謝你讓我擺脫了...那個!', `MaleText_loc7`='Dulce Elune, gracias por sacarme... ¡de ese lugar espantoso!' WHERE `ID`=5173;
