UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서판을 옮겨 적습니다.', `MaleText_loc4`='拓下石板上的文字。', `MaleText_loc5`='拓下石板上的文字。', `MaleText_loc7`='Transcribe la tablilla.', `FemaleText_loc1`='서판을 옮겨 적습니다.', `FemaleText_loc4`='拓下石板上的文字。', `FemaleText_loc5`='拓下石板上的文字。', `FemaleText_loc7`='Transcribe la tablilla.' WHERE `ID`=5177;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서판의 기호를 조심스럽게 사본에 옮겨 새깁니다.', `MaleText_loc4`='石板上的符号被小心翼翼地拓了下来……', `MaleText_loc5`='石板上的符號被小心翼翼地拓了下來...', `MaleText_loc7`='Los símbolos de la tablilla se han transcrito cuidadosamente...' WHERE `ID`=5178;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하시오, $c. 어떤 이들에게 사냥은 삶의 방식이고 직업이지만, 다른 이들에게는 취미나 용맹의 증거가 되기도 하고, 또 부족에 따라서는 통과의례가 되기도 하지.$B$B내게 종족이나 직업 따위는 아무런 의미가 없소. 그대의 영혼과 정신을 시험하는 수단일 뿐... 자연의 힘에 맞서 모든 능력을 시험해보는 것이 진정한 명예의 징표라오.$B$B자신을 시험해보고 나의 존경을 얻고 싶거든 언제든지 날 찾아오시오.', `MaleText_loc4`='你好，$c。对于某些人来说，猎人是一种生活方式，是一种选定的职业。对于其他人来说，它是某种消遣，是勇气的象征，或是为了通过狩猎部族的仪式。$B$B对于我来说，种族和职业并不重要--我尊重的是你的灵魂和心智，而正是它们将要接受考验。当一个人独自面对自然的力量，竭力发挥其毕生所学之时，荣誉才会留下它真正的印记。$B$B如果你希望考验自己并赢得我的尊敬，那就跟我多谈谈。', `MaleText_loc5`='你好，$c。對於某些人來說，獵人是一種生活方式，一種所選的職業。對於其他人來說，這是用來消遣的東西，一個勇氣的徽章，或是依照你的部族所通過的某種祭儀。$B$B對於我來說，種族和職業什麼都不是，我所尊敬的是對你的靈魂和心智的測試。因為對自然力的抵抗和他們的技能的測試是真正榮譽的標誌。$B$B如果你希望檢測自己並贏得我的尊敬，那就跟我多談談。', `MaleText_loc7`='Saludos, $c. Para algunos, la caza es una forma de vida, una profesión que han elegido ellos. Para otros, es cosa del pasado, un símbolo de coraje, un rito de madurez, dependiendo de cada tribu.$B$BPara mí, la raza y la profesión no significan nada; lo que yo respeto es la capacidad de poner a prueba el espíritu y la mente. Tener la oportunidad de enfrentarse a las fuerzas de la naturaleza y poner a prueba las habilidades propias es una verdadera marca de honor.$B$BSi deseas probarte a ti $gmismo:misma; y ganar mi respeto, habla más conmigo.' WHERE `ID`=5179;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 그대는 명예로운 길을 걷기 시작한 것이오. 내 선조들은 그대의 의지에 존경을 보내고 있소. 하지만 나의 인정을 받기 위해서는 내가 주는 임무를 모두 완수해야 하오.$B$B그대가 진정한 사냥꾼임을 입증해 보이려면 무엇을 해야 하는지는 알고 있을 거라 생각하오.', `MaleText_loc4`='你正行进在一条光荣的道路上，$n。我的祖先尊敬你的意愿，但你在完成我所交付的任务之前我不会对你有任何认可的。$B$B如果你希望证明在精神层面是一个猎手的话你该知道你必须做什么。', `MaleText_loc5`='你正行進在一條光榮的道路上，$n。我的祖先尊敬你的意願，但在完成我所交付的任務之前你將不會擁有任何我對你的認可。$B$B如果你想要證明你在精神上是一個獵手的話你該知道你必須做些什麼。', `MaleText_loc7`='Has iniciado un camino honorable, $n. Mis ancestros respetan tu voluntad, pero no tendrás mi aprobación hasta que no hayas seguido paso a paso mis instrucciones.$B$BDebes saber lo que tienes que hacer si deseas saber si tienes espíritu de $gcazador:cazadora;.' WHERE `ID`=5181;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오게. 우리 으스러진 손에서는 자네를 환영하는 바이네.$B$B그리 놀란 표정 지을 것 없네, $n. 세상 모든 곳에는 음지가 필요하지. 이곳 오그리마에도 그림자는 있네. 어두운 곳에 숨겨져 있는 무언가가... 우리 으스러진 손이 그 역할을 맡은 것뿐이야. 스랄 님도 오크와 트롤의 안전을 위해서는 으스러진 손이 꼭 필요하다는 것을 인정하고 있네.$B$B지금은... 그 일에 대해 의논하러 온 게 아니라 다른 일 때문에 온 거겠지?', `MaleText_loc4`='我和碎手都向你致敬，$c。$B$B别这么惊讶，$n。连奥格瑞玛最高的地方也会有阴影——一定有什么东西隐藏在那儿。碎手欣然接受了那项任务。萨尔也承认要确保兽人和巨魔的安全，他是不可缺少的。$B$B但是你到这儿来不是谈论我的事儿吧，你一定另有目的。', `MaleText_loc5`='我和破碎之手都向你致敬，$c。$B$B別這麼驚訝，$n。連奧格瑪最高的地方也會有陰影─一定有什麼東西隱藏在那兒。破碎之手欣然接受了那項任務。索爾也承認要確保獸人和食人妖的安全，他是不可缺少的。$B$B但是你到這兒來不是談論我的事兒吧，你一定另有目的。', `MaleText_loc7`='Te doy mi más cordial bienvenida, $c, como hacen los Mano Destrozada.$B$BNo te sorprendas tanto, $n. Hay sombras incluso en los puntos más altos de Orgrimmar, algo debe de esconderse allí. Los Mano Destrozada juegan ese papel gustosamente. Incluso el bueno de Thrall reconoce que los Mano Destrozada son necesarios para garantizar la seguridad de los orcos y los trols.$B$BPero no has venido aquí para hablar de mi oficio, has venido para otra cosa.' WHERE `ID`=5182;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='운고로 분화구는 타나리스의 버섯구름 봉우리 너머 칼림도어 남쪽 멀리 있네. 가거든 둥둥 떠 있는 커다란 바위를 찾게나. 그 바위가 분화구로 들어가는 입구니까 말이야. 하지만 조심하게... 결코 쉬운 길은 아니라네. 입구에서 그리 멀지 않은 곳에 랩터들이 살고 있을 게야.', `MaleText_loc4`='安戈洛环形山在卡利姆多南部，位于塔纳利斯沙漠的西面。去寻找巨大的浮空石……它们是环形山入口的标志。但是要小心，那里可是很危险的，迅猛龙就在入口附近徘徊。', `MaleText_loc5`='安戈洛環形山在卡林多南部，位於塔納利斯那裡千針石林沙漠的後面。去尋找巨大的浮空石...它們是環形山入口的標誌。但是要小心，那裡可是很危險的，迅猛龍就在入口附近徘徊。', `MaleText_loc7`='El Cráter de Un''Goro está lejos, al sur de Kalimdor. Más allá de las Mil Agujas en Tanaris. Busca las grandes piedras flotantes... marcan la entrada del Cráter. Pero ten cuidado... no se trata de un camino fácil. Hay raptores no muy lejos de la entrada.' WHERE `ID`=5183;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='운고로 분화구는 어디에 있습니까?', `MaleText_loc4`='安戈洛环形山在哪儿？', `MaleText_loc5`='安戈洛環形山在哪兒?', `MaleText_loc7`='¿Dónde está el cráter de Un''Goro?', `FemaleText_loc1`='운고로 분화구는 어디에 있습니까?', `FemaleText_loc4`='安戈洛环形山在哪儿？', `FemaleText_loc5`='安戈洛環形山在哪兒?', `FemaleText_loc7`='¿Dónde está el cráter de Un''Goro?' WHERE `ID`=5184;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신 덕에 신비한 수정탑과 수정의 수수께끼를 풀 수 있게 됐어요, $n. 언제라도 정보가 더 필요하시면 날 다시 찾아오세요!', `FemaleText_loc4`='谢谢你，现在我们能解开水晶和神秘的水晶塔的秘密了，$n。要是你需要更多信息，请随时回来找我！', `FemaleText_loc5`='謝謝你，現在我們能解開水晶和神秘的水晶塔的秘密了，$n。要是你需要更多資訊，請隨時回來找我!', `FemaleText_loc7`='Gracias a ti, podemos desentrañar los secretos de los cristales y las torres misteriosas, $n. Si necesitas más información en cualquier momento, ¡ven a verme en otra ocasión!' WHERE `ID`=5185;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동쪽 수정탑에 대해 더 말씀해 주십시오.', `MaleText_loc4`='请告诉我关于东部水晶塔的事情。', `MaleText_loc5`='請告訴我關於東部水晶塔的事情。', `MaleText_loc7`='Háblame más sobre la Torre de cristal del Este.', `FemaleText_loc1`='동쪽 수정탑에 대해 더 말씀해 주십시오.', `FemaleText_loc4`='请告诉我关于东部水晶塔的事情。', `FemaleText_loc5`='請告訴我關於東部水晶塔的事情。', `FemaleText_loc7`='Háblame más sobre la Torre de cristal del Este.' WHERE `ID`=5186;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방금 말씀하신 라르코르위는 누굽니까?', `MaleText_loc4`='你所说的这个拉克维是谁？', `MaleText_loc5`='你所說的這個拉克維是誰?', `MaleText_loc7`='¿Quién es ese Lar''korwi del que me has hablado?', `FemaleText_loc1`='방금 말씀하신 라르코르위는 누굽니까?', `FemaleText_loc4`='你所说的这个拉克维是谁？', `FemaleText_loc5`='你所說的這個拉克維是誰?', `FemaleText_loc7`='¿Quién es ese Lar''korwi del que me has hablado?' WHERE `ID`=5187;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='북쪽 수정탑에 대해 더 말씀해 주십시오.', `MaleText_loc4`='请告诉我关于北部水晶塔的事情。', `MaleText_loc5`='請告訴我關於北部水晶塔的事情。', `MaleText_loc7`='Háblame más sobre la Torre de cristal del Norte.', `FemaleText_loc1`='북쪽 수정탑에 대해 더 말씀해 주십시오.', `FemaleText_loc4`='请告诉我关于北部水晶塔的事情。', `FemaleText_loc5`='請告訴我關於北部水晶塔的事情。', `FemaleText_loc7`='Háblame más sobre la Torre de cristal del Norte.' WHERE `ID`=5188;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 운고로 분화구에 서식하는 라바사우루스는 불모의 땅에 서식하는 랩터와 분명히 어떤 관련이 있는 듯하오. 아주 지능이 높고 포악할 뿐 아니라 행동 지침 같은 것도 있소. 지금까지 내 눈으로 본 중에서 라르코르위라는 녀석이 가장 거대한데 그 어떤 짐승보다 위험한 녀석이오... 타우렌어로 라르코르위란 ''뾰족한 발톱''이란 뜻인데, 그 말만으로는 녀석을 제대로 설명할 수 없지.$B$B라르코르위를 사냥할 생각이라면 녀석을 과소평가하지 마시오. 그리고 내가 힘닿는 데까지 도와주겠소이다.', `MaleText_loc4`='安戈洛的暴掠龙看起来与贫瘠之地的迅猛龙有些共同点--非常聪明，十分灵活，并且似乎具有着某种程度的行为智能，或者说遵循着某种行为准则。其中我所遇到的最强大的是拉克维。他是我所见过的最危险的动物之一。在牛头人语里，拉克维的意思是“锋利的爪子”，但这个名字并不足以恰如其分的描述他的可怕。$B$B如果你计划猎杀拉克维的话，千万不要低估他，但如果你决定要这样做，无论如何我都会帮你的。', `MaleText_loc5`='安戈洛這裡的暴掠龍看起來與貧瘠之地的迅猛龍有關，非常聰明，十分靈活，還有相似的行為準則。其中我所遇到的最偉大的是拉克維。他是我所見過的最危險的動物之一。在牛頭人語，拉克維的意思是「鋒利的爪子」，但那對他並不公平。$B$B如果你計畫獵殺拉克維的話，千萬不要低估他，但如果你決定要這樣做，無論如何我都會幫你的。', `MaleText_loc7`='Al parecer, el ravasaurio de Un''Goro está relacionado con los raptores de los baldíos: es muy inteligente, imprevisible, y sigue un código de conducta determinado. El más ravasaurio más grande que he encontrado es Lar''korwi. Es una de las bestias más peligrosas que he visto jamás. En taurahe, Lar''korwi significa "garra afilada," pero este detalle no le hace justicia.$B$BNo subestimes a Lar''korwi si piensas cazarlo, pero te ayudaré en lo que pueda si lo haces.' WHERE `ID`=5189;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서쪽 수정탑에 대해 더 말씀해 주십시오.', `MaleText_loc4`='请告诉我关于西部水晶塔的事情。', `MaleText_loc5`='請告訴我關於西部水晶塔的事情。', `MaleText_loc7`='Háblame más sobre la Torre de cristal del Oeste.', `FemaleText_loc1`='서쪽 수정탑에 대해 더 말씀해 주십시오.', `FemaleText_loc4`='请告诉我关于西部水晶塔的事情。', `FemaleText_loc5`='請告訴我關於西部水晶塔的事情。', `FemaleText_loc7`='Háblame más sobre la Torre de cristal del Oeste.' WHERE `ID`=5190;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수정탑 사용설명서를 잃어버렸습니다. 새것이 하나 필요합니다.', `MaleText_loc4`='我把水晶塔使用手册弄丢了，能再给我一份吗？', `MaleText_loc5`='我把水晶塔使用手冊弄丟了，能再給我一份嗎?', `MaleText_loc7`='He perdido mi Manual de instrucciones de la Torre de cristal y necesito otro.', `FemaleText_loc1`='수정탑 사용설명서를 잃어버렸습니다. 새것이 하나 필요합니다.', `FemaleText_loc4`='我把水晶塔使用手册弄丢了，能再给我一份吗？', `FemaleText_loc5`='我把水晶塔使用手冊弄丟了，能再給我一份嗎?', `FemaleText_loc7`='He perdido mi Manual de instrucciones de la Torre de cristal y necesito otro.' WHERE `ID`=5191;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='동쪽 수정탑에는 푸른, 노란, 녹색 수정이 들어가지요.$B$B동쪽 수정탑의 주된 마력 원천은 푸른 수정이 만들어내는 에너지인데, 이 경우 두 가지 결과가 나올 수 있어요. 하나는 정신력이 높아지는 것이고 다른 하나는 상대에게 피해를 주는 방어막이 생성되는 것이에요.$B$B정신력의 수정에는 푸른 수정과 녹색 수정이 필요해요. 이 경우 정신력을 높일 수 있어요.$B$B그리고 돌기의 수정에는 푸른 수정과 노란 수정이 필요해요. 이 수정은 공격하는 자에게 피해를 주는 방어막을 생성하지요.', `FemaleText_loc4`='东方的水晶塔接受蓝色，黄色，还有绿色的水晶。$B$B它专注于使用蓝色水晶作为主要力量之源而产生的能量。有两种可能的效果：一种对精神有益，而另一种产生一种破坏性的护盾。$B$B精神水晶需要蓝色和绿色的水晶。这将会增加你的勇气。$B$B尖刺水晶需要蓝色和黄色的水晶。这会产生一个对攻击者造成伤害的护盾。', `FemaleText_loc5`='東部水晶塔接受藍色，黃色，還有綠色的水晶。$B$B它專注於使用藍色水晶作為主要力量之源而產生的能量。有兩種可能的效果:一種對精神有益，而另一種產生一種破壞性的護盾。$B$B精神水晶需要藍色和綠色的水晶。這將會增加你的勇氣。$B$B尖刺水晶需要藍色和黃色的水晶。這會產生一個對攻擊者造成傷害的護盾。', `FemaleText_loc7`='La Torre de Cristal del Este acepta cristales azules, amarillos y verdes.$B$BSe centra en la energía que puede crearse usando cristales azules como fuente principal de poder. Existen dos efectos posibles: uno proporciona puntos adicionales para el espíritu y el otro crea un escudo de ataque.$B$BLa fuerza de los cristales requiere cristales azules y verdes. Esto fortalecerá tu espíritu.$B$BLa aguja de cristal requiere el uso de cristales azules y amarillos. Esto creará un escudo que perjudica a los atacantes.' WHERE `ID`=5192;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='북쪽 수정탑에는 노란, 붉은, 녹색 수정이 들어가지요.$B$B북쪽 수정탑의 주된 마력 원천은 노란 수정이 만들어내는 에너지인데, 이 경우 두 가지 결과가 나올 수 있어요. 하나는 상대에게 피해를 주는 것이고, 다른 것은 상대에게 입은 피해를 무효로 하는 것이지요.$B$B발화의 수정에는 붉은 수정과 노란 수정이 필요해요. 이 경우 적진 한가운데서 큰 폭발을 일으킬 수 있어요.$B$B그리고 회복의 수정에는 노란 수정과 녹색 수정이 필요해요. 이 경우에는 생명력을 회복하는 치유의 오라가 생성되지요.', `FemaleText_loc4`='北方的水晶塔接受黄红绿三种颜色的水晶构成。$B$B而关键是使用黄水晶所产生的能量作为主要的力量来源。有两种可能的效果：一种会制造破坏，一种会消除破坏。$B$B爆炸水晶需要红水晶和黄水晶。这将产生剧烈爆炸，足以震慑你的敌人。$B$B恢复水晶需要黄水晶和绿水晶。这将给你提供治疗光环。', `FemaleText_loc5`='北部水晶塔接受黃紅綠三種顏色的水晶構成。$B$B而關鍵是使用黃水晶所產生的能量作為主要的力量來源。有兩種可能的效果:一種會製造破壞，一種會消除破壞。$B$B爆炸水晶需要紅水晶和黃水晶。這將產生劇烈爆炸，足以震懾你的敵人。$B$B恢復水晶需要黃水晶和綠水晶。這將給你提供治療光環。', `FemaleText_loc7`='La Torre de Cristal del Norte acepta cristales amarillos, rojos y verdes.$B$BSe centra en la energía que puede crearse usando cristales amarillos como fuente principal de poder. Existen dos efectos posibles: uno produce daño y el otro lo niega. $B$BLa carga de cristal requiere cristales rojos y amarillos. Esto producirá una gran explosión, asustando a tus enemigos.$B$BEl cristal de restauración requiere el uso de cristales amarillos y verdes. Este cristal te proporcionará un aura de curación.' WHERE `ID`=5193;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='서쪽 수정탑에는 붉은, 녹색, 푸른 수정이 들어가지요.$B$B서쪽 수정탑의 주된 마력 원천은 붉은 수정이 만들어내는 에너지인데, 이 경우 두 가지 결과가 나올 수 있어요. 하나는 방어력이 높아지는 것이고, 다른 하나는 적의 방어력이 약해지는 것이지요.$B$B수호의 수정에는 붉은 수정과 녹색 수정이 필요해요. 이 경우 방어도를 높일 수 있어요.$B$B그리고 굴복의 수정에는 푸른 수정과 붉은 수정이 필요해요. 이 경우에는 적의 방어도를 약하게 할 수 있지요.', `FemaleText_loc4`='西方的水晶塔接受红色，绿色和蓝色的水晶。$B$B塔门关键是要用红色水晶作为力量源泉而产生的能量。可能有两种结果：一种能提高你的防御力，而另一种则是削弱敌人的防御。$B$B防御水晶需要红色和绿色的水晶。这将会使你的装甲更完备。$B$B破甲水晶需要蓝色和红色的水晶。这将会削弱即定目标的装甲防御。', `FemaleText_loc5`='西部水晶塔接受紅色，綠色和藍色的水晶。$B$B塔門關鍵是要用紅色水晶作為力量源泉而產生的能量。可能有兩種結果:一種能提高你的防禦力，而另一種則是削弱敵人的防禦。$B$B防禦水晶需要紅色和綠色的水晶。這將會使你的裝甲更完備。$B$B破甲水晶需要藍色和紅色的水晶。這將會削弱即定目標的裝甲防禦。', `FemaleText_loc7`='La Torre de Cristal del Oeste acepta cristales rojos, verdes y azules.$B$BLa torre se centra en la energía que puede crearse usando cristales rojos como fuente principal de poder. Existen dos efectos posibles: uno para aumentar la protección contra el daño y otro para debilitar las defensas del enemigo.$B$BLa protección de cristal requiere el uso de cristales rojos y verdes. Esto fortalecerá tu armadura.$B$BEl rendimiento de cristal requiere el uso de cristales azules y rojos. Puede debilitar la armadura de un blanco específico.' WHERE `ID`=5194;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='새로 하나 드리지요. 여기 받으세요, $n.', `FemaleText_loc4`='当然的事情，$n。还有一个给你。', `FemaleText_loc5`='當然的事情，$n。還有一個給你。', `FemaleText_loc7`='Claro, $n. Aquí hay otro para ti.' WHERE `ID`=5195;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고치 안에 있는 인간형 생물의 윤곽이 흐릿하게 보입니다. 이제서야 이곳이 꼭 와야 했던 곳이라는 것을 알 수 있습니다. 나중에는 고치를 열 수 있을 것 같지만 지금은 아무리 애를 써서 열려고 해도 열리지 않습니다.', `MaleText_loc4`='你在虫茧里看到了模糊的人体轮廓，你现在知道这就是你要找的地方了。虽然你认为自己可以打开虫茧，但即使你用尽全力，它还是紧紧地关着。', `MaleText_loc5`='你在蟲繭裡看到了模糊的人體輪廓，你現在知道這就是你要找的地方了。雖然你認為自己可以打開蟲繭，但即使你用盡全力，它還是緊緊地關著。', `MaleText_loc7`='Puedes ver el contorno difuso de una figura humanoide dentro de la vaina. Ahora sabes que es ahí donde debes estar. Aun cuando creas que podrás abrir la vaina, esta permanecerá cerrada por más fuerza que apliques al intentar abrirla.' WHERE `ID`=5196;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 새로운 대상을 공격합니다!', `MaleText_loc4`='%s攻击新的目标！', `MaleText_loc5`='%s攻擊新的目標!', `MaleText_loc7`='¡%s ataca un nuevo blanco!' WHERE `ID`=5197;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 완벽한 모자로군!', `MaleText_loc4`='拿你做个新帽子肯定不错，$r！', `MaleText_loc5`='拿你做個新帽子肯定不錯，$r!', `MaleText_loc7`='¡Vales perfectamente para hacer un pequeño sombrero, $r!' WHERE `ID`=5198;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오그라비시는 새 모자가 필요해!', `MaleText_loc4`='奥格拉比斯需要新的帽子！', `MaleText_loc5`='奧格拉比斯需要新的帽子!', `MaleText_loc7`='¡Ograbisi necesita nuevo sombrero!' WHERE `ID`=5199;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 쓰레기가 감히 내 방에 들어오는 것이냐!?', `MaleText_loc4`='谁胆敢进入我的房间！？', `MaleText_loc5`='誰膽敢進入我的房間!?', `MaleText_loc7`='¡¿Qué clase de basura osa entrar en mi recinto?!' WHERE `ID`=5200;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정화할 때에 맞춰 잘 왔다. 네 영혼의 불결함을 깨끗이 씻어내 주마.', `MaleText_loc4`='啊，刚好赶上你的净化仪式，$c。我将清除你灵魂中的杂质。', `MaleText_loc5`='啊，剛好趕上你的淨化儀式，$r。我將清除你靈魂中的雜質。', `MaleText_loc7`='Ah, has llegado justo a tiempo para limpiarte, $r. Barreré las impurezas de tu alma.' WHERE `ID`=5201;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 사랑 토비아스, 당신이오?', `MaleText_loc4`='我亲爱的图比亚斯，是你吗？', `MaleText_loc5`='我親愛的托比亞斯，是你嗎?', `MaleText_loc7`='¿¿¿Eres tú, mi querido Tobías???' WHERE `ID`=5202;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신과 볼일이 끝나면 오그라비시가 당신 머리를 작은 모자로 쓸 지도 모르겠군.', `MaleText_loc4`='当我厌倦你时，或许奥格拉比斯会拿你的脑袋做一顶小帽子。', `MaleText_loc5`='當我厭倦你時，或許奧格拉比斯會拿你的腦袋做一頂小帽子。', `MaleText_loc7`='Quizás Ograbisi use tu cabeza como pequeño sombrero cuando acabe contigo.' WHERE `ID`=5203;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='한 때는 아름다웠던 이 숲이 끔찍한 저주에 걸려 고통받고 있어요! 타락한 세력이 이곳 생명체들을 변형시키고 있답니다. 자신들의 모습을 닮은 어두운 그림자로 만들려는 것 같아요. 당신이 이 타락의 앞잡이가 아니라면 저를 도와 악령숲을 정화할 수 있을지도 모르겠군요.', `FemaleText_loc4`='这片美丽的森林受到了可怕的诅咒！腐化的力量将这儿变成了一片恐惧之地。如果你跟他们不是一伙的，或许你能帮助我夺回费伍德森林。', `FemaleText_loc5`='這片美麗的森林受到了可怕的詛咒!腐化的力量將這兒變成了一片恐懼之地。如果你跟他們不是一夥的，或許你能幫助我奪回費伍德森林。', `FemaleText_loc7`='¡Estos bosques, antaño hermosos, han sucumbido al embrujo de una terrible maldición! Ciertas fuerzas malignas convierten la vida en sombras de lo que antes existió. Si no eres agente de este mal, ¡quizás entonces puedas ayudarme a reclamar Frondavil!' WHERE `ID`=5204;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 갑시다. 이쪽으로 가면 있는 저장소에 내 장비들이 있을 거요...', `MaleText_loc4`='我们行动吧。我的装备应该在这条路上的某个储物间里。', `MaleText_loc5`='我們行動吧。我的裝備應該在這條路上的某個儲物間裡。', `MaleText_loc7`='Démonos prisa. Mis herramientas deberían estar en el almacén por aquí...' WHERE `ID`=5205;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='"타우렌어?"$B$B타우렌 드루이드가 기대에 가득 찬 눈길로 당신을 바라보지만, 그녀와 의사소통을 할 수는 없는 게 분명합니다. 하지만 그녀는 아무렇지 않은 듯 손가락으로 자신을 가리키며 미소를 지어 보이더니, 이번에는 당신을 가리키며 한 번 더 미소를 지어 보입니다. 그리고 마지막으로 남쪽으로 난 길을 여러 번 가리킵니다.$B$B혹시 이 길을 따라가면 언어가 통하는 드루이드가 있다는 뜻일까요?', `FemaleText_loc4`='“牛头人语？”$B$B牛头人德鲁伊满怀期望地看着你，但是你显然无法跟她沟通。她微笑着指向自己，然后指着你。最后她向南面的道路指了几下。$B$B或许她是在说那里有能跟你进行交谈的德鲁伊？', `FemaleText_loc5`='「牛頭人語?」$B$B牛頭人德魯伊滿懷期望地看著你，但是你顯然無法跟她溝通。她微笑著指向自己，然後指著你。最後她向南面的道路指了幾下。$B$B或許她是在表示南面道路的前方有可以跟你進行交談的德魯伊?', `FemaleText_loc7`='«¿Taurahe?»$B$BLa druida tauren te observa con expectación pero está claro que no te puedes comunicar con ella verbalmente. Impertérrita, se señala a sí misma y sonríe. Te señala a ti y sonríe de nuevo. Finalmente hace varios gestos señalando el camino hacia el sur.$B$BQuizás quiera indicarte que hay un druida con el que puedes hablar siguiendo el camino.' WHERE `ID`=5206;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 방을 살펴보시오, $n. 아직도 살아 있는 자가 있다면 꺼내주어야 하오.', `MaleText_loc4`='检查那间牢房，$n。如果那里还有人活着，我们就得把他们救出来。', `MaleText_loc5`='檢查那間牢房，$n。如果那裡還有人活著，我們就得把他們救出來。', `MaleText_loc7`='Comprueba esa celda, $n. Si todavía hay vivos dentro, tendremos que sacarlos de ahí.' WHERE `ID`=5207;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='한 때는 아름다웠던 이 숲이 끔찍한 저주에 걸려 고통받고 있어요! 타락한 세력이 이곳 생명체들을 변형시키고 있답니다. 자신들의 모습을 닮은 어두운 그림자로 만들려는 것 같아요. 당신이 이 타락의 앞잡이가 아니라면 저를 도와 악령숲을 정화할 수 있을지도 모르겠군요.', `FemaleText_loc4`='这片美丽的森林受到了可怕的诅咒！腐化的力量将这儿变成了一片恐惧之地。如果你跟他们不是一伙的，或许你能帮助我夺回费伍德森林。', `FemaleText_loc5`='這片美麗的森林受到了可怕的詛咒!腐化的力量將這兒變成了一片恐懼之地。如果你跟他們不是一夥的，或許你能幫助我奪回費伍德森林。', `FemaleText_loc7`='¡Estos bosques, antaño hermosos, han sucumbido al embrujo de una terrible maldición! Ciertas fuerzas malignas convierten la vida en sombras de lo que antes existió. Si no eres agente de este mal, ¡quizás entonces puedas ayudarme a reclamar Frondavil!' WHERE `ID`=5208;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='"다르나서스어?"$B$B나이트 엘프 드루이드가 기대에 가득 찬 눈길로 당신을 바라보지만, 그녀와 의사소통을 할 수 없다는 것이 명백합니다. 하지만 그녀는 아무렇지 않은 듯 손가락으로 자신을 가리키며 미소를 지어 보이더니, 이번에는 당신을 가리키며 한 번 더 미소를 지어 보입니다. 그리고 마지막으로 북쪽으로 난 길을 여러 번 가리킵니다.$B$B혹시 이 길을 따라가면 얘기를 나눌 수 있는 드루이드가 있다고 얘기하는 것일까요?', `FemaleText_loc4`='“达纳苏斯语？”$B$B暗夜精灵德鲁伊满怀期望地看着你，但是你显然无法跟她沟通。她微笑着指向自己，然后指着你。最后她向北面的道路指了几下。$B$B或许她是在说那边有能跟你进行交谈的德鲁伊？', `FemaleText_loc5`='「達納蘇斯語?」$B$B夜精靈德魯伊滿懷期望地看著你，但是你顯然無法跟她溝通。她微笑著指向自己，然後指著你。最後她向北面的道路指了幾下。$B$B或許她是在表示北面道路的前方有可以跟你進行交談的德魯伊?', `FemaleText_loc7`='"¿Darnassae?"$B$BLa druida de los elfos de la noche te mira expectante, pero está claro que no puedes comunicarte verbalmente con ella. Impertérrita, se señala a sí misma y sonríe. Te señala a ti y sonríe de nuevo. Finalmente hace varios gestos señalando el camino hacia el norte.$B$BQuizás quiera indicarte que hay un druida con el que puedes hablar siguiendo el camino.' WHERE `ID`=5209;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙소, $n! 난 이제 자유요!!!', `MaleText_loc4`='谢谢你，$n！我自由了！！！', `MaleText_loc5`='謝謝你，$n!我自由了!!!', `MaleText_loc7`='¡Gracias, $n! ¡¡¡Soy libre!!!' WHERE `ID`=5210;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살려주시오!!!', `MaleText_loc4`='救命！！！！', `MaleText_loc5`='救命!!!!', `MaleText_loc7`='¡¡¡SOCORRO!!!' WHERE `ID`=5211;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 이제 자유입니다, 더그할! 어서 여길 빠져나가십시오!', `MaleText_loc4`='你自由了，杜格哈尔！快出去！', `MaleText_loc5`='你自由了，杜格哈爾!快出去!', `MaleText_loc7`='¡Eres libre, Dughal! ¡Márchate!', `FemaleText_loc1`='당신은 이제 자유입니다, 더그할! 어서 여길 빠져나가십시오!', `FemaleText_loc4`='你自由了，杜格哈尔！快出去！', `FemaleText_loc5`='你自由了，杜格哈爾!快出去!', `FemaleText_loc7`='¡Eres libre, Dughal! ¡Márchate!' WHERE `ID`=5212;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘했소! 거의 다 왔소이다! 이쪽이오.', `MaleText_loc4`='干得好！我们差不多成功了！这边走。', `MaleText_loc5`='幹得好!我們差不多成功了!走這邊。', `MaleText_loc7`='¡Buen trabajo! Estamos a punto de llegar. Por aquí.' WHERE `ID`=5213;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기요, $n. 내 장비가 저 방 안에 있을 거요. 방으로 들어 갈 테니 날 엄호해주시오!', `MaleText_loc4`='没错，$n，我的东西都在那个房间里。保护我，我准备冲进去了！', `MaleText_loc5`='沒錯，$n，我的東西都在那個房間裡。保護我，我準備衝進去了!', `MaleText_loc7`='Aquí es, $n. Mis cosas tienen que estar en esa habitación. ¡Cúbreme, voy a entrar!' WHERE `ID`=5214;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 저기 있군!', `MaleText_loc4`='啊，它在那儿！', `MaleText_loc5`='啊，它在那兒!', `MaleText_loc7`='Ah, ahí está.' WHERE `ID`=5215;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘이 느껴지시오, $n? 이제 한판 붙어봐야지!', `MaleText_loc4`='你能感受到这力量吗，$n？让我们舞动起来吧！', `MaleText_loc5`='你能感受到這力量嗎，$n?讓我們舞動起來吧!', `MaleText_loc7`='¿¿¿Sientes el poder, $n??? ¡Es hora de JUGAR!' WHERE `ID`=5216;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 토비아스를 구하기만 하면 여기서 빠져나갈 수 있소. 이쪽으로!', `MaleText_loc4`='我们只需解放图比亚斯，然后就能离开这儿了。这边走！', `MaleText_loc5`='我們只需解放托比亞斯，然後就能離開這兒了。這邊走!', `MaleText_loc7`='Ahora solo tenemos que liberar a Tobías y podremos salir de aquí. ¡Por aquí!' WHERE `ID`=5217;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='됐소!! 이제 이 쓰레기 더미 같은 곳을 빠져나갈 수 있겠어.', `MaleText_loc4`='我终于可以离开这个垃圾场了！！', `MaleText_loc5`='我終於可以離開這個垃圾場了!!', `MaleText_loc7`='¡Por fin! Puedo irme de este vertedero.' WHERE `ID`=5218;
