UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 여길 빠져나가십시오, 토비아스. 당신은 이제 자유입니다!', `MaleText_loc4`='出去吧，图比亚斯，你自由了！', `MaleText_loc5`='出去吧，托比亞斯，你自由了!', `MaleText_loc7`='¡Sal de aquí, Tobias! ¡Eres libre!', `FemaleText_loc1`='어서 여길 빠져나가십시오, 토비아스. 당신은 이제 자유입니다!', `FemaleText_loc4`='出去吧，图比亚斯，你自由了！', `FemaleText_loc5`='出去吧，托比亞斯，你自由了!', `FemaleText_loc7`='¡Sal de aquí, Tobias! ¡Eres libre!' WHERE `ID`=5220;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 잘했소, $n. 이제 출구를 찾읍시다. 출구가 어디 있는지 알 것도 같으니 날 따라오시오!', `MaleText_loc4`='干得很好，$n。让我们去找出口吧。我想我知道该怎么走，跟着我！', `MaleText_loc5`='幹得很好，$n。讓我們去找出口吧。我想我知道該怎麼走，跟著我!', `MaleText_loc7`='Excelente trabajo, $n. Encontremos la salida. Creo que conozco el camino. ¡Seguidme!' WHERE `ID`=5221;
