UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 저 둘이 처음부터 마음에 들지 않았다오. 어서 갑시다.', `MaleText_loc4`='我从未喜欢过那两个家伙。我们继续前进吧。', `MaleText_loc5`='我從未喜歡過那兩個傢伙。我們繼續前進吧。', `MaleText_loc7`='Nunca hice lo que esos dos. Vámonos de aquí.' WHERE `ID`=5223;
