UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 형편 없는 고집불통 녀석이 마침내 응당한 벌을 받은 거요. 속이 다 후련하군!', `MaleText_loc4`='那个愚蠢的家伙真是罪有应得！', `MaleText_loc5`='那個愚蠢的傢伙真是罪有應得!', `MaleText_loc7`='Ese maldito intolerante finalmente recibió su merecido. ¡Adiós y hasta nunca!' WHERE `ID`=5225;
