UPDATE `locales_broadcast_text` SET `MaleText_loc1`='열어보시오. 서둘러야 하오. 나는 멀리서도 검은무쇠 녀석들이 오고 있는 것을 냄새로 알 수 있지. 그리고 한가지 확실한 것은 지금 그들이 오고 있다는 것이오!!!', `MaleText_loc4`='打开它。我们要抓紧时间。我已经可以闻到黑铁军团的气味了，我可以告诉你，他们就要来了！', `MaleText_loc5`='打開它。我們要抓緊時間。我已經可以聞到黑鐵軍團的氣味了，我可以告訴你，他們就要來了!', `MaleText_loc7`='Ábrela. Tenemos que darnos prisa. Puedo oler a esos Hierro Negro a un kilómetro de distancia y puedo decirte una cosa: ¡SE ACERCAN!' WHERE `ID`=5228;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그자는 마지막 방에 있을 거요. 녀석들이... 죽이지만 않았다면 말이오.', `MaleText_loc4`='他应该在最后一间牢房里。除非……除非他们已经把他给杀了。', `MaleText_loc5`='他應該在最後一間牢房裡。除非...除非他們已經把他給殺了。', `MaleText_loc7`='Tiene que estar en la última celda. A no ser... que le hayan matado.' WHERE `ID`=5229;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그를 어서 꺼내주시오!', `MaleText_loc4`='把他从那里弄出去！', `MaleText_loc5`='把他從那裡弄出去!', `MaleText_loc7`='¡Sacadle de ahí!' WHERE `ID`=5230;
