UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맥스웰의 야영지에서 만나도록 합시다. 그곳에서 다음 단계의 계획을 함께 검토하고 암호 해독 반지 없이 내 서판을 해독할 방법을 찾아볼 것이오.', `MaleText_loc4`='到麦克斯韦尔的营地碰面吧。我们将在那儿开始下一阶段的计划，在没有译码戒指的情况下找出破解石板上的文字的方法。', `MaleText_loc5`='到麥斯威爾的營地碰面吧。我們將在那兒開始下一階段的計畫，在沒有解碼戒指的情況下找出破解石板上的文字的方法。', `MaleText_loc7`='Nos vemos en el campamento de Maxwell. Una vez allí, atravesaremos las siguientes etapas del plan y averiguaremos la manera de descodificar mis tablillas sin el anillo de descodificación.' WHERE `ID`=5232;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그루르크가 연다. 그러면 보물 나눠 가지자.', `MaleText_loc4`='格鲁尔克很快就打开，然后我们就分财宝。', `MaleText_loc5`='格盧爾克很快就打開，然後我們就分財寶。', `MaleText_loc7`='Grurk abrir pronto. Luego dividimos tesoro.' WHERE `ID`=5233;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 바보 같은 상자! 바보. 바보, 바보 같은 상자! 열려! 열려! 열려라!', `MaleText_loc4`='愚蠢的箱子！愚蠢！打开！格鲁尔克要你快点打开！', `MaleText_loc5`='愚蠢的箱子!愚蠢!打開!格盧爾克要你快點打開!', `MaleText_loc7`='¡Caja estúpida! ¡Caja estúpida! ¡ABRIR! ¡GRURK DECIR ABRIR!' WHERE `ID`=5234;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 해보지! 바보는 너야!', `MaleText_loc4`='让我试试！你太蠢了！', `MaleText_loc5`='讓我試試!你太蠢了!', `MaleText_loc7`='¡Déjame intentarlo! ¡Tú demasiado estúpido!' WHERE `ID`=5236;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그루르크가 바보라고? 어디 한번 열어봐! 노움만큼 똑똑하기라도 해?', `MaleText_loc4`='格鲁尔克很蠢？你试试试看！难道你像侏儒一样聪明？', `MaleText_loc5`='格盧爾克很蠢?你試試試看!難道你像地精一樣聰明?', `MaleText_loc7`='¿Grurk estúpido? ¡Tú intentar abrir caja! ¿¿¿Quizás tú listo como gnomo???' WHERE `ID`=5237;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='루무르크는 이 상자 쉽게 연다!', `MaleText_loc4`='拉穆尔克轻易打开了箱子！', `MaleText_loc5`='拉莫爾克輕易打開了箱子!', `MaleText_loc7`='¡Lumurk abrir esta caja fácilmente!' WHERE `ID`=5238;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바보 같은 상자... 루무르크 졸려...', `MaleText_loc4`='箱子真蠢。拉穆尔克要睡觉。', `MaleText_loc5`='箱子真蠢。拉莫爾克要睡覺。', `MaleText_loc7`='Caja estúpida. Lumurk durmiendo.' WHERE `ID`=5239;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='악령숲에는 세나리온 식물 고약을 바르면 오염된 성분을 정화할 수 있는 식물들이 있어요. 저는 몇 가지 재료를 이용해 그 고약을 만드는 방법을 알고 있어요. 그대가 갖고 있는 기술에 따라, 여러 가지 방법으로 저를 도와주실 수 있어요.$B$B그리고 이 일을 하시려면 세나리온 등불이 필요할 거예요. 그 등불을 이용하면 육안으로는 놓치기 쉬운 자연의 타락과 오염을 볼 수 있어요.', `FemaleText_loc4`='费伍德的某些植物或许能因为塞纳里奥植物药膏的效用而避免堕落。我知道如何从几种不同的东西中获取这种药膏，凭借你的能力，你会发现有多种方法可以协助我制造药膏。$B$B首先，你需要一盏塞纳里奥信标，它是一种能让你看到肉眼所看不到的堕落和腐烂力量的装置。', `FemaleText_loc5`='費伍德森林的某些植物或許能因為塞納里奧植物藥膏的效用而避免墮落。我知道如何從幾種不同的東西中獲取這種藥膏，憑藉你的能力，你會發現有多種方法可以協助我製造藥膏。$B$B首先，你需要一盞塞納里奧信標，它是一種能讓你看到肉眼所看不到的墮落和腐爛力量的裝置。', `FemaleText_loc7`='En Frondavil hay plantas que pueden librarse del mal cuando se les aplique el bálsamo para plantas Cenarion. Sé cómo fabricar el bálsamo a partir de distintas clases de objetos. Según tus conocimientos, verás que puedes ayudarme de varias maneras.$B$BTambién vas a necesitar una antorcha Cenarion para poder trabajar aquí. Se trata de un objeto que te permite ver el mal y la podredumbre de la naturaleza ocultos a simple vista.' WHERE `ID`=5240;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='악령숲에는 세나리온 식물 고약을 바르면 오염된 성분을 정화할 수 있는 식물들이 있습니다. 나는 몇 가지 재료를 이용해 그 고약을 만드는 방법을 알고 있습니다. 당신이 갖고 있는 기술에 따라, 여러 가지 방법으로 날 도와줄 수 있습니다.$B$B그 일을 하려면 세나리온 등불이 필요할 거요. 그 등불을 이용하면 육안으로는 놓치기 쉬운 자연의 타락과 오염을 볼 수 있습니다.', `FemaleText_loc4`='费伍德的某些植物或许能因为塞纳里奥植物药膏的效用而避免堕落。我知道如何从几种不同的东西中获取这种药膏，凭借你的能力，你会发现有多种方法可以协助我制造药膏。$B$B首先，你需要一盏塞纳里奥信标，它是一种能让你看到肉眼所看不到的堕落和腐烂力量的装置。', `FemaleText_loc5`='費伍德森林的某些植物或許能因為塞納里奧植物藥膏的效用而避免墮落。我知道如何從幾種不同的東西中獲取這種藥膏，憑藉你的能力，你會發現有多種方法可以協助我製造藥膏。$B$B首先，你需要一盞塞納里奧信標，它是一種能讓你看到肉眼所看不到的墮落和腐爛力量的裝置。', `FemaleText_loc7`='En Frondavil hay plantas que pueden librarse del mal cuando se les aplique el bálsamo para plantas Cenarion. Sé cómo fabricar el bálsamo a partir de distintas clases de objetos. Según tus conocimientos, verás que puedes ayudarme de varias maneras.$B$BTambién vas a necesitar una antorcha Cenarion para poder trabajar aquí. Se trata de un objeto que te permite ver el mal y la podredumbre de la naturaleza ocultos a simple vista.' WHERE `ID`=5241;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세나리온 등불이 필요합니다.', `MaleText_loc4`='我需要塞纳里奥信标。', `MaleText_loc5`='我需要塞納里奧信標。', `MaleText_loc7`='Necesito una antorcha Cenarion.', `FemaleText_loc1`='세나리온 등불이 필요합니다.', `FemaleText_loc4`='我需要塞纳里奥信标。', `FemaleText_loc5`='我需要塞納里奧信標。', `FemaleText_loc7`='Necesito una antorcha Cenarion.' WHERE `ID`=5243;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기 이 등불을 받으세요. 오염된 식물을 찾으려면 항상 지니고 있어야 합니다.', `FemaleText_loc4`='给你一盏塞纳里奥信标，$n。如果你想要找到我们所需的堕落的物品，你就必须留着它。', `FemaleText_loc5`='給你一盞塞納里奧信標，$n。如果你想要找到我們所需的墮落的物品，你就必須留著它。', `FemaleText_loc7`='Aquí tienes una antorcha, $n. Debes tenerla tú para poder encontrar los objetos malignos que necesitamos.' WHERE `ID`=5244;
