UPDATE `locales_broadcast_text` SET `MaleText_loc1`='유해가 온통 파리와 구더기로 뒤덮여 있습니다.', `MaleText_loc4`='残骸上满是苍蝇和蛆虫。', `MaleText_loc5`='殘骸上滿是蒼蠅和蛆蟲。', `MaleText_loc7`='Los restos están cubiertos de moscas y gusanos.' WHERE `ID`=5246;
