UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 곤경에 처한 것 같습니다. 잠시 숨을 고른 후 상처가 회복됩니다.', `MaleText_loc4`='%s看上去似乎受到了重创。他花了好一会儿才恢复过来。', `MaleText_loc5`='%s看起來像是被抽了魂魄似的，花了好一會兒才從傷痛中恢復過來。', `MaleText_loc7`='%s parece como si la hubieran contrariado. Él tarda unos momentos en recuperarse de sus heridas.' WHERE `ID`=5248;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n에게 분노의 주먹을!', `MaleText_loc4`='狠狠地打$n！', `MaleText_loc5`='狠狠地打$n!', `MaleText_loc7`='¡Aplastaré a $n con mis puños de furia!' WHERE `ID`=5249;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 붙잡는 게 좋을 거요. 안 그러면 $n에게 교도소란 곳의 구타가 어떤 것인지 가르쳐주겠어.', `MaleText_loc4`='你最好抓牢我，否则$n就有苦头吃了！', `MaleText_loc5`='你最好抓牢我，否則$n就有苦頭吃了!', `MaleText_loc7`='Será mejor que me detengáis o, de lo contrario, $n va a recibir una paliza memorable.' WHERE `ID`=5250;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈에게 내 주먹 맛의 증표를 남겨주도록 하지!', `MaleText_loc4`='看招！', `MaleText_loc5`='這會留下一個痕跡!', `MaleText_loc7`='¡Esto le dejará huella!' WHERE `ID`=5251;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 후회스럽겠지, $n?', `MaleText_loc4`='我敢打赌你现在感到遗憾了，不是吗$n！？！', `MaleText_loc5`='我敢打賭你現在感到遺憾了，不是嗎$n!?!', `MaleText_loc7`='A que ahora lo lamentas, ¿verdad, $n?' WHERE `ID`=5252;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈은 잘못된 치안대장을 감금했어, $n. 박살 날 준비나 해라!', `MaleText_loc4`='你关错元帅了，$n。准备受死吧！', `MaleText_loc5`='你關錯元帥了，$n。準備受死吧!', `MaleText_loc7`='Has encerrado al alguacil equivocado, $n. ¡Prepárate para tu destrucción!' WHERE `ID`=5253;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 큰 제단은 오래전에 이 땅에 거주하던 나이트 엘프들이 지은 것입니다.$B$B이 사원에는 어떤 비밀이 숨겨져 있을지 아직은 알 수 없습니다.', `MaleText_loc4`='数年前居住在此地的暗夜精灵修建了这座神殿。$B$B它隐藏着什么秘密吗？', `MaleText_loc5`='數年前居住在此地的夜精靈修建了這座神殿。$B$B它隱藏著什麼秘密嗎?', `MaleText_loc7`='El gran santuario fue construido hace muchos años por los elfos de la noche que antaño vivían en esta tierra.$B$B¿Qué secretos podría guardar ahora?' WHERE `ID`=5254;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반짝이는 돌이 하나 더 필요합니다.', `MaleText_loc4`='我还需要一块闪光的石头。', `MaleText_loc5`='我還需要一塊閃亮的石頭。', `MaleText_loc7`='Necesito otra piedra refulgente.', `FemaleText_loc1`='반짝이는 돌이 하나 더 필요합니다.', `FemaleText_loc4`='我还需要一块闪光的石头。', `FemaleText_loc5`='我還需要一塊閃亮的石頭。', `FemaleText_loc7`='Necesito otra piedra refulgente.' WHERE `ID`=5255;
