UPDATE `locales_broadcast_text` SET `MaleText_loc1`='문이 열렸습니다, 카란. 이제 당신은 자유입니다.', `MaleText_loc4`='卡兰，门开了。你自由了。', `MaleText_loc5`='卡蘭，門開了。你自由了。', `MaleText_loc7`='La puerta está abierta, Kharan. Eres un hombre libre.', `FemaleText_loc1`='문이 열렸습니다, 카란. 이제 당신은 자유입니다.', `FemaleText_loc4`='卡兰，门开了。你自由了。', `FemaleText_loc5`='卡蘭，門開了。你自由了。', `FemaleText_loc7`='La puerta está abierta, Kharan. Eres un hombre libre.' WHERE `ID`=5257;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 살던 곳에서는 다른 죄수의 감옥문을 열어주다 걸리면 큰일난다고!', `MaleText_loc4`='在我所在的地方，你会因为打开其他牢友的门而受惩罚的！', `MaleText_loc5`='在我所在的地方，你會因為打開其他牢友的門而受懲罰的!', `MaleText_loc7`='¡En mi tierra te colgarían de un pie si abres la puerta de la celda de un interno!' WHERE `ID`=5258;
