UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아즈샤리트 퇴마 무기가 부숴졌습니다! 사악한 3인조를 해치워야 하는데 당신의 도움이 필요합니다.', `MaleText_loc4`='我弄坏了我的艾萨莱特水晶武器！我需要你的帮助来打败那三个恶魔。', `MaleText_loc5`='我弄壞了我的艾薩拉水晶武器!我需要你的幫助來打敗那三個惡魔。', `MaleText_loc7`='¡He destruido mis armas de Azshara! Necesito tu ayuda para derrotar a la tríada del poder.', `FemaleText_loc1`='아즈샤리트 퇴마 무기가 부숴졌습니다! 사악한 3인조를 해치워야 하는데 당신의 도움이 필요합니다.', `FemaleText_loc4`='我弄坏了我的艾萨莱特水晶武器！我需要你的帮助来打败那三个恶魔。', `FemaleText_loc5`='我弄壞了我的艾薩拉水晶武器!我需要你的幫助來打敗那三個惡魔。', `FemaleText_loc7`='¡He destruido mis armas de Azshara! Necesito tu ayuda para derrotar a la tríada del poder.' WHERE `ID`=5260;
