UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그걸로 됐어! 이 사태가 수습될 때까지는 그만 마셔야겠군!', `MaleText_loc4`='好了！把这儿收拾好才能喝酒！', `MaleText_loc5`='好了!把這兒收拾好才能喝酒!', `MaleText_loc7`='¡Eso es! ¡Se acabó la cerveza hasta que no paréis esto!' WHERE `ID`=5267;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하하! 날 풀어주다니 정말 고맙군, 멍청한 녀석들. 이제 그 보답을 해야겠군. 네놈의 모든 살덩어리를 남김없이 태워주마!', `MaleText_loc4`='哈！哈！哈！谢谢你们这些笨蛋放了我。现在让我吃掉你们的肉来报答你们吧。', `MaleText_loc5`='哈!哈!哈!謝謝你們這些笨蛋放了我。現在讓我吃掉你們的肉來報答你們吧。', `MaleText_loc7`='¡Ja! ¡Ja! ¡Ja! ¡Gracias por liberarme, idiotas! Dejen que salde mi deuda calcinando su carne.' WHERE `ID`=5268;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리가 녀석들에게 본때를 보여줬어요!', `FemaleText_loc4`='干得好！', `FemaleText_loc5`='幹得好!', `FemaleText_loc7`='¡Así aprenderá!' WHERE `ID`=5269;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='운고로 분화구의 수정탑에 숨겨진 비밀을 발견했습니다. 언제든지 수정탑에 가서 수정탑의 힘을 얻고 유용한 자원을 얻을 수 있습니다.', `MaleText_loc4`='安戈洛环形山水晶塔的秘密现在已经被你破解了。你可以随时造访水晶塔，获取它们的力量。', `MaleText_loc5`='安戈洛環形山水晶塔的秘密現在已經被你破解了。你可以隨時造訪水晶塔，獲取它們的力量。', `MaleText_loc7`='Los secretos ocultos en las torres del cráter de Un’Goro ahora te pertenecen. Visita las torres cada vez que necesites para utilizar su poder y obtener recursos útiles.' WHERE `ID`=5270;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 눈을 피할 수는 없다. 네놈을 모조리 태워주마!', `MaleText_loc4`='你别想再躲着我们了。准备去死吧！', `MaleText_loc5`='你別想再躲著我們了。準備去死吧!', `MaleText_loc7`='No os podéis esconder de nosotros. ¡Preparaos para arder!' WHERE `ID`=5271;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타나리스에 온 걸 환영한다고. 그래, 오늘은 무슨 일을 도와주면 되지? 그런데 당신 말이야, 대장장이처럼 보이지는 않는데? 하기야 겉모습이란 건 믿을 게 못 되는 법이니까 뭐...', `MaleText_loc4`='欢迎来到塔纳利斯，$n。我能为你提供什么服务？你看起来可不像铁匠，但是我知道，人不可貌相。', `MaleText_loc5`='歡迎來到塔納利斯，$n。我能為你提供什麼服務?你看起來可不像鐵匠，但是我知道，人不可貌相。', `MaleText_loc7`='Te doy la bienvenida a Tanaris, $n. ¿En qué te puedo ayudar hoy? No pareces un herrero, pero sé que las apariencias engañan.' WHERE `ID`=5274;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오, 이런! 여기서 나가야겠어요!', `FemaleText_loc4`='啊呀！我要离开这儿！', `FemaleText_loc5`='啊呀!我要離開這兒!', `FemaleText_loc7`='¡Oh, no! ¡Me voy de aquí!' WHERE `ID`=5275;
