UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='푸른 수정에 붉은 수정을 더하면... 내 생각에는...', `FemaleText_loc4`='蓝色加红色……我觉得……', `FemaleText_loc5`='藍色加紅色...我覺得...', `FemaleText_loc7`='Azul y rojo... Supongo...' WHERE `ID`=5288;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n, 해냈어요! 드디어 알아냈어요!', `FemaleText_loc4`='$n，就是它！我终于想到了！', `FemaleText_loc5`='$n，就是它!我終於想到了!', `FemaleText_loc7`='¡$n, eso es! ¡Por fin lo he averiguado!' WHERE `ID`=5289;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='열한 분의 스승님들께서 쓰신 고서를 잃어버렸소. 쿠엘탈라스에 스컬지가 침략했을 때 전 세계로 흩어져버린 게지.$B$B지금 우리는 그 고서를 찾고 있소. 그 고서에 담긴 비밀을 찾아내 한때 우리가 지녔던 힘을 되찾고자 하는 것이오.$B$B난 카리엘 윈탈루스 스승님께서 쓰신 10권을 찾고 있소. 고서 하나를 찾아 가지고 오면 그 고서의 마법을 흡수해 강력한 마력을 지닌 결정체를 만들어 주겠소. 물론 모든 일에는 대가가 따르게 마련이지. 비싼 값일 테지만 그 값을 꼭 치러야 할 것이오.', `MaleText_loc4`='它们都失踪了，$r。在亡灵天灾入侵奎尔萨拉斯的时候，精灵族的圣契散落到世界各地。$B$B现在我们得搜寻这些圣契。寻找其中的秘密——并恢复其中蕴含的力量。$B$B我在寻找由卡里尔·温萨鲁斯书写的圣契。如果你找到了圣契，请允许我吸收它的魔法力量，而为你我可以制作一种力量的融合物……当然，所有的事情都是有代价的。这项任务的风险极大，但是我给予的回报也是相当丰厚的。', `MaleText_loc5`='它們都失蹤了，$r。在天譴軍團入侵奎爾薩拉斯的時候，精靈族的聖契散落到世界各地。$B$B現在我們得搜尋這些聖契。尋找其中的秘密─並恢復其中蘊含的力量。$B$B我在尋找由卡里爾·溫薩魯斯書寫的聖契。如果你找到了聖契，請允許我吸收它的魔法力量，而為你我可以製作一種力量的融合物...當然，所有的事情都是有代價的。這項任務的風險極大，但是我給予的回報也是相當豐厚的。', `MaleText_loc7`='Están perdidos, $r. Tratados escritos por los maestros elfos. Dispersos por el mundo cuando se desató la Plaga sobre Quel''Thalas.$B$BAhora estamos buscando esos tratados. Los buscamos para desentrañar los secretos que esconden - para recuperar el poder que una vez tuvimos.$B$BYo busco los diez tratados escritos por el maestro Kariel Winthalus. Si encuentras uno de esos tratados, déjame que absorba sus propiedades mágicas y te fabricaré una fusión de poder... por supuesto, todo tiene su precio. Mi precio te parecerá elevado, pero deberás pagarlo.' WHERE `ID`=5290;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='숙고의 고서를 드리겠습니다.', `MaleText_loc4`='看看吧，这就是沉思圣契。', `MaleText_loc5`='看看吧，這就是沉思聖契。', `MaleText_loc7`='Te presento el tratado sobre Reflexión.', `FemaleText_loc1`='숙고의 고서를 드리겠습니다.', `FemaleText_loc4`='看看吧，这就是沉思圣契。', `FemaleText_loc5`='看看吧，這就是沉思聖契。', `FemaleText_loc7`='Te presento el tratado sobre Reflexión.' WHERE `ID`=5291;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 그러니까... 찾은 게로군.$B$B<고서를 가리키는 마스레디스>$B$B필요한 재료는 모아왔소?$B$B고서에 적혀 있잖소, 어리석기는!', `MaleText_loc4`='啊，这么说……你已经找到了。$B$B<玛瑟迪斯指着你手中的书。>$B$B你收集到所需要的材料了吗？$B$B那些材料都已经在书中列出来了，笨蛋！', `MaleText_loc5`='啊，這麼說...你已經找到了。$B$B<瑪瑟迪斯指著你手中的書。>$B$B你收集到所需要的材料了嗎?$B$B那些材料都已經在書中列出來了，笨蛋!', `MaleText_loc7`='Ah, así... que lo has encontrado.$B$B<Mathredis apunta al libro que está en tu poder.>$B$B¿Has reunido los componentes necesarios?$B$B¡Las manifestaciones que se detallan en el tratado, imbécil!' WHERE `ID`=5292;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<고서를 뚫어지게 바라는 마스레디스>$B$B결정체 때문에 온 거요? 고서에 적힌 대로 했소?', `MaleText_loc4`='<玛瑟迪斯目不转睛地盯着圣契。>$B$B你来寻求融合物的？你按照圣契的指示做了吗？', `MaleText_loc5`='<瑪瑟迪斯目不轉睛地盯著聖契。>$B$B你來尋求融合物的?你按照聖契的指示做了嗎?', `MaleText_loc7`='<Mathredis mira el libro intensamente.>$B$B¿Vienes en busca de una fusión? ¿Has actuado según las instrucciones del tratado?' WHERE `ID`=5293;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물건들을 가져오면 결정체를 만들어 주겠소.', `MaleText_loc4`='给我奥术力量，然后我就会进行融合，凡人。', `MaleText_loc5`='給我秘法力量，然後我就會進行融合，凡人。', `MaleText_loc7`='Dame el Arcano y prepararé la fusión, mortal.' WHERE `ID`=5294;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 희귀한 걸 찾았군.$B$B<고개를 끄덕이는 마스레디스>$B$B계속하고 싶거든 재료를 더 가지고 오시오.', `MaleText_loc4`='确实是一项难得的发现。$B$B<玛瑟迪斯点了点头。>$B$B如果你希望继续的话，我会需要相应的材料。', `MaleText_loc5`='確實是一項難得的發現。$B$B<瑪瑟迪斯點了點頭。>$B$B如果你希望繼續的話，我會需要相應的材料。', `MaleText_loc7`='Ciertamente es un hallazgo extraño.$B$B<Mathredis asiente.>$B$BSi deseas continuar, necesitaré los componentes.' WHERE `ID`=5295;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='결국은 욕심에 눈이 멀어 여기까지 왔군.$B$B<비웃는 마스레디스>$B$B한 드레나이가 내게 말한 적 있소. 욕심이야말로 이 세계 모든 종족들에게 공통된 단 하나의 특성이라고 말이지. 나도 그 말에 동의한다오.$B$B고서에 적힌 재료들은 모두 모아왔소?', `MaleText_loc4`='贪婪又把你带回给我了。$B$B<玛瑟迪斯笑了。>$B$B从前有个叫聪明的德莱尼人告诉我，婪是这个世界上所有的种族共有的唯一品质。我不得不同意。$B$B你找到圣契上所列出的材料了吗？', `MaleText_loc5`='貪婪又把你帶回來我這裡了。$B$B<瑪瑟迪斯笑了。>$B$B有個聰明的德萊尼告訴我，貪婪是這個世界上所有種族的共同特性。我不得不同意。$B$B你找到聖契上列出的材料了嗎?', `MaleText_loc7`='La codicia te ha traído hasta mí.$B$B<Mathredis ríe.>$B$BUn draenei sabio un día me dijo que la codicia es la única cualidad que comparten todas las razas de este mundo. Coincido con esa idea.$B$B¿Has reunido los componentes que se detallan en el tratado?' WHERE `ID`=5296;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공장에 침략자들이라니! 나의 기계들이 해치울 것이다!', `MaleText_loc4`='有入侵者闯入制造厂？我的傀儡要毁掉你们！', `MaleText_loc5`='入侵者到達製造廠了?我的傀儡人要毀掉你們!', `MaleText_loc7`='¿Intrusos en La Fábrica? ¡Mis ensamblajes os destruirán!' WHERE `ID`=5297;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성스러운 빛의 가호가 함께하길.', `MaleText_loc4`='愿光明保佑你。', `MaleText_loc5`='願光明保佑你。', `MaleText_loc7`='Que la Luz te proteja hoy.', `FemaleText_loc1`='성스러운 빛의 가호가 함께하길.', `FemaleText_loc4`='愿光明保佑你。', `FemaleText_loc5`='願光明保佑你。', `FemaleText_loc7`='Que la Luz te proteja hoy.' WHERE `ID`=5298;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛의 길에 대해 좀 더 가르침을 내려 주십시오.', `MaleText_loc4`='我想接受更多的关于圣光的训练。', `MaleText_loc5`='我想接受更多的關於聖光的訓練。', `MaleText_loc7`='Me gustaría recibir más instrucción en el camino de la Luz.', `FemaleText_loc1`='빛의 길에 대해 좀 더 가르침을 내려 주십시오.', `FemaleText_loc4`='我想接受更多的关于圣光的训练。', `FemaleText_loc5`='我想接受更多的關於聖光的訓練。', `FemaleText_loc7`='Me gustaría recibir más instrucción en el camino de la Luz.' WHERE `ID`=5299;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭력! 재산 파괴! 아무도 못 지나갈 것이다!!', `MaleText_loc4`='攻击！财产损害！没人能通过！！', `MaleText_loc5`='攻擊!財產損害!沒人能通過!!', `MaleText_loc7`='¡Violencia! ¡Daños a la propiedad! ¡¡No hay paso!!' WHERE `ID`=5300;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='술집에서 나가시오!', `MaleText_loc4`='你必须离开酒吧！', `MaleText_loc5`='你必須離開酒吧!', `MaleText_loc7`='¡Debes dejar la barra!' WHERE `ID`=5301;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 더 이상 당신을 환영하지 않아!', `MaleText_loc4`='你已经不受欢迎了！', `MaleText_loc5`='你已經不受歡迎了!', `MaleText_loc7`='¡Tu bienvenida ya está desfasada!' WHERE `ID`=5302;
