UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라제에게 뭘 원하나?', `MaleText_loc4`='你想让拆毁者干什么？', `MaleText_loc5`='你想讓拆毀者幹什麼?', `MaleText_loc7`='¿¿Qué querer de Arrasa??' WHERE `ID`=5304;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, $n. 임무를 완수하는 데 도움이 필요하다면 말씀만 하세요. 제 수호물, 라제가 그늘거미 밀렵꾼들을 처치하는 걸 도와줄 테니까요. 이 지휘봉으로 라제를 이용해 싸우세요. 라제는 그늘거미 밀렵꾼만 공격하도록 훈련을 받았답니다.', `FemaleText_loc4`='你好，$n。如果你在完成任务时需要帮助，你只需开口就行了。我的卫兵，拆毁者可以帮你打败暗影蛛丝偷猎者。用这个命令法杖在战斗中指挥拆毁者。他受训只攻击暗影蛛丝偷猎者。', `FemaleText_loc5`='你好，$n。如果你在完成任務時需要幫助，你只需開口就行了。我的守衛拆毀者可以幫你打敗暗影蛛絲盜獵者。用這個命令法杖在戰鬥中指揮拆毀者。他受訓只攻擊暗影蛛絲盜獵者。', `FemaleText_loc7`='Hola, $n. Si necesitas ayuda para terminar tu misión, solo tienes que pedirla. Mi guardián, Arrasa, puede ayudarte a derrotar a los furtivos Sedaumbría. Usa este bastón de mando con Arrasa en la batalla. Está entrenado para atacar SOLO a furtivos Sedaumbría.' WHERE `ID`=5305;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그늘거미 밀렵꾼을 처치해야 하는데 도움이 필요합니다.', `MaleText_loc4`='我需要帮助来击败暗影蛛丝偷猎者。', `MaleText_loc5`='我需要幫助來擊敗暗影蛛絲盜獵者。', `MaleText_loc7`='Necesito ayuda para derrotar a los furtivos Sedaumbría.', `FemaleText_loc1`='그늘거미 밀렵꾼을 처치해야 하는데 도움이 필요합니다.', `FemaleText_loc4`='我需要帮助来击败暗影蛛丝偷猎者。', `FemaleText_loc5`='我需要幫助來擊敗暗影蛛絲盜獵者。', `FemaleText_loc7`='Necesito ayuda para derrotar a los furtivos Sedaumbría.' WHERE `ID`=5306;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼마든지 더 있으니 걱정하지 마시고 쭉 들이켜세요!', `MaleText_loc4`='喝光它！我们还有很多酒！', `MaleText_loc5`='喝光它!我們還有很多酒!', `MaleText_loc7`='¡Bebed! ¡Hay más para beber!' WHERE `ID`=5307;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맛있게 드십시오! 이런 맥주는 어디서도 찾을 수 없을 겁니다!', `MaleText_loc4`='尽情享受吧！你找不到比这更好的啤酒了！', `MaleText_loc5`='盡情享受吧!你找不到比這更好的麥芽酒了!', `MaleText_loc7`='¡A disfrutar! ¡No existe mejor cerveza que esta!' WHERE `ID`=5308;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은무쇠 맥주라고 들어보셨습니까? 정말 최고랍니다!', `MaleText_loc4`='你喝过黑铁啤酒吗？那可是最好的啤酒！', `MaleText_loc5`='你喝過黑鐵麥芽酒嗎?那可是最好的麥芽酒!', `MaleText_loc7`='¿Has probado la cerveza Hierro Negro? ¡Es la mejor!' WHERE `ID`=5309;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멧돼지 고기 좀 들어보세요! 제가 새로 개발한 요립니다!', `MaleText_loc4`='尝尝野猪肉吧！这是我的新作！', `MaleText_loc5`='嘗嘗野豬肉吧!這是我的新作!', `MaleText_loc7`='¡Prueba el jabalí! ¡Es mi nueva receta!' WHERE `ID`=5310;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 어리석은 원로원의원들을 제거해줘서 고맙군. 이제 라그나로스의 가장 강력한 부하의 손에 죽을 준비나 하게.', `MaleText_loc4`='感谢你清除了这些愚蠢的议员。去面对拉格纳罗斯最强大的仆人吧，看看你的命运如何。', `MaleText_loc5`='感謝你清除了這些愚蠢的議員。去面對拉格納羅斯最強大的僕人吧，看看你的命運如何。', `MaleText_loc7`='Gracias por acabar con esos necios senadores. Ahora, preparense para enfrentarse a su destino a manos del sirviente más poderoso de Ragnaros.' WHERE `ID`=5311;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='애써 봤자 헛수고다, 어리석은 것들! 너희들은 절대로 날 이기지 못해!', `MaleText_loc4`='你们所做的一切都没有意义，蠢货！你们永远都无法打败我！', `MaleText_loc5`='你們所做的一切都沒有意義，蠢貨!你們永遠都無法打敗我!', `MaleText_loc7`='¡Sus esfuerzos son inútiles, idiotas! ¡Jamás podrán derrotarme!' WHERE `ID`=5312;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그자들은 어차피 거치적거리는 존재일 뿐이었어.', `MaleText_loc4`='他们只是阻碍了一下。', `MaleText_loc5`='他們只是阻礙了一下。', `MaleText_loc7`='De todas maneras, interferían con mis propósitos.' WHERE `ID`=5313;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 너희들의 노력이 얼마나 헛된 것인지 상상조차 못할 것이다.', `MaleText_loc4`='哈！你甚至不能想象你的努力全都白费了。', `MaleText_loc5`='哈!你甚至不能想像你的努力全都白費了。', `MaleText_loc7`='¡Ja! No pueden siquiera imaginar la futilidad de sus esfuerzos.' WHERE `ID`=5314;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겨우 이 정도였더냐? 나처럼 위대한 힘을 가진 존재를 이길 수 있을 거라고 생각했단 말이더냐?', `MaleText_loc4`='那就是你的最好表现吗？你真的期望自己能打败一个象我这样令人畏惧的人吗？', `MaleText_loc5`='那就是你的最好表現嗎?你真的期望自己能打敗一個象我這樣令人畏懼的人嗎?', `MaleText_loc7`='¿Estás dando lo mejor de ti? ¿Realmente crees que puedes vencer a alguien tan sobrecogedor como yo?' WHERE `ID`=5315;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경매장', `MaleText_loc4`='拍卖行', `MaleText_loc5`='拍賣場', `MaleText_loc7`='Casa de subastas', `FemaleText_loc1`='경매장', `FemaleText_loc4`='拍卖行', `FemaleText_loc5`='拍賣場', `FemaleText_loc7`='Casa de subastas' WHERE `ID`=5316;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경매장 말입니까? 아이언포지 성문 근처에 있습니다. 아이언포지 사설금고 바로 맞은 편이랍니다.', `MaleText_loc4`='拍卖行在哪儿？当你进入我们美丽的城市时它就在铁炉堡大门旁边。你会在银行的正对面找到它。', `MaleText_loc5`='拍賣場在哪兒?當你進入我們美麗的城市時它就在鐵爐堡大門旁邊。你會在銀行的正對面找到它。', `MaleText_loc7`='¿Dónde está la casa de subastas? Veamos, está junto a las puertas de Forjaz cuando entras en nuestra bella ciudad. Está justo delante de la Cámara.', `FemaleText_loc1`='경매장 말입니까? 아이언포지 성문 근처에 있습니다. 아이언포지 사설금고 바로 맞은 편이랍니다.', `FemaleText_loc4`='拍卖行在哪儿？当你进入我们美丽的城市时它就在铁炉堡大门旁边。你会在银行的正对面找到它。', `FemaleText_loc5`='拍賣場在哪兒?當你進入我們美麗的城市時它就在鐵爐堡大門旁邊。你會在銀行的正對面找到它。', `FemaleText_loc7`='¿Dónde está la casa de subastas? Veamos, está junto a las puertas de Forjaz cuando entras en nuestra bella ciudad. Está justo delante de la Cámara.' WHERE `ID`=5317;
