UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다르나서스에는 정말로 멋진 곳이 많이 있답니다. 어디로 가시기를 원하십니까?', `MaleText_loc4`='达纳苏斯有无数令人惊异的地方，你想去哪儿？', `MaleText_loc5`='達納蘇斯有無數令人驚異的地方，你想去哪兒?', `MaleText_loc7`='De todos los lugares maravillosos de Darnassus, ¿en qué dirección quieres que te oriente?', `FemaleText_loc1`='다르나서스에는 정말로 멋진 곳이 많이 있답니다. 어디로 가시기를 원하십니까?', `FemaleText_loc4`='达纳苏斯有无数令人惊异的地方，你想去哪儿？', `FemaleText_loc5`='達納蘇斯有無數令人驚異的地方，你想去哪兒?', `FemaleText_loc7`='De todos los lugares maravillosos de Darnassus, ¿en qué dirección quieres que te oriente?' WHERE `ID`=5325;
