UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여행을 하시다가 얻은 귀중한 물건이나 돈을 보관할 곳을 찾으시는군요. 이 멋진 도시 중앙에 다르나서스 은행이 있으니 그곳으로 가 보시기 바랍니다.', `MaleText_loc4`='你可以在达纳苏斯银行找到你存放财物的地方，它就在我们神奇的城市中央。', `MaleText_loc5`='你可以在達納蘇斯銀行找到你存放財物的地方，它就在我們神奇的城市中央。', `MaleText_loc7`='Puedes guardar tus bienes más valiosos en el banco de Darnassus, que está en el centro de una ciudad maravillosa.', `FemaleText_loc1`='여행을 하시다가 얻은 귀중한 물건이나 돈을 보관할 곳을 찾으시는군요. 이 멋진 도시 중앙에 다르나서스 은행이 있으니 그곳으로 가 보시기 바랍니다.', `FemaleText_loc4`='你可以在达纳苏斯银行找到你存放财物的地方，它就在我们神奇的城市中央。', `FemaleText_loc5`='你可以在達納蘇斯銀行找到你存放財物的地方，它就在我們神奇的城市中央。', `FemaleText_loc7`='Puedes guardar tus bienes más valiosos en el banco de Darnassus, que está en el centro de una ciudad maravillosa.' WHERE `ID`=5329;
