UPDATE `locales_broadcast_text` SET `MaleText_loc1`='베스프리스투스가 조련한 히포그리프가 그대를 목적지까지 신속하게 데려다 줄 수 있습니다. 다르나서스 서쪽에 있는 문을 지나면 루테란 마을이 있는데 그곳에서 베스프리스투스를 찾아보십시오.', `MaleText_loc4`='维斯派塔斯的角鹰兽会送你到达目的地的。穿过达纳苏斯西部入口，去鲁瑟兰村找他吧。', `MaleText_loc5`='維斯派塔斯的角鷹獸會送你到達目的地的。穿過達納蘇斯西部入口，去魯瑟蘭村找他吧。', `MaleText_loc7`='Los hipogrifos de Vesprystus te conducirán rápidamente a tu destino. Búscalo en la aldea Ruth’theran, a través del portal que está en la zona oeste de Darnassus.', `FemaleText_loc1`='베스프리스투스가 조련한 히포그리프가 그대를 목적지까지 신속하게 데려다 줄 수 있습니다. 다르나서스 서쪽에 있는 문을 지나면 루테란 마을이 있는데 그곳에서 베스프리스투스를 찾아보십시오.', `FemaleText_loc4`='维斯派塔斯的角鹰兽会送你到达目的地的。穿过达纳苏斯西部入口，去鲁瑟兰村找他吧。', `FemaleText_loc5`='維斯派塔斯的角鷹獸會送你到達目的地的。穿過達納蘇斯西部入口，去魯瑟蘭村找他吧。', `FemaleText_loc7`='Los hipogrifos de Vesprystus te conducirán rápidamente a tu destino. Búscalo en la aldea Ruth’theran, a través del portal que está en la zona oeste de Darnassus.' WHERE `ID`=5331;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='길드 사무관과 상인', `MaleText_loc4`='公会注册员及公会商人', `MaleText_loc5`='公會註冊員和商人', `MaleText_loc7`='Maestro de hermandad y vendedor', `FemaleText_loc1`='길드 사무관과 상인', `FemaleText_loc4`='公会注册员及公会商人', `FemaleText_loc5`='公會註冊員和商人', `FemaleText_loc7`='Maestro de hermandad y vendedor' WHERE `ID`=5332;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='길드를 만들고자 하신다면 길드 사무관, 리셰아나를 만나셔야 합니다. 다르나서스 북동쪽에 있는 장인의 정원에 가면 그녀를 만나실 수 있을 겁니다.', `MaleText_loc4`='要是你想要组建公会的话，你必须去见公会管理人琳沙娜。她在达纳苏斯东北部的工匠区。', `MaleText_loc5`='要是你想要組建公會的話，你必須去見公會管理人琳沙娜。她在達納蘇斯東北部的工匠區。', `MaleText_loc7`='Si deseas formar una hermandad, tienes que buscar a Lysheana, maestra de hermandades. La encontrarás en el Bancal del Artesano, en la zona noreste de Darnassus.', `FemaleText_loc1`='길드를 만들고자 하신다면 길드 사무관, 리셰아나를 만나셔야 합니다. 다르나서스 북동쪽에 있는 장인의 정원에 가면 그녀를 만나실 수 있을 겁니다.', `FemaleText_loc4`='要是你想要组建公会的话，你必须去见公会管理人琳沙娜。她在达纳苏斯东北部的工匠区。', `FemaleText_loc5`='要是你想要組建公會的話，你必須去見公會管理人琳沙娜。她在達納蘇斯東北部的工匠區。', `FemaleText_loc7`='Si deseas formar una hermandad, tienes que buscar a Lysheana, maestra de hermandades. La encontrarás en el Bancal del Artesano, en la zona noreste de Darnassus.' WHERE `ID`=5333;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여관', `MaleText_loc4`='旅店', `MaleText_loc5`='旅店', `MaleText_loc7`='La posada', `FemaleText_loc1`='여관', `FemaleText_loc4`='旅店', `FemaleText_loc5`='旅店', `FemaleText_loc7`='La posada' WHERE `ID`=5334;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='텔드랏실을 뒤덮고 있는 촉촉한 풀밭도 아주 훌륭한 침대가 될 수 있겠지만 좀 더 편안한 잠자리를 원한다면 장인의 정원에 있는 다르나서스 여관 침대가 제격일 것입니다. 가서 셀리에네를 찾으십시오.', `MaleText_loc4`='尽管我可以将覆盖着整个泰达希尔的草坪当作很好的床铺，但是工匠区中塞琳尼经营的旅馆对那些享受一下奢华生活的人来说再合适不过了。', `MaleText_loc5`='儘管我可以將覆蓋著整個泰達希爾的草坪當作很好的床鋪，但是工匠區中塞琳尼經營的旅館對那些享受一下奢華生活的人來說再合適不過了。', `MaleText_loc7`='Si bien para mí no hay mejor cama que la fresca hierba que cubre las praderas de Teldrassil, las camas que Saelienne prepara en la posada del Bancal del Artesano son muy adecuadas para los sibaritas.', `FemaleText_loc1`='텔드랏실을 뒤덮고 있는 촉촉한 풀밭도 아주 훌륭한 침대가 될 수 있겠지만 좀 더 편안한 잠자리를 원한다면 장인의 정원에 있는 다르나서스 여관 침대가 제격일 것입니다. 가서 셀리에네를 찾으십시오.', `FemaleText_loc4`='尽管我可以将覆盖着整个泰达希尔的草坪当作很好的床铺，但是工匠区中塞琳尼经营的旅馆对那些享受一下奢华生活的人来说再合适不过了。', `FemaleText_loc5`='儘管我可以將覆蓋著整個泰達希爾的草坪當作很好的床鋪，但是工匠區中塞琳尼經營的旅館對那些享受一下奢華生活的人來說再合適不過了。', `FemaleText_loc7`='Si bien para mí no hay mejor cama que la fresca hierba que cubre las praderas de Teldrassil, las camas que Saelienne prepara en la posada del Bancal del Artesano son muy adecuadas para los sibaritas.' WHERE `ID`=5335;
