UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다르나서스의 중앙 부근에 있는 은행 바깥쪽에 우체통이 있습니다.', `MaleText_loc4`='在达纳苏斯的东北部，也就是工匠区，你会在旅馆外面找到邮箱的。', `MaleText_loc5`='在達納蘇斯的東北部，也就是工匠區，你會在旅館外面找到銀行的。', `MaleText_loc7`='Hay un buzón en la parte exterior del banco. Lo encontrarás en el centro de Darnassus.', `FemaleText_loc1`='다르나서스의 중앙 부근에 있는 은행 바깥쪽에 우체통이 있습니다.', `FemaleText_loc4`='在达纳苏斯的东北部，也就是工匠区，你会在旅馆外面找到邮箱的。', `FemaleText_loc5`='在達納蘇斯的東北部，也就是工匠區，你會在旅館外面找到銀行的。', `FemaleText_loc7`='Hay un buzón en la parte exterior del banco. Lo encontrarás en el centro de Darnassus.' WHERE `ID`=5337;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='직업 상급자', `MaleText_loc4`='职业训练师', `MaleText_loc5`='職業訓練師', `MaleText_loc7`='Un instructor de clase', `FemaleText_loc1`='직업 상급자', `FemaleText_loc4`='职业训练师', `FemaleText_loc5`='職業訓練師', `FemaleText_loc7`='Un instructor de clase' WHERE `ID`=5338;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳 다르나서스에는 오랜 세월 동안 자신이 선택한 직업의 기술을 갈고 닦은 다양한 상급자들이 있답니다. 그대의 지도자가 될 분에게 가는 길을 가르쳐드리겠습니다.', `MaleText_loc4`='达纳苏斯有许多熟练的训练师，他们拥有多年的训练经验。我会介绍一名导师给你，沿着你选择的道路前进吧。', `MaleText_loc5`='達納蘇斯有許多熟練的訓練師，他們擁有多年的訓練經驗。我會介紹一名導師給你，沿著你選擇的道路前進吧。', `MaleText_loc7`='Aquí en Darnassus encontrarás expertos instructores que han perfeccionado las habilidades de su clase elegida en años de entrenamiento y dedicación. Puedo ponerte en contacto con el que podría ser tu mentor. Basta que digas que este es el camino que has elegido.', `FemaleText_loc1`='이곳 다르나서스에는 오랜 세월 동안 자신이 선택한 직업의 기술을 갈고 닦은 다양한 상급자들이 있답니다. 그대의 지도자가 될 분에게 가는 길을 가르쳐드리겠습니다.', `FemaleText_loc4`='达纳苏斯有许多熟练的训练师，他们拥有数年的训练经验。我会介绍一名导师给你，沿着你选择的道路前进吧。', `FemaleText_loc5`='達納蘇斯有許多熟練的訓練師，他們擁有數年的訓練經驗。我會介紹一名導師給你，沿著你選擇的道路前進吧。', `FemaleText_loc7`='Aquí en Darnassus encontrarás expertos instructores que han perfeccionado las habilidades de su clase elegida en años de entrenamiento y dedicación. Puedo ponerte en contacto con el que podría ser tu mentor. Basta que digas que este es el camino que has elegido.' WHERE `ID`=5339;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사냥꾼', `MaleText_loc4`='猎人', `MaleText_loc5`='獵人', `MaleText_loc7`='Cazador', `FemaleText_loc1`='사냥꾼', `FemaleText_loc4`='猎人', `FemaleText_loc5`='獵人', `FemaleText_loc7`='Cazador' WHERE `ID`=5340;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 조카스테처럼 훌륭한 사냥꾼이 있는 다르나서스로 오셔서 다행이군요. 그녀는 세나리온 자치령에 있으니 찾아가서 사냥꾼의 기술을 배우시기 바랍니다.', `MaleText_loc4`='你很幸运来到达纳苏斯，因为你遇到了像祖卡斯特这样多才多艺的猎人作为你的培训师。我建议你到塞纳里奥区拜访她并寻求她的指导。', `MaleText_loc5`='你很幸運來到達納蘇斯，因為你遇到了像祖卡斯特這樣多才多藝的獵人作為你的訓練師。我建議你到塞納里奧區拜訪她並尋求她的指導。', `MaleText_loc7`='Eres afortunado al venir a Darnassus, en donde podrás encontrarte con una cazadora tan avezada como Jocaste entre nuestros instructores. Te animo a que la visites en el Enclave Cenarion y que le pidas que sea tu tutora.', `FemaleText_loc1`='아, 조카스테처럼 훌륭한 사냥꾼이 있는 다르나서스로 오셔서 다행이군요. 그녀는 세나리온 자치령에 있으니 찾아가서 사냥꾼의 기술을 배우시기 바랍니다.', `FemaleText_loc4`='你很幸运来到达纳苏斯，因为你遇到了像祖卡斯特这样多才多艺的猎人作为你的培训师。我建议你到塞纳里奥区拜访她并寻求她的指导。', `FemaleText_loc5`='你很幸運來到達納蘇斯，因為你遇到了像祖卡斯特這樣多才多藝的獵人作為你的訓練師。我建議你到塞納里奧區拜訪她並尋求她的指導。', `FemaleText_loc7`='Eres afortunado al venir a Darnassus, en donde podrás encontrarte con una cazadora tan avezada como Jocaste entre nuestros instructores. Te animo a que la visites en el Enclave Cenarion y que le pidas que sea tu tutora.' WHERE `ID`=5341;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드루이드', `MaleText_loc4`='德鲁伊', `MaleText_loc5`='德魯伊', `MaleText_loc7`='Druida', `FemaleText_loc1`='드루이드', `FemaleText_loc4`='德鲁伊', `FemaleText_loc5`='德魯伊', `FemaleText_loc7`='Druida' WHERE `ID`=5342;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금과 같이 힘든 시기에 드루이드는 주위 동료에게 아주 절친한 친구가 되어줄 수 있답니다. 세나리온 자치령에 있는 어느 드루이드에게 물어도 같은 대답을 할 겁니다.', `MaleText_loc4`='在灰色年代，德鲁伊对周遭的人都很友好。你随便问塞纳里奥区的任何一个德鲁伊，他们会给出相同的说法的。', `MaleText_loc5`='在灰色年代，德魯伊對周遭的人都很友好。你隨便問塞納里奧區的任何一個德魯伊，他們會給出相同的說法的。', `MaleText_loc7`='En momentos difíciles, un druida puede ser un cálido amigo a quien acudir. Pregunta a cualquier druida del Enclave Cenarion y te dirán lo mismo.', `FemaleText_loc1`='지금과 같이 힘든 시기에 드루이드는 주위 동료에게 아주 절친한 친구가 되어줄 수 있답니다. 세나리온 자치령에 있는 어느 드루이드에게 물어도 같은 대답을 할 겁니다.', `FemaleText_loc4`='在灰色年代，德鲁伊对周遭的人都很友好。你随便问塞纳里奥区的任何一个德鲁伊，他们会给出相同的说法的。', `FemaleText_loc5`='在灰色年代，德魯伊對周遭的人都很友好。你隨便問塞納里奧區的任何一個德魯伊，他們會給出相同的說法的。', `FemaleText_loc7`='En momentos difíciles, un druida puede ser un cálido amigo a quien acudir. Pregunta a cualquier druida del Enclave Cenarion y te dirán lo mismo.' WHERE `ID`=5343;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사제', `MaleText_loc4`='牧师', `MaleText_loc5`='牧師', `MaleText_loc7`='Sacerdote', `FemaleText_loc1`='사제', `FemaleText_loc4`='牧师', `FemaleText_loc5`='牧師', `FemaleText_loc7`='Sacerdote' WHERE `ID`=5344;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달의 신전은 엘룬의 사제들에게 집과 같은 곳입니다. 그곳으로 가시면 잔드리아와 라리아가 사제의 길에 대해 자세히 안내해줄 것입니다.', `MaleText_loc4`='月神殿是艾露恩的祭司们的家园。你会在那儿找到贾德莉亚和拉瑞亚，她们会对你的牧师生涯做出进一步的指导。', `MaleText_loc5`='月神殿是伊露恩的祭司們的家園。你會在那兒找到賈德莉亞和拉瑞亞，她們會對你的牧師生涯做出進一步的指導。', `MaleText_loc7`='El Templo de la Luna es el hogar de los sacerdotes de Elune. Allí encontrarás a Jandria y Lariia, quienes te proporcionarán toda la ayuda necesaria en tu camino al sacerdocio.', `FemaleText_loc1`='달의 신전은 엘룬의 사제들에게 집과 같은 곳입니다. 그곳으로 가시면 잔드리아와 라리아가 사제의 길에 대해 자세히 안내해줄 것입니다.', `FemaleText_loc4`='月神殿是艾露恩的祭司们的家园。你会在那儿找到贾德莉亚和拉瑞亚，她们会对你的牧师生涯做出进一步的指导。', `FemaleText_loc5`='月神殿是伊露恩的祭司們的家園。你會在那兒找到賈德莉亞和拉瑞亞，她們會對你的牧師生涯做出進一步的指導。', `FemaleText_loc7`='El Templo de la Luna es el hogar de los sacerdotes de Elune. Allí encontrarás a Jandria y Lariia, quienes te proporcionarán toda la ayuda necesaria en tu camino al sacerdocio.' WHERE `ID`=5345;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엘룬께서 끝없는 능력으로 그대를 인도하기를!

어서 가십시오. 다르나서스 남부에 있는 달의 신전 중앙 전당에서 잔드리아가 기다리고 있습니다.', `MaleText_loc4`='月神的力量支配着你！月神的力量支配着你！

出发吧！去达纳苏斯东部的月神殿中央大厅找贾德莉亚！', `MaleText_loc5`='伊露恩的力量支配著你!伊露恩的力量支配著你!

出發吧!去達納蘇斯南部的月神殿中央大廳找賈德莉亞!', `MaleText_loc7`='¡El poder de Elune te obliga! ¡El poder de Elune te obliga! 

¡Puedes marcharte! ¡Busca a Jandria en el pasillo central del Templo de la Luna en la zona sur de Darnassus!', `FemaleText_loc1`='엘룬께서 끝없는 능력으로 그대를 인도하기를!

어서 가십시오. 다르나서스 남부에 있는 달의 신전 중앙 전당에서 잔드리아가 기다리고 있습니다.', `FemaleText_loc4`='月神的力量支配着你！月神的力量支配着你！

出发吧！去达纳苏斯东部的月神殿中央大厅找贾德莉亚！', `FemaleText_loc5`='伊露恩的力量支配著你!伊露恩的力量支配著你!

出發吧!去達納蘇斯南部的月神殿中央大廳找賈德莉亞!', `FemaleText_loc7`='¡El poder de Elune te obliga! ¡El poder de Elune te obliga! 

¡Puedes marcharte! ¡Busca a Jandria en el pasillo central del Templo de la Luna en la zona sur de Darnassus!' WHERE `ID`=5346;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도적', `MaleText_loc4`='潜行者', `MaleText_loc5`='盜賊', `MaleText_loc7`='Pícaro', `FemaleText_loc1`='도적', `FemaleText_loc4`='潜行者', `FemaleText_loc5`='盜賊', `FemaleText_loc7`='Pícaro' WHERE `ID`=5347;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도적의 길을 걷겠다면 시우르나를 찾아가십시오. 그녀는 세나리온 자치령 서쪽 끝에 있는 나무 안의 소용돌이 모양의 길에서 기거하고 있습니다.', `MaleText_loc4`='要是你想做潜行者的话，就该去找塞尤娜。她居住在西部森林盘旋山道下的塞纳里奥区。', `MaleText_loc5`='要是你想做盜賊的話，就該去找塞尤娜。她居住在西部森林盤旋山道下的塞納里奧區。', `MaleText_loc7`='Tienes que acudir a Syurna si quieres seguir el camino de los pícaros. Ella vive en el Enclave Cenarion bajando el camino en espiral en el árbol situado más al oeste.', `FemaleText_loc1`='도적의 길을 걷겠다면 시우르나를 찾아가십시오. 그녀는 세나리온 자치령 서쪽 끝에 있는 나무 안의 소용돌이 모양의 길에서 기거하고 있습니다.', `FemaleText_loc4`='要是你想做潜行者的话，就该去找塞尤娜。她居住在西部森林盘旋山道下的塞纳里奥区。', `FemaleText_loc5`='要是你想做盜賊的話，就該去找塞尤娜。她居住在西部森林盤旋山道下的塞納里奧區。', `FemaleText_loc7`='Tienes que acudir a Syurna si quieres seguir el camino de los pícaros. Ella vive en el Enclave Cenarion bajando el camino en espiral en el árbol situado más al oeste.' WHERE `ID`=5348;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠을 사랑하여 도적의 길을 가려는 자들도 있지만, 진정으로 밤의 품에 안길 수 있는 건 우리 나이트 엘프뿐이랍니다. 그늘진 길을 걸어나가실 생각이시라면 세나리온 자치령에 있는 시우르나를 찾아가십시오.', `MaleText_loc4`='很多人都试图追随潜行者的脚步，但是只有暗夜精灵能真正被黑夜接受。如果你想在阴暗的道路上前行的话，就去塞纳里奥区找塞尤娜吧。', `MaleText_loc5`='很多人都試圖追隨著盜賊的腳步，但是只有夜精靈能真正被黑夜接受。如果你想在陰暗的道路上前行的話，就去塞納里奧區找塞尤娜吧。', `MaleText_loc7`='Existen algunos que intentan seguir el camino de los pícaros, pero solo los elfos de la noche disfrutan del cobijo de la noche. Si quieres seguir el camino tenebroso, busca a Syurna en el Enclave Cenarion.', `FemaleText_loc1`='어둠을 사랑하여 도적의 길을 가려는 자들도 있지만, 진정으로 밤의 품에 안길 수 있는 건 우리 나이트 엘프뿐이랍니다. 그늘진 길을 걸어나가실 생각이시라면 세나리온 자치령에 있는 시우르나를 찾아가십시오.', `FemaleText_loc4`='很多人都试图追随潜行者的脚步，但是只有暗夜精灵能真正被黑夜接受。如果你想在阴暗的道路上前行的话，就去塞纳里奥区找塞尤娜吧。', `FemaleText_loc5`='很多人都試圖追隨著盜賊的腳步，但是只有夜精靈能真正被黑夜接受。如果你想在陰暗的道路上前行的話，就去塞納里奧區找塞尤娜吧。', `FemaleText_loc7`='Existen algunos que intentan seguir el camino de los pícaros, pero solo los elfos de la noche disfrutan del cobijo de la noche. Si quieres seguir el camino tenebroso, busca a Syurna en el Enclave Cenarion.' WHERE `ID`=5349;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전사', `MaleText_loc4`='战士', `MaleText_loc5`='戰士', `MaleText_loc7`='Guerrero', `FemaleText_loc1`='전사', `FemaleText_loc4`='战士', `FemaleText_loc5`='戰士', `FemaleText_loc7`='Guerrero' WHERE `ID`=5350;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전사의 정원을 지키고 있는 파수꾼들 사이에서 실단나이르를 찾으십시오. 그녀는 혹시라도 적이 도시로 침입할 때를 대비해 텔드랏실의 숲 속을 감시하고 있습니다.', `MaleText_loc4`='你会在战士区的护卫队中找到希达奈尔，她敏锐的眼睛扫视着森林，寻找着胆敢进入我们美丽的城市的敌人。', `MaleText_loc5`='你會在戰士區的守衛中找到希達奈爾，她敏銳的眼睛掃視著森林，尋找著膽敢進入我們美麗的城市的敵人。', `MaleText_loc7`='Encontrarás a Sildinair en el Bancal del Guerrero entre los guardias, escrutando el bosque con sus ojos despiertos en busca de enemigos que pretendan entrar en nuestra hermosa ciudad.', `FemaleText_loc1`='전사의 정원을 지키고 있는 파수꾼들 사이에서 실단나이르를 찾으십시오. 그녀는 혹시라도 적이 도시로 침입할 때를 대비해 텔드랏실의 숲 속을 감시하고 있습니다.', `FemaleText_loc4`='你会在战士区的护卫队中找到希达奈尔，她敏锐的眼睛扫视着森林，寻找着胆敢进入我们美丽的城市的敌人。', `FemaleText_loc5`='你會在戰士區的守衛中找到希達奈爾，她敏銳的眼睛掃視著森林，尋找著膽敢進入我們美麗的城市的敵人。', `FemaleText_loc7`='Encontrarás a Sildinair en el Bancal del Guerrero entre los guardias, escrutando el bosque con sus ojos despiertos en busca de enemigos que pretendan entrar en nuestra hermosa ciudad.' WHERE `ID`=5351;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기술 전문가', `MaleText_loc4`='专业训练师', `MaleText_loc5`='專業技能訓練師', `MaleText_loc7`='Instructor de profesión', `FemaleText_loc1`='기술 전문가', `FemaleText_loc4`='专业训练师', `FemaleText_loc5`='專業技能訓練師', `FemaleText_loc7`='Instructor de profesión' WHERE `ID`=5352;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다르나서스의 장인들에게는 그대에게 도움이 될 만한 지식이 수천 가지는 있을 겁니다. 자, 말씀해 보십시오. 어떤 기술을 익히고 싶으세요?', `MaleText_loc4`='达纳苏斯的工匠们可传授给你很多工艺知识。告诉我，你对哪种工艺最好奇？', `MaleText_loc5`='達納蘇斯的工匠們可傳授很多工藝知識給你。告訴我，你對哪種工藝最好奇?', `MaleText_loc7`='Los artesanos de Darnassus encierran un milenio de conocimiento para el beneficio del oficio que has elegido. Ahora dime, ¿qué oficio consideras el más interesante?', `FemaleText_loc1`='다르나서스의 장인들에게는 그대에게 도움이 될 만한 지식이 수천 가지는 있을 겁니다. 자, 말씀해 보십시오. 어떤 기술을 익히고 싶으세요?', `FemaleText_loc4`='达纳苏斯的工匠们可传授给你很多工艺知识。告诉我，你对哪种工艺最好奇？', `FemaleText_loc5`='達納蘇斯的工匠們可傳授很多工藝知識給你。告訴我，你對哪種工藝最好奇?', `FemaleText_loc7`='Los artesanos de Darnassus encierran un milenio de conocimiento para el beneficio del oficio que has elegido. Ahora dime, ¿qué oficio consideras el más interesante?' WHERE `ID`=5353;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연금술', `MaleText_loc4`='炼金术', `MaleText_loc5`='鍊金術', `MaleText_loc7`='Alquimia', `FemaleText_loc1`='연금술', `FemaleText_loc4`='炼金术', `FemaleText_loc5`='鍊金術', `FemaleText_loc7`='Alquimia' WHERE `ID`=5354;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정 연금술을 배우고자 하신다면 다르나서스 북쪽, 장인의 정원으로 가서 뛰어난 실력을 지닌 에이네실이라는 연금술사를 찾으십시오.', `MaleText_loc4`='如果你真的想做这个职业，就去达纳苏斯北部的工匠区找一个技艺纯熟的炼金士：安尼希尔。', `MaleText_loc5`='如果你真的想學習這個專業技能，就去達納蘇斯北部的工匠區找一個技藝純熟的鍊金師:安尼希爾。', `MaleText_loc7`='Si realmente deseas aprender esta profesión, te guiaría hasta Ainethil, una alquimista experta que está en el Bancal del Artesano, en el norte de Darnassus.', `FemaleText_loc1`='진정 연금술을 배우고자 하신다면 다르나서스 북쪽, 장인의 정원으로 가서 뛰어난 실력을 지닌 에이네실이라는 연금술사를 찾으십시오.', `FemaleText_loc4`='如果你真的想做这个职业，就去达纳苏斯北部的工匠区找一个技艺纯熟的炼金士：安尼希尔。', `FemaleText_loc5`='如果你真的想學習這個專業技能，就去達納蘇斯北部的工匠區找一個技藝純熟的鍊金師:安尼希爾。', `FemaleText_loc7`='Si realmente deseas aprender esta profesión, te guiaría hasta Ainethil, una alquimista experta que está en el Bancal del Artesano, en el norte de Darnassus.' WHERE `ID`=5355;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요리', `MaleText_loc4`='烹饪', `MaleText_loc5`='烹飪', `MaleText_loc7`='Cocina', `FemaleText_loc1`='요리', `FemaleText_loc4`='烹饪', `FemaleText_loc5`='烹飪', `FemaleText_loc7`='Cocina' WHERE `ID`=5356;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알레고른은 수백 년 동안 요리 기술을 갈고 닦았지요. 그런 노련한 요리사에게 기술을 배울 수 있다면 정말 축복이라 여기십시오. 만약 그대에게 그럴 자격이 충분하다고 생각하거든 장인의 정원으로 찾아가 보십시오.', `MaleText_loc4`='阿雷贡是一名技艺精湛的厨师，数个世纪以来，他都在完善着自己的厨艺。要是他愿意教你的话，你就得谢天谢地了。要是你相信自己的实力的话，就去工匠区找他吧。', `MaleText_loc5`='阿雷貢是一名技藝精湛的廚師，數個世紀以來，他都在精進自己的廚藝。要是他願意教你的話，你就得謝天謝地了。要是你相信自己的實力的話，就去工匠區找他吧。', `MaleText_loc7`='Alegorn es un maestro chef que lleva perfeccionando su cocina desde hace siglos. Deberías considerarte tremendamente afortunado en el caso de que decidiera enseñarte. Si crees que eres $gdigno:digna; de ser su aprendiz, lo encontrarás en el Bancal del Artesano.', `FemaleText_loc1`='알레고른은 수백 년 동안 요리 기술을 갈고 닦았지요. 그런 노련한 요리사에게 기술을 배울 수 있다면 정말 축복이라 여기십시오. 만약 그대에게 그럴 자격이 충분하다고 생각하거든 장인의 정원으로 찾아가 보십시오.', `FemaleText_loc4`='阿雷贡是一名技艺精湛的厨师，数个世纪以来，他都在完善着自己的厨艺。要是他愿意教你的话，你就得谢天谢地了。要是你相信自己的实力的话，就去工匠区找他吧。', `FemaleText_loc5`='阿雷貢是一名技藝精湛的廚師，數個世紀以來，他都在精進自己的廚藝。要是他願意教你的話，你就得謝天謝地了。要是你相信自己的實力的話，就去工匠區找他吧。', `FemaleText_loc7`='Alegorn es un maestro chef que lleva perfeccionando su cocina desde hace siglos. Deberías considerarte tremendamente afortunado en el caso de que decidiera enseñarte. Si crees que eres $gdigno:digna; de ser su aprendiz, lo encontrarás en el Bancal del Artesano.' WHERE `ID`=5357;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알레고른이 뚝딱 만들어 내는 음식은 정말 맛이 끝내주지요. 그는 장인의 정원에서 새로운 별미를 만드느라 여념이 없습니다. 그곳에 세나리온 무침 요리 남은 게 있거든 꼭 한번 드셔 보세요.

자, 그럼 저는 이만 실례하겠습니다. 요새 부쩍 늘고 있는 사슴 실종 사건을 조사해야 하거든요.', `MaleText_loc4`='阿雷贡做的食物很受欢迎。他总是在工匠区忙于制作新的美食。要是有 塞纳里奥绿色烹饪的话，你一定要尝尝。

如果你不介意的话，我必须先去调查一下接二连三的鹿群失踪事件。', `MaleText_loc5`='阿雷貢做的食物很受歡迎。他總是在工匠區忙於製作新的美食。要是有 塞納里奧綠色烹飪的話，你一定要嘗嘗。

如果你不介意的話，我必須先去調查一下接二連三的鹿群失蹤事件。', `MaleText_loc7`='Los platos creados por Alegorn son para morirse. Siempre está ocupado preparando nuevas delicias en el Bancal del Artesano. No olvides probar su receta Verde Cenarion, si es que aún le queda algo. 

Ahora, si no te importa, tengo que investigar la ola de ciervos desaparecidos.', `FemaleText_loc1`='알레고른이 뚝딱 만들어 내는 음식은 정말 맛이 끝내주지요. 그는 장인의 정원에서 새로운 별미를 만드느라 여념이 없습니다. 그곳에 세나리온 무침 요리 남은 게 있거든 꼭 한번 드셔 보세요.

자, 그럼 저는 이만 실례하겠습니다. 요새 부쩍 늘고 있는 사슴 실종 사건을 조사해야 하거든요.', `FemaleText_loc4`='阿雷贡做的食物很受欢迎。他总是在工匠区忙于制作新的美食。要是有 塞纳里奥绿色烹饪的话，你一定要尝尝。

如果你不介意的话，我必须先去调查一下接二连三的鹿群失踪事件。', `FemaleText_loc5`='阿雷貢做的食物很受歡迎。他總是在工匠區忙於製作新的美食。要是有 塞納里奧綠色烹飪的話，你一定要嘗嘗。

如果你不介意的話，我必須先去調查一下接二連三的鹿群失蹤事件。', `FemaleText_loc7`='Los platos creados por Alegorn son para morirse. Siempre está ocupado preparando nuevas delicias en el Bancal del Artesano. No olvides probar su receta Verde Cenarion, si es que aún le queda algo. 

Ahora, si no te importa, tengo que investigar la ola de ciervos desaparecidos.' WHERE `ID`=5358;
