UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거, 이래서야 얼마나 멀리 갈 수 있을지 모르겠네요... 현기증이 좀 나는데...', `MaleText_loc4`='嗯，我不知道自己还能撑多久……我感到有些乏力……', `MaleText_loc5`='嗯，我不知道自己還能撐多久...我感到有些乏力...', `MaleText_loc7`='No sé hasta dónde llegaré en este estado... me siento muy débil...' WHERE `ID`=5391;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='만약 내가 어지러워하면, 마구 때려. 만약 내가 쓰러지면, 수통을 사용하고. 이제 가자고!', `MaleText_loc4`='记住，如果我迷糊了，就抽我的耳光。如果我晕厥的话，就用这个水壶。现在，我们走吧！', `MaleText_loc5`='如果我看起來暈暈的，就給我一巴掌。如果我昏了過去，就用水壺澆我。我們走吧!', `MaleText_loc7`='Si parezco mareado, abofetéame. Si me desmayo, usa la cantimplora. ¡Vamos!' WHERE `ID`=5392;
