UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 이제 기분이 좀 나아졌네요. 고마워요.', `MaleText_loc4`='我现在感觉好些了，谢谢你。', `MaleText_loc5`='我現在感覺好些了，謝謝你。', `MaleText_loc7`='Ya me siento un poco mejor, gracias.' WHERE `ID`=5399;
