UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기분이 어떠냐고요? 상당히 축축한 느낌인데요. 아무튼 고마워요.', `MaleText_loc4`='我感觉怎么样？简直湿透了，谢谢你。', `MaleText_loc5`='我感覺怎麼樣?簡直濕透了，謝謝你。', `MaleText_loc7`='¿Cómo me siento? Empapado, gracias.' WHERE `ID`=5401;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스프래글! 난 내가 돌아오지 못할 줄 알았어!', `MaleText_loc4`='斯普拉格！我简直不敢相信自己居然能活着回来！', `MaleText_loc5`='斯普拉格!我簡直不敢相信自己居然能活著回來!', `MaleText_loc7`='¡Spraggle! ¡Nunca creí que volvería!' WHERE `ID`=5402;
