UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='링고? 일어나봐! 아, 걱정하지 마세요. 제가 잘 돌봐 줄게요.', `FemaleText_loc4`='林格？快醒醒！不要担心，我会照顾你的。', `FemaleText_loc5`='林格?快醒醒!不要擔心，我會照顧你的。', `FemaleText_loc7`='¿Ringo? ¡Despierta! No te preocupes, me ocuparé de ti.' WHERE `ID`=5406;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아! 정말로 고맙네, $n! 드디어 난 자유야!', `MaleText_loc4`='啊！太感谢你了，$n！我自由了！终于自由了！', `MaleText_loc5`='啊!太感謝你了，$n!我自由了!終於自由了!', `MaleText_loc7`='¡Ay! ¡Muchas gracias, $n! ¡Soy libre! ¡Por fin!' WHERE `ID`=5407;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 자넨 알아서 해! 난 여기서 나갈 거라네.', `MaleText_loc4`='你照顾好你自己！我要离开这儿了。', `MaleText_loc5`='你照顧好你自己!我要離開這兒了。', `MaleText_loc7`='¡Tú haz lo que quieras! Yo me largo de aquí.' WHERE `ID`=5408;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끄응... 누구요?!', `MaleText_loc4`='有人吗？', `MaleText_loc5`='有人嗎?', `MaleText_loc7`='¿Hola?' WHERE `ID`=5409;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엄... 방해해서 미안하지만, 혹시 지금 보고 있지 않으면... 굿스틸 장부를 다시 보여 줄 수 없겠습니까?', `MaleText_loc4`='嗯……很抱歉打扰你，如果你现在没有在用古德斯迪尔的账本……能让我再看看吗？', `MaleText_loc5`='嗯...很抱歉打擾你，如果你現在沒有在用古德斯迪爾的帳本...能讓我再看看嗎?', `MaleText_loc7`='Um... siento molestarte, pero ¿podría volver a ver el libro de contabilidad de Buenacero... si no lo estás usando?', `FemaleText_loc1`='엄... 방해해서 미안하지만, 혹시 지금 보고 있지 않으면... 굿스틸 장부를 다시 보여 줄 수 없겠습니까?', `FemaleText_loc4`='嗯……很抱歉打扰你，如果你现在没有在用古德斯迪尔的账本……能让我再看看吗？', `FemaleText_loc5`='嗯...很抱歉打擾你，如果你現在沒有在用古德斯迪爾的帳本...能讓我再看看嗎?', `FemaleText_loc7`='Um... siento molestarte, pero ¿podría volver a ver el libro de contabilidad de Buenacero... si no lo estás usando?' WHERE `ID`=5410;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 물론이네, $n! 미안, 난 또 다 본 줄 알았지.', `MaleText_loc4`='啊，没问题，$n！对不起……我还以为你已经搞定了。', `MaleText_loc5`='啊，沒問題，$n!對不起...我還以為你已經搞定了。', `MaleText_loc7`='¡Sí, claro, $n! Lo siento... creí que ya habías terminado.' WHERE `ID`=5411;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잠깐만 기다려 주세요. 지금은 나가들이 공격을 해 대고 있어서... 공격이 끝나는 대로 제가 얘기하죠!', `FemaleText_loc4`='你必须给我一点时间，$c，纳迦正在攻击我们。搞定他们之后再来找我！', `FemaleText_loc5`='你必須給我一點時間，$c，納迦正在攻擊我們。搞定他們之後再來找我!', `FemaleText_loc7`='Tendrás que esperar un momento, $c, los nagas nos están atacando ahora mismo. ¡Hablaré contigo en cuanto el ataque haya terminado!' WHERE `ID`=5412;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야기를 들려주세요, 존.', `MaleText_loc4`='约翰，给我讲个故事吧。', `MaleText_loc5`='約翰，給我講個故事吧。', `MaleText_loc7`='Cuéntame una historia, John.', `FemaleText_loc1`='이야기를 들려주세요, 존.', `FemaleText_loc4`='约翰，给我讲个故事吧。', `FemaleText_loc5`='約翰，給我講個故事吧。', `FemaleText_loc7`='Cuéntame una historia, John.' WHERE `ID`=5413;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋소. *딸꾹*... 근데, 당신 낯이 익어. *딸꾹* 나하고 윈저가 수 처... 으... 처... 수 백만이나 되는 오크를 물리친 얘기를 들려줬던가? 꺼억!$B$B좀 앉아 보시오, 친구. 아주 멋진 얘기니까!', `MaleText_loc4`='好吧*嗝儿*……嗯，你看起来很眼熟*嗝儿*。我有跟你说过我和温德索尔一起跟，呃，一，一百万个兽人战斗的事儿吗？$B$B哦，坐下来吧，朋友，这个故事非常棒的！', `MaleText_loc5`='好吧*嗝兒*...嗯，你看起來很眼熟*嗝兒*。我有跟你說過我和溫德索爾一起跟，呃，一，一百萬個獸人戰鬥的事兒嗎?$B$B哦，坐下來吧，朋友，這個故事非常棒的!', `MaleText_loc7`='De acuerdo, *hip*... Vaya, me suena tu cara *hip*. ¿Alguna vez te he hablado de la vez en que Windsor y yo luchamos contra... miles... Ejem... un millón de orcos?$B$B¡Siéntate, esta historia es buena!' WHERE `ID`=5414;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 팝콘이라도 가져올게요, 털보.', `MaleText_loc4`='阁下，让我拿些玉米仁吧。', `MaleText_loc5`='閣下，讓我拿些玉米仁吧。', `MaleText_loc7`='Deja que coja palomitas.', `FemaleText_loc1`='그럼 팝콘이라도 가져올게요, 털보.', `FemaleText_loc4`='阁下，让我拿些玉米仁吧。', `FemaleText_loc5`='閣下，讓我拿些玉米仁吧。', `FemaleText_loc7`='Déjeme que coja palomitas.' WHERE `ID`=5415;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='골격의 고서를 드리겠습니다.', `MaleText_loc4`='这是给你的体质圣契。', `MaleText_loc5`='這是給你的體質聖契。', `MaleText_loc7`='Te presento el tratado sobre Constitución.', `FemaleText_loc1`='골격의 고서를 드리겠습니다.', `FemaleText_loc4`='这是给你的体质圣契。', `FemaleText_loc5`='這是給你的體質聖契。', `FemaleText_loc7`='Te presento el tratado sobre Constitución.' WHERE `ID`=5416;
