UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탄력의 고서를 드리겠습니다.', `MaleText_loc4`='这是给你的恢复圣契。', `MaleText_loc5`='這是給你的韌性聖契。', `MaleText_loc7`='Te presento el tratado sobre Resistencia.', `FemaleText_loc1`='탄력의 고서를 드리겠습니다.', `FemaleText_loc4`='这是给你的恢复圣契。', `FemaleText_loc5`='這是給你的韌性聖契。', `FemaleText_loc7`='Te presento el tratado sobre Resistencia.' WHERE `ID`=5418;
