UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수정에 미끼를 달자 %s|1이;가; 부화장 안으로 뛰어들어옵니다!', `MaleText_loc4`='在你把诱饵涂抹到水晶上之后，%s立刻冲进了孵卵所！', `MaleText_loc5`='你一把誘餌抹在水晶之上%s就衝進了孵化室!', `MaleText_loc7`='%s se dirige al criadero una vez que colocas el cebo en el cristal.' WHERE `ID`=5420;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오그리마 경매장은 힘의 골짜기에 있네. 붐스틱 수입상의 오른쪽 건물이니 한번 찾아가보게.', `MaleText_loc4`='奥格瑞玛拍卖所位于力量谷。去火枪进口公司东面找它吧。', `MaleText_loc5`='奧格瑪拍賣場位於力量谷。去火槍進口公司東面找它吧。', `MaleText_loc7`='La casa de subastas de Orgrimmar está en el Valle de la Fuerza. Búscala en el este, junto a Importaciones Bocarda.', `FemaleText_loc1`='오그리마 경매장은 힘의 골짜기에 있네. 붐스틱 수입상의 오른쪽 건물이니 한번 찾아가보게.', `FemaleText_loc4`='奥格瑞玛拍卖所位于力量谷。去火枪进口公司东面找它吧。', `FemaleText_loc5`='奧格瑪拍賣場位於力量谷。去火槍進口公司東面找它吧。', `FemaleText_loc7`='La casa de subastas de Orgrimmar está en el Valle de la Fuerza. Búscala en el este, junto a Importaciones Bocarda.' WHERE `ID`=5421;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소리를 지르느라 목이 쉬었군? 힘의 골짜기에서 오그리마 경매장을 찾아보게.', `MaleText_loc4`='你的嗓子喊哑了是吗？在力量谷就可以找到奥格瑞玛拍卖行。', `MaleText_loc5`='你的嗓子喊啞了是嗎?在力量谷就可以找到奧格瑪拍賣場。', `MaleText_loc7`='Tienes la voz ronca de tanto gritar, ¿eh? Encuentra la casa de subastas de Orgrimmar en el Valle de la Fuerza.', `FemaleText_loc1`='소리를 지르느라 목이 쉬었군? 힘의 골짜기에서 오그리마 경매장을 찾아보게.', `FemaleText_loc4`='你的嗓子喊哑了是吗？在力量谷就可以找到奥格瑞玛拍卖行。', `FemaleText_loc5`='你的嗓子喊啞了是嗎?在力量谷就可以找到奧格瑪拍賣場。', `FemaleText_loc7`='¿Tienes la voz ronca de tanto gritar, eh? Encuentra la casa de subastas de Orgrimmar en el Valle de la Fuerza.' WHERE `ID`=5422;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경매장', `MaleText_loc4`='拍卖行', `MaleText_loc5`='拍賣場', `MaleText_loc7`='Casa de subastas', `FemaleText_loc1`='경매장', `FemaleText_loc4`='拍卖行', `FemaleText_loc5`='拍賣場', `FemaleText_loc7`='Casa de subastas' WHERE `ID`=5423;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다르나서스 은행에 오신 걸 환영합니다. 저희 은행에서는 금융 계좌는 물론 각종 귀중품을 보관하기 위한 안전 금고도 제공합니다. 저희 은행에 계좌를 가지고 계십니까, 손님?', `MaleText_loc4`='欢迎来到达纳苏斯银行。我们提供金融帐户和存储贵重物品的保险箱。你要开户吗$g先生:女士;？', `MaleText_loc5`='歡迎來到達納蘇斯銀行。我們提供金融帳戶和存儲貴重物品的保險箱。你要開戶嗎$g先生:女士;?', `MaleText_loc7`='Te doy la bienvenida al Banco de Darnassus. Ofrecemos cuentas financieras y cajas fuertes para depositar artículos valiosos. ¿Ya tienes una cuenta con nosotros, $gseñor:señora;?', `FemaleText_loc1`='다르나서스 은행에 오신 걸 환영합니다. 저희 은행에서는 금융 계좌는 물론 각종 귀중품을 보관하기 위한 안전 금고도 제공합니다. 저희 은행에 계좌를 가지고 계십니까, 손님?', `FemaleText_loc4`='欢迎来到达纳苏斯银行。我们提供金融帐户和存储贵重物品的保险箱。你要开户吗$g先生:女士;？', `FemaleText_loc5`='歡迎來到達納蘇斯銀行。我們提供金融帳戶和存儲貴重物品的保險箱。你要開戶嗎$g先生:女士;?', `FemaleText_loc7`='Te doy la bienvenida al Banco de Darnassus. Ofrecemos cuentas financieras y cajas fuertes para depositar artículos valiosos. ¿Ya tiene una cuenta con nosotros, $gseñor:señora;?' WHERE `ID`=5424;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놀랍지 않소? 이 역사의 잔재들이...$B$B날 얼마나 더 놀라게 할지 가늠할 수 없소이다. 그 굉장한 크기? 아니면 유구한 역사? 조사할 게 너무나도 많소. 어떤 연관성이 있는지 알아내야지.$B$B그런데 혹시 여러 종족이 나이트 엘프와 같은 전통을 가지고 있다는 소문을 들어 본 적이 있소?', `MaleText_loc4`='不可思议，不是吗？所有这些神器和残骸。$B$B我不清楚是什么给我留下了更为深刻的印象，它们的规模，还是它们背后的故事。要学习的东西还很多。我们能找到其中的关联……$B$B你知道那个传闻吗，听说许多种族与暗夜精灵有着相同的遗产。', `MaleText_loc5`='太不可思議了，你說對吧?這麼多的文物和東西。$B$B我都不知道該對什麼訝異了，是該訝異它們的規模，還是它們背後的故事。要研究和學習的東西實在太多了，說不定我們還能找到什麼新的關聯...$b$b你知道那個傳聞嗎，聽說許多種族與夜精靈有著相同的血脈。', `MaleText_loc7`='Son sorprendentes, ¿verdad? Todos estos artefactos y restos.$B$BNo sé qué me impresiona más, si su tamaño o las historias que se cuentan sobre ellos. Hay tanto que estudiar y aprender... y los vínculos que se pueden establecer... $B$B¿Sabías que se dice que muchas razas comparten la herencia de los elfos de la noche?' WHERE `ID`=5425;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형상 소멸까지 앞으로 60초...', `MaleText_loc4`='影像将在一分钟内消散。', `MaleText_loc5`='影像將在一分鐘內消散。', `MaleText_loc7`='Disipación de imagen en sesenta segundos.' WHERE `ID`=5426;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 강력한 주문을 시전합니다.', `MaleText_loc4`='%s开始施放法术。', `MaleText_loc5`='%s開始施展強大的法術。', `MaleText_loc7`='%s comienza a lanzar un poderoso encantamiento.' WHERE `ID`=5427;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 물건들을 토템으로 변환합니다.', `MaleText_loc4`='%s将这些物品转换成一个图腾。', `MaleText_loc5`='%s將這些物品轉換成一個圖騰。', `MaleText_loc7`='%s transforma los objetos en un tótem.' WHERE `ID`=5428;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 타우릿산 제왕이 죽는 것을 보고 상당히 놀란 것 같습니다.', `FemaleText_loc4`='%s显然对索瑞森大帝的死亡感到震惊。', `FemaleText_loc5`='%s很明顯的因為索瑞森大帝的死亡而震驚。', `FemaleText_loc7`='%s está visiblemente afectado por la muerte del emperador Thaurissan.' WHERE `ID`=5429;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타우릿산 제왕께서는 혼자 계시고 싶어하신다! 지금 돌아서든가 그렇지 않으면 죽음을 맛보아라, 나약한 녀석들!', `MaleText_loc4`='索瑞森大帝不希望有人打扰他！滚回去面对自己的命运吧，你们这些懦弱的人！', `MaleText_loc5`='索瑞森大帝不希望有人打擾他!滾回去面對自己的命運吧，你們這些懦弱的人!', `MaleText_loc7`='¡El emperador Thaurissan no desea ser perturbado! ¡Regresen ahora o enfréntense a su fin, débiles mortales!' WHERE `ID`=5430;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여봐라, 국왕 행차시다!', `MaleText_loc4`='为国王欢呼吧，宝贝！', `MaleText_loc5`='為國王歡呼吧，寶貝!', `MaleText_loc7`='¡Viva el rey, nena!' WHERE `ID`=5431;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요? 난 페트라라고 하고 내 오른쪽은 내 코도, 다단가라고 합니다. 우린 먀살 원정대 소속이죠. 다단가가 새끼였던 이후로 벌써 몇 년이 지났군요.$B$B횃불이나 다른 화기 종류가 있다면 부디 감추어 주세요. 다단가는 연기를 싫어하거든요.', `FemaleText_loc4`='嗨，我是派提亚。在我右边是科多兽达丹加。我们曾跟马歇尔探险队在一起——那已经是数年前的事儿了，那时达丹加还是只幼兽呢。$B$B要是你带有火炬或是任何火种，请尽可能地把它们藏起来。达丹加不喜欢烟。', `FemaleText_loc5`='嗨，我是派提亞。在我右邊是科多獸達丹加。我們曾跟馬歇爾探險隊在一起─那已經是數年前的事兒了，那時達丹加還是只幼獸呢。$B$B要是你帶有火炬或是任何火種，請盡可能地把它們藏起來。達丹加不喜歡煙。', `FemaleText_loc7`='Hola, mi nombre es Petra. A mi derecha está mi kodo, Dadanga. Estamos con Expediciones Marshal. De hecho, lo hemos estado durante unos cuantos años, desde que Dadanga era pequeño.$B$BSi tienes antorchas encendidas o cualquier fuente de ignición, te pediría que las guardases si puedes. A Dadanga no le gusta el humo.' WHERE `ID`=5432;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제발 엎드려서 빌기라도 할 테니, 이 몹쓸 땅에서 우리를 좀 구해 주게. 비록 내가 마샬 원정대 소속이긴 하지만, 자네 배낭 안에 숨어 이곳을 뜰 수만 있다면 내 금니라도 뽑아서 주지.', `MaleText_loc4`='为了所有神圣高贵的爱，请告诉我你是来把我们从这片被遗忘之地带走的。虽然我是与马绍尔探险队一起的，我愿给你我口中的金牙，只要你让我爬进你的背包并离开这个地方。', `MaleText_loc5`='為了所有神聖高貴的愛，請告訴我你是來把我們從這片被遺忘之地帶走的。雖然我是與馬紹爾探險隊一起的，我願給你我口中的金牙，只要你讓我爬進你的背包並離開這個地方。', `MaleText_loc7`='Por lo más sagrado, dime que has venido a rescatarnos de esta tierra abandonada. Aunque estoy con Expediciones Marshal, te daría mi diente de oro por subirme en tu mochila y dejar este lugar.' WHERE `ID`=5433;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어머나, 안녕하세요! 저는 마샬 원정대의 수석 과학자 겸 생물학자, 홀라니에라고 합니다. 저와 오빠는 동료와 함께 온 아제로스를 여행하며 장엄한 야생의 세계를 탐험하지요. 참 재미있는 일인데... 이번에는... 그 재미의 도가 좀 지나쳤던 모양이에요!', `FemaleText_loc4`='哦，你好！我是霍莱伊，马绍尔探险队的首席科学家和生物学家。我的兄弟和我，还有我们的同伴，一起到艾泽拉斯去探索荒野和未被驯化的雄伟景象。真是太激动人心了……但是，嗯……我想这次我们陷入了太多激动中了！', `FemaleText_loc5`='哦，你好!我是霍萊伊，馬紹爾探險隊的首席科學家和生物學家。我的兄弟和我，還有我們的同伴，一起到艾澤拉斯去探索荒野和未被馴化的雄偉景象。真是太激動人心了...但是，嗯...我想這次我們陷入了太多激動中了!', `FemaleText_loc7`='¡Hola! Soy Hol''anyee, la jefa científica y bióloga de Expediciones Marshal. Mi hermano y yo, junto con nuestros compañeros, viajamos por Azeroth para explorar la majestuosidad de la naturaleza salvaje. Es emocionante, pero... um... ¡Creo que esta vez nos hemos excedido en nuestra dosis de emoción!' WHERE `ID`=5434;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, 이방인 친구. 야생이 살아 숨 쉬는 운고로 분화구에 온 것을 환영합니다! 저는 윌리덴 마샬이라고 합니다. 저와 제 여동생, 그리고 동료는 마샬 원정대를 구성하고 있습니다. 우리는 위대한 아제로스의 야생과 미지의 세계를 탐험하는 과학자와 탐험가들이죠.', `MaleText_loc4`='你好，陌生人。欢迎你来到遍布丛莽的安戈洛环形山！$B$B我叫威利德·马绍尔。我、我的姐妹以及同伴组成了马绍尔探险队——致力于探索艾泽拉斯荒野和未知之地的科学家和探险家们。', `MaleText_loc5`='嗨，陌生人，歡迎來到安戈洛環形山這個失樂園!$B$B我叫威利德·馬紹爾。我、我的姐妹以及同伴組成了馬紹爾探險隊，一組探索艾澤拉斯神秘和不可思議的科學家和探險家們。', `MaleText_loc7`='Hola, $gextraño:extraña;, ¡te doy la bienvenida a la majestuosidad salvaje del cráter Un’Goro!$B$BMi nombre es Williden Marshal. Mi hermana, nuestros compañeros y yo formamos Expediciones Marshal, un grupo de científicos y exploradores del Azeroth más salvaje y desconocido.' WHERE `ID`=5435;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기서 일이 재밌어진답니다. 왼쪽으로 산맥의 절벽을 끼고 죽 따라갈 계획입니다. 그렇게 하면 밀림에서 길을 잃지 않고, 도중에 사나운 짐승도 덜 만나게 될 겁니다. 자, 준비됐나요?', `FemaleText_loc4`='事情变得有趣起来。我的计划是沿着左侧的山前进。这样我们就不会在丛林中迷路，还能避开敌人。你准备好了吗？', `FemaleText_loc5`='事情變得有趣起來。我的計畫是沿著左側的山前進。這樣我們就不會在叢林中迷路，還能避開敵人。你準備好了嗎?', `FemaleText_loc7`='Aquí es donde las cosas se ponen interesantes. Mi plan es recorrer la ladera de las montañas, manteniéndolas a nuestra izquierda. De esa manera, no nos perderemos en el bosque y podremos combatir mejor al enemigo. ¿Preparados?' WHERE `ID`=5436;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='산맥의 동부로군요! 자, 이제 남쪽으로 꺾겠습니다. 아직 완전히 빠져나간 게 아니니 뒤처지지 마세요.', `FemaleText_loc4`='这是东部的山墙！我现在正向南推进；跟紧了。我们还不会从最危险的地方撤离！', `FemaleText_loc5`='這是東部的山牆!我現在正向南推進;跟緊了。我們還不會從最危險的地方撤離!', `FemaleText_loc7`='¡Esta es la barrera de montañas del este! Ahora me dirijo hacia el sur. Intenta seguir el paso. ¡Aún no ha pasado lo peor!' WHERE `ID`=5437;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='드디어 운고로에서 빠져나가는 길이에요! 해냈군요! 자, 이제부터는 타나리스 사막만 걱정하면 돼요.', `FemaleText_loc4`='这就是离开安戈洛的路！我们做到了！现在我们所担心的就是塔纳利斯沙漠了。', `FemaleText_loc5`='這就是離開安戈洛的路!我們做到了!現在我們所擔心的就是塔納利斯沙漠了。', `FemaleText_loc7`='¡Este es el camino para salir de Un''Goro! ¡Lo hemos conseguido! Lo único que debe preocuparnos ahora es el Desierto de Tanaris.' WHERE `ID`=5439;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='타나리스 사막이로군요. 이렇게 험한 곳도 반갑다니, 재밌네요. 하마터면 영원히 푸른 밀림에 갇혀 있을 뻔했으니 당연하죠.', `FemaleText_loc4`='就是这儿——塔纳利斯沙漠。这样荒凉的地方比难以走出的绿色丛林看起来好多了，这可真有意思。', `FemaleText_loc5`='就是這兒─塔納利斯沙漠。這樣荒涼的地方比難以走出的綠色叢林看起來好多了，這可真有意思。', `FemaleText_loc7`='Aquí está: el Desierto de Tanaris. Es extraño cómo un lugar tan inhóspito como este parece más agradable que la jungla exuberante una vez que te encuentras atrapado en él.' WHERE `ID`=5440;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은무쇠 제국에 반하는 범죄를 저질렀으므로 사형을 선고한다!', `MaleText_loc4`='你因为反对黑铁王国的罪行而被宣判死罪！', `MaleText_loc5`='你因為反對黑鐵王國的罪行而被宣判死罪!', `MaleText_loc7`='¡Se os ha sentenciado a muerte por delitos cometidos contra la nación Hierro Negro!' WHERE `ID`=5441;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타우릿산의 아드님들께서 너희가 법의 심판장에서 종말을 맞이하는 모습을 지켜볼 것이다!', `MaleText_loc4`='索瑞森的臣民将在秩序竞技场中看着你死去！', `MaleText_loc5`='索瑞森的臣民將在秩序競技場中看著你死去!', `MaleText_loc7`='¡Los hijos de Thaurissan os verán morir en el Círculo de la Ley!' WHERE `ID`=5442;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분노를 참지 말고 처단하라!', `MaleText_loc4`='释放你的怒气吧！', `MaleText_loc5`='釋放你的怒氣吧!', `MaleText_loc7`='¡Desaten su furia y castigen a los culpables!' WHERE `ID`=5443;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하! 그냥 죽일 줄 알았더냐!', `MaleText_loc4`='哈！我敢打赌你以为自己能获胜！', `MaleText_loc5`='哈!我敢打賭你以為自己能獲勝!', `MaleText_loc7`='¡Ja, ja! ¡A que pensabas que eso era todo!' WHERE `ID`=5444;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정한 처형이 너를 기다리고 있도다.', `MaleText_loc4`='但是真正的惩戒还在后面呢。', `MaleText_loc5`='但是真正的懲罰還在後面呢。', `MaleText_loc7`='Pero tu verdadero castigo no ha comenzado aún.' WHERE `ID`=5445;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 해치웠다!', `MaleText_loc4`='很好！', `MaleText_loc5`='很好!', `MaleText_loc7`='¡Hasta nunca!' WHERE `ID`=5446;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='믿어지지 않는군! 놀라워! 도대체 이게 무슨 뜻인지도 모르겠소이다!', `MaleText_loc4`='难以置信！太令我惊讶了！我甚至根本不知道这意味着什么！', `MaleText_loc5`='難以置信!太令我驚訝了!我甚至根本不知道這意味著什麼!', `MaleText_loc7`='¡Increíble! ¡Sorprendente! ¡Ni siquiera sé lo que esto significa!' WHERE `ID`=5447;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 견본들을 보시오! 이게 무슨 뜻일까? 이게 무슨 뜻일 것 같소? 시간이 필요할 거요. 이 모든 정보를 살펴 볼 시간이... 그리고 정보가 더 필요하오. 내가 얻을 수 없는 정보... 젠장! 머리를 써, 라리스! 머리를!$B$B어떻게 할 거야? 어떻게?$B$B해결책은 반드시 있을 거라고!', `MaleText_loc4`='看看这些样本！这意味着什么？这意味着什么？我需要时间来解读这些信息。我还需要更多我无法获得的信息……该死！好好想想，拉里斯，好好想想！$B$B你要做什么？什么？！$B$B必须得有解决的方法！', `MaleText_loc5`='看看這些樣本!這意?著什麼?這意味著什麼?我需要時間來解讀這些資訊。我還需要更多我無法獲得的資訊...該死!好好想想，拉里斯，好好想想!$B$B你要做什麼?什麼?!$B$B必須得有解決的方法!', `MaleText_loc7`='¡Mirad estas muestras! ¿Eso qué significa? ¿Eso qué significa? Voy a necesitar tiempo, tiempo para estudiar toda esta información. Y necesitaré más información. ¡Información que no puedo encontrar.. maldita sea! ¡Piensa, Laris, piensa!$B$B¿Qué vas a hacer? ¡¿Qué?!$B$B¡Tiene que haber una solución!' WHERE `ID`=5448;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분명 아제로스 어딘가에 스컬지나 다른 것들에 의해 오염되지 않은 수액괴물들이 있을 텐데... 그런데 그게 대체 어디냔 말이지!', `MaleText_loc4`='在艾泽拉斯，一定有未被亡灵天灾侵蚀的软泥怪。但是在哪儿呢？', `MaleText_loc5`='在艾澤拉斯，一定有未被天譴軍團侵蝕的軟泥怪。但是在哪兒呢?', `MaleText_loc7`='Tiene que haber un lugar un Azeroth en el que haya moco no contaminado por la Plaga o libre de cualquier tipo de contaminación. ¡¿Pero dónde?!' WHERE `ID`=5449;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수액괴물과 진흙괴물 사이에 무슨 차이가 있습니까?', `MaleText_loc4`='软泥怪和泥浆怪有何不同？', `MaleText_loc5`='軟泥怪和泥漿怪有何不同?', `MaleText_loc7`='¿Hay alguna diferencia entre el moco y la baba?', `FemaleText_loc1`='수액괴물과 진흙괴물 사이에 무슨 차이가 있습니까?', `FemaleText_loc4`='软泥怪和泥浆怪有何不同？', `FemaleText_loc5`='軟泥怪和泥漿怪有何不同?', `FemaleText_loc7`='¿Hay alguna diferencia entre el moco y la baba?' WHERE `ID`=5450;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런 것 같지는 않소. 대부분 지역 특색에 따라 다른 것 같은데 어떤 종족들은 그걸 수액괴물이라고 부르고, 어떤 종족들은 진흙괴물이라고 부른다오. 대체로 취향의 문제인 것 같소.$B$B수액괴물이나 녹괴물, 진흙괴물을 접할 때마다 겉모양은 기본적으로 다 똑같은 생물들이었소. 환경에 따라 차이가 있는 것이기에 순수한 견본이 필요한 거요.', `MaleText_loc4`='不，我并不清楚。似乎那主要与地域有关。有些种类称为泥浆怪，有些称为软泥怪。似乎这属于个人偏好。$B$B每次我遇到软泥怪、淤泥怪或泥浆怪时，它们从根本上都是一种生物。不同之处在于它们的环境，这也是我们需要一份纯净的样本的原因。', `MaleText_loc5`='不，我並不清楚。似乎那主要與地域有關。有些種類稱為泥漿怪，有些稱為軟泥怪。似乎這屬於個人偏好。$B$B每次我遇到軟泥怪、爛泥怪或泥漿怪時，它們從根本上都是一種生物。不同之處在於它們的環境，這也是我們需要一份純淨的樣本的原因。', `MaleText_loc7`='No, yo al menos no la percibo. Al parecer, depende básicamente de la zona. Algunas razas la han llamado baba y otras, moco. Al parecer, es cuestión de preferencias.$B$BCada vez que he encontrado moco, barro o baba, se ha tratado siempre de las mismas criaturas. Las diferencias parecen basarse en el entorno, por lo que necesitamos una muestra pura.' WHERE `ID`=5451;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"순수하다"니 무슨 말씀입니까?', `MaleText_loc4`='你说的“纯净”是什么意思？', `MaleText_loc5`='你說的「純淨」是什麼意思?', `MaleText_loc7`='¿A qué te refieres con "pura?"', `FemaleText_loc1`='"순수하다"니 무슨 말씀입니까?', `FemaleText_loc4`='你说的“纯净”是什么意思？', `FemaleText_loc5`='你說的「純淨」是什麼意思?', `FemaleText_loc7`='¿A qué te refieres con "pura?"' WHERE `ID`=5452;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='순수한 견본이라면 어떤 영향에 의해서도 오염되지 않은 걸 말하는 거요. 가장 단순하고 정상적인 환경에서 이 생물들을 찾아야만 하오.$B$B그것은 곧 문명이 발달하지 않았거나 아제로스 주요 종족들의 영향을 받지 않은 곳을 말하는데, 어딘가... 천연 그대로의 장소라야 하오.', `MaleText_loc4`='一个纯净的样品就是在非故意情况下未被腐蚀的样品。我们需要尽可能在最基本，最正常的环境中找到这样的生物。$B$B这意味着某个全无文明痕迹或是未受艾泽拉斯某个种族所影响的地方。某块……处女地。', `MaleText_loc5`='一個純淨的樣品就是在非故意情況下未被腐蝕的樣品。我們需要盡可能在最基本，最正常的環境中找到這樣的生物。$B$B這意味著某個全無文明痕跡或是未受艾澤拉斯某個種族所影響的地方。某塊...處女地。', `MaleText_loc7`='Una muestra pura es la que no ha sido contaminada por influencias no deseadas. Tenemos que encontrar criaturas en su entorno más básico y normal posible.$B$BEsto supone un lugar apartado de la civilización o de los efectos de las razas dominantes de Azeroth. Un lugar... intacto.' WHERE `ID`=5453;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇게 천연 그대로일만한 장소가 있습니까?', `MaleText_loc4`='你认为还有这样一块处女地吗？', `MaleText_loc5`='你認為還有這樣一塊處女地嗎?', `MaleText_loc7`='¿Conoces alguna zona que esté tan intacta?', `FemaleText_loc1`='그렇게 천연 그대로일만한 장소가 있습니까?', `FemaleText_loc4`='你认为还有这样一块处女地吗？', `FemaleText_loc5`='你認為還有這樣一塊處女地嗎?', `FemaleText_loc7`='¿Conoces alguna zona que esté tan intacta?' WHERE `ID`=5454;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런 곳은 동부 왕국에서는 절대 찾을 수 없소.$B$B칼림도어 어딘가에서 찾아야 하겠지만 호드를 비롯한 다른 모든 종족에게서 멀리 떨어진 곳이라야 하오. 대륙 분리의 영향도 받지 않아야 하니, 나이트 엘프 문명 근처는 아니겠지.$B$B아마 자연적으로 보호되는 곳일 거요. 골짜기라든가 분화구라든가... 음, 잘 모르겠소. 단지 내 추측일 뿐이니, 더 도움이 되지 못해서 미안하오.', `MaleText_loc4`='那绝不是东部王国的任何一个地方。$B$B一定是在卡利姆多大陆的某处，但是距离部落和其他种族仍有相当遥远的距离。还没有受到分裂影响的某个地方——远离暗夜精灵文明的地方。$B$B我猜有人守护在那儿……就像守护山谷或是环形山一样；我不确定。我只是猜测。很抱歉我不能提供更多的帮助了。', `MaleText_loc5`='那絕不是東部王國的任何一個地方。$B$B一定是在卡林多大陸的某處，但是距離部落和其他種族仍有相當遙遠的距離。還沒有受到大爆炸影響的某個地方─遠離夜精靈文明的地方。$B$B我猜有人守護在那兒...就像守護山谷或是環形山一樣;我不確定。我只是猜測。很抱歉我不能提供更多的幫助了。', `MaleText_loc7`='Definitivamente no estará en ningún lugar de los Reinos del Este, eso está claro.$B$BTiene que ser algún lugar de Kalimdor, pero lo suficientemente lejos de la Horda y de otras razas. Un lugar que no haya sufrido los estragos del Cataclismo, en otras palabras, un lugar que también esté apartado de la civilización de los elfos de la noche.$B$BSupongo que debería ser un lugar protegido, como un valle o un cráter. No lo sé. Solo es una suposición. Siento no poder ayudarte más.' WHERE `ID`=5455;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오시오. $c. 연금술 실험실은 물론이고, 그중에서도 이곳까지 방문객이 오는 일은 매우 드문데... 물론, 뭔가 특별한 걸 필요로 한다면 얘기가 다르지만.$B$B<키득키득 웃으며...>$B$B도와 드릴 일이라도?', `MaleText_loc4`='欢迎你，$c。炼金房区很少有访客……当然，除非有人对这儿的某些东西感兴趣。$B$B<炼金师克林笑起来。>$B$B我能帮助你吗？', `MaleText_loc5`='歡迎你，$c。鍊金房區很少有訪客...當然，除非有人對這兒的某些東西感興趣。$B$B<鍊金師克林笑起來。>$B$B有什麼我能幫忙的嗎?', `MaleText_loc7`='Te doy la bienvenida, $c. Rara vez tenemos visitantes en estos niveles del Apothecarium... a menos que tengamos algo que alguien quiera... o necesita.$B$B<El químico Coely ríe.>$B$B¿En qué te puedo ayudar hoy, eh?' WHERE `ID`=5456;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈을 작디작은 조각으로 박살 내겠다!', `MaleText_loc4`='我要把你打成碎片！', `MaleText_loc5`='我要把你碎屍萬段!', `MaleText_loc7`='¡Te aplastaré y reduciré a pedazos minúsculos!' WHERE `ID`=5457;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 낮은 소리로 신음합니다.', `MaleText_loc4`='%s呻吟着。', `MaleText_loc5`='%s呻吟了起來。', `MaleText_loc7`='%s refunfuña.', `FemaleText_loc1`='%s|1이;가; 신음합니다.', `FemaleText_loc4`='%s呻吟着。', `FemaleText_loc5`='%s呻吟了起來。', `FemaleText_loc7`='%s refunfuña.' WHERE `ID`=5458;
