UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 어서 비참한 목숨을 거둬달라고 간청합니다.', `MaleText_loc4`='%s发出痛苦的呻吟。', `MaleText_loc5`='%s祈求你將他從悲慘中解放。', `MaleText_loc7`='%s ruega para que lo liberen de tanto sufrimiento.', `FemaleText_loc1`='%s|1이;가; 어서 비참한 목숨을 거둬달라고 간청합니다.', `FemaleText_loc4`='%s发出痛苦的呻吟。', `FemaleText_loc5`='%s祈求你將她從悲慘中解放。', `FemaleText_loc7`='%s ruega para que la liberen de tanto sufrimiento.' WHERE `ID`=5460;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기 그냥 서 있으면 안 돼! 어서 가자, 다단가! 이랴!', `FemaleText_loc4`='好吧，不要再靠近了，就站在这儿。快些，达丹加！', `FemaleText_loc5`='好吧，不要再靠近了，就站在這兒。快些，達丹加!', `FemaleText_loc7`='No estamos avanzando nada, simplemente estamos aquí parados. ¡Vamos, Dadanga! ¡Venga!' WHERE `ID`=5461;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='활기차게 걸어, 다단가! 기운 내! 여기서 빠져나가면, 우리에겐 행복한 시간이 다가올 테니까! 어서 가자!', `FemaleText_loc4`='加把劲，达丹加！快一点，小女孩！', `FemaleText_loc5`='加把勁，達丹加!快一點，小女孩!', `FemaleText_loc7`='¡Camina con ganas, Dadanga! ¡Vamos, muchacha! Cuanto más rápido salgamos de aquí, más felices seremos.' WHERE `ID`=5462;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 감히 나의 휴식을 방해하다니!', `MaleText_loc4`='$n，你打扰我休息了！', `MaleText_loc5`='$n，你打擾我休息了!', `MaleText_loc7`='¡$n, has interrumpido mi descanso!' WHERE `ID`=5463;
