UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 감히 이 아쿠에멘타스를 깨우는 것이냐?', `MaleText_loc4`='谁敢唤醒亚奎门塔斯？', `MaleText_loc5`='誰敢喚醒亞奎門塔斯?', `MaleText_loc7`='¿Quién osa despertar a Aquamentas?' WHERE `ID`=5465;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 코도에게서 떨어져. 이 괴물 같은 놈아!', `FemaleText_loc4`='离我的科多兽远些，你这个怪物！', `FemaleText_loc5`='離我的科多獸遠些，你這個怪物!', `FemaleText_loc7`='¡Apártate de mi kodo, monstruo de la naturaleza!' WHERE `ID`=5466;
