UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저렇게 덩치 큰 $n|1은;는; 처음이야... 녀석이 달려든다! 조심해요!', `FemaleText_loc4`='这一定是我所见过的最大的$n……而它正向我们冲过来！', `FemaleText_loc5`='這一定是我所見過的最大的$n...而它正向我們衝過來!', `FemaleText_loc7`='¡Es $gel:la; $n más grande que he visto nunca... y viene directo hacia nosotros!' WHERE `ID`=5468;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='조심해! $n|1이;가; 왔어요!', `FemaleText_loc4`='小心$n！', `FemaleText_loc5`='小心$n!', `FemaleText_loc7`='¡Ten cuidado con $n!' WHERE `ID`=5469;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='약초채집에 대한 지식과 기술이라면 피로드렌 문콜러가 전문입니다. 다르나서스 남서부에 있는 신전 정원으로 가보십시오.', `MaleText_loc4`='草药的收集和与之相关的知识是菲罗迪恩·唤月的专长。去达纳苏斯西南部的神殿花园找他吧。', `MaleText_loc5`='草藥的收集和與之相關的知識是菲羅迪恩·喚月的專長。去達納蘇斯西南部的神殿花園找他吧。', `MaleText_loc7`='La recolección y el conocimiento de las hierbas es una especialidad de Firodren Llamaluna. Búscalo en los Jardines del Templo, en la zona sudoeste de Darnassus.', `FemaleText_loc1`='약초채집에 대한 지식과 기술이라면 피로드렌 문콜러가 전문입니다. 다르나서스 남서부에 있는 신전 정원으로 가보십시오.', `FemaleText_loc4`='草药的收集和与之相关的知识是菲罗迪恩·唤月的专长。去达纳苏斯西南部的神殿花园找他吧。', `FemaleText_loc5`='草藥的收集和與之相關的知識是菲羅迪恩·喚月的專長。去達納蘇斯西南部的神殿花園找他吧。', `FemaleText_loc7`='La recolección y el conocimiento de las hierbas es una especialidad de Firodren Llamaluna. Búscalo en los Jardines del Templo, en la zona sudoeste de Darnassus.' WHERE `ID`=5470;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대는 약초채집가 지망생이시로군요? 그렇다면 신전 정원으로 가서 피로드렌 문콜러를 만나 보십시오. 몇 가지 요령을 가르쳐 줄 겁니다.', `MaleText_loc4`='一个新手采药师？那你该找神殿花园的菲罗迪恩·唤月聊聊。他或许有些专业诀窍要传授给你。', `MaleText_loc5`='一個新手草藥師?那你該找神殿花園的菲羅迪恩·喚月聊聊。他或許有些專業訣竅要傳授給你。', `MaleText_loc7`='¿Acaso somos herboristas en ciernes? Entonces deberás visitar a Firodren Llamaluna, en los Jardines del Templo. Puede enseñarte algunos trucos del oficio.', `FemaleText_loc1`='그대는 약초채집가 지망생이시로군요? 그렇다면 신전 정원으로 가서 피로드렌 문콜러를 만나 보십시오. 몇 가지 요령을 가르쳐 줄 겁니다.', `FemaleText_loc4`='一个新手采药师？那你该找神殿花园的菲罗迪恩·唤月聊聊。他或许有些专业诀窍要传授给你。', `FemaleText_loc5`='一個新手草藥師?那你該找神殿花園的菲羅迪恩·喚月聊聊。他或許有些專業訣竅要傳授給你。', `FemaleText_loc7`='¿Acaso somos herboristas en ciernes? Entonces deberás visitar a Firodren Llamaluna, en los Jardines del Templo. Puede enseñarte algunos trucos del oficio.' WHERE `ID`=5471;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 이 햇볕 따사로운 해안과 푸른 바다를 떠나려고 하는지 모르겠습니다. 여기는 낙원 같은 곳이라고요. 하지만 제 동생 자페타에게는 그런 말 하지 마십쇼. 티리스팔에 온종일 처박혀 있게 돼서 기분이 상당히 안 좋으니까요. 이 비행선은 다행히 오그리마에서 서니까 그 녀석의 불평불만을 들을 일은 없을 겁니다. 하지만 혹시라도 티리스팔에 가면 녀석 성질 돋우는 짓은 안 하시는 게 좋을 걸요.', `MaleText_loc4`='我不知道你为什么想要离开这阳光灿烂的沙滩和蓝色晶莹的水域。这里就象是天堂。但是不要告诉我的哥哥萨匹塔这些，他整天被困在提瑞斯法已经够难过的了。这里的地精飞艇目的地是奥格瑞玛，所以你不用担心得听他发牢骚。但是如果你到了提瑞斯法，要留意我的警告并且不要让他开始抱怨。', `MaleText_loc5`='我不知道你為什麼想要離開這陽光燦爛的沙灘和藍色晶瑩的水域。這裡就像是天堂。但是不要告訴我的哥哥薩匹塔這些，他整天被困在提里斯法已經夠難過的了。這裡的地精飛艇目的地是奧格瑪，所以你不用擔心得聽他發牢騷。但是如果你到了提里斯法，要留意我的警告並且不要讓他開始抱怨。', `MaleText_loc7`='No tengo idea de por qué quieres abandonar estas playas soleadas y aguas cristalinas. Esto es como el paraíso. Pero no se lo digas a mi hermano Zapetta. Ya está suficientemente enfadado por tener que pasar el día entero en Tirisfal. Este zepelín hace parada en Orgrimmar, así que no tendrás que escuchar sus lamentos. Pero si vas pronto a Tirisfal, sigue mi consejo y no dejes que se queje.', `FemaleText_loc1`='왜 이 햇볕 따사로운 해안과 푸른 바다를 떠나려고 하는지 모르겠습니다. 여기는 낙원 같은 곳이라고요. 하지만 제 동생 자페타에게는 그런 말 하지 마십쇼. 티리스팔에 온종일 처박혀 있게 돼서 기분이 상당히 안 좋으니까요. 이 비행선은 다행히 오그리마에서 서니까 그 녀석의 불평불만을 들을 일은 없을 겁니다. 하지만 혹시라도 티리스팔에 가면 녀석 성질 돋우는 짓은 안 하시는 게 좋을 걸요.', `FemaleText_loc4`='我不知道你为什么想要离开这阳光灿烂的沙滩和蓝色晶莹的水域。这里就象是天堂。但是不要告诉我的哥哥萨匹塔这些，他整天被困在提瑞斯法已经够难过的了。这里的地精飞艇目的地是奥格瑞玛，所以你不用担心得听他发牢骚。但是如果你到了提瑞斯法，要留意我的警告并且不要让他开始抱怨。', `FemaleText_loc5`='我不知道你為什麼想要離開這陽光燦爛的沙灘和藍色晶瑩的水域。這裡就像是天堂。但是不要告訴我的哥哥薩匹塔這些，他整天被困在提里斯法已經夠難過的了。這裡的地精飛艇目的地是奧格瑪，所以你不用擔心得聽他發牢騷。但是如果你到了提里斯法，要留意我的警告並且不要讓他開始抱怨。', `FemaleText_loc7`='No tengo idea de por qué quieres abandonar estas playas soleadas y aguas cristalinas. Esto es como el paraíso. Pero no se lo digas a mi hermano Zapetta. Ya está suficientemente enfadado por tener que pasar el día entero en Tirisfal. Este zepelín hace parada en Orgrimmar, así que no tendrás que escuchar sus lamentos. Pero si vas pronto a Tirisfal, sigue mi consejo y no dejes que se queje.' WHERE `ID`=5472;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 $n에게서 타락으로 오염된 흔적이 느껴지는구나. 날 도와 이놈을 물리쳐야 해!', `MaleText_loc4`='我感觉$n散发着堕落的气息。帮我毁掉它！', `MaleText_loc5`='我感覺$n散發著墮落的氣息。幫我毀掉它!', `MaleText_loc7`='Siento cómo la corrupción se cierne sobre $n. ¡Ayúdame a destruirlo!' WHERE `ID`=5473;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 생명체는 사악한 기운으로 고통받고 있네... 우리가 편히 쉬게 해줘야만 해.', `MaleText_loc4`='这个生物受着毒药的折磨……我们必须终止它的痛苦。', `MaleText_loc5`='這個生物受著毒藥的折磨...我們必須終止它的痛苦。', `MaleText_loc7`='Esta criatura padece los efectos de la energía vil... Tenemos que acabar con su sufrimiento.' WHERE `ID`=5474;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 $n의 영혼은 타락으로 미쳐 버렸네!', `MaleText_loc4`='$n已经被堕落力量逼疯了。', `MaleText_loc5`='$n已經被墮落力量逼瘋了。', `MaleText_loc7`='¡$n ha enloquecido al entrar en contacto con el mal!' WHERE `ID`=5475;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자연에서 구한 약초는 그것을 존중하는 마음으로 대할 때 우리의 강력한 동지가 되어 줄 것입니다. 봉우리 중간층에서 연금술 가게를 운영하고 있는 베나를 찾아가서 훈련을 더 받도록 하십시오.', `MaleText_loc4`='好好利用自然界的草药，它会成为你有力的助手的。去本娜的炼金店找她吧，接受更多训练。', `MaleText_loc5`='好好利用自然界的草藥，它會成為你有力的助手的。去貝娜的鍊金店找她吧，接受更多訓練。', `MaleText_loc7`='Las hierbas que hay en la naturaleza pueden convertirse en un poderoso aliado cuando se las usa con respeto. Deberías ir a ver a Bena en su tienda de alquimia en la cuesta para continuar con tu instrucción.', `FemaleText_loc1`='자연에서 구한 약초는 그것을 존중하는 마음으로 대할 때 우리의 강력한 동지가 되어 줄 것입니다. 봉우리 중간층에서 연금술 가게를 운영하고 있는 베나를 찾아가서 훈련을 더 받도록 하십시오.', `FemaleText_loc4`='好好利用自然界的草药，它会成为你有力的助手的。去本娜的炼金店找她吧，接受更多训练。', `FemaleText_loc5`='好好利用自然界的草藥，它會成為你有力的助手的。去貝娜的鍊金店找她吧，接受更多訓練。', `FemaleText_loc7`='Las hierbas que hay en la naturaleza pueden convertirse en un poderoso aliado cuando se las usa con respeto. Deberías ir a ver a Bena en su tienda de alquimia en la cuesta para continuar con tu instrucción.' WHERE `ID`=5476;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='속세의 소유물은 봉우리 하층에 있는 썬더 블러프 은행에서 떨쳐 버리도록 하십시오.', `MaleText_loc4`='你可以到中部高地的底层的雷霆崖银行存放你的财物。', `MaleText_loc5`='你可以到中部高地的底層的雷霆崖銀行存放你的財物。', `MaleText_loc7`='Puedes despojarte de tus bienes más valiosos y dejarlos en el Banco de Cima del Trueno en la pequeña pendiente.', `FemaleText_loc1`='속세의 소유물은 봉우리 하층에 있는 썬더 블러프 은행에서 떨쳐 버리도록 하십시오.', `FemaleText_loc4`='你可以到中部高地的底层的雷霆崖银行存放你的财物。', `FemaleText_loc5`='你可以到中部高地的底層的雷霆崖銀行存放你的財物。', `FemaleText_loc7`='Puedes despojarte de tus bienes más valiosos y dejarlos en el Banco de Cima del Trueno en la pequeña pendiente.' WHERE `ID`=5477;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 것들과 마찬가지로 금속도 자연과 균형을 고려해서 사용해야 합니다. 카른 스톤후프가 봉우리 하층에서 대장간을 하고 있으니 가서 그로부터 지혜를 구하십시오.', `MaleText_loc4`='和其他所有事物一样，金属应该被平衡的使用。卡恩·石蹄在中部高地的底层的池塘边设立了一处铁匠铺。去寻求他的指引吧。', `MaleText_loc5`='和其他所有事物一樣，金屬應該被平衡的使用。卡恩·石蹄在中部高地的底層的池塘邊設立了一處鐵匠鋪。去尋求他的指引吧。', `MaleText_loc7`='Como ocurre con otros elementos, el metal debe usarse en equilibrio con la naturaleza. Karn Pezuña Pétrea tiene un equipo de forja en la pequeña pendiente junto al estanque. Busca su sabio consejo.', `FemaleText_loc1`='다른 것들과 마찬가지로 금속도 자연과 균형을 고려해서 사용해야 합니다. 카른 스톤후프가 봉우리 하층에서 대장간을 하고 있으니 가서 그로부터 지혜를 구하십시오.', `FemaleText_loc4`='和其他所有事物一样，金属应该被平衡的使用。卡恩·石蹄在中部高地的底层的池塘边设立了一处铁匠铺。去寻求他的指引吧。', `FemaleText_loc5`='和其他所有事物一樣，金屬應該被平衡的使用。卡恩·石蹄在中部高地的底層的池塘邊設立了一處鐵匠鋪。去尋求他的指引吧。', `FemaleText_loc7`='Como ocurre con otros elementos, el metal debe usarse en equilibrio con la naturaleza. Karn Pezuña Pétrea tiene un equipo de forja en la pequeña pendiente junto al estanque. Busca su sabio consejo.' WHERE `ID`=5478;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자연에서 사냥한 동물은 한 군데도 버릴 곳이 없습니다. 그러므로 우리는 동물의 혼을 존중해 주어야 합니다. 아스카 미스트러너가 그 방법을 가르쳐줄 수 있습니다. 봉우리 상층에 있는 그녀의 주방을 찾아가 보십시오.', `MaleText_loc4`='你没有浪费那些你必须杀死的动物，因此你赐予了这些动物的灵魂以荣誉。阿丝卡·迷雾行者将会给你演示怎么处理。她在高地上有个厨房。', `MaleText_loc5`='你沒有浪費那些你必須殺死的動物，因此你賜予了這些動物的靈魂以榮譽。阿絲卡·迷霧行者將會給你演示怎麼處理。她在高地上有個廚房。', `MaleText_loc7`='Debes honrar el espíritu de los animales que sacrificas aprovechando su carne. Aska Correbruma te enseñará cómo. Tiene una cocina en la cuesta.', `FemaleText_loc1`='자연에서 사냥한 동물은 한 군데도 버릴 곳이 없습니다. 그러므로 우리는 동물의 혼을 존중해 주어야 합니다. 아스카 미스트러너가 그 방법을 가르쳐줄 수 있습니다. 봉우리 상층에 있는 그녀의 주방을 찾아가 보십시오.', `FemaleText_loc4`='你没有浪费那些你必须杀死的动物，因此你赐予了这些动物的灵魂以荣誉。阿丝卡·迷雾行者将会给你演示怎么处理。她在高地上有个厨房。', `FemaleText_loc5`='你沒有浪費那些你必須殺死的動物，因此你賜予了這些動物的靈魂以榮譽。阿絲卡·迷霧行者將會給你演示怎麼處理。她在高地上有個廚房。', `FemaleText_loc7`='Debes honrar el espíritu de los animales que sacrificas aprovechando su carne. Aska Correbruma te enseñará cómo. Tiene una cocina en la cuesta.' WHERE `ID`=5479;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명예로운 자여, 장로의 봉우리에 있는 장로의 전당에서 투락 룬토템과 다른 드루이드들이 당신을 기다리고 있습니다.', `MaleText_loc4`='你好尊贵的客人。图拉克·符文图腾和其余的德鲁伊正在长者高地上的长者大厅等你。', `MaleText_loc5`='你好尊貴的客人。圖拉克·符文圖騰和其餘的德魯伊正在長者高地上的長者大廳等你。', `MaleText_loc7`='Saludos, honorable $gamigo:amiga;. Turak Tótem de Runa y los demás druidas te han estado esperando en Sala de los Ancestros.', `FemaleText_loc1`='명예로운 자여, 장로의 봉우리에 있는 장로의 전당에서 투락 룬토템과 다른 드루이드들이 당신을 기다리고 있습니다.', `FemaleText_loc4`='你好尊贵的客人。图拉克·符文图腾和其余的德鲁伊正在长者高地上的长者大厅等你。', `FemaleText_loc5`='你好尊貴的客人。圖拉克·符文圖騰和其餘的德魯伊正在長者高地上的長者大廳等你。', `FemaleText_loc7`='Saludos, honorable $gamigo:amiga;. Turak Tótem de Runa y los demás druidas te han estado esperando en Sala de los Ancestros.' WHERE `ID`=5480;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법부여 기술은 자연의 중심에 있는 파괴와 창조의 순환을 보여 주지요. 봉우리 중간층, 돈스트라이더의 마법부여점에 있는 테그가 가르쳐 줄 겁니다.', `MaleText_loc4`='附魔体现了毁灭和新生的循环，这正是自然界的基本准则。晨行者附魔师将为你展示这一切。', `MaleText_loc5`='附魔這項專業技能展現了製造和毀滅的輪迴，這正是自然界的基本準則。晨行者附魔商店的泰戈將為你展示這一切。', `MaleText_loc7`='La profesión del encantador desvela el ciclo de destrucción y creación que reside en el corazón de la naturaleza. Teg, de los encantadores Caminalba, que habitan en la cuesta, te lo enseñará.', `FemaleText_loc1`='마법부여 기술은 자연의 중심에 있는 파괴와 창조의 순환을 보여 주지요. 봉우리 중간층, 돈스트라이더의 마법부여점에 있는 테그가 가르쳐 줄 겁니다.', `FemaleText_loc4`='附魔体现了毁灭和新生的循环，这正是自然界的基本准则。晨行者附魔师将为你展示这一切。', `FemaleText_loc5`='附魔這項專業技能展現了製造和毀滅的輪迴，這正是自然界的基本準則。晨行者附魔商店的泰戈將為你展示這一切。', `FemaleText_loc7`='La profesión del encantador desvela el ciclo de destrucción y creación que reside en el corazón de la naturaleza. Teg, de los encantadores Caminalba, que habitan en la cuesta, te lo enseñará.' WHERE `ID`=5481;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='삶이란 투쟁이고 죽지 않을 정도의 상처는 오히려 몸을 강하게 만든다는 말이 언제나 옳은 것은 아닙니다. 상처가 쉽게 아물지 않을 때도 있는 법이지요. 그래서 붕대가 필요한 것입니다. 정기의 봉우리에 있는 판드 스톤바인더가 응급치료를 가르쳐줄 수 있습니다.', `MaleText_loc4`='生活是一场竞争，“大难不死必有后福”这句俗语并不是始终正确的。有时伤口愈合得很慢，这就是我们需要绑带的原因。灵魂高地的潘德·缚石能教你急救的技能。', `MaleText_loc5`='生活是一場競爭，「大難不死必有後福」這句俗語並不是始終正確的。有時傷口癒合得很慢，這就是我們需要綁帶的原因。靈魂高地的潘德·縛石能教你急救的技能。', `MaleText_loc7`='La vida es una lucha y decir que lo que no te mata te hace más fuerte no siempre es verdad. A veces, las heridas actúan lentamente, lo que explica que usemos vendas. Pand Amarrapiedra, del Alto de los Espíritus, puede enseñarte el arte de los primeros auxilios.', `FemaleText_loc1`='삶이란 투쟁이고 죽지 않을 정도의 상처는 오히려 몸을 강하게 만든다는 말이 언제나 옳은 것은 아닙니다. 상처가 쉽게 아물지 않을 때도 있는 법이지요. 그래서 붕대가 필요한 것입니다. 정기의 봉우리에 있는 판드 스톤바인더가 응급치료를 가르쳐줄 수 있습니다.', `FemaleText_loc4`='生活是一场竞争，“大难不死必有后福”这句俗语并不是始终正确的。有时伤口愈合得很慢，这就是我们需要绑带的原因。灵魂高地的潘德·缚石能教你急救的技能。', `FemaleText_loc5`='生活是一場競爭，「大難不死必有後福」這句俗語並不是始終正確的。有時傷口癒合得很慢，這就是我們需要綁帶的原因。靈魂高地的潘德·縛石能教你急救的技能。', `FemaleText_loc7`='La vida es una lucha y decir que lo que no te mata te hace más fuerte no siempre es verdad. A veces, las heridas actúan lentamente, lo que explica que usemos vendas. Pand Amarrapiedra, del Alto de los Espíritus, puede enseñarte el arte de los primeros auxilios.' WHERE `ID`=5482;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='봉우리 상층, 산꼭대기 낚시용품점에 있는 카 미스트러너를 찾아가 보십시오. 요리에 쓸 물고기를 낚으면서 내면의 평화와 고요함을 찾는 법을 가르쳐줄 겁니다.', `MaleText_loc4`='山顶渔具店的卡尔·迷雾行者将为你指明如何实现内心平静的同时还能通过钓鱼为自己准备好下一餐。', `MaleText_loc5`='山頂漁具店的卡爾·迷霧行者將為你指明如何實現內心平靜的同時還能通過釣魚為自己準備好下一餐。', `MaleText_loc7`='Kah Correbruma, de Anzuelos y Aparejos La Cumbre, en la gran pendiente, te enseñará el camino para encontrar la paz interior y la serenidad mientras pescas tu próximo alimento.', `FemaleText_loc1`='봉우리 상층, 산꼭대기 낚시용품점에 있는 카 미스트러너를 찾아가 보십시오. 요리에 쓸 물고기를 낚으면서 내면의 평화와 고요함을 찾는 법을 가르쳐줄 겁니다.', `FemaleText_loc4`='山顶渔具店的卡尔·迷雾行者将为你指明如何实现内心平静的同时还能通过钓鱼为自己准备好下一餐。', `FemaleText_loc5`='山頂漁具店的卡爾·迷霧行者將為你指明如何實現內心平靜的同時還能通過釣魚為自己準備好下一餐。', `FemaleText_loc7`='Kah Correbruma, de Anzuelos y Aparejos La Cumbre, en la gran pendiente, te enseñará el camino para encontrar la paz interior y la serenidad mientras pescas tu próximo alimento.' WHERE `ID`=5483;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동족과의 우정은 아주 강력한 힘이 될 수 있습니다. 이런 일은 크룸이 도와 줄 수 있지요. 봉우리 하층, 승강기 옆에 있는 썬더 블러프 길드 사무소를 찾아가 보십시오.', `MaleText_loc4`='一个志趣相投的团体可以成为一支非常强大的力量。克拉姆会帮助你们达到这个目的。你可以在雷霆崖升降梯旁边中部高地的底层的公民信息中心找到他。', `MaleText_loc5`='一個志趣相投的團體可以成為一支非常強大的力量。克拉姆會幫助你們達到這個目的。你可以在雷霆崖升降梯旁邊中部高地的底層的公民資訊中心找到他。', `MaleText_loc7`='Una hermandad de espíritus similares puede constituir una fuerza poderosa. Krumn te ayudará a conseguirlo. Lo encontrarás en el centro de Información al ciudadano, en la pequeña pendiente que está junto a los ascensores.', `FemaleText_loc1`='동족과의 우정은 아주 강력한 힘이 될 수 있습니다. 이런 일은 크룸이 도와 줄 수 있지요. 봉우리 하층, 승강기 옆에 있는 썬더 블러프 길드 사무소를 찾아가 보십시오.', `FemaleText_loc4`='一个志趣相投的团体可以成为一支非常强大的力量。克拉姆会帮助你们达到这个目的。你可以在雷霆崖升降梯旁边中部高地的底层的公民信息中心找到他。', `FemaleText_loc5`='一個志趣相投的團體可以成為一支非常強大的力量。克拉姆會幫助你們達到這個目的。你可以在雷霆崖升降梯旁邊中部高地的底層的公民資訊中心找到他。', `FemaleText_loc7`='Una hermandad de espíritus similares puede constituir una fuerza poderosa. Krumn te ayudará a conseguirlo. Lo encontrarás en el centro de Información al ciudadano, en la pequeña pendiente que está junto a los ascensores.' WHERE `ID`=5484;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자연은 우리가 필요로 하는 모든 것을 제공합니다. 봉우리 중간층 조화의 약초상점에 있는 코민 윈터후프를 찾아가 보십시오.', `MaleText_loc4`='自然会提供我们所需的一切。跟中部高地中层克米恩·冰蹄谈谈草药学吧。', `MaleText_loc5`='自然會提供我們所需的一切。跟中部高地中層克米恩·冬蹄談談草藥學吧。', `MaleText_loc7`='La naturaleza nos da todo lo que necesitamos. Habla con Komin Pezuña Invernal de la Herboristería Holística, que está en la cuesta.', `FemaleText_loc1`='자연은 우리가 필요로 하는 모든 것을 제공합니다. 봉우리 중간층 조화의 약초상점에 있는 코민 윈터후프를 찾아가 보십시오.', `FemaleText_loc4`='自然会提供我们所需的一切。跟中部高地中层克米恩·冰蹄谈谈草药学吧。', `FemaleText_loc5`='自然會提供我們所需的一切。跟中部高地中層克米恩·冬蹄談談草藥學吧。', `FemaleText_loc7`='La naturaleza nos da todo lo que necesitamos. Habla con Komin Pezuña Invernal de la Herboristería Holística, que está en la cuesta.' WHERE `ID`=5485;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모든 동물은 사냥꾼의 친구지요. 수렵의 봉우리 꼭대기에 있는 사냥꾼의 전당으로 가 보십시오.', `MaleText_loc4`='动物的朋友就是我的朋友。你要找的猎人大厅就在猎人高地的顶部。', `MaleText_loc5`='動物的朋友就是我的朋友。你要找的獵人大廳就在獵人高地的頂部。', `MaleText_loc7`='Todo aquel que sea amigo de los animales es amigo mío. El Recinto de los Cazadores es lo que buscas. Está en el Alto de los Cazadores.', `FemaleText_loc1`='모든 동물은 사냥꾼의 친구지요. 수렵의 봉우리 꼭대기에 있는 사냥꾼의 전당으로 가 보십시오.', `FemaleText_loc4`='动物的朋友就是我的朋友。你要找的猎人大厅就在猎人高地的顶部。', `FemaleText_loc5`='動物的朋友就是我的朋友。你要找的獵人大廳就在獵人高地的頂部。', `FemaleText_loc7`='Todo aquel que sea amigo de los animales es amigo mío. El Recinto de los Cazadores es lo que buscas. Está en el Alto de los Cazadores.' WHERE `ID`=5486;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적의 가죽을 이용해 자신을 몸을 보호할 수 있다니... 가죽세공술을 익히고 싶으시면 봉우리 중간층에 있는 썬더 블러프 갑옷 상점에서 우나를 찾아보십시오.', `MaleText_loc4`='利用敌人的兽皮来保护自己这一想法运用了拟态学的知识。要进一步提高制皮技能，你得去雷霆崖防具店找库纳。', `MaleText_loc5`='利用敵人的獸皮來保護自己這一想法運用了擬態學的知識。要進一步提高製皮技能，你得去雷霆崖防具店找猶納。', `MaleText_loc7`='La idea del pellejo de tu enemigo brindándote protección presenta cierta simetría. Para perfeccionar tus habilidades en peletería, busca a Una en los Armeros de Cima del Trueno, en la cuesta.', `FemaleText_loc1`='적의 가죽을 이용해 자신을 몸을 보호할 수 있다니... 가죽세공술을 익히고 싶으시면 봉우리 중간층에 있는 썬더 블러프 갑옷 상점에서 우나를 찾아보십시오.', `FemaleText_loc4`='利用敌人的兽皮来保护自己这一想法运用了拟态学的知识。要进一步提高制皮技能，你得去雷霆崖防具店找库纳。', `FemaleText_loc5`='利用敵人的獸皮來保護自己這一想法運用了擬態學的知識。要進一步提高製皮技能，你得去雷霆崖防具店找猶納。', `FemaleText_loc7`='La idea del pellejo de tu enemigo brindándote protección presenta cierta simetría. Para perfeccionar tus habilidades en peletería, busca a Una en los Armeros de Cima del Trueno, en la cuesta.' WHERE `ID`=5487;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불쌍한 언데드들의 운명을 생각하면 아주 슬퍼지지요. 정기의 봉우리 밑에 있는 예언의 웅덩이에서 명상에 잠겨 있는 대마법사 심을 찾아가 보십시오.', `MaleText_loc4`='想到这些可怜的亡灵灵魂的遭遇，我感到非常悲伤。你可以去灵魂高地之下的预见之池附近找大法师山姆。', `MaleText_loc5`='想到這些可憐的亡靈靈魂的遭遇，我感到非常悲傷。你可以去靈魂高地之下的預見之池附近找大法師山姆。', `MaleText_loc7`='Da tristeza pensar en lo que ha ocurrido a esas pobres almas no-muertas. Encontrarás al archimago Shymm meditando cerca de las Pozas de las Visiones, bajo el Alto de los Espíritus.', `FemaleText_loc1`='불쌍한 언데드들의 운명을 생각하면 아주 슬퍼지지요. 정기의 봉우리 밑에 있는 예언의 웅덩이에서 명상에 잠겨 있는 대마법사 심을 찾아가 보십시오.', `FemaleText_loc4`='想到这些可怜的亡灵灵魂的遭遇，我感到非常悲伤。你可以去灵魂高地之下的预见之池附近找大法师山姆。', `FemaleText_loc5`='想到這些可憐的亡靈靈魂的遭遇，我感到非常悲傷。你可以去靈魂高地之下的預見之池附近找大法師山姆。', `FemaleText_loc7`='Da tristeza pensar en lo que ha ocurrido a esas pobres almas no-muertas. Encontrarás al archimago Shymm meditando cerca de las Pozas de las Visiones, bajo el Alto de los Espíritus.' WHERE `ID`=5488;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대지모신은 여러 가지 비밀을 간직하고 있는데, 브렉 스톤후프의 도움을 얻으면 일부라도 발견할 수 있을 것입니다. 봉우리 하층에 있는 스톤후프 지질연구소로 가 보십시오.', `MaleText_loc4`='大地之母有许多秘密，布瑞克·石蹄能帮助你发现一些秘密。你会在 石蹄地质学会的中部高地的底层那找到他的。', `MaleText_loc5`='大地之母有許多秘密，布瑞克·石蹄能幫助你發現一些秘密。你會在 石蹄地質學會的中部高地的底層那找到他的。', `MaleText_loc7`='La Madre Tierra guarda muchos secretos y Brek Pezuña Pétrea puede ayudarte a descubrir algunos de ellos. Lo encontrarás en la pequeña pendiente, en la Geología Pezuña Pétrea.', `FemaleText_loc1`='대지모신은 여러 가지 비밀을 간직하고 있는데, 브렉 스톤후프의 도움을 얻으면 일부라도 발견할 수 있을 것입니다. 봉우리 하층에 있는 스톤후프 지질연구소로 가 보십시오.', `FemaleText_loc4`='大地之母有许多秘密，布瑞克·石蹄能帮助你发现一些秘密。你会在 石蹄地质学会的中部高地的底层那找到他的。', `FemaleText_loc5`='大地之母有許多秘密，布瑞克·石蹄能幫助你發現一些秘密。你會在 石蹄地質學會的中部高地的底層那找到他的。', `FemaleText_loc7`='La Madre Tierra guarda muchos secretos y Brek Pezuña Pétrea puede ayudarte a descubrir algunos de ellos. Lo encontrarás en la pequeña pendiente, en la Geología Pezuña Pétrea.' WHERE `ID`=5489;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언데드들은 종족이 겪고 있는 비극적인 상황에도 불구하고 여기까지 와서 우리를 돕고 있습니다. 우리도 그만큼 그들에게 도움이 되었으면 좋겠군요. 정기의 봉우리 밑에 있는 예언의 웅덩이 근처에서 신부 콥을 찾아보시기 바랍니다.', `MaleText_loc4`='虽然亡灵受到重创，但是他们还是赶来帮助我们。我只希望我们也能对他们有所帮助。去灵魂高地下面的预见之池附近寻找柯布神父。', `MaleText_loc5`='雖然亡靈受到重創，但是他們還是趕來幫助我們。我只希望我們也能對他們有所幫助。去靈魂高地下麵的預見之池附近尋找柯布神父。', `MaleText_loc7`='A pesar de su tragedia, los no-muertos han venido hasta aquí para ayudarnos. Solo espero poder ayudarles tanto como lo hacen ellos con nosotros. Busca al padre Cobb cerca de las Pozas de las Visiones, bajo el Alto de los Espíritus.', `FemaleText_loc1`='언데드들은 종족이 겪고 있는 비극적인 상황에도 불구하고 여기까지 와서 우리를 돕고 있습니다. 우리도 그만큼 그들에게 도움이 되었으면 좋겠군요. 정기의 봉우리 밑에 있는 예언의 웅덩이 근처에서 신부 콥을 찾아보시기 바랍니다.', `FemaleText_loc4`='虽然亡灵受到重创，但是他们还是赶来帮助我们。我只希望我们也能对他们有所帮助。去灵魂高地下面的预见之池附近寻找柯布神父。', `FemaleText_loc5`='雖然亡靈受到重創，但是他們還是趕來幫助我們。我只希望我們也能對他們有所幫助。去靈魂高地下麵的預見之池附近尋找柯布神父。', `FemaleText_loc7`='A pesar de su tragedia, los no-muertos han venido hasta aquí para ayudarnos. Solo espero poder ayudarles tanto como lo hacen ellos con nosotros. Busca al padre Cobb cerca de las Pozas de las Visiones, bajo el Alto de los Espíritus.' WHERE `ID`=5490;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대지모신께서 당신의 부름에 응하실 것입니다. 정기의 봉우리에 있는 정기의 전당으로 가 보십시오.', `MaleText_loc4`='大地之母发出召唤，你得做出应答。你可以在灵魂高地找到灵魂大厅。', `MaleText_loc5`='大地之母發出召喚，你得做出應答。你可以在靈魂高地找到靈魂大廳。', `MaleText_loc7`='La Madre Tierra te llama y tú respondes. Encontrarás la Sala de los Espíritus en el Alto de los Espíritus.', `FemaleText_loc1`='대지모신께서 당신의 부름에 응하실 것입니다. 정기의 봉우리에 있는 정기의 전당으로 가 보십시오.', `FemaleText_loc4`='大地之母发出召唤，你得做出应答。你可以在灵魂高地找到灵魂大厅。', `FemaleText_loc5`='大地之母發出召喚，你得做出應答。你可以在靈魂高地找到靈魂大廳。', `FemaleText_loc7`='La Madre Tierra te llama y tú respondes. Encontrarás la Sala de los Espíritus en el Alto de los Espíritus.' WHERE `ID`=5491;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='금속 조각을 잘만 활용하면 낭비가 적어지고 대지모신에게 더욱 가까워질 수 있습니다. 무란타가 그 비법을 알려 줄 겁니다. 봉우리 중간층에 있는 썬더 블러프 갑옷 상점 앞에서 찾아보시기 바랍니다.', `MaleText_loc4`='充分利用每块碎片会让我们更加节约并会拉近我们和大地母亲的距离。莫兰塔会教给你方法。到中部高地上的雷霆崖兵器库外面可以找到她。', `MaleText_loc5`='充分利用每塊碎塊會讓我們更加節約並會拉近我們和大地之母的距離。莫蘭塔會教給你方法。到中部高地上的雷霆崖兵器庫外面可以找到她。', `MaleText_loc7`='Cada trozo de tierra que usamos nos hace menos derrochadores, acercándonos a la Madre Tierra. Mooranta te enseñará cómo hacerlo. Búscala en la parte exterior de los Armeros de Cima del Trueno, en la cuesta.', `FemaleText_loc1`='금속 조각을 잘만 활용하면 낭비가 적어지고 대지모신에게 더욱 가까워질 수 있습니다. 무란타가 그 비법을 알려 줄 겁니다. 봉우리 중간층에 있는 썬더 블러프 갑옷 상점 앞에서 찾아보시기 바랍니다.', `FemaleText_loc4`='充分利用每块碎片会让我们更加节约并会拉近我们和大地母亲的距离。莫兰塔会教给你方法。到中部高地上的雷霆崖兵器库外面可以找到她。', `FemaleText_loc5`='充分利用每塊碎塊會讓我們更加節約並會拉近我們和大地之母的距離。莫蘭塔會教給你方法。到中部高地上的雷霆崖兵器庫外面可以找到她。', `FemaleText_loc7`='Cada trozo de tierra que usamos nos hace menos derrochadores, acercándonos a la Madre Tierra. Mooranta te enseñará cómo hacerlo. Búscala en la parte exterior de los Armeros de Cima del Trueno, en la cuesta.' WHERE `ID`=5492;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자연과 조화를 이루며 자신만의 생존 기술만으로 살아남는 것... 이것이 바로 대지모신의 뜻입니다. 수렵의 봉우리에서 야영 전문가 베일을 찾아가 보십시오.', `MaleText_loc4`='你，与自然和谐相处，而只有靠你的技能才能生存。这就是大地母亲想要的方式。你会在猎人高地找到拜尔的。', `MaleText_loc5`='你，與自然和諧相處，而只有靠你的技能才能生存。這就是大地之母想要的方式。你會在獵人高地找到拜爾的。', `MaleText_loc7`='Tú, en armonía con la naturaleza y provisto solo de tus habilidades de supervivencia. Así es como lo había previsto la Madre Tierra. Busca a Fardo, en el Alto de los Cazadores.', `FemaleText_loc1`='자연과 조화를 이루며 자신만의 생존 기술만으로 살아남는 것... 이것이 바로 대지모신의 뜻입니다. 수렵의 봉우리에서 야영 전문가 베일을 찾아가 보십시오.', `FemaleText_loc4`='你，与自然和谐相处，而只有靠你的技能才能生存。这就是大地母亲想要的方式。你会在猎人高地找到拜尔的。', `FemaleText_loc5`='你，與自然和諧相處，而只有靠你的技能才能生存。這就是大地之母想要的方式。你會在獵人高地找到拜爾的。', `FemaleText_loc7`='Tú, en armonía con la naturaleza y provisto solo de tus habilidades de supervivencia. Así es como lo había previsto la Madre Tierra. Busca a Fardo, en el Alto de los Cazadores.' WHERE `ID`=5493;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부족에게 옷을 제공하는 것은 다른 어떤 일보다도 중요하죠. 썬더 블러프 갑옷 상점에서 테파를 찾아보십시오. 바느질에는 선천적인 소질이 있지요.', `MaleText_loc4`='给部落做衣服与其余的工作同样重要。你该到雷霆崖防具店里面寻找坦帕。她对针线活有自己的天赋。', `MaleText_loc5`='給部族做衣服與其餘的工作同樣重要。你該到雷霆崖防具店裡面尋找坦帕。她對針線活有自己的天賦。', `MaleText_loc7`='Vestir a la tribu es una tarea tan importante como otra cualquiera. Debes buscar a Tepa en el interior de los Armeros de Cima del Trueno. Ella tiene un don especial para la sastrería.', `FemaleText_loc1`='부족에게 옷을 제공하는 것은 다른 어떤 일보다도 중요하죠. 썬더 블러프 갑옷 상점에서 테파를 찾아보십시오. 바느질에는 선천적인 소질이 있지요.', `FemaleText_loc4`='给部落做衣服与其余的工作同样重要。你该到雷霆崖防具店里面寻找坦帕。她对针线活有自己的天赋。', `FemaleText_loc5`='給部族做衣服與其餘的工作同樣重要。你該到雷霆崖防具店裡面尋找坦帕。她對針線活有自己的天賦。', `FemaleText_loc7`='Vestir a la tribu es una tarea tan importante como otra cualquiera. Debes buscar a Tepa en el interior de los Armeros de Cima del Trueno. Ella tiene un don especial para la sastrería.' WHERE `ID`=5494;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 노련한 사냥꾼이 되려는 분이시군요! 사냥감을 쫓는 것은 삶의 끝없는 놀이입니다. 해답을 얻고 싶으시면 수렵의 봉우리에 있는 드레일을 찾아보십시오.', `MaleText_loc4`='啊，猎人的真正标志！在永无止境的生命游戏中追踪猎物。去猎人高地寻找德拉伊吧。', `MaleText_loc5`='啊，獵人的真正標誌!在永無止境的生命遊戲中追蹤獵物。去獵人高地尋找德拉伊吧。', `MaleText_loc7`='¡Ah, esa es la verdadera marca distintiva del cazador! Acechar a la presa en el interminable juego de la vida. Busca a Drayl en el Alto de los Cazadores para obtener respuesta a tus preguntas.', `FemaleText_loc1`='아, 노련한 사냥꾼이 되려는 분이시군요! 사냥감을 쫓는 것은 삶의 끝없는 놀이입니다. 해답을 얻고 싶으시면 수렵의 봉우리에 있는 드레일을 찾아보십시오.', `FemaleText_loc4`='啊，猎人的真正标志！在永无止境的生命游戏中追踪猎物。去猎人高地寻找德拉伊吧。', `FemaleText_loc5`='啊，獵人的真正標誌!在永無止境的生命遊戲中追蹤獵物。去獵人高地尋找德拉伊吧。', `FemaleText_loc7`='¡Ah, la verdadera marca distintiva del cazador! Acechar a la presa en el interminable juego de la vida. Busca a Drayl en el Alto de los Cazadores para obtener respuesta a tus preguntas.' WHERE `ID`=5495;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강인한 신체와 영혼이 조화를 이뤘을 때 최강의 전사로 다시 태어나게 되는 것입니다! 사냥꾼의 전당에서 사크 레이지토템을 찾아가 전사로서의 당신의 새로운 운명을 발견하십시오.', `MaleText_loc4`='强壮的身体和精神。没有比这更强大的组合了！去猎人大厅跟萨尔克·暴怒图腾找寻自己的命运吧。', `MaleText_loc5`='強壯的身體和精神。沒有比這更強大的組合了!去獵人大廳跟薩爾克·狂暴圖騰找尋自己的命運吧。', `MaleText_loc7`='Fuerte de cuerpo y mente. ¡No puede haber una combinación más poderosa! Encuentra tu destino con Sark Tótem de Ira, en el Recinto de los Cazadores.', `FemaleText_loc1`='강인한 신체와 영혼이 조화를 이뤘을 때 최강의 전사로 다시 태어나게 되는 것입니다! 사냥꾼의 전당에서 사크 레이지토템을 찾아가 전사로서의 당신의 새로운 운명을 발견하십시오.', `FemaleText_loc4`='强壮的身体和精神。没有比这更强大的组合了！去猎人大厅跟萨尔克·暴怒图腾找寻自己的命运吧。', `FemaleText_loc5`='強壯的身體和精神。沒有比這更強大的組合了!去獵人大廳跟薩爾克·狂暴圖騰找尋自己的命運吧。', `FemaleText_loc7`='Fuerte de cuerpo y mente. ¡No puede haber una combinación más poderosa! Encuentra tu destino con Sark Tótem de Ira, en el Recinto de los Cazadores.' WHERE `ID`=5496;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거대한 새를 타고 하늘을 날아오르는 건 참으로 멋진 일이지요. 와이번 횃대 꼭대기에서 탈을 찾으십시오. 당신이 가고자 하는 곳으로 보내 줄 겁니다.', `MaleText_loc4`='啊，和天空中的巨鸟一同翱翔。去双足飞龙巢穴顶端找塔尔吧。他会指引你完成你的梦想的。', `MaleText_loc5`='啊，和天空中的巨鳥一同翱翔。去雙足飛龍棲息處頂端找塔爾吧。他會指引你完成你的夢想的。', `MaleText_loc7`='Ah, qué daría por volar con las grandes aves del cielo. Busca a Tal, en la cima de la Alcándara de los jinetes del viento. Te guiará en tu camino.', `FemaleText_loc1`='거대한 새를 타고 하늘을 날아오르는 건 참으로 멋진 일이지요. 와이번 횃대 꼭대기에서 탈을 찾으십시오. 당신이 가고자 하는 곳으로 보내 줄 겁니다.', `FemaleText_loc4`='啊，和天空中的巨鸟一同翱翔。去双足飞龙巢穴顶端找塔尔吧。他会指引你完成你的梦想的。', `FemaleText_loc5`='啊，和天空中的巨鳥一同翱翔。去雙足飛龍棲息處頂端找塔爾吧。他會指引你完成你的夢想的。', `FemaleText_loc7`='Ah, qué daría por volar con las grandes aves del cielo. Busca a Tal, en la cima de la Alcándara de los jinetes del viento. Te guiará en tu camino.' WHERE `ID`=5497;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='봉우리 하층, 썬더 블러프 은행 바로 남쪽에 있는 건물에서 여관주인 팔라를 찾아보십시오.', `MaleText_loc4`='去中部高地的底层的雷霆崖银行以南的建筑物中可以找到旅店老板帕拉。', `MaleText_loc5`='去中部高地的底層的雷霆崖銀行以南的建築物中可以找到旅店老闆帕拉。', `MaleText_loc7`='Busca a la tabernera Pala en el edificio que hay al sur del Banco de Cima del Trueno, en la pequeña pendiente.', `FemaleText_loc1`='봉우리 하층, 썬더 블러프 은행 바로 남쪽에 있는 건물에서 여관주인 팔라를 찾아보십시오.', `FemaleText_loc4`='去中部高地的底层的雷霆崖银行以南的建筑物中可以找到旅店老板帕拉。', `FemaleText_loc5`='去中部高地的底層的雷霆崖銀行以南的建築物中可以找到旅店老闆帕拉。', `FemaleText_loc7`='Busca a la tabernera Pala en el edificio que hay al sur del Banco de Cima del Trueno, en la pequeña pendiente.' WHERE `ID`=5498;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여관주인 팔라가 몸과 마음, 그리고 당신의 영혼이 편히 쉴 수 있도록 해 줄 거예요. 봉우리 하층에 있는 은행 바로 남쪽에 여관이 있습니다.', `MaleText_loc4`='旅店老板帕拉能帮助你得到身心的休息。他就在中部高地的底层的雷霆崖银行以南的建筑物中。', `MaleText_loc5`='旅店老闆帕拉能幫助你得到身心的休息。他就在中部高地的底層的雷霆崖銀行以南的建築物中。', `MaleText_loc7`='La tabernera Pala te ayudará a descansar el cuerpo y el espíritu. Busca a la tabernera Pala en el edificio que hay al sur del Banco de Cima del Trueno, en la pequeña pendiente.', `FemaleText_loc1`='여관주인 팔라가 몸과 마음, 그리고 당신의 영혼이 편히 쉴 수 있도록 해 줄 거예요. 봉우리 하층에 있는 은행 바로 남쪽에 여관이 있습니다.', `FemaleText_loc4`='旅店老板帕拉能帮助你得到身心的休息。他就在中部高地的底层的雷霆崖银行以南的建筑物中。', `FemaleText_loc5`='旅店老闆帕拉能幫助你得到身心的休息。他就在中部高地的底層的雷霆崖銀行以南的建築物中。', `FemaleText_loc7`='La tabernera Pala te ayudará a descansar el cuerpo y el espíritu. Busca a la tabernera Pala en el edificio que hay al sur del Banco de Cima del Trueno, en la pequeña pendiente.' WHERE `ID`=5499;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우체통은 봉우리 하층에 있는 썬더 블러프 은행 바로 밖에서 찾을 수 있습니다.', `MaleText_loc4`='你能在中部高地的底层的雷霆崖银行外面找到一个邮筒。', `MaleText_loc5`='你能在中部高地的底層的雷霆崖銀行外面找到一個郵箱。', `MaleText_loc7`='Puedes encontrar un buzón justo fuera del Banco de Cima del Trueno, en la pequeña pendiente.', `FemaleText_loc1`='우체통은 봉우리 하층에 있는 썬더 블러프 은행 바로 밖에서 찾을 수 있습니다.', `FemaleText_loc4`='你能在中部高地的底层的雷霆崖银行外面找到一个邮筒。', `FemaleText_loc5`='你能在中部高地的底層的雷霆崖銀行外面找到一個郵箱。', `FemaleText_loc7`='Puedes encontrar un buzón justo fuera del Banco de Cima del Trueno, en la pequeña pendiente.' WHERE `ID`=5500;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조금 전 새로운 우편물이 배달되는 것을 본 것 같습니다. 우체통은 봉우리 하층에 있는 썬더 블러프 은행 바로 밖에서 찾을 수 있습니다.', `MaleText_loc4`='我记得不久之前我有新邮件寄出。你可以在中部高地的底层雷霆崖银行外找到邮箱。', `MaleText_loc5`='我記得不久之前我有新郵件寄出。你可以在中部高地的底層雷霆崖銀行外找到郵箱。', `MaleText_loc7`='Creo que se ha enviado un nuevo cargamento de correo hace no mucho. Encontrarás el buzón en el exterior del Banco de Cima del Trueno, en la pequeña pendiente.', `FemaleText_loc1`='조금 전 새로운 우편물이 배달되는 것을 본 것 같습니다. 우체통은 봉우리 하층에 있는 썬더 블러프 은행 바로 밖에서 찾을 수 있습니다.', `FemaleText_loc4`='我记得不久之前我有新邮件寄出。你可以在中部高地的底层雷霆崖银行外找到邮箱。', `FemaleText_loc5`='我記得不久之前我有新郵件寄出。你可以在中部高地的底層雷霆崖銀行外找到郵箱。', `FemaleText_loc7`='Creo que se ha enviado un nuevo cargamento de correo hace no mucho. Encontrarás el buzón en el exterior del Banco de Cima del Trueno, en la pequeña pendiente.' WHERE `ID`=5501;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='썬더 블러프 봉우리 하층에 있습니다. 은행 가까이에 있으니 한번 찾아보십시오.', `MaleText_loc4`='你可以在雷霆崖的最低处寻找，就在离银行不远的地方。', `MaleText_loc5`='它就在雷霆崖下方，在銀行附近找一找吧，離這兒不遠。', `MaleText_loc7`='Está en la zona baja de Cima del Trueno. Busca junto al banco. No está lejos de aquí.', `FemaleText_loc1`='썬더 블러프 봉우리 하층에 있습니다. 은행 가까이에 있으니 한번 찾아보십시오.', `FemaleText_loc4`='你可以在雷霆崖的最低处寻找，就在离银行不远的地方。', `FemaleText_loc5`='它就在雷霆崖下方，在銀行附近找一找吧，離這兒不遠。', `FemaleText_loc7`='Está en la zona baja de Cima del Trueno. Busca junto al banco. No está lejos de aquí.' WHERE `ID`=5502;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경매장은 썬더 블러프 중앙에서 찾을 수 있습니다. 와이번 조련사의 탑 맨 아래층을 찾아보십시오. 선조님의 영혼이 당신을 보살피기를.', `MaleText_loc4`='你可以在雷霆崖的中央高地找到拍卖行。在双足飞龙飞行点下方附近找找吧，愿你的先祖保佑你。', `MaleText_loc5`='拍賣場位於雷霆崖的中央尖塔，在雙足飛龍塔下方附近找找吧。願你的祖先保佑你。', `MaleText_loc7`='La casa de subastas se encuentra en la cumbre central de Cima del Trueno. Busca junto a la parte inferior de la Torre de los jinetes del viento. Que tus antepasados cuiden de ti.', `FemaleText_loc1`='경매장은 썬더 블러프 중앙에서 찾을 수 있습니다. 와이번 조련사의 탑 맨 아래층을 찾아보십시오. 선조님의 영혼이 당신을 보살피기를.', `FemaleText_loc4`='你可以在雷霆崖的中央高地找到拍卖行。在双足飞龙飞行点下方附近找找吧，愿你的先祖保佑你。', `FemaleText_loc5`='拍賣場位於雷霆崖的中央尖塔，在雙足飛龍塔下方附近找找吧。願你的祖先保佑你。', `FemaleText_loc7`='La casa de subastas se encuentra en la cumbre central de Cima del Trueno. Busca junto a la parte inferior de la Torre de los jinetes del viento. Que tus antepasados cuiden de ti.' WHERE `ID`=5503;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='충격적인 얘기일지 모르겠지만 요즘 들어 경기가 영 안 좋아서 말이지...', `MaleText_loc4`='或许这会令你震惊，但是近来的事情不是那么顺利……', `MaleText_loc5`='或許這會令你震驚，但是近來的事情不是那麼順利...', `MaleText_loc7`='Puede que esto te escandalice, pero el negocio no ha ido nada bien últimamente...' WHERE `ID`=5504;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='테라모어에 온 것을 환영합니다, $n.$B$B도시를 지키는 것이 우선이라 제대로 인사할 시간도 갖지 못해 미안합니다. 우리 삶의 방식과 얼라이언스의 신성함을 위협하는 것들이 너무나도 많습니다. 내 주민들이 안전하고 행복하게 살 수 있도록 하려면 우리 지배권 밖에 있는 세력들에 대한 경계를 늦출 수 없답니다.$B$B우린 나중에 얘기를 더 나눌 기회가 있을 겁니다.', `FemaleText_loc4`='欢迎你来到塞拉摩，$n。$B$B我没时间跟你寒暄，我为自己的唐突向你道歉，但是我必须以城市为首。我们的生活和联盟的尊严受到了严重的威胁。要想使我的人民平安幸福，我就必须对不在我们控制之外的力量保持警惕。$B$B或许稍后我们能找时间谈谈。', `FemaleText_loc5`='歡迎你來到塞拉摩，$n。$B$B我沒時間跟你寒暄，我為自己的唐突向你道歉，但是我必須以城市為首。我們的生活和聯盟的尊嚴受到了嚴重的威脅。要想使我的人民平安幸福，我就必須對不在我們控制之外的力量保持警惕。$B$B或許稍後我們能找時間談談。', `FemaleText_loc7`='Te doy la bienvenida a Theramore, $n.$B$BTe pido disculpas por ser tan cortante y por no tener tiempo para atenderte como es debido, pero mi ciudad es mi prioridad. Muchas cosas amenazan nuestra forma de vida y la santidad de la Alianza. Debo estar totalmente alerta frente a las fuerzas externas que escapan a nuestro control si quiero que mi gente esté segura y viva feliz.$B$BTal vez tengamos más tiempo para hablar después.' WHERE `ID`=5505;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그대 덕분에 헨델을 잡아들일 수 있었습니다.$B$B심문은 천천히 진행되고 있지만 반드시 모든 걸 털어놓도록 할 겁니다.$B$B일단은 참고 기다려 주세요. 그대의 도움이 필요하면 즉시 연락을 드리겠습니다.$B$B그때까지는 부디 테라모어에서 편안히 지내도록 하세요. 얼라이언스의 벗으로서 우리 도시의 성벽 아래에서 집처럼 얼마든지 오래 머무르셔도 좋습니다.', `FemaleText_loc4`='亨德尔已经被我们逮捕了，$n。谢谢你。$B$B尽管审讯的进展会比较缓慢，但我向你保证，他会告诉我们他所知道的一切。$B$B眼下还请你耐心等待。如果我需要你的帮助，就会马上联系你。$B$B在那之前，请享受塞拉摩之旅，我邀请你作为联盟的朋友来到我们城市，要待多久随便你。', `FemaleText_loc5`='亨德爾已經被我們逮捕了，$n。謝謝你。$B$B儘管審訊的進展會比較緩慢，但我向你保證，他會告訴我們他所知道的一切。$B$B現在還請你耐心等待。如果我需要你的幫助，就會馬上聯繫你。$B$B在那之前，請享受塞拉摩之旅，我邀請你作為聯盟的朋友來到我們城市，要待多久隨便你。', `FemaleText_loc7`='Gracias a ti, $n, Hendel está bajo nuestra custodia.$B$BSi bien el interrogatorio es lento, te aseguro que nos dirá todo lo que sabe.$B$BPor ahora, ten paciencia. Te buscaré de inmediato si necesitamos ayuda.$B$BHasta entonces, disfruta de Theramore y te invito a quedarte el tiempo que quieras dentro de los muros de nuestra ciudad como amigo de la Alianza.' WHERE `ID`=5506;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다단가와 저는 준비가 끝났으니 당신도 준비가 됐으면 출발하도록 하죠!', `FemaleText_loc4`='要是你准备就绪，我和达丹加也整装待发了。我们出发吧！', `FemaleText_loc5`='要是你準備就緒，我和達丹加也整裝待發了。我們出發吧!', `FemaleText_loc7`='Si estás $glisto:lista;, Dadanga y yo también lo estamos. ¡En marcha!' WHERE `ID`=5508;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, 제가 도와드릴 일이 있는지요?', `MaleText_loc4`='是的$g兄弟:姐妹;，我可以帮你吗？', `MaleText_loc5`='是的$g兄弟:姐妹;，我可以幫你嗎?', `MaleText_loc7`='Sí, $ghermano:hermana;, ¿cómo puedo ayudarte?', `FemaleText_loc1`='안녕하십니까, 제가 도와드릴 일이 있는지요?', `FemaleText_loc4`='是的$g兄弟:姐妹;，我可以帮你吗？', `FemaleText_loc5`='是的$g兄弟:姐妹;，我可以幫你嗎?', `FemaleText_loc7`='Sí, $ghermano:hermana;, ¿cómo puedo ayudarte?' WHERE `ID`=5509;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋아요. 제가 가젯잔으로 통하는 길을 알고 있습니다. 당신이 해 줘야 할 일은 우리에게 달려드는 야수들을 떼어놓는 거예요. 다단가는 자기 방어를 할 줄은 알지만 오랫동안은 버틸 수가 없어요. 준비가 끝나면 알려주세요, $n.', `FemaleText_loc4`='好吧……我知道如何往返加基森。但我需要你驱赶沿路的野兽。我已经对 达丹加进行了良好的自我保护训练，但是我们无法应对那儿过于疯狂的野兽。你准备好了就告诉我吧，$n。', `FemaleText_loc5`='好吧...我知道如何往返加基森。但我需要你驅趕沿路的野獸。我已經對 達丹加進行了良好的自我保護訓練，但是我們無法應對那兒過於瘋狂的野獸。你準備好了就告訴我吧，$n。', `FemaleText_loc7`='De acuerdo... Conozco el camino de ida y vuelta a Gadgetzan. Lo que necesito que hagas es que mantengas a las bestias alejadas de nosotros. He entrenado a Dadanga para que se defienda sola, pero no podemos controlar por mucho tiempo la locura que crece allí fuera. Dime cuándo estás $glisto:lista; para partir, $n.' WHERE `ID`=5511;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다단가는 어떤 짐승인가요?', `MaleText_loc4`='你认为达丹加如何？', `MaleText_loc5`='你認為達丹加如何?', `MaleText_loc7`='¿Qué piensas de Dadanga?', `FemaleText_loc1`='다단가는 어떤 짐승인가요?', `FemaleText_loc4`='你认为达丹加如何？', `FemaleText_loc5`='你認為達丹加如何?', `FemaleText_loc7`='¿Qué piensas de Dadanga?' WHERE `ID`=5512;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여관', `MaleText_loc4`='旅店', `MaleText_loc5`='旅店', `MaleText_loc7`='Posada', `FemaleText_loc1`='여관', `FemaleText_loc4`='旅店', `FemaleText_loc5`='旅店', `FemaleText_loc7`='Posada' WHERE `ID`=5513;
