UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경매장', `MaleText_loc4`='拍卖行', `MaleText_loc5`='拍賣場', `MaleText_loc7`='Casa de subastas', `FemaleText_loc1`='경매장', `FemaleText_loc4`='拍卖行', `FemaleText_loc5`='拍賣場', `FemaleText_loc7`='Casa de subastas' WHERE `ID`=5515;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도시의 정문 바로 밖에 표지판이 있네. 그 표지판을 따라가면 서쪽 비행선 탑승장으로 갈 수 있을 거야.', `MaleText_loc4`='在城市的大门外有一处路标指向西部地精塔。', `MaleText_loc5`='在城市的大門外有一處路標，上頭註明了往西方飛艇塔的方向。', `MaleText_loc7`='Justo fuera de la Entrada Principal de la ciudad hay un poste indicador. Apunta hacia la torre del zepelín. Habla con el maestro de zepelines Frezza, en la parte superior de la torre.', `FemaleText_loc1`='도시의 정문 바로 밖에 표지판이 있네. 그 표지판을 따라가면 서쪽 비행선 탑승장으로 갈 수 있을 거야.', `FemaleText_loc4`='在城市的大门外有一处路标指向西部地精塔。', `FemaleText_loc5`='在城市的大門外有一處路標，上頭註明了往西方飛艇塔的方向。', `FemaleText_loc7`='Justo fuera de la Entrada Principal de la ciudad hay un poste indicador. Apunta hacia la torre del zepelín. Habla con el maestro de zepelines Frezza, en la parte superior de la torre.' WHERE `ID`=5516;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도시 밖, 남동쪽에 있는 동쪽 비행선 탑승장을 찾아가게.', `MaleText_loc4`='去城外东南方找东部飞艇塔。', `MaleText_loc5`='去城外東南方找東部飛艇降落塔。', `MaleText_loc7`='Busca la torre de aterrizaje de zepelines que está fuera de la ciudad en el sudeste.', `FemaleText_loc1`='도시 밖, 남동쪽에 있는 동쪽 비행선 탑승장을 찾아가게.', `FemaleText_loc4`='去城外东南方找东部飞艇塔。', `FemaleText_loc5`='去城外東南方找東部飛艇降落塔。', `FemaleText_loc7`='Busca la torre de aterrizaje de zepelines que está fuera de la ciudad en el sudeste.' WHERE `ID`=5517;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비행선 기장', `MaleText_loc4`='飞艇管理员', `MaleText_loc5`='飛艇管理員', `MaleText_loc7`='Maestro de zepelines', `FemaleText_loc1`='비행선 기장', `FemaleText_loc4`='飞艇管理员', `FemaleText_loc5`='飛艇管理員', `FemaleText_loc7`='Maestro de zepelines' WHERE `ID`=5518;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 형제는 실바나스 여왕님에게 헌신하기로 다짐했소. 가장 힘든 시기에 그분은 한 줄기 빛과 같은 분이셨소. 우리에게 닥친 운명을 극복하기 위해, 아침 저녁으로 희생하고 있소.$B$B우리가 언제나 약하게만 머물러 있지는 않을 거요. 우리가 마땅히 받을 자격이 있는 것은 받아내고, 우리가 겪은 고통은 열 배로 되갚을 거요. 얼굴에 차디찬 미소를 머금은 채로... 반드시 그렇게 하고야 말 거요.', `MaleText_loc4`='我和我的兄弟效忠于希尔瓦娜斯。在最黑暗的时代，她是我们的指路明灯。我们日复一日地奉献着，希望使种族避免遭受厄运。$B$B我们不会一直软弱下去的。我们会取回自己应得的。我们将报复敌人，让他们尝到十倍于我们的痛苦。并且，我们将面带微笑报复敌人。', `MaleText_loc5`='我和我的兄弟效忠於希瓦娜斯。在最黑暗的時代，她是我們的指路明燈。我們日復一日地奉獻著，希望使種族避免遭受厄運。$B$B我們不會一直軟弱下去的。我們會取回自己應得的。我們將報復敵人，讓他們嘗到十倍於我們的痛苦。並且，我們將面帶微笑報復敵人。', `MaleText_loc7`='Mi hermano y yo hemos dedicado nuestra vida a Sylvanas. Ella es nuestro faro de luz en los momentos más oscuros. Nos sacrificamos todos los días para garantizar que nuestra especie supere el destino que nos ha elegido.$B$BNo seguiremos siendo débiles. Recuperaremos lo que es nuestro. Devolveremos por diez el dolor que nos han infligido. Y lo haremos sonrientes.' WHERE `ID`=5519;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실바나스 여왕님께서는 아제로스의 자연 현상을 조사하라고 명령을 내리셨소. 그러면 비밀스러운 과거에 대한 뭔가 엄청난 사실을 알아낼 수 있을 거라고 생각하고 계시지.$B$B여왕님께서 그런 것들을 어떻게 아시는지는 나도 잘 모르겠지만, 나는 그분을 전적으로 믿기 때문에 최선을 다할 것이오.$B$B지금은 진흙괴물, 수액괴물 같은 것들을 조사하고 있소. 이 생물들의 구조는 유사하지만 환경의 영향을 크게 받는 것 같소.$B$B이 생물들의 견본을 구하는 데 당신 도움이 필요하오.', `MaleText_loc4`='希尔瓦娜斯女王已经下令对艾泽拉斯的某些自然现象进行调查。她觉得能从艾泽拉斯神秘的历史中学到更多的知识。$B$B我不知道要如何才能学到这些知识，但是我完全相信她，因此我会尽力而为的。所有的生物看起来很相似，但是周围的环境对它们的影响是不容忽略的。$B$B我需要你帮我收集生物样本。', `MaleText_loc5`='希瓦娜斯女王已經下令對艾澤拉斯的某些自然現象進行調查。她覺得能從艾澤拉斯神秘的歷史中學到更多的知識。$B$B我不知道要如何才能學到這些知識，但是我完全相信她，因此我會盡力而為的。所有的生物看起來很相似，但是周圍的環境對它們的影響是不容忽略的。$B$B我需要你幫我收集生物樣本。', `MaleText_loc7`='Lady Sylvanas ha ordenado que investiguemos algunos de los fenómenos naturales que ocurren en Azeroth. Ella cree que hay algo grandioso que aprender de su pasado oculto.$B$BNo sé cómo ha aprendido esas cosas, pero confío ciegamente en ella, así que daré lo mejor de mí.$B$BAhora mismo estoy investigando las babas, los mocos y organismos similares. Estas criaturas son muy similares en constitución, pero están gravemente afectadas por su entorno.$B$BTu ayuda me vendría bien para recoger muestras de las criaturas.' WHERE `ID`=5520;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 새끼가 죽는 것을 보고 분노합니다!', `FemaleText_loc4`='%s目睹死去的幼兽，变得极为愤怒！', `FemaleText_loc5`='%s看到一隻幼獸的死去變得極為憤怒!', `FemaleText_loc7`='¡%s enfurece al ver morir un cachorro!' WHERE `ID`=5521;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='붉은해적단의 제독 $n|1을;를; 위해 만세삼창!', `MaleText_loc4`='为血帆海军的上将——$n欢呼吧！', `MaleText_loc5`='為血帆海軍的上將─$n歡呼吧!', `MaleText_loc7`='¡Tres hurras para $n, almirante de la escuadra de Bucaneros Velasangre!' WHERE `ID`=5522;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='만세! 만세! 으아악!', `MaleText_loc4`='嗨！嗨！……啊……', `MaleText_loc5`='嗨!嗨!...啊...', `MaleText_loc7`='¡Hip, hip, hurra!' WHERE `ID`=5523;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<볼코르에게 다가가도 볼코르는 전혀 이쪽을 보지 않습니다. 붕대가 풀리지 않도록 하는 데 집중하고 있는 것 같습니다. 잠시 후 약간 놀란 듯이 이쪽을 봅니다.>$B$B아, 미안하오. 지금은 때가 좋지 않으니 양해를 바라오.', `MaleText_loc4`='<你靠近沃科尔时，他一点都不理睬你。他好象集中精力关注他的绷带以防脱落。过了一会儿，他抬头看你，有一点惊诧。>$B$B噢，对不起，$c。现在不太合适。我希望你能理解。', `MaleText_loc5`='<你靠近沃科爾時，他一點都不理睬你。他好像集中精力關注他的繃帶以防脫落。過了一會兒，他抬頭看你，有一點驚詫。>$B$B噢，對不起，$c。現在不太合適。我希望你能理解。', `MaleText_loc7`='<Volcor no te mira cuando te acercas a él. Parece concentrarse en evitar que se le caigan las vendas. Tras una pausa, levanta la mirada hacia ti, un poco perplejo.>$B$BOh, disculpa, $c. Este no es un buen momento. Espero que lo comprendas.' WHERE `ID`=5524;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 생각에 이 동굴을 빠져 나가는 방법은 두 가지뿐이오.$B$B당신이 준 망토를 내가 쓰고 당신은 알아서 자기 방어를 해 빠져 나가든가, 아니면 우리 둘이 등을 맞대고 함께 싸워 나가는 거요. 지금은 내가 다쳐서 좀 더 힘들겠지만...$B$B당신 자신의 힘은 스스로 더 잘 알 테니 당신의 판단에 맡기겠소.', `MaleText_loc4`='嗯，依我看来，$n，要离开这个洞穴有两种选择。$B$B我们可以秘密潜逃——我利用你给我的披风，你用你自己的办法；或者，我们一起杀出去，但是我受伤了，这个方法或许比较困难。$B$B你更了解自己的实力，因此我让你来做选择。', `MaleText_loc5`='嗯，依我看來，$n，要離開這個洞穴有兩種選擇。$B$B我們可以秘密潛逃─我利用你給我的披風，你用你自己的辦法;或者，我們一起殺出去，但是我受傷了，這個方法或許比較困難。$B$B你更瞭解自己的實力，因此我讓你來做選擇。', `MaleText_loc7`='Bueno, tal como lo veo, $n, tenemos dos opciones al abandonar esta caverna.$B$BPodemos irnos a hurtadillas: yo uso la capa que me diste y tú tendrás que buscarte la vida o, y esta puede ser una opción más difícil, considerando mis heridas, luchamos de espaldas, cada cual por su cuenta.$B$BDejo que lo decidas tú, ya que conoces tus fuerzas más que yo.' WHERE `ID`=5525;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오시오, 젊은이. 아이언포지 외곽에서 가장 괜찮은 물건을 찾고 있다면 제대로 찾아 오셨소이다.', `MaleText_loc4`='你好，$g小伙子:姑娘;，如果你想要在铁炉堡之外找到最好的交易地点，那么你就算找对地方了。', `MaleText_loc5`='你好，$g小夥子:姑娘;，如果你想要在鐵爐堡之外找到最好的交易地點，那麼你就算找對地方了。', `MaleText_loc7`='Saludos, $gmuchacho:muchacha;, si buscas los mejores precios que hay fuera de Forjaz, has venido al lugar adecuado.' WHERE `ID`=5526;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 호수에 있는 타락한 물의 정령들을 보셨나요? 참으로 안타까운 것이 어디서, 왜 나타나는 건지 조차 알지 못한다는 것입니다.$B$B사람들과 얘기를 나누다 그대의 이름을 접하게 되었습니다. 그대가 이 문제를 도와 줄 수 있을지도 모르겠군요.$B$B급선무는 이 타락한 정령들을 지배하는 자를 밝혀내는 것입니다.', `FemaleText_loc4`='你看到我们湖中污浊的水元素了吗，$n？这个场景令人感到伤感，但是我不知道它们是从哪里来的。$B$B在我过去的谈话中似乎有人提起过你的名字，或许你可以帮我。$B$B我们必须了解的第一件事就是谁控制着这些元素。', `FemaleText_loc5`='你看到我們湖中污濁的水元素了嗎，$n?這個場景令人感到傷感，但是我不知道它們是從哪裡來的。$B$B在我過去的談話中似乎有人提起過你的名字，或許你可以幫我。$B$B我們必須瞭解的第一件事就是誰控制著這些元素。', `FemaleText_loc7`='¿Has visto los elementales de agua podridos en nuestro lago, $n? Es un paisaje lamentable, pero no sé de dónde vienen.$B$BTu nombre se ha mencionado en conversaciones pasadas. Tal vez podrías ayudarme con este problema.$B$BLo primero que hay que saber es quién controla estos elementales.' WHERE `ID`=5527;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요? 전 구버 블럼프라고 해요.', `MaleText_loc4`='你好。我是古博·布拉普。', `MaleText_loc5`='你好。我是古博·布拉普。', `MaleText_loc7`='¡Hola! Soy Gubber Blump.' WHERE `ID`=5528;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구버, 저는 낚시를 할 줄 모릅니다.', `MaleText_loc4`='古博，我不知道怎么钓鱼。', `MaleText_loc5`='古博，我不知道怎麼釣魚。', `MaleText_loc7`='Gubber, no sé pescar.', `FemaleText_loc1`='구버, 저는 낚시를 할 줄 모릅니다.', `FemaleText_loc4`='古博，我不知道怎么钓鱼。', `FemaleText_loc5`='古博，我不知道怎麼釣魚。', `FemaleText_loc7`='Gubber, no sé pescar.' WHERE `ID`=5529;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구버, 저는 낚싯대가 없어요.', `MaleText_loc4`='古博, 我没有钓鱼竿。', `MaleText_loc5`='古博, 我沒有釣魚竿。', `MaleText_loc7`='Gubber, no tengo caña de pescar.', `FemaleText_loc1`='구버, 저는 낚싯대가 없어요.', `FemaleText_loc4`='古博, 我没有钓鱼竿。', `FemaleText_loc5`='古博, 我沒有釣魚竿。', `FemaleText_loc7`='Gubber, no tengo caña de pescar.' WHERE `ID`=5530;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='낚시는 정말로 쉽지요. 낚싯대에 줄을 묶어 끝에 미끼를 달고 물에 던지기만 하면 되거든요. 그러면 고기들이 입질을 시작할 겁니다.', `MaleText_loc4`='钓鱼真的很简单。就是拿着一根杆子带着一条线，或许再放些鱼饵，然后扔到水里去，然后那些鱼就会开始咬饵了。', `MaleText_loc5`='釣魚真的很簡單。就是拿著一根杆子帶著一條線，或許再放些魚餌，然後扔到水裡去，然後那些魚就會開始咬餌了。', `MaleText_loc7`='Pescar es realmente muy sencillo. Coge una caña con un hilo, si quieres coloca un cebo en el extremo y tíralo al agua. Con toda seguridad, los peces empezarán a picar.' WHERE `ID`=5531;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저한테 여분이 좀 있어요. 제값만 치르시면 낚싯대를 하나 드리지요. 미끼도 있답니다.', `MaleText_loc4`='我这里还有多余的，如果你付给我成本钱，我就可以给你一个。另外我还有一些诱饵。', `MaleText_loc5`='我這裡還有多餘的，如果你付給我成本錢，我就可以給你一個。另外我還有一些誘餌。', `MaleText_loc7`='Tengo algunas que me sobran. Si me pagas lo que me costaron, puedes coger una. También tengo algunos cebos.' WHERE `ID`=5532;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='...팬에 살짝 튀기고, 기름을 가득 넣고 튀기고, 휘저어 가며 튀기고...', `MaleText_loc4`='……油煎，油炸，还有爆炒……', `MaleText_loc5`='...油煎，油炸，還有爆炒...', `MaleText_loc7`='... fritos en sartén, fritos en mucho aceite y a la plancha...' WHERE `ID`=5533;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도움이 필요하십니까?', `MaleText_loc4`='你需要帮助吗？', `MaleText_loc5`='你需要幫助嗎?', `MaleText_loc7`='¿Necesitas ayuda?', `FemaleText_loc1`='도움이 필요하십니까?', `FemaleText_loc4`='你需要帮助吗？', `FemaleText_loc5`='你需要幫助嗎?', `FemaleText_loc7`='¿Necesitas ayuda?' WHERE `ID`=5534;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뒤를 엄호해주세요. 한바탕 소란이 일어날 거 같네요.', `FemaleText_loc4`='注意我的后面，这有可能非常混乱。', `FemaleText_loc5`='注意我的後面，這有可能非常混亂。', `FemaleText_loc7`='Vigila mi espalda, aquí se puede montar una buena.' WHERE `ID`=5535;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가까이 다가가 보니, 장비 안에 이상한 액체와 혼합물이 거품을 내며 끓고 있습니다. 장비 옆에는 수액괴물 견본을 집어넣는 데 쓸 법한 집게가 놓여 있습니다.$B$B안전 장비 비슷한 게 있는 것 같지만 먼지가 쌓여 있고 오랫동안 사용되지 않은 듯합니다.$B$B아무래도 건드리지 않는 것이 나을 것 같습니다.', `MaleText_loc4`='当你靠近时，那些液体和混合物剧烈地翻腾起来。设备旁边是一把巨大的钳子，似乎很适合用来夹起淤泥样本。$B$B还有安全齿轮装备，但是上面布满灰尘，似乎很久没有使用过了。$B$B你觉得什么东西都不碰为好。', `MaleText_loc5`='當你靠近時，那些液體和混合物劇烈地翻騰起來。設備旁邊是一把巨大的鉗子，似乎很適合用來夾起軟泥樣本。$B$B還有安全齒輪裝備，但是上面布滿灰塵，似乎很久沒有使用過了。$B$B你覺得最好什麼東西都別碰。', `MaleText_loc7`='Los líquidos y las mezclas burbujean y se contraen a medida que te acercas a ellos. Cerca del equipo hay un par de tenazas que parecen servir para coger un par de muestras de moco.$B$BTenemos equipo de seguridad, pero parece polvoriento y abandonado.$B$BNo creo que sea buena idea tocar nada.' WHERE `ID`=5536;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제 물건들이 저 안에 있어요!', `FemaleText_loc4`='设计图就在那儿！', `FemaleText_loc5`='設計圖就在那兒!', `FemaleText_loc7`='¡Los planos están ahí dentro!' WHERE `ID`=5537;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자들이 우리 알을 파괴하고 있다! 저지하라!!', `MaleText_loc4`='入侵者正在破坏我们的蛋！住手！！', `MaleText_loc5`='入侵者正在破壞我們的蛋!住手!!', `MaleText_loc7`='¡Unos intrusos están destruyendo nuestros huevos! ¡Basta!', `FemaleText_loc1`='침입자들이 우리 알을 파괴하고 있다! 저지하라!!', `FemaleText_loc4`='入侵者正在破坏我们的蛋！住手！！', `FemaleText_loc5`='入侵者正在破壞我們的蛋!住手!!', `FemaleText_loc7`='¡Unos intrusos están destruyendo nuestros huevos! ¡Basta!' WHERE `ID`=5538;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꽤액!! 콜록... 콜록! 담배를 끊어야겠군!', `MaleText_loc4`='哇！*咳**咳*我要戒烟！', `MaleText_loc5`='哇!*咳**咳*我要戒煙!', `MaleText_loc7`='¡¡¡KRUAAAAC!!! *tose* *tose* ¡Tengo que dejar de fumar!' WHERE `ID`=5539;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보물? 키블러에게 물어봐! 꽤액!', `MaleText_loc4`='问问基布雷尔关于宝藏的事情！哇！', `MaleText_loc5`='問問基布雷爾關於寶藏的事情!哇!', `MaleText_loc7`='¡Pregunta a Kibler acerca del tesoro! ¡KRUAAAAC!' WHERE `ID`=5540;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비쥬 사라졌다! 꽤액! 콜록!', `MaleText_loc4`='比修失败了！啊！*咳嗽*', `MaleText_loc5`='比修失敗了!啊!*咳嗽*', `MaleText_loc7`='¡Bijou se ha perdido! ¡KRUAAAAC! *tose*' WHERE `ID`=5541;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보물 숨겨진 장소 비쥬가 알아.', `MaleText_loc4`='比修知道宝藏被藏在哪儿了。', `MaleText_loc5`='比修知道寶藏被藏在哪兒了。', `MaleText_loc7`='Bijou sabe dónde están los tesoros.' WHERE `ID`=5542;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오푸스는 쿠에르고 골드 원해... 나 벌레 좋아해.', `MaleText_loc4`='奥普斯想要一些科尔戈的黄金……和一些虫子。', `MaleText_loc5`='奧普斯想要一些科爾戈的黃金...和一些蟲子。', `MaleText_loc7`='Opus quiere un poco de Oro Cuergo... con gusano.' WHERE `ID`=5543;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 첨탑으로 가서는 돌아오지 않아... 비쥬처럼!', `MaleText_loc4`='他们都去了黑石塔，但是跟比修一样……没有人活着回来。', `MaleText_loc5`='他們都去了黑石塔，但是跟比修一樣...沒有人活著回來。', `MaleText_loc7`='Todos van a la Cumbre, pero ninguno regresa... al igual que Bijou.' WHERE `ID`=5544;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='키블러는 조사를 받으러 식약청에 끌려갔어요.', `MaleText_loc4`='基布雷尔正在接受地精工程学协会的调查。', `MaleText_loc5`='基布雷爾正在接受地精工程學協會的調查。', `MaleText_loc7`='Kibler está siendo investigado por G.E.T.A.' WHERE `ID`=5545;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용이 오크를 지배해? 꽤액!', `MaleText_loc4`='龙控制着兽人！？不会吧！', `MaleText_loc5`='龍控制著獸人!?不會吧!', `MaleText_loc7`='¿¡Dragones controlando orcos!? ¡GUAU!' WHERE `ID`=5546;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 보잘것없는 벌레들아, 내가 왔다! 침입을 한 대가를 치르게 해 주마!', `MaleText_loc4`='我在这儿！可悲的渣滓，你们会为侵入这里付出代价的！', `MaleText_loc5`='我在這兒!可悲的渣滓，你們會為侵入這裡付出代價的!', `MaleText_loc7`='¡Aquí estoy! Ahora, pequeños gusanos insignificantes, ¡pagarán por su intromisión!' WHERE `ID`=5547;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 거칠게 으르렁거리더니 쓰러집니다. 그때 검은바위 첨탑의 전당 안에서 끔찍한 비명이 울려 퍼집니다. 무언가... 몹시 화가 난 것 같습니다.', `MaleText_loc4`='%s发出凄惨的低啸，轰然倒地。黑石塔大厅中紧接着传来令人毛骨悚然的咆哮声。看来有什么生物受到了刺激，变得异常愤怒。', `MaleText_loc5`='%s倒了下去，並發出了一聲淒慘的低嘯。緊接著，有一聲憤怒而恐怖的咆哮聲從黑石塔大廳中傳來。它聽起來似乎非常憤怒!', `MaleText_loc7`='%s suelta un gruñido gutural a medida que su cuerpo cae al suelo. Se escucha un aullido aterrador haciendo eco a través de los pasillos de la Cumbre de Roca Negra. Hay algo que está muy, pero que muy enfadado.' WHERE `ID`=5548;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, $n?', `MaleText_loc4`='你好，$n。', `MaleText_loc5`='你好，$n。', `MaleText_loc7`='Hola, $n.' WHERE `ID`=5549;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스쿼토의 말은 신경 쓰시지 않아도 됩니다. 일부러 무례하게 구는 게 아니라 굉장히 바쁜 것뿐이니까요. 스쿼토의 정찰이 끝날 때까지 우리는 좀 더 생산적인 걸 해 보도록 하죠?', `MaleText_loc4`='别担心斯奎尔图，$n。他不想这么粗鲁的，他只是非常繁忙。我们不如趁着等他完成侦察任务的时候做些更有用的事情？', `MaleText_loc5`='別擔心斯奎爾圖，$n。他不想這麼粗魯的，他只是非常繁忙。我們不如趁著等他完成偵察任務的時候做些更有用的事情?', `MaleText_loc7`='No os preocupéis de Skuerto, $n. No quería ser grosero, lo que ocurre es que está terriblemente ocupado. Mientras esperamos a que termine de explorar, ¿por qué no trabajamos en algo más productivo?' WHERE `ID`=5550;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요!$B$B전 지금 어떤 장치를 만들고 있는데 나중에 용의 알을 가져다 줄 일손이 필요할 거예요!', `FemaleText_loc4`='你好$n！$B$B我必须继续研究我的装置了，但是最终……我需要有人给我带来龙蛋！', `FemaleText_loc5`='你好$n!$B$B我必須繼續研究我的裝置了，但是最終...我需要有人給我帶來龍蛋!', `FemaleText_loc7`='¡Hola, $n!$B$BTengo que trabajar en mis dispositivos pero, en algún momento... ¡Voy a necesitar que alguien me consiga huevos de dragón!' WHERE `ID`=5551;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='불타는 평원은 위험한 곳이지만 나 같은 학자들은 지식을 넓히기 위해서라면 어떤 일이라도 감수하지요.', `FemaleText_loc4`='燃烧平原是个危险的地方，但是我这样的学者将不惜一切代价来获取新知识。', `FemaleText_loc5`='燃燒平原是個危險的地方，但是我這樣的學者將不惜一切代價來獲取新知識。', `FemaleText_loc7`='Las Estepas de Fuego es un lugar peligroso pero, los eruditos como yo, hacemos lo que sea por avanzar en nuestro conocimiento.' WHERE `ID`=5552;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부화장으로 돌아가겠습니다, 팅키. 알껍질급속냉각기가 필요합니다!', `MaleText_loc4`='我要返回龙蛋房了，丁奇。我需要一个龙蛋冷冻器！', `MaleText_loc5`='我要返回龍蛋房了，丁奇。我需要一個龍蛋冷凍器!', `MaleText_loc7`='Volveré al Grajero, Tinkee. ¡Necesito un ovosciloscopio!', `FemaleText_loc1`='부화장으로 돌아가겠습니다, 팅키. 알껍질급속냉각기가 필요합니다!', `FemaleText_loc4`='我要返回龙蛋房了，丁奇。我需要一个龙蛋冷冻器！', `FemaleText_loc5`='我要返回龍蛋房了，丁奇。我需要一個龍蛋冷凍器!', `FemaleText_loc7`='Volveré a El Grajero, Tinkee. ¡Necesito un ovosciloscopio!' WHERE `ID`=5553;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 검은무쇠를 제련하는 기술을 유용하게 쓰길 바라네. 지식 때문에 타락하는 일이 없도록... 우리처럼 말일세.', `MaleText_loc4`='愿你能得心应手地应用熔炼黑铁的技能，$n。但是不要让你的知识使你堕落……就像我们一样堕落了。', `MaleText_loc5`='願你能得心應手地應用熔煉黑鐵的技能，$n。但是不要讓你的知識使你墮落...就像我們一樣墮落了。', `MaleText_loc7`='Que tus habilidades en fundir hierro negro te sirvan de mucho, $n. Pero no dejes que tu conocimiento te corrompa... como lo ha hecho con nosotros.' WHERE `ID`=5554;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 제 지식을 전해줄 만한 이가 나타났군요. 걱정하지 마십시오. 당신의 생각을 본 것뿐이니 해로울 거 없습니다.', `MaleText_loc4`='终于……终于有人值得学到我的知识了。别担心——我已经了解你的想法，我不会伤害你的。', `MaleText_loc5`='終於...終於有人值得學到我的知識了。別擔心─我已經瞭解你的想法，我不會傷害你的。', `MaleText_loc7`='Por fin... uno de ustedes es digno de mi conocimiento. No se preocupen: he sondeado sus pensamientos y nada les hará daño.' WHERE `ID`=5555;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 듣도록 하십시오. 준비를 제대로 하지 않으면 검은바위의 군주가 당신을 분명 없애버리고 말 테니까 말입니다.', `MaleText_loc4`='听仔细了，要是你没有准备好的话，黑石统领会杀死你的。', `MaleText_loc5`='聽仔細了，要是你沒有準備好的話，黑石之王會殺死你的。', `MaleText_loc7`='Escuchad con atención, porque el señor de Roca Negra os destruirá si no estáis preparados.' WHERE `ID`=5556;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='카르 아만, $n. 아주 강한 $c 같군요. 이 지역에서는 조심하는 게 좋을 겁니다. 전혀 알지 못하는 물건에 손을 대거나 윗사람에게 불경하게 굴면 마땅한 응징을 받게 될 테니까요.$B$B우리를 존경하진 않더라도 불손한 행동을 하면 완력으로라도 우리의 힘을 존경하게 만들어 드리지요.$B$B자, 인사는 대충 이 정도로 끝내도록 하죠. 그런데 내가 도와 줄 일이라도 있나요?', `FemaleText_loc4`='你好，$n。你看上去是个强壮的$c——你应该能够在这个地区有所作为。你可以去接触一下你不了解的东西，否则对你的长辈表现出失礼的行为将招致惩罚。$B$B你可以不尊重我或者我的同伴，但是如果你真的那么愚蠢的话，你就必然会学会尊重我们的力量。$B$B现在，闲聊够了，有什么事情我可以帮忙的？', `FemaleText_loc5`='你好，$n。你看起來是個強壯的$c─你應該能夠在這個地區有所作為。你可以去接觸一下你不瞭解的東西，否則對你的長輩表現出失禮的行為將招致懲罰。$B$B你可以不尊重我或者我的同伴，但是如果你真的那麼愚蠢的話，你就必然會學會尊重我們的力量。$B$B現在，閒聊夠了，有什麼事情我可以幫忙的?', `FemaleText_loc7`='Kar Aman, $n. Pareces $gun:una; $c fuerte. Harías bien en cuidar de ti mismo en esta zona. Meterte con cosas sobre las que no tienes ni idea u ofender a tus mayores es causa justa de castigo.$B$BPuedes faltarme al respecto a mí o a mis compañeros, pero aprenderás a respetar nuestro poder si demuestras ser lo suficientemente idiota.$B$BBueno, dejando la cortesía a un lado, ¿en qué puedo ayudarte?' WHERE `ID`=5557;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 어느 정도 자신의 가치를 입증한 흑마법사 동료로군요.$B$B만나게 돼서 반가워요. 나는 미네라 보이드렌더라고 해요. 이런 이름을 지은 데는 다 그만한 이유가 있죠.$B$B당신은 강한 새 도구들에 쉽게 적응하고 어리석게 남에게 줘 버리지 않을 정도의 상식은 있는 것 같군요. 그렇다면 다시 나와 얘기를 하도록 해요. 아니면 전투는커녕 부둣가로 돌아가서 다시 고향으로 돌아가 편히 사시는 게 좋을 거예요.', `FemaleText_loc4`='啊，一个术士同伴已经在某种程度上证明了$g他的:她的;价值。$B$B很高兴认识你。我的名字是梅纳拉·沃伦德……那是有原因的。$B$B你看上去强大并博学，其他的工具……你是更强大的工具……会很受欢迎而不是愚蠢地泄密。如果事实确实如此，那再与我更深入地谈谈。如果不是，那么你知道你该怎么回到码头然后回到海洋的另一边。', `FemaleText_loc5`='啊，一個術士同伴已經在某種程度上證明了$g他的:她的;價值。$B$B很高興認識你。我的名字是梅納拉·虛無撕裂者...那是有原因的。$B$B你看起來強大並博學，其他的工具...你是更強大的工具...會很受歡迎而不是愚蠢地洩密。如果事實確實如此，那再與我更深入地談談。如果不是，那麼你知道你該怎麼回到碼頭然後回到海洋的另一邊。', `FemaleText_loc7`='Ah, $gun:una; joven $gbrujo:bruja; que ha demostrado su valor en cierta medida.$B$BEs un placer conocerte. Mi nombre es Menara Nadiz... y no sin razón.$B$BPareces tener ciertos poderes y conocimientos suficientemente sólidos como para considerar enseñarte otras herramientas... más poderosas... que aprovecharás sabiamente. Si esto es así, sígueme contando. En caso contrario, ya conoces el camino de vuelta al puerto y de ahí al mar.' WHERE `ID`=5558;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='인간들은 대개 가슴 왼쪽, 4번째와 5번째 갈비뼈 사이가 약하다네. 이 자리를 이렇게 찌르는 연습을 해 보도록...', `MaleText_loc4`='人类左边第4和第5根肋骨之间的部位最脆弱。让我们来练习一下攻击这个部位……', `MaleText_loc5`='人類左邊第4和第5根肋骨之間的部位最脆弱。讓我們來練習一下攻擊這個部位...', `MaleText_loc7`='Los humanos suelen ser vulnerables en el costado izquierdo entre la cuarta y la quinta costilla. Practiquemos atacando esta zona así...', `FemaleText_loc1`='인간들은 대개 가슴 왼쪽, 4번째와 5번째 갈비뼈 사이가 약하다네. 이 자리를 이렇게 찌르는 연습을 해 보도록...', `FemaleText_loc4`='人类左边第4和第5根肋骨之间的部位最脆弱。让我们来练习一下攻击这个部位……', `FemaleText_loc5`='人類左邊第4和第5根肋骨之間的部位最脆弱。讓我們來練習一下攻擊這個部位...', `FemaleText_loc7`='Los humanos suelen ser vulnerables en el costado izquierdo entre la cuarta y la quinta costilla. Practiquemos atacando esta zona así...' WHERE `ID`=5559;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 자네가 한번 해 보게.', `MaleText_loc4`='你来试试看。', `MaleText_loc5`='你來試試看。', `MaleText_loc7`='Ahora inténtalo tú.', `FemaleText_loc1`='이제 자네가 한번 해 보게.', `FemaleText_loc4`='你来试试看。', `FemaleText_loc5`='你來試試看。', `FemaleText_loc7`='Ahora inténtalo tú.' WHERE `ID`=5560;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나이트 엘프들은 마법을 시전할 때 한쪽 다리에 무게를 두는 경향이 있지. 그 다리는 이렇게 찌르게.', `MaleText_loc4`='暗夜精灵在施法时喜欢单腿站立。你可以这样来攻击那条站立的腿……', `MaleText_loc5`='夜精靈在施法時喜歡單腿站立。你可以這樣來攻擊那條站立的腿...', `MaleText_loc7`='A los elfos de la noche les gusta sostenerse sobre una pierna mientras tiran el anzuelo. Pégales en esa pierna así...', `FemaleText_loc1`='나이트 엘프들은 마법을 시전할 때 한쪽 다리에 무게를 두는 경향이 있지. 그 다리는 이렇게 찌르게.', `FemaleText_loc4`='暗夜精灵在施法时喜欢单腿站立。你可以这样来攻击那条站立的腿……', `FemaleText_loc5`='夜精靈在施法時喜歡單腿站立。你可以這樣來攻擊那條站立的腿...', `FemaleText_loc7`='A los elfos de la noche les gusta sostenerse sobre una pierna mientras tiran el anzuelo. Pégales en esa pierna así...' WHERE `ID`=5561;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드워프들은 때로 뒤돌아 서서 등에 허점이 드러나게 한다네. 그 기회를 살려서 이렇게 찌르게.', `MaleText_loc4`='有时，矮人会在把武器抡圆的过程中将背部暴露出来。利用这个机会像这样打下去……', `MaleText_loc5`='有時，矮人會在把武器掄圓的過程中將背部暴露出來。利用這個機會像這樣打下去...', `MaleText_loc7`='Los enanos a veces giran sobre sí mismos dejando sus espaldas al descubierto. Aprovecha esa oportunidad para golpearlos así...', `FemaleText_loc1`='드워프들은 때로 뒤돌아 서서 등에 허점이 드러나게 한다네. 그 기회를 살려서 이렇게 찌르게.', `FemaleText_loc4`='有时，矮人会在把武器抡圆的过程中将背部暴露出来。利用这个机会像这样打下去……', `FemaleText_loc5`='有時，矮人會在把武器掄圓的過程中將背部暴露出來。利用這個機會像這樣打下去...', `FemaleText_loc7`='Los enanos a veces giran sobre sí mismos dejando sus espaldas al descubierto. Aprovecha esa oportunidad para golpearlos así...' WHERE `ID`=5562;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노움들은 크기 때문에 맞히기 어려울 수가 있지만 엉덩이를 실룩거리면서 마구 왔다갔다하는 경향이 있으니 그럴 때는 이렇게 찌르게...', `MaleText_loc4`='侏儒因为体格矮小而很难击中。不过，他们有时会手舞足蹈，摆臀扭胯。这时你就可以像这样攻击他们……', `MaleText_loc5`='地精因為體格矮小而很難擊中。不過，他們有時會手舞足蹈，擺臀扭胯。這時你就可以像這樣攻擊他們...', `MaleText_loc7`='A los gnomos puede resultar difícil pegarles debido a su tamaño. No obstante, les encanta bailar y mover las caderas. Cuando lo hagan, atácalos así...', `FemaleText_loc1`='노움들은 크기 때문에 맞히기 어려울 수가 있지만 엉덩이를 실룩거리면서 마구 왔다갔다하는 경향이 있으니 그럴 때는 이렇게 찌르게...', `FemaleText_loc4`='侏儒因为体格?小而很难击中。不过，他们有时会手舞足蹈，摆臀扭胯。这时你就可以像这样攻击他们……', `FemaleText_loc5`='地精因為體格矮小而很難擊中。不過，他們有時會手舞足蹈，擺臀扭胯。這時你就可以像這樣攻擊他們...', `FemaleText_loc7`='A los gnomos puede resultar difícil pegarles debido a su tamaño. No obstante, les encanta bailar y mover las caderas. Cuando lo hagan, atácalos así...' WHERE `ID`=5563;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아. 정예군에 가담할 만한 재목인 것 같군. 자, 연습을 더 해 보지.', `MaleText_loc4`='很好。你有希望加入精英的行列。现在，你需要更多的训练。', `MaleText_loc5`='很好。你有希望加入精英的行列。現在，你需要更多的訓練。', `MaleText_loc7`='Bien. Tus aptitudes te hacen candidato a las fuerzas de élite. Ahora lo que necesitas es practicar más.', `FemaleText_loc1`='좋아. 정예군에 가담할 만한 재목인 것 같군. 자, 연습을 더 해 보지.', `FemaleText_loc4`='很好。你有希望加入精英的行列。现在，你需要更多的训练。', `FemaleText_loc5`='很好。你有希望加入精英的行列。現在，你需要更多的訓練。', `FemaleText_loc7`='Bien. Tus aptitudes te hacen candidato a las fuerzas de élite. Ahora lo que necesitas es practicar más.' WHERE `ID`=5564;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 힘을 되찾기 시작합니다!', `MaleText_loc4`='%s开始恢复力量！', `MaleText_loc5`='%s開始恢復力量!', `MaleText_loc7`='¡%s comienza a recuperar la fuerza!' WHERE `ID`=5565;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 힘을 거의 다 회복했습니다!', `MaleText_loc4`='%s几乎完全恢复了力量！', `MaleText_loc5`='%s幾乎完全恢復了力量!', `MaleText_loc7`='¡%s está casi en la plenitud de su fuerza!' WHERE `ID`=5566;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 힘을 완전히 회복해 속박에서 풀려납니다!', `MaleText_loc4`='%s恢复力量，摆脱了镣铐的束缚！', `MaleText_loc5`='%s恢復力量並擺脫了束縛!', `MaleText_loc7`='¡%s recupera su poder y se libera de sus ataduras!' WHERE `ID`=5567;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 오래전 고대 전투와 여러 충돌이 있었을 때, 저희 종족은 거의 멸종될 뻔했지요. 많은 고난을 겪었습니다, $r.$B$B불타는 군단의 학살. 악마의 영혼. 5대 위상의 분리. 데스윙의 봉기. 용아귀 부족에게 포로가 되어버린 저희의 여왕, 알렉스트라자 님.$B$B그러한 와중에도 저희에겐 용들의 흔들리지 않는 의지가 생겼지요. 이 세계에서 사라져만 가는 저희 종족을 대표하려는 용감한 세력이었습니다.', `MaleText_loc4`='很久以前——我们的种族经历了无数战乱和冲突，几乎到了灭绝的边缘。我们承受了太多灾难，$c。$B$B燃烧军团的进攻，恶魔之魂，巨龙军团的分裂，死亡之翼的崛起，我们的女王阿莱克丝塔萨受到龙喉氏族的奴役。$B$B经过种种磨难，我们拥有了不可动摇的意志——那是努力生存的大无畏力量。', `MaleText_loc5`='很久以前─我們的種族經歷了無數戰亂和衝突，幾乎到了滅絕的邊緣。我們承受了太多災難，$r。$B$B燃燒軍團的進攻，惡魔之魂，守護巨龍的分裂，死亡之翼的崛起，我們的女王雅立史卓莎受到龍喉氏族的奴役。$B$B經過種種磨難，我們擁有了不可動搖的意志─那是努力生存的大無畏力量。', `MaleText_loc7`='En décadas pasadas, en guerras y conflictos de otros tiempos, nuestra especie estuvo a un paso de la extinción. Hemos soportado muchas cosas, $r.$B$BEl ataque de la Legión Ardiente. El Alma demoníaca. Los Aspectos divididos. El ascenso de Alamuerte. La esclavización de nuestra reina, Alexstrasza, por los Faucedraco.$B$BEn todo ello, hemos demostrado tener la inquebrantable voluntad de los dragones, la fuerza impertérrita que ha luchado para representar nuestra existencia menguante en este mundo.' WHERE `ID`=5568;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 종족이라고요?', `MaleText_loc4`='你们的种族？', `MaleText_loc5`='你們的種族?', `MaleText_loc7`='¿Tu especie?', `FemaleText_loc1`='당신 종족이라고요?', `FemaleText_loc4`='你们的种族？', `FemaleText_loc5`='你們的種族?', `FemaleText_loc7`='¿Tu especie?' WHERE `ID`=5569;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇습니다. 지금은 당신의 앞에서 당신이 이해할 수 있는 형상으로 제가 서 있는 것입니다, 필멸자여. 밸라스트라즈라는 이름으로 알려진 용 앞에서 서 있을 용기가 있으십니까?$B$B<크게 웃는 밸란>$B$B그럼 계속 얘기를 할까요?', `MaleText_loc4`='我以你所能接受的形态站在你面前。显然，你无法接受一条名叫瓦拉斯塔兹的龙。$B$B<维埃兰笑了起来。>$B$B我可以继续吗？', `MaleText_loc5`='我以你所能接受的形態站在你面前。顯然，你無法接受一條名叫瓦拉斯塔茲的龍。$B$B<維埃蘭笑了起來。>$B$B我可以繼續嗎?', `MaleText_loc7`='Ciertamente. Aparezco delante de ti en una forma que no puedes comprender, mortal. Claro, tú no podrías soportar estar ante la presencia del dragón conocido como Vaelastrasz.$B$B<Vaelan ríe.>$B$B¿Continúo?' WHERE `ID`=5570;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네.', `MaleText_loc4`='拜托。', `MaleText_loc5`='拜託。', `MaleText_loc7`='Por favor.', `FemaleText_loc1`='네.', `FemaleText_loc4`='拜托。', `FemaleText_loc5`='拜託。', `FemaleText_loc7`='Por favor.' WHERE `ID`=5571;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 왜 이곳에 왔는지 얘기해 드려야 하겠군요.$B$B데스윙이라는 위상이나 그의 자손들인 네파리안이나 오닉시아에 대해서 아십니까?', `MaleText_loc4`='或许我应该告诉你为什么我会在这儿。$B$B你知道死亡之翼或者他的后裔，奈法利安和奥妮克希亚吗？', `MaleText_loc5`='或許我應該告訴你為什麼我會在這兒。$B$B你知道守護巨龍，死亡之翼或者他的後裔，奈法利安和奧妮克希亞嗎?', `MaleText_loc7`='Tal vez debería decirte por qué estoy aquí.$B$B¿Conoces el Aspecto Alamuerte? O a sus descendientes, Nefarian y Onyxia?' WHERE `ID`=5572;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니요. 모릅니다, 밸란.', `MaleText_loc4`='不，维埃兰，我不清楚。', `MaleText_loc5`='不，維埃蘭，我不清楚。', `MaleText_loc7`='No, Vaelan, no los conozco.', `FemaleText_loc1`='아니요. 모릅니다, 밸란.', `FemaleText_loc4`='不，维埃兰，我不清楚。', `FemaleText_loc5`='不，維埃蘭，我不清楚。', `FemaleText_loc7`='No, Vaelan, no los conozco.' WHERE `ID`=5573;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한때 넬타리온이라는 이름으로 불린 데스윙은 세계의 힘을 보유한 위상이었지요. 이 필멸의 세계에 대한 거의 무한한 권한을 만물의 창조주, 카즈고로스라는 티탄에게서 받았습니다.$B$B타락한 그는 배반과 속임수로 다른 위상들이 자신들의 힘으로 악마의 영혼이라는 물건을 만들도록 설득했고 그 물건으로 한때 위대했던 위상들을 약하게 하여 갈라놓은 것입니다.', `MaleText_loc4`='死亡之翼，曾被称为奈萨里奥，它是代表世界的力量的守护巨龙——世界的缔造者卡兹格罗斯赋予了他无尽的力量，让他保护这个世界。$B$B但是这个卑鄙的家伙欺骗了其他四条守护巨龙，让他们使用自己的力量制造了恶魔之魂——这使得他们的力量大为减弱，巨龙军团于是就分裂了。', `MaleText_loc5`='死亡之翼，曾被稱為奈薩里奧，它是代表世界的力量的守護巨龍─世界的締造者卡茲格羅斯賦予了他無盡的力量，讓他保護這個世界。$B$B但是這個卑鄙的傢伙欺騙了其他四條守護巨龍，讓他們使用自己的力量製造了惡魔之魂─這使得他們的力量大為減弱，巨龍軍團於是就分裂了。', `MaleText_loc7`='Alamuerte, anteriormente conocido como Neltharion, fue el Aspecto que encarnó la fuerza del mundo: concedía poder casi ilimitado en este reino mortal a través del creador de titanes conocido como Khaz’goroth: Forjador del mundo.$B$BMediante la traición y el engaño, este ser inmundo convenció a los otros cuatro Aspectos para que transmitieran sus poderes a un elemento, conocido como el Alma demoníaca, debilitándolos enormemente y provocando su división.' WHERE `ID`=5574;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악마의 영혼이라고요?', `MaleText_loc4`='恶魔之魂？', `MaleText_loc5`='惡魔之魂?', `MaleText_loc7`='¿Alma demoníaca?', `FemaleText_loc1`='악마의 영혼이라고요?', `FemaleText_loc4`='恶魔之魂？', `FemaleText_loc5`='惡魔之魂?', `FemaleText_loc7`='¿Alma demoníaca?' WHERE `ID`=5575;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇습니다. 이 물건은 결국 파괴되었고 데스윙도 다른 4명의 위상들이 모여 형성된 새로운 힘에 의해 거의 처치될 뻔했지요. 지금 데스윙이 어디에 있는지는 모르나 그의 자손인 네파리안이 이 요새를 지배하며 자신의 아버지가 남긴 업적을 마저 이루고자 한다는 것은 압니다.', `MaleText_loc4`='是的。最终恶魔之魂被摧毁了，剩余的四条守护巨龙联合起来，几乎取了死亡之翼的性命。没人知道死亡之翼现在到底在哪里。但是，我们知道他的一名后裔奈法利安正统治着这座要塞，希望能继续他父亲未竟的事业。', `MaleText_loc5`='是的。最終惡魔之魂被摧毀了，剩餘的四條守護巨龍聯合起來，幾乎取了死亡之翼的性命。沒人知道死亡之翼現在到底在哪裡。但是，我們知道他的一名後裔奈法利安正統治著這座要塞，希望能繼續他父親未竟的事業。', `MaleText_loc7`='Así es. El elemento fue destruido finalmente y Alamuerte estuvo a punto de sucumbir frente al poder conjunto y renovado de los cuatro Aspectos restantes. Alamuerte ahora resulta desconocido. No obstante, lo que sí sabemos es que Nefarian, uno de sus descendientes, gobierna esta ciudadela y desea continuar la misión de su padre desde el punto en que la dejó.' WHERE `ID`=5576;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그가 남긴 업적이라고 하셨습니까?', `MaleText_loc4`='未竟的事业？', `MaleText_loc5`='未竟的事業?', `MaleText_loc7`='¿Desde donde la dejó?', `FemaleText_loc1`='그가 남긴 업적이라고 하셨습니까?', `FemaleText_loc4`='未竟的事业？', `FemaleText_loc5`='未竟的事業?', `FemaleText_loc7`='¿Desde donde la dejó?' WHERE `ID`=5577;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='데스윙은 추방을 당하기 전, 타락한 자식을 하나 탄생시키려고 하고 있었습니다. 위상의 선천적인 힘과 능력에 대한 면역이 있을 뿐만 아니라 데스윙의 완전한 지배를 받는 반 종족을 만들려고 한 것이지요.$B$B데스윙은 실패했지만 네파리안은 적어도 일부는 성공을 했을지도 모르겠습니다.$B$B꿈의 위상, 이세라 님이 이 몹쓸 생물들을 보고서는 저희에게 행동을 취하도록 한 것입니다. 이 "오색" 용혈족이라는 것들이 정말로 존재한다면 반드시 녀석들을 말살해야만 합니다.', `MaleText_loc4`='在被放逐之前，死亡之翼曾试图产下混血的后代。混血的龙不仅无法获得守护巨龙天生的力量，也无法被死亡之翼控制。$B$B似乎奈法利安在他父亲失败了的事情上取得了成功——至少是一些进展。$B$B梦境之神伊瑟拉预见到了这种混血龙类的存在，我们必须杀死那些“彩色”的龙。', `MaleText_loc5`='在被放逐之前，死亡之翼曾試圖產下混血的後代。混血的龍不僅免疫於牠們守護巨龍天生的力量，而且完全服從死亡之翼。$B$B似乎奈法利安在他父親失敗了的事情上取得了成功─至少是一些進展。$B$B夢境之王伊瑟拉預見到了這種混血龍類的存在，我們必須殺死那些「炫彩」之龍。', `MaleText_loc7`='Antes de su destierro, Alamuerte estaba intentando crear un descendiente impuro. Deseaba crear razas que no solo fueran inmunes a los poderes y habilidades innatos de sus Aspectos, sino que estuvieran bajo el control total de Alamuerte.$B$BAl parecer, el hijo de Nefarian logró lo que su padre nunca consiguió, al menos en parte.$B$BFue Ysera, Aspecto de los sueños, fue quien advirtió estas abominaciones y nos obligó a actuar. Si esta especie de dragonantes ‘cromáticos’ existe, tiene que ser destruida.' WHERE `ID`=5578;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위상들의 힘을 모아서 녀석들을 쳐부술 수는 없습니까?', `MaleText_loc4`='为什么巨龙们不联合起来消灭它们？', `MaleText_loc5`='為什麼守護巨龍們不聯合起來消滅它們?', `MaleText_loc7`='¿Por qué no destruirla utilizando las fuerzas conjuntas de los Aspectos?', `FemaleText_loc1`='위상들의 힘을 모아서 녀석들을 쳐부술 수는 없습니까?', `FemaleText_loc4`='为什么巨龙们不联合起来消灭它们？', `FemaleText_loc5`='為什麼守護巨龍們不聯合起來消滅它們?', `FemaleText_loc7`='¿Por qué no destruirla utilizando las fuerzas conjuntas de los Aspectos?' WHERE `ID`=5579;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그건 저희의 방식이 아닌데다 가능하지도 않습니다. 네파리안은 위상들만큼이나 오래된 고대 보호막의 보호를 받고 있지요. 그것 때문에 제가 이 요새의 내부 성소에 들어가지 못하는 것입니다. 암흑 마법 때문에 임명되지 않은용군단은 들어갈 수가 없어요. 하지만...', `MaleText_loc4`='这不是我们做事的方法，也不可能是。奈法利安受到远古结界的保护，这些结界与守护巨龙本身一样古老。正是它们阻止我进入这座要塞的内部。除非……除非得到授权，否则黑暗魔法会永远把我们挡在外面。', `MaleText_loc5`='這不是我們做事的方法，也不可能是。奈法利安受到遠古結界的保護，這些結界與守護巨龍本身一樣古老。正是它們阻止我進入這座要塞的內部。除非...除非得到授權，否則黑暗魔法會永遠把我們擋在外面。', `MaleText_loc7`='No es nuestra opción y tampoco sería posible. Nefarian está protegido por salas antiguas, tanto como los propios Aspectos. Ellas me impiden entrar en el Sagrario Interior de esta ciudadela. La magia negra evita que cualquiera de los otros Vuelos entre sin haber sido ordenados... a menos que...' WHERE `ID`=5580;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만?', `MaleText_loc4`='除非？', `MaleText_loc5`='除非?', `MaleText_loc7`='¿A menos que...?', `FemaleText_loc1`='하지만?', `FemaleText_loc4`='除非？', `FemaleText_loc5`='除非?', `FemaleText_loc7`='¿A menos que...?' WHERE `ID`=5581;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용족이 아닌 자가 벼리지 않은 승천의 인장을 구해 보호막을 지나가는 것은 가능합니다. 저 같은 자가 그러한 물건을 지니면 저 자신이 파괴되어 버리겠지만 당신이라면 그 인장으로 보호막을 약하게 할 수 있을 것입니다.', `MaleText_loc4`='除龙族之外的任何人都可能获得晋升印章并通过那层保护屏障，但是这样的东西肯定会要了我的性命，或许你能使用它，想办法破除屏障。', `MaleText_loc5`='除龍族之外的任何人都可能獲得晉升徽印並通過那層保護屏障，但是這樣的東西肯定會要了我的性命，或許你能使用它，想辦法破除屏障。', `MaleText_loc7`='Solo un ser, que no es de la especie de los dragones, puede obtener el Sello Adornado de Ascensión y atravesar la barrera protegida. Si bien la posesión de este objeto podría suponer mi destrucción, tal vez tú podrías utilizarlo y hacer descender la barrera.' WHERE `ID`=5582;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시도는 해 보겠습니다만 먼저 어떻게 해야 하는지 가르쳐 주십시오.', `MaleText_loc4`='我很乐意尝试，但是我需要指导。', `MaleText_loc5`='我很樂意嘗試，但是我需要指導。', `MaleText_loc7`='Lo intentaría, pero esto requiere instrucción.', `FemaleText_loc1`='시도는 해 보겠습니다만 먼저 어떻게 해야 하는지 가르쳐 주십시오.', `FemaleText_loc4`='我很乐意尝试，但是我需要指导。', `FemaleText_loc5`='我很樂意嘗試，但是我需要指導。', `FemaleText_loc7`='Lo intentaría, pero esto requiere instrucción.' WHERE `ID`=5583;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 요새의 아랫부분에서 가공하지 않은 승천의 인장을 습득한 녀석 하나를 찾아야 합니다. 그 물건을 취득하면 요새 위층으로 갈 수 있고, 또한 네파리안의 정예 경비대인 검은손부대의 일원이 되는 첫 걸음이니만큼 하급 생물이 이 물건을 취득하는 것은 크나큰 영광이지요. 그 물건을 찾아 제게 가져오시면 제가 그 물건의 성질을 조사하겠습니다. 인장을 다 조사하면 어떻게 해야 할지 알 수 있을 것입니다.', `MaleText_loc4`='你必须在这座要塞下层部分的那些邪恶生物里找到一个拥有原始晋升印章的家伙。对于那些劣等生物来说，得到这枚物品是一个至高无上的荣誉，这是迈入堡垒上层，进入奈法利安的精英军团——黑手军团的第一步。找到这么一件东西，把它交给我，让我来检查一下它，然后我就会知道下一步该怎么做了。', `MaleText_loc5`='你必須在這座要塞下層部分的那些邪惡生物裡找到一個擁有原始晉升徽印的傢伙。對於那些劣等生物來說，得到這枚物品是一個至高無上的榮譽，這是邁入堡壘上層，進入奈法利安的精英軍團─黑手軍團的第一步。找到這麼一件東西，把它交給我，讓我來檢查一下它，然後我就會知道下一步該怎麼做了。', `MaleText_loc7`='Tienes que encontrar a alguien, entre los desdichados que habitan la parte baja de esta ciudadela, que haya recibido el sello de ascensión no Adornado. Es un gran honor para uno de estos seres inferiores recibir este objeto, ya que constituye el primer paso para entrar en la parte superior de la ciudadela y convertirse en uno de los guardias de élite de Nefarian, la legión Puño Negro. Encuentra ese objeto y devuélvemelo para que pueda examinar sus propiedades. Entonces sabré cómo proceder una vez que haya terminado mi análisis del sello.' WHERE `ID`=5584;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최선을 다하겠습니다, 밸란.', `MaleText_loc4`='我会尽力做到最好的，维埃兰。', `MaleText_loc5`='我會盡力做到最好的，維埃蘭。', `MaleText_loc7`='Haré todo lo que pueda, Vaelan.', `FemaleText_loc1`='최선을 다하겠습니다, 밸란.', `FemaleText_loc4`='我会尽力做到最好的，维埃兰。', `FemaleText_loc5`='我會盡力做到最好的，維埃蘭。', `FemaleText_loc7`='Haré todo lo que pueda, Vaelan.' WHERE `ID`=5585;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주의해야 합니다, 필멸자여. 이 요새의 하급 부족이 그런 물건을 가지고 있는 경우는 매우 드물기에 수십 년 동안 탐색을 해야 할지도 모릅니다. 인정사정 볼 것 없이 이 야수들을 처치하는 것이 좋을 것입니다.', `MaleText_loc4`='你要知道，这样的物品是非常罕见的。你可能需要进行数年的搜索才能找到一枚印章。我建议你对这些邪恶的生物毫不留情，把他们全都杀掉。', `MaleText_loc5`='你要知道，這樣的物品是非常罕見的。你可能需要進行數年的搜索才能找到一枚印章。我建議你對這些邪惡的生物毫不留情，把他們全都殺掉。', `MaleText_loc7`='Te lo advierto, mortal, es excepcionalmente raro que uno de los clanes inferiores de esta ciudadela posea este elemento. Tu búsqueda podría llevar décadas. Recomiendo que destruyas a esta bestias impunemente.' WHERE `ID`=5586;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇게 하겠습니다.', `MaleText_loc4`='我们会完成这个任务的。', `MaleText_loc5`='我們會完成這個任務的。', `MaleText_loc7`='Se hará.', `FemaleText_loc1`='그렇게 하겠습니다.', `FemaleText_loc4`='我们会完成这个任务的。', `FemaleText_loc5`='我們會完成這個任務的。', `FemaleText_loc7`='Se hará.' WHERE `ID`=5587;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 인장을 더 가까이 가져오지 마십시오, 필멸자여. 여기서도 그 인장을 감싸고 있는 악을 느낄 수 있군요.$B$B제가 조사를 하는 동안 잠깐만 기다리십시오. 꽉 쥐고 계셔야 합니다.', `MaleText_loc4`='别再靠近我了，$n。我已经可以感觉到印章中流淌着的邪恶力量了。$B$B给我一点时间，让我来检查检查——你要紧紧地握住它。', `MaleText_loc5`='別再靠近我了，$n。我已經可以感覺到徽印中流淌著的邪惡力量了。$B$B給我一點時間，讓我來檢查檢查─你要緊緊地握住它。', `MaleText_loc7`='No te acerques más, mortal. Puedo sentir el mal en el sello desde donde estoy.$B$BDame un momento para identificar el objeto... sujétalo con fuerza.' WHERE `ID`=5588;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇게 하지요, 밸란.', `MaleText_loc4`='如你所愿，维埃兰。', `MaleText_loc5`='如你所願，維埃蘭。', `MaleText_loc7`='Como desees, Vaelan.', `FemaleText_loc1`='그렇게 하지요, 밸란.', `FemaleText_loc4`='如你所愿，维埃兰。', `FemaleText_loc5`='如你所願，維埃蘭。', `FemaleText_loc7`='Como desees, Vaelan.' WHERE `ID`=5589;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법 보호막이 %s|1을;를; 둘러쌉니다.', `MaleText_loc4`='%s被反魔法屏障包围着。', `MaleText_loc5`='%s被一道反魔法屏障包圍著。', `MaleText_loc7`='%s está rodeado por una barrera antimagia.' WHERE `ID`=5590;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 어떻게 해야 할지 알아냈습니다. 자, 준비는 되셨습니까?', `MaleText_loc4`='我已经看清了你要走的路。你准备好了吗？', `MaleText_loc5`='我已經看清了你要走的路。你準備好了嗎?', `MaleText_loc7`='He vislumbrado el camino que debes seguir. ¿Estás $gpreparado:preparada;?' WHERE `ID`=5591;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가십시오, 필멸자여. 당신은 제 지식을 알 자격이 없습니다.', `MaleText_loc4`='走开，凡人！你不配获得我的知识。', `MaleText_loc5`='走開，凡人!你不配獲得我的知識。', `MaleText_loc7`='Márchate, mortal. No eres $gmerecedor:merecedora; de mis conocimientos.' WHERE `ID`=5592;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아. 돌아왔군요, $r|1이여;여;!', `MaleText_loc4`='啊，$r，你回来了！', `MaleText_loc5`='啊，$r，你回來了!', `MaleText_loc7`='Ah, $r, ¡has vuelto!' WHERE `ID`=5593;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s의 기세가 약해진 듯합니다.', `MaleText_loc4`='%s的意志开始动摇。', `MaleText_loc5`='%s的意志動搖了。', `MaleText_loc7`='La voluntad de %s se tambalea.' WHERE `ID`=5594;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 너를 따라잡았구나, 네파리안. 다른 위상들의 힘에서 벗어날 수 있을 줄 알았더냐?', `MaleText_loc4`='我终于能够与你抗衡了，奈法利安。你认为自己能躲过其他守护巨龙的力量吗？', `MaleText_loc5`='我終於能夠與你抗衡了，奈法利安。你認為自己能躲過其他守護巨龍的力量嗎?', `MaleText_loc7`='Por fin te he alcanzado, Nefarian. Seguro que nunca pensaste que escaparías al poder de los otros Aspectos.' WHERE `ID`=5595;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만! 이제 장난은 끝났다!', `MaleText_loc4`='够了！娱乐时间已经过了！', `MaleText_loc5`='夠了!娛樂時間已經過了!', `MaleText_loc7`='¡Ya es suficiente! ¡Se acabaron los juegos!' WHERE `ID`=5596;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련을 받고 싶습니다.', `MaleText_loc4`='我要接受训练。', `MaleText_loc5`='我要接受訓練。', `MaleText_loc7`='Me gustaría recibir instrucción.', `FemaleText_loc1`='훈련을 받고 싶습니다.', `FemaleText_loc4`='我要接受训练。', `FemaleText_loc5`='我要接受訓練。', `FemaleText_loc7`='Me gustaría recibir instrucción.' WHERE `ID`=5597;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도끼를 쓸 줄 모른다니 그게 말이나 되는 소리인가?', `MaleText_loc4`='你说自己不知道如何使用斧头是什么意思？', `MaleText_loc5`='你說自己不知道如何使用斧頭是什麼意思?', `MaleText_loc7`='¿Qué quieres decir con que no sabes usar un hacha?' WHERE `ID`=5598;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크기는 작지만 제대로 쓸 줄만 알면 치명적인 상처를 남기지. 내가 찔러 넣어야 할 곳이 어디 어디인지 제대로 한번 보여 주겠네.', `MaleText_loc4`='它很小，但是如果你明白自己在做什么的话，还是能使它发挥效用的。让我来向你说明该怎么用它。', `MaleText_loc5`='它很小，但是如果你明白自己在做什麼的話，還是能使它發揮效用的。讓我來向你說明該怎麼用它。', `MaleText_loc7`='Es pequeña pero cumple con su cometido si sabes utilizarla. Deja que te enseñe los lugares donde golpear.' WHERE `ID`=5599;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날을 이렇게 쥐고 던지십시오. 손목을 한 번만 꺾어 주면 저녁 식사감 정도는 눈 깜짝 할 사이에 잡을 수 있습니다.', `MaleText_loc4`='像这样拿着刀，然后掷出去。把手腕放松一些，只需要一两下，你就可以把你的午饭搞定了。', `MaleText_loc5`='像這樣拿著刀，然後擲出去。把手腕放鬆一些，只需要一兩下，你就可以把你的午飯搞定了。', `MaleText_loc7`='Coge una hoja como esta y lánzala. Gira la muñeca así, otro giro y la lanzas.' WHERE `ID`=5600;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='활은 우리 아버지의 아버지, 그 할아버지 세대 이전부터 사용해온 것이라네. 단단하고 흔들림이 없는 데다 적을 재빨리 제압할 수 있지. 고블린이나 타우렌들이 그렇게 좋아하는 총이 무슨 필요가 있단 말인가.', `FemaleText_loc4`='我们很早以前就开始使用弓箭了。它们坚实可靠，能迅速杀死敌人。我不认为我们该使用地精和牛头人们爱不释手的火枪。', `FemaleText_loc5`='我們很早以前就開始使用弓箭了。它們堅實可靠，能迅速殺死敵人。我不認為我們該使用哥布林和牛頭人們愛不釋手的火槍。', `FemaleText_loc7`='Hemos usado arcos desde antes del tiempo de mi padre. Son resistentes y seguros y derriban a nuestros enemigos rápidamente. No veo ninguna razón para usar las armas de fuego a las que son tan aficionados los goblins y los tauren.' WHERE `ID`=5601;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='창 쓰는 법을 배우고 싶어서 왔군요?', `FemaleText_loc4`='你是来学习的吗，伙计？', `FemaleText_loc5`='你是來學習的嗎，夥計?', `FemaleText_loc7`='¿A aprender vienes, colega?' WHERE `ID`=5602;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오크의 주먹은 무기 그 자체라네. 거기에 칼날이나 쇳덩어리를 달면 얼마나 더 강해 지겠나? 주먹으로 평원의 늑대를 길들이고 적이 입은 방어구를 박살낼 수도 있지.', `FemaleText_loc4`='兽人的拳头已经是一种强大的武器了，所以为什么不给它们再加上用坚硬的钢铁做成的刀刃或是大头钉呢？我以前用来驯服野狼的拳头现在足以用来击碎敌人的装甲。', `FemaleText_loc5`='獸人的拳頭已經是一種強大的武器了，所以為什麼不給它們再加上用堅硬的鋼鐵做成的刀刃或是大頭釘呢?我以前用來馴服野狼的拳頭現在足以用來擊碎敵人的裝甲。', `FemaleText_loc7`='Los puños de un orco ya son una poderosa arma, así que... ¿por qué no añadirles espadas o remaches de duro acero? Así para despedazar la armadura de mis enemigos puedo utilizar los mismos puños que me sirven para domar los lobos de las llanuras.' WHERE `ID`=5603;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 단순한 지팡이로 쓰인다고 생각하고 있겠지요?! 흐흐... 전 모두 그런 착각에 빠져 있기를 바라고 있습니다.', `MaleText_loc4`='你也许会认为这是我的手杖。这是我正希望你所想的。', `MaleText_loc5`='你也許會認為這是我的手杖。這是我正希望你所想的。', `MaleText_loc7`='¿Crees que esto ser bastón? Quiero que solo eso tú pensar.' WHERE `ID`=5604;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='활이란 좋은 친구와 같이 믿을 수 있는 물건입니다. 활을 잘 보살펴 주면 활도 당신을 잘 보살펴 줄 겁니다.', `MaleText_loc4`='弓很重要,我的朋友。你只需照顾它，而它就会照顾你。', `MaleText_loc5`='弓很重要,我的朋友。你只需照顧它，而它就會照顧你。', `MaleText_loc7`='Un arco ser cosa muy grande, amigo. Solo cuidarlo tienes y él cuidar de ti.' WHERE `ID`=5605;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도끼를 제대로 사용하고 싶으면 적당한 인사도 해줘야 하는 법이지. 농담이 아냐. 날 한번 따라해 보게. "안녕! 내 작은 친구야? 오늘은 뭘 베고 싶니?!"', `MaleText_loc4`='这不是个游戏，伙计。你想使用斧子，就必须说那句话。说什么？“跟我的小朋友打个招呼。”', `MaleText_loc5`='這不是個遊戲，老兄。你想用斧頭，就必須說那句話。跟著我說:「跟我的小朋友打個招呼。」', `MaleText_loc7`='Esto no ser juego. Quieres usar hacha, di palabras. ¿Sí? "Di hola a mi coleguita."' WHERE `ID`=5606;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='활은 그다지 쓸 만하지가 않지만 고블린들이 만드는 이 소총은 사냥할 때 아주 편리하죠. 화약 냄새는 영 고약하지만 말입니다.', `MaleText_loc4`='弓箭的用途向来不大，但是地精制造的这些来复枪在狩猎时非常有用。虽然我仍然无法习惯这气味。', `MaleText_loc5`='弓箭的用途向來不大，但是哥布林製造的這些來福槍在狩獵時非常有用。雖然我仍然無法習慣這氣味。', `MaleText_loc7`='Nunca le he dado mucho uso a un arco, pero estos rifles que hacen los goblins son muy buenos para cazar. Aunque aún no me he acostumbrado al olor.' WHERE `ID`=5607;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 어둠해안에 악마의 이끼가 얼마만큼 퍼져 있는지 조사하러 왔소. 텔드랏실과 일대에 남은 타락의 기운이 퍼져 가고 있어서 세나리온 의회 드루이드들과 모든 나이트 엘프들이 심히 걱정하고 있지.$B$B이 사태의 원인을 알아내고 수습하는 게 내 목표라오.', `MaleText_loc4`='$n，我已经查明魔苔在整个黑海岸的影响有多么的猖獗。泰达希尔和我们周围大地的堕落的确引起了塞纳里奥议会德鲁伊以及所有的暗夜精灵的关注。$B$B我的目标就是查出为什么会发生这样的事并将其制止。', `MaleText_loc5`='$n，我已經查明魔苔在整個黑海岸的影響有多麼的猖獗。泰達希爾和我們周圍大地的墮落的確引起了塞納里奧議會德魯伊以及所有的夜精靈的關注。$B$B我的目標就是查出為什麼會發生這樣的事並將其制止。', `MaleText_loc7`='$n, tengo que averiguar cómo han proliferado los efectos del musgovil en toda la Costa Oscura. La corrupción queda en Teldrassil y en las tierras que nos rodean es muy importante para los druidas del Círculo Cenarion y para todos los elfos de la noche.$B$BMi objetivo es averiguar por qué ha ocurrido todo esto y ponerle punto y final.' WHERE `ID`=5608;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='큼직한 나무 막대기 끝에 추를 달아 놓은 것처럼 단순하게 보이겠지만 타우렌의 힘으로 휘두르면 돌로 된 벽도 무너뜨릴 수 있소.', `MaleText_loc4`='这看起来或许很简单，无非是一根前端极重的大棍。但是当强壮的牛头人挥动起来时，这根棍子可以击穿石墙。', `MaleText_loc5`='這看起來或許很簡單，無非是一根前端極重的大棍。但是當強壯的牛頭人揮動起來時，這根棍子可以擊穿石牆。', `MaleText_loc7`='Puede parecer muy simple, un palo largo con un peso enorme en un extremo. Pero movido por la fuerza de un tauren, este palo puede romper muros de piedra.' WHERE `ID`=5609;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지팡이가 그냥 막대기일 뿐이라고요? 이 "막대기"로 어떤 일을 할 수 있는지 당장 보여 드릴까요?', `MaleText_loc4`='只是一根手杖吗？你想让我看看一根手杖能做什么？', `MaleText_loc5`='只是一根手杖嗎?你想讓我看看一根手杖能做什麼?', `MaleText_loc7`='¿Un simple palo? ¿Quieres que te enseñe todo lo que puede hacer "un simple palo"?' WHERE `ID`=5610;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 검은손부대 공포술사를 소환하기 시작합니다!', `FemaleText_loc4`='%s开始召唤黑手恐法师！', `FemaleText_loc5`='%s開始召喚一個黑手織懼者!', `FemaleText_loc7`='%s comienza a invocar a un tejedor de tinieblas Puño Negro.' WHERE `ID`=5611;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 자신을 도울 검은손부대 공포술사를 소환합니다!', `FemaleText_loc4`='%s召唤出黑手恐法师来帮助他！', `FemaleText_loc5`='%s召喚了一個黑手織懼者來幫他的忙!', `FemaleText_loc7`='%s invoca a un tejedor de tinieblas Puño Negro para que le ayude.' WHERE `ID`=5612;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 검은손부대 고참병을 소환하기 시작합니다!', `FemaleText_loc4`='%s开始召唤黑手老兵！', `FemaleText_loc5`='%s開始召喚一個黑手老兵!', `FemaleText_loc7`='%s comienza a invocar a un veterano Puño Negro.' WHERE `ID`=5613;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 자신을 도울 검은손부대 고참병을 소환합니다!', `FemaleText_loc4`='%s召唤出黑手老兵来帮助他！', `FemaleText_loc5`='%s召喚了一個黑手老兵來幫他的忙!', `FemaleText_loc7`='%s invoca a un veterano Puño Negro para que le ayude.' WHERE `ID`=5614;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가슴 방어구에 마법부여를 해주시겠다고요? 고마운 말씀이지만 별로 관심없는데요... 아, 마법부여를 배울 곳을 찾고 계시다고요? 이런 당황스러울 데가! 배우셔야죠. 그... 누구지... 탈라단! 그래요. 장인의 정원에 있는 탈라단을 찾아가 보세요!', `MaleText_loc4`='过奖了，但我真的不感兴趣……什么？你想知道在哪儿能学习附魔知识吗？哦，真令人为难！呃，你应该……我想你应该……去找那个，嗯……塔兰丹！对，去工匠区找塔兰丹！', `MaleText_loc5`='過獎了，但我真的不感興趣...什麼?你想知道在哪兒能學習附魔知識嗎?哦，真令人為難!呃，你應該...我想你應該...去找那個，嗯...塔蘭丹!對，去工匠區找塔蘭丹!', `MaleText_loc7`='Estoy halagado, pero la verdad es que no me interesa... ¿Qué? ¿Quieres saber dónde aprendí a encantar? ¡Oh, qué embarazoso! Veamos, deberías... Seguro que podrías... ir a ver... um... ¡Taladan! Sí, ¡visita a Taladan en el Bancal del Artesano!', `FemaleText_loc1`='가슴 방어구에 마법부여를 해주시겠다고요? 고마운 말씀이지만 별로 관심없는데요... 아, 마법부여를 배울 곳을 찾고 계시다고요? 이런 당황스러울 데가! 배우셔야죠. 그... 누구지... 탈라단! 그래요. 장인의 정원에 있는 탈라단을 찾아가 보세요!', `FemaleText_loc4`='过奖了，但我真的不感兴趣……什么？你想知道在哪儿能学习附魔知识吗？哦，真令人为难！呃，你应该……我想你应该……去找那个，嗯……塔兰丹！对，去工匠区找塔兰丹！', `FemaleText_loc5`='過獎了，但我真的不感興趣...什麼?你想知道在哪兒能學習附魔知識嗎?哦，真令人為難!呃，你應該...我想你應該...去找那個，嗯...塔蘭丹!對，去工匠區找塔蘭丹!', `FemaleText_loc7`='Estoy halagada, pero la verdad es que no me interesa... ¿Qué? ¿Quieres saber dónde aprendí a encantar? ¡Oh, qué embarazoso! Veamos, deberías... Seguro que podrías... ir a ver... um... ¡Taladan! Sí, ¡visita a Taladan en el Bancal del Artesano!' WHERE `ID`=5615;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐야? 아무도 내 야영지에서 펄볼그를 정화하지는 못해! 이 사브라시스의 분노를 맛봐라!', `MaleText_loc4`='什么……没有人可以在我的营地里净化熊怪！准备体验萨巴克希斯的愤怒吧！', `MaleText_loc5`='什麼...沒有人可以在我的營地裡淨化熊怪!準備體驗薩巴克希斯的憤怒吧!', `MaleText_loc7`='Qué demo... ¡nadie se atreve a purificar a un fúrbolg en MI campamento! ¡Enfréntate a la ira de Xabraxxis!' WHERE `ID`=5616;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 정화된 음식의 맛있는 냄새에 이끌려 나옵니다.', `MaleText_loc4`='%s被已净化的食物的香味所吸引。', `MaleText_loc5`='%s被已淨化的食物的香味所吸引。', `MaleText_loc7`='%s se siente atraído por el dulce aroma de la comida purificada.' WHERE `ID`=5617;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 음식을 게걸스레 먹어치우기 시작합니다.', `MaleText_loc4`='%s开始狼吞虎咽地进食。', `MaleText_loc5`='%s開始狼吞虎嚥地進食。', `MaleText_loc7`='%s comienza a devorar ávidamente la comida.' WHERE `ID`=5618;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밴클리프가 너희놈들 잡아오랬어.', `MaleText_loc4`='范克里夫出高价悬赏你！', `MaleText_loc5`='范克里夫會為你的腦袋出個好價錢的!', `MaleText_loc7`='¡VanCleef paga mucho por sus cabezas!' WHERE `ID`=5619;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겁낼 것 없어. 이리 와 보게.', `MaleText_loc4`='没什么可怕的。来吧。', `MaleText_loc5`='沒什麼可怕的。來吧。', `MaleText_loc7`='No hay nada que temer. Ven.', `FemaleText_loc1`='겁낼 것 없어. 이리 와 보게.', `FemaleText_loc4`='没什么可怕的。来吧。', `FemaleText_loc5`='沒什麼可怕的。來吧。', `FemaleText_loc7`='No hay nada que temer. Ven.' WHERE `ID`=5621;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 이제 죽었군!', `MaleText_loc4`='我们玩完了！', `MaleText_loc5`='我們玩完了!', `MaleText_loc7`='¡Estamos perdidos!', `FemaleText_loc1`='우린 이제 죽었군!', `FemaleText_loc4`='我们玩完了！', `FemaleText_loc5`='我們玩完了!', `FemaleText_loc7`='¡Estamos perdidos!' WHERE `ID`=5622;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 아는 기술은 전부 인간을 죽이는 것 빼고는 전혀 쓸모가 없지. 다른 무엇도 아니고, 인간 말이야. 이 검들은 오직 인간의 생명을 끝내기 위해 개발된 거야. 아름답지 않나?', `MaleText_loc4`='武器就是用来杀人的，它们被制造出来的目的就是杀人。它们都很漂亮，不是吗？', `MaleText_loc5`='武器就是用來殺人的，它們被製造出來的目的就是殺人。它們都很漂亮，不是嗎?', `MaleText_loc7`='La única arma que conozco así no tiene más fin que matar a alguien. No a algo, a alguien. Estas espadas fueron ideadas para poner fin a las vidas de los hombres. ¿No son hermosas?' WHERE `ID`=5623;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='진짜 쓸만한 무기라면, 적들이 가까이 오지 못하도록 하는 동시에 조각을 낼 수 있어야 하지. 딱 한 가지 단점이 있다면, 자루가 너무 길어 손에 따끈한 피를 묻혀볼 수가 없다는 거지.', `FemaleText_loc4`='让你的敌人走投无路，同时将他们撕成碎末。唯一的问题是我手拿着东西而无法大开杀戒。', `FemaleText_loc5`='讓你的敵人走投無路，同時將他們撕成碎末。唯一的問題是我手拿著東西而無法大開殺戒。', `FemaleText_loc7`='Mantén a raya a tus enemigos y hazlos filetes. El único problema es que con este bastón tan largo no me mancho de sangre las manos.' WHERE `ID`=5624;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자고로 무기란 재빠르고 정확해야죠. 힘줄 하나씩, 동맥 하나씩 자르면서 즐길 수 있게 말이에요. 아무리 작은 칼이라도 완벽한 살생 무기로 사용하는 법을 보여 드리죠.', `FemaleText_loc4`='敏捷而自信。这里切断一条肌腱，那里割断一根动脉。我要教你如何把任何一把刀子变成一种完美的杀人机器。', `FemaleText_loc5`='敏捷而自信。這裡切斷一條肌腱，那裡割斷一根動脈。我要教你如何把任何一把刀子變成一種完美的殺人機器。', `FemaleText_loc7`='Rápido y seguro. Corta un tendón por aquí, saja una arteria por allá. Puedo enseñarte a convertir cualquier cuchillo en una máquina perfecta para matar.' WHERE `ID`=5625;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='활을 다시 장전하는데 시간이 좀 오래 걸리긴 하지만, 멀찌감치 떨어져서 싸움을 거는 데는 안성맞춤이지.', `MaleText_loc4`='长时间重装弹药需要时间来适应，但是没有什么比战争更锻炼人了。', `MaleText_loc5`='長時間重裝彈藥需要時間來適應，但是沒有什麼比戰爭更鍛鍊人了。', `MaleText_loc7`='Lleva algo de tiempo acostumbrarse al tiempo de recarga, pero no hay nada mejor para empezar un combate.' WHERE `ID`=5626;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오시게, $c|1이여;여;. 굿스티치 형제가 도와 드릴 일이라도 있는지?', `MaleText_loc4`='欢迎来到我的商店，$c。古斯提兄弟能为你做什么吗？', `MaleText_loc5`='歡迎來到我的商店，$c。古斯提兄弟能為你做什麼嗎?', `MaleText_loc7`='$GBienvenido:Bienvenida; a mi tienda, $c. ¿Qué pueden hacer por ti los hermanos Cortefino?' WHERE `ID`=5627;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 내가 제일 좋아하는 손님이로군. 당신은 꽤 강한 흑마법사 같네. 만나서 반가우이. 혹시 내가 해 줄 수 있는 일이라도 있으면 말만 하게.$B$B우리 형제들은 당신과 같은 부류의 이들이 다음 세대를 이끌어 줄 것이라 믿고 있지. 그렇게나 큰 힘을 가진 이라면 불타는 군단이 무릎을 꿇는 것도 시간문제일 뿐이야.$B$B아주 부럽소이다.', `MaleText_loc4`='啊，我最喜爱的顾客之一。你似乎是个有能力的术士，$n。很高兴认识你。要是我能帮上什么忙，请尽管开口。$B$B我和我的兄弟都认为你这样的人才能领导我们进入新纪元。一个拥有力量……和控制力的人……让军团臣服于你只是时间问题。$B$B我有些羡慕你了。', `MaleText_loc5`='啊，我最喜愛的顧客之一。你似乎是個有能力的術士，$n。很高興認識你。要是我能幫上什麼忙，請儘管開口。$B$B我和我的兄弟都認為你這樣的人才能領導我們進入新紀元。一個擁有力量...和控制力的人...讓軍團臣服於你只是時間問題。$B$B我有些羡慕你了。', `MaleText_loc7`='Ah, uno de mis clientes favoritos. Pareces ser un brujo de cierto poder, $n. Encantado de verte. Si hay algo que pueda hacer por ti, por favor, pídelo.$B$BMi hermano y yo tenemos la sensación de que será uno de tu clase el que nos conduzca a la siguiente era de grandeza. Alguien con tu poder... con tu control... es solo una cuestión de tiempo que la Legión se someta a tu voluntad.$B$BSiento algo de envidia.' WHERE `ID`=5628;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스에 대한 소식은 어찌 됐느냐, 렌드?', `MaleText_loc4`='联盟怎么样，雷德？', `MaleText_loc5`='聯盟怎麼樣，雷德?', `MaleText_loc7`='¿Qué se sabe de la Alianza, Rend?' WHERE `ID`=5629;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들이 윈저라는 인간을 풀어준 것 같습니다. 오닉시아도 곧 발각될 것입니다.', `MaleText_loc4`='阁下，他们释放了温德索尔。奥妮克希亚的伪装被揭穿也是迟早的事情了。', `MaleText_loc5`='閣下，他們釋放了溫德索爾。奧妮克希亞的偽裝被揭穿也是遲早的事情了。', `MaleText_loc7`='Han liberado al humano, Windsor, señor. No pasará mucho hasta que descubran a Onyxia.' WHERE `ID`=5630;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇다면 더 이상 시간을 낭비할 수 없다. 오색용군단은 준비되었느냐?', `MaleText_loc4`='我们不能再浪费时间了。多彩龙人准备好了吗？', `MaleText_loc5`='我們不能再浪費時間了。炫彩龍軍團準備好了嗎?', `MaleText_loc7`='Entonces no podemos perder más tiempo. ¿Está listo el Vuelo Cromático?' WHERE `ID`=5631;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음 무리가 곧 부화합니다. 이번 주말이면 공격을 감행할 수 있을 것입니다.', `MaleText_loc4`='阁下，下一个时间点就要来临。我们已经准备在周末发动攻击。', `MaleText_loc5`='閣下，下一個時間點就要來臨。我們已經準備在週末發動攻擊。', `MaleText_loc7`='Se espera que la siguiente nidada salga muy pronto del cascarón, señor. Estaremos listos para lanzar los ataques a final de semana.' WHERE `ID`=5632;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='단검을 던져, 한 치의 오차도 없이 목표물을 명중시키고 싶나요? 아니면 양손 검의 힘을 이용해 곰의 뼈라도 으스러뜨릴 수 있는 방법을 배우시겠습니까? 당신이 검술의 달인이 되고 싶다면, 둘 다 가르쳐줄 수도 있어요. 여러 가지 상황에 아주 유용하겠죠.', `FemaleText_loc4`='我能教你使用短刃的绝招或双手武器威力巨大的劈砍招式。或者我们疯狂些，我两样都教给你，这样当情况有变时就能派得上用场。', `FemaleText_loc5`='我能教你使用短刃的絕招或雙手武器威力巨大的劈砍招式。或者我們瘋狂些，我兩樣都教給你，這樣當情況有變時就能派得上用場。', `FemaleText_loc7`='Puedo enseñarte la delicadeza de una espada corta y el poder que emana que un arma descomunal de dos manos. O podemos hacer una locura y te enseño las dos cosas, podría serte útil si algún día cambia tu situación.' WHERE `ID`=5633;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='기다란 창을 젓가락처럼 자유자재로 다루는 창의 달인이 되고 싶으신가요? 그렇다면, 제가 환상적인 기술을 가르쳐 드리죠. 단, 돈은 좀 쓰셔야 할 겁니다.', `FemaleText_loc4`='我肯定会教你挥舞长柄武器的艺术，但你要交费。', `FemaleText_loc5`='我肯定會教你揮舞長柄武器的藝術，但你要交費。', `FemaleText_loc7`='Claro que puedo enseñarte el delicado arte de blandir un arma de asta, pero te costará algo.' WHERE `ID`=5634;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 됐군. 내 군단에게 먹일 보잘것없는 벌레들이 제시간에 도착한 것 같구나. 어서 오너라, 나약한 생명체들아!', `MaleText_loc4`='很好……看起来好像这些爱管闲事的小人物来得正是时候。欢迎，凡人！！', `MaleText_loc5`='很好...看起來好像這些愛管閒事的小人物來得正是時候。歡迎，凡人!!', `MaleText_loc7`='Excelente... es como si esos entrometidos insectos vinieran justo a tiempo para servir de comida a mi legión. ¡Bienvenidos, mortales!' WHERE `ID`=5635;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='석궁에 화살을 다시 꽂는 데 시간이 좀 걸리는 건 사실입니다. 하지만, 이놈만 있으면 아무리 튼튼한 방패에도 주먹만한 구멍을 내놓을 수 있답니다.', `MaleText_loc4`='要重新装弹显然要花费较长时间，但是有了这个家伙，我可以在任何护甲上弄一个拳头大的洞来。', `MaleText_loc5`='要重新裝彈顯然要花費較長時間，但是有了這個傢伙，我可以在任何護甲上弄一個拳頭大的洞來。', `MaleText_loc7`='Claro que la recarga es larga pero este juguete puede hacer un agujero tan gordo como mi puño en cualquier armadura.' WHERE `ID`=5636;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='농부들이 지팡이를 들고 전문 훈련을 받은 병사들을 막아내는 걸 본 적 있어요. 힘과 솜씨가 있는 자가 지팡이를 올바르게 사용하면 엄청난 힘을 발휘할 수도 있으니... 함부로 무시하지 마세요.', `FemaleText_loc4`='我看过拿着棍棒的农夫抵挡训练有素的士兵。绝不要低估正确挥舞棍棒所需要的力量和技巧。', `FemaleText_loc5`='我看過拿著棍棒的農夫抵擋訓練有素的士兵。絕不要低估正確揮舞棍棒所需要的力量和技巧。', `FemaleText_loc7`='He visto granjeros armados con bastones ofrecer resistencia a Soldados entrenados. No subestimes nunca el poder y las habilidades que se obtienen si se sabe blandir uno de estos.' WHERE `ID`=5637;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 싸움 한번 잘할 것 같이 생겼다고요? 하긴 부부 싸움도 지팡이 한 번만 휘두르면 끝이 나긴 해요.', `FemaleText_loc4`='如果你认为我很棒，那你该看看我的丈夫如何打斗。', `FemaleText_loc5`='如果你認為我很棒，那你該看看我的丈夫如何打鬥。', `FemaleText_loc7`='Si crees que soy buena deberías ver cómo combate mi marido.' WHERE `ID`=5638;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 돌아서서 이쪽을 봅니다.', `MaleText_loc4`='%s转过来面对着你。', `MaleText_loc5`='%s轉過來面對著你。', `MaleText_loc7`='%s se gira para mirarte.' WHERE `ID`=5639;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피 한 방울도 남김없이 먹어 치워라, 아이들아. 놈들의 영혼을 잡아먹어라!', `MaleText_loc4`='我的孩子，让他们的鲜血在地板上一滴也不要留下了。享受他们的灵魂大餐吧！', `MaleText_loc5`='我的孩子，讓他們的鮮血在地板上一滴也不要留下了。享受他們的靈魂大餐吧!', `MaleText_loc7`='No dejéis ni una sola gota de su sangre en el suelo, hijos míos. ¡Devorad sus almas!' WHERE `ID`=5640;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋은 망치 하나만 손에 쥐고 있어도 세상이 더 안전해 보이는 법이지. 커다란 쇳덩이를 손에 쥐고 있다고 생각해보게. 아무리 강한 적이라도 물리칠 수 있을 것 같은 생각이 들지.', `MaleText_loc4`='你手中的一把锤头让这个世界感觉安全了许多。有一块巨大的金属抓在你的手中，你感觉能够对付即使是最强大的敌人。', `MaleText_loc5`='你手中的一把錘頭讓這個世界感覺安全了許多。有一塊巨大的金屬抓在你的手中，你感覺能夠對付即使是最強大的敵人。', `MaleText_loc7`='Con un buen martillo en las manos el mundo parece mucho más seguro. Teniendo un gran trozo de metal en el puño es como si pudieras enfrentarte al más poderoso de tus enemigos.' WHERE `ID`=5641;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신에게 적을 도끼로 나무 베듯 무찌르는 법을 가르쳐 주겠소.', `MaleText_loc4`='我将教你如何杀敌，让他们像小树苗一样倒下。', `MaleText_loc5`='我將教你如何殺敵，讓他們像小樹苗一樣倒下。', `MaleText_loc7`='Te enseñaré a despedazar a tus enemigos como si fueran retoños.' WHERE `ID`=5642;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='드넓은 황야의 땅에서 굶주린 늑대가 초당 10미터의 속도로 달리고 있었어요. 친구들과 오른쪽 눈을 쏘느냐?, 왼쪽 눈을 쏘느냐? 내기를 하며 놀았지요. 그래요, 젊은 $C. 난 그 정도라고요.', `FemaleText_loc4`='地平线上的猎犬以每秒三十英尺的速度移动。现在唯一的问题是，右眼还是左眼。那就对了$g小伙子:姑娘;，我就是那么棒。', `FemaleText_loc5`='地平線上的獵犬以每秒三十英尺的速度移動。現在唯一的問題是，右眼還是左眼。那就對了$g小夥子:姑娘;，我就是那麼棒。', `FemaleText_loc7`='Diviso a un can en el horizonte moviéndose a treinta pies por segundo. La única pregunta es: ojo derecho o izquierdo. Tienes razón $gmuchacho:muchacha;, soy muy buena.' WHERE `ID`=5643;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이거 보이세요? 바로 제 최고급 드워프제 붐스틱이에요! 네, 바로 카즈 모단의 아이언포지에서 만든 거랍니다. 소매가는 199실버 하고도 99코퍼 정도지요. 호두나무 개머리판에 단단한 토륨으로 만들었고 방아쇠는 아주 섬세하게 제작했죠.', `FemaleText_loc4`='看到这个了吗？这是我的钓竿！这就对了，这个甜美的宝贝在卡兹莫丹的铁炉堡制造。零售价一百零九块金币，九十五块铜币。它的柄是胡桃木做的，钍合金的钢铁做的竿身，还有一个灵敏的浮标。', `FemaleText_loc5`='看到這個了嗎?這是我的釣竿!這就對了，這個甜美的寶貝在卡茲莫丹的鐵爐堡製造。零售價一百零九塊金幣，九十五塊銅幣。它的柄是胡桃木做的，瑟銀的鋼鐵做的竿身，還有一個敏感的扳機。', `FemaleText_loc7`='¿Veis esto! ¡Esto es mi escoba de fuego! Lo mejor que puede ofrecer los enanos. Esta maravilla ha sido fabricada en Forjaz, Khaz Modan. Su precio de venta es de ciento nueve monedas de oro y noventa y cinco de cobre. La culata es de nogal y los cañones recortados de torio, tiene un gatillo de pelo ya lo ven.' WHERE `ID`=5644;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 나는 맨주먹으로 싸우는 걸 무척이나 즐기는 편인데, 때로는 상대의 머리가 토륨 방패보다도 더 단단하단 말이오. 이럴 때는 무기의 도움이 약간 필요하지.', `MaleText_loc4`='啊，我想好好干一架，但是有时你的敌人的骨头比瑟银护甲还坚硬。这时你就需要一些帮助了。', `MaleText_loc5`='啊，我想好好幹一架，但是有時你的敵人的骨頭比瑟銀護甲還堅硬。這時你就需要一些幫助了。', `MaleText_loc7`='Aj, me encanta una buena pelea, pero a veces tu enemigo tiene el cráneo más duro que un escudo de torio. En esas ocasiones siempre viene bien algo de ayuda.' WHERE `ID`=5645;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오색용군단이 이 침입자들과 상대할 테니 우린 더 중요한 얘기를 하도록 하지.', `MaleText_loc4`='多彩龙人会对付这些入侵者的。我们谈谈更为紧迫的事情吧。', `MaleText_loc5`='炫彩龍人會對付這些入侵者的。我們談談更為緊迫的事情吧。', `MaleText_loc7`='El Vuelo Cromático se encargará de los intrusos. Vamos a hablar de cosas más urgentes.' WHERE `ID`=5646;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요즘엔 뭐든지 현대화가 중요해요. 석궁에도 크랭크에 지렛대까지 있으면 오우거만큼 세게 활을 잡아당길 수 있지요.', `MaleText_loc4`='现代化是关键。利用手柄和杠杆，你只需用食人魔拉弓的力量就能使这个小孩弹出去。', `MaleText_loc5`='現代化是關鍵。利用手柄和槓桿，你只需用巨魔拉弓的力量就能使這個小孩彈出去。', `MaleText_loc7`='Modernización es la clave. Con una manivela y una palanca puedes hacer que este juguete dispare igual de fuerte que un ogro con un arco normal.' WHERE `ID`=5647;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 가요, $n. 백사장 야영지에 갈 준비가 다 됐어요.', `MaleText_loc4`='走吧$n，前往白沙岗哨。', `MaleText_loc5`='走吧$n，前往白沙崗哨。', `MaleText_loc7`='Vamos, $n. Estoy listo para llegar al Campamento del Tramo Blanco.' WHERE `ID`=5648;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='샥, 샥, 푹! 며칠 전에 맞닥뜨린 녀석, 배 닻으로 만든 양손 식칼을 들고 있었을지 모르지만 제 식사용 칼로 몇 군데 잘 찔러 주니까 그대로 넘어가더군요!', `FemaleText_loc4`='嗵，嗖，哐！他或许有一把用船锚改装的巨大的双手刀，但当我用餐刀巧妙地切了几刀后，他就是那个要倒下去的人！', `FemaleText_loc5`='嗡，嘰，碰!他或許有一把用船錨改裝的巨大的雙手斧，但當我用餐刀巧妙地切了幾刀後，他就是那個要倒下去的人!', `FemaleText_loc7`='¡Zum, zing y BAM! Puede que se hubiera hecho un machete enorme de dos manos con un ancla de barco, pero en cuanto le di unos golpes bien colocados con mi cuchillo de mesa, ¡fue él el que se rompió!' WHERE `ID`=5649;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='소매에 잘 감춰 둔 칼 하나로 당신이나 적의 생사가 결정 날 수가 있어요.', `FemaleText_loc4`='袖子里藏着刀片意味着要么你躺在小巷里死去，要么你的对手卧在他自己的鲜血里。', `FemaleText_loc5`='袖子裡藏著刀片意味著要麼你躺在小巷裡死去，要麼你的對手臥在他自己的鮮血裡。', `FemaleText_loc7`='Una espada oculta bajo la manga puede suponer la diferencia entre yacer muerto en un callejón o dejar a tu oponente tumbado sobre su propia sangre.' WHERE `ID`=5650;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='작은 단검이라도 세심히 잘만 다루면 방패라도 뚫을 수 있는 법이오.', `MaleText_loc4`='钝刀穿透了盾牌。', `MaleText_loc5`='鈍刀穿透了盾牌。', `MaleText_loc7`='El lento filo penetra en el escudo.' WHERE `ID`=5651;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼을 잘 쓰는 비결이라... 적에게 필살의 일격을 가할 때까지 잘 감춰 두는 거요.', `MaleText_loc4`='刀的秘密在于，在你挥刀之前，其刀锋是隐藏的。', `MaleText_loc5`='刀的秘密在於，在你揮刀之前，其刀鋒是隱藏的。', `MaleText_loc7`='El secreto del cuchillo es dejarlo escondido hasta que llega el momento de golpear.' WHERE `ID`=5652;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 나이트 엘프 대대로 전해 내려오는 창술을 배우고 싶으십니까? 그럼 첫 수업부터 시작하겠습니다.', `FemaleText_loc4`='那么，你想多学些我们精灵族的武器？我们开始上第一节课吧。', `FemaleText_loc5`='那麼，你想多學些我們精靈族的武器?我們開始上第一節課吧。', `FemaleText_loc7`='¿Así que quieres aprender más sobre el armamento de los elfos? Que comience la primera lección.' WHERE `ID`=5653;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기는 좀 낯익은 곳이군요. 계속해서 동쪽으로 가면 아마... 으앗! 와이번의 공격이에요!', `MaleText_loc4`='这看上去很眼熟，要是我们一直朝东走的话，我想我们能做到的。啊！双足飞龙，备战吧！', `MaleText_loc5`='這看起來很眼熟，要是我們一直朝東走的話，我想我們能做到的。啊!雙足翼龍，備戰吧!', `MaleText_loc7`='Esto ya me resulta familiar. Si seguimos hacia el Este creo que podemos... ¡Ahh! ¡Dracoleón al ataque!' WHERE `ID`=5654;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마치 주먹이 하나 더 달린 것만큼 무기가 손에 착 달라붙었으면 합니까? 그렇다면 제가 한번 시범을 보여 드리지요.', `MaleText_loc4`='你想要一种武器可以作为你的拳头的延伸？好的，我相信可以给你看看某样东西。', `MaleText_loc5`='你想要一種武器可以作為你的拳頭的延伸?好的，我相信可以給你看看某樣東西。', `MaleText_loc7`='¿Quieres un arma que sea como una extensión de tu propia mano? Sí, creo que puedo enseñarte algo.' WHERE `ID`=5655;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='많은 이들이 배우러 오는 타이거 스트라이크니 하는 것은 잘 모르겠지만, 호랑이 발톱을 사용하는 법이라면 가르쳐 줄 수 있소.', `MaleText_loc4`='我不太清楚老虎眼睛的用途，但是我可以教你如何使用老虎爪子。', `MaleText_loc5`='我不太清楚老虎眼睛的用途，但是我可以教你如何使用老虎爪子。', `MaleText_loc7`='No sé nada de ese Ojo del tigre del que algunos hablan pero puedo enseñarte a utilizar las garras del tigre.' WHERE `ID`=5656;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='많은 이들이 지팡이는 시대에 좀 뒤떨어지는 무기라고 생각하는데, 그러면 제 지팡이에 맞서 자기들의 그 잘난 무기를 한번 시험해 보라죠.', `FemaleText_loc4`='许多人认为法杖是一种下等的武器。我向所有这么认为的人发出挑战，让他们挑战我的法杖以证明他们的实力。', `FemaleText_loc5`='許多人認為法杖是一種下等的武器。我向所有這麼認為的人發出挑戰，讓他們挑戰我的法杖以證明他們的實力。', `FemaleText_loc7`='Quizás consideres al bastón un arma menor. Reto a todo el que piense así a probar su fuerza contra la de mi bastón.' WHERE `ID`=5657;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='활을 사용할 줄 아는 건 사냥꾼뿐만이 아닌 누구에게나 유용하지. 재빨리, 그리고 조용히 치면 사냥감을 눈도 깜빡이기 전에 죽일 수 있는 거요.', `MaleText_loc4`='不只是对猎人，掌握弓箭的使用技能对每个人来说都相当有用。你可以在猎物眨眼之前快速，悄无声息地出击……还没等反应过来，它们就已经死了。', `MaleText_loc5`='弓箭的使用技能對每個人來說都相當有用，不只有對獵人而已。你可以快速，悄無聲息地出擊...在獵物反應過來之前，它們已經死了。', `MaleText_loc7`='El manejo del arco es muy útil para todo el mundo, no solo para los cazadores. Si puedes golpear en silencio, con rapidez y antes de que tu presa pueda pestañear... la puedes dar por muerta.' WHERE `ID`=5658;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 저는 이 세계의 많은 지식을 알고 있습니다. 강력한 힘을 지닌 부적을 만드는 법도 안답니다.', `FemaleText_loc4`='啊，$r……我了解很多关于这个世界的知识，以及如何制造巨大能量的符咒的方法。', `FemaleText_loc5`='啊，$r...我瞭解很多關於這個世界的知識，以及如何製造巨大能量的符咒的方法。', `FemaleText_loc7`='Ah, $r... Poseo gran saber del mundo y de hacer talismanes con gran poder.' WHERE `ID`=5659;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼마나 많은 수의 적들을 내 근처에 오기도 전에 칼을 던져 쓰러뜨렸나 모른다오. 비결은 능숙한 손목 놀림에 있지.', `MaleText_loc4`='好几次我仅用刀就吓退了试图靠近袭击我的敌人。秘密就在于手腕的动作。', `MaleText_loc5`='好幾次我僅用刀就嚇退了試圖靠近襲擊我的敵人。秘密就在於手腕的動作。', `MaleText_loc7`='Muchas veces mis espadas han derribado a mi objetivo antes incluso de que pudiera acercarse. El secreto está en el golpe de muñeca.' WHERE `ID`=5660;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마우아리는 자네가 왜 나를 찾아왔는지 알고 있네...$B$B내게 에코를 갖고 오면 자네를 위해 부적으로 만들어 주지.', `FemaleText_loc4`='玛艾里知道你为什么找她……$B$B带给我你找到的魂精，我就会为你转换它。', `FemaleText_loc5`='瑪艾里知道你為什麼找她...$b$b帶給我你找到的魂精，我就會為你轉換它。', `FemaleText_loc7`='Mau''ari sabe por qué la buscas...$B$BDame el E''ko que tú encontrar, transformarlo para ti puedo.' WHERE `ID`=5661;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마우아리의 부적은 어떻게 사용합니까?', `MaleText_loc4`='我要如何使用玛艾里的容器？', `MaleText_loc5`='我要如何使用瑪艾里的容器?', `MaleText_loc7`='¿Cómo utilizo el Alijo de Mau''ari?', `FemaleText_loc1`='마우아리의 부적은 어떻게 사용합니까?', `FemaleText_loc4`='我要如何使用玛艾里的容器？', `FemaleText_loc5`='我要如何使用瑪艾里的容器?', `FemaleText_loc7`='¿Cómo utilizo el Alijo de Mau''ari?' WHERE `ID`=5662;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋았어... 그러면 내 아이들이 이 나약한 녀석들을 찢어 놓는 모습을 구경하자고.', `MaleText_loc4`='妙极了……让我的孩子们将这些凡人撕成碎片吧。', `MaleText_loc5`='妙極了...讓我的孩子們將這些凡人撕成碎片吧。', `MaleText_loc7`='Fantássstico... Vamos a ver cómo despedazan mis hijos a esos mortales.' WHERE `ID`=5663;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='냉기의 숨결을 써, 이 바보 녀석!', `MaleText_loc4`='使用冰冻喷吐，你这蠢货！', `MaleText_loc5`='使用冰凍噴吐，你這蠢貨!', `MaleText_loc7`='¡Utilizad el aliento helado, imbécil!' WHERE `ID`=5664;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어리석은 것들... 부상당한 녀석을 죽여라!', `MaleText_loc4`='蠢货……杀死穿那件衣服的人！', `MaleText_loc5`='蠢貨...殺死穿那件衣服的人!', `MaleText_loc7`='Idiotassss... ¡Matad al del vestido!' WHERE `ID`=5665;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='믿을 수가 없군!', `MaleText_loc4`='难以想象！', `MaleText_loc5`='難以想像!', `MaleText_loc7`='¡Increíble!' WHERE `ID`=5666;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 직접 나서면 너희의 가죽으로 장화를 만들어 버리겠다. 어서 저 녀석들을 없애란 말이야!', `MaleText_loc4`='孩子，别推我的手！我将用你的兽皮装饰我的靴子。', `MaleText_loc5`='孩子，別推我的手!我將用你的獸皮裝飾我的靴子。', `MaleText_loc7`='¡No me obliguen a hacer lo que no quiero, pequeños! Utilizaré sus pellejos para forrarme las botas.' WHERE `ID`=5667;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 헛수고일 뿐이야. 아무도 우리를 막진 못한다!', `MaleText_loc4`='你的努力都是白费心机。没有什么会阻止我们的！', `MaleText_loc5`='你的努力都是白費心機。沒有什麼會阻止我們的!', `MaleText_loc7`='Tus esfuerzos serán inútiles. ¡Nadie se pondrá en nuestro camino!' WHERE `ID`=5668;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실수에 대한 대가로 영원한 화장실 청소형을 내리겠노라!', `MaleText_loc4`='你将为自己的失败受到惩罚，永远在这儿清扫粪便！', `MaleText_loc5`='你將為自己的失敗受到懲罰，永遠在這兒清掃糞便!', `MaleText_loc7`='¡Te prometo una eternidad condenado a limpiar estiércol por ese fallo!' WHERE `ID`=5669;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나약한 생명체여, 내 너에게 저주를 내리리라!', `MaleText_loc4`='诅咒你，凡人。', `MaleText_loc5`='詛咒你，凡人。', `MaleText_loc7`='Maldito seas mortal.' WHERE `ID`=5670;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='치유사를 집중 공격하란 말이다!', `MaleText_loc4`='集中攻击那个医疗者！', `MaleText_loc5`='集中攻擊那個醫療者!', `MaleText_loc7`='¡Concentren sus ataques en el sanador!' WHERE `ID`=5671;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님, 저도 같이 싸우도록 해주십시오! 맨손으로 녀석들의 뼈를 으스러뜨려 놓겠나이다!', `MaleText_loc4`='阁下，让我参战吧！我将赤手空拳地把他们的脊椎撕碎！', `MaleText_loc5`='塞爾，讓我參戰吧!我將赤手空拳地把他們的脊椎撕碎!', `MaleText_loc7`='¡Señor, déjeme unirme a la lucha! ¡Les partiré la espalda con mis propias manos!' WHERE `ID`=5672;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말도 안 돼!', `MaleText_loc4`='这不可能！', `MaleText_loc5`='不可能!', `MaleText_loc7`='¡Imposible!' WHERE `ID`=5673;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기회가 있을 때 도망 쳐라, 필멸의 생명체여. 내가 나서면 빨리 죽게되길 빌게 될 테니까...', `MaleText_loc4`='趁你们还有机会的时候，赶快逃走吧，凡人。如果我进入竞技场，你们就会祈求速死的。', `MaleText_loc5`='趁你還有機會快逃吧，人類。如果我進入競技場，你們就會祈求速死的。', `MaleText_loc7`='Huid mientras podáis, mortales. Imploraréis una muerte rápida si entro en la arena.' WHERE `ID`=5674;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오직 죽음만이 줄 수 있는 안식이란 어떤 것인지 알게 될 것이다...', `MaleText_loc4`='你会了解只有死亡才是唯一的避难所……', `MaleText_loc5`='你會瞭解只有死亡才是唯一的避難所...', `MaleText_loc7`='Aprenderás del santuario que solo la muerte puede ofrecer...' WHERE `ID`=5675;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 직접 나서서 네놈들을 처치해야겠구나.', `MaleText_loc4`='似乎我不得不插手这件事，亲自来解决你。', `MaleText_loc5`='似乎我不得不插手這件事，親自來解決你。', `MaleText_loc7`='Parece que tendré que tomar cartas en el asunto y cuidar de ti yo mismo.' WHERE `ID`=5676;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 사지를 뜯어 흠씬 두들겨 패 주마!', `MaleText_loc4`='我要撕裂你，用你的肢体打败你！', `MaleText_loc5`='我要撕裂你，用你的肢體打敗你!', `MaleText_loc7`='¡Te arrancaré los brazos y los utilizaré para golpearte hasta que te sometas!' WHERE `ID`=5677;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더러운 것들!', `MaleText_loc4`='污染者！', `MaleText_loc5`='污染者!', `MaleText_loc7`='¡Rapiñadores!' WHERE `ID`=5678;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 이상은 못 참겠다!', `MaleText_loc4`='我再也不能忍受啦！', `MaleText_loc5`='我再也不能忍受啦!', `MaleText_loc7`='¡No puedo soportarlo más!' WHERE `ID`=5679;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빈센트! 너와 너의 보잘것없는 부하들도 키린 토의 거지 같은 것들처럼 내 아들들을 물리치는 데는 실패하고 말 것이다.', `MaleText_loc4`='文森特！你和你可怜的家族跟肯瑞托那些贫穷的幸存者一样，是不可能打败我和我儿子的。', `MaleText_loc5`='文森!你和你可憐的家族跟祈倫托那些貧窮的倖存者一樣，是不可能打敗我和我兒子的。', `MaleText_loc7`='¡Vincent! Ni tú ni los de tu pelaje tendréis más éxito aniquilándonos a mí y a mis hijos que aquellos miserables vestigios del Kirin Tor.' WHERE `ID`=5680;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너의 칼과 우리의 적에 대한 지식을 가지고 내 주인님을 섬기지 않겠다면 어쩔 수가 없군...', `MaleText_loc4`='如果你不愿为我的主人服务，不愿提供敌人的消息的话……', `MaleText_loc5`='如果你不願為我的主人服務，不願提供敵人的消息的話...', `MaleText_loc7`='Si no sirvieras a mi maestro con tu espada y con tu saber sobre sus enemigos...' WHERE `ID`=5681;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너의 불타는 시체는 내 영역에 침범하는 어리석은 자들이 어떻게 되는지를 보여주는 계기가 될 것이다!', `MaleText_loc4`='你腐烂的尸体将会成为我的奴仆，让别人知道如果有哪个蠢货胆敢入侵我的地盘，他会有什么样的后果！', `MaleText_loc5`='你腐爛的屍體將會成為我的奴僕，讓別人知道如果有哪個蠢貨膽敢入侵我的地盤，他會有什麼樣的後果!', `MaleText_loc7`='¡Tus mohosos restos ME servirán como testimonio de lo que le ocurre a quien es tan estúpido como para adentrarse en mis dominios!' WHERE `ID`=5682;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말로 고맙습니다. 여기서부터는 혼자서도 백사장 야영지로 돌아갈 수 있겠어요. 참, 잊지 말고 모테가 파이어메인과 얘기를 나눠보세요. 제가 집으로 돌아갔다고 꼭 전해주셔야 해요.', `MaleText_loc4`='非常感谢你……从这里我能找到回白沙岗哨的路。记得跟莫特加·火鬃谈谈，也许你能阻止他送我回家。', `MaleText_loc5`='非常感謝你...從這裡我能找到回白沙崗哨的路。記得跟莫特加·火鬃談談，也許你能阻止他送我回家。', `MaleText_loc7`='Mil gracias... Puedo encontrar el camino de vuelta al Campamento del Tramo Blanco. Asegúrate de hablar con Motega Pirocabello; quizás puedas evitar que me envíe a casa.' WHERE `ID`=5683;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야영지에서 과일을 훔치려다 들키고 말았습니다. %s|1이;가; 공격합니다!', `MaleText_loc4`='%s发现你在破坏营地的水果储藏，开始攻击你！', `MaleText_loc5`='%s發現你在破壞營地儲藏的水果並開始攻擊你!', `MaleText_loc7`='%s te observa manipulando las reservas de fruta del campamento y te ataca.' WHERE `ID`=5684;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곡식 도둑을 잡으려고 %s|1이;가; 통나무집에서 뛰쳐나옵니다!', `MaleText_loc4`='%s从木屋中出来就发现你在粮仓捣鬼！', `MaleText_loc5`='%s從木屋中出來就發現你在糧倉搗鬼!', `MaleText_loc7`='%s emerge del cobertizo y te sorprende manipulando las reservas de grano.' WHERE `ID`=5685;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 왼쪽으로 보이는 칼림도어의 땅이 점점 더 타락하고 뒤틀리고 있어요. 그곳에서 서식하는 생물들은 아주 흉포하니 발길을 조심하셔야 해요.', `FemaleText_loc4`='越来越多的卡利姆多的生物正开始变得疯狂，而栖息其中的小动物并不友善。你走路时要多加小心。', `FemaleText_loc5`='越來越多的卡林多的生物正開始變得瘋狂，而棲息其中的小動物並不友善。你走路時要多加小心。', `FemaleText_loc7`='Cada vez más terreno de Kalimdor se está convirtiendo en el extraño paisaje que ves a nuestra izquierda, y los bichos que habitan en él NO son muy amistosos. Vigila tus pasos.' WHERE `ID`=5686;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런... 오우거들이로군. 이 못난 것들을 잊고 있었네요. 돌아서 갈 지름길은 없으니, 싸울 준비를 단단히 하세요. 정신 바짝 차리고요!', `FemaleText_loc4`='该死的……兽人。我忘记这些小丑了。跟他们打交道可不容易，所以做好战斗准备。赶快！', `FemaleText_loc5`='該死的...獸人。我忘記這些小丑了。跟他們打交道可不容易，所以做好戰鬥準備。趕快!', `FemaleText_loc7`='Maldita sea... ogros. Me olvidé de esos bufones. No es fácil esquivarlos, así que prepárate para luchar. ¡Estate $gatento:atenta;!' WHERE `ID`=5687;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이랴, 다단가! 행진이야! 가자!', `FemaleText_loc4`='快点达丹加！女孩快跑，快跑！', `FemaleText_loc5`='快點達丹加!女孩快跑，快跑!', `FemaleText_loc7`='¡Venga Dadanga! ¡Camina chica, camina!' WHERE `ID`=5688;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저기가 가젯잔이에요! 이제 고향 땅에 돌아온 겁니다!', `FemaleText_loc4`='就在那里——加基森！我们现在处于冲刺阶段！', `FemaleText_loc5`='就在那裡─加基森!我們現在處於衝刺階段!', `FemaleText_loc7`='Ahí está... ¡Gadgetzan! ¡Ya estamos en el último tramo!' WHERE `ID`=5689;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='드디어 도착했군요. 감사합니다, $n! 당신이 도와 주지 않았으면, 우리는 지금쯤 과도하게 성장한 도마뱀들의 먹이가 되어 버렸을 거예요!', `FemaleText_loc4`='我们终于到了，多谢你，$n！没有你的帮助，我们没准已经被那些巨大的蜥蜴当作午餐了！', `FemaleText_loc5`='我們終於到了，多謝你，$n!沒有你的幫助，我們沒准已經被那些巨大的蜥蜴當作午餐了!', `FemaleText_loc7`='Por fin hemos llegado, ¡gracias $n! ¡Sin tu ayuda habríamos sido el almuerzo de algún lagarto hiperdesarrollado!' WHERE `ID`=5690;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='꽤 길고 힘든 여정이었죠?! 이제 보급품을 싣고 운고로 분화구로 다시 갈 수 있을 것 같아요. 가면 바깥에서 들여 온 화물도 좀 내릴 수 있을 테고...', `FemaleText_loc4`='货物非常多，但现在我可以再装载一些返回环形山了。我还可以卸载一不需要的部分货物。', `FemaleText_loc5`='貨物非常多，但現在我可以再裝載一些返回環形山了。我還可以卸載一不需要的部分貨物。', `FemaleText_loc7`='¡Vaya recorrido!, pero ya puedo cargar los suministros para el viaje de vuelta al Cráter. También debería poder descargar algo de este cargamento exótico.' WHERE `ID`=5691;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='조심해! 적이다!', `FemaleText_loc4`='当心，敌人来了！', `FemaleText_loc5`='當心，敵人來了!', `FemaleText_loc7`='¡Cuidado, ya vienen!' WHERE `ID`=5692;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='도와 주세요! $n|1을;를; 처치해야 해요.', `FemaleText_loc4`='我需要$n的一些帮助！', `FemaleText_loc5`='我需要$n的一些幫助!', `FemaleText_loc7`='¡Necesitaré algo de ayuda con esto, $n!' WHERE `ID`=5693;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 그래, 맞아. 다단가는 연기를 싫어하지. 하지만 곁에서 냄새를 맡아 보니 목욕하는 것도 싫어하는 모양이던데?', `MaleText_loc4`='是的是的，我知道达丹加不喜欢烟。但从它身上的气味来看，达丹加好像还不喜欢洗澡。', `MaleText_loc5`='是的是的，我知道達丹加不喜歡煙。但從它身上的氣味來看，達丹加好像還不喜歡洗澡。', `MaleText_loc7`='Sí, sí, ya sé que a Dadanga no le gusta el humo. Y por el olor parece que a Dadanga tampoco del gusta bañarse.' WHERE `ID`=5694;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혹시 이 근처에서 페트라나 다단가를 못 보셨나요?', `MaleText_loc4`='你在附近见过皮塔斯或达丹加吗？', `MaleText_loc5`='你在附近見過皮塔斯或達丹加嗎?', `MaleText_loc7`='¿Has visto por aquí a Petra o a Dadanga?', `FemaleText_loc1`='혹시 이 근처에서 페트라나 다단가를 못 보셨나요?', `FemaleText_loc4`='你在附近见过皮塔斯或达丹加吗？', `FemaleText_loc5`='你在附近見過皮塔斯或達丹加嗎?', `FemaleText_loc7`='¿Has visto por aquí a Petra o a Dadanga?' WHERE `ID`=5695;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들은 우리에게 줄 보급품을 가지러 좀 전에 가젯잔으로 떠났어. 솔직히 말하자면, 다단가의 가방에 기어들어갈 기회를 얻을 수 있었다면 최소 손가락 네 개라도 줬을 텐데... 이 저주받은 곳을 떠날 수 있게 말이야.', `MaleText_loc4`='他们动身去了加基森，帮我们取回一些物资。坦白地说，我原本有很多机会可以爬进达丹加的包裹中，离开这片不毛之地。', `MaleText_loc5`='他們動身去了加基森，幫我們取回一些物資。坦白地說，我原本有很多機會可以爬進達丹加的包裹中，離開這片不毛之地。', `MaleText_loc7`='Partieron hacia Gadgetzan hace tiempo para traernos provisiones. Francamente, habría dado cuatro dedos por haberme podido meter en uno de los paquetes de Dadanga y abandonar este lugar olvidado.' WHERE `ID`=5696;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에코란 건 뭡니까?', `MaleText_loc4`='魂精是什么?', `MaleText_loc5`='魂精是什麼?', `MaleText_loc7`='¿Qué es E''ko?', `FemaleText_loc1`='에코란 건 뭡니까?', `FemaleText_loc4`='魂精是什么?', `FemaleText_loc5`='魂精是什麼?', `FemaleText_loc7`='¿Qué es E''ko?' WHERE `ID`=5698;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마우아리의 부적은 많은 비밀을 간직하고 있지... 그 부적을 만드는 데 사용한 얼음 조각의 빛나는 표면은 반사 성질이 있어, 다른 존재들의 힘을 자기 자신에게 반사해 빨아들일 수 있네.$B$B부적을 소지하고 있으면 자신이 싸워 이긴 야수들의 영혼 에너지인 에코를 모을 수 있을 거야. 에코를 찾으면 이 마우아리에게 가져오게.', `FemaleText_loc4`='玛艾里的容器有很多秘密……用来制作它的碎片是可以反光的，你可以使用它的反光面从其它事物身上吸取能量然后反射到自己身上。$B$B将护符放在你的背包里可以让你聚集魂精，也就是与你战斗的野兽的灵魂力量。一旦你找到魂精，你把它带给玛艾里。', `FemaleText_loc5`='瑪艾里的容器有很多秘密...用來製作它的裂片是可以反光的，你可以使用它的反光面從其他事物身上吸取能量然後反射到自己身上。$B$B將符咒放在你的背包裡可以讓你聚集魂精，也就是與你戰鬥的野獸的靈魂力量。一旦你找到魂精，你把它帶給瑪艾里。', `FemaleText_loc7`='El Alijo de Mau''ari guarda grandes secretos... Los fragmentos que se utilizaron para crearlo son reflectantes y puedes utilizar su brillante superficie para absorber el poder de otras cosas y reflejarlo sobre ti mismo.$B$BSi guardas el talismán en tu inventario podrás recoger E''ko, el poder espiritual de las bestias que combatas. Cuando encuentres E''ko dáselo a Mau''ari.' WHERE `ID`=5699;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='에코란 모든 생물이 가지고 있는 힘을 말하지. 자네에게 만들어 준 부적을 몸에 지니고 있으면 그 힘을 얻을 수 있네.$B$B난 에코를 부적으로 변화시키는 주문을 알지.$B$B그러면 마우아리의 부적을 사용해 그 힘을 자신에게 반사시킬 수 있어.$B$B어때? 한번 해 보는 게. 에코를 이 마우아리에게 가져오면 한번 재미있게 놀아볼 수 있을걸.', `FemaleText_loc4`='魂精是每个生物都有的能量。我为你做的护符使你能以物理形态来抓到它。$B$B我知道一个可以转换你发现的魂精的咒语，并把它转换成魂能。$B$B你然后可以得到玛艾里的容器，并使用它把魂能的能量转换到自己身上。$B$B来吧，试一下。把玛艾里的魂精带来我们开心一下。', `FemaleText_loc5`='魂精是每個生物都有的能量。我為你做的符咒使你能以物理形態來抓到它。$B$B我知道一個可以轉換你發現的魂精的咒語，並把它轉換成魂能。$B$B你然後可以得到瑪艾里的容器，並使用它把魂能的能量轉換到自己身上。$B$B來吧，試一下。把瑪艾里的魂精帶來我們開心一下。', `FemaleText_loc7`='E''ko es el poder que poseen todas las criaturas. El talismán que he hecho para ti te permitirá capturarlo en una manifestación física.$B$BConozco un encantamiento que puede transformar el E''ko que encuentres y convertirlo en Juju.$B$BEntonces podrás coger el Alijo de Mau''ari y utilizarlo para reflejar el poder del Juju sobre ti $gmismo:misma;.$B$BVenga, dale una oportunidad. Trae el E''ko a Mau''ari y nos divertiremos.' WHERE `ID`=5700;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='운고로에 비교해도 손색없을 정도로 가젯잔은 아주 멋진 곳이지만, 우리가 보급품을 가져다 주기를 기다리는 이들이 있어서 말입니다. 다단가와 나는 준비가 끝났으니 당신도 준비가 끝나는 대로 출발하도록 해요.', `FemaleText_loc4`='虽然加基森跟安戈洛相比还不错，我有些伙计还指望我们给他们带来些补给。如果你准备好出发了，那达丹加和我也是。我们上马吧！', `FemaleText_loc5`='雖然加基森跟安戈洛相比還不錯，我有些夥計還指望我們給他們帶來些補給。如果你準備好出發了，那達丹加和我也是。我們上馬吧!', `FemaleText_loc7`='Comparado con Un''Goro es tan agradable como Gadgetzan, hay mucha gente que cuenta con nosotros para que les llevemos suministros. Si tienes todo listo, Dadanga y yo también. ¡Vamos allá!' WHERE `ID`=5701;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='타나리스 사막에는 저렇게 커다란 뼈들이 널려 있습니다. 만약 우리가 저 생물이 살아 있을 때 마주쳤다면 아주 큰일이었겠죠.', `FemaleText_loc4`='塔纳利斯沙漠遍布巨大的骨头，就像我右边这个一样。我讨厌碰到那些东西。', `FemaleText_loc5`='塔納利斯沙漠遍佈巨大的骨頭，就像我右邊這個一樣。我討厭碰到那些東西。', `FemaleText_loc7`='El Desierto de Tanaris está plagado de huesos gigantes como este que tengo a mi derecha. No me hubiera gustado nada haberme cruzado con esta cosa.' WHERE `ID`=5702;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='워, 워. 다단가. 기다려!', `FemaleText_loc4`='哦，哦，停下，达丹加，我的女孩。', `FemaleText_loc5`='哦，哦，停下，達丹加，我的女孩。', `FemaleText_loc7`='Guau, guau... tranquila chica Dadanga.' WHERE `ID`=5703;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 콧바람을 불더니 정지합니다.', `MaleText_loc4`='%s停下来时大声地喷着鼻息。', `MaleText_loc5`='%s在她停下來時候哼了一聲。', `MaleText_loc7`='%s resopla profundamente cuando hace un alto.' WHERE `ID`=5704;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭔가... 이상하군요. 이 사막은 너무 낯설어 보이는데요! 여기를 지나가는 건 아주 큰 실수일 것 같습니다.', `FemaleText_loc4`='这看起来不太……对头。沙漠实在是太陌生了！从这里通过可能是一个巨大的错误。', `FemaleText_loc5`='這看起來不太...對頭。沙漠實在是太陌生了!從這裡通過可能是一個巨大的錯誤。', `FemaleText_loc7`='Esto no tiene buen aspecto. ¡Mira qué extraño es el desierto! Atravesar esto sería un terrible error.' WHERE `ID`=5705;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭐야... 뭔가 우리한테 기어 오고 있는데요? 저... 적이에요!', `FemaleText_loc4`='什么……那些向我们爬过来的东西是什么？我们……我们正将遭受袭击！', `FemaleText_loc5`='什麼...那些向我們爬過來的東西是什麼?我們...我們正將遭受襲擊!', `FemaleText_loc7`='Qué demo... ¿qué son esas cosas que avanzan hacia nosotros? Nos... ¡nos están atacando!' WHERE `ID`=5706;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전혀 도움이 되지 않는 생물들이로군요. 피해서 가야겠어요. 저기 바위가 있는 남쪽으로 가도록 하죠. 그 사이로 비집고 가면서 오우거들을 피할 수 있을지도 몰라요.', `FemaleText_loc4`='那不是我所说的“和平地护卫”。我会想办法绕开这些东西。我们朝南移动，向那块岩石走去。或许我们能从中穿过去并同时避开兽人。', `FemaleText_loc5`='那不是我所說的「和平地護衛」。我會想辦法繞開這些東西。我們朝南移動，向那塊岩石走去。或許我們能從中穿過去並同時避開獸人。', `FemaleText_loc7`='Eso no ha sido precisamente cordial. Encontraré un camino para rodear a esas cosas. Vayamos hacia el Sur, hacia esa roca. Quizás podamos encontrar un escondrijo y evitar a los ogros.' WHERE `ID`=5707;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기만 지나가면 되겠군요. 이 지독한 벌레 놈들만 피해가면, 서쪽으로 운고로까지 가는 길이 열릴 거예요.', `FemaleText_loc4`='这会起作用的——继续穿越这条沟壑。一旦我们绕过这些地狱昆虫，通往安戈洛的道路就在这里正西边。', `FemaleText_loc5`='這會起作用的─繼續穿越這條溝壑。一旦我們繞過這些煉獄火昆蟲，通往安戈洛的道路就在這裡正西邊。', `FemaleText_loc7`='Esto funcionará. Sigue por este hueco. El camino a Un''Goro está directamente al oeste de aquí una vez que hayamos rodeado a esos bichos infernales.' WHERE `ID`=5708;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 말도 안 돼!!! 렌드, 이 벌레들을 해치우도록 하라.', `MaleText_loc4`='这不可能！！！雷德，解决掉这些家伙。', `MaleText_loc5`='這不可能!!!雷德，解決掉這些傢伙。', `MaleText_loc7`='¡¡NO PUEDE SER!! Rend, encárgate de esos insectos.' WHERE `ID`=5709;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나약한 생명체들이 쓰러졌다! 검은바위 부대의 새로운 시대가 도래하였느니라!', `MaleText_loc4`='凡人战败了！黑石军团的新时代即将来临！', `MaleText_loc5`='凡人戰敗了!黑石軍團的新時代即將來臨!', `MaleText_loc7`='¡Los mortales han caído! ¡Se acerca la nueva era de la legión Roca Negra!' WHERE `ID`=5710;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 비룡에서 떨어집니다!', `MaleText_loc4`='%s从他的座龙身上摔了下来！', `MaleText_loc5`='%s從他的座龍身上被打了下來!', `MaleText_loc7`='%s es derribado del draco.' WHERE `ID`=5711;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아자!', `MaleText_loc4`='呜喔！', `MaleText_loc5`='嗚喔!', `MaleText_loc7`='¡GUAU!' WHERE `ID`=5712;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이러면 확실히 일거리가 줄어들겠군.', `MaleText_loc4`='这的确能省不少力。', `MaleText_loc5`='這的確能省不少力。', `MaleText_loc7`='Me ahorrará algo de trabajo.' WHERE `ID`=5713;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저놈의 장화는 내 거다! 아무도 시체에 손대지 마!', `MaleText_loc4`='我想要这些靴子！都别碰那具尸体！', `MaleText_loc5`='我想要這些靴子!都別碰那具屍體!', `MaleText_loc7`='¡Quiero esas botas! ¡Que nadie toque el cuerpo!' WHERE `ID`=5714;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너는 그래도 운이 좋구나, 필멸의 생명체여. 네 시체는 그나마 봐 줄 만하군.', `MaleText_loc4`='你已经算幸运的了，凡人。至少你的尸体还比较完整。', `MaleText_loc5`='你已經算幸運的了，凡人。至少你的屍體還比較完整。', `MaleText_loc7`='Considérate afortunado, mortal. Al menos tu cadáver sigue estando presentable.' WHERE `ID`=5715;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시체들을 완전히 먹어 치우지는 마라, 아이들아! 나중에 후식도 먹어야 해!', `MaleText_loc4`='孩子，别把整个尸体都吃了！留着肚子吃些甜点吧！', `MaleText_loc5`='孩子，別把整個屍體都吃了!留著肚子吃些甜點吧!', `MaleText_loc7`='¡No os comáis todo el cuerpo, chicos! ¡Dejad sitio para el postre!' WHERE `ID`=5716;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='옳지!', `MaleText_loc4`='你完了！', `MaleText_loc5`='你完了!', `MaleText_loc7`='¡Servido!' WHERE `ID`=5717;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 놈들이 이길 수 있을 거라고 생각했더냐?', `MaleText_loc4`='你真的以为你还有机会？', `MaleText_loc5`='你真的以為你還有機會?', `MaleText_loc7`='¿De verdad creías que tenías alguna oportunidad?' WHERE `ID`=5718;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은손부대가 네 가죽을 장식품으로 달고 다닐 것이다!', `MaleText_loc4`='黑石军团会将你们的皮制成饰品！', `MaleText_loc5`='黑石軍團會將你們的皮製成飾品!', `MaleText_loc7`='¡La legión Puño Negro utilizará tu piel para hacerse unos bonitos complementos!' WHERE `ID`=5719;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장이 곧 너희를 처리할 것이니 각오해라!', `MaleText_loc4`='酋长会除掉你的，凡人。做好准备吧！', `MaleText_loc5`='大酋長會除掉你的，凡人。做好準備吧!', `MaleText_loc7`='El Jefe de Guerra será rápido con ustedes, mortales. ¡Prepárense!' WHERE `ID`=5720;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 전투를 기대하는 듯 왔다갔다 서성입니다.', `MaleText_loc4`='%s焦急地踱来踱去，等待着进行战斗。', `MaleText_loc5`='%s焦急地踱來踱去，等待著進行戰鬥。', `MaleText_loc7`='%s se mueve adelante y atrás anticipándose al combate.' WHERE `ID`=5721;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기꺼이 그리하겠나이다...', `MaleText_loc4`='很荣幸……', `MaleText_loc5`='很榮幸...', `MaleText_loc7`='Con placer...' WHERE `ID`=5722;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오시오, 젊은 $R 양반. 무얼 도와 드릴까요?', `MaleText_loc4`='你好，$g小伙子:姑娘;。我可以帮你什么忙吗？', `MaleText_loc5`='你好，$g小夥子:姑娘;。我可以幫你什麼忙嗎?', `MaleText_loc7`='Buenos días $gmuchacho:muchacha;. ¿Puedo ayudarte?' WHERE `ID`=5723;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련을 받고 싶단 말인가요? 저도 이제 막 배움의 길로 들어섰지만 제가 가르쳐 줄 수 있는 건 뭐든지 알려드리죠.', `MaleText_loc4`='你是来接受训练的吗？我也是刚刚开始学习这方面的知识，但是我很乐意把我所知道的教给你。', `MaleText_loc5`='你是來接受訓練的嗎?我也是剛剛開始學習這方面的知識，但是我很樂意把我所知道的教給你。', `MaleText_loc7`='¿Estás aquí para instruirte, eh? Yo mismo acabo de empezar mi instrucción, pero me gustaría enseñarte lo que puedo hacer.' WHERE `ID`=5724;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배우는 속도가 빠르시군요. 제가 따라갈 수 없을 만큼 아주 빨라요. 계속해서 훈련을 받고 싶거든 스승님을 만나 보시는 게 좋겠어요. 로트가스 스톤비어드라고 하는 분인데 아이언포지의 대용광로에서 계실 겁니다.', `MaleText_loc4`='你学得很快，$g小伙子:姑娘;，快得我已经远远跟不上你了。如果你想继续学习的话，我建议你去见见我的导师。他的名字叫洛特加斯，嗯，洛特加斯·石须。你可以在铁炉堡的大锻炉那里找到他。', `MaleText_loc5`='你學得很快，$g小夥子:姑娘;，快得我已經遠遠跟不上你了。如果你想繼續學習的話，我建議你去見見我的導師。他的名字叫洛特加斯，嗯，洛特加斯·石鬚。你可以在鐵爐堡的大鍛爐那裡找到他。', `MaleText_loc7`='Aprendes rápido $gmuchacho:muchacha;, tan rápido que no puedo seguirte el paso. Si quieres seguir tu instrucción te sugiero visitar a mi maestro. Su nombre es Rotgath, Rotgath Barbapétrea, lo encontrarás en Forjaz, en La Gran Fundición.' WHERE `ID`=5725;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 힘을 맛보라!', `MaleText_loc4`='尝尝我的力量吧！', `MaleText_loc5`='嘗嘗我的力量吧!', `MaleText_loc7`='¡Prueba mi poder!' WHERE `ID`=5726;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='응? 잡담할 시간 없어. 오늘 안으로 아버지가 시킨 일 다해야 한단 말일세.', `MaleText_loc4`='嗯？我没时间聊天，我父亲要我完成这个使命。', `MaleText_loc5`='嗯?我沒時間聊天，我父親要我完成這個使命。', `MaleText_loc7`='¿Eh? No tengo tiempo para charlas, papá quiere que termine este encargo.' WHERE `ID`=5727;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='솜씨가 좀 있어 보이는군. 몇 가지 더 배울 수 있겠어. 어디 내가 뭘 가르쳐 줄 수 있을지 한번 보지.', `MaleText_loc4`='你确实有点本事。我打赌你的技术足够让你学些东西了，我们来看看我有什么能教给你的，好吗？', `MaleText_loc5`='你確實有點本事。我打賭你的技術足夠讓你學些東西了，我們來看看我有什麼能教給你的，好嗎?', `MaleText_loc7`='¿Ya tienes algo de idea, eh? Apostaría que basta para enseñarte algunas cosas. Vamos a ver lo que puedo enseñarte, ¿de acuerdo?' WHERE `ID`=5728;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 확실히, 당신이 나보다 더 많은 걸 알게 되었군. 이제 우리 아버지와 얘기해 봐. 당신 솜씨부터 먼저 증명해 보여야겠지만, 인정만 받으면 정말로 좋은 스승이 되어 주실 거니까. 아버지 성함은 로트가스인데, 벤구스 옆에서 작업하고 계셔.', `MaleText_loc4`='你知道的比我还多，这一点很肯定。我告诉你接下来该怎么办，去和我的爸爸谈谈。他是个好的老师，但是他会要求你证明自己的实力。他的名字叫洛特加斯，你可以在本古斯的铁砧旁边找到他。', `MaleText_loc5`='你知道的比我還多，這一點很肯定。我告訴你接下來該怎麼辦，去和我的爸爸談談。他是個好的老師，但是他會要求你證明自己的實力。他的名字叫洛特加斯，你可以在本古斯的鐵砧旁邊找到他。', `MaleText_loc7`='Sabes más que yo, eso es seguro. Pero te diré algo, ve a hablar con mi padre. Te querrá poner a prueba, pero es un buen instructor. Su nombre es Rotgath, lo encontrarás junto a los yunques, trabajando el acero para el viejo Bengus.' WHERE `ID`=5729;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 당신은 나보다 솜씨가 더 좋습니다. 내 오랜 친구인 로트가스 스톤비어드를 만나 보지 않겠소? 내가 제이나의 군대에 입대하기 전에 그 친구는 아이언포지에 남아 있었습니다. 그라면 당신에게 몇 가지 가르쳐 줄 수 있을 겁니다. 아니면 최소한 당신을 가르칠 수 있는 이를 알고 있을 거고. 아직 아이언포지에 있다면 대용광로에 살고 있을 겁니다.', `MaleText_loc4`='我的朋友，你所掌握的技艺远胜于我。你为什么不去找我的老朋友洛特加斯·石须继续深造呢？我离开铁炉堡加入了吉安娜的军队，而他留了下来。我想他能教你点什么，至少他会知道谁能教你。如果他还待在铁炉堡的话，我想他一定在大锻炉附近。', `MaleText_loc5`='我的朋友，你所掌握的技藝遠勝於我。你為什麼不去找我的老朋友洛特加斯·石鬚繼續深造呢?我離開鐵爐堡加入了珍娜的軍隊，而他留了下來。我想他能教你點什麼，至少他會知道誰能教你。如果他還待在鐵爐堡的話，我想他一定在大鍛爐附近。', `MaleText_loc7`='Muy bien, $gamigo:amiga;, ya eres más hábil que yo. ¿Por qué no vas a buscar a mi viejo amigo Rotgath Barbapétrea? Estaba en Forjaz cuando partí para unirme al ejército de Jaina. Estoy seguro de que podrá enseñarte algo, o, por lo menos, sabrá de alguien que pueda hacerlo. Si sigue por ahí seguro que está en La Gran Fundición.' WHERE `ID`=5730;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에코는 어디서 찾을 수 있습니까?', `MaleText_loc4`='我该到哪里去寻找魂精？', `MaleText_loc5`='我該到哪裡去尋找魂精?', `MaleText_loc7`='¿Dónde debería buscar E''ko?', `FemaleText_loc1`='에코는 어디서 찾을 수 있습니까?', `FemaleText_loc4`='我该到哪里去寻找魂精？', `FemaleText_loc5`='我該到哪裡去尋找魂精?', `FemaleText_loc7`='¿Dónde debería buscar E''ko?' WHERE `ID`=5731;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우선 여명의 설원에 있는 생물들에게서 찾아보는 게 좋겠지.$B$B하지만 다른 곳에서도 찾을 수 있을 걸세.', `FemaleText_loc4`='从冬泉谷的生物开始应该不错。$B$B然而，或许还有别的地方你可以看看……', `FemaleText_loc5`='從冬泉谷的生物開始應該不錯。$B$B然而，或許還有別的地方你可以看看...', `FemaleText_loc7`='Las criaturas de Cuna del Invierno son una opción para empezar.$B$BPero puede haber más sitios donde mirar...' WHERE `ID`=5732;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련을 받고 싶으신가요? 당연히 도와 드릴 수 있습니다. 나도 수습 과정에 있을 뿐이지만 당신에게 가르쳐 줄 게 뭔가 있을 겁니다.', `MaleText_loc4`='当然，我可以帮你进行训练。我也只是一个新手，但是我想我还是能对你有所帮助的。', `MaleText_loc5`='當然，我可以幫你進行訓練。我也只是一個新手，但是我想我還是能對你有所幫助的。', `MaleText_loc7`='Por supuesto que puedo ayudarte con tu instrucción. No soy más que un oficial, pero seguro que puedo enseñarte algo.' WHERE `ID`=5733;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쉽게 인정하기는 싫은 사실이지만, 당신은 나보다도 솜씨가 훨씬 좋습니다. 이제 내가 가르쳐줄 수 있는 건 보잘것없는 것들뿐입니다. 더 큰 배움을 얻으려면 스톰윈드에 있는 테룸 딥포지라는 드워프를 찾아가 보십시오. 드워프 지구에 있을 겁니다.', `MaleText_loc4`='我不会轻易承认这一点的，不过你的确是个比我出色得多的铁匠。如果你想要学习更多高级的技能，我建议你去暴风城的矮人区找一个名叫瑟鲁姆·深炉的矮人。', `MaleText_loc5`='我不會輕易承認這一點的，不過你的確是個比我出色得多的鐵匠。如果你想要學習更多高級的技能，我建議你去暴風城的矮人區找一個名叫瑟魯姆·深爐的矮人。', `MaleText_loc7`='Me cuesta reconocerlo, pero eres mucho mejor $gherrero:herrera; que yo. Si quieres aprender algo más que mis exiguas enseñanzas te sugiero buscar a un enano llamado Therum Forjahonda en Ventormenta. Lo encontrarás en el Distrito de los Enanos.' WHERE `ID`=5734;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미안하지만, 지금 호숫골에 있는 베르너 오스구드에게 가져갈 편자를 만드는 중이라 좀 바쁘오.', `MaleText_loc4`='很抱歉，我现在有些忙，我要为湖畔镇的弗纳·奥斯古打造马蹄。', `MaleText_loc5`='很抱歉，我現在有些忙，我要為湖畔鎮的弗納·奧斯古打造馬蹄。', `MaleText_loc7`='Lo siento, estoy bastante ocupado ahora mismo haciendo herraduras para Verner Osbien de la Comarca del Lago.' WHERE `ID`=5735;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 지금 수다나 떨고 있게 생겼소?', `MaleText_loc4`='我看上去像是有时间和你闲谈的样子吗？', `MaleText_loc5`='我看起來像是有時間和你閒談的樣子嗎?', `MaleText_loc7`='¿Te parece que me sobra el tiempo para darle a la sinhueso?' WHERE `ID`=5736;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='솜씨가 나쁘지는 않지만 몇 가지 쓸 만한 요령을 더 가르쳐 주겠소.', `MaleText_loc4`='你还不坏，但让我耍耍几个小把戏，你可能会觉得很方便实用的。', `MaleText_loc5`='你還不壞，但讓我耍耍幾個小把戲，你可能會覺得很方便實用的。', `MaleText_loc7`='No está mal, pero déjame enseñarte algunos trucos que encontrarás útiles.' WHERE `ID`=5737;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 분명 나보다 솜씨가 더 좋은 대장장이요. 내가 그렇게 말한 사실을 다른 이에게 말한다면야 당연히 부인할 테지만 말이오. 가서 테룸 딥포지와 얘기를 나눠 보시오. 당신에게 뭔가 더 가르칠 수 있는 이가 있다면 바로 그 친구니 말이야.', `MaleText_loc4`='你已经是一个比我好得多的铁匠，那是肯定的。尽管如果你告诉其他人这点我会否认我曾说过。你该去找瑟鲁姆·深炉谈谈。如果有人能教你，那就是他。', `MaleText_loc5`='你已經是一個比我好得多的鐵匠，那是肯定的。儘管如果你告訴其他人這點我會否認我曾說過。你該去找瑟魯姆·深爐談談。如果有人能教你，那就是他。', `MaleText_loc7`='Un herrero mucho mejor que yo, eso está claro. Pero lo negaré si lo vas diciendo por ahí. Deberías hablar con Therum Forjahonda. Si hay alguien que pueda seguir instruyéndote, ese es él.' WHERE `ID`=5738;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 싫어하는 물오리 얘기를 한마디라도 꺼내면 평생 누워서 살도록 해 주겠네.', `MaleText_loc4`='我听过对水禽的评价，据说它们可以通过一个管子一样的东西吃东西。', `MaleText_loc5`='我若聽到任何有關水禽的意見, 你將來就必須用管子進食。', `MaleText_loc7`='Si escucho la más mínima palabra sobre aves acuáticas, necesitarás un tubo metido en la garganta para poder comer.' WHERE `ID`=5739;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모루에다 망치만 휘두른다고 대장장이는 아니지. 누가 보고 비웃기 전에 그 망치를 이리 주게. 내가 제대로 가르쳐 줄 테니까.', `MaleText_loc4`='仅仅会挥动铁锤是无法成为铁匠的。把铁锤给我，在你让大家感到窘迫之前让我教教你好了。', `MaleText_loc5`='僅僅會揮動鐵錘是無法成為鐵匠的。把鐵錘給我，在你讓大家感到窘迫之前讓我教教你好了。', `MaleText_loc7`='Aporrear el yunque con un martillo no te convierte en $gherrero:herrera;. Dame eso y déjame enseñarte algo antes de que nos abochornes a todos.' WHERE `ID`=5740;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상당히 늘었군. 스날에게 가서 얘기를 해 보게. 사루의 슬하에서 수련을 받으러 오그리마로 갔으니, 전사 지구에 있는 불타는 모루 부근에서 찾을 수 있을 거야. 참, 그 친구 분명 당신을 시험하려 들 테니 준비 단단히 하는 게 좋을 걸세.', `MaleText_loc4`='还行。去跟斯纳尔谈谈，他刚前往奥格瑞玛向萨鲁求学。去萨鲁的铁匠铺附近的战士区找他吧。他会对你进行测试，你最好做好准备。', `MaleText_loc5`='還行。去跟斯納爾談談，他剛前往奧格瑪向薩魯求學。去薩魯的鐵匠鋪附近的戰士區找他吧。他會對你進行測試，你最好做好準備。', `MaleText_loc7`='No está mal. Ve a hablar con Gruños, acaba de trasladarse a Orgrimmar para estudiar con Saru. Búscalo en el distrito guerrero, cerca de la herrería de Saru. Oh, y te pondrá a prueba, así que procura estar tan preparado como crees estarlo.' WHERE `ID`=5741;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스날은 내가 좀 느려서 답답하다고 하지만, 난 그저 일을 만족스럽게 마무리하고 싶은 것뿐이오. 일을 제대로 하려면 시간이 걸리는 법이지 않소.', `MaleText_loc4`='斯纳尔因为我动作慢了所以叫我。我只是想做好工作罢了，这得花时间的。', `MaleText_loc5`='斯納爾因為我動作太慢所以說我很笨。我只是想做好工作罷了，這得花時間的。', `MaleText_loc7`='Gruños me llama bobo porque soy demasiado lento. Solo quiero hacer bien mi trabajo, y eso lleva su tiempo.' WHERE `ID`=5742;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 알고 싶어하는 걸 당장 가르쳐 줄 수도 있지만 인내심을 갖고 참아야 하오. 천천히 강철을 달구면서 망치로 두드릴 때마다 변화하는 형태를 몸과 마음으로 느끼도록 하시오. 강철과 당신이 하나가 되면 그제야 내 말을 이해할 수 있을 거요.', `MaleText_loc4`='我可以告诉你你想知道的一切，但是你必须要有耐心。去练习打铁吧，摸索用锤的力度。当你熟练后，自然也就掌握啦。', `MaleText_loc5`='我可以告訴你想知道的一切，但是你必須要有耐心。去練習打鐵吧，摸索用錘的力度。當你熟練後，自然也就掌握啦。', `MaleText_loc7`='Puedo enseñarte lo que quieres saber, pero debes tener paciencia. Lleva su tiempo trabajar el acero y sentir cómo va tomando forma bajo el martillo. Cuando te hagas $guno:una; con el acero lo entenderás.' WHERE `ID`=5743;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 배우는 속도가 빠르군. 나쁜 건 아니지. 다만 작업은 제대로 마무리해야 한다는 것에만 주의하시오. 자, 이제 당신을 스날에게 보내야 하겠소이다. 그에게 가르침을 얻되 화가 나서 내뱉는 말은 귀담아 듣지 마시오. 사루의 딸들이 자기를 비웃을 때마다 늘 그러니까.', `MaleText_loc4`='你学得很快，这是件好事。但要注意按照工作的要求适当地完成工作。现在，我恐怕必须要把你送到斯纳尔那里多学些东西。你要学会所有他能教的，但不要听他的气话。当萨鲁的女儿笑话他时他就变成那样了。', `MaleText_loc5`='你學得很快，這是件好事。但要注意按照工作的要求適當地完成工作。現在，我恐怕必須要把你送到斯納爾那裡多學些東西。你要學會所有他能教的，但不要聽他的氣話。當薩魯的女兒笑話他時他就變成那樣了。', `MaleText_loc7`='Aprendes rápido, eso es bueno. Pero asegúrate de hacer bien tu trabajo y tómate el tiempo que necesites para que sea así. Ahora, me temo que debo enviarte con Gruños para continuar tu instrucción. Aprende todo lo que pueda enseñarte, pero no tomes en serio sus duras palabras. Se enfada muchísimo cuando las hijas de Saru se ríen de él.' WHERE `ID`=5744;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무리 귀를 기울여도 카른이 말하는 그 영혼의 소리가 전혀 들리지 않소.', `MaleText_loc4`='我在听，我在听，但是听不见卡恩所说的那些灵魂的声音。', `MaleText_loc5`='我在聽，我在聽，但是聽不見卡恩所說的那些靈魂的聲音。', `MaleText_loc7`='No hago más que escuchar, pero no consigo oír los espíritus de los que habla Karn.' WHERE `ID`=5745;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카른은 강철과 가열로의 영혼이 우리를 인도하는 소리에 들어야 한다고 하는데, 나는 아무리 귀를 기울여도 쇳소리밖에 들리지 않더군. 자, 나와 같이 망치를 들고 영혼의 소리를 듣도록 노력해 봅시다.', `MaleText_loc4`='卡恩说我们需要聆听熔炉和钢铁的灵魂之声，它们会指引我们的。我只听见一阵铃声。拿起铁锤，让我们一起试着听它们在说什么。', `MaleText_loc5`='卡恩說我們需要聆聽熔爐和鋼鐵的靈魂之聲，它們會指引我們的。我只聽見一陣鈴聲。拿起鐵錘，讓我們一起試著聽它們在說什麼。', `MaleText_loc7`='Karn dice que necesitamos oír a los espíritus de la forja y del acero, que ellos nos guiarán. Pero yo solo noto un zumbido en el oído. Ven aquí, coge un martillo y vamos a tratar de oír juntos a los espíritus.' WHERE `ID`=5746;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강철의 영혼은 나보다 당신을 더 마음에 들어 하는 것 같소. 나는 아직도 그들의 소리를 듣지 못했지만 당신은 잘 배운 모양이오. 가서 카른과 얘기를 해 보시오. 자기처럼 영혼의 소리를 들을 줄 아는 이를 만나면 기뻐할 거요.', `MaleText_loc4`='我猜那些灵魂更加喜欢你，我还没有听到他们的召唤但是你看起来已经上过他们好多课程了。去找卡恩谈谈，他会很高兴看到一个像他一样听到它们声音的人。', `MaleText_loc5`='我猜那些靈魂更加喜歡你，我還沒有聽到他們的召喚但是你看起來已經上過他們好多課程了。去找卡恩談談，他會很高興看到一個像他一樣聽到它們聲音的人。', `MaleText_loc7`='Supongo que les gustas más que yo a los espíritus, todavía no he oído su llamada pero tú pareces haberte hecho con todas sus lecciones. Ve a hablar con Karn, estará encantado de ver a alguien que los oye como él.' WHERE `ID`=5747;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 절망하지 마라! 두려워 말고 이 야수들과 싸워라. 상처가 나거나 뼈가 부러지면 내가 보살펴 줄 것이니. 재기하라, 영웅들이여!', `MaleText_loc4`='我们并未丧失一切！毫无恐惧地跟这些野兽交战吧。我能为你医治伤口的，安抚痛苦。英雄们，振作起来吧！', `MaleText_loc5`='我們並未喪失一切!毫無恐懼地跟這些野獸交戰吧。我能為你醫治傷口的，安撫痛苦。英雄們，振作起來吧!', `MaleText_loc7`='¡No está todo perdido! Combatan sin miedo a esas bestias. Yo curaré sus heridas y soldaré sus huesos. ¡Renóvense héroes!' WHERE `ID`=5748;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='망치질할 시간도 턱없이 모자란 판에, 당신 지금 날 방해하는군요. 물론 그럴 만한 이유가 있는 거겠죠? 만약 그렇지 않다면...', `FemaleText_loc4`='你的打扰在占用我的宝贵时间，你最好带来的是好消息。', `FemaleText_loc5`='你的打擾在佔用我的寶貴時間，你最好帶來的是好消息。', `FemaleText_loc7`='Tu interrupción me está costando tiempo, un tiempo muy valioso, más vale que merezca la pena.' WHERE `ID`=5749;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 또 불의 힘과 모루를 이용해, 무기를 만들 자가 나타난 것이로군. 물론 가르쳐 드려야죠.', `FemaleText_loc4`='啊是的，另一个要烧炉火并锻造战斗武器的人。我当然会教你怎么操作。', `FemaleText_loc5`='啊是的，另一個要燒爐火並鍛造戰鬥武器的人。我當然會教你怎麼操作。', `FemaleText_loc7`='Ah sí, otro que avivará los fuegos y fundirá las armas de guerra. Por supuesto que te enseñaré a hacerlo.' WHERE `ID`=5750;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아주 제대로 배웠군요. 이제 언더시티로 가서 제임스 반 브런트라는 대장장이를 찾아보세요. 내가 가르치지 못하는 것들을 많이 가르쳐 줄 거예요. 전사를 양성하는 군사 지구 근처에서 무기와 방어구를 만들며 시간을 보내는 걸로 알고 있어요.', `FemaleText_loc4`='我的孩子，你学得很好。去幽暗城找一个名叫詹姆斯·范·布朗特的铁匠。他能传授给你更多的知识。我想他应该在战士训练大厅附近铸造武器。', `FemaleText_loc5`='我的孩子，你學得很好。去幽暗城找一個名叫詹姆士·凡·布朗特的鐵匠。他能傳授給你更多的知識。我想他應該在戰士訓練大廳附近鑄造武器。', `FemaleText_loc7`='Has aprendido muy bien, $ghijo:hija;. Ve a Entrañas y busca a un herrero llamado James Van Brunt. Él te enseñará cosas que yo no puedo. Tengo entendido que pasa el tiempo junto a la sala de entrenamiento de los guerreros, forjando sus armas y armaduras.' WHERE `ID`=5751;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 언젠가 적의 뼈로 무기와 방어구를 만들어 볼 날이 있기를 고대하고 있다오.', `MaleText_loc4`='我希望有一天能用敌人的骨头制作武器。', `MaleText_loc5`='我希望有一天能用敵人的骨頭製作武器。', `MaleText_loc7`='Algún día, quiero forjar armas y armaduras con los huesos de mis enemigos.' WHERE `ID`=5752;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='망치로 모루를 죽이는 게 아니라, 적을 죽일 무기를 만드는 거요. 당신이 지금 뭘 잘못하고 있는 건지 보여 주리다.', `MaleText_loc4`='你不要用锤子傻乎乎地敲打铁砧，你应该是在制造一种可以杀死你的敌人的武器。让我给你演示一下你哪里做错了。', `MaleText_loc5`='你不要用錘子傻乎乎地敲打鐵砧，你應該是在製造一種可以殺死你的敵人的武器。讓我給你演示一下你哪裡做錯了。', `MaleText_loc7`='No se trata de matar al yunque con el martillo sino de crear un arma para matar a tus enemigos. Deja que te enseñe lo que haces mal.' WHERE `ID`=5753;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 많은 것을 배웠소. 이제 내가 더 가르칠 수 있는 게 없군. 제임스 반 브런트에게 가 보시오. 내가 가르칠 수 없는 것을 알려 줄 테니까.', `MaleText_loc4`='你已经学得很多，我没什么能教你了。去找詹姆斯·范·布朗特，他会教给你我所不能的。', `MaleText_loc5`='你已經學得很多，我沒什麼能教你了。去找詹姆士·凡·布朗特，他會教給你我所不會的。', `MaleText_loc7`='Has aprendido mucho, más de lo que puedo enseñarte. Ve con James Van Brunt, te enseñará lo que yo no puedo.' WHERE `ID`=5754;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 싸워라! 놈들의 의지가 약해져 가고 있다. 내 힘을 들이켜 다시 일어나라!', `MaleText_loc4`='你必须继续！他们的决心正在减弱。从我的身体中汲取力量并再次获得重生！', `MaleText_loc5`='你必須繼續!他們的決心正在減弱。從我的身體中汲取力量並再次獲得重生!', `MaleText_loc7`='¡Debes continuar! Su determinación se está debilitando. ¡Bebe de mi fuerza y renuévate de nuevo!' WHERE `ID`=5755;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부적이란 건 뭡니까?', `MaleText_loc4`='魂能是什么?', `MaleText_loc5`='魂能是什麼?', `MaleText_loc7`='¿Qué es Juju?', `FemaleText_loc1`='부적이란 건 뭡니까?', `FemaleText_loc4`='魂能是什么?', `FemaleText_loc5`='魂能是什麼?', `FemaleText_loc7`='¿Qué es Juju?' WHERE `ID`=5756;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='에코란 초자연적 힘이 흩어져 있는 형태이고, 부적은 그 힘이 정기로 집중된 것이라네. 난 강력한 주문을 외워서 에코를 부적으로 만들 수 있지. 마우아리의 부적을 사용해 자연의 힘을 자기 자신에게 반사시킬 수 있는 거라네.', `FemaleText_loc4`='魂精是超自然力量的一种尚未汇聚起来的形态，而魂能则是浓缩的精华。通过使用一种强大的咒语，我可以把魂精变成魂能。一旦它变成魂能，你就可以使用玛艾里的容器把能量反射到你自己身上。', `FemaleText_loc5`='魂精是超自然力量的一種沒有彙聚的形態，而魂能則是濃縮的精華。通過使用一種強大的咒語，我可以把魂精變成魂能。一旦它變成魂能，你就可以使用瑪艾里的容器把能量反射到你自己身上。', `FemaleText_loc7`='E''ko es la forma prima del poder sobrenatural, y Juju es la esencia concentrada. Utilizando un encantamiento puedo transformar el E''ko en Juju. Cuando se convierte en Juju puedes utilizar el Alijo de Mau''ari para reflejar en ti los poderes.' WHERE `ID`=5757;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마우아리의 부적을 잃어버렸는데, 어떡하죠?', `MaleText_loc4`='我把玛艾里的容器弄丢了。我该怎么办？', `MaleText_loc5`='我把瑪艾里的容器弄丟了。我該怎麼辦?', `MaleText_loc7`='He perdido el Alijo de Mau''ari. ¿Qué puedo hacer?', `FemaleText_loc1`='마우아리의 부적을 잃어버렸는데, 어떡하죠?', `FemaleText_loc4`='我把玛艾里的容器弄丢了。我该怎么办？', `FemaleText_loc5`='我把瑪艾里的容器弄丟了。我該怎麼辦?', `FemaleText_loc7`='He perdido el Alijo de Mau''ari. ¿Qué puedo hacer?' WHERE `ID`=5758;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신처럼 조심성이 부족한 이가 이만큼 해냈다는 게 놀랍군...$B$B좋아, 부적을 하나 더 주겠어. 기분은 좀 나쁘군!$B$B어서 가보게.', `FemaleText_loc4`='我很惊讶一个如此粗心的人竟然能走到这里……$B$B是的，你可能还有一个符咒，但是玛艾里对你的行为很生气！$B$B现在赶紧离开。', `FemaleText_loc5`='我很驚訝一個如此粗心的人竟然能走到這裡...$b$b是的，你可能還有一個符咒，但是瑪艾里對你的行為很生氣!$B$B現在趕緊離開。', `FemaleText_loc7`='Ah, me sorprende ver que alguien con una naturaleza tan descuidada haya llegado hasta tan lejos...$B$BSí, quizás tengas otro encanto, ¡pero Mau''ari está muy descontenta con tus acciones!$B$BY ahora, vete.' WHERE `ID`=5759;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 실패하기에는 아까울 정도로 일이 너무 커졌다. 물러서라, 나약한 생명체들이여.', `MaleText_loc4`='你已经走了太远了，你将注定失败。后退，凡人。', `MaleText_loc5`='你已經走了太遠了，你將註定失敗。後退，凡人。', `MaleText_loc7`='Has llegado demasiado lejos para fracasar ahora. Atrás, mortales.' WHERE `ID`=5760;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='패배의 쓴 맛을 보게 되리라, 네파리안!', `MaleText_loc4`='你会遭受失败的痛苦的，奈法利安！', `MaleText_loc5`='你會遭受失敗的痛苦的，奈法利安!', `MaleText_loc7`='¡Sufrirás con esta derrota, Nefarian!' WHERE `ID`=5761;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거면 될 걸세! 적어도 아까보다는 낫겠지!', `MaleText_loc4`='这东西应该管用的！至少它看上去管用！', `MaleText_loc5`='這東西應該管用的!至少它看起來管用!', `MaleText_loc7`='¡Esto debería hacerlo! Bueno, ¡más vale que lo haga!' WHERE `ID`=5762;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 일이! 온도는 크래클씨 428,000도입니다!', `MaleText_loc4`='天哪！现在的温度是428,000克氏度！', `MaleText_loc5`='天哪!現在的溫度是428,000克拉蘭克度!', `MaleText_loc7`='¡Sagrado Krakle! ¡La temperatura es de 428,000 grados Kraklenheit!' WHERE `ID`=5763;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='온도는 크래클씨 9280도입니다. 아주 뜨거운 거죠!', `MaleText_loc4`='温度是9280克氏度！真热！', `MaleText_loc5`='溫度是9280克拉蘭克度!真熱!', `MaleText_loc7`='¡La temperatura es de 9,280 grados Kraklenheit! ¡Es muy alta!' WHERE `ID`=5764;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='온도는 크래클씨 564도입니다.', `MaleText_loc4`='温度是564克氏度。', `MaleText_loc5`='溫度是564克拉蘭克度。', `MaleText_loc7`='La temperatura es de 564 grados Kraklenheit.' WHERE `ID`=5765;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='온도는 크래클씨 122도입니다.', `MaleText_loc4`='温度是122克氏度。', `MaleText_loc5`='溫度是122克拉蘭克度。', `MaleText_loc7`='¡La temperatura es de 122 grados Kraklenheit!' WHERE `ID`=5766;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='온도는 크래클씨 12도입니다. 아주 흥미롭군요.', `MaleText_loc4`='温度是12克氏度。真令人激动。', `MaleText_loc5`='溫度是12克拉蘭克度。真令人激動。', `MaleText_loc7`='¡La temperatura es de 12 grados Kraklenheit! ¡Qué excitante!' WHERE `ID`=5767;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 오지... 좀 위험한 것 같아 보이는데?', `MaleText_loc4`='嗯，奥齐……那个似乎不太安全。', `MaleText_loc5`='嗯，奧齊...那個似乎不太安全。', `MaleText_loc7`='Um, Ozzie... eso no parece muy seguro.' WHERE `ID`=5768;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오지!!!! 안 돼!', `MaleText_loc4`='奥齐！！天哪！', `MaleText_loc5`='奧齊!!天哪!', `MaleText_loc7`='¡¡¡¡OZZIE!!!! ¡OH, NO!' WHERE `ID`=5769;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='머리카락 하나 남기지 않고 사라졌군...', `MaleText_loc4`='连他的靴子都没留下……', `MaleText_loc5`='連他的靴子都沒留下...', `MaleText_loc7`='Ni siquiera se dejó las botas...' WHERE `ID`=5770;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 상관없다는 듯 어깨를 으쓱합니다.', `MaleText_loc4`='%s耸了耸肩。', `MaleText_loc5`='%s聳了聳肩。', `MaleText_loc7`='%s se encoge de hombros.' WHERE `ID`=5771;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 쓰러지지만 부서진 몸이 다시 일어섭니다!', `MaleText_loc4`='%s倒下了，但是它那破碎的躯体又挣扎着站了起来！', `MaleText_loc5`='%s雖然被擊倒了但是那破碎的軀體又站立起來!', `MaleText_loc7`='%s se derrumba pero el arruinado cuerpo vuelve a alzarse.' WHERE `ID`=5772;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살아있는 자들이 왔다!', `MaleText_loc4`='这儿有活人！', `MaleText_loc5`='這兒有活人!', `MaleText_loc7`='¡Los vivos están aquí!' WHERE `ID`=5773;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아야! 알았다고요. 돌아가서 다시 일 할게요, $n!', `MaleText_loc4`='嗷！好吧，我回去工作，$n！', `MaleText_loc5`='噢!好吧，我會回去工作，$n!', `MaleText_loc7`='¡Oh! ¡Muy bien, volveré al trabajo, $n!' WHERE `ID`=5774;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 완전히 정신이 나갔을 때 소리지르는 걸 들어주시라고요...', `MaleText_loc4`='当我饱受惊吓时，你将听到我大声喊叫……', `MaleText_loc5`='當我飽受驚嚇時，你將聽到我大聲喊叫...', `MaleText_loc7`='Cuando me altero... se me oye gritar.' WHERE `ID`=5775;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밸라스트라즈여, 이 세계가 검은용군단의 손아귀에 떨어지는 그날, 너의용군단은 멸망을 피하지 못할 것이니라!', `MaleText_loc4`='瓦拉斯塔兹，当黑龙统治世界的时候，你们这些龙就准备受死吧。', `MaleText_loc5`='瓦拉斯塔茲，當黑龍統治世界時，你的龍就準備受死吧。', `MaleText_loc7`='Vaelastrasz, cuando este mundo pertenezca al Vuelo Negro, tu Vuelo llegará a su fin.' WHERE `ID`=5776;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 지금은 너를 죽이는 것으로 만족하겠다...', `MaleText_loc4`='但是现在，你必须死……', `MaleText_loc5`='但是現在，你必須死...', `MaleText_loc7`='Pero, por ahora, tu muerte tendrá que ser suficiente...' WHERE `ID`=5777;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너는 한낱 형상을 처치했을 뿐이다, 어리석은 자여. 나는 너를 세상 끝날 때까지 좇을 것이다.', `MaleText_loc4`='你只不过消灭了一副幻象，蠢蛋。我会追踪你到天涯海角的。', `MaleText_loc5`='你只不過消滅了一副幻象，蠢蛋。我會追蹤你到天涯海角的。', `MaleText_loc7`='Solo has destruido una imagen, idiota. Te perseguiré hasta el fin de los días.' WHERE `ID`=5778;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음, 꽤나 배운 것 같군. 놀라워. 하지만 내 제자가 되고자 하는 이가 얼마나 많은지 아시오? 이렇게 합시다. 작은 일거리 하나만 대신 맡아 주면 내 제자로 삼아 주리다.', `MaleText_loc4`='是的，似乎你已经学到了很多知识，你给我留下了深刻的印象。但是你知道想做我学生的人有多少吗？这样吧，帮我完成一项任务，我就教你。', `MaleText_loc5`='是的，似乎你已經學到了很多知識，你給我留下了深刻的印象。但是你知道想做我學生的人有多少嗎?這樣吧，幫我完成一項任務，我就教你。', `MaleText_loc7`='Vaya, parece que has aprendido bastante, estoy impresionado. ¿Pero sabes cuántos hay que pretenden ser mis aprendices? Te diré algo, haz para mí una pequeña tarea y te tomaré a mi cargo.' WHERE `ID`=5779;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='망치와 모루를 다루는 솜씨가 좀 있긴 하지만 아직은 부족하오. 가서 데인 린드그렌과 얘기를 해 보시오. 내게 가르침을 얻을 수 있도록 준비를 제대로 시켜 줄 테니까.', `MaleText_loc4`='你掌握一些关于锤头和铁砧的技艺，但还不够。去找丹恩·林德雷谈谈，他会让你做好准备学习我教给你的知识。', `MaleText_loc5`='你掌握一些關於錘頭和鐵砧的技藝，但還不夠。去找丹恩·林德雷談談，他會讓你做好準備學習我教給你的知識。', `MaleText_loc7`='Tienes talento con el yunque y el martillo, pero no el suficiente. Ve a hablar con Dane Lindgren, te preparará y después podré entrenarte.' WHERE `ID`=5780;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신에게 대장장이의 피가 흐르고 있다고 말한 적이 있었지. 역시 내 말이 옳았소. 아이언포지의 대용광로로 가서 벤구스 딥포지라는 이름의 드워프 대장장이를 한번 찾아보시오. 내 스승이자 내가 아는 한, 최고의 대장장이니까.', `MaleText_loc4`='我说过你有铁匠的血统，看来我是对的。去铁炉堡大熔炉找一个名叫本古斯·深炉的矮人铁匠。他是我的老师，是我知道的最伟大的铁匠之一。', `MaleText_loc5`='我說過你有鐵匠的血統，看來我是對的。去鐵爐堡大鍛爐找一個名叫本古斯·深爐的矮人鐵匠。他是我的老師，是我知道的最偉大的鐵匠之一。', `MaleText_loc7`='Ya te dije que por tus venas corría la sangre de un herrero, y estaba en lo cierto. Ve a Forjaz, a La Gran Fundición, y encuentra a un herrero enano llamado Bengus Forjahonda. Mi maestro y uno de los mejores herreros que nunca he conocido.' WHERE `ID`=5781;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대장장이의 삶이란 결코 쉬운 게 아니지만, 뼈에는 강철을 심어 주고 가슴에는 화염을 심어 준다오. 우리 아버지께서도 대장장이셨고, 조부님께서도 그림 바톨의 슬하에서 강철을 주무르셨지. 그리고 이제는 우리 아들 녀석도 가문의 발자취를 따르고 있소. 내 마음을 아주 뿌듯하게 하는 사실이지.', `MaleText_loc4`='铁匠的生活可不轻松，但是它能让你体格健壮，充满热情。我的父亲是一名铁匠，我的祖父曾经在格瑞姆巴托的炼铁炉工作。现在，我的儿子也跟随着我们的脚步，他让我倍感自豪。', `MaleText_loc5`='鐵匠的生活可不輕鬆，但是它能讓你體格健壯，充滿熱情。我的父親是一名鐵匠，我的祖父曾經在格瑞姆巴托的煉鐵爐工作。現在，我的兒子也跟隨著我們的腳步，他讓我倍感自豪。', `MaleText_loc7`='La vida de un herrero no es fácil, pero llena de acero tus huesos y de fuego tu corazón. Mi padre era herrero, y mi abuelo antes que él en las forjas bajo Grim Batol. Y ahora mi hijo sigue nuestros pasos, estoy orgulloso de ese chico.' WHERE `ID`=5783;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미안하지만, 당신은 내게 배울 준비가 아직 덜 된 것 같소. 내 아들 녀석, 그로움을 만나보시오. 새 수습생이 찾아오면 무척이나 기뻐할 거요.', `MaleText_loc4`='很抱歉，$g小伙子:姑娘;，你还不够资格在我这儿求学。去找我的儿子 格鲁姆，他会收你做学生的。', `MaleText_loc5`='很抱歉，$g小夥子:姑娘;，你還不夠資格在我這兒求學。去找我的兒子 格魯姆，他會收你做學生的。', `MaleText_loc7`='Lo siento $gmuchacho:muchacha;, todavía no eres tan $gbueno:buena; como para aprender de mí. Ve a ver a mi hijo Groum, le alegrará el día conseguir un nuevo aprendiz.' WHERE `ID`=5784;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='솜씨가 부족해 보이지는 않지만, 당신을 제자로 받아들이기 전에 마지막 시험을 한 번 거쳐야겠소.', `MaleText_loc4`='你的技艺不是一无是处，但我在接纳你之前还需进行最后一次测试。', `MaleText_loc5`='你的技藝不是一無是處，但我在接納你之前還需進行最後一次測試。', `MaleText_loc7`='Tu talento tiene mucho mérito, pero necesito que superes una última prueba antes de poder continuar.' WHERE `ID`=5785;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래요. 내 기꺼이 당신에게 대장기술을 가르쳐주겠소. 가서 작업복과 망치를 가져오시오. 뭘 만들 수 있을지 한번 보자고.', `MaleText_loc4`='是的，很高兴能教你如何锻造。系上围裙，拿起铁锤，看看我们能锻造出什么来？', `MaleText_loc5`='是的，很高興能教你如何鍛造。繫上圍裙，拿起鐵錘，看看我們能鍛造出什麼來?', `MaleText_loc7`='Vaya, me encantaría enseñarte una cosa o dos sobre herrería. Coge un mandil y un martillo y veamos qué podemos hacer, ¿de acuerdo?' WHERE `ID`=5786;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배우는 속도도 빠르고 솜씨도 좋은 대장장이로군. 내가 가르칠 건 다 가르쳤네만 당신은 아직 더 배워야 할 것이 많은 것 같소. 가서 벤구스 딥포지와 얘기를 나눠보시오. 어려운 숙제를 많이 내주긴 하지만 그래도 최고의 대장장이지.', `MaleText_loc4`='你是个有天分的学生，而且还是个有潜质的铁匠。我可以在本周任何时候宣布你可以从我这里毕业了。但是我觉得你还有东西要学。去找本古斯·深炉谈谈，他是个严厉的人，但他也是最出色的。', `MaleText_loc5`='你是個有天份的學生，而且還是個有潛質的鐵匠。我可以在本週任何時候宣佈你可以從我這裡畢業了。但是我覺得你還有東西要學。去找本古斯·深爐談談，他是個嚴厲的人，但他也是最出色的。', `MaleText_loc7`='La verdad es que eres $gun buen:una buena; aprendiz y por si fuera poco $gun buen herrero:una buena herrera;. Aprobaría tu trabajo en cualquier momento. Pero tengo la impresión de que puedes seguir aprendiendo. Ve a hablar con Bengus Forjahonda. Es un maestro duro pero también uno de los mejores.' WHERE `ID`=5787;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 날카로운 비명을 지릅니다.', `MaleText_loc4`='%s高声喊叫。', `MaleText_loc5`='%s發出了一聲尖叫。', `MaleText_loc7`='%s suelta un grito agudo.' WHERE `ID`=5788;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='깜짝 놀랐잖아요. 그렇게 어두운 데서 불쑥 나타나지 마요. 다음에는 인기척이라도 내세요.', `FemaleText_loc4`='不要那样从阴暗中走出来。下次你要先给女生一点警示。', `FemaleText_loc5`='不要那樣從陰暗中走出來。下次你要先給女生一點警示。', `FemaleText_loc7`='No salgas así de las sombras. ¡La próxima vez avisa!' WHERE `ID`=5789;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='암흑이 그늘숲을 집어삼켰을 때부터 난 잠을 잘 수가 없었어요. 바람에 실려오는 무시무시한 비명에 자꾸 잠이 깨거든요. 마치 양들의 비명 소리처럼 들리는데, 그치지를 않아요.', `FemaleText_loc4`='自从阴影占据了暮色森林我就一直无法入睡。我总是被风中传来的可怕尖叫声惊醒。那听起来好像羔羊的叫声，而且声音从不会停止。', `FemaleText_loc5`='自從陰影佔據了暮色森林我就一直無法入睡。我總是被風中傳來的可怕尖叫聲驚醒。那聽起來好像羔羊的叫聲，而且聲音從不會停止。', `FemaleText_loc7`='Desde que las sombras reclamaron el Bosque del Ocaso no he podido volver a dormir. No me dejan dormir los fantasmales sonidos de gritos que trae la brisa. Parecen gritos de corderos, y nunca se detendrán.' WHERE `ID`=5790;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='흠... 당신 작품이 괜찮긴 하지만 아직까지 내가 바라는 기술에는 근처도 가지 못했군요. 황금골에 가서 대장장이 아르거스를 만나보세요. 그 친구가 기본기를 가르쳐줄 거예요. 기본기를 다 배우거든 다시 날 찾아오세요. 그러면 내게서 대장기술을 배울 준비가 됐는지 몇 가지 시험을 해보겠어요.', `FemaleText_loc4`='呣，你的工作还可以，但是离我期盼的学生素质还差太远。去找闪金镇的铁匠阿古斯谈谈，我敢肯定他能教你一些基础知识。当你学完后再来找我，我会给你一次小测试以确定你准备好了。', `FemaleText_loc5`='呣，你的工作還可以，但是離我期盼的學生素質還差太遠。去找閃金鎮的鐵匠阿古斯談談，我敢肯定他能教你一些基礎知識。當你學完後再來找我，我會給你一次小測試以確定你準備好了。', `FemaleText_loc7`='Ummm... tu trabajo está bien pero ni siquiera se acerca a la calidad que busco en un alumno. Ve a hablar con el herrero Argus de Villadorada, estoy seguro de que puede enseñarte lo más básico. Cuando hayas terminado, vuelve aquí y te haré una prueba para ver si estás $gpreparado:preparada;.' WHERE `ID`=5791;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네, 조만간 당신이 찾아올 거라는 소식은 들었어요. 하지만 난 아무나 제자로 받지 않아요. 당신에게 솜씨가 있다는 확신이 있어야 하죠. 내가 주는 시험을 치르면서 한번 확인해 보도록 하죠.', `FemaleText_loc4`='是的，我曾听到传言说我迟早会见到你的。但我不会随便接纳任何人的，我需要首先确定你的水准。你愿接受我的测试吗？', `FemaleText_loc5`='是的，我曾聽到傳言說我遲早會見到你的。但我不會隨便接納任何人的，我需要首先確定你的水準。你願接受我的測試嗎?', `FemaleText_loc7`='Sí, me ha dicho un pajarito que volveremos a vernos, tarde o temprano. Pero no creas que acepto a cualquiera, primero tengo que asegurarme de que tienes lo que se necesita. ¿Quieres realizar mi pequeña prueba y descubrirlo?' WHERE `ID`=5792;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='꽤 괜찮은 실력이지만 모서리 둘레가 좀 거칠군요. 그건 연습하면 나아질 테니까 걱정하진 마세요. 말이 나와서 말인데 요즘 당신이 만들고 있는 거나 한번 보도록 하죠.', `FemaleText_loc4`='你干得很漂亮，但是刀口还有些粗糙。不要担心，多加练习就会好的。说到这里，我们看看你一直以来的工作怎么样？', `FemaleText_loc5`='你幹得很漂亮，但是刀口還有些粗劣。不要擔心，多加練習就會好的。說到這裡，我們看看你一直以來的工作怎麼樣?', `FemaleText_loc7`='Haces un buen trabajo, aunque algo desigual en los bordes. No te preocupes, lo superarás con la práctica. Y, hablando de práctica, ¿qué te parece si vemos lo que hemos estado haciendo?' WHERE `ID`=5793;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제는 오히려 내 작품의 모서리 둘레가 거친 것 같군요. 솔직히 더 이상은 내가 가르쳐 드릴 게 없을 것 같아요. 아이언포지의 벤구스 딥포지라면 당신을 가르칠 수 있을 거예요. 금속에 관해서라면 모르는 게 없는 드워프거든요. 아이언포지의 대용광로로 가서 제자를 받는지 한번 알아보세요.', `FemaleText_loc4`='现在我真是力不从心了，我说实话真是没什么可教你的了。但你知道谁可以吗？铁炉堡的本古斯·深炉，现在有一个矮人很了解他。到铁炉堡的大铁炉去找他，看看他是否想收个新学徒。', `FemaleText_loc5`='現在我真是力不從心了，我說實話真是沒什麼可教你的了。但你知道誰可以嗎?鐵爐堡的本古斯·深爐，現在有一個矮人很瞭解他。到鐵爐堡的大鍛爐去找他，看看他是否想收個新學徒。', `FemaleText_loc7`='Ahora soy yo la que necesita pulirse un poco, creo, sinceramente, que no puedo enseñarte nada más. ¿Pero sabes quién podrá hacerlo? Bengus Forjahonda, de Forjaz, es un enano que conoce a la perfección su acero. Ve a buscarlo en La Gran Fundición de Forjaz, quizás quiera instruirte.' WHERE `ID`=5794;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사루에게 내 뛰어난 솜씨를 증명해 보이면 자기 딸 중 하나를 내게 줄 수밖에 없을 거야. 어디 최후에 누가 웃게 되는지 한번 보자고.', `MaleText_loc4`='要是我向萨鲁证明了自己的实力，他将别无选择，只能让我为他的一个女儿而战。让我们看看谁是失败的那个吧。', `MaleText_loc5`='要是我向薩魯證明了自己的實力，他將別無選擇，只能讓我為他的一個女兒而戰。讓我們看看誰是失敗的那個吧。', `MaleText_loc7`='Si le muestro a Saru de lo que soy capaz no tendrá otra opción que dejarme luchar por una de sus hijas. Entonces veremos quién ríe.' WHERE `ID`=5795;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수미와 투미에게는 접근하지 않는 게 자네 신상에 좋을 거야. 임자가 있거든.', `MaleText_loc4`='离苏米和图米远点。他们会……极力推销他们的东西的。', `MaleText_loc5`='離蘇米和圖米遠點。他們會...極力推銷他們的東西的。', `MaleText_loc7`='Aléjate de Sumi y Tumi. Están... comprometidas.' WHERE `ID`=5796;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 번만 더 그런 형편없는 솜씨를 가지고 날 찾아오면 염소 오줌에 절인 조그만 상자에 집어넣어 집으로 보내버리겠어. 오그톡 같은 얼간이한테나 가봐. 자네 수준에는 그런 자가 딱 맞으니까.', `MaleText_loc4`='再次给我带来这种劣质货我就把你装在用山羊尿回过火的小铁盒里送回家。现在去见见那个傻瓜乌格索克，他更加适合你的需要。', `MaleText_loc5`='再次給我帶來這種劣質貨我就把你裝在用山羊尿回過火的小鐵盒裡送回家。現在去見見那個傻瓜烏格索克，他更加適合你的需要。', `MaleText_loc7`='Vuelve otra vez con un trabajo tan lamentable y te mandaré a casa en una cajita de hierro que he templado en orín de cabra. Ve a ver al idiota de Ug''thok, es más adecuado para tus necesidades.' WHERE `ID`=5797;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러니까 내 가르침을 받을 만큼 솜씨가 있다고 생각하는 건가? 자네는 내 장화 밑의 벌레 정도밖에 되지 않아. 하지만 아랫 것을 받아주면 수미와 투미의 마음을 살 수 있을지도 모르겠군. 자네가 얼마나 실력이 있는지 한번 봐주지. 보잘것없을 게 뻔하지만!', `MaleText_loc4`='你认为自己够资格向我学习吗？你不过是我脚下的一名卑微的小人物罢了。但是，收纳一名下属或许能增加我对苏米和图米的吸引力。让我看看你拥有什么技能。', `MaleText_loc5`='你認為自己夠資格向我學習嗎?偉大的斯納爾?你不過是我腳下的一名卑微的小人物罷了。但是，收納一名下屬或許能增加我對蘇米和圖米的吸引力。讓我看看你擁有什麼技能。', `MaleText_loc7`='¿Así que crees que eres tan $gbueno:buena; como para aprender de mí? ¿Del gran Gruños? No eres más que un gusano bajo la suela de mis botas. Sin embargo, con un subordinado puede que Sumi y Tumi me encuentren más atractivo. Vamos a ver cuáles son tus habilidades.' WHERE `ID`=5798;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래? 물론 원한다면 가르쳐줄 수야 있지. 하지만 수미와 투미는 건드리지 마. 자네 같은 자에게 어울리는 상대가 아니니까. 사루는 자기 딸들 앞에 실력 없는 얼간이들이 얼씬대는 꼴을 못 보지.', `MaleText_loc4`='嗯？啊是的，如果你期望的话我可以教你一些东西。但是要离苏米和图米远些，她们不喜欢像你这样的人。萨鲁只让那些技艺高超的人接近他的女儿。', `MaleText_loc5`='嗯?啊是的，如果你期望的話我可以教你一些東西。但是要離蘇米和圖米遠些，她們不喜歡像你這樣的人。薩魯只讓那些技藝高超的人接近他的女兒。', `MaleText_loc7`='¿Hmm? Oh sí, puedo enseñarte algo si quieres. Pero no te acerques a Sumi ni a Tumi, no son para tipos como tú. Saru solo dejará que se acerque a sus hijas alguien con gran talento.' WHERE `ID`=5799;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네에게 더는 가르칠 것이 없으니 이제 가 보게. 사루에게 갈 생각인가? 꿈도 야무지군. 자네처럼 보잘것없는 자가 찾아가면 피에다가 쇠를 담금질하고 말걸.', `MaleText_loc4`='我没有什么东西可以教你了，现在你可以走了。不要想接近萨鲁，因为像你一样卑微的家伙，他只会用你们的血来炼钢。', `MaleText_loc5`='我沒有什麼東西可以教你了 - 快滾!不要想接近薩魯，因為像你一樣卑微的人他只會用你們的血來煉鋼的。', `MaleText_loc7`='Ya no te puedo enseñar nada más, ¡vete! Y ni siquiera pienses en acercarte a Saru, de alguien tan inútil como tú solo aprovecharía la sangre para templar su acero.' WHERE `ID`=5800;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼들이 당신을 내게로 이끌어주었군. 내가 축복을 받았나 봅니다.', `MaleText_loc4`='灵魂将你带到我这儿来，感谢他们。', `MaleText_loc5`='靈魂將你帶到我這兒來，感謝他們。', `MaleText_loc7`='Los espíritus te han traído hasta mí, y puedo sentir su bendición.' WHERE `ID`=5801;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='젊은이, 당신은 영혼의 말에 좀 더 귀를 기울일 필요가 있소. 당신의 운명은 썬더 블러프에 있는 트라그 스톤후프라는 자에게 향해야 하오. 서로 가르침을 줄 수도 있을 거요.', `MaleText_loc4`='你需要多加留心灵魂的指引。你的路线取决于另一个人，雷霆崖的瑟拉格·石蹄。或许你们可以互相学习。', `MaleText_loc5`='你需要多加留心靈魂的指引。你的路線取決於另一個人，雷霆崖的瑟拉格·石蹄。或許你們可以互相學習。', `MaleText_loc7`='Tienes que prestar un poco más de atención a la guía de los espíritus, joven. Tu camino está junto a otro, Thrag Pezuña Pétrea de Cima del Trueno. Quizás puedas aprender algo de algún otro.' WHERE `ID`=5803;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 그럼 내가 제시한 과제를 수행할 준비가 되었소? 영혼들의 이야기로는 당신이 이 시험에 통과할 것이라고 하는군. 영혼들과 자신의 힘을 믿고 있소?', `MaleText_loc4`='告诉你，你准备好接受我为你安排的挑战了吗？幽灵告诉我你会通过的，但是你相信他们抑或是相信自己？', `MaleText_loc5`='告訴你，你準備好接受我為你安排的挑戰了嗎?幽靈告訴我你會通過的，但是你相信他們抑或是相信自己?', `MaleText_loc7`='Dime, ¿te sientes $gpreparado:preparada; para afrontar el reto que te he dispuesto? Los espíritus me dicen que lo superarás, pero ¿tienes fe en ellos o en ti $gmismo:misma;?' WHERE `ID`=5805;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 우리 함께 용광로 영혼들의 인도를 받아 강철이 진정으로 원하고 있는 모양을 만들어 봅시다.', `MaleText_loc4`='一起来吧，我们将调整熔炉的火力，找出金属的真正形态。', `MaleText_loc5`='一起來吧，我們將調整熔爐的火力，找出金屬的真正形態。', `MaleText_loc7`='Únete a mí, juntos vincularemos los espíritus de la fundición y encontraremos la forma verdadera que busca el metal.' WHERE `ID`=5806;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 인생길에서 인연이란 아주 잠시 동안만 교차하는 것... 이제는 그 짧은 만남을 끝내고 각자의 길을 가야 할 때로군. 당신에게 가르침을 주고 그다음 스승에게까지 인도할 수 있음을 영광이라 생각하오. 오그리마에 있는 사루 스틸퓨리를 찾아가보시오. 당신이 배워야 할 것을 알 수 있을게요.', `MaleText_loc4`='我们的人生之路只是暂时相交，现在是我们分道扬镳的时候啦。很荣幸能传授你知识，现在我送你上路，去找下一个导师吧。去奥格瑞玛找萨鲁·钢怒，他会教你你想学的知识。', `MaleText_loc5`='我們的人生之路只是暫時相交，現在是我們分道揚鑣的時候啦。很榮幸能傳授你知識，現在我送你上路，去找下一個導師吧。去奧格瑪找薩魯·鋼怒，他會教你想學的知識。', `MaleText_loc7`='Nuestros senderos por la vida solo se cruzan brevemente y ha llegado el momento de que se separen. Me considero bendecido por el tiempo que he dedicado a enseñarte y ahora te envío a unir tus pasos con los de tu siguiente mentor. Busca a Saru Furiacerada de Orgrimmar, él te enseñará lo que necesitas.' WHERE `ID`=5807;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신에게는 큰 잠재력이 있지만 먼저 이해심부터 키워야 하오. 영혼의 힘을 인정하고 그들의 부름에 귀를 기울여야 하지. 그제야 비로소 당신이 가야 할 길을 걸을 준비가 된 거요. 가서 트라그와 얘기를 나눠보시오. 어쩌면 당신 둘은 서로 많은 도움이 될 수 있을 것 같단 생각이 드니까.', `MaleText_loc4`='你有巨大的潜能，但你必须首先能理解，你必须接受精灵们并听从他们的召唤。只有那时你才会准备好走你要走的路。去找瑟拉格谈谈，我想你们可能会互相学习很多东西。', `MaleText_loc5`='你有巨大的潛能，但你必須首先能理解，你必須接受精靈們並聽從他們的召喚。只有那時你才會準備好走你要走的路。去找瑟拉格談談，我想你們可能會互相學習很多東西。', `MaleText_loc7`='Tienes un gran potencial, pero primero debes conseguir el conocimiento, debes aceptar a los espíritus y escuchar su llamada. Solo entonces estarás $gpreparado:preparada; para el camino que debes seguir. Ve a hablar con Thrag, creo que podríais aprender mucho el uno del otro.' WHERE `ID`=5808;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제야 당신의 삶과 나의 삶이 교차하여 같은 길을 갈 준비가 되었군. 비록 짧은 시간이긴 하지만 말이오. 하지만 그 전에, 당신이 영혼의 이야기를 이해하고 있다는 것은 확실히 해두어야 하오.', `MaleText_loc4`='你现在准备好把你我的命运联系在一起了，即使只有一小段时间。然而我们必须确定你明白精灵们所说的话。', `MaleText_loc5`='你現在準備好把你我的命運聯繫在一起了，即使只有一小段時間。然而我們必須確定你明白精靈們所說的話。', `MaleText_loc7`='Ya estás $glisto:lista; para seguir el camino que une tu vida con la mía, aunque por poco tiempo. Pero debemos asegurarnos de que comprendes las cosas de las que hablan los espíritus.' WHERE `ID`=5809;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 이미 많은 것을 배웠지만, 영혼의 말에 의하면, 아직도 배울 게 많이 있다는 것 같소. 나는 가야 할 방향만 제시할 뿐이지. 당신을 직접 이끌어줄 수는 없소. 오그리마에 있는 사루 스틸퓨리를 찾아가도록 하시오. 당신의 다음 여정은 그곳에서 시작될 거요.', `MaleText_loc4`='你已经学了很多，但我觉得精灵们还有很多要教给你。我可以给你引路但不能替你走路。去找到奥格瑞玛的萨鲁·钢怒，你的旅程的下一段从那里开始。', `MaleText_loc5`='你已經學了很多，但我覺得精靈們還有很多要教給你。我可以給你引路但不能替你走路。去找到奧格瑪的薩魯·鋼怒，你的旅程的下一段從那裡開始。', `MaleText_loc7`='Has aprendido mucho, pero tengo la sensación de que los espíritus pueden enseñarte aún más. Puedo mostrarte el camino pero no guiar tus pasos. Ve y encuentra a Saru Furiacerada en Orgrimmar, con él comienza tu siguiente etapa.' WHERE `ID`=5810;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간 뺏을 생각일랑 말고 내 제자, 바실하고나 얘기해 보게.', `MaleText_loc4`='你在浪费我的时间，去找我的学生巴兹尔谈谈吧。', `MaleText_loc5`='你在浪費我的時間，去找我的學生巴茲爾談談吧。', `MaleText_loc7`='Estás perdiendo el tiempo, ve a hablar con mi estudiante Basil.' WHERE `ID`=5811;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신에게 재능이 있을 수도 있고 없을 수도 있지. 재능이 있다면 내 제자로 삼아 당신이 배우고자 하는 걸 가르쳐 주겠소. 재능이 없으면? 여기서 그만두지.', `MaleText_loc4`='或许你明白这意味着什么，或许你不明白。如果你懂的话，我会传授知识给你。如果你不懂……嗯，那就这样吧。', `MaleText_loc5`='或許你有那個本事，或許沒有。如果你有，我會傳授知識給你。如果你沒有...那麼，就這樣吧。', `MaleText_loc7`='Puede que tengas lo necesario, y puede que no. Si lo tienes te acogeré y te enseñaré lo que quieres saber. Si no es así lo dejaré tal y como está.' WHERE `ID`=5812;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장비를 만드는 실력이 꽤 쓸만하군. 훌륭해... 오크의 고향, 오그리마로 가서 사루 스틸퓨리라는 대장장이를 찾게. 오크에게도 한 가지 인정할 게 있다면, 바로 죽음의 도구를 썩 잘 만들 줄 안다는 거지.', `MaleText_loc4`='你制造的装备很不错，真的。去兽人的家园奥格瑞玛找一个名叫萨鲁·钢怒的铁匠吧。你必须给那些制造美丽的死亡器具的兽人一样东西。', `MaleText_loc5`='你製造的裝備很不錯，真的。去獸人的家園奧格瑪找一個名叫薩魯·鋼怒的鐵匠吧。你必須給那些製造美麗的死亡器具的獸人一樣東西。', `MaleText_loc7`='Haces muy buen equipo, muy bueno, sin duda. Ve al hogar de los orcos, Orgrimmar, y busca a un herrero llamado Saru Furiacerada. Hay que reconocer una cosa, y es que los orcos hacen bellas herramientas de muerte.' WHERE `ID`=5813;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미안하지만 당신은 아직 기본기도 갖추고 있지 않아 내 가르침을 받기에는 무리겠소. 하지만 걱정하지 마시오. 내 제자인 로트가스를 찾아가 얘기해 보시오. 당신을 도와줄 테니까.', `MaleText_loc4`='很抱歉$g小伙子:姑娘;，但是你基础不足，我不能教你。但是别烦恼，跟我的学生洛特加斯谈谈，他会帮助你的。', `MaleText_loc5`='很抱歉$g小夥子:姑娘;，但是你基礎不足，我不能教你。但是別煩惱，跟我的學生洛特加斯談談，他會幫助你的。', `MaleText_loc7`='Lo siento $gmuchacho:muchacha; pero no tienes la base necesaria para aprender de mí. Pero no te inquietes, ve a hablar con mi estudiante Rotgath, él te ayudará.' WHERE `ID`=5814;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 훌륭한 대장장이가 될 소질이 있을 것 같군. 하지만 당신을 가르치기 전에 진짜 솜씨가 있는지 알아봐야겠소.', `MaleText_loc4`='看来你具有成为一名优秀铁匠的潜质。但是在我教你之前，我得知道你是否明白自己在做什么。', `MaleText_loc5`='看來你具有成為一名優秀鐵匠的潛質。但是在我教你之前，我得知道你是否明白自己在做什麼。', `MaleText_loc7`='Parece que la herrería podría ser lo tuyo. Pero, antes de enseñarte nada, necesito saber si tienes lo que se necesita.' WHERE `ID`=5815;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 솜씨는 그 어떤 말로 칭찬해도 모자라겠군. 망치와 모루로 이렇게 놀라운 일을 할 수 있다니. 이제는 고블린에게 가서 대장기술을 배우시오. 단 내가 그런 말을 했다고는 아무에게도 얘기하지 말고. 브리크 킨크래프트라고 하는 자를 찾아가시오. 일전에 듣기로는 무법항에서 상점을 하나 운영하고 있다고 하더군.', `MaleText_loc4`='我不能对你进行什么指导啦，你能用铁锤和铁砧做出如此令人称奇的东西。我建议你去找一个名叫布里克·基克拉夫的地精，你可别告诉别人,我最后一次听说他在藏宝海湾经营一家商店。', `MaleText_loc5`='我無法對你光用鐵錘和鐵砧就做出如此令人稱奇的東西提供足夠的意見。現在，不要告訴別人我建議你去找一位哥布林，不過那確實就是我想要做的事。布里克·基克拉夫是他的名字，我最後一次聽到他是在藏寶海灣經營一家商店。', `MaleText_loc7`='Todo lo que diga sobre tu trabajo es poco, puedes hacer auténticas maravillas con un yunque y un martillo. No le digas a nadie que te he aconsejado buscar a un goblin para seguir aprendiendo, pero eso es exactamente lo que voy a hacer. Brikk Finoficio es su nombre, y lo último que oí de él es que estaba dirigiendo una tienda en Bahía del Botín.' WHERE `ID`=5816;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대장기술이 무슨 어린애들 장난인 줄 아는가! 밖에 나가 스날하고나 얘기하게. 능구렁이 같은 놈이긴 해도 그래도 모루 다루는 법은 제대로 아니까.', `MaleText_loc4`='这可不是一个年轻人玩的游戏！去外面找斯纳尔谈谈。他看上去或许有些阴险，但是他确实是使铁砧的好手。', `MaleText_loc5`='這可不是一個年輕人玩的遊戲!去外面找斯納爾談談。他看起來或許有些陰險，但是他確實是使鐵砧的好手。', `MaleText_loc7`='¡Esto no es ningún juego, joven! Vete, habla con Gruños fuera. Quizás no sea más que una serpiente de mi guarida, pero sabe cómo manejar un yunque.' WHERE `ID`=5817;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 좀 약하고 균형도 덜 잡힌데다 자신감도 없군. 자네가 만드는 작품 말고, 바로 자네 본인 말일세! 자, 진짜 대장장이가 될 준비는 됐는가?', `MaleText_loc4`='有些软弱、缺乏平衡性、缺乏自信。我不是说你所做的工作，年轻人，而是说你！你准备好学习如何成为一名真正的铁匠了吗？', `MaleText_loc5`='有些軟弱、缺乏平衡性、缺乏自信。我不是說你所做的工作，年輕人，而是說你!你準備好學習如何成為一名真正的鐵匠了嗎?', `MaleText_loc7`='Sigue siendo débil, sin equilibrio ni seguridad. ¡No estoy hablando de tu trabajo $gjovencito:jovencita;, estoy hablando de ti! Dime, ¿estás $glisto:lista; para convertirte en un auténtico herrero o no?' WHERE `ID`=5818;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 나보다 쇠의 비밀을 더 많이 알고 있군. 좋은 일이야. 쇠의 비밀이란 꼭 손에 넣어야 할 가치있는 것이지. 자네는 이제 인간 영토 남쪽에 있는 밀림으로 가게. 무법항이라는 고블린 도시를 찾아. 그곳에 브리크 킨크래프트라고 하는 고블린이 있을 것이네. 별로 마음에 들지 않지만 쇠의 비밀에 대한 지식은 내가 아는 어느 누구하고도 비교할 수가 없을 정도지.', `MaleText_loc4`='我发现你所掌握的炼钢知识已经比我多了。这很好，本该如此。现在你必须去人类领土南部的丛林，去地精城市藏宝海湾。你将在那儿找到一个名为布里克·基克拉夫的地精。我不喜欢地精，但他所掌握的炼钢知识却是无与伦比的。', `MaleText_loc5`='我發現你所掌握的煉鋼知識已經比我多了。這很好，本該如此。現在你必須去人類領土南部的叢林，去哥布林城市藏寶海灣。你將在那兒找到一個名為布里克·基克拉夫的哥布林。我不喜歡哥布林，但他所掌握的煉鋼知識卻是無與倫比的。', `MaleText_loc7`='Veo que sabes más del secreto del acero que yo mismo. Eso es bueno, pues es algo necesario. Ahora debes viajar a la jungla situada al sur de las tierras de los humanos, a la ciudad de los goblins, Bahía del Botín. Allí encontrarás un goblin llamado Brikk Finoficio. No me gustan los goblins pero no conozco a nadie que sepa más que ellos del secreto del acero.' WHERE `ID`=5819;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='응? 나? 당연히 대장장이지. 가만, 그러고 보니 자네 지금 드워프만 쇠를 다룰 줄 안다고 생각하는 게로군? 그럼 맘대로 하게. 가서 드워프한테나 도움을 청하라고!', `MaleText_loc4`='什么？我当然是一个铁匠。什么，你认为矮人是打铁最有效率的种族？好吧，可能是那样。去找一个矮人来帮你！', `MaleText_loc5`='什麼?我當然是一個鐵匠。什麼，你認為矮人是打鐵最有效率的種族?好吧，可能是那樣。去找一個矮人來幫你!', `MaleText_loc7`='¿Sí? Pues claro que soy un herrero. ¿Qué? ¿Crees que los enanos son los únicos que valen su peso en yunques? Muy bien, pues que así sea. ¡Encuentra a un enano que te ayude!' WHERE `ID`=5820;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 날 놀리는 거야? 맞지?! 놀리는 게 아니라면 나를 어릿광대 정도로 생각하는 거겠지. 그런 거야? 내가 광대처럼 보여? 나 원 참, 맞지?! 지금 내가 광대라고 생각하는 거지!', `MaleText_loc4`='你是在开玩笑吧？你一定是在开玩笑！你认为我是个取悦于你的小丑，是吗？我是小丑？嗯，是的！你认为我是小丑，是吧！', `MaleText_loc5`='你是在開玩笑吧?你一定是在開玩笑!你認為我是個取悅於你的小丑，是嗎?我是小丑?嗯，是的!你認為我是小丑，是吧!', `MaleText_loc7`='¿Me estás tomando el pelo? ¡Me debes de estar tomando el pelo! O eso, o crees que soy un payaso con el que divertirte. ¿Es eso lo que piensas? ¿Que soy un payaso? ¡Ja, eso es! ¡Piensas que soy un payaso!, ¿verdad?' WHERE `ID`=5821;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마치 내가 이런 물건을 처음 본 것인 양 행동하는군. 괜찮은 물건이긴 하지만 이런 "괜찮은" 수준의 물건은 매일 본단 말이야. 이렇게 하지. 나를 아주 놀라게 해주면 잠자던 드워프가 벌떡 일어나게 할 만한 것을 만드는 법을 가르쳐주겠어.', `MaleText_loc4`='好像这是我所见过的最好的垃圾。当然它还过得去，但我每天都看到这类‘还行’的东西。告诉你吧，你若能想办法让我叫好，我就会教给你能让矮人们在睡梦里都会笑的东西。', `MaleText_loc5`='你表現得像這是我見過最好的垃圾。當然它還過得去，但我每天都看到這類‘還行’的東西。告訴你吧，你若能想辦法讓我叫好，我就會教給你能讓矮人們在睡夢裡都會笑的東西。', `MaleText_loc7`='Te comportas como si fuera lo mejor que has visto nunca. Claro que está bien, pero veo cosas que "están bien" todos los días. Te diré algo, encuentra un modo de sorprenderme y te enseñaré cosas que hacen sonreír en sueños a los enanos.' WHERE `ID`=5822;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상상의 나래를 펼치게, 친구. 일단 어떻게 만드는지만 알면 전 세계 소매상에 팔 수 있거든. 물론 그때는 시장 전략도 구상해야 할 테지. 하지만, 지금은 대장기술이나 갈고 닦고 있자고.', `MaleText_loc4`='我的朋友，你缺乏想象力，要是你能明白锻造它的方法，那么你就能生产、装送、配送给全世界的零售商。当然，那时你就得学做贸易了。现在，我们就先关注锻造这块吧，好吗？', `MaleText_loc5`='朋友，你太缺乏想像力了。要是你能搞懂它的鍛造方法，那麼你就能生產、裝箱、配送給全世界的零售商。當然，到時候你就得處理行銷上的問題了。不過呢，現在我們還是先關注鍛造這塊就好，好嗎?', `MaleText_loc7`='El único límite es la imaginación, $gamigo:amiga;, si puedes imaginar cómo forjarlo podrás hacerlo, empaquetarlo y enviarlo a vendedores de todo el mundo. Aunque entonces, claro está, tendrás que vértelas con las técnicas de mercado. Te diré algo, por ahora vamos a quedarnos con la parte de la herrería, ¿vale?' WHERE `ID`=5823;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너의 승리는 오래 가지 못한다. 얼라이언스와 호드의 시대도 점차 끝나고 있어! 우리가 다음에 또 만나면 그게 바로 끝이 될 것이다.', `MaleText_loc4`='你的胜利不会长久。联盟和部落的日子都不长了！下次我们见面就是最后一次了。', `MaleText_loc5`='你的勝利不會長久。聯盟和部落的日子都不長了!下次我們見面就是最後一次了。', `MaleText_loc7`='Esta victoria durará poco. ¡Los días divididos entre la Horda y la Alianza están llegando a su fin! La próxima vez que nos encontremos será la última.' WHERE `ID`=5824;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리페가 뭐라고 했나?? 그리페의 말은 거짓이 아니었다! 저기, 전투 계획서를 훔치려 하고 있다!', `MaleText_loc4`='格里芬对首领说了什么？？格里芬可没说谎！她在那儿，试图窃取战役计划！', `MaleText_loc5`='葛里夫對首領說了什麼??葛里夫可沒說謊!她在那兒，試圖竊取戰役計畫!', `MaleText_loc7`='¿¿Qué es lo que dijo Gryphe, jefe?? ¡Gryphe no mentía! ¡Ahí está ella, intenta robar los planes de batalla!' WHERE `ID`=5825;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리페 일 한다! 그리페 지금 간다!!!', `MaleText_loc4`='格里芬做他的工作！格里芬现在离开！！！', `MaleText_loc5`='葛萊夫做他的工作!葛萊夫現在離開!!!', `MaleText_loc7`='¡Gryfe hace su trabajo! ¡¡¡Gryfe ya se va!!!' WHERE `ID`=5826;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 이제 시작이군! 내가 혼자 있을 줄 알았지, 응?!', `MaleText_loc4`='哦，开始起作用了！我敢打赌你觉得我会孤单，是吧？！', `MaleText_loc5`='哦，開始起作用了!我敢打賭你覺得我會孤單，是吧?!', `MaleText_loc7`='¡Listo! ¡Seguro que pensabas que estaría solo, ¿eh?!' WHERE `ID`=5827;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런! 이건 얘기했던 것보다 더 심하잖아. 혼자 알아서 해보게, 홀쭉이!', `MaleText_loc4`='哦！这比我预料的要多得多了，你随便吧，干柴！', `MaleText_loc5`='哦!這比我預料的要多得多了，你得靠自己了，『瘦子』!', `MaleText_loc7`='¡Guau! Supera con creces lo que habíamos acordado, ¡ahora te las tendrás que apañar solo, Flaco!' WHERE `ID`=5828;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='인정하기는 싫지만 곰이 나보다 한 수 위군. 무지막지하게 큰 곰이야!$B$B저 곰을 때려눕힐 수 있을 정도면 자랑스러워할 만하지! 녀석 때문에 골치깨나 앓은 사냥꾼이 한둘이 아니거든.$B$B<당신의 등을 철썩 치는 마렉>$B$B그 곰을 잡으면 자네를 우리 원정순찰대 오두막 정식 회원으로 받아주지.', `MaleText_loc4`='尽管我不愿承认，但是熊确实打败了我。我的天，那是一只体型庞大的熊！$b$b但是，如果你能打败那只熊的话，那可是一件值得骄傲的事儿！既便是我们中最好的猎人，也为此头痛不已。$b$b<他拍着你的背。>$b$b打败熊吧，你将成为旅行者营地中一名合格的成员的。', `MaleText_loc5`='儘管我不願承認，但是熊確實打敗了我。我的天，那是一隻體型龐大的熊!$b$b但是，如果你能打敗那隻熊的話，那可是一件值得驕傲的事兒!既便是我們中最好的獵人，也為此頭痛不已。$b$b<他拍著你的背。>$b$b打敗熊吧，你將成為遠行者小屋中一名合格的成員的。', `MaleText_loc7`='Aunque odio admitirlo, el oso me superó con creces. ¡Dios mío, es un oso enorme!$B$BNo obstante, si puedes vencer al oso será una hazaña de la que estar orgulloso. Ha dado problemas a muchos de nuestros mejores cazadores.$B$B<Te da unos golpecitos en la espalda.>$B$BDerrota al oso y te aceptaremos como miembro regular de la Cabaña del Errante.' WHERE `ID`=5829;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳 원정순찰대 오두막에서는 무엇보다도 사냥 기술을 가장 높이 평가하지. 내게 인정을 받고 싶은가? 그건 공짜로 얻어지는 게 아니라네.$B$B한번 도전해 보게!', `MaleText_loc4`='在旅行者营地，我们最推崇狩猎技能。想获得我的赏识吗？你得靠行动来证明。$B$B面对挑战吧，$G小伙子:姑娘;！', `MaleText_loc5`='在遠行者小屋，我們最推崇狩獵技能。想獲得我的賞識嗎?你得靠行動來證明。$B$B面對挑戰吧，$G小夥子:姑娘;!', `MaleText_loc7`='Aquí, en la Cabaña del Errante valoramos la habilidad cazando más que cualquier otra cosa. ¿Quieres mi aprobación? Tendrás que ganártela.$B$B¡Enfréntate al desafío, $Gmuchacho:muchacha;!' WHERE `ID`=5830;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꽤나 실력 있는 사냥꾼이 되었군, $n! 기술도 입증하고 다릴마저도 능가하다니. 진짜 칭찬받을만한 일이야!$B$B자네는 언제나 환영이네.', `MaleText_loc4`='你已经成为一个出色的猎手了，$n！你不但证明了你的技能，你还胜过了达瑞尔，这是你在我的名册中得到了额外的分数！$B$B欢迎你随时来到这里。', `MaleText_loc5`='你已經成為一個出色的獵手了，$n!你不但證明了你的技能，你還勝過了達瑞爾，這是你在我的名冊中得到了額外的分數!$B$B歡迎你隨時來到這裡。', `MaleText_loc7`='¡Te has hecho $gtodo un cazador:toda una cazadora;, $n! No solo has probado tus habilidades sino que has derrotado a Daryl, ¡y eso te da aún más puntos!$B$BSiempre serás $gbienvenido:bienvenida;.' WHERE `ID`=5831;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나를 소환하다니, 어리석기는! 이제 죽어라!', `MaleText_loc4`='是你召唤我来的，愚蠢的东西！现在受死吧！', `MaleText_loc5`='是你召喚我來的，愚蠢的東西!現在受死吧!', `MaleText_loc7`='¡Me has invocado, idiota! ¡Y ahora MUERE!' WHERE `ID`=5832;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='독을 짜내세요, 존.', `MaleText_loc4`='挤“奶”吧，约翰。', `MaleText_loc5`='約翰，餵我奶喝。', `MaleText_loc7`='Ordéñame, John.', `FemaleText_loc1`='독을 짜내세요, 존.', `FemaleText_loc4`='挤“奶”吧，约翰。', `FemaleText_loc5`='約翰，餵我奶喝。', `FemaleText_loc7`='Ordéñame, John.' WHERE `ID`=5833;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='후후, 기꺼이... 이 순간을 조금만 더 즐기겠소.', `MaleText_loc4`='很愿意……只是让我再多回味一下这一刻。', `MaleText_loc5`='很願意...只是讓我再多回味一下這一刻。', `MaleText_loc7`='Será un placer... pero déjame saborear este momento durante un minuto más.' WHERE `ID`=5834;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 하세요. 어서...', `MaleText_loc4`='做吧……现在就做。', `MaleText_loc5`='做吧...現在就做。', `MaleText_loc7`='Hazlo... Hazlo ya.', `FemaleText_loc1`='어서 하세요. 어서...', `FemaleText_loc4`='做吧……现在就做。', `FemaleText_loc5`='做吧...現在就做。', `FemaleText_loc7`='Hazlo... Hazlo ya.' WHERE `ID`=5835;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법 지구에 있지. 무시무시한 해골처럼 생긴 건물에서 찾아봐.', `MaleText_loc4`='他们在魔法区。去那幢恐怖的骷髅楼中找他们吧。', `MaleText_loc5`='他們在魔法區。去那幢恐怖的骷髏樓中找他們吧。', `MaleText_loc7`='Están en el Barrio de la Magia. Búscalos en el tenebroso edificio de las calaveras.', `FemaleText_loc1`='마법 지구에 있지. 무시무시한 해골처럼 생긴 건물에서 찾아봐.', `FemaleText_loc4`='他们在魔法区。去那幢恐怖的骷髅楼中找他们吧。', `FemaleText_loc5`='他們在魔法區。去那幢恐怖的骷髏樓中找他們吧。', `FemaleText_loc7`='Están en el Barrio de la Magia. Búscalos en el tenebroso edificio de las calaveras.' WHERE `ID`=5836;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디 있는지 알아! 언더시티 외곽, 마법 지구, 해골 건물...', `MaleText_loc4`='我们知道他们在哪儿！他们就在城市外环魔法区的骷髅建筑物中。', `MaleText_loc5`='我們知道他們在哪兒!他們就在城市外環魔法區的骷髏建築物中。', `MaleText_loc7`='¡Nosotros saber dónde están! Edificio de las calaveras en el Barrio de la Magia, en el cinturón exterior de la ciudad.', `FemaleText_loc1`='어디 있는지 알아! 언더시티 외곽, 마법 지구, 해골 건물...', `FemaleText_loc4`='我们知道他们在哪儿！他们就在城市外环魔法区的骷髅建筑物中。', `FemaleText_loc5`='我們知道他們在哪兒!他們就在城市外環魔法區的骷髏建築物中。', `FemaleText_loc7`='¡Nosotros saber dónde están! Edificio de las calaveras en el Barrio de la Magia, en el cinturón exterior de la ciudad.' WHERE `ID`=5837;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상업 지구 중앙에 있는 탑이 은행이야. 금방 찾아.', `MaleText_loc4`='银行就在贸易区中心的塔中。你不会找不到的。', `MaleText_loc5`='銀行就在貿易區中心的塔中。你不會找不到的。', `MaleText_loc7`='Banco en torre central, Barrio del Comercio. No falléis.', `FemaleText_loc1`='상업 지구 중앙에 있는 탑이 은행이야. 금방 찾아.', `FemaleText_loc4`='银行就在贸易区中心的塔中。你不会找不到的。', `FemaleText_loc5`='銀行就在貿易區中心的塔中。你不會找不到的。', `FemaleText_loc7`='Banco en torre central, Barrio del Comercio. No falléis.' WHERE `ID`=5838;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나, 눈 하나지만 너보다 잘 볼 수 있다! 언더시티 중앙에 은행 있어!', `MaleText_loc4`='我们只有一只眼睛，但看得比你远！银行就在幽暗城中心！', `MaleText_loc5`='我們只有一隻眼睛，但看得比你遠!銀行就在幽暗城中心!', `MaleText_loc7`='¡Tenemos un ojo y vemos mejor que tú! ¡Banco en el centro de Entrañas!', `FemaleText_loc1`='나, 눈 하나지만 너보다 잘 볼 수 있다! 언더시티 중앙에 은행 있어!', `FemaleText_loc4`='我们只有一只眼睛，但看得比你远！银行就在幽暗城中心！', `FemaleText_loc5`='我們只有一隻眼睛，但看得比你遠!銀行就在幽暗城中心!', `FemaleText_loc7`='¡Tenemos un ojo y vemos mejor que tú! ¡Banco en el centro de Entrañas!' WHERE `ID`=5839;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마이클 가레트? 상업 지구 위쪽에 있다.', `MaleText_loc4`='贸易区上层的迈克尔·加勒特。', `MaleText_loc5`='貿易區上層的麥可·加勒特。', `MaleText_loc7`='Michael Garrett en el cinturón superior en el Barrio del Comercio.', `FemaleText_loc1`='마이클 가레트? 상업 지구 위쪽에 있다.', `FemaleText_loc4`='贸易区上层的迈克尔·加勒特', `FemaleText_loc5`='貿易區上層的麥可·加勒特。', `FemaleText_loc7`='Michael Garrett en el cinturón superior en el Barrio del Comercio.' WHERE `ID`=5840;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상업 지구 위층에 박쥐 조련사 있다.', `MaleText_loc4`='贸易区上层的蝙蝠管理员。', `MaleText_loc5`='貿易區上層的蝙蝠管理員。', `MaleText_loc7`='El hombre de los murciélagos está en el nivel superior del Barrio del Comercio.', `FemaleText_loc1`='상업 지구 위층에 박쥐 조련사 있다.', `FemaleText_loc4`='贸易区上层的蝙蝠管理员。', `FemaleText_loc5`='貿易區上層的蝙蝠管理員。', `FemaleText_loc7`='El hombre de los murciélagos está en el nivel superior del Barrio del Comercio.' WHERE `ID`=5841;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크리스토퍼 드라쿨은... 상업 지구 동쪽에.', `MaleText_loc4`='噢，你在寻找贸易区的克里斯托弗·德库尔。他在东部的平台上。', `MaleText_loc5`='噢，你在尋找貿易區的克里斯多夫·德庫爾。他在東部的平臺上。', `MaleText_loc7`='Sí, buscas a Christopher Drakul en el Barrio del Comercio. En plataforma oriental.', `FemaleText_loc1`='크리스토퍼 드라쿨은... 상업 지구 동쪽에.', `FemaleText_loc4`='噢，你在寻找贸易区的克里斯托弗·德库尔。他在东部的平台上。', `FemaleText_loc5`='噢，你在尋找貿易區的克里斯多夫·德庫爾。他在東部的平臺上。', `FemaleText_loc7`='Sí, buscas a Christopher Drakul en el Barrio del Comercio. En plataforma oriental.' WHERE `ID`=5842;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리도 너네 길드 들 수 있어? 안 돼? 몸무게 제한? 상업 지구 동쪽에 길드 사무관 찾아봐.', `MaleText_loc4`='我们加入公会了？没有？好吧，去贸易区的东平台找公会注册员吧。', `MaleText_loc5`='我們加入公會了?沒有?好吧，去貿易區的東平臺找公會註冊員吧。', `MaleText_loc7`='¿Unir a hermandad? Bien, encontrarás al maestro de hermandad en la plataforma oriental del Barrio del Comercio.', `FemaleText_loc1`='우리도 너네 길드 들 수 있어? 안 돼? 몸무게 제한? 상업 지구 동쪽에 길드 사무관 찾아봐.', `FemaleText_loc4`='我们加入公会了？没有？好吧，去贸易区的东平台找公会注册员吧。', `FemaleText_loc5`='我們加入公會了?沒有?好吧，去貿易區的東平臺找公會註冊員吧。', `FemaleText_loc7`='¿Unir a hermandad? Bien, encontrarás al maestro de hermandad en la plataforma oriental del Barrio del Comercio.' WHERE `ID`=5843;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상업 지구 위층, 여관주인 노먼한테 말해봐.', `MaleText_loc4`='你得去贸易区找旅店老板诺曼谈谈。', `MaleText_loc5`='你得去貿易區找旅店老闆諾曼談談。', `MaleText_loc7`='Con quien tienes que hablar es con el tabernero Norman en el cinturón superior del Barrio del Comercio.', `FemaleText_loc1`='상업 지구 위층, 여관주인 노먼한테 말해봐.', `FemaleText_loc4`='你得去贸易区找旅店老板诺曼谈谈。', `FemaleText_loc5`='你得去貿易區找旅店老闆諾曼談談。', `FemaleText_loc7`='Con quien tienes que hablar es con el tabernero Norman en el cinturón superior del Barrio del Comercio.' WHERE `ID`=5844;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마음이 사악한 자에겐 휴식 없다. 당신은 괜찮을 거야. 상업 지구 위층, 여관주인 노먼을 찾아봐.', `MaleText_loc4`='不能让邪恶势力有喘息的机会，但是我想你还是需要一些休息。去贸易区的上层找旅店老板诺曼吧。', `MaleText_loc5`='不能讓邪惡勢力有喘息的機會，但是我想你還是需要一些休息。去貿易區的上層找旅店老闆諾曼吧。', `MaleText_loc7`='Que no descanse el malvado, pero suponemos que no hay problema contigo. Encontrarás al tabernero Norman en el anillo superior del Barrio del Comercio.', `FemaleText_loc1`='마음이 사악한 자에겐 휴식 없다. 당신은 괜찮을 거야. 상업 지구 위층, 여관주인 노먼을 찾아봐.', `FemaleText_loc4`='不能让邪恶势力有喘息的机会，但是我想你还是需要一些休息。去贸易区的上层找旅店老板诺曼吧。', `FemaleText_loc5`='不能讓邪惡勢力有喘息的機會，但是我想你還是需要一些休息。去貿易區的上層找旅店老闆諾曼吧。', `FemaleText_loc7`='Que no descanse el malvado, pero suponemos que no hay problema contigo. Encontrarás al tabernero Norman en el anillo superior del Barrio del Comercio.' WHERE `ID`=5845;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우체통... 한가운데... 상업 지구 위층 여관 옆에...', `MaleText_loc4`='在交易区中心就有的邮箱……就在旅馆旁边。', `MaleText_loc5`='在交易區中心就有的郵箱...就在旅館旁邊。', `MaleText_loc7`='Buzón en el centro de la ciudad, Barrio del Comercio, cinturón superior... junto a la posada.', `FemaleText_loc1`='우체통... 한가운데... 상업 지구 위층 여관 옆에...', `FemaleText_loc4`='在交易区中心就有的邮箱……就在旅馆旁边。', `FemaleText_loc5`='在交易區中心就有的郵箱...就在旅館旁邊。', `FemaleText_loc7`='Buzón en el centro de la ciudad, Barrio del Comercio, cinturón superior... junto a la posada.' WHERE `ID`=5846;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 파... 파쇄의 톱날도끼 팔렸나? 상업 지구 위층, 여관 옆 우체통 찾아.', `MaleText_loc4`='我们得确认一下是否碎……碎……碎灵斧是不是卖掉了。去贸易区上层的旅馆旁找邮箱吧。', `MaleText_loc5`='我們得確認一下是否碎...碎...碎靈斧是不是賣掉了。去貿易區上層的旅館旁找郵箱吧。', `MaleText_loc7`='Nosotros necesitar cheque para ver si nuestro Rebana... Rebana... Rebanasesos se vendió en la subasta. Tú encuentras un buzón junto a la posada en el anillo superior del Barrio del Comercio.', `FemaleText_loc1`='우리 파... 파쇄의 톱날도끼 팔렸나? 상업 지구 위층, 여관 옆 우체통 찾아.', `FemaleText_loc4`='我们得确认一下是否碎……碎……碎灵斧是不是卖掉了。去贸易区上层的旅馆旁找邮箱吧。', `FemaleText_loc5`='我們得確認一下是否碎...碎...碎靈斧是不是賣掉了。去貿易區上層的旅館旁找郵箱吧。', `FemaleText_loc7`='Nosotros necesitar cheque para ver si nuestro Rebana... Rebana... Rebanasesos se vendió en la subasta. Tú encuentras un buzón junto a la posada en el anillo superior del Barrio del Comercio.' WHERE `ID`=5847;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경매장 여기 있어. 도시 중앙에 있는 원 쪽에.', `MaleText_loc4`='中央地带有拍卖行，就在南边。', `MaleText_loc5`='拍賣場就在中環區。', `MaleText_loc7`='Tenemos casa de subastas en el cinturón central.', `FemaleText_loc1`='경매장 여기 있어. 도시 중앙에 있는 원 쪽에.', `FemaleText_loc4`='中央地带有拍卖行，就在南边。', `FemaleText_loc5`='拍賣場就在中環區。', `FemaleText_loc7`='Tenemos casa de subastas en el cinturón central.' WHERE `ID`=5848;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도시 중앙에 있는 원 쪽에... 어서 뛰어!', `MaleText_loc4`='中部区域，南侧。去吧！', `MaleText_loc5`='中環區!快去吧!', `MaleText_loc7`='Cinturón central. ¡Ve!', `FemaleText_loc1`='도시 중앙에 있는 원 쪽에... 어서 뛰어!', `FemaleText_loc4`='中部区域，南侧。去吧！', `FemaleText_loc5`='中環區!快去吧!', `FemaleText_loc7`='Cinturón central. ¡Ve!' WHERE `ID`=5849;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조그만 고블린... 로데론의 폐허 북쪽 건물 옥상에... 언더시티에서 나가.', `MaleText_loc4`='洛丹伦废墟以北建筑顶端那有地精。离开幽暗城，前往那儿吧。', `MaleText_loc5`='羅德隆廢墟以北建築頂端那有哥布林。離開幽暗城，前往那兒吧。', `MaleText_loc7`='Pequeño goblin encima del edificio al norte de las ruinas de Lordaeron. Deja Entrañas y ve allí.', `FemaleText_loc1`='조그만 고블린... 로데론의 폐허 북쪽 건물 옥상에... 언더시티에서 나가.', `FemaleText_loc4`='洛丹伦废墟以北建筑顶端那有地精。离开幽暗城，前往那儿吧。', `FemaleText_loc5`='羅德隆廢墟以北建築頂端那有哥布林。離開幽暗城，前往那兒吧。', `FemaleText_loc7`='Pequeño goblin encima del edificio al norte de las ruinas de Lordaeron. Deja Entrañas y ve allí.' WHERE `ID`=5850;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폐허의 북쪽 위로 풍선 보여. 타면 멀리 간다.', `MaleText_loc4`='我们可以看见从废墟北部升起的飞艇。它会将你带到遥远的地方。', `MaleText_loc5`='我們可以看見從廢墟北部升起的飛艇。它會將你帶到遙遠的地方。', `MaleText_loc7`='Nosotros ver un globo al norte de las ruinas, por arriba. Te llevará a lugares muy lejanos.', `FemaleText_loc1`='폐허의 북쪽 위로 풍선 보여. 타면 멀리 간다.', `FemaleText_loc4`='我们看见废墟北部上空升起的飞艇。它会将你带到遥远的地方。', `FemaleText_loc5`='我們看見廢墟北部上空升起的飛艇。它會將你帶到遙遠的地方。', `FemaleText_loc7`='Nosotros ver un globo al norte de las ruinas, por arriba. Te llevará a lugares muy lejanos.' WHERE `ID`=5851;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상급 사제? 군사 지구 외곽으로 가서 찾아봐.', `MaleText_loc4`='牧师训练者？去军事区的外圈找找看。', `MaleText_loc5`='牧師訓練師?去軍事區的外圈找找看。', `MaleText_loc7`='¿Instructor de sacerdotes? Dirígete al cinturón exterior del Barrio de la Guerra y búscalos allí.', `FemaleText_loc1`='상급 사제? 군사 지구 외곽으로 가서 찾아봐.', `FemaleText_loc4`='牧师训练者？去军事区的外圈找找看。', `FemaleText_loc5`='牧師訓練師?去軍事區的外圈找找看。', `FemaleText_loc7`='¿Instructor de sacerdotes? Dirígete al cinturón exterior del Barrio de la Guerra y búscalos allí.' WHERE `ID`=5852;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어.. 어... 군사 지구의 그 부정한 놈들... 도시 외곽에 있는 건물 둘러싸고 있어.', `MaleText_loc4`='哼。军事区的邪恶的生物站在城市外圈的主建筑物周围。', `MaleText_loc5`='哼哼。軍事區的邪惡的生物站在城市外圈的主建築物周圍。', `MaleText_loc7`='Uy, uy. Impuros en el Barrio de la Guerra alrededor del edificio principal en el cinturón exterior de la ciudad.', `FemaleText_loc1`='어.. 어... 군사 지구의 그 부정한 놈들... 도시 외곽에 있는 건물 둘러싸고 있어.', `FemaleText_loc4`='哼。军事区的邪恶的生物站在城市外圈的主建筑物周围。', `FemaleText_loc5`='哼哼。軍事區的邪惡的生物站在城市外圈的主建築物周圍。', `FemaleText_loc7`='Uy, uy. Impuros en el Barrio de la Guerra alrededor del edificio principal en el cinturón exterior de la ciudad.' WHERE `ID`=5853;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그 머리를 가져가면 다릴 녀석, 겁 좀 먹을 거예요. 당해도 싸지, 못된 녀석. 호호! 이걸 보고 어떤 표정을 지을지 기대가 되는걸요.', `FemaleText_loc4`='这肯定会让达瑞尔大吃一惊。是他活该，这个傲慢又该死的混蛋。但是哈！把这个给他瞧瞧，我迫不及待地想看看他脸上的表情。', `FemaleText_loc5`='拿到那顆頭顱肯定會讓達瑞爾大吃一驚。是他活該，這個傲慢又該死的混蛋。但是，哇哈!我等不及想看到他見到這東西時臉上的表情。', `FemaleText_loc7`='Coge esa cabeza y le darás a Daryl un buen susto. No es que no se lo merezca... necio arrogante. Pero ¡ja! no puedo esperar a ver su cara cuando se la enseñes.' WHERE `ID`=5854;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='원정순찰대 오두막에 오신 것을 환영해요, $n!', `FemaleText_loc4`='欢迎来到旅行者营地，$n！', `FemaleText_loc5`='歡迎來到遠行者小屋，$n!', `FemaleText_loc7`='¡$GBienvenido:Bienvenida; a la Cabaña del Errante, $n!' WHERE `ID`=5855;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도적 지구 외곽... 건물로 가봐.', `MaleText_loc4`='潜行者都在盗贼区外环的建筑物中。', `MaleText_loc5`='盜賊都在盜賊區外環的建築物中。', `MaleText_loc7`='Pícaros en el edificio en el anillo exterior del Barrio de los Pícaros.', `FemaleText_loc1`='도적 지구 외곽... 건물로 가봐.', `FemaleText_loc4`='潜行者都在盗贼区外环的建筑物中。', `FemaleText_loc5`='盜賊都在盜賊區外環的建築物中。', `FemaleText_loc7`='Pícaros en el edificio en el anillo exterior del Barrio de los Pícaros.' WHERE `ID`=5856;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 놈들에게 숨는 법 배운다. 언더시티 도적 지구 외곽으로 가.', `MaleText_loc4`='他们教我如何“妙手空空顺手牵羊”。你可以在幽暗城外围的盗贼区找到他们。', `MaleText_loc5`='他們教我如何偷竊。你可以在幽暗城週邊的盜賊區找到他們。', `MaleText_loc7`='Me enseñaron a moverme en sigilo. Los encontrarás en el Barrio de los Pícaros en el anillo exterior de Entrañas.', `FemaleText_loc1`='우리 놈들에게 숨는 법 배운다. 언더시티 도적 지구 외곽으로 가.', `FemaleText_loc4`='他们教我如何“妙手空空顺手牵羊”。你可以在幽暗城外围的盗贼区找到他们。', `FemaleText_loc5`='他們教我如何偷竊。你可以在幽暗城週邊的盜賊區找到他們。', `FemaleText_loc7`='Me enseñaron a moverme en sigilo. Los encontrarás en el Barrio de los Pícaros en el anillo exterior de Entrañas.' WHERE `ID`=5857;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신은 언제나 환영이에요, $n. 웃게 해줘서 고마워요. 다릴 걱정은 안 하셔도 돼요. 당해도 싼 녀석이니까!', `FemaleText_loc4`='你在这里永远都受欢迎，$n。谢谢你带来的欢笑--还有不要担心达瑞尔，他就是这样一个人！', `FemaleText_loc5`='你在這裡永遠都受歡迎，$n。謝謝你帶來的歡笑--還有不要擔心達瑞爾，他就是這樣一個人!', `FemaleText_loc7`='Siempre eres $gbienvenido:bienvenida; aquí, $n. Gracias por el buen rato que me has hecho pasar. Y no te preocupes por Daryl, ¡tenía una en camino!' WHERE `ID`=5858;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흑마법사들 마법 지구 외곽에, 마법사들이랑 있는 거 봤다.', `MaleText_loc4`='术士训练者在法师区外环中的建筑物中，他们跟法师呆在一起。', `MaleText_loc5`='術士訓練師在魔法區外環中的建築物中，他們跟法師待在一起。', `MaleText_loc7`='Instructores de brujos en el Barrio de la Magia, en el edificio del cinturón exterior con los magos.', `FemaleText_loc1`='흑마법사들 마법 지구 외곽에, 마법사들이랑 있는 거 봤다.', `FemaleText_loc4`='术士训练者在法师区外环中的建筑物中，他们跟法师呆在一起。', `FemaleText_loc5`='術士訓練師在魔法區外環中的建築物中，他們跟法師待在一起。', `FemaleText_loc7`='Instructores de brujos en el Barrio de la Magia, en el edificio del cinturón exterior con los magos.' WHERE `ID`=5859;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 애완용 지옥사냥개 있으면 좋겠다. 먹을 거도 주고, 막대기 던지기 놀이도 하고, 잘 놀아줄 수 있는데. 흑마법사? 도시 외곽의 마법 지구에 있다.', `MaleText_loc4`='我们想让地狱犬成为宠物。我们喂养它、善待它并教它学会去拣我丢出去的木棒。去城市外环的法师区找术士吧。', `MaleText_loc5`='我們想讓惡魔犬成為寵物。我們餵養它、善待它並教它學會去揀我丟出去的木棒。去城市外環的魔法區找術士吧。', `MaleText_loc7`='Nosotros querer un manáfago como mascota. Le alimentamos, tratamos bien y le enseñamos a buscar la pelota. Encontrarás brujos en el Barrio de la Magia, en el cinturón exterior de la ciudad.', `FemaleText_loc1`='나 애완용 지옥사냥개 있으면 좋겠다. 먹을 거도 주고, 막대기 던지기 놀이도 하고, 잘 놀아줄 수 있는데. 흑마법사? 도시 외곽의 마법 지구에 있다.', `FemaleText_loc4`='我们想让地狱犬成为宠物。我们喂养它、善待它并教它学会去拣我丢出去的木棒。去城市外环的法师区找术士吧。', `FemaleText_loc5`='我們想讓惡魔犬成為寵物。我們餵養它、善待它並教它學會去揀我丟出去的木棒。去城市外環的魔法區找術士吧。', `FemaleText_loc7`='Nosotros querer un manáfago como mascota. Le alimentamos, tratamos bien y le enseñamos a buscar la pelota. Encontrarás brujos en el Barrio de la Magia, en el cinturón exterior de la ciudad.' WHERE `ID`=5860;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도시 외곽, 군사 지구의 건물 안에 있다.', `MaleText_loc4`='在城市外围军事区建筑中。', `MaleText_loc5`='在城市週邊軍事區建築中。', `MaleText_loc7`='En edificio del Barrio de la Guerra, en el cinturón exterior de la ciudad.', `FemaleText_loc1`='도시 외곽, 군사 지구의 건물 안에 있다.', `FemaleText_loc4`='在城市外围军事区建筑中。', `FemaleText_loc5`='在城市週邊軍事區建築中。', `FemaleText_loc7`='En edificio del Barrio de la Guerra, en el cinturón exterior de la ciudad.' WHERE `ID`=5861;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전사 싸움 잘해. 언더시티 외곽, 군사 지구에서 찾아.', `MaleText_loc4`='战士训练师都是作战高手。你可以去幽暗城外环的军事区找他们。', `MaleText_loc5`='戰士訓練師都是作戰高手。你可以去幽暗城的軍事區外環找他們。', `MaleText_loc7`='Los instructores de guerreros combaten bien. Tú los encuentras en el Barrio de la Guerra en el cinturón exterior de Entrañas.', `FemaleText_loc1`='전사 싸움 잘해. 언더시티 외곽, 군사 지구에서 찾아.', `FemaleText_loc4`='战士训练师都是作战高手。你可以去幽暗城外环的军事区找他们。', `FemaleText_loc5`='戰士訓練師都是作戰高手。你可以去幽暗城的軍事區外環找他們。', `FemaleText_loc7`='Los instructores de guerreros combaten bien. Tú los encuentras en el Barrio de la Guerra en el cinturón exterior de Entrañas.' WHERE `ID`=5862;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연금술 실험실로 가봐. 그곳에, 학자 허버트 핼시와 학자 마쉬, 물약 들고 꼼지락대고 있어.', `MaleText_loc4`='你可以去炼金房看看。那是赫伯特·哈尔希医生和马尔什医生练习的地方。', `MaleText_loc5`='你可以去鍊金房看看。那是赫伯特·哈爾希醫生和馬許醫生練習的地方。', `MaleText_loc7`='Tú miras en El Apothecarium. Allí consultas del doctor Herbert Halsey y del doctor Marsh.', `FemaleText_loc1`='연금술 실험실로 가봐. 그곳에, 학자 허버트 핼시와 학자 마쉬, 물약 들고 꼼지락대고 있어.', `FemaleText_loc4`='你可以去炼金房看看。那是赫伯特·哈尔希医生和马尔什医生练习的地方。', `FemaleText_loc5`='你可以去鍊金房看看。那是赫伯特·哈爾希醫生和馬許醫生練習的地方。', `FemaleText_loc7`='Tú miras en El Apothecarium. Allí consultas del doctor Herbert Halsey y del doctor Marsh.' WHERE `ID`=5863;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연금술 실험실에 학자 허버트 핼시 있다. 우리 태어난 곳이다. 당신도 우리처럼 잘 꿰매줄 거야.', `MaleText_loc4`='在我们出生之地炼金房的赫伯特·哈尔希医生的医术高于我们，他会医好你的背部的。', `MaleText_loc5`='在我們出生之地鍊金房的赫伯特·哈爾希醫生的醫術高於我們，他會醫好你的背部的。', `MaleText_loc7`='Doctor Herbert Halsey en El Apothecarium, donde nosotros nacer. Podría coser tu espalda mejor como nosotros.', `FemaleText_loc1`='연금술 실험실에 학자 허버트 핼시 있다. 우리 태어난 곳이다. 당신도 우리처럼 잘 꿰매줄 거야.', `FemaleText_loc4`='在我们出生之地炼金房的赫伯特·哈尔希医生的医术高于我们，他会医好你的背部的。', `FemaleText_loc5`='在我們出生之地鍊金房的赫伯特·哈爾希醫生的醫術高於我們，他會醫好你的背部的。', `FemaleText_loc7`='Doctor Herbert Halsey en El Apothecarium, donde nosotros nacer. Podría coser tu espalda mejor como nosotros.' WHERE `ID`=5864;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제임스 반 브런트 군사 지구 내곽에 있다.', `MaleText_loc4`='内环军事区的詹姆斯·范·布朗特。', `MaleText_loc5`='詹姆士·凡·布朗特在軍事區的內環。', `MaleText_loc7`='James Van Brunt en el Barrio de la Guerra en el cinturón exterior.', `FemaleText_loc1`='제임스 반 브런트 군사 지구 내곽에 있다.', `FemaleText_loc4`='内环军事区的詹姆斯·范·布朗特。', `FemaleText_loc5`='詹姆士·凡·布朗特在軍事區的內環。', `FemaleText_loc7`='James Van Brunt en el Barrio de la Guerra en el cinturón exterior.' WHERE `ID`=5865;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제임스 반 브런트 군사 지구 내곽에서 일해. 사슬 잘 만들어.', `MaleText_loc4`='詹姆斯·范·布朗特的工作地点在军事区内环。他能为我们打造很好的锁链。', `MaleText_loc5`='詹姆士·凡·布朗特的工作地點在軍事區內環。他能為我們打造很好的鎖鍊。', `MaleText_loc7`='Cinturón interior del Barrio de la Guerra, donde trabaja James Van Brunt. Él hacernos buena malla.', `FemaleText_loc1`='제임스 반 브런트 군사 지구 내곽에서 일해. 사슬 잘 만들어.', `FemaleText_loc4`='詹姆斯·范·布朗特的工作地点在军事区内环。他能为我们打造很好的锁链。', `FemaleText_loc5`='詹姆士·凡·布朗特的工作地點在軍事區內環。他能為我們打造很好的鎖鍊。', `FemaleText_loc7`='Cinturón interior del Barrio de la Guerra, donde trabaja James Van Brunt. Él hacernos buena malla.' WHERE `ID`=5866;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='유니스 버치? 상업 지구!', `MaleText_loc4`='贸易区的那个尤奈斯·伯奇。', `MaleText_loc5`='貿易區的那個尤奈斯·伯奇。', `MaleText_loc7`='Eunice Burch en el Barrio del Comercio.', `FemaleText_loc1`='유니스 버치? 상업 지구!', `FemaleText_loc4`='贸易区的那个尤奈斯·伯奇。', `FemaleText_loc5`='貿易區的那個尤奈斯·伯奇。', `FemaleText_loc7`='Eunice Burch en el Barrio del Comercio.' WHERE `ID`=5867;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='유니스 버치... 팔다 남은 음식만 줘. 상업 지구로 가.', `MaleText_loc4`='尤奈斯·伯奇卖剩下的零部件。你可以到贸易区找她。', `MaleText_loc5`='尤奈斯·伯奇賣剩下的零部件。你可以到貿易區找她。', `MaleText_loc7`='Eunice Burch vende sobras. La encontrarás en el Barrio del Comercio.', `FemaleText_loc1`='유니스 버치... 팔다 남은 음식만 줘. 상업 지구로 가.', `FemaleText_loc4`='尤奈斯·伯奇卖剩下的零部件。你可以到贸易区找她。', `FemaleText_loc5`='尤奈斯·伯奇賣剩下的零部件。你可以到貿易區找她。', `FemaleText_loc7`='Eunice Burch vende sobras. La encontrarás en el Barrio del Comercio.' WHERE `ID`=5868;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연금술 실험실 내곽으로 가. 거기 라비니아 크로...', `MaleText_loc4`='到炼金房的内环去。拉文尼亚就在那儿。', `MaleText_loc5`='你到鍊金房的內環去。拉玟妮雅·克洛威就在那裡。', `MaleText_loc7`='Ve al cinturón interior de El Apothecarium. Lavinia Crowe está allí.', `FemaleText_loc1`='연금술 실험실 내곽으로 가. 거기 라비니아 크로...', `FemaleText_loc4`='到炼金房的内环去。拉文尼亚就在那儿。', `FemaleText_loc5`='你到鍊金房的內環去。拉玟妮雅·克洛威就在那裡。', `FemaleText_loc7`='Ve al cinturón interior de El Apothecarium. Lavinia Crowe está allí.' WHERE `ID`=5869;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 아가씨 마법 물건 만들기 가르쳐 준다. 연금술 실험실 내곽에 있어.', `MaleText_loc4`='拉文尼亚女士教你制作魔法物品。她就在炼金房的内环。', `MaleText_loc5`='幽靈女士教你製作魔法物品。她就在鍊金房的內環。', `MaleText_loc7`='La señora te enseña a hacer objetos mágicos. Está en el cinturón interior de El Apothecarium.', `FemaleText_loc1`='그 아가씨 마법 물건 만들기 가르쳐 준다. 연금술 실험실 내곽에 있어.', `FemaleText_loc4`='拉文尼亚女士教你制作魔法物品。她就在炼金房的内环。', `FemaleText_loc5`='幽靈女士教你製作魔法物品。她就在鍊金房的內環。', `FemaleText_loc7`='La señora te enseña a hacer objetos mágicos. Está en el cinturón interior de El Apothecarium.' WHERE `ID`=5870;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='프랭클린 로이드? 언더시티 외곽 도적 지구에 있다.', `MaleText_loc4`='幽暗城外环盗贼区的弗兰克林·洛伊德。', `MaleText_loc5`='富蘭克林·洛伊德就在幽暗城盜賊區的外環。', `MaleText_loc7`='Franklin Lloyd en el Barrio de los Pícaros, en el anillo exterior de Entrañas.', `FemaleText_loc1`='프랭클린 로이드? 언더시티 외곽 도적 지구에 있다.', `FemaleText_loc4`='幽暗城外环盗贼区的弗兰克林·洛伊德。', `FemaleText_loc5`='富蘭克林·洛伊德就在幽暗城盜賊區的外環。', `FemaleText_loc7`='Franklin Lloyd en el Barrio de los Pícaros, en el anillo exterior de Entrañas.' WHERE `ID`=5871;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헤... 폭탄? 우리 꽝 좋아해. 그레이엄 반 탈렌 보면 만들기 가르쳐 줘. 도적 지구 외곽에 있다.', `MaleText_loc4`='嗨，炸弹，我们喜欢炸弹。格拉哈姆·范·塔伦会教你如何制造炸弹的。他居住在盗贼区的外层。', `MaleText_loc5`='嗨，炸彈，我們喜歡炸彈。格拉哈姆·範·塔倫會教你如何製造炸彈的。他居住在盜賊區的外層。', `MaleText_loc7`='Heh, bombas, a nosotros gustan las bombas. Graham Van Talen te enseña a hacer. En el anillo exterior del Barrio de los Pícaros.', `FemaleText_loc1`='헤... 폭탄? 우리 꽝 좋아해. 그레이엄 반 탈렌 보면 만들기 가르쳐 줘. 도적 지구 외곽에 있다.', `FemaleText_loc4`='嗨，炸弹，我们喜欢炸弹。格拉哈姆·范·塔伦会教你如何制造炸弹的。他居住在盗贼区的外层。', `FemaleText_loc5`='嗨，炸彈，我們喜歡炸彈。格拉哈姆·範·塔倫會教你如何製造炸彈的。他居住在盜賊區的外層。', `FemaleText_loc7`='Heh, bombas, a nosotros gustan las bombas. Graham Van Talen te enseña a hacer. En el anillo exterior del Barrio de los Pícaros.' WHERE `ID`=5872;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 안다. 그녀 좋아. 메리 에드라스 도적 지구 내곽에 있어.', `MaleText_loc4`='我们很了解玛丽·艾塔斯。她就在盗贼区的内环。', `MaleText_loc5`='我們很瞭解瑪麗·艾塔斯。她就在盜賊區的內環。', `MaleText_loc7`='Nosotros conocerla bien. Ella Mary Edras, en el anillo interior del Barrio de los Pícaros.', `FemaleText_loc1`='나 안다. 그녀 좋아. 메리 에드라스 도적 지구 내곽에 있어.', `FemaleText_loc4`='我们很了解玛丽·艾塔斯。她就在盗贼区的内环。', `FemaleText_loc5`='我們很瞭解瑪麗·艾塔斯。她就在盜賊區的內環。', `FemaleText_loc7`='Nosotros conocerla bien. Ella Mary Edras, en el anillo interior del Barrio de los Pícaros.' WHERE `ID`=5873;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 다치면 꿰매주고 붕대 감아줘. 도적 지구 내곽에서.', `MaleText_loc4`='当我们受伤时，她总为我们医治。你可以在盗贼区找到她。', `MaleText_loc5`='當我們受傷時，她總為我們醫治。你可以在盜賊區找到她。', `MaleText_loc7`='Lady cosernos y vendarnos si nos herimos. La encontrarás en el anillo interior del Barrio de los Pícaros.', `FemaleText_loc1`='우리 다치면 꿰매주고 붕대 감아줘. 도적 지구 내곽에서.', `FemaleText_loc4`='当我们受伤时，她总为我们医治。你可以在盗贼区找到她。', `FemaleText_loc5`='當我們受傷時，她總為我們醫治。你可以在盜賊區找到她。', `FemaleText_loc7`='Lady cosernos y vendarnos si nos herimos. La encontrarás en el anillo interior del Barrio de los Pícaros.' WHERE `ID`=5874;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법 지구 가면 알만드 크롬웰 금방 찾아. 둑에 서 있다.', `MaleText_loc4`='你在魔法区不会找不到阿曼德·克伦威尔的。他就站在码头上。', `MaleText_loc5`='你在魔法區不會找不到阿曼德·克倫威爾的。他就站在碼頭上。', `MaleText_loc7`='No olvidar a Armand Cromwell en el Barrio de la Magia. Está en los embarcaderos.', `FemaleText_loc1`='마법 지구 가면 알만드 크롬웰 금방 찾아. 둑에 서 있다.', `FemaleText_loc4`='你在魔法区不会找不到阿曼德·克伦威尔的。他就站在码头上。', `FemaleText_loc5`='你在魔法區不會找不到阿曼德·克倫威爾的。他就站在碼頭上。', `FemaleText_loc7`='No olvidar a Armand Cromwell en el Barrio de la Magia. Está en los embarcaderos.' WHERE `ID`=5875;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알만드 크롬웰... 늘 마법 지구의 둑에 서 있다. 그거 알아? 녹색 물에 사는 물고기 맛좋아. 먹어봐.', `MaleText_loc4`='阿曼德·克伦威尔在魔法区的码头附近垂钓。试试去那儿找他。', `MaleText_loc5`='阿曼德·克倫威爾在魔法區的碼頭附近垂釣。試試去那兒找他。', `MaleText_loc7`='Armand Cromwell siempre está en los embarcaderos del Barrio de la Magia. Los peces del lodo verde son muy ricos. Tú probar.', `FemaleText_loc1`='알만드 크롬웰... 늘 마법 지구의 둑에 서 있다. 그거 알아? 녹색 물에 사는 물고기 맛좋아. 먹어봐.', `FemaleText_loc4`='阿曼德·克伦威尔在魔法区的码头附近垂钓。试试去那儿找他。', `FemaleText_loc5`='阿曼德·克倫威爾在魔法區的碼頭附近垂釣。試試去那兒找他。', `FemaleText_loc7`='Armand Cromwell siempre está en los embarcaderos del Barrio de la Magia. Los peces del lodo verde son muy ricos. Tú probar.' WHERE `ID`=5876;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마사 알리스타 찾아? 연금술 실험실 내곽에 있다.', `MaleText_loc4`='你寻找的是马尔萨·奥列斯塔。她在炼金房的内环上。', `MaleText_loc5`='你尋找的是瑪莎·奧列斯塔。她在鍊金房的內環上。', `MaleText_loc7`='Buscas a Martha Alliestar. Estar en el cinturón interior de El Apothecarium.', `FemaleText_loc1`='마사 알리스타 찾아? 연금술 실험실 내곽에 있다.', `FemaleText_loc4`='你寻找的是马尔萨·奥列斯塔。她在炼金房的内环上。', `FemaleText_loc5`='你尋找的是瑪莎·奧列斯塔。她在鍊金房的內環上。', `FemaleText_loc7`='Buscas a Martha Alliestar. Estar en el cinturón interior de El Apothecarium.' WHERE `ID`=5877;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연금술 실험실 내곽으로 가봐. 마사 알리스타가 꽃 꺾는 법 가르쳐 준다.', `MaleText_loc4`='你需要去内环的炼金房。那就是马尔萨·奥列斯塔教你如何摘花的地方。', `MaleText_loc5`='你需要去內環的鍊金房。那就是瑪莎·奧列斯塔教你如何摘花的地方。', `MaleText_loc7`='Debes ir a El Apothecarium en el cinturón interior. Allí Martha Alliestar te enseñará a coger flores.', `FemaleText_loc1`='연금술 실험실 내곽으로 가봐. 마사 알리스타가 꽃 꺾는 법 가르쳐 준다.', `FemaleText_loc4`='你需要去内环的炼金房。那就是马尔萨·奥列斯塔教你如何摘花的地方。', `FemaleText_loc5`='你需要去內環的鍊金房。那就是瑪莎·奧列斯塔教你如何摘花的地方。', `FemaleText_loc7`='Debes ir a El Apothecarium en el cinturón interior. Allí Martha Alliestar te enseñará a coger flores.' WHERE `ID`=5878;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도적 지구 내곽에 있다.', `MaleText_loc4`='他居住在盗贼区内环。', `MaleText_loc5`='他居住在盜賊區內環。', `MaleText_loc7`='Él estar en el anillo interior del Barrio de los Pícaros.', `FemaleText_loc1`='도적 지구 내곽에 있다.', `FemaleText_loc4`='他居住在盗贼区内环。', `FemaleText_loc5`='他居住在盜賊區內環。', `FemaleText_loc7`='Él estar en el anillo interior del Barrio de los Pícaros.' WHERE `ID`=5879;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가죽세공? 도적 지구 내곽에서 아서 무어가 을 가르쳐.', `MaleText_loc4`='盗贼区内环的亚瑟·摩尔能教你制革技能。', `MaleText_loc5`='盜賊區內環的亞瑟·摩爾能教你製皮技能。', `MaleText_loc7`='Arthur Moore en anillo interior del Barrio de los Pícaros te enseñará peletería.', `FemaleText_loc1`='가죽세공? 도적 지구 내곽에서 아서 무어가 을 가르쳐.', `FemaleText_loc4`='盗贼区内环的亚瑟·摩尔能教你制革技能。', `FemaleText_loc5`='盜賊區內環的亞瑟·摩爾能教你製皮技能。', `FemaleText_loc7`='Arthur Moore en anillo interior del Barrio de los Pícaros te enseñará peletería.' WHERE `ID`=5880;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='군사 지구 내곽으로 가. 브롬 킬리안 있어.', `MaleText_loc4`='到军事区的内环去。布罗姆·基里安在那里。', `MaleText_loc5`='到軍事區的內環去。布羅姆·基里安在那裡。', `MaleText_loc7`='Ve al cinturón interior del Barrio de la Guerra. Allí Brom Killian.', `FemaleText_loc1`='군사 지구 내곽으로 가. 브롬 킬리안 있어.', `FemaleText_loc4`='到军事区的内环去。布罗姆·基里安在那里。', `FemaleText_loc5`='到軍事區的內環去。布羅姆·基里安在那裡。', `FemaleText_loc7`='Ve al cinturón interior del Barrio de la Guerra. Allí Brom Killian.' WHERE `ID`=5881;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='브롬 킬리안 만나면, 반짝이는 돌을 캘 수 있어. 군사 지구 내곽에 있다.', `MaleText_loc4`='布罗姆·基里安教你如何为挖掘出闪光的东西。他在军事区的内环。', `MaleText_loc5`='布羅姆·基里安教你如何為挖掘出閃光的東西。他在軍事區的內環。', `MaleText_loc7`='Brom Killian te enseñará a excavar para mí. Él en el cinturón interior del Barrio de la Guerra.', `FemaleText_loc1`='브롬 킬리안 만나면, 반짝이는 돌을 캘 수 있어. 군사 지구 내곽에 있다.', `FemaleText_loc4`='布罗姆·基里安教你如何为挖掘出闪光的东西。他在军事区的内环。', `FemaleText_loc5`='布羅姆·基里安教你如何為挖掘出閃光的東西。他在軍事區的內環。', `FemaleText_loc7`='Brom Killian te enseñará a excavar para mí. Él en el cinturón interior del Barrio de la Guerra.' WHERE `ID`=5882;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='킬리안 헤이지는 도적 지구 내곽에서 무두질을 가르칩니다.', `MaleText_loc4`='基里安·哈根在盗贼区传授剥皮的技能。', `MaleText_loc5`='基里安·哈根在盜賊區傳授剝皮的技能。', `MaleText_loc7`='Killian Hagey enseña a desollar en el Barrio de los Pícaros, en el anillo interior.', `FemaleText_loc1`='킬리안 헤이지는 도적 지구 내곽에서 무두질을 가르칩니다.', `FemaleText_loc4`='基里安·哈根在盗贼区传授剥皮的技能。', `FemaleText_loc5`='基里安·哈根在盜賊區傳授剝皮的技能。', `FemaleText_loc7`='Killian Hagey enseña a desollar en el Barrio de los Pícaros, en el anillo interior.' WHERE `ID`=5883;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 무두질 갈고리 있다. 킬리안 헤이지가 줬어. 가죽 벗기는 법도 가르쳐주고. 아... 당신 피부가 좋군. 도적 지구 내곽에 가봐.', `MaleText_loc4`='我们有闪光的钩子。这是基里安·哈根给我们的，他教我们如何剥皮。你有很好的兽皮。去盗贼区的内环找他吧。', `MaleText_loc5`='我們有閃光的鉤子。這是基里安·哈根給我們的，他教我們如何剝皮。你有很好的獸皮。去盜賊區的內環找他吧。', `MaleText_loc7`='Nosotros tener gancho desollador Nos dio Killian Hagey que nos enseña desollar. Tú ser bastante $gdiestro:diestra;. Lo encontrarás en anillo interior de Barrio de los Pícaros.', `FemaleText_loc1`='우리 무두질 갈고리 있다. 킬리안 헤이지가 줬어. 가죽 벗기는 법도 가르쳐주고. 아... 당신 피부가 좋군. 도적 지구 내곽에 가봐.', `FemaleText_loc4`='我们有闪光的钩子。这是基里安·哈根给我们的，他教我们如何剥皮。你有很好的兽皮。去盗贼区的内环找他吧。', `FemaleText_loc5`='我們有閃光的鉤子。這是基里安·哈根給我們的，他教我們如何剝皮。你有很好的獸皮。去盜賊區的內環找他吧。', `FemaleText_loc7`='Nosotros tener gancho desollador. Nos dio Killian Hagey que nos enseña a desollar. Tú ser bastante $gdiestro:diestra;. Lo encontrarás en anillo interior de Barrio de los Pícaros.' WHERE `ID`=5884;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조셉 그레고리안... 마법 지구 내곽 쪽... 녹색 운하 옆에 있다.', `MaleText_loc4`='你寻找乔瑟夫·格里高利。他在绿色运河的内环边上的魔法区里。', `MaleText_loc5`='你尋找喬瑟夫·格里高利。他在綠色運河的內環邊上的魔法區裡。', `MaleText_loc7`='Tú buscar a Josef Gregorian. En el Barrio de la Magia, cinturón interior junto al canal verde.', `FemaleText_loc1`='조셉 그레고리안... 마법 지구 내곽 쪽... 녹색 운하 옆에 있다.', `FemaleText_loc4`='你寻找乔瑟夫·格里高利。他在绿色运河的内环边上的魔法区里。', `FemaleText_loc5`='你尋找喬瑟夫·格里高利。他在綠色運河的內環邊上的魔法區裡。', `FemaleText_loc7`='Tú buscar a Josef Gregorian. En el Barrio de la Magia, cinturón interior junto al canal verde.' WHERE `ID`=5885;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음, 좋은 생각. 나도 가서 꿰맨 데 좀 봐달라고 할까? 조셉 그레고리안 바느질 잘한다. 마법 지구 내곽에 있다.', `MaleText_loc4`='嗯，那是个好主意。或许我们该到那儿去换一下我们身上的线？他的针线活做得很好。你可以在魔法区的内环里找到乔瑟夫·格里高利。', `MaleText_loc5`='嗯，那是個好主意。或許我們該到那兒去換一下我們身上的線?他的針線活做得很好。你可以在魔法區的內環裡找到喬瑟夫·格里高利。', `MaleText_loc7`='Ummmm, buena idea. Podíamos ir allí a que nos vuelvan a hacer algunos remiendos. Remienda bien. Encontrarás a Josef Gregorian en el cinturón interior del Barrio de la Magia.', `FemaleText_loc1`='음, 좋은 생각. 나도 가서 꿰맨 데 좀 봐달라고 할까? 조셉 그레고리안 바느질 잘한다. 마법 지구 내곽에 있다.', `FemaleText_loc4`='嗯，那是个好主意。或许我们该到那儿去换一下我们身上的线？他的针线活做得很好。你可以在魔法区的内环里找到乔瑟夫·格里高利。', `FemaleText_loc5`='嗯，那是個好主意。或許我們該到那兒去換一下我們身上的線?他的針線活做得很好。你可以在魔法區的內環裡找到喬瑟夫·格里高利。', `FemaleText_loc7`='Ummmm, buena idea. Podíamos ir allí a que nos vuelvan a hacer algunos remiendos. Remienda bien. Encontrarás a Josef Gregorian en el cinturón interior del Barrio de la Magia.' WHERE `ID`=5886;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 네! 여기 있어요, $n. 당신이 도와준 데 대한 최소한의 보답이죠.', `FemaleText_loc4`='哦，好的！给你，$n。我只能这么报答你了！', `FemaleText_loc5`='哦，好的!給你，$n。我只能這麼報答你了!', `FemaleText_loc7`='¡Oh, qué bien! Aquí estás, $n. Es lo mínimo que puedo hacer por la ayuda que me has prestado.' WHERE `ID`=5887;
