UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 늙은이의 얘기를 잘 들어보십시오, $n. 할 얘기가 많답니다...', `MaleText_loc4`='听一听长者的故事吧，$n。我有许多话要说……', `MaleText_loc5`='聽一聽長者的故事吧，$n。我有許多話要說...', `MaleText_loc7`='Escucha las historias de un anciano. $n. Tengo mucho de qué hablar...' WHERE `ID`=5922;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n, 마샬의 야영지에 오신 걸 환영해요. 이곳은 어떤 목적이 있어 오기도 하고 우연히 길을 가다 들르기도 하지요. 모두 나름대로 사연이 있는 법이지 않습니까?!', `FemaleText_loc4`='欢迎来到避难所，$n。有些人来这里是有目的的，其余的是凑巧路过……但是每个到这里的人好像都有一个奇特的故事要讲。', `FemaleText_loc5`='歡迎來到避難所，$n。有些人帶著目的來到這裡，其餘的是湊巧路過...但是每個到這裡的人好像都有一個奇特的故事要講。', `FemaleText_loc7`='$GBienvenido:Bienvenida; al refugio, $n. Algunos vienen aquí con algún fin, otros por accidente... Pero todos tienen una historia única que contar.' WHERE `ID`=5923;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정신 바짝 차리세요... 아르낙이 그림토템 부족에게 이상한 마법을 걸었어요. 내가 탈출하는 걸 보면 결코 좋아하지 않을 거예요.', `FemaleText_loc4`='警惕些……阿纳克对恐怖图腾有一种奇怪的能力……他们看到我逃跑了是不会开心的。', `FemaleText_loc5`='警惕些...阿納克對恐怖圖騰有一種奇怪的能力...他們看到我逃跑了是不會開心的。', `FemaleText_loc7`='En guardia... Arnak tiene un poder extraño sobre los Tótem Siniestro... no se alegrarán de verme huir.' WHERE `ID`=5926;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='조심하세요. 그림토템 부족이 쫓아와요!', `FemaleText_loc4`='当心，恐怖图腾的成员快要过来了！', `FemaleText_loc5`='當心，恐怖圖騰的成員快要過來了!', `FemaleText_loc7`='¡Cuidado, los Tótem Siniestro se nos echan encima!' WHERE `ID`=5927;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='놈들이 오고 있어요.', `FemaleText_loc4`='他们来了。', `FemaleText_loc5`='他們來了。', `FemaleText_loc7`='Aquí vienen.' WHERE `ID`=5928;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그림토템 부족이 더 많이 몰려오고 있어요!', `FemaleText_loc4`='更多恐怖图腾的成员正在朝这边冲过来！', `FemaleText_loc5`='更多恐怖圖騰的成員正在朝這邊衝過來!', `FemaleText_loc7`='¡Se acercan más Tótem Siniestro por este camino!' WHERE `ID`=5929;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='드디어 탈출했군요... 전 이제 그만 가봐야겠어요. 도와주셔서 감사합니다. 높새바람 봉우리까지는 혼자서도 갈 수 있겠어요.', `FemaleText_loc4`='终于自由了……我现在必须走了，谢谢你帮我逃脱。我自己会回到乱风岗去的。', `FemaleText_loc5`='終於自由了...我現在必須走了，謝謝你幫我逃脫。我自己會回到亂風崗去的。', `FemaleText_loc7`='Al fin libre... debo irme, gracias por ayudarme a escapar. Puedo volver al Poblado Viento Libre por mí misma.' WHERE `ID`=5930;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n! 때맞춰 오셨네요!', `FemaleText_loc4`='$n！你终于回来了！', `FemaleText_loc5`='$n!你終於回來了!', `FemaleText_loc7`='¡$n! ¡Has vuelto! ¡Y justo a tiempo!' WHERE `ID`=5931;
