UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간의 균열을 통해 %s|1이;가; 소환됩니다!', `MaleText_loc4`='%s从时间裂隙中钻了出来！', `MaleText_loc5`='%s從時光裂隙中鑽了出來!', `MaleText_loc7`='%s es invocado a través de una falla temporal.' WHERE `ID`=6033;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n, 탑 안에 있는 제 수행사제들과 얘기는 해보셨나요? 그들이 주는 임무 중 하나는 완수해야, 제가 보주를 만들어드릴 수 있어요. 준비가 되셨다면 지금 가서 얘기를 나눠보도록 하세요.', `FemaleText_loc4`='你跟塔里的侍僧说过话了吗，$n？除非你能完成他们之中某个人的任务，否则我们就无法为你制作宝珠。如果你准备好了的话，就去跟他们谈谈吧。', `FemaleText_loc5`='你跟塔里的侍僧說過話了嗎，$n?除非你能完成他們之中某個人的任務，否則我們就無法為你製作寶珠。如果你準備好了的話，就去跟他們談談吧。', `FemaleText_loc7`='¿Has hablado ya con alguno de mis acólitos de la torre, $n? No podemos terminar tu orbe hasta que no hayas cumplido sus tareas. Ve a hablar con ellos si estás $gpreparado:preparada;.' WHERE `ID`=6034;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1을;를; 처치할 수 있게 도와줘요!', `MaleText_loc4`='帮我杀死N！', `MaleText_loc5`='幫我殺死$n!', `MaleText_loc7`='¡Ayúdame a matar a $n!' WHERE `ID`=6035;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보호해 주세요! 이 $n|1이;가; 날 해치지 못하게... 우리 종족에게 돌아가야 해.', `MaleText_loc4`='别让这个$n伤害我！我必须平安返回家园。', `MaleText_loc5`='別讓這個$n傷害我!我必須平安返回家園。', `MaleText_loc7`='¡Protégeme de $n! Debo regresar con mi camada.' WHERE `ID`=6036;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살려주세요!', `MaleText_loc4`='别让我丧命！', `MaleText_loc5`='別讓我喪命!', `MaleText_loc7`='¡No me dejes morir!' WHERE `ID`=6037;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아!', `MaleText_loc4`='干得好！', `MaleText_loc5`='幹得好!', `MaleText_loc7`='¡Bien hecho!', `FemaleText_loc1`='좋아!', `FemaleText_loc4`='干得好！', `FemaleText_loc5`='幹得好!', `FemaleText_loc7`='¡Bien hecho!' WHERE `ID`=6038;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 큰 소리로 으르렁거리며 짝을 부릅니다!', `FemaleText_loc4`='%s痛苦地呼唤着恋人的名字，冲了出去！', `FemaleText_loc5`='%s大聲地咆哮!呼喚著她的伴侶!', `FemaleText_loc7`='%s ruge por su compañero.' WHERE `ID`=6039;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 샤이로탐의 부름에 응답하는 듯이 울부짖습니다.', `MaleText_loc4`='%s响应着希洛塔姆的呼唤。', `MaleText_loc5`='%s響應著希洛塔姆的號召。', `MaleText_loc7`='%s responde a la llamada de Shi-Rotam.' WHERE `ID`=6040;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제발 도와줘.$B$B나는 곧 이 세상을 뜨게 될 거라네. 지금은 고통스럽지만 숨을 거두면 더 이상 아픔도 없겠지. 하지만 야생동물들은... 동물들도 나와 같은 고통을 겪고 있는데 그 고통에는 끝이 보이질 않네. 죽기 전 마지막 부탁이니, 부디 들어주게.', `MaleText_loc4`='我的$g兄弟:姐妹;帮帮我吧……$B$B我很快就将离开这个世界了，虽然我饱受苦楚，但是我知道死了之后所有痛苦都将解除。但是，那些野生生物，我的$g兄弟:姐妹;……也历经折磨，永无止境。在我生命的最后一刻，我请求你的帮助。', `MaleText_loc5`='我的$g兄弟:姐妹;幫幫我吧...$b$b我很快就將離開這個世界了，雖然我飽受苦楚，但是我知道死了之後所有痛苦都將解除。但是，那些野生生物，我的$g兄弟:姐妹;...也歷經折磨，永無止境。在我生命的最後一刻，我請求你的幫助。', `MaleText_loc7`='Por favor, ayúdame $ghermano:hermana;...$B$BPronto dejaré este mundo y, aunque sufro, sé que dejaré de hacerlo en cuanto lo abandone. Pero la naturaleza, $ghermano:hermana;... la naturaleza también sufre y no conoce ninguna liberación. Te pido ayuda con mi último aliento de vida.' WHERE `ID`=6043;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는... 당신네 말을 할 줄 알아. 우리는 짐승이 아니야! 그런데 외모가 다르다고 우리를 괴물 취급하고 위협했지! 하지만, 이 문제는 이 땅이 처한 비극에 비하면 아무것도 아니지. 부디 우리와의 불화를 잠시 잊고, 죽어가는 나의 청을 들어주게.$B$B내가 여기 온 이유는 가능한 모든 수단을 동원해 이 땅을 치유하려는 거라네. 하지만 자네가 도와주지 않으면 모두 허사가 되어버릴 것 같아. 마지막 남은 힘을 다해 부탁하니 제발 도와줘.', `MaleText_loc4`='是的，我讲的语言你听得懂$r。我们不是动物，然而你们中大多数却仍然把我们像动物一样对待！可是我们的分歧比起降临到这片土地上的悲剧来显得微不足道。恳请你们把与我们存在的分歧搁置一边，倾听一下我临死前的请求。$B$B我来到这片土地尽我所能改善状况，而现在除非你能帮我，否则那即将要化为泡影。我用我生命的最后一息请你帮这个忙。', `MaleText_loc5`='是的，我講的語言你聽得懂$r。我們不是動物，然而你們中大多數卻仍然把我們像動物一樣對待!可是我們的分歧比起降臨到這片土地上的悲劇來顯得微不足道。懇請你們把與我們存在的分歧擱置一邊，傾聽一下我臨死前的請求。$B$B我來到這片土地盡我所能改善狀況，而現在除非你能幫我，否則那即將要化為泡影。我用我生命的最後一息請你幫這個忙。', `MaleText_loc7`='Sí, hablo un idioma que comprendes, $r. No somos animales, aunque casi todos los de tu clase nos siguen tratando así. Pero nuestras diferencias empalidecen en vista de la tragedia que ha asolado estas tierras. Por favor, deja a un lado tus diferencias con los de mi clase y escucha mi agonizante súplica.$B$BVine a esta tierra para reparar todo lo que me fuera posible, pero todo habrá sido en vano a menos que puedas ayudarme. Te estoy pidiendo ayuda con el último aliento de vida.' WHERE `ID`=6045;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"..."$B$B이 타우렌 드루이드의 몸에 움직임이 없습니다. 마침내 이승을 떠나 뒤틀린 황천으로 간 모양입니다.', `MaleText_loc4`='“……”$B$B牛头人德鲁伊的尸体静静地躺着，看起来他好像终于离开了这个世界。', `MaleText_loc5`='「...」$B$B牛頭人德魯伊的屍體靜靜地躺著，看起來他好像終於離開了這個世界。', `MaleText_loc7`='""...""$B$BEl cuerpo del druida tauren yace inmóvil. Parecería que finalmente ha abandonado este mundo para descubrir las maravillas del más allá.' WHERE `ID`=6046;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 데피아즈단에 맞서려 하다니!', `MaleText_loc4`='没有人胆敢挑战兄弟会！', `MaleText_loc5`='沒有人能與兄弟會抗衡!', `MaleText_loc7`='¡Nadie puede enfrentarse a la Hermandad!' WHERE `ID`=6061;
