UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어리석은 것들! 우린 정의의 수호자란 말이다!', `MaleText_loc4`='蠢货！我们的事业是正义的！', `MaleText_loc5`='笨蛋!我們的理想是正當的!', `MaleText_loc7`='¡Locos! ¡Nuestra causa es justa!' WHERE `ID`=6064;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='데피아즈단은 반드시 승리할 것이다!', `MaleText_loc4`='胜利属于兄弟会！', `MaleText_loc5`='兄弟會必將獲得最終的勝利!', `MaleText_loc7`='¡La Hermandad prevalecerá!' WHERE `ID`=6065;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오염된 노움들이 뒤집어질 일이로군요! 여기에 몇 달 동안이나 갇혀 있었는데. 고마워요.', `MaleText_loc4`='这些讨厌的侏儒！我被困在这儿好几个月了。谢谢你。', `MaleText_loc5`='這些討厭的地精!我被困在這兒好幾個月了。謝謝你。', `MaleText_loc7`='¡Gnomos leprosos saltarines! He estado ahí metido durante meses. Gracias, muchachos.' WHERE `ID`=6066;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 누가 내 땅에 발을 들여놓는 것이냐! 덤벼봐! 집어삼켜 버리겠어!', `MaleText_loc4`='谁敢踏入我的领地！来！来被消灭吧！', `MaleText_loc5`='誰敢踏入我的領地!來!來被消滅吧!', `MaleText_loc7`='¡Quién osa adentrarse en mis dominios! ¡Ven! ¡Ven para ser consumido!' WHERE `ID`=6067;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드루이드는 이 세계의 자연을 보호하는 데 있어 결코 경계를 늦추지 않습니다. 세나리온 자치령에 사는 대드루이드 판드랄 스태그헬름이 이끌고 있으니 찾아가 조언을 구하시기 바랍니다. 다르나서스 북부에서 판드랄과 다른 상급 드루이드를 찾을 수 있습니다.', `MaleText_loc4`='居住于塞纳里奥区的德鲁伊一直在大德鲁伊鹿盔的领导下警惕地保卫着自然界。你可以在达那苏斯北部找到他和别的德鲁伊训练师。', `MaleText_loc5`='居住於塞納里奧區的德魯伊一直在大德魯伊范達爾·鹿盔的領導下警惕地保衛著自然界。你可以在達納蘇斯北部找到他和別的德魯伊訓練師。', `MaleText_loc7`='En eterna vigía en su protección del mundo natural, los druidas están guiados por el archidruida Fandral Corzocelada que reside en el Enclave Cenarion. Lo encontrarás junto a los otros instructores de druidas en la sección septentrional de Darnassus.', `FemaleText_loc1`='드루이드는 이 세계의 자연을 보호하는 데 있어 결코 경계를 늦추지 않습니다. 세나리온 자치령에 사는 대드루이드 판드랄 스태그헬름이 이끌고 있으니 찾아가 조언을 구하시기 바랍니다. 다르나서스 북부에서 판드랄과 다른 상급 드루이드를 찾을 수 있습니다.', `FemaleText_loc4`='居住于塞纳里奥区的德鲁伊一直在大德鲁伊鹿盔的领导下警惕地保卫着自然界。你可以在达那苏斯北部找到他和别的德鲁伊训练师。', `FemaleText_loc5`='居住於塞納里奧區的德魯伊一直在大德魯伊范達爾·鹿盔的領導下警惕地保衛著自然界。你可以在達納蘇斯北部找到他和別的德魯伊訓練師。', `FemaleText_loc7`='En eterna vigía en su protección del mundo natural, los druidas están guiados por el archidruida Fandral Corzocelada que reside en el Enclave Cenarion. Lo encontrarás junto a los otros instructores de druidas en la sección septentrional de Darnassus.' WHERE `ID`=6068;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 이 도시의 공무를 보고 있네. 언더시티의 인구를 조사하는 업무를 맡고 있지. 스컬지에게 해방된 후로 우리는 인구를 정확하게 기록해 두려고 노력하고 있지. 난 마법과 고도로 단련된 정신력으로 그걸 조사해 기록할 수 있다네. 용건이 있다면 말해 보게. 내게 용건이 있는지 없는지 정도는 알겠지?', `MaleText_loc4`='我是这座城市的官员，从事幽暗城的人口普查工作。自从我们从亡灵天灾中解脱出来以后，我们就尽力对我们的城市人口做出精确的记录。通过一些奥术方式和聪明的方法，我才得以弄到这些记录。如果你需要有事找我的话，请继续。你应该知道你是否有事需要我的帮助。', `MaleText_loc5`='我是這座城市的官員，從事幽暗城的人口普查工作。自從我們從天譴軍團中解脫出來以後，我們就盡力對我們的城市人口做出精確的記錄。通過一些秘法方式和聰明的方法，我才得以弄到這些記錄。如果你需要有事找我的話，請繼續。你應該知道你是否有事需要我的幫助。', `MaleText_loc7`='Soy un oficial de la ciudad, trabajo a cargo del censo de Entrañas. Desde nuestra liberación de la Plaga, hemos intentado seguir con precisión la evolución de la población de nuestra ciudad. Puedo acceder a los registros a través de métodos arcanos y de una aguda disciplina mental. Si tienes negocios conmigo sobre este asunto, adelante. Al menos deberías saber si es así.' WHERE `ID`=6069;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장님께서는 내게 모든 종류의 무기와 방어구에 대해 연구하라고 지시를 내리셨소. 타우렌과 오크의 문화가 만나는 이곳 불모의 땅으로 나를 보내, 이 땅의 문화에 대해서 배우고 가능한 한 다양한 여행자를 접해보라고 하셨지.$B$B대족장님께서는 가시멧돼지나 켄타우로스처럼 하찮은 짐승들의 문화에서도 배울 게 있다고 생각하시오.', `MaleText_loc4`='酋长指示我学习各种武器和护甲知识。他把我派遣到这兽人和牛头人文明的集合之地，接触尽可能多的旅行者，学习整个贫瘠之地的文明。$B$B他认为即使是最未开化的文明也有值得学习的地方——比如野猪人和半人马。', `MaleText_loc5`='大酋長指示我學習各種武器和護甲知識。他把我派遣到這獸人和牛頭人文明的集合之地，接觸盡可能多的旅人，學習整個貧瘠之地的文明。$B$B他認為即使是最未開化的文明也有值得學習的地方─比如野豬人和半人馬。', `MaleText_loc7`='El Jefe de Guerra me ha ordenado que estudie todo tipo de armas y armaduras. Me ha enviado aquí, al centro de las culturas tauren y orca, en los Baldíos, para conocer a tantos viajeros como sea posible y para aprender cosas acerca de las culturas de los Baldíos.$B$BCree que hay algo que aprender hasta de la más patética de las culturas... como los jabaespín o centauros.' WHERE `ID`=6070;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기권했으니 내가 이겼다.', `MaleText_loc4`='你投降了。我赢了。', `MaleText_loc5`='你投降了。我贏了。', `MaleText_loc7`='Te rendiste. Yo gano.', `FemaleText_loc1`='기권했으니 내가 이겼다.', `FemaleText_loc4`='你投降了。我赢了。', `FemaleText_loc5`='你投降了。我贏了。', `FemaleText_loc7`='Te rendiste. Yo gano.' WHERE `ID`=6071;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투 발구르기가 그 정도는 돼야지! 잘했어!', `MaleText_loc4`='现在来个战争践踏！干得好！', `MaleText_loc5`='現在來個戰爭踐踏!幹得好!', `MaleText_loc7`='¡Eso ha sido un Pisotón de guerra! ¡Buen trabajo!', `FemaleText_loc1`='전투 발구르기가 그 정도는 돼야지! 잘했어!', `FemaleText_loc4`='现在来个战争践踏！干得好！', `FemaleText_loc5`='現在來個戰爭踐踏!幹得好!', `FemaleText_loc7`='¡Eso ha sido un Pisotón de guerra! ¡Buen trabajo!' WHERE `ID`=6072;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 저렇게 하는 것이다! 다들 잘 보고 있겠지!', `MaleText_loc4`='那就是完成的方法！你最好认真听讲！', `MaleText_loc5`='那就是完成的方法!你最好認真聽講!', `MaleText_loc7`='¡Así es como se hace, clase! ¡Será mejor que prestéis atención!', `FemaleText_loc1`='바로 저렇게 하는 것이다! 다들 잘 보고 있겠지!', `FemaleText_loc4`='那就是完成的方法！你最好认真听讲！', `FemaleText_loc5`='那就是完成的方法!你最好認真聽講!', `FemaleText_loc7`='¡Así es como se hace, clase! ¡Será mejor que prestéis atención!' WHERE `ID`=6073;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발구르기가 일품인걸!', `MaleText_loc4`='现在放下你的蹄子！', `MaleText_loc5`='現在放下你的蹄子!', `MaleText_loc7`='¡Te está poniendo firme!', `FemaleText_loc1`='발구르기가 일품인걸!', `FemaleText_loc4`='现在放下你的蹄子！', `FemaleText_loc5`='現在放下你的蹄子!', `FemaleText_loc7`='¡Te está poniendo firme!' WHERE `ID`=6074;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어이! $R! 이리 와 봐. <킁킁>$B$B시간이 없어. 난 곧 최후를 <킁> 맞을 거야. 하지만 두고 봐... 결국 최후의 승자는 이 뻐드렁니가 될 테니까 말이야. <킁킁>$B$B비록 갇혀 있는 신세이긴 하지만 <킁킁> 아직 우리 부족에게 도움이 될 수는 있거든. 서슬갈기 일족은 뾰족털 가시멧돼지들 중에서도 가장 강한 부족이란 말이야!$B$B호드는 습격을 주도한 자가 누군지 알고 싶어 해. <킁킁> 이 뻐드렁니를 도와주면 그 대가로 나만이 알고 있는 정보를 주겠어. 이 뻐드렁니가 자네를 도와줄 수 있지! <킁> 자네가 이 뻐드렁니를 도와주면 말이야! <킁>', `MaleText_loc4`='你！$R！过来。<喷鼻声>$B$B时间短暂，而我的末日<喷鼻声>就要来临了。碎牙会赢；你会看到的。<喷鼻声>$B$B我的战利品还可以帮助<喷鼻声>我的人民。钢鬃部落要比刺背野猪人更加强大！$B$B部落正期望找出由谁来带领人民发动袭击。你<喷鼻声>作为回报要援助碎牙，告诉他只有我才知道的信息。碎牙能帮你！<喷鼻声>但你必须帮助碎牙。', `MaleText_loc5`='你!$R!過來。<噴鼻聲>$B$B時間短暫，而我的末日<噴鼻聲>就要來臨了。碎牙會贏;你會看到的。<噴鼻聲>$B$B我的戰利品還可以幫助<噴鼻聲>我的人民。剃鬃部族要比刺背野豬人更加強大!$B$B部族正期望找出由誰來帶領人民發動襲擊。你<噴鼻聲>作為回報要援助碎牙，告訴他只有我才知道的資訊。碎牙能幫你!<噴鼻聲>但你必須幫助碎牙。', `MaleText_loc7`='¡Tú! ¡$R! Ven aquí.<resopla>$B$BEl tiempo es breve y mi fin -resopla-está cerca. Quebrantadientes vencerá, ya lo verás. -resopla-$B$BMi captura todavía puede ayudar <resopla> a mi gente. ¡La tribu Crines de Acero es más poderosa que los Erizapúas!$B$BLa Horda quiere averiguar quién lidera las incursiones sobre su pueblo. Tú <resopla> ayudarás a Quebrantadientes a cambio de la información que solo yo conozco. ¡Quebrantadientes puede ayudarte! <resopla> Pero debes ayudar a Quebrantadientes.' WHERE `ID`=6075;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드에 오신 것을 환영합니다! 저는 인구조사국에서 시민을 위해 일하고 있는 공무원입니다. 찾는 사람이 있다면 제가 도와드릴 수 있을 겁니다. 저는 마법과 고도로 단련된 정신력을 이용하여 이 기록들을 조사할 수 있거든요.$B$B제게 용건이 있으시면 언제든지 말씀해 보십시오!', `MaleText_loc4`='欢迎来到暴风城！我是城市的一名长官，帮助城市的人口调查局登记居民。如果你想找人的话，我也许能帮上你。我能运用奥术和智慧拿到这些记录。$B$B如果你找我有事的话，那就开口吧！', `MaleText_loc5`='歡迎來到暴風城!我是城市的一名長官，幫助城市的人口調查局登記居民。如果你想找人的話，我也許能幫上你。我能運用秘法和智慧拿到這些記錄。$B$B如果你找我有事的話，那就開口吧!', `MaleText_loc7`='¡$gBienvenido:Bienvenida; a Ventormenta! Soy uno de los oficiales de la ciudad y sirvo a la ciudadanía a través de nuestra oficina censal. Si necesitas localizar a alguien en concreto, creo que podré ayudarte. Puedo acceder a los registros a través de métodos arcanos y una aguda disciplina mental.$B$BSi tienes algún asunto conmigo, ¡procede!' WHERE `ID`=6076;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='화가 나서 코가 자꾸 막히지만, <킁킁> $R한테 이 이야기는 꼭 해줘야겠어.$B$B아주 오래전 신들의 전쟁이 일어났지. 우리 위대한 멧돼지 신, 아감마간 님은 그 고대의 전쟁에서 패배한 후, 땅으로 떨어지셨어. 피는 비가 되어 내리고 뼈는 산산조각나 버렸지. <킁킁>$B$B아감마간 님의 피가 뿌려진 땅에서는 커다란 가시들이 돋아났고, 해골은 남쪽에 있는 동굴에 떨어졌어.', `MaleText_loc4`='我怀着深深的仇恨<哼>，但是是时候告诉你了，$r。$B$B很久之前，众神之间爆发了一场战争。我们伟大的野猪神阿迦玛甘在史前战争中战败，鲜血四溅，骨肉横飞。<哼>$B$B当他的鲜血流到地面上时，巨大的荆棘破土而出，他的徽记装饰着此地以南的洞穴。', `MaleText_loc5`='我懷著深深的仇恨<哼>，但是是時候告訴你了，$r。$B$B很久之前，眾神之間爆發了一場戰爭。我們偉大的野豬神阿迦瑪甘在先祖之戰中戰敗，鮮血四濺，骨肉橫飛。<哼>$B$B當他的鮮血流到地面上時，巨大的荊棘破土而出，他的頭顱裝飾著此地以南的洞穴。', `MaleText_loc7`='Mi odio es fuerte -resopla-, pero hay tiempo de contarte una historia, $r.$B$BHace mucho tiempo tuvo lugar una batalla entre dioses. Agamaggan, nuestro gran dios jabalí, cayó a tierra tras ser derrotado en la Guerra de los Ancestros, con su sangre derramada y sus huesos partidos en dos. -resopla-$B$BAllí donde su sangre tocó el suelo, se alzaron grandes púas, y su cráneo adorna una de las cavernas del Sur.' WHERE `ID`=6077;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='휴... 담배 한 모금 피운 후, 아리따운 노움 여성과 데이트라도 했으면... 아니, 데이트 먼저 하고 한 모금 펴도 좋겠지!$B$B전 저 녀석의 뱃속에 몇 달 동안이나 갇혀 있었답니다! 오늘이 무슨 요일이죠? 참, 나 방금 빠져 나왔지...$B$B얏호!', `MaleText_loc4`='吆……我需要一根烟和找个好看的侏儒女人摸几下--倒不必非要按那个顺序！$B$B我被困在那个东西的肚子里已经有几个月了。今天几号了？啊，不要紧。重要的是我终于出来了。$B$B呜呼！', `MaleText_loc5`='吆...我需要一根煙和找個好看的地精女人摸幾下--倒不必非要按那個順序!$B$B我被困在那個東西的肚子裡已經有幾個月了。今天幾號了?啊，不要緊。重要的是我終於出來了。$B$B嗚呼!', `MaleText_loc7`='Buah... Necesito un pitillo y la caricia de una hermosa mujer gnoma... ¡y no tiene por qué ser en ese orden!$B$B¡He estado metido en la tripa de esa cosa durante meses! ¿Pero qué día es hoy? Ah, da igual. Lo que importa es que por fin estoy fuera.$B$B¡YUHUUUUUU!' WHERE `ID`=6078;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저긴 애초에 어떻게 들어간 겁니까?', `MaleText_loc4`='你究竟是怎么进去的？', `MaleText_loc5`='你究竟是怎麼進去的?', `MaleText_loc7`='Pero para empezar, ¿cómo demonios acabaste ahí dentro?', `FemaleText_loc1`='저긴 애초에 어떻게 들어간 겁니까?', `FemaleText_loc4`='你究竟是怎么进去的？', `FemaleText_loc5`='你究竟是怎麼進去的?', `FemaleText_loc7`='Pero para empezar, ¿cómo demonios acabaste ahí dentro?' WHERE `ID`=6079;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 들어갔느냐고요? 흠... 얘기하자면 길지요.', `MaleText_loc4`='怎么进去的？？嗯，这故事真长。', `MaleText_loc5`='怎麼進去的??嗯，這故事真長。', `MaleText_loc7`='¿¿Cómo?? Bueno, es una larga historia.' WHERE `ID`=6080;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래도 듣고 싶습니다.', `MaleText_loc4`='我将洗耳恭听。', `MaleText_loc5`='我將洗耳恭聽。', `MaleText_loc7`='Soy todo oídos.', `FemaleText_loc1`='그래도 듣고 싶습니다.', `FemaleText_loc4`='我将洗耳恭听。', `FemaleText_loc5`='我將洗耳恭聽。', `FemaleText_loc7`='Soy todo oídos.' WHERE `ID`=6081;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇다면 좋아요! 전 용암 방열복의 성능을 시험해 보려고 작열하는 교각의 용암 구덩이에 갔어요. 모든 게 잘 되고 있었지요. 그 속에서 한 군데도 화상을 입지 않고 헤엄칠 수 있을 정도로 말이에요!$B$B그곳에서 볼일도 보고 배영도 하면서 있는데 난데없이 녀석이 나타나서 날 통째로 집어삼키지 뭐예요! 용암 방열복이랑 그 안에 내장된 자동 음식 공급기가 아니었으면 전 그대로 끝장이었을 거라고요!', `MaleText_loc4`='好吧！我在熔岩大桥的熔岩坑测试熔岩服。一切进展顺利。我甚至能在熔岩中毫发无损地游泳！$B$B我在那儿做自己的事，有时仰泳一会，突然之间它把我一口吞没！若不是有了熔岩服和便携式食物机，我一定会就此交待了！', `MaleText_loc5`='好吧!我在熔岩之橋的熔岩坑測試熔岩服。一切進展順利。我甚至能在熔岩中毫髮無損地游泳!$B$B我在那兒做自己的事，有時仰泳一會，突然之間它把我一口吞沒!若不是有了熔岩服和可攜式食物機，我早就死定了!', `MaleText_loc7`='¡Está bien! Estaba ahí abajo, en los fosos de lava de la Luz de Magma, probando mi traje de lava. Todo iba de maravilla. ¡Hasta podía nadar sin sufrir ni un solo daño!$B$BAsí que ahí estaba yo, metido en mis cosas, nadando de espaldas, cuando, de repente, esa cosa salió de la nada y me tragó entero. Si no hubiera sido por mi traje de lava y por mi dispensador integrado de comida comprimida, ¡hubiera estado perdido!' WHERE `ID`=6082;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러니까 당신 말은 이... 용암 방열복이라는 걸 입고 용암 속에서 헤엄을... 아니, 배영을 했다는 거죠? 그리고 갑자기 이 괴물이 나타나서는 당신을 통째로 집어삼켰고요?', `MaleText_loc4`='让我搞搞清楚。你穿着这件……这件熔岩服，在火红的岩浆里面游泳，不，仰泳？而且在毫无察觉的情况下，被这只野兽吞下了肚？', `MaleText_loc5`='讓我搞清楚。你穿著這件...這件熔岩服，在火紅的熔岩裡面游泳，不，仰泳?而且在毫無察覺的情況下，被這隻野獸吞下了肚?', `MaleText_loc7`='¡Puedes quedarte con ese, ya no lo necesito!', `FemaleText_loc1`='그러니까 당신 말은 이... 용암 방열복이라는 걸 입고 용암 속에서 헤엄을... 아니, 배영을 했다는 거죠? 그리고 갑자기 이 괴물이 나타나서는 당신을 통째로 집어삼켰고요?', `FemaleText_loc4`='让我搞搞清楚。你穿着这件……这件熔岩服，在火红的岩浆里面游泳，不，仰泳？而且在毫无察觉的情况下，被这只野兽吞下了肚？', `FemaleText_loc5`='讓我搞清楚。你穿著這件...這件熔岩服，在火紅的熔岩裡面游泳，不，仰泳?而且在毫無察覺的情況下，被這隻野獸吞下了肚?', `FemaleText_loc7`='Vamos a ver si lo he entendido. Estabas nadando, ¿no?, ¿dando brazadas en la lava fundida con este... con este traje tuyo de lava? ¿Verdad? ¿Y, de repente, esta cosa salió de la nada y te tragó entero?' WHERE `ID`=6083;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='허. 좀 믿지 못하는 듯한 목소리로네요. 그래요. 그런 일이 벌어졌어요.', `MaleText_loc4`='我说，我感觉你对此充满怀疑——但是，那就是事情的经过。', `MaleText_loc5`='我說，我感覺你對此充滿懷疑─但是，那就是事情的經過。', `MaleText_loc7`='Ummm... noto algo de incredulidad en tu voz... pero sí, así es cómo ocurrió.' WHERE `ID`=6084;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한가지 알고 싶은 게 있는데, 그걸 입고 화장실은 어떻게 갑니까?', `MaleText_loc4`='我必须知道一些事情：你如何穿着这个东西解决个人问题的？', `MaleText_loc5`='我必須知道一些事情:你如何穿著這個東西解決個人問題的?', `MaleText_loc7`='Necesito saber algo: ¿cómo hacías tus necesidades con esa cosa puesta?', `FemaleText_loc1`='한가지 알고 싶은 게 있는데, 그걸 입고 화장실은 어떻게 갑니까?', `FemaleText_loc4`='我必须知道一些事情：你如何在那个东西开着的时候进浴室的？', `FemaleText_loc5`='我必須知道一些事情:你如何在那個東西開著的時候進浴室的?', `FemaleText_loc7`='Necesito saber algo: ¿cómo hacías tus necesidades con esa cosa puesta?' WHERE `ID`=6085;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 괴물 뱃속에서 나온 지 얼마나 됐다고 벌써 제 화장실 습관에 대해 묻는 거죠? 이봐요, 날 구해준 것만 아니었으면 벌써 흠씬 두들겨 패 주었을 거라고요!$B$B어쨌든! 도와줘서 고마워요. 당신한테 사례라도 해야겠는데 말이에요.', `MaleText_loc4`='我才从这野兽的肚腹之中出来还不到两分钟，就有人问起我如厕的问题？？？$G先生:小姐;，如果你不是救我的那个人，我一定早就把你敲傻掉了！$B$B无论如何！我很感谢你的帮助。或许我能回报你？', `MaleText_loc5`='我才從這野獸的肚腹之中出來還不到兩分鐘，就有人問起我如廁的問題???$G先生:小姐;，如果你不是救我的那個人，我一定早就把你敲傻掉了!$B$B無論如何!我很感謝你的幫助。或許我能回報你?', `MaleText_loc7`='¿¿¿Hace menos de dos minutos que estoy fuera de la tripa de esa bestia y ya me están preguntando por mis costumbres gástricas??? $GSeñor:Señora;, ¡te hubiera dado un buen bofetón por esa pregunta si no me hubieras rescatado!$B$B¡En cualquier caso!, te estoy agradecido por la ayuda. ¿Cómo puedo pagarte?' WHERE `ID`=6086;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사례라고요?', `MaleText_loc4`='哦？', `MaleText_loc5`='哦?', `MaleText_loc7`='¿Oh?', `FemaleText_loc1`='사례라고요?', `FemaleText_loc4`='哦？', `FemaleText_loc5`='哦?', `FemaleText_loc7`='¿Oh?' WHERE `ID`=6087;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음... ''사례''라는 말이 그리 적절하지 않을지도 모르겠군요. 제가 저 괴물의 뱃속에 들어앉아 있는 동안 쭉 생각을 해봤는데 말이죠...$B$B이 생물은 불길이 이글거리는 용암 속에 살면서도 전혀 화상이라던가 상처를 입지 않더라고요!$B$B그런 괴물의 가죽을 원상태 그대로 구할 수만 있다면, 눈망루 마을에 사는 말리퍼스 다크해머라는 제 친구에게 가지고 가세요. 그 괴물의 가죽을 가공할 수 있는 자가 있다면 바로 그 친구거든요.', `MaleText_loc4`='嗯，或许报酬这个词不是最合适的说法。当我在那东西的肚腹之中时，我在想：$B$B这家伙生活在灼热的岩浆中，火焰却不能伤害它一丝一毫！$B$B如果我能找到这样一块兽皮的话，我就把它交给我在永望镇的朋友玛雷弗斯·暗锤。如果说有人能处理这种兽皮的话，那个人就是他。', `MaleText_loc5`='嗯，或許報酬這個詞不是最合適的說法。當我在那東西的肚腹之中時，我在想:$B$B這傢伙生活在灼熱的岩漿中，火焰卻不能傷害它一絲一毫!$B$B如果我能找到這樣一塊獸皮的話，我就把它交給我在永望鎮的朋友瑪雷弗斯·暗錘。如果說有人能處理這種獸皮的話，那個人就是他。', `MaleText_loc7`='Bueno, quizás "pagar" no sea la palabra adecuada. Veamos, cuando estaba metido en la tripa de esa cosa, tuve mucho tiempo para pensar:$B$BEsta criatura vive en el magma caliente y llameante, ¡y el fuego no le hace nada de daño!$B$BSi pudiera hacerme con un cuero prístino de una de estas bestias podría llevárselo a mi querido amigo Malyfous Martilloscuro, de Vista Eterna. Si hay alguien que pueda hacer algo con la piel de estas bestias, será él.' WHERE `ID`=6088;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음번에 이런 괴물을 보면 잘 기억해 두죠.', `MaleText_loc4`='下次再遇到这种事情的时候我会好好考虑一下的。', `MaleText_loc5`='下次再遇到這種事情的時候我會好好考慮一下的。', `MaleText_loc7`='Lo tendré en cuenta la próxima vez que me encuentre con una de esas cosas.', `FemaleText_loc1`='다음번에 이런 괴물을 보면 잘 기억해 두죠.', `FemaleText_loc4`='下次再遇到这种事情的时候我会好好考虑一下的。', `FemaleText_loc5`='下次再遇到這種事情的時候我會好好考慮一下的。', `FemaleText_loc7`='Lo tendré en cuenta la próxima vez que me encuentre con una de esas cosas.' WHERE `ID`=6089;
