UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론, 말리퍼스에게 전할 소식이겠죠.', `MaleText_loc4`='我想，你应该去玛雷弗斯那里。', `MaleText_loc5`='我想，你應該去瑪雷弗斯那裡。', `MaleText_loc7`='A Malyfous, supongo', `FemaleText_loc1`='물론, 말리퍼스에게 전할 소식이겠죠.', `FemaleText_loc4`='我想，你应该去玛雷弗斯那里。', `FemaleText_loc5`='我想，你應該去瑪雷弗斯那裡。', `FemaleText_loc7`='A Malyfous, supongo' WHERE `ID`=6092;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바퀴벌레 사시려고? 말도 잘 듣고 귀여운 놈으로 골라줄 테니, 한 마리 들여 가게.', `MaleText_loc4`='想买蟑螂吗？', `MaleText_loc5`='想買蟑螂嗎?', `MaleText_loc7`='¿Quieres comprar una cucaracha?' WHERE `ID`=6093;
