UPDATE `locales_broadcast_text` SET `MaleText_loc1`='온몸을 휘감아 으스러뜨려주마!', `MaleText_loc4`='死亡的纠缠会让你彻底湮灭！', `MaleText_loc5`='死亡的力量會徹底摧毀你!', `MaleText_loc7`='¡Los anillos de la muerte te aplastarán!' WHERE `ID`=6095;
