UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇지, 그렇지. 이제 서로 인사하고.', `MaleText_loc4`='很好，很好。现在互相鞠躬。', `MaleText_loc5`='很好，很好。現在互相鞠躬。', `MaleText_loc7`='Bien, bien. Ahora haceos una reverencia mutua.', `FemaleText_loc1`='그렇지, 그렇지. 이제 서로 인사하고.', `FemaleText_loc4`='很好，很好。现在互相鞠躬。', `FemaleText_loc5`='很好，很好。現在互相鞠躬。', `FemaleText_loc7`='Bien, bien. Ahora haceos una reverencia mutua.' WHERE `ID`=6098;
