UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저에게는... 아니, 우리 모두에게... 시간은 별로 남아있지 않아요.', `FemaleText_loc4`='我的时间不多了……我们的时间都不多了……', `FemaleText_loc5`='我的時間不多了...我們的時間都不多了...', `FemaleText_loc7`='Se me acaba el tiempo... a todos nosotros...' WHERE `ID`=6110;
