UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<킁킁> 이 뻐드렁니에게 많은 도움을 주었군. 솔직히 기대 이상이야, $R!$B$B고마워. <킁>$B$B나는 여기에 갇혀 있지만, 뾰족털 가시멧돼지에게 혈석 파편을 빼앗아 오면 자네에게 아감마간 님의 힘을 주겠어.', `MaleText_loc4`='你对<猪哼声>碎牙的帮助比我想象的要大得多，$r。$B$B谢谢你。$B$B只要我还是这里的俘虏，你就可以从刺背野猪人那里给我拿血岩碎片来换取阿迦玛甘的力量。', `MaleText_loc5`='你對<豬哼聲>碎牙的幫助比我想像的要大得多，$r。$B$B謝謝你。$B$B只要我還是這裡的俘虜，你就可以從刺背野豬人那裡給我拿血岩裂片來換取阿迦瑪甘的力量。', `MaleText_loc7`='Has <resopla> ayudado a Quebrantadientes más de lo que hubiera soñado, $r.$B$BGracias.$B$BMientras siga aquí cautivo puedes traerme esquirlas de sangre del jabaespín Erizapúas y te ungiré con la fuerza de Agamaggan.' WHERE `ID`=6117;
