UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 토륨 대장조합에서는 개미 같은 자들과는 상대하지 않습니다. 썩 사라지시오!', `MaleText_loc4`='瑟银兄弟会是不会在蚂蚁身上浪费时间的。快滚开！', `MaleText_loc5`='瑟銀兄弟會是不會在螞蟻身上浪費時間的。快滾開!', `MaleText_loc7`='La Hermandad del Torio no pierde el tiempo con hormigas. ¡Lárgate!' WHERE `ID`=6128;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 가죽에 대해서 설명해주십시오.', `MaleText_loc4`='告诉我关于那块皮的事情。', `MaleText_loc5`='告訴我關於那塊皮的事情。', `MaleText_loc7`='Háblame de los pellejos.', `FemaleText_loc1`='그 가죽에 대해서 설명해주십시오.', `FemaleText_loc4`='告诉我关于那块皮的事情。', `FemaleText_loc5`='告訴我關於那塊皮的事情。', `FemaleText_loc7`='Háblame de los pellejos.' WHERE `ID`=6129;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 정도의 솜씨를 가진 이에게는 간단한 일이지만.$B$B짐승의 가죽으로 물건을 제작할 때 가장 힘든 부분이 바로 그 재료를 구하는 일이오. 내게 온전한 괴수의 가죽을 가지고 오면 강력한 물건을 몇 가지 만들어 줄 수 있소.', `MaleText_loc4`='对我这样的工匠来说，制造的流程本身是很简单的。$B$B困难之处在于获得原料。如果你能为我取回一块完美的比斯巨兽的皮，我就能用它制作出一些强大的装备。', `MaleText_loc5`='對我這樣的工匠來說，製造的流程本身是很簡單的。$B$B困難之處在於獲得原料。如果你能為我取回一塊完美的比斯巨獸的皮，我就能用它製作出一些強大的裝備。', `MaleText_loc7`='Es un proceso muy sencillo para un artesano de mi calibre.$B$BLo más complicado de la elaboración de objetos a partir de pellejos y caparazones de bestias es la adquisición de las piezas. Ahora bien, si pudieras traerme un cuero prístino de esa bestia, podría hacer con ella varios objetos de gran poder.' WHERE `ID`=6130;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런 가죽을 구할 가능성은 얼마나 됩니까?', `MaleText_loc4`='我如何才能获得比斯巨兽的皮呢？', `MaleText_loc5`='我如何才能獲得比斯巨獸的皮呢?', `MaleText_loc7`='¿Qué oportunidades hay de obtener un pellejo así?', `FemaleText_loc1`='그런 가죽을 구할 가능성은 얼마나 됩니까?', `FemaleText_loc4`='我如何才能获得比斯巨兽的皮呢？', `FemaleText_loc5`='我如何才能獲得比斯巨獸的皮呢?', `FemaleText_loc7`='¿Qué oportunidades hay de obtener un pellejo así?' WHERE `ID`=6131;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가능성은 아마 백만 분의 일 정도일 거요! 일생에 한번 볼까 말까 한 그런 가죽이지! 내로라하는 세공인들조차도 무두질 과정에서 수백 번은 실패한 후에 온전한 가죽을 얻을 수 있으니까 말입니다.', `MaleText_loc4`='我估计获得这样一件东西的概率是百万分之一！一件让你终身受用的兽皮！即使是技艺最高超的工匠也不一定能剥出一张完美的皮来！', `MaleText_loc5`='我估計獲得這樣一件東西的概率是百萬分之一!一件讓你終身受用的獸皮!即使是技藝最高超的工匠也不一定能剝出一張完美的皮來!', `MaleText_loc7`='¡Calculo que las probabilidades de obtener una pieza así serían de una entre un millón! ¡Una piel única en la vida! Incluso los artesanos con más disciplina fracasarían varios cientos de veces desollando la bestia antes de poder obtener una sola muestra prístina.' WHERE `ID`=6132;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 그 가죽을 구했다고 하죠. 그밖에 또 뭐가 필요하고, 그런 것들로 뭘 만들어주실 수 있습니까?', `MaleText_loc4`='假设我已经得到了比斯巨兽的皮，那么你还需要什么东西吗？你能用它做些什么？', `MaleText_loc5`='假設我已經得到了比斯巨獸的皮，那麼你還需要什麼東西嗎?你能用它做些什麼?', `MaleText_loc7`='Bueno, supongamos que consigo ese pellejo, ¿qué más necesitarías y qué es todo lo que podrías hacer?', `FemaleText_loc1`='제가 그 가죽을 구했다고 하죠. 그밖에 또 뭐가 필요하고, 그런 것들로 뭘 만들어주실 수 있습니까?', `FemaleText_loc4`='假设我已经得到了比斯巨兽的皮，那么你还需要什么东西吗？你能用它做些什么？', `FemaleText_loc5`='假設我已經得到了比斯巨獸的皮，那麼你還需要什麼東西嗎?你能用它做些什麼?', `FemaleText_loc7`='Bueno, supongamos que consigo ese pellejo, ¿qué más necesitarías y qué es todo lo que podrías hacer?' WHERE `ID`=6133;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 가죽을 실제로 구했다면? 음... 더 설명해 드리지요.', `MaleText_loc4`='要是你真的带来了那张皮？嗯……让我为你展示一番吧……', `MaleText_loc5`='要是你真的帶來了那張皮?嗯...讓我為你展示一番吧...', `MaleText_loc7`='¿Si consiguieras traerme el pellejo de la bestia? Bien... Déjame enseñarte...' WHERE `ID`=6134;
