UPDATE `locales_broadcast_text` SET `MaleText_loc1`='토륨 대장조합 가을 품목:$B$B이 시대의 모험가를 위한 각종 용품을 아주 저렴한 가격에 제공하고 있습니다! 찾기 힘든 재료를 어디서 구해야 하는지도 설명해 드립니다.', `MaleText_loc4`='瑟银兄弟会的目录：$B$B你可以从中找到所有你冒险必需的最强装备！我们还将告诉你到哪儿去收集这些材料。', `MaleText_loc5`='瑟銀兄弟會的目錄:$B$B你可以從中找到所有你冒險必需的最強裝備!我們還將告訴你到哪兒去收集這些材料。', `MaleText_loc7`='Catálogo de otoño de la Hermandad del Torio:$B$B¡En su interior encontrarás las mejores ofertas para todas las necesidades de un aventurero! Incluso se indica dónde recoger los componentes y suministros más difíciles de encontrar.' WHERE `ID`=6144;
