UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제4장: 신비한 수정과 아케이나이트', `MaleText_loc4`='关于奥术水晶和奥金的章节。', `MaleText_loc5`='關於秘法水晶和奧金的章節。', `MaleText_loc7`='Capítulo sobre cristales Arcanos y arcanita.', `FemaleText_loc1`='제4장: 신비한 수정과 아케이나이트', `FemaleText_loc4`='关于奥术水晶和奥金的章节。', `FemaleText_loc5`='關於秘法水晶和奧金的章節。', `FemaleText_loc7`='Capítulo sobre cristales Arcanos y arcanita.' WHERE `ID`=6151;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대는 내 기권을 받아들였소.', `MaleText_loc4`='你接受我的投降了。', `MaleText_loc5`='你接受我的投降了。', `MaleText_loc7`='Has aceptado mi rendición.', `FemaleText_loc1`='그대는 내 기권을 받아들였소.', `FemaleText_loc4`='你接受我的投降了。', `FemaleText_loc5`='你接受我的投降了。', `FemaleText_loc7`='Has aceptado mi rendición.' WHERE `ID`=6152;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자, 저를 따라 오세요.', `FemaleText_loc4`='请跟着我。', `FemaleText_loc5`='請跟著我。', `FemaleText_loc7`='Por favor, sígueme.' WHERE `ID`=6153;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아직 확실하게는 모르겠지만 이 온천에는 뭔가 이상한 점이 있어요...', `FemaleText_loc4`='我并没有真正弄明白这是什么，但那些温泉却有些奇怪……', `FemaleText_loc5`='我並沒有真正弄明白這是什麼，但那些溫泉卻有些奇怪...', `FemaleText_loc7`='Nunca he entendido qué es, pero hay algo muy extraño en las fuentes termales...' WHERE `ID`=6154;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 얕은 물웅덩이 속으로 칼을 던집니다.', `FemaleText_loc4`='%s把剑扔进浅水池。', `FemaleText_loc5`='%s把劍扔進淺水池。', `FemaleText_loc7`='%s sumerge la espada en las aguas poco profundas.' WHERE `ID`=6155;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 온천수에 뭔가를 넣었다가 꺼내면 성능이 엄청나게 향상된다는 걸 최근에 알아냈어요.', `FemaleText_loc4`='我发现当我把什么东西扔进水里然后再拿回它时，它已经明显变大了。', `FemaleText_loc5`='我發現當我把什麼東西扔進水裡然後再拿回它時，它已經明顯變大了。', `FemaleText_loc7`='He descubierto que si arrojo algo al agua mejora de forma increíble cuando lo vuelvo a sacar.' WHERE `ID`=6156;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이유야 어쨌건 간에 아주 효과가 좋더라고요!', `FemaleText_loc4`='好吧，不管它是什么，效果很好！', `FemaleText_loc5`='好吧，不管它是什麼，效果很好!', `FemaleText_loc7`='Bien, sea lo que sea, ¡funciona bastante bien!' WHERE `ID`=6157;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그래서 더 연구를 해보려고요... 또 제 도움이 필요하시면 이곳으로 언제든지 절 찾아오세요.', `FemaleText_loc4`='而我下决心要找出更多相关的东西……如果你还需要我的帮助，你知道我会在哪里。', `FemaleText_loc5`='而我下決心要找出更多相關的東西...如果你還需要我的幫助，你知道我會在哪裡。', `FemaleText_loc7`='Y no descansaré hasta llegar al final de este asunto... Así que si necesitas mi ayuda de nuevo, ya sabes dónde encontrarme.' WHERE `ID`=6158;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 책의 제목은 장식체로 ''마우린 달슨의 일기''라고 쓰여 있습니다.', `MaleText_loc4`='这本书的标题是手写体：莫琳·达尔松的日记。', `MaleText_loc5`='這本書的標題是手寫體:莫琳·達爾松的日記。', `MaleText_loc7`='El título de este libro muestra una rúbrica escrita a mano: Diario de Maureen Dalson.' WHERE `ID`=6159;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='책장이 누렇게 변해 가는 일기장의 마지막 페이지가 펼쳐진 채로 있습니다.$B$B"해럴드가 언데드로 변해버려 이제 무슨 일이 벌어질지 모르겠다. 안간힘을 써서 그를 가두고 문을 잠갔다. 열쇠를 감춰뒀는데, 효과가 있었으면 좋겠다...$B$B여기서 빠져나가고 싶지만 그러려면 돈이 든다. 우리 물건은 모두 장롱에 넣어 둔 것 같다... 그러고 보니 해럴드에게도 열쇠가 있지 않나?$B$B그건 일단 쉬고 나서 생각해야겠다. 너무 피곤하다."', `MaleText_loc4`='一本打开的日记放在你的面前，发黄的书页上写着如下的文字：$B$B“哈洛德变成了这个样子，我不知道接下来会发生什么事。把他拖进我能找到的唯一可以关住他的地方之后，我已经心力憔悴了。我把钥匙藏在身上，祈祷能渡过这个难关……$B$B我希望能离开这里，但我需要钱。我想我们的东西都在那个柜橱里……现在我想起来了，哈罗德是不是把柜橱的钥匙藏在自己身上了？$B$B我要先休息一下，现在我实在是太疲倦了。”', `MaleText_loc5`='一本打開的日記放在你的面前，發黃的書頁上寫著如下的文字:$B$B「哈洛德變成了這個樣子，我不知道接下來會發生什麼事。把他拖進我能找到的唯一可以關住他的地方之後，我已經心力憔悴了。我把鑰匙藏在身上，祈禱能渡過這個難關...$b$b我希望能離開這裡，但我需要錢。我想我們的東西都在那個櫃櫥裡...現在我想起來了，哈樂德是不是把櫃櫥的鑰匙藏在自己身上了?$B$B我要先休息一下，現在我實在是太疲倦了。」', `MaleText_loc7`='Un diario con páginas que comienzan a amarillear descansa abierto por la última entrada:$B$B"No sé lo que va a ocurrir ahora que Harold se ha transformado. Gasté todas mis fuerzas en arrastrarlo hasta el único lugar que pude encontrar y en el que pudiera quedar encerrado. Escondí en mí la llave y ruego porque funcione...$B$BEspero poder salir de aquí, pero necesito dinero para hacerlo. Creo que todas nuestras cosas están en el armario... y ahora que lo pienso, ¿no tiene Harold la llave con él?$B$BDescansaré, estoy terriblemente cansada."' WHERE `ID`=6160;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제4장: 어둠의 허물', `MaleText_loc4`='关于暗影之皮的章节。', `MaleText_loc5`='關於暗影之皮的章節。', `MaleText_loc7`='Capítulo sobre la piel de Sombra.', `FemaleText_loc1`='제4장: 어둠의 허물', `FemaleText_loc4`='关于暗影之皮的章节。', `FemaleText_loc5`='關於暗影之皮的章節。', `FemaleText_loc7`='Capítulo sobre la piel de Sombra.' WHERE `ID`=6161;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='광장 정문에 침입자들이 나타났다! 리븐데어 군주님께 알려드려야 해!', `MaleText_loc4`='入侵者到达偏门了！赶快通知瑞文戴尔男爵！', `MaleText_loc5`='入侵者到達側門了!趕快通知瑞文戴爾男爵!', `MaleText_loc7`='¡Intrusos en la Puerta de Servicio! ¡Hay que avisar a Lord Osahendido!' WHERE `ID`=6162;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='닳아해진 누더기골렘 조각을 찾는다면 스트라솔름으로 가보십시오.$B$B예전에는 빛의 수호자 우서 경의 고향이었지만, 지금은 켈투자드의 부하들이 점령하고 있습니다.$B$B그 불타는 도시에서 위험을 무릅쓰고 누더기골렘을 쓰러뜨리면 닳아해진 누더기골렘 조각을 얻을 수 있습니다!', `MaleText_loc4`='要是你想要磨损的憎恶缝合线，你就得长途跋涉去斯坦索姆。$B$B以前那儿是光明使者的家园，现在被克尔苏加德的仆从们侵占了。$B$B解除这燃烧的城市的危机，击败那些强大的憎恶吧！从他们那儿夺取磨损的憎恶缝合线！', `MaleText_loc5`='要是你想要磨損的憎惡縫合線，你就得長途跋涉去斯坦索姆。$B$B以前那兒是光明使者的家園，現在被科爾蘇加德的僕從們侵佔了。$B$B解除這燃燒的城市的危機，擊敗那些強大的憎惡吧!從他們那兒奪取磨損的憎惡縫合線!', `MaleText_loc7`='Si las costuras desgarradas de abominación son tu deseo, Stratholme es tu destino.$B$BLa antigua ciudad del Iluminado, invadida ahora por los esbirros de Kel''Thuzad.$B$B¡Desafía los peligros de la ciudad en llamas y derrota a las carnosas abominaciones! Toma de ellas tu premio: ¡costuras desgarradas de abominación!' WHERE `ID`=6163;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='광신도들의 마지막 성소... 지금도 그곳에서는 마력 깃든 붉은 실타래로 붉은 제복을 지어 입고 있습니다!$B$B모험가여, 스트라솔름으로!', `MaleText_loc4`='那些疯狂的信徒的最后一处圣地。他们在那制作红色制服，使用的就是魔化红线！$B$B冒险家们，向斯坦索姆城前进！', `MaleText_loc5`='那些瘋狂的信徒的最後一處聖地。他們在那製作紅色制服，使用的就是附魔血色絲線!$B$B冒險家們，向斯坦索姆城前進!', `MaleText_loc7`='El último santuario de los zelotes. ¡Allí crean sus uniformes escarlata, imbuidos de magia por el hilo escarlata encantado!$B$B¡A Stratholme, aventurero!' WHERE `ID`=6164;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='인간과 스컬지 모두에게 최고의 신체 보존제로 알려진 프로스트위스퍼의 불변의 액체... 이 물건을 찾을 수 있는 곳은 오직 한 군데뿐입니다. 이 액체 이름의 모태가 된 리치는 외부인을 몹시 싫어합니다.$B$B그래도 이 액체를 원한다면 스칼로맨스로 가보십시오.', `MaleText_loc4`='人类和亡灵天灾所知的最好的肉类防腐剂——莱斯·霜语的防腐液。这种防腐剂只能在一个地方找到，人们认为这东西得名于巫妖，要去那种地方一定不是件容易的事儿。$B$B但是……如果这正是你想要的东西，就去通灵学院吧……', `MaleText_loc5`='人類和天譴軍團所知的最好的肉類防腐劑─萊斯·霜語的防腐液。這種防腐劑只能在一個地方找到，人們認為這東西得名於巫妖，要去那種地方一定不是件容易的事兒。$B$B但是...如果這正是你想要的東西，就去通靈學院吧...', `MaleText_loc7`='El mejor conservador de carne conocido entre los hombres y los miembros de la Plaga: el líquido de embalsamar de Murmuhielo. Los aventureros solo pueden encontrarlo en un lugar y los que le han dado nombre no son amigos de visitas.$b$bSin embargo... si es lo que necesitas, tendrás que dirigirte a Scholomance...' WHERE `ID`=6165;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스칼로맨스가 세워진 땅은 바로브 가에서 켈투자드에게 넘긴 땅입니다. 땅을 넘겨준 대가로, 켈투자드는 그들을 언데드로 만들어 영생을 허락했습니다. 그리하여 저주받은 자들의 교단은 그 땅에 본거지를 세우고, 스컬지의 더럽고 사악한 마법을 배울 수 있게 된 것입니다.$B$B어둠의 무기고에 가면 어둠의 허물의 주인, 여군주 일루시아 바로브를 찾을 수 있습니다.$B$B허황된 꿈을 쫓는 망자의 좋은 본보기죠.', `MaleText_loc4`='巴罗夫家族将通灵学院所在的土地给了克尔苏加德。作为交换这块诅咒神教可以研究亡灵天灾堕落法术的地方，克尔苏加德让巴罗夫家族以亡灵的形式获得永生。$B$B在阴影拱顶房间中，你能找到暗影之皮及其拥有者伊露希亚·巴罗夫。$B$B你无法找到比暗影之皮更好反射虚无和死亡的镜子了。', `MaleText_loc5`='巴羅夫家族將通靈學院所在的土地給了科爾蘇加德。作為交換這塊詛咒神教可以研究天譴軍團墮落法術的地方，科爾蘇加德讓巴羅夫家族以亡靈的形式獲得永生。$B$B在暗影穹殿中，你能找到暗影之皮及其擁有者伊露希亞·巴羅夫女士。$B$B你無法找到比暗影之皮更好反射虛無和死亡的鏡子了。', `MaleText_loc7`='El suelo sobre el que Scholomance fue construida fue entregado a Kel''Thuzad por la familia Barov. A cambio de esta tierra (un lugar donde el Culto de los Malditos podía aprender la vil magia de la Plaga), Kel''Thuzad garantizó a los Barov la inmortalidad a través de la no-muerte.$B$BEs en La Cámara de las Sombras donde encontrarás la piel de Sombra, junto a su dueña, Lady Illucia Barov.$B$BNunca existió mejor espejo para los vanidosos y los muertos.' WHERE `ID`=6166;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='토륨 대장조합의 주요 상품입니다.$B$B토륨 광맥에서 아케이나이트 수정을 구할 수 있습니다. 강력한 연금술사들의 탁월한 솜씨에 의해 아케이나이트 주괴가 탄생하는 것입니다.$B$B채광 기술이 없다면, 실력있는 광부를 하나 찾아놓으십시오. 솜씨 좋은 연금술사도 찾으시고 말입니다. 둘 다 필요할 겁니다.', `MaleText_loc4`='瑟银兄弟会。$B$B奥术水晶是从富瑟银矿脉中采集的。通过强大的炼金师的威力，奥金诞生了。$B$B找出一个矿工，如果你不是的话……还有找到一个出色的炼金术士！你两样都会需要的。', `MaleText_loc5`='瑟銀兄弟會。$B$B秘法水晶是從富瑟銀礦脈中採集的。通過強大的鍊金師的威力，奧金誕生了。$B$B找出一個礦工，如果你不是的話...還有找到一個出色的鍊金師!你兩樣都會需要的。', `MaleText_loc7`='Un producto de primera necesidad de la Hermandad del Torio.$B$BLos cristales de arcanita se extraen de las vetas ricas de torio. Gracias a la proeza de poderosos alquimistas nacen las barras de arcanita.$B$BBusca a un minero, si tú no lo eres... ¡y encuentra a un buen alquimista! Necesitarás a los dos.' WHERE `ID`=6167;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 불안한 듯 왔다 갔다 합니다.', `MaleText_loc4`='%s来回焦急地踱步。', `MaleText_loc5`='%s來回焦急地踱步。', `MaleText_loc7`='%s se mueve adelante y atrás con nerviosismo.' WHERE `ID`=6168;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='감히 이곳에 들어오다니! 모두 처치해!', `FemaleText_loc4`='你们不该来这里！杀了他们！', `FemaleText_loc5`='你們不該來這裡!殺了他們!', `FemaleText_loc7`='¡No deberías estar aquí! ¡Mátalos!' WHERE `ID`=6169;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하찮은 것!', `FemaleText_loc4`='死不足惜。', `FemaleText_loc5`='不值得一提。', `FemaleText_loc7`='Qué muerte miserable.' WHERE `ID`=6170;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 감히 내 명상을 방해하는 거냐?', `MaleText_loc4`='谁敢打扰我的冥思？', `MaleText_loc5`='誰敢擾亂我的冥想?', `MaleText_loc7`='¿Quién osa interrumpir mi meditación?' WHERE `ID`=6171;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 가라.', `MaleText_loc4`='尘归尘，土归土。', `MaleText_loc5`='塵歸塵，土歸土。', `MaleText_loc7`='Polvo al polvo.' WHERE `ID`=6172;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이놈들! 놈리건은 내 꺼란 말이야!', `MaleText_loc4`='篡位者！诺莫瑞根是我的！', `MaleText_loc5`='篡位者!諾姆瑞根是我的!', `MaleText_loc7`='¡Usurpadores! ¡Gnomeregan es mía!' WHERE `ID`=6173;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 발명품들이야말로 놈리건의 미래지! 모두 쓸어버려!', `MaleText_loc4`='我的机器代表未来！它们会将你们统统摧毁的！', `MaleText_loc5`='我的機器人才是未來!你們都得死!', `MaleText_loc7`='¡Mis máquinas son el futuro! ¡Acabarán con todos ustedes!' WHERE `ID`=6174;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끝장을 내주지!', `MaleText_loc4`='站着别动！', `MaleText_loc5`='給我死透點!', `MaleText_loc7`='¡Y PERMANECE así muerto!' WHERE `ID`=6175;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭탄! 폭탄이 필요해! 폭탄 더 가져와!', `MaleText_loc4`='爆炸！更多爆炸！我需要更多爆炸！', `MaleText_loc5`='炸藥!更多的炸藥!我要更多的炸藥!', `MaleText_loc7`='¡Explosiones! ¡MÁS explosiones! ¡Tengo que provocar más explosiones!' WHERE `ID`=6176;
