UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 안에 담겨있는 게 무엇입니까, $n?$B$B<당신의 가방 밖으로 튀어나온 불타지 않은 판금 건틀릿을 가리키는 말리퍼스>', `MaleText_loc4`='那是什么， $n？$B$B<玛雷弗斯指着你从包裹里拿出来的未淬火的板甲护手。>', `MaleText_loc5`='那是什麼， $n?$B$B<瑪雷弗斯指著你從包裹裡拿出來的未淬火的鎧甲護手。>', `MaleText_loc7`='¿Qué tienes ahí, $n?$B$B<Malyfous señala los guanteletes de placas sin templar que cuelgan de tu bolsa.>' WHERE `ID`=6209;
