UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 상자에서 화염병 몇 개를 꺼내가는 걸 잊지 말게나. 녀석들의 지휘 막사를 파괴하는 데 꼭 필요할 거야.', `MaleText_loc4`='别忘记从箱中的瓶子里面取出瓶中火。你必须用它来破坏他们指挥官的帐篷。', `MaleText_loc5`='別忘記從箱中的瓶子裡面取出瓶中火。你必須用它來破壞他們指揮官的帳篷。', `MaleText_loc7`='No olvides coger algún fuego en botella de esa caja. Lo necesitarás para destruir su tienda de mando.' WHERE `ID`=6211;
