UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 허물어지면서 힘을 잃습니다!', `MaleText_loc4`='%s碎了，失去了力量！', `MaleText_loc5`='%s分裂並失去了力量!', `MaleText_loc7`='%s se desmorona y pierde fuerza.' WHERE `ID`=6255;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가까이 다가가 보니, 장비 안에 이상한 액체와 혼합물이 거품을 내며 부글거리고 있습니다. 장비 옆에는 수액괴물 견본을 집어넣는 데 쓰일 법한 커다란 집게가 놓여 있습니다.$B$B안전 장비 비슷한 게 있는 것 같지만 먼지가 쌓여 있어 오랫동안 사용된 적이 없는 듯합니다.$B$B비커에 견본을 넣으시겠습니까?', `MaleText_loc4`='当你靠近时，那些液体和混合物剧烈地翻腾起来。设备旁边是一把巨大的钳子，似乎很适合用来夹起淤泥样本。$B$B还有安全齿轮装备，但是上面布满灰尘，似乎很久没有使用过了。$B$B将一些样本放进烧杯吗？', `MaleText_loc5`='當你靠近時，那些液體和混合物劇烈地翻騰起來。設備旁邊是一把巨大的鉗子，似乎很適合用來夾起軟泥樣本。$B$B還有安全齒輪裝備，但是上面布滿灰塵，似乎很久沒有使用過了。$B$B將一些樣本放進燒杯嗎?', `MaleText_loc7`='Los líquidos y mezclas burbujean y se agitan cuanto te acercas. Junto al equipo hay unas grandes tenazas que parecen adecuadas para recoger muestras de moco.$B$BTambién hay equipamiento de seguridad, pero parece polvoriento y olvidado.$B$B¿Pones alguna de tus muestras en los vasos?' WHERE `ID`=6256;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 폭발하며 몇 마리 위액괴물이 나타납니다!', `MaleText_loc4`='%s爆破，释放出数个绿汁软泥怪！', `MaleText_loc5`='%s爆破並釋放數個綠汁泥漿怪!', `MaleText_loc7`='%s explota y suelta varias babosas de bilis.' WHERE `ID`=6257;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 역겨운 위액괴물을 내뿜습니다!', `MaleText_loc4`='%s喷出一股令人恶心的绿汁软泥！', `MaleText_loc5`='%s打嗝嘔出了一隻令人噁心的綠汁泥漿怪!', `MaleText_loc7`='%s escupe una babosa de bilis.' WHERE `ID`=6258;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하하! 당신이 그 머리를 보여줬을 때 사색이 된 다릴의 표정은 정말로 잊을 수 없을 거예요!', `FemaleText_loc4`='哈哈，$n！我永远不会忘记达瑞尔看到你时他脸上的表情！', `FemaleText_loc5`='哈哈，$n!我永遠不會忘記達瑞爾看到你帶來的頭顱時他臉上的表情!', `FemaleText_loc7`='¡Ajá, $n! ¡Nunca olvidaré la cara que se le quedó a Daryl cuando le enseñaste aquella cabeza!' WHERE `ID`=6259;
