UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 차례야, 이 바보야. 자, 이제 던진다!', `MaleText_loc4`='傻瓜，轮到我了！我要投掷了。', `MaleText_loc5`='傻瓜，輪到我了!我要投擲了。', `MaleText_loc7`='¡Mi turno, estúpido! Ahora me toca lanzar a mí.', `FemaleText_loc1`='내 차례야, 이 바보야. 자, 이제 던진다!', `FemaleText_loc4`='傻瓜，轮到我了！我要投掷了。', `FemaleText_loc5`='傻瓜，輪到我了!我要投擲了。', `FemaleText_loc7`='¡Mi turno, estúpido! Ahora me toca lanzar a mí.' WHERE `ID`=6261;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 마지막으로 던졌잖아, 바보야. 이제 내 차례라고.', `MaleText_loc4`='你已经掷过最后一颗了，笨蛋。现在该我了。', `MaleText_loc5`='你已經擲過最後一顆了，笨蛋。現在該我了。', `MaleText_loc7`='Tú lanzaste el último, idiota. Es mi turno.', `FemaleText_loc1`='네가 마지막으로 던졌잖아, 바보야. 이제 내 차례라고.', `FemaleText_loc4`='你已经掷过最后一颗了，笨蛋。现在该我了。', `FemaleText_loc5`='你已經擲過最後一顆了，笨蛋。現在該我了。', `FemaleText_loc7`='Tú lanzaste el último, idiota. Es mi turno.' WHERE `ID`=6262;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 서로 앞뒤로 밀치기 시작합니다.', `MaleText_loc4`='%s开始互相推攘起来。', `MaleText_loc5`='%s開始互相推來推去。', `MaleText_loc7`='%s comienzan a empujarse.', `FemaleText_loc1`='%s|1이;가; 서로 앞뒤로 밀치기 시작합니다.', `FemaleText_loc4`='%s开始互相推攘起来。', `FemaleText_loc5`='%s開始互相推來推去。', `FemaleText_loc7`='%s comienzan a empujarse.' WHERE `ID`=6263;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다단가는 어떤 음식을 좋아하죠?', `MaleText_loc4`='达丹加喜欢吃什么？', `MaleText_loc5`='達丹加喜歡吃什麼?', `MaleText_loc7`='¿Qué le gusta comer a Dadanga?', `FemaleText_loc1`='다단가는 어떤 음식을 좋아하죠?', `FemaleText_loc4`='达丹加喜欢吃什么？', `FemaleText_loc5`='達丹加喜歡吃什麼?', `FemaleText_loc7`='¿Qué le gusta comer a Dadanga?' WHERE `ID`=6264;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리가 운고로 분화구에 머무르기 시작하면서, 다단가는 이곳에서 자라나는 붉은꽃잎덩굴손 씨눈에 맛을 들였어요.$B$B누군가 좀 모아서 가져다주면 우리 다단가에게 좋은 간식이 될 텐데...', `FemaleText_loc4`='从我们呆在环形山这里开始，达丹加就喜欢上了遍布这里的巨大的血瓣花苗芽。$B$B我敢肯定她会喜欢，如果你愿意带给她一大堆花苗芽的话……', `FemaleText_loc5`='從我們待在環形山這裡開始，達丹加就喜歡上了遍佈這裡的巨大的血瓣花苗芽。$B$B我敢肯定她會喜歡，如果你願意帶給她一大堆花苗芽的話...', `FemaleText_loc7`='Desde que comenzó nuestra estancia en el cráter, Dadanga se ha aficionado a los brotes Sangrepétalo que crecen por toda la zona.$B$BEstoy segura de que le gustaría comer algo, si te apetece traerle algunos...' WHERE `ID`=6265;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알았어. 알았다고! 네 차례 해!', `MaleText_loc4`='好，好！轮到你了！', `MaleText_loc5`='好，好!輪到你了!', `MaleText_loc7`='¡Vale, vale! ¡Te toca a ti!', `FemaleText_loc1`='알았어. 알았다고! 네 차례 해!', `FemaleText_loc4`='好，好！轮到你了！', `FemaleText_loc5`='好，好!輪到你了!', `FemaleText_loc7`='¡Vale, vale! ¡Te toca a ti!' WHERE `ID`=6266;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여어, 친구. 필요한 물건을 조금만 구하면 당장에라도 자넬 치료해 줄 수 있을 텐데!', `MaleText_loc4`='嗨，只要我手头的物资能够再多一些，我就能立刻给你修理好！', `MaleText_loc5`='嘿，老兄。等我再多拿到點補給品，我就來幫你!', `MaleText_loc7`='Ey, colega. En cuanto me haga con algunos suminihtros más, ¡te curaré en un santiamén!' WHERE `ID`=6267;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 봉사 활동을 하는 것도 의술사 수련의 일부라네. 자넨 날 도와줬으니 공짜로 도와주지. 어딜 고쳐 줄까?', `MaleText_loc4`='在这里志愿工作就是我通过巫医学校课程的方式。既然你帮了我，我就免费帮你。需要修理什么吗？', `MaleText_loc5`='在這裡做義工讓我通過了巫醫學校課程的考試。既然你幫了我，我就免費幫你。需要修理什麼嗎?', `MaleText_loc7`='Eh''te trabajo voluntario es mi forma de entrar en la Escuela de médicos brujos. Como tú me has ayuda''o yo te ayudaré gratis. ¿Qué necesitas?' WHERE `ID`=6268;
