UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 괜찮습니다, 아우비. 습격한 자들을 모두 처치했습니다.', `MaleText_loc4`='你会没事的，奥比。攻击你的人已经被杀死了。', `MaleText_loc5`='你會沒事的，奧比。攻擊你的人已經被殺死了。', `MaleText_loc7`='Te pondrás bien, Awbee. Tus atacantes han sido aniquilados.', `FemaleText_loc1`='이제 괜찮습니다, 아우비. 습격한 자들을 모두 처치했습니다.', `FemaleText_loc4`='你会没事的，奥比。攻击你的人已经被杀死了。', `FemaleText_loc5`='你會沒事的，奧比。攻擊你的人已經被殺死了。', `FemaleText_loc7`='Te pondrás bien, Awbee. Tus atacantes han sido aniquilados.' WHERE `ID`=6275;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$R, 제 말을 잘 들으세요...$B$B밤에 검은 용을 탄 자들이 나타나서 무서울 정도로 빠르고 정확하게 저 같은 어린 용을 낚아채 어둠 속으로 사라졌어요.$B$B저는 형제와 누이들이 녀석들의 실험에 이용되는 끔찍한 광경을 목격하게 됐죠. 우리의 정기를 이용해 유채용군단을 만들려는 거였어요.', `MaleText_loc4`='听着，$r。听好了……$B$B龙骑士骑着黑龙，趁着夜色而来。他们迅速出击，给予幼龙——像我这样经验不足的幼龙——致命而精确的攻击。$B$B我怀着极大的恐惧注视着我的兄弟姐妹被他们用在实验中。我们的精华能创造出多彩龙人。', `MaleText_loc5`='聽著，$r。聽好了...$b$b龍騎士騎著黑龍，趁著夜色而來。他們迅速出擊，給予幼龍─像我這樣經驗不足的幼龍─致命而精確的攻擊。$B$B我懷著極大的恐懼注視著我的兄弟姐妹被他們用在實驗中。我們的精華能創造出炫彩龍人。', `MaleText_loc7`='Escucha, $r. Escúchame bien...$B$BLos jinetes de dragones vinieron por la noche, cabalgando a lomos del Vuelo Negro. Golpearon rápidamente y con una precisión letal, llevándose a las jóvenes crías, como yo, y escapando ocultos en el velo de la oscuridad.$B$BVi con horror cómo utilizaban a mis hermanos y hermanas para sus experimentos. Con nuestra esencia habrían de crear el Vuelo Cromático.' WHERE `ID`=6276;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 말해봐요...', `MaleText_loc4`='请继续……', `MaleText_loc5`='請繼續...', `MaleText_loc7`='Continúa, por favor...', `FemaleText_loc1`='계속 말해봐요...', `FemaleText_loc4`='请继续……', `FemaleText_loc5`='請繼續...', `FemaleText_loc7`='Continúa, por favor...' WHERE `ID`=6277;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그나마 네파리안은 적합하지 않은 실험 대상은 즉시 없애버리라고 명령했지만, 이 천벌 받을 괴물들은 죽을 때까지 끔찍한 고문을 가했어요.$B$B놈들은 우리를 철저하게 ''망가뜨린'' 후 목숨이 붙어 있는 자와 죽은 자를 모두 모아 이 악당들에게 던져주었지. 녀석들은 우리의 몸을 가지고 온갖 더러운 놀이를 했어요. 용암 속에 던져 넣기도 하고, 피에 굶주린 병사들에게 던져주기도 했죠.', `MaleText_loc4`='奈法利安已经下令立即杀死那些不合适的实验品，但是这些恶心的野兽在没有对我们反复摧残之前是不会这样做的。$B$B当我们被彻底折磨完了之后，他们会将我们丢给那些杀手。我们的身体将成为他们游戏的道具：被投掷到熔岩中，或是丢弃到开阔地带，等待着被嗜血如命的军团砍杀。', `MaleText_loc5`='奈法利安已經下令立即摧毀那些不合適的實驗品，但是這些噁心的野獸在沒有對我們折磨「夠」之前是不會這樣做的。$B$B當我們完全「壞」了之後，他們會將我們的殘骸丟給那些暴徒。我們的身體將成為他們變態遊戲的道具:被投擲到熔岩中，或是更不幸的，淪落到嗜血如命的軍團士兵手裡。', `MaleText_loc7`='Nefarian había ordenado destruir inmediatamente a los sujetos no aptos, pero esas bestias repugnantes no iban a hacerlo sin someternos antes a una "gran" tortura.$B$BCuando estuvimos "destrozados", reunieron nuestros restos y nos arrojaron a estas bestias. Utilizaron nuestros cuerpos como instrumento para sus perversos juegos: fuimos arrojados a la lava o a algo aún peor: a los brazos abiertos y ansiosos de la sádica legión de ahí abajo.' WHERE `ID`=6278;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 끔찍하군요.', `MaleText_loc4`='太可怕了。', `MaleText_loc5`='太可怕了。', `MaleText_loc7`='Es horrible.', `FemaleText_loc1`='너무 끔찍하군요.', `FemaleText_loc4`='太可怕了。', `FemaleText_loc5`='太可怕了。', `FemaleText_loc7`='Es horrible.' WHERE `ID`=6279;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='녀석들이 날 저 밑에 있는 악마들에게 던지려던 찰나에 당신이 나타난 거예요. 정말로 고마워요. 혹시 제가, 아니, 우리 푸른용군단의 자손들이 당신을 도와줄 일이 있나요?$B$B아니면, 많은 위험을 무릅쓰고 여기까지 왔으니 조금만 더 힘을 내서 네파리안과 그의 검은바위일족 군단과 싸워주지 않겠어요?', `MaleText_loc4`='就在他们要把我扔给下面的魔鬼时你来了——为此我感谢你。或许，我——更确切的说——我们，蓝龙是不是可以进一步帮你？$B$B你已经走到这一步，$r，冒了很多险。你还愿去参加抵抗奈法利安和他的黑石军团的战斗吗？', `MaleText_loc5`='就在他們要把我扔給下面的魔鬼時你來了─為此我感謝你。或許，我─更確切的說─我們，藍龍軍團是不是可以進一步幫你?$B$B你已經走到這一步，$r，冒了很多險。你還願去參加抵抗奈法利安和他的黑石軍團的戰鬥嗎?', `MaleText_loc7`='Viniste justo cuando iban a arrojarme a esos demonios, te doy las gracias. ¿Hay algún modo en el que yo, o mejor dicho, nosotros, los del Vuelo Azul, podamos ayudarte?$B$BHas llegado hasta aquí, $r, y has arriesgado mucho. ¿Seguirás adelante para combatir a Nefarian y a su legión de Roca Negra?' WHERE `ID`=6280;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론 그렇게 해드리죠.', `MaleText_loc4`='毫无疑问。', `MaleText_loc5`='毫無疑問。', `MaleText_loc7`='¡Desde luego!', `FemaleText_loc1`='물론 그렇게 해드리죠.', `FemaleText_loc4`='毫无疑问。', `FemaleText_loc5`='毫無疑問。', `FemaleText_loc7`='¡Desde luego!' WHERE `ID`=6281;
