UPDATE `locales_broadcast_text` SET `MaleText_loc1`='애쉬아리 수정이 파괴되었다! 도살장이 위험하다!', `MaleText_loc4`='阿莎利水晶已经被摧毁了！屠宰场危险！', `MaleText_loc5`='阿莎利水晶已經被摧毀了!屠宰房危險!', `MaleText_loc7`='¡Han destruido los Cristales de Ash''ari! ¡El Degolladero es vulnerable!' WHERE `ID`=6289;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용을 사냥하러 왔다면 내가 대접하겠소. 애도의 뜻은 어디로 전해야 하는 거요?', `MaleText_loc4`='如果你到这儿来猎龙，那你就是我的客人了。我应该去哪里表示我的哀悼？', `MaleText_loc5`='如果你到這兒來獵龍，那你就是我的客人了。我應該去哪裡表示我的哀悼?', `MaleText_loc7`='Si has venido para cazar dragones, sé $gbienvenido:bienvenida;. ¿Adónde debo enviar mis condolencias?' WHERE `ID`=6290;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네한테서 나는 악취 때문에 수 킬로 멀리서도 용이 쫓아오겠군. 원하는 거나 빨리 말해보게.', `MaleText_loc4`='你的臭气会把数英里内的所有龙都招来的。告诉我你想要什么，快些。', `MaleText_loc5`='你的臭氣會把數英哩內的所有龍都招來的。告訴我你想要什麼，快些。', `MaleText_loc7`='Tu hedor atraerá a todos los dragones que estén a millas de distancia. Dime qué quieres, y que sea rápido.' WHERE `ID`=6291;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 올 거라고 영혼들이 말해주었다네. 어떤 이유로 날 찾아오긴 하는데 그 이유는 자네도 모를 것이라고 하더군. 그래, 이곳에 온 이유는 알고 있나?', `MaleText_loc4`='灵魂告诉我说你会来的，你会出于某种原因来此寻找我，但是你也许自己都不清楚这个原因。那么，你知道你为什么会在这儿吗？', `MaleText_loc5`='靈魂告訴我說你會來的，你會出於某種原因來此尋找我，但是你也許自己都不清楚這個原因。那麼，你知道你為什麼會在這兒嗎?', `MaleText_loc7`='Los espíritus me advirtieron de que vendrías, de que me buscabas por alguna razón, una razón que quizás ni tú mismo conocerías. Así que... ¿sabes por qué estás aquí?' WHERE `ID`=6292;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 안녕하세요! 난 사라라고 해요. 뭐, 도와드릴 일이라도 있나요?', `FemaleText_loc4`='哦你好！我的名字是萨拉。我能为你做什么吗？', `FemaleText_loc5`='哦你好!我的名字是薩拉。我能為你做什麼嗎?', `FemaleText_loc7`='¡Oh, hola! Mi nombre es Sarah. ¿Qué puedo hacer por ti?' WHERE `ID`=6293;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='숲이 그대가 온다는 소식을 전해주긴 했는데 오는 이유에 대해서는 말하지 않더군요. 자, 제게 오신 이유를 말씀해 주시겠어요?', `FemaleText_loc4`='森林告知我你的存在，但是没有说你为什么在这里。那么，告诉我真相吧。', `FemaleText_loc5`='森林告知我你的存在，但是沒有說你為什麼在這裡。那麼，告訴我真相吧。', `FemaleText_loc7`='El bosque me advirtió de tu presencia, pero no me dijo por qué has venido. Así que habla e ilumíname.' WHERE `ID`=6294;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하신가!', `MaleText_loc4`='你做得怎么样啦！', `MaleText_loc5`='你做得怎麼樣啦!', `MaleText_loc7`='¡Qué tal va colega!' WHERE `ID`=6295;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='에메랄드 의회에서 당신을 환영합니다.$B$B당신과 함께 한때 울창했던 이 숲을 다시 일으켜 세우고 보호할 수 있었으면 합니다. 외부에서는 물론이고, 내부에 숨은 다양한 세력이 이 숲을 파괴하려 들고 있어요.$B$B이곳에 있는 힘에 넘어가지 마세요. 이 땅을 다 가진 듯 유혹하며 당신을 타락시킬 거예요.', `FemaleText_loc4`='翡翠议会欢迎你，$n。$B$B希望我们能一起恢复并保护这片曾经繁茂的森林。许多势力试图从外部和……内部毁灭它。$B$B不要被这里的邪恶力量打败——它会腐蚀你，就它腐蚀这片土地一样。', `FemaleText_loc5`='翡翠議會歡迎你，$n。$B$B希望我們能一起恢復並保護這片曾經繁茂的森林。有許多勢力試圖從外部...和內部毀滅它。$B$B不要被此處的力量給影響了─那只會腐化你，就像這整片土地一樣。', `FemaleText_loc7`='El Círculo Esmeralda te da la bienvenida, $n.$B$BCon suerte juntos podremos ayudar a rejuvenecer y proteger este bosque antaño poderoso. Muchas fuerzas pretenden destruirlo, desde dentro... y desde fuera.$B$BNo te dejes convencer por el poder que aquí reside... solo te corromperá, como lo ha hecho con toda esta tierra.' WHERE `ID`=6296;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그레타는 제데나르의 회복과 악령숲을 정화하는 데 큰 책임감을 느끼는 자들을 모으는 데 주력하지만, 나는 타락이 이 땅에 미친 영향을 연구하는 데 주로 시간을 쏟고 있소.$B$B타락이 이 땅의 짐승들에게 어떤 영향을 주었는가? 그들의 고통을 끝내려면 어떻게 해야 하는가?$B$B유감스럽게도 타락이 워낙 심하다 보니 차라리 영원한 안식이 그 해답이 되는 경우가 너무나 많다오.', `MaleText_loc4`='当格雷塔集中精力恢复加德纳尔和对付那些她认为最应该对费伍德森林的堕落负责任的人的时候，我正忙于调查堕落给这片土地带来的影响。$B$B它是如何影响地面上的生物的？该采取什么办法来结束它们所遭受的痛苦？$B$B不幸的是，堕落已经如此深入，永久的沉睡似乎是绝对的答案。', `MaleText_loc5`='當格雷塔集中精力恢復加德納爾和對付那些她認為最應該對費伍德森林的墮落負責任的人的時候，我正忙於調查墮落給這片土地帶來的影響。$B$B它是如何影響地面上的生物的?該採取什麼辦法來結束它們所遭受的痛苦?$B$B不幸的是，墮落已經如此深入，永久的沉睡似乎是絕對的答案。', `MaleText_loc7`='Mientras Greta concentra su energía en recuperar Jaedenar y en los que cree responsables de la corrupción de Frondavil, yo dedico mi tiempo a estudiar los efectos de la corrupción sobre el país.$B$B¿Cómo ha afectado a las criaturas de esta tierra? ¿Qué hacer para poner fin a su sufrimiento?$B$BPor desgracia, la corrupción está tan arraigada que el sueño eterno suele ser la única respuesta.' WHERE `ID`=6297;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법사 지구에 연금술의 모든 것이라는 작은 상점이 있습니다. 마법사 지구를 지나가다 보면 온갖 기이한 상점들을 보게 되는데, 바깥쪽으로 붙어서 계속 가다 보면 틀림없이 찾을 수 있을 겁니다.', `MaleText_loc4`='他在法师区，那儿有一间名叫炼金材料店的小商店。你会在前往法师区的沿途看到各种各样奇怪的商店，但是如果你沿着外围走的话，你一定会找到它的。', `MaleText_loc5`='他在法師區，那兒有一間名叫鍊金材料店的小商店。你會在前往法師區的沿途看到各種各樣奇怪的商店，但是如果你沿著週邊走的話，你一定會找到它的。', `MaleText_loc7`='Escondida en el Barrio de los Magos hay una pequeña tienda llamada El Rincón del Alquimista. Cuando atravieses el Barrio de los Magos verás todo tipo de extrañas tiendas, pero si no te separas del borde exterior seguro que la encontrarás.', `FemaleText_loc1`='마법사 지구에 연금술의 모든 것이라는 작은 상점이 있습니다. 마법사 지구를 지나가다 보면 온갖 기이한 상점들을 보게 되는데, 바깥쪽으로 붙어서 계속 가다 보면 틀림없이 찾을 수 있을 겁니다.', `FemaleText_loc4`='他在法师区，那儿有一间名叫炼金材料店的小商店。你会在前往法师区的沿途看到各种各样奇怪的商店，但是如果你沿着外围走的话，你一定会找到它的。', `FemaleText_loc5`='他在法師區，那兒有一間名叫鍊金材料店的小商店。你會在前往法師區的沿途看到各種各樣奇怪的商店，但是如果你沿著週邊走的話，你一定會找到它的。', `FemaleText_loc7`='Escondida en el Barrio de los Magos hay una pequeña tienda llamada El Rincón del Alquimista. Cuando atravieses el Barrio de los Magos verás todo tipo de extrañas tiendas, pero si no te separas del borde exterior seguro que la encontrarás.' WHERE `ID`=6298;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드 회계사무소는 스톰윈드 상업 지구의 성문 옆에 있습니다. 돈을 세는 게 지겨워질 때는 꼭 황금 장미 여관에 들러 한잔 하시기 바랍니다.', `MaleText_loc4`='暴风城的暴风城会计室位于城中贸易区的前门处。当你厌烦细数你的金钱时，一定要在镶金玫瑰喝一杯。', `MaleText_loc5`='暴風城的暴風城會計室位於城中貿易區的前門處。當你厭煩細數你的金錢時，一定要在鑲金玫瑰喝一杯。', `MaleText_loc7`='La contaduría de Ventormenta se encuentra junto a las puertas principales del Distrito de los Mercaderes de Ventormenta. Y si te cansas de contar tu dinero no olvides visitar la posada La Rosa Áurea para tomar un trago.', `FemaleText_loc1`='스톰윈드 회계사무소는 스톰윈드 상업 지구의 성문 옆에 있습니다. 돈을 세는 게 지겨워질 때는 꼭 황금 장미 여관에 들러 한잔 하시기 바랍니다.', `FemaleText_loc4`='暴风城的暴风城会计室位于城中贸易区的前门处。当你厌烦细数你的金钱时，一定要在镶金玫瑰喝一杯。', `FemaleText_loc5`='暴風城的暴風城會計室位於城中貿易區的前門處。當你厭煩細數你的金錢時，一定要在鑲金玫瑰喝一杯。', `FemaleText_loc7`='La contaduría de Ventormenta se encuentra junto a las puertas principales del Distrito de los Mercaderes de Ventormenta. Y si te cansas de contar tu dinero no olvides visitar la posada La Rosa Áurea para tomar un trago.' WHERE `ID`=6299;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드워프 가열로의 그윽한 연기 냄새가 나지 않으세요? 대장기술을 배우고 싶으시다면 테룸 딥포지를 찾아가셔야 해요. 대성당 광장 바로 북쪽에 있는 드워프 지구에 있습니다.', `MaleText_loc4`='你说你不能在这儿闻到矮人煅炉的烟味？哦，如果你想学习锻造的话就该找瑟鲁姆·深炉。他就在大教堂广场北边的矮人区。', `MaleText_loc5`='你說你不能在這兒聞到矮人鍛爐的煙味?哦，如果你想學習鍛造的話就該找瑟魯姆·深爐。他就在大教堂廣場北邊的矮人區。', `MaleText_loc7`='¿Quieres decir que no puedes oler el humo de las forjas de los enanos desde aquí? Bueno, si quieres aprender herrería estarás buscando a Therum Forjahonda. Está en el Distrito de los Enanos, justo al norte de la Plaza de la Catedral.', `FemaleText_loc1`='드워프 가열로의 그윽한 연기 냄새가 나지 않으세요? 대장기술을 배우고 싶으시다면 테룸 딥포지를 찾아가셔야 해요. 대성당 광장 바로 북쪽에 있는 드워프 지구에 있습니다.', `FemaleText_loc4`='你说你不能在这儿闻到矮人煅炉的烟味？哦，如果你想学习锻造的话就该找瑟鲁姆·深炉。他就在大教堂广场北边的矮人区。', `FemaleText_loc5`='你說你不能在這兒聞到矮人鍛爐的煙味?哦，如果你想學習鍛造的話就該找瑟魯姆·深爐。他就在大教堂廣場北邊的矮人區。', `FemaleText_loc7`='¿Quieres decir que no puedes oler el humo de las forjas de los enanos desde aquí? Bueno, si quieres aprender herrería estarás buscando a Therum Forjahonda. Está en el Distrito de los Enanos, justo al norte de la Plaza de la Catedral.' WHERE `ID`=6300;
