UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어떻게 이럴 수가 있죠! 누가 이런 짓을 시킨 거예요?', `FemaleText_loc4`='你个尖酸的刻薄鬼！谁把这个给你的？', `FemaleText_loc5`='你個尖酸的刻薄鬼!誰把這個給你的?', `FemaleText_loc7`='¡Eh, tacaño! ¿Quién te dio la idea?' WHERE `ID`=6303;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우미가 시킨 거죠? 항상 나한테 장난을 치더니, 이제는 당신까지 끌어들였군요!', `FemaleText_loc4`='是乌米，是吗？？她总是跟我开玩笑，现在也让你参与到玩笑之中了！', `FemaleText_loc5`='是烏米，是嗎??她總是跟我開玩笑，現在也讓你參與到玩笑之中了!', `FemaleText_loc7`='¡Fue Umi, ¿verdad?! Siempre me está gastando bromas, ¡y ahora también te la ha jugado a ti!' WHERE `ID`=6304;
