UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 이럴 수가!!', `MaleText_loc4`='这不可能！', `MaleText_loc5`='這不可能!', `MaleText_loc7`='¡¡NO PUEDE SER!!' WHERE `ID`=6371;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모든 선원들은 전투 태세를 갖춰라! 나가들이 오고 있다!', `MaleText_loc4`='所有参与作战的人都各就各位！纳迦来了！', `MaleText_loc5`='所有參與作戰的人都各就各位!納迦來了!', `MaleText_loc7`='¡Zafarrancho de combate! ¡Se acercan nagas!' WHERE `ID`=6372;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 폭발하여 독성 있는 점액질로 변합니다!', `MaleText_loc4`='%s爆裂，喷发出有毒的粘性物质！', `MaleText_loc5`='%s自爆而轉變成了有毒的黏性物質!', `MaleText_loc7`='%s explota en baba venenosa.' WHERE `ID`=6373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 누가 이 신성하고 거룩한 땅을 더럽힌단 말이냐?', `MaleText_loc4`='你敢玷污这片圣地吗？', `MaleText_loc5`='你敢玷污這片聖地嗎?', `MaleText_loc7`='¿Osas profanar este terreno sagrado?', `FemaleText_loc1`='감히 누가 이 신성하고 거룩한 땅을 더럽힌단 말이냐?', `FemaleText_loc4`='你敢玷污这片圣地吗？', `FemaleText_loc5`='你敢玷污這片聖地嗎?', `FemaleText_loc7`='¿Osas profanar este terreno sagrado?' WHERE `ID`=6374;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 칼날로 깨끗이 정화해 주마, 쓰레기 같은 것!', `MaleText_loc4`='让刀刃清洗你这个污秽吧！', `MaleText_loc5`='讓刀刃清洗你這個污穢吧!', `MaleText_loc7`='¡Que la espada te purifique, escoria!', `FemaleText_loc1`='내 칼날로 깨끗이 정화해 주마, 쓰레기 같은 것!', `FemaleText_loc4`='让刀刃清洗你这个污秽吧！', `FemaleText_loc5`='讓刀刃清洗你這個污穢吧!', `FemaleText_loc7`='¡Que la espada te purifique, escoria!' WHERE `ID`=6375;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적들이 문 앞까지 왔다! 안으로 들어가! 반드시 사수해야 해!', `MaleText_loc4`='敌人已经打到门口了！坚持住！我们必须守住！', `MaleText_loc5`='敵人已經打到門口了!堅持住!我們必須守住!', `MaleText_loc7`='¡Los enemigos han llegado a la puerta! ¡Entrad! ¡Debemos resistir!', `FemaleText_loc1`='적들이 문 앞까지 왔다! 안으로 들어가! 반드시 사수해야 해!', `FemaleText_loc4`='敌人已经打到门口了！坚持住！我们必须守住！', `FemaleText_loc5`='敵人已經打到門口了!堅持住!我們必須守住!', `FemaleText_loc7`='¡Los enemigos han llegado a la puerta! ¡Entrad! ¡Debemos resistir!' WHERE `ID`=6376;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뒤로 물러나 전선을 사수하라! 실패하면 모든 게 끝장이야!', `MaleText_loc4`='后退，坚持住！我们不能失败，否则一切都会失败的！', `MaleText_loc5`='後退，堅持住!我們不能失敗，否則一切都會失敗的!', `MaleText_loc7`='¡Retroceded y mantened la formación! ¡Si fallamos todo estará perdido!', `FemaleText_loc1`='뒤로 물러나 전선을 사수하라! 실패하면 모든 게 끝장이야!', `FemaleText_loc4`='后退，坚持住！我们不能失败，否则一切都会失败的！', `FemaleText_loc5`='後退，堅持住!我們不能失敗，否則一切都會失敗的!', `FemaleText_loc7`='¡Retroceded y mantened la formación! ¡Si fallamos todo estará perdido!' WHERE `ID`=6377;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계단으로 올라가서 방어하라!', `MaleText_loc4`='到楼梯那儿去防守！', `MaleText_loc5`='到樓梯那兒去防守!', `MaleText_loc7`='¡Poneos en las escaleras y defended!', `FemaleText_loc1`='계단으로 올라가서 방어하라!', `FemaleText_loc4`='到楼梯那儿去防守！', `FemaleText_loc5`='到樓梯那兒去防守!', `FemaleText_loc7`='¡Poneos en las escaleras y defended!' WHERE `ID`=6378;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='녀석들이 빛의 회랑 안으로 침입했다! 침략자들을 반드시 막아야 한다!', `MaleText_loc4`='他们已经闯进了光明大厅！我们必须阻止这些入侵者！', `MaleText_loc5`='他們已經闖進了光明大廳!我們必須阻止這些入侵者!', `MaleText_loc7`='¡Han irrumpido en La Sala de las Luces! ¡Hay que parar a esos intrusos!', `FemaleText_loc1`='녀석들이 빛의 회랑 안으로 침입했다! 침략자들을 반드시 막아야 한다!', `FemaleText_loc4`='他们已经闯进了光明大厅！我们必须阻止这些入侵者！', `FemaleText_loc5`='他們已經闖進了光明大廳!我們必須阻止這些入侵者!', `FemaleText_loc7`='¡Han irrumpido en La Sala de las Luces! ¡Hay que parar a esos intrusos!' WHERE `ID`=6379;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='붉은십자군은 이렇게 끝나지 않을 것이다! 우리 방어선을 뚫지는 못해!', `MaleText_loc4`='血色十字军不会就此灭亡的！你不会冲破我们的战线的！', `MaleText_loc5`='血色十字軍不會就此滅亡的!你不會衝破我們的戰線的!', `MaleText_loc7`='¡Este no será el fin de la Cruzada Escarlata! ¡No romperéis nuestras líneas!', `FemaleText_loc1`='붉은십자군은 이렇게 끝나지 않을 것이다! 우리 방어선을 뚫지는 못해!', `FemaleText_loc4`='血色十字军不会就此灭亡的！你不会冲破我们的战线的！', `FemaleText_loc5`='血色十字軍不會就此滅亡的!你不會衝破我們的戰線的!', `FemaleText_loc7`='¡Este no será el fin de la Cruzada Escarlata! ¡No romperéis nuestras líneas!' WHERE `ID`=6380;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여행자여, 반갑소. 나를 만난 걸 행운으로 여겨야 할 거요. 동부 왕국에서 나를 만난 자는 아주 드무니까 말이오.$B$B내 이름은 리베른... 여명의 설원 눈호랑이를 탈것으로 훈련시킨다오.$B$B이 눈호랑이는 가장 사납고 다루기 어려운 맹수 중의 맹수요. 신뢰와 확고한 동맹으로 인정받는 자만이 탈 수 있다오.$B$B아무에게나 팔지는 않을 뿐 더러 열심히 노력해서 나뿐만 아니라, 눈호랑이에게서도 인정받아야만 하오.', `MaleText_loc4`='旅行者，你好。很少有人以这种方式找到我。$B$B我叫雷沃，我在冬泉谷驯化这些霜刃豹，使它们成为坐骑。$B$B这些猫科动物非常凶猛，极难驯服。只有那些最值得信赖和最受人尊敬的人才可能骑上它们。$B$B我是不会随意出售这样的坐骑的，你必须用行动来证明，让我和霜刃豹都接受你。', `MaleText_loc5`='旅人，你好。很少有人以這種方式找到我。$B$B我叫雷沃，我馴化冬泉霜刃豹，使牠們成為坐騎。$B$B這些貓科動物非常兇猛，極難馴服。只有那些最值得信賴和最受人尊敬的人才可能騎上牠們。$B$B我是不會隨意出售這樣的坐騎的，你必須用行為來證明，讓我和霜刃豹都接受你。', `MaleText_loc7`='Hola $gviajero:viajera;. No son muchos los que me encuentran así.$B$BMi nombre es Rivern y entreno a los Sables de Hielo de Cuna del Inverno para convertirlos en monturas.$B$BEstos felinos son los más salvajes y difíciles de domar de todos los dientes de sable. Solo aquellos en los que tenemos más confianza, los exaltados, pueden intentar montar uno.$B$BNo venderé una montura así a todo el mundo. No, debes trabajar duro y ganarte mi aprobación y la de los propios dientes de sable.' WHERE `ID`=6381;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오색 등껍질에 대한 정보입니다.', `MaleText_loc4`='关于多彩龙鳞的信息。', `MaleText_loc5`='關於炫彩龍鱗的資訊。', `MaleText_loc7`='Información sobre el caparazón cromático.', `FemaleText_loc1`='오색 등껍질에 대한 정보입니다.', `FemaleText_loc4`='关于多彩龙鳞的信息。', `FemaleText_loc5`='關於炫彩龍鱗的資訊。', `FemaleText_loc7`='Información sobre el caparazón cromático.' WHERE `ID`=6382;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반짝이는 오색 비늘에 대한 정보입니다.', `MaleText_loc4`='关于魔光多彩鳞片的信息。', `MaleText_loc5`='關於閃亮的炫彩龍鱗的資訊。', `MaleText_loc7`='Información sobre escamas cromáticas luminosas.', `FemaleText_loc1`='반짝이는 오색 비늘에 대한 정보입니다.', `FemaleText_loc4`='关于魔光多彩鳞片的信息。', `FemaleText_loc5`='關於閃亮的炫彩龍鱗的資訊。', `FemaleText_loc7`='Información sobre escamas cromáticas luminosas.' WHERE `ID`=6383;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영웅의 피에 대한 정보입니다.', `MaleText_loc4`='关于英雄之血的信息。', `MaleText_loc5`='關於英雄之血的資訊。', `MaleText_loc7`='Información sobre la sangre de héroes.', `FemaleText_loc1`='영웅의 피에 대한 정보입니다.', `FemaleText_loc4`='关于英雄之血的信息。', `FemaleText_loc5`='關於英雄之血的資訊。', `FemaleText_loc7`='Información sobre la sangre de héroes.' WHERE `ID`=6384;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='닳아해진 누더기골렘 조각에 대한 정보입니다.', `MaleText_loc4`='关于破碎憎恶织线的信o。', `MaleText_loc5`='關於磨損的憎惡體縫合線的資訊。', `MaleText_loc7`='Información sobre costuras desgarradas de abominación.', `FemaleText_loc1`='닳아해진 누더기골렘 조각에 대한 정보입니다.', `FemaleText_loc4`='关于破碎憎恶织线的信息。', `FemaleText_loc5`='關於磨損的憎惡體縫合線的資訊。', `FemaleText_loc7`='Información sobre costuras desgarradas de abominación.' WHERE `ID`=6385;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠의 허물에 대한 정보입니다.', `MaleText_loc4`='关于暗影之皮的信息。', `MaleText_loc5`='關於暗影之皮的資訊。', `MaleText_loc7`='Información sobre la piel de Sombra.', `FemaleText_loc1`='어둠의 허물에 대한 정보입니다.', `FemaleText_loc4`='关于暗影之皮的信息。', `FemaleText_loc5`='關於暗影之皮的資訊。', `FemaleText_loc7`='Información sobre la piel de Sombra.' WHERE `ID`=6386;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='존재하는 것으로 추정. 상급 오색용혈족이나 오색용만이 이러한 등껍질을 보유할 수 있다.', `MaleText_loc4`='假设存在这种东西。只有体型更大的多彩飞龙才可能具有这样的外壳。', `MaleText_loc5`='假設存在這種東西。只有體型更大的炫彩飛龍才可能具有這樣的外殼。', `MaleText_loc7`='Se presume de su existencia. Solo un dragón o dragonante cromático mayor podrían poseer un caparazón así.' WHERE `ID`=6387;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새끼용이나 하급 고룡족과 같은 하급 오색용군단에게서 흔히 찾을 수 있다.', `MaleText_loc4`='通常在较小的多彩飞龙身上找到：幼龙，龙崽，较小的龙人。', `MaleText_loc5`='通常在較小的炫彩龍族身上找到:幼龍、小龍以及較小的龍人。', `MaleText_loc7`='Se encuentra con frecuencia en los Vuelos Cromáticos menores: crías, estirpes, vermintes menores.' WHERE `ID`=6388;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전설에 의하면 현재 역병지대라는 지역에서 극심한 충돌이 있었던 장소에는 땅에서 깨끗하고 신성한 샘물이 솟아오르기도 한다고 전해진다. 전쟁에서 스컬지에 의해 쓰러진 자들을 기리는 뜻에서 대가와 일반인 할 것 없이 모두 이러한 샘에서 나는 물을 ''영웅의 피''라고 불렀다.', `MaleText_loc4`='传说在战事极度激烈的地方，在现今被称为瘟疫之地的土地上；地表也许会涌出洁净而神圣的温泉。这些泉水被人们命名为‘英雄之血’——以纪念那些在对抗亡灵天灾的战争中牺牲的勇士。', `MaleText_loc5`='傳說在戰事極度激烈的地方，在現今被稱為瘟疫之地的土地上;地表也許會湧出潔淨而神聖的溫泉。這些泉水被人們命名為‘英雄之血’─以紀念那些在對抗天譴軍團的戰爭中犧牲的勇士。', `MaleText_loc7`='La leyenda dice que en lugares de sumo conflicto, a través de lo que hoy se conoce como las Tierras de la Peste, pueden surgir fuentes sagradas y puras. El pueblo llano y los artesanos llaman al agua que mana de esas fuentes la "Sangre de héroes", en honor de los que cayeron en la guerra contra la Plaga.' WHERE `ID`=6389;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스트라솔름의 누더기골렘들을 한데 꿰매는 데 사용되는 이 실은 탄성이 극도로 커서 거의 끊어지지 않기 때문에 장인 대가들이 많이 찾는다.', `MaleText_loc4`='工匠们都热衷于寻找缝合斯坦索姆憎恶的线：特别是有弹力的——几乎不会断裂的线。', `MaleText_loc5`='工匠們都熱衷於尋找縫合斯坦索姆憎惡的線:特別是有彈力的─幾乎不會斷裂的線。', `MaleText_loc7`='Los hilos que mantienen unidas a las abominaciones de Stratholme son muy buscados por los artesanos. Son extremadamente resistentes... prácticamente irrompibles.' WHERE `ID`=6390;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 거울은 스칼로맨스의 바로브 가가 더 이상 자신들이 소유하지 않는 영혼들을 비춰 보는 데 사용되는 아주 귀중한 유품이다.', `MaleText_loc4`='通灵学院的巴罗夫家族将它作为照耀他们不复存在的灵魂的镜子。那是一件贵重的纪念品。', `MaleText_loc5`='通靈學院的巴羅夫家族將它作為照耀他們不復存在的靈魂的鏡子。那是一件貴重的紀念品。', `MaleText_loc7`='Utilizada por la familia Barov de Scholomance como un espejo de las almas que ya no poseen. Un valioso recuerdo.' WHERE `ID`=6391;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드에는 술 한 잔 기울일 만한 곳이 많이 있습니다. 하지만 그중 딱 한 곳만이 숙박을 제공합니다. 상업 지구에 있는 황금 장미 여관으로 가 보십시오. 방 값도 괜찮은 편이고 깨끗하다고 들었습니다.', `MaleText_loc4`='在暴风城，有很多地方可供饮水休息，但是只有一处可以过夜。去贸易区的镶金玫瑰吧。我听说客房的费用相当合理，被单也很整洁。', `MaleText_loc5`='在暴風城，有很多地方可供飲水休息，但是只有一處可以過夜。去貿易區的鑲金玫瑰吧。我聽說客房的費用相當合理，被單也很整潔。', `MaleText_loc7`='Hay muchos establecimientos para tomar un trago en Ventormenta, pero solo en uno puedes pasar la noche. Dirígete a La Rosa Áurea del Distrito de Mercaderes. He oído que el precio de una habitación es bastante razonable, y las sábanas están limpias.', `FemaleText_loc1`='스톰윈드에는 술 한 잔 기울일 만한 곳이 많이 있습니다. 하지만 그중 딱 한 곳만이 숙박을 제공합니다. 상업 지구에 있는 황금 장미 여관으로 가 보십시오. 방 값도 괜찮은 편이고 깨끗하다고 들었습니다.', `FemaleText_loc4`='在暴风城，有很多地方可供饮水休息，但是只有一处可以过夜。去贸易区的镶金玫瑰吧。我听说客房的费用相当合理，被单也很整洁。', `FemaleText_loc5`='在暴風城，有很多地方可供飲水休息，但是只有一處可以過夜。去貿易區的鑲金玫瑰吧。我聽說客房的費用相當合理，被單也很整潔。', `FemaleText_loc7`='Hay muchos establecimientos para tomar un trago en Ventormenta, pero solo en uno puedes pasar la noche. Dirígete a La Rosa Áurea del Distrito de Mercaderes. He oído que el precio de una habitación es bastante razonable, y las sábanas están limpias.' WHERE `ID`=6392;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 황금 장미 여관 말씀이십니까? 푹신한 침대에 따뜻한 목욕물... 그 여관은 생각만 해도... 흐아암... 그곳으로 가신다니 여유가 있으신 분이로군요. 상업 지구 서쪽 부근에 있습니다. 푹신푹신한 베개에 포근한 이불... 아이고, 졸려라.', `MaleText_loc4`='啊，镶金玫瑰？那柔软的床铺和温水沐浴……想想这一切吧。::打哈欠::如果你要前往那儿的话，你可真幸运。旅馆就在贸易区的西边……柔软的枕头、温暖的毛毯。::打哈欠::', `MaleText_loc5`='啊，鑲金玫瑰...那柔軟的床鋪和溫水沐浴...想想這一切吧。::打哈欠::如果你要前往那兒的話，你可真幸運。旅館就在貿易區的西邊...柔軟的枕頭、溫暖的毛毯。::打哈欠::', `MaleText_loc7`='Ah, La Rosa Áurea... con sus cómodas camas y los baños calientes... con solo pensar en esa posada me entra... aauuhhh... Eres $gafortunado:afortunada; si vas hacia allá... la encontrarás en la parte oeste del Distrito de Mercaderes... suaves almohadas, cálidas mantas... aaauhhh...', `FemaleText_loc1`='아, 황금 장미 여관 말씀이십니까? 푹신한 침대에 따뜻한 목욕물... 그 여관은 생각만 해도... 흐아암... 그곳으로 가신다니 여유가 있으신 분이로군요. 상업 지구 서쪽 부근에 있습니다. 푹신푹신한 베개에 포근한 이불... 아이고, 졸려라.', `FemaleText_loc4`='啊，镶金玫瑰？那柔软的床铺和温水沐浴……想想这一切吧。::打哈欠::如果你要前往那儿的话，你可真幸运。旅馆就在贸易区的西边……柔软的枕头、温暖的毛毯。::打哈欠::', `FemaleText_loc5`='啊，鑲金玫瑰...那柔軟的床鋪和溫水沐浴...想想這一切吧。::打哈欠::如果你要前往那兒的話，你可真幸運。旅館就在貿易區的西邊...柔軟的枕頭、溫暖的毛毯。::打哈欠::', `FemaleText_loc7`='Ah, La Rosa Áurea... con sus cómodas camas y los baños calientes... con solo pensar en esa posada me entra... aauuhhh... Eres $gafortunado:afortunada; si vas hacia allá... la encontrarás en la parte oeste del Distrito de Mercaderes... suaves almohadas, cálidas mantas... aaauhhh...' WHERE `ID`=6393;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드 우체통은 상업 지구에서 바로 스톰윈드 은행과 황금 장미 여관 사이에 있어서 이용하시기 아주 편리할 것입니다.', `MaleText_loc4`='在暴风城银行和贸易区的镶金玫瑰旅店之间设有邮箱，非常便利。', `MaleText_loc5`='在暴風城銀行和貿易區的鑲金玫瑰旅店之間設有郵箱，非常便利。', `MaleText_loc7`='Hay un buzón estratégicamente situado entre el banco de Ventormenta y la posada La Rosa Áurea en el Distrito de Mercaderes.', `FemaleText_loc1`='스톰윈드 우체통은 상업 지구에서 바로 스톰윈드 은행과 황금 장미 여관 사이에 있어서 이용하시기 아주 편리할 것입니다.', `FemaleText_loc4`='在暴风城银行和贸易区的镶金玫瑰旅店之间设有邮箱，非常便利。', `FemaleText_loc5`='在暴風城銀行和貿易區的鑲金玫瑰旅店之間設有郵箱，非常便利。', `FemaleText_loc7`='Hay un buzón estratégicamente situado entre el banco de Ventormenta y la posada La Rosa Áurea en el Distrito de Mercaderes.' WHERE `ID`=6394;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 그렇게 하는 건지 도대체 모르겠습니다. 우체통 안에 틀림없이 무슨 마법의 문 같은 게 들어 있을 거예요. 스톰윈드 은행 옆에 있는 우체통 앞에 하루종일 인파가 모여들어 그 작은 통에서 검이며 방패, 온갖 방어구를 꺼내더란 말입니다!', `MaleText_loc4`='我不知道他们是怎么做到的……这些邮箱一定是传送门之类的东西。为什么人们整天都聚集在银行旁边的邮箱那儿，从小小的邮箱中不断地取出剑、盾牌和各种护甲！', `MaleText_loc5`='我不知道他們是怎麼做到的...這些郵箱一定是傳送門之類的東西。為什麼人們整天都聚集在銀行旁邊的郵箱那兒，從小小的郵箱中不斷地取出劍、盾牌和各種護甲!', `MaleText_loc7`='No sé cómo lo hacen... esos buzones deben ser portales mágicos o algo así. ¡No paro de ver a gente amontonada alrededor del buzón que está junto al banco sacando espadas, escudos y armaduras de esa diminuta cosa!', `FemaleText_loc1`='어떻게 그렇게 하는 건지 도대체 모르겠습니다. 우체통 안에 틀림없이 무슨 마법의 문 같은 게 들어 있을 거예요. 스톰윈드 은행 옆에 있는 우체통 앞에 하루종일 인파가 모여들어 그 작은 통에서 검이며 방패, 온갖 방어구를 꺼내더란 말입니다!', `FemaleText_loc4`='我不知道他们是怎么做到的……这些邮箱一定是传送门之类的东西。为什么人们整天都聚集在银行旁边的邮箱那儿，从小小的邮箱中不断地取出剑、盾牌和各种护甲！', `FemaleText_loc5`='我不知道他們是怎麼做到的...這些郵箱一定是傳送門之類的東西。為什麼人們整天都聚集在銀行旁邊的郵箱那兒，從小小的郵箱中不斷地取出劍、盾牌和各種護甲!', `FemaleText_loc7`='No sé cómo lo hacen... esos buzones deben ser portales mágicos o algo así. ¡No paro de ver a gente amontonada alrededor del buzón que está junto al banco sacando espadas, escudos y armaduras de esa diminuta cosa!' WHERE `ID`=6395;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여관', `MaleText_loc4`='旅店', `MaleText_loc5`='旅店', `MaleText_loc7`='Posada', `FemaleText_loc1`='여관', `FemaleText_loc4`='旅店', `FemaleText_loc5`='旅店', `FemaleText_loc7`='Posada' WHERE `ID`=6396;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우체통', `MaleText_loc4`='邮箱', `MaleText_loc5`='郵箱', `MaleText_loc7`='Buzón', `FemaleText_loc1`='우체통', `FemaleText_loc4`='邮箱', `FemaleText_loc5`='郵箱', `FemaleText_loc7`='Buzón' WHERE `ID`=6397;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러니까 네놈이 리치 왕의 위대한 창조물들과 장난 칠 정도의 실력이 된다고 생각하나 보지? 람스타인. 가서 침입자들에게 따뜻한 환영 인사를 해 주고 오너라!', `MaleText_loc4`='你想戏耍一下巫妖王创造的生物吗？拉姆斯登，好好教训这些入侵者。', `MaleText_loc5`='你想戲耍一下巫妖王創造的生物嗎?拉姆斯登，好好教訓這些入侵者。', `MaleText_loc7`='¿Así que crees que es adecuado juguetear con las creaciones del Rey Exánime? Ramstein, asegúrate de dar a los intrusos la bienvenida que se merecen.' WHERE `ID`=6398;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거래를 하고 싶습니다.', `MaleText_loc4`='我想从你这里买点东西。', `MaleText_loc5`='我想從你這裡買點東西。', `MaleText_loc7`='Me gustaría comprarte algo.', `FemaleText_loc1`='거래를 하고 싶습니다.', `FemaleText_loc4`='我想从你这里买点东西。', `FemaleText_loc5`='我想從你這裡買點東西。', `FemaleText_loc7`='Me gustaría comprarte algo.' WHERE `ID`=6399;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요! 저는 남서쪽에 있는 켈테릴의 폐허를 조사하고 돌아왔답니다. 지금은 이곳 올빼미날개 숲의 산마루 위에 있는 올빼미야수들을 조사하는데 집중하고 있지요.$B$B루테란 마을에 있는 에렐라스 앰버스카이와 얘기해 본 적 있나요? 그가 절 이곳으로 와달라고 요청했었답니다. 아마도 그가 당신에게 임무를 줄 거예요.', `FemaleText_loc4`='你好！我刚刚探索凯斯利尔废墟回来，就在西南方。现在我决定调查在这个山脉之上的枭兽，在枭翼树丛内。$B$B你与鲁瑟兰村的艾瑞拉斯·琥珀谈过话了吗？他要求我来这里，或许他还有任务给你。', `FemaleText_loc5`='你好!我剛剛探索凱斯利爾廢墟回來，就在西南方。現在我決定調查在這個山脈之上的梟獸，在梟翼樹叢內。$B$B你與魯瑟蘭村的艾瑞拉斯·琥珀談過話了嗎?他要求我來這裡，或許他還有任務給你。', `FemaleText_loc7`='¡Hola! Acabo de volver de explorar las Ruinas de Kel''Theril, al Suroeste. Ahora pretendo investigar al lechúcico salvaje que se encuentra sobre esa colina, en el Matorral del Ala del Búho.$B$B¿Has hablado con Eralas Cieloámbar de Aldea Rut''theran? Él me pidió venir aquí y quizás tenga también una tarea para ti.' WHERE `ID`=6400;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 직접 나설 때가 되었군. 오너라. 이리 와서 스컬지의 강한 힘을 맛보아라!', `MaleText_loc4`='是我亲自动手的时候了。来吧。进入我的领域，向强大的亡灵天灾挑战吧！', `MaleText_loc5`='是我親自動手的時候了。來吧。進入我的領域，向強大的天譴軍團挑戰吧!', `MaleText_loc7`='Ya es hora de tomar el asunto en mis propias manos. Ven. ¡Entra en mis dominios y desafía el poder de la Plaga!' WHERE `ID`=6401;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보수는 쥐꼬리만큼 받으면서 이런 지저분한 일을 해야 하다니!', `MaleText_loc4`='做这种事情才得到这么点报酬，亏大了！', `MaleText_loc5`='做這種事情才得到這麼點報酬，虧大了!', `MaleText_loc7`='¡No se me paga lo suficiente por este excremento de vaca!' WHERE `ID`=6402;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 부담스러운 세금은 도저히 용납 못 하겠습니다! 동부 왕국 연금으로 안정된 노후 대비라고요? 흥!', `MaleText_loc4`='我可负担不起这么高的税金！', `MaleText_loc5`='我可負擔不起這麼高的稅金!', `MaleText_loc7`='¡No puedo pagar tantos impuestos! ¿Seguridad Social? ¿SS? ¡No le queda mal el nombre!' WHERE `ID`=6403;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이보시오, 요새 밥은 제대로 먹고 다니시나요?', `MaleText_loc4`='嗨！你喜欢沙司吗？沙司很美味，不是吗？', `MaleText_loc5`='嗨!你喜歡沙司嗎?沙司很美味，不是嗎?', `MaleText_loc7`='Umm... ¿flamable, significa lo mismo que inflamable?' WHERE `ID`=6404;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 글쎄... 타우렌이 그랬더군요. ''아무리 봐도 타우렌 여자가 젤 예뻐!''', `MaleText_loc4`='然后牛头人说“13先生！”', `MaleText_loc5`='然後牛頭人說「13先生!」', `MaleText_loc7`='Y entonces va el tauren y dice: "¡39 CENTÍMETROS!".' WHERE `ID`=6405;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 저 밑에 있는 세계에서 왔습니다... 고통과 질병에 남녀차별이 없는 평등한 곳이죠.', `MaleText_loc4`='我来自底层社会……我们那儿的人民倍受折磨。', `MaleText_loc5`='我來自底層社會...我們那兒的人民倍受折磨。', `MaleText_loc7`='Mi novia es una no-muerta, es un muerto viviente que volvió desde Entrañas para estar conmigo.' WHERE `ID`=6406;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 인도자라고? 아, 파멸의 인도자 말인가요? 난 그런 거 모릅니다. 뭡니까? 성가시게 하지 마세요!', `MaleText_loc4`='什么？哦，灰烬使者？没有听说过……什么？别烦我！', `MaleText_loc5`='什麼?哦，灰燼使者?沒有聽說過...什麼?別煩我!', `MaleText_loc7`='¿¿Quemaescoria??? ¡Ah! ¿Crematoria? Debo de estar quedándome sordo... No, nunca he oído hablar de ello... ¡Deja de molestarme!' WHERE `ID`=6407;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 그 노란 알약을 먹었어야 하는 건데.', `MaleText_loc4`='我该服下那透明小药丸的。', `MaleText_loc5`='我該服下那透明小藥丸的。', `MaleText_loc7`='Debería haber tomado la pastilla translúcida.' WHERE `ID`=6408;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐 앉아 보시오. 재미있는 이야기를... *딸꾹* 해드릴... *딸꾹* 웩... *딸꾹* 제길!', `MaleText_loc4`='别动，你会听到嗝……嗝……的打嗝声，真该死！', `MaleText_loc5`='別動，你會聽到嗝...嗝...的打嗝聲，真該死!', `MaleText_loc7`='Tú recuéstate y oirás u... ¡hip! Uuun... ¡hip! ¡Maldita sea! ¡Hip! Uuun... ¡hip! ¡Maldita sea!' WHERE `ID`=6409;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='순찰대원 바커스를 본 적 있나요? 얼마나 용맹스러운지...$B$B그가 모든 어둠의 순찰대원 중에서 제일 힘이 센 것 같아요. 내가 주변에 있다는 걸 그가 알기라도 할지 모르겠네요...', `FemaleText_loc4`='你见过守夜人巴库斯吗？很勇敢……$B$B我想他是所有守夜人中最凶猛的一个。我怀疑他是否看到我就在周围……', `FemaleText_loc5`='你見過守夜人巴庫斯嗎?很勇敢...$b$b我想他是所有守夜人中最兇猛的一個。我懷疑他是否看到我就在周圍...', `FemaleText_loc7`='¿Has visto al vigía Backus? Tan valiente... $B$BCreo que es el más duro de La Guardia Nocturna. Creo que ni siquiera se da cuenta que estoy por ahí...' WHERE `ID`=6410;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='온도가... 아직 충분히 뜨겁지 않습니다!', `MaleText_loc4`='温度的数值是……反正还不够高！', `MaleText_loc5`='溫度的數值是...反正還不夠高!', `MaleText_loc7`='La temperatura no es... ¡lo suficientemente alta!' WHERE `ID`=6411;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='휴... 크래클씨 113도입니다. 좀 더 잘 찾아볼 수 없나요?', `MaleText_loc4`='*叹息* ...113克氏度。你在观光吗？', `MaleText_loc5`='*歎息* ...113克拉蘭克度。你在觀光嗎?', `MaleText_loc7`='*suspiro*... 113 grados Kraklenheit. ¿Es todo lo que sabes hacer?' WHERE `ID`=6412;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='점점 더 따뜻해지고 있군요... 크래클씨 7039도입니다!', `MaleText_loc4`='越来越暖和了……7039克氏度！', `MaleText_loc5`='越來越暖和了...7039克拉蘭克度!', `MaleText_loc7`='Cada vez estás más caliente... ¡7039 grados Kraklenheit!' WHERE `ID`=6413;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크래클씨 8536도입니다... 자꾸 이러니까 짜증나죠?', `MaleText_loc4`='读数是8536克氏度……你已经开始厌烦我了吗？', `MaleText_loc5`='讀數是8536克拉蘭克度...你已經開始厭煩我了嗎?', `MaleText_loc7`='La lectura es de 8536 grados Kraklenheit... ¿ya te canso?' WHERE `ID`=6414;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 감히 우리 주인님을 귀찮게 하는 거냐?', `MaleText_loc4`='谁敢打扰我们的主人？', `MaleText_loc5`='誰敢打擾我們的主人?', `MaleText_loc7`='¿Quién osa molestar a nuestro maestro?' WHERE `ID`=6415;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='만세! 내 인형이다!', `FemaleText_loc4`='万岁！我的洋娃娃！', `FemaleText_loc5`='萬歲!我的洋娃娃!', `FemaleText_loc7`='¡Viva! ¡Mi muñeca!' WHERE `ID`=6416;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네가 나쁜 사람들 다 쫓아내 줄 거지? 그치?', `FemaleText_loc4`='你会赶走坏人的，是吗？', `FemaleText_loc5`='你會趕走壞人的，是嗎?', `FemaleText_loc7`='Mantendrás alejada a la mala gente, ¿de acuerdo?' WHERE `ID`=6417;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무슨 일인지 모두 다 알아보도록 하죠. 그러려면 마법을 좀 써야겠군요...', `FemaleText_loc4`='我们来查明历史的详情吧。这需要使用一些魔法……', `FemaleText_loc5`='我們來查明故事的詳情。這需要使用些魔法...', `FemaleText_loc7`='Averigüemos toda la historia. Será necesaria algo de magia...' WHERE `ID`=6418;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자, 다 됐군요. 책이 확장되었어요...', `FemaleText_loc4`='就这样，完成了。这本书已经被增强了……', `FemaleText_loc5`='就這樣，完成了。這本書已經被增強了...', `FemaleText_loc7`='Allí, ya está listo. El libro ha mejorado...' WHERE `ID`=6419;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이걸 찾는 거냐???? 절대로 못 가질 걸!', `MaleText_loc4`='想找这些？？？？你永远都不可能得到它们的！', `MaleText_loc5`='想找這些????你永遠都不可能得到它們的!', `MaleText_loc7`='¿¿¿¿Buscabas algo???? ¡Nunca serán tuyos!' WHERE `ID`=6420;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성채가 무너진다! 증거를 태워 버려라!', `MaleText_loc4`='碉堡正在倒塌！证物正在被烧毁！', `MaleText_loc5`='碉堡正在倒塌!把證物燒掉!', `MaleText_loc7`='¡El bastión se viene abajo! ¡Quema las pruebas!' WHERE `ID`=6421;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 가죽으로 내 시린 무릎을 덮어야겠다! 담배? 내 눈에 흙이 들어가기 전까지는 절대... 으... 우워어어어!!!', `MaleText_loc4`='我要把你的皮当作便服来穿！长靴呢？你得将它们从那儿撬下来！！！！', `MaleText_loc5`='我要把你的皮當作便服來穿!長靴呢?你得將它們從那兒撬下來!!!!', `MaleText_loc7`='¡Me voy a hacer una chaqueta con tu pellejo! ¿Los cigarrillos? Tendrás que pasar por encima de mi cadáver... eh... ¡¡¡¡RAWR!!!!' WHERE `ID`=6422;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하나도 남김없이 처리해!', `MaleText_loc4`='别拉下东西！', `MaleText_loc5`='別拉下東西!', `MaleText_loc7`='¡No te olvides de nada!' WHERE `ID`=6423;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성채가 무너지기 전에 문서를 모조리 없애 버려!', `MaleText_loc4`='在堡垒倒塌之前毁掉所有文件！', `MaleText_loc5`='在堡壘倒塌之前毀掉所有檔案!', `MaleText_loc7`='¡Destruye los documentos antes de que se derrumbe el bastión!' WHERE `ID`=6424;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='람스타인, 고기 먹고 싶다!', `MaleText_loc4`='拉姆斯登想吃肉了！', `MaleText_loc5`='拉姆斯登想吃肉了!', `MaleText_loc7`='¡Ramstein tiene hambre de carne!' WHERE `ID`=6425;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='환영하네! 향기 가득한 이곳을 찾아왔으니, 내 따뜻하게 맞이해주지!', `MaleText_loc4`='欢迎来到风味王国！', `MaleText_loc5`='歡迎來到風味王國!', `MaleText_loc7`='¡$gBienvenido:Bienvenida; al país de los sabores!' WHERE `ID`=6426;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙습니다! 절 해방시켜 주셨어요.', `MaleText_loc4`='谢谢你！你让我自由了！', `MaleText_loc5`='謝謝你!你讓我自由了!', `MaleText_loc7`='¡Gracias! ¡Me has liberado!', `FemaleText_loc1`='고맙습니다! 절 해방시켜 주셨어요.', `FemaleText_loc4`='谢谢你！你让我自由了！', `FemaleText_loc5`='謝謝你!你讓我自由了!', `FemaleText_loc7`='¡Gracias! ¡Me has liberado!' WHERE `ID`=6427;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 고맙습니다! 이 악몽에 너무 오랫동안 갇혀 있었어요...', `MaleText_loc4`='哦，谢谢你！我已经深陷恶梦多时了……', `MaleText_loc5`='哦，謝謝你!我已經深陷夢魘多時了...', `MaleText_loc7`='¡Oh, muchas gracias! He estado atrapado tanto tiempo en esta pesadilla...', `FemaleText_loc1`='아, 고맙습니다! 이 악몽에 너무 오랫동안 갇혀 있었어요...', `FemaleText_loc4`='哦，谢谢你！我已经深陷恶梦多时了……', `FemaleText_loc5`='哦，謝謝你!我已經深陷夢魘多時了...', `FemaleText_loc7`='¡Oh, muchas gracias! He estado atrapada tanto tiempo en esta pesadilla...' WHERE `ID`=6428;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 제 영혼이 해방되었군요!', `MaleText_loc4`='我的灵魂终于自由了。', `MaleText_loc5`='我的靈魂終於自由了。', `MaleText_loc7`='¡Al fin, mi alma es libre!', `FemaleText_loc1`='드디어 제 영혼이 해방되었군요!', `FemaleText_loc4`='我的灵魂终于自由了。', `FemaleText_loc5`='我的靈魂終於自由了。', `FemaleText_loc7`='¡Al fin, mi alma es libre!' WHERE `ID`=6429;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다! 다로우골 전투 이후, 이 끔찍한 운명의 속박을 피할 수 없었지만 당신이 절 해방시켜 주셨군요!', `MaleText_loc4`='谢谢你！我注定会在达隆郡之战中身亡，但是你让我获得了自由！', `MaleText_loc5`='謝謝你!我註定會在達隆郡之戰中身亡，但是你讓我獲得了自由!', `MaleText_loc7`='¡Gracias! La batalla por Villa Darrow fue mi perdición, ¡pero tú me has hecho libre!', `FemaleText_loc1`='감사합니다! 다로우골 전투 이후, 이 끔찍한 운명의 속박을 피할 수 없었지만 당신이 절 해방시켜 주셨군요!', `FemaleText_loc4`='谢谢你！我注定会在达隆郡之战中身亡，但是你让我获得了自由！', `FemaleText_loc5`='謝謝你!我註定會在達隆郡之戰中身亡，但是你讓我獲得了自由!', `FemaleText_loc7`='¡Gracias! La batalla por Villa Darrow fue mi perdición, ¡pero tú me has hecho libre!' WHERE `ID`=6430;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아! 다로우골에서 생존자를 보게 되시거든 제가 풀려났다고 전해 주세요!', `MaleText_loc4`='啊！如果你见到一个达隆郡的幸存者，请告诉他们我自由了！', `MaleText_loc5`='啊!如果你見到一個達隆郡的倖存者，請告訴他們我自由了!', `MaleText_loc7`='¡Ah! Por favor, si ves a algún superviviente de Villa Darrow, ¡diles que soy libre!', `FemaleText_loc1`='아! 다로우골에서 생존자를 보게 되시거든 제가 풀려났다고 전해 주세요!', `FemaleText_loc4`='啊！如果你见到一个达隆郡的幸存者，请告诉他们我自由了！', `FemaleText_loc5`='啊!如果你見到一個達隆郡的倖存者，請告訴他們我自由了!', `FemaleText_loc7`='¡Ah! Por favor, si ves a algún superviviente de Villa Darrow, ¡diles que soy libre!' WHERE `ID`=6431;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='에메랄드 의회에서는 상처받은 악령숲을 치유하기 위해 노력하고 있어요. 비록 이 땅을 타락시킨 것의 이름을 따서 악령숲이긴 하지만, 언젠가 이 땅에서 그 타락을 완전히 뿌리 뽑을 수 있는 날이 오기만을 바라요.', `FemaleText_loc4`='翡翠议会试图治愈费伍德森林受伤的大地。尽管这片大地是以腐蚀它的东西命名，我们还是希望有一天我们能从这片土地中将腐败清除。', `FemaleText_loc5`='翡翠議會試圖治癒費伍德森林受傷的大地。儘管這片大地是以腐蝕它的東西命名，我們還是希望有一天我們能從這片土地中將腐敗清除。', `FemaleText_loc7`='El Círculo Esmeralda procura sanar la herida tierra de Frondavil. Aunque la tierra recibe el nombre del mal que la ha corrompido, esperamos poder erradicar algún día la corrupción de esta tierra.' WHERE `ID`=6432;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전 준비됐어요, $n. 제 장비를 찾아 여기서 빠져나가죠. 어디 있는지 알 것 같아요.', `FemaleText_loc4`='我准备好了，$n。找到我的装备离开这里。我想我知道装备在哪里。', `FemaleText_loc5`='我準備好了，$n。找到我的裝備離開這裡。我想我知道裝備在哪裡。', `FemaleText_loc7`='Estoy lista, $n. Vamos a buscar mi equipo y a salir de aquí. Creo que sé dónde está.' WHERE `ID`=6433;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다 틀렸어요, $n!!', `FemaleText_loc4`='我们失败了，$n！！', `FemaleText_loc5`='我們失敗了，$n!!', `FemaleText_loc7`='¡Hemos fracasado, $n!' WHERE `ID`=6434;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$C|1이여;여;, 안녕하세요. 저는 제시르 문보우라고 해요. 두 명의 친구들을 찾기 위해 다르나서스에서 왔지요. 그들은 악령숲에 숨어 있다는 어둠의 의회에 대한 단서를 찾으러 떠났었죠.$B$B오크족의 고통에 많은 부분 책임이 있는 사악한 생물들이 다시 예전의 힘을 되찾으려는 것 같아요.$B$B제 두 친구들은 무슨 일이 일어나고 있는지 알아보려고 제데나르를 조사하러 갔답니다.$B$B제가 여기 도착하면 친구들이 와 있을 줄 알았는데 벌써 예정된 날짜를 며칠이나 넘겼네요.', `FemaleText_loc4`='你好，$c。我是杰希尔·月弓。我从达纳苏斯来寻找两个朋友，他们是来寻找费伍德森林暗影议会的踪迹的。$B$B看起来那些宣称对兽人种族的苦难负大部分责任的卑鄙的生物正试图重获一些能量。$B$B我的两个朋友进入加德纳尔搜寻证据来证明有事情发生。$B$B我希望我来时他们在这里，但是他们已经晚了数天了。', `FemaleText_loc5`='你好，$c。我是傑希爾·月弓。我從達納蘇斯來尋找兩個朋友，他們是來尋找費伍德森林暗影議會的蹤跡的。$B$B看起來那些宣稱對獸人種族的苦難負大部分責任的卑鄙的生物正試圖重獲一些能量。$B$B我的兩個朋友進入加德納爾搜尋證據來證明有事情發生。$B$B我希望我來時他們在這裡，但是他們已經晚了數天了。', `FemaleText_loc7`='Hola, $c. Soy Jessir Arcolunar. He venido desde Darnassus buscando a dos amigos que vinieron aquí en busca de señales del Consejo de la Sombra en Frondavil.$B$BParece que esas infames criaturas que se reclaman culpables de gran parte del sufrimiento de la raza orca pretenden recobrar parte de su poder.$B$BMis dos amigos fueron a Jaedenar para mostrar de un modo u otro lo que estaba ocurriendo.$B$BEsperaba que estuvieran aquí a mi llegada, pero ya llevan varios días de retraso.' WHERE `ID`=6435;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스컬지가 성채 안으로 침입했다! 힘을 내라! 절대로 져서는 안 돼!', `MaleText_loc4`='亡灵天灾打进堡垒了！坚守阵地！我们绝对不能失败！', `MaleText_loc5`='天譴軍團被迫退守堡壘!加倍努力!我們不能失敗!', `MaleText_loc7`='¡La Plaga ha irrumpido en el bastión! ¡Redoblen sus esfuerzos! ¡No podemos fallar!', `FemaleText_loc1`='스컬지가 성채 안으로 침입했다! 힘을 내라! 절대로 져서는 안 돼!', `FemaleText_loc4`='亡灵天灾打进堡垒了！坚守阵地！我们绝对不能失败！', `FemaleText_loc5`='天譴軍團被迫退守堡壘!加倍努力!我們不能失敗!', `FemaleText_loc7`='¡La Plaga ha irrumpido en el bastión! ¡Redoblen sus esfuerzos! ¡No podemos fallar!' WHERE `ID`=6436;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해골 녀석들이 빛의 회랑까지 들어왔다! 녀석들을 쳐부숴라!', `MaleText_loc4`='骷髅已经进入了光明大厅！消灭他们！', `MaleText_loc5`='骷髏已經進入了光明大廳!消滅他們!', `MaleText_loc7`='¡Los esqueletos han pasado la Sala de las Luces! ¡Destrúyanlos!', `FemaleText_loc1`='해골 녀석들이 빛의 회랑까지 들어왔다! 녀석들을 쳐부숴라!', `FemaleText_loc4`='骷髅已经进入了光明大厅！消灭他们！', `FemaleText_loc5`='骷髏已經進入了光明大廳!消滅他們!', `FemaleText_loc7`='¡Los esqueletos han pasado la Sala de las Luces! ¡Destrúyanlos!' WHERE `ID`=6437;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 방어선이 무너지고 있다! 성스러운 빛의 힘으로 반드시 승리해야 한다!', `MaleText_loc4`='我们的防线崩溃了！以圣光的名义，我们一定要战斗到底！', `MaleText_loc5`='我們的防禦失敗了!以聖光之名我們一定會獲勝的!', `MaleText_loc7`='¡Nuestras defensas están fallando! ¡Por la Luz, debemos vencer!', `FemaleText_loc1`='우리 방어선이 무너지고 있다! 성스러운 빛의 힘으로 반드시 승리해야 한다!', `FemaleText_loc4`='我们的防线崩溃了！以圣光的名义，我们一定要战斗到底！', `FemaleText_loc5`='我們的防禦失敗了!以聖光之名我們一定會獲勝的!', `FemaleText_loc7`='¡Nuestras defensas están fallando! ¡Por la Luz, debemos vencer!' WHERE `ID`=6438;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스컬지가 모든 구역에 침투했다! 성스러운 빛이 이 역겨운 것들을 물리쳐 주시기를! 우리는 끝까지 싸울 것이다!', `MaleText_loc4`='亡灵天灾从四面八方涌入了堡垒！愿圣光击败这些邪恶的生物！我们要奋战到底！', `MaleText_loc5`='天譴軍團將我們全部的防禦都擊潰了!願聖光擊敗這些邪惡的生物!我們要抗戰到底!', `MaleText_loc7`='¡La Plaga ha irrumpido en todas las alas! ¡Que la luz derrote a esas infectas criaturas! ¡Lucharemos hasta el final!', `FemaleText_loc1`='스컬지가 모든 구역에 침투했다! 성스러운 빛이 이 역겨운 것들을 물리쳐 주시기를! 우리는 끝까지 싸울 것이다!', `FemaleText_loc4`='亡灵天灾从四面八方涌入了堡垒！愿圣光击败这些邪恶的生物！我们要奋战到底！', `FemaleText_loc5`='天譴軍團將我們全部的防禦都擊潰了!願聖光擊敗這些邪惡的生物!我們要抗戰到底!', `FemaleText_loc7`='¡La Plaga ha irrumpido en todas las alas! ¡Que la luz derrote a esas infectas criaturas! ¡Lucharemos hasta el final!' WHERE `ID`=6439;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저그 저그, 용감한 $c|1이여;여;! 내겐 호드에서 제일 알아주는 늑대들이 있지. 자네도 꼭 한번은 봐야 해... 어떤 곳에서도 이보다 더 생존 본능이 뛰어나고 지구력이 강한 늑대는 찾아볼 수 없을 걸세! 직접 한번 시승해 보는 건 어때?', `MaleText_loc4`='你好，勇敢的$c！我有世界上最训练有素的狼供你挑选。你到哪里都不会发现能与狼拥有同样的耐力和生存本能的动物！你亲自来看看它们吧。', `MaleText_loc5`='嘖嘖，勇敢的$c!我有最訓練有素的狼來讓你挑選。你到哪裡都不會發現另一種動物有與狼同樣的耐力和生存本能!請你親自來查看一下他們吧。', `MaleText_loc7`='¡Zug zug, valiente $c! Crío las mejores monturas de lobo, puedes examinarlas concienzudamente. ¡No encontrarás en ningún sitio a otro animal con el nivel de resistencia y con los instintos de supervivencia del lobo! Por favor, examínalos tú $gmismo:misma;.', `FemaleText_loc1`='저그 저그, 용감한 $c|1이여;여;! 내겐 호드에서 제일 알아주는 늑대들이 있지. 자네도 꼭 한번은 봐야 해... 어떤 곳에서도 이보다 더 생존 본능이 뛰어나고 지구력이 강한 늑대는 찾아볼 수 없을 걸세! 직접 한번 시승해 보는 건 어때?', `FemaleText_loc4`='你好，勇敢的$c！我有世界上最训练有素的狼供你挑选。你到哪里都不会发现能与狼拥有同样的耐力和生存本能的动物！你亲自来看看它们吧。', `FemaleText_loc5`='嘖嘖，勇敢的$c!我有最訓練有素的狼來讓你挑選。你到哪裡都不會發現另一種動物有與狼同樣的耐力和生存本能!請你親自來查看一下他們吧。', `FemaleText_loc7`='¡Zug zug, valiente $c! Crío las mejores monturas de lobo, puedes examinarlas concienzudamente. ¡No encontrarás en ningún sitio a otro animal con el nivel de resistencia y con los instintos de supervivencia del lobo! Por favor, examínalos tú $gmismo:misma;.' WHERE `ID`=6440;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 수년 동안 이룩한 것을 네놈들이 하루아침에 무너뜨리다니! 오늘 그 대가로 모두 내 손에 죽게 될 것이다!', `MaleText_loc4`='你们破坏了我数年的心血！我要把你们全都杀了！', `MaleText_loc5`='你弄壞了我耗費數年才創造出的東西!我要殺了你!', `MaleText_loc7`='¡Has deshecho en un solo día lo que me ha costado crear años! ¡Mereces que te mate con mis propias manos!' WHERE `ID`=6441;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저주를 받으리라, 평범한 생명체들이여! 내 복수의 계획, 내가 품은 증오... 되값아 주리라...', `MaleText_loc4`='你们这群该死的凡人！我所有的复仇计划，我所有的仇恨……我一定会报仇……', `MaleText_loc5`='詛咒你們凡人!我所有的復仇計畫，我所有的仇恨...有人會為我報仇的...', `MaleText_loc7`='¡Malditos seáis, mortales! Todos mis planes de venganza, todo mi odio... Seré vengado...' WHERE `ID`=6442;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='', `MaleText_loc4`='', `MaleText_loc5`='', `MaleText_loc7`='' WHERE `ID`=6443;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 오크족과 오그리마에 호의적이라고 판명된 자들에게만 탈것을 판매한다네. 가서 우리에게 자네의 의지를 입증해 보인다면 내 힘센 늑대들을 살펴볼 기회를 주도록 하지.', `MaleText_loc4`='我只跟那些被奥格瑞玛的兽人当朋友的人做生意。证明自己吧，然后再来和我谈那些强大的座狼。', `MaleText_loc5`='我只跟奧格瑪和獸人的朋友做生意。證明自己吧，我將給你看看那些強大的狼。', `MaleText_loc7`='Solo pongo mis monturas a disposición de los que son considerados por Orgrimmar y la raza orca como amistosos. Pruébate ante nosotros y te permitiré inspeccionar mis poderosos lobos.', `FemaleText_loc1`='나는 오크족과 오그리마에 호의적이라고 판명된 자들에게만 탈것을 판매한다네. 가서 우리에게 자네의 의지를 입증해 보인다면 내 힘센 늑대들을 살펴볼 기회를 주도록 하지.', `FemaleText_loc4`='我只跟那些被奥格瑞玛的兽人当朋友的人做生意。证明自己吧，然后再来和我谈那些强大的座狼。', `FemaleText_loc5`='我只跟奧格瑪和獸人的朋友做生意。證明自己吧，我將給你看看那些強大的狼。', `FemaleText_loc7`='Solo pongo mis monturas a disposición de los que son considerados por Orgrimmar y la raza orca como amistosos. Pruébate ante nosotros y te permitiré inspeccionar mis poderosos lobos.' WHERE `ID`=6444;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, 용감한 $c님. 훌륭한 탈것을 구하시는 것 같은데 그렇다면 랩터만큼 훌륭한 탈것도 없답니다! 제가 파는 것들을 한번 둘러보십시오. 전 어디서도 찾아볼 수 없는 사나운 놈들만 취급한답니다.', `MaleText_loc4`='祝你好运，勇敢的$c。我知道你在寻找一匹好战马。告诉你吧$g兄弟:姐妹;，在你所在的区域没有什么比迅猛龙更好的坐骑了！看看我的这些迅猛龙吧——他们的祖先曾经是极其凶猛的野兽。', `MaleText_loc5`='祝你好運，勇敢的$c。我知道你在尋找一匹好戰馬。告訴你吧$g兄弟:姐妹;，在你所在的區域沒有什麼比迅猛龍更好的坐騎了!看看我的這些迅猛龍吧─他們的祖先曾經是極其兇猛的野獸。', `MaleText_loc7`='Que tengas buenos días, valiente $c. Me he enterado de que buscas un buen corcel. No hay nada mejor que tener un raptor a tus órdenes, ¡deja que te enseñe colega! Mira los que tengo para ofrecerte, criados de entre los más fieros.', `FemaleText_loc1`='안녕하십니까, 용감한 $c님. 훌륭한 탈것을 구하시는 것 같은데 그렇다면 랩터만큼 훌륭한 탈것도 없답니다! 제가 파는 것들을 한번 둘러보십시오. 전 어디서도 찾아볼 수 없는 사나운 놈들만 취급한답니다.', `FemaleText_loc4`='祝你好运，勇敢的$c。我知道你在寻找一匹好战马。告诉你吧$g兄弟:姐妹;，在你所在的区域没有什么比迅猛龙更好的坐骑了！看看我的这些迅猛龙吧——他们的祖先曾经是极其凶猛的野兽。', `FemaleText_loc5`='祝你好運，勇敢的$c。我知道你在尋找一匹好戰馬。告訴你吧$g兄弟:姐妹;，在你所在的區域沒有什麼比迅猛龍更好的坐騎了!看看我的這些迅猛龍吧─他們的祖先曾經是極其兇猛的野獸。', `FemaleText_loc7`='Que tengas buenos días, valiente $c. Me he enterado de que buscas un buen corcel. No hay nada mejor que tener un raptor a tus órdenes, ¡deja que te enseñe colega! Mira los que tengo para ofrecerte, criados de entre los más fieros.' WHERE `ID`=6445;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죄송하지만 검은창 부족의 친구임이 증명되지 않은 이들에게는 랩터를 팔지 않습니다. 적어도 우리에게 우호적이라는 걸 증명해 보인다면 제 랩터를 보여 드리겠습니다.', `MaleText_loc4`='很抱歉$g兄弟:姐妹;，但是在确定买主是黑暗之矛部落的朋友之前，我不会将迅猛龙卖给他的。当你证明自己是我们的朋友之后，我才会把迅猛龙卖给你。', `MaleText_loc5`='很抱歉$g兄弟:姐妹;，但是在確定買主是暗矛部族的朋友之前，我不會將迅猛龍賣給他的。當你證明自己是我們的朋友之後，我才會把迅猛龍賣給你。', `MaleText_loc7`='Lo siento colega, pero no voy a vender mis raptores a nadie que no se haya probado como amigo de la tribu Lanza Negra. Demuestra que eres $gamistoso:amistosa; y pondré a tu disposición mis raptores.', `FemaleText_loc1`='죄송하지만 검은창 부족의 친구임이 증명되지 않은 이들에게는 랩터를 팔지 않습니다. 적어도 우리에게 우호적이라는 걸 증명해 보인다면 제 랩터를 보여 드리겠습니다.', `FemaleText_loc4`='很抱歉$g兄弟:姐妹;，但是在确定买主是黑暗之矛部落的朋友之前，我不会将迅猛龙卖给他的。当你证明自己是我们的朋友之后，我才会把迅猛龙卖给你。', `FemaleText_loc5`='很抱歉$g兄弟:姐妹;，但是在確定買主是暗矛部族的朋友之前，我不會將迅猛龍賣給他的。當你證明自己是我們的朋友之後，我才會把迅猛龍賣給你。', `FemaleText_loc7`='Lo siento colega, pero no voy a vender mis raptores a nadie que no se haya probado como amigo de la tribu Lanza Negra. Demuestra que eres $gamistoso:amistosa; y pondré a tu disposición mis raptores.' WHERE `ID`=6446;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 그리 쉽게 무너질 것이라 생각했더냐, 어리석은 것들! 나스레짐의 진정한 힘을 맛보아라!', `MaleText_loc4`='你们这些蠢货以为可以这么容易就打败我吗？看看纳斯雷兹姆的真正力量吧！', `MaleText_loc5`='你們這些笨蛋以為可以這麼容易就打敗我嗎?看看納斯雷茲姆的真正力量吧!', `MaleText_loc7`='Idiotas, ¿pensabais que podríais derrotarme tan fácilmente? ¡Enfrentaos al verdadero poder de Nathrezim!' WHERE `ID`=6447;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도둑놈들! 네놈들의 시체 냄새를 맡게 해주마!', `MaleText_loc4`='盗贼！我要毁掉你们的尸体！', `MaleText_loc5`='盜賊!我要毀掉你們的屍體!', `MaleText_loc7`='¡Ladrones! ¡Fundiré sus restos!', `FemaleText_loc1`='도둑놈들! 네놈들의 시체 냄새를 맡게 해주마!', `FemaleText_loc4`='盗贼！我要毁掉你们的尸体！', `FemaleText_loc5`='盜賊!我要毀掉你們的屍體!', `FemaleText_loc7`='¡Ladrones! ¡Fundiré sus restos!' WHERE `ID`=6448;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도면에 대한 대가는 뼈로 치러야지. 네놈의 뼈를 내놓아라!', `MaleText_loc4`='这些计划的报酬将从尸体中得来——你的尸体！', `MaleText_loc5`='這些計畫的報酬將從屍體中得來─你的屍體!', `MaleText_loc7`='El precio de esos planos es en huesos... ¡TUS HUESOS!' WHERE `ID`=6449;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고마워요, $n. 내 고통도 이제 끝이군요.', `MaleText_loc4`='谢谢你，$n。我的痛苦结束了。', `MaleText_loc5`='謝謝你，$n。我的痛苦結束了。', `MaleText_loc7`='Gracias, $n. Mi tormento ha llegado a su fin.' WHERE `ID`=6450;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자유다!!!', `MaleText_loc4`='自由了！！！', `MaleText_loc5`='自由了!!!', `MaleText_loc7`='¡¡¡LIBRE!!!' WHERE `ID`=6451;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저주가 풀렸다!', `MaleText_loc4`='诅咒结束了！', `MaleText_loc5`='詛咒結束了!', `MaleText_loc7`='¡La maldición termina!' WHERE `ID`=6452;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에간에게 신의 찬미를!', `MaleText_loc4`='赞美埃根！', `MaleText_loc5`='讚美伊根!', `MaleText_loc7`='¡Loado sea Egan!' WHERE `ID`=6453;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='켈투자드가 언젠가 우리의 복수를 느끼게 되길.', `MaleText_loc4`='总有一天我们会对克尔苏加德进行报复的。', `MaleText_loc5`='總有一天我們會對科爾蘇加德進行報復的。', `MaleText_loc7`='Que Kel''Thuzad sienta un día nuestra venganza.' WHERE `ID`=6454;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리븐데어를 반드시 물리쳐야 해요!', `MaleText_loc4`='瑞文戴尔必须死！', `MaleText_loc5`='瑞文戴爾必須死!', `MaleText_loc7`='¡Osahendido debe ser destruido!' WHERE `ID`=6455;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='맙소사! 이것 좀 보세요... 양초가 이렇게 많다니. 분명 어떤 끔찍한 의식이나 암흑의 소환 같은 걸 치르는 데 사용하는 거겠죠. 서두르는 게 좋겠어요!', `FemaleText_loc4`='啊，天哪！看看这……这些蜡烛。我敢肯定它们是被用来进行某种可怕而黑暗的仪式的。我们最好快一点！', `FemaleText_loc5`='啊，天哪!看看這...這些蠟燭。我敢肯定它們是被用來進行某種可怕而黑暗的儀式的。我們最好快一點!', `FemaleText_loc7`='¡Oh vaya! Mira esto... todas estas velas. Estoy segura de que se utilizan para algún horrible ritual u oscura invocación. ¡Es mejor que nos demos prisa!' WHERE `ID`=6456;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저기! 저쪽이에요!', `FemaleText_loc4`='那里！在那里！', `FemaleText_loc5`='那裡!在那裡!', `FemaleText_loc7`='¡Allí! ¡Por allí!' WHERE `ID`=6457;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 금으로 된 올가미만 있으면 좋겠는데...', `FemaleText_loc4`='我现在需要的是一副金套索。', `FemaleText_loc5`='我現在需要的是一副金套索。', `FemaleText_loc7`='Lo único que necesito es un lazo de oro.' WHERE `ID`=6458;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기서 빠져나가요, $n. 준비는 다 됐어요!', `FemaleText_loc4`='我们离开这里吧，$n。我准备好了！', `FemaleText_loc5`='我們離開這裡吧，$n。我準備好了!', `FemaleText_loc7`='Salgamos de aquí, $n. ¡Ya estoy lista!' WHERE `ID`=6459;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='죽어라, 지옥의 개들!', `FemaleText_loc4`='死吧，恶魔的爪牙！', `FemaleText_loc5`='死吧，惡魔的爪牙!', `FemaleText_loc7`='¡MORID, PERROS DEMONÍACOS!' WHERE `ID`=6460;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아! 드디어 신선한 공기를 마시게 되는군요! 다시는 이런 날이 없을 줄 알았어요...', `FemaleText_loc4`='啊！终于呼吸到新鲜空气了！我从没想过还能见到天日……', `FemaleText_loc5`='啊!終於呼吸到新鮮空氣了!我從沒想過還能見到天日...', `FemaleText_loc7`='¡Ah! ¡Al fin, aire fresco! Creía que este día nunca llegaría...' WHERE `ID`=6461;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무슨 소리였죠? 트레이? 트레이인가?', `FemaleText_loc4`='那是什么？！特雷? 特雷!?', `FemaleText_loc5`='那是什麼?!特雷? 特雷!?', `FemaleText_loc7`='¡¿Qué ha sido eso?! ¿Trey? ¡¿TREY?!' WHERE `ID`=6463;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 시체를 받아서 구덩이에 던져 넣어 처리하는 일을 하고 있어요.', `MaleText_loc4`='他们将尸体交给了我，他将尸体投进了深坑。', `MaleText_loc5`='他們將屍體交給了我，他將屍體投進了深坑。', `MaleText_loc7`='Ellos me dan los cuerpos y yo los tiro al foso.' WHERE `ID`=6464;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물건을 사고 싶습니다.', `MaleText_loc4`='我想买些东西。', `MaleText_loc5`='我想買些東西。', `MaleText_loc7`='Me gustaría hacer una compra.', `FemaleText_loc1`='물건을 사고 싶습니다.', `FemaleText_loc4`='我想买些东西。', `FemaleText_loc5`='我想買些東西。', `FemaleText_loc7`='Me gustaría hacer una compra.' WHERE `ID`=6465;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배신자!', `MaleText_loc4`='叛徒！', `MaleText_loc5`='叛徒!', `MaleText_loc7`='¡TRAIDOR!' WHERE `ID`=6466;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안 돼! 녀석들이 도대체 네게 무슨 짓을 한 거야?', `FemaleText_loc4`='不！他们对你做什么了！？', `FemaleText_loc5`='不!他們對你做什麼了!?', `FemaleText_loc7`='¡NO! ¿¡Qué te han hecho!?' WHERE `ID`=6467;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='트레이... 무슨 일이 일어난 거야? 다 내 잘못이야...', `FemaleText_loc4`='不！我的朋友……发生什么了？都是我的错……', `FemaleText_loc5`='不!我的朋友...發生什麼了?都是我的錯...', `FemaleText_loc7`='¡Oh no! ¿Qué ha pasado? Es todo culpa mía...' WHERE `ID`=6468;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기서부터는 혼자서 가야 더 빨리 갈 수 있어요, $n. 잿빛 골짜기 근처에서 제시르 문보우를 만나 보세요. 에메랄드 의회의 드루이드들과 함께 있을 겁니다. 제시르가 다음에 할 일이 뭔지 얘기해 줄 거예요. 도와 주셔서 정말 고맙습니다!', `FemaleText_loc4`='我自己走可以更快些,$n。在灰谷附近与杰希尔·月弓会合。她应该与翡翠议会的德鲁伊在一起。她会告诉你接下来做什么。谢谢你的帮助！', `FemaleText_loc5`='我自己走可以更快些,$n。在梣谷附近與傑希爾·月弓會合。她應該與翡翠議會的德魯伊在一起。她會告訴你接下來做什麼。謝謝你的幫助!', `FemaleText_loc7`='Desde aquí viajaré más rápido sola, $n. Encuentra a Jessir Arcolunar cerca de Vallefresno. Debería estar con los druidas del Círculo Esmeralda. Ella te dirá qué es lo siguiente que debes hacer. ¡Muchas gracias por tu ayuda!' WHERE `ID`=6469;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우편물에 함부로 손을 대서는 안 되지!', `MaleText_loc4`='别把邮件给弄乱了！', `MaleText_loc5`='別把郵件給弄亂了!', `MaleText_loc7`='¡El correo no se toca!', `FemaleText_loc1`='우편물에 함부로 손을 대서는 안 되지!', `FemaleText_loc4`='别把邮件给弄乱了！', `FemaleText_loc5`='別把郵件給弄亂了!', `FemaleText_loc7`='¡El correo no se toca!' WHERE `ID`=6470;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 해보세요!', `MaleText_loc4`='再试一次！', `MaleText_loc5`='再試一次!', `MaleText_loc7`='¡Prueba otra vez!' WHERE `ID`=6471;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정확하군요!', `MaleText_loc4`='当然！', `MaleText_loc5`='當然!', `MaleText_loc7`='¡Desde luego!' WHERE `ID`=6472;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼!', `MaleText_loc4`='不可能！', `MaleText_loc5`='不可能!', `MaleText_loc7`='¡¡Imposible!!' WHERE `ID`=6473;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우체국장께서 오셨다!', `MaleText_loc4`='邮差来了！', `MaleText_loc5`='郵差來了!', `MaleText_loc7`='¡Aquí viene el jefe de correos!', `FemaleText_loc1`='우체국장께서 오셨다!', `FemaleText_loc4`='邮差来了！', `FemaleText_loc5`='郵差來了!', `FemaleText_loc7`='¡Aquí viene el jefe de correos!' WHERE `ID`=6474;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하시오, $n. 나는 대용광로 관리인, 미올로 선더퓨리라고 하오.', `MaleText_loc4`='你好，$n。我是米洛尔·怒斩，大熔炉的看守者。', `MaleText_loc5`='你好，$n。我是米洛爾·怒斬，大鍛爐的守衛者。', `MaleText_loc7`='Saludos, $n. Soy Myolor Furiahendida, guardián de La Gran Fundición.' WHERE `ID`=6475;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방어구제작자가 되고 싶습니다.', `MaleText_loc4`='我希望成为一名铸甲师。', `MaleText_loc5`='我希望成為一名護甲鍛造師。', `MaleText_loc7`='Me gustaría convertirme en forjador de armaduras.', `FemaleText_loc1`='방어구제작자가 되고 싶습니다.', `FemaleText_loc4`='我希望成为一名铸甲师。', `FemaleText_loc5`='我希望成為一名護甲鍛造師。', `FemaleText_loc7`='Me gustaría convertirme en una forjadora de armaduras.' WHERE `ID`=6476;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무기제작자가 되고 싶습니다.', `MaleText_loc4`='我希望成为一名武器铸造师。', `MaleText_loc5`='我希望成為一名武器鍛造師。', `MaleText_loc7`='Me gustaría convertirme en forjador de armas.', `FemaleText_loc1`='무기제작자가 되고 싶습니다.', `FemaleText_loc4`='我希望成为一名武器铸造师。', `FemaleText_loc5`='我希望成為一名武器鍛造師。', `FemaleText_loc7`='Me gustaría convertirme en forjadora de armas.' WHERE `ID`=6477;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 당신의 대장기술은 아주 뛰어나군. 이제 결정을 내릴 때가 됐소. 두 가지 길을 선택할 수 있소. 무기제작자의 길을 걷든가, 방어구제작자의 기술을 배우든가 양자택일하시오.$B$B한 가지 주의할 점은, 한번 결정을 내리면 돌이킬 수 없다는 거요. 어느 것을 택하든 일단 하나를 선택하면 다른 것은 배울 수 없지.', `MaleText_loc4`='你在锻造方面的技术已经非常高超了，$n。该做出决定了。有两条路你可以选择：武器制造工匠或是装甲制造工匠。$B$B注意，当你做出决定以后，就不能回头了。每个方向的守则都不允许你三心二意。', `MaleText_loc5`='你在鍛造方面的技術已經非常高超了，$n。該做出決定了。有兩條路你可以選擇:武器鍛造師或是護甲鍛造師。$B$B注意，當你做出決定以後，就不能回頭了。這兩門技藝的守則都不允許你三心二意。', `MaleText_loc7`='Tu habilidad en herrería es excepcional, $n. Ha llegado el momento de tomar una decisión. Puedes elegir entre dos caminos: el del forjador de armas o el del forjador de armaduras.$B$BPero $gatento:atenta;, cuando elijas dedicarte a uno de ellos, ya no habrá vuelta atrás. La disciplina que exigen no deja espacio para híbridos.' WHERE `ID`=6478;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$g형제:자매;여. 스컬지에게서 어둠을 다시 빼앗을 때가 되었다네!', `FemaleText_loc4`='时机成熟了，我的$g兄弟:姐妹;们，武装起来，从亡灵天灾手中夺回属于我们的夜晚！', `FemaleText_loc5`='時機成熟了，我的$g兄弟:姐妹;們，武裝起來，從天譴軍團手中奪回屬於我們的夜晚!', `FemaleText_loc7`='Ha llegado la hora, $ghermano:hermana;, a las armas, ¡hay que recuperar la noche de la Plaga!' WHERE `ID`=6479;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$g형제:자매;여. 스컬지에게서 밤을 다시 빼앗을 때가 되었습니다!', `FemaleText_loc4`='时机成熟了，我的$g兄弟:姐妹;们，武装起来，从亡灵天灾手中夺回属于我们的夜晚！', `FemaleText_loc5`='時機成熟了，我的$g兄弟:姐妹;們，武裝起來，從天譴軍團手中奪回屬於我們的夜晚!', `FemaleText_loc7`='Ha llegado la hora, $ghermano:hermana;, a las armas, ¡hay que recuperar la noche de la Plaga!' WHERE `ID`=6480;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안타깝게도 그대가 텔드랏실 나이트 엘프와 다르나서스의 진정한 친구라는 생각은 들지 않는군요. 말뿐이 아니라 행동으로 그대가 우리 나이트 엘프의 친구라는 걸 증명해 보인 후에만 제가 판매하는 탈것을 그대에게 보여 드리겠습니다.', `MaleText_loc4`='唉$c，你不是达纳苏斯的臣民和泰达希尔的暗夜精灵的朋友。除非你以实际行动——不仅仅是口头上的话语——证明自己的友好态度，那样的话，我会提供坐骑让你挑选的。', `MaleText_loc5`='唉$c，你不是達納蘇斯的臣民和泰達希爾的夜精靈的朋友。除非你以實際行動─不僅僅是口頭上的話語─證明自己的友好態度，那樣的話，我會提供坐騎讓你挑選的。', `MaleText_loc7`='Por desgracia, $c, no eres $gconsiderado:considerada; $gun auténtico amigo:una auténtica amiga; de Darnassus y de los elfos de la noche de Teldrassil. Solo cuando demuestres ser $gamistoso:amistosa; con nosotros a través de los hechos (y no solo con las palabras) pondré a tu disposición mi selección de monturas, entonces podrás examinarlas.', `FemaleText_loc1`='안타깝게도 그대가 텔드랏실 나이트 엘프와 다르나서스의 진정한 친구라는 생각은 들지 않는군요. 말뿐이 아니라 행동으로 그대가 우리 나이트 엘프의 친구라는 걸 증명해 보인 후에만 제가 판매하는 탈것을 그대에게 보여 드리겠습니다.', `FemaleText_loc4`='唉$c，你不是达纳苏斯的臣民和泰达希尔的暗夜精灵的朋友。除非你以实际行动——不仅仅是口头上的话语——证明自己的友好态度，那样的话，我会提供坐骑让你挑选的。', `FemaleText_loc5`='唉$c，你不是達納蘇斯的臣民和泰達希爾的夜精靈的朋友。除非你以實際行動─不僅僅是口頭上的話語─證明自己的友好態度，那樣的話，我會提供坐騎讓你挑選的。', `FemaleText_loc7`='Por desgracia, $c, no eres $gconsiderado:considerada; $gun auténtico amigo:una auténtica amiga; de Darnassus y de los elfos de la noche de Teldrassil. Solo cuando demuestres ser $gamistoso:amistosa; con nosotros a través de los hechos (y no solo con las palabras) pondré a tu disposición mi selección de monturas, entonces podrás examinarlas.' WHERE `ID`=6481;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엘룬의 은총으로 그대에게 텔드랏실 최고의 탈것인 밤호랑이를 보여 드리게 된 것을 진심으로 기쁘게 생각합니다. 오랫동안 파수대는 이 밤호랑이 친구를 믿고 의지해 왔습니다.$B$B맘에 드는 게 있는지 천천히 살펴보십시오. 결코 실망하시는 일은 없을 겁니다.', `MaleText_loc4`='承蒙月神的关照，我很高兴给你在整个泰达希尔找到的最好——甚至是这世上最好的坐骑，它们就是夜刃豹。数年来，哨兵部队一直倚赖这些同伴的价值。$B$B抓紧时间，朋友，挑选一匹你满意的。我敢肯定你不会失望的。', `MaleText_loc5`='承蒙伊露恩的關照，我很高興給你在整個泰達希爾找到的最好的坐騎，甚至是這世上最好的--黑豹。數年來，哨兵部隊一直倚賴這些同伴的價值。$B$B抓緊時間，朋友，挑選一匹你滿意的。我敢肯定你不會失望的。', `MaleText_loc7`='Por la gracia de Elune, estoy encantado de ofrecerte el mejor corcel que podrás encontrar en Teldrassil, y quizás en todo el mundo... el sable de la noche. Durante años, el ejército de los centinelas ha confiado en su valor.$B$BTómate tu tiempo para examinarlos cuanto desees. Estoy seguro de que no quedarás $gdecepcionado:decepcionada;.', `FemaleText_loc1`='엘룬의 은총으로 그대에게 텔드랏실 최고의 탈것인 밤호랑이를 보여 드리게 된 것을 진심으로 기쁘게 생각합니다. 오랫동안 파수대는 이 밤호랑이 친구를 믿고 의지해 왔습니다.$B$B맘에 드는 게 있는지 천천히 살펴보십시오. 결코 실망하시는 일은 없을 겁니다.', `FemaleText_loc4`='承蒙月神的关照，我很高兴给你在整个泰达希尔找到的最好——甚至是这世上最好的坐骑，它们就是夜刃豹。数年来，哨兵部队一直倚赖这些同伴的价值。$B$B抓紧时间，朋友，挑选一匹你满意的。我敢肯定你不会失望的。', `FemaleText_loc5`='承蒙伊露恩的關照，我很高興給你在整個泰達希爾找到的最好的坐騎，甚至是這世上最好的--黑豹。數年來，哨兵部隊一直倚賴這些同伴的價值。$B$B抓緊時間，朋友，挑選一匹你滿意的。我敢肯定你不會失望的。', `FemaleText_loc7`='Por la gracia de Elune, estoy encantada de ofrecerte el mejor corcel que podrás encontrar en Teldrassil, y quizás en todo el mundo... el sable de la noche. Durante años, el ejército de los centinelas ha confiado en su valor.$B$BTómate tu tiempo para examinarlos cuanto desees. Estoy segura de que no quedarás $gdecepcionado:decepcionada;.' WHERE `ID`=6482;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엄... 죄송하지만 제가 당신을 그리 잘 알지 못해서 말이죠. 그게, 저는 공인 기계타조 상인으로서 노움의 친구로 간주되는 이들에게만 탈것을 팔 수가 있단 말이죠. 당신이 놈리건에 우호적이라고 인정받으면 기꺼이 제가 가진 것들을 보여 드리도록 하겠어요.', `MaleText_loc4`='呃……很抱歉，我真的不太了解你。我是说，作为公认的机械陆行鸟经销商，我只能跟侏儒的朋友做生意。要是你能和诺莫瑞根保持友好态度，我会很高兴地为你提供服务的。', `MaleText_loc5`='呃...很抱歉，我真的不太瞭解你。我是說，作為公認的機械陸行鳥經銷商，我只能跟地精的朋友做生意。要是你能和諾姆瑞根保持友好態度，我會很高興地為你提供服務的。', `MaleText_loc7`='Errr... No te conozco lo suficiente lo siento. Como agente autorizado de mecazancudos solo puedo vender mis monturas a los que son considerados amigos de los gnomos. Si llegas a ser $greconocido:reconocida; como $gamigo:amiga; de Gnomeregan, estaré encantado de enseñarte toda mi oferta.', `FemaleText_loc1`='엄... 죄송하지만 제가 당신을 그리 잘 알지 못해서 말이죠. 그게, 저는 공인 기계타조 상인으로서 노움의 친구로 간주되는 이들에게만 탈것을 팔 수가 있단 말이죠. 당신이 놈리건에 우호적이라고 인정받으면 기꺼이 제가 가진 것들을 보여 드리도록 하겠어요.', `FemaleText_loc4`='呃……很抱歉，我真的不太了解你。我是说，作为公认的机械陆行鸟经销商，我只能跟侏儒的朋友做生意。要是你能和诺莫瑞根保持友好态度，我会很高兴地为你提供服务的。', `FemaleText_loc5`='呃...很抱歉，我真的不太瞭解你。我是說，作為公認的機械陸行鳥經銷商，我只能跟地精的朋友做生意。要是你能和諾姆瑞根保持友好態度，我會很高興地為你提供服務的。', `FemaleText_loc7`='Errr... No te conozco lo suficiente lo siento. Como agente autorizada de mecazancudos solo puedo vender mis monturas a los que son considerados amigos de los gnomos. Si llegas a ser $greconocido:reconocida; como $gamigo:amiga; de Gnomeregan, estaré encantada de enseñarte toda mi oferta.' WHERE `ID`=6483;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그게... 그 기계타조를 타시기에는 좀 체격이 너무 크신 것 같은데요? 손님이 기계타조를 타시면 미세하게 조정된 서보 평형 유지 장치가 부서져 버릴 것 같아요!', `MaleText_loc4`='嗯……我认?你体型过大，不能乘坐机械陆行鸟，$g先生:女士;。你很可能会压碎这些精美的机器！', `MaleText_loc5`='嗯...我認為你體型過大，不能乘坐機械陸行鳥，$g先生:女士;。你很可能會壓碎這些精美的機器!', `MaleText_loc7`='Umm... Creo que es demasiado grande para montar un mecazancudo, $gseñor:señora;. ¡Podría aplastar los delicados servoestabilizadores!', `FemaleText_loc1`='그게... 그 기계타조를 타시기에는 좀 체격이 너무 크신 것 같은데요? 손님이 기계타조를 타시면 미세하게 조정된 서보 평형 유지 장치가 부서져 버릴 것 같아요!', `FemaleText_loc4`='嗯……我认为你体型过大，不能乘坐机械陆行鸟，$g先生:女士;。你很可能会压碎这些精美的机器！', `FemaleText_loc5`='嗯...我認為你體型過大，不能乘坐機械陸行鳥，$g先生:女士;。你很可能會壓碎這些精美的機器!', `FemaleText_loc7`='Umm... Creo que es demasiado grande para montar un mecazancudo, $gseñor:señora;. ¡Podría aplastar los delicados servoestabilizadores!' WHERE `ID`=6484;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빠르고 안전한 이동 수단을 찾으신다면 제대로 찾아오신 겁니다! 올해 신형 기계타조 모델이 최근에 들어왔어요, 왔어. 전부 다 보여 드리도록 하죠!', `MaleText_loc4`='如果你是为获得快速而安全的产品而来，那么这儿就是你的目的地了！今年的机械陆行鸟模型已经到了，我将为你展示其性能！', `MaleText_loc5`='如果你是為獲得快速而安全的產品而來，那麼這兒就是你的目的地了!今年的機械陸行鳥模型已經到了，我將為你展示其性能!', `MaleText_loc7`='Si has venido buscando el don de la movilidad segura y rápida, ¡has llegado a tu destino! Acaban de llegar los nuevos modelos de mecazancudos ¡y estoy listo para enseñarte todas sus prestaciones!', `FemaleText_loc1`='빠르고 안전한 이동 수단을 찾으신다면 제대로 찾아오신 겁니다! 올해 신형 기계타조 모델이 최근에 들어왔어요, 왔어. 전부 다 보여 드리도록 하죠!', `FemaleText_loc4`='如果你是为获得快速而安全的产品而来，那么这儿就是你的目的地了！今年的机械陆行鸟模型已经到了，我将为你展示其性能！', `FemaleText_loc5`='如果你是為獲得快速而安全的產品而來，那麼這兒就是你的目的地了!今年的機械陸行鳥模型已經到了，我將為你展示其性能!', `FemaleText_loc7`='Si has venido buscando el don de la movilidad segura y rápida, ¡has llegado a tu destino! Acaban de llegar los nuevos modelos de mecazancudos ¡y estoy lista para enseñarte todas sus prestaciones!' WHERE `ID`=6485;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 이로누스와 얘기해 보시오. 무기 제작술을 가르쳐 줄 거요.', `MaleText_loc4`='跟埃隆努斯谈谈，$n。他会教你如何成为一名武器铸造师的。', `MaleText_loc5`='跟埃隆努斯談談，$n。他會教你如何成為一名武器鍛造師的。', `MaleText_loc7`='Habla con Ironus, $n. Él será quien te instruya en el camino del forjador de armas.' WHERE `ID`=6486;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방어구 제작술은 그룸누스를 찾아가 보시오.', `MaleText_loc4`='格鲁努斯就是你要找的人，$n。他会教授你铸甲师这门艺术。', `MaleText_loc5`='格魯努斯就是你要找的人，$n。他會教授你護甲鍛造這門藝術。', `MaleText_loc7`='Grumnus es tu hombre, $n. Te instruirá en el arte de la forja de armaduras.' WHERE `ID`=6487;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 자네 정도의 수준에 이른 대장장이들에게 선택을 하도록 하지.$B$B반드시 선택을 해야 하는 건 아니지만, 그편이 더 좋을 거야. 어쨌거나 평생 남의 밑에서 있을 수만은 없지 않나? 우리 군대가 전쟁에서 승리하여 갈채를 받는 데 있어 주인공은 바로 물자를 보급하는 전문 방어구제작자와 무기제작자들이야!$B$B$n, 한 가지 주의를 줄 게 있네. 한번 선택을 하고 주어진 임무를 마치고 나면 돌이킬 수 없어. 오직 한 길을 걸어갈 수 있을 뿐이지.', `MaleText_loc4`='当一个铁匠达到了你这样的专业水平的时候，我会提供给他们一个选择。$B$B虽然我并没有要求你必须做出选择，但我建议你最好还是做出抉择——毕竟，你想永远当一名新手吗？是大师级的铸甲师和武器铸造师给我们的军队提供补给，让我们赢得战争的胜利并获得荣耀！$B$B注意，$n，一旦你做出了决定并完成了指定的任务，就没有回头路了。一个人只能沿一条路走到底。', `MaleText_loc5`='當一個鐵匠達到了你們專家工藝水準的時候，我會提供給他們一個選擇。$B$B雖然沒有要求你做出選擇，但建議你最好還是做出抉擇─畢竟，你想永遠的當一名新手嗎?是專家級的護甲鍛造師和武器鍛造師給我們軍隊提供補給，從而贏得戰爭的勝利並獲得稱讚!$B$B注意，$n。一旦做出了決定並完成了要求的任務--就沒有回頭路了。一個人只能沿一條路走到底。', `MaleText_loc7`='Cuando el trabajo de un herrero alcanza el grado de experto, le planteo una elección.$B$BNo tienes por qué tomar una decisión, pero es mejor hacerlo. Después de todo no querrás ser siempre $gun neófito:una neófita;, ¿verdad? Son los artesanos forjadores de armaduras y de armas los que equipan a nuestros ejércitos, ganan nuestras guerras y cosechan los aplausos.$B$BPero $gatento:atenta;, $n. Cuando hagas tu elección y completes las tareas necesarias, ya no habrá vuelta atrás. Solo se puede seguir un camino.' WHERE `ID`=6488;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 크라토크라고 하네. 이 대장장이들을 감독하고 있지.', `MaleText_loc4`='我是克拉索克，这些工匠的监工。', `MaleText_loc5`='我是克拉索克，這些工匠的監督者。', `MaleText_loc7`='Soy Krathok, sobrestante de estos artesanos.' WHERE `ID`=6489;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보르고쉬! $n|1이;가; 훈련 받을 준비가 됐군.', `MaleText_loc4`='伯古什！$n已经准备好接受训练啦。', `MaleText_loc5`='伯古西!$n已經準備好接受訓練啦。', `MaleText_loc7`='¡Borgosh! $n está listo para recibir instrucción.' WHERE `ID`=6490;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오코토스가 자네 훈련을 맡을 걸, $n.', `MaleText_loc4`='奥克索斯会教你的，$n。', `MaleText_loc5`='奧克索斯會教你的，$n。', `MaleText_loc7`='Okothos te instruirá, $n.' WHERE `ID`=6491;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='애쉬아리 수정 하나가 파괴되었다! 침략자들을 처치하라!', `MaleText_loc4`='一块阿莎利水晶已经被摧毁了！杀死入侵者！', `MaleText_loc5`='一塊阿莎利水晶已經被摧毀了!殺死入侵者!', `MaleText_loc7`='¡Ha sido destruido uno de los Cristales de Ash''ari! ¡Eliminad a esos intrusos!', `FemaleText_loc1`='애쉬아리 수정 하나가 파괴되었다! 침략자들을 처치하라!', `FemaleText_loc4`='一块阿莎利水晶已经被摧毁了！杀死入侵者！', `FemaleText_loc5`='一塊阿莎利水晶已經被摧毀了!殺死入侵者!', `FemaleText_loc7`='¡Ha sido destruido uno de los Cristales de Ash''ari! ¡Eliminad a esos intrusos!' WHERE `ID`=6492;
