UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 누가 이 가마솥에 접근하는 것이냐? 내 암흑의 칼맛을 봐라!', `MaleText_loc4`='谁敢靠近这个大熔炉？尝尝我的黑暗之刃！', `MaleText_loc5`='誰敢靠近這個大熔爐?嘗嘗我的黑暗之刃!', `MaleText_loc7`='¿Quién osa acercarse a la caldera? ¡Disfruta de mi oscura espada!' WHERE `ID`=6495;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너도 스컬지가 되게 해주겠다! 어리석은 $r|1이여;여;.', `MaleText_loc4`='亡灵天灾在召唤你，愚蠢的$r。', `MaleText_loc5`='天譴軍團在召喚你，愚蠢的$r。', `MaleText_loc7`='La Plaga te llama, $gestúpido:estúpida; $r.' WHERE `ID`=6496;
