UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 말로운 님이 무서운 맛을 보여주마!', `MaleText_loc4`='准备被玛罗恩干掉吧。', `MaleText_loc5`='準備被瑪羅恩幹掉吧。', `MaleText_loc7`='¡Prepárate para recibir un machaque de Gassol!' WHERE `ID`=6504;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='명가의 원혼들이여! 진정하세요! 진말로의 수정이 다시 제자리를 찾았습니다!', `FemaleText_loc4`='上层精灵的灵魂，安息吧！辛玛洛水晶终于复原了！', `FemaleText_loc5`='精靈貴族的靈魂，安息吧!辛瑪洛水晶終於復原了!', `FemaleText_loc7`='¡Espíritus Altonato! ¡Estad en paz! ¡El Cristal de Zin-Malor vuelve a estar entero!' WHERE `ID`=6505;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저주받은 영혼들이여! 과거는 잊어 버리세요! 더 이상 진말로의 수정이 속박하는 일은 없을 테니까요!', `FemaleText_loc4`='被诅咒的灵魂！忘记过去吧！辛玛洛水晶已经不再束缚你们了！', `FemaleText_loc5`='被詛咒的靈魂!忘記過去吧!辛瑪洛水晶已經不再束縛你們了!', `FemaleText_loc7`='¡Espíritus malditos! ¡Abandonad el pasado! ¡El Cristal de Zin-Malor ya no os ata!' WHERE `ID`=6506;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='명가의 원혼들이여! 안식을 찾으세요! 이제 수정의 저주에서 풀려 났어요!', `FemaleText_loc4`='上层精灵的灵魂！你们可以安息了！水晶的诅咒已经被解除了！', `FemaleText_loc5`='精靈貴族的靈魂!你們可以安息了!水晶的詛咒已經被解除了!', `FemaleText_loc7`='¡Espíritus de los Altonato! ¡Ya podéis descansar! ¡La maldición del cristal os ha liberado!' WHERE `ID`=6507;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 은빛 성기사단처럼 성스러운 빛을 추종하는 건 아니지만, 언제든 저희에게 도움을 청하셔도 좋습니다.', `MaleText_loc4`='你可能不会像一个银手骑士那样追寻光之踪迹，但是你总可以向我们寻求帮助。', `MaleText_loc5`='你可能不會像白銀之手騎士團那樣追尋光之蹤跡，但是你總可以向我們尋求幫助。', `MaleText_loc7`='No puedes seguir la senda de la Luz como un caballero de la Mano de Plata, pero siempre podrás pedir nuestra ayuda.', `FemaleText_loc1`='당신이 은빛 성기사단처럼 성스러운 빛을 추종하는 건 아니지만, 언제든 저희에게 도움을 청하셔도 좋습니다.', `FemaleText_loc4`='你可能不会像一个银手骑士那样追寻圣光的踪迹，但是你总可以向我们寻求帮助。', `FemaleText_loc5`='你可能不會像白銀之手騎士團那樣追尋光之蹤跡，但是你總可以向我們尋求幫助。', `FemaleText_loc7`='No puedes seguir la senda de la Luz como un caballero de la Mano de Plata, pero siempre podrás pedir nuestra ayuda.' WHERE `ID`=6509;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성스러운 빛이 함께하기를, $c|1이여;여;. 무엇을 도와 드릴까요?', `MaleText_loc4`='愿圣光与你同在，$c。我能帮上忙吗？', `MaleText_loc5`='願聖光與你同在，$c。我能幫上忙嗎?', `MaleText_loc7`='Que la Luz esté contigo, $c. ¿Puedo ayudarte?', `FemaleText_loc1`='성스러운 빛이 함께하기를, $c|1이여;여;. 무엇을 도와 드릴까요?', `FemaleText_loc4`='愿圣光与你同在，$c。我能帮上忙吗？', `FemaleText_loc5`='願聖光與你同在，$c。我能幫上忙嗎?', `FemaleText_loc7`='Que la Luz esté contigo, $c. ¿Puedo ayudarte?' WHERE `ID`=6510;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 언데드 하수인을 다시 살려냅니다!', `MaleText_loc4`='%s复活了一名亡灵仆从！', `MaleText_loc5`='%s將一名亡靈僕從復活!', `MaleText_loc7`='%s devuelve a un sirviente no-muerto a la vida.' WHERE `ID`=6511;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 하수인에게 죽음의 서약을 시전하려고 합니다!', `MaleText_loc4`='%s尝试对他的仆从释放死亡契约！', `MaleText_loc5`='%s嘗試對他的僕從們施展死亡契約!', `MaleText_loc7`='¡%s intenta lanzar un Pacto de Muerte a sus sirvientes!' WHERE `ID`=6512;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비전 촉매제를 구입하고 싶습니다.', `MaleText_loc4`='我想向你购买奥术催化剂。', `MaleText_loc5`='我想向你購買秘法速化劑。', `MaleText_loc7`='Desearía comprarte un acelerador arcano.', `FemaleText_loc1`='비전 촉매제를 구입하고 싶습니다.', `FemaleText_loc4`='我想向你购买奥术催化剂。', `FemaleText_loc5`='我想向你購買秘法速化劑。', `FemaleText_loc7`='Desearía comprarte un acelerador arcano.' WHERE `ID`=6513;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뼈가 훤히 다 드러난 내 무릎이 쑤시는 걸 보니, 곧 굉장한 비바람이 불어오겠구먼. 그 폭풍에 갇히지나 않았으면 좋겠네.', `MaleText_loc4`='一场猛烈的风就要来了——我可以通过我裸露膝盖的疼痛判断出来。我就是希望我们不要被狂风困住。', `MaleText_loc5`='一場猛烈的風就要來了─我可以透過我裸露的膝蓋的疼痛來判斷。我只希望我們不要被狂風困住。', `MaleText_loc7`='Se acerca un viento violento, lo noto por el dolor de la rodilla que tengo al descubierto. Solo espero que no nos alcance.' WHERE `ID`=6514;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자 이제, 가마솥들에 작업을 시작해 보세, $n! 우리가 필요로 하는 재료들을 모으려면 나한테서 유리질 집중기를 하나 받아야 할 게야. 스컬지에게서 가마솥 변환에 필요한 제대로 된 재료를 찾으려면 이게 있어야 하니까.$B$B그리고 가마솥들에 사용할 비전 촉매제도 한 번 쓸 분량만큼 필요하지. 값도 싸지 않은 데 안정성도 없지. 일단 30분이 지나면 못쓰게 되니까, 그 안에 사용해야 해. 그러니까 살 때 잘 생각해 보게나.', `MaleText_loc4`='好吧，$n，让我们来看看怎么对付这些天灾之锅！如果你要收集所需的成分，就带上一个玻璃聚焦装置吧。在鉴别从亡灵天灾的爪牙身上获取的资源时，你会用得着它的。$B$B你还需要找一份奥术催化剂。这东西可不便宜，而且也非常不稳定。一旦你得到药剂，就必须在15分钟内使用它，否则药剂就失效了。所以你可得留神别乱买。', `MaleText_loc5`='好吧，$n，讓我們來看看怎麼對付這些瘟疫之鍋!如果你要收集所需的成分，就帶上一個玻璃聚焦裝置吧。在鑒別從天譴軍團的爪牙身上獲取的資源時，你會用得著它的。$B$B你還需要找一份秘法速化劑。這東西可不便宜，而且也非常不穩定。一旦你得到藥劑，就必須在15分鐘內使用它，否則藥劑就失效了。所以你可得留神別亂買。', `MaleText_loc7`='Veamos $n, ¡pongámonos a trabajar con esas calderas! Si vas a reunir los componentes necesarios, te proporcionaré un enfocador vítreo. Necesitas llevarlo contigo para identificar los ingredientes necesarios que se encuentran en los miembros de la Plaga y que transformarán las calderas.$B$BTambién necesitarás un acelerador arcano. No es barato, ni estable. Cuando lo tengas en tus manos solo tendrás treinta minutos para usarlo antes de que se consuma; cómpralo cuando vayas a utilizarlo y sé $grápido:rápida;.' WHERE `ID`=6515;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='펠스톤 농장에 있는 가마솥에는 무엇이 필요합니까?', `MaleText_loc4`='费尔斯通农场的天灾之锅都需要什么？', `MaleText_loc5`='費爾斯通農場的瘟疫之鍋都需要什麼?', `MaleText_loc7`='¿Qué se necesita para la caldera del Campo de Piedramácula?', `FemaleText_loc1`='펠스톤 농장에 있는 가마솥에는 무엇이 필요합니까?', `FemaleText_loc4`='费尔斯通农场的天灾之锅都需要什么？', `FemaleText_loc5`='費爾斯通農場的瘟疫之鍋都需要什麼?', `FemaleText_loc7`='¿Qué se necesita para la caldera del Campo de Piedramácula?' WHERE `ID`=6516;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달슨의 눈물에 있는 가마솥에는 무엇이 필요합니까?', `MaleText_loc4`='达尔松之泪的天灾之锅都需要什么？', `MaleText_loc5`='達爾松之淚的瘟疫之鍋都需要什麼?', `MaleText_loc7`='¿Qué se necesita para la caldera del Llanto de Dalson?', `FemaleText_loc1`='달슨의 눈물에 있는 가마솥에는 무엇이 필요합니까?', `FemaleText_loc4`='达尔松之泪的天灾之锅都需要什么？', `FemaleText_loc5`='達爾松之淚的瘟疫之鍋都需要什麼?', `FemaleText_loc7`='¿Qué se necesita para la caldera del Llanto de Dalson?' WHERE `ID`=6517;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고통의 흉가에 있는 가마솥에는 무엇이 필요합니까?', `MaleText_loc4`='嚎哭鬼屋的天灾之锅都需要什么？', `MaleText_loc5`='苦痛鬼屋的瘟疫之鍋都需要什麼?', `MaleText_loc7`='¿Qué se necesita para la caldera de El Tormento?', `FemaleText_loc1`='고통의 흉가에 있는 가마솥에는 무엇이 필요합니까?', `FemaleText_loc4`='嚎哭鬼屋的天灾之锅都需要什么？', `FemaleText_loc5`='苦痛鬼屋的瘟疫之鍋都需要什麼?', `FemaleText_loc7`='¿Qué se necesita para la caldera de El Tormento?' WHERE `ID`=6518;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가론의 흉가에 있는 가마솥에는 무엇이 필요합니까?', `MaleText_loc4`='盖罗恩农场的天灾之锅都需要什么？', `MaleText_loc5`='蓋羅恩農場的瘟疫之鍋都需要什麼?', `MaleText_loc7`='¿Qué se necesita para la caldera de la Gangrena de Gahrron?', `FemaleText_loc1`='가론의 흉가에 있는 가마솥에는 무엇이 필요합니까?', `FemaleText_loc4`='盖罗恩农场的天灾之锅都需要什么？', `FemaleText_loc5`='蓋羅恩農場的瘟疫之鍋都需要什麼?', `FemaleText_loc7`='¿Qué se necesita para la caldera de la Gangrena de Gahrron?' WHERE `ID`=6519;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 가져온 독극물 견본을 보니 비전 촉매제 하나, 골성 교반기 6개, 그리고 룬무늬 옷감 4개가 필요할 것 같군. 유리질 집중기를 가지고 가면 이곳 역병지대에 있는 해골 언데드에게서 골성 교반기를 구할 수 있다네.$B$B이 물건들을 다 찾으면 그 가마솥에 반작용 물질을 투입할 수 있을 것이야.', `MaleText_loc4`='根据你提供的样本，我们认为你需要下面这些东西：一份奥术催化剂、六份骨质分离素和四块符文布。你可以使用玻璃放大镜从瘟疫之地的骸骨亡灵身上获取骨质分离素！$B$B一旦你获得了这些物品，就可以把它们放进天灾之锅里了。', `MaleText_loc5`='根據你提供的毒素樣本，我們認為你需要下面這些東西:一份秘法速化劑、六份骨質分離素和四塊符文布。你可以使用玻璃放大鏡從瘟疫之地的骷髏亡靈身上獲取骨質分離素!$B$B一旦你獲得了這些物品，就可以把它們放進瘟疫之鍋裡了。', `MaleText_loc7`='A partir de la muestra de la toxina que nos has proporcionado, pensamos que necesitarás lo siguiente: un acelerador arcano, seis agitadores óseos y cuatro piezas de paño rúnico. Llevando contigo el enfocador vítreo obtén los agitadores de los no-muertos esqueléticos de las Tierras de la Peste.$B$BCuando tengas todo lo necesario, deberías poder cargar el contraagente en la caldera.' WHERE `ID`=6520;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 가져온 독극물 견본을 보니 비전 촉매제 하나, 체세포 강화물질 5개, 그리고 룬무늬 옷감 4개가 필요할 것 같군. 유리질 집중기를 가지고 가면 이곳 역병지대에 있는 좀비나 구울 언데드에게서 체세포 강화물질을 구할 수 있다네.$B$B이 물건들을 다 찾으면 그 가마솥에 반작용 물질을 투입할 수 있을 것이야.', `MaleText_loc4`='根据你提供的样本，我们认为你需要下面这些东西：一份奥术催化剂、五份细胞增强剂和四块符文布。你可以使用玻璃放大镜从瘟疫之地的僵尸或食尸鬼身上获取细胞增强剂！$B$B一旦你获得了这些物品，就可以把它们放进天灾之锅里了。', `MaleText_loc5`='根據你提供的毒素樣本，我們認為你需要下面這些東西:一份秘法速化劑、五份細胞增強劑和四塊符文布。你可以使用玻璃放大鏡從瘟疫之地的殭屍或食屍鬼身上獲取細胞增強劑!$B$B一旦你獲得了這些物品，就可以把它們放進瘟疫之鍋裡了。', `MaleText_loc7`='A partir de la muestra de la toxina que nos has proporcionado, pensamos que necesitarás lo siguiente: un acelerador arcano, cinco intensificadores somáticos y cuatro piezas de paño rúnico. Llevando contigo el enfocador vítreo obtén los intensificadores de los zombis o no-muertos necrófagos de las Tierras de la Peste.$B$BCuando tengas todo lo necesario, deberías poder cargar el contraagente en la caldera.' WHERE `ID`=6521;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 가져온 독극물 견본을 보니 비전 촉매제 하나, 체세포 강화물질 5개, 그리고 룬무늬 옷감 4개가 필요할 것 같군. 유리질 집중기를 가지고 가면 이곳 역병지대에 있는 좀비나 구울 언데드에게서 체세포 강화물질을 구할 수 있다네.$B$B이 물건들을 다 찾으면 그 가마솥에 반작용 물질을 투입할 수 있을 것이야.', `MaleText_loc4`='根据你提供的样本，我们认为你需要下面这些东西：一份奥术催化剂、五份细胞增强剂和四块符文布。你可以使用玻璃放大镜从瘟疫之地的僵尸或食尸鬼身上获取细胞增强剂！$B$B一旦你获得了这些物品，就可以把它们放进天灾之锅里了。', `MaleText_loc5`='根據你提供的毒素樣本，我們認為你需要下面這些東西:一份秘法速化劑、五份細胞增強劑和四塊符文布。你可以使用玻璃放大鏡從瘟疫之地的殭屍或食屍鬼身上獲取細胞增強劑!$B$B一旦你獲得了這些物品，就可以把它們放進瘟疫之鍋裡了。', `MaleText_loc7`='A partir de la muestra de la toxina que nos has proporcionado, pensamos que necesitarás lo siguiente: un acelerador arcano, cinco intensificadores somáticos y cuatro piezas de paño rúnico. Llevando contigo el enfocador vítreo obtén los intensificadores de los zombis o no-muertos necrófagos de las Tierras de la Peste.$B$BCuando tengas todo lo necesario, deberías poder cargar el contraagente en la caldera.' WHERE `ID`=6522;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 가져온 독극물 견본을 보니 비전 촉매제 하나, 심령 공명체 4개, 그리고 룬무늬 옷감 4개가 필요할 것 같군. 유리질 집중기를 가지고 있으면 이곳 역병지대에 있는 망령이나 유령 언데드에게서 심령 공명체를 구할 수 있다네.$B$B이 물건들을 다 찾으면 그 가마솥에 반작용 물질을 투입할 수 있을 것이야.', `MaleText_loc4`='根据你提供的样本，我们认为你需要下面这些东西：一份奥术催化剂、四份外膜震荡体和四块符文布。你可以使用玻璃放大镜从瘟疫之地的鬼魂或怨灵身上获取外膜震荡体！$B$B一旦你获得了这些物品，就可以把它们放进天灾之锅里了。', `MaleText_loc5`='根據你提供的毒素樣本，我們認為你需要下面這些東西:一份秘法速化劑、四份魂能共振器和四塊符文布。你可以使用玻璃放大鏡從瘟疫之地的鬼魂或怨靈身上獲取魂能共振器!$B$B一旦你獲得了這些物品，就可以把它們放進瘟疫之鍋裡了。', `MaleText_loc7`='A partir de la muestra de la toxina que nos has proporcionado, pensamos que necesitarás lo siguiente: un acelerador arcano, cuatro resonadores ectoplásmicos y cuatro piezas de paño rúnico. Llevando contigo el enfocador vítreo obtén los resonadores de las ánimas y fantasmas de no-muertos de las Tierras de la Peste.$B$BCuando tengas todo lo necesario, deberías poder cargar el contraagente en la caldera.' WHERE `ID`=6523;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하는 일에 비하면 보수가 형편 없어요.', `MaleText_loc4`='这份工作明显不值16500的年薪。', `MaleText_loc5`='這份工作明顯不值16500的年薪。', `MaleText_loc7`='Ciento sesenta y cinco al año es poco por este trabajo.' WHERE `ID`=6524;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자 이제, 저 가마솥들에 작업을 시작해 봅시다, $n! 우리가 필요로 하는 재료들을 모으려면 나한테서 유리질 집중기를 하나 받아 가십시오. 스컬지에게서 가마솥들을 전환시키는 데 필요한 재료를 제대로 알아보려면 이게 있어야 하니까요.$B$B그리고 가마솥들에 사용할 비전 촉매제도 한 번 쓸 분량만큼 필요할 겁니다. 값도 싸지 않은 데다 안정성 있는 물건도 아니지만... 일단 그걸 구한 다음에는 30분이 지나면 못쓰게 되니 그 전에 사용해야 할 겁니다. 그러니까 살 때 잘 생각해 보고 구입하도록 하십시오.', `MaleText_loc4`='好吧，$n，让我们来看看怎么对付这些天灾之锅！如果你要收集所需的成分，就带上一个玻璃聚焦装置吧。在鉴别从亡灵天灾的爪牙身上获取的资源时，你会用得着它的。$B$B你还需要找一份奥术催化剂。这东西可不便宜，而且也非常不稳定。一旦你得到药剂，就必须在15分钟内使用它，否则药剂就失效了。所以你可得留神别乱买。', `MaleText_loc5`='好吧，$n，讓我們來看看怎麼對付這些瘟疫之鍋!如果你要收集所需的成分，就帶上一個玻璃聚焦裝置吧。在鑒別從天譴軍團的爪牙身上獲取的資源時，你會用得著它的。$B$B你還需要找一份秘法速化劑。這東西可不便宜，而且也非常不穩定。一旦你得到藥劑，就必須在15分鐘內使用它，否則藥劑就失效了。所以你可得留神別亂買。', `MaleText_loc7`='Veamos $n, ¡pongámonos a trabajar con esas calderas! Si vas a reunir los componentes necesarios, te proporcionaré un enfocador vítreo. Necesitas llevarlo contigo para identificar los ingredientes necesarios que se encuentran en los miembros de la Plaga y que transformarán las calderas.$B$BTambién necesitarás un acelerador arcano. No es barato, ni estable. Cuando lo tengas en tus manos solo tendrás treinta minutos para usarlo antes de que se consuma; cómpralo cuando vayas a utilizarlo y sé $grápido:rápida;.' WHERE `ID`=6525;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='애쉬아리 수정 하나가 쓰러졌다! 형제들이여, 리치 왕에 대한 충성을 지켜 수정을 다시 소환하라!', `MaleText_loc4`='阿莎利水晶已经被摧毁了！我的兄弟们，忠诚于巫妖王,重新召唤它！', `MaleText_loc5`='阿莎利水晶已經被摧毀了!我的兄弟們，忠誠於巫妖王,重新召喚它!', `MaleText_loc7`='¡Ha caído uno de los Cristales de Ash''ari! Manteneos fieles al Rey Exánime, hermanos míos, e intentad invocarlo de nuevo.', `FemaleText_loc1`='애쉬아리 수정 하나가 쓰러졌다! 형제들이여, 리치 왕에 대한 충성을 지켜 수정을 다시 소환하라!', `FemaleText_loc4`='阿莎利水晶已经被摧毁了！我的兄弟们，忠诚于巫妖王,重新召唤它！', `FemaleText_loc5`='阿莎利水晶已經被摧毀了!我的兄弟們，忠誠於巫妖王,重新召喚它!', `FemaleText_loc7`='¡Ha caído uno de los Cristales de Ash''ari! Manteneos fieles al Rey Exánime, hermanos míos, e intentad invocarlo de nuevo.' WHERE `ID`=6526;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='애쉬아리 수정 하나가 무너졌다! 도살장이 공격받기 전에 지구라트를 복원하라!', `MaleText_loc4`='一块阿莎利水晶已经被摧毁了！趁屠宰场处于易受攻击状态，赶快修复通灵塔！', `MaleText_loc5`='阿莎利水晶已經被摧毀了!在屠宰房遭到攻擊之前修復通靈塔!', `MaleText_loc7`='¡Un Cristal de Ash''ari se ha venido abajo! ¡Restaurad el zigurat antes de que El Degolladero sea vulnerable!', `FemaleText_loc1`='애쉬아리 수정 하나가 무너졌다! 도살장이 공격받기 전에 지구라트를 복원하라!', `FemaleText_loc4`='一块阿莎利水晶已经被摧毁了！趁屠宰场处于易受攻击状态，赶快修复通灵塔！', `FemaleText_loc5`='阿莎利水晶已經被摧毀了!在屠宰房遭到攻擊之前修復通靈塔!', `FemaleText_loc7`='¡Un Cristal de Ash''ari se ha venido abajo! ¡Restaurad el zigurat antes de que El Degolladero sea vulnerable!' WHERE `ID`=6527;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 소환이 끝났다! 애쉬아리 수정이 복원되었다!', `MaleText_loc4`='召唤已经完成！阿莎利水晶已经复原！', `MaleText_loc5`='召喚已經完成!阿莎利水晶已經復原!', `MaleText_loc7`='¡La invocación ha terminado! ¡Los Cristales de Ash''ari han sido restaurados!', `FemaleText_loc1`='우리의 소환이 끝났다! 애쉬아리 수정이 복원되었다!', `FemaleText_loc4`='召唤已经完成！阿莎利水晶已经复原！', `FemaleText_loc5`='召喚已經完成!阿莎利水晶已經復原!', `FemaleText_loc7`='¡La invocación ha terminado! ¡Los Cristales de Ash''ari han sido restaurados!' WHERE `ID`=6528;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성공이다! 애쉬아리 수정이 복원되었다!', `MaleText_loc4`='我们胜利了！阿莎利水晶已经修复！', `MaleText_loc5`='我們勝利了!阿莎利水晶已經修復!', `MaleText_loc7`='¡Hemos tenido éxito! ¡Los Cristales de Ash''ari han sido restaurados!', `FemaleText_loc1`='성공이다! 애쉬아리 수정이 복원되었다!', `FemaleText_loc4`='我们胜利了！Ash''ari Crystal 已经修复！', `FemaleText_loc5`='我們勝利了!阿莎利水晶已經修復!', `FemaleText_loc7`='¡Hemos tenido éxito! ¡Los Cristales de Ash''ari han sido restaurados!' WHERE `ID`=6529;
