UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 잠깐 쉬었다 가도 되겠소?', `MaleText_loc4`='如果我在这里稍微呆一会儿，你不会介意吧？', `MaleText_loc5`='如果我在這裡稍微待一會兒，你不會介意吧?', `MaleText_loc7`='¿No te importa que me detenga aquí un segundo, verdad?' WHERE `ID`=6545;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가마솥을 수호하기 위해 어둠 속에서 %s|1이;가; 나타납니다!', `MaleText_loc4`='%s从阴影中现身保护锅炉！', `MaleText_loc5`='%s從陰影中出現來保護鍋爐!', `MaleText_loc7`='%s emerge de las sombras para defender la caldera.' WHERE `ID`=6546;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 지역에는 아직도 스컬지의 역병이 만연해 있고 역병을 변형시켜 스컬지에 영향을 주기까지는 아직 한참이나 남았습니다. 필요한 재료를 모아 전쟁에 도움을 주십시오!', `MaleText_loc4`='亡灵天灾带来的灾难还在这片区域蔓延，在扭转局面，摧毁亡灵天灾之前，我们要走的路还很长。收集必要的资源，尽力帮助我们吧！', `MaleText_loc5`='天譴軍團帶來的災難還在這片區域蔓延，在扭轉局面，摧毀天譴軍團之前，我們要走的路還很長。收集必要的資源，盡力幫助我們吧!', `MaleText_loc7`='La peste de la Plaga sigue controlando la zona y todavía nos queda un largo camino antes de que el mal esté lo suficientemente alterado como para influir en ellos. ¡Reúne los ingredientes necesarios y ayuda en el esfuerzo de guerra!', `FemaleText_loc1`='이 지역에는 아직도 스컬지의 역병이 만연해 있고 역병을 변형시켜 스컬지에 영향을 주기까지는 아직 한참이나 남았습니다. 필요한 재료를 모아 전쟁에 도움을 주십시오!', `FemaleText_loc4`='亡灵天灾带来的灾难还在这片区域蔓延，在扭转局面，摧毁亡灵天灾之前，我们要走的路还很长。收集必要的资源，尽力帮助我们吧！', `FemaleText_loc5`='天譴軍團帶來的災難還在這片區域蔓延，在扭轉局面，摧毀天譴軍團之前，我們要走的路還很長。收集必要的資源，盡力幫助我們吧!', `FemaleText_loc7`='La peste de la Plaga sigue controlando la zona y todavía nos queda un largo camino antes de que el mal esté lo suficientemente alterado como para influir en ellos. ¡Reúne los ingredientes necesarios y ayuda en el esfuerzo de guerra!' WHERE `ID`=6547;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 이 지역 내의 역병 상황을 판단하는 데 어려움을 겪고 있습니다. 잠시 후에 다시 오시면 상황을 좀 더 명확하게 파악하고 있을지도 모르겠군요.', `MaleText_loc4`='我们在确定这片区域的状况时遇到了困难；快去核对一下，或许我们能得出一个较好的结论。', `MaleText_loc5`='我們在確定這片區域的瘟疫狀況時遇到了困難;快去核對一下，或許我們能得出一個較好的結論。', `MaleText_loc7`='Tenemos problemas para determinar el estado de la peste en la zona; vuelve a comprobarlo de inmediato y tal vez podamos hacernos con una idea más clara.', `FemaleText_loc1`='우리는 이 지역 내의 역병 상황을 판단하는 데 어려움을 겪고 있습니다. 잠시 후에 다시 오시면 상황을 좀 더 명확하게 파악하고 있을지도 모르겠군요.', `FemaleText_loc4`='我们在确定这片区域的状况时遇到了困难；快去核对一下，或许我们能得出一个较好的结论。', `FemaleText_loc5`='我們在確定這片區域的瘟疫狀況時遇到了困難;快去核對一下，或許我們能得出一個較好的結論。', `FemaleText_loc7`='Tenemos problemas para determinar el estado de la peste en la zona; vuelve a comprobarlo de inmediato y tal vez podamos hacernos con una idea más clara.' WHERE `ID`=6548;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스컬지의 역병이 거의 전환 단계에 이르렀습니다. 조금만 더 가마솥 전복을 시도하면 우리가 우세해지게 될 겁니다! 당신도 도와 주십시오!', `MaleText_loc4`='亡灵天灾带来的灾难就快结束；一场难以控制的颠覆行动会将我们推向顶峰！你务必要帮助我们！', `MaleText_loc5`='天譴軍團帶來的災難就快結束;一場難以控制的顛覆行動會將我們推向頂峰!你務必要幫助我們!', `MaleText_loc7`='La peste de la Plaga casi ha alcanzado su punto decisivo; ¡en cuanto alteremos unas cuantas calderas más lo habremos conseguido! ¡Haz lo que puedas para ayudar!', `FemaleText_loc1`='스컬지의 역병이 거의 전환 단계에 이르렀습니다. 조금만 더 가마솥 전복을 시도하면 우리가 우세해지게 될 겁니다! 당신도 도와 주십시오!', `FemaleText_loc4`='亡灵天灾带来的灾难就快结束；一场难以控制的颠覆行动会将我们推向顶峰！你务必要帮助我们！', `FemaleText_loc5`='天譴軍團帶來的災難就快結束;一場難以控制的顛覆行動會將我們推向頂峰!你務必要幫助我們!', `FemaleText_loc7`='La peste de la Plaga casi ha alcanzado su punto decisivo; ¡en cuanto alteremos unas cuantas calderas más lo habremos conseguido! ¡Haz lo que puedas para ayudar!' WHERE `ID`=6549;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스컬지의 역병을 스컬지에게 역이용하기 시작했지만 아직은 미약한 수준입니다. 녀석들의 가마솥을 전복시켜 우리를 도와 주십시오!', `MaleText_loc4`='我们已经开始反攻亡灵天灾了，但是我们撑不了多久了！去摧毁他们的锅炉吧！', `MaleText_loc5`='我們已經用天譴軍團的瘟疫反攻他們了，但是我們撐不了多久了!去摧毀他們的鍋爐吧!', `MaleText_loc7`='¡Hemos empezado a volver la peste de la Plaga en su contra, pero nuestra posición es muy delicada! ¡Asegúrate de apoyar nuestra causa destruyendo sus calderas!', `FemaleText_loc1`='스컬지의 역병을 스컬지에게 역이용하기 시작했지만 아직은 미약한 수준입니다. 녀석들의 가마솥을 전복시켜 우리를 도와 주십시오!', `FemaleText_loc4`='我们已经开始反攻亡灵天灾了，但是我们撑不了多久了！去摧毁他们的锅炉吧！', `FemaleText_loc5`='我們已經用天譴軍團的瘟疫反攻他們了，但是我們撐不了多久了!去摧毀他們的鍋爐吧!', `FemaleText_loc7`='¡Hemos empezado a volver la peste de la Plaga en su contra, pero nuestra posición es muy delicada! ¡Asegúrate de apoyar nuestra causa destruyendo sus calderas!' WHERE `ID`=6550;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 스컬지를 제압하고 있습니다. 변형된 역병의 효과는 적어도 만 하루 동안 더 지속될 것입니다! 하지만 계속해서 우세를 유지해야 하니 기회가 오면 꼭 가마솥 하나를 파괴해 주십시오.', `MaleText_loc4`='我们正控制着亡灵天灾——至少还会侵扰它们一整天时间！但是我们得对此有足够的把握，因此你要尽可能地破坏锅炉。', `MaleText_loc5`='我們正控制著天譴軍團─瘟疫至少還會侵擾它們一整天時間!但是我們得對此有足夠的把握，因此你要盡可能地破壞鍋爐。', `MaleText_loc7`='Estamos dominando la Plaga, ¡estarán bajo los efectos de la peste alterada al menos un día más! Pero tenemos que seguir esforzándonos, asegúrate de sabotear las calderas que puedas.', `FemaleText_loc1`='우리가 스컬지를 제압하고 있습니다. 변형된 역병의 효과는 적어도 만 하루 동안 더 지속될 것입니다! 하지만 계속해서 우세를 유지해야 하니 기회가 오면 꼭 가마솥 하나를 파괴해 주십시오.', `FemaleText_loc4`='我们正控制着亡灵天灾——至少还会侵扰它们一整天时间！但是我们得对此有足够的把握，因此你要尽可能地破坏锅炉。', `FemaleText_loc5`='我們正控制著天譴軍團─瘟疫至少還會侵擾它們一整天時間!但是我們得對此有足夠的把握，因此你要盡可能地破壞鍋爐。', `FemaleText_loc7`='Estamos dominando la Plaga, ¡estarán bajo los efectos de la peste alterada al menos un día más! Pero tenemos que seguir esforzándonos, asegúrate de sabotear las calderas que puedas.' WHERE `ID`=6551;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가마솥 전복을 위한 전투는 어떻게 돼가고 있습니까?', `MaleText_loc4`='我们破坏大熔炉的战斗进行得怎么样了？', `MaleText_loc5`='我們破壞大熔爐的戰鬥進行得怎麼樣了?', `MaleText_loc7`='¿Cómo va nuestra lucha por destruir las calderas?', `FemaleText_loc1`='가마솥 전복을 위한 전투는 어떻게 돼가고 있습니까?', `FemaleText_loc4`='我们破坏大熔炉的战斗进行得怎么样了？', `FemaleText_loc5`='我們破壞大熔爐的戰鬥進行得怎麼樣了?', `FemaleText_loc7`='¿Cómo va nuestra lucha por destruir las calderas?' WHERE `ID`=6552;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 반작용 물질을 내뿜기 시작하는가 싶더니 이내 멈춥니다.', `MaleText_loc4`='%s在向空中释放反作用试剂时停止了移动。', `MaleText_loc5`='%s在它開始向空中釋放反作用試劑時停止移動。', `MaleText_loc7`='%s se detiene cuando el contraagente comienza a liberarse por el aire.' WHERE `ID`=6553;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='땅문서는 내 겁니다, 형님! 내 앞길을 가로막지 못하도록 곧 영원히 제거해 드리지요!', `MaleText_loc4`='兄弟，这些契约是我的！很快你就将永远从我眼前消失了！', `MaleText_loc5`='兄弟，這些契約是我的!很快你就將永遠從我眼前消失了!', `MaleText_loc7`='¡Las escrituras son mías, hermano! ¡Pronto estarás fuera de mi camino para siempre!' WHERE `ID`=6554;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='재산은 내 거야, 알렉시! 곧 너를 끝장내 주마!', `MaleText_loc4`='奥蕾西娅，这些财宝是我的！你准备死吧！', `MaleText_loc5`='奧蕾西婭，這些財寶是我的!你準備死吧!', `MaleText_loc7`='¡La suerte está de mi lado, Alexi! ¡Se acerca tu fin!' WHERE `ID`=6555;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소타르라는 상급 사냥꾼이 있긴 하지. 칼바위 언덕 남서쪽에 있는 지하실 안에서 찾아보게.', `MaleText_loc4`='猎人训练者名叫索塔尔。去剃刀岭西南部的洞穴中找他吧。', `MaleText_loc5`='那位獵人訓練師名字叫索塔爾。去剃刀嶺西南部的洞穴中找他吧。', `MaleText_loc7`='El nombre del instructor de cazadores es Thotar. Búscale en su madriguera al suroeste de Cerrotajo.', `FemaleText_loc1`='소타르라는 상급 사냥꾼이 있긴 하지. 칼바위 언덕 남서쪽에 있는 지하실 안에서 찾아보게.', `FemaleText_loc4`='猎人训练者名叫索塔尔。去剃刀岭西南部的洞穴中找他吧。', `FemaleText_loc5`='那位獵人訓練師名字叫索塔爾。去剃刀嶺西南部的洞穴中找他吧。', `FemaleText_loc7`='El nombre del instructor de cazadores es Thotar. Búscale en su madriguera al suroeste de Cerrotajo.' WHERE `ID`=6556;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네도 사냥꾼인가? 어쨌든, 칼바위 언덕 남서쪽에 있는 어두컴컴한 지하실에서 태양을 피하고 있는 소타르를 찾아가 봐.', `MaleText_loc4`='你是个猎人？你会发现索塔尔为了躲避太阳就藏在城镇西南角上的洞穴里。', `MaleText_loc5`='你是個獵人?你會發現索塔爾為了躲避太陽就藏在城鎮西南角上的洞穴裡。', `MaleText_loc7`='¿Eres un cazador? Muy bien, encontrarás a Thotar escondido del sol en su madriguera, en el suroeste de la ciudad.', `FemaleText_loc1`='자네도 사냥꾼인가? 어쨌든, 칼바위 언덕 남서쪽에 있는 어두컴컴한 지하실에서 태양을 피하고 있는 소타르를 찾아가 봐.', `FemaleText_loc4`='你是个猎人？你会发现索塔尔为了躲避太阳就藏在城镇西南角上的洞穴里。', `FemaleText_loc5`='你是個獵人?你會發現索塔爾為了躲避太陽就藏在城鎮西南角上的洞穴裡。', `FemaleText_loc7`='¿Eres un cazador? Muy bien, encontrarás a Thotar escondido del sol en su madriguera, en el suroeste de la ciudad.' WHERE `ID`=6557;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='남쪽에 있는 센진 마을로 가서 운투와와 얘기해 보게.', `MaleText_loc4`='去南方的森金村，找安苏瓦谈谈。', `MaleText_loc5`='去南方的森金村，找安蘇瓦談談。', `MaleText_loc7`='Habla con Un''Thuwa, al sur del Poblado Sen''jin.', `FemaleText_loc1`='남쪽에 있는 센진 마을로 가서 운투와와 얘기해 보게.', `FemaleText_loc4`='去南方的森金村，找安苏瓦谈谈。', `FemaleText_loc5`='去南方的森金村，找安蘇瓦談談。', `FemaleText_loc7`='Habla con Un''Thuwa, al sur del Poblado Sen''jin.' WHERE `ID`=6558;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='트롤에게 가봐. 남쪽에 있는 센진 마을로 가서 운투와를 찾아보게.', `MaleText_loc4`='那是巨魔的事儿。去南方的森金村找安苏瓦。', `MaleText_loc5`='那是食人妖的事兒。去南方的森金村找安蘇瓦。', `MaleText_loc7`='Eso es asunto de los trols. Busca a Un''Thuwa en el Poblado Sen''jin hacia el Sur.', `FemaleText_loc1`='트롤에게 가봐. 남쪽에 있는 센진 마을로 가서 운투와를 찾아보게.', `FemaleText_loc4`='那是巨魔的事儿。去南方的森金村找安苏瓦。', `FemaleText_loc5`='那是食人妖的事兒。去南方的森金村找安蘇瓦。', `FemaleText_loc7`='Eso es asunto de los trols. Busca a Un''Thuwa en el Poblado Sen''jin hacia el Sur.' WHERE `ID`=6559;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타이진을 찾고 있군. 칼바위 언덕 동쪽에 있는 병영에서 찾아보게.', `MaleText_loc4`='你应该是在寻找泰金。在城镇东面的兵营里可以找到她。', `MaleText_loc5`='你應該是在尋找泰金。在城鎮東面的兵營裡可以找到她。', `MaleText_loc7`='Buscas a Tai''jin. La podrás encontrar en los cuarteles de la parte oriental de la ciudad.', `FemaleText_loc1`='타이진을 찾고 있군. 칼바위 언덕 동쪽에 있는 병영에서 찾아보게.', `FemaleText_loc4`='你应该是在寻找泰金。在城镇东面的兵营里可以找到她。', `FemaleText_loc5`='你應該是在尋找泰金。在城鎮東面的兵營裡可以找到她。', `FemaleText_loc7`='Buscas a Tai''jin. La podrás encontrar en los cuarteles de la parte oriental de la ciudad.' WHERE `ID`=6560;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타이진이라고 하는 여자를 찾아가보게. 칼바위 언덕 동쪽에 있는 병영 안에 있을 게야. 당신에게 신을 공경하는 법을 가르쳐 줄걸. 단, 당신이 그녀를 공경하는 태도를 보일 때의 얘기지.', `MaleText_loc4`='她名叫泰金，你可以在剃刀岭东面的兵营中找到她。她会教你如何尊敬神灵的。作为回报，你必须向她表示尊重。', `MaleText_loc5`='她名叫泰金，你可以在剃刀嶺東面的兵營中找到她。她會教你如何尊敬神靈的。作為回報，你必須向她表示尊重。', `MaleText_loc7`='Su nombre es Tai''jin y la encontrarás dentro de los cuarteles, en la parte oriental de Cerrotajo. Te enseñará a respetar a los dioses. A cambio, ¡asegúrate de mostrarle el respeto debido!', `FemaleText_loc1`='타이진이라고 하는 여자를 찾아가보게. 칼바위 언덕 동쪽에 있는 병영 안에 있을 게야. 당신에게 신을 공경하는 법을 가르쳐 줄걸. 단, 당신이 그녀를 공경하는 태도를 보일 때의 얘기지.', `FemaleText_loc4`='她名叫泰金，你可以在剃刀岭东面的兵营中找到她。她会教你如何尊敬神灵的。作为回报，你必须向她表示尊重。', `FemaleText_loc5`='她名叫泰金，你可以在剃刀嶺東面的兵營中找到她。她會教你如何尊敬神靈的。作為回報，你必須向她表示尊重。', `FemaleText_loc7`='Su nombre es Tai''jin y la encontrarás dentro de los cuarteles, en la parte oriental de Cerrotajo. Te enseñará a respetar a los dioses. A cambio, ¡asegúrate de mostrarle el respeto debido!' WHERE `ID`=6561;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카플라크와 얘기해 보게. 칼바위 언덕 남서쪽에 있는 지하실 위에 서 있을 거야.', `MaleText_loc4`='到村庄西南方的洞穴顶部找到卡普拉克。', `MaleText_loc5`='到村莊西南方的洞穴頂部找到卡普拉克。', `MaleText_loc7`='Encuentra a Kaplak encima de la madriguera, en la sección suroeste de la ciudad.', `FemaleText_loc1`='카플라크와 얘기해 보게. 칼바위 언덕 남서쪽에 있는 지하실 위에 서 있을 거야.', `FemaleText_loc4`='到村庄西南方的洞穴顶部找到卡普拉克。', `FemaleText_loc5`='到村莊西南方的洞穴頂部找到卡普拉克。', `FemaleText_loc7`='Encuentra a Kaplak encima de la madriguera, en la sección suroeste de la ciudad.' WHERE `ID`=6562;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카플라크는 왜 찾는 겐가? 뭐, 그야 내가 신경 쓸 일은 아니지만. 칼바위 언덕 남서쪽에 있는 지하실 위를 찾아보게. 그를 만나면 가방 단속은 단단히 하도록 하게.', `MaleText_loc4`='你为什么想找卡普拉克谈谈？没关系。到剃刀岭西南角的洞穴顶部找他。不过你一定不要把手放错地方！', `MaleText_loc5`='你為什麼想找卡普拉克談談?沒關係。到剃刀嶺西南角的洞穴頂部找他。不過你一定不要把手放錯地方!', `MaleText_loc7`='¿Por qué querrías hablar con Kaplak? Es igual. Búscalo encima de la madriguera que hay al suroeste de Cerrotajo. ¡Pero procura mantener las manos quietas!', `FemaleText_loc1`='카플라크는 왜 찾는 겐가? 뭐, 그야 내가 신경 쓸 일은 아니지만. 칼바위 언덕 남서쪽에 있는 지하실 위를 찾아보게. 그를 만나면 가방 단속은 단단히 하도록 하게.', `FemaleText_loc4`='你为什么想找卡普拉克谈谈？没关系。到剃刀岭西南角的洞穴顶部找他。不过你一定不要把手放错地方！', `FemaleText_loc5`='你為什麼想找卡普拉克談談?沒關係。到剃刀嶺西南角的洞穴頂部找他。不過你一定不要把手放錯地方!', `FemaleText_loc7`='¿Por qué querrías hablar con Kaplak? Es igual. Búscalo encima de la madriguera que hay al suroeste de Cerrotajo. ¡Pero procura mantener las manos quietas!' WHERE `ID`=6563;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스워트를 찾아가야 해. 칼바위 언덕 동쪽에 있는 병영 안에서 찾아보게.', `MaleText_loc4`='你应该去找斯瓦特。到剃刀岭东边的兵营里找找看。', `MaleText_loc5`='你應該去找斯瓦特。到剃刀嶺東邊的兵營裡找找看。', `MaleText_loc7`='Debes encontrar a Swart. Búscalo en los cuarteles, en el lado oriental de Cerrotajo.', `FemaleText_loc1`='스워트를 찾아가야 해. 칼바위 언덕 동쪽에 있는 병영 안에서 찾아보게.', `FemaleText_loc4`='你应该去找斯瓦特。到剃刀岭东边的兵营里找找看。', `FemaleText_loc5`='你應該去找斯瓦特。到剃刀嶺東邊的兵營裡找找看。', `FemaleText_loc7`='Debes encontrar a Swart. Búscalo en los cuarteles, en el lado oriental de Cerrotajo.' WHERE `ID`=6564;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장님이 주도하고 계시는 개혁의 바람은 분명 호드에게 승리를 안겨 줄 거야! 참, 주술사라고? 마을 동쪽에 있는 병영 안에서 스워트를 찾게.', `MaleText_loc4`='酋长进行的变革将帮助部落取得胜利！去城镇东边的兵营找斯瓦特吧。', `MaleText_loc5`='大酋長進行的變革將幫助部落取得勝利!去城鎮東邊的兵營找斯瓦特吧。', `MaleText_loc7`='¡El Jefe de Guerra introduce cambios que darán la victoria a la Horda! Busca a Swart en los cuarteles en la parte oriental de la ciudad.', `FemaleText_loc1`='대족장님이 주도하고 계시는 개혁의 바람은 분명 호드에게 승리를 안겨 줄 거야! 참, 주술사라고? 마을 동쪽에 있는 병영 안에서 스워트를 찾게.', `FemaleText_loc4`='酋长进行的变革将帮助部落取得胜利！去城镇东边的兵营找斯瓦特吧。', `FemaleText_loc5`='大酋長進行的變革將幫助部落取得勝利!去城鎮東邊的兵營找斯瓦特吧。', `FemaleText_loc7`='¡El Jefe de Guerra introduce cambios que darán la victoria a la Horda! Busca a Swart en los cuarteles en la parte oriental de la ciudad.' WHERE `ID`=6565;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼바위 언덕 동쪽, 병영 뒤편으로 가게. 두그루 고어러스트를 찾아.', `MaleText_loc4`='你能在剃刀岭东面的兵营后找到杜格鲁·血怒。', `MaleText_loc5`='你能在剃刀嶺東面的兵營後找到杜格魯·血怒。', `MaleText_loc7`='En la parte oriental de Cerrotajo, detrás de los cuarteles, encontrarás a Dhugru Ansiagore.', `FemaleText_loc1`='칼바위 언덕 동쪽, 병영 뒤편으로 가게. 두그루 고어러스트를 찾아.', `FemaleText_loc4`='你能在剃刀岭东面的兵营后找到杜格鲁·血怒。', `FemaleText_loc5`='你能在剃刀嶺東面的兵營後找到杜格魯·血怒。', `FemaleText_loc7`='En la parte oriental de Cerrotajo, detrás de los cuarteles, encontrarás a Dhugru Ansiagore.' WHERE `ID`=6566;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두그루 고어러스트는 마을 동쪽에 있는 병영 뒤편에 숨어 있지. 그는 왜 찾는가? 당신 혹시 불타는 군단과 한통속이야? 그런 일은 없길 바라네. 그렇다면 내 손으로 당신을 체포해야 하니까 말이야.', `MaleText_loc4`='杜格鲁·血怒在城镇东边的兵营后面。不要让我发觉你跟燃烧军团是一伙的！', `MaleText_loc5`='杜格魯·血怒在城鎮東邊的兵營後面。不要讓我發覺你跟燃燒軍團是一夥的!', `MaleText_loc7`='Dhugru Ansiagore se esconde detrás de los cuarteles de la parte oriental de la ciudad. ¡No me digas que eres un aliado de la Legión Ardiente!', `FemaleText_loc1`='두그루 고어러스트는 마을 동쪽에 있는 병영 뒤편에 숨어 있지. 그는 왜 찾는가? 당신 혹시 불타는 군단과 한통속이야? 그런 일은 없길 바라네. 그렇다면 내 손으로 당신을 체포해야 하니까 말이야.', `FemaleText_loc4`='杜格鲁·血怒在城镇东边的兵营后面。不要让我发觉你跟燃烧军团是一伙的！', `FemaleText_loc5`='杜格魯·血怒在城鎮東邊的兵營後面。不要讓我發覺你跟燃燒軍團是一夥的!', `FemaleText_loc7`='Dhugru Ansiagore se esconde detrás de los cuarteles de la parte oriental de la ciudad. ¡No me digas que eres un aliado de la Legión Ardiente!' WHERE `ID`=6567;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼바위 언덕 동쪽에 있는 병영에서 타쇼 재기드스카를 찾아보게.', `MaleText_loc4`='去城镇东面的兵营找塔绍尔·锯痕。', `MaleText_loc5`='去城鎮東面的兵營找塔紹爾·鋸痕。', `MaleText_loc7`='Busca a Tarshaw Marcauna en los cuarteles, en la parte oriental de la ciudad.', `FemaleText_loc1`='칼바위 언덕 동쪽에 있는 병영에서 타쇼 재기드스카를 찾아보게.', `FemaleText_loc4`='去城镇东面的兵营找塔绍尔·锯痕。', `FemaleText_loc5`='去城鎮東面的兵營找塔紹爾·鋸痕。', `FemaleText_loc7`='Busca a Tarshaw Marcauna en los cuarteles, en la parte oriental de la ciudad.' WHERE `ID`=6568;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼바위 언덕 동쪽에 있는 병영 안에서 타쇼 재기드스카를 찾아보게. 호드의 젊은이들에게 자부심과 명예를 가져다주기를!', `MaleText_loc4`='到剃刀岭东面的兵营里找到塔绍尔·锯痕。给部落的年轻人带去骄傲和荣誉！', `MaleText_loc5`='到剃刀嶺東面的兵營裡找到塔紹爾·鋸痕。給部落的年輕人帶去驕傲和榮譽!', `MaleText_loc7`='Encuentra a Tarshaw Marcauna en los cuarteles de la parte oriental de Cerrotajo. ¡Procura honor a la Horda joven!', `FemaleText_loc1`='칼바위 언덕 동쪽에 있는 병영 안에서 타쇼 재기드스카를 찾아보게. 호드의 젊은이들에게 자부심과 명예를 가져다주기를!', `FemaleText_loc4`='到剃刀岭东面的兵营里找到塔绍尔·锯痕。给部落的年轻人带去骄傲和荣誉！', `FemaleText_loc5`='到剃刀嶺東面的兵營裡找到塔紹爾·鋸痕。給部落的年輕人帶去驕傲和榮譽!', `FemaleText_loc7`='Encuentra a Tarshaw Marcauna en los cuarteles de la parte oriental de Cerrotajo. ¡Procura honor a la Horda joven!' WHERE `ID`=6569;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='남쪽에 있는 센진 마을로 가서 미아오잔을 찾아보게.', `MaleText_loc4`='去南方的森金村找米奥赞。', `MaleText_loc5`='去南方的森金村找米奧贊。', `MaleText_loc7`='Busca a Miao''zan en Poblado Sen''jin, hacia el Sur.', `FemaleText_loc1`='남쪽에 있는 센진 마을로 가서 미아오잔을 찾아보게.', `FemaleText_loc4`='去南方的森金村找米奥赞。', `FemaleText_loc5`='去南方的森金村找米奧贊。', `FemaleText_loc7`='Busca a Miao''zan en Poblado Sen''jin, hacia el Sur.' WHERE `ID`=6570;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='센진 마을에는 미아오잔이라고 하는 트롤이 물약을 제조한다더군. 그곳에 가보지그래.', `MaleText_loc4`='我听说森金村的巨魔中有个名叫米奥赞的药剂师。去那儿找他吧。', `MaleText_loc5`='我聽說森金村的食人妖中有個名叫米奧贊的藥劑師。去那兒找他吧。', `MaleText_loc7`='He oído que los trols de Poblado Sen''jin tienen un fabricante de pociones llamado Miao''zan. Busca ahí.', `FemaleText_loc1`='센진 마을에는 미아오잔이라고 하는 트롤이 물약을 제조한다더군. 그곳에 가보지그래.', `FemaleText_loc4`='我听说森金村的巨魔中有个名叫米奥赞的药剂师。去那儿找他吧。', `FemaleText_loc5`='我聽說森金村的食人妖中有個名叫米奧贊的藥劑師。去那兒找他吧。', `FemaleText_loc7`='He oído que los trols de Poblado Sen''jin tienen un fabricante de pociones llamado Miao''zan. Busca ahí.' WHERE `ID`=6571;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드우크 말이로군. 칼바위 언덕 북서쪽에 있는 가열로 옆에서 일하고 있을 거야.', `MaleText_loc4`='那是杜克。去城镇西北角炙热的熔炉附近找他。', `MaleText_loc5`='那是杜克。去城鎮西北角炙熱的熔爐附近找他。', `MaleText_loc7`='Será Dwukk. Búscalo junto a la fundición en la parte noroeste de la ciudad.', `FemaleText_loc1`='드우크 말이로군. 칼바위 언덕 북서쪽에 있는 가열로 옆에서 일하고 있을 거야.', `FemaleText_loc4`='那是杜克。去城镇西北角炙热的熔炉附近找他。', `FemaleText_loc5`='那是杜克。去城鎮西北角炙熱的熔爐附近找他。', `FemaleText_loc7`='Será Dwukk. Búscalo junto a la fundición en la parte noroeste de la ciudad.' WHERE `ID`=6572;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스스로 호드를 위한 무기와 방어구를 만들기 위해, 단단한 금속을 두드릴 힘이 있다고 생각이 들거든, 칼바위 언덕의 북서쪽으로 가게. 가열로 옆에 있는 드우크를 찾아가.', `MaleText_loc4`='如果你认为自己有能力为部落打造武器，就去剃刀岭西北部，炙热的熔炉旁找杜克。', `MaleText_loc5`='如果你認為自己有能力為部落打造武器，就去剃刀嶺西北部，炙熱的熔爐旁找杜克。', `MaleText_loc7`='Si crees que tienes la fuerza para convertir metal en armas y armaduras para la Horda busca a Dwukk junto a la fundición del noroeste de Cerrotajo.', `FemaleText_loc1`='스스로 호드를 위한 무기와 방어구를 만들기 위해, 단단한 금속을 두드릴 힘이 있다고 생각이 들거든, 칼바위 언덕의 북서쪽으로 가게. 가열로 옆에 있는 드우크를 찾아가.', `FemaleText_loc4`='如果你认为自己有能力为部落打造武器，就去剃刀岭西北部，灼热的熔炉旁找杜克。', `FemaleText_loc5`='如果你認為自己有能力為部落打造武器，就去剃刀嶺西北部，灼熱的熔爐旁找杜克。', `FemaleText_loc7`='Si crees que tienes la fuerza para convertir metal en armas y armaduras para la Horda busca a Dwukk junto a la fundición del noroeste de Cerrotajo.' WHERE `ID`=6573;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='북쪽으로 난 길을 따라 오그리마로 가게. 그곳 그런트에게 어디로 가면 요리를 배울 수 있는지 다시 한번 물어보게.', `MaleText_loc4`='沿着北边的道路去奥格瑞玛。你可以问问那儿的守卫烹饪训练师在哪儿。', `MaleText_loc5`='沿著北邊的道路去奧格瑪。你可以問問那兒的守衛烹飪訓練師在哪兒。', `MaleText_loc7`='Sigue hacia el norte el camino de Orgrimmar. Puedes preguntar a uno de los Brutos por las señas del instructor de cocina.', `FemaleText_loc1`='북쪽으로 난 길을 따라 오그리마로 가게. 그곳 그런트에게 어디로 가면 요리를 배울 수 있는지 다시 한번 물어보게.', `FemaleText_loc4`='沿着北边的道路去奥格瑞玛。你可以问问那儿的守卫烹饪训练师在哪儿。', `FemaleText_loc5`='沿著北邊的道路去奧格瑪。你可以問問那兒的守衛烹飪訓練師在哪兒。', `FemaleText_loc7`='Sigue hacia el norte el camino de Orgrimmar. Puedes preguntar a uno de los Brutos por las señas del instructor de cocina.' WHERE `ID`=6574;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엄... 요리 말인가? 북쪽에 있는 오그리마로 가야겠군. 그리 멀지는 않지. 그곳에 도착하면 그런트에게 다시 한번 물어봐야 할 거야.', `MaleText_loc4`='嗯……食物。旅途并不遥远，你需要朝北走，去奥格瑞玛，问问那儿的守卫。', `MaleText_loc5`='嗯...食物。旅途並不遙遠，你需要朝北走，去奧格瑪，問問那兒的守衛。', `MaleText_loc7`='Ummmm... comida. No está muy lejos, pero debes ir hacia el Norte, a Orgrimmar. Cuando estés allí pregunta a uno de los Brutos.', `FemaleText_loc1`='엄... 요리 말인가? 북쪽에 있는 오그리마로 가야겠군. 그리 멀지는 않지. 그곳에 도착하면 그런트에게 다시 한번 물어봐야 할 거야.', `FemaleText_loc4`='嗯……食物。旅途并不遥远，你需要朝北走，去奥格瑞玛，问问那儿的守卫。', `FemaleText_loc5`='嗯...食物。旅途並不遙遠，你需要朝北走，去奧格瑪，問問那兒的守衛。', `FemaleText_loc7`='Ummmm... comida. No está muy lejos, pero debes ir hacia el Norte, a Orgrimmar. Cuando estés allí pregunta a uno de los Brutos.' WHERE `ID`=6575;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오그리마에 한 명 있지. 그곳에 있는 그런트가 길을 더 자세히 가르쳐 줄 거야. 여기서 길을 따라 북쪽으로 가기만 하면 바로 보여.', `MaleText_loc4`='在奥格瑞玛有你要找的人。那儿的守卫会为你指明方向的。朝着北方的道路走，应该不会错过的。', `MaleText_loc5`='在奧格瑪有你要找的人。那兒的守衛會為你指明方向的。朝著北方的道路走，應該不會錯過的。', `MaleText_loc7`='Hay uno en Orgrimmar. Uno de los Brutos de la ciudad te ayudará con las señas. Sigue el camino hacia el Norte, no tiene pérdida.', `FemaleText_loc1`='오그리마에 한 명 있지. 그곳에 있는 그런트가 길을 더 자세히 가르쳐 줄 거야. 여기서 길을 따라 북쪽으로 가기만 하면 바로 보여.', `FemaleText_loc4`='在奥格瑞玛有你要找的人。那儿的守卫会为你指明方向的。朝着北方的道路走，应该不会错过的。', `FemaleText_loc5`='在奧格瑪有你要找的人。那兒的守衛會為你指明方向的。朝著北方的道路走，應該不會錯過的。', `FemaleText_loc7`='Hay uno en Orgrimmar. Uno de los Brutos de la ciudad te ayudará con las señas. Sigue el camino hacia el Norte, no tiene pérdida.' WHERE `ID`=6576;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 부근에 그런 일을 하는 자는 없네. 북쪽에 있는 오그리마에는 있을지도 모르지. 그곳 그런트에게 물어보는 게 제일 좋겠군.', `MaleText_loc4`='据我所知，附近没有这些训练师。你最好去北方的奥格瑞玛看看，去问问那儿的守卫。', `MaleText_loc5`='據我所知，附近沒有這些訓練師。你最好去北方的奧格瑪看看，去問問那兒的守衛。', `MaleText_loc7`='No tengo noticia de que haya uno de esos por aquí. Creo que lo mejor sería ir a Orgrimmar, al Norte, y hablar con uno de sus Brutos.', `FemaleText_loc1`='이 부근에 그런 일을 하는 자는 없네. 북쪽에 있는 오그리마에는 있을지도 모르지. 그곳 그런트에게 물어보는 게 제일 좋겠군.', `FemaleText_loc4`='据我所知，附近没有这些训练师。你最好去北方的奥格瑞玛看看，去问问那儿的守卫。', `FemaleText_loc5`='據我所知，附近沒有這些訓練師。你最好去北方的奧格瑪看看，去問問那兒的守衛。', `FemaleText_loc7`='No tengo noticia de que haya uno de esos por aquí. Creo que lo mejor sería ir a Orgrimmar, al Norte, y hablar con uno de sus Brutos.' WHERE `ID`=6577;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼바위 언덕에 전문 기계공학자가 한 명 있지. 머크드락이라고 하는데, 보통 가열로 근처에 볼 수 있다네.', `MaleText_loc4`='在剃刀岭居住着一名工程学训练师。他名叫穆德拉克，你在熔炉附近就能找到他。', `MaleText_loc5`='在剃刀嶺居住著一名工程學訓練師。他名叫穆德拉克，你在熔爐附近就能找到他。', `MaleText_loc7`='Hay un instructor de ingeniería en Cerrotajo. Se llama Mukdrak y suele encontrarse cerca de la fundición.', `FemaleText_loc1`='칼바위 언덕에 전문 기계공학자가 한 명 있지. 머크드락이라고 하는데, 보통 가열로 근처에 볼 수 있다네.', `FemaleText_loc4`='在剃刀岭居住着一名工程学训练师。他名叫穆德拉克，你在熔炉附近就能找到他。', `FemaleText_loc5`='在剃刀嶺居住著一名工程學訓練師。他名叫穆德拉克，你在熔爐附近就能找到他。', `FemaleText_loc7`='Hay un instructor de ingeniería en Cerrotajo. Se llama Mukdrak y suele encontrarse cerca de la fundición.' WHERE `ID`=6578;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흥, 그런 건 고블린이나 손을 대는 일인데! 뭐, 그래도 이 칼바위 언덕에도 그런 걸 가르쳐 줄 오크가 한 명 있긴 해. 가열로 근처에 있는 머크드락을 찾아보게.', `MaleText_loc4`='呸，那是地精的东西！在剃刀岭有一个兽人可以教你如何制作这些物品。去熔炉附近找穆德拉克吧。', `MaleText_loc5`='呸?￡是哥布林的東西!在剃刀嶺有一個獸人可以教你如何製作這些物品。去熔爐附近找穆德拉克吧。', `MaleText_loc7`='¡Bah, eso es trabajo goblin! Pero tenemos un orco aquí en Cerrotajo que podrá enseñarte esas cosas. Busca a Mukdrak cerca de la fundición.', `FemaleText_loc1`='흥, 그런 건 고블린이나 손을 대는 일인데! 뭐, 그래도 이 칼바위 언덕에도 그런 걸 가르쳐 줄 오크가 한 명 있긴 해. 가열로 근처에 있는 머크드락을 찾아보게.', `FemaleText_loc4`='呸，那是地精的东西！在剃刀岭有一个兽人可以教你如何制作这些物品。去熔炉附近找穆德拉克吧。', `FemaleText_loc5`='呸，那是哥布林的東西!在剃刀嶺有一個獸人可以教你如何製作這些物品。去熔爐附近找穆德拉克吧。', `FemaleText_loc7`='¡Bah, eso es trabajo goblin! Pero tenemos un orco aquí en Cerrotajo que podrá enseñarte esas cosas. Busca a Mukdrak cerca de la fundición.' WHERE `ID`=6579;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼바위 언덕 동쪽에 있는 병영 안으로 들어가보게. 로울크를 찾아.', `MaleText_loc4`='拉乌克就在剃刀岭东边的兵营中。', `MaleText_loc5`='拉烏克就在剃刀嶺東邊的兵營中。', `MaleText_loc7`='Hay uno de esos en los cuarteles, en la parte oriental de Cerrotajo. Pregunta por Rawrk.', `FemaleText_loc1`='칼바위 언덕 동쪽에 있는 병영 안으로 들어가보게. 로울크를 찾아.', `FemaleText_loc4`='拉乌克就在剃刀岭东边的兵营中。', `FemaleText_loc5`='拉烏克就在剃刀嶺東邊的兵營中。', `FemaleText_loc7`='Hay uno de esos en los cuarteles, en la parte oriental de Cerrotajo. Pregunta por Rawrk.' WHERE `ID`=6580;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 싸움을 많이 하는데 칼바위 언덕에 응급치료사가 없겠나? 동쪽에 있는 병영 안에서 로울크를 찾아보게.', `MaleText_loc4`='因为我们经常战斗，我们当然有一个急救训练师在剃刀岭。在城镇东面的兵营里可以找到拉乌克。', `MaleText_loc5`='因為我們經常戰鬥，我們當然有一個急救訓練師在剃刀嶺。在城鎮東面的兵營裡可以找到拉烏克。', `MaleText_loc7`='Con todos los combates que tenemos, por supuesto que tenemos un instructor de primeros auxilios en Cerrotajo. Busca a Rawrk en los cuarteles, en la parte oriental de la ciudad.', `FemaleText_loc1`='이렇게 싸움을 많이 하는데 칼바위 언덕에 응급치료사가 없겠나? 동쪽에 있는 병영 안에서 로울크를 찾아보게.', `FemaleText_loc4`='因为我们经常战斗，我们当然有一个急救训练师在剃刀岭。在城镇东面的兵营里可以找到拉乌克。', `FemaleText_loc5`='因為我們經常戰鬥，我們當然有一個急救訓練師在剃刀嶺。在城鎮東面的兵營裡可以找到拉烏克。', `FemaleText_loc7`='Con todos los combates que tenemos, por supuesto que tenemos un instructor de primeros auxilios en Cerrotajo. Busca a Rawrk en los cuarteles, en la parte oriental de la ciudad.' WHERE `ID`=6581;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='남쪽에 있는 검은창 해안에서 라우티키라는 트롤이 낚시를 하는 걸 본 적 있네. 센진 마을 바로 외곽에 있지.', `MaleText_loc4`='我曾见到一个名叫劳迪克的巨魔在暗矛海滩南部钓鱼，就在森金村的外围。', `MaleText_loc5`='我曾見到一個名叫勞迪克的食人妖在暗矛海灘南部釣魚，就在森金村的週邊。', `MaleText_loc7`='He visto a un trol llamado Lau''Tiki pescando hacia el Sur, en la Playa Lanza Negra, a las afueras de Poblado Sen''jin.', `FemaleText_loc1`='남쪽에 있는 검은창 해안에서 라우티키라는 트롤이 낚시를 하는 걸 본 적 있네. 센진 마을 바로 외곽에 있지.', `FemaleText_loc4`='我曾见到一个名叫劳迪克的巨魔在暗矛海滩南部钓鱼，就在森金村的外围。', `FemaleText_loc5`='我曾見到一個名叫勞迪克的食人妖在暗矛海灘南部釣魚，就在森金村的週邊。', `FemaleText_loc7`='He visto a un trol llamado Lau''Tiki pescando hacia el Sur, en la Playa Lanza Negra, a las afueras de Poblado Sen''jin.' WHERE `ID`=6582;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라우티키를 찾는군. 남쪽에 있는 센진 마을 바로 외곽에 있는 검은창 해안으로 가. 그곳에서 만날 수 있을 거야.', `MaleText_loc4`='你在寻找劳迪克。你会在南面的森金村外的暗矛海滩找到他。', `MaleText_loc5`='你在尋找勞迪克。你會在南面的森金村外的暗矛海灘找到他。', `MaleText_loc7`='Buscas a Lau''Tiki. Lo encontrarás en la Playa Lanza Negra, saliendo de Poblado Sen''jin hacia el Sur.', `FemaleText_loc1`='라우티키를 찾는군. 남쪽에 있는 센진 마을 바로 외곽에 있는 검은창 해안으로 가. 그곳에서 만날 수 있을 거야.', `FemaleText_loc4`='你在寻找劳迪克。你会在南面的森金村外的暗矛海滩找到他。', `FemaleText_loc5`='你在尋找勞迪克。你會在南面的森金村外的暗矛海灘找到他。', `FemaleText_loc7`='Buscas a Lau''Tiki. Lo encontrarás en la Playa Lanza Negra, saliendo de Poblado Sen''jin hacia el Sur.' WHERE `ID`=6583;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미시키를 찾고 있군. 남쪽에 있는 센진 마을로 가보게. 그녀의 오두막을 찾아.', `MaleText_loc4`='你在寻找米什基。她在森金村南面有一间小屋。', `MaleText_loc5`='你在尋找米什基。她在森金村南面有一間小屋。', `MaleText_loc7`='Buscas a Mishiki. Tiene una cabaña al sur de Poblado Sen''jin.', `FemaleText_loc1`='미시키를 찾고 있군. 남쪽에 있는 센진 마을로 가보게. 그녀의 오두막을 찾아.', `FemaleText_loc4`='你在寻找米什基。她在森金村南面有一间小屋。', `FemaleText_loc5`='你在尋找米什基。她在森金村南面有一間小屋。', `FemaleText_loc7`='Buscas a Mishiki. Tiene una cabaña al sur de Poblado Sen''jin.' WHERE `ID`=6584;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꽃이라고? 이런 황무지에서 말인가? 그런 걸 찾는 법을 가르쳐 줄 이가 호드에 있으려나? 아, 남쪽에 있는 센진 마을로 한번 가보게. 미시키라면 뭔가 알 거야.', `MaleText_loc4`='花？在这片荒芜的土地上？如果有人能教你如何找到它们，那就是南方的森金村的米什基。', `MaleText_loc5`='花?在這片荒蕪的土地上?如果有人能教你如何找到它們，那就是南方的森金村的米什基。', `MaleText_loc7`='¿Flores? ¿En este páramo? Si hay alguien que pueda enseñarte a encontrarlas, será Mishiki, al sur de Poblado Sen''jin.', `FemaleText_loc1`='꽃이라고? 이런 황무지에서 말인가? 그런 걸 찾는 법을 가르쳐 줄 이가 호드에 있으려나? 아, 남쪽에 있는 센진 마을로 한번 가보게. 미시키라면 뭔가 알 거야.', `FemaleText_loc4`='花？在这片荒芜的土地上？如果有人能教你如何找到它们，那就是南方的森金村的米什基。', `FemaleText_loc5`='花?在這片荒蕪的土地上?如果有人能教你如何找到它們，那就是南方的森金村的米什基。', `FemaleText_loc7`='¿Flores? ¿En este páramo? Si hay alguien que pueda enseñarte a encontrarlas, será Mishiki, al sur de Poblado Sen''jin.' WHERE `ID`=6585;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='물의 정령이시여, 찬미를 드립니다. 한 가지 청이 있습니다. $n의 탄원을 들으셨겠지요. 그 뜻이 숭고하다고 생각됩니다. 그러니 부디 우리를 도와 주십시오.', `FemaleText_loc4`='水之精灵，我赞美你，还有我想请你帮个忙。你听到$n的请求了，而我相信$g他的:她的;用意是高尚的。你愿意帮助我们吗？', `FemaleText_loc5`='水靈，我讚美你，還有我想請你幫個忙。你聽到$n的請求了，而我相信$g他的:她的;用意是高尚的。你願意幫助我們嗎?', `FemaleText_loc7`='Espíritus del Agua, alabados sean, ruego su favor. Han escuchado la súplica de $N y confío en la nobleza de sus propósitos. Por favor, ¿nos prestarán su ayuda?' WHERE `ID`=6586;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오그리마로 가야할 걸세. 칼바위 언덕에서 나가는 북쪽 길을 따라 협곡을 통과하면 오그리마에 이르게 되지. 그곳에서 그런트 중 한 명에게 길을 더 자세히 물어보게.', `MaleText_loc4`='为此你需要到奥格瑞玛去。只需沿着从剃刀岭出去的路穿过峡谷就会到达那里。到了那里,你可以问问步兵以得到进一步的指引。', `MaleText_loc5`='為此你需要到奧格瑪去。只需沿著從剃刀嶺往北出去的路，穿過峽谷就會到達那裡。到了那裡,你可以問問蠻兵以得到進一步的指引。', `MaleText_loc7`='Deberás dirigirte a Orgrimmar para eso. Sigue el camino que sale de Cerrotajo hacia el Norte, atravesando el cañón y llegarás a la ciudad. Cuando estés allí pide a uno de los Brutos más indicaciones.', `FemaleText_loc1`='오그리마로 가야할 걸세. 칼바위 언덕에서 나가는 북쪽 길을 따라 협곡을 통과하면 오그리마에 이르게 되지. 그곳에서 그런트 중 한 명에게 길을 더 자세히 물어보게.', `FemaleText_loc4`='为此你需要到奥格瑞玛去。只需沿着从剃刀岭出去的路穿过峡谷就会到达那里。到了那里,你可以问问步兵以得到进一步的指引。', `FemaleText_loc5`='為此你需要到奧格瑪去。只需沿著從剃刀嶺往北出去的路，穿過峽谷就會到達那裡。到了那裡,你可以問問蠻兵以得到進一步的指引。', `FemaleText_loc7`='Deberás dirigirte a Orgrimmar para eso. Sigue el camino que sale de Cerrotajo hacia el Norte, atravesando el cañón y llegarás a la ciudad. Cuando estés allí pide a uno de los Brutos más indicaciones.' WHERE `ID`=6587;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가죽세공을 배우려면 북쪽에 있는 오그리마로 가야 하네. 오그리마 그런트에게 물어보면, 가죽세공을 어디서 배울 수 있는지 가르쳐줄 걸세.', `MaleText_loc4`='要学习如何处理皮革，你得去北面的奥格瑞玛。那儿的守卫会告诉你如何找到制皮训练师的。', `MaleText_loc5`='要學習如何處理皮革，你得去北面的奧格瑪。奧格瑪蠻兵會告訴你如何找到製皮訓練師的。', `MaleText_loc7`='Para aprender a curtir pellejos y a trabajar con el cuero dirígete a Orgrimmar, al Norte. Uno de los Brutos de la ciudad podrá indicarte cómo llegar al instructor de peletería.', `FemaleText_loc1`='가죽세공을 배우려면 북쪽에 있는 오그리마로 가야 하네. 오그리마 그런트에게 물어보면, 가죽세공을 어디서 배울 수 있는지 가르쳐줄 걸세.', `FemaleText_loc4`='要学习如何处理皮革，你得去北面的奥格瑞玛。那儿的守卫会告诉你如何找到制皮训练师的。', `FemaleText_loc5`='要學習如何處理皮革，你得去北面的奧格瑪。奧格瑪蠻兵會告訴你如何找到製皮訓練師的。', `FemaleText_loc7`='Para aprender a curtir pellejos y a trabajar con el cuero dirígete a Orgrimmar, al Norte. Uno de los Brutos de la ciudad podrá indicarte cómo llegar al instructor de peletería.' WHERE `ID`=6588;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론, 이 칼바위 언덕에 광부 하나쯤은 살고 있지. 북서쪽 여관 옆에서 크룬을 찾아보게.', `MaleText_loc4`='当然，当然。城镇中有一名采矿训练师。在旅馆旁西北角可以找到克鲁恩。', `MaleText_loc5`='當然，當然。城鎮中有一名採礦訓練師。在旅館旁西北角可以找到克魯恩。', `MaleText_loc7`='Claro, por supuesto que tenemos un instructor de minería en la ciudad. Busca a Krunn en el extremo noroeste, al lado de la posada.', `FemaleText_loc1`='물론, 이 칼바위 언덕에 광부 하나쯤은 살고 있지. 북서쪽 여관 옆에서 크룬을 찾아보게.', `FemaleText_loc4`='当然，当然。城镇中有一名采矿训练师。在旅馆旁西北角可以找到克鲁恩。', `FemaleText_loc5`='當然，當然。城鎮中有一名採礦訓練師。在旅館旁西北角可以找到克魯恩。', `FemaleText_loc7`='Claro, por supuesto que tenemos un instructor de minería en la ciudad. Busca a Krunn en el extremo noroeste, al lado de la posada.' WHERE `ID`=6589;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='듀로타에는 채광을 하기 좋은 곳이 많다고 하더군. 그래서, 이 칼바위 언덕에도 광부가 하나 머물고 있지. 북서쪽에 있는 가열로 옆에서 크룬을 찾아보게.', `MaleText_loc4`='我听说杜隆塔尔的采矿业极为发达。我们在剃刀岭有一个采矿训练师，你可以去城镇西北角的大熔炉附近寻找克鲁恩。', `MaleText_loc5`='我聽說杜洛塔的採礦業極為發達。我們在剃刀嶺有一個採礦訓練師，你可以去城鎮西北角的大熔爐附近尋找克魯恩。', `MaleText_loc7`='Aquí en Durotar hay muy buena minería, al menos eso es lo que yo he oído. Tan buena que, de hecho, tenemos un instructor de minería aquí mismo, en Cerrotajo. Encontrarás a Krunn junto a la fundición, en el extremo noroeste de la ciudad.', `FemaleText_loc1`='듀로타에는 채광을 하기 좋은 곳이 많다고 하더군. 그래서, 이 칼바위 언덕에도 광부가 하나 머물고 있지. 북서쪽에 있는 가열로 옆에서 크룬을 찾아보게.', `FemaleText_loc4`='我听说杜隆塔尔的采矿业极为发达。我们在剃刀岭有一个采矿训练师，你可以去城镇西北角的大熔炉附近寻找克鲁恩。', `FemaleText_loc5`='我聽說杜洛塔的採礦業極為發達。我們在剃刀嶺有一個採礦訓練師，你可以去城鎮西北角的大熔爐附近尋找克魯恩。', `FemaleText_loc7`='Aquí en Durotar hay muy buena minería, al menos eso es lo que yo he oído. Tan buena que, de hecho, tenemos un instructor de minería aquí mismo, en Cerrotajo. Encontrarás a Krunn junto a la fundición, en el extremo noroeste de la ciudad.' WHERE `ID`=6590;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무두장이라면 오그리마에 있네. 칼바위 언덕에서 나가는 길을 따라 북쪽으로 가. 도착한 후에 오그리마 그런트에게 물어봐.', `MaleText_loc4`='在奥格瑞玛有一名剥皮训练者。出了剃刀岭往北走，当你到达奥格瑞玛时问问那儿的守卫，他们会为你指明方向的。', `MaleText_loc5`='在奧格瑪有一名剝皮訓練師。出了剃刀嶺往北走，當你到達奧格瑪時問問奧格瑪蠻兵，他們會為你指明方向的。', `MaleText_loc7`='Hay un instructor de desuello en Orgrimmar. Para ir allí sigue el camino que sale hacia el norte de Cerrotajo. Cuando llegues, pregunta a un bruto de Orgrimmar por las señas.', `FemaleText_loc1`='무두장이라면 오그리마에 있네. 칼바위 언덕에서 나가는 길을 따라 북쪽으로 가. 도착한 후에 오그리마 그런트에게 물어봐.', `FemaleText_loc4`='在奥格瑞玛有一名剥皮训练者。出了剃刀岭往北走，当你到达奥格瑞玛时问问那儿的守卫，他们会为你指明方向的。', `FemaleText_loc5`='在奧格瑪有一名剝皮訓練師。出了剃刀嶺往北走，當你到達奧格瑪時問問奧格瑪蠻兵，他們會為你指明方向的。', `FemaleText_loc7`='Hay un instructor de desuello en Orgrimmar. Para ir allí sigue el camino que sale hacia el norte de Cerrotajo. Cuando llegues, pregunta a un bruto de Orgrimmar por las señas.' WHERE `ID`=6591;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여긴 없고, 오그리마에 한 명 있지. 북쪽으로 가서 그런트에게 다시 물어보게.', `MaleText_loc4`='在奥格瑞玛有你要找的人。朝着北方走，跟那儿的守卫谈谈。', `MaleText_loc5`='在奧格瑪有你要找的人。朝著北方走，跟那兒的守衛談談。', `MaleText_loc7`='Hay uno en Orgrimmar. Ve hacia el norte y habla con uno de los Brutos de la ciudad.', `FemaleText_loc1`='여긴 없고, 오그리마에 한 명 있지. 북쪽으로 가서 그런트에게 다시 물어보게.', `FemaleText_loc4`='在奥格瑞玛有你要找的人。朝着北方走，跟那儿的守卫谈谈。', `FemaleText_loc5`='在奧格瑪有你要找的人。朝著北方走，跟那兒的守衛談談。', `FemaleText_loc7`='Hay uno en Orgrimmar. Ve hacia el norte y habla con uno de los Brutos de la ciudad.' WHERE `ID`=6592;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오그리마로 가야겠군. 칼바위 언덕에서 나가는 북쪽 길로 곧장 가게. 그곳 그런트에게 물어보면 길을 더 자세히 가르쳐 줄걸.', `MaleText_loc4`='你得去奥格瑞玛。出了剃刀岭沿着北面的道路走，就能到那儿了。跟那儿的守卫谈谈，他们会给你指明方向的。', `MaleText_loc5`='你得去奧格瑪。出了剃刀嶺沿著北面的道路走，就能到那兒了。跟那兒的守衛談談，他們會給你指明方向的。', `MaleText_loc7`='Entonces debes ir a Orgrimmar. El camino que sale hacia el norte de Cerrotajo te lleva allí directamente. Cuando llegues habla con uno de los Brutos y él te dará más indicaciones.', `FemaleText_loc1`='오그리마로 가야겠군. 칼바위 언덕에서 나가는 북쪽 길로 곧장 가게. 그곳 그런트에게 물어보면 길을 더 자세히 가르쳐 줄걸.', `FemaleText_loc4`='你得去奥格瑞玛。出了剃刀岭沿着北面的道路走，就能到那儿了。跟那儿的守卫谈谈，他们会给你指明方向的。', `FemaleText_loc5`='你得去奧格瑪。出了剃刀嶺沿著北面的道路走，就能到那兒了。跟那兒的守衛談談，他們會給你指明方向的。', `FemaleText_loc7`='Entonces debes ir a Orgrimmar. El camino que sale hacia el norte de Cerrotajo te lleva allí directamente. Cuando llegues habla con uno de los Brutos y él te dará más indicaciones.' WHERE `ID`=6593;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='재봉술이라고? 북쪽에 있는 오그리마로 가면 배울 수 있을지도 모르지. 그곳 그런트에게 물어보게.', `MaleText_loc4`='你可以试着在奥格瑞玛解决你的问题，就在这里的北方。或许某个奥格瑞玛步兵可以帮你。', `MaleText_loc5`='你可以試著在奧格瑪解決你的問題，就在這裡的北方。或許某個奧格瑪蠻兵可以幫你。', `MaleText_loc7`='Puedes aprender a coser en Orgrimmar. Está al Norte. Puede que uno de los brutos de la ciudad pueda ayudarte.', `FemaleText_loc1`='재봉술이라고? 북쪽에 있는 오그리마로 가면 배울 수 있을지도 모르지. 그곳 그런트에게 물어보게.', `FemaleText_loc4`='你可以试着在奥格瑞玛解决你的问题，就在这里的北方。或许某个奥格瑞玛步兵可以帮你。', `FemaleText_loc5`='你可以試著在奧格瑪解決你的問題，就在這裡的北方。或許某個奧格瑪蠻兵可以幫你。', `FemaleText_loc7`='Puedes aprender a coser en Orgrimmar. Está al Norte. Puede que uno de los brutos de la ciudad pueda ayudarte.' WHERE `ID`=6594;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은행? 오그리마에 있지. 길을 따라 북쪽으로 가면 된다고. 그런 다음 그곳 그런트 중 한 명에게 다시 물어봐.', `MaleText_loc4`='呃？你可以在奥格瑞玛找到银行。沿着道路往北走，跟那儿的守卫谈谈。', `MaleText_loc5`='呃?你可以在奧格瑪找到銀行。沿著道路往北走，跟那兒的守衛談談。', `MaleText_loc7`='¿Qué? Encontrarás el banco en Orgrimmar. Sigue el camino hacia el norte y ve allí, cuando llegues pregunta a uno de los Brutos.', `FemaleText_loc1`='은행? 오그리마에 있지. 길을 따라 북쪽으로 가면 된다고. 그런 다음 그곳 그런트 중 한 명에게 다시 물어봐.', `FemaleText_loc4`='呃？你可以在奥格瑞玛找到银行。沿着道路往北走，跟那儿的守卫谈谈。', `FemaleText_loc5`='呃?你可以在奧格瑪找到銀行。沿著道路往北走，跟那兒的守衛談談。', `FemaleText_loc7`='¿Qué? Encontrarás el banco en Orgrimmar. Sigue el camino hacia el norte y ve allí, cuando llegues pregunta a uno de los Brutos.' WHERE `ID`=6595;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 보관해 둘 물건이라도 있나보군. 길을 따라 북쪽으로 오그리마까지 가게. 그곳 그런트 중 한 명에게 다시 물어봐.', `MaleText_loc4`='是的，我自己也需要放置一些东西。要找到它你需要向北沿着去奥格瑞玛的路一直走，然后找那里的步兵询问一下。', `MaleText_loc5`='是的，我自己也需要放置一些東西。要找到它你需要向北沿著去奧格瑪的路一直走，然後找那裡的蠻兵詢問一下。', `MaleText_loc7`='Sí, yo también tengo que hacer algunas entregas. Lo encontrarás siguiendo el camino hacia el Norte, hasta Orgrimmar, cuando llegues pregunta a uno de los Brutos.', `FemaleText_loc1`='아, 보관해 둘 물건이라도 있나보군. 길을 따라 북쪽으로 오그리마까지 가게. 그곳 그런트 중 한 명에게 다시 물어봐.', `FemaleText_loc4`='是的，我自己也需要放置一些东西。要找到它你需要向北沿着去奥格瑞玛的路一直走，然后找那里的步兵询问一下。', `FemaleText_loc5`='是的，我自己也需要放置一些東西。要找到它你需要向北沿著去奧格瑪的路一直走，然後找那裡的蠻兵詢問一下。', `FemaleText_loc7`='Sí, yo también tengo que hacer algunas entregas. Lo encontrarás siguiendo el camino hacia el Norte, hasta Orgrimmar, cuando llegues pregunta a uno de los Brutos.' WHERE `ID`=6596;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와이번 조련사는 오그리마에서 찾을 수 있지. 길을 따라 북쪽으로 가서 오그리마 그런트에게 물어보면 더 자세히 가르쳐 줄 거야.', `MaleText_loc4`='你会在奥格瑞玛找到双足飞龙管理员的。沿着公路向北走到那里去，并向一个奥格瑞玛步兵询问更多指示。', `MaleText_loc5`='你會在奧格瑪找到雙足飛龍管理員的。沿著公路向北走到那裡去，並向一個奧格瑪蠻兵詢問更多指示。', `MaleText_loc7`='Encontrarás al maestro de jinetes del viento en Orgrimmar. Sigue el camino hacia el norte y cuando llegues allí pide más indicaciones a uno de los brutos de la ciudad.', `FemaleText_loc1`='와이번 조련사는 오그리마에서 찾을 수 있지. 길을 따라 북쪽으로 가서 오그리마 그런트에게 물어보면 더 자세히 가르쳐 줄 거야.', `FemaleText_loc4`='你会在奥格瑞玛找到双足飞龙管理员的。沿着公路向北走到那里去，并向一个奥格瑞玛步兵询问更多指示。', `FemaleText_loc5`='你會在奧格瑪找到雙足飛龍管理員的。沿著公路向北走到那裡去，並向一個奧格瑪蠻兵詢問更多指示。', `FemaleText_loc7`='Encontrarás al maestro de jinetes del viento en Orgrimmar. Sigue el camino hacia el norte y cuando llegues allí pide más indicaciones a uno de los brutos de la ciudad.' WHERE `ID`=6597;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 한창 바쁜 거 안 보이나? 오그리마로 가서 그곳 그런트에게나 물어 봐. 오그리마는 쉽게 찾을 수 있겠지? 북쪽 길을 따라 가!', `MaleText_loc4`='你没看到我很忙吗?沿着路向北走到奥格瑞玛并询问那里的步兵。你不会错过的。', `MaleText_loc5`='你沒看到我很忙嗎?沿著路向北走到奧格瑪並詢問那裡的蠻兵。你不會錯過的。', `MaleText_loc7`='¿No ves que estoy ocupado? Sigue el camino hacia el Norte, hasta Orgrimmar, y cuando llegues pregunta a uno de los Brutos. No tiene pérdida.', `FemaleText_loc1`='지금 한창 바쁜 거 안 보이나? 오그리마로 가서 그곳 그런트에게나 물어 봐. 오그리마는 쉽게 찾을 수 있겠지? 북쪽 길을 따라 가!', `FemaleText_loc4`='你没看到我很忙吗?沿着路向北走到奥格瑞玛并询问那里的步兵。你不会错过的。', `FemaleText_loc5`='你沒看到我很忙嗎?沿著路向北走到奧格瑪並詢問那裡的蠻兵。你不會錯過的。', `FemaleText_loc7`='¿No ves que estoy ocupada? Sigue el camino hacia el Norte, hasta Orgrimmar, y cuando llegues pregunta a uno de los Brutos. No tiene pérdida.' WHERE `ID`=6598;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='감사합니다, 위대한 영혼이시여. 정말 감사합니다!', `FemaleText_loc4`='谢谢你，伟大的精灵。谢谢你！', `FemaleText_loc5`='謝謝你，偉大的精靈。謝謝你!', `FemaleText_loc7`='Gracias, gran espíritu. ¡Gracias!' WHERE `ID`=6599;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크아, 나도 한잔 들이켜면서 쉬고 싶군. 칼바위 언덕 북서쪽으로 가보게. 도착하면 여관주인 그로스크에게 내 안부나 전해 주게.', `MaleText_loc4`='我可以喝点东西，稍事休息。到剃刀岭西北角，替我向旅店管理人罗斯克问声好。', `MaleText_loc5`='我可以喝點東西，稍事休息。到剃刀嶺西北角，替我向旅店老闆格羅斯克問聲好。', `MaleText_loc7`='A mí tampoco me vendría mal tomar algo y descansar un poco. La encontrarás en el extremo noroeste de Cerrotajo. Saluda de mi parte al tabernero Grosk.', `FemaleText_loc1`='크아, 나도 한잔 들이켜면서 쉬고 싶군. 칼바위 언덕 북서쪽으로 가보게. 도착하면 여관주인 그로스크에게 내 안부나 전해 주게.', `FemaleText_loc4`='我可以喝点东西，稍事休息。到剃刀岭西北角，替我向旅店管理人罗斯克问声好。', `FemaleText_loc5`='我可以喝點東西，稍事休息。到剃刀嶺西北角，替我向旅店老闆格羅斯克問聲好。', `FemaleText_loc7`='A mí tampoco me vendría mal tomar algo y descansar un poco. La encontrarás en el extremo noroeste de Cerrotajo. Saluda de mi parte al tabernero Grosk.' WHERE `ID`=6600;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼바위 언덕에 병영 말고 또 다른 커다란 건물이 있네. 그게 바로 여관이지. 그 안으로 들어가 여관주인 그로스크에게 말을 건네보게. 알겠나?', `MaleText_loc4`='那是剃刀岭的一幢大建筑，而不是兵营。去跟旅店老板格罗斯克谈谈。明白了？', `MaleText_loc5`='那是剃刀嶺的一幢大建築，而不是兵營。去跟旅店老闆格羅斯克談談。明白了?', `MaleText_loc7`='Es el gran edificio de Cerrotajo que no son los cuarteles. En su interior habla con el tabernero Grosk. ¿Lo has cogido?', `FemaleText_loc1`='칼바위 언덕에 병영 말고 또 다른 커다란 건물이 있네. 그게 바로 여관이지. 그 안으로 들어가 여관주인 그로스크에게 말을 건네보게. 알겠나?', `FemaleText_loc4`='那是剃刀岭的一幢大建筑，而不是兵营。去跟旅店老板格罗斯克谈谈。明白了？', `FemaleText_loc5`='那是剃刀嶺的一幢大建築，而不是兵營。去跟旅店老闆格羅斯克談談。明白了?', `FemaleText_loc7`='Es el gran edificio de Cerrotajo que no son los cuarteles. En su interior habla con el tabernero Grosk. ¿Lo has cogido?' WHERE `ID`=6601;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 직업 상급자를 찾나?', `MaleText_loc4`='你要找什么技能的训练师？', `MaleText_loc5`='你要找什麼技能的訓練師?', `MaleText_loc7`='¿A qué instructor buscas?', `FemaleText_loc1`='어떤 직업 상급자를 찾나?', `FemaleText_loc4`='你要找什么技能的训练师？', `FemaleText_loc5`='你要找什麼技能的訓練師?', `FemaleText_loc7`='¿A qué instructor buscas?' WHERE `ID`=6602;
