UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 무엇을 하려는지 들었고 우리도 동의하느니라... 그 목적이 숭고하고 가상하도다. 물을 정화해 줄 터이니 우리의 축복과 함께 가도록 하게, $C|1이여;여;.', `MaleText_loc4`='我们听说了你的请求，我们同意……这是件好事。我们会为你净化水的。带着我们的祝福上路吧，萨满。', `MaleText_loc5`='我們聽說了你的請求，我們同意...這是件好事。我們會為你淨化水的。帶著我們的祝福上路吧，薩滿。', `MaleText_loc7`='Hemos oído tus peticiones y estamos de acuerdo... es un noble propósito. Purificaremos tus aguas. Márchate con nuestra bendición, chamán.' WHERE `ID`=6607;
