UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 안내원처럼 보이나? 그래, 필요한 게 뭐야?', `MaleText_loc4`='你看我像个向导吗？好极了，你需要什么？', `MaleText_loc5`='你看我像個嚮導嗎?好極了，你需要什麼?', `MaleText_loc7`='¿Tengo aspecto de guía? Bueno, ¿qué necesitas?', `FemaleText_loc1`='내가 안내원처럼 보이나? 그래, 필요한 게 뭐야?', `FemaleText_loc4`='你看我像个向导吗？好极了，你需要什么？', `FemaleText_loc5`='你看我像個嚮導嗎?好極了，你需要什麼?', `FemaleText_loc7`='¿Tengo aspecto de guía? Bueno, ¿qué necesitas?' WHERE `ID`=6797;
