UPDATE `locales_broadcast_text` SET `MaleText_loc1`='낮잠을 자기에 딱 좋은 장소 같아 보이는데...', `MaleText_loc4`='这儿看上去是个休憩的好地方。', `MaleText_loc5`='這兒看起來是個休憩的好地方。', `MaleText_loc7`='Parece el lugar perfecto para echar una siesta...' WHERE `ID`=6813;
