UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 탁 트인 곳으로 이끌려 나옵니다!', `MaleText_loc4`='%s被引到了开阔地带！', `MaleText_loc5`='%s被引誘到了開闊地帶!', `MaleText_loc7`='%s se siente atraído al aire libre.' WHERE `ID`=6874;
