UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까? 길을 찾고 계신가요?', `MaleText_loc4`='你好，公民。你需要指引吗？', `MaleText_loc5`='你好，居民。你需要指引嗎?', `MaleText_loc7`='Salve, $gciudadano:ciudadana;. ¿Necesitas ayuda con alguna seña?', `FemaleText_loc1`='안녕하십니까? 길을 찾고 계신가요?', `FemaleText_loc4`='你好，公民。你需要指引吗？', `FemaleText_loc5`='你好，居民。你需要指引嗎?', `FemaleText_loc7`='Salve, $gciudadano:ciudadana;. ¿Necesitas ayuda con alguna seña?' WHERE `ID`=6901;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭔가 찾고 계신 것 같은데, 도와 드릴까요?', `MaleText_loc4`='我能帮你找到你要寻找的东西吗？', `MaleText_loc5`='我能幫你找到你要尋找的東西嗎?', `MaleText_loc7`='¿Puedo ayudarte a encontrar algo?', `FemaleText_loc1`='뭔가 찾고 계신 것 같은데, 도와 드릴까요?', `FemaleText_loc4`='我能帮你找到你要寻找的东西吗？', `FemaleText_loc5`='我能幫你找到你要尋找的東西嗎?', `FemaleText_loc7`='¿Puedo ayudarte a encontrar algo?' WHERE `ID`=6902;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='길을 잃으신 것 같군요. 무엇을 찾고 계십니까?', `MaleText_loc4`='你看起来有些迷茫。你在找谁？', `MaleText_loc5`='你看起來有些迷茫。你在找誰?', `MaleText_loc7`='Pareces algo $gperdido:perdida;. ¿Qué estás buscando?', `FemaleText_loc1`='길을 잃으신 것 같군요. 무엇을 찾고 계십니까?', `FemaleText_loc4`='你看起来有些迷茫。你在找谁？', `FemaleText_loc5`='你看起來有些迷茫。你在找誰?', `FemaleText_loc7`='Pareces algo $gperdido:perdida;. ¿Qué estás buscando?' WHERE `ID`=6903;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에 처음이신가요? 그럼 무얼 찾고 계시는지 말씀해 보십시오. 제가 도와드리겠습니다.', `MaleText_loc4`='你是新来的吗？嗯，告诉我你在找什么吧。', `MaleText_loc5`='你是新來的嗎?嗯，告訴我你在找什麼吧。', `MaleText_loc7`='¿Eres $gnuevo:nueva; por aquí? Bien, dime qué es lo que buscas.', `FemaleText_loc1`='이곳에 처음이신가요? 그럼 무얼 찾고 계시는지 말씀해 보십시오. 제가 도와드리겠습니다.', `FemaleText_loc4`='你是新来的吗？嗯，告诉我你在找什么吧。', `FemaleText_loc5`='你是新來的嗎?嗯，告訴我你在找什麼吧。', `FemaleText_loc7`='¿Eres $gnuevo:nueva; por aquí? Bien, dime qué es lo que buscas.' WHERE `ID`=6904;
