UPDATE `locales_broadcast_text` SET `MaleText_loc1`='길을 잃은 것 같은데, 좀 도와 드릴까요?', `MaleText_loc4`='你看起来有些迷茫。我能帮你什么忙吗？', `MaleText_loc5`='你看起來有些迷茫。我能幫你什麼忙嗎?', `MaleText_loc7`='Pareces un poco $gperdido:perdida;. ¿Puedo ayudarte a encontrar algo?', `FemaleText_loc1`='길을 잃은 것 같은데, 좀 도와 드릴까요?', `FemaleText_loc4`='你看起来有些迷茫。我能帮你什么忙吗？', `FemaleText_loc5`='你看起來有些迷茫。我能幫你什麼忙嗎?', `FemaleText_loc7`='Pareces un poco $gperdido:perdida;. ¿Puedo ayudarte a encontrar algo?' WHERE `ID`=6982;
