UPDATE `locales_broadcast_text` SET `MaleText_loc1`='젊은 $C 친구, 은행 업무를 볼 요량이라면 아이언포지에 있는 사설금고로 가십시오. 그래도 여기서 제일 가까우니까.', `MaleText_loc4`='最近的银行就是铁炉堡银行，$g小伙子:姑娘;。', `MaleText_loc5`='最近的銀行就是鐵爐堡銀行，$g小夥子:姑娘;。', `MaleText_loc7`='El banco más cercano son Las Arcas de Forjaz, $gmuchacho:muchacha;.', `FemaleText_loc1`='젊은 $C 친구, 은행 업무를 볼 요량이라면 아이언포지에 있는 사설금고로 가십시오. 그래도 여기서 제일 가까우니까.', `FemaleText_loc4`='最近的银行就是铁炉堡银行，$g小伙子:姑娘;。', `FemaleText_loc5`='最近的銀行就是鐵爐堡銀行，$g小夥子:姑娘;。', `FemaleText_loc7`='El banco más cercano son Las Arcas de Forjaz, $gmuchacho:muchacha;.' WHERE `ID`=6988;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이언포지 사설금고가 이 근방에서 그래도 제일 가까운 은행일 겁니다.', `MaleText_loc4`='铁炉堡银行是这一带最近的银行。', `MaleText_loc5`='鐵爐堡銀行是這一帶最近的銀行。', `MaleText_loc7`='Las Arcas de Forjaz son el banco más cercano que encontrarás por estos lares.', `FemaleText_loc1`='아이언포지 사설금고가 이 근방에서 그래도 제일 가까운 은행일 겁니다.', `FemaleText_loc4`='铁炉堡银行是这一带最近的银行。', `FemaleText_loc5`='鐵爐堡銀行是這一帶最近的銀行。', `FemaleText_loc7`='Las Arcas de Forjaz son el banco más cercano que encontrarás por estos lares.' WHERE `ID`=6989;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리핀 조련사', `MaleText_loc4`='狮鹫管理员', `MaleText_loc5`='獅鷲獸管理員', `MaleText_loc7`='Maestro de grifos', `FemaleText_loc1`='그리핀 조련사', `FemaleText_loc4`='狮鹫管理员', `FemaleText_loc5`='獅鷲獸管理員', `FemaleText_loc7`='Maestro de grifos' WHERE `ID`=6990;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리핀을 타고 다른 곳으로 가고 싶습니까? 안타깝게도 그리핀 조련사는 던 모로 어디에서도 찾을 수 없을 겁니다. 아이언포지로 가보십시오.', `MaleText_loc4`='丹莫罗一带是没有狮鹫管理员的，$g小伙子:姑娘;。如果你想骑狮鹫去什么地方的话，就必须去铁炉堡。', `MaleText_loc5`='丹莫洛一帶是沒有獅鷲獸管理員的，$g小夥子:姑娘;。如果你想騎獅鷲獸去什麼地方的話，就必須去鐵爐堡。', `MaleText_loc7`='No encontrarás ningún maestro de grifos por Dun Morogh, $gmuchacho:muchacha;. Tendrás que ir hasta Forjaz si quieres ir en grifo a alguna parte.', `FemaleText_loc1`='그리핀을 타고 다른 곳으로 가고 싶습니까? 안타깝게도 그리핀 조련사는 던 모로 어디에서도 찾을 수 없을 겁니다. 아이언포지로 가보십시오.', `FemaleText_loc4`='丹莫罗一带是没有狮鹫管理员的，$g小伙子:姑娘;。如果你想骑狮鹫去什么地方的话，就必须去铁炉堡。', `FemaleText_loc5`='丹莫洛一帶是沒有獅鷲獸管理員的，$g小夥子:姑娘;。如果你想騎獅鷲獸去什麼地方的話，就必須去鐵爐堡。', `FemaleText_loc7`='No encontrarás ningún maestro de grifos por Dun Morogh, $gmuchacho:muchacha;. Tendrás que ir hasta Forjaz si quieres ir en grifo a alguna parte.' WHERE `ID`=6991;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리핀 조련사를 찾으신다면 아이언포지의 대용광로 근처로 가십시오. 그래도 가장 가까운 곳이니까요. 아이언포지로 가면 그리핀을 타고 날아갈 수 있을 겁니다.', `MaleText_loc4`='最近的狮鹫管理员居住在铁炉堡的大锻炉附近。如果你想乘坐狮鹫的话，就前往铁炉堡吧。', `MaleText_loc5`='最近的獅鷲獸管理員居住在鐵爐堡的大鍛爐附近。如果你想乘坐獅鷲獸的話，就前往鐵爐堡吧。', `MaleText_loc7`='El maestro de grifos más cercano está en Forjaz, junto a La Gran Fundición. Tendrás que dirigirte a Forjaz si quieres viajar en grifo.', `FemaleText_loc1`='그리핀 조련사를 찾으신다면 아이언포지의 대용광로 근처로 가십시오. 그래도 가장 가까운 곳이니까요. 아이언포지로 가면 그리핀을 타고 날아갈 수 있을 겁니다.', `FemaleText_loc4`='最近的狮鹫管理员居住在铁炉堡的大锻炉附近。如果你想乘坐狮鹫的话，就前往铁炉堡吧。', `FemaleText_loc5`='最近的獅鷲獸管理員居住在鐵爐堡的大鍛爐附近。如果你想乘坐獅鷲獸的話，就前往鐵爐堡吧。', `FemaleText_loc7`='El maestro de grifos más cercano está en Forjaz, junto a La Gran Fundición. Tendrás que dirigirte a Forjaz si quieres viajar en grifo.' WHERE `ID`=6992;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='길드 사무관과 상인', `MaleText_loc4`='公会注册员及公会商人', `MaleText_loc5`='公會註冊員和商人', `MaleText_loc7`='Maestro de hermandad y vendedor', `FemaleText_loc1`='길드 사무관과 상인', `FemaleText_loc4`='公会注册员及公会商人', `FemaleText_loc5`='公會註冊員和商人', `FemaleText_loc7`='Maestro de hermandad y vendedor' WHERE `ID`=6993;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공무를 담당하는 이들은 모두 아이언포지에 살고 있습니다. 길드를 창설하기 위해 서류가 필요하다면 아이언포지 사무소로 가보는 게 좋겠군요.', `MaleText_loc4`='所有的官员都居住在铁炉堡。你得去铁炉堡访客中心领取公会登记表。', `MaleText_loc5`='所有的官員都居住在鐵爐堡。你得去鐵爐堡訪客中心領取公會登記表。', `MaleText_loc7`='Todos esos oficiales residen en Forjaz. Tendrás que acudir al Centro del Viajero de Forjaz, allí obtendrás los documentos necesarios para fundar una hermandad.', `FemaleText_loc1`='공무를 담당하는 이들은 모두 아이언포지에 살고 있습니다. 길드를 창설하기 위해 서류가 필요하다면 아이언포지 사무소로 가보는 게 좋겠군요.', `FemaleText_loc4`='所有的官员都居住在铁炉堡。你得去铁炉堡访客中心领取公会登记表。', `FemaleText_loc5`='所有的官員都居住在鐵爐堡。你得去鐵爐堡訪客中心領取公會登記表。', `FemaleText_loc7`='Todos esos oficiales residen en Forjaz. Tendrás que acudir al Centro del Viajero de Forjaz, allí obtendrás los documentos necesarios para fundar una hermandad.' WHERE `ID`=6994;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='길드를 창설하려고 하십니까? 아이언포지 사무소에 들러 필요한 서류 업무를 보셔야겠군요.', `MaleText_loc4`='要是你需要一些公会登记表的话，就前往铁炉堡，去拜访铁炉堡访客中心吧。', `MaleText_loc5`='要是你需要一些公會登記表的話，就前往鐵爐堡，去拜訪鐵爐堡訪客中心吧。', `MaleText_loc7`='Si quieres echarle mano a los papeles para crear una hermandad tendrás que ir a Forjaz y visitar el Centro del Viajero.', `FemaleText_loc1`='길드를 창설하려고 하십니까? 아이언포지 사무소에 들러 필요한 서류 업무를 보셔야겠군요.', `FemaleText_loc4`='要是你需要一些公会登记表的话，就前往铁炉堡，去拜访铁炉堡访客中心吧。', `FemaleText_loc5`='要是你需要一些公會登記表的話，就前往鐵爐堡，去拜訪鐵爐堡訪客中心吧。', `FemaleText_loc7`='Si quieres echarle mano a los papeles para crear una hermandad tendrás que ir a Forjaz y visitar el Centro del Viajero.' WHERE `ID`=6995;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여관', `MaleText_loc4`='旅店', `MaleText_loc5`='旅店', `MaleText_loc7`='La posada', `FemaleText_loc1`='여관', `FemaleText_loc4`='旅店', `FemaleText_loc5`='旅店', `FemaleText_loc7`='La posada' WHERE `ID`=6996;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='썬더브루 가문에서는 카라노스에 썩 괜찮은 양조장 겸 여관을 하나 운영하고 있습니다. 이름도 자기들 성을 따서 지었더군요. 그곳에 잠시 들러서 맥주도 한잔 하시고 좀 쉬었다 가십시오.', `MaleText_loc4`='雷酒家族在卡拉诺斯开了一家旅店，久负盛名。在那里喝杯酒休息一下吧。', `MaleText_loc5`='雷酒家族在卡拉諾斯開了一家旅店，久負盛名。在那裡喝杯酒休息一下吧。', `MaleText_loc7`='Los Cebatruenos tienen una agradable posada en Kharanos que lleva su nombre. Entra a tomar una pinta y a descansar un poco.', `FemaleText_loc1`='썬더브루 가문에서는 카라노스에 썩 괜찮은 양조장 겸 여관을 하나 운영하고 있습니다. 이름도 자기들 성을 따서 지었더군요. 그곳에 잠시 들러서 맥주도 한잔 하시고 좀 쉬었다 가십시오.', `FemaleText_loc4`='雷酒家族在卡拉诺斯开了一家旅店，久负盛名。在那里喝杯酒休息一下吧。', `FemaleText_loc5`='雷酒家族在卡拉諾斯開了一家旅店，久負盛名。在那裡喝杯酒休息一下吧。', `FemaleText_loc7`='Los Cebatruenos tienen una agradable posada en Kharanos que lleva su nombre. Entra a tomar una pinta y a descansar un poco.' WHERE `ID`=6997;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 여관 말씀이십니까? 쉴 곳으로는 썬더브루 양조장만한 데가 또 없지요. 휴식이 필요하다면 쉬었다 가십시오. 가신 김에 에일 맥주 한두 잔 정도는 꼭 드셔 보시기 바랍니다.', `MaleText_loc4`='哦，旅店是吗？嗯，雷酒酿制厂是最棒的。你可以在那里稍事休息，但是你一定得尝尝那儿的啤酒。', `MaleText_loc5`='哦，旅店是嗎?嗯，雷酒釀酒廠是最棒的。你可以在那裡稍事休息，但是你一定得嘗嘗那兒的麥芽酒。', `MaleText_loc7`='Oooh, ¿una posada? No hay ninguna como la Destilería Cebatruenos. Descansa si lo necesitas y tómate una cerveza o dos cuando estés ahí.', `FemaleText_loc1`='아, 여관 말씀이십니까? 쉴 곳으로는 썬더브루 양조장만한 데가 또 없지요. 휴식이 필요하다면 쉬었다 가십시오. 가신 김에 에일 맥주 한두 잔 정도는 꼭 드셔 보시기 바랍니다.', `FemaleText_loc4`='哦，旅店是吗？嗯，雷酒酿制厂是最棒的。你可以在那里稍事休息，但是你一定得尝尝那儿的啤酒。', `FemaleText_loc5`='哦，旅店是嗎?嗯，雷酒釀酒廠是最棒的。你可以在那裡稍事休息，但是你一定得嘗嘗那兒的麥芽酒。', `FemaleText_loc7`='Oooh, ¿una posada? No hay ninguna como la Destilería Cebatruenos. Descansa si lo necesitas y tómate una cerveza o dos cuando estés ahí.' WHERE `ID`=6998;
