UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 직업 상급자를 찾고 있습니까?', `MaleText_loc4`='你需要找哪个职业的训练师？', `MaleText_loc5`='你需要找哪個職業的訓練師?', `MaleText_loc7`='¿Qué instructor de clase estás buscando?', `FemaleText_loc1`='어떤 직업 상급자를 찾고 있습니까?', `FemaleText_loc4`='你需要找哪个职业的训练师？', `FemaleText_loc5`='你需要找哪個職業的訓練師?', `FemaleText_loc7`='¿Qué instructor de clase estás buscando?' WHERE `ID`=7000;
