UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라우르나 모닝라이트라는 여사제가 돌라나르에서 살고 있습니다. 여관의 바로 북쪽에서 찾을 수 있다고 알고 있습니다.', `MaleText_loc4`='一位名叫劳尔娜·晨光的女祭司住在多兰纳尔，我认为你可以在旅店北面找到她。', `MaleText_loc5`='一位名叫勞爾娜·晨光的女祭司住在多蘭納爾，我認為你可以在旅店北面找到她。', `MaleText_loc7`='Una sacerdotisa llamada Laurna Luzdelalba vive en Dolanaar. Creo que la puedes encontrar al norte de la posada.', `FemaleText_loc1`='라우르나 모닝라이트라는 여사제가 돌라나르에서 살고 있습니다. 여관의 바로 북쪽에서 찾을 수 있다고 알고 있습니다.', `FemaleText_loc4`='一位名叫劳尔娜·晨光的女祭司住在多兰纳尔，我认为你可以在旅店北面找到她。', `FemaleText_loc5`='一位名叫勞爾娜·晨光的女祭司住在多蘭納爾，我認為你可以在旅店北面找到她。', `FemaleText_loc7`='Una sacerdotisa llamada Laurna Luzdelalba vive en Dolanaar. Creo que la puedes encontrar al norte de la posada.' WHERE `ID`=7087;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌라나르 근처에 사는 이들은 라우르나 모닝라이트에게 가서 치유를 받습니다. 사제의 길을 가신다면 그녀를 찾아가 보시는 게 좋을 것 같네요.', `MaleText_loc4`='劳尔娜·晨光为居住在多兰纳尔附近的居民们提供医疗服务。或许她能教你如何成为一名牧师。', `MaleText_loc5`='勞爾娜·晨光為居住在多蘭納爾附近的居民們提供醫療服務。或許她能教你如何成為一名牧師。', `MaleText_loc7`='Laurna Luzdelalba ofrece su curación a todos los que viven en Dolanaar. quizás pueda enseñarte las artes del sacerdote.', `FemaleText_loc1`='돌라나르 근처에 사는 이들은 라우르나 모닝라이트에게 가서 치유를 받습니다. 사제의 길을 가신다면 그녀를 찾아가 보시는 게 좋을 것 같네요.', `FemaleText_loc4`='劳尔娜·晨光为居住在多兰纳尔附近的居民们提供医疗服务。或许她能教你如何成为一名牧师。', `FemaleText_loc5`='勞爾娜·晨光為居住在多蘭納爾附近的居民們提供醫療服務。或許她能教你如何成為一名牧師。', `FemaleText_loc7`='Laurna Luzdelalba ofrece su curación a todos los que viven en Dolanaar. Quizás pueda enseñarte las artes del sacerdote.' WHERE `ID`=7088;
