UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도적이라고요? 그런 부류에 관한 일에 엮이는 건 그다지 좋아하지 않습니다. 분명 잔노크를 찾으시는 거겠죠. 돌라나르 여관으로 가보십시오.', `MaleText_loc4`='潜行者？我不习惯跟那些家伙打交道，但我相信詹诺克就是你要找的训练师。你可以在多兰纳尔的旅店找到他。', `MaleText_loc5`='一個盜賊?我不習慣跟那些傢伙打交道，但我相信詹諾克就是你要找的訓練師。你可以在多蘭納爾的旅店找到他。', `MaleText_loc7`='¿Un pícaro? No tengo la costumbre de indicar a la gente donde están esos tipos, pero creo que a quien buscas es a Jannok. Lo encontrarás en la posada de Dolanaar.', `FemaleText_loc1`='도적이라고요? 그런 부류에 관한 일에 엮이는 건 그다지 좋아하지 않습니다. 분명 잔노크를 찾으시는 거겠죠. 돌라나르 여관으로 가보십시오.', `FemaleText_loc4`='潜行者？我不习惯跟那些家伙打交道，但我相信詹诺克就是你要找的训练师。你可以在多兰纳尔的旅店找到他。', `FemaleText_loc5`='一個盜賊?我不習慣跟那些傢伙打交道，但我相信詹諾克就是你要找的訓練師。你可以在多蘭納爾的旅店找到他。', `FemaleText_loc7`='¿Un pícaro? No tengo la costumbre de indicar a la gente donde están esos tipos, pero creo que a quien buscas es a Jannok. Lo encontrarás en la posada de Dolanaar.' WHERE `ID`=7090;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도적을 찾으시나요? 잔노크 말씀이로군요. 돌라나르 여관으로 가보십시오.', `MaleText_loc4`='你在找寻一个潜行者？我认为詹诺克很适合你的描述。你为什么不到多兰纳尔的旅馆里去找他谈谈呢？', `MaleText_loc5`='你在找尋一個盜賊?我認為詹諾克很適合你的描述。你為什麼不到多蘭納爾的旅館裡去找他談談呢?', `MaleText_loc7`='¿Buscas a un pícaro? Creo que Jannok encaja en esa descripción. ¿Por qué no vas a hablar con él en la posada de Dolanaar?', `FemaleText_loc1`='도적을 찾으시나요? 잔노크 말씀이로군요. 돌라나르 여관으로 가보십시오.', `FemaleText_loc4`='你在找寻一个潜行者？我认为詹诺克很适合你的描述。你为什么不到多兰纳尔的旅馆里去找他谈谈呢？', `FemaleText_loc5`='你在找尋一個盜賊?我認為詹諾克很適合你的描述。你為什麼不到多蘭納爾的旅館裡去找他談談呢?', `FemaleText_loc7`='¿Buscas a un pícaro? Creo que Jannok encaja en esa descripción. ¿Por qué no vas a hablar con él en la posada de Dolanaar?' WHERE `ID`=7091;
