UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼 쓰는 솜씨라면 키라 윈드블레이드가 일품이죠. 돌라나르 여관에서 찾아보세요. 키라가 뭔가 가르쳐 줄 수 있을 거예요.', `MaleText_loc4`='凯拉·风刃的战斗技能炉火纯青。她可以对你进行训练。到多兰纳尔的旅店中去找她吧。', `MaleText_loc5`='凱拉·風刃的戰鬥技能爐火純青。她可以對你進行訓練。到多蘭納爾的旅店中去找她吧。', `MaleText_loc7`='Kyra Espada del Viento maneja la espada con gran habilidad. Seguro que puede ofrecerte instrucción. La encontrarás en la posada de Dolanaar.', `FemaleText_loc1`='칼 쓰는 솜씨라면 키라 윈드블레이드가 일품이죠. 돌라나르 여관에서 찾아보세요. 키라가 뭔가 가르쳐 줄 수 있을 거예요.', `FemaleText_loc4`='凯拉·风刃的战斗技能炉火纯青。她可以对你进行训练。到多兰纳尔的旅店中去找她吧。', `FemaleText_loc5`='凱拉·風刃的戰鬥技能爐火純青。她可以對你進行訓練。到多蘭納爾的旅店中去找她吧。', `FemaleText_loc7`='Kyra Espada del Viento maneja la espada con gran habilidad. Seguro que puede ofrecerte instrucción. La encontrarás en la posada de Dolanaar.' WHERE `ID`=7093;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예전에 한 번 키라 윈드블레이드가 싸우는 모습을 지켜 본 적이 있습니다. 정말 멋져서 탄성이 저절로 나오더군요. 키라가 그대를 잘 가르칠 수 있을 거예요. 돌라나르 여관에서 찾아보세요.', `MaleText_loc4`='我以前曾有幸看到在凯拉·风刃作战，因此我相信她可以好好训练你。到多兰纳尔旅店去找她吧。', `MaleText_loc5`='我以前曾有幸看到在凱拉·風刃作戰，因此我相信她可以好好訓練你。到多蘭納爾旅店去找她吧。', `MaleText_loc7`='En una ocasión tuve el placer de ver a Kyra Espada del Viento en combate. Teniendo en cuenta lo que vi, estoy seguro de que te entrenará bien. Búscala en la posada de Dolanaar.', `FemaleText_loc1`='예전에 한 번 키라 윈드블레이드가 싸우는 모습을 지켜 본 적이 있습니다. 정말 멋져서 탄성이 저절로 나오더군요. 키라가 그대를 잘 가르칠 수 있을 거예요. 돌라나르 여관에서 찾아보세요.', `FemaleText_loc4`='我以前曾有幸看到在凯拉·风刃作战，因此我相信她可以好好训练你。到多兰纳尔旅店去找她吧。', `FemaleText_loc5`='我以前曾有幸看到在凱拉·風刃作戰，因此我相信她可以好好訓練你。到多蘭納爾旅店去找她吧。', `FemaleText_loc7`='Una vez tuve el placer de ver a Kyra Espada del Viento en combate. Con todo de lo que fui testigo, puedo asegurarte que recibirás una buena instrucción. Búscala en la posada de Dolanaar.' WHERE `ID`=7094;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기술 전문가', `MaleText_loc4`='专业训练师', `MaleText_loc5`='專業技能訓練師', `MaleText_loc7`='Instructor de profesión', `FemaleText_loc1`='기술 전문가', `FemaleText_loc4`='专业训练师', `FemaleText_loc5`='專業技能訓練師', `FemaleText_loc7`='Instructor de profesión' WHERE `ID`=7095;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어느 기술이나, 왕도가 되는 길은 길고도 험하지만 그만큼 큰 보람을 주지요. 어떤 전문가의 길을 걷고 싶으신가요?', `MaleText_loc4`='从事某种专业的学习是一个长期的过程，但是回报很丰厚。你想选择什么样的专业？', `MaleText_loc5`='學習專業技能是一個長期的過程，但是回報很豐厚。你想選擇什麼樣的專業技能?', `MaleText_loc7`='El camino de aquellos que deciden ejercer una profesión es largo pero gratificante. ¿Qué camino eliges tú?', `FemaleText_loc1`='어느 기술이나, 왕도가 되는 길은 길고도 험하지만 그만큼 큰 보람을 주지요. 어떤 전문가의 길을 걷고 싶으신가요?', `FemaleText_loc4`='从事某种专业的学习是一个长期的过程，但是回报很丰厚。你想选择什么样的专业？', `FemaleText_loc5`='學習專業技能是一個長期的過程，但是回報很豐厚。你想選擇什麼樣的專業技能?', `FemaleText_loc7`='El camino de aquellos que deciden ejercer una profesión es largo pero gratificante. ¿Qué camino eliges tú?' WHERE `ID`=7096;
