UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알란나 레이븐아이는 신탁의 숲에 있는 영혼들과 교제한 이후 마법부여 능력을 얻었다고 하더군요. 지금 그곳에 가보시면 알란나를 만날 수 있을 거예요.', `MaleText_loc4`='奥兰纳·鸦眼将她的天赋部分归结为与神谕林地的灵魂进行了交流。你应该能在那儿找到她的。', `MaleText_loc5`='奧蘭納·鴉眼將她的天賦部分歸結為與神諭林地的靈魂進行了交流。你應該能在那兒找到她的。', `MaleText_loc7`='Alanna Cuervojo atribuye parte de su talento en el arte del encantamiento a su comunión con los espíritus de El Claro del Oráculo. Deberías poder encontrarla allí.', `FemaleText_loc1`='알란나 레이븐아이는 신탁의 숲에 있는 영혼들과 교제한 이후 마법부여 능력을 얻었다고 하더군요. 지금 그곳에 가보시면 알란나를 만날 수 있을 거예요.', `FemaleText_loc4`='奥兰纳·鸦眼将她的天赋部分归结为与神谕林地的灵魂进行了交流。你应该能在那儿找到她的。', `FemaleText_loc5`='奧蘭納·鴉眼將她的天賦部分歸結為與神諭林地的靈魂進行了交流。你應該能在那兒找到她的。', `FemaleText_loc7`='Alanna Cuervojo atribuye parte de su talento en el arte del encantamiento a su comunión con los espíritus de El Claro del Oráculo. Deberías poder encontrarla allí.' WHERE `ID`=7104;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알란나는 대부분의 시간을 신탁의 숲에서 마법부여를 연구하며 보내죠. 마법부여를 배우고 싶으시다면 그 숲으로 가서 알란나를 찾아보셔야 할 거예요.', `MaleText_loc4`='阿兰娜大部分时间都在神谕林地练习技能。如果你想学做一名附魔师的话，就去那儿找她吧。', `MaleText_loc5`='阿蘭娜大部分時間都在神諭林地實習她的專業技能。如果你想學習附魔技能的話，就去那兒找她吧。', `MaleText_loc7`='Alanna pasa casi todo el día en El Claro del Oráculo, donde ejerce su profesión. Si deseas aprender encantamiento tendrás que ir allí para encontrarla.', `FemaleText_loc1`='알란나는 대부분의 시간을 신탁의 숲에서 마법부여를 연구하며 보내죠. 마법부여를 배우고 싶으시다면 그 숲으로 가서 알란나를 찾아보셔야 할 거예요.', `FemaleText_loc4`='阿兰娜大部分时间都在神谕林地练习技能。如果你想学做一名附魔师的话，就去那儿找她吧。', `FemaleText_loc5`='阿蘭娜大部分時間都在神諭林地實習她的專業技能。如果你想學習附魔技能的話，就去那兒找她吧。', `FemaleText_loc7`='Alanna pasa casi todo el día en El Claro del Oráculo, donde ejerce su profesión. Si deseas aprender encantamiento tendrás que ir allí para encontrarla.' WHERE `ID`=7105;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='응급치료', `MaleText_loc4`='急救', `MaleText_loc5`='急救', `MaleText_loc7`='Primeros auxilios', `FemaleText_loc1`='응급치료', `FemaleText_loc4`='急救', `FemaleText_loc5`='急救', `FemaleText_loc7`='Primeros auxilios' WHERE `ID`=7106;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파수꾼들이 숲 속을 순찰하다가 다치면, 보통 비얀시에게 간답니다. 응급치료를 배우고 싶으시다면 비얀시를 찾아가 보세요.', `MaleText_loc4`='拜恩希经常为在野外巡逻的哨兵服务。如果你想学习急救的话就该找她谈谈。', `MaleText_loc5`='拜恩希經常為在野外巡邏的哨兵服務。如果你想學習急救的話就該找她談談。', `MaleText_loc7`='Byancie ha prestado a menudo sus servicios a los centinelas que patrullan nuestro entorno natural. Si tu deseo es aprender primeros auxilios deberías ir a hablar con ella.', `FemaleText_loc1`='파수꾼들이 숲 속을 순찰하다가 다치면, 보통 비얀시에게 간답니다. 응급치료를 배우고 싶으시다면 비얀시를 찾아가 보세요.', `FemaleText_loc4`='拜恩希经常为在野外巡逻的哨兵服务。如果你想学习急救的话就该找她谈谈。', `FemaleText_loc5`='拜恩希經常為在野外巡邏的哨兵服務。如果你想學習急救的話就該找她談談。', `FemaleText_loc7`='Byancie ha prestado a menudo sus servicios a los centinelas que patrullan nuestro entorno natural. Si tu deseo es aprender primeros auxilios deberías ir a hablar con ella.' WHERE `ID`=7107;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비얀시의 응급치료 기술이 없었다면 돌라나르의 많은 주민은 생명의 위기를 겪었을 겁니다. 비얀시에게 배우고 싶다면 돌라나르 여관 바로 북쪽으로 가면 만날 수 있을 거예요.', `MaleText_loc4`='拜恩希在急救方面的技巧已经很知名了。如果你想向她学习的话，你可以到多兰纳尔旅店的北面去找她。', `MaleText_loc5`='拜恩希在急救方面的技巧已經很知名了。如果你想向她學習的話，你可以到多蘭納爾旅店的北面去找她。', `MaleText_loc7`='Las aptitudes de Byancie en primeros auxilios se han mostrado útiles en numerosas ocasiones. Si deseas aprender de ella podrás encontrarla al norte de la posada de Dolanaar.', `FemaleText_loc1`='비얀시의 응급치료 기술이 없었다면 돌라나르의 많은 주민은 생명의 위기를 겪었을 겁니다. 비얀시에게 배우고 싶다면 돌라나르 여관 바로 북쪽으로 가면 만날 수 있을 거예요.', `FemaleText_loc4`='拜恩希在急救方面的技巧已经很知名了。如果你想向她学习的话，你可以到多兰纳尔旅店的北面去找她。', `FemaleText_loc5`='拜恩希在急救方面的技巧已經很知名了。如果你想向她學習的話，你可以到多蘭納爾旅店的北面去找她。', `FemaleText_loc7`='Las aptitudes de Byancie en primeros auxilios se han mostrado útiles en numerosas ocasiones. Si deseas aprender de ella podrás encontrarla al norte de la posada de Dolanaar.' WHERE `ID`=7108;
