UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하시오, $c.', `MaleText_loc4`='你好，$c。', `MaleText_loc5`='你好，$c。', `MaleText_loc7`='Saludos, $c.' WHERE `ID`=7132;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='북녘골 수도원의 멍청이들이 새로 보낸 풋내기로군.', `MaleText_loc4`='修道院的那些傻子给我们送来了鲜肉。', `MaleText_loc5`='修道院的那些傻子給我們送來了鮮肉。', `MaleText_loc7`='Parece que esos idiotas de la Abadía nos han enviado carne fresca.', `FemaleText_loc1`='북녘골 수도원의 멍청이들이 새로 보낸 풋내기로군.', `FemaleText_loc4`='修道院的那些傻子给我们送来了鲜肉。', `FemaleText_loc5`='修道院的那些傻子給我們送來了鮮肉。', `FemaleText_loc7`='Parece que esos idiotas de la Abadía nos han enviado carne fresca.' WHERE `ID`=7133;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 땅은 이제 데피아즈 결사단의 것이다!', `MaleText_loc4`='这片土地现在属于迪菲亚兄弟会！', `MaleText_loc5`='這片土地現在屬於迪菲亞兄弟會!', `MaleText_loc7`='¡Ahora esta tierra pertenece a la Hermandad Defias!', `FemaleText_loc1`='이 땅은 이제 데피아즈 결사단의 것이다!', `FemaleText_loc4`='这片土地现在属于迪菲亚兄弟会！', `FemaleText_loc5`='這片土地現在屬於迪菲亞兄弟會!', `FemaleText_loc7`='¡Ahora esta tierra pertenece a la Hermandad Defias!' WHERE `ID`=7134;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 펄볼그일족 최후의 생존자요. 현재 나무구렁 일족은 타락하지 않은 상태로 남아 있지만, 외부 세력에 의해 우리와 똑같은 위협을 받고 있소이다. 대부분 불가능한 일이라고 생각하더군. 타락을 면한 펄볼그가 존재한다는 사실이 믿기지 않는 모양이지...$B$B너무나 쉽게 우리를 적대시하는 자들에게 화가 난 우리 형제들은, 이제 가까이 다가오는 자를 모두 공격하고 있소. 그러니 아무도 믿지 못하는 게 당연하지.$B$B하지만 당신이 평화롭게 접근한다면 당신을 동맹으로 생각할지도 모르오.', `MaleText_loc4`='我们是熊怪家族仅剩的成员了……木喉部落还未堕落，但是其他部落对我们怀有相同的敌意；有熊怪能免于堕落……很多人都认为这是不可能的……$B$B我的兄弟们对那么急于与我们为敌的家伙非常生气，现在他们已经开始攻击任何靠近我们的生物；他们谁都不信任。$B$B但是，如何你能努力证明想要和他们和平相处的话，他们或许会把你当作盟友的。', `MaleText_loc5`='我們是熊怪家族僅剩的成員了...木喉部族還未墮落，但是其他部族對我們懷有相同的敵意;有熊怪能免於墮落...很多人都認為這是不可能的...$b$b我的兄弟們對那麼急於與我們為敵的傢伙非常生氣，現在他們已經開始攻擊任何靠近我們的生物;他們誰都不信任。$B$B但是，如何你能努力證明想要和他們和平相處的話，他們或許會把你當作盟友的。', `MaleText_loc7`='Somos la última raza fúrbolg... La tribu Fauces de Madera sigue incorrupta, aunque tenemos que enfrentarnos a la misma hostilidad por parte de los forasteros; la mayoría cree que es imposible... que no puede haber ningún fúrbolg que haya escapado a la corrupción... $B$BFuriosos con los que se esfuerzan por ganar enemigos demasiado deprisa, mis hermanos atacan a todo el que se acerca; no confían en nadie.$B$BPero quizá, y si te esfuerzas porque tu presencia sea pacífica, llegarán a verte como $gun aliado:una aliada;.' WHERE `ID`=7135;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나무구렁 일족에게 제가 동지라는 걸 입증하려면 어떻게 해야 하죠?', `MaleText_loc4`='我怎么才能向木喉的熊怪证明我自己呢？', `MaleText_loc5`='我怎麼才能向木喉的熊怪證明我自己呢?', `MaleText_loc7`='¿Cómo puedo demostrar mi valía al fúrbolg Fauces de Madera?', `FemaleText_loc1`='나무구렁 일족에게 제가 동지라는 걸 입증하려면 어떻게 해야 하죠?', `FemaleText_loc4`='我怎么才能向木喉的熊怪证明我自己呢？', `FemaleText_loc5`='我怎麼才能向木喉的熊怪證明我自己呢?', `FemaleText_loc7`='¿Cómo puedo demostrar mi valía al fúrbolg Fauces de Madera?' WHERE `ID`=7136;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='같은 편에서 싸우고 있다는 걸 보여 주어야만 하오. 나무구렁 일족이 당장은 공격할지도 모르나, 당신이 평화로운 동맹 관계를 입증할 길을 부지런히 찾는다면 반드시 길이 보일 거요.$B$B나무구렁 펄볼그를 공격하면 그들과 동지가 될 가능성이 많이 줄어든다는 것을 기억해 두시오.$B$B악령숲 곳곳에 있는 마른가지 펄볼그와 싸우는 걸로 시작하는 게 좋을 거요. 그 펄볼그들은 나무구렁 일족의 적이므로, 녀석들을 쓰러뜨리면 나무구렁 일족과의 관계가 크게 향상될 것이오.', `MaleText_loc4`='你必须想办法来证明你们两个是在同一条战线上的。尽管现在木喉可能会攻击你，但如果你够勤奋的话，你就会找到办法的。$B$B你一定要记住，任何对木喉熊怪的攻击都会大大降低你们赢得与他们结盟的机会。$B$B有个不错的着手点就是在费伍德森林的许多部分都发现的死木熊怪。这些熊怪是木喉部落的敌人，杀了他们将会大大提高你在木喉中的地位。', `MaleText_loc5`='你必須想辦法來證明你們兩個是在同一條戰線上的。儘管現在木喉可能會攻擊你，但如果你夠勤奮的話，你就會找到辦法的。$B$B你一定要記住，任何對木喉熊怪的攻擊都會大大降低你們贏得與他們結盟的機會。$B$B有個不錯的著手點就是在費伍德森林的許多部分都發現的死木熊怪。這些熊怪是木喉部族的敵人，殺了他們將會大大提高你在木喉中的地位。', `MaleText_loc7`='Debes encontrar un modo de demostrar que tu lucha está de su lado. Aunque los Fauces de Madera te ataquen, si eres diligente encontrarás el modo de hacerlo.$B$BDebes recordar que cualquier ataque directo a los Fauces de Madera reducirá notablemente tus oportunidades de que lleguen a considerarte como $gun aliado:una aliada;.$B$BUn buen punto de partida serían los Muertobosque, que habitan muchos puntos de Frondavil. Esos fúrbolgs son los enemigos de la tribu Fauces de Madera y aniquilarlos mejoraría considerablemente tu reputación con los Fauces de Madera.' WHERE `ID`=7137;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 나무구렁 일족은 당신이 요새를 무사히 지나갈 수 있도록 허락해 줄 수 있지만, 먼저 당신이 우리의 도움을 받을 자격이 있다는 것을 증명해 보여야 하오.', `MaleText_loc4`='我们能让你安全通过这儿，但是，你得证明自己值得我们给予帮助。', `MaleText_loc5`='我們能讓你安全通過這兒，但是，你得證明自己值得我們給予幫助。', `MaleText_loc7`='Nosotros, los Fauces de Madera, podemos garantizarte un paso seguro a través del pasadizo, pero antes debes demostrar que mereces nuestra ayuda.' WHERE `ID`=7138;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겨울눈 펄볼그에 대해 말씀해주십시오.', `MaleText_loc4`='冬泉熊怪怎么样？', `MaleText_loc5`='冬泉熊怪怎麼樣?', `MaleText_loc7`='¿Y qué hay de los fúrbolgs Nevada?', `FemaleText_loc1`='겨울눈 펄볼그에 대해 말씀해주세요.', `FemaleText_loc4`='冬泉熊怪怎么样？', `FemaleText_loc5`='冬泉熊怪怎麼樣?', `FemaleText_loc7`='¿Y qué hay de los fúrbolgs Nevada?' WHERE `ID`=7139;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳 여명의 설원에 사는 겨울눈 펄볼그는 한때 우리의 동맹이었지... 하지만 어느 날, 모든 게 변해 버렸소.$B$B그들은 대족장의 이상한 명령에 따라 우리 일족을 포함해 그들이 마주치는 모든 자들을 공격하기 시작한 거요. 이제는 자신들을 고립시키고 있소이다.', `MaleText_loc4`='居住在冬泉谷的寒水熊怪曾经是我们的盟友……但是有一天，这一切都改变了。$B$B他们听从高级首领的号令，开始攻击他们接触到的任何生物，包括我们的部族。他们现在几乎不与外界接触了……', `MaleText_loc5`='居住在冬泉谷的冬泉熊怪曾經是我們的盟友...但是有一天，這一切都改變了。$B$B他們聽從酋長的號令，開始攻擊他們接觸到的任何生物，包括我們的部族。他們現在幾乎不與外界接觸了...', `MaleText_loc7`='Los fúrbolgs Nevada que habitan en Cuna del Invierno fueron una vez nuestros aliados... Pero un día cambiaron.$B$BGuiados por las extrañas demandas de su gran jefe, comenzaron a atacar a todos con los que entraban en contacto, incluyendo a nuestra tribu. Ahora solo se relacionan entre ellos...' WHERE `ID`=7140;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 귀찮게 하지 말라고... 너희는 모두 똑같은 것들이야...', `MaleText_loc4`='请不要打扰我……你们这种人都一样……', `MaleText_loc5`='請不要打擾我...你們這種人都一樣...', `MaleText_loc7`='Por favor, no me molestes... Los de tu especie sois todos iguales...' WHERE `ID`=7141;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물건을 사고 싶습니다.', `MaleText_loc4`='我想从你这里买点东西。', `MaleText_loc5`='我想從你這裡買點東西。', `MaleText_loc7`='Me gustaría comprarte algo.', `FemaleText_loc1`='물건을 사고 싶습니다.', `FemaleText_loc4`='我想从你这里买点东西。', `FemaleText_loc5`='我想從你這裡買點東西。', `FemaleText_loc7`='Me gustaría comprarte algo.' WHERE `ID`=7142;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 같은 부류를 믿는 일은 거의 없지만 당신만큼은 우리의 친구라는 것을 알 수가 있소, $n.', `MaleText_loc4`='我只信任你所在种族中的少数人，$n。但是我把你当朋友。', `MaleText_loc5`='我只信任你所在種族中的少數人，$n。但是我把你當朋友。', `MaleText_loc7`='Tengo muy poca confianza en los de tu clase, $n. Pero podría decirse que eres $gun amigo:una amiga;.' WHERE `ID`=7143;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 그래. 알겠소.$B$B썩 사라지시오. 당신이 우리 일족의 몇몇에게 신뢰를 얻었을지 모르겠지만, 나한테는 그것만으로는 부족하지!', `MaleText_loc4`='是的，是的。我看到你了。$B$B在去找你的路上。你可能已经赢得了一些人的信任，但要向我证明可并不仅仅如此！', `MaleText_loc5`='是的，是的。我看到你了。$B$B在去找你的路上。你可能已經贏得了一些人的信任，但要向我證明可並不僅僅如此!', `MaleText_loc7`='Sí, sí. Te veo.$B$BNo te separes de tu camino. Puede que te hayas ganado la confianza de unos pocos, ¡pero aún necesitarás más tiempo para probarte ante mí!' WHERE `ID`=7144;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수업이 시작됐다!', `MaleText_loc4`='正在上课！', `MaleText_loc5`='正在上課!', `MaleText_loc7`='¡Estamos dando clase!' WHERE `ID`=7145;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너한테 낭비할 시간은 없다, $r. 내 눈앞에서 사라져 버리라고.', `MaleText_loc4`='我没时间理你，$r。你还是继续走你的路吧。', `MaleText_loc5`='我沒時間理你，$r。你還是繼續走你的路吧。', `MaleText_loc7`='No tengo tiempo para ti, $r. Sigue tu camino.' WHERE `ID`=7146;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 우리의 진정한 동맹이라는 걸 증명해 보인다면, 한번 생각해 볼 수도 있지... 훈련 말이야.', `MaleText_loc4`='如果你能证明自己是个真正的盟友，我或许会考虑训练你的……', `MaleText_loc5`='如果你能證明自己是個真正的盟友，我或許會考慮訓練你的...', `MaleText_loc7`='Si demuestras que eres $gun verdadero aliado:una verdadera aliada;, quizás me plantee instruirte...' WHERE `ID`=7147;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='환영하네, $n! 재봉술 훈련을 받고 싶은 건가?', `MaleText_loc4`='欢迎你，$n！你想学作一名裁缝？', `MaleText_loc5`='歡迎你，$n!你想學作一名裁縫?', `MaleText_loc7`='¡$GBienvenido:Bienvenida;, $n! ¿Estás $ginteresado:interesada; en aprender sastrería?' WHERE `ID`=7148;
