UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성스러운 빛을 피하려고 하지 마십시오, $c|1이여;여;. 언젠가 당신의 목숨을 구해 주는 유일한 길이 될 수 있습니다.', `MaleText_loc4`='别与圣光作对，$c，或许有一天它能拯救你。', `MaleText_loc5`='別與聖光作對，$c，或許有一天它能拯救你。', `MaleText_loc7`='No des la espalda a la Luz, $c, puede ser lo único que te salve algún día.', `FemaleText_loc1`='성스러운 빛을 피하려고 하지 마세요, $c|1이여;여;. 언젠가 당신의 목숨을 구해줄 유일한 길이 될 수 있습니다.', `FemaleText_loc4`='别与圣光作对，$c，或许有一天它能拯救你。', `FemaleText_loc5`='別與聖光作對，$c，或許有一天它能拯救你。', `FemaleText_loc7`='No des la espalda a la Luz, $c, puede ser lo único que te salve algún día.' WHERE `ID`=7155;
