UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성스러운 빛이 함께하기를, $n. 무엇을 도와 드리면 되겠습니까?', `MaleText_loc4`='愿圣光与你同在，$n。我能为你做什么吗？', `MaleText_loc5`='願聖光與你同在，$n。我能為你做什麼嗎?', `MaleText_loc7`='Espero que la Luz esté contigo, $n. ¿Puedo hacer algo por ti?', `FemaleText_loc1`='성스러운 빛이 함께하기를, $n. 무엇을 도와 드리면 되겠습니까?', `FemaleText_loc4`='愿圣光与你同在，$n。我能为你做什么吗？', `FemaleText_loc5`='願聖光與你同在，$n。我能為你做什麼嗎?', `FemaleText_loc7`='Espero que la Luz esté contigo, $n. ¿Puedo hacer algo por ti?' WHERE `ID`=7159;
