UPDATE `locales_broadcast_text` SET `MaleText_loc1`='몸가짐을 삼가십시오, $c|1이여;여;. 우리의 예를 존중하지 않으면 당신과 당신 일족에 저주가 내릴 것입니다.', `MaleText_loc4`='你当心些，$c。尊重我们的方式，否则你和你的人们就会受到诅咒。', `MaleText_loc5`='你當心些，$c。尊重我們的方式，否則你和你的人們就會受到詛咒。', `MaleText_loc7`='Estate alerta, $c. Respeta nuestras costumbres o una maldición caerá sobre ti y sobre los tuyos.', `FemaleText_loc1`='몸가짐을 삼가게, $c|1이여;여;. 우리의 예를 존중하지 않으면 당신과 당신 일족에 저주가 내릴 거야.', `FemaleText_loc4`='你当心些，$c。尊重我们的方式，否则你和你的人们就会受到诅咒。', `FemaleText_loc5`='你當心些，$c。尊重我們的方式，否則你和你的人們就會受到詛咒。', `FemaleText_loc7`='Estate alerta, $c. Respeta nuestras costumbres o una maldición caerá sobre ti y sobre los tuyos.' WHERE `ID`=7161;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사제의 예를 배우러 여기까지 오셨다면, 최선을 다해 가르쳐 드리도록 하겠습니다.', `MaleText_loc4`='如果这就是你来此的目的，我们会尽一切可能训练你，帮助你成为真正的牧师。', `MaleText_loc5`='如果這就是你來此的目的，我們會盡一切可能訓練你，幫助你成為真正的牧師。', `MaleText_loc7`='Hacer lo que mí poder para instruir tú en las costumbres sacerdotales, si eso es por lo que tú estar aquí.', `FemaleText_loc1`='사제의 예를 배우러 여기까지 오셨다면, 최선을 다해 가르쳐 드리도록 하겠습니다.', `FemaleText_loc4`='如果这就是你来此的目的，我们会尽一切可能训练你，帮助你成为真正的牧师。', `FemaleText_loc5`='如果這就是你來此的目的，我們會盡一切可能訓練你，幫助你成為真正的牧師。', `FemaleText_loc7`='Hacer lo que mí poder para instruir tú en las costumbres sacerdotales, si eso es por lo que tú estar aquí.' WHERE `ID`=7162;
