UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엘룬께서 그대와 함께하시기를, $c|1이여;여;.', `MaleText_loc4`='愿月神与你同在，$c。', `MaleText_loc5`='願伊露恩與你同在，$c。', `MaleText_loc7`='Que Elune esté contigo, $c.', `FemaleText_loc1`='엘룬께서 그대와 함께하시기를, $c|1이여;여;.', `FemaleText_loc4`='愿月神与你同在，$c。', `FemaleText_loc5`='願伊露恩與你同在，$c。', `FemaleText_loc7`='Que Elune esté contigo, $c.' WHERE `ID`=7165;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나의 지혜와 지식은 곧 그대의 지혜와 지식이 될 것입니다. 무엇을 도와 드릴까요, $n?', `MaleText_loc4`='我的智慧就是你的智慧，我的知识也一样。我能为你做什么，$n？', `MaleText_loc5`='我的智慧就是你的智慧，我的知識也一樣。我能為你做什麼，$n?', `MaleText_loc7`='Mi sabiduría es tuya, así como mi conocimiento. ¿Qué puedo hacer por ti, $n?', `FemaleText_loc1`='나의 지혜와 지식은 곧 그대의 지혜와 지식이 될 것입니다. 무엇을 도와 드릴까요, $n?', `FemaleText_loc4`='我的智慧就是你的智慧，我的知识也一样。我能为你做什么，$n？', `FemaleText_loc5`='我的智慧就是你的智慧，我的知識也一樣。我能為你做什麼，$n?', `FemaleText_loc7`='Mi sabiduría es tuya, así como mi conocimiento. ¿Qué puedo hacer por ti, $n?' WHERE `ID`=7166;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사제의 길에 대해 더 배우고 싶습니다.', `MaleText_loc4`='我想接受更多的牧师技能方面的训练。', `MaleText_loc5`='我想接受更多的牧師技能方面的訓練。', `MaleText_loc7`='Deseo continuar mi formación como sacerdote.', `FemaleText_loc1`='사제의 길에 대해 더 배우고 싶습니다.', `FemaleText_loc4`='我想接受更多的牧师技能方面的训练。', `FemaleText_loc5`='我想接受更多的牧師技能方面的訓練。', `FemaleText_loc7`='Deseo continuar mi formación como sacerdotisa.' WHERE `ID`=7167;
