UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 누굴 좀 찾고 있으니 내버려두게나... 제발... 중요한 일이라네.', `MaleText_loc4`='我在找人，$c。请不要打扰我……这对我很重要。', `MaleText_loc5`='我在找人，$c。請不要打擾我...這對我很重要。', `MaleText_loc7`='Yo buscar a alguien, $c. Por favor, déjame en paz... es importante que yo encontrarlos.' WHERE `ID`=7170;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 동부 왕국에서 온 사신이네, $n. 이곳으로 오는 사제들이 올바른 지도를 받을 수 있도록 하기 위해서 파견되었지.', `MaleText_loc4`='我是来自东部王国的信使，$n。我到这儿来是确保来此的牧师已经受到正确指示。', `MaleText_loc5`='我是來自東部王國的信差，$n。我到這兒來是確保來此的牧師已經受到正確指示。', `MaleText_loc7`='Yo ser un mensajero de los Reinos del Este, $n. Yo haber sido enviado para que los sacerdotes que viajan aquí disfrutar de protección puedan.' WHERE `ID`=7171;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조용히 하세요! 스승님이 말씀하시는 중이잖습니까?', `MaleText_loc4`='安静！你没听见主人在讲话吗？', `MaleText_loc5`='安靜!你沒聽見主人在講話嗎?', `MaleText_loc7`='¡Silencio! ¿No puedes ver que está hablando el maestro?', `FemaleText_loc1`='조용히 하세요! 스승님이 말씀하시는 중이잖습니까?', `FemaleText_loc4`='安静！你没听见主人在讲话吗？', `FemaleText_loc5`='安靜!你沒聽見主人在講話嗎?', `FemaleText_loc7`='¡Silencio! ¿No puedes ver que está hablando el maestro?' WHERE `ID`=7172;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잡담할 시간에 경청하도록 하세요.', `MaleText_loc4`='少说废话，认真听讲。', `MaleText_loc5`='少說廢話，認真聽講。', `MaleText_loc7`='Dedica menos tiempo a hablar y más a escuchar.', `FemaleText_loc1`='잡담할 시간에 경청하도록 하세요.', `FemaleText_loc4`='少说废话，认真听讲。', `FemaleText_loc5`='少說廢話，認真聽講。', `FemaleText_loc7`='Dedica menos tiempo a hablar y más a escuchar.' WHERE `ID`=7173;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의용군단을 만들어 내려면 집중을 해야만 해요!', `MaleText_loc4`='如果要孵化出我们的龙的话，我们必须集中精力！', `MaleText_loc5`='如果要孵化出我們自己的龍軍團的話，我們必須集中精力!', `MaleText_loc7`='¡Debemos centrarnos si queremos que desove nuestro Vuelo!', `FemaleText_loc1`='우리의용군단을 만들어 내려면 집중을 해야만 해요!', `FemaleText_loc4`='如果要孵化出我们的龙的话，我们必须集中精力！', `FemaleText_loc5`='如果要孵化出我們自己的龍軍團的話，我們必須集中精力!', `FemaleText_loc7`='¡Debemos centrarnos si queremos que desove nuestro Vuelo!' WHERE `ID`=7174;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조용히 하세요! 난 이 강의 내용을 한순간도 놓칠 수 없으니까!', `MaleText_loc4`='肃静！我不能漏掉这次讲座任何一句话！', `MaleText_loc5`='肅靜!我不能漏掉這次講座任何一句話!', `MaleText_loc7`='¡Silencio! ¡No puedo permitirme perder ni una sola de sus palabras!', `FemaleText_loc1`='조용히 하세요! 난 이 강의 내용을 한순간도 놓칠 수 없으니까!', `FemaleText_loc4`='肃静！我不能漏掉这次讲座任何一句话！', `FemaleText_loc5`='肅靜!我不能漏掉這次講座任何一句話!', `FemaleText_loc7`='¡Silencio! ¡No puedo permitirme perder ni una sola de sus palabras!' WHERE `ID`=7175;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='학생 복장을 갖추는 걸 잊으셨나요? 스컬지의 세계 정복보다 옷맵시가 더 중요하다고 생각하는 겁니까?', `MaleText_loc4`='你忘记自己的学生服了吗？你认为时尚比亡灵天灾的统治更重要吗？', `MaleText_loc5`='你忘記自己的學生服了嗎?你認為時尚比天譴軍團的統治更重要嗎?', `MaleText_loc7`='¿Has olvidado tu uniforme de alumno? ¿Crees que la moda es más importante que la dominación de la Plaga?', `FemaleText_loc1`='학생 복장을 갖추는 걸 잊으셨나요? 스컬지의 세계 정복보다 옷맵시가 더 중요하다고 생각하는 겁니까?', `FemaleText_loc4`='你忘记自己的学生服了吗？你认为时尚比亡灵天灾的统治更重要吗？', `FemaleText_loc5`='你忘記自己的學生服了嗎?你認為時尚比天譴軍團的統治更重要嗎?', `FemaleText_loc7`='¿Has olvidado tu uniforme de alumno? ¿Crees que la moda es más importante que la dominación de la Plaga?' WHERE `ID`=7176;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어제 숙제는 다 했나요? 그렇다면 어서 내 옆에 앉으라고요!', `MaleText_loc4`='你完成了昨天的作业吗？要是完成了，就过来跟我坐一块吧！', `MaleText_loc5`='你完成了昨天的作業嗎?要是完成了，就過來跟我坐一塊吧!', `MaleText_loc7`='¿Terminaste las tareas de ayer? ¡Si es así, siéntate a mi lado!', `FemaleText_loc1`='어제 숙제는 다 했나요? 그렇다면 어서 내 옆에 앉으라고요!', `FemaleText_loc4`='你完成了昨天的作业吗？要是完成了，就过来跟我坐一块吧！', `FemaleText_loc5`='你完成了昨天的作業嗎?要是完成了，就過來跟我坐一塊吧!', `FemaleText_loc7`='¿Terminaste las tareas de ayer? ¡Si es así, siéntate a mi lado!' WHERE `ID`=7177;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서는 몸가짐을 잘 하세요. 스승님은 뭐든 다 보고 계시니까...', `MaleText_loc4`='小心点，$g男孩:女孩;。主人能洞察一切……', `MaleText_loc5`='小心點，$g男孩:女孩;。主人能洞察一切...', `MaleText_loc7`='Vigila tus pasos aquí, $gchico:chica;. El maestro lo ve todo...', `FemaleText_loc1`='여기서는 몸가짐을 잘 하세요. 스승님은 뭐든 다 보고 계시니까...', `FemaleText_loc4`='小心点，$g男孩:女孩;。主人能洞察一切……', `FemaleText_loc5`='小心點，$g男孩:女孩;。主人能洞察一切...', `FemaleText_loc7`='Vigila tus pasos aquí, $gchico:chica;. El maestro lo ve todo...' WHERE `ID`=7178;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='교과서는 가져왔나요? 같이 봐도 될까요?', `MaleText_loc4`='你带来了课本吗？我能和你一起看吗？', `MaleText_loc5`='你帶來了課本嗎?我能和你一起看嗎?', `MaleText_loc7`='¿Has traído tus libros de texto? ¿Puedo verlos contigo?', `FemaleText_loc1`='교과서는 가져왔나요? 같이 봐도 될까요?', `FemaleText_loc4`='你带来了课本吗？我能和你一起看吗？', `FemaleText_loc5`='你帶來了課本嗎?我能和你一起看嗎?', `FemaleText_loc7`='¿Has traído tus libros de texto? ¿Puedo verlos contigo?' WHERE `ID`=7179;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 도대체 여기서 뭐 하고 있는 건가? 어서 학생다운 복장을 갖추고 공부해라!', `MaleText_loc4`='我可以问，你在这里做什么吗？穿上你的学生服装，然后学习！', `MaleText_loc5`='我可以問，你在這裡做什麼嗎?穿上你的學生服裝，然後學習!', `MaleText_loc7`='¿Qué, si se me permite preguntar, estás haciendo aquí? ¡Ponte el uniforme y estudia!' WHERE `ID`=7180;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조용히 해! 우리의 역병 걸린 용들이 스스로 알을 깨고 나와서 저절로 훈련을 할 거라 생각하는 건가?', `MaleText_loc4`='肃静！你认为那些被感染的龙会自己孵蛋并哺育幼龙吗？', `MaleText_loc5`='肅靜!你認為那些瘟疫龍會自己孵蛋並哺育幼龍嗎?', `MaleText_loc7`='¡Silencio! ¿Crees que los dragones apestados nacerán y se adiestrarán solos?' WHERE `ID`=7181;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불타는 평원에서 왔나? 내 검은용 알은 가져왔는가?', `MaleText_loc4`='你来自燃烧平原吗？你有黑龙蛋吗？', `MaleText_loc5`='你來自燃燒平原嗎?你有黑龍蛋嗎?', `MaleText_loc7`='¿Has venido aquí desde Las Estepas Ardientes? ¿Tienes mis huevos de dragón Negro?' WHERE `ID`=7182;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 마음은 집중이 되어 있지 않군. 나에게 뭔가 숨기는 거라도 있나?', `MaleText_loc4`='你的精神不够集中。你对我隐瞒着什么吗?', `MaleText_loc5`='你的精神不夠集中。你對我隱瞞著什麼嗎?', `MaleText_loc7`='Tu mente no está centrada. ¿Me estás ocultando algo?' WHERE `ID`=7183;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 주변에서 뭔가 동요가 느껴져...', `MaleText_loc4`='我感觉一场动乱潜伏在你周围……', `MaleText_loc5`='我感覺一場動亂潛伏在你周圍...', `MaleText_loc7`='Siento que algo te perturba...' WHERE `ID`=7185;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 미래가 흐릿하군. 집중을 한 후에 다시 물어 보도록 하게.', `MaleText_loc4`='你的未来乌云密布。集中精力，再问一次。', `MaleText_loc5`='你的未來烏雲密佈。集中精力，再問一次。', `MaleText_loc7`='Tu futuro está nublado. Concéntrate y pregunta de nuevo.' WHERE `ID`=7186;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 학생 같아 보이지 않는데...', `MaleText_loc4`='你看起来不像是个学生……', `MaleText_loc5`='你看起來不像是個學生...', `MaleText_loc7`='No pareces un estudiante...' WHERE `ID`=7187;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 교과서 34쪽을 보면 드워프를 해부하는 그림이 있다...', `MaleText_loc4`='如果你翻到34页的话，你会看见矮人被解剖的图片……', `MaleText_loc5`='如果你翻到34頁的話，你會看見矮人被解剖的圖片...', `MaleText_loc7`='Si vas a la página 34 de tu libro verás una ilustración que muestra la disección de un enano...' WHERE `ID`=7188;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='역병 걸린 용은 아무 거나 먹지 않는다는 것에 주목하도록. 용들은 겁에 질린 살덩어리만을 만족스러워 할 것이다.', `MaleText_loc4`='看看龙食谱的精妙吧。只有恐惧之肉才能满足他们。', `MaleText_loc5`='看看瘟疫龍食譜的精妙吧。只有恐懼之肉才能滿足他們。', `MaleText_loc7`='Toma nota de la delicadeza de la dieta de un dragón apestado. Solo vale la carne aterrorizada.' WHERE `ID`=7189;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 불타는 평원에서 검은용 알이 오기를 기다리고 있다. 검은용 연구를 통해 우리의 지식이 크게 확장되리라 믿는다.', `MaleText_loc4`='我们在等一批来自燃烧平原的黑龙蛋。我们相信，通过研究我们能大幅度地增进知识。', `MaleText_loc5`='我們在等一批來自燃燒平原的黑龍蛋。我們相信，通過研究我們能大幅度地增進知識。', `MaleText_loc7`='Aguardamos una tanda de huevos de dragón Negro de las Estepas Ardientes. Creemos que, a través de su estudio, avanzaremos en nuestros conocimientos drásticamente.' WHERE `ID`=7190;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리에게 있는 가장 오래된 용 알 무리도 성숙기까지는 아직 한참이나 남았지만 인내하며 공부한다면 머지않아용군단이 준비될 것이라 확신한다.', `MaleText_loc4`='最早产下的龙蛋尚未成熟，但是通过耐心地研究，飞龙很快就能孵出了。', `MaleText_loc5`='最早產下的龍蛋尚未成熟，但是通過耐心地研究，相信我們的龍群很快就能準備完畢了。', `MaleText_loc7`='Nuestra nidada de dragones más antigua todavía está lejos de la madurez, pero con paciencia y estudio, estamos seguros de que el Vuelo pronto estará listo.' WHERE `ID`=7191;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어제 현지 조사에서 마르두크가 보여 줬듯이 용은 죽은 지 얼마 되지 않은 인간의 고기도 먹긴 하지만 그 인간이 천천히 그리고 고통스럽게 죽은 경우에만 그 고기를 먹는다.', `MaleText_loc4`='从昨天的实地考察来看，马杜克表示巨龙可以食用近期被杀人类的肉，但是只有痛苦缓慢地死去人的肉才行。', `MaleText_loc5`='從昨天的實地考察來看，馬杜克表示巨龍可以食用近期被殺人類的肉，但是只有痛苦緩慢地死去人的肉才行。', `MaleText_loc7`='En el viaje de estudios que hicimos ayer, Marduk nos enseñó que los dragones tolerarían la carne de humanoides que hubieran sido asesinados recientemente, pero solo si murieron lenta y horriblemente.' WHERE `ID`=7192;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내일 장래가 유망한 우리 어린 용들의 훈련이 시작되니 개껌... 아니 용껌은 꼭 지참하도록.', `MaleText_loc4`='明天我们将开始训练这些大有前途的龙，别忘了带上你的玩具骨头。', `MaleText_loc5`='明天我們將開始訓練這些大有前途的龍，別忘了帶上你的嚼咬玩具。', `MaleText_loc7`='Mañana comenzaremos la instrucción de nuestros prometedores dragones, así que no olviden sus mordedores.' WHERE `ID`=7193;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕의 군단이 점점 더 크게 규합되고 있다. 반드시 우리의 일정이 그분의 계획을 제대로 지원할 수 있어야만 한다.', `MaleText_loc4`='巫妖王的势力渐渐扩大。我们的时间安排必须支持他的计划。', `MaleText_loc5`='巫妖王的勢力漸漸擴大。我們的時間安排必須支援他的計畫。', `MaleText_loc7`='Las fuerzas del Rey Exánime se están intensificando. Es fundamental que nuestro trabajo sustente sus planes.' WHERE `ID`=7194;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용의 식사를 준비할 때에는 용이 보는 앞에서 포로를 고문하는 것을 잊지 말도록. 식전 오락에 아주 좋은 반응을 보이니까 말이야.', `MaleText_loc4`='当准备龙的食物时，一定要给它找点乐子。它对饭前娱乐反应不错。', `MaleText_loc5`='當準備龍的食物時，一定要當著龍的面折磨囚犯。它對飯前娛樂反應不錯。', `MaleText_loc7`='Al preparar la comida del dragón, asegúrate de torturar el prisionero delante de él. Siempre responde bien a este entretenimiento antes de la comida.' WHERE `ID`=7195;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 코도는 애초에 길들인 것과는 전혀 딴판으로 생겼습니다! 코도 유인기가 먹혀 들지 궁금합니다.', `MaleText_loc4`='这只科多兽显然不是我最初召唤的那只。我在想科多兽诱引器是否能为我所用。', `MaleText_loc5`='這隻科多獸顯然不是我最初召喚的那隻。我在想科多獸誘引器是否能為我所用。', `MaleText_loc7`='¡Este kodo no se parece en nada a la bestia a la que atraje! Me pregunto si podría utilizar el combobulador sobre mí mismo.', `FemaleText_loc1`='이 코도는 애초에 길들인 것과는 전혀 딴판으로 생겼습니다! 코도 유인기가 먹혀 들지 궁금합니다.', `FemaleText_loc4`='这只科多兽显然不是我最初召唤的那只。我在想科多兽诱引器是否能为我所用。', `FemaleText_loc5`='這隻科多獸顯然不是我最初召喚的那隻。我在想科多獸誘引器是否能為我所用。', `FemaleText_loc7`='¡Este kodo no se parece en nada a la bestia a la que atraje! Me pregunto si podría utilizar el combobulador sobre mí misma.' WHERE `ID`=7196;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='역병지대는 스컬지를 공격하기에 아주 좋은 장소랍니다!', `FemaleText_loc4`='瘟疫之地是对付天灾亡灵绝佳的地方！', `FemaleText_loc5`='瘟疫之地是對付天譴軍團絕佳的地方!', `FemaleText_loc7`='¡Las Tierras de la Peste son un lugar excelente para atacar a la Plaga!' WHERE `ID`=7197;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여명의 계략을 하나 더 주시겠어요, 베티나? 다시 시험해 보고 싶어요.', `MaleText_loc4`='贝蒂娜，我能再要一个黎明先锋吗？我想再次测试一下……', `MaleText_loc5`='貝蒂娜，我能再要一個黎明先鋒嗎?我想再次測試一下...', `MaleText_loc7`='¿Puedes darme otro Gambito del Alba, Betina? Quiero intentarlo otra vez...', `FemaleText_loc1`='여명의 계략을 하나 더 주시겠어요, 베티나? 다시 시험해 보고 싶어요.', `FemaleText_loc4`='贝蒂娜，我能再要一个黎明先锋吗？我想再次测试一下……', `FemaleText_loc5`='貝蒂娜，我能再要一個黎明先鋒嗎?我想再次測試一下...', `FemaleText_loc7`='¿Puedes darme otro Gambito del Alba, Betina? Quiero intentarlo otra vez...' WHERE `ID`=7198;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='화살이 떨어졌어요! 더 몰려온다면 혼자서 처리하셔야 합니다.', `FemaleText_loc4`='我的箭用光了！如果还有来进攻的话，你们就要靠自己对付了，我的朋友。', `FemaleText_loc5`='我的箭用光了!如果還有來進攻的話，你們就要靠自己對付了，我的朋友。', `FemaleText_loc7`='¡Me he quedado sin flechas! Me temo que si viene alguno más tendrás que ocuparte tú de ellos.' WHERE `ID`=7199;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잠깐... 들었어요? 서쪽에서 뭔가 접근하고 있어요!', `FemaleText_loc4`='等等……你听到了吗？有东西从西面逼近了！', `FemaleText_loc5`='等等...你聽到了嗎?有東西從西面逼近了!', `FemaleText_loc7`='Espera... ¿has oído eso? ¡Algo se aproxima desde el Oeste!' WHERE `ID`=7200;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='엘룬이시여! 감사합니다. 그대가 없었다면 살아남을 수 없었을지도 몰라요.', `FemaleText_loc4`='赞美月神！要是没有你这个朋友，我不知道自己还能不能生还。', `FemaleText_loc5`='讚美伊露恩!要是沒有你這個朋友，我不知道自己還能不能生還。', `FemaleText_loc7`='¡Alabada sea Elune! No sé si habría acabado el día con vida si no fuera por ti, $gamigo:amiga;.' WHERE `ID`=7201;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='독이 퍼진 다리가 훨씬 좋아졌습니다. 해독제가 효과가 있었나 봐요. 실례가 안 된다면 저는 상관께 여기서 밝혀진 일을 보고하러 가야겠습니다.', `FemaleText_loc4`='我的腿现在感觉好多了，治疗肯定起作用了。请原谅我，我必须去向我的上级汇报这里发生的事情。', `FemaleText_loc5`='我的腿現在感覺好多了，治療肯定起作用了。請原諒我，我必須去向我的上級彙報這裡發生的事情。', `FemaleText_loc7`='Mi pierna está mucho mejor, la pócima debe de estar haciendo efecto. Si me disculpas, debo ir a informar a mis superiores sobre lo que ha pasado aquí.' WHERE `ID`=7202;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 구역에서 감히 누가 덤비는 것이냐?', `MaleText_loc4`='谁敢在我的领地里向我挑战？！', `MaleText_loc5`='誰敢在我的領地裡向我挑戰?!', `MaleText_loc7`='¡¿Quién osa desafiarme en mis dominios?!' WHERE `ID`=7203;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그저 활을 쏜 것뿐입니다.', `FemaleText_loc4`='我刚刚射了一支箭。', `FemaleText_loc5`='我剛剛射了一支箭。', `FemaleText_loc7`='Yo solo he disparado una flecha.' WHERE `ID`=7204;
