UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 다로우골이여! 천 개의 생명을 드릴게요!', `MaleText_loc4`='哦，达隆郡！我会为你带来无限生机的！', `MaleText_loc5`='哦，達隆郡!我會為你帶來無限生機的!', `MaleText_loc7`='¡Oh, Villa Darrow! ¡Por ti daría mil vidas!', `FemaleText_loc1`='오, 다로우골이여! 천 개의 생명을 드릴게요!', `FemaleText_loc4`='哦，达隆郡！我会为你带来无限生机的！', `FemaleText_loc5`='哦，達隆郡!我會為你帶來無限生機的!', `FemaleText_loc7`='¡Oh, Villa Darrow! ¡Por ti daría mil vidas!' WHERE `ID`=7207;
