UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정의는 반드시 승리할 거예요!', `MaleText_loc4`='圣光力量会胜利的！', `MaleText_loc5`='聖光力量會勝利的!', `MaleText_loc7`='¡La Luz debe prevalecer!', `FemaleText_loc1`='정의는 반드시 승리할 거예요!', `FemaleText_loc4`='圣光力量会胜利的！', `FemaleText_loc5`='聖光力量會勝利的!', `FemaleText_loc7`='¡La Luz debe prevalecer!' WHERE `ID`=7209;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마르두크를 조심하세요! 조심하지 않으면 힘이 약해질 거예요.', `MaleText_loc4`='马杜克，小心！否则你的力量将逐渐消弱。', `MaleText_loc5`='馬杜克，小心!否則你的力量將逐漸消弱。', `MaleText_loc7`='¡Cuidado Marduk! Cuidado o tu fuerza marchitará.', `FemaleText_loc1`='마르두크를 조심하세요! 조심하지 않으면 힘이 약해질 거예요.', `FemaleText_loc4`='马杜克，小心！否则你的力量将逐渐消弱。', `FemaleText_loc5`='馬杜克，小心!否則你的力量將逐漸消弱。', `FemaleText_loc7`='¡Cuidado Marduk! Cuidado o tu fuerza marchitará.' WHERE `ID`=7210;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호르구스가 날 삼켰었어요! 그 이빨은 생각만 해도 소름이 끼쳐요.', `MaleText_loc4`='我被霍古斯吞食了！我还能感觉到他的牙齿噬咬我！', `MaleText_loc5`='我被霍古斯吞食了!我還能感覺到他的牙齒噬咬我!', `MaleText_loc7`='¡Fui devorado por Horgus! ¡Todavía puedo sentir sus dientes!', `FemaleText_loc1`='호르구스가 날 삼켰었어요! 그 이빨은 생각만 해도 소름이 끼쳐요.', `FemaleText_loc4`='我被霍古斯吞食了！我还能感觉到他的牙齿噬咬我！', `FemaleText_loc5`='我被霍古斯吞食了!我還能感覺到他的牙齒噬咬我!', `FemaleText_loc7`='¡Fui devorado por Horgus! ¡Todavía puedo sentir sus dientes!' WHERE `ID`=7211;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경비대장 레드패스! 어떻게 우리를 버릴 수가 있죠?', `MaleText_loc4`='雷德帕斯队长！你怎么能抛弃我们！', `MaleText_loc5`='雷德帕斯隊長!你怎麼能拋棄我們!', `MaleText_loc7`='¡Capitán Rutagrana! ¡Cómo pudiste abandonarnos!', `FemaleText_loc1`='경비대장 레드패스! 어떻게 우리를 버릴 수가 있죠?', `FemaleText_loc4`='雷德帕斯队长！你怎么能抛弃我们！', `FemaleText_loc5`='雷德帕斯隊長!你怎麼能拋棄我們!', `FemaleText_loc7`='¡Capitán Rutagrana! ¡Cómo pudiste abandonarnos!' WHERE `ID`=7212;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 숨을 깊게 들이쉽니다.', `MaleText_loc4`='%s深深地吸了一口气……', `MaleText_loc5`='%s深深地吸了一口氣...', `MaleText_loc7`='%s toma aliento...', `FemaleText_loc1`='%s|1이;가; 숨을 깊게 들이쉽니다.', `FemaleText_loc4`='%s深深地吸了一口气……', `FemaleText_loc5`='%s深深地吸了一口氣...', `FemaleText_loc7`='%s toma aliento...' WHERE `ID`=7213;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='만나서 반갑습니다. 반드시 마가타 주인님을 직접 만나야 하는 일이 아니라면 제게 말씀하시죠.$B$B마가타 님께서 중요한 업무에 집중할 수 있도록 제가 대부분의 일을 처리하고 있습니다. 마가타 님을 알현하시기 전에 저와 의논할 일이 있으시겠죠?', `MaleText_loc4`='很高兴见到你，$c。除非你和我的女主人玛加萨之间有直接交易关系，否则别找我说话。$B$B我帮她处理大部分的事务，让她能集中精力处理更重要的事情。或许在你拜见她之前我们可以谈谈。', `MaleText_loc5`='很高興見到你，$c。除非你和我的女主人瑪加薩之間有直接交易關係，否則別找我說話。$B$B我幫她處理大部分的事務，讓她能集中精力處理更重要的事情。或許在你拜見她之前我們可以談談。', `MaleText_loc7`='Hola, $c. Puedes dirigirte a mí a no ser que necesites resolver algo directamente con la maestra Magatha.$B$BYo soy quien lleva casi todos sus asuntos para que ella pueda concentrarse en temas más importantes. ¿Quizás haya algo que podamos discutir entre nosotros antes acudir a su presencia?' WHERE `ID`=7214;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 안녕하시오?', `MaleText_loc4`='你好，$n。', `MaleText_loc5`='你好，$n。', `MaleText_loc7`='Hola, $n.' WHERE `ID`=7215;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언제든지 말씀만 하십시오. $n, 마가타 님을 잘 보좌해 주셨더군요. 나중에 분명 마가타 님께서 도움을 청하실 날이 있을 겁니다.', `MaleText_loc4`='你随时都可以跟我交谈，$n。你对玛加萨忠心耿耿。我想将来她会召见你的。', `MaleText_loc5`='你隨時都可以跟我交談，$n。你對瑪加薩忠心耿耿。我想將來她會召見你的。', `MaleText_loc7`='Por favor, habla conmigo siempre que quieras, $n. Has servido bien a Magatha. Estoy seguro de que recurrirá a ti en el futuro.' WHERE `ID`=7216;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 나와 맞먹으려고 하지 마라. 실바나스 님은 나의 여왕님이시며 나는 여왕님께서 원하시는 대로 할 것이다.$B$B나에게 경의를 표하지 않는다면 단언컨대 지옥으로 보내 주마.$B$B하지만 네가 어둠의 여왕을 돕겠다면 대화를 나눌 수도 있을 것이다.', `MaleText_loc4`='别把自己当我的同辈来跟我讲话，$c。希尔瓦娜斯是我的女王，我听从她的命令。$B$B要是你不表现出适当的尊重，我敢说我们将为你在扭曲虚空选个更为合适的位置。$B$B但是要是你愿意帮助黑暗女王的话，我们便无话可说了……', `MaleText_loc5`='別把自己當我的同輩來跟我講話，$c。希瓦娜斯是我的女王，我聽從她的命令。$B$B要是你不表現出適當的尊重，我敢說我們將為你在扭曲虛空選個更為合適的位置。$B$B但是要是你願意幫助黑暗女王的話，我們便無話可說了...', `MaleText_loc7`='No presumas de hablar conmigo como si fueras mi igual, $c. Sylvanas es mi reina y haré lo que ella disponga.$B$BSi no muestras el respeto adecuado te aseguro que podemos encontrar un lugar más apropiado para ti en El Vacío Abisal.$B$BPero si deseas ayudar a la Dama Oscura no hay ninguna razón por la que no podamos intercambiar algunas palabras...' WHERE `ID`=7217;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 스랄의 앞에서 호드의 만백성들은 평등하도다. 우리는 힘든 시기를 함께 해왔다. 명예, 그리고 지혜가 없었더라면 악마 만노로스에 의해 우리의 피는 더럽혀지고 스컬지와 다를 바 없는 신세가 되었으리라.$B$B너의 임무는 호드를 돕고 우리 오크족을 수호하는 것이다. 그리고 적군에게도 자비와 관대함을 보여야 하는 시기를 알아내는 것도 너의 임무다.$B$B이 점을 명심해라. 이제 우리는 자유 의지를 빼앗긴 악마의 군대가 아니라 새로운 시대의 호드로 거듭났도다.', `MaleText_loc4`='在我眼中，部落的所有成员都是平等的，$n。我们的血液被恶魔玛诺洛斯污染了，人民承受着重负，如果不是为了学识和荣耀的话，我们几乎就快沦为亡灵天灾了。$B$B协助部落，让我们获得新生，这是你的职责。但是你也得明白什么时候应该对朋友同情，对敌人怜悯。$B$B好好理解。这是新生的部落，而不是缺乏自由意愿的恶魔军队。', `MaleText_loc5`='在我眼中，部落的所有成員都是平等的，$n。我們的血液被惡魔瑪諾洛斯污染了，人民承受著重負，如果不是為了學識和榮耀的話，我們幾乎就快淪為天譴軍團了。$B$B協助部落，讓我們獲得新生，這是你的職責。但是你也得明白什麼時候應該對朋友同情，對敵人憐憫。$B$B好好理解。這是新生的部落，而不是缺乏自由意願的惡魔軍隊。', `MaleText_loc7`='Todos los miembros de la Horda son iguales ante mis ojos, $n. Todos hemos sufrido innumerables cargas y si no fuera por la sabiduría y el honor, no seríamos mejores que la Plaga o que mi propia gente cuando nuestra sangre estaba manchada por el demonio Mannoroth.$B$BEs tu deber ayudar a la Horda y defender nuestro modo de vida. Pero también lo es saber cuándo dar clemencia y compasión a amigos y enemigos por igual. Esto es la nueva Horda, no una prole de demonios sin voluntad propia.' WHERE `ID`=7218;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말씀하시지요, 티리온.', `MaleText_loc4`='我准备好听你的故事，提里奥。', `MaleText_loc5`='我準備好聽你的故事，提里奧。', `MaleText_loc7`='Estoy listo para escuchar tu historia, Tirion.', `FemaleText_loc1`='말씀하시지요, 티리온.', `FemaleText_loc4`='我准备好听你的故事，提里奥。', `FemaleText_loc5`='我準備好聽你的故事，提里奧。', `FemaleText_loc7`='Estoy lista para escuchar tu historia, Tirion.' WHERE `ID`=7219;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우선 내 신분을 솔직하게 밝히지 못한 것부터 사과해야겠군. 난 자네를 신뢰해도 되는지 확신이 없었다네. 누가 늙고 잊혀진 은둔자를 사심 없이 도와주겠는가?$B$B자네는 스스로 그걸 증명해 보였네. 자네는 청렴하고 명예를 아는 친구야.', `MaleText_loc4`='由于我的身份问题，我并未对你说实话，我必须为此向你道歉。我必须确定你是值得信赖的——很少有人能无私地为一个年老的隐士提供帮助。$B$B你已经证明了自己是个正直崇高的人。', `MaleText_loc5`='由於我的身分問題，我並未對你說實話，我必須為此向你道歉。我必須確定你是值得信賴的─很少有人能無私地為一個年老的隱士提供幫助。$B$B你已經證明了自己是個正直崇高的人。', `MaleText_loc7`='Debo disculparme por no haber sido muy sincero en lo que respecta a mi identidad. Tenía que asegurarme de que podía confiar en ti... muy pocos darían ayuda desinteresadamente a un viejo y olvidado ermitaño.$B$BHas demostrado ser uno de ellos: una persona de integridad y honor.' WHERE `ID`=7220;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다, 티리온. 당신이 어떤 분이신지 궁금합니다.', `MaleText_loc4`='谢谢你，提里奥。你的身份是什么？', `MaleText_loc5`='謝謝你，提里奧。你的身分是什麼?', `MaleText_loc7`='Gracias, Tirion. ¿Qué ocurre con tu identidad?', `FemaleText_loc1`='감사합니다, 티리온. 당신이 어떤 분이신지 궁금합니다.', `FemaleText_loc4`='谢谢你，提里奥。你的身份是什么？', `FemaleText_loc5`='謝謝你，提里奧。你的身分是什麼?', `FemaleText_loc7`='Gracias, Tirion. ¿Qué ocurre con tu identidad?' WHERE `ID`=7221;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 반역죄로 얼라이언스에서 추방당하고 망명 생활을 할 때 내 아들 탤런은 어린 아이였네. 나는 여기 남아서 내 아들을 지켜보기로 결정했지. 어떤 방법으로든 아들이 훌륭하게 성장할 수 있도록 지켜주기 위해서였다네.$B$B내가 바라던 대로 아들은 내 자리였던 마르덴홀드의 군주가 되었지. 그러나 운명이란 어찌나 가혹하던지... 아들은 붉은십자군이 되었고 지금은 그들의 대영주가 되었지.', `MaleText_loc4`='当我以叛国罪被放逐离开联盟过着流放的生活时，我的儿子泰兰还是个小孩。我呆在这儿就是为了看着他长大，让他成为一个可敬的人。$B$B正如我期望的那样，他接替我的位置，成为玛登霍尔德之王，但是命运是如此残酷，他加入了血色十字军的队伍。现在他成了十字军的高级统领，$r。', `MaleText_loc5`='當我以叛國罪被放逐離開聯盟過著流放的生活時，我的兒子泰蘭還是個小孩。我待在這兒就是為了看著他長大，讓他成為一個可敬的人。$B$B正如我期望的那樣，他接替我的位置，成為瑪登霍爾德的領主，但是命運是如此殘酷，他加入了血色十字軍的隊伍。現在他成了十字軍的高級統領，$r。', `MaleText_loc7`='Mi hijo, Taelan, era solo un niño cuando se me declaró culpable de traición y fui desterrado de la Alianza para vivir en el exilio. Decidí quedarme aquí para poder vigilarle, para asegurarme, de algún modo, de que crecía como un hombre honorable.$B$BComo había esperado, tomó mi lugar como señor de Mardenholde; pero en un cruel juego del destino, se unió a las filas de la Cruzada Escarlata. Ahora es su Alto Señor, $r.' WHERE `ID`=7222;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 가혹하군요.', `MaleText_loc4`='那可真糟糕。', `MaleText_loc5`='那可真糟糕。', `MaleText_loc7`='Es terrible.', `FemaleText_loc1`='정말 가혹하군요.', `FemaleText_loc4`='那可真糟糕。', `FemaleText_loc5`='那可真糟糕。', `FemaleText_loc7`='Es terrible.' WHERE `ID`=7223;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇다네. 은빛 성기사단의 원칙을 어기는 자들이 붉은십자군이 되는 거라네.$B$B날 믿어야 해. 탤런은 좋은 녀석일세. 이끌어줄 자가 필요해. 녀석은 무엇이 옳은 일인지 명예란 어떤 것인지 다시 기억해 내야만 하네. 탤런도 자기가 하는 일이 잘못이라는 걸 가슴으로는 느끼고 있을 거야. 자네가 탤런을 도와서 기억을 일깨워 주겠나?', `MaleText_loc4`='真的。血色十字军是银手骑士团做出的错误决策。$B$B你必须相信我，$r；泰兰是个好人。他需要指导。他必须记起……记起高贵和荣耀的含义。我知道那信念就在他心中，他知道他所做的是错误的。你帮助他好吗？帮助他记起来？', `MaleText_loc5`='真的。血色十字軍是白銀之手騎士團做出的錯誤決策。$B$B你必須相信我，$r;泰蘭是個好人。他需要指導。他必須記起...記起高貴和榮耀的含義。我知道那信念就在他心中，他知道他所做的是錯誤的。你幫助他好嗎?幫助他記起來?', `MaleText_loc7`='Desde luego. La Cruza Escarlata es una aberración de la Orden de la Mano de Plata.$B$BDebes creerme, $r; Taelan es un buen hombre. Solo necesita guía. Tiene que recordar... recordar lo que es ser noble y honorable. Sé que en su corazón sabe que lo que hace no es correcto. ¿Le ayudarás? ¿Le ayudarás a recordar?' WHERE `ID`=7224;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇게 하겠습니다, 티리온.', `MaleText_loc4`='我会的，提里奥。', `MaleText_loc5`='我會的，提里奧。', `MaleText_loc7`='Lo haré, Tirion.', `FemaleText_loc1`='그렇게 하겠습니다, 티리온.', `FemaleText_loc4`='我会的，提里奥。', `FemaleText_loc5`='我會的，提里奧。', `FemaleText_loc7`='Lo haré, Tirion.' WHERE `ID`=7225;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어째서 고블린같이 작은 녀석들은 덩치 큰 놈들만 보면 힘을 못 쓰는 거지?', `MaleText_loc4`='为什么像地精这样的小生物总是迷恋创造大的发明呢？', `MaleText_loc5`='為什麼像哥布林這樣的小生物總是迷戀創造大的發明呢?', `MaleText_loc7`='¿Por qué esas pequeñas criaturas como los goblins siempre están fascinadas por las criaturas grandes?', `FemaleText_loc1`='어째서 고블린같이 작은 녀석들은 덩치 큰 놈들만 보면 힘을 못 쓰는 거지?', `FemaleText_loc4`='为什么像地精这样的小生物总是迷恋创造大的发明呢？', `FemaleText_loc5`='為什麼像哥布林這樣的小生物總是迷戀創造大的發明呢?', `FemaleText_loc7`='¿Por qué esas pequeñas criaturas como los goblins siempre están fascinadas por las criaturas grandes?' WHERE `ID`=7226;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 부상이 너무 심해... 병사들이여, 내가 없어도 꿋꿋히 맞서 싸워야 한다.', `MaleText_loc4`='啊！我的伤太严重了。卫士们，我不在你们要继续战斗！', `MaleText_loc5`='啊!我的傷太嚴重了。防衛者們，我不在你們要繼續戰鬥!', `MaleText_loc7`='¡Ah! Mis heridas son demasiado graves. Defensores, ¡seguid luchando sin mí!' WHERE `ID`=7227;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='남의 말을 들을 땐 주의를 기울이게. 성급하게 믿어서도 안 되지만, 무턱대고 불신하는 것도 어리석은 일이지. 친구 사이라도 자신의 목적을 위해서라면 수단과 방법을 가리지 않는 세상이지 않나, $c.$B$B위대하신 우리 대족장님께서도 이 점을 잘 알고 계시지. 나는 우리의 젊은 지도자를 돕기 위해 자발적으로 나섰다네. 흑마법사들이 다 호드를 무너뜨리거나 장악하려고 드는 건 아니라는 것을 증명하려고 말이야.', `MaleText_loc4`='你要仔细听好了，别轻易相信或怀疑你所听到的一切。因为即使是朋友也可能将自己送上死路，$c。$B$B我们伟大的酋长深知这一点，为了证明部落中有一些术士并不想从内部毁掉部落，或是为了获得权力，我自愿尽我所能帮助年轻的首领。', `MaleText_loc5`='你要仔細聽好了，別輕易相信或懷疑你所聽到的一切。因為即使是朋友也可能將自己送上死路，$c。$B$B我們偉大的大酋長深知這一點，為了證明部落中有一些術士並不想從內部毀掉部落，或是為了獲得權力，我自願盡我所能幫助年輕的首領。', `MaleText_loc7`='Escucha con cuidado lo que se te dice, y no confíes, ni desconfíes, demasiado deprisa. Incluso los amigos persiguen sus propios intereses, $c.$B$BNuestro gran Jefe de Guerra lo sabe, y para demostrar que hay brujos en la Horda que no desean destruirla desde dentro ni ganar control sobre ella, me he ofrecido como voluntario para ayudar a nuestro joven líder como me sea posible.' WHERE `ID`=7228;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽을 준비는 됐겠지.', `MaleText_loc4`='准备被揍吧。', `MaleText_loc5`='準備被揍吧。', `MaleText_loc7`='Prepárate para recibir una auténtica paliza.' WHERE `ID`=7229;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갈기갈기 찢어주마!', `MaleText_loc4`='我会将你的内脏当作项链的。', `MaleText_loc5`='我會將你的內臟當作項鍊的。', `MaleText_loc7`='Debería ponerme tus entrañas como colgante.' WHERE `ID`=7230;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으흐흐... $R, 너의 공포가 느껴지는군.', `MaleText_loc4`='我可以感觉到你的恐惧，$r。', `MaleText_loc5`='我可以感覺到你的恐懼，$r。', `MaleText_loc7`='Puedo oler tu miedo, $r.' WHERE `ID`=7231;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금이라도 도망쳐. 그러면 목숨만은 건질 수 있다.', `MaleText_loc4`='要是你现在跑的话，你也许还有机会活下去。', `MaleText_loc5`='要是你現在跑的話，你也許還有機會活下去。', `MaleText_loc7`='Si empiezas a correr, quizás vivas.' WHERE `ID`=7232;
