UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 힘을 쓸 가치도 없는 놈이다. <침을 뱉는 나타노스>', `MaleText_loc4`='你不值得我花费力气。<纳萨诺斯吐了一口唾沫。>', `MaleText_loc5`='你不值得我花費力氣。<納薩諾斯吐了一口唾沫。>', `MaleText_loc7`='No mereces que gaste mi energía. <Nathanos escupe.>' WHERE `ID`=7238;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음에는 친구라도 데리고 오너라.', `MaleText_loc4`='下一次带朋友一起来。', `MaleText_loc5`='下一次帶朋友一起來。', `MaleText_loc7`='La próxima vez, trae amigos.' WHERE `ID`=7239;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 네 영혼도 타락하게 해주마...', `MaleText_loc4`='我正让你堕落……', `MaleText_loc5`='我正讓你墮落...', `MaleText_loc7`='Ahora te corromperé...' WHERE `ID`=7240;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무기 전문가', `MaleText_loc4`='武器训练师', `MaleText_loc5`='武器訓練師', `MaleText_loc7`='Instructor de armas', `FemaleText_loc1`='무기 전문가', `FemaleText_loc4`='武器训练师', `FemaleText_loc5`='武器訓練師', `FemaleText_loc7`='Instructor de armas' WHERE `ID`=7241;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우 핑의 체력은 정말 놀랍습니다. 몇 시간 동안이나 넋을 놓고 우 핑이 기술을 연마하는 걸 지켜본 적이 있는데 훈련용 허수아비가 불쌍하다는 생각이 들 정도였어요. 무기를 사용한 전투 기술도 일품이니 당신에게는 최고의 스승일 겁니다.', `MaleText_loc4`='吴平的精力真令人惊奇。我看着他连续练习了数小时技巧。他用双手击打练习用的假人，直到他的拳头沾满鲜血。我想不到还有谁比他更适合训练你的战斗技能。', `MaleText_loc5`='吳平的精力真令人驚奇。我看著他連續練習了數小時技巧。他用雙手擊打練習用的假人直到他的拳頭沾滿鮮血。我想不到還有誰比他還適合訓練你的戰鬥技能。', `MaleText_loc7`='La fortaleza de Woo Ping es realmente increíble. Cuando le veo practicar sus técnicas durante horas acabo sintiendo lástima por el muñeco con el que practica. No imagino a nadie más apropiado para instruirte en el combate con armas.', `FemaleText_loc1`='우 핑의 체력은 정말 놀랍습니다. 몇 시간 동안이나 넋을 놓고 우 핑이 기술을 연마하는 걸 지켜본 적이 있는데 훈련용 허수아비가 불쌍하다는 생각이 들 정도였어요. 무기를 사용한 전투 기술도 일품이니 당신에게는 최고의 스승일 겁니다.', `FemaleText_loc4`='吴平的精力真令人惊奇。我看着他连续练习了数小时技巧。他用双手击打练习用的假人，直到他的拳头沾满鲜血。我想不到还有谁比他更适合训练你的战斗技能。', `FemaleText_loc5`='吳平的精力真令人驚奇。我看著他連續練習了數小時技巧。他用雙手擊打練習用的假人直到他的拳頭沾滿鮮血。我想不到還有誰比他還適合訓練你的戰鬥技能。', `FemaleText_loc7`='La fortaleza de Woo Ping es realmente increíble. Cuando le veo practicar sus técnicas durante horas acabo sintiendo lástima por el muñeco con el que practica. No imagino a nadie más apropiado para instruirte en el combate con armas.' WHERE `ID`=7242;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무기 전문가 우 핑은 동부 왕국에 존재하는 거의 모든 무기를 능숙하게 다룰 줄 압니다. 특히 검술이 정말 위력적이죠. 웰러의 무기고에서 무기가 배달되기를 기다리고 있을 테니까 뭔가 배우고 싶다면 찾아가 보십시오.', `MaleText_loc4`='吴平大师几乎懂得人类所知的所有武器的用法。在徒手搏斗中，他的觉醒之拳技能具有致命的攻击力。要是你需要训练的话，就去找他吧，他一般都在维勒武器店等待新武器的运送。', `MaleText_loc5`='吳平大師幾乎精通人類所知的所有武器用法。他的劍法尤其具有致命的攻擊力。要是你需要訓練的話就去找他吧，他大部分時間都在維勒武器店等待新武器的到來。', `MaleText_loc7`='La maestra Woo Ping domina casi todas las armas que conoce el hombre. Es especialmente mortal con sus técnicas de espada. Pasa mucho tiempo en el Arsenal de Weller, esperando nuevos cargamentos de armas. La encontrarás allí si necesitas instrucción.', `FemaleText_loc1`='무기 전문가 우 핑은 동부 왕국에 존재하는 거의 모든 무기를 능숙하게 다룰 줄 알아요. 특히 검술이 정말 위력적이죠. 웰러의 무기고에서 무기가 배달되기를 기다리고 있을 테니까 뭔가 배우고 싶다면 찾아가 보세요.', `FemaleText_loc4`='吴平大师几乎懂得人类所知的所有武器的用法。在徒手搏斗中，他的觉醒之拳技能具有致命的攻击力。要是你需要训练的话，就去找他吧，他一般都在维勒武器店等待新武器的运送。', `FemaleText_loc5`='吳平大師幾乎精通人類所知的所有武器用法。他的劍法尤其具有致命的攻擊力。要是你需要訓練的話就去找他吧，他大部分時間都在維勒武器店等待新武器的到來。', `FemaleText_loc7`='La maestra Woo Ping domina casi todas las armas que conoce el hombre. Es especialmente mortal con sus técnicas de espada. Pasa mucho tiempo en el Arsenal de Weller, esperando nuevos cargamentos de armas. La encontrarás allí si necesitas instrucción.' WHERE `ID`=7243;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무기 전문가', `MaleText_loc4`='武器训练师', `MaleText_loc5`='武器訓練師', `MaleText_loc7`='Instructor de armas', `FemaleText_loc1`='무기 전문가', `FemaleText_loc4`='武器训练师', `FemaleText_loc5`='武器訓練師', `FemaleText_loc7`='Instructor de armas' WHERE `ID`=7244;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일예니아 문파이어는 지난 천 년 동안 수많은 무기를 익혀왔습니다. 지금은 다른 이들에게 그 기술을 전수하고 있지요. 훈련을 받고 싶으면 전사의 정원으로 가서 일예니아를 찾아보십시오.', `MaleText_loc4`='通过千百次的锤炼，伊琳尼雅·月火已经掌握了若干种武器的使用方法，现在她为别人提供训练。如果你想接受训练的话，就去战士区找她吧。', `MaleText_loc5`='通過千百次的錘煉，伊琳尼雅·月火已經掌握了若干種武器的使用方法，現在她為別人提供訓練。如果你想接受訓練的話，就去戰士區找她吧。', `MaleText_loc7`='Con el paso de los milenios, Ilyenia Fuegolunar ha llegado a dominar muchas armas y ofrece instrucción a otros. Si deseas instruirte podrás encontrarla en el Bancal del Guerrero.', `FemaleText_loc1`='일예니아 문파이어는 지난 천 년 동안 수많은 무기를 익혀왔습니다. 지금은 다른 이들에게 그 기술을 전수하고 있지요. 훈련을 받고 싶으면 전사의 정원으로 가서 일예니아를 찾아보십시오.', `FemaleText_loc4`='通过千百次的锤炼，伊琳尼雅·月火已经掌握了若干种武器的使用方法，现在她为别人提供训练。如果你想接受训练的话，就去战士区找她吧。', `FemaleText_loc5`='通過千百次的錘煉，伊琳尼雅·月火已經掌握了若干種武器的使用方法，現在她為別人提供訓練。如果你想接受訓練的話，就去戰士區找她吧。', `FemaleText_loc7`='Con el paso de los milenios, Ilyenia Fuegolunar ha llegado a dominar muchas armas y ofrece instrucción a otros. Si deseas instruirte podrás encontrarla en el Bancal del Guerrero.' WHERE `ID`=7245;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희 파수꾼들도 대부분 일예니아 문파이어에게 무기 훈련을 받았습니다. 새로운 무기의 사용법을 배우고 싶다면 전사의 정원으로 일예니아를 찾아가보십시오.', `MaleText_loc4`='我的大部分武器都来自战士区的伊琳尼雅·月火。要是你想学习如何使用新武器，就去找她吧。', `MaleText_loc5`='我的大部分武器都來自戰士區的伊琳尼雅·月火。要是你想學習如何使用新武器，就去找她吧。', `MaleText_loc7`='Recibí casi toda mi instrucción en armas de Ilyenia Fuegolunar, en el Bancal del Guerrero. Harías bien en buscarla si deseas aprender el uso de una nueva arma.', `FemaleText_loc1`='저희 파수꾼들도 대부분 일예니아 문파이어에게 무기 훈련을 받았습니다. 새로운 무기의 사용법을 배우고 싶다면 전사의 정원으로 일예니아를 찾아가보십시오.', `FemaleText_loc4`='我的大部分武器都来自战士区的伊琳尼雅·月火。要是你想学习如何使用新武器，就去找她吧。', `FemaleText_loc5`='我的大部分武器都來自戰士區的伊琳尼雅·月火。要是你想學習如何使用新武器，就去找她吧。', `FemaleText_loc7`='Recibí casi toda mi instrucción en armas de Ilyenia Fuegolunar, en el Bancal del Guerrero. Harías bien en buscarla si deseas aprender el uso de una nueva arma.' WHERE `ID`=7246;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무기 전문가', `MaleText_loc4`='武器训练师', `MaleText_loc5`='武器訓練師', `MaleText_loc7`='Instructor de armas', `FemaleText_loc1`='무기 전문가', `FemaleText_loc4`='武器训练师', `FemaleText_loc5`='武器訓練師', `FemaleText_loc7`='Instructor de armas' WHERE `ID`=7247;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빅시와 불리위프는 별별 무기를 다 써서 오크를 때려잡은 경험이 있소. 그들은 언제나 잘나가는 무기 상점에 머물고 있으니까 훈련을 받고 싶으면 가보시오.', `MaleText_loc4`='比克斯和布里维夫的武器沾满了兽人的鲜血。如果你想学习的话，就去密林武器店找他们吧。', `MaleText_loc5`='比克斯和布里維夫的武器沾滿了獸人的鮮血。如果你想學習的話，就去密林武器店找他們吧。', `MaleText_loc7`='Entre Bixi y Buliwyf no habrá muchas armas con las que no hayan tenido el placer de despedazar o machacar a un orco. Si necesitas instrucción los podrás encontrar junto a la tienda Mil Maderas.', `FemaleText_loc1`='빅시와 불리위프는 별별 무기를 다 써서 오크를 때려잡은 경험이 있소. 그들은 언제나 잘나가는 무기 상점에 머물고 있으니까 훈련을 받고 싶으면 가보시오.', `FemaleText_loc4`='比克斯和布里维夫的武器沾满了兽人的鲜血。如果你想学习的话，就去密林武器店找他们吧。', `FemaleText_loc5`='比克斯和布里維夫的武器沾滿了獸人的鮮血。如果你想學習的話，就去密林武器店找他們吧。', `FemaleText_loc7`='Entre Bixi y Buliwyf no habrá muchas armas con las que no hayan tenido el placer de despedazar o machacar a un orco. Si necesitas instrucción los podrás encontrar junto a la tienda Mil Maderas.' WHERE `ID`=7248;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새로 얻은 무기를 제대로 사용하는 방법을 배우고 싶습니까? 그렇다면 잘나가는 무기 상점에 가서 빅시나 불리위프를 찾아보십시오. 그들은 도끼부터 시작해서 투척용 나이프까지 정통하답니다.', `MaleText_loc4`='你想学习怎样使用一种新武器是吗？那么，你就应该与那边的密林武器店武器商店的比克斯和布里维夫谈谈，$g小伙子:姑娘;。他们对从斧头到……嗯……双手武器都非常了解。', `MaleText_loc5`='你想學習怎樣使用一種新武器是嗎?那麼，你就應該與那邊的密林武器店武器商店的比克斯和布里維夫談談，$g小夥子:姑娘;。他們對從斧頭到...嗯...雙手武器都非常瞭解。', `MaleText_loc7`='¿Quieres aprender a utilizar una nueva arma, eh? Bueno, deberías estar hablando con Bixi o con Buliwyf, en la tienda Mil Maderas, ¿no crees $gmuchacho:muchacha;? Conocen todo tipo de armas, desde hachas hasta... uh... montantes.', `FemaleText_loc1`='새로 얻은 무기를 제대로 사용하는 방법을 배우고 싶습니까? 그렇다면 잘나가는 무기 상점에 가서 빅시나 불리위프를 찾아보십시오. 그들은 도끼부터 시작해서 투척용 나이프까지 정통하답니다.', `FemaleText_loc4`='你想学习怎样使用一种新武器是吗？那么，你就应该与那边的密林武器店武器商店的比克斯和布里维夫谈谈，$g小伙子:姑娘;。他们对从斧头到……嗯……双手武器都非常了解。', `FemaleText_loc5`='你想學習怎樣使用一種新武器是嗎?那麼，你就應該與那邊的密林武器店武器商店的比克斯和布里維夫談談，$g小夥子:姑娘;。他們對從斧頭到...嗯...雙手武器都非常瞭解。', `FemaleText_loc7`='¿Quieres aprender a utilizar una nueva arma, eh? Bueno, deberías estar hablando con Bixi o con Buliwyf, en la tienda Mil Maderas, ¿no crees $gmuchacho:muchacha;? Conocen todo tipo de armas, desde hachas hasta... uh... montantes.' WHERE `ID`=7249;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새로 얻은 무기 사용법을 배우고 싶은가? 명예의 골짜기에 있는 전설의 무기점으로 가서 하나시와 함께 있는 사요크를 찾아보게.', `MaleText_loc4`='想学习如何使用新武器？去荣誉谷的传说中的装备店中找塞尤克和哈纳什吧。', `MaleText_loc5`='想學習如何使用新武器?去榮譽谷的傳說中的裝備店中找塞尤克和哈納什吧。', `MaleText_loc7`='¿Quieres aprender a usar una nueva arma? Busca a Sayoc y Hanashi en Armas de Leyenda, en el Valle del Honor.', `FemaleText_loc1`='새로 얻은 무기 사용법을 배우고 싶은가? 명예의 골짜기에 있는 전설의 무기점으로 가서 하나시와 함께 있는 사요크를 찾아보게.', `FemaleText_loc4`='想学习如何使用新武器？去荣誉谷的传说中的装备店中找塞尤克和哈纳什吧。', `FemaleText_loc5`='想學習如何使用新武器?去榮譽谷的傳說中的裝備店中找塞尤克和哈納什吧。', `FemaleText_loc7`='¿Quieres aprender a usar una nueva arma? Busca a Sayoc y Hanashi en Armas de Leyenda, en el Valle del Honor.' WHERE `ID`=7251;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명예의 골짜기, 용사의 전당에 있는 전설의 무기점으로 가서 사요크와 하나시를 찾아보게. 그들 앞에서는 말 조심하는 게 좋을 거요. 까딱 잘못 했다간 사요크가 당신 살점을 사나운 들개에게 간식으로 줄지도 모르니까.', `MaleText_loc4`='去荣誉谷的传说中的装备店中找塞尤克和哈纳什。注意你的言行，否则塞尤克也许会将你作为喂狗的美食。', `MaleText_loc5`='去榮譽谷的傳說中的裝備店中找塞尤克和哈納什。注意你的言行，否則塞尤克也許會將你作為餵狗的美食。', `MaleText_loc7`='Busca a Sayoc y Hanashi en el Valle del Honor, en Armas de Leyenda. Cuando estés con ellos procura morderte la lengua, a Sayoc se le puede ocurrir hacerte pedacitos para darle de comer a Perro Rictus.', `FemaleText_loc1`='명예의 골짜기, 용사의 전당에 있는 전설의 무기점으로 가서 사요크와 하나시를 찾아보게. 그들 앞에서는 말 조심하는 게 좋을 거요. 까딱 잘못 했다간 사요크가 당신 살점을 사나운 들개에게 간식으로 줄지도 모르니까.', `FemaleText_loc4`='去荣誉谷的传说中的装备店中找塞尤克和哈纳什。注意你的言行，否则塞尤克也许会将你作为喂狗的美食。', `FemaleText_loc5`='去榮譽谷的傳說中的裝備店中找塞尤克和哈納什。注意你的言行，否則塞尤克也許會將你作為喂狗的美食。', `FemaleText_loc7`='Busca a Sayoc y Hanashi en el Valle del Honor, en Armas de Leyenda. Cuando estés con ellos procura morderte la lengua, a Sayoc se le puede ocurrir hacerte pedacitos para darle de comer a Perro Rictus.' WHERE `ID`=7252;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무기 전문가', `MaleText_loc4`='武器大师', `MaleText_loc5`='武器大師', `MaleText_loc7`='Maestro de armas', `FemaleText_loc1`='무기 전문가', `FemaleText_loc4`='武器大师', `FemaleText_loc5`='武器大師', `FemaleText_loc7`='Maestro de armas' WHERE `ID`=7253;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안세크화의 지혜를 구하러 오셨군요. 썬더 블러프 봉우리 하층에 있는 썬더 블러프 무기점에서 그를 찾아보십시오.', `MaleText_loc4`='啊，你是在找安塞瓦。去雷霆崖武器店中部高地的底层找他吧。', `MaleText_loc5`='啊，你是在找安塞瓦。去雷霆崖武器店中部高地的底層找他吧。', `MaleText_loc7`='Ah, buscas la sabiduría de Ansekhwa. Búscale en la colina inferior, en Armas de Cima del Trueno.', `FemaleText_loc1`='안세크화의 지혜를 구하러 오셨군요. 썬더 블러프 봉우리 하층에 있는 썬더 블러프 무기점에서 그를 찾아보십시오.', `FemaleText_loc4`='啊，你是在找安塞瓦。去雷霆崖武器店中部高地的底层找他吧。', `FemaleText_loc5`='啊，你是在找安塞瓦。去雷霆崖武器店中部高地的底層找他吧。', `FemaleText_loc7`='Ah, buscas la sabiduría de Ansekhwa. Búscale en la colina inferior, en Armas de Cima del Trueno.' WHERE `ID`=7254;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무기를 다루는 기술은 안세크화를 따라올 자가 없습니다. 우리 선조 중에서도 최고로 뛰어난 전사의 영혼이 안세크화를 이끌어 주고 있다고 합니다. 수렵의 봉우리에 가서 안세크화를 찾아보십시오. 당신이 알고 싶어하는 것을 가르쳐 줄 것입니다.', `MaleText_loc4`='在武器使用方面，没有人能胜过安塞瓦了。据说他接受过我们尊敬的祖先，最伟大的战士的灵魂的指导。去中部高地的底层寻找他，他会教你的。', `MaleText_loc5`='在武器使用方面，沒有人能勝過安塞瓦了。據說他接受過我們尊敬的祖先，最偉大的戰士的靈魂的指導。去中部高地的底層尋找他，他會教你的。', `MaleText_loc7`='Nadie es tan diestro en el manejo de las armas como Ansekhwa. Se dice que le guían los espíritus de los mejores guerreros de nuestros honorables antepasados. Búscale en el alto inferior y te enseñará lo que quieres saber.', `FemaleText_loc1`='무기를 다루는 기술은 안세크화를 따라올 자가 없습니다. 우리 선조 중에서도 최고로 뛰어난 전사의 영혼이 안세크화를 이끌어 주고 있다고 합니다. 수렵의 봉우리에 가서 안세크화를 찾아보십시오. 당신이 알고 싶어하는 것을 가르쳐 줄 것입니다.', `FemaleText_loc4`='在武器使用方面，没有人能胜过安塞瓦了。据说他接受过我们尊敬的祖先，最伟大的战士的灵魂的指导。去中部高地的底层寻找他，他会教你的。', `FemaleText_loc5`='在武器使用方面，沒有人能勝過安塞瓦了。據說他接受過我們尊敬的祖先，最偉大的戰士的靈魂的指導。去中部高地的底層尋找他，他會教你的。', `FemaleText_loc7`='Nadie es tan diestro en el manejo de las armas como Ansekhwa. Se dice que le guían los espíritus de los mejores guerreros de nuestros honorables antepasados. Búscale en el alto inferior y te enseñará lo que quieres saber.' WHERE `ID`=7255;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무기 전문가', `MaleText_loc4`='武器大师', `MaleText_loc5`='武器大師', `MaleText_loc7`='Maestro de armas', `FemaleText_loc1`='무기 전문가', `FemaleText_loc4`='武器大师', `FemaleText_loc5`='武器大師', `FemaleText_loc7`='Maestro de armas' WHERE `ID`=7256;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아키발드 말이야? 군사 지구의 내곽으로 가봐. 무기 상점 밖에 있을 거야.', `MaleText_loc4`='你要找的阿基巴德在战争区内环的武器商店外。', `MaleText_loc5`='你要找的阿基巴德在戰爭區內環的武器商店外。', `MaleText_loc7`='A Archibald buscas. Él fuera de la tienda de armas, círculo interior del Barrio de la Guerra.', `FemaleText_loc1`='아키발드 말이야? 군사 지구의 내곽으로 가봐. 무기 상점 밖에 있을 거야.', `FemaleText_loc4`='你要找的阿基巴德在战争区内环的武器商店外。', `FemaleText_loc5`='你要找的阿基巴德在戰爭區內環的武器商店外。', `FemaleText_loc7`='A Archibald buscas. Él fuera de la tienda de armas, círculo interior del Barrio de la Guerra.' WHERE `ID`=7257;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='작은 포세이큰 친구, 아키발드... 모르는 무기가 없다. 군사 지구의 내곽에서 찾을 수 있다.', `MaleText_loc4`='小亡灵阿基巴德知晓所有武器。你可以在军事区内环找到他。', `MaleText_loc5`='被遺忘者小阿基巴德知曉所有武器。你可以在軍事區內環找到他。', `MaleText_loc7`='Pequeño Renegado conoce todas las armas. Él Archibald. Tú busca en círculo interior del Barrio de la Guerra.', `FemaleText_loc1`='작은 포세이큰 친구, 아키발드... 모르는 무기가 없다. 군사 지구의 내곽에서 찾을 수 있다.', `FemaleText_loc4`='小亡灵阿基巴德知晓所有武器。你可以在军事区内环找到他。', `FemaleText_loc5`='被遺忘者小阿基巴德知曉所有武器。你可以在軍事區內環找到他。', `FemaleText_loc7`='Pequeño Renegado conoce todas las armas. Él Archibald. Tú busca en círculo interior del Barrio de la Guerra.' WHERE `ID`=7258;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무기 전문가', `MaleText_loc4`='武器大师', `MaleText_loc5`='武器大師', `MaleText_loc7`='Maestro de armas', `FemaleText_loc1`='무기 전문가', `FemaleText_loc4`='武器大师', `FemaleText_loc5`='武器大師', `FemaleText_loc7`='Maestro de armas' WHERE `ID`=7259;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금까지 적들이 우릴 어떻게 속여왔는지 설명해주지.$B$B지금부터 내가 하는 말을 명심하게. 우리의 적은 바로 어둠의 의회일세. 내가 자네에게 어떤 일을 시키든지, 누구와 싸우라고 하든지... 이것 하나만은 잊지 말게.$B$B어둠의 의회는 수많은 종파로 나누어져 있지만 모두 어리석은 자들의 눈을 흐리게 만들기 위한 수단일 뿐일세.$B$B불타는 칼날단, 아르거스 재림회, 그리고 이글거리는 칼날단 같은 단체들이 모두 어둠의 의회의 앞잡이란 말이지. 모두 한통속이야.', `MaleText_loc4`='我得向你解释，我们的敌人能安然地潜伏在我们的眼皮底下。$B$B首先要记住这一点：我们的敌人是暗影议会。无论我给你什么任务，或许无论我让你与谁对抗，你都必须明了这个事实。$B$B议会拥有许多信徒，但是其行动信息绝对不会透露给愚蠢的信徒。$B$B像火刃、阿古斯的觉醒和燃刃都是议会的工具。他们是一伙的。', `MaleText_loc5`='我得向你解釋，我們的敵人能安然地潛伏在我們的眼皮底下。$B$B首先要記住這一點:我們的敵人是暗影議會。無論我給你什麼任務，或許無論我讓你與誰對抗，你都必須明瞭這個事實。$B$B議會擁有許多信徒，但是其行動資訊絕對不會透露給愚蠢的信徒。$B$B像燃刃、阿古斯覺醒和灼刃都是議會的工具。他們是一夥的。', `MaleText_loc7`='Sería acertado explicarte las profundidades a las que huirían nuestros enemigos para esconderse ante nuestras narices.$B$BEsto es lo primero y más importante: nuestro enemigo es el Consejo de las Sombras. No importa qué tarea te dé ni contra quién te ordene actuar, recuerda solo ese simple hecho.$B$BExisten muchos cultos en el Consejo, pero todos se resumen en ocultar sus acciones frente al imprudente.$B$BGrupos como la Hoja Abrasadora, el Despertar de Argus y la Hoja Abrasadora son herramientas del Consejo. Considéralos una misma cosa.' WHERE `ID`=7260;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런, 이런. 이자도 뭔가 훔치려 온 거로군. 없애 버리자!', `MaleText_loc4`='好，好。看来我们要展开角逐了。去吧，孩子们！', `MaleText_loc5`='好，好。看來我們要展開角逐了。去吧，孩子們!', `MaleText_loc7`='Bien, bien, parece que tenemos competencia. ¡Cogedlos chicos!' WHERE `ID`=7261;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 동지였군. 하루가 다르게 동지들이 늘어나서 좋기는 한데 얼굴을 익힐 수가 있어야지...$B$B멍청한 스랄은 내가 흑마법사의 부정적인 이미지를 벗고 자신의 충실한 종이라는 걸 증명하기 위해 불철주야 열심히 일하는 줄로만 알고 있지. 바보 같은 놈! 불타는 군단이 휩쓸고 지나가면 온 세상이 잿더미가 될 게 분명하네.', `MaleText_loc4`='啊，是我们的人。很高兴看到我们的队伍增长如此迅速，以至于我都记不清每个人的容貌了。$B$B萨尔那个傻子认为我正努力改善术士的形象并为他服务呢。白痴！燃烧军团在耗尽这世界的资源后会将它化为灰烬的。', `MaleText_loc5`='啊，是我們的人。很高興看到我們的隊伍增長如此迅速，以至於我都記不清每個人的容貌了。$B$B索爾那個傻子認為我正努力改善術士的形象並為他服務呢。白癡!燃燒軍團在耗盡這世界的資源後會將它化為灰燼的。', `MaleText_loc7`='Ah, uno de los nuestros. Es estupendo ver cómo crece nuestro número, tan rápido que ya no puedo recordar las caras de nuestros miembros.$B$BEl idiota de Thrall cree que estoy trabajando duro para limpiar la imagen de los brujos y probar que somos sus siervos. ¡Idiota! La Legión Ardiente reducirá a cenizas el mundo cuando termine de exprimirlo.' WHERE `ID`=7262;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='순진하군. 불타는 칼날단이 바로 어둠의 의회야! 어둠의 의회에는 많은 종파와 단체가 있지만 다 한통속이지. 내가 불타는 칼날단을 이끈다고 해도 어둠의 의회에서 보면, 일원에 불과할 뿐이야. 다 한 식구란 말이야...$B$B그런데, 이글거리는 칼날단을 한번 생각해 보게. 자기들이 어둠의 의회를 대신할 강력한 흑마법사 군단으로 떠오를 거라고 떠들고 다니지. 어리석은 것들.', `MaleText_loc4`='天真的傻子。火刃就是暗影议会！议会拥有许多信徒和组织，但是他们都服从于议会的意愿。我或许能领导火刃，但是我无非是议会手下的一名爪牙，就像你是我的爪牙一样！$B$B看看燃刃吧——他们中的大多数人认为自己会成为下一批极具潜力的术士，并成功替代暗影议会。', `MaleText_loc5`='天真的傻子。燃刃就是暗影議會!議會擁有許多信徒和組織，但是他們都服從於議會的意願。我或許能領導燃刃，但是我無非是議會手下的一名爪牙，就像你是我的爪牙一樣!$B$B看看灼刃吧─他們中的大多數人認為自己會成為下一批極具潛力的術士，並成功替代暗影議會。', `MaleText_loc7`='Tonto ingenuo. ¡El Filo Ardiente ES el Consejo de la Sombra! Hay muchos cultos y organizaciones reunidos en el Consejo pero todos ellos no son más que extensiones de su voluntad. ¡Puede que yo lidere el Filo Ardiente, pero no soy más que un peón del Consejo, como tú lo eres de mí!$B$BMira la Hoja Abrasadora... casi todos creen que se están convirtiendo en el siguiente grupo de poderosos brujos que sustituirá al Consejo de la Sombra.' WHERE `ID`=7263;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하! 놈들의 우두머리를 잡으려면 힘을 아껴두어야 할 거야. 사티로스 바잘란, 흑마법사 제로쉬... 난 지금까지 그들에게 스랄의 숭배자들을 숱하게 보내왔네. 스랄의 도시에서 악을 제거하고 있다는 인상을 주고 싶었거든. 꼭 성공해서 돌아오게. 스랄의 추종자들을 처치하고 이글거리는 칼날단 녀석들이 우리 편이 될 자격이 있는지 한번 시험해 보는 거야.', `MaleText_loc4`='哈哈！除了他们的领导人——萨特, 巴扎兰, 还有术士耶戈什——是的，他们所有人。这就是我不断的派萨尔的信徒到他们那儿去的原因。这样会让萨尔觉得我正在铲除他伟大城市中邪恶的人。事实上胜利是双重的：杀掉萨尔的信徒并测试一下那些燃刃的力量，看看他们是否真的有资格加入我的队伍。', `MaleText_loc5`='哈哈!除了他們的領導人─薩特, 巴札蘭, 還有術士耶戈什─是的，他們所有人。這就是我不斷的派索爾的信徒到他們那兒去的原因。這樣會讓索爾覺得我正在剷除他偉大城市中邪惡的人。事實上勝利是雙重的:殺掉索爾的信徒並測試一下那些灼刃的力量，看看他們是否真的有資格加入我的隊伍。', `MaleText_loc7`='¡Jaja! Excepto sus líderes (el sátiro, Bazzalan, y el brujo Jergosh) sí, todos ellos. Por eso les envío constantemente a los devotos de Thrall. Eso le da a Thrall la impresión de que estoy limpiando el mal en las entrañas de su gran ciudad. La victoria tiene dos caras: matar a los devotos de Thrall y poner a prueba la fuerza de los de la Hoja Abrasadora para ver si realmente merecen unirse a mí.' WHERE `ID`=7264;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 들게. 자네는 이미 어둠의 의회에서 특출난 실력을 증명했기 때문에 부관으로 고속 승진이 가능할 정도야. 나중에 돌아온다면 임무를 맡기도록 하지. 어둠의 의회는 비전 마법에 능숙한 자를 유독 반기지만, 동지가 되고 싶다면 직업이나 종족에 상관없이 누구나 환영한다네.', `MaleText_loc4`='我会让你知道这一点的。很明显，你如此迅速地成为中尉，已经证明了自己的实力。或许稍后你回到我这儿时，我会派给你任务的。委员会崇尚那些能熟练运用魔法的人，但也欢迎各种族的仆从，无论该仆从从事何种职业。', `MaleText_loc5`='我會讓你知道這一點的。很明顯，你如此迅速地成為中尉，已經證明了自己的實力。或許稍後你回到我這兒時，我會派給你任務的。委員會崇尚那些能熟練運用魔法的人，但也歡迎各種族的僕從，無論該僕從從事何種職業。', `MaleText_loc7`='Te lo haré saber. Está claro que te estás probando en nuestras filas para convertirte en teniente. Quizás puedas volver más adelante y tendré tareas para ti. El consejo adora a los diestros en la magia Arcana, pero son bienvenidos los siervos de todo tipo, sea cual sea su profesión.' WHERE `ID`=7265;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저한테는 솔직하게 얘기를 해도 괜찮습니다, 네루.', `MaleText_loc4`='你明说吧，尼尔鲁……', `MaleText_loc5`='你明說吧，尼爾魯...', `MaleText_loc7`='Puedes ser sincero, Neeru...', `FemaleText_loc1`='저한테는 솔직하게 얘기를 해도 괜찮습니다, 네루.', `FemaleText_loc4`='你明说吧，尼尔鲁……', `FemaleText_loc5`='你明說吧，尼爾魯...', `FemaleText_loc7`='Puedes ser sincero, Neeru...' WHERE `ID`=7266;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠의 의회가 실패한 일을 불타는 칼날단이라도 대신하는 걸 보니 기분이 참 좋군요.', `MaleText_loc4`='很高兴看到火刃接管了那些暗影议会无力接管的地方。', `MaleText_loc5`='很高興看到燃刃接管了那些暗影議會無力接管的地方。', `MaleText_loc7`='Es estupendo ver que el Filo Ardiente tiene éxito donde falló el Consejo de la Sombra.', `FemaleText_loc1`='어둠의 의회가 실패한 일을 불타는 칼날단이라도 대신하는 걸 보니 기분이 참 좋군요.', `FemaleText_loc4`='很高兴看到火刃接管了那些暗影议会无力接管的地方。', `FemaleText_loc5`='很高興看到燃刃接管了那些暗影議會無力接管的地方。', `FemaleText_loc7`='Es estupendo ver que el Filo Ardiente tiene éxito donde falló el Consejo de la Sombra.' WHERE `ID`=7267;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이글거리는 칼날단을 이용해도 된단 말이지요?', `MaleText_loc4`='这么说，燃刃可以牺牲了？', `MaleText_loc5`='這麼說，灼刃可以犧牲了?', `MaleText_loc7`='¿Así que la Hoja Abrasadora es prescindible?', `FemaleText_loc1`='이글거리는 칼날단을 이용해도 된단 말이지요?', `FemaleText_loc4`='这么说，燃刃可以牺牲了？', `FemaleText_loc5`='這麼說，灼刃可以犧牲了?', `FemaleText_loc7`='¿Así que la Hoja Abrasadora es prescindible?' WHERE `ID`=7268;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 성공해 돌아온다면...', `MaleText_loc4`='要是你能从我这儿拿走什么的话……', `MaleText_loc5`='要是你能從我這兒拿走什麼的話...', `MaleText_loc7`='Si necesitas algo de mí...', `FemaleText_loc1`='제가 성공해 돌아온다면...', `FemaleText_loc4`='要是你能从我这儿拿走什么的话……', `FemaleText_loc5`='要是你能從我這兒拿走什麼的話...', `FemaleText_loc7`='Si necesitas algo de mí...' WHERE `ID`=7269;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 타락했다.', `MaleText_loc4`='我被腐化了。', `MaleText_loc5`='我被腐化了。', `MaleText_loc7`='Ahora estoy corrupto.' WHERE `ID`=7270;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 난 구원받았어.', `MaleText_loc4`='我得救了。', `MaleText_loc5`='我得救了。', `MaleText_loc7`='Estoy salvado.' WHERE `ID`=7271;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너무 어두워...', `FemaleText_loc4`='这么黑暗……', `FemaleText_loc5`='這麼黑暗...', `FemaleText_loc7`='Tan oscuro...' WHERE `ID`=7272;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='거기 누구 있어요? 나의 오랜 친구, 티리온인가요? 우리를 구하러 왔나요?', `FemaleText_loc4`='有人吗？提里奥我的老朋友，是你吗？你来救我们吗？', `FemaleText_loc5`='有人嗎?提里奧我的老朋友，是你嗎?你來救我們嗎?', `FemaleText_loc7`='¿Hay alguien ahí? Tirion, viejo amigo, ¿eres tú? ¿Has venido a salvarnos?' WHERE `ID`=7273;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='모두... 죽은 건가?', `FemaleText_loc4`='他们都……死了？', `FemaleText_loc5`='他們都...死了?', `FemaleText_loc7`='¿Están todos... muertos?' WHERE `ID`=7274;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사크호프가... 가끔 사크호프가 찾아오고는 해요. 좋은 사람들이랍니다.', `FemaleText_loc4`='萨克霍夫……有时萨克霍夫他们会来。他们是好人。', `FemaleText_loc5`='薩克霍夫...有時薩克霍夫他們會來。他們是好人。', `FemaleText_loc7`='Los Sarkhoff... a veces la visita de Sarkhoff. Son buena gente.' WHERE `ID`=7275;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 탐험가 연맹의 일원으로서 유물을 찾아다녔소. 여명의 설원에 신비한 마법이 걸린 물건이 있다고 하는데... 대부분은 감시가 철저하지.', `MaleText_loc4`='作为探险者协会的一员，我曾在这片区域搜寻古代器物。据说冬泉谷有许多不可思议的物品……很多物品都受到严密的保护。', `MaleText_loc5`='作為探險者協會的一員，我曾在這片區域搜尋古代器物。據說冬泉谷有許多不可思議的物品...很多物品都受到嚴密的保護。', `MaleText_loc7`='Cuando formaba parte de la Liga de Expedicionarios, buscaba artefactos en la arena. Se decía que Cuna del Invierno contenía objetos con gran magia... La mayoría están muy protegidos.' WHERE `ID`=7276;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 집어삼킬 영혼이 있는지 두 눈을 번뜩이며 주위를 둘러봅니다.', `MaleText_loc4`='%s搜寻着灵魂，想要饱餐一顿！', `MaleText_loc5`='%s尋找可供吞食的靈魂。', `MaleText_loc7`='%s busca un alma que engullir.' WHERE `ID`=7277;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용액은 내 가마솥에 있습니다. 단지 미완성인 열쇠와 왕쇠똥구리만 처리하면 됩니다.', `MaleText_loc4`='熔炉中的溶液已经可以使用了。接下来无非是处理未完成的钥匙和圣甲虫的问题。', `MaleText_loc5`='熔爐中的溶液已經可以使用了。接下來無非是處理未完成的鑰匙和聖甲蟲的問題。', `MaleText_loc7`='La solución está lista en mi caldera. Solo hay que tratar la llave incompleta y el escarabajo.' WHERE `ID`=7278;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다 끝났습니다. 결과에 만족하실 겁니다.', `MaleText_loc4`='完成了$n，我想你会对结果感到满意的。', `MaleText_loc5`='完成了$n，我想你會對結果感到滿意的。', `MaleText_loc7`='Listo, $n, creo que estarás $gsatisfecho:satisfecha; con los resultados.' WHERE `ID`=7279;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용액은 내 가마솥에 있다네. 미완성인 열쇠와 왕쇠똥구리만 처리해 주면 되지.', `MaleText_loc4`='熔炉中的溶液已经可以使用了。接下来无非是处理未完成的钥匙和圣甲虫的问题。', `MaleText_loc5`='熔爐中的溶液已經可以使用了。接下來無非是處理未完成的鑰匙和聖甲蟲的問題。', `MaleText_loc7`='La solución está lista en mi caldera. Solo hay que tratar la llave incompleta y el escarabajo.' WHERE `ID`=7280;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다 끝났군. 결과에 만족할 것일세.', `MaleText_loc4`='完成了$n，我想你会对结果感到满意的。', `MaleText_loc5`='完成了$n，我想你會對結果感到滿意的。', `MaleText_loc7`='Listo, $n, creo que estarás $gsatisfecho:satisfecha; con los resultados.' WHERE `ID`=7281;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부대장 발린다 스톤하스가 곧 전초기지에 도착할 것입니다. 곧 전투가 새로 시작될 것입니다!', `MaleText_loc4`='巴琳达·斯通赫尔斯马上就会到位，新的战斗马上就要开始了！', `MaleText_loc5`='巴琳達·石爐馬上就會到位，新的戰鬥馬上就要開始了!', `MaleText_loc7`='La capitana Ballinda Piedrahogar llegará pronto a su baluarte. ¡Pronto se unirá a una nueva batalla!' WHERE `ID`=7282;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼음피 주둔지에 새로운 부대가 몰려왔습니다! 곧 부대장 갈반가르께서 도착하시면 새로운 전투가 벌어질 것입니다!', `MaleText_loc4`='援军补充入了冰血要塞！加尔范上尉马上就到，新的战斗马上开始！', `MaleText_loc5`='援軍補充入了冰血要塞!加爾凡加上尉馬上就到，新的戰鬥馬上開始!', `MaleText_loc7`='¡Tropas frescas llegan a raudales al Baluarte Sangrehielo! El capitán Galvangar llegará pronto, ¡enseguida comenzará una nueva batalla!' WHERE `ID`=7283;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기는 알터랙 계곡의 전장입니다. 현재 양 진영이 전투 중입니다.', `MaleText_loc4`='这是奥特兰克山谷战场。双方还在交战。', `MaleText_loc5`='這是奧特蘭克山谷戰場。雙方還在交戰。', `MaleText_loc7`='Este es el campo de batalla del Valle de Alterac. Los dos bandos siguen combatiendo.' WHERE `ID`=7284;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투 개시! 호드를 무찌릅시다!', `MaleText_loc4`='让我们展开新的战役，对抗部落！', `MaleText_loc5`='讓我們展開新的戰役，對抗部落!', `MaleText_loc7`='Vamos a comenzar una nueva batalla, ¡esta vez derrotad a la Horda!', `FemaleText_loc1`='전투 개시! 호드를 무찌릅시다!', `FemaleText_loc4`='让我们展开新的战?，对抗部落！', `FemaleText_loc5`='讓我們展開新的戰役，對抗部落!', `FemaleText_loc7`='Vamos a comenzar una nueva batalla, ¡esta vez derrotad a la Horda!' WHERE `ID`=7285;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기는 알터랙 계곡의 전장입니다. 현재 양 진영이 전투 중입니다.', `MaleText_loc4`='这是奥特兰克山谷战场。目前双方势均力敌。', `MaleText_loc5`='這是奧特蘭克山谷戰場。目前雙方正勢均力敵。', `MaleText_loc7`='Este es el campo de batalla del Valle de Alterac. Los dos bandos están en liza.' WHERE `ID`=7286;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투 개시! 얼라이언스를 무찌릅시다!', `MaleText_loc4`='让我们展开新的战役，这次要击败联盟！', `MaleText_loc5`='讓我們展開新的戰役，這次要擊敗聯盟!', `MaleText_loc7`='Vamos a comenzar una nueva batalla, ¡esta vez derrotad a la Alianza!', `FemaleText_loc1`='전투 개시! 얼라이언스를 무찌릅시다!', `FemaleText_loc4`='让我们展开新的战役，这次要击败联盟！', `FemaleText_loc5`='讓我們展開新的戰役，這次要擊敗聯盟!', `FemaleText_loc7`='Vamos a comenzar una nueva batalla, ¡esta vez derrotad a la Alianza!' WHERE `ID`=7287;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투 준비 완료! 우리 부대의 사기가 하늘을 찌를 듯합니다. 곧 부대장 발린다 스톤하스께서 전초기지에 들어서면 전투가 다시 시작될 겁니다!', `MaleText_loc4`='我们的军队已准备就绪，士气高涨。巴琳达·斯通赫尔斯将很快进入前哨，战争即将开始！', `MaleText_loc5`='我們的軍隊已準備就緒，士氣高漲。巴琳達·石爐將很快進入前哨，戰爭即將開始!', `MaleText_loc7`='Nuestras fuerzas están listas y llenas de entusiasmo. ¡Pronto Balinda Piedrahogar entrará en su Avanzada y la batalla comenzará de nuevo!' WHERE `ID`=7288;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반다르 스톰파이크 사령관이 전사했습니다! 우리가 패배했습니다!$B$B병참장교와 얘기하여 전력을 다시 구축하십시오.', `MaleText_loc4`='我们的将军范达尔·雷矛在战斗中倒下了！战斗失败了！$B$B和我们的军需官谈谈，然后帮助重建我们的部队。', `MaleText_loc5`='我們的將軍范達爾·雷矛在戰鬥中倒下了!戰鬥失敗了!$B$B和我們的軍需官談談，然後幫助重建我們的部隊。', `MaleText_loc7`='¡Nuestro general, Vanndar Pico Tormenta, ha caído en combate! ¡La batalla está perdida!$B$BHablad con nuestro intendente y ayudad a reconstruir nuestras fuerzas.' WHERE `ID`=7289;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드 사령관이 전사했습니다!$B$B얼라이언스의 승리입니다. 지금 호드는 약해진 전력을 보강하기 위해 허둥대고 있습니다.', `MaleText_loc4`='部落的将军被打败啦！$B$B联盟胜利啦，部落乱作一团，正忙着重建他们残弱的部队。', `MaleText_loc5`='部落的將軍被打敗啦!$B$B聯盟勝利啦，部落亂作一團，正忙著重建他們殘弱的部隊。', `MaleText_loc7`='¡El general de la Horda ha sido derrotado!$B$BLa Alianza se alza victoriosa, y la Horda se afana por reconstruir sus debilitadas fuerzas.' WHERE `ID`=7290;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='양 진영 모두 사령관이 없습니다.', `MaleText_loc4`='双方的将军均未重生。', `MaleText_loc5`='雙方的將軍均未重生。', `MaleText_loc7`='Ninguno de los generales ha vuelto a aparecer.' WHERE `ID`=7291;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드렉타르께서 전사했습니다! 이번 승리는... 얼라이언스의 것입니다.$B$B모든 호드는 병참장교를 도와 전력을 다시 구축하십시오!', `MaleText_loc4`='德雷克塔尔被击败了！联盟胜利了……至少现在是胜利了。$B$B和我们的军需官谈谈兵帮助我们的重建。', `MaleText_loc5`='德雷克塔爾被擊敗了!聯盟勝利了...至少現在是勝利了。$B$B和我們的軍需官談談兵幫助我們的重建。', `MaleText_loc7`='¡Drek''Thar ha sido derrotado! La Alianza se alza con la victoria... por ahora.$B$BHablen con sus intendentes y contribuyan en nuestra reconstrucción.' WHERE `ID`=7293;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기다, 여기! 계집애 같은 얼라 놈들아! 나 잡아봐라!', `MaleText_loc4`='我在这儿！过来和我作战，你们这些联盟的懦夫！', `MaleText_loc5`='我在這兒!過來和我作戰，你們這些聯盟的懦夫!', `MaleText_loc7`='¡Aquí estoy! ¡Venid a cogerme, cobardes de la Alianza!' WHERE `ID`=7294;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반다르 님 여기 계시다. 덤벼! 이 지저분한 호드놈들아! 잔재주라도 좀 부려봐라!', `MaleText_loc4`='范达尔在这儿！来吧！给我看看你有什么能耐！', `MaleText_loc5`='范達爾在這兒!來吧!給我看看你有什麼能耐!', `MaleText_loc7`='Vanndar está aquí. ¡Adelante hijos de la Horda! ¡Mostradme de lo que sois capaces!' WHERE `ID`=7295;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서리늑대 부족 사령관이 전사했습니다!', `MaleText_loc4`='部落的将军死了！', `MaleText_loc5`='部落的將軍死了!', `MaleText_loc7`='¡El general Lobo Gélido ha muerto!' WHERE `ID`=7296;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰파이크 사령관이 전사했습니다!', `MaleText_loc4`='联盟的将军死了！', `MaleText_loc5`='雷矛將軍死了!', `MaleText_loc7`='¡El general Pico Tormenta ha muerto!' WHERE `ID`=7297;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어이, 저기 코도를 조심하라고! 자네가 코도를 살펴본다면, 자넬 믿어주지!', `MaleText_loc4`='嗨，小心那头科多兽！你最好在我寄予你信任之前看好这头野兽！', `MaleText_loc5`='嗨，小心那頭科多獸!你最好在我寄予你信任之前看好這頭野獸!', `MaleText_loc7`='¡Eh, cuidado con ese kodo! ¡Te convendría examinar a esa bestia antes de que te dé crédito!' WHERE `ID`=7301;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 코도 정말 예쁘군, 잠시만... 내 안경이 어디 있지? 음... 자네가 날 위해 저 코도를 살펴봐 줘야겠어.', `MaleText_loc4`='那只科多兽真美。等等，我的眼镜在哪儿？也许你该帮我照看这头野兽。', `MaleText_loc5`='那隻科多獸真美。等等，我的眼睛在哪兒?也許你該幫我照看這頭野獸。', `MaleText_loc7`='Ese kodo es una belleza. Espera un segundo, ¿dónde están mis gafas bifocales? quizás deberías examinar por mí a la bestia.' WHERE `ID`=7302;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 신비한 코도 소리로군. 난 코도가 땅을 울리는 게 참 좋단 말이야. 날 위해 그 짐승을 살펴봐 주게.', `MaleText_loc4`='啊……科多兽令人惊奇的声音。我喜欢它们震动地表的方式……帮我照看这些野兽。', `MaleText_loc5`='啊...科多獸令人驚奇的聲音。我喜歡它們震動地表的方式...幫我照看這些野獸。', `MaleText_loc7`='Ah... el maravilloso sonido de los kodos. Me encanta cómo sacuden el suelo... examina por mí a la bestia.' WHERE `ID`=7303;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 고블린이 코도한테 짐을 지키게 할 수가 있나? 코도가 10배는 더 크다고!', `MaleText_loc4`='地精是如何把包裹放到这些野兽身上的，他们是怎么做到的？科多兽比他们大十倍！', `MaleText_loc5`='哥布林是如何把包裹放到這些野獸身上的，他們是怎麼做到的?科多獸比他們大十倍!', `MaleText_loc7`='¿Cómo se las arreglan los goblins para asegurar la carga en estas bestias? ¡Los kodos son diez veces más grandes que ellos!', `FemaleText_loc1`='어떻게 고블린이 코도한테 짐을 지키게 할 수가 있나? 코도가 10배는 더 크다고!', `FemaleText_loc4`='地精是如何把包裹放到这些野兽身上的，他们是怎么做到的？科多兽比他们大十倍！', `FemaleText_loc5`='哥布林是如何把包裹放到這些野獸身上的，他們是怎麼做到的?科多獸比他們大十倍!', `FemaleText_loc7`='¿Cómo se las arreglan los goblins para asegurar la carga en estas bestias? ¡Los kodos son diez veces más grandes que ellos!' WHERE `ID`=7304;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='위험한 시기라네, 모험가 양반. 걸음을 빨리 하시게나.', `FemaleText_loc4`='现在是危险时期，冒险者。多加小心。', `FemaleText_loc5`='現在是危險時期，冒險者。多加小心。', `FemaleText_loc7`='Corren tiempos peligrosos, $gaventurero:aventurera;. Ve con cautela.' WHERE `ID`=7305;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비됐습니다, 미란다.', `MaleText_loc4`='我准备好接受幻象了，麦兰达。', `MaleText_loc5`='我準備好接受幻影了，米蘭達。', `MaleText_loc7`='Estoy listo para la ilusión, Myranda.', `FemaleText_loc1`='준비됐습니다, 미란다.', `FemaleText_loc4`='我准备好接受幻象了，麦兰达。', `FemaleText_loc5`='我準備好接受幻影了，米蘭達。', `FemaleText_loc7`='Estoy lista para la ilusión, Myranda.' WHERE `ID`=7306;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요. 여명의 설원에는 무슨 일이신가요? 이 춥고 광활한 땅은 정말 황량하지만, 정말로 많은 비밀이 숨어 있답니다.', `FemaleText_loc4`='你好！是什么吸引你来到冬泉谷？这片寒冷广袤的土地或许显得有些凄凉，但是它蕴含着无数的秘密……', `FemaleText_loc5`='你好!是什麼吸引你來到冬泉谷?這片寒冷廣袤的土地或許顯得有些淒涼，但是它蘊含著無數的秘密...', `FemaleText_loc7`='¡Hola! ¿Qué te trae a la Cuna del Invierno? Estas tierras vastas y frías pueden parecer sombrías pero albergan mucho secretos...' WHERE `ID`=7307;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너무 슬퍼요오... 과거는 돌이킬 수 없거든요...', `FemaleText_loc4`='真让人感到悲痛……但是覆水难收……', `FemaleText_loc5`='真讓人感到悲痛...但是覆水難收...', `FemaleText_loc7`='Tantasssss penasss... El passsado no puede cambiarssse...' WHERE `ID`=7308;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 한 일은 잊지 않을 게요...$B$B제발 저...를...', `FemaleText_loc4`='我不会忘记你所做的……$B$B请离开我……', `FemaleText_loc5`='我不會忘記你所做的...$b$b請離開我...', `FemaleText_loc7`='No olvidaré lo que hasss hecho... $B$BPorrrr favorrrr, déjameeee...' WHERE `ID`=7309;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 자네 경호원이잖아! 어서 우릴 보호해 달라고...', `MaleText_loc4`='嗨，你说自己是一名保镖？那么保护我们吧……', `MaleText_loc5`='嗨，你說自己是一名保鏢?那麼保護我們吧...', `MaleText_loc7`='Eh, ¿y tú te llamas guardaespaldas? Ponte a trabajar y protégenos...' WHERE `ID`=7310;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 경호원 씨! 일 할 거야, 말 거야?', `MaleText_loc4`='保镖先生，你是要赚钱还是干嘛？', `MaleText_loc5`='保鏢先生，你是要賺錢還是幹嘛?', `MaleText_loc7`='Señor guardaespaldas, ¿vas a ganarte tu dinero o qué?' WHERE `ID`=7311;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자넨 해고야! <콜록거리며 목을 고르는 코르크> 아니 내 말은... 도와줘!', `MaleText_loc4`='你被炒鱿鱼了！ <咳嗽...考克清了清嗓子。> 我是说，快帮忙！', `MaleText_loc5`='你被炒魷魚了! <咳嗽...考克清了清嗓子。> 我是說，快幫忙!', `MaleText_loc7`='¡Estás $gdespedido:despedida;! <Cof... Cork carraspea.> Quiero decir... ¡ayuda!' WHERE `ID`=7312;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 하스글렌을 지나 이곳 외곽까지 인도하지. 자네는 거기서부터 날 아버지에게로 안내하게.', `MaleText_loc4`='我将带我们穿越壁炉谷到达森林的边缘。然后你就可以把我带到我父亲那儿了。', `MaleText_loc5`='我將帶我們穿越壁爐谷到達森林的邊緣。從那兒，你就能將我帶到我父親那兒了。', `MaleText_loc7`='Te guiaré a través de la Vega del Amparo hasta el final del bosque. Desde allí me llevarás con mi padre.' WHERE `ID`=7313;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 분노해 휘두른 칼에 맞으면 안 되니까 변장을 풀도록 하게.', `MaleText_loc4`='脱下你的伪装吧，以免我控制不住，挥刀伤到你。', `MaleText_loc5`='脫下你的偽裝吧，以免我控制不住，揮刀傷到你。', `MaleText_loc7`='Quítate el disfraz, no vaya a ser que sientas el mordisco de mi espada cuando la furia se haga con el control.' WHERE `ID`=7314;
