UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대영주님이 이상하다. 누가 어떻게 좀 해봐!', `MaleText_loc4`='大领主有些不对劲。采取行动！', `MaleText_loc5`='大領主有些不對勁。採取行動!', `MaleText_loc7`='Algo va mal con el Alto Señor. ¡Haz algo!', `FemaleText_loc1`='대영주님이 이상하다. 누가 어떻게 좀 해봐!', `FemaleText_loc4`='大领主有些不对劲。采取行动！', `FemaleText_loc5`='大領主有些不對勁。採取行動!', `FemaleText_loc7`='Algo va mal con el Alto Señor. ¡Haz algo!' WHERE `ID`=7320;
