UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 거기 무슨 일인가? 대영주님, 괜찮으십니까? 대영주님?', `MaleText_loc4`='嗨，那儿发生什么事了？先生，你还好吧？先生？？', `MaleText_loc5`='嗨，那兒發生什麼事了?先生，你還好吧?先生??', `MaleText_loc7`='Eh, ¿qué está pasando? Señor, ¿está bien? ¿¿Señor??', `FemaleText_loc1`='이봐, 거기 무슨 일인가? 대영주님, 괜찮으십니까? 대영주님?', `FemaleText_loc4`='嗨，那儿发生什么事了？先生，你还好吧？先生？？', `FemaleText_loc5`='嗨，那兒發生什麼事了?先生，你還好吧?先生??', `FemaleText_loc7`='Eh, ¿qué está pasando? Señor, ¿está bien? ¿¿Señor??' WHERE `ID`=7322;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폴드링 대영주님, 괜찮으십니까?', `MaleText_loc4`='大领主弗丁，你还好吧？', `MaleText_loc5`='大領主弗丁，你還好吧?', `MaleText_loc7`='Alto señor Vadín, ¿se encuentra bien?', `FemaleText_loc1`='폴드링 대영주님, 괜찮으십니까?', `FemaleText_loc4`='大领主弗丁，你还好吧？', `FemaleText_loc5`='大領主弗丁，你還好吧?', `FemaleText_loc7`='Alto señor Vadín, ¿se encuentra bien?' WHERE `ID`=7323;
