UPDATE `locales_broadcast_text` SET `MaleText_loc1`='프라우드무어다! 여기서 벗어나야 돼!', `MaleText_loc4`='是普罗德摩尔将军！离开这儿！', `MaleText_loc5`='是普勞德摩爾將軍!離開這兒!', `MaleText_loc7`='¡Es Valiente! ¡Fuera de aquí!', `FemaleText_loc1`='프라우드무어다! 여기서 벗어나야 돼!', `FemaleText_loc4`='是普罗德摩尔将军！离开这儿！', `FemaleText_loc5`='是普勞德摩爾將軍!離開這兒!', `FemaleText_loc7`='¡Es Valiente! ¡Fuera de aquí!' WHERE `ID`=7325;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 여기 있다. 얼라 놈들아! 한 번 쓰러뜨려 봐라!', `MaleText_loc4`='我来啦，联盟！如果你行的话……放马过来吧！', `MaleText_loc5`='我來啦，聯盟!如果你行的話...放馬過來吧!', `MaleText_loc7`='¡Aquí estoy, Alianza! Derrotadme... ¡si podéis!' WHERE `ID`=7326;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='얼라이언스를 위하여!', `FemaleText_loc4`='为了联盟！', `FemaleText_loc5`='為了聯盟!', `FemaleText_loc7`='¡Por la Alianza!' WHERE `ID`=7327;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잿빛 골짜기의 마에스트라 주둔지에 가서 파수꾼 오나에야를 만나보십시오. 그대가 오늘 보여준 용감한 행동에 대해 반드시 보답을 할 겁니다.', `FemaleText_loc4`='跟灰谷梅伊瑟娜岗哨的哨兵奥奈雅谈谈，她将为你今天的勇敢行为给予相应的回报。', `FemaleText_loc5`='跟梣谷邁斯特拉崗哨的哨兵奧奈雅談談，她將為你今天的勇敢行為給予相應的回報。', `FemaleText_loc7`='Por favor, ve a hablar con la centinela Onaeya en la Atalaya de Maestra, en Vallefresno, procurará dar una recompensa adecuada a la valentía que has mostrado este día.' WHERE `ID`=7328;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇게 멀지는 않군. 큰 길이 바로 위에 있네.', `MaleText_loc4`='还不够远。大道还在前面呢。', `MaleText_loc5`='還不夠遠。大道還在前面呢。', `MaleText_loc7`='No queda mucho. El camino principal está ahí delante.' WHERE `ID`=7329;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이크! 악마들이 우리 코도를 탐내는 것 같아요!', `MaleText_loc4`='呃！恶魔对科多兽垂涎欲滴！', `MaleText_loc5`='呃!惡魔對科多獸垂涎欲滴!', `MaleText_loc7`='¡Eeck! ¡Los demonios parecen hambrientos de kodo!' WHERE `ID`=7330;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이러고도 돈 받길 바라요? 코도가 죽을 뻔했잖아요!', `MaleText_loc4`='我付钱给你是为了什么？科多兽就快死了！', `MaleText_loc5`='我付錢給你是為了什麼?科多獸就快死了!', `MaleText_loc7`='¿Para qué te pago? ¡Los kodos están casi muertos!' WHERE `ID`=7331;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='키가 1.5미터만 더 컸어도 이 불손한 악마 놈들한테 예절이 뭔지 가르쳐 줄 텐데. 도와주세요!', `MaleText_loc4`='要是我再高五英尺，我就会给这些亵渎神明的恶魔一点颜色看看！快帮帮我！', `MaleText_loc5`='要是我再高五英尺，我就會給這些褻瀆神明的惡魔一點顏色看看!快幫幫我!', `MaleText_loc7`='¡Si tan solo fuera un metro y medio más alto enseñaría a esos malditos demonios un par de cosas! ¡Socorro!' WHERE `ID`=7332;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우와! 해냈어... 이렇게 쉬운데 우리가 왜 경호원 따위를 구하려고 했는지 모르겠네요. 어쨌든 스미드 스크래블스크류와 얘기해 보세요. 보상을 해줄 겁니다!', `MaleText_loc4`='啊哈！我们成功了……不明白为什么我们会认为需要像你这样的人。不管怎样，去跟斯米德·瑟卡布斯库谈谈吧；他会给你报酬的！', `MaleText_loc5`='啊哈!我們成功了...不明白為什麼我們會需要你這種人。不管怎樣，去跟斯米德·瑟卡布斯庫談談吧;他會給你報酬的!', `MaleText_loc7`='¡Guau! Lo conseguimos... no entiendo por qué pensábamos que necesitábamos tu ayuda. ¡Pero no importa, habla con Smeed Mezclatornillos, te dará tus honorarios!' WHERE `ID`=7333;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청한 켄타우로스를 해치워 달라고! 휴... 계약대로 잘해 줬군. 길을 따라 위로 가면 스미드 스크래블스크류가 보상을 해줄 거라고.', `MaleText_loc4`='杀死那些愚蠢的半人马！唉——嗯，似乎你信守承诺。沿着这条路走，去找斯米德·瑟卡布斯库，他会付钱给你的。', `MaleText_loc5`='殺死那些愚蠢的半人馬!唉─嗯，似乎你信守承諾。沿著這條路走，去找斯米德·瑟卡布斯庫，他會付錢給你的。', `MaleText_loc7`='¡Malditos sean esos estúpidos centauros! Uff... parece que mantienes tu trato. Siguiendo el camino encontrarás a Smeed Mezclatornillos, él tiene tu dinero.' WHERE `ID`=7334;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스 승리!', `MaleText_loc4`='联盟胜利了！', `MaleText_loc5`='聯盟勝利了!', `MaleText_loc7`='¡La Alianza gana!' WHERE `ID`=7335;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드 승리!', `MaleText_loc4`='部落胜利了！', `MaleText_loc5`='部落勝利了!', `MaleText_loc7`='¡La Horda gana!' WHERE `ID`=7336;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='결국, 날 좌절시키는군, 탤런! 널 목표로... 굉장한 계획을 세웠는데. 아아! 시간이 조금만 더 있었더라면 네가 그 더러운 혈통을 타고난 사실을 땅을 치며 후회하게 해줄 것을...', `MaleText_loc4`='你让我失望了，泰兰。原本我设计了一个规划……一个重要的计划。啊，你肮脏的血统最终表露出来只是个时间问题。', `MaleText_loc5`='你讓我失望了，泰蘭。原本我設計了一個規劃...一個重要的計畫。啊，你骯髒的血統最終表露出來只是個時間問題。', `MaleText_loc7`='Me has decepcionado, Taelan. Tenía planes para ti... grandes planes. Desgraciadamente era solo una cuestión de tiempo que tu sucia estirpe te recuperase.' WHERE `ID`=7337;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='들은 대로군. 그 아버지에 그 아들이라니... 티리온 만큼이나 나약하군. 어쩌면 더 나약할지도 모르겠고 말이야. 내가 보낸 암살자가 티리온의 비참한 삶을 끝내주길 바랄 뿐...', `MaleText_loc4`='就像他们说的：有其父必有其子。你就跟提里奥一样软弱……或许比他更软弱。我只希望我派出的刺客能顺利结束他令人同情的一生。', `MaleText_loc5`='就像他們說的:有其父必有其子。你就跟提里奧一樣軟弱...或許比他更軟弱。我只希望我派出的刺客能順利結束他令人同情的一生。', `MaleText_loc7`='Esto es lo que dijeron: De tal palo, tal astilla. Tu voluntad es tan débil como la de Tirion... quizás incluso más. Solo puedo esperar que mis asesinos triunfen y pongan fin a su lamentable vida.' WHERE `ID`=7338;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시험용 - 전장 재시작', `MaleText_loc4`='测试——重启战场。', `MaleText_loc5`='測試─重啟戰場。', `MaleText_loc7`='TEST- reinicio campo de batalla.', `FemaleText_loc1`='시험용 - 전장 재시작', `FemaleText_loc4`='测试——重启战场。', `FemaleText_loc5`='測試─重啟戰場。', `FemaleText_loc7`='TEST- reinicio campo de batalla.' WHERE `ID`=7339;
