UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잡히면 안 돼!', `MaleText_loc4`='别让他们抓住你！', `MaleText_loc5`='別讓他們抓住你!', `MaleText_loc7`='¡No dejéis que os atrapen!', `FemaleText_loc1`='잡히면 안 돼!', `FemaleText_loc4`='别让他们抓住你！', `FemaleText_loc5`='別讓他們抓住你!', `FemaleText_loc7`='¡No dejéis que os atrapen!' WHERE `ID`=7341;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잡히면 프라우드무어가 우릴 죽일 거야!', `MaleText_loc4`='如果我们被抓住的话，她会取我们的性命的！', `MaleText_loc5`='如果我們被抓住的話，她會取我們的性命的!', `MaleText_loc7`='¡Si nos atrapan ella se hará con nuestras cabezas!', `FemaleText_loc1`='잡히면 프라우드무어가 우릴 죽일 거야!', `FemaleText_loc4`='如果我们被抓住的话，她会取我们的性命的！', `FemaleText_loc5`='如果我們被抓住的話，她會取我們的性命的!', `FemaleText_loc7`='¡Si nos atrapan ella se hará con nuestras cabezas!' WHERE `ID`=7342;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다로우골이여! 희망의 빛을 잃지 말기를! 우리는 절대 꺾이지 않을 겁니다!', `MaleText_loc4`='达隆郡，别放弃希望！我们不会失败的！', `MaleText_loc5`='達隆郡，別放棄希望!我們不會失敗的!', `MaleText_loc7`='¡No pierdas la esperanza, Villa Darrow! ¡No fracasaremos!' WHERE `ID`=7343;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다빌, 네 안에서 성스러운 빛이 불타고 있군. 그럼, 즐거운 마음으로 그 빛을 꺼볼까!', `MaleText_loc4`='戴维，圣光照亮你的内心。我要把它挖出来！', `MaleText_loc5`='大衛，聖光照亮你的內心。我要把它挖出來!', `MaleText_loc7`='La Luz brilla con fuerza en ti, Davil. ¡Disfrutaré extinguiéndola!' WHERE `ID`=7344;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간이 됐다, 다빌. 네가 죽을 시간!', `MaleText_loc4`='戴维，你的死期到了！', `MaleText_loc5`='大衛，你的死期到了!', `MaleText_loc7`='Ya es la hora, Davil. ¡Es la hora de tu muerte!' WHERE `ID`=7345;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호르구스, 네놈의 악몽도 여기까지다! 각오해라!', `MaleText_loc4`='霍古斯，你的噩梦结束了！现在！', `MaleText_loc5`='霍古斯，你的夢魘結束了!現在!', `MaleText_loc7`='Horgus, ¡tu pesadilla ha terminado! ¡Ahora!' WHERE `ID`=7346;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다로우골을 위하여!', `MaleText_loc4`='为了达隆郡！', `MaleText_loc5`='為了達隆郡!', `MaleText_loc7`='¡Por Villa Darrow!', `FemaleText_loc1`='다로우골을 위하여!', `FemaleText_loc4`='为了达隆郡！', `FemaleText_loc5`='為了達隆郡!', `FemaleText_loc7`='¡Por Villa Darrow!' WHERE `ID`=7347;
