UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싸워라! 우리의 가족을 위해!', `MaleText_loc4`='战斗！为了你的家人而战！', `MaleText_loc5`='戰鬥!為了你的家人而戰!', `MaleText_loc7`='¡Luchen! ¡Luchen por sus familias!', `FemaleText_loc1`='싸워라! 우리의 가족을 위해!', `FemaleText_loc4`='战斗！为了你的家人而战！', `FemaleText_loc5`='戰鬥!為了你的家人而戰!', `FemaleText_loc7`='¡Luchen! ¡Luchen por sus familias!' WHERE `ID`=7349;
