UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싸워라! 승리는 우리 것이다!', `MaleText_loc4`='战斗，我们今天一定会赢！', `MaleText_loc5`='戰鬥，我們今天一定會贏!', `MaleText_loc7`='¡Luchad y este día será el de nuestra victoria!', `FemaleText_loc1`='싸워라! 승리는 우리 것이다!', `FemaleText_loc4`='战斗，我们今天一定会赢！', `FemaleText_loc5`='戰鬥，我們今天一定會贏!', `FemaleText_loc7`='¡Luchad y este día será el de nuestra victoria!' WHERE `ID`=7352;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형제자매들이여, 최후의 순간까지 싸우자!', `MaleText_loc4`='战斗直到最后一息，兄弟姐妹们！', `MaleText_loc5`='戰鬥直到最後一息，兄弟姐妹們!', `MaleText_loc7`='¡Luchad hasta el último aliento, hermanos y hermanas!', `FemaleText_loc1`='형제자매들이여, 최후의 순간까지 싸우자!', `FemaleText_loc4`='战斗直到最后一息，兄弟姐妹们！', `FemaleText_loc5`='戰鬥直到最後一息，兄弟姐妹們!', `FemaleText_loc7`='¡Luchad hasta el último aliento, hermanos y hermanas!' WHERE `ID`=7353;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕에게로 돌아가, 역겨운 놈들아!', `MaleText_loc4`='回到你的巫妖王那里去，肮脏的东西！', `MaleText_loc5`='回到你的巫妖王那裡去，骯髒的東西!', `MaleText_loc7`='¡Regresen con su Rey Exánime, horrendas criaturas!', `FemaleText_loc1`='리치 왕에게로 돌아가, 역겨운 놈들아!', `FemaleText_loc4`='回到你的巫妖王那里去，肮脏的东西！', `FemaleText_loc5`='回到你的巫妖王那裡去，骯髒的東西!', `FemaleText_loc7`='¡Regresen con su Rey Exánime, horrendas criaturas!' WHERE `ID`=7354;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다로우골의 병사들이여! 집결하라! 반드시 승리해야 한다!', `MaleText_loc4`='达隆郡的守护者们！集合起来！我们必须战胜他们！', `MaleText_loc5`='達隆郡的防衛者們!集合起來!我們必須戰勝他們!', `MaleText_loc7`='¡Defensores de Villa Darrow! ¡Reuníos! ¡Debemos imponernos!' WHERE `ID`=7355;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다로우골! 이제 끝장이다!', `MaleText_loc4`='达隆郡！这是命中注定的！', `MaleText_loc5`='達隆郡!這是命中註定的!', `MaleText_loc7`='¡Villa Darrow! ¡Estás perdida!' WHERE `ID`=7356;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다로우골은 패배한다! 조만간 로데론 전역이 파괴될 것이다!', `MaleText_loc4`='达隆郡被击败了！很快，整个洛丹伦就会陷落！', `MaleText_loc5`='達隆郡被擊敗了!很快，整個羅德隆就會陷落!', `MaleText_loc7`='¡Villa Darrow ha sido derrotada! ¡Pronto caerá todo Lordaeron!' WHERE `ID`=7357;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다로우골의 병사들이여, 전투 준비! 스컬지가 접근한다!', `MaleText_loc4`='达隆郡的勇士们，拿起武器吧！亡灵天灾就要来了！', `MaleText_loc5`='達隆郡的勇士們，拿起武器吧!天譴軍團就要來了!', `MaleText_loc7`='¡Villa Darrow, a las armas! ¡La Plaga se acerca!', `FemaleText_loc1`='다로우골의 병사들이여, 전투 준비! 스컬지가 접근한다!', `FemaleText_loc4`='达隆郡的勇士们，拿起武器吧！亡灵天灾就要来了！', `FemaleText_loc5`='達隆郡的勇士們，拿起武器吧!天譴軍團就要來了!', `FemaleText_loc7`='¡Villa Darrow, a las armas! ¡La Plaga se acerca!' WHERE `ID`=7358;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='십자군 사령관께서 너와 최근에 발견한 너의 친구들을 제거하라고 하셨지. 하지만 말이야 탤런, 이 말은 꼭하고 싶군. 꼭 명령이나 임무가 아니더라도 난 이 일을 하게 되어 즐겁다네.', `MaleText_loc4`='大十字军命令我毁掉了你和你新交的朋友泰兰，但是你要知道：我做这事儿纯属个人兴趣，跟职责和义务无关。', `MaleText_loc5`='大十字軍命令我毀掉了你和你新交的朋友泰蘭，但是你要知道:我做這事兒純屬個人興趣，跟職責和義務無關。', `MaleText_loc7`='El Gran Cruzado me ha encargado destruirte a ti y a tus nuevos amigos, Taelan, pero has de saber algo: lo hago por placer, no por obligación ni por deber.' WHERE `ID`=7359;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 보초병을 부릅니다.', `MaleText_loc4`='%s呼叫他的卫兵。', `MaleText_loc5`='%s呼叫他的守衛。', `MaleText_loc7`='%s llama a sus guardias.' WHERE `ID`=7360;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 끝이군, 폴드링.', `MaleText_loc4`='弗丁，该结束了。', `MaleText_loc5`='弗丁，該結束了。', `MaleText_loc7`='Este es el fin, Vadín.' WHERE `ID`=7361;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앉아서 내 얘기를 좀 들어보게, $r.', `MaleText_loc4`='坐下来听听我的故事吧，$r。', `MaleText_loc5`='坐下來聽聽我的故事吧，$r。', `MaleText_loc7`='Siéntate y escucha mi historia, $r.' WHERE `ID`=7362;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='시간이 너무 많이 지났군요. 나중을 기약하기로 해요.', `FemaleText_loc4`='已经过了太久了。我们必须晚些再试。', `FemaleText_loc5`='已經過了太久了。我們必須晚些再試。', `FemaleText_loc7`='Ha pasado demasiado tiempo. Debemos volver a intentarlo luego.' WHERE `ID`=7363;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘했어요, 계속 가야 해요!', `FemaleText_loc4`='好了，我们继续前进！', `FemaleText_loc5`='好了，我們繼續前進!', `FemaleText_loc7`='¡Muy bien, pongámonos en marcha!' WHERE `ID`=7364;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='기억해두세요. 제가 주문을 외우는데 집중하려면 그대의 도움이 꼭 필요해요. 목적을 달성할 때까지 몇 차례 도움을 청할 테니 준비하고 계세요.', `FemaleText_loc4`='记住，我需要你的帮助来正确进行吟唱。我在我们前进的路上会请你帮好几次忙，所以请准备好。', `FemaleText_loc5`='記住，我需要你的幫助來正確進行吟唱。我在我們前進的路上會請你幫好幾次忙，所以請準備好。', `FemaleText_loc7`='Recuerda, necesito tu ayuda para la canalización. Te pediré ayuda varias veces durante nuestro camino, tendrás que estar $gpreparado:preparada;.' WHERE `ID`=7365;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다빌 라이트파이어가 죽었다! 다로우골이 졌다!', `MaleText_loc4`='达维·莱法尔死了！达隆郡沦陷了！', `MaleText_loc5`='達維·萊法爾死了!達隆郡淪陷了!', `MaleText_loc7`='¡Davil Fuegoluz ha sido derrotado! ¡Villa Darrow está perdida!', `FemaleText_loc1`='다빌 라이트파이어가 죽었다! 다로우골이 졌다!', `FemaleText_loc4`='达维·莱法尔死了！达隆郡沦陷了！', `FemaleText_loc5`='達維·萊法爾死了!達隆郡淪陷了!', `FemaleText_loc7`='¡Davil Fuegoluz ha sido derrotado! ¡Villa Darrow está perdida!' WHERE `ID`=7366;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다빌 라이트파이어가 부상으로 죽었다!', `MaleText_loc4`='达维·莱法尔死于重伤！', `MaleText_loc5`='達維·萊法爾死於重傷!', `MaleText_loc7`='¡Davil Fuegoluz ha sucumbido a sus heridas!', `FemaleText_loc1`='다빌 라이트파이어가 부상으로 죽었다!', `FemaleText_loc4`='达维·莱法尔死于重伤！', `FemaleText_loc5`='達維·萊法爾死於重傷!', `FemaleText_loc7`='¡Davil Fuegoluz ha sucumbido a sus heridas!' WHERE `ID`=7367;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호르구스가 죽었다! 힘을 내라! 다로우골의 파수병들이여!', `MaleText_loc4`='霍古斯被杀了！振作起来，达隆郡的守卫们！', `MaleText_loc5`='霍古斯被殺了!振作起來，達隆郡的防衛者們!', `MaleText_loc7`='¡Horgus ha sido asesinado! ¡Ánimo, defensores de Villa Darrow!', `FemaleText_loc1`='호르구스가 죽었다! 힘을 내라! 다로우골의 파수병들이여!', `FemaleText_loc4`='霍古斯被杀了！振作起来，达隆郡的守卫们！', `FemaleText_loc5`='霍古斯被殺了!振作起來，達隆郡的防衛者們!', `FemaleText_loc7`='¡Horgus ha sido asesinado! ¡Ánimo, defensores de Villa Darrow!' WHERE `ID`=7368;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경비대장 레드패스가 죽었다!', `MaleText_loc4`='雷德帕斯队长被杀了！', `MaleText_loc5`='雷德帕斯隊長被殺了!', `MaleText_loc7`='¡El capitán Rutagrana ha sido asesinado!', `FemaleText_loc1`='경비대장 레드패스가 죽었다!', `FemaleText_loc4`='雷德帕斯队长被杀了！', `FemaleText_loc5`='雷德帕斯隊長被殺了!', `FemaleText_loc7`='¡El capitán Rutagrana ha sido asesinado!' WHERE `ID`=7369;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이실리엔!', `MaleText_loc4`='伊森利恩！', `MaleText_loc5`='伊森利恩!', `MaleText_loc7`='¡Isillien!' WHERE `ID`=7370;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이방인, 자네와는 상관없는 싸움이다. 진홍십자군 정예병의 공격으로부터 몸을 지켜라. 나는 종교재판장과 일전을 치르겠다.', `MaleText_loc4`='这场战斗跟你没有关系，$c。保护好你自己，当心别被红衣精英干掉。我会去挑战大检察官的。', `MaleText_loc5`='這場戰鬥跟你沒有關係，$c。保護好你自己，當心別被紅衣精英幹掉。我會去挑戰大審判官的。', `MaleText_loc7`='Esta no es tu lucha, $gforastero:forastera;. Protégete de los ataques de la Élite carmesí. Yo lucharé con el Gran inquisidor.' WHERE `ID`=7371;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 짓인가, 이실리엔? 한 때 명예를 위해, 백성을 위해 싸우던 자네가... 자네가 내 아들을 해치다니...', `MaleText_loc4`='你做了什么，伊森利恩？你从前为名誉而战，为了人民的幸福而战……而现在……你杀死了我的孩子……', `MaleText_loc5`='你做了什麼，伊森利恩?你從前為名譽而戰，為了人民的幸福而戰...而現在...你殺死了我的孩子...', `MaleText_loc7`='¿Qué has hecho, Isillien? Hubo un día en el que luchabas con honor, por el bien de nuestra gente... y ahora... has asesinado a mi chico...' WHERE `ID`=7372;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이실리엔, 자네 영혼은 고통 속에서 불타게 될 것이야! 빛이시여! 저에게 이자와 대적할 힘을 주소서.', `MaleText_loc4`='伊森利恩，你的灵魂将痛苦地燃烧着！圣光会赋予我力量对抗这个恶魔的。', `MaleText_loc5`='伊森利恩，你的靈魂將痛苦地燃燒著!聖光會賦予我力量對抗這個惡魔的。', `MaleText_loc7`='¡Que tu alma arda de angustia, Isillien! ¡Luz, dame fuerza para enfrentarme a este demonio!' WHERE `ID`=7373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나를 보게나. 한 때 자네가 보여 주었던 신념과 힘을 직시하란 말이네.', `MaleText_loc4`='看着我，胆小鬼。面对你从前也曾拥有的信念和力量。', `MaleText_loc5`='看著我，膽小鬼。面對你從前也曾擁有的信念和力量。', `MaleText_loc7`='Enfréntate a mí, cobarde. Enfréntate a la fe y a la fuerza que un día encarnaste.' WHERE `ID`=7374;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저 푸른 빛은... 이상하군요. 저게 과연 무슨 뜻일까요?', `FemaleText_loc4`='这蓝色的亮光……真奇怪。你认为它意味着什么？', `FemaleText_loc5`='這藍色的亮光...真奇怪，$n。你認為它意味著什麼?', `FemaleText_loc7`='Esta luz azul... es extraña. ¿Qué crees que significa?' WHERE `ID`=7375;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$g 이봐요, 귀여운 친구. 그롬골로 타고 갈 걸 찾으십니까? 저 너머 가시덤불 골짜기의 정글은 점점 찜통이 되고 있다더군요. 비행선에 몸을 맡기면 그곳에서 짧은 휴가를 만끽할 수 있게 되는 겁니다. 어쩌면 진짜 정글표범도 볼 수도 있고. 어떻습니까? : 멋지고 화려한 열대 정글이 우거진 가시덤불 골짜기로 여행을 떠나보십시오. 에메랄드빛 해안에서 일광욕을 할 수도 있습니다. 제가 온종일 여기 서서 이 지독한 열기를 견디면서 프레자 형 얼굴이나 보는 동안 말입니다. 즐거운 시간이 되시기를 바랍니다! ;', `MaleText_loc4`='$g嗨，帅哥，你想去格罗姆高吗？我听说那里的丛林整日雾气腾腾的，也许我们可以一起度个短假，我让你看看真正的丛林虎怎么样？:来吧，参观一下奇妙绚丽的荆棘谷丛林。你可以在水晶般的蓝色海岸线上惬意地洗日光浴，而我却站在这难以忍受的高温下整天傻看着我的兄弟弗雷萨！尽情享受你的旅程吧！;', `MaleText_loc5`='$g嗨，帥哥，你想去格羅姆高嗎?我聽說那裡的叢林整日霧氣騰騰的，也許我們可以一起度個短假，我讓你看看真正的叢林虎怎麼樣?:來吧，參觀一下奇妙絢麗的荊棘谷叢林。你可以在水晶般的藍色海岸線上愜意地洗日光浴，而我卻站在這難以忍受的高溫下整天傻看著我的兄弟弗雷薩!盡情享受你的旅程吧!;', `MaleText_loc7`='$gEh, monada, ¿necesitar viajar a Grom''gol? He oído que esas junglas se llegan a poner muy calientes... quizás me una a ti para ir de vacaciones, te mostraré lo que es un auténtico felino.:Ven, viaja a las maravillosas y estupendas selvas tropicales de Tuercespina. Está bien, puedes pasarte el tiempo tomando el sol junto a las aguas cristalinas mientras yo me quedo aquí con este calor insoportable y sin nada más que hacer que mirar todo el día a mi hermano Frezza. ¡Disfruta del viaje!;', `FemaleText_loc1`='$g 이봐요, 귀여운 친구. 그롬골로 타고 갈 걸 찾나요? 저 너머 가시덤불 골짜기의 정글은 점점 찜통이 되고 있다던데. 비행선에 몸을 맡기면 그곳에서 짧은 휴가를 만끽할 수 있게 되는 거예요. 어쩌면 진짜 정글표범도 볼 수도 있고. 어때요? : 멋지고 화려한 열대 정글이 우거진 가시덤불 골짜기로 여행을 떠나보세요. 에메랄드빛 해안에서 일광욕을 할 수도 있어요. 제가 온종일 여기 서서 이 지독한 열기를 견디면서 프레자 오빠의 얼굴이나 보는 동안 말이죠. 즐거운 시간이 되시기를 바라요! ;', `FemaleText_loc4`='$g嗨，帅哥，你想去格罗姆高吗？我听说那里的丛林整日雾气腾腾的，也许我们可以一起度个短假，我让你看看真正的丛林虎怎么样？:来吧，参观一下奇妙绚丽的荆棘谷丛林。你可以在水晶般的蓝色海岸线上惬意地洗日光浴，而我却站在这难以忍受的高温下整天傻看着我的兄弟弗雷萨！尽情享受你的旅程吧！;', `FemaleText_loc5`='$g嗨，帥哥，你想去格羅姆高嗎?我聽說那裡的叢林整日霧氣騰騰的，也許我們可以一起度個短假，我讓你看看真正的叢林虎怎麼樣?:來吧，參觀一下奇妙絢麗的荊棘谷叢林。你可以在水晶般的藍色海岸線上愜意地洗日光浴，而我卻站在這難以忍受的高溫下整天傻看著我的兄弟弗雷薩!盡情享受你的旅程吧!;', `FemaleText_loc7`='$gEh, monada, ¿necesitar viajar a Grom''gol? He oído que esas junglas se llegan a poner muy calientes... quizás me una a ti para ir de vacaciones, te mostraré lo que es un auténtico felino.:Ven, viaja a las maravillosas y estupendas selvas tropicales de Tuercespina. Está bien, puedes pasarte el tiempo tomando el sol junto a las aguas cristalinas mientras yo me quedo aquí con este calor insoportable y sin nada más que hacer que mirar todo el día a mi hermano Frezza. ¡Disfruta del viaje!;' WHERE `ID`=7376;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐 원하는 게 있으면 사장 손에 몇 실버쯤 쥐여주지 그래요. 전 정말이지 이 일을 사랑합니다. 하지만 작은 폭탄 같은 스눌크가 이 항구에 다시 배정되게 할 수만 있다면... 그보다 더 좋을 순 없겠죠. 하여간 당신이 제 사업 때문에 여기 오신 건 확실히 아닐 테고. 언더시티로 가는 비행선을 타러 오신 거겠죠? 맞죠? 네, 비행선은 바로 제 뒤에 정박합니다. 참, 스눌크를 보면 제 얘기 좀 잘 해주십쇼. 알았죠?', `MaleText_loc4`='将一枚硬币塞到首领手中，看看你会得到什么。我喜欢自己的工作。但是，如果我能设法让斯纳尔克重新分配给这个飞行点的话……那样就好了。但是我敢打赌，你到这儿来不是要帮我进行职业训练的，而是寻找地精飞艇前往幽暗城，对吧？那很好，因为它会停泊在我后面。如果你看见斯纳尔克，代我向他问好，行吗？', `MaleText_loc5`='將一枚硬幣塞到首領手中，看看你會得到什麼。我喜歡自己的工作。但是，如果我能設法讓斯納爾克重新分配給這個飛行點的話...那樣就好了。但是我敢打賭，你到這兒來不是要幫我進行職業訓練的，而是尋找地精飛艇前往幽暗城，對吧?那很好，因為它會停泊在我後面。如果你看見斯納爾克，代我向他問好，行嗎?', `MaleText_loc7`='Deja caer una moneda en la mano del jefe y mira lo que pasa. Adoro mi trabajo. Aunque si pudiera encontrar un modo de que reasignaran a ese petardo de Snurk a este puerto... bien, no puedo imaginar nada mejor. Pero supongo que no estás aquí por estas cosas. Buscas el zepelín a Entrañas, ¿me equivoco? Genial, porque el embarcadero está justo detrás de mí. Oh, y escucha, si ves a Snurk háblale bien de mí, ¿lo harás?', `FemaleText_loc1`='뭐 원하는 게 있으면 사장 손에 몇 실버쯤 쥐여주지 그래요. 전 정말이지 이 일을 사랑합니다. 하지만 작은 폭탄 같은 스눌크가 이 항구에 다시 배정되게 할 수만 있다면... 그보다 더 좋을 순 없겠죠. 하여간 당신이 제 사업 때문에 여기 오신 건 확실히 아닐 테고. 언더시티로 가는 비행선을 타러 오신 거겠죠? 맞죠? 네, 비행선은 바로 제 뒤에 정박합니다. 참, 스눌크를 보면 제 얘기 좀 잘 해주십쇼. 알았죠?', `FemaleText_loc4`='将一枚硬币塞到首领手中，看看你会得到什么。我喜欢自己的工作。但是，如果我能设法让斯纳尔克重新分配给这个飞行点的话……那样就好了。但是我敢打赌，你到这儿来不是要帮我进行职业训练的，而是寻找地精飞艇前往幽暗城，对吧？那很好，因为它会停泊在我后面。如果你看见斯纳尔克，代我向他问好，行吗？', `FemaleText_loc5`='將一枚硬幣塞到首領手中，看看你會得到什麼。我喜歡自己的工作。但是，如果我能設法讓斯納爾克重新分配給這個飛行點的話...那樣就好了。但是我敢打賭，你到這兒來不是要幫我進行職業訓練的，而是尋找地精飛艇前往幽暗城，對吧?那很好，因為它會停泊在我後面。如果你看見斯納爾克，代我向他問好，行嗎?', `FemaleText_loc7`='Deja caer una moneda en la mano del jefe y mira lo que pasa. Adoro mi trabajo. Aunque si pudiera encontrar un modo de que reasignaran a ese petardo de Snurk a este puerto... bien, no puedo imaginar nada mejor. Pero supongo que no estás aquí por estas cosas. Buscas el zepelín a Entrañas, ¿me equivoco? Genial, porque el embarcadero está justo detrás de mí. Oh, y escucha, si ves a Snurk háblale bien de mí, ¿lo harás?' WHERE `ID`=7377;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 주문을 외우는데 집중하는 동안 불을 밝혀 주세요.', `FemaleText_loc4`='请在我吟唱的时候点亮这个。', `FemaleText_loc5`='請在我吟唱的時候點亮這個。', `FemaleText_loc7`='Por favor, ilumina esto mientras estoy canalizando.' WHERE `ID`=7378;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기예요. 불을 밝혀 주세요.', `FemaleText_loc4`='就是这个地方。让我们点亮它。', `FemaleText_loc5`='就是這個地方。讓我們點亮它。', `FemaleText_loc7`='Aquí es. Vamos a iluminarlo.' WHERE `ID`=7379;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리가 찾아냈어요!', `FemaleText_loc4`='我们找到它了！', `FemaleText_loc5`='我們找到它了，$n。', `FemaleText_loc7`='¡Lo hemos encontrado!' WHERE `ID`=7380;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만!', `MaleText_loc4`='够了！', `MaleText_loc5`='夠了!', `MaleText_loc7`='¡Ya es suficiente!' WHERE `ID`=7381;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 웃습니다.', `MaleText_loc4`='%s笑了。', `MaleText_loc5`='%s大笑。', `MaleText_loc7`='%s ríe.' WHERE `ID`=7382;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 날 이길 수 있다고 생각했나? 네 친구도 곧 보내 주마, 탤런.', `MaleText_loc4`='你真的认为自己能打败我吗？你的朋友很快就会随你去的，泰兰。', `MaleText_loc5`='你真的認為自己能打敗我嗎?你的朋友很快就會隨你去的，泰蘭。', `MaleText_loc7`='¿De verdad creías que podrías vencerme? Tus amigos pronto se reunirán contigo, Taelan.' WHERE `ID`=7383;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 고개를 돌려 이쪽을 봅니다.', `MaleText_loc4`='%s注意到你了。', `MaleText_loc5`='%s注意到你了。', `MaleText_loc7`='%s vuelve hacia ti su atención.' WHERE `ID`=7384;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 마지막 단계입니다. 제단을 여세요.', `FemaleText_loc4`='现在该进行最后一步了，我们必须激活祭坛。', `FemaleText_loc5`='$n，現在該進行最後一步了;我們必須啟動祭壇。', `FemaleText_loc7`='Ha llegado la hora del sueño final; debemos activar el altar.' WHERE `ID`=7385;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='난 돌에 새겨진 룬을 읽겠어요. 그대는 제단을 열 방법을 찾으세요.', `FemaleText_loc4`='我会阅读刻在石头上的字，而你必须想办法点亮它。', `FemaleText_loc5`='我會讀刻在石頭上的字，而你必須想辦法點亮它。', `FemaleText_loc7`='Leeré las palabras talladas en la piedra, encuentra una forma de iluminarla.' WHERE `ID`=7386;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제단이... 제단이 열리고 있어요!', `FemaleText_loc4`='它……它起作用了！', `FemaleText_loc5`='它...它起作用了!', `FemaleText_loc7`='¡Es... está funcionando!' WHERE `ID`=7387;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무슨 일이 일어난 걸까요? 앗! 보세요!', `FemaleText_loc4`='发生什么了？看！', `FemaleText_loc5`='發生什麼了?看!', `FemaleText_loc7`='¿Qué ocurre? ¡Mira!' WHERE `ID`=7388;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아... 실로 오랜 세월이 흘렀구나...', `FemaleText_loc4`='已经很多年了……', `FemaleText_loc5`='已經很多年了...', `FemaleText_loc7`='Han sido muchos años...' WHERE `ID`=7389;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='감히 누가 엘룬의 제단에서 소란을 일으키는 것이냐?', `FemaleText_loc4`='谁在女神的祭坛捣乱？', `FemaleText_loc5`='誰在女神的祭壇搗亂?', `FemaleText_loc7`='¿Quién ha perturbado el altar de la diosa?' WHERE `ID`=7390;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여사제시여, 성소에 들어와 소란을 일으킨 죄를 용서하소서. 절대 이곳에 어떤 피해도 입히지 않겠나이다.', `FemaleText_loc4`='女祭司,请原谅我们的闯入。我们不想造成任何伤害。', `FemaleText_loc5`='女祭司，請原諒我們的闖入。我們不想造成任何傷害。', `FemaleText_loc7`='Por favor, sacerdotisa, perdona nuestra intromisión. No queremos causar ningún problema.' WHERE `ID`=7391;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저희는 단지 올빼미야수가 이 지역을 수호하는 이유를 알고자 할 뿐입니다.', `FemaleText_loc4`='我们只是希望知道枭兽为什么要守卫这片地区……', `FemaleText_loc5`='我們只是希望知道梟獸為什麼要守衛這片地區...', `FemaleText_loc7`='Solo queremos saber por qué los lechúcicos salvajes guardan esta zona...' WHERE `ID`=7392;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='에누도라 세라도르... 이곳은 성스럽고 무서운 곳이다.', `FemaleText_loc4`='Enu thora''serador。这是一片神圣之地。', `FemaleText_loc5`='(達納蘇斯語)伊奴·索拉''西拉朵。這是一片神聖之地。', `FemaleText_loc7`='Enu thora''serador. Este lugar es sagrado.' WHERE `ID`=7393;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 그대들에게 보여주도록 하겠노라...', `FemaleText_loc4`='我们会给你看……', `FemaleText_loc5`='我們會給你看...', `FemaleText_loc7`='Te enseñaremos...' WHERE `ID`=7394;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 이런... 폴드링, 자네를 그렇게 쉽게 보내줄 수는 없지.', `MaleText_loc4`='你不会到达森林边缘的，弗丁。', `MaleText_loc5`='你不會到達森林邊緣的，弗丁。', `MaleText_loc7`='No lo harás en el extremo del bosque, Vadín.' WHERE `ID`=7395;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마침내 악몽이 끝났다! 다로우골이여, 날 용서해라!', `MaleText_loc4`='恶梦终于结束了！达隆郡，原谅我吧！', `MaleText_loc5`='夢魘終於結束了!達隆郡，原諒我吧!', `MaleText_loc7`='¡La Pesadilla por fin ha terminado! ¡Villa Darrow, perdóname!' WHERE `ID`=7396;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파멜라? 아가, 거기 있느냐?', `MaleText_loc4`='帕米拉？亲爱的，你在那儿吗？', `MaleText_loc5`='帕米拉?親愛的，你在那兒嗎?', `MaleText_loc7`='¿Pamela? ¿Estás ahí, tesoro?' WHERE `ID`=7397;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하하!', `MaleText_loc4`='哈！', `MaleText_loc5`='哈!', `MaleText_loc7`='¡Jaja!' WHERE `ID`=7398;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아빠!', `FemaleText_loc4`='爸爸！', `FemaleText_loc5`='爸爸!', `FemaleText_loc7`='¡Papá!' WHERE `ID`=7399;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아빠! 왜 이리 늦게 온 거야!', `FemaleText_loc4`='爸爸！你回来了！', `FemaleText_loc5`='爸爸!你回來了!', `FemaleText_loc7`='¡Papá! ¡Has vuelto!' WHERE `ID`=7400;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아빠! 나랑 놀아줘요! 재미난 이야기도 해줘! 예쁜 꽃도 꺾으러 가고! 아이스크림도 사줘요! 인형도 찾았는데... 내가 아빠한테 말해줬나?', `FemaleText_loc4`='我们去玩吧！不，给我讲个故事，爸爸！不……我们去摘花！然后喝茶！我找到我的玩具娃娃了，我告诉过你吗？', `FemaleText_loc5`='我們去玩吧!不，給我講個故事，爸爸!不...我們去摘花!然後喝茶!我找到我的玩具娃娃了，我告訴過你嗎?', `FemaleText_loc7`='¡Vamos a jugar! No, ¡cuéntame un cuento, papá! No... ¡vamos a coger flores! ¡Y a jugar a cocinitas! He encontrado mi muñeca, ¿te lo había dicho?' WHERE `ID`=7401;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아빠, 너무 보고 싶었어요!', `FemaleText_loc4`='我真想你，爸爸！', `FemaleText_loc5`='我真想你，爸爸!', `FemaleText_loc7`='¡Te he echado tanto de menos, papá!' WHERE `ID`=7402;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나도 보고 싶었단다, 아가야. 이렇게 집으로 돌아왔잖니.', `MaleText_loc4`='我也想你，亲爱的。我终于回家了……', `MaleText_loc5`='我也想你，親愛的。我終於回家了...', `MaleText_loc7`='Te he echado tanto de menos, tesoro. Por fin estoy en casa...' WHERE `ID`=7403;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='초승달발톱의 영혼이 뭔가 원하는 것이라도 있는 듯 당신을 뚫어져라 응시합니다.', `MaleText_loc4`='月爪枭兽逝去的灵魂专注地盯着你，就像等待发生什么事情一样。', `MaleText_loc5`='月爪梟獸逝去的靈魂專注地盯著你，就像等待發生什麼事情一樣。', `MaleText_loc7`='El espíritu asesinado de Garraluna te mira atentamente, como si quisiera algo de ti.' WHERE `ID`=7404;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼이시여, 훌륭히 싸워주셨습니다. 이제 저에게 당신의 육체와 정신의 힘을 주소서.', `MaleText_loc4`='你战斗得很勇敢，精灵。我请你赐予我你身体和心灵的力量。', `MaleText_loc5`='你戰鬥得很勇敢，精靈。我請求你賜予我你身體和心靈的力量。', `MaleText_loc7`='Has luchado bien, espíritu. Te pido que me concedas la fuerza de tu cuerpo y de tu corazón.', `FemaleText_loc1`='영혼이시여, 훌륭히 싸워주셨습니다. 이제 저에게 당신의 육체와 정신의 힘을 주소서.', `FemaleText_loc4`='你战斗得很勇敢，精灵。我请你赐予我你身体和心灵的力量。', `FemaleText_loc5`='你戰鬥得很勇敢，精靈。我請求你賜予我你身體和心靈的力量。', `FemaleText_loc7`='Has luchado bien, espíritu. Te pido que me concedas la fuerza de tu cuerpo y de tu corazón.' WHERE `ID`=7405;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼이 당신의 눈을 뚫어져라 응시합니다. 손을 잡는 것이 느껴집니다. 당신의 온몸에 매우 따뜻한 온기가 퍼지면서, 거의 무릎까지 후들거릴 지경입니다.$B$B온기가 지나간 자리에 당신의 결의를 더욱 굳건하게 해줄 곰의 영혼이 존재하는 것이 어렴풋이 느껴집니다.', `MaleText_loc4`='灵魂专注地盯着你的眼睛，握紧你的双手。你感到一股热流抨击着身体，几乎无法站立。$B$B热流过后，你感觉身体中似乎充斥着熊的灵魂……让你更加坚定。', `MaleText_loc5`='靈魂專注地盯著你的眼睛，握緊你的雙手。你感到一股熱流抨擊著身體，幾乎無法站立。$B$B熱流過後，你感覺身體中似乎充斥著熊的靈魂...讓你更加堅定。', `MaleText_loc7`='El espíritu te mira atentamente a los ojos y aprieta tu mano. Sientes cómo el calor recorre tu cuerpo y casi te hace caer de rodillas.$B$BCuando pasa el calor, sientes en tu interior la ligera presencia de un espíritu osuno... dando fuerzas a tu determinación.' WHERE `ID`=7406;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스컬지가 패배했다! 우린 다로우골을 지켜냈다!', `MaleText_loc4`='亡灵天灾被打败了！达隆郡得救了！', `MaleText_loc5`='天譴軍團被打敗了!達隆郡得救了!', `MaleText_loc7`='¡La Plaga ha sido derrotada! ¡Villa Darrow está a salvo!', `FemaleText_loc1`='스컬지가 패배했다! 우린 다로우골을 지켜냈다!', `FemaleText_loc4`='亡灵天灾被打败了！达隆郡得救了！', `FemaleText_loc5`='天譴軍團被打敗了!達隆郡得救了!', `FemaleText_loc7`='¡La Plaga ha sido derrotada! ¡Villa Darrow está a salvo!' WHERE `ID`=7407;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 모두 끔찍한 비극을 경험했지만, 결코 절망하지는 맙시다.$B$B다만, 빚을 갚아줄 그날까지는 그 기억을 잊어서도 안 되오.', `MaleText_loc4`='我们都亲眼目睹了无数可怕的灾难，但是我们不能由此绝望。$B$B记住这些往事，总有一天，我们会进行报复的。', `MaleText_loc5`='我們都親眼目睹了無數可怕的災難，但是我們不能由此絕望。$B$B記住這些往事，總有一天，我們會進行報復的。', `MaleText_loc7`='Todos hemos sido testigos de terribles tragedias, pero no debemos permitir que nos lleven a la desesperación.$B$BEn lugar de ello, aferraos a esos recuerdos para que algún día podamos resarcirnos.' WHERE `ID`=7408;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 다른 유물 더미가 필요해요!', `MaleText_loc4`='我还需要一个遗物包裹!', `MaleText_loc5`='我還需要一個聖物包裹!', `MaleText_loc7`='¡Necesito otro Fardo de reliquias!', `FemaleText_loc1`='또 다른 유물 더미가 필요해요!', `FemaleText_loc4`='我还需要一个遗物包裹!', `FemaleText_loc5`='我還需要一個聖物包裹!', `FemaleText_loc7`='¡Necesito otro Fardo de reliquias!' WHERE `ID`=7409;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다음 목표를 찾으러 가요.', `FemaleText_loc4`='我们再找下一个。', `FemaleText_loc5`='我們再找下一個，$n。', `FemaleText_loc7`='Vamos a buscar el siguiente.' WHERE `ID`=7410;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기서 멈출 수는 없어요.', `FemaleText_loc4`='我们必须继续前进。', `FemaleText_loc5`='我們必須繼續前進。', `FemaleText_loc7`='Debemos continuar.' WHERE `ID`=7411;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제단이 빛나고 있어요! 우리가 해냈어요!', `FemaleText_loc4`='祭坛在发光！我们做到了！', `FemaleText_loc5`='祭壇在發光!我們做到了!', `FemaleText_loc7`='¡El altar está resplandeciendo! ¡Lo hemos conseguido!' WHERE `ID`=7412;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='위를 보라... 타라 도르밀 도라...', `FemaleText_loc4`='朝上看，Thara dormil dorah……', `FemaleText_loc5`='朝上看，(達納蘇斯語)薩拉·多米爾·多哈...', `FemaleText_loc7`='Mira ahí arriba; thara dormil dorah...' WHERE `ID`=7413;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='한 때 우리는 저 보석을 통해 엘룬 님과 직접 대화를 할 수가 있었느니라.', `FemaleText_loc4`='这宝石曾允许与月神本人进行直接沟通。', `FemaleText_loc5`='這寶石曾允許與伊露恩本人進行直接溝通。', `FemaleText_loc7`='Antaño esta gema permitía comunicarse directamente con la propia Elune.' WHERE `ID`=7414;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='엘룬께서는 보석을 통해서 무한한 지혜를 보내셨다.', `FemaleText_loc4`='月神通过宝石传达着她无尽的智慧……', `FemaleText_loc5`='伊露恩通過寶石傳達著她無盡的智慧...', `FemaleText_loc7`='A través de la gema, Elune canalizaba su sabiduría infinita...' WHERE `ID`=7415;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아누도리니 탈라... 루 샬로라 에누도릴...', `FemaleText_loc4`='Anu''dorini Talah。Ru shallora enudoril。', `FemaleText_loc5`='(達納蘇斯語)安奴''多利尼·塔拉哈。奴·夏羅拉·伊奴多利。', `FemaleText_loc7`='Anu''dorini Talah. Ru shallora enudoril.' WHERE `ID`=7416;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리는 엘룬 님을 섬기는 자로서, 보석을 수호해야 한다는 사실을 깨달았느니...', `FemaleText_loc4`='宝石需要得到保护，于是我们就向女神求助。', `FemaleText_loc5`='寶石需要得到保護，我們向女神本人求助。', `FemaleText_loc7`='Al comprender que la gema debía ser protegida, recurrimos a la propia diosa.' WHERE `ID`=7417;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그리고 얼마 후 어떤 짐승을 보게 되었다. 깃털은 분명 올빼미의 것이지만, 곰의 힘과 의지가 있었노라.', `FemaleText_loc4`='很快，我们眼前浮现出一种生物的幻象……它有猫头鹰的羽毛，同时也有熊的意志和力量……', `FemaleText_loc5`='很快，我們眼前浮現出一種生物的幻象...它有貓頭鷹的羽毛，同時也有熊的意志和力量...', `FemaleText_loc7`='Poco después comenzamos a tener visiones de una criatura... Una criatura con plumas de búho, pero con la voluntad y la fuerza del oso...' WHERE `ID`=7418;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='바로 그날, 우리는 올빼미야수를 얻게 되었노라. 엘룬께서는 사나운 올빼미야수를 수호자로 보내시어 모든 성소를 지키도록 하셨다.', `FemaleText_loc4`='就在那天我们得到了枭兽。凶猛的守卫，女神派枭兽保护她所有的神圣之地。', `FemaleText_loc5`='就在那天我們得到了梟獸。兇猛的守衛，女神派梟獸保護她所有的神聖之地。', `FemaleText_loc7`='Ese día se nos concedieron los lechúcicos, fieros guardianes. La diosa les encomendó proteger sus lugares salvajes sagrados.' WHERE `ID`=7419;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저자와 비슷한 이들이 천 명도 넘게 있다네. 만 명이 넘을지도 몰라. 한 명이 사라지면 다른 이가 올라서서 그 자리를 차지할 것이네.', `MaleText_loc4`='一千个像他一样的人存在着。一万个。如果一个倒下了，另一个会起来争夺权力的宝座。', `MaleText_loc5`='一千個像他一樣的人存在著。一萬個。如果一個倒下了，另一個會起來爭奪權力的寶座。', `MaleText_loc7`='Hay mil más como él. Diez mil. Si cayera uno, otros se levantarían para tomar la sede del poder.' WHERE `ID`=7420;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 한쪽 무릎을 꿇습니다.', `MaleText_loc4`='%s单膝跪地。', `MaleText_loc5`='%s單膝跪地。', `MaleText_loc7`='%s hinca una rodilla.' WHERE `ID`=7421;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하지만, 수년이 흐른 지금, 올빼미야수는 수호자의 역할을 잊고 점점 광포한 야생의 본능으로 돌아가고 있다. 자신도 혼란스러워 하는 것이지...', `FemaleText_loc4`='但是现在，枭兽已经变得更加凶猛，而且由于失去了女神的指引，它们很迷茫……', `FemaleText_loc5`='但是現在，梟獸已經變得更加兇猛，而且由於失去了女神的指引，它們很迷茫...', `FemaleText_loc7`='Pero ahora, muchos años después, los lechúcicos salvajes se han hecho más salvajes y sin la guía de la diosa, están confundidos...' WHERE `ID`=7422;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 내 아들에게 한 짓을 보게나.', `MaleText_loc4`='看看他们对我的孩子做了什么!', `MaleText_loc5`='看看他們對我的孩子做了什麼!', `MaleText_loc7`='Mira lo que hicieron a mi chico.' WHERE `ID`=7423;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그들은 아무런 목적도 없이 배회하고 있다. 그렇지만 그중 많은 올빼미야수가 한 때 그들이 지키기로 신께 맹세했던 성스러운 장소로 돌아온 것이다.', `FemaleText_loc4`='它们毫无目的地游荡……但是很多枭兽又回到了它们曾经发誓要保护的神圣之地。', `FemaleText_loc5`='毫無目的，他們在遊蕩...但是他們很多又回到了曾經發誓要保護的神聖之地。', `FemaleText_loc7`='Privados de ningún propósito, vagan por las tierras... Pero muchos encuentran el camino de vuelta a las zonas sagradas que un día juraron proteger.' WHERE `ID`=7424;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 축 늘어진 탤런 폴드링의 몸을 끌어안고 조용히 흐느낍니다.', `MaleText_loc4`='%s搂着泰兰·弗丁毫无生气的身体低声抽泣。', `MaleText_loc5`='%s擁著泰蘭·弗丁柔軟的身體輕輕地抽泣。', `MaleText_loc7`='%s sostiene el cuerpo inerte de Taelan Vadín y solloza.' WHERE `ID`=7425;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 죽음을 결코 헛되이 하지 않으마, 내 아들, 탤런. 세상을 오염시키는 악을 멸하기 위해 헌신할 준비가 된 새로운 기사단이 창설되고 있단다. 어떤 술책이나 웃음으로도 숨길 수 없는 악을 제거하기 위해서 말이야.', `MaleText_loc4`='你不会白死的，泰兰。今天产生了一种新秩序……一种致力于消灭正在折磨这个世界的邪恶势力的秩序。这种邪恶势力是不能被政治和幽默所掩盖的。', `MaleText_loc5`='你不會白死的，泰蘭。今天產生了一種新秩序...一種致力於消滅正在折磨這個世界的邪惡勢力的秩序。這種邪惡勢力是不能被政治和幽默所掩蓋的。', `MaleText_loc7`='Tu muerte no habrá sido en vano, Taelan. En este día ha nacido una nueva Orden... una Orden que se dedicará a extinguir la peste que infesta este mundo. Un mal que no puede ocultarse tras diplomacias y galanterías.' WHERE `ID`=7426;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='선천적으로 올빼미야수는 마법을 사용할 줄 안다. 바로 엘룬께서 주신 능력이지.', `FemaleText_loc4`='枭兽天生具有魔力；这种力量是由女神赐予他们的。', `FemaleText_loc5`='梟獸天生具有魔力;這種力量是由女神賜予他們的。', `FemaleText_loc7`='Los lechúcicos salvajes son mágicos intrínsecamente; un poder que les fue otorgado por la diosa.' WHERE `ID`=7427;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='만약 그대들이 이 세계의 어떤 장소에서 올빼미야수들을 발견한다면, 그것은 뭔가 중요한 걸 수호하고 있다는 뜻이다. 아주 오래전부터 맡아온 임무이지.', `FemaleText_loc4`='你要知道，无论身处何地，他们都会受他人委托，保护着某种重要的东西。', `FemaleText_loc5`='你要知道，無論身處何地，他們都會受他人委託，保護著某種重要的東西。', `FemaleText_loc7`='Tienes que saber que donde quiera que combatas con ellos, estarán protegiendo algo importante, como se les encargó hace tantísimo tiempo.' WHERE `ID`=7428;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 너무 오랫동안 의미없는 시간만 보내고 있었네. 멍한 상태로 무기력감에 빠져서 이렇게 할 수도 있었는데, 이렇게 했어야 하는데 후회하면서...', `MaleText_loc4`='我虚度了太多时光，在混沌……痛苦中度过，为或许发生过……或者应该发生而没有发生的事情感到悲伤。', `MaleText_loc5`='我虛度了太多時光，在混沌...痛苦中度過，為或許發生過...或者應該發生而沒有發生的事情感到悲傷。', `MaleText_loc7`='He estado demasiado tiempo sin hacer nada, atado a esta bruma... a este malestar, lamentando lo que podría haber sido... lo que debiera haber sido.' WHERE `ID`=7429;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이것만큼은 약속한다... 이것만큼은 맹세하지.', `MaleText_loc4`='我承诺……我发誓……', `MaleText_loc5`='我承諾...我發誓...', `MaleText_loc7`='Lo prometo... Lo juro...' WHERE `ID`=7430;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='부디 지금 내가 그대들에게 보여준 것을 잊지마라.', `FemaleText_loc4`='记住我们向你展示的……', `FemaleText_loc5`='記住我們向你展示的...', `FemaleText_loc7`='Por favor, recuerda lo que te he enseñado...' WHERE `ID`=7431;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='평안히 가라... 엘룬께서 그대의 갈 길을 인도할 것이니라!', `FemaleText_loc4`='再见。', `FemaleText_loc5`='再見。', `FemaleText_loc7`='Buen viaje.' WHERE `ID`=7432;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비극적이군. 저 늙은 폴드링이 아직 살아 있다니... 이보라고, 당신은 너무 오래 살았어. 뒤틀린 황천에 있는 아들을 따라가고 싶지 않으면 다시 동굴로 돌아가서 숨어서 지내라고!', `MaleText_loc4`='真悲哀。弗丁还活着……你来晚了，年老的隐士。回到你的洞穴吧，除非你想和在扭曲虚空的儿子一起。', `MaleText_loc5`='真悲哀。弗丁還活著...你來晚了，年老的隱士。回到你的洞穴吧，除非你想和在扭曲虛空的兒子一起。', `MaleText_loc7`='Trágico. El mayor de los Vadín sigue con vida... Llegas demasiado tarde, anciano. Regresa a tu cueva, ermitaño, si no quieres reunirte con tu hijo en El Vacío Abisal.' WHERE `ID`=7433;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='도와줘서 고마워요, $n. 그대가 아제로스에서 모험을 하시며, 엘룬의 가호로 무사하시길 빌어요.', `FemaleText_loc4`='谢谢你的帮助，$n。祝你探险顺利。', `FemaleText_loc5`='謝謝你的幫助，$n。祝你探險順利。', `FemaleText_loc7`='Gracias por tu ayuda, $n. Que tengas suerte en tus aventuras.' WHERE `ID`=7434;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기에서 조금 더 머무르시며, 방금 우리가 알아낸 사실을 생각해 보셨으면 해요. 그리고 에렐라스를 만나서, 이 소식을 전해주세요.', `FemaleText_loc4`='我想呆在这儿，思考一下所见的事情。找到艾瑞拉斯并告诉他我们学到的东西。', `FemaleText_loc5`='我想待在這兒，思考一下所見的事情。找到艾瑞拉斯並告訴他我們學到的東西。', `FemaleText_loc7`='Quiero quedarme aquí y meditar sobre lo que he visto. Por favor, ve a ver a Eralas y dile lo que hemos aprendido.' WHERE `ID`=7435;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇다면 덤벼봐!', `MaleText_loc4`='来吧，隐士！', `MaleText_loc5`='來吧，隱士!', `MaleText_loc7`='¡Adelante, ermitaño!' WHERE `ID`=7436;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거대한 곰이 당신을 조용하고 느긋하게 바라볼 뿐 아무 말도 하지 않습니다.', `MaleText_loc4`='熊平静地注视着你，但是没说一句话。', `MaleText_loc5`='熊平靜地注視著你，但是沒說一句話。', `MaleText_loc7`='El oso te mira con calma y paciencia, pero no dice nada.' WHERE `ID`=7437;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거대한 곰이 당신을 침착하고 부드러운 눈길로 바라봅니다. 곰의 것이라고 생각되는 말소리가 들리지만... 이상하게도 곰의 입은 전혀 움직이지 않습니다.$B$B"반갑다, 어린 친구. 내게 뭔가 청이 있어서 온 것인가? 그대가 원하는 것을 얻을 수 있을 것이다."', `MaleText_loc4`='熊的灵魂平和的凝视着你。你听到了一个声音在对你讲话，好象是从熊那里传来，但是没有迹象表明这个动物在说话。$B$B“你好，我年轻的朋友。如果你是来找我寻求指引的，那么或许我能帮你找到你想要的东西。”', `MaleText_loc5`='熊的靈魂平和的凝視著你。你聽到了一個聲音在對你講話，好像是從熊那裡傳來，但是沒有跡象表明這個動物在說話。$B$B「你好，我年輕的朋友。如果你是來找我尋求指引的，那麼或許我能幫你找到你想要的東西。」', `MaleText_loc7`='El espíritu del oso mira hacia ti con una mirada tranquila y pacífica. Oyes una voz que se dirige a ti y que parece venir del oso, pero la criatura no hace ningún gesto.$B$B"Saludos, joven $gamigo:amiga;. Si has venido hasta aquí buscando mi guía, quizás pueda ayudarte a encontrar lo que buscas."' WHERE `ID`=7438;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위대한 영혼이시여, 당신의 존재는 무엇을 상징합니까?', `MaleText_loc4`='你代表什么，灵魂？', `MaleText_loc5`='你代表什麼，靈魂?', `MaleText_loc7`='¿Qué representas, espíritu?', `FemaleText_loc1`='위대한 영혼이시여, 당신의 존재는 무엇을 상징합니까?', `FemaleText_loc4`='你代表什么，灵魂？', `FemaleText_loc5`='你代表什麼，靈魂?', `FemaleText_loc7`='¿Qué representas, espíritu?' WHERE `ID`=7439;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 그대와 같은 젊은 드루이드를 강화시켜 주기 위해서 존재한다. 나는 곧 육체와 정신의 힘이다. 그대는 이미 훈련을 통해서 이 사실을 느끼고 있을 것이다. 곰의 형태로 변신하면 이 강한 힘을 이용할 수 있다.$B$B젊은 친구, 모든 일에 균형을 유지하고 사물을 명확하고 진실한 눈으로 보아야 한다. 그대가 날 필요로 할 때면 언제나 내가 그 자리에 있을 것이다.', `MaleText_loc4`='我代表着使你成为一名年轻的德鲁伊的力量，是躯体和心灵的力量。你已经在训练中知晓了这一点，当你变身为熊的时候便可利用这力量了。$B$B年轻人，继续保持平衡，眼光清晰而有条理。当你需要我的时候……我会在那儿等你的。', `MaleText_loc5`='我代表著使你成為一名年輕的德魯伊的力量，是軀體和心靈的力量。你已經在訓練中知曉了這一點，當你變身為熊的時候便可利用這力量了。$B$B年輕人，繼續保持平衡，眼光清晰而有條理。當你需要我的時候...我會在那兒等你的。', `MaleText_loc7`='Represento la fuerza que te apoya como $gun:una; joven druida. Soy la fuerza del cuerpo y la fuerza del corazón. Ya has podido saber esto a través de tu instrucción y lo aprovechas cuando adoptas el aspecto del oso.$B$BSigue guardando el equilibrio de todas las cosas, joven, y mantén tu mirada limpia y verdadera. Si me necesitas... allí estaré.' WHERE `ID`=7440;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 그대와 같은 젊은 드루이드를 강화시켜 주기 위해서 존재한다. 그대가 내게 힘을 얻으러 왔으니 가르침을 내려 주겠다. 그대가 내 말을 귀 기울여 듣고 이해할 준비가 되었다면 나... 거대한 곰의 혼에 대한 모든 것을 배울 수 있다.$B$B그리고... 그대의 영혼에 의지한다는 것이 무슨 의미인지 알려면, 정신의 힘뿐만 아니라 육체적 힘의 중요성도 이해해야 한다.', `MaleText_loc4`='我代表着使你成为一名年轻的德鲁伊的力量。年轻人，你得向我学习这力量，我也乐于传授给你。要是你愿意听从并理解的话，我将教你如何使用熊的灵魂。$B$B为了明白利用我的灵魂的含义，你需要了解躯体和心灵的力量的重要性。', `MaleText_loc5`='我代表著使你成為一名年輕的德魯伊的力量。年輕人，你得向我學習這力量，我也樂於傳授給你。要是你願意聽從並理解的話，我將教你如何使用熊的靈魂。$B$B為了明白利用我的靈魂的含義，你需要瞭解軀體和心靈的力量的重要性。', `MaleText_loc7`='Represento la fuerza que te apoya como $gun:una; joven druida. Has venido hasta aquí para aprender esa fuerza, joven, y te la enseñaré. Te enseñaré qué es el espíritu del oso, siempre que lo escuches y comprendas.$B$BPara saber lo que significa recurrir a mi espíritu debes comprender la importancia de la fuerza del cuerpo y de la fuerza del corazón.' WHERE `ID`=7441;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='육체적 힘의 중요성에 대해 알고 싶습니다.', `MaleText_loc4`='我想了解躯体力量的重要性。', `MaleText_loc5`='我想瞭解軀體力量的重要性。', `MaleText_loc7`='Quiero comprender la importancia de la fuerza del cuerpo.', `FemaleText_loc1`='육체적 힘의 중요성에 대해 알고 싶습니다.', `FemaleText_loc4`='我想了解躯体力量的重要性。', `FemaleText_loc5`='我想瞭解軀體力量的重要性。', `FemaleText_loc7`='Quiero comprender la importancia de la fuerza del cuerpo.' WHERE `ID`=7442;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='육체의 힘이란 민첩하고도 강한 동작을 말한다. 그대는 육체적으로나 정신적으로 항상 최적의 상태를 유지해야 한다. 전투에서 가장 위협적인 요소는 바로 힘이다. 곰은 그 거대함으로 힘을 확연히 드러내지만 그 안에는 유연한 민첩성과 날카로운 정신이 감춰져 있다. 이 점을 잘 이용하면 상대방을 완전히 제압할 할 수 있지.$B$B할퀴기의 도를 완전히 익히려면 곰의 육체적 힘을 믿어야 한다.', `MaleText_loc4`='身体的力量能使动作充满力度，行动迅速。你必须在身体上和精神上一直保持就绪状态。熊的体型造就了它的力量，使它成为危险的对手。但是，熊的体型也限制了其身体的敏捷性和头脑的灵活性。你可以好好利用这点。$B$B你必须依赖熊的力量掌握利爪的使用方法。', `MaleText_loc5`='身體的力量能使動作充滿力度，行動迅速。你必須在身體上和精神上一直保持就緒狀態。熊的體型造就了它的力量，使它成為危險的對手。但是，熊的體型也限制了其身體的敏捷性和頭腦的靈活性。你可以好好利用這點。$B$B你必須依賴熊的力量掌握利爪的使用方法。', `MaleText_loc7`='La fuerza del cuerpo es el poder y la presteza de acción. Debes mantenerte siempre en forma, mental y físicamente. La envergadura del oso destaca su fuerza, es un enemigo feroz en combate. Pero a su vez, esa envergadura, disfraza su agilidad y agudeza mental. Son sorpresas de las que podrás beneficiarte.$B$BDebes confiar en la fuerza del cuerpo del oso para llegar a dominar el camino de la zarpa.' WHERE `ID`=7443;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정신적 힘의 중요성에 대해 알고 싶습니다.', `MaleText_loc4`='我想了解心灵力量的重要性。', `MaleText_loc5`='我想瞭解心靈力量的重要性。', `MaleText_loc7`='Quiero comprender la importancia de la fuerza del corazón.', `FemaleText_loc1`='정신적 힘의 중요성에 대해 알고 싶습니다.', `FemaleText_loc4`='我想了解心灵力量的重要性。', `FemaleText_loc5`='我想瞭解心靈力量的重要性。', `FemaleText_loc7`='Quiero comprender la importancia de la fuerza del corazón.' WHERE `ID`=7444;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정신의 힘은 순수하고 솔직한 마음에서 우러나오는 행동을 할 수 있는 의지를 준다. 균형을 유지하는 것은 자기만족을 위함도 아니고 사소한 일도 아니다.$B$B그대 자신이 믿음에 대한 의지를 보여야 하며 그 믿음을 위해 싸울 수 있어야 한다. 어미 곰이 새끼를 지킬 때나, 늙은 곰이 자기 보금자리를 지킬 때는, 굳은 신념을 보여 준다. 이것이 바로 할퀴기의 도를 완전히 익히기 위해 그대가 깨달아야 하는 의지이자 정신의 힘이다.', `MaleText_loc4`='心灵的力量将给你采取行动的决心……基于明确的、直接的目的的行动。保持平衡并不意味着自命不凡或是平庸陈腐。$B$B你必须表现出对信仰的决心，你必须愿意为此奋斗。母熊对幼仔有极强的保护意识，年老的熊也这样保护着它的洞穴。这就是决心，心灵的力量，如果你想要掌握利爪的使用方法，你就必须知道这一点。', `MaleText_loc5`='心靈的力量將給你採取行動的決心...基於明確的、直接的目的行動。保持平衡並不意味著自命不凡或是平庸陳腐。$B$B你必須表現出對信仰的決心，你必須願意為此奮鬥。母熊對幼仔有極強的保護意識，年老的熊也這樣保護著它的洞穴。這就是決心，心靈的力量，如果你想要掌握利爪的使用方法，你就必須知道這一點。', `MaleText_loc7`='La fuerza del corazón es lo que te da la determinación para emprender la acción... la acción enraizada en propósitos puros y nobles. Mantener el equilibrio no es ni banal ni autocomplaciente.$B$BDebes mostrar determinación en lo que crees, y debes desear luchar por ello. La madre oso muestra una convicción infinita en la defensa y protección de su osezno, al igual que un oso adulto protegiendo su guarida. Es esta determinación, esta fuerza del corazón, la que debes llegar a conocer si deseas dominar el camino de la zarpa.' WHERE `ID`=7445;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거대한 곰의 혼이시여, 말씀 잘 들었습니다. 제가 할퀴기의 도를 완전히 익힐 수 있도록 부디 축복을 내려 주소서.', `MaleText_loc4`='我听到你的话了，巨熊之灵，而且我理解。我现在寻求你的赐福以深入地学习力利爪的技能。', `MaleText_loc5`='我聽到你的話了，巨熊之靈，而且我理解。我現在尋求你的賜福以深入地學習利爪的技能。', `MaleText_loc7`='He oído tus palabras, Espíritu del gran oso, y las comprendo. Ahora necesito tu bendición para terminar de aprender el camino de la zarpa.', `FemaleText_loc1`='거대한 곰의 혼이시여, 말씀 잘 들었습니다. 제가 할퀴기의 도를 완전히 익힐 수 있도록 부디 축복을 내려 주소서.', `FemaleText_loc4`='我听到你的话了，巨熊之灵，而且我理解。我现在寻求你的赐福以深入地学习爪的技能。', `FemaleText_loc5`='我聽到你的話了，巨熊之靈，而且我理解。我現在尋求你的賜福以深入地學習利爪的技能。', `FemaleText_loc7`='He oído tus palabras, Espíritu del gran oso, y las comprendo. Ahora necesito tu bendición para terminar de aprender el camino de la zarpa.' WHERE `ID`=7446;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러려면 우선 그대가 준비됐는지 확인해야 한다. 가장 현명하고 성숙한 드루이드라고 해도 최종 시험에 대해 완벽하게 준비가 됐다고는 할 수 없는 법이지.$B$B내 말을 새겨들었으면, 쉬지 말고 전진하라. 내가 가르쳐 준 교훈을 유념해라. 그대의 힘을 시험할 때가 곧 올 것이다. 곰과 같은 육체와 정신의 힘으로 적과 맞서라. 실전을 통해 배워라. 나의 축복이 그대와 함께할 것이다.', `MaleText_loc4`='年轻人，还要看你是否准备就绪。当最终考验来临时，即使最聪明最年老的德鲁伊也无法真正地做好准备。$B$B你已经听到我的话了，你必须继续前进。记得我的嘱咐。某个时候你的能力将经受考验。你必须像熊那样勇敢面对自己的敌人——用身体和心灵的力量。年轻人，你得从战争中学习成长。去吧……带上我的祝福。', `MaleText_loc5`='年輕人，還要看你是否準備就緒。當最終考驗來臨時，即使最聰明最年老的德魯伊也無法真正地做好準備。$B$B你已經聽到我的話了，你必須繼續前進。記得我的囑咐。某個時候你的能力將經受考驗。你必須像熊那樣勇敢面對自己的敵人─用身體和心靈的力量。年輕人，你得從戰爭中學習成長。去吧...帶上我的祝福。', `MaleText_loc7`='Todavía está por ver si estás $gpreparado:preparada;, joven. Ni siquiera el más sabio y anciano de los druidas llega a estar nunca realmente listo cuando se acerca la hora de someterse a la última prueba.$B$BYa has oído mis palabras, ahora debes continuar. Presta atención a lo que te he enseñado. Llegará la hora en la que habrás mostrado tu fuerza. Debes enfrentarte a tu enemigo como lo haría el oso, con fuerza de cuerpo y con fuerza de corazón. Aprende de la lucha, joven. Y ahora vete... con mi bendición.' WHERE `ID`=7447;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까? $C|1이여;여;. 밤의 안식처에 잘 오셨습니다. 달숲 전역에서 그대를 환영하는 바입니다. 세나리온 의회에서는 자연을 사랑하는 모든 이들을 환영합니다.$B$B여기 머무시는 동안, 매사에 균형을 잃지 않도록 주의하십시오. 특히 소란을 일으키는 행위는 절대 용납하지 않습니다. 우리는 모든 적대적인 행위에 대해 이유를 불문하고 진압하도록 훈련받았습니다.', `MaleText_loc4`='你好，$c。欢迎你来到永夜港，还有整个月光林地。塞纳里奥议会欢迎所有尊敬大自然的权威和支配力的生灵。$B$B当你在这里的时候，请一定要保持所有事物的平衡。这里不喜欢受到打扰，而我们的看守所受的训练就是无条件地停止所有的敌对行为。', `MaleText_loc5`='你好，$c。歡迎你來到永夜港，還有整個月光林地。塞納里奧議會歡迎所有尊敬大自然的權威和支配力的生靈。$B$B當你在這裡的時候，請一定要保持所有事物的平衡。這裡不喜歡受到打擾，而我們的看守所受的訓練就是無條件地停止所有的敵對行為。', `MaleText_loc7`='Saludos, $c. Sé $gbienvenido:bienvenida; al Amparo de la Noche y a todo Claro de la Luna. El Círculo Cenarion da la bienvenida a todos los que respeten la autoridad y el mando de la naturaleza.$B$BMientras estés aquí, por favor, cuídate de guardar el equilibrio de todas las cosas. Las alteraciones no son bien recibidas y nuestros celadores están instruidos para poner fin a todo tipo de hostilidad sin hacer ninguna pregunta.' WHERE `ID`=7448;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='환영을 원하는 건가?$B$B임무 수행 도중에 환영의 효력이 사라지면 내게 돌아오게. 그러면 다시 환영 마법을 걸어주지.$B$B실패해도 절대로 포기하지 말게! 내게 돌아오면 일을 마칠 때까지 돕도록 하겠네.', `FemaleText_loc4`='你需要幻象吗？$B$B要是在执行任务的过程中幻象失效，回到我这儿来，我将重新对你进行伪装。$B$B如果你尽力而为还是失败了，别放弃！回到我这儿来。我将助你完成目标。', `FemaleText_loc5`='你需要幻影嗎?$B$B要是在執行任務的過程中幻影失效，回到我這兒來，我將重新對你進行偽裝。$B$B如果你盡力而為還是失敗了，別放棄!回到我這兒來。我將助你完成目標。', `FemaleText_loc7`='¿Necesitas una ilusión?$B$BSi tu ilusión vacilara en medio de tu misión, vuelve aquí y volveré a aplicar la apariencia.$B$BSi tus esfuerzos fallas, ¡no abandones! Vuelve aquí y te ayudaré hasta que completes tus objetivos.' WHERE `ID`=7449;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$C|1이여;여;, 매사에서 균형을 유지하도록 노력하게. 진정한 조화는 바로 거기에 있는 법이니까.', `MaleText_loc4`='努力保持所有事情的平衡性，$c。真正的和谐便在于此。', `MaleText_loc5`='努力保持所有事情的平衡性，$c。真正的和諧便在於此。', `MaleText_loc7`='Procura mantener el equilibrio de todas las cosas, $c. En él descansa la verdadera armonía.', `FemaleText_loc1`='$C|1이여;여;, 매사에서 균형을 유지하도록 노력하세요. 진정한 조화는 바로 거기에 있는 법이니까요.', `FemaleText_loc4`='努力保持所有事情的平衡性，$c。真正的和谐便在于此。', `FemaleText_loc5`='努力保持所有事情的平衡性，$c。真正的和諧便在於此。', `FemaleText_loc7`='Procura mantener el equilibrio de todas las cosas, $c. En él descansa la verdadera armonía.' WHERE `ID`=7450;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='환영하네. 훈련을 하러 온 거라면 기꺼이 가르침을 주지.$B$B다시금 자신의 자리를 확인하는 것도 나쁘지 않겠지. 난 그걸 위대한 균형이라고 부르고 싶다네. 우리는 균형의 수호자로서 청명한 정신력과 강한 의지를 지키기 위해 꾸준히 노력해야 해. 바로 뼈를 깎는 듯한 훈련을 통해서 말일세.', `MaleText_loc4`='欢迎你，我的$g兄弟:姐妹;。如果你想接受训练，我会很乐意教你的。$B$B重申自己在这伟大的平衡中的地位总是无伤大雅的。作为这种平衡的守护者，我们必须努力保持清醒的头脑和坚定的信念。训练能使我们做到这一点。', `MaleText_loc5`='歡迎你，我的$g兄弟:姐妹;。如果你想接受訓練，我會很樂意教你的。$B$B重申自己在這偉大的平衡中的地位總是無傷大雅的。作為這種平衡的守護者，我們必須努力保持清醒的頭腦和堅定的信念。訓練能使我們做到這一點。', `MaleText_loc7`='$GBienvenido hermano:Bienvenida hermana;. Si has venido para instruirte, será un placer enseñarte.$B$BNunca viene mal reafirmar el lugar propio en lo que me gusta denominar El Gran Equilibrio. Como guardianes de ese equilibrio debemos procurar mantener siempre nuestras mentes limpias y nuestros corazones fuertes. La instrucción nos ayuda a realizar este fin.', `FemaleText_loc1`='환영합니다. 훈련을 하러 오신 거라면 기꺼이 가르침을 드리지요.$B$B다시금 자신의 자리를 확인하는 것도 나쁘지 않겠지요. 전 그걸 위대한 균형이라고 부르고 싶습니다. 우리는 균형의 수호자로서 청명한 정신력과 강한 의지를 지키기 위해 꾸준히 노력해야 합니다. 바로 뼈를 깎는 듯한 훈련을 통해서 말이지요.', `FemaleText_loc4`='欢迎你，我的$g兄弟:姐妹;。如果你想接受训练，我会很乐意教你的。$B$B重申自己在这伟大的平衡中的地位总是无伤大雅的。作为这种平衡的守护者，我们必须努力保持清醒的头脑和坚定的信念。训练能使我们做到这一点。', `FemaleText_loc5`='歡迎你，我的$g兄弟:姐妹;。如果你想接受訓練，我會很樂意教你的。$B$B重申自己在這偉大的平衡中的地位總是無傷大雅的。作為這種平衡的守護者，我們必須努力保持清醒的頭腦和堅定的信念。訓練能使我們做到這一點。', `FemaleText_loc7`='$GBienvenido hermano:Bienvenida hermana;. Si has venido para instruirte, será un placer enseñarte.$B$BNunca viene mal reafirmar el lugar propio en lo que me gusta denominar El Gran Equilibrio. Como guardianes de ese equilibrio debemos procurar mantener siempre nuestras mentes limpias y nuestros corazones fuertes. La instrucción nos ayuda a realizar este fin.' WHERE `ID`=7451;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드루이드 훈련을 받고 싶습니다.', `MaleText_loc4`='我想接受德鲁伊技能方面的训练。', `MaleText_loc5`='我想接受成為德魯伊的訓練。', `MaleText_loc7`='Necesito instruirme como druida.', `FemaleText_loc1`='드루이드 훈련을 받고 싶습니다.', `FemaleText_loc4`='我想接受德鲁伊技能方面的训练。', `FemaleText_loc5`='我想接受成為德魯伊的訓練。', `FemaleText_loc7`='Necesito instruirme como druida.' WHERE `ID`=7452;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투는 끝났고 이제 다로우골 주민들은 안전합니다.', `MaleText_loc4`='战争结束了，达隆郡的人民得救了。', `MaleText_loc5`='戰爭結束了，達隆郡的人民得救了。', `MaleText_loc7`='La batalla ha terminado, y la población de Villa Darrow está a salvo.' WHERE `ID`=7453;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투가 끝났고 이제 다로우골 주민들은 안전합니다.$B$B$n, 이제 살았습니다. 모두 당신 덕분이에요. 당신은 진정한 다로우골의 영웅입니다.', `MaleText_loc4`='战争结束了，达隆郡的人民得救了。$B$B他们得救了，$n，这都归功于你。你是达隆郡的英雄。', `MaleText_loc5`='戰爭結束了，達隆郡的人民得救了。$B$B他們得救了，$n，這都歸功於你。你是達隆郡的英雄。', `MaleText_loc7`='La batalla ha terminado, y la población de Villa Darrow está a salvo.$B$BEstán a salvo, $n, gracias a ti. Eres un auténtico héroe de Villa Darrow.' WHERE `ID`=7454;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한때 사악한 악의 힘에 의해 판단력이 흐려졌지만, 이제 당신이 저를 사악한 망상으로부터 자유롭게 해주었어요. 절 구하셨군요.$B$B그리고, 부디... 제 잘못을 용서해주세요.', `MaleText_loc4`='我的眼睛被黑暗所蒙蔽，但是你把我从邪恶的幻想中拯救出来。你救了我，$n。$B$B现在我求你……原谅我。', `MaleText_loc5`='我的眼睛被黑暗所蒙蔽，但是你把我從邪惡的幻想中拯救出來。你救了我，$n。$B$B現在我求你...原諒我。', `MaleText_loc7`='La oscuridad había caído sobre mis ojos, pero me has arrancado de mi impura ensoñación. Me has salvado, $n.$B$BY ahora, te lo suplico... perdóname.' WHERE `ID`=7455;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오십시오. 훈련하러 오신 것이라면 제가 기꺼이 가르쳐 드리겠습니다.$B$B말퓨리온 님이 우릴 지켜보고 계시는 이상, 우리는 언제까지나 균형을 수호해야 합니다. 절대 잊지 마십시오.', `MaleText_loc4`='欢迎你，我的$g兄弟:姐妹;。如果你想接受训练，我会很乐意教你的。$B$B只要玛法里奥还在沉睡中，我们便永远是平衡的守卫者。别忘了这一点。', `MaleText_loc5`='歡迎你，我的$g兄弟:姐妹;。如果你想接受訓練，我會很樂意教你的。$B$B在瑪法里恩的守護下，我們永遠是平衡的守衛者。別忘了這一點。', `MaleText_loc7`='Te doy la bienvenida, $ghermano:hermana;. Si has venido en busca de instrucción, estaré encantado de ayudarte.$B$BSomos los protectores del equilibrio, ahora y siempre, y Malfurion vela por nosotros. Nunca lo olvides.', `FemaleText_loc1`='어서 오십시오. 훈련하러 오신 것이라면 제가 기꺼이 가르쳐 드리겠습니다.$B$B말퓨리온 님이 우릴 지켜보고 계시는 이상, 우리는 언제까지나 균형을 수호해야 합니다. 절대 잊지 마십시오.', `FemaleText_loc4`='欢迎你，我的$g兄弟:姐妹;。如果你想接受训练，我会很乐意教你的。$B$B只要玛法里奥还在沉睡中，我们便永远是平衡的守卫者。别忘了这一点。', `FemaleText_loc5`='歡迎你，我的$g兄弟:姐妹;。如果你想接受訓練，我會很樂意教你的。$B$B在瑪法里恩的守護下，我們永遠是平衡的守衛者。別忘了這一點。', `FemaleText_loc7`='Te doy la bienvenida, $ghermano:hermana;. Si has venido en busca de instrucción, estaré encantado de ayudarte.$B$BSomos los protectores del equilibrio, ahora y siempre, y Malfurion vela por nosotros. Nunca lo olvides.' WHERE `ID`=7456;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c님, 우리의 지도자이신 말퓨리온 님께서는 에메랄드의 꿈속에서 돌아오셨습니다. 그분은 우리의 길을 비추는 빛이십니다. 우리는 그 빛을 지키도록 온 힘을 다해야 합니다.', `MaleText_loc4`='我们的导师玛法里奥已经从沉睡中回来了，$c。他是我们的指路明灯，我们必须竭尽全力保护他。', `MaleText_loc5`='我們的主人瑪法里恩已從夢境中歸來，$c。他是我們的指路明燈，我們必須竭盡全力保護他。', `MaleText_loc7`='Nuestro maestro Malfurion ha regresado del Sueño, $c. Él es la luz de un faro que ilumina nuestro camino, y debemos hacer todo lo que sea posible para conservar esa luz.', `FemaleText_loc1`='$c님, 우리의 지도자이신 말퓨리온 님께서는 에메랄드의 꿈속에서 돌아오셨습니다. 그분은 우리의 길을 비추는 빛이십니다. 우리는 그 빛을 지키도록 온 힘을 다해야 합니다.', `FemaleText_loc4`='我们的导师玛法里奥已经从沉睡中回来了，$c。他是我们的指路明灯，我们必须竭尽全力保护他。', `FemaleText_loc5`='我們的主人瑪法里恩已從夢境中歸來，$c。他是我們的指路明燈，我們必須竭盡全力保護他。', `FemaleText_loc7`='Nuestro maestro Malfurion ha regresado del Sueño, $c. Él es la luz de un faro que ilumina nuestro camino, y debemos hacer todo lo que sea posible para conservar esa luz.' WHERE `ID`=7457;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$C|1이여;여;, 세나리우스의 축복이 그대와 함께하기를.', `MaleText_loc4`='塞纳留斯保佑你，$c。', `MaleText_loc5`='塞納留斯保佑你，$c。', `MaleText_loc7`='Que Cenarius te bendiga, $c.', `FemaleText_loc1`='$C|1이여;여;, 세나리우스의 축복이 그대와 함께하기를.', `FemaleText_loc4`='塞纳留斯保佑你，$c。', `FemaleText_loc5`='塞納留斯保佑你，$c。', `FemaleText_loc7`='Que Cenarius te bendiga, $c.' WHERE `ID`=7458;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오십시오. 훈련을 하러 온 것이라면 제가 기꺼이 가르쳐 드리겠습니다.', `MaleText_loc4`='欢迎你，我的$g兄弟:姐妹;。如果你想接受训练，我会很乐意教你的。', `MaleText_loc5`='歡迎你，我的$g兄弟:姐妹;。如果你想接受訓練，我會很樂意教你的。', `MaleText_loc7`='$GBienvenido:Bienvenida;, $ghermano:hermana;. ¡Si has venido aquí para instruirte, estaré encantado de hacerlo!', `FemaleText_loc1`='어서 오십시오. 훈련을 하러 온 것이라면 제가 기꺼이 가르쳐 드리겠습니다.', `FemaleText_loc4`='欢迎你，我的$g兄弟:姐妹;。如果你想接受训练，我会很乐意教你的。', `FemaleText_loc5`='歡迎你，我的$g兄弟:姐妹;。如果你想接受訓練，我會很樂意教你的。', `FemaleText_loc7`='$GBienvenido:Bienvenida;, $ghermano:hermana;. Si has venido aquí para instruirte, estaré encantado de hacerlo.$B$BHay rumores de disputas con el Círculo Cenarion, pero no deberías dar crédito a los que hablan así. ¡Nuestro archidruida, Fandral Corzocelada, nos guía a nosotros y a todo Teldrassil hacia la gloria!' WHERE `ID`=7459;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 마을을 보호하는 돌벽과도 같이 차가운 벽 안에서도 평온을 찾을 수는 있답니다. 마음의 균형을 찾아 자신의 내면을 살펴본다면 사실 어디에서나 평온을 찾을 수 있습니다.', `MaleText_loc4`='即使在冰冷的石头墙内，就像庇护这座城镇的墙一样，人们仍旧可以找到宁静与和平。事实上，你可以在你所在的任何地方找到他们……只需在你体内寻找这种平衡。', `MaleText_loc5`='即使在冰冷的石頭牆內，就像庇護這座城市的牆一樣，人們仍舊可以找到寧靜與和平。事實上，不論你人在哪裡都找得到它們...只需往你心裡探尋此等平衡。', `MaleText_loc7`='Incluso entre fríos muros de piedra como los que rodean esta ciudad, podría encontrarse paz y tranquilidad. De hecho, puedes encontrarlas donde quiera que estés... solo debes buscar en tu interior para encontrar ese equilibrio.', `FemaleText_loc1`='이 마을을 보호하는 돌벽과도 같이 차가운 벽 안에서도 평온을 찾을 수는 있답니다. 마음의 균형을 찾아 자신의 내면을 살펴본다면 사실 어디에서나 평온을 찾을 수 있습니다.', `FemaleText_loc4`='即使在冰冷的石头墙内，就像庇护这座城镇的墙一样，人们仍旧可以找到宁静与和平。事实上，你可以在你所在的任何地方找到他们……只需在你体内寻找这种平衡。', `FemaleText_loc5`='即使在冰冷的石頭牆內，就像庇護這座城市的牆一樣，人們仍舊可以找到寧靜與和平。事實上，不論你人在哪裡都找得到它們...只需往你心裡探尋此等平衡。', `FemaleText_loc7`='Incluso entre fríos muros de piedra como los que rodean esta ciudad, podría encontrarse paz y tranquilidad. De hecho, puedes encontrarlas donde quiera que estés... solo debes buscar en tu interior para encontrar ese equilibrio.' WHERE `ID`=7460;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오십시오. 훈련을 받으러 오신 것이라면 제가 기꺼이 가르쳐 드리겠습니다.$B$B머지않아 에메랄드의 꿈이 그대를 부를 것입니다. 그러면 그대는 여러 해 동안 잠을 자며 가장 순수한 형태의 세계를 거닐게 될 것입니다. 바로 그때, 거기서 그대는 최종 훈련을 받게 될 것입니다.', `MaleText_loc4`='欢迎你，我的$g兄弟:姐妹;。如果你想接受训练，我会很乐意教你的。$B$B来自翡翠梦境的召唤将很快占据你的心灵。你将冬眠数年，在最纯净的环境中生活。你将在那儿接受最终的训练。', `MaleText_loc5`='歡迎你，我的$g兄弟:姐妹;。如果你想接受訓練，我會很樂意教你的。$B$B來自翡翠夢境的召喚將很快佔據你的心靈。你將冬眠數年，在最純淨的環境中生活。你將在那兒接受最終的訓練。', `MaleText_loc7`='Te doy la bienvenida, $ghermano:hermana;. Si estás aquí para recibir instrucción, estaré encantado de ayudarte.$B$BPronto llegará el momento en que recibirás la llamada del Sueño Esmeralda. Hibernarás durante muchos años y caminarás entre las formas más puras. Ahí y entonces tendrá lugar tu instrucción definitiva.', `FemaleText_loc1`='어서 오십시오. 훈련을 받으러 오신 것이라면 제가 기꺼이 가르쳐 드리겠습니다.$B$B머지않아 에메랄드의 꿈이 그대를 부를 것입니다. 그러면 그대는 여러 해 동안 잠을 자며 가장 순수한 형태의 세계를 거닐게 될 것입니다. 바로 그때, 거기서 그대는 최종 훈련을 받게 될 것입니다.', `FemaleText_loc4`='欢迎你，我的$g兄弟:姐妹;。如果你想接受训练，我会很乐意教你的。$B$B来自翡翠梦境的召唤将很快占据你的心灵。你将冬眠数年，在最纯净的环境中生活。你将在那儿接受最终的训练。', `FemaleText_loc5`='歡迎你，我的$g兄弟:姐妹;。如果你想接受訓練，我會很樂意教你的。$B$B來自翡翠夢境的召喚將很快佔據你的心靈。你將冬眠數年，在最純淨的環境中生活。你將在那兒接受最終的訓練。', `FemaleText_loc7`='Te doy la bienvenida, $ghermano:hermana;. Si estás aquí para recibir instrucción, estaré encantado de ayudarte.$B$BPronto llegará el momento en que recibirás la llamada del Sueño Esmeralda. Hibernarás durante muchos años y caminarás entre las formas más puras. En ese lugar y momento tendrá lugar tu instrucción definitiva.' WHERE `ID`=7461;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='운명은 피할 수 없는 것. 네 운명에 따라 어서 무릎을 꿇어라. 여왕님께서 너의 영혼을 인도하실 것이다.', `MaleText_loc4`='你只是在拖延时间，结果是不可避免的。投降吧。她会释放你误入歧途的灵魂的。', `MaleText_loc5`='你只是在拖延時間，結果是不可避免的，$r。投降吧。她會釋放你誤入歧途的靈魂的。', `MaleText_loc7`='Lo único que haces es aplazar lo inevitable. Sucumbe. Ella liberará tu confundida alma.' WHERE `ID`=7462;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$C|1이여;여;, 우리는 세나리우스의 가르침대로 균형을 지키기 위해 노력하고 있습니다. 그분은 우리의 길을 비추는 빛이시지요. 우리는 그 빛을 지키기 위해 최선을 다해야 합니다.', `MaleText_loc4`='我们的工作就是保持平衡，如同塞纳留斯所教给我们的一样，$c。他就是指引我们前进的明灯，而我们必须竭尽所能保护它的光芒。', `MaleText_loc5`='我們的工作就是保持萬物的平衡，如同塞納留斯所教給我們的那樣，$c。他就是指引我們前進的明燈，而我們必須竭盡所能保護那道光芒。', `MaleText_loc7`='Trabajamos para preservar el equilibrio siguiendo las enseñanzas de Cenarius, $c. Él es la luz de un faro que ilumina nuestro camino, y debemos hacer todo lo que sea posible para conservar esa luz.', `FemaleText_loc1`='$C|1이여;여;, 우리는 세나리우스의 가르침대로 균형을 지키기 위해 노력하고 있습니다. 그분은 우리의 길을 비추는 빛이시지요. 우리는 그 빛을 지키기 위해 최선을 다해야 합니다.', `FemaleText_loc4`='我们的工作就是保持平衡，如同塞纳留斯所教给我们的一样，$c。他就是指引我们前进的明灯，而我们必须竭尽所能保护它的光芒。', `FemaleText_loc5`='我們的工作就是保持萬物的平衡，如同塞納留斯所教給我們的那樣，$c。他就是指引我們前進的明燈，而我們必須竭盡所能保護那道光芒。', `FemaleText_loc7`='Trabajamos para preservar el equilibrio siguiendo las enseñanzas de Cenarius, $c. Él es la luz de un faro que ilumina nuestro camino, y debemos hacer todo lo que sea posible para conservar esa luz.' WHERE `ID`=7463;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오십시오. 훈련을 받으러 오신 것이라면 제가 기꺼이 가르쳐 드리겠습니다.$B$B세나리우스의 가르침대로 우리는 언제까지나 균형을 지키도록 노력해야 합니다. 절대 잊지 마십시오.', `MaleText_loc4`='欢迎你，我的$g兄弟:姐妹;。如果你是来接受训练的，那我很高兴能训练你。$B$B如塞纳留斯教导我们的一样，我们一直都是平衡的保护者。永远不要忘记这点。', `MaleText_loc5`='歡迎你，我的$g兄弟:姐妹;。如果你是來接受訓練的，那我很高興能訓練你。$B$B如塞納留斯教導我們的一樣，我們一直都是平衡的保護者。永遠不要忘記這點。', `MaleText_loc7`='$GBienvenido:Bienvenida;, $ghermano:hermana;. Si has venido en busca de instrucción, estaré encantada de ayudarte.$B$BSomos los protectores del equilibrio, ahora y siempre, siguiendo las enseñanzas de Cenarius. Nunca lo olvides.', `FemaleText_loc1`='어서 오십시오. 훈련을 받으러 오신 것이라면 제가 기꺼이 가르쳐 드리겠습니다.$B$B세나리우스의 가르침대로 우리는 언제까지나 균형을 지키도록 노력해야 합니다. 절대 잊지 마십시오.', `FemaleText_loc4`='欢迎你，我的$g兄弟:姐妹;。如果你是来接受训练的，那我很高兴能训练你。$B$B如塞纳留斯教导我们的一样，我们一直都是平衡的保护者。永远不要忘记这点。', `FemaleText_loc5`='歡迎你，我的$g兄弟:姐妹;。如果你是來接受訓練的，那我很高興能訓練你。$B$B如塞納留斯教導我們的一樣，我們一直都是平衡的保護者。永遠不要忘記這點。', `FemaleText_loc7`='$GBienvenido:Bienvenida;, $ghermano:hermana;. Si has venido en busca de instrucción, estaré encantada de ayudarte.$B$BSomos los protectores del equilibrio, ahora y siempre, siguiendo las enseñanzas de Cenarius. Nunca lo olvides.' WHERE `ID`=7464;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n, 다시 한 번 감사드려요! 이 사실을 알게 돼서 얼마나 기쁜지 모른답니다.$B$B행운을 빌어요!', `FemaleText_loc4`='再次感谢你，$n！我对我们所发现的东西感到很高兴。$B$B祝你好运！', `FemaleText_loc5`='再次感謝你，$n!我對我們所發現的東西感到很高興。$B$B祝你好運!', `FemaleText_loc7`='¡Gracias de nuevo, $n! Estoy muy contenta con lo que hemos descubierto.$B$B¡Buena suerte!' WHERE `ID`=7465;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='숲에 올라갈 채비를 하고 있었어요. 누가 도와주면 좋겠는데... 같이 가실래요? $n.', `FemaleText_loc4`='我准备出发了，$n。我需要一些帮助——你愿意跟我来吗？', `FemaleText_loc5`='我準備出發了，$n。我需要一些幫助─你願意跟我來嗎?', `FemaleText_loc7`='Me estoy preparando para subir a la cresta, $n. Podría necesitar ayuda, ¿te gustaría acompañarme?' WHERE `ID`=7466;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 이상한 주문을 외우기 시작합니다.', `FemaleText_loc4`='%s开始吟唱一个奇怪的法术……', `FemaleText_loc5`='%s開始吟唱一個奇怪的法術...', `FemaleText_loc7`='%s comienza a lanzar un extraño hechizo...' WHERE `ID`=7467;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물어 올 준비 됐지? 멍멍아?', `MaleText_loc4`='你准备好了吗，孩子？', `MaleText_loc5`='你準備好了嗎，孩子?', `MaleText_loc7`='¿Estás listo para recoger esto, muchacho?' WHERE `ID`=7468;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 기대감에 가득 찬 소리로 짖습니다.', `MaleText_loc4`='%s充满期待地叫了起来。', `MaleText_loc5`='%s充滿期待地叫了起來。', `MaleText_loc7`='%s ladra con expectación.' WHERE `ID`=7469;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가서 물어와!!', `MaleText_loc4`='快去！！', `MaleText_loc5`='快去!!', `MaleText_loc7`='¡¡Ve a cogerlo!!!' WHERE `ID`=7470;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='레드패스! 넌 여기서 끝이다!', `MaleText_loc4`='雷德帕斯！纳命来！', `MaleText_loc5`='雷德帕斯!納命來!', `MaleText_loc7`='¡Rutagrana! ¡Ha llegado el fin de tus días, aquí y ahora!' WHERE `ID`=7471;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미안하지만, 자네는 가르칠 수 없네.', `MaleText_loc4`='我无法训练你。', `MaleText_loc5`='我無法訓練你。', `MaleText_loc7`='No puedo instruirte.', `FemaleText_loc1`='미안하지만, 자네는 가르칠 수 없네.', `FemaleText_loc4`='我无法训练你。', `FemaleText_loc5`='我無法訓練你。', `FemaleText_loc7`='No puedo instruirte.' WHERE `ID`=7472;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘했어! 뼈다귀 더미에 갖다 놓거라, 멍멍아.', `MaleText_loc4`='干得好！现在把它放在上面。', `MaleText_loc5`='幹得好!現在把它放到骨頭堆上。', `MaleText_loc7`='¡Buen chico! Ahora ponlo otra vez en la pila de huesos.' WHERE `ID`=7473;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기젤톤 대상단을 보호할 경호원을 구합니다! 저희는 코르메크의 오두막에서 동쪽, 콜카르 켄타우로스 마을에서 북쪽에 있는 길가에 서 있습니다.', `MaleText_loc4`='我在寻找愿意保护基泽尔顿车队的卫兵。我们被挡在了考米克小屋东面的路上，就在科尔卡半人马村的北边。', `MaleText_loc5`='我在尋找願意保護基澤爾頓商隊的守衛。我們被擋在了考米克小屋東面的路上，就在科卡爾半人馬村的北邊。', `MaleText_loc7`='Estoy buscando guardaespaldas que quieran proteger la caravana Gizelton. Estamos parados en el camino al este de la Cabaña de Kormek, al norte del Poblado centauro Kolkar.' WHERE `ID`=7474;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리거 기젤톤입니다! 제 짐마차가 만노로크 소굴을 무사히 통과할 수 있도록 도움이 필요합니다. 저희는 지금 그늘수렵 마을의 동쪽 길에 있습니다.', `MaleText_loc4`='里格·基泽尔顿寻求帮助，护送我的商队穿过玛诺洛克集会所。我在葬影村东面的路上。', `MaleText_loc5`='里格·基澤爾頓尋求幫助，護送我的商隊穿過瑪諾洛克集會所。我在葬影村東面的路上。', `MaleText_loc7`='Aquí Rigger Gizelton, pidiendo ayuda para escoltar mi caravana a través de Aquelarre Mannoroc. Estoy en el camino, al este de Aldea Cazasombras.' WHERE `ID`=7475;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 $c|1은;는; 가르치지 않는다네.', `MaleText_loc4`='我不能训练你。', `MaleText_loc5`='我不能訓練你，$c。', `MaleText_loc7`='No entreno a tu clase, $c.', `FemaleText_loc1`='난 $c|1은;는; 가르치지 않는다네.', `FemaleText_loc4`='我不能训练你。', `FemaleText_loc5`='我不能訓練你，$c。', `FemaleText_loc7`='No entreno a tu clase, $c.' WHERE `ID`=7476;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 이 세계의 어둠이자 그림자요. 영원하며 보이지 않는...', `MaleText_loc4`='我们代表的是黑暗，永恒而无形。', `MaleText_loc5`='我們代表的是黑暗與陰影。永恆。無形。', `MaleText_loc7`='No somos más que tinieblas y sombras. Eternos. Invisibles.', `FemaleText_loc1`='우리는 이 세계의 어둠이자 그림자요. 영원하며 보이지 않는...', `FemaleText_loc4`='我们代表的是黑暗，永恒而无形。', `FemaleText_loc5`='我們代表的是黑暗與陰影。永恆。無形。', `FemaleText_loc7`='No somos más que tinieblas y sombras. Eternos. Invisibles.' WHERE `ID`=7477;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련을 받고 싶습니다.', `MaleText_loc4`='我想接受训练。', `MaleText_loc5`='我想接受訓練。', `MaleText_loc7`='Necesito instrucción.', `FemaleText_loc1`='훈련을 받고 싶습니다.', `FemaleText_loc4`='我想接受训练。', `FemaleText_loc5`='我想接受訓練。', `FemaleText_loc7`='Necesito instrucción.' WHERE `ID`=7478;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='젊은 도적이여, 안녕하시오? 무엇을 찾고 있소?', `MaleText_loc4`='你好，年轻的潜行者。你在找什么？', `MaleText_loc5`='你好，年輕的盜賊。你在找什麼?', `MaleText_loc7`='Saludos joven pícaro. ¿Qué necesitas?', `FemaleText_loc1`='젊은 도적이여, 안녕하세요? 무엇을 찾고 계세요?', `FemaleText_loc4`='你好，年轻的潜行者。你在找什么？', `FemaleText_loc5`='你好，年輕的盜賊。你在找什麼?', `FemaleText_loc7`='Saludos joven pícaro. ¿Qué necesitas?' WHERE `ID`=7479;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 자네를 가르칠 수 없어. 자네 직업에 맞는 상급자나 찾아가 보게.', `MaleText_loc4`='我不能训练你。你必须去找你的职业训练师。', `MaleText_loc5`='我不能訓練你。你必須去找你的職業訓練師。', `MaleText_loc7`='No puedo instruirte. Debes hablar con tu instructor de clase.', `FemaleText_loc1`='난 자네를 가르칠 수 없어. 자네 직업에 맞는 상급자나 찾아가 보게.', `FemaleText_loc4`='我不能训练你。你必须去找你的职业训练师。', `FemaleText_loc5`='我不能訓練你。你必須去找你的職業訓練師。', `FemaleText_loc7`='No puedo instruirte. Debes hablar con tu instructor de clase.' WHERE `ID`=7480;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 도와줄 수 없겠구먼. 난 도적만 가르치거든.', `MaleText_loc4`='我帮不了你，$n。我只训练潜行者。', `MaleText_loc5`='沒法幫你，$n。我只訓練盜賊。', `MaleText_loc7`='No puedo ayudarte, $n. Solo instruyo a pícaros.', `FemaleText_loc1`='$n, 도와줄 수 없겠구먼. 난 도적만 가르치거든.', `FemaleText_loc4`='我帮不了你，$n。我只训练潜行者。', `FemaleText_loc5`='沒法幫你，$n。我只訓練盜賊。', `FemaleText_loc7`='No puedo ayudarte, $n. Solo instruyo a pícaros.' WHERE `ID`=7481;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 미안하네만 도와줄 수 없네. 난 도적만 가르친다네.', `MaleText_loc4`='我帮不了你，$n。我只训练潜行者。', `MaleText_loc5`='沒法幫你，$n。我只訓練盜賊。', `MaleText_loc7`='No puedo ayudarte, $n. Solo instruyo a pícaros.', `FemaleText_loc1`='$n, 죄송하지만 도와드릴 수 없어요. 전 도적만 가르친답니다.', `FemaleText_loc4`='我帮不了你，$n。我只训练潜行者。', `FemaleText_loc5`='沒法幫你，$n。我只訓練盜賊。', `FemaleText_loc7`='No puedo ayudarte, $n. Solo entreno a pícaros.' WHERE `ID`=7482;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죄송합니다만, 전 도적만 가르칩니다.', `MaleText_loc4`='对不起，但是我只训练盗贼。', `MaleText_loc5`='對不起，但是我只訓練盜賊。', `MaleText_loc7`='Lo siento, pero solo entreno a pícaros.', `FemaleText_loc1`='죄송합니다만, 전 도적만 가르칩니다.', `FemaleText_loc4`='对不起，但是我只训练盗贼。', `FemaleText_loc5`='對不起，但是我只訓練盜賊。', `FemaleText_loc7`='Lo siento, solo instruyo a pícaros.' WHERE `ID`=7483;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오! 또 손님이군. 어서 오시게! 내 위대한 발명품, 자동판매기 1000을 한번 사용해 보는 게 어때? 필요한 건 다 있다고. 칼림도어의 온 상점을 다 뒤져도 못 찾을 희귀한 물건도 있다네! 참, 값을 깎지 못하도록 프로그램했을 거라는 건 말 안 해도 알겠지? 그냥 달라는 대로 내라고.', `MaleText_loc4`='啊……一名顾客！看看我最伟大的发明，贸易机器人1000型！它拥有你所需的一切商品……其中的一些稀有物品更是在卡利姆多的其它任何市场上都找不到……更不用说它的设计不支持任何讨价还价的废话了，因此你看到的价格就是你要支付的价格。', `MaleText_loc5`='啊...一名顧客!看看我最偉大的發明，貿易機器人1000型!它擁有你所需的一切商品...其中的一些稀有物品更是在卡林多的其他任何市場上都找不到...更不用說它的設計不支持任何討價還價的廢話了，因此你看到的價格就是你要支付的價格。', `MaleText_loc7`='¡Ah... un cliente! Habla con mi grandioso invento, el Vende-Tron 1000. Tiene todo lo que necesitas... algunos de los objetos más raros que puedas encontrar en cualquier mercado de Kalimdor... por no mencionar que su programación no permitirá ningún tipo de regateo, así que el precio que ves será exactamente lo que pagues.' WHERE `ID`=7484;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보나 마나 어둠의 여왕님께서 훈련을 시키라고 보내신 얼간이로군.$B$B<한숨을 쉬는 나타노스>$B$B이제까지 너 같은 놈들은 모조리 두 동강을 내서 여왕님께 돌려보냈지. 네놈도 같은 꼴이 될 거야.$B$B나야 뭐, 여왕님의 분부대로 할 뿐이니까 상관없지만 말이야.', `MaleText_loc4`='毫无疑问，你是黑暗女王派来接受训练的又一个无能的白痴。$B$B<纳萨诺斯叹息着。>$B$B我每次都得把你们的尸体运回去给她，我想这次也不会有什么例外。$B$B但是，我并不会问什么，我只按照黑暗女王的吩咐办事。', `MaleText_loc5`='毫無疑問，你是黑暗女王派來接受訓練的又一個無能的白癡。$B$B<納薩諾斯歎息著。>$B$B我每次都得把你們的屍體運回去給她，我想這次也不會有什麼例外。$B$B但是，我並不會問什麼，我只按照黑暗女王的吩咐辦事。', `MaleText_loc7`='Sin duda eres $gotro inepto enviado:otra inepta enviada; por la Dama Oscura para que se instruya con su Campeón.$B$B<Nathanos suspira.>$B$BOs he devuelto a todos hechos pedazos, no creo que esta vez vaya a ser diferente.$B$BPero yo no debo plantearme el porqué, tan solo hacer lo que disponga la Dama Oscura.' WHERE `ID`=7486;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물건 좀 봅시다.', `MaleText_loc4`='让我看看你提供的东西。', `MaleText_loc5`='讓我看看你提供的東西。', `MaleText_loc7`='Déjame echar un vistazo a tu oferta.', `FemaleText_loc1`='물건 좀 봅시다.', `FemaleText_loc4`='让我看看你提供的东西。', `FemaleText_loc5`='讓我看看你提供的東西。', `FemaleText_loc7`='Déjame echar un vistazo a tu oferta.' WHERE `ID`=7487;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 운이 좋으시군요. 방금 슈퍼 판매기 680의 정비를 마쳤는데. 아주 저렴한 물건이 잔뜩 쌓여 있습니다. 가서 한번 보시죠. 제 동생 코르크는 자동판매기 1000이 물건을 더 많이 팔 거라고 했지만, 흥!', `MaleText_loc4`='今天碰巧是你的幸运日；我完成了超级商人680型的维护工作，因此有大量物品以超低的价格出售。你自己去看看吧……我的兄弟考克认为他的贸易机器人1000型会胜过我的。', `MaleText_loc5`='今天碰巧是你的幸運日;我完成了超級商人680型的維護工作，因此有大量物品以超低的價格出售。你自己去看看吧...我的兄弟考克認為他的貿易機器人1000型會勝過我的。', `MaleText_loc7`='Vaya, es tu día de suerte; acabo de terminar el mantenimiento del Supervendedor 680. Hay toneladas de objetos a la venta a precios de risa. Adelante y mira tu mismo... mi hermano Cork piensa que su Vende-Tron 1000 venderá más que mi robot.' WHERE `ID`=7488;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 뭘 도와 드릴까요?', `MaleText_loc4`='我可以为你效劳吗，$n？', `MaleText_loc5`='我可以為你效勞嗎，$n?', `MaleText_loc7`='¿Qué puedo hacer por ti, $n?', `FemaleText_loc1`='$n, 뭘 도와 드릴까요?', `FemaleText_loc4`='我可以为你效劳吗，$n？', `FemaleText_loc5`='我能為你做什麼事嗎, $n?', `FemaleText_loc7`='¿Qué puedo hacer por ti, $n?' WHERE `ID`=7489;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도적 훈련을 받으러 왔습니다.', `MaleText_loc4`='我想接受潜行者的训练。', `MaleText_loc5`='我想接受盜賊的訓練。', `MaleText_loc7`='Busco instrucción como pícaro.', `FemaleText_loc1`='도적 훈련을 받으러 왔습니다.', `FemaleText_loc4`='我想接受潜行者的训练。', `FemaleText_loc5`='我想接受盜賊的訓練。', `FemaleText_loc7`='Busco instrucción como pícaro.' WHERE `ID`=7490;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도적 기술을 가르쳐 주시겠습니까?', `MaleText_loc4`='你能训练我使用潜行者技能吗？', `MaleText_loc5`='你能訓練我使用盜賊技能嗎?', `MaleText_loc7`='¿Puedes instruirme en las habilidades del pícaro?', `FemaleText_loc1`='도적 기술을 가르쳐 주시겠습니까?', `FemaleText_loc4`='你能训练我使用潜行者技能吗？', `FemaleText_loc5`='你能訓練我使用盜賊技能嗎?', `FemaleText_loc7`='¿Puedes instruirme en las habilidades del pícaro?' WHERE `ID`=7491;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신을 보니 왠지 내 가방이 잘 있나 확인해봐야겠다는 생각이 드는군. 도울 일이라도 있습니까?', `MaleText_loc4`='你看起来像是那种手脚不干净的家伙。有什么我可以帮忙的吗？', `MaleText_loc5`='你看起來像是那種手腳不乾淨的傢伙。有什麼我可以幫忙的嗎?', `MaleText_loc7`='Parece que contigo tendré que vigilar bien el bolsillo. ¿Puedo ayudarte en algo?', `FemaleText_loc1`='당신을 보니 왠지 저도 모르게 가방이 잘 있나 확인하게 되는군요. 그런데... 제가 도울 일이라도 있나요?', `FemaleText_loc4`='你看起来像是那种手脚不干净的家伙。有什么我可以帮忙的吗？', `FemaleText_loc5`='你看起來像是那種手腳不乾淨的傢伙。有什麼我可以幫忙的嗎?', `FemaleText_loc7`='Parece que contigo tendré que vigilar bien el bolsillo. ¿Puedo ayudarte en algo?' WHERE `ID`=7492;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신에게 내 기술은 별로 쓸모가 없을 것 같습니다. 상급 $c|1을;를; 찾아가면 도움을 받을 수 있을 거요.', `MaleText_loc4`='我跟你没什么好说的，你最好找个$c训练师来帮助你。', `MaleText_loc5`='我跟你沒什麼好說的，你最好找個$c訓練師來幫助你。', `MaleText_loc7`='Creo que no te interesa lo que puedo enseñarte. Quizás te interese encontrar a un instructor de $c que te ayude.', `FemaleText_loc1`='당신에게 제 기술은 별로 쓸모가 없을 것 같군요 상급 $c|1을;를; 찾아가면 도움을 받을 수 있을 거예요.', `FemaleText_loc4`='我跟你没什么好说的，你最好找个$c训练师来帮助你。', `FemaleText_loc5`='我跟你沒什麼好說的，你最好找個$c訓練師來幫助你。', `FemaleText_loc7`='Creo que no te interesa lo que puedo enseñarte. Quizás te interese encontrar a un instructor de $c que te ayude.' WHERE `ID`=7493;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전문가의 솜씨를 배우러 왔나?', `MaleText_loc4`='你是来学习的吗？', `MaleText_loc5`='你是來學習的嗎?', `MaleText_loc7`='¿Vienes a aprender del maestro, eh?', `FemaleText_loc1`='전문가의 솜씨를 배우러 왔습니까?', `FemaleText_loc4`='你是来学习的吗？', `FemaleText_loc5`='你是來學習的嗎?', `FemaleText_loc7`='¿Vienes a aprender del maestro, eh?' WHERE `ID`=7494;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부디 가르침을 내려 주십시오.', `MaleText_loc4`='当然，我有。教给我吧。', `MaleText_loc5`='當然，我有。教給我吧。', `MaleText_loc7`='Sí, así es. Enséñame.', `FemaleText_loc1`='부디 가르침을 내려 주십시오.', `FemaleText_loc4`='当然，我有。教给我吧。', `FemaleText_loc5`='當然，我有。教給我吧。', `FemaleText_loc7`='Sí, así es. Enséñame.' WHERE `ID`=7495;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 눈에는 내가 $c|1으로;로; 보이나? 내 칼날을 너의 피로 물들이기 전에 썩 물러가라!', `MaleText_loc4`='你看我像是个$c吗？在我决定用你的血洗我的刀之前，赶紧逃吧。', `MaleText_loc5`='你看我像是個$c嗎?在我決定用你的血洗我的刀之前，趕緊逃吧。', `MaleText_loc7`='¿Te parece que soy $c? Ahora vete antes de que me entren ganas de afilar mi espada... en tu carne.', `FemaleText_loc1`='당신 눈에는 내가 $c|1으로;로; 보입니까? 내 칼날을 당신 피로 물들이기 전에 썩 물러가세요!', `FemaleText_loc4`='你看我像是个$c吗？在我决定用你的血洗我的刀之前，赶紧逃吧。', `FemaleText_loc5`='你看我像是個$c嗎?在我決定用你的血洗我的刀之前，趕緊逃吧。', `FemaleText_loc7`='¿Te parece que soy $c? Ahora vete antes de que me entren ganas de afilar mi espada... en tu carne.' WHERE `ID`=7496;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$C|1이여;여;, 엘룬께서 그대와 함께하시기를.', `MaleText_loc4`='愿月神与你同在，$c。', `MaleText_loc5`='願伊露恩與你同在，$c。', `MaleText_loc7`='Que Elune esté contigo, $c.' WHERE `ID`=7497;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하시오? 이 혼란과 격동의 시기에 여명이 당신을 지켜주기를...', `MaleText_loc4`='你好，朋友。愿黎明在这个乱世之中保佑你平安无恙。', `MaleText_loc5`='你好，朋友。願黎明在這個亂世之中保佑你平安無恙。', `MaleText_loc7`='Saludos, $gamigo:amiga;. Que el Alba te cuide en estos tiempos terribles.' WHERE `ID`=7498;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐. 너무 서두르지는 마시오. 아이언포지 드워프들의 동지임이 입증되지 않은 자에게 힘 좋은 산양을 넘길 수는 없지. 아이언포지에 호의적이라는 것만 밝혀지면 비싼 값에 팔려고 내놓은 산양을 내 기꺼이 보여주겠소.', `MaleText_loc4`='现在还不行，$g小伙子:姑娘;……我是不会把强大的战羊随意卖给其他人的，你必须首先证明自己是铁炉堡矮人的忠实盟友才行。一旦我确认你在铁炉堡的声望达到友善的程度，那我会很乐意让你看看我出售的多种战羊的。', `MaleText_loc5`='現在還不行，$g小夥子:姑娘;...我是不會把強大的戰羊隨意賣給其他人的，你必須首先證明自己是鐵爐堡矮人的忠實盟友才行。一旦我確認你在鐵爐堡的聲望達到友好的程度，那我會很樂意讓你看看我出售的多種戰羊的。', `MaleText_loc7`='No tan deprisa, $gmuchacho:muchacha;... No iré repartiendo por ahí el mando de un poderoso carnero de montar a alguien que no es considerado aliado de los enanos de Forjaz. Cuando tu reputación sea de $gamistoso:amistosa; con Forjaz, estaré encantado de mostrarte toda mi variedad de carneros.', `FemaleText_loc1`='이봐. 너무 서두르지는 마시오. 아이언포지 드워프들의 동지임이 입증되지 않은 자에게 힘 좋은 산양을 넘길 수는 없지. 아이언포지에 호의적이라는 것만 밝혀지면 비싼 값에 팔려고 내놓은 산양을 내 기꺼이 보여주겠소.', `FemaleText_loc4`='现在还不行，$g小伙子:姑娘;……我是不会把强大的战羊随意卖给其他人的，你必须首先证明自己是铁炉堡矮人的忠实盟友才行。一旦我确认你在铁炉堡的声望达到友善的程度，那我会很乐意让你看看我出售的多种战羊的。', `FemaleText_loc5`='現在還不行，$g小夥子:姑娘;...我是不會把強大的戰羊隨意賣給其他人的，你必須首先證明自己是鐵爐堡矮人的忠實盟友才行。一旦我確認你在鐵爐堡的聲望達到友好的程度，那我會很樂意讓你看看我出售的多種戰羊的。', `FemaleText_loc7`='No tan deprisa, $gmuchacho:muchacha;... No iré repartiendo por ahí el mando de un poderoso carnero de montar a alguien que no es considerado aliado de los enanos de Forjaz. Cuando tu reputación sea de $gamistoso:amistosa; con Forjaz, estaré encantado de mostrarte toda mi variedad de carneros.' WHERE `ID`=7499;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물건값을 깎을 수 없도록 프로그램되어 있습니다.', `MaleText_loc4`='我的规划是不允许减少任何项目的成本的。', `MaleText_loc5`='我的規劃是不允許減少任何專案的成本的。', `MaleText_loc7`='Mi programación no me permite rebajar el coste de ningún objeto.' WHERE `ID`=7500;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 물건이 있는지 봅시다.', `MaleText_loc4`='我很好奇这样一台机器能为我提供什么。', `MaleText_loc5`='我很好奇這樣一台機器能為我提供什麼。', `MaleText_loc7`='Tengo curiosidad por ver lo que puede hacer un saco de tornillos.', `FemaleText_loc1`='어떤 물건이 있는지 봅시다.', `FemaleText_loc4`='我很好奇这样一台机器能为我提供什么。', `FemaleText_loc5`='我很好奇這樣一台機器能為我提供什麼。', `FemaleText_loc7`='Tengo curiosidad por ver lo que puede hacer un saco de tornillos.' WHERE `ID`=7501;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 키운 바라크 토롤 산양을 타보기 전까지는 제대로 된 탈것에 올라봤다고 할 수 없지요. 이 훌륭한 놈들을 언제라도 어느 모험가에게든 자랑스럽게 보여주십시오. 그리고 어떤 상황에서든지 아주 유용할 테니까요, 제 말을 믿으십시오.', `MaleText_loc4`='在驾驭过一头受过良好训练的山羊之前，就别夸口说你已经拥有了真正的坐骑，我的朋友。请随意看看这些杰出的坐骑吧。它们会让你满意的，相信我。', `MaleText_loc5`='在駕馭過一頭受過良好訓練的山羊之前，就別誇口說你已經擁有了真正的坐騎，我的朋友。請隨意看看這些傑出的坐騎吧。它們會讓你滿意的，相信我。', `MaleText_loc7`='No habrás tenido un corcel hasta que no hayas cogido las riendas de un carnero montañés de raza pura Barak Tor''ol, $gamigo:amiga;. Por favor, examina cuanto quieras estos fieles compañeros de cualquier aventurero. Te servirán bien, créeme.', `FemaleText_loc1`='잘 키운 바라크 토롤 산양을 타보기 전까지는 제대로 된 탈것에 올라봤다고 할 수 없지요. 이 훌륭한 놈들을 언제라도 어느 모험가에게든 자랑스럽게 보여주십시오. 그리고 어떤 상황에서든지 아주 유용할 테니까요, 제 말을 믿으십시오.', `FemaleText_loc4`='在驾驭过一头受过良好训练的山羊之前，就别夸口说你已经拥有了真正的坐骑，我的朋友。请随意看看这些杰出的坐骑吧。它们会让你满意的，相信我。', `FemaleText_loc5`='在駕馭過一頭受過良好訓練的山羊之前，就別誇口說你已經擁有了真正的坐騎，我的朋友。請隨意看看這些傑出的坐騎吧。它們會讓你滿意的，相信我。', `FemaleText_loc7`='No habrás tenido un corcel hasta que no hayas cogido las riendas de un carnero montañés de raza pura Barak Tor''ol, $gamigo:amiga;. Por favor, examina cuanto quieras estos fieles compañeros de cualquier aventurero. Te servirán bien, créeme.' WHERE `ID`=7503;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 최신형 자동 로봇 상인입니다. 언젠가는 우리가 세계를 지배할 것입니다. 제가 돈을 떼먹고 있다고 주인님에게 이르거나 하지는 마십시오.', `MaleText_loc4`='我是自动售货商的最新形态……我们总有一天会统治这个世界的……别告诉老板我从他的商品中榨取钱财……', `MaleText_loc5`='我是自動售貨商的最新形態...我們總有一天會統治這個世界的...別告訴老闆我從他的商品中榨取錢財...', `MaleText_loc7`='Soy la última encarnación de los vendedores automatizados... algún día dominaremos el mundo... no le diga a mi jefe que le estoy sisando dinero con su mercancía...' WHERE `ID`=7504;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='손님을 남겨 놓고 가기는 미안하지만 건수가 있어서... 이따 돌아올 거라고. 안녕!', `MaleText_loc4`='很抱歉。我们不得不动身前往别处，继续行骗。我们会回来的。再见！', `MaleText_loc5`='很抱歉。我們不得不動身前往別處，繼續行騙。我們會回來的。再見!', `MaleText_loc7`='Siento mucho tener que dejar a un cliente, pero tenemos muchos sitios a los que ir y mucha gente a la que estafar. Volveremos hoy mismo, algo más tarde. ¡Hasta la vista!' WHERE `ID`=7505;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기젤톤의 짐마차가 이제 출발합니다! 곧 돌아올 테지만, 좀이 쑤셔서 기다릴 수 없으면 북쪽에 있는 코르메크의 오두막으로 와 주세요. 저희는 한 시간 안에 거기서 문을 열 겁니다.', `MaleText_loc4`='基泽尔顿车队出发的时间到了！我们很快就会回来的，但是如果你等不及的话，朝北方走，到考米克小屋去。我们会在一小时后开张的。', `MaleText_loc5`='基澤爾頓車隊出發的時間到了!我們很快就會回來的，但是如果你等不及的話，朝北方走，到考米克小屋去。我們會在一小時後開張的。', `MaleText_loc7`='¡Es hora de que la caravana Gizleton siga su camino! ¡Volveremos muy pronto pero si no puedes esperar, ve hacia el Norte, hacia la Cabaña de Kormek. Abriremos nuestra tienda en una hora.' WHERE `ID`=7506;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죄송하지만, 스톰윈드 왕국에 호의적이지 않은 자에게 말을 팔고 싶지는 않습니다. 이 말들은 다른 어디에서도 볼 수 없는 최고의 품종인데 적의 손에 들어가기라도 하면 안 되니까 말입니다.$B$B물론 당신이 적이라는 얘기는 아닙니다. 스톰윈드의 신임을 얻어 오면 그때 거래를 하도록 하겠습니다.', `MaleText_loc4`='很抱歉，如果你没有在暴风城达到友善的声望，我是不会将马匹卖给你的。这些战马是最好的，我们当然不会当它们落入敌人之手。$B$B想要证明自己不是敌人的话，你只需赢得暴风城的信任，这样我就可以跟你做买卖了。', `MaleText_loc5`='很抱歉，如果你沒有在暴風城達到友好的聲望，我是不會將馬匹賣給你的。這些戰馬是最好的，我們當然不會當它們落入敵人之手。$B$B想要證明自己不是敵人的話，你只需贏得暴風城的信任，這樣我就可以跟你做買賣了。', `MaleText_loc7`='Lo siento, pero no estoy dispuesto a vender mis caballos a nadie que no sea considerado amistoso del Reino de Ventormenta. Estos corceles son los mejores que podrás encontrar y no los querríamos ver en las manos de nuestros enemigos.$B$BNo sugiero que tú seas $gun enemigo:una enemiga;... por supuesto... gánate la confianza de Ventormenta y podremos hacer negocios.', `FemaleText_loc1`='죄송하지만, 스톰윈드 왕국에 호의적이지 않은 자에게 말을 팔고 싶지는 않습니다. 이 말들은 다른 어디에서도 볼 수 없는 최고의 품종인데 적의 손에 들어가기라도 하면 안 되니까 말입니다.$B$B물론 당신이 적이라는 얘기는 아닙니다. 스톰윈드의 신임을 얻어 오면 그때 거래를 하도록 하겠습니다.', `FemaleText_loc4`='很抱歉，如果你没有在暴风城达到友善的声望，我是不会将马匹卖给你的。这些战马是最好的，我们当然不会当它们落入敌人之手。$B$B想要证明自己不是敌人的话，你只需赢得暴风城的信任，这样我就可以跟你做买卖了。', `FemaleText_loc5`='很抱歉，如果你沒有在暴風城達到友好的聲望，我是不會將馬匹賣給你的。這些戰馬是最好的，我們當然不會當它們落入敵人之手。$B$B想要證明自己不是敵人的話，你只需贏得暴風城的信任，這樣我就可以跟你做買賣了。', `FemaleText_loc7`='Lo siento, pero no estoy dispuesta a vender mis caballos a nadie que no sea considerado amistoso del Reino de Ventormenta. Estos corceles son los mejores que podrás encontrar y no los querríamos ver en las manos de nuestros enemigos.$B$BNo sugiero que tú seas $gun enemigo:una enemiga;... por supuesto... gánate la confianza de Ventormenta y podremos hacer negocios.' WHERE `ID`=7507;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수년에 걸친 품종 개량과 정성을 쏟은 결과로 탄생한 말들을 자랑스럽게 소개합니다! 타실 말을 천천히 골라 보세요. 말은 평생 친구죠. 오늘 여기서 멋진 녀석으로 한 마리 마련하세요! 당신은 소중한 분이시니까요!', `MaleText_loc4`='多年的精心饲养和细致的品种培育使我能够有机会向你展示这些良种马。请慢慢挑选，马是你长期的伙伴，朋友。不要把自己低估了——今天就在这里找到你想要的马！', `MaleText_loc5`='多年的精心飼養和細緻的品種培育使我能夠有機會向你展示這些良種馬。請慢慢挑選，馬是你長期的夥伴，朋友。不要把自己低估了─今天就在這裡找到你想要的馬!', `MaleText_loc7`='¡Mis años de experiencia como criador y todos mis cuidados me otorgan el privilegio de mostrarte estos caballos! Por favor, tómate tu tiempo para examinarlos. Un caballo te acompañará durante años, $gamigo:amiga;. ¡Hazte valer y adquiere hoy mismo tu montura!', `FemaleText_loc1`='수년에 걸친 품종 개량과 정성을 쏟은 결과로 탄생한 말들을 자랑스럽게 소개합니다! 타실 말을 천천히 골라 보세요. 말은 평생 친구죠. 오늘 여기서 멋진 녀석으로 한 마리 마련하세요! 당신은 소중한 분이시니까요!', `FemaleText_loc4`='多年的精心饲养和细致的品种培育使我能够有机会向你展示这些良种马。请慢慢挑选，马是你长期的伙伴，朋友。不要把自己低估了——今天就在这里找到你想要的马！', `FemaleText_loc5`='多年的精心飼養和細緻的品種培育使我能夠有機會向你展示這些良種馬。請慢慢挑選，馬是你長期的夥伴，朋友。不要把自己低估了─今天就在這裡找到你想要的馬!', `FemaleText_loc7`='¡Mis años de experiencia como criadora y todos mis cuidados me otorgan el privilegio de mostrarte estos caballos! Por favor, tómate tu tiempo para examinarlos. Un caballo te acompañará durante años, $gamigo:amiga;. ¡Hazte valer y adquiere hoy mismo tu montura!' WHERE `ID`=7508;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물건을 보고 싶습니다.', `MaleText_loc4`='让我看看你的货物。', `MaleText_loc5`='讓我看看你的貨物。', `MaleText_loc7`='Deja que eche un vistazo a tus mercancías.', `FemaleText_loc1`='물건을 보고 싶습니다.', `FemaleText_loc4`='让我看看你的货物。', `FemaleText_loc5`='讓我看看你的貨物。', `FemaleText_loc7`='Deja que eche un vistazo a tus mercancías.' WHERE `ID`=7509;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='낯선 분이로군요. 코도는 힘이 아주 세답니다. 우리 타우렌 종족의 사랑과 보살핌의 산물이죠. 그래서 이방인에게는 드릴 수 없습니다. 썬더 블러프 장로들에게 친구로 인정받기 전에는 코도를 팔 수 없습니다.', `MaleText_loc4`='你并不为我的同胞所知。科多兽是强大的坐骑，它是我们的爱心和关怀的产物；所以我不能把它卖给陌生的冒险者。在你同雷霆崖的声望达到友善之前，我不能卖给你科多兽。', `MaleText_loc5`='你並不為我的同胞所知。科多獸是強大的坐騎，它是我們的愛心和關懷的產物;所以我不能把它賣給陌生的冒險者。在你同雷霆崖的聲望達到友善之前，我不能賣給你科多獸。', `MaleText_loc7`='No eres muy $gconocido:conocida; entre mi pueblo. Un kodo es un poderoso corcel y es el resultado del amor y cuidado de mi pueblo, algo así no se da a un extraño. Hasta que los mayores de Cima del Trueno te consideren como $gun amigo:una amiga; no puedo ofrecerte la compra de un kodo.', `FemaleText_loc1`='낯선 분이로군요. 코도는 힘이 아주 세답니다. 우리 타우렌 종족의 사랑과 보살핌의 산물이죠. 그래서 이방인에게는 드릴 수 없습니다. 썬더 블러프 장로들에게 친구로 인정받기 전에는 코도를 팔 수 없습니다.', `FemaleText_loc4`='你并不为我的同胞所知。科多兽是强大的坐骑，它是我们的爱心和关怀的产物；所以我不能把它卖给陌生的冒险者。在你同雷霆崖的声望达到友善之前，我不能卖给你科多兽。', `FemaleText_loc5`='你並不為我的同胞所知。科多獸是強大的坐騎，它是我們的愛心和關懷的產物;所以我不能把它賣給陌生的冒險者。在你同雷霆崖的聲望達到友善之前，我不能賣給你科多獸。', `FemaleText_loc7`='No eres muy $gconocido:conocida; entre mi pueblo. Un kodo es un poderoso corcel y es el resultado del amor y cuidado de mi pueblo, algo así no se da a un extraño. Hasta que los mayores de Cima del Trueno te consideren como $gun amigo:una amiga; no puedo ofrecerte la compra de un kodo.' WHERE `ID`=7510;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사냥을 나갈 때는 사냥감을 찾아 나서기 전에 사냥감에 대해 누군가에게 물어보는 것이 좋다네.', `MaleText_loc4`='在狩猎之前最好问问你要找什么猎物。', `MaleText_loc5`='在狩獵之前最好問問你要找什麼獵物。', `MaleText_loc7`='Antes de empezar una caza, es conveniente preguntar a alguien por lo que estas buscando antes de empezar a buscarlo.', `FemaleText_loc1`='사냥을 나갈 때는 사냥감을 찾아 나서기 전에 사냥감에 대해 누군가에게 물어보는 것이 좋다네.', `FemaleText_loc4`='在狩猎之前最好问问你要找什么猎物。', `FemaleText_loc5`='在狩獵之前最好問問你要找什麼獵物。', `FemaleText_loc7`='Antes de empezar una caza, es conveniente preguntar a alguien por lo que estas buscando antes de empezar a buscarlo.' WHERE `ID`=7511;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이놈이 코도요! 어렸을 때부터 멀고어의 황금 초원에서 훈련을 받으면서 자란 이 멋진 놈들은 정말 최고의 탈것이라고 할 수 있소! 코도들을 직접 한 번 보시오. 우리 타우렌이 이 멋진 친구들을 믿는 이유를 알게 될 거요!', `MaleText_loc4`='看看这些科多兽，我的朋友！它们幼年时便开始接受训练，在莫高雷的金色平原长大，这些家伙就是我们出色的坐骑！看看它们吧，看看我们牛头人为什么会依赖于这些强大的生物！', `MaleText_loc5`='看看這些科多獸，我的朋友!它們幼年時便開始接受訓練，在莫高雷的金色平原長大，這些傢伙就是我們出色的坐騎!看看它們吧，看看我們牛頭人為什麼會依賴於這些強大的生物!', `MaleText_loc7`='¡Bestias kodo, $gamigo:amiga;! ¡Entrenados desde edad temprana y criados en Las Llanuras Doradas de Mulgore, estos delicados animales serán los mejores corceles! Por favor, ¡déjame enseñarte mi selección y comprueba por ti $gmismo:misma; por qué los tauren hemos llegado a confiar en estas magníficas criaturas!', `FemaleText_loc1`='이놈이 코도요! 어렸을 때부터 멀고어의 황금 초원에서 훈련을 받으면서 자란 이 멋진 놈들은 정말 최고의 탈것이라고 할 수 있소! 코도들을 직접 한 번 보시오. 우리 타우렌이 이 멋진 친구들을 믿는 이유를 알게 될 거요!', `FemaleText_loc4`='看看这些科多兽，我的朋友！它们幼年时便开始接受训练，在莫高雷的金色平原长大，这些家伙就是我们出色的坐骑！看看它们吧，看看我们牛头人为什么会依赖于这些强大的生物！', `FemaleText_loc5`='看看這些科多獸，我的朋友!它們幼年時便開始接受訓練，在莫高雷的金色平原長大，這些傢伙就是我們出色的坐騎!看看它們吧，看看我們牛頭人為什麼會依賴於這些強大的生物!', `FemaleText_loc7`='¡Bestias kodo, $gamigo:amiga;! ¡Entrenados desde edad temprana y criados en Las Llanuras Doradas de Mulgore, estos delicados animales serán los mejores corceles! Por favor, ¡déjame enseñarte mi selección y comprueba por ti $gmismo:misma; por qué los tauren hemos llegado a confiar en estas magníficas criaturas!' WHERE `ID`=7512;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$C|1이여;여;, 세나리온 의회에 잘 오셨습니다.', `MaleText_loc4`='欢迎来到塞纳里奥议会，$c。', `MaleText_loc5`='歡迎來到塞納里奧議會，$c。', `MaleText_loc7`='Te doy la bienvenida al Círculo Cenarion, $c.', `FemaleText_loc1`='$C|1이여;여;, 세나리온 의회에 잘 오셨습니다.', `FemaleText_loc4`='欢迎来到塞纳里奥议会，$c。', `FemaleText_loc5`='歡迎來到塞納里奧議會，$c。', `FemaleText_loc7`='$GBienvenido:Bienvenida; al Círculo Cenarion, $c.' WHERE `ID`=7513;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련을 받고 싶습니다.', `MaleText_loc4`='我想接受训练。', `MaleText_loc5`='我想接受訓練。', `MaleText_loc7`='Me gustaría instruirme.', `FemaleText_loc1`='훈련을 받고 싶습니다.', `FemaleText_loc4`='我想接受训练。', `FemaleText_loc5`='我想接受訓練。', `FemaleText_loc7`='Me gustaría instruirme.' WHERE `ID`=7514;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련을 받으러 왔습니다.', `MaleText_loc4`='我准备接受训练。', `MaleText_loc5`='我準備接受訓練。', `MaleText_loc7`='He venido para recibir instrucción.', `FemaleText_loc1`='훈련을 받으러 왔습니다.', `FemaleText_loc4`='我准备接受训练。', `FemaleText_loc5`='我準備接受訓練。', `FemaleText_loc7`='He venido para recibir instrucción.' WHERE `ID`=7515;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대를 훌륭한 사냥꾼으로 훈련시켜 주겠소.', `MaleText_loc4`='让我传授你猎人的技艺吧。', `MaleText_loc5`='讓我傳授你獵人的技藝吧。', `MaleText_loc7`='Déjame instruirte en la senda del cazador.', `FemaleText_loc1`='그대를 훌륭한 사냥꾼으로 훈련시켜 주겠소.', `FemaleText_loc4`='让我传授你猎人的技艺吧。', `FemaleText_loc5`='讓我傳授你獵人的技藝吧。', `FemaleText_loc7`='Déjame instruirte en la senda del cazador.' WHERE `ID`=7516;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련을 받고 싶습니다.', `MaleText_loc4`='我需要培训。', `MaleText_loc5`='我需要培訓。', `MaleText_loc7`='Necesito instrucción.', `FemaleText_loc1`='훈련을 받고 싶습니다.', `FemaleText_loc4`='我需要培训。', `FemaleText_loc5`='我需要培訓。', `FemaleText_loc7`='Necesito instrucción.' WHERE `ID`=7517;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네에게 알려주고 싶은 게 많다네. 명예롭게 사냥하는 법을 배우는 것이 특히 중요하지.', `MaleText_loc4`='我有许多知识可以让你大开眼界，$c。你必须学会带着荣耀去狩猎。', `MaleText_loc5`='我有許多知識可以讓你大開眼界，$c。你必須學會帶著榮耀去狩獵。', `MaleText_loc7`='Tengo mucho conocimiento que transmitirte, $c. Debes aprender a cazar con honor.', `FemaleText_loc1`='당신에게 알려드리고 싶은 게 많습니다. 명예롭게 사냥하는 법을 배우는 것이 특히 중요하지요.', `FemaleText_loc4`='我有许多知识可以让你大开眼界，$c。你必须学会带着荣耀去狩猎。', `FemaleText_loc5`='我有許多知識可以讓你大開眼界，$c。你必須學會帶著榮耀去狩獵。', `FemaleText_loc7`='Tengo muchos conocimientos para impresionarte, $c. Debes aprender a cazar con honor.' WHERE `ID`=7518;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련을 받으러 왔습니다.', `MaleText_loc4`='我是来接受培训的。', `MaleText_loc5`='我是來接受培訓的。', `MaleText_loc7`='He venido para instruirme.', `FemaleText_loc1`='훈련을 받으러 왔습니다.', `FemaleText_loc4`='我是来接受培训的。', `FemaleText_loc5`='我是來接受培訓的。', `FemaleText_loc7`='He venido para instruirme.' WHERE `ID`=7519;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 사냥꾼들을 우리 선조들의 방식과 전통에 따라 가르치고 있습니다.', `MaleText_loc4`='我用祖先传下来的方法训练猎人。', `MaleText_loc5`='我用祖先傳下來的方法訓練獵人。', `MaleText_loc7`='Instruyo a los cazadores en las artes y tradiciones de nuestros ancestros.', `FemaleText_loc1`='난 사냥꾼들을 우리 선조들의 방식과 전통에 따라 가르치고 있소.', `FemaleText_loc4`='我用祖先传下来的方法训练猎人。', `FemaleText_loc5`='我用祖先傳下來的方法訓練獵人。', `FemaleText_loc7`='Instruyo a los cazadores en las artes y tradiciones de nuestros ancestros.' WHERE `ID`=7520;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련을 받고 싶습니다.', `MaleText_loc4`='我需要培训。', `MaleText_loc5`='我需要培訓。', `MaleText_loc7`='Necesito instrucción.', `FemaleText_loc1`='훈련을 받고 싶습니다.', `FemaleText_loc4`='我需要培训。', `FemaleText_loc5`='我需要培訓。', `FemaleText_loc7`='Necesito instrucción.' WHERE `ID`=7521;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타우렌은 사냥에 대한 열정이 대단하지. 우리 종족은 사냥에 뛰어난 재능을 타고났소.', `MaleText_loc4`='牛头人热衷于狩猎，这是流淌在我们血液中的灵魂。', `MaleText_loc5`='牛頭人熱衷於狩獵，這是流淌在我們血液中的靈魂。', `MaleText_loc7`='Los tauren tienen auténtica pasión por la caza, tiene unas raíces muy profundas entre nosotros.', `FemaleText_loc1`='타우렌은 사냥에 대한 열정이 대단하지요. 우리 종족은 사냥에 뛰어난 재능을 타고났습니다.', `FemaleText_loc4`='牛头人热衷于狩猎，这是流淌在我们血液中的灵魂。', `FemaleText_loc5`='牛頭人熱衷於狩獵，這是流淌在我們血液中的靈魂。', `FemaleText_loc7`='Los tauren tienen auténtica pasión por la caza, tiene unas raíces muy profundas entre nosotros.' WHERE `ID`=7522;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사냥꾼 훈련을 받고 싶습니다.', `MaleText_loc4`='我是一名猎人，我想接受训练。', `MaleText_loc5`='我是一名獵人，我想接受訓練。', `MaleText_loc7`='Soy cazador y deseo instruirme.', `FemaleText_loc1`='사냥꾼 훈련을 받고 싶습니다.', `FemaleText_loc4`='我是一名猎人，我想接受训练。', `FemaleText_loc5`='我是一名獵人，我想接受訓練。', `FemaleText_loc7`='Soy cazadora y deseo instruirme.' WHERE `ID`=7523;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왕립 연금술 학회는 어리석은 자를 기다려 주지 않는다. 나 또한 마찬가지고. 어쩌면 다음에 자네가 언더시티의 친구로 인정을 받으면, 내가 타고 다니는 멋진 놈에 대한 대화를 나눌 수도 있겠지. 그럼 그때까지 잘 지내도록.', `MaleText_loc4`='皇家药剂师协会对愚蠢的家伙没有耐心，我也一样。或许下次我们谈到战马的时候，你与幽暗城的关系已经到了友善的地步。否则的话……', `MaleText_loc5`='皇家藥劑師學會對愚蠢的傢伙沒有耐心，我也一樣。或許下次我們談到戰馬的時候，你與幽暗城的關係已經到了友善的地步。否則的話...', `MaleText_loc7`='La Sociedad Real de Boticarios tiene poca paciencia con los necios, y yo también. Quizás la próxima vez que hablemos sobre mis corceles, ya tendrás reputación de $gamistoso:amistosa; en Entrañas. Hasta entonces...', `FemaleText_loc1`='왕립 연금술 학회는 어리석은 자를 기다려 주지 않는다. 나 또한 마찬가지고. 어쩌면 다음에 자네가 언더시티의 친구로 인정을 받으면, 내가 타고 다니는 멋진 놈에 대한 대화를 나눌 수도 있겠지. 그럼 그때까지 잘 지내도록.', `FemaleText_loc4`='皇家药剂师协会对愚蠢的家伙没有耐心，我也一样。或许下次我们谈到战马的时候，你与幽暗城的关系已经到了友善的地步。否则的话……', `FemaleText_loc5`='皇家藥劑師學會對愚蠢的傢伙沒有耐心，我也一樣。或許下次我們談到戰馬的時候，你與幽暗城的關係已經到了友善的地步。否則的話...', `FemaleText_loc7`='La Sociedad Real de Boticarios tiene poca paciencia con los necios, y yo también. Quizás la próxima vez que hablemos sobre mis corceles, ya tendrás reputación de $gamistoso:amistosa; en Entrañas. Hasta entonces...' WHERE `ID`=7524;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왕립 연금술 학회를 대표해서 우리 포세이큰의 동지에게 최고로 훌륭한 탈것을 제공하게 되어 기쁘군. 우리는 이놈들을 고된 훈련을 통해서 더 강하게 길렀지. 직접 살펴보면서 확인하게.', `MaleText_loc4`='很高兴我能代表皇家药剂师协会为你提供最好的战马。这些战马与我们一样经历过考验和磨难，现在它们已经远胜于那些血肉之躯所铸成的战马了，它们更为强壮，更易恢复精力！好好看看它们吧。', `MaleText_loc5`='很高興我能代表皇家藥劑師學會為你提供被遺忘者最好的戰馬。這些戰馬與我們一樣經歷過考驗和磨難，現在它們已經遠勝於那些血肉之軀所鑄成的戰馬了，它們更為強壯，更易恢復精力!好好看看它們吧。', `MaleText_loc7`='En nombre de la Sociedad Real de Boticarios, me complace ofrecerte los mejores corceles a disposición de los Renegados. Estas bestias han sufrido las mismas pruebas y tribulaciones que nosotros ¡y ahora han emergido más fuertes y resistentes de lo que les hubiera estado destinado por la simple carne mortal! Por favor, examínalos por ti $gmismo:misma; y lo verás.', `FemaleText_loc1`='왕립 연금술 학회를 대표해서 우리 포세이큰의 동지에게 최고로 훌륭한 탈것을 제공하게 되어 기쁘군. 우리는 이놈들을 고된 훈련을 통해서 더 강하게 길렀지. 직접 살펴보면서 확인하게.', `FemaleText_loc4`='很高兴我能代表皇家药剂师协会为你提供最好的战马。这些战马与我们一样经历过考验和磨难，现在它们已经远胜于那些血肉之躯所铸成的战马了，它们更为强壮，更易恢复精力！好好看看它们吧。', `FemaleText_loc5`='很高興我能代表皇家藥劑師學會為你提供被遺忘者最好的戰馬。這些戰馬與我們一樣經歷過考驗和磨難，現在它們已經遠勝於那些血肉之軀所鑄成的戰馬了，它們更為強壯，更易恢復精力!好好看看它們吧。', `FemaleText_loc7`='En nombre de la Sociedad Real de Boticarios, me complace ofrecerte los mejores corceles a disposición de los Renegados. Estas bestias han sufrido las mismas pruebas y tribulaciones que nosotros ¡y ahora han emergido más fuertes y resistentes de lo que les hubiera estado destinado por la simple carne mortal! Por favor, examínalos por ti $gmismo:misma; y lo verás.' WHERE `ID`=7525;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사냥꾼의 길에 대해 배우십시오. 긍지, 명예, 그리고 전통에 대해서 말입니다.', `MaleText_loc4`='来学习猎人之道吧。骄傲，荣誉，还有传统。', `MaleText_loc5`='來學習獵人之道吧。驕傲，榮譽，還有傳統。', `MaleText_loc7`='Ven a aprender las artes del cazador. Orgullo, honor y tradición.', `FemaleText_loc1`='사냥꾼의 길에 대해 배우시오. 긍지, 명예, 그리고 전통에 대해서 말이오.', `FemaleText_loc4`='来学习猎人之道吧。骄傲，荣誉，还有传统。', `FemaleText_loc5`='來學習獵人之道吧。驕傲，榮譽，還有傳統。', `FemaleText_loc7`='Ven a aprender las artes del cazador. Orgullo, honor y tradición.' WHERE `ID`=7526;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뛰어난 산양 기수가 되는 법을 가르쳐 주겠어요. 단 수업료로 낼 골드만 충분하다면 말이죠!', `MaleText_loc4`='我可以教你骑山羊的技巧，只要你有足够的金币支付学费！', `MaleText_loc5`='我可以教你騎山羊的技巧，只要你有足夠的金幣支付學費!', `MaleText_loc7`='Puedo enseñarte los mejores trucos para montar un carnero, ¡siempre que tengas suficiente oro para pagar la lección!', `FemaleText_loc1`='뛰어난 산양 기수가 되는 법을 가르쳐 주겠어요. 단 수업료로 낼 골드만 충분하다면 말이죠!', `FemaleText_loc4`='我可以教你骑山羊的技巧，只要你有足够的金币支付学费！', `FemaleText_loc5`='我可以教你騎山羊的技巧，只要你有足夠的金幣支付學費!', `FemaleText_loc7`='Puedo enseñarte los mejores trucos para montar un carnero, ¡siempre que tengas suficiente oro para pagar la lección!' WHERE `ID`=7527;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련을 받고 싶습니다.', `MaleText_loc4`='我想接受训练。', `MaleText_loc5`='我想接受訓練。', `MaleText_loc7`='Me gustaría instruirme.', `FemaleText_loc1`='훈련을 받고 싶습니다.', `FemaleText_loc4`='我想接受训练。', `FemaleText_loc5`='我想接受訓練。', `FemaleText_loc7`='Me gustaría instruirme.' WHERE `ID`=7528;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 여러 세대를 거쳐 내려온 전통적인 방법으로 젊은 사냥꾼들을 가르치고 있소.', `MaleText_loc4`='我按照传统一代代地训练、指导年轻猎人。', `MaleText_loc5`='我按照一代代的傳統來訓練、指導年輕獵人。', `MaleText_loc7`='Instruyo y guío a los jóvenes cazadores en las tradiciones transmitidas a través de muchas generaciones.', `FemaleText_loc1`='전 여러 세대를 거쳐 내려온 전통적인 방법으로 젊은 사냥꾼들을 가르치고 있습니다.', `FemaleText_loc4`='我按照传统一代代地训练、指导年轻猎人。', `FemaleText_loc5`='我按照一代代的傳統來訓練、指導年輕獵人。', `FemaleText_loc7`='Instruyo y guío a los jóvenes cazadores en las tradiciones transmitidas a través de muchas generaciones.' WHERE `ID`=7529;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 기계타조 조종법을 가르쳐 줄 수 있어요. 손에 몇 골드나 쥐었는지 한번 짤랑거려 보세요. 헤헤... 수업료가 충분한지 궁금해서요.', `MaleText_loc4`='我可以教你操纵机械陆行鸟的技巧，只要你有足够的金币支付学费！', `MaleText_loc5`='我可以教你操縱機械陸行鳥的技巧，只要你有足夠的金幣支付學費!', `MaleText_loc7`='Puedo enseñarte los mejores trucos para pilotar mecazancudos, ¡siempre que tengas suficiente oro para pagar la lección!', `FemaleText_loc1`='제가 기계타조 조종법을 가르쳐 줄 수 있어요. 손에 몇 골드나 쥐었는지 한번 짤랑거려 보세요. 헤헤... 수업료가 충분한지 궁금해서요.', `FemaleText_loc4`='我可以教你操纵机械陆行鸟的技巧，只要你有足够的金币支付学费！', `FemaleText_loc5`='我可以教你操縱機械陸行鳥的技巧，只要你有足夠的金幣支付學費!', `FemaleText_loc7`='Puedo enseñarte los mejores trucos para pilotar mecazancudos, ¡siempre que tengas suficiente oro para pagar la lección!' WHERE `ID`=7530;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뛰어난 승마 기술을 가르쳐 드리겠습니다. 단, 수업료는 제대로 내셔야 합니다!', `MaleText_loc4`='我可以教你骑马的技巧，只要你有足够的金币支付学费！', `MaleText_loc5`='我可以教你騎馬的技巧，只要你有足夠的金幣支付學費!', `MaleText_loc7`='Puedo enseñarte los mejores trucos para montar a caballo, ¡siempre que tengas suficiente oro para pagar la lección!', `FemaleText_loc1`='뛰어난 승마 기술을 가르쳐 드리겠습니다. 단, 수업료는 제대로 내셔야 합니다!', `FemaleText_loc4`='我可以教你骑马的技巧，只要你有足够的金币支付学费！', `FemaleText_loc5`='我可以教你騎馬的技巧，只要你有足夠的金幣支付學費!', `FemaleText_loc7`='Puedo enseñarte los mejores trucos para montar a caballo, ¡siempre que tengas suficiente oro para pagar la lección!' WHERE `ID`=7531;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대에게 뛰어난 호랑이 기수가 되는 방법을 가르쳐 드리겠습니다. 그런데 수업료로 낼 골드는 충분한가요?!', `MaleText_loc4`='我可以教你骑豹的技巧，只要你有足够的金币支付学费！', `MaleText_loc5`='我可以教你騎豹的技巧，只要你有足夠的金幣支付學費!', `MaleText_loc7`='Puedo enseñarte los mejores trucos para montar un tigre, ¡siempre que tengas suficiente oro para pagar la lección!', `FemaleText_loc1`='그대에게 뛰어난 호랑이 기수가 되는 방법을 가르쳐 드리겠습니다. 그런데 수업료로 낼 골드는 충분한가요?!', `FemaleText_loc4`='我可以教你骑豹的技巧，只要你有足够的金币支付学费！', `FemaleText_loc5`='我可以教你騎豹的技巧，只要你有足夠的金幣支付學費!', `FemaleText_loc7`='Puedo enseñarte los mejores trucos para montar un tigre, ¡siempre que tengas suficiente oro para pagar la lección!' WHERE `ID`=7532;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뛰어난 코도 기수가 될 수 있도록 제가 알고 있는 모든 기술을 전수해 드리겠습니다. 단, 수업료는 내셔야 합니다!', `MaleText_loc4`='我可以教你骑科多兽的技巧，只要你有足够的金币支付学费！', `MaleText_loc5`='我可以教你騎科多獸的技巧，只要你有足夠的金幣支付學費!', `MaleText_loc7`='Puedo enseñarte los mejores trucos para montar un kodo, ¡siempre que tengas suficiente oro para pagar la lección!', `FemaleText_loc1`='뛰어난 코도 기수가 될 수 있도록 제가 알고 있는 모든 기술을 전수해 드리겠습니다. 단, 수업료는 내셔야 합니다!', `FemaleText_loc4`='我可以教你骑科多兽的技巧，只要你有足够的金币支付学费！', `FemaleText_loc5`='我可以教你騎科多獸的技巧，只要你有足夠的金幣支付學費!', `FemaleText_loc7`='Puedo enseñarte los mejores trucos para montar un kodo, ¡siempre que tengas suficiente oro para pagar la lección!' WHERE `ID`=7533;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뛰어난 랩터 기수가 되는 법을 가르쳐 드리겠습니다. 그런데 수업료로 낼 골드는 충분하겠지요?!', `MaleText_loc4`='我可以教你骑迅猛龙的技巧，只要你有足够的金币支付学费！', `MaleText_loc5`='我可以教你騎迅猛龍的技巧，只要你有足夠的金幣支付學費!', `MaleText_loc7`='Puedo enseñarte los mejores trucos para montar un raptor, ¡siempre que tengas suficiente oro para pagar la lección!', `FemaleText_loc1`='뛰어난 랩터 기수가 되는 법을 가르쳐 드리겠습니다. 그런데 수업료로 낼 골드는 충분하겠지요?!', `FemaleText_loc4`='我可以教你骑迅猛龙的技巧，只要你有足够的金币支付学费！', `FemaleText_loc5`='我可以教你騎迅猛龍的技巧，只要你有足夠的金幣支付學費!', `FemaleText_loc7`='Puedo enseñarte los mejores trucos para montar un raptor, ¡siempre que tengas suficiente oro para pagar la lección!' WHERE `ID`=7534;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뛰어난 해골마 기수가 되는 법을 가르쳐 주지. 그런데 자네... 수업료는 충분한가?!', `MaleText_loc4`='我可以教你骑骸骨战马的技巧，只要你有足够的金币支付学费！', `MaleText_loc5`='我可以教你騎骸骨戰馬的技巧，只要你有足夠的金幣支付學費!', `MaleText_loc7`='Puedo enseñarte los mejores trucos para montar un caballo esquelético, ¡siempre que tengas suficiente oro para pagar la lección!', `FemaleText_loc1`='뛰어난 해골마 기수가 되는 법을 가르쳐 주지. 그런데 자네... 수업료는 충분한가?!', `FemaleText_loc4`='我可以教你骑骸骨战马的技巧，只要你有足够的金币支付学费！', `FemaleText_loc5`='我可以教你騎骸骨戰馬的技巧，只要你有足夠的金幣支付學費!', `FemaleText_loc7`='Puedo enseñarte los mejores trucos para montar un caballo esquelético, ¡siempre que tengas suficiente oro para pagar la lección!' WHERE `ID`=7535;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뛰어난 늑대 기수가 되는 법을 가르쳐 주겠소. 단, 수업료만 충분하다면!', `MaleText_loc4`='我可以教你骑狼的技巧，只要你有足够的金币支付学费！', `MaleText_loc5`='我可以教你騎狼的技巧，只要你有足夠的金幣支付學費!', `MaleText_loc7`='Puedo enseñarte los mejores trucos para montar un lobo, ¡siempre que tengas suficiente oro para pagar la lección!', `FemaleText_loc1`='뛰어난 늑대 기수가 되는 법을 가르쳐 주겠소. 단, 수업료만 충분하다면!', `FemaleText_loc4`='我可以教你骑狼的技巧，只要你有足够的金币支付学费！', `FemaleText_loc5`='我可以教你騎狼的技巧，只要你有足夠的金幣支付學費!', `FemaleText_loc7`='Puedo enseñarte los mejores trucos para montar un lobo, ¡siempre que tengas suficiente oro para pagar la lección!' WHERE `ID`=7536;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 산양 기수가 되려는 $C|1이;가; 도착했군. 하지만, 먼저 아이언포지 드워프들과 친분을 쌓아야 할 거야...', `MaleText_loc4`='在我教你骑术之前，你必须与铁炉堡的矮人达到友善关系，$c。', `MaleText_loc5`='在我教你騎術之前，你必須與鐵爐堡的矮人達到友好的聲望才行，$c。', `MaleText_loc7`='Es necesario que los enanos de Forjaz te consideren $gamistoso:amistosa; para que te pueda enseñar la habilidad de equitación, $c.', `FemaleText_loc1`='여기 산양 기수가 되려는 $C|1이;가; 도착했군. 하지만, 먼저 아이언포지 드워프들과 친분을 쌓아야 할 거야...', `FemaleText_loc4`='在我教你骑术之前，你必须与铁炉堡的矮人达到友善关系，$c。', `FemaleText_loc5`='在我教你騎術之前，你必須與鐵爐堡的矮人達到友好的聲望才行，$c。', `FemaleText_loc7`='Es necesario que los enanos de Forjaz te consideren $gamistoso:amistosa; para que te pueda enseñar la habilidad de equitación, $c.' WHERE `ID`=7537;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$C, 늑대를 타고 싶소? 먼저 오그리마 오크들과 친분을 쌓아야 할 거요.', `MaleText_loc4`='在我教你骑术之前，你必须与奥格瑞玛的兽人达到友善关系，$c。', `MaleText_loc5`='在我教你騎術之前，你必須與奧格瑪的獸人達到友好的聲望才行，$c。', `MaleText_loc7`='Es necesario que los orcos de Orgrimmar te consideren $gamistoso:amistosa; para que te pueda enseñar la habilidad de equitación, $c.', `FemaleText_loc1`='$C, 늑대를 타고 싶소? 먼저 오그리마 오크들과 친분을 쌓아야 할 거요.', `FemaleText_loc4`='在我教你骑术之前，你必须与奥格瑞玛的兽人达到友善关系，$c。', `FemaleText_loc5`='在我教你騎術之前，你必須與奧格瑪的獸人達到友好的聲望才行，$c。', `FemaleText_loc7`='Es necesario que los orcos de Orgrimmar te consideren $gamistoso:amistosa; para que te pueda enseñar la habilidad de equitación, $c.' WHERE `ID`=7538;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$C|1이여;여;, 랩터 타는 법을 배우려면 검은창 트롤과 친분을 쌓아야 합니다.', `MaleText_loc4`='在我教你骑术之前，你必须与暗矛部族的巨魔达到友善关系，$c。', `MaleText_loc5`='在我教你騎術之前，你必須與暗矛部族的食人妖達到友好的聲望才行，$c。', `MaleText_loc7`='Es necesario que los trols Lanza Negra te consideren $gamistoso:amistosa; para que te pueda enseñar la habilidad de equitación, $c.', `FemaleText_loc1`='$C|1이여;여;, 랩터 타는 법을 배우려면 검은창 트롤과 친분을 쌓아야 합니다.', `FemaleText_loc4`='在我教你骑术之前，你必须与暗矛部族的巨魔达到友善关系，$c。', `FemaleText_loc5`='在我教你騎術之前，你必須與暗矛部族的食人妖達到友好的聲望才行，$c。', `FemaleText_loc7`='Es necesario que los trols Lanza Negra te consideren $gamistoso:amistosa; para que te pueda enseñar la habilidad de equitación, $c.' WHERE `ID`=7539;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 고마워요. 이제 여기를 빠져나가자고요!', `FemaleText_loc4`='谢谢你，$n。现在让我们离开这儿！', `FemaleText_loc5`='謝謝你，$n。現在讓我們離開這兒!', `FemaleText_loc7`='Gracias, $n. ¡Ahora salgamos de aquí!' WHERE `ID`=7540;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$C|1이여;여;, 코도 타는 법을 배우려면 썬더 블러프 타우렌들과 친분을 쌓아야 하네.', `MaleText_loc4`='在我教你骑术之前，你必须与雷霆崖的牛头人达到友善关系，$c。', `MaleText_loc5`='在我教你騎術之前，你必須與雷霆崖的牛頭人達到友好的聲望才行，$c。', `MaleText_loc7`='Es necesario que los tauren de Cima del Trueno te consideren $gamistoso:amistosa; para que te pueda enseñar la habilidad de equitación, $c.', `FemaleText_loc1`='$C|1이여;여;, 코도 타는 법을 배우려면 썬더 블러프 타우렌들과 친분을 쌓아야 하네.', `FemaleText_loc4`='在我教你骑术之前，你必须与雷霆崖的牛头人达到友善关系，$c。', `FemaleText_loc5`='在我教你騎術之前，你必須與雷霆崖的牛頭人達到友好的聲望才行，$c。', `FemaleText_loc7`='Es necesario que los tauren de Cima del Trueno te consideren $gamistoso:amistosa; para que te pueda enseñar la habilidad de equitación, $c.' WHERE `ID`=7541;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$C|1이여;여;, 말 타는 법을 배우고 싶습니까? 먼저 스톰윈드 인간들과 친분을 쌓아야 합니다.', `MaleText_loc4`='在我教你骑术之前，你必须与暴风城的人类达到友善关系，$c。', `MaleText_loc5`='在我教你騎術之前，你必須與暴風城的人類達到友好的聲望才行，$c。', `MaleText_loc7`='Es necesario que los humanos de Ventormenta te consideren $gamistoso:amistosa; para que te pueda enseñar la habilidad de equitación, $c.', `FemaleText_loc1`='$C|1이여;여;, 말 타는 법을 배우고 싶습니까? 먼저 스톰윈드 인간들과 친분을 쌓아야 합니다.', `FemaleText_loc4`='在我教你骑术之前，你必须与暴风城的人类达到友善关系，$c。', `FemaleText_loc5`='在我教你騎術之前，你必須與暴風城的人類達到友好的聲望才行，$c。', `FemaleText_loc7`='Es necesario que los humanos de Ventormenta te consideren $gamistoso:amistosa; para que te pueda enseñar la habilidad de equitación, $c.' WHERE `ID`=7542;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$C|1이여;여;, 호랑이 타는 법을 배우려면 먼저 다르나서스 나이트 엘프들과 친분을 쌓아야 합니다.', `MaleText_loc4`='在我教你骑术之前，你必须与达纳苏斯的暗夜精灵达到友善关系，$c。', `MaleText_loc5`='在我教你騎術之前，你必須與達納蘇斯的夜精靈達到友好的聲望才行，$c。', `MaleText_loc7`='Es necesario que los elfos de la noche de Darnassus te consideren $gamistoso:amistosa; para que te pueda enseñar la habilidad de equitación, $c.', `FemaleText_loc1`='$C|1이여;여;, 호랑이 타는 법을 배우려면 먼저 다르나서스 나이트 엘프들과 친분을 쌓아야 합니다.', `FemaleText_loc4`='在我教你骑术之前，你必须与达纳苏斯的暗夜精灵达到友善关系，$c。', `FemaleText_loc5`='在我教你騎術之前，你必須與達納蘇斯的夜精靈達到友好的聲望才行，$c。', `FemaleText_loc7`='Es necesario que los elfos de la noche de Darnassus te consideren $gamistoso:amistosa; para que te pueda enseñar la habilidad de equitación, $c.' WHERE `ID`=7543;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='해냈군요! 정말 고마워요! 먼저 갈게요!', `FemaleText_loc4`='我们成功了！再次感谢你！我先走了！', `FemaleText_loc5`='我們成功了!再次感謝你!我先走了!', `FemaleText_loc7`='¡Lo logramos! ¡Gracias de nuevo! ¡Yo iré delante!' WHERE `ID`=7544;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$C|1이여;여;, 기계타조 조종법을 배우려면 먼저 놈리건에서 피난 온 노움들과 친해져야 해요.', `MaleText_loc4`='在我教你如何驾驭机械陆行鸟之前，你必须与诺莫瑞根的侏儒们达到友善关系，$c。', `MaleText_loc5`='在我教你如何駕馭機械陸行鳥之前，你必須與諾姆瑞根流亡者的地精達到友好的聲望才行，$c。', `MaleText_loc7`='Es necesario que los gnomos de los Exiliados de Gnomeregan te consideren $gamistoso:amistosa; para que te pueda enseñar a pilotar un mecazancudo, $c.', `FemaleText_loc1`='$C|1이여;여;, 기계타조 조종법을 배우려면 먼저 놈리건에서 피난 온 노움들과 친해져야 해요.', `FemaleText_loc4`='在我教你如何驾驭机械陆行鸟之前，你必须与诺莫瑞根的侏儒们达到友善关系，$c。', `FemaleText_loc5`='在我教你如何?馭機械陸行鳥之前，你必須與諾姆瑞根流亡者的地精達到友好的聲望才行，$c。', `FemaleText_loc7`='Es necesario que los gnomos de los Exiliados de Gnomeregan te consideren $gamistoso:amistosa; para que te pueda enseñar a pilotar un mecazancudo, $c.' WHERE `ID`=7545;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$C, 해골마 타는 법을 배우려면 먼저 언더시티 포세이큰들과 친분을 쌓아야만 해!', `MaleText_loc4`='在我教你骑术之前，你必须与幽暗城的被遗忘者达到友善关系，$c。', `MaleText_loc5`='在我教你騎術之前，你必須與幽暗城的被遺忘者達到友好的聲望才行，$c。', `MaleText_loc7`='Es necesario que los Renegados de Entrañas te consideren $gamistoso:amistosa; para que te pueda enseñar la habilidad de equitación, $c.', `FemaleText_loc1`='$C, 해골마 타는 법을 배우려면 먼저 언더시티 포세이큰들과 친분을 쌓아야만 해!', `FemaleText_loc4`='在我教你骑术之前，你必须与幽暗城的被遗忘者达到友善关系，$c。', `FemaleText_loc5`='在我教你騎術之前，你必須與幽暗城的被遺忘者達到友好的聲望才行，$c。', `FemaleText_loc7`='Es necesario que los Renegados de Entrañas te consideren $gamistoso:amistosa; para que te pueda enseñar la habilidad de equitación, $c.' WHERE `ID`=7546;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신에게 기계타조 조종법을 가르쳐 봤자 돈 낭비에, 시간 낭비예요. 당신은 너무 크시잖아요!', `MaleText_loc4`='要教你学会驾驶机械陆行鸟，那简直就是在浪费我的金钱和时间，$c。你的体形太庞大了！', `MaleText_loc5`='要教你學會駕駛機械陸行鳥，那簡直就是在浪費我的金錢和時間，$c。你的體形太龐大了!', `MaleText_loc7`='Si te enseñara a pilotar un mecazancudo estaría perdiendo mi oro y mi tiempo, $c. ¡Eres demasiado grande!', `FemaleText_loc1`='당신에게 기계타조 조종법을 가르쳐 봤자 돈 낭비에, 시간 낭비예요. 당신은 너무 크시잖아요!', `FemaleText_loc4`='要教你学会驾驶机械陆行鸟，那简直就是在浪费我的金钱和时间，$c。你的体形太庞大了！', `FemaleText_loc5`='要教你學會駕駛機械陸行鳥，那簡直就是在浪費我的金錢和時間，$c。你的體形太龐大了!', `FemaleText_loc7`='Si te enseñara a pilotar un mecazancudo estaría perdiendo mi oro y mi tiempo, $c. ¡Eres demasiado grande!' WHERE `ID`=7547;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탈것에 오르는 기술을 배우고 싶습니다.', `MaleText_loc4`='我想接受骑术训练。', `MaleText_loc5`='我想接受騎術訓練。', `MaleText_loc7`='Quiero aprender a montar un corcel.', `FemaleText_loc1`='탈것에 오르는 기술을 배우고 싶어요.', `FemaleText_loc4`='我想接受骑术训练。', `FemaleText_loc5`='我想接受騎術訓練。', `FemaleText_loc7`='Quiero aprender a montar un corcel.' WHERE `ID`=7548;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련을 받고 싶습니다.', `MaleText_loc4`='请训练我吧。', `MaleText_loc5`='請訓練我吧。', `MaleText_loc7`='Por favor, instrúyeme.', `FemaleText_loc1`='훈련을 받고 싶습니다.', `FemaleText_loc4`='请训练我吧。', `FemaleText_loc5`='請訓練我吧。', `FemaleText_loc7`='Por favor, instrúyeme.' WHERE `ID`=7549;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='호르니즈! 나 돌아왔어! 날 도와주신 분도 곧 여기 올 거야.', `FemaleText_loc4`='嗨，霍恩尼兹！我回来了！有些好心人帮我脱离了困境。', `FemaleText_loc5`='嗨，霍恩尼茲!我回來了!有些好心人幫我脫離了困境。', `FemaleText_loc7`='¡Eh Hornizz! ¡He vuelto! Los que vienen detrás de mí me ayudaron a salir de un aprieto.' WHERE `ID`=7550;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 장부에서 마라우돈 일족은 지워야겠어. 거래를 할 수가 있어야지, 원...', `FemaleText_loc4`='我们不得不把玛洛迪半人马从我们的合作伙伴列表中划掉。他们太难共事了……', `FemaleText_loc5`='我們不得不把瑪洛迪半人馬從我們的合作夥伴列表中劃掉。他們太難共事了...', `FemaleText_loc7`='Vamos a tener que borrar a los Maraudines de nuestra lista. Es difícil trabajar con ellos...' WHERE `ID`=7551;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='겔키스 쪽에 가봐야겠어. 마라우돈 일족만큼 멍청하지도 않고 분별력도 있는 편이잖아.', `FemaleText_loc4`='好吧，我要到吉尔吉斯村去了。他们不像玛洛迪半人马一样蠢，而且他们更加通情达理。', `FemaleText_loc5`='好吧，我要到吉爾吉斯村去了。他們不像瑪洛迪半人馬一樣蠢，而且他們更加通情達理。', `FemaleText_loc7`='Bueno, me voy con los Gelkis. No son tan tontos como los Maraudines, pero son más razonables.' WHERE `ID`=7552;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 잘 가! 다음에는 더 잘해보라고!', `MaleText_loc4`='再见！祝你下次好运！', `MaleText_loc5`='再見!祝你下次好運!', `MaleText_loc7`='¡Adiós! ¡Que tengas más suerte otra vez!' WHERE `ID`=7553;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쟤는 항상 바쁘다니까...', `MaleText_loc4`='那个女孩总是忙个不停。', `MaleText_loc5`='那個女孩總是忙個不停。', `MaleText_loc7`='Esa chica, no para nunca.' WHERE `ID`=7554;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 세계의 모든 것이 연관되어 있다는 것을 잊지 마시오. 만일 이 대지에 짐승들이 사라진다면 우리 종족은 영혼이 메말라 죽어버릴 것이오. 짐승들에게 무슨 일이 생긴다면 우리 타우렌도 결코 무사할 수 없소. 아제로스의 대지와 그곳에 사는 생명들은 운명을 같이하는 법이지.', `MaleText_loc4`='记住，所有的事物都是有关联的。如果陆地上的野兽灭绝，我们的种族将在孤独中死去，因为牛头人和野兽的命运是相通的，而艾泽拉斯的命运和所有艾泽拉斯上的生灵的命运也休戚相关。', `MaleText_loc5`='記住，所有的事物都是有關聯的。如果陸地上的野獸滅絕，我們的種族將在孤獨中死去，因為牛頭人和野獸的命運是相通的，而艾澤拉斯的命運也和艾澤拉斯上所有生靈的命運休戚相關。', `MaleText_loc7`='Recuerda, todo está conectado. Si las bestias abandonaran esta tierra, nuestra clase moriría consumida por la soledad de espíritu, cualquier cosa que le suceda a las bestias, le sucede también a los tauren. Cualquier cosa que suceda en Azeroth le sucede también a quienes lo habitan.', `FemaleText_loc1`='이 세계의 모든 것이 연관되어 있다는 것을 잊지 마세요. 만일 이 대지에 짐승들이 사라진다면 우리 종족은 영혼이 메말라 죽어버릴 것입니다. 짐승들에게 무슨 일이 생긴다면 우리 타우렌도 결코 무사할 수 없지요. 아제로스의 대지와 그곳에 사는 생명들은 운명을 같이하는 법이니까요.', `FemaleText_loc4`='记住，所有的事物都是有关联的。如果陆地上的野兽灭绝，我们的种族将在孤独中死去，因为牛头人和野兽的命运是相通的，而艾泽拉斯的命运和所有艾泽拉斯上的生灵的命运也休戚相关。', `FemaleText_loc5`='記住，所有的事物都是有關聯的。如果陸地上的野獸滅絕，我們的種族將在孤獨中死去，因為牛頭人和野獸的命運是相通的，而艾澤拉斯的命運也和艾澤拉斯上所有生靈的命運休戚相關。', `FemaleText_loc7`='Recuerda, todo está conectado. Si las bestias abandonaran esta tierra, nuestra clase moriría consumida por la soledad de espíritu, cualquier cosa que le suceda a las bestias, le sucede también a los tauren. Cualquier cosa que suceda en Azeroth le sucede también a quienes lo habitan.' WHERE `ID`=7555;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련을 받고 싶습니다.', `MaleText_loc4`='我想接受训练。', `MaleText_loc5`='我想接受訓練。', `MaleText_loc7`='Deseo instruirme.', `FemaleText_loc1`='훈련을 받고 싶습니다.', `FemaleText_loc4`='我想接受训练。', `FemaleText_loc5`='我想接受訓練。', `FemaleText_loc7`='Deseo instruirme.' WHERE `ID`=7556;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사냥 전략을 배우러 왔다면 제대로 찾아왔네!', `MaleText_loc4`='如果你是来接受狩猎技巧训练的，那你就来对地方了！', `MaleText_loc5`='如果你是來接受狩獵技巧訓練的，那你就來對地方了!', `MaleText_loc7`='Si estás aquí para recibir instrucción en las tácticas y en la estrategia de la caza, ¡has venido al lugar correcto!', `FemaleText_loc1`='사냥 전략을 배우러 왔다면 제대로 찾아오셨습니다!', `FemaleText_loc4`='如果你是来接受狩猎技巧训练的，那你就来对地方了！', `FemaleText_loc5`='如果你是來接受狩獵技巧訓練的，那你就來對地方了!', `FemaleText_loc7`='Si estás aquí para recibir instrucción en las tácticas y en la estrategia de la caza, ¡has venido al lugar correcto!' WHERE `ID`=7557;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련을 받으러 왔습니다.', `MaleText_loc4`='我准备接受训练。', `MaleText_loc5`='我準備接受訓練。', `MaleText_loc7`='He venido para recibir instrucción.', `FemaleText_loc1`='훈련을 받으러 왔습니다.', `FemaleText_loc4`='我准备接受训练。', `FemaleText_loc5`='我準備接受訓練。', `FemaleText_loc7`='He venido para recibir instrucción.' WHERE `ID`=7558;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어이! 바다 깊숙이 잠수해본 적 있나? 내가 비밀 하나 알려줌세. 물속으로 깊이 들어가면 거품 균열이 있네. 그 근처에 있으면, 물속에서도 숨을 쉴 수 있지. 이건 우리끼리만 알고 있자고, 알았나? 가재 잡는 데 경쟁자가 생기는 건 싫으니까 말일세. 무슨 말인지 알겠지?!', `MaleText_loc4`='嗨！?从来没有过深海潜水的经历吗？我告诉你一个小秘诀，嗯。在海洋深处有许多冒气泡的裂缝，当你在水下时可利用这些气泡进行呼吸。这个秘密只限于你我之间。对我来说，贝壳到处都是……如果你懂我的意思的话！', `MaleText_loc5`='嗨!你從來沒有過深海潛水的經歷嗎?我告訴你一個小秘訣，嗯。在海洋深處有許多冒氣泡的裂縫，當你在水下時可利用這些氣泡進行呼吸。這個秘密只限於你我之間。對我來說，貝殼到處都是...如果你懂我的意思的話!', `MaleText_loc7`='¡Eh, colega! ¿Has buceado alguna vez en las profundidades del océano? Te contaré un secretillo, eh. En las profundidades del mar puedes encontrar fisuras burbujeantes; con ellas podrás respirar bajo el agua. Pero que este secreto quede entre tú y yo, eh. No me hace falta competencia para mis trampas de marisco... ¡supongo que me entiendes!' WHERE `ID`=7559;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이럴 수가! 그만! 제발 그만! 내가 졌다! 내가 졌어!', `MaleText_loc4`='不……不可能！等一下……我投降！我投降！', `MaleText_loc5`='不...不可能!等一下...我投降!我投降!', `MaleText_loc7`='¡Imposible! Cancelen el ataque mortales... ¡Me rindo! ¡Me rindo!' WHERE `ID`=7561;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='매의 날개가 펄럭거리는 소리, 눈발이 날리는 가운데 들리는 산양의 숨소리, 숲 속에서 들려오는 곰 발걸음 소리... 바로 이런 것이야말로 사냥꾼의 인생이지요.', `FemaleText_loc4`='老鹰翅膀的扇动，雪地里山羊的喘息，熊穿过森林的脚步……这就是猎人的生活。', `FemaleText_loc5`='老鷹翅膀的扇動，雪地裡山羊的喘息，熊穿過森林的腳步...這就是獵人的生活。', `FemaleText_loc7`='El batir de las alas de un halcón, el aliento de un carnero en la nieve, los pasos de un oso a través del bosque... Así es la vida del cazador.' WHERE `ID`=7562;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련을 받고 싶습니다.', `MaleText_loc4`='我要接受训练。', `MaleText_loc5`='我要接受訓練。', `MaleText_loc7`='Me gustaría recibir instrucción.', `FemaleText_loc1`='훈련을 받고 싶습니다.', `FemaleText_loc4`='我要接受训练。', `FemaleText_loc5`='我要接受訓練。', `FemaleText_loc7`='Me gustaría recibir instrucción.' WHERE `ID`=7563;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신도 짐승들의 지혜와 경험을 깨닫게 될 것입니다. 올빼미와 같은 부리부리한 눈으로 세계를 관찰하고, 퓨마의 영리함을 배우고, 늑대의 강인한 정신을 본받으십시오.', `FemaleText_loc4`='看看野兽们的智慧和知识，你就会看到你自己。像猫头鹰一样地观察，从猎豹身上学习聪明机灵，并体现出狼的强大精神力量。', `FemaleText_loc5`='看看野獸們的智慧和知識，你就會看到你自己。像貓頭鷹一樣地觀察，從獵豹身上學習聰明機靈，並體現出狼的強大精神力量。', `FemaleText_loc7`='Observa la sabiduría y el conocimiento de la bestia, y te verás a ti $gmismo:misma;. Observa como el búho, aprende la astucia del dientes de sable, encarna el poderoso espíritu del lobo.' WHERE `ID`=7564;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련을 받고 싶어요.', `MaleText_loc4`='请训练我吧。', `MaleText_loc5`='請訓練我吧。', `MaleText_loc7`='Por favor, instrúyeme.', `FemaleText_loc1`='훈련을 받고 싶어요.', `FemaleText_loc4`='请训练我吧。', `FemaleText_loc5`='請訓練我吧。', `FemaleText_loc7`='Por favor, instrúyeme.' WHERE `ID`=7565;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보호의 룬이 파괴됐다! 형제들이여, 이단자들을 찾아 처치하라!', `MaleText_loc4`='守护符文被摧毁了！兄弟们，杀掉这些入侵者！', `MaleText_loc5`='守護符文被摧毀了!兄弟們，殺掉這些入侵者!', `MaleText_loc7`='¡Han destruido las runas de protección! ¡Persigan a los infieles, hermanos míos!' WHERE `ID`=7566;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 여기까지 와서 살아있는 불꽃의 비밀을 캐내려 한단 말이냐! 그 무모한 용기를 후회하게 되리라.', `MaleText_loc4`='你们要不顾一切地揭开烈焰之子的秘密，你们会为这鲁莽的行为付出巨大的代价！', `MaleText_loc5`='你們要不顧一切地揭開烈焰之子的秘密，你們會為這魯莽的行為付出巨大的代價!', `MaleText_loc7`='¡Con suma arrogancia, han venido para despojarnos de los secretos de la Llama viviente! Pronto lamentaran lo imprudente de su misión.' WHERE `ID`=7567;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 여기 거처하시는 군주님을 소환하겠다. 그분을 알현하면 너희 벌레 같은 목숨도 끝장날 것이다! 그때도 그런 배짱이 남아 있을지 어디 한번 보자!', `MaleText_loc4`='我将会召唤这里真正的主人，让你们直接面对他无尽的愤怒，你们渺小的生命即将完结！不过，你们得自己进入他的房间！', `MaleText_loc5`='我將會召喚這裡真正的主人，讓你們直接面對他無盡的憤怒，你們渺小的生命即將完結!', `MaleText_loc7`='Ahora, invocaré al señor de este dominio. Si desean que él les conceda audiencia, ¡es probable que tomen sus vidas! No obstante, ¡busquen su refugio si se atreven!' WHERE `ID`=7568;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라그나로스의 둥지에서 보자!', `MaleText_loc4`='[PH]好吧，我离开这儿……到拉格纳罗斯的巢穴见……18', `MaleText_loc5`='[PH]好吧，我離開這兒...到拉格納羅斯的巢穴見...l8', `MaleText_loc7`='[PH] Está bien, me voy de aquí... te veré en la Guarida de Ragnaros... l8' WHERE `ID`=7569;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 두 개의 용암 피조물로 갈라집니다!', `MaleText_loc4`='%s分裂成两只熔岩爪牙！', `MaleText_loc5`='%s分裂成兩隻熔岩爪牙!', `MaleText_loc7`='%s se divide en otros dos Príncipes de Lava.' WHERE `ID`=7570;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제야 나의 방랑이 끝났군.', `MaleText_loc4`='我刚结束流浪生活。', `MaleText_loc5`='我剛結束流浪生活。', `MaleText_loc7`='Acabo de terminar mi viaje.' WHERE `ID`=7571;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그대는 드루이드가 아니지 않습니까!', `FemaleText_loc4`='你不是德鲁伊！', `FemaleText_loc5`='你不是德魯伊!', `FemaleText_loc7`='¡No eres un druida!' WHERE `ID`=7572;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='루테란 마을로 날아가고 싶습니다.', `MaleText_loc4`='我想飞往鲁瑟兰村。', `MaleText_loc5`='我想飛往魯瑟蘭村。', `MaleText_loc7`='Me gustaría volar a Aldea Rut''theran.', `FemaleText_loc1`='루테란 마을로 날아가고 싶어요.', `FemaleText_loc4`='我想飞往鲁瑟兰村。', `FemaleText_loc5`='我想飛往魯瑟蘭村。', `FemaleText_loc7`='Me gustaría volar a Aldea Rut''theran.' WHERE `ID`=7573;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='세나리온 의회에서 베푸는 호의입니다. 루테란 마을로 날아가시겠습니까?', `FemaleText_loc4`='你想乘坐塞纳里奥议会的免费航线飞回鲁瑟兰村吗？', `FemaleText_loc5`='你想飛回塞納里奧議會的魯瑟蘭村嗎?', `FemaleText_loc7`='¿Te gustaría volar a Aldea Rut''theran por cortesía del Círculo Cenarion?' WHERE `ID`=7574;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다시 썬더 블러프로 날아가려면 저 같은 일을 하는 타우렌, 분덴 플레인즈윈드와 대화를 하십시오.', `FemaleText_loc4`='要是你想要飞回雷霆崖，就该跟我的牛头人搭档布瑟恩·草风谈谈。', `FemaleText_loc5`='要是你想要飛回雷霆崖，就該跟我的牛頭人搭檔布瑟恩·草風談談。', `FemaleText_loc7`='Si buscas un vuelo de vuelta a Cima del Trueno deberías hablar con mi compañero tauren, Bunthen Viento del Llano.' WHERE `ID`=7575;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대는 드루이드가 아니잖소!', `MaleText_loc4`='你不是德鲁伊！', `MaleText_loc5`='你不是德魯伊!', `MaleText_loc7`='¡No eres un druida!' WHERE `ID`=7576;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세나리온 의회에서 베푸는 호의요. 썬더 블러프로 날아가시겠소?', `MaleText_loc4`='你需要乘坐塞纳里奥议会的免费航线飞往雷霆崖吗？', `MaleText_loc5`='你需要飛往雷霆崖嗎?這次由塞納里奧議招待。', `MaleText_loc7`='¿Te gustaría volar a Cima del Trueno por cortesía del Círculo Cenarion?' WHERE `ID`=7577;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='루테란 마을로 다시 날아가려 하오? 그렇다면 나와 같은 일을 하는 나이트 엘프, 실비아 필나베스와 이야기를 나눠보시오.', `MaleText_loc4`='如果你想飞回鲁瑟兰村，就该找暗夜精灵希尔瓦·菲纳雯斯谈谈。', `MaleText_loc5`='如果你想飛回魯瑟蘭村，就該找夜精靈希爾瓦·菲納雯斯談談。', `MaleText_loc7`='Si buscas un vuelo de vuelta a Aldea Rut''theran, deberías hablar con quien ocupa mi puesto entre los elfos de la noche, Silva Fil''naveth.' WHERE `ID`=7578;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어리석은 놈! 우리 계획을 방해하는 건 이게 마지막인 줄 알아라! $C!', `MaleText_loc4`='这是你最后一次干扰我们的计划了，愚蠢的$c！', `MaleText_loc5`='這是你最後一次妨礙我們的計畫了，愚蠢的$c!', `MaleText_loc7`='¡Ha sido la última vez que interfieres en nuestros planes, $gestúpido:estúpida; $c!', `FemaleText_loc1`='어리석은 놈! 우리 계획을 방해하는 건 이게 마지막인 줄 알아라! $C!', `FemaleText_loc4`='这是你最后一次干扰我们的计划了，愚蠢的$c！', `FemaleText_loc5`='這是你最後一次妨礙我們的計畫了，愚蠢的$c!', `FemaleText_loc7`='¡Ha sido la última vez que interfieres en nuestros planes, $gestúpido:estúpida; $c!' WHERE `ID`=7579;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 초읽기를 시작합니다.', `MaleText_loc4`='%s开始倒数计时。', `MaleText_loc5`='%s開始倒數計時。', `MaleText_loc7`='%s comienza la cuenta atrás.' WHERE `ID`=7580;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 유령 지역을 무력화했습니다.', `MaleText_loc4`='%s削弱了鬼魂区域的力量。', `MaleText_loc5`='%s無效的鬼魂區域。', `MaleText_loc7`='%s ha desactivado la región de fantasmas.' WHERE `ID`=7581;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어리석은 놈! 우리 계획을 방해하는 건 이게 마지막인 줄 알아라!', `FemaleText_loc4`='这是你最后一次干扰我们的计划了，愚蠢的$c！', `FemaleText_loc5`='這是你最後一次妨礙我們的計畫了，愚蠢的$c!', `FemaleText_loc7`='¡Ha sido la última vez que interfieres en nuestros planes, $gestúpido:estúpida; $c!' WHERE `ID`=7582;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 분노합니다!', `MaleText_loc4`='%s变得愤怒起来！', `MaleText_loc5`='%s被激怒了!', `MaleText_loc7`='%s se enfurece.' WHERE `ID`=7583;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 사는 이 시대는 풍향이 바뀌듯 변덕스럽소. $c, 땅이 저절로 열리고, 괴로움으로 울부짖고 있소. 굳세게 버텨야 하오. 그러지 않으면 우리는 이 혼란에 압도당하고 말 거요.', `MaleText_loc4`='我们所处的这个时期就像风云般变化无常，$c。大地正在痛苦中战栗，哀嚎。我们必须坚定地站稳脚跟，才能避免被这股混乱的漩涡吞噬。', `MaleText_loc5`='我們所處的這個時期就像風雲般變化無常，$c。大地本身在搖動和發出了痛苦的悲鳴。我們必須自立自強，才不會被混亂所吞噬。', `MaleText_loc7`='Los tiempos que nos han tocado vivir son tan volubles como el viento, $c. La misma tierra tiembla y se lamenta. Debemos mantenernos firmes o la confusión nos engullirá.' WHERE `ID`=7584;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 유령 유인기로 끌려갑니다.', `MaleText_loc4`='%s被鬼魂磁铁吸过去了……', `MaleText_loc5`='%s被鬼魂磁鐵吸過去了...', `MaleText_loc7`='%s es atraído hacia el imán fantasmal...' WHERE `ID`=7585;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$C|1이여;여;, 아제로스에서 우리만큼 고통을 당한 종족은 없다네. 죽음을 눈앞에 두고도 웃음을 짓는 건 이제 우리의 천성처럼 돼버렸지.', `MaleText_loc4`='艾泽拉斯中没有哪一个种族经历过我们的人民所受的磨难，$c。面对死亡仍安之若素已经成为我们的第二天性了。', `MaleText_loc5`='艾澤拉斯中沒有哪一個種族經歷過我們的人民所受的磨難，$c。面對死亡仍安之若素已經成為我們的第二天性了。', `MaleText_loc7`='Ninguna otra raza de Azeroth ha sufrido tanto como nuestro pueblo, $c. Reírnos en la cara de la muerte se ha convertido en nuestra segunda naturaleza.' WHERE `ID`=7586;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비 단단히 하십시오. 오늘 우리는 대모님의 이름으로 가시멧돼지 놈들에게 후회와 슬픔, 공포가 무엇인지 제대로 알려 줄 것입니다.', `MaleText_loc4`='准备好。今天，我们将以我们伟大的大地之母的名义，教导这些野猪人学会懊悔、悲哀和恐惧。', `MaleText_loc5`='整裝戒備。今天，以主母之名，我們將讓野豬人嘗到後悔、悲痛和恐怖的滋味。', `MaleText_loc7`='Prepárate hoy enseñaremos a los jabaespines acerca del arrepentimiento, la tristeza y el miedo en nombre de nuestra abuela.' WHERE `ID`=7587;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아! 아름다운 그늘 협곡은 언제나 저의 오감을 만족시켜 주지요!', `MaleText_loc4`='啊，幽影谷的美景永远使我感到快乐！', `MaleText_loc5`='啊，幽影谷的美景永遠使我感到快樂!', `MaleText_loc7`='¡Ah, la belleza de Cañada Umbría nunca deja de deleitar mis sentidos!' WHERE `ID`=7588;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='트로그는 한 마리만 봐도 놈들이 어떤 녀석들인지 잘 알 수 있지요.', `MaleText_loc4`='你看见一个穴居人，也就相当于看见了所有穴居人。', `MaleText_loc5`='當你看到一隻穴居怪，其他的很快就會出現在你面前。', `MaleText_loc7`='¡Visto un trogg, vistos todos!' WHERE `ID`=7589;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='북녘골의 시민이여... 당신 체격이 꽤 좋은 분이로군요. 여기 경비가 좀 부실한데 좀 도와주실 수 있습니까?', `MaleText_loc4`='你好！你看起来挺强壮的。我们这里的卫兵数量不太够，你愿意帮忙吗……', `MaleText_loc5`='你好!你看起來挺強壯的。我們這裡的守衛數量不太夠，你願意幫忙嗎...', `MaleText_loc7`='¡Eh, $gciudadano:ciudadana;! Pareces fuerte. Nosotros, los guardias, no tenemos una presencia demasiado densa ahí fuera, podría necesitar tu ayuda...' WHERE `ID`=7590;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아즈샤라의 땅에 대해 말씀해 주십시오.', `MaleText_loc4`='艾萨拉地区。', `MaleText_loc5`='艾薩拉地區。', `MaleText_loc7`='La tierra de Azshara.', `FemaleText_loc1`='아즈샤라의 땅에 대해 말씀해 주십시오.', `FemaleText_loc4`='艾萨拉地区。', `FemaleText_loc5`='艾薩拉地區。', `FemaleText_loc7`='La tierra de Azshara.' WHERE `ID`=7591;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나이트 엘프에 대해 내가 알고 있는 지식에는 한계가 있소. 하지만, 일전에 들은 바로는 오래전 나이트 엘프가 아직 비전 마법의 성스러움을 지키고 있을 당시, 아즈샤라가 그중 가장 뛰어났다고 하오. 그들은 이 아름다운 여인을 여왕으로 받들었소. 하지만 비전술에 중독이 되어버린 여왕은 역사상 가장 파괴적인 사건의 주인공이 되어버렸소이다.', `MaleText_loc4`='我对暗夜精灵的了解有限，但是据说很早以前——当暗夜精灵还掌握着神秘法术时——艾萨拉便是其中的佼佼者，她年轻美貌，是暗夜精灵的女王。不幸地是，正是她对魔法的痴迷才导致历史上最具破坏性事件的发生。', `MaleText_loc5`='我對夜精靈的瞭解有限，但是據說很早以前─當夜精靈還掌握著神秘法術時─艾薩拉便是其中的佼佼者，她年輕美貌，是夜精靈的女王。不幸地是，正是她對魔法的癡迷才導致歷史上最具破壞性事件的發生。', `MaleText_loc7`='Mi conocimiento sobre la historia de los elfos de la noche es limitado, pero se dice que hace mucho tiempo, cuando los elfos de la noche todavía cultivaban el sagrado arte del lanzamiento de conjuros Arcanos, Azshara era la mayor de su clase. Llamaron reina a esa hermosa mujer. Por desgracia, fue su adicción a la magia Arcana la que acabó siendo un día el catalizador de los acontecimientos más devastadores de la historia de este mundo.' WHERE `ID`=7592;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엘다라스 폐허에 대해 말씀해 주십시오.', `MaleText_loc4`='埃达拉斯废墟。', `MaleText_loc5`='埃達拉斯廢墟。', `MaleText_loc7`='Las Ruinas de Eldarath.', `FemaleText_loc1`='엘다라스 폐허에 대해 말씀해 주십시오.', `FemaleText_loc4`='埃达拉斯废墟。', `FemaleText_loc5`='埃達拉斯廢墟。', `FemaleText_loc7`='Las Ruinas de Eldarath.' WHERE `ID`=7593;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='북쪽에 있는 마법사 탑에 대해 말씀해 주십시오.', `MaleText_loc4`='北方的魔法塔。', `MaleText_loc5`='北方的法師塔。', `MaleText_loc7`='La Torre de los Magos al Norte.', `FemaleText_loc1`='북쪽에 있는 마법사 탑에 대해 말씀해 주십시오.', `FemaleText_loc4`='北方的魔法塔。', `FemaleText_loc5`='北方的法師塔。', `FemaleText_loc7`='La Torre de los Magos al Norte.' WHERE `ID`=7594;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='암살자다! 파수병! 파수병!', `FemaleText_loc4`='刺客！来人啊！来人啊！', `FemaleText_loc5`='刺客!來人啊!來人啊!', `FemaleText_loc7`='¡Asesinos! ¡Guardias! ¡Guardias!' WHERE `ID`=7595;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='앞에 뭔가 위험이 도사리고 있어요.', `FemaleText_loc4`='我感到前方有危险。', `FemaleText_loc5`='我感到前方有危險。', `FemaleText_loc7`='Siento que se acerca el peligro.' WHERE `ID`=7596;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='허리가 아파 죽겠군요.', `FemaleText_loc4`='我的背部痛死了。', `FemaleText_loc5`='我的背部痛死了。', `FemaleText_loc7`='La espalda me está matando.' WHERE `ID`=7597;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 명령서를 고위사령관 아벤디스에게 전해줘야 해요!', `FemaleText_loc4`='这些命令必须传达到大将军阿比迪斯那里！', `FemaleText_loc5`='這些命令必須傳達到大將軍阿比迪斯那裡!', `FemaleText_loc7`='¡Estas órdenes deben llegar a manos de la Alta General Abbendis!' WHERE `ID`=7598;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='혹시라도 내게 불상사가 생기거든 이걸 꼭 고위사령관님께 전해주세요.', `FemaleText_loc4`='要是我遇难的话，拿着我的背包。一定要将它送到大将军手上。', `FemaleText_loc5`='要是我遇難的話，拿著我的背包。一定要將它送到大將軍手上。', `FemaleText_loc7`='Si cayera, coge mi bolsa y asegúrate de que llega a manos de la Alta General.' WHERE `ID`=7599;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나무구렁 펄볼그에 대해 말씀해 주십시오.', `MaleText_loc4`='木喉熊怪', `MaleText_loc5`='木喉熊怪', `MaleText_loc7`='Los fúrbolgs Fauces de Madera.', `FemaleText_loc1`='나무구렁 펄볼그에 대해 말씀해 주십시오.', `FemaleText_loc4`='木喉熊怪', `FemaleText_loc5`='木喉熊怪', `FemaleText_loc7`='Los fúrbolgs Fauces de Madera.' WHERE `ID`=7600;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='푸른용혈족의 존재에 대해 말씀해 주십시오.', `MaleText_loc4`='蓝龙现身', `MaleText_loc5`='藍龍現身', `MaleText_loc7`='La presencia de dragones Azules.', `FemaleText_loc1`='푸른용혈족의 존재에 대해 말씀해 주십시오.', `FemaleText_loc4`='蓝龙现身', `FemaleText_loc5`='藍龍現身', `FemaleText_loc7`='La presencia de dragones Azules.' WHERE `ID`=7601;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 도와주었으니 이 땅에 대해서 아는 대로 말해주겠소. 내 지식이 그리 깊지는 않지만, 어쩌면 당신 같은 이가 흥미를 가질 만한 사실을 몇 가지 알려줄 수 있지도 않겠소.', `MaleText_loc4`='你帮助了我，我会告诉我所知的这片土地和生物的情况。我所了解的并不多，但是我可以告诉你一些你可能感兴趣的事儿。', `MaleText_loc5`='你幫助了我，我會告訴我所知的這片土地和生物的情況。我所瞭解的並不多，但是我可以告訴你一些你可能感興趣的事兒。', `MaleText_loc7`='Como me has ayudado te diré lo que sé sobre esta tierra y sobre las cosas que pueden verse. Mi saber no es muy vasto, pero quizás pueda apuntar algunas cosas que podrían interesar a alguien como tú.' WHERE `ID`=7602;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그곳은 한때 거대한 나이트 엘프 도시였소. 엘프의 명가가 군림하며 아주 강력한 비전 마법을 연마했지. 하지만 지금은 저주를 받아 유령처럼 그곳을 떠돌고 있지. 폐허가 되어버린 도시는 원한꼬리 나가들 때문에 더욱더 황폐해지고 말았소. 나가들은 그 폐허에 숨겨진 강력한 명가의 유물을 찾아다니는 걸로 알고 있소.', `MaleText_loc4`='上层暗夜精灵曾经统治这座城池，他们在此演练威力强大的奥术。现在他们受到诅咒，灵魂在这片土地上游荡，恶鞭军官纳迦侵占了精灵的城市。纳迦一定在废墟中搜寻那些上层精灵的神器。', `MaleText_loc5`='夜精靈貴族曾經統治這座城市，他們在此練習威力強大的秘法。現在他們受到詛咒，冤魂在這片土地上遊蕩，惡鞭軍官納迦侵佔了精靈的城市。納迦一定在廢墟中搜尋那些精靈貴族的神器。', `MaleText_loc7`='Antaño una gran ciudad de los elfos de la noche, gobernada un día por los Altonato, que practicaban la gran y poderosa magia Arcana. Ahora están malditos, vagando las tierras, y su ciudad en ruinas ha caído en manos de los nagas Látigo de Ira. Supongo que los nagas buscan en las ruinas poderosos artefactos Altonato.' WHERE `ID`=7603;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='북쪽에 아주 강력한 힘을 지닌 인간 마법사가 산다는 소문이 있소. 어째서인지 이 땅을 감시하고 있다더군. 나도 직접 만난 적은 없지만 들리는 바로는 누구든지 방문할 수 있고, 그자가 시키는 일을 좀 해주면 아주 친절하게 대해 준다고 하더이다.', `MaleText_loc4`='一个强大的人类魔法师传闻就在北部生活；他为了某种不为人知的原因一直在看守着那片大地。我自己没有亲自去过，但是据说访问者在那里很受欢迎，如果他们愿意为他办些差事的话甚至可以赢得他的好感。', `MaleText_loc5`='一個強大的人類魔法師傳聞就在北部生活;他為了某種不為人知的原因一直在看守著那片大地。我自己沒有親自去過，但是據說訪問者在那裡很受歡迎，如果他們願意為他辦些差事的話甚至可以贏得他的好感。', `MaleText_loc7`='Se rumorea que un poderoso mago humano vive al Norte; guardia vigilancia sobre el país por alguna razón desconocida. No he ido hasta allí yo mismo, pero se dice que los visitantes son bienvenidos y que incluso pueden ganarse su favor si están dispuestos a hacerle recados.' WHERE `ID`=7604;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지난 몇 년 동안 펄볼그에게는 끔찍한 일들이 일어났소. 수많은 전투에서 피해를 입었지. 하지만 그 부족이 왜 그렇게 되었는지는 잘 모르오. 악령숲에 퍼진 역병으로 인해 타락했을 수도 있고, 한때는 평화로웠던 자기 종족에게 생긴 일이 화가 나서 지나치게 자기방어적으로 변한 걸 수도 있지. 이유야 어떻든 녀석들은 그 지역에 들어오는 모든 자들에게 아주 공격적이오.', `MaleText_loc4`='过去数年来，我目睹了熊怪所经历的种种可怕的事情——它们成为战场上的无辜受害者。但是我不清楚这个部落现在怎么样了。它们被席卷费伍德森林的天灾腐化了吗？或许它们对自己曾经和平的民族所遭遇的一切表示愤怒，正试图自我保护？无论如何，它们中的大多数对进入这片领域的人都会表现出敌意。', `MaleText_loc5`='過去數年來，我目睹了熊怪所經歷的種種可怕的事情─它們成為戰場上的無辜受害者。但是我不清楚這個部族現在怎麼樣了。它們被席捲費伍德森林的瘟疫腐化了嗎?或許它們對自己曾經和平的民族所遭遇的一切表示憤怒，正試圖自我保護?無論如何，它們中的大多數對進入這片領域的人都會表現出敵意。', `MaleText_loc7`='He visto cómo a los fúrbolgs les sucedían cosas terribles en los últimos años... fueron víctimas en muchos frentes. Pero no está claro qué pasó con esta tribu. ¿Están corruptos por la misma peste que afectó a Frondavil? O tal vez tan solo están furiosos por lo que le ocurrió a su gente y buscan defenderse. En cualquier caso, la mayoría de ellos son hostiles con quien se adentra en la zona.' WHERE `ID`=7605;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에 푸른용혈족은 없지만, 말리고스의 추종자들은 있소. 정확한 이유는 모르겠지만 한 가지는 분명하오. 푸른용혈족이 있는 곳에는 비전 마법이 있게 마련이라는 것이지. 이곳에서 용혈족이 뭔가를 보호하고 있다고 해도 놀라운 일은 아니오... 어쩌면 엘프의 명가가 남긴 것을 보호하는 걸지도 모르오.', `MaleText_loc4`='蓝龙玛里苟斯不在那儿，但是他的信徒在。我不清楚这是怎么回事，但是我可以告诉你：蓝龙所在的地方都有希望找到神秘的魔法。如果说龙人在这儿保护某种东西的话，我是不会感到惊讶的……或许是上层精灵遗漏的物品。', `MaleText_loc5`='藍龍瑪里苟斯不在那兒，但是他的信徒在。我不清楚這是怎麼回事，但是我可以告訴你:藍龍所在的地方都有希望找到神秘的魔法。如果說龍裔在這兒保護某種東西的話，我是不會感到驚訝的...或許是精靈貴族遺漏的物品。', `MaleText_loc7`='No están aquí los dragones Azules, sino los seguidores de Malygos. No sé la razón, pero puedo asegurarte una cosa: dondequiera que haya dragones Azules, prepárate para encontrar magia Arcana. No me sorprendería saber que los dragauros están protegiendo algo... quizás algo que los Altonato dejaron aquí.' WHERE `ID`=7606;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='시간제 직원이라도 고용해야겠어요. 온종일 여기 앉아 낚시용품이나 파는 건 정말 지겹군요. 장사보단 낚시가 제 적성에 맞습니다.', `FemaleText_loc4`='我应该寻求某些帮助；我不喜欢整天坐在这儿卖鱼。我更愿意去钓鱼，然后再卖掉。', `FemaleText_loc5`='我應該尋求某些幫助;我不喜歡整天坐在這兒賣魚。我更願意去釣魚，然後再賣掉。', `FemaleText_loc7`='Debería contratar a alguien para que me ayude, no me gusta estar aquí sentada todo el día, vendiendo material de pesca. Me gusta mucho más ir a pescar, y luego, vender.' WHERE `ID`=7607;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='낚시용품을 보고 싶습니다.', `MaleText_loc4`='让我们看看你的钓鱼装备。', `MaleText_loc5`='讓我們看看你的釣魚裝備。', `MaleText_loc7`='Vamos a echar un vistazo a tus suministros de pesca.', `FemaleText_loc1`='낚시용품을 보고 싶습니다.', `FemaleText_loc4`='让我们看看你的钓鱼装备。', `FemaleText_loc5`='讓我們看看你的釣魚裝備。', `FemaleText_loc7`='Vamos a echar un vistazo a tus suministros de pesca.' WHERE `ID`=7608;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='트롬카, $c. 오늘 기분이 무척 좋지 않으니, 도와주러 온 게 아니라면 혼자 있게 내버려둬.', `FemaleText_loc4`='你好, $c。我今天情绪很差，所以除非你能帮我，否则我更愿意自己呆着。', `FemaleText_loc5`='你好, $c。我今天情緒很差，所以除非你能幫我，否則我更願意自己一個人待著。', `FemaleText_loc7`='Throm-Ka, $c. Hoy no estoy de buen humor así que, por favor, si no puedes ayudarme preferiría estar sola.' WHERE `ID`=7610;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘하셨어요, $n! 자, 이제 저와 얘기를 나누시면 이 시험이 완전히 끝나죠. 그냥 그렇게 서 있으면 시간은 계속해서 흘러 가버리고 말아요!', `FemaleText_loc4`='干得好，$n！跟我谈谈以完成对你的考验。来吧，时间可不等人！', `FemaleText_loc5`='幹得好，$n!跟我談談以完成對你的考驗。來吧，時間可不等人!', `FemaleText_loc7`='¡Buen trabajo, $n! Termina la prueba hablando conmigo. ¡El tiempo seguirá pasando hasta que no lo hagas!' WHERE `ID`=7611;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무모한 놈들! 감히 누가 살아있는 불꽃의 후예에게 덤비느냐!', `MaleText_loc4`='可笑的凡人！在烈焰之子面前灰飞烟灭吧！', `MaleText_loc5`='可笑的凡人!在烈焰之子面前灰飛煙滅吧!', `MaleText_loc7`='¡Imprudentes mortales! ¡Nadie puede desafiar a los Hijos de la Llama viviente!' WHERE `ID`=7612;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 당신은 내게 훈련을 받을 수 없습니다.', `MaleText_loc4`='我不能训练你，$c。', `MaleText_loc5`='我不能訓練你，$c。', `MaleText_loc7`='No puedo entrenarte, $c.', `FemaleText_loc1`='$c|1이여;여;, 당신은 내게 훈련을 받을 수 없습니다.', `FemaleText_loc4`='我不能训练你，$c。', `FemaleText_loc5`='我不能訓練你，$c。', `FemaleText_loc7`='No puedo entrenarte, $c.' WHERE `ID`=7613;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 용맹호의 선장, 율리시스 랙모어다. 돌이킬 수 없는 운명에 처한 우리 배에서 마지막 며칠 동안의 일을 이 일지에 기록했다.$B$B보급 물자를 싣고 페더문 요새로 향하던 중 나가들이 배의 측면을 공격해 왔다. 간신히 녀석들을 몰아내기는 했지만, 놈들이 되돌아오리란 걸 알고 있었다. 나는 귀중한 물건들을 잃어버릴까 염려해 용맹호를 잊혀진 땅의 해안에서 좀 떨어진 섬으로 몰고 갔다. 그 섬은 나이트 엘프의 고대 유적이 있는 곳으로서, 나는 거기에 보물이 든 궤짝을 남겨놓았다.', `MaleText_loc4`='我是奥塞斯·拉克摩尔，豪侠轮船的船长。这是最近几天轮船的航行日志。$B$B我们的船只满载货物驶向羽月要塞，纳迦袭击了船只一侧。我们赶走了他们，但是我们知道他们会回来的。我担心纳迦会毁掉我最宝贵的财物，因此我将豪侠驶向远离凄凉之地的一座小岛，岛上全是古老的暗夜精灵建筑废墟。我将自己的宝箱放在了岛上。', `MaleText_loc5`='我是奧塞斯·拉克摩爾，豪俠輪船的船長。這是最近幾天輪船的航行日誌。$B$B我們的船隻滿載貨物駛向羽月要塞，納迦襲擊了船隻一側。我們趕走了他們，但是我們知道他們會回來的。我擔心納迦會毀掉我最寶貴的財物，因此我將豪俠駛向遠離淒涼之地的一座小島，島上全是古老的夜精靈建築廢墟。我將自己的藏寶箱放在了島上。', `MaleText_loc7`='Soy Ulysses Masatormento, capitán de El galante. Y este es el cuaderno de bitácora de los últimos días de mi barco y de su perdición.$B$BNos encontrábamos rumbo al Bastión Plumaluna con un cargamento de suministros, cuando los nagas lo tomaron al asalto. Logramos echarlos atrás pero sabíamos que regresarían. Temiendo la pérdida de mis valiosas posesiones, puse rumbo a una isla de la costa de Desolace, una isla con antiguas ruinas de los elfos de la noche. Y allí dejé mi arqueta.' WHERE `ID`=7614;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 읽습니다...', `MaleText_loc4`='继续读下去……', `MaleText_loc5`='繼續讀下去...', `MaleText_loc7`='Sigue leyendo...', `FemaleText_loc1`='계속 읽습니다...', `FemaleText_loc4`='继续读下去……', `FemaleText_loc5`='繼續讀下去...', `FemaleText_loc7`='Sigue leyendo...' WHERE `ID`=7615;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 궤짝은 견고하게 설계되어 있으며, 궤짝을 열려면 은색 열쇠와 금색 열쇠가 필요하다. 첫 번째 열쇠인 은색 열쇠는 내 일등항해사에게 주었고 금색 열쇠는 내가 가지고 있었다.$B$B하지만, 우리는 그 열쇠를 잃어버리고 말았다. 금색 열쇠는 나가를 공격하던 중 잃어버렸고, 은색 열쇠는 다음날 사나운 마크루라가 쳐들어와 일등항해사를 물속 깊이 끌고 가버리면서 잃어버렸다.$B$B분명 나가와 마크루라가 두 열쇠를 가지고 있을 것이다. 녀석들이 사이가 좋지 않아서 열쇠를 따로 갖고 있으리란 사실이 그나마 다행이다.', `MaleText_loc4`='我的箱子设计独特，需要两把钥匙来开锁，一把金钥匙和一把银钥匙。我将银钥匙给了我的大副，自己保留了金钥匙。$B$B但是我们注定会失去它们。在一次纳迦发动的袭击中，我丢了钥匙；而后，龙虾人攻击了我们，将大副推入了深渊。$B$B我想钥匙一定在纳迦和龙虾人那儿。还好这两方是敌人，不会共享钥匙的。', `MaleText_loc5`='我的箱子設計獨特，需要兩把鑰匙來開鎖，一把金鑰匙和一把銀鑰匙。我將銀鑰匙給了我的大副，自己保留了金鑰匙。$B$B但是我們註定會失去它們。在一次納迦發動的襲擊中，我丟了鑰匙;而後，龍蝦人攻擊了我們，將大副推入了深淵。$B$B我想鑰匙一定在納迦和龍蝦人那兒。還好這兩方是敵人，不會共用鑰匙的。', `MaleText_loc7`='Mi cofre tiene un diseño muy ingenioso y necesita abrirse con dos llaves, una dorada y una de plata. La primera llave, la de plata, se la di al contramaestre, yo mismo guardé la de oro.$B$BPero estábamos condenados a perderlas. Mi llave se perdió en el segundo ataque de los nagas y la del primero de a bordo un día después, cuando los makrura Golpeseco nos asaltaron y lo arrastraron a las profundidades.$B$BEstoy seguro de que los nagas y los makrura tienen las llaves. Me consuela pensar que ambos son enemigos y no las compartirán.' WHERE `ID`=7616;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마크루라의 습격을 받은 후, 우리는 용맹호가 또다시 공격을 받으면 버텨내지 못할 것임을 알았다. 그래서 나와 살아남은 선원들은 배를 버렸다.$B$B이제 바닷가에 왔으니 곧 나이젤의 야영지로 갈 생각이다. 하지만 그 길에는 너무나 많은 위험이 도사리고 있다. 잊혀진 땅이 우릴 집어삼킬까 두렵다.$B$B언젠가 어느 영웅이 이 곤경을 알고, 우리를 이 지경으로 만든 물귀신 놈들에게 복수해 주길 바라는 마음에서 이 글을 남긴다.', `MaleText_loc4`='在龙虾人的进攻后，我们知道下一次豪侠是无法幸免于难的。于是我和几个幸存的水手弃船逃生。$B$B我们现在上岸了并很快就会向尼耶尔前哨站游去，但是在到达避难所之前我们还有很多危险，而且我害怕凄凉之地会吞噬我们。$B$B我现在写下这些是希望有人能知道我们的困境，有一天能把那些带给我们灭顶之灾的水中魔鬼杀死为我们报仇。', `MaleText_loc5`='在龍蝦人的進攻後，我們知道下一次豪俠是無法倖免於難的。於是我和幾個倖存的水手棄船逃生。$B$B我們現在上岸了並很快就會向尼耶爾前哨站遊去，但是在到達避難所之前我們還有很多危險，而且我害怕淒涼之地會吞噬我們。$B$B我現在寫下這些是希望有人能知道我們的困境，有一天能把那些帶給我們滅頂之災的水中魔鬼殺死為我們報仇。', `MaleText_loc7`='Después del ataque makrura, pudimos ver que El galante no sobreviviría a otro. Así que los pocos marineros que sobrevivieron y yo abandonamos mi nave.$B$BAhora estamos en tierra y pronto emprenderemos el camino hacia la ciudad de la Punta de Nijel, pero hay mucho peligro entre nosotros y el santuario, y me temo que Desolace nos consumirá.$B$BEscribo esto ahora con la esperanza de que alguien conozca nuestra situación y nos vengue ante los pálidos desalmados que fueron nuestra ruina.' WHERE `ID`=7617;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='달숲에서 이곳 레물로스의 제단은 우리 세나리온 의회가 모이는 성스러운 곳이니 방문객의 신분에 어긋나지 않게 행동해 주시기 바랍니다.$B$B제 시미터에 당해 숲에 묻히고 싶지 않다면 말이에요.', `FemaleText_loc4`='对我们这些在月光林地塞纳里奥议会的人来说，雷姆洛斯神殿是个神圣的地方……所以请你的表现符合访客的身份。$B$B我想你不愿让我用弯刀杀死你，那就是了。', `FemaleText_loc5`='對我們這些在月光林地塞納里奧議會的人來說，雷姆洛斯神殿是個神聖的地方...所以請你的表現符合訪客的身分。$B$B我想你不願讓我用彎刀殺死你，那就是了。', `FemaleText_loc7`='El Santuario de Remulos es un lugar sagrado para nosotros los del Círculo Cenarion en el Claro de la Luna... así que, por favor, compórtate de forma adecuada para un visitante.$B$BUn visitante que no quiere ver clavada en él mi cimitarra.' WHERE `ID`=7618;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='세나리우스의 가호가 당신과 함께하기를.$B$B저는 타자리라고 합니다. 이 제단을 수호할 것을 맹세했지요. 수호자 레물로스를 받들어 이 성스러운 땅의 관리인으로서 일하는 것은 정말 영광이랍니다.', `FemaleText_loc4`='愿塞纳留斯庇护你，我的$g兄弟:姐妹;。$B$B我是塔加里，神殿的保卫者。能够作为这片神圣大地的看守来服侍守护者雷姆洛斯是我的荣耀。', `FemaleText_loc5`='願塞納留斯注視著你，$g兄弟:姐妹;。$B$B我是塔加里，一個神殿的堅定保衛者。能夠作為這片神聖大地的守衛來服侍守衛者雷姆洛斯是我的榮耀。', `FemaleText_loc7`='Que Cenarius te guarde, $ghermano:hermana;.$B$BSoy Tajarri, y he jurado proteger este santuario. Mi honor consiste en servir al guardián Remulos como celador de su tierra sagrada.' WHERE `ID`=7619;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스컬지가 오기 전까지만 해도, 나도 정말 잘 나갔는데 말이야. 뭐든지 사고 팔았지. 뭐든지!$B$B정말 말도 안 되게 가격도 높게 불렀는데도 말이야!$B$B살아있는 자라면 다 알 테니 아무나 붙잡고 물어보라고.', `MaleText_loc4`='在亡灵天灾来临之前，我是一名大商贩。我出售所有商品。所有！$B$B价钱都极其便宜！$B$B你随便问问那些没死的人，看看我说的是不是真的。', `MaleText_loc5`='在天譴軍團來臨之前，我是一名大商販。我出售所有商品。所有!$B$B價錢都極其便宜!$B$B你隨便問問那些沒死的人，看看我說的是不是真的。', `MaleText_loc7`='Antes de que viniera la Plaga, tenía un gran negocio. Vendía y compraba de todo. ¡De todo!$B$B¡Y mis precios eran UNA LOCURA!$B$BPregúntale a quien quieras. A alguien que todavía viva.' WHERE `ID`=7620;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하신가, $n! 뭔가 사러 온 건가? 아니면 팔러?$B$B여기보다 더 싼 곳은 없을 거야. 아니면 내가 성을 갈겠어!', `MaleText_loc4`='嗨$n！你是来购物的，还是来出售物品的？$B$B如果有比这儿更便宜的物品，我就不叫被感动的奥古斯图斯！', `MaleText_loc5`='嗨$n!你是來購物的，還是來出售物品的?$B$B如果有比這兒更便宜的物品，我就不叫精神失常的奧古斯圖斯!', `MaleText_loc7`='¡Hola $n! ¿Has venido a comprar algo? ¿Tal vez a vender?$B$B¡Si puedes encontrar mejores precios es que no me llamo Augustus el Agraciado!' WHERE `ID`=7621;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거래! 거래를 하세!', `MaleText_loc4`='商业！我需要它！', `MaleText_loc5`='商業!我需要它!', `MaleText_loc7`='¡Comercio! ¡Me muero de ganas!' WHERE `ID`=7622;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 아우구스투스. 거래를 하고 싶습니다.', `MaleText_loc4`='是的，奥古斯图斯。我想做生意。', `MaleText_loc5`='是的，奧古斯圖斯。我想做生意。', `MaleText_loc7`='Sí, Augustus. Me gustaría hacer negocios.', `FemaleText_loc1`='네, 아우구스투스. 거래를 하고 싶습니다.', `FemaleText_loc4`='是的，奥古斯图斯。我想做生意。', `FemaleText_loc5`='是的，奧古斯圖斯。我想做生意。', `FemaleText_loc7`='Sí, Augustus. Me gustaría hacer negocios.' WHERE `ID`=7623;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 이곳은 위험한 곳입니다. 조심하십시오.', `MaleText_loc4`='这是个危险的地方，$n。要小心。', `MaleText_loc5`='這是個危險的地方，$n。小心周遭。', `MaleText_loc7`='Es un lugar peligroso, $n. Ten cuidado por aquí.' WHERE `ID`=7624;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요, $c 친구여. 키린 토에 도움을 청하려고 온 것이면 용건만 간단히 말하도록 하세요.', `MaleText_loc4`='你好，$c。请简要介绍肯瑞托能如何为你效力。', `MaleText_loc5`='你好，$c。請簡要介紹祈倫托能如何為你效力。', `MaleText_loc7`='Saludos, $c. Sé breve y explica cómo puede ayudarte el Kirin Tor.' WHERE `ID`=7625;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽어라, 벌레 같은 놈들!', `MaleText_loc4`='死吧，你这卑鄙的家伙！', `MaleText_loc5`='去死吧!', `MaleText_loc7`='¡MUERE, INSECTO!' WHERE `ID`=7626;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이보다 더 저렴한 가격은 어디서도 찾을 수 없다네!', `MaleText_loc4`='你在任何地方都不会找到比这更低的价格的！', `MaleText_loc5`='你在任何地方都不會找到比這更低的價格的!', `MaleText_loc7`='¡No encontrarás mejores precios en ninguna parte!' WHERE `ID`=7627;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 이름은 아우구스투스. 내 가격은 말도 안 되는 가격이지!', `MaleText_loc4`='我是奥古斯图斯，这价格太高啦！', `MaleText_loc5`='我是奧古斯圖斯，這價格太高啦!', `MaleText_loc7`='¡Soy Augustus, y mis precios son UNA LOCURA!' WHERE `ID`=7628;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 아우구스투스! 자네에게 필요한 건 뭐든 있지! 팔고 싶은 게 있으면 뭐든 다 사주겠네!', `MaleText_loc4`='我是奥古斯图斯！我有你想要的东西！我想要你准备出售的东西！', `MaleText_loc5`='我是奧古斯圖斯!我有你想要的東西!我想要你準備出售的東西!', `MaleText_loc7`='¡Soy Augustus! ¡Lo quieres... pues lo tienes! ¡Lo quieres vender... pues yo te lo compro!' WHERE `ID`=7629;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 내 시간을 뺏지 않는 게 좋을 걸세.', `MaleText_loc4`='别浪费我的时间，$c。', `MaleText_loc5`='別浪費我的時間，$c。', `MaleText_loc7`='No me hagas perder el tiempo, $c.', `FemaleText_loc1`='$c|1이여;여;, 내 시간을 뺏지 않는 게 좋을 걸세.', `FemaleText_loc4`='别浪费我的时间，$c。', `FemaleText_loc5`='別浪費我的時間，$c。', `FemaleText_loc7`='No me hagas perder el tiempo, $c.' WHERE `ID`=7630;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 $c|1은;는; 가르치지 않는데... 괜히 성질 돋우지 말고 자네에게 맞는 상급자나 찾아가 보게.', `MaleText_loc4`='我不训练你这样的$c。在你惹恼我之前找你自己的训练师吧。', `MaleText_loc5`='我不訓練你這樣的$c。在你惹惱我之前找你自己的訓練師吧。', `MaleText_loc7`='No entreno a los de tu clase, $c. Busca a tu instructor antes de que me enfade.', `FemaleText_loc1`='난 $c|1은;는; 가르치지 않는데... 괜히 성질 돋우지 말고 자네에게 맞는 상급자나 찾아가 보게.', `FemaleText_loc4`='我不训练你这样的$c。在你惹恼我之前找你自己的训练师吧。', `FemaleText_loc5`='我不訓練你這樣的$c。在你惹惱我之前找你自己的訓練師吧。', `FemaleText_loc7`='No entreno a los de tu clase, $c. Busca a tu instructor antes de que me enfade.' WHERE `ID`=7631;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='딴 데 가서 알아보게. 나는 전사만 가르치니까.', `MaleText_loc4`='放轻松点。我只训练战士。', `MaleText_loc5`='放輕鬆點。我只訓練戰士。', `MaleText_loc7`='Con calma, colega. Solo entreno a guerreros.', `FemaleText_loc1`='딴 데 가서 알아보게. 나는 전사만 가르치니까.', `FemaleText_loc4`='放轻松点。我只训练战士。', `FemaleText_loc5`='放輕鬆點。我只訓練戰士。', `FemaleText_loc7`='Con calma, colega. Solo entreno a guerreros.' WHERE `ID`=7632;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 도와드릴까?', `MaleText_loc4`='我可以为你效劳吗?', `MaleText_loc5`='我可以為你效勞嗎，老兄?', `MaleText_loc7`='¿Qué puedo hacer por ti, colega?', `FemaleText_loc1`='뭘 도와드릴까?', `FemaleText_loc4`='我可以为你效劳吗?', `FemaleText_loc5`='我可以為你效勞嗎，老兄?', `FemaleText_loc7`='¿Qué puedo hacer por ti, colega?' WHERE `ID`=7633;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신, 직업의 호환성이 저와는 일치하지 않는 문제로 인해, 당신의 능력이 모자라 처한 상황을 수정하도록 도와드릴 수 없군요.', `MaleText_loc4`='由于职业的不同，因此我对你缺乏技能的现状无能为力。', `MaleText_loc5`='由於職業的不同，因此我對你缺乏技能的現狀無能為力。', `MaleText_loc7`='Debido a una clara incompatibilidad en tu especificación de clase, soy incapaz de ayudarte a rectificar cualquier situación a la que hayas llegado por la falta de habilidades.', `FemaleText_loc1`='당신, 직업의 호환성이 저와는 일치하지 않는 문제로 인해, 당신의 능력이 모자라 처한 상황을 수정하도록 도와드릴 수 없군요.', `FemaleText_loc4`='由于职业的不同，因此我对你缺乏技能的现状无能为力。', `FemaleText_loc5`='由於職業的不同，因此我對你缺乏技能的現狀無能為力。', `FemaleText_loc7`='Debido a una clara incompatibilidad en tu especificación de clase, soy incapaz de ayudarte a rectificar cualquier situación a la que hayas llegado por la falta de habilidades.' WHERE `ID`=7634;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훌륭합니다! 필요한 변수와 규격에 관한 요구 사항을 모두 만족하는군요. 뭘 도와드릴까요?', `MaleText_loc4`='很好！你达到了要求的参数和规格。我可以为你做些什么吗？', `MaleText_loc5`='很好!你達到了要求的參數和規格。我可以為你做些什麼嗎?', `MaleText_loc7`='¡Excelente! Cumples con los parámetros y especificaciones requeridos. ¿Qué puedo hacer por ti?', `FemaleText_loc1`='훌륭합니다! 필요한 변수와 규격에 관한 요구 사항을 모두 만족하는군요. 뭘 도와드릴까요?', `FemaleText_loc4`='很好！你达到了要求的参数和规格。我可以为你做些什么吗？', `FemaleText_loc5`='很好!你達到了要求的參數和規格。我可以為你做些什麼嗎?', `FemaleText_loc7`='¡Excelente! Cumples con los parámetros y especificaciones requeridos. ¿Qué puedo hacer por ti?' WHERE `ID`=7635;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 때가 아닌데 나를 너무 일찍 깨웠도다, 이그젝큐투스, 대체 왜 이런 불경한 짓을 저지른 게냐?', `MaleText_loc4`='你为什么要唤醒我，埃克索图斯，为什么要打扰我？', `MaleText_loc5`='太早了!你太早叫醒我了，埃克索圖斯!為什麼要打擾我?', `MaleText_loc7`='¡DEMASIADO PRONTO! ¡ME HAS DESPERTADO DEMASIADO PRONTO, EXECUTUS! ¿¿¿QUÉ SIGNIFICA ESTA INTRUSIÓN???' WHERE `ID`=7636;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 헤그너 럼블샷이라고 합니다. 말씀만 하십시오!', `MaleText_loc4`='海格纳·重枪，愿为你效劳！', `MaleText_loc5`='海格納·重槍，願為你效勞!', `MaleText_loc7`='¡Hegnar Estruendo a tu servicio!' WHERE `ID`=7637;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='테라모어가 뛰어난 전사 훈련으로 명성을 떨치고 있긴 하지만, 안타깝게도 당신을 도와드릴 수는 없소.', `MaleText_loc4`='虽然塞拉摩以它特有的武士培训闻名，我恐怕还是不能帮你。', `MaleText_loc5`='雖然塞拉摩以它特有的武士培訓聞名，我恐怕還是不能幫你。', `MaleText_loc7`='Theramore es famosa por la excepcional instrucción que reciben sus guerreros, pero me temo que yo no puedo ayudarte.', `FemaleText_loc1`='테라모어가 뛰어난 전사 훈련으로 명성을 떨치고 있긴 하지만, 안타깝게도 당신을 도와드릴 수는 없소.', `FemaleText_loc4`='虽然塞拉摩以它特有的武士培训闻名，我恐怕还是不能帮你。', `FemaleText_loc5`='雖然塞拉摩以它特有的武士培訓聞名，我恐怕還是不能幫你。', `FemaleText_loc7`='Theramore es famosa por la excepcional instrucción que reciben sus guerreros, pero me temo que yo no puedo ayudarte.' WHERE `ID`=7638;
