UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사냥꾼의 도를 배우고자 합니다.', `MaleText_loc4`='我想接受猎人技能方面的训练。', `MaleText_loc5`='我想接受成為獵人的訓練。', `MaleText_loc7`='Necesito instrucción en las artes del cazador.', `FemaleText_loc1`='사냥꾼의 도를 배우고자 합니다.', `FemaleText_loc4`='我想接受猎人技能方面的训练。', `FemaleText_loc5`='我想接受成為獵人的訓練。', `FemaleText_loc7`='Necesito instrucción en las artes del cazador.' WHERE `ID`=7643;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 그대를 훈련시켜줄 수 없소, 젊은이.', `MaleText_loc4`='我不能训练你，年轻人。', `MaleText_loc5`='我不能訓練你，年輕人。', `MaleText_loc7`='No puedo entrenarte, joven.', `FemaleText_loc1`='저는 당신을 훈련시켜줄 수 없습니다.', `FemaleText_loc4`='我不能训练你，年轻人。', `FemaleText_loc5`='我不能訓練你，年輕人。', `FemaleText_loc7`='No puedo entrenarte, joven.' WHERE `ID`=7644;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불의 군주님은 한때 동지들과 함께 전 세계를 군림했었다. 그분은 고대 신의 신하로서 티탄들과 이 세계를 장악하기 위한 싸움을 벌였지. 하지만 승리는 티탄들에게 돌아갔고 주인님은 동지들과 정령계로 영원히 추방당했다. 그리고 티탄의 시대가 끝날 때까지 그곳에 갇히고 말았다.', `MaleText_loc4`='炎魔之王和他的兄弟们曾经统治整个世界。作为上古之神的一名仆从，他与泰坦争夺这个星球的统治权。获胜的泰坦将我的主人和他的兄弟们放逐到元素神域——他们被关押在那儿直到时间尽头。', `MaleText_loc5`='炎魔和他的兄弟們曾經統治整個世界。作為上古諸神的一名僕從，他與泰坦爭奪這個星球的統治權。獲勝的泰坦將我的主人和他的兄弟們放逐到元素界域─他們被關押在那兒直到時間盡頭。', `MaleText_loc7`='El Señor del Fuego y sus hermanos dominaron un día todo el mundo, mortal. Como siervo de los dioses antiguos, luchó contra los titanes por el control de este planeta. Los titanes, que se alzaron con la victoria, desterraron a mi maestro y a sus hermanos al plano elemental... para quedar allí encarcelados hasta el fin de los tiempos.' WHERE `ID`=7645;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 얘기해 보십시오.', `MaleText_loc4`='告诉我更多的信息。', `MaleText_loc5`='告訴我更多的資訊。', `MaleText_loc7`='Cuéntame más.', `FemaleText_loc1`='계속 얘기해 보십시오.', `FemaleText_loc4`='告诉我更多的信息。', `FemaleText_loc5`='告訴我更多的資訊。', `FemaleText_loc7`='Cuéntame más.' WHERE `ID`=7646;
