UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 자네를 훈련시킬 수 없네.', `MaleText_loc4`='我不能训练你。', `MaleText_loc5`='我不能訓練你。', `MaleText_loc7`='No puedo instruirte.', `FemaleText_loc1`='저는 당신을 훈련시킬 수 없습니다.', `FemaleText_loc4`='我不能训练你。', `FemaleText_loc5`='我不能訓練你。', `FemaleText_loc7`='No puedo instruirte.' WHERE `ID`=7654;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='건방진 젖먹이! 죽고 싶어 안달이구나! 자, 보아라. 주인님께서 일어나신다!', `MaleText_loc4`='你这个莽撞的家伙！你简直是自寻死路！看吧，你惊动了主人！', `MaleText_loc5`='你這個莽撞的傢伙!你簡直是自尋死路!看吧，你驚動了主人!', `MaleText_loc7`='¡Crías imprudentes! ¡Se han precipitado hasta su propia muerte! ¡Ahora miren, el maestro se agita!|n' WHERE `ID`=7655;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑네. 자네는 상급 $c|1을;를; 찾아가야겠군.', `MaleText_loc4`='嗨，你需要继续前进，去找$c训练师。', `MaleText_loc5`='嗨，你需要繼續前進，去找$c訓練師。', `MaleText_loc7`='Eh, colega, tendrás que ir con el inh''tructor de $c.', `FemaleText_loc1`='반갑습니다. 당신은 상급 $c|1을;를; 찾아가야 합니다.', `FemaleText_loc4`='嗨，你需要继续前进，去找$c训练师。', `FemaleText_loc5`='嗨，你需要繼續前進，去找$c訓練師。', `FemaleText_loc7`='Eh colega, tendrás que ir con el instructor de $c.' WHERE `ID`=7656;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보라! 불의 군주 라그나로스 님을! 태초부터 존재하셨던 분이다. 경배하라! 최후를 맞기 전 그분 앞에 무릎을 꿇어라!', `MaleText_loc4`='拉格纳罗斯，炎魔之王！他比这个世界本身还要古老，在他面前屈服吧！在你们的末日面前屈服吧！', `MaleText_loc5`='炎魔拉格納羅斯!他比這個世界本身還要古老，在他面前屈服吧!在你們的末日面前屈服吧!', `MaleText_loc7`='¡Contemplen a Ragnaros, el Señor del Fuego! ¡El que ya era anciano cuando el mundo aún era joven! ¡Arrodriguen se ante él, mortales! ¡Arrodriguen se antes de su fin!' WHERE `ID`=7657;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼의 도를 배우고 싶습니다.', `MaleText_loc4`='教我灵魂的行事方法。', `MaleText_loc5`='教我元素之靈的運用法門。', `MaleText_loc7`='Enséñame las artes de los espíritus.', `FemaleText_loc1`='영혼의 도를 배우고 싶습니다.', `FemaleText_loc4`='教我灵魂的行事方法。', `FemaleText_loc5`='教我元素之靈的運用法門。', `FemaleText_loc7`='Enséñame las artes de los espíritus.' WHERE `ID`=7658;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼들이 당신을 나에게로 이끌어주셨군. 무얼 도와드리면 되겠소?', `MaleText_loc4`='灵魂引导你来到我这儿。我要怎么帮你？', `MaleText_loc5`='靈魂引導你來到我這兒。我要怎麼幫你?', `MaleText_loc7`='Los espíritus te han guiado hasta mí. ¿Cómo puedo serte de ayuda?', `FemaleText_loc1`='영혼들이 당신을 내게로 이끌어주셨군요. 무얼 도와드리면 되겠습니까?', `FemaleText_loc4`='灵魂引导你来到我这儿。我要怎么帮你？', `FemaleText_loc5`='靈魂引導你來到我這兒。我要怎麼幫你?', `FemaleText_loc7`='Los espíritus te han guiado hasta mí. ¿Cómo puedo serte de ayuda?' WHERE `ID`=7659;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼이 그대와 함께하기를.', `MaleText_loc4`='愿灵魂与你同在。', `MaleText_loc5`='願元素之靈與你同在。', `MaleText_loc7`='Que los espíritus estén contigo.', `FemaleText_loc1`='영혼이 그대와 함께하기를.', `FemaleText_loc4`='愿灵魂与你同在。', `FemaleText_loc5`='願元素之靈與你同在。', `FemaleText_loc7`='Que los espíritus estén contigo.' WHERE `ID`=7660;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님! 저 필멸의 이단자들이 감히 주인님의 성소에 침입해 비밀을 훔치려 했나이다!', `MaleText_loc4`='是因为这些入侵者，我的主人！他们闯入了您的圣殿，想要窃取您的秘密！', `MaleText_loc5`='是因為這些入侵者，我的主人!他們闖入了您的聖所，想要竊取您的秘密!', `MaleText_loc7`='¡He aquí estos mortales infieles, mi señor! ¡Han invadido su santuario y intentan robar sus secretos!' WHERE `ID`=7661;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바보 같은 놈! 이 성스러운 곳에 저 벌레 같은 것들이 날뛰도록 내버려두었더란 말이냐? 날 실망시켰다, 이그젝큐투스! 그 대가를 치러라!', `MaleText_loc4`='蠢货！你让这些不值一提的虫子进入了这个神圣的地方？现在你还将他们引到了我这里来？你太让我失望了，埃克索图斯，你太让我失望了！', `MaleText_loc5`='蠢貨!你讓這些不值得一提的蟲子進入了這個神聖的地方?現在你還將他們引到了我這裡來?你太讓我失望了，埃克索圖斯，你太讓我失望了!', `MaleText_loc7`='¡INEPTO! ¿HAS PERMITIDO QUE ESTOS INSECTOS INGRESEN EN ESTE LUGAR SAGRADO? ¿Y AHORA LOS CONDUCES HASTA MI PROPIO REFUGIO? ¡ME HAS DEFRAUDADO, EXECUTUS! ¡TENDRÉ QUE IMPARTIR JUSTICIA!' WHERE `ID`=7662;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네의 존재감에서 영혼의 힘이 강하게 느껴지는군. 이 트롤이 무슨 일을 도와주면 되나?', `MaleText_loc4`='灵魂与你永在，孩子。我能为你做些什么？', `MaleText_loc5`='靈魂與你永在，孩子。我能為你做些什麼?', `MaleText_loc7`='Que los espíritus estén con ti, colega. ¿Qué puede hacer este trol por ti?', `FemaleText_loc1`='자네의 존재감에서 영혼의 힘이 강하게 느껴지는군. 이 트롤이 무슨 일을 도와주면 되나?', `FemaleText_loc4`='灵魂与你永在，孩子。我能为你做些什么？', `FemaleText_loc5`='靈魂與你永在，孩子。我能為你做些什麼?', `FemaleText_loc7`='Que los espíritus estén con ti, colega. ¿Qué puede hacer esta trol por ti?' WHERE `ID`=7663;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼들의 가호가 있기를.', `MaleText_loc4`='愿灵魂保佑你。', `MaleText_loc5`='願靈魂保佑你。', `MaleText_loc7`='Que los espíritus te protejan, colega.', `FemaleText_loc1`='영혼들의 가호가 있기를.', `FemaleText_loc4`='愿灵魂保佑你。', `FemaleText_loc5`='願靈魂保佑你。', `FemaleText_loc7`='Que los espíritus te protejan, colega.' WHERE `ID`=7664;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디로 가시려고 하십니까? 어딜 가시든지, 빠른 여행을 원하신다면 더 멀리 가서 찾을 것도 없습니다!', `MaleText_loc4`='你去哪儿？如果你想快些到那里，那就别犹豫了！', `MaleText_loc5`='你要去哪兒?如果你想快點抵達那裡，那就別猶豫了!', `MaleText_loc7`='¿Qué estás haciendo? ¡Si quieres ir allí rápidamente, no sigas mirando!' WHERE `ID`=7665;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 항상 감시의 언덕에 물자를 충분히 비축해 두려고는 하지만, 이렇게 전투가 빈번하게 일어나서 쉽지만은 않소.', `MaleText_loc4`='我会尽量保证哨兵岭物资供给的，要维持这项行动可不容易。', `MaleText_loc5`='我會盡量保證哨兵嶺物資供給的，要維持這項行動可不容易。', `MaleText_loc7`='Intento mantener la Colina del Centinela abastecida, y no es fácil con toda esta acción.' WHERE `ID`=7666;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타고 갈 게 필요해요, 지금 당장이요! 아주 중요한 전갈을 전해야 하거든요!', `MaleText_loc4`='我需要飞骑，要快！我有一封非常重要的信要送！', `MaleText_loc5`='我需要飛騎，要快!我有一封非常重要的信要送!', `MaleText_loc7`='¡Necesito un viaje, rápido! ¡Tengo que entregar un mensaje muy importante!', `FemaleText_loc1`='타고 갈 게 필요해요, 지금 당장이요! 아주 중요한 전갈을 전해야 하거든요!', `FemaleText_loc4`='我需要飞骑，要快！我有一封非常重要的信要送！', `FemaleText_loc5`='我需要飛騎，要快!我有一封非常重要的信要送!', `FemaleText_loc7`='¡Necesito un viaje, rápido! ¡Tengo que entregar un mensaje muy importante!' WHERE `ID`=7667;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 사제님. 제때에 와주셨군요. 정말 감사합니다.', `MaleText_loc4`='啊，$g牧师:女牧师;，你来的正是时候。谢谢你。', `MaleText_loc5`='啊，$g牧師:女牧師;，你來的正是時候。謝謝你。', `MaleText_loc7`='Ah, $gsacerdote:sacerdotisa;, viniste justo a tiempo. Te lo agradezco.' WHERE `ID`=7668;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으... 정말 아프군. 고통이 멎지 않을 것 같아.', `MaleText_loc4`='啊，这无尽的痛苦何时才能不再困扰我？', `MaleText_loc5`='啊，這無盡的痛苦何時才能不再困擾我?', `MaleText_loc7`='Argh, el sufrimiento. ¿Me abandonará alguna vez?' WHERE `ID`=7669;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다! 감사합니다, 사제님! 이제 성스러운 빛이 함께하니 저 멀록들과 맞설 수 있겠습니다!', `MaleText_loc4`='谢谢你！谢谢你，牧师。有了你的帮助，我就能对付这些鱼人了！', `MaleText_loc5`='謝謝你!謝謝你，牧師。有了你的幫助，我就能對付這些魚人了!', `MaleText_loc7`='¡Gracias! Gracias, $gsacerdote:sacerdotisa;. ¡Ya me puedo encargar de esos múrlocs, la Luz está de mi lado!' WHERE `ID`=7670;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕히 가십시오. 성스러운 빛이 항상 함께하시기를.', `MaleText_loc4`='再见，愿光明与你同在。', `MaleText_loc5`='再見，願光明與你同在。', `MaleText_loc7`='Que tengas buen viaje, y que la Luz siempre te acompañe.' WHERE `ID`=7671;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불과 300년 전, 타우릿산이라는 무모한 드워프 하나가 주인님을 불타는 세계로부터 소환해냈다. 주인님께서 이 보잘것없는 작은 세계로 귀환하시는 것만으로, 땅이 파괴되고 화산의 심장부가 생겨났지. 그때부터 위대하신 라그나로스는 이 산 아래 잠들어 계신다.', `MaleText_loc4`='仅在三百年前，一个叫作索瑞森的鲁莽的矮人从他炽热的领地中召唤出了魔王。他重返这个卑微的世界吞噬了周围的田地并形成了这个火山之核。从那以后，强大的拉格纳罗斯就沉睡在了这座山下。', `MaleText_loc5`='僅在三百年前，一個叫作索瑞森的魯莽的矮人從他熾熱的領地中召喚出了魔王。他重返這個卑微的世界吞噬了周圍的田地並形成了這個火山之核。從那以後，強大的拉格納羅斯就沉睡在了這座山下。', `MaleText_loc7`='Hace tan solo trescientos años, un temerario enano llamado Thaurissan invocó al maestro desde su reino de fuego. Su regreso a este despreciable mundo devastó las tierras circundantes y dio lugar a este Núcleo volcánico. Desde entonces el poderoso Ragnaros ha dormido bajo esta montaña.' WHERE `ID`=7672;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='할 얘기가 더 있나요?', `MaleText_loc4`='你还想说什么？', `MaleText_loc5`='你還想說什麼?', `MaleText_loc7`='¿Qué más tienes que decir?', `FemaleText_loc1`='할 얘기가 더 있나요?', `FemaleText_loc4`='你还想说什么？', `FemaleText_loc5`='你還想說什麼?', `FemaleText_loc7`='¿Qué más tienes que decir?' WHERE `ID`=7673;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 그분의 종으로 헌신할 것을 맹세했고, 주인님의 철권 통치를 받들어 지시를 따르며 시행한다. 라그나로스 님이 현신하셔도 불의 세계로부터 정기를 받지 못하기 때문에 실체가 아닌 그림자에 불과하지만, 너 정도는 끝내고도 남을 만큼 강력하시다.', `MaleText_loc4`='作为忠实的仆从，我们会听从他的命令，执行他的铁血政策的。没有了强大的领域实权，拉格纳罗斯不过是他自身的傀儡罢了。但是，他拥有足够的力量与你抗衡。', `MaleText_loc5`='作為忠實的僕從，我們會聽從他的命令，執行他的鐵血政策的。沒有了強大的領域實權，拉格納羅斯不過是他自身的傀儡罷了。但是，他擁有足夠的力量與你抗衡。', `MaleText_loc7`='Nosotros, sus siervos, cumplimos sus mandatos y hacemos cumplir sus férreas reglas. Separado de las energías de su reino de fuego, Ragnaros solo es una sombra de su verdadero yo. Pero aún tiene fuerza más que suficiente para ser tu fin.' WHERE `ID`=7674;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 도전에 응하기 위해 여기 왔습니다. 당신의 주인이란 자는 어디 있습니까?', `MaleText_loc4`='你向我们发出挑战而我们来了。你所说的大师在哪里？', `MaleText_loc5`='你向我們發出挑戰而我們來了。你所說的大師在哪裡?', `MaleText_loc7`='Nos retaste y hemos venido. ¿Dónde está el maestro del que hablas?', `FemaleText_loc1`='당신의 도전에 응하기 위해 여기 왔습니다. 당신의 주인이란 자는 어디 있습니까?', `FemaleText_loc4`='你向我们发出挑战而我们来了。你所说的大师在哪里？', `FemaleText_loc5`='你向我們發出挑戰而我們來了。你所說的大師在哪裡?', `FemaleText_loc7`='Nos retaste y hemos venido. ¿Dónde está el maestro del que hablas?' WHERE `ID`=7675;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까? 악수를 청하고 싶지만 보시다시피 뭘 하고 있는 중이라서요... 제가 도와 드릴 일이라도 있습니까?', `MaleText_loc4`='你好，$g先生:女士;。我想握你的手，但是如你所见，我正忙着做事。我可以帮忙吗？', `MaleText_loc5`='你好，$g先生:女士;。我想握你的手，但是如你所見，我正忙著做事。我可以幫忙嗎?', `MaleText_loc7`='Buenos días, $gseñor:señora;. Te daría la mano, pero como ves, estoy ocupado. ¿Puedo serte de ayuda?' WHERE `ID`=7676;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 첫 출발은 좋습니다만 아직 배울 건 많이 있습니다.', `MaleText_loc4`='你有了一个好的开始，但是你要学的还有很多，$n。', `MaleText_loc5`='你有了一個好的開始，但是你要學的還有很多，$n。', `MaleText_loc7`='Has empezado bien, pero todavía tienes mucho que aprender, $n.' WHERE `ID`=7677;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 알고 있는 건 모두 가르쳐 드렸으니 더 많은 것을 배우고 싶으면 스톰윈드 마법사 지구에 있는 나이트 엘프 릴리시아 나이트브리즈를 만나 보십시오. 그녀가 연금술에 대해서는 잘 가르친다는 소문이 있더군요.', `MaleText_loc4`='你已经学会了我能教给你的所有东西，$n。如果你还想继续学习的话，去找暴风城法师区的暗夜精灵莉琳希亚·夜风谈话。我听说她是个好老师。', `MaleText_loc5`='你已經學會了我能教給你的所有東西，$n。如果你還想繼續學習的話，去找暴風城法師區的夜精靈莉琳希亞·夜風談話。我聽說她是個好老師。', `MaleText_loc7`='Ya has aprendido todo lo que puedo enseñarte, $n. Si quieres continuar tus estudios habla con la elfa de la noche Lilyssia Brisa Nocturna, en el Barrio de los Magos de Ventormenta. He oído que es una buena instructora.' WHERE `ID`=7678;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 조그만 집 안에서 전 성벽 밖에서 한창 벌어지고 있는 전투에 참가하는 꿈을 꾸곤 합니다. 하지만 지금으로서는 의무감에 저를 대신해서 싸움터로 나가는 이들에게 지식을 나누어줄 수밖에 없답니다.', `FemaleText_loc4`='虽然我被关在这间小屋里，但是我梦想着加入城墙外激烈的战斗。然而，职责迫使我为替我战斗的那些人传授知识……', `FemaleText_loc5`='雖然我被關在這間小屋裡，但是我夢想著加入城牆外激烈的戰鬥。然而，職責迫使我為替我戰鬥的那些人傳授知識...', `FemaleText_loc7`='Encerrada en esta pequeña casa sueño unirme a las batallas que arden fuera de los muros de la ciudad. Pero el deber me obliga a compartir mi conocimiento con otros que combaten en mi lugar... por ahora.' WHERE `ID`=7679;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이시누 알라, 엘룬께 영광을. 저에게 외부 소식이라도 가지고 오셨습니까? 텔드랏실의 소식이 무척 궁금하답니다.', `MaleText_loc4`='向您致敬，$g兄弟:姐妹;。你有外面的消息吗？我希望得到泰达希尔的消息。', `MaleText_loc5`='(達納蘇斯語)祝你好運，$g兄弟:姐妹;。你有外面的消息嗎?我希望得到泰達希爾的消息。', `MaleText_loc7`='Ishnu-alah, $ghermano:hermana;. ¿Traes nuevas del extranjero? Mi corazón suspira por noticias de Teldrassil.' WHERE `ID`=7682;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대에게 저의 지식을 나누게 되어 영광입니다. 부디 잘 사용하시기를 바랍니다.', `MaleText_loc4`='我很荣幸能够传授给你知识，$n。看得出来你用得不错。', `MaleText_loc5`='我很榮幸能夠傳授給你知識，$n。看得出來你用得不錯。', `MaleText_loc7`='Es un honor compartir contigo mi conocimiento, $n. Procura usarlo bien.' WHERE `ID`=7683;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대는 제 능력을 벗어나셨으니 좀 더 숙련된 스승을 찾아가시는 게 좋겠습니다. 이곳에 있는 릴리시아 나이트브리즈를 만나 보시면 배울 것이 많을 겁니다.', `MaleText_loc4`='你必须找一个更有经验的老师，因为你已经超越了我的能力了。我建议你找这里的莉琳希亚·夜风谈谈：她有更多知识可以传授给你。', `MaleText_loc5`='你必須找一個更有經驗的老師，因為你已經超越了我的能力了。我建議你找這裡的莉琳希亞·夜風談談:她有更多知識可以傳授給你。', `MaleText_loc7`='Debes elegir a un instructor con más experiencia, has superado ya mis habilidades. Te recomiendo hablar con Lilyssia Brisa Nocturna, tiene mucho saber que ofrecer.' WHERE `ID`=7684;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 너희 놈들 차례다! 이 라그나로스의 힘을 찾으러 왔다 했으니 내 몸소 보여주리라!', `MaleText_loc4`='现在轮到你们了！你们愚蠢地追寻拉格纳罗斯的力量，现在你们即将亲眼见到它！', `MaleText_loc5`='現在輪到你們了!你們愚蠢地追尋拉格納羅斯的力量，現在你們即將親眼見到它!', `MaleText_loc7`='¡Y AHORA USTEDES, INSECTOS! CON ARROGANCIA, BUSCARON EL PODER DE RAGNAROS. ¡AHORA LO CONOCERAN DE PRIMERA MANO!' WHERE `ID`=7685;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='드루이드들이 말하길 자연 스스로 호드를 칼림도어에서 밀어내는 것은 시간문제라고 하더군요. 하지만 우리의 대지는 계속 오염되고 있고 여기 텔드랏실도 마찬가지입니다.', `FemaleText_loc4`='德鲁伊们说大自然把部落从卡利姆多赶出去只是个时间问题。然而堕落继续在我们的大地上蔓延，甚至在泰达希尔这里也是。', `FemaleText_loc5`='德魯伊們說大自然把部落從卡林多趕出去只是個時間問題。然而墮落繼續在我們的大地上蔓延，甚至在泰達希爾這裡也是。', `FemaleText_loc7`='Los druidas dicen que es solo una cuestión de tiempo que la naturaleza haga salir a la Horda de Kalimdor. Pero la corrupción sigue esparciéndose por nuestras tierras, incluso aquí, en Teldrassil.' WHERE `ID`=7686;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘하셨습니다! 물약에 대한 이해가 빠르시군요.', `FemaleText_loc4`='干得好！你对药剂的理解进展不错。', `FemaleText_loc5`='幹得好!你對藥劑的理解進展不錯。', `FemaleText_loc7`='¡Bien hecho! Tu saber sobre pociones hace muy buenos progresos.' WHERE `ID`=7687;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안타깝게도 그대와 같이 경험 많은 이에게 제가 할 수 있는 일은 거의 없습니다. 다르나서스 장인의 정원에 거주하는 나이트 엘프 실반나 포레스트문을 찾아가 보십시오.', `FemaleText_loc4`='不幸的是，对于拥有像你这样经历的人来说我没有什么可教的，我的朋友。找到暗夜精灵希尔瓦娜·林月，她住在达纳苏斯的工匠区。', `FemaleText_loc5`='不幸的是，對於擁有像你這樣經歷的人來說我沒有什麼可教的，我的朋友。找到夜精靈希爾瓦娜·林月，她住在達納蘇斯的工匠區。', `FemaleText_loc7`='Desafortunadamente, puedo enseñar muy poco a alguien con tu experiencia, $gamigo:amiga;. Busca a la elfa de la noche Sylvanna Bosqueluna, vive en el Bancal del Artesano de Darnassus.' WHERE `ID`=7688;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='엘룬 아도레, $g형제:자매;여, 잘 오셨습니다.', `FemaleText_loc4`='Elune-adore，我的$g兄弟:姐妹;。欢迎来到这里。', `FemaleText_loc5`='(達納蘇斯語)願伊露恩與你同在，我的$g兄弟:姐妹;。我們這裡歡迎你。', `FemaleText_loc7`='Elune-adora, $ghermano:hermana;. Sé $gbienvenido:bienvenida;.' WHERE `ID`=7689;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='숲에 있는 식물로 창조할 수 있는 것들이 정말 놀랍지 않습니까? 실로 엘룬께서 우리를 아낌없이 축복하셨습니다.', `FemaleText_loc4`='人们从森林植物中制造的东西难道不令人震惊吗？说真的，月神对我们已经很慷慨了。', `FemaleText_loc5`='人們從森林植物中製造的東西難道不令人震驚嗎?說真的，伊露恩對我們已經很慷慨了。', `FemaleText_loc7`='¿No es asombroso lo que puede crearse a partir de las plantas del bosque? Realmente Elune nos ha bendecido con sus dones.' WHERE `ID`=7690;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저를 찾아 주시니 감사하지만 그대는 제 능력을 능가하시는군요. 바로 저쪽 편에 있는 실반나 포레스트문을 만나 보세요. 그녀가 제자로 삼을 만한 이를 찾고 있더군요.', `FemaleText_loc4`='不幸的是，对于拥有像你这样经历的人来说我没有什么可教的，我的朋友。去找暗夜精灵希尔瓦娜·林月，她住在达纳苏斯的工匠区。', `FemaleText_loc5`='不幸的是，對於擁有像你這樣經歷的人來說我沒有什麼可教的，我的朋友。去找夜精靈希爾瓦娜·林月，她住在達納蘇斯的工匠區。', `FemaleText_loc7`='Has sido muy amable viniendo a buscarme, pero tus habilidades superan a las mías. Ve a hablar con Sylvanna Bosqueluna, está ahí mismo. Está buscando un nuevo alumno.' WHERE `ID`=7691;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사랑스러운 칼리가 당신을 여기로 보냈나? 눈에 넣어도 아프지 않을 만큼 사랑스럽지...', `MaleText_loc4`='是我亲爱的恋人卡利派你来找我的？她可是我的宝贝。', `MaleText_loc5`='是我親愛的戀人卡利派你來找我的?她可是我的寶貝。', `MaleText_loc7`='¿Mi tierna Kali te ha enviado hasta mí? Es la niña de mis ojos.' WHERE `ID`=7692;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나의 사랑스러운 칼리 얘기를 하려고 온 것 같진 않군. 그렇다면 좋아, 물약에 대해 얘기를 하지. 당신은 너무 융통성이 없다고 누가 말해주지 않든가?', `MaleText_loc4`='没想到你会来这儿找我的可爱的卡利谈话。很好。这是药水。有没有人说过你是个头脑简单的家伙？', `MaleText_loc5`='沒想到你會來這兒找我的可愛的卡利談話。很好。這是藥水。有沒有人說過你是個頭腦簡單的傢伙?', `MaleText_loc7`='No creo que estés aquí para hablar de mi adorable Kali. Bueno, veamos. Se trata de pociones. ¿Te han dicho ya que eres de ideas fijas?' WHERE `ID`=7693;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 내 능력 밖이군. 아이언포지 땜장이 마을에 사는 노움인 탈리 베리피즈에게 가서 졸라보시오. 아, 그리고 가는 김에 사랑스러운 칼리에게 안부도 좀 전해주시오.', `MaleText_loc4`='我教不了你，$n。去找塔雷·浆泡；她是一个侏儒，住在铁炉堡的侏儒区。哦，既然你反正要去，请把我的爱带给卡利。', `MaleText_loc5`='我教不了你，$n。去找塔利·漿泡;她是一個地精，住在鐵爐堡的地精區。哦，既然你反正要去，請把我的愛帶給卡利。', `MaleText_loc7`='Tus habilidades me superan, $n. Ve a molestar a Tally Burbubaya en Ciudad Manitas, en Forjaz. Oh, y ya que vas hacia allá, dale a Kali todo mi amor.' WHERE `ID`=7694;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크고 순진해 보이는 그녀의 눈을 보고 착각하지 말게나. 탈리는 대단한 전문가야. 매일 새로운 것을 배우곤 하지. 내가 왜 땜장이 마을에 있다고 생각하나? 내가 기술자로 보이나? 그래, 당연히 아니지.', `MaleText_loc4`='别被那些天真的大眼睛欺骗了。塔雷是个专家，我每天都在学习新知识。你认为我为什么会在侏儒区？你看我像个工程师吗？啊，我可不这么想。', `MaleText_loc5`='別被那些天真的大眼睛欺騙了。塔利是個專家，我每天都在學習新知識。你認為我為什麼會在地精區?你看我像個工程師嗎?啊，我可不這麼想。', `MaleText_loc7`='No dejes que esos ojos grandes e inocentes te engañen. Tally es una auténtica experta, con ella aprendo algo nuevo cada día. ¿Por qué crees que estoy si no en Ciudad Manitas? ¿Te parezco un ingeniero? Vaya, creía que no.' WHERE `ID`=7695;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘 좀 써보라고! 고된 일과 결단력만이 살길이야! 책만 보면 모든 걸 배울 수 있다는 녀석들은 쳐다보지도 말게.', `MaleText_loc4`='$g小伙子:姑娘;，努力吧。苦干和决心——那就是成功之道！书本知识是远远不够的。', `MaleText_loc5`='$g小夥子:小姑娘;，努力吧。苦幹和決心 - 那才是成功之道!書本知識是遠遠不夠的。', `MaleText_loc7`='Esfuérzate $gmuchacho:muchacha;. Trabajo duro y determinación, ¡así hay que hacerlo! No dejes que nadie te diga que todo lo que necesitas es estudiar un libro.' WHERE `ID`=7696;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠, 자네에겐 가르칠 게 하나도 없군. 저기 있는 탈리 베리피즈에게 가 보게. 탁자에 겨우 팔이 닿는 키지만 물약을 제조할 때는 조심하는 게 좋다네!', `MaleText_loc4`='哦，我不能教给你什么，$n。跟塔雷·浆泡谈谈。她几乎够不着桌子，但是当她在配制药水时，你得看仔细了！', `MaleText_loc5`='哦，我無法教你任何東西，$n。跟那邊的塔利·漿泡談談。她幾乎搆不著桌子，但是當她在配製藥水時，你得小心一點!', `MaleText_loc7`='Oj, no puedo enseñarte nada, $n. Habla con Tally Burbubaya. Casi no llega a la mesa, pero si empieza a preparar una poción ¡presta atención!' WHERE `ID`=7697;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모험을 찾고 있는 게로군. 나도 말이야... 우리 트롤이 이곳으로 왔을 때 지겹게 모험을 찾아 다녔지. 이제는 하루하루를 다른 이들을 가르치면서 그들의 모험담을 듣는 낙으로 살지.', `MaleText_loc4`='你看起来像是个喜欢冒险的人。而我，自从我们巨魔来到这里我就受够冒险了。现在我每天都是既来之则安之，而且我为自己训练其他家伙处理冒险的经历。', `MaleText_loc5`='你看起來像是個喜歡冒險的人。而我，自從我們食人妖來到這裡我就受夠冒險了。現在我每天都是既來之則安之，而且我訓練其他傢伙替我冒險。', `MaleText_loc7`='Parece que andas en busca de aventuras. Yo ya tuve bastantes cuando los trols vinimos aquí. Ahora me dedico a pasar los días tal y como vienen, e instruyo a otros para que pasen aventuras por mí.' WHERE `ID`=7698;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음 수업을 받을 준비가 됐나? 좋아, 그렇다면 먼저 긴장을 풀게. 물약을 올바르게 저으려면 긴장하면 안 돼.', `MaleText_loc4`='准备好接受下一次训练了吗？好吧。首先，你得放松。随意搅动药水就可以了。', `MaleText_loc5`='準備好接受下一次訓練了嗎?好吧。首先，你得放鬆。隨意攪動藥水就可以了。', `MaleText_loc7`='¿$GListo:Lista; para otra lección? Muy bien, veamos. En primer lugar, relájate. Tienes que estar $grelajado:relajada; para agitar bien una poción.' WHERE `ID`=7699;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게는 너무 어려운 요청이군. 오그리마 골목길에 있는 오크 옐마크를 만나 보면 자네를 도와줄 걸세.', `MaleText_loc4`='你的问题我都回答不了，$n。你需要与奥格瑞玛暗巷区的兽人耶尔玛克谈谈。他会帮你的。', `MaleText_loc5`='你的問題我都回答不了，$n。你需要與奧格瑪暗巷區的獸人耶爾瑪克談談。他會幫你的。', `MaleText_loc7`='Tienes preguntas, pero son demasiado grandes para poder responderlas, $n. Tendrás que hablar con el orco Yelmak en La Calle Mayor de Orgrimmar. Él te ayudará.' WHERE `ID`=7700;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탁자에 있는 물약은 전부 내가 오늘 만든 것이지. 냄비를 쳐다보고 있으면 절대 끓지 않는다고 그러더군. 하하!', `MaleText_loc4`='桌上的所有瓶子中都盛有今天配制好的药水。心急吃不到热豆腐。哈哈！', `MaleText_loc5`='桌上的所有瓶子中都盛有今天配製好的藥水。心急吃不到熱豆腐。哈哈!', `MaleText_loc7`='Todas estas botellas son las pociones que he preparado hoy. Y decían que si se vigila un caldero nunca hierve. ¡Ja!' WHERE `ID`=7701;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다들 나보고 멍청하다고 했지만 그들에게 보여주고 말겠어. 여기 있는 모든 냄비를 쳐다보고 있다가 그래도 물약이 끓는다는 것을 증명해 보이겠어! 꼭 성공할 거야! 이제 누가 진짜 멍청한지 말해봐! 말해보라고!', `MaleText_loc4`='他们说我愚蠢，我要证明自己的实力。我要关注所有的罐子，证明它们都能煮东西。我的好运就要来了！谁是愚蠢的人，嗯？嗯！？', `MaleText_loc5`='他們說我愚蠢，我要證明自己的實力。我要關注所有的罐子，證明它們都能煮東西。我的好運就要來了!誰是愚蠢的人，嗯?嗯!?', `MaleText_loc7`='Decían que era estúpido... pero ahora verán. Voy a vigilar todas las ollas que tengo y demostraré que pueden hervir cualquier cosa. Sí, ¡esto marcha! ¿Quién es ahora el estúpido, eh? ¡¿Eh?!' WHERE `ID`=7702;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 자넬 도와줄 수 없어. 자넨 나보다 물약에 대해 더 많이 알고 있네. 게다가 난 이 냄비들을 계속 쳐다봐야 한다고. 저기 있는 옐마크에게 가 보게. 저 친구는 물약에 대해 많이 알고 있으니까 말이야.', `MaleText_loc4`='不能帮你。你比我更懂药剂。还有，我还要看着罐子。去找那边的Yelmak谈谈。他懂得很多药剂的知识。', `MaleText_loc5`='不能幫你。你比我更懂藥劑。還有，我還要看著罐子。去找那邊的耶爾瑪克談談。他懂得很多藥劑的知識。', `MaleText_loc7`='No puedo ayudarte. Sabes más que yo de pociones. Además, tengo que vigilar estas ollas. Habla con Yelmak. Sabe mucho de pociones.' WHERE `ID`=7703;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='베나는 마치 신들린 것처럼 일을 한다네. 잠도 안 자고 밥도 안 먹고 밤낮으로 물약 제조에만 파묻혀 있었지. 나도 언데드 동맹들이 도움을 필요로 한다는 것을 모르는 건 아니지만 저러다가 쓰러지고 말지.', `MaleText_loc4`='本娜就像着魔一样工作。她日以继夜地调制这些药剂，不吃不睡。我知道我们的亡灵盟友需要帮助，但是我担心她这样会伤身体的。', `MaleText_loc5`='貝娜就像著魔一樣工作。她日以繼夜地調製這些藥劑，不吃不睡。我知道我們的不死族盟友需要幫助，但是我擔心她這樣會傷身體的。', `MaleText_loc7`='Bena trabaja como una posesa. La he visto encorvada día y noche sobre estas pociones, casi siempre sin comer ni dormir. Sé que nuestros aliados no-muertos necesitan ayuda, pero empiezo a temer que acabará haciéndose daño.' WHERE `ID`=7704;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 처음 물약을 만들기 시작했을 때 약병을 수도 없이 깼지. 내 서툰 손놀림에 유리 약병이 너무 쉽게 깨진 걸세. 자넨 나보다는 조심성이 있기를 바라네.', `MaleText_loc4`='在我首次开始配制药水时，我一定打碎过成百个瓶子。我笨手笨脚，瓶子在我手中极易破碎。希望你比我更为小心。', `MaleText_loc5`='在我首次開始配製藥水時，我一定打碎過成百個瓶子。我笨手笨腳，瓶子在我手中極易破碎。希望你比我更為小心。', `MaleText_loc7`='Debo haber roto cientos de viales cuando empecé a preparar pociones. El cristal era demasiado frágil entre mis torpes manos. Espero que seas más $gcuidadoso:cuidadosa; que yo.' WHERE `ID`=7705;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네의 능력이 나를 능가했군. 더 많은 것을 배우고 싶다면 저기에 있는 베나 윈터후프에게 가는 것이 좋을 걸세. 하지만 베나도 쉬어야 하니까 시간을 너무 많이 뺐지는 말게나.', `MaleText_loc4`='你学习的能力已经超过我了。你需要找那边的本娜·冰蹄谈谈以获得更多指示。但请不要占用她太多时间。她需要休息。', `MaleText_loc5`='你學習的能力已經超過我了。你需要找那邊的貝娜·冬蹄談談以獲得更多指示。但請不要佔用她太多時間。她需要休息。', `MaleText_loc7`='Tu capacidad de aprendizaje me ha superado. Tendrás que hablar con Bena Pezuña Invernal para seguir tu instrucción. Pero por favor, no pases mucho tiempo con ella. Necesita descansar.' WHERE `ID`=7706;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정다운 얼굴을 보니 좋군. 연금술사 요한은 뭔가 원하는 것이 있을 때만 잡담을 늘어놓지. 그는 무덤 밖에 너무 오래 있었네. 언젠가는 나도 그렇게 되겠지. 소름 끼치지만 그때쯤이면 별로 신경 쓰지 않을지도 모르겠군.', `FemaleText_loc4`='能看到一张友善的脸真不错。我没有跟药剂师乔汉聊过很多，除非他想要什么东西。他离开坟墓太久了。有一天我也会像他一样，我听说。真可怕。或许到那时我就不在乎了。', `FemaleText_loc5`='能看到一張友善的臉真不錯。我沒有跟藥劑師喬漢聊過很多，除非他想要什麼東西。他離開墳墓太久了。有一天我也會像他一樣，我聽說。真可怕。或許到那時我就不在乎了。', `FemaleText_loc7`='Me alegro de ver un rostro amistoso. El boticario Johann no me da mucha charla, a no ser que quiera algo. Ha estado demasiado tiempo fuera de la tumba. Algún día yo también seré así... se supone. Espeluznante. Aunque quizás entonces ya no me importe.' WHERE `ID`=7707;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='물약에 대해 배우러 왔다고? 가르쳐 줄 것이 아주 많다네. 죽은 몸이긴 하지만 아직은 머리까지 죽진 않았네.', `FemaleText_loc4`='你是来学习配制药水的？我能传授给你很多知识。虽然我已年老力衰，但脑子还是管用的。', `FemaleText_loc5`='你是來學習配製藥水的?我能傳授給你很多知識。雖然我已年老力衰，但腦子還是管用的。', `FemaleText_loc7`='¿Has venido a aprender a hacer pociones? Tengo mucho que enseñarte. Quizás esté muerta, pero no he perdido mis sesos. Todavía.' WHERE `ID`=7708;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='같이 지내게 된다면 좋겠지만 현실을 직시하자고. 자넨 나보다 물약 제조 경험이 더 많잖나. 더 많은 것을 배우고 싶으면 언더시티 연금술 실험실에 있는 포세이큰인 학자 마쉬를 찾아가게.', `FemaleText_loc4`='我很珍惜我们之间的友谊，但是让我们面对现实吧：你对药水的了解比我多。要是你想得到训练的话，就找亡灵马尔什医生谈谈。他居住在幽暗城的炼金房。', `FemaleText_loc5`='我很珍惜我們之間的友誼，但是讓我們面對現實吧:你對藥水的瞭解比我多。要是你想得到訓練的話，就找被遺忘者馬許醫生談談。他居住在幽暗城的鍊金房。', `FemaleText_loc7`='Agradezco la compañía, pero vamos a decirlo claro: tienes más experiencia que yo con las pociones. Ve a hablar con el doctor Marsh si quieres recibir instrucción. Es un Renegado, lo encontrarás en El Apothecarium de Entrañas.' WHERE `ID`=7709;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한때는 나도 인간이었네. 인간의 약점이 우리에게는 이점이 되기도 하지. 난 인간의 약점을 속속들이 알거든.', `MaleText_loc4`='这是真的，我曾经是人类。缺点是可能转换为我们的优势的，$n，因为我对人类的劣势了如指掌。', `MaleText_loc5`='這是真的，我曾經是人類。缺點是可能轉換為我們的優勢的，$n，因為我對人類的劣勢瞭若指掌。', `MaleText_loc7`='Es cierto, una vez fui humano. Lo que normalmente sería una deficiencia nos servirá de ventaja, $n. Conozco íntimamente las debilidades humanas.' WHERE `ID`=7710;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아. 표본에서 살점을 더 잘라내 보게. 자, 이제까지 배운 것을 시험해 볼까나. 시험을 기초로 더 많은 것을 배울 수 있을 걸세.', `MaleText_loc4`='很好。从这些标本上再切下一块肉来。让我们看看你学到了什么，我们可以由此开始。', `MaleText_loc5`='很好。從這些標本上再切下一塊肉來。讓我們看看你學到了什麼，我們可以由此開始。', `MaleText_loc7`='Muy bien. Corta otro pedazo de carne de uno de estos especimenes. Vamos a probar lo que has aprendido hasta ahora, y avanzaremos desde allí.' WHERE `ID`=7711;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물약에 대한 지식이 나를 능가했군. 하지만 자넨 아직도 더 배울 것이 많네. 동남쪽 계단을 따라 올라가서 학자 마쉬를 만나 보게나. 그가 진정한 고통을 가르쳐 줄 걸세... 에헴! 학자 마쉬는 포세이큰으로서 자네에게 많은 것을 가르쳐 줄 것이야.', `MaleText_loc4`='你对药剂的知识已经远胜于我，但你还有很多要学的。上楼去到东南面见见马尔什医生。他会交给你真正的苦痛——啊咳。他是一个被遗忘者，他能进一步训练你。', `MaleText_loc5`='你對藥劑的知識已經遠勝於我，但你還有很多要學的。上樓去到東南面見見馬許醫生。他會交給你真正的苦痛─啊咳。他是一個被遺忘者，他能進一步訓練你。', `MaleText_loc7`='Tu saber sobre pociones ha superado al mío, pero todavía tienes mucho que aprender. Sube las escaleras hacia el Sureste y visita al doctor Marsh. Te enseñará a sufr... ejem... Es un Renegado y continuará tu instrucción.' WHERE `ID`=7712;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇게 쳐다보지 마시오! 당신과 같은 모험가는 아니어도 근육정도는 있다오. 물약을 휘저으면 팔이 이렇게 강해지지.', `MaleText_loc4`='别那样看我。我也许跟你不同，我不是个冒险家，但是这并不意味着我的力量比你小。忙碌的生活会让你的手臂变得强壮的。', `MaleText_loc5`='別那樣看我。我也許跟你不同，我不是個冒險家，但是這並不意味著我的力量比你小。忙碌的生活會讓你的手臂變得強壯的。', `MaleText_loc7`='Deja de mirarme así. Puede que no sea un aventurero como tú, pero eso no significa que no pueda tener algún músculo. Tanto agitar fortalece los brazos.' WHERE `ID`=7713;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네에겐 더 가르칠 게 더 없군. 하지만 자네를 가르칠 만한 나이트 엘프를 하나 알고 있다네. 에이네실이라고 다르나서스 장인의 정원에 살고 있으니 그리 가 보게.', `MaleText_loc4`='我没有什么可教你的了。但是，我听说有位名叫安尼希尔的暗夜精灵也许能教你。她居住在达纳苏斯的工匠区。', `MaleText_loc5`='我沒有什麼可教你的了。但是，我聽說有位名叫安尼希爾的夜精靈也許能教你。她居住在達納蘇斯的工匠區。', `MaleText_loc7`='No puedo enseñarte nada más. Pero he oído hablar de una elfa de la noche que podría hacerlo. Su nombre es Ainethil y vive en el Bancal del Artesano de Darnassus.' WHERE `ID`=7714;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미안하지만 난 초보자를 가르칠 시간은 없네. 자네 기술 숙련도에 맞는 자를 찾아보도록 하게나. 다르나서스 장인의 정원에 있는 나이트 엘프 밀라 페어랜코라에게 가 보는 게 좋겠군.', `MaleText_loc4`='很抱歉，$n，但是我可不在新手身上浪费时间。你得找一个跟自己技能相近的人。去达纳苏斯的工匠区找一个名叫米拉·法拉科纳的暗夜精灵。', `MaleText_loc5`='很抱歉，$n，但是我可不在新手身上浪費時間。你得找一個跟自己技能相近的人。去達納蘇斯的工匠區找一個名叫米拉·法拉科納的夜精靈。', `MaleText_loc7`='Lo siento, $n, pero no tengo tiempo que perder con novatos. Necesitas a alguien que esté más cerca de tu nivel. Intenta hablar con la elfa de la noche Milla Fairancora, en el Bancal del Artesano de Darnassus.' WHERE `ID`=7715;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기초 공부를 열심히 했군. 이제는 수준을 좀 올려야겠어.', `MaleText_loc4`='你已经花时间学习基础知识了。现在该提高了。', `MaleText_loc5`='你已經花時間學習基礎知識了。現在該升級的時候。', `MaleText_loc7`='Has invertido tu tiempo en estudiar los principios básicos. Es hora de subir el listón.' WHERE `ID`=7716;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 도움이 필요하다고? 좋아. 뭘 도와줄까?', `MaleText_loc4`='你需要我的帮助？可以。你需要什么？', `MaleText_loc5`='你需要我的幫助?可以。你需要什麼?', `MaleText_loc7`='¿Quieres mi ayuda? La tienes. ¿Qué necesitas?' WHERE `ID`=7717;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='말똥말똥한 눈과 무성한 수염을 보고 착각하지 말라고요. 보수르는 유능한 수습생이자 좋은 친구랍니다. 얘기할 때 목에 쥐가 날 것 같기는 하지만...', `FemaleText_loc4`='别被沃萨亮晶晶的眼睛和浓密的胡须愚弄了。他是个很有才能的学徒，也是个很好的朋友，即使我在跟他谈话时颈部有些痉挛。', `FemaleText_loc5`='別被沃薩亮晶晶的眼睛和濃密的鬍鬚愚弄了。他是個很有才能的學徒，也是個很好的朋友，即使我在跟他談話時頸部有些痙攣。', `FemaleText_loc7`='No dejes que sus ojos pequeños y brillantes y su tupida barba te engañen. Vosur es un aprendiz con mucho talento y un buen amigo... aunque siempre me da tortícolis cuando le hablo.' WHERE `ID`=7718;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='음... 제가 가르칠만한 것은 이미 다 아시네요. 이제 다른 스승을 찾아갈 시간입니다. 다르나서스 장인의 정원에 있는 나이트 엘프 에이네실을 한 번 찾아가 보세요. 정말 유능한 나이트 엘프랍니다!', `FemaleText_loc4`='嗯，我能教的你已经都学会了。或许你该找其他人谈谈了。试一下达纳苏斯工匠区的暗夜精灵安尼希尔。她确实很有智慧！', `FemaleText_loc5`='嗯，我能教的你已經都學會了。或許你該找其他人談談了。試一下達納蘇斯工匠區的夜精靈安尼希爾。她確實很有智慧!', `FemaleText_loc7`='Um, ya sabes todo lo que puedo enseñarte. Quizás haya llegado el momento de que vayas a hablar con algún otro. Ve a ver a ver a la elfa de la noche Ainhethil, en el Bancal del Artesano de Darnassus. ¡Tiene auténtico talento!' WHERE `ID`=7719;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나쁘지 않은데요! 좋아요. 그럼 심부름 하나 해보시겠어요?', `FemaleText_loc4`='嗨，实际上没有这么坏。好吧，那么。你想怎么为我办差呢？', `FemaleText_loc5`='嗨，實際上沒有這麼壞。好吧，那麼。你想怎麼為我辦差呢?', `FemaleText_loc7`='Eh, no está tan mal. Muy bien, veamos. ¿Te gustaría hacerme un recado?' WHERE `ID`=7720;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋아요. 저기 있는 보수르에게 뭔가 보여 주세요. 모르는 것이 있으면 물어보시면 될 거예요.', `FemaleText_loc4`='那很好，$n。无论那是什么，去拿给那边的沃萨看看。他会回答你的任何问题。', `FemaleText_loc5`='那很好，$n。無論那是什麼，去拿給那邊的沃薩看看。他會回答你的任何問題。', `FemaleText_loc7`='Muy bien, $n. Ve a enseñarle lo que sea a Vosur, está ahí mismo. Él responderá a todas tus preguntas.' WHERE `ID`=7721;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='누구신데 절 귀찮게 하시죠? 아, 맞다. 물약 제조에 대해 배우려는 분이시군요. 좋아요. 뭘 도와 드릴까요?', `FemaleText_loc4`='你是谁？为什么骚扰我？哦，是啦——你是学生吧。是的。我能为你做什么吗？', `FemaleText_loc5`='你是誰?為什麼騷擾我?哦，是啦─你是學生吧。是的。我能為你做什麼嗎?', `FemaleText_loc7`='¿Quién eres y por qué me molestas? Oh, sí... $gun:una; estudiante de pociones. Muy bien. ¿Qué puedo hacer por ti?' WHERE `ID`=7722;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이시누 달 디에브, $n. 지식을 추구하려 오셨나요?', `FemaleText_loc4`='和平也与你同在, $n。你是来寻求知识的吗？', `FemaleText_loc5`='(達納蘇斯語)祝你與家人好運, $n。你是來尋求知識的嗎?', `FemaleText_loc7`='Ishnu-dal-dieb, $n. ¿Has venido aquí buscando conocimiento?' WHERE `ID`=7723;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가르친다는 것은 주기만 하는 것이 아닙니다. 당신을 가르침으로써 저 또한 배우고 제가 가진 지식도 늘어가는 것이지요.', `FemaleText_loc4`='教学不只是一项单边活动，$n。当我教你时，我自己也在学习，而我的理解也在加深。', `FemaleText_loc5`='教學不只是一項單邊活動，$n。當我教你時，我自己也在學習，而我的理解也在加深。', `FemaleText_loc7`='El aprendizaje no va en una sola dirección, $n. Cuando te instruyo, yo también aprendo, y crecen mi saber y conocimientos.' WHERE `ID`=7724;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='죄송합니다만 초보자는 가르치지 않습니다. 저 대신 다르나서스 장인의 정원에 있는 밀라 페어랜코라를 찾아가 보십시오. 소비한 시간이 아깝지 않을 것입니다.', `FemaleText_loc4`='我很抱歉，$n，但是我不给新手提供培训。你应该找达纳苏斯工匠区的米拉·法拉科纳谈谈。她可以帮你弥补损失的时间。', `FemaleText_loc5`='我很抱歉，$n，但是我不給新手提供培訓。你應該找達納蘇斯工匠區的米拉·法拉科納談談。她可以幫你彌補損失的時間。', `FemaleText_loc7`='Mis disculpas, $n, pero no ofrezco instrucción a novatos. Ve a hablar con Milla Fairancora en el Bancal del Artesano de Darnassus. Ella te ayudará a recuperar el tiempo perdido.' WHERE `ID`=7725;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신은 물약 제조의 기초를 배우셨습니다. 하지만 더 많은 것을 배우려면 더욱 정진해야 합니다. 임무를 완수하여 당신이 진정 헌신하고 있음을 증명해 보이십시오.', `FemaleText_loc4`='你已经学会了制作药剂的基础知识，但是要想深化学习需要更加投入。为我完成一项任务以证明你做出的贡献。', `FemaleText_loc5`='你已經學會了製作藥劑的基礎知識，但是要想深化學習需要更加投入。為我完成一項任務以證明你做出的貢獻。', `FemaleText_loc7`='Has aprendido los principios básicos de la preparación de pociones, el estudio, a partir de ahora, exige un compromiso mayor. Prueba tu dedicación pidiéndome una tarea.' WHERE `ID`=7726;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제 능력을 인정하시니 기쁘지만 당신은 이미 제 능력을 앞질렀습니다. 다르나서스 장인의 정원으로 가셔서 나이트 엘프인 에이네실을 만나시면 그녀가 당신을 도와줄 것입니다.', `FemaleText_loc4`='虽然我很高兴听到你对我的能力充满信心，但我真的没法再教你了。你必须到达纳苏斯的工匠区去找暗夜精灵安尼希尔谈谈。她可以帮助你。', `FemaleText_loc5`='雖然我很高興聽到你對我的能力充滿信心，但我真的沒法再教你了。你必須到達納蘇斯的工匠區去找夜精靈安尼希爾談談。她可以幫助你。', `FemaleText_loc7`='Aunque me siento halagada por tu confianza en mis habilidades, instruirte queda fuera de mi alcance. Debes ir al Bancal del Artesano de Darnassus y hablar con la elfa de la noche Ainethil. Ella podrá ayudarte.' WHERE `ID`=7727;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='물약의 재료를 조금만 바꿔도 완전히 다른 물약이 된답니다. 인내와 정확성이 필요한 것이지요. 이 두 요소는 삶의 모든 영역에서 도움이 될 겁니다.', `FemaleText_loc4`='即使轻微地改变药剂的成份也能使它发生根本的变化。耐心和精确，年轻人：他们会让你在所有行业都受益匪浅。', `FemaleText_loc5`='即使輕微地改變藥劑的成份也能使它發生根本的變化。耐心和精確，年輕人:他們會讓你在所有行業都受益匪淺。', `FemaleText_loc7`='Hasta las más ligeras modificaciones en los ingredientes de una poción pueden cambiarla radicalmente. Paciencia y precisión, joven: te ayudarán en los caminos de la vida.' WHERE `ID`=7728;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제 물약 제조술은 그대에 비해 수준이 낮습니다. 이제 저기에 있는 에이네실을 만나도 되겠군요. 그녀도 그대가 좀 더 수준이 높은 교육을 받을 시간이 되었다는 것을 알아볼 것입니다.', `FemaleText_loc4`='我制造药剂的技能在你之下。你应该与那边的安尼希尔谈谈。她会明白你需要进一步的培训。', `FemaleText_loc5`='我製造藥劑的技能在你之下。你應該與那邊的安尼希爾談談。她會明白你需要進一步的培訓。', `FemaleText_loc7`='Mi habilidad creando pociones es inferior a la tuya. Estás $glisto:lista; para hablar con Ainethil. Ella comprenderá que estás $gpreparado:preparada; para seguir tu instrucción.' WHERE `ID`=7729;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='흠... 솜씨가 괜찮아 보이는군요. 경험이 충분한 것 같으니 제 일을 좀 도와주시겠어요?', `FemaleText_loc4`='你的技能并不是毫无可取之处的。既然你看起来经验非常丰富，有一件事情我需要你的帮助。', `FemaleText_loc5`='你的技能並不是毫無可取之處的。既然你看起來經驗非常豐富，有一件事情我需要你的幫助。', `FemaleText_loc7`='Tu habilidad es considerable. Como parece que tienes la suficiente experiencia, hay un asunto para el que necesito tu ayuda.' WHERE `ID`=7730;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 젊음이란... 물약을 처음 접했을 때는 또 어떻고... 기억을 상기시켜줘서 고맙습니다. 이제 저기에 있는 밀라 페어랜코라와 젊은 열정을 나누어 보세요.', `FemaleText_loc4`='啊，又回到年轻的时候了，还有第一次发现药剂的时候。谢谢你恢复我的记忆，$n。去跟那边的米拉·法拉科纳分享那份年轻的热情吧。', `FemaleText_loc5`='啊，又回到年輕的時候了，還有第一次發現藥劑的時候。謝謝你恢復我的記憶，$n。去跟那邊的米拉·法拉科納分享那份年輕的熱情吧。', `FemaleText_loc7`='Ah, ser joven de nuevo, y descubrir pociones por primera vez. Gracias por refrescar mi memoria, $n. Ahora ve a compartir tu entusiasmo juvenil con Milla Fairancora, está ahí mismo.' WHERE `ID`=7731;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전 오랫동안 물약 제조법에 대해 많은 것을 배웠습니다. 이제는 그 지식을 그대에게 전해드릴 테니 말씀만 하십시오.', `FemaleText_loc4`='我已经用多年学会了很多药剂知识，$n，而那些知识都由你支配。你只需提要求就可以。', `FemaleText_loc5`='我已經用多年學會了很多藥劑知識，$n，而那些知識都由你支配。你只需提要求就可以。', `FemaleText_loc7`='A lo largo de los años he aprendido mucho sobre pociones, $n, y todo ese saber está a tu disposición. Solo tienes que preguntar.' WHERE `ID`=7732;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 바쁩니다, $n. 무슨 일로 왔든 우트에게 가 보십시오. 그 풋내기 녀석... 온종일 뭔가 푹푹 끓이고만 있는데, 계속 저러다간 무슨 일이 나고 말 겁니다.', `MaleText_loc4`='我很忙，$n。告诉伍特去处理一切。那个年轻人整天都焦虑不安的。他大部分时间都处于这种状态，像是要做些什么。', `MaleText_loc5`='我很忙，$n。告訴伍特去處理一切。那個年輕人整天都焦慮不安的。他大部分時間都處於這種狀態，像是要做些什麼。', `MaleText_loc7`='Estoy ocupado, $n. Di a Whuut que se ocupe de lo que sea. Ese joven cachorro se ha pasado todo ante el fuego. Pasa demasiado tiempo así, terminará causando algún daño.' WHERE `ID`=7733;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='만나서 영광이오, $n. 당신의 연금술 기술이 내 솜씨보다 낫군. 언더시티 연금술 실험실에 있는 언데드 학자 허버트 핼시를 찾아가 보시오. 이제부터는 그가 도와줄 것이오.', `MaleText_loc4`='见到你是我的荣幸，$n，但是你在配制药水方面比我厉害。去幽暗城 炼金房找亡灵赫伯特·哈尔希医生。他能帮助你。', `MaleText_loc5`='見到你是我的榮幸，$n，但是你在配製藥水方面比我厲害。去幽暗城 鍊金房找亡靈赫伯特·哈爾希醫生。他能幫助你。', `MaleText_loc7`='Es un honor verte, $n, pero tus habilidades preparando pociones son mayores que las mías. Ve a ver al doctor Herbert Halsey, un no-muerto de El Apothecarium de Entrañas. Podrá seguir ayudándote.' WHERE `ID`=7734;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 도와줄 만한 이를 찾고 있었는데 말이야. 당신 정도면 기술도 있으니 충분하겠군. 용기만 있다면 말이야.', `MaleText_loc4`='我曾四处寻找帮助。你已经获得了技能，要是你有勇气的话，我猜你会付诸行动的。', `MaleText_loc5`='我曾四處尋找幫助。你已經獲得了技能，要是你有勇氣的話，我猜你會付諸行動的。', `MaleText_loc7`='He estado buscando algo de ayuda. Como tienes la habilidad necesaria supongo que lo harás, siempre y cuando también tengas agallas.' WHERE `ID`=7735;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 잘못 찾아왔군. 난 초보자는 가르치지 않소이다. 저기 있는 우트라는 젊은이에게 가 보시오. 저 친구랑 얘기할 때 긴 단어는 사용하지 마시오.', `MaleText_loc4`='你找错兽人了。我不训练新手。去问问那边的小伍特……谦虚一点。', `MaleText_loc5`='你找錯獸人了。我不訓練新手。去問問那邊的小伍特...謙虛一點。', `MaleText_loc7`='Estás hablando con el orco equivocado. No entreno a novatos. Habla con el joven Whuut... y usa palabras sencillas.' WHERE `ID`=7736;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 다른 학생이로군? 좋아. 도와주도록 하지.', `MaleText_loc4`='另一名学生，是吗？好吧。我看看有什么能帮助你的。', `MaleText_loc5`='另一名學生，是嗎?好吧。我看看有什麼能幫助你的。', `MaleText_loc7`='¿Otro estudiante, eh? Muy bien. Veré qué puedo hacer para ayudarte.' WHERE `ID`=7737;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='글릭스와 난 서로 이해관계가 있지. 글릭스는 나에게 물품을 공급해 주고 나는 글릭스를 부자로 만들어 주거든. 농담은 그만하고! 그 해적놈이 쭈글쭈글한 왕꽃잎풀을 쥐방울만한 주머니에 넣어 주면서 돈을 얼마나 많이 달라고 하는지... 다 큰 고블린도 울 정도라니까.', `MaleText_loc4`='格里克斯和我达成一项共识：他给我供货，而我给他钱。这是很认真的！那个海盗为了一小袋皱皱巴巴的皇血草收我多少钱……足够把一个成年的地精弄哭了。', `MaleText_loc5`='格里克斯和我達成一項共識:他給我供貨，而我給他錢。這是很認真的!那個海賊為了一小袋皺皺巴巴的皇血草收我多少錢...足夠把一個成年的哥布林弄哭了。', `MaleText_loc7`='Glyx y yo tenemos un acuerdo: él se asegura de que yo tenga suministros y yo me aseguro de que él siga siendo rico. ¡En serio! Lo que ese pirata me entrega a cambio de un saquito de sangrerregia... bastaría para hacer llorar a un goblin adulto.' WHERE `ID`=7738;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 좋은 제조법을 아주 많이 보유하고 있다고. 자, 이거 보라고... 게다가 할인도 해 준다니까!', `MaleText_loc4`='我有许多处方可供选择，我还可以为你打折！', `MaleText_loc5`='我有許多處方可供選擇，我還可以為你打折!', `MaleText_loc7`='Tengo un montón de grandes recetas a las que puedes echar un vistazo, ¡y con descuentos!' WHERE `ID`=7739;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐 하는 거지? 내 명성을 망치려 하는 건가? 난 초보자 연금술사는 가르치지 않는다고. 오그리마 골목길에 있는 우트라는 오크한테 가 봐. 그 친구가 자네 수준에 잘 맞을 거야. 머리에 든 것도 말이야.', `MaleText_loc4`='这是什么？你试图毁坏我的名声？我不教新手的，$g老兄:女士;。试试找奥格瑞玛暗巷区的兽人伍特谈谈。他很接近你的技术水平。还有智力水平。', `MaleText_loc5`='這是什麼?你試圖毀壞我的名聲?我不教新手的，$g老兄:女士;。試試找奧格瑪暗巷區的獸人伍特談談。他很接近你的技術水準。以及智力水準。', `MaleText_loc7`='¿Qué es esto? ¿Intentas arruinar mi reputación? No instruyo a novatos, $gmuchachito:señorita;. Ve a hablar con el orco Whuut en La Calle Mayor de Orgrimmar. Está mucho más cerca de tu nivel. Y de tus sesos.' WHERE `ID`=7740;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='약초들이 너무 비싸! 다른 걸 조금 넣을 수도 있는데... 무슨 말인지 알지? 이 고블린 좀 도와주겠나?', `MaleText_loc4`='草药价格太高啦！我总是使用一点别的东西，如果你明白我的意思的话。帮帮我好吗？', `MaleText_loc5`='草藥價格太高啦!我總是使用一點別的東西，如果你明白我的意思的話。幫幫我好嗎?', `MaleText_loc7`='¡Las hierbas son tan valiosas! Nunca tengo bastante... ya sabes a qué me refiero. ¿Ayudarás a un goblin?' WHERE `ID`=7741;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나보다 훨 낫군! 나보다는 경험이 풍부한 스승이 필요하겠는걸? 그렇다면 아마 다르나서스의 장인의 정원에 사는 나이트 엘프 에이네실 정도가 되겠지.', `MaleText_loc4`='你做得比我要好！你需要一个经验比我还要多的人。那就是安尼希尔，一个在达纳苏斯工匠区生活的暗夜精灵女士。', `MaleText_loc5`='你做得比我要好!你需要一個經驗比我還要多的人。那就是安尼希爾，一個在達納蘇斯工匠區生活的夜精靈女士。', `MaleText_loc7`='¡Eres mejor que yo en esto! Necesitas a alguien con más experiencia que yo. Esa podría ser Ainethil, una elfa de la noche que vive en el Bancal del Artesano de Darnassus.' WHERE `ID`=7742;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='처음으로 언데드를 봤을 땐 그들의 공포와 외로움이 너무 커보였기에 눈물을 흘릴 수밖에 없었습니다. 그때 대지모신께서 제게 말씀하셨지요. 그분께서는 제 핏속에서 노래하셨습니다. 그러시면서 "그들을 구하라."고 말씀하셨답니다.', `FemaleText_loc4`='第一次看见亡灵时，我哭了，我无法想象他们的恐惧和孤寂。大地之母在我耳边吟唱，她告诉我：“拯救他们吧。”', `FemaleText_loc5`='第一次看見亡靈時，我哭了，我無法想像他們的恐懼和孤寂。大地之母在我耳邊吟唱，她告訴我:「拯救他們吧。」', `FemaleText_loc7`='La primera vez que vi a los no-muertos, lloré, no podía imaginarme su horror y soledad. Entonces me habló la Madre Tierra, cantó en mi sangre. Y me dijo: "Sálvalos."' WHERE `ID`=7743;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신은 대지모신께서 사랑스러운 자식인 언데드들을 잃는 것에 대해 고뇌하고 계시다는 것을 느낄 수 없단 말입니까? 한시가 급하니 어서 말해보십시오. 그들이 대지모신에게 돌아갈 수 있도록 도와줘야만 합니다.', `FemaleText_loc4`='你难道感觉不到大地母亲为了她所丢失的孩子，也就是亡灵们，而出现的苦恼吗？快些说，$n。每一秒对我都很珍贵。我们必须帮他们找到回归她身边的路！', `FemaleText_loc5`='你難道感覺不到大地之母為了她所丟失的孩子，也就是亡靈們，而出現的苦惱嗎?快些說，$n。每一秒對我都很珍貴。我們必須幫他們找到回歸她身邊的路!', `FemaleText_loc7`='¿No puedes sentir el dolor de la Madre Tierra por sus hijos perdidos, los no-muertos? Habla deprisa, $n. Cada segundo me es muy valioso. ¡Debemos ayudarles a encontrar el camino de vuelta a ella!' WHERE `ID`=7744;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 양심상 우리 동맹인 언데드들이 고통을 겪고 있는 상황에서 초보자를 가르칠 수는 없습니다. 나 대신 저기 있는 크레이에게 부탁하면 당신을 도와줄 수 있을 겁니다.', `FemaleText_loc4`='当我们的盟友，也就是亡灵们，在遭受可怕苦难时候，我如果还在这里训练新手，这会让我感到良心不安。请找那边的克瑞谈谈；他目前能够帮你。', `FemaleText_loc5`='當我們的盟友，也就是亡靈們，在遭受可怕苦難時候，我如果還在這裡訓練新手，這會讓我感到良心不安。請找那邊的克瑞談談;他目前能夠幫你。', `FemaleText_loc7`='Tengo remordimientos por dedicar mi tiempo a entrenar novatos mientras nuestros aliados, los no-muertos, sufren tan horriblemente. Por favor, habla con Kray en mi lugar, él podrá ayudarte por ahora.' WHERE `ID`=7745;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신은 어느 정도 기술을 지니고 있지만 내가 당신을 가르치는 순간에도 언데드들은 고통받고 있을 겁니다. 내가 시간을 투자할 가치가 있다는 것을 증명해 보십시오.', `FemaleText_loc4`='你的确有些能力，这是真的，但是我花费时间教你的每一刻对亡灵来说都是承受痛苦折磨的每一刻。你必须向我证明值得让我花时间教你。', `FemaleText_loc5`='你的確有些能力，這是真的，但是我花費時間教你的每一刻對亡靈來說都是承受痛苦折磨的每一刻。你必須向我證明值得讓我花時間教你。', `FemaleText_loc7`='Tienes ciertas habilidades, es cierto, pero cada momento que dedico a instruirte es un momento que los no-muertos pasan en el tormento. Demuestra que mereces mi tiempo.' WHERE `ID`=7746;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신의 물약 제조 기술은 나를 능가하는군요. 그렇다면 언더시티 연금술 실험실에 있는 언데드 학자 허버트 핼시를 찾아가도록 하십시오. 그 친구는 당신에게 더 많은 것을 가르칠 수 있는 기술이 있는데다가 당신 눈으로 직접 언데드들의 고통을 목격할 수도 있을 겁니다.', `FemaleText_loc4`='你制造药剂的技术已经在我之上。去幽暗城的炼金房找亡灵赫伯特·哈尔希医生。他可以继续你的训练，而你也可以亲眼目睹他的人民所遭受的苦难。', `FemaleText_loc5`='你製造藥劑的技術已經在我之上。去幽暗城的鍊金房找亡靈赫伯特·哈爾希醫生。他可以繼續你的訓練，而你也可以親眼目睹他的人民所遭受的苦難。', `FemaleText_loc7`='Tus habilidades preparando pociones superan a las mías. Ve a ver al doctor no-muerto Herbert Halsey, en El Apothecarium de Entrañas. Él podrá seguir instruyéndote, y podrás ser testigo de primera mano de los sufrimientos de su pueblo.' WHERE `ID`=7747;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 방해로군. 이런 식으로 나오면 대체 나보고 어떻게 일을 하라는 거요? 대답할 필요 없소. 변명 따위 듣자고 한 말이 아니니까. 만약 이곳을 청소하고 우리 제국의 영토를 확장할 생각이라면 날 좀 가만히 놔두시오!', `MaleText_loc4`='又来打扰我了。像这样我还能做什么工作么？不用回答，我看起来像是很在乎你的回答么？如果我们要把这个地方打理干净，并继续扩展我们的帝国，我就需要绝对的安静！', `MaleText_loc5`='又來打擾我了。像這樣我還能做什麼工作麼?不用回答，我看起來像是很在乎你的回答麼?如果我們要清理這個地方並且擴張我們帝國的話，我需要絕對的安靜!', `MaleText_loc7`='Otra interrupción. ¿Cómo se supone que voy a poder trabajar así? No me respondas, ¿te parece que importará lo que digas? Si queremos limpiar este sitio algún día y expandir nuestro imperio, ¡voy a necesitar silencio absoluto!' WHERE `ID`=7748;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신에게 기술을 가르쳐달라는 말입니까? 왜 이러십니까? 안 된다는 거 알면서... 제 기술이 부족해서 가르칠 게 없습니다. 언더시티 연금술 실험실에 있는 포세이큰 학자 허버트 핼시를 찾아가보십시오.', `MaleText_loc4`='要我训练你？别开玩笑了——我们都知道这是不可能的。我可无法胜任。你要是想接受训练的话，就去幽暗城的炼金房找亡灵赫伯特·哈尔希医生吧。', `MaleText_loc5`='要我訓練你?別開玩笑了─我們都知道這是不可能的。我可無法勝任。你要是想接受訓練的話，就去幽暗城的鍊金房找被遺忘者赫伯特·哈爾希醫生吧。', `MaleText_loc7`='¿Yo, entrenarte? Venga... los dos sabemos que no puedo. Mis propias habilidades se resienten. Si quieres instruirte ve a ver al doctor Herbert Halsey, un Renegado de El Apothecarium de Entrañas.' WHERE `ID`=7749;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 시간을 뺏을 생각이라면 당신이 그럴 가치가 있는 분이라는 걸 제게 증명해 보이십시오. 떡고물이라도 떨어질 수 있을는지 알아봐야겠습니다.', `MaleText_loc4`='如果你要占用我的时间的话，你最好证明自己的价值。毕竟，我应该从这样的安排中获得点什么。', `MaleText_loc5`='如果你要佔用我的時間的話，你最好證明自己的價值。畢竟，我應該從這樣的安排中獲得點什麼。', `MaleText_loc7`='Si vas a hacerme perder el tiempo más vale que demuestres que lo mereces. Después de todo debería sacar algo de este acuerdo.' WHERE `ID`=7750;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 시간을 뺏지 마십시오. 제겐 당신이 살아온 시간보다도 더 오래 연구해 온 과제가 있단 말입니다. 언더시티 연금술 실험실에 있는 박사 마틴 펠벤을 찾아가보십시오. 그 포세이큰이라면 기초부터 가르쳐줄 수 있을 테니까.', `MaleText_loc4`='别浪费我时间。我从事研究的时间比你的年纪还要大。去跟幽暗城炼金房的亡灵马丁·费尔本谈谈。他或许能传授给你一些基础知识。', `MaleText_loc5`='別浪費我時間。我從事研究的時間比你的年紀還要大。去跟幽暗城鍊金房的被遺忘者馬丁·費爾本醫生談談。他或許能傳授給你一些基礎知識。', `MaleText_loc7`='No me hagas perder el tiempo. Tengo proyectos de investigación más viejos que tú. Ve a hablar con el doctor Martin Felben en El Apothecarium de Entrañas. Es un Renegado y seguramente te podrá enseñar los principios básicos.' WHERE `ID`=7751;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새로 온 제자인가? 멋지군. 이래서 라이던은 관리자로 칭송받고 난 여기 처박혀서 교습이나 하는 거겠지. 또다시 올해의 최우수 강사로 선정되는 날에는 민망해서 얼굴도 못 들고 다닐 거야!', `MaleText_loc4`='又一个学生。棒极了。正因为如此，所以在林度恩进入管理阶层的时候，我仍然在坚持作一名教师。只要我再获得一枚教学奖章，我的美名便不会被人所遗忘了。', `MaleText_loc5`='另一名學生。棒極了。這就是林度恩躋身皇家學會從事研究工作的原因，也是我堅持成為一名導師的原因。只要我再獲得一枚教學獎章，我的美名便不會被人所遺忘了!', `MaleText_loc7`='Otro alumno. Maravilloso. Esta es la razón por la que Lydon supervisa mientras que yo tengo que seguir siendo un instructor. Si gano otro premio a la enseñanza, ¡no podré superarlo!' WHERE `ID`=7752;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나의 힘이 돌아와 너희들의 노력은 수포로 돌아갔도다, 어리석은 것들. 그럼 다시 만날 때까지...', `MaleText_loc4`='我已经恢复了力量，愚蠢的人类，你浪费了一次机会。下次再会吧。', `MaleText_loc5`='我已經恢復了力量，愚蠢的人類，你浪費了一次機會。下次再會吧。', `MaleText_loc7`='Mis poderes han regresado y han desperdiciado su oportunidad, necios mortales. Hasta que nos volvamos a encontrar.' WHERE `ID`=7753;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알게르논이 물품을 다 대주니 나는 약초 하나 안 캐고 여기서 작업을 할 수 있다네. 앞으로도 계속해서 약초를 직접 캐지 않아도 된다면 멀지 않아 할 수 있을 걸세.', `MaleText_loc4`='有奥格诺恩提供所需的供应，我可以不用寻找一株草药就能完成在这里的任务。如果我永远都不用再次看到自然的奇迹，这就不会很快发生。', `MaleText_loc5`='有奧格諾恩提供所需的供應，我可以不用尋找一株草藥就能完成在這裡的任務。如果我永遠都不用再次看到自然的奇蹟，這就不會很快發生。', `MaleText_loc7`='Con Algernon a cargo de los suministros puedo hacer aquí todo mi trabajo sin tener que buscar una sola hierba. Aunque nunca más volviera a ver las maravillas de la naturaleza ya tendría bastante.' WHERE `ID`=7754;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네에겐 더 이상 가르칠 지식이 없네. 아치길을 지나 동남쪽 경사로 밑으로 가서 학자 허버트 핼시를 만나 보게. 그 친구가 자네에게 전문 기술을 가르쳐 줄 포세이큰일세.', `MaleText_loc4`='我没有可传授给你的知识了。穿过拱门走下斜坡到东南方，找赫伯特·哈尔希医生谈谈。他是个被遗忘者，他能教给你更加高级的技术。', `MaleText_loc5`='我沒有可傳授給你的知識了。穿過拱門走下斜坡到東南方，找赫伯特·哈爾希醫生談談。他是個被遺忘者，他能教給你更加高級的技術。', `MaleText_loc7`='No tengo más saber que transmitirte. Atraviesa el pórtico y sigue la rampa hacia el Sureste, cuando encuentres al doctor Helbert Halsey habla con él. Es un Renegado y puede enseñarte técnicas más avanzadas.' WHERE `ID`=7755;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 제자가 되려면 과제를 하나 완료해야 하네. 자네가 가르칠 만한 친구라는 걸 증명하면 상까지 줄지도 모르지.', `MaleText_loc4`='如果你想成为我的学生，你需要完成一项任务。证明自己的价值，或许我会考虑好好回报你的。', `MaleText_loc5`='如果你想成為我的學生，你需要完成一項任務。證明自己的價值，或許我會考慮好好回報你的。', `MaleText_loc7`='Si deseas convertirte en mi alumno tendrás que completar una tarea para mí. Demuestra que eres $gmerecedor:merecedora; y tal vez tome en consideración recompensarte.' WHERE `ID`=7756;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나를 찾아와 가르쳐 달라고 하다니 뻔뻔스럽기 짝이 없군. 아치길을 지나 동남쪽 경사로 밑으로 가서 박사 마틴 펠벤을 만나 보게. 그 친구가 자네를 기초부터 가르쳐 줄 포세이큰이라네.', `MaleText_loc4`='你如此大胆地跑来找我，想要接受训练，我对此可不高兴。穿过拱道，沿着坡道向东南方走，跟亡灵马丁·费尔本谈谈。他能教你一些基础知识。', `MaleText_loc5`='你如此大膽地跑來找我，想要接受訓練，我對此可不高興。穿過拱道，沿著坡道向東南方走，跟被遺忘者馬丁·費爾本醫生談談。他能教你一些基礎知識。', `MaleText_loc7`='No me divierte la audacia que muestras presentándote aquí para recibir instrucción. Atraviesa el pórtico y desciende la rampa hacia el Sureste, cuando encuentres al doctor Martin Felben habla con él. Es un Renegado y podrá enseñarte los principios básicos.' WHERE `ID`=7757;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연금술을 배우러 왔다고? 아주 좋아. 자네를 가르친다고 우리 동맹에 해가 되지는 않겠지. 자네가 우리의 적들에게 피해를 줄 수 있는 한은 말이야.', `MaleText_loc4`='到这儿来学习的吗？很好。我想要是我教你的话，你不会对我们的联盟造成太多的伤害。只要你一心对付我们的敌人。', `MaleText_loc5`='到這兒來學習的嗎?很好。我想要是我教你的話，你不會對我們的聯盟造成太多的傷害。只要你一心對付我們的敵人。', `MaleText_loc7`='¿Has venido para instruirte? Muy bien. Supongo que no haré mucho daño a nuestros aliados si te instruyo. Siempre que procures dañar a nuestros enemigos.' WHERE `ID`=7758;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='똑같은 재료를 쓰는데도 제가 만든 물약을 사용하면 상처가 덜 아무는 것 같아요. 식물들이 변하고 있다는 한 가지 결론이 나오네요. 하지만 식물들이 무슨 이유로 무엇으로 변하고 있는지는 말씀 드릴 수가 없군요.', `FemaleText_loc4`='虽然每次我都使用了相同的成分，但配制出的药水似乎都达不到预期的治疗效果。这只能得出一个结论：植物发生了变化。我还不清楚具体原因。', `FemaleText_loc5`='雖然每次我都使用了相同的成分，但配製出的藥水似乎都達不到預期的治療效果。這只能得出一個結論:植物發生了變化。我還不清楚具體原因。', `FemaleText_loc7`='Cada vez que preparo esta poción parece curar menos, aunque siempre utilizo los mismos ingredientes. Solo llego a una conclusión: las plantas están cambiando. No puede decir por qué ni en qué.' WHERE `ID`=7759;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 그대는 좀 더 숙련된 스승에게 배울 때가 되었습니다. 페랄라스의 페더문 요새에는 킬란나 윈드위스퍼라는 나이트 엘프가 살고 있답니다. 그녀는 지력이 대단하니 그대에게 많은 것을 가르쳐 줄 수 있을 것입니다.', `FemaleText_loc4`='现在你该找一位更加渊博的老师了。在菲拉斯的羽月要塞居住着暗夜精灵凯兰娜·风语。她有聪明的头脑；毫无疑问她能继续教你。', `FemaleText_loc5`='現在你該找一位更加淵博的老師了。在菲拉斯的羽月要塞居住著夜精靈凱蘭娜·風語。她有聰明的頭腦;毫無疑問她能繼續教你。', `FemaleText_loc7`='Es hora de que te dirijas a un instructor más avanzado. En el Bastión Plumaluna de Feralas habita la elfa de la noche Kylanna Vientosusurro. Tiene una mente brillante y sin duda podrá seguir tu instrucción.' WHERE `ID`=7760;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말 잘하셨군요. 저를 대신해 임무를 수행할 수 있겠습니까? 제가 아는 이 중에서는 그대가 적격자입니다.', `FemaleText_loc4`='这是出色的工作。你准备代表我接受这项任务吗？没人比你更能胜任了。', `FemaleText_loc5`='這是出色的工作。你準備代表我接受這項任務嗎?沒人比你更能勝任了。', `FemaleText_loc7`='Es un trabajo excelente. ¿Estás $glisto:lista; para aceptar una misión a mis órdenes? No conozco a nadie más $gcualificado:cualificada;.' WHERE `ID`=7761;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그대는 저의 제자가 되기에는 물약 제조 기술이 부족합니다. 저기 있는 실반나 포레스트문이나 밀라 페어랜코라가 그대를 도와줄 수 있을 듯싶군요.', `FemaleText_loc4`='你制造药剂的技能需要再高超一些才能当我的学生。在此期间，在那边的希尔瓦娜·林月或米拉·法拉科纳可能会帮助你。', `FemaleText_loc5`='你製造藥劑的技能需要再高超一些才能當我的學生。在此期間，在那邊的希爾瓦娜·林月或米拉·法拉科納可能會幫助你。', `FemaleText_loc7`='Tus habilidades preparando pociones tienen que ser mayores antes de poder convertirte en uno de mis alumnos. Hasta entonces quizás puedan ayudarte Sylvanna Bosqueluna o Milla Fairancora, están ahí mismo.' WHERE `ID`=7762;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='교육을 잘 따라오시는군요. 자신의 성과에 자부심을 가져도 좋습니다.', `FemaleText_loc4`='你的培训进展很好。你该为你的成就感到自豪。', `FemaleText_loc5`='你的培訓進展很好。你該為你的成就感到自豪。', `FemaleText_loc7`='Tu educación hace grandes progresos. Deberías sentirte $gorgulloso:orgullosa; por tus logros.' WHERE `ID`=7763;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나와 내 동료는 우리가 아는 가장 치명적인 물질들을 모아 적에게 그 효과를 시험해 보고 있습니다. 필요한 걸 모두 알아내면, 여태 본 적도 없는 무시무시한 역병을 만들어낼 수 있겠지요.', `MaleText_loc4`='我和我的同伴正在收集我们所知的素材，并测试它们的效果。一旦我收集齐备，我将制造出这世界前所未有的药剂。', `MaleText_loc5`='我和我的同伴正在收集我們所知的致命物質，並在敵人身上測試它們的效果。一旦我收集齊備，我將製造出這世界前所未有的瘟疫。', `MaleText_loc7`='Mis colegas y yo estamos reuniendo las sustancias más mortíferas que conocemos y probando sus efectos en nuestros enemigos. Cuando tenga todo lo que necesito preparé unas pestes nunca vistas en este mundo.' WHERE `ID`=7764;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놀라워. 자네의 물약은 내 물약과 비교해도 손색이 없군. 더 가르칠 것이 없네. 하지만 슬픔의 늪, 스토나드로 가서 최신 실험으로 유명한 로그바라는 오크를 만나 보게.', `MaleText_loc4`='难以置信。你配制药水的技能已经能跟我匹敌了。我不能再训练你了，去悲伤沼泽找斯通纳德的兽人罗格瓦尔谈谈。他以他的宝刀而闻名。', `MaleText_loc5`='難以置信。你配製藥水的技能已經能跟我匹敵了。我不能再訓練你了，去悲傷沼澤找斯通納德的獸人羅格瓦爾談談。他以他的寶刀而聞名。', `MaleText_loc7`='Increíble. Tus pociones demuestran un conocimiento que rivaliza con el mío propio. No puedo seguir instruyéndote, pero habla con el orco Rogvar del Rocal, en el Pantano de las Penas. Es famoso por sus experimentos punteros.' WHERE `ID`=7765;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 물약을 만드는 재능과 열정이 대단하군. 하지만 딱 한 가지 해결할 것이 있네.', `MaleText_loc4`='你在配制药剂方面确实有才华和激情。然而，我还有一件事要你打理一下。', `MaleText_loc5`='你在配製藥劑方面確實有才華和激情。然而，我還有一件事要你打理一下。', `MaleText_loc7`='Tienes auténtico talento y pasión por las pociones. Pero hay un asuntillo del que tendrías que ocuparte.' WHERE `ID`=7766;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자넨 나에게 배우기에는 아직 기술이 부족하군. 저기 있는 마틴 펠벤 박사에게 가 보게나. 아니면 동남쪽으로 경사로를 올라가서 학자 마쉬에게 가던가. 그들은 자네에게 필요한 기술을 가르쳐 줄 수 있는 포세이큰들이야.', `MaleText_loc4`='你的技术太差了，还不能跟我学习。去跟那边的马丁医生谈谈，或者爬上斜坡到东南方去看看马尔什医生。他们是被遗忘者，可以给你所需的训练。', `MaleText_loc5`='你的技術太差了，還不能跟我學習。去跟那邊的馬丁·費爾本醫生談談，或者爬上斜坡到東南方去看看馬許醫生。他們是被遺忘者，可以給你所需的訓練。', `MaleText_loc7`='Todavía no tienes suficientes habilidades para estudiar conmigo. Ve a hablar con el doctor Martin Felben, o sube la rampa hacia el Sureste para ver al doctor Marsh. Son unos Renegados que pueden darte la instrucción que necesitas.' WHERE `ID`=7767;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련 준비는 됐나? 그렇다면 배울 내용이 아주 방대하니까 잘 따라오게.', `MaleText_loc4`='准备好接受训练了？保持速度，$n。我们要走的路还长着呢。', `MaleText_loc5`='準備好接受訓練了?保持速度，$n。我們要走的路還長著呢。', `MaleText_loc7`='¿Listo para la instrucción? Pues intenta mantener el ritmo, $n. Tenemos mucho camino que recorrer.' WHERE `ID`=7768;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='한때 저는 어둠이 밤의 동생이기 때문에 어둠을 반겼답니다. 하지만 이제는 낮에도 어둠이 깔려 숲이 생명을 유지하기 위해 절규하고 있습니다. 우리가 즉시 행동하지 않으면 이 어두운 그림자는 곧 세상을 덮어버릴 것입니다.', `FemaleText_loc4`='从前我欢迎过黑暗，因为它是夜晚的姐妹。现在总是漆黑一片，甚至在白天也是这样，而森林迫切需要给养。除非我们快些行动，否则这扩散的瘟疫就会遍布整个世界。', `FemaleText_loc5`='從前我歡迎過黑暗，因為它是夜晚的姐妹。現在總是漆黑一片，甚至在白天也是這樣，而森林迫切需要給養。除非我們快些行動，否則這擴散的荒疫會遍佈整個世界。', `FemaleText_loc7`='Hubo un día en el que daba la bienvenida a la oscuridad, la hermana de la noche. Ahora siempre reina la oscuridad, también durante el día, y los bosques gritan de dolor por su sustento. Si no actuamos pronto, este añublo se extenderá por todo el mundo.' WHERE `ID`=7769;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='물약 제조 기술을 배우려고 이곳에 오셨습니까? 노력 없이 그런 특권을 주리라 생각했다면 오산입니다. 가서 기술을 더 익힌 후에 돌아오십시오.', `FemaleText_loc4`='你是来接受药水配制这一技能的训练的吗？要是你认为能从我这儿不费吹灰之力地学到东西的话，你就大错特错了。走吧，在你没有掌握更高技能之前别来找我。', `FemaleText_loc5`='你是來接受藥水配製這一技能的訓練的嗎?要是你認為能從我這兒不費吹灰之力地學到東西的話，你就大錯特錯了。走吧，在你沒有掌握更高技能之前別來找我。', `FemaleText_loc7`='¿Has venido para instruirte en el arte de preparar pociones? Estabas muy $gequivocado:equivocada; si pensabas que te ofrecería ese privilegio, no lo has ganado. Vete y no vuelvas hasta que tengas más habilidades.' WHERE `ID`=7770;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그대의 기술을 보면 물약 제조술에 대해 상당한 애정이 있음을 알 수 있습니다. 하지만 그것으로는 조금 부족합니다. 그런 의미로 임무를 하나 드리도록 하겠으니 이를 완수하신다면 저도 만족할 수 있을 겁니다.', `FemaleText_loc4`='你的技能显示你一直喜爱我们的艺术，但是我想看到你所做承诺的进一步证据。我会分配给你一项任务。完成它就会令我满意。', `FemaleText_loc5`='你的技能顯示你一直喜愛我們的藝術，但是我想看到你所做承諾的進一步證據。我會分配給你一項任務。完成它就會令我滿意。', `FemaleText_loc7`='Tus habilidades muestran una dedicación constante y fiel a tu arte, pero necesito más pruebas de tu compromiso. Te encargaré una tarea, complétala y quedaré satisfecha.' WHERE `ID`=7771;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='영광스럽게도 엘룬께서 저에게 기술과 경험을 내려 주셨습니다. 이제는 그것을 그대에게 전하겠습니다.', `FemaleText_loc4`='月神曾赐与我技能和经验。现在我要把它们传授给你。', `FemaleText_loc5`='伊露恩曾賜予我技能和經驗。現在我要把它們傳授給你。', `FemaleText_loc7`='Elune tuvo a bien bendecirme con habilidad y experiencia. Ahora te las transmitiré a ti.' WHERE `ID`=7772;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼라란, 햇불을 잃어버렸어요. 새 것이 필요합니다.', `MaleText_loc4`='卡拉然，我把火炬弄丢了。给我一个新的吧。', `MaleText_loc5`='卡拉然，我把火炬的位置放錯了。我還要一個。', `MaleText_loc7`='Kalaran, he perdido mi antorcha. Necesito otra.', `FemaleText_loc1`='칼라란, 햇불을 잃어버렸어요. 새 것이 필요합니다.', `FemaleText_loc4`='卡拉然，我把火炬弄丢了。给我一个新的吧。', `FemaleText_loc5`='卡拉然，我把火炬的位置放錯了。我還要一個。', `FemaleText_loc7`='Kalaran, he perdido mi antorcha. Necesito otra.' WHERE `ID`=7773;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스랄 님께서 직접 이곳으로 저를 보내셨습니다. 대족장님께 명령을 받은 것만으로도 영광스럽기 때문에 하나도 힘든 줄 모르겠습니다. 사실 스토나드보다 나은 곳도 없지요. 필요한 약초는 죄다 여기 이 늪지대 진흙탕에서 자라니까 말입니다.', `MaleText_loc4`='萨尔酋长派我到这儿来，我感到非常荣幸。我并不奢求能被派往比斯通纳德更好的地方，我只想找些生长在这儿的草药。', `MaleText_loc5`='大酋長索爾親自邀請我到這兒來。我感到非常榮幸，這並不困難。我不要求自己的職務高於斯通納德。我只想找些生長在這兒的草藥。', `MaleText_loc7`='El propio Jefe de Guerra Thrall me pidió venir aquí. Fue un honor obedecerle y no un castigo. No podría haber pedido un destino mejor que el Rocal. Prácticamente todas las hierbas que pueda necesitar crecen en este estiércol.' WHERE `ID`=7774;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='허어, 물약을 그렇게 휘저으면 쓰나... 이 서투른 시골뜨기 양반아! 아니, 아니... 그렇다고 젓는 걸 멈춰도 안 됩니다! 참나, 그만두십시오. 불이라도 내기 전에 국자 이리 주십시오. 건질 수 있는 데까지 건져 봐야겠습니다. 자, 잘 봐두십시오.', `MaleText_loc4`='别像那样搅动药水，你这个笨手笨脚的农民！不，也不要停止搅动它！算了——在你弄出火之前把杓子给我吧。我将尽力补救。现在，你得注意了。', `MaleText_loc5`='別像那樣攪動藥水，你這個笨手笨腳的農民!不，也不要停止攪動它!算了─在你弄出火之前把杓子給我吧。我將盡力補救。現在，你得注意了。', `MaleText_loc7`='¡No agites así la poción, torpe $ggranjero:granjera;! ¡No, pero tampoco pares de agitarla! Olvídalo... Dame ese cazo antes de que provoques un incendio. Salvaré lo que pueda. Y ahora, presta atención.' WHERE `ID`=7775;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠, 물약 만드는 소질이 좀 있으시군요. 그렇다고 제자로 받아들이겠다는 건 아닙니다. 전 아주 바쁜 몸이니까요. 저를 만족시킨다면 또 얘기가 틀리지만. 당신에게 맡길 일이 있습니다.', `MaleText_loc4`='嗯，好吧，我看到你还懂一点做药剂的方法。然而，你是否配做我的学生仍有待察看。我有一项任务交给你。争取给我一个好印象。', `MaleText_loc5`='嗯，好吧，我看到你還懂一點做藥劑的方法。然而，你是否配做我的學生仍有待察看。我有一項任務交給你。爭取給我一個好印象。', `MaleText_loc7`='Umm... bien, puedo ver que sabes algo de preparar pociones. Pero aún hay que ver si mereces ser mi $galumno:alumna;. Tengo un trabajo para ti. Convénceme.' WHERE `ID`=7776;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어느 안전에서 감히 가르쳐 달라는 겁니까? 뭘 바라고 온 거예요? 이 답답하고 얼빠진 촌놈 같은 양반. 은엽수 덤불 사용법이라도 배우겠다는 겁니까? 당장 나가요! 아까운 시간을 낭비하게 한 대가로 신나게 두들겨 맞지 않은 것만 해도 다행인 줄 아십시오!', `MaleText_loc4`='你胆敢让我培训你，你这可怜虫？你期望什么，你这个呆头呆脑的乡巴佬，一场关于如何正确使用银叶的讲演？滚出去！你浪费我的时间没把你打个半死算你走运。', `MaleText_loc5`='你膽敢讓我培訓你，你這可憐蟲?你期望什麼，你這個呆頭呆腦的鄉巴佬，一場關於如何正確使用銀葉的講演?滾出去!你浪費我的時間沒把你打個半死算你走運。', `MaleText_loc7`='¿Cómo te atreves a pedirme que te instruya, gusano? ¿Qué esperabas, $gpaleto bobo:paleta boba;, una lección sobre los usos de la hojaplata? ¡Fuera de aquí! Tienes suerte de que no te deje inconsciente por hacerme perder el tiempo.' WHERE `ID`=7777;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 사제님. 제때에 와주셨군요. 감사합니다.', `FemaleText_loc4`='啊，你来的正是时候。谢谢你。', `FemaleText_loc5`='啊，你來的正是時候。謝謝你。', `FemaleText_loc7`='Ah, $gsacerdote:sacerdotisa;, viniste justo a tiempo. Te lo agradezco.' WHERE `ID`=7778;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='으... 너무 아파요. 고통이 멎지 않을 것 같아요.', `FemaleText_loc4`='啊，这无尽的痛苦何时才能不再困扰我？', `FemaleText_loc5`='啊，這無盡的痛苦何時才能不再困擾我?', `FemaleText_loc7`='Argh, el sufrimiento. ¿Me abandonará alguna vez?' WHERE `ID`=7779;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='감사합니다! 감사합니다, 사제님! 이제 엘룬의 힘을 얻었으니 저 타락한 나무괴물들과 맞설 수 있겠어요!', `FemaleText_loc4`='谢谢你！谢谢你，$g牧师:女祭司;。有了月神的庇护，我就可以对抗那些堕落的树精了！', `FemaleText_loc5`='謝謝你!謝謝你，$g牧師:女牧師;。現在有伊露恩的力量在背後支持，我能夠對抗那些墮落的樹木!', `FemaleText_loc7`='¡Gracias! Gracias, $gsacerdote:sacerdotisa;. ¡Ya me puedo encargar de esos Brezomadera corruptos, el poder de Elune me da fuerzas!' WHERE `ID`=7780;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕히 가십시오. 엘룬께서 항상 그대와 함께하시기를.', `FemaleText_loc4`='再见，愿月神与你同在。', `FemaleText_loc5`='再見，願伊露恩與你同在。', `FemaleText_loc7`='Que tengas buen viaje, y que Elune siempre te acompañe.' WHERE `ID`=7781;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 사제님. 제때 와주셨군요. 감사합니다.', `FemaleText_loc4`='啊，牧师，你来得正是时候。谢谢你。', `FemaleText_loc5`='啊，牧師，你來的正是時候。謝謝你。', `FemaleText_loc7`='Ah, $gsacerdote:sacerdotisa;, viniste justo a tiempo. Te lo agradezco.' WHERE `ID`=7782;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='으. 너무 아프군. 고통이 멎지 않을 것 같아.', `FemaleText_loc4`='啊，这无尽的痛苦何时才能不再困扰我？', `FemaleText_loc5`='啊，這無盡的痛苦何時才能不再困擾我?', `FemaleText_loc7`='Argh, el sufrimiento. ¿Me abandonará alguna vez?' WHERE `ID`=7783;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='감사합니다! 감사합니다, 사제님! 이제 힘을 되찾았으니 저 인간들과 맞설 수 있겠어요!', `FemaleText_loc4`='谢谢！谢谢你，$g祭司:女祭司;。有了你的力量我就可以继续作战了！', `FemaleText_loc5`='謝謝!謝謝你，$g牧師:女牧師;。有了你的力量我就能使這些人回到我身邊了!', `FemaleText_loc7`='¡Gracias! Gracias, $gsacerdote:sacerdotisa;. ¡Ya me puedo encargar de esos humanos gracias al poder que me has devuelto!' WHERE `ID`=7784;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕히 가십시오. 선조님께서 항상 함께하시기를.', `FemaleText_loc4`='再见了，愿我们的祖先永远保佑你！', `FemaleText_loc5`='再見了，願我們的祖先永遠保佑你!', `FemaleText_loc7`='¡Que tengas buen viaje, y que nuestros ancestros siempre te acompañen!' WHERE `ID`=7785;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, $g사제:여사제;님. 제때에 와주셨군요. 감사합니다.', `MaleText_loc4`='啊，$g牧师:女牧师;，你来得正是时候。谢谢你。', `MaleText_loc5`='啊$g牧師:女牧師;，你來的正是時候。謝謝你。', `MaleText_loc7`='Ah, $gsacerdote:sacerdotisa;, viniste justo a tiempo. Te lo agradezco.' WHERE `ID`=7786;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으. 아프군. 고통이 멎지 않을 것 같아.', `MaleText_loc4`='啊，这无尽的痛苦何时才能不再困扰我？', `MaleText_loc5`='啊，這無盡的痛苦何時才能不再困擾我?', `MaleText_loc7`='Argh, el sufrimiento. ¿Me abandonará alguna vez?' WHERE `ID`=7787;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다! 감사합니다, 사제님! 이제 성스러운 빛이 저와 함께하니 저 웬디고들과 맞설 수 있겠어요!', `MaleText_loc4`='谢谢你！谢谢你，牧师。有了你的帮助，我就能对付这些雪怪了！', `MaleText_loc5`='謝謝你!謝謝你，牧師。有了聖光的幫助，我就能對付這些雪怪了!', `MaleText_loc7`='¡Gracias! Gracias, $gsacerdote:sacerdotisa;. ¡Ya me puedo encargar de esos wendigo, la Luz está de mi lado!' WHERE `ID`=7788;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕히 가십시오. 성스러운 빛이 항상 함께하시기를.', `MaleText_loc4`='再见，愿光明与你同在。', `MaleText_loc5`='再見，願光明與你同在。', `MaleText_loc7`='Que tengas buen viaje, y que la Luz siempre te acompañe.' WHERE `ID`=7789;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 사제여. 제때에 와주었군. 고맙네.', `MaleText_loc4`='啊，$g牧师:女牧师;，你来得正是时候。谢谢你。', `MaleText_loc5`='啊$g牧師:女牧師;，你來的正是時候。謝謝你。', `MaleText_loc7`='Ah, $gsacerdote:sacerdotisa;, viniste justo a tiempo. Te lo agradezco.' WHERE `ID`=7790;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으... 아프군. 고통이 멎지 않을 것 같아.', `MaleText_loc4`='啊，这无尽的痛苦何时才能不再困扰我？', `MaleText_loc5`='啊，這無盡的痛苦何時才能不再困擾我?', `MaleText_loc7`='Argh, el sufrimiento. ¿Me abandonará alguna vez?' WHERE `ID`=7791;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙네! 고마워, 사제여! 이제 힘이 되돌아왔으니 저 놀 무리를 해치울 수 있겠군!', `MaleText_loc4`='谢谢你！谢谢你，牧师。有了你的帮助，我就能对付这些豺狼人了！', `MaleText_loc5`='謝謝你!謝謝你，牧師。有了你的幫助，我就能對付這些豺狼人了!', `MaleText_loc7`='¡Gracias! Gracias, $gsacerdote:sacerdotisa;. ¡Ya me puedo encargar de esos gnolls con el poder que me has devuelto!' WHERE `ID`=7792;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 가게. 어둠의 가호가 항상 함께하기를!', `MaleText_loc4`='再见，愿暗影永远保护你！', `MaleText_loc5`='再見，願暗影永遠保護你!', `MaleText_loc7`='¡Que tengas buen viaje, y que la sombra siempre te proteja!' WHERE `ID`=7793;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이것만 조금 조절하면... 아, 됐다!', `MaleText_loc4`='只需做些小调整……搞定！', `MaleText_loc5`='只需做些小調整...我們出發吧!', `MaleText_loc7`='Solo un pequeño ajuste... ¡y allá vamos!' WHERE `ID`=7794;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='할 수만 있으면 내가 당신을 훈련시켜 주겠지만 당신에게는 그... 뭐라고 하더라? 그렇지! 머리가 좀 더 잘 굴러 가는 이가 필요할 것 같소. 아이언포지에 있는 트리시 퀵스위치를 찾아가서 브롱크가 보냈다고 해 보시오!', `MaleText_loc4`='要是我能的话，我是会训练你的，但是你需要找个稍微……怎么说，聪明点的人为你服务吧！去铁炉堡找特里克希吧。告诉他是布隆克派你去的！', `MaleText_loc5`='要是我能的話，我是會訓練你的，但是你需要找個稍微...怎麼說，聰明點的人為你服務吧!去鐵爐堡找崔克希·迅移吧。告訴他是布隆克派你去的!', `MaleText_loc7`='Te instruiría si pudiera, pero necesitas los servicios de alguien un poco más... ¿cuál es la palabra? ¡Sesudo! busca a Trixie Chispaveloz de Forjaz. ¡Dile que vas de parte de Bronk!' WHERE `ID`=7795;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기술자가 되고 싶은 거요? 아, 그렇다면 두말할 것 없이 아주 잘 찾아온 거요!', `MaleText_loc4`='想成为工程师，是吗？嗯，穆拉丁保佑你，你来对地方了！', `MaleText_loc5`='想成為工程師，是嗎?嗯，穆拉丁保佑你，你來對地方了!', `MaleText_loc7`='Quieres ser $gingeniero:ingeniera;, ¿eh? ¡Bien, por Muradin, has venido al lugar adecuado!' WHERE `ID`=7796;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 살기를 띤 듯한 광란 상태에 빠집니다!', `MaleText_loc4`='%s变得极为狂暴！', `MaleText_loc5`='%s變得極為狂暴!', `MaleText_loc7`='%s entra en un frenesí de muerte.' WHERE `ID`=7797;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 분노합니다!', `MaleText_loc4`='%s变得愤怒了！', `MaleText_loc5`='%s暴怒了起來!', `MaleText_loc7`='¡%s se enfurece!' WHERE `ID`=7798;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 스피너가 어디 있지? 분명히 여기 어딘가에 뒀는데...', `MaleText_loc4`='我的旋转诱饵在哪儿？我刚刚还把它放在这附近的……', `MaleText_loc5`='我的旋轉誘餌在哪兒?我剛剛還把它放在這附近的...', `MaleText_loc7`='¿Dónde está mi centrifugador? Estaba por algún sitio...' WHERE `ID`=7799;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 현재 가지고 있는 재능은 제 능력을 한참 웃도는군요. 아이언포지에 있는 내 노움 친구 트리시 퀵스위치에게 더 자세히 물어 보세요!', `MaleText_loc4`='你目前的智能超出了我的指导能力。你该找我在铁炉堡的侏儒同伴特里克希询问一下！', `MaleText_loc5`='你目前的智慧超出了我的指導能力。你該找我在鐵爐堡的地精同伴崔克希·迅移詢問一下!', `MaleText_loc7`='Tus aptitudes superan mi capacidad para instruirte. ¡Deberías preguntar a mi compañero gnomo Trixie Chispaveloz de Forjaz!' WHERE `ID`=7800;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 추구하는 바를 시작할 수 있도록 내 기꺼이 도와드리겠습니다! 내 스피너를 찾은 다음 곧 시작합시다...', `MaleText_loc4`='我很高兴能在你事业开始的时候帮上忙，！让我们抓紧纺纱机，开始吧……', `MaleText_loc5`='我很高興能在你事業開始的時候幫上忙，!讓我們抓緊紡紗機，開始吧...', `MaleText_loc7`='¡Estaría encantado de ayudarte a comenzar tu tarea! Déjame coger mi centrifugador y nos pondremos en marcha...' WHERE `ID`=7801;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='신형 병아리저울 6000의 제조가 곧 끝날 거라고 하더군요. 너무 흥분돼서 참을 수가 없어요!', `FemaleText_loc4`='我听说新型的极速6000型很快就要开下生产线了。我几乎不能抑制激动的心情！', `FemaleText_loc5`='我聽說新型的極速6000型很快就要開下生產線了。我幾乎不能抑制激動的心情!', `FemaleText_loc7`='He oído que el nuevo Pesagallinas 6000 pronto estará en la cadena de montaje. ¡Apenas puedo contener los nervios!' WHERE `ID`=7802;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='글쎄요... 인정하고 싶진 않지만 계속해서 훈련을 받으실 거라면 제 언니를 찾아가 보셔야 할 것 같군요. 저는 언니만큼 많이 알지는 못하거든요. 아직까지는 말이에요! 언닌 로켓 자동차 옆에 서 있을 거예요.', `FemaleText_loc4`='呃……虽然我不愿承认，但是你要想继续训练的话就必须跟我的姐妹谈谈。目前来说……我知道的没她多！她乘坐火箭车四处巡查。', `FemaleText_loc5`='呃...雖然我不願承認，但是你要想繼續訓練的話就必須跟我的姐妹談談。目前來說...我知道的沒她多!她乘坐火箭車四處巡查。', `FemaleText_loc7`='Bien... odio admitirlo, pero tendrás que hablar con mi hermana si quieres seguir tu instrucción. No sé tanto como ella... ¡todavía! La encontrarás junto al coche cohete.' WHERE `ID`=7803;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='기꺼이 가르쳐 드리죠! 기계공학에 대해서 좀 알고 있는 게 언니 뿐만은 아니라는 걸 보여 주고 말겠어요.', `FemaleText_loc4`='我愿意教你！要让我的姐姐看看她不是唯一了解工程学的人……', `FemaleText_loc5`='我願意教你!要讓我的姐姐看看她不是唯一瞭解工程學的人...', `FemaleText_loc7`='¡Me encantaría instruirte! Le enseñaré a mi hermana que ella no es la única que sabe un par de cosas sobre ingeniería...' WHERE `ID`=7804;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요! 저는 지나라고 해요! 당신은요?', `FemaleText_loc4`='你好！我的名字是洁娜！你呢？', `FemaleText_loc5`='你好!我的名字是潔娜!你呢?', `FemaleText_loc7`='¡Hola! ¡Me llamo Jenna! ¿Y tú?' WHERE `ID`=7805;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 배우실 거야 아직도 잔뜩 있죠. 제가 할 수만 있으면 모두 다 가르쳐 드리고 싶지만 저도 아직 배우고 있는 입장이라서요. 아이언포지에 있는 트리시 퀵스위치를 한번 찾아가 보세요. 계속해서 훈련을 시켜 줄 수 있을 겁니다!', `FemaleText_loc4`='哦，你还有很多东西要学。我会教给你我所学的全部知识，但是我自己也在学习！你为什么不找铁炉堡的特里克希谈谈，她会帮你进修的！', `FemaleText_loc5`='哦，你還有很多東西要學。我會教給你我所學的全部知識，但是我自己也在學習!你為什麼不找鐵爐堡的崔克希·迅移談談，她會幫你進修的!', `FemaleText_loc7`='Oh, aún tienes muchas cosas que aprender. Te enseñaría todo si pudiera, ¡pero yo también sigo aprendiendo! ¿Por qué no vas a hablar con Trixie Chispaveloz en Forjaz? ¡Te ayudará a seguir adelante con tu educación!' WHERE `ID`=7806;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='훈련을 받고 싶으시다고요? 저한테서요? 아주 좋죠! 탄환이랑 폭발 장치를 조립하는 것보다 더 나은 유일한 일은 바로 그 지식을 다른 이와 나누는 거니까요! 어서 시작해요!', `FemaleText_loc4`='你想学习？跟着我？太棒了！唯一比装配子弹和炸药装置有趣的事情就是与别人分享那种知识！我们开始吧！', `FemaleText_loc5`='你想學習?跟著我?太棒了!唯一比裝配子彈和爆裂物裝置有趣的事情就是與別人分享那種知識!我們開始吧!', `FemaleText_loc7`='¿Quieres instruirte? ¿Conmigo¿ ¡Fantástico! Solo hay una cosa mejor que fabricar balas y explosivos: compartir ese conocimiento con alguien más. ¡Vamos a empezar!' WHERE `ID`=7807;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 뭐 하나 날려 버리기에는 딱 좋은 날씨네!', `FemaleText_loc4`='啊，多么美好的一天啊！真该炸点什么东西。', `FemaleText_loc5`='啊，多麼美好的一天啊!真該炸點什麼東西。', `FemaleText_loc7`='¡Ah, qué día tan bonito para hacer estallar algo!' WHERE `ID`=7808;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신은 이제 제 실력 밖에 있는 것들을 배우기 시작해야 해요! 저쪽 천막 앞에 있는 릴리암 스파크스핀들과 얘기해 보세요. 그가 필요한 내용을 가르쳐 줄 수 있을 테니까요!', `FemaleText_loc4`='你需要开始学习一些我的专门技术之外的东西！跟那边帐篷前面的利廉姆·火轴谈谈。他会让你步入正轨的！', `FemaleText_loc5`='你需要開始學習一些我的專門技術之外的東西!跟那邊帳篷前面的利廉姆·火軸談談。他會讓你步入正軌的!', `FemaleText_loc7`='¡Tienes que empezar a aprender cosas que superan mi grado de pericia! Ve a hablar con Lilliam Chispeje, en esa tienda. ¡Te pondrá en el buen camino!' WHERE `ID`=7809;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런 종류의 일은 담이 약한 이는 할 게 못 돼요. 한쪽 손을 잃어 버린 삼촌도 있다니까요! 불쌍한 스텀피 삼촌... 어쨌든 그래도 관심이 있다면 제가 몇 가지 가르쳐 드릴 수 있을지도 모르겠네요.', `FemaleText_loc4`='这种工作胆小鬼做不了的。我有个叔叔丢了一只手！可怜的老胖子……无论如何，如果你还感兴趣我或许能给你看些东西？', `FemaleText_loc5`='這種工作膽小鬼做不了的。我有個叔叔丟了一隻手!可憐的老胖子...無論如何，如果你還感興趣的話，我或許能給你看些東西。', `FemaleText_loc7`='Esta clase de trabajo no es para los débiles. ¡Un tío mío perdió la mano! Pobre Rechoncho... en cualquier caso, si sigues estando $ginteresado:interesada; puedo enseñarte un par de cosas.' WHERE `ID`=7810;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음? 저한테 원하는 게 있나요?', `MaleText_loc4`='什么？你要什么东西？', `MaleText_loc5`='什麼?你要什麼東西?', `MaleText_loc7`='¿Qué? ¿Quieres algo?' WHERE `ID`=7811;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 당신을 도와 줄 수 없소! 당신은 나보다 더 오래 이 일을 해 온 이를 찾아갈 때가 된 거요! 보자... 아무래도 당신은 얼라이언스 일원이니 스톰윈드에 있는 릴리암 스파크스핀들과 얘기해 봐야 할 거요.', `MaleText_loc4`='我不能帮助你！你会遇到比我更精于此道的人！你是联盟的人，你得跟暴风城的利廉姆·火轴谈谈。', `MaleText_loc5`='我不能幫助你!你會遇到比我更精於此道的人!你是聯盟的人，你得跟暴風城的利廉姆·火軸談談。', `MaleText_loc7`='¡No puedo ayudarte! Estás $glisto:lista; para ver a alguien con mucha más experiencia que yo. Veamos... eres de la Alianza, así que tendrás que hablar con Lilliam Chispeje de Ventormenta.' WHERE `ID`=7812;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아요, 당신에게 몇 가지 가르쳐 드리죠. 당신 솜씨나 한번 봅시다. 어쩌면 저를 놀라게 할 정도일지도 모르죠!', `MaleText_loc4`='是的，我有些东西要给你看看。我们来看一下你做得怎么样，或许你会令我吃惊的！', `MaleText_loc5`='是的，我有些東西要給你看看。我們來看一下你做得怎麼樣，或許你會令我吃驚的!', `MaleText_loc7`='Sí, te enseñaré algo. Veamos qué tal lo haces, ¡tal vez me lleve una sorpresa!' WHERE `ID`=7813;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='*킁킁* 냄새가 나시오? 기름 냄새가 아주 황홀하지 않소?', `MaleText_loc4`='（吸气声，吸气声）你闻到了吗？你难道不是只喜欢油脂的气味吗？', `MaleText_loc5`='(吸氣聲，吸氣聲)你聞到了嗎?你難道不是只喜歡油脂的氣味嗎?', `MaleText_loc7`='(Snif, snif) ¿Hueles eso? ¿No ADORAS el olor de la grasa?' WHERE `ID`=7814;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미안하지만 나는 자네를 가르칠 실력이 안 되네! 오그리마로 가서 노그를 찾아보시게. 그가 자네를 다음 단계로 이끌어 줄 테니까 말이야!', `MaleText_loc4`='恐怕你得离开我了，朋友！你该去找奥格瑞玛的诺格，他将带你进入下一阶段!', `MaleText_loc5`='恐怕你得離開我了，朋友!你該去找奧格瑪的諾格，他將帶你進入下一階段!', `MaleText_loc7`='¡Me temo que ya juegas a otro nivel, $gamigo:amiga;! Deberías ir a ver a Nogg en Orgrimmar, él te ayudará a seguir progresando.' WHERE `ID`=7815;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네도 나 같은 기계공학광이로군. 어디 두고 보게. 머지않아 자네를 제대로 된 기술자로 만들어 줄 테니까!', `MaleText_loc4`='一个热心的朋友，是吗？好吧，你等等，我们会立刻帮你制成一个传动头的！', `MaleText_loc5`='一個熱心的朋友，是嗎?好吧，你等等，我們會立刻幫你製成一個傳動頭的!', `MaleText_loc7`='¿Un aficionado, eh? Bien, espera, ¡enseguida te convertiremos en un auténtico cerebro mecánico!' WHERE `ID`=7816;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 뭔가 만드는 걸 좋아하지. 물론 산산조각나게 폭발시켜 버리는 건 훨씬 더 좋아하고 말이오!', `MaleText_loc4`='我希望组建队伍。当然，我更希望扩大队伍！', `MaleText_loc5`='我希望組建隊伍。當然，我更希望擴大隊伍!', `MaleText_loc7`='Me gusta construir cosas. ¡Aunque todavía me gusta más destruirlas!' WHERE `ID`=7817;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기계공학을 정말 제대로 아는 게 누군지 알기나 하는 거요? 오그리마로 가서 노그를 찾아보시오!', `MaleText_loc4`='你知道谁能真正让你开阔见识吗？诺格！去奥格瑞玛可以找到他。', `MaleText_loc5`='你知道誰能真正讓你開闊見識嗎?諾格!去奧格瑪可以找到他。', `MaleText_loc7`='¿Sabes quién te puede enseñar esas cosas? ¡Nogg! Lo encontrarás en Orgrimmar.' WHERE `ID`=7818;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 기계공학을 좀 알지. 내가 가르쳐 드릴까?', `MaleText_loc4`='我知道一些。要我告诉你吗？', `MaleText_loc5`='我知道一些。要我告訴你嗎?', `MaleText_loc7`='Sé algunas cosas. ¿Quieres que te las enseñe?' WHERE `ID`=7819;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도대체 누가 오크는 머리가 나쁘다고 하는 거야? 머리가 나쁘면 기술자는 될 수 없단 말이야!', `MaleText_loc4`='谁说兽人不聪明？当工程师可是很费脑筋的！', `MaleText_loc5`='誰說獸人不聰明?當工程師很費腦筋的!', `MaleText_loc7`='¿Quién dice que los orcos no son listos? ¡Se necesita mucho seso para ser ingeniero!' WHERE `ID`=7820;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진짜 머리 좋은 기술자가 누군지 아나? 바로 노그지! 나보다도 머리 회전이 빠르다니까. 노그에게 가서 선드가 보냈다고 하게! 바로 저기 기계 장치 제어판 앞에 서있으니까...', `MaleText_loc4`='你知道谁是真正聪明的人吗？诺格！甚至比我还要聪明。你去告诉诺格是桑德派你来的！你可以在那边的控制台那里找到他。', `MaleText_loc5`='你知道誰是真正聰明的人嗎?諾格!甚至比我還要聰明。你去告訴諾格是桑德派你來的!你可以在那邊的控制台那裡找到他。', `MaleText_loc7`='¿Sabes quién es listo de verdad? ¡Nogg! Es hasta más listo que yo. ¡Ve a decirle que vas de parte de Thund! Podrás encontrarle junto al panel de control de ahí mismo.' WHERE `ID`=7821;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 스스로 머리가 꽤 좋다고 생각하나? 뭐든지 잘해낼 수 있을 자신이 있다고? 어디 한번 보세!', `MaleText_loc4`='你认为你很聪明吗？你认为你得到了吗？让我们查明真相！', `MaleText_loc5`='你認為你很聰明嗎?你認為你得到了嗎?讓我們查明真相!', `MaleText_loc7`='¿Crees que eres lo bastante inteligente? ¿Crees que tienes lo que se necesita? ¡Vamos a verlo!' WHERE `ID`=7822;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠의 여왕님께서 말씀하시길, 이 전쟁에서 우리의 가장 큰 무기는 바로 지식이라고 하셨소.', `MaleText_loc4`='黑暗女王说过，在这场战争中，知识是我们最强大的武器。', `MaleText_loc5`='黑暗女王說過，在這場戰爭中，知識是我們最強大的武器。', `MaleText_loc7`='La Dama Oscura ha dicho que mi saber será nuestra mayor arma en esta guerra.' WHERE `ID`=7823;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 이제 더 큰 것들을 배워야 합니다! 내 오른편에 있는 프랭클린 로이드와 얘기해 보십시오. 이제부터는 그가 당신을 지도해 줄 것입니다.', `MaleText_loc4`='你准备好迎接更大的挑战了！见见我右边的弗兰克林·洛伊德。从现在开始他会指导你。', `MaleText_loc5`='你準備好迎接更大的挑戰了!見見我右邊的弗蘭克林·洛伊德。從現在開始他會指導你。', `MaleText_loc7`='¡Estás $glisto:lista; para hacer grandes cosas! Ve a ver a Franklin Lloyd, a mi derecha. Él te guiará a partir de ahora.' WHERE `ID`=7824;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기계공학을 알면 적을 산산조각 낼 기술과 지식을 얻을 수 있습니다! 내가 보여주겠습니다.', `MaleText_loc4`='工程学能赋予你瓦解敌人的技能和知识！让我教你该如何做……', `MaleText_loc5`='工程學能賦予你擊敗敵人的技能和知識!讓我來教你這是如何辦到的。', `MaleText_loc7`='¡La ingeniería te dará la técnica y el conocimiento para desmontar a tus oponentes! ¿Me permites mostrarte cómo?' WHERE `ID`=7825;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이방인 친구와 얘기할 시간이야 언제든 있고 말고요! 뭐, 적어도 거의 항상 그렇답니다.', `MaleText_loc4`='我忙死了，不会跟陌生人讲话的！几乎从来不……', `MaleText_loc5`='我忙死了，不會跟陌生人講話的!幾乎從來不...', `MaleText_loc7`='¡Nunca estoy demasiado ocupado para hablar con un extraño! Bueno, casi nunca...' WHERE `ID`=7826;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제부터 당신은 나보다 더 높은 기술을 쌓게 되는 겁니다! 아이언포지에 있는 스프링스핀들 피즐기어를 찾아가서 나보다 더 잘할 수 있다는 걸 보여주십시오!', `MaleText_loc4`='你在努力上进……现在甚至已经超过我了！你应该与铁炉堡的宾斯匹德谈话！（他会？她会？）让你见识那些我所做不到的！', `MaleText_loc5`='如今，你進步的程度...已經超過我了!你應該與鐵爐堡的賓斯匹德談話!(他會?她會?)讓你見識那些我所做不到的!', `MaleText_loc7`='Vas a llegar muy alto... ¡más que yo, a este paso! Ve a hablar con Muello Saltarín, en Forjaz. Él te enseñará más de lo que yo podría enseñarte jamás.' WHERE `ID`=7827;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러니까 먼저 간단한 일 하나만 해 준다면 내가 몇 가지 요령을 가르쳐 줄 수 있어요.', `MaleText_loc4`='我可以教你一些诀窍……如果你不介意先帮我做些事情的话。', `MaleText_loc5`='我可以教你一些訣竅...如果你不介意先幫我做些事情的話。', `MaleText_loc7`='Puedo enseñarte algunos trucos... si no te importa hacer algo antes, eso es.' WHERE `ID`=7828;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흐음... 글쎄, 나는 아직 당신에게 큰 도움을 줄 수 없겠네요! 당신은 우선 기본적인 것부터 배워야겠습니다. 스톰윈드로 가서 스프라이트 점프스프로켓을 찾아보시기 바랍니다.', `MaleText_loc4`='嗯……好吧，我现在还帮不到你！你必须先学习基础知识。你为什么不去见见暴风城的斯普莱特呢！', `MaleText_loc5`='嗯。好吧，我還不能幫你!你必須先學習基礎知識。你為什麼不去見見暴風城的斯普萊特呢!', `MaleText_loc7`='Ummm... ¡Todavía no puedo ayudarte! Antes tienes que aprender los principios básicos. ¿Por qué no vas a ver a Duendy Ruedadentada en Ventormenta?' WHERE `ID`=7829;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대단하군요! 당신 정말 열심히 하는군요. 자, 그럼 시작해 봅시다.', `MaleText_loc4`='太棒了！难道你不是一个勤奋的人吗？好的，让我们开始吧，行吗？', `MaleText_loc5`='太棒了!難道你不是一個勤奮的人嗎?好的，讓我們開始吧，行嗎?', `MaleText_loc7`='¡Fantástico! ¿Tú eres bastante $gtrabajador:trabajadora; verdad? Bien, empecemos, ¿te parece?' WHERE `ID`=7830;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디 보자... 14 더하기 7은... 2 올라가고... 아, 네?', `MaleText_loc4`='让我看看……14加7，得1进2……是吗？', `MaleText_loc5`='讓我看看...14加7，得1進2...是嗎?', `MaleText_loc7`='Veamos... catorce más siete, me llevo dos... ¿sí?' WHERE `ID`=7831;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 빨리 배우는군요! 제가 달리 가르쳐 드릴 게 없네요. 하지만 스프링스핀들 피즐기어라면 틀림없이 더 많은 걸 가르쳐 줄 겁니다! 그 친구를 만나려면 아이언포지로 가세요. 행운을 빌어요!', `MaleText_loc4`='嗯，你学得速度蛮快的！我没法教给你所有知识，但是宾斯匹德是可以的！你可以在铁炉堡中找到他。祝你好运！', `MaleText_loc5`='嗯，你學習速度蠻快的!我沒辦法教你更多知識了，但是賓斯匹德可以!你可以在鐵爐堡裡找到他。祝你好運!', `MaleText_loc7`='¡Bien, vas a toda velocidad! No puedo enseñarte nada que ya no sepas, ¡pero Muello Saltarín podrá! Lo encontrarás en Forjaz. ¡Buena suerte!' WHERE `ID`=7832;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가는 정이 있으면 오는 정도 있어야지요! 제가 한수 가르쳐드릴 테니 그 전에 먼저 간단한 일 한 가지만 해주시지요...', `MaleText_loc4`='成交！我会将我所知的传授给你，但是你首先得执行一个小任务……', `MaleText_loc5`='成交!我會將我所知的傳授給你，但是在那之前我要你替我執行一個小任務。', `MaleText_loc7`='¡Quid pro quo! Te enseñaré lo que quieres saber, pero antes quiero que realices una pequeña tarea.' WHERE `ID`=7833;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='때가 되면 나한테서도 배울 수 있게 되겠지만 아직은 이릅니다... 이곳 내 오른편에 있는 스프라이트 점프스프로켓과 먼저 얘기를 나눠 보십시오. 기본기를 다지거든 날 다시 찾아오시기 바랍니다!', `MaleText_loc4`='你总有一天能跟我学习……但现在还不是时候！为什么不先跟站在我右边的斯普莱特聊聊呢。入门之后再来找我！', `MaleText_loc5`='馬上你就可以跟我學習...但不是現在!為什麼你不從跟我右邊的斯普萊特談話開始呢。你熱好身以後再來找我!', `MaleText_loc7`='Seguro que podrás aprender de mí. ¡Pero todavía no! Deberías empezar hablando con Duendy Ruedadentada, a mi derecha. Cuando ya te hayas estrenado puedes volver a intentarlo conmigo.' WHERE `ID`=7834;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='확실히 솜씨가 괜찮군요! 일을 끝냈으니 이제 수업을 시작합시다!', `MaleText_loc4`='你当然不会失望!现在既然我们已经把那个清除掉,你可以下达指令了!', `MaleText_loc5`='你當然不會失望!現在既然我們已經把那個清除掉,你可以下達指令了!', `MaleText_loc7`='¡No me has defraudado! ¡Ahora que te has quitado eso de en medio puede comenzar tu instrucción!' WHERE `ID`=7835;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='6미터 높이의 칠면조 조리 기계 설계도가 거의 다 완성됐어요! 이제 6미터짜리 칠면조만 있으면 되는데...', `FemaleText_loc4`='我的二十英尺高的火鸡烤肉架的计划快要完成了！现在我需要的就是一只二十英尺高的火鸡了……', `FemaleText_loc5`='我的二十英尺高的火雞烤肉架的計畫快要完成了!現在我需要的就是一隻二十英尺高的火雞了...', `FemaleText_loc7`='¡El diseño de mi rociador de pavos de siete metros ya casi está terminado! Ahora lo único que necesito es un pavo de siete metros...' WHERE `ID`=7836;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리끼리만 하는 얘긴데, 저도 모든 걸 다 아는 건 아니랍니다! 계속 배우고 싶으시다면 가게 주인인 스프링스핀들 피즐기어와 얘기해 보셔야 할 거예요.', `FemaleText_loc4`='不要告诉任何人我说过，就当我什么都不知道！如果你还想学习，你应该与店主宾斯匹德谈谈。', `FemaleText_loc5`='不要告訴任何人我說過，就當我什麼都不知道!如果你還想學習，你應該與店主賓斯匹德談談。', `FemaleText_loc7`='No le digas a nadie esto pero... ¡no lo sé todo! Si quieres seguir aprendiendo deberías hablar con el propietario de la tienda, Muello Saltarín.' WHERE `ID`=7837;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제 비법을 전수해 주기 전에 먼저 당신이 배울 자격이 있다는 걸 보여 주셔야 해요! 아주 적당한 시험이 하나 있죠...', `FemaleText_loc4`='在我袒露秘密之前，你得证明自己的价值！我会对你进行测试的。', `FemaleText_loc5`='在我袒露秘密之前，你得證明自己的價值!我會對你進行測試的。', `FemaleText_loc7`='¡Tendrás que probar que lo mereces antes de darte todos mis secretos! Ya tengo lista tu prueba...' WHERE `ID`=7838;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭐, 거의 가깝긴 하지만 아직은 안 되겠네요. 아무래도 먼저 제 여동생 젬마와 얘기를 나눠 보셔야 할 것 같군요. 젬마한테서 기본기를 배운 다음 절 찾아오시면 아주 끝내주는 것들을 보여 드리죠!', `FemaleText_loc4`='靠近点，但是不要抽雪茄！我恐怕你必须得先跟我的妹妹洁娜谈谈。当她领你复习完基础知识再回来找我，我那时就会让你见识真正有趣的东西！', `FemaleText_loc5`='靠近點，但是不要抽雪茄!我恐怕你必須得先跟我的妹妹潔娜談談。當她領你復習完基礎知識再回來找我，我那時就會讓你見識真正有趣的東西!', `FemaleText_loc7`='Casi, pero no. Me temo que tendrás que hablar antes con mi hermana Jemma. Cuando te haya enseñado los principios básicos ven a verme, ¡y te enseñaré lo bueno!' WHERE `ID`=7839;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='초보자치고는 상당한데요? 당신에게 몇 가지 가르쳐 줘도 문제없을 것 같군요...', `FemaleText_loc4`='对一个初学者来说还不坏！我猜给你看些东西也不会对我有什么损失……', `FemaleText_loc5`='對一個初學者來說還不壞!我猜給你看些東西也不會對我有什麼損失...', `FemaleText_loc7`='¡No está mal para $gun:una; principiante! No me hará ningún daño enseñarte un par de cosas...' WHERE `ID`=7840;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하루가 몇 시간만 더 길다면 좋을 텐데...', `MaleText_loc4`='要是离天黑还有些时间的话……', `MaleText_loc5`='要是離天黑還有些時間的話...', `MaleText_loc7`='Si el día tuviera unas cuantas horas más...' WHERE `ID`=7841;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 이제 나보다 더 훌륭한 스승에게 훈련받을 수 있는 특권을 얻은 겁니다. 저기 내 친구 록시크와 얘기해 보시죠.', `MaleText_loc4`='你赢得了到一个更高级的导师那里学习的权利。去见见我那边的朋友罗克希克。', `MaleText_loc5`='你贏得了到一個更高級的導師那裡學習的權利。去見見我那邊的朋友羅克希克。', `MaleText_loc7`='Has ganado el privilegio de recibir instrucción de alguien más elevado. Ve a ver a mi colega Roxxik.' WHERE `ID`=7842;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하루하루가 다 시험이고, 오늘 역시 예외는 아니죠. 이 시험을 통과하면 내 지식을 좀 전수하도록 하겠어요...', `MaleText_loc4`='每天都是考验，这天也不例外。如果你通过这次测试，我会教你一些知识……', `MaleText_loc5`='每天都是考驗，這天也不例外。如果你通過這次測試，我會教你一些知識...', `MaleText_loc7`='Cada día es una prueba, y hoy no será distinto. Si superas esta prueba compartiré contigo algo de mi saber...' WHERE `ID`=7843;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 아직 나에게 가르침을 받을 수 있는 권리를 얻지 못했어요. 저쪽 탁자 옆에 있는 선드부터 먼저 만나 보시죠. 그가 당신더러 준비가 됐다고 하거든 다시 날 찾아오시고요.', `MaleText_loc4`='你还没有资格接受我的培训。先去见见桑德，就在那张桌子旁边。当他说你可以了再来找我！', `MaleText_loc5`='你還沒有資格接受我的培訓。先去見見桑德，就在那張桌子旁邊。當他說你可以了再來找我!', `MaleText_loc7`='Todavía no te has ganado el derecho de instruirte conmigo. Ve a ver antes a Thund, junto a la mesa. ¡Vuelve cuando diga que estás $gpreparado:preparada;!' WHERE `ID`=7844;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시험을 통과했군요. 잘하셨어요! 이제 훈련을 계속하죠.', `MaleText_loc4`='你已经通过测试了，干得好！对你的培训可以继续了。', `MaleText_loc5`='你已經通過測試了，幹得好!對你的培訓可以繼續了。', `MaleText_loc7`='Has superado la prueba, ¡bien hecho! Tu instrucción puede continuar.' WHERE `ID`=7845;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한가하게 잡담이나 하고 있을 시간 없습니다. 저는 프로란 말입니다!', `MaleText_loc4`='我可没时间闲谈，我是个专业人士！', `MaleText_loc5`='我可沒時間閒談，我是個專業人士!', `MaleText_loc7`='No tengo tiempo para chismes, ¡soy un profesional!' WHERE `ID`=7846;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 뭘 가르쳐 줄 수 있을 거라 생각하는 건가? 그런 거라면 록시크가 훨씬 더 잘할 걸세. 그 친구는 오그리마에 가면 있을 테니 어서 가 보게!', `MaleText_loc4`='你认为我能教给你什么？罗克希克比我更适合做你的老师。你可以在奥格瑞玛找到他。出发吧。', `MaleText_loc5`='你認為我能教給你什麼?羅克希克比我更適合做你的老師。你可以在奧格瑪找到他。出發吧。', `MaleText_loc7`='¿Qué crees que podría enseñarte? Roxxik lo haría mucho mejor. Podrás encontrarlo en Orgrimmar. ¡Vete de aquí!' WHERE `ID`=7847;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 실력이 어느 정도 되는지 어디 한번 볼까? 이 임무를 내가 만족할 수 있을 정도로 잘 완수한다면 내 시간을 내서 자네를 가르쳐 주도록 하겠네!', `MaleText_loc4`='让我们看看你的能力，好吗？要是你按要求完成任务，我会乐意教你的！', `MaleText_loc5`='讓我們看看你的能力，好嗎?要是你按要求完成任務，我會樂意教你的!', `MaleText_loc7`='Veamos cómo eres de competente, ¿te parece? Si realizas bien esta tarea, dedicaré mi tiempo a instruirte.' WHERE `ID`=7848;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 당신한테나 나한테나 시간 낭비야! 훈련을 시작하고 싶거든 그레이엄 반 탈렌을 찾아가 보게! 그 친구는 저기 내 왼쪽에 서 있으니까 말이야.', `MaleText_loc4`='我们彼此都在浪费时间！如果你想接受训练的话，就去找格拉哈姆·范·塔伦吧！他就站在右边。', `MaleText_loc5`='我們彼此都在浪費?間!如果你想接受訓練的話，就去找格拉哈姆·範·塔倫吧!他就站在右邊。', `MaleText_loc7`='Es una pérdida de tiempo, para ti y para mí. Si quieres comenzar tu instrucción ve a ver a Graham Van Talen. Está a mi izquierda, por ahí.' WHERE `ID`=7849;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠... 좀 하시는군요. 시간을 내서 몇 가지 가르쳐드려도 될 것 같은데요...', `MaleText_loc4`='呃……你给我留下了深刻印象。我想我会花时间传授知识给你的……', `MaleText_loc5`='呃...你給我留下了深刻印象。我想我會花時間傳授知識給你的...', `MaleText_loc7`='Bien... casi me has impresionado. Supongo que podría dedicarte tiempo para unas cuantas lecciones...' WHERE `ID`=7850;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 계산이 맞는다면 이 바퀴는 곧 구식이 되어 버릴 겁니다!', `MaleText_loc4`='要是我计算正确的话，这车轮很快就会作废的！', `MaleText_loc5`='要是我計算正確的話，這車輪很快就會作廢的!', `MaleText_loc7`='Si mis cálculos son correctos, ¡esta rueda pronto quedará obsoleta!' WHERE `ID`=7851;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 그동안 많은 훈련을 쌓아 왔군요. 수련을 좀 더 쌓고 싶다면, 사막으로 여행을 떠나야 할 겁니다. 가젯잔으로 가서 부젝 브라켓스윙을 찾아보세요!', `MaleText_loc4`='你的训练已经非常深入了，只有一个导师可以进一步地训练你。找到加基森的巴兹克·布拉斯温！', `MaleText_loc5`='你確實投注了很多心力於你的訓練當中。如果你想要得到更多的知識，你就必須前往沙漠。去找到加基森的巴茲克·布拉斯溫!', `MaleText_loc7`='La verdad es que has avanzado mucho en tu instrucción. Si quieres aprender más, tendrás que viajar al desierto. ¡Busca a Buzzek Giracorchete de Gadgetzan!' WHERE `ID`=7852;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 능력을 의심하는 건 아니지만 먼저 날 위해 한 가지 임무를 수행해 주었으면 하오. 신의를 입증해 보이기 위한 것이라고 할 수 있지...', `MaleText_loc4`='我并非怀疑你的能力，但是我希望你为我执行一项任务，以此证明你的信念。', `MaleText_loc5`='我並非懷疑你的能力，但是我希望你為我執行一項任務，以此證明你的信念。', `MaleText_loc7`='No es que dude de tus habilidades, pero me gustaría que hicieras una tarea para mí. Considérala una muestra de buena fe...' WHERE `ID`=7853;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 가르쳐 줄 내용은 당신 머리를 어지럽게 만들 겁니다! 충분히 배운 후에 다시 찾아오도록 하세요!', `MaleText_loc4`='我要教你的东西会让你头脑混乱的！当你学到足够的知识后再来找我吧！', `MaleText_loc5`='我要教你的東西會讓你頭腦混亂的!當你學到足夠的知識後再來找我吧!', `MaleText_loc7`='¡Las cosas que podría enseñarte te harían temblar los sesos! ¡Vuelve cuando hayas aprendido lo suficiente!' WHERE `ID`=7854;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 좋아요. 내게 배울 만한 자격이 있다는 걸 보여 줬으니 이제 다음 순서로 넘어갑시다!', `MaleText_loc4`='很好，你已经证明了你自己！现在进入下一阶段的授课……', `MaleText_loc5`='很好，你已經證明了你自己!現在進入下一階段的授課...', `MaleText_loc7`='Excelente, ¡has demostrado tu valía! Ahora pasemos a la siguiente fase de tu instrucción...' WHERE `ID`=7855;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가끔 저는 저 자신에게도 깜짝 놀랍니다!', `MaleText_loc4`='有时，连我自己都感到惊讶！', `MaleText_loc5`='有時，連我自己都感到驚訝!', `MaleText_loc7`='¡A veces me sorprendo hasta a mí mismo!' WHERE `ID`=7856;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 모르는 걸 가르쳐 줄 수는 없잖나! 나보다 더 많이 아는 누군가가 있다면 모를까... 잠깐, 그렇지! 가젯잔에 있는 부젝 브라켓스윙을 만나 보게!', `MaleText_loc4`='我没有什么可以教你的啦！如果有人比我知道得多……等等，有啦！去加基森找巴兹克·布拉斯温吧。', `MaleText_loc5`='我沒有什麼可以教你的啦!如果有人比我知道得多...等等，有啦!去加基森找巴茲克·布拉斯溫吧。', `MaleText_loc7`='¡No puedo enseñarte lo que no sé! Si hubiera alguien que supiera más que yo... ¡espera, sí lo hay! ¡Ve a ver a Buzzek Giracorchete de Gadgetzan!' WHERE `ID`=7857;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네라면 이렇게 간단한 과제 정도는 손쉽게 해낼 수 있을 것 같은데... 내가 제대로 봤는지 어디 한번 보세나!', `MaleText_loc4`='我认为你更能胜任这项小任务……看看我的说法是否正确！', `MaleText_loc5`='我認為你更能勝任這項小任務...看看我的說法是否正確!', `MaleText_loc7`='Creo que estás más que $gcualificado:cualificada; para esta pequeña tarea... ¡veamos si tengo razón!' WHERE `ID`=7858;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노력하는 건 좋지만, 나한테서 배우려면 경험이 좀 더 있어야겠군! 좀 더 경험을 쌓도록 하게나!', `MaleText_loc4`='很好的尝试，但是在训练之前，你还需要进行更多的锻炼！回到战壕！', `MaleText_loc5`='很好的嘗試，但是在訓練之前，你還需要進行更多的鍛鍊!回到戰壕!', `MaleText_loc7`='Buen intento, ¡pero necesitarás algo más de experiencia antes de instruirte conmigo! ¡Vuelve a las trincheras!' WHERE `ID`=7859;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘했네! 다른 사람들이 뭐라고 하든 나는 내가 당신을 제대로 본 줄 알았다니까. 하하! 농담일세! 좋아, 수업을 시작하도록 하지...', `MaleText_loc4`='很好！无论其他人怎么说，我想我对你的看法是正确的。哈哈！我是开玩笑的！好吧，开始上课……', `MaleText_loc5`='很好!無論其他人怎麼說，我就知道我對你的看法是正確的。哈哈!我是開玩笑的!好吧，開始上課。', `MaleText_loc7`='¡Buen trabajo! No me equivoqué contigo, no importa lo que digan los demás. ¡Ja! ¡Estoy bromeando! Muy bien, ¿seguimos nuestras lecciones?' WHERE `ID`=7860;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지하 통로를 통해 대도시들 간에 기름을 운송할 방법을 연구하고 있었는데, 다들 뜬구름 잡는 얘기라고 하는군.', `MaleText_loc4`='我一直在研究在大城市间通过地下通道运送石油的方法，但是每个人都认为我是在做白日梦。', `MaleText_loc5`='我一直在研究在大城市間通過地下通道運送石油的方法，但是每個人都認為我是在做白日夢。', `MaleText_loc7`='He estado trabajando en una forma de transportar petróleo bajo tierra entre las ciudades más importantes, pero todos dicen que son castillos en el aire.' WHERE `ID`=7861;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 이제 당신은 어떤 사람들은 꿈밖에 꾸지 못하는 높은 경지에 다다른 걸세. 축하하네! 그럼 이제 축하는 이 정도로 해 두고 마지막 수업을 시작하도록 하세!', `MaleText_loc4`='我的朋友，你所掌握的学识已经到了别人梦寐以求的程度。祝贺你！无需更多的仪式，开始你的最后一课吧！', `MaleText_loc5`='我的朋友，你所掌握的學識已經到了別人夢寐以求的程度。恭喜你!無需更多的儀式，開始你的最後一課吧!', `MaleText_loc7`='Bien $gamigo:amiga; has llegado a niveles con los que algunos solo pueden soñar. ¡Felicidades! Y ahora, sin más ceremonias, ¡ha llegado el momento de tu última lección!' WHERE `ID`=7862;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제까지 닦아 온 실력을 보여 보시게! 내 생각엔 틀림없이 잘해 낼 것 같으니까 말이야!', `MaleText_loc4`='给你看看你得到了什么！我承诺，你不会有遗憾的！', `MaleText_loc5`='給你看看你得到了什麼!我承諾，你不會有遺憾的!', `MaleText_loc7`='¡Enséñame lo que tienes! No te arrepentirás, ¡lo prometo!' WHERE `ID`=7863;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나에게 배울 준비가 된 이를 돌려보내는 일은 절대로 없소만, 유감스럽게도 자네는 그런 사람이 아닐세! 아직 배워야 할 게 많이 남아 있단 말일세!', `MaleText_loc4`='我从不拒绝那些已经准备好跟我一同训练的人。不幸的是，你不是！你还像个小孩！', `MaleText_loc5`='我從不拒絕那些已經準備好跟我一同訓練的人。不幸的是，你不是!你還像個小孩!', `MaleText_loc7`='Nunca daría la espalda a alguien que está listo para instruirse conmigo. Por desgracia ¡tú no lo estás! ¡Todavía te queda un largo camino $gchiquillo:chiquilla;!' WHERE `ID`=7864;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인이 위험에 처한 것을 본 %s|1이;가; 죽지 않으려고 몸부림칩니다!', `MaleText_loc4`='%s在主人遇到危险时是不会选择死亡的！', `MaleText_loc5`='%s在主人面臨危險時, 是不會輕易死去的!', `MaleText_loc7`='%s se niega a morir mientras su maestro esté amenazado.' WHERE `ID`=7865;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 쓰러지더니 녹아내리기 시작합니다.', `MaleText_loc4`='%s倒在地上并开始冒烟。', `MaleText_loc5`='%s崩潰並開始冒煙。', `MaleText_loc7`='%s se derrumba y comienza a arder.' WHERE `ID`=7866;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 다른 심장부 사냥개에게 힘을 빌려 다시 싸움에 뛰어듭니다!', `MaleText_loc4`='%s因另一只熔火恶犬的高温而复燃！', `MaleText_loc5`='%s因另一隻熔核犬的高溫而複燃!', `MaleText_loc7`='%s vuelve a encenderse del calor de otro can del Núcleo.' WHERE `ID`=7867;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, 여행자님! 제 집에는 무슨 일로 오셨나요?', `FemaleText_loc4`='欢迎，旅行者！是什么风把你吹来的？', `FemaleText_loc5`='歡迎，旅人!是什麼風把你吹來的?', `FemaleText_loc7`='¡Salve, $gviajero:viajera;! ¿Qué te trae hasta mi casa?' WHERE `ID`=7868;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='죄송하지만 당신만큼 경험이 많은 분에게는 제가 가르쳐 드릴 게 없군요. 하지만 당신이 배워야 할 건 아직 더 남아 있으니 저기 카운터 뒤에 있는 루칸 코르델과 얘기해 보세요. 당신 여정의 다음 단계를 안내해 줄 거예요.', `FemaleText_loc4`='我担心对有你这样经验的人没什么可教的。但是你还有其他方法。去找那边柜台后面的鲁坎·考迪尔谈谈。他会指引你通过旅行的下一个阶段。', `FemaleText_loc5`='我擔心對有你這樣經驗的人沒什麼可教的。但是你還有其他方法。去找那邊櫃檯後面的魯坎·考迪爾談談。他會指引你通過旅行的下一個階段。', `FemaleText_loc7`='Me temo que no puedo enseñar nada a alguien de tu experiencia. Pero todavía no has llegado al final de tu camino. Habla con Lucan Cordell, está tras el mostrador. Te guiará en la siguiente etapa de tu viaje.' WHERE `ID`=7869;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='흐음... 당신은 꽤 실력이 있는 것 같군요. 정말로 배우고 싶으시다면 넘지 못할 벽이란 없겠죠! 앞으로 길고도 보람으로 가득 차게 될 여행의 첫걸음은 제가 안내해 드리겠어요.', `FemaleText_loc4`='嗯……你看起来很有能耐。如果你真想学习的话，那么没有什么能阻挡你！我会指引你通过漫长而硕果丰盛的道路上的第一步。', `FemaleText_loc5`='嗯...你看起來很有能耐。如果你真想學習的話，那麼沒有什麼能阻擋你!我會指引你通過漫長而碩果豐盛的道路上的第一步。', `FemaleText_loc7`='Umm... pareces $gcapacitado:capacitada;. ¡Si de verdad deseas aprender, nada se pondrá en tu camino! Te guiaré en los últimos pasos y espero que sea un camino largo y provechoso.' WHERE `ID`=7870;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='망치와 가열로 외에도 강철을 더 강하게 만드는 길은 있습니다, 방랑자 양반.', `MaleText_loc4`='年轻的流浪者，有比铁锤和熔炉更能使钢铁坚固的方法。想学学吗？', `MaleText_loc5`='除了鐵錘和熔爐外還有許多方法能使鋼鐵更堅固，年輕的漫遊者。', `MaleText_loc7`='Hay más modos de reforzar el acero que el martillo y la forja, joven trotamundos.' WHERE `ID`=7871;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 아주 괜찮은 마법부여사로군요! 이제 실력을 더 발전시킬 때가 됐습니다. 위층으로 가서 김블 시슬퍼즈와 얘기해 보는 게 좋겠군요. 좀 괴짜 같은 친구지만 지금부터 당신을 제대로 가르쳐 줄 겁니다!', `MaleText_loc4`='你确实是个不错的附魔师！现在你该继续了。我想让你与楼上的吉布·草须谈谈。他人有些古怪，但是他会继续指引你！', `MaleText_loc5`='你確實是個不錯的附魔師!現在你該繼續了。我想讓你與樓上的吉布·草鬚談談。他人有些古怪，但是他會繼續指引你!', `MaleText_loc7`='¡Eres $gun buen encantador:una buena hechicera;, no hay duda! Es hora de que sigas tu camino. Quiero que hables con Gimble Cardopelusa, en el piso de arriba. Tiene bastante carácter, ¡pero a partir de ahora te mostrará el camino correcto!' WHERE `ID`=7872;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 호기심이 많은 친구로군요. 아주 좋습니다! 상황이 험악해질 때 당신 목숨을 구할 수 있을지도 모르니까 잘 봐 두십시오!', `MaleText_loc4`='啊，你是个好奇的人，是吗？太好了！听仔细了，这也许能在恶劣的环境下保护好你的皮肤！', `MaleText_loc5`='啊，你是個好奇的人，是嗎?太好了!聽仔細了，這也許能在惡劣的環境下保護好你的皮膚!', `MaleText_loc7`='Ah, ¿eres muy $gcurioso:curiosa; eh? ¡Excelente! Presta mucha atención, ¡esto puedo salvarte el pellejo si las cosas se ponen feas!' WHERE `ID`=7873;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이방인이여, 엘룬께서는 제게 지혜를 베푸셨습니다. 엘룬의 뜻이라면 그대에게도 그 지혜를 전해 드리도록 하지요.', `FemaleText_loc4`='女神已经赐予我智慧，陌生人。如果那是她的意愿，我将会把它传给你。', `FemaleText_loc5`='女神已經賜予我智慧，陌生人。如果那是她的意願，我將會把它傳給你。', `FemaleText_loc7`='La Diosa me ha otorgado sabiduría, $gforastero:forastera;. Si ese es su deseo, te la transmitiré.' WHERE `ID`=7874;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그대의 솜씨는 내가 닿을 수 없는 곳에 있군요. 이제 새로운 도전을 할 때입니다. 저기 탁자 옆에 서 있는 탈라단을 찾아가면 그대가 준비하는 걸 도와 줄 겁니다.', `FemaleText_loc4`='你的技能已经非我能及。现在你该接受新的挑战了。塔兰丹会帮你准备。他就站在那里的桌子旁边。', `FemaleText_loc5`='你的技能已經非我能及。現在你該接受新的挑戰了。塔蘭丹會幫你準備。他就站在那裡的桌子旁邊。', `FemaleText_loc7`='Tus habilidades quedan fuera de mi alcance. Es hora de que afrontes nuevos retos. Taladan te ayudará a prepararte. Está junto a esa mesa.' WHERE `ID`=7875;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 할 수 있는 대로 모두 가르쳐 드리지요. 각 수업은 엘룬께서 내리시는 선물이랍니다. 엘룬께서 내려주신 선물을 지혜롭게 사용하면 실패하는 일이 없을 거예요.', `FemaleText_loc4`='我会尽我所能教你。每一节课都是女神亲自给你的礼物。正确使用她的礼物，你就会无往不胜。', `FemaleText_loc5`='我會盡我所能教你。每一節課都是女神親自給你的禮物。正確使用她的禮物，你就會無往不勝。', `FemaleText_loc7`='Te enseñaré lo que pueda. Cada lección es un don de la Diosa. Si te vales de esos dones con sabiduría no flaquearás.' WHERE `ID`=7876;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='엘룬께는 많은 비밀이 있지만, 그 비밀은 아무하고나 나눌 수 없는 것입니다.', `FemaleText_loc4`='月神的秘密很多，但是它们不能让任何人知道。', `FemaleText_loc5`='伊露恩的秘密很多，但是它們不能讓任何人知道。', `FemaleText_loc7`='Son muchos los secretos de Elune, pero no pueden compartirse con cualquiera.' WHERE `ID`=7877;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마법부여 지식이 정말 뛰어나군요. 원한다면 더 많은 것을 배울 수 있답니다. 다르나서스 장인의 정원에 있는 탈라단과 얘기를 나눠 보세요.', `FemaleText_loc4`='你在魔法方面的知识真是很出色。如果你愿意的话，还有很多要学的。跟塔兰丹谈谈，他在达纳苏斯的工匠区。', `FemaleText_loc5`='你在附魔方面的知識真是很出色。如果你願意的話，還有很多要學的。跟塔蘭丹談談，他在達納蘇斯的工匠區。', `FemaleText_loc7`='Realmente has progresado mucho en tu saber sobre encantamiento. Pero aún hay mucho que aprender si lo deseas. Habla con Taladan, en el Bancal del Artesano de Darnassus.' WHERE `ID`=7878;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마음의 눈을 뜨세요, 방랑자여. 그러면 시작하도록 하겠어요.', `FemaleText_loc4`='开阔你的视野，流浪者，我们马上开始。', `FemaleText_loc5`='放開你的心胸，漫遊者，我們馬上開始。', `FemaleText_loc7`='Abre tu mente, trotamundos, y comenzaremos.' WHERE `ID`=7879;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='낭비할 시간이 없네, 이방인 양반. 용건을 말하든가 아니면 썩 물러가게나!', `MaleText_loc4`='陌生人，我没有时间浪费啦。说说你的事儿吧，要么就离开！', `MaleText_loc5`='陌生人，我沒有時間浪費啦。說說你的事兒吧，要麼就離開!', `MaleText_loc7`='No puedo perder el tiempo, $gforastero:forastera;. ¡Expón tus asuntos o lárgate!' WHERE `ID`=7880;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐, 이 정도 해 냈으니... 저기 책장 옆에 있는 라비니아 크로를 만나 보게. 너무 서투르게 굴지만 않으면 좀 더 배울 수 있을 걸세.', `MaleText_loc4`='呃，你进展到这个程度了吗？去那边的书架找拉文尼亚·克洛文。要是你没把事情搞糟，或许你能学到更多知识。', `MaleText_loc5`='呃，你進展到這個程度了嗎?去那邊的書架找拉玟妮雅·克洛威。要是你沒把事情搞糟，或許你能學到更多知識。', `MaleText_loc7`='Eh, bien, has llegado hasta aquí... ve a ver a Lavinia Crowe junto al otro estante. Si tienes cuidado y no echas a perder las cosas con ella, podrás aprender algo más.' WHERE `ID`=7881;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게 그리 대단해 보이진 않지만 혹시 또 모를 일이지, 어딘가에 마법부여사의 재능이 숨어 있을지도!', `MaleText_loc4`='你看起来不怎么像我，但谁知道呢，可能有一个附魔师藏在那里的什么地方！', `MaleText_loc5`='你看起來不怎麼像我，但誰知道呢，可能有一個附魔師藏在那裡的什麼地方!', `MaleText_loc7`='No te pareces mucho a mí, pero quién sabe, ¡quizás haya $gun encantador escondido:una hechicera escondida; ahí dentro!' WHERE `ID`=7882;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 같은 날은 드넓은 초원을 맘껏 거닐고 싶은 맘 간절하지만... 할 일이 있으니 어쩔 수 없지.', `MaleText_loc4`='我最喜欢在这样的日子里到开阔的大草原上去……但是，我的职责所在不容许我那样做。', `MaleText_loc5`='我最不願放棄的就是在這樣的日子裡到開闊的大草原上...但我的職責約束著我。', `MaleText_loc7`='En un día como este lo daría todo por poder salir a los llanos... pero mi deber me lo impide.' WHERE `ID`=7883;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 자네가 이미 알고 있는 것 이상을 가르쳐 줄 수 없네. 하지만 우리 아버지께서 나보다 훨씬 더 많은 것을 알고 계시니 안에 들어가서 우리 아버지와 얘기를 나눠 보게나. 행운을 빌겠네!', `MaleText_loc4`='我不能再教你什么啦。但是，我父亲的知识远胜于我。进去跟他谈谈。祝你好运！', `MaleText_loc5`='我不能再教你什麼啦。但是，我父親的知識遠勝於我。進去跟他談談。祝你好運!', `MaleText_loc7`='No puedo enseñarte nada que ya no sepas. Sin embargo, el saber de mi padre supera en mucho al mío. Pasa adentro y habla con él. ¡Buena suerte!' WHERE `ID`=7884;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='인내와 굳은 결의가 있으면 많은 비밀을 알아낼 수 있지. 자, 시작하세나...', `MaleText_loc4`='只要有耐心和决心，很多秘密都是有可能解开的。现在，让我们开始吧……', `MaleText_loc5`='只要有耐心和決心，很多秘密都是有可能解開的。現在，讓我們開始吧...', `MaleText_loc7`='Con paciencia y determinación pueden abrirse muchos secretos. Ahora, vamos a empezar...' WHERE `ID`=7885;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='트롬카! 뭘 찾고 있는 것이오, 이방인 친구?', `MaleText_loc4`='你好！陌生人，你在找什么？', `MaleText_loc5`='你好!陌生人，你在找什麼?', `MaleText_loc7`='¡Throm-ka! ¿Qué estás buscando, $gforastero:forastera;?' WHERE `ID`=7886;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘못 찾아왔군. 저쪽에 있는 전문가 고단과 얘기하면 더 배울 수 있을 것이오.', `MaleText_loc4`='你来错地方了。去找那边的专家古丹谈谈。你可以从他那儿学到更多东西。', `MaleText_loc5`='你來錯地方了。去找那邊的專家古丹談談。你可以從他那兒學到更多東西。', `MaleText_loc7`='Has venido al lugar equivocado. Habla con el experto Godan. Aprenderás más con él.' WHERE `ID`=7887;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전장에서 전사하는 것은 영광스러운 일! 하지만 내가 가르쳐 주는 걸 배워 두면 그리 빨리 죽지 않을지도 모른다오.', `MaleText_loc4`='战死沙场是件光荣的事儿！但是，若是你能利用我教你的东西，或许你不会死得那么快，嗯？', `MaleText_loc5`='戰死沙場是件光榮的事兒!但是，若是你能利用我教你的東西，或許你不會死得那麼快，嗯?', `MaleText_loc7`='¡Morir en la batalla es glorioso! Pero, con lo que voy a enseñarte, puede que no mueras tan rápido, ¿umm?' WHERE `ID`=7888;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 누구요? 나한테 뭘 원하는 거요?', `MaleText_loc4`='你是谁？你想从我这儿得到什么？', `MaleText_loc5`='你是誰?你想從我這兒得到什麼?', `MaleText_loc7`='¿Quién eres? ¿Qué quieres de mí?' WHERE `ID`=7889;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 마법부여사의 지존이라도 되는 듯이 보이나요? 당신 만큼 실력이 좋은 이라면 대가를 찾아가서 배워야 한다고! 아조라의 탑으로 가서 키타 파이어윈드를 만나보세요.', `MaleText_loc4`='我看起来像什么，附魔师普巴尔？你的技能还需要附魔大师的指导！去阿祖拉之塔找基塔·费温德。', `MaleText_loc5`='我看起來像什麼，附魔師普巴爾?你的技能還需要附魔大師的指導!去阿祖拉之塔找基塔·費溫德。', `MaleText_loc7`='¿Qué te parezco, el Gran Pooh-Bah de los encantadores? ¡Tus habilidades necesitan la guía de un artesano! Ve a buscar a Kitta Vientofuego en la Torre de Azora.' WHERE `ID`=7890;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋습니다, 그럼 시작해 볼까요? 하핫! 속았죠! 나한테서 배우기가 그리 간단할 줄 알았나요? 다른 이들과 마찬가지로 당신도 실력을 증명해 보여야지요!', `MaleText_loc4`='太好了，我们开始吧……哈！你受骗了！你当然不会认为是那么简单吧。你需要像其他人一样证明你的勇气！', `MaleText_loc5`='太好了，我們開始吧...哈!你受騙了!你當然不會認為是那麼簡單吧。你需要像其他人一樣證明你的勇氣!', `MaleText_loc7`='Estupendo, vamos a empezar... ¡ja! ¡Idiota! Seguro que no creías que sería tan fácil. ¡Tendrás que demostrar tu entereza como todos los demás!' WHERE `ID`=7891;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 농담하는 건가요? 당신이 찾는다는 키 작은 친구는 내가 아니라 토니스 필라스톤인 것 같군요. 아래층에 있을 테니 어서 가 보세요!', `MaleText_loc4`='你在开玩笑，是吗？我认为你在寻找那个矮家伙，索恩斯·火石。他就在楼下。现在快逃吧！', `MaleText_loc5`='你在開玩笑，是嗎?我認為你在尋找那個矮傢伙，索恩斯·火石。他就在樓下。現在快逃吧!', `MaleText_loc7`='Estás bromeando, ¿verdad? Creo que estás buscando a mi OTRO colega, Thonys Piedrapilar. Está en el piso de abajo. ¡Sal pitando!' WHERE `ID`=7892;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠, 좋아요. 잘난 척하진 마세요! 당신 실력을 입증해 보였으니 이제 시작합시다!', `MaleText_loc4`='好吧，嗯……别骄傲！既然你已经证明了自己的能力，我们可以开始了！', `MaleText_loc5`='好吧，那麼，別驕傲!你已經證明了自己的能力，我們可以開始了!', `MaleText_loc7`='Bueno, vale... ¡no te pongas $gchulo:chula;! Aunque, como has demostrado tu competencia, ¡podemos empezar!' WHERE `ID`=7893;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게서 배울 만한 실력이 된다면 내 기꺼이 가르쳐 주도록 하겠습니다.', `MaleText_loc4`='如果你带着那东西，我会很高兴地为你指路的。', `MaleText_loc5`='如果你帶著那東西，我會很高興地為你指路的。', `MaleText_loc7`='Si tienes lo necesario, estaré encantado de enseñarte.' WHERE `ID`=7894;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정한 프로는 자신의 한계를 아는 법이지요. 당신 실력이 나보다 뛰어나다는 것을 인정하는 데 전혀 부끄러움이 없습니다. 이제 아조라의 탑에 있는 키타 파이어윈드를 찾아가 보는 게 좋겠습니다. 키타는 아주 유명한데, 충분히 그럴 만한 이유가 있지요.', `MaleText_loc4`='一个真正的专家知道他的局限，而我并不羞于承认你的技能超越了我。我想让你到阿祖拉之塔拜访基塔·费温德。她很有声誉。', `MaleText_loc5`='一個真正的專家知道他的局限，而我並不羞於承認你的技能超越了我。我想讓你到阿祖拉之塔拜訪基塔·費溫德。她很有聲譽。', `MaleText_loc7`='Un verdadero profesional conoce sus límites, y no me avergüenza admitir que tus habilidades superan a las mías. Quiero que hagas una visita a Kitta Vientofuego en la Torre de Azora. Tiene buena fama, y por buenas razones.' WHERE `ID`=7895;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 자신감에 차 있는 것 같군요. 물론 당신의 실력을 시험해 보는 걸 꺼리지는 않겠지요?', `MaleText_loc4`='你看起来很自信。我想你不会介意测试一下你的技术吧？', `MaleText_loc5`='你看起來很自信。我想你不會介意測試一下你的技術吧?', `MaleText_loc7`='Pareces muy $gseguro:segura;, así que no te importará que ponga a prueba tus habilidades, ¿verdad?' WHERE `ID`=7896;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 아직 준비가 덜 됐군요. 저기 계단 옆에 서 있는 베티 퀸과 얘기해 보도록 하고 좀 더 실력을 쌓은 후에 내게 다시 오도록 하십시오.', `MaleText_loc4`='你还没有准备好。找贝蒂·奎恩谈谈，他就站在那边的楼梯旁边。当你提高以后再来找我。', `MaleText_loc5`='你還沒有準備好。找貝蒂·奎恩談談，他就站在那邊的樓梯旁邊。當你提高以後再來找我。', `MaleText_loc7`='No estás $gpreparado:preparada;. Habla con Betty Quinn, la encontrarás junto a las escaleras. Vuelve aquí cuando tu preparación haya mejorado.' WHERE `ID`=7897;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 자신감을 갖기에 충분한 실력을 지니고 있군요, 여행자 친구. 이제 진정한 교육을 시작해도 되겠습니다!', `MaleText_loc4`='旅行者，你有充分的理由让自己充满信心。现在你真正的培训开始了！', `MaleText_loc5`='旅人，你有充分的理由讓自己充滿信心。現在你真正的培訓開始了!', `MaleText_loc7`='Tu confianza está bien fundada, $gviajero:viajera;. ¡Que comience tu verdadera educación!' WHERE `ID`=7898;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나가를 사냥하려면 이용할 수 있는 건 뭐든 이용해야 합니다. 물속 깊이 들어가면 거품 균열이 있는데, 거기서는 공기 방울이 많이 솟아나 물속에서도 숨을 쉴 수 있게 해줍니다. 균열 가까이 헤엄쳐 가서 그 공기 방울을 잘 이용하십시오.', `MaleText_loc4`='如果你想猎杀纳迦，你需要所能获得的所有帮助。水底有裂缝，能产生足够的气泡供你在水下呼吸。向水面游动，就能利用这些气泡了。', `MaleText_loc5`='如果你想獵殺納迦，你需要所能獲得的所有幫助。水底有裂縫，能產生足夠的氣泡供你在水下呼吸。向水面遊動，就能利用這些氣泡了。', `MaleText_loc7`='Si pretendes cazar nagas, necesitarás toda la ayuda que sea posible. En las profundidades del agua encontrarás fisuras burbujeantes que producen burbujas de aire. Te permitirán respirar bajo el agua. Acércate lo suficiente como para poder respirar las burbujas.' WHERE `ID`=7899;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='말라간, 바로 저분이에요. 믿음직하고 용감한 분이죠. 이름은 $n|1이래요;래요;.', `FemaleText_loc4`='看，玛拉甘。我认识$g他:她;。可靠，勇敢，值得信赖。$g他:她;的名字叫$n。', `FemaleText_loc5`='那一個，瑪拉甘。我知道$g他:她;。可靠，勇敢，還有值得信賴。$n是$g他的:她的;名字。', `FemaleText_loc7`='$gEse:Esa;, Malagan. $gLo:La; conozco. $gDigno:Digna; de confianza, valiente y fiable. Su nombre es $n.' WHERE `ID`=7900;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠, $n? $R 시민이여, 이리 와 보시오. 대영주 볼바르 폴드라곤께서는 얼라이언스의 모험가들에게 사지가 멀쩡하다면, 스톰윈드 왕궁에 전원 모이라고 요청하셨소. 바로 당신을 모집하는 것이니 어서 가보시오!', `MaleText_loc4`='$n，嗯？啊！公民$n，过来。伯瓦尔·弗塔根公爵要求联盟所有体格健壮的英雄们都到暴风城要塞见他。你刚刚被征募了，下士！快去！', `MaleText_loc5`='$n，嗯?啊!居民$n，過來。大領主伯瓦爾·弗塔根要求聯盟所有體格健壯的英雄們都到暴風要塞見他。你剛剛被徵募了，下士!快去!', `MaleText_loc7`='¿$n, eh? ¡Oy! $gCiudadano:Ciudadana; $n, ven aquí. El alto señor Bolvar Fordragón ha pedido que todos los héroes sanos de la Alianza se encuentren con él en el Castillo de Ventormenta. ¡Acabas de ser $greclutado:reclutada;! ¡En marcha!' WHERE `ID`=7901;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 자격이 있는 이들에게 가르쳐 줄 기술을 지니고 있는 것은 사실입니다만, 그대에게 그런 자격이 있는지요?', `MaleText_loc4`='我确实有能力对那些有价值的人进行教学。你是这样的人吗？', `MaleText_loc5`='我確實有能力對那些有價值的人進行教學。你是這樣的人嗎?', `MaleText_loc7`='Es cierto que tengo habilidades que enseñar a quienes lo merecen. ¿Lo harás tú?' WHERE `ID`=7902;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대는 아주 뛰어난 마법부여사로군요. 스승인 나의 재능보다도 뛰어난 것 같습니다. 이제 아조라의 탑에 있는 키타 파이어윈드를 찾아가 보십시오. 그대의 스승이 될 만한 이는 이제 그 친구뿐입니다.', `MaleText_loc4`='你是一个非常棒的附魔师。我恐怕已经超出我的才能了。到阿祖拉之塔找到基塔·费温德。现在只有她才配作你的导师。', `MaleText_loc5`='你是一個非常棒的附魔師。我恐怕已經超出我的才能了。到阿祖拉之塔找到基塔·費溫德。現在只有她才配作你的導師。', `MaleText_loc7`='Eres $gun encantador:una hechicera; excepcional. Me temo que superas mi talento como profesor. Busca a Kitta Vientofuego en la Torre de Azora. Ahora es la única que puede servirte de instructora.' WHERE `ID`=7903;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 그대가 이 임무를 맡을 자격이 있다고 믿습니다... 이 임무를 받아들이겠습니까?', `MaleText_loc4`='我相信你能胜任这项任务……你要接受挑战吗？', `MaleText_loc5`='我相信你能勝任這項任務，你要接受挑戰嗎?', `MaleText_loc7`='Creo que eres capaz de realizar estas tareas... ¿aceptarás el reto?' WHERE `ID`=7904;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대는 아직 기본기를 익히지 못했군요, 방랑자 친구. 내 조수, 랄리나 서머문과 얘기해 보았습니까? 그녀와 얘기해 봐야 할 거요.', `MaleText_loc4`='你还没有学会基础知识，流浪者。你找我的助手拉琳娜·夏月谈话了吗？可能你需要跟她谈谈。', `MaleText_loc5`='你還沒有學會基礎知識，漫遊者。你找我的助手拉琳娜·夏月談話了嗎?可能你需要跟她談談。', `MaleText_loc7`='Todavía no has aprendido los principios básicos, trotamundos. ¿Has hablado con mi asistente, Lalina Luna de Verano? Quizás deberías hacerlo.' WHERE `ID`=7905;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘했습니다! 진정 나의 가르침을 받을 만한 자격이 있군요!', `MaleText_loc4`='真是细致的工作！你完全有资格获得我将授予你的知识！', `MaleText_loc5`='真是細緻的工作!你完全有資格獲得我將授予你的知識!', `MaleText_loc7`='¡Buen trabajo! ¡Realmente mereces el saber que puedo transmitirte!' WHERE `ID`=7906;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='진정으로 보람된 길을 걷고 싶다면 마법부여사가 되어 보세요!', `FemaleText_loc4`='如果你在寻找一种真正回报丰厚的事业，那么附魔行业正在等待着你！', `FemaleText_loc5`='如果你在尋找一種真正回報豐厚的事業，那麼附魔行業正在等待著你!', `FemaleText_loc7`='Si buscas una dedicación realmente gratificante, ¡dedica tu vida al encantamiento!' WHERE `ID`=7907;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나도 많은 것을 알고 있지만 그대의 지식 수준은 나와 견줄 만하군요. 기술을 더 연마하고자 하는 마법부여사들은 아조라의 탑으로 간다고들 하죠. 그곳에 키타 파이어윈드라는 대가가 살고 있어요.', `FemaleText_loc4`='我知道很多事，陌生人，但是你的知识与我的不相上下。想更深入研究的附魔师要去阿祖拉之塔，那里住着一个叫做基塔·费温德的工匠。', `FemaleText_loc5`='我知道很多事，陌生人，但是你的知識與我的不相上下。想更深入研究的附魔師要去阿祖拉之塔，那裡住著一個叫做基塔·費溫德的工匠。', `FemaleText_loc7`='Sé muchas cosas, $gforastero:forastera;, pero tu saber rivaliza con el mío. Los encantadores que quieren seguir perfeccionando sus habilidades viajan a la Torre de Azora, donde reside una artesana llamada Kitta Vientofuego.' WHERE `ID`=7908;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그대의 솜씨를 한번 보도록 할까요? 임무를 완수하면 기꺼이 그대를 훈련시켜 드리도록 하죠.', `FemaleText_loc4`='为什么不让我们见识一下你的能耐呢？如果你完成任务我会很高兴对你继续深造！', `FemaleText_loc5`='為什麼不讓我們見識一下你的能耐呢?如果你完成任務我會很高興對你繼續深造!', `FemaleText_loc7`='¿Por qué no vemos de lo que eres capaz? ¡Si completas la tarea estaré encantada de seguir con tu instrucción!' WHERE `ID`=7909;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그대가 준비되었을 때 기꺼이 가르쳐 드리겠지만 아직은 때가 아니로군요! 그때까지는 랄리나 서머문이 그대를 지도해 줄 거예요. 랄리나는 다르나서스에 있는 장인의 정원에서 만날 수 있을 겁니다.', `FemaleText_loc4`='当你准备好后我会很高兴教你，但是那一刻还没有来临！我敢肯定拉琳娜·夏月会一直指引你直到那一刻。你或许会在达纳苏斯的工匠区找到她。', `FemaleText_loc5`='當你準備好後我會很高興教你，但是那一刻還沒有來臨!我敢肯定拉琳娜·夏月會一直指引你直到那一刻。你或許會在達納蘇斯的工匠區找到她。', `FemaleText_loc7`='Estaré encantada de instruirte cuando estés $gpreparado:preparada;, ¡pero aún no ha llegado el momento! Estoy segura de que Lalina Luna de Verano te guiará hasta entonces. La podrás encontrar en el Bancal del Artesano de Darnassus.' WHERE `ID`=7910;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그대는 정말 열심히 해 주었습니다, 이방인 친구. 감사의 마음을 전합니다. 그대를 훈련시켜 주겠다고 약속했으니 이제 그 약속을 지키도록 하겠어요.', `FemaleText_loc4`='你已经竭尽全力了，陌生人，我感激你。我曾答应要继续培训你，而现在我要遵守诺言。', `FemaleText_loc5`='你已經竭盡全力了，陌生人，我感激你。我曾答應要繼續培訓你，而現在我要遵守諾言。', `FemaleText_loc7`='Has hecho todo lo posible, $gforastero:forastera;, y te estoy agradecida. Te prometí seguir tu instrucción y ahora cumpliré esa promesa.' WHERE `ID`=7911;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법부여는 우리 가문 대대로 내려온 일이오. 내 아들 녀석처럼 나도 어렸을 때부터 배웠소이다.', `MaleText_loc4`='我的家族数代都从事附魔工作。我在很小的时候就学会了这项技能，就像我儿子现在在做的一样。', `MaleText_loc5`='我的家族數代都從事附魔工作。我在很小的時候就學會了這項技能，就像我兒子現在在做的一樣。', `MaleText_loc7`='El encantamiento ha acompañado a nuestra familia durante generaciones. Lo aprendí siendo muy joven, como hace ahora mi hijo.' WHERE `ID`=7912;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나보다 더 많이 알고 있는 이가 있소. 이제 당신은 그를 찾아갈 때가 된 것 같소. 돌발톱 산맥에 있는 해바위 야영지로 가시오. 하가스를 만나 계속 훈련을 받도록 하시오.', `MaleText_loc4`='赫加斯掌握的知识远胜于我。你得去石爪山脉的太阳石居所找他，继续训练。', `MaleText_loc5`='赫加斯掌握的知識遠勝於我。你得去石爪山脈的烈日石居找他，繼續訓練。', `MaleText_loc7`='Hay alguien con unos conocimientos que superan a los míos. Estás $glisto:lista; para buscarla. Ve al Refugio Roca del Sol en Sierra Espolón. Busca a Hgarth y continúa tu instrucción.' WHERE `ID`=7913;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 곧 가르쳐 주리다... 단 먼저 당신의 성실함을 증명해 보여야 하오.', `MaleText_loc4`='我会教你……很快的。可我需要你先证明自己的忠心。', `MaleText_loc5`='我很快就會教你。首先，我需要你先表現你的忠誠。', `MaleText_loc7`='Te instruiré... enseguida. Antes necesito una muestra de tu lealtad.' WHERE `ID`=7914;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모트가 아직 준비가 안 된 당신을 내게 보낼 정도로 바보는 아닌데... 당신은 아직 내가 가르칠 내용을 전부 이해할 수 없소. 바로 저 바깥에 있는 내 아들 모트에게 가서 남은 훈련을 마치도록 하시오.', `MaleText_loc4`='明显莫特并没有派你到我这儿来。他知道得很清楚。你还无法理解我能传授给你的知识。去外面找我的儿子莫特，他会对你进行训练的。', `MaleText_loc5`='明顯莫特並沒有派你到我這兒來。他知道得很清楚。你還無法理解我能傳授給你的知識。去外面找我的兒子莫特，他會對你進行訓練的。', `MaleText_loc7`='¿No te ha enviado Mot, verdad? Lo sabe bien. Todavía no puedes comprender lo que yo te enseñaría. Ve a ver a mi hijo Mot, está ahí fuera, y termina con él tu instrucción.' WHERE `ID`=7915;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 아주 잘했소. 당신은 내게 배울 자격이 있군. 당신이 나의 제자가 된다는 사실이 아주 흡족하군. 자, 이제 훈련을 시작합시다...', `MaleText_loc4`='啊，很好。你是个优秀的学生，我对你非常满意。现在，我可以开始训练你了……', `MaleText_loc5`='啊，很好。你是個優秀的學生，我對你非常滿意。現在，我們開始訓練吧。', `MaleText_loc7`='Ah, muy bien. Me complace ver que eres $gun valioso alumno:una valiosa alumna;. ¿Comenzamos tu instrucción conmigo?' WHERE `ID`=7916;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저한테 손님이 찾아오는 일은 드문데... 구체적으로 뭔가 찾으시는 게 있나요?', `FemaleText_loc4`='我很少有访客。你在寻找某种特殊的东西，是吗？', `FemaleText_loc5`='我很少有訪客。你在尋找某種特殊的東西，是嗎?', `FemaleText_loc7`='No recibo muchas visitas. Estás buscando algo en concreto, ¿verdad?' WHERE `ID`=7917;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나도 하루종일 이곳에 처박혀 있지만 않다면 당신 같은 이를 가르칠 수 있을 정도로 기술을 익힐 수 있었을 거예요! 하지만 유감스럽게도 그렇지 못하니 돌발톱 산맥의 해바위 야영지로 하가스를 찾아가 보세요.', `FemaleText_loc4`='如果我不是天天都陷在这里，我已经得到训练你们这些人的技能了！不幸的是事实不是这样。去找石爪山脉太阳石居所的赫加斯谈谈。', `FemaleText_loc5`='如果我不是天天都陷在這裡，我已經得到訓練你們這些人的技能了!不幸的是事實不是這樣。去石爪山脈的烈日石居找赫加斯談談。', `FemaleText_loc7`='¡Si no hubiera estado aquí metida día tras día me habría hecho con la maestría necesaria para instruir a alguien como tu! Por desgracia, no es ese el caso. Ve a hablar con Hgarth en el Refugio Roca del Sol en la Sierra Espolón.' WHERE `ID`=7918;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='흠... 가는 게 있으면 오는 것도 있어야겠죠. 내가 부탁하는 일을 잘해 준다면 당신 훈련에 관해 얘기해 볼 수 있을 거예요.', `FemaleText_loc4`='嗯，你若帮我，我就帮你。如果找我要求的做，并做得很漂亮，或许我们可以谈谈你训练的问题。', `FemaleText_loc5`='嗯，你若幫我，我就幫你。如果找我要求的做，並做得很漂亮，或許我們可以談ˇ你訓練的問題。', `FemaleText_loc7`='Ummm... tú me rascas la espalda y yo la tuya. Si haces lo que voy a pedirte y lo haces bien, tal vez podamos hablar sobre tu instrucción.' WHERE `ID`=7919;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아뇨, 안 되겠어요. 나한테서 배우려면 그 전에 한참 더 훈련을 해야겠군요! 저 무뚝뚝한 초심자 말콤 린한테 가서 얘기해 보세요. 저쪽에 책에 파묻혀 있는 이가 말콤이에요.', `FemaleText_loc4`='不，不，在你准备好跟我学习之前你还需要很多训练！去跟那个保守的业余人士玛考布·维恩谈谈。他就是那个埋在书里的人。', `FemaleText_loc5`='不，不，在你準備好跟我學習之前你還需要很多訓練!去跟那個保守的業餘人士瑪考布·威恩談談。他就是那個埋在書裡的人。', `FemaleText_loc7`='¡No, no, necesitarás MUCHA más instrucción antes de estar $gpreparado:preparada; para aprender de mí! Ve a hablar con ese mojigato de Malcomb Wynn. Es el que está enterrado entre libros.' WHERE `ID`=7920;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='음, 당신은 향상의 여지가 있긴 하네요. 당신이 잠재력을 지니고 있다는 건 인정하죠. 자, 잘 보고 배우도록 하세요!', `FemaleText_loc4`='好吧，我明白些了。但是，你有潜力，这点我不会否定。多加留心你或许就能学到什么东西！', `FemaleText_loc5`='好吧，我明白些了。但是，你有潛力，這點我不會否定。多加留心你或許就能學到什麼東西!', `FemaleText_loc7`='Bueno, he visto cosas mejores. Pero tienes potencial, no lo negaré. ¡Presta atención e intenta aprender algo!' WHERE `ID`=7921;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오게, 여행자 친구! 비전 마법의 수수께끼를 파헤쳐 볼 생각 없나?', `MaleText_loc4`='你好，旅行者！介意探索一下神秘世界的秘密吗？嗯？', `MaleText_loc5`='你好，旅人!介意探索一下神秘世界的秘密嗎?嗯?', `MaleText_loc7`='¡Saludos, $gviajero:viajera;! ¿Quieres sumergirte en los misterios de la magia Arcana? ¿Um?' WHERE `ID`=7922;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 모험가들은 마법부여가 무용지물이라고 생각하지만, 내가 싸움을 걸려고 하면 얼른 말을 바꾼단 말이야.', `MaleText_loc4`='有些冒险家认为附魔术不起作用。我发现当我向他们挑战，要与他们作战时，他们的看法就改变了！', `MaleText_loc5`='有些冒險家認為附魔術不起作用。我發現當我向他們挑戰，要與他們作戰時，他們的看法就改變了!', `MaleText_loc7`='Algunos aventureros creen que el encantamiento no funciona. ¡Si los retase a un combate cambiarían su opinión!' WHERE `ID`=7927;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이방인 친구, 자네의 솜씨는 내가 가르칠 수 있는 정도를 초월했군. 돌발톱 산맥으로 가서 해바위 야영지에서 하가스와 얘기해 보게나. 나보다 더 많은 걸 가르쳐 줄 테니까.', `MaleText_loc4`='你的技艺胜过我的水平了，陌生人。与石爪山脉烈日石居的赫加斯谈谈。他会传授你比我还要多的知识。', `MaleText_loc5`='你的技藝勝過我的水準了，陌生人。與石爪山脈烈日石居的赫加斯談談。他會傳授你比我還要多的知識。', `MaleText_loc7`='Tus habilidades superan con creces a las mías, $gforastero:forastera;. Ve a hablar con Hgarth en el Refugio Roca del Sol de la Sierra Espolón. Con él podrás avanzar en tu conocimiento.' WHERE `ID`=7928;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='솜씨가 있는지 없는지 어디 한번 보세!', `MaleText_loc4`='你可能拥有它所需的。让我们查明真相！', `MaleText_loc5`='你可能擁有它所需的。讓我們查明真相!', `MaleText_loc7`='Quizás tengas lo necesario. ¡Vamos a averiguarlo!' WHERE `ID`=7929;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게 훈련을 받기에는 아직 실력이 조금 부족하구먼, 이방인 친구. 시간을 좀 내서 저쪽에 있는 내 조수 자그를 만나보도록.', `MaleText_loc4`='你现在没有资格受我的培训，陌生人。先到我的助手夏格那里学习一段时间。', `MaleText_loc5`='你現在沒有資格受我的培訓，陌生人。先到我的助手夏格那裡學習一段時間。', `MaleText_loc7`='No estás $glisto:lista; para instruirte conmigo, $gforastero:forastera;. Antes deberás pasar un tiempo con mi asistente Jhag, ahí lo tienes.' WHERE `ID`=7930;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘했네! 자네 눈빛이 예사롭지 않군... 그런 눈빛을 잘 알고 있지. 나도 마법부여를 막 시작했을 때 그런 눈빛을 하고 있었으니까! 자, 이제 당신에게 가르쳐줄 만한 게 뭐가 있나 한번 보세나.', `MaleText_loc4`='干得好！在你眼中闪动的光芒……我很熟悉，我年少时也跟你一样！让我看看能不能教你点什么。', `MaleText_loc5`='幹得好!你的眼中有著那種光芒...我明白，我年幼時就擁有跟你一樣的光芒!讓我看看能不能教你點什麼。', `MaleText_loc7`='¡Bien hecho! ¿Se te ha metido una chispa en el ojo? La conozco bien... ¡es la misma que me dio a mí cuando era un cachorro! Ahora vamos a ver si puedo enseñarte algo.' WHERE `ID`=7931;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아조라의 탑에는 어쩐 일이세요?', `FemaleText_loc4`='是什么使你来到塔楼的？', `FemaleText_loc5`='是什麼使你來到塔樓的?', `FemaleText_loc7`='¿Qué te trae a la Torre?' WHERE `ID`=7932;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='훈련이 거의 절정에 다다랐군요. 더 나은 실력을 갖춘 마법부여사가 되려면 찾아가야 할 스승이 또 있습니다. 그녀의 이름은 안노라라고 하며, 울다만으로 가면 만날 수 있을 겁니다.', `FemaleText_loc4`='你差不多已经达到训练的顶峰了。为了成为你能做到的最伟大的附魔师，你还需见一位导师。她的名字叫做安诺拉，而你或许能在奥达曼找到她。', `FemaleText_loc5`='你差不多已經達到訓練的頂峰了。想要成為一位偉大的附魔師的話，你還需要去找另一位導師。她的名字叫做安諾拉，你或許可以在奧達曼找到她。', `FemaleText_loc7`='Casi has culminado tu instrucción. Para convertirte en $gun gran encantador:una gran hechicera; tienes que buscar una nueva instructora. Su nombre es Annora, la encontrarás en Uldaman.' WHERE `ID`=7933;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이만큼 해낸다는 게 쉽지 않다는 건 알고 있습니다만 어려운 일이 없다면 삶이란 참 지루한 것일 거예요. 안 그런가요? 좋아요. 당신에게 한 가지 과제를 드리도록 하죠...', `FemaleText_loc4`='走到这一步很不容易，我知道。但是生活若没有挑战将会多么枯燥无味啊，你不这么认为吗？很好，因为我有一项任务要交给你……', `FemaleText_loc5`='走到這一步很不容易，我知道。但是生活若沒有挑戰將會多麼枯燥無味啊，你不這麼認為嗎?很好，因為我有一項任務交給你...', `FemaleText_loc7`='Llegar hasta aquí no ha sido fácil, lo sé. Pero la vida sería muy aburrida sin retos, ¿no crees? Estupendo, porque tengo un reto para ti.' WHERE `ID`=7934;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='배우고자 하는 마음이 간절하군요. 좋은 모습이지만 당신은 아직 나 같은 숙련자에게 배울 준비가 안 돼 있어요.', `FemaleText_loc4`='你很热心，这很好。然而，你还不够资格接受像我这样的人的培训。', `FemaleText_loc5`='你很熱心，這很好。然而，你還不夠資格接受像我這樣的人的培訓。', `FemaleText_loc7`='Eres ardiente, eso es bueno. Pero aún no estás $gpreparado:preparada; para instruirte con alguien como yo.' WHERE `ID`=7935;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신 실력은 참으로 현저히 좋아져 가고 있네요. 자, 이제 훈련을 계속해 볼까요?', `FemaleText_loc4`='你的技能正变得非同寻常。现在，继续你的训练……', `FemaleText_loc5`='你的技能正變得非同尋常。現在，繼續你的訓練...', `FemaleText_loc7`='Tus habilidades se están haciendo realmente extraordinarias. Ahora, sigamos con tu instrucción...' WHERE `ID`=7936;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 하가스의 지식을 구하기 위해 온 건가?', `MaleText_loc4`='你是来学习赫加斯部落的知识的吗？', `MaleText_loc5`='你是來學習赫加斯部落的知識的嗎?', `MaleText_loc7`='¿Has venido buscando el saber de Hgarth?' WHERE `ID`=7937;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 분야에서 나를 능가하는 실력을 갖춘 이가 하나 있지. 자네 그 여자의 지식을 전수받을 준비가 됐군. 안노라라고 하는데, 울다만...에서 만날 수 있을 거야.', `MaleText_loc4`='安诺拉是唯一一个在技能上胜过我的人。你得去……奥达曼找她，学习更多知识。', `MaleText_loc5`='有一位是唯一能在技能上勝過我的人。你已經準備好學習她的知識了。她就是安諾拉，而你可以在...奧達曼找到她。', `MaleText_loc7`='Solo hay alguien mejor que yo en este arte. Ya puedes recibir sus saberes. Es Annora, la encontrarás... en Uldaman.' WHERE `ID`=7938;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정 마법부여에 통달한 대가의 위치는 열심히 땀을 흘려서만 얻을 수 있는 것! 이제 모두 자네에게 달려 있네.', `MaleText_loc4`='必须获得真正的实权！现在这一切都取决于你,是现在吗？', `MaleText_loc5`='一定要得到真正的支配權!現在就靠你爭取了...', `MaleText_loc7`='¡Hay que ganarse la auténtica maestría! Ahora hacerlo depende solo de ti...' WHERE `ID`=7939;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='매일 열심히 훈련을 하게. 솜씨를 완벽하게 다듬은 후에 다시 날 찾아오도록 하고.', `MaleText_loc4`='日复一日地坚持训练吧。当你熟练掌握所有技能的时候，再来找我。', `MaleText_loc5`='日復一日地堅持訓練吧。當你熟練掌握所有技能的時候，再來找我。', `MaleText_loc7`='Entrena duro, entrena todos los días. Y cuando hayas perfeccionado tus habilidades, vuelve aquí.' WHERE `ID`=7940;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 마법부여의 대가를 향한 길에서 새로운 경지에 올라섰군. 더 높이 올라갈 수 있을지 어디 한번 보세.', `MaleText_loc4`='你在成为大师的旅途上又达到了新的高度。让我们看看能不能让你更上一层楼……', `MaleText_loc5`='你在成為大師的道路上又創了新高。讓我們看看能不能讓你更上一層樓?', `MaleText_loc7`='Has alcanzado cotas insospechadas en tu camino hacia la maestría. Vamos a ver si puedo llevarte aún más lejos...' WHERE `ID`=7941;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, 여행자님. 저 끔찍한 생물들을 물리쳐 줘서 뭐라고 감사의 말을 전해야 할지 모르겠네요! 평생 숨어 지내야 할지도 모른다고 생각하고 있었거든요!', `FemaleText_loc4`='向你致意，旅行者，你帮我驱散了这些可怕的生物，我将永远感激你！我还以为自己要躲藏一辈子呢！', `FemaleText_loc5`='向你致意，旅人，你幫我驅散了這些可怕的生物，我將永遠感激你!我還以為自己要躲藏一輩子呢!', `FemaleText_loc7`='Saludos $gviajero:viajera;, ¡tienes mi eterna gratitud por haberte ocupado de esas horribles criaturas! ¡Ya empezaba a pensar que tendría que esconderme para siempre!' WHERE `ID`=7942;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자랑스럽군요. 당신은 정말로 재능있는 제자예요. 이제 마지막 수업을 시작해 보도록 하지요.', `FemaleText_loc4`='我很自豪。你真是个天才学生。现在是你的最后一课吗？', `FemaleText_loc5`='我很驕傲。你真是個有天份的學生。現在，你的最後一課...', `FemaleText_loc7`='Estoy orgullosa. Eres $gun alumno:una alumna; muy $gdotado:dotada;. Pasemos ahora a la lección final...' WHERE `ID`=7943;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신에게 필요한 교육이 거의 다 끝나가는군요. 이제 모든 노력의 완성과 당신 사이에는 마지막 임무 하나만이 남아 있을 뿐이랍니다.', `FemaleText_loc4`='你的培训快结束了。完成一项最终的任务你就可以达到你成就的顶点了？', `FemaleText_loc5`='你的培訓快結束了。完成最後一項任務就可以達到你成就的頂點了...', `FemaleText_loc7`='Tu educación casi ha terminado. Una tarea es todo lo que te separa de la culminación de todos tus esfuerzos...' WHERE `ID`=7944;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 지식을 전수받기 전에 먼저 다른 이에게 배워야 할 게 아직 남아 있군요. 부지런히 노력하고 희망을 잃지 마세요.', `FemaleText_loc4`='在我传授你知识之前，你还必须从其他人那里学习一些课程。勤奋些，不要放弃希望。', `FemaleText_loc5`='在我傳授你知識之前，你還必須從其他人那裡學習一些課程。勤奮些，不要放棄希望。', `FemaleText_loc7`='Todavía tienes que aprender de otros algunas lecciones antes de poder compartir contigo mi conocimiento. Sé diligente y no pierdas la esperanza.' WHERE `ID`=7945;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제 남편이 전쟁터에 나가 있기 때문에 헬렌이 저에게 힘이 돼주었답니다. 그녀의 고운 심성과 뛰어난 검술 실력으로 힘든 시기를 견디도록 도와주었죠. 전 헬렌이 없었으면 어떻게 되었을지 정말 모르겠어요.', `FemaleText_loc4`='自从我的丈夫上了前线后，海伦尼便一直保护着我。她用善良的心肠和锋利的宝剑帮助我度过了无数艰难岁月。没有她，我真不知道会发生什么事。', `FemaleText_loc5`='自從我的丈夫上了前線後，海倫尼便一直保護著我。她用善良的心腸和鋒利的寶劍幫助我度過了無數艱難歲月。沒有她，我真不知道會發生什麼事。', `FemaleText_loc7`='Desde que mi marido partió al frente, Helene ha sido mi fuerza. Su amable corazón y su afilada espada me han ayudado en los tiempos difíciles, y han sido muchos. No sé lo que habría hecho sin ella.' WHERE `ID`=7946;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런, 미안해요. 제가 가르쳐 드릴 게 없네요. 스톰윈드 구 시가지에 있는 사이먼 태너를 만나 보세요. 그는 멋진 근육을 가지고 있고 붉은색 머리를 한 친구랍니다.', `FemaleText_loc4`='唉，对不起。我没什么新东西可以教你了。你去暴风城的老城区找西蒙·坦纳尔谈谈怎么样？他是一个肌肉发达有一头漂亮红发的人类。', `FemaleText_loc5`='唉，對不起。我沒什麼新東西可以教你了。你去暴風城的老城區找西蒙·坦納爾談談怎麼樣?他是一個肌肉發達有一頭漂亮紅發的人類。', `FemaleText_loc7`='Gosh, lo siento, no tengo nada nuevo que enseñarte. ¿Por qué no vas a hablar con Simon Peletero en el Casco Antiguo de Ventormenta? Es un humano con grandes músculos y un pelo rojo de ensueño.' WHERE `ID`=7947;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘 지내세요? 저는 가죽 냄새가 너무 좋답니다. 당신은 어떤가요?', `FemaleText_loc4`='它怎么样了？我喜欢皮革的味道；你不喜欢吗？', `FemaleText_loc5`='它怎麼樣了?我喜歡皮革的味道;你不喜歡嗎?', `FemaleText_loc7`='¿Qué tal va? Me encanta el olor del cuero, ¿a ti no?' WHERE `ID`=7948;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='유행 스타일에 대해서는 이미 충분히 알고 있습니다. 이젠 가죽 다듬는 법만 통달하면 되죠. 사이먼이 흔쾌히 도와줘서 정말 다행입니다.', `MaleText_loc4`='我已经了解到很多关于时尚的东西。现在那不过就是掌握制革技巧罢了。西蒙能帮助学习制革的。', `MaleText_loc5`='我已經瞭解到很多關於時尚的東西。現在那不過就是掌握製革技巧罷了。西蒙能幫助學習製革的。', `MaleText_loc7`='Ya sé mucho sobre estilo. Pero ahora se trata de dominar las técnicas del trabajo con cuero. Es estupendo que Simón sea tan comprensivo ayudándome a aprenderlas.' WHERE `ID`=7949;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='색깔 보는 법처럼 자잘한 사항 외에는 더는 당신에게 가르쳐 줄 게 없습니다. 저기 있는 사이먼 태너에게 가보십시오. 숙련된 가죽세공 기술을 가지고 있는 사람입니다.', `MaleText_loc4`='除了对色彩和细节的鉴别能力外，我没有什么可以教你的。跟西蒙·坦纳尔谈谈；他知道很多制皮的高级技能。', `MaleText_loc5`='除了對色彩和細節的鑒別能力外，我沒有什麼可以教你的。跟西蒙·坦納爾談談;他知道很多製皮的高級技能。', `MaleText_loc7`='No puedo enseñarte nada, quizás otros tengan más ojo para el color y los detalles. Habla con Simon Peletero, conoce muchas técnicas avanzadas del trabajo con cuero.' WHERE `ID`=7950;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떠세요? 이 방어구가 제 짙고 서글서글한 눈매를 더욱 돋보이게 하는 것 같지 않습니까? 저를 척 보면 몇 가지 기술 정도는 가르쳐 줄 만큼 솜씨가 뛰어나다고 생각이 안 드십니까? 그러니 제 말을 귀 기울여 잘 들어 보십시오. 아셨죠?', `MaleText_loc4`='这套装备真的让我眼前一亮，你觉得呢？显然，我有多种技能可以使用，我可以将贸易的一些诀窍与你分享。听好了。', `MaleText_loc5`='這套裝備真的讓我眼前一亮，你覺得呢?顯然，我有多種技能可以使用，我可以將貿易的一些訣竅與你分享。聽好了。', `MaleText_loc7`='Este conjunto resalta el azul de mis ojos, ¿no crees? Debería quedar claro que mis técnicas son más que suficientes, así que puedo permitirme el lujo de compartir algunos de mis trucos profesionales. Escucha, ¿de acuerdo?' WHERE `ID`=7951;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저희 집에 오신 것을 환영합니다. 래드날과 저는 가르쳐 드릴 게 별로 없지만 최선을 다해 돕겠습니다.', `FemaleText_loc4`='欢迎来到我们家，$n。拉德纳尔和我没什么东西拿给你，但是我们会尽最大盛情欢迎你。', `FemaleText_loc5`='歡迎來到我們家，$n。拉德納爾和我沒什麼東西拿給你，但是我們會盡最大盛情歡迎你。', `FemaleText_loc7`='$GBienvenido:Bienvenida; a nuestro hogar, $n. Radnaal y yo tenemos poco que ofrecerte, pero te acogemos con toda nuestra hospitalidad.' WHERE `ID`=7952;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='죄송하지만 제가 아는 것은 이미 배우셨군요. 하지만 팔드론이라는 나이트 엘프는 그대를 도와줄 수 있을 것입니다. 다르나서스에 있는 장인의 정원에서 그를 찾아보도록 하세요.', `FemaleText_loc4`='我很抱歉，但你已经学会我所知的一切了。然而，暗夜精灵法多恩可以提供给你进一步的培训。你可以到达纳苏斯的工匠区找他。', `FemaleText_loc5`='我很抱歉，但你已經學會我所知的一切了。然而，夜精靈法多恩可以提供給你進一步的培訓。你可以到達納蘇斯的工匠區找他。', `FemaleText_loc7`='Mis disculpas, pero ya has aprendido todo lo que sé. Sin embargo, el elfo de la noche Faldron podría seguir instruyéndote. Búscalo en el Bancal del Artesano de Darnassus.' WHERE `ID`=7953;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='음... 바느질을 더 꼼꼼히 하셔야 해요. 그러면 화살통과 탄환 주머니에서 물건이 빠지지 않을 겁니다. 게다가 울퉁불퉁한 조끼를 좋아하는 이는 아무도 없을 것이고요.', `FemaleText_loc4`='你要把你的针法做得更小些，$n。这样你的箭袋和弹药袋就不会有东西掉出来。还有，没有人喜欢穿着鼓鼓囊囊的外衣的。', `FemaleText_loc5`='你要把你的針法做得更小些，$n。這樣你的箭袋和彈藥包就不會有東西掉出來。還有，沒有人喜歡穿著鼓鼓囊囊的外套的。', `FemaleText_loc7`='Tienes que hacer los puntos más pequeños, $n. Algunos objetos se saldrían de los carcajes y bolsas de municiones. Además, a nadie le gusta una túnica llena de agujeros.' WHERE `ID`=7954;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가죽세공에 관심이 있으시다면 제대로 찾아오셨습니다. 팔드론과 텔로니스는 진정한 예술가들이죠. 저도 그들에게 많은 것을 배우고 싶습니다.', `FemaleText_loc4`='如果你对皮革缝纫感兴趣，那你算来对地方了。法多恩和泰龙尼斯都是真正的艺术家，而我希望能从他们那里多学些知识。', `FemaleText_loc5`='如果你對皮革縫紉感興趣，那你算來對地方了。法多恩和泰龍尼斯都是真正的藝術家，而我希望能從他們那裡多學些知識。', `FemaleText_loc7`='Si quieres coser cuero, has venido al lugar adecuado. Faldron y Telonis son auténticos artistas, yo espero aprender mucho de ellos.' WHERE `ID`=7955;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오, 죄송하지만 제가 가죽에 대해 아는 것보다 더 많은 것을 알고 계시는군요. 더 많은 것을 배우고 싶으시다면 저기 있는 팔드론을 만나 보세요.', `FemaleText_loc4`='哦，我很抱歉，但是对于皮革你知道的比我要多。如果你想多学些知识的话去找那边的法多恩谈谈。', `FemaleText_loc5`='哦，我很抱歉，但是對於皮革你知道的比我要多。如果你想多學些知識的話去找那邊的法多恩談談。', `FemaleText_loc7`='Oh, lo siento, pero en este momento ya sabes más sobre cuero que yo. Habla con Faldron y deseas seguir aprendiendo.' WHERE `ID`=7956;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이렇게 다르나서스의 유능한 이들에게 둘러싸여 있다니 너무 흥분되지 않나요? 가족들이 저를 자랑스러워할 겁니다. 정말 운이 좋으면 파수대에서 입대해 전방에서 싸워 달라는 부탁을 받게 될지도 모른답니다!', `FemaleText_loc4`='在达纳苏斯这里真是太令人兴奋了，到处都是才华横溢的人们！我这才知道我会让我的家人感到骄傲的。或许如果我幸运的话，哨兵们会请我加入他们前线的军队的！', `FemaleText_loc5`='在達納蘇斯這裡真是太令人興奮了，到處都是才華橫溢的人們!我這才知道我會讓我的家人感到驕傲的。或許如果我幸運的話，哨兵們會請我加入他們前線的軍隊的!', `FemaleText_loc7`='¡Es tan emocionante estar en Darnassus, rodeada de tanta gente con talento! Solo sé que mi familia se sentirá orgullosa. Y tal vez, si tengo suerte, ¡los centinelas me pedirán unirme a sus fuerzas en el frente!' WHERE `ID`=7957;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 모피는 아직 손을 더 봐야 할 거 같군요. 가죽 만드는 데 오래 걸리지 않으면 좋으련만... 이렇게 오래 기다리지 않아도 될 방법이 있을 거예요! 건강에도 안 좋잖아요, 그렇죠?', `FemaleText_loc4`='还没准备好收拾这张皮。我希望做皮革不要花太多时间。肯定有办法削减等待的时间。这对我身体不太好，你知道吗？', `FemaleText_loc5`='還沒準備好收拾這張皮。我希望做皮革不要花太多時間。肯定有辦法削減等待的時間。這對我身體不太好，你知道嗎?', `FemaleText_loc7`='Todavía no se puede trabajar con este pellejo, no está preparado. Ojalá no costara tanto trabajar con el cuero. Tiene que haber algún modo de reducir todo este tiempo de espera. No puede ser bueno para la salud, ¿sabes?' WHERE `ID`=7958;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='으으, 운도 되게 없으시네요! 제 기술은 당신에게 도움이 될 만큼 뛰어나지 않아요. 음... 저기 베틀 옆에 있는 핌블 파인스핀들에게 가 보세요. 저보다 훨씬 더 오래 가죽세공을 했으니까요.', `FemaleText_loc4`='啊，运气真坏！我的技能对你来说一无是处。呃。跟那边的费布·钢轴谈谈吧。他接触皮革的时间比我长多了。', `FemaleText_loc5`='啊，運氣真壞!我的技能對你來說一無是處。呃。跟那邊的費布·鋼軸談談吧。他接觸皮革的時間比我長多了。', `FemaleText_loc7`='Ayy... ¡qué mala suerte! Mis habilidades no te servirían de nada. Pero veamos... Ve a hablar con Fimble Bueneje, junto al telar. Ha trabajado con cuero mucho más tiempo que yo.' WHERE `ID`=7959;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오, 좋았어요! 기다리는 동안 할 일이 생겼네요! $n, 당신은 저의 구세주세요!', `FemaleText_loc4`='哦，好啊，在我等待时找些别的事情做！你真是救命菩萨，$n！', `FemaleText_loc5`='哦，好啊，在我等待時找些別的事情做!你真是救命菩薩，$n!', `FemaleText_loc7`='¡Oh, yupi! ¡Algo que hacer mientras espero! ¡Eres un auténtico salvavidas, $n!' WHERE `ID`=7960;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그 양탄자가 맘에 드시나요? 내 손으로 짐승을 잡아 가죽을 벗겼답니다. 다른 켄타우로스도 다 이렇게 쉽게 잡을 수 있었으면!', `FemaleText_loc4`='你喜欢这地毯吗？我亲自把动物杀死并剥皮的。但愿所有的半人马能被同样容易的击倒。', `FemaleText_loc5`='你喜歡這地毯嗎?我親自把動物殺死並剝皮的。但願所有的半人馬能被同樣容易的擊倒。', `FemaleText_loc7`='¿Te gusta la alfombra? Yo misma maté y desollé a la bestia. Ojalá todos los centauros cayeran tan fácilmente.' WHERE `ID`=7961;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='난 더는 가르칠 게 없군요. 가죽세공에 대해 더 많은 것을 배우려면 카롤렉에게 가보세요.', `FemaleText_loc4`='我没有东西可传授给你了。要是你想进一步学习制皮技能，就找卡洛雷克交谈。', `FemaleText_loc5`='我沒有東西可傳授給你了。要是你想進一步學習製皮技能，就找卡洛雷克交談。', `FemaleText_loc7`='No tengo nada más que enseñarte. Habla con Karolek si quieres seguir mejorando tus habilidades como $gpeletero:peletera;.' WHERE `ID`=7962;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='인간과 그 동맹들의 껍질을 벗길 수 없다니 정말 유감이네요. 그 껍질을 다 허비하다니... 하지만 누가 그런 껍질로 만든 보잘것없는 가죽을 입겠어요?', `FemaleText_loc4`='我们不能剥下人类及其联盟的皮，这真糟糕。这些皮都白白浪费掉了。尽管如此，谁想穿着你由此制造出的质地极差的皮革？', `FemaleText_loc5`='我們不能剝下人類及其聯盟的皮，這真糟糕。這些皮都白白浪費掉了。儘管如此，誰想穿著你由此製造出的質地極差的皮革?', `FemaleText_loc7`='Es una pena que no podamos desollar a los humanos y a sus aliados. Toda esa piel desperdiciada... Pero bueno... ¿quién querría vestirse con ese cuero tan frágil?' WHERE `ID`=7963;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='놀라운 가죽... 내장을 감싸 안아 주죠. 제 피부가 별로 안 좋은 걸 눈치채셨나요? 예전엔 저도 모공 관리를 했었다니까요. 요새는 피부가 거의 남아 있지도 않죠. 어떻게 생각하면 더 자유로워진 것 같아요.', `FemaleText_loc4`='肤质很好。它将你包裹其中。你也许已经注意到我的皮肤不是那么好。我过去常常担心自己的毛孔。这些日子我几乎不担心皮肤了。在某种程度上，它得到了解放。', `FemaleText_loc5`='膚質很好。它將你包裹其中。你也許已經注意到我的皮膚不是那麼好。我過去常常擔心自己的毛孔。這些日子我幾乎不擔心皮膚了。在某種程度上，它得到了解放。', `FemaleText_loc7`='Piel, magnífica piel. Mantiene tus tripas... sujetas. Tal vez hayas notado que mi piel ya no lo hace muy bien. Y pensar que solía preocuparme por mis poros... Ya no me queda casi piel por la que preocuparme. En cierto modo es una liberación.' WHERE `ID`=7964;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가죽세공의 감을 잡았군요. 저는 더 가르칠 것이 없으니 언더시티의 도적 지구에서 일하는 아서 무어라는 포세이큰을 만나서 제가 보냈다고 하면 될 겁니다.', `FemaleText_loc4`='你已经掌握了它的用法。我没有什么要教你的了，但是找亚瑟·摩尔谈谈，他是在幽暗城盗贼区工作的一位被遗忘者。告诉他是我派你去的。', `FemaleText_loc5`='你已經掌握了它的用法。我沒有什麼要教你的了，但是找亞瑟·摩爾談談，他是在幽暗城盜賊區工作的一位被遺忘者。告訴他是我派你去的。', `FemaleText_loc7`='Ya le has cogido el truco. No puedo enseñarte nada más, pero ve a hablar con Arthur Moore, un Renegado que trabaja en el Barrio de los Pícaros de Entrañas. Dile que vas de mi parte.' WHERE `ID`=7965;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='역병이 오기 전에는 가죽의 가라는 글자도 몰랐답니다. 이젠 다른 이들을 충분히 가르칠 수 있을 정도로 알고 있지요. 죽으니 할 일이 없더라고요.', `FemaleText_loc4`='在瘟疫来之前，我对皮革一无所知。现在我的知识可以传授别人了。死亡让我有了很多时间供自己支配。', `FemaleText_loc5`='在瘟疫來之前，我對皮革一無所知。現在我的知識可以傳授別人了。死亡讓我有了很多時間供自己支配。', `FemaleText_loc7`='Antes de que viniera la Peste, no sabía nada sobre el cuero. Ahora sé lo suficiente para instruir a otros. La muerte ha puesto mucho tiempo en mis manos.' WHERE `ID`=7966;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고기, 뼈, 그리고 가죽... 훌륭한 사냥꾼이라면 아무것도 버리지 않는다네. 가죽을 깨끗이 벗겨 동지의 방어구를 두껍게 만들어 줄 수 있지. 즉 혼자서도 독야청청 강할 수 있겠지만 힘을 합치면 무적이 되는 법이야.', `MaleText_loc4`='肉、兽皮、骨头……好的猎人是不会浪费任何东西的。每块兽皮都有利用价值，也许能用来增强盟友的武器装备。单独来看，我们每个人都很强大，但是团结在一起我们就无敌了。', `MaleText_loc5`='肉、獸皮、骨頭...好的獵人是不會浪費任何東西的。每塊獸皮都有利用價值，也許能用來增強盟友的武器裝備。單獨來看，我們每個人都很強大，但是團結在一起我們就無敵了。', `MaleText_loc7`='Carne, piel, huesos... un buen cazador no desperdicia nada. Puede recuperarse cada pedacito de cuero, quizás para reforzar la armadura de un aliado. Todos somos fuertes por separado, pero juntos nos hacemos invencibles.' WHERE `ID`=7967;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 이미 내 능력을 능가하는군. 대지모신의 축복을 등에 업고 전진하게. 썬더 블러프 중앙에서 북서쪽에 있는 갑옷 상점으로 가서 타른이라는 타우렌을 찾아. 그의 지혜의 인도를 구하게나.', `MaleText_loc4`='我已经没什么可教你了。带着大地之母的祝福离开吧。在雷霆崖的中央高原西北方的商店找到牛头人塔恩。愿你得到他智慧的指引。', `MaleText_loc5`='我已經沒什麼可教你了。帶著大地之母的祝福離開吧。在雷霆崖的中央高原西北方的商店找到牛頭人塔恩。願你得到他智慧的指引。', `MaleText_loc7`='Has superado cualquier enseñanza que pueda ofrecerte. Márchate con la bendición de la Madre Tierra. Busca al tauren Tarn en las tiendas que están al noroeste de la meseta central de Cima del Trueno. Que te guíe su sabiduría.' WHERE `ID`=7968;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 이 세계에서 살다가 제 명을 다하면 떠나야 하지만 대지는 세상사에 관계없이 영원히 남는다네. 그러므로 대지는 우리의 것이 아니야. 우리가 대지에 속하는 것이지. 그러므로 우리는 대지를 보호해야 하는 것이야. 대지 없이는 생존할 수 없으니까.', `MaleText_loc4`='我们在此繁衍生息，生生死死，数年来大地却亘古不动。因此，这片土地并不属于我们，$n。我们是属于大地的。因此，我们守护着它，没有它我们就无法生存。', `MaleText_loc5`='我們在此繁衍生息，生生死死，數年來大地卻亙古不動。因此，這片土地並不屬於我們，$n。我們是屬於大地的。因此，我們守護著它，沒有它我們就無法生存。', `MaleText_loc7`='Vivimos y morimos y la tierra permanece, eterna, inalterada por nuestro paso. La tierra no puede pertenecernos, $n. Nosotros pertenecemos a ella. Por ello protegemos la tierra porque sin ella no tenemos ninguna esperanza de sobrevivir.' WHERE `ID`=7969;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 밑에 있는 동굴은 신비하고 놀라운 가죽의 원천일세. 하지만 깊이 들어가면 조심해야 하네. 가죽 몇 조각 구하려다 자네의 가죽이 다칠 수 있으니까. 자네는 소중하다는 걸 항상 기억하게.', `MaleText_loc4`='我们脚下的洞穴中有许多奇异的兽皮，如果你想深入其中探险的话，一定要非常小心，$n。要记住你自己的性命比那些兽皮有价值得多。', `MaleText_loc5`='我們腳下的洞穴中有許多奇異的獸皮，如果你想深入其中探險的話，一定要非常小心，$n。要記住你自己的性命比那些獸皮有價值得多。', `MaleText_loc7`='Las cavernas que yacen bajo nosotros están llenas de extraños y maravillosos pellejos, pero debes tener cuidado si te aventuras hacia las profundidades, $n. Recuerda que tu propia piel es mucho más valiosa.' WHERE `ID`=7970;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가죽에 대한 자네의 지식이 나보다 깊어졌군. 불모의 땅 타우라조 야영지에 있는 크룰무 풀문이라는 타우렌을 만나보는 것이 좋겠네. 자네처럼 재능이 있는 자에게 전해줄 지식이 많으니까.', `MaleText_loc4`='你对皮革的理解比我要深刻。可能你应该拜访一下贫瘠之地陶拉祖营地的牛头人克鲁姆·满月。对你这么聪明的学生他有很多知识要教给你。', `MaleText_loc5`='你對皮革的理解比我要深刻。可能你應該拜訪一下貧瘠之地陶拉祖營地的牛頭人克魯姆·滿月。對你這麼聰明的學生他有很多知識要教給你。', `MaleText_loc7`='Tu conocimiento del cuero supera al mío. Quizás deberías visitar al tauren Krulmoo Lunallena en el Campamento Taurajo en Los Baldíos. Tiene mucho que ofrecer a un estudiante de tu talento.' WHERE `ID`=7971;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 이런 황무지에서조차 배움을 구하는군. 지식에 대한 그 열정 실로 존경할 만하네.', `MaleText_loc4`='即使在这里的荒原里，你仍在寻求知识。你的求知欲是一种令人倾佩的品德。', `MaleText_loc5`='即使在這裡的荒原裡，你仍在尋求知識。你的求知欲是一種令人傾佩的品德。', `MaleText_loc7`='Incluso aquí, en plena naturaleza, quieres aprender. Tu ansia de conocimiento es admirable.' WHERE `ID`=7972;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에 케른이 산다고 하더군. 그의 고귀한 성품과 심오한 지식에 걸맞은 선물을 완성하면 그를 찾아 떠날 거야. 내게 지혜로운 말 한마디쯤은 들려주실지도 모르지.', `MaleText_loc4`='凯恩自己住这儿，他们说。一旦我完成了制作一件合适的礼物，我就会把他找出来。或许他会有智慧的话要对我说。', `MaleText_loc5`='凱恩自己住這兒，他們說。一旦我完成了製作一件合適的禮物，我就會把他找出來。或許他會有智慧的話要對我說。', `MaleText_loc7`='Dicen que el mismísimo Cairne vive aquí. Cuando haya terminado de fabricar un regalo digno de él, iré a buscarle. Quizás tenga alguna palabra sabia que decirme.' WHERE `ID`=7973;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 능력은 이미 나를 앞섰네. 이곳에 있는 타른을 만나 보게나. 가죽에 대한 그의 지식은 나를 압도하니까. 자네라면 흔쾌히 제자로 받아줄 걸세.', `MaleText_loc4`='你的智慧胜于我，朋友。与这里的塔恩谈话；他对皮革的知识比我要丰富得多。我肯定他会欢迎新学生的。', `MaleText_loc5`='你的智慧勝於我，朋友。與這裡的塔恩談話;他對皮革的知識比我要豐富得多。我肯定他會歡迎新學生的。', `MaleText_loc7`='Tu talento supera al mío, $gamigo:amiga;. Ve a hablar con Tarn; su conocimiento sobre el cuero es mucho mayor que el mío. Estoy seguro de que aceptará a otro estudiante.' WHERE `ID`=7974;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='작업을 시작하기 전에 손부터 씻고 오게. 싸움에서 묻은 피나 먼지로 가죽을 더럽히면 그 천연의 아름다움이 사라질 테니까.', `MaleText_loc4`='在你开始任何工作之前都要洗净双手。皮革被血或尘土玷污了会带走它的自然美。', `MaleText_loc5`='在你開始任何工作之前都要洗淨雙手。皮革被血或塵土玷污了會帶走它的自然美。', `MaleText_loc7`='Lávate las manos antes de comenzar cualquier proyecto. Manchar el cuero con sangre o suciedad haría que la piel perdiese su belleza natural.' WHERE `ID`=7975;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 무덤 속에서 기어 나왔을 때 가족들이 나를 두 팔 벌려 반겨줄 것만 같았소. 환대는커녕 이제는 더 이상 이해할 수 없는 언어로 소리를 고래고래 지르며 나를 마을 밖으로 쫓아내더군.', `MaleText_loc4`='当我从墓穴中爬出来后，我本以为我的家人会热烈地欢迎我。相反，他们把我从村里赶了出去，用一种我听不懂的语言高声尖叫着。', `MaleText_loc5`='當我從墓穴中爬出來後，我本以為我的家人會熱烈地歡迎我。相反，他們把我從村裡趕了出去，用一種我聽不懂的語言高聲尖叫著。', `MaleText_loc7`='Cuando conseguí arrastrarme fuera de la tumba, creí que mi familia me recibiría con los brazos abiertos. Pero, al contrario, me echaron de la aldea, gritando en un idioma que ya no podía comprender.' WHERE `ID`=7976;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 자네를 도와줄 수가 없겠군. 자넨 내 능력을 뛰어넘었어. 저기 저 관 앞에 서있는 아서 무어에게 가보게. 나보다 더 많은 걸 가르쳐 줄 거야.', `MaleText_loc4`='我不能帮助你，我无法胜任。跟棺材那边的亚瑟·摩尔谈谈。他会为你提供更多的训练的。', `MaleText_loc5`='我不能幫助你，我無法勝任。跟棺材那邊的亞瑟·摩爾談談。他會為你提供更多的訓練的。', `MaleText_loc7`='No puedo ayudarte; tu trabajo supera en gran medida al mío. Habla con Arthur Moore, está junto a los féretros. Él podrá darte una instrucción mejor.' WHERE `ID`=7977;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 하는 모든 말을 명심하게. 적의 뿌리를 뽑을 때까지는 절대 배움을 게을리해서는 안 돼. 방어구도 열심히 갈고 닦아놓고. 경비도 소홀히 해서는 절대 안 되지.', `MaleText_loc4`='记住我说的每句话。在打败敌人之前，我们绝对不能放弃学习知识、提高自身能力的机会。增强你的实力，绝不能放松警戒。', `MaleText_loc5`='記住我說的每句話。在打敗敵人之前，我們絕對不能放棄學習知識、提高自身能力的機會。增強你的實力，絕不能放鬆警戒。', `MaleText_loc7`='Absorbe cada palabra que te digo y recuérdala bien. Hasta que nuestros enemigos hayan sido erradicados, nunca debemos eludir la oportunidad de ampliar nuestro conocimiento. Refuerza tu armadura y nunca, nunca bajes la guardia.' WHERE `ID`=7978;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살려주시오! 암살자들이 날 죽이려 하오!', `MaleText_loc4`='帮帮我！刺客来杀我了！', `MaleText_loc5`='幫幫我!刺客來殺我了!', `MaleText_loc7`='¡AYUDA! ¡UNOS ASESINOS QUIEREN MATARME!' WHERE `ID`=7979;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자유다! 이제 저 장치 때문에 괴로워할 일은 없으리라!', `MaleText_loc4`='我自由了！那东西再也不能折磨我了！', `MaleText_loc5`='我自由了!那東西再也不能折磨我了!', `MaleText_loc7`='¡Soy libre! ¡Ese dispositivo no volverá a atormentarme!' WHERE `ID`=7980;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그대는 저의 능력을 능가하시는군요. 다르나서스의 장인의 정원에 있는 에이네실이라는 나이트 엘프를 찾아가 보시면 그녀가 더 많은 것을 가르쳐 줄 것입니다. 저도 그대와 함께 가고 싶을 뿐입니다.', `FemaleText_loc4`='你已经超越我有限的能力了。到达纳苏斯的工匠区寻找暗夜精灵安尼希尔。她可以教给你更多知识。我很希望我可以跟你一起去。', `FemaleText_loc5`='你已經超越我有限的能力了。到達納蘇斯的工匠區尋找夜精靈安尼希爾。她可以教給你更多知識。我很希望我可以跟你一起去。', `FemaleText_loc7`='Has superado mis limitadas habilidades. Busca a la elfa de la noche Ainethil en el Bancal del Artesano de Darnassus. Ella te podrá enseñar mejor. Ojalá pudiera ir contigo.' WHERE `ID`=7983;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='절 찾아오시다니 현명한 선택을 하셨습니다. 조그만 부탁을 하나 드릴 테니 도와 주신다면 보답으로 많은 것을 가르쳐 드리겠습니다.', `FemaleText_loc4`='能找到我算你聪明。我想请你帮个小忙。作为回报，我会传授给你很多知识的。', `FemaleText_loc5`='能找到我算你聰明。我想請你幫個小忙。作為回報，我會傳授給你很多知識的。', `FemaleText_loc7`='Ha sido una sabia decisión venir a buscarme. Te voy a pedir un pequeño favor. A cambio, puedo enseñarte muchas cosas.' WHERE `ID`=7984;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 가르치는 내용을 이해하기에 그대의 수준이 너무 낮군요. 물약 제조에 대해 배우고 싶다면 이곳에 있는 텔아실을 만나 보십시오.', `FemaleText_loc4`='对你来说，我的教学在这个阶段略显深奥了。要是你想学习有关药水的更多知识，就跟泰兰希尔谈谈。', `FemaleText_loc5`='對你來說，我的教學在這個階段略顯深奧了。要是你想學習有關藥水的更多知識，就跟泰蘭希爾談談。', `FemaleText_loc7`='Mis enseñanzas te resultarían demasiado avanzadas en este momento. Si quieres aprender más sobre pociones, ve a hablar con Tel''Athir.' WHERE `ID`=7985;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='주의 깊게 들으십시오, $n. 나누어 드릴 지식이 많습니다.', `FemaleText_loc4`='听仔细了，$n，我要传授给你的知识很多。', `FemaleText_loc5`='聽仔細了，$n，我要傳授給你的知識很多。', `FemaleText_loc7`='Escucha detenidamente, $n, porque puedo transmitirte mucho conocimiento.' WHERE `ID`=7986;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게도 한계는 있단 말이야! 계속해서 훈련을 하고 싶다면 언더시티에 있는 라비니아 크로를 찾아가 보게나.', `MaleText_loc4`='即使我也有我的局限性！如果你想继续学习的话去找幽暗城的拉文尼亚·克洛文谈谈。', `MaleText_loc5`='即使我也有我的極限!如果你想繼續學習的話去找幽暗城的拉玟妮雅·克洛威談談。', `MaleText_loc7`='¡Incluso yo tengo limitaciones! Ve a hablar con Lavinia Crowe en Entrañas si deseas recibir más instrucción.' WHERE `ID`=7987;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꽤 괜찮은데... 자네는 훈련을 시킬 만하겠어. 아주 좋아! 그럼 시작해 볼까?', `MaleText_loc4`='还行……训练你是不成问题的。很好！我们开始吧……', `MaleText_loc5`='不錯...訓練你是不成問題的。很好!我們開始吧。', `MaleText_loc7`='No está mal... Supongo que puedo ofrecerte instrucción. ¡Muy bien! Comencemos...' WHERE `ID`=7988;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='랜달은 멋 부리기를 지나치게 좋아하는 것이 사실이지만 제가 가르치는 어떤 학생들보다 믿음직스럽죠. 모험을 좀 좋아한다고 뭐라고 할 수는 없는 일이니까요.', `MaleText_loc4`='兰达尔打扮得有些像花花公子，但是他是个可靠的人，他比我向许多学生所说的那样更加值得信赖。尽管如此，我还是不能责备他们想要冒险的想法。', `MaleText_loc5`='蘭達爾打扮得有些像花花公子，但是他是個可靠的人，他比我向許多學生所說的那樣更加值得信賴。儘管如此，我還是不能責備他們想要冒險的想法。', `MaleText_loc7`='Randal es un tanto chulo, pero te puedes fiar de él, que es más de lo que puedo decir de otros estudiantes que están conmigo. De todas formas, supongo que no puedo culparles por querer un poco de aventura...' WHERE `ID`=7989;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미안하지만 당신을 가르치는 것은 제 능력 밖입니다. 더 많은 것을 배우고 싶다면 다르나서스 장인의 정원에 있는 텔로니스를 찾아가 보세요. 듣기로는 아주 실력파라고 하더군요.', `MaleText_loc4`='很抱歉，我已经没有什么可以教给你的了。如果你还想学的话，就去达纳苏斯的工匠区找泰龙尼斯吧。我听说他相当有才能。', `MaleText_loc5`='很抱歉，我已經沒有什麼可以教給你的了。如果你還想學的話，就去達納蘇斯的工匠區找泰龍尼斯吧。我聽說他相當有才能。', `MaleText_loc7`='Lo siento, pero has alcanzado el límite de lo que puedo enseñarte. Si quieres aprender más, ve a ver a Telonis en el Bancal del Artesano de Darnassus. Tiene mucho talento, o eso es lo que dicen.' WHERE `ID`=7990;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아요. 가르쳐 드리겠습니다. 하지만 그 전에 한 가지 부탁이 있어요. 매우 중요한 일이니 잘 들으세요.', `MaleText_loc4`='好吧，我会教你的，但是我需要你为我做一些事情。这很重要，听仔细了。', `MaleText_loc5`='好吧，我會教你的，但是我需要你為我做一些事情。這很重要，聽仔細了。', `MaleText_loc7`='De acuerdo, te enseñaré, pero quiero que hagas algo por mí. Es importante, así que presta atención.' WHERE `ID`=7991;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좀 더 수련을 한 뒤에 찾아오세요. 저쪽에 있는 랜달 워스에게 가면 당신을 도와드릴 거예요.', `MaleText_loc4`='当你接受更多训练以后再回来找我。在那边的兰达尔·沃斯可以帮你。', `MaleText_loc5`='當你接受更多訓練以後再回來找我。在那邊的蘭達爾·沃斯可以幫你。', `MaleText_loc7`='Vuelve a verme cuando hayas recibido más instrucción. Está allí Randal Valor, él puede ayudarte con eso.' WHERE `ID`=7992;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠, 제자로 받아들여도 될 만큼 실력이 있는 분이로군요. 거기 그렇게 가만히 서있지만 마시고 배우고 싶은 게 뭔지 말해보세요.', `MaleText_loc4`='嗯，我想我可以再收一个学生。好吧，不要傻站在那里。告诉我你想学什么。', `MaleText_loc5`='嗯，我想我可以再收一個學生。好吧，不要傻站在那裡。告訴我你想學什麼。', `MaleText_loc7`='Mmm, supongo que puedo aceptar a otro estudiante. Bueno, no te quedes ahí tranquilamente. Dime qué es lo que quieres aprender.' WHERE `ID`=7993;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다리안나에게 소질이 보이는 것 같기는 한데 활기가 넘쳐서 가만히 듣고 있지를 못합니다. 다리안나가 가진 힘과 민첩성이라면 곧 전투에 불려 나가게 될 텐데. 좀 더 빨리 가르쳐야겠습니다.', `MaleText_loc4`='达丽亚娜答应了，但是她的精力如此充沛，很难让她安静下来仔细的聆听。她气力十足又机灵敏捷，我恐怕她不久就会被叫去参加战斗。我们必须快点教她。', `MaleText_loc5`='達麗亞娜答應了，但是她的精力如此充沛，很難讓她安靜下來仔細的聆聽。她氣力十足又機靈敏捷，我恐怕她不久就會被叫去參加戰鬥。我們必須快點教她。', `MaleText_loc7`='Darianna promete, pero tiene tanta energía que le resulta difícil quedarse quieta y escuchar. Con su fuerza y agilidad, me temo que no pasará mucho tiempo antes de que la llamen a formar filas. Debemos enseñarla rápidamente.' WHERE `ID`=7994;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 많은 배움을 구하러 오셨다면 제 능력을 과대평가하셨습니다. 저쪽에 있는 텔로니스를 만나 보십시오. 그대에게 도움이 될 것입니다.', `MaleText_loc4`='如果你来这儿是为了得到进一步的训练，那你是高估我的能力了。跟泰龙尼斯谈谈；他应该能帮助你。', `MaleText_loc5`='如果你來這兒是為了得到進一步的訓練，那你是高估我的能力了。跟泰龍尼斯談談;他應該能幫助你。', `MaleText_loc7`='Si estás aquí para recibir más instrucción, has sobrestimado mis habilidades. Allí está Telonis. Ve a hablar con él, seguro que puede ayudarte.' WHERE `ID`=7995;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 전쟁은 우리의 생명과 자원을 수없이 앗아갔습니다. 이곳 텔드랏실도 그 영향을 벗어날 수는 없습니다. 죄송합니다만 하나만 부탁을 드려도 되겠습니까?', `MaleText_loc4`='这场战争夺去了很多人的性命，也耗费了大量的资源。即使是泰达希尔的人民也不能幸免于难。请原谅我做出这样的请求，你能帮我执行一项任务吗？', `MaleText_loc5`='這場戰爭奪去了很多人的性命，也耗費了大量的資源。即使是泰達希爾的人民也不能倖免於難。請原諒我做出這樣的請求，你能幫我執行一項任務嗎?', `MaleText_loc7`='Esta guerra ha sido una sangría total de nuestra gente y nuestros recursos. Incluso aquí, en Teldrassil, no podemos escapar a las repercusiones. Perdona por pedirte esto pero, ¿podrías hacer algo por mí?' WHERE `ID`=7996;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간이 지나면 그대도 제 가르침을 받을 준비가 될 것입니다. 그때까지는 저기 있는 다리안나에게 가서 훈련을 받으십시오.', `MaleText_loc4`='你得及时准备好接受我的教学，$n。到那时，找达丽亚娜谈谈，他会帮助你训练的。', `MaleText_loc5`='你得及時準備好接受我的教學，$n。到那時，找達麗亞娜談談，他會幫助你訓練的。', `MaleText_loc7`='Pronto tendrás el suficiente conocimiento como para aprender lo que tengo que enseñarte, $n. Hasta entonces, pídele a Darianna que te ayude con tu instrucción.' WHERE `ID`=7997;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='재료를 구한다는 명분으로 수많은 동물이 희생되었습니다. 그들의 희생을 가볍게 생각해서는 안 됩니다. 숭고한 죽음에 대한 존경심을 가지고 가죽을 다루어 주십시오.', `MaleText_loc4`='我们可以从死去的动物身上获得原料。别无视它们的牺牲，$n。带着尊敬来处理这些皮革。', `MaleText_loc5`='我們可以從死去的動物身上獲得原料。別無視它們的犧牲，$n。帶著尊敬來處理這些皮革。', `MaleText_loc7`='Muchos animales han perdido su vida para que nosotros pudiéramos obtener estos materiales. No permitas que su sacrificio haya sido en vano, $n. Trata el cuero con el respeto que se merece.' WHERE `ID`=7998;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='휴, 할 일이 너무 많네요! 제 사촌의 실수로 놈리건의 모든 옷감과 가죽이 증발한 뒤로 이렇게 바쁜 적 처음이랍니다. $n, 그러고 보니 요새 꽤 추웠죠?! 아, 옛날이여...', `MaleText_loc4`='要做的事情很多！自从我的兄弟不小心蒸发了诺莫瑞根所有的衣料和皮革之后，事情便多起来了。我只能保持暂时通风！啊，$n，那些日子……', `MaleText_loc5`='要做的事情很多!自從我的兄弟不小心蒸發了諾姆瑞根所有的衣料和皮革之後，事情便多起來了。我只能保持暫時通風!啊，$n，那些日子...', `MaleText_loc7`='¡Mucho que hacer! No he estado tan ocupado desde que mi primo, accidentalmente, vaporizase todas las telas y el cuero de Gnomeregan. ¡Cielos, sí que todo estuvo húmedo durante un tiempo! Ah, $n, esos eran buenos días...' WHERE `ID`=7999;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아뇨, 도와 드릴 수가 없네요. 이미 저를 능가하셨거든요! 더 배우고 싶으시다면 다르나서스 장인의 정원에 있는 텔로니스라는 나이트 엘프에게 가 보세요. 정말 훌륭한 분이죠!', `MaleText_loc4`='不，恐怕我不能帮你。你的技能远胜于我！如果你想学习更多的知识，跟达纳苏斯工匠区的暗夜精灵泰龙尼斯谈谈。他拥有令人惊异的技能！', `MaleText_loc5`='不，恐怕我不能幫你。你的技能遠勝於我!如果你想學習更多的知識，跟達納蘇斯工匠區的夜精靈泰龍尼斯談談。他擁有令人驚異的技能!', `MaleText_loc7`='No, me temo que no puedo ayudarte. ¡Tu habilidad me aventaja! Si quieres aprender más, ve a ver al elfo de la noche Telonis en el Bancal del Artesano de Darnassus. ¡Es increíble!' WHERE `ID`=8000;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='척 보니 재능 있는 분이라는 걸 알겠네요. 저도 좋습니다. 요즘 한참 바쁘거든요. 참, 그러고 보니 생각이 나는데 얼른 심부름 하나만 해주실래요?', `MaleText_loc4`='你的学习速度真快。这很好，我最近实在是太忙啦。事实上，那倒提醒了我：你能帮我办件差事吗？', `MaleText_loc5`='你的學習速度真快。這很好，我最近實在是太忙啦。事實上，那倒提醒了我:你能幫我辦件差事嗎?', `MaleText_loc7`='Puedo ver que aprenderás rápidamente. Lo que me viene muy bien, porque siempre estoy ocupado estos días. De hecho, eso me recuerda... ¿Podrías hacerme un rápido recado?' WHERE `ID`=8001;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아! 새로운 학생이로군요! 기술을 조금만 더 익혀오시면 제가 아는 것을 기꺼이 가르쳐 드리죠. 저쪽에 있는 그레타 파인스핀들에게 가 보세요. 당신이라면 아마 금방 배우실 수 있을 겁니다.', `MaleText_loc4`='嗯，我声明！他是个新学生！只要你再多掌握一点技能，我会很乐意将我所知道的一切都教给你的。去跟格雷塔谈谈，好吗？她会教你如何速成技能的。', `MaleText_loc5`='嗯，我聲明!他是個新學生!只要你再多掌握一點技能，我會很樂意將我所知道的一切都教給你的。去跟格雷塔談談，好嗎?她會教你如何速成技能的。', `MaleText_loc7`='¡Por mis ancestros! ¡Es un nuevo estudiante! Te enseñaré encantado todo lo que sé cuando tu habilidad sea algo mejor. Vete a hablar con Gretta Bueneje, ¿vale? Está justo allí. Te pondrá en marcha en un abrir y cerrar de ojos.' WHERE `ID`=8002;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 따라 배우시는군요. 얼마 안 가 가죽 상점을 직접 차려도 되겠어요. 기꺼이 도와 드려야죠. 너무 바빠서 문제지만... 할 일이 너무 많아요!', `MaleText_loc4`='你的技术在进步,很快你就会拥有一家你自己的皮革商店。我很高兴能帮你，$n。我的速度就只能这么快了，你知道吗？有那么多工作要做！', `MaleText_loc5`='你的技術在進步,很快你就會擁有一家你自己的皮革商店。我很高興能幫你，$n。我的速度就只能這麼快了，你知道嗎?有那麼多工作要做!', `MaleText_loc7`='Tu habilidad está mejorando mucho. Pronto, podrás abrir tu propia tienda de cuero. Me vendrá bien la ayuda, $n. Mis manos son rápidas, ¡pero con un límite! ¡Hay demasiado trabajo que hacer!' WHERE `ID`=8003;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 이 푸른 가죽은 정말 매력적이군. 알다시피 이 근방에는 호드의 신병이 되고 싶어서 지혜보다 열정만을 앞세워 사냥을 하는 이들이 아주 많네. 그러니 누구나 조심해야 하지.', `MaleText_loc4`='我知道，这块蓝色的皮革吸引了你的目光。你看，许多热情高涨的新兵都在这附近狩猎，像失去理智般砍杀动物。你必须提高警惕。', `MaleText_loc5`='我知道，這塊藍色的皮革吸引了你的目光。你看，許多熱情高漲的新兵都在這附近狩獵，像失去理智般砍殺動物。你必須提高警惕。', `MaleText_loc7`='Este cuero azul atrae miradas, lo sé. Verás, tenemos a muchos reclutas ansiosos por aquí, cazando y matando con más entusiasmo que sabiduría. Hay que tomar precauciones.' WHERE `ID`=8004;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 이상 가르칠 게 없네. 자네의 기술이 이미 나를 능가했기 때문이야. 썬더 블러프 중앙에서 북서쪽에 있는 상점으로 우나라는 타우렌을 찾아가게. 고급 기술을 가르쳐줄 테니까.', `MaleText_loc4`='我不能再教你啦：你所掌握的技能已经超过我了。去雷霆崖中央平原西北部的商店找牛头人犹纳吧。她会为你提供更多训练的。', `MaleText_loc5`='我不能再教你啦:你所掌握的技能已經超過我了。去雷霆崖中央平原西北部的商店找牛頭人猶納吧。她會為你提供更多訓練的。', `MaleText_loc7`='No puedo ayudarte con más lecciones. Tus habilidades me han sobrepasado. Vete a hablar con la tauren Una. La encontrarás en las tiendas del noroeste de la meseta central de Cima del Trueno. Puede ofrecerte una instrucción más avanzada.' WHERE `ID`=8005;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일의 압박이 너무도 무거워 내게는 중요한 임무를 수행할 시간이 없네. 자네 나 대신 임무를 수행해 주겠나?', `MaleText_loc4`='我有一项紧急的工作，但我自己没有时间处理。我可以把它交给你吗？', `MaleText_loc5`='我有一項緊急的工作，但我自己沒有時間處理。我可以把它交給你嗎?', `MaleText_loc7`='Tengo una tarea urgente que hacer, pero no tengo tiempo para hacerla. ¿Podrías encargarte tú?' WHERE `ID`=8006;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 수습생은 가르치지 않아. 이곳 불모의 땅에 있는 통곡의 동굴에서 왈도르라는 타우렌을 찾아가게. 자네를 도와줄 수 있을 걸세.', `MaleText_loc4`='我不会给一个学徒训练。去贫瘠之地的哀嚎洞穴找牛头人瓦多尔吧，他会帮助你的。', `MaleText_loc5`='我不會給一個學徒訓練。去貧瘠之地的哀嚎洞穴找牛頭人瓦多爾吧，他會幫助你的。', `MaleText_loc7`='No ofrezco instrucción a aprendices. Busca al tauren Waldor en las Cuevas de los Lamentos aquí, en Los Baldíos. Podrá ayudarte con lo que necesites.' WHERE `ID`=8007;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련을 받으러 왔나? 자네의 옷에 묻어 있는 그 먼지부터 털어내고 시작하도록 하지.', `MaleText_loc4`='你来这里是为了进一步的训练？抖去你身上的尘土吧，让我们马上开始工作。', `MaleText_loc5`='你來這裡是為了進一步的訓練?抖去你身上的塵土吧，讓我們馬上開始工作。', `MaleText_loc7`='¿Has venido en busca de instrucción? Quítate el polvo del camino de tu ropa y pongámonos manos a la obra.' WHERE `ID`=8008;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수많은 전투에서 나와 함께한 이 도끼를 항상 옆에 두고 싶소. 적군이 우리 수도로 쳐들어온 게 한두 번은 아니지만 두려워할 필요는 없지. 그들을 막지 못한 적은 한 번도 없었으니까.', `MaleText_loc4`='我的斧头经历过多场战事，我喜欢将它带在身边。敌人曾数次入侵我们的首都，但是别怕：我们总能击退他们。', `MaleText_loc5`='我的斧頭經歷過多場戰事，我喜歡將它帶在身邊。敵人曾數次入侵我們的首都，但是別怕:我們總能擊退他們。', `MaleText_loc7`='Mi hacha ha visto muchas batallas y me gusta tenerla a mano. Las tropas enemigas han conseguido llegar a nuestra capital varias veces, pero no temas, siempre hemos conseguido expulsarlas.' WHERE `ID`=8009;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더는 가르쳐 줄 게 없소. 당신의 가죽세공술은 이미 나와 대등하니까. 저쪽에 있는 우나에게 가도록 하시오. 필요하다면 당신의 실력은 내가 보증하도록 하겠소이다.', `MaleText_loc4`='我不能为你提供更多的训练啦：你的制革技能已经超过我啦。你应该去那儿找犹纳谈谈。如果需要的话我会为你担保的。', `MaleText_loc5`='我不能為你提供更多的訓練啦:你的製革技能已經超過我啦。你應該去那兒找猶納談談。如果需要的話我會為你擔保的。', `MaleText_loc7`='No puedo ayudarte con más instrucción. Tu talento con el cuero rivaliza con el mío. Deberías hablar con Una, está allí. Yo daré fe de tus habilidades si es necesario.' WHERE `ID`=8010;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나에게 배움을 구하러 왔다면 한 가지 부탁을 들어줘야겠소. 대신 그만한 가치는 충분히 있을 것이오. 내 장담하지...', `MaleText_loc4`='你来找我寻求建议，而我也要请你帮一个忙。确保它完成，你就会得到奖赏。', `MaleText_loc5`='你來找我尋求建議，而我也要請你幫一個忙。確保它完成，你就會得到獎賞。', `MaleText_loc7`='Has venido a mí en busca de instrucción y, a cambio, tengo un favor que pedirte. Hazlo y recibirás una recompensa.' WHERE `ID`=8011;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 가르치는 것을 배우기에 당신의 기술은 아직 설익었소. 대신 저쪽에 있는 마크를 찾아가보시오. 고급 기술을 배울 수 있을 때까지 당신을 도와줄 테니까.', `MaleText_loc4`='你的技艺不足以学会我所教授的。去找那边的玛克谈谈。他可以帮你直到你准备好学习更高级的课程。', `MaleText_loc5`='你的技藝不足以學會我所教授的。去找那邊的麥克談談。他可以幫你直到你準備好學習更高級的課程。', `MaleText_loc7`='Tus habilidades son insuficientes para aprender lo que yo enseño. Prueba a hablar con Mak. Podrá ayudarte hasta que estés $glisto:lista; para recibir lecciones avanzadas.' WHERE `ID`=8012;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 발전한 당신의 모습을 보니 기쁘기 그지없소. 대지모신께서 당신의 손에 영감을 불어넣어 주신 것이 틀림없군.', `MaleText_loc4`='我目前对你的进步感到很满意。很显然大地母亲已经赋予你的双手以灵感了。', `MaleText_loc5`='我目前對你的進步感到很滿意。很顯然大地之母已經賦予你的雙手以靈感了。', `MaleText_loc7`='Me complace tu progreso. Está claro que la Madre Tierra ha inspirado tus manos.' WHERE `ID`=8013;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='현재 우리가 이 땅에 설 자리는 별로 없지만 언제나 인간들이 이기란 법은 없지 않소. 그때가 되면 우리를 노예로 만든 대가를 치르게 될 거요. 그들의 기만에 대한 대가로 거짓말만을 내뱉는 그 혀를 잘라버리고 말겠소.', `MaleText_loc4`='眼下，我们在这片大陆上只有一处立足之地，但是人类是永远不可能打败我们的。他们很快就会受到报复。我们会割下他们说谎的舌头，惩戒他们的背叛行为。', `MaleText_loc5`='現在，我們在這片大陸上只有一處立足之地，但是人類是永遠不可能打敗我們的。他們很快就會受到報復。我們會割下他們說謊的舌頭，懲戒他們的背叛行為。', `MaleText_loc7`='De momento, solo hemos conseguido introducirnos en este continente, pero los humanos no pueden luchar con nosotros eternamente. Y después, nos pagarán por habernos esclavizado. Cortaremos sus mentirosas lenguas traidoras.' WHERE `ID`=8014;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 할 수만 있다면 가르쳐 주겠지만 너무 벅차군. 그러지 말고 썬더 블러프 중앙에서 북서쪽 상점에 있는 우나라는 타우렌을 찾아가 보시오. 정말 유능한 타우렌이지.', `MaleText_loc4`='要是我能的话，我会教你的，但我力所不及。去跟雷霆崖中央高地西北部的商店找牛头人犹纳谈谈。她拥有真正的才能。', `MaleText_loc5`='要是我能的話，我會教你的，但我力所不及。去跟雷霆崖中央高地西北部的商店找牛頭人猶納談談。她擁有真正的才能。', `MaleText_loc7`='Te instruiría si pudiera, pero tu habilidad es muy superior a la mía. Te diré algo: vete a hablar con la tauren Una. La encontrarás en las tiendas del noroeste de la meseta central de Cima del Trueno. Tiene un gran talento.' WHERE `ID`=8015;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일감은 항상 충분하니까 이곳 오크 녀석들에게 맡기면 좋겠지만 대부분은 나만이 할 수 있는 일이오. 하지만 당신이라면 믿고 맡길만한 일이 있는데...', `MaleText_loc4`='兽人军队要做的事情还很多，而大部分的事情只有我才能做。但是，我还是能帮一下忙的。', `MaleText_loc5`='獸人軍隊要做的事情還很多，而大部分的事情只有我才能做。但是，我還是能幫一下忙的。', `MaleText_loc7`='Aquí hay suficiente trabajo para un ejército de orcos y yo soy el único que puede hacer la mayor parte de ese trabajo. De todas formas, hay algo para lo que me vendría bien una mano.' WHERE `ID`=8016;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제대로 된 교육도 받지 않고 나에게 왔단 말이오? 머리보단 행동이 앞서는군. 당신 수준에 맞는 자나 찾아가 보십시오. 오그리마 골목길에 있는 카마리 같은 오크 말입니다.', `MaleText_loc4`='你没经过适当的训练就来找我，说明你勇气有余而智慧不足。去找个接近你的技术水平的人谈话，像兽人卡玛瑞，他住在奥格瑞玛的暗巷区。', `MaleText_loc5`='你沒經過適當的訓練就來找我，說明你勇氣有餘而智慧不足。去找個接近你的技術水準的人談話，像獸人卡瑪瑞，他住在奧格瑪的暗巷區。', `MaleText_loc7`='Tienes más agallas que cerebro... ¡Venir a verme sin tener la instrucción adecuada! Vete a hablar con alguien más cercano a tu nivel de habilidad, como el orco Kamari. Vive en La Calle Mayor de Orgrimmar.' WHERE `ID`=8017;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳은 문명과는 거리가 멀어서 호드에서 보급품을 보내 주기 전까지는 할 일이 별로 없는 편이라네. 그나저나 가죽 다루는 것을 상당히 좋아하나 보군.', `MaleText_loc4`='至少在部落派出更多的援军之前，这儿还不能被称为文明社会。你一定很喜欢制作皮革。', `MaleText_loc5`='至少在部落派出更多的援軍之前，這兒還不能被稱為文明社會。你一定很喜歡製作皮革。', `MaleText_loc7`='Estamos lejos de cualquier lugar al que yo tacharía de civilizado, al menos hasta que la Horda pueda enviarnos más refuerzos. Debe de gustarte mucho trabajar con cuero.' WHERE `ID`=8018;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바쁘냐고? 무슨 질문이 그래? 내가 하루종일 발가락이나 꼼지락거리면서 빈둥거리는 줄 알아? 뭘 사러 온 거라면 한도르에게나 가보게.', `MaleText_loc4`='我忙吗？这话什么意思？你觉得我只是成天站在这儿玩弄手指吗？如果你想买些什么的话，跟罕杜尔谈谈。', `MaleText_loc5`='我忙嗎?這話什麼意思?你覺得我只是成天站在這兒玩弄手指嗎?如果你想買些什麼的話，跟罕杜爾談談。', `MaleText_loc7`='¿Que si estoy ocupado? ¿Qué se supone que quiere decir eso? ¿Crees que me dedico a estar aquí todo el día jugueteando con mis pulgares? Si has venido a comprar algo, vete a hablar con Handor.' WHERE `ID`=8019;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게 배울 건 별로 없을 걸? 이미 많은 걸 알고 있잖아. 더 많이 배우고 싶다면 썬더 블러프 중앙에서 북서쪽 상점에 있는 우나라는 타우렌을 찾아가 봐. 가는 김에 내 안부도 좀 전해주고. 알았지?', `MaleText_loc4`='你在我这里学不到新的东西了；你知道的已经很多了。如果你想得到更多培训的话，去找雷霆崖中央高原西北方商店里的牛头人尤纳谈谈。替我向她致意，怎么样？', `MaleText_loc5`='你在我這裡學不到新的東西了;你知道的已經很多了。如果你想得到更多培訓的話，去找雷霆崖中央高原西北方商店裡的牛頭人猶納談談。替我向她致意，怎麼樣?', `MaleText_loc7`='No aprenderás nada más de mí; ya sabes demasiado. Si quieres más instrucción vete a hablar con la tauren Una. La encontrarás en las tiendas del noroeste de la meseta central de Cima del Trueno. Dale recuerdos de mi parte, ¿eh?' WHERE `ID`=8020;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꽤 솜씨가 좋군. 인정하네. 하지만 한가지 부탁만 들어주면 내게 더 잘 보일 수도 있을 텐데.', `MaleText_loc4`='我承认，那是份体面的工作。如果你能帮我处理一些事务的话，你会给我留下更深的印象的。', `MaleText_loc5`='我承認，那是份體面的工作。如果你能幫我處理一些事務的話，你會給我留下更深的印象的。', `MaleText_loc7`='Admito que es un trabajo decente. Pero estaría más impresionado si pudieras hacer algo por mí.' WHERE `ID`=8021;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기초도 모르면서 내 기술을 배울 수는 없네. 카마리를 찾아가 더 배우고 오게.', `MaleText_loc4`='你在学习好基础知识之前不能学我的技艺。如果你对训练感兴趣的话就去找卡玛瑞谈谈。', `MaleText_loc5`='你在學習好基礎知識之前不能學我的技藝。如果你對訓練感興趣的話就去找卡瑪瑞談談。', `MaleText_loc7`='No puedes estudiar mis técnicas hasta que no hayas aprendido los conceptos básicos. Vete a hablar con Kamari si te interesa recibir instrucción.' WHERE `ID`=8022;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오그리마의 길이 구불구불 굴곡이 많은 것은 침입자의 이동을 방해하기 위함이지. 조그만 노움들이 그 짧은 다리로 여기서 길을 잃고 헤매는 걸 상상해 봤나? 하하! 운만 좋으면 하나 잡아서 애완동물로 키우면 딱 좋겠는데 말이야.', `MaleText_loc4`='奥格瑞玛地形迂回曲折，能有效地阻止入侵者。你能想象这些矮小的侏儒在多么短的时间内就迷失方向吗？哈哈！如果足够幸运的话，我会追踪到他们，将他们变成我的宠物。', `MaleText_loc5`='奧格瑪地形迂回曲折，能有效地阻止入侵者。你能想像這些矮小的地精在多麼短的時間內就迷失方向嗎?哈哈!如果夠幸運的話，我會追蹤到他們，將他們變成我的寵物。', `MaleText_loc7`='Los giros y recovecos de Orgrimmar están diseñados para frustrar a los invasores. ¿Puedes imaginarte lo rápido que uno de esos raquíticos gnomos se perdería aquí? ¡Ja! Si sirviera como amuleto de suerte, le daría caza y me lo quedaría como mascota.' WHERE `ID`=8023;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 죽기 전에는 사서를 했었지. 전쟁이나 역병과는 아무 상관이 없는 일이었다고. 이렇게 되고 싶은 적은 단 한 번도 없었네... 이제 정신을 되찾았으니 한번 제대로 싸워보지도 않고 항복하는 일은 절대로 없을 거야.', `MaleText_loc4`='我生前是一名图书管理员，与战争和灾难无缘。我从未想过要变成现在这样。另一方面，现在我能主宰自己，我是不会不战而降的。', `MaleText_loc5`='我生前是一名圖書管理員，與戰爭和災難無緣。我從未想過要變成現在這樣。另一方面，現在我能主宰自己，我是不會不戰而降的。', `MaleText_loc7`='Antes de mi muerte, fui un bibliotecario; nada que ver con guerras y pestes. Nunca pedí convertirme en esto. Por otra parte, ahora que mi mente me pertenece de nuevo, no pienso rendirme sin pelear.' WHERE `ID`=8024;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 이제 나를 능가하다니 정말 기쁘군. 이제 길을 떠나야 해. 음, 썬더 블러프 중앙에서 북서쪽 상점에 있는 우나라는 타우렌을 찾아가보게. 내가 보장하건대 그녀는 아주 실력 있는 스승일세.', `MaleText_loc4`='你的能力已经超过我了。走吧。嗯，去雷霆崖中央高地西北部的商店找牛头人犹纳。她拥有强大的力量。', `MaleText_loc5`='你的能力已經超過我了。走吧。嗯，去雷霆崖中央高地西北部的商店找牛頭人猶納。她擁有強大的力量。', `MaleText_loc7`='Me complace poder decirte que tu talento ha sobrepasado al mío. Y ahora, vete. Eeeh, prueba con la tauren Una. La encontrarás en las tiendas del noroeste de la meseta central de Cima del Trueno. Te puedo asegurar que es muy buena en su trabajo.' WHERE `ID`=8025;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 알았어. 가르쳐 주겠네. 그렇게 목소리를 높일 필요는 없지 않나?!', `MaleText_loc4`='好的，好的，我会训练你。你没有必要大声嚷。', `MaleText_loc5`='好的，好的，我會訓練你。你沒有必要大聲嚷。', `MaleText_loc7`='Sí, sí. Te enseñaré. No hay necesidad de levantar la voz.' WHERE `ID`=8026;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='초보자까지 전부 받아들이면 너무 시끌벅적해질 거야. 저쪽에 있는 단 골다스에게 가보게. 좀 감정적이기는 하지만 다 좋은 뜻으로 그러는 걸세. 게다가 아주 잘 가르친다네.', `MaleText_loc4`='要是我教新手的话，那会有无数的学生来拜访我，那还不得乱成一团了。去跟那儿的丹·戈萨斯谈谈。他有些过于热情了，但意图总是好的，而且他是个相当好的老师。', `MaleText_loc5`='要是我教新手的話，那會有無數的學生來拜訪我，那還不得亂成一團了。去跟那兒的丹·戈薩斯談談。他有些過於熱情了，但意圖總是好的，而且他是個相當好的老師。', `MaleText_loc7`='Si enseñara a novatos, tendría muchos estudiantes visitándome y todo se volvería muy ruidoso. Ve a hablar con Dan Golthas, está allí. Es bastante duro, pero tiene buena intención y es un buen profesor.' WHERE `ID`=8027;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='처음 상점을 연 게 마법 지구였는데 그쪽은 좀 시끄럽더군. 그래서 자리를 옮겼는데도 끈질기게 나를 쫓아다니며 제자로 받아달라는 이들의 발걸음은 끊이질 않았어. 어쩔 수 없이 그들을 막아야 했지. 이제는 아주 조용해진 편이라네.', `MaleText_loc4`='起先，我在魔法区开设商店，但是那儿太嘈杂啦。尽管我进行了重新部署，除了有些学生坚持要向我求学之外，环境还是得到了相当的改善。', `MaleText_loc5`='起先，我在魔法區開設商店，但是那兒太嘈雜啦。儘管我進行了重新部署，除了有些學生堅持要向我求學之外，環境還是得到了相當的改善。', `MaleText_loc7`='Primero abrí una tienda en el Barrio de la Magia, pero había demasiado ruido. Es una mejora definitiva, a pesar de algunos estudiantes insistentes que siguen persiguiéndome, aunque me haya cambiado de sitio.' WHERE `ID`=8028;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='엘룬께서는 나이트 엘프들에게 많은 재능을 부여하셨습니다. 그에 대한 보답으로 호드의 마력으로부터 숲이 오염되는 것을 막는 것이 저희의 의무입니다.', `FemaleText_loc4`='月神已经赐予暗夜精灵很多礼物。作为回报，我们有职责保卫这些森林免受部落带来的恶魔的污染。', `FemaleText_loc5`='伊露恩已經賜予夜精靈很多禮物。作為回報，我們有職責保衛這些森林免受部落帶來的惡魔的污染。', `FemaleText_loc7`='Elune ha concedido muchos dones a los elfos de la noche. A cambio, nuestra responsabilidad es proteger estos bosques de la contaminación demoníaca que la Horda deja a su paso.' WHERE `ID`=8029;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그대를 더 가르치는 것은 제 능력 밖입니다. 다르나서스 장인의 정원에 있는 텔로니스를 만나 보십시오. 그는 재능 있는 학생이라면 항상 가르치고 싶어한답니다.', `FemaleText_loc4`='继续培训你已经超越我的能力了。与达纳苏斯工匠区的泰龙尼斯谈谈。他总是很愿意帮助有才能的学生。', `FemaleText_loc5`='繼續培訓你已經超越我的能力了。與達納蘇斯工匠區的泰龍尼斯談談。他總是很願意幫助有才能的學生。', `FemaleText_loc7`='Tu instrucción está por encima de mis habilidades. Ve a ver a Telonis en el Bancal del Artesano de Darnassus. Siempre está encantado de ayudar a estudiantes con talento.' WHERE `ID`=8030;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 전 이곳을 떠날 수는 없지만 수행해야 할 임무가 있습니다. 제 대신 해주시겠습니까?', `FemaleText_loc4`='我不能离开这里的岗位，$n，但是有一项任务必须完成。我可以把它托付给你吗？', `FemaleText_loc5`='我不能離開這裡的崗位，$n，但是有一項任務必須完成。我可以把它託付給你嗎?', `FemaleText_loc7`='No puedo dejar mi puesto aquí, $n, pero hay algo que debo hacer. ¿Puedo confiar en que tú lo hagas?' WHERE `ID`=8031;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전 기초 기술을 습득한 이들만 가르치고 있습니다. 다르나서스 장인의 정원에 있는 다리안나라는 나이트 엘프를 만나 보십시오. 당신의 기술을 보완하는 데 그녀가 적격일 겁니다.', `FemaleText_loc4`='我只教那些掌握基本指示的学生。你必须在达纳苏斯工匠区找到暗夜精灵达丽亚娜。她的技能与你的是完美的互补。', `FemaleText_loc5`='我只教那些掌握基本指示的學生。你必須在達納蘇斯工匠區找到夜精靈達麗亞娜。她的技能與你的是完美的互補。', `FemaleText_loc7`='Solo enseño a estudiantes que ya dominan los conceptos básicos. Ve a buscar a la elfa de la noche Darianna en el Bancal del Artesano de Darnassus. Su habilidad será el complemento perfecto de la tuya.' WHERE `ID`=8032;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가죽을 자르기 전에 항상 치수를 두 번씩 확인하도록 하십시오. 재료를 낭비할 수는 없습니다.', `FemaleText_loc4`='在你开始切割皮革之前一定要仔细检查尺寸。我们可不能浪费材料。', `FemaleText_loc5`='在你開始切割皮革之前一定要仔細檢查尺寸。我們可不能浪費材料。', `FemaleText_loc7`='Comprueba siempre dos veces las medidas antes de comenzar a cortar el cuero. No podemos permitirnos desperdiciar materiales.' WHERE `ID`=8033;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타고 날아갈 것이 필요해요! 아주 중요한 물품을 전달해야 하거든요!', `MaleText_loc4`='杜加尔，我需要空运服务！我要运送重要物资！', `MaleText_loc5`='杜加爾，我需要空運服務!我要運送重要物資!', `MaleText_loc7`='¡Necesito un transporte, Dungar! ¡Tengo que entregar unos suministros muy importantes!', `FemaleText_loc1`='타고 날아갈 것이 필요해요! 아주 중요한 물품을 전달해야 하거든요!', `FemaleText_loc4`='杜加尔，我需要空运服务！我要运送重要物资！', `FemaleText_loc5`='杜加爾，我需要空運服務!我要運送重要物資!', `FemaleText_loc7`='¡Necesito un transporte, Dungar! ¡Tengo que entregar unos suministros muy importantes!' WHERE `ID`=8034;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혹시 민첩성의 바다 펜던트 반쪽이 어디 있는지 아십니까?', `MaleText_loc4`='你知道在哪儿能找到水兽敏捷坠饰吗？', `MaleText_loc5`='你知道在哪兒能找到水獸敏捷墜飾嗎?', `MaleText_loc7`='¿Sabes dónde puedo encontrar la mitad del Colgante de Agilidad acuática?', `FemaleText_loc1`='혹시 민첩성의 바다 펜던트 반쪽이 어디 있는지 아십니까?', `FemaleText_loc4`='你知道在哪儿能找到水兽敏捷坠饰吗？', `FemaleText_loc5`='你知道在哪兒能找到水獸敏捷墜飾嗎?', `FemaleText_loc7`='¿Sabes dónde puedo encontrar la mitad del Colgante de Agilidad acuática?' WHERE `ID`=8035;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='인내의 바다 펜던트 반쪽이 어디 있는지 혹시 아십니까?', `MaleText_loc4`='你知道在哪儿能找到水兽耐力坠饰吗？', `MaleText_loc5`='你知道在哪兒能找到水獸耐力墜飾嗎?', `MaleText_loc7`='¿Sabes dónde puedo encontrar la mitad del Colgante de Resistencia acuática?', `FemaleText_loc1`='인내의 바다 펜던트 반쪽이 어디 있는지 혹시 아십니까?', `FemaleText_loc4`='你知道在哪儿能找到水兽耐力坠饰吗？', `FemaleText_loc5`='你知道在哪兒能找到水獸耐力墜飾嗎?', `FemaleText_loc7`='¿Sabes dónde puedo encontrar la mitad del Colgante de Resistencia acuática?' WHERE `ID`=8036;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서부 몰락지대의 물속을 찾아봐야 하오. 여기서 정서쪽, 황금해안 채석장과 해안이 만나는 곳에서 북서쪽에 있소. 닻을 찾으시오. 그곳이 바로 배가 바다 깊숙이 가라앉은 곳이니까. 수압이 워낙 세서 아무리 수영을 잘하는 자라도 너무 멀리까지 수영하면 지쳐서 빠져 죽기 십상이오.$B$B$n, 주변을 잘 살피시오. 분명 도움이 될 만한 게 있을 테니까. 그 근처에는 거품 균열이 있는데 가까이 가면 깊은 물속에서도 숨을 쉴 수 있소.', `MaleText_loc4`='你必须去西部荒野的海洋搜寻，向正西方——金海岸矿洞与海岸交接处往西北方向。海岸边有一只锚，看来附近一定有艘沉船。水下的压力很大；如果游得太远的话，即使是最优秀的潜水者也可能死于疲劳。$B$B去找一处适宜的自然环境吧，$n——这附近有起泡的海底裂缝，能在深海潜水时提供氧气。', `MaleText_loc5`='你必須去西部荒野的海洋搜尋，朝正西方西─金海岸礦坑與海岸交接處往西北方向。海岸邊有一隻錨，看來附近一定有艘沉船。水下的壓力很大;如果游得太遠的話，即使是最優秀的潛水者也可能死於疲勞。$B$B去找一處適宜的自然環境吧，$n─這附近有起泡的海底裂縫，能在深海潛水時提供氧氣。', `MaleText_loc7`='Tienes que buscar en las aguas de los Páramos de Poniente, al oeste-noroeste de la orilla de la Mina de la Costa del Oro. Un ancla muestra dónde hay un barco hundido, en las profundidades. La presión debajo del agua es fortísima; bajar demasiado podría matar incluso al nadador más experimentado. $B$BBusca una formación natural que puede ayudarte, $n: cerca de aquí hay una fisura oxigenada que ofrece a los nadadores la oportunidad de respirar.' WHERE `ID`=8037;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은빛소나무 숲에서 북부 해안가의 가장자리를 따라가다 보면, 바닷가에 난파된 배 한 척이 있을 거요. 거기서 서쪽으로 가면 당신이 찾는 것이 있소. 하지만 거기 가려면 깊은 바닷속을 오래 헤엄을 쳐야 하기 때문에 피로에 지치게 될 거요. 펜던트는 바로 거기, 바닥의 금고 안에서 당신이 가져가길 얌전히 기다리고 있을 거요.$B$B그렇게 깊은 곳을 혼자 힘으로 헤엄쳐 들어간다는 것은 쉬운 일이 아니니 각오를 단단히 해야 할 거요. 다행히도 펜던트 반쪽을 찾아 들어가는 자들이 이용할 수 있는 거품 균열이 있을 테니, 잘 활용하길 바라오.', `MaleText_loc4`='在银松森林北流海岸边缘，海滩上搁着一艘废弃的船。船只以西有你要找的东西；游得太远的话，你会因疲劳无法游回海岸的。海床上有一只上了锁的箱子，等着你去取呢。$B$B要是没有人帮忙的话，潜到这样的深度会受到极大的压强，要小心；海床上有一道裂缝，能释放出气泡，有助于你寻找那半块坠饰。好好利用吧。', `MaleText_loc5`='在銀松森林的北潮海岸邊緣，海灘上擱著一艘廢棄的船。船隻以西有你要找的東西;遊得太遠的話，你會因疲勞無法遊回海岸的。海床上有一隻上了鎖的帶鎖箱，等著你去取呢。$B$B要是沒有人幫忙的話，潛到這樣的深度會承受極大的水壓，要小心;海床上有一道裂縫，能釋放出氣泡，有助於你尋找那半塊墜飾。好好利用吧。', `MaleText_loc7`='En el Bosque de Argénteos, junto a los bordes de la Cala Mareanorte, descansa un barco abandonado en la orilla. Al oeste de ese punto está lo que buscas. Si nadas demasiado, el océano te matará de cansancio. Yace en el fondo del océano en una caja fuerte, esperando tu llegada.$B$BSufrirás una enorme presión a la hora de sobrevivir a una inmersión a tal profundidad sin ayuda, así que, concéntrate; una fisura oxigenada proporciona la posibilidad de respirar a los nadadores que buscan la mitad de este colgante. Utilízala sabiamente.' WHERE `ID`=8038;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어둠해안 북부로 가면 악령숲이라고 하는 땅에서 흘러내려 오는 폭포수 강이 있어요. 폭포수 강이 안개 해안으로 들어가는 곳에서 북쪽으로 가면 수심이 아주 깊어지죠. 거기에는 모양이 발톱 같다 하여 돌발톱이라는 이름이 붙은 바위 지형이 있는데 당신이 찾는 게 거기 있답니다.$B$B조심하세요. 돌발톱 바위 근처에 모여 있는 트레샤돈은 자기 영토에 들어오는 자는 모조리 공격하거든요.', `FemaleText_loc4`='在黑海岸的北面流淌着壁泉河，发源于现今的费伍德森林。随着河流流到并汇入薄雾海，一直蜿蜒到海洋北部最深处。在那儿有你要的石头，由于这种石头的形状酷似爪状，因此被称为石爪。$B$B要当心——蛇颈龙聚集在石爪那里，他们会攻击那些贸然入侵的人。', `FemaleText_loc5`='在黑海岸的北面流淌著壁泉河，發源於現今的費伍德森林。隨著河流流出並匯入薄霧海，一直蜿蜒到海洋北部最深處。一處被人們稱為石爪的地方有你要找的東西。$B$B要當心─蛇頸龍聚集在石爪那裡，會攻擊侵入他們領地的人。', `FemaleText_loc7`='El Río Fonroca pasa por la parte norte de la Costa Oscura, fluyendo desde las tierras ahora conocidas como Frondavil. Cuando el cauce del río merme y desemboque en el Cabo de la Niebla, dirígete al norte, hacia donde comienzan las partes más profundas del océano. Encontrarás una formación de rocas que algunos llaman la Garra de Piedra debido a su forma. Ahí es donde encontrarás lo que buscas.$B$BTen cuidado, hay trilladores cerca de la Garra de Piedra que atacarán a cualquiera que se adentre en su territorio.' WHERE `ID`=8039;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='불모의 땅 북동부로 가면 오염으로 병든 물웅덩이가 하나 있어요. 그곳에서는 그 웅덩이를 진흙 늪이라고 부르죠. 한때는 수정처럼 맑고 푸르렀던 물을 투자개발회사에서 산업 폐기물과 쓰레기 수렁으로 만들어버린 거예요. 그 진흙 늪 한가운데 당신이 찾는 물건이 있답니다, $n.$B$B조심하세요. 투자개발회사에서는 불법 침입자를 그냥 놔두지 않거든요. 자기네 회사에서 일하지 않는 자는 모두 불법 침입자로 취급해요. 녀석들은 자연에 대한 반감이 아주 강하기 때문에, 당신을 자연의 수호자로 보고 공격할 거예요.', `FemaleText_loc4`='在贫瘠之地的东北部，有一处受到严重污染的水池。当地人称它为淤泥沼泽；风险投资公司将水晶般幽蓝的水域变成工业副产品和废弃品的泥潭。在沼泽的中心有你要找的东西，$n。$B$B要小心，风险投资公司绝不容许有人入侵，他们将不为其工作的人都当作入侵者。你作为自然的保护者，更是他们极力对抗的目标。', `FemaleText_loc5`='在貧瘠之地的東北部，有一處受到嚴重污染的水池。當地人稱它為淤泥沼澤;風險投資公司將水晶般幽藍的水域變成工業副產品和廢棄品的泥潭。在沼澤的中心有你要找的東西，$n。$B$B要小心，風險投資公司絕不容許有人入侵，他們將不為其工作的人都當作入侵者。你作為自然的保衛者，更是他們極力對抗的目標。', `FemaleText_loc7`='En el noreste de Los Baldíos hay un pozo de agua contaminada por la polución. Los vecinos del lugar lo llaman El Fangal; Ventura y Cía. ha convertido las aguas antaño cristalinas, en un lodazal de bioproductos y residuos industriales. En el centro de este lodazal está lo que buscas, $n.$B$BTen mucho cuidado, Ventura y Cía. no tolera a los intrusos y consideran un intruso a cualquiera que no trabaje para ellos. Serás su objetivo por proteger a la naturaleza, algo a lo que se oponen vehementemente.' WHERE `ID`=8040;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='풀밭은 부드럽고 폭신합니다. 공기는 상쾌하고 밝은 빛과 노랫소리로 가득 차 있습니다. 제가 보는 모든 것들이 텔드랏실은 꿈의 장소라는 것을 말해줍니다. 그런데 왜 제 마음은 이리도 불길한 예감으로 가득할까요?', `MaleText_loc4`='草地柔软青葱。空气清新，阳光明媚，歌声飘飘。泰达希尔的梦想终成现实。但是为什么我感到有种不详的预兆？', `MaleText_loc5`='草地柔軟青蔥。空氣清新，陽光明媚，歌聲飄飄。泰達希爾的夢想終成現實。但是為什麼我感到有種不詳的預兆?', `MaleText_loc7`='La hierba es suave y exuberante. El aire es fresco, lleno de luz y música. Todo lo que he visto sugiere que Teldrassil es un sueño hecho realidad. ¿Por qué, entonces, está mi corazón lleno de aprensión?' WHERE `ID`=8041;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대를 가르치기에 제 능력이 모자랍니다. 이제 동부 내륙지에 있는 맹금의 봉우리로 가서 드라크 스톤핸드라는 드워프를 만나 보십시오. 그의 작품은 제 것과는 비교조차 안 될 정도로 훌륭합니다.', `MaleText_loc4`='你的进步已经超越了我能教授的技艺了。现在到辛特兰的鹰巢山去找矮人德拉克·石拳谈话。他的作品太棒了，比我的好多了。', `MaleText_loc5`='你的進步已經超越了我能教授的技藝了。現在到辛特蘭的鷹巢山去找矮人德拉克·石拳談話。他的作品太棒了，比我的好多了。', `MaleText_loc7`='Has aventajado mucho mis habilidades como para poder enseñarte. Viaja hasta el Pico Nidal en las Tierras del Interior y habla con el enano Drakk Petramano. Su trabajo es magnífico, mucho mejor que el mío.' WHERE `ID`=8042;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대는 지금까지 기술을 배워 사용할 수 있다는 것을 몸소 증명해 보이셨습니다. 이제 저를 대신하여 임무를 수행할 결의가 있다는 것 또한 보여주시겠습니까?', `MaleText_loc4`='你已经证明了学习我们的工艺的技巧。但你有替我完成任务的决心吗？', `MaleText_loc5`='你已經證明了學習我們的工藝的技巧。但你有替我完成任務的決心嗎?', `MaleText_loc7`='Has demostrado gran talento al aprender nuestro oficio. ¿Posees también la capacidad de realizar una misión para mí?' WHERE `ID`=8043;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='송구스럽지만 가죽세공 기술을 좀 더 배우실 때까지는 그대를 도와드릴 수가 없습니다. 저 대신 이곳에 있는 팔드론이나 다리안나를 만나 보십시오. 필요한 수련을 받으실 수 있을 겁니다.', `MaleText_loc4`='$g尊敬的先生:女士;，在你掌握制皮的更多知识之前，我还不能帮助你，对此我感到很遗憾。跟法多恩或达丽亚娜谈谈。他们能教你所需的技能。', `MaleText_loc5`='$g尊敬的先生:女士;，在你掌握製皮的更多知識之前，我還不能幫助你，對此我感到很遺憾。跟法多恩或達麗亞娜談談。他們能教你所需的技能。', `MaleText_loc7`='Siento decirte que no puedo ayudarte, $gnoble señor:gentil dama;, hasta que no sepas mejor cómo trabajar con el cuero. Ve a hablar con Faldron o Darianna. Pueden enseñarte la habilidad que necesitas.' WHERE `ID`=8044;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가죽에 그대의 의지를 강요하려고 하지 마십시오. 대신 가죽의 자연적 성향을 판단해 어떤 형태로 만들어 어떤 기능을 하도록 할지 생각해 보십시오. 가죽을 세공하는 일은 전쟁이 아닙니다. 가죽을 이기려 들지 말고 가죽과 함께하십시오.', `MaleText_loc4`='别试图将你的意愿强加到皮革上。而是让其天然的特性显示出自身的形状和功能。这不是一场战役。与皮革协同工作，而不是与其作对。', `MaleText_loc5`='別試圖將你的意願強加到皮革上。而是讓其天然的特性顯示出自身的形狀和功能。這不是一場戰役。與皮革協同工作，而不是與其作對。', `MaleText_loc7`='No intentes forzar tu voluntad al cuero. Al contrario, permite que su tendencia natural dicte qué forma y función tendrá. Esto no se trata de una batalla que hay que ganar. Trabaja con el cuero, no contra él.' WHERE `ID`=8045;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='바늘은 작지만 실은 강하며 이 실로 맺은 바늘 땀은 촘촘한 것입니다. 스랄 님과 다른 이들과 맺은 조약은 유효하니 호드를 이 땅에서 몰아낼 수는 없을 것입니다.', `FemaleText_loc4`='针太细，线太粗，针脚倒还不错。我们与萨尔和其他人的合约将继续有效。部落不会被驱逐出这片土地的。', `FemaleText_loc5`='針太細，線太粗，針腳倒還不錯。我們與索爾和其他人的合約將繼續有效。部落不會被驅逐出這片土地的。', `FemaleText_loc7`='La aguja es pequeña, pero el hilo es fuerte y las puntadas están bien dadas. Se mantendrá nuestro pacto con Thrall y los otros. La Horda no será expulsada de estas tierras.' WHERE `ID`=8046;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 재능도 한계가 있다는 것을 당신이 일깨워 주는군요. 축하합니다. 이제 페랄라스에 있는 모자케 야영지로 가십시오. 그곳에는 기술이 아주 뛰어난 하라나 아이언하이드라는 타우렌이 살고 있습니다.', `FemaleText_loc4`='我的才能有限，你也已经达到了。恭喜你，$n。你的下一站应该是菲拉斯的莫沙彻营地。牛头人哈拉纳·铁皮住在那里；她的技术很有声望。', `FemaleText_loc5`='我的才能有限，你也已經達到了。恭喜你，$n。你的下一站應該是菲拉斯的莫沙徹營地。牛頭人哈拉納·鐵皮住在那裡;她的技術很有聲望。', `FemaleText_loc7`='Incluso mi talento tiene un límite, y tú ya lo has alcanzado. Enhorabuena, $n. Tu próxima parada debería ser el Campamento Mojache en Feralas. La tauren Hahrana Pielférrea vive allí; es famosa por su talento.' WHERE `ID`=8047;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='호드의 일원으로서 우리는 호드가 번창하도록 사회에 공헌해야 합니다. 이번 임무를 통해서 당신이 호드를 위해 공헌한다는 것을 증명해 보십시오.', `FemaleText_loc4`='作为部落的成员，我们必须为我们的社会做出贡献，以保证它的繁荣兴旺。因此，我相信你会很高兴能帮助我们完成一项小小的任务。', `FemaleText_loc5`='作為部落的成員，我們必須為我們的社會做出貢獻，以保證它的繁榮興旺。因此，我相信你會很高興能幫助我們完成一項小小的任務。', `FemaleText_loc7`='Como miembros de la Horda, debemos contribuir con nuestra comunidad para asegurarnos de que sigue prosperando. Por ello, estoy segura de que nos ayudarás encargándote de una pequeña tarea que tengo para ti.' WHERE `ID`=8048;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내가 초보자였던 것이 까마득한 옛날이기에 당신을 제대로 가르칠 수 없을 것 같습니다. 바로 저기에 있는 타른이나 마크에게 가면 둘 중 하나는 당신에게 도움을 줄 겁니다.', `FemaleText_loc4`='我自己不久前也是一个新手，所以我觉得我不太适合教你。试着跟那边的塔恩或是玛克谈谈。他们之中应该有人能回答你的问题。', `FemaleText_loc5`='我自己不久前也是一個新手，所以我覺得我不太適合教你。試著跟那邊的塔恩或是麥克談談。他們之中應該有人能回答你的問題。', `FemaleText_loc7`='Ha pasado tanto tiempo desde que yo fui aprendiz, que no creo ser la mejor profesora para ti. Prueba con Tarn o Mak, están justo allí. Seguro que uno de ellos puede responder a tus preguntas.' WHERE `ID`=8049;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='케른께서는 우리를 무한한 가능성의 땅으로 데려오셨습니다. 우리는 대단한 자산을 받았기에 그에 대한 보답으로 우리의 자산을 다른 이에게도 나누어 주어야 합니다. 그것이 바로 내가 학생들을 가르치기 시작한 이유입니다.', `FemaleText_loc4`='凯恩把我们带到了一片充满希望的大地。我们很幸运，因此我们再把好运带给别人。这就是我为什么开始教学的原因，$n。', `FemaleText_loc5`='凱恩把我們帶到了一片充滿希望的大地。我們很幸運，因此我們再把好運帶給別人。這就是我為什麼開始教學的原因，$n。', `FemaleText_loc7`='Cairne nos ha traído a una tierra fértil con posibilidades de futuro. Somos afortunados y, a cambio, debemos pasar nuestra buena fortuna a otros. Esa es la razón de que comenzase a enseñar, $n.' WHERE `ID`=8050;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에서 찾을 수 있는 재료로 놀라운 것들을 만들어낼 수 있지. 무라딘 님의 수염을 걸고 말하는데 이 언덕에는 환상적인 생물이 많아. 한 번 가서 잡아 보라고. 돌아와서는 멋진 얘기도 좀 해주고 말이야.', `MaleText_loc4`='我可以利用在这儿找到的材料制作有趣的东西。这些山林中有许多奇怪的生物！去杀死它们，$n。', `MaleText_loc5`='我可以利用在這兒找到的材料製作有趣的東西。這些山林中有許多奇怪的生物!去殺死它們，$n。', `MaleText_loc7`='Puedo crear objetos increíbles con los materiales que encuentro aquí. ¡Por las barbas de Muradin! ¡Estas colinas están pobladas de fantásticas criaturas! Ve a dar mamporrazos por ahí, $n, y tráeme buenas colas.' WHERE `ID`=8051;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 내 집념을 비로소 깨닫게 된 날은 정말 슬펐지. 아침에 일어났는데 맥주를 한 잔 하기도 전에 벌써 내가 가죽을 만지고 있더라니까... 숙취도 없이 말이야! 그때 알았지... 그래, 그때 알았어! 앞으로 어떻게 될지 알아버렸단 말이야.', `MaleText_loc4`='哦，我认识到自己的困惑，这真是个悲伤的日子。当我醒来时，发现自己被晒黑了，接着我生平第一次喝啤酒。那根本不算一场宿醉！从那时起——我便明白了啤酒！——明白了喝下啤酒是怎么样的状况。', `MaleText_loc5`='哦，我認識到自己的困惑，這真是個悲傷的日子。當我醒來時，發現自己被曬黑了，接著我生平第一次喝麥芽酒。那根本不算一場宿醉!從那時起─我便明白了!─明白了喝下麥芽酒是怎麼樣的狀況。', `MaleText_loc7`='¡Buff! Un día triste cuando me di cuenta de mi obsesión. Me desperté y curtido me encontré, antes de beber mi primera jarra de cerveza. ¡Ni siquiera una resaca respetable! Y entonces lo supe... sí. ¡Ay! ¡Supe cómo iba a ser a partir de entonces!' WHERE `ID`=8052;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 도전이 좋아. 자넨 안 그런가? 그래, 당연히 그래야지. 그러면 내가 시키는 일도 당연히 해주겠지?', `MaleText_loc4`='我喜欢机会；你不喜欢吗？啊，当然你也喜欢。这就是你要按我说的去做的原因。', `MaleText_loc5`='我喜歡機會;你不喜歡嗎?啊，當然你也喜歡。這就是你要按我說的去做的原因。', `MaleText_loc7`='Me encanta un buen desafío, ¿y a ti? Sí, claro que a ti también. Y por eso estás a punto de hacer exactamente lo que digo.' WHERE `ID`=8053;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 요람에서 방금 기어 나온 친구를 가르칠 순 없어. 내 제자가 되려면 많은 기술을 익혀야 한다고. 사실 자넨 몰골도 말이 아니니 거기 서서 입 좀 다물어 준다면 고맙겠군그래.', `MaleText_loc4`='我不是来教那些刚离开摇篮的宝宝的。你离我对学生的要求还差远了。你不过是个年幼的$g小伙子:姑娘;，你最好别在这儿烦我了。', `MaleText_loc5`='我不是來教那些剛離開搖籃的寶寶的。你離我對學生的要求還差遠了。你不過是個年幼的$g小夥子:姑娘;，你最好別在這兒煩我了。', `MaleText_loc7`='No estoy aquí para enseñar a bebés que acaban de salir de la cuna. Ni siquiera te acercas a la habilidad que exijo a mis estudiantes. De hecho, me das pena $gmuchacho:muchacha;, y te agradecería que no te quedaras ahí lloriqueando.' WHERE `ID`=8054;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 작품을 사려면 직접 나를 찾아와야 합니다. 올윈은 종종 다시 생각해 보라고 하지만 아쉬운 건 내가 아닙니다. 주위를 둘러보십시오. 많은 전사들이 내 갑옷에 의지하고 있습니다.', `FemaleText_loc4`='我所有的作品都必须由买主亲自来订购。奥尔文常常要我改变这个习惯，但是我就是不改。看看你周围吧，无数战士还指望我给他们打造装甲呢。', `FemaleText_loc5`='我所有的作品都必須由買主親自來訂購。奧爾文常常要我改變這個習慣，但是我就是不改。看看你周圍吧，無數戰士還指望我給他們打造裝甲呢。', `FemaleText_loc7`='Los compradores tienen que hacerme los pedidos personalmente. Orwin me pide muchas veces que cambie de idea al respecto, pero mis prioridades están aquí. Mira a tu alrededor, muchos de esos luchadores confían en mí para su armadura.' WHERE `ID`=8055;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신 같은 제자만 있다면 좋겠군요. 용기 있게 적진 깊은 곳으로 들어갈 자는 많지 않답니다. 당신의 용기에 경의를 표합니다.', `FemaleText_loc4`='我真希望有更多像你一样的学生。很少有人会冒险深入敌境。我佩服你的勇气。', `FemaleText_loc5`='我真希望有更多像你一樣的學生。很少有人會冒險深入敵境。我佩服你的勇氣。', `FemaleText_loc7`='Ojalá tuviera más estudiantes como tú. No hay muchos que se aventuren tan adentro en territorio enemigo. Aplaudo tu coraje.' WHERE `ID`=8056;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 전쟁에서는 한 조각의 가죽도 허비하지 말아야 합니다. 난 밤낮으로 새 갑옷을 만들어 내지만 헌 갑옷도 최대한 수선해서 다시 입을 수 있게 합니다. 난 다른 임무를 할 시간이 없습니다. 그래서 말인데 내 부탁 하나 들어주시겠습니까?', `FemaleText_loc4`='我不会在这场战争中让步。我不分昼夜的制造新装甲，还把旧的装甲修补好。我没时间做其他任务。你愿帮我分担一些吗？', `FemaleText_loc5`='我不會在這場戰爭中讓步。我不分晝夜的製造新裝甲，還把舊的裝甲修補好。我沒時間做其他任務。你願幫我分擔一些嗎?', `FemaleText_loc7`='No podemos permitirnos ceder ni un centímetro en esta guerra. Día y noche fabrico nuevas armaduras y arreglo lo que puede salvarse de las viejas. No tengo tiempo para nada más. ¿Podrías hacer algo por mí?' WHERE `ID`=8057;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나를 찾아오느라 당신 시간뿐 아니라 내 시간까지 허비했군요. 난 기본 기술까지 가르칠 시간이 없습니다. 이곳에서는 전투가 벌어지고 있으며 여기는 최전선이란 말입니다. 좀 더 준비가 될 때까지 돌아오지 마십시오.', `FemaleText_loc4`='你来找我求学是浪费了你我的时间，$n。我没时间教授基础技能。我们在这里战斗，而这里是一处前线。在你准备充分之前不要再来找我。', `FemaleText_loc5`='你來找我求學是浪費了你我的時間，$n。我沒時間教授基礎技能。我們在這裡戰鬥，而這裡是一處前線。在你準備充分之前不要再來找我。', `FemaleText_loc7`='Has perdido tu tiempo y el mío viniendo hasta aquí en busca de instrucción, $n. No tengo tiempo para enseñar las habilidades básicas. Aquí estamos luchando una guerra, y estamos en primera línea. No vuelvas a verme hasta que no te hayas preparado más a conciencia.' WHERE `ID`=8058;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 행색을 보아하니 하루빨리 옷 좀 구하셔야겠습니다.', `MaleText_loc4`='我觉得你的服饰急需维修。', `MaleText_loc5`='我覺得你的服飾急需維修。', `MaleText_loc7`='Puedo ver que tu armario necesita urgentemente un repaso.' WHERE `ID`=8059;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 그저 재봉술을 조금 아는 평범한 사람에 불과합니다. 당신은 제가 지닌 기술보다 더 많은 것을 배워야 합니다. 스톰윈드 마법사 지구에서 상당히 솜씨 좋은 나이트 엘프 재봉사가 산다고 들었습니다.', `MaleText_loc4`='我对裁缝业知之甚少，但你需要更多的帮助。我听说有个暗夜精灵精通裁缝技术。他居住在暴风城的魔法区。', `MaleText_loc5`='我對裁縫業知之甚少，但你需要更多的幫助。我聽說有個夜精靈精通裁縫技術。他居住在暴風城的魔法區。', `MaleText_loc7`='Soy un hombre sencillo con algo de conocimiento sobre sastrería, pero necesitas más ayuda de la que yo puedo proporcionarte. He oído hablar de un elfo de la noche que es un sastre consumado. Vive en Ventormenta, en el Barrio de los Magos.' WHERE `ID`=8060;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제게서 몇 가지 배우고 싶다는 말입니까? 기꺼이 가르쳐드리겠습니다!', `MaleText_loc4`='你想学点东西吗？我会很乐意教你的！', `MaleText_loc5`='你想學點東西嗎?我會很樂意教你的!', `MaleText_loc7`='¿Y bien? ¿Te gustaría aprender unas cuántas cosas? ¡Estaré encantado de ayudarte a empezar!' WHERE `ID`=8061;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='인생이란 정성 들여 짠 양탄자와 같습니다.', `MaleText_loc4`='生活就像一幅小心编织的锦缎。', `MaleText_loc5`='生活就像一幅小心編織的錦緞。', `MaleText_loc7`='La vida es como un tapiz delicadamente tejido.' WHERE `ID`=8062;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠... 당신이 이제부터 배워야 할 것은 제 한계를 넘는 것들입니다. 이제 여기서 나가 골목을 오른쪽으로 틀면 있는 라슨의 옷가게로 가십시오. 거기서 일하는 셀란두스와 의논하셔야 합니다. 사실은 제 모든 기술도 그 나이트 엘프에게 전수 받은 것이랍니다!', `MaleText_loc4`='嗯……你需要学的东西有点超出我的能耐了。去找那边的塞拉多斯谈谈。我会的东西全是他教的！', `MaleText_loc5`='嗯...你需要學的東西有點超出我的能耐了。去找那邊的塞拉多斯談談。我會的東西全是他教的!', `MaleText_loc7`='Mmm... Las cosas que necesitas aprender me sobrepasan. Ve a hablar con Sellandus en la Sastrería Larson, en la parte de arriba del camino a la derecha. ¡Él me enseñó todo lo que sé!' WHERE `ID`=8063;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋습니다. 이제 재봉술의 여정을 시작해 봅시다.', `MaleText_loc4`='很好，开始学习裁缝吧。', `MaleText_loc5`='很好，開始學習裁縫吧。', `MaleText_loc7`='Muy bien, que comience tu viaje al mundo de la sastrería.' WHERE `ID`=8064;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바느질에는 안정된 손길도 필요하지만, 무엇보다 인내심이 필요합니다.', `MaleText_loc4`='缝纫需要娴熟的手法，以及……也是最重要的，耐性。', `MaleText_loc5`='縫紉需要嫺熟的手法，以及...也是最重要的，耐性。', `MaleText_loc7`='Las labores de aguja requieren un pulso firme. Y paciencia... por encima de todo, paciencia.' WHERE `ID`=8065;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 그대는 다르나서스로 가서 메린과 얘기해야 합니다. 이제부터는 그녀가 그대를 가르쳐줄 것입니다.', `MaleText_loc4`='现在是你去达纳苏斯跟迈里恩谈谈的时候了。她将对你进行指导。', `MaleText_loc5`='現在是你去達納蘇斯跟玫琳恩談談的時候了。她將對你進行指導。', `MaleText_loc7`='Es hora de que vayas a Darnassus y hables con Me''lynn. Ella te guiará a partir de ahora.' WHERE `ID`=8066;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기꺼이 그대를 제자로 받아들이겠습니다. 자, 시작해볼까요?!', `MaleText_loc4`='很高兴能将你收入麾下。让我们开始吧。', `MaleText_loc5`='很高興能將你收入麾下。讓我們開始吧。', `MaleText_loc7`='Me encantará hacerme cargo de ti. Comencemos.' WHERE `ID`=8067;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오십시오. 무얼 도와드릴까요?', `MaleText_loc4`='欢迎来到我的商店。我能为你做什么？', `MaleText_loc5`='歡迎來到我的商店。我能為你做什麼?', `MaleText_loc7`='Encantado de tenerte en mi tienda. ¿Qué puedo hacer por ti?' WHERE `ID`=8068;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠시만요... 전 수습 재봉사에 불과합니다. 멋진 걸 만들고 싶다면 저기 스톤브라우와 얘기를 나눠 보십시오.', `MaleText_loc4`='等一下，我只是一个助手。如果你想学那些花哨的东西，找那边的老约莫德·石眉谈谈。', `MaleText_loc5`='等一下，我只是一個助手。如果你想學那些花哨的東西，找那邊的老約莫德·石眉談談。', `MaleText_loc7`='Espera, solo soy un ayudante. Si quieres empezar a aprender las cosas elegantes, habla con Petrocejas, está ahí.' WHERE `ID`=8069;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 됐군요! 그렇지 않아도 새로운 제자를 기다리고 있었는데. 자, 그럼 당장 시작하도록 합시다!', `MaleText_loc4`='很好！我一直希望收个新学生。那么就让我们立刻开始吧！', `MaleText_loc5`='很好!我一直希望收個新學生。那麼就讓我們立刻開始吧!', `MaleText_loc7`='¡Fantástico! Estaba esperando que llegase un nuevo estudiante. ¡Bueno, pues comencemos ahora mismo!' WHERE `ID`=8070;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 여러 가지 동물에서 벗겨낸 가죽과 껍질로 제품을 만들고 있소.', `MaleText_loc4`='我们使用动物皮毛制作物品。', `MaleText_loc5`='我們使用動物皮毛製作物品。', `MaleText_loc7`='En nuestras creaciones utilizamos muchas pieles y pelambres de animales.' WHERE `ID`=8071;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 아는 게 좀 있긴 하지만 전문가는 아니오. 다행히도 마가르는 전문가지. 상점 뒤편에 있으니 가서 도와줄 수 있는지 한번 물어보시오. 성질이 불같으니 화나지 않게 조심해야 할 거요.', `MaleText_loc4`='我知道一些，但我不是专家。祝你好远，玛加尔也是。他就站在商店后面。看看他是否能帮助你，但是小心别惹恼他。他脾气有些暴躁。', `MaleText_loc5`='我知道一些，但我不是專家。祝你好遠，瑪加爾也是。他就站在商店後面。看看他是否能幫助你，但是小心別惹惱他。他脾氣有些暴躁。', `MaleText_loc7`='Sé un par de cosas, pero no soy un experto. Por suerte para ti, Magar sí que lo es. Está cerca de la parte trasera de la tienda. Vete a ver si puede ayudarte, pero ten cuidado y no le irrites. Puede llegar a ser muy quisquilloso.' WHERE `ID`=8072;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 아는 데까지 최선을 다해 가르쳐주겠소.', `MaleText_loc4`='我会将我所知道的传授给你的。', `MaleText_loc5`='我會將我所知道的傳授給你的。', `MaleText_loc7`='Te enseñaré lo que pueda.' WHERE `ID`=8073;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 사냥하는 동물의 어떤 부분도 낭비해서는 안 되오.', `MaleText_loc4`='我们没有浪费狩猎而得的动物的任何一部分。', `MaleText_loc5`='我們沒有浪費狩獵而得的動物的任何一部分。', `MaleText_loc7`='No desperdiciamos ninguna parte de los animales que cazamos.' WHERE `ID`=8074;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 높은 지식을 구하고 있군. 테파가 그런 지식을 가지고 있소. 이 근처 어딘가에 서있을 텐데...', `MaleText_loc4`='你寻求更高级的知识。坦帕拥有这种知识。她应该就站在附近……', `MaleText_loc5`='你尋求更高級的知識。坦帕擁有這種知識。她應該就站在附近...', `MaleText_loc7`='Buscas un conocimiento superior. Tepa ha sido bendecida con un conocimiento así. Creo que está por aquí cerca...' WHERE `ID`=8075;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대지모신의 축복을 빌며 이제 수업을 시작하도록 합시다.', `MaleText_loc4`='带着大地母亲的祝福，我们要开始了。', `MaleText_loc5`='帶著大地之母的祝福，我們要開始了。', `MaleText_loc7`='Con la bendición de la Madre Tierra, comencemos.' WHERE `ID`=8076;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='만나서 반갑소. 내가 도와드릴 일이라도 있소?', `MaleText_loc4`='去结交朋友吧。我能帮你吗？', `MaleText_loc5`='去結交朋友吧。我能幫你嗎?', `MaleText_loc7`='Es un placer conocerte. ¿Puedo ayudarte?' WHERE `ID`=8077;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나도 재봉에 대해서 꽤 알긴 하지만 전문가는 아닐세. 자네가 얘기해야 할 사람은 바로 리안논이지! 멀리 있지 않으니 언더시티에서 그녀가 어디 있는지 물어보게나.', `MaleText_loc4`='我知识渊博，但我还不是专家。你知道你该去找谁谈话吗？雷安诺！她就在不远的地方。到幽暗城打听她的下落。', `MaleText_loc5`='我知識淵博，但我還不是專家。你知道你該去找誰談話嗎?雷安諾!她就在不遠的地方。到幽暗城打聽她的下落。', `MaleText_loc7`='Estoy bastante informado, pero no soy un experto. ¿Sabes con quién deberías hablar? ¡Rhiannon! No está lejos. Pregunta por ella en Entrañas.' WHERE `ID`=8078;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러니까... 재봉사가 되고 싶다는 것이오? 좋소. 당신이 그럴 만한 실력이 있는지 알아봅시다.', `MaleText_loc4`='这么说……你想当一名裁缝？很好，让我们看看你是否具有这样的潜质。', `MaleText_loc5`='這麼說...你想當一名裁縫?很好，讓我們看看你是否具有這樣的潛質。', `MaleText_loc7`='Así que... ¿Quieres ser un sastre? Muy bien, veamos si tienes lo que se necesita.' WHERE `ID`=8079;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에 방문객이 오는 일은 드문데. 뭐 관심 가는 거라도 있는 건가?', `MaleText_loc4`='到我们这儿来的客人可不多。你对我感兴趣？', `MaleText_loc5`='到我們這兒來的客人可不多。你對我感興趣?', `MaleText_loc7`='No solemos recibir muchos visitantes aquí. ¿Te interesa algo?' WHERE `ID`=8080;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실은 나도 수습생일 뿐이오. 리안논이 진짜 전문가인데, 저기 상자들 옆에 서 있소. 당신은 리안논에게 많은 것을 배울 수 있을 거요.', `MaleText_loc4`='我只是个学生。雷安诺才是专家。她站在那边的箱子旁。你可以从她那儿学到很多东西。', `MaleText_loc5`='我只是個學生。雷安諾才是專家。她站在那邊的木箱旁。你可以從她那兒學到很多東西。', `MaleText_loc7`='En realidad yo soy solo un estudiante. Rhiannon es la experta. Está ahí, al lado de las cajas. Podrás aprender mucho de ella.' WHERE `ID`=8081;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래. 소질은 있는 것 같군. 내가 몇 가지 가르쳐줘도 되겠군.', `MaleText_loc4`='是的，我认为你有潜力。或许我可以给你看看一两样东西？', `MaleText_loc5`='是的，我認為你有潛力。或許我可以給你看看一兩樣東西?', `MaleText_loc7`='Sí, creo que tienes potencial. Quizás pueda enseñarte un par de cosas.' WHERE `ID`=8082;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정신을 가다듬는 데는 실을 짜는 게 최고지요.', `FemaleText_loc4`='没有比编织更好的宁神方法了。', `FemaleText_loc5`='沒有比編織更好的寧神方法了。', `FemaleText_loc7`='No hay mejor forma de despejar la mente que tejer.' WHERE `ID`=8083;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 아직 계속 배우는 중인데 그대가 저보다 한 수 위군요. 더 배우고 싶거든 메린과 얘기해 보시면 그대를 가르쳐줄 겁니다.', `FemaleText_loc4`='你的教育正在继续，而你的知识已超越了我。如果你还想继续学习你就必须找迈里恩谈谈。她会指引你的。', `FemaleText_loc5`='你的教育正在繼續，而你的知識已超越了我。如果你還想繼續學習你就必須找玫琳恩談談。她會指引你的。', `FemaleText_loc7`='Yo todavía estoy aprendiendo y tu conocimiento supera al mío. Si quieres aprender más, debes hablar con Me''lynn. Ella te guiará.' WHERE `ID`=8084;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='재봉술이란 아주 즐거운 기술이니까 결코 실망하지 않을 거예요.', `FemaleText_loc4`='你不会失望的，旅行者。裁缝是一种充满乐趣的工作。', `FemaleText_loc5`='你不會失望的，旅人。裁縫是一種充滿樂趣的工作。', `FemaleText_loc7`='No te defraudaré, $gviajero:viajera;. La sastrería es una profesión que te llenará de júbilo.' WHERE `ID`=8085;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오세요. 뭘 도와드릴까요?', `MaleText_loc4`='嗨，我能为你做什么呢？', `MaleText_loc5`='嗨，我能為你做什麼呢?', `MaleText_loc7`='¡Eh, colega! ¿Qué puedo hacer por ti?' WHERE `ID`=8086;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 당신은 내게 배울 수 있는 걸 다 배웠습니다. 당신은 오그리마에 있는 마가르를 찾아가야 할지도 모르겠군요. 성질이 불같은 게 탈이긴 하지만 당신을 도와주기는 할 겁니다.', `MaleText_loc4`='你所掌握的知识已经跟我差不多啦。或许你可以去奥格瑞玛找玛加尔。他虽然不是最好的裁缝，但是他一定可以帮助你。', `MaleText_loc5`='你所掌握的知識已經跟我差不多啦。或許你可以去奧格瑪找瑪加爾。他雖然不是最好的裁縫，但是他一定可以幫助你。', `MaleText_loc7`='En este momento sabes tanto como yo, colega. Quizás deberías ir a ver a Magar en Orgrimmar. No es que sea el sastre más feliz del mundo, pero podrá ayudarte.' WHERE `ID`=8087;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 그런 자세입니다! 바늘하고 실을 가지고 오십시오. 당장 시작합시다!', `MaleText_loc4`='这就对了！拿起针线让我们开始吧！', `MaleText_loc5`='這就對了!拿起針線讓我們開始吧!', `MaleText_loc7`='¡Buena actitud! ¡Pilla la aguja y el hilo y empecemos a darle marcha!' WHERE `ID`=8088;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 더는 친절하거나 겸손하지 못할까 걱정이군. 세월과 끝없는 전쟁으로 내 몸뚱이와 영혼이 모두 굳어버린 듯하군. 어쩌면 그 때문에 케른 님께서 날 해바위 야영지로 보낸 것인지도 모르지... 부드러운 바람과 따뜻한 햇살이 고통을 덜어주는구려.', `MaleText_loc4`='恐怕我已不再是个文雅谦逊的人了。年龄和无数战争让我的皮肤和灵魂变得坚硬无比。或许这就是凯恩派我来烈日石居的原因……和煦的暖风和温暖的阳光无法减轻我的痛苦。', `MaleText_loc5`='恐怕我已不再是個文雅謙遜的人了。年齡和無數戰爭讓我的皮膚和靈魂變得堅硬無比。或許這就是凱恩派我來烈日石居的原因...和煦的暖風和溫暖的陽光無法減輕我的痛苦。', `MaleText_loc7`='Me temo que ya no soy moderado ni modesto. La edad y las innumerables batallas han endurecido tanto mi piel como mi alma. Quizás por eso Cairne me envió al Refugio Roca del Sol... los suaves vientos y el cálido sol sirven para calmar el dolor.' WHERE `ID`=8089;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 올 줄 알았소, $n. 또 보게 돼서 반갑군, 친구.', `MaleText_loc4`='我知道你会来的，$n。很高兴再次见到你，朋友。', `MaleText_loc5`='我知道你會來的，$n。很高興再次見到你，朋友。', `MaleText_loc7`='Sabía que vendrías, $n. Me alegra verte de nuevo, camarada.' WHERE `ID`=8090;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여어!', `MaleText_loc4`='嗷！', `MaleText_loc5`='嗷!', `MaleText_loc7`='¡Aaaaau!' WHERE `ID`=8091;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 힘을 잃고 작동을 멈춥니다!', `MaleText_loc4`='%s失去能量，被关闭了！', `MaleText_loc5`='%s失去能量，停止運作!', `MaleText_loc7`='%s pierde potencia y se apaga.' WHERE `ID`=8092;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 거의 조각났습니다!', `MaleText_loc4`='%s几乎碎掉了！', `MaleText_loc5`='%s幾乎粉碎了!', `MaleText_loc7`='%s casi se hace añicos.' WHERE `ID`=8093;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하시오. 우리 박쥐들은 훈련도 잘된 상태고 먹을 것도 많이 먹었소. 이 박쥐들보다 빠른 녀석들은 찾아볼 수 없을 것이오.', `MaleText_loc4`='你好。我们的蝙蝠训练很严而且吃得不错。你不会找到比他们还快的了。', `MaleText_loc5`='你好。我們的蝙蝠訓練很嚴而且吃得不錯。你不會找到比他們還快的了。', `MaleText_loc7`='Saludos. Nuestros murciélagos están bien entrenados y alimentados. No los encontrarás más rápidos.' WHERE `ID`=8094;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무엇을 도와주면 되겠나?', `MaleText_loc4`='我要如何效劳？', `MaleText_loc5`='我要如何效勞?', `MaleText_loc7`='¿Cómo te puedo ayudar?' WHERE `ID`=8095;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까? 잘 오셨습니다. 전 웃는 데 서투르지만 당신을 손님으로 맞이하게 되어 기쁩니다.', `MaleText_loc4`='你好，欢迎。我不太擅长微笑，但是相信我；我很高兴能为您服务。', `MaleText_loc5`='你好，歡迎。我不太擅長微笑，但是相信我;我很高興能為您服務。', `MaleText_loc7`='Hola, te doy la bienvenida. No se me da muy bien sonreír, pero confía en mí, estoy contento de poder ayudarte.' WHERE `ID`=8096;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물건을 구입하고 싶습니다.', `MaleText_loc4`='让我看看你的货物。', `MaleText_loc5`='讓我看看你的貨物。', `MaleText_loc7`='Deja que eche un vistazo a tus mercancías.', `FemaleText_loc1`='물건을 구입하고 싶습니다.', `FemaleText_loc4`='让我看看你的货物。', `FemaleText_loc5`='讓我看看你的貨物。', `FemaleText_loc7`='Deja que eche un vistazo a tus mercancías.' WHERE `ID`=8097;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='히포그리프는 긍지를 알고 고결하며 재빠른 짐승으로서 명예를 위해 훈련을 받아왔습니다. 그대를 아주 먼 곳까지 빠르게 데려다 줄 수 있지요.', `FemaleText_loc4`='角鹰兽是一种高贵而迅捷的动物。这些训练有素的飞兽可以让它们的骑手以很快的速度旅行。', `FemaleText_loc5`='角鷹獸是一種高貴而迅捷的動物。這些訓練有素的飛獸可以讓它們的騎手以很快的速度旅行。', `FemaleText_loc7`='El hipogrifo es una bestia noble, orgullosa y rápida. Es un honor entrenarlos y pueden transportar a sus jinetes rápidamente a una gran distancia.' WHERE `ID`=8098;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='육지와 연결하기 위해 저희는 루테란 마을과 어둠해안 사이를 왕복하는 히포그리프를 두고 있습니다.', `MaleText_loc4`='为了与大陆保持联系，我们会定期派出角鹰兽在鲁瑟兰村和黑海岸之间传递信息的。', `MaleText_loc5`='為了與大陸保持聯繫，我們會定期派出角鷹獸在魯瑟蘭村和黑海岸之間傳遞資訊的。', `MaleText_loc7`='Para mantener nuestro contacto con la península, tenemos hipogrifos volando constantemente entre la Aldea Rut''theran y la Costa Oscura.' WHERE `ID`=8099;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='텔드랏실의 해안에서 잡히는 물고기는 매우 크고 기운차답니다. 소문에 따르면 우리 세계수가 빨리 자라는 것이 그 원인이라고 하는군요.', `FemaleText_loc4`='泰达希尔海岸边的鱼儿又大又精神。有传言说那是因为我们新的世界之树的快速增长而引起的。', `FemaleText_loc5`='泰達希爾海岸邊的魚兒又大又精神。有傳言說那是因為我們新的世界之樹的快速增長而引起的。', `FemaleText_loc7`='El pescado de la Costa de Teldrassil es bastante grande y robusto. Según dicen por ahí, la causa de esto es el veloz crecimiento de nuestro nuevo Árbol del Mundo.' WHERE `ID`=8100;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠해안이 텔드랏실의 해안보다 위험하기는 하지만 많은 낚시꾼들이 이곳에서 수익을 올리고 있습니다.', `MaleText_loc4`='尽管黑海岸比泰达希尔更危险，但是很多渔夫都在此谋生。', `MaleText_loc5`='儘管黑海岸比泰達希爾更危險，但是很多漁夫都在此謀生。', `MaleText_loc7`='Si bien la Costa Oscura es más peligrosa que la de Teldrassil, muchos pescadores obtienen buenos beneficios allí.' WHERE `ID`=8101;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모험가분들께 제 물건을 제공하게 되어 영광입니다. 모험가분들은 영웅이 될 자질이 풍부한 이들이니까 말입니다.', `MaleText_loc4`='为冒险家服务是我的荣幸，因为他们即将成为英雄。', `MaleText_loc5`='為冒險家服務是我的榮幸，因為他們即將成為英雄。', `MaleText_loc7`='Es un honor poder suministrar a los aventureros, ya que son héroes en potencia.' WHERE `ID`=8102;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미안하네만 자네는 내 그리핀을 탈 수 없네. 자네가 원하는 곳으로 가려면 그링거에게 가 보게나.', `MaleText_loc4`='很抱歉我不能让你乘坐我的狮鹫。如果你确实需要飞行服务的话，就去找格林戈谈谈。', `MaleText_loc5`='很抱歉我不能讓你乘坐我的獅鷲獸。要是你確實需要的話，就去找格林戈談談。', `MaleText_loc7`='Lo siento, pero no puedo permitirte montar a uno de mis grifos. Deberías ir a hablar con Gringer si necesitas un transporte.' WHERE `ID`=8103;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맹금의 봉우리에서 가장 빠른 그리핀일세. 타겠나?', `MaleText_loc4`='我这里的狮鹫是鹰巢山以南飞得最快的。想要乘坐吗？', `MaleText_loc5`='鷹巢山這邊最快的獅鷲獸了。想乘坐嗎?', `MaleText_loc7`='Los grifos más rápidos a este lado del Pico Nidal. ¿Te apetece un paseo?' WHERE `ID`=8104;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋습니다! 탑시다.', `MaleText_loc4`='好吧！我们出发。', `MaleText_loc5`='好吧!我們出發。', `MaleText_loc7`='¡Claro! Vayamos a dar una vuelta.', `FemaleText_loc1`='좋습니다! 탑시다.', `FemaleText_loc4`='好吧！我们出发。', `FemaleText_loc5`='好吧!我們出發。', `FemaleText_loc7`='¡Claro! Vayamos a dar una vuelta.' WHERE `ID`=8105;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='북쪽 부두에서는 루테란 마을과 다르나서스로 가는 배를 탈 수 있고 남쪽 부두에서는 대해를 건너 스톰윈드 항구로 갈 수 있네. 방파제의 맨 끝에 있는 서쪽 부두에서 엑소다르 근처인 하늘안개 섬으로 갈 수 있다네. 그럼, 편안하고 즐거운 여행이 되기를 빌지!', `MaleText_loc4`='你可以在北边的码头搭船前往鲁瑟兰村和达纳苏斯。南边的码头是穿越无尽之海通往暴风城港口的航线。西边的那座码头通往埃索达附近的秘蓝岛。祝你一路平安！', `MaleText_loc5`='你可以在北部碼頭搭船前往魯瑟蘭村和達納蘇斯。你可以在南部碼頭發現穿越無盡之海通往暴風港。西邊的碼頭，直走到底，則航向藍謎島，艾克索達的附近。祝你一路平安!', `MaleText_loc7`='En el embarcadero del norte, puedes subirte a un barco que te llevará a la Aldea Rut''theran y a Darnassus. En el embarcadero del sur, puedes encontrar un pasaje a través del Mare Magnum hasta el Puerto de Ventormenta. El embarcadero del oeste, al final del muelle, llega hasta la Isla Bruma Azur, cerca de El Exodar. ¡Buen viaje!' WHERE `ID`=8106;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하게, 친구. 프레스톨은 쉽게 쓰러지지 않을 걸세.', `MaleText_loc4`='朋友，保持警惕。除非打一架，否则母龙是不会放弃的。', `MaleText_loc5`='朋友，保持警惕。除非打一架，否則母龍是不會放棄的。', `MaleText_loc7`='En guardia, camarada. El dragón no se rendirá sin luchar.' WHERE `ID`=8107;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 이 부두 말인가요? 이곳을 운항하는 배는 그 나이트 엘프들이 있는 곳으로 출항하죠. 이름이 뭐더라? 아마도... 아우... 아우버다인일 거예요. 정확하게는 모르겠어요. 전 단지 짐만 싣고 내릴 뿐이거든요.', `MaleText_loc4`='这个码头？你可以乘船前往暗夜精灵的领地。地名？嗯，我想是奥伯丁。我不太确定，我只是一名搬运工。', `MaleText_loc5`='這個碼頭?你可以乘船前往夜精靈的領地。地名?嗯，我想是奧伯丁。我不太確定，我只是一名搬運工。', `MaleText_loc7`='¿Este embarcadero de aquí? Bueno, puedes coger el barco que va a ese sitio de los elfos de la noche. ¿Cómo se llama? Mmm... Auberdine, creo. No lo sé seguro, solo cargo y descargo mercancías.' WHERE `ID`=8108;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 오래전 카라잔에서 결정된 대로 내가 왔소. 그리고 정의의 심판이 내릴 것이오!', `MaleText_loc4`='就像很久以前在卡拉赞注定的那样，怪物。我来了，带着公正的裁决而来！', `MaleText_loc5`='怪物，如同前生就於卡拉贊註定一般—我來了—帶著公正的裁決而來。', `MaleText_loc7`='Como se predijo hace una eternidad en Karazhan, monstruo, he venido y, conmigo, traigo la justicia.' WHERE `ID`=8109;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 내 배달을 도와주러 왔나? 미란도 이제 곧 준비가 될 걸세.', `MaleText_loc4`='你是来帮助投递物品的吗？米兰就快准备好了。', `MaleText_loc5`='你是來幫助投遞物品的嗎?米蘭就快準備好了。', `MaleText_loc7`='¿Estás aquí para ayudar con la entrega? Miran está a punto.' WHERE `ID`=8110;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 와이번은 뜨거운 불모의 땅의 공기를 헤치고 빠르게 나아갈 수 있도록 훈련되어 있다네.', `MaleText_loc4`='我的双足飞龙可以在贫瘠之地高速飞翔。', `MaleText_loc5`='我的雙足飛龍可以在貧瘠之地高速飛翔。', `MaleText_loc7`='Mis jinetes del viento están entrenados para volar rápidamente atravesando el aire caliente de Los Baldíos.' WHERE `ID`=8111;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불모의 땅에는 작열하는 태양과 적대적인 생물들이 있어 자네의 강인함과 불굴의 의지를 시험하기에 최적의 장소라네.', `MaleText_loc4`='贫瘠之地阳光灼热，那儿的居住者充满敌意，是考验你的力量和决心的最佳地点。', `MaleText_loc5`='貧瘠之地陽光灼熱，那兒的居住者充滿敵意，是考驗你的力量和決心的最佳地點。', `MaleText_loc7`='Los Baldíos, con su sol abrasador y sus crueles habitantes, es el lugar perfecto para probar tu fuerza y tu entereza.' WHERE `ID`=8112;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 화약통들을 발굴현장으로 배달하는 것은 힘든 일이네. 하지만 그곳에는 화약을 얻으려고 우리에게 의지하는 이가 너무 많다네.$B$B검은무쇠 부족에 대항하기 위해 우리가 할 수 있는 일은 다해야 하네!', `MaleText_loc4`='要将这些桶运送到挖掘点非常困难，但是要获得火药，还得靠我们自己。$B$B我们必须竭尽所能地对抗黑铁！', `MaleText_loc5`='要將這些桶運送到挖掘點非常困難，但是要獲得火藥，還得靠我們自己。$B$B我們必須竭盡所能地對抗黑鐵!', `MaleText_loc7`='Llevar esos barriles a la excavación es un trabajo duro, pero hay muchos que dependen de que les llevemos la pólvora.$B$B¡Debemos hacer todo lo posible contra los Hierro Negro!' WHERE `ID`=8113;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하시오. 가죽 용품을 사려고 왔다면 내 물건이 질이 좋다는 것을 한 눈에 알아볼 수 있을 것이오.', `MaleText_loc4`='你好。如果你是来找皮件的，那么你会看到我的货品做工精细。', `MaleText_loc5`='你好。如果你是來找皮件的，那麼你會看到我的貨品做工精細。', `MaleText_loc7`='Saludos. Si has venido a encontrar objetos de cuero, verás que mis mercancías son de excelente calidad.' WHERE `ID`=8114;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와줘서 고맙네, $n. 자네 덕분에 발굴현장에 뱃짐을 안전하게 배달할 수 있었네.', `MaleText_loc4`='谢谢你的帮助，$n。在你的帮助下，另一艘货船安全抵达了挖掘地。', `MaleText_loc5`='謝謝你的幫助，$n。在你的幫助下，另一艘貨船安全抵達了挖掘地。', `MaleText_loc7`='Te agradezco tu ayuda, $n. Gracias a ti, otro cargamento ha llegado a salvo a la excavación.' WHERE `ID`=8115;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와이번 등에 타면 왜 와이번이 강인함과 빠른 속도로 유명한지 알게 될 것이오.', `MaleText_loc4`='当坐在一个驭风者背上时，你就会发现它的力量和速度的确不是徒有虚名。', `MaleText_loc5`='當坐在一頭雙足飛龍背上時，你就會發現它的力量和速度的確不是徒有虛名。', `MaleText_loc7`='Cuando estás montado a lomos de un jinete del viento, puedes ver que su reputación de fuerza y velocidad es bien merecida.' WHERE `ID`=8116;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 나보다 훨씬 낫군! 자넨 나보다도 경험이 풍부한 이가 필요하겠는데... 그런 이라면 아마 언더시티 연금술 실험실에서 일하는 언데드 학자 허버트 핼시 정도가 되겠군.', `MaleText_loc4`='你操纵得比我要好！你需要一个经验比我还要多的人。那就是赫?特·哈尔希医生，一个在幽暗城炼金房工作的亡灵。', `MaleText_loc5`='你操縱得比我要好!你需要一個經驗比我還要多的人。那就是赫伯特·哈爾希醫生，一個在幽暗城鍊金房工作的亡靈。', `MaleText_loc7`='¡Esto se te da mejor que a mí! Necesitas a alguien más experimentado que yo. Y ese puede ser el doctor Herbert Halsey, un no-muerto que trabaja en El Apothecarium de Entrañas.' WHERE `ID`=8117;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일인가? 자네 내 명성을 망치려는 건가? 난 초보자는 가르치지 않네. 다르나서스 장인의 정원에 있는 밀라 페어랜코라에게 가 보게.', `MaleText_loc4`='什么？你试图毁坏我的名声？我不教新手的，$g老兄:女士;。去找达纳苏斯工匠区的米拉·法拉科纳谈谈。', `MaleText_loc5`='這是什麼?你試圖毀壞我的名聲?我不教新手的，$g老兄:女士;。去找達納蘇斯工匠區的米拉·法拉科納談談。', `MaleText_loc7`='¿Qué es esto? ¿Intentas arruinar mi reputación? No enseño a novatos, $gchico:chica;. Ve a hablar con Milla Fairancora en el Bancal del Artesano en Darnassus.' WHERE `ID`=8118;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저놈을 잡아라! 저 쓸모없는 죄인과 그 친구들을 잡아들여라!', `FemaleText_loc4`='抓住他！抓住这个卑鄙的罪犯和他的同伙！', `FemaleText_loc5`='抓住他!抓住這個卑鄙的罪犯和他的同夥!', `FemaleText_loc7`='¡Atrapadle! ¡Apresad al indigno criminal y a sus aliados!' WHERE `ID`=8119;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 고기 좀 둘러보게, 친구. 예비 식량을 넉넉하게 챙기지 않고서 불모의 땅에 나가고 싶지는 않을 걸세.', `MaleText_loc4`='看看我的肉，朋友。你不会想双手空空就进入贫瘠之地吧。', `MaleText_loc5`='看看我的肉，朋友。你不會想雙手空空就進入貧瘠之地吧。', `MaleText_loc7`='Echa un vistazo a mi carne. No creo que quieras adentrarte en Los Baldíos sin buenas provisiones.' WHERE `ID`=8120;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='레지널드, 자네를 통과시킬 수 없다는 것을 알지 않나?', `MaleText_loc4`='雷吉纳德，你知道，我是不能让你通过的。', `MaleText_loc5`='雷吉納德，你知道，我是不能讓你通過的。', `MaleText_loc7`='Reginald, sabes que no puedo dejarte pasar.' WHERE `ID`=8121;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와이번 등에 올라타 세상을 내려다보지 않고서는 세상을 살았다고 할 수 없지.', `MaleText_loc4`='在你从驭风者背上往下俯瞰这个世界之前，不能说你真正活过。', `MaleText_loc5`='在你從雙足飛龍背上往下俯瞰這個世界之前，不能說你真正活過。', `MaleText_loc7`='No has vivido hasta que no has visto el mundo desde un jinete del viento.' WHERE `ID`=8122;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자신이 옳다고 생각하는 것을 해야 하네, 마커스. 우리는 투랄리온 장군 밑에서 함께 복무했잖나. 투랄리온 장군께서는 오늘날의 우리를 만들어 주신 분이시네. 진정 내가 우리 동맹에 해를 끼치려 한다고 믿는 것인가? 내가 우리 영웅들을 수치스럽게 할 인물로 보이나?', `MaleText_loc4`='你一定要做你认为是正确的事情，马库斯。我们一起在图拉扬将军麾下服役。他使我们两个成为了今天的样子。他看错我了么？你真的相信我的目的是要破坏我们的联盟吗？我让我们的英雄们蒙羞了吗？', `MaleText_loc5`='你一定要做你認為是正確的事情，馬庫斯。我們一起服役於圖拉揚將軍。他使我們兩個成為今天的樣子。他看錯我了嗎?你真的相信我的目的是要破壞我們的聯盟嗎?我給我們的英雄們蒙羞了嗎?', `MaleText_loc7`='Debes hacer lo que creas correcto, Marcus. Servimos juntos a las órdenes de Turalyon. Él nos convirtió en los hombres que somos hoy. ¿Crees que se equivocó conmigo? ¿Realmente piensas que pretendo hacer daño a nuestra alianza? ¿Crees que avergonzaría a nuestros héroes?' WHERE `ID`=8123;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 사색에 잠긴 듯합니다.', `MaleText_loc4`='%s似乎陷入了沉思。', `MaleText_loc5`='%s似乎陷入沉思。', `MaleText_loc7`='%s parece meditar.' WHERE `ID`=8124;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 부끄럽다네, 나의 오랜 친구여. 나도 더 이상 내가 무슨 짓을 하는지 모르겠다네. 전설의 영웅들에게 수치를 가져올 자는 자네가 아니라 바로 나라네. 나와 이 부패한 정치가들 말이야. 그들은 끊임없는 거짓말로 우리에게 공허한 약속만 하고 있네.', `MaleText_loc4`='我很惭愧，老朋友。我不知道我该怎么办了。并不是你使那些伟大的英雄蒙羞，而是我。是我和其余堕落的政客们。他们让我们的生命中充满空洞的诺言和无尽的谎言。', `MaleText_loc5`='我很慚愧，老朋友。我不知道我該怎麼辦了。並不是你使傳奇英雄蒙羞--而是我。是我和其餘墮落的政客。他們讓我們的生命中充滿空洞的諾言，無盡的謊言。', `MaleText_loc7`='Me siento avergonzado. Ya no sé qué hago. No eres tú quien podría avergonzar a los héroes de la leyenda... sino yo. Yo y el resto de esos políticos corruptos. Llenan nuestras vidas de promesas vacías, mentiras interminables.' WHERE `ID`=8125;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='친구여, 자네는 경계를 늦추지 않고 저 영웅들을 명예스럽게 하고 있지 않는가? 자네의 충성심은 확고하다네. 난 자네가 경의를 표하는 저 영웅들 못지않게 시민들을 위해 희생할 것을 단 한순간도 의심한 적이 없네.', `MaleText_loc4`='亲爱的朋友，你警惕的目光让英雄们以你为荣，你对联盟忠心耿耿。你会在必要的时候像那些俯瞰着你的英雄一样，为你的人民做出伟大的牺牲，我对此毫不怀疑。', `MaleText_loc5`='親愛的朋友，你用警惕的眼光注視著他們。你真忠心。你不會像那些在你之上的英雄一樣，為你的人民做出偉大的犧牲，我對此毫不懷疑。', `MaleText_loc7`='Querido amigo, tú les honras con tu vigilante guardia. Eres firme en tu lealtad. No dudo ni por un instante, que no harías un sacrificio por tu gente tan grande como cualquiera de los héroes que están por encima de ti.' WHERE `ID`=8126;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멈춰라! 너희들 눈에는 살아 있는 전설이 보이지 않는단 말이냐?', `MaleText_loc4`='退后！你们没看到英雄正在与我们同行吗？', `MaleText_loc5`='退後!你沒看見那些英雄與我們同行嗎?', `MaleText_loc7`='¡Agachaos! ¿No veis que los héroes están pasando entre nosotros?' WHERE `ID`=8127;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비켜라! 저들을 지나가게 하도록 해라!', `MaleText_loc4`='让开！让他们过去！', `MaleText_loc5`='到旁邊去!讓他們過去!', `MaleText_loc7`='¡Moveos! ¡Dejadles pasar!' WHERE `ID`=8128;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='레지널드 윈저 치안대장을 다치게 해서는 안 된다! 손 끝 하나도 대지 말고 지나가시게 해 드려라!', `MaleText_loc4`='雷吉纳德·温德索尔不得受到任何伤害！让他安全地通过这里！', `MaleText_loc5`='雷吉納德·溫德索爾不能受到傷害!他必須安全!', `MaleText_loc7`='¡Reginald Windsor no debe sufrir ni un rasguño! ¡Pasará por aquí y nadie le tocará!' WHERE `ID`=8129;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 가게, 레지널드. 성스러운 빛이 자네를 인도하기를.', `MaleText_loc4`='去吧，雷吉纳德。愿光明指引着你。', `MaleText_loc5`='去吧，雷吉納德。願光明指引著你。', `MaleText_loc7`='Adelante, Reginald. Que la Luz guíe tu mano.' WHERE `ID`=8130;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 부두에서 테라모어로 가실 수 있습니다. 제 말 잘 들으세요. 그곳은 얼라이언스들이 여행하기에 안전한 곳이 절대 아니니 항상 조심하시고 뒤를 살피세요.', `MaleText_loc4`='你可以从这个码头找到去塞拉摩的路。记住我的话，那些地方对从联盟去的人们是非常不安全的。一定要小心谨慎。', `MaleText_loc5`='你可以從這個碼頭找到去塞拉摩的路。記住我的話，那些地方對從聯盟去的人們是非常不安全的。一定要小心謹慎。', `MaleText_loc7`='En este embarcadero puedes encontrar un pasaje a Theramore. Haz caso de lo que digo, esas tierras no son un lugar seguro para la Alianza. Cuidado con dónde pisas y vigila tu espalda.' WHERE `ID`=8131;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 선조님을 수치스럽게 만들고 있다네. 우린 전쟁터에서 잃은 이들을 수치스럽게 만들고 있어... 용서하게, 레지널드 ...', `MaleText_loc4`='我们令祖先蒙羞。我们令牺牲的同胞蒙羞……原谅我吧，雷吉纳德。', `MaleText_loc5`='我們令祖先蒙羞。我們令犧牲的同胞蒙羞...原諒我吧，雷納德。', `MaleText_loc7`='Avergonzamos a nuestros ancestros. Avergonzamos a aquellos que murieron por nosotros... perdóname, Reginald.' WHERE `ID`=8132;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나를 이곳에 붙들고 있는 것은 현명하지 못한 처사야, 마커스.', `MaleText_loc4`='把我挡在这里可不是明智的决定，马库斯。', `MaleText_loc5`='把我監禁在這裡可不是明智的決定，馬庫斯。', `MaleText_loc7`='Mantenerme aquí no es la decisión correcta, Marcus.' WHERE `ID`=8133;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제는 여군주 프레스톨의 통치를 끝내야 할 시간이네, 마커스. 비켜서게, 친구.', `MaleText_loc4`='现在是结束她统治的时候了，马库斯。让开，我的朋友。', `MaleText_loc5`='現在是結束她統治的時候了，馬庫斯。走吧，朋友。', `MaleText_loc7`='Es hora de poner fin a su reinado, Marcus. No te incorpores, camarada.' WHERE `ID`=8134;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가죽에 대한 자네의 지식이 나보다 깊어졌군. 아마도 자넨 잿빛 골짜기의 아스트라나르 마을에 있는 아얀디아 플로럴윈드를 찾아가야 할 거 같군. 자네 같이 재능을 가진 자에게 가르칠 지식이 풍부한 인물일세.', `MaleText_loc4`='你对皮革的理解比我要深刻。可能你应该拜访一下灰谷森林阿斯特兰纳的艾蒂安·花丛之风。对你这么聪明的学生,她应该有很多知识要教给你。', `MaleText_loc5`='你對皮革的理解比我要深刻。可能你應該拜訪一下梣谷森林阿斯特蘭納的艾蒂安·花叢之風。對你這麼聰明的學生,她應該有很多知識要教給你。', `MaleText_loc7`='Tu conocimiento del cuero supera al mío. Quizás deberías visitar a Aayndia Vientofloral en la ciudad de Astranaar en el Bosque de Vallefresno. Tiene mucho que ofrecer a un estudiante de tu talento.' WHERE `ID`=8135;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까?', `MaleText_loc4`='你好。', `MaleText_loc5`='你好。', `MaleText_loc7`='Que tengas un buen día.' WHERE `ID`=8136;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대의 기술은 이제 내 기술을 앞질렀습니다. 길모퉁이 근처에 던컨의 옷가게의 주인인 조르지오 볼레로가 그대의 기술을 향상할 수 있도록 도와줄 것입니다.', `MaleText_loc4`='你的技艺在我的技术水平之上了。可能你该见见我们商店的老板，乔吉奥·波利罗。他就站在那边的柜台附近。', `MaleText_loc5`='你的技藝在我的技術水準之上了。喬吉奧·波利羅，轉角鄧肯布料店老闆可能精進你的技能。', `MaleText_loc7`='Superas mi nivel de pericia. Georgio Bolero, el maestro de Tejidos Duncan, al doblar la esquina, podría ayudarte a progresar en tus habilidades.' WHERE `ID`=8137;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대에게 기술을 가르쳐줄 수야 있지만 먼저 그럴 만한 자격이 있는지 증명해 보여야 합니다.', `MaleText_loc4`='我会教你的，但是首先你得证明自己的实力……', `MaleText_loc5`='我會教你的，但是首先你得證明自己的實力...', `MaleText_loc7`='Te enseñaré, pero primero debes demostrar tu valía...' WHERE `ID`=8138;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왼쪽 모퉁이를 돌아 쭉 내려가면 던컨의 옷가게가 보일 겁니다. 거기서 일하는 로렌스 슈나이더와 얘기해 보십시오. 초보 재봉사들을 아주 잘 가르치는 분입니다.', `MaleText_loc4`='跟楼梯那儿的劳伦斯·瑟尼德交谈。他善于引导初学者。', `MaleText_loc5`='跟樓梯那兒的勞倫斯·瑟尼德交談。他善於引導初學者。', `MaleText_loc7`='Habla con Lawrence Shneider en Tejidos Duncan. Justo pasada la esquina, a la izquierda. Tiene gran experiencia con principiantes.' WHERE `ID`=8139;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대의 실력은 잘 보았으니 그럼 이제부터 내 기술을 가르쳐주도록 하겠습니다.', `MaleText_loc4`='都是些有用的东西。你的教导可以继续进行了。', `MaleText_loc5`='都是些有用的東西。你的教導可以繼續進行了。', `MaleText_loc7`='Una buena demostración. Tu instrucción puede continuar.' WHERE `ID`=8140;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 이 다르나서스 옷감이 최고라니까!', `MaleText_loc4`='啊，这件达纳苏斯织品质量最好！', `MaleText_loc5`='啊，這件達納蘇斯織品品質最好!', `MaleText_loc7`='¡Ah, esta tela de Darnassus es la mejor!' WHERE `ID`=8141;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음... 머리가 아주 좋은 친구로군. 당신이 나보다도 많이 알고 있는 건 인정하지! 자만하라고 하는 말은 아니지만 계속해서 배우고 싶다면 스톰윈드에 있는 조르지오 볼레로와 얘기해 보시오. 재봉술만큼은 아주 제대로 알고 있는 친구니까!', `MaleText_loc4`='嗯，你这个聪明的家伙！我可以明确地告诉你，你知道的比我多！你可别为此自负，如果你想继续学习的话，就去暴风城找乔吉奥·波利罗谈谈吧。听说他是个很好的裁缝！', `MaleText_loc5`='嗯，你這個聰明的傢伙!我可以明確地告訴你，你知道的比我多!你可別為此自負，如果你想繼續學習的話，就去暴風城找喬吉奧·波利羅談談吧。聽說他是個很好的裁縫!', `MaleText_loc7`='¡Uy! ¿No eres tú quien se las sabe todas? ¡Sabes más que yo, y te lo digo yo! No vayas por ahí en plan presumido... si quieres seguir aprendiendo, habla con Georgio Bolero en Ventormenta. ¡Dicen que es buen sastre, sí señor!' WHERE `ID`=8142;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 아무나 가르치지 않소! 먼저 과제를 하나 끝내야 하오!', `MaleText_loc4`='我不训练任何人！你需要首先完成一项任务！', `MaleText_loc5`='我不訓練任何人!你需要首先完成一項任務!', `MaleText_loc7`='¡No instruyo a cualquiera! ¡Tendrás que hacer una tarea primero!' WHERE `ID`=8143;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 초보자나 봐주고 있을 시간은 없소이다! 내 조수인 우슬라하고나 얘기해 보시오!', `MaleText_loc4`='我可没时间跟小孩子耗！去跟我的助手阿斯拉谈谈！', `MaleText_loc5`='我可沒時間跟小孩子耗!去跟我的助手阿斯拉談談!', `MaleText_loc7`='¡No tengo tiempo para hacer de canguro! Vete a hablar con mi asistente, Uthrar.' WHERE `ID`=8144;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠... 소질은 있는 것 같군. 그건 인정하지. 좋소. 그럼 어디까지 얘기했더라?', `MaleText_loc4`='嗯……看来还有点希望，我会把那个给你的。那好吧，我们在哪里？', `MaleText_loc5`='嗯...看來還有點希望，我會把那個給你的。那好吧，我們在哪裡?', `MaleText_loc7`='Mmm... parece que prometes, te concedo eso. ¿Y bien? ¿Dónde estábamos?' WHERE `ID`=8145;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='주위를 둘러보십시오. 그리고 오늘 그대가 본 것을 생각해 보십시오.$b$b이 숲에 처음으로 온 이후로 많은 것이 변했습니다. 깜짝 놀랄만한, 그리고 전혀 예상치 못했던 변화지요...', `FemaleText_loc4`='看看周围，$r。你应该为今天能看到的一切而心存感激。$b$b自从我第一次走进这片森林，这里的许多东西都已经改变了。这些都是奇妙的，出乎意料的改变……', `FemaleText_loc5`='看看你的周圍，$r。對你今天所看到的抱持感激之心。$b$b與我剛踏入這個森林相比，現在它改變了很多。美好和令人意外的改變....', `FemaleText_loc7`='Mira a tu alrededor, $c. Disfruta de lo que ves.$b$bMuchas cosas han cambiado desde la primera vez que pisé este bosque. Cambios maravillosos e inesperados...' WHERE `ID`=8146;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 가게에 있는 많은 것들을 내가 만들었지. 어떤가? 신중히 대답하지 않으면 목숨을 잃을 수도 있어.', `MaleText_loc4`='我能制造你在商店里看见的若干东西。你认为如何？小心回答，这也许能决定你的命运。', `MaleText_loc5`='我能製造你在商店裡看見的若干東西。你認為如何?小心回答，這也許能決定你的命運。', `MaleText_loc7`='Yo mismo he hecho muchas de las cosas que ves en la tienda. ¿Qué te parece? Responde con cuidado, tu vida podría depender de ello.' WHERE `ID`=8147;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 나보다 더 많이 아는 자에게 배워야 하네. 언더시티로 가서 조셉 그레고리안과 얘기해 보게나. 아니, 어서 가지 않고 뭐 하는 건가?', `MaleText_loc4`='你需要找一个比我懂得多的人。去找幽暗城的乔瑟夫·格里高利谈谈。那么，你还在这里干吗？', `MaleText_loc5`='你需要找一個比我懂得多的人。去找幽暗城的喬瑟夫·格里高利談談。那麼，你還在這裡幹嗎?', `MaleText_loc7`='Tienes que aprender con alguien que sepa más que yo. Ve a hablar con Josef Gregorian en Entrañas. ¿Y bien? ¿Por qué sigues aquí?' WHERE `ID`=8148;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그냥 날 찾아오기만 하면 내가 가르쳐줄 거라 생각했나? 흥! 내게서 배우려면 다른 자들처럼 대가를 지급해야 하네!', `MaleText_loc4`='你认为你走到我跟前我就开始教你了？哈！你需要像其余所有人一样支付学费！', `MaleText_loc5`='你認為你走到我跟前我就開始教你了?哈!你需要像其餘所有人一樣支付學費!', `MaleText_loc7`='¿Crees que puedes venir a verme sin más y empezar a aprender? ¡Ja! ¡Tienes que pagar tus deudas, como todo el mundo!' WHERE `ID`=8149;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐지? 왜 날 귀찮게 하는 건가? 자네는 고품질의 로브도 만들지 못할 것 같은데 말이야! 가서 스낭하고나 얘기해 보게. 내 가르침을 받을 자격이 되면 그때 다시 찾아오라고!', `MaleText_loc4`='什么？你为什么在烦我？哎呀，我打赌你甚至不能制造一件高质量的长袍！去找斯诺恩谈谈，等你水平提高以后再来找我！', `MaleText_loc5`='什麼?你為什麼在煩我?哎呀，我打賭你甚至不能製造一件高品質的長袍!去找斯諾恩談談，等你水準提高以後再來找我!', `MaleText_loc7`='¿Qué? ¿Por qué me molestas? ¡Vamos, que apuesto lo que quieras a que ni siquiera puedes hacer una túnica de buena calidad! ¡Ve a hablar con Snang y vuelve cuando te merezcas aprender con alguien de mi talento!' WHERE `ID`=8150;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제야 뭔가 좀 하는 것 같군! 지금부터는 내가 제대로 하는 게 어떤 건지 보여주지!', `MaleText_loc4`='你那时给我看了某些结果！现在该我给你看看结果了！', `MaleText_loc5`='你那時給我看了某些結果!現在該我給你看看結果了!', `MaleText_loc7`='¡Ya era hora de que demostrases algún resultado! ¡Ahora, yo te mostraré resultados!' WHERE `ID`=8151;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제때 한 땀 뜬 것이 몇 땀의 수고를 던다더라? 열한 땀이던가? 아, 모르겠군. 어차피 말도 안 되는 속담이니...', `MaleText_loc4`='他们说小洞不补大洞……什么来着？啊，我记不得了。反正是愚蠢的说法。', `MaleText_loc5`='他們說小洞不補大洞...什麼來著?啊，我記不得了。反正是愚蠢的說法。', `MaleText_loc7`='Dicen que una puntada a tiempo ahorra... ¿cuántas, mil? Ah, no lo puedo recordar. Es un refrán estúpido de todas formas.' WHERE `ID`=8152;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='초보자치고는 말이야... 나쁘지 않군! 게다가 나랑 실력도 비슷하고. 더 배우고 싶거든 언더시티에 있는 조셉 그레고리안을 찾아가야 할 걸세.', `MaleText_loc4`='对一个业余者来说……这还行！你的知识量已经跟我持平了。要是你想学习更多知识，就去幽暗城找乔瑟夫·格里高利谈谈。', `MaleText_loc5`='對一個業餘者來說...這還行!你的知識量已經跟我持平了。要是你想學習更多知識，就去幽暗城找喬瑟夫·格里高利談談。', `MaleText_loc7`='No está mal... ¡para un principiante! De todas formas, sabes casi tanto como yo. Si quieres aprender más, ve a hablar con Josef Gregorian en Entrañas.' WHERE `ID`=8153;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네에게 소질이 있을 수도 있고 없을 수도 있지만 그걸 알아낼 방법이 하나 있지...', `MaleText_loc4`='或许你懂了，或许你没懂。我想我会设法查明真相的……', `MaleText_loc5`='或許你懂了，或許你沒懂。我想我會設法查明真相的...', `MaleText_loc7`='Quizás lo tengas, o quizás no. Creo que sé la manera de descubrirlo...' WHERE `ID`=8154;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하! 아직은 솜씨가 모자라는군. 좀 더 배운 뒤에나 날 찾아오게나!', `MaleText_loc4`='哈！你仍然还没有所需的……！你学会些东西后再来找我！', `MaleText_loc5`='哈!你仍然還沒有所需的...!你學會些東西後再來找我!', `MaleText_loc7`='¡Ja! No tienes lo que se necesita... todavía. ¡Vuelve a verme cuando hayas aprendido unas cuantas cosas más!' WHERE `ID`=8155;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠... 괜찮군. 내가 몇 가지 가르쳐줘도 되겠어...', `MaleText_loc4`='嗯，嗯，还不坏。或许我能让你看点什么……', `MaleText_loc5`='嗯，嗯，還不壞。或許我能讓你看點什麼...', `MaleText_loc7`='Bueno, bueno, no está demasiado mal. Quizás PUEDA enseñarte un par de cosas...' WHERE `ID`=8156;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='날씨가 아주 좋군요! 새로운 옷을 만들어 내기에 좋은 날씨에요.', `FemaleText_loc4`='多好的天气！它让我有了创造新设计的灵感。', `FemaleText_loc5`='多好的天氣!它讓我有了創造新設計的靈感。', `FemaleText_loc7`='¡Qué día tan estupendo! Me inspira para crear un nuevo diseño.' WHERE `ID`=8157;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그대는 재능이 아주 뛰어나군요! 정말로 영감이 좋은 분이에요. 계속해서 더 배울 생각이라면 스톰윈드에 있는 조르지오 볼레로를 찾아가 보세요. 아주 유명하신 분이라 그대를 잘 가르쳐주실 거예요.', `FemaleText_loc4`='你的才能出众！你真是有灵性。你要想继续追求知识的话，找暴风城的乔吉奥·波利罗谈谈。他深受众人尊敬，而且他能深化对你的指导。', `FemaleText_loc5`='你的才能出眾!你真是有靈性。你要想繼續追求知識的話，找暴風城的喬吉奧·波利羅談談。他深受眾人尊敬，而且他能深化對你的指導。', `FemaleText_loc7`='¡Tus talentos son excelentes! ¡Qué gran inspiración! Para continuar con tu búsqueda de conocimiento, ve a hablar con Georgio Bolero en Ventormenta. Todos le tienen un gran respeto y podrá ayudarte a avanzar en tu instrucción.' WHERE `ID`=8158;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='최고의 경지에 오르려면 그에 앞서 많은 난관을 극복해야 한답니다. 그건 그대도 마찬가지고요...', `FemaleText_loc4`='一个人在通向成功的路上必须克服很多困难。你的道路也不例外……', `FemaleText_loc5`='一個人在通向成功的路上必須克服很多困難。你的道路也不例外...', `FemaleText_loc7`='En el camino de la excelencia, hay muchos obstáculos que vencer. Tu camino no es una excepción...' WHERE `ID`=8159;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어느 기술이나 꼭 배워야 하는 기본기가 있게 마련이죠. 트리안나가 근처에 있을 테니 가서 얘기를 나눠보고 나중에 다시 찾아오도록 하세요.', `FemaleText_loc4`='必须首先学习一些基础知识。蒂安娜就站在旁边，找她谈谈然后回来找我。', `FemaleText_loc5`='必須首先學習一些基礎知識。蒂安娜就站在旁邊，找她談談然後回來找我。', `FemaleText_loc7`='Tienes que aprender los principios básicos. Trianna está aquí cerca, habla con ella y vuelve a verme más tarde.' WHERE `ID`=8160;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아주 잘하셨어요, 여행자님. 이제 그대를 제자라고 자신 있게 불러도 되겠네요!', `FemaleText_loc4`='你干的很好，旅行者。我能收你当徒弟令感到很骄傲！', `FemaleText_loc5`='你幹得很好，旅人。我能收你當徒弟令感到很驕傲!', `FemaleText_loc7`='Lo has hecho bien, $gviajero:viajera;. ¡Me siento orgullosa de poder tenerte como estudiante!' WHERE `ID`=8161;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저희 야영지에 잘 오셨습니다. 무엇을 도와드릴까요?', `FemaleText_loc4`='欢迎来到我的帐篷。我可以帮你吗？', `FemaleText_loc5`='歡迎來到我的帳篷。我可以幫你嗎?', `FemaleText_loc7`='Te doy la bienvenida a nuestra tienda. ¿Puedo ayudarte?' WHERE `ID`=8162;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아주 많은 것을 알고 계시군요, 여행자님. 당신은 나보다 더 현명한 사람에게 배워야 해요. 조셉 그레고리안이라는 자의 지혜에 대해서 많이들 얘기하니 언더시티로 한번 가보도록 하세요.', `FemaleText_loc4`='你的知识很渊博，旅行者。你必须向一个比我更聪明的人学习。关于乔瑟夫·格里高利的智慧的故事广为流传。你可以在幽暗城找到他。', `FemaleText_loc5`='你的知識很淵博，旅人。你必須向一個比我更聰明的人學習。關於喬瑟夫·格里高利的智慧的故事廣為流傳。你可以在幽暗城找到他。', `FemaleText_loc7`='Tienes un gran conocimiento, $gviajero:viajera;. Debes aprender de alguien más sabio que yo. Se han contado muchas historias sobre la sabiduría de Josef Gregorian. Puedes encontrarle en Entrañas.' WHERE `ID`=8163;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='먼저, 한 가지 과제를 마쳐줬으면 좋겠군요...', `FemaleText_loc4`='在我们继续之前我想让你完成一项任务……', `FemaleText_loc5`='在我們繼續之前我想讓你完成一項任務...', `FemaleText_loc7`='Hay algo que me gustaría que hicieras antes de seguir avanzando...' WHERE `ID`=8164;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 가르침을 받기 전에 당신이 먼저 배워야 할 것들이 있습니다. 썬더 블러프에 있는 반을 찾아가보면 도움을 받을 수 있을 겁니다.', `FemaleText_loc4`='在我开始培训你之前你还有功课要学。而在同时，或许雷霆崖的范恩能够帮你。', `FemaleText_loc5`='在我開始培訓你之前你還有功課要學。而在同時，或許雷霆崖的樊恩能夠幫你。', `FemaleText_loc7`='Todavía te quedan lecciones por aprender antes de que pueda encargarme de tu instrucción. Mientras tanto, quizás Vhan, en Cima del Trueno pueda ayudarte.' WHERE `ID`=8165;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아주 훌륭해요! 그럼 수업을 계속하도록 하죠...', `FemaleText_loc4`='完成得很熟练！现在，让我们继续你的教育……', `FemaleText_loc5`='完成得很熟練!現在，讓我們繼續你的教育...', `FemaleText_loc7`='¡Lo has hecho excelentemente bien! Ahora, continuemos con tu educación...' WHERE `ID`=8166;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성스러운 빛이 함께하기를 빕니다, 대장님.', `MaleText_loc4`='愿圣光与您同在，长官。', `MaleText_loc5`='願光明與你同在，先生。', `MaleText_loc7`='Que la Luz sea contigo, señor.', `FemaleText_loc1`='성스러운 빛이 함께하기를 빕니다, 대장님.', `FemaleText_loc4`='愿圣光与您同在，长官。', `FemaleText_loc5`='願光明與你同在，先生。', `FemaleText_loc7`='Que la Luz sea contigo, señor.' WHERE `ID`=8167;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무늬가 정말 아름답지 않나요? 각각의 무늬가 저마다의 목소리로 말을 하고 있어요.', `FemaleText_loc4`='这些图案难道不漂亮吗？每一个都有自己的风格。', `FemaleText_loc5`='這些圖案難道不漂亮嗎?每一個都有自己的風格。', `FemaleText_loc7`='¿No son preciosos los diseños? Cada uno de ellos habla con su propia voz.' WHERE `ID`=8168;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저도 계속 배우고는 있지만 제 지식에는 아직까지 한계가 있어요. 이제 당신은 다른 사람을 찾아가야 합니다. 언더시티에 있는 조셉 그레고리안을 찾아가 배울 준비가 됐다고 말하세요.', `FemaleText_loc4`='我的知识有限，尽管我还在继续学习。现在该你继续了，旅行者。在幽暗城找到乔瑟夫·格里高利并告诉他你准备好了。', `FemaleText_loc5`='我的知識有限，儘管我還在繼續學習。現在該你繼續了，旅人。在幽暗城找到喬瑟夫·格里高利並告訴他你準備好了。', `FemaleText_loc7`='Mi conocimiento es limitado, sigo aprendiendo. Es hora de que sigas adelante. Busca a Josef Gregorian en Entrañas y dile que ya estás $gpreparado:preparada;.' WHERE `ID`=8169;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대장님께서는 우리 모두의 귀감이십니다.', `MaleText_loc4`='您对我们所有人都是一种激励，阁下。', `MaleText_loc5`='你對我們所有人都是一種激勵，閣下。', `MaleText_loc7`='Eres una inspiración para todos nosotros, señor.', `FemaleText_loc1`='대장님께서는 우리 모두의 귀감이십니다.', `FemaleText_loc4`='您对我们所有人都是一种激励，阁下。', `FemaleText_loc5`='你對我們所有人都是一種激勵，閣下。', `FemaleText_loc7`='Eres una inspiración para todos nosotros, señor.' WHERE `ID`=8170;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저의 지식을 함께 나누기 전에 먼저 당신의 결의가 어떤 것인지 한번 보았으면 좋겠군요.', `FemaleText_loc4`='在我教给你我的本事之前我需要看到你的决心……', `FemaleText_loc5`='在我教給你我的本事之前我需要看到你的決心...', `FemaleText_loc7`='Necesitaré una demostración de tu determinación antes de compartir mi talento contigo...' WHERE `ID`=8171;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 영웅이 가신다.', `MaleText_loc4`='那边走过来一位英雄。', `MaleText_loc5`='那邊走過來一位英雄。', `MaleText_loc7`='Por ahí va un héroe.', `FemaleText_loc1`='여기 영웅이 가신다.', `FemaleText_loc4`='那边走过来一位英雄。', `FemaleText_loc5`='那邊走過來一位英雄。', `FemaleText_loc7`='Por ahí va un héroe.' WHERE `ID`=8172;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제 도움을 받기 전에 먼저 기본적인 것들을 배워야 합니다. 제 수습생인 반과 얘기해 보세요. 친절하고 인내심이 강한 친구라 당신이 배워야 할 것들을 잘 가르쳐줄 겁니다.', `FemaleText_loc4`='在我帮你之前你必须学会一些基础的东西。与我的徒弟范恩谈谈。他很耐心而且愿意教你所需的知识。', `FemaleText_loc5`='在我幫你之前你必須學會一些基礎的東西。與我的徒弟樊恩談談。他很耐心而且願意教你所需的知識。', `FemaleText_loc7`='Debes aprender las cosas fundamentales antes de que pueda enseñarte. Ve a hablar con mi aprendiz, Vhan. Es amable y paciente, y te enseñará todo lo que necesitas saber.' WHERE `ID`=8173;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신은 아주 의지가 강한 학생이로군요. 기꺼이 재봉술을 가르쳐주도록 하죠!', `FemaleText_loc4`='你真是一个意志坚定的学生。我很高兴给你提供指导！', `FemaleText_loc5`='你真是一個意志堅定的學生。我很高興給你提供指導!', `FemaleText_loc7`='Tienes mucha determinación. ¡Estaré encantada de instruirte!' WHERE `ID`=8174;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='길을 비켜라!', `MaleText_loc4`='让开！', `MaleText_loc5`='前進!', `MaleText_loc7`='¡Haced sitio!', `FemaleText_loc1`='길을 비켜라!', `FemaleText_loc4`='让开！', `FemaleText_loc5`='前進!', `FemaleText_loc7`='¡Haced sitio!' WHERE `ID`=8175;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='재봉술은 아주 유용하답니다. 한번은 제 팔을 꿰맨 적도 있었거든요.', `FemaleText_loc4`='裁缝可以派得上大用场。我从前就不得不把我的胳膊缝上。', `FemaleText_loc5`='裁縫可以派得上大用場。我從前就不得不把我的胳膊縫上。', `FemaleText_loc7`='Saber coser puede resultar muy útil. Una vez tuve que coserme el brazo al cuerpo.' WHERE `ID`=8176;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 그저 대장님의 발아래 흙 같은 존재일 뿐입니다.', `MaleText_loc4`='我们不过是您脚下的尘土。', `MaleText_loc5`='我們不過是您腳下的塵土。', `MaleText_loc7`='Solo somos suciedad bajo sus pies, señor.', `FemaleText_loc1`='우리는 그저 대장님의 발아래 흙 같은 존재일 뿐입니다.', `FemaleText_loc4`='我们不过是您脚下的尘土。', `FemaleText_loc5`='我們不過是您腳下的塵土。', `FemaleText_loc7`='Solo somos suciedad bajo sus pies, señor.' WHERE `ID`=8177;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신은 열심히 배웠으니... 이제는 나보다 더 뛰어난 재봉술을 보유한 자를 만나야 해요. 조셉에게 가서 준비가 됐다고 말하세요.', `FemaleText_loc4`='你做得很好……是时候见见老板了。找到乔瑟夫并告诉他你准备好了。', `FemaleText_loc5`='你已經完成了...是時候見見老闆了。找到喬瑟夫並告訴他你準備好了。', `FemaleText_loc7`='Has logrado avanzar, es hora de que vayas a ver al jefe. Ve a ver a Josef y dile que ya estás $gpreparado:preparada;.' WHERE `ID`=8178;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋아요... 재봉사가 되고 싶다는 것이지요. 그걸 한번 증명해 보이는 게 어때요?', `FemaleText_loc4`='好的……那么说你想成为一个裁缝。你能证明这点么？', `FemaleText_loc5`='好的...那麼說你想成為一個裁縫。你能證明這點麼?', `FemaleText_loc7`='Muy bien... ¿Así que quieres ser un sastre? ¿Qué te parece si me lo demuestras?' WHERE `ID`=8179;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이날을 언제까지나 기억할 것입니다.', `MaleText_loc4`='我永远都会记住这一刻。', `MaleText_loc5`='我永遠都會記住這一刻。', `MaleText_loc7`='Un momento que recordaré eternamente.', `FemaleText_loc1`='이날을 언제까지나 기억할 것입니다.', `FemaleText_loc4`='我永远都会记住这一刻。', `FemaleText_loc5`='我永遠都會記住這一刻。', `FemaleText_loc7`='Un momento que recordaré eternamente.' WHERE `ID`=8180;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='초보자에게는 제 비밀 노하우를 나눠드릴 수 없으니 먼저 빅터 워드와 얘기해 보세요.', `FemaleText_loc4`='我怎么能把我的秘密告诉一个初学者呢？先试着跟博文谈谈。', `FemaleText_loc5`='我怎麼能把我的秘密告訴一個初學者呢?先試著跟維克多·瓦德談談。', `FemaleText_loc7`='¿Cómo voy a compartir mis secretos con $gun principiante:una principiante;? Vete a hablar primero con Victor Ward.' WHERE `ID`=8181;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋아요, 소질이 있군요! 맘에 드는데요. 자, 그럼 시작하도록 하죠!', `FemaleText_loc4`='好极了，你很有勇气！我很满意。那么，我们就出发吧！', `FemaleText_loc5`='好極了，你很有勇氣!我很滿意。那麼，我們就出發吧!', `FemaleText_loc7`='Bien, tienes agallas. Me gusta. ¡En marcha!' WHERE `ID`=8182;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='담력이 토륨같이 센 분이라는군.', `MaleText_loc4`='……瑟银的胆量。', `MaleText_loc5`='...瑟銀的膽量。', `MaleText_loc7`='... coraje de torio.', `FemaleText_loc1`='담력이 토륨같이 센 분이라는군.', `FemaleText_loc4`='……瑟银的胆量。', `FemaleText_loc5`='...瑟銀的膽量。', `FemaleText_loc7`='... coraje de torio.' WHERE `ID`=8183;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살아있는 전설...', `MaleText_loc4`='一个活生生的传说……', `MaleText_loc5`='生動的傳說...', `MaleText_loc7`='Una leyenda viviente...', `FemaleText_loc1`='살아있는 전설...', `FemaleText_loc4`='一个活生生的传说……', `FemaleText_loc5`='生動的傳說...', `FemaleText_loc7`='Una leyenda viviente...' WHERE `ID`=8184;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇습니다. 이 상점을 운영한 지는 꽤 됐지요. 요즘 들어서는 장사도 아주 잘 되는 편이랍니다. 새로운 모험가들이 많이 지나다니고 있거든요.', `MaleText_loc4`='是的，我现在已经经营这家店一段时间了。最近生意非常好。许多新的探险者来了……', `MaleText_loc5`='是的，我現在已經經營這家店一段時間了。最近生意非常好。許多新的探險者來了...', `MaleText_loc7`='Sí, llevo algún tiempo dirigiendo esta tienda. El negocio ha ido bastante bien últimamente. Muchos aventureros nuevos pasan por aquí...' WHERE `ID`=8185;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나보다 재봉술 솜씨가 좋은 자가 아제로스에 있다면 딱 하나뿐입니다. 마지막으로 들은 소문에 의하면 테라모어 섬에 있다고 하던데, 바로 그분을 찾아가야 할 겁니다.', `MaleText_loc4`='我只知道有一个人能在裁缝技能上胜过我。我最后一次听说他在塞拉摩岛。你该去找他。', `MaleText_loc5`='我只知道有一個人能在裁縫技能上勝過我。我最後一次聽說他在塞拉摩島。你該去找他。', `MaleText_loc7`='Solo hay una persona con más talento en el arte de la sastrería que yo. La última vez que supe de él, estaba en la Isla Theramore. Él es la persona a quien debes buscar.' WHERE `ID`=8186;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 제자가 되려고 오는 모든 이들에게 먼저 결의를 입증해 보이라고 하지요. 자, 이제 당신 차례입니다.', `MaleText_loc4`='我要所有学生都证明他们的热情。现在轮到你了……', `MaleText_loc5`='我要所有學生都證明他們的熱情。現在輪到你了...', `MaleText_loc7`='Exijo que todos mis estudiantes demuestren su dedicación. Es tu turno...' WHERE `ID`=8187;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 됐지만 내게 가르침을 받기에는 아직 좀 모자라는 것 같군요. 더 배워야겠습니다.', `MaleText_loc4`='我恐怕在我可以教授你知识之前你要需要更多的训练。', `MaleText_loc5`='我恐怕在我可以教授你知識之前你要需要更多的訓練。', `MaleText_loc7`='Me temo que necesitas más instrucción antes de que pueda compartir mi conocimiento contigo.' WHERE `ID`=8188;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아! 이제 당신을 가르친다 해도 헛수고는 아니겠군요!', `MaleText_loc4`='太好了！我能断定我的努力不会白费！', `MaleText_loc5`='太好了!我能斷定我的努力不會白費!', `MaleText_loc7`='¡Bien! ¡Veo que mis esfuerzos no han sido en vano!' WHERE `ID`=8189;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='옷감도 괜찮지만 개인적으로는 인간의 피부를 더 좋아하지.', `MaleText_loc4`='布料也可以。就我个人来说我更喜欢使用人皮。', `MaleText_loc5`='布料也可以。就我個人來說我更喜歡使用人皮。', `MaleText_loc7`='La tela está bien. Aunque, personalmente, prefiero trabajar con piel humana.' WHERE `ID`=8190;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정한 장인의 지도를 받아야겠군! 타렌 제분소에 있는 다릴 스택을 찾아가 자네의 운명을 맡기는 게 좋겠어!', `MaleText_loc4`='你需要一个真正大师的指导！到塔伦米尔的达瑞尔·斯塔克那儿去试试你的运气！', `MaleText_loc5`='你需要一個真正大師的指導!到塔倫米爾的達瑞爾·斯塔克那兒去試試你的運氣!', `MaleText_loc7`='¡Necesitas la instrucción de un verdadero maestro! ¡Ve a ver a Daryl Stack en el Molino Tarren y acepta tu destino!' WHERE `ID`=8191;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네에게 뭔가 가르쳐주기 전에 한 가지 부탁할 게 있는데...', `MaleText_loc4`='在你开始学习之前，我得让你帮我个忙……', `MaleText_loc5`='在你開始學習之前，我得讓你幫我個忙...', `MaleText_loc7`='Antes de que dé comienzo tu instrucción, debo pedirte un favor...' WHERE `ID`=8192;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='때가 되면 가르쳐주겠어. 하지만 지금은 때가 안 됐어. 먼저 기초부터 다지고 와야겠군!', `MaleText_loc4`='当时机合适时，我会传授知识给你的……不是现在。你还得学习更多的知识！', `MaleText_loc5`='當時機合適時，我會傳授知識給你的...不是現在。你還得學習更多的知識!', `MaleText_loc7`='Te instruiré cuando llegue el momento preciso... y, ese momento, aún no ha llegado. ¡Todavía te queda mucho por aprender!' WHERE `ID`=8193;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아! 당신을 가르치는 게 최소한 헛수고는 되지 않겠군!', `MaleText_loc4`='太好了！我能断定我的努力不会白费！', `MaleText_loc5`='太好了!我能斷定我的努力不會白費!', `MaleText_loc7`='¡Bien! ¡Veo que mis esfuerzos no han sido en vano!' WHERE `ID`=8194;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 왕에게도 옷을 만들어 바쳤지요. 훈련만 제대로 받는다면 당신도 그렇게 할 수 있을 겁니다.', `MaleText_loc4`='我给国王提供过装备。如果有正确的训练，你也可以。', `MaleText_loc5`='我給國王提供過裝備。如果有正確的訓練，你也可以。', `MaleText_loc7`='He vestido a reyes. Con la instrucción adecuada, tú también podrás hacerlo.' WHERE `ID`=8195;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='축하합니다! 당신은 머지않아 최고의 재봉사가 될 것입니다! 당신을 가르칠 수 있어서 정말 영광입니다!', `MaleText_loc4`='你已经真正成为这行中最好的裁缝之一了！恭喜你，我为曾当过你的导师而感到骄傲！', `MaleText_loc5`='你已經真正成為這行中最好的裁縫之一了!恭喜你，我為曾當過你的導師而感到驕傲!', `MaleText_loc7`='¡Realmente te has convertido en uno de los mejores sastres que hay! ¡Enhorabuena, me siento orgulloso de haber sido tu instructor!' WHERE `ID`=8196;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 먼 길을 오셨군요. 당신이 해줄 일이 하나 있습니다...', `MaleText_loc4`='你走了好远的路了，旅行者。还有一项工作要你完成……', `MaleText_loc5`='你走了好遠的路了，旅人。還有一項工作要你完成...', `MaleText_loc7`='Has hecho un largo viaje. Hay una tarea más que necesito que hagas...' WHERE `ID`=8197;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기본기를 좀 더 다지고 오셔야겠습니다. 그렇지 않으면 저도 도와드릴 수가 없겠군요. 준비가 되거든 그때 다시 찾아오십시오.', `MaleText_loc4`='你要学习更多的基本技能，我才能帮助你。当你准备好了再来找我。', `MaleText_loc5`='你要學習更多的基本技能，我才能幫助你。當你準備好了再來找我。', `MaleText_loc7`='No puedo ayudarte hasta que hayas aprendido mejor los principios básicos. Vuelve a verme cuando lo hayas superado.' WHERE `ID`=8198;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 그럴 가치도 없는 자입니다, 대장님.', `MaleText_loc4`='我不值得，先生。', `MaleText_loc5`='我不值得，先生。', `MaleText_loc7`='No soy digno, señor.' WHERE `ID`=8199;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에는 찬바람이 좀 들긴 하지만... 뭐, 상관없지. 어차피 난 죽은 몸이니까.', `MaleText_loc4`='这地方通风良好……但是我还在乎什么？我已经死了。', `MaleText_loc5`='這地方通風良好...但是我還在乎什麼?我已經死了。', `MaleText_loc7`='En este lugar hay mucha corriente... ¿Pero qué me importa? Estoy muerto.' WHERE `ID`=8200;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수고했소. 이제 당신은 재봉술의 최고봉에 오른 것이오. 가서 이 기술로 끔찍한 일들을 한번 저질러 보시오!', `MaleText_loc4`='干得好！你获得了裁缝的最高荣誉。去吧，好好利用自己的知识去做大事！', `MaleText_loc5`='幹得好!你獲得了裁縫的最高榮譽。去吧，好好利用自己的知識去做大事!', `MaleText_loc7`='Bien hecho. Has obtenido el más alto honor de sastrería. ¡Sigue adelante y crea magníficas obras con tu conocimiento!' WHERE `ID`=8201;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='재봉술을 아주 착실하게 배우고 있군. 그건 인정하겠소. 자, 그러면 진짜 솜씨가 어느 정도인지 알아볼까...', `MaleText_loc4`='你在缝纫艺术方面做得很好，我必须承认。现在，让我们看看你到底有多棒……', `MaleText_loc5`='你在縫紉藝術方面做得很好，我必須承認。現在，讓我們看看你到底有多棒...', `MaleText_loc7`='Debo admitir que lo estás haciendo muy bien en el arte de la sastrería. Y ahora, veamos lo REALMENTE capaz que eres...' WHERE `ID`=8202;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 당신을 여기로 보냈소? 아직 가르침을 받을 준비가 덜 됐어! 때가 되면 누군가 말해줄 거요.', `MaleText_loc4`='谁派你来的？你还没有准备好接受我的指令！当你们准备好以后会得到通知的。', `MaleText_loc5`='誰派你來的?你還沒有準備好接受我的指令!當你們準備好以後會得到通知的。', `MaleText_loc7`='¿Quién te ha enviado aquí? ¡Todavía no puedes recibir mi instrucción! Te lo dirán cuando estés $glisto:lista;.' WHERE `ID`=8203;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전 대해에서 들려오는 소리를 들으며 여기 앉아 있는 것을 좋아한답니다. 오, 뭐라고 하셨죠? 네, 메네실 항구로 가는 배가 있죠. 이곳에 가끔 정박한답니다.', `FemaleText_loc4`='我确实很喜欢坐在这里，听着大海的声音。哦，什么？是的，有一艘船会把你带到米奈希尔港。它有时会停在这里。', `FemaleText_loc5`='我確實很喜歡坐在這裡，聽著大海的聲音。哦，什麼?是的，有一艘船會把你帶到米奈希爾港。它有時會停在這裡。', `FemaleText_loc7`='Disfruto muchísimo aquí sentada, escuchando los sonidos del Mare Magnum. ¿Qué? Sí, hay un barco que puede llevarte al Puerto de Menethil. Atraca aquí de vez en cuando.' WHERE `ID`=8204;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙네, 나의 오랜 친구여. 자네는 옳은 일을 하는 걸세.', `MaleText_loc4`='谢谢你，老朋友。你做得好。', `MaleText_loc5`='謝謝你，老朋友。你做得好。', `MaleText_loc7`='Gracias, $gviejo amigo:vieja amiga;. Has hecho lo correcto.' WHERE `ID`=8205;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='따라오게, 친구들이여. 스톰윈드 왕궁으로 가세!', `MaleText_loc4`='跟着我，朋友。到暴风城要塞！', `MaleText_loc5`='跟著我，朋友。到暴風要塞!', `MaleText_loc7`='Amigos, seguidme. ¡Al Castillo de Ventormenta!' WHERE `ID`=8206;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용기를 내시오, 친구들. 파충류들이 사정없이 공격해 올 것이오. 하지만 그것은 녀석들의 절박함에서 나오는 행동일 뿐이오.', `MaleText_loc4`='朋友，勇敢些。这只爬虫会剧烈地翻滚起来。那是绝望的表现。你准备好了就跟我说一声。', `MaleText_loc5`='朋友，勇敢些。這只爬蟲會劇烈地翻滾起來。那是絕望的表現。你準備好了就跟我說一聲。', `MaleText_loc7`='Sed valientes, amigos. El reptil se sacudirá violentamente. Es un acto de desesperación. Cuando estéis listos, avisad.' WHERE `ID`=8207;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앞으로!', `MaleText_loc4`='前进！', `MaleText_loc5`='前進!', `MaleText_loc7`='¡Adelante!' WHERE `ID`=8208;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 장담하지! 자네는 여기 텔사마에 있는 그리핀보다 더 빠른 녀석을 동부 왕국 어디에서도 찾아볼 수 없을 걸세.', `MaleText_loc4`='记得我的话！你在东部王国是找不到比塞尔萨玛狮鹫更快的狮鹫的！', `MaleText_loc5`='記得我的話!你在東部王國是找不到比塞爾薩瑪獅鷲獸更快的獅鷲獸的!', `MaleText_loc7`='¡Ya verás! ¡No encontrarás grifos más rápidos en ningún lugar de los Reinos del Este que los que están aquí, en Thelsamar!' WHERE `ID`=8209;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폐하, 아직 힘이 남아 계실 때 도망치십시오. 그녀는 폐하의 상상을 초월하는...', `MaleText_loc4`='国王陛下，请在一切还来得及的时候赶快退避一下吧。她并非你所想象的那样……', `MaleText_loc5`='君王，盡你所能地跑吧。她並非你想像的那樣...', `MaleText_loc7`='Majestad, corred mientras podéis. No es quien creéis que es...' WHERE `ID`=8210;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무도회는 끝났다, 프레스톨. 아니면 진짜 이름으로 불러 줄까? 오닉시아...', `MaleText_loc4`='化妆舞会结束了，女伯爵普瑞斯托。或者我应该称呼你的真名……奥妮克希亚……', `MaleText_loc5`='化妝舞會結束了，普瑞斯托女士。我能叫你的本名嗎...奧妮克希亞...', `MaleText_loc7`='La farsa se ha terminado, Lady Prestor. O... debería llamarte por tu verdadero nombre... Onyxia...' WHERE `ID`=8211;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 안전한 곳으로 가시지요, 폐하.', `MaleText_loc4`='尊贵的陛下，请到安全的大厅去。', `MaleText_loc5`='尊貴的王，請到安全的大廳去。', `MaleText_loc7`='A la sala asegurada, su majestad.' WHERE `ID`=8212;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 물어보더라도 이 세상에 광부보다 좋은 직업은 없다고 대답하겠습니다. 우리 드워프를 능가하는 광부는 더더욱 없고 말이죠!', `MaleText_loc4`='要是你问我的话，没有比矿工更好的职业了，也没有比矮人更好的矿工了！', `MaleText_loc5`='要是你問我的話，沒有比礦工更好的職業了，也沒有比矮人更好的礦工了!', `MaleText_loc7`='Si me lo preguntas a mí, no hay mejor profesión que la del minero. Y, si me lo preguntas a mí, no hay mejor minero que un enano.' WHERE `ID`=8213;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 비웃습니다.', `FemaleText_loc4`='%s笑起来。', `FemaleText_loc5`='%s大笑。', `FemaleText_loc7`='%s ríe.' WHERE `ID`=8214;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너는 반역죄로 재판을 받아 투옥될 것이다, 윈저! 유죄 판결과 함께 사형을 선고 받고 교수형 당하는 꼴을 즐겁게 지켜봐 주지.', `FemaleText_loc4`='你会被监禁并因叛国罪接受审判，温德索尔。我会很高兴看到他们宣布你有罪，并把你送上绞刑架……', `FemaleText_loc5`='你會被監禁並以叛國罪接受審判，溫德索爾。我很高興看到他們宣佈有罪判決並判處你絞刑...', `FemaleText_loc7`='Windsor, serás encarcelado y juzgado por traición. Estaré observando con júbilo mientras pronuncian el veredicto de culpabilidad y dictan tu sentencia de muerte... en la horca.' WHERE `ID`=8215;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너의 힘없는 사체가 교수대에 매달려 있을 때 나는 미치광이를 처리했다는 사실에 매우 기쁠 것이야. 결국 아무런 증거도 없지 않는가? 이런 식으로 쳐들어와서 이 여군주에게 손가락질을 해대고도 무사할 줄 알았더냐?', `FemaleText_loc4`='当你瘫软的尸体在绞刑架上摇摆的时候，我会为一个疯子的性命终于得到终结而高兴。毕竟，你有什么证据呢？你难道想要到这里来挑衅一个贵族，然后毫发无伤地离开？', `FemaleText_loc5`='你柔軟的屍體隨著木筏搖擺著，我很高興得知一個瘋子又被殺死了。畢竟，你有什麼證據呢?你難道想要到這裡來挑釁一個貴族，然後毫髮無傷地離開?', `FemaleText_loc7`='Y, cuando tu cadáver lacio y sin vida, cuelgue de las vigas, me complacerá saber que un hombre loco ha sido ejecutado. Después de todo, ¿qué pruebas tienes? ¿Esperabas venir aquí, señalar con el dedo a un miembro de la familia real y salir indemne?' WHERE `ID`=8216;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맹금의 봉우리에 있는 와일드해머 드워프들도 빠른 그리핀들을 가지고 있긴 하지만 과연 그 그리핀들이 대용광로의 열기를 견뎌낼 수 있을까요? 어림도 없죠!', `MaleText_loc4`='蛮锤城堡的矮人也许有奔跑迅速的战马，但是这些鹰巢山的狮鹫能承受大熔炉的热量吗？我觉得不能！', `MaleText_loc5`='蠻錘城堡的矮人也許有奔跑迅速的戰馬，但是這些鷹巢山的獅鷲獸能承受大鍛爐的熱量嗎?我覺得不能!', `MaleText_loc7`='Es posible que los enanos Martillo Salvaje tengan veloces corceles pero, ¿podrán esos grifos del Pico Nidal soportar el calor de La Gran Fundición? ¡No lo creo!' WHERE `ID`=8217;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음을 면치 못하리라, 오닉시아! 그 예언은 카라잔의 위대한 전당에 울려 퍼져왔다. 이제야 끝나는구나...', `MaleText_loc4`='你逃脱不了你的命运，奥妮克希亚。预言早已注定了这一切——卡拉赞的大厅里浮现的幻景早已预示了你的结局。现在来做一个了结吧……', `MaleText_loc5`='妳逃脫不了妳的命運的，奧妮克希亞。這已經被預言了-由宏偉的卡拉贊大廳裡呈現的景象。一切將在此結束...', `MaleText_loc7`='No escaparás a tu destino, Onyxia. La profecía así lo cuenta... una visión resonando en las grandes salas de Karazhan. Acaba ahora...' WHERE `ID`=8218;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 들어라, 용이여. 진실이 이곳에 울려 퍼질 것이다.', `MaleText_loc4`='听着，你这条龙。让真相大白于天下吧。', `MaleText_loc5`='聽著，飛龍。讓真相在大廳中迴響吧。', `MaleText_loc7`='Escucha, dragón. Que la verdad resuene en estas salas.' WHERE `ID`=8219;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최고의 광부라면 곡괭이를 단단히 잡는 손과 가슴에 있는 용기, 머리에 두껍게 앉은 먼지부터가 다르지.', `MaleText_loc4`='最好的矿工紧握$g他:她;的铁锄，拥有一颗坚定的心，头发上还散落着一层厚厚的黑灰。', `MaleText_loc5`='最好的礦工緊握$g他:她;的鐵鋤，擁有一顆堅定的心，頭髮上還散落著一層厚厚的黑灰。', `MaleText_loc7`='El buen minero tiene bien agarrado su pico, un corazón fuerte en el pecho y polvo denso y negro en el pelo.' WHERE `ID`=8220;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련을 받고 싶습니다.', `MaleText_loc4`='我要接受训练。', `MaleText_loc5`='我要接受訓練。', `MaleText_loc7`='Me gustaría recibir instrucción.', `FemaleText_loc1`='훈련을 받고 싶습니다.', `FemaleText_loc4`='我要接受训练。', `FemaleText_loc5`='我要接受訓練。', `FemaleText_loc7`='Me gustaría recibir instrucción.' WHERE `ID`=8221;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='튼튼한 상자가 잔해와 붉은십자군의 열성적인 추종자들에게 둘러싸인 채로 벌목지 중앙에 놓여 있습니다.', `MaleText_loc4`='那个坚固的箱子在木材厂中间，周围推满了残骸和血色十字军的狂热信徒。', `MaleText_loc5`='那個堅固的木箱在木材廠中間，周圍推滿了殘骸和血色十字軍的狂熱信徒。', `MaleText_loc7`='La sólida caja está en el centro del aserradero, rodeada de escombros y muchos seguidores fervientes de la Cruzada Escarlata.' WHERE `ID`=8222;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흰개미 통을 상자에 놓아야 합니다.', `MaleText_loc4`='将装有白蚁的桶放入箱中。', `MaleText_loc5`='將白蟻桶放入木箱中。', `MaleText_loc7`='Coloca el barril de termitas en la caja.', `FemaleText_loc1`='흰개미 통을 상자에 놓아야 합니다.', `FemaleText_loc4`='将装有白蚁的桶放入箱中。', `FemaleText_loc5`='將白蟻桶放入木箱中。', `FemaleText_loc7`='Coloca el barril de termitas en la caja.' WHERE `ID`=8223;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 심각한 부상으로 추적을 포기합니다.', `MaleText_loc4`='%s伤得太重，放弃了追逐。', `MaleText_loc5`='%s因傷勢太重而放棄追擊。', `MaleText_loc7`='%s abandona la persecución, ha recibido demasiado daño.' WHERE `ID`=8224;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 패배하여 도망치려 합니다.', `MaleText_loc4`='%s很明显被击败了，他正试图逃跑。', `MaleText_loc5`='很明顯，%s被擊敗了，正試圖逃跑呢。', `MaleText_loc7`='%s intenta correr, está claro que ha perdido.' WHERE `ID`=8225;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 소지품 안에서 암호화된 서판을 꺼냅니다.', `MaleText_loc4`='%s打开包裹，取出密文石板。', `MaleText_loc5`='%s打開他的包裹，取出石板。', `MaleText_loc7`='%s mete la mano en su mochila y saca las tablillas codificadas.' WHERE `ID`=8226;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은무쇠 부족은 이 서판이 암호화되었다고 생각했다. 암호가 아니라 고대 용족의 언어이다.', `MaleText_loc4`='黑铁矮人认为这些石板是经过加密的。但这不是什么密码，只是古老的龙语而已。', `MaleText_loc5`='黑鐵矮人認為這些石板被加密過。這不是什麼密碼，只是古老的龍族語言。', `MaleText_loc7`='Los Hierro Negro creían que esas tablillas estaban codificadas. Esto no se trata de ningún código, es la lengua antigua de los dragones.' WHERE `ID`=8227;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 서판을 읽어내려 갑니다. 한 번도 들어본 적 없는 소리가 의식 속에 울려 퍼집니다.', `MaleText_loc4`='%s开始阅读石板。某种从未听过的神秘声音在你耳边回荡。', `MaleText_loc5`='%s閱讀石板。某種未知的聲音在你耳邊回蕩。', `MaleText_loc7`='%s lee las tablillas. Unos sonidos desconocidos, que nunca habías oído, fluyen por tu mente.' WHERE `ID`=8228;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곰 우르산고우스에 대해 알려 주십시오.', `MaleText_loc4`='你能告诉我关于那只熊——乌萨苟斯的情况吗？', `MaleText_loc5`='你能告訴我關於那隻熊─烏薩苟斯的情況嗎?', `MaleText_loc7`='¿Qué puedes decirme sobre el oso Ursangous?', `FemaleText_loc1`='곰 우르산고우스에 대해 알려 주십시오.', `FemaleText_loc4`='你能告诉我关于那只熊——乌萨苟斯的情况吗？', `FemaleText_loc5`='你能告訴我關於那隻熊─烏薩苟斯的情況嗎?', `FemaleText_loc7`='¿Qué puedes decirme sobre el oso Ursangous?' WHERE `ID`=8229;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밤호랑이 샤둠브라에 대해 알려 주십시오.', `MaleText_loc4`='你能告诉我关于夜刃豹——猎影的情况吗？', `MaleText_loc5`='你能告訴我關於夜刃豹─薩杜布拉的情況嗎?', `MaleText_loc7`='¿Qué puedes decirme sobre el felino sable de la noche Shadumbra?', `FemaleText_loc1`='밤호랑이 샤둠브라에 대해 알려 주십시오.', `FemaleText_loc4`='你能告诉我关于夜刃豹——猎影的情况吗？', `FemaleText_loc5`='你能告訴我關於夜刃豹─薩杜布拉的情況嗎?', `FemaleText_loc7`='¿Qué puedes decirme sobre el felino Sable de la noche Shadumbra?' WHERE `ID`=8230;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='히포그리프 뾰족발톱에 대해 알려 주십시오.', `MaleText_loc4`='你能告诉我关于角鹰兽尖爪的情况吗？', `MaleText_loc5`='你能告訴我關於角鷹獸─沙普塔隆的情況嗎?', `MaleText_loc7`='¿Qué puedes decirme sobre el hipogrifo Garfafilada?', `FemaleText_loc1`='히포그리프 뾰족발톱에 대해 알려 주십시오.', `FemaleText_loc4`='你能告诉我关于角鹰兽尖爪的情况吗？', `FemaleText_loc5`='你能告訴我關於角鷹獸─沙普塔隆的情況嗎?', `FemaleText_loc7`='¿Qué puedes decirme sobre el hipogrifo Garfafilada?' WHERE `ID`=8231;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그 곰은 갈퀴자국 토굴길 근처의 길을 서성거린답니다. 갈퀴자국 토굴길은 미스트랄 호수와 실바람 산장에 있는 얼라이언스 전초기지 서쪽에 있지요. 그 곰은 잿빛 골짜기 사냥 대회의 동물 세 마리 중에서 가장 쉬운 녀석입니다. 그러니 당신은 녀석과 꼭 한 번은 만나겠지요. 쉽게 볼 놈은 아니란 걸 기억하시고 조심하시기 바랍니다. 사실 그 녀석은 잿빛 골짜기와 돌발톱 산맥 사이를 오가는 여행자들에게 위협이 되는 존재이거든요.', `FemaleText_loc4`='这只熊漫步在一条靠近石爪小径的路上，在密斯特拉湖和联盟的银风避难所正西方。虽然他是你在灰谷遇到的三个动物之中最好对付的一个，对他也不能掉以轻心。他的出现对于逗留在灰谷和石爪山脉之间的旅客来说是一个巨大的威胁。', `FemaleText_loc5`='這隻熊漫步在一條靠近深爪小徑的路上，在密斯特拉湖和聯盟的銀風避難所正西方。雖然他是你在梣谷遇到的三個動物之中最好對付的一個，對他也不能掉以輕心。他的出現對於逗留在梣谷和石爪山脈之間的旅客來說是一個巨大的威脅。', `FemaleText_loc7`='Este oso vaga por un camino cercano a El Paso del Espolón, al oeste del Lago Mystral y la Avanzada de la Alianza del Refugio Brisa de Plata. Si bien es la criatura más dócil de las tres a las que te enfrentarás en la Caza de Vallefresno, no deberías subestimarlo. Su presencia es una amenaza constante para los viajeros que pasan por Vallefresno y Sierra Espolón.' WHERE `ID`=8232;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 밤호랑이는 나이트 엘프들과 그들의 동맹 사이에서는 유순하다는 소문이 있습니다. 그래서 더 가치 있는 사냥감이지요. 샤둠브라의 사냥길은 레인나무 은신처에서 바로 우리 서쪽 땅까지 이른답니다. 샤둠브라의 털은 송진빛이 돌며 그 속도를 절대 얕잡아 봐서는 안 됩니다.', `FemaleText_loc4`='这只夜刃豹传言在暗夜精灵和他们的同盟面前很驯服，这使她成为一个更有价值的对手。猎影的猎杀路线把她从瑞恩伍德居所赶到了我们的西方，最终在那里的正西方登陆。她的皮毛是沥青一般的颜色，而她的速度也不能低估。', `FemaleText_loc5`='這隻夜刃豹傳言在夜精靈和他們的盟友面前很馴服，這使她成為一個更有價值的對手。薩杜布拉的獵殺路線把她從林中樹居趕到了我們的西方，最後會在那邊的正西方登陸。她的皮毛是瀝青一般的顏色，而她的速度也不能低估。', `FemaleText_loc7`='Se rumorea que los Sables de la Noche son dóciles en presencia de los elfos de la noche y sus aliados, lo que los convierte en un oponente mucho más respetable. La ruta de caza de Shadumbra la lleva desde el Refugio de la Algaba hacia el oeste, para terminar en las tierras que quedan al oeste de aquí. Su piel es del color de la brea y su velocidad no se puede subestimar.' WHERE `ID`=8233;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잿빛 골짜기 사냥 대회에서 가장 어려운 상대인 뾰족발톱은 이 땅의 수호자라 주장하는 나이트 엘프들에 의해 자유로이 살고 있습니다. 뾰족발톱은 이곳의 남쪽 지역을 다니며 먹이를 사냥하고 있지요. 그들의 존재를 모르는 여행자들의 사지를 하나씩 찢어내는 것을 즐기며 말입니다.$B$B그런 짐승을 처치한다는 것은 대단한 소득일 것입니다. 이 짐승을 잡는 데 행운이 따르길 바랍니다!', `FemaleText_loc4`='作为灰谷猎场最强大的野兽，尖爪可以在这片大地自封的卫兵——暗夜精灵的陪伴下自由的漫步。尖爪在这里南部寻找猎物，尽情的撕裂着毫无防备的旅客。$B$B要想杀死这样一个野兽需要极大的努力，$n。我希望你在猎杀这个野兽时运气好一点！', `FemaleText_loc5`='作為梣谷獵場最強大的野獸，沙普塔隆可以在這片大地自封的守護者─夜精靈的陪伴下自由的漫步。沙普塔隆在這裡南部尋找獵物，盡情的撕裂著毫無防備的旅客。$B$B要想殺死這樣一個野獸需要極大的努力，$n。我希望你在獵殺這個野獸時運氣好一點!', `FemaleText_loc7`='La bestia más poderosa de todas las de la Caza de Vallefresno. Los guardianes autoproclamados de esta tierra, los elfos de la noche, permiten que Garfafilada vague a su libre albedrío por aquí. Garfafilada patrulla en busca de presas al sur de aquí, deleitándose en desgarrar los miembros de algún viajero desprevenido.$B$BAcabar con una bestia así es una gran hazaña, $n. ¡Te deseo buena suerte con la caza de esta criatura!' WHERE `ID`=8234;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='윈저, 그대는 그 예언 속에서 살아남던가? 궁금하군그래... 내가 묻는 연유는 내가 그대를 살려두지 않을 것이 불 보듯 뻔하기 때문이다. 지금 여기서 말이다!', `FemaleText_loc4`='我好奇的是……温德索尔，在那个幻象中，你最终有没有活下来？我之所以这样问，是因为我可以确保你今天死定了。就是现在。', `FemaleText_loc5`='真奇怪...溫德索爾，在幻象之中，你沒有死嗎?我之所以這樣問是因為我能肯定你已經死了。這是怎麼回事。', `FemaleText_loc7`='Muy curioso... Windsor, en esa visión, ¿sobrevivías? Solo lo pregunto porque lo único que puedo asegurar y aseguraré, es tu muerte. Aquí y ahora.' WHERE `ID`=8235;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 놀라서 입을 벌립니다.', `MaleText_loc4`='%s喘息着。', `MaleText_loc5`='%s喘息著。', `MaleText_loc7`='%s da un grito ahogado.' WHERE `ID`=8236;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 더러운 용 같으니! 경비병, 경비병! 이 괴물을 잡아라!', `MaleText_loc4`='龙！卫兵！卫兵！抓住这个怪物！', `MaleText_loc5`='污穢之龍!守衛!守衛!打敗那怪物!', `MaleText_loc7`='¡Dragón asqueroso! ¡Guardias! ¡Guardias! ¡Coged al monstruo!' WHERE `ID`=8237;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 비웃습니다.', `FemaleText_loc4`='%s笑起来。', `FemaleText_loc5`='%s大笑。', `FemaleText_loc7`='%s ríe.' WHERE `ID`=8238;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그래... 경비병들아, 내 품으로 오너라!', `FemaleText_loc4`='对……卫兵们，过来帮帮你们的主人！', `FemaleText_loc5`='是...守衛，過來幫幫你的主人!', `FemaleText_loc7`='Sssí... ¡Guardias, vengan en ayuda de su señor!' WHERE `ID`=8239;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여러분, 빨리 앉으시오! 경주가 2분 안에 시작됩니다!', `MaleText_loc4`='大家请就座！比赛两分钟后开始！', `MaleText_loc5`='大家請就座!比賽兩分鐘後開始!', `MaleText_loc7`='¡Todo el mundo a su asiento! ¡La carrera comenzará en 2 minutos!' WHERE `ID`=8240;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경주가 1분 안에 시작됩니다!', `MaleText_loc4`='拉力赛将在1分钟之后开始！', `MaleText_loc5`='拉力賽將在1分鐘之後開始!', `MaleText_loc7`='¡La carrera de Fórmula Humo comenzará en 1 minuto!' WHERE `ID`=8241;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 가져온 것 좀 보라고! 자, 어서 마시자!', `MaleText_loc4`='看$n给我们带来了什么！我们畅饮吧！', `MaleText_loc5`='看$n給我們帶來了什麼!我們暢飲吧!', `MaleText_loc7`='¡Mirad lo que $n nos ha traído! ¡Todos a beber!' WHERE `ID`=8242;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하시오. 잿빛 골짜기 점령을 위한 최전선에 오신 걸 환영하오! 영웅이 되기 위한 임무를 구하러 왔다면 제대로 찾아 오신 겁니다. 나는 이곳에서 호드에 영광을 가져다줄 강한 $C|1을;를; 찾고 있었소이다.', `MaleText_loc4`='你好，$c。欢迎来到我们征服灰谷的前线！如果你在找事做的话，那么你算来对地方了。我总是在寻找体格健壮的$r去为部落赢得荣誉！', `MaleText_loc5`='你好$c--歡迎來到我們征服梣谷的前線!如果你在找事做的話，那麼你算來對地方了。我總是在尋找體格健壯的人來為部落帶來榮譽!', `MaleText_loc7`='Hola, $c. ¡Te doy la bienvenida a la primera línea de nuestra conquista de Vallefresno! Si estás buscando algo que hacer, has venido al lugar adecuado. Siempre necesito individuos sanos que ayuden a aumentar la gloria de la Horda.' WHERE `ID`=8243;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 술을 가져왔다! 놀아 보자!', `MaleText_loc4`='$n给我们带酒来了！我们狂欢吧！', `MaleText_loc5`='$n給我們帶酒來了!我們狂歡吧!', `MaleText_loc7`='¡$n nos ha traído bebida! ¡Fiesta!' WHERE `ID`=8244;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 위협적인 소리를 냅니다.', `MaleText_loc4`='%s发出了嘶嘶声。', `MaleText_loc5`='%s發出嘶嘶聲。', `MaleText_loc7`='%s silba.' WHERE `ID`=8245;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이것도 운명인가 윈저? 그대가 죽으러 왔다면 예언이 맞아 떨어졌군. 뒤틀린 황천에서 썩게 해주마! 얘들아, 이 귀찮은 벌레들을 마저 없애라. 볼바르, 그동안 꼭두각시로 잘 있어 주었다.', `FemaleText_loc4`='这是命运吗，温德索尔？如果你是赶来赴死的，那么预言已经实现了。愿你的思想在扭曲虚空里面腐烂。干掉其余爱管闲事的家伙，我的孩子们。伯瓦尔，你是一个令人满意的傀儡。', `FemaleText_loc5`='這是命運嗎，溫德索爾?如果你是從死亡中來的，那麼預言已經實現了。願你的思想在扭曲虛空腐爛。幹掉其餘愛管閒事的傢伙，孩子。伯瓦爾，你是一個令人滿意的傀儡。', `FemaleText_loc7`='¿Estaba esto predestinado, Windsor? Si era la muerte lo que habías venido a buscar, entonces la profecía se ha cumplido. Que tu conciencia se pudra en El Vacío Abisal. Acabad con el resto de estos insectos entrometidos, niños. Bolvar, has sido una placentera marioneta.' WHERE `ID`=8246;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폐하를 위해 싸워라! 오닉시아가 달아나게 해서는 안 된다!', `MaleText_loc4`='别让她逃了！', `MaleText_loc5`='別讓她逃了!', `MaleText_loc7`='¡NO LA DEJÉIS ESCAPAR!' WHERE `ID`=8247;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너희는 패배했다, 나약한 것들. 잘 있거라!', `FemaleText_loc4`='你们已经失败了，凡人……再见！', `FemaleText_loc5`='你已經失敗了，人類...再見!', `FemaleText_loc7`='Le habéis fallado, mortalesss... ¡Adiós!' WHERE `ID`=8248;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='레지널드... 미안하오.', `MaleText_loc4`='雷吉纳德……我……很抱歉。', `MaleText_loc5`='雷吉納德...我...很抱歉。', `MaleText_loc7`='Reginald... Yo... Lo siento.' WHERE `ID`=8249;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='볼... 볼바르... 메달...을... 사... 용...', `MaleText_loc4`='伯……伯瓦尔……勋章……用它……', `MaleText_loc5`='伯...伯瓦爾...大勳章...', `MaleText_loc7`='Bol... Bolvar... El medallón... Utilízalo...' WHERE `ID`=8250;
