UPDATE `locales_broadcast_text` SET `MaleText_loc1`='습득한 특성을 취소하고 싶습니다.', `MaleText_loc4`='我想要遗忘我的天赋。', `MaleText_loc5`='我想要遺忘我的天賦。', `MaleText_loc7`='Deseo olvidar mis talentos.', `FemaleText_loc1`='습득한 특성을 취소하고 싶습니다.', `FemaleText_loc4`='我想要遗忘我的天赋。', `FemaleText_loc5`='我想要遺忘我的天賦。', `FemaleText_loc7`='Deseo olvidar mis talentos.' WHERE `ID`=8271;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 알겠습니다.', `MaleText_loc4`='没错。', `MaleText_loc5`='是的。我願意。', `MaleText_loc7`='Sí, quiero.', `FemaleText_loc1`='네, 알겠습니다.', `FemaleText_loc4`='没错。', `FemaleText_loc5`='是的。我願意。', `FemaleText_loc7`='Sí, quiero.' WHERE `ID`=8272;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='습득한 특성을 취소하고 싶습니다.', `MaleText_loc4`='我想要遗忘我的天赋。', `MaleText_loc5`='我想要遺忘我的天賦。', `MaleText_loc7`='Deseo olvidar mis talentos.' WHERE `ID`=8273;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='습득한 특성을 취소하고 싶습니다.', `FemaleText_loc4`='我想要遗忘我的天赋。', `FemaleText_loc5`='我想要遺忘我的天賦。', `FemaleText_loc7`='Sí, deseo olvidar mis talentos.' WHERE `ID`=8274;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일로 오셨나요?', `MaleText_loc4`='我能为你做什么？', `MaleText_loc5`='我能為你做什麼?', `MaleText_loc7`='¿Qué quieres que haga por ti?', `FemaleText_loc1`='무슨 일로 오셨나요?', `FemaleText_loc4`='我能为你做什么？', `FemaleText_loc5`='我能為你做什麼?', `FemaleText_loc7`='¿Qué quieres que haga por ti?' WHERE `ID`=8275;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신처럼 많이 알고 있는 이에겐 나는 더 이상 가르칠 게 없소! 당신은 호드 일원이니까 오그리마에 있는 노그를 찾아가야 하오!', `MaleText_loc4`='我没有什么可以教你的啦！无论如何，不是每个人都像你能懂这么多知识！你需要跟奥格瑞玛的诺格谈谈。', `MaleText_loc5`='我沒有什麼可以教你的啦!無論如何，不是每個人都像你能懂這麼多知識!你需要跟奧格瑪的諾格談談。', `MaleText_loc7`='¡No tengo na más que enseñar! Vamos, no pa alguien que sabe tanto como yo. Ustedes, los de la Horda, tienen que hablar con Nogg en Orgrimmar.' WHERE `ID`=8276;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가서 물어 와!', `MaleText_loc4`='狂暴者，出击！', `MaleText_loc5`='狂怒者，出擊!', `MaleText_loc7`='¡Ragers, cógelo!' WHERE `ID`=8277;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 가자!', `MaleText_loc4`='好吧，我们出去吧！', `MaleText_loc5`='好吧，我們出去吧!', `MaleText_loc7`='¡Venga, en marcha!' WHERE `ID`=8278;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='감히 누가 은빛날개 전초기지를 공격하는 것이냐?', `FemaleText_loc4`='谁敢攻击银翼哨站？！？', `FemaleText_loc5`='誰敢攻擊銀翼哨站?!?', `FemaleText_loc7`='¡¿Quién osa atacar la Avanzada Ala de Plata?!' WHERE `ID`=8279;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은빛날개 전초기지는 우리 것이다!', `MaleText_loc4`='银翼是我们的！', `MaleText_loc5`='銀翼是我們的!', `MaleText_loc7`='¡Ala de Plata nos pertenece!' WHERE `ID`=8280;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가서 전초기지를 점령했다고 보고하라. 우리는 여기 남아있겠다.', `MaleText_loc4`='去汇报说我们的前哨沦陷了。我们要留下。', `MaleText_loc5`='回去報告說已經奪下了哨站。我們將會在此留守。', `MaleText_loc7`='Ve a informar de que la Avanzada ha sido conquistada. Nosotros nos quedaremos aquí.' WHERE `ID`=8281;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 준비하라. 저기만 돌아가면 은빛날개 전초기지다.', `MaleText_loc4`='准备好了。银翼正在发狂呢。', `MaleText_loc5`='最好準備。銀翼快要抓狂了。', `MaleText_loc7`='Preparaos. Ala de Plata está pasada la curva.' WHERE `ID`=8282;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드를 위하여!', `MaleText_loc4`='为了部落！', `MaleText_loc5`='為了部落!', `MaleText_loc7`='¡Por la Horda!' WHERE `ID`=8283;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 준비됐나?', `MaleText_loc4`='都准备好了吗？', `MaleText_loc5`='都準備好了嗎?', `MaleText_loc7`='¿Todo el mundo preparado?' WHERE `ID`=8284;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신을 해칠 생각은 없어요. 나는 가시멧돼지들을 염탐하면서 녀석들의 동태를 살피고 있어요. 동료가 이 지역에서 뭔가 이상한 암흑의 기운이 뿜어져 나오는 것이 느껴진다고 해서 조사하러 왔는데, 우려할만한 사실을 알아냈어요.$B$B마법에 능한 언데드 외교관이 있는 것 같아요. 포세이큰은 아닌 것 같고... 그보다 더 악한 자라고 생각돼요.', `FemaleText_loc4`='我不会伤害你的。我在监视野猪人并记录他们的活动。我的人民注意到了某些奇怪的事情……某种黑暗的气息从这个地区中散播出来。我是前来调查此事的，而我的发现很令人不安。$B$B似乎有一个很善于使用奥术魔法的亡灵外交官在附近。我不相信他也是被遗忘者……我认为情况比这更糟糕。', `FemaleText_loc5`='我不會傷害你的。我在監視野豬人並記錄他們的活動。我的人民注意到了某些奇怪的事情─黑暗的彌漫─從這個地區來的。我是來調查的，而我的發現很令人不安。$B$B似乎有一個很善於秘法的亡靈外交官。我不相信他也是被遺忘者...我認為更壞。', `FemaleText_loc7`='No quiero hacerte daño. Estoy observando a los jabaespines y tomando notas de sus actividades. Mi pueblo ha notado algo extraño, como una emanación u oscuridad, que salía de esta zona. Vine a investigar y, lo que he descubierto, es muy perturbador.$B$BParece ser que hay un diplomático no-muerto que domina en gran medida los poderes arcanos. No creo que sea uno de los Renegados... Creo que se trata de algo peor.' WHERE `ID`=8285;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오늘은 운이 아주 좋군. 평소엔 먹이를 찾으려면 둥지에서 나가야 하는데 말이야.', `FemaleText_loc4`='真是走运。通常我必须离开窝才能找到食物。', `FemaleText_loc5`='真是幸運。通常我為了覓食就必須離開窩。', `FemaleText_loc7`='Qué casualidad. Generalmente, debo salir de mi guarida para poder comer.' WHERE `ID`=8286;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네 주제를 알아라, 나약한 생명체여!', `FemaleText_loc4`='要明白你的处境，凡人！', `FemaleText_loc5`='要明白你的處境，凡人!', `FemaleText_loc7`='¡Aprende a saber estar, mortal!' WHERE `ID`=8287;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='쓸데없이 힘을 쓰는 것도 지루하군. 네 녀석들 머리 위에서 모조리 불살라 주마!', `FemaleText_loc4`='这毫无意义的行动让我很厌烦。我会从上空把你们都烧成灰！', `FemaleText_loc5`='這毫無意義的行動讓我很厭煩。我會從上空把你們都燒成灰!', `FemaleText_loc7`='Este ejercicio sin sentido me aburre. ¡Los incineraré a todos desde arriba!' WHERE `ID`=8288;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 치명적인 마법을 많이 알고 있긴 하지만 나한테는 아직도 부족해 보이는군. $n, 훈련을 더 받아야 할 것 같네.', `MaleText_loc4`='你知道的已经够危险了，但是对我来说你看起来还需要训练，$n。', `MaleText_loc5`='你知道的已經夠危險了，但是對我來說你看起來還需要訓練$n。', `MaleText_loc7`='Sabes lo suficiente como para ser $gpeligroso:peligrosa;, pero a mí me parece que todavía necesitas instrucción, $n.', `FemaleText_loc1`='자네가 치명적인 마법을 많이 알고 있긴 하지만 나한테는 아직도 부족해 보이는군. $n, 훈련을 더 받아야 할 것 같네.', `FemaleText_loc4`='你知道的已经够危险了，但是对我来说你看起来还需要训练，$n。', `FemaleText_loc5`='你知道的已經夠危險了，但是對我來說你看起來還需要訓練$n。', `FemaleText_loc7`='Sabes lo suficiente como para ser $gpeligroso:peligrosa;, pero a mí me parece que todavía necesitas instrucción, $n.' WHERE `ID`=8289;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='혼이 더 나야 정신을 차리겠구나!', `FemaleText_loc4`='看起来需要再给你一次教训，凡人！', `FemaleText_loc5`='看起來需要再給你一次教訓，凡人!', `FemaleText_loc7`='¡Parece ser que van a necesitar otra lección, mortales!' WHERE `ID`=8290;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 우리가 제어하는 힘을 맘대로 조작할 정도로 의지가 강하지 않네, $c 친구.', `MaleText_loc4`='你的意志不足以操纵我们控制的军队，$c。', `MaleText_loc5`='你的意志不足以操縱我們控制的軍隊$c。', `MaleText_loc7`='Tu voluntad no es lo suficientemente fuerte como para manipular las fuerzas que controlamos, $c.', `FemaleText_loc1`='자네는 우리가 제어하는 힘을 맘대로 조작할 정도로 의지가 강하지 않네, $c 친구.', `FemaleText_loc4`='你的意志不足以操纵我们控制的军队，$c。', `FemaleText_loc5`='你的意志不足以操縱我們控制的軍隊$c。', `FemaleText_loc7`='Tu voluntad no es lo suficientemente fuerte como para manipular las fuerzas que controlamos, $c.' WHERE `ID`=8291;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흑마법사로서 더 큰 지식을 갈망합니다.', `MaleText_loc4`='我喜欢学习更多的关于术士的知识。', `MaleText_loc5`='我追求高超的術士之道。', `MaleText_loc7`='Yo ansío un conocimiento más profundo de la brujería.', `FemaleText_loc1`='흑마법사로서 더 큰 지식을 갈망합니다.', `FemaleText_loc4`='我喜欢学习更多的关于术士的知识。', `FemaleText_loc5`='我追求高超的術士之道。', `FemaleText_loc7`='Yo ansío un conocimiento más profundo de la brujería.' WHERE `ID`=8292;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대지모신 앞에서 대체 내가 어떻게 자네를 더 훈련시켜 줄 수 있겠나, $n?', `MaleText_loc4`='$n，我如何才能在大地母亲的心目中继续你的深造呢？', `MaleText_loc5`='$n，我如何才能在大地之母的心目中繼續你的深造呢?', `MaleText_loc7`='$n, ¿cómo puedo fomentar tu instrucción a los ojos de la Madre Tierra?', `FemaleText_loc1`='대지모신 앞에서 대체 제가 어떻게 당신을 더 훈련시켜 줄 수 있겠습니까, $n 님?', `FemaleText_loc4`='$n，我如何才能在大地母亲的心目中继续你的深造呢？', `FemaleText_loc5`='$n，我如何才能在大地之母的心目中繼續你的深造呢?', `FemaleText_loc7`='$n, ¿cómo puedo fomentar tu instrucción a los ojos de la Madre Tierra?' WHERE `ID`=8293;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대지모신의 길에는 여러 가지가 있지. 선조들께서 보살펴 주시기를 비네, $c|1이여;여;.', `MaleText_loc4`='这些都是大地之母走过的道路。愿你的祖先保佑你$c。', `MaleText_loc5`='這些都是大地之母走過的道路。願你的祖先保佑你們$c。', `MaleText_loc7`='Muchos son los caminos de la Madre Tierra. Que tus ancestros te protejan, $c.', `FemaleText_loc1`='대지모신의 길에는 여러 가지가 있지요. 선조들께서 보살펴 주시기를 빕니다, $c|1이여;여;.', `FemaleText_loc4`='我不会伤害你的。我在监视野猪人并记录他们的活动。我的人民注意到了某些奇怪的事情——黑暗的弥漫——从这个地区来的。我是来调查的，而我的发现很令人不安。$B$B似乎有一个很善于奥术的亡灵外交官。我不相信他也是被遗忘者……我认为事态更坏了。', `FemaleText_loc5`='這些都是大地之母走過的道路。願你的祖先保佑你們$c。', `FemaleText_loc7`='Muchos son los caminos de la Madre Tierra. Que tus ancestros te protejan, $c.' WHERE `ID`=8294;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대지모신의 뜻을 더 잘 이해할 수 있도록 드루이드 훈련을 더 받고 싶습니다.', `MaleText_loc4`='我想接受更多的德鲁伊训练，更好地理解大地之母的意愿。', `MaleText_loc5`='我想接受更多的德魯伊訓練，更好地理解大地之母的意願。', `MaleText_loc7`='Persigo una instrucción druida más profunda para poder comprender mejor la voluntad de la Madre Tierra.', `FemaleText_loc1`='대지모신의 뜻을 더 잘 이해할 수 있도록 드루이드 훈련을 더 받고 싶습니다.', `FemaleText_loc4`='我想接受更多的德鲁伊训练，更好地理解大地之母的意愿。', `FemaleText_loc5`='我想接受更多的德魯伊訓練，更好地理解大地之母的意願。', `FemaleText_loc7`='Persigo una instrucción druida más profunda para poder comprender mejor la voluntad de la Madre Tierra.' WHERE `ID`=8295;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흑마법사 지식을 더 얻고자 내 앞에서 자신을 낮추다니, 아주 현명한 친구로군, $n.', `MaleText_loc4`='你想学习更多的术士知识，那你还是放聪明点，在我面前表现得谦卑一些，$n。', `MaleText_loc5`='為了學習更多的術士知識，你在我面前表現謙卑是很明智的做法，$n。', `MaleText_loc7`='Es una sabia decisión humillarte ante mí, $n, en tu deseo de aumentar tu conocimiento de la brujería.', `FemaleText_loc1`='흑마법사 지식을 더 얻고자 내 앞에서 자신을 낮추다니, 아주 현명한 친구로군, $n.', `FemaleText_loc4`='你想学习更多的术士知识，那你还是放聪明点，在我面前表现得谦卑一些，$n。', `FemaleText_loc5`='為了學習更多的術士知識，你在我面前表現謙卑是很明智的做法，$n。', `FemaleText_loc7`='Es una sabia decisión humillarte ante mí, $n, en tu deseo de aumentar tu conocimiento de la brujería.' WHERE `ID`=8296;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 같은 $c에게 낭비할 시간은 없네.', `MaleText_loc4`='我没有时间浪费在像你这样的人身上$c。', `MaleText_loc5`='我沒有時間浪費在像你這樣的人身上$c。', `MaleText_loc7`='No tengo tiempo que perder con los de tu clase, $c.', `FemaleText_loc1`='자네 같은 $c에게 낭비할 시간은 없네.', `FemaleText_loc4`='我没有时间浪费在像你这样的人身上$c。', `FemaleText_loc5`='我沒有時間浪費在像你這樣的人身上$c。', `FemaleText_loc7`='No tengo tiempo que perder con los de tu clase, $c.' WHERE `ID`=8297;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가르침을 내려 주시기 바랍니다.', `MaleText_loc4`='我服从安排接受进一步的训练，我的主人。', `MaleText_loc5`='我聽從安排，只為得到更多訓練。', `MaleText_loc7`='Me presento para recibir más instrucción, maestro.', `FemaleText_loc1`='가르침을 내려 주시기 바랍니다.', `FemaleText_loc4`='我服从安排接受进一步的训练，我的主人。', `FemaleText_loc5`='我聽從安排，只為得到更多訓練。', `FemaleText_loc7`='Me presento para recibir más instrucción, maestro.' WHERE `ID`=8298;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서 있는 모습만 봐도 전사가 아닌 걸 알겠군.$B$B저리 가서 좀 더 안전한 일이나 독서를 하는 게 어떻겠소?', `MaleText_loc4`='从你的站姿我可以看出你不是战士。$B$B你为什么不做点安全的事，比如读书什么的。', `MaleText_loc5`='從你的站姿我可以看出你不是戰士。$B$B你為什麼不做點安全的事，比如讀書什麼的。', `MaleText_loc7`='Por tu postura, puedo decir que no eres $gun guerrero:una guerrera;. $B$B¿Por qué no te vas a hacer algo más seguro, como leer un libro o algo así?', `FemaleText_loc1`='서 있는 모습만 봐도 전사가 아닌 걸 알겠군.$B$B저리 가서 좀 더 안전한 일이나 독서를 하는 게 어떻겠소?', `FemaleText_loc4`='从你的站姿我可以看出你不是战士。$B$B你为什么不做点安全的事，比如读书什么的。', `FemaleText_loc5`='從你的站姿我可以看出你不是戰士。$B$B你為什麼不做點安全的事，比如讀書什麼的。', `FemaleText_loc7`='Por tu postura, puedo decir que no eres $gun guerrero:una guerrera;. $B$B¿Por qué no te vas a hacer algo más seguro, como leer un libro o algo así?' WHERE `ID`=8299;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠은 당신 같은 $c|1을;를; 원하지 않소. 그만 재잘대고 내 눈앞에서 썩 사라지시오!', `MaleText_loc4`='黑暗没有拥抱你这样的$c。别说废话，从我视线中消失吧！滚！', `MaleText_loc5`='黑暗並沒有包圍你，$c。別說廢話，從我視線中消失吧!滾!', `MaleText_loc7`='La oscuridad no te abraza, $c. ¡Déjate de chácharas y sal de mi vista! ¡Lárgate!', `FemaleText_loc1`='어둠은 당신 같은 $c|1을;를; 원하지 않습니다. 그만 재잘대고 내 눈앞에서 썩 사라지세요!', `FemaleText_loc4`='黑暗没有拥抱你这样的$c。别说废话，从我视线中消失吧！滚！', `FemaleText_loc5`='黑暗並沒有包圍你，$c。別說廢話，從我視線中消失吧!滾!', `FemaleText_loc7`='La oscuridad no te abraza, $c. ¡Déjate de chácharas y sal de mi vista! ¡Lárgate!' WHERE `ID`=8300;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신에게 함유된 흑마법 소질을 측정해보니, 그 분량이 충분하지 않군요. 제가 더 이상 얘기를 나눌 이유가 없어요. 이만 가보세요.', `MaleText_loc4`='恐怕你给我的份额太低了，我可不愿跟你废话了。请走吧。', `MaleText_loc5`='你的黑暗指數真的是低到會讓我不屑繼續與你對話。請走吧。', `MaleText_loc7`='Me temo que tu grado de oscuridad no es suficiente como para que me moleste en seguir hablando contigo. Vete de aquí, por favor.', `FemaleText_loc1`='당신에게 함유된 흑마법 소질을 측정해보니, 그 분량이 충분하지 않군요. 제가 더 이상 얘기를 나눌 이유가 없어요. 이만 가보세요.', `FemaleText_loc4`='恐怕你给我的份额太低了，我可不愿跟你废话了。请走吧。', `FemaleText_loc5`='你的黑暗指數真的是低到會讓我不屑繼續與你對話。請走吧。', `FemaleText_loc7`='Me temo que tu grado de oscuridad no es suficiente como para que me moleste en seguir hablando contigo. Vete de aquí, por favor.' WHERE `ID`=8301;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 전사가 아닌데... 내 훈련 방식은 하루도 견뎌 내지 못하게 생겼군!$B$B$c 주제에 자기가 전사쯤이나 되는 줄 알다니, 허 그것 참!', `MaleText_loc4`='你不是战士……你为什么在我的训练课程中一天都坚持不下去！$B$B一个以为自己是战士的$c，哈哈！', `MaleText_loc5`='你不是戰士...你在我的訓練課程中會連一天都堅持不下去的!$B$B認為$g他是:她是;一個戰士的$c。哈!', `MaleText_loc7`='No eres $gun guerrero:una guerrera;... ¡Pero si no durarías ni un día siguiendo mi régimen de instrucción! $B$B¡$gUn:Una:c; $c que se cree ser $gun guerrero:una guerrera;! ¡Ja!', `FemaleText_loc1`='당신은 전사가 아닌데... 내 훈련 방식은 하루도 견뎌 내지 못하게 생겼군!$B$B$c 주제에 자기가 전사쯤이나 되는 줄 알다니, 허 그것 참!', `FemaleText_loc4`='你不是战士……你为什么在我的训练课程中一天都坚持不下去！$B$B一个以为自己是战士的$c，哈哈！', `FemaleText_loc5`='你不是戰士...你在我的訓練課程中會連一天都堅持不下去的!$B$B認為$g他是:她是;一個戰士的$c。哈!', `FemaleText_loc7`='No eres $gun guerrero:una guerrera;... ¡Pero si no durarías ni un día siguiendo mi régimen de instrucción! $B$B¡$gUn:Una:c; $c que se cree ser $gun guerrero:una guerrera;! ¡Ja!' WHERE `ID`=8302;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대에게는 전사의 혼이 보이지 않는군요. 나는 그대 같은 $c에게 가르칠 만한 것이 없습니다.', `MaleText_loc4`='孩子，我看不出你具备战士的精神。我不会训练你这样的$c的。', `MaleText_loc5`='孩子，我看不出你具備戰士的精神。我不會訓練你這樣的$c的。', `MaleText_loc7`='No veo el espíritu del guerrero en ti. No tengo enseñanzas que puedan servir a $gun:una; $c como tú.', `FemaleText_loc1`='그대에게는 전사의 혼이 보이지 않는군요. 나는 그대 같은 $c에게 가르칠 만한 것이 없습니다.', `FemaleText_loc4`='孩子，我看不出你具备战士的精神。我不会训练你这样的$c的。', `FemaleText_loc5`='孩子，我看不出你具備戰士的精神。我不會訓練你這樣的$c的。', `FemaleText_loc7`='No veo el espíritu del guerrero en ti. No tengo enseñanzas que puedan servir a $gun:una; $c como tú.' WHERE `ID`=8303;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 심연의 돌을 보호하기 위해 나타납니다!', `MaleText_loc4`='%s现身保护深渊之石！', `MaleText_loc5`='%s冒出來保護深淵之石!', `MaleText_loc7`='%s emerge para proteger la piedra de las profundidades.' WHERE `ID`=8304;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='애처롭군. 고작 그 정도밖에 안 된다면 너희 둘은 여기서 훈련받을 자격이 없다.', `MaleText_loc4`='真可怜。如果这就是你们的最佳表现，你们俩的训练算是白费了。', `MaleText_loc5`='真可憐。如果這就是你們的最佳表現，你們倆的訓練算是白費了。', `MaleText_loc7`='Patético. Si eso es lo mejor que podéis hacer, no os merecéis la instrucción que estáis recibiendo aquí.' WHERE `ID`=8305;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리스타, 언데드 포로들을 불러내라.', `MaleText_loc4`='利斯塔，召唤亡灵俘虏。', `MaleText_loc5`='利斯塔，召喚亡靈俘虜。', `MaleText_loc7`='Lysta, invoca a los cautivos no-muertos.' WHERE `ID`=8306;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리스타, 누더기골렘을 데려오너라!', `MaleText_loc4`='利斯塔，冲啊……憎恶！', `MaleText_loc5`='利斯塔，衝啊...憎惡!', `MaleText_loc7`='Lysta, invoca... ¡a la abominación!' WHERE `ID`=8307;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장님, 부디 당신의 지혜를 제게도 나눠 주십시오.', `MaleText_loc4`='战争之王，请将你的智慧与我共享。', `MaleText_loc5`='大酋長，請讓我分享你的智慧。', `MaleText_loc7`='Por favor, comparte tu sabiduría conmigo, Jefe de Guerra.', `FemaleText_loc1`='대족장님, 부디 당신의 지혜를 제게도 나눠 주십시오.', `FemaleText_loc4`='战争之王，请将你的智慧与我共享。', `FemaleText_loc5`='大酋長，請讓我分享你的智慧。', `FemaleText_loc7`='Por favor, comparte tu sabiduría conmigo, Jefe de Guerra.' WHERE `ID`=8308;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으스러진 손은 검은바위 요새 위쪽 곳곳에 첩자들을 파견할 수 있었지. 정보 수집 절차가 느리긴 했지만 보고 그냥 넘길 수 없는 발견을 했다.', `MaleText_loc4`='碎手已经在黑石的大本营中安插了数名间谍。尽管信息收集的过程已经慢了下来，但是我们发现了一些不容忽略的现象。', `MaleText_loc5`='破碎之手已經在黑石的大本營中安插了數名間諜。儘管資訊收集的過程已經慢了下來，但是我們發現了一些不容忽略的現象。', `MaleText_loc7`='La Mano Destrozada ha colocado espías en la ciudadela superior de Roca Negra. Si bien el proceso de recogida de información ha sido lento, hemos hecho descubrimientos que no podemos desoír.' WHERE `ID`=8309;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 발견 말씀입니까?', `MaleText_loc4`='有什么发现？', `MaleText_loc5`='有什麼發現?', `MaleText_loc7`='¿Qué descubrimientos?', `FemaleText_loc1`='어떤 발견 말씀입니까?', `FemaleText_loc4`='有什么发现？', `FemaleText_loc5`='有什麼發現?', `FemaleText_loc7`='¿Qué descubrimientos?' WHERE `ID`=8310;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은용군단의 세력이 불타는 평원의 경계를 넘어 스톰윈드 왕국까지 퍼져나갔던 것 같아! 그 찬탈자가 발각되어 축출된 것이지.', `MaleText_loc4`='似乎黑龙的势力范围已经超越了燃烧平原，扩展到暴风城了！人们揭下了篡位者的面具并将他流放出境。', `MaleText_loc5`='似乎黑龍軍團的勢力範圍已經超越了燃燒平原，擴展到暴風城了!人們揭下了篡位者的面具並將他流放出境。', `MaleText_loc7`='La influencia del Vuelo Negro se extendió más allá de las fronteras de las Estepas Ardientes y consiguió llegar al mismísimo Reino de Ventormenta. Desde entonces, la usurpadora ha sido desenmascarada y derrocada.' WHERE `ID`=8311;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='찬탈자라고요?', `MaleText_loc4`='篡位者？', `MaleText_loc5`='篡位者?', `MaleText_loc7`='¿Usurpadora?', `FemaleText_loc1`='찬탈자라고요?', `FemaleText_loc4`='篡位者？', `FemaleText_loc5`='篡位者?', `FemaleText_loc7`='¿Usurpadora?' WHERE `ID`=8312;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래. 검은용군단의 여왕이 속임수를 써서 스스로 인간 왕궁의 일원으로 가장했던 거야. 더 끔찍한 사실은 그 용이 현재 스톰윈드의 대영주 볼바르 폴드라곤을 마음대로 조종했다는 거지.$B$B그렇게 터무니없는 군사 전략을 취한 것도 이해가 가기는 한다네. 최근 얼라이언스의 움직임을 보면서 우리 모두 언제 일이 터질지 궁금해 했거든. 이제야 검은용군단이 얼라이언스의 내부부터 무너뜨리려고 했던 거라는 걸 알게 됐지.', `MaleText_loc4`='真的。黑龙之母运用幻象和欺诈术将自己伪装成贵族法庭的成员。更糟糕的是，眼下，她似乎已经控制了暴风城的伯瓦尔·弗塔根公爵。$B$B做出这样愚蠢的军事决定不足为奇。联盟军队最近的行动令我们头疼。现在我们知道，黑龙正试图分裂帝国——从内部分裂它。', `MaleText_loc5`='真的。黑龍公主運用幻影和欺詐術將自己偽裝成貴族法庭的成員。更糟糕的是，現在，她似乎已經控制了暴風城的大領主伯瓦爾·弗塔根。$B$B做出這樣愚蠢的軍事決定不足為奇。聯盟軍隊最近的行動令我們頭疼。現在我們知道，黑龍正試圖分裂帝國─從內部分裂它。', `MaleText_loc7`='Sí. La madre de linaje del Vuelo Negro utilizó ilusión y trucos para disfrazarse como un miembro de la corte real. Peor aún, logró controlar al actual alto señor de Ventormenta, Bolvar Fordragón.$B$BNo es sorprendente que se hayan tomado unas decisiones militares tan estúpidas. Los últimos movimientos de las tropas de la Alianza nos dejaron estupefactos. Pero ahora comprendemos que el Vuelo Negro pretendía dividir el imperio, destruirlo desde dentro.' WHERE `ID`=8313;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장님, 주제넘은 말인 줄 압니다만, 얼라이언스 녀석들이 무너지도록 내버려두면 좋지 않습니까? 그러면 우리 호드의 지위가 더욱 굳건해지지 않을까요?', `MaleText_loc4`='恕我直言，统帅大人--为什么不消灭他们？难道这不会巩固我们的地位吗？', `MaleText_loc5`='恕我直言，大酋長--為什麼不消滅他們?難道這不會鞏固我們的地位嗎?', `MaleText_loc7`='Con todo el respeto, Jefe de Guerra... ¿Por qué no dejar que sean destruidos? ¿No reforzaría eso nuestra posición?', `FemaleText_loc1`='대족장님, 주제넘은 말인 줄 압니다만, 얼라이언스 녀석들이 무너지도록 내버려두면 좋지 않습니까? 그러면 우리 호드의 지위가 더욱 굳건해지지 않을까요?', `FemaleText_loc4`='恕我直言，统帅大人--为什么不消灭他们？难道这不会巩固我们的地位吗？', `FemaleText_loc5`='恕我直言，大酋長--為什麼不消滅他們?難道這不會鞏固我們的地位嗎?', `FemaleText_loc7`='Con todo el respeto, Jefe de Guerra... ¿Por qué no dejar que sean destruidos? ¿No reforzaría eso nuestra posición?' WHERE `ID`=8314;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<소리 내어 웃는 스랄>$B$B$R|1이여;여;, 자넨 아직 배울 게 많군.$B$B하긴 아주 오래전에 벌어진 전쟁과 유혈 충돌을 알기엔 자네는 너무 젊지... 우리 종족이 짊어졌던 굴레와 저주도 모르겠지.$B$B지금 얼라이언스와 우리의 관계는 아주 미묘하다네. 자잘한 충돌과 전투가 일어나고는 있지만 그래도 평화가 유지되고 있지 않는가? 우리가 수천 년 동안이나 누리지 못했던 그 평화 말이야. 이 평화를 저버리고 다시 혼돈의 불덩어리 속으로 뛰어들어야 하나? 모든 것이 파멸될 때까지 절대 멈추지 않을 그 혼돈 속으로?', `MaleText_loc4`='<萨尔笑了。>$B$B还有这么多要学的，$r。$B$B你太年轻了，记不得多年前的战争和流血。记不得我们的人民所承受的诅咒的重压。$B$B我们现在与联盟的形势很脆弱。小冲突和小规模战斗时常发生，但是仍有和平--我们的人民数千年来未有过的和平。你愿放弃这个并把我们再次投入这片混沌中去面对一个新的敌人吗？这个敌人在毁灭我们之前是不会停手的。', `MaleText_loc5`='<索爾笑了。>$B$B還有這麼多要學的，$r。$B$B你太年輕了，記不得多年前的戰爭和流血。記不得我們的人民所承受的詛咒的重壓。$B$B我們現在與聯盟的形勢很脆弱。小衝突和小規模戰鬥時常發生，但是仍有和平--我們的人民數千年來未有過的和平。你願放棄這個並把我們再次投入這片混沌中去面對一個新的敵人嗎?這個敵人在毀滅我們之前是不會停手的。', `MaleText_loc7`='<Thrall ríe.>$B$BTodavía te queda mucho por aprender, $r.$B$BEres demasiado joven para recordar las guerras y el derramamiento de sangre del pasado. Demasiado joven para recordar la carga de la maldición que tuvo que soportar nuestro pueblo.$B$BAhora mismo, nuestra posición con la Alianza es bastante endeble. Hay escaramuzas y pequeñas batallas de vez en cuando, pero tenemos paz... algo que nuestro pueblo no había visto en milenios. ¿Sacrificarías todo eso y nos lanzarías a las fauces del caos otra vez contra un nuevo enemigo? ¿Uno que no descansaría hasta que fuésemos destruidos?' WHERE `ID`=8315;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그... 그런 생각은 미처 하지 못했습니다, 대족장님.', `MaleText_loc4`='我……我可不这样想，战争之王。', `MaleText_loc5`='我...我可不這樣想，大酋長。', `MaleText_loc7`='Ehh... No lo había pensado así, Jefe de Guerra.', `FemaleText_loc1`='그... 그런 생각은 미처 하지 못했습니다, 대족장님.', `FemaleText_loc4`='我……我可不这样想，战争之王。', `FemaleText_loc5`='我...我可不這樣想，大酋長。', `FemaleText_loc7`='Ehh... No lo había pensado así, Jefe de Guerra.' WHERE `ID`=8316;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 그랬겠지, $n. 자네를 나무라는 것은 아니야. 나도 젊었을 때는 그랬거든. 충동적이고, 반항적이고... 게다가 사고에 일관성이라고는 하나도 찾아볼 수 없을 때가 많았지! 난 이제 더 이상 그런 성깔을 부릴 수가 없다네.$B$B휴, 넋두리는 그만하도록 하지. 자네에게 맡길 임무가 있네. 목숨을 걸어도 성공을 장담 못 하는 위험한 임무야.', `MaleText_loc4`='不，$n，你没有。我没找你茬，但是你跟年幼的我非常相似：冲动、叛逆、思维缺乏连贯性！这些特点在我身上已经荡然无存。$B$B悲伤够了。$R，我有个任务要你完成；或许你会在执行任务过程中丧命。', `MaleText_loc5`='不，$n，你沒有。我沒找你茬，但是你跟年幼的我非常相似:衝動、叛逆、思維缺乏連貫性!這些特點在我身上已經蕩然無存。$B$B悲傷夠了。$R，我有個任務要你完成;或許你會在執行任務過程中喪命。', `MaleText_loc7`='No, $n, por supuesto que no. Sin embargo, no te culpo, ya que tu mente se asemeja a la mía cuando era joven: impetuosa, rebelde y, a menudo, ¡sin ningún pensamiento coherente! Unos lujos que ya no puedo permitirme.$B$BPero basta de lamentarme. $R, tengo un trabajo para ti. Uno al que quizás no sobrevivas.' WHERE `ID`=8317;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장님! 명령만 내리십시오. 제 목숨은 대족장님의 인도가 없이는 의미가 없습니다.', `MaleText_loc4`='我活着就是为了为战争之王服务！没有你的指导，我的生活将空虚而无意义。', `MaleText_loc5`='我活著就是為了為大酋長服務!沒有你的指導，我的生活將空虛而無意義。', `MaleText_loc7`='¡Solo vivo para servir, Jefe de Guerra! Mi vida está vacía y carece de significado si no te tengo de guía.', `FemaleText_loc1`='대족장님! 명령만 내리십시오. 제 목숨은 대족장님의 인도가 없이는 의미가 없습니다.', `FemaleText_loc4`='我活着就是为了为战争之王服务！没有你的指导，我的生活将空虚而无意义。', `FemaleText_loc5`='我活著就是為了為大酋長服務!沒有你的指導，我的生活將空虛而無意義。', `FemaleText_loc7`='¡Solo vivo para servir, Jefe de Guerra! Mi vida está vacía y carece de significado si no te tengo de guía.' WHERE `ID`=8318;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<소리 내어 웃는 스랄>$B$B잘 기억해 두지. 자, $n. 내 말을 잘 듣게. 검은용군단의 여왕인 오닉시아가 스톰윈드의 권력층에서 밀려났네. 그 용은 탈출해서 먼지진흙 습지대에 있는 자기 둥지로 도망갔지.$B$B우리 호드의 수도와 그렇게 가까운 곳에서 살게 놔둘 수는 없어! 당하기 전에 우리가 먼저 쳐야 해!$B$B$n, 오닉시아를 처치하게.', `MaleText_loc4`='<萨尔笑了。>$B$B注意……现在专心些，$n。黑龙的母亲，奥妮克希亚，从她在暴风城的权位上被推翻了。她已经逃到她在尘泥沼泽的窝里。$B$B她不能生活在离我们的首都这么近的地方。我们必须先发制人！$B$B我想要消灭她，$n。', `MaleText_loc5`='<索爾笑著。>$B$B瞭注意...現在專心些，$n。黑龍公主，奧妮克希亞，被逐出了她原本在暴風城一帶的勢力範圍。她已經逃到她在塵泥沼澤的窩裡。$B$B她不能生活在離我們的首都這麼近的地方。我們必須先發制人!$B$B我想要消滅她，$n。', `MaleText_loc7`='<Thrall ríe.>$B$BLo tendré en cuenta... Ahora presta atención, $n. La madre de linaje del Vuelo Negro, Onyxia, ha perdido su posición de poder en Ventormenta. Ha escapado. Huyó a su guarida en el Marjal Revolcafango.$B$BNo podemos permitir que viva tan cerca de nuestras capitales. ¡Tenemos que atacar antes de ser atacados!$B$BQuiero que la destruyas, $n.' WHERE `ID`=8319;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지당한 말씀이십니다, 대족장님!', `MaleText_loc4`='遵命，酋长！', `MaleText_loc5`='當然，大酋長!', `MaleText_loc7`='¡Sí, Jefe de Guerra!', `FemaleText_loc1`='지당한 말씀이십니다, 대족장님!', `FemaleText_loc4`='遵命，酋长！', `FemaleText_loc5`='當然，大酋長!', `FemaleText_loc7`='¡Sí, Jefe de Guerra!' WHERE `ID`=8320;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 주인이 죽는 모습을 보더니 쓰러집니다!', `MaleText_loc4`='%s眼见主人死去，随即倒塌在地！', `MaleText_loc5`='%s看到他的主人死去，也隨即崩潰了!', `MaleText_loc7`='%s se derrumba al ver morir a su maestro.' WHERE `ID`=8321;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오시오, $g형제:자매;여. 이곳에 훈련을 받으러 온 것이라면 내가 기꺼이 가르쳐 드리겠소.$B$B말퓨리온 님께서는 에메랄드의 꿈속에 계시니 우리가 영원한 균형의 수호자요. 이 사실을 잊지 마시오.', `MaleText_loc4`='欢迎你，我的$g兄弟:姐妹;。如果你想接受训练，我会很乐意教你的。$B$B只要玛法里奥还在沉睡中，我们便永远是平衡的守卫者。别忘了这一点。', `MaleText_loc5`='歡迎你，我的$g兄弟:姐妹;。如果你想接受訓練，我會很樂意教你的。$B$B只要瑪法里恩還在沉睡中，我們便永遠是平衡的守衛者。別忘了這一點。', `MaleText_loc7`='Te doy la bienvenida, $ghermano:hermana;. Si has venido en busca de instrucción, estaré encantado de ayudarte.$B$BSomos los protectores del equilibrio, ahora y siempre, mientras Malfurion siga sumido en el Sueño. Nunca lo olvides.', `FemaleText_loc1`='어서 오세요, $g형제:자매;여. 이곳에 훈련을 받으러 온 것이라면 제가 기꺼이 가르쳐 드리지요.$B$B말퓨리온 님께서는 에메랄드의 꿈속에 계시니 우리가 영원한 균형의 수호자입니다. 이 사실을 잊지 마세요.', `FemaleText_loc4`='欢迎你，我的$g兄弟:姐妹;。如果你想接受训练，我会很乐意教你的。$B$B只要玛法里奥还在沉睡中，我们便永远是平衡的守卫者。别忘了这一点。', `FemaleText_loc5`='歡迎你，我的$g兄弟:姐妹;。如果你想接受訓練，我會很樂意教你的。$B$B只要瑪法里恩還在沉睡中，我們便永遠是平衡的守衛者。別忘了這一點。', `FemaleText_loc7`='Te doy la bienvenida, $ghermano:hermana;. Si has venido en busca de instrucción, estaré encantado de ayudarte.$B$BSomos los protectores del equilibrio, ahora y siempre, mientras Malfurion siga sumido en el Sueño. Nunca lo olvides.' WHERE `ID`=8322;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오시오, $g형제:자매;여. 이곳에 훈련을 받으러 온 것이라면 내가 기꺼이 가르쳐 드리겠소.$B$B말퓨리온 님께서는 에메랄드의 꿈속에 계시니 우리가 영원한 균형의 수호자요. 이 사실을 잊지 마시오.', `MaleText_loc4`='欢迎你，我的$g兄弟:姐妹;。如果你想接受训练，我会很乐意教你的。$B$B只要玛法里奥还在沉睡中，我们便永远是平衡的守卫者。别忘了这一点。', `MaleText_loc5`='歡迎你，我的$g兄弟:姐妹;。如果你想接受訓練，我會很樂意教你的。$B$B只要瑪法里恩還在沉睡中，我們便永遠是平衡的守衛者。別忘了這一點。', `MaleText_loc7`='Te doy la bienvenida, $ghermano:hermana;. Si has venido en busca de instrucción, estaré encantado de ayudarte.$B$BSomos los protectores del equilibrio, ahora y siempre, mientras Malfurion siga sumido en el Sueño. Nunca lo olvides.', `FemaleText_loc1`='어서 오세요, $g형제:자매;여. 이곳에 훈련을 받으러 온 것이라면 제가 기꺼이 가르쳐 드리지요.$B$B말퓨리온 님께서는 에메랄드의 꿈속에 계시니 우리가 영원한 균형의 수호자입니다. 이 사실을 잊지 마세요.', `FemaleText_loc4`='欢迎你，我的$g兄弟:姐妹;。如果你想接受训练，我会很乐意教你的。$B$B只要玛法里奥还在沉睡中，我们便永远是平衡的守卫者。别忘了这一点。', `FemaleText_loc5`='歡迎你，我的$g兄弟:姐妹;。如果你想接受訓練，我會很樂意教你的。$B$B只要瑪法里恩還在沉睡中，我們便永遠是平衡的守衛者。別忘了這一點。', `FemaleText_loc7`='Te doy la bienvenida, $ghermano:hermana;. Si has venido en busca de instrucción, estaré encantado de ayudarte.$B$BSomos los protectores del equilibrio, ahora y siempre, mientras Malfurion siga sumido en el Sueño. Nunca lo olvides.' WHERE `ID`=8323;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미란다, 아뮬렛을 또 만들 수 있는 눈동자가 있습니까? 전에 있던 것을 잃어버렸습니다.', `MaleText_loc4`='麦兰达，你有足够的眼珠再制作一个护身符吗？我把先前那个弄丢了。', `MaleText_loc5`='米蘭達，你有足夠的眼珠再製作一個護符嗎?我把先前那個弄丟了。', `MaleText_loc7`='Myranda, ¿tienes suficientes globos oculares para hacer otro amuleto? He perdido el que tenía.', `FemaleText_loc1`='미란다, 아뮬렛을 또 만들 수 있는 눈동자가 있습니까? 전에 있던 것을 잃어버렸습니다.', `FemaleText_loc4`='麦兰达，你有足够的眼珠再制作一个护身符吗？我把先前那个弄丢了。', `FemaleText_loc5`='米蘭達，你有足夠的眼珠再製作一個護符嗎?我把先前那個弄丟了。', `FemaleText_loc7`='Myranda, ¿tienes suficientes globos oculares para hacer otro amuleto? He perdido el que tenía.' WHERE `ID`=8324;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 항구에 꽤 수상한 자들이 드나들고 있으니 몸조심하는 게 좋을 겁니다, $n. 절대 아무나 믿어서는 안 돼요. 여기서는 알 수 없는 일들도 많이 일어나고 있으니까 말이죠...', `MaleText_loc4`='我看见一些有趣的人在港口进进出出。小心，$n。你永远不清楚谁值得信任以及跟这儿发生的所有事情的缘由……', `MaleText_loc5`='我看見一些有趣的人在港口進進出出。小心，$n。你永遠不清楚誰值得信任以及跟這兒發生的所有事情的緣由...', `MaleText_loc7`='Aquí en el puerto, veo pasar a muchos personajes interesantes. Ten cuidado, $n. Nunca se puede saber con seguridad en quien confiar, con toda la actividad sospechosa que hay por aquí...' WHERE `ID`=8325;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러니까 전쟁노래 도끼 때문에 온 게로군요. 좀 늦었군요. 저 화물상자는 벌써 며칠째 저렇게 있었답니다.$B$B준비가 끝나거든 주저하지 말고 가지고 가십시오.', `MaleText_loc4`='你是为战歌之斧而来的吧。嗯，是时候了，$n。那箱子已经放了好长时间了。$B$B你可以随时拖走它。', `MaleText_loc5`='你是為戰歌之斧而來的吧。嗯，是時候了，$n。那木箱已經放了好長時間了。$B$B你可以隨時拖走它。', `MaleText_loc7`='Así que has venido a buscar las hachas Grito de Guerra. Bueno, ya era hora, $n. Esa caja lleva días ahí.$B$BEres libre para llevártela cuando quieras.' WHERE `ID`=8326;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 풀려난 사실을 알아채기 전에 어서 빠져나가요!', `FemaleText_loc4`='在他们发现我获得自由之前我们离开这儿！', `FemaleText_loc5`='在他們發現我獲得自由之前我們離開這兒!', `FemaleText_loc7`='¡Vámonos antes de que descubran que estoy libre!' WHERE `ID`=8327;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='조심해요! 녀석들이 공격해오고 있어요!', `FemaleText_loc4`='当心！我们正在遭受攻击！', `FemaleText_loc5`='當心!我們正在遭受攻擊!', `FemaleText_loc7`='¡Cuidado! ¡Nos atacan!' WHERE `ID`=8328;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='도와주셔서 감사합니다. 여기서부터는 길을 찾아갈 수 있어요.', `FemaleText_loc4`='谢谢你帮助我。我知道从这里回去的路。', `FemaleText_loc5`='謝謝你幫助我。我知道從這裡回去的路。', `FemaleText_loc7`='Gracias por ayudarme. Puedo seguir sola a partir de aquí.' WHERE `ID`=8329;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌발톱 산맥에는 곳곳에 위험한 동굴들이 많이 있지. 영광을 위해서 기꺼이 목숨까지 내놓을 각오가 돼 있는 자라면 이 동굴에서 많은 모험을 할 수 있을 걸세.$B$B어쩌면 자네는 마음과 영혼을 따라야만 얻을 수 있는 부를 찾고 있는 것인지도 모르겠군.', `MaleText_loc4`='石爪山脉在这片区域拥有许多危险的洞穴。若干冒险家愿意冒着生命的危险到这些洞穴中探险。$B$B$C，也许只要你全心全意地寻找，会找到财宝的。', `MaleText_loc5`='石爪山脈在這片區域擁有許多危險的洞穴。若干冒險家願意冒著生命的危險到這些洞穴中探險。$B$B$C，也許只要你全心全意地尋找，會找到財寶的。', `MaleText_loc7`='Sierra Espolón tiene muchas cavernas peligrosas en esta región. Explorar esas cavernas puede proporcionar muchas aventuras a aquellos dispuestos a arriesgar su vida a cambio de gloria.$B$B$C, quizás busques riquezas que solo puedas obtener siguiendo a tu alma y tu corazón.' WHERE `ID`=8330;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미샤가 쓰러지는 모습을 보고 %s|1이;가; 분노합니다!', `MaleText_loc4`='%s看到米莎阵亡后变得狂怒无比！', `MaleText_loc5`='%s看到米莎陣亡後變得狂怒!', `MaleText_loc7`='%s monta en cólera tras ver a Misha caer en combate.', `FemaleText_loc1`='미샤가 쓰러지는 모습을 보고 %s|1이;가; 분노합니다!', `FemaleText_loc4`='%s看到米莎阵亡后变得狂怒无比！', `FemaleText_loc5`='%s看到米莎陣亡後變得狂怒!', `FemaleText_loc7`='%s monta en cólera tras ver a Misha caer en combate.' WHERE `ID`=8331;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 조각들을 붙여서 다시 원래대로 만들어볼 테니 잠시만 기다리세요.', `FemaleText_loc4`='我尝试把碎片复合，以使他们能再次成为一个整体，在这期间请你耐心等待。', `FemaleText_loc5`='我嘗試把裂片複合，以使他們能再次成為一個整體，在這期間請你耐心等待。', `FemaleText_loc7`='Espera aquí mientras intento unir los fragmentos para que vuelvan a ser un todo.' WHERE `ID`=8332;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이시누... 오샬란타라 도르밀... 아누도린...', `FemaleText_loc4`='Ishnu... Oshalan thara dormil... Anu''dorin...', `FemaleText_loc5`='(達納蘇斯語)伊蘇奴... 歐夏蘭·薩拉·多米爾·... 安奴''多利尼...', `FemaleText_loc7`='Ishnu... Oshalan thara dormil... Anu''dorin...' WHERE `ID`=8333;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음... 생선은 너무 맛있어. 당신 낚시 배우러 온 건가? 아님 생선 먹으러? 음...', `MaleText_loc4`='鱼肉真鲜美。你来学钓鱼的？还是来吃鱼的？呣……', `MaleText_loc5`='魚肉真鮮美。你來學釣魚的?還是來吃魚的?呣...', `MaleText_loc7`='Peces muy deliciosos. ¿Venir a aprender pescar? ¿Comer peces? Mmmmm...' WHERE `ID`=8334;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련을 받고 싶습니다, 루막.', `MaleText_loc4`='我需要训练，鲁玛克。', `MaleText_loc5`='我需要訓練，魯瑪克。', `MaleText_loc7`='Necesito instrucción, Lumak.', `FemaleText_loc1`='훈련을 받고 싶습니다, 루막.', `FemaleText_loc4`='我需要训练，鲁玛克。', `FemaleText_loc5`='我需要訓練，魯瑪克。', `FemaleText_loc7`='Necesito instrucción, Lumak.' WHERE `ID`=8335;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론, 낚시하는 걸 가르쳐줄 수 있지.', `MaleText_loc4`='对，我可以教你钓鱼。', `MaleText_loc5`='好吧，我可以教你釣魚。', `MaleText_loc7`='Sí, puedo enseñarte a pescar.' WHERE `ID`=8336;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련을 받고 싶습니다, 그림누르.', `MaleText_loc4`='我需要训练，格瑞诺尔。', `MaleText_loc5`='我需要訓練，格瑞諾爾。', `MaleText_loc7`='Necesito instrucción, Grimnur.', `FemaleText_loc1`='훈련을 받고 싶습니다, 그림누르.', `FemaleText_loc4`='我需要训练，格瑞诺尔。', `FemaleText_loc5`='我需要訓練，格瑞諾爾。', `FemaleText_loc7`='Necesito instrucción, Grimnur.' WHERE `ID`=8337;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n, 이제 유물을 다시 합칠 수 있겠어요.', `FemaleText_loc4`='是的，我能重新给遗物盖上封印，$n。', `FemaleText_loc5`='是的，我能重新給聖物蓋上封印，$n。', `FemaleText_loc7`='Sí, conseguí volver a sellar la reliquia, $n.' WHERE `ID`=8338;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n, 제발 이곳을 떠나세요. 그대는 여기서 어떤 일이 일어나고 있는지 모릅니다...', `FemaleText_loc4`='请离开这个地方，$n。你对困扰我们的问题毫不知情……', `FemaleText_loc5`='請離開這個地方，$n。你對困擾我們的問題毫不知情...', `FemaleText_loc7`='Por favor, vete de aquí, $n. No sabes nada de nuestras preocupaciones...' WHERE `ID`=8339;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마력 깃든 토륨은 어디서 구할 수 있습니까?', `MaleText_loc4`='我到哪里可以找到魔化瑟银锭？', `MaleText_loc5`='我到哪裡可以找到附魔瑟銀?', `MaleText_loc7`='¿Dónde puedo conseguir torio encantado?', `FemaleText_loc1`='마력 깃든 토륨은 어디서 구할 수 있습니까?', `FemaleText_loc4`='我到哪里可以找到魔化瑟银锭？', `FemaleText_loc5`='我到哪裡可以找到附魔瑟銀?', `FemaleText_loc7`='¿Dónde puedo conseguir torio encantado?' WHERE `ID`=8340;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='회복의 수정은 어디서 구할 수 있습니까?', `MaleText_loc4`='我到哪里可以找到恢复水晶？', `MaleText_loc5`='我到哪裡可以找到合成水晶?', `MaleText_loc7`='¿Dónde puedo encontrar cristal de restauración?', `FemaleText_loc1`='회복의 수정은 어디서 구할 수 있습니까?', `FemaleText_loc4`='我到哪里可以找到恢复水晶？', `FemaleText_loc5`='我到哪裡可以找到合成水晶?', `FemaleText_loc7`='¿Dónde puedo encontrar cristal de restauración?' WHERE `ID`=8341;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마력 깃든 토륨은 많은 이들이 찾는 금속이죠. 그걸 찾으려면 대장장이나 광부에게 물어보는 게 가장 빠른 길일 것입니다.', `FemaleText_loc4`='魔化瑟银锭是一种很受欢迎的金属。你找到它的最好办法就是找个铁匠或是矿工谈谈。', `FemaleText_loc5`='附魔瑟銀是一種高度受歡迎的金屬。你找到它的最好辦法就是找個鐵匠或是礦工談談。', `FemaleText_loc7`='El torio encantado es un metal muy preciado. Lo mejor que puedes hacer para encontrarlo es hablar con un herrero o un minero.' WHERE `ID`=8342;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='회복의 수정은 구하기 쉽지 않은 물건입니다.$B$B운고로 분화구에서 구할 수 있을 것이니 그리로 가보는 게 제일 좋은 방법일 겁니다.', `FemaleText_loc4`='恢复水晶很难入手。$B$B我相信它来自安戈洛环形山，你最好去那儿看看。', `FemaleText_loc5`='要想依靠自己的力量尋找恢復水晶是件很困難的事情。$B$B我認為它來自安戈洛環形山，你最好去那兒。但是，或許你能找到某個願意出售自己的裝備的人...', `FemaleText_loc7`='El cristal de restauración es un objeto muy difícil de encontrar.$B$BCreo que viene del Cráter de Un''Goro. Será mejor que vayas allí.' WHERE `ID`=8343;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가뭄이 들어 고생을 할지언정 고기는 부족한 법이 없지! 내 물건을 한번 보겠나?', `MaleText_loc4`='我们可能遇到了旱季，但是供给并不缺乏！想看看我的货物吗？', `MaleText_loc5`='我們可能遇到強氣流了，但是並不缺乏肉食!想看看我的貨物嗎?', `MaleText_loc7`='¡Es posible que hayamos sufrido una sequía, pero no tenemos escasez de carne! ¿Quieres echarle un vistazo a mis mercancías?' WHERE `ID`=8344;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물건을 보고 싶습니다, 더지.', `MaleText_loc4`='我想看看你的货物，迪尔格。', `MaleText_loc5`='我想看看你的貨物，戴格。', `MaleText_loc7`='Me gustaría ver tus mercancías, Dirge.', `FemaleText_loc1`='물건을 보고 싶습니다, 더지.', `FemaleText_loc4`='我想看看你的货物，迪尔格。', `FemaleText_loc5`='我想看看你的貨物，戴格。', `FemaleText_loc7`='Me gustaría ver tus mercancías, Dirge.' WHERE `ID`=8345;
