UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 종족은 그대가 고치려는 그 유물만큼이나 산산조각났답니다.', `FemaleText_loc4`='我的人民，他们就像你试图修复的遗物一样支离破碎。', `FemaleText_loc5`='我的人民，他們就像你試圖修復的聖物一樣支離破碎。', `FemaleText_loc7`='Mi pueblo, están tan destrozados como la reliquia que quieres reparar.' WHERE `ID`=8371;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='과거는 바꿀 수 없지만 시간은 어떤 상처라도 치유할 수 있죠. 그게 가능하다는 걸 보여줘서 고마워요, $n. 안녕히 가세요.', `FemaleText_loc4`='虽说没有东西可以改变过去，时间可以治愈所有伤口。谢谢你让我看到那是可能的，$n。我祝你顺利。', `FemaleText_loc5`='雖說沒有東西可以改變過去，時間可以治癒所有傷口。謝謝你讓我看到那是可能的，$n。我祝你順利。', `FemaleText_loc7`='Si bien es imposible cambiar el pasado, el tiempo puede curar todas las heridas. Gracias por enseñarme que eso es posible, $n. Te deseo lo mejor.' WHERE `ID`=8372;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='켈투자드라고? 그 이름을 알고 있다면 내가 가져오라고 했던 책을 읽은 게로군.$B$B미안하지만 자네의 대답은 틀렸네.', `MaleText_loc4`='克尔苏加德？如果你知道这个名字，那么你肯定读过我要你去找的那本书。$B$B不幸的是，你的答案是错误的。', `MaleText_loc5`='科爾蘇加德?如果你知道這個名字，那麼你肯定讀過我要你去找的那本書。$B$B不幸的是，你的答案是錯誤的。', `MaleText_loc7`='¿Kel''Thuzad? Si conoces ese nombre, quizás sea porque has leído el libro que te envié a buscar.$B$BPor desgracia, tu respuesta no es correcta.' WHERE `ID`=8373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='굴단이라... 아제로스에서는 그리 잘 알려지지 않은 이름이지.$B$B미안하지만 자네의 대답은 틀렸네.', `MaleText_loc4`='古尔丹。这个名字在艾泽拉斯没有多少人听说过。$B$B不幸的是，答案错误。', `MaleText_loc5`='古爾丹。這個名字在艾澤拉斯沒有多少人聽說過。$B$B不幸的是，答案錯誤。', `MaleText_loc7`='Gul''dan. No es un nombre que muchos hayan oído en Azeroth.$B$BPor desgracia, no es la respuesta correcta.' WHERE `ID`=8374;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 재미있는 답이지만 틀렸네.', `MaleText_loc4`='这个回答很有意思……可惜答案错误。', `MaleText_loc5`='這個回答很有意思...可惜答案錯誤。', `MaleText_loc7`='Una respuesta interesante a mi pregunta... pero incorrecta.' WHERE `ID`=8375;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 넬쥴이라... 입에 함부로 올려서는 안 되는 이름이지만 내가 그 대답을 기대하고 물은 것이지.$B$B넬쥴이 정답일세.', `MaleText_loc4`='啊， 耐奥祖。这名字不应如此轻松地说出，但是我确实要求你说出一个答案。$B$B耐奥祖是正确的答案。', `MaleText_loc5`='啊， 耐祖奧。這名字不應如此輕鬆地說出，但是我確實要求你說出一個答案。$B$B耐祖奧是正確的答案。', `MaleText_loc7`='Ah, Ner''zhul. No es un nombre que se pueda pronunciar tranquilamente, pero te pedí una respuesta.$B$BY Ner''zhul es la correcta.' WHERE `ID`=8376;
