UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오게, $c. 내가 도울 일이라도 있나?', `MaleText_loc4`='你好，$c。有什么我能帮忙的吗？', `MaleText_loc5`='你好，$c。有什麼我能幫忙的嗎?', `MaleText_loc7`='Hola, $c. ¿Puedo ayudarte en algo?' WHERE `ID`=8389;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 그대에게 할 질문은 이것일세.$B티탄이 창조한 위상 중 데스윙이라는 사악한 존재가 된 것은 무엇인가?', `MaleText_loc4`='我想问你，$c：$B在泰坦创造的守护巨龙中，是谁后来变成了被称作死亡之翼的邪恶生物？', `MaleText_loc5`='我想問你，$c:$B在泰坦創造的守護巨龍中，是誰後來變成了被稱作死亡之翼的邪惡生物?', `MaleText_loc7`='Esta es mi pregunta, $c:$B¿Cuál de los Aspectos creados por los titanes se convirtió en la malvada criatura conocida como Alamuerte?' WHERE `ID`=8390;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누군가 나와 얘기를 나누려고 찾아온다는 것은 항상 기분 좋은 일이야. 어떻게 지냈나?', `MaleText_loc4`='有人找我谈话总是件高兴的事儿。事情进展如何，$c？', `MaleText_loc5`='有人找我談話總是件高興的事兒。事情進展如何，$c?', `MaleText_loc7`='Siempre es agradable que alguien quiera hablar conmigo. ¿Cómo te va todo, $c?' WHERE `ID`=8391;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 내 질문에 대답해 보게나, $n.$B리치 왕이 되어 로데론 전역에 역병을 퍼뜨린 존재는 무엇인가?', `MaleText_loc4`='不，回答我，$n：$B在洛丹伦天灾爆发之前，是谁变成了巫妖王？', `MaleText_loc5`='不，回答我，$n:$B在羅德隆瘟疫爆發之前，是誰變成了巫妖王?', `MaleText_loc7`='Ahora, respóndeme a esto, $n.$B¿Qué criatura se convirtió en el Rey Exánime antes de extender la Peste por Lordaeron?' WHERE `ID`=8392;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='답이 틀렸네, $n. 이제 그만 가보게나.', `MaleText_loc4`='答案错误，$n。走吧。', `MaleText_loc5`='答案錯誤，$n。走吧。', `MaleText_loc7`='La respuesta no es correcta, $n. Puedes irte.' WHERE `ID`=8393;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미안하지만 아닐세, $n! 이제 자네 스스로 불러온 수치와 굴욕이 어떤 것인지 느껴보게나.', `MaleText_loc4`='恐怕不是这样，$n。自食苦果吧。', `MaleText_loc5`='恐怕不是這樣，$n。自食苦果吧。', `MaleText_loc7`='Me temo que no, $n. Ahora, siente la vergüenza de la que tan solo tú eres responsable.' WHERE `ID`=8394;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='위치로!', `FemaleText_loc4`='就位！', `FemaleText_loc5`='就位!', `FemaleText_loc7`='¡En posición!' WHERE `ID`=8395;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='위대한 어머니를 위하여!', `FemaleText_loc4`='为了伟大的母亲！', `FemaleText_loc5`='為了祖母!', `FemaleText_loc7`='¡Por la Gran Madre!' WHERE `ID`=8396;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='밤의 전사들이여, 집결하라!', `FemaleText_loc4`='暗夜的战士……集合！', `FemaleText_loc5`='暗夜的戰士...集合!', `FemaleText_loc7`='Guerreros de la noche... ¡Únanse!' WHERE `ID`=8397;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 깃발을 공격합니다!', `MaleText_loc4`='%s正在攻击旗帜！', `MaleText_loc5`='%s朝旌旗進攻!', `MaleText_loc7`='¡%s ataca el estandarte!' WHERE `ID`=8398;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 자네 좀 아는군! 더 배우고 싶거든 스톰윈드에 있는 조르지오 볼레로를 찾아가 보게.', `MaleText_loc4`='是的，你知道一些事情！如果你想学会更多的话就必须与暴风城的乔吉奥·波利罗谈谈。', `MaleText_loc5`='是的，你知道一些事情!如果你想學會更多的話就必須與暴風城的喬吉奧·波利羅談談。', `MaleText_loc7`='¡Sí, sabes un par de cosas! Si quieres aprender más, vas a tener que hablar con Georgio Bolero en Ventormenta.' WHERE `ID`=8399;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='토륨 대장조합에서는 불의 군주의 성스러운 무기를 만드는 비법을 알고 있는데, 필요한 재료를 모아올 인력이 부족한 형편이네.$B$B나, 로크토스 다크바게이너는 토륨 대장조합을 대신하여 화산 심장부에서 재료를 모아오는 자에게 보상으로 아주 값진 비법을 줄 거야.$B$B$R|1이여;여;, 자네의 생각을 말해 보게.', `MaleText_loc4`='瑟银兄弟会懂得如何制造炎魔之王的神圣武器，但是我们缺乏人力，无法获得制造武器所需的材料。$B$B我，罗克图斯·暗契，兄弟会赋予我强大的力量，用珍贵的药方来交换从熔火之心收集的材料。$B$B给个价吧，$r。', `MaleText_loc5`='瑟銀兄弟會懂得如何製造炎魔的神聖武器，但是我們缺乏人力，無法獲得製造武器所需的材料。$B$B瑟銀兄弟會准許我，羅克圖斯·暗契，用珍貴的設計圖交換從熔火之心收集的材料。$B$B你有什麼東西，$r。', `MaleText_loc7`='La Hermandad del Torio posee el conocimiento necesario para crear las armas y armamentos sagrados del Señor del Fuego, pero nos hace falta alguien que vaya a obtener los materiales necesarios para la fabricación.$B$BYo, Lokhtos Tratoscuro, estoy autorizado por la Hermandad para intercambiar las recetas exaltadas por materiales recogidos en El Núcleo de Magma.$B$BPresenta tu oferta, $r.' WHERE `ID`=8400;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 받을 수 있는 것이 어떤 것인지 보여주십시오, 로크토스.', `MaleText_loc4`='罗克图斯，哪些东西是我有权使用的。', `MaleText_loc5`='羅克圖斯，哪些東西是我有權使用的。', `MaleText_loc7`='Muéstrame hasta dónde tengo acceso, Lokhtos.', `FemaleText_loc1`='제가 받을 수 있는 것이 어떤 것인지 보여주십시오, 로크토스.', `FemaleText_loc4`='罗克图斯，哪些东西是我有权使用的。', `FemaleText_loc5`='羅克圖斯，哪些東西是我有權使用的。', `FemaleText_loc7`='Muéstrame hasta dónde tengo acceso, Lokhtos.' WHERE `ID`=8401;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 악마를 더 강하게 만들고 싶습니까? 돈이야 좀 들겠지만 제대로 찾아오셨습니다.', `MaleText_loc4`='想让你的恶魔变得更强大吗？这需要花钱的，但是你来对地方啦。', `MaleText_loc5`='想讓你的惡魔變得更強大嗎?這需要花錢的，但是你來對地方啦。', `MaleText_loc7`='¿Quieres que tus demonios sean más poderosos? Te costará, pero has venido al lugar adecuado.', `FemaleText_loc1`='당신의 악마를 더 강하게 만들고 싶습니까? 돈이야 좀 들겠지만 제대로 찾아오셨습니다.', `FemaleText_loc4`='想让你的恶魔变得更强大吗？这需要花钱的，但是你来对地方啦。', `FemaleText_loc5`='想讓你的惡魔變得更強大嗎?這需要花錢的，但是你來對地方啦。', `FemaleText_loc7`='¿Quieres que tus demonios sean más poderosos? Te costará, pero has venido al lugar adecuado.' WHERE `ID`=8402;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 흑마법사가 아니니 당신한테 낭비할 시간은 없습니다. 어서 가십시오!', `MaleText_loc4`='你不是术士而且我没时间理你。走开！', `MaleText_loc5`='你不是術士而且我沒時間理你。走開!', `MaleText_loc7`='No eres $gun brujo:una bruja; y no tengo tiempo para ti. ¡Largo!', `FemaleText_loc1`='당신은 흑마법사가 아니니 당신한테 낭비할 시간은 없습니다. 어서 가십시오!', `FemaleText_loc4`='你不是术士而且我没时间理你。走开！', `FemaleText_loc5`='你不是術士而且我沒時間理你。走開!', `FemaleText_loc7`='No eres $gun brujo:una bruja; y no tengo tiempo para ti. ¡Largo!' WHERE `ID`=8403;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가지고 있는 흑마법서를 보여주십시오.', `MaleText_loc4`='让我看看你收集的魔典。', `MaleText_loc5`='讓我看看你收集的魔典。', `MaleText_loc7`='Enséñame tu selección de grimorios.', `FemaleText_loc1`='가지고 있는 흑마법서를 보여주십시오.', `FemaleText_loc4`='让我看看你收集的魔典。', `FemaleText_loc5`='讓我看看你收集的魔典。', `FemaleText_loc7`='Enséñame tu selección de grimorios.' WHERE `ID`=8404;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='', `MaleText_loc4`='', `MaleText_loc5`='', `MaleText_loc7`='' WHERE `ID`=8405;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야수에게 가르칠 기술을 배우러 오셨습니까?', `MaleText_loc4`='你来接受训练为的是把它传递到你的宠物身上？', `MaleText_loc5`='你來接受訓練為的是把它傳遞到你的寵物身上?', `MaleText_loc7`='¿Has venido en busca de instrucción para poder pasársela a tus mascotas?', `FemaleText_loc1`='야수에게 가르칠 기술을 배우러 오셨나요?', `FemaleText_loc4`='你来接受训练为的是把它传递到你的宠物身上？', `FemaleText_loc5`='你來接受訓練為的是把它傳遞到你的寵物身上?', `FemaleText_loc7`='¿Has venido en busca de instrucción para poder pasársela a tus mascotas?' WHERE `ID`=8406;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$g형제:자매;여, 미안하지만 나는 사냥꾼과 그 야수에게만 도움을 줄 수가 있습니다.', `MaleText_loc4`='啊朋友，我只帮助猎人和他们的宠物。', `MaleText_loc5`='啊朋友，我只幫助獵人和他們的寵物。', `MaleText_loc7`='Oh, solo ayudo a los cazadores y sus mascotas.', `FemaleText_loc1`='$g형제:자매;여, 미안하지만 저는 사냥꾼과 그 야수에게만 도움을 줄 수가 있어요.', `FemaleText_loc4`='啊朋友，我只帮助猎人和他们的宠物。', `FemaleText_loc5`='啊朋友，我只幫助獵人和他們的寵物。', `FemaleText_loc7`='Oh, solo ayudo a los cazadores y sus mascotas.' WHERE `ID`=8407;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야수에게 기술을 가르치고 싶어요.', `MaleText_loc4`='将野兽的技能传授给我吧。', `MaleText_loc5`='將野獸的技能傳授給我吧。', `MaleText_loc7`='Enséñame las costumbres de las bestias.', `FemaleText_loc1`='야수에게 기술을 가르치고 싶어요.', `FemaleText_loc4`='将野兽的技能传授给我吧。', `FemaleText_loc5`='將野獸的技能傳授給我吧。', `FemaleText_loc7`='Enséñame las costumbres de las bestias.' WHERE `ID`=8408;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가슴 속에 공포가 남아 있군. 정말로 채찍꼬리 보르샤와 맞설 준비가 되거든 날 다시 찾아오게나.', `MaleText_loc4`='恐惧存在于你的心中，$n。当你真正准备好面对鞭笞者沃尔沙时，就来找我谈谈。', `MaleText_loc5`='恐懼存在你的心中。當你真正準備好面對『鞭笞者』沃爾沙時，來找我談談。', `MaleText_loc7`='El miedo yace en tu corazón. Cuando realmente seas capaz de enfrentarte a Vorsha el Azotador, ven a hablar conmigo.' WHERE `ID`=8409;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 기다려야 하네. 곧 있으면 보르샤가 낌새를 알아차리고 나타날 테니까...', `MaleText_loc4`='现在我们必须等待。纳迦很快就会意识到我们干了些什么。', `MaleText_loc5`='現在我們必須等待。納迦很快就能意識到我們所做的事情。', `MaleText_loc7`='Ahora debemos esperar. Los nagas no tardarán en ver lo que hemos hecho.' WHERE `ID`=8410;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왕립 연금술 학회는 어리석은 자를 기다려 주지 않으며 나 또한 마찬가지일세. 다음에 내가 타고 다니는 녀석에 대해 우리가 대화를 나눌 때쯤이면 자네가 언더시티의 친구로 인정받게 될지도 모르겠군. 그럼 그때까지 안녕히...', `MaleText_loc4`='皇家药剂师协会对愚蠢的家伙可没有耐心，我也一样。或许下次我们谈到战马的时候，你会被当作是幽暗城的贵族。到那时……', `MaleText_loc5`='皇家藥劑師學會對愚蠢的傢伙可沒有耐心，我也一樣。或許下次我們談到戰馬的時候，你會被當作是幽暗城的貴族。到那時...', `MaleText_loc7`='La Sociedad Real de Boticarios tiene poca paciencia con los necios, y yo también. Quizás la próxima vez que hablemos sobre mis corceles, ya tendrás reputación de $gexaltado:exaltada; en Entrañas. Hasta entonces...', `FemaleText_loc1`='왕립 연금술 학회는 어리석은 자를 기다려 주지 않으며 나 또한 마찬가지일세. 다음에 내가 타고 다니는 녀석에 대해 우리가 대화를 나눌 때쯤이면 자네가 언더시티의 친구로 인정받게 될지도 모르겠군. 그럼 그때까지 안녕히...', `FemaleText_loc4`='皇家药剂师协会对愚蠢的家伙可没有耐心，我也一样。或许下次我们谈到战马的时候，你会被当作是幽暗城的贵族。到那时……', `FemaleText_loc5`='皇家藥劑師學會對愚蠢的傢伙可沒有耐心，我也一樣。或許下次我們談到戰馬的時候，你會被當作是幽暗城的貴族。到那時...', `FemaleText_loc7`='La Sociedad Real de Boticarios tiene poca paciencia con los necios, y yo también. Quizás la próxima vez que hablemos sobre mis corceles, ya tendrás reputación de $gexaltado:exaltada; en Entrañas. Hasta entonces...' WHERE `ID`=8411;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경계를 늦추지 말게, $n!', `MaleText_loc4`='保持警惕，$n！', `MaleText_loc5`='保持警惕，$n!', `MaleText_loc7`='¡En guardia, $n!' WHERE `ID`=8412;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐 쉴 틈이 생길 것 같군그래. 하지만 난 보르샤와 직접 맞붙기 전까지는 절대로 포기하지 않을 걸세!', `MaleText_loc4`='或许我们能休息一下。但是在打败沃尔沙之前我绝不放弃！', `MaleText_loc5`='或許我們能休息一下。但是在打敗沃爾沙之前我絕不放棄!', `MaleText_loc7`='Quizás podamos descansar un momento. Pero no me rendiré hasta que nos hayamos enfrentado a Vorsha.' WHERE `ID`=8413;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 오그리마와 오크 종족에게 확고한 동맹인 자들에게만 탈것을 판매하네. 가서 우리 오크족에게 자신을 증명해 보이게나. 그럼 내 힘센 늑대들을 살펴볼 수 있게 해 주겠네.', `MaleText_loc4`='我只跟那些被奥格瑞玛的兽人当朋友的人做生意。证明自己吧，然后再来和我谈那些强大的座狼。', `MaleText_loc5`='我只跟奧格瑪和獸人的貴族做生意。證明自己吧，我將給你看看那些強大的狼。', `MaleText_loc7`='Solo permito que usen mis monturas aquellos considerados como exaltados por Orgrimmar y la raza orca. Demuestra tu valía y permitiré que inspecciones a mis poderosos lobos.', `FemaleText_loc1`='난 오그리마와 오크 종족에게 확고한 동맹인 자들에게만 탈것을 판매하네. 가서 우리 오크족에게 자신을 증명해 보이게나. 그럼 내 힘센 늑대들을 살펴볼 수 있게 해 주겠네.', `FemaleText_loc4`='我只跟那些被奥格瑞玛的兽人当朋友的人做生意。证明自己吧，然后再来和我谈那些强大的座狼。', `FemaleText_loc5`='我只跟奧格瑪和獸人的貴族做生意。證明自己吧，我將給你看看那些強大的狼。', `FemaleText_loc7`='Solo permito que usen mis monturas aquellos considerados como exaltados por Orgrimmar y la raza orca. Demuestra tu valía y permitiré que inspecciones a mis poderosos lobos.' WHERE `ID`=8414;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미안하네만 검은창 부족에게 확고한 동맹임을 증명하지 않은 자에게 랩터를 팔지 않네. 우리에게 우호적인 평판 이상이라는 걸 증명해 보인다면 내 랩터를 보여 주겠네.', `MaleText_loc4`='很抱歉$g兄弟:姐妹;，但是在确定买主是暗矛部落的贵族之前，我不会将迅猛龙卖给他的。当你证明自己是部落贵族之后，我才会把迅猛龙卖给你。', `MaleText_loc5`='很抱歉$g兄弟:姐妹;，但是在確定買主受到暗矛部族的崇拜之前，我不會將迅猛龍賣給他的。當你證明自己受到我們的崇拜之後，我才會把迅猛龍賣給你。', `MaleText_loc7`='Lo siento $ghermano:hermana;, pero no venderé mis raptores a alguien que no haya demostrado tener reputación de exaltado con la tribu Lanza Negra. Cuando demuestres tu reputación como $gexaltado:exaltada;, entonces tendrás disponibles a mis raptores.', `FemaleText_loc1`='죄송하지만 전 검은창 부족에게 확고한 동맹임을 증명하지 않은 자에게 랩터를 팔지 않습니다. 우리에게 우호적인 평판 이상이라는 걸 증명해 보인다면 제 랩터를 보여 드리겠습니다.', `FemaleText_loc4`='很抱歉$g兄弟:姐妹;，但是在确定买主是暗矛部落的贵族之前，我不会将迅猛龙卖给他的。当你证明自己是部落贵族之后，我才会把迅猛龙卖给你。', `FemaleText_loc5`='很抱歉$g兄弟:姐妹;，但是在確定買主受到暗矛部族的崇拜之前，我不會將迅猛龍賣給他的。當你證明自己受到我們的崇拜之後，我才會把迅猛龍賣給你。', `FemaleText_loc7`='Lo siento $ghermano:hermana;, pero no venderé mis raptores a alguien que no haya demostrado tener reputación de exaltado con la tribu Lanza Negra. Cuando demuestres tu reputación como $gexaltado:exaltada;, entonces tendrás disponibles a mis raptores.' WHERE `ID`=8415;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 우리 종족에게 알려지지 않았군. 코도는 강인한 탈것이며, 우리 종족의 사랑과 애정으로 자란 짐승이기 때문에 낯선 자에게는 팔지 않네. 즉 썬더 블러프의 장로들이 자네를 확고한 동맹으로 인정하기 전까지는 코도를 팔 수가 없다네.', `MaleText_loc4`='你并不为我的人民所知。科多兽是强大的坐骑，它是我的人民爱心和关怀的产物；所以它不能给陌生人。在雷霆崖的长老认为你的品德高尚之前，我不能卖给你科多兽。', `MaleText_loc5`='你並不為我的人民所知。科多獸是強大的坐騎，它是我的人民愛心和關懷的產物;所以它不能給陌生人。在雷霆崖的長老認為你的品德高尚之前，我不能賣給你科多獸。', `MaleText_loc7`='Mi pueblo no te conoce. Los kodos son poderosos corceles, y el producto del amor y el cuidado de mi pueblo; por esa razón, no los vendemos a extranjeros. Hasta que los ancestros de Cima del Trueno te consideren $gexaltado:exaltada;, no puedo venderte un kodo.', `FemaleText_loc1`='당신은 우리 종족에게 알려지지 않았군요. 코도는 강인한 탈것이며, 우리 종족의 사랑과 애정으로 자란 짐승이기 때문에 낯선 자에게는 팔지 않습니다. 즉 썬더 블러프의 장로들이 당신을 확고한 동맹으로 인정하기 전까지는 코도를 팔 수가 없습니다.', `FemaleText_loc4`='你并不为我的人民所知。科多兽是强大的坐骑，它是我的人民爱心和关怀的产物；所以它不能给陌生人。在雷霆崖的长老认为你的品德高尚之前，我不能卖给你科多兽。', `FemaleText_loc5`='你並不為我的人民所知。科多獸是強大的坐騎，它是我的人民愛心和關懷的產物;所以它不能給陌生人。在雷霆崖的長老認為你的品德高尚之前，我不能賣給你科多獸。', `FemaleText_loc7`='Mi pueblo no te conoce. Los kodos son poderosos corceles, y el producto del amor y el cuidado de mi pueblo; por esa razón, no los vendemos a extranjeros. Hasta que los ancestros de Cima del Trueno te consideren $gexaltado:exaltada;, no puedo venderte un kodo.' WHERE `ID`=8416;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안타깝게도 다르나서스와 텔드랏실의 나이트 엘프는 그대를 같은 편으로 생각하지 않는군요. 말이 아닌 행동으로 그대가 우리 나이트 엘프의 친구라는 것을 증명해 보인 후에만 제가 판매하는 탈것을 그대에게 보여드릴 수 있습니다.', `MaleText_loc4`='唉$c，你不是达纳苏斯的贵族，也不是泰达希尔的上层精灵。除非你以实际行动——不仅仅是口头上的话语——证明自己的友好态度，那样的话，我会提供马匹让你挑选的。', `MaleText_loc5`='唉$c，你不是達納蘇斯的貴族，也不是泰達希爾的高等精靈。除非你以實際行動─不僅僅是口頭上的話語─證明自己的友好態度，那樣的話，我會提供馬匹讓你挑選的。', `MaleText_loc7`='¡Oh, $c! No te consideran $gexaltado:exaltada; en Darnassus ni tampoco los elfos de la noche de Teldrassil piensan así. Solo cuando demuestres tu valía mediante actos, no con simples palabras, tendrás a tu disposición mi selección de monturas.', `FemaleText_loc1`='안타깝게도 다르나서스와 텔드랏실의 나이트 엘프는 그대를 같은 편으로 생각하지 않는군요. 말이 아닌 행동으로 그대가 우리 나이트 엘프의 친구라는 것을 증명해 보인 후에만 제가 판매하는 탈것을 그대에게 보여드릴 수 있습니다.', `FemaleText_loc4`='唉$c，你不是达纳苏斯的贵族，也不是泰达希尔的上层精灵。除非你以实际行动——不仅仅是口头上的话语——证明自己的友好态度，那样的话，我会提供马匹让你挑选的。', `FemaleText_loc5`='唉$c，你不是達納蘇斯的貴族，也不是泰達希爾的高等精靈。除非你以實際行動─不僅僅是口頭上的話語─證明自己的友好態度，那樣的話，我會提供馬匹讓你挑選的。', `FemaleText_loc7`='¡Oh, $c! No te consideran $gexaltado:exaltada; en Darnassus ni tampoco los elfos de la noche de Teldrassil piensan así. Solo cuando demuestres tu valía mediante actos, no con simples palabras, tendrás a tu disposición mi selección de monturas.' WHERE `ID`=8417;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물러서시오! 여긴 애들이 올 곳이 아니오! 애송이는 어서 가란 말이오!', `MaleText_loc4`='后退！小孩子不应该在这儿的！回去吧，孩子们！', `MaleText_loc5`='後退!小孩子不應該在這兒的!回去吧，孩子們!', `MaleText_loc7`='¡Atrás! ¡Los niñatos no deberían estar aquí! ¡Márchate!' WHERE `ID`=8418;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자다! 침입자를 공격하라!', `MaleText_loc4`='入侵者！攻击入侵者！', `MaleText_loc5`='入侵者!攻擊入侵者!', `MaleText_loc7`='¡Intrusos! ¡Atacad a los intrusos!', `FemaleText_loc1`='침입자다! 침입자를 공격하라!', `FemaleText_loc4`='入侵者！攻击入侵者！', `FemaleText_loc5`='入侵者!攻擊入侵者!', `FemaleText_loc7`='¡Intrusos! ¡Atacad a los intrusos!' WHERE `ID`=8419;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정들 하시오. 곧 공격을 시작할 테니까.', `MaleText_loc4`='保持镇定。我们很快将发动奇袭。', `MaleText_loc5`='保持鎮定。我們很快將發動奇襲。', `MaleText_loc7`='Calma, pueblo. Pronto atacaremos.' WHERE `ID`=8420;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='운이 좋으면 오늘 아주 멋진 흉터가 생길지도 몰라.', `MaleText_loc4`='如果运气好的话，我们今天会得到几处不错的伤痕的。', `MaleText_loc5`='如果運氣好的話，我們今天會得到幾處不錯的傷痕的。', `MaleText_loc7`='Con suerte, conseguiremos unas buenas cicatrices hoy.' WHERE `ID`=8421;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 숲에 있으면 송곳니가 근질거려...', `MaleText_loc4`='这些树木弄得我的长牙发痒……', `MaleText_loc5`='這些樹木弄得我的長牙發癢...', `MaleText_loc7`='Estos bosques hacen que me piquen los colmillos...' WHERE `ID`=8422;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='들리는 소문으로는 두리엘이 아주 거친 나이트 엘프라던데. 아주 해볼만한 싸움이 될 거요!', `MaleText_loc4`='他们说杜瑞尔是一名勇猛的暗夜精灵。这将是一场恶战！', `MaleText_loc5`='他們說杜瑞爾是一名勇猛的夜精靈。這將是一場惡戰!', `MaleText_loc7`='Dicen que Duriel es un elfo de la noche muy fiero. ¡Será una buena pelea!' WHERE `ID`=8423;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다 끝나면 도끼에 눈금을 새겨 기록으로 남길 거요.', `MaleText_loc4`='在这之后我们会在斧头上刻下胜利的标记。', `MaleText_loc5`='在這之後我們會在斧頭上刻下勝利的標記。', `MaleText_loc7`='Después de esto, podremos hacer una muesca en nuestras hachas.' WHERE `ID`=8424;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정들 하시오. 우리 위치를 들키면 안 되니까.', `MaleText_loc4`='保持镇静。我们不能放弃自己的阵地。', `MaleText_loc5`='保持鎮靜。我們不能放棄自己的陣地。', `MaleText_loc7`='Todo el mundo en calma. No debemos revelar nuestra posición.' WHERE `ID`=8425;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='씩씩이 말이오? 탑 위에 있는 경주진행자 크롱크라이더가 그가 있는 곳을 안다고 하더군.', `MaleText_loc4`='胆大的约翰森？我听说塔顶的赛场主管科鲁克莱德知道他在哪儿。', `MaleText_loc5`='大膽的強森?我聽說塔頂的賽場主管，科魯克萊德，知道他在哪兒。', `MaleText_loc7`='¿El Desplumado? He oído que Kronkpiloto, el maestro del circuito que está en la parte de arriba de la torre, sabe dónde está.', `FemaleText_loc1`='씩씩이 말이오? 탑 위에 있는 경주진행자 크롱크라이더가 그가 있는 곳을 안다고 하더군.', `FemaleText_loc4`='胆大的约翰森？我听说塔顶的赛场主管科鲁克莱德知道他在哪儿。', `FemaleText_loc5`='大膽的強森?我聽說塔頂的賽場主管，科魯克萊德，知道他在哪兒。', `FemaleText_loc7`='¿El Desplumado? He oído que Kronkpiloto, el maestro del circuito que está en la parte de arriba de la torre, sabe dónde está.' WHERE `ID`=8426;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='씩씩이 그 친구를 찾는 거요? 탑 위에 있는 크론크라이더에게 물어보면 말해줄 거요. 내가 가르쳐줬다고는 아무한테도 말하지 말고...', `MaleText_loc4`='你在寻找约翰森？哦，我不该说太多，不过……或许你该问问塔顶的科鲁克莱德，他会告诉你……', `MaleText_loc5`='你在尋找勇氣?哦，你沒聽到我的話，但是...或許你該問問塔里的科魯克萊德，他會告訴你...', `MaleText_loc7`='¿Buscas al Desplumado? Bueno, yo no te he dicho esto, pero... quizás si le preguntas a Kronkrider, te pueda decir algo. Está en la parte de arriba de la torre...', `FemaleText_loc1`='씩씩이 그 친구를 찾는 거요? 탑 위에 있는 크론크라이더에게 물어보면 말해줄 거요. 내가 가르쳐줬다고는 아무한테도 말하지 말고...', `FemaleText_loc4`='你在寻找约翰森？哦，我不该说太多，不过……或许你该问问塔顶的科鲁克莱德，他会告诉你……', `FemaleText_loc5`='你在尋找勇氣?哦，你沒聽到我的話，但是...或許你該問問塔里的科魯克萊德，他會告訴你...', `FemaleText_loc7`='¿Buscas al Desplumado? Bueno, yo no te he dicho esto, pero... quizás si le preguntas a Kronkrider, te pueda decir algo. Está en la parte de arriba de la torre...' WHERE `ID`=8427;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미안하지만, 스톰윈드 왕국에 호의적이지 않은 자에게 말을 팔고 싶지는 않소. 이 말들은 다른 어디에서도 볼 수 없는 최고의 품종인데 적의 손에 들어가기라도 하면 안 되니까 말이오.$B$B물론 당신이 적이라는 얘기는 아니지만 스톰윈드의 신임을 얻어 오면 그때 거래를 하도록 하겠소이다.', `MaleText_loc4`='很抱歉，如果你不是暴风城中的贵族，我是不会将马匹卖给你的。这些战马是最好的，我们当然不会当它们落入敌人之手。$B$B想要证明自己不是敌人，当然……你只需赢得暴风城的信任，我就可以跟你做买卖了。', `MaleText_loc5`='很抱歉，如果你不是暴風城中的貴族，我是不會將馬匹賣給你的。這些戰馬是最好的，我們當然不會當它們落入敵人之手。$B$B想要證明自己不是敵人，當然...你只需贏得暴風城的信任，我就可以跟你做買賣了。', `MaleText_loc7`='Lo siento, pero no estoy dispuesto a vender caballos a alguien a quien el Reino de Ventormenta no considere exaltado. Estos corceles son los mejores que se pueden encontrar y, ciertamente, no queremos que caigan en manos enemigas.$B$BNo estoy diciendo que seas $gun enemigo:una enemiga;, no... Solo tienes que ganarte la confianza de Ventormenta y después podremos hacer negocios.', `FemaleText_loc1`='죄송하지만, 스톰윈드 왕국에 호의적이지 않은 자에게 말을 팔고 싶지는 않습니다. 이 말들은 다른 어디에서도 볼 수 없는 최고의 품종인데 적의 손에 들어가기라도 하면 안 되니까 말입니다.$B$B물론 당신이 적이라는 얘기는 아닙니다. 스톰윈드의 신임을 얻어 오면 그때 거래를 하도록 하겠습니다.', `FemaleText_loc4`='很抱歉，如果你不是暴风城中的贵族，我是不会将马匹卖给你的。这些战马是最好的，我们当然不会当它们落入敌人之手。$B$B想要证明自己不是敌人，当然……你只需赢得暴风城的信任，我就可以跟你做买卖了。', `FemaleText_loc5`='很抱歉，如果你不是暴風城中的貴族，我是不會將馬匹賣給你的。這些戰馬是最好的，我們當然不會當它們落入敵人之手。$B$B想要證明自己不是敵人，當然...你只需贏得暴風城的信任，我就可以跟你做買賣了。', `FemaleText_loc7`='Lo siento, pero no estoy dispuesta a vender caballos a alguien a quien el Reino de Ventormenta no considere exaltado. Estos corceles son los mejores que se pueden encontrar y, ciertamente, no queremos que caigan en manos enemigas.$B$BNo estoy diciendo que seas $gun enemigo:una enemiga;, no... Solo tienes que ganarte la confianza de Ventormenta y después podremos hacer negocios.' WHERE `ID`=8428;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 서두르지는 마세요. 아이언포지 드워프들의 동지임이 입증되지 않은 자에게 힘 좋은 산양을 넘길 수는 없습니다. 당신이 아이언포지의 확고한 동맹이라는 게 인정되면 팔려고 내놓은 산양을 기꺼이 보여드리지요.', `MaleText_loc4`='现在还不行，$g小伙子:姑娘;……我是不会把强大的战羊随意卖给其他人的，你必须首先证明自己是铁炉堡矮人的忠实盟友才行。一旦我确认你在铁炉堡有着显赫的地位，那我会很乐意让你看看我出售的多种战羊的。', `MaleText_loc5`='現在還不行，$g小夥子:姑娘;...我是不會把強大的戰羊隨意賣給其他人的，你必須首先證明自己是鐵爐堡矮人的忠實盟友才行。一旦我確認你在鐵爐堡有著顯赫的地位，那我會很樂意讓你看看我出售的多種戰羊的。', `MaleText_loc7`='No tan rápido, $gchico:chica;... No entregaré las riendas de un poderoso corcel a alguien que no haya demostrado ser un aliado de los enanos de Forjaz. Cuando Forjaz te reconozca como $gexaltado:exaltada;, te mostraré encantado la variedad de carneros que tengo a la venta.', `FemaleText_loc1`='너무 서두르지는 마세요. 아이언포지 드워프들의 동지임이 입증되지 않은 자에게 힘 좋은 산양을 넘길 수는 없습니다. 당신이 아이언포지의 확고한 동맹이라는 게 인정되면 팔려고 내놓은 산양을 기꺼이 보여드리지요.', `FemaleText_loc4`='现在还不行，$g小伙子:姑娘;……我是不会把强大的战羊随意卖给其他人的，你必须首先证明自己是铁炉堡矮人的忠实盟友才行。一旦我确认你在铁炉堡有着显赫的地位，那我会很乐意让你看看我出售的多种战羊的。', `FemaleText_loc5`='現在還不行，$g小夥子:姑娘;...我是不會把強大的戰羊隨意賣給其他人的，你必須首先證明自己是鐵爐堡矮人的忠實盟友才行。一旦我確認你在鐵爐堡有著顯赫的地位，那我會很樂意讓你看看我出售的多種戰羊的。', `FemaleText_loc7`='No tan rápido, $gchico:chica;... No entregaré las riendas de un poderoso corcel a alguien que no haya demostrado ser un aliado de los enanos de Forjaz. Cuando Forjaz te reconozca como $gexaltado:exaltada;, te mostraré encantado la variedad de carneros que tengo a la venta.' WHERE `ID`=8429;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엄... 죄송하지만 제가 당신을 그리 잘 알지 못해서 말이죠. 그게, 저는 공인 기계타조 상인으로서 확고한 노움의 친구로 간주되는 이들에게만 탈것을 팔 수가 있단 말이죠. 당신이 놈리건의 확고한 동맹이라고 인정받으면 기꺼이 제가 가진 것들을 보여 드리도록 하죠.', `MaleText_loc4`='呃……很抱歉，我真的不太了解你。我是说，作为公认的机械陆行鸟经销商，我只能跟高贵的侏儒做生意。要是你是诺莫瑞根的侏儒贵族，我会很高兴地为你提供服务的。', `MaleText_loc5`='呃...很抱歉，我真的不太瞭解你。我是說，作為公認的機械陸行鳥經銷商，我只能跟高貴的地精做生意。要是你是諾姆瑞根的地精貴族，我會很高興地為你提供服務的。', `MaleText_loc7`='Ehh... Realmente no te conozco tan bien, lo siento. Como tratante autorizado de mecazancudos, solo puedo vender mis monturas a aquellos considerados como exaltados entre los gnomos. Si, alguna vez, Gnomeregan te considera $gun exaltado:una exaltada;, estaré encantado de enseñarte lo que tengo que ofrecer.', `FemaleText_loc1`='엄... 죄송하지만 제가 당신을 그리 잘 알지 못해서 말이죠. 그게, 저는 공인 기계타조 상인으로서 확고한 노움의 친구로 간주되는 이들에게만 탈것을 팔 수가 있단 말이죠. 당신이 놈리건의 확고한 동맹이라고 인정받으면 기꺼이 제가 가진 것들을 보여 드리도록 하죠.', `FemaleText_loc4`='呃……很抱歉，我真的不太了解你。我是说，作为公认的机械陆行鸟经销商，我只能跟高贵的侏儒做生意。要是你是诺莫瑞根的侏儒贵族，我会很高兴地为你提供服务的。', `FemaleText_loc5`='呃...很抱歉，我真的不太瞭解你。我是說，作為公認的機械陸行鳥經銷商，我只能跟高貴的地精做生意。要是你是諾姆瑞根的地精貴族，我會很高興地為你提供服務的。', `FemaleText_loc7`='Ehh... Realmente no te conozco tan bien, lo siento. Como tratante autorizado de mecazancudos, solo puedo vender mis monturas a aquellos considerados como exaltados entre los gnomos. Si, alguna vez, Gnomeregan te considera $gun exaltado:una exaltada;, estaré encantado de enseñarte lo que tengo que ofrecer.' WHERE `ID`=8430;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이언포지 드워프들과 확고한 동맹이 되시면 산양을 부리는 법을 가르쳐 드릴 수 있답니다.', `MaleText_loc4`='在我教你骑术之前，你必须达到被铁炉堡的矮人所崇拜的声望才行，$c。', `MaleText_loc5`='在我教你騎術之前，你必須與鐵爐堡的矮人達到崇拜的聲望才行，$c。', `MaleText_loc7`='Es necesario que los enanos de Forjaz te consideren $gun exaltado:una exaltada; para que te pueda enseñar la habilidad de equitación, $c.', `FemaleText_loc1`='아이언포지 드워프들과 확고한 동맹이 되시면 산양을 부리는 법을 가르쳐 드릴 수 있답니다.', `FemaleText_loc4`='在我教你骑术之前，你必须达到被铁炉堡的矮人所崇拜的声望才行，$c。', `FemaleText_loc5`='在我教你騎術之前，你必須與鐵爐堡的矮人達到崇拜的聲望才行，$c。', `FemaleText_loc7`='Es necesario que los enanos de Forjaz te consideren $gun exaltado:una exaltada; para que te pueda enseñar la habilidad de equitación, $c.' WHERE `ID`=8431;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해골마 타는 법은 먼저 언더시티 포세이큰들과 확고한 동맹이 되면 배울 수 있다네.', `MaleText_loc4`='在我教你骑术之前，你必须达到被幽暗城的被遗忘者所崇拜的声望才行，$c。', `MaleText_loc5`='在我教你騎術之前，你必須與幽暗城的被遺忘者達到崇拜的聲望才行，$c。', `MaleText_loc7`='Es necesario que los Renegados de Entrañas te consideren $gun exaltado:una exaltada; para que te pueda enseñar la habilidad de equitación, $c.', `FemaleText_loc1`='해골마 타는 법은 먼저 언더시티 포세이큰들과 확고한 동맹이 되면 배울 수 있답니다.', `FemaleText_loc4`='在我教你骑术之前，你必须达到被幽暗城的被遗忘者所崇拜的声望才行，$c。', `FemaleText_loc5`='在我教你騎術之前，你必須與幽暗城的被遺忘者達到崇拜的聲望才行，$c。', `FemaleText_loc7`='Es necesario que los Renegados de Entrañas te consideren $gun exaltado:una exaltada; para que te pueda enseñar la habilidad de equitación, $c.' WHERE `ID`=8432;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기계타조 조종법을 배우려면 먼저 놈리건의 노움들과 확고한 동맹이 되어야 합니다.', `MaleText_loc4`='在我教你骑术之前，你必须达到被诺莫瑞根逃亡侏儒所崇拜的声望才行，$c。', `MaleText_loc5`='在我教你騎術之前，你必須與諾姆瑞根流亡者的地精達到崇拜的聲望才行，$c。', `MaleText_loc7`='Es necesario que los Exiliados de Gnomeregan te consideren $gun exaltado:una exaltada; para que te pueda enseñar pilotar un mecazancudo, $c.', `FemaleText_loc1`='기계타조 조종법을 배우려면 먼저 놈리건의 노움들과 확고한 동맹이 되어야 합니다.', `FemaleText_loc4`='在我教你骑术之前，你必须达到被诺莫瑞根逃亡侏儒所崇拜的声望才行，$c。', `FemaleText_loc5`='在我教你騎術之前，你必須與諾姆瑞根流亡者的地精達到崇拜的聲望才行，$c。', `FemaleText_loc7`='Es necesario que los Exiliados de Gnomeregan te consideren $gun exaltado:una exaltada; para que te pueda enseñar pilotar un mecazancudo, $c.' WHERE `ID`=8433;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드의 인간과 확고한 동맹이 되시면 말 타는 법을 배우실 수 있습니다.', `MaleText_loc4`='在我教你骑术之前，你必须达到被暴风城的人类所崇拜的声望才行，$c。', `MaleText_loc5`='在我教你騎術之前，你必須與暴風城的人類達到崇拜的聲望才行，$c。', `MaleText_loc7`='Es necesario que los humanos de Ventormenta te consideren $gun exaltado:una exaltada; para que te pueda enseñar la habilidad de equitación, $c.', `FemaleText_loc1`='스톰윈드의 인간과 확고한 동맹이 되시면 말 타는 법을 배우실 수 있습니다.', `FemaleText_loc4`='在我教你骑术之前，你必须达到被暴风城的人类所崇拜的声望才行，$c。', `FemaleText_loc5`='在我教你騎術之前，你必須與暴風城的人類達到崇拜的聲望才行，$c。', `FemaleText_loc7`='Es necesario que los humanos de Ventormenta te consideren $gun exaltado:una exaltada; para que te pueda enseñar la habilidad de equitación, $c.' WHERE `ID`=8434;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다르나서스 나이트 엘프들과 확고한 동맹이 되시면 호랑이 타는 법을 가르쳐 드릴 수 있습니다.', `MaleText_loc4`='在我教你骑术之前，你必须达到被达纳苏斯的暗夜精灵所崇拜的声望才行，$c。', `MaleText_loc5`='在我教你騎術之前，你必須與達納蘇斯的夜精靈達到崇拜的聲望才行，$c。', `MaleText_loc7`='Es necesario que los elfos de la noche de Darnassus te consideren $gun exaltado:una exaltada; para que te pueda enseñar la habilidad de equitación, $c.', `FemaleText_loc1`='다르나서스 나이트 엘프들과 확고한 동맹이 되시면 호랑이 타는 법을 가르쳐 드릴 수 있답니다.', `FemaleText_loc4`='在我教你骑术之前，你必须达到被达纳苏斯的暗夜精灵所崇拜的声望才行，$c。', `FemaleText_loc5`='在我教你騎術之前，你必須與達納蘇斯的夜精靈達到崇拜的聲望才行，$c。', `FemaleText_loc7`='Es necesario que los elfos de la noche de Darnassus te consideren $gun exaltado:una exaltada; para que te pueda enseñar la habilidad de equitación, $c.' WHERE `ID`=8435;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오그리마 오크들과 확고한 동맹인 자만이 늑대 기수가 될 수 있습니다.', `MaleText_loc4`='在我教你骑术之前，你必须达到被奥格瑞玛的兽人所崇拜的声望才行，$c。', `MaleText_loc5`='在我教你騎術之前，你必須與奧格瑪的獸人達到崇拜的聲望才行，$c。', `MaleText_loc7`='Es necesario que los orcos de Orgrimmar te consideren $gun exaltado:una exaltada; para que te pueda enseñar la habilidad de equitación, $c.', `FemaleText_loc1`='오그리마 오크들과 확고한 동맹인 자만이 늑대 기수가 될 수 있습니다.', `FemaleText_loc4`='在我教你骑术之前，你必须达到被奥格瑞玛的兽人所崇拜的声望才行，$c。', `FemaleText_loc5`='在我教你騎術之前，你必須與奧格瑪的獸人達到崇拜的聲望才行，$c。', `FemaleText_loc7`='Es necesario que los orcos de Orgrimmar te consideren $gun exaltado:una exaltada; para que te pueda enseñar la habilidad de equitación, $c.' WHERE `ID`=8436;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코도 타는 법은 썬더 블러프 타우렌들과 확고한 동맹이 되면 배울 수 있다네.', `MaleText_loc4`='在我教你骑术之前，你必须达到被雷霆崖的牛头人所崇拜的声望才行，$c。', `MaleText_loc5`='在我教你騎術之前，你必須與雷霆崖的牛頭人達到崇拜的聲望才行，$c。', `MaleText_loc7`='Es necesario que los tauren de Cima del Trueno te consideren $gun exaltado:una exaltada; para que te pueda enseñar la habilidad de equitación, $c.', `FemaleText_loc1`='코도 타는 법은 썬더 블러프 타우렌들과 확고한 동맹이 되면 배울 수 있다네.', `FemaleText_loc4`='在我教你骑术之前，你必须达到被雷霆崖的牛头人所崇拜的声望才行，$c。', `FemaleText_loc5`='在我教你騎術之前，你必須與雷霆崖的牛頭人達到崇拜的聲望才行，$c。', `FemaleText_loc7`='Es necesario que los tauren de Cima del Trueno te consideren $gun exaltado:una exaltada; para que te pueda enseñar la habilidad de equitación, $c.' WHERE `ID`=8437;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='랩터 타는 법은 검은창 트롤과 확고한 동맹이 되시면 가르쳐 드릴 수 있습니다.', `MaleText_loc4`='在我教你骑术之前，你必须达到被暗矛部族的巨魔所崇拜的声望才行，$c。', `MaleText_loc5`='在我教你騎術之前，你必須與暗矛部族的食人妖達到崇拜的聲望才行，$c。', `MaleText_loc7`='Es necesario que los trols Lanza Negra te consideren $gun exaltado:una exaltada; para que te pueda enseñar la habilidad de equitación, $c.', `FemaleText_loc1`='랩터 타는 법은 검은창 트롤과 확고한 동맹이 되시면 가르쳐 드릴 수 있답니다.', `FemaleText_loc4`='在我教你骑术之前，你必须达到被暗矛部族的巨魔所崇拜的声望才行，$c。', `FemaleText_loc5`='在我教你騎術之前，你必須與暗矛部族的食人妖達到崇拜的聲望才行，$c。', `FemaleText_loc7`='Es necesario que los trols Lanza Negra te consideren $gun exaltado:una exaltada; para que te pueda enseñar la habilidad de equitación, $c.' WHERE `ID`=8438;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절반 정도 왔네...', `MaleText_loc4`='走了一半路了……', `MaleText_loc5`='半路上...', `MaleText_loc7`='Estás a medio camino...' WHERE `ID`=8439;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신에게는 차원문 마법을 이해할만한 정신적인 능력이 없는 것 같군요.', `FemaleText_loc4`='我不认为你具有掌握传送门魔法所必需的潜质。', `FemaleText_loc5`='我不認為你具有掌握傳送門魔法所必需的潛質。', `FemaleText_loc7`='No puedo creerme que poseas la agudeza mental necesaria para comprender la naturaleza de la magia del portal.' WHERE `ID`=8440;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신은 마법사로서 차원문을 소환해 바로 이곳으로 돌아올 수 있는 선택된 사람 중 하나입니다. 준비가 됐다면 가르쳐 드리도록 하죠.', `FemaleText_loc4`='作为一个法师，你是极少数可以操纵传送门魔法来帮助你回到这里的$r之一。如果你准备好了，我现在就可以教你。', `FemaleText_loc5`='作為一個法師，你是極少數可以操縱傳送門魔法來幫助你回到這裡的$r之一。如果你準備好了，我現在就可以教你。', `FemaleText_loc7`='Como mago, perteneces a un grupo selecto que puede invocar un portal para transportarte de nuevo a este lugar. Puedo enseñarte si eres capaz de aprender.' WHERE `ID`=8441;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='차원문 마법을 가르쳐 주십시오.', `MaleText_loc4`='请教教我吧。', `MaleText_loc5`='請教教我吧。', `MaleText_loc7`='Por favor, enséñame.', `FemaleText_loc1`='차원문 마법을 가르쳐 주십시오.', `FemaleText_loc4`='请教教我吧。', `FemaleText_loc5`='請教教我吧。', `FemaleText_loc7`='Por favor, enséñame.' WHERE `ID`=8442;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신에게는 차원문을 이해할만한 정신적인 능력이 없는 것 같군요.', `FemaleText_loc4`='我不认为你具有掌握传送门魔法所必需的潜质。', `FemaleText_loc5`='我不認為你具有掌握傳送門魔法所必需的潛質。', `FemaleText_loc7`='No puedo creerme que poseas la agudeza mental necesaria para comprender la naturaleza de la magia del portal.' WHERE `ID`=8443;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마법사로서 당신은 차원문을 소환해낸 후 바로 이곳으로 돌아올 수 있는 능력을 지닌 선택된 소수 중 하나입니다. 자, 준비가 됐다면 가르쳐 드리도록 하지요.', `FemaleText_loc4`='作为一个法师，你是极少数可以操纵传送门魔法来帮助你回到这里的$r之一。如果你准备好了，我现在就可以教你。', `FemaleText_loc5`='作為一個法師，你是極少數可以操縱傳送門魔法來幫助你回到這裡的$r之一。如果你準備好了，我現在就可以教你。', `FemaleText_loc7`='Como mago, perteneces a un grupo selecto que puede invocar un portal para transportarte de nuevo a este lugar. Puedo enseñarte si eres capaz de aprender.' WHERE `ID`=8444;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신에게는 차원문을 이해할만한 정신적인 능력이 없는 것 같군요.', `MaleText_loc4`='我不认为你具有掌握传送门魔法所必需的潜质。', `MaleText_loc5`='我不認為你具有掌握傳送門魔法所必需的潛質。', `MaleText_loc7`='No puedo creerme que poseas la agudeza mental necesaria para comprender la naturaleza de la magia del portal.' WHERE `ID`=8445;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법사로서 당신은 차원문을 소환해낸 다음 바로 이곳으로 돌아올 수 있는 능력을 지닌 선택된 존재들 중 하나예요. 준비가 됐다면 가르쳐 드리도록 하지요.', `MaleText_loc4`='作为一名法师，你是少数可以召唤传送门返回这个地方的$r。如果你已经准备就绪，我就可以教你这种法术。', `MaleText_loc5`='作為一名法師，你是少數可以召喚傳送門返回這個地方的$r。如果你已經準備就緒，我就可以教你這種法術。', `MaleText_loc7`='Como mago, perteneces a un grupo selecto que puede invocar un portal para transportarte de nuevo a este lugar. Puedo enseñarte si eres capaz de aprender.' WHERE `ID`=8446;
