UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법사로서 차원문을 소환해낸 후 바로 이곳으로 돌아올 수 있는 능력을 지닌 선택된 소수 중 하나로군. 준비가 됐다면 언제든지 배움을 구할 수 있는 재목이야...', `MaleText_loc4`='作为一名法师，你是少数可以召唤传送门返回这个地方的$r。如果你已经准备就绪，我就可以教你这种法术。', `MaleText_loc5`='作為一名法師，你是少數可以召喚傳送門返回這個地方的$r。如果你已經準備就緒，我就可以教你這種法術。', `MaleText_loc7`='Como mago, perteneces a un grupo selecto que puede invocar un portal para transportarte de nuevo a este lugar. Puedo enseñarte si eres capaz de aprender.', `FemaleText_loc1`='마법사로서 차원문을 소환해낸 후 바로 이곳으로 돌아올 수 있는 능력을 지닌 선택된 소수 중 하나로군. 준비가 됐다면 언제든지 배움을 구할 수 있는 재목이야...', `FemaleText_loc4`='作为一名法师，你是少数可以召唤传送门返回这个地方的$r。如果你已经准备就绪，我就可以教你这种法术。', `FemaleText_loc5`='作為一名法師，你是少數可以召喚傳送門返回這個地方的$r。如果你已經準備就緒，我就可以教你這種法術。', `FemaleText_loc7`='Como mago, perteneces a un grupo selecto que puede invocar un portal para transportarte de nuevo a este lugar. Puedo enseñarte si eres capaz de aprender.' WHERE `ID`=8448;
