UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쥐가 넘쳐나는군! 이 불쌍한 해적 좀 도와주게, 친구!', `MaleText_loc4`='老鼠泛滥成灾啦！朋友，帮助一个可怜的海盗离开这儿！', `MaleText_loc5`='老鼠氾濫成災啦!朋友，幫助一個可憐的海賊離開這兒!', `MaleText_loc7`='¡Hasta arriba de ratas! ¡Echa una mano a un pirata, camarada!' WHERE `ID`=8458;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='깊은굴 지하철을 깨끗하게 유지하는 일에 동참하게!', `MaleText_loc4`='你参与矿道地铁的保洁工作了吗？', `MaleText_loc5`='你參與礦道地鐵的保潔工作了嗎?', `MaleText_loc7`='¡Hacer tu parte para mantener el Tranvía Subterráneo limpio!' WHERE `ID`=8459;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어허, 나한테 너무 붙지들 말라고!', `MaleText_loc4`='别挤我！', `MaleText_loc5`='別擠我!', `MaleText_loc7`='¡No me atosigar, gente!' WHERE `ID`=8460;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 네 힘은 내 증오의 원천이다!', `MaleText_loc4`='你的力量让我更加强大，$n！', `MaleText_loc5`='你的力量使我壯大，$n!', `MaleText_loc7`='¡Tu propia fuerza me alimenta, $n!' WHERE `ID`=8461;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 조그만 녀석은 저 상자 중 하나에 숨어 있을 거야. 행운을 빌어주지!', `MaleText_loc4`='伙计，伐木机就藏在这些箱子中。祝你好运！', `MaleText_loc5`='夥計，伐木機就藏在這些箱子中。祝你好運!', `MaleText_loc7`='La coleguita está escondida en una de las cajas, camarada. ¡Suerte!' WHERE `ID`=8462;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 이름은 몬티. 쥐들은 내 사냥감이지.', `MaleText_loc4`='我名叫蒙提，老鼠是我的玩物。', `MaleText_loc5`='我名叫蒙提，老鼠是我的玩物。', `MaleText_loc7`='Monty ser mi nombre y las ratas, mi juego preferido.' WHERE `ID`=8463;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다람쥐를 찾을 준비가 됐습니다, 몬티.', `MaleText_loc4`='我要去寻找松鼠了，蒙提。', `MaleText_loc5`='我要去尋找松鼠了，蒙提。', `MaleText_loc7`='$gListo:lista; para encontrar a la ardilla, Monty.', `FemaleText_loc1`='다람쥐를 찾을 준비가 됐습니다, 몬티.', `FemaleText_loc4`='我要去寻找松鼠了，蒙提。', `FemaleText_loc5`='我要去尋找松鼠了，蒙提。', `FemaleText_loc7`='Lista para encontrar a la ardilla, Monty.' WHERE `ID`=8464;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상자 안으로! 내 귀여운 것들! 옳지. 하나씩 차례대로 들어가.', `MaleText_loc4`='进到盒子里来。一个接一个地进去。', `MaleText_loc5`='進到盒子裡來。一個接一個地進去。', `MaleText_loc7`='¡A la caja, preciosas! ¡Mu bien! Una a una, ¡así me gusta a mí!' WHERE `ID`=8465;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='승리! 우승자가 여기 있다!', `MaleText_loc4`='胜利者！我们这里将会有一个胜者！', `MaleText_loc5`='勝利者!我們這裡將會有一個勝者!', `MaleText_loc7`='¡Ganador! ¡Tenemos un ganador!' WHERE `ID`=8466;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 황무지에서 쉬고 있는 코도에게서는 아주 튼튼한 가죽을 얻을 수 있네.', `MaleText_loc4`='这些栖息在这片荒地上的科多兽的兽皮最为坚韧。', `MaleText_loc5`='這些棲息在這片荒地上的科多獸的獸皮最為堅韌。', `MaleText_loc7`='Los mejores pellejos son las de los kodos que han venido a descansar en esta tierra yerma.' WHERE `ID`=8467;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 솜씨가 나보다 훨씬 뛰어나구먼, 젊은이. 이제 썬더 블러프의 중앙 고원에서 가게를 운영하고 있는 우나를 찾아가보게. 그녀라면 자네가 원하는 것을 가르쳐줄 수 있을 걸세.', `MaleText_loc4`='你的技巧已经超过我了，年轻人。去找尤纳，她在雷霆崖的中央高地上有一家商店。她能给你你需要的指导。', `MaleText_loc5`='你的技巧已經超過我了，年輕人。去找猶納，她在雷霆崖的中央高地上有一家商店。她能給你需要的指導。', `MaleText_loc7`='Tus habilidades me han sobrepasado, joven. Ve a ver a Una, tiene una tienda en la meseta central de Cima del Trueno. Ella puede proporcionarte la ayuda que necesitas.' WHERE `ID`=8468;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미안하네만 나는 더 이상 수습생을 가르치지 않네. 썬더 블러프에 있는 마크를 찾아가면 그 친구가 기본기를 가르쳐줄 걸세.', `MaleText_loc4`='很抱歉，我不能再多收学生啦。去雷霆崖找玛克吧。他会教你一些基本技能的。', `MaleText_loc5`='很抱歉，我不能再多收學生啦。去雷霆崖找麥克吧。他會教你一些基本技能的。', `MaleText_loc7`='Lo siento, pero no puedo instruir a más aprendices. Ve a ver a Mak en Cima del Trueno. Él podrá enseñarte los conceptos básicos.' WHERE `ID`=8470;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='먼저 자네 실력을 보여주면 가르쳐 주도록 하지.', `MaleText_loc4`='你首先必须向我证明你自己，然后我就会训练你。', `MaleText_loc5`='你首先必須向我證明你自己，然後我就會訓練你。', `MaleText_loc7`='Primero, debes demostrarme tu habilidad. Después te instruiré.' WHERE `ID`=8471;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 자네는 한층 수준 높은 코도 통가죽 무두질을 배울 준비가 된 걸세. 시작하도록 하지...', `MaleText_loc4`='你已经准备好学习科多兽制皮的要点。让我们开始吧……', `MaleText_loc5`='你已經準備好學習科多獸製皮的要點。讓我們開始吧...', `MaleText_loc7`='Ahora puedes aprender a curtir los pellejos de kodo. Comencemos...' WHERE `ID`=8472;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='빛과 어두움 사이에는 그림자가 있지... 그 그림자는 자네가 지금껏 보지 못한 힘을 가지고 있다네.', `FemaleText_loc4`='在光明与黑暗之间，还有阴影……而那些阴影有些你未曾见过的力量。', `FemaleText_loc5`='在光明與黑暗之間，還有陰影...而那些陰影有些你未曾見過的力量。', `FemaleText_loc7`='Entre la Luz y la oscuridad hay una sombra... y, esas sombras, tienen poderes que todavía no has visto.' WHERE `ID`=8473;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='빛과 어두움 사이에는 그림자가 있지요... 그 그림자는 당신이 지금껏 보지 못한 힘을 가지고 있어요.', `FemaleText_loc4`='在光明与黑暗之间，还有阴影……而那些阴影有些你未曾见过的力量。', `FemaleText_loc5`='在光明與黑暗之間，還有陰影...而那些陰影有些你未曾見過的力量。', `FemaleText_loc7`='Entre la Luz y la oscuridad hay una sombra... y, esas sombras, tienen poderes que todavía no has visto.' WHERE `ID`=8474;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카즈 모단에서는 우리 쥐 꼬치구이가 최고지!', `MaleText_loc4`='你在卡兹莫丹不会找到更好的老鼠肉烧烤店的！', `MaleText_loc5`='你在卡茲莫丹不會找到更好的老鼠肉燒烤店的!', `MaleText_loc7`='¡No encontrarás mejores kebabs de rata a este lado de Khaz Modan!' WHERE `ID`=8475;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물건을 사고 싶습니다, 닙시.', `MaleText_loc4`='我想做些买卖，尼普希。', `MaleText_loc5`='我想做些買賣，尼普希。', `MaleText_loc7`='Quiero comprar algo, Niblis.', `FemaleText_loc1`='물건을 사고 싶습니다, 닙시.', `FemaleText_loc4`='我想做些买卖，尼普希。', `FemaleText_loc5`='我想做些買賣，尼普希。', `FemaleText_loc7`='Quiero comprar algo, Niblis.' WHERE `ID`=8476;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보아하니 일거리를 찾고 있는 것 같은데 지하철을 타고 아이언포지에 있는 깊은굴 지하철로 가서 내 동생 몬티를 만나보세요. 아마 당신에게 맡길 일이 있을 거예요.', `MaleText_loc4`='你看起来能用一些机件，$g小伙子:女士;。你应该上地铁去拜访我的兄弟蒙提，他在铁炉堡矿道地铁库房。我肯定他有些事情是你能做的。', `MaleText_loc5`='你看起來能用一些機件，$g小夥子:女士;。你應該上地鐵去拜訪我的兄弟蒙提，他在鐵爐堡礦道地鐵庫房。我肯定他有些事情是你能做的。', `MaleText_loc7`='Parece que te vendría bien algo de trabajo, $gamigo:amiga;. Deberías subirte al tren y visitar a mi hermano Monty, en el Depósito de Tranvías Subterráneos. Seguro que tiene algo para ti.' WHERE `ID`=8477;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이방인 친구, 조심하는 게 좋을 겁니다.', `MaleText_loc4`='陌生人，小心身后。', `MaleText_loc5`='陌生人，小心身後。', `MaleText_loc7`='Vigila tu espalda.' WHERE `ID`=8478;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라벤홀트 장원에서는 당신을 인정할 수 없습니다.', `MaleText_loc4`='你并未得到拉文霍德公爵的认可，$c。', `MaleText_loc5`='你並未得到拉文霍德莊園的認可，$c。', `MaleText_loc7`='La Mansión Ravenholdt no te reconoce, $c.' WHERE `ID`=8479;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무례하군요. 라벤홀트 경은 무례한 자를 싫어하십니다.', `MaleText_loc4`='鲁莽的家伙。拉文霍德公爵可不喜欢这样的人。', `MaleText_loc5`='魯莽的傢伙。拉文霍德大人可不喜歡這樣的人。', `MaleText_loc7`='Gritos. Al Maestro Ravenholdt no le gustan los gritos.' WHERE `ID`=8480;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 만나서 반갑습니다, $n.', `MaleText_loc4`='很高兴再次见到你，$n。', `MaleText_loc5`='很高興再次見到你，$n。', `MaleText_loc7`='Me alegra verte de nuevo, $n.' WHERE `ID`=8481;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오십시오. 파라드 님과는 얘기해 봤습니까?', `MaleText_loc4`='你好，$c。你找法拉德谈过了吗？', `MaleText_loc5`='你好，$c。你找法拉德談過了嗎?', `MaleText_loc7`='Hola, $c. ¿Ya has hablado con Fahrad?' WHERE `ID`=8482;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비밀결사대는 그야말로 오합지졸입니다. 조직력은 물론이고 실력도 형편없는 데다가 게으르기까지 하니...', `MaleText_loc4`='辛迪加工会的成员都是些平庸的家伙——缺乏组织性、技能拙劣、懒惰……', `MaleText_loc5`='辛迪加工會的成員都是些平庸的傢伙─缺乏組織性、技能拙劣、懶惰...', `MaleText_loc7`='La Hermandad está formada por un grupo de necios, desorganizados, inútiles y vagos...' WHERE `ID`=8483;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 참으로 실력이 많이 늘었군요, $n.', `MaleText_loc4`='你真的变得狡猾多了，$n。', `MaleText_loc5`='你真的變得狡猾多了，$n。', `MaleText_loc7`='Tu astucia ha aumentado en gran medida, $n.' WHERE `ID`=8484;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 만나게 돼서 영광입니다, $n.', `MaleText_loc4`='很荣幸再次看到你，$n。', `MaleText_loc5`='很榮幸再次看到你，$n。', `MaleText_loc7`='Es un honor verte de nuevo, $n.' WHERE `ID`=8485;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시몬이 당신을 찾고 있는 것 같던데. 아직 만나보지 않았나요?', `MaleText_loc4`='我想之前西蒙尼找过你，$n。你跟她谈过了吗？', `MaleText_loc5`='我想之前西蒙尼找過你，$n。你跟她談過了嗎?', `MaleText_loc7`='Creo que Simone te estaba buscando antes, $n. ¿Ya has hablado con ella?' WHERE `ID`=8486;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n! 스승 캉께서 찾고 계십니다! 이제 때가 된 건지도 모르지요!', `MaleText_loc4`='$n$g先生:女士;！康恩大人一直在打听你的事情，也许你该去见见他了！', `MaleText_loc5`='$n$g先生:女士;!康大師一直在打聽你的事情，也許你該去見見他了!', `MaleText_loc7`='¡$gMaestro:Maestra; $n! ¡El Maestro Kang ha estado preguntando por ti! ¡Quizás te haya llegado la hora!' WHERE `ID`=8487;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='만나 뵙게 돼서 참으로 기쁩니다, $n 님.', `MaleText_loc4`='你的出现让我们精神紧张，$n。', `MaleText_loc5`='你的出現讓我們精神緊張，$G主人:女主人;$n。', `MaleText_loc7`='Tu presencia nos hace fuertes, $gMaestro:Maestra; $n.' WHERE `ID`=8488;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라벤홀트 장원에는 당신에 관한 영웅담이 자자하답니다, $n 님.', `MaleText_loc4`='拉文霍德庄园流传着你的英雄事迹，$n。', `MaleText_loc5`='拉文霍德莊園流傳著你的英雄事蹟，$G主人:女主人;$n。', `MaleText_loc7`='Hemos oído muchas historias sobre tus heroicas hazañas en la Mansión Ravenholdt, $gMaestro:Maestra; $n.' WHERE `ID`=8489;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저처럼 미천한 것에게 시간을 내어주시다니...', `MaleText_loc4`='我不适合这次谈话，$G主人:女主人;。', `MaleText_loc5`='我不適合這次談話，$G主人:女主人;。', `MaleText_loc7`='No soy digno de esta conversación, $gMaestro:Maestra;.' WHERE `ID`=8490;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 언젠가 $n 님 밑에서 일하는 게 꿈입니다. 물론 제가 그런 자격이 있다고 생각하신다면 말이죠...', `MaleText_loc4`='能为你服务是我的梦想，$G主人:女主人;$n。换句话说，你认为我值得得到这些东西吗……', `MaleText_loc5`='能為你服務是我的夢想，$G主人:女主人;$n。換句話說，你認為我值得得到這些東西嗎...', `MaleText_loc7`='Mi sueño es poder servirte algún día, $gMaestro:Maestra; $n... Si alguna vez me consideras digno de tan alto honor...' WHERE `ID`=8491;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라벤홀트 장원에서는 $n 님이 오신다는 소식에 모두들 들떠 있었습니다. 모두들 $n 님을 맞이하게 된 걸 영광으로 생각하고 있답니다.', `MaleText_loc4`='整个庄园都在议论你的到来，$G主人:女主人;$n。对你的光临，我们感到无比荣幸。', `MaleText_loc5`='整個莊園都在議論你的到來，$G主人:女主人;$n。對你的光臨，我們感到無比榮幸。', `MaleText_loc7`='La Mansión bulle de excitación con las noticias de tu llegada, $gMaestro:Maestra; $n. Todos nos sentimos honrados por tu presencia.' WHERE `ID`=8492;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벌레 같은 것이 감히 라벤홀트 장원에 발을 들여놓다니!', `MaleText_loc4`='你敢踏入拉文霍德庄园，可怜虫？', `MaleText_loc5`='你敢踏入拉文霍德莊園，可憐蟲?', `MaleText_loc7`='¿Osas poner el pie en la Mansión Ravenholdt, babosa?', `FemaleText_loc1`='벌레 같은 것이 감히 라벤홀트 장원에 발을 들여놓다니!', `FemaleText_loc4`='你敢踏入拉文霍德庄园，可怜虫？', `FemaleText_loc5`='你敢踏入拉文霍德莊園，可憐蟲?', `FemaleText_loc7`='¿Osas poner el pie en la Mansión Ravenholdt, babosa?' WHERE `ID`=8493;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='등에 비수가 꽂히거나 몸 속에 독이 퍼지거나 하지 않고 성한 몸으로 이곳을 빠져나가기만 해도 다행인 줄 아십시오.', `MaleText_loc4`='不借助刀具或是毒药离开这儿就算完成任务。', `MaleText_loc5`='不挨刀子也不中毒藥就能離開這裡，真是了不起。', `MaleText_loc7`='Salir de aquí sin una espada clavada en tu espalda o veneno corriendo por tus venas, sería un gran logro.', `FemaleText_loc1`='등에 비수가 꽂히거나 몸 속에 독이 퍼지거나 하지 않고 성한 몸으로 이곳을 빠져나가기만 해도 다행인 줄 아세요.', `FemaleText_loc4`='不借助刀具或是毒药离开这儿就算完成任务。', `FemaleText_loc5`='不挨刀子也不中毒藥就能離開這裡，真是了不起。', `FemaleText_loc7`='Salir de aquí sin una espada clavada en tu espalda o veneno corriendo por tus venas, sería un gran logro.' WHERE `ID`=8494;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갈수록 실력이 늘고 있군요, $n. 소문을 좀 들었습니다...', `MaleText_loc4`='你一直进行得不错，$n。我听到好消息了……', `MaleText_loc5`='你一直進行得不錯，$n。我聽到好消息了...', `MaleText_loc7`='Lo estás haciendo muy bien, $n. He oído muchos halagos...', `FemaleText_loc1`='갈수록 실력이 늘고 있군요, $n. 소문을 좀 들었습니다...', `FemaleText_loc4`='你一直进行得不错，$n。我听到好消息了……', `FemaleText_loc5`='你一直進行得不錯，$n。我聽到好消息了...', `FemaleText_loc7`='Lo estás haciendo muy bien, $n. He oído muchos halagos...' WHERE `ID`=8495;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='윈스톤을 찾아가 얘기해 보십시오. 당신처럼 실력 있는 도적을 찾고 있다고 합니다.', `MaleText_loc4`='你该与温斯顿谈谈。我听说他在寻找一个与你有相同技能的潜行者。', `MaleText_loc5`='你該與溫斯頓談談。我聽說他在尋找一個與你有相同技能的盜賊。', `MaleText_loc7`='Deberías hablar con Ganapiedra. Creo que está buscando ladrones de tu talento.', `FemaleText_loc1`='윈스톤을 찾아가 얘기해 보십시오. 당신처럼 실력 있는 도적을 찾고 있다고 합니다.', `FemaleText_loc4`='你该与温斯顿谈谈。我听说他在寻找一个与你有相同技能的潜行者。', `FemaleText_loc5`='你該與溫斯頓談談。我聽說他在尋找一個與你有相同技能的盜賊。', `FemaleText_loc7`='Deberías hablar con Ganapiedra. Creo que está buscando ladrones de tu talento.' WHERE `ID`=8496;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대단합니다. 정말 대단해요. 당신은 우리 모두에게 큰 귀감이 되었습니다, $n.', `MaleText_loc4`='不可思议。太不可思议了。你给了我们启迪，$n。', `MaleText_loc5`='不可思議。太不可思議了。你給了我們啟迪，$n。', `MaleText_loc7`='Maravilloso. Simplemente maravilloso. Eres una inspiración para todos nosotros, $n.', `FemaleText_loc1`='대단합니다. 정말 대단해요. 당신은 우리 모두에게 큰 귀감이 되었습니다, $n.', `FemaleText_loc4`='不可思议。太不可思议了。你给了我们启迪，$n。', `FemaleText_loc5`='不可思議。太不可思議了。你給了我們啟迪，$n。', `FemaleText_loc7`='Maravilloso. Simplemente maravilloso. Eres una inspiración para todos nosotros, $n.' WHERE `ID`=8497;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇게 놀라운 일을 해낼 수 있다니 정말 부럽습니다, $n.', `MaleText_loc4`='我真羡慕你，$n。你做得太出色了。', `MaleText_loc5`='我真羡慕你，$n。你做得太出色了。', `MaleText_loc7`='Realmente te envidio, $n. Haces un trabajo impresionante.', `FemaleText_loc1`='그렇게 놀라운 일을 해낼 수 있다니 정말 부럽습니다, $n.', `FemaleText_loc4`='我真羡慕你，$n。你做得太出色了。', `FemaleText_loc5`='我真羡慕你，$n。你做得太出色了。', `FemaleText_loc7`='Realmente te envidio, $n. Haces un trabajo impresionante.' WHERE `ID`=8498;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 당신의 때가 왔습니다, $n. 캉 스승님께서 기다리고 계십니다...', `MaleText_loc4`='你的机会来了，$n。康恩在等……', `MaleText_loc5`='你的機會來了，$n。康大師在等你...', `MaleText_loc7`='Ha llegado tu hora, $n. El Maestro Kang te espera...', `FemaleText_loc1`='이제 당신의 때가 왔습니다, $n. 캉 스승님께서 기다리고 계십니다...', `FemaleText_loc4`='你的机会来了，$n。康恩在等……', `FemaleText_loc5`='你的機會來了，$n。康大師在等你...', `FemaleText_loc7`='Ha llegado tu hora, $n. El Maestro Kang te espera...' WHERE `ID`=8499;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생각해 보니 언젠가는 당신이 전설 속에 등장하는 인물이 될지도 모르겠군요!', `MaleText_loc4`='想想吧，有一天你也许可以成为传说中故事的主人公！', `MaleText_loc5`='想想吧，有一天你也許可以成為傳說中故事的主人公!', `MaleText_loc7`='¡Y pensar que algún día quizás todas las historias y las leyendas hablen de ti!', `FemaleText_loc1`='생각해 보니 언젠가는 당신이 전설 속에 등장하는 인물이 될지도 모르겠군요!', `FemaleText_loc4`='想想吧，有一天你也许可以成为传说中故事的主人公！', `FemaleText_loc5`='想想吧，有一天你也許可以成為傳說中故事的主人公!', `FemaleText_loc7`='¡Y pensar que algún día quizás todas las historias y las leyendas hablen de ti!' WHERE `ID`=8500;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신에 대한 영웅담을 듣고는 어린애처럼 울었습니다. 라벤홀트 경도 당신 같은 제자를 받아들이면 좋을 텐데요.', `MaleText_loc4`='当我听到你的豪言壮语时，我像小孩子一样哭了起来。拉文霍德有你这样的学徒真好。', `MaleText_loc5`='當我聽到你的豪言壯語時，我像小孩子一樣哭了起來。拉文霍德有你這樣的學徒真好。', `MaleText_loc7`='Lloré como un bebé cuando oí tus heroicas hazañas. El Maestro Ravenholdt hará bien en tener a un aprendiz como tú.', `FemaleText_loc1`='당신에 대한 영웅담을 듣고는 어린애처럼 울었습니다. 라벤홀트 경도 당신 같은 제자를 받아들이면 좋을 텐데요.', `FemaleText_loc4`='当我听到你的豪言壮语时，我像小孩子一样哭了起来。拉文霍德有你这样的学徒真好。', `FemaleText_loc5`='當我聽到你的豪言壯語時，我像小孩子一樣哭了起來。拉文霍德有你這樣的學徒真好。', `FemaleText_loc7`='Lloré como un bebé cuando oí tus heroicas hazañas. El Maestro Ravenholdt hará bien en tener a un aprendiz como tú.' WHERE `ID`=8501;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라벤홀트 경에게 충성할 의무만 없었다면 지구 끝까지라도 당신을 따라갔을 겁니다, $n 님. 당신은 그야말로 살아 있는 전설입니다.', `MaleText_loc4`='要是我无须对拉文霍德公爵尽职的话，我将跟随你到世界的尽头，$G主人:女主人;$n。你既优雅又聪明。', `MaleText_loc5`='要是我無須對拉文霍德大人盡職的話，我將跟隨你到世界的盡頭，$G主人:女主人;$n。你既優雅又聰明。', `MaleText_loc7`='Si no estuviera obligado a servir al Maestro Ravenholdt, te seguiría hasta los confines del mundo, $gMaestro:Maestra; $n. Eres la gracia y la astucia personificada.', `FemaleText_loc1`='라벤홀트 경에게 충성할 의무만 없었다면 지구 끝까지라도 당신을 따라갔을 겁니다, $n 님. 당신은 그야말로 살아 있는 전설입니다.', `FemaleText_loc4`='要是我无须对拉文霍德公爵尽职的话，我将跟随你到世界的尽头，$G主人:女主人;$n。你既优雅又聪明。', `FemaleText_loc5`='要是我無須對拉文霍德大人盡職的話，我將跟隨你到世界的盡頭，$G主人:女主人;$n。你既優雅又聰明。', `FemaleText_loc7`='Si no estuviera obligada a servir al Maestro Ravenholdt, te seguiría hasta los confines del mundo, $gMaestro:Maestra; $n. Eres la gracia y la astucia personificada.' WHERE `ID`=8502;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='엘룬께서 그대와 함께하시길, $c|1이여;여;. 저는 아우버다인의 고통받는 주민들을 돕기 위해 달의 신전에서 왔습니다.', `FemaleText_loc4`='愿月神与你同在，$c。月神殿已经来帮助奥伯丁饱受煎熬的公民了。', `FemaleText_loc5`='願伊露恩與你同在，$c。月神殿已經來幫助奧伯丁飽受煎熬的居民了。', `FemaleText_loc7`='Que Elune camine contigo, $c. El Templo de la Luna ha venido a ayudar a los desamparados ciudadanos de Auberdine.' WHERE `ID`=8503;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 시험용 영혼의 치유사입니다.', `MaleText_loc4`='我是个测试用的灵魂医者。', `MaleText_loc5`='我是個測試用的靈魂醫者。', `MaleText_loc7`='Ángel de la Resurrección de prueba.' WHERE `ID`=8504;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크아아, 너 왜 날 죽인 거냐, $n?', `MaleText_loc4`='你为什么要杀我，$n？', `MaleText_loc5`='你為什麼要殺我，$n?', `MaleText_loc7`='¿Por qué me has matado, $n?' WHERE `ID`=8505;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쇼자미는 저 건너 여관 앞에 있으니 어서 가보게나. 저리 비켜! 난 지금 아주 바쁘니까.', `MaleText_loc4`='苏亚米在旅馆前面。去吧，我正忙着呢。', `MaleText_loc5`='蘇亞米在旅館前面。去吧，我正忙著呢。', `MaleText_loc7`='Shoja''my está delante de la posada. Y ahora vete, estoy ocupado.', `FemaleText_loc1`='쇼자미는 저 건너 여관 앞에 있으니 어서 가보게나. 저리 비켜! 난 지금 아주 바쁘니까.', `FemaleText_loc4`='苏亚米在旅馆前面。去吧，我正忙着呢。', `FemaleText_loc5`='蘇亞米在旅館前面。去吧，我正忙著呢。', `FemaleText_loc7`='Shoja''my está delante de la posada. Y ahora vete, estoy ocupada.' WHERE `ID`=8506;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야수라도 돌봐줘야 하는 모양이군? 그냥 대소변이나 잘 치우면 되는 일이지! 여관 앞에 가면 쇼자미가 있을 테니 그리로 가보게.', `MaleText_loc4`='要照料宠物吗？你得确保它的清洁！去旅馆前面找苏亚米吧。', `MaleText_loc5`='要照料寵物嗎?你得確保它的清潔!去旅館前面找蘇亞米吧。', `MaleText_loc7`='¿Mascotas que cuidar? ¡Pues asegúrate de limpiar su porquería! Busca a Shoja''my delante de la posada.', `FemaleText_loc1`='야수라도 돌봐줘야 하는 모양이군? 그냥 대소변이나 잘 치우면 되는 일이지! 여관 앞에 가면 쇼자미가 있을 테니 그리로 가보게.', `FemaleText_loc4`='要照料宠物吗？你得确保它的清洁！去旅馆前面找苏亚米吧。', `FemaleText_loc5`='要照料寵物嗎?你得確保它的清潔!去旅館前面找蘇亞米吧。', `FemaleText_loc7`='¿Mascotas que cuidar? ¡Pues asegúrate de limpiar su porquería! Busca a Shoja''my delante de la posada.' WHERE `ID`=8507;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야수 관리인', `MaleText_loc4`='兽栏管理员', `MaleText_loc5`='獸欄管理員', `MaleText_loc7`='El maestro de establos', `FemaleText_loc1`='야수 관리인', `FemaleText_loc4`='兽栏管理员', `FemaleText_loc5`='獸欄管理員', `FemaleText_loc7`='El maestro de establos' WHERE `ID`=8508;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명예의 골짜기로 가서 우리 근처에 있는 손차를 찾아보게나.', `MaleText_loc4`='到荣誉山谷去并在马厩附近找到克苏卡。', `MaleText_loc5`='到榮譽谷去並在獸欄附近找到克蘇卡。', `MaleText_loc7`='Ve al Valle del Honor y busca a Xon''cha, cerca de los establos.', `FemaleText_loc1`='명예의 골짜기로 가서 우리 근처에 있는 손차를 찾아보게나.', `FemaleText_loc4`='到荣誉山谷去并在马厩附近找到克苏卡。', `FemaleText_loc5`='到榮譽谷去並在獸欄附近找到克蘇卡。', `FemaleText_loc7`='Ve al Valle del Honor y busca a Xon''cha, cerca de los establos.' WHERE `ID`=8509;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 데리고 있는 야수라면 손차가 잘 돌봐줄 걸세. 명예의 골짜기에 가면 용맹의 투기장과 사냥꾼의 전당이 있는데 그 사이에 있는 우리에 있지. 그럼 어서 가보게!', `MaleText_loc4`='克苏卡会把你多余的宠物圈养起来的。到荣誉山谷的竞技场和猎人大厅之间的畜栏里找到他，现在走吧！', `MaleText_loc5`='克蘇卡會把你多餘的寵物圈養起來的。到榮譽谷的競技場和獵人大廳之間的獸欄裡找到他，現在走吧!', `MaleText_loc7`='Xon''cha guardará en el establo a tus mascotas extra. Búscale en el Valle del Honor, en los establos que están entre la arena y el Recinto de los Cazadores. ¡Ahora, vete!', `FemaleText_loc1`='자네가 데리고 있는 야수라면 손차가 잘 돌봐줄 걸세. 명예의 골짜기에 가면 용맹의 투기장과 사냥꾼의 전당이 있는데 그 사이에 있는 우리에 있지. 그럼 어서 가보게!', `FemaleText_loc4`='克苏卡会把你多余的宠物圈养起来的。到荣誉山谷的竞技场和猎人大厅之间的畜栏里找到他，现在走吧！', `FemaleText_loc5`='克蘇卡會把你多餘的寵物圈養起來的。到榮譽谷的競技場和獵人大廳之間的獸欄裡找到他，現在走吧!', `FemaleText_loc7`='Xon''cha guardará en el establo a tus mascotas extra. Búscale en el Valle del Honor, en los establos que están entre la arena y el Recinto de los Cazadores. ¡Ahora, vete!' WHERE `ID`=8510;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야수 관리인', `MaleText_loc4`='兽栏管理员', `MaleText_loc5`='獸欄管理員', `MaleText_loc7`='Maestro de establos', `FemaleText_loc1`='야수 관리인', `FemaleText_loc4`='兽栏管理员', `FemaleText_loc5`='獸欄管理員', `FemaleText_loc7`='Maestro de establos' WHERE `ID`=8511;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도둑 소굴로 걸어 들어오는 것은 바보나 하는 짓이지. 그런데 그런 바보가 걸어 나가는 일도 거의 없단 말이지...', `MaleText_loc4`='只有傻子才会在不知不觉中进入贼窝。他是不可能出来的了……', `MaleText_loc5`='只有傻子才會在不知不覺中進入賊窩。他是不可能出來的了...', `MaleText_loc7`='Solo un necio entraría sin saberlo en una guarida de ladrones. Y, ese necio, casi nunca sale con vida...' WHERE `ID`=8512;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 세이크와를 찾아가셔야겠군요. 여관 앞에 서 있는 걸 마지막으로 본 것 같습니다.', `MaleText_loc4`='啊是的，你必须找到希克瓦。我记得我最后一次见她时她在旅馆前面站着。', `MaleText_loc5`='啊是的，你必須找到希克瓦。我記得我最後一次見她時她在旅館前面站著。', `MaleText_loc7`='Ah, sí, debes buscar a Seikwa. Creo que la última vez que la vi estaba fuera de la posada.', `FemaleText_loc1`='아, 세이크와를 찾아가셔야겠군요. 여관 앞에 서 있는 걸 마지막으로 본 것 같습니다.', `FemaleText_loc4`='啊是的，你必须找到希克瓦。我记得我最后一次见她时她在旅馆前面站着。', `FemaleText_loc5`='啊是的，你必須找到希克瓦。我記得我最後一次見她時她在旅館前面站著。', `FemaleText_loc7`='Ah, sí, debes buscar a Seikwa. Creo que la última vez que la vi estaba fuera de la posada.' WHERE `ID`=8513;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세이크와가 당신의 동물 친구를 돌봐줄 수 있을 겁니다. 여관 앞에서 찾아보십시오.', `MaleText_loc4`='希克瓦能在你需要的时候帮你照看宠物。去旅馆前面找她吧。', `MaleText_loc5`='希克瓦能在你需要的時候幫你照看寵物。去旅館前面找她吧。', `MaleText_loc7`='Seikwa puede encargarse de tus animales cuando tengas la necesidad. La encontrarás delante de la posada.', `FemaleText_loc1`='세이크와가 당신의 동물 친구를 돌봐줄 수 있을 겁니다. 여관 앞에서 찾아보십시오.', `FemaleText_loc4`='希克瓦能在你需要的时候帮你照看宠物。去旅馆前面找她吧。', `FemaleText_loc5`='希克瓦能在你需要的時候幫你照看寵物。去旅館前面找她吧。', `FemaleText_loc7`='Seikwa puede encargarse de tus animales cuando tengas la necesidad. La encontrarás delante de la posada.' WHERE `ID`=8514;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야수 관리인', `MaleText_loc4`='兽栏管理员', `MaleText_loc5`='獸欄管理員', `MaleText_loc7`='El maestro de establos', `FemaleText_loc1`='야수 관리인', `FemaleText_loc4`='兽栏管理员', `FemaleText_loc5`='獸欄管理員', `FemaleText_loc7`='El maestro de establos' WHERE `ID`=8515;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불루그의 도움이 필요하신 거로군요. 봉우리 하층에 있는 여관과 썬더 블러프 은행 사이에 있을 겁니다.', `MaleText_loc4`='你需要布尔鲁格的帮助。他在旅馆和雷霆崖银行间较低的山上。', `MaleText_loc5`='你需要布爾魯格的幫助。他在旅館和雷霆崖銀行間較低的山上。', `MaleText_loc7`='Necesitas la ayuda de Bulrug. Le encontrarás en la colina inferior, entre la posada y la Ribera de Cima del Trueno.', `FemaleText_loc1`='불루그의 도움이 필요하신 거로군요. 봉우리 하층에 있는 여관과 썬더 블러프 은행 사이에 있을 겁니다.', `FemaleText_loc4`='你需要布尔鲁格的帮助。他在旅馆和雷霆崖银行间较低的山上。', `FemaleText_loc5`='你需要布爾魯格的幫助。他在旅館和雷霆崖銀行間較低的山上。', `FemaleText_loc7`='Necesitas la ayuda de Bulrug. Le encontrarás en la colina inferior, entre la posada y la Ribera de Cima del Trueno.' WHERE `ID`=8516;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동물 친구들의 안녕에 그렇게 신경을 쓰이시나요? 당신은 참 좋은 분이시군요. 봉우리 하층에 있는 불루그가 도와드릴 수 있을 겁니다. 은행과 여관 사이에 있으니 한번 찾아보십시오.', `MaleText_loc4`='你对自己的宠物伙伴表现出的关爱之情是值得赞扬的。矮山上的布尔鲁格能帮助你照看宠物。他居住在银行和旅馆之间的地方，去找他吧。', `MaleText_loc5`='你對自己的寵物夥伴表現出的關愛之情是值得讚揚的。矮山上的布爾魯格能幫助你照看寵物。他居住在銀行和旅館之間的地方，去找他吧。', `MaleText_loc7`='La preocupación que sientes por el bienestar de tus compañeros animales es digna de elogio. Bulrug podrá ayudarte con eso, está en la colina inferior. Búscale entre la Ribera y la posada.', `FemaleText_loc1`='동물 친구들의 안녕에 그렇게 신경을 쓰이시나요? 당신은 참 좋은 분이시군요. 봉우리 하층에 있는 불루그가 도와드릴 수 있을 겁니다. 은행과 여관 사이에 있으니 한번 찾아보십시오.', `FemaleText_loc4`='你对自己的宠物伙伴表现出的关爱之情是值得赞扬的。矮山上的布尔鲁格能帮助你照看宠物。他居住在银行和旅馆之间的地方，去找他吧。', `FemaleText_loc5`='你對自己的寵物夥伴表現出的關愛之情是值得讚揚的。矮山上的布爾魯格能幫助你照看寵物。他居住在銀行和旅館之間的地方，去找他吧。', `FemaleText_loc7`='La preocupación que sientes por el bienestar de tus compañeros animales es digna de elogio. Bulrug podrá ayudarte con eso, está en la colina inferior. Búscale entre la Ribera y la posada.' WHERE `ID`=8517;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야수 관리인', `MaleText_loc4`='兽栏管理员', `MaleText_loc5`='獸欄管理員', `MaleText_loc7`='Maestro de establos', `FemaleText_loc1`='야수 관리인', `FemaleText_loc4`='兽栏管理员', `FemaleText_loc5`='獸欄管理員', `FemaleText_loc7`='Maestro de establos' WHERE `ID`=8518;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야수 관리인 모르가누스라면 당연히 마구간 앞에 서 있지...', `MaleText_loc4`='说也奇怪，兽栏管理员莫加努斯就在马厩外面。', `MaleText_loc5`='說也奇怪，獸欄管理員莫加努斯就在獸欄外面。', `MaleText_loc7`='Por extraño que parezca, podrás encontrar a Morganus, el maestro de establos, delante de los establos.', `FemaleText_loc1`='야수 관리인 모르가누스라면 당연히 마구간 앞에 서 있지...', `FemaleText_loc4`='说也奇怪，兽栏管理员莫加努斯就在马厩外面。', `FemaleText_loc5`='說也奇怪，獸欄管理員莫加努斯就在獸欄外面。', `FemaleText_loc7`='Por extraño que parezca, podrás encontrar a Morganus, el maestro de establos, delante de los establos.' WHERE `ID`=8519;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='눈치가 좀 느리군? 흠, 자네가 만약 야수 관리인이라면 어디에 있겠나? 마구간 근처로 가서 모르가누스를 찾아보게.', `MaleText_loc4`='你不算太聪明吧？嗯，如果我是兽栏管理员的话，我应该是在马厩附近吧？去那边找莫加努斯吧。', `MaleText_loc5`='你不算太聰明吧?嗯，如果我是獸欄管理員的話，我應該是在獸欄附近吧?去那邊找莫加努斯吧。', `MaleText_loc7`='¿No eres muy inteligente, eh? Mmm... Vamos a ver... Si fueras un maestro de establos, ¿no te parece que estarías cerca de los establos? Busca a Morganus allí.', `FemaleText_loc1`='눈치가 좀 느리군? 흠, 자네가 만약 야수 관리인이라면 어디에 있겠나? 마구간 근처로 가서 모르가누스를 찾아보게.', `FemaleText_loc4`='你不算太聪明吧？嗯，如果我是兽栏管理员的话，我应该是在马厩附近吧？去那边找莫加努斯吧。', `FemaleText_loc5`='你不算太聰明吧?嗯，如果我是獸欄管理員的話，我應該是在獸欄附近吧?去那邊找莫加努斯吧。', `FemaleText_loc7`='¿No eres muy inteligente, eh? Mmm... Vamos a ver... Si fueras un maestro de establos, ¿no te parece que estarías cerca de los establos? Busca a Morganus allí.' WHERE `ID`=8520;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야수 관리인', `MaleText_loc4`='兽栏管理员', `MaleText_loc5`='獸欄管理員', `MaleText_loc7`='El maestro de establos', `FemaleText_loc1`='야수 관리인', `FemaleText_loc4`='兽栏管理员', `FemaleText_loc5`='獸欄管理員', `FemaleText_loc7`='El maestro de establos' WHERE `ID`=8521;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안야 마울레이 상업 지구 위층 여관에 있다.', `MaleText_loc4`='安雅·玛尔雷在贸易区上层的旅馆中。', `MaleText_loc5`='安雅·瑪爾雷在貿易區上層的旅館中。', `MaleText_loc7`='Anya Maulray está en la posada del cinturón central del Barrio del Comercio.', `FemaleText_loc1`='안야 마울레이 상업 지구 위층 여관에 있다.', `FemaleText_loc4`='安雅·玛尔雷在贸易区上层的旅馆中。', `FemaleText_loc5`='安雅·瑪爾雷在貿易區上層的旅館中。', `FemaleText_loc7`='Anya Maulray está en la posada del cinturón central del Barrio del Comercio.' WHERE `ID`=8522;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 야수가 많으면 좋겠다. 야수 돌봐주는 거 안야 마울레이가 도와준다. 상업 지구 위층 여관에서 찾아봐라.', `MaleText_loc4`='我们想要很多宠物。安雅·玛尔雷能帮你照顾它们。去贸易区上层的旅馆找她吧。', `MaleText_loc5`='我們想要很多寵物。安雅·瑪爾雷能幫你照顧它們。去貿易區上層的旅館找她吧。', `MaleText_loc7`='Nosotros querer muchas mascotas. Anya Maulray ayudarte a cuidarlas. Tú encontrarla en posada, cinturón central del Barrio del Comercio.', `FemaleText_loc1`='우리 야수가 많으면 좋겠다. 야수 돌봐주는 거 안야 마울레이가 도와준다. 상업 지구 위층 여관에서 찾아봐라.', `FemaleText_loc4`='我们想要很多宠物。安雅·玛尔雷能帮你照顾它们。去贸易区 upper ring 的旅馆找她吧。', `FemaleText_loc5`='我們想要很多寵物。安雅·瑪爾雷能幫你照顧它們。去貿易區上層的旅館找她吧。', `FemaleText_loc7`='Nosotros querer muchas mascotas. Anya Maulray ayudarte a cuidarlas. Tú encontrarla en posada, cinturón central del Barrio del Comercio.' WHERE `ID`=8523;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야수 관리인', `MaleText_loc4`='兽栏管理员', `MaleText_loc5`='獸欄管理員', `MaleText_loc7`='Maestro de establos', `FemaleText_loc1`='야수 관리인', `FemaleText_loc4`='兽栏管理员', `FemaleText_loc5`='獸欄管理員', `FemaleText_loc7`='Maestro de establos' WHERE `ID`=8524;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야수 관리인', `MaleText_loc4`='兽栏管理员', `MaleText_loc5`='獸欄管理員', `MaleText_loc7`='Maestro de establos', `FemaleText_loc1`='야수 관리인', `FemaleText_loc4`='兽栏管理员', `FemaleText_loc5`='獸欄管理員', `FemaleText_loc7`='Maestro de establos' WHERE `ID`=8525;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소환수는 안심하고 알랏신에게 맡기셔도 좋습니다. 그는 사냥꾼들이 모이는 세나리온 자치령에 살고 있으니 그리로 가서 만나보도록 하십시오.', `MaleText_loc4`='阿拉辛是个值得信赖的人，让他来悉心照料你的任何宠物。他就住在猎人们聚集的塞纳里奥区。', `MaleText_loc5`='阿拉辛是個值得信賴的人，讓他來悉心照料你的任何寵物。他就住在獵人們聚集的塞納里奧區。', `MaleText_loc7`='Puedes confiar en que Alassin cuidará bien de tus mascotas. Vive en el Enclave Cenarion, donde se reúnen los cazadores.', `FemaleText_loc1`='소환수는 안심하고 알랏신에게 맡기셔도 좋습니다. 그는 사냥꾼들이 모이는 세나리온 자치령에 살고 있으니 그리로 가서 만나보도록 하십시오.', `FemaleText_loc4`='阿拉辛是个值得信赖的人，让他来悉心照料你的任何宠物。他就住在猎人们聚集的塞纳里奥区。', `FemaleText_loc5`='阿拉辛是個值得信賴的人，讓他來悉心照料你的任何寵物。他就住在獵人們聚集的塞納里奧區。', `FemaleText_loc7`='Puedes confiar en que Alassin cuidará bien de tus mascotas. Vive en el Enclave Cenarion, donde se reúnen los cazadores.' WHERE `ID`=8526;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알랏신은 수백 년 동안 사냥꾼이 길들인 야수를 돌봐왔습니다. 이 부근 사냥꾼들은 알랏신의 손길을 많이 찾지요. 그대도 알랏신을 찾는 거라면 세나리온 자치령으로 가보시기 바랍니다.', `MaleText_loc4`='数百年以来阿拉辛一直很关心我们猎人视作朋友的动物。他对动物的关心被周围的猎人所追随。如果你也来向他请教，那么就到塞纳里奥区找他。', `MaleText_loc5`='數百年以來阿拉辛一直很關心我們獵人視作朋友的動物。他對動物的關心被周圍的獵人所追隨。如果你也來向他請教，那麼就到塞納里奧區找他。', `MaleText_loc7`='Durante cientos de años, Alassin ha cuidado a los animales amigos de nuestros cazadores. Los cazadores de por aquí, siempre confían en Alassin para el cuidado de sus animales. Si también le estás buscando, hazlo en el Enclave Cenarion.', `FemaleText_loc1`='알랏신은 수백 년 동안 사냥꾼이 길들인 야수를 돌봐왔습니다. 이 부근 사냥꾼들은 알랏신의 손길을 많이 찾지요. 그대도 알랏신을 찾는 거라면 세나리온 자치령으로 가보시기 바랍니다.', `FemaleText_loc4`='数百年以来阿拉辛一直很关心我们猎人视作朋友的动物。他对动物的关心被周围的猎人所追随。如果你也来向他请教，那么就到塞纳里奥区找他。', `FemaleText_loc5`='數百年以來阿拉辛一直很關心我們獵人視作朋友的動物。他對動物的關心被周圍的獵人所追隨。如果你也來向他請教，那麼就到塞納里奧區找他。', `FemaleText_loc7`='Durante cientos de años, Alassin ha cuidado a los animales amigos de nuestros cazadores. Los cazadores de por aquí, siempre confían en Alassin para el cuidado de sus animales. Si también le estás buscando, hazlo en el Enclave Cenarion.' WHERE `ID`=8527;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 모두 하나의 커다란 퍼즐을 이루는 조각들이오, $n. 조각조각 모여 하나의 퍼즐을 맞춰나가듯이 우리도 서로 이끌어나가는 거요.$B$B그리고 우리를 이끌어주는 이들 역시 더욱 큰 세력의 이끌림을 받고 있는 것인지도 모르오.', `MaleText_loc4`='我们共同构成了一个巨大的拼图，$n。跟你一样，很多人都在进行小块拼图的整合工作。$B$B或许还有更强大的人正在将这些人当作拼图来玩。', `MaleText_loc5`='我們共同構成了一個巨大的拼圖，$n。跟你一樣，很多人都在進行小塊拼圖的整合工作。$B$B或許還有更強大的人正在將這些人當作拼圖來玩。', `MaleText_loc7`='Todos somos piezas de un puzle mucho mayor, $n. Al igual que tú guías la pieza de un puzle hacia su destino, también nosotros somos guiados por alguien.$B$BY, quizás, aquellos que nos guían a nosotros también son guiados por una fuerza superior.' WHERE `ID`=8528;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야수 관리인', `MaleText_loc4`='兽栏管理员', `MaleText_loc5`='獸欄管理員', `MaleText_loc7`='Maestro de establos', `FemaleText_loc1`='야수 관리인', `FemaleText_loc4`='兽栏管理员', `FemaleText_loc5`='獸欄管理員', `FemaleText_loc7`='Maestro de establos' WHERE `ID`=8529;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 상냥한 세리아드네 말이군요. 그녀가 보살피는 동물들은 모두 우리 안에 안전하게 살고 있지요. 돌라나르 여관 바로 밖에서 찾을 수 있을 겁니다.', `MaleText_loc4`='啊，友善的瑟里亚迪。在她的庇护下，所有动物都很安全。你可以在多兰纳尔的旅馆外找到她。', `MaleText_loc5`='啊，友善的瑟里亞迪。在她的庇護下，所有動物都很安全。你可以在多蘭納爾的旅館外找到她。', `MaleText_loc7`='Ah, gentil Seriadne. Todos los animales están a salvo a su cuidado. Podrás encontrarla justo fuera de la posada de Dolanaar.', `FemaleText_loc1`='아, 상냥한 세리아드네 말이군요. 그녀가 보살피는 동물들은 모두 우리 안에 안전하게 살고 있지요. 돌라나르 여관 바로 밖에서 찾을 수 있을 겁니다.', `FemaleText_loc4`='啊，友善的瑟里亚迪。在她的庇护下，所有动物都很安全。你可以在多兰纳尔的旅馆外找到她。', `FemaleText_loc5`='啊，友善的瑟里亞迪。在她的庇護下，所有動物都很安全。你可以在多蘭納爾的旅館外找到她。', `FemaleText_loc7`='Ah, gentil Seriadne. Todos los animales están a salvo a su cuidado. Podrás encontrarla justo fuera de la posada de Dolanaar.' WHERE `ID`=8530;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동물을 보살피는 사람을 찾으신다고요? 그렇다면 돌라나르의 여관 밖에 있는 세리아드네를 찾아보십시오. 그녀가 도와줄 수 있을 겁니다.', `MaleText_loc4`='你寻找一个喜欢动物的人？那么你应该到多兰纳尔旅馆的外面寻找瑟里亚迪。她就是你找的那个人。', `MaleText_loc5`='你尋找一個喜歡動物的人?那麼你應該到多蘭納爾旅館的外面尋找瑟里亞迪。她就是你找的那個人。', `MaleText_loc7`='¿Buscas a alguien que se preocupe por los animales? Entonces deberías buscar a Seriadne fuera de la posada de Dolanaar.', `FemaleText_loc1`='동물을 보살피는 사람을 찾으신다고요? 그렇다면 돌라나르의 여관 밖에 있는 세리아드네를 찾아보십시오. 그녀가 도와줄 수 있을 겁니다.', `FemaleText_loc4`='你寻找一个喜欢动物的人？那么你应该到多兰纳尔旅馆的外面寻找瑟里亚迪。她就是你找的那个人。', `FemaleText_loc5`='你尋找一個喜歡動物的人?那麼你應該到多蘭納爾旅館的外面尋找瑟里亞迪。她就是你找的那個人。', `FemaleText_loc7`='¿Buscas a alguien que se encargue de cuidar a tus animales? Pues deberías ir a ver a Seriadne, puedes encontrarla fuera de la posada de Dolanaar. Ella es la que estás buscando.' WHERE `ID`=8531;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='인심 좋은 엘마는 오랜 세월 동안 이곳 동물들을 보살펴 왔소. 당신이 동물을 맡긴다면 기꺼이 보살펴줄 거요. 엘마는 사자무리 여관 바로 밖에서 찾을 수 있소이다.', `MaleText_loc4`='好心的旅店老板艾玛，她现在已经照顾当地的动物好些年了。我敢肯定她会很高兴照顾你给的任何动物。你可以在狮王之傲旅店的外面找到她。', `MaleText_loc5`='好心的旅店老闆艾瑪，她現在已經照顧當地的動物好些年了。我敢肯定她會很高興照顧你給的任何動物。你可以在獅王之傲旅店的外面找到她。', `MaleText_loc7`='La buena de Erma, lleva años cuidando a los animales de la zona. Estoy seguro de que estará encantada de cuidar a tus animales. Puedes encontrarla justo fuera de la Posada Orgullo de León.', `FemaleText_loc1`='인심 좋은 엘마는 오랜 세월 동안 이곳 동물들을 보살펴 왔어요. 당신이 동물을 맡긴다면 기꺼이 보살펴줄 거예요. 엘마는 사자무리 여관 바로 밖에서 찾을 수 있습니다.', `FemaleText_loc4`='好心的旅店老板艾玛，她现在已经照顾当地的动物好些年了。我敢肯定她会很高兴照顾你给的任何动物。你可以在狮王之傲旅店的外面找到她。', `FemaleText_loc5`='好心的旅店老闆艾瑪，她現在已經照顧當地的動物好些年了。我敢肯定她會很高興照顧你給的任何動物。你可以在獅王之傲旅店的外面找到她。', `FemaleText_loc7`='La buena de Erma, lleva años cuidando a los animales de la zona. Estoy segura de que estará encantada de cuidar a tus animales. Puedes encontrarla justo fuera de la Posada Orgullo de León.' WHERE `ID`=8532;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 근처에서 동물을 보살피는 일이라면 엘마가 다 맡아서 하오. 사자무리 여관 바로 밖에 있을 테니 필요하면 찾아가 보시오.', `MaleText_loc4`='旅店老板艾玛照料着这周围的所有动物。要是你需要跟她交谈的话，就去狮王之傲旅店外面找她。', `MaleText_loc5`='旅店老闆艾瑪照料著這周圍的所有動物。要是你需要跟她交談的話，就去獅王之傲旅店外面找她。', `MaleText_loc7`='Erma se encarga del cuidado de los animales de la zona. Si necesitas hablar con ella, ahora está justo fuera de la Posada Orgullo de León.', `FemaleText_loc1`='이 근처에서 동물을 보살피는 일이라면 엘마가 다 맡아서 해요. 사자무리 여관 바로 밖에 있을 테니 필요하면 찾아가 보십시오.', `FemaleText_loc4`='旅店老板艾玛照料着这周围的所有动物。要是你需要跟她交谈的话，就去狮王之傲旅店外面找她。', `FemaleText_loc5`='旅店老闆艾瑪照料著這周圍的所有動物。要是你需要跟她交談的話，就去獅王之傲旅店外面找她。', `FemaleText_loc7`='Erma se encarga del cuidado de los animales de la zona. Si necesitas hablar con ella, ahora está justo fuera de la Posada Orgullo de León.' WHERE `ID`=8533;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야수 관리인', `MaleText_loc4`='兽栏管理员', `MaleText_loc5`='獸欄管理員', `MaleText_loc7`='Maestro de establos', `FemaleText_loc1`='야수 관리인', `FemaleText_loc4`='兽栏管理员', `FemaleText_loc5`='獸欄管理員', `FemaleText_loc7`='Maestro de establos' WHERE `ID`=8534;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 날 죽인 거냐, $n?', `MaleText_loc4`='你为什么要杀我，$n？', `MaleText_loc5`='你為什麼要殺我，$n?', `MaleText_loc7`='¿Por qué me has matado, $n?' WHERE `ID`=8535;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야수 관리인', `MaleText_loc4`='兽栏管理员', `MaleText_loc5`='獸欄管理員', `MaleText_loc7`='Maestro de establos', `FemaleText_loc1`='야수 관리인', `FemaleText_loc4`='兽栏管理员', `FemaleText_loc5`='獸欄管理員', `FemaleText_loc7`='Maestro de establos' WHERE `ID`=8536;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드워프 지구에 있는 제노바 스톤실드를 찾아가셔야 합니다. 사냥꾼들이 그녀의 아버지를 찾아가 훈련을 받는 동안 그녀가 동물들을 돌봐주곤 합니다.', `MaleText_loc4`='矮人区的耶诺瓦·石盾是你要找的人。在猎人接受她父亲的训练时，她帮着照看猎人的宠物。', `MaleText_loc5`='矮人區的耶諾瓦·石盾是你要找的人。在獵人接受她父親的訓練時，她幫著照看獵人的寵物。', `MaleText_loc7`='Tienes que buscar a Jenova Petrescudo, está en el Distrito de los Enanos. Se encarga de cuidar a las mascotas de los cazadores mientras su padre las entrena.', `FemaleText_loc1`='드워프 지구에 있는 제노바 스톤실드를 찾아가셔야 해요. 사냥꾼들이 그녀의 아버지를 찾아가 훈련을 받는 동안 그녀가 동물들을 돌봐주곤 하지요.', `FemaleText_loc4`='矮人区的耶诺瓦·石盾是你要找的人。在猎人接受她父亲的训练时，她帮着照看猎人的宠物。', `FemaleText_loc5`='矮人區的耶諾瓦·石盾是你要找的人。在獵人接受她父親的訓練時，她幫著照看獵人的寵物。', `FemaleText_loc7`='Tienes que buscar a Jenova Petrescudo, está en el Distrito de los Enanos. Se encarga de cuidar a las mascotas de los cazadores mientras su padre las entrena.' WHERE `ID`=8537;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야수 훈련을 위해 다른 야수를 맡길 곳이 필요하다면 저기 드워프 지구에 있는 제노바 스톤실드를 찾아가 보십시오.', `MaleText_loc4`='如果你需要将宠物关在屋内，以便训练另一只宠物的话，就去矮人区找耶诺瓦·石盾谈谈。', `MaleText_loc5`='如果你需要將寵物關在屋內，以便訓練另一隻寵物的話，就去矮人區找耶諾瓦·石盾談談。', `MaleText_loc7`='Si necesitas un alojamiento para tu mascota mientras estás entrenando a otra, deberías hablar con Jenova Petrescudo, en el Distrito de los Enanos.', `FemaleText_loc1`='야수 훈련을 위해 다른 야수를 맡길 곳이 필요하다면 저기 드워프 지구에 있는 제노바 스톤실드를 찾아가 보십시오.', `FemaleText_loc4`='如果你需要将宠物关在屋内，以便训练另一只宠物的话，就去矮人区找耶诺瓦·石盾谈谈。', `FemaleText_loc5`='如果你需要將寵物關在屋內，以便訓練另一隻寵物的話，就去矮人區找耶諾瓦·石盾談談。', `FemaleText_loc7`='Si necesitas un alojamiento para tu mascota mientras estás entrenando a otra, deberías hablar con Jenova Petrescudo, en el Distrito de los Enanos.' WHERE `ID`=8538;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야수 관리인', `MaleText_loc4`='兽栏管理员', `MaleText_loc5`='獸欄管理員', `MaleText_loc7`='Maestro de establos', `FemaleText_loc1`='야수 관리인', `FemaleText_loc4`='兽栏管理员', `FemaleText_loc5`='獸欄管理員', `FemaleText_loc7`='Maestro de establos' WHERE `ID`=8539;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카라노스 썬더브루 양조장 바로 밖에 있는 셸비 스톤플린트를 찾아가 보세요. 당신이 맡기는 동물을 아주 잘 돌봐줄 겁니다.', `MaleText_loc4`='$g小伙子:姑娘;，你可以去卡拉诺斯雷酒酿制厂外找谢尔比·石火。她会好好照顾你的宠物的。', `MaleText_loc5`='$g小夥子:姑娘;，你可以去卡拉諾斯雷酒釀酒廠外找謝爾比·石火。她會好好照顧你的寵物的。', `MaleText_loc7`='Bueno, bueno $gmuchacho:muchacha;, puedes encontrar a Shelby Petrepiedra justo fuera de la Destilería Cebatruenos en Kharanos. Cuidará bien de tus mascotas.', `FemaleText_loc1`='카라노스 썬더브루 양조장 바로 밖에 있는 셸비 스톤플린트를 찾아가 보세요. 당신이 맡기는 동물을 아주 잘 돌봐줄 겁니다.', `FemaleText_loc4`='$g小伙子:姑娘;，你可以去卡拉诺斯雷酒酿制厂外找谢尔比·石火。她会好好照顾你的宠物的。', `FemaleText_loc5`='$g小夥子:姑娘;，你可以去卡拉諾斯雷酒釀酒廠外找謝爾比·石火。她會好好照顧你的寵物的。', `FemaleText_loc7`='Bueno, bueno $gmuchacho:muchacha;, puedes encontrar a Shelby Petrepiedra justo fuera de la Destilería Cebatruenos en Kharanos. Cuidará bien de tus mascotas.' WHERE `ID`=8540;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='셸비 스톤플린트가 이 지역 사냥꾼들의 동물을 꽤나 많이 보살피고 있지요. 당신도 도움이 필요하다면 썬더브루 양조장 쪽에 있는 셸비를 한번 찾아가 보세요.', `MaleText_loc4`='谢尔比·石火帮当地猎人看管宠物。如果你想让她帮你照看宠物的话，就去雷酒酿制厂找她吧。', `MaleText_loc5`='謝爾比·石火幫當地獵人看管寵物。如果你想讓她幫你照看寵物的話，就去雷酒釀酒廠找她吧。', `MaleText_loc7`='Shelby Petrepiedra da alojamiento a muchas de las mascotas de los cazadores locales. Está en la Destilería Cebatruenos. Vete a hablar con ella si quieres que te cuide alguna mascota.', `FemaleText_loc1`='셸비 스톤플린트가 이 지역 사냥꾼들의 동물을 꽤나 많이 보살피고 있지요. 당신도 도움이 필요하다면 썬더브루 양조장 쪽에 있는 셸비를 한번 찾아가 보세요.', `FemaleText_loc4`='谢尔比·石火帮当地猎人看管宠物。如果你想让她帮你照看宠物的话，就去雷酒酿制厂找她吧。', `FemaleText_loc5`='謝爾比·石火幫當地獵人看管寵物。如果你想讓她幫你照看寵物的話，就去雷酒釀酒廠找她吧。', `FemaleText_loc7`='Shelby Petrepiedra da alojamiento a muchas de las mascotas de los cazadores locales. Está en la Destilería Cebatruenos. Vete a hablar con ella si quieres que te cuide alguna mascota.' WHERE `ID`=8541;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야수 관리인', `MaleText_loc4`='兽栏管理员', `MaleText_loc5`='獸欄管理員', `MaleText_loc7`='Maestro de establos', `FemaleText_loc1`='야수 관리인', `FemaleText_loc4`='兽栏管理员', `FemaleText_loc5`='獸欄管理員', `FemaleText_loc7`='Maestro de establos' WHERE `ID`=8542;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='울브렉 파이어핸드는 다른 일이라면 몰라도 동물 보살피는 일이라면 아주 진지하게 생각하죠. 울브렉은 전투의 전당에서 사냥꾼들과 자주 어울리는 모양이니 동물을 돌봐줄 자가 필요하다면 그를 찾아가 보십시오.', `MaleText_loc4`='乌布雷克·火拳总是极其认真地照顾动物。如果你想让他帮你照看宠物的话，就去武器大厅找他吧，他通常跟那些猎人在一起。', `MaleText_loc5`='烏布雷克·火拳總是極其認真地照顧動物。如果你想讓他幫你照看寵物的話，就去武器大廳找他吧，他通常跟那些獵人在一起。', `MaleText_loc7`='Ulbrek Manofuego se toma muy en serio el cuidado de los animales. Si quieres que te cuide alguna mascota, generalmente está con los cazadores en la Sala de Armas.', `FemaleText_loc1`='울브렉 파이어핸드는 다른 일이라면 몰라도 동물 보살피는 일이라면 아주 진지하게 생각하죠. 울브렉은 전투의 전당에서 사냥꾼들과 자주 어울리는 모양이니 동물을 돌봐줄 자가 필요하다면 그를 찾아가 보십시오.', `FemaleText_loc4`='乌布雷克·火拳总是极其认真地照顾动物。如果你想让他帮你照看宠物的话，就去武器大厅找他吧，他通常跟那些猎人在一起。', `FemaleText_loc5`='烏布雷克·火拳總是極其認真地照顧動物。如果你想讓他幫你照看寵物的話，就去武器大廳找他吧，他通常跟那些獵人在一起。', `FemaleText_loc7`='Ulbrek Manofuego se toma muy en serio el cuidado de los animales. Si quieres que te cuide alguna mascota, generalmente está con los cazadores en la Sala de Armas.' WHERE `ID`=8543;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투의 전당으로 가면 이 지역 야수 관리인 울브렉 파이어핸드가 있어요. 동물을 맡기면 잘 먹이면서 정성껏 보살펴줄 겁니다.', `MaleText_loc4`='你可以在武器大厅找到我们的常驻马厩管理人乌布雷克·火拳。他将替你喂养和照料宠物。', `MaleText_loc5`='你可以在武器大廳找到我們的常駐獸欄管理人烏布雷克·火拳。他將替你餵養和照料寵物。', `MaleText_loc7`='Puedes encontrar a nuestro maestro de establos residente, Ulbrek Manofuego en la Sala de Armas. Él se encargará de que tus mascotas estén bien alimentadas y cuidadas.', `FemaleText_loc1`='전투의 전당으로 가면 이 지역 야수 관리인 울브렉 파이어핸드가 있어요. 동물을 맡기면 잘 먹이면서 정성껏 보살펴줄 겁니다.', `FemaleText_loc4`='你可以在武器大厅找到我们的常驻马厩管理人乌布雷克·火拳。他将替你喂养和照料宠物。', `FemaleText_loc5`='你可以在武器大廳找到我們的常駐獸欄管理人烏布雷克·火拳。他將替你餵養和照料寵物。', `FemaleText_loc7`='Puedes encontrar a nuestro maestro de establos residente, Ulbrek Manofuego en la Sala de Armas. Él se encargará de que tus mascotas estén bien alimentadas y cuidadas.' WHERE `ID`=8544;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다 이겼다고 생각하느냐? 또 다른 고통의 맛을 가르쳐 주어야겠군.', `MaleText_loc4`='你以为你赢了？可能你需要另一堂痛苦的课程！', `MaleText_loc5`='你以為你贏了?可能你需要另一堂痛苦的課程!', `MaleText_loc7`='¿Creéis que ya habéis ganado? ¡Pues yo creo que necesitáis otra lección de dolor!' WHERE `ID`=8545;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와주시오, 경비병! 이러다 깔려 죽겠다고!', `MaleText_loc4`='帮帮我！守卫！就要踩到我啦！', `MaleText_loc5`='幫幫我!守衛!就要踩到我啦!', `MaleText_loc7`='¡Socorro! ¡Guardias! ¡Me va a pisar!', `FemaleText_loc1`='도와주시오, 경비병! 이러다 깔려 죽겠다고!', `FemaleText_loc4`='帮帮我！守卫！就要踩到我啦！', `FemaleText_loc5`='幫幫我!守衛!就要踩到我啦!', `FemaleText_loc7`='¡Socorro! ¡Guardias! ¡Me va a pisar!' WHERE `ID`=8546;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 당신에게 드릴 것이 있습니다. 꽤 중요한 것이라고 할 수 있지요.', `MaleText_loc4`='我给你带来一些东西，$n。它们看起来挺重要的。', `MaleText_loc5`='我給你帶來一些東西，$n。它們看起來挺重要的。', `MaleText_loc7`='Tengo algo para ti, $n. Parece importante.', `FemaleText_loc1`='$n, 당신에게 드릴 것이 있습니다. 꽤 중요한 것이라고 할 수 있지요.', `FemaleText_loc4`='我给你带来一些东西，$n。它们看起来挺重要的。', `FemaleText_loc5`='我給你帶來一些東西，$n。它們看起來挺重要的。', `FemaleText_loc7`='Tengo algo para ti, $n. Parece importante.' WHERE `ID`=8547;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이리 주십시오.', `MaleText_loc4`='请问，我能拿走它吗？', `MaleText_loc5`='請問，我能拿走它嗎?', `MaleText_loc7`='¿Me lo puedes dar, por favor?', `FemaleText_loc1`='이리 주십시오.', `FemaleText_loc4`='请问，我能拿走它吗？', `FemaleText_loc5`='請問，我能拿走它嗎?', `FemaleText_loc7`='¿Me lo puedes dar, por favor?' WHERE `ID`=8548;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님, SI:7 본부에 온 걸 환영합니다.', `MaleText_loc4`='欢迎来到军情七处总部，$n。', `MaleText_loc5`='歡迎來到軍情七處總部，$n。', `MaleText_loc7`='Te doy la bienvenida al puesto de mando del IV:7, $n.' WHERE `ID`=8549;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 아침 당신 앞으로 이것이 왔습니다.', `MaleText_loc4`='$n，这是今天早上送来给你的。', `MaleText_loc5`='$n，這是今天早上送來給你的。', `MaleText_loc7`='Ha llegado esto para ti por la mañana, $n.' WHERE `ID`=8550;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라벤홀트 장원에서 온 사절이 오늘 아침 제게 이 편지를 건네주더군요. 수신인이 당신으로 되어 있습니다, $n.', `MaleText_loc4`='拉文霍德的信使今天早上将这封信交给了我。这是写给你的，$n。', `MaleText_loc5`='拉文霍德的信差今天早上將這封信交給了我。這是寫給你的，$n。', `MaleText_loc7`='Unos mensajeros de Ravenholdt me han entregado esta carta hoy por la mañana. Va dirigida a ti, $n.', `FemaleText_loc1`='라벤홀트 장원에서 온 사절이 오늘 아침 제게 이 편지를 건네주더군요. 수신인이 당신으로 되어 있습니다, $n.', `FemaleText_loc4`='拉文霍德的信使今天早上将这封信交给了我。这是写给你的，$n。', `FemaleText_loc5`='拉文霍德的信差今天早上將這封信交給了我。這是寫給你的，$n。', `FemaleText_loc7`='Unos mensajeros de Ravenholdt me han entregado esta carta hoy por la mañana. Va dirigida a ti, $n.' WHERE `ID`=8551;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기운 내십시오! 고통은 사라지기 마련이고 약간의 흉터라면 이성에게 호감을 살 수도 있으니까요!', `MaleText_loc4`='振作起来！疼痛会消失的，$g女人喜欢有伤疤的男人:男人喜欢有伤疤的女人;！', `MaleText_loc5`='振作起來!疼痛會消失的，$g女人喜歡有傷疤的男人:男人喜歡有傷疤的女人;!', `MaleText_loc7`='¡Anímate! ¡El dolor desaparece y a $glas damas les gustan los hombres con cicatrices:los hombres les gustan las damas con cicatrices;!', `FemaleText_loc1`='기운 내십시오! 고통은 사라지기 마련이고 약간의 흉터라면 이성에게 호감을 살 수도 있으니까요!', `FemaleText_loc4`='振作起来！疼痛会消失的，$g女人喜欢有伤疤的男人:男人喜欢有伤疤的女人;！', `FemaleText_loc5`='振作起來!疼痛會消失的，$g女人喜歡有傷疤的男人:男人喜歡有傷疤的女人;!', `FemaleText_loc7`='¡Anímate! ¡El dolor desaparece y a $glas damas les gustan los hombres con cicatrices:los hombres les gustan las damas con cicatrices;!' WHERE `ID`=8552;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='치료가 필요합니다.', `MaleText_loc4`='我需要帮助。', `MaleText_loc5`='我需要幫助。', `MaleText_loc7`='Necesito ayuda.', `FemaleText_loc1`='치료가 필요합니다.', `FemaleText_loc4`='我需要帮助。', `FemaleText_loc5`='我需要幫助。', `FemaleText_loc7`='Necesito ayuda.' WHERE `ID`=8553;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적에게 우리의 힘을 보여 주십시오. 그러면 승리를 맛보게 될 겁니다!', `MaleText_loc4`='让敌人见识见识你的力量，我们会取胜的！', `MaleText_loc5`='讓敵人見識見識你的力量，我們會取勝的!', `MaleText_loc7`='Demuestra tu fuerza a tu enemigo, ¡y venceremos!', `FemaleText_loc1`='적에게 우리의 힘을 보여 주십시오. 그러면 승리를 맛보게 될 겁니다!', `FemaleText_loc4`='让敌人见识见识你的力量，我们会取胜的！', `FemaleText_loc5`='讓敵人見識見識你的力量，我們會取勝的!', `FemaleText_loc7`='Demuestra tu fuerza a tu enemigo, ¡y venceremos!' WHERE `ID`=8554;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘든 싸움이 될 걸세, $n. 내 뒤에 바짝 붙어 따라오라고!', `MaleText_loc4`='这将是一场艰难的战事，$n。跟我来吧！', `MaleText_loc5`='這將是一場艱難的戰事，$n。跟我來吧!', `MaleText_loc7`='Esta pelea no va a ser fácil, $n. ¡Sígueme muy de cerca!' WHERE `ID`=8555;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 그 화로라네, $n. 꺼 버리게나. 보르샤는 그 누구에게도 찬미를 받을 자격이 없는 괴물에 불과해!', `MaleText_loc4`='这是火盆，$n。熄灭它。沃尔沙是一头野兽，不值得任何人赞扬！', `MaleText_loc5`='這是火盆，$n。熄滅它。沃爾沙是一頭野獸，不值得任何人讚揚!', `MaleText_loc7`='Este es el brasero, $n. Apágalo. Vorsha es una bestia, ¡no se merece que nadie le alabe!' WHERE `ID`=8556;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런, 여기에 없잖아. 마지막으로 내가 그걸 어디 뒀더라...', `MaleText_loc4`='呸！不在这儿。让我想想上次把它放在哪儿了……', `MaleText_loc5`='呸!不在這兒。讓我想想上次把它放在哪兒了...', `MaleText_loc7`='¡Bah, no está aquí! Me pregunto dónde lo habré dejado...' WHERE `ID`=8557;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 깊은 감사의 마음을 전하네. 정말 고맙네.', `MaleText_loc4`='我对你表示最深的感激，谢谢你。', `MaleText_loc5`='對你表示最深的感激。謝謝你。', `MaleText_loc7`='Te lo agradezco de todo corazón. Gracias.' WHERE `ID`=8558;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디 보자... 그 부록을 어디다 뒀지?', `MaleText_loc4`='我把勇士的资料放在哪儿了？', `MaleText_loc5`='我把夥伴的資料放在哪兒了?', `MaleText_loc7`='¿Pero dónde habré metido ese documento del manual?' WHERE `ID`=8559;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무지하게 지루한 이야기군. 책에 왜 그렇게 먼지가 많이 쌓여 있었는지 알겠어.', `MaleText_loc4`='相当引人入胜的故事。现在我知道为什么那本书上积了那么多灰尘了。', `MaleText_loc5`='相當引人入勝的故事。現在我知道為什麼那本書上積了那麼多灰塵了。', `MaleText_loc7`='¡Muy interesante! Ahora sé por qué había tanto polvo en ese libro.' WHERE `ID`=8560;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정리할 책은 이렇게 많은데 시간이 너무 없구만...', `MaleText_loc4`='这么多的书架，时间却如此紧迫……', `MaleText_loc5`='這麼多的書架，時間卻如此緊迫...', `MaleText_loc7`='Demasiadas estanterías, demasiado poco tiempo...' WHERE `ID`=8561;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='책들을 더 효율적으로 정리할 수 있는 기록 체계 같은 게 필요하니 듀위에게 얘기해 보는 게 좋겠군.', `MaleText_loc4`='我该告诉杜威关于符号系统的一些知识，让他更好地摆放这些书。', `MaleText_loc5`='我該告訴杜威關於編碼系統的一些知識，讓他能更妥善地排放這些書籍。', `MaleText_loc7`='Debería hablar con Dewey a ver si conseguimos crear algún tipo de sistema de notación para que los libros estén mejor organizados.' WHERE `ID`=8562;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고블린이 쓴 노움의 군사적 승리에 대한 책이라... 아니, 그런데 이게 뭐야? 모든 페이지가 백지로군. 내 그럴 줄 알았어.', `MaleText_loc4`='地精写的关于侏儒的军事胜利的书……而所有的纸张都是空白的。数字。', `MaleText_loc5`='哥布林寫的關於地精的軍事勝利的書...而所有的紙張都是空白的。數字。', `MaleText_loc7`='Un libro escrito por un goblin sobre victorias militares de los gnomos... y todas las páginas están en blanco. Típico.' WHERE `ID`=8563;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 얼마간 이 지역을 좀 더 정찰하면서 치안안전에 전력을 기울여야겠네.', `MaleText_loc4`='我会再巡视这片地区一会儿并确保一切安全。', `MaleText_loc5`='我會再巡視這片地區一會兒並確保一切安全。', `MaleText_loc7`='Voy a seguir patrullando la zona un rato más para asegurarme de que todo está bien.' WHERE `ID`=8564;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 조람가르로 돌아가서 전쟁노래 길잡이에게 우리의 성공을 보고하도록 하게나.', `MaleText_loc4`='请回到佐拉姆加前哨站，向战歌信使汇报我们的成功。', `MaleText_loc5`='請回到佐拉姆加前哨站，向戰歌信差彙報我們的成功。', `MaleText_loc7`='Por favor, vete a Zoram''gar e informa sobre nuestro éxito al corredor Grito de Guerra.' WHERE `ID`=8565;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네, 준비가 끝난 게 확실한가? 우리를 도와 줄 자네 동료가 모이지 않으면 분명히 패배하게 될 걸세.', `MaleText_loc4`='你确信自己已准备就绪？要是没有你的帮助，我们一定会失败的。', `MaleText_loc5`='你確信自己已準備就緒?要是沒有你的幫助，我們一定會失敗的。', `MaleText_loc7`='¿Seguro que estás $gpreparado:preparada;? Si no tenemos un grupo de tus aliados que nos ayude, perderemos.' WHERE `ID`=8566;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거대한 야수가 가까이 다가오는 것이 느껴지는군...', `MaleText_loc4`='我感到那头巨大的野兽正在逼近……', `MaleText_loc5`='我感到巨大的野獸逼近了...', `MaleText_loc7`='Siento que la gran bestia se acerca...' WHERE `ID`=8567;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기 수면을 보게!', `MaleText_loc4`='看水面！', `MaleText_loc5`='看水面!', `MaleText_loc7`='¡Mira, en la superficie del agua!' WHERE `ID`=8568;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 해냈군!', `MaleText_loc4`='我们成功了！', `MaleText_loc5`='我們做到了!', `MaleText_loc7`='¡Lo hemos conseguido!' WHERE `ID`=8569;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나를 알로부터 유인해 내려고 하다니! 그 무례함을 용서하지 않겠다. 반드시 대가를 치르게 해 주지!', `FemaleText_loc4`='你们这些渣滓居然想要挑战我？你们会为你们的傲慢付出代价的！', `FemaleText_loc5`='你試圖引誘我放開爪子?你會為你的傲慢付出代價的!', `FemaleText_loc7`='¿Pretendes apartarme de mi nidada? ¡Pagarás por tu insolencia!' WHERE `ID`=8570;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$C|1이여;여;, 보고를 하러 온 거요?', `MaleText_loc4`='什么事，$c？你在汇报吗？', `MaleText_loc5`='什麼事，$c?你在彙報嗎?', `MaleText_loc7`='¿Sí, $c? ¿Vienes a informar?' WHERE `ID`=8571;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나의 종들아! 어서 나와 주인을 돕거라!', `MaleText_loc4`='出现吧，我的奴仆！保卫你们的主人！', `MaleText_loc5`='出現吧，我的奴僕! 保衛你們的主人!', `MaleText_loc7`='¡AVANCEN, MIS SIRVIENTES! ¡DEFIENDAN A SU MAESTRO!' WHERE `ID`=8572;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누구도 살아있는 불꽃을 꺾을 수는 없다! 나타나라! 불의 신하들이여! 나오너라! 증오의 피조물들이여! 네 주인이 부르노라!', `MaleText_loc4`='你们不是烈焰之王的敌人！出现吧，火焰的奴仆！你们的主人在召唤你们！', `MaleText_loc5`='你們不是烈焰之王的敵人!出現吧，火焰的奴僕!你們的主人在召喚你們!', `MaleText_loc7`='¡NO PUEDEN VENCER A LA LLAMA VIVIENTE! ¡VENGAN, ESCLAVOS DEL FUEGO! ¡AVANCEN, CRIATURAS DEL ODIO! ¡SU MAESTRO LOS LLAMA!' WHERE `ID`=8573;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들을 처치하라!!!', `MaleText_loc4`='干掉他们！', `MaleText_loc5`='擊碎他們!!!', `MaleText_loc7`='¡¡¡Aplastadles!!!' WHERE `ID`=8574;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='병사들이여, 녀석들을 쳐부숴라!', `MaleText_loc4`='士兵们，干掉他们！', `MaleText_loc5`='士兵們，幹掉他們!', `MaleText_loc7`='¡SOLDADOS, ACABEN CON ELLOS!' WHERE `ID`=8575;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들을 자기들의 요새로 쫓아내라! 이 전장에서 단 한 명의 얼라 놈도 살려 두지 마라!', `MaleText_loc4`='将他们逼回基地去！将战场上的联盟士兵统统杀死！', `MaleText_loc5`='將他們逼回基地去!將戰場上的聯盟士兵統統殺死!', `MaleText_loc7`='¡Haced que retrocedan hasta su base! ¡Que no quede vivo ni un Soldado de la Alianza en este campo de batalla!' WHERE `ID`=8576;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부관과 지휘관들 주위로 집결하라! 요새를 수호하라!', `MaleText_loc4`='团结在中尉和指挥官身边！保护我们的基地！', `MaleText_loc5`='團結在中尉和指揮官身邊!保護我們的基地!', `MaleText_loc7`='¡Reúne a tus Tenientes y Comandantes! ¡Proteged nuestras bases!' WHERE `ID`=8577;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='청기기 준비 완료', `MaleText_loc4`='管理者埃克索图斯被激活。', `MaleText_loc5`='管理者埃克索圖斯被啟動。', `MaleText_loc7`='Major Domo activado.' WHERE `ID`=8578;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼음이빨 광산은 누가 점령하고 있습니까?', `MaleText_loc4`='谁控制着冷齿矿洞？', `MaleText_loc5`='誰控制著冷齒礦坑?', `MaleText_loc7`='¿Quién controla la Mina Dentefrío?', `FemaleText_loc1`='얼음이빨 광산은 누가 점령하고 있습니까?', `FemaleText_loc4`='谁控制着冷齿矿洞？', `FemaleText_loc5`='誰控制著冷齒礦坑?', `FemaleText_loc7`='¿Quién controla la Mina Dentefrío?' WHERE `ID`=8579;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼음이빨 광산은 코볼트들이 점령하고 있습니다.', `MaleText_loc4`='冷齿矿洞为狗头人所有。', `MaleText_loc5`='冷齒礦坑為狗頭人所有。', `MaleText_loc7`='La Mina Dentefrío pertenece a los kóbolds.' WHERE `ID`=8580;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼음이빨 광산은 얼라이언스가 점령하고 있습니다.', `MaleText_loc4`='冷齿矿洞为联盟所有。', `MaleText_loc5`='冷齒礦坑為聯盟所有。', `MaleText_loc7`='La Mina Dentefrío pertenece a la Alianza.' WHERE `ID`=8581;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼음이빨 광산은 호드가 점령하고 있습니다.', `MaleText_loc4`='冷齿矿洞为部落所有。', `MaleText_loc5`='冷齒礦坑為部落所有。', `MaleText_loc7`='La Mina Dentefrío pertenece a la Horda.' WHERE `ID`=8582;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼음이빨 광산은 호드의 영토에 있으며 서리늑대 무덤에서 북쪽 산맥에 있습니다.$B$B현재 얼라이언스가 점령하고 있습니다.', `MaleText_loc4`='部落领地中的冷齿矿洞就在霜狼墓地以北的山脉脚下。$B$B它现在被联盟控制着。', `MaleText_loc5`='部落領地中的冷齒礦坑就在霜狼墓地以北的山脈腳下。$B$B它現在被聯盟控制著。', `MaleText_loc7`='La Mina Dentefrío se encuentra en territorio de la Horda, en las montañas que están al norte del Cementerio Lobo Gélido.$B$BEstá controlada por la Alianza.' WHERE `ID`=8583;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼음이빨 광산은 호드의 영토에 있으며 서리늑대 무덤에서 북쪽 산맥에 있습니다.$B$B현재 호드가 점령하고 있습니다.', `MaleText_loc4`='部落领地中的冷齿矿洞就在霜狼墓地以北的山脉脚下。$B$B它现在被部落控制着。', `MaleText_loc5`='部落領地中的冷齒礦坑就在霜狼墓地以北的山脈腳下。$B$B它現在被部落控制著。', `MaleText_loc7`='La Mina Dentefrío está en territorio de la Horda, en las montañas al norte del Cementerio Lobo Gélido.$B$BPertenece a la Horda.' WHERE `ID`=8584;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼음이빨 광산은 호드의 영토에 있으며 서리늑대 무덤에서 북쪽 산맥에 있습니다.$B$B현재 코볼트들이 점령하고 있습니다.', `MaleText_loc4`='部落领地中的冷齿矿洞就在霜狼墓地以北的山脉脚下。$B$B它现在被狗头人控制着。', `MaleText_loc5`='部落領地中的冷齒礦坑就在霜狼墓地以北的山脈腳下。$B$B它現在被狗頭人控制著。', `MaleText_loc7`='La Mina Dentefrío está en territorio de la Horda, en las montañas al norte del Cementerio Lobo Gélido.$B$BPertenece a los kóbolds.' WHERE `ID`=8585;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='깊은무쇠 광산은 누가 점령하고 있습니까?', `MaleText_loc4`='谁控制着深铁矿洞？', `MaleText_loc5`='誰控制著深鐵礦坑?', `MaleText_loc7`='¿Quién controla la Mina Ferrohondo?', `FemaleText_loc1`='깊은무쇠 광산은 누가 점령하고 있습니까?', `FemaleText_loc4`='谁控制着深铁矿洞？', `FemaleText_loc5`='誰控制著深鐵礦坑?', `FemaleText_loc7`='¿Quién controla la Mina Ferrohondo?' WHERE `ID`=8586;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='깊은무쇠 광산은 얼라이언스 영토에 있으며 스톰파이크 무덤의 북쪽에 있습니다.$B$B현재 얼라이언스가 점령하고 있습니다.', `MaleText_loc4`='联盟领地中的深铁矿洞就在雷矛墓地北边。$B$B它现在被联盟控制着。', `MaleText_loc5`='聯盟領地中的深鐵礦坑就在雷矛墓地北邊。$B$B它現在被聯盟控制著。', `MaleText_loc7`='La Mina Ferrohondo está en territorio de la Alianza, al norte del Cementerio Pico Tormenta.$B$BPertenece a la Alianza.' WHERE `ID`=8587;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='깊은무쇠 광산은 얼라이언스 영토에 있으며 스톰파이크 무덤의 북쪽에 있습니다.$B$B현재 호드가 점령하고 있습니다.', `MaleText_loc4`='联盟领地中的深铁矿洞就在雷矛墓地北边。$B$B它现在被部落控制着。', `MaleText_loc5`='聯盟領地中的深鐵礦坑就在雷矛墓地北邊。$B$B它現在被部落控制著。', `MaleText_loc7`='La Mina Ferrohondo está en territorio de la Alianza, al norte del Cementerio Pico Tormenta.$B$BPertenece a la Horda.' WHERE `ID`=8588;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='깊은무쇠 광산은 얼라이언스 영토에 있으며 스톰파이크 무덤의 북쪽에 있습니다.$B$B현재 트로그들이 점령하고 있습니다.', `MaleText_loc4`='联盟领地中的深铁矿洞就在雷矛墓地北边。$B$B它现在被穴居人控制着。', `MaleText_loc5`='聯盟領地中的深鐵礦坑就在雷矛墓地北邊。$B$B它現在被穴居怪控制著。', `MaleText_loc7`='La Mina Ferrohondo está en territorio de la Alianza, al norte del Cementerio Pico Tormenta.$B$BPertenece a los troggs.' WHERE `ID`=8589;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 기념비는 스톰윈드를 수호하다 쓰러져 간 모든 이들에게 바쳐진 것이다. 우리 종족은 자유를 지키고 스스로 운명에 대한 주도권을 잃지 않기 위해 믿을 수 없을 정도의 고난을 극복해 왔다. 바로 이곳에서 우리 종족을 휩쓸고 간 1차 대전쟁 중에 있었던 시민들의 모든 희생을 기념하는 것이다.', `MaleText_loc4`='这座纪念碑是用于缅怀在暴风城保卫战中牺牲的勇士。我们的人民经受了难以想象的痛苦才得以恢复自由，重新掌握自己的命运。我们将永远铭记那些在第一次兽人战争中牺牲的同胞。', `MaleText_loc5`='這座紀念碑是用於緬懷在暴風城保衛戰中犧牲的勇士。我們的人民經受了難以想像的痛苦才得以恢復自由，重新掌握自己的命運。我們將永遠銘記那些在第一次獸人戰爭中犧牲的同胞。', `MaleText_loc7`='Este monumento está dedicado a todos los que dieron su vida por proteger Ventormenta. Nuestro pueblo ha tenido que sufrir increíbles dificultades para mantener su libertad y para poder controlar su propio destino. Aquí es donde recordamos los sacrificios que nuestros ciudadanos hicieron durante la primera guerra que destrozó a nuestro pueblo.' WHERE `ID`=8590;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='깊은무쇠 광산은 얼라이언스가 점령하고 있습니다.', `MaleText_loc4`='深铁矿洞为联盟所有。', `MaleText_loc5`='深鐵礦坑為聯盟所有。', `MaleText_loc7`='La Mina Ferrohondo pertenece a la Alianza.' WHERE `ID`=8591;
