UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스가 얼음이빨 광산을 점령했습니다! 광산의 자원이 군사력을 키우는 데 쓰일 겁니다!', `MaleText_loc4`='联盟占领了冷齿矿洞！矿洞中的物资可以为他们提供增援了！', `MaleText_loc5`='聯盟佔領了冷齒礦坑!其中的補給品現在將會用來強化戰力!', `MaleText_loc7`='¡La Alianza ha capturado la Mina Dentefrío! ¡Ahora usarán sus suministros como refuerzos!' WHERE `ID`=8594;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스가 깊은무쇠 광산을 점령했습니다! 광산의 자원이 군사력을 키우는 데 쓰일 겁니다!', `MaleText_loc4`='联盟夺取了深铁矿洞！矿洞中的物资可以为他们提供增援了！', `MaleText_loc5`='聯盟佔領了深鐵礦坑!其中的補給品現在將會用來強化戰力!', `MaleText_loc7`='¡La Alianza ha capturado la Mina Ferrohondo! ¡Ahora usarán sus suministros como refuerzos!' WHERE `ID`=8595;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드가 얼음이빨 광산을 점령했습니다! 광산의 자원이 군사력을 키우는 데 쓰일 겁니다!', `MaleText_loc4`='部落占领了冷齿矿洞！矿洞中的物资可以为他们提供增援了！', `MaleText_loc5`='部落佔領了冷齒礦坑!其中的補給品現在將會用來強化戰力!', `MaleText_loc7`='¡La Horda ha capturado la Mina Dentefrío! ¡Ahora usarán sus suministros como refuerzos!' WHERE `ID`=8596;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드가 깊은무쇠 광산을 점령했습니다! 광산의 자원이 군사력을 키우는 데 쓰일 겁니다!', `MaleText_loc4`='部落占领了深铁矿洞！矿洞中的物资可以为他们提供增援了！', `MaleText_loc5`='部落佔領了深鐵礦坑!其中的補給品現在將會用來強化戰力!', `MaleText_loc7`='¡La Horda ha capturado la Mina Ferrohondo! ¡Ahora usarán sus suministros como refuerzos!' WHERE `ID`=8597;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='트로그들이 깊은무쇠 광산을 되찾으려 하고 있습니다!', `MaleText_loc4`='穴居人重新占领了深铁矿洞！', `MaleText_loc5`='穴居怪重新佔領了深鐵礦坑!', `MaleText_loc7`='¡Los troggs están recuperando la Mina Ferrohondo!' WHERE `ID`=8599;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코볼트들이 얼음이빨 광산을 되찾으려 하고 있습니다!', `MaleText_loc4`='狗头人重新占领了冷齿矿洞！', `MaleText_loc5`='狗頭人重新佔領了冷齒礦坑!', `MaleText_loc7`='¡Los kóbolds están recuperando la Mina Dentefrío!' WHERE `ID`=8600;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알터랙 계곡에서는 전투가 한창인데 장비 보급이 부족하오.', `MaleText_loc4`='奥特兰克山谷中的作战物资总是非常缺乏。', `MaleText_loc5`='奧特蘭克山谷中的作戰物資總是非常缺乏。', `MaleText_loc7`='En el Valle de Alterac resuena el fulgor de la batalla y escasean los suministros.' WHERE `ID`=8601;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 당분간은 필요한 보급품이 충분해졌군.', `MaleText_loc4`='我的供给需求得到了满足。', `MaleText_loc5`='我的供給需求得到了滿足。', `MaleText_loc7`='Por ahora, he conseguido mis suministros.' WHERE `ID`=8602;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 다 갖춰졌군!', `MaleText_loc4`='抓住我！', `MaleText_loc5`='抓住我!', `MaleText_loc7`='¡Comparte!', `FemaleText_loc1`='이제 다 갖춰졌군!', `FemaleText_loc4`='抓住我！', `FemaleText_loc5`='抓住我!', `FemaleText_loc7`='¡Comparte!' WHERE `ID`=8603;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='날 엄호하라! 요새로 돌아가 공습에 대비해 우리 편대의 전열을 정비해야 한다!', `FemaleText_loc4`='掩护我，士兵！我必须返回基地并让空军做好战斗准备！', `FemaleText_loc5`='掩護我，士兵!我必須返回基地並讓艦隊做好空襲的準備!', `FemaleText_loc7`='¡Cúbreme, Soldado! ¡Tengo que llegar a la base y preparar a la flota para un asalto aéreo!' WHERE `ID`=8604;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우후! 해 냈다!', `FemaleText_loc4`='哈哈！成功了！', `FemaleText_loc5`='喔!成功了!', `FemaleText_loc7`='¡GUAU! ¡Conseguido!' WHERE `ID`=8605;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='낭비할 시간이 없습니다! 즉시 요새로 귀환해야 하니 본관을 엄호하십시오!', `FemaleText_loc4`='别浪费时间，士兵。我必须马上返回基地！掩护我！', `FemaleText_loc5`='沒有時間浪費，騎兵。我必須馬上返回基地!掩護我!', `FemaleText_loc7`='No hay tiempo que perder, Soldado. ¡He de volver a la base inmediatamente! ¡Cúbreme!' WHERE `ID`=8606;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자, 그럼 시작해 볼까!', `FemaleText_loc4`='赶快！', `FemaleText_loc5`='我們言歸正傳!', `FemaleText_loc7`='¡Pongámonos en marcha!' WHERE `ID`=8607;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구스? 제즈톨? 그들이 수평 나선 비행... 중이란 말인가?? 남녘해안 바다에서??', `MaleText_loc4`='古斯？杰斯托？他们……迫降了吗？？南海镇外的海域？？', `MaleText_loc5`='古斯? 傑斯托?他們...慌了嗎??南海鎮的海洋??', `MaleText_loc7`='¿Guse? ¿Jeztor? ¿¿Están...?? ¿En los Mares de Costasur?' WHERE `ID`=8608;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와이번에게 돌아가야 한다. 곧 수색 및 파괴가 시작된다! 6시 방향에서 본관을 엄호하라! 실시! 실시!', `MaleText_loc4`='我得回到基地去。摧毁那些想要阻挡我的家伙！保护我！走吧！', `MaleText_loc5`='我得繼續自己的旅程。去摧毀那些即將來臨的危險!保護我!去吧!', `MaleText_loc7`='Necesito volver a coger mi montura. ¡Búsqueda y destrucción inminente! ¡Cubridme! ¡A mis seis! ¡VAMOS, VAMOS, VAMOS!' WHERE `ID`=8609;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 왔다, 얼라이언스 놈들아!', `MaleText_loc4`='我来啦，弱小的联盟！', `MaleText_loc5`='我來啦，弱小的聯盟!', `MaleText_loc7`='¡Voy a por ti, patética Alianza!' WHERE `ID`=8610;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘했다. 이제 가서 놈들에게 본때를 보여 주자!', `MaleText_loc4`='干得好，士兵。现在让我们发泄对他们的忿怒！', `MaleText_loc5`='幹得好，士兵。現在讓我們發洩對他們的憤怒!', `MaleText_loc7`='Buen trabajo, Soldado. ¡Ahora encendemos los fuegos y despertaremos su ira!' WHERE `ID`=8611;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 귀가 찢어질 듯 위협적인 고함을 지릅니다.', `MaleText_loc4`='%s发出威胁的叫声。', `MaleText_loc5`='%s讓我們發出威脅的叫聲。', `MaleText_loc7`='%s da un grito amenazador.' WHERE `ID`=8612;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='서리늑대 부족 병사들이여, 나를 따르라! 적들에게 정령들의 분노를 보여줄 때가 왔노라!', `FemaleText_loc4`='霜狼的战士们，来帮助我！是时候让他们感受元素的狂怒了！', `FemaleText_loc5`='霜狼的戰士們，來幫助我!是時候讓他們感受元素的狂怒了!', `FemaleText_loc7`='¡Soldados Lobo Gélido, venid en mi ayuda! ¡Ha llegado la hora de desatar la furia de los elementos sobre ellos!' WHERE `ID`=8613;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당분간 필요한 보급품이 충분해졌습니다.', `MaleText_loc4`='我的供给需求得到了满足。', `MaleText_loc5`='我的供給需求得到了滿足。', `MaleText_loc7`='Por ahora, he conseguido mis suministros.' WHERE `ID`=8614;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 전쟁 때문에 군사 보급품이 심히 부족하군요.', `MaleText_loc4`='这次探险将耗费大量军事物资。', `MaleText_loc5`='這次探險將耗費大量軍事物資。', `MaleText_loc7`='Esta expedición es una terrible sangría de suministros militares.' WHERE `ID`=8615;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 감히 이 로크홀라를 소환한 것이냐?', `MaleText_loc4`='谁敢召唤冰雪之王洛克霍拉？', `MaleText_loc5`='誰敢召喚冰雪之王洛克霍拉?', `MaleText_loc7`='¿QUIÉN OSA INVOCAR A LOKHOLAR?' WHERE `ID`=8616;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수천 얼라이언스의 피가 흘러 넘치리라. 그 누구도 얼음 군주의 힘에 맞설 수는 없을 것이다!', `MaleText_loc4`='就算流尽一千名联盟士兵的鲜血……也不能战胜强大的冰雪之王！', `MaleText_loc5`='就算流盡一千名聯盟士兵的鮮血...也不能戰勝強大的冰雪之王!', `MaleText_loc7`='Derramaré la sangre de un millar de Soldados de la Alianza... ¡Nadie podrá vencer al poderoso Señor del Hielo!' WHERE `ID`=8617;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필멸의 생명체여, 내가 너의 고통을 들이마시겠노라. 너의 정수가 나 로크홀라와 더불어 응결될 것이다!', `MaleText_loc4`='让我结束你的痛苦吧。让你的精华和洛克霍拉一起冻结！', `MaleText_loc5`='讓我結束你的痛苦吧。讓你的精華和洛克霍拉一起凍結!', `MaleText_loc7`='Bebo tu sufrimiento, mortal. ¡Deja que tu esencia se coagule con Lokholar!' WHERE `ID`=8618;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 비명을 지르면서 죽자 근처 실리시드 곤충집이 요동칩니다!', `MaleText_loc4`='%s临死时的哀号传遍了临近的虫巢！', `MaleText_loc5`='%s的死亡哀嚎已經擾動了附近的異種巢穴!', `MaleText_loc7`='¡El grito de muerte de %s ha sobresaltado a la colmena de silítidos cercana!' WHERE `ID`=8619;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 비명을 지르면서 죽자 근처 실리시드 곤충집이 요동칩니다!', `FemaleText_loc4`='%s临死时发出的哀嚎惊动了附近的异种蝎巢穴！', `FemaleText_loc5`='%s的死亡哀嚎已經擾動了附近的異種巢穴!', `FemaleText_loc7`='¡El grito de muerte de %s ha sobresaltado a la colmena de silítidos cercana!' WHERE `ID`=8620;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전장에는 적의 피가 흐르고 위대한 정령들이 우리의 부름에 응하여 호드의 앞을 가로막는 이들은 모두 쓰러뜨릴 것입니다.', `FemaleText_loc4`='我们敌人的鲜血会洒落疆场的。伟大的元素会回应我们的呼唤并碾碎所有阻挡我们前进的东西。', `FemaleText_loc5`='我們敵人的鮮血會灑落疆場的。偉大的元素會回應我們的呼喚並碾碎所有阻擋我們前進的東西。', `FemaleText_loc7`='La sangre de nuestros enemigos se derramará sobre el campo de batalla. Los grandiosos elementales responderán a nuestra llamada y aplastarán a todo aquel que se interponga en nuestro camino.' WHERE `ID`=8621;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 웃습니다.', `FemaleText_loc4`='%s发出咯咯的笑声。', `FemaleText_loc5`='%s咯咯的笑。', `FemaleText_loc7`='%s se ríe socarronamente.' WHERE `ID`=8622;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='얼음 군주께서 스톰파이크 부대 전체를 집어삼키실 것입니다!', `FemaleText_loc4`='冰雪之王会吞噬整个的联盟军队！', `FemaleText_loc5`='冰雪之王會吞噬整個的雷矛軍隊!', `FemaleText_loc7`='¡El Señor del Hielo consumirá a todo el ejército Pico Tormenta!' WHERE `ID`=8623;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뒤틀린 황천을 통해 답을 알아볼 수는 없다.', `MaleText_loc4`='在扭曲虚空是听不到任何回应的。', `MaleText_loc5`='在扭曲虛空是聽不到任何回應的。', `MaleText_loc7`='La respuesta no se puede ver a través de El Vacío Abisal.' WHERE `ID`=8624;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='적의 붉은 피가 하얀 눈을 적시는 것을 잘 보십시오. 정령의 힘은 우리에게 결속될 것입니다!', `FemaleText_loc4`='当血深入雪地时仔细看着，孩子。元素会附到我们身上的！', `FemaleText_loc5`='當血深入雪地時仔細看著，孩子。元素會附到我們身上的!', `FemaleText_loc7`='Hijos míos, ved cómo la sangre se filtra en la nieve. ¡El elemental quedará vinculado a nosotros!' WHERE `ID`=8625;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='됐습니다! 얼음 군주께서 당도하셨어요! 어리석은 얼라이언스들이여, 호드의 힘 앞에 무릎을 꿇어라!', `FemaleText_loc4`='结束了！冰雪之王来了！向部落的力量敬礼，蠢货！', `FemaleText_loc5`='結束了!冰雪之王來了!向部落的力量敬禮，蠢貨!', `FemaleText_loc7`='¡Hecho! ¡El Señor del Hielo ha llegado! ¡Inclinaos ante el poder de la Horda, necios!' WHERE `ID`=8626;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말도 안 돼!', `MaleText_loc4`='忘了它吧！', `MaleText_loc5`='忘了它吧!', `MaleText_loc7`='¡Olvídalo!' WHERE `ID`=8627;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대답할 가치도 없군.', `MaleText_loc4`='这问题根本不值得回答。', `MaleText_loc5`='這問題根本不值得回答。', `MaleText_loc7`='No merece la pena responder.' WHERE `ID`=8628;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='농담이겠지?', `MaleText_loc4`='那是个玩笑吧？', `MaleText_loc5`='那是個玩笑吧?', `MaleText_loc7`='¿Se trata de algún tipo de broma?' WHERE `ID`=8629;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제대로 된 질문을 하려는 게 아니라면 다시는 소환하지도 않는 게 좋을 것이다...', `MaleText_loc4`='除非你真有问题要问，否则就别召唤我，好吗？', `MaleText_loc5`='除非你真有問題要問，否則就別召喚我，好嗎?', `MaleText_loc7`='No vuelvas a invocarme a no ser que tengas una pregunta real, ¿de acuerdo?' WHERE `ID`=8630;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 분노합니다!', `MaleText_loc4`='%s被激怒了！', `MaleText_loc5`='%s被激怒了!', `MaleText_loc7`='A %s le hierve la sangre.' WHERE `ID`=8631;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제단에 힘을 집중하라!', `FemaleText_loc4`='把你的能量引导到祭坛里！', `FemaleText_loc5`='把你的能量引導到祭壇裡!', `FemaleText_loc7`='¡Canaliza tus energías al altar!' WHERE `ID`=8632;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 큰일이군. 공습 중 얼라이언스 영공에서 우리 편대사령관 세 명이 격추됐소. 그들이 살았는지 죽었는지 아무도 모른단 말이오!$B$B흠... 우리 전력에 아주 큰 타격을 입은 것이지.', `MaleText_loc4`='太可怕了。在一次空袭中，我们的三个顶级枪手倒在了联盟的领地上，没人知道他们是生是死！$B$B这对我们的空中部队是个可怕的冲击。', `MaleText_loc5`='太可怕了。在一次空襲中，我們的三個頂級槍手倒在了聯盟的領地上，沒人知道他們是生是死!$B$B這對我們的空中部隊是個可怕的衝擊。', `MaleText_loc7`='Es horrible. Nuestros tres mejores pilotos fueron derribados y cayeron en territorio de la Alianza durante un asalto aéreo. ¡Nadie sabe si están vivos o muertos!$B$BHa sido un golpe terrible para nuestra fuerza de ataque aéreo.' WHERE `ID`=8633;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 타고 나갈 게 필요합니다, 마틴.', `MaleText_loc4`='马丁，我需要飞离这儿。', `MaleText_loc5`='馬丁，我需要飛離這兒。', `MaleText_loc7`='Necesito salir de aquí, Martin.', `FemaleText_loc1`='여기서 타고 나갈 게 필요합니다, 마틴.', `FemaleText_loc4`='马丁，我需要飞离这儿。', `FemaleText_loc5`='馬丁，我需要飛離這兒。', `FemaleText_loc7`='Necesito salir de aquí, Martin.' WHERE `ID`=8634;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기까지 오느라 수고하셨습니다. 요새로 돌아가야 하니 본관을 엄호해 주지 않겠습니까?', `FemaleText_loc4`='干得好，士兵。我需要回到大本营！你愿意掩护我吗？', `FemaleText_loc5`='幹得好，士兵。我需要回到大本營!你願意掩護我嗎?', `FemaleText_loc7`='Buen trabajo, Soldado. Necesito volver al campamento base. ¿Me cubres?' WHERE `ID`=8635;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엄호는 제게 맡기십시오, 구스 사령관님.', `MaleText_loc4`='我来支援你，古斯。', `MaleText_loc5`='我來支援你，古斯。', `MaleText_loc7`='Te cubro la espalda, Guse.', `FemaleText_loc1`='엄호는 제게 맡기십시오, 구스 사령관님.', `FemaleText_loc4`='我来支援你，古斯。', `FemaleText_loc5`='我來支援你，古斯。', `FemaleText_loc7`='Te cubro la espalda, Guse.' WHERE `ID`=8636;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제서야 오는군요. 도대체 뭐가 이리 오래 걸린 거죠? 아무튼 날 엄호해요. 요새로 돌아가야 하니까!', `FemaleText_loc4`='你来的真是时候。怎么耽搁了这么久？啊，没关系。掩护我，士兵。我必须返回基地！', `FemaleText_loc5`='你來的真是時候。怎麼耽擱了這麼久?啊，沒關係。掩護我，士兵。我必須返回基地!', `FemaleText_loc7`='¡Maldita sea! ¡Ya era hora de que alguien llegase! ¿Por qué has tardado tanto? Ah, olvídalo. Cúbreme, Soldado. ¡Tengo que llegar a la base!' WHERE `ID`=8637;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맡겨만 주십시오, 편대사령관님', `MaleText_loc4`='你可以相信我，杰斯托。', `MaleText_loc5`='你可以相信我，傑斯托。', `MaleText_loc7`='Puedes contar conmigo, Jeztor.', `FemaleText_loc1`='맡겨만 주십시오, 편대사령관님', `FemaleText_loc4`='你可以相信我，杰斯托。', `FemaleText_loc5`='你可以相信我，傑斯托。', `FemaleText_loc7`='Puedes contar conmigo, Jeztor.' WHERE `ID`=8638;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너는 우리의 정원에 속한 자가 아니군... 너의 몸을 이 아름다운 정원의 거름으로 써 주지!', `FemaleText_loc4`='你不属于这些花园。你的肉身将会滋养我们美丽的作品！', `FemaleText_loc5`='你不屬於這些花園。你的肉身將會滋養我們美麗的作品!', `FemaleText_loc7`='No puedes estar en estos jardines. ¡Tu cuerpo nutrirá a nuestras hermosas creaciones!' WHERE `ID`=8639;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그 어떤 것도 이곳을 더럽힐 수는 없지! 선택의 여지가 없군. 너를 처치해야겠다!', `FemaleText_loc4`='花园绝不能被弄脏！你死定了！', `FemaleText_loc5`='花園絕不能被弄髒!你死定了!', `FemaleText_loc7`='¡Nada debe contaminar los jardines! ¡Debes morir!' WHERE `ID`=8640;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피가 얼마나 더 필요합니까?', `MaleText_loc4`='指挥官，还需要多少血？', `MaleText_loc5`='指揮官，還需要多少血?', `MaleText_loc7`='¿Cuánta sangre más es necesaria, Comandante?', `FemaleText_loc1`='피가 얼마나 더 필요합니까?', `FemaleText_loc4`='指挥官，还需要多少血？', `FemaleText_loc5`='指揮官，還需要多少血?', `FemaleText_loc7`='¿Cuánta sangre más es necesaria, Comandante?' WHERE `ID`=8641;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n, 할 일이 많이 남아 있습니다! 계속해서 적을 쓰러뜨리도록 하십시오!', `FemaleText_loc4`='还有很多工作要做，$n！继续消灭我们的敌人！', `FemaleText_loc5`='還有很多工作要做，$n!繼續消滅我們的敵人!', `FemaleText_loc7`='Todavía queda mucho trabajo por hacer, $n. ¡Seguid atacando a nuestros enemigos!' WHERE `ID`=8642;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거의 다 된 모양이군요. 정령들이 동요하는 걸 느낄 수 있습니다.', `MaleText_loc4`='指挥官，我们必须靠拢点。我能感觉到那些元素正在骚动。', `MaleText_loc5`='指揮官，我們必須靠近點。我能感覺到那些元素正在騷動。', `MaleText_loc7`='Debemos de estar cerca, Comandante. Puedo sentir cómo se agitan los elementos.', `FemaleText_loc1`='거의 다 된 모양이군요. 정령들이 동요하는 걸 느낄 수 있습니다.', `FemaleText_loc4`='指挥官，我们必须靠拢点。我能感觉到那些元素正在骚动。', `FemaleText_loc5`='指揮官，我們必須靠近點。我能感覺到那些元素正在騷動。', `FemaleText_loc7`='Debemos de estar cerca, Comandante. Puedo sentir cómo se agitan los elementos.' WHERE `ID`=8643;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그렇습니다, $n! 정령들이 동요하고 있습니다. 곧 적들에게 정령들의 힘을 보여 주게 될 것이고 엄청난 타격으로 놈들이 비틀거릴 것입니다!', `FemaleText_loc4`='是的，$n。元素很活跃。很快，我们就会将他们的能量释放到我们的敌人身上。他们会被彻底击垮的！', `FemaleText_loc5`='是的，$n。元素很活躍。很快，我們就會將他們的能量釋放到我們的敵人身上。他們會被徹底擊垮的!', `FemaleText_loc7`='Sí, $n. Los elementos se están agitando. Pronto, desataremos su poder sobre nuestros enemigos. ¡Y saldrán por los aires!' WHERE `ID`=8644;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리에게 아주 커다란 힘이 생긴 것이 느껴지는군요. 마법은 준비됐습니까?', `MaleText_loc4`='指挥官，我感觉我们中蕴藏着一股强大的力量。准备好魔法了吗？', `MaleText_loc5`='指揮官，我感覺我們中蘊藏著一股強大的力量。準備好魔法了嗎?', `MaleText_loc7`='Percibo un gran poder entre nosotros, Comandante. ¿Está listo el conjuro?', `FemaleText_loc1`='우리에게 아주 커다란 힘이 생긴 것이 느껴지는군요. 마법은 준비됐습니까?', `FemaleText_loc4`='指挥官，我感觉我们中蕴藏着一股强大的力量。准备好魔法了吗？', `FemaleText_loc5`='指揮官，我感覺我們中蘊藏著一股強大的力量。準備好魔法了嗎?', `FemaleText_loc7`='Percibo un gran poder entre nosotros, Comandante. ¿Está listo el hechizo?' WHERE `ID`=8645;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n, 얼음군주 로크홀라와 접촉하는 데 성공했습니다. 그를 대지에 결속하기 위한 제물도 충분했고 우리의 대의를 듣고 가치 있는 일이라 여기셨습니다. 준비하십시오. 이제 그분이 오십니다...', `FemaleText_loc4`='我已经做过接触了，$n。那是冰雪之王洛克霍拉。他认为我们的事业很有价值--我们给大地的祭品十分充足。他很快就来了……做好准备。', `FemaleText_loc5`='我已經做過接觸了，$n。那是『冰雪之王』洛克霍拉。他認為我們的事業很有價值--我們給大地的祭品十分充足。他很快就來了...做好準備。', `FemaleText_loc7`='He conseguido contactar, $n. Es Lokholar, el Señor del Hielo. Ha considerado nuestra causa digna... Nuestro sacrificio del vínculo con la tierra justo. Llegará pronto... ¡Prepárate!' WHERE `ID`=8646;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 무사히 빠져나가 요새로 귀환하려면 날 호위 해줄 쓸만한 병사가 몇 명 필요한데...', `MaleText_loc4`='我需要一些增援来带我安全地飞离这儿，返回基地。', `MaleText_loc5`='我需要安全地飛離這兒，返回基地。', `MaleText_loc7`='Necesito unos pilotos diestros que me saquen de aquí y me lleven a la base.' WHERE `ID`=8647;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 호위해 드리죠!', `MaleText_loc4`='为你效劳！', `MaleText_loc5`='我將成為你的飛行員!', `MaleText_loc7`='¡Yo seré tus alas!', `FemaleText_loc1`='제가 호위해 드리죠!', `FemaleText_loc4`='为你效劳！', `FemaleText_loc5`='我將成為你的飛行員!', `FemaleText_loc7`='¡Yo seré tus alas!' WHERE `ID`=8648;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 성스러운 곳을 떠나라. 아니면 죽음을 면치 못할 것이다!', `MaleText_loc4`='离开这神圣的地方，否则你会丧命！', `MaleText_loc5`='離開這神聖的地方，否則你會喪命!', `MaleText_loc7`='¡Salid de este lugar sagrado o morid!' WHERE `ID`=8649;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불타는 군단과 킬제덴을 위하여!', `MaleText_loc4`='为了军团！为了基尔加丹！', `MaleText_loc5`='為了軍團!為了基爾加德!', `MaleText_loc7`='¡Por la Legión! ¡Por Kil''jaeden!' WHERE `ID`=8650;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카자크는 위대하다!', `MaleText_loc4`='卡扎克是至高无上的！', `MaleText_loc5`='卡札克是至高無上的!', `MaleText_loc7`='¡Kazzak es supremo!' WHERE `ID`=8651;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='머리 위에 겨우살이를 들고 있습니다.', `MaleText_loc4`='抓着槲寄生放到$g他的:她的;头上', `MaleText_loc5`='抓著槲寄生放到$g他的:她的;頭上', `MaleText_loc7`='Sujeta una rama de muérdago por encima de su cabeza.', `FemaleText_loc1`='머리 위에 겨우살이를 들고 있습니다.', `FemaleText_loc4`='抓着槲寄生放到$g他的:她的;头上', `FemaleText_loc5`='抓著槲寄生放到$g他的:她的;頭上', `FemaleText_loc7`='Sujeta una rama de muérdago por encima de su cabeza.' WHERE `ID`=8652;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기에는 거래와 구매인에 대한 정보며 기타 사업과 관계된 여러 가지 사항이 가득 적혀 있는 것 같습니다.', `MaleText_loc4`='日记中似乎记载了关于贸易、买主和其它商业事务的信息。', `MaleText_loc5`='日誌中似乎記載了關於貿易、買主和其他商業事件的資訊。', `MaleText_loc7`='Las páginas del diario parecen contener información sobre comercios, compradores y otras cosas relacionadas con los negocios.' WHERE `ID`=8653;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지휘관님의 눈을 똑바로 쳐다봐서는 안 되네.', `FemaleText_loc4`='绝不要直视指挥官的眼睛。', `FemaleText_loc5`='絕不要直視指揮官的眼睛。', `FemaleText_loc7`='Nunca mires al Comandante directamente a los ojos.' WHERE `ID`=8654;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리는 케른 님으로부터 직접 명령을 받았네. 지휘관님의 임무를 방해하지 말게나.', `FemaleText_loc4`='我们直接受命于凯恩，$r。不要干预指挥官的工作。', `FemaleText_loc5`='我們直接受命於凱恩，$r。不要干預指揮官的工作。', `FemaleText_loc7`='Tenemos órdenes directas de Cairne, $r. No interferir con la misión del Comandante.' WHERE `ID`=8655;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='주술사 지휘관은 소홀히 대할 대상이 아니네, $r.', `FemaleText_loc4`='萨满指挥官可不能小瞧，$r。', `FemaleText_loc5`='薩滿指揮官可不能小瞧，$r。', `FemaleText_loc7`='El Comandante chamán no es alguien con quien se pueda jugar, $r.' WHERE `ID`=8656;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='곧 로크홀라 님께서 일어나실 거예요... 이제 곧...', `FemaleText_loc4`='很快，洛克霍拉就会出现……很快……非常，非常快……', `FemaleText_loc5`='很快，洛克霍拉就會出現...很快...非常，非常快...', `FemaleText_loc7`='Pronto, Lokholar se levantará... Pronto... Muy, muy pronto...' WHERE `ID`=8657;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도난당한 궤짝을 찾는 데 도움이 될 만한 정보가 있나 하여 계속해서 일지를 훑어봅니다.$B$B끝까지 읽다 보니 제임스가 빨간 색연필로 책장 구석에 써 놓은 글이 보입니다. "돌무덤 호수 근처의 오래된 집... 놀들이 그곳을 아주 철저하게 지키고 있을 것이다."$B$B그곳에 궤짝이 있다고 확신할 만한 이유는 없지만 단서라고 할만한 다른 정보 또한 없는 것 같습니다.', `MaleText_loc4`='你继续翻阅这本日志寻找任何可以帮你找到那个被盗箱子的消息。$B$B到书的最后几页, 你可以在书页的边上看到詹姆士用红色铅笔做的标记。上面写着, “石碑湖附近的老房子……豺狼人当保镖会很出色。”$B$B没理由这就是箱子的所在暗示, 但好象又没有任何其它的线索。', `MaleText_loc5`='你繼續翻閱這本日誌尋找任何可以幫你找到那個被盜箱子的消息。$B$B到書的最後幾頁, 你可以在書頁的邊上看到詹姆士用紅色鉛筆做的標記。上面寫著, 「石碑湖附近的老房子...豺狼人當保鏢會很出色。」$B$B沒理由這就是箱子的所在暗示, 但好像又沒有任何其他的線索。', `MaleText_loc7`='"Sigues hojeando el diario buscando algo de información que pueda ayudarte en tu búsqueda del cofre robado.$B$BHacia el final del libro, en letras rojas, ves una nota de James en el margen de la página. Dice: "Casa vieja cerca del Lago del Hito... los gnolls servirán de guardaespaldas perfectamente."$B$BNo hay ninguna razón que apunte a que ese es el lugar donde está el cofre, pero no parece haber más pistas."' WHERE `ID`=8658;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='편대 출격 준비 완료! $n, 지금 이 봉화를 전장의 중앙으로 가져가서 동부 분화구에 놓도록 한다. 편대의 출격 좌표를 전송할 때까지 봉화를 수호하도록!', `FemaleText_loc4`='空军部队整装待发，$n。你必须带上火炬，把它放在战场中心的东部环形山中。在空军部队进行定位时，你必须好好保护火炬！', `FemaleText_loc5`='艦隊整裝待發，$n。你必須帶上火炬，並將它放在戰場中心的東部環形山。在艦隊確定其位置時你要保護好火炬。', `FemaleText_loc7`='La flota está lista, $n. Debes coger este localizador y colocarlo en el cráter del este del campo de batalla central. ¡Defiende el localizador de los atacantes hasta que la flota consiga bloquear las coordenadas!' WHERE `ID`=8659;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='** 목표 자동 추적 확인. 전투와이번 부대 진입 중. 공습 임박. **', `MaleText_loc4`='**确认目标锁定。空军单位突击。空中突袭就绪。**', `MaleText_loc5`='**確認鎖定目標。雙足飛龍部隊逼近。空襲來臨。**', `MaleText_loc7`='** CONFIRMA BLOQUEO DE OBJETIVO. UNIDAD DE JINETES DE GUERRA LLEGANDO. ATAQUE AÉREO INMINENTE. **' WHERE `ID`=8660;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='** 위치 고정 완료. 전투와이번 자동 추적 중. 대기 바람. 앞으로 60초. **', `MaleText_loc4`='**收到。确认空军目标锁定。准备就绪。倒计时60秒。**', `MaleText_loc5`='**裝置妥當。確認鎖定雙足飛龍。待機中。倒數計時60秒。**', `MaleText_loc7`='** EN POSICIÓN. CONFIRMANDO BLOQUEO DE JINETES DE GUERRA. EN GUARDIA. 60 SEGUNDOS PARA EL DESPEGUE. **' WHERE `ID`=8661;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='** 서보 기구 파괴됨. 목표 추적 장치 손상. 작동 중지 임박. **', `MaleText_loc4`='**定位系统被毁。目标锁定丢失。终止行动，终止行动。**', `MaleText_loc5`='**控制裝置被毀。瞄準系統失效。即將關機。**', `MaleText_loc7`='** SERVO DESTRUIDO. BLOQUEO DE UNIDAD DAÑADO. DESACTIVACIÓN INMINENTE. **' WHERE `ID`=8662;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 날카로운 비명을 지릅니다.', `MaleText_loc4`='%s发出了尖锐的叫声。', `MaleText_loc5`='%s發出刺耳的叫聲。', `MaleText_loc7`='%s suelta un grito agudo.' WHERE `ID`=8663;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 바다제왕들의 군주인 히드락시스다. 너는 정령이 아니므로 우리의 전쟁을 이해하지 못할 것이다... 어쩌면 우리 모두에게 이득이 될 거래를 할 수 있을 것도 같군...', `MaleText_loc4`='我是水元素公爵海达克西斯。你不是元素生物的一员，所以你不明白我们的困境，但是或许我们可以达成一项对双方都有益处的协议……', `MaleText_loc5`='我是水元素公爵海達克西斯。你不是元素中的一員所以你不明白我們的困境，但是或許我們可以達成一項對雙方都有益處的協定...', `MaleText_loc7`='Soy Hydraxis, duque de los Señores del Agua. No eres $gun:una; elemental y, por lo tanto, no puedes comprender nuestra lucha, pero quizás podamos llegar a un pacto que nos beneficie a ambos...' WHERE `ID`=8664;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='만나서 반갑군. 또 다른 정령 군주들과 대적하는 우리의 전투는 아직 격해지지 않지만 자네의 노력은 우리가 승리하는 데 도움이 될 것이야.', `MaleText_loc4`='$n，见到你真好。我们与其它的元素之间的战斗正酣，但是你的参与会确保我们的胜利。', `MaleText_loc5`='$n，見到你真好。我們與其它元素之王間的戰鬥正酣，但是你的參與會確保我們的勝利。', `MaleText_loc7`='Me alegra verte de nuevo, $n. Nuestra guerra con los otros Señores Elementales sigue en pleno apogeo, pero tus esfuerzos ayudan a asegurar nuestra victoria.' WHERE `ID`=8665;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='히드락시스, 화산 심장부로 가서 불의 군주의 룬을 없애려면 물의 진수가 한 병 더 필요합니다.', `MaleText_loc4`='我需要一瓶水之精萃，海达克西斯，因为我要去熔火之心毁掉炎魔之王的符文。', `MaleText_loc5`='我需要一瓶水之精粹，海達克西斯，因為我要去熔火之心毀掉火焰之王的符文。', `MaleText_loc7`='Necesito un vial de quintaesencia de agua, Hydraxis, me dirijo al Núcleo de Magma a extinguir una runa de los señores del Fuego.', `FemaleText_loc1`='히드락시스, 화산 심장부로 가서 불의 군주의 룬을 없애려면 물의 진수가 한 병 더 필요합니다.', `FemaleText_loc4`='我需要一瓶水之精萃，海达克西斯，因为我要去熔火之心毁掉炎魔之王的符文。', `FemaleText_loc5`='我需要一瓶水之精粹，海達克西斯，因為我要去熔火之心毀掉火焰之王的符文。', `FemaleText_loc7`='Necesito un vial de quintaesencia de agua, Hydraxis, me dirijo al Núcleo de Magma a extinguir una runa de los señores del Fuego.' WHERE `ID`=8666;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='봉화를 분화구에 무사히 가져다 놓겠습니다. 맡겨 주십시오!', `MaleText_loc4`='我将把火炬安全带到环形山，古斯。我是值得信赖的！', `MaleText_loc5`='我將把火炬安全帶到環形山，古斯。我是值得信賴的!', `MaleText_loc7`='Yo llevaré el localizador al cráter, Guse. ¡Puedes contar conmigo!', `FemaleText_loc1`='봉화를 분화구에 무사히 가져다 놓겠습니다. 맡겨 주십시오!', `FemaleText_loc4`='我将把火炬安全带到环形山，古斯。我是值得信赖的！', `FemaleText_loc5`='我將把火炬安全帶到環形山，古斯。我是值得信賴的!', `FemaleText_loc7`='Yo llevaré el localizador al cráter, Guse. ¡Puedes contar conmigo!' WHERE `ID`=8667;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='편대 출격 준비 완료! $n, 지금 이 봉화를 전장의 중앙으로 가져가서 서부 분화구에 놓도록 한다. 편대의 출격 좌표를 전송할 때까지 봉화를 수호하도록!', `FemaleText_loc4`='舰队整装待命，$n。你必须带着这个信号灯并把它放置在中央战区西部的凹地里。保护信号灯不被攻击，直到舰队能够锁定它的坐标！', `FemaleText_loc5`='艦隊整裝待命，$n。你必須帶著這個信號燈並把它放置在中央戰區西部的凹地裡。保護信號燈不被攻擊，直到艦隊能夠鎖定它的座標!', `FemaleText_loc7`='La flota está lista, $n. Debes coger este localizador y colocarlo en el cráter del oeste del campo de batalla central. ¡Defiende el localizador de los atacantes hasta que la flota consiga bloquear las coordenadas!' WHERE `ID`=8668;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='문제없습니다. 봉화를 주십시오.', `MaleText_loc4`='没问题，杰斯托。给我一盏信号灯。', `MaleText_loc5`='結束了，傑斯托。給我一盞信號燈。', `MaleText_loc7`='Dalo por hecho, Jeztor. Dame un localizador.', `FemaleText_loc1`='문제없습니다. 봉화를 주십시오.', `FemaleText_loc4`='结束了，杰斯托。给我一盏信号灯。', `FemaleText_loc5`='結束了，傑斯托。給我一盞信號燈。', `FemaleText_loc7`='Dalo por hecho, Jeztor. Dame un localizador.' WHERE `ID`=8669;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 이제 자네의 가치를 입증해 보일 때가 왔다. 이 봉화를 가져가서 눈사태 무덤 정중앙에 설치하도록! 우리 편대가 도착할 때까지 봉화를 수호하라.$B$B<경례하는 멀베릭>', `MaleText_loc4`='现在是你证明自己实力的时候了，$n。带上这个信号灯，将它插在雪落墓地的正中心。在我的空军赶到之前好好保护它。$B$B<穆维里克敬礼。>', `MaleText_loc5`='現在是你證明自己實力的時候了，$n。帶上這根火炬，將它插在中央墓地的正中心。在我的艦隊趕到之前好好保護它。$B$B<穆維里克敬禮。>', `MaleText_loc7`='Ha llegado la hora de demostrar tu valía como piloto, $n. Coge este localizador y colócalo en el centro del Cementerio Avalancha. Defiéndelo hasta que llegue mi flota.$B$B<Mulverick saluda.>' WHERE `ID`=8670;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가져다 놓을 준비가 됐으니 봉화를 이리 주십시오.', `MaleText_loc4`='我要放置火炬了，穆维。把火炬给我。', `MaleText_loc5`='我要放置火炬了，穆維。把火炬給我。', `MaleText_loc7`='Listo para colocar el localizador, Monty. Dame un localizador.', `FemaleText_loc1`='가져다 놓을 준비가 됐으니 봉화를 이리 주십시오.', `FemaleText_loc4`='我要放置火炬了，穆维。把火炬给我。', `FemaleText_loc5`='我要放置火炬了，穆維。把火炬給我。', `FemaleText_loc7`='Lista para colocar el localizador, Monty. Dame un localizador.' WHERE `ID`=8671;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멀베릭 편대 출격 준비 완료! 몸이 성한 호드 병사들은 모두 들어라! 우리 전투와이번 편대가 공습을 수행하려면 자동 좌표 장치의 역할을 할 봉화를 올바른 위치에 설치해야 한다. 모두 최선을 다하도록!', `MaleText_loc4`='啊哈！穆维里克的舰队准备好啦。所有体格健壮的部落士兵都需要一个灯塔，我们必须要尽最大努力建造一个，以便进行准确的空中袭击。', `MaleText_loc5`='啊哈!穆維里克的艦隊準備好啦。所有體格健壯的部落士兵都需要一個燈塔，我們必須要盡最大努力建造一個，以便進行準確的空中襲擊。', `MaleText_loc7`='¡Yujuuuuuuu! La flota de Mulverick está lista para dar caña. Todos los Soldados no heridos de la Horda tienen que solicitar un localizador y conseguir colocarlo como sea, para que mis jinetes de guerra estén localizados en el ataque aéreo.' WHERE `ID`=8672;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전투와이번 출격 준비 완료! 호드의 병사들이여! 나를 따르라!', `FemaleText_loc4`='战马现在准备好了！部落的战士们，我需要你们的帮助。', `FemaleText_loc5`='戰馬現在準備好了!部落的戰士們，我需要你們的幫助。', `FemaleText_loc7`='¡Jinetes de guerra preparados! Soldados de la Horda, necesito su ayuda.' WHERE `ID`=8673;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제즈톨 편대 준비 완료! 호드의 병사들이여, 출동 보고하라!', `FemaleText_loc4`='杰斯托的骑士准备好了！部落的战士们，汇报你们的工作！', `FemaleText_loc5`='傑斯托的騎士準備好了!部落的戰士們，彙報你們的工作!', `FemaleText_loc7`='¡Jinetes de Jeztor preparados! ¡Soldados de la Horda, presentaos!' WHERE `ID`=8674;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 집을 지키기 위해 뛰쳐나옵니다!', `MaleText_loc4`='%s倾巢而动，保护巢穴！', `MaleText_loc5`='%s為了保護巢穴向前衝來!', `MaleText_loc7`='%s se lanza para defender su colmena.' WHERE `ID`=8675;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 집을 지키기 위해 뛰쳐나옵니다!', `MaleText_loc4`='%s倾巢而动，保护巢穴！', `MaleText_loc5`='%s為了保護巢穴向前衝來!', `MaleText_loc7`='%s se lanza para defender su colmena.' WHERE `ID`=8676;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밤의 장막 아래에서도 대지모신께서 훤한 대낮과 같이 우리를 지켜 주시기를. 이 불이 우리의 몸과 영혼을 모두 비추며, 항상 우리를 이끌어 주시는 영광스러운 선조를 기억하게 해 주기를...', `MaleText_loc4`='大地之母日夜监视着我们。让这火焰照亮我们的身体和灵魂吧，让我们想起尊敬的祖先，他们一直都在我们身边，指导我们前行。', `MaleText_loc5`='大地之母日夜監視著我們。讓這火焰照亮我們的身體和靈魂吧，讓我們想起尊敬的祖先，他們一直都在我們身邊，指導我們前行。', `MaleText_loc7`='La Madre Tierra nos protege; tanto al amparo de la noche como durante el día. Que este fuego ilumine nuestros cuerpos y espíritus y nos recuerde a nuestros honorables ancestros, que siempre están con nosotros guiándonos en el camino.' WHERE `ID`=8677;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가죽세공술을 배우고 싶습니다.', `MaleText_loc4`='我想重新学习制皮的技能。', `MaleText_loc5`='我想學習製皮的技能。', `MaleText_loc7`='Me gustaría aprender peletería.', `FemaleText_loc1`='가죽세공술을 배우고 싶습니다.', `FemaleText_loc4`='我想重新学习制皮的技能。', `FemaleText_loc5`='我想學習製皮的技能。', `FemaleText_loc7`='Me gustaría aprender peletería.' WHERE `ID`=8678;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 야만적인 놈들에게 자비를 보이지 말라! 아마 녀석들은 더할 테니까!', `MaleText_loc4`='士兵们，别对这些野蛮的家伙抱有仁慈之心！他们是不会对你手下留情的！', `MaleText_loc5`='士兵們，別對這些野蠻的傢伙抱有仁慈之心!他們是不會對你手下留情的!', `MaleText_loc7`='¡Soldados, no tengan piedad con esos salvajes! ¡Ellos no la tendrán con ustedes!' WHERE `ID`=8679;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='철수하시오. 그러면 두 번째 죽음은 고통 없이 신속하게 맞게 해 줄 테니까!', `MaleText_loc4`='把你的军队撤退，修士，我答应让你速死！', `MaleText_loc5`='把你的軍隊撤退，修士，我答應讓你速死!', `MaleText_loc7`='Retira tus tropas, hermano, y te prometo una muerte rápida.' WHERE `ID`=8680;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부관과 지휘관들 주위로 집결! 야만족 놈들이 다가오지 못하도록 하라!', `MaleText_loc4`='士兵们，团结在中尉和指挥官周围！阻止那些野蛮的家伙！', `MaleText_loc5`='士兵們，團結在中尉和指揮官周圍!阻止那些野蠻的傢伙!', `MaleText_loc7`='¡Soldados, reúnanse con sus tus Tenientes y Comandantes! ¡Mantengan a los salvajes a raya!' WHERE `ID`=8681;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적에게 굳은 결의를 보여라! 그대들의 발 밑에 녀석들을 쓰러뜨려라!', `MaleText_loc4`='士兵们，让敌人见识见识你们的决心！用武器粉碎他们！', `MaleText_loc5`='士兵們，讓敵人見識見識你們的決心!用武器粉碎他們!', `MaleText_loc7`='¡Demuestren su determinación al enemigo, Soldados! ¡¡¡Aplástenlos!!! ¡Pisotéenlos!' WHERE `ID`=8682;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='국왕 폐하 만세! 병사들이여, 놈들을 밀어내라!', `MaleText_loc4`='为了国王！把他们顶回去，士兵们！', `MaleText_loc5`='為了國王!把他們頂回去，士兵們!', `MaleText_loc7`='¡POR EL REY! ¡Soldados, hacedles retroceder!' WHERE `ID`=8683;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='항복하면 살려 주겠다! 무기를 버리고 떠나란 말이다! 이 야만인들아!', `MaleText_loc4`='你们这些野蛮的家伙，投降吧，我们会留下你的小命的！放下武器！', `MaleText_loc5`='你們這些野蠻的傢伙，投降吧，我們會留下你的小命的!放下武器!', `MaleText_loc7`='¡Rendíos y os dejaremos vivir, paganos! ¡Soltad las armas y marchad!' WHERE `ID`=8684;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지상 공격 부대를 보내려면 막대한 보급품이 필요하오!', `MaleText_loc4`='发动地面攻击需要大量军需物资！', `MaleText_loc5`='發動地面攻擊需要大量軍需物資!', `MaleText_loc7`='Los asaltos terrestres nos llevan enormes cantidades de suministros.' WHERE `ID`=8685;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 우물쭈물 하고 있는 거요, $n? 투쟁의 벌판에서 테라베인 야전사령관을 찾아 공격명령서를 전해 주시오. 명령서를 받으면 그와 그 부대가 호드 진영으로 쳐들어가 놈들을 말살시켜 버릴 테니까.', `MaleText_loc4`='$n，你还在等什么？去征战平原找指挥官特拉瓦雷，将攻击指令交给他。一旦他得到指令，他和他的军队就能发动对部落的攻击，不留活口！', `MaleText_loc5`='$n，你還在等什麼?去征戰平原找戰場元帥特拉瓦雷，將攻擊指令交給他。一旦他得到指令，他和他的軍隊就能發動對部落的攻擊，不留活口!', `MaleText_loc7`='$n, ¿a qué estás esperando? Encuentra al Mariscal de campo Teravaine en la Tierra de Disputa y dale las órdenes de asalto. ¡Cuando tenga las órdenes, él y sus tropas cargarán contra la Horda y no dejarán a nadie con vida!', `FemaleText_loc1`='뭘 우물쭈물 하고 있는 거요, $n? 투쟁의 벌판에서 테라베인 야전사령관을 찾아 공격명령서를 전해 주시오. 명령서를 받으면 그와 그 부대가 호드 진영으로 쳐들어가 놈들을 말살시켜 버릴 테니까.', `FemaleText_loc4`='$n，你还在等什么？去征战平原找指挥官特拉瓦雷，将攻击指令交给他。一旦他得到指令，他和他的军队就能发动对部落的攻击，不留活口！', `FemaleText_loc5`='$n，你還在等什麼?去征戰平原找戰場元帥特拉瓦雷，將攻擊指令交給他。一旦他得到指令，他和他的軍隊就能發動對部落的攻擊，不留活口!', `FemaleText_loc7`='$n, ¿a qué estás esperando? Encuentra al Mariscal de campo en la Tierra de Disputa y dale las órdenes de asalto. ¡Cuando tenga las órdenes, él y sus tropas cargarán contra la Horda y no dejarán a nadie con vida!' WHERE `ID`=8686;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명령서를 주십시오! 투쟁의 벌판에 있는 테라베인에게 전달하겠습니다!', `MaleText_loc4`='给我定单！我会将它们交给征战平原的特拉瓦雷。', `MaleText_loc5`='給我定單!我會將它們交給征戰平原的特拉瓦雷。', `MaleText_loc7`='¡Dame las órdenes! ¡Yo se las entregaré a Teravaine en la Tierra de Disputa!', `FemaleText_loc1`='명령서를 주십시오! 투쟁의 벌판에 있는 테라베인에게 전달하겠습니다!', `FemaleText_loc4`='给我定单！我会将它们交给征战平原的特拉瓦雷。', `FemaleText_loc5`='給我定單!我會將它們交給征戰平原的特拉瓦雷。', `FemaleText_loc7`='¡Dame las órdenes! ¡Yo se las entregaré a Teravaine en la Tierra de Disputa!' WHERE `ID`=8687;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천리안은 그 영향권 내에 있는 것은 뭐든지 볼 수 있지. 보고 싶은 게 뭔가?', `MaleText_loc4`='这眼睛能看见其视线范围内的一切事物，$c。你想看什么？', `MaleText_loc5`='這眼睛能看見其視線範圍內的一切事物，$c。你想看什麼?', `MaleText_loc7`='El Ojo ve todo aquello que entra en su esfera de influencia, $c. ¿Qué deseas ver?' WHERE `ID`=8688;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명령이 떨어졌다! 진격! 우리가 어떤 존재인지 놈들에게 보여 줘라!', `MaleText_loc4`='命令已经下达！行动，给他们点颜色瞧瞧！', `MaleText_loc5`='命令已經下達!行動，給他們點顏色瞧瞧!', `MaleText_loc7`='¡Órdenes entregadas! ¡En marcha y demostradles de qué estamos hechos!', `FemaleText_loc1`='명령이 떨어졌다! 진격! 우리가 어떤 존재인지 놈들에게 보여 줘라!', `FemaleText_loc4`='命令已经下达！行动，给他们点颜色瞧瞧！', `FemaleText_loc5`='命令已經下達!行動，給他們點顏色瞧瞧!', `FemaleText_loc7`='¡Órdenes entregadas! ¡En marcha y demostradles de qué estamos hechos!' WHERE `ID`=8689;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙네, $n. 지금 당장 부대를 출동시키도록 하지!', `MaleText_loc4`='谢谢你，$n。我立即动员人民！', `MaleText_loc5`='謝謝你，$n。我立即動員人民!', `MaleText_loc7`='Gracias, $n. ¡Movilizaré a mi gente ahora mismo!', `FemaleText_loc1`='고맙네, $n. 지금 당장 부대를 출동시키도록 하지!', `FemaleText_loc4`='谢谢你，$n。我立即动员人民！', `FemaleText_loc5`='謝謝你，$n。我立即動員人民!', `FemaleText_loc7`='Gracias, $n. ¡Movilizaré a mi gente ahora mismo!' WHERE `ID`=8691;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적들을 보고 싶습니다. 그들을 보게 해 주십시오. 라이슨', `MaleText_loc4`='我想看看我的敌人，雷松。将他们带过来。', `MaleText_loc5`='我想看看我的敵人，雷松。將他們帶過來。', `MaleText_loc7`='Deseo ver a mis enemigos, Ryson. Enséñamelos.', `FemaleText_loc1`='적들을 보고 싶습니다. 그들을 보게 해 주십시오. 라이슨', `FemaleText_loc4`='我想看看我的敌人，雷松。将他们带过来。', `FemaleText_loc5`='我想看看我的敵人，雷松。將他們帶過來。', `FemaleText_loc7`='Deseo ver a mis enemigos, Ryson. Enséñamelos.' WHERE `ID`=8692;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 가져가게! 천리안의 힘이 사라지면 내게 다시 오게나.', `MaleText_loc4`='带上它！一旦眼球的力量减弱，就回到我这儿来。', `MaleText_loc5`='帶上它!一旦眼球的力量減弱，就回到我這兒來。', `MaleText_loc7`='Aquí tienes. Ven a verme si el poder del Ojo falla.' WHERE `ID`=8693;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세나리온 의회가 어딘가에 기록해 두었을 정보를 찾고 있는 거라면 제게 말해 보십시오. 그렇지만 제 도움을 받으려면 먼저 당신 스스로 무슨 정보를 찾고 있는지부터 확실히 알아야합니다.$B$B이제 이해가 가신다고요? 좋습니다!', `MaleText_loc4`='如果你想在塞纳里奥议会中找寻某些档案的话，我就是那个你要交谈的人。你首先要知道要寻找的确切信息，那样我才能帮你。$B$B看看那个，真是光彩夺目呀！', `MaleText_loc5`='如果你想在塞納里奧議會中找尋某些檔案的話，我就是那個你要交談的人。你首先要知道要尋找的確切資訊，那樣我才能幫你。$B$B看看那個，真是光彩奪目呀!', `MaleText_loc7`='Si necesitas información que el Círculo Cenarion pueda tener archivada, yo soy la persona que buscas. Pero primero, necesitas saber qué información buscas para poder ayudarte.$B$B¿Te das cuenta de cómo va esto? ¡Fantástico!' WHERE `ID`=8694;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모든 문제의 답은 그대의 내면에 잠들어 있소. 그러니 세상 사람들이 하는 소리에 너무 귀를 기울이지 마시오. 그대는 이미 답을 알고 있소.', `MaleText_loc4`='别聆听来自世界的心声——答案就在你心中，你知道真相的。', `MaleText_loc5`='別聆聽來自世界的心聲─答案就在你心中，你知道真相的。', `MaleText_loc7`='No escuches los corazones del mundo... la respuesta está dentro de ti. Tú sabes la verdad.' WHERE `ID`=8695;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$C님, 이 황무지에는 과거의 망령들이 살고 있습니다. 우린 그들을 깨우지 않도록 항상 조심해야 합니다.', `MaleText_loc4`='死者在这片荒地长眠，$c。我们必须小心，别惊动他们。', `MaleText_loc5`='死者在這片荒原長眠，$c。我們必須小心，別驚動他們。', `MaleText_loc7`='El pasado vive en estos eriales, $c. Debemos tener cuidado y no despertarlo.' WHERE `ID`=8696;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천리안의 힘은 의심할 여지가 없지 강력한 것이군요, 라이슨. 그런데 대체 이걸로 뭘 하는 거죠?', `MaleText_loc4`='这眼睛的力量是不容置疑的，雷松，但是它还能做什么呢？', `MaleText_loc5`='這眼睛的力量是不容置疑的，雷松，但是它還能做什麼呢?', `MaleText_loc7`='El poder del Ojo es innegable, Ryson, ¿pero qué más puede hacer?', `FemaleText_loc1`='천리안의 힘은 의심할 여지가 없지 강력한 것이군요, 라이슨. 그런데 대체 이걸로 뭘 하는 거죠?', `FemaleText_loc4`='这眼睛的力量是不容置疑的，雷松，但是它还能做什么呢？', `FemaleText_loc5`='這眼睛的力量是不容置疑的，雷松，但是它還能做什麼呢?', `FemaleText_loc7`='El poder del Ojo es innegable, Ryson, ¿pero qué más puede hacer?' WHERE `ID`=8697;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천리안의 힘은 의심할 여지가 없지 강력한 것이지요, 라이슨. 그런데 대체 이걸로 뭘 하는 거죠?', `MaleText_loc4`='这眼睛的力量是不容置疑的，雷松，但是它还能做什么呢？', `MaleText_loc5`='這眼睛的力量是不容置疑的，雷松，但是它還能做什麼呢?', `MaleText_loc7`='El poder del Ojo es innegable, Ryson, ¿pero qué más puede hacer?', `FemaleText_loc1`='천리안의 힘은 의심할 여지가 없지 강력한 것이지요, 라이슨. 그런데 대체 이걸로 뭘 하는 거죠?', `FemaleText_loc4`='这眼睛的力量是不容置疑的，雷松，但是它还能做什么呢？', `FemaleText_loc5`='這眼睛的力量是不容置疑的，雷松，但是它還能做什麼呢?', `FemaleText_loc7`='El poder del Ojo es innegable, Ryson, ¿pero qué más puede hacer?' WHERE `ID`=8698;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 자네는 이제 겨우 천리안의 힘을 보기 시작했을 뿐이네. 천리안의 능력을 더 보고 싶다면 먼저 완수해야 할 임무가 있다네.', `MaleText_loc4`='你仅仅只是开始看到眼的力量，$c。如果你想增强眼的力量，那么必须完成一项任务。', `MaleText_loc5`='你僅僅只是開始看到眼的力量，$c。如果你想增強眼的力量，那麼必須完成一項任務。', `MaleText_loc7`='Acabas de empezar a ver el poder del Ojo, $c. Si quieres ver todo lo que puede hacer, debes completar una misión.' WHERE `ID`=8699;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 임무입니까?', `MaleText_loc4`='这次任务是什么?', `MaleText_loc5`='這次任務是什麼?', `MaleText_loc7`='¿De qué se trata?', `FemaleText_loc1`='어떤 임무입니까?', `FemaleText_loc4`='这次任务是什么?', `FemaleText_loc5`='這次任務是什麼?', `FemaleText_loc7`='¿De qué se trata?' WHERE `ID`=8700;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 봉화를 들고 적의 요새로 쳐들어가게. 녀석들의 본진 바깥까지 들어간 다음 안마당 중앙에 이 봉화를 설치하고 천리안이 이 봉화의 정확한 위치를 찾을 때까지 적으로부터 봉화를 지켜내도록 하게.$B$B이 일이 다 끝나면 적의 요새 바깥에서 일어나는 모든 일을 여기에서 볼 수 있게 될 거야.$B$B이 임무를 맡을 텐가?', `MaleText_loc4`='带上这根火炬，前往敌人的基地。将火炬插在敌人主要据点的庭院中心。在眼球追踪到火炬的位置之前，好好保护火炬。$B$B一旦你完成这件事，我们就能看见敌人在基地之外的所有活动。$B$B你愿意接受这项任务吗？', `MaleText_loc5`='帶上這根火炬，前往敵人的基地。將火炬插在敵人主要據點的庭院中心。在眼球追蹤到火炬的位置之前，好好保護火炬。$B$B一旦你完成這件事，我們就能看見敵人在基地之外的所有活動。$B$B你願意接受這項任務嗎?', `MaleText_loc7`='Coge este localizador y ve hasta la base enemiga. Vete hasta el exterior de su bastión principal y coloca el localizador en el medio del patio. Defiende el localizador de los atacantes hasta que el Ojo haya bloqueado las coordenadas del localizador.$B$BCuando lo hayas conseguido, podremos ver toda la actividad que tenga lugar en el exterior de la base enemiga desde aquí.$B$B¿Lo harás?' WHERE `ID`=8701;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론입니다. 봉화를 주십시오, 라이슨.', `MaleText_loc4`='绝对是。给我一个火把，雷松。', `MaleText_loc5`='絕對是。給我一個火把，雷松。', `MaleText_loc7`='Por supuesto. Dame un localizador, Ryson.', `FemaleText_loc1`='물론입니다. 봉화를 주십시오, 라이슨.', `FemaleText_loc4`='绝对是。给我点一盏灯火，雷松。', `FemaleText_loc5`='絕對是。給我一個火把，雷松。', `FemaleText_loc7`='Por supuesto. Dame un localizador, Ryson.' WHERE `ID`=8702;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 이제 최종 임무를 수행할 준비가 되었군. 화산 심장부 바닥에 새겨진 불의 룬은 불의 세계로 통하는 길로서, 불의 군주들에게 마력을 부여하는 원천이노라. 우리에게는 치욕의 상징일 뿐이지. 반드시 그것을 꺼야만 하노라!$B$B룬을 끄려면 물의 진수를 한 병 들고 가서 그 위에 부어야 한다. 그러면 불길이 꺼져 룬은 제 힘을 잃어버릴 것이고 당연히 우리의 적들도 약해질 것이다!', `MaleText_loc4`='$n，你准备好完成终极任务了。刻在熔火之心地面上的炽热的符文是通向火海的导管,它们的存在既是对我们的侵犯，又是炎魔之王的力量源泉。必须把它们扑灭！$B$B要熄灭符文，拿一小瓶水之精华。把它倒在符文上,火焰就会熄灭,这会使其变得毫无用处并能削弱我们的敌人！', `MaleText_loc5`='$n，你準備好完成終極任務了。刻在熔火之心地面上的熾熱的符文是通向火海的導管,它們的存在既是對我們的侵犯，又是火焰之王的力量源泉。必須把它們撲滅!$B$B要熄滅符文，拿一小瓶水之精華。把它倒在符文上,火焰就會熄滅,這會使其變得毫無用處並能削弱我們的敵人!', `MaleText_loc7`='$n, estás $glisto:lista; para la misión definitiva. Las runas ardientes incrustadas en el suelo del Núcleo de Magma son pasajes al Reino del Fuego y, su presencia, es una afronta hacia nosotros además de una fuente de poder para los señores del Fuego. ¡Hay que extinguirlas!$B$BPara extinguir una runa, coge un vial de quintaesencia de agua y viértelo sobre la runa. La llama se apagará dejando la runa extinguida y nuestro enemigo quedará debilitado.' WHERE `ID`=8703;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언더시티 길드 사무소에 온 것을 환영하네. 무슨 일로 왔는가?', `MaleText_loc4`='欢迎来到幽暗城公会登记处。你需要什么帮助么？', `MaleText_loc5`='歡迎來到幽暗城公會登記處。你需要什麼幫助嗎?', `MaleText_loc7`='Te doy la bienvenida al Registro de hermandades de Entrañas. ¿Qué quieres?' WHERE `ID`=8704;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세나리온 의회에 오신 것을 환영합니다, $c|1이여;여;. 무엇을 도와 드릴까요?', `MaleText_loc4`='欢迎来到塞纳里奥议会，$c。我要怎么帮你呢？', `MaleText_loc5`='歡迎來到塞納里奧議會，$c。我要怎麼幫你呢?', `MaleText_loc7`='Te doy la bienvenida al Círculo Cenarion, $c. ¿Cómo puedo ayudarte?', `FemaleText_loc1`='세나리온 의회에 오신 것을 환영합니다, $c|1이여;여;. 무엇을 도와 드릴까요?', `FemaleText_loc4`='欢迎来到塞纳里奥议会，$c。我要怎么帮你呢？', `FemaleText_loc5`='歡迎來到塞納里奧議會，$c。我要怎麼幫你呢?', `FemaleText_loc7`='Te doy la bienvenida al Círculo Cenarion, $c. ¿Cómo puedo ayudarte?' WHERE `ID`=8705;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라이슨, 관측용 지구본을 볼 관측용 망원경이 필요합니다.', `MaleText_loc4`='雷松，我需要占卜瞄准镜查看占卜之球。', `MaleText_loc5`='雷松，我需要占卜瞄準鏡查看占卜之球。', `MaleText_loc7`='Necesito una mira de visión para ver el globo de visión, Ryson.', `FemaleText_loc1`='라이슨, 관측용 지구본을 볼 관측용 망원경이 필요합니다.', `FemaleText_loc4`='雷松，我需要占卜瞄准镜查看占卜之球。', `FemaleText_loc5`='雷松，我需要占卜瞄準鏡查看占卜之球。', `FemaleText_loc7`='Necesito una mira de visión para ver el globo de visión, Ryson.' WHERE `ID`=8706;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='히드락시스와 얘기를 나눠 보도록!', `MaleText_loc4`='跟海达克西斯公爵交谈。', `MaleText_loc5`='跟海達克西斯交談。', `MaleText_loc7`='Habla con Hydraxis.' WHERE `ID`=8707;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필멸의 존재여... 나를 귀찮게 하지 마라!', `MaleText_loc4`='你跟我没有关系，小家伙。', `MaleText_loc5`='你跟我沒有關係，小傢伙。', `MaleText_loc7`='No tienes nada que hablar conmigo, $gpequeñajo:pequeñaja;.' WHERE `ID`=8708;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 어디서 그 저속한 언어를 내뱉는가! 그런 걸 참을 수 있는 건 오직 히드락시스 군주뿐이시다.', `MaleText_loc4`='闭上你的脏嘴！也只有海达克西斯公爵才受得了你。', `MaleText_loc5`='閉上你的髒嘴!也只有海達克西斯才受得了你。', `MaleText_loc7`='¡No me hables en tu vulgar idioma! ¡Solo Hydraxis puede aguantarlo!' WHERE `ID`=8709;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필멸의 존재여, 어서 오라! 물의 군주에게 무슨 용무라도 있느냐?', `MaleText_loc4`='你好，小伙计。你跟水元素之王有关系吗？', `MaleText_loc5`='你好，小夥計。你跟水元素之王有關係嗎?', `MaleText_loc7`='Saludos, $gpequeñajo:pequeñaja;. ¿Tienes que hablar de algo con los Señores del Agua?' WHERE `ID`=8710;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그간 네가 이룬 위업에 대한 얘기가 널리 퍼지고 있다. $n, 모두 너의 이름을 알고 있지.', `MaleText_loc4`='关于你的英雄事迹已经流传开来。我们没有听说过你的名字，$n。', `MaleText_loc5`='關於你的英雄事蹟已經流傳開來。我們沒有聽說過你的名字，$n。', `MaleText_loc7`='Se cuentan historias sobre tus hazañas. Tu nombre no nos es desconocido, $n.' WHERE `ID`=8711;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리를 대신해 적과 싸울 결심을 하다니, 내 기꺼이 너와 위대한 물의 힘을 나누도록 하겠다.', `MaleText_loc4`='你已经把我们的敌人当成了你自己的敌人。我会很高兴能与你分享水的伟大。', `MaleText_loc5`='你已經把我們的敵人當成了你自己的敵人。我會很高興能與你分享水的偉大。', `MaleText_loc7`='Has hecho de nuestros enemigos los tuyos propios. Compartiré encantado mis aguas contigo.' WHERE `ID`=8712;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 그간 네가 이룬 위업에 대한 얘기를 좀 듣고 싶구나. 시간을 내어 들려 준다면 큰 영광으로 알겠노라.', `MaleText_loc4`='或许你能告诉我你的一些事情，$n。我非常想听听。', `MaleText_loc5`='或許你能告訴我你的一些事情，$n。我非常想聽聽。', `MaleText_loc7`='Quizás podrías contarme tus hazañas, $n. Me sentiría muy honrado.' WHERE `ID`=8713;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='군주 히드락시스께서 자네 칭찬을 아주 많이 하시더군. 친구여, 편히 있다 가게나.', `MaleText_loc4`='海达克西斯公爵赞扬你。我的水就是你的水，朋友。', `MaleText_loc5`='海達克西斯公爵讚揚你。我的水就是你的水，朋友。', `MaleText_loc7`='Nuestro señor Hydraxis habla muy bien de ti. Mi agua es tu agua, $gamigo:amiga;.' WHERE `ID`=8714;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음에 또 화산 심장부로 가면 날 위해 불의 군주 한 놈을 처치해 주지 않겠나?', `MaleText_loc4`='当你下次去熔火之心时，请为我杀死一个火焰之王，行吗？', `MaleText_loc5`='當你下次去熔火之心時，請為我殺死一個火焰之王，行嗎?', `MaleText_loc7`='La próxima vez que vayas al Núcleo de Magma, mata a un señor del Fuego por mí, ¿de acuerdo?' WHERE `ID`=8715;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나의 가르침을 받을 만한 자질이 없군. 상급 $c|1을;를; 찾아보는 게 좋을 거요.', `MaleText_loc4`='我想你不愿意向我学习吧。你最好找个$c训练师帮助你。', `MaleText_loc5`='我想你不願意向我學習吧。你最好找個$c訓練師幫助你。', `MaleText_loc7`='Creo que no te interesa lo que puedo enseñarte. Quizás te interese encontrar a un instructor de $c que te ayude.', `FemaleText_loc1`='나의 가르침을 받을 만한 자질이 없군. 상급 $c|1을;를; 찾아보는 게 좋을 거요.', `FemaleText_loc4`='我想你不愿意向我学习吧。你最好找个$c训练师帮助你。', `FemaleText_loc5`='我想你不願意向我學習吧。你最好找個$c訓練師幫助你。', `FemaleText_loc7`='Creo que no te interesa lo que puedo enseñarte. Quizás te interese encontrar a un instructor de $c que te ayude.' WHERE `ID`=8716;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보아하니 소매치기에 일가견이 있는 분 같은데... 내가 뭐 도울 일이라도 있소?', `MaleText_loc4`='你看起来像是那种手脚不干净的人。有什么我可以帮忙的吗？', `MaleText_loc5`='你看起來像是那種手腳不乾淨的人。有什麼我可以幫忙的嗎?', `MaleText_loc7`='Parece que contigo tendré que vigilar bien el bolsillo. ¿Puedo ayudarte en algo?', `FemaleText_loc1`='보아하니 소매치기에 일가견이 있는 분 같은데... 내가 뭐 도울 일이라도 있소?', `FemaleText_loc4`='你看起来像是那种手脚不干净的人。有什么我可以帮忙的吗？', `FemaleText_loc5`='你看起來像是那種手腳不乾淨的人。有什麼我可以幫忙的嗎?', `FemaleText_loc7`='Parece que contigo tendré que vigilar bien el bolsillo. ¿Puedo ayudarte en algo?' WHERE `ID`=8717;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상급 부대로 승급!', `MaleText_loc4`='升级到经验丰富的士兵！', `MaleText_loc5`='升級到經驗豐富的士兵!', `MaleText_loc7`='¡Mejorar a unidades experimentadas!', `FemaleText_loc1`='상급 부대로 승급!', `FemaleText_loc4`='升级到经验丰富的士兵！', `FemaleText_loc5`='升級到經驗豐富的士兵!', `FemaleText_loc7`='¡Mejorar a unidades experimentadas!' WHERE `ID`=8718;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정예 부대로 승급!', `MaleText_loc4`='升级到老兵！', `MaleText_loc5`='升級到老兵!', `MaleText_loc7`='¡Mejorar a unidades veteranas!', `FemaleText_loc1`='정예 부대로 승급!', `FemaleText_loc4`='升级到老兵！', `FemaleText_loc5`='升級到老兵!', `FemaleText_loc7`='¡Mejorar a unidades veteranas!' WHERE `ID`=8719;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천리안을 찾았군.$B$B<씩 웃어 보이는 비밀결사대장 라이슨>$B$B자, 이리 주게!', `MaleText_loc4`='你已经找到眼珠了。$B$B<指挥官雷尔松咧嘴笑着。>$B$B好吧，把它给我！', `MaleText_loc5`='你已經找到眼珠了。$B$B<指揮官雷松咧嘴笑著。>$B$B好吧，把它給我!', `MaleText_loc7`='Veo que has encontrado el Ojo.$B$B<El Maestro Ryson sonríe.>$B$B¡Bien, dámelo!' WHERE `ID`=8720;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 건 가지고 있어 봐야 골칫거리밖에 안 될 테니까 가져가세요!', `MaleText_loc4`='带上它！跟其价值相比，这东西也许会带来更多的麻烦。', `MaleText_loc5`='帶上它!跟其價值相比，這東西也許會帶來更多的麻煩。', `MaleText_loc7`='Aquí lo tienes. De todas formas, probablemente no valga tanto.', `FemaleText_loc1`='이런 건 가지고 있어 봐야 골칫거리밖에 안 될 테니까 가져가세요!', `FemaleText_loc4`='带上它！跟其价值相比，这东西也许会带来更多的麻烦。', `FemaleText_loc5`='帶上它!跟其價值相比，這東西也許會帶來更多的麻煩。', `FemaleText_loc7`='Aquí lo tienes. De todas formas, probablemente no valga tanto.' WHERE `ID`=8721;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천리안을 찾아야 해!', `MaleText_loc4`='必须修复全视之眼！', `MaleText_loc5`='必須修復全視之眼!', `MaleText_loc7`='¡Hay que recuperar el Ojo que todo lo ve!' WHERE `ID`=8722;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최정예 부대로 승급!', `MaleText_loc4`='升级到勇士！', `MaleText_loc5`='升級到勇士!', `MaleText_loc7`='¡Mejorar a unidades campeonas!', `FemaleText_loc1`='최정예 부대로 승급!', `FemaleText_loc4`='升级到勇士！', `FemaleText_loc5`='升級到勇士!', `FemaleText_loc7`='¡Mejorar a unidades campeonas!' WHERE `ID`=8723;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 자네 요새로 돌아가자고!', `MaleText_loc4`='我们回到你的基地吧！', `MaleText_loc5`='我們回到你的基地吧!', `MaleText_loc7`='¡Volvamos a la base!' WHERE `ID`=8724;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 큰 신세를 졌군, $c 친구. 이제 내가 자네를 도울 차례야.', `MaleText_loc4`='我很感激你，$c。或许我对你的目标有所帮助。', `MaleText_loc5`='我很感激你，$c。或許我對你的目標有所幫助。', `MaleText_loc7`='Estoy en deuda contigo, $c. Quizás pueda ayudarte en tu causa.' WHERE `ID`=8725;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼마 전 희대의 발명품이 될 최신 휴대용 벌목기를 만들기 위해 이곳에 재료를 찾으러 왔지. 그런데 이 트롤들이 날 습격해서는 놈들의 본거지인 동굴 깊숙한 곳까지 끌고 왔다네.$B$B안전한 곳으로 피신할 수 있도록 도와주면 보답으로 자네를 돕도록 하지.', `MaleText_loc4`='当这些巨魔将我击倒，并将我拖到洞穴深处时，我便开始搜寻原料，用于制作我最后一项也是最好的一项发明——便携式远程遥控伐木机。$B$B将我送到安全地带，我会帮助你的，$r。', `MaleText_loc5`='當這些食人妖將我擊倒，並將我拖到洞穴深處時，我便開始搜尋原料，用於製作我最後一項也是最好的一項發明─可攜式遠端遙控伐木機。$B$B將我送到安全地帶，我會幫助你的，$r。', `MaleText_loc7`='Estaba buscando materiales para construir mi último y más grandioso invento, la trituradora portátil con control remoto, cuando esos trols me empezaron a dar garrotazos y me arrastraron hasta las profundidades de su cueva.$B$BRescátame y te ayudaré en tu causa, $r.' WHERE `ID`=8726;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 가자고, 고블린 친구!', `MaleText_loc4`='走吧，地精！', `MaleText_loc5`='走吧，哥布林!', `MaleText_loc7`='¡Vamos, goblin!', `FemaleText_loc1`='어서 가자고, 고블린 친구!', `FemaleText_loc4`='走吧，地精！', `FemaleText_loc5`='走吧，哥布林!', `FemaleText_loc7`='¡Vamos, goblin!' WHERE `ID`=8727;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상급 부대로 승급!', `MaleText_loc4`='升级到经验丰富的士兵！', `MaleText_loc5`='升級到經驗豐富的士兵!', `MaleText_loc7`='¡Mejorar a unidades experimentadas!', `FemaleText_loc1`='상급 부대로 승급!', `FemaleText_loc4`='升级到经验丰富的士兵！', `FemaleText_loc5`='升級到經驗豐富的士兵!', `FemaleText_loc7`='¡Mejorar a unidades experimentadas!' WHERE `ID`=8728;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정예 부대로 승급!', `MaleText_loc4`='升级到老兵！', `MaleText_loc5`='升級到老兵!', `MaleText_loc7`='¡Mejorar a unidades veteranas!', `FemaleText_loc1`='정예 부대로 승급!', `FemaleText_loc4`='升级到老兵！', `FemaleText_loc5`='升級到老兵!', `FemaleText_loc7`='¡Mejorar a unidades veteranas!' WHERE `ID`=8729;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최정예 부대로 승급!', `MaleText_loc4`='升级到勇士！', `MaleText_loc5`='升級到勇士!', `MaleText_loc7`='¡Mejorar a unidades campeonas!', `FemaleText_loc1`='최정예 부대로 승급!', `FemaleText_loc4`='升级到勇士！', `FemaleText_loc5`='升級到勇士!', `FemaleText_loc7`='¡Mejorar a unidades campeonas!' WHERE `ID`=8730;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 땅은 오염됐어요. 이부스 님을 소환해야 합니다!', `FemaleText_loc4`='这片土地被污染了。必须召唤伊弗斯。', `FemaleText_loc5`='這片土地受污染了。必須召喚伊弗斯。', `FemaleText_loc7`='Esta tierra estar contaminada. ¡Ivus debe ser llamado!' WHERE `ID`=8731;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='스톰파이크의 전사들이여, 도와 주십시오! 숲군주께서 우리를 보호해 주겠다고 하셨습니다. 지금 문을 열어야 합니다!', `FemaleText_loc4`='卡尔·雷矛的战士，帮助并保护我们！森林之王已经许诺要保护我们。大门现在必须被打开了！', `FemaleText_loc5`='雷矛的戰士，幫助並保護我們!森林之王已經許諾要保護我們。大門現在必須被打開了!', `FemaleText_loc7`='¡Soldados de Pico Tormenta, ayudadnos y protegednos! El Señor del Bosque nos ha concedido su protección. ¡La puerta debe ser abierta!' WHERE `ID`=8732;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='형제들이여, 어서 오세요.', `FemaleText_loc4`='来，兄弟。', `FemaleText_loc5`='來，兄弟。', `FemaleText_loc7`='Venid, hermanos.' WHERE `ID`=8733;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='앞으로!', `FemaleText_loc4`='前进！', `FemaleText_loc5`='前進!', `FemaleText_loc7`='¡Adelante!' WHERE `ID`=8734;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='숲군주님을 소환하려면 소환진에 정신을 집중해야만 합니다! 서둘러야 합니다! 그대의 모든 힘을 집중하도록 하세요!', `FemaleText_loc4`='如果森林之王要来，我们必须集中思想于召唤法阵！我们需要赶紧！集中精力！', `FemaleText_loc5`='如果森林之王要來，我們必須集中思想於召喚法陣!我們需要趕緊!集中精力!', `FemaleText_loc7`='Si queremos que el Señor del Bosque nos escuche, debemos concentrar nuestros pensamientos en el Círculo de Llamamiento. ¡Debemos darnos prisa! ¡Concentra tus energías!' WHERE `ID`=8735;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사악하디 사악한 필멸의 생명체들이여, 숲이 울부짖는구나! 너희가 벌이는 파괴로 인해 정령들이 몸서리치고 있다. 이부스가 너희를 제거해 이 세계를 깨끗이 정화하겠노라!', `MaleText_loc4`='邪恶，太邪恶了，你们这些凡人！森?在哭泣，元素的力量在毁灭面前颤抖。伊弗斯必须把你们从这世上清除！', `MaleText_loc5`='邪惡,太邪惡了,人類!森林在哭泣。大自然的力量面對毀滅退縮了。伊弗斯必須把你從這世上清除!', `MaleText_loc7`='¡Malvados, malvados mortales! El bosque llora. Los elementos retroceder ante tanta destrucción. ¡Ivus tiene que expulsaros de este mundo!' WHERE `ID`=8736;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서리늑대 부족이여, 내 친히 너희 요새를 파괴하러 왔도다. 이 이부스가 너희의 배신을 응징하리라!', `MaleText_loc4`='我是来铲平你的基地的，霜狼氏族。你们的背叛将受到伊弗斯的惩罚！', `MaleText_loc5`='我是來鏟平你的基地的，霜狼氏族。你們的背叛將受到伊弗斯的懲罰!', `MaleText_loc7`='Yo venir a arrasar sus bases, clan Lobo Gélido. ¡Ivus castiga por su traición!' WHERE `ID`=8737;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고대정령들이여, 일어나라!', `MaleText_loc4`='强大的古树，出现吧！', `MaleText_loc5`='遠古的民族，站起來吧!', `MaleText_loc7`='¡Ancestros, alzaos!' WHERE `ID`=8738;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필멸의 생명체들이여, 너희 요새를 완전히 몰수하겠노라! 너희 육체가 타고남은 재에서 새 생명이 일어서리라!', `MaleText_loc4`='你们的根据地已经丧失了！生命将因它化为废墟而延续！', `MaleText_loc5`='你們的根據地已經喪失了，人類!從它的廢墟中會出現新的生命!', `MaleText_loc7`='¡Su base está destruida, mortales! ¡De sus cenizas renacerá la vida!' WHERE `ID`=8739;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보잘것없는 필멸의 생명체들아, 이제 너희 요새도 끝장이다!', `MaleText_loc4`='你们的根据地已经丧失了，渺小的人类！', `MaleText_loc5`='你們的根據地已經喪失了，渺小的人類!', `MaleText_loc7`='¡Su base está destruida, insignificantes mortales!' WHERE `ID`=8740;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 상급 부대가 전장을 떠나고 있네. 보급품이 더 필요해!', `MaleText_loc4`='经验丰富的士兵已经离开战场。我们需要更多士兵！', `MaleText_loc5`='經驗豐富的士兵已經離開戰場。我們需要更多士兵!', `MaleText_loc7`='Nuestras unidades experimentadas están saliendo del campo. ¡Necesitamos más suministros!' WHERE `ID`=8741;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 정예 부대가 전장을 떠나고 있네. 보급품이 더 필요해!', `MaleText_loc4`='老兵部队已经离开战场。我们需要更多的士兵！', `MaleText_loc5`='老兵部隊已經離開戰場。我們需要更多的士兵!', `MaleText_loc7`='Nuestras unidades veteranas están saliendo del campo. ¡Necesitamos más suministros!' WHERE `ID`=8742;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 최정예 부대가 전장을 떠나고 있네. 보급품이 더 필요해!', `MaleText_loc4`='我们的勇士军队已经离开战场。我们需要更多的军需！', `MaleText_loc5`='我們的勇士軍隊已經離開戰場。我們需要更多的軍需!', `MaleText_loc7`='Nuestras unidades campeonas están saliendo del campo. ¡Necesitamos más suministros!' WHERE `ID`=8743;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상급 부대가 전장에 진입하고 있네!', `MaleText_loc4`='经验丰富的部队已经参战！', `MaleText_loc5`='經驗豐富的部隊已經參戰!', `MaleText_loc7`='¡Unidades experimentadas entrando en combate!' WHERE `ID`=8744;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정예 부대가 전장에 진입하고 있네!', `MaleText_loc4`='作战经验丰富的老兵参战了！', `MaleText_loc5`='作戰經驗豐富的老兵參戰了!', `MaleText_loc7`='¡Unidades veteranas entrando en combate!' WHERE `ID`=8745;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최정예 부대가 전장에 진입하고 있네!', `MaleText_loc4`='勇士部队正开入战斗！', `MaleText_loc5`='勇士部隊正開入戰鬥!', `MaleText_loc7`='¡Unidades campeonas entrando en combate!' WHERE `ID`=8746;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다르나서스에서 저희를 이곳으로 보낸 이유는 스톰파이크 부족이 어려울 때 돕기 위해서입니다.', `MaleText_loc4`='我们奉命从达纳苏斯来到这儿，帮助身处患难的卡尔·雷矛。', `MaleText_loc5`='我們奉命從達納蘇斯來到這兒，幫助身處患難的雷矛氏族。', `MaleText_loc7`='Nos han enviado desde Darnassus para ayudar a los Pico Tormenta cuando más lo necesitan.' WHERE `ID`=8747;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대드루이드께서는 알터랙 계곡의 파괴적인 상황을 알리면 숲군주 이부스께서 분명 도우러 올 것이라 생각하고 계십니다.', `MaleText_loc4`='德鲁伊首领相信，一旦森林之王伊弗斯意识到山谷中的破坏性力量，他就会出现的。', `MaleText_loc5`='德魯伊首領相信，一旦『森林之王』伊弗斯意識到山谷中的破壞性力量，他就會出現的。', `MaleText_loc7`='El archidruida cree que Ivus, el Señor del Bosque, vendrá cuando sea consciente de las fuerzas destructivas que hay en este valle.' WHERE `ID`=8748;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 끔찍한 일에 대한 심판은 우리의 몫이 아닙니다. 이부스가 오셔서 심판의 응징을 내리실 겁니다.', `MaleText_loc4`='让伊弗斯来裁决这些暴行吧。', `MaleText_loc5`='讓伊弗斯來裁決這些暴行吧。', `MaleText_loc7`='No estamos en posición de juzgar estas atrocidades. Ivus lo hará cuando llegue.' WHERE `ID`=8749;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$r|1이여;여;, 저는 믿음에 따라 행동한답니다. 이부스는 분명히 올 거예요.', `FemaleText_loc4`='我的信念指引着我的行动，$r。我知道伊弗斯会来的。', `FemaleText_loc5`='我的信念指引著我的行動，$r。我知道伊弗斯會來的。', `FemaleText_loc7`='Mi fe guía mis actos, $r. Sé que Ivus vendrá.' WHERE `ID`=8750;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 상급 부대가 전장을 떠나고 있소. 보급품이 더 필요하외다!', `MaleText_loc4`='经验丰富的士兵已经离开战场。我们需要更多士兵！', `MaleText_loc5`='經驗豐富的士兵已經離開戰場。我們需要更多士兵!', `MaleText_loc7`='Nuestras unidades experimentadas están saliendo del campo. ¡Necesitamos más suministros!' WHERE `ID`=8751;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 정예 부대가 전장을 떠나고 있소. 보급품이 더 필요하외다!', `MaleText_loc4`='老兵已经离开战场。我们需要更多的士兵！', `MaleText_loc5`='老兵已經離開戰場。我們需要更多的士兵!', `MaleText_loc7`='Nuestras unidades veteranas están saliendo del campo. ¡Necesitamos más suministros!' WHERE `ID`=8752;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 최정예 부대가 전장을 떠나고 있소. 보급품이 더 필요하외다!', `MaleText_loc4`='我们的勇士军队已经离开战场。我们需要更多的军需！', `MaleText_loc5`='我們的勇士軍隊已經離開戰場。我們需要更多的軍需!', `MaleText_loc7`='Nuestras unidades campeonas están saliendo del campo. ¡Necesitamos más suministros!' WHERE `ID`=8753;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상급 부대가 전장으로 진격하고 있소!', `MaleText_loc4`='经验丰富的部队已经接管了防御工作！', `MaleText_loc5`='經驗豐富的部隊已經接管了防禦工作!', `MaleText_loc7`='¡Unidades experimentadas entrando en el campo!' WHERE `ID`=8754;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 정예 부대가 전장에 진입하고 있소!', `MaleText_loc4`='老兵已经离开战场！', `MaleText_loc5`='老兵已經離開戰場!', `MaleText_loc7`='¡Nuestras unidades veteranas están entrando en el campo!' WHERE `ID`=8755;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 최정예 부대가 전투 준비를 마쳤소! 조심해라, 얼라이언스 녀석들아!', `MaleText_loc4`='我们的勇士军队已经装备就绪！联盟，小心了！', `MaleText_loc5`='我們的勇士軍隊已經裝備就緒!聯盟，小心了!', `MaleText_loc7`='¡Nuestras unidades campeonas están equipadas! ¡Cuidado, Alianza!' WHERE `ID`=8756;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='렌퍼럴 님, 이부스와 접촉해 보았습니까?', `MaleText_loc4`='你跟大德鲁伊伊弗斯联系上了吗？', `MaleText_loc5`='你跟大德魯伊伊弗斯聯繫上了嗎?', `MaleText_loc7`='¿Has contactado con Ivus, archidruida?', `FemaleText_loc1`='렌퍼럴 님, 이부스와 접촉해 보았습니까?', `FemaleText_loc4`='你跟大德鲁伊伊弗斯联系上了吗？', `FemaleText_loc5`='你跟大德魯伊伊弗斯聯繫上了嗎?', `FemaleText_loc7`='¿Has contactado con Ivus, archidruida?' WHERE `ID`=8757;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='에메랄드의 꿈에서 깨어난 지 얼마 되지 않아 조금 몽롱하군요. 그래도 이부스의 생명력이 느껴져요. 하지만 제 힘이 충분히 회복되지 않아서 아직 접촉하기는 어렵겠습니다.', `FemaleText_loc4`='我迷失在梦里了。我感觉到了他的生命力，但是我的力量还不够强大，无法进行沟通。', `FemaleText_loc5`='我迷失在夢裡了。我感覺到了他的生命力，但是我的力量還不夠強大，無法進行溝通。', `FemaleText_loc7`='He estado perdida en el Sueño. Puedo sentir su fuerza de vida, pero mis poderes no son lo suficientemente fuertes como para establecer contacto.' WHERE `ID`=8758;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정기가 가득 실린 바람이 불어오고 있군요. 렌퍼럴, 숲군주를 소환하는 일은 어떻게 돼가고 있습니까?', `MaleText_loc4`='大德鲁伊，空气中充满活力。森林之王的情况怎么样？', `MaleText_loc5`='大德魯伊，空氣中充滿活力。森林之王的情況怎麼樣?', `MaleText_loc7`='El aire bulle de energía, archidruida. ¿Cuál es el estado del Señor del Bosque?', `FemaleText_loc1`='정기가 가득 실린 바람이 불어오고 있군요. 렌퍼럴, 숲군주를 소환하는 일은 어떻게 돼가고 있습니까?', `FemaleText_loc4`='大德鲁伊，空气中充满活力。森林之王的情况怎么样？', `FemaleText_loc5`='大德魯伊，空氣中充滿活力。森林之王的情況怎麼樣?', `FemaleText_loc7`='El aire bulle de energía, archidruida. ¿Cuál es el estado del Señor del Bosque?' WHERE `ID`=8759;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n. 숲군주의 위치를 파악했어요. 더욱더 노력해야 합니다! 수정을 더 모아야 해요!', `FemaleText_loc4`='是的。$n。我已经查到了森林之王的位置。我们必须加倍努力！需要更多的水晶！', `FemaleText_loc5`='是的。$n。我已經查到了森林之王的位置。我們必須加倍努力!需要更多的水晶!', `FemaleText_loc7`='Sí, $n. He localizado al Señor del Bosque. ¡Debemos redoblar nuestros esfuerzos! ¡Se necesitan más cristales!' WHERE `ID`=8760;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='숲 전체가 흔들리고 있어요. 사나운 바람이 몰아쳐요! 숲군주가 다가오고 있는 건가요?', `MaleText_loc4`='森林剧烈震动起来！飓风咆哮！森林之王要来了吗？', `MaleText_loc5`='森林劇烈震動起來!颶風咆哮!森林之王要來了嗎?', `MaleText_loc7`='¡El bosque tiembla y se estremece! ¡Los vientos aúllan! ¿Se aproxima el Señor del Bosque?', `FemaleText_loc1`='숲 전체가 흔들리고 있어요. 사나운 바람이 몰아쳐요! 숲군주가 다가오고 있는 건가요?', `FemaleText_loc4`='森林剧烈震动起来！飓风咆哮！森林之王要来了吗？', `FemaleText_loc5`='森林劇烈震動起來!颶風咆哮!森林之王要來了嗎?', `FemaleText_loc7`='¡El bosque tiembla y se estremece! ¡Los vientos aúllan! ¿Se aproxima el Señor del Bosque?' WHERE `ID`=8761;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n, 숲군주에게 이 계곡의 파괴 상황 알렸어요. 서둘러 소환진으로 가야 합니다. 준비하세요!', `FemaleText_loc4`='森林之王已经知晓了这个山谷的毁灭，$n。很快我们就要到召唤法阵去了。做好准备！', `FemaleText_loc5`='森林之王已經知曉了這個山谷的毀滅，$n。很快我們就要到召喚法陣去了。做好準備!', `FemaleText_loc7`='El Señor del Bosque es consciente de la destrucción que habita en este valle, $n. Pronto deberemos dirigirnos al Círculo de Invocación. ¡Prepárate!' WHERE `ID`=8762;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주제도 모르는 바보 멀베릭에게 격추당했소. 요새로 돌아가지 못하면 모든 게 끝장일까 두렵소! 멀베릭과 그 전투와이번 부대를 막아내야 하오!', `MaleText_loc4`='我被穆维里克这个鲁莽的蠢货击中了。我担心要是我无法回到基地中去的话，一切都要玩完了！必须阻止穆维里克和他的飞行中队！', `MaleText_loc5`='我被穆維里克這個魯莽的傻子擊中了。我擔心要是不能將這東西送到基地的話，所有的事情都會失敗的!必須阻止穆維里克和他的騎兵隊!', `MaleText_loc7`='Fui derribado por un insensato, Mulverick. Me temo que si no consigo regresar a la base, ¡todo se habrá perdido! ¡Hay que detener a Mulverick y a su escuadrón de jinetes de guerra!' WHERE `ID`=8763;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뒤는 제가 엄호하겠습니다, 이크만 님. 어서 출발하시죠!', `MaleText_loc4`='我来支援你，艾克曼。快走！', `MaleText_loc5`='我來支援你，艾克曼。快走!', `MaleText_loc7`='Te cubro la espalda, Ichman. ¡VAMOS, VAMOS, VAMOS!', `FemaleText_loc1`='뒤는 제가 엄호하겠습니다, 이크만 님. 어서 출발하시죠!', `FemaleText_loc4`='我来支援你，艾克曼。快走！', `FemaleText_loc5`='我來支援你，艾克曼。快走!', `FemaleText_loc7`='Te cubro la espalda, Ichman. ¡VAMOS, VAMOS, VAMOS!' WHERE `ID`=8764;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직도 믿기지가 않아... 매일 하던 정찰 임무로 중앙 비무장지대 위를 날던 중 변을 당했지 뭔가. 난 이크만과 실도르 모두 호드 편대사령관 멀베릭에게 당하는 모습을 목격했네! 그래서 홧김에 혼자 동료를 벗어나 그 잘난 척하는 멀베릭 녀석을 격추시켜 버렸지. 그런데 녀석이 떨어지기 전에 내 그리핀에 상처를 입히는 바람에 불행히 나도 추락했고, 이렇게 이 야만족 녀석들에게 포로로 붙잡힌 신세가 됐다네.$B$B꼭 요새로 돌아가야 하니 도와주게!', `MaleText_loc4`='真不敢相信……我在中央非军事区执行例行侦察任务时，事情变得一团糟。我看见部落中校穆维里克击倒了艾克曼和斯里多尔！我发怒了，冲出队伍将穆维里克打倒在地。不幸的是，他在倒下之前击中了我的狮鹫，我也随之跌下。我被这些野蛮的家伙抓住啦。$B$B我必须返回基地！帮帮我！', `MaleText_loc5`='真不敢相信...我在中央非軍事區執行例行偵察任務時，事情變得一團糟。我看見部落空軍指揮官穆維里克擊倒了艾克曼和斯里多爾!怒不可遏的我，撇下我的僚機，把那個愛現自大的穆維里克打了下來。不幸的是，他在墜機之前擊中了我的獅鷲獸，我也隨之跌下。結局就是我被這些野蠻的傢伙給活逮了。$B$B我必須返回基地!幫幫我!', `MaleText_loc7`='No me lo puedo creer... Estaba haciendo una misión de reconocimiento de rutina por la zona desmilitarizada central cuando, de pronto, se desató el infierno. Vi al Comandante del aire de la Horda, Mulverick, derribar a Ichman y a Slidore. Me enfurecí y me separé de mi compañero y conseguí derribar a ese petulante de Mulverick. Por desgracia, golpeó mi grifo antes de estrellarse, con lo que yo también caí. Acabé aquí, capturado por estos salvajes.$B$B¡Tengo que volver a la base! ¡Ayuda!' WHERE `ID`=8765;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 엄호하겠습니다, 비포르 님. 가시죠!', `MaleText_loc4`='我来掩护你，维波里。快点行动吧！', `MaleText_loc5`='我來掩護你，維波里。快行動!', `MaleText_loc7`='Te cubro, Vipore. ¡En marcha!', `FemaleText_loc1`='제가 엄호하겠습니다, 비포르 님. 가시죠!', `FemaleText_loc4`='我来掩护你，维波里。快点行动吧！', `FemaleText_loc5`='我來掩護你，維波里。快行動!', `FemaleText_loc7`='Te cubro, Vipore. ¡En marcha!' WHERE `ID`=8766;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$C|1이여;여;, 내 그리핀이 추락해 불타고 있을 때 녀석들이 날 조롱하는 목소리를 들었지.$B$B"실도르! 너한테선 지독한 냄새가 나!"라고 소리치더군.$B$B감히 이 실도르 님에게 그런 조롱을 퍼붓다니! 여기서 빠져나가도록 좀 도와줘! 정말로 냄새 나는 게 누군지 똑똑히 가르쳐 줄 수 있도록!', `MaleText_loc4`='当我的狮鹫坠落时，我听到了他们嘲弄的笑声，$c。$B$B“斯里多尔， 你太差劲了！”他们大声嚷道。$B$B没有人敢对斯里多尔那样说话！帮我离开这里，我会让他们知道我的厉害！', `MaleText_loc5`='當我的獅鷲獸墜落時，我聽到了他們嘲弄的笑聲，$c。$B$B「斯里多爾， 你太差勁了!」他們大聲嚷道。$B$B沒有人敢對斯里多爾那樣說話!幫我離開這裡，我會讓他們知道我的厲害!', `MaleText_loc7`='Oí su burlona risa cuando mi grifo se estrellaba y se quemaba, $c.$B$B"¡Slidore, apestas!" Gritaron.$B$B¡Nadie habla así a Slidore! Ayúdame a salir de aquí para poder demostrarles quién es el que apesta.' WHERE `ID`=8767;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뒤는 제가 엄호하죠, 실도르 님. 그런데 솔직히 말해서 정말로 냄새는 납니다. 세수라도 좀 하시죠...', `MaleText_loc4`='我来支援你了，斯里多尔，但说实话，你真是太臭了。快冲个澡，伙计。', `MaleText_loc5`='我來支援你了，斯里多爾，但說實話，你真是太臭了。快沖個澡，夥計。', `MaleText_loc7`='Te cubro la espalda, Slidore, pero para ser sincero contigo, sí que apestas. Dúchate, tío.', `FemaleText_loc1`='뒤는 제가 엄호하죠, 실도르 님. 그런데 솔직히 말해서 정말로 냄새는 납니다. 세수라도 좀 하시죠...', `FemaleText_loc4`='我来支援你了，斯里多尔，但说实话，你真是太臭了。快冲个澡，伙计。', `FemaleText_loc5`='我來支援你了，斯里多爾，但說實話，你真是太臭了。快沖個澡，夥計。', `FemaleText_loc7`='Te cubro la espalda, Slidore, pero para ser sincera contigo, sí que apestas. Dúchate, tío.' WHERE `ID`=8768;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 출발할 테니까 엄호하도록!', `MaleText_loc4`='掩护我，我在趁机逃跑！', `MaleText_loc5`='掩護我，我在趁機逃跑!', `MaleText_loc7`='¡Cúbreme, voy a por todas!' WHERE `ID`=8769;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='낭비할 시간이 없다네. 정말 긴 여정이 될 거야! 엄호 부탁해!', `MaleText_loc4`='我们没时间浪费了。路途遥远！保护我！', `MaleText_loc5`='我們沒時間浪費了。路途遙遠!保護我!', `MaleText_loc7`='No tenemos tiempo que perder. ¡Un recorrido muy largo! ¡Cúbreme!' WHERE `ID`=8770;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 요새로 충분히 가까이 가기만 하면 거기서 순간이동을 할 수 있소!', `MaleText_loc4`='让我尽量接近基地，这样我才能使用传送技能！', `MaleText_loc5`='讓我盡量接近基地，然後我會開啟傳送通道!', `MaleText_loc7`='Acércame lo suficiente a la base para que pueda canalizar un teletransporte.' WHERE `ID`=8771;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 충분히 멀리 나왔군! 요새에서 다시 만납시다!', `MaleText_loc4`='你走过头啦！到营地来见我！', `MaleText_loc5`='你走過頭啦!到營地來見我!', `MaleText_loc7`='¡Hasta aquí! ¡Nos vemos en la base!' WHERE `ID`=8772;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멀베릭, 이제 넌 끝장이야!', `MaleText_loc4`='你完蛋了，穆维!', `MaleText_loc5`='你撐不了多久，穆維!', `MaleText_loc7`='¡Mulv, acabaré contigo!' WHERE `ID`=8773;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전장 중앙에 있는 얼라이언스 부대를 치기 위한 공격명령서가 있는데, 누군가 이걸 지휘관에게 가져다줬으면 좋겠단 말이야.', `FemaleText_loc4`='我在此有命令从中场进攻联盟军队。我需要有人把它们带到攻击指挥那里。', `FemaleText_loc5`='我在此有命令從中場進攻聯盟軍隊。我需要有人把它們帶到攻擊指揮那裡。', `FemaleText_loc7`='Tengo órdenes para atacar a las tropas de la Alianza en los campos centrales. Necesito que alguien se las lleve al líder de asalto.' WHERE `ID`=8774;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리는 임금을 받고 이 추운 알터랙 계곡에서 선혈이 낭자한 전투를 치르고 있네. 아주 딱 맞는 일이지.', `FemaleText_loc4`='我们在奥特兰克山谷发动的战斗冷酷而血腥。太完美了。', `FemaleText_loc5`='我們在奧特蘭克山谷發動的戰鬥冷酷而血腥。太完美了。', `FemaleText_loc7`='La batalla que luchamos en el Valle de Alterac, es una batalla fría y sangrienta. Es perfecta.' WHERE `ID`=8775;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 명령서를 가르릭 전투대장께 전달하겠습니다!', `MaleText_loc4`='是的，我会将这些订单交给霜狼突击队队长的！', `MaleText_loc5`='是的，我會將這些訂單交給將領加瑞克的!', `MaleText_loc7`='¡Sí, le entregaré las órdenes al maestro de guerra Garrick!', `FemaleText_loc1`='네, 명령서를 가르릭 전투대장께 전달하겠습니다!', `FemaleText_loc4`='是的，我会将这些订单交给霜狼突击队队长的！', `FemaleText_loc5`='是的，我會將這些訂單交給將領加瑞克的!', `FemaleText_loc7`='¡Sí, le entregaré las órdenes al maestro de guerra Garrick!' WHERE `ID`=8776;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='때로는 이 숲이 아주 혼란스러울 때도 있답니다. 조심하도록 하세요.', `FemaleText_loc4`='这片森林容易使人迷路！要小心。', `FemaleText_loc5`='這片森林容易使人迷路!要小心。', `FemaleText_loc7`='Este bosque puede resultar confuso. Ten cuidado ahí fuera.' WHERE `ID`=8777;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='즐겁고 풍족한 명절 되라고!', `MaleText_loc4`='储存下来的物资都给你和你的家属！', `MaleText_loc5`='儲存下來的物資都給你和你的家屬!', `MaleText_loc7`='¡Descuentos de temporada para ti y los tuyos!', `FemaleText_loc1`='즐겁고 풍족한 명절 되라고!', `FemaleText_loc4`='储存下来的物资都给你和你的家属！', `FemaleText_loc5`='儲存下來的物資都給你和你的家屬!', `FemaleText_loc7`='¡Descuentos de temporada para ti y los tuyos!' WHERE `ID`=8778;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='굴뚝나무 목장조합 직영 농장에서 직접 공수해온 신선한 재료로 만든 맛있는 요리를 맛보라고!', `MaleText_loc4`='这是刚从农场带来的新鲜货--这是烟林牧场的健康食品！', `MaleText_loc5`='這是剛從農場帶來的新鮮貨--這是燻木牧場的健康食品!', `MaleText_loc7`='De la granja a la mesa, ¡todo lo bueno de los Pastos de Bosquehumeante!', `FemaleText_loc1`='굴뚝나무 목장조합 직영 농장에서 직접 공수해온 신선한 재료로 만든 맛있는 요리를 맛보라고!', `FemaleText_loc4`='这是刚从农场带来的新鲜货--这是烟林牧场的健康食品！', `FemaleText_loc5`='這是剛從農場帶來的新鮮貨--這是燻木牧場的健康食品!', `FemaleText_loc7`='De la granja a la mesa, ¡todo lo bueno de los Pastos de Bosquehumeante!' WHERE `ID`=8779;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='트랄랄랄라! 풍성한 계절이 돌아왔군! 축제를 맞이해 나온 특별 용품들을 대폭 할인된 가격으로 줄 테니 한번 둘러보라고!', `MaleText_loc4`='现在是廉价货上市的时候！啦啦啦啦！', `MaleText_loc5`='現在是廉價貨上市的時候!啦啦啦啦!', `MaleText_loc7`='¡Es la temporada de los grandes descuentos! ¡La, la, la, la!', `FemaleText_loc1`='트랄랄랄라! 풍성한 계절이 돌아왔군! 축제를 맞이해 나온 특별 용품들을 대폭 할인된 가격으로 줄 테니 한번 둘러보라고!', `FemaleText_loc4`='现在是廉价货上市的时候！啦啦啦啦！', `FemaleText_loc5`='現在是廉價貨上市的時候!啦啦啦啦!', `FemaleText_loc7`='¡Es la temporada de los grandes descuentos! ¡La, la, la, la!' WHERE `ID`=8780;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번 겨울맞이 축제는 굴뚝나무 목장조합에서 제공하는 맛있는 요리와 함께하라고!', `MaleText_loc4`='尽情享受冬幕节吧！品尝来自烟林牧场的盛宴！', `MaleText_loc5`='盡情享受冬幕節吧!品嘗來自燻木牧場的盛宴!', `MaleText_loc7`='¡Que tengas un feliz festín del Festival de Invierno! ¡Puedes empezar a disfrutarlo con los manjares de los Pastos de Bosquehumeante!', `FemaleText_loc1`='이번 겨울맞이 축제는 굴뚝나무 목장조합에서 제공하는 맛있는 요리와 함께하라고!', `FemaleText_loc4`='尽情享受冬幕节吧！品尝来自烟林牧场的盛宴！', `FemaleText_loc5`='盡情享受冬幕節吧!品嘗來自燻木牧場的盛宴!', `FemaleText_loc7`='¡Que tengas un feliz festín del Festival de Invierno! ¡Puedes empezar a disfrutarlo con los manjares de los Pastos de Bosquehumeante!' WHERE `ID`=8781;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번 겨울맞이 축제에는 어떤 선물을 받고 싶은지 겨울 할아버지에게 소원을 비는 거 절대 잊지마!', `MaleText_loc4`='请告诉冬天爷爷是什么秘密让你想要得到冬幕！', `MaleText_loc5`='記得告訴冬天爺爺今年的冬幕節你想得到什麼神秘禮物!', `MaleText_loc7`='¡Asegúrate de decirle al Gran Padre Invierno la sorpresa secreta que te gustaría recibir este Festival de Invierno!', `FemaleText_loc1`='이번 겨울맞이 축제에는 어떤 선물을 받고 싶은지 겨울 할아버지에게 소원을 비는 거 절대 잊지마!', `FemaleText_loc4`='请告诉冬天爷爷是什么秘密让你想要得到冬幕！', `FemaleText_loc5`='記得告訴冬天爺爺今年的冬幕節你想得到什麼神秘禮物!', `FemaleText_loc7`='¡Asegúrate de decirle al Gran Padre Invierno la sorpresa secreta que te gustaría recibir este Festival de Invierno!' WHERE `ID`=8782;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 데 찾아봤자 실속 없이 돈만 낭비할 뿐이지... 굴뚝나무 목장조합에서 맛있는 요리를 사서 즐거운 겨울맞이 축제 보내라고!', `MaleText_loc4`='别花钱购买那些铃当！为了你的冬幕盛宴，把烟林牧场买下吧！', `MaleText_loc5`='別花錢購買那些鈴噹了!為了你的冬幕節盛宴，快來買些燻木牧場的小點心吧!', `MaleText_loc7`='¡No permitas que el tintineo de las campanas no deje sonar el tintineo de las monedas de tu bolsillo! ¡Compra manjares de los Pastos de Bosquehumeante para celebrar el Festival de Invierno!', `FemaleText_loc1`='다른 데 찾아봤자 실속 없이 돈만 낭비할 뿐이지... 굴뚝나무 목장조합에서 맛있는 요리를 사서 즐거운 겨울맞이 축제 보내라고!', `FemaleText_loc4`='别花钱购买那些铃当！为了你的冬幕盛宴，把烟林牧场买下吧！', `FemaleText_loc5`='別花錢購買那些鈴噹了!為了你的冬幕節盛宴，快來買些燻木牧場的小點心吧!', `FemaleText_loc7`='¡No permitas que el tintineo de las campanas no deje sonar el tintineo de las monedas de tu bolsillo! ¡Compra manjares de los Pastos de Bosquehumeante para celebrar el Festival de Invierno!' WHERE `ID`=8783;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고구마라도 좀 있으면 모닥불에다가 구워 먹을 텐데... 음, 맛있겠다!', `MaleText_loc4`='要是我有栗子的话，你最好相信我会将它们烤熟吃掉的。嗯！', `MaleText_loc5`='要是我有栗子的話，你最好相信我會將它們烤熟吃掉的。嗯!', `MaleText_loc7`='Si tuviera castañas, te aseguro que estaría asándolas al fuego ahora mismo. ¡Mmmm!', `FemaleText_loc1`='고구마라도 좀 있으면 모닥불에다가 구워 먹을 텐데... 음, 맛있겠다!', `FemaleText_loc4`='要是我有栗子的话，你最好相信我会将它们烤熟吃掉的。嗯！', `FemaleText_loc5`='要是我有栗子的話，你最好相信我會將它們烤熟吃掉的。嗯!', `FemaleText_loc7`='Si tuviera castañas, te aseguro que estaría asándolas al fuego ahora mismo. ¡Mmmm!' WHERE `ID`=8784;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연말연시엔 포장지 구입하는 것을 잊지 말라고! 친구들에게 방어구와 무기를 예쁘게 포장해 선물하는 것만큼 겨울맞이 축제의 따뜻한 정을 잘 전달할 수 있는 방법도 없지!', `MaleText_loc4`='在假期里不要忘记储备包装纸！没什么能比包装精美的护甲和武器一样让你的朋友和家人感受到冬幕节的温馨快乐！', `MaleText_loc5`='在假期裡不要忘記儲備包裝紙!沒什麼能比包裝精美的護甲和武器一樣讓你的朋友和家人感受到冬幕節的溫馨快樂!', `MaleText_loc7`='¡No te olvides de comprar mucho papel de regalo para las vacaciones! Nada dice "Feliz Festival de Invierno" como armas y armaduras envueltas en papel de regalo para tus amigos y tu familia.', `FemaleText_loc1`='연말연시엔 포장지 구입하는 것을 잊지 말라고! 친구들에게 방어구와 무기를 예쁘게 포장해 선물하는 것만큼 겨울맞이 축제의 따뜻한 정을 잘 전달할 수 있는 방법도 없지!', `FemaleText_loc4`='在假期里不要忘记储备包装纸！没什么能比包装精美的护甲和武器一样让你的朋友和家人感受到冬幕节的温馨快乐！', `FemaleText_loc5`='在假期裡不要忘記儲備包裝紙!沒什麼能比包裝精美的護甲和武器一樣讓你的朋友和家人感受到冬幕節的溫馨快樂!', `FemaleText_loc7`='¡No te olvides de comprar mucho papel de regalo para las vacaciones! Nada dice "Feliz Festival de Invierno" como armas y armaduras envueltas en papel de regalo para tus amigos y tu familia.' WHERE `ID`=8785;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='축제 특선으로 나온 물건을 보고 싶습니다.', `MaleText_loc4`='让我看看你携带的食物。', `MaleText_loc5`='讓我看看你攜帶的食物。', `MaleText_loc7`='Deja que eche un vistazo a tus mercancías de temporada.', `FemaleText_loc1`='축제 특선으로 나온 물건을 보고 싶습니다.', `FemaleText_loc4`='让我看看你携带的食物。', `FemaleText_loc5`='讓我看看你攜帶的食物。', `FemaleText_loc7`='Deja que eche un vistazo a tus mercancías de temporada.' WHERE `ID`=8786;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 이제부터 더 빨리 달려야겠어!', `MaleText_loc4`='快跑！', `MaleText_loc5`='快跑!', `MaleText_loc7`='¡Tiempo doble!' WHERE `ID`=8787;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 작동 중입니다. 완료 60초 전...', `MaleText_loc4`='%s正在启动。还剩60秒。', `MaleText_loc5`='%s整裝中。還剩60秒。', `MaleText_loc7`='%s armado. Faltan 60 segundos.' WHERE `ID`=8788;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s 준비 완료, 맹금의 그리핀 이동 중...', `MaleText_loc4`='%s已启动。狮鹫准备就绪。', `MaleText_loc5`='%s整裝完畢。鷹巢山獅鷲獸出發。', `MaleText_loc7`='%s armado. Grifo nidal en ruta.' WHERE `ID`=8789;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 파괴되었습니다. 공습 지점 확인 불가능... 임무 중단...', `MaleText_loc4`='%s被摧毁了！空军无法确认袭击点。行动中断。', `MaleText_loc5`='%s被摧毀了。空中部隊無法確認攻擊地點。任務取消。', `MaleText_loc7`='%s destruido. Asalto aéreo imposible de confirmar el punto de ataque. Misión abortada.' WHERE `ID`=8790;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰파이크의 병사들이여, 나를 따르라! 반드시 이 봉화를 설치해야 한다.', `MaleText_loc4`='雷矛士兵，过来帮帮我！必须插好火炬。', `MaleText_loc5`='雷矛士兵，過來幫幫我!必須插好火炬。', `MaleText_loc7`='¡Soldados de Pico Tormenta, venid en mi ayuda! Hay que colocar el localizador.' WHERE `ID`=8791;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새겨들으시오! 이 봉화를 눈사태 무덤으로 가져가서 설치하시오! 그리고 그곳을 수호하여 내 그리핀이 위치를 파악할 시간을 벌어 주시오.$B$B그리핀이 정확한 공격 위치를 파악하면 멀베릭과 그 편대원들은 수모를 당하게 될 것이오!', `MaleText_loc4`='注意！你需要带上这根火炬，将它插在中央墓地！要好好保护它，以便我的狮鹫能进行追踪。$B$B如果我的狮鹫能准确定位的话，穆维和他的手下会感到耻辱的！', `MaleText_loc5`='注意!你需要帶上這根火炬，將它插在中央墓地!要好好保護它，以便我的獅鷲獸能進行追蹤。$B$B如果我的獅鷲獸能準確定位的話，穆維和他的手下會感到羞恥的!', `MaleText_loc7`='¡Presta atención, Soldado! Tienes que llevar este localizador al Cementerio Avalancha y colocarlo ahí. Protégelo hasta que mi grifo pueda bloquear.$B$BSi mi grifo consigue una ubicación de ataque sólida, Mulv y su grupo recibirán una gran humillación.' WHERE `ID`=8792;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='걱정 마십시오, 이크만. 봉화를 주세요!', `MaleText_loc4`='我是你的人。给我火炬！', `MaleText_loc5`='我是你的人。給我火炬!', `MaleText_loc7`='Soy tu hombre, Ich. Dame un localizador.', `FemaleText_loc1`='걱정 마십시오, 이크만. 봉화를 주세요!', `FemaleText_loc4`='我是你的人。给我火炬！', `FemaleText_loc5`='我是你的人。給我火炬!', `FemaleText_loc7`='Yo lo haré, Ich. Dame un localizador.' WHERE `ID`=8793;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='편대 출정 준비 완료! 병사들이여, 나를 따르라!', `MaleText_loc4`='我准备飞行了！士兵们，过来帮忙！', `MaleText_loc5`='我準備飛行了!士兵們，過來幫忙!', `MaleText_loc7`='¡Mi vuelo está listo! ¡Soldados, venid en mi ayuda!' WHERE `ID`=8794;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n! 드디어 왔군!$B$B이 봉화를 가져가서 중앙 전장의 동부 분화구에 설치하도록 ! 봉화가 공습 위치를 알려 주면 나의 편대가 떠서 그곳을 초토화할 것이다!', `MaleText_loc4`='$n！你总算来了！$B$B你必须带着这个信号灯并把它放置在中心战场东部的凹地中。当信号灯指示出坐标后，我的小伙子们就会进攻！', `MaleText_loc5`='$n!終於!$B$B你必須帶著這個信號燈並把它放置在中心戰場東部的凹地中。當信號燈指示出座標後我的飛行隊就會進攻!', `MaleText_loc7`='¡$n! ¡Por fin!$B$BTienes que coger este localizador y colocarlo en el cráter del este del campo de batalla central. Mi vuelo atacará cuando el localizador transmita las coordenadas.' WHERE `ID`=8795;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='봉화를 주십시오, 실도르! 그런데 아직도 냄새가 지독하군요!', `MaleText_loc4`='给我信号灯，斯里多尔！还有，你还是很臭！', `MaleText_loc5`='給我信號燈，斯里多爾!還有，你還是很臭!', `MaleText_loc7`='¡Dame el localizador, Slidore! ¡Por cierto, sigues apestando!', `FemaleText_loc1`='봉화를 주십시오, 실도르! 그런데 아직도 냄새가 지독하군요!', `FemaleText_loc4`='给我信号灯，斯里多尔！还有，你还是很臭！', `FemaleText_loc5`='給我信號燈，斯里多爾!還有，你還是很臭!', `FemaleText_loc7`='¡Dame el localizador, Slidore! ¡Por cierto, sigues apestando!' WHERE `ID`=8796;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사기가 회복됐다! 그리핀들이 출격 준비를 마쳤노라! 오라, 병사들이여! 나를 따르라!', `MaleText_loc4`='他们的精神恢复了！狮鹫已经准备好作战了！来吧，战士们！到我这儿来！', `MaleText_loc5`='他們的精神恢復了!獅鷲獸已經準備好作戰了!來吧，戰士們!到我這兒來!', `MaleText_loc7`='¡Sus espíritus han sido restaurados! ¡Los grifos están listos para atacar! ¡Adelante, Soldados! ¡Vengan junto a mí!' WHERE `ID`=8797;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리핀들이 출격 준비를 마쳤네, $n! 이 봉화를 가져가서 전장 중앙의 서부 분화구에 설치하도록 하게.$B$B그렇게 하면 이번 전투는 우리의 승리일세!', `MaleText_loc4`='狮鹫准备袭击了，$n！你必须带上这根火炬，将它插在战场中心的西环形山。$B$B去吧，胜利是属于我们的！', `MaleText_loc5`='獅鷲獸準備襲擊了，$n!你必須帶上這根火炬，將它插在戰場中心的西環形山。$B$B去吧，勝利是屬於我們的!', `MaleText_loc7`='¡Los grifos están listos para atacar, $n! Debes coger este localizador y colocarlo en el cráter del oeste del campo de batalla central.$B$B¡Hazlo y la victoria será nuestra!' WHERE `ID`=8798;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비 완료됐습니다, 비포르! 봉화를 주십시오.', `MaleText_loc4`='我准备好了，维波里！给我一个信号。', `MaleText_loc5`='我準備好了，維波里!給我一個信號。', `MaleText_loc7`='¡Estoy listo para dar caña, Vipore! Dame un localizador.', `FemaleText_loc1`='준비 완료됐습니다, 비포르! 봉화를 주십시오.', `FemaleText_loc4`='我准备好了，维波里！给我一个信号。', `FemaleText_loc5`='我準備好了，維波里!給我一個信號。', `FemaleText_loc7`='¡Estoy lista para dar caña, Vipore! Dame un localizador.' WHERE `ID`=8799;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겨울도끼 부족의 지혜는 이제 우리 것일세. $n, 자네가 이 힘을 원한다면 잠시 동안이나마 쓸 수 있도록 허락하겠네.', `MaleText_loc4`='我们掌握了冰斧的智慧，$n。如你所愿，他的力量将在短期内为你所用。', `MaleText_loc5`='我們掌握了冰斧的智慧，$n。如你所願，他的力量將在短期內為你所用。', `MaleText_loc7`='Ahora tenemos la sabiduría del Hacha Invernal, $n. Este poder puede ser tuyo durante un corto período de tiempo si así lo deseas.' WHERE `ID`=8800;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겨울도끼 부족의 지혜를 주십시오!', `MaleText_loc4`='赐予我冰斧的智慧！', `MaleText_loc5`='賜予我冰斧的智慧!', `MaleText_loc7`='¡Concédeme la sabiduría del Hacha Invernal!', `FemaleText_loc1`='겨울도끼 부족의 지혜를 주십시오!', `FemaleText_loc4`='赐予我冰斧的智慧！', `FemaleText_loc5`='賜予我冰斧的智慧!', `FemaleText_loc7`='¡Concédeme la sabiduría del Hacha Invernal!' WHERE `ID`=8801;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 부대는 아직 승급하지 않았어. 승급할 보급품이 부족하네.', `MaleText_loc4`='我们的军队不能升级，军需不够，无法升级。', `MaleText_loc5`='我們的軍隊不能升級，軍需不夠，無法升級。', `MaleText_loc7`='Nuestras unidades no están mejoradas y no tengo suficientes suministros para hacerlo.' WHERE `ID`=8802;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 부대가 상급 부대로 승급하기는 했지만 정예 부대로 승급하기에는 보급품이 부족하네.', `MaleText_loc4`='我们的军队已经升级到经验丰富的军队，但是我没有足够的军需升级到老兵。', `MaleText_loc5`='我們的軍隊已經升級到經驗豐富的軍隊，但是我沒有足夠的軍需升級到老兵。', `MaleText_loc7`='Nuestras unidades han sido mejoradas a experimentadas, pero no tengo suficientes suministros para mejorarlas a veteranas.' WHERE `ID`=8803;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 부대가 정예 부대로 승급하기는 했지만 최정예 부대로 승급하기에는 보급품이 부족하네.', `MaleText_loc4`='我们的军队已经升级到老兵，但是我没有足够的军需升级到勇士。', `MaleText_loc5`='我們的軍隊已經升級到老兵，但是我沒有足夠的軍需升級到勇士。', `MaleText_loc7`='Nuestras unidades han sido mejoradas a veteranas, pero no tengo suficientes suministros para mejorarlas a campeonas.' WHERE `ID`=8804;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 부대가 상급 부대로 승급할 보급품이 충분하네.', `MaleText_loc4`='我有足够的军需将我们的军队升级到经验丰富的军队。', `MaleText_loc5`='我有足夠的軍需將我們的軍隊升級到經驗豐富的軍隊。', `MaleText_loc7`='Tengo suficientes suministros para mejorar nuestras tropas a experimentadas.' WHERE `ID`=8805;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 부대가 정예 부대로 승급할 보급품이 충분하네.', `MaleText_loc4`='我有足够的军需将我们的军队升级到老兵。', `MaleText_loc5`='我有足夠的軍需將我們的軍隊升級到老兵。', `MaleText_loc7`='Tengo suficientes suministros para mejorar nuestras tropas a veteranas.' WHERE `ID`=8806;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 부대가 최정예 부대로 승급할 보급품이 충분하네.', `MaleText_loc4`='我有足够的军需将我们的军队升级到勇士。', `MaleText_loc5`='我有足夠的軍需將我們的軍隊升級到勇士。', `MaleText_loc7`='Tengo suficientes suministros para mejorar nuestras tropas a campeonas.' WHERE `ID`=8807;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 부대가 최정예 부대로 승급하기는 했지만 그래도 보급품을 좀 더 모아야 하네.', `MaleText_loc4`='我们的军队已经升级到勇士，但是我仍需要收集更多的军需。', `MaleText_loc5`='我們的軍隊已經升級到勇士，但是我仍需要收集更多的軍需。', `MaleText_loc7`='Nuestras unidades han sido mejoradas a campeonas, pero todavía puedo recoger más suministros.' WHERE `ID`=8808;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 이상 보급품을 저장할 수 없네. 보관할 공간이 이미 바닥났단 말일세.', `MaleText_loc4`='我不能再存储物资了。我的背包都满了！', `MaleText_loc5`='我不能再存儲物資啦。我的背包都滿啦!', `MaleText_loc7`='No puedo seguir almacenando suministros. ¡Tengo más de los que necesito!' WHERE `ID`=8809;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새로운 무기를 다루는 법을 배우러 온 건가, 아니면 나의 소중한 시간을 빼앗으러 온 건가?', `MaleText_loc4`='到这儿是学习如何使用新武器，还是来浪费我时间的？', `MaleText_loc5`='到這兒是學習如何使用新武器，還是來浪費我時間的?', `MaleText_loc7`='¿Has aprendido a empuñar una nueva arma, o solo a hacerme perder el tiempo?' WHERE `ID`=8810;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무기 훈련을 받고 싶습니다.', `MaleText_loc4`='我想进行一些武器方面的训练', `MaleText_loc5`='我想進行一些武器訓練', `MaleText_loc7`='Me gustaría aprender a utilizar armas.', `FemaleText_loc1`='무기 훈련을 받고 싶습니다.', `FemaleText_loc4`='我想进行一些武器方面的训练', `FemaleText_loc5`='我想進行一些武器訓練', `FemaleText_loc7`='Me gustaría aprender a utilizar armas.' WHERE `ID`=8811;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 무기 기술을 배울 수 있는 무기 전문가가 있습니까?', `MaleText_loc4`='其他的武器大师能教给我什么呢？', `MaleText_loc5`='其他的武器大師能教給我什麼呢?', `MaleText_loc7`='¿Qué pueden enseñar otros maestros de armas?', `FemaleText_loc1`='다른 무기 기술을 배울 수 있는 무기 전문가가 있습니까?', `FemaleText_loc4`='其他的武器大师能教给我什么呢？', `FemaleText_loc5`='其他的武器大師能教給我什麼呢?', `FemaleText_loc7`='¿Qué pueden enseñar otros maestros de armas?' WHERE `ID`=8812;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 무기를 배우고 싶은지 말해 보게. 볼일이 없다면 썩 물러가도록.', `MaleText_loc4`='你想要学习哪种武器技能？', `MaleText_loc5`='告訴我你想要學那項武器，不然就走開。', `MaleText_loc7`='Dime qué arma quieres aprender a usar o vete.' WHERE `ID`=8813;
