UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰파이크 무덤은 던 발다르의 동쪽 다리 건너에 있으며 산을 앞뒤로 만나고 있습니다.$B$B현재 얼라이언스가 점령하고 있습니다.', `MaleText_loc4`='穿过丹巴达尔以东的桥梁，雷矛墓地就在群山之中。$B$B联盟控制着这片土地。', `MaleText_loc5`='穿過丹巴達爾以東的橋樑，雷矛墓地就在群山之中。$B$B聯盟控制著這片土地。', `MaleText_loc7`='El Cementerio Pico Tormenta está en las montañas, pasado el puente al este de Dun Baldar.$B$BActualmente pertenece a la Alianza.' WHERE `ID`=8817;
