UPDATE `locales_broadcast_text` SET `MaleText_loc1`='눈사태 무덤은 겨울도끼 요새의 동쪽, 투쟁의 벌판 언덕 꼭대기에 있습니다.$B$B현재 얼라이언스가 점령하고 있습니다.', `MaleText_loc4`='雪落墓地就在冰斧要塞以东的征战平原的高山顶部。$B$B联盟控制着这片土地。', `MaleText_loc5`='落雪墓地就在冰斧要塞以東的征戰平原的高山頂部。$B$B聯盟控制著這片土地。', `MaleText_loc7`='El Cementerio Avalancha se encuentra en la cumbre de una colina en la Tierra de Disputa, al este del Fuerte Hacha Invernal.$B$BActualmente pertenece a la Alianza.' WHERE `ID`=8821;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='눈사태 무덤은 겨울도끼 요새 동쪽, 투쟁의 벌판 언덕 꼭대기에 있습니다.$B$B현재 호드가 점령하고 있습니다.', `MaleText_loc4`='雪落墓地就在冰斧要塞以东的征战平原的高山顶部。$B$B部落控制着这片土地。', `MaleText_loc5`='落雪墓地就在冰斧要塞以東的征戰平原的高山頂部。$B$B部落控制著這片土地。', `MaleText_loc7`='El Cementerio Avalancha se encuentra en la cumbre de una colina en la Tierra de Disputa, al este del Fuerte Hacha Invernal.$B$BActualmente pertenece a la Horda.' WHERE `ID`=8823;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서리늑대 무덤은 어느 진영에서 점령하고 있습니까?', `MaleText_loc4`='谁控制着霜狼墓地？', `MaleText_loc5`='誰控制著霜狼墓地?', `MaleText_loc7`='¿Quién controla el Cementerio Lobo Gélido?', `FemaleText_loc1`='서리늑대 무덤은 어느 진영에서 점령하고 있습니까?', `FemaleText_loc4`='谁控制着霜狼墓地？', `FemaleText_loc5`='誰控制著霜狼墓地?', `FemaleText_loc7`='¿Quién controla el Cementerio Lobo Gélido?' WHERE `ID`=8824;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서리늑대 무덤은 서리늑대 마을에서 북쪽으로 그리 멀리 떨어지지 않은 길가에 있습니다.$B$B현재 얼라이언스가 점령하고 있습니다.', `MaleText_loc4`='霜狼墓地就在离霜狼村北面不远的地方。$B$B联盟控制着这片土地。', `MaleText_loc5`='霜狼墓地就在離霜狼村北面不遠的地方。$B$B聯盟控制著這片土地。', `MaleText_loc7`='El Cementerio Lobo Gélido está justo al lado del camino, cerca de la Aldea Lobo Gélido.$B$BActualmente pertenece a la Alianza.' WHERE `ID`=8825;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서리늑대 무덤은 서리늑대 마을에서 북쪽으로 그리 멀리 떨어지지 않은 길가에 있습니다.$B$B현재 호드가 점령하고 있습니다.', `MaleText_loc4`='霜狼墓地就在离霜狼村北面不远的地方。$B$B部落控制着这片土地。', `MaleText_loc5`='霜狼墓地就在離霜狼村北面不遠的地方。$B$B部落控制著這片土地。', `MaleText_loc7`='El Cementerio Lobo Gélido está justo al lado del camino, cerca de la Aldea Lobo Gélido.$B$BActualmente pertenece a la Horda.' WHERE `ID`=8826;
