UPDATE `locales_broadcast_text` SET `MaleText_loc1`='귀여운 우리 친구! 즐거운 겨울맞이 되세요... 착한 와우저 어린이들이라면 굴뚝나무 목장조합에서 특별한 물품을 할인된 가격에 구입할 수 있어요. 음... 생각만 해도 군침 도는 음식들이 다양하게 준비되어 있답니다.', `MaleText_loc4`='祝你过一个神奇的冬幕节，小$G伙子:姑娘;！好孩子在任何烟林牧场小卖部都有特别优惠的哦。', `MaleText_loc5`='一個神奇的冬幕節...啊...小$G男孩:女孩;。好孩子在燻木牧場當地的任何小販部都有特別的，嗯，折扣。真棒。', `MaleText_loc7`='Feliz Festival de Invierno... mmm... $gpequeño: pequeña;. Los niños buenos tienen un... ehm... descuento especial en cualquier tienda de Pastos de Bosquehumeante. Mmm.' WHERE `ID`=8834;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번 명절이 지나가면 분명 이 겨울 할아버지는 다음 해를 위해 새 술을 빚을 준비를 할 거예요. 그러니 여기 이 가방 안에 있는 겨울맞이용 술은 한 방울도 남김없이 모조리 마셔 버려야겠어요.', `MaleText_loc4`='这轮结束后冬天爷爷会做什么呢，我有一个很好的主意。我在包里有一瓶冬幕啤酒，而且我想喝光它。', `MaleText_loc5`='冬天爺爺下班之後會做什麼呢，我有一個很好的主意。我在包包裡有一瓶冬幕啤酒，而且我想喝光它。', `MaleText_loc7`='Tengo bastante claro lo que el viejo Gran Padre Invierno va a hacer cuando se acabe este turno. Tengo una botella de licor de Festival de Invierno en mi bolsa, y no va a quedar ni una gota.' WHERE `ID`=8835;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니... 아무리 폭신해 보여도 그렇지, 제 무릎 위에 앉으면 안 되지요.', `MaleText_loc4`='不……你不能坐在我的膝盖上。', `MaleText_loc5`='不...你不能坐在我的膝蓋上。', `MaleText_loc7`='No... No te puedes sentar encima de mí.' WHERE `ID`=8836;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래요! 이번 겨울맞이 축제에는 겨울 할아버지에게 어떤 선물을 받고 싶은지 한번 말해 봐요.$B$B호호호! 어서...', `MaleText_loc4`='是的，当然，去告诉冬天爷爷你都想从这个冬幕中得到什么。$B$B赶紧些。', `MaleText_loc5`='是的，當然，去告訴冬天爺爺你這個冬幕節想得到什麼。$B$B趕緊去。', `MaleText_loc7`='Sí, claro, adelante, dile al viejo Gran Padre Invierno qué te gustaría recibir este Festival de Invierno.$B$B¡Jo, jo, jo, date prisa!' WHERE `ID`=8837;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰파이크 부족은 아무에게도 굴복하지 않소. 특히 호드에게는!', `MaleText_loc4`='雷矛一族不会对任何人俯首称臣的，特别是部落！', `MaleText_loc5`='雷矛一族不會對任何人俯首稱臣的，特別是部落!', `MaleText_loc7`='¡El clan Pico Tormenta no se somete a nadie, especialmente a la Horda!' WHERE `ID`=8838;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주먹이 솜방망이로군! 가서 토끼 잡는 연습이나 좀 더 한 다음에 오시오.', `MaleText_loc4`='你的攻击太微弱了！去找些兔子练习一下，当你强壮些后再回来找我。', `MaleText_loc5`='你的攻擊太微弱了!去找些兔子練習一下，當你強壯些後再回來找我。', `MaleText_loc7`='¡Tus ataques son débiles! Vete a practicar con algunos conejos y vuelve cuando te hayas fortalecido.' WHERE `ID`=8839;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기껏 이 정도란 말인가?', `MaleText_loc4`='那就是你的最好表现吗？', `MaleText_loc5`='那就是你的最好表現嗎?', `MaleText_loc7`='¿Es eso lo mejor que puedes hacer?' WHERE `ID`=8840;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 같은 오합지졸로는 나를 쓰러뜨릴 수 없다!', `MaleText_loc4`='你这样的乌合之众是不可能打倒我的！', `MaleText_loc5`='你這樣的烏合之眾是不可能打倒我的!', `MaleText_loc7`='¡Va a ser necesario algo más que tu chusma para acabar conmigo!' WHERE `ID`=8841;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 절대 흔들리지 않을 것이오!', `MaleText_loc4`='我们一定会完成使命的！', `MaleText_loc5`='我們一定會完成使命的!', `MaleText_loc7`='¡Nadie nos apartará de nuestra misión!' WHERE `ID`=8842;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 얼라이언스가 승리할 거요!', `MaleText_loc4`='联盟会胜利的！', `MaleText_loc5`='聯盟會勝利的!', `MaleText_loc7`='¡Somos la Alianza y venceremos!' WHERE `ID`=8843;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희는 절대로 서리늑대 부족을 물리칠 수 없다!', `MaleText_loc4`='你不能击败霜狼部落！', `MaleText_loc5`='你不能擊敗霜狼氏族!', `MaleText_loc7`='¡No podéis vencer al clan Lobo Gélido!' WHERE `ID`=8844;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='약해빠진 정신력에 주먹은 그보다 더 약하구나!', `MaleText_loc4`='你的精神很虚弱，你的打击更弱！', `MaleText_loc5`='你的精神很虛弱，你的打擊更弱!', `MaleText_loc7`='Sus espíritus son débiles y sus arcos, más débiles aún.' WHERE `ID`=8845;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 추워서 공격도 제대로 못하는군!', `MaleText_loc4`='我想你的进攻因为寒冷减弱了！', `MaleText_loc5`='我想你的進攻因為寒冷減弱了!', `MaleText_loc7`='Creo que el frío ralentiza sus ataques.' WHERE `ID`=8846;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 발로 알터랙 계곡을 떠나지 않겠다면 우리 서리늑대 부족이 그렇게 해주겠다!', `MaleText_loc4`='如果你不自动离开奥特兰克山谷，霜狼会强迫你离开的！', `MaleText_loc5`='如果你不自動離開奧特蘭克山谷，霜狼會強迫你離開的!', `MaleText_loc7`='Si no se van del Valle de Alterac por su propio pie, ¡los Lobo Gélido se encargarán de ello!' WHERE `ID`=8847;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희는 막강한 우리 호드에게 상대도 안 돼!', `MaleText_loc4`='你不是部落的力量的对手！', `MaleText_loc5`='你不是部落的力量的對手!', `MaleText_loc7`='¡No sois rival para la fuerza de la Horda!' WHERE `ID`=8848;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 황천에서 네 선조를 만나게 될 줄 알아라!', `MaleText_loc4`='你会在今天见到你的祖先的！', `MaleText_loc5`='你會在今天見到你的祖先的!', `MaleText_loc7`='¡Hoy, conocerán a sus ancestros!' WHERE `ID`=8849;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멀리서부터 우레와 같은 %s의 날갯짓 소리가 들립니다.', `MaleText_loc4`='%s扇动翅膀的声音从远处传来。', `MaleText_loc5`='遠處傳來%s的翅膀振動聲。', `MaleText_loc7`='Las alas de %s resuenan cual trueno en la distancia.' WHERE `ID`=8850;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛나는 조각에 대해 얘기해 주십시오.', `MaleText_loc4`='告诉我关于发光的碎片的事情。', `MaleText_loc5`='告訴我關於發光的裂片的事情。', `MaleText_loc7`='Háblame del fragmento resplandeciente.', `FemaleText_loc1`='빛나는 조각에 대해 얘기해 주십시오.', `FemaleText_loc4`='告诉我关于发光的碎片的事情。', `FemaleText_loc5`='告訴我關於發光的裂片的事情。', `FemaleText_loc7`='Háblame del fragmento resplandeciente.' WHERE `ID`=8851;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 거야! 내 거! 내 거! 여기서는 기즐록이 두목이다! 절대로 내 존재를 알리지는 못해!', `MaleText_loc4`='我的！我的！我的！吉兹洛克是这片领域的统治者！你绝对不能泄漏我的行踪！', `MaleText_loc5`='我的!我的!我的!吉茲洛克是這片領域的統治者!你絕對不能洩漏我的行蹤!', `MaleText_loc7`='¡Mío! ¡Mío! ¡Mío! ¡Gizlock es quien gobierna este lugar! ¡Jamás revelarás mi presencia!' WHERE `ID`=8852;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지난 번 호드의 공격으로 던 발다르가 큰 타격을 입었소! 재건과 수리를 위해서는 더 많은 보급품이 필요하오!', `MaleText_loc4`='丹巴达尔在部落的最后一次进攻中给了我们狠狠一击！我们需要物资重建基地！', `MaleText_loc5`='丹巴達爾在部落的最後一次進攻中給了我們狠狠一擊!我們需要物資重建基地!', `MaleText_loc7`='Dun Baldar sufrió muchos daños en el último ataque de la Horda. Necesitamos más suministros para poder reconstruir y hacer reparaciones.' WHERE `ID`=8853;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='군대는 물자의 힘으로 움직인다고 하는데, 정말 맞는 말이오. 어떤 공격이든 성공하려면 반드시 병사들을 잘 먹이고 보급품을 충분히 지급해야 하오.', `MaleText_loc4`='他们说食物是行军的保障，这是真的。要想成功应对敌人的攻击，军队必须拥有足够的粮草和装备供应。', `MaleText_loc5`='他們說食物是行軍的保障，這是真的。要想成功應對敵人的攻擊，軍隊必須擁有足夠的糧草和裝備供應。', `MaleText_loc7`='Dicen que un ejército solo se mueve con el estómago lleno, y es cierto. Para que un ataque tenga éxito, tus tropas deben tener comida y suministros.' WHERE `ID`=8854;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 이들은 군대의 성공은 힘과 용기가 좌우한다고들 하는데, 그 말도 맞소! 하지만 군대를 제대로 유지하기 위해서는 보급품이 반드시 필요하지. 그런 보급품을 공급하는 게 바로 내 일이오.', `MaleText_loc4`='有人说军队的成功靠的是力量和勇气。这是真的！但是军队同样需要充足的物资来维系士气，我的工作便是确保他们的物资需求。', `MaleText_loc5`='有人說軍隊的成功靠的是力量和勇氣。這是真的!但是軍隊同樣需要充足的物資來維繫士氣，我的工作便是確保他們的物資需求。', `MaleText_loc7`='Hay quienes dicen que el éxito de un ejército depende de su fuerza y valentía. ¡Y qué cierto es! Pero un ejército también necesita suministros para estar en buena forma y mi trabajo es asegurarme de que tienen lo que necesitan.' WHERE `ID`=8855;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서리늑대 요새가 파괴됐소! 재건하고 수리하려면 보급품이 있어야 하오!', `MaleText_loc4`='霜狼要塞被摧毁了！我们需要物资重建基地！', `MaleText_loc5`='霜狼要塞被摧毀了!我們需要物資重建基地!', `MaleText_loc7`='¡Han arrasado el Bastión Lobo Gélido! Necesitamos suministros para reparar y reconstruir.' WHERE `ID`=8857;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 순종하는 의미로 낑낑댑니다.', `MaleText_loc4`='%s温顺地低声呜咽着。', `MaleText_loc5`='%s溫順地低聲叫著。', `MaleText_loc7`='%s gimotea obediente.' WHERE `ID`=8858;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어서 오십시오. 호드의 대의를 따르러 오셨나요?', `FemaleText_loc4`='士兵，你好。你是来帮我的吗？', `FemaleText_loc5`='士兵，你好。你是來幫我的嗎?', `FemaleText_loc7`='Saludos, Soldado. ¿Estás aquí para ayudar a la causa?' WHERE `ID`=8859;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘하셨습니다. 조금만 더 하면 이 우리에 호드의 기병대가 전투에 타고 나갈 늑대가 넘쳐날 것입니다!', `FemaleText_loc4`='士兵，做得好。我们的马厩将塞满骑兵们的战斗坐骑！', `FemaleText_loc5`='幹得好，士兵。我們的獸欄將塞滿騎兵們的戰鬥坐騎!', `FemaleText_loc7`='Muy bien, Soldado. Unas cuántas más y nuestros establos estarán llenos de monturas para que la caballería entre en combate.' WHERE `ID`=8860;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 늑대를 맡아주시면 감사하겠습니다.', `MaleText_loc4`='谢谢你，兽栏管理员。请牵走动物吧。', `MaleText_loc5`='謝謝你，獸欄管理員。請牽走動物吧。', `MaleText_loc7`='Gracias, maestro de establos. Por favor, coge al animal.', `FemaleText_loc1`='이 늑대를 맡아주시면 감사하겠습니다.', `FemaleText_loc4`='谢谢你，兽栏管理员。请牵走动物吧。', `FemaleText_loc5`='謝謝你，獸欄管理員。請牽走動物吧。', `FemaleText_loc7`='Gracias, maestro de establos. Por favor, coge al animal.' WHERE `ID`=8861;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오게. 새 무기 휘두르는 걸 배우려는 거면 아주 제대로 찾아온 거라네.', `MaleText_loc4`='嗨。你到这儿来学习如何使用新武器算是来对地方啦。', `MaleText_loc5`='嗨。你到這兒來學習如何使用新武器算是來對地方啦。', `MaleText_loc7`='Eh, colega. Has venio al sitio perfecto pa aprender a empuñar una nueva arma.' WHERE `ID`=8862;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, $n! 마침 자네 같은 이를 찾고 있던 중이었네! 이제 보급품이 충분히 모여서 호드에 맞설 지상 공격 부대를 출격시킬 수 있어! 투쟁의 벌판에서 테라베인 야전사령관이 명령서를 기다리고 있을 걸세.$B$B자네는 수 차례 자기 자신의 가치를 몸소 입증해 보인 노련한 용사이니 테라베인에게 명령서를 전달해 주지 않겠나?', `MaleText_loc4`='啊，$n！你就是我希望见到的人！我们已经拥有足够的军备，可以对部落发动地面攻击！指挥官特拉瓦雷正在征战平原等待指令……$B$B你曾多次证明自己是一名勇敢且经验丰富的士兵。你想为特拉瓦雷传达指令吗？', `MaleText_loc5`='啊，$n!你就是我希望見到的人!我們已經擁有足夠的軍備，可以對部落發動地面攻擊!戰場元帥特拉瓦雷正在征戰平原等待指令...$b$b你曾多次證明自己是一名勇敢且經驗豐富的士兵。你想為特拉瓦雷傳達指令嗎?', `MaleText_loc7`='¡Ah, $n! ¡Eres justo la persona que esperaba ver! Tenemos suficientes suministros para lanzar un asalto terrestre contra la Horda. El Mariscal de campo Teravaine está esperando órdenes en la Tierra de Disputa...$B$BHas demostrado ser un veterano con mucho coraje. ¿Quieres entregar las órdenes a Teravaine?' WHERE `ID`=8863;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='친구여, 어떤 무기를 배우고 싶나?', `MaleText_loc4`='你对哪种武器感兴趣？', `MaleText_loc5`='你想要學些什麼，嗯?', `MaleText_loc7`='¿Qué quieres aprender, mon?' WHERE `ID`=8864;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n! 뭐 하는 건가? 여기서 나와 잡담이나 하고 있을 시간이 있나? 어서 나가서 호드와 싸워야지!$B$B투쟁의 벌판에 있는 우리 야전사령관 중 하나에게 공격명령서를 전달해야 하는데, 믿을 만한 이가 필요하거든.$B$B스톰파이크 경비대 내에서 자네의 지위가 좀 더 높다면 믿을 수 있었을 텐데...', `MaleText_loc4`='$n！你在做什么？你应该出去为了部落而战！$B$B我需要一名值得信赖的人去征战平原，去找指挥官传达攻击命令。$B$B要是你的声望再高一点，我也许能派你去……', `MaleText_loc5`='$n!你在做什麼?你應該出去為了部落而戰!$B$B我需要一名值得信賴的人去征戰平原，去找戰場元帥傳達攻擊命令。$B$B要是你的聲望再高一點，我也許能派你去...', `MaleText_loc7`='¡$n! ¿Qué haces hablando conmigo? ¡Deberías estar combatiendo contra la Horda!$B$BTengo órdenes de asalto de uno de nuestros Mariscales de campo en la Tierra de Disputa, pero necesito a alguien digno de confianza.$B$BQuizás, si la milicia Pico Tormenta te tuviera te tuvieran en más alta consideración, podría contar contigo...' WHERE `ID`=8865;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무기 사용하는 법을 내 기꺼이 가르쳐 주겠소. 내가 통달한 꼭 그만큼 당신도 능숙하게 무기 다루는 법을 배우게 될 거요.', `MaleText_loc4`='如果你有能力学习的话，我是很荣幸教你如何使用武器的。', `MaleText_loc5`='如果你有能力學習的話，我是很榮幸教你如何使用武器的。', `MaleText_loc7`='Me encantaría instruirte en el uso de las armas que domino, siempre y cuando tengas la facultad de aprender.' WHERE `ID`=8866;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n! 보급품이 점점 줄어들고 있어서 더 모으기 전에는 투쟁의 벌판에서 대규모 지상 공격을 펼칠 수가 없네!$B$B우리 병참장교와 얘기해 보게나. 우리 부대에 보급품을 보충하기 위해 자네가 할 수 있는 일이 뭔지 말해 줄 걸세.', `MaleText_loc4`='$n！我们的军备正在减少，在我们获得更多的军备之前是无法发动对征战平原的地面攻击的！$B$B跟雷矛军需官谈谈，他会告诉你如何增加我们的军备。', `MaleText_loc5`='$n!我們的軍備正在減少，在我們獲得更多的軍備之前是無法發動對征戰平原的地面攻擊的!$B$B跟雷矛軍需官談談。他會告訴你如何增加我們的軍備。', `MaleText_loc7`='¡$n! Nuestros suministros cada vez son más limitados y, hasta que no consigamos más, no podremos lanzar asaltos terrestres a gran escala en la Tierra de Disputa.$B$BHabla con el Intendente Pico Tormenta. Te dirá lo que puedes hacer para reabastecer a nuestras tropas de asalto.' WHERE `ID`=8867;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 배우기를 원한다면 누가 그대를 도와줄지 기꺼이 알려드리겠소. 그래, 어떤 무기가 그대의 관심을 끌었소?', `MaleText_loc4`='如果你想要进行更多训练，我可以告诉你该去哪里。你想要学习哪种武器呢？', `MaleText_loc5`='如果你需要更多訓練，我很樂意告訴你誰可以幫助你。是什麼樣的武器吸引你的目光呢?', `MaleText_loc7`='Si requieres más formación, será un placer indicarte dónde puedes obtener ayuda. ¿Qué tipo de arma te ha llamado la atención?' WHERE `ID`=8868;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰파이크에 죽음을!', `MaleText_loc4`='卡尔·雷矛，死吧！', `MaleText_loc5`='雷矛氏族，去死吧!', `MaleText_loc7`='¡Muerte a Pico Tormenta!' WHERE `ID`=8869;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기병대에 진격을 명하십시오!', `MaleText_loc4`='骑兵们，冲锋！', `MaleText_loc5`='騎兵們，衝鋒!', `MaleText_loc7`='¡Soltad la caballería!', `FemaleText_loc1`='기병대에 진격을 명하십시오!', `FemaleText_loc4`='骑兵们，冲锋！', `FemaleText_loc5`='騎兵們，衝鋒!', `FemaleText_loc7`='¡Soltad la caballería!' WHERE `ID`=8870;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훌륭했다! 이제 기병대는 귀관의 명령에 따라 출격할 준비가 되었다.', `MaleText_loc4`='士兵，你做得棒极了！骑兵们已整装待发，就听你的指令了。', `MaleText_loc5`='士兵，你做得棒極了!騎兵們已整裝待發，就聽你的指令了。', `MaleText_loc7`='Has hecho un trabajo excepcional, Soldado. La caballería está lista para marchar cuando des la orden.' WHERE `ID`=8871;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나의 상관이 보내올 명령서를 기다리는 중일세.', `MaleText_loc4`='等待上级命令。', `MaleText_loc5`='等待上級命令。', `MaleText_loc7`='Esperando órdenes de mis superiores.' WHERE `ID`=8872;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새 무기 사용법을 배우러 온 거겠지? 내가 많이 바쁘니까 빨리 말해 보라고!', `MaleText_loc4`='我猜想你到这儿来是训练如何使用新武器的？快点，我很忙的！', `MaleText_loc5`='我猜想你到這兒來是訓練如何使用新武器的?快點，我很忙的!', `MaleText_loc7`='Supongo que estás aquí para aprender a utilizar una nueva arma. Rápido, estoy muy ocupado.' WHERE `ID`=8873;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 무기를 배우고 싶은지 알려 주면 어디로 가야 할지 가르쳐 주지.', `MaleText_loc4`='如果你想要进行更多训练，我可以告诉你该去哪里。你想要学习哪种武器呢？', `MaleText_loc5`='只要你告訴我你的興趣，我就會告訴你該怎麼做。', `MaleText_loc7`='Te diré dónde debes ir siempre y cuando me digas qué te interesa.' WHERE `ID`=8874;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 야수를 맡기고 싶습니다.', `MaleText_loc4`='兽栏管理员，我想寄放我的宠物。', `MaleText_loc5`='獸欄管理員，我想寄放我的寵物。', `MaleText_loc7`='Quiero guardar a mi mascota en el establo, maestro de establos.', `FemaleText_loc1`='제 야수를 맡기고 싶습니다.', `FemaleText_loc4`='兽栏管理员，我想寄放我的宠物。', `FemaleText_loc5`='獸欄管理員，我想寄放我的寵物。', `FemaleText_loc7`='Quiero guardar a mi mascota en el establo, maestro de establos.' WHERE `ID`=8875;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 자네처럼 노련한 이를 전장에서 보게 되다니 반갑네! 유감스럽게도 현재 우리는 보급품이 너무 적어서 호드에 대한 대규모 지상 공격을 펼칠 수 없는 상태라네.$B$B우리 병참장교와 얘기해 보게. 보급품 관련 임무를 줄 걸세.', `MaleText_loc4`='$n，在战场上看到你这样经验丰富的家伙真好！很抱歉，我们军队的物资过低，无法发动对部落的大规模地面攻击。$B$B跟我们的军需官谈谈，他会给你供给任务的。', `MaleText_loc5`='$n，在戰場上看到你這樣經驗豐富的傢伙真好!很抱歉，我們軍隊的物資過低，無法發動對部落的大規模地面攻擊。$B$B跟我們的軍需官談談，他會給你供給任務的。', `MaleText_loc7`='¡$n, me alegro de ver a veteranos como tú en el campo! Siento informarte de que nuestros suministros son demasiado escasos para lanzar asaltos terrestres a gran escala contra la Horda.$B$BHabla con nuestro intendente; tiene misiones de suministros disponibles.' WHERE `ID`=8876;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무기를 들고 싸우는 전투 훈련을 받으려고 왔습니까?', `MaleText_loc4`='你是来学习如何作战吗？', `MaleText_loc5`='你是來學習如何作戰嗎?', `MaleText_loc7`='¿Has venido a aprender a combatir con armas?' WHERE `ID`=8877;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 무기에 특별히 관심이 있으신가요?', `MaleText_loc4`='你对哪种武器感兴趣？', `MaleText_loc5`='你偏好那種武器?', `MaleText_loc7`='¿Qué arma te interesa en particular?' WHERE `ID`=8878;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='싸울 때의 내 우아한 모습은 가르쳐 줄 수 있는 게 아니지만 여러 가지 무기를 다루는 법은 가르쳐 줄 수 있어요.', `FemaleText_loc4`='我可没法教你战斗时如何保持优雅姿态，我只能教你如何使用武器。', `FemaleText_loc5`='我可沒法教你戰鬥時如何保持優雅姿態，我只能教你如何使用武器。', `FemaleText_loc7`='No puedo enseñarte mi gracia a la hora de luchar, pero sí a utilizar algunas armas.' WHERE `ID`=8879;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='원한다면 다른 무기 전문가에게 가는 길을 안내해 드리겠습니다. 어떤 무기를 배우고 싶으신가요?', `FemaleText_loc4`='我可以告诉你该找谁进行训练。你对哪类武器感兴趣？', `FemaleText_loc5`='如果你想，我可以介紹其他武器大師給你。你想學些什麼?', `FemaleText_loc7`='Puedo indicarte cómo encontrar otro maestro de armas, si lo prefieres. ¿Qué armas te interesan?' WHERE `ID`=8880;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러니까, 무기 다루는 법을 배우고 싶단 말이지? 거기 그렇게 바보같이 서 있지만 말고 대답 좀 크게 해 보라고, 젊은이!', `MaleText_loc4`='你想学习如何使用武器，是吗？嗨，$g小伙子:姑娘;，别在站在那儿发呆啦，大声说吧！', `MaleText_loc5`='你想學習如何使用武器，是嗎?嗨，$g小夥子:姑娘;，別在站在那兒發呆啦，大聲說吧!', `MaleText_loc7`='¿Quieres aprender a usar un arma, eh? Bueno, no te quedes ahí con cara de idiota, habla, $gchico:chica;.' WHERE `ID`=8881;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 무기가 배우고 싶어서 왔나요?', `MaleText_loc4`='你想要学习哪种武器技能？', `MaleText_loc5`='你想要學習什麼武器技能?', `MaleText_loc7`='¿Qué arma buscas aprender?' WHERE `ID`=8882;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요! 새 무기를 제대로 사용하는 기술을 배우러 오셨나요?', `FemaleText_loc4`='嗨！你是来这儿学习新武器的吗？', `FemaleText_loc5`='嗨!你是來這兒學習新武器的嗎?', `FemaleText_loc7`='¡Eh, hola! ¿Has venido a aprender cómo usar una nueva arma?' WHERE `ID`=8883;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저한테 훈련을 받고 싶지는 않나 보죠? 그래, 어떤 다른 무기에 눈길이 가던가요?', `FemaleText_loc4`='你想要学习哪种武器？', `FemaleText_loc5`='唔，不想找我一起訓練?是什麼武器吸引你的目光?', `FemaleText_loc7`='Ah, ¿no quieres entrenar conmigo? ¿Qué otra arma te llama la atención?' WHERE `ID`=8884;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지원 요청! 늑대가 더 필요하다! 이쪽 우리로 와서 나를 도우라!', `FemaleText_loc4`='我们需要更多的狼！去马厩需求帮助吧！', `FemaleText_loc5`='我們需要更多的狼!去獸欄幫忙吧!', `FemaleText_loc7`='¡Necesitamos más lobos! ¡Ven a los establos y echa una mano!' WHERE `ID`=8885;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='호드의 일원이여, 수고했노라! 우리에 서리늑대가 충분히 모였으니 모든 늑대기병에게 탈것을 제공할 수 있겠군!', `FemaleText_loc4`='做得好，部落！马厩中有足够的霜狼可供我们的狼骑兵乘坐！', `FemaleText_loc5`='做得好，部落!獸欄中有足夠的霜狼可供我們的狼騎兵乘坐!', `FemaleText_loc7`='¡Bien hecho, Horda! Tenemos los suficientes Lobo Gélido en nuestros establos para proporcionar monturas a todos nuestros Caballeros Lobo.' WHERE `ID`=8886;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='늑대기병들이여, 서리비수 고개로 진격!', `MaleText_loc4`='狼骑兵们，去霜刀小径！', `MaleText_loc5`='狼騎兵們，去霜刀小徑!', `MaleText_loc7`='¡Caballeros Lobo, al Paso de la Daga Escarcha!' WHERE `ID`=8887;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우워어어어어!', `MaleText_loc4`='啊~~~！', `MaleText_loc5`='啊～～～～～～!', `MaleText_loc7`='¡RARRRRRR!' WHERE `ID`=8888;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='출격하기에 가장 알맞은 때가 되면 내게 다시 알려 주게. 자네는 최전선에서 기병대의 눈과 귀 역할을 해줘야 하네!', `MaleText_loc4`='告诉我乘坐什么坐骑最好。你就是我们在前线的耳目。', `MaleText_loc5`='告訴我乘坐什麼坐騎最好。你就是我們在前線的耳目。', `MaleText_loc7`='Dime cuándo es mejor montar. Tendrás que ser nuestros ojos y nuestros oídos en el frente de batalla.' WHERE `ID`=8889;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드의 형제들이여, 때가 왔노라. 결코 적이 서리비수 고개를 통과하도록 놔둬서는 안 된다. 우리 중 일부는 죽음을 피할 수 없겠지만 이 영광스러운 임무로부터 도망치는 것은 죽음보다 부끄러운 일이다! 돌격 앞으로! 호드를 위하여!', `MaleText_loc4`='兄弟们，是时候了。我们必须阻止敌人通过霜刀小径。我们中必然会有人在战斗中牺牲，但是你们有谁想要逃避这个职责吗？逃避这个荣耀的职责？前进吧！为了部落而战！', `MaleText_loc5`='兄弟們，是時候啦。我們必須阻止敵人通過霜刀小徑。我們中必然會有人在戰鬥中犧牲，但是你們有誰想要逃避這個職責嗎?逃避這個榮耀的職責?前進吧!為了部落而戰!', `MaleText_loc7`='Ha llegado la hora, hermanos. No podemos permitir que el enemigo atraviese el Paso de la Daga Escarcha. Algunos de nosotros moriremos pero, ¿hay alguno de ustedes que no quiera cumplir con este deber? ¿Este honor? ¡Adelante! ¡Por la Horda!' WHERE `ID`=8890;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장님의 이름으로!', `MaleText_loc4`='为了酋长而战！', `MaleText_loc5`='為了大酋長而戰!', `MaleText_loc7`='¡Por el Jefe de Guerra!', `FemaleText_loc1`='대족장님의 이름으로!', `FemaleText_loc4`='为了酋长而战！', `FemaleText_loc5`='為了大酋長而戰!', `FemaleText_loc7`='¡Por el Jefe de Guerra!' WHERE `ID`=8891;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미올로 씨, 갑옷 제작자로서 다시 한번 망치를 들고자 합니다! 갑옷 제작의 도를 가르쳐 주십시오.', `MaleText_loc4`='米洛尔，我曾经是一名护甲铸造师，我想重抄旧业！教教我吧。', `MaleText_loc5`='米洛爾，我曾經是一名護甲鍛造師，我想重操舊業!教教我吧。', `MaleText_loc7`='Myolor, hace tiempo fui forjador de armaduras, y me gustaría volver a coger el martillo. Enséñame a forjar armaduras.', `FemaleText_loc1`='미올로 씨, 갑옷 제작자로서 다시 한번 망치를 들고자 합니다! 갑옷 제작의 도를 가르쳐 주십시오.', `FemaleText_loc4`='米洛尔，我曾经是一名护甲铸造师，我想重抄旧业！教教我吧。', `FemaleText_loc5`='米洛爾，我曾經是一名護甲鍛造師，我想重操舊業!教教我吧。', `FemaleText_loc7`='Myolor, hace tiempo fui forjadora de armaduras, y me gustaría volver a coger el martillo. Enséñame a forjar armaduras.' WHERE `ID`=8892;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미올로 씨, 무기 제작자로서 다시 한번 망치를 들고자 합니다! 무기 제작의 도를 가르쳐 주십시오.', `MaleText_loc4`='米洛尔，我曾经是一名武器铸造师，我想重抄旧业！教教我吧。', `MaleText_loc5`='米洛爾，我曾經是一名武器鍛造師，我想重操舊業!教教我吧。', `MaleText_loc7`='Myolor, hace tiempo fui forjador de armas, y me gustaría volver a coger el martillo. Enséñame a forjar armas.', `FemaleText_loc1`='미올로 씨, 무기 제작자로서 다시 한번 망치를 들고자 합니다! 무기 제작의 도를 가르쳐 주십시오.', `FemaleText_loc4`='米洛尔，我曾经是一名武器铸造师，我想重抄旧业！教教我吧。', `FemaleText_loc5`='米洛爾，我曾經是一名武器鍛造師，我想重操舊業!教教我吧。', `FemaleText_loc7`='Myolor, hace tiempo fui forjadora de armas, y me gustaría volver a coger el martillo. Enséñame a forjar armas.' WHERE `ID`=8893;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크라토크 씨. 한때 갑옷제작자였던 제가 다시 한번 망치를 집어 들고자 합니다! 갑옷제작의 도를 가르쳐 주십시오.', `MaleText_loc4`='克拉索克，我曾经是一名护甲铸造师，我想重抄旧业！教教我吧。', `MaleText_loc5`='克拉索克，我曾經是一名護甲鍛造師，我想重操舊業!教教我吧。', `MaleText_loc7`='Krathok, hace tiempo fui forjador de armaduras, y me gustaría volver a coger el martillo. Enséñame a forjar armaduras.', `FemaleText_loc1`='크라토크 씨. 한때 갑옷제작자였던 제가 다시 한번 망치를 집어 들고자 합니다! 갑옷제작의 도를 가르쳐 주십시오.', `FemaleText_loc4`='克拉索克，我曾经是一名护甲铸造师，我想重抄旧业！教教我吧。', `FemaleText_loc5`='克拉索克，我曾經是一名護甲鍛造師，我想重操舊業!教教我吧。', `FemaleText_loc7`='Krathok, hace tiempo fui forjadora de armaduras, y me gustaría volver a coger el martillo. Enséñame a forjar armaduras.' WHERE `ID`=8894;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크라토크 씨. 한때 무기제작자였던 제가 다시 한번 망치를 집어 들고자 합니다! 무기제작의 도를 가르쳐 주십시오.', `MaleText_loc4`='克拉索克，我曾经是一名武器铸造师，我想重抄旧业！教教我吧。', `MaleText_loc5`='克拉索克，我曾經是一名武器鍛造師，我想重操舊業!教教我吧。', `MaleText_loc7`='Krathok, hace tiempo fui forjador de armas, y me gustaría volver a coger el martillo. Enséñame a forjar armas.', `FemaleText_loc1`='크라토크 씨. 한때 무기제작자였던 제가 다시 한번 망치를 집어 들고자 합니다! 무기제작의 도를 가르쳐 주십시오.', `FemaleText_loc4`='克拉索克，我曾经是一名武器铸造师，我想重抄旧业！教教我吧。', `FemaleText_loc5`='克拉索克，我曾經是一名武器鍛造師，我想重操舊業!教教我吧。', `FemaleText_loc7`='Krathok, hace tiempo fui forjadora de armas, y me gustaría volver a coger el martillo. Enséñame a forjar armas.' WHERE `ID`=8895;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서리비수 고개를 순찰하라. 그 누구도 통과하지 못하도록! 명예롭게 싸우다 죽어라!', `MaleText_loc4`='去霜刀小径巡逻。别让任何人通过那儿！为荣誉而战……', `MaleText_loc5`='去霜刀小徑巡邏。別讓任何人通過那兒!為榮譽而戰...', `MaleText_loc7`='Patrulla del Paso de la Daga Escarcha. ¡No permitáis que pase nadie! Morid con honor...' WHERE `ID`=8896;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='콜카르 침입자들이 퇴각하고 있다!', `MaleText_loc4`='科卡尔入侵者们撤退了！', `MaleText_loc5`='科卡爾入侵者們撤退了!', `MaleText_loc7`='¡Los invasores Kolkar se retiran!' WHERE `ID`=8897;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서리늑대 가죽이 충분히 모였소. 곧 기병대도 출격 준비를 끝낼 것이오! 충분한 수의 산양을 우리에 들여보내면 다시 얘기합시다.', `MaleText_loc4`='我们已经收集到足够的狼皮。很快，骑兵们就可以上马出发啦！当我们有足够的山羊时再来跟我谈谈。', `MaleText_loc5`='我們已經收集到足夠的狼皮。很快，騎兵們就可以上馬出發啦!當我們有足夠的山羊時再來跟我談談。', `MaleText_loc7`='Hemos recogido suficientes pellejos de lobo. Pronto, la caballería estará lista para marchar. Vuelve a hablar conmigo cuando tengamos suficientes carneros en el establo.' WHERE `ID`=8898;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다시 우리가 가득 찼어요! 곧 우리 기병대가 출격할 거예요!', `FemaleText_loc4`='马厩又满啦！我们的骑兵很快就可以乘坐啦！', `FemaleText_loc5`='獸欄又滿啦!我們的騎兵很快就可以乘坐啦!', `FemaleText_loc7`='¡Los establos están llenos de nuevo! Nuestra caballería está lista.' WHERE `ID`=8899;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리가 텅 비었어요! 우리 기병대에게 탈것을 마련해 줘야 합니다. 당신이 스톰파이크를 위해 힘을 보태 주세요!', `FemaleText_loc4`='马厩是空的！我们必须为骑兵提供充足的坐骑。卡尔·雷矛马厩需要你的帮助！', `FemaleText_loc5`='獸欄是空的!我們必須為騎兵提供充足的坐騎。雷矛獸欄需要你的幫助!', `FemaleText_loc7`='¡El establo está vacío! Debemos proporcionar monturas adecuadas a nuestra caballería. ¡Los establos Pico Tormenta requieren tu ayuda!' WHERE `ID`=8900;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서리늑대 부족에게 죽음을!', `MaleText_loc4`='霜狼，死吧！', `MaleText_loc5`='霜狼，死吧!', `MaleText_loc7`='¡Muerte al Lobo Gélido!' WHERE `ID`=8901;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 귀관의 명령에 따라 출격한다!', `MaleText_loc4`='听从你的指令！', `MaleText_loc5`='聽從你的指令!', `MaleText_loc7`='¡Cabalgaremos cuando nos des la orden!' WHERE `ID`=8902;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이랴! 최전선으로 출격!', `MaleText_loc4`='哟！呃，跟你一起去前线！', `MaleText_loc5`='喲!呃，跟你一起去前線!', `MaleText_loc7`='¡AAAH! ¡A la primera línea!', `FemaleText_loc1`='이랴! 최전선으로 출격!', `FemaleText_loc4`='哟！呃，跟你一起去前线！', `FemaleText_loc5`='喲!呃，跟你一起去前線!', `FemaleText_loc7`='¡AAAH! ¡A la primera línea!' WHERE `ID`=8903;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나의 상관에게서 올 명령서를 기다리는 중이오!', `MaleText_loc4`='等待上级命令！', `MaleText_loc5`='等待上級命令!', `MaleText_loc7`='Esperando órdenes de mis superiores.' WHERE `ID`=8904;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='산양기병대여, 전열을 맞춰라!', `MaleText_loc4`='山羊骑兵，列队！', `MaleText_loc5`='山羊騎兵，列隊!', `MaleText_loc7`='Jinetes de carneros, ¡EN ORDEN!' WHERE `ID`=8905;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제군들이여, 오늘이야말로 최고의 날이 될 것이다. 바로 오늘, 제군들은 스톰파이크의 영광을 위해 싸우는 것이다! 전투에 나서면 절대로 적에게 자비를 베풀지 말도록! 야만족을 쓰러뜨리고 그들의 대족장으로 하여금 시신들을 수습하도록 하자!', `MaleText_loc4`='女士们先生们，今天是个伟大的日子。因为今天，你们将为卡尔·雷矛的荣耀而战！前进吧，对敌人绝不手下留情！打倒那些野蛮的家伙！', `MaleText_loc5`='女士們先生們，今天是個偉大的日子。因為今天，你們將為雷矛的榮耀而戰!前進吧，對敵人絕不手下留情!打倒那些野蠻的傢伙!', `MaleText_loc7`='Guerreros y guerreras. Hoy, puede ser su gran día, porque hoy, ¡luchan por la gloria Pico Tormenta! ¡Cabalguen y no tengan piedad con nuestros enemigos! ¡Machaquen a los salvajes y que su Jefe de Guerra tenga problemas para reconocer sus cadáveres!' WHERE `ID`=8906;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='병사들이여, 최전선을 순찰하라!', `MaleText_loc4`='士兵们，去前线巡逻！', `MaleText_loc5`='士兵們，去前線巡邏!', `MaleText_loc7`='¡Patrullad la primera línea, Soldados!' WHERE `ID`=8907;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='국왕 폐하 만세!', `MaleText_loc4`='为了国王而战！', `MaleText_loc5`='為了國王而戰!', `MaleText_loc7`='¡Por el rey!', `FemaleText_loc1`='국왕 폐하 만세!', `FemaleText_loc4`='为了国王而战！', `FemaleText_loc5`='為了國王而戰!', `FemaleText_loc7`='¡Por el rey!' WHERE `ID`=8908;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 기병대가 움직이려면 알터랙 토종 산양이 꼭 필요해요!', `FemaleText_loc4`='奥特兰克本地出产的山羊对我们的骑兵至关重要！', `FemaleText_loc5`='奧特蘭克本地出產的山羊對我們的騎兵至關重要!', `FemaleText_loc7`='Los carneros indígenas de Alterac son cruciales para nuestra caballería.' WHERE `ID`=8909;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='조금만 더 있으면 이 우리가 탈것으로 넘쳐나겠어요. 용맹한 얼라이언스의 병사여, 산양들은 이제부터 제가 잘 돌볼 테니 안심하시고 넘기세요.', `FemaleText_loc4`='再有一些坐骑我们的马厩就满啦。士兵，让我来保管它们吧。我会从这儿牵走一些。', `FemaleText_loc5`='再有一些坐騎我們的獸欄就滿啦。士兵，讓我來保管它們吧。我會從這兒牽走一些。', `FemaleText_loc7`='Solo unas cuántas más y nuestros establos estarán llenos de monturas. Déjalo conmigo, Soldado. Yo me haré cargo a partir de ahora.' WHERE `ID`=8910;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='산양을 길들여 왔습니다. 이 녀석들 냄새 무지 지독하네요!', `MaleText_loc4`='乐意效劳。这些东西真臭！', `MaleText_loc5`='樂意效勞。這些東西真臭!', `MaleText_loc7`='Encantado. ¡Estas cosas apestan!', `FemaleText_loc1`='산양을 길들여 왔습니다. 이 녀석들 냄새 무지 지독하네요!', `FemaleText_loc4`='乐意效劳。这些东西真臭！', `FemaleText_loc5`='樂意效勞。這些東西真臭!', `FemaleText_loc7`='Encantada. ¡Estas cosas apestan!' WHERE `ID`=8911;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 야수를 맡아주십시오.', `MaleText_loc4`='我想寄放我的宠物。', `MaleText_loc5`='我想寄放我的寵物。', `MaleText_loc7`='Deseo guardar a mi mascota en el establo.', `FemaleText_loc1`='제 야수를 맡아주십시오.', `FemaleText_loc4`='我想寄放我的宠物。', `FemaleText_loc5`='我想寄放我的寵物。', `FemaleText_loc7`='Deseo guardar a mi mascota en el establo.' WHERE `ID`=8912;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋았어! 명령서가 도착했군! 자, 출격이다!', `MaleText_loc4`='好啦，入侵者们！攻击吧！', `MaleText_loc5`='好啦，劫奪者們!攻擊吧!', `MaleText_loc7`='¡De acuerdo, atracadores! ¡Tenemos las órdenes! ¡A luchar!' WHERE `ID`=8913;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기꺼이 이 명령서의 내용을 따르도록 하지, $n!', `MaleText_loc4`='乐意效劳，$n！', `MaleText_loc5`='樂意效勞，$n!', `MaleText_loc7`='¡Lo haré encantado, $n!' WHERE `ID`=8914;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 치유하기 알맞은 상태로 식물에서 튀어나옵니다.', `MaleText_loc4`='%s从植株中生长出来，开始进行治疗。', `MaleText_loc5`='%s從植株中生長出來並進行治療。', `MaleText_loc7`='%s emerge de la planta permitiendo su curación.' WHERE `ID`=8915;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 공격하기 시작합니다!', `MaleText_loc4`='%s发起了攻击！', `MaleText_loc5`='%s展開攻擊!', `MaleText_loc7`='%s ataca.' WHERE `ID`=8916;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='만나서 반갑습니다, $n. 할 일이 굉장히 많으니 인사는 간단히 하도록 하겠습니다.', `MaleText_loc4`='很高兴遇见你，$n。要做的事情还很多，我们必须抓紧时间。', `MaleText_loc5`='很高興遇見你，$n。要做的事情還很多，我們必須抓緊時間。', `MaleText_loc7`='Muy bien, $n. Debemos ser breves, hay mucho que hacer.' WHERE `ID`=8917;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$C|1이여;여;, 세나리우스께서 그대를 인도하시길.$B$B나는 세나리온 의회의 명을 받아 아주 중요한 임무를 수행하고자 자매들과 함께 이 타락한 땅에 왔네. 하지만 우리의 문제에 관해서는 좀 더 강한 자와 얘기를 나누고 싶군. 섣불리 약한 자를 보내는 것은 바보 같은 짓이니까.', `MaleText_loc4`='愿塞纳留斯指引你，$c。$B$B我和我的姊妹身负重任，从塞纳里奥议会来到这片被污染的土地。而只有那些足够强大的人才能帮助我，毕竟让能力不足的人去完成任务是愚蠢的做法。', `MaleText_loc5`='願塞納留斯指引你，$c。$B$B我和我的姐妹身負重任，從塞納里奧議會來到這片被污染的土地。但是在我詢問的人中，只有那些足夠強大的人才告訴我說─派遣能力較低的人是愚蠢的做法。', `MaleText_loc7`='Que Cenarius te guíe, $c.$B$BEstoy aquí, con mis hermanas, en esta tierra corrupta en una misión de gran importancia para el Círculo Cenarion. Pero exijo que solo se dirijan a mí aquellos que tengan el suficiente poder... enviar a un ser de menos poder sería una insensatez.' WHERE `ID`=8918;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저와 제 자매들은 오래전에 발생한 비극을 멈추기 위해 돌발톱 산맥에서 내려왔어요. 유감스럽게도 우리만으로는 그 목표를 달성할 만한 힘이 부족하기에 이제 당신과 같은 필사의 존재들에게 힘을 빌리게 된 거죠.$B$B당신에게 충분한 힘이 있다면 나누고 싶은 얘기가 너무나 많답니다, $c. 그렇지 않다면 당신 자신의 안전을 위해서라도 우리 임무에 대해 자세히 얘기하지 않겠어요.', `FemaleText_loc4`='我和我的姐妹从石爪山脉来到这儿，想要终止数年来的悲剧。不幸的是，我们还不够强大，无法独立完成目标，想向你这样的人寻求帮助。$B$B如果你足够强大，我们就谈谈任务的详细情况，$c。如果你还不够强大，那么，为了你的安全着想，就到此为止吧。', `FemaleText_loc5`='我和我的姐妹從石爪山脈來到這兒，想要終止數年來的悲劇。不幸的是，我們還不夠強大，無法獨立完成目標，想向你這樣的人尋求幫助。$B$B如果你足夠強大，我們就談談任務的詳細情況，$c。如果你還不夠強大，那麼，為了你的安全著想，就到此為止吧。', `FemaleText_loc7`='Mis hermanas y yo hemos venido desde Sierra Espolón para concluir una tragedia del pasado. Por desgracia, no somos lo suficientemente poderosas para conseguir nuestro objetivo, y estamos buscando a un mortal como tú que pueda ayudarnos.$B$BSi eres lo suficientemente $gpoderoso:poderosa;, podríamos hablar de ello, $c. Si no, por tu propia seguridad, no te contaré los detalles de esta misión.' WHERE `ID`=8919;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 제가 동굴에서 가져온 바일줄기 덩굴나무 견본을 잘 살펴보세요. 동굴 안에 들어가셨을 때 잘 찾을 수 있도록 말입니다...', `FemaleText_loc4`='$n，请看看我从洞穴中取出的维雷斯塔姆藤蔓的样本，这样你就知道自己要找什么了……', `FemaleText_loc5`='$n，請看看我從洞穴中取出的維雷斯塔姆藤蔓的樣本，這樣你就知道自己要找什麼了...', `FemaleText_loc7`='$n, por favor, echa un vistazo a la muestra de hiedravil que cogí en las cuevas, así sabrás lo que estás buscando...' WHERE `ID`=8920;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오라, $r|1이여;여;.', `MaleText_loc4`='向你致意，$r。', `MaleText_loc5`='向你致意，$r。', `MaleText_loc7`='Te saludo, $r.' WHERE `ID`=8921;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자유다! 자유! 마침내 해방됐도다!', `MaleText_loc4`='解放啦！我终于从镣铐中解放啦！', `MaleText_loc5`='解放啦!我終於從鐐銬中解放啦!', `MaleText_loc7`='¡Libre! ¡Por fin soy libre de mis ataduras!' WHERE `ID`=8922;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님, 제가 동굴에서 가져온 바일줄기 덩굴나무 견본을 잘 살펴보십시오. 동굴 안에 들어가셨을 때 잘 찾을 수 있도록 말입니다...', `MaleText_loc4`='$n，请看看我从洞穴中取出的维雷斯塔姆藤蔓的样本，这样你就知道自己要找什么了……', `MaleText_loc5`='$n，請看看我從洞穴中取出的維雷斯塔姆藤蔓的樣本，這樣你就知道自己要找什麼了...', `MaleText_loc7`='$n, por favor, echa un vistazo a la muestra de hiedravil que cogí en las cuevas, así sabrás lo que estás buscando...' WHERE `ID`=8923;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게 비록 고향이라고 부를 만한 곳은 없지만 이 세계에서 내가 설 자리가 있다는 것은 알고 있소. 언젠가 모든 부족들이 깨닫게 될 거요. 독수리가 먹다 남긴 찌꺼기... 불타는 군단이 득실거리는 이 땅을 두고 서로 싸우고들 있다니... 쳇!$B$B켄타우로스는 자신들의 혈통을 자랑스럽게 여겨야 하오. 나이트 엘프나 오크의 혈통만큼이나 고귀하니까 말이오. 이제 우리도 고귀한 혈통에 맞는 행동을 개시할 때가 됐소이다!', `MaleText_loc4`='在这世上，我已经不需要什么立足之地了，$c。部落……所有的部落成员将看见。他们相互交战，这是为了什么？遍地是秃鹫留下的骸骨……军团大肆侵犯我们的土地……呸！$B$B半人马应该为他们的遗产感到骄傲——这些遗产就跟暗夜精灵或兽人的遗产一样高贵——现在是我们效仿的时候啦！', `MaleText_loc5`='在這世上，我已經不需要什麼立足之地了，$c。部族...所有的部族成員將看見。他們相互交戰，這是為了什麼?遍地是禿鷹留下的骸骨...軍團大肆侵犯我們的土地...呸!$B$B半人馬應該為他們的遺產感到驕傲─這些遺產就跟夜精靈或獸人的遺產一樣高貴─現在是我們效仿的時候啦!', `MaleText_loc7`='No necesito que nadie sepa que todavía tengo un lugar en este mundo, $c. Las tribus verán... todas ellas. Luchan entre ellas y, ¿para qué? Sobras de los buitres... tierras infectadas por la Legión... ¡Bah!$B$BEl centauro debería sentirse orgulloso de su herencia... es tan noble como la de cualquier elfo de la noche u orco... ¡Ya era hora de que empezáramos a actuar como tal!' WHERE `ID`=8924;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어, 이곳에 나를 묶어 놓았던 타락에서 벗어났구나...', `MaleText_loc4`='最后，我从将我禁锢在此的腐化中解脱了……', `MaleText_loc5`='最後，我從將我禁錮在此的腐化中解脫了...', `MaleText_loc7`='Por fin soy libre de la corrupción que me tenía atado a este lugar...' WHERE `ID`=8925;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 날 구해 줘서 진정으로 고맙네.$B$B그 홀은 잘 간수하게나. 이곳에 침입한 악의 무리와 맞서 싸우는 데 도움이 될걸세...', `MaleText_loc4`='感谢你所做的一切，$n。$B$B请保管好节杖，它可以帮你抵御那些入侵此地的邪恶力量。', `MaleText_loc5`='感謝你所做的一切，$n。$B$B請保管好權杖，它可以幫你抵禦那些入侵此地的邪惡力量。', `MaleText_loc7`='Gracias por lo que has hecho, $n.$B$BProtege el cetro. Que te ayude en tu lucha contra el mal que ha invadido este lugar...' WHERE `ID`=8926;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 된 건가, $n? 셀레브라스의 홀과 같은 물건이 사소한 것이라고 생각하는가?$B$B이번에는 내가 도와 줄 수 있지만 또다시 그런 귀중한 물건을 함부로 다루는 일이 없도록 하라...', `MaleText_loc4`='怎么会这样，$n？你认为像塞雷布拉斯节杖这样的物品是微不足道的吗？$B$B这次我可以帮助你，但是别再对这么重要的物品掉以轻心啦……', `MaleText_loc5`='怎麼會這樣，$n?你認為像塞雷布拉斯權杖這樣的物品是微不足道的嗎?$B$B這次我可以幫助你，但是別再對這麼重要的物品掉以輕心啦...', `MaleText_loc7`='¿Cómo ha podido suceder esto, $n? ¿Crees que un objeto como el cetro de Celebras no es importante?$B$BTe ayudaré esta vez, pero no descuides de esa manera un objeto tan valioso...' WHERE `ID`=8927;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='셀레브라스, 제 홀을 잃어버렸습니다...', `MaleText_loc4`='塞雷布拉斯，我丢了我的节杖……', `MaleText_loc5`='塞雷布拉斯，我丟了我的權杖...', `MaleText_loc7`='Celebras, he perdido mi cetro...', `FemaleText_loc1`='셀레브라스, 제 홀을 잃어버렸습니다...', `FemaleText_loc4`='塞雷布拉斯，我丢了我的节杖……', `FemaleText_loc5`='塞雷布拉斯，我丟了我的權杖...', `FemaleText_loc7`='Celebras, he perdido mi cetro...' WHERE `ID`=8928;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='홀의 두 조각을 모두 가지고 있습니다.', `MaleText_loc4`='我携带有节杖的两个部分。', `MaleText_loc5`='我攜帶有權杖的兩個部分。', `MaleText_loc7`='Tengo las dos partes del cetro.', `FemaleText_loc1`='홀의 두 조각을 모두 가지고 있습니다.', `FemaleText_loc4`='我携带有节杖的两个部分。', `FemaleText_loc5`='我攜帶有權杖的兩個部分。', `FemaleText_loc7`='Tengo las dos partes del cetro.' WHERE `ID`=8929;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 홀... 그렇게 오랜 세월 끝에... 자네가 되찾았군! 자네야말로 이곳의 진정한 구원자라 할 수 있겠군...$B$B내 말 잘 듣게나, $n. 홀의 머리 부분과 자루는 마라우돈의 돌에서만 다시 하나로 결합시킬 수 있다네.', `MaleText_loc4`='我的节杖……这么多年过去了……你终于重新得到它了！你真是这儿的救世主……$B$B请仔细听我说，$n。只有在玛拉顿之石才能将节杖的杖头和杖身结合在一起。', `MaleText_loc5`='我的權杖...這麼多年過去了...你終於重新得到它了!你真是這兒的救世主...$b$b請仔細聽我說，$n。只有在瑪拉頓之石才能將權杖的杖頭和杖身結合在一起。', `MaleText_loc7`='Mi cetro... Después de tantos años... ¡Lo has recuperado! ¡Realmente eres $gel salvador:la salvadora; de este lugar!$B$BEscucha con atención, $n. Solo es posible unir la cabeza y la vara en la Piedra de Maraudon.' WHERE `ID`=8930;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마라우돈의 돌을 보여 주십시오.', `MaleText_loc4`='请让我看看玛拉顿的石头。', `MaleText_loc5`='請讓我看看瑪拉頓的石頭。', `MaleText_loc7`='Por favor, enséñame la Piedra de Maraudon.', `FemaleText_loc1`='마라우돈의 돌을 보여 주십시오.', `FemaleText_loc4`='请让我看看玛拉顿的石头。', `FemaleText_loc5`='請讓我看看瑪拉頓的石頭。', `FemaleText_loc7`='Por favor, enséñame la Piedra de Maraudon.' WHERE `ID`=8931;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='홀은 어떻게 사용되는 것인지 가르쳐 주십시오.', `MaleText_loc4`='请解释一下怎么使用节杖。', `MaleText_loc5`='請解釋一下怎麼使用權杖。', `MaleText_loc7`='Por favor, explícame cómo funciona el cetro.', `FemaleText_loc1`='홀은 어떻게 사용되는 것인지 가르쳐 주십시오.', `FemaleText_loc4`='请解释一下怎么使用节杖。', `FemaleText_loc5`='請解釋一下怎麼使用權杖。', `FemaleText_loc7`='Por favor, explícame cómo funciona el cetro.' WHERE `ID`=8932;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='색 사이로 길이 있어$B$B빛 가운데 지나가니$B$B물에서 그대가 나타나도다.', `MaleText_loc4`='在繁复的色彩中出现一条小路。$B$B被光线映衬得闪闪发光。$B$B你从水底浮上来。', `MaleText_loc5`='在繁複的色彩中出現一條小路。$B$B被光線映襯得閃閃發光。$B$B你從水底浮上來。', `MaleText_loc7`='Entre los colores, un camino.$B$BParpadea en la luz.$B$BDel agua, nacerás.' WHERE `ID`=8933;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 뜻인지 이해가 잘 안 됩니다...', `MaleText_loc4`='我不太明白……', `MaleText_loc5`='我不太明白...', `MaleText_loc7`='No lo comprendo muy bien...', `FemaleText_loc1`='무슨 뜻인지 이해가 잘 안 됩니다...', `FemaleText_loc4`='我不太明白……', `FemaleText_loc5`='我不太明白...', `FemaleText_loc7`='No lo comprendo muy bien...' WHERE `ID`=8934;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마라우돈으로 통하는 문 근처에 있는 주황색 길과 보라색 길 사이에 세 번째 길이 보일 걸세.$B$B자네가 손에 들고 있는 그 홀이 바로 열쇠인 것이지.', `MaleText_loc4`='在玛拉顿大门附近的橙色和紫色通道之间还有一条道路。$B$B你手中的节杖便是钥匙。', `MaleText_loc5`='在瑪拉頓大門附近的橘色和紫色通道之間還有一條道路。$B$B你手中的權杖便是鑰匙。', `MaleText_loc7`='Entre los pasadizos naranja y púrpura, cerca de las puertas de Maraudon, encontrarás un tercer camino.$B$BEl cetro que llevas en tus manos, es la llave.' WHERE `ID`=8935;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직도 무슨 말인지 모르겠습니다...', `MaleText_loc4`='不，真的，我还是不懂……', `MaleText_loc5`='不，真的，我還是不懂...', `MaleText_loc7`='No, en serio, sigo sin entenderlo...', `FemaleText_loc1`='아직도 무슨 말인지 모르겠습니다...', `FemaleText_loc4`='不，真的，我还是不懂……', `FemaleText_loc5`='不，真的，我還是不懂...', `FemaleText_loc7`='No, en serio, sigo sin entenderlo...' WHERE `ID`=8936;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피곤하게 하는군...$B$B여기서 폭포가 보일 텐데, 다시 마라우돈의 정문을 통과하고 싶다면 그 홀이 자네에게 바로 이곳까지 올 수 있는 힘을 부여해 줄 거란 말일세, $n.$B$B마라우돈의 입구 근처에 동굴 밑으로 통하는 길이 있으니 고대 의식 장소에서 홀을 사용해 차원문을 만들면 다시 여기로 오게 된다는 거지.', `MaleText_loc4`='我越来越疲惫了……$B$B从这儿你可以看见瀑布，$n……要是你敢再次进入玛拉顿的大门，节杖将赋予你抵达那儿的能力。$B$B在玛拉顿的入口附近，你会看见一条通往洞穴之下的通道。在远古遗址处使用节杖创造传送门，你就可以进入玛拉顿了。', `MaleText_loc5`='我越來越疲憊了...$b$b從這兒你可以看見瀑布，$n...要是你敢再次進入瑪拉頓的大門，權杖將賦予你抵達那兒的能力。$B$B在瑪拉頓的入口附近，你會看見一條通往洞穴之下的通道。在遠古遺址處使用權杖講創造傳送門，你就可進入瑪拉頓。', `MaleText_loc7`='Me estoy cansando...$B$BDesde aquí, puedes ver las cataratas, $n... El cetro te otorga el poder de viajar a este mismo lugar si alguna vez deseas atravesar de nuevo las puertas de Maraudon.$B$BCerca de la entrada de Maraudon, encontrarás un pasadizo que baja a las cuevas. Utiliza el cetro en el lugar del ritual ancestral para crear un portal y te encontrarás aquí de nuevo.' WHERE `ID`=8937;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마라우돈에 대해 더 자세히 얘기해 주십시오.', `MaleText_loc4`='告诉我关于玛拉顿的更多信息。', `MaleText_loc5`='告訴我關於瑪拉頓的更多資訊。', `MaleText_loc7`='Háblame más sobre Maraudon, por favor.', `FemaleText_loc1`='마라우돈에 대해 더 자세히 얘기해 주십시오.', `FemaleText_loc4`='告诉我关于玛拉顿的更多信息。', `FemaleText_loc5`='告訴我關於瑪拉頓的更多資訊。', `FemaleText_loc7`='Háblame más sobre Maraudon, por favor.' WHERE `ID`=8938;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오래전, 내 드리아드 자매들과 나는 내 숙부 재타르의 고통받는 영혼을 풀어 드리기 위해 이 동굴에 들어왔었네. 하지만 우리도 곧 이 동굴에 이미 퍼져 있던 타락에 제압돼 쓰러져 버렸지.$B$B우리는 이 길에서 방황할 운명을 맞게 되었고, 우리의 정신에는 독이 퍼지고 있었어...$B$B이제 내 영혼은 쉴 수 있게 됐지만 내 임무는 실패한 것이라는 걸 아네. 내가 짊어져야 할 큰 슬픔이지...', `MaleText_loc4`='很久以前，我和我的森林女神姐妹们曾进入这些洞穴，想释放我的叔叔扎尔塔倍受折磨的灵魂。但是，已经充斥了所有洞穴的腐化力量很快击败了我们。$B$B我们注定要在此迷失方向；毒素侵蚀了我们的头脑……$B$B尽管现在我的灵魂已经安息，但是我知道我没能完成任务。我要为此承担巨大的悲伤……', `MaleText_loc5`='很久以前，我和我的森林女神姐妹們曾進入這座洞穴，想釋放我的叔叔札爾塔倍受折磨的靈魂。但是，已經充斥了所有洞穴的腐化力量很快擊敗了我們。$B$B我們註定要在此迷失方向;毒素侵蝕了我們的頭腦...$b$b儘管現在我的靈魂已經安息，但是我知道我沒能完成任務。我要為此承擔巨大的悲傷...', `MaleText_loc7`='Mucho tiempo atrás, mis hermanas dríades y yo entramos en estas cuevas para liberar el espíritu atormentado de mi tío, Zaetar. Sin embargo, la corrupción que ya se había extendido por estas cuevas, pronto se apoderó de nosotros.$B$BFuimos condenados a vagar por estos tres pasadizos; las toxinas envenenaban nuestras mentes...$B$BAunque mi espíritu ahora puede descansar, sé que he fallado en mi misión. Y me embarga una gran tristeza...' WHERE `ID`=8939;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='재타르에 대해 자세히 말씀해 주시기 바랍니다.', `MaleText_loc4`='告诉我关于扎尔塔的更多信息。', `MaleText_loc5`='告訴我關於札爾塔的更多資訊。', `MaleText_loc7`='Háblame más sobre Zaetar, por favor.', `FemaleText_loc1`='재타르에 대해 자세히 말씀해 주시기 바랍니다.', `FemaleText_loc4`='告诉我关于扎尔塔的更多信息。', `FemaleText_loc5`='告訴我關於札爾塔的更多資訊。', `FemaleText_loc7`='Háblame más sobre Zaetar, por favor.' WHERE `ID`=8940;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 재타르 숙부... <고개를 돌리는 셀레브라스>$B$B우리 아버지 레물로스께서 재타르 숙부를 말리려고 하셨었지...$B$B고집 센 재타르 숙부가 대지의 정령 공주와 사랑에 빠졌을 때 우리 아버지께서는 그 사랑이 저주받은 것이라는 사실을 깨달으셨지만 재타르 숙부는 그 말을 들으려 하지 않았네.$B$B그 실수의 결과로 켄타우로스가 탄생한 것이지. 증오에 가득 차 기형으로 태어난 그 켄타우로스들의 손에 우리 재타르 숙부도 살해 당하셨네... 자신의 혈족의 손에 말이야.$B$B사악한 테라드라스 공주는 아직도 이 수정 동굴에서 재타르 숙부의 유해를 지키고 있다네.', `MaleText_loc4`='啊，扎尔塔……<塞雷布拉斯把头扭了过去。>$B$B我的父亲雷姆洛斯试图阻止他……$B$B扎尔塔太顽固了，当他爱上一位土元素公主时，我父亲就知道他们的结合将受到诅咒，但是扎尔塔拒绝听从父亲的意见。$B$B他因此变成了半人马。他们生下来就带着畸形的躯体，并充满仇恨；我的叔叔扎尔塔被自己的亲戚所杀……$B$B那个邪恶的瑟莱德丝公主，还在水晶洞穴内守护着他的遗体。', `MaleText_loc5`='啊，札爾塔...<塞雷布拉斯把頭扭了過去。>$B$B我的父親雷姆洛斯試圖阻止他...$b$b札爾塔太頑固了，當他愛上一位土元素公主時，我父親就知道他們的結合將受到詛咒，但是札爾塔拒絕聽從父親的意見。$B$B他因此變成了半人馬。他們生下來就帶著畸形的軀體，並充滿仇恨;我的叔叔札爾塔被自己的親戚所殺...$b$b那個邪惡的瑟萊德絲公主，還在水晶洞穴內守護著他的遺體。', `MaleText_loc7`='Ah, Zaetar... <Celebras aparta su mirada.>$B$BMi padre, Remulos, intentó detenerle...$B$BZaetar era muy obstinado y, cuando se enamoró de una princesa elemental de la tierra, mi padre supo que esa unión estaba condenada, pero Zaetar se negó a escuchar.$B$BLos centauros son el resultado de su error. Nacieron deformes y llenos de odio; mi tío Zaetar murió a manos de sus hijos...$B$BLa malvada princesa, Theradras, sigue guardando sus restos aquí, en las Cuevas de Cristal.' WHERE `ID`=8941;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쳇! 저런 경박한 고블린 녀석들, 스스로 부끄러운 줄 알아야지...', `MaleText_loc4`='这些地精应该为他们的行为感到羞耻。呸！', `MaleText_loc5`='這些哥布林應該為他們的行為感到羞恥。呸!', `MaleText_loc7`='Esos goblins deberían sentirse avergonzados. ¡Bah!' WHERE `ID`=8942;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겨울맞이 축제의 진정한 의미는 흥청망청 돈 쓰는 게 아니라고!', `MaleText_loc4`='花费金钱不是为了冬幕节！', `MaleText_loc5`='花費金錢不是為了冬幕節!', `MaleText_loc7`='Gastar dinero NO es la razón del festín del Festival de Invierno.' WHERE `ID`=8943;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='믿을 수 없는 일이지, 정말... 저 탐욕스러운 고블린 녀석들이 숭고한 축제의 정신을 더럽히는 싸구려 물건을 팔도록 내버려두다니 말이야.', `MaleText_loc4`='我不敢相信这些贪婪的地精能在破坏季节的精神的同时兜售他们的器皿。', `MaleText_loc5`='我不敢相信這些貪婪的哥布林能在破壞季節的精神的同時兜售他們的器皿。', `MaleText_loc7`='No puedo creer que esos avariciosos goblins puedan ir pregonando sus mercancías por ahí, arruinando el espíritu del Festival.' WHERE `ID`=8944;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더러운 고블린 녀석들... 돈이라면 뭐든지 한다니까.', `MaleText_loc4`='卑鄙的地精……什么东西都要一金币。', `MaleText_loc5`='卑鄙的哥布林...什麼東西都要一金幣。', `MaleText_loc7`='Malvados goblins... cualquier cosa por una moneda de oro.' WHERE `ID`=8945;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"겨울맞이 축제"라는 책을 한 권 구할 수 있을까요?', `MaleText_loc4`='能给我一本《冬幕节》书的副本读一读吗？', `MaleText_loc5`='能給我一本《冬幕節》的書讀一讀嗎?', `MaleText_loc7`='Me gustaría leer un ejemplar de "El festín del Festival de Invierno", si es posible.', `FemaleText_loc1`='"겨울맞이 축제"라는 책을 한 권 구할 수 있을까요?', `FemaleText_loc4`='能给我一本《冬幕节》书的副本读一读吗？', `FemaleText_loc5`='能給我一本《冬幕節》的書讀一讀嗎?', `FemaleText_loc7`='Me gustaría leer un ejemplar de "El festín del Festival de Invierno", si es posible.' WHERE `ID`=8946;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무래도 나중에 시도해 봐야겠군. 생각이 있거든 다시 나한테 얘기하게.', `MaleText_loc4`='或许我们可以稍后再尝试尝试。等你想好的时候再跟我谈谈。', `MaleText_loc5`='或許我們可以稍後再嘗試嘗試。等你想好的時候再跟我談談。', `MaleText_loc7`='Quizás podamos intentarlo más tarde. Vuelve a hablar conmigo si deseas hacerlo.' WHERE `ID`=8947;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두 부분이 합쳐져 다시 하나가 될지니.', `MaleText_loc4`='这两部分将再次合二为一。', `MaleText_loc5`='這兩部分將再次合二為一。', `MaleText_loc7`='Juntas, las dos partes se convierten en una, de nuevo.' WHERE `ID`=8948;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샬 미리난 이시누 달도라...', `MaleText_loc4`='Shal myrinan ishnu daldorah……', `MaleText_loc5`='(達納蘇斯語)雪憂·麥利奈·伊蘇奴·朵多拉...', `MaleText_loc7`='Shal myrinan ishnu daldorah...' WHERE `ID`=8949;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 자네 앞에 놓은 이 책을 큰 소리로 읽어 보게.', `MaleText_loc4`='看看我放在你面前的这本卷轴，大声阅读。', `MaleText_loc5`='看看我放在你面前的這本卷軸，大聲閱讀。', `MaleText_loc7`='Lee en voz alta el libro que he colocado ante ti.' WHERE `ID`=8950;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 돌에 힘을 집중하기 시작합니다.', `MaleText_loc4`='%s开始将他的能量引导到石头上。', `MaleText_loc5`='%s開始將他的能量傳送至石頭上。', `MaleText_loc7`='%s comienza a canalizar su energía, concentrándose en la piedra.' WHERE `ID`=8951;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌에 대해서 알고 싶은가? 날 따라오게.', `MaleText_loc4`='你想研究石头？跟我来。', `MaleText_loc5`='你想研究石頭?跟我來。', `MaleText_loc7`='¿Quieres saber más sobre la piedra? Sígueme.' WHERE `ID`=8952;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 홀의 두 부분이 다시 합쳐져 하나가 될지니...', `MaleText_loc4`='多年来我都在被诅咒的形态下飘泊生活。你恢复了我的自由……你会得到报答的。', `MaleText_loc5`='多年來我都在被詛咒的形態下飄泊生活。你恢復了我的自由...你會得到報答的。', `MaleText_loc7`='He vivido durante demasiado tiempo en mi forma maldita. Me has liberado... Se te recompensará por tu duro trabajo.' WHERE `ID`=8953;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 지시한 대로 하도록 하게, $n.', `MaleText_loc4`='请按照我教你的那样做，$n。', `MaleText_loc5`='請按照我教你的那樣做，$n。', `MaleText_loc7`='Por favor, haz lo que te digo, $n.' WHERE `ID`=8954;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 홀이 다시 한번 온전한 하나가 될지니!', `MaleText_loc4`='我的节杖再次合二为一啦！', `MaleText_loc5`='我的權杖再次合二為一啦!', `MaleText_loc7`='¡Mi cetro volverá a estar completo!' WHERE `ID`=8955;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탐험가 연맹에 잘 왔네. 정보를 찾고 있는 거라면 내가 도와 줄 수 있을지도 모르지. 난 책에는 빠삭하니까.', `MaleText_loc4`='欢迎来到探险者联盟。如果你需要书面信息的话，我也许能帮你。', `MaleText_loc5`='歡迎來到探險者協會。如果你需要資訊，而又剛好是屬於書面形式的，我也許能幫你。', `MaleText_loc7`='Te doy la bienvenida a la Liga de Expedicionarios. Si necesitas información, y esa información viene en algún libro, quizás pueda ayudarte.' WHERE `ID`=8956;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='홀의 두 조각은 어떻게 찾을 수 있습니까?', `MaleText_loc4`='我要怎么才能找到节杖的两个部分呢？', `MaleText_loc5`='我要怎麼才能找到權杖的兩個部分呢?', `MaleText_loc7`='¿Cómo puedo encontrar las dos partes del cetro?', `FemaleText_loc1`='홀의 두 조각은 어떻게 찾을 수 있습니까?', `FemaleText_loc4`='我要怎么才能找到节杖的两个部分呢？', `FemaleText_loc5`='我要怎麼才能找到權杖的兩個部分呢?', `FemaleText_loc7`='¿Cómo puedo encontrar las dos partes del cetro?' WHERE `ID`=8957;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마라우돈 안에 퍼져 있는 독이 내 정신에 스며들면서 나는 현실에 대한 감각을 잃어 가기 시작했네. 내 홀이 악한 목적에 사용될 것을 두려워한 내 드리아드 자매들은 내게서 홀을 빼앗아 두 조각 낸 다음 이 굴 속에 숨겨 두었지.$B$B그러나 곧 그들도 광기에 희생되었고 아무도 지키고 있지 않던 홀의 두 부분은 바일텅 녀석의 손에 들어가게 되었다네. 바일텅은 그중 하나는 녹시온이라는 사악한 정령에게 맡겼고, 나머지 하나는 지금까지 그가 지니고 있지.', `MaleText_loc4`='潜伏在玛拉顿的毒素开始渗入我的头脑，我逐渐丧失对事实的判断力。我的树妖姐妹们担心我会被恶魔利用，她们悄悄地拿走了我的节杖，将节杖断成两截，藏在洞穴中。$B$B很快，她们也丧失了理智，两段节杖也因无人看守，成了维利塔恩的囊中之物。那个萨特将一截节杖交给邪恶的元素诺克赛恩看管，另一截则由他自己保管至今。', `MaleText_loc5`='潛伏在瑪拉頓的毒素開始滲入我的頭腦，我逐漸喪失對事實的判斷力。我的林精姐妹們擔心我會被惡魔利用，她們悄悄地拿走了我的權杖，將權杖斷成兩截，藏在洞穴中。$B$B很快，她們也喪失了理智，兩段權杖也因無人看守，成了維利塔恩的囊中之物。那個薩特將一截權杖交給邪惡的元素諾克賽恩看管，另一截則由他自己保管至今。', `MaleText_loc7`='Cuando las toxinas que flotaban en Maraudon empezaron a filtrarse en mi mente, comencé a perder el contacto con la realidad. Mis hermanas dríades, preocupadas por si lo utilizaba para hacer el mal, me lo quitaron en secreto y lo partieron en dos antes de esconderlo en las cuevas.$B$BPronto, ellas también cayeron víctimas de la locura y las dos partes del cetro, desprotegidas, fueron a parar al malvado Lenguavil. El sátiro le confió una de las partes a Noxxion, un elemental malvado, y se quedó con la otra.' WHERE `ID`=8958;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='군주 바일텅은 왜 그 홀의 두 조각을 하나로 결합시키지 않은 겁니까?', `MaleText_loc4`='诺克赛恩为什么不能将节杖的两部分结合到一起？', `MaleText_loc5`='維利塔恩領主為什麼不能將權杖的兩部分結合起來呢?', `MaleText_loc7`='¿Y por qué Lord Lenguavil no unió las partes del cetro?', `FemaleText_loc1`='군주 바일텅은 왜 그 홀의 두 조각을 하나로 결합시키지 않은 겁니까?', `FemaleText_loc4`='诺克赛恩为什么不能将节杖的两部分结合到一起？', `FemaleText_loc5`='維利塔恩領主為什麼不能將權杖的兩部分結合起來呢?', `FemaleText_loc7`='¿Y por qué Lord Lenguavil no unió las partes del cetro?' WHERE `ID`=8959;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='군주 바일텅이 두 조각을 결합시키는 데 필요한 주문을 알지 못하니 그 홀을 사용할 수가 없었지. 하지만 이제 내가 바일텅의 타락의 저주로부터 해방됐으니 자네가 홀의 머리 부분과 자루 부분을 모두 가져오면 내가 자네를 도와 주도록 하겠네.', `MaleText_loc4`='没有结合节杖两部分所需的咒语，诺克赛恩是无法使用节杖的。但是，我已经从诺克赛恩的诅咒中解放啦，如果你能将节杖的两部分交给我——节杖的头部和棍身，我会帮助你的。', `MaleText_loc5`='沒有結合權杖兩部分所需的咒語，維利塔恩領主是無法使用權杖的。但是，我已經從維利塔恩的詛咒中解放啦，如果你能將權杖的兩部分交給我─權杖的頭部和杖身，我會幫助你的。', `MaleText_loc7`='Sin el conocimiento de los encantamientos necesarios para unir ambas partes, Lord Lenguavil no podía usar el cetro. Sin embargo, ahora que soy libre de la maldición de la corrupción de Lenguavil, podré ayudarte si quieres traerme las dos partes. La cabeza y la vara del cetro.' WHERE `ID`=8960;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='레물로스와 재타르의 역사에 대해 좀 더 자세히 얘기해 주십시오.', `MaleText_loc4`='请告诉我关于雷姆洛斯和扎尔塔的历史。', `MaleText_loc5`='請告訴我關於雷姆洛斯和札爾塔的歷史。', `MaleText_loc7`='Cuéntame más sobre Remulos y Zaetar.', `FemaleText_loc1`='레물로스와 재타르의 역사에 대해 좀 더 자세히 얘기해 주십시오.', `FemaleText_loc4`='请告诉我关于雷姆洛斯和扎尔塔的历史。', `FemaleText_loc5`='請告訴我關於雷姆洛斯和札爾塔的歷史。', `FemaleText_loc7`='Cuéntame más sobre Remulos y Zaetar.' WHERE `ID`=8961;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='레물로스와 재타르는 세나리우스의 아들들이라네.$B$B우리 아버지 레물로스는 강하고 뛰어난 분이셨고, 재타르 숙부는 매우 영리하고 늘씬한 신체를 지닌 분이셨지. 두 분 모두 똑같이 존경을 받았지만 재타르 숙부는 언제나 아버지가 자신보다 훨씬 더 큰 영광과 주목을 받고 있다고 생각했다네.$B$B나와 내 자매들이 태어난 후, 시기심에 눈이 먼 재타르 숙부는 자신의 형을 처치해 버리려 했고... 결국 자멸의 길을 걷고 말았지. 시간이 흘러도 그로 인한 내 슬픔은 가시지 않는다네...', `MaleText_loc4`='你问到塞纳留斯的儿子雷姆洛斯和扎尔塔。$B$B我的父亲雷姆洛斯强壮英俊，我的叔叔扎尔塔矮小灵动。虽然两人受到大家的一致尊重，但是扎尔塔总认为自己无法得到雷姆洛斯所享受的荣耀和受到的关注。$B$B我和我的姐妹们出生后，扎尔塔在嫉妒心的驱使下，想要超越他的兄弟……他自作自受。即使事情已经过去了这么久，我心中仍悲恸不已……', `MaleText_loc5`='你問到塞納留斯的兒子雷姆洛斯和札爾塔。$B$B我的父親雷姆洛斯強壯英俊，我的叔叔札爾塔矮小靈動。雖然兩人受到大家的一致尊重，但是札爾塔總認為自己無法得到雷姆洛斯所享受的榮耀和受到的關注。$B$B我和我的姐妹們出生後，札爾塔在嫉妒心的驅使下，想要超越他的兄弟...他自作自受。即使事情已經過去了這麼久，我心中仍悲慟不已...', `MaleText_loc7`='Los Hijos de Cenarius, Remulos y Zaetar.$B$BMi padre, Remulos, era fuerte y hermoso, y mi tío, Zaetar, muy astuto y de complexión pequeña. Si bien eran respetados por igual, Zaetar siempre sintió que no recibía la misma gloria y atención que su hermano.$B$BDespués de que mis hermanas y yo nacieramos, Zaetar, cegado por los celos, partió para intentar superar a su hermano... Fue el creador de su propio fin. Todavía me produce una gran tristeza, incluso con el paso del tiempo...' WHERE `ID`=8962;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 영혼과 유해는 이곳 마라우돈에 오랫동안 붙들려 있었느니라, 젊은 $c|1이여;여;. 그동안 내가 저지른 실수를 반성하고 형님에 대한 내 시기심이 어리석었다는 것을 깨달을 기회를 충분히 가졌도다. 형님은 나와 테라드라스의 관계에서 나오는 것은 그 어떤 것도 순수할 수 없고 오직 혼돈으로부터 파괴가 나오게 될 뿐이라고 충고하고 설득하려 하셨었지. 형님의 말씀이 옳았어.$B$B하지만 그렇다고 해서 네가 나를 구해 준 것으로 내 죄가 씻긴 것은 아니지.', `MaleText_loc4`='我的灵魂和残骸被禁锢在玛拉顿很久了，年轻的$c。我在这儿深深反思自己的错误，发现自己对雷姆洛斯的嫉妒是很愚蠢的行为。他尝试告诫我，并劝我说我和瑟莱德丝公主之间的关系只能是纯洁的——一旦关系混乱灾难就会降临。我的兄弟是对的。$B$B但是现在你释放了我，情况就不同了。', `MaleText_loc5`='我的靈魂和殘骸被禁錮在瑪拉頓很久了，年輕的$c。我在這兒深深反思自己的錯誤，發現自己對雷姆洛斯的嫉妒是很愚蠢的行為。他嘗試告誡我，並勸我說我和瑟萊德絲公主之間的關係只能是純潔的─一旦關係混亂災難就會降臨。我的兄弟是對的。$B$B但是現在你釋放了我，情況就不同了。', `MaleText_loc7`='Mi espíritu y mis restos llevan mucho tiempo cautivos en Maraudon, joven $c. El tiempo solo me ha concedido oportunidades para reflexionar sobre mis errores y darme cuenta de que los celos que sentía por Remulos eran una locura. Intentó advertirme y convencerme que de que mi relación con Theradras no podría salir nada puro... que solo la destrucción vendría del caos. Mi hermano tenía razón.$B$BPero eso no significa que como me has liberado, soy libre de mi penitencia.' WHERE `ID`=8963;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 말씀해 주십시오.', `MaleText_loc4`='请继续。', `MaleText_loc5`='請繼續。', `MaleText_loc7`='Por favor, continúa.', `FemaleText_loc1`='계속 말씀해 주십시오.', `FemaleText_loc4`='请继续。', `FemaleText_loc5`='請繼續。', `FemaleText_loc7`='Por favor, continúa.' WHERE `ID`=8964;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비록 이단자로 추방을 당하기는 했지만 내 믿음은 여전히 흔들리지 않소. 오히려 나를 앞으로 나아가게 하는 유일한 힘이 되고 있지. 하지만 내 운명의 목적을 달성하려면 타인의 도움이 필요하오... 켄타우로스 부족이 아닌 다른 누군가의 도움이...$B$B이 임무를 위해서는 누군가 마라우돈의 성스러운 전당으로 들어가야 하는데, 그곳은 우리 일족이 지키는 신전이자 가장 신앙심이 깊은 자들만이 들어갈 수 있는 장소요.$B$B당신이 나를 도와 주겠다면 고개만 끄덕이시오. 내가 지시 사항을 적어 놓은 양피지를 줄 테니. 그걸 읽어 보고 내 말을 잘 생각해 보시오.', `MaleText_loc4`='尽管我被当作异教徒，我仍然坚持自己的信仰——这信仰指引着我不断前进。但是要完成我的使命，我需要他人的帮助……这人只要不是半人马就行。$B$B任务需要你进入玛拉顿神圣的大厅——我的人民守护着这座神殿，只有最虔诚的人才可以进去。$B$B如果你同意帮助我的话，就点点头吧。我会给你一张羊皮纸，上面写着我给你指示。好好看看。', `MaleText_loc5`='儘管我被當作異教徒，我仍然堅持自己的信仰─這信仰指引著我不斷前進。但是要完成我的使命，我需要他人的幫助...這人只要不是半人馬就行。$B$B任務需要你進入瑪拉頓神聖的大廳─我的人民守護著這座神殿，只有最虔誠的人才可以進去。$B$B如果你同意幫助我的話，就點點頭吧。我會給你一張羊皮紙，上面寫著我給你指示。好好看看。', `MaleText_loc7`='Aunque me exiliaron por hereje, sé que digo la verdad y eso me anima a seguir adelante. Pero para que mi destino se complete, necesito la ayuda de un extranjero... alguien que no pertenezca a una tribu de centauros.$B$BLa misión requiere que alguien entre en las salas sagradas de Maraudon, un templo que los míos protegen y donde solo se permite entrar a los más devotos.$B$BSi quieres ayudarme, solo tienes que decir que sí. Te daré un papiro con instrucciones. Léelo y considera mi propuesta.' WHERE `ID`=8965;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 도와 주겠으니 그 지시서를 주시오.', `MaleText_loc4`='我会帮你的。教我怎么做。', `MaleText_loc5`='我會幫你的。教我怎麼做。', `MaleText_loc7`='Te ayudaré. Dame las instrucciones.', `FemaleText_loc1`='내가 도와 주겠으니 그 지시서를 주시오.', `FemaleText_loc4`='我会帮你的。教我怎么做。', `FemaleText_loc5`='我會幫你的。教我怎麼做。', `FemaleText_loc7`='Te ayudaré. Dame las instrucciones.' WHERE `ID`=8966;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 꾸벅 인사를 합니다.', `MaleText_loc4`='%s在你面前深深鞠躬。', `MaleText_loc5`='%s在你面前深深鞠躬。', `MaleText_loc7`='%s se inclina ante ti.' WHERE `ID`=8967;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙다, 고귀한 $c|1이여;여;.', `MaleText_loc4`='谢谢你，好心的$c。', `MaleText_loc5`='謝謝你，好心的$c。', `MaleText_loc7`='Gracias, $c.' WHERE `ID`=8968;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하시오. 나는 호드 응급의학회 수석 군의관을 맡고 있는 의사 그레고리 빅터라고 하오.', `MaleText_loc4`='你好，$n。我是格里高利·维克托医生，部落的首席外科医生。', `MaleText_loc5`='你好，$n。我是葛列格里·維克多醫生，部落的首席外科醫生。', `MaleText_loc7`='Hola, $n. Soy el doctor Gregory Víctor, cirujano de traumatismos cerebrales de la Horda.' WHERE `ID`=8969;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 보게 되어 반갑소. 그동안 지켜본 결과, 당신의 의술은 상당히 향상되었군. 이제 좀 더 어려운 고급 기술을 익힐 때가 되었다는 걸 알려주게 되어 상당히 기쁘오.$B$B지금처럼 기술이 향상될 즈음이면 때때로 이 몸을 찾아 주시오. 내가 알고 있는 모든 것을 천천히 당신에게 가르쳐 줄 작정이니까 말이오.', `MaleText_loc4`='很高兴再次见到你，$n医生。我看着你逐步成长，我敢说现在是你学习更高的绷带技能的时候啦。$B$B一旦你的技能得到提高，就回来找我，我会把我所知的一切都教给你的。', `MaleText_loc5`='很高興再次見到你，$n醫生。我看著你逐步成長，我敢說現在是你學習更高的繃帶技能的時候啦。$B$B一旦你的技能得到提高，就回來找我，我會把我所知的一切都教給你的。', `MaleText_loc7`='Me alegra verte de nuevo, doctor $n. He estado siguiendo tu progreso y, debo decir, que ya es hora de que aprendas algunas técnicas de vendaje más avanzadas.$B$BVen a verme de vez en cuando, según vayas progresando, y te enseñaré todo lo que sé.' WHERE `ID`=8970;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두꺼운 마법 붕대를 만들어 쓰는 법을 가르쳐 주십시오.', `MaleText_loc4`='医生，请告诉我制作厚魔纹绷带的方法。', `MaleText_loc5`='醫生，請教我製作厚魔紋繃帶的方法。', `MaleText_loc7`='Enséñame a hacer y aplicar vendas de tejido mágico gruesas, doctor.', `FemaleText_loc1`='두꺼운 마법 붕대를 만들어 쓰는 법을 가르쳐 주십시오.', `FemaleText_loc4`='医生，请告诉我制作厚魔纹绷带的方法。', `FemaleText_loc5`='醫生，請教我製作厚魔紋繃帶的方法。', `FemaleText_loc7`='Enséñame a hacer y aplicar vendas de tejido mágico gruesas, doctor.' WHERE `ID`=8971;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='룬무늬 붕대를 만들어 쓰는 법을 가르쳐 주십시오.', `MaleText_loc4`='医生，请告诉我制作符文布绷带的方法。', `MaleText_loc5`='醫生，請教我製作符文布繃帶的方法。', `MaleText_loc7`='Enséñame a hacer y aplicar vendas de paño rúnico, doctor.', `FemaleText_loc1`='룬무늬 붕대를 만들어 쓰는 법을 가르쳐 주십시오.', `FemaleText_loc4`='医生，请告诉我制作符文布绷带的方法。', `FemaleText_loc5`='醫生，請教我製作符文布繃帶的方法。', `FemaleText_loc7`='Enséñame a hacer y aplicar vendas de paño rúnico, doctor.' WHERE `ID`=8972;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두꺼운 룬무늬 붕대를 만들어 쓰는 법을 가르쳐 주십시오.', `MaleText_loc4`='医生，请告诉我制作厚符文布绷带的方法。', `MaleText_loc5`='醫生，請教我製作厚符文布繃帶的方法。', `MaleText_loc7`='Enséñame a hacer y aplicar vendas de paño rúnico gruesas, doctor.', `FemaleText_loc1`='두꺼운 룬무늬 붕대를 만들어 쓰는 법을 가르쳐 주십시오.', `FemaleText_loc4`='医生，请告诉我制作厚符文布绷带的方法。', `FemaleText_loc5`='醫生，請教我製作厚符文布繃帶的方法。', `FemaleText_loc7`='Enséñame a hacer y aplicar vendas de paño rúnico gruesas, doctor.' WHERE `ID`=8973;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까! 나는 얼라이언스 응급의학회 수석 군의관을 맡고 있는 의사 구스타프 밴하우젠이라고 합니다.', `MaleText_loc4`='你好，$n。我是古斯塔夫·范沃森医生，联盟的首席外科医生。', `MaleText_loc5`='你好，$n。我是古斯塔夫·范沃森醫生，聯盟的首席外科醫生。', `MaleText_loc7`='Hola, $n. Soy el doctor Gustaf VanHowzen, cirujano de traumatismos cerebrales de la Alianza.' WHERE `ID`=8974;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아! 계속 보급품을 가지고 오도록!', `MaleText_loc4`='好极了！我们要保证物资的运送！', `MaleText_loc5`='好極了!我們要保證物資的運送!', `MaleText_loc7`='¡Muy bien! ¡Vamos, gente, seguid trayendo suministros!' WHERE `ID`=8975;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보급품을 가져다줘서 고맙네, $n!', `MaleText_loc4`='感谢你提供的物资，$n！', `MaleText_loc5`='感謝你提供的物資，$n!', `MaleText_loc7`='¡Gracias por los suministros, $n!' WHERE `ID`=8976;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말로 고맙소, $n!', `MaleText_loc4`='非常感谢，$n！', `MaleText_loc5`='非常感謝，$n!', `MaleText_loc7`='¡Muchas gracias, $n!' WHERE `ID`=8977;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진척이 있군! 던 발다르를 수리하기 위한 보급품을 더 가져오도록 하시오!', `MaleText_loc4`='我们已经取得了不错的进展！需要取回更多的物资来修复丹巴达尔！', `MaleText_loc5`='我們已經取得了不錯的進展!需要取回更多的物資來修復丹巴達爾!', `MaleText_loc7`='¡Estamos progresando! Necesitamos más suministros para reparar Dun Baldar.' WHERE `ID`=8978;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보급품이 충분하오! 지휘관께서 투쟁의 벌판에서 거점을 다시 확보하셨소!', `MaleText_loc4`='我们拥有足够的物资啦！我们的队长重新在征战平原占据了阵地！', `MaleText_loc5`='我們擁有足夠的物資啦!我們的隊長重新在征戰平原佔據了陣地!', `MaleText_loc7`='¡Ya tenemos suficientes suministros! Nuestro capitán ha retomado su posición en la Tierra de Disputa.' WHERE `ID`=8979;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제야 진척이 좀 있군그래!', `MaleText_loc4`='现在我们取得了进展！', `MaleText_loc5`='現在我們取得了進展!', `MaleText_loc7`='¡Ahora estamos progresando!' WHERE `ID`=8980;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 방어구 조각들을 모아줘서 고맙소!', `MaleText_loc4`='谢谢你提供的护甲碎片，$n！', `MaleText_loc5`='謝謝你提供的護甲碎塊，$n!', `MaleText_loc7`='¡Gracias por los restos de armadura, $n!' WHERE `ID`=8981;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 장비와 물자가 늘어나고 있소!', `MaleText_loc4`='我们的装备储备增加啦!', `MaleText_loc5`='我們的裝備儲備增加啦!', `MaleText_loc7`='Nuestro alijo de equipamiento aumenta.' WHERE `ID`=8982;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 보급품을 가져다줘서 고맙소.', `MaleText_loc4`='谢谢你提供的物资，$n。', `MaleText_loc5`='謝謝你提供的物資，$n。', `MaleText_loc7`='Gracias por los suministros, $n.' WHERE `ID`=8983;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하하! 우리 창고에 보급품이 꽉꽉 들어차고 있소.', `MaleText_loc4`='很好。我们的物资在不断增加……', `MaleText_loc5`='很好。我們的物資在不斷增加...', `MaleText_loc7`='Muy bien. Nuestro alijo de equipamiento aumenta...' WHERE `ID`=8984;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속해서 가져오시오! 재건하려면 보급품이 더 필요하오!', `MaleText_loc4`='保持这样！我们还需要更多的物资来重建……', `MaleText_loc5`='保持這樣!我們還需要更多的物資來重建...', `MaleText_loc7`='¡Que sigan llegando! Necesitamos más suministros para reconstruir...' WHERE `ID`=8985;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 재건할 수 있소! 호드를 위하여!', `MaleText_loc4`='我们可以重建啦！为了部落而战！', `MaleText_loc5`='我們可以重建啦!為了部落而戰!', `MaleText_loc7`='¡Ahora podemos reconstruir! ¡Por la Horda!' WHERE `ID`=8986;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n! 자네가 날 찾아와 다행이야. 우린 투쟁의 벌판에 대한 지상 공격을 펼칠 준비가 됐어! 전투대장 가르릭이 명령서를 받기만 하면 그의 부대가 얼라이언스를 싹 쓸어버릴 거야!$B$B$n, 이 명령서를 전달해 주지 않겠나? 가르릭이 투쟁의 벌판에서 기다리고 있을 텐데...', `FemaleText_loc4`='嗨，$n！很高兴你来看我。我们正准备对征战平原发动一场规模浩大的地面攻击！等到霜狼突击队队长一声令下，他和他的部队将给予联盟致命的攻击！$B$B你想传达这些命令吗，$n？加瑞克在征战平原等着你呢……', `FemaleText_loc5`='嗨，$n!很高興你來看我。我們正準備對征戰平原發動一場規模浩大的地面攻擊!等到霜狼突擊隊隊長一聲令下，他和他的部隊將給予聯盟致命的攻擊!$B$B你想傳達這些命令嗎，$n?加瑞克在征戰平原等著你呢...', `FemaleText_loc7`='¡Saludos, $n! Me alegro de que hayas venido a verme. Estamos listos para lanzar un asalto terrestre en la Tierra de Disputa. Cuando el maestro de guerra Garrick obtenga las órdenes, él y sus atracadores se abrirán camino entre las tropas de la Alianza.$B$B¿Quieres entregar las órdenes, $n? Garrick está esperando en la Tierra de Disputa...' WHERE `ID`=8987;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n, 여기서 뭐 하는 거야? 장화에 주괴라도 들었나?$B$B자네에게 공격명령서가 있잖아! 그 명령서를 투쟁의 벌판에 있는 전투대장 가르릭이 받아야만 공격을 펼칠 수 있단 말이야! 어서 가게!', `FemaleText_loc4`='你怎么在这儿，$n？你怎么到这儿来啦？$B$B你不是带着攻击指令吗——征战平原的霜狼突击队队长还在等着发动进攻呢！去吧！', `FemaleText_loc5`='你怎麼在這兒，$n?你怎麼到這兒來啦?$B$B你不是帶著攻擊指令嗎─征戰平原的霜狼突擊隊隊長還在等著發動進攻呢!去吧!', `FemaleText_loc7`='¿Qué haces aquí, $n? ¿Tienes plomo en las botas?$B$BTienes las órdenes de asalto, el maestro de guerra Garrick las necesita en la Tierra de Disputa para poder lanzar el asalto. ¡Vete!' WHERE `ID`=8988;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n, 알터랙 계곡에서 자네처럼 노련한 용사를 만나게 돼서 반갑네. 우린 보급품이 너무 적어서 알터랙 계곡에 대한 지상 공격을 펼칠 수 없는 상태일세. 우리 병참장교와 얘기해 보게. 보급품 물량을 늘리는 방법을 가르쳐 줄 걸세.', `FemaleText_loc4`='能在奥特兰克山谷找到你这样经验丰富的家伙真好，$n。我们的军需不够，无法发动对奥特兰克山谷的地面攻击……跟我们的军需官谈谈——他会告诉你如何增加我们的军需储备。', `FemaleText_loc5`='能在奧特蘭克山谷找到你這樣經驗豐富的傢伙真好，$n。我們的軍需不夠，無法發動對奧特蘭克山谷的地面攻擊...跟我們的軍需官談談─他會告訴你如何增加我們的軍需儲備。', `FemaleText_loc7`='Me alegra tener a veteranos como tú en el Valle de Alterac, $n. Nuestros suministros son demasiado escasos para lanzar un asalto terrestre en el Valle de Alterac... Vete a hablar con el intendente, te dirá como aumentar nuestros suministros.' WHERE `ID`=8989;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어서 와! 보급품은 충분하고 투쟁의 벌판으로 지상 공격을 감행할 준비도 완료됐어. 전장에서 자네가 이름을 좀 더 날렸더라면 내가 믿고 공격명령서 전달을 맡겼을 텐데...$B$B그러니 지금은 가서 얼라이언스와 싸우도록! 자네가 능력 있고 믿을 수 있는 호드의 일원이라는 걸 입증해 보이란 말이야!', `FemaleText_loc4`='嗨，$c！我们的军需已经增加，现在可以对征战平原发送地面攻击啦。要是你的声望再高一点，我一定会派你传达攻击命令的。$B$B去吧，为了联盟而战！证明你是一名值得信赖的、有能力的部落成员！', `FemaleText_loc5`='嗨，$c!我們的軍需已經增加，現在可以對征戰平原發送地面攻擊啦。要是你的聲望再高一點，我一定會派你傳達攻擊命令的。$B$B去吧，為了聯盟而戰!證明你是一名值得信賴的、有能力的部落成員!', `FemaleText_loc7`='¡Saludos, $c! Nuestro nivel de suministros es alto y estamos listos para lanzar un asalto terrestre en la Tierra de Disputa. Quizás, si tu reputación fuera mejor, te confiaría la misión de entregar las órdenes de asalto.$B$B¡Sal ahí fuera y lucha por la Alianza! ¡Demuéstrame que eres un miembro de la Horda capaz en quien se puede confiar!' WHERE `ID`=8990;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이봐! $n! 그렇게 마을을 어슬렁거리고 다니면서 뭐 하는 거지? 지금 알터랙 계곡에 얼라이언스 놈들이 쳐들어왔단 말이야! 반드시 놈들을 몰아내야 해!$B$B그런데 보급품이 턱없이 모자라 대규모 지상 공격은 꿈도 못꾸니 이렇게 안타까울 데가... 서리늑대 병참장교와 얘기를 나눠 보게. 어떻게 하면 보급품을 늘릴 수 있는지 방법을 가르쳐 줄 거야.', `FemaleText_loc4`='你！$n！你在山谷这儿游荡什么呢？在奥特兰克到处都是联盟的敌人！我们必须赶走它们！$B$B我们的军需不够，无法发动大规模的地面攻击,跟我们的军需官谈谈.他会告诉你如何增加我们的军需。', `FemaleText_loc5`='你!$n!你在山谷這兒遊蕩什麼呢?在奧特蘭克到處都是聯盟的敵人!我們必須趕走它們!$B$B我們的軍需不夠，無法發動大規模的地面攻擊,跟我們的軍需官談談。他會告訴你如何增加我們的軍需。', `FemaleText_loc7`='¡Tú! ¡$n! ¿Qué haces dando un paseo por la aldea? ¡Hay enemigos de la Alianza en Alterac! ¡Tenemos que expulsarlos de allí!$B$BTenemos muy pocos suministros para lanzar un asalto terrestre a gran escala, vete a hablar con nuestro intendente. Te dirá cómo aumentar nuestros suministros.' WHERE `ID`=8991;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아무리 용감한 전사라도 보급품을 충분히 지급받아야 제대로 힘을 내서 적과 싸울 수 있는 법이지!', `FemaleText_loc4`='在面对强大的敌人时，即使是最勇敢的士兵也必须拥有充足的装备！', `FemaleText_loc5`='在面對強大的敵人時，即使是最勇敢的士兵也必須擁有充足的裝備!', `FemaleText_loc7`='Incluso el guerrero más valiente necesita suministros si quiere enfrentarse con fuerza a sus enemigos.' WHERE `ID`=8993;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방금 $n에게 사살 승인을 내렸소.', `MaleText_loc4`='我刚把击杀荣誉给$n。', `MaleText_loc5`='我剛把擊殺榮譽給$n。', `MaleText_loc7`='Acabo de darle crédito de esta muerte a $n.' WHERE `ID`=8994;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부활 후유증을 치유하고 모든 장비를 수리하려면 여기를 클릭하십시오.', `MaleText_loc4`='单击此处消除复活效果并修理所有装备', `MaleText_loc5`='單擊此處消除復活效果並修理所有裝備', `MaleText_loc7`='Haz clic aquí para eliminar los efectos de resurrección y reparar el equipamiento.', `FemaleText_loc1`='부활 후유증을 치유하고 모든 장비를 수리하려면 여기를 클릭하십시오.', `FemaleText_loc4`='单击此处消除复活s效果并修理所有装备', `FemaleText_loc5`='單擊此處消除復活效果並修理所有裝備', `FemaleText_loc7`='Haz clic aquí para eliminar los efectos de resurrección y reparar el equipamiento.' WHERE `ID`=8995;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요! 부활 후유증은 여기서 치유하세요!', `MaleText_loc4`='嗨！取消你的抵抗魔法！', `MaleText_loc5`='嗨!取消你的抵抗魔法!', `MaleText_loc7`='¡Hola! Puedes eliminar tus efectos de resucitación aquí.' WHERE `ID`=8996;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모든 장비를 수리하려면 여기를 클릭하십시오.', `MaleText_loc4`='单击此处修理装备', `MaleText_loc5`='單擊此處修理裝備', `MaleText_loc7`='Haz clic aquí para reparar tu equipamiento.', `FemaleText_loc1`='모든 장비를 수리하려면 여기를 클릭하십시오.', `FemaleText_loc4`='单击此处修理装备', `FemaleText_loc5`='單擊此處修理裝備', `FemaleText_loc7`='Haz clic aquí para reparar tu equipamiento.' WHERE `ID`=8997;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지상 공격을 펼칠 보급품이 충분히 있으니, 명령서를 전달하길 원하고 또 자신이 그럴 자격이 충분히 있다고 생각되거든 야즈라 블러드스날 하사관과 얘기를 나눠 보시오.', `MaleText_loc4`='我们拥有足够的物资来发动地面攻击啦。如果你认为自己够资格传达指令的话，就跟亚斯拉·血矛谈谈。', `MaleText_loc5`='我們擁有足夠的物資來發動地面攻擊啦。如果你認為自己夠資格傳達指令的話，就跟亞斯拉·血矛談談。', `MaleText_loc7`='Tenemos suficientes suministros para lanzar un asalto terrestre. Si quieres dar la orden y crees que puedes hacerlo, habla con el sargento Yazra Gruñido Sangriento.' WHERE `ID`=8998;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지상 공격을 펼칠 보급품이 충분히 있으니, 명령서를 전달하길 원하고 또 자신이 그럴 자격이 충분히 있다고 생각되거든 노레그 스톰파이크 하사관과 얘기를 나눠 보시오.', `MaleText_loc4`='我们拥有足够的物资来发动地面攻击啦。如果你认为自己够资格传达指令的话，就跟诺雷格·雷矛中尉谈谈。', `MaleText_loc5`='我們擁有足夠的物資來發動地面攻擊啦。如果你認為自己夠資格傳達指令的話，就跟諾雷格·雷矛下士談談。', `MaleText_loc7`='Tenemos suficientes suministros para lanzar un asalto terrestre. Si quieres dar la orden y crees que puedes hacerlo, habla con el cabo Noreg Pico Tormenta.' WHERE `ID`=8999;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 서리늑대 부족의 신병 모집을 담당하고 있네. 서리늑대 부족의 일원이라면 계급이 오를 때마다 나를 찾아와야 하지.$B$B명예와 존경은 이렇게 혹독한 추위 속에서 얻을 수 있는 것이야.', `MaleText_loc4`='我负责霜狼氏族的军队招募工作。作为一名霜狼士兵，如果你的等级足够高的话，就来向我报到吧。$B$B在冰冷的战场上，你会获得荣誉和尊重的。', `MaleText_loc5`='我負責霜狼氏族的軍隊招募工作。作為一名霜狼士兵，如果你的等級足夠高的話，就來向我報到吧。$B$B在冰冷的戰場上，你會獲得榮譽和尊重的。', `MaleText_loc7`='Estoy a cargo del reclutamiento para el clan Lobo Gélido. Como Soldado de Lobo Gélido, es tu responsabilidad venir a informarme según avances en tu clasificación dentro del clan.$B$BEn este campo gélido se gana honor y respeto.' WHERE `ID`=9000;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투대장님, 계급장을 잃어버렸습니다. 새로 하나 지급해주시겠어요?', `MaleText_loc4`='队长，我把徽章弄丢了。你能再给我一枚吗？', `MaleText_loc5`='隊長，我把徽記弄丟了。你能再給我一枚嗎?', `MaleText_loc7`='Maestro de guerra, he perdido mi insignia. ¿Podrías darme otra?', `FemaleText_loc1`='전투대장님, 계급장을 잃어버렸습니다. 새로 하나 지급해주시겠어요?', `FemaleText_loc4`='队长，我把徽章弄丢了。你能再给我一枚吗？', `FemaleText_loc5`='隊長，我把徽記弄丟了。你能再給我一枚嗎?', `FemaleText_loc7`='Maestro de guerra, he perdido mi insignia. ¿Podrías darme otra?' WHERE `ID`=9001;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오시오, 용맹한 $r 친구! 나는 스톰파이크 경비대의 신병 모집을 담당하고 있는 부관 해거딘이라 하오.$B$B스톰파이크 경비대 내에서 신망과 명성을 얻으면 새 계급장을 달아줄 테니 날 찾아오도록 하시오. 만약 계급장을 잃어버리는 일이 생기면 새로 지급해 주도록 하겠소.', `MaleText_loc4`='你好，$r！我是哈格丁中尉，是负责招募雷矛卫兵的官员。$B$B你在雷矛军队中获得一定的威望后再来找我吧，我会升级你的徽章的。如果你丢失了徽章，我也能再给你一枚。', `MaleText_loc5`='你好，$r!我是哈格丁中尉，是負責招募雷矛衛隊的官員。$B$B你在雷矛中獲得一定的威望後再來找我吧，我會升級你的徽記的。如果你丟失了徽記，我也能再給你一枚。', `MaleText_loc7`='¡Saludos, $r! Soy el teniente Haggerdin, oficial a cargo del reclutamiento de la Guardia Pico Tormenta.$B$BSegún vayas obteniendo prestigio y notoriedad dentro del clan, ven a hablar conmigo y veremos lo que puedo hacer para mejorar tu insignia. Si alguna vez pierdes tu insignia, podré darte una de repuesto.' WHERE `ID`=9002;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부관님, 계급장을 잃어버렸습니다. 새로 하나 지급해 주시겠습니까?', `MaleText_loc4`='副官，我丢失了我的徽章。你能再给我一枚吗？', `MaleText_loc5`='中尉，我丟失了我的徽記。你能再給我一枚嗎?', `MaleText_loc7`='Teniente, he perdido mi insignia. ¿Podrías darme otra?', `FemaleText_loc1`='부관님, 계급장을 잃어버렸습니다. 새로 하나 지급해 주시겠습니까?', `FemaleText_loc4`='副官，我丢失了我的徽章。你能再给我一枚吗？', `FemaleText_loc5`='中尉，我丟失了我的徽記。你能再給我一枚嗎?', `FemaleText_loc7`='Teniente, he perdido mi insignia. ¿Podrías darme otra?' WHERE `ID`=9003;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='홀의 양쪽 부분을 모두 찾았습니다.', `MaleText_loc4`='我已经找到节杖的两个部分啦。', `MaleText_loc5`='我已經找到權杖的兩個部分啦。', `MaleText_loc7`='He encontrado ambas partes de tu cetro.', `FemaleText_loc1`='홀의 양쪽 부분을 모두 찾았습니다.', `FemaleText_loc4`='我已经找到节杖的两个部分啦。', `FemaleText_loc5`='我已經找到權杖的兩個部分啦。', `FemaleText_loc7`='He encontrado ambas partes de tu cetro.' WHERE `ID`=9004;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으아악! 도와주세요!', `MaleText_loc4`='啊，我需要帮助！', `MaleText_loc5`='啊，我需要幫助!', `MaleText_loc7`='¡Aah, necesito ayuda!' WHERE `ID`=9005;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1을;를; 조심하세요!', `MaleText_loc4`='小心$n！', `MaleText_loc5`='小心$n!', `MaleText_loc7`='¡Cuidado con el $n!' WHERE `ID`=9006;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 옵니다! 정신들 바짝 차리세요!', `MaleText_loc4`='$n来了——留神，我的朋友！', `MaleText_loc5`='進來$n─快點，朋友!', `MaleText_loc7`='$n aproximándose. ¡Atentos, amigos!' WHERE `ID`=9007;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 날 거역한 걸 후회하도록 만들어주마.', `MaleText_loc4`='你会后悔遇见我的，$n。', `MaleText_loc5`='你會後悔遇見我的，$n。', `MaleText_loc7`='Te arrepentirás del día que te interpusiste en mi camino, $n.' WHERE `ID`=9008;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 선조들은 개개인의 힘도 강해야 하지만 힘을 합칠수록 더욱 안전하다고 가르치셨지. 길드를 조직해 썬더 블러프의 명예를 수호할 생각이 있나?', `MaleText_loc4`='我们的祖先教诲说，集体的力量胜过个人的力量。你想要加入公会为了雷霆崖的荣誉而战吗？', `MaleText_loc5`='我們的祖先教誨說，集體的力量勝過個人的力量。你想要加入公會為了雷霆崖的榮譽而戰嗎?', `MaleText_loc7`='Nuestros ancestros nos han enseñado que, aunque los individuos deben ser fuertes, la seguridad está en los grupos grandes. ¿Quieres defender el honor de Cima del Trueno organizando una hermandad?' WHERE `ID`=9009;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 지도자의 면모를 갖춘 분이시로군요. 얼라이언스를 위해 싸울 길드를 조직하려고 여기를 찾으셨나요?', `MaleText_loc4`='是的，你看起来是个领导者。你是来这里组织公会与联盟作战吗？', `MaleText_loc5`='是的，你看起來是個領導者。你是來這裡組織公會與聯盟作戰嗎?', `MaleText_loc7`='Sí, creo que serías un buen líder. ¿Estás aquí para organizar una hermandad que luche por la Alianza?' WHERE `ID`=9010;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넘어가지 않겠다!', `MaleText_loc4`='我不会受到引诱离开的！', `MaleText_loc5`='我不會受到引誘離開的!', `MaleText_loc7`='¡No saldré de aquí!' WHERE `ID`=9011;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='셴툴, 호루라기를 잃어버렸는데다가 섬광탄포가 모자랍니다. 도와주세요!', `MaleText_loc4`='申苏尔，我丢了我的哨子，也没有信号枪啦。请帮帮我！', `MaleText_loc5`='申蘇爾，我丟了我的哨子，也沒有信號槍啦。請幫幫我!', `MaleText_loc7`='Shenthul, he perdido mi silbato y no me quedan bengalas. Por favor, necesito ayuda.', `FemaleText_loc1`='셴툴, 호루라기를 잃어버렸는데다가 섬광탄포가 모자랍니다. 도와주세요!', `FemaleText_loc4`='申苏尔，我丢了我的哨子，也没有信号枪啦。请帮帮我！', `FemaleText_loc5`='申蘇爾，我丟了我的哨子，也沒有信號槍啦。請幫幫我!', `FemaleText_loc7`='Shenthul, he perdido mi silbato y no me quedan bengalas. Por favor, necesito ayuda.' WHERE `ID`=9012;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하신가, $c. 나는 로카로라고 하네.', `MaleText_loc4`='你好，$c。我是罗卡鲁。', `MaleText_loc5`='你好，$c。我是部落的勇士羅卡洛，是索爾的僕人，是野獸與野性之王。', `MaleText_loc7`='Bien hecho, $c. Soy Rokaro.' WHERE `ID`=9013;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로카로, 비룡불꽃 아뮬렛을 잃어버렸습니다. 하나 더 만들어 줄 수 있습니까?', `MaleText_loc4`='罗卡鲁，我丢了龙火护符。你能再给我一个吗？', `MaleText_loc5`='羅卡洛，我丟了龍火護符。你能再給我一個嗎?', `MaleText_loc7`='Rokaro, he perdido el amuleto Pirodraco. ¿Se podría crear otro?', `FemaleText_loc1`='로카로, 비룡불꽃 아뮬렛을 잃어버렸습니다. 하나 더 만들어 줄 수 있습니까?', `FemaleText_loc4`='罗卡鲁，我丢了龙火护符。你能再给我一个吗？', `FemaleText_loc5`='羅卡洛，我丟了龍火護符。你能再給我一個嗎?', `FemaleText_loc7`='Rokaro, he perdido el amuleto Pirodraco. ¿Se podría crear otro?' WHERE `ID`=9014;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='푸른용군단에 무슨 청을 하러 오셨나요?', `FemaleText_loc4`='你向蓝龙要求什么？', `FemaleText_loc5`='你向藍龍軍團要求什麼?', `FemaleText_loc7`='¿Qué quieres saber sobre el Vuelo Azul?' WHERE `ID`=9015;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헬레, 비룡불꽃 아뮬렛을 잃어버렸습니다. 하나 더 만들어 줄 수 있습니까?', `MaleText_loc4`='哈尔琳，我把龙火护符弄丢了。你能帮我再做一个吗？', `MaleText_loc5`='哈爾琳，我把龍火護符弄丟了。你能幫我再做一個嗎?', `MaleText_loc7`='Haleh, he perdido mi Amuleto Picodraco. ¿Podrías hacerme otro?', `FemaleText_loc1`='헬레, 비룡불꽃 아뮬렛을 잃어버렸습니다. 하나 더 만들어 줄 수 있습니까?', `FemaleText_loc4`='哈尔琳，我把龙火护符弄丢了。你能帮我再做一个吗？', `FemaleText_loc5`='哈爾琳，我把龍火護符弄丟了。你能幫我再做一個嗎?', `FemaleText_loc7`='Haleh, he perdido mi Amuleto Picodraco. ¿Podrías hacerme otro?' WHERE `ID`=9016;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네싱워리 님께서는 큰 놈을 잡을 준비를 하고 계십니다. 사실 전 전투보다는 사냥 준비를 돕는 게 훨씬 더 마음 편하더군요... 가끔 전장의 영광스럽던 순간들이 그립긴 하지만 말입니다.', `MaleText_loc4`='奈辛瓦里要出去狩猎。我发现帮助他做丛林狩猎的准备工作比做战争准备的工作轻松多了。尽管我错过了战场上的光辉岁月。', `MaleText_loc5`='奈辛瓦里要出去狩獵。我發現幫助他做叢林狩獵的準備工作比做戰爭準備的工作輕鬆多了。儘管我錯過了戰場上的光輝歲月。', `MaleText_loc7`='Al maestro Nesingwary le espera una gran cacería. Encuentro mucho más relajante ayudarle a prepararse para un día en la jungla, que para el combate. Aunque echo de menos algunos de esos momentos gloriosos en el campo de batalla.' WHERE `ID`=9017;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바닐, 제1장을 어디다 두었는지 잊어버린 거 같습니다.', `MaleText_loc4`='巴尼尔，我好像把第一章给弄丢了。', `MaleText_loc5`='巴尼爾，我好像把第一章給弄丟了。', `MaleText_loc7`='Barnil, creo que he perdido el capítulo I.', `FemaleText_loc1`='바닐, 제1장을 어디다 두었는지 잊어버린 거 같습니다.', `FemaleText_loc4`='巴尼尔，我好像把第一章给弄丢了。', `FemaleText_loc5`='巴尼爾，我好像把第一章給弄丟了。', `FemaleText_loc7`='Barnil, creo que he perdido el capítulo I.' WHERE `ID`=9018;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바닐, 제2장을 어디다 두었는지 잊어버린 거 같습니다.', `MaleText_loc4`='巴尼尔，我好像把第二章给弄丢了。', `MaleText_loc5`='巴尼爾，我好像把第二章給弄丟了。', `MaleText_loc7`='Barnil, creo que he perdido el capítulo II.', `FemaleText_loc1`='바닐, 제2장을 어디다 두었는지 잊어버린 거 같습니다.', `FemaleText_loc4`='巴尼尔，我好像把第二章给弄丢了。', `FemaleText_loc5`='巴尼爾，我好像把第二章給弄丟了。', `FemaleText_loc7`='Barnil, creo que he perdido el capítulo II.' WHERE `ID`=9019;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바닐, 제3장을 어디다 두었는지 잊어버린 거 같습니다.', `MaleText_loc4`='巴尼尔，我好像把第三章给弄丢了。', `MaleText_loc5`='巴尼爾，我好像把第三章給弄丟了。', `MaleText_loc7`='Barnil, creo que he perdido el capítulo III.', `FemaleText_loc1`='바닐, 제3장을 어디다 두었는지 잊어버린 거 같습니다.', `FemaleText_loc4`='巴尼尔，我好像把第三章给弄丢了。', `FemaleText_loc5`='巴尼爾，我好像把第三章給弄丟了。', `FemaleText_loc7`='Barnil, creo que he perdido el capítulo III.' WHERE `ID`=9020;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바닐, 제4장을 어디다 두었는지 잊어버린 거 같습니다.', `MaleText_loc4`='巴尼尔，我好像把第四章给弄丢了。', `MaleText_loc5`='巴尼爾，我好像把第四章給弄丟了。', `MaleText_loc7`='Barnil, creo que he perdido el capítulo IV.', `FemaleText_loc1`='바닐, 제4장을 어디다 두었는지 잊어버린 거 같습니다.', `FemaleText_loc4`='巴尼尔，我好像把第四章给弄丢了。', `FemaleText_loc5`='巴尼爾，我好像把第四章給弄丟了。', `FemaleText_loc7`='Barnil, creo que he perdido el capítulo IV.' WHERE `ID`=9021;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 그렇게도 열심히 구해 온 걸 잃어버렸다니 어이가 없군요. 아니, 여기다 두었군요!', `MaleText_loc4`='我看到你将辛辛苦苦拼好的篇章随意乱放，$n。嗯，就放在那儿！', `MaleText_loc5`='我看到你將辛辛苦苦拼好的篇章隨意亂放，$n。嗯，就放在那兒!', `MaleText_loc7`='Veo que has perdido ese capítulo que tanto trabajo te costó preparar, $n. ¡Lo habías dejado justo aquí!' WHERE `ID`=9022;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼라란, 횃불에 주문을 걸어 주시기 바랍니다.', `MaleText_loc4`='卡拉然，请为火炬附魔。', `MaleText_loc5`='卡拉然，請為火炬附魔。', `MaleText_loc7`='Kalaran, encanta la antorcha, por favor.', `FemaleText_loc1`='칼라란, 횃불에 주문을 걸어 주시기 바랍니다.', `FemaleText_loc4`='卡拉然，请为火炬附魔。', `FemaleText_loc5`='卡拉然，請為火炬附魔。', `FemaleText_loc7`='Kalaran, encanta la antorcha, por favor.' WHERE `ID`=9023;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전 이 숲을 제 몸의 한 부분처럼 속속들이 다 알고 있답니다. 하지만, 아직도 숲에는 배워야 할 것들이 더 많고 수많은 위험 또한 도사리고 있습니다.', `FemaleText_loc4`='我对这片森林非常熟悉，它们就像我身体的一部分……但是它们还蕴藏着很多值得学习的知识，当然也有很多危险。', `FemaleText_loc5`='我對這片森林非常熟悉，它們就像我自己的身體一樣...但是它們依然隱藏著很多值得學習的知識，當然也隱藏著很多危險。', `FemaleText_loc7`='Conozco estos bosques como si fueran parte de mí... pero has de saber que todavía pueden enseñarnos mucho, y aún hay muchos peligros ocultos.' WHERE `ID`=9024;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='레이네, 다르톨의 변신마법봉을 잃어버렸습니다.', `MaleText_loc4`='莱恩，我把达图尔的变形魔棒弄丢了。', `MaleText_loc5`='萊恩，我把達圖爾的變形魔棒弄丟了。', `MaleText_loc7`='Raene, he perdido la Vara de la Transformación de Dartol.', `FemaleText_loc1`='레이네, 다르톨의 변신마법봉을 잃어버렸습니다.', `FemaleText_loc4`='莱恩，我把达图尔的变形魔棒弄丢了。', `FemaleText_loc5`='萊恩，我把達圖爾的變形魔棒弄丟了。', `FemaleText_loc7`='Raene, he perdido la Vara de la Transformación de Dartol.' WHERE `ID`=9025;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네, 당신이 돌아오리라 예상하고 있었습니다. 내가 코라를 좀 일찍 보내 버려진 숲에서 다르톨의 마법봉을 찾아냈습니다.$B$B우리는 마법봉을 되찾기 위해서 매우 힘들게 노력했습니다, $n. 추후에 마법봉을 부주의하게 다루지 않도록 조심하시길 바랍니다.', `FemaleText_loc4`='是的，我曾盼望你能回来。早些时候，我派科兰出去，她发现了达图尔的魔棒被遗弃在森林里。$B$B我们竭力想要找回它，$n。请你小心以后不要掉了它。', `FemaleText_loc5`='是的，我曾盼望你能回來。早些時候，我派科蘭出去，她發現了達圖爾的魔棒被遺棄在森林裡。$B$B我們竭力想要找回它，$n。請你小心以後不要掉了它。', `FemaleText_loc7`='Sí, esperaba que regresaras. Hace un rato, envié a Khorra a hacer un recado y se encontró con la Vara de Dartol, abandonado en el bosque.$B$BNos ha costado tanto recuperarlo, $n. Por favor, cuídalo mejor en el futuro.' WHERE `ID`=9026;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신은 테로니스의 임무를 완수해 주었군요. 임무를 완수하는 동안 해낸 모든 일에 감사드립니다, $n.', `FemaleText_loc4`='你已经完成了泰洛尼斯的任务，感谢你所做的一切，$n。', `FemaleText_loc5`='你已經完成了泰洛尼斯的任務，感謝你所做的一切，$n。', `FemaleText_loc7`='Has completado la misión de Teronis, y aprecio mucho todo lo que has hecho, $n.' WHERE `ID`=9027;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요! 지금 이 작업장의 주인은 제가 아니지만 언젠가 수련을 마치고 훌륭한 발명가가 될 거랍니다. 제 영웅이신 마본 리벳시커씨처럼 말이죠.$B$B들어본 적도 없다고요? 그럴 수도 있겠죠. 얼마 전 늘 말씀하시던 어느 고대 트롤의 유적지를 조사하러 떠났거든요. 비행선을 타고 갔는데... 정확히 어디로 갔는지는 잘 모르겠어요.$B$B타나라신? 텡케리스? 타네라니사니?$B$B<고개를 가로 흔드는 리브>$B$B아니, 그게 아닌데...', `FemaleText_loc4`='你好！这间工场不是我的，不是！但是终有一天当我完成训练后，我将成为一名发明家，就像我崇拜的英雄玛尔冯·瑞文斯克那样。$B$B你从来没有听说过他吗？哦，碰巧他已经离开好长一段日子啦，他去研究远古巨魔废墟啦，他是乘坐地精飞艇走的……我也不是很清楚他究竟去了哪儿……$B$B塔纳拉辛？坦克利斯？塔纳里萨尼？$B$B<莉芙摇着头。>$B$B不，名字不是这样……', `FemaleText_loc5`='你好!這間工廠不是我的，不是!但是終有一天當我完成訓練後，我將成為一名發明家，就像我崇拜的英雄瑪爾馮·瑞文斯克那樣。$B$B你從來沒有聽說過他嗎?哦，碰巧他已經離開好長一段日子啦，他去研究遠古食人妖廢墟啦，他是乘坐地精飛艇走的...我也不是很清楚他究竟去了哪兒...$b$b塔納拉辛?坦克利斯?塔納里薩尼?$B$B<莉芙搖著頭。>$B$B不，名字不是這樣...', `FemaleText_loc7`='¡Hola! Este taller no es mío, no. Pero, algún día, cuando finalice mi instrucción, voy a ser una inventora, como mi héroe, Marvon Buscarroblones.$B$B¿Has oído hablar de él? Pues resulta que se fue hace algún tiempo para estudiar unas antiguas ruinas trol de las que no dejaba de hablar. Se fue en un zepelín... Aunque no tengo muy claro dónde exactamente...$B$B¿Tanarasin? ¿Tenkeris? ¿Taneranisany?$B$B<Liv niega con la cabeza.>$B$BNo, no era así...' WHERE `ID`=9028;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요. 애석하게도 마본씨는 여기 안 계세요. 앞으로 한동안은 돌아오지 않을 거예요. 사실 좀 걱정되기는 해요...$B$B빨리 오셨으면 좋겠어요. 마본씨 앞으로 웬 커다란 궤짝이 하나 왔는데 도저히 제 힘으로는 안으로 가져올 수가 없어서 밖에 문 옆에다 뒀답니다.', `FemaleText_loc4`='嗨。不，玛尔冯一定不在这儿，他还要好些时间才能回来呢。实际上，我有些担心他……$B$B我希望他能很快回来。有人寄了一只大箱子给他，我可没力气把这东西拖进去！我只能把它放在门口……', `FemaleText_loc5`='嗨。不，瑪爾馮一定不在這兒，他還要好些時間才能回來呢。實際上，我有些擔心他...$b$b我希望他能很快回來。有人寄了一隻大箱子給他，我可沒力氣把這東西拖進去!我只能把它放在門口...', `FemaleText_loc7`='Eh, hola. No, Marvon no está aquí y no volverá hasta dentro de mucho. De hecho, estoy empezando a preocuparme...$B$BEspero que vuelva pronto. Llegó un gran cofre para él y es demasiado pesado para mí, no puedo meterlo dentro. He tenido que dejarlo fuera, al lado de la puerta...' WHERE `ID`=9029;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 이번에 내가 가르쳐 줄 수 있는 모든 것을 배웠습니다, 의사 양반. 당신의 기술이 발전했을 때 내게 돌아오면 내가 좀 더 고급의 응급치료 기술을 가르쳐 주도록 하겠습니다.', `MaleText_loc4`='你已经学会了我现在能教你的所有知识，$n医生。当你获得更多经验的时候再来找我吧，我会传授给你更多高级的医学知识的。', `MaleText_loc5`='你已經學會了我現在能教你的所有知識，$n醫生。當你獲得更多經驗的時候再來找我吧，我會傳授給你更多高級的醫學知識的。', `MaleText_loc7`='Has aprendido todo lo que puedo enseñarte por el momento, doctor $n. Vuelve a verme cuando tengas más experiencia y te enseñaré una medicina más avanzada.' WHERE `ID`=9030;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도망쳐라! 그들이 오고 있다!', `MaleText_loc4`='快跑！他们来了！', `MaleText_loc5`='快跑!他們來了!', `MaleText_loc7`='¡Corred! ¡Se están acercando!', `FemaleText_loc1`='도망쳐라! 그들이 오고 있다!', `FemaleText_loc4`='快跑！他们来了！', `FemaleText_loc5`='快跑!他們來了!', `FemaleText_loc7`='¡Corred! ¡Se están acercando!' WHERE `ID`=9031;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이곳은... 오염되었어요.$B$B전 간신히 탈출했지만 도저히 다시 굴을 통과해서 내려가질 못하겠네요.$B$B제 형제와 자매들은... 운이 좋지 못했답니다. 내부에 있는 덫 때문에, 그들은 그곳에 자라는 악마의 정원에서 흘러나온 타락한 기운이 깃든 안개로 제정신이 아니에요.$B$B당신이 우리를 도와줘야만 합니다.', `FemaleText_loc4`='这地方……受到了诅咒。$B$B我刚刚设法逃脱，我可不想再进入那些地道啦。$B$B但是，我的兄弟姐妹……就没这么幸运了。他们被困在里面，恶魔花园散发的堕落烟雾令他们疯狂。$B$B你一定要帮帮他们。', `FemaleText_loc5`='這地方...受到了詛咒。$B$B我剛剛設法逃脫，我可不想再進入那些地道啦。$B$B但是，我的兄弟姐妹...就沒這麼幸運了。他們被困在裡面，惡魔花園散發的墮落煙霧令他們瘋狂。$B$B你一定要幫幫他們。', `FemaleText_loc7`='Este lugar... está maldito.$B$BConseguí escapar por los pelos, y no puedo soportar la idea de tener que volver a bajar a esos túneles.$B$BMi hermano y mis hermanas, sin embargo... No tuvieron tanta suerte. Atrapados dentro, han sido contaminados por la bruma corrupta que emana del jardín malvado.$B$BPor favor, tienes que ayudarnos.' WHERE `ID`=9032;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오, $n! 당신이 돌아와서 무척 기쁘군요.$B$B제 형제의 영혼은 이제 오염에서 해방되었지만 전 애도의 뜻에서 이곳에 남기로 했습니다.$B$B당신의 도움에 깊이 감사드립니다.', `FemaleText_loc4`='哦，很高兴你已经回来啦，$n。$B$B我兄弟的灵魂已经从堕落中解脱啦，但是我得留在此地表示我的哀悼。$B$B非常感谢你的帮助，$n。', `FemaleText_loc5`='哦，很高興你已經回來啦，$n。$B$B我兄弟的靈魂已經從墮落中解脫啦，但是我得留在此地表示我的哀悼。$B$B非常感謝你的幫助，$n。', `FemaleText_loc7`='Oh, me alegro tanto de que hayas vuelto, $n.$B$BEl espíritu de mi hermano está libre de la corrupción, pero he decidido quedarme aquí, llorando.$B$BMuchísimas gracias por tu ayuda, $n.' WHERE `ID`=9033;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자다! 훼방꾼이다! 천리안을 도둑맞았다! 저 비열한 $n 녀석이 천리안을 가지고 있다! 잡아라!', `MaleText_loc4`='入侵者！入侵者！全视之眼被偷了！可耻的$n偷走了它！', `MaleText_loc5`='入侵者!入侵者!全視之眼被偷啦!可憐的$r傢伙，$n，就是$g他:她;!', `MaleText_loc7`='¡Intrusos! ¡Invasores! ¡Han robado al Ojo que todo lo ve! ¡El maldito $n lo tiene en su poder!' WHERE `ID`=9034;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='보급품이 필요하십니까?', `FemaleText_loc4`='需要物资供给吗？', `FemaleText_loc5`='需要物資供給嗎?', `FemaleText_loc7`='¿Necesitas más suministros?' WHERE `ID`=9036;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무엇을 팔고 있는지 보여 주십시오.', `MaleText_loc4`='你有什么要出售的东西？', `MaleText_loc5`='讓我看看你出售的東西。', `MaleText_loc7`='Muéstrame lo que tienes a la venta.', `FemaleText_loc1`='무엇을 팔고 있는지 보여 주십시오.', `FemaleText_loc4`='你有什么要出售的东西？', `FemaleText_loc5`='讓我看看你出售的東西。', `FemaleText_loc7`='Muéstrame lo que tienes a la venta.' WHERE `ID`=9037;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='콜라크가 왔노라, 나약한 존재들이여! 눈사태 무덤은 겨울도끼 부족의 것이다!', `MaleText_loc4`='科尔拉克来了，懦弱的家伙！一场盛宴就要开始了。来吧！受死吧！', `MaleText_loc5`='科爾拉克來啦，懦弱的傢伙!落雪墓地是屬於冰斧的!', `MaleText_loc7`='¡Korrak ha venido, bastardos! ¡Avalancha pertenece al Hacha Invernal!' WHERE `ID`=9038;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼마나 많은 보급품이 더 필요합니까?', `MaleText_loc4`='我们还需要多少物资供给？', `MaleText_loc5`='我們還需要多少物資供給?', `MaleText_loc7`='¿Cuántos suministros más necesitamos?', `FemaleText_loc1`='얼마나 많은 보급품이 더 필요합니까?', `FemaleText_loc4`='我们还需要多少物资供给？', `FemaleText_loc5`='我們還需要多少物資供給?', `FemaleText_loc7`='¿Cuántos suministros más necesitamos?' WHERE `ID`=9039;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알터랙 계곡 - 얼라이언스 병참장교 인사 옵션 기본', `MaleText_loc4`='奥特兰克山谷——联盟军需官问候默认选项', `MaleText_loc5`='奧特蘭克山谷─聯盟軍需官問候原始設定選項', `MaleText_loc7`='Valle de Alterac: opción predeterminada de saludo al intendente de la Alianza' WHERE `ID`=9040;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지휘관님께서 당하셨다! 돌진! 명예롭게 죽음을 맞이하라!', `MaleText_loc4`='指挥官被杀死啦！冲向他们的战线！为荣耀而死！', `MaleText_loc5`='指揮官被殺死啦!衝向他們的戰線!為榮耀而死!', `MaleText_loc7`='¡El Comandante ha muerto! ¡Cargad contra ellos! ¡Morid con honor!', `FemaleText_loc1`='지휘관님께서 당하셨다! 돌진! 명예롭게 죽음을 맞이하라!', `FemaleText_loc4`='指挥官被杀死啦！冲向他们的战线！为荣耀而死！', `FemaleText_loc5`='指揮官被殺死啦!衝向他們的戰線!為榮耀而死!', `FemaleText_loc7`='¡El Comandante ha muerto! ¡Cargad contra ellos! ¡Morid con honor!' WHERE `ID`=9041;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지휘관께서 쓰러지셨다! 지금은 복수를 위한 시간이다! 산양기병대여, 돌진하라!!!!!!', `MaleText_loc4`='我们的指挥官倒下啦！报仇的时候到啦！山羊骑士们，冲吧！！', `MaleText_loc5`='我們的指揮官倒下啦!報仇的時候到啦!山羊騎士們，衝吧!!', `MaleText_loc7`='Nuestro Comandante ha caído. ¡Ha llegado la hora de la venganza! ¡¡¡¡Jinetes de carneros, cargad!!!!', `FemaleText_loc1`='지휘관께서 쓰러지셨다! 지금은 복수를 위한 시간이다! 산양기병대여, 돌진하라!!!!!!', `FemaleText_loc4`='我们的指挥官倒下啦！报仇的时候到啦！山羊骑士们，冲吧！！', `FemaleText_loc5`='我們的指揮官倒下啦!報仇的時候到啦!山羊騎士們，衝吧!!', `FemaleText_loc7`='Nuestro Comandante ha caído. ¡Ha llegado la hora de la venganza! ¡¡¡¡Jinetes de carneros, cargad!!!!' WHERE `ID`=9042;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='늑대기병들이 적진으로 돌격할 때가 되었습니다. 명령만 내려주십시오.', `MaleText_loc4`='指挥官，是狼骑兵攻击敌人的时候啦。发出指令吧。', `MaleText_loc5`='指揮官，是狼騎兵攻擊敵人的時候啦。發出指令吧。', `MaleText_loc7`='Comandante, ha llegado la hora de que los Caballeros Lobo carguen contra las líneas enemigas. Da la orden.', `FemaleText_loc1`='늑대기병들이 적진으로 돌격할 때가 되었습니다. 명령만 내려주십시오.', `FemaleText_loc4`='指挥官，是狼骑兵攻击敌人的时候啦。发出指令吧。', `FemaleText_loc5`='指揮官，是狼騎兵攻擊敵人的時候啦。發出指令吧。', `FemaleText_loc7`='Comandante, ha llegado la hora de que los Caballeros Lobo carguen contra las líneas enemigas. Da la orden.' WHERE `ID`=9044;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명령 대기 중입니다. 명령만 내리시면 놈들에게 지옥의 유황 맛을 맛보여주겠습니다!', `MaleText_loc4`='等待指令。我将听从你的命令，让那些家伙命丧黄泉！', `MaleText_loc5`='等待指令。我將聽從你的命令，讓那些傢伙命喪黃泉!', `MaleText_loc7`='Esperando órdenes, señor. ¡Cuando des la orden desataré el infierno sobre ellos!' WHERE `ID`=9045;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명령이 떨어졌다! 스톰파이크에 죽음을! 적진으로 돌격!', `MaleText_loc4`='命令已经下达啦！杀死雷矛！向敌人冲锋！', `MaleText_loc5`='命令已經下達啦!殺死雷矛!向敵人衝鋒!', `MaleText_loc7`='¡Órdenes recibidas! ¡Muerte a Pico Tormenta! ¡Cargad contra el enemigo!', `FemaleText_loc1`='명령이 떨어졌다! 스톰파이크에 죽음을! 적진으로 돌격!', `FemaleText_loc4`='命令已经下达啦！杀死雷矛！向敌人冲锋！', `FemaleText_loc5`='命令已經下達啦!殺死雷矛!向敵人衝鋒!', `FemaleText_loc7`='¡Órdenes recibidas! ¡Muerte a Pico Tormenta! ¡Cargad contra el enemigo!' WHERE `ID`=9046;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쓰레기 같은 서리늑대 부족을 공격할 때가 되었습니다! 모두 쓸어버리죠!', `MaleText_loc4`='指挥官，是攻击霜狼的时候啦！杀死他们！', `MaleText_loc5`='指揮官，是攻擊霜狼的時候啦!殺死他們!', `MaleText_loc7`='¡Comandante, ha llegado el momento de cargar contra la escoria Lobo Gélido! ¡Aplastadles!', `FemaleText_loc1`='쓰레기 같은 서리늑대 부족을 공격할 때가 되었습니다! 모두 쓸어버리죠!', `FemaleText_loc4`='指挥官，是攻击霜狼的时候啦！杀死他们！', `FemaleText_loc5`='指揮官，是攻擊霜狼的時候啦!殺死他們!', `FemaleText_loc7`='¡Comandante, ha llegado el momento de cargar contra la escoria Lobo Gélido! ¡Aplastadles!' WHERE `ID`=9047;
