UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명령만 내리시면 기병대를 출격시키겠습니다!', `MaleText_loc4`='听您的命令调遣骑兵，先生！', `MaleText_loc5`='聽您的命令調遣騎兵，先生!', `MaleText_loc7`='¡La caballería cargará cuando des la orden!' WHERE `ID`=9049;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌격!!! 놈들을 밟아 버리자!', `MaleText_loc4`='冲啊！！！杀死他们！', `MaleText_loc5`='衝啊!!!殺死他們!', `MaleText_loc7`='¡¡¡Cargad!!! ¡Aplastadles a todos!', `FemaleText_loc1`='돌격!!! 놈들을 밟아 버리자!', `FemaleText_loc4`='冲啊！！！杀死他们！', `FemaleText_loc5`='衝啊!!!殺死他們!', `FemaleText_loc7`='¡¡¡Cargad!!! ¡Aplastadles a todos!' WHERE `ID`=9050;
