UPDATE `locales_broadcast_text` SET `MaleText_loc1`='병법을 배우러 왔소, $r 친구? 그렇다면 잘못 찾아 왔구려.', `MaleText_loc4`='你是来学习战斗的艺术的，$r？你来错地方了。', `MaleText_loc5`='你是來學習戰鬥的藝術的，$r?', `MaleText_loc7`='¿Has venido a aprender las artes de la guerra, $r? Has venido al lugar equivocado.' WHERE `ID`=9069;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 땅에서 끊임없이 벌어진 승리와 패배의 교훈에 대해 배우러 왔소? 그런데 여기 승자는 없소이다.', `MaleText_loc4`='你是来学习战役案例的吧？听好了，我会为你讲解那些显赫的胜仗和耻辱的败仗的。', `MaleText_loc5`='你是來學習戰役案例的吧?聽好了，我會為你講解那些顯赫的勝仗和恥辱的敗仗的。', `MaleText_loc7`='¿Has venido a aprender sobre las batallas ganadas y perdidas en este campo? Aquí no hay ganadores...' WHERE `ID`=9070;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와라, 조무래기들아! 덤벼라!', `MaleText_loc4`='来吧，小家伙们。面对我！', `MaleText_loc5`='來吧，小子。挑戰我!', `MaleText_loc7`='Vamos, pequeñajos. ¡Luchad conmigo!' WHERE `ID`=9071;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기는 내가 지킨다. 어느 누구도 비전술의 신비를 건드리지 못할 것이다.', `MaleText_loc4`='我保护着这个地方。神秘的奥术不能受到亵渎。', `MaleText_loc5`='我保護著這個地方。神秘的秘法不能受到褻瀆。', `MaleText_loc7`='Este lugar está bajo mi protección. Los misterios arcanos no serán mancillados.' WHERE `ID`=9072;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지나친 호기심은 화를 불러 오게 마련이지.', `MaleText_loc4`='这就是好奇的代价。', `MaleText_loc5`='這就是好奇的代價。', `MaleText_loc7`='Ese es el precio de la curiosidad.' WHERE `ID`=9073;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오시오. 첩보원의 보고에 의하면 서쪽에 있는 겨울도끼 부족 녀석들이 고블린 수석 기술자 하나를 포로로 잡아갔다 하오. 당신이 좀 조사해보지 않겠소?', `MaleText_loc4`='你好，士兵。据报道西边的冰斧巨魔抓走了一名地精工程师。或许你得去调查一下？', `MaleText_loc5`='你好，士兵。據報導西邊的冰斧食人妖抓走了一名哥布林工程師。或許你得去調查一下?', `MaleText_loc7`='Saludos, Soldado. Inteligencia nos ha informado de que los trols Hacha Invernal del oeste, tienen prisionero a un maestro ingeniero goblin. ¿Quizás deberías ir a investigar?' WHERE `ID`=9074;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정찰병들의 보고에 의하면 비밀결사대가 동부 고원 지대에 숨겨진 어떤 동굴에 거처를 정했다고 하는군. 그러니 그 부근에서는 조심하도록 하시오.', `MaleText_loc4`='我的斥候报告说辛迪加在东部平原一处隐秘的洞穴中居住。在你进入这片地区的时候要小心。', `MaleText_loc5`='我的斥候報告說辛迪加在東部平原一處隱秘的洞穴中居住。在你進入這片地區的時候要小心。', `MaleText_loc7`='Mis exploradores me han informado de que la Hermandad tiene una nueva guarida en una cueva oculta de la meseta oriental. Ten cuidado cuando te adentres en esa zona.' WHERE `ID`=9075;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발밑을 조심하시오. 스톰파이크 녀석들이 요새 주변에 지뢰를 깔아놓았어. 그 지뢰를 해제하는 방법에 대해 자세히 알고 싶거든 여기서 동쪽 주둔지에 있는 우리 폭파 전문가와 얘기를 나눠보시오.', `MaleText_loc4`='士兵，谨慎些。雷矛在基地周围埋下了许多地雷。要是你想要进入雷区，就去跟东面了望塔里的爆破专家谈谈。', `MaleText_loc5`='士兵，謹慎些。雷矛在基地周圍埋下了許多地雷。要是你想要進入雷區，就去跟東面瞭望塔里的爆破專家談談。', `MaleText_loc7`='Mira dónde pisas, Soldado. Los Pico Tormenta han plagado de minas terrestres el suelo alrededor de sus bases. Habla con nuestro experto en explosivos en la torre vigía que está al este, si quieres saber cómo desactivar sus campos de minas.' WHERE `ID`=9076;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정신 바짝 차리시오, 제군! 스톰파이크 첩보부의 보고에 의하면 고블린 수석 기술자 하나가 겨울도끼 부족에게 포로로 끌려갔다고 하오. 그런데 서리늑대 놈들이 그를 구출해서 기계를 만들게 해 우리를 치려고 하고 있소! 그런 일이 절대로 일어나서는 안 되지...', `MaleText_loc4`='提起精神，士兵！雷矛智者报告说冰斧巨魔已经抓住了一名地精工程师。霜狼正试图解救他，以便利用他的工程学制品来摧毁我们！可别让这种事情发生。', `MaleText_loc5`='提起精神，士兵!雷矛智者報告說冰斧食人妖已經抓住了一名哥布林工程師。霜狼正試圖解救他，以便利用他的工程學製品來摧毀我們!可別讓這種事情發生。', `MaleText_loc7`='¡Despierta, Soldado! La inteligencia Pico Tormenta nos ha informado de que los trols Hacha Invernal han cogido prisionero a un maestro goblin. Esos perros Lobo Gélido están intentando rescatarle para poder usar sus aparatos y destruirnos. No permitas que ocurra.' WHERE `ID`=9077;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비밀결사대가 동부 고원 지대의 한 동굴에서 은밀히 움직이고 있다는 보고가 들어왔소. 제군, 녀석들이 무슨 수작을 부리려는 것인지 알아오시오! 가는 길에 서리늑대 부족을 조심하도록!', `MaleText_loc4`='据报，辛迪加工会东部平原的一处洞穴人声鼎沸。去看看那儿发生了什么事，士兵！小心霜狼的活动！', `MaleText_loc5`='據報，辛迪加工會東部平原的一處洞穴人聲鼎沸。去看看那兒發生了什麼事，士兵!小心霜狼的活動!', `MaleText_loc7`='Nos han informado de que la Hermandad está en una cueva en la meseta oriental. ¡Descubre lo que están planeando, Soldado! ¡Ten cuidado, es posible que los Lobo Gélido estén por allí!' WHERE `ID`=9078;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서리늑대 부족의 영토에 들어갈 때는 조심하시오. 그 망할 곳은 온통 지뢰가 깔려 있소! 말 그대로 지뢰밭이란 말이오! 더 자세한 얘기는 최전선의 첫 번째 보초탑에 있는 우리 폭파 전문가에게 가서 들으시오. 분명, 이 상황을 어떻게 해결할 것인지 가르쳐줄 것이오.', `MaleText_loc4`='进入霜狼领土时要当心，士兵。这儿到处都是陷阱！还有无数的地雷！跟前线第一座塔楼的爆破专家谈谈。我想他会教你如何处理这些情况的。', `MaleText_loc5`='進入霜狼領土時要當心，士兵。這兒到處都是陷阱!還有無數的地雷!跟前線第一座塔樓的爆破專家談談。我想他會教你如何處理這些情況的。', `MaleText_loc7`='No entres en territorio Lobo Gélido, Soldado. ¡Todo ese maldito lugar está plagado de minas! ¡Un sinfín de minas terrestres! Habla con nuestro experto en explosivos en la primera torre de las primeras líneas para obtener más información. Estoy seguro de que podrá ayudarte con esta situación.' WHERE `ID`=9079;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 지휘관님', `MaleText_loc4`='是的，我有，指挥官。', `MaleText_loc5`='是的，我有，指揮官。', `MaleText_loc7`='Sí, Comandante.', `FemaleText_loc1`='네, 지휘관님', `FemaleText_loc4`='是的，我有，指挥官。', `FemaleText_loc5`='是的，我有，指揮官。', `FemaleText_loc7`='Sí, Comandante.' WHERE `ID`=9080;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 들으시오, $c.$B$B나로부터 퍼져나가는 힘과 사기를 느낄 수 있소? 이미 당신도 충만해 보이는군. 하지만 적도 마찬가지일 거요. 적의 방어선을 붕괴하고 그들의 수를 줄이는 것은 쉬운 임무가 아니지만 반드시 해내야만 하오! 승리는 우리 것이오!', `MaleText_loc4`='那么听好了，$c。$B$B你能感知到从我身上散发出的力量吗？你的士气不够？是的，对另一方来说也是这样。要破坏瓦解他们的军队并不容易，但是必须完成任务！胜利是属于我们的！', `MaleText_loc5`='那麼聽好了，$c。$B$B你能感知到從我身上散發出的力量嗎?你的士氣不夠?是的，對另一方來說也是這樣。要破壞瓦解他們的軍隊並不容易，但是必須完成任務!勝利是屬於我們的!', `MaleText_loc7`='Pues escucha atentamente, $c.$B$B¿Puedes sentir el poder que emana de mí? ¿Acaso no aumenta tu moral? Sí, pues es lo mismo para el enemigo. Destruir sus defensas y disminuir sus tropas no será una tarea fácil, ¡pero hay que hacerlo de todas formas! ¡La victoria será nuestra!' WHERE `ID`=9081;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 누구를 처치해야 합니까? 말씀만 하십시오!', `MaleText_loc4`='要我杀死谁？指挥官，告诉我他们在哪儿。', `MaleText_loc5`='要我殺死誰?指揮官，告訴我他們在哪兒。', `MaleText_loc7`='¿A quién tengo que matar? Solo dime dónde están, Comandante.', `FemaleText_loc1`='제가 누구를 처치해야 합니까? 말씀만 하십시오!', `FemaleText_loc4`='要我杀死谁？指挥官，告诉我他们在哪儿。', `FemaleText_loc5`='要我殺死誰?指揮官，告訴我他們在哪兒。', `FemaleText_loc7`='¿A quién tengo que matar? Solo dime dónde están, Comandante.' WHERE `ID`=9082;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최전선에는 방어를 지휘하는 적의 부대장이 여섯이 있는데, 먼저 그들을 처치해야 하오! 사제들이 쓰러진 놈을 부활시키면 곤란해지니까 속전속결로 끝내 버리시오!$B$B순식간에 부대장을 모두 해치워버리면 최전선의 사기가 떨어지겠지! 전의를 상실한 부대원들은 겁에 질려 도망칠 테고, 그러면 나머지 병사들은 지원군도 없이 싸우다 비참한 죽음을 맞이할 것이오.', `MaleText_loc4`='六名中尉指挥着前线的防御事务。必须迅速解决他们！我们绝不能让他们的任何一名牧师活着逃回去。$B$B要是我们能很快结果掉所有的中尉，前线的士气将大跌！战线也会很快攻破！他们的军队将落荒而逃，留守的士兵将失去后援。', `MaleText_loc5`='六名中尉指揮著前線的防禦事務。必須迅速解決他們!我們絕不能讓他們的任何一名牧師活著逃回去。$B$B要是我們能很快結果掉所有的中尉，前線的士氣將大跌!戰線也會很快攻破!他們的軍隊將落荒而逃，留守的士兵將失去後援。', `MaleText_loc7`='Hay seis Tenientes controlando las defensas de la primera línea. ¡Hay que acabar con ellos rápidamente antes de nada! No podemos permitir que uno de sus sacerdotes resucite a los Tenientes muertos.$B$BSi todos los Tenientes caen rápidamente, la moral de sus tropas decaerá. ¡Será el caos! Sus tropas huirán muertas de miedo y dejarán a los Soldados sin refuerzos.' WHERE `ID`=9083;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그게 다입니까? 더 큰 도전이 기다리고 있을 것이라고 생각했었는데...', `MaleText_loc4`='就这样吗？我以为你会向我挑战。', `MaleText_loc5`='就這樣嗎?我以為你會向我挑戰。', `MaleText_loc7`='¿Eso es todo? Creía que ibas a proponerme un desafío.', `FemaleText_loc1`='그게 다입니까? 더 큰 도전이 기다리고 있을 것이라고 생각했었는데...', `FemaleText_loc4`='就这样吗？我以为你会向我挑战。', `FemaleText_loc5`='就這樣嗎?我以為你會向我挑戰。', `FemaleText_loc7`='¿Eso es todo? Creía que ibas a proponerme un desafío.' WHERE `ID`=9084;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그뿐만이 아니오, $c. 놈들의 요새에 있는 네 명의 지휘관이 정예 부대를 지휘하고 있는데, 그 넷에게 신속하고도 치명적인 타격을 입힐 수만 있다면 제아무리 정예 부대라도 흔들릴 수밖에 없지! 적들의 수는 점점 줄어들어 결국에는 아무도 남지 않게 될 거요.$B$B하지만 지휘관이나 부관은 가벼운 상대는 아닐 것이니 늘 조심해야 하오. 그만한 지위를 얻은 데는 다 이유가 있으니까...', `MaleText_loc4`='不，$c，这并不是全部。敌对阵营的精英部队是由基地的四名指挥官领导的。要是你能给予他们致命的一击，快速解决掉这些指挥官，精英前线即可攻破。他们将溃不成军！$B$B但是，士兵，要小心；对指挥官和中尉可不能掉以轻心。他们可不是徒有虚名的……', `MaleText_loc5`='不，$c，這並不是全部。敵對陣營的精英部隊是由基地的四名指揮官領導的。要是你能給予他們致命的一擊，快速解決掉這些指揮官，精英前線即可攻破。他們將潰不成軍!$B$B但是，士兵，要小心;對指揮官和中尉可不能掉以輕心。他們可不是徒有虛名的...', `MaleText_loc7`='No, $c, eso no es todo. Hay cuatro Comandantes de la base al mando de las tropas de élite de la oposición. Si consigues atacar rápida y mortalmente a sus Comandantes, la élite también caerá. Se quedarán sin tropas.$B$BPero te lo advierto, Soldado. Los Comandantes y los Tenientes no son unidades que se puedan tomar a la ligera. Se han ganado su rango...' WHERE `ID`=9085;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='손뼉을 쳐요, 모두들! 모두 손뼉을 쳐요!', `MaleText_loc4`='所有人鼓掌，所有人鼓掌！', `MaleText_loc5`='所有人鼓掌，所有人鼓掌!', `MaleText_loc7`='¡Que todo el mundo dé palmas! ¡Todos a dar palmas!' WHERE `ID`=9086;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='봐 주셔서 감사합니다! 일주일 내내 이곳에 있을 테니 또 와주십시오!', `MaleText_loc4`='谢谢你，你是个很好的聆听者！我整周都会在这儿的！', `MaleText_loc5`='謝謝你，你是個很好的聆聽者!我整週都會在這兒的!', `MaleText_loc7`='Gracias, ¡sois un gran público! Estaré aquí toda la semana.' WHERE `ID`=9087;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='몇 푼만 좀 나눠주실 수 없을까요?', `MaleText_loc4`='省下一些零钱？', `MaleText_loc5`='施捨點錢給我?', `MaleText_loc7`='¿Algo suelto?' WHERE `ID`=9088;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나도 한때는 부자였지! 그런데 몽땅 잃어버렸어. 잃어버렸다고... 모두 다 사라졌어... 마치... 내 마음처럼. 내 마음은 꼭... 순두부 같아. 나 순두부 참 좋아하는데...', `MaleText_loc4`='我已经拥有它啦！我已经拥有了，然后又丢失啦。丢掉了……所有的东西……就像……我的思绪。我的思绪就像……奶酪。我喜欢奶酪。', `MaleText_loc5`='我已經擁有它啦!我已經擁有了，然後又丟失啦。丟掉了...所有的東西...就像...我的思緒。我的思緒就像...乳酪。我喜歡乳酪。', `MaleText_loc7`='¡Lo tenía todo! Lo tenía todo y lo perdí. Todo... perdido. Como... mi mente. Mi mente es como... un queso. Me gusta el queso.' WHERE `ID`=9089;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예술을 이해할 줄 아는 분이시라면 제 모자에 몇 푼만 넣어주십시오!', `MaleText_loc4`='看看你对艺术的欣赏能力吧，往我的帽子里扔些钱币！', `MaleText_loc5`='看看你對藝術的欣賞能力吧，往我的帽子裡扔些錢幣!', `MaleText_loc7`='¡Muestra que sabes apreciar las artes y deja un par de monedas en mi sombrero!' WHERE `ID`=9090;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생명체 검색 중... 목표물 찾을 수 없다...', `MaleText_loc4`='搜索生命体……没有发现目标', `MaleText_loc5`='搜索生命體...沒有發現目標', `MaleText_loc7`='Escaneando formas de vida... objetivo no encontrado.' WHERE `ID`=9091;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알 수 없는 생명체 발견... 분석 중...', `MaleText_loc4`='发现不明生物体……判断中……', `MaleText_loc5`='發現不明生物體...判斷中...', `MaleText_loc7`='Detectadas formas de vida desconocidas... evaluando...' WHERE `ID`=9092;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='목표물 상실... 델타 형식으로 검색 재시작', `MaleText_loc4`='目标丢失……返回搜索模式', `MaleText_loc5`='目標丟失...返回搜索模式', `MaleText_loc7`='Objetivo perdido... retomando patrones de búsqueda Delta.' WHERE `ID`=9093;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모험가 보고! 훌륭하다!', `MaleText_loc4`='探险者报告！……棒极了！', `MaleText_loc5`='探險者報告!...棒極了!', `MaleText_loc7`='¡Expedicionario informando!... ¡Excelente!' WHERE `ID`=9094;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='허기진 얼굴을 한 %s|1이;가; 깊은굴쥐를 뚫어지게 쳐다봅니다.', `MaleText_loc4`='%s垂涎欲滴地盯着一只矿道鼠。', `MaleText_loc5`='%s垂涎欲滴地盯著一隻礦道老鼠。', `MaleText_loc7`='%s mira con expresión hambrienta una rata subterránea.' WHERE `ID`=9095;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음... 구워먹기 딱 좋겠는걸.', `MaleText_loc4`='嗯……你看起来味道不错。', `MaleText_loc5`='嗯...你看起來味道不錯。', `MaleText_loc7`='Mmmm... ¡Pareces deliciosa!' WHERE `ID`=9096;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 생각해 보니... 그냥 굶는 게 낫겠어.', `MaleText_loc4`='让我想想……我想我会通过的。', `MaleText_loc5`='讓我想想...我想我會通過的。', `MaleText_loc7`='Pensándolo mejor... Creo que voy a pasar.' WHERE `ID`=9097;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마흔둘... 마흔둘... 뭐가 마흔둘이냐고? 흐흐흐... 뭐든지 될 수 있지! 마흔둘... 흠...', `MaleText_loc4`='42……42……42，什么？什么都不是！42……嗯……', `MaleText_loc5`='42...42...42，什麼?什麼都不是!42...嗯...', `MaleText_loc7`='Cuarenta y dos... cuarenta y dos... ¿Cuarenta y dos qué? ¡Podría ser cualquier cosa! Cuarenta y dos... Mmmm.' WHERE `ID`=9098;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 바란다면...', `MaleText_loc4`='如你所愿……', `MaleText_loc5`='如你所願...', `MaleText_loc7`='Como desees...' WHERE `ID`=9099;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나의 힘이 쇠약해져 가고 있다, 필멸의 존재여. 약속은 지켰고 길은 뚫렸으니 이제 내가 온 곳으로 돌아가야겠노라.', `MaleText_loc4`='我的力量在消退，人类。我履行了承诺，清除了道路。我得回去啦。', `MaleText_loc5`='我的力量在消退，人類。我履行了承諾，清除了道路。我得回去啦。', `MaleText_loc7`='Mi fuerza disminuye, mortal. He hecho lo que prometí, el camino está despejado. Ahora regreso al lugar de donde vine.' WHERE `ID`=9100;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘이 없다... 아무것도 할 수가 없다... 힘을 되찾아야 하노라... 제브림의 손에 있다... 이 고통을 끝내다오...', `MaleText_loc4`='无能为力……没有力气啦……恢复……必须恢复……瑟雷姆控制着……结束这痛苦的折磨吧……', `MaleText_loc5`='無能為力...沒有力氣啦...恢復...必須恢復...瑟雷姆控制著...結束這痛苦的折磨吧...', `MaleText_loc7`='Incapaz... sin poder... restaurar... debo restaurar... Zevrim controla... acabar con este tormento...' WHERE `ID`=9101;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙구나, 필멸의 존재여. 꿈속으로 돌아가기 전에 네게 해줄 수 있는 게 딱 한 가지 있노라.$B$B제브림의 주인인 알진에게로 통하는 문이 너의 길을 가로막고 있으니 내가 그 문을 파괴할 수 있도록 도와주겠다. 명령만 내리거라. 그리하면 문이 열리리라.', `MaleText_loc4`='谢谢你，人类。在我重回梦境之前我只能帮助你一次。$B$B通往瑟雷姆的主人奥兹恩的大门阻挡了你前进的道路。我会充当你破坏的器械。我等待你的命令，帮你打开大门。', `MaleText_loc5`='謝謝你，人類。在我重回夢境之前我只能幫助你一次。$B$B通往瑟雷姆的主人奧茲恩的大門阻擋了你前進的道路。我會充當你破壞的器械。我等待你的命令，幫你打開大門。', `MaleText_loc7`='Gracias, mortal. Solo puedo ofrecerte un servicio antes de regresar al Sueño.$B$BLa puerta del maestro Zevrim, Alzzin, bloquea tu camino. Seré tu instrumento de destrucción. La puerta se abrirá, solo tienes que darme la orden.' WHERE `ID`=9102;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다, 무쇠껍질 님. 준비가 됐으니 문을 열어주십시오.', `MaleText_loc4`='谢谢你，埃隆巴克。我们等着你打开大门。', `MaleText_loc5`='謝謝你，鐵桉。我們等著你打開大門。', `MaleText_loc7`='Gracias, Cortezaférrea. Estamos preparados, abre la puerta.', `FemaleText_loc1`='감사합니다, 무쇠껍질 님. 준비가 됐으니 문을 열어주십시오.', `FemaleText_loc4`='谢谢你，埃隆巴克。我们等着你打开大门。', `FemaleText_loc5`='謝謝你，鐵桉。我們等著你打開大門。', `FemaleText_loc7`='Gracias, Cortezaférrea. Estamos preparados, abre la puerta.' WHERE `ID`=9103;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 녀석의 손아귀에서 벗어나는구나!', `MaleText_loc4`='终于……从他邪恶的魔爪下逃脱了！', `MaleText_loc5`='終於...從他邪惡的魔爪下逃脫了!', `MaleText_loc7`='Por fin... ¡Libre de este maldito encierro!' WHERE `ID`=9104;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌난로 무덤은 어느 진영에서 점령하고 있습니까?', `MaleText_loc4`='谁控制着石炉墓地？', `MaleText_loc5`='誰控制著石爐墓地?', `MaleText_loc7`='¿Quién controla el Cementerio Piedrahogar?', `FemaleText_loc1`='돌난로 무덤은 어느 진영에서 점령하고 있습니까?', `FemaleText_loc4`='谁控制着石炉墓地？', `FemaleText_loc5`='誰控制著石爐墓地?', `FemaleText_loc7`='¿Quién controla el Cementerio Piedrahogar?' WHERE `ID`=9105;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌난로 무덤은 투쟁의 벌판에 있는 돌난로 전초기지 동쪽에 있습니다.$B$B현재 얼라이언스가 점령하고 있습니다.', `MaleText_loc4`='石炉墓地就在征战平原的石炉前哨东面。$B$B联盟控制着这片土地。', `MaleText_loc5`='石爐墓地就在征戰平原的石爐哨站東面。$B$B聯盟控制著這片土地。', `MaleText_loc7`='El Cementerio Piedrahogar se encuentra al este de la Avanzada Piedrahogar, en la Tierra de Disputa.$B$BActualmente pertenece a la Alianza.' WHERE `ID`=9106;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌난로 무덤은 투쟁의 벌판에 있는 돌난로 전초기지 동쪽에 있습니다.$B$B현재 호드가 점령하고 있습니다.', `MaleText_loc4`='石炉墓地就在征战平原的石炉前哨东面。$B$B部落控制着这片土地。', `MaleText_loc5`='石爐墓地就在征戰平原的石爐哨站東面。$B$B部落控制著這片土地。', `MaleText_loc7`='El Cementerio Piedrahogar se encuentra al este de la Avanzada Piedrahogar, en la Tierra de Disputa.$B$BActualmente pertenece a la Horda.' WHERE `ID`=9107;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지상 공격 부대를 보내려면 보급품이 얼마나 더 필요합니까?', `MaleText_loc4`='发动一次地面攻击还需要多少物资供给？', `MaleText_loc5`='發動一次地面攻擊還需要多少物資供給?', `MaleText_loc7`='¿Cuántos suministros más se necesitan para lanzar un asalto terrestre?', `FemaleText_loc1`='지상 공격 부대를 보내려면 보급품이 얼마나 더 필요합니까?', `FemaleText_loc4`='发动一次地面攻击还需要多少物资供给？', `FemaleText_loc5`='發動一次地面攻擊還需要多少物資供給?', `FemaleText_loc7`='¿Cuántos suministros más se necesitan para lanzar un asalto terrestre?' WHERE `ID`=9110;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 요새를 재건하려면 보급품이 얼마나 더 필요합니까?', `MaleText_loc4`='重建基地还需要多少物资供给？', `MaleText_loc5`='重建基地還需要多少物資供給?', `MaleText_loc7`='¿Cuántos suministros más se necesitan para reconstruir nuestra base?', `FemaleText_loc1`='우리 요새를 재건하려면 보급품이 얼마나 더 필요합니까?', `FemaleText_loc4`='重建基地还需要多少物资供给？', `FemaleText_loc5`='重建基地還需要多少物資供給?', `FemaleText_loc7`='¿Cuántos suministros más se necesitan para reconstruir nuestra base?' WHERE `ID`=9111;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보급품이 좀 있긴 하지만 투쟁의 벌판으로 지상 공격 부대를 보내려면 훨씬 더 많이 필요하오.', `MaleText_loc4`='我们有很多物资储备啦，但是要发动对征战平原的地面攻击，我们还需要更多的物资。', `MaleText_loc5`='我們有很多物資儲備啦，但是要發動對征戰平原的地面攻擊，我們還需要更多的物資。', `MaleText_loc7`='Tenemos muchos suministros, pero necesitamos muchos más para lanzar un asalto terrestre en la Tierra de Disputa.' WHERE `ID`=9112;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보급품이 있긴 하지만 충분하지 않소. 투쟁의 벌판으로 지상 공격 부대를 보내려면 훨씬 더 많이 있어야 하오.', `MaleText_loc4`='我们有一些物资，但是现在有很多啦。我们还需要一些来发动对征战平原的地面攻击。', `MaleText_loc5`='我們有一些物資，但是現在有很多啦。我們還需要一些來發動對征戰平原的地面攻擊。', `MaleText_loc7`='Tenemos algunos suministros, pero no demasiados. Necesitaremos muchos más para poder lanzar un asalto terrestre en la Tierra de Disputa.' WHERE `ID`=9113;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보급품은 거의 다 떨어졌소. 투쟁의 벌판으로 지상 공격 부대를 보내려면 훨씬 더 많은 보급품이 필요하오!', `MaleText_loc4`='我们几乎没有物资装备。想要发动对征战平原的地面攻击的话，还需要很多物资！', `MaleText_loc5`='我們幾乎沒有物資裝備。想要發動對征戰平原的地面攻擊的話，還需要很多物資!', `MaleText_loc7`='Casi no tenemos suministros. Si queremos lanzar un asalto terrestre en la Tierra de Disputa, vamos a necesitar muchos más.' WHERE `ID`=9114;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서리늑대 요새를 재건할 보급품이 충분히 모아졌소. 조금만 더 있으면 정비를 하고 전투를 재개할 수 있을 거요!', `MaleText_loc4`='我们拥有丰富的物资储备来修复霜狼要塞。再有一些我们就能完全修复，重新开战啦！', `MaleText_loc5`='我們擁有豐富的物資儲備來修復霜狼要塞。再有一些我們就能完全修復，重新開戰啦!', `MaleText_loc7`='Tenemos una gran cantidad de suministros para reconstruir el Bastión Lobo Gélido. Con algunos más, tendremos suficientes para reparar y volver a entrar en la batalla.' WHERE `ID`=9115;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보급품이 어느 정도 있긴 하지만 서리늑대 요새를 완전히 재건할 수 있으려면 훨씬 더 많이 필요하오.', `MaleText_loc4`='我们的物资储备状况一般，要完全修复霜狼要塞的话，我们还需要更多的物资。', `MaleText_loc5`='我們的物資儲備狀況一般，要完全修復霜狼要塞的話，我們還需要更多的物資。', `MaleText_loc7`='Tenemos una cantidad de suministros media para reconstruir, pero necesitamos muchos más antes de poder reparar el Bastión Lobo Gélido completamente.' WHERE `ID`=9116;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보급품이 아주 조금뿐이오. 서리늑대 요새를 재건하는 데는 턱없이 모자란 양이지... 수리를 하고 전투를 다시 시작하려면 훨씬 더 많이 있어야 하오.', `MaleText_loc4`='我们的物资太少，不足以修复霜狼要塞。如果想要完全修复，重新开战，需要的物资就更多啦。', `MaleText_loc5`='我們的物資太少，不足以修復霜狼要塞。如果想要完全修復，重新開戰，需要的物資就更多啦。', `MaleText_loc7`='Tenemos una cantidad de suministros muy pequeña para reconstruir el Bastión Lobo Gélido. Vamos a necesitar muchos más para poder reparar y volver a entrar en la batalla.' WHERE `ID`=9117;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서리늑대 요새를 재건할 보급품이 거의 없소. 요새를 수리하고 전투를 다시 시작하려면 아직 한참 더 많이 필요하오.', `MaleText_loc4`='我们几乎没有物资来修复霜狼要塞。我们需要更多的物资来重建基地，重新开战。', `MaleText_loc5`='我們幾乎沒有物資來修復霜狼要塞。我們需要更多的物資來重建基地，重新開戰。', `MaleText_loc7`='Casi no tenemos suministros para reconstruir el Bastión Lobo Gélido. Necesitaremos muchos, muchos más, para poder reparar nuestra base y volver a entrar en la batalla.' WHERE `ID`=9118;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 투쟁의 벌판에 대한 지상 공격을 펼치는 데 필요한 보급품이 충분히 모아졌소. 공격명령서를 보내길 원하고 또 당신 계급이 충분히 높다고 생각한다면 서리늑대 마을에 있는 하사관 야즈라 블러드스날에게 가서 얘기를 나눠 보시오.', `MaleText_loc4`='$n，我们已经具备了足够的物资来发动对征战平原的地面攻击。如果你想要传递指令，而且你的等级足够高的话，就跟霜狼村的亚斯拉·血矛谈谈。', `MaleText_loc5`='$n，我們已經具備了足夠的物資來發動對征戰平原的地面攻擊。如果你想要傳遞指令，而且你的等級足夠高的話，就跟霜狼村的亞斯拉·血矛談談。', `MaleText_loc7`='$n, tenemos suficientes suministros para lanzar asaltos terrestres en la Tierra de Disputa. Si quieres dar las órdenes, y tienes rango para hacerlo, vete a hablar con el sargento Yazra Gruñido Sangriento en la Aldea Lobo Gélido.' WHERE `ID`=9119;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='재건에 필요한 보급품이 많이 모아졌소. 조금만 더 있으면 던 발다르를 수리하고 전투를 다시 시작할 수 있을 거요!', `MaleText_loc4`='我们有许多用于重建的物资了。再多一些我们就能修复丹巴达尔，重新开战啦！', `MaleText_loc5`='我們有許多用於重建的物資了。再多一些我們就能修復丹巴達爾，重新開戰啦!', `MaleText_loc7`='Tenemos muchos suministros para reconstruir. Con algunos más, tendremos suficientes para reparar Dun Baldar y volver a entrar en la batalla.' WHERE `ID`=9120;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='재건에 쓸 보급품을 많이 모으긴 했지만 던 발다르를 수리하려면 훨씬 더 많이 필요하다오. 보급품을 계속 더 가져오시오!', `MaleText_loc4`='我们已经收集到很多用于重建的物资，但是还需要一些才能修复丹巴达尔。继续收集吧！', `MaleText_loc5`='我們已經收集到很多用於重建的物資，但是還需要一些才能修復丹巴達爾。繼續收集吧!', `MaleText_loc7`='Hemos reunido muchos suministros para reconstruir, pero necesitamos más para reparar Dun Baldar. ¡Sigue trayéndome suministros!' WHERE `ID`=9121;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='재건에 쓸 보급품이 많지 않소. 던 발다르를 수리하려면 훨씬 더 많이 필요할 거요.', `MaleText_loc4`='我们的物资不够，无法修复。要修复丹巴达尔，还需要很多物资。', `MaleText_loc5`='我們的物資不夠，無法修復。要修復丹巴達爾，還需要很多物資。', `MaleText_loc7`='No tenemos muchos suministros para reconstruir. Necesitaremos muchos más para poder reparar Dun Baldar.' WHERE `ID`=9122;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='던 발다르가 큰 타격을 입었고 이를 재건하기 위한 보급품도 아주 적은 상태요. 얼라이언스에서는 보급품을 모으는 데 당신의 도움을 필요로 하고 있소!', `MaleText_loc4`='丹巴达尔破坏严重，要修复的话，我们还需要大量物资供给。联盟需要你的帮助！', `MaleText_loc5`='丹巴達爾破壞嚴重，要修復的話，我們還需要大量物資供給。聯盟需要你的幫助!', `MaleText_loc7`='Dun Baldar está en muy mal estado y no tenemos muchos suministros para reconstruir. ¡La Alianza necesita tu ayuda para que traigas suministros!' WHERE `ID`=9123;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 우리에겐 지상 공격을 펼치는 데 필요한 보급품이 충분히 있소. 스톰파이크 경비대에서 지위가 충분히 높다면 하사관 노레그 스톰파이크와 얘기해 보시오.', `MaleText_loc4`='$n，我们已经具备足够的物资来发动地面攻击。如果您在雷矛守卫的声望够高的话，就跟诺雷格·雷矛中尉谈谈吧。', `MaleText_loc5`='$n，我們已經具備足夠的物資來發動地面攻擊。如果您在雷矛守衛的聲望夠高的話，就跟諾雷格·雷矛下士談談吧。', `MaleText_loc7`='$n, tenemos suficientes suministros para lanzar asaltos terrestres. Si tu rango en la Guardia Pico Tormenta es lo suficientemente alto, habla con el cabo Noreg Pico Tormenta.' WHERE `ID`=9124;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여분의 보급품이 많이 있긴 하지만 투쟁의 벌판으로 공격 부대를 보내려면아직 더 많이 필요하오.', `MaleText_loc4`='我们的物资储备已经很多了，但是要发动对征战平原的地面攻击，我们还需要更多的物资。', `MaleText_loc5`='我們的物資儲備已經很多了，但是要發動對征戰平原的地面攻擊，我們還需要更多的物資。', `MaleText_loc7`='Tenemos muchos suministros de sobra, pero necesitamos más para poder lanzar un asalto en la Tierra de Disputa.' WHERE `ID`=9125;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여분의 보급품이 있긴 하지만 많지는 않소. 투쟁의 벌판으로 지상 공격 부대를 보낼 수 있으려면 훨씬 더 많이 필요하다오.', `MaleText_loc4`='我们有剩余的物资，但是不太多。我们还需要更多的物资才能发动对征战平原的地面攻击。', `MaleText_loc5`='我們有剩餘的物資，但是不太多。我們還需要更多的物資才能發動對征戰平原的地面攻擊。', `MaleText_loc7`='Tenemos suministros de sobra, pero no demasiados. Necesitaremos muchos más para poder lanzar un asalto terrestre en la Tierra de Disputa.' WHERE `ID`=9126;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여분의 보급품이 거의 없소. 투쟁의 벌판으로 다른 지상 공격 부대를 보낼 수 있으려면 훨씬 더 많이 노력해야 할 거요.', `MaleText_loc4`='我们几乎没有多余的物资。要发动对征战平原的另一场地面攻击，我们还需要很多物资。', `MaleText_loc5`='我們幾乎沒有多餘的物資。要發動對征戰平原的另一場地面攻擊，我們還需要很多物資。', `MaleText_loc7`='Casi no tenemos suministros de sobra. Necesitaremos muchos más antes de que estemos listos para lanzar un asalto terrestre en la Tierra de Disputa.' WHERE `ID`=9127;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지상 공격 부대를 보내려면 보급품이 얼마나 더 필요합니까?', `MaleText_loc4`='发动地面攻击还需要多少物资供给？', `MaleText_loc5`='發動地面攻擊還需要多少物資供給?', `MaleText_loc7`='¿Cuántos suministros más se necesitan para lanzar asaltos terrestres?', `FemaleText_loc1`='지상 공격 부대를 보내려면 보급품이 얼마나 더 필요합니까?', `FemaleText_loc4`='发动地面攻击还需要多少物资供给？', `FemaleText_loc5`='發動地面攻擊還需要多少物資供給?', `FemaleText_loc7`='¿Cuántos suministros más se necesitan para lanzar asaltos terrestres?' WHERE `ID`=9128;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요새를 재건하려면 보급품이 얼마나 더 필요합니까?', `MaleText_loc4`='重建基地还需要多少物资供给？', `MaleText_loc5`='重建基地還需要多少物資供給?', `MaleText_loc7`='¿Cuántos suministros más se necesitan para reconstruir nuestra base?', `FemaleText_loc1`='요새를 재건하려면 보급품이 얼마나 더 필요합니까?', `FemaleText_loc4`='重建基地还需要多少物资供给？', `FemaleText_loc5`='重建基地還需要多少物資供給?', `FemaleText_loc7`='¿Cuántos suministros más se necesitan para reconstruir nuestra base?' WHERE `ID`=9129;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부대가 다음 단계로 승급하려면 보급품이 얼마나 더 필요합니까?', `MaleText_loc4`='再升一级还需要多少物资供给？', `MaleText_loc5`='再升一級還需要多少物資供給?', `MaleText_loc7`='¿Cuántos suministros más se necesitan para la siguiente mejora?', `FemaleText_loc1`='부대가 다음 단계로 승급하려면 보급품이 얼마나 더 필요합니까?', `FemaleText_loc4`='再升一级还需要多少物资供给？', `FemaleText_loc5`='再升一級還需要多少物資供給?', `FemaleText_loc7`='¿Cuántos suministros más se necesitan para la siguiente mejora?' WHERE `ID`=9130;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정예 부대로 승급하는 데 필요한 보급품이 거의 다 모였네.', `MaleText_loc4`='我差不多拥有足够的物资供给来升级到精练部队了。', `MaleText_loc5`='我差不多擁有足夠的物資供給來升級到老練部隊了。', `MaleText_loc7`='Casi tengo suficientes suministros para mejorar a unidades veteranas.' WHERE `ID`=9131;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보급품이 더 많이 있어야 우리 부대가 승급할 수 있네.', `MaleText_loc4`='我需要更多的物资来升级我们的军队。', `MaleText_loc5`='我需要更多的物資來升級我們的軍隊。', `MaleText_loc7`='Necesito muchos más suministros para mejorar nuestras unidades.' WHERE `ID`=9132;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 부대가 승급하는 데 필요한 보급품이 거의 다 모였네.', `MaleText_loc4`='我差不多拥有足够的物资供给来升级部队了。', `MaleText_loc5`='我差不多擁有足夠的物資供給來升級部隊了。', `MaleText_loc7`='Casi tengo suficientes suministros para mejorar nuestras tropas.' WHERE `ID`=9133;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정예 부대로 승급하는 데 필요한 보급품이 절반 정도 있네.', `MaleText_loc4`='升级到精练部队所需的物资还差一半呢。', `MaleText_loc5`='升級到老練部隊所需的物資還差一半呢。', `MaleText_loc7`='Tengo la mitad de suministros necesarios para mejorar a unidades veteranas.' WHERE `ID`=9134;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정예 부대로 승급하는 데 필요한 보급품이 삼분의 일도 안 되네.', `MaleText_loc4`='升级到精练部队所需的物资只有不到三分之一。', `MaleText_loc5`='升級到老練部隊所需的物資只有不到三分之一。', `MaleText_loc7`='Tengo menos de un tercio de los suministros necesarios para mejorar a unidades veteranas.' WHERE `ID`=9135;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='승급하는 데 필요한 보급품이 거의 없어.', `MaleText_loc4`='我几乎没有任何可供升级的物资。', `MaleText_loc5`='我幾乎沒有任何可供升級的物資。', `MaleText_loc7`='Casi no tengo suministros para las mejoras.' WHERE `ID`=9136;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으으... 저 잡초들 때문에 밤낮으로 눈코 뜰 새가 없으니, 원! 당신도 보셨죠?$B$B그냥 수도관 같은 걸 타고 이 녀석들에게 멀리 좀 도망갔으면 좋겠다니까...', `MaleText_loc4`='啊……这些家伙让我整天都不得安宁！你看见他们了吗？$B$B我真希望自己能藏到地下，避开他们……', `MaleText_loc5`='啊...這些傢伙讓我整天都不得安寧!你看見他們了嗎?$B$B我真希望自己能藏到地下，避開他們...', `MaleText_loc7`='Agh, esas ratas me tienen ocupado día y noche. ¿No las has visto?$B$BOjalá pudiera meterme en un agujero negro y escapar de ellas...' WHERE `ID`=9137;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 잡초들과 싸우는 걸 도와드리겠습니다, 라리온!', `MaleText_loc4`='拉瑞安，我想帮助你打败这些家伙！', `MaleText_loc5`='拉里安，我想幫助你打敗這些傢伙!', `MaleText_loc7`='Larion, quiero ayudarte a luchar contra las ratas.', `FemaleText_loc1`='이 잡초들과 싸우는 걸 도와드리겠습니다, 라리온!', `FemaleText_loc4`='拉瑞安，我想帮助你打败这些家伙！', `FemaleText_loc5`='拉里安，我想幫助你打敗這些傢伙!', `FemaleText_loc7`='Larion, quiero ayudarte a luchar contra las ratas.' WHERE `ID`=9138;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 특수 장비라고요! 부주의하게 다루면 큰일 나요! 당신이 그렇게 좋아한다는 그 독한 럼주를 잔뜩 마시고 만져도 안됩니다...$B$B참, 말이 나왔으니 말인데... 혹시 그 독하다는 럼주 좀 남은 거 없어요?', `MaleText_loc4`='这是一些特殊装备！要小心对待，要是你喝了太多那种烈性酒，可别试着操纵这些装备，我听说你很喜欢饮酒的……$B$B说到酒……你没有带吧，嗯？', `MaleText_loc5`='這是特殊裝備!要小心對待，要是你喝了太多那種烈性酒，可別妄想操縱這些裝備，我聽說你很喜歡飲酒的...$b$b說到酒...你沒有帶吧，嗯?', `MaleText_loc7`='¡Esto sí que es equipamiento especializado! Manéjalo con mucho cuidado y, por supuesto, no intentes utilizarlo si has bebido ese ron volátil que he oído que te gusta tanto...$B$BHablando de ron... ¿No tendrás algo por ahí, eh?' WHERE `ID`=9139;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어느 쪽으로 가야 하냐고요? 제가 줄 수 있는 유일한 충고는 어떤 길이든 발길 닿는 대로, 당신 원하는 대로 가라는 거예요!$B$B사실은 하나도 기억이 안 나거든요!', `MaleText_loc4`='你要走哪条路？嗯，我能给你的唯一建议是走你想走的路！$B$B我什么都记不得啦！', `MaleText_loc5`='你要走哪條路?嗯，我能給你的唯一建議是走你想走的路!$B$B我什麼都記不得啦!', `MaleText_loc7`='¿Por dónde debería ir? Bueno, el único consejo que puedo ofrecerte es que vayas por donde quieras.$B$B¡No puedo acordarme de nada!' WHERE `ID`=9140;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 쓰레기를 뒤집니다.', `MaleText_loc4`='%s仔细检查着垃圾。', `MaleText_loc5`='%s仔細檢查垃圾。', `MaleText_loc7`='%s rebusca en la basura.' WHERE `ID`=9141;
