UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 곤봉을 쳐들더니 마구 휘두르기 시작합니다!', `MaleText_loc4`='%s放下木棒，开始狂野地摇摆！', `MaleText_loc5`='%s放下木棒，開始狂野地搖擺!', `MaleText_loc7`='%s coge su mazo y empieza a balancearlo salvajemente.' WHERE `ID`=9144;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='약골 같은 녀석이 감히 나를 헤치려고 하다니!', `MaleText_loc4`='你胆敢惹恼我，懦弱的家伙！', `MaleText_loc5`='你膽敢惹惱我，懦弱的傢伙!', `MaleText_loc7`='¡Cómo osas intentar enfrentarte a mí, pelele!' WHERE `ID`=9145;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 하품을 합니다.', `MaleText_loc4`='%s打着呵欠。', `MaleText_loc5`='%s打呵欠。', `MaleText_loc7`='%s bosteza.' WHERE `ID`=9147;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일인가, $c 양반?', `MaleText_loc4`='有什么事吗，$c？', `MaleText_loc5`='找我有事嗎，$c?', `MaleText_loc7`='¿Sí, $c?' WHERE `ID`=9148;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='온통 쥐떼로군. 보이는 곳마다 쥐가 있어. 항상 저 새까맣고 조그만 눈으로 날 감시하고 있어. 쓴맛을 보여줘야지. 모두 다 말이야!', `MaleText_loc4`='到处都是老鼠。随处可见。它们那贪婪的小眼睛老是盯着我。我会给它们点颜色看看的！', `MaleText_loc5`='到處都是老鼠。隨處可見。它們那貪婪的小眼睛老是盯著我。我會給它們點顏色看看的!', `MaleText_loc7`='Ratas por todas partes. Todo lo que veo son ratas. Siempre mirándome con sus ojitos como canicas. Yo les enseñaré. ¡Van a ver lo que es bueno!' WHERE `ID`=9149;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쥐 꼬치구이요! 맛있는 쥐 꼬치구이 사가세요! 얼마 안 있으면 다 팔리니까 얼른 사가세요!', `MaleText_loc4`='烤鼠肉串！在这儿取一些好吃的烤鼠肉串！尽快拿吧！', `MaleText_loc5`='烤鼠肉串!在這兒取一些好吃的烤鼠肉串!儘快拿吧!', `MaleText_loc7`='¡Kebabs de rata! ¡Deliciosos kebabs de rata! ¡Consigue uno antes de que se acaben!' WHERE `ID`=9150;
