UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 부대는 아직 아무런 승급도 되지 않았소. 현재 보급품이 부족해 승급할 수 없소.', `MaleText_loc4`='我们的军队不能升级，军需不够，无法升级。', `MaleText_loc5`='我們的軍隊不能升級，軍需不夠，無法升級。', `MaleText_loc7`='Nuestras unidades no están mejoradas y no tengo suficientes suministros para hacerlo.' WHERE `ID`=9164;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 부대는 상급 부대로 승급했소. 하지만 정예 부대로 승급하기에는 보급품이 부족하오.', `MaleText_loc4`='我们的军队已经升级到经验丰富的军队，但是我没有足够的军需升级到老兵。', `MaleText_loc5`='我們的軍隊已經升級到經驗豐富的軍隊，但是我沒有足夠的軍需升級到老兵。', `MaleText_loc7`='Nuestras unidades han sido mejoradas a experimentadas, pero no tengo suficientes suministros para mejorarlas a veteranas.' WHERE `ID`=9165;
