UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰파이크 보급기지는 던 발다르 병영 바로 외곽인 던 발다르에 있습니다.$B$B현재 얼라이언스가 점령하고 있습니다.', `MaleText_loc4`='雷矛急救站在丹巴达尔，就在丹巴达尔军营外。$B$B联盟控制着这片土地。', `MaleText_loc5`='雷矛急救站在丹巴達爾，就在丹巴達爾軍營外。$B$B聯盟控制著這片土地。', `MaleText_loc7`='El Puesto de auxilio Pico Tormenta está en Dun Baldar, justo fuera del cuartel de Dun Baldar.$B$BActualmente pertenece a la Alianza.' WHERE `ID`=9238;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰파이크 보급기지는 던 발다르 병영 바로 외곽인 던 발다르에 있습니다.$B$B현재 호드가 점령하고 있습니다.', `MaleText_loc4`='雷矛急救站在丹巴达尔，就在丹巴达尔军营外。$B$B部落控制着这片土地。', `MaleText_loc5`='雷矛急救站在丹巴達爾，就在丹巴達爾軍營外。$B$B部落控制著這片土地。', `MaleText_loc7`='El Puesto de auxilio Pico Tormenta está en Dun Baldar, justo fuera del cuartel de Dun Baldar.$B$BActualmente pertenece a la Horda.' WHERE `ID`=9239;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰파이크 보급기지는 던 발다르 병영 바로 외곽인 던 발다르에 있습니다.$B$B현재 아무도 이곳을 점령하지 않았습니다.', `MaleText_loc4`='雷矛急救站在丹巴达尔，就在丹巴达尔军营外。$B$B联盟和部落还在争夺这片土地。', `MaleText_loc5`='雷矛急救站在丹巴達爾，就在丹巴達爾軍營外。$B$B聯盟和部落還在爭奪這片土地。', `MaleText_loc7`='El Puesto de auxilio Pico Tormenta está en Dun Baldar, justo fuera del cuartel de Dun Baldar.$B$BAhora mismo no pertenece a nadie.' WHERE `ID`=9240;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌난로 무덤은 투쟁의 벌판에 있는 돌난로 전초기지 동쪽에 있습니다.$B$B현재 아무도 이곳을 점령하지 않았습니다.', `MaleText_loc4`='石炉墓地就在征战平原的炉石前哨东面。$B$B联盟和部落还在争夺这片土地。', `MaleText_loc5`='石爐墓地就在征戰平原的石爐哨站東面。$B$B聯盟和部落還在爭奪這片土地。', `MaleText_loc7`='El Cementerio Piedrahogar se encuentra al este de la Avanzada Piedrahogar, en la Tierra de Disputa.$B$BAhora mismo no pertenece a nadie.' WHERE `ID`=9241;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰파이크 무덤은 던 발다르의 동쪽 다리 건너에 있으며 산을 앞뒤로 만나고 있습니다.$B$B현재 아무도 이곳을 점령하지 않았습니다.', `MaleText_loc4`='雷矛墓地就在丹巴达尔以东的桥梁对面的山脉中。$B$B联盟和部落还在争夺这片土地。', `MaleText_loc5`='雷矛墓地散佈在丹巴達爾以東的橋樑對面的山脈中。$B$B聯盟和部落還在爭奪這片土地。', `MaleText_loc7`='El Cementerio Pico Tormenta está en las montañas, pasado el puente al este de Dun Baldar.$B$BAhora mismo no pertenece a nadie.' WHERE `ID`=9242;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서리늑대 무덤은 서리늑대 마을에서 북쪽으로 그리 멀리 떨어지지 않은 길가에 있습니다.$B$B아무도 이곳을 점령하지 않았습니다.', `MaleText_loc4`='霜狼墓地就在距离霜狼村以北不远的路面。$B$B联盟和部落还在争夺这片土地。', `MaleText_loc5`='霜狼墓地就在距離霜狼村以北不遠的路面。$B$B聯盟和部落還在爭奪這片土地。', `MaleText_loc7`='El Cementerio Lobo Gélido está justo al lado del camino, cerca de la Aldea Lobo Gélido.$B$BAhora mismo no pertenece a nadie.' WHERE `ID`=9243;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='눈사태 무덤은 겨울도끼 요새에서 동쪽, 투쟁의 벌판 언덕 꼭대기에 있습니다.$B$B아무도 이곳을 점령하지 않았습니다.', `MaleText_loc4`='雪落墓地就在征战平原的高山顶部，就在冰斧要塞以东。$B$B联盟和部落还在争夺这片土地。', `MaleText_loc5`='落雪墓地就在征戰平原的高山頂部，就在冰斧要塞以東。$B$B聯盟和部落還在爭奪這片土地。', `MaleText_loc7`='El Cementerio Avalancha se encuentra en la cumbre de una colina en la Tierra de Disputa, al este del Fuerte Hacha Invernal.$B$BAhora mismo no pertenece a nadie.' WHERE `ID`=9244;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서리늑대 구호막사는 서리늑대 보초탑의 남쪽, 서리늑대 요새에 있습니다.$B$B현재 얼라이언스가 점령하고 있습니다.', `MaleText_loc4`='霜狼急救站在霜狼城堡中，就在霜狼哨塔以南。$B$B联盟控制着这片土地。', `MaleText_loc5`='霜狼急救站在霜狼要塞中，就在霜狼哨塔以南。$B$B聯盟控制著這片土地。', `MaleText_loc7`='El Puesto de auxilio Lobo Gélido está en el Bastión Lobo Gélido, al sur de las Torres Lobo Gélido.$B$BActualmente pertenece a la Alianza.' WHERE `ID`=9245;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서리늑대 구호막사는 서리늑대 보초탑의 남쪽, 서리늑대 요새에 있습니다.$B$B현재 호드가 점령하고 있습니다.', `MaleText_loc4`='霜狼急救站在霜狼城堡中，就在霜狼哨塔以南。$B$B部落控制着这片土地。', `MaleText_loc5`='霜狼急救站在霜狼要塞中，就在霜狼哨塔以南。$B$B部落控制著這片土地。', `MaleText_loc7`='El Puesto de auxilio Lobo Gélido está en el Bastión Lobo Gélido, al sur de las Torres Lobo Gélido.$B$BActualmente pertenece a la Horda.' WHERE `ID`=9246;
