UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갈반가르 부대장은 드렉타르가 신뢰하는 부하로서 투쟁의 벌판 남부에 있는 얼음피 주둔지에서 호드를 지휘했습니다.$B$B갈반가르 부대장은 전사했습니다.', `MaleText_loc4`='加尔范上尉是德雷克塔尔值得信赖的助手。他领导着来自征战平原以南的冰血要塞的部落军队。$B$B如果加尔范上尉的话，德雷克塔尔将进入霜狼要塞的奥特兰克山谷。$B$B加尔范上尉现在在冰血要塞里。', `MaleText_loc5`='加爾凡加上尉是德雷克塔爾值得信賴的助手。他領導著來自征戰平原以南的冰血要塞的部落軍隊。$B$B如果加爾凡加上尉的話，德雷克塔爾將進入霜狼要塞的奧特蘭克山谷。$B$B加爾凡加上尉現在在冰血要塞裡。', `MaleText_loc7`='El capitán Galvangar es la mano derecha de Drek''Thar. Lidera a las tropas de la Horda desde el Baluarte Sangrehielo, en la sección sur de la Tierra de Disputa.$B$BEl capitán Galvangar ha sido asesinado.' WHERE `ID`=9327;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반다르 스톰파이크는 알터랙 계곡에 주둔한 얼라이언스 군대의 사령관으로서 던 발다르에서 지휘하고 있습니다.$B$B그를 쓰러뜨리면 알터랙 전투의 승리는 호드에게 돌아갑니다.', `MaleText_loc4`='范达尔·雷矛是驻守在奥特兰克山谷的联盟将军，他指挥着来自丹巴达尔的军队。$B$B如果他被打败，联盟将在奥特兰克一役败北；但是只有在巴琳达·斯通赫尔斯阵亡后他才会出现。$B$B范达尔目前不在奥特兰克山谷。', `MaleText_loc5`='范達爾·雷矛是駐守在奧特蘭克山谷的聯盟將軍，他指揮著來自丹巴達爾的軍隊。$B$B如果他被打敗，聯盟將在奧特蘭克一役敗北。$B$B范達爾目前不在奧特蘭克山谷。', `MaleText_loc7`='Vanndar Pico Tormenta es el general de la milicia de la Alianza en Alterac, y dirige a sus tropas desde Dun Baldar.$B$BSi cae, seguramente la Alianza perderá la batalla de Alterac.' WHERE `ID`=9328;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반다르 스톰파이크는 알터랙 계곡에 주둔한 얼라이언스 군대의 사령관으로서 던 발다르에서 지휘하고 있습니다.$B$B그를 쓰러뜨리면 알터랙 전투의 승리는 호드에게 돌아갑니다.', `MaleText_loc4`='范达尔·雷矛是驻守在奥特兰克山谷的联盟将军，他指挥着来自丹巴达尔的军队。$B$B如果他被打败，联盟将在奥特兰克一役败北；但是只有在巴琳达·斯通赫尔斯阵亡后他才会出现。$B$B范达尔目前不在奥特兰克山谷。', `MaleText_loc5`='范達爾·雷矛是駐守在奧特蘭克山谷的聯盟將軍，他指揮著來自丹巴達爾的軍隊。$B$B如果他被打敗，聯盟將在奧特蘭克一役敗北。$B$B范達爾目前不在奧特蘭克山谷。', `MaleText_loc7`='Vanndar Pico Tormenta es el general de la milicia de la Alianza en Alterac, y dirige a sus tropas desde Dun Baldar.$B$BSi cae, seguramente la Alianza perderá la batalla de Alterac.' WHERE `ID`=9329;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전쟁이라고요?', `MaleText_loc4`='一场战斗？', `MaleText_loc5`='一場戰鬥?', `MaleText_loc7`='¿Una batalla?', `FemaleText_loc1`='전쟁이라고요?', `FemaleText_loc4`='一场战斗？', `FemaleText_loc5`='一場戰鬥?', `FemaleText_loc7`='¿Una batalla?' WHERE `ID`=9330;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정령계에 대전쟁이 벌어지던 시기에 불의 군주 라그나로스가 저의 주인이자 바람의 왕자이신 썬더란을 소멸시키려 했습니다.$B$B<분노로 얼굴이 일그러지며 고개를 떨구는 데미트리안>$B$B놈의 이름을 입 밖에도 내지 마십시오. 화가 치밀어 당신의 이빨로 이 황폐한 야영지를 장식해버릴지도 모르니까 말입니다. 조용히 듣기만 하십시오.', `MaleText_loc4`='炎魔之王拉格纳罗斯在元素大灾变中想要杀死我的主人桑德兰，空气的王子。$B$B<德米提恩低下头，面部肌肉因愤怒而扭曲。>$B$B一旦你说出他的名字，我就会用你的内脏装点这座被破坏的营帐。保持安静，听好了。', `MaleText_loc5`='炎魔拉格納羅斯在元素大爆炸中想要殺死我的主人桑德蘭，風元素王子。$B$B<德米提恩低下頭，面部肌肉因憤怒而扭曲。>$B$B一旦你說出他的名字，我就會用你的內臟裝點這座被破壞的營帳。保持安靜，聽好了。', `MaleText_loc7`='Ocurrió durante el Cataclismo Elemental. El Señor del Fuego, Ragnaros, pretendía consumir a mi Señor, Thunderaan, Príncipe del Viento.$B$B<Demitrian inclina la cabeza con un gesto de cólera.>$B$BPronuncia su nombre y decoraré este campo arrasado con tus entrañas. Permanece en silencio y escúchame.' WHERE `ID`=9331;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<조용히 고개를 끄덕입니다.>', `MaleText_loc4`='<点头>。', `MaleText_loc5`='<點頭>。', `MaleText_loc7`='<Asentir>.', `FemaleText_loc1`='<조용히 고개를 끄덕입니다.>', `FemaleText_loc4`='<点头>。', `FemaleText_loc5`='<點頭>。', `FemaleText_loc7`='<Asentir>.' WHERE `ID`=9332;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님을 배신한 것은 라그나로스의 부관인 게돈과 가르였습니다. 썬더란께서는 영문도 모르고 변을 당하셨습니다.', `MaleText_loc4`='拉格纳罗斯、迦顿和加尔背叛了我的领主。桑德兰王子在毫不知情的情况下被捕了。', `MaleText_loc5`='拉格納羅斯的副官，迦頓和加爾背叛了我的主人。桑德蘭在毫無警覺下被抓。', `MaleText_loc7`='Fueron los tenientes de Ragnaros, Geddon y Garr, quienes perpetraron la traición contra mi Señor. Cogieron por sorpresa a Thunderaan.' WHERE `ID`=9333;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영문도 모르고 변을 당했다니... 어떻게 말입니까?', `MaleText_loc4`='在毫无觉察的情况下碰到的？怎么会？', `MaleText_loc5`='在毫無覺察的情況下碰到的?怎麼會?', `MaleText_loc7`='¿Por sorpresa? ¿Cómo?', `FemaleText_loc1`='영문도 모르고 변을 당했다니... 어떻게 말입니까?', `FemaleText_loc4`='在毫无觉察的情况下碰到的？怎么会？', `FemaleText_loc5`='在毫無覺察的情況下碰到的?怎麼會?', `FemaleText_loc7`='¿Por sorpresa? ¿Cómo?' WHERE `ID`=9334;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='썬더란께서는 불의 군주가 다가오는 것을 전혀 모르고 계셨기 때문에 손쓸 겨를도 없이 라그나로스의 전설적인 망치인 설퍼라스에 의해 무자비하게 당하고 말았습니다. 썬더란께서는 참패를 당해 쓰러지셨지요.$B$B불의 군주가 탐욕스럽게 주인님의 정기를 빨아들였지만 그분을 완전히 소멸시키지는 못했습니다.', `MaleText_loc4`='桑德兰王子对炎魔之王的进攻毫不知情。在王子做出反应之前，传说中拉格纳罗斯使用的大锤萨弗拉斯就会无情地痛击王子。桑德兰倒下了，他完全被打败了。$B$B炎魔之王吸取了王子的精华，但这仍然不能满足他的贪欲。', `MaleText_loc5`='桑德蘭王子對炎魔的進攻毫不知情。在王子做出反應之前，傳說中拉格納羅斯使用的大錘薩弗拉斯就會無情地痛擊王子。桑德蘭倒下了，他完全被打敗了。$B$B炎魔吸取了王子的精華，但這仍然不能滿足他的貪欲。', `MaleText_loc7`='Thunderaan no tenía ni idea de los avances del Señor del Fuego. Antes de que mi Señor pudiera reaccionar, Sulfuras, el legendario martillo de Ragnaros, descargó un golpe mortal. Thunderaan cayó, derrotado.$B$BEl Señor del Fuego se dio un festín con la esencia de mi Señor, pero no consiguió consumirlo completamente.' WHERE `ID`=9335;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래서 라그나로스는 그다음에 뭘 했습니까?', `MaleText_loc4`='那么，拉格纳罗斯接下来做了什么？', `MaleText_loc5`='那麼，拉格納羅斯接下來做了什麼?', `MaleText_loc7`='¿Y qué hizo Ragnaros a continuación?', `FemaleText_loc1`='그래서 라그나로스는 그다음에 뭘 했습니까?', `FemaleText_loc4`='那么，拉格纳罗斯接下来做了什么？', `FemaleText_loc5`='那麼，拉格納羅斯接下來做了什麼?', `FemaleText_loc7`='¿Y qué hizo Ragnaros a continuación?' WHERE `ID`=9336;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라그나로스는 썬더란 님의 남은 정기를 정령을 봉인하는 부적에 넣은 다음 완벽하게 이등분했습니다. 그러곤 그 조각들을 자기 부관에게 나누어 주었습니다.', `MaleText_loc4`='桑德兰的精华的些许残留物存储在元素绑定护符中。拉格纳罗斯将护符打碎成两块，分给了他的两名士官……', `MaleText_loc5`='桑德蘭的精華的些許殘留物存儲在元素束縛護符中。拉格納羅斯將護符打碎成兩塊，分給了他的兩名副官...', `MaleText_loc7`='Lo poco que quedaba de la esencia de Thunderaan, se guardó en un talismán de vínculo elemental. A continuación, Ragnaros partió el talismán en dos partes perfectamente iguales. Entregó las piezas a sus tenientes...' WHERE `ID`=9337;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='던 발다르는 알터랙 계곡에서 얼라이언스의 위력이 가장 강한 지역입니다. 계곡의 북쪽에 자리 잡고 있는 던 발다르는 남쪽으로 진격하기 위한 중간 거점이라고 할 수 있습니다.$B$B던 발다르는 안전합니다.', `MaleText_loc4`='丹巴达尔是联盟在奥特兰克军力最强的地方。位于山谷北部的丹巴达尔是通往南部的军事要塞。$B$B丹巴达尔现在完好无损。', `MaleText_loc5`='丹巴達爾是聯盟在奧特蘭克山谷軍力最強的地方。位於山谷北部的丹巴達爾是通往南部的軍事要塞。$B$B丹巴達爾現在完好無損。', `MaleText_loc7`='Dun Baldar es el punto más álgido de poder de la Alianza en el Valle de Alterac. Enclavado en la parte norte del valle, Dun Baldar es el punto de partida de todos los avances hacia el sur.$B$BDun Baldar sigue intacto.' WHERE `ID`=9338;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='던 발다르는 알터랙 계곡에서 얼라이언스의 위력이 가장 강한 지역입니다. 계곡의 북쪽에 자리 잡고 있는 던 발다르는 남쪽으로 진격하기 위한 중간 거점이라고 할 수 있습니다.$B$B던 발다르는 파괴되어 재건 중입니다.', `MaleText_loc4`='丹巴达尔是联盟在奥特兰克军力最强的地方。位于山谷北部的丹巴达尔是通往南部的军事要塞。$B$B丹巴达尔已经被夷为平地，正在重建。', `MaleText_loc5`='丹巴達爾是聯盟在奧特蘭克軍力最強的地方。位於山谷北部的丹巴達爾是通往南部的軍事要塞。$B$B丹巴達爾已經被夷為平地，正在重建。', `MaleText_loc7`='Dun Baldar es el punto más álgido de poder de la Alianza en el Valle de Alterac. Enclavado en la parte norte del valle, Dun Baldar es el punto de partida de todos los avances hacia el sur.$B$BDun Baldar fue arrasado y está en plena reconstrucción.' WHERE `ID`=9339;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서리늑대 요새는 알터랙 계곡의 남쪽 구석에 자리하고 있으며, 오크족의 고향인 서리늑대 마을을 방어하고 있습니다. 알터랙 계곡의 모든 호드 영토는 이곳을 거점으로 뻗어나갑니다.$B$B서리늑대 요새는 안전합니다.', `MaleText_loc4`='霜狼要塞位于奥特兰克山谷的南部，是通往霜狼村的要塞，是名为霜狼的兽人氏族的家园。部落在奥特兰克山谷所有领土都从这儿衍生。$B$B霜狼要塞完好无损。', `MaleText_loc5`='霜狼要塞位於奧特蘭克山谷的南部，是通往霜狼村的要塞，是名為霜狼的獸人氏族的家園。部落在奧特蘭克山谷所有領土都從這兒衍生。$B$B霜狼要塞完好無損。', `MaleText_loc7`='El Bastión Lobo Gélido está en la parte sur del Valle de Alterac y protege la Aldea Lobo Gélido, el hogar del clan de orcos que lleva el mismo nombre. Todos los territorios de la Horda del Valle de Alterac se extienden desde este lugar de poder.$B$BEl Bastión Lobo Gélido está intacto.' WHERE `ID`=9340;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서리늑대 요새는 알터랙 계곡의 남쪽 구석에 있으며, 오크족의 고향인 서리늑대 마을을 방어하고 있습니다. 알터랙 계곡의 모든 호드 영토는 이곳을 거점으로 뻗어나갑니다.$B$B서리늑대 요새는 파괴되어 재건 중입니다.', `MaleText_loc4`='霜狼要塞位于奥特兰克山谷的南部，是通往霜狼村的要塞，是名为霜狼的兽人氏族的家园。部落在奥特兰克山谷所有领土都从这儿衍生。$B$B霜狼要塞被夷为平地，需要重建。', `MaleText_loc5`='霜狼要塞位於奧特蘭克山谷的南部，是通往霜狼村的要塞，是名為霜狼的獸人氏族的家園。部落在奧特蘭克山谷所有領土都從這兒衍生。$B$B霜狼要塞被夷為平地，需要重建。', `MaleText_loc7`='El Bastión Lobo Gélido está en la parte sur del Valle de Alterac y protege la Aldea Lobo Gélido, el hogar del clan de orcos que lleva el mismo nombre. Todos los territorios de la Horda del Valle de Alterac se extienden desde este lugar de poder.$B$BEl Bastión Lobo Gélido fue arrasado y está en plena reconstrucción.' WHERE `ID`=9341;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='던 발다르에 대해 말씀해 주십시오.', `MaleText_loc4`='告诉我关于丹巴达尔的事情。', `MaleText_loc5`='告訴我關於丹巴達爾的事情。', `MaleText_loc7`='Háblame sobre Dun Baldar.', `FemaleText_loc1`='던 발다르에 대해 말씀해 주십시오.', `FemaleText_loc4`='告诉我关于丹巴达尔的事情。', `FemaleText_loc5`='告訴我關於丹巴達爾的事情。', `FemaleText_loc7`='Háblame sobre Dun Baldar.' WHERE `ID`=9342;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서리늑대 요새에 대해 말씀해 주십시오.', `MaleText_loc4`='告诉我关于霜狼要塞的事情。', `MaleText_loc5`='告訴我關於霜狼要塞的事情。', `MaleText_loc7`='Háblame sobre el Bastión Lobo Gélido.', `FemaleText_loc1`='서리늑대 요새에 대해 말씀해 주십시오.', `FemaleText_loc4`='告诉我关于霜狼要塞的事情。', `FemaleText_loc5`='告訴我關於霜狼要塞的事情。', `FemaleText_loc7`='Háblame sobre el Bastión Lobo Gélido.' WHERE `ID`=9343;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='족쇄를 풀 열쇠를 찾았습니다만...', `MaleText_loc4`='这样，我发现了镣铐的钥匙……', `MaleText_loc5`='這樣，我發現了鐐銬的鑰匙...', `MaleText_loc7`='Bueno, he encontrado una llave de grilletes...', `FemaleText_loc1`='족쇄를 풀 열쇠를 찾았습니다만...', `FemaleText_loc4`='这样，我发现了镣铐的钥匙……', `FemaleText_loc5`='這樣，我發現了鐐銬的鑰匙...', `FemaleText_loc7`='Bueno, he encontrado una llave de grilletes...' WHERE `ID`=9344;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='열쇠를 찾았다고? 정말 그 열쇠가 맞아? 그러니까 이 족쇄를 풀 수 있는 열쇠냐는 말이지. 뭐, 한번 해보면 알 수 있겠지만!', `MaleText_loc4`='你找到钥匙啦？嗯，是那把钥匙吗？我指的是能打开这些枷锁的钥匙。$G先生:女士;，只有一种方法能证明！', `MaleText_loc5`='你找到鑰匙啦?嗯，是那把鑰匙嗎?我指的是能打開這些枷鎖的鑰匙。$G先生:女士;，只有一種方法能證明!', `MaleText_loc7`='¿Has encontrado una llave? ¿Y bien? ¿Es LA llave? ¿Es la llave que abre estos grilletes? Bueno, $gcaballero:señora;, ¡solo hay una forma de descubrirlo!' WHERE `ID`=9345;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 오늘 내 목숨을 구해준 사실을 무역회사의 모든 동료에게 알리도록 하지. 자, 이제 길을 떠나려면 짐을 최대한 줄여서 가야 하니까... 이 재봉용품과 가죽세공용품 중에서 골라보라고! 다시 한번 정말 고마웠어. 안녕!', `MaleText_loc4`='$n，我会让我所有的盟友朋友都知道你今天救了我的命。给你——我需要轻装上路，请你帮忙收下我的裁缝和制革物品！再次感谢你——再见！', `MaleText_loc5`='$n，我會讓我所有的盟友朋友都知道你今天救了我的命。給你─我需要輕裝上路，請你幫忙收下我的裁縫和製皮物品!再次感謝你─再見!', `MaleText_loc7`='$n, me aseguraré de que todos mis amigos del Cártel sepan que me has salvado la vida. Necesito viajar ligero de peso así que, por favor, coge lo que quieras de mi alijo de suministros de sastrería y peletería. ¡Gracias de nuevo, hasta luego!' WHERE `ID`=9346;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너 이제 왕이다! 왕이야! 모두 고르독 왕인 $n 폐하에게 경례!$B$B너 이제 왕 됐으니까 부하들이 공물 바칠 거야! 왕, 몇 놈이나 살려뒀지?', `MaleText_loc4`='你现在是首领啦！你是我们的王！向戈多克王$n致敬！$B$B既然你是首领，所有的手下都会为你上贡的！你留下一些活口的，是吗？', `MaleText_loc5`='你現在是首領啦!你是我們的王!向戈多克王$n致敬!$B$B既然你是首領，所有的手下都會為你上貢的!你留下一些活口的，是嗎?', `MaleText_loc7`='¡Tú gran $gjefe:jefa; ahora! ¡Tú $grey:reina;! ¡Todos saludar $gal rey:a la reina; $n de Gordok!$B$B¡Ahora que tú ser $gjefe:jefa;, todos los esbirros te darán un tributo! ¿Has dejao algunos vivos, eh, $gjefe:jefa;?' WHERE `ID`=9347;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런! 왕이 죽었군! 야호! 어... 새로운 왕에게 경례!', `MaleText_loc4`='哦不！国王死啦！呃……向新国王致敬！啊！', `MaleText_loc5`='哦不!國王死啦!呃...向新國王致敬!啊!', `MaleText_loc7`='¡OH, NO! ¡$gEl rey tá muerto:la reina tá muerta;! Mmm... ¡Viva $gel nuevo rey:la nueva reina;! ¡Sí!' WHERE `ID`=9348;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='열쇠를 가지려면 먼저 날 잡아야 할걸!', `MaleText_loc4`='想要钥匙的话，就来追我吧！', `MaleText_loc5`='想要鑰匙的話，就來追我吧!', `MaleText_loc7`='¡Si quieres la llave tendrás que cogerme!' WHERE `ID`=9349;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나랑 놀이 하나 할래, 말썽꾼 양반?', `MaleText_loc4`='你想玩个游戏吗，自以为是的人？', `MaleText_loc5`='你想玩個遊戲嗎，自以為是的人?', `MaleText_loc7`='¿Quieres jugar a un juego, $gapestoso:apestosa;?' WHERE `ID`=9350;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 자유의 땅으로 통하는 열쇠를 갖고 있지롱! 나 잡아봐! 그럼 무슨 소린지 알게 될 거야!', `MaleText_loc4`='我拥有通往那里的钥匙！跟着我来吧，你会看到的！', `MaleText_loc5`='我擁有通往那裡的鑰匙!跟著我來吧，你會看到的!', `MaleText_loc7`='¡Tengo la llave de las tierras de la libertad! ¡Persígueme y verás!' WHERE `ID`=9351;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놀이? 미쳤어?', `MaleText_loc4`='游戏？你疯了吗？', `MaleText_loc5`='遊戲?你瘋了嗎?', `MaleText_loc7`='¿Un juego? ¿Estás mal de la cabeza?', `FemaleText_loc1`='놀이? 미쳤어?', `FemaleText_loc4`='游戏？你疯了吗？', `FemaleText_loc5`='遊戲?你瘋了嗎?', `FemaleText_loc7`='¿Un juego? ¿Estás mal de la cabeza?' WHERE `ID`=9352;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='따라올 테면 따라와 봐! 뒤도 안 돌아보고 튈 테니까!', `MaleText_loc4`='如果你敢的话就来追我吧！我会毫不犹豫地奔跑的！', `MaleText_loc5`='如果你敢的話就來追我吧!我會毫不猶豫地奔跑的!', `MaleText_loc7`='¡Cógeme si puedes! ¡Corro tan rápido como el viento!' WHERE `ID`=9353;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직도 살아있네? 신기해라! 도망가는 내 꽁지나 구경해라!', `MaleText_loc4`='还活着吗？惊讶吧。眼睁睁看着我逃跑吧！', `MaleText_loc5`='還活著嗎?驚訝吧。眼睜睜看著我逃跑吧!', `MaleText_loc7`='¿Sigues con vida? Me sorprendes. ¡Mira cómo corro!' WHERE `ID`=9354;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 조그만 게...', `MaleText_loc4`='为什么你这么矮小……', `MaleText_loc5`='為什麼你這麼矮小...', `MaleText_loc7`='Maldito...', `FemaleText_loc1`='이 조그만 게...', `FemaleText_loc4`='为什么你这么矮小……', `FemaleText_loc5`='為什麼你這麼矮小...', `FemaleText_loc7`='Maldito...' WHERE `ID`=9355;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 들어둬라. 꼭 잡고 말 테다, 이 마귀야! 잡히면 끝장인 줄 알아!', `MaleText_loc4`='记住我的话，我会抓住你的，小鬼。我会的！', `MaleText_loc5`='記住我的話，我會抓住你的，小鬼。我會的!', `MaleText_loc7`='Escúchame bien, te cogeré, diablillo. ¡Y te vas a enterar cuando lo haga!', `FemaleText_loc1`='잘 들어둬라. 꼭 잡고 말 테다, 이 마귀야! 잡히면 끝장인 줄 알아!', `FemaleText_loc4`='记住我的话，我会抓住你的，小鬼。我会的！', `FemaleText_loc5`='記住我的話，我會抓住你的，小鬼。我會的!', `FemaleText_loc7`='Escúchame bien, te cogeré, diablillo. ¡Y te vas a enterar cuando lo haga!' WHERE `ID`=9356;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 날 해치려 들까? 우린 사이 좋은 친구가 될 수도 있는데 말이야!', `MaleText_loc4`='为什么你想要伤害我！？我们可以成为朋友的！', `MaleText_loc5`='為什麼你想要傷害我!?我們可以成為朋友的!', `MaleText_loc7`='¿Por qué ibas a querer hacerme daño? ¡Vamos! ¡Podemos ser amigos!' WHERE `ID`=9357;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇게 울상만 짓지 말고 좀 웃어봐!', `MaleText_loc4`='皱皱眉头！', `MaleText_loc5`='皺皺眉頭!', `MaleText_loc7`='¡Deja de fruncir el ceño!' WHERE `ID`=9358;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 손에 죽을 줄 알아!', `MaleText_loc4`='去死吧！', `MaleText_loc5`='去死吧!', `MaleText_loc7`='¡MUERE!', `FemaleText_loc1`='내 손에 죽을 줄 알아!', `FemaleText_loc4`='去死吧！', `FemaleText_loc5`='去死吧!', `FemaleText_loc7`='¡MUERE!' WHERE `ID`=9359;
