UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다 끝났어. 너랑 친구 안 할래!', `MaleText_loc4`='这是底线，你不再是我的朋友啦！', `MaleText_loc5`='這是底線，你不再是我的朋友啦!', `MaleText_loc7`='¡Se acabó, no somos amigos!' WHERE `ID`=9361;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최후를 맞을 준비나 하시지.', `MaleText_loc4`='准备跟你的缔造者见面吧。', `MaleText_loc5`='準備跟你的締造者見面吧。', `MaleText_loc7`='Prepárate para conocer a tu creador.', `FemaleText_loc1`='최후를 맞을 준비나 하시지.', `FemaleText_loc4`='准备跟你的缔造者见面吧。', `FemaleText_loc5`='準備跟你的締造者見面吧。', `FemaleText_loc7`='Prepárate para conocer a tu creador.' WHERE `ID`=9362;
