UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악마가 풀려났다! 서둘러 녀석을 막아야 한다!', `MaleText_loc4`='恶魔逃脱了！我们必须尽快制止他！', `MaleText_loc5`='惡魔逃脫了!我們必須儘快制止他!', `MaleText_loc7`='¡El demonio está suelto! ¡Rápido, tenemos que cogerle!', `FemaleText_loc1`='악마가 풀려났다! 서둘러 녀석을 막아야 한다!', `FemaleText_loc4`='恶魔逃脱了！我们必须尽快制止他！', `FemaleText_loc5`='惡魔逃脫了!我們必須儘快制止他!', `FemaleText_loc7`='¡El demonio está suelto! ¡Rápido, tenemos que cogerle!' WHERE `ID`=9364;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새 왕이라고? 지금 무슨 얘기를 하고 있는 건지?', `MaleText_loc4`='我是新国王？你在说什么？', `MaleText_loc5`='我是新國王?你在說什麼?', `MaleText_loc7`='¿Soy el nuevo rey? ¿De qué estás hablando?', `FemaleText_loc1`='새 왕이라고? 지금 무슨 얘기를 하고 있는 건지?', `FemaleText_loc4`='我是新国王？你在说什么？', `FemaleText_loc5`='我是新國王?你在說什麼?', `FemaleText_loc7`='¿Soy la nueva reina? ¿De qué estás hablando?' WHERE `ID`=9365;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전부 왕의 부하다. 천둥발 크리그, 경비병 셋, 크롬크러쉬 대장, 그리고 정찰병이 새 왕에게 공물 바친다. 부하를 죽이면 공물 못 받는다! 부하 한 놈씩 살려둘 때마다 공물을 더 받는다. 모두 살려두면 아주 큰 공물 받을 거다!$B$B암, 그렇고말고!', `MaleText_loc4`='老大手下的所有下属——践踏者克雷格、三名守卫、克罗卡斯和观察者——都为新的国王献上贡品。如果你杀死了一名下属，这名下属就不能为新国王上贡啦！留下的活口越多，你得到的贡品就越多。别杀他们，你会得到很多东西的！$B$B就是这样的！', `MaleText_loc5`='老大手下的所有下屬─踐踏者克雷格、三名守衛、隊長克羅卡斯和觀察者─都為新的國王獻上貢品。如果你殺死了一名下屬，這名下屬就不能為新國王上貢啦!留下的活口越多，你得到的貢品就越多。別殺他們，你會得到很多東西的!$B$B就是這樣的!', `MaleText_loc7`='Todos los esbirros del jefe: el vapuleador Kreeg, los tres guardias, el capitán Kromcrush y el observador, dar tributo $gal nuevo jefe:a la nueva jefa;. Si te cargas a un esbirro, ese esbirro no podrá darte un tributo. Por cada uno que mantengas con vida, más tributo recibirás. ¡Mantenlos a todos con vida y tú recibir el GRAN tributo!$B$B¡Sí!' WHERE `ID`=9366;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 그렇다면... 공물을 바쳐 보아라!', `MaleText_loc4`='那么……把贡品给我吧！', `MaleText_loc5`='那麼...把貢品給我吧!', `MaleText_loc7`='Bueno... Pues enséñame el tributo...', `FemaleText_loc1`='좋아, 그렇다면... 공물을 바쳐 보아라!', `FemaleText_loc4`='那么……把贡品给我吧！', `FemaleText_loc5`='那麼...把貢品給我吧!', `FemaleText_loc7`='Bueno... Pues enséñame el tributo...' WHERE `ID`=9367;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어째서 굳이 함정을 고쳐야 합니까? 왜 그냥 경비병들을 처치하면 안 됩니까?', `MaleText_loc4`='为什么我要做修好陷阱这样的麻烦事儿？为什么不按老办法杀死守卫？', `MaleText_loc5`='為什麼我要做修好陷阱這樣的麻煩事兒?為什麼不按老辦法殺死守衛?', `MaleText_loc7`='¿Por qué debería molestarme en arreglar la trampa? ¿Por qué no eliminar al guardia como toda la vida?', `FemaleText_loc1`='어째서 굳이 함정을 고쳐야 합니까? 왜 그냥 경비병들을 처치하면 안 됩니까?', `FemaleText_loc4`='为什么我要做修好陷阱这样的麻烦事儿？为什么不按老办法杀死守卫？', `FemaleText_loc5`='為什麼我要做修好陷阱這樣的麻煩事兒?為什麼不按老辦法殺死守衛?', `FemaleText_loc7`='¿Por qué debería molestarme en arreglar la trampa? ¿Por qué no eliminar al guardia como toda la vida?' WHERE `ID`=9368;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 저 멍청이들의 밥이 되길 기다리다 알아낸 바로는... 여기 오우거를 다 처치할 필요는 없다는 거지.$B$B그제는 오우거들이 고르독 왕이 즉위한 것에 대해서 하루종일 수다를 떨더라고. 자세히 들어보니까, 고르독이 이전 왕을 죽이고 그 자리를 차지했다지 뭐야. 그리고 그 이전 왕의 부하들, 그러니까 고르독이 살려둔 부하들은 즉시 새 왕에게 충성의 맹세를 했다네.$B$B그러니까 혹시 알아? 당신이 살려둔 오우거가 훗날 당신에게 충성을 맹세할지... 말하자면 세상 일이 다 그렇다는 거지.', `MaleText_loc4`='嗯，从我跟食人魔的交战情况来看……你不必逐一杀死这儿的所有食人魔。$B$B就在前几天戈多克大王恢复权力，杀死以前的国王取而代之的时候，食人魔纷纷离开此地。嗯，国王的追随者们——戈多克没有要他们的命——立即发誓效忠新国王。$B$B谁知道呢——你饶恕的食人魔说不定会效忠于你呢……当然，这是打个比方！', `MaleText_loc5`='嗯，從我跟巨魔的交戰情況來看...你不必逐一殺死這兒的所有巨魔。$B$B就在前幾天戈多克大王恢復權力，殺死以前的國王取而代之的時候，巨魔紛紛離開此地。嗯，國王的追隨者們─戈多克沒有要他們的命─立即發誓效忠新國王。$B$B誰知道呢─你饒恕的巨魔說不定會效忠於你呢...當然，這是打個比方!', `MaleText_loc7`='Bueno, por lo que oí mientras estaba esperando a que esos palurdos me comiesen... quizás no sea necesario matar a todos los ogros que encuentres.$B$BEl otro día, los ogros hablaban todo el rato de cómo llegó el rey Gordok al poder... Mató al anterior rey y ocupó su lugar. Los esbirros del rey, a los que Gordok perdonó la vida, juraron lealtad inmediatamente al nuevo rey.$B$BQuién sabe... A lo mejor el ogro que salvaste podría ser... ¡En sentido figurado, por supuesto!' WHERE `ID`=9369;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이벤트 작동 중', `FemaleText_loc4`='这个东西正在起作用。', `FemaleText_loc5`='這個東西正在起作用。', `FemaleText_loc7`='ESTE EVENTO FUNCIONA.' WHERE `ID`=9370;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 새 왕이지? 새 왕 만세!$B$B이 크리그 고르독 술 보게 해 준다. 술 하면 오우거 술, 오우거 술 하면 고르독 술! 나한테서 좀 살 생각 없어, 왕?!', `MaleText_loc4`='你现在是首领了，对吗？祝新国王长命百岁！$B$B克雷格让你看看戈多克酒。食人魔酒是所有酒中的极品，戈多克酒则是食人魔酒中的极品！你能从我这里买一些，是不是国王？！', `MaleText_loc5`='你現在是首領了，對嗎?祝新國王長命百歲!$B$B克雷格讓你看看戈多克酒。巨魔酒是所有酒中的極品，戈多克酒則是巨魔酒中的極品!你能從我這裡買一些，是不是國王?!', `MaleText_loc7`='¿Tú ser $gnuevo jefe:nueva jefa;, no? ¡Viva $gel nuevo rey:la nueva reina;!$B$BKreeg dejarte ver el garrafón de Gordok. ¡El garrafón ogro ser mejor garrafón de todos, y garrafón de Gordok ser el mejor de todos los garrafones ogros! ¿Quizás quieras comprarme algo, $gjefe:jefa;?' WHERE `ID`=9371;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 술이 있는지 좀 보여 줘, 크리그.', `MaleText_loc4`='克雷格，让我看看你都卖些什么酒。', `MaleText_loc5`='克雷格，讓我看看你都賣些什麼酒。', `MaleText_loc7`='Enséñame el garrafón que tienes a la venta, Kreeg.', `FemaleText_loc1`='어떤 술이 있는지 좀 보여 줘, 크리그.', `FemaleText_loc4`='克雷格，让我看看你都卖些什么酒。', `FemaleText_loc5`='克雷格，讓我看看你都賣些什麼酒。', `FemaleText_loc7`='Enséñame el garrafón que tienes a la venta, Kreeg.' WHERE `ID`=9372;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사다니 그게 무슨 소리지?! 난 이제 왕인데... 왕은 뭐든 마음대로 할 수 있는 것 아닌가?', `MaleText_loc4`='你什么意思，购买？！我现在是国王……做国王棒极了！', `MaleText_loc5`='你什麼意思，購買?!我現在是國王...做國王棒極了!', `MaleText_loc7`='¿Cómo que comprar? Soy el rey ahora... ¡Y me gusta!', `FemaleText_loc1`='사다니 그게 무슨 소리지?! 난 이제 왕인데... 왕은 뭐든 마음대로 할 수 있는 것 아닌가?', `FemaleText_loc4`='你什么意思，购买？！我现在是国王……做国王棒极了！', `FemaleText_loc5`='你什麼意思，購買?!我現在是國王...做國王棒極了!', `FemaleText_loc7`='¿Cómo que comprar? Soy la reina ahora... ¡Y me gusta!' WHERE `ID`=9373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 자라나기 시작합니다!', `MaleText_loc4`='%s开始生长啦！', `MaleText_loc5`='%s開始生長啦!', `MaleText_loc7`='¡%s comienza a crecer!' WHERE `ID`=9374;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 계속해서 자라납니다!', `MaleText_loc4`='%s继续生长着！', `MaleText_loc5`='%s繼續生長!', `MaleText_loc7`='¡%s sigue creciendo!' WHERE `ID`=9375;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 끝까지 자라났습니다!', `MaleText_loc4`='%s已经完全长大了！', `MaleText_loc5`='%s已經完全長大啦!', `MaleText_loc7`='¡%s ha crecido hasta alcanzar su tamaño completo!' WHERE `ID`=9376;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왕! 좋아, 부하들에게서 공물을 받을 준비가 되면 내게 알려주라고!', `MaleText_loc4`='好吧老大，当你想要下属为你上贡的时候，就告诉我！', `MaleText_loc5`='好吧老大，當你想要下屬為你上貢的時候，就告訴我!', `MaleText_loc7`='Vale, $gjefe:jefa;, cuando quieras el tributo de los esbirros, ¡decírmelo!' WHERE `ID`=9377;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고르독 전투 위장을 발라라!', `MaleText_loc4`='绘制戈多克战争之画！', `MaleText_loc5`='繪製戈多克戰爭之畫!', `MaleText_loc7`='¡Poner la pintura de guerra Gordok!', `FemaleText_loc1`='고르독 전투 위장을 발라라!', `FemaleText_loc4`='绘制戈多克战争之画！', `FemaleText_loc5`='繪製戈多克戰爭之畫!', `FemaleText_loc7`='¡Poner la pintura de guerra Gordok!' WHERE `ID`=9378;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이방인이여, 이곳을 떠나세요. 그렇지 않으면 그대도 다른 이들처럼 재가 되어버릴 것입니다.', `FemaleText_loc4`='陌生人，离开这儿吧，免得送命，它会吃掉它接触到的一切东西的。', `FemaleText_loc5`='陌生人，離開這兒吧，免得送命，它會吃掉它接觸到的一切東西的。', `FemaleText_loc7`='Vete de aquí, $gforastero:forastera;, o te consumirá como ha hecho con todo lo que toca.' WHERE `ID`=9379;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 무슨 일이 있었던 거죠?', `MaleText_loc4`='精灵，这儿发生了什么事？', `MaleText_loc5`='精靈，這兒發生了什麼事?', `MaleText_loc7`='¿Qué ha ocurrido aquí, espíritu?', `FemaleText_loc1`='여기서 무슨 일이 있었던 거죠?', `FemaleText_loc4`='精灵，这儿发生了什么事？', `FemaleText_loc5`='精靈，這兒發生了什麼事?', `FemaleText_loc7`='¿Qué ha ocurrido aquí, espíritu?' WHERE `ID`=9380;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='명가에 대해 아시나요? 셴드랄라는요?', `FemaleText_loc4`='你知道上层精灵吗？你知道辛德拉古吗？', `FemaleText_loc5`='你知道精靈貴族嗎?你知道辛德拉古嗎?', `FemaleText_loc7`='¿Conoces a los Altonato? ¿Los Shen''dralar?' WHERE `ID`=9381;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명가에 대해선 잘 모르고 셴드랄라라니, 처음 듣는군요.', `MaleText_loc4`='我对上层精灵知之甚少，对辛德拉更是一无所知。', `MaleText_loc5`='我對精靈貴族知之甚少，對辛德拉更是一無所知。', `MaleText_loc7`='Sé muy poco de los Altonato y nada de los Shen''dralar.', `FemaleText_loc1`='명가에 대해선 잘 모르고 셴드랄라라니, 처음 듣는군요.', `FemaleText_loc4`='我对上层精灵知之甚少，对辛德拉更是一无所知。', `FemaleText_loc5`='我對精靈貴族知之甚少，對辛德拉更是一無所知。', `FemaleText_loc7`='Sé muy poco de los Altonato y nada de los Shen''dralar.' WHERE `ID`=9382;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='셴드랄라는 아즈샤라 여왕의 가장 신임받는 비전술사였어요. 온통 성벽으로 둘러싸인 바로 이곳에서 여왕이 맡긴 중요한 일들을 비밀리에 처리했지요.$B$B영원의 샘이 파괴되고 그로 인해 나이트 엘프 명가를 비롯한 모든 계층이 권태에 빠지자 엘드레탈라스의 왕자 토르텔드린은 서쪽 전당에 흩어져 있는 수정탑들을 짓기 시작했답니다.', `FemaleText_loc4`='辛德拉古是艾萨拉女王最器重的奥术学家。女王最重要的物品都在这些高大的城墙内秘密制造完成。$B$B永恒之井被破坏后，上层精灵陷入浑浑噩噩的境地，一支较小的暗夜精灵氏族，埃雷萨拉斯的王子托塞德林开始建造水晶塔，你可以在西侧的城墙那儿看到那些分散在各处的水晶塔。', `FemaleText_loc5`='辛德拉古是艾薩拉女王最器重的秘法師。女王最重要的物品都在這些高大的城牆內秘密製造完成。$B$B永恆之井被破壞後，精靈貴族陷入渾渾噩噩的境地，一支較小的夜精靈氏族，埃德薩拉斯的王子托塞德林開始建造水晶塔，你可以在西側的城牆那兒看到那些分散在各處的水晶塔。', `FemaleText_loc7`='Los Shen''dralar eran los arcanistas más venerados de la reina Azshara. Fue entre estos muros, donde se cumplieron las demandas de la reina, a menudo en secreto.$B$BDespués de la destrucción del pozo y el subsiguiente letargo que se apoderó de los Altonato y de las sectas menores de elfos de la noche, el príncipe de Eldre''Thalas, Tortheldrin, comenzó la construcción de las torres que ves en las salas del ala oeste.' WHERE `ID`=9383;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='토르텔드린 왕자는 거대한 마법진 안에 어마어마한 힘을 가진 악마를 가두려는 계획을 세웠지요. 그 마법진은 수정탑들이 전달하는 눈에 보이지 않는 어떤 마력에 의해 작동하는 것 같았어요.$B$B이몰타르는 그 안에 갇혀 있는 동안 엘드레탈라스 주민들에게 힘의 원천이 되었습니다.', `FemaleText_loc4`='王子策划将拥有巨大力量的恶魔伊莫塔尔禁锢到一个巨大的力场中。水晶塔能将潜在的能量汇集到这个力场中。$B$B一旦被囚禁，恶魔将成为埃雷萨拉斯人民的能量来源。', `FemaleText_loc5`='王子策劃將擁有巨大力量的惡魔伊莫塔爾禁錮到一個巨大的力場中。水晶塔能將潛在的能量彙集到這個力場中。$B$B一旦被囚禁，惡魔將成為埃德薩拉斯人民的能量來源。', `FemaleText_loc7`='El Príncipe planeó encarcelar a un demonio de gran poder en un campo de fuerza. Las torres canalizarían las energías latentes hacia el campo, manteniéndolo operativo.$B$BMientras estuviera atrapado, Immol''thar serviría como energía para el pueblo de Eldre''Thalas.' WHERE `ID`=9384;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 말씀해 주십시오.', `MaleText_loc4`='请继续。', `MaleText_loc5`='請繼續。', `MaleText_loc7`='Continúa, por favor.', `FemaleText_loc1`='계속 말씀해 주십시오.', `FemaleText_loc4`='请继续。', `FemaleText_loc5`='請繼續。', `FemaleText_loc7`='Continúa, por favor.' WHERE `ID`=9385;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흥미롭군요. 계속 말씀해 주십시오.', `MaleText_loc4`='真令人着迷啊。请继续。', `MaleText_loc5`='真令人著迷啊。請繼續。', `MaleText_loc7`='Fascinante. Continúa, por favor.', `FemaleText_loc1`='흥미롭군요. 계속 말씀해 주십시오.', `FemaleText_loc4`='真令人着迷啊。请继续。', `FemaleText_loc5`='真令人著迷啊。請繼續。', `FemaleText_loc7`='Fascinante. Continúa, por favor.' WHERE `ID`=9386;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마법진이 이몰타르에게서 흡수한 힘이 명가의 마력을 유지시켜 주었고, 엘드레탈라스 성벽 안에 사는 이들이 갖고 있는 마법에 대한 끝없는 갈망을 충족시켜 주었습니다.$B$B그런데, 수천 년이 지나면서 엘드레탈라스의 생명력을 유지하면서 이몰타르를 가두어 두는 데 필요한 마력이 필요하게 됐어요. 이몰타르를 가두어 둠으로써 얻는 힘보다 그를 가두는 데 더 많은 마력이 필요해진 것이죠. 즉, 흑자에서 적자로 바뀐 겁니다.', `FemaleText_loc4`='汲取的能量能维持上层精神的魔力，使埃雷萨拉斯的人民满足他们对魔法无尽而持续增长的渴求。$B$B数千年过去了，用于监禁恶魔伊莫塔尔以及维系埃雷萨拉斯人民生命的力量开始减弱。监禁恶魔所需的魔法就要超过所能汲取的魔法。曾经的能量机制已经不复存在。', `FemaleText_loc5`='汲取的能量能維持精靈貴族的魔力，使埃德薩拉斯的人民滿足他們對魔法無盡而持續增長的渴求。$B$B數千年過去了，用於監禁惡魔伊莫塔爾以及維繫埃德薩拉斯人民生命的力量開始減弱。監禁惡魔所需的魔法就要超過所能汲取的魔法。曾經的能量機制已經不復存在。', `FemaleText_loc7`='Las energías absorbidas sustentarían la magia de los Altonato, permitiendo a aquellos que estaban en Eldre''Thalas alimentar su infinita y creciente magia.$B$BMiles de años pasaron, y el poder requerido para mantener encarcelado a Immol''thar a la vez que se mantenía la vida de Eldre''Thalas, comenzó a cambiar. El coste de mantener a Immol''thar, comenzó a eclipsar la cantidad de energía que podía ser absorbida y distribuida. La antigua red perfecta se convirtió en una gran pérdida.' WHERE `ID`=9387;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러니까 또 뭔가를 죽여야 한다는 얘기인가요?', `MaleText_loc4`='我要杀一些东西，是吗？', `MaleText_loc5`='我要殺一些東西，是嗎?', `MaleText_loc7`='Voy a tener que matar algo, ¿no?', `FemaleText_loc1`='그러니까 또 뭔가를 죽여야 한다는 얘기인가요?', `FemaleText_loc4`='我要杀一些东西，是吗？', `FemaleText_loc5`='我要殺一些東西，是嗎?', `FemaleText_loc7`='Voy a tener que matar algo, ¿no?' WHERE `ID`=9388;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사실, 엘드레탈라스의 마당과 전당을 배회하고 있는 명가의 영혼들은 고르독 오우거나 사티로스의 침략으로 살해된 것이 아닙니다. 바로 토르텔드린 왕자에게 죽임을 당한 것이지요!', `FemaleText_loc4`='你所见到的那些在埃雷萨拉斯的庭院和城墙附近游荡的上层精灵灵魂不是被戈多克食人魔或萨特所杀，而是死于王子之手！', `FemaleText_loc5`='你所見到的那些在埃德薩拉斯的庭院和城牆附近遊蕩的精靈貴族鬼魂不是被戈多克巨魔或薩特所殺，而是死於王子之手!', `FemaleText_loc7`='Los fantasmas Altonato que ves vagando por el patio y las salas de Eldre''Thalas fueron asesinados, no por ogros Gordok invasores ni sátiros, ¡sino por el mismísimo Príncipe!' WHERE `ID`=9389;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 끝없는 비극의 세상에서 살고 있군요.', `MaleText_loc4`='我们生活在无尽的悲剧中。', `MaleText_loc5`='我們生活在無盡的悲劇中。', `MaleText_loc7`='Vivimos en un mundo de tragedia eterna.', `FemaleText_loc1`='우리는 끝없는 비극의 세상에서 살고 있군요.', `FemaleText_loc4`='我们生活在无尽的悲剧中。', `FemaleText_loc5`='我們生活在無盡的悲劇中。', `FemaleText_loc7`='Vivimos en un mundo de tragedia eterna.' WHERE `ID`=9390;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='토르텔드린 왕자는 불멸의 삶과 무한한 힘을 위해 주민들을 살해했습니다. 한 때는 수천 명이 함께 나누던 마력을 이제는 토르텔드린 왕자와 셴드랄라 광신도들이 독점하고 있지요. 소수의 생존자들이 이몰타르를 계속 가두어 놓기 위해 수정탑에 직접 마력을 불어넣고 있습니다.$B$B그 악마가 풀려나기라도 한다면 한때는 위대한 비전술의 보루였던 이곳의 유적들은 완전히 파괴될 거예요.', `FemaleText_loc4`='王子为了获得永恒的生命和无尽的力量，杀死了许多人。数千人的力量全部汇集到王子和辛德拉狂热者身上。那些少数的幸存者不停地向水晶塔输送能量来禁锢恶魔伊莫塔尔。$B$B如果恶魔挣脱束缚，它一定会毁掉这座曾经繁荣辉煌的魔法都市。', `FemaleText_loc5`='王子為了獲得永恆的生命和無盡的力量，殺死了許多人。曾經在數千人中分配的力量現在全部彙集到王子和辛德拉狂熱者身上。那些少數的倖存者不停地向水晶塔輸送能量來禁錮惡魔伊莫塔爾。$B$B一旦惡魔掙脫束縛，他一定會毀掉這片曾經繁榮的秘法之地。', `FemaleText_loc7`='Fueron destruidos para preservar la vida inmortal del Príncipe y aumentar sus ilimitados poderes. El poder antiguamente dividido entre miles, ahora solo pertenece al príncipe y los zelotes de Shen''dralar. Los que sobrevivieron, emanan poder directamente en las torres para mantener encarcelado a Immol''thar.$B$BSi el demonio rompiese sus cadenas, seguramente destruiría lo poco que queda de este antiguo bastión de los poderes arcanos.' WHERE `ID`=9391;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 슬픈 얘기로군요. 잘 들었습니다.', `MaleText_loc4`='很悲伤的故事。谢谢你，灵魂。', `MaleText_loc5`='很悲傷的故事。謝謝你，靈魂。', `MaleText_loc7`='Una historia muy triste. Gracias, espíritu.', `FemaleText_loc1`='아주 슬픈 얘기로군요. 잘 들었습니다.', `FemaleText_loc4`='很悲伤的故事。谢谢你，灵魂。', `FemaleText_loc5`='很悲傷的故事。謝謝你，靈魂。', `FemaleText_loc7`='Una historia muy triste. Gracias, espíritu.' WHERE `ID`=9392;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 네가 왕이야! 위대한 고르독의 멍멍이!', `MaleText_loc4`='卑微的家伙，你现在是个男人啦！', `MaleText_loc5`='卑微的傢伙，你現在是個男人啦!', `MaleText_loc7`='¡Ser jefe ahora, perro!' WHERE `ID`=9393;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 왕이라고? 당연하지! 그럼 펜구스 넌 고르독의 새 왕을 위해 뭘 할거지?', `MaleText_loc4`='我是，是吗？芬古斯，你给戈多克大王的新门徒带来了什么？', `MaleText_loc5`='我是，是嗎?芬古斯，你給戈多克大王的新門徒帶來了什麼?', `MaleText_loc7`='¿Lo soy, lo soy? Bueno... ¿Qué tienes para el nuevo perro de Gordok, Fengus?', `FemaleText_loc1`='내가 왕이라고? 당연하지! 그럼 펜구스 넌 고르독의 새 왕을 위해 뭘 할거지?', `FemaleText_loc4`='我是，是吗？芬古斯，你给戈多克大王的新门徒带来了什么？', `FemaleText_loc5`='我是，是嗎?芬古斯，你給戈多克大王的新門徒帶來了什麼?', `FemaleText_loc7`='¿Lo soy, lo soy? Bueno... ¿Qué tienes para el nuevo perro de Gordok, Fengus?' WHERE `ID`=9394;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='펜구스가 너 거칠게 만들어 주지! 미친 것처럼! 크아악!', `MaleText_loc4`='卫兵芬古斯令你变得凶残！疯狂！啊！', `MaleText_loc5`='衛兵芬古斯令你變得兇殘!瘋狂!啊!', `MaleText_loc7`='¡Fengus hacerte fiero! ¡Loco! ¡AAARR!' WHERE `ID`=9396;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왕이 제대로 이겨버렸네?! 어떻게 슬립킥을 속였담?? 하지만 슬립킥은 똑똑하니까 다음번엔 어림없어! 하하!$B$B이제 아무도 슬립킥 못 속여. 슬립킥 약속해!', `MaleText_loc4`='你可找到我啦，头儿！斯里基克陷入的大块的冰块中！好在我动作敏捷，很快就逃了出来！哈哈！$B$B或许冰块很快就会融化……', `MaleText_loc5`='你可難倒我啦，老大!你怎麼能逃出斯里基克那一關呢??好在我動作敏捷，很快就逃了出來!哈哈!$B$B沒有人逃的過斯里基克那一關。斯里基克萬歲!', `MaleText_loc7`='¡Tú traer buen jefe! ¿¿Cómo pasar por Slip''kik?? ¡Yo listo, mirar la próxima vez! ¡Arr, arr!$B$BNadie pasar por Slip''kik nunca más. ¡¡Slip''kik prometer!!' WHERE `ID`=9397;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호오, 그렇게 머리가 좋으시다고? 도대체 네가 얼마나 똑똑하다고 생각하는 거야, 슬립킥?', `MaleText_loc4`='是，你真是个笨蛋。斯里基克，你认为自己有多聪明？', `MaleText_loc5`='是，你真是個笨蛋。斯里基克，你認為自己有多聰明?', `MaleText_loc7`='Sí, tienes un gran cerebro... ¿Cómo de listo te crees que eres, Slip''kik?', `FemaleText_loc1`='호오, 그렇게 머리가 좋으시다고? 도대체 네가 얼마나 똑똑하다고 생각하는 거야, 슬립킥?', `FemaleText_loc4`='是，你真是个笨蛋。斯里基克，你认为自己有多聪明？', `FemaleText_loc5`='是，你真是個笨蛋。斯里基克，你認為自己有多聰明?', `FemaleText_loc7`='Sí, tienes un gran cerebro... ¿Cómo de listo te crees que eres, Slip''kik?' WHERE `ID`=9398;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왕, 나 얼마나 똑똑한지 보여주지! 이제 왕은 강력한 마법 모조로 더욱 똑똑해질 거야!$B$B엄... 어쩌면 마법을 슬립킥한테 써 볼까? 그것 참 좋은 생각이네...', `MaleText_loc4`='头儿，我会让你看看我有多聪明的！有了这些强大的魔精，你会更聪明的！$B$B嗯……我应该用在自己身上……', `MaleText_loc5`='國王陛下，我會讓你看看我有多聰明的!有了這些強大的魔法魔精，你會更聰明的!$B$B嗯...或許斯里基克在自己身上使用魔法。那會是個不錯的點子...', `MaleText_loc7`='¡Yo enseñarte lo listo que soy, $gjefe:jefa;! ¡Tú ser extra inteligente con poderoso mojo mágico ahora!$B$BMmm... Quizás Slip''kik usar magia consigo mismo. Sería una buena idea...' WHERE `ID`=9399;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고르독의 왕이시여! 진정한 고르독의 일인자로군!', `MaleText_loc4`='你是戈多克的国王！你是至高无上的王！', `MaleText_loc5`='你是戈多克的國王!你是至高無上的王!', `MaleText_loc7`='¡Tú ser $grey:reina; de los Gordok! ¡El número uno!' WHERE `ID`=9400;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 그냥 "왕"이라고 부르도록... 그런데 나한테 줄 거라도 있느냐!', `MaleText_loc4`='叫我“国王”。你为我带来了什么！', `MaleText_loc5`='叫我「國王」。你為我帶來了什麼!', `MaleText_loc7`='Llámame "jefe". ¿Qué tienes para mí?', `FemaleText_loc1`='날 그냥 "왕"이라고 부르도록... 그런데 나한테 줄 거라도 있느냐!', `FemaleText_loc4`='叫我“国王”。你为我带来了什么！', `FemaleText_loc5`='叫我「國王」。你為我帶來了什麼!', `FemaleText_loc7`='Llámame "jefa". ¿Qué tienes para mí?' WHERE `ID`=9401;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너 죽었다고 들었는데... 이렇게 하면 쉽게 죽지 않을 거다!', `MaleText_loc4`='我听说你已经死啦……嗯，以后你想要装死的话就不那么容易啦！', `MaleText_loc5`='我聽說你已經死啦...嗯，以後你想要裝死的話就不那麼容易啦!', `MaleText_loc7`='Yo oír que tú estar $gmuerto:muerta;... Bueno, ¡no será fácil que pases por cadáver después de esto!' WHERE `ID`=9402;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 가죽세공인입니다만 그 오우거 위장복을 만드는 방법을 좀 가르쳐주지 않겠습니까, 노트?', `MaleText_loc4`='你好，诺特——我是制皮师。你能教我怎么制作食人魔套装吗？', `MaleText_loc5`='你好，諾特─我是製革師。你能教我怎麼製作巨魔套裝嗎?', `MaleText_loc7`='Eh, Knot, soy un peletero. ¿Crees que podrías enseñarme a hacer el traje de ogro?', `FemaleText_loc1`='저는 가죽세공인입니다만 그 오우거 위장복을 만드는 방법을 좀 가르쳐주지 않겠습니까, 노트?', `FemaleText_loc4`='你好，诺特——我是制皮师。你能教我怎么制作食人魔套装吗？', `FemaleText_loc5`='你好，諾特─我是製革師。你能教我怎麼製作巨魔套裝嗎?', `FemaleText_loc7`='Eh, Knot, soy una peletera. ¿Crees que podrías enseñarme a hacer el traje de ogro?' WHERE `ID`=9403;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 재봉사입니다만 그 오우거 위장복을 만드는 방법을 좀 가르쳐주지 않겠습니까, 노트?', `MaleText_loc4`='你好，诺特——我是裁缝。你能教我怎么制作食人魔套装吗？', `MaleText_loc5`='你好，諾特─我是裁縫。你能教我怎麼製作巨魔套裝嗎?', `MaleText_loc7`='Eh, Knot, soy un sastre. ¿Crees que podrías enseñarme a hacer el traje de ogro?', `FemaleText_loc1`='저는 재봉사입니다만 그 오우거 위장복을 만드는 방법을 좀 가르쳐주지 않겠습니까, 노트?', `FemaleText_loc4`='你好，诺特——我是裁缝。你能教我怎么制作食人魔套装吗？', `FemaleText_loc5`='你好，諾特─我是裁縫。你能教我怎麼製作巨魔套裝嗎?', `FemaleText_loc7`='Eh, Knot, soy un sastre. ¿Crees que podrías enseñarme a hacer el traje de ogro?' WHERE `ID`=9404;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가르쳐줘도 좋겠지. 아마도 오우거 타닌은 여기서밖에 못 찾겠지만 다른 것들은 웬만하면 어디서나 찾을 수 있지!', `MaleText_loc4`='我想我能教你。你也许只能在这儿找到食人魔鞣酸，但是你几乎可以在任何地方找到其他东西。', `MaleText_loc5`='我想我能教你。你也許只能在這兒找到巨魔鞣酸，但是你幾乎可以在任何地方找到其他東西。', `MaleText_loc7`='Supongo que puedo enseñártelo. Probablemente el tanino de ogro solo lo puedas encontrar aquí, pero el resto de las cosas las puedes encontrar en cualquier parte.' WHERE `ID`=9405;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 일만 년 동안이나 이 왕국을 다스려왔습니다. 그동안 셴드랄라 가문의 신성한 땅을 밟은 자들에게서 흥미로운 이야기를 많이 들었지요.$B$B여기 매인 몸인지라 이곳을 찾는 이들을 통해 바깥세상의 이야기를 듣는 것입니다. 그대는 내게 들려주러 오셨나요? 아니면 내 이야기를 듣고자 오셨습니까?', `MaleText_loc4`='我统治这个王国已经有一万年啦。在那时，我从那些神圣的辛德拉家族成员那儿听到很多令人着迷的故事。$B$B由于我必须呆在这儿，所以我常常和访问者沟通交谈。你可以为我讲个故事吗，或许你想听听我的故事？', `MaleText_loc5`='我統治這個王國已經有一萬年啦。在那時，我從那些神聖的辛德拉家族成員那兒聽到很多令人著迷的故事。$B$B由於我必須待在這兒，所以我常常和訪問者溝通交談。你可以為我講個故事嗎，或許你想聽聽我的故事?', `MaleText_loc7`='Durante 10,000 años he gobernado este reino. Durante ese tiempo, quienes han pasado por los terrenos sagrados de la Casa de Shen’dralar, me han contado muchas historias fascinantes.$B$BYo estoy atado a este lugar y, a menudo, intercambio historias con los visitantes. ¿Tienes una historia para mí, o quizás quieras escuchar una?' WHERE `ID`=9406;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 엘드레탈라스의 신성함을 더럽히는 게 누구냐? 썩 나와라, 겁쟁이들아!', `MaleText_loc4`='谁敢破坏埃雷萨拉斯的圣洁？懦夫，面对我！', `MaleText_loc5`='誰敢破壞埃德薩拉斯的聖潔?懦夫，面對我!', `MaleText_loc7`='¿Quién osa perturbar la santidad de Eldre''Thalas? ¡Enfréntense a mí, cobardes!' WHERE `ID`=9407;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님의 노여움을 살 생각은 마십시오. 한 번 노하시면 상상을 초월할 만큼 잔인해지신답니다.', `MaleText_loc4`='我们可不能惹恼了他。他发起火来就没有节制啦。', `MaleText_loc5`='我們可不能惹惱了他。他發起火來就沒有節制啦。', `MaleText_loc7`='No debemos enfurecer al Maestro. Su ira es cruel e irracional.', `FemaleText_loc1`='주인님의 노여움을 살 생각은 마십시오. 한 번 노하시면 상상을 초월할 만큼 잔인해지신답니다.', `FemaleText_loc4`='我们可不能惹恼了他。他发起火来就没有节制啦。', `FemaleText_loc5`='我們可不能惹惱了他。他發起火來就沒有節制啦。', `FemaleText_loc7`='No debemos enfurecer al Maestro. Su ira es cruel e irracional.' WHERE `ID`=9408;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이방인이여, 목소리를 낮추십시오. 주인님의 명상을 방해하지 않는 게 좋을 겁니다.', `MaleText_loc4`='陌生人，把你的声音放小一点。你不是想打扰主人的沉思吧。', `MaleText_loc5`='陌生人，把你的聲音放小一點。你不是想打擾主人的沉思吧。', `MaleText_loc7`='Habla bajo, $gforastero:forastera;. No queremos perturbar la meditación del Maestro.', `FemaleText_loc1`='이방인이여, 목소리를 낮추십시오. 주인님의 명상을 방해하지 않는 게 좋을 겁니다.', `FemaleText_loc4`='陌生人，把你的声音放小一点。你不是想打扰主人的沉思吧。', `FemaleText_loc5`='陌生人，把你的聲音放小一點。你不是想打擾主人的沉思吧。', `FemaleText_loc7`='Habla bajo, $gforastero:forastera;. No queremos perturbar la meditación del Maestro.' WHERE `ID`=9409;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 성소를 찾아온 자들은 많지만 성한 몸으로 떠난 자는 별로 없지요.', `MaleText_loc4`='许多人来到这个避难所，少数人却离开了。', `MaleText_loc5`='許多人來到這個避難所，少數人卻離開了。', `MaleText_loc7`='Muchos han venido a este santuario, muchos se han ido.', `FemaleText_loc1`='이 성소를 찾아온 자들은 많지만 성한 몸으로 떠난 자는 별로 없지요.', `FemaleText_loc4`='许多人来到这个避难所，少数人却离开了。', `FemaleText_loc5`='許多人來到這個避難所，少數人卻離開了。', `FemaleText_loc7`='Muchos han venido a este santuario, muchos se han ido.' WHERE `ID`=9410;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래! 확실히 죽었군... 그렇다면 너... 아니 너희 모두 새 왕이 되는 거야! 왕! 이제 고르독은 네 거야. 왕 노릇이 어떤 건지 알고 싶으면 나하고 얘기해! 난... 왕의 비서였다! 맞아, 나를 약삭빠른 미즐이라고 부르는 것도 그 때문이지!', `MaleText_loc4`='他真的死了。你成了新国王……嗯，就是你！戈多克是你的啦，国王！你应该跟我谈谈，了解这儿的一切！我是……我是他的助手！是的，这就是我为什么被称为狡猾的家伙的原因！', `MaleText_loc5`='他真的死了。你成了新國王...嗯，就是你!戈多克是你的啦，國王!你應該跟我談談，瞭解這兒的一切!我是...我是他的助手!是的，這就是我為什麼被稱為狡猾的傢伙的原因!', `MaleText_loc7`='Sí, está muy muerto. ¡Eso te convierte en $gel nuevo rey:la nueva reina;...! ¡Bueno, todos ustedes! ¡Gordok te pertenece, $gjefe:jefa;! Ven a hablar conmigo para aprender todo lo necesario sobre ser $gel rey:la reina;. ¡Yo fui... soy su asistente! ¡Sí, por eso me llaman el Astuto!' WHERE `ID`=9411;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 현자는 고대부터 존재했으며 우리의 여왕님을 받들어 영예로운 임무를 맡아왔소!', `MaleText_loc4`='博学者是个古老的学者。他为我们伟大的女王服务！', `MaleText_loc5`='博識者是個古老的組織，並為我們偉大的女王服務!', `MaleText_loc7`='El Tradicionalista es un Ancestro. ¡Ha servido a nuestra gloriosa reina!', `FemaleText_loc1`='그 현자는 고대에서 존재했으며 우리의 여왕님을 받들어 영예로운 임무를 맡아왔소!', `FemaleText_loc4`='博学者是个古老的学者。他为我们伟大的女王服务！', `FemaleText_loc5`='博識者是個古老的組織，並為我們偉大的女王服務!', `FemaleText_loc7`='El Tradicionalista es un Ancestro. ¡Ha servido a nuestra gloriosa reina!' WHERE `ID`=9412;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 근처 동료에게 경고하는 듯 우렁차게 포효하더니 분노합니다!', `MaleText_loc4`='%s低声咆哮着警告附近的盟友，看来是被激怒啦！', `MaleText_loc5`='%s發出一聲深沉的咆哮，向附近的盟友發出信號，看來是被激怒啦!', `MaleText_loc7`='¡%s deja salir un gruñido profundo que alerta a los aliados cercanos y se enfurece!' WHERE `ID`=9413;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 만취해서 분노에 휩싸입니다!', `MaleText_loc4`='%s酒醉后变得狂暴起来！', `MaleText_loc5`='%s酒醉後變得狂暴起來!', `MaleText_loc7`='%s entra en un frenesí alcohólico.' WHERE `ID`=9414;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐라고, 펜구스 녀석이 나보고 놀의 애인이라고 했다고?! 어서 포로들 왕에게 데려가. 녀석들 위험하다는 걸 보여주려고 무기를 들린 채 데려오다니 제법 영리하군. 난 가서 펜구스 녀석 혼내줘야겠다. 그때도 계속 그딴 소리를 지껄이나 보자! 흥!', `MaleText_loc4`='嘿，芬古斯说谁是恋豺狼人癖？！把囚犯交给国王吧，他们携带着武器，对国王来说是个威胁。我倒要看看当我把芬古斯打趴下的时候他还敢说什么！哈！', `MaleText_loc5`='啊，衛兵芬古斯把誰叫做豺狼人嗜好者?!把囚犯交給國王吧;他們攜帶武器，對國王來說是個威脅。我倒要看看當我將芬古斯打倒在地的時候他還敢說什麼!哈哈!', `MaleText_loc7`='¡Eh! ¿A quién llamar Fengus amante de gnolls? Llevar prisioneros $gal rey:a la reina;; tú inteligente para llevarles con armas y mostrar que son una amenaza. ¡A ver si Fengus seguir tan listillo cuando yo darle mamporrazo! ¡JAR!' WHERE `ID`=9416;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 있는 한 누구도 왕 위협할 순 없다! 우어어! 받아라!', `MaleText_loc4`='没有人能打败我，没有人敢威胁国王！死吧！', `MaleText_loc5`='沒有人能打敗我，威脅國王!啊，接受現實吧!!', `MaleText_loc7`='¡Nadie pasar por mí y amenazar $gal rey:a la reina;! ¡Agh, toma!' WHERE `ID`=9418;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 왜 어슬렁대는 거냐? 저 녀석들한테 왜 족쇄 채우지 않았지?', `MaleText_loc4`='你在附近闲逛什么？为什么不把那些小家伙锁起来？！', `MaleText_loc5`='你在附近閒逛什麼?為什麼不把那些小傢伙鎖起來?!', `MaleText_loc7`='¿Qué hacer por aquí? ¿Por qué no estar los peleles con cadenas?' WHERE `ID`=9419;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 당신이 왕이야! 모두 고르독의 새 왕에게 경례!', `MaleText_loc4`='现在你变得强大了！向戈多克的新国王致敬！', `MaleText_loc5`='現在你變得強大了!向戈多克的新國王致敬!', `MaleText_loc7`='¡Tú ahora $gel más fuerte:la más fuerte;! ¡Que todos saluden $gal nuevo rey:a la nueva reina; de los Gordok!' WHERE `ID`=9420;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음... 그냥 외부에서 붙잡은 포로 몇을 왕께 데리고 가 처벌하려고 하는데요.', `MaleText_loc4`='嗯，我要把这些人带到国王那里去听候发落。', `MaleText_loc5`='嗯，在國王下令懲處囚犯之前，我救出了一些人。', `MaleText_loc7`='Mmm... Llevo ante el rey unos prisioneros que encontramos fuera, para que los castigue.', `FemaleText_loc1`='음... 그냥 외부에서 붙잡은 포로 몇을 왕께 데리고 가 처벌하려고 하는데요.', `FemaleText_loc4`='嗯，我要把这些人带到国王那里去听候发落。', `FemaleText_loc5`='嗯，在國王下令懲處囚犯之前，我救出了一些人。', `FemaleText_loc7`='Mmm... Llevo ante el rey unos prisioneros que encontramos fuera, para que los castigue.' WHERE `ID`=9421;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직도 녀석들 무기를 들고 있는 것 같은데? 어째서 무기를 그대로 지니고 있게 한 거냐?', `MaleText_loc4`='为什么他们身上还有武器？你为什么不拿走他们的武器？！', `MaleText_loc5`='為什麼他們身上還有武器?你為什麼不拿走他們的武器?!', `MaleText_loc7`='¿Es cierto lo que ven mis ojos? ¿Siguen con sus armas? ¿Por qué les has permitido quedarse con las armas?' WHERE `ID`=9422;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그게... 녀석들 발견했을 때부터 무기를 지니고 있었습니다요. 녀석들 위험하다는 걸 왕께 보여드리고 싶었거든요! 근데 말입니다... 펜구스가 대장님 뚱뚱한 놀 애인이라고 비웃는 걸 엿들었습니다!', `MaleText_loc4`='呃……我就是这样找到他们的。我想告诉国王他们是个威胁！我跟你说啊，头儿……我无意中听到卫兵芬古斯说你是个肥胖无用的恋豺狼人癖！', `MaleText_loc5`='呃...我就是這樣找到他們的。我想告訴國王他們是個威脅!首領...我無意中聽到守衛芬古斯叫你肥胖無用的豺狼人嗜好者!', `MaleText_loc7`='Ehh... así les encontré. ¡Quería mostrar al rey que eran una amenaza! Dime capitán... Escuché cómo el guardia Fengus te decía que eras un amante de gnolls gordo e inútil.', `FemaleText_loc1`='그게... 녀석들 발견했을 때부터 무기를 지니고 있었습니다요. 녀석들 위험하다는 걸 왕께 보여드리고 싶었거든요! 근데 말입니다... 펜구스가 대장님 뚱뚱한 놀 애인이라고 비웃는 걸 엿들었습니다!', `FemaleText_loc4`='呃……我就是这样找到他们的。我想告诉国王他们是个威胁！我跟你说啊，头儿……我无意中听到卫兵芬古斯说你是个肥胖无用的恋豺狼人癖！', `FemaleText_loc5`='呃...我就是這樣找到他們的。我想告訴國王他們是個威脅!首領...我無意中聽到守衛芬古斯叫你肥胖無用的豺狼人嗜好者!', `FemaleText_loc7`='Ehh... así les encontré. ¡Quería mostrar al rey que eran una amenaza! Dime capitán... Escuché cómo el guardia Fengus te decía que eras un amante de gnolls gordo e inútil.' WHERE `ID`=9423;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아. 펜구스 이 녀석, 어디 있는 거냐?! 어디 나와서 놀 애인이라고 또 비웃어봐! 이 망치로 정신이 번쩍 들게 해줄 테니까!', `MaleText_loc4`='好吧，芬古斯，你什么意思？！你敢叫我恋豺狼人癖，看我一锤打得你找不到北！', `MaleText_loc5`='好吧，芬古斯，你什麼意思?!你叫我豺狼人嗜好者，當心我對著你的腦袋就是一錘!', `MaleText_loc7`='Muy bien, Fengus, ¿qué estás haciendo? Llamarme amante de gnolls mientras te doy un mamporrazo...' WHERE `ID`=9424;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='재로 돌아가라!', `MaleText_loc4`='尘归尘，土归土！', `MaleText_loc5`='塵歸塵，土歸土!', `MaleText_loc7`='¡Polvo al polvo!' WHERE `ID`=9425;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불의 세례를 받아라!', `MaleText_loc4`='让火焰净化一切吧！', `MaleText_loc5`='讓火焰淨化一切!', `MaleText_loc7`='¡QUE EL FUEGO TE PURIFIQUE!' WHERE `ID`=9426;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='설퍼론의 유황 맛을 보아라!', `MaleText_loc4`='尝尝萨弗隆的火焰吧！', `MaleText_loc5`='感受薩弗隆的烈焰吧!', `MaleText_loc7`='¡PRUEBEN LAS LLAMAS DE SULFURON!' WHERE `ID`=9427;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n, 명령서 여기 있습니다. 서둘러 가르릭 전투대장에게 가져가십시오!', `FemaleText_loc4`='这些是指令，$n。请迅速将它们交给霜狼突击队队长!', `FemaleText_loc5`='這些是指令，$n。請迅速將它們交給霜狼突擊隊隊長!', `FemaleText_loc7`='Aquí están las órdenes, $n. ¡Llévaselas rápidamente al maestro de guerra Garrick!' WHERE `ID`=9428;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 명령서 여기 있습니다. 서둘러 테라베인 야전사령관에게 가져가십시오!', `MaleText_loc4`='这是指令，$n。现在快将它们交给指挥官特拉瓦雷吧！', `MaleText_loc5`='這是指令，$n。現在快將它們交給戰場元帥特拉瓦雷吧!', `MaleText_loc7`='Aquí están las órdenes, $n. Llévaselas rápidamente al Mariscal de campo Teravaine.' WHERE `ID`=9429;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타나리운, 덫을 잃어 버렸는데, 새로 하나 주실 수 있습니까?', `MaleText_loc4`='萨纳瑞恩，我把捕兽器弄丢啦。你能再给我一个吗？', `MaleText_loc5`='薩納瑞恩，我把捕獸器弄丟啦。你能再給我一個嗎?', `MaleText_loc7`='Tharnariun, he perdido la trampa. ¿Podrías darme otra?', `FemaleText_loc1`='타나리운, 덫을 잃어 버렸는데, 새로 하나 주실 수 있습니까?', `FemaleText_loc4`='萨纳瑞恩，我把捕兽器弄丢啦。你能再给我一个吗？', `FemaleText_loc5`='薩納瑞恩，我把捕獸器弄丟啦。你能再給我一個嗎?', `FemaleText_loc7`='Tharnariun, he perdido la trampa. ¿Podrías darme otra?' WHERE `ID`=9431;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='테라베인 야전사령관은 어디 있습니까?', `MaleText_loc4`='指挥官特拉瓦雷在哪儿？', `MaleText_loc5`='戰場元帥特拉瓦雷在哪兒?', `MaleText_loc7`='¿Dónde está el Mariscal de campo Teravaine?', `FemaleText_loc1`='테라베인 야전사령관은 어디 있습니까?', `FemaleText_loc4`='指挥官特拉瓦雷在哪儿？', `FemaleText_loc5`='戰場元帥特拉瓦雷在哪兒?', `FemaleText_loc7`='¿Dónde está el Mariscal de campo Teravaine?' WHERE `ID`=9432;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가르릭 전투대장은 어디 있습니까?', `MaleText_loc4`='突击队长加瑞克在哪儿？', `MaleText_loc5`='將領加瑞克在哪兒?', `MaleText_loc7`='¿Dónde está el maestro de guerra Garrick?', `FemaleText_loc1`='가르릭 전투대장은 어디 있습니까?', `FemaleText_loc4`='突击队长加瑞克在哪儿？', `FemaleText_loc5`='將領加瑞克在哪兒?', `FemaleText_loc7`='¿Dónde está el maestro de guerra Garrick?' WHERE `ID`=9433;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보급품이 충분할 때 테라베인 야전사령관은 투쟁의 벌판 남단에 투석기를 설치한 지점에 계십니다.', `MaleText_loc4`='一旦我们拥有充足的物资供给，指挥官特拉瓦雷就会前往征战平原，驻守在我们最南端的弩车附近。', `MaleText_loc5`='一旦我們擁有充足的物資供給，戰場元帥特拉瓦雷就會前往征戰平原，駐守在我們最南端的弩砲附近。', `MaleText_loc7`='Cuando nuestro nivel de suministros es alto, el Mariscal de campo Teravaine está estacionado en la Tierra de Disputa. En nuestro emplazamiento de balista más al sur.' WHERE `ID`=9434;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='보급품이 충분할 때 가르릭 전투대장은 투쟁의 벌판, 얼음피 주둔지 북쪽에 있는 투석기에 계십니다.', `FemaleText_loc4`='一旦我们拥有丰富的物资供给，霜狼突击队队长就会驻守在冰血要塞以北的征战平原，就在攻城机旁边。', `FemaleText_loc5`='一旦我們擁有豐富的物資供給，霜狼突擊隊隊長就會駐守在冰血要塞以北的征戰平原，就在攻城機旁邊。', `FemaleText_loc7`='Cuando nuestro nivel de suministros es alto, el maestro de guerra Garrick está estacionado en la Tierra de Disputa. En una catapulta, al norte del Baluarte Sangrehielo.' WHERE `ID`=9435;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서리늑대 병참장교는 어디 있습니까?', `MaleText_loc4`='霜狼军需官在哪儿？', `MaleText_loc5`='霜狼軍需官在哪兒?', `MaleText_loc7`='¿Dónde está el Intendente Lobo Gélido?', `FemaleText_loc1`='서리늑대 병참장교는 어디 있습니까?', `FemaleText_loc4`='霜狼军需官在哪儿？', `FemaleText_loc5`='霜狼軍需官在哪兒?', `FemaleText_loc7`='¿Dónde está el Intendente Lobo Gélido?' WHERE `ID`=9436;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰파이크 병참장교는 어디 있습니까?', `MaleText_loc4`='雷矛军需官在哪儿？', `MaleText_loc5`='雷矛軍需官在哪兒?', `MaleText_loc7`='¿Dónde está el Intendente Pico Tormenta?', `FemaleText_loc1`='스톰파이크 병참장교는 어디 있습니까?', `FemaleText_loc4`='雷矛军需官在哪儿？', `FemaleText_loc5`='雷矛軍需官在哪兒?', `FemaleText_loc7`='¿Dónde está el Intendente Pico Tormenta?' WHERE `ID`=9437;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰파이크 병참장교는 여기서 바로 서쪽에 있는 천막에서 보급품을 관리하고 있네.', `MaleText_loc4`='雷矛军需官将物资存储在雨棚下，就在这儿以西的地方。', `MaleText_loc5`='雷矛軍需官將物資存儲在雨棚下，就在這兒以西的地方。', `MaleText_loc7`='El intendente Pico Tormenta guarda sus suministros bajo un toldo, justo al oeste de aquí.' WHERE `ID`=9438;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='서리늑대 병참장교는 이 참호에서 남서쪽에 있네. 참호로 들어가서 오른쪽에 있는 문으로 나간 다음 길을 따라 조금만 가면 만날 수 있을 걸세.', `FemaleText_loc4`='霜狼军需官就在这个工事的东面。进入碉堡，从右边的出口出去，不远处你就可以看到军需官。', `FemaleText_loc5`='霜狼軍需官就在這個碉堡的西南面。進入碉堡，從右邊的出口出去，不遠處你就可以看到軍需官。', `FemaleText_loc7`='El intendente Lobo Gélido está al suroeste de este búnker. Entra en el búnker y sal por la derecha. Verás al intendente un poco más adelante, en el camino.' WHERE `ID`=9439;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부하? 공물?', `MaleText_loc4`='追随者？贡品？', `MaleText_loc5`='追隨者?貢品?', `MaleText_loc7`='¿Esbirros? ¿Tributo?', `FemaleText_loc1`='부하? 공물?', `FemaleText_loc4`='追随者？贡品？', `FemaleText_loc5`='追隨者?貢品?', `FemaleText_loc7`='¿Esbirros? ¿Tributo?' WHERE `ID`=9440;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왕이 되니까 좋은데! 자, 그럼 아까 얘기하던 거 말인데...', `MaleText_loc4`='当国王真好！现在，让我们继续谈谈你刚才说的事儿……', `MaleText_loc5`='當國王真好!現在，讓我們繼續談談你剛才說的事兒...', `MaleText_loc7`='¡Me gusta ser el rey! Ahora, volvamos a hablar de lo que me estabas comentando antes...', `FemaleText_loc1`='왕이 되니까 좋은데! 자, 그럼 아까 얘기하던 거 말인데...', `FemaleText_loc4`='当国王真好！现在，让我们继续谈谈你刚才说的事儿……', `FemaleText_loc5`='當國王真好!現在，讓我們繼續談談你剛才說的事兒...', `FemaleText_loc7`='¡Me gusta ser la reina! Ahora, volvamos a hablar de lo que me estabas comentando antes...' WHERE `ID`=9441;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음, 당신이 왕 죽였지? 그럼 당신이 왕 자리를 차지하는 거지. 새 왕이 되는 거라고! 왕 만세!', `MaleText_loc4`='嗯，你杀死了国王，是吗？这就是说你取代了他的位置。你成为了新的头目！向国王致敬！', `MaleText_loc5`='嗯，你殺死了國王，是嗎?這就是說你取代了他的位置。你成為了新的頭目!向國王致敬!', `MaleText_loc7`='Mmm... ¿Tú matar al rey, sí? Eso significa que tú ocupar su lugar. ¡Eso te convierte en $gel nuevo rey:la nueva reina;! ¡Viva $gel rey:la reina;!' WHERE `ID`=9442;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='맙소사! 이런 비극이! 거의 다 됐는데 모든 걸 잃어버릴 수 있다니...', `FemaleText_loc4`='哦，真恐怖！这是个悲剧！我们就要突破啦，但也有可能遭遇全军覆灭的惨剧。', `FemaleText_loc5`='哦，真恐怖!這是個悲劇!我們就要突破啦，但也有可能遭遇全軍覆滅的慘劇。', `FemaleText_loc7`='¡Oh, el horror! ¡La tragedia! Estamos a punto de conseguir un gran avance, pero todo podría perderse.' WHERE `ID`=9443;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어... 때려서 미안! 왕, 나 죽이지 마, 제발... 알았지!? 이제 네가 왕이니까 내가 더 좋은 공물 받게 돕는다!', `MaleText_loc4`='呃……很抱歉我袭击了你。不要杀我，求你了！？你是国王啦，我会为你提供更多的贡品的！', `MaleText_loc5`='呃...很抱歉我襲擊了你。不要殺我，求你了!?你是國王啦，我會為你提供更多的貢品的!', `MaleText_loc7`='Eeeh... Siento haberte atacado, $gjefe:jefa;. Tú no matarme, por favor, ¿vale? ¡Tú $grey:reina; ahora y yo ayudarte a hacer tu tributo más grande!' WHERE `ID`=9444;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='유해를 대충 조사해보니 살갗이 불에 타서 떨어져 나간 것 같습니다. 아주 소름끼치는 광경입니다.', `MaleText_loc4`='粗略地检查一下骸骨，上面的肉已经干枯了。真是令人毛骨悚然的场景。', `MaleText_loc5`='粗略地檢查一下骨骸，上面的肉已經乾枯了。真是令人毛骨悚然的場景。', `MaleText_loc7`='Un examen superficial del esqueleto indica que la carne fue quemada. Una visión espeluznante.' WHERE `ID`=9445;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이방인이여, 그는 죽었으니 아무 말도 해주지 않으리라 생각하오만...', `MaleText_loc4`='我很怀疑他有什么话可说，陌生人……', `MaleText_loc5`='我很懷疑他有什麼話可說，陌生人...', `MaleText_loc7`='Dudo mucho que tenga algo que decir, $gforastero:forastera;.' WHERE `ID`=9446;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 개인적으로 토르텔드린 왕자가 하는 일에 관여하지 않았소. 예외적으로 하이 엘프를 자신의 영토에 들인 것은 토르텔드린 왕자였소. 유감스럽게도 나는 토르텔드린 왕자에게 의문을 제기할 입장이 못 되오. 조금이나마 왕자를 두둔하자면, 윈탈루스를 즉시 불태워 죽이지는 않았다는 거지.', `MaleText_loc4`='我个人并不在意他。王子从未如此对待过他领地中的高等精灵。唉，我还没资格质疑王子。不过至少,他并没有立即把温萨鲁斯烧成灰。', `MaleText_loc5`='我個人並不在意他。王子從未如此對待過他領域中的高等精靈。唉，我還沒資格質疑王子。他並沒有立即火化溫薩羅斯大師的屍體。', `MaleText_loc7`='Personalmente, no me molestaba. Fue el Príncipe quien se ofendió con un elfo noble en su dominio. ¡Ay! Pero yo no soy nadie para cuestionar al Príncipe. En su defensa, no incineró al maestro Winthalus inmediatamente.' WHERE `ID`=9447;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더는 이목을 끌어서는 안 되오. 당신에게 윈탈루스를 찾으라고 지시한 자들에게 돌아가서 아무것도 찾을 수 없었다고 전하시오. 그런 다음 날 다시 찾아오시오. 그 말을 전하는 순간 난 당신이 할 일을 마쳤다는 걸 알 수 있으니까 말이오. 그러면 죽은 윈탈루스의 비밀을 알려주리다.', `MaleText_loc4`='我们再也不想得到什么关注啦，陌生人。回到那些让你来找失踪的管理员的家伙那儿去吧，告诉他们什么都找不到。然后回到我这儿来，我会告诉你一个失传的秘密。', `MaleText_loc5`='我們再也不想得到什麼關注啦，陌生人。回到那些讓你來找失蹤的管理員的傢伙那兒去吧，告訴他們什麼都找不到。然後回到我這兒來，我會告訴你一個失傳的秘密。', `MaleText_loc7`='Definitivamente, no necesitamos llamar más la atención, $gforastero:forastera;. Vuelve a ver a quienes te enviaron a buscar al maestro perdido y diles que no has logrado encontrar nada. Cuando lo hayas hecho, y sabré cuándo lo has hecho, ven a verme y te revelaré los secretos de los fallecidos.' WHERE `ID`=9448;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크나큰 상실감에 흐느껴 웁니다.', `MaleText_loc4`='向阵亡者默哀。', `MaleText_loc5`='向陣亡者默哀。', `MaleText_loc7`='Lamenta la gran pérdida.', `FemaleText_loc1`='크나큰 상실감에 흐느껴 웁니다.', `FemaleText_loc4`='向阵亡者默哀。', `FemaleText_loc5`='向陣亡者默哀。', `FemaleText_loc7`='Lamenta la gran pérdida.' WHERE `ID`=9449;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투 준비 완료! 호드는 한시라도 빨리 얼라이언스의 피 맛을 보고 싶습니다. 이제 곧 우리 부대장님께서 얼음피 주둔지에 진입하실 것이고 다시 전쟁이 시작될 겁니다!', `MaleText_loc4`='面对战争，我们的军队泰然自若，誓与联盟展开血战。我们的队长很久就会进入冰血要塞，战争即将展开！', `MaleText_loc5`='面對戰爭，我們的軍隊泰然自若，誓與聯盟展開血戰。我們的隊長很久就會進入冰血要塞，戰爭即將展開!', `MaleText_loc7`='Nuestras tropas están dispuestas para la batalla y ansiosas por derramar la sangre de la Alianza. Pronto, nuestro capitán entrará en el Baluarte Sangrehielo y la guerra comenzará de nuevo.' WHERE `ID`=9450;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 내가 새 왕이 됐는데... 나에게 뭘 바칠 거지?!', `MaleText_loc4`='那么，现在我是国王啦……你给我带来了什么？！', `MaleText_loc5`='那麼，現在我是國王啦...你給我帶來了什麼?!', `MaleText_loc7`='Y bien, ahora que soy el rey... ¿Qué tienes para mí?', `FemaleText_loc1`='이제 내가 새 왕이 됐는데... 나에게 뭘 바칠 거지?!', `FemaleText_loc4`='那么，现在我是国王啦……你给我带来了什么？！', `FemaleText_loc5`='那麼，現在我是國王啦...你給我帶來了什麼?!', `FemaleText_loc7`='Y bien, ahora que soy la reina... ¿Qué tienes para mí?' WHERE `ID`=9451;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음... 당신이라면 이전 왕하고 달리 기분 나쁜 명가의 왕자에게서 귀중한 고르독 유물 되찾을 수 있을지도 모르겠군!', `MaleText_loc4`='从可怕的上层精灵王子那儿取回戈多克的遗物，或许你能比老头目做得更好！', `MaleText_loc5`='從可怕的精靈王子那兒取回戈多克的聖物，或許你能比老頭目做得更好!', `MaleText_loc7`='Quizás tú tener más suerte que el viejo jefe para recuperar la valiosa reliquia de Gordok, que tener el príncipe Altonato ese asqueroso.' WHERE `ID`=9452;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러니까 이 근처에 궤짝이라던가 그런 건 없습니까? 고르독 오우거들이 값으로 따지지 못할 만큼 소중히 여기는 유물인 건틀릿이 든 궤짝 말입니다.', `MaleText_loc4`='那么……这附近没有什么箱子了，你要知道，在戈多克食人魔眼里，护手是一件无价的神器？', `MaleText_loc5`='那麼...這附近沒有什麼箱子了，你要知道，在戈多克巨魔眼裡，護手是一件無價的神器?', `MaleText_loc7`='Así que... ¿No tendrás por ahí un cofre que contenga, digamos, un guantelete que los ogros Gordok consideran un artefacto muy valioso?', `FemaleText_loc1`='그러니까 이 근처에 궤짝이라던가 그런 건 없습니까? 고르독 오우거들이 값으로 따지지 못할 만큼 소중히 여기는 유물인 건틀릿이 든 궤짝 말입니다.', `FemaleText_loc4`='那么……这附近没有什么箱子了，你要知道，在戈多克食人魔眼里，护手是一件无价的神器？', `FemaleText_loc5`='那麼...這附近沒有什麼箱子了，你要知道，在戈多克巨魔眼裡，護手是一件無價的神器?', `FemaleText_loc7`='Así que... ¿No tendrás por ahí un cofre que contenga, digamos, un guantelete que los ogros Gordok consideran un artefacto muy valioso?' WHERE `ID`=9453;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='설사 그런 걸 가지고 있어도 그대에게 순순히 넘겨줄 거 같습니까? 어리석은 자여... 실제로 내게 그 유물이 있고, 그대가 그걸 손에 넣을 수 있는 유일한 방법은 날 처치하고 가져가는 것뿐입니다.$B$B친구여, 아직은 그런 일이 생기지는 않을 거요.', `MaleText_loc4`='愚蠢的家伙，即使我这么做了，你认为我会让你轻易得手吗？你要得到这东西——如果我确实有这东西的话——你只能从我冰冷的手指中把它抢走。$B$B我的朋友，这种事情是不可能发生的。', `MaleText_loc5`='愚蠢的傢伙，即使我這麼做了，你認為我會讓你輕易得手嗎?你要得到這東西─如果我確實有這東西的話─你只能從我冰冷的手指中把它搶走。$B$B我的朋友，這種事情是不可能發生的。', `MaleText_loc7`='Incluso si lo tuviera, $gnecio:necia;, ¿acaso crees que te lo daría sin más? La única forma que tendrías de conseguirlo, si yo lo tuviera, sería arrancándomelo de mis dedos, fríos y rígidos.$B$BY eso, mi $gquerido amigo:querida amiga; no ocurrirá pronto.' WHERE `ID`=9454;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새로운 왕 만세!', `MaleText_loc4`='向新国王致敬！', `MaleText_loc5`='向新國王致敬!', `MaleText_loc7`='¡Viva $gel nuevo rey:la nueva reina;!' WHERE `ID`=9455;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어... 그러니까 너 새로운 왕이 되기 전에 째려본 건... 그냥 장난이었는데?$B$B정말이다, 왕!', `MaleText_loc4`='在你成为新国王之前，我曾对你横眉竖眼……嗯……我那是在开玩笑。$B$B是的！', `MaleText_loc5`='在你成為新國王之前，我曾對你橫眉豎眼...嗯...我那是在開玩笑。$B$B是的!', `MaleText_loc7`='Cuando te miré mal antes... antes de que te convirtieras en $gel nuevo rey:la nueva reina;... Mmm... Solo estaba bromeando.$B$BSí.' WHERE `ID`=9456;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왕을 공격하다니, 다른 오우거들은 바보야! 그래서 내가 아직 살아 있는 거야, 난 똑똑하니까!', `MaleText_loc4`='其他的食人魔居然攻击你，他们太笨了，国王！这就是我还活着的原因——我既聪明又结实！', `MaleText_loc5`='其他的巨魔居然攻擊你，他們太笨了，國王!這就是我還活著的原因─我既聰明又結實!', `MaleText_loc7`='¡Los otros ogros fueron tontos por atacarte, $gjefe:jefa;! Por eso yo seguir con vida, ¡soy listo y todo eso!' WHERE `ID`=9457;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 타나리스에 있는 오우거보다 훨씬 깨끗해. 저 넓은 사막에서 눈에 보이는 거라곤 오우거 똥뿐이니... 여기서는 절대 안 그렇지, 왕!', `MaleText_loc4`='我们可比塔纳利斯的食人魔干净多了。那片沙漠中到处都是食人魔。这儿可不是，$g先生:女士;！', `MaleText_loc5`='我們可比塔納利斯的巨魔乾淨多了。那片沙漠中到處都是巨魔。這兒可不是，$g先生:女士;!', `MaleText_loc7`='Nosotros mucho más limpios que los ogros de Tanaris. Por todo el desierto hasta donde poder ver, caca de ogro. ¡Aquí no, no $gseñor: señora;!' WHERE `ID`=9458;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 우리랑 머무는 한 네가 왕이지. 딴 데 가버리면 다른 오우거가 왕 자리 차지한다. 그게 고르독 방식이거든!', `MaleText_loc4`='只要你跟我们呆在一起，你就是国王。你离开的话，会有其他食人魔取代你的位置的。这就是戈多克的行事之道！', `MaleText_loc5`='只要你跟我們待在一起，你就是國王。你離開的話，會有其他巨魔取代你的位置的。這就是戈多克的行事之道!', `MaleText_loc7`='Mientras te quedes aquí con nosotros, tú ser $grey:reina;. Tú marcharte y algún otro ogro ocupará tu lugar. ¡Así funcionamos los Gordok!' WHERE `ID`=9459;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 진짜 천재야, 천재!', `MaleText_loc4`='我很聪明！我知道二加二等于五！', `MaleText_loc5`='我很聰明!聰—明—!', `MaleText_loc7`='¡Yo muy listo! ¡L-S-T-O!' WHERE `ID`=9460;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='옛날 왕이 죽었어? 어, 그럴 리가!', `MaleText_loc4`='老国王死了吗？那不可能！', `MaleText_loc5`='老國王死了嗎?那不可能!', `MaleText_loc7`='¿El viejo rey está muerto? ¡Imposible!' WHERE `ID`=9461;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 아무 말썽 안 부린다, 왕.', `MaleText_loc4`='国王陛下，我可没有给你带来什么麻烦。', `MaleText_loc5`='國王陛下，我可沒有給你帶來什麼麻煩。', `MaleText_loc7`='No te causaré problemas, $gjefe:jefa;.' WHERE `ID`=9462;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 이런. "방어의 고서"가 어디 있지? 리드로스가 틀림없이 화를 낼 텐데...', `MaleText_loc4`='哦，亲爱的，“防御圣典”在哪儿？莱德罗斯会勃然大怒的。', `MaleText_loc5`='哦，親愛的，「防禦聖典」在哪兒?萊德羅斯會勃然大怒的。', `MaleText_loc7`='Oh, no, ¿dónde está el "Códice de Defensa?" Lydros se disgustará mucho.' WHERE `ID`=9463;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 한숨을 쉽니다.', `MaleText_loc4`='%s叹了口气。', `MaleText_loc5`='%s嘆了一口氣。', `MaleText_loc7`='%s suspira.' WHERE `ID`=9464;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"신비술사의 요리책"도 없어졌잖아! 이거 정말 큰일이군!', `MaleText_loc4`='“奥术学家的食谱”也不见啦！这真是一场灾难！', `MaleText_loc5`='「《秘法師的烹飪書》也不見啦!這真是一場災難!」', `MaleText_loc7`='"El libro de cocina del Arcanista" también ha desaparecido. ¡Esto es un desastre!' WHERE `ID`=9465;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최근 들어 책이 계속 분실되고 있소. 현자들과 그 조수들이 크게 분노하고 있소이다. 엘드레탈라스 내의 누군가가 배신행위를 저지르고 있는 것이 아닌가 의심들을 하고 있소.', `MaleText_loc4`='最近书本丢失甚多。博学者和他的助手非常恼怒。他们怀疑在埃雷萨拉斯有人妄图不轨。', `MaleText_loc5`='最近書本丟失甚多。博識者和他的助手非常惱怒。他們懷疑在埃德薩拉斯有人妄圖不軌。', `MaleText_loc7`='Últimamente están desapareciendo libros. El Tradicionalista y sus asistentes están desesperados. Sospechan que alguien de Eldre''Thalas tiene la culpa.', `FemaleText_loc1`='최근 들어 책이 계속 분실되고 있습니다. 현자들과 그 조수들이 크게 분노하고 있습니다. 엘드레탈라스 내의 누군가가 배신행위를 저지르고 있는 것이 아닌가 의심들을 하고 있지요.', `FemaleText_loc4`='最近书本丢失甚多。博学者和他的助手非常恼怒。他们怀疑在埃雷萨拉斯有人妄图不轨。', `FemaleText_loc5`='最近書本丟失甚多。博識者和他的助手非常惱怒。他們懷疑在埃德薩拉斯有人妄圖不軌。', `FemaleText_loc7`='Últimamente están desapareciendo libros. El Tradicionalista y sus asistentes están desesperados. Sospechan que alguien de Eldre''Thalas tiene la culpa.' WHERE `ID`=9466;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='토르텔드린 왕자께서 파멸의 인도자에 대한 얘기를 들려 주셨소? 그분의 이야기 중에서 우리가 제일 좋아하는 얘기지. 그분이 제일 좋아하시는 건 파멸의 인도자의 다음 얘기요. 물론 아무도 그분에게서 그 이야기를 듣진 못했소이다.', `MaleText_loc4`='王子不再讲述灰烬使者的故事了吗？在他的诸多故事中，我们最喜欢这个。他的爱好则是寻找灰烬使者的下落。当然，没人能从他口中得知那个故事。', `MaleText_loc5`='王子不再講述灰燼使者的故事了嗎?在他的故事中，我們最喜歡這個啦。他的愛好則是追隨灰燼使者。當然，沒人能從他口中得知那個故事。', `MaleText_loc7`='¿Ha contado el Príncipe la historia de la Crematoria? Es nuestra historia favorita. Su favorita es la continuación de la Crematoria. Nadie ha conseguido que le contara esa historia.', `FemaleText_loc1`='토르텔드린 왕자께서 파멸의 인도자 얘기를 들려 주셨습니까? 그분의 이야기 중에서 우리가 제일 좋아하는 얘기지요. 그분이 제일 좋아하시는 건 파멸의 인도자의 다음 얘기랍니다. 물론 아무도 그분에게서 그 이야기를 듣진 못했지만요.', `FemaleText_loc4`='王子不再讲述灰烬使者的故事了吗？在他的诸多故事中，我们最喜欢这个。他的爱好则是寻找灰烬使者的下落。当然，没人能从他口中得知那个故事。', `FemaleText_loc5`='王子不再講述灰燼使者的故事了嗎?在他的故事中，我們最喜歡這個啦。他的愛好則是追隨灰燼使者。當然，沒人能從他口中得知那個故事。', `FemaleText_loc7`='¿Ha contado el Príncipe la historia de la Crematoria? Es nuestra historia favorita. Su favorita es la continuación de la Crematoria. Nadie ha conseguido que le contara esa historia.' WHERE `ID`=9467;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 생각엔 임프들이 책을 훔치고 있는 것 아닌가 싶소이다.', `MaleText_loc4`='我猜想那些小鬼在偷学知识。', `MaleText_loc5`='我猜想那些小鬼在偷學知識。', `MaleText_loc7`='Sospecho que los diablillos están robando conocimiento.', `FemaleText_loc1`='내 생각엔 임프들이 책을 훔치고 있는 것 아닌가 싶습니다.', `FemaleText_loc4`='我猜想那些小鬼在偷学知识。', `FemaleText_loc5`='我猜想那些小鬼在偷學知識。', `FemaleText_loc7`='Sospecho que los diablillos están robando conocimiento.' WHERE `ID`=9468;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님께서는 네파리안의 소굴에 큰 관심을 보이고 계시오. 누군가가 네파리안과 그 졸개들을 처치하고 그 무용담을 왕자님께 들려 드리기만 한다면 왕자님도 틀림없이 흔쾌히 말해 주실 거요. 파멸의 인도자를 찾을 수 있을지도 모른단 말이오!', `MaleText_loc4`='王子对奈法利安的巢穴非常感兴趣。如果有谁能杀死巨龙及其属下，并将战斗经过告诉王子，我敢打赌王子会非常满意的。找到灰烬使者之日可待啦！', `MaleText_loc5`='王子對奈法利安的巢穴非常感興趣。如果有誰能殺死巨龍及其屬下，並將戰鬥經過告訴王子，我敢打賭王子會非常滿意的。必須找到灰燼使者!', `MaleText_loc7`='El Maestro tiene un gran interés por la Guarida de Nefarian. Ojalá alguien pudiera vencer al dragón y a sus esbirros y volver a contar la historia al Príncipe. Apuesto a que eso conseguiría hacer que el príncipe hablase. ¡Podríamos encontrar la Crematoria!', `FemaleText_loc1`='주인님께서는 네파리안의 소굴에 큰 관심을 보이고 계십니다. 누군가가 네파리안과 그 졸개들을 처치하고 그 무용담을 왕자님께 들려 드리기만 한다면 왕자님도 틀림없이 흔쾌히 말해 주실 겁니다. 파멸의 인도자를 찾을 수 있을지도 모른단 말입니다!', `FemaleText_loc4`='王子对奈法利安的巢穴非常感兴趣。如果有谁能杀死巨龙及其属下，并将战斗经过告诉王子，我敢打赌王子会非常满意的。找到灰烬使者之日可待啦！', `FemaleText_loc5`='王子對奈法利安的巢穴非常感興趣。如果有誰能殺死巨龍及其屬下，並將戰鬥經過告訴王子，我敢打賭王子會非常滿意的。必須找到灰燼使者!', `FemaleText_loc7`='El Maestro tiene un gran interés por la Guarida de Nefarian. Ojalá alguien pudiera vencer al dragón y a sus esbirros y volver a contar la historia al Príncipe. Apuesto a que eso conseguiría hacer que el príncipe hablase. ¡Podríamos encontrar la Crematoria!' WHERE `ID`=9469;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미즐하고 얘기 안 하면 왕 못 돼! 약삭빠른 미즐하고 얘기를 해 봐!', `MaleText_loc4`='你不跟米兹勒谈话的话是当不了国王的！跟他谈谈！', `MaleText_loc5`='你不跟米茲勒講話，你就不能變成國王!跟狡猾的米茲勒講話!', `MaleText_loc7`='¡Si no hablar con Mizzle, nunca ser $grey:reina;! ¡Habla con Mizzle el Astuto!' WHERE `ID`=9470;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러니까... 당신이 왕을 해치운 모양이군. 그 얼간이들이 당신을 새 왕으로 삼을 줄 알았다니까, 진짜! 그 멍청이들이 아는 거라고는 힘밖에 없거든.$B$B부하들을 많이 살려 둘수록 공물도 그만큼 많이 들어올 테니, 그것도 괜찮지. 재미있는 과제랄까... 당신이 떠나면 아마 왕 노릇은 계속 못 할 거야. 분명 그 촌뜨기 녀석들 중 하나가 나서서 당신 자리를 차지할 테니까.$B$B참, 혹시 내 열쇠 못 봤나?', `MaleText_loc4`='那么……你杀死了国王？我就知道这些家伙会拥戴你成为新国王的。我就知道！那些家伙只知道力量。$B$B似乎你赦免的跟随者越多，献殷勤的人也就越多。别这么不公平——我是说来一次有趣的挑战。如果你离开，我可不希望继续当国王。这些家伙肯定有人趁机取代你的地位。$B$B还有……你找到了我的钥匙，是吗？', `MaleText_loc5`='那麼...你殺死了國王?我就知道這些傢伙會擁戴你成為新國王的。我就知道!那些傢伙只知道力量。$B$B似乎你赦免的跟隨者越多，獻殷勤的人也就越多。別這麼不公平─我是說來一次有趣的挑戰。如果你離開，我也不敢期望繼續當國王。這些傢伙肯定有人趁機取代你的地位。$B$B還有...你找到了我的鑰匙，是嗎?', `MaleText_loc7`='¿Así que has matado al rey, eh? Sabía que esos tipos te harían $grey:reina;, ¡lo sabía! Solo entienden eso: el poder.$B$BParece ser que cuantos más esbirros mantengas con vida, más alto será tu tributo. No está tan mal... Diría que es un desafío interesante. Pero si te vas, no creo que sigas siendo $gel rey:la reina;. Sin duda, uno de esos palurdos ocupará tu lugar.$B$BOtra cosa, ¿no habrás conseguido encontrar mi llave, no?' WHERE `ID`=9471;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왕이 죽었다. 오, 이제 어쩌지! 약삭빠른 미즐을 불러와! 그가 다음에 어떻게 해야 하는지 알고 있다!', `MaleText_loc4`='国王死了——哦，不！召唤米兹勒！他知道下一步该怎么做！', `MaleText_loc5`='國王死了─哦，不!召喚米茲勒!他知道下一步該怎麼做!', `MaleText_loc7`='¡El rey está muerto, OH, NO! ¡Invoca a Mizzle el Astuto! ¡Sabe qué hay que hacer!' WHERE `ID`=9472;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 한 가지 알아두어야 할 것은 1만 년 동안의 삶을 기록할 수 있다 보니 삶에 대해서 좀 독특한 관점을 갖게 되더라는 거요. 오늘날 당신의 고난과 시련은 무의미하오.', `MaleText_loc4`='你必须明白，像我这样活了一万年的人，对生命有独特的看法。眼下你经受的考验和磨难都是毫无意义的。', `MaleText_loc5`='你必須明白，像我這樣活了一萬年的人，對生命有獨特的看法。現在你經受的考驗和磨難都是毫無意義的。', `MaleText_loc7`='Debes entender que 10,000 años de existencia me han proporcionado una perspectiva de la vida única. Tus tribulaciones carecen de sentido.' WHERE `ID`=9473;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어린 주인님께서 얼마나 야단법석을 하시던지... 꼭 세계의 운명을 그대로 어깨에 짊어지기라도 하신 것 같았을 것이오. 우리 세계에 대해 그런 비뚤어진 관점을 가질 수 있는 건 평범한 필멸의 생명체들뿐이지.$B$B안타깝게도 주인님이 남겨 주신 거라곤 이 빈약한 마법 비밀뿐이라오... 고서나 말도 안 되는 것들뿐이지. 나한테는 이런 시시한 마법이 필요 없지만 당신이라면 흥미가 있을지도 모르겠군.', `MaleText_loc4`='哦，年轻的主人制造的这一系列事件和慌乱。可以想象，世界的命运就掌控在他手中。只有人类才会对世界产生这种扭曲的看法。$B$B唉，他将奥术的秘密都告诉了我……圣契之类的无用之物。这种东西对我来说是一无是处，但是或许你对它们感兴趣。', `MaleText_loc5`='哦，年輕的主人製造的這一系列事件和慌亂。可以想像，世界的命運就掌控在他手中。只有人類才會對世界產生這種扭曲的看法。$B$B唉，他將秘法的秘密都告訴了我...聖契之類的無用之物。這種東西對我來說是一無是處，但是或許你對它們感興趣。', `MaleText_loc7`='¡Era increíble, el joven Maestro era todo drama y alboroto! Cualquiera pensaría que el destino del mundo recaía sobre sus hombros. Solo un mortal podría tener una perspectiva tan errónea de nuestro mundo.$B$BMe dejó con sus magros secretos mágicos... Unos tratados o alguna tontería parecida. A mí no me sirve de nada su magia, pero quizás a ti te interesen sus encantamientos.' WHERE `ID`=9474;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"가로나: 은신과 기만에 대한 연구"가 어디 있담! 이 책들은 꼭 되찾아야 되는데!', `MaleText_loc4`='“迦罗娜：潜行与诡计研究”在哪儿？必须找到它！', `MaleText_loc5`='「迦羅娜:潛行與詭計研究」在哪兒?必須找到它!', `MaleText_loc7`='¿Dónde está "Garona: un Estudio sobre el Sigilo y la Traición."? ¡Necesitamos que nos devuelvan los libros!' WHERE `ID`=9475;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='책을 도둑맞았소, $r 친구! 우리가 가장 귀중히 여기는 책 세 권을 말이오. 그 책들을 되찾아주면 반드시 보상을 해 주리다.', `MaleText_loc4`='被偷啦，$r！我们最珍贵的三卷卷轴。如果你能找回来的话，一定会得到丰厚的报酬的。', `MaleText_loc5`='被偷啦，$r!我們最珍貴的三卷卷軸。如果你能找回來的話，一定會得到豐厚的報酬的。', `MaleText_loc7`='¡Los han robado, $r! Tres de nuestros libros más valiosos. Si nos devuelves los libros, muy probablemente recibirás una recompensa.' WHERE `ID`=9476;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 공격을 모두 되받아치기 시작합니다!', `MaleText_loc4`='%s开始反击，展开报复！', `MaleText_loc5`='%s開始對受到的所有攻擊展開報復!', `MaleText_loc7`='¡%s comienza a responder a todos los ataques!' WHERE `ID`=9477;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 약골들 쓰러뜨리는 걸 도와라!', `MaleText_loc4`='帮我粉碎这些微不足道的家伙！', `MaleText_loc5`='幫我粉碎這些微不足道的傢伙!', `MaleText_loc7`='¡Ayúdame a aplastar a estos impresentables!' WHERE `ID`=9478;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 열쇠가 맞는 것 같아요!', `MaleText_loc4`='我是这么想的！', `MaleText_loc5`='我是這麼想的!', `MaleText_loc7`='¡Supongo!', `FemaleText_loc1`='그 열쇠가 맞는 것 같아요!', `FemaleText_loc4`='我是这么想的！', `FemaleText_loc5`='我是這麼想的!', `FemaleText_loc7`='¡Supongo!' WHERE `ID`=9479;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새 왕에게 걸맞은 직무로군!', `MaleText_loc4`='这听起来是个值得去做的任务！', `MaleText_loc5`='這聽起來是個值得去做的任務!', `MaleText_loc7`='Suena como una tarea digna del nuevo rey.', `FemaleText_loc1`='새 왕에게 걸맞은 직무로군!', `FemaleText_loc4`='这听起来是个值得去做的任务！', `FemaleText_loc5`='這聽起來是個值得去做的任務!', `FemaleText_loc7`='Suena como una tarea digna de la nueva reina.' WHERE `ID`=9480;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너 감히 나한테 덤비다니! 난 왕이고 영원히 왕으로 지낼 거다!!!', `MaleText_loc4`='别向我挑战，矮小的家伙！现在我是国王啦，永远都是！！！', `MaleText_loc5`='別向我挑戰，矮小的傢伙!現在我是國王啦，永遠都是!!!', `MaleText_loc7`='¡No sois un desafío para mí, babosas! ¡Soy el rey ahora y seré el rey PARA SIEMPRE!' WHERE `ID`=9481;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으욱!', `MaleText_loc4`='啊！', `MaleText_loc5`='啊!', `MaleText_loc7`='¡Bah!' WHERE `ID`=9482;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 두루마리에 적힌 방대한 분량의 기술적인 내용은 무슨 말인지 전혀 이해할 수가 없습니다.', `MaleText_loc4`='<你无法理解这份卷轴上记载的任何技术。>', `MaleText_loc5`='<你無法理解這份卷軸上記載的任何技術。>', `MaleText_loc7`='<No puedes comprender nada de la jerga técnica que aparece en el pergamino.>' WHERE `ID`=9483;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 두루마리에는 야전수리로봇의 설계도가 그려져 있습니다.', `MaleText_loc4`='<羊皮纸上画着的是修理机器人的结构示意图。>', `MaleText_loc5`='<羊皮紙上畫著的是修理機器人的結構示意圖。>', `MaleText_loc7`='<En el papiro hay un dibujo esquemático de un robot de reparación de campo.>' WHERE `ID`=9484;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='설계도를 자신의 기계공학 책에 베낍니다.', `MaleText_loc4`='<将这份结构示意图复制到你的工程学书本中。>', `MaleText_loc5`='<將這份結構示意圖複製到你的工程學書本中。>', `MaleText_loc7`='<Copiar el dibujo esquemático en tu cuaderno de ingeniería>', `FemaleText_loc1`='설계도를 자신의 기계공학 책에 베낍니다.', `FemaleText_loc4`='<将这份结构示意图复制到你的工程学书本中。>', `FemaleText_loc5`='<將這份結構示意圖複製到你的工程學書本中。>', `FemaleText_loc7`='<Copiar el dibujo esquemático en tu cuaderno de ingeniería>' WHERE `ID`=9485;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='복잡한 이 설계도의 내용을 이해하기에는 기계공학 숙련도나 지식이 부족합니다.', `MaleText_loc4`='<依你目前的工程学技能是看不懂这张复杂的结构示意图的。>', `MaleText_loc5`='<依你目前的工程學技能是看不懂這張複雜的結構圖的。>', `MaleText_loc7`='<El dibujo esquemático es demasiado complicado para tu escaso conocimiento de ingeniería.>' WHERE `ID`=9486;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이미 이 로봇의 제작 방법과 기능에 대해 잘 알고 있습니다.', `MaleText_loc4`='<你精通制造和操作这个机器人。>', `MaleText_loc5`='<你精通製造和操作這個機器人。>', `MaleText_loc7`='<Entiendes a la perfección la creación y el funcionamiento de este robot.>' WHERE `ID`=9487;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 세계를 구성하는 구조물은 아주 섬세하기 때문에 약간의 지식을 응용하는 것만으로도 상처를 낼 수 있답니다. 그리해서 균열이 생겨나는 것이지요.', `MaleText_loc4`='世界的构造精妙细致。只靠某些知识和对已知知识的应用是不可能破坏世界构造的。裂缝也由此产生。', `MaleText_loc5`='世界的構造精妙細緻。只靠某些知識和對已知知識的應用是不可能破壞世界構造的。裂隙也由此產生。', `MaleText_loc7`='La tela con la que está tejido nuestro mundo, es extremadamente delicada. Solo se necesita algo de conocimiento y saber aplicar dicho conocimiento para rasgar la tela. Así es como nacen las discordias.' WHERE `ID`=9488;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 당신의 존재를 알아채고 황천의 차원문을 엽니다!', `MaleText_loc4`='%s察觉到你的存在，打开了虚空之门！', `MaleText_loc5`='%s感覺到你的存在，並開始打開虛空傳送門!', `MaleText_loc7`='%s siente tu presencia y abre un portal abisal.' WHERE `ID`=9489;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='초루쉬가 죽었어! 너 이제 죽는다!', `MaleText_loc4`='克鲁什死啦！现在你也去死吧！', `MaleText_loc5`='克魯什死啦!現在你也去死吧!', `MaleText_loc7`='¡Cho''Rush morir! ¡AHORA MUERE!' WHERE `ID`=9490;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드의 백성들이여, 오그리마의 주민들이여, 모두 와서 호드의 영웅을 찬양하라. 오늘, 우리 영광스러운 대족장님의 가호 아래 $n|1이;가; 검은용군단에 죽음의 일격을 가했노라! 검은용군단의 여왕 오닉시아가 처형됐도다!', `MaleText_loc4`='部落的人民，奥格瑞玛的居民，来吧，聚集在一起，欢庆部落英雄的诞生！今天，$n在我们伟大的酋长的领导下，给予了黑龙致命的一击。奥妮克希亚已经被斩杀了！', `MaleText_loc5`='部落的人民，奧格瑪的城民，來吧，聚集到一起歡慶部落英雄的誕生。今天，$n，在我們偉大的大酋長的領導下，給予了黑龍軍團致命的一擊。黑龍公主奧妮克希亞死啦!', `MaleText_loc7`='Miembros de la Horda, ciudadanos de Orgrimmar, venid y reuníos para homenajear un hecho heroico. En el día de hoy, $n, bajo los auspicios de nuestro glorioso Jefe de Guerra, asestó un golpe mortal al Vuelo Negro. ¡Onyxia, la madre de linaje del Vuelo, ha sido asesinada!' WHERE `ID`=9491;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부인할 수 없는 대족장님의 힘을 보라! 용을 처치한 영웅들의 환성에 맞춰 기쁨의 춤을 추자!', `MaleText_loc4`='见证酋长的勿庸置疑的能力吧！在屠龙大军的战斗口号声中精神抖擞地前进吧！', `MaleText_loc5`='見證大酋長的勿庸置疑的能力吧!在屠龍大軍的戰鬥口號聲中精神抖擻地前進吧!', `MaleText_loc7`='¡Sean testigos del innegable poder de su Jefe de Guerra! ¡Sientan cómo los eleva el grito de llamamiento de sus cazadragones!' WHERE `ID`=9492;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적을 똑바로 응시하게, $r 친구. 가장 막강하다는 용들마저 호드의 힘 앞에서 얼마나 보잘것없는가! 우리에게 맞서는 모든 이들이 똑같은 운명을 맞이할 것이야!', `MaleText_loc4`='盯着敌人，$r。看吧，强大的部落足以对付巨龙！所有跟我们做对的人都是这种下场！', `MaleText_loc5`='盯著敵人，$r。看吧，強大的部落足以對付巨龍!所有跟我們做對的人都是這種下場!', `MaleText_loc7`='¡Observa al enemigo, $r! ¡Observa lo que el poder de la Horda hace con los dragones incluso más poderosos! Todos aquellos que se opongan a nosotros, sufrirán un destino parecido.' WHERE `ID`=9493;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 대족장님의 명을 받드는 자, 호드의 일원이다!', `MaleText_loc4`='我当然是来传达酋长的命令的。我是部落的。', `MaleText_loc5`='我當然是來傳達大酋長的命令的。我是部落的。', `MaleText_loc7`='Yo soy quien ejecuta las órdenes del Jefe de Guerra, nadie me puede cuestionar. Yo soy la Horda.' WHERE `ID`=9494;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드의 주민들과 모든 얼라이언스여! 오늘, 역사가 이루어졌노라. $n|1이;가; 우리 왕국의 질서를 파괴하려 했던 자를 물리쳤으니 모두 함께 모여 우리 영웅들에게 경의를 표해야 마땅할 것이다.', `MaleText_loc4`='暴风城的城民和盟友们，今天，有人创造了历史。$n已经杀死了那个妄图篡夺王权的家伙。都聚过来吧，跟我们一起庆祝英雄的诞生。', `MaleText_loc5`='暴風城的城民和盟友們，今天，有人創造了歷史。$n已經殺死了那個妄圖篡奪王權的傢伙。都聚過來吧，跟我們一起慶祝英雄的誕生。', `MaleText_loc7`='Ciudadanos y aliados de Ventormenta, en el día de hoy, hemos hecho historia. $n ha derrotado a quienes pretendían usurpar el gobierno del reino. Venid y reuníos para honrar a nuestros héroes.' WHERE `ID`=9495;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스의 힘을 보라! 공포의 여군주 오닉시아의 목이 잘려 홍예문에 걸려 있다! 용을 처치한 영웅들의 환성에 함께 기쁨의 춤을 추자!', `MaleText_loc4`='看看强大的联盟吧！奥妮克希亚的徽记悬挂在拱门之上！让我们为屠龙大军高声欢呼吧！', `MaleText_loc5`='看看強大的聯盟吧!奧妮克希亞的頭顱懸掛在拱門之上!讓我們為屠龍大軍高聲歡呼吧!', `MaleText_loc7`='¡Contemplen el poder de la Alianza! La aterradora Onyxia, está colgada de los arcos. ¡Que el grito de llamamiento de los cazadores de dragones eleve sus espíritus!' WHERE `ID`=9496;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='국왕 폐하를 위해 이 한 목숨 바칠 따름이노라.', `MaleText_loc4`='我活着就是为了为国王服务。', `MaleText_loc5`='我活著就是為了為國王服務。', `MaleText_loc7`='Solo vivo para servir a nuestro rey.' WHERE `ID`=9497;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아마 그대들도 언젠가는 오늘의 영웅들처럼 얼라이언스를 위해 위대한 공헌을 하게 될 것이다. 영웅들에게 경의를!', `MaleText_loc4`='或许有一天，你对联盟的贡献会跟你今日所见的英雄一样伟大。尊重英雄吧，$n。', `MaleText_loc5`='或許有一天，你對聯盟的貢獻會跟你今日所見的英雄一樣偉大。尊重英雄吧，$n。', `MaleText_loc7`='Quizás algún día, tus contribuciones a la Alianza sean tan grandes como las de los héroes que has visto hoy. Hónrales, $n.' WHERE `ID`=9498;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='찾아 주다니 영광일세.', `MaleText_loc4`='主人，您的到来令我们倍感荣幸。', `MaleText_loc5`='$g先生:女士;，你的到來令我們倍感榮幸。', `MaleText_loc7`='Nos honras con tu presencia, mi $gseñor:señora;.' WHERE `ID`=9499;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$R|1이여;여;, 이제 식물들을 함부로 건드리면 안 된다는 걸 배웠겠지.', `MaleText_loc4`='它会教你如果挑选草药的，$r。', `MaleText_loc5`='它會教你如果挑選草藥的，$r。', `MaleText_loc7`='Eso te enseñará a dejar la hierba, $r.' WHERE `ID`=9500;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맙소사! 저기 검투장에 머쉬고그가 있잖아.', `MaleText_loc4`='神圣的母牛！姆斯高格就在厄运之槌里。', `MaleText_loc5`='神聖的母牛!姆斯高格就在厄運之槌裡。', `MaleText_loc7`='¡Oh cielos! El que está ahí abajo en La Marra es Mushgog.', `FemaleText_loc1`='맙소사! 저기 검투장에 머쉬고그가 있잖아.', `FemaleText_loc4`='神圣的母牛！姆斯高格就在厄运之槌里。', `FemaleText_loc5`='神聖的母牛!姆斯高格就在厄運之槌裡。', `FemaleText_loc7`='¡Oh cielos! El que está ahí abajo en La Marra es Mushgog.' WHERE `ID`=9501;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저것 좀 봐! 누가 머쉬고그와 싸우고 있다고!', `MaleText_loc4`='看那边！有人在跟姆斯高格打斗！', `MaleText_loc5`='看那邊!有人在跟姆斯高格打鬥!', `MaleText_loc7`='¡Eh, mira! ¡Hay alguien luchando contra Mushgog!', `FemaleText_loc1`='저것 좀 봐! 누가 머쉬고그와 싸우고 있다고!', `FemaleText_loc4`='看那边！有人在跟姆斯高格打斗！', `FemaleText_loc5`='看那邊!有人在跟姆斯高格打鬥!', `FemaleText_loc7`='¡Eh, mira! ¡Hay alguien luchando contra Mushgog!' WHERE `ID`=9502;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기 검투장에 있는 게 라자 맞나? 아주 재미있겠는 걸!', `MaleText_loc4`='在厄运之槌那儿的是拉扎尔吗？这可真令人激动！', `MaleText_loc5`='在厄運之槌那兒的是拉札爾嗎?這可真令人激動!', `MaleText_loc7`='¿No es aquel El Razza, ahí en La Marra? ¡Esto va a estar bien!', `FemaleText_loc1`='저기 검투장에 있는 게 라자 맞나? 아주 재미있겠는 걸!', `FemaleText_loc4`='在厄运之槌那儿的是拉扎尔吗？这可真令人激动！', `FemaleText_loc5`='在厄運之槌那兒的是拉札爾嗎?這可真令人激動!', `FemaleText_loc7`='¿No es aquel El Razza, ahí en La Marra? ¡Esto va a estar bien!' WHERE `ID`=9503;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야! 진짜 제대로 싸우고있다!', `MaleText_loc4`='喔！他们进去啦！', `MaleText_loc5`='喔!他們進去啦!', `MaleText_loc7`='¡Guauuu! ¡Ahora sí que se están dando bien!', `FemaleText_loc1`='이야! 진짜 제대로 싸우고있다!', `FemaleText_loc4`='喔！他们进去啦！', `FemaleText_loc5`='喔!他們進去啦!', `FemaleText_loc7`='¡Guauuu! ¡Ahora sí que se están dando bien!' WHERE `ID`=9504;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라자가 머쉬고그에게 당하고 말았군!', `MaleText_loc4`='拉扎尔给姆斯高格带来了更多的肥料！', `MaleText_loc5`='拉札爾給姆斯高格帶來了更多的肥料!', `MaleText_loc7`='El Razza acaba de hacer más fertilizante para Mushgog.', `FemaleText_loc1`='라자가 머쉬고그에게 당하고 말았군!', `FemaleText_loc4`='拉扎尔给姆斯高格带来了更多的肥料！', `FemaleText_loc5`='拉札爾給姆斯高格帶來了更多的肥料!', `FemaleText_loc7`='El Razza acaba de hacer más fertilizante para Mushgog.' WHERE `ID`=9505;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 본격적인 싸움이 시작되겠군! 검투장에 무패의 스카르가 등장했다!', `MaleText_loc4`='重要的决斗即将开始！无敌的斯卡尔就在巨槌竞技场！', `MaleText_loc5`='重要的決鬥即將開始!無敵的斯卡爾就在巨槌競技場!', `MaleText_loc7`='¡Es la hora del evento principal! ¡Skarr el Inquebrantable está en La Marra!', `FemaleText_loc1`='이제 본격적인 싸움이 시작되겠군! 검투장에 무패의 스카르가 등장했다!', `FemaleText_loc4`='重要的决斗即将开始！无敌的斯卡尔就在巨槌竞技场！', `FemaleText_loc5`='重要的決鬥即將開始!無敵的斯卡爾就在巨槌競技場!', `FemaleText_loc7`='¡Es la hora del evento principal! ¡Skarr el Inquebrantable está en La Marra!' WHERE `ID`=9506;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 다른 누군가가 스카르에게 도전을 하는 것 같은데! 저런 불쌍할 데가! 목숨이라도 부지하면 다행일 거야!', `MaleText_loc4`='似乎斯卡尔已经找到了下一个挑战者！想取代他的位置吗！', `MaleText_loc5`='似乎斯卡爾已經找到了下一個挑戰者!想取代他的位置嗎!', `MaleText_loc7`='¡Parece que Skarr ha encontrado a su siguiente contrincante! No me gustaría estar en el lugar de ese pobre imbécil.', `FemaleText_loc1`='또 다른 누군가가 스카르에게 도전을 하는 것 같은데! 저런 불쌍할 데가! 목숨이라도 부지하면 다행일 거야!', `FemaleText_loc4`='似乎斯卡尔已经找到了下一个挑战者！想取代他的位置吗！', `FemaleText_loc5`='似乎斯卡爾已經找到了下一個挑戰者!想取代他的位置嗎!', `FemaleText_loc7`='¡Parece que Skarr ha encontrado a su siguiente contrincante! No me gustaría estar en el lugar de ese pobre imbécil.' WHERE `ID`=9507;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쓰러진다, 프레이저! 쓰러진다, 프레이저! 쓰러지... 뭐? 프레이저가 아니라고?', `MaleText_loc4`='弗雷瑟倒下去啦！弗雷瑟倒下去啦！弗雷瑟……嗯？那不是弗雷瑟？', `MaleText_loc5`='弗雷瑟倒下去啦!弗雷瑟倒下去啦!弗雷瑟...嗯?那不是弗雷瑟?', `MaleText_loc7`='¡Allá va Frazier! ¡Allá va Frazier! ¡Allá va...! ¿Eh? ¿No era Frazier?', `FemaleText_loc1`='쓰러진다, 프레이저! 쓰러진다, 프레이저! 쓰러지... 뭐? 프레이저가 아니라고?', `FemaleText_loc4`='弗雷瑟倒下去啦！弗雷瑟倒下去啦！弗雷瑟……嗯？那不是弗雷瑟？', `FemaleText_loc5`='弗雷瑟倒下去啦!弗雷瑟倒下去啦!弗雷瑟...嗯?那不是弗雷瑟?', `FemaleText_loc7`='¡Allá va Frazier! ¡Allá va Frazier! ¡Allá va...! ¿Eh? ¿No era Frazier?' WHERE `ID`=9508;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='1만 년간의 기록된 지식이 모여 있다 보니 도서관에 쓸데없는 것들이 몰려오곤 한다니까. 책을 도난당하고, 회수하고, 다시 도난당하고 하는 건 매일 있는 일이라오.', `MaleText_loc4`='拥有万年历史的知识卷轴将那些邪恶的家伙吸引到图书馆。大量的书籍被盗，被找回之后再次被盗。', `MaleText_loc5`='擁有萬年曆史的知識卷軸將那些邪惡的傢伙吸引到圖書館。大量的書籍被盜，被找回之後再次被盜。', `MaleText_loc7`='10,000 años de conocimiento registrado suele atraer a los elementos inadecuados a El Athenaeum. Se roban libros, se recuperan y se vuelven a robar todos los días.' WHERE `ID`=9509;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='킬드라스는 상황을 너무 부풀리는 경향이 있단 말이죠. 예를 들자면 "가로나: 은신과 기만에 대한 연구"는 400번 넘게 도난당했던 책이랍니다.$B$B책에는 도서관의 낙인이 있어서 허락 없이 아무나 읽을 수 없지요.', `FemaleText_loc4`='基尔达斯总是过分夸大。比如，“迦罗娜：潜行与诡计研究”已经被偷过400多次啦。$B$B神殿的标志保护着这本卷轴，防止任何人偷看。', `FemaleText_loc5`='基爾達斯總是過分誇大。比如，「迦羅娜:潛行與詭計研究」已經被偷過400多次啦。$B$B圖書館的標誌保護著這本卷軸，防止任何人偷看。', `FemaleText_loc7`='Kildrath suele dramatizar la situación. Por ejemplo, "Garona: un Estudio sobre el Sigilo y la Traición," ha sido robado más de 400 veces.$B$BLa marca de El Athenaeum protege los libros, evitando que alguien sin autorización los vea.' WHERE `ID`=9510;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 한숨을 쉽니다.', `FemaleText_loc4`='%s叹了口气。', `FemaleText_loc5`='%s嘆了一口氣。', `FemaleText_loc7`='%s suspira.' WHERE `ID`=9511;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='언제 정신들을 차리려나?', `FemaleText_loc4`='他们什么时候才能吸取教训？', `FemaleText_loc5`='他們什麼時候學習?', `FemaleText_loc7`='¿Cuándo aprenderán?' WHERE `ID`=9512;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='바보 녀석! 아직도 듀이십진분류법을 익히지 못했단 말이냐? 벌써 우리 밑에서 일을 하기 시작한 지 3,000년이나 됐는데! 무능한 어릿광대 같으니...', `FemaleText_loc4`='愚蠢！你没有学过杜威十进制吗？至少你也已经为我们工作3000年啦！无能的家伙。', `FemaleText_loc5`='愚蠢!你沒有學過杜威十進位嗎?至少你也已經為我們工作3,000年啦!無能的傢伙。', `FemaleText_loc7`='¡Imbécil! ¿Todavía no has aprendido el sistema decimal de Dewey? Llevas más de 3,000 años trabajando para nosotros. Bufón incompetente.' WHERE `ID`=9513;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 투덜거립니다.', `MaleText_loc4`='%s咕哝着发起了牢骚。', `MaleText_loc5`='%s發牢騷。', `MaleText_loc7`='%s refunfuña.' WHERE `ID`=9514;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꾐에 빠져 이곳을 떠나지 않을 것이다.', `MaleText_loc4`='我不会受到引诱离开这儿的。', `MaleText_loc5`='我不會受到引誘離開這兒的。', `MaleText_loc7`='Nadie me hará salir de este lugar.' WHERE `ID`=9515;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<로브 속에서 무디고 납작한 엘프 검을 꺼내 주는 리드로스>$B$B아주 오래전, 고대의 전쟁이 일어나기 훨씬 전부터 이 검이 있었지.', `MaleText_loc4`='<莱德罗斯将手伸进他的长袍，拿出一把又盾又扁的精灵刀。>$B$B在过去，在远古战争之前，他们就是用这把刀来求生的。', `MaleText_loc5`='<萊德羅斯將手伸進他的長袍，拿出一把又鈍又扁的精靈劍刀。>$B$B在過去，甚至是在先祖之戰之前，這把劍就已經存在了。', `MaleText_loc7`='<Lydros mete la mano en su toga y saca una espada élfica, plana y sin brillo.>$B$BEsta espada ya existía en el pasado, mucho antes de La Guerra de los Ancestros.' WHERE `ID`=9516;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 멋지군요, 현자님. 계속 말씀해 주십시오.', `MaleText_loc4`='真令人着迷啊，博学者。请继续。', `MaleText_loc5`='真令人著迷啊，博識者。請繼續。', `MaleText_loc7`='Fascinante, Tradicionalista. Continúa, por favor.', `FemaleText_loc1`='아주 멋지군요, 현자님. 계속 말씀해 주십시오.', `FemaleText_loc4`='真令人着迷啊，博学者。请继续。', `FemaleText_loc5`='真令人著迷啊，博識者。請繼續。', `FemaleText_loc7`='Fascinante, Tradicionalista, por favor.' WHERE `ID`=9517;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 검은 위상들의 자손들과 함께 예식을 치르면서 만들어져야만 했소. 참으로 보기 드문 일이지... 용이 직접 기꺼이 그 숨결로 마법이 걸린 쇳덩이에 열을 가하고 모양을 다듬어야 할 뿐 아니라, 자신들의 피에 날을 담금질해서 그들 마법의 분노를 담아야 하니까 말이오.', `MaleText_loc4`='在仪式中，必须使用守护者的后代来锻造这柄剑。真是少见啊……龙不得不锻造并为这柄剑附魔，还得牺牲自己的后代做为附魔的调和剂。', `MaleText_loc5`='在儀式中，必須使用守護巨龍的後代來鍛造這柄劍。真是少見啊...不只是龍必須要以他的噴焰來替那些金屬加熱還有融化，還必須以他們的血來做為媒介，讓他們的狂怒能附加在長劍的魔法上。', `MaleText_loc7`='La espada tenía que hacerse en una ceremonia con los hijos de los Aspectos. Una extraña ocurrencia... Ya que no solo un dragón, voluntariamente, tenía que calentar y moldear el metal encantado con su aliento, sino que también necesitaban contener la furia de su propio encantamiento utilizando su sangre como temple.' WHERE `ID`=9518;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='(계속)', `MaleText_loc4`='（继续。）', `MaleText_loc5`='(繼續。)', `MaleText_loc7`='(Continuar.)', `FemaleText_loc1`='(계속)', `FemaleText_loc4`='（继续。）', `FemaleText_loc5`='(繼續。)', `FemaleText_loc7`='(Continuar.)' WHERE `ID`=9519;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='8,000년이 넘는 시간 동안 이런 검은 단 몇 개밖에 만들어지지 않았소. 각 검은 그 힘과 모양 면에서 모두 아주 독특하지. 쿠엘세라의 검은 바로 그 검을 만든 이의 특성을 지니게 된다오.', `MaleText_loc4`='8,000年来只铸造出少量的剑——每柄剑的威力和外观都是独一无二的。奎尔赛拉之剑将沿袭其锻造者的特点。', `MaleText_loc5`='8,000年來只有極少數的劍被鑄造出來─每柄劍的威力和外觀都是獨一無二的。奎爾賽拉之劍將沿襲其鍛造者的特點。', `MaleText_loc7`='Durante el transcurso de 8,000 años, se crearon pocas espadas. Cada una de ellas tenía un poder y una apariencia únicos. Las espadas de Quel''Serrar adoptaban las características de su creador.' WHERE `ID`=9520;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='(계속)', `MaleText_loc4`='（继续。）', `MaleText_loc5`='(繼續。)', `MaleText_loc7`='(Continuar.)', `FemaleText_loc1`='(계속)', `FemaleText_loc4`='（继续。）', `FemaleText_loc5`='(繼續。)', `FemaleText_loc7`='(Continuar.)' WHERE `ID`=9521;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전설에 의하면 5대 위상들이 힘을 합쳐 어떤 정체불명의 존재에게 전설의 쿠엘세라의 검을 하나 만들어 줬다고 하오. 네파리안과 데스윙의 역겨운 졸개들이 우리 세계에 들어오기 전, 5대 위상이 그렇게 회합을 한 것을 일컬어 ''상변화''라 칭했지. 오색 검 쿠엘세라는 가장 영광스러운 창조물이라 생각할 수밖에 없소이다.', `MaleText_loc4`='在传说中，奎尔塞拉之剑是由一位不知名的铁匠结合了五条守护巨龙的力量锻造而成的。在奈法利安和死亡之翼扰乱我们的世界之前，守护巨龙的聚会被称为“五色集会”。看起来五色圣剑奎尔塞拉是他们最为显赫的创作之一。', `MaleText_loc5`='謠傳傳說中獨一無二的奎爾賽拉之劍是由一個不知名的鐵匠，結合了五條守護巨龍的力量鍛造而成的。在奈法利安和死亡之翼擾亂我們的世界之前，守護巨龍之間的集會被稱為「稜彩」。我只能猜想奎爾賽拉·稜彩之劍是一件最為顯赫的傑作。', `MaleText_loc7`='""Corren rumores sobre una espada legendaria de Quel''Serrar creada por el poder legendario de los cinco Aspectos, para una entidad desconocida. Antes de que las abominaciones de Nefarian y Alamuerte fueran empujadas a nuestro mundo, esas reuniones de los Aspectos estaban representadas por el término "Prismático". Solo puedo asumir que la Espada Prismática de Quel''Serrar fue una creación gloriosa."' WHERE `ID`=9522;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='(계속)', `MaleText_loc4`='（继续。）', `MaleText_loc5`='(繼續。)', `MaleText_loc7`='(Continuar.)', `FemaleText_loc1`='(계속)', `FemaleText_loc4`='（继续。）', `FemaleText_loc5`='(繼續。)', `FemaleText_loc7`='(Continuar.)' WHERE `ID`=9523;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 내가 당신에게 주는 것은 불에 닿지도, 열에 쏘이지도, 다듬어지지도 않은, 가장 기본적인 형태의 검이오.$B$B이제 기꺼이 이 검에 마법을 불어넣어 줄 용을 찾기만 하면 되는 것이오.$B$B당신이 불멸의 생명체였다면 이런 일이 가능할 수 있겠지만, 당신은 평범한 필멸의 생명체인 만큼 어느 순간 갑자기 죽을지도 모르는 일이니 하급 용들 중 하나를 설득해 볼 것을 권하고 싶소이다.', `MaleText_loc4`='我能给你的只有这把未经烧制、未经加工的刀刃——最原始、最基本的形态。$B$B现在你只需去找一条愿意为这把刀附魔的龙。$B$B如果你能长生不老的话，或许这还有可能；但是你是凡人，随时都可能命丧黄泉，我建议你试着找体型较小的龙来帮你完成这把剑。', `MaleText_loc5`='我能給你的只有這把未經燒制、未經加工的刀刃─最原始、最基本的形態。$B$B現在你只需去找一條願意為這把刀附魔的龍。$B$B如果你能長生不老的話，或許這還有可能;但是你是凡人，隨時都可能命喪黃泉，我建議你試著找體型較小的龍來幫你完成這把劍。', `MaleText_loc7`='Lo que te ofrezco ahora, es una de esas espadas, sin fuego, sin calor y sin tratar, una espada en su forma más básica.$B$BAhora solo necesitas encontrar un dragón que, voluntariamente, encante la espada.$B$BSi tu vida fuera eterna, podrías hacerlo, pero como eres mortal y podrías morir en cualquier momento, te recomiendo que intentes convencer a uno de los dragones inferiores para que lo haga.' WHERE `ID`=9524;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='허걱;;', `MaleText_loc4`='嗯？', `MaleText_loc5`='嗯?', `MaleText_loc7`='¿Eh?', `FemaleText_loc1`='허걱;;', `FemaleText_loc4`='嗯？', `FemaleText_loc5`='嗯?', `FemaleText_loc7`='¿Eh?' WHERE `ID`=9525;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은용군단의 여왕에 대해서 들어 본 적 있소? 이름이 오닉시아라고 하는 것 같던데...', `MaleText_loc4`='你听说过黑龙公主吗？我想她名叫奥妮克希亚……', `MaleText_loc5`='你聽說過黑龍公主嗎?我想她名叫奧妮克希亞...', `MaleText_loc7`='¿Has oído hablar de la madre de linaje del Vuelo Negro? Creo que se llama Onyxia...' WHERE `ID`=9526;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='들어본 것 같긴 한데... 그럼 이제 뭘 해야 합니까?', `MaleText_loc4`='或许吧……我现在能做什么呢？', `MaleText_loc5`='或許吧...我現在能做什麼呢?', `MaleText_loc7`='Quizás... ¿Qué tengo que hacer ahora?', `FemaleText_loc1`='들어본 것 같긴 한데... 그럼 이제 뭘 해야 합니까?', `FemaleText_loc4`='或许吧……我现在能做什么呢？', `FemaleText_loc5`='或許吧...我現在能做什麼呢?', `FemaleText_loc7`='Quizás... ¿Qué tengo que hacer ahora?' WHERE `ID`=9527;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바쁘니까 방해하지 말게.', `MaleText_loc4`='我可没时间停下来。', `MaleText_loc5`='我可沒時間停下來。', `MaleText_loc7`='No tengo tiempo para interrupciones.' WHERE `ID`=9528;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='렉스로트, 토륨 족쇄를 잃어버렸습니다.', `MaleText_loc4`='雷克斯洛特，我把瑟银镣铐弄丢了。', `MaleText_loc5`='雷克斯洛特，我把瑟銀鐐銬弄丟了。', `MaleText_loc7`='Lexlort, he perdido los grilletes de torio.', `FemaleText_loc1`='렉스로트, 토륨 족쇄를 잃어버렸습니다.', `FemaleText_loc4`='雷克斯洛特，我把瑟银镣铐弄丢了。', `FemaleText_loc5`='雷克斯洛特，我把瑟銀鐐銬弄丟了。', `FemaleText_loc7`='Lexlort, he perdido los grilletes de torio.' WHERE `ID`=9529;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나타노스, 썩은 사과를 잃어버려서 하나 더 필요합니다.', `MaleText_loc4`='纳萨诺斯，我把腐烂的苹果弄丢啦。我需要一个。', `MaleText_loc5`='納薩諾斯，我把腐爛的蘋果弄丟啦。我需要一個。', `MaleText_loc7`='Nathanos, he perdido la manzana podrida. Necesito otra.', `FemaleText_loc1`='나타노스, 썩은 사과를 잃어버려서 하나 더 필요합니다.', `FemaleText_loc4`='纳萨诺斯，我把腐烂的苹果弄丢啦。我需要一个。', `FemaleText_loc5`='納薩諾斯，我把腐爛的蘋果弄丟啦。我需要一個。', `FemaleText_loc7`='Nathanos, he perdido la manzana podrida. Necesito otra.' WHERE `ID`=9530;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 도와 줄 일이라도 있소?', `MaleText_loc4`='我能帮忙吗？', `MaleText_loc5`='我能幫忙嗎?', `MaleText_loc7`='¿Puedo ayudarte?' WHERE `ID`=9531;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='치료제를 잃어버렸습니다, 의사 선생님! 더 가지고 계신 것 맞죠?', `MaleText_loc4`='医生，我把解药弄丢啦！再给我一些！！！', `MaleText_loc5`='醫生，我把治癒之法弄丟啦!再給我一些!!!', `MaleText_loc7`='¡He perdido el remedio, doctor! ¡¡¡Dime que tienes más!!!', `FemaleText_loc1`='치료제를 잃어버렸습니다, 의사 선생님! 더 가지고 계신 것 맞죠?', `FemaleText_loc4`='医生，我把解药弄丢啦！再给我一些！！！', `FemaleText_loc5`='醫生，我把治癒之法弄丟啦!再給我一些!!!', `FemaleText_loc7`='¡He perdido el remedio, doctor! ¡¡¡Dime que tienes más!!!' WHERE `ID`=9532;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서지, 잔질의 손길 치료제를 잃어버렸습니다! 도와 주세요!', `MaleText_loc4`='瑟尔格，我把赞吉尔之触的解药弄丢了！帮帮我！', `MaleText_loc5`='瑟爾格，我把贊吉爾之觸的治癒之法弄丟啦!幫幫我!', `MaleText_loc7`='Serge, he perdido el remedio para el Toque de Zanzil. ¡AYUDA!', `FemaleText_loc1`='서지, 잔질의 손길 치료제를 잃어버렸습니다! 도와 주세요!', `FemaleText_loc4`='瑟尔格，我把赞吉尔之触的解药弄丢了！帮帮我！', `FemaleText_loc5`='瑟爾格，我把贊吉爾之觸的治癒之法弄丟啦!幫幫我!', `FemaleText_loc7`='Serge, he perdido el remedio para el Toque de Zanzil. ¡AYUDA!' WHERE `ID`=9533;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혈투의 전장이라는 곳에 대해 들어 보신 적 있습니까?', `MaleText_loc4`='你听说过一个名叫厄运之槌的地方吗？', `MaleText_loc5`='你聽說過一個名叫厄運之槌的地方嗎?', `MaleText_loc7`='¿Alguna vez has oído hablar de un lugar llamado La Masacre?', `FemaleText_loc1`='혈투의 전장이라는 곳에 대해 들어 보신 적 있습니까?', `FemaleText_loc4`='你听说过一个名叫厄运之槌的地方吗？', `FemaleText_loc5`='你聽說過一個名叫厄運之槌的地方嗎?', `FemaleText_loc7`='¿Alguna vez has oído hablar de un lugar llamado La Masacre?' WHERE `ID`=9534;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇소. 하지만 내가 아는 그곳의 진짜 이름은 바로 엘드레탈라스요. 아주 오래전 나이트 엘프들의 마법을 간직한 보루였던 곳이지.$B$B엘드레탈라스에 대해 들어본 적 있으시오? 지금 내가 처한 상황과 우연히 맞아떨어진다고 할 수도 있겠지만... 나는 우연 같은 걸 믿지 않아서 말이오.', `MaleText_loc4`='是的，我知道它真正的名字——埃雷萨拉斯。许多许多年前，那儿曾是暗夜精灵的魔法研究基地。$B$B你知道埃雷萨拉斯吗，年轻的$c？也许有人会说这跟我目前的处境很巧合……但是我可不相信巧合这回事。', `MaleText_loc5`='是的，我知道埃德薩拉斯。多年前，那兒曾是夜精靈的魔法要塞。$B$B你知道埃德薩拉斯嗎，年輕人?也許有人會說這跟我目前的處境一致...但是我可不相信巧合這回事。', `MaleText_loc7`='Sí, pero lo conozco por su verdadero nombre: Eldre''Thalas. Fue un bastión de poder mágico para los elfos de la noche durante muchos, muchos años.$B$B¿Habías oído hablar de Eldre''Thalas, joven? Se podría decir que coincide con mi situación actual... Pero no creo en las coincidencias.' WHERE `ID`=9535;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어째서 우연이라고 말씀하시는 거죠, 라빈?', `MaleText_loc4`='拉比恩，你为什么说这是个巧合？', `MaleText_loc5`='拉比恩，你為什麼說這是個巧合?', `MaleText_loc7`='¿Por qué dices que se trata de una coincidencia, Rabine?', `FemaleText_loc1`='어째서 우연이라고 말씀하시는 거죠, 라빈?', `FemaleText_loc4`='拉比恩，你为什么说这是个巧合？', `FemaleText_loc5`='拉比恩，你為什麼說這是個巧合?', `FemaleText_loc7`='¿Por qué dices que se trata de una coincidencia, Rabine?' WHERE `ID`=9536;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세나리온 의회의 요원들이 엘드레탈라스의 현재 상황과 관련해 우려할 만한 정보를 알아냈소. 벼랑 끝에 매달린 상황이라 분명 힘깨나 쓰는 이들의 도움이 필요할 테지.$B$B하지만, 엘드레탈라스에서 제대로 행동을 취하려면 풍요의 열매라고 알려진 물건에 대해서 잘 알아 둬야 하오.', `MaleText_loc4`='塞纳里奥议会的人已经了解到埃雷萨拉斯的近况了。我陷入了僵局，不知如何是好。我很可能要向那些体格强健、善于作战的冒险者寻求帮助。$B$B但是，要对埃雷萨拉斯采取行动，就要了解关于丰饶之果的知识。', `MaleText_loc5`='塞納里奧議會的人已經瞭解埃德薩拉斯的近況了。我陷入僵局，不知如何是好。我很可能向那些體格強健、善於作戰的人尋求幫助。$B$B但是，要對埃德薩拉斯採取行動，就要瞭解關於豐碩的果實的知識。', `MaleText_loc7`='Unos miembros del Círculo Cenarion han descubierto información muy preocupante sobre la situación actual de Eldre''Thalas. Estoy en un punto muerto, no sé qué hacer y buscaré sin duda la ayuda de individuos capaces de combatir.$B$BSin embargo, para poder emprender cualquier acción en Eldre''Thalas, es necesario comprender el funcionamiento de un objeto conocido como la fruta de la fertilidad.' WHERE `ID`=9537;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='풍요의 열매라고요?', `MaleText_loc4`='丰饶之果？', `MaleText_loc5`='豐饒之果?', `MaleText_loc7`='¿La fruta de la fertilidad?', `FemaleText_loc1`='풍요의 열매라고요?', `FemaleText_loc4`='丰饶之果？', `FemaleText_loc5`='豐饒之果?', `FemaleText_loc7`='¿La fruta de la fertilidad?' WHERE `ID`=9538;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 오래전, 엘드레탈라스는 마법의 집합소였고 그 성스러운 전당 안에 사는 자들은 모두 엄청난 힘을 소유하고 있었소. 그중 밀리센트 세레네라는 나이트 엘프가 있었는데, 자연의 힘을 자유자재로 부여해 강력한 물건을 만들어 내는 식물학자였지.$B$B그녀의 업적 중 으뜸가는 것이 바로 풍요의 열매였소... 보호와 성장의 오라를 불어넣은 희귀하고 생기 넘치는 덩굴을 특별히 준비한 달샘에다 길렀는데, 엘드레탈라스 전체가 그 덩굴로 우거졌었소.', `MaleText_loc4`='多年前，埃雷萨拉斯是魔法师的集中地，居住在那些神圣的大厅中的人都能使用强大的魔法。米琳丝特·塞雷恩就是这样一名暗夜精灵——她是个博学者，她可以将大自然的力量灌输到她铸造的神器中。$B$B丰饶之果就是她的杰作……她利用特殊的月亮井制造出一种奇异的、具备保护和生长效力的藤蔓来。埃雷萨拉斯在藤蔓的滋养下日益繁华起来。', `MaleText_loc5`='多年前，埃德薩拉斯是魔法師的集中地，居住在那些神聖的大廳中的人都能使用強大的魔法。米莉仙·瑟琳就是這樣一名夜精靈─她是個自然學家，能將自然本身的力量灌輸到她鑄造的神器中。$B$B豐饒之果便是她的傑作...她利用特殊的月井製造出一種奇異的葡萄酒，具備保護和生長的效力。埃德薩拉斯在葡萄酒的滋養下日益繁華起來。', `MaleText_loc7`='En el pasado, Eldre''Thalas era un nexo de poder mágico y, quienes habitaban dentro de sus muros sagrados, tenían un inmenso poder. Una de esas elfas de la noche fue Millicent Serena, una naturista que canalizaba el poder de la naturaleza en los potentes artefactos que forjaba.$B$BLa fruta de la fertilidad fue su mayor logro... Utilizó una Poza de la Luna especialmente preparada, para sembrar una hiedra exótica y vibrante que fue imbuida de un aura de protección y crecimiento. Todo Eldre''Thalas floreció a partir de su existencia.' WHERE `ID`=9539;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런데 뭔가 잘못된 거군요?', `MaleText_loc4`='但是，有些事情好像出了差错，是吗？', `MaleText_loc5`='但是，有些事情好像出了差錯，是嗎?', `MaleText_loc7`='Pero algo salió mal, ¿no?', `FemaleText_loc1`='그런데 뭔가 잘못된 거군요?', `FemaleText_loc4`='但是，有些事情好像出了差错，是吗？', `FemaleText_loc5`='但是，有些事情好像出了差錯，是嗎?', `FemaleText_loc7`='Pero algo salió mal, ¿no?' WHERE `ID`=9540;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안타깝게도, 세상 일이 늘 그런 것 같소이다. 나를 비롯한 세나리온 의회의 다른 이들도 모두 고대의 전쟁 중에 밀리의 덩굴이 파괴되었을 거라 추측했었지... 이제야 알게 된 사실이지만 전혀 그렇지 않았던 거요.$B$B풍요의 열매는 살아남았소... 이제는 악령덩굴이라 불리고 있지만... 엘드레탈라스에 거처하는 칼날바람 알진이라는 악마 군주에 의해 타락하고 있었던 것이오.', `MaleText_loc4`='唉，事情似乎总是这样。和塞纳里奥议会的其他人一样，我也认为米琳的杰作在上古战争时就被毁掉了。但是我最近认识到，这种观点是错误的。$B$B丰饶之果并未被摧毁……尽管现在它被称为魔藤。它被埃雷萨拉斯的恶魔领主，荒野变形者奥兹恩污染了。', `MaleText_loc5`='唉，事情似乎總是這樣。和塞納里奧議會的其他人一樣，我也認為是米利的造物在先祖之戰中毀掉了。但是我已經認識到，這種觀點是錯誤的。$B$B豐碩的果實並未被摧毀...儘管現在它被稱為惡魔之藤。它被埃德薩拉斯的惡魔領主『狂野變形者』奧茲恩污染了。', `MaleText_loc7`='Sí, parece ser que algo siempre sale mal. Yo, al igual que el resto del Círculo Cenarion, asumí que la creación de Milli fue destruida durante La Guerra de los Ancestros. Pero, como he llegado a descubrir, no es cierto.$B$BLa fruta de la fertilidad sobrevivió... Aunque ahora se llama gangrevid. El señor demoníaco de esa sección de Eldre''Thalas, Alzzin el Formaferal, la está corrompiendo.' WHERE `ID`=9541;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='풍요의 열매, 그러니까 악령덩굴이 완전히 타락하도록 두면 어떻게 되죠?', `MaleText_loc4`='如果丰饶之果——或者说是魔藤——完全堕落，那会发生什么事呢？', `MaleText_loc5`='如果豐碩的果實─或是惡魔之藤─完全墮落，那會發生什麼事呢?', `MaleText_loc7`='¿Qué ocurriría si la fruta de la fertilidad, o la gangrevid, llegara a estar completamente corrupta?', `FemaleText_loc1`='풍요의 열매, 그러니까 악령덩굴이 완전히 타락하도록 두면 어떻게 되죠?', `FemaleText_loc4`='如果丰饶之果——或者说是魔藤——完全堕落，那会发生什么事呢？', `FemaleText_loc5`='如果豐碩的果實─或是惡魔之藤─完全墮落，那會發生什麼事呢?', `FemaleText_loc7`='¿Qué ocurriría si la fruta de la fertilidad, o la gangrevid, llegara a estar completamente corrupta?' WHERE `ID`=9542;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상... 상상조차 할 수 없소, $n. 확실한 건 그런 일이 발생하도록 내버려둬서는 안 된다는 사실이오. 그 덩굴을 반드시 파괴해야 하오. 악마의 타락으로부터 우리 자신을 보호하기 위해서가 아니더라도 밀리센트 세레네를 기리기 위해서... 밀리...$B$B바로 그대가 도와 줬으면 하는 거요.', `MaleText_loc4`='我……我无法想象，$n。我只知道我不能让这件事发生。它必须被摧毁的——就算不是为了阻止那些恶魔，也要为了米琳丝特·塞雷恩……米琳……$B$B我的朋友，这就是我希望你伸出援手的事情。', `MaleText_loc5`='我...我無法開始想像，$n。我只知道我不能讓這件事發生。它會被摧毀的─就算不毀在我們對巨魔的防禦上，也會毀在米莉仙·瑟琳的記憶上...米莉...$b$b我的朋友，這就是我希望你伸出援手的事情。', `MaleText_loc7`='No puedo ni imaginármelo, $n. Lo único que sé, es que no pienso permitir que eso ocurra. Hay que destruirla... Si no por mantenernos a salvo de la mancha demoníaca, al menos en memoria de Millicent Serena... Milli...$B$BY, $gamigo mío:amiga mía; espero que me ayudes.' WHERE `ID`=9543;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 어떻게 하면 되죠, 라빈?', `MaleText_loc4`='拉比恩，你要我做什么？', `MaleText_loc5`='拉比恩，你要我做什麼?', `MaleText_loc7`='¿Qué quieres que haga, Rabine?', `FemaleText_loc1`='제가 어떻게 하면 되죠, 라빈?', `FemaleText_loc4`='拉比恩，你要我做什么？', `FemaleText_loc5`='拉比恩，你要我做什麼?', `FemaleText_loc7`='¿Qué quieres que haga, Rabine?' WHERE `ID`=9544;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나와 얘기를 나누면 되오, $n. 그대가 이 일을 맡을 마음이 있다면 세나리온 의회에서는 기꺼이 그대의 친절한 도움을 수락할 것이오. 엘드레탈라스에 있는 악령덩굴의 위협은 참으로 끔찍한 것이니...', `MaleText_loc4`='跟我谈谈，$n——如果你愿意的话，塞纳里奥议会很乐意接受你慷慨的帮助。埃雷萨拉斯的魔藤已经对我们造成了非常大的威胁。', `MaleText_loc5`='跟我談談，$n─如果你願意的話，塞納里奧議會很樂意接受你慷慨的幫助。埃德薩拉斯的水晶相當可怕。', `MaleText_loc7`='Habla conmigo, $n. Si estás $gdispuesto:dispuesta;, el Círculo Cenarion aceptará encantado tu generosa oferta de ayuda. La amenaza que representa la gangrevid para Eldre''Thalas es muy grave.' WHERE `ID`=9545;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<털썩 무릎을 꿇는 데미트리안>$B$B당신이 우리 주인님을 가둔 끝없는 감옥을 찾아내셨습니다!$B$B아! 그토록 오랜 세월을 기다려온 꿈이 드디어 현실로 다가왔군요.$B$B반드시 주인님을 풀어드려야 합니다!', `MaleText_loc4`='<德米提恩跪倒在地。>$B$B你已经找回了主人的牢笼！$B$B我期待这一天已经很久很久了，我的愿望终于实现了。$B$B必须解放我的主人！', `MaleText_loc5`='<德米提恩跪倒在地。>$B$B你已經找回了主人的永久牢籠!$B$B我期待這一天已經很久很久了，我的願望終於實現了。$B$B必須解放我的主人!', `MaleText_loc7`='<Demitrian cae sobre sus rodillas.>$B$B¡Has encontrado la prisión eterna de mi maestro!$B$B¡Oh, cuánto tiempo he esperado a que llegase este día y, al fin, lo ven mis ojos!$B$B¡Tenemos que liberarle!' WHERE `ID`=9546;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 해야 합니까?', `MaleText_loc4`='我要做些什么？', `MaleText_loc5`='我必須做什麼?', `MaleText_loc7`='¿Qué hay que hacer?', `FemaleText_loc1`='어떻게 해야 합니까?', `FemaleText_loc4`='我要做些什么？', `FemaleText_loc5`='我必須做什麼?', `FemaleText_loc7`='¿Qué hay que hacer?' WHERE `ID`=9547;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저에게 그분이 환생할 수 있는 결정이 있습니다. 이 임무를 맡을 각오가 되었다면 결정을 강하게 만드십시오. 궁극적으로 라그나로스의 마수로부터 벗어나야 합니다!', `MaleText_loc4`='我这里有他的重生之瓶。如果你决心接受这项任务，就必须保护好这只小瓶，并击败拉格纳罗斯！', `MaleText_loc5`='我有他的重生之瓶。一旦你準備接受這項任務，你必須保護好這個小瓶，要擺脫拉格納羅斯的控制!', `MaleText_loc7`='Poseo la vasija de su renacimiento. Si estás $gpreparado:preparada; para llevar a cabo esta misión, necesitarás fortificar la vasija y, por último, ¡vencer al mismísimo Ragnaros!' WHERE `ID`=9548;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불의 군주는 물론 누구든지 제 앞을 가로막는 자들은 분노의 응징을 면하지 못할 것입니다.', `MaleText_loc4`='炎魔之王和所有胆敢挡住我去路的家伙，都将尝到我的愤怒。', `MaleText_loc5`='炎魔和所有膽敢擋住我的去路的傢伙，都將嘗到我的憤怒。', `MaleText_loc7`='El Señor del Fuego y todos aquellos que osen interponerse en mi camino, sentirán mi ira.', `FemaleText_loc1`='불의 군주는 물론 누구든지 제 앞을 가로막는 자들은 분노의 응징을 면하지 못할 것입니다.', `FemaleText_loc4`='炎魔之王和所有胆敢挡住我去路的家伙，都将尝到我的愤怒。', `FemaleText_loc5`='炎魔和所有膽敢擋住我的去路的傢伙，都將嘗到我的憤怒。', `FemaleText_loc7`='El Señor del Fuego y todos aquellos que osen interponerse en mi camino, sentirán mi ira.' WHERE `ID`=9549;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='환생의 관은 반드시 엘레멘티움으로 강화해야 합니다. 그런데 그 광석이 나는 곳은 바로 우리 세계의 중심부에 있는 정령계, 한 군데뿐이지요.$B$B그토록 귀한 물건을 구하는 일이라면 저보다 대지창조자가 더 잘 알 테니 꼭 대지창조자를 찾으십시오!', `MaleText_loc4`='必须使用源质对重生之瓶进行加固。我只知道这种矿物的一种原料：位于这个世界核心中的元素领域。$B$B塑地者对这种东西的了解比我多得多。你必须找到塑地者！', `MaleText_loc5`='必須用源質來對重生之瓶進行固化。我只知道這種礦物的一種原料:位於世界核心的元素神域。$B$B塑地者對這種東西的瞭解比我多得多。你必須找到塑地者!', `MaleText_loc7`='Es necesario fortificar la vasija de renacimiento con elementium. Solo conozco un lugar donde encontrar este mineral. El plano elemental, en el centro del mundo.$B$BHay alguien, un modelador de tierra, que quizás sepa más que yo sobre cómo adquirir el elementium. ¡Debes encontrar al modelador de tierra!' WHERE `ID`=9550;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영웅이시어, 안녕하십니까! 양쪽의 대륙은 물론 다른 지역에서 온 최근 소식이 있는데 아마 관심이 있을 겁니다.', `MaleText_loc4`='向你致敬，英雄！我有来自大陆和岛屿的最新消息，供你参考。', `MaleText_loc5`='向你致敬，英雄!我有來自大陸和島嶼的最新消息，供你參考。', `MaleText_loc7`='¡Saludos, $ghéroe:heroína;! Tengo las últimas noticias de ambos continentes y de lugares que ni siquiera conoces.', `FemaleText_loc1`='영웅이시어, 안녕하십니까! 양쪽의 대륙은 물론 다른 지역에서 온 최근 소식이 있는데 아마 관심이 있을 겁니다.', `FemaleText_loc4`='向你致敬，英雄！我有来自大陆和岛屿的最新消息，供你参考。', `FemaleText_loc5`='向你致敬，英雄!我有來自大陸和島嶼的最新消息，供你參考。', `FemaleText_loc7`='¡Saludos, $ghéroe:heroína;! Tengo las últimas noticias de ambos continentes y de lugares que ni siquiera conoces.' WHERE `ID`=9551;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='온 세상을 샅샅이 뒤져서라도 그 대지창조자를 찾아내겠습니다. 그런데 정수는 어떻게 하지요?', `MaleText_loc4`='我得去找找那个什么塑地者。是什么精华？', `MaleText_loc5`='我得去找找那個什麼塑地者。是什麼精華?', `MaleText_loc7`='Peinaré el mundo en busca de ese modelador de tierra. ¿Qué pasa con la esencia?', `FemaleText_loc1`='온 세상을 샅샅이 뒤져서라도 그 대지창조자를 찾아내겠습니다. 그런데 정수는 어떻게 하지요?', `FemaleText_loc4`='我得去找找那个什么塑地者。是什么精华？', `FemaleText_loc5`='我得去找找那個什麼塑地者。是什麼精華?', `FemaleText_loc7`='Peinaré el mundo en busca de ese modelador de tierra. ¿Qué pasa con la esencia?' WHERE `ID`=9552;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라그나로스의 육신을 파괴하십시오. 그의 시체에서 정수가 나타날 것입니다. 그렇게 라그나로스가 약해지면 썬더란을 감옥에 가둬 놓는 힘도 느슨해 지겠지요. 정수가 바로 열쇠 역할을 하는 것입니다.', `MaleText_loc4`='你必须摧毁拉格纳罗斯的肉身，他的精华将在尸体的残骸中出现。在他极度虚弱的时候，他对桑德兰的控制将被大大减弱。精华本身就是一把钥匙……', `MaleText_loc5`='必須摧毀拉格納羅斯的肉身。在屍體殘骸中將出現他的精華。在這個虛弱時期，被關押在桑德蘭監獄中的拉格納羅斯的護手將被釋放。精華本身就是鑰匙...', `MaleText_loc7`='Es imprescindible destruir la forma corpórea de Ragnaros. De sus restos, surgirá su esencia. En su estado, débil, se perderá el control que Ragnaros tiene sobre la prisión de Thunderaan. La esencia es la llave...' WHERE `ID`=9553;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대영주님, 결정을 제게 주십시오.', `MaleText_loc4`='大人，请把复生之瓶给我。', `MaleText_loc5`='大領主，請把容器給我。', `MaleText_loc7`='Dame la vasija, Alto Señor.', `FemaleText_loc1`='대영주님, 결정을 제게 주십시오.', `FemaleText_loc4`='大人，请把复生之瓶给我。', `FemaleText_loc5`='大領主，請把容器給我。', `FemaleText_loc7`='Dame la vasija, Alto Señor.' WHERE `ID`=9554;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금보다 실력을 더 키우려면 먼지진흙 습지대에 있는 내트 페이글을 찾아가는 것이 좋을 것일세.', `MaleText_loc4`='你需要去尘泥沼泽找纳特·帕格接受训练，提高自己的能力。', `MaleText_loc5`='你需要去塵泥沼澤找納特·帕格接受訓練，提高自己的能力。', `MaleText_loc7`='Tendrás que encontrar a Nat Pagle en el Marjal Revolcafango para mejorar tus habilidades.', `FemaleText_loc1`='지금보다 실력을 더 키우려면 먼지진흙 습지대에 있는 내트 페이글을 찾아가는 것이 좋을 것일세.', `FemaleText_loc4`='你需要去尘泥沼泽找纳特·帕格接受训练，提高自己的能力。', `FemaleText_loc5`='你需要去塵泥沼澤找納特·帕格接受訓練，提高自己的能力。', `FemaleText_loc7`='Tendrás que encontrar a Nat Pagle en el Marjal Revolcafango para mejorar tus habilidades.' WHERE `ID`=9555;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금보다 실력을 더 키우려면 먼지진흙 습지대에 있는 내트 페이글을 찾아가는 것이 좋을 겁니다.', `MaleText_loc4`='你需要去尘泥沼泽找纳特·帕格接受训练，提高自己的能力。', `MaleText_loc5`='你需要去塵泥沼澤找納特·帕格接受訓練，提高自己的能力。', `MaleText_loc7`='Tendrás que encontrar a Nat Pagle en el Marjal Revolcafango para mejorar tus habilidades.', `FemaleText_loc1`='지금보다 실력을 더 키우려면 먼지진흙 습지대에 있는 내트 페이글을 찾아가는 것이 좋을 겁니다.', `FemaleText_loc4`='你需要去尘泥沼泽找纳特·帕格接受训练，提高自己的能力。', `FemaleText_loc5`='你需要去塵泥沼澤找納特·帕格接受訓練，提高自己的能力。', `FemaleText_loc7`='Tendrás que encontrar a Nat Pagle en el Marjal Revolcafango para mejorar tus habilidades.' WHERE `ID`=9556;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 낚시 기술을 가르쳐 드릴 수 있습니다.', `MaleText_loc4`='我可以教你一些钓鱼技能。', `MaleText_loc5`='我可以教你一些釣魚技能。', `MaleText_loc7`='Puedo enseñarte a pescar.', `FemaleText_loc1`='제가 낚시 기술을 가르쳐 드릴 수 있습니다.', `FemaleText_loc4`='我可以教你一些钓鱼技能。', `FemaleText_loc5`='我可以教你一些釣魚技能。', `FemaleText_loc7`='Puedo enseñarte a pescar.' WHERE `ID`=9557;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도전에 실패했습니다!', `MaleText_loc4`='你的挑战失败了！', `MaleText_loc5`='你的挑戰失敗了!', `MaleText_loc7`='¡Tu desafío ha fallado!' WHERE `ID`=9558;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자물쇠 따기 기술을 좀 더 갈고 닦으려면 어디로 가야 합니까?', `MaleText_loc4`='我该去哪儿提高自己的开锁技能？', `MaleText_loc5`='我該去哪兒提高自己的開鎖技能?', `MaleText_loc7`='¿Dónde puedo ir para mejorar mi habilidad de forzar cerraduras?', `FemaleText_loc1`='자물쇠 따기 기술을 좀 더 갈고 닦으려면 어디로 가야 합니까?', `FemaleText_loc4`='我该去哪儿提高自己的开锁技能？', `FemaleText_loc5`='我該去哪兒提高自己的開鎖技能?', `FemaleText_loc7`='¿Dónde puedo ir para mejorar mi habilidad de forzar cerraduras?' WHERE `ID`=9559;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저습지에 있는 메네실 항구 북쪽의 푸른아가미 습지대로 가보게. 난파된 배에서 뭍으로 떠내려온 금고들이 잔뜩 있을 걸세. 물이 빠지고 나니 드러났지 뭔가.', `MaleText_loc4`='海浪将船只残骸中的许多上锁的箱子冲到了位于湿地米奈希尔海湾以北的蓝腮沼泽中。', `MaleText_loc5`='海浪將船隻殘骸中的許多上鎖的箱子沖到了位於濕地米奈希爾港以北的藍鰓沼澤中。', `MaleText_loc7`='En el Pantano Branquiazul, al norte del Puerto de Menethil, en Los Humedales, hay muchas cajas fuertes debido a los restos de los naufragios que las olas han llevado a tierra firme.', `FemaleText_loc1`='저습지에 있는 메네실 항구 북쪽의 푸른아가미 습지대로 가보게. 난파된 배에서 뭍으로 떠내려온 금고들이 잔뜩 있을 걸세. 물이 빠지고 나니 드러났지 뭔가.', `FemaleText_loc4`='海浪将船只残骸中的许多上锁的箱子冲到了位于湿地米奈希尔海湾以北的蓝腮沼泽中。', `FemaleText_loc5`='海浪將船隻殘骸中的許多上鎖的箱子沖到了位於濕地米奈希爾港以北的藍鰓沼澤中。', `FemaleText_loc7`='En el Pantano Branquiazul, al norte del Puerto de Menethil, en Los Humedales, hay muchas cajas fuertes debido a los restos de los naufragios que las olas han llevado a tierra firme.' WHERE `ID`=9560;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잊혀진 땅의 북쪽 살데리스 해안 수역이나 황야의 땅에 있는 고통의 요새로 가면 자물쇠 따는 연습을 할만한 잠겨진 금고들이 있을 겁니다.', `MaleText_loc4`='凄凉之地北部萨瑟里斯海岸和荒芜之地苦痛堡垒都有可以拾取的带锁的箱子。', `MaleText_loc5`='淒涼之地北部薩瑟里斯海岸和荒蕪之地苦痛堡壘都有可以拾取的帶鎖的箱子。', `MaleText_loc7`='En las aguas del norte de la Playa de Sar''theris, en Desolace, o en la Fortaleza de Angor, en las Tierras Inhóspitas, puedes encontrar cajas fuertes.', `FemaleText_loc1`='잊혀진 땅의 북쪽 살데리스 해안 수역이나 황야의 땅에 있는 고통의 요새로 가면 자물쇠 따는 연습을 할만한 잠겨진 금고들이 있을 겁니다.', `FemaleText_loc4`='凄凉之地北部萨瑟里斯海岸和荒芜之地苦痛堡垒都有可以拾取的带锁的箱子。', `FemaleText_loc5`='淒涼之地北部薩瑟里斯海岸和荒蕪之地苦痛堡壘都有可以拾取的帶鎖的箱子。', `FemaleText_loc7`='En las aguas del norte de la Playa de Sar''theris, en Desolace, o en la Fortaleza de Angor, en las Tierras Inhóspitas, puedes encontrar cajas fuertes.' WHERE `ID`=9561;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='슬픔의 늪에 있는 눈물의 연못에 가면 오랜 세월 방치되어 있던 고대의 금고들을 찾을 수 있을 겁니다.', `MaleText_loc4`='悲伤沼泽泪水之池有许多带锁的上个世纪丢失的盒子。', `MaleText_loc5`='悲傷沼澤淚水之池有許多帶鎖的上個世紀丟失的盒子。', `MaleText_loc7`='En la Charca de Lágrimas, en el Pantano de las Penas, hay cajas fuertes muy antiguas que se perdieron hace mucho tiempo.', `FemaleText_loc1`='슬픔의 늪에 있는 눈물의 연못에 가면 오랜 세월 방치되어 있던 고대의 금고들을 찾을 수 있을 겁니다.', `FemaleText_loc4`='悲伤沼泽泪水之池有许多带锁的上个世纪丢失的盒子。', `FemaleText_loc5`='悲傷沼澤淚水之池有許多帶鎖的上個世紀丟失的盒子。', `FemaleText_loc7`='En la Charca de Lágrimas, en el Pantano de las Penas, hay cajas fuertes muy antiguas que se perdieron hace mucho tiempo.' WHERE `ID`=9562;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이글거리는 협곡의 잿가루 채석장에 있는 검은무쇠 드워프들이 잠겨진 금고를 잔뜩 갖고 있습니다.', `MaleText_loc4`='灼热峡谷熔渣之池的黑铁矮人有许多带锁的箱子。', `MaleText_loc5`='灼熱峽谷熔渣之池的黑鐵矮人有許多帶鎖的箱子。', `MaleText_loc7`='Los enanos Hierro Negro de La Fosa de la Escoria en La Garganta de Fuego, tienen muchas cajas fuertes.', `FemaleText_loc1`='이글거리는 협곡의 잿가루 채석장에 있는 검은무쇠 드워프들이 잠겨진 금고를 잔뜩 갖고 있습니다.', `FemaleText_loc4`='灼热峡谷熔渣之池的黑铁矮人有许多带锁的箱子。', `FemaleText_loc5`='灼熱峽谷熔渣之池的黑鐵矮人有許多帶鎖的箱子。', `FemaleText_loc7`='Los enanos Hierro Negro de La Fosa de la Escoria en La Garganta de Fuego, tienen muchas cajas fuertes.' WHERE `ID`=9563;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타나리스의 해적단 소굴과 아즈샤라에 있는 폭풍의 만에 자물쇠 따기 연습을 하기에 좋은 금고들이 있습니다.', `MaleText_loc4`='塔纳利斯的落帆海湾和艾萨拉的风暴海湾都有许多上锁的箱子，打开之后即可提高你的技能。', `MaleText_loc5`='塔納利斯的落帆海灣和艾薩拉的風暴海灣都有許多上鎖的箱子，打開之後即可提高你的技能。', `MaleText_loc7`='En la Cala del Aparejo Perdido, en Tanaris y en la Bahía de la Tempestad, en Azshara, hay cajas que puedes coger para mejorar tu habilidad.', `FemaleText_loc1`='타나리스의 해적단 소굴과 아즈샤라에 있는 폭풍의 만에 자물쇠 따기 연습을 하기에 좋은 금고들이 있습니다.', `FemaleText_loc4`='塔纳利斯的落帆海湾和艾萨拉的风暴海湾都有许多上锁的箱子，打开之后即可提高你的技能。', `FemaleText_loc5`='塔納利斯的落帆海灣和艾薩拉的風暴海灣都有許多上鎖的箱子，打開之後即可提高你的技能。', `FemaleText_loc7`='En la Cala del Aparejo Perdido, en Tanaris y en la Bahía de la Tempestad, en Azshara, hay cajas que puedes coger para mejorar tu habilidad.' WHERE `ID`=9564;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동부 역병지대에 있는 티르의 손 수도원에 가면 자물쇠 따는 연습을 하기에 좋은 금고들이 많이 있을 겁니다.', `MaleText_loc4`='东瘟疫之地蒂尔引领的血色十字军有许多带锁的箱子，这对你的技能可是个挑战。', `MaleText_loc5`='東瘟疫之地蒂爾引領的血色十字軍有許多帶鎖的帶鎖箱，這對你的技能可是個挑戰。', `MaleText_loc7`='La Cruzada Escarlata de la Mano de Tyr, en las Tierras de la Peste del Este, tiene muchas cajas fuertes que pondrán a prueba tu habilidad.', `FemaleText_loc1`='동부 역병지대에 있는 티르의 손 수도원에 가면 자물쇠 따는 연습을 하기에 좋은 금고들이 많이 있을 겁니다.', `FemaleText_loc4`='东瘟疫之地蒂尔引领的血色十字军有许多带锁的箱子，这对你的技能可是个挑战。', `FemaleText_loc5`='東瘟疫之地蒂爾引領的血色十字軍有許多帶鎖的帶鎖箱，這對你的技能可是個挑戰。', `FemaleText_loc7`='La Cruzada Escarlata de la Mano de Tyr, en las Tierras de la Peste del Este, tiene muchas cajas fuertes que pondrán a prueba tu habilidad.' WHERE `ID`=9565;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='붉은마루 산맥에 있는 영원고요 호수로 가보시오. 오크들의 보급품이 든 금고가 여러 개 가라앉아 있소.', `MaleText_loc4`='兽人将许多带锁的物资箱沉入了赤脊山的止水湖。', `MaleText_loc5`='獸人將許多帶鎖的物資箱沉入了赤脊山的止水湖。', `MaleText_loc7`='Los orcos hundieron muchas cajas de suministros en el Lago Sempiterno, en Crestagrana.', `FemaleText_loc1`='붉은마루 산맥에 있는 영원고요 호수로 가보시오. 오크들의 보급품이 든 금고가 여러 개 가라앉아 있소.', `FemaleText_loc4`='兽人将许多带锁的物资箱沉入了赤脊山的止水湖。', `FemaleText_loc5`='獸人將許多帶鎖的物資箱沉入了赤脊山的止水湖。', `FemaleText_loc7`='Los orcos hundieron muchas cajas de suministros en el Lago Sempiterno, en Crestagrana.' WHERE `ID`=9566;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나가들이 잿빛 골짜기에 있는 조람 해안을 점령했을 때 보급품을 담은 많은 금고들이 분실되었습니다.', `MaleText_loc4`='在纳迦侵袭灰谷佐拉姆海岸时，许多带锁的物资箱都丢失啦。', `MaleText_loc5`='在納迦侵襲梣谷佐拉姆海岸時，許多帶鎖的物資箱都丟失啦。', `MaleText_loc7`='Cuando los nagas asolaron La Ensenada de Zoram en Vallefresno, se perdieron muchas cajas de suministros.', `FemaleText_loc1`='나가들이 잿빛 골짜기에 있는 조람 해안을 점령했을 때 보급품을 담은 많은 금고들이 분실되었습니다.', `FemaleText_loc4`='在纳迦侵袭灰谷佐拉姆海岸时，许多带锁的物资箱都丢失啦。', `FemaleText_loc5`='在納迦侵襲梣谷佐拉姆海岸時，許多帶鎖的物資箱都丟失啦。', `FemaleText_loc7`='Cuando los nagas asolaron La Ensenada de Zoram en Vallefresno, se perdieron muchas cajas de suministros.' WHERE `ID`=9567;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='투자개발회사는 돌발톱 요새에 있는 칼바람 바위산에 자신들의 물품을 금고에 넣어 보관하고 있으니 그리로 가 보시오.', `MaleText_loc4`='以石爪山脉狂风峭壁为基地的风险投资公司将他们的物资存储在带锁的箱子里。', `MaleText_loc5`='以石爪山脈狂風峭壁為基地的風險投資公司將他們的物資存儲在帶鎖的箱子裡。', `MaleText_loc7`='Ventura y Cía., cerca del Risco Cortaviento, en Sierra Espolón, guarda sus suministros en cajas fuertes.', `FemaleText_loc1`='투자개발회사는 돌발톱 요새에 있는 칼바람 바위산에 자신들의 물품을 금고에 넣어 보관하고 있으니 그리로 가 보시오.', `FemaleText_loc4`='以石爪山脉狂风峭壁为基地的风险投资公司将他们的物资存储在带锁的箱子里。', `FemaleText_loc5`='以石爪山脈狂風峭壁為基地的風險投資公司將他們的物資存儲在帶鎖的箱子裡。', `FemaleText_loc7`='Ventura y Cía., cerca del Risco Cortaviento, en Sierra Espolón, guarda sus suministros en cajas fuertes.' WHERE `ID`=9568;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언덕마루의 던홀드 요새에 비밀결사대의 보급품을 넣은 금고가 많이 있소이다.', `MaleText_loc4`='辛迪加工会在希尔斯布莱德的敦霍尔德城堡有许多带锁的箱子。', `MaleText_loc5`='辛迪加工會在希爾斯布萊德的敦霍爾德城堡有許多帶鎖的箱子。', `MaleText_loc7`='La Hermandad tiene muchas cajas fuertes de suministros en el Castillo de Durnholde, en Trabalomas.', `FemaleText_loc1`='언덕마루의 던홀드 요새에 비밀결사대의 보급품을 넣은 금고가 많이 있소이다.', `FemaleText_loc4`='辛迪加工会在希尔斯布莱德的敦霍尔德城堡有许多带锁的箱子。', `FemaleText_loc5`='辛迪加工會在希爾斯布萊德的敦霍爾德城堡有許多帶鎖的箱子。', `FemaleText_loc7`='La Hermandad tiene muchas cajas fuertes de suministros en el Castillo de Durnholde, en Trabalomas.' WHERE `ID`=9569;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수고했다, 나의 종이여... 너무나도 오랜 세월 동안 불의 군주에게 갇혀있었구나. 이제 자유의 몸이 되었으니 바깥세상을 마음껏 집어삼킬 수 있게 되었다! 이 땅은 다시 한번 바람추적자의 힘에 의해 황폐해질 것이다!', `MaleText_loc4`='干得好，我的仆人。我被关押在炎魔之王的监狱里已经很久了，现在我终于又自由了！让这个世界再次感受逐风者的强大力量吧！', `MaleText_loc5`='幹得好。我被關押在炎魔的監獄裡已經夠久啦。我又自由啦!讓世界再次被逐風者的強大力量摧毀吧!', `MaleText_loc7`='Bien hecho, $gsiervo:sierva;. He estado cautivo en la prisión del Señor del Fuego durante demasiado tiempo. ¡Y ahora, soy libre de nuevo para comerme el mundo exterior! ¡Una vez más, la fuerza del Hijo del Viento asolará la tierra!' WHERE `ID`=9570;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 먼저 나를 풀어준 바보 녀석부터 삼켜 이 크나큰 굶주림을 달래야겠노라.', `MaleText_loc4`='啊，就让那个放我出来的蠢货首先成为我的祭品吧。', `MaleText_loc5`='啊，就讓那個放我出來的傻子首先滿足我腹中的饑渴吧。', `MaleText_loc7`='¡Ah, $gel insensato:la insensata; que me liberó estará entre los primeros que sacien mi inmensa hambre!' WHERE `ID`=9571;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나의 엄청난 위력에 정신을 차릴 수 없을 것이다! 하찮은 미물 주제에 감히 내 영역을 침범하려 하다니 정말 가소롭구나!', `MaleText_loc4`='我拥有无穷的力量！这些愚蠢的凡人居然企图进入我的领域！', `MaleText_loc5`='我擁有不可思議的破壞性力量!那些愚蠢的人類居然企圖進入我的領域!', `MaleText_loc7`='¡Mi poder es descombobuladoramente devastador! Es absurdo que esos mortales intentasen siquiera infiltrarse en mi reino.' WHERE `ID`=9572;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<소리 내어 껄껄 웃는 데미트리안>$B$B이 바보 녀석!너에게 내릴 보상은 빠르고도 고통스러운 죽음뿐이다!', `MaleText_loc4`='<德米提恩笑了。>$B$B愚蠢的家伙，你的奖励就是痛苦地死去！', `MaleText_loc5`='<德米提恩笑道。>$B$B愚蠢的傢伙，你的獎勵就是痛苦地死去吧!', `MaleText_loc7`='<Demitrian ríe.>$B$B¡Tu recompensa es una muerte rápida y dolorosa, imprudente!' WHERE `ID`=9573;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비겁한 녀석아, 어디 한번 네 겁쟁이 주인을 불러내 봐라! 내가 직접 상대해주마!', `MaleText_loc4`='蠢货，让你那胆怯的主人出来！让他面对我！', `MaleText_loc5`='傻子，讓你那膽怯的主人到前面來!讓他面對我!', `MaleText_loc7`='¡Invoca a tu cobarde maestro, idiota! ¡Que se enfrente a mí!', `FemaleText_loc1`='비겁한 녀석아, 어디 한번 네 겁쟁이 주인을 불러내 봐라! 내가 직접 상대해주마!', `FemaleText_loc4`='蠢货，让你那胆怯的主人出来！让他面对我！', `FemaleText_loc5`='傻子，讓你那膽怯的主人到前面來!讓他面對我!', `FemaleText_loc7`='¡Invoca a tu cobarde maestro, idiota! ¡Que se enfrente a mí!' WHERE `ID`=9574;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 이 세계에 이미 알려진 원소들은 물론 미지의 원소들도 연구합니다.', `MaleText_loc4`='我研究这个世界上的已知和未知的元素。', `MaleText_loc5`='我研究世界已知和未知的元素。', `MaleText_loc7`='Yo estudio los elementos conocidos y desconocidos de nuestro mundo.' WHERE `ID`=9575;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 엘레멘티움을 만들 수 있는 대지창조자입니까?', `MaleText_loc4`='你是能制造出源质的塑地者吗？', `MaleText_loc5`='你是能製造出源質的塑地者嗎?', `MaleText_loc7`='¿Eres el modelador de tierra capaz de crear elementium?', `FemaleText_loc1`='당신이 엘레멘티움을 만들 수 있는 대지창조자입니까?', `FemaleText_loc4`='你是能制造出源质的塑地者吗？', `FemaleText_loc5`='你是能製造出源質的塑地者嗎?', `FemaleText_loc7`='¿Eres el modelador de tierra capaz de crear elementium?' WHERE `ID`=9576;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엘레멘티움이라고요? 필멸의 생명체의 입에서 그 이름이 나오는 것도 수십 년 만의 일이로군요.', `MaleText_loc4`='源质？我已经很久没有听过这个词从一个凡人口中冒出来了。', `MaleText_loc5`='源質?我已經很久沒有聽過這個詞從一個凡人口中冒出來了。', `MaleText_loc7`='¿Elementium? Hacía décadas que no escuchaba esa palabra en boca de un mortal.' WHERE `ID`=9577;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='프랑잘, 엘레멘티움에 대해서 알려주십시오.', `MaleText_loc4`='弗兰扎尔，你对此了解多少？', `MaleText_loc5`='弗蘭札爾，你對此瞭解多少?', `MaleText_loc7`='¿Qué sabes sobre eso, Franzahl?', `FemaleText_loc1`='프랑잘, 엘레멘티움에 대해서 알려주십시오.', `FemaleText_loc4`='弗兰扎尔，你对此了解多少？', `FemaleText_loc5`='弗蘭札爾，你對此瞭解多少?', `FemaleText_loc7`='¿Qué sabes sobre eso, Franzahl?' WHERE `ID`=9578;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한때 저의 제자였던 크릭시스라는 고블린은 지하 세계에 구속된 신들과 소통하는 방법을 연구하는데 평생을 바쳤습니다. 황폐해진 대지에서 무언가 솟아오르기를 바란 것이죠... 원소들의 거대한 충돌로만 생성될 수 있는 그 무언가...$B$B필멸의 생명체들에게는 아마 엘레멘티움이라고 알려져 있을 겁니다.$B$B대략 십 년 전 어느 날 크릭시스의 연구가 빛을 발해 이 협곡을 만든 균열이 일어나게 되었습니다.', `MaleText_loc4`='克里希克是我以前的一个学生，他耗费了一生的时间尝试与被封锁在地狱中的神灵进行沟通。他研究那些能够让毫无生机的土地上变为沃土的东西……只有通过元素之间的剧烈碰撞才能创造出来的东西。$B$B凡人把这种东西称为源质。$B$B大约在十年前的某一天，克里希克的研究工作使这片峡谷裂开了。', `MaleText_loc5`='克里希克是我以前的一個學生，他耗費一生的時間嘗試與被封鎖在幽界中的神靈進行溝通。他研究從被摧毀的土地上能生長出什麼來...只有通過泰坦間的碰撞才能創造的元素。$B$B凡人把這種東西稱為源質。$B$B大約在十年前的某一天，克里希克的研究工作使這片峽谷裂開。', `MaleText_loc7`='Un antiguo estudiante mío llamado Krixix, se pasó la vida entera intentando contactar con los dioses encadenados del inframundo. Perseguía aquello que surgió de la tierra devastada... Aquello que aparecía solo como resultado del choque de los elementos en un conflicto titánico.$B$BElementium, tal y como lo conocerían los mortales.$B$BUn día, hace casi una década, el ansia de Krixix tuvo como resultado una fisura que formó esta garganta.' WHERE `ID`=9579;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='균열이라고요?', `MaleText_loc4`='裂缝？', `MaleText_loc5`='裂縫?', `MaleText_loc7`='¿Una fisura?', `FemaleText_loc1`='균열이라고요?', `FemaleText_loc4`='裂缝？', `FemaleText_loc5`='裂縫?', `FemaleText_loc7`='¿Una fisura?' WHERE `ID`=9580;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래요. 불가능한 임무를 해낸 것이죠. 그런데 그 균열에서 테라제인의 대리인이 나오지 않았겠습니까?!$B$B전 높은 곳에서 크릭시스가 고대 신의 종과 대화를 나누는 걸 볼 수 있었는데, 그 후에 아주 끔찍한 일이 일어나고 말았답니다.', `MaleText_loc4`='是的，他完成了几乎不可能完成的任务。塞拉赞恩的使者从裂缝中跳了出来！$B$B在我看来，那个地精已经能够和上古之神的使者交谈了。此后发生的事情非常恐怖……', `MaleText_loc5`='是的，他完成了幾乎不可能完成的任務。從裂縫中出現了瑟拉贊恩的使者!$B$B在我看來，哥布林已經能夠和上古之神的使者進行交談。此後發生的事情非常恐怖...', `MaleText_loc7`='Sí, había conseguido lo que se creía imposible. ¡De la fisura salió un agente de Therazane!$B$BDesde donde yo estaba, pude ver al goblin hablando con el agente del dios antiguo. Lo que ocurrió después, fue terrible...' WHERE `ID`=9581;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일이 있었습니까?', `MaleText_loc4`='发生了什么事？', `MaleText_loc5`='發生了什麼事?', `MaleText_loc7`='¿Y qué ocurrió?', `FemaleText_loc1`='무슨 일이 있었습니까?', `FemaleText_loc4`='发生了什么事？', `FemaleText_loc5`='發生了什麼事?', `FemaleText_loc7`='¿Y qué ocurrió?' WHERE `ID`=9582;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='균열이 닫히면서 크릭시스까지 사라져버린 겁니다! 통째로 빨려들어갔지요!$B$B$r|1이여;여;, 미리 경고하겠습니다. 그대가 찾고 있는 건 그대를 파멸로 이끌 수도 있습니다. 시간 그 자체보다 더 오래된 존재들과 맞서게 될 것이니까요!$B$B크릭시스가 아직 살아있고 그대가 원하는 정보를 갖고 있다 해도 순순히 알려 주지는 않겠지요. 크릭시스는 그대가 상상할 수 있는 그 어떤 공포보다도 훨씬 험한 일들을 겪었을 테니까요.', `MaleText_loc4`='裂缝闭合了，克里希克死了！完全被海水吞没了！$B$B你要小心，$r，你所期望的事情很可能成为你不愿意看到的事情。你所面对的是比事件本身还要古老的生物和魔法！$B$B如果克里希克还活着，如果他知道你要找的讯息，你是不用指望他会告诉你的。他所经历的远远比你想象的要多。', `MaleText_loc5`='裂縫閉合了，克里希克死啦!完全被海水吞沒啦!$B$B要小心，$r，你所期望的事情很可能成為你不願意看到的事情。你與人類和秘法之間的遊戲已經過時啦!$B$B如果克里希克還活著，如果他知道你要找的訊息，你是不用指望他會告訴你的。他所經歷的遠遠比你想像中的要多。', `MaleText_loc7`='¡La fisura se cerró y Krixix desapareció! ¡La fisura se lo tragó!$B$BTen cuidado, $r, lo que deseas, podría convertirse fácilmente en lo que no quieres. ¡Estás jugando con seres y poderes arcanos mucho más viejos que el mismo tiempo!$B$BSi Krixix estuviera vivo, y tuviera la información que buscas, te aseguro que no te lo habría contado. Se ha enfrentado a terrores mucho más oscuros de los que jamás podrías soñar con perpetrar.' WHERE `ID`=9583;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살다 보면 우리가 아는 삶이란 것이 아주 실망스러울 때가 있습니다. 어딘가에 갇혀서 해답을 갈구하다가 어둠 속에서 타오르는 희망을 찾게 되지요.$B$B그때에서야 비로소 자유를 향한 첫 걸음을 떼게 되는 겁니다, $n.', `MaleText_loc4`='我们陷入生存危机。我们陷入困境，寻找答案，希望在黑暗中闪闪发光。$B$B那时，$n，就是我们迈向自由的第一步。', `MaleText_loc5`='我們陷入生存危機。我們陷入困境，尋找答案，希望在黑暗中閃閃發光。$B$B那時，$n，就是我們邁向自由的第一步。', `MaleText_loc7`='Llega un momento cuando la vida que conocemos se nos queda corta. Estamos atrapados y buscamos respuestas. Encontramos la esperanza ardiendo en oscuros lugares.$B$BSolo entonces, $n, damos nuestros primeros pasos hacia la libertad.' WHERE `ID`=9584;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거미나 딱정벌레 좀 있나, $c 친구? 녀석들이 날쌔긴 하지만 몸을 조금만 더 빨리 움직여서 잡아보라고! 아주 별미라는 걸 알게 될 테니까!', `MaleText_loc4`='你有蜘蛛或是甲虫吗，$c？它们速度很快，但是如果你的速度更快的话，你会发现拥有它们是件乐事！', `MaleText_loc5`='你有蜘蛛或是甲蟲嗎，$c?它們速度快，但是如果你的速度更快的話，你會發現擁有它們是件樂事!', `MaleText_loc7`='¿Tienes arañas o alfazaques, $c? Son muy escurridizos, pero si eres más $grápido:rápida;, ¡descubrirás que son todo un manjar!' WHERE `ID`=9585;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고르지키, 물건을 사고 싶습니다.', `MaleText_loc4`='戈瑟奇，我想买点东西。', `MaleText_loc5`='戈瑟奇，我想買點東西。', `MaleText_loc7`='Gorzeeki, me gustaría hacer una compra.', `FemaleText_loc1`='고르지키, 물건을 사고 싶습니다.', `FemaleText_loc4`='戈瑟奇，我想买点东西。', `FemaleText_loc5`='戈瑟奇，我想買點東西。', `FemaleText_loc7`='Gorzeeki, me gustaría hacer una compra.' WHERE `ID`=9586;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혹시 방금 던전에서 나오셨나요? 그럼, 저한테 줄 선물은 뭐 없어요?', `MaleText_loc4`='你刚从地下城出来吗？有什么东西给我的吗？', `MaleText_loc5`='你剛從地城出來嗎?有什麼東西給我的嗎?', `MaleText_loc7`='¿Acabas de salir de una mazmorra? ¿Me has cogido algo?' WHERE `ID`=9587;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이, 무서워! 그 방어구 보니까 정말 겁나요... $g형:누나;, 무서운 분이에요?', `MaleText_loc4`='你的护甲看起来很破旧。你为此感到胆怯吗？', `MaleText_loc5`='你的護甲看起來很破舊。你為此感到膽怯嗎?', `MaleText_loc7`='Tu armadura da miedo. ¿Tú das miedo también?' WHERE `ID`=9588;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 신전에 들어가게 놔둘 수 없다! 차라리 여기서 죽는 걸 감사하게 여길 것이다!', `MaleText_loc4`='我不允许你进入神庙！我会摧毁你的！', `MaleText_loc5`='我不允許你進入神廟!我會摧毀你的!', `MaleText_loc7`='¡No puedo permitirte que entres en el templo! ¡Debo destruirte por tu propio bien!' WHERE `ID`=9589;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나를 부르려면 제물을 바쳐야 하는 법이다, 필멸의 생명체여...', `MaleText_loc4`='一旦我被召唤出来，就会有人牺牲，凡人。', `MaleText_loc5`='一旦我被召喚出來，就會有人犧牲，凡人。', `MaleText_loc7`='Será necesario hacer un sacrificio si alguna vez me invocas, mortal...' WHERE `ID`=9590;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 나락으로 떨어질 때 너희 모두 끌고 가겠다!', `MaleText_loc4`='如果我要落入地狱，那么你们这些凡人也要跟我同去！', `MaleText_loc5`='讓我用誇張的喊叫聲來預示你的死期吧。哦，順便說一句，迎接死亡吧。', `MaleText_loc7`='¡Si yo caigo en el abismo, ustedes mortales vendrán conmigo!' WHERE `ID`=9591;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수정 구슬에서 통제력이 빠져나가자 %s|1이;가; 도망칩니다.', `MaleText_loc4`='在宝珠的控制力消失的瞬间，%s逃走了。', `MaleText_loc5`='%s在寶珠的控制力消失之前逃走。', `MaleText_loc7`='%s huyen mientras se consume el poder del orbe.' WHERE `ID`=9592;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 이 다음에 커서 스톰윈드의 국왕이 될 거예요!', `MaleText_loc4`='我长大后想成为暴风城的王！', `MaleText_loc5`='我長大後想成為暴風之王!', `MaleText_loc7`='¡Cuando sea mayor, quiero ser el rey de Ventormenta!' WHERE `ID`=9593;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전에 아이언포지에 한번 가봤는데요... 퀴퀴하고 이상한 냄새가 났어요.', `MaleText_loc4`='我以前去过铁炉堡。那儿闻起来怪怪的。', `MaleText_loc5`='我曾經去過鐵爐堡。那兒很有趣。', `MaleText_loc7`='Ya he estado en Forjaz. Huele raro.' WHERE `ID`=9594;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='버섯은 다 축축한 곳에서 자라니까 우산처럼 생겼나 봐요.', `MaleText_loc4`='蘑菇总是生长的阴暗的地方，因此它们长得像雨伞。', `MaleText_loc5`='蘑菇總是生長在潮濕的地方，因此它們長得像雨傘。', `MaleText_loc7`='Los champiñones siempre crecen en lugares húmedos, por eso parecen paraguas.' WHERE `ID`=9595;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멜빵 바지는 위에 달린 멜빵으로 바지를 올려 입는 건데 허리띠 넣는 구멍은 왜 있어요?', `MaleText_loc4`='如果罩衫是由顶部的摁扣固定的，那为什么还需要袢带呢？', `MaleText_loc5`='如果罩衫是由頂部的摁扣固定的，那為什麼還需要袢帶呢?', `MaleText_loc7`='Si los petos están sujetos por los tirantes de arriba, ¿por qué tienen hebillas para cinturón?' WHERE `ID`=9596;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='콧구멍 안에서 코딱지가 얼어붙으면 어떻게 돼요?', `MaleText_loc4`='要是你的鼻涕在鼻子里结冰了怎么办？', `MaleText_loc5`='要是你的鼻涕在鼻子裡結冰了怎麼辦?', `MaleText_loc7`='¿Qué pasa si los mocos se te congelan en la nariz?' WHERE `ID`=9597;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물고기도 목말라 해요?', `MaleText_loc4`='鱼不会口渴吗？', `MaleText_loc5`='魚不會口渴嗎?', `MaleText_loc7`='¿Alguna vez tienen sed los peces?' WHERE `ID`=9598;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실패하려고 마음먹은 것에 성공했다면 성공한 건가요, 실패한 건가요?', `MaleText_loc4`='如果你想要失败，但是却成功了，你做了什么？', `MaleText_loc5`='如果你想要失敗，但是卻成功了，你做了什麼?', `MaleText_loc7`='Si intentas fallar y tienes éxito, ¿qué acabas de hacer?' WHERE `ID`=9599;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$g형이:누나가; 진짜 호드의 영웅이라면 용하고 싸우는 걸 얼른 보여줘요!', `MaleText_loc4`='要是你真是部落的英雄，我想看看你屠龙！啊！', `MaleText_loc5`='要是你真是部落的英雄，我想看看你屠龍!啊!', `MaleText_loc7`='¡Si eres un verdadero héroe de la Horda, quiero ver cómo luchas contra un dragón! ¡Sí!' WHERE `ID`=9600;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바다에 벼락이 떨어지면 어째서 물고기들이 다 죽지 않죠?', `MaleText_loc4`='当闪电击中海洋的时候，为什么所有的鱼都没有死？', `MaleText_loc5`='當閃電擊中海洋的時候，為什麼所有的魚都沒有死?', `MaleText_loc7`='Cuando un rayo cae sobre el océano, ¿por qué no mueren los peces?' WHERE `ID`=9601;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날개 없는 파리들을 벼룩이라고 부르나요?', `MaleText_loc4`='没有翅膀的鸟可以被称为步行生物吗？', `MaleText_loc5`='沒有翅膀的鳥可以被稱為步行生物嗎?', `MaleText_loc7`='Un insecto volador sin alas, ¿se llamaría un insecto andador?' WHERE `ID`=9602;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코 속에 돌이 낀 것 같아요.', `MaleText_loc4`='我的鼻子里有块石头。', `MaleText_loc5`='我的鼻子裡有塊石頭。', `MaleText_loc7`='Tengo una roca metida en la nariz.' WHERE `ID`=9603;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거북이가 등껍질이 없으면 집을 잃은 건가요, 아니면 옷을 잃은 건가요?', `MaleText_loc4`='要是海龟没有壳的话，那不就成无家可归或是裸体啦？', `MaleText_loc5`='要是海龜沒有殼的話，那不就成無家可歸或是裸體啦?', `MaleText_loc7`='Si una tortuga no tiene caparazón, ¿es que no tiene casa o que está desnuda?' WHERE `ID`=9604;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런데 "저그 저그"가 무슨 뜻이에요?', `MaleText_loc4`='“咔咔”是什么意思？', `MaleText_loc5`='「嘖嘖」是什麼意思?', `MaleText_loc7`='¿Qué significa "zug zug"?' WHERE `ID`=9605;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장갑이 너무 커 보여요. 양말로 신지 그래요?', `MaleText_loc4`='要是你的手套太大的话，还算是合手的手套吗？', `MaleText_loc5`='要是你的手套太大的話，還算是合手的手套嗎?', `MaleText_loc7`='Si tu guante es demasiado grande, ¿te sigue quedando como un guante?' WHERE `ID`=9606;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 멀리서 왔군, $r 친구.', `MaleText_loc4`='你离家还远着呢，$r。', `MaleText_loc5`='你離家還遠著呢，$r。', `MaleText_loc7`='Estás muy lejos de casa, $r.' WHERE `ID`=9607;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가르침을 받으러 왔습니다, 다이오.', `MaleText_loc4`='戴奥，我是来学习的。', `MaleText_loc5`='戴奧，我是來學習的。', `MaleText_loc7`='He venido a aprender, Daio.', `FemaleText_loc1`='가르침을 받으러 왔습니다, 다이오.', `FemaleText_loc4`='戴奥，我是来学习的。', `FemaleText_loc5`='戴奧，我是來學習的。', `FemaleText_loc7`='He venido a aprender, Daio.' WHERE `ID`=9608;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 용케도 찾았구려. 내게 억제와 지배에 대해 배우려고 온 거겠지.$B$B그보다 더 많은 기술도 가르쳐주리다... 희생에 대해서도 가르쳐주겠단 말이오.$B$B<씩 웃는 다이오.>', `MaleText_loc4`='你来了。你是来学习镇压和控制之道的吧。$B$B我会教你更多的东西……你将学会牺牲。$B$B<戴奥咧嘴而笑。>', `MaleText_loc5`='你已經找到我啦。你是來學習鎮壓和控制之道的吧。$B$B我會教你更多的東西...你將學到犧牲。$B$B<戴奧咧嘴而笑。>', `MaleText_loc7`='Y me has encontrado. Supongo que has venido a aprender tácticas de fuego de supresión y control.$B$BTe enseñaré mucho más que eso... También vas a aprender lo que significa el sacrificio.$B$B<Daio sonríe.>' WHERE `ID`=9609;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무엇을 희생해야 합니까?', `MaleText_loc4`='我要牺牲什么？', `MaleText_loc5`='我要犧牲什麼?', `MaleText_loc7`='¿Qué tengo que sacrificar?', `FemaleText_loc1`='무엇을 희생해야 합니까?', `FemaleText_loc4`='我要牺牲什么？', `FemaleText_loc5`='我要犧牲什麼?', `FemaleText_loc7`='¿Qué tengo que sacrificar?' WHERE `ID`=9610;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그건 당신이 소환해서 부하로 만들기를 원하는 악마의 종류에 따라 다르다오. 우리는 암흑의 마력을 이용하고 그에 따른 큰 대가를 치러야 하는 것이지.', `MaleText_loc4`='你得选择自己要召唤和驱使的恶魔。我们运用黑暗力量并为此付出巨大的代价。', `MaleText_loc5`='你得選擇自己要召喚和驅使的惡魔。我們運用黑暗力量並為此付出巨大的代價。', `MaleText_loc7`='Eso lo decidirá el demonio a quien quieras invocar y esclavizar. Poseemos poderes oscuros y tenemos que pagar un alto precio por utilizarlos.' WHERE `ID`=9611;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악마는 어떻게 해야 소환할 수 있습니까?', `MaleText_loc4`='要怎么召唤恶魔？', `MaleText_loc5`='要怎麼召喚惡魔?', `MaleText_loc7`='¿Cómo puedo invocar a un demonio?', `FemaleText_loc1`='악마는 어떻게 해야 소환할 수 있습니까?', `FemaleText_loc4`='要怎么召唤恶魔？', `FemaleText_loc5`='要怎麼召喚惡魔?', `FemaleText_loc7`='¿Cómo puedo invocar a un demonio?' WHERE `ID`=9612;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭔가를 해 보려면 먼저 그 악마를 가두어 둘 감옥을 만들어야 하오.', `MaleText_loc4`='要是你还想继续前进的话，我们必须首先找人对付野兽。', `MaleText_loc5`='要是你還想繼續前進的話，我們必須首先找人對付野獸。', `MaleText_loc7`='Si quieres hacerlo, primero tenemos que crear una prisión para recluir a la bestia.' WHERE `ID`=9613;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='통제력을 회복했다! 모두 제 위치로!', `MaleText_loc4`='我已经夺回了控制权！大家都回到自己的岗位上去！', `MaleText_loc5`='我已經奪回了控制權!大家都回到自己的崗位上去!', `MaleText_loc7`='¡He vuelto a tomar el control! ¡Todos a sus puestos!' WHERE `ID`=9614;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 임프시! 느낌이 와! 아주 큰 거야!', `MaleText_loc4`='这就是啦。我能感觉到！这可真是个大家伙！', `MaleText_loc5`='這就是啦。我能感覺到!這可真是個大傢伙!', `MaleText_loc7`='Ya está, Diblis. ¡Puedo sentirlo! ¡Va a ser grande!' WHERE `ID`=9615;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영광으로 알고 받아들여라, 임프시!', `MaleText_loc4`='振作起来，迎接挑战！', `MaleText_loc5`='振作起來，迎接挑戰!', `MaleText_loc7`='Prepárate para el glorioso impacto, Diblis.' WHERE `ID`=9616;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 날 쫓아내겠다고!? 허우대만 멀쩡한 스톰윈드의 골 빈 녀석들에게 이 나이비의 진정한 힘을 보여줘야겠군! 두고 봐!', `MaleText_loc4`='把我踢出去，他们会吗！？我会让暴风城中这些愚蠢的家伙见识见识尼比的力量！等着瞧！', `MaleText_loc5`='把我踢出去，他們會嗎!?我會讓暴風城中這些愚蠢的傢伙見識見識尼比的力量!等著瞧!', `MaleText_loc7`='¿Echarme? ¿¿Pretenden echarme?? ¡Yo les enseñaré a esos bastardos cabezacono de Ventormenta el verdadero poder de Niby! ¡MIRAD!' WHERE `ID`=9617;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='화가 난 %s|1이;가; 주먹을 흔듭니다.', `MaleText_loc4`='%s怀着挫败的心情挥舞着拳头。', `MaleText_loc5`='%s懷著挫敗的心情揮動他的拳頭。', `MaleText_loc7`='%s agita el puño para expresar su frustración.' WHERE `ID`=9618;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나이비, 당신 정말 멍청하군요.', `MaleText_loc4`='尼比，你真蠢。', `MaleText_loc5`='尼比，你真愚蠢。', `MaleText_loc7`='Niby, eres estúpido.' WHERE `ID`=9619;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이고, 이런! 또 실패하셨어요!? 어째서요, 위대하신 주인님?', `MaleText_loc4`='我的天，我太惊讶了！又一次失败啦！？怎么会呢？？', `MaleText_loc5`='我的天，太令人震驚了!又一次的失敗!?怎麼會這樣??', `MaleText_loc7`='¡Pues menuda sorpresa! ¿Otro fracaso? ¿Pero cómo es posible?' WHERE `ID`=9620;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놀라우신 주인님, 그 무능함에 진정으로 놀라움을 금할 수 없네요.', `MaleText_loc4`='主人，你令人感到敬畏。你的不称职令人敬畏。', `MaleText_loc5`='主人，你令人感到敬畏。你的不稱職令人敬畏。', `MaleText_loc7`='Impresionante, maestro. Tu ineptitud es impresionante.' WHERE `ID`=9621;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 조그만 게!', `MaleText_loc4`='为什么你这个小东西这么做！', `MaleText_loc5`='為什麼你這個小東西這麼做!', `MaleText_loc7`='Maldito...' WHERE `ID`=9622;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으악! 살려줘! 미친 노움이 날 죽이려고 해요!', `MaleText_loc4`='啊！帮帮我！那些疯狂的侏儒想要杀了我！', `MaleText_loc5`='啊!幫幫我!那些瘋狂的地精想要殺了我!', `MaleText_loc7`='¡Aaah! ¡Ayuda! ¡Un gnomo loco intenta matarme!' WHERE `ID`=9623;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 내 앞에 엎드려 머리를 조아리지 못할까, 이 벌레 같은 것! 네까짓 것의 힘은 내 손아귀 안에 있다는 걸 모르겠느냐?', `MaleText_loc4`='卑微的家伙，在我面前鞠躬吧！你能感受到我那强大的力量。', `MaleText_loc5`='卑微的傢伙，在我面前鞠躬吧!你能感受到我那強大的力量。', `MaleText_loc7`='¡Inclínate ante mí, insecto! Seguro que puedes sentir el poder que tengo sobre ti.' WHERE `ID`=9624;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위대한 힘을 지닌 흑마법사 한 분을 찾고 있습니다.', `MaleText_loc4`='我在寻找一名强大的术士。', `MaleText_loc5`='我在尋找一名強大的術士。', `MaleText_loc7`='Estoy buscando a un poderoso brujo.', `FemaleText_loc1`='위대한 힘을 지닌 흑마법사 한 분을 찾고 있습니다.', `FemaleText_loc4`='我在寻找一名强大的术士。', `FemaleText_loc5`='我在尋找一名強大的術士。', `FemaleText_loc7`='Estoy buscando a un poderoso brujo.' WHERE `ID`=9625;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 나이비에게서 황천으로부터 지옥불정령을 소환하는 비결을 배우고 싶은 거로군.$B$B아무 말 하지 마! 이 나이비는 모든 걸 알고 있으니까!$B$B하지만, 그런 지식을 쉽게 전수할 만큼 이 나이비가 호락호락하진 않아. 먼저 나를 도와 아주 중요한 임무를 하나 수행하도록!', `MaleText_loc4`='这么说，你是来找尼比学习如何从虚空中召唤地域火仆从的。$B$B安静！尼比什么都知道！$B$B他可不会这么轻易地将知识传授给你。首先，你必须帮助尼比完成一项至关重要的任务。', `MaleText_loc5`='這麼說，你是來找尼比學習如何從虛空中召喚煉獄火僕從的。$B$B肅靜!尼比什麼都知道!$B$B他可不會這麼輕易地將知識傳授給你。首先，你必須幫助尼比完成一項至關重要的任務。', `MaleText_loc7`='Así que has venido a buscar a Niby para aprender a invocar a un infernal del averno.$B$B¡Silencio! ¡Niby lo sabe todo!$B$BPero Niby no le cuenta lo que sabe a cualquiera. Primero, deberás ayudar a Niby con una tarea muy importante.' WHERE `ID`=9626;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 임무 말입니까?', `MaleText_loc4`='什么任务？', `MaleText_loc5`='什麼任務?', `MaleText_loc7`='¿Qué tarea?', `FemaleText_loc1`='어떤 임무 말입니까?', `FemaleText_loc4`='什么任务？', `FemaleText_loc5`='什麼任務?', `FemaleText_loc7`='¿Qué tarea?' WHERE `ID`=9627;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 야영지에서 북동쪽으로 가면 크로쉬우스라는 지옥불정령이 하나 쓰러져 있지. 이 나이비가 여기 온 이유도 바로 그 녀석 때문이야. 크로쉬우스는 상급 지옥불정령으로 예상보다 오래 버텼어. 원래 지옥불정령이란 게 주인을 섬기기 위해 강렬한 힘으로 땅 위에 떨어지지만 그 힘은 아주 빨리 시들거든. 화염이 꺼지면 지옥불정령도 힘을 잃고 재가 되어 부서지는 거야.', `MaleText_loc4`='在这座营地的东北面有一个名叫克罗苏斯的强大的地狱火。这就是尼比待在这儿的原因。克罗苏斯极其强大，前所未闻。你瞧，菜鸟，地狱火以极高的速度坠落在地面上，但是它的生命却很短暂。一旦火焰熄灭，地狱火便崩溃了。', `MaleText_loc5`='在這座營地的東北面有一個名叫克羅蘇斯的強大的煉獄火。這就是尼比在這兒的原因。克羅蘇斯極其強大，前所未聞。小子，看吧，煉獄火以極大的速度墜落地面，但是生命卻很短暫。一旦火焰熄滅，煉獄火便崩潰了。', `MaleText_loc7`='Hay un poderoso infernal llamado Kroshius al noroeste de este campamento. Por eso Niby está aquí. Kroshius es un infernal superior. Un infernal que ha durado más de lo que se esperaba. Verás, los infernales llegan a las profundidades de la tierra con mucha intensidad para servir a su maestro, pero esa intensidad se desvanece rápidamente. Cuando las abrasadoras llamas se mueren, el infernal se viene abajo.' WHERE `ID`=9628;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 흥미로운 이야기이긴 합니다만 당신이 원하는 게 정확히 뭡니까?', `MaleText_loc4`='这很有趣，但是你到底想说什么？', `MaleText_loc5`='這很有趣，但是這是你想要的嗎?', `MaleText_loc7`='Muy interesante, ¿pero qué es lo que quieres?', `FemaleText_loc1`='아주 흥미로운 이야기이긴 합니다만 당신이 원하는 게 정확히 뭡니까?', `FemaleText_loc4`='这很有趣，但是这是你想要的吗？', `FemaleText_loc5`='這很有趣，但是這是你想要的嗎?', `FemaleText_loc7`='Muy interesante, ¿pero qué es lo que quieres?' WHERE `ID`=9629;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어리석은 것! 이 나이비의 말을 함부로 가로막지 마라. 네 살가죽을 벗긴 다음 뼈다귀를 옷걸이로 써버릴 수도 있다. 그런데... 어디까지 말했더라? 아, 그래. 그러니까 이 크로쉬우스란 놈은 평범한 지옥불정령보다 열 배는 더 오래 버텼다는 말이야. 어떻게 그럴 수 있는지는 모르겠지만 자세히 조사하면 분명 알아낼 수 있을 거야.$B$B가서 크로쉬우스의 지옥핵을 가져 오도록.', `MaleText_loc4`='别打断我，你这个蠢货！我会把你身上的肉刮下来，把你的骨头做成衣架。我说到哪儿了？哦，对，克罗苏斯的存活时间是普通地狱火的10倍。我不知道为什么会这样，但是我想只要进行足够的研究，我一定可以查明真相。$B$B你必须帮我找到克罗苏斯的火焰核心。', `MaleText_loc5`='別打斷我，你這個傻子!我會將你身上的肉刮下來，把你的骨骸當作衣架。我在哪兒?哦，是的，克羅蘇斯的存活時間是普通煉獄火的10倍。我不知道為什麼會這樣，但是我想透過足夠的研究，我會查明真相的。$B$B你得幫我找到克羅蘇斯的煉獄火之核。', `MaleText_loc7`='¡No interrumpas a Niby, insensato! Desgarraré la carne de tus huesos y utilizaré los restos de tu esqueleto como perchero. ¿Por dónde iba? Ah, sí, pues eso, Kroshius duró casi diez veces más que cualquier otro infernal. No sé muy bien por qué, pero creo que si lo estudio a fondo, podría descubrirlo.$B$BNecesito que recuperes el núcleo infernal de Kroshius.' WHERE `ID`=9630;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 해야 합니까?', `MaleText_loc4`='我要干些什么呢？', `MaleText_loc5`='我要怎麼才能做到呢?', `MaleText_loc7`='¿Cómo lo hago?', `FemaleText_loc1`='어떻게 해야 합니까?', `FemaleText_loc4`='我要干些什么呢？', `FemaleText_loc5`='我要怎麼才能做到呢?', `FemaleText_loc7`='¿Cómo lo hago?' WHERE `ID`=9631;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지옥불정령 하수인을 소환하는 비결을 알고 싶으면 먼저 크로쉬우스를 처치하고 불타버린 그의 잔해에서 지옥핵을 가져 와야 해. 그게 말처럼 쉬운 일은 아니겠지만... 크로쉬우스는 이미 완전히 타버렸을 테니 그의 잔해에 다시 불을 지펴 잿더미가 된 다시 살려야 하거든. 그렇게 하려면 다른 악마적 존재로부터 어떤 재료를 모아야 해.$B$B저기 있는 내 부하 임프시가 더 자세히 가르쳐줄 거야.', `MaleText_loc4`='要想让我教你召唤地狱火仆从，你必须杀死克罗苏斯，然后从他燃烧的尸体中取出恶魔之核交给我。但是这项任务并不简单，克罗苏斯几乎已经烧尽了。你必须重新点燃他的尸体，令他复活。所以你必须从其它恶魔那儿收集一些东西才能令他复活。$B$B我的孩子，准备上路吧。', `MaleText_loc5`='要想我教你召喚煉獄火僕從，你必須殺死克羅蘇斯並從他燃燒的屍體中取出煉獄火之核交給我。但是這項任務並不簡單。克羅蘇斯幾乎已經燒盡了。你必須重新點燃他的屍體，令他復活。你必須從其他惡魔那兒收集一些東西才能令他復活。$B$B我的孩子，準備上路吧。', `MaleText_loc7`='Si quieres que te enseñe los secretos para invocar a un sirviente infernal, debes destruir a Kroshius y traerme el núcleo infernal que encontrarás entre sus restos quemados. Sin embargo, no es tan fácil como parece. Kroshius se ha quemado completamente. Tienes que prender fuego a su cadáver y hacer que renazca de sus cenizas. Para hacerlo, necesitas encontrar algunos componentes de otras entidades demoníacas.$B$BMi diablillo, Diblis, te ayudará a ponerte en marcha.' WHERE `ID`=9632;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 크로쉬우스가 살아난 건가? 크로쉬우스가 전부 다 없애 주겠다!', `MaleText_loc4`='克罗苏斯活了？克罗苏斯要摧毁一切！', `MaleText_loc5`='克羅蘇斯還活著!克羅蘇斯死啦!', `MaleText_loc7`='¿Kroshius vivo? ¡Kroshius aplastar!' WHERE `ID`=9633;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물러서! 비키라고! 지옥불정령은 공간이 많이 필요할 거야!', `MaleText_loc4`='退后！退后！与地狱火保持安全距离！', `MaleText_loc5`='退後!肅靜!要與煉獄火保持安全距離!', `MaleText_loc7`='¡Atrás! ¡Atrás! Tenemos que dejarle mucho espacio al infernal.' WHERE `ID`=9634;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 전지전능한 나이비께 머리를 조아려 예를 갖추라! 머리를 숙여 나의 지옥불... 닭?', `MaleText_loc4`='向全能的主鞠躬吧！满怀敬畏之情看着我所召唤出来的毁灭一切的地狱……小鸡？', `MaleText_loc5`='向全能的主鞠躬吧!在我的毀滅煉獄火之前鞠躬吧...膽小鬼?', `MaleText_loc7`='¡INCLINAOS ANTE EL TODOPODEROSO! INCLINAOS ANTE MI INFERNAL DESTRUC... ¿Gallina?' WHERE `ID`=9635;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 데굴데굴 구르며 웃습니다.', `MaleText_loc4`='%s笑得在地上打滚。', `MaleText_loc5`='%s笑到在地板上打滾。', `MaleText_loc7`='%s rueda por el suelo riéndose sin parar.' WHERE `ID`=9636;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나이비, 당신 정말 바보로군요.', `MaleText_loc4`='尼比，你是个白痴。', `MaleText_loc5`='尼比，你是個白癡。', `MaleText_loc7`='Niby, eres un idiota.' WHERE `ID`=9637;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='입 다물어라... 하인 주제에 감히! 복수하고 말 테다! 스톰윈드에 죽음을! 닭으로 죽음을!', `MaleText_loc4`='肃静，仆人们！复仇吧！摧毁暴风城！让他们全军覆灭！', `MaleText_loc5`='肅靜，僕人們!復仇吧!摧毀暴風城!讓他們全軍覆滅!', `MaleText_loc7`='¡Silencio, siervo! ¡La venganza será mía! ¡Muerte a Ventormenta! ¡Muerte por sobredosis de gallina!' WHERE `ID`=9638;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='설퍼론 주괴라고? 그럴 리가! 그건 내가 가져야 해! 내가 가져야 한다고! 내가!$B$B나는 그 주괴로 굉장한 거래를 할 수 있는 허가를 받았네. 라그나로스의 손에 관한 비밀을 알고 싶지 않나? 설퍼라스 말이야. 참 답답한 친구로군! 불의 군주의 전설적인 망치 말일세.', `MaleText_loc4`='萨弗隆铁锭？！？？！不可能！我必须得到它！必须！必须！$B$B$R，我会花大价钱购买铁锭的。或许你会对炎魔拉格纳罗斯之手之谜感兴趣？就是萨弗拉斯，白痴！传说中火元素之王使用的铁锤。', `MaleText_loc5`='薩弗隆鐵錠?!??!不可能!我必須得到它!必須!必須!$B$B$R，我會花大價錢購買鐵錠的。或許你會對炎魔拉格納羅斯之手之謎感興趣?就是薩弗拉斯，白癡!傳說中炎魔使用的鐵錘。', `MaleText_loc7`='¡¿Un lingote de Sulfuron?! ¡Imposible! ¡Lo quiero! ¡Lo quiero! ¡Lo necesito!$B$B$R, estoy autorizado a proponerte un trato muy beneficioso para ti a cambio de ese lingote. ¿Quizás te interesaría saber los secretos de la Mano de Ragnaros? ¡Sulfuras, idiota! El legendario martillo del Señor del Fuego.' WHERE `ID`=9639;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠, 계속 해 보십시오. 제안하는 게 뭡니까?', `MaleText_loc4`='嗯，我在听。你出多少价钱？', `MaleText_loc5`='嗯，我在聽。你出多少價錢?', `MaleText_loc7`='Mmm, te escucho. ¿De qué oferta estamos hablando?', `FemaleText_loc1`='흠, 계속 해 보십시오. 제안하는 게 뭡니까?', `FemaleText_loc4`='嗯，我在听。你出多少价钱？', `FemaleText_loc5`='嗯，我在聽。你出多少價錢?', `FemaleText_loc7`='Mmm, te escucho. ¿De qué oferta estamos hablando?' WHERE `ID`=9640;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 설퍼론 주괴 하나에 설퍼론 망치 제작 도면 하나를 주도록 허가를 받았네.$B$B자네 같은 모험가라면 아마도 이렇게 생각하겠지. "내가 가지고 있는 게 훨씬 우수한데 그런 망치와 왜 바꾸겠어?"라고 말이지.$B$B한 가지만 말하지. 설퍼론 망치가 지닌 잠재력보다 더 뛰어난 건 없다네!', `MaleText_loc4`='我愿意用萨弗隆战锤的设计图换取一块萨弗隆铁锭。$B$B现在，你大概正在暗自盘算吧，“我要那种战锤来做什么，我现有的装备比这东西高级多了！”$B$B嗯，让我告诉你吧，$g先生:女士;，没有什么武器比萨弗隆战锤更高级了！', `MaleText_loc5`='我願意用薩弗隆戰錘的設計圖換取一塊薩弗隆鐵錠。$B$B現在，你大概正在暗自盤算吧，「我要那種戰錘來做什麼，我現有的裝備比這東西高級多了!」$B$B嗯，讓我告訴你吧，$g先生:女士;，沒有什麼武器比薩弗隆戰錘更高級了!', `MaleText_loc7`='A cambio de un lingote de Sulfuron, estoy autorizado a darte una copia de los planos para forjar un martillo de Sulfuron.$B$BSí, seguro que $gun aventurero:una aventurera; como tú está pensando: "¿Para qué iba a querer un martillo cuando lo que tengo es mucho más superior?"$B$BBueno, deja que te diga algo, $gcaballerete:señorita;, no hay nada más superior que en lo que se puede convertir el martillo de Sulfuron.' WHERE `ID`=9641;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='귀가 솔깃한데요. 더 말해 주십시오.', `MaleText_loc4`='你吸引了我的注意。', `MaleText_loc5`='你吸引了我的注意。', `MaleText_loc7`='Tienes toda mi atención.', `FemaleText_loc1`='귀가 솔깃한데요. 더 말해 주십시오.', `FemaleText_loc4`='你吸引了我的注意。', `FemaleText_loc5`='你吸引了我的注意。', `FemaleText_loc7`='Tienes toda mi atención.' WHERE `ID`=9642;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러니까 설퍼론 망치를 제작하고 설퍼라스의 눈을 찾기만 하면 되는 것이야. 설퍼라스의 눈과 설퍼론 망치를 합치면 설퍼라스가 되는 것이지! 언제 어디서 어떻게 설퍼라스의 눈을 구할 수 있는가 하는 따위의 기술적 정보는 얘기하지 않겠네. 그런 건 자네 스스로 생각해낼 수 있을 거라 믿네. 그저 이 계약서에 서명을 하기만 하면 정식으로 합의하는 것이고 거래는 완료되는 것일세.', `MaleText_loc4`='你所要做的就是铸造萨弗隆战锤和找到萨弗拉斯之眼。将萨弗拉斯之眼和萨弗隆战锤结合在一起就能成为萨弗拉斯！我不会告诉你任何关于萨弗拉斯之眼的信息。我想你自己能找到的。在这张合约上签字，让我们达成交易。', `MaleText_loc5`='你所要做的就是鑄造薩弗隆戰錘和找到薩弗拉斯之眼。將薩弗拉斯之眼和薩弗隆戰錘結合在一起就能成為薩弗拉斯!我不會告訴你任何關於薩弗拉斯之眼的資訊。我想你自己能找到的。在這張合約上簽字，讓我們達成交易。', `MaleText_loc7`='Verás, todo lo que tienes que hacer es forjar el martillo de Sulfuron y encontrar el Ojo de Sulfuras. Después, combina el Ojo de Sulfuras con el martillo de Sulfuron, ¡y se convertirá en Sulfuras! Bueno, no voy a aburrirte con información técnica sobre dónde o cómo encontrar el Ojo de Sulfuras. Estoy seguro de que lo puedes conseguir tranquilamente. Firma este contrato para que nuestro acuerdo sea vinculante y habremos terminado.' WHERE `ID`=9643;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계약서를 주십시오.', `MaleText_loc4`='把契约给我。', `MaleText_loc5`='把契約給我。', `MaleText_loc7`='Dame el contrato.', `FemaleText_loc1`='계약서를 주십시오.', `FemaleText_loc4`='把契约给我。', `FemaleText_loc5`='把契約給我。', `FemaleText_loc7`='Dame el contrato.' WHERE `ID`=9644;
