UPDATE `locales_broadcast_text` SET `MaleText_loc1`='승리했습니다!', `MaleText_loc4`='你胜利了！', `MaleText_loc5`='你是勝利者!', `MaleText_loc7`='¡HAS GANADO!', `FemaleText_loc1`='승리했습니다!', `FemaleText_loc4`='你胜利了！', `FemaleText_loc5`='你是勝利者!', `FemaleText_loc7`='¡HAS GANADO!' WHERE `ID`=9646;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='졌습니다. 우우~', `MaleText_loc4`='你失败了！', `MaleText_loc5`='你是失敗者!', `MaleText_loc7`='¡HAS PERDIDO!', `FemaleText_loc1`='졌습니다. 우우~', `FemaleText_loc4`='你失败了！', `FemaleText_loc5`='你是失敗者!', `FemaleText_loc7`='¡HAS PERDIDO! ¡BUUU!' WHERE `ID`=9647;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 난 또다시 실패했군요...', `FemaleText_loc4`='我再次失败了……', `FemaleText_loc5`='我再次失敗了...', `FemaleText_loc7`='He vuelto a fallar...' WHERE `ID`=9648;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제야 내가 왔던 곳으로 돌아왔는데 또다시 엄청난 비극을 겪게 되다니...', `FemaleText_loc4`='我现在就回去，我到这儿来无非是再次体验相同的悲惨遭遇罢了。', `FemaleText_loc5`='我現在就回去，我到這兒來無非是再次體驗相同的悲慘遭遇罷了。', `FemaleText_loc7`='Ahora regreso al lugar de donde vengo, solo para encontrarme de nuevo aquí, para revivir la misma tragedia épica.' WHERE `ID`=9649;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어... 끝났구나...', `MaleText_loc4`='终于结束了……', `MaleText_loc5`='終於結束了...', `MaleText_loc7`='Por fin ha terminado...', `FemaleText_loc1`='드디어... 끝났구나...', `FemaleText_loc4`='终于结束了……', `FemaleText_loc5`='終於結束了...', `FemaleText_loc7`='Por fin ha terminado...' WHERE `ID`=9650;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙습니다. 친절하신 분. 당신의 영웅적인 행동이 결코 잊혀지지 않기를 바랍니다.', `MaleText_loc4`='谢谢你，好心的陌生人。我们将永远铭记你的英雄事迹。', `MaleText_loc5`='謝謝你，好心的陌生人。我們將永遠銘記你的英雄事蹟。', `MaleText_loc7`='Gracias, eres muy amable. Que tu heroísmo no se olvide jamás.', `FemaleText_loc1`='고맙습니다. 친절하신 분. 당신의 영웅적인 행동이 결코 잊혀지지 않기를 바랍니다.', `FemaleText_loc4`='谢谢你，好心的陌生人。我们将永远铭记你的英雄事迹。', `FemaleText_loc5`='謝謝你，好心的陌生人。我們將永遠銘記你的英雄事蹟。', `FemaleText_loc7`='Gracias, amable $gforastero:forastera;. Que tu heroísmo no se olvide jamás.' WHERE `ID`=9651;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 당신과 함께하게 되었군요, 내 사랑...', `MaleText_loc4`='我的爱人，我们会再次复合的……', `MaleText_loc5`='我的愛人，我們會再次複合的...', `MaleText_loc7`='Podremos volver a estar juntos, amor mío...', `FemaleText_loc1`='다시 당신과 함께하게 되었군요, 내 사랑...', `FemaleText_loc4`='我的爱人，我们会再次复合的……', `FemaleText_loc5`='我的愛人，我們會再次複合的...', `FemaleText_loc7`='Podremos volver a estar juntos, amor mío...' WHERE `ID`=9652;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이방인이여, 부디 타락한 메네실 왕자를 찾아 그의 공포 정치에 종지부를 찍어주십시오.', `MaleText_loc4`='陌生人，去找战败的王子米奈希尔和他统治的国土。', `MaleText_loc5`='陌生人，去找戰敗的王子米奈希爾和他統治的國土。', `MaleText_loc7`='$gForastero:forastera;, encuentra al príncipe caído, Menethil, y pon fin a su reinado de terror.', `FemaleText_loc1`='이방인이여, 부디 타락한 메네실 왕자를 찾아 그의 공포 정치에 종지부를 찍어주십시오.', `FemaleText_loc4`='陌生人，去找战败的王子米奈希尔和他统治的国土。', `FemaleText_loc5`='陌生人，去找戰敗的王子米奈希爾和他統治的國土。', `FemaleText_loc7`='$gForastero:forastera;, encuentra al príncipe caído, Menethil, y pon fin a su reinado de terror.' WHERE `ID`=9653;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛의 힘은 참으로 위대하고 자비롭군요.', `MaleText_loc4`='光明的力量如此强大、如此仁慈。', `MaleText_loc5`='光明的力量如此強大、如此仁慈。', `MaleText_loc7`='El poder de la Luz es grandioso y misericordioso.', `FemaleText_loc1`='빛의 힘은 참으로 위대하고 자비롭군요.', `FemaleText_loc4`='光明的力量如此强大、如此仁慈。', `FemaleText_loc5`='光明的力量如此強大、如此仁慈。', `FemaleText_loc7`='El poder de la Luz es grandioso y misericordioso.' WHERE `ID`=9654;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='치유되어라!', `FemaleText_loc4`='痊愈吧！', `FemaleText_loc5`='已接受治療!', `FemaleText_loc7`='¡Cúrate!' WHERE `ID`=9655;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전쟁에는 희생이 따르죠... 시간이 지나면 묻혀버리고 마는 희생이요. 그러한 희생이 바로 고아들이랍니다. 아제로스 전역에서 너무나 빈번하게 발생하는 충돌로 인해 부모를 잃은 불쌍한 아이들이죠. 기댈 곳이 없는 아이들은 이곳에 와서 혼자 살아갈 수 있는 나이가 될 때까지 지낸답니다.$B$B우리 호드는 봄이 오면 일주일 동안 시간을 내서 이 무고한 아이들에게 뭔가를 해주는 행사를 벌이는데, 이 주간을 바로 어린이 주간이라고 해요.', `FemaleText_loc4`='战争是有代价的，$c……这种代价常常被我们忽略。艾泽拉斯大地冲突迭起，到处都是失去双亲的孤儿。那些无家可归的孤儿没有别的地方可去，他们通常在这儿成长，到了自力更生的年龄才离开。$B$B部落将春季的某一周设为儿童周，为这些无辜的孩子赠送物品。', `FemaleText_loc5`='戰爭是有代價的，$c...這種代價常常被我們忽略。艾澤拉斯大地衝突迭起，到處都是失去雙親的孤兒。那些無家可歸的孤兒沒有別的地方可去，他們通常在這兒成長，到了自力更生的年齡才離開。$B$B部落將春季的某一週設為兒童週，為這些無辜的孩子贈送物品。', `FemaleText_loc7`='La guerra conlleva unos costos, $c... Unos que, a menudo, se pasan por alto. Esos costos son los huérfanos, niños que han perdido a sus padres en los demasiado numerosos conflictos que asolan Azeroth. Esos niños, que no tienen a quien acudir, a menudo vienen a vivir aquí hasta que son lo suficientemente mayores para no depender de nadie.$B$BUna semana al año, en la primavera, la Horda intenta darles algo a estos inocentes. Y esto se llama la Semana de los Niños.' WHERE `ID`=9656;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하찮은 생명이여, 내가 왔도다! 너희의 운명을 맞이하라!', `MaleText_loc4`='卑微的人类——我在这儿！你们的末日到啦！', `MaleText_loc5`='卑微的人類─我在這兒!你們的末日到啦!', `MaleText_loc7`='¡Mortales diminutos, yo ESTAR AQUÍ! ¡Llegar su día del Juicio Final!' WHERE `ID`=9658;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전쟁에는 희생이 따르지요... 가끔 그냥 묻혀버리고 마는 희생이요. 그러한 희생이 바로 고아들이랍니다. 아제로스 전역에서 너무나 빈번하게 일어나는 충돌로 말미암아 부모를 잃은 아이들이죠. 기댈 곳이 없는 아이들은 이곳에 와서 혼자 살아갈 수 있는 나이가 될 때까지 지낸답니다.$B$B얼라이언스에서는 봄이 오면 일주일 동안 시간을 내어 이 무고한 아이들에게 아이들이 원하는 뭔가를 해주는 행사를 벌이는데, 이 주간을 어린이 주간이라고 한답니다.', `FemaleText_loc4`='战争是有代价的，$c……这种代价常常被我们忽略。艾泽拉斯大地冲突迭起，到处都是失去双亲的孤儿。那些无家可归的孤儿没有别的地方可去，他们通常在这儿成长，到了自力更生的年龄才离开。$B$B联盟将春季的某一周设为儿童周，为这些无辜的孩子赠送物品。', `FemaleText_loc5`='戰爭是有代價的，$c...這種代價常常被我們忽略。艾澤拉斯大地衝突迭起，到處都是失去雙親的孤兒。那些無家可歸的孤兒沒有別的地方可去，他們通常在這兒成長，到了自力更生的年齡才離開。$B$B聯盟將春季的某一週設為兒童週，為這些無辜的孩子贈送物品。', `FemaleText_loc7`='La guerra conlleva unos costes, $c... Unos que, a menudo, se pasan por alto. Esos costes son los huérfanos, niños que han perdido a sus padres en los demasiado numerosos conflictos que asolan Azeroth. Esos niños, que no tienen a quien acudir, a menudo vienen a vivir aquí hasta que son lo suficientemente mayores para no depender de nadie.$B$BUna semana al año, en la primavera, la Alianza intenta darles algo a estos inocentes. Y esto se llama la Semana de los Niños.' WHERE `ID`=9659;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐라고?! 너는 날 이길 수 없다! 난 다시 돌아올 것이다!', `MaleText_loc4`='什么？！你不可能打败我！我会回来的！', `MaleText_loc5`='什麼?!你不可能打敗我!我會回來的!', `MaleText_loc7`='¡¿Qué?! ¡Tú no poder vencerme! ¡Volveré!' WHERE `ID`=9660;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 끝나지 않았다, 어리석은 놈들아! 결국 모든 것이 재로 변할 것이니라!', `MaleText_loc4`='你还没有见识过真正的我，愚蠢的家伙！我最终会毁掉一切的！', `MaleText_loc5`='你還沒有見識過真正的我，愚蠢的傢伙!我最終會毀掉一切的!', `MaleText_loc7`='¡Volveréis a verme, miserables! ¡Todo será consumido!' WHERE `ID`=9661;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='들어라! 분화구의 모든 생명체들이여, 나는 이 땅의 모든 불순한 무리를 제거하고자 왔노라!', `MaleText_loc4`='环形山的居民们，听我说！我是来烧毁这片不洁的土地的！', `MaleText_loc5`='環形山的居民們，聽我說!我是來燒毀這片不潔的土地的!', `MaleText_loc7`='¡Escuchadme, ciudadanos del Cráter! ¡He venido a quemar esta tierra, a poner fin a su impureza!' WHERE `ID`=9662;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제이나 님. 이상하게 들릴지 모르겠습니다만... 제가 지금 어린 고아를 하나 돌보고 있는데, 워낙 수줍음이 많습니다. 여군주님을 굉장히 존경한다면서 친필서명을 받아달라고 부탁하더군요.', `MaleText_loc4`='吉安娜女士，这听起来像是个奇怪的请求……但是我正在照顾一个非常害羞的孩子。对他来说，你是个英雄，他想要你的签名。', `MaleText_loc5`='珍娜女士，這聽起來像是個奇怪的請求...但是我這裡有一位相當害羞的年輕人。對他來說，你是個英雄，他想要你的簽名。', `MaleText_loc7`='Lady Jaina, quizás te parezca una extraña petición... Pero tengo a un joven guardia bastante tímido. Eres una gran heroína para él y me ha pedido que le consiguiera tu autógrafo.', `FemaleText_loc1`='제이나 님. 이상하게 들릴지 모르겠습니다만... 제가 지금 어린 고아를 하나 돌보고 있는데, 워낙 수줍음이 많습니다. 여군주님을 굉장히 존경한다면서 친필서명을 받아달라고 부탁하더군요.', `FemaleText_loc4`='吉安娜女士，这听起来像是个奇怪的请求……但是我正在照顾一个非常害羞的孩子。对他来说，你是个英雄，他想要你的签名。', `FemaleText_loc5`='珍娜女士，這聽起來像是個奇怪的請求...但是我這裡有一位相當害羞的年輕人。對他來說，你是個英雄，他想要你的簽名。', `FemaleText_loc7`='Lady Jaina, quizás te parezca una extraña petición... Pero tengo a un joven guardia bastante tímido. Eres una gran heroína para él y me ha pedido que le consiguiera tu autógrafo.' WHERE `ID`=9663;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 심연에서 돌아오는 날, 너희 모두 큰 대가를 치르리라!', `MaleText_loc4`='当我从深渊回来的时候你就得付出代价！', `MaleText_loc5`='當我從深淵回來的時候你就得付出代價!', `MaleText_loc7`='¡Lo pagaréis muy caro cuando vuelva del inframundo!' WHERE `ID`=9664;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그렇군요... 그대는 참 친절하군요. 어린이 주간 동안 자원봉사를 하는 모양이지요. 정말 칭찬받을 만한 일이 아닐 수 없네요. 우리 모두 전쟁으로 불우해진 이웃들, 특히 어린이들을 꼭 기억해야 해요.$B$B기꺼이 서명해 드리지요. 자, 받으세요.', `FemaleText_loc4`='哎呀……你可真是好人。我听说你是儿童周的志愿者，是吗，$c？嗯，你会受到赞扬的。我们必须记得那些不幸的人——特别是那些孩子。$B$B我很高兴能给他签名。给你。', `FemaleText_loc5`='哎呀...你可真是好人。我聽說你是兒童週的志願者，是嗎$c?嗯，你會受到讚揚的。我們必須記得那些不幸的人─特別是那些孩子。$B$B我很樂意簽名。拿去吧。', `FemaleText_loc7`='Oh... Qué amable de tu parte. Supongo que te estás ofreciendo $gvoluntario:voluntaria; para la Semana de los Niños, ¿no, $c? Bueno, eres $gdigno:digna; de elogio. Es de suma importancia que recordemos a aquellos menos afortunados, especialmente los niños.$B$BMe encantará firmar un autógrafo. Aquí tienes...' WHERE `ID`=9665;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일단 이 얼어붙은 땅덩어리로 만족하도록 하지... 덤벼라! 필멸의 생명체들아... 빠르고도 고통스러운 죽음을 맛보게 해주마.', `MaleText_loc4`='这片被冻结的土地将成为我们的起点。来吧，凡人们，我会让你们痛苦地死去。', `MaleText_loc5`='這片被凍結的土地還是能承受的。跟我一起來吧，人類─我會讓你痛苦地死去的。', `MaleText_loc7`='Esta tierra congelada será suficiente para empezar. Venid a mí, mortales. Y os daré una muerte rápida y dolorosa.' WHERE `ID`=9666;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오게, 젊은 친구... 썬더 블러프에 온 걸 환영하네. 이곳에서는 세상 짐을 벗어버리고 편안하게 쉴 수 있을 걸세. 호드의 일원이라면 누구나 환영이지.$B$B이 성스러운 곳에서는 현재와 과거의 영혼들이 다시 살아난다네. 그들에게 예를 갖추게. 그리고 자기 자신에게 예를 갖추는 것도 잊지 말게나.', `MaleText_loc4`='年轻人，欢迎你来到雷霆崖。在这儿你能卸下负担，享受庇佑。我们欢迎所有的部落居民来到雷霆崖。$B$B我的朋友，灵魂都会来这个神圣的地方复活。尊敬他们吧，这也是尊敬你自己。', `MaleText_loc5`='年輕人，歡迎你來到雷霆崖。在這兒你能卸下負擔，享受庇佑。我們歡迎所有的部落居民來到雷霆崖。$B$B我的朋友，靈魂都會來這個神聖的地方復活。尊敬他們吧，這也是尊敬你自己。', `MaleText_loc7`='Saludos, joven. Te doy la bienvenida a Cima del Trueno. Aquí encontrarás un refugio seguro de las cargas del mundo. Todos los miembros de la Horda son bienvenidos aquí.$B$BLos espíritus del presente y del pasado conviven aquí, en este sagrado lugar. Hónrales y, al hacerlo, hónrate a ti $gmismo:misma;.' WHERE `ID`=9667;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 하늘로 사라집니다. 아직도 귓가에는 바람소리가 윙윙거립니다.', `MaleText_loc4`='%s消散在空气中，他的哀号声还在你耳边回荡。', `MaleText_loc5`='%s消散在空氣中，他的哀號聲還在你耳邊迴蕩。', `MaleText_loc7`='%s se disipa en el éter, su viento aullador sigue resonando en tus oídos.' WHERE `ID`=9668;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 이끄는 침략군이 소란스러운 사태가 발생한 실리더스 북서쪽 현장에 나타납니다.', `MaleText_loc4`='%s率领入侵的大军突然从希利苏斯西北方的火场中冲出。', `MaleText_loc5`='%s和他的大軍突然從希利蘇斯西北方的火場中躍出。', `MaleText_loc7`='%s y sus fuerzas invasoras aparecen en medio de una tumultuosa conflagración al noroeste de Silithus.' WHERE `ID`=9669;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='블러드후프 족장님, 좀 이상하게 들리실 지 모르겠습니다만... 제가 지금 어린 고아를 하나 돌보고 있는데 워낙 수줍음이 많은 아이라서요. 족장님을 굉장히 존경한다면서 저한테 발굽도장을 받아달라고 부탁하더군요.', `MaleText_loc4`='血蹄酋长，也许这请求听起来有些奇怪……但是我正在照顾一个非常害羞的孩子。对他来说，你就是个英雄，是他请求我来拿到你的蹄印。', `MaleText_loc5`='血蹄酋長，也許這請求聽起來有些奇怪...但是我這裡有一位相當害羞的年輕人。對他來說，你就是個英雄，是他請求我來拿你的蹄印的。', `MaleText_loc7`='Jefe Pezuña de Sangre, quizás te parezca una extraña petición... Pero tengo a un joven guardia bastante tímido. Eres un gran héroe para él y me ha pedido que le consiguiera la huella de tu pezuña.', `FemaleText_loc1`='블러드후프 족장님, 좀 이상하게 들리실 지 모르겠습니다만... 제가 지금 어린 고아를 하나 돌보고 있는데 워낙 수줍음이 많은 아이라서요. 족장님을 굉장히 존경한다면서 저한테 발굽도장을 받아달라고 부탁하더군요.', `FemaleText_loc4`='血蹄酋长，也许这请求听起来有些奇怪……但是我正在照顾一个非常害羞的孩子。对他来说，你就是个英雄，是他请求我来拿到你的蹄印。', `FemaleText_loc5`='血蹄酋長，也許這請求聽起來有些奇怪...但是我這裡有一位相當害羞的年輕人。對他來說，你就是個英雄，是他請求我來拿你的蹄印的。', `FemaleText_loc7`='Jefe Pezuña de Sangre, quizás te parezca una extraña petición... Pero tengo a un joven guardia bastante tímido. Eres un gran héroe para él y me ha pedido que le consiguiera la huella de tu pezuña.' WHERE `ID`=9670;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 어린이 전사의 부탁인 게로군! 그대도 어린이 주간 중 자원봉사를 하고 있는 모양이지? 솔선수범해서 다른 이들에게 좋은 본보기가 되고 있다니 나의 시린 무릎이 다 따뜻해지는구나.$B$B그대와 그 어린 소년의 부탁을 기꺼이 들어주겠다. 흠... 그런데 그 아이에게 어떤 조언을 해주는 게 좋을까? 영혼의 소리에 귀를 기울이거라? 그래... 편식하지 말고 반찬을 골고루 먹거라... 특히 채소를 말이지...', `MaleText_loc4`='啊，毫无疑问，他一定是想要成为一名战士！我想你是来参加儿童周的，是吗？你的行为堪称楷模，其他人必定会以你为榜样的，这令那些疲惫不堪的灵魂倍感欣慰。$B$B我很乐意帮助你和这位年轻的男子。嗯……我要给他提些什么建议呢？听听灵魂怎么说吧，是的……或许是关于吃掉所有蔬菜……', `MaleText_loc5`='啊，毫無疑問，他一定是想要成為一名戰士!我想你是來參加兒童週的，是嗎?你的行為堪稱楷模，其他人必定會以你為榜樣的，這令那些疲憊不堪的靈魂倍感欣慰。$B$B我很樂意幫助你和這位年輕的男子。嗯...我要給他提些什麼建議呢?聽聽靈魂怎麼說吧，是的...或許是關於吃掉所有蔬菜...', `MaleText_loc7`='¡Ah, $gun joven guerrero:una joven guerrera;, no cabe duda! ¿Supongo que has venido a participar en la Semana de los Niños, no? Mis cansados huesos se sienten reconfortados al oír que vas a dar ejemplo y otros muchos te seguirán.$B$BMe encantará ayudaros a ti y al muchachito. Mmm... ¿Qué consejo debería darle? Escucha a los espíritus, sí... Y quizás, algo así como que se coma las verduras también...' WHERE `ID`=9671;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어린이 주간이 아직 끝나지 않았으니 고아 호루라기를 하나 더 받을 수 있을까요?', `MaleText_loc4`='看护者之周还没有结束……我能再拿一个孤儿哨吗？', `MaleText_loc5`='兒童週還沒有結束...我能再拿一個孤兒哨嗎?', `MaleText_loc7`='La Semana de los Niños todavía no se ha terminado... ¿Me puedes dar otro silbato de huérfano?', `FemaleText_loc1`='어린이 주간이 아직 끝나지 않았으니 고아 호루라기를 하나 더 받을 수 있을까요?', `FemaleText_loc4`='看护者之周还没有结束……我能再拿一个孤儿哨吗？', `FemaleText_loc5`='兒童週還沒有結束...我能再拿一個孤兒哨嗎?', `FemaleText_loc7`='La Semana de los Niños todavía no se ha terminado... ¿Me puedes dar otro silbato de huérfano?' WHERE `ID`=9672;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꽤나 겁쟁이로군! 내가 찾아내겠다!', `MaleText_loc4`='你被吓坏啦！我找到你啦！', `MaleText_loc5`='你被嚇壞啦!我找到你啦!', `MaleText_loc7`='¡Tú tener mucho miedo! ¡Yo encontrarte!' WHERE `ID`=9673;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 필멸의 생명체들이 전부 다 이렇게 겁쟁이라면... 흠, 생각보다 훨씬 수월하겠군!', `MaleText_loc4`='要是你们人类都这么胆小的话，这事儿比我想象的就容易多了！', `MaleText_loc5`='要是你們人類都這麼膽小的話，這事兒比我想像的就容易多了!', `MaleText_loc7`='Si los mortales sois tan cobardes, ¡esto va a ser más fácil de lo que yo había pensado!' WHERE `ID`=9674;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번 주가 어린이 주간이네요! 제가 뭘 도와드리면 될까요?', `MaleText_loc4`='嘿，朋友，这是儿童周！我能帮忙吗？', `MaleText_loc5`='你知道嗎，現在是兒童週!我能幫上什麼忙嗎?', `MaleText_loc7`='¡Bueno, esta es la Semana de los Niños! ¿Qué puedo hacer para ayudar?', `FemaleText_loc1`='이번 주가 어린이 주간이네요! 제가 뭘 도와드리면 될까요?', `FemaleText_loc4`='嘿，朋友，这是儿童周！我能帮忙吗？', `FemaleText_loc5`='你知道嗎，現在是兒童週!我能幫上什麼忙嗎?', `FemaleText_loc7`='¡Bueno, esta es la Semana de los Niños! ¿Qué puedo hacer para ayudar?' WHERE `ID`=9675;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소위 이 세계의 영웅이란 것들은 다 어디 있는 게냐? 너무 무서워서 내 앞에 나오지도 못하는 게냐?', `MaleText_loc4`='所谓的英雄在哪儿？心里害怕不敢出来玩吗？', `MaleText_loc5`='所謂的英雄在哪兒?心裡害怕不敢出來玩嗎?', `MaleText_loc7`='¿Dónde están los supuestos héroes de este mundo? ¿Demasiado gallinas para salir a jugar?' WHERE `ID`=9676;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어린이 주간 동안 우리 아이들 중 한 명의 후견인이 되어주세요!', `FemaleText_loc4`='在守护者之周中成为一名孤儿的导师！哈哈！', `FemaleText_loc5`='在守護者之週中成為一名孤兒的導師!哈哈!', `FemaleText_loc7`='Conviértete en $gun mentor:una mentora; para uno de nuestros huérfanos durante la Semana de los Celadores! ¡Genial!' WHERE `ID`=9677;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이번 어린이 주간 동안 우리 고아 중 한 명을 돌봐주세요! 호드를 위하여!', `FemaleText_loc4`='在守护者之周中成为一名孤儿的导师！为了部落！', `FemaleText_loc5`='在守護者之週中成為一名孤兒的導師!為了部落!', `FemaleText_loc7`='Conviértete en $gun mentor:una mentora; para uno de nuestros huérfanos durante la Semana de los Celadores! ¡Por la Horda!' WHERE `ID`=9678;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 돌풍을 일으켜 대지를 휩씁니다. 북서쪽에서 끔찍한 분노에 가득한 소리가 들려옵니다.', `MaleText_loc4`='狂风骤起，%s愤怒的吼叫声从西北方传来。', `MaleText_loc5`='%s在大地卷起一陣狂風，從西北方傳來他憤怒的吼叫聲。', `MaleText_loc7`='%s provoca un vendaval que se extiende por la tierra; el sonido de su furia salvaje se aproxima desde el noroeste.' WHERE `ID`=9679;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 안 될 것... 같아요... 머... 먼저 가... 세요...', `MaleText_loc4`='我不会……撒手不管的……', `MaleText_loc5`='我不會...撒手不管的...', `MaleText_loc7`='No lo conseguiré... Vete... Sigue sin mí...', `FemaleText_loc1`='저는 안 될 것... 같아요... 머... 먼저 가... 세요...', `FemaleText_loc4`='我不会……撒手不管的……', `FemaleText_loc5`='我不會...撒手不管的...', `FemaleText_loc7`='No lo conseguiré... Vete... Sigue sin mí...' WHERE `ID`=9680;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아악! 참을 수 없을 정도로 고통스러워요!', `MaleText_loc4`='难以忍受的痛苦！', `MaleText_loc5`='難以忍受的痛苦!', `MaleText_loc7`='El dolor es insoportable.', `FemaleText_loc1`='아아악! 참을 수 없을 정도로 고통스러워요!', `FemaleText_loc4`='难以忍受的痛苦！', `FemaleText_loc5`='難以忍受的痛苦!', `FemaleText_loc7`='El dolor es insoportable.' WHERE `ID`=9681;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 살아남으면 아서스를 파괴하는 데 내 남은 일생을 바치리...', `MaleText_loc4`='如果我能活下来，我一定把杀死阿尔萨斯当做毕生的目标……', `MaleText_loc5`='如果我經歷過，我會以殺死阿薩斯以畢生目標的...', `MaleText_loc7`='Si consigo sobrevivir, la única ambición de mi vida será destruir a Arthas...', `FemaleText_loc1`='여기서 살아남으면 아서스를 파괴하는 데 내 남은 일생을 바치리...', `FemaleText_loc4`='如果我能活下来，我一定把杀死阿尔萨斯当做毕生的目标……', `FemaleText_loc5`='如果我經歷過，我會以殺死阿薩斯以畢生目標的...', `FemaleText_loc7`='Si consigo sobrevivir, la única ambición de mi vida será destruir a Arthas...' WHERE `ID`=9682;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음이여, 어서 날 데리고 가라! 더 이상은 견딜 수 없다! 내겐 아무것도 남은 게 없다...', `MaleText_loc4`='死亡来临了！我不能继续下去了！我没有什么剩下的了……', `MaleText_loc5`='死亡來臨了!我不能繼續下去了!我沒有什麼剩下的了...', `MaleText_loc7`='¡Que la muerte me lleve! No puedo seguir adelante. Ya no me queda nada...', `FemaleText_loc1`='죽음이여, 어서 날 데리고 가라! 더 이상은 견딜 수 없다! 내겐 아무것도 남은 게 없다...', `FemaleText_loc4`='死亡来临了！我不能继续下去了！我没有什么剩下的了……', `FemaleText_loc5`='死亡來臨了!我不能繼續下去了!我沒有什麼剩下的了...', `FemaleText_loc7`='¡Que la muerte me lleve! No puedo seguir adelante. Ya no me queda nada...' WHERE `ID`=9683;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실바람 산장에 있는 샨드리나를 찾아가 보십시오. "고급 요리책"을 팔고 있을 겁니다.', `MaleText_loc4`='去银风避难所找珊蒂瑞亚吧。她可以卖给你“中级烹饪教材”。', `MaleText_loc5`='去銀風避難所找珊蒂瑞亞吧。她可以賣給你「高級烹飪書」。', `MaleText_loc7`='Busca a Shandrina en el Refugio Brisa de Plata. Te puede vender el "Libro de cocina para expertos".', `FemaleText_loc1`='실바람 산장에 있는 샨드리나를 찾아가 보십시오. "고급 요리책"을 팔고 있을 겁니다.', `FemaleText_loc4`='去银风避难所找珊蒂瑞亚吧。她可以卖给你“中级烹饪教材”。', `FemaleText_loc5`='去銀風避難所找珊蒂瑞亞吧。她可以賣給你「高級烹飪書」。', `FemaleText_loc7`='Busca a Shandrina en el Refugio Brisa de Plata. Te puede vender el "Libro de cocina para expertos".' WHERE `ID`=9684;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요리란 평생 꾸준히 익혀야 하지요. 우린 같은 열정을 지니고 있는 것 같군요!', `MaleText_loc4`='烹饪是我一生的追求，我觉得我们俩有共同的爱好！', `MaleText_loc5`='烹飪是一種值得畢生追求的職業，而我可以看到我們共有著一樣的熱情!', `MaleText_loc7`='Cocinar es algo para toda la vida, y veo que compartimos la misma pasión.', `FemaleText_loc1`='요리란 평생 꾸준히 익혀야 하지요. 우린 같은 열정을 지니고 있는 것 같군요!', `FemaleText_loc4`='烹饪是我一生的追求，我觉得我们俩有共同的爱好！', `FemaleText_loc5`='烹飪是一種值得畢生追求的職業，而我可以看到我們共有著一樣的熱情!', `FemaleText_loc7`='Cocinar es algo para toda la vida, y veo que compartimos la misma pasión.' WHERE `ID`=9685;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요리라면 가젯잔의 더지 퀵클레이브가 달인입니다. 요리 솜씨를 늘리려면 그자를 찾아가야 할 겁니다.', `MaleText_loc4`='加基森的迪尔格·奎克里弗对厨艺非常精通。要想提高自己的能力，你就去找他吧。', `MaleText_loc5`='加基森的戴格·迅斬對廚藝非常精通。要想提高自己的能力，你就去找他吧。', `MaleText_loc7`='Dirge Hojágil de Gadgetzan es un maestro de las artes culinarias. Búscale si quieres que tu habilidad mejore.', `FemaleText_loc1`='요리라면 가젯잔의 더지 퀵클레이브가 달인입니다. 요리 솜씨를 늘리려면 그자를 찾아가야 할 겁니다.', `FemaleText_loc4`='加基森的迪尔格·奎克里弗对厨艺非常精通。要想提高自己的能力，你就去找他吧。', `FemaleText_loc5`='加基森的戴格·迅斬對廚藝非常精通。要想提高自己的能力，你就去找他吧。', `FemaleText_loc7`='Dirge Hojágil de Gadgetzan es un maestro de las artes culinarias. Búscale si quieres que tu habilidad mejore.' WHERE `ID`=9686;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그늘수렵 마을에 있는 울란이 "고급 요리책"을 팔고 있소. 요리 솜씨를 늘리려면 그 책이 필요할 것이오.', `MaleText_loc4`='葬影村的乌兰可以卖给你“中级烹饪教材”。如果你想要提高烹饪技能的话，就需要这本书。', `MaleText_loc5`='葬影村的烏蘭可以賣給你「高級烹飪書」。如果你想要提高烹飪技能的話，就需要這本書。', `MaleText_loc7`='Wulan, en la Aldea Cazasombras, puede venderte el "Libro de cocina para expertos". Lo necesitarás si quieres mejorar.', `FemaleText_loc1`='그늘수렵 마을에 있는 울란이 "고급 요리책"을 팔고 있소. 요리 솜씨를 늘리려면 그 책이 필요할 것이오.', `FemaleText_loc4`='葬影村的乌兰可以卖给你“中级烹饪教材”。如果你想要提高烹饪技能的话，就需要这本书。', `FemaleText_loc5`='葬影村的烏蘭可以賣給你「高級烹飪書」。如果你想要提高烹飪技能的話，就需要這本書。', `FemaleText_loc7`='Wulan, en la Aldea Cazasombras, puede venderte el "Libro de cocina para expertos". Lo necesitarás si quieres mejorar.' WHERE `ID`=9687;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 요리를 가르쳐 드리죠!', `MaleText_loc4`='我可以教你如何烹饪！', `MaleText_loc5`='我可以教你如何烹飪!', `MaleText_loc7`='Puedo enseñarte a cocinar.', `FemaleText_loc1`='제가 요리를 가르쳐 드리죠!', `FemaleText_loc4`='我可以教你如何烹饪！', `FemaleText_loc5`='我可以教你如何烹飪!', `FemaleText_loc7`='Puedo enseñarte a cocinar.' WHERE `ID`=9688;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='불쌍하기도 하지.', `FemaleText_loc4`='可怜的孩子，我为你难过。', `FemaleText_loc5`='可憐的孩子，我為你難過。', `FemaleText_loc7`='Es muy triste para los pobres niños.' WHERE `ID`=9689;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='애들아, 이제 그만해! 안 그러면 화낸다!', `FemaleText_loc4`='孩子们，停下来！别闹了！', `FemaleText_loc5`='孩子們，停下來!我是說真的!', `FemaleText_loc7`='¡Niños, paren! ¡Lo digo en serio!' WHERE `ID`=9690;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='얘들아, 다 괜찮아질 거야. 빛의 힘이 꼭 그렇게 만들어줄 거란다!', `FemaleText_loc4`='孩子们，一切都会好起来的。光明会庇佑我们的！', `FemaleText_loc5`='孩子們，一切都會好起來的。光明會庇佑我們的!', `FemaleText_loc7`='Todo irá bien, niños. ¡La Luz se encargará de eso!' WHERE `ID`=9691;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너희들이야말로 우리의 미래라고 나는 믿고 있단다...', `FemaleText_loc4`='我相信你们这群孩子是我们的未来……', `FemaleText_loc5`='我相信你們這群孩子是我們的未來...', `FemaleText_loc7`='Creo que los niños son nuestro futuro...' WHERE `ID`=9692;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 내가 너희를 돌봐줄게. 너희는 강한 호드의 일원으로 자라게 될 거야!', `FemaleText_loc4`='孩子们，现在该我照顾你们啦。你们会成长为强壮的部落成员的！', `FemaleText_loc5`='孩子們，你們屬於我的啦。你們會成長為強壯的部落成員的!', `FemaleText_loc7`='Ahora son míos, niños. ¡Crecerán y se convertirán en fuertes miembros de la Horda!' WHERE `ID`=9693;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='찔찔 짜지 마!', `FemaleText_loc4`='别发牢骚了！', `FemaleText_loc5`='別發牢騷了!', `FemaleText_loc7`='¡Dejen de lloriquear!' WHERE `ID`=9694;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당장 깨끗이 치워! 이렇게 지저분한 곳에서 어떻게 살겠니...', `FemaleText_loc4`='把这儿打扫干净！我们可不能生活在这么糟糕的地方。', `FemaleText_loc5`='把這兒打掃乾淨!我們可不能生活在這麼骯髒的地方。', `FemaleText_loc7`='¡Limpien este lugar! No vamos a vivir en un vertedero.' WHERE `ID`=9695;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그렇게 말 안 들으면 혼자 황금길로 보내버린다. 알아 듣겠어?', `FemaleText_loc4`='要么跟着我，要么去黄金之路。明白吗？', `FemaleText_loc5`='要麼跟著我，要麼去黃金之路。明白嗎?', `FemaleText_loc7`='Hagan lo que yo digo, o al Camino de Oro. ¿Comprendido?' WHERE `ID`=9696;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 당신의 기술을 키워줄 수 있는 자는 유명한 그레고리 빅터 의사밖에 없소이다. 아라시 고원에 있는 망치 주둔지에 가면 그 친구를 찾을 수 있을 것이오.', `MaleText_loc4`='现在，只有著名的格里高利·维克托医生能提高你的技能啦。你可以在阿拉希高地的落锤镇找到他。', `MaleText_loc5`='現在，只有有名的葛列格里·維克多醫生能提高你的技能啦。你可以在阿拉希高地的落錘鎮找到他。', `MaleText_loc7`='A estas alturas, solo el famoso doctor Gregory Víctor puede ayudarte a mejorar tu habilidad. Puedes encontrarle en las Tierras Altas de Arathi, en Sentencia.', `FemaleText_loc1`='이제 당신의 기술을 키워줄 수 있는 자는 유명한 그레고리 빅터 의사밖에 없소이다. 아라시 고원에 있는 망치 주둔지에 가면 그 친구를 찾을 수 있을 것이오.', `FemaleText_loc4`='现在，只有著名的格里高利·维克托医生能提高你的技能啦。你可以在阿拉希高地的落锤镇找到他。', `FemaleText_loc5`='現在，只有有名的葛列格里·維克多醫生能提高你的技能啦。你可以在阿拉希高地的落錘鎮找到他。', `FemaleText_loc7`='A estas alturas, solo el famoso doctor Gregory Víctor puede ayudarte a mejorar tu habilidad. Puedes encontrarle en las Tierras Altas de Arathi, en Sentencia.' WHERE `ID`=9697;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='먼지진흙 습지대의 담쟁이 마을에 있는 발라이 로크웨인이 당신의 기술을 향상시키는 데 필요한 서적을 팔고 있소.', `MaleText_loc4`='尘泥沼泽蕨墙村的格鲁克卡恩在卖指南书，你需要好好研究它来提高自己的技能！', `MaleText_loc5`='塵泥沼澤，蕨牆村的格魯克卡恩在賣指南書，你需要好好研究它來提高自己的技能!', `MaleText_loc7`='Balai Lok''Wein, del Poblado Murohelecho, en el Marjal Revolcafango, tiene a la venta un manual que necesitarás estudiar si quieres mejorar tu habilidad.', `FemaleText_loc1`='먼지진흙 습지대의 담쟁이 마을에 있는 발라이 로크웨인이 당신의 기술을 향상시키는 데 필요한 서적을 팔고 있소.', `FemaleText_loc4`='尘泥沼泽蕨墙村的格鲁克卡恩在卖指南书，你需要好好研究它来提高自己的技能！', `FemaleText_loc5`='塵泥沼澤，蕨牆村的格魯克卡恩在賣指南書，你需要好好研究它來提高自己的技能!', `FemaleText_loc7`='Balai Lok''Wein, del Poblado Murohelecho, en el Marjal Revolcafango, tiene a la venta un manual que necesitarás estudiar si quieres mejorar tu habilidad.' WHERE `ID`=9698;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='응급치료 기술을 더 배우고 싶다면 존경받는 의사 구스타프 밴하우젠을 찾아가 보십시오. 테라모어 병영에서 부상자를 치료하고 있을 겁니다.', `MaleText_loc4`='倍受尊敬的古斯塔夫·范沃森医生能进一步训练你。他在塞拉摩的兵营里治疗伤兵。', `MaleText_loc5`='倍受尊敬的古斯塔夫·范沃森醫生能進一步訓練你。他就在塞拉摩的兵營裡治療傷兵。', `MaleText_loc7`='El estimado doctor Gustav VanHowzen, puede darte una instrucción mejor. Puedes encontrarle en Theramore, cuidando a los enfermos en el cuartel.', `FemaleText_loc1`='응급치료 기술을 더 배우고 싶다면 존경받는 의사 구스타프 밴하우젠을 찾아가 보십시오. 테라모어 병영에서 부상자를 치료하고 있을 겁니다.', `FemaleText_loc4`='倍受尊敬的古斯塔夫·范沃森医生能进一步训练你。他在塞拉摩的兵营里治疗伤兵。', `FemaleText_loc5`='倍受尊敬的古斯塔夫·范沃森醫生能進一步訓練你。他就在塞拉摩的兵營裡治療傷兵。', `FemaleText_loc7`='El estimado doctor Gustav VanHowzen, puede darte una instrucción mejor. Puedes encontrarle en Theramore, cuidando a los enfermos en el cuartel.' WHERE `ID`=9699;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='듣자 하니 스트롬가드에 틀어박혀 지내는 데네브 워커에게 응급치료 기술을 뚜렷이 향상시킬 서적이 있다고 합니다.', `MaleText_loc4`='我听说居住在激流堡的德尼布·沃克有一本书，这本书一定能帮助你提高急救技能。', `MaleText_loc5`='我聽說藏身在激流堡的德尼布·沃克有一本書，這本書一定能幫助你提高急救技能。', `MaleText_loc7`='He oído decir que Deneb Camino, en Stromgarde, tiene un libro que podría ayudarte a mejorar tus técnicas de primeros auxilios.', `FemaleText_loc1`='듣자 하니 스트롬가드에 틀어박혀 지내는 데네브 워커에게 응급치료 기술을 뚜렷이 향상시킬 서적이 있다고 합니다.', `FemaleText_loc4`='我听说居住在激流堡的德尼布·沃克有一本书，这本书一定能帮助你提高急救技能。', `FemaleText_loc5`='我聽說藏身在激流堡的德尼布·沃克有一本書，這本書一定能幫助你提高急救技能。', `FemaleText_loc7`='He oído decir que Deneb Camino, en Stromgarde, tiene un libro que podría ayudarte a mejorar tus técnicas de primeros auxilios.' WHERE `ID`=9700;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='응급치료 기술을 가르쳐 드리죠.', `MaleText_loc4`='我可以教你急救技能。', `MaleText_loc5`='我可以訓練你急救技能。', `MaleText_loc7`='Puedo enseñarte técnicas de primeros auxilios.', `FemaleText_loc1`='응급치료 기술을 가르쳐 드리죠.', `FemaleText_loc4`='我可以教你急救技能。', `FemaleText_loc5`='我可以訓練你急救技能。', `FemaleText_loc7`='Puedo enseñarte técnicas de primeros auxilios.' WHERE `ID`=9701;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음, 부름인가? 우선, 종을... 당신의 원기를 북돋우어 주기 위한 것이죠!', `MaleText_loc4`='嗯，要开始了，是吗？首先，钟……给你活力！', `MaleText_loc5`='嗯，關稅，是嗎?首先，鐘...提起精神來!', `MaleText_loc7`='Bueno, el deber llama, ¿no? Primero, la campana... ¡Para darte vigor!' WHERE `ID`=9702;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음으로, 이제 물레를 놓을 거예요. 해악에서 당신을 보호하기 위해서 말이죠.', `MaleText_loc4`='接下来，我会用车轮……来保护你。', `MaleText_loc5`='接下來，我會用車輪...來保護你的前臂。', `MaleText_loc7`='Después, colocaré la rueda... ¡Para protegerte del peligro!' WHERE `ID`=9703;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마지막으로 초... 당신을 방해하는 자들을 불태우기 위한 것이랍니다!', `MaleText_loc4`='最终，蜡烛……烧死那些碍手碍脚的家伙！', `MaleText_loc5`='最終，蠟燭...燒死那些阻礙你的人!', `MaleText_loc7`='Y por último, la vela... ¡Para quemar a todos aquellos que pretendan frustrarte!' WHERE `ID`=9704;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 자유다! 짧지만 달콤한 자유...', `MaleText_loc4`='啊，自由！虽然短暂，却如此甜美……', `MaleText_loc5`='啊，自由!雖然短暫，卻如此甜美...', `MaleText_loc7`='¡Ah, libertad! Aunque breve, es tan dulce...' WHERE `ID`=9705;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 내 임무는 다 완수했으니 이제 그만 가보겠어요. 종, 물레, 양초가 계속 작동되게 하는 것을 잊지 마시고요. 행운을 빌겠어요!', `MaleText_loc4`='$n，我完成了我的职责，我得走啦。祝你好运，$g先生:女士;，记得保持铃铛、书籍和蜡烛一直生效！', `MaleText_loc5`='$n，我完成了我的職責，我得走啦。祝你好運$g先生:女士;，記得保持鈴鐺、書籍和蠟燭一直生效!', `MaleText_loc7`='$n, he terminado con mi trabajo y ahora debo irme. Que tengas suerte, $gcompañero:compañera;, y recuerda mantener en funcionamiento la campana, la rueda y la vela.' WHERE `ID`=9706;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='빛에게 찬미를. 마침내 부름에 응한 자가 나타났군요.', `FemaleText_loc4`='赞美圣光，终于有人对召唤做出了回应。', `FemaleText_loc5`='讚揚聖光，終於有人對召喚做出回應啦。', `FemaleText_loc7`='Bendita sea la Luz, alguien ha respondido por fin a la llamada.' WHERE `ID`=9707;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가만...', `MaleText_loc4`='不过，我必须指出……', `MaleText_loc5`='等等...', `MaleText_loc7`='Pero, espera...' WHERE `ID`=9708;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 의식을 행해야 할 때 다시 날 소환하세요.', `MaleText_loc4`='$n，如果你需要再次执行仪式，只要再召唤我就可以了。随叫随到。', `MaleText_loc5`='$n，如果你需要執行儀式，可以再次召喚我。', `MaleText_loc7`='$n, vuelve a invocarme cuando necesites volver a realizar el ritual.' WHERE `ID`=9709;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그때까지 전 떠나 있겠어요...', `MaleText_loc4`='那么，我先走了……', `MaleText_loc5`='直到那時，我才會離開...', `MaleText_loc7`='Hasta entonces, ahora debo irme...' WHERE `ID`=9710;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너무 많이 쓰러졌어요, $g사제:여사제;님. 정신을 집중해야 해요!', `FemaleText_loc4`='太多人已经倒下了，牧师。你必须集中精神！', `FemaleText_loc5`='很多人都倒下啦，$g牧師:女牧師;。你必須集中精神!', `FemaleText_loc7`='Han caído demasiados, $gsacerdote:sacerdotisa;. ¡Debes concentrarte!' WHERE `ID`=9711;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스컬지가 나타났다! 달아나라! 목숨을 건지려면 도망쳐라!', `MaleText_loc4`='亡灵天灾来了！快跑啊！逃命吧！', `MaleText_loc5`='天譴軍團來啦!跑吧!逃命吧!', `MaleText_loc7`='¡La Plaga nos ataca! ¡Corran! ¡Corran si quieren salvar su vida!', `FemaleText_loc1`='스컬지가 나타났다! 달아나라! 목숨을 건지려면 도망쳐라!', `FemaleText_loc4`='亡灵天灾来了！快跑啊！逃命吧！', `FemaleText_loc5`='天譴軍團來啦!跑吧!逃命吧!', `FemaleText_loc7`='¡La Plaga nos ataca! ¡Corran! ¡Corran si quieren salvar su vida!' WHERE `ID`=9712;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와주세요! 왕자가 미쳐버렸어요!', `MaleText_loc4`='请帮帮我们！王子发狂了！', `MaleText_loc5`='請幫幫我們!王子發狂了!', `MaleText_loc7`='¡Por favor, ayúdanos! ¡El príncipe se ha vuelto loco!', `FemaleText_loc1`='도와주세요! 왕자가 미쳐버렸어요!', `FemaleText_loc4`='请帮帮我们！王子发狂了！', `FemaleText_loc5`='請幫幫我們!王子發狂了!', `FemaleText_loc7`='¡Por favor, ayúdanos! ¡El príncipe se ha vuelto loco!' WHERE `ID`=9713;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하스글렌으로 피신하세요! 그게 우리의 유일한 희망입니다!', `MaleText_loc4`='去壁炉谷寻求庇护吧！那是我们惟一的希望！', `MaleText_loc5`='去壁爐谷尋求庇護吧!那是我們惟一的希望!', `MaleText_loc7`='¡Buscad refugio en la Vega del Amparo! ¡Es nuestra única esperanza!', `FemaleText_loc1`='하스글렌으로 피신하세요! 그게 우리의 유일한 희망입니다!', `FemaleText_loc4`='去壁炉谷寻求庇护吧！那是我们惟一的希望！', `FemaleText_loc5`='去壁爐谷尋求庇護吧!那是我們惟一的希望!', `FemaleText_loc7`='¡Buscad refugio en la Vega del Amparo! ¡Es nuestra única esperanza!' WHERE `ID`=9714;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스트라솔름은 이제 끝이로군요! 도시는 폐허가 되어버렸고 왕자는 증오로 가득 차 미쳐버렸어요...', `MaleText_loc4`='斯坦索姆已经面目全非了！城市变成了一片废墟。王子被仇恨和疯狂……吞噬了……', `MaleText_loc5`='斯坦索姆已經面目全非啦!城市成為廢墟。王子沉浸在仇恨...瘋狂...中', `MaleText_loc7`='¡Stratholme ha desaparecido! La ciudad está en ruinas. El Príncipe, consumido por el odio... la locura...', `FemaleText_loc1`='스트라솔름은 이제 끝이로군요! 도시는 폐허가 되어버렸고 왕자는 증오로 가득 차 미쳐버렸어요...', `FemaleText_loc4`='斯坦索姆已经面目全非了！城市变成了一片废墟。王子被仇恨和疯狂……吞噬了……', `FemaleText_loc5`='斯坦索姆已經面目全非啦!城市成為廢墟。王子沉浸在仇恨...瘋狂...中', `FemaleText_loc7`='¡Stratholme ha desaparecido! La ciudad está en ruinas. El Príncipe, consumido por el odio... la locura...' WHERE `ID`=9715;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠의 눈에 이끌려 여기까지 왔습니다, 에리스.', `MaleText_loc4`='眼睛指引我来到这儿，艾瑞斯。', `MaleText_loc5`='眼睛指引我來到這兒，伊利斯。', `MaleText_loc7`='El Ojo me ha traído aquí, Eris.', `FemaleText_loc1`='어둠의 눈에 이끌려 여기까지 왔습니다, 에리스.', `FemaleText_loc4`='眼睛指引我来到这儿，艾瑞斯。', `FemaleText_loc5`='眼睛指引我來到這兒，伊利斯。', `FemaleText_loc7`='El Ojo me ha traído aquí, Eris.' WHERE `ID`=9716;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='<고개를 끄덕이는 에리스>$B$B어둠의 눈은 수많은 공포와 기적을 보아왔어요.$B$B어둠의 눈은 그것을 들여다보고 있는 자에게 가장 적합하다고 느끼는 것을 보여주죠.', `FemaleText_loc4`='<艾瑞斯点着头。>$B$B这只眼睛见证了许多恐怖和惊奇的事情。$B$B它会显现出观察者理应看到的场景。', `FemaleText_loc5`='<伊利斯點著頭。>$B$B那隻眼睛見證了許多恐怖和驚奇的事情。$B$B它會顯現出最適合注視者觀看的場景。', `FemaleText_loc7`='<Eris asiente.>$B$BEl Ojo ha visto demasiados horrores y demasiadas maravillas.$B$BMuestra lo que cree que quien lo mira está preparado para ver.' WHERE `ID`=9717;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇다면 나에게 가장 적합한 것이 이것이었단 말입니까?', `MaleText_loc4`='是说我吗？', `MaleText_loc5`='我適合觀看這個嗎?', `MaleText_loc7`='¿Y yo tenía que ver esto?', `FemaleText_loc1`='그렇다면 나에게 가장 적합한 것이 이것이었단 말입니까?', `FemaleText_loc4`='是说我吗？', `FemaleText_loc5`='我適合觀看這個嗎?', `FemaleText_loc7`='¿Y yo tenía que ver esto?' WHERE `ID`=9718;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그래요. 어둠의 눈은 틀리는 일이 없답니다.$B$B결국 그대는 $g사제:여사제;인 거예요. 어둠의 눈이 이런 끔찍한 기억을 보여주었다면 그대는 강력한 힘을 지닌 $g사제:여사제;인 것이랍니다.$B$B그대는 구원 때문에 이곳에 왔음에도 정작 자신은 그것을 깨닫지 못하고 있어요. 그렇죠?', `FemaleText_loc4`='是的。眼睛绝不会弄错的。$B$B毕竟，你是一名牧师。如果眼睛向你展示了这段恐怖的记忆，那么你肯定是一名强大的牧师。$B$B你是来救赎的，但是你甚至还没有意识到这一点……对吗？', `FemaleText_loc5`='是的。眼睛絕不會弄錯的。$B$B畢竟，你是一名$g牧師:女牧師;。如果眼睛中顯現處這段恐怖的記憶，你會是一名強大的$g牧師:女牧師;。$B$B你是來救贖的，但是你甚至還沒有意識到這一點...是嗎?', `FemaleText_loc7`='Sí. El Ojo nunca se equivoca.$B$BDespués de todo, eres $gun sacerdote:una sacerdotisa;. Debes ser $gun poderoso sacerdote:una poderosa sacerdotisa;, si el Ojo te ha mostrado ese horrible recuerdo.$B$BHas venido buscando la redención y, sin embargo, no te das cuenta de ello... ¿Verdad?' WHERE `ID`=9719;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 일이 있을지 알지 못했습니다, 에리스. 제가 만약 당신을 도와야 한다면 힘닿는 데까지 도와드리겠습니다.', `MaleText_loc4`='艾瑞斯，我真不知道会发生什么。如果你需要我的帮助，我会竭尽全力的。', `MaleText_loc5`='伊利斯，我真不知道還能期盼些什麼。如果你需要的話，我會幫助你的。', `MaleText_loc7`='Realmente, no sabía qué esperar, Eris. Utilizaré mis poderes para ayudarte si así me lo pides.', `FemaleText_loc1`='어떤 일이 있을지 알지 못했습니다, 에리스. 제가 만약 당신을 도와야 한다면 힘닿는 데까지 도와드리겠습니다.', `FemaleText_loc4`='艾瑞斯，我真不知道会发生什么。如果你需要我的帮助，我会竭尽全力的。', `FemaleText_loc5`='伊利斯，我真不知道還能期盼些什麼。如果你需要的話，我會幫助你的。', `FemaleText_loc7`='Realmente, no sabía qué esperar, Eris. Utilizaré mis poderes para ayudarte si así me lo pides.' WHERE `ID`=9720;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그대가 도와줄 것이라는 걸 압니다.$B$B비록 그대와는 달리 이 세계에서 떠난 지 오래되긴 했지만요. 나 역시 여사제니까요. 하지만 미쳐버린 아서스 메네실 왕자와 그의 언데드 군단에게 무참히 살해된 수천 명의 영혼들처럼 내 영혼도 이곳에 남아있게 되었답니다.', `FemaleText_loc4`='我知道你会的，$n。$B$B我也是一名牧师，与你不同的是，我已经辞世多年了，但是我的灵魂仍停留在此，跟这儿的数千个冤魂一样，我们是被疯狂的阿尔萨斯·米奈希尔王子和他的亡灵军团残忍杀害的。', `FemaleText_loc5`='你知道你會的，$n。$B$B我也是一名女牧師，跟你不同的是，我已辭世多年。但是我的靈魂仍停留在此，跟這兒的數千靈魂一樣，我們是被瘋狂的阿薩斯·米奈希爾王子和他的亡靈軍團殘忍殺害的。', `FemaleText_loc7`='Sé que lo harás, $n.$B$BYo misma soy una sacerdotisa aunque, al contrario de ti, hace mucho que me he ido de este mundo. Sin embargo, mi espíritu permanece aquí, al igual que los espíritus de los miles que fueron brutalmente asesinados por el príncipe Arthas Menethil y su legión de no-muertos.' WHERE `ID`=9721;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런 날도 이젠 끝입니다, 에리스.', `MaleText_loc4`='那段历史已经结束了，艾瑞斯。', `MaleText_loc5`='這些日子都結束啦，艾瑞斯。', `MaleText_loc7`='Esos días han llegado a su fin, Eris.', `FemaleText_loc1`='그런 날도 이젠 끝입니다, 에리스.', `FemaleText_loc4`='那段历史已经结束了，艾瑞斯。', `FemaleText_loc5`='這些日子都結束啦，艾瑞斯。', `FemaleText_loc7`='Esos días han llegado a su fin, Eris.' WHERE `ID`=9722;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나는 그대 자신이 구원받기 위해 여기 온 거라고는 말하지 않았습니다. 그대는 나와 스트라솔름에서 탈출하려다 살해당한 무고한 이들을 구원하러 온 거예요.$B$B내 영혼과 길 잃은 영혼들은 이곳에 구속되어 끊임없이 우리의 비극적인 죽음을 되풀이하고 있어요.', `FemaleText_loc4`='我可没说你是到这儿来救赎你自己的，牧师。你是来解救我和那些在试图逃离斯坦索姆时丧命的无辜者的。$B$B我和那些无辜者的灵魂受到诅咒，被禁锢在这儿忍受无尽的轮回。', `FemaleText_loc5`='我可沒說你是到這兒來救贖你自己的，$g牧師:女牧師;。你是來解救我和那些在試圖逃離斯坦索姆時喪命的無辜者的。$B$B我和那些無辜者的靈魂受到詛咒，被綁定在這兒忍受無盡的悲劇輪回。', `FemaleText_loc7`='Nunca dije que tuvieras que redimirte, $gsacerdote:sacerdotisa;. Estás aquí para redimirnos a mí y a los inocentes asesinados mientras tratábamos de escapar de Stratholme.$B$BMi espíritu y el de aquellos que fallecieron, están atados a este lugar, condenados a revivir eternamente nuestras trágicas muertes.' WHERE `ID`=9723;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 어떻게 하면 되는 겁니까?', `MaleText_loc4`='那么，我能帮什么忙呢？', `MaleText_loc5`='那麼，我能幫什麼忙呢?', `MaleText_loc7`='¿Qué puedo hacer para ayudar?', `FemaleText_loc1`='제가 어떻게 하면 되는 겁니까?', `FemaleText_loc4`='那么，我能帮什么忙呢？', `FemaleText_loc5`='那麼，我能幫什麼忙呢?', `FemaleText_loc7`='¿Qué puedo hacer para ayudar?' WHERE `ID`=9724;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내가 할 수 없었던 일을 해야 합니다. 스트라솔름에서 탈출하려다 살해당한 인부들을 구해야 해요.$B$B그들은 빛을 향해 나아갈 겁니다. 그대는 그들이 살아남을 수 있도록 지켜줘야 해요. 너무 많은 이들이 쓰러진다면 우리의 저주받은 삶은 계속될 겁니다. 그런 일이 벌어지면 그대는 실패하게 될 겁니다.$B$B그대가 지금까지 터득한 모든 기술과 주문, 마법을 시험받을 거예요. 빛의 가호가 있기를 빌겠어요, $n.', `FemaleText_loc4`='你必须完成我未做完的事情：保护逃离斯坦索姆的农夫。$B$B他们会走向光明，而你必须确保他们的安全。如果死去的人数量过多，我们将继续生活在诅咒之下——你的任务也会失败。$B$B这项任务将检验你学到的所有技能和法术。愿圣光保佑你，$n。', `FemaleText_loc5`='你必須完成我未做完的事情:保護逃離斯坦索姆的農民。$B$B他們會走向光明，而你必須確保他們的安全。要是死去的人數量過多，我們將繼續生活在詛咒之下─你的任務也會失敗。$B$B這項任務將檢驗你學到的所有技能和法術。願光明保佑你，$n。', `FemaleText_loc7`='Debes hacer lo que yo no pude: salvar a los campesinos que fueron asesinados cuando huían de Stratholme.$B$BIrán hacia la Luz, debes asegurarte de que sobrevivan. Si caen demasiados, nuestra existencia maldita continuará... Habrás fallado.$B$BTodas las habilidades, oraciones y hechizos que hayas aprendido se pondrán a prueba. Que la Luz te proteja, $n.' WHERE `ID`=9725;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 이 존재의 시험을 방해하겠다고? 전투는 홀로 치러야 하는 법! 이 경솔한 짓에 대한 대가를 모두 받게 될 것이다.', `MaleText_loc4`='你敢干预这家伙的试炼？挑战者必须独立战斗！你会为你的轻率之举付出代价的。', `MaleText_loc5`='你敢干預這傢伙的測試?必須獨立戰鬥!你會為你的輕率之舉付出代價的。', `MaleText_loc7`='¿Osas interferir con la prueba de este ser? ¡Nadie debe interferir en la batalla! Todos sufriréis por esta indiscreción.' WHERE `ID`=9726;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 감히 내 소중한 탈것을 앗아가려 한단 말이냐? 이 오만함에 대한 대가를 치르게 되리라, 평범한 생명체여!', `MaleText_loc4`='谁敢盗走我心爱的坐骑？你会为自己的傲慢付出代价的，凡人！', `MaleText_loc5`='誰敢盜走我心愛的坐騎?你會為自己的傲慢付出代價的，凡人!', `MaleText_loc7`='¿Quién osa robar mi valiosa montura? ¡Pagarás por tu insolencia, mortal!' WHERE `ID`=9727;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 됐어요! 인부들이 스컬지에게서 탈출했습니다!', `FemaleText_loc4`='我们得救了！农夫们逃脱了亡灵天灾的魔爪！', `FemaleText_loc5`='我們得救了啦!農民們逃脫了亡靈之手!', `FemaleText_loc7`='¡Estamos salvados! ¡Los campesinos se han salvado de la Plaga!' WHERE `ID`=9728;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공포마의 영혼이 격노하여 요동칩니다.', `MaleText_loc4`='恐怖战马的灵魂散发出愤怒的气息。', `MaleText_loc5`='恐懼戰馬的靈魂發怒啦。', `MaleText_loc7`='El espíritu del corcel nefasto late con ira.' WHERE `ID`=9729;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어이, 친구들! 다들 잘 들어! 내가 남은 보물을 나눠 줄게! 구루바시 투기장에 궤짝을 놔둘 테니 가져가라고! 먼저 여는 자가 임자인 거 알지?', `MaleText_loc4`='啊，我亲爱的朋友们！我在古拉巴什竞技场放了一些宝贝！你们要做的只是去竞技场中央，打开箱子，然后拿到里面的财宝！', `MaleText_loc5`='啊，我親愛的!我把多出來的財寶放在了古拉巴什競技場!你要做的只是去競技場中央，打開箱子，然後拿到裡面的財寶!', `MaleText_loc7`='¡Arr, compañeros! ¡Yo tener algunos tesoros extra que dar en la Arena Gurubashi! ¡Ustedes solo tener que abrir el cofre que yo dejar en el suelo de la arena!' WHERE `ID`=9730;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피 튀기는 싸움을 시작하자!', `MaleText_loc4`='开始厮杀吧！', `MaleText_loc5`='開始放血吧!', `MaleText_loc7`='¡Que comience el combate a muerte!' WHERE `ID`=9731;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 지혜의 심판에 휩싸여 고통으로 뒷걸음칩니다!', `MaleText_loc4`='%s在智慧的审判降临时痛苦地后退！', `MaleText_loc5`='%s在智慧審判降臨時痛苦地後退!', `MaleText_loc7`='¡%s se retuerce de dolor mientras la Sentencia de Sabiduría lo envuelve!' WHERE `ID`=9732;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제데나르의 방식은 어둡고 믿을 수 없는 것이오. $C|1이여;여;, 당신의 움직임 하나하나에 주의하시오. 자칫하면 적에게 영혼을 빼앗길 수 있으니...', `MaleText_loc4`='加德纳尔的行事准则是隐晦奸诈。别在这儿探头探脑，$C，否则你的灵魂就会被永远禁锢在此……', `MaleText_loc5`='加德納爾行事隱晦奸詐。你在這兒幹什麼呢，$C，你的靈魂被敵人禁錮在此的...', `MaleText_loc7`='Jaedenar es un lugar oscuro y traicionero. Ten cuidado aquí, $c, o tu alma podría acabar en manos del enemigo...' WHERE `ID`=9733;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물건을 구입하고 싶습니다.', `MaleText_loc4`='我想从你这儿买点东西。', `MaleText_loc5`='我想從你這兒買點東西。', `MaleText_loc7`='Quiero comprarte algo.', `FemaleText_loc1`='물건을 구입하고 싶습니다.', `FemaleText_loc4`='我想从你这儿买点东西。', `FemaleText_loc5`='我想從你這兒買點東西。', `FemaleText_loc7`='Quiero comprarte algo.' WHERE `ID`=9734;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더러운 놈! 이제 네 영혼을 수정 안에 가둬 내 임프에게 장난감으로 줘 버리겠다!', `MaleText_loc4`='你这个卑鄙的家伙！我会把你的灵魂变成碎片，让你成为我的小鬼的玩具！', `MaleText_loc5`='你這個卑鄙的傢伙!我會將你的靈魂變成裂片，讓你成為我的小鬼的玩具!', `MaleText_loc7`='¡Despreciable! ¡Meteré tu alma en un fragmento y se lo daré a mi diablillo como juguete!' WHERE `ID`=9735;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='썩 꺼져! 나는 공포의 군주님들과 우리의 계획을 함께 상의하는 몸이시고 우리가 의논하는 내용은 네가 신경 쓸 바 아니다!', `MaleText_loc4`='滚！我只和恐惧魔王打交道，你没资格来跟我说话！', `MaleText_loc5`='滾!我在跟驚懼領主商量要事，我們討論的事情與你無關!', `MaleText_loc7`='¡Largo! Estoy en pleno consejo con los Señores del Terror, ¡y lo que estamos discutiendo no es de tu incumbencia!' WHERE `ID`=9736;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공포의 군주라고? 베인할로우 군주님을 말하는 거겠지. 그분이 안부를 전하시며 당신에게 전할 말이 있다고 하시더군.', `MaleText_loc4`='恐惧魔王？你是说魔王贝恩霍勒。他向你问好，并有消息给你……', `MaleText_loc5`='驚懼領主?也許你是說貝恩霍勒領主。他向你問好，並有一個消息要給你...', `MaleText_loc7`='¿Señores del Terror? Quizás te refieras a Lord Pesadilla. Te envía recuerdos y tiene un mensaje para ti...', `FemaleText_loc1`='공포의 군주라고? 베인할로우 군주님을 말하는 거겠지. 그분이 안부를 전하시며 당신에게 전할 말이 있다고 하시더군.', `FemaleText_loc4`='恐惧魔王？你是说魔王贝恩霍勒。他向你问好，并有消息给你……', `FemaleText_loc5`='驚懼領主?也許你是說貝恩霍勒領主。他向你問好，並有一個消息要給你...', `FemaleText_loc7`='¿Señores del Terror? Quizás te refieras a Lord Pesadilla. Te envía recuerdos y tiene un mensaje para ti...' WHERE `ID`=9737;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='...베인할로우 님이 내게? 무슨 얘기지? 그분의 훌륭한 조언가이자 신하인 이 울라텍을 필요로 하시나? 나더러 오라고 하시는 건가?', `MaleText_loc4`='来自贝恩霍勒的消息？是什么消息？他需要伟大的导师和仆人乌拉泰克吗？他需要我吗？', `MaleText_loc5`='...來自貝恩霍勒的消息?是什麼消息?他需要偉大的導師和僕人烏拉泰克嗎?他需要我嗎?', `MaleText_loc7`='¿Un mensaje de Pesadilla? ¿Qué mensaje? ¿Necesita a su fiel consejero y sirviente, Ulathek? ¿Requiere mi presencia?' WHERE `ID`=9738;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니오, 울라텍. 그분은 당신의 비밀을 알고 계시오. 당신의 소로스의 헬누라스 군주와 음모를 꾸미고 있다는 사실을 아신단 말이지.', `MaleText_loc4`='不，乌拉泰克。他知道你的秘密。他知道你跟克索诺斯的赫尔努拉斯之间的阴谋。', `MaleText_loc5`='不，烏拉泰克。他知道你的秘密。他知道你跟克索諾斯，赫爾努拉斯領主的陰謀。', `MaleText_loc7`='No, Ulathek. Conoce tu secreto. Se ha enterado de tu plan con Lord Hel''nurath de Xoroth.', `FemaleText_loc1`='아니오, 울라텍. 그분은 당신의 비밀을 알고 계시오. 당신의 소로스의 헬누라스 군주와 음모를 꾸미고 있다는 사실을 아신단 말이지.', `FemaleText_loc4`='不，乌拉泰克。他知道你的秘密。他知道你跟克索诺斯的赫尔努拉斯之间的阴谋。', `FemaleText_loc5`='不，烏拉泰克。他知道你的秘密。他知道你跟克索諾斯，赫爾努拉斯領主的陰謀。', `FemaleText_loc7`='No, Ulathek. Conoce tu secreto. Se ha enterado de tu plan con Lord Hel''nurath de Xoroth.' WHERE `ID`=9739;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐? 하지만 어떻게? 아냐! 그럴 리가 없어! 그렇게 주의를 했는데... 알 수 있을 리가 없잖아!$B$B네 말은 거짓이다! 거짓말로 속이려 들다니 죽여 주마!', `MaleText_loc4`='什么？但是怎么可能呢？不！这不可能！我已经很小心了……他不可能知道的！$B$B你撒谎！你撒谎，你欺骗了我，去死吧！', `MaleText_loc5`='什麼?但是怎麼做呢?不!這不可能!我已經很小心了...他不可能知道的!$B$B你撒謊!你撒謊，你欺騙了我，去死吧!', `MaleText_loc7`='¿Qué? ¿Pero cómo? ¡No! ¡No es posible! He tenido mucho cuidado... ¡No puede saberlo!$B$B¡Estás mintiendo! ¡Mientes y morirás por ello!' WHERE `ID`=9740;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거짓말이 아니다, 배신자. 베인할로우 님께서 너의 심장을 원하신다. 내가 너의 심장을 가져갈 것이다.', `MaleText_loc4`='叛徒，我可没骗你。魔王贝恩霍勒想要你的命。', `MaleText_loc5`='叛徒，我可沒騙你。魔王貝恩霍勒想要你的心臟，我現在就取給他。', `MaleText_loc7`='No es una mentira, traidor. Pesadilla quiere tu corazón y yo voy a llevárselo.', `FemaleText_loc1`='거짓말이 아니다, 배신자. 베인할로우 님께서 너의 심장을 원하신다. 내가 너의 심장을 가져갈 것이다.', `FemaleText_loc4`='叛徒，我可没骗你。魔王贝恩霍勒想要你的命。', `FemaleText_loc5`='叛徒，我可沒騙你。魔王貝恩霍勒想要你的心臟，我現在就取給他。', `FemaleText_loc7`='No es una mentira, traidor. Pesadilla quiere tu corazón y yo voy a llevárselo.' WHERE `ID`=9741;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끝났어요. 양피지를 다 만들었으니 이제 고르지키 님께 가지고 가세요.', `MaleText_loc4`='完成啦。羊皮纸终于做好啦。现在回到戈瑟奇那儿去吧……', `MaleText_loc5`='完成啦。羊皮紙做好啦。現在回到戈瑟奇那兒去...', `MaleText_loc7`='¡He terminado! El papiro está listo. Ahora, ve a ver a Gorzeeki...' WHERE `ID`=9742;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 이제 나와 함께한다, 공포마! 네 영혼은 이제 내게 결속되었단다!', `MaleText_loc4`='恐怖战马，你是我的了！你的灵魂已经与我连结在一起了！', `MaleText_loc5`='恐怖戰馬，你是我的啦!你的靈魂已經跟我綁定在一起了!', `MaleText_loc7`='¡Eres mío, corcel nefasto! ¡Tu espíritu está unido al mío!', `FemaleText_loc1`='넌 이제 나와 함께한다, 공포마! 네 영혼은 이제 내게 결속되었단다!', `FemaleText_loc4`='恐怖战马，你是我的了！你的灵魂已经与我连结在一起了！', `FemaleText_loc5`='恐怖戰馬，你是我的啦!你的靈魂已經跟我綁定在一起了!', `FemaleText_loc7`='¡Eres mío, corcel nefasto! ¡Tu espíritu está unido al mío!' WHERE `ID`=9743;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='살아 있다는 게 감사히 느껴지는 멋진 날이로군요! 친구여, 주위에 펼쳐진 아름다운 광경을 한번 보세요. 삶이 우리에게 준 선물을 즐기자고요!', `FemaleText_loc4`='多么幸福的活着的一天啊！朋友，看看你周围的美景吧。享受自然赋予你的一切！', `FemaleText_loc5`='又是一個幸福的活著的一天啊!朋友，看看你周圍的美景吧。享受自然賦予的一切!', `FemaleText_loc7`='¡Qué día tan maravilloso para estar viva! Mira la belleza que te rodea, $gamigo:amiga;. ¡Disfruta de todo lo que la vida nos puede ofrecer!' WHERE `ID`=9744;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='*그르르르* *멍* *멍*', `MaleText_loc4`='*呜噜噜* *汪* *汪汪*', `MaleText_loc5`='吼～～汪汪～～汪～～', `MaleText_loc7`='*GRRRR* *UFF* *UFF*' WHERE `ID`=9745;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용암? 그런 것에는 신경 쓸 것 없습니다, 친구여... 주위 경관을 둘러보며 자연이 주는 기쁨을 있는 그대로 받아들이세요.', `MaleText_loc4`='熔岩？朋友，别在意那个。看看你周围吧。享受自然赋予的一切欢乐。', `MaleText_loc5`='熔岩?朋友，別在意那個。看看你周圍吧。享受自然賦予的一切歡樂。', `MaleText_loc7`='¿Lava? No te preocupes por eso, $gamigo mío:amiga mía;. Mira a tu alrededor. Disfruta de la belleza que la naturaleza nos ofrece.' WHERE `ID`=9746;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 매년 이맘때쯤 실리더스를 찾습니다. 발가락 물집에는 이런 날씨가 아주 딱이거든요.$B$B저랑 산책이나 합시다, 친구. 멋진 경치와 이것저것 구경해보자고요.', `MaleText_loc4`='每年的这个时候我都会来希利苏斯。这里的气候对治疗我的拇趾囊肿很有帮助。$B$B你应该跟我四处逛逛，朋友。欣赏一下风景什么的。', `MaleText_loc5`='每年的這個時候我都會來希利蘇斯。這裡的氣候對治療我的拇指囊腫很有幫助。$B$B你應該跟我四處逛逛，朋友。欣賞一下風景什麼的。', `MaleText_loc7`='Todos los años, vengo a Silithus en esta temporada. El tiempo es fantástico para mis juanetes.$B$BDeberías dar un paseo conmigo, $gamigo:amiga;. Disfruta del hermoso paisaje.' WHERE `ID`=9747;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 외진 곳에서 친구를 만나게 되다니 정말 반갑군. 자, 함께 걸어보세. 서로 체온을 나누면 몸도 따뜻해지고 좋지 않나?!', `MaleText_loc4`='在这么偏远的地方遇到人可真好啊。来吧，跟我一起。让我们用身体互相取暖。', `MaleText_loc5`='在這麼偏遠的地方遇到人可真好啊。來吧，跟我一起。讓我們用身體互相取暖。', `MaleText_loc7`='Es maravilloso ver a otra persona en esta remota región del mundo. Ven, camina conmigo. Deja que nuestros cuerpos se den calor.' WHERE `ID`=9748;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장교 막사', `MaleText_loc4`='军官的休息室', `MaleText_loc5`='軍官的休息室', `MaleText_loc7`='Sala de los Oficiales', `FemaleText_loc1`='장교 막사', `FemaleText_loc4`='军官的休息室', `FemaleText_loc5`='軍官的休息室', `FemaleText_loc7`='Sala de los Oficiales' WHERE `ID`=9749;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘의 골짜기 서쪽 높은 곳을 찾아보게.', `MaleText_loc4`='去力量谷西边的山顶找找看。', `MaleText_loc5`='去力量谷西邊的山頂找找看。他們只會讓官員進去的!如果你不是官員，可以跟外面的巴沙中士談談。', `MaleText_loc7`='Búscala en la parte superior del lado oeste del Valle de la Fuerza.', `FemaleText_loc1`='힘의 골짜기 서쪽 높은 곳을 찾아보게.', `FemaleText_loc4`='去力量谷西边的山顶找找看。', `FemaleText_loc5`='去力量谷西邊的山頂找找看。他們只會讓官員進去的!如果你不是官員，可以跟外面的巴沙中士談談。', `FemaleText_loc7`='Búscala en la parte superior del lado oeste del Valle de la Fuerza..' WHERE `ID`=9750;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 파멸의 인도자 아토리우스라는 걸 알고 있다. 이 악마야! 참모습을 드러내고 내게 맞서라!', `MaleText_loc4`='我知道你是摧毁者阿托留斯。恶魔，现身吧！', `MaleText_loc5`='我知道你是『末日使者』阿托留斯。惡魔，現身吧!面對我!', `MaleText_loc7`='Te conozco como Artorius el Fatídico. ¡Muéstrate, demonio! ¡Enfréntate a mí!', `FemaleText_loc1`='네가 파멸의 인도자 아토리우스라는 걸 알고 있다. 이 악마야! 참모습을 드러내고 내게 맞서라!', `FemaleText_loc4`='我知道你是摧毁者阿托留斯。恶魔，现身吧！', `FemaleText_loc5`='我知道你是『末日使者』阿托留斯。惡魔，現身吧!面對我!', `FemaleText_loc7`='Te conozco como Artorius el Fatídico. ¡Muéstrate, demonio! ¡Enfréntate a mí!' WHERE `ID`=9751;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전설의 전당을 찾는군. 힘의 골짜기에서 서쪽으로 높은 곳에 있다네.', `MaleText_loc4`='你要去传说大厅？它就在西边的力量谷上边。', `MaleText_loc5`='你要去傳說大廳?它就在西邊的力量谷之上。如果你不是官員的話，你是不能進入傳說大廳的，但是你可以跟大廳外的巴沙談談。', `MaleText_loc7`='Tienes que ir a la Sala de las Leyendas. Está en la parte superior del Valle de la Fuerza, en el lado oeste.', `FemaleText_loc1`='전설의 전당을 찾는군. 힘의 골짜기에서 서쪽으로 높은 곳에 있다네.', `FemaleText_loc4`='你要去传说大厅？它就在西边的力量谷上边。', `FemaleText_loc5`='你要去傳說大廳?它就在西邊的力量谷之上。如果你不是官員的話，你是不能進入傳說大廳的，但是你可以跟大廳外的巴沙談談。', `FemaleText_loc7`='Tienes que ir a la Sala de las Leyendas. Está en la parte superior del Valle de la Fuerza, en el lado oeste.' WHERE `ID`=9752;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노움? 처량하군. 내게 맞서라, 이 악마야!', `MaleText_loc4`='侏儒？真可怜。面对我吧，恶魔！', `MaleText_loc5`='地精?真可憐。面對我吧，惡魔!', `MaleText_loc7`='¿Un gnomo? Qué patético. ¡Enfréntate a mí, demonio!', `FemaleText_loc1`='노움? 처량하군. 내게 맞서라, 이 악마야!', `FemaleText_loc4`='侏儒？真可怜。面对我吧，恶魔！', `FemaleText_loc5`='地精?真可憐。面對我吧，惡魔!', `FemaleText_loc7`='¿Un gnomo? Qué patético. ¡Enfréntate a mí, demonio!' WHERE `ID`=9753;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러니까 네가 바로 광기의 클린프랑이란 말이지? 이거 아쉽네... 난 또 제대로 된 적수 하나 만나보나 했지... 어디 진짜 모습으로 나와 맞서 보겠어?', `MaleText_loc4`='这么说你是疯狂的克林弗兰？真不幸，我所期望的是一次真正的挑战。你敢以真面目视人吗？', `MaleText_loc5`='這麼說你是瘋狂的克林弗蘭?真不幸，我所期望的是一次真正的挑戰。你敢以真面目視人嗎?', `MaleText_loc7`='¿Así que eres Klinfran el Enloquecido? Qué pena, esperaba un desafío. ¿Te atreves a enfrentarte a mí en tu forma verdadera?', `FemaleText_loc1`='그러니까 네가 바로 광기의 클린프랑이란 말이지? 이거 아쉽네... 난 또 제대로 된 적수 하나 만나보나 했지... 어디 진짜 모습으로 나와 맞서 보겠어?', `FemaleText_loc4`='这么说你是疯狂的克林弗兰？真不幸，我所期望的是一次真正的挑战。你敢以真面目视人吗？', `FemaleText_loc5`='這麼說你是瘋狂的克林弗蘭?真不幸，我所期望的是一次真正的挑戰。你敢以真面目視人嗎?', `FemaleText_loc7`='¿Así que eres Klinfran el Enloquecido? Qué pena, esperaba un desafío. ¿Te atreves a enfrentarte a mí en tu forma verdadera?' WHERE `ID`=9754;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 요부야... 그 요사스러운 변장에 속을 정도로 어리석은 내가 아니다. 이제 네가 죽을 때가 됐다.', `MaleText_loc4`='我可不会受你的魅惑。去死吧。', `MaleText_loc5`='我不會被你的偽裝給欺騙的，妖女。你的死期已到。', `MaleText_loc7`='No me engaña tu disfraz, tentadora. Ha llegado tu hora de morir.', `FemaleText_loc1`='이 요부야... 그 요사스러운 변장에 속을 정도로 어리석은 내가 아니다. 이제 네가 죽을 때가 됐다.', `FemaleText_loc4`='我可不会受你的魅惑。去死吧。', `FemaleText_loc5`='我不會被你的偽裝給欺騙的，妖女。你的死期已到。', `FemaleText_loc7`='No me engaña tu disfraz, tentadora. Ha llegado tu hora de morir.' WHERE `ID`=9755;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장교 막사', `MaleText_loc4`='军官的休息室', `MaleText_loc5`='軍官的休息室', `MaleText_loc7`='Sala de los Oficiales', `FemaleText_loc1`='장교 막사', `FemaleText_loc4`='军官的休息室', `FemaleText_loc5`='軍官的休息室', `FemaleText_loc7`='Sala de los Oficiales' WHERE `ID`=9756;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갑자기 ''얼라이언스의 수호자''라도 되기로 결심하신 겁니까?! 아무래도 구 시가지 안에 용사의 전당으로 가보셔야겠군요.', `MaleText_loc4`='突然之间，你成为了“联盟的保卫者”，是吗？！嗯，我猜你一定是想去勇士大厅。大厅就在旧城区。', `MaleText_loc5`='突然之間，你成為了「聯盟的防衛者」，是嗎?!嗯，我猜你一定是想去勇士大廳。它就在舊城區。', `MaleText_loc7`='¿Así que ahora, de pronto, eres $gun ''Defensor de la Alianza'':una ''Defensora de la Alianza'';? Bueno, supongo que querrás ir a la Sala de los Campeones. Está en el Casco Antiguo.', `FemaleText_loc1`='갑자기 ''얼라이언스의 수호자''라도 되기로 결심하신 겁니까?! 아무래도 구 시가지 안에 용사의 전당으로 가보셔야겠군요.', `FemaleText_loc4`='突然之间，你成为了“联盟的保卫者”，是吗？！嗯，我猜你一定是想去勇士大厅。大厅就在旧城区。', `FemaleText_loc5`='突然之間，你成為了「聯盟的防衛者」，是嗎?!嗯，我猜你一定是想去勇士大廳。它就在舊城區。', `FemaleText_loc7`='¿Así que ahora, de pronto, eres $gun ''Defensor de la Alianza'':una ''Defensora de la Alianza'';? Bueno, supongo que querrás ir a la Sala de los Campeones. Está en el Casco Antiguo.' WHERE `ID`=9757;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 진급이라도 하시는 모양인가요?! 용사의 전당으로 가보십시오. 구 시가지의 남동쪽 끝에서 찾을 수 있을 겁니다. 좋은 하루 되세요!', `MaleText_loc4`='在旧城区的东南角落，你可以找到勇士大厅。', `MaleText_loc5`='嗯，嗯，我們都生活在這個世界中，是嗎?在舊城區的東南角落，你可以找到勇士大廳。祝你好運!', `MaleText_loc7`='Bueno, bueno... ¿Ascendiendo en el mundo, eh? Estás buscando la Sala de los Campeones, y la encontrarás en la parte sureste del Casco Antiguo. ¡Buena suerte!', `FemaleText_loc1`='아, 진급이라도 하시는 모양인가요?! 용사의 전당으로 가보십시오. 구 시가지의 남동쪽 끝에서 찾을 수 있을 겁니다. 좋은 하루 되세요!', `FemaleText_loc4`='在旧城区的东南角落，你可以找到勇士大厅。', `FemaleText_loc5`='嗯，嗯，我們都生活在這個世界中，是嗎?在舊城區的東南角落，你可以找到勇士大廳。祝你好運!', `FemaleText_loc7`='Bueno, bueno... ¿Ascendiendo en el mundo, eh? Estás buscando la Sala de los Campeones, y la encontrarás en la parte sureste del Casco Antiguo. ¡Buena suerte!' WHERE `ID`=9758;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 당신의 어리석은 행동을 비웃습니다.', `FemaleText_loc4`='%s嘲笑你那愚蠢的请求。', `FemaleText_loc5`='%s嘲笑你那愚蠢的請求。', `FemaleText_loc7`='%s se ríe de tu estúpida petición.' WHERE `ID`=9759;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$c|1이여;여;, 정녕 원한다면 소원대로 해드리지요.', `FemaleText_loc4`='如你所愿，$c。', `FemaleText_loc5`='如你所願，$c。', `FemaleText_loc7`='Como desees, $c.' WHERE `ID`=9760;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='필멸의 생명체들아, 내가 바보로 보이느냐? 바보가 아니고서야 여기 남아서 네가 달고 온 수많은 친구를 상대로 싸우겠는가? 혹시 다음에는 또 모르지... 널 이렇게 희롱하는 날 홀로 막아 설 용기가 생긴다면 그때 날 찾아와라.', `FemaleText_loc4`='我看起来像个傻子吗，凡人？因为只有傻子才会留在这儿，跟你和你的盟友交战。或许下一次……你会有勇气收回嘲讽的话。', `FemaleText_loc5`='我看起來像個傻子嗎，凡人?因為只有傻子才會留在這兒，跟你和你的盟友交戰。或許下一次...你有勇氣收回嘲諷的話嗎。', `FemaleText_loc7`='¿Te parezco una imbécil, mortal? Porque solo un imbécil permanecería aquí para luchar contra ti y todos tus aliados. Quizás en otra ocasión... Si alguna vez encuentras en coraje para hacer lo que dices.' WHERE `ID`=9761;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 독침에 찔리자 조용히 합니다.', `FemaleText_loc4`='%s被毒针沉默了。', `FemaleText_loc5`='%s被毒針噤聲了。', `FemaleText_loc7`='%s se queda en silencio debido al tósigo.' WHERE `ID`=9762;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 엄청난 천둥소리와 함께 영혼의 구속에서 풀려납니다!', `MaleText_loc4`='%s在巨大的轰隆声中挣脱锁镣！', `MaleText_loc5`='%s在巨大的轟隆聲中掙脫鎖鐐!', `MaleText_loc7`='%s se libera de sus ataduras espectrales con un estruendoso estrépito.' WHERE `ID`=9763;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 살기를 띤 듯 흥분합니다!', `MaleText_loc4`='%s变得极为狂暴！', `MaleText_loc5`='%s變得極為狂暴!', `MaleText_loc7`='¡%s entra en un frenesí letal!' WHERE `ID`=9764;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벌써 의식이 시작됐어요!', `MaleText_loc4`='仪式正在进行中。', `MaleText_loc5`='儀式正在進行中。', `MaleText_loc7`='El ritual ha comenzado.' WHERE `ID`=9765;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 전 이 야수들 중에 절 맘에 들어 하는 녀석이 있기 전에 어서 자리를 떠나야겠어요!', `MaleText_loc4`='$n，我得在这些野兽吃掉我之前离开这儿！', `MaleText_loc5`='$n，我得在這些野獸吃掉我之前離開這兒!', `MaleText_loc7`='$n, me voy de aquí antes de que una de estas bestias se interese por mí.' WHERE `ID`=9766;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 다시 소로스로 빨려 들어갑니다!', `MaleText_loc4`='%s被拉回了克索诺斯世界！', `MaleText_loc5`='%s被拉回到克索諾斯那兒了!', `MaleText_loc7`='%s tiene que volver a Xoroth.' WHERE `ID`=9768;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 여기군! 시작해 볼까?', `MaleText_loc4`='啊，我们到了！让我们开始工作，好吗……？', `MaleText_loc5`='啊，我們到了!讓我們開始工作，好嗎...?', `MaleText_loc7`='¡Ah, aquí estamos! Bien, pongámonos manos a la obra, ¿de acuerdo?' WHERE `ID`=9769;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 맞아! 이번에는 이쪽에...', `MaleText_loc4`='哦，对！就在这儿……', `MaleText_loc5`='哦，對!就在這兒...', `MaleText_loc7`='Oh, sí. Ahora por aquí...' WHERE `ID`=9770;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 이제... 마지막으로!', `MaleText_loc4`='现在……最后一步！', `MaleText_loc5`='現在...最後一步!', `MaleText_loc7`='Y ahora... ¡El último paso!' WHERE `ID`=9771;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c 친구여, 함께 즐겨 봅시다', `MaleText_loc4`='我会满意的，$c。', `MaleText_loc5`='我會滿意的，$c。', `MaleText_loc7`='Me voy a divertir con esto, $c.' WHERE `ID`=9772;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 빛의 심판에 휩싸여 고통스러워합니다!', `MaleText_loc4`='%s在光明的审判降临时痛苦地后退！', `MaleText_loc5`='%s在聖光審判降臨時痛苦地後退!', `MaleText_loc7`='%s se retuerce de dolor mientras la Sentencia de Luz lo envuelve.' WHERE `ID`=9773;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 정의의 심판에 휩싸여 고통스러워합니다!', `MaleText_loc4`='%s在公正的审判降临时痛苦地后退！', `MaleText_loc5`='%s在公正審判降臨時痛苦地後退!', `MaleText_loc7`='%s se retuerce de dolor mientras la Sentencia de Justicia lo envuelve.' WHERE `ID`=9774;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 정의의 심판에 휩싸여 고통스러워합니다!', `MaleText_loc4`='%s在正义的审判降临时痛苦地后退！', `MaleText_loc5`='%s在正義審判降臨時痛苦地後退!', `MaleText_loc7`='%s se retuerce de dolor mientras la Sentencia de Rectitud lo envuelve.' WHERE `ID`=9775;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 따라오시오, 성기사 양반. 드워프 스타우트 맥주를 마시듯 빠르게 마갑을 완성해 주겠소. 음... 스타우트 맥주가 갑자기 먹고 싶은데...', `MaleText_loc4`='跟着我吧，圣骑士。我制造马饰比我喝矮人烈酒要快。嗯……烈酒。', `MaleText_loc5`='跟著我吧，聖騎士。我製造馬飾比我喝矮人烈酒要快。嗯...烈酒。', `MaleText_loc7`='Sígueme buen paladín. Tendré la gualdrapa lista en menos de lo que tardo en beberme una cerveza enana. Mmmm... Cerveza.' WHERE `ID`=9776;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 마갑 안에 룬무늬 옷감, 약초, 성수를 넣습니다.', `MaleText_loc4`='%s将符文布、草药和圣水装配成马饰。', `MaleText_loc5`='%s將符文布、草藥和聖水安置在戰馬上。', `MaleText_loc7`='%s mete el paño rúnico, las hierbas y el agua sagrada en la gualdrapa.' WHERE `ID`=9777;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 마갑 표면을 아케이나이트로 두릅니다.', `MaleText_loc4`='%s将奥金镶入马饰。', `MaleText_loc5`='%s將奧金鑲入戰馬護甲。', `MaleText_loc7`='%s mete la arcanita en la gualdrapa.' WHERE `ID`=9778;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성능에 만족할 것이오. 자, 오시오. 이제 가게로 돌아가서 거래를 마무리합시다!', `MaleText_loc4`='嗯，这能应该就行了。来吧，回到商店，完成我们的交易！', `MaleText_loc5`='嗯，這能應該就行了。來吧，回到商店，完成我們的交易!', `MaleText_loc7`='Ya está, esto deberá servir. ¡Venga, vamos a la tienda para terminar el trabajo!' WHERE `ID`=9779;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최고의 솜씨를 가진 장인을 찾아다닌 것이라면 제대로 오셨소!$B$B그리만트 엘모어라고 하오. 뭐든지 주문만 하시오!', `MaleText_loc4`='要是你是来找世界上最富经验的工匠，你就找对地方啦！$B$B格瑞曼德·艾尔默，愿为你效劳！', `MaleText_loc5`='如果你是來找世界上最富經驗的工匠，你就找對地方啦!$B$B格瑞曼德·艾爾默，願為你效勞!', `MaleText_loc7`='Si has venido a buscar la mejor artesanía de este o cualquier otro continente del mundo, entonces has venido al lugar adecuado.$B$B¡Grimand Elmore, a tu servicio!' WHERE `ID`=9780;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예언의 탐지기를 통해 빠져나온 %s|1이;가; 암흑 속에서 나타납니다!', `MaleText_loc4`='占卜师将%s从黑暗中拽了出来！', `MaleText_loc5`='%s從黑暗中現身，被占卜者的預言所吸引!', `MaleText_loc7`='%s emerge de la oscuridad, siguiendo el cristal de adivinación.' WHERE `ID`=9781;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 나에게 도전을? 끝없는 공포가 무엇인지 가르쳐주마.', `MaleText_loc4`='你敢向我挑战？准备面对无尽的恐惧吧。', `MaleText_loc5`='你敢向我挑戰?準備面對無盡的恐懼吧。', `MaleText_loc7`='¿Osas desafiarme? Prepárate para una eternidad de terror.' WHERE `ID`=9782;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 비겁한 전술을 알아차린 %s|1이;가; 전투에서 도망칩니다.', `MaleText_loc4`='%s觉察到你那畏头畏尾的战争策略，从战场上仓惶逃走了。', `MaleText_loc5`='%s在明白你懦弱的戰爭策略後從戰場上逃跑了。', `MaleText_loc7`='%s se percata de tus cobardes tácticas de combate y huye de la batalla.' WHERE `ID`=9783;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만하면 충분하다! 이제 내게 맞서라! 너희들도 내 해골 진열장에 넣어주마!', `MaleText_loc4`='够了——结束吧！你们这些蠢货的骨头也将成为我的收藏品！', `MaleText_loc5`='夠了─結束吧!面對我!', `MaleText_loc7`='¡YA ESTÁ BIEN! ¡Esto se va a acabar aquí y ahora! ¡Imbéciles, pasaréis a formar parte de mi colección de huesos!' WHERE `ID`=9784;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 몸을 움직일 수 없습니다.', `MaleText_loc4`='%s被固定了。', `MaleText_loc5`='%s被定身了。', `MaleText_loc7`='%s no se puede mover.' WHERE `ID`=9785;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 치명적으로 중독되어 괴로워합니다.', `MaleText_loc4`='%s饮下了剧毒的毒药。', `MaleText_loc5`='%s被劇毒所侵襲。', `MaleText_loc7`='Un veneno virulento abate a %s.' WHERE `ID`=9786;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='약한 자여, 그대의 영혼은 내가 접수하겠다.', `MaleText_loc4`='软弱的家伙，你的灵魂是我的了。', `MaleText_loc5`='軟弱的傢伙，你的靈魂是我的了。', `MaleText_loc7`='Tu alma me pertenece, alfeñique.' WHERE `ID`=9787;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공포마를 소환하려면 먼저 대소환진을 만들어야 합니다. 소로스로 가는 차원문을 그 안에서만 열 수 있기 때문이지요.$B$B대소환진을 만들려면 세 가지 강력한 도구가 필요합니다. 데스무라의 종, 어둠의 물레, 심판의 양초가 바로 그것입니다.', `MaleText_loc4`='要召唤恐惧战马，你必须首先开启一道强大的法阵。通往克索诺斯世界的传送门只可能在这种法阵中打开。$B$B而开启法阵，你就需要三种魔法器具：达斯莫拉的铃铛、黑色战车之轮和末日蜡烛。', `MaleText_loc5`='要召喚恐懼戰馬，你必須首先製造出強力召喚法陣。恐懼戰馬只可能在法陣中生成。$B$B要製造強力召喚法陣需要三種器具:達斯莫拉之鈴鐺、黑暗戰車之輪和末日蠟燭。', `MaleText_loc7`='Para invocar a un corcel nefasto, primero debes crear un Círculo de invocación superior. Solo es posible crear un portal a Xoroth a partir de ese círculo.$B$BPara formar el Círculo de invocación superior necesitas tres poderosos objetos: una Campana de Dethmoora, una Rueda de la Marcha Negra y una Vela del día del Juicio Final.' WHERE `ID`=9788;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비가 다 됐군요. 지금 그대와 그대의 공포마 앞에 놓인 일은 대소환진과 공포마의 영혼을 봉인하기 위한 의식입니다.', `MaleText_loc4`='你的准备工作已经完成了。现在挡在你和你的恐惧战马之间的就只有开启强力召唤法阵、束缚恐惧战马灵魂的仪式。', `MaleText_loc5`='你的準備工作完成啦。現在你和你的恐懼戰馬之間的阻礙只剩下強力召喚法陣的儀式，以及恐懼戰馬的約束。', `MaleText_loc7`='Los preparativos están acabados. Lo único que te falta para conseguir al corcel nefasto es el ritual del Círculo de invocación superior y la vinculación del espíritu del corcel nefasto...' WHERE `ID`=9789;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고르지키가 그대가 데스무라의 종, 어둠의 물레, 심판의 양초에 필요한 것을 모두 가져다주었다고 하더군요.$B$B잘하셨습니다, $n! 공포마를 잡기 위한 의식을 치를 준비가 다 된 것 같군요!', `MaleText_loc4`='戈瑟奇告诉我说你带来了他需要的所有东西：达斯莫拉的铃铛、黑色战车之轮和末日蜡烛。$B$B干得好，$n！你差不多可以执行仪式，拥有一匹恐惧战马了！', `MaleText_loc5`='戈瑟奇告訴我說你帶來了他需要的所有東西:達斯莫拉之鈴鐺、黑暗戰車之輪和末日蠟燭。$B$B做得好，$n!你差不多可以執行儀式，擁有一匹恐懼戰馬啦!', `MaleText_loc7`='Gorzeeki me dice que le has traído todo lo necesario para la Campana de Dethmoora, la Rueda de la Marcha Negra y la Vela del día del Juicio Final.$B$B¡Bien hecho, $n! ¡Casi estás $glisto:lista; para realizar el ritual y vincular a un corcel nefasto!' WHERE `ID`=9790;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑습니다, $n. 마력적이고 신비한 곳을 탐험한다고 하던데 잘 되고 있습니까? 최근에 밝혀낸 마법의 흑막이라도 있나요?', `MaleText_loc4`='你好，$n。你对魔法的研究进展得怎么样啦？你解开了黑暗的秘密了吗？', `MaleText_loc5`='你好，$n。你對魔法的研究進展得怎麼樣啦?你解開了黑暗的秘密了嗎?', `MaleText_loc7`='Hola, $n. ¿Qué tal va tu investigación de las artes demoníacas y Arcanas? ¿Has descubierto algún oscuro secreto últimamente?' WHERE `ID`=9791;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='메리데스, 맛좋은 만나 사료를 좀 더 받을 수 있을까요?', `MaleText_loc4`='梅丽德丝，请问我能再要一些魔法粮草吗？', `MaleText_loc5`='梅麗德絲，請問我能再要一些魔法糧草嗎?', `MaleText_loc7`='Merideth, ¿podrías darme más comida para caballos enriquecida con maná, por favor?', `FemaleText_loc1`='메리데스, 맛좋은 만나 사료를 좀 더 받을 수 있을까요?', `FemaleText_loc4`='梅丽德丝，请问我能再要一些魔法粮草吗？', `FemaleText_loc5`='梅麗德絲，請問我能再要一些魔法糧草嗎?', `FemaleText_loc7`='Merideth, ¿podrías darme más comida para caballos enriquecida con maná, por favor?' WHERE `ID`=9792;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 가죽을 빛내며 주춤 물러섭니다.', `MaleText_loc4`='%s的皮肤闪着微光，它畏缩了。', `MaleText_loc5`='%s因皮膚閃著微光而驚訝退縮。', `MaleText_loc7`='%s se estremece mientras su piel empieza a brillar.' WHERE `ID`=9793;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아! 영웅들... 아주 끈질긴 족속이지. 바로 이곳에서 너희 동료가 내게 도전했다가 그 대가를 치렀다. 이제 녀석은 날 섬기지.', `MaleText_loc4`='啊……英雄们。你们都会坚持不懈的，是不是？你们这群凡人想要与我的力量相抗衡——那么你们就要付出代价。现在他将为我而战……他的任务就是干掉你们。', `MaleText_loc5`='啊...英雄們。你們都會堅持不懈的，是不是?你們這群人想要與我的力量相抗衡─然後就會付出代價。現在他就將為我服務...他的任務就是幹掉你。', `MaleText_loc7`='Ah... Los héroes. Son obstinados, ¿no? Su aliado ha intentado enfrentar su poder contra el mío y pagó por ello. Ahora él me servirá... y los descuartizará. ¡Levántate dragoncito rojo... y destrúyelos!' WHERE `ID`=9794;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아! 투기장에서 사람들이 죽을 때까지 싸우는 것을 보는 것보다 좋은 건 없지. 자네가 제때에 여기 있다면 아마도 그중 하나가 될 수 있을 거라고!', `MaleText_loc4`='啊！没有比看人们在竞技场中互相厮杀更好看的东西了。如果你来得是时候的话，那你也将是他们中的一员！', `MaleText_loc5`='啊!沒有比看人們在競技場中互相廝殺更好看的東西了。如果你來得是時候的話，那你也將是他們中的一員!', `MaleText_loc7`='¡Arr! Nada gustarme más que tipos luchando a muerte en la arena. Si estar aquí en el momento justo, quizás poder ser uno de ellos.' WHERE `ID`=9795;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 방해하지 말라고.', `MaleText_loc4`='不要打断我。', `MaleText_loc5`='不要打斷我。', `MaleText_loc7`='No me interrumpas.' WHERE `ID`=9796;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타일이 미끄러워 넘어집니다.', `MaleText_loc4`='光滑的地面让你无法站稳。', `MaleText_loc5`='滑溜的地磚害你無法站穩。', `MaleText_loc7`='Una baldosa resbaladiza hace que pierdas el equilibrio.' WHERE `ID`=9797;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 맞아. 나는 장님이나 다름없지! 또 그... 뭐냐... 어쨌든 뭣처럼 취했다고.$B$B한 가지 알려 주지, $c. 내 감각이 날카로운 건 술 덕분이라고. 한 가지 감각을 잃으면 나머지 감각들이 더 날카로워진다는 건 상식이라니까. 내 취각이 요즘 들어 아주 기막히게 좋아졌어.', `MaleText_loc4`='是的，那是真的，我好像一只蝙蝠一样瞎了！而且还醉得……呃，醉得好像喝了很多酒。$B$B我会告诉这个感受的，$r。是酒让我感觉灵敏。人人都知道如果你丧失了一种感觉，那么另外一个感觉会变得更加灵敏。我的饮酒感觉这两天非常灵敏。', `MaleText_loc5`='是啊，那倒是真的，我瞎得跟蝙蝠一樣!而且還醉得...呃，醉得好像喝了很多酒。$B$B其實啊，$r，我跟你說，就是酒精讓我感覺更敏銳的。大家都知道，只要你喪失了一種感覺，那麼其他的感覺就會變得更加敏銳。這兩天啊，我的酒醉感尤其超厲害的!', `MaleText_loc7`='Sssí, ess verdad. ¡Toy tan ciego como un murciélago! Y borrrracho como... Ehhh, borrrracho como algo que ssse emborrrracha.$B$BTe diré algo, $r. La bebida mantiene misss sssentidosss alerta. To’l mundo sssabe que cuando pierdesss un sssentido, losss otrosss sssentidosss tán másss alerta. Mi sssentido de la bebida esss increíble últimamente.' WHERE `ID`=9798;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='베개! 누가 우리 베개를 훔쳐 갔어!', `MaleText_loc4`='有人偷走了我们的东西！', `MaleText_loc5`='我們的枕頭!有人偷了我們的枕頭!', `MaleText_loc7`='¡Nuestras almohadas! ¡Alguien ha robado nuestras almohadas!', `FemaleText_loc1`='베개! 누가 우리 베개를 훔쳐 갔어!', `FemaleText_loc4`='有人偷走了我们的东西！', `FemaleText_loc5`='我們的枕頭!有人偷了我們的枕頭!', `FemaleText_loc7`='¡Nuestras almohadas! ¡Alguien ha robado nuestras almohadas!' WHERE `ID`=9799;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 발칙한 짓은 반드시 응징해야 한다고!', `MaleText_loc4`='我们不会让这种疯狂行为不受到惩罚的！', `MaleText_loc5`='我們不會讓這種瘋狂行為不受到懲罰的!', `MaleText_loc7`='¡No permitiremos que este acto de locura quede impune!', `FemaleText_loc1`='이런 발칙한 짓은 반드시 응징해야 한다고!', `FemaleText_loc4`='我们不会让这种疯狂行为不受到惩罚的！', `FemaleText_loc5`='我們不會讓這種瘋狂行為不受到懲罰的!', `FemaleText_loc7`='¡No permitiremos que este acto de locura quede impune!' WHERE `ID`=9800;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 호드 깃발 쟁탈에 성공했습니다!', `MaleText_loc4`='$n获得了部落军旗！', `MaleText_loc5`='$n奪取了部落的旗幟!', `MaleText_loc7`='¡$n ha capturado la bandera de la Horda!' WHERE `ID`=9801;
