UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 얼라이언스 깃발을 떨어뜨렸습니다!', `MaleText_loc4`='联盟的旗帜被$n丢掉了！', `MaleText_loc5`='聯盟的旗幟被$n丟掉了!', `MaleText_loc7`='¡$n ha dejado caer la bandera de la Alianza!' WHERE `ID`=9805;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 호드 깃발을 떨어뜨렸습니다!', `MaleText_loc4`='$n掉落了部落军旗！', `MaleText_loc5`='部落的旗幟被$n丟掉了!', `MaleText_loc7`='¡$n ha dejado caer la bandera de la Horda!' WHERE `ID`=9806;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 호드 깃발을 손에 넣었습니다!', `MaleText_loc4`='$n拾起了部落军旗！', `MaleText_loc5`='部落的旗幟被$n拔起了!', `MaleText_loc7`='¡$n ha tomado la bandera de la Horda!' WHERE `ID`=9807;
