UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 호드 깃발을 되찾았습니다!', `MaleText_loc4`='$n将部落军旗放回到旗座上了！', `MaleText_loc5`='部落的旗幟被$n歸還到它的基地了!', `MaleText_loc7`='¡$n ha devuelto la bandera de la Horda a su base!' WHERE `ID`=9809;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='도둑! 깡패! 악당! 와서 내 거대한 베개와 맞서봐라!', `FemaleText_loc4`='小偷！无赖！恶棍！来尝尝我的大枕头的滋味吧！', `FemaleText_loc5`='竊賊!無賴!惡棍!來嘗嘗我巨大枕頭的利害吧!', `FemaleText_loc7`='¡Ladrones! ¡Pillos! ¡Tunantes! ¡Venid, devolvedme mis almohadas gigantescas!' WHERE `ID`=9810;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리는 세계를 착취... 아... 아니... 그러니까 탐험하고자 검은바위 나락의 보호와 안락함을 떠나기로 했답니다.', `FemaleText_loc4`='我们选择了离开黑石深渊的保护出来探险……呃，我是说……嗯，我们这么做是对的，我们要探索整个世界。', `FemaleText_loc5`='我們選擇了離開黑石深淵的保護和安居之所來進行探險...呃，我是說...嗯，我們這麼做是對的，我們要探索整個世界。', `FemaleText_loc7`='Hemos elegido abandonar la protección y el confort de las Profundidades... Ehh... Mmm... Sí, eso, para EXPLORAR el mundo.' WHERE `ID`=9811;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바보가 아니라면 도망쳐라! 어쨌든 너희 목숨은 이미 끝난 것이지만!', `MaleText_loc4`='你们的末日已经来了！', `MaleText_loc5`='如果你是個傻瓜的話就快跑吧! 你的命運已經被封印了!', `MaleText_loc7`='¡Corran si quieren, idiotas! ¡Su destino está escrito!' WHERE `ID`=9812;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 두 다리가 달릴 수 있을 때 도망쳐라, 필멸의 생명체들이여!', `MaleText_loc4`='凡人，趁现在还有机会，赶快逃跑吧！', `MaleText_loc5`='凡人，趁現在快點逃跑吧!', `MaleText_loc7`='¡Huye mientras puedas, mortal!' WHERE `ID`=9813;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일반 텍스트', `MaleText_loc4`='Generic Text', `MaleText_loc5`='Generic Text', `MaleText_loc7`='Texto genérico', `FemaleText_loc1`='일반 텍스트', `FemaleText_loc4`='Generic Text', `FemaleText_loc5`='Generic Text', `FemaleText_loc7`='¡Texto genérico!' WHERE `ID`=9814;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 전투에 끝까지 남아 있는 놈이 멍청한 거지. 잘 있어라, 겁쟁이...', `MaleText_loc4`='只有傻瓜还会继续战斗。再见了，懦夫。', `MaleText_loc5`='只有傻瓜還會繼續戰鬥。再見了，懦夫。', `MaleText_loc7`='Solo un imbécil se quedaría en esta batalla. Adiós, cobarde.', `FemaleText_loc1`='이 전투에 끝까지 남아 있는 놈이 멍청한 거지. 잘 있어라, 겁쟁이...', `FemaleText_loc4`='只有傻瓜还会继续战斗。再见了，懦夫。', `FemaleText_loc5`='只有傻瓜還會繼續戰鬥。再見了，懦夫。', `FemaleText_loc7`='Solo un imbécil se quedaría en esta batalla. Adiós, cobarde.' WHERE `ID`=9815;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기요! 지나가던 여행자님! 이리 오셔서 돈 좀 벌어 가시죠!', `MaleText_loc4`='嗨，你！旅行者！到这里来挣些钱吧！', `MaleText_loc5`='喂，你!不知哪來的旅行者!來這碰碰運氣，贏些金幣!', `MaleText_loc7`='¡Eh tú! ¡Viajero cualquiera! ¡Entra aquí y gástate unos cuartos!' WHERE `ID`=9816;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐, 재미있는 거라도 파십니까, 조르빈?', `MaleText_loc4`='有没有什么好玩的东西卖，索尔宾？', `MaleText_loc5`='有沒有什麼有趣的可以賣的，索爾賓?', `MaleText_loc7`='¿Tienes algo interesante a la venta, Zorbin?', `FemaleText_loc1`='뭐, 재미있는 거라도 파시나요, 조르빈?', `FemaleText_loc4`='有没有什么好玩的东西卖，索尔宾？', `FemaleText_loc5`='有沒有什麼有趣的可以賣的，索爾賓?', `FemaleText_loc7`='¿Tienes algo interesante a la venta, Zorbin?' WHERE `ID`=9817;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물건을 보여주십시오.', `MaleText_loc4`='我想要看看你的货物。', `MaleText_loc5`='我想要看看你的貨物。', `MaleText_loc7`='Me gustaría echar un vistazo a tus mercancías.', `FemaleText_loc1`='물건을 보여주십시오.', `FemaleText_loc4`='我想要看看你的货物。', `FemaleText_loc5`='我想要看看你的貨物。', `FemaleText_loc7`='Me gustaría echar un vistazo a tus mercancías.' WHERE `ID`=9818;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 대장장이인 버니네이트라네. 어... 그리고... 약간의 음식과 음료 등을 파는 일을 부업으로 하고 있지. 고기 좀 들지 않겠나?', `MaleText_loc4`='博恩奈特是我的名字，我把铁匠作为我的兴趣……另外，呃……我还卖一些食物和水。来点肉类怎么样？', `MaleText_loc5`='博恩奈特是我的名字，我把鐵匠作為我的興趣...另外，呃...我還賣一些食物和水。來點肉類怎麼樣?', `MaleText_loc7`='Burninate es mi nombre, la herrería, mi juego favorito... Y, eeeh... Vendo algo de comida y agua. ¿Te apetece carne?' WHERE `ID`=9819;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 만나 반갑습니다, $n! 제가 얼마나 더 오랫동안 이런 외딴 곳에 작업장을 세우려는 작업을 계속해 나갈지는 모르겠습니다. 그래도 전에 도와 주신 적이 있으니 관심을 가지실 만한 물건을 좀 보여 드리죠!', `MaleText_loc4`='很高兴再见到你，$n！我不知道我还可以坚持多久来创建这样一个店。现在，由于你对我的帮助，我会给你看一些你会感兴趣的东西！', `MaleText_loc5`='很高興再見到你，$n!我不知道我還可以堅持多久來創建這樣一個店。現在，由於你對我的幫助，我會給你看一些你會感興趣的東西!', `MaleText_loc7`='¡Hola de nuevo, $n! No sé cuánto tiempo más voy a seguir intentando establecer una tienda aquí, en medio de ninguna parte. De todas formas, como me ayudaste en el pasado, te enseñaré un par de cosas que quizás te parezcan interesantes.' WHERE `ID`=9820;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='롤로가 자신의 소중한 에일 맥주를 흘리거나 옷을 더럽히고 싶어하지 않을 때면 내가 등장하지. 암, 그렇고 말고. 정의를 실현하고 누군가를 응징해야 할 때는 이 노병 한셀을 부른다네.', `MaleText_loc4`='当洛洛尔不想撒掉他宝贵的酒或者弄脏他衣服的时候，我就被召唤而来。是的。汉瑟尔就是别人口中正义和痛苦的结合体。', `MaleText_loc5`='當洛洛爾不想撒掉他寶貴的麥芽酒或者弄髒他衣服的時候，我就被召喚而來。是的。漢瑟爾就是別人口中正義和痛苦的結合體。', `MaleText_loc7`='Cuando Lolo no quiere derramar ná de su valiosa cerveza o mancharse el vestidito, me llama. Sip. El viejo Hansel es el enano al que usan pa administrar algo de justicia y mucho dolor.' WHERE `ID`=9821;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰파이크 사령관이 쓰러졌으니 이제 겨울도끼 요새를 방어할 부대를 보낼 수 있겠군. 하지만 얼라이언스 녀석들은 반드시 돌아올 테니 잠시도 방심해선 안 돼!$B$B주위에 살금살금 돌아다니는 녀석들이 눈의 띄거든 또 혼을 내 주라고!', `MaleText_loc4`='现在雷矛部族的将军被击败了，我们可以派出一些军队来驻守冰斧要塞。但是我们还是要保持警惕，$c，联盟会回来的。$B$B当你在周围看到他们在偷偷摸摸活动的时候，好好教训他们一下吧！', `MaleText_loc5`='現在雷矛將軍被擊敗了，我們可以派出一些軍隊來駐守冰斧要塞。但是我們還是要保持警惕，$c，聯盟會回來的。$B$B當你在周圍看到他們在偷偷摸摸活動的時候，好好教訓他們一下吧!', `MaleText_loc7`='Ahora que el general Pico Tormenta ha sido derrotado, podemos prescindir de algunas tropas para que protejan el Fuerte Hacha Invernal. Pero siempre debemos estar atentos, $c, porque la Alianza volverá.$B$BCuando les encuentres merodeando por ahí, ¡enséñales otra lección!', `FemaleText_loc1`='스톰파이크 사령관이 쓰러졌으니 이제 겨울도끼 요새를 방어할 부대를 보낼 수 있겠군. 하지만 얼라이언스 녀석들은 반드시 돌아올 테니 잠시도 방심해선 안 돼!$B$B주위에 살금살금 돌아다니는 녀석들이 눈의 띄거든 또 혼을 내 주라고!', `FemaleText_loc4`='现在雷矛部族的将军被击败了，我们可以派出一些军队来驻守冰斧要塞。但是我们还是要保持警惕，$c，联盟会回来的。$B$B当你在周围看到他们在偷偷摸摸活动的时候，好好教训他们一下吧！', `FemaleText_loc5`='現在雷矛將軍被擊敗了，我們可以派出一些軍隊來駐守冰斧要塞。但是我們還是要保持警惕，$c，聯盟會回來的。$B$B當你在周圍看到他們在偷偷摸摸活動的時候，好好教訓他們一下吧!', `FemaleText_loc7`='Ahora que el general Pico Tormenta ha sido derrotado, podemos prescindir de algunas tropas para que protejan el Fuerte Hacha Invernal. Pero siempre debemos estar atentos, $c, porque la Alianza volverá.$B$BCuando les encuentres merodeando por ahí, ¡enséñales otra lección!' WHERE `ID`=9822;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='서리늑대 사령관을 쓰러뜨렸으니 이제 부대를 보내 겨울도끼 요새 입구를 지킬 수 있겠군요.$B$B하지만 경계를 늦추지 마세요! 늘 호드 침입자들에 대한 경계 태세를 늦춰선 안 돼요.', `FemaleText_loc4`='现在霜狼氏族的将军被击败了，我们可以派出一些军队来驻守冰斧要塞。$B$B但是我们还是要保持警惕！我们要小心那些部落的入侵者……', `FemaleText_loc5`='現在霜狼部族的將軍被擊敗了，我們可以派出一些軍隊來駐守冰斧要塞。$B$B但是我們還是要保持警惕!我們要小心那些部落的入侵者...', `FemaleText_loc7`='Ahora que el general Lobo Gélido ha sido derrotado, podemos prescindir de algunas tropas para que protejan la entrada del Fuerte Hacha Invernal.$B$B¡Pero permaneced alerta! Siempre tenemos que estar atentos por si aparecen intrusos de la Horda...' WHERE `ID`=9823;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳의 현역 작업반장으로서 이곳에서 일어나는 모든 형태의 사업, 노동, 휴식, 그리고 휴식에 일정 수준의 지루함이 포함되도록 하는 게 내 임무라네.$B$B자네에게 부탁한 일이 너무 쉽고 간단하다고 생각되면 즉시 내게 보고하라고.', `MaleText_loc4`='作为驻扎在这里的工头，我的职责就是确保在这里所进行的所有事情，从工作到休息和放松都包含着一定的令人厌烦的成分。$B$B如果你发现某件你被要求去做的事情过于简单或者没有什么好抱怨的话，请立即向我报告。', `MaleText_loc5`='作為駐紮在這裡的現任監工，我的職責就是確保在這裡所進行的所有事情，工作，休息和放鬆都包含一定令人厭煩的成分。$B$B如果你發現某件你被要求做的事情過於簡單或者沒有什麼好抱怨的話，請立即向我報告。', `MaleText_loc7`='Como capataz de este lugar, mi deber es asegurarme de que hay cierto nivel de tedio en todas las formas de negocio, trabajo, descanso y relajación que ocurren aquí.$B$BSi algo que te manden hacer te parece demasiado fácil y sin complicaciones, ven a hablar conmigo inmediatamente.' WHERE `ID`=9824;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 부탁한 일을 모두 끝냈으니 정말 이곳에서는 더 이상 자네에게 맡길 일이 없네. 토륨 대장조합의 요원으로 계속 일할 의향이 있으면, 검은바위 나락에 있는 험상궂은 주정뱅이 선술집에서 로크토스 다크바게이너와 얘기해 보게나.$B$B살펴가게!', `MaleText_loc4`='你已经完成我要求你做的事情，$n。我这里没有什么需要你做的了。如果你想继续为瑟银兄弟会服务的话，和黑石深渊的黑铁酒吧的罗克图斯·暗契谈谈。$B$B再见！', `MaleText_loc5`='你已經完成我要求你做的事情，$n。我這裡沒有什麼需要你做的了。如果你想繼續為瑟銀兄弟會服務的話，和黑石深淵的黑鐵酒吧的羅克圖斯·暗契談談。$B$B再見!', `MaleText_loc7`='Has hecho todo lo que te he pedido, $n. Ya no puedes hacer nada más. Si te interesa continuar tu carrera como agente de la Hermandad del Torio, habla con Lokhtos Tratoscuro en la Tragapenas, en las Profundidades de Roca Negra.$B$B¡Adiós!' WHERE `ID`=9825;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말이지... 퀸티스가 한 번만 더 내 옷 속에 낚시용 땅벌레를 집어넣으려고 하면 날이 시퍼런 이 검으로 거길 잘라 버릴 겁니다.', `MaleText_loc4`='我发誓……如果奎恩提斯胆敢再乱栽食虫花，我就马上把他的树给砍了。', `MaleText_loc5`='我發誓...如果奎恩特膽敢再把一個飛蟲放在我這裡的話，我會立即去用鋒利的劍把他的樹給砍了。', `MaleText_loc7`='Te lo juro... Si Quint intenta colocarme un cebo de peces más, ¡voy a cargarme a golpetazos este árbol con mi espada no tan oxidada!' WHERE `ID`=9826;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='조심하라! $n|1이라는;라는; $r|1이;가; 겨울도끼 요새에서 우리를 공격한다!', `FemaleText_loc4`='小心！$r$n正在攻击冰斧要塞！', `FemaleText_loc5`='小心!$r的$n正在攻擊冰斧要塞!', `FemaleText_loc7`='¡Cuidado! ¡$gEl:La; $r $n nos ataca en el Fuerte Hacha Invernal!' WHERE `ID`=9827;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='토륨 대장조합이든 아니든, 검은무쇠 드워프 녀석들이 가까이 오기만 하면 내 곡괭이로 혼내 줄 거예요! 어머, 제가 말이 많았네요. 자, 어디로 보내 드릴까요?', `FemaleText_loc4`='不管我是不是瑟银兄弟会的，只要有个黑铁矮人敢靠近我，我一定会让他们尝尝我的厉害！现在，你想去哪里呢，$g小伙子:小姑娘;？', `FemaleText_loc5`='不管我是不是瑟銀兄弟會的，只要有個黑鐵矮人敢靠近我，我一定會讓他們嘗嘗我錘頭的厲害!現在，我可以送你去哪裡，$g小夥子:小姑娘;?', `FemaleText_loc7`='Hermandad del Torio o no, si uno de los Hierro Negro se acerca a mí, ¡probará mi azadón justo en su cabeza! Y bien, ¿dónde puedo enviarte, $gmuchacho: muchacha;?' WHERE `ID`=9828;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야생 가죽 장화 만드는 법을 다시 가르쳐 줄 수 있습니까?', `MaleText_loc4`='嘿，普拉特——你能再教我一下如何制作蛮皮战靴吗？', `MaleText_loc5`='嘿，普拉特─你能再教我一下如何製作蠻皮長靴嗎?', `MaleText_loc7`='Eh, Pratt, ¿puedes enseñarme de nuevo a hacer unas botas de cuero salvaje?', `FemaleText_loc1`='야생 가죽 장화 만드는 법을 다시 가르쳐 줄 수 있습니까?', `FemaleText_loc4`='嘿，普拉特——你能再教我一下如何制作蛮皮战靴吗？', `FemaleText_loc5`='嘿，普拉特─你能再教我一下如何製作蠻皮長靴嗎?', `FemaleText_loc7`='Eh, Pratt, ¿puedes enseñarme de nuevo a hacer unas botas de cuero salvaje?' WHERE `ID`=9829;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야생 가죽 망토 만드는 법을 다시 가르쳐 줄 수 있습니까?', `MaleText_loc4`='嘿，普拉特——你能再教我一下如何制作蛮皮披风吗？', `MaleText_loc5`='嘿，普拉特─你能再教我一下如何製作蠻皮披風嗎?', `MaleText_loc7`='Eh, Pratt, ¿puedes enseñarme de nuevo a hacer una capa de cuero salvaje?', `FemaleText_loc1`='야생 가죽 망토 만드는 법을 다시 가르쳐 줄 수 있습니까?', `FemaleText_loc4`='嘿，普拉特——你能再教我一下如何制作蛮皮披风吗？', `FemaleText_loc5`='嘿，普拉特─你能再教我一下如何製作蠻皮披風嗎?', `FemaleText_loc7`='Eh, Pratt, ¿puedes enseñarme de nuevo a hacer una capa de cuero salvaje?' WHERE `ID`=9830;
