UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야생 가죽 조끼 만드는 법을 다시 가르쳐 줄 수 있습니까?', `MaleText_loc4`='嘿，杉多尔——你能再教我一下如何制作蛮皮外衣吗？', `MaleText_loc5`='嘿，杉多爾─你能再教我一下如何製作蠻皮外衣嗎?', `MaleText_loc7`='Eh, Jangdor, ¿puedes enseñarme de nuevo a hacer un jubón de cuero salvaje?', `FemaleText_loc1`='야생 가죽 조끼 만드는 법을 다시 가르쳐 줄 수 있습니까?', `FemaleText_loc4`='嘿，杉多尔——你能再教我一下如何制作蛮皮外衣吗？', `FemaleText_loc5`='嘿，杉多爾─你能再教我一下如何製作蠻皮外衣嗎?', `FemaleText_loc7`='Eh, Jangdor, ¿puedes enseñarme de nuevo a hacer un jubón de cuero salvaje?' WHERE `ID`=9840;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저 드워프들이 저쪽에서만 지낸다면 문제는 없을 거야. 그런데 어디로 가려는가, $n?', `FemaleText_loc4`='只要那些矮人一直待在那里，我们就不会有麻烦。你现在要去哪里，$n？', `FemaleText_loc5`='只要那些矮人一直待在那裡，我們就不會有麻煩。你現在要去哪裡，$n?', `FemaleText_loc7`='Mientras esos enanos se queden ahí, no tendremos problemas. ¿Dónde te diriges, $n?' WHERE `ID`=9841;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드가 승리했습니다!', `MaleText_loc4`='部落胜利了！', `MaleText_loc5`='部落勝利了!', `MaleText_loc7`='¡La Horda gana!' WHERE `ID`=9842;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스가 승리했습니다!', `MaleText_loc4`='联盟获胜！', `MaleText_loc5`='聯盟勝利了!', `MaleText_loc7`='¡La Alianza gana!' WHERE `ID`=9843;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일어나라! 붉은고룡이여... 놈들을 처치하라!', `MaleText_loc4`='醒来吧，小红龙……毁灭他们！', `MaleText_loc5`='升空吧，小紅雙足龍...毀滅他們!', `MaleText_loc7`='Levántate, dragoncito rojo... ¡Y destrúyelos!' WHERE `ID`=9844;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흐흐흐흐... 게임을 시작하자!', `MaleText_loc4`='比赛现在开始！', `MaleText_loc5`='讓賽事開始吧!', `MaleText_loc7`='¡Que comiencen los juegos!' WHERE `ID`=9845;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강력한 $n의 군대 앞에 내가 두려워 움츠러들기라도 할 줄 알았더냐?$B$B넌 나에게 하찮은 존재일 뿐이다. 아니, 그 이하지.$B$B너도 모든 평범한 생명체들이 저지르는 것과 똑같은 실수를 저지른 것이니라.$B$B<한숨을 쉬는 군주 빅터 네파리우스>$B$B시간은 시간을 돈의 형태로 사용하는 자들에게 이상한 짓을 저지르지.', `MaleText_loc4`='你是不是想要我在强大的$n所率领的军团之前畏缩？$B$B你对我来说不算什么。什么都不是。取你的性命对我来说是易如反掌的事情。$B$B你犯了所有凡人都会犯的错误。$B$B<维克多·奈法里奥斯叹了口气。>$B$B如果你像花钱一样花费你的时间，那就会发生一些奇怪的事情。', `MaleText_loc5`='你是不是想要我在萬能的$n之前畏縮?$B$B你對我不算什麼。什麼都不是。如果我想要你的頭顱，那它就會被插在長矛上呈送給我。$B$B你犯了所有凡人都會犯的錯誤。$B$B<維克多·奈法利斯領主歎了口氣。>$B$B如果你像花錢一樣花費你的時間，那就會發生一些奇怪的事情。', `MaleText_loc7`='¿Esperas que me encoja de miedo ante la poderosa legión de $n?$B$BNo eres nada para mí. Menos de nada. Si hubiera deseado tu corazón, lo habría tenido, clavado en una pica.$B$BHas cometido el mismo error que cometen todos los mortales.$B$B<Lord Víctor Nefarius suspira.>$B$BEl tiempo hace cosas extrañas con aquellos que lo utilizan como moneda.' WHERE `ID`=9846;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 못하겠습니다, 밸라스트라즈! 당신을 치유할 수 있는 방법이 분명히 있을 겁니다!', `MaleText_loc4`='我做不到，瓦拉斯塔兹！一定有什么办法可以拯救你！', `MaleText_loc5`='我做不到，瓦拉斯塔茲!一定有什麼辦法可以治療你!', `MaleText_loc7`='¡No puedo, Vaelastrasz! ¡Tiene que haber algo que podamos hacer para curarte!', `FemaleText_loc1`='전 못하겠습니다, 밸라스트라즈! 당신을 치유할 수 있는 방법이 분명히 있을 겁니다!', `FemaleText_loc4`='我做不到，瓦拉斯塔兹！一定有什么办法可以拯救你！', `FemaleText_loc5`='我做不到，瓦拉斯塔茲!一定有什麼辦法可以治療你!', `FemaleText_loc7`='¡No puedo, Vaelastrasz! ¡Tiene que haber algo que podamos hacer para curarte!' WHERE `ID`=9847;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사제야, 그렇게 치유를 계속할 테냐?! 그럼 어디 좀 더 재미있게 만들어 줄까!', `MaleText_loc4`='牧师们！如果你们要继续这么治疗的话，那我们就来玩点有趣的东西吧！', `MaleText_loc5`='牧師!如果你要繼續這麼治療的話，那我們來玩點有趣的東西!', `MaleText_loc7`='¡Sacerdotes! Si vais a seguir curando de esa forma, ¡podíamos hacerlo más interesante!' WHERE `ID`=9848;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사냥꾼 놈에다 그 장난감 같은 총이라니, 정말 거슬리는구나!', `MaleText_loc4`='猎人们，还有你们那些讨厌的玩具枪！', `MaleText_loc5`='獵人和你那討厭的豌豆射擊!', `MaleText_loc7`='¡Cazadores y sus molestas cerbatanas!' WHERE `ID`=9849;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 마법사냐? 마법을 가지고 장난칠 상대를 고를 때는 좀 더 신중했어야지...', `MaleText_loc4`='你们也是法师？小心别玩火自焚……', `MaleText_loc5`='還有法師?你應該小心使用你的魔法...', `MaleText_loc7`='¿Magos también? Deberíais tener más cuidado cuando jugáis con la magia...' WHERE `ID`=9850;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드루이드 녀석, 그 바보 같은 변신을 했다고 내가 모를 줄 알았더냐? 받아라!', `MaleText_loc4`='德鲁伊和你们愚蠢的变形法术。让我们看看有什么事情会发生吧！', `MaleText_loc5`='德魯伊和你們愚蠢的變身術。讓我們看看什麼會發生吧!', `MaleText_loc7`='Los druidas y su estúpido poder de cambiar de forma. ¡Veámoslo en acción!' WHERE `ID`=9851;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흑마법사여, 네가 이해하지도 못하는 마법을 가지고 장난을 쳐서야 쓰나... 바로 이런 꼴이 되어 버렸지 않는가!', `MaleText_loc4`='术士们，不要随便去尝试那些你们根本不理解的法术。看到后果了吧？', `MaleText_loc5`='術士，不要隨便去玩那些你不理解的法術。看看會發生什麼吧?', `MaleText_loc7`='Brujos... No deberíais estar jugando con magia que no comprendéis. ¿Veis lo que pasa?' WHERE `ID`=9852;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성기사여... 네 목숨은 여러 개라고 하던데 어디 한번 보여 다오.', `MaleText_loc4`='圣骑士……听说你们有无数条命。让我看看到底是怎么样的吧。', `MaleText_loc5`='聖騎士...聽說你有無數條命。讓我看看到底是怎麼樣的吧。', `MaleText_loc7`='Paladines... He oído que tenéis muchas vidas. Demostrádmelo.' WHERE `ID`=9853;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주술사, 네 놈의 토템이 얼마나 쓸모 있는지 한번 보자!', `MaleText_loc4`='萨满祭司，让我看看你们的图腾到底是干什么用的！', `MaleText_loc5`='薩滿，讓我看看你圖騰到底是什麼用處的!', `MaleText_loc7`='¡Chamanes, muéstrenme lo que pueden hacer sus tótems!' WHERE `ID`=9854;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전사들이로군, 네가 그보다 더 강하게 내려 칠 수 있다는 걸 알고 있다! 어디 한번 제대로 쳐 보란 말이다!', `MaleText_loc4`='战士们，我知道你们可以更加勇猛！让我们见识一下！', `MaleText_loc5`='戰士，我知道你的力量不只如此!讓我們來見識一下吧!', `MaleText_loc7`='¡Sé que podéis golpear más fuerte, guerreros! ¡Veámoslo!' WHERE `ID`=9855;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도적들인가? 숨어 다니지만 말고 나와서 나와 맞서라!', `MaleText_loc4`='潜行者？不要躲躲藏藏了，勇敢地面对我吧！', `MaleText_loc5`='盜賊?不要躲了，面對我吧!', `MaleText_loc7`='¿Pícaros? ¡Dejad de esconderos y enfrentaos a mí!' WHERE `ID`=9856;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보주의 표면에 커다란 인간의 손자국이 새겨져 있습니다. 끊임없는 조작과 처리에 시달려 보이지만 보주는 전혀 손상되지 않았습니다.', `MaleText_loc4`='一个巨大的人类手印出现在宝珠的表面。除了看上去的那些处理过的痕迹，宝珠并没有损坏。', `MaleText_loc5`='一個巨大的人類手印出現在寶珠的表面。除了看起來的那些處理過的痕跡，寶珠並沒有損壞。', `MaleText_loc7`='Una gran huella de una mano humanoide está incrustada en la superficie del orbe. A pesar de lo que parece ser una manipulación constante, el orbe permanece en perfectas condiciones.' WHERE `ID`=9857;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보주에 있는 표시가 손에 찍힌 낙인과 일치합니다.', `MaleText_loc4`='宝珠的印记和你的手正好适合。', `MaleText_loc5`='寶珠的印記和你的手正好適合。', `MaleText_loc7`='Las marcas del orbe son iguales que el estigma de tu mano.' WHERE `ID`=9858;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<보주에 손을 얹습니다.>', `MaleText_loc4`='<把我的手放在宝珠上。>', `MaleText_loc5`='<把你的手放在寶珠之上。>', `MaleText_loc7`='<Colocar mi mano sobre el orbe.>', `FemaleText_loc1`='<보주에 손을 얹습니다.>', `FemaleText_loc4`='<把我的手放在宝珠上。>', `FemaleText_loc5`='<把你的手放在寶珠之上。>', `FemaleText_loc7`='<Colocar mi mano sobre el orbe.>' WHERE `ID`=9859;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 고통이 끝나는구나. 여왕님께 실망을 안겨 드렸나이다. 우리 모두에게 실망을 안겼나이다...', `MaleText_loc4`='终于，痛苦结束了。我让你失望了，我的女王。我让你们都失望了……', `MaleText_loc5`='終於，痛苦結束?我讓您失望了吾后。我讓你們都失望了...', `MaleText_loc7`='Por fin termina la agonía. Te he fallado, mi reina. Nos he fallado a todos...' WHERE `ID`=9860;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나... 나는 실패하고 말았다, $n. 검은... 검은바위의 군주는 너무나도 강하다. 간단히 내 마력을... 소진시켜 버리더군. 난... 날... 죽여라... 네가... 날 죽여야 한다.', `MaleText_loc4`='我……我失败了，$n。黑石……黑石山脉的领主实在是太强大了。他轻易地……轻易地吸收了我的力量。我已经……我……请你一定要……一定要杀了我。', `MaleText_loc5`='我...我失敗了，$n。黑石...黑石之王實在是太強大了。他輕易地...輕易地吸收了我的力量。我已經...我...請你一定要...一定要殺了我。', `MaleText_loc7`='He... fallado, $n. El Señor de Roca Negra... El Señor de Roca Negra es demasiado poderoso. He consumido mi energía con... con facilidad. Me he convertido en... Yo... mátame. Debes... matarme.' WHERE `ID`=9861;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 저들의 감시자이자 복수의 주먹... 저항 세력을 진압하는 자이니라. 감히 이 대군주에게 덤빌 자가 누구냐? 나의 무자비한 심판에 맞설 자가 누구란 말이더냐?', `MaleText_loc4`='我是联军的指挥官。我是惩戒之拳。我的职责就是扫清其拉虫人的势力。你敢挑衅酋长的权威吗？你敢直面我无情的审判吗？', `MaleText_loc5`='我是監查他們的人。我是懲罰之拳。我來鎮壓反抗。你敢挑釁大酋長?那你敢不敢面對我無情的審判?', `MaleText_loc7`='Yo soy quien les observa. Soy el puño del castigo. Quien aplasta a los obstinados. ¿Osas desafiar al Jefe de Guerra? ¿Osas enfrentarte a mi castigo despiadado?' WHERE `ID`=9862;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 낚시하고 있는 게 안 보이시오!', `MaleText_loc4`='你没看到我在这里钓鱼吗？', `MaleText_loc5`='你看不到我在這裡釣魚嗎?', `MaleText_loc7`='¿No ves que estoy pescando aquí?' WHERE `ID`=9863;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 때문에 물고기가 겁나서 도망갔잖소! 원하는 게 뭐요?', `MaleText_loc4`='你把我的鱼吓走了！你到底要怎么样？', `MaleText_loc5`='你把我的魚嚇走了!你到底要怎麼樣?', `MaleText_loc7`='¡Has espantado a los peces! ¿Qué quieres?' WHERE `ID`=9864;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일로 왔소, $c 친구?', `MaleText_loc4`='我可以为你做什么吗，$c？', `MaleText_loc5`='我可以為你做什麼$c?', `MaleText_loc7`='¿Qué puedo hacer por ti, $c?' WHERE `ID`=9865;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 34Kg짜리 농어를 잡을 때까지는 여기 있을 참이오! 당신은 어디 다른 곳으로 가고 싶은 것이겠지... 그렇지 않소?', `MaleText_loc4`='我要一直待在这里直到钓到68磅重的石斑鱼！你却要离开到什么地方去，是不是？', `MaleText_loc5`='我要一直待在這裡直到釣到68磅重的石斑魚!你卻要離開到什麼地方去，是不是?', `MaleText_loc7`='¡No me muevo de aquí hasta que pesque un mero de 130 kilos! Pero creo que tú quieres largarte a otra parte, ¿tengo razón?' WHERE `ID`=9866;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네파리안이 쓰러졌다! 오그리마의 백성들이여, $n|1과;와; 친구들의 힘 앞에 경의를 표하라! 이들은 검은용군단에 큰 타격을 입히고 위상들을 동요시켰도다! 오늘의 참패는 분명 검은용군단의 아버지인 데스윙에게도 영향을 미칠 것이니... 오늘 데스윙이 고통으로 비틀거리는구나!', `MaleText_loc4`='奈法利安被杀掉了！奥格瑞玛的居民，在强大的$B和$g他:她;的盟友面前鞠躬致意吧，他们对即使是神也要忌惮三分的黑龙军团进行了致命一击！这一次的失败定会让黑龙之父死亡之翼感到疼痛和苦恼！', `MaleText_loc5`='奈法利安被幹掉了!奧格瑪的人們，在強大的$n和$g他:她;的盟友面前鞠躬致意吧，他們對黑龍軍團進行了致命一擊!守護巨龍不必再苦惱了。這次的失敗一定會讓黑龍之父:死亡之翼感到痛苦和懊惱!', `MaleText_loc7`='¡NEFARIAN HA SIDO ASESINADO! Ciudadanos de Orgrimmar, inclínense ante el poder de $n y sus aliados, porque ellos han asestado un gran golpe al Vuelo Negro que sacará a los Aspectos de su pesadumbre. El padre del Vuelo Negro sentirá esta derrota. ¡En este día, Alamuerte retrocede, lleno de dolor y angustia!' WHERE `ID`=9867;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1과;와; 친구들의 업적에 감사하라! 모두 함께 함성을 질러 승리를 축하하자!', `MaleText_loc4`='为$n的成就而庆祝！为$g他:她;的胜利而狂欢吧！', `MaleText_loc5`='為$n的成就而慶祝!為$g他:她;的勝利而狂歡吧!', `MaleText_loc7`='¡Siéntanse elevados por el logro de $n! ¡Deléitense en su grito de llamamiento!' WHERE `ID`=9868;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 쓰러진 용을 보게, $r 친구. 호드의 강한 힘은 의심의 여지가 없지 않나?!', `MaleText_loc4`='看看这条被干掉的龙的脸，$r。部落的强大是毋庸置疑的！', `MaleText_loc5`='看看這條被幹掉的龍的臉，$r。部落的強大是毋庸置疑的!', `MaleText_loc7`='Mira al dragón caído, $r. ¡El poder de la Horda es incuestionable!' WHERE `ID`=9869;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스의 시민들이여, 검은바위의 군주가 쓰려졌다! $n|1과;와; 그 동료의 결속된 힘에 네파리안이 무릎을 꿇었다!', `MaleText_loc4`='联盟的人民们，黑石领主已经被干掉了！奈法利安已经被强大的$n和$g他:她;的盟友所降伏了！', `MaleText_loc5`='聯盟的人民們，黑石之王已經被幹掉了!奈法利安已經被萬能的$n和$g他:她;的盟友所降伏了!', `MaleText_loc7`='¡Ciudadanos de la Alianza, el Señor de Roca Negra está muerto! ¡Nefarian ha sido vencido gracias a la combinación del poder de $n y sus aliados!' WHERE `ID`=9870;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성난불길 협곡은 오그리마의 어둠의 틈 밑에 서로 연결된 화산 굴로 이루어져 있습니다. 최근 사악한 어둠의 의회를 섬기는 이교집단이 이 협곡의 타오르는 심연 내에 자리를 잡았다는 소문이 퍼졌지요. 불타는 칼날단이라 알려진 이 이교집단은 듀로타의 주권 자체를 위협하고 있습니다. 많은 이들이 오크 대족장이신 스랄 님께서 불타는 칼날단의 존재를 아시지만 이들이 어둠의 의회로 자신을 인도할 수 있을 거라는 희망 때문에 그들을 멸하지 않기로 했다고 믿고 있습니다.', `MaleText_loc4`='怒焰裂谷是由许多火山洞穴所组成的，它位于部落的新都城奥格瑞玛中。最近，有传言说一群忠于阴影教会的教徒占据了那个地方。这群被称为火刃得教徒威胁了杜隆塔尔的安宁。许多人相信兽人酋长萨尔已经意识到了火刃的存在，他并不想着急于摧毁他们，因为萨尔希望这个教会能够将他带往阴影教会。', `MaleText_loc5`='怒焰裂谷是由許多火山洞穴所組成的，它位於部落的新都城奧格瑪中。最近，有傳言說一群忠於暗影議會的教徒佔據了那個地方。這群被稱為燃刃的教徒威脅了杜洛塔的安寧。許多人相信獸人大酋長索爾已經意識到了燃刃的存在，他並不想著急於摧毀他們，因為索爾希望這個教會能夠引領他找到暗影議會。', `MaleText_loc7`='La Sima Ígnea consiste en una red de cuevas volcánicas que se extiende bajo la nueva capital de los orcos, Orgrimmar. Recientemente, se han extendido rumores sobre un culto leal al Consejo de la Sombra que se ha asentado en las ardientes profundidades de la Sima. Este culto, conocido como el Filo Ardiente, amenaza la soberanía de Durotar. Hay muchos que creen que Thrall, el Jefe de Guerra orco, conoce la existencia del Filo y ha decidido no destruirlo, con la esperanza de que sus miembros le lleven directo al Consejo de la Sombra.', `FemaleText_loc1`='성난불길 협곡은 오그리마의 어둠의 틈 밑에 서로 연결된 화산 굴들로 구성되어 있습니다. 최근 사악한 어둠의 의회를 섬기는 이교집단이 이 협곡의 타오르는 심연 내에 자리를 잡았다는 소문이 퍼졌지요. 불타는 칼날단이라 알려진 이 이교집단은 듀로타의 주권 자체를 위협하고 있습니다. 많은 이들이 오크 대족장이신 스랄 님께서 불타는 칼날단의 존재를 아시지만 이들이 어둠의 의회로 자신을 인도할 수 있을 거라는 희망 때문에 그들을 멸하지 않기로 했다고 믿고 있습니다.', `FemaleText_loc4`='怒焰裂谷是由许多火山洞穴所组成的，它位于部落的新都城奥格瑞玛中。最近，有传言说一群忠于阴影教会的教徒占据了那个地方。这群被称为火刃得教徒威胁了杜隆塔尔的安宁。许多人相信兽人酋长萨尔已经意识到了火刃的存在，他并不想着急于摧毁他们，因为萨尔希望这个教会能够将他带往阴影教会。', `FemaleText_loc5`='怒焰裂谷是由許多火山洞穴所組成的，它位於部落的新都城奧格瑪中。最近，有傳言說一群忠於暗影議會的教徒佔據了那個地方。這群被稱為燃刃的教徒威脅了杜洛塔的安寧。許多人相信獸人大酋長索爾已經意識到了燃刃的存在，他並不想著急於摧毀他們，因為索爾希望這個教會能夠引領他找到暗影議會。', `FemaleText_loc7`='La Sima Ígnea consiste en una red de cuevas volcánicas que se extiende bajo la nueva capital de los orcos, Orgrimmar. Recientemente, se han extendido rumores sobre un culto leal al Consejo de la Sombra que se ha asentado en las ardientes profundidades de la Sima. Este culto, conocido como el Filo Ardiente, amenaza la soberanía de Durotar. Hay muchos que creen que Thrall, el Jefe de Guerra orco, conoce la existencia del Filo y ha decidido no destruirlo, con la esperanza de que sus miembros le lleven directo al Consejo de la Sombra.' WHERE `ID`=9871;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기뻐하라! 용사 주위에 모여 $g그:그녀;의 영광을 만끽하라! 용을 처치한 영웅들의 단결을 향한 외침을 즐겨라!', `MaleText_loc4`='兴奋起来！为你们的勇士欢呼，沐浴在$g他:她;的荣耀之中！为我们伟大的屠龙者欢呼吧！', `MaleText_loc5`='讓大家的情緒沸騰起來!為你們的勇士歡呼，沐浴在$g他:她;的榮耀之中!為我們偉大的屠龍者歡呼吧!', `MaleText_loc7`='¡Dejen que se eleven sus espíritus! ¡Reúnanse alrededor de $gnuestro campeón:nuestra campeona;! ¡Gocen en su gloria! ¡Deléitense con el grito de llamamiento $gdel cazador:de la cazadora; de dragones!' WHERE `ID`=9872;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 던전에 들어가는 파티에 참가하고 싶습니다. <여기를 클릭하면 만남의 돌 대기자 명단에 올라갑니다.>', `MaleText_loc4`='加入将要进入这个地下城的队伍。<这个选择将会让你排入汇合石的队伍中>', `MaleText_loc5`='加入將要進入這個地城的隊伍。<這個選擇將會讓你排入集合石的隊伍中>', `MaleText_loc7`='Unirse a un grupo que vaya a esta mazmorra. <Esta selección te colocará en una cola de la roca de encuentro>', `FemaleText_loc1`='이 던전에 들어가는 파티에 참가하고 싶습니다. <여기를 클릭하면 만남의 돌 대기자 명단에 올라갑니다.>', `FemaleText_loc4`='加入将要进入这个地下城的队伍。<这个选择将会让你排入汇合石的队伍中>', `FemaleText_loc5`='加入將要進入這個地城的隊伍。<這個選擇將會讓你排入集合石的隊伍中>', `FemaleText_loc7`='Unirse a un grupo que vaya a esta mazmorra. <Esta selección te colocará en una cola de la roca de encuentro>' WHERE `ID`=9873;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은바위의 군주가 죽었다는 증거가 홍예문 위에 걸려 있다!', `MaleText_loc4`='黑石领主从灰烬中升起！', `MaleText_loc5`='黑石之王從灰燼中升起!', `MaleText_loc7`='¡El Señor de Roca Negra está colgado de los arcos!' WHERE `ID`=9874;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에는 볼 것이 없으니 어서 가십시오.', `MaleText_loc4`='快点离开，市民。没有什么好看的。', `MaleText_loc5`='快點離開，居民。沒有什麼好看的。', `MaleText_loc7`='Vete de aquí, $gciudadano:ciudadana;. No hay nada que ver aquí.' WHERE `ID`=9875;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성난불길 협곡', `MaleText_loc4`='怒焰裂谷', `MaleText_loc5`='怒焰裂谷', `MaleText_loc7`='Furia Ardiente', `FemaleText_loc1`='성난불길 협곡', `FemaleText_loc4`='怒焰裂谷', `FemaleText_loc5`='怒焰裂谷', `FemaleText_loc7`='Furia Ardiente' WHERE `ID`=9876;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 던전들 중 하나를 골라 탐험해 보시겠습니까?', `MaleText_loc4`='你有兴趣探索这些地下城中的一个吗？', `MaleText_loc5`='你有興趣探索這些地城中的一個嗎?', `MaleText_loc7`='¿Te interesa explorar una de estas mazmorras?', `FemaleText_loc1`='이 던전들 중 하나를 골라 탐험해 보시겠습니까?', `FemaleText_loc4`='你有兴趣探索这些地下城中的一个吗？', `FemaleText_loc5`='你有興趣探索這些地城中的一個嗎?', `FemaleText_loc7`='¿Te interesa explorar una de estas mazmorras?' WHERE `ID`=9877;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='통곡의 동굴', `MaleText_loc4`='哀嚎洞穴', `MaleText_loc5`='哀嚎洞穴', `MaleText_loc7`='Cuevas de los Lamentos', `FemaleText_loc1`='통곡의 동굴', `FemaleText_loc4`='哀嚎洞穴', `FemaleText_loc5`='哀嚎洞穴', `FemaleText_loc7`='Cuevas de los Lamentos' WHERE `ID`=9878;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기에 설계도로 보이는 종이 뭉치가 흩어져 있습니다.', `MaleText_loc4`='这里散乱着放着一堆堆的图纸和设计图。', `MaleText_loc5`='這裡散亂地放著成堆的圖紙和設計圖。', `MaleText_loc7`='Hay unos papeles y dibujos esquemáticos esparcidos.' WHERE `ID`=9879;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 종이들을 지키고 있는 자가 있습니다. 자멕과 대화하여 그의 주의를 분산시키십시오!', `MaleText_loc4`='这些图纸被守卫着。和扎米克谈谈来引开守卫的注意！', `MaleText_loc5`='這些圖紙被守衛著。和札米克談話來引開守衛的注意!', `MaleText_loc7`='Los papeles están protegidos. Habla con Zamek para crear una distracción.' WHERE `ID`=9880;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최근에 나랄렉스라고 하는 나이트 엘프 드루이드가 불모의 땅 중심부에 있는 지하 동굴을 발견했습니다. 그 동굴의 샘을 이용해 불모의 땅을 다시 푸르게 만들 수 있을 거로 생각한 나랄렉스는 그 유명한 에메랄드의 꿈의 마력을 끌어들이기 시작했지요. 하지만 그의 예견은 어떻게 돼선지 악몽으로 변해 버렸고 통곡의 동굴은 곧 사납고 무서운 짐승들의 소굴이 되어 버렸습니다. 소문에 따르면 그 미궁 안 어딘가에서 여전히 나랄렉스가 에메랄드의 꿈 가장자리 너머에 갇혀 살고 있다고 합니다.', `MaleText_loc4`='最近一个名叫纳拉雷克斯的暗夜精灵德鲁伊在贫瘠之地中的地下发现了一个错综复杂的洞穴网。这个被称作“哀嚎洞穴”的地方有很多的蒸汽缝隙，所以当蒸气喷射的时候发出的声音就犹如哀嚎一般，其因此而得名。纳拉雷克斯可以利用洞穴中的温泉来恢复贫瘠之地的生态，让这里重新获得生机——但是这样做需要吸收传说中的翡翠梦境的能量。一旦和翡翠梦境相连接，德鲁伊的视线中就变成了一场噩梦。不久之后，哀嚎洞穴开始变化——洞中的水开始腐化——曾经温顺的生物开始变成狂暴，致命的捕食者。据说纳拉雷克斯自己还居住在这个迷宫的最深处，他被翡翠梦境的边缘所困扰着。即使他以前的随从也被他们的主人所经历的噩梦所腐化——他们都变成了邪恶的尖牙德鲁伊。', `MaleText_loc5`='最近一個名叫納拉雷克斯的夜精靈德魯伊在貧瘠之地中的地下發現了一個錯綜複雜的洞穴網。這個被稱作「哀嚎洞穴」的地方有很多的蒸汽縫隙，所以當蒸汽噴射的時候發出的聲音就猶如哀嚎一般，其因此而得名。納拉雷克斯可以利用洞穴中的溫泉來恢復貧瘠之地的生態，讓這裡重新獲得生機─但是這樣做需要吸收傳說中的翡翠夢境的能量。一旦和翡翠夢境相連接，德魯伊的視線中就變成了一場夢魘。不久之後，哀嚎洞穴開始變化─洞中的水開始腐化─曾經溫順的生物開始變成狂暴，致命的捕食者。據說納拉雷克斯自己還居住在這個迷宮的最深處，他被翡翠夢境的邊緣所困擾著。即使他以前的隨從也被他們的主人所經歷的夢魘所腐化─他們都變成了邪惡的尖牙德魯伊。', `MaleText_loc7`='Hace poco, un druida elfo de la noche llamado Naralex, descubrió una red de cuevas subterráneas en el corazón de Los Baldíos. Creyendo que podría usar los manantiales de las cuevas para restaurar la exuberancia de Los Baldíos, el druida comenzó a absorber las energías del legendario Sueño Esmeralda. De alguna forma, su visión se transformó en una pesadilla y pronto, las Cuevas de los Lamentos se convirtieron en una guarida de feroces y letales depredadores. Se dice que Naralex sigue en algún lugar del laberinto, atrapado más allá de los límites del Sueño Esmeralda.', `FemaleText_loc1`='최근에 나랄렉스라고 하는 나이트 엘프 드루이드가 불모의 땅 중심부에 있는 지하 동굴을 발견했습니다. 그 동굴의 샘을 이용해 불모의 땅을 다시 푸르게 만들 수 있을 거로 생각한 나랄렉스는 그 유명한 에메랄드의 꿈의 마력을 끌어들이기 시작했지요. 하지만 그의 예견은 어떻게 돼선지 악몽으로 변해 버렸고 통곡의 동굴은 곧 사납고 무서운 짐승들의 소굴이 되어 버렸습니다. 소문에 따르면 그 미궁 안 어딘가에서 여전히 나랄렉스가 에메랄드의 꿈 가장자리 너머에 갇혀 살고 있다고 합니다.', `FemaleText_loc4`='最近一个名叫纳拉雷克斯的暗夜精灵德鲁伊在贫瘠之地中的地下发现了一个错综复杂的洞穴网。这个被称作“哀嚎洞穴”的地方有很多的蒸汽缝隙，所以当蒸气喷射的时候发出的声音就犹如哀嚎一般，其因此而得名。纳拉雷克斯可以利用洞穴中的温泉来恢复贫瘠之地的生态，让这里重新获得生机——但是这样做需要吸收传说中的翡翠梦境的能量。一旦和翡翠梦境相连接，德鲁伊的视线中就变成了一场噩梦。不久之后，哀嚎洞穴开始变化——洞中的水开始腐化——曾经温顺的生物开始变成狂暴，致命的捕食者。据说纳拉雷克斯自己还居住在这个迷宫的最深处，他被翡翠梦境的边缘所困扰着。即使他以前的随从也被他们的主人所经历的噩梦所腐化——他们都变成了邪恶的尖牙德鲁伊。', `FemaleText_loc5`='最近一個名叫納拉雷克斯的夜精靈德魯伊在貧瘠之地中的地下發現了一個錯綜複雜的洞穴網。這個被稱作「哀嚎洞穴」的地方有很多的蒸汽縫隙，所以當蒸汽噴射的時候發出的聲音就猶如哀嚎一般，其因此而得名。納拉雷克斯可以利用洞穴中的溫泉來恢復貧瘠之地的生態，讓這裡重新獲得生機─但是這樣做需要吸收傳說中的翡翠夢境的能量。一旦和翡翠夢境相連接，德魯伊的視線中就變成了一場夢魘。不久之後，哀嚎洞穴開始變化─洞中的水開始腐化─曾經溫順的生物開始變成狂暴，致命的捕食者。據說納拉雷克斯自己還居住在這個迷宮的最深處，他被翡翠夢境的邊緣所困擾著。即使他以前的隨從也被他們的主人所經歷的夢魘所腐化─他們都變成了邪惡的尖牙德魯伊。', `FemaleText_loc7`='Hace poco, un druida elfo de la noche llamado Naralex, descubrió una red de cuevas subterráneas en el corazón de Los Baldíos. Creyendo que podría usar los manantiales de las cuevas para restaurar la exuberancia de Los Baldíos, el druida comenzó a absorber las energías del legendario Sueño Esmeralda. De alguna forma, su visión se transformó en una pesadilla y pronto, las Cuevas de los Lamentos se convirtieron en una guarida de feroces y letales depredadores. Se dice que Naralex sigue en algún lugar del laberinto, atrapado más allá de los límites del Sueño Esmeralda.' WHERE `ID`=9881;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탐험할만한 던전에 대해 알려 주십시오.', `MaleText_loc4`='告诉我关于我可以探索的地下城的信息。', `MaleText_loc5`='告訴我關於我可以探索的地城的資訊。', `MaleText_loc7`='Háblame sobre las mazmorras que puedo explorar.', `FemaleText_loc1`='탐험할만한 던전에 대해 알려 주십시오.', `FemaleText_loc4`='告诉我关于我可以探索的地下城的信息。', `FemaleText_loc5`='告訴我關於我可以探索的地城的資訊。', `FemaleText_loc7`='Háblame sobre las mazmorras que puedo explorar.' WHERE `ID`=9882;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말도 안 돼! 일어나라! 다시 한 번 너희 주인을 섬겨라!', `MaleText_loc4`='不可能！出现吧，我的仆人！再次为你们的主人效力！', `MaleText_loc5`='不可能!出現吧，我的僕人!再次為我的主人服務!', `MaleText_loc7`='¡Imposible! ¡Levántense, mis esbirros! ¡Sirvan a su amo una vez más!' WHERE `ID`=9883;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달라란 마법사들이 3차 대전쟁 중 언데드에 대한 조치가 제대로 진척되지 않자, 이에 실망한 대마법사 아루갈은 자기 편의 줄어드는 군세를 보충하기 위해 전혀 다른 차원에서 늑대인간들을 소환하기로 결정했습니다. 이 늑대인간들은 스컬지를 참살한 후 곧 마법사들에게 반기를 들었고 실버레인 남작의 성채를 포위했지요. 이 요새는 빠르게 암흑과 폐허로 무너져 갔고 죄책감에 미쳐 버린 아루갈은 늑대인간들을 자신의 후예로 삼아 ''그림자송곳니 성채''라는 새로운 이름으로 불리게 된 그 요새로 퇴각했습니다.', `MaleText_loc4`='在第三次大战中，肯瑞托的法师和亡灵天灾进行了殊死的战斗。大法师阿鲁高召唤了异世界中的狼人来增强达拉然守备部队的力量。这些狂暴的狼型生物踏平了来犯的亡灵天灾，然后迅速将目标转向达拉然的法师，并开始围攻席瓦莱恩男爵的城堡。这座位于焚木村的城堡不久之后就变成了黑暗势力的聚集地，并从此荒废。因为对于自己罪过的愧疚，阿鲁高将那些狼人当作自己的孩子并隐居在“影牙城堡”中。', `MaleText_loc5`='對於達拉然巫師在第三次戰爭中，對抗亡靈的緩慢進展，大法師阿魯高選擇去召喚了一批異次元狼人來強化他們逐漸衰弱的武力。這些狂暴的狼人不僅屠殺了天譴軍團的士兵，而且迅速將目標轉向那些巫師並且開始圍攻席瓦萊恩男爵的要塞。堡壘很快地陷落，變成一座黑暗聚集的廢墟。而阿魯高被自己的罪惡感所逼瘋，把那些狼人當成自己的孩子躲在這座更名「影牙城堡」的要塞中。', `MaleText_loc7`='Frustrado por la falta de progreso de los magos de Dalaran contra los no-muertos durante la Tercera Guerra, el archimago Arugal decidió invocar a los huargen extra-dimensionales para dar un empujón a sus tropas cada vez menores. Los hombres lobo atacaron a la Plaga y, rápidamente, se dirigieron a los magos y asediaron el bastión del noble barón Filargenta. Pronto, el fuerte fue presa de las sombras y se convirtió en cenizas. Enloquecido por la culpa, Arugal adoptó a los huargen como sus hijos y se retiró al Castillo de Colmillo Oscuro.', `FemaleText_loc1`='달라란 마법사들이 3차 대전쟁 중 언데드에 대한 조치가 제대로 진척되지 않자, 이에 실망한 대마법사 아루갈은 자기 편의 줄어드는 군세를 보충하기 위해 전혀 다른 차원에서 늑대인간들을 소환하기로 결정했습니다. 이 늑대인간들은 스컬지를 참살한 후 곧 마법사들에게 반기를 들었고 실버레인 남작의 성채를 포위했지요. 이 요새는 빠르게 암흑과 폐허로 무너져 갔고 죄책감에 미쳐 버린 아루갈은 늑대인간들을 자신의 후예로 삼아 ''그림자송곳니 성채''라는 새로운 이름으로 불리게 된 그 요새로 퇴각했습니다.', `FemaleText_loc4`='在第三次大战中，肯瑞托的法师和亡灵天灾进行了殊死的战斗。大法师阿鲁高召唤了异世界中的狼人来增强达拉然守备部队的力量。这些狂暴的狼型生物踏平了来犯的亡灵天灾，然后迅速将目标转向达拉然的法师，并开始围攻席瓦莱恩男爵的城堡。这座位于焚木村的城堡不久之后就变成了黑暗势力的聚集地，并从此荒废。因为对于自己罪过的愧疚，阿鲁高将那些狼人当作自己的孩子并隐居在“影牙城堡”中。', `FemaleText_loc5`='對於達拉然巫師在第三次戰爭中，對抗亡靈的緩慢進展，大法師阿魯高選擇去召喚了一批異次元狼人來強化他們逐漸衰弱的武力。這些狂暴的狼人不僅屠殺了天譴軍團的士兵，而且迅速將目標轉向那些巫師並且開始圍攻席瓦萊恩男爵的要塞。堡壘很快地陷落，變成一座黑暗聚集的廢墟。而阿魯高被自己的罪惡感所逼瘋，把那些狼人當成自己的孩子躲在這座更名「影牙城堡」的要塞中。', `FemaleText_loc7`='Frustrado por la falta de progreso de los magos de Dalaran contra los no-muertos durante la Tercera Guerra, el archimago Arugal decidió invocar a los huargen extra-dimensionales para dar un empujón a sus tropas cada vez menores. Los hombres lobo atacaron a la Plaga y, rápidamente, se dirigieron a los magos y asediaron el bastión del noble barón FIlargenta. Pronto, el fuerte fue presa de las sombras y se convirtió en cenizas. Enloquecido por la culpa, Arugal adoptó a los huargen como sus hijos y se retiró al Castillo de Colmillo Oscuro.' WHERE `ID`=9884;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그림자송곳니 성채', `MaleText_loc4`='影牙城堡', `MaleText_loc5`='影牙城堡', `MaleText_loc7`='Castillo de Colmillo Oscuro', `FemaleText_loc1`='그림자송곳니 성채', `FemaleText_loc4`='影牙城堡', `FemaleText_loc5`='影牙城堡', `FemaleText_loc7`='Castillo de Colmillo Oscuro' WHERE `ID`=9885;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 늦었어! 네파리우스의 타락이 뿌리를 내려... 난... 나 자신을 통제할 수가 없어.', `MaleText_loc4`='太晚了，朋友们！奈法利安的堕落力量已经生效……我无法……控制自己。', `MaleText_loc5`='太遲了，朋友! 奈法利斯的腐化已經掌握了我...我已經無法...控制我自己了。', `MaleText_loc7`='¡Demasiado tarde, amigos! Ahora estoy poseído por la corrupción de Nefarius... No puedo... controlarme.' WHERE `ID`=9886;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부탁이다. 도망쳐라! 내가 자제력을 완전히 잃기 전에! 내 가슴 속에 검은 불길이 끓고 있다! 내뿜어야만 해!', `MaleText_loc4`='求求你们，快跑吧！在我丧失所有理智之前快逃命吧！黑色的火焰在我的心中燃烧！我必须——释放它！', `MaleText_loc5`='我乞求你，凡人─快逃吧!在我失去控制前快逃吧!黑色的火焰在我心中狂烈的燃燒著!我必須要─釋放它!', `MaleText_loc7`='Se los ruego, mortales, ¡ESCAPEN! ¡Escapen antes de que pierda todo el control! ¡Las llamaradas negras se extienden en mi corazón! ¡DEBO liberarlas!' WHERE `ID`=9887;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불! 파괴! 죽음! 군주의 분노를 두려워하라! 안 돼! 난 싸워야해! 알렉스트라자여, 도와주소서! 난 싸워야해!', `MaleText_loc4`='火焰！死亡！毁灭！你们这些凡人，让奈法里奥斯大人的力量……不——我要抗争！阿莱克丝塔萨，帮帮我，我必须抗争到底！', `MaleText_loc5`='火焰!死亡!毀滅!畏縮吧，面對奈法利安大王的盛怒的凡人們...不─我必須要對抗它!幫我，雅立史卓莎，我必須要對抗它!', `MaleText_loc7`='¡FUEGO! ¡MUERTE! ¡DESTRUCCIÓN! Póstrense mortales ante la ira del Señor... ¡NO, TENGO que combatirlo! ¡Alexstrasza ayúdame, tengo que combatirlo!' WHERE `ID`=9888;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요! 검은창 부족의 존경과 호의를 얻고 싶다면 가난한 이들에게 귀한 자원을 기부하는 걸로 시작해 보십시오! 옷감이나 붕대가 하늘에서 뚝 떨어질 수는 없으니까요.$B$B모험을 하시면서 다양한 옷감을 구하실 텐데... 그냥 팔아버리는 것보다 좋은 일에 쓰는 건 어떻습니까?! 검은창 부족으로부터 인정도 받고 말입니다!', `FemaleText_loc4`='啊，你！如果你想要赢得暗矛部族的尊重，那你可以向我们捐赠那些急需的资源！你要知道，布料和绷带不会从树上长出来。$B$B我们需要你在冒险中得到的那些布料，把它们捐给我们吧！这样你就可以得到暗矛部族的青睐！', `FemaleText_loc5`='啊，你!如果你想要贏得暗矛的尊重，那你可以向我們捐贈那些繼續的資源!你要知道，布料和繃帶不會從樹上長出來。$B$B我們需要你在冒險中得到的那些布料，把它們捐給我們吧!這樣你就可以得到暗矛部族的親睞!', `FemaleText_loc7`='¡Eh, tú! ¡Si quieres ganarte el respeto de los Lanza Negra, puedes empezar donando valiosos recursos a quienes los necesitan! Las telas y las vendas no crecen el los árboles, ¿sabes?$B$BEn lugar de vender los paños que te encuentras en tus aventuras, ¡dónalos! Hacerlo te proporcionará el reconocimiento de los Lanza Negra.' WHERE `ID`=9889;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런 어려운 시기에는 옷감 같은 단순한 걸 기부하는 일만으로도 형편이 어려운 이들에겐 큰 힘이 되지. 붕대나 옷을 만들 수 있는 옷감이야말로 전시에 아주 중요한 물건이고 말고!$B$B오그리마의 오크족에게 옷감을 기부할 생각이 있다면 기꺼이 받겠어. 그리고 자네도 마땅한 대우와 인정을 받을 수 있을 거야.$B$B호드를 위하여!', `FemaleText_loc4`='在这个艰难的时期，捐赠布料对于那些不幸的人是非常重要的帮助手段。布料还可以制作装备和绷带——这对于战争十分重要！$B$B如果你想要为奥格瑞玛的兽人捐赠布料的话，我会欣然接受它们，你一定会受到我们的青睐。$B$B为了部落！', `FemaleText_loc5`='在這個艱難的時期，捐贈布料對於那些不幸的人是非常重要的幫助手段。布料還可以製作裝備和繃帶─這對於戰爭十分重要!$B$B如果你想要為奧格瑪的獸人捐贈布料的話，我會欣然接受它們，你一定會收到我們的親睞。$B$B為了部落!', `FemaleText_loc7`='En estos tiempos difíciles, una simple donación de paño haría mucho por ayudar a aquellos menos afortunados que nosotros mismos. El paño es necesario para hacer ropas y vendas, ambas cosas son muy necesarias para la guerra.$B$BSi quieres donar paños a los orcos de Orgrimmar, los aceptaré y me aseguraré de que recibas el reconocimiento adecuado por ello.$B$B¡Por la Horda!' WHERE `ID`=9890;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까! 잠깐 제 얘길 좀 들어주십시오.$B$B우리 타우렌족은 고향 땅을 일으켜 세우기 위해 많은 고난과 시련을 겪어 왔습니다. 그러다 보니 지금 옷감이 많이 부족하군요. 혹시 여분이 좀 있다면 기부를 부탁드려도 될까요? 나를 도우면 어디에서든지 타우렌 종족의 감사와 존경을 받게 될 것입니다!', `MaleText_loc4`='嘿，$g兄弟:姐妹;……我希望可以打扰你一下，如果可以的话。$B$B我们在通过试炼和进行家园重建中经历了很多。我们现在极度缺乏布料。如果你有一些多余的话，我希望你可以捐献给我们。你一定会为此赢得所有牛头人的尊重的！', `MaleText_loc5`='嘿，$g兄弟:姐妹;...我希望可以打擾你一下，如果可以的話。$B$B我們在通過試煉和進行家園重建中經歷了很多。我們現在極度缺乏布料。如果你有一些多餘的話，我希望你可以捐獻給我們。你一定會為此贏得所有牛頭人的尊重的!', `MaleText_loc7`='Te saludo, $ghermano: hermana;... Me gustaría hablar contigo unos minutos, si es posible.$B$BNosotros, los tauren, hemos sufrido muchos problemas y tribulaciones para establecer nuestro hogar. Ahora nos encontramos con una gran escasez de paño. Si te sobran materiales, te ruego que los dones. Te ganarás la gratitud de los tauren de todas partes por ayudarnos.' WHERE `ID`=9891;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한때 인간 땅의 금 생산 중심지였던 죽음의 폐광은 이제 데피아즈 결사단이 차지하고 그 어두운 굴을 자신들만의 성소로 만들어 버렸습니다. 소문에 의하면, 이 도적단은 똑똑한 고블린들을 징집해 폐광 바닥에서 뭔가 끔찍한 것을 만드는 걸 돕도록 했다고 합니다만, 그게 무엇인지는 아직 확실하지 않습니다. 들리는 얘기로는, 죽음의 폐광으로 내려가는 길이 조용하고 평온해 보이는 달빛시내 마을에 있다고 하더군요.', `MaleText_loc4`='这里曾经是人类最主要的产金地，希望矿井在部落第一次大战期间席卷暴风城的时候被废弃。现在迪菲亚兄弟会的人占据了那里并将这个黑暗的通道转变成他们的避难所。据说那些盗贼已经劝说了聪明的地精帮助他们在矿井的深处建造一些可怕的东西——但是没有人知道这是真的还是假的。有传言说，死亡矿井的入口在安宁的月溪镇中。', `MaleText_loc5`='這裡曾經是人類最主要的產金地，希望礦坑在部落第一次大戰期間席捲暴風城的時候被廢棄。現在迪菲亞兄弟會的人佔據了那裡並將這個黑暗的通道轉變成他們的避難所。據說那些盜賊已經勸說了聰明的哥布林幫助他們在礦坑的深處建造一些可怕的東西─但是沒有人知道這是真的還是假的。有傳言說，死亡礦坑的入口在安寧的月溪鎮中。', `MaleText_loc7`='Las Minas de la Muerte, antiguamente el mayor centro de producción de oro de las tierras humanas, están habitadas por la Hermandad Defias, que han convertido los oscuros túneles en su santuario privado. Se rumorea que los ladrones han reclutado a los astutos goblins, para ayudarles a construir algo terrible en la parte inferior de las minas, aunque se desconoce de qué se trata. Dicen que el camino que lleva a las Minas de la Muerte pasa por la tranquila y sencilla aldea Arroyo de la Luna.', `FemaleText_loc1`='한때 인간 땅의 금 생산 중심지였던 죽음의 폐광은 이제 데피아즈 결사단이 차지하고 그 어두운 굴을 자신들만의 성소로 만들어 버렸습니다. 소문에 의하면, 이 도적단은 똑똑한 고블린들을 징집해 폐광 바닥에서 뭔가 끔찍한 것을 만드는 걸 돕도록 했다고 합니다만, 그게 무엇인지는 아직 확실하지 않습니다. 들리는 얘기로는, 죽음의 폐광으로 내려가는 길이 조용하고 평온해 보이는 달빛시내 마을에 있다고 하더군요.', `FemaleText_loc4`='这里曾经是人类最主要的产金地，希望矿井在部落第一次大战期间席卷暴风城的时候被废弃。现在迪菲亚兄弟会的人占据了那里并将这个黑暗的通道转变成他们的避难所。据说那些盗贼已经劝说了聪明的地精帮助他们在矿井的深处建造一些可怕的东西——但是没有人知道这是真的还是假的。有传言说，死亡矿井的入口在安宁的月溪镇中。', `FemaleText_loc5`='這裡曾經是人類最主要的產金地，希望礦坑在部落第一次大戰期間席捲暴風城的時候被廢棄。現在迪菲亞兄弟會的人佔據了那裡並將這個黑暗的通道轉變成他們的避難所。據說那些盜賊已經勸說了聰明的哥布林幫助他們在礦坑的深處建造一些可怕的東西─但是沒有人知道這是真的還是假的。有傳言說，死亡礦坑的入口在安寧的月溪鎮中。', `FemaleText_loc7`='Las Minas de la Muerte, antiguamente el mayor centro de producción de oro de las tierras humanas, están habitadas por la Hermandad Defias, que han convertido los oscuros túneles en su santuario privado. Se rumorea que los ladrones han reclutado a los astutos goblins, para ayudarles a construir algo terrible en la parte inferior de las minas, aunque se desconoce de qué se trata. Dicen que el camino que lleva a las Minas de la Muerte pasa por la tranquila y sencilla aldea Arroyo de la Luna.' WHERE `ID`=9892;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요즘처럼 힘든 전시에 포세이큰을 돕는 게 자네에게도 큰 득이 될 걸세. 난 같은 말을 되풀이하는 걸 좋아하지 않으니 잘 듣게나.$B$B지금 우린 옷감이 몹시 부족한 상태라 붕대와 옷을 만들 수 없다네... 그래서 줄어만 가는 재고를 채우기 위해 기부를 받고 있네. 착한 일을 했다고 금전적인 보상을 바라지는 말게나. 기부란 원래 그런 거니까 말이야. 그렇다고 자네의 도움을 완전히 무시하겠다는 얘기는 아니라네.', `MaleText_loc4`='你……现在是你帮助被遗忘者最好的时机。好好听着，我不喜欢重复我说过的话。$B$B我们现在极度缺乏布料。绷带和任何布料储存量都很低，我们希望接受捐赠来补充库存。你的捐赠不会有任何经济补偿——这就是捐赠的含义——你的捐赠一定会为我们所赏识。', `MaleText_loc5`='就是你...在這迫切的時期是你幫助被遺忘者最好的時機。好好聽著，我不喜歡重複我說過的話。$B$B我們現在極度缺乏布料。繃帶和任何布料儲存量都很低，我們希望接受捐贈來補充庫存。你的捐贈不會有任何經濟補償─這就是捐贈的含義─你的捐贈一定會為我們所賞識。', `MaleText_loc7`='¡Eh, tú! Por tu bien, debes ayudar a los Renegados en estos tiempos nefastos. Escucha atentamente, no me gusta repetirme.$B$BActualmente tenemos una terrible escasez de paño. Nos estamos quedando sin vendas y sin telas y aceptamos donaciones para aumentar los inventarios. Si bien no recibirás una compensación monetaria, por eso se llama donación, tu ayuda no pasará desapercibida.' WHERE `ID`=9893;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드의 친구여, 스톰윈드에서는 당신의 도움과 관대한 마음을 필요로 하고 있습니다!$B$B한때 그 많던 옷감 재고가 위태로울 정도로 바닥나 버렸습니다. 스톰윈드에서는 옷감과 붕대 생산을 위해 그 재고량을 다시 보충하기 위해 여러 각도의 노력을 기울이고 있습니다! 옷감을 기부하면 스톰윈드에 큰 도움이 될 뿐만 아니라 시민들의 존경도 받게 될 것입니다!', `MaleText_loc4`='朋友——暴风城需要你的协助和慷慨解囊！$B$B我们曾经储藏丰富的布料已经所剩不多了。暴风城现在需要大量的布料和绷带！你的捐赠将能够帮助暴风城度过难关，你还能赢得我们对你的尊重！', `MaleText_loc5`='朋友─暴風城需要你的協助和慷慨解囊!$B$B我們曾經儲藏豐富的布料已經所剩不多了。暴風城現在需要大量的布料和繃帶!你的捐贈將能夠幫助暴風城度過難關，你還能贏得我們對你的尊重!', `MaleText_loc7`='$gAmigo:Amiga; Ventormenta necesita tu ayuda y tu generosidad,$B$BNuestra antigua gran reserva de textiles está disminuyendo críticamente. Ventormenta se encuentra en pleno proceso a dos bandas para rellenar nuestras reservas para los fabricantes de telas y vendas. Tu donación de paños ayudaría inmensamente a Ventormenta, ¡y te proporcionaría el respeto de los ciudadanos!' WHERE `ID`=9894;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요! 아이언포지 드워프들의 존경을 한몸에 받고 싶다면 귀중한 물건을 기부하는 선행으로 시작해 보십시오! 아이언포지에서는 붕대나 옷을 만들 옷감이 턱없이 모자라요. 그런 귀한 물건들이 하늘에서 뚝 떨어지는 게 아니니까요!$B$B당신 같은 모험가라면 세상 곳곳을 여행하면서 다양한 옷감을 모으시겠죠?! 그냥 팔아 버리기보다는 기부를 통해 뜻 깊은 일에 쓰시는 게 어떠신가요?! 아이언포지 드워프 주민들의 존경과 인정을 받을 수도 있고 말이죠!', `FemaleText_loc4`='啊，你！如果你想要赢得铁炉堡矮人的尊重，那么你可以为我们捐赠有价值的资源！铁炉堡现在的布料和绷带的存储量很低！$B$B你可以捐赠各种你在冒险中得到的布料！这样一来，你就可以赢得铁炉堡矮人对你的尊重！', `FemaleText_loc5`='啊，你!如果你想要贏得鐵爐堡矮人的尊重，那麼你可以開始為我們捐贈有價值的資源!鐵爐堡現在的布料和繃帶的存儲量很低!$B$B你可以捐贈各種你在冒險中得到的布料!這樣做你可以贏得鐵爐堡矮人對你的尊重中!', `FemaleText_loc7`='¡Eh, tú! Si quieres conseguir el respeto de los enanos de Forjaz, ¡empieza a donar valiosos recursos! Forjaz se encuentra con una gran escasez de paños. Las telas y los vendas no crecen el los árboles, ¿sabes?$B$BEn lugar de vender los paños que te encuentras en tus aventuras, ¡dónalos! Hacerlo te proporcionará el respeto de los ciudadanos de Forjaz.' WHERE `ID`=9895;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성난불길 협곡은 오그리마 중심부에 있는 어둠의 틈 바로 밑에 있습니다.', `MaleText_loc4`='怒焰裂谷位于奥格瑞玛中心的暗影裂口。', `MaleText_loc5`='怒焰裂谷位於奧格瑪中心的暗影裂口。', `MaleText_loc7`='La Sima Ígnea está bajo el Circo de las Sombras, en el centro de Orgrimmar.', `FemaleText_loc1`='성난불길 협곡은 오그리마 중심부에 있는 어둠의 틈 바로 밑에 있습니다.', `FemaleText_loc4`='怒焰裂谷位于奥格瑞玛中心的暗影裂口。', `FemaleText_loc5`='怒焰裂谷位於奧格瑪中心的暗影裂口。', `FemaleText_loc7`='La Sima Ígnea está bajo el Circo de las Sombras, en el centro de Orgrimmar.' WHERE `ID`=9896;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 놈리건에서 떠날 수밖에 없었던 사태 때보다 훨씬 더 큰 곤경에 빠져 있어요! 좀 도와 주지 않을래요? 옷감이 모자라요!$B$B재고를 보충할 여분의 옷감이 있거든 좀 가져오세요. 남는 옷감을 기부하면 어딜 가나 우리 노움들의 신뢰와 존경을 받게 될 거예요. 그건 돈으로도 살 수 없는... 결국 옷감으로 사는 게 되겠지만, 지금 그게 중요한 게 아니니까...', `MaleText_loc4`='诺莫瑞根的流亡者需要大量的布料资源！也许你可以帮帮我们，是不是？$B$B把你多余的布料资源带给我们。通过捐献它们，你可以获得所有侏儒的尊重。这是金钱无法换得的！好吧，布料可以帮助我们，但是它们意义绝不限于这些……', `MaleText_loc5`='諾姆瑞根的流亡者需要大量的布料資源!也許你可以幫幫我們，是不是?$B$B把你多餘的布料資源帶給我們。通過捐獻它們，你可以獲得所有地精的尊重。這是金錢無法換的!好吧，布料可以幫助我們，但是它們意義絕不限於這些...', `MaleText_loc7`='Los Exiliados de Gnomeregan están en un terrible estado, ¡las reservas de paño se están agotando! ¿Quizás puedas ayudarnos, eh?$B$BTráeme paños que puedas tener para ayudarnos a llenar nuestras reservas. Con esa donación, te ganarás el respeto y la confianza de los gnomos de todas partes. ¡Y eso es algo que el dinero no puede comprar! Bueno, supongo que el paño sí lo puede comprar, pero eso va más allá de...' WHERE `ID`=9897;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에 대해 더 자세히 말씀해 주시겠습니까?', `MaleText_loc4`='告诉我更多关于这个地方的信息？', `MaleText_loc5`='告訴我更多關於這個地方的資訊?', `MaleText_loc7`='¿Puedes hablarme más sobre este lugar?', `FemaleText_loc1`='이곳에 대해 더 자세히 말씀해 주시겠습니까?', `FemaleText_loc4`='告诉我更多关于这个地方的信息？', `FemaleText_loc5`='告訴我更多關於這個地方的資訊?', `FemaleText_loc7`='¿Puedes hablarme más sobre este lugar?' WHERE `ID`=9898;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='통곡의 동굴 입구는 불모의 땅에 있는 십자로에서 남서쪽으로 가면 찾을 수 있는 푸른 오아시스에 있습니다.', `MaleText_loc4`='哀嚎洞穴的入口位于贫瘠之地十字路口西南边的甜水绿洲。', `MaleText_loc5`='哀嚎洞穴的入口位於貧瘠之地十字路口西南邊甜水綠洲。', `MaleText_loc7`='La entrada de las Cuevas de los Lamentos está en el Oasis Aguaverde, al suroeste de El Cruce, en Los Baldíos.', `FemaleText_loc1`='통곡의 동굴 입구는 불모의 땅에 있는 십자로에서 남서쪽으로 가면 찾을 수 있는 푸른 오아시스에 있습니다.', `FemaleText_loc4`='哀嚎洞穴的入口位于贫瘠之地十字路口西南边的甜水绿洲。', `FemaleText_loc5`='哀嚎洞穴的入口位於貧瘠之地十字路口西南邊甜水綠洲。', `FemaleText_loc7`='La entrada de las Cuevas de los Lamentos está en el Oasis Aguaverde, al suroeste de El Cruce, en Los Baldíos.' WHERE `ID`=9899;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하시오, 친구여... 괜찮다면 잠시 시간을 내서 이야기를 들어주시오.$B$B우린 텔드랏실을 일으켜 세우는 데 많은 고난과 시련을 겪어 왔소. 계속되는 고난으로도 모자라 이제는 옷감까지 부족하구려. 혹시라도 여분이 있다면 부디 기부해 주시오. 우리를 도와 주면 어디서든 나이트 엘프의 친구로 대접받게 될 것이오!', `MaleText_loc4`='嘿，朋友——请等一下，如果可以的话……$B$B我们在重建泰达希尔的过程中经历了很多的痛苦。现在，我们不仅要忍受这些痛苦，而且我们还发现我们的布料存储已经很少了。如果你有多余的布料，那我希望你可以捐赠出它们。你一定因为帮助暗夜精灵赢得我们的尊重！', `MaleText_loc5`='嘿，朋友─請等一下，如果可以的話...$b$b我們在重建泰達希爾的過程中經歷了很多的痛苦。現在，我們不僅要忍受這些痛苦，而且我們還發現我們的布料存儲已經很少了。如果你有多餘的布料，那我希望你可以捐贈出它們。你一定因為幫助夜精靈贏得我們的尊重!', `MaleText_loc7`='Hola, $gamigo:amiga;, me gustaría hablar contigo unos minutos, si es posible.$B$BHemos sufrido muchos problemas y tribulaciones para establecer Teldrassil. Por si no fuera bastante con los constantes conflictos, ahora nos encontramos con una gran escasez de paño. Si te sobran materiales, te ruego que los dones. Te ganarás la gratitud de los elfos de la noche de todas partes por ayudarnos.' WHERE `ID`=9900;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그림자송곳니 성채는 은빛소나무 숲 남쪽, 장작나무 마을 바로 북쪽에 있습니다.', `MaleText_loc4`='影牙城堡位于南部银松森林，就在焚木村的北面。', `MaleText_loc5`='影牙城堡位於南部銀松森林，就在焚木村的北面。', `MaleText_loc7`='El Castillo de Colmillo Oscuro está en la parte sur de Argénteos, justo al norte de la Aldea Piroleña.', `FemaleText_loc1`='그림자송곳니 성채는 은빛소나무 숲 남쪽, 장작나무 마을 바로 북쪽에 있습니다.', `FemaleText_loc4`='影牙城堡位于南部银松森林，就在焚木村的北面。', `FemaleText_loc5`='影牙城堡位於南部銀松森林，就在焚木村的北面。', `FemaleText_loc7`='El Castillo de Colmillo Oscuro está en la parte sur de Argénteos, justo al norte de la Aldea Piroleña.' WHERE `ID`=9901;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 실수하지 않았습니다.', `MaleText_loc4`='我从不犯错。', `MaleText_loc5`='我從不犯錯。', `MaleText_loc7`='No he cometido ningún error.', `FemaleText_loc1`='전 실수하지 않았습니다.', `FemaleText_loc4`='我从不犯错。', `FemaleText_loc5`='我從不犯錯。', `FemaleText_loc7`='No he cometido ningún error.' WHERE `ID`=9902;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영광을 구하며 돌진하던 너는 만사가 네 행동에 의해 좌우된다고 믿었지. 나 같은 존재에게는 그게 얼마나 터무니없어 보이는 일인지 상상이나 할 수 있겠나? 나는 원한다면 네놈의 보잘것없는 생각이 네 머릿속에 떠다니는 땅콩만한 잿빛 덩어리를 짓뭉개 버리도록 할 수도 있는 존재란 말이다.', `MaleText_loc4`='在你匆忙追寻荣耀的过程中，你有没有想过你的行动对于这场竞赛的节奏有什么影响？你有没有想过你们的行为对我来说是多么可笑而荒谬？我对你来说是个难以理解的存在，这让你那花生大小的脑子感到十分迷茫。', `MaleText_loc5`='在你匆忙追尋榮耀的過程中，你有沒有想過你的行動對於遊戲的節奏影響。你是否感覺我說的話很荒謬!我所說的話都是如此哲理化，這讓你頭顱裡那花生大小的東西感到十分迷茫。', `MaleText_loc7`='En tu prisa por conseguir la gloria, has asumido que el ritmo del juego se cernía por tus acciones. ¿Puedes imaginarte lo absurdo que eso le suena a un ser como yo? ¿Un ser que, si lo quisiera, podría hacer que tus insignificantes pensamientos aplastasen la diminuta masa de materia gris que flota por tu cerebro?' WHERE `ID`=9903;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미쳐 버렸군요, 네파리우스. 수수께끼 같은 말만 내뱉다니...', `MaleText_loc4`='你已经失去理智了，奈法里奥斯。你在胡言乱语。', `MaleText_loc5`='你已經失去理智，奈法利斯。你在說什麼啞謎。', `MaleText_loc7`='Has perdido la cabeza, Nefarius. Hablas con acertijos.', `FemaleText_loc1`='미쳐 버렸군요, 네파리우스. 수수께끼 같은 말만 내뱉다니...', `FemaleText_loc4`='你已经失去理智了，奈法里奥斯。你在胡言乱语。', `FemaleText_loc5`='你已經失去理智，奈法利斯。你在說什麼啞謎。', `FemaleText_loc7`='Has perdido la cabeza, Nefarius. Hablas con acertijos.' WHERE `ID`=9904;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실은 간단하다. 내가 요약해 주지...', `MaleText_loc4`='这是真的。请允许我总结一下……', `MaleText_loc5`='這是真的。請允許我總結一下...', `MaleText_loc7`='Realmente es simple. Permíteme que te lo resuma...' WHERE `ID`=9905;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋습니다.', `MaleText_loc4`='请继续。', `MaleText_loc5`='請繼續。', `MaleText_loc7`='Hazlo, por favor.', `FemaleText_loc1`='좋습니다.', `FemaleText_loc4`='请继续。', `FemaleText_loc5`='請繼續。', `FemaleText_loc7`='Hazlo, por favor.' WHERE `ID`=9906;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간이 너의 적인 이 세계에서 그 시간이 나의 가장 위대한 동료다. 네가 네 맘대로 조종하고 있다고 믿는 인생이란 놀이가 사실은 널 갖고 놀고 있는 것이지. 그러니까 내 말은...', `MaleText_loc4`='在这个世界中，时间是你的敌人，但是它是我的战友。这段你自以为在你掌握之中的时光实际上是你的主宰。因此我会说……', `MaleText_loc5`='在這個世界中，時間是你的敵人，但是它是我的戰友。這段你進行遊戲的時光其實反過來在遊戲你。因此我會說...', `MaleText_loc7`='En este mundo donde el tiempo es tu enemigo, es mi mayor aliado. Este gran juego de la vida que crees jugar, en realidad juega contigo. Y yo digo...' WHERE `ID`=9907;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈리건', `MaleText_loc4`='诺莫瑞根', `MaleText_loc5`='諾姆瑞根', `MaleText_loc7`='Gnomeregan', `FemaleText_loc1`='놈리건', `FemaleText_loc4`='诺莫瑞根', `FemaleText_loc5`='諾姆瑞根', `FemaleText_loc7`='Gnomeregan' WHERE `ID`=9908;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은심연 나락', `MaleText_loc4`='黑暗深渊', `MaleText_loc5`='黑澗深淵', `MaleText_loc7`='Cavernas de Brazanegra', `FemaleText_loc1`='검은심연 나락', `FemaleText_loc4`='黑暗深渊', `FemaleText_loc5`='黑澗深淵', `FemaleText_loc7`='Cavernas de Brazanegra' WHERE `ID`=9909;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은심연 나락은 잿빛 골짜기 해안을 따라 가면 있는 조람 해안 북쪽 끝에서 찾을 수 있습니다.', `MaleText_loc4`='黑暗深渊位于灰谷海岸佐拉姆海岸的最北部。', `MaleText_loc5`='黑澗深淵位於梣谷海岸佐拉姆海岸的最北部。', `MaleText_loc7`='Puedes encontrar las Cavernas de Brazanegra en el extremo norte de La Ensenada de Zoram, junto a la costa de Vallefresno.', `FemaleText_loc1`='검은심연 나락은 잿빛 골짜기 해안을 따라 가면 있는 조람 해안 북쪽 끝에서 찾을 수 있습니다.', `FemaleText_loc4`='黑暗深渊位于灰谷海岸佐拉姆海岸的最北部。', `FemaleText_loc5`='黑澗深淵位於梣谷海岸佐拉姆海岸的最北部。', `FemaleText_loc7`='Puedes encontrar las Cavernas de Brazanegra en el extremo norte de La Ensenada de Zoram, junto a la costa de Vallefresno.' WHERE `ID`=9910;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잿빛 골짜기의 조람 해안에 위치한 검은심연 나락은 한때 나이트 엘프들의 달의 여신 엘룬에게 바쳐진 영광스러운 신전이었다고 합니다. 하지만 세계의 분리로 인해 신전이 파괴되어 장막의 바다의 물결 아래로 가라앉아 버렸지요. 그곳에 그 모습 그대로 남았는데, 나가와 사티로스가 그 고대 마력에 이끌려 등장하더니 신전의 비밀을 캐내기 시작했습니다. 전설에 의하면, 고대 괴물 아쿠마이가 그 신전의 폐허 안에 자리 잡고 있다고 합니다.', `MaleText_loc4`='位于灰谷佐拉姆海岸的黑暗深渊曾经是为供奉暗夜精灵月神艾露尼尔建造的。然而，在大分裂中，神庙受到极大的冲击然后沉入了海中。它一直保持着原样——直到，其蕴含的古老的力量吸引来了纳迦和萨特。传说，古代怪兽阿库麦尔就居住在神庙遗迹中。作为古代之神最喜欢的宠物之一，阿库麦尔就一直生活在这个地区进行捕食。在阿库麦尔的吸引下，一群被称作幕光之锤的教徒也聚集在这里从事邪恶的勾当。', `MaleText_loc5`='位於梣谷佐拉姆海岸的黑澗深淵曾經是為供奉夜精靈月神伊露恩建造的。然而，在大爆炸中，神廟受到極大的衝擊然後沉入了海中。它一直保持著原樣─直到，其蘊含的古老的力量吸引來了納迦和薩特。傳說，古老怪獸阿庫麥爾就居住在神廟遺跡中。', `MaleText_loc7`='Las Cavernas de Brazanegra, en La Ensenada de Zoram, en Vallefresno, fueron antiguamente un glorioso templo de los elfos de la noche dedicado a la diosa de la luna, Elune. Sin embargo, el Gran Cataclismo destruyó el templo, hundiéndolo bajo las olas del Mar de la Bruma. Y ahí permaneció, intacto, hasta que los nagas y los sátiros, atraídos por su ancestral poder, fueron en su busca para descubrir sus secretos. Según las leyendas, Aku''mai, la bestia ancestral, vive en las ruinas del templo.', `FemaleText_loc1`='잿빛 골짜기의 조람 해안에 위치한 검은심연 나락은 한때 나이트 엘프들의 달의 여신 엘룬에게 바쳐진 영광스러운 신전이었다고 합니다. 하지만 세계의 분리로 인해 신전이 파괴되어 장막의 바다의 물결 아래로 가라앉아 버렸지요. 그곳에 그 모습 그대로 남았는데, 나가와 사티로스가 그 고대 마력에 이끌려 등장하더니 신전의 비밀을 캐내기 시작했습니다. 전설에 의하면, 고대 괴물 아쿠마이가 그 신전의 폐허 안에 자리 잡고 있다고 합니다.', `FemaleText_loc4`='位于灰谷佐拉姆海岸的黑暗深渊曾经是为供奉暗夜精灵月神艾露尼尔建造的。然而，在大分裂中，神庙受到极大的冲击然后沉入了海中。它一直保持着原样——直到，其蕴含的古老的力量吸引来了纳迦和萨特。传说，古代怪兽阿库麦尔就居住在神庙遗迹中。作为古代之神最喜欢的宠物之一，阿库麦尔就一直生活在这个地区进行捕食。在阿库麦尔的吸引下，一群被称作幕光之锤的教徒也聚集在这里从事邪恶的勾当。', `FemaleText_loc5`='位於梣谷佐拉姆海岸的黑澗深淵曾經是為供奉夜精靈月神伊露恩建造的。然而，在大爆炸中，神廟受到極大的衝擊然後沉入了海中。它一直保持著原樣─直到，其蘊含的古老的力量吸引來了納迦和薩特。傳說，古老怪獸阿庫麥爾就居住在神廟遺跡中。', `FemaleText_loc7`='Las Cavernas de Brazanegra, en La Ensenada de Zoram, en Vallefresno, fueron antiguamente un glorioso templo de los elfos de la noche dedicado a la diosa de la luna, Elune. Sin embargo, el Gran Cataclismo destruyó el templo, hundiéndolo bajo las olas del Mar de la Bruma. Y ahí permaneció, intacto, hasta que los nagas y los sátiros, atraídos por su ancestral poder, fueron en su busca para descubrir sus secretos. Según las leyendas, Aku''mai, la bestia ancestral, vive en las ruinas del templo.' WHERE `ID`=9911;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈리건은 던 모로 서쪽에 있습니다.', `MaleText_loc4`='诺莫瑞根在丹莫洛的西边。', `MaleText_loc5`='諾姆瑞根在丹莫洛的西邊。', `MaleText_loc7`='Gnomeregan se encuentra en la parte oeste de Dun Morogh.', `FemaleText_loc1`='놈리건은 던 모로 서쪽에 있습니다.', `FemaleText_loc4`='诺莫瑞根在丹莫洛的西边。', `FemaleText_loc5`='諾姆瑞根在丹莫洛的西邊。', `FemaleText_loc7`='Gnomeregan se encuentra en la parte oeste de Dun Morogh.' WHERE `ID`=9913;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='던 모로에 위치한 놈리건은 최근 돌연 변이 트로그들이 출몰하고는 있지만 아주 오랜 세월 동안 노움들의 수도였습니다. 보복을 위해 필사적으로 노력하던 땜장이왕 멕카토크는 놈리건의 방사성 폐기물 탱크의 비상 배출을 명령했지요. 트로그들은 방사선에 노출되었지만, 그들의 공성 기세는 약화하지 않았고 노움들은 드워프족의 도시 아이언포지로 피신할 수밖에 없었습니다. 땜장이왕은 이제 아이언포지에서 자신들의 사랑하는 수도를 되찾는 일을 도와 줄 용기 있는 자들을 모집하고 있습니다.', `MaleText_loc4`='位于丹莫洛的科技奇迹城市诺莫瑞根世代以来都是侏儒的主城。最近，一群邪恶的变异食鄂怪侵入了包括侏儒主城在内的多处丹莫洛地区。为了做出殊死一搏来干掉入侵的食腭怪，大工匠梅卡托克命令打开城市中的紧急辐射水箱。侏儒在等待那些食腭怪死亡或者逃跑的同时也在寻找躲避辐射的方法。不幸的是，虽然食腭怪在经过辐射之后感染了毒性——但是它们的攻击没有停止，也没有丝毫的减弱。那些没有被辐射杀死的注入被迫逃离，他们在附近的矮人城市铁炉堡找到了安身之处。大工匠梅卡托克组建了一个智囊团来商议重新夺回他们挚爱的城市的计划。', `MaleText_loc5`='位於丹莫洛的科技奇蹟城市諾姆瑞根世代以來都是地精的主城。最近，一群邪惡的變異穴居怪侵入了包括地精主城在內的多處丹莫洛地區。為了做出殊死一搏來幹掉入侵的穴居怪，大工匠梅卡托克命令打開城市中的緊急輻射水箱。地精在等待那些穴居怪死亡或者逃跑的同時也在尋找躲避輻射的方法。不幸的是，雖然穴居怪在經過輻射之後感染了毒性─但是它們的攻擊沒有停止，也沒有絲毫的減弱。那些沒有被輻射殺死的地精不得不逃出來，他們在附近的矮人城市鐵爐堡找到了安身之處。大工匠梅卡托克組建了一個智囊團來商議重新奪回他們摯愛的城市的計畫。', `MaleText_loc7`='Situada en Dun Morogh, Gnomeregan ha sido la capital de los gnomos durante generaciones aunque, recientemente, ha sido tomada por unos troggs mutantes. En un intento desesperado de contraataque, el Manitas Mayor Mekkatorque, ordenó la apertura de emergencia de los tanques de residuos radioactivos de la ciudad. Si bien los troggs recibieron la radiación, su asedio continuó implacable y los gnomos se vieron forzados a refugiarse en la ciudad enana de Forjaz, donde el Manitas Mayor, ahora recluta almas valientes para ayudar a su pueblo a reconquistar su amada ciudad.', `FemaleText_loc1`='던 모로에 위치한 놈리건은 최근 돌연 변이 트로그들이 출몰하고는 있지만 아주 오랜 세월 동안 노움들의 수도였습니다. 보복을 위해 필사적으로 노력하던 땜장이왕 멕카토크는 놈리건의 방사성 폐기물 탱크의 비상 배출을 명령했지요. 트로그들은 방사선에 노출되었지만, 그들의 공성 기세는 약화하지 않았고 노움들은 드워프족의 도시 아이언포지로 피신할 수밖에 없었습니다. 땜장이왕은 이제 아이언포지에서 자신들의 사랑하는 수도를 되찾는 일을 도와 줄 용기 있는 자들을 모집하고 있습니다.', `FemaleText_loc4`='位于丹莫洛的科技奇迹城市诺莫瑞根世代以来都是侏儒的主城。最近，一群邪恶的变异食鄂怪侵入了包括侏儒主城在内的多处丹莫洛地区。为了做出殊死一搏来干掉入侵的食腭怪，大工匠梅卡托克命令打开城市中的紧急辐射水箱。侏儒在等待那些食腭怪死亡或者逃跑的同时也在寻找躲避辐射的方法。不幸的是，虽然食腭怪在经过辐射之后感染了毒性——但是它们的攻击没有停止，也没有丝毫的减弱。那些没有被辐射杀死的注入被迫逃离，他们在附近的矮人城市铁炉堡找到了安身之处。大工匠梅卡托克组建了一个智囊团来商议重新夺回他们挚爱的城市的计划。', `FemaleText_loc5`='位於丹莫洛的科技奇蹟城市諾姆瑞根世代以來都是地精的主城。最近，一群邪惡的變異穴居怪侵入了包括地精主城在內的多處丹莫洛地區。為了做出殊死一搏來幹掉入侵的穴居怪，大工匠梅卡托克命令打開城市中的緊急輻射水箱。地精在等待那些穴居怪死亡或者逃跑的同時也在尋找躲避輻射的方法。不幸的是，雖然穴居怪在經過輻射之後感染了毒性─但是它們的攻擊沒有停止，也沒有絲毫的減弱。那些沒有被輻射殺死的地精不得不逃出來，他們在附近的矮人城市鐵爐堡找到了安身之處。大工匠梅卡托克組建了一個智囊團來商議重新奪回他們摯愛的城市的計畫。', `FemaleText_loc7`='Situada en Dun Morogh, Gnomeregan ha sido la capital de los gnomos durante generaciones aunque, recientemente, ha sido tomada por unos troggs mutantes. En un intento desesperado de contraataque, el Manitas Mayor Mekkatorque, ordenó la apertura de emergencia de los tanques de residuos radioactivos de la ciudad. Si bien los troggs recibieron la radiación, su asedio continuó implacable y los gnomos se vieron forzados a refugiarse en la ciudad enana de Forjaz, donde el Manitas Mayor, ahora recluta almas valientes para ayudar a su pueblo a reconquistar su amada ciudad.' WHERE `ID`=9914;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가시덩굴 우리', `MaleText_loc4`='剃刀沼泽', `MaleText_loc5`='剃刀沼澤', `MaleText_loc7`='Horado Rajacieno', `FemaleText_loc1`='가시덩굴 우리', `FemaleText_loc4`='剃刀沼泽', `FemaleText_loc5`='剃刀沼澤', `FemaleText_loc7`='Horado Rajacieno' WHERE `ID`=9915;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가시덩굴 우리는 불모의 땅 남단, 길 서쪽에 있습니다.', `MaleText_loc4`='剃刀沼泽位于贫瘠之地最南端的大路西边。', `MaleText_loc5`='剃刀沼澤位於貧瘠之地最南端的大路西邊。', `MaleText_loc7`='Horado Rajacieno se encuentra en el extremo más al sur de Los Baldíos, en el lado oeste del camino.', `FemaleText_loc1`='가시덩굴 우리는 불모의 땅 남단, 길 서쪽에 있습니다.', `FemaleText_loc4`='剃刀沼泽位于贫瘠之地最南端的大路西边。', `FemaleText_loc5`='剃刀沼澤位於貧瘠之地最南端的大路西邊。', `FemaleText_loc7`='Horado Rajacieno se encuentra en el extremo más al sur de Los Baldíos, en el lado oeste del camino.' WHERE `ID`=9916;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고대의 전쟁 동안, 반신 아감마간은 불타는 군단과 싸우기 위해 나섰습니다. 그 거대한 멧돼지는 패배했고 그가 피를 흘린 자리에서는 시간이 지나자 가시 돋친 덩굴이 자라났지요. 이 지역을 점령한 가시멧돼지들은 이곳을 성지로 받들고 있습니다. 이 거대한 가시덩굴 지역의 중심부에 바로 가시덩굴 우리가 있답니다. 가시덩굴 우리는 서슬깃 차를가라는 노파가 점령했는데, 혹자들은 그 노파가 어떤 교활한 목적을 위해 스컬지 요원들과 내통을 하고 있다고 추측하고 있습니다.', `MaleText_loc4`='在一万年前的上古战争中，强大的半神阿迦玛甘和燃烧军团进行了激战。虽然这头巨大的野猪在战斗中倒下了，但是他的努力最终令艾泽拉斯免遭涂炭。很久之后，在它血液流淌过的地方长出了巨大的荆棘藤蔓。那些被认为是半神后代的野猪人占领了这些地区，并将其奉为圣地。这些荆棘地的中心被称为剃刀岭，而巨大的剃刀沼泽则被一个老丑婆卡尔加·刺肋所占据。在她的统治下，信奉萨满教的野猪人和其他的部族为敌。有些人甚至猜测卡尔加还在和亡灵天灾有来往——她想要联合亡灵天灾以达到一些不可告人的险恶目的。', `MaleText_loc5`='在一萬年前的先祖之戰中，萬能的半神阿迦瑪甘和燃燒軍團進行了激戰。雖然這頭巨大的野豬在戰鬥中倒下了，但是他的努力最終拯救了艾澤拉斯大陸免遭塗炭。雖然已經過去了很久，但是在它血液流淌的地方巨大的荊棘藤蔓生長出來。那些被認為是半神後代的野豬人佔領了這些地區並將其奉為聖地。這些荊棘地的中心被稱為剃刀嶺。而巨大的剃刀沼澤則被一個老巫婆卡爾加·刺肋所佔據。在她的統治下，信奉薩滿教的野豬人和別的部族以及部落為敵。有些人甚至猜測卡爾加還在和天譴軍團的有來往─她想要聯合天譴軍團來達到一些不可告人的險惡目的。', `MaleText_loc7`='Durante la Guerra de los Ancestros, el semidiós Agamaggan luchó contra la Legión Ardiente. El colosal jabalí fue derrotado y, con el tiempo, en las zonas donde su sangre se había derramado, brotaron unas enormes vides llenas de espinas. Los jabaespines vinieron a ocupar estas regiones y encargarse de que se mantuvieran como un terreno sagrado. El corazón de estas enormes colonias de espinas es Rajacieno. El brujo Charlga Filonavaja conquistó Horado Rajacieno y se dice que ha estado negociando con agentes de la Plaga con algún propósito insidioso.', `FemaleText_loc1`='고대의 전쟁 동안, 반신 아감마간은 불타는 군단과 싸우기 위해 나섰습니다. 그 거대한 멧돼지는 패배했고 그가 피를 흘린 자리에서는 시간이 지나자 가시 돋친 덩굴이 자라났지요. 이 지역을 점령한 가시멧돼지들은 이곳을 성지로 받들고 있습니다. 이 거대한 가시덩굴 지역의 중심부에 바로 가시덩굴 우리가 있답니다. 가시덩굴 우리는 서슬깃 차를가라는 노파가 점령했는데, 혹자들은 그 노파가 어떤 교활한 목적을 위해 스컬지 요원들과 내통을 하고 있다고 추측하고 있습니다.', `FemaleText_loc4`='在一万年前的上古战争中，强大的半神阿迦玛甘和燃烧军团进行了激战。虽然这头巨大的野猪在战斗中倒下了，但是他的努力最终令艾泽拉斯免遭涂炭。很久之后，在它血液流淌过的地方长出了巨大的荆棘藤蔓。那些被认为是半神后代的野猪人占领了这些地区，并将其奉为圣地。这些荆棘地的中心被称为剃刀岭，而巨大的剃刀沼泽则被一个老丑婆卡尔加·刺肋所占据。在她的统治下，信奉萨满教的野猪人和其他的部族为敌。有些人甚至猜测卡尔加还在和亡灵天灾有来往——她想要联合亡灵天灾以达到一些不可告人的险恶目的。', `FemaleText_loc5`='在一萬年前的先祖之戰中，萬能的半神阿迦瑪甘和燃燒軍團進行了激戰。雖然這頭巨大的野豬在戰鬥中倒下了，但是他的努力最終拯救了艾澤拉斯大陸免遭塗炭。雖然已經過去了很久，但是在它血液流淌的地方巨大的荊棘藤蔓生長出來。那些被認為是半神後代的野豬人佔領了這些地區並將其奉為聖地。這些荊棘地的中心被稱為剃刀嶺。而巨大的剃刀沼澤則被一個老巫婆卡爾加·刺肋所佔據。在她的統治下，信奉薩滿教的野豬人和別的部族以及部落為敵。有些人甚至猜測卡爾加還在和天譴軍團的有來往─她想要聯合天譴軍團來達到一些不可告人的險惡目的。', `FemaleText_loc7`='Durante la Guerra de los Ancestros, el semidiós Agamaggan luchó contra la Legión Ardiente. El colosal jabalí fue derrotado y, con el tiempo, en las zonas donde su sangre se había derramado, brotaron unas enormes vides llenas de espinas. Los jabaespines vinieron a ocupar estas regiones y encargarse de que se mantuvieran como un terreno sagrado. El corazón de estas enormes colonias de espinas, es Rajacieno. El brujo Charlga Filonavaja conquistó Horado Rajacieno, de quien se dice que ha estado negociando con agentes de la Plaga con algún propósito insidioso.' WHERE `ID`=9917;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='붉은십자군 수도원', `MaleText_loc4`='血色修道院', `MaleText_loc5`='血色修道院', `MaleText_loc7`='Monasterio Escarlata', `FemaleText_loc1`='붉은십자군 수도원', `FemaleText_loc4`='血色修道院', `FemaleText_loc5`='血色修道院', `FemaleText_loc7`='Monasterio Escarlata' WHERE `ID`=9918;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='붉은십자군 수도원은 티리스팔 숲 북동쪽에 있는 언덕에 있습니다.', `MaleText_loc4`='血色修道院位于提瑞斯法林地东北部的山坡上。', `MaleText_loc5`='血色修道院位於提里斯法林地東北部的山坡上。', `MaleText_loc7`='El Monasterio Escarlata está en las colinas al noroeste de los Claros de Tirisfal.', `FemaleText_loc1`='붉은십자군 수도원은 티리스팔 숲 북동쪽에 있는 언덕에 있습니다.', `FemaleText_loc4`='血色修道院位于提瑞斯法林地东北部的山坡上。', `FemaleText_loc5`='血色修道院位於提里斯法林地東北部的山坡上。', `FemaleText_loc7`='El Monasterio Escarlata está en las colinas al noroeste de los Claros de Tirisfal.' WHERE `ID`=9919;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수도원은 한때 학문과 계몽의 중심지였습니다. 3차 대전쟁 당시 언데드 스컬지가 봉기하자 이 평화로운 수도원은 광신적인 붉은십자군의 요새로 바뀌었습니다. 붉은십자군은 인간이 아니라면 동맹이나 소속에 관여치 않고 관용을 보이지 않습니다. 그들은 외부인이라면 누구나 잠재적인 언데드 역병 보균자로 보고 그들을 처치해야 한다고 믿습니다.', `MaleText_loc4`='血色修道院曾经是洛丹伦王国牧师的荣耀之地——那里是学习圣光知识和膜拜的中心。随着在第三次大战中亡灵天灾的崛起，宁静的修道院成为了疯狂的血色十字军的要塞。十字军对于所有非人类都有着偏激的态度，无论他们是自己的盟友还是对手。他们相信所有任何外来者都带着亡灵的诅咒——他们必须被摧毁。', `MaleText_loc5`='血色修道院曾經是羅德隆王國牧師的榮耀之地─那裡是學習聖光知識和膜拜的中心。隨著在第三次大戰中天譴軍團的崛起，寧靜的修道院成為了瘋狂的血色十字軍的要塞。十字軍對於所有非人類都有著偏激的態度，無論他們是自己的盟友還是對手。他們相信所有任何外來者都帶著亡靈的瘟疫─他們必須被摧毀。', `MaleText_loc7`='El Monasterio fue antiguamente un centro de aprendizaje y conocimiento. Con la Plaga de los no-muertos durante la Tercera Guerra, el pacífico Monasterio se convirtió en una fortaleza de la fanática Cruzada Escarlata. Los Cruzados no toleran a ninguna raza que no sea la humana, sin tener en cuenta alianzas ni afiliaciones. Creen que todos los forasteros son portadores potenciales de la peste, y deben ser destruidos.', `FemaleText_loc1`='수도원은 한때 학문과 계몽의 중심지였습니다. 3차 대전쟁 당시 언데드 스컬지가 봉기하자 이 평화로운 수도원은 광신적인 붉은십자군의 요새로 바뀌었습니다. 붉은십자군은 인간이 아니라면 동맹이나 소속에 관여치 않고 관용을 보이지 않습니다. 그들은 외부인이라면 누구나 잠재적인 언데드 역병 보균자로 보고 그들을 처치해야 한다고 믿습니다.', `FemaleText_loc4`='血色修道院曾经是洛丹伦王国牧师的荣耀之地——那里是学习圣光知识和膜拜的中心。随着在第三次大战中亡灵天灾的崛起，宁静的修道院成为了疯狂的血色十字军的要塞。十字军对于所有非人类都有着偏激的态度，无论他们是自己的盟友还是对手。他们相信所有任何外来者都带着亡灵的诅咒——他们必须被摧毁。', `FemaleText_loc5`='血色修道院曾經是羅德隆王國牧師的榮耀之地─那裡是學習聖光知識和膜拜的中心。隨著在第三次大戰中天譴軍團的崛起，寧靜的修道院成為了瘋狂的血色十字軍的要塞。十字軍對於所有非人類都有著偏激的態度，無論他們是自己的盟友還是對手。他們相信所有任何外來者都帶著亡靈的瘟疫─他們必須被摧毀。', `FemaleText_loc7`='El Monasterio fue antiguamente un centro de aprendizaje y conocimiento. Con la Plaga de los no-muertos durante la Tercera Guerra, el pacífico Monasterio se convirtió en una fortaleza de la fanática Cruzada Escarlata. Los Cruzados no toleran a ninguna raza que no sea la humana, sin tener en cuenta alianzas ni afiliaciones. Creen que todos los forasteros son portadores potenciales de la peste de los no-muertos, y deben ser destruidos.' WHERE `ID`=9920;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가시덩굴 구릉', `MaleText_loc4`='剃刀高地', `MaleText_loc5`='剃刀高地', `MaleText_loc7`='Zahúrda Rajacieno', `FemaleText_loc1`='가시덩굴 구릉', `FemaleText_loc4`='剃刀高地', `FemaleText_loc5`='剃刀高地', `FemaleText_loc7`='Zahúrda Rajacieno' WHERE `ID`=9921;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가시덩굴 구릉은 불모의 땅 남단, 길 동쪽에 있습니다.', `MaleText_loc4`='剃刀高地位于贫瘠之地最南端的大路东边。', `MaleText_loc5`='剃刀高地位於貧瘠之地最南端的大路東邊。', `MaleText_loc7`='Zahúrda Rajacieno se encuentra en el extremo más al sur de Los Baldíos, en el lado este del camino.', `FemaleText_loc1`='가시덩굴 구릉은 불모의 땅 남단, 길 동쪽에 있습니다.', `FemaleText_loc4`='剃刀高地位于贫瘠之地最南端的大路东边。', `FemaleText_loc5`='剃刀高地位於貧瘠之地最南端的大路東邊。', `FemaleText_loc7`='Zahúrda Rajacieno se encuentra en el extremo más al sur de Los Baldíos, en el lado este del camino.' WHERE `ID`=9922;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가시덩굴 우리처럼 가시덩굴이 우거진 가시덩굴 구릉은 가시멧돼지의 전통적인 수도였습니다. 가시 덩굴이 얼기설기 퍼진 이 미궁에는 가시멧돼지 귀족들의 충실한 군대는 물론 대사제들 즉, 죽음의 머리교 일족이 살고 있습니다. 최근 이 조잡한 은신처에 기분 나쁜 그림자가 드리워지고 있습니다. 혹한의 암네나르가 이끄는 언데드 스컬지 요원들이 가시멧돼지를 지배하고 그들의 가시 미궁을 언데드 군단의 요새로 만든 것입니다.', `MaleText_loc4`='剃刀高地和剃刀沼泽一样由巨大的藤蔓组成，剃刀高地是野猪人的传统都城。在那错综复杂的荆棘迷宫中居住着大群忠诚的野猪人军队，以及他们的高等祭司——亡首部族。然而最近，一股黑暗的力量笼罩了这座原始的洞穴。亡灵天灾的爪牙在巫妖寒冰之王亚门纳尔的带领下控制了野猪部族，并将布满荆棘的迷宫变成了亡灵力量的堡垒。现在野猪人正在奋力战斗来夺回他们的城市，并阻止亚门纳尔继续控制贫瘠之地。', `MaleText_loc5`='剃刀高地和剃刀沼澤一樣由巨大的藤蔓組成，剃刀高地是野豬人的傳統都城。在那錯綜複雜的荊棘迷宮中居住著大群忠誠的野豬人軍隊以及他們的高階牧師─亡首部族。然而最近，一股陰影力量籠罩了這個原始的洞穴。天譴軍團的人在巫妖『寒冰使者』亞門納爾的帶領下控制了野豬部族並將荊棘迷宮變成了亡靈力量的堡壘。現在野豬人正奮力戰鬥來重新奪回他們的城市，並阻止亞門納爾繼續控制貧瘠之地。', `MaleText_loc7`='Construida con las mismas vides que Horado Rajacieno, Zahúrda Rajacieno es la capital tradicional de la raza de los jabaespines. El laberinto de espinas que se extiende por todas partes, aloja un verdadero ejército de leales jabaespines junto con sus altos sacerdotes, la tribu Caramuerte. Sin embargo, recientemente una sombra de mal presagio ha caído sobre la rudimentaria guarida. Unos agentes de la Plaga de los no-muertos, a las órdenes del exánime Amnennar el Gélido, han tomado el control de la raza de los jabaespines y han convertido el laberinto de espinas en un bastión del poder de los no-muertos.', `FemaleText_loc1`='가시덩굴 우리처럼 가시덩굴이 우거진 가시덩굴 구릉은 가시멧돼지의 전통적인 수도였습니다. 가시 덩굴이 얼기설기 퍼진 이 미궁에는 가시멧돼지 귀족들의 충실한 군대는 물론 대사제들 즉, 죽음의 머리교 일족이 살고 있습니다. 최근 이 조잡한 은신처에 기분 나쁜 그림자가 드리워지고 있습니다. 혹한의 암네나르가 이끄는 언데드 스컬지 요원들이 가시멧돼지를 지배하고 그들의 가시 미궁을 언데드 군단의 요새로 만든 것입니다.', `FemaleText_loc4`='剃刀高地和剃刀沼泽一样由巨大的藤蔓组成，剃刀高地是野猪人的传统都城。在那错综复杂的荆棘迷宫中居住着大群忠诚的野猪人军队，以及他们的高等祭司——亡首部族。然而最近，一股黑暗的力量笼罩了这座原始的洞穴。亡灵天灾的爪牙在巫妖寒冰之王亚门纳尔的带领下控制了野猪部族，并将布满荆棘的迷宫变成了亡灵力量的堡垒。现在野猪人正在奋力战斗来夺回他们的城市，并阻止亚门纳尔继续控制贫瘠之地。', `FemaleText_loc5`='剃刀高地和剃刀沼澤一樣由巨大的藤蔓組成，剃刀高地是野豬人的傳統都城。在那錯綜複雜的荊棘迷宮中居住著大群忠誠的野豬人軍隊以及他們的高階牧師─亡首部族。然而最近，一股陰影力量籠罩了這個原始的洞穴。天譴軍團的人在巫妖『寒冰使者』亞門納爾的帶領下控制了野豬部族並將荊棘迷宮變成了亡靈力量的堡壘。現在野豬人正奮力戰鬥來重新奪回他們的城市，並阻止亞門納爾繼續控制貧瘠之地。', `FemaleText_loc7`='Construida con las mismas vides que Horado Rajacieno, Zahúrda Rajacieno es la capital tradicional de la raza de los jabaespines. El laberinto de espinas que se extiende por todas partes, aloja un verdadero ejército de leales jabaespines junto con sus altos sacerdotes, la tribu Caramuerte. Sin embargo, recientemente una sombra de mal presagio ha caído sobre la rudimentaria guarida. Unos agentes de la Plaga de los no-muertos, a las órdenes del exánime Amnennar el Gélido, han tomado el control de la raza de los jabaespines y han convertido el laberinto de espinas en un bastión del poder de los no-muertos.' WHERE `ID`=9923;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='울다만', `MaleText_loc4`='奥达曼', `MaleText_loc5`='奧達曼', `MaleText_loc7`='Uldaman', `FemaleText_loc1`='울다만', `FemaleText_loc4`='奥达曼', `FemaleText_loc5`='奧達曼', `FemaleText_loc7`='Uldaman' WHERE `ID`=9924;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='울다만은 황야의 땅 북쪽 맨 끝에 있습니다.', `MaleText_loc4`='奥达曼位于荒芜之地最北端。', `MaleText_loc5`='奧達曼位於荒蕪之地最北端。', `MaleText_loc7`='Uldaman se encuentra en el extremo más al norte de las Tierras Inhóspitas.', `FemaleText_loc1`='울다만은 황야의 땅 북쪽 맨 끝에 있습니다.', `FemaleText_loc4`='奥达曼位于荒芜之地最北端。', `FemaleText_loc5`='奧達曼位於荒蕪之地最北端。', `FemaleText_loc7`='Uldaman se encuentra en el extremo más al norte de las Tierras Inhóspitas.' WHERE `ID`=9925;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라드 여기 지킨다. 라드 물고기도 팔아. 물고기 살래?', `MaleText_loc4`='拉尔德在这里维持和平。拉尔德还在这里钓鱼。想要一些鱼吗？', `MaleText_loc5`='拉爾德在這裡維持和平。拉爾德還在這裡賣魚。想要一些魚嗎?', `MaleText_loc7`='Lard mantener la paz aquí. Lard también vender peces. ¿Querer peces?', `FemaleText_loc1`='라드 여기 지킨다. 라드 물고기도 팔아. 물고기 살래?', `FemaleText_loc4`='拉尔德在这里维持和平。拉尔德还在这里钓鱼。想要一些鱼吗？', `FemaleText_loc5`='拉爾德在這裡維持和平。拉爾德還在這裡賣魚。想要一些魚嗎?', `FemaleText_loc7`='Lard mantener la paz aquí. Lard también vender peces. ¿Querer peces?' WHERE `ID`=9926;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='울다만은 세계 창조 이래로 땅속에 묻혀 있던 고대 티탄의 저장고입니다. 드워프의 발굴로 인해 티탄의 첫 번째 창조 실패작인 트로그들이 최근에 풀려났습니다. 전설에 의하면, 티탄들이 트로그 실험을 실패로 간주하고 다시 시도를 했을 때 드워프 종족이 탄생한 것이라고 합니다. 이 비밀은 저 전설적인 노르간논의 원반에 기록되어 있습니다. 이 어마어마한 크기의 유물은 고대 도시 울다만의 바닥에 있는데, 살아 있는 거대한 바위 피조물이 보호하고 있답니다.', `MaleText_loc4`='奥达曼是古代泰坦创世之时所留下的深埋于地下的城市。矮人探险队最近发觉到了这块被遗忘的城市，将泰坦一款失败的创造物：食腭怪唤醒了。传说说泰坦是从石头中创造了食腭怪。当实施证明这次试验很失败的时候，泰坦把食腭怪锁了起来并进行了第二次的尝试——最终创造了矮人这个种族。矮人创造的秘密被记录在精密的白金圆盘中——那是位于古代城市最底部的大型泰坦遗迹。', `MaleText_loc5`='奧達曼是古代泰坦創世之時所留下的深埋於地下的城市。矮人探險隊最近發覺到了這塊被遺忘的城市，將泰坦一款失敗的創造物:穴居怪喚醒了。傳說泰坦是從石頭中創造了穴居怪。當執行證明這次試驗很失敗的時候，泰坦把穴居怪鎖了起來並進行了第二次的嘗試─最終創造了矮人這個種族。矮人創造的秘密被記錄在精密的白金圓盤中─那是位於古代城市最底部的大型泰坦遺跡。', `MaleText_loc7`='Uldaman es una antigua gruta titánica, profunda en la tierra desde el comienzo de los tiempos. Las recientes excavaciones de los enanos han liberado a una de las primeras creaciones fallidas de los titanes: los troggs. La leyenda cuenta que cuando los titanes se percataron de su fallo con los troggs volvieron a intentarlo; entonces fue cuando apareció la raza enana. Estos secretos se encuentran guardados en los legendarios Discos de Norgannon: son unos artefactos gigantescos que se encuentran en las profundidades de la antigua ciudad y están protegidos por constructos gigantescos de piedra viva.', `FemaleText_loc1`='울다만은 세계 창조 이래로 땅속에 묻혀 있던 고대 티탄의 저장고입니다. 드워프의 발굴로 인해 티탄의 첫 번째 창조 실패작인 트로그들이 최근에 풀려났습니다. 전설에 의하면, 티탄들이 트로그 실험을 실패로 간주하고 다시 시도를 했을 때 드워프 종족이 탄생한 것이라고 합니다. 이 비밀은 저 전설적인 노르간논의 원반에 기록되어 있습니다. 이 어마어마한 크기의 유물은 고대 도시 울다만의 바닥에 있는데, 살아 있는 거대한 바위 피조물이 보호하고 있답니다.', `FemaleText_loc4`='奥达曼是古代泰坦创世之时所留下的深埋于地下的城市。矮人探险队最近发觉到了这块被遗忘的城市，将泰坦一款失败的创造物：食腭怪唤醒了。传说说泰坦是从石头中创造了食腭怪。当实施证明这次试验很失败的时候，泰坦把食腭怪锁了起来并进行了第二次的尝试——最终创造了矮人这个种族。矮人创造的秘密被记录在精密的白金圆盘中——那是位于古代城市最底部的大型泰坦遗迹。', `FemaleText_loc5`='奧達曼是古代泰坦創世之時所留下的深埋於地下的城市。矮人探險隊最近發覺到了這塊被遺忘的城市，將泰坦一款失敗的創造物:穴居怪喚醒了。傳說泰坦是從石頭中創造了穴居怪。當執行證明這次試驗很失敗的時候，泰坦把穴居怪鎖了起來並進行了第二次的嘗試─最終創造了矮人這個種族。矮人創造的秘密被記錄在精密的白金圓盤中─那是位於古代城市最底部的大型泰坦遺跡。', `FemaleText_loc7`='Uldaman es una antigua gruta titánica, profunda en la tierra desde el comienzo de los tiempos. Las recientes excavaciones de los enanos han liberado a una de las primeras creaciones fallidas de los titanes: los troggs. La leyenda cuenta que cuando los titanes se percataron de su fallo con los troggs volvieron a intentarlo; entonces fue cuando apareció la raza enana. Estos secretos se encuentran guardados en los legendarios Discos de Norgannon: son unos artefactos gigantescos que se encuentran en las profundidades de la antigua ciudad y están protegidos por constructos gigantescos de piedra viva.' WHERE `ID`=9927;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='줄파락', `MaleText_loc4`='祖尔法拉克', `MaleText_loc5`='祖爾法拉克', `MaleText_loc7`='Zul''Farrak', `FemaleText_loc1`='줄파락', `FemaleText_loc4`='祖尔法拉克', `FemaleText_loc5`='祖爾法拉克', `FemaleText_loc7`='Zul''Farrak' WHERE `ID`=9928;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='줄파락의 폐허는 타나리스 사막의 북서쪽 가장자리에 있습니다.', `MaleText_loc4`='祖尔法拉克遗迹位于塔纳利斯沙漠最西北角。', `MaleText_loc5`='祖爾法拉克遺跡位於塔納利斯沙漠最西北角。', `MaleText_loc7`='Las Ruinas de Zul''Farrak están situadas en el extremo noroeste del Desierto de Tanaris.', `FemaleText_loc1`='줄파락의 폐허는 타나리스 사막의 북서쪽 가장자리에 있습니다.', `FemaleText_loc4`='祖尔法拉克遗迹位于塔纳利斯沙漠最西北角。', `FemaleText_loc5`='祖爾法拉克遺跡位於塔納利斯沙漠最西北角。', `FemaleText_loc7`='Las Ruinas de Zul''Farrak están situadas en el extremo noroeste del Desierto de Tanaris.' WHERE `ID`=9929;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='햇볕에 시들어 버린 이 도시는 그 유별난 무자비함과 암흑 신비술로 악명 높은 성난모래 트롤들의 고향입니다. 트롤 전설을 보면 질풍의 술트라제라는 강력한 검 이야기가 나옵니다. 아무리 끔찍한 적에게라도 공포와 나약함을 주입시킬 수 있는 무기라고 합니다. 오래전 이 검이 두 조각이 났다고 하는데, 들리는 소문에 따르면 이 두 조각이 줄파락 성벽 내 어딘가에 있다고 합니다.', `MaleText_loc4`='日光暴晒下的这座城市是沙怒巨魔的家园，他们一向以来都以其无情和黑暗魔法而闻名。巨魔传说中有一把强大的名叫鞭笞者苏萨斯的武器能够让最弱小的人可以击败最强大的敌人。很久以前，这把武器被分成了两半。然而，有传言说这两半可以在祖尔法拉克任何地方找到。', `MaleText_loc5`='日光暴曬下的這座城市是沙怒食人妖的家園，他們一向以來都以其無情和黑暗魔法而聞名。食人妖傳說中有一把強大的名叫鞭笞者蘇薩斯的武器能夠讓最弱小的人可以擊敗最強大的敵人。很久以前，這把武器被分成了兩半。然而，有傳言說這兩半可以在祖爾法拉克任何地方找到。', `MaleText_loc7`='Esta ciudad abrasada por los rayos del sol es el hogar de los trols Furiarena, famosos por su particular falta de piedad y su oscuro misticismo. Las leyendas de los trols hablan de una poderosa espada llamada Sul''thraze la Azotadora, un arma capaz de infundir miedo y flaqueza incluso a los enemigos más formidables. Mucho tiempo atrás, la espada fue partida por la mitad. Sin embargo, hay rumores que dicen que las dos mitades se encuentran en algún lugar dentro de los muros de Zul''Farrak.', `FemaleText_loc1`='햇볕에 시들어 버린 이 도시는 그 유별난 무자비함과 암흑 신비술로 악명 높은 성난모래 트롤들의 고향입니다. 트롤 전설을 보면 질풍의 술트라제라는 강력한 검 이야기가 나옵니다. 아무리 끔찍한 적에게라도 공포와 나약함을 주입시킬 수 있는 무기라고 합니다. 오래전 이 검이 두 조각이 났다고 하는데, 들리는 소문에 따르면 이 두 조각이 줄파락 성벽 내 어딘가에 있다고 합니다.', `FemaleText_loc4`='日光暴晒下的这座城市是沙怒巨魔的家园，他们一向以来都以其无情和黑暗魔法而闻名。巨魔传说中有一把强大的名叫鞭笞者苏萨斯的武器能够让最弱小的人可以击败最强大的敌人。很久以前，这把武器被分成了两半。然而，有传言说这两半可以在祖尔法拉克任何地方找到。', `FemaleText_loc5`='日光暴曬下的這座城市是沙怒食人妖的家園，他們一向以來都以其無情和黑暗魔法而聞名。食人妖傳說中有一把強大的名叫鞭笞者蘇薩斯的武器能夠讓最弱小的人可以擊敗最強大的敵人。很久以前，這把武器被分成了兩半。然而，有傳言說這兩半可以在祖爾法拉克任何地方找到。', `FemaleText_loc7`='Esta ciudad abrasada por los rayos del sol es el hogar de los trols Furiarena, famosos por su particular falta de piedad y su oscuro misticismo. Las leyendas de los trols hablan de una poderosa espada llamada Sul''thraze la Azotadora, un arma capaz de infundir miedo y flaqueza incluso a los enemigos más formidables. Mucho tiempo atrás, la espada fue partida por la mitad. Sin embargo, hay rumores que dicen que las dos mitades se encuentran en algún lugar dentro de los muros de Zul''Farrak.' WHERE `ID`=9930;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마라우돈', `MaleText_loc4`='玛拉顿', `MaleText_loc5`='瑪拉頓', `MaleText_loc7`='Maraudon', `FemaleText_loc1`='마라우돈', `FemaleText_loc4`='玛拉顿', `FemaleText_loc5`='瑪拉頓', `FemaleText_loc7`='Maraudon' WHERE `ID`=9931;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마라우돈은 뾰족바위 골짜기에 있는 잊혀진 땅 서쪽 해안의 중간 지점에 있습니다.', `MaleText_loc4`='玛拉顿位于凄凉之地西部中间的长矛谷中。', `MaleText_loc5`='瑪拉頓位於淒涼之地西部中間的長矛谷中。', `MaleText_loc7`='Maraudon está en el medio de la costa oeste de Desolace, en el Valle de las Lanzas.', `FemaleText_loc1`='마라우돈은 뾰족바위 골짜기에 있는 잊혀진 땅 서쪽 해안의 중간 지점에 있습니다.', `FemaleText_loc4`='玛拉顿位于凄凉之地西部中间的长矛谷中。', `FemaleText_loc5`='瑪拉頓位於淒涼之地西部中間的長矛谷中。', `FemaleText_loc7`='Maraudon está en el medio de la costa oeste de Desolace, en el Valle de las Lanzas.' WHERE `ID`=9932;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마라우돈은 잊혀진 땅에서 가장 성스러운 곳 중 하나입니다. 이 거대한 신전 겸 동굴은 반신 세나리우스가 낳은 두 명의 불멸의 아들 중 하나인 재타르의 묘소이지요. 전설에 의하면, 재타르와 대지 정령 공주 테라드라스가 사생인 켄타우로스 종족을 자신들의 자식으로 삼기로 했고, 그들이 나타나자 야만적인 켄타우로스족은 자신들의 아버지에게 반기를 들어 그를 죽였다고 합니다. 어떤 이들은 테라드라스가 슬픔을 못 이겨 재타르의 영혼을 그 굽이치는 동굴 안에 가두고 그 힘을 어떤 사악한 목적으로 이용했다고 믿습니다.', `MaleText_loc4`='玛拉顿被狂暴的玛拉顿半人马所保护，那是凄凉之地最神圣的地方。玛拉顿是扎尔塔的伟大神庙，扎尔塔使半神塞纳留斯不朽的儿子之一。传说说扎尔塔和瑟莱德丝大地元素公主的私生子成为了半人马种族。据说半人马这个野蛮的种族在其出生了之后就开始转向他们的父亲并将其杀死。有些人则相信瑟莱德丝在悲伤中将扎尔塔的灵魂困了起来，并将其藏在洞中——利用它的能量来达到一些不可告人的目的。', `MaleText_loc5`='瑪拉頓被狂暴的瑪拉頓半人馬所保護，那是淒涼之地最神聖的地方。瑪拉頓是札爾塔的偉大神廟，札爾塔使半神塞納留斯不朽的兒子之一。傳說札爾塔和瑟萊德絲土元素公主的私生子成為了半人馬種族。據說半人馬這個野蠻的種族在其出生了之後就開始轉向他們的父親並將其殺死。有些人則相信瑟萊德絲在悲傷中將札爾塔的靈魂困了起來，並將其藏在洞中─利用它的能量來達到一些不可告人的目的。', `MaleText_loc7`='Maraudon es uno de los lugares más sagrados de Desolace. El gran templo caverna, es la sepultura de Zaetar, uno de los dos hijos inmortales del semidiós Cenarius. Dice la leyenda, que Zaetar y la princesa elemental de tierra, Theradras, engendraron a la malnacida raza centaura. Dicen que cuando aparecieron, los brutales centauros se volvieron contra su padre y le mataron. Algunos creen que Theradras, en su profunda pena, atrapó el espíritu de Zaetar en la cueva y utilizó sus energías con algún propósito maligno.', `FemaleText_loc1`='마라우돈은 잊혀진 땅에서 가장 성스러운 곳 중 하나입니다. 이 거대한 신전 겸 동굴은 반신 세나리우스가 낳은 두 명의 불멸의 아들 중 하나인 재타르의 묘소이지요. 전설에 의하면, 재타르와 대지 정령 공주 테라드라스가 사생인 켄타우로스 종족을 자신들의 자식으로 삼기로 했고, 그들이 나타나자 야만적인 켄타우로스족은 자신들의 아버지에게 반기를 들어 그를 죽였다고 합니다. 어떤 이들은 테라드라스가 슬픔을 못 이겨 재타르의 영혼을 그 굽이치는 동굴 안에 가두고 그 힘을 어떤 사악한 목적으로 이용했다고 믿습니다.', `FemaleText_loc4`='玛拉顿被狂暴的玛拉顿半人马所保护，那是凄凉之地最神圣的地方。玛拉顿是扎尔塔的伟大神庙，扎尔塔使半神塞纳留斯不朽的儿子之一。传说说扎尔塔和瑟莱德丝大地元素公主的私生子成为了半人马种族。据说半人马这个野蛮的种族在其出生了之后就开始转向他们的父亲并将其杀死。有些人则相信瑟莱德丝在悲伤中将扎尔塔的灵魂困了起来，并将其藏在洞中——利用它的能量来达到一些不可告人的目的。', `FemaleText_loc5`='瑪拉頓被狂暴的瑪拉頓半人馬所保護，那是淒涼之地最神聖的地方。瑪拉頓是札爾塔的偉大神廟，札爾塔使半神塞納留斯不朽的兒子之一。傳說札爾塔和瑟萊德絲土元素公主的私生子成為了半人馬種族。據說半人馬這個野蠻的種族在其出生了之後就開始轉向他們的父親並將其殺死。有些人則相信瑟萊德絲在悲傷中將札爾塔的靈魂困了起來，並將其藏在洞中─利用它的能量來達到一些不可告人的目的。', `FemaleText_loc7`='Maraudon es uno de los lugares más sagrados de Desolace. El gran templo caverna, es la sepultura de Zaetar, uno de los dos hijos inmortales del semidiós Cenarius. Dice la leyenda, que Zaetar y la princesa elemental de tierra, Theradras, engendraron a la malnacida raza centaura. Dicen que cuando aparecieron, los brutales centauros se volvieron contra su padre y le mataron. Algunos creen que Theradras, en su profunda pena, atrapó el espíritu de Zaetar en la cueva y utilizó sus energías con algún propósito maligno.' WHERE `ID`=9933;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가라앉은 사원(아탈학카르 신전)', `MaleText_loc4`='沉没的神庙', `MaleText_loc5`='沉沒的神廟', `MaleText_loc7`='Templo Sumergido', `FemaleText_loc1`='가라앉은 사원(아탈학카르 신전)', `FemaleText_loc4`='沉没的神庙', `FemaleText_loc5`='沉沒的神廟', `FemaleText_loc7`='Templo Sumergido' WHERE `ID`=9934;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가라앉은 사원은 슬픔의 늪 동쪽에 있는 거대한 호수 한가운데에서 찾을 수 있습니다.', `MaleText_loc4`='沉没的神庙位于悲伤沼泽东部的一个大湖的中心。', `MaleText_loc5`='沉沒的神廟位於悲傷沼澤東部的一個大湖的中心。', `MaleText_loc7`='El Templo Sumergido se encuentra en el centro de un gran lago, en la parte este del Pantano de las Penas.', `FemaleText_loc1`='가라앉은 사원은 슬픔의 늪 동쪽에 있는 거대한 호수 한가운데에서 찾을 수 있습니다.', `FemaleText_loc4`='沉没的神庙位于悲伤沼泽东部的一个大湖的中心。', `FemaleText_loc5`='沉沒的神廟位於悲傷沼澤東部的一個大湖的中心。', `FemaleText_loc7`='El Templo Sumergido se encuentra en el centro de un gran lago, en la parte este del Pantano de las Penas.' WHERE `ID`=9935;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='1천여 년 전에 아탈라이라고 알려진 트롤 사제 집단이 영혼약탈자 학카르라고 하는 고대 혈신을 깨우려고 했습니다. 그로 인한 내란에서 패배한 사제들은 슬픔의 늪으로 유배되었고, 그들은 그곳에서 학카르를 위한 신전을 지어 바치고 그를 물리적인 이 세계로의 현신을 준비했습니다. 아탈라이의 계획을 곧 알아낸 용의 위상 이세라는 그 신전을 늪 아래로 처박아 버렸고 오늘날까지 그 신전의 폐허는 강력한 녹색용들이 지키고 있습니다.', `MaleText_loc4`='在一千年之前，强大的古拉巴什王国被一次大型内部战争所毁灭。一部份被称为阿塔莱的巨魔牧师试图将古代的血神，夺灵者哈卡带回这个世界。虽然这些牧师被击败并最终被流放，这个伟大的王国变得四分五裂。流放的牧师逃到了北面的悲伤沼泽。他们为哈卡建立了一座伟大的神庙——在那里他们期望能够把哈卡重新带回世间。伟大的守护神龙伊瑟拉了解了阿塔莱的计划并将神庙摧毁沉入沼泽之中。在今天，神庙沉没的遗迹被绿龙所守卫并阻止任何人进入或者出去。', `MaleText_loc5`='在一千年之前，強大的古拉巴什王國被一次大型內部戰爭所毀滅。一部份被稱為阿塔萊的食人妖牧師試圖將古代血神哈卡奪魂者帶回這個世界。雖然這些牧師被擊敗並最終被流放，這個偉大的王國變得四分五裂。流放的牧師逃到了北面的悲傷沼澤。他們為哈卡建立了一座偉大的神廟─在那裡他們期望能夠把哈卡重新帶回世間。偉大的守護巨龍伊瑟拉瞭解了阿塔萊的計畫並將神廟摧毀沉入沼澤之中。而今，神廟沉沒的遺跡被綠龍所守衛並阻止任何人進入或者出去。', `MaleText_loc7`='Hace más de mil años, un grupo de sacerdotes trols conocidos como los Atal''ai, intentaron resucitar a un dios de la sangre ancestral llamado Hakkar el Cazador de Almas. Tras la consecuente guerra civil, los sacerdotes fueron derrotados y exiliados al Pantano de las Penas. Allí erigieron un templo en honor de Hakkar, para prepararse para su llegada al mundo físico. La dragón Aspecto Ysera, pronto descubrió los planes de los Atal''ai y hundió el templo bajo el pantano. Hasta el día de hoy, las ruinas han estado protegidas por los poderosos dragones Verdes.', `FemaleText_loc1`='1천여 년 전에 아탈라이라고 알려진 트롤 사제 집단이 영혼약탈자 학카르라고 하는 고대 혈신을 깨우려고 했습니다. 그로 인한 내란에서 패배한 사제들은 슬픔의 늪으로 유배되었고, 그들은 그곳에서 학카르를 위한 신전을 지어 바치고 그를 물리적인 이 세계로의 현신을 준비했습니다. 아탈라이의 계획을 곧 알아낸 용의 위상 이세라는 그 신전을 늪 아래로 처박아 버렸고 오늘날까지 그 신전의 폐허는 강력한 녹색용들이 지키고 있습니다.', `FemaleText_loc4`='在一千年之前，强大的古拉巴什王国被一次大型内部战争所毁灭。一部份被称为阿塔莱的巨魔牧师试图将古代的血神，夺灵者哈卡带回这个世界。虽然这些牧师被击败并最终被流放，这个伟大的王国变得四分五裂。流放的牧师逃到了北面的悲伤沼泽。他们为哈卡建立了一座伟大的神庙——在那里他们期望能够把哈卡重新带回世间。伟大的守护神龙伊瑟拉了解了阿塔莱的计划并将神庙摧毁沉入沼泽之中。在今天，神庙沉没的遗迹被绿龙所守卫并阻止任何人进入或者出去。', `FemaleText_loc5`='在一千年之前，強大的古拉巴什王國被一次大型內部戰爭所毀滅。一部份被稱為阿塔萊的食人妖牧師試圖將古代血神哈卡奪魂者帶回這個世界。雖然這些牧師被擊敗並最終被流放，這個偉大的王國變得四分五裂。流放的牧師逃到了北面的悲傷沼澤。他們為哈卡建立了一座偉大的神廟─在那裡他們期望能夠把哈卡重新帶回世間。偉大的守護巨龍伊瑟拉瞭解了阿塔萊的計畫並將神廟摧毀沉入沼澤之中。而今，神廟沉沒的遺跡被綠龍所守衛並阻止任何人進入或者出去。', `FemaleText_loc7`='Hace más de mil años, un grupo de sacerdotes trols conocidos como los Atal''ai, intentaron resucitar a un dios de la sangre ancestral llamado Hakkar el Cazador de Almas. Tras la consecuente guerra civil, los sacerdotes fueron derrotados y exiliados al Pantano de las Penas. Allí erigieron un templo en honor de Hakkar, para prepararse para su llegada al mundo físico. La dragón Aspecto Ysera, pronto descubrió los planes de los Atal''ai y hundió el templo bajo el pantano. Hasta el día de hoy, las ruinas han estado protegidas por los poderosos dragones Verdes.' WHERE `ID`=9936;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은바위 나락', `MaleText_loc4`='黑石深渊', `MaleText_loc5`='黑石深淵', `MaleText_loc7`='Profundidades de Roca Negra', `FemaleText_loc1`='검은바위 나락', `FemaleText_loc4`='黑石深渊', `FemaleText_loc5`='黑石深淵', `FemaleText_loc7`='Profundidades de Roca Negra' WHERE `ID`=9937;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은바위 산은 이글거리는 협곡을 북쪽에, 불타는 평원을 남쪽에 두고 그 사이에 있습니다.', `MaleText_loc4`='黑石山脉位于灼热峡谷和燃烧平原的中间。', `MaleText_loc5`='黑石山位於灼熱峽谷和燃燒平原的中間。', `MaleText_loc7`='La Montaña Roca Negra linda con La Garganta de Fuego al norte y Las Estepas Ardientes al sur.', `FemaleText_loc1`='검은바위 산은 이글거리는 협곡을 북쪽에, 불타는 평원을 남쪽에 두고 그 사이에 있습니다.', `FemaleText_loc4`='黑石山脉位于灼热峡谷和燃烧平原的中间。', `FemaleText_loc5`='黑石山位於灼熱峽谷和燃燒平原的中間。', `FemaleText_loc7`='La Montaña Roca Negra linda con La Garganta de Fuego al norte y Las Estepas Ardientes al sur.' WHERE `ID`=9938;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한때 검은무쇠 드워프들의 수도였던 이 화산 미궁은 이제 불의 군주 라그나로스의 권력 중심지로 쓰이고 있습니다. 돌에서 생명체를 만들어 내는 비밀을 알아낸 라그나로스는 그 누구도 멈출 수 없는 골렘 군단을 만들어 검은바위 산 전체를 정복하는 데 이용하려는 음모를 꾸미고 있습니다. 네파리안과 그의 용 부하들을 물리칠 생각에 사로잡힌 라그나로스는 최후의 승리를 달성하기 위해서라면 그 어떤 극단적인 수단도 가리지 않을 겁니다.', `MaleText_loc4`='黑石深渊曾经是黑铁矮人的伟大都城，这个火山中的迷宫现在成为拉格纳罗斯火焰领主的王座所在地。拉格纳罗斯找到了特殊的方法，可以使用石头来创造一支无敌的石头人军队，帮助它征服黑石深渊。为了打败奈法利安和他的龙子龙孙，拉格纳罗斯会不惜一切代价达到最后的胜利。', `MaleText_loc5`='黑石山曾經是黑鐵矮人的偉大都城，這個火山中的迷宮現在成為『炎魔』拉格納羅斯的王座所在地。拉格納羅斯找到了利用岩石創造生命的方法，打算創造一支無法阻擋的魔像軍隊來幫助他征服黑石山。他執意要打敗奈法利安和他的龍群，拉格納羅斯會不惜一切代價來達到最後的勝利。', `MaleText_loc7`='Antiguamente la capital de los enanos Hierro Negro, este laberinto volcánico ahora sirve como trono de poder de Ragnaros, el Señor del Fuego. Ragnaros ha descubierto cómo crear vida a partir de la piedra y planea formar un ejército de gólems imparables para ayudarle a conquistar la Montaña Roca Negra. Ragnaros, obsesionado con derrotar a Nefarian y a sus esbirros dracónicos, hará lo que sea por conseguir la victoria final.', `FemaleText_loc1`='한때 검은무쇠 드워프들의 수도였던 이 화산 미궁은 이제 불의 군주 라그나로스의 권력 중심지로 쓰이고 있습니다. 돌에서 생명체를 만들어 내는 비밀을 알아낸 라그나로스는 그 누구도 멈출 수 없는 골렘 군단을 만들어 검은바위 산 전체를 정복하는 데 이용하려는 음모를 꾸미고 있습니다. 네파리안과 그의 용 부하들을 물리칠 생각에 사로잡힌 라그나로스는 최후의 승리를 달성하기 위해서라면 그 어떤 극단적인 수단도 가리지 않을 겁니다.', `FemaleText_loc4`='黑石深渊曾经是黑铁矮人的伟大都城，这个火山中的迷宫现在成为拉格纳罗斯火焰领主的王座所在地。拉格纳罗斯找到了特殊的方法，可以使用石头来创造一支无敌的石头人军队，帮助它征服黑石深渊。为了打败奈法利安和他的龙子龙孙，拉格纳罗斯会不惜一切代价达到最后的胜利。', `FemaleText_loc5`='黑石山曾經是黑鐵矮人的偉大都城，這個火山中的迷宮現在成為『炎魔』拉格納羅斯的王座所在地。拉格納羅斯找到了利用岩石創造生命的方法，打算創造一支無法阻擋的魔像軍隊來幫助他征服黑石山。他執意要打敗奈法利安和他的龍群，拉格納羅斯會不惜一切代價來達到最後的勝利。', `FemaleText_loc7`='Antiguamente la capital de los enanos Hierro Negro, este laberinto volcánico ahora sirve como trono de poder de Ragnaros, el Señor del Fuego. Ragnaros ha descubierto cómo crear vida a partir de la piedra y planea formar un ejército de gólems imparables para ayudarle a conquistar la Montaña Roca Negra. Ragnaros, obsesionado con derrotar a Nefarian y a sus esbirros dracónicos, hará lo que sea por conseguir la victoria final.' WHERE `ID`=9939;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은바위 첨탑', `MaleText_loc4`='黑石塔', `MaleText_loc5`='黑石塔', `MaleText_loc7`='Cumbre de Roca Negra', `FemaleText_loc1`='검은바위 첨탑', `FemaleText_loc4`='黑石塔', `FemaleText_loc5`='黑石塔', `FemaleText_loc7`='Cumbre de Roca Negra' WHERE `ID`=9940;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은바위 산의 불타는 내부를 깎아 만든 이 강대한 요새는 데스윙의 교활한 아들 네파리안이 첨탑의 상층을 점령하고 검은바위 산의 화산 심연에 있는 드워프들과 전쟁을 치르기 전까지는 수세기 동안 사악한 검은무쇠 드워프들이 차지하고 있었습니다. 강력한 불의 정령 라그나로스가 이 드워프들을 이끌고 있다는 사실을 깨달은 네파리안은 그의 적들을 제압하고 검은바위 산 전체를 손아귀에 둘 것을 맹세했습니다.', `MaleText_loc4`='黑石深渊深处的巨大堡垒是由矮人建筑大师弗兰克罗恩·铸铁所设计的。这个堡垒是矮人力量的象征并被邪恶的黑铁矮人占据了数个世纪。然而，奈法利安——死亡之翼狡猾的儿子——对这个巨大的堡垒别有意图。他和他的黑龙军团占据了上层黑石塔并向占据着黑石深渊的黑铁矮人宣战。奈法利安知道矮人是由强大的火元素拉格纳罗斯所领导的，所以他立志要摧毁他的敌人并将黑石深渊全被占为己有。', `MaleText_loc5`='黑石山深處的巨大堡壘是由矮人建築大師弗蘭克羅恩·鑄鐵所設計的。這個堡壘是矮人力量的象徵並被邪惡的黑鐵矮人佔據了數個世紀。然而，奈法利安─死亡之翼狡猾的兒子─對這個巨大的堡壘別有意圖。他和他的黑龍軍團佔據了上層黑石塔並向佔據著黑石山深淵的黑鐵矮人宣戰。奈法利安知道矮人是由強大的火元素拉格納羅斯所領導的，所以他立志要摧毀他的敵人並將黑石山全被占為己有。', `MaleText_loc7`='La poderosa fortaleza enclavada en las fieras entrañas de la Montaña Roca Negra, estuvo ocupada por los siniestros enanos Hierro Negro durante siglos, hasta que Nefarian, el astuto hijo del dragón Alamuerte, tomó el control de la Cumbre superior y declaró la guerra a los enanos en las profundidades volcánicas de la montaña. Al darse cuenta de que los enanos estaban a las órdenes del poderoso elemental de fuego Ragnaros, Nefarian juró aplastar a sus enemigos y reclamar toda la Montaña Roca Negra para sí.', `FemaleText_loc1`='검은바위 산의 불타는 내부를 깎아 만든 이 강대한 요새는 데스윙의 교활한 아들 네파리안이 첨탑의 상층을 점령하고 검은바위 산의 화산 심연에 있는 드워프들과 전쟁을 치르기 전까지는 수세기 동안 사악한 검은무쇠 드워프들이 차지하고 있었습니다. 강력한 불의 정령 라그나로스가 이 드워프들을 이끌고 있다는 사실을 깨달은 네파리안은 그의 적들을 제압하고 검은바위 산 전체를 손아귀에 둘 것을 맹세했습니다.', `FemaleText_loc4`='黑石深渊深处的巨大堡垒是由矮人建筑大师弗兰克罗恩·铸铁所设计的。这个堡垒是矮人力量的象征并被邪恶的黑铁矮人占据了数个世纪。然而，奈法利安——死亡之翼狡猾的儿子——对这个巨大的堡垒别有意图。他和他的黑龙军团占据了上层黑石塔并向占据着黑石深渊的黑铁矮人宣战。奈法利安知道矮人是由强大的火元素拉格纳罗斯所领导的，所以他立志要摧毁他的敌人并将黑石深渊全被占为己有。', `FemaleText_loc5`='黑石山深處的巨大堡壘是由矮人建築大師弗蘭克羅恩·鑄鐵所設計的。這個堡壘是矮人力量的象徵並被邪惡的黑鐵矮人佔據了數個世紀。然而，奈法利安─死亡之翼狡猾的兒子─對這個巨大的堡壘別有意圖。他和他的黑龍軍團佔據了上層黑石塔並向佔據著黑石山深淵的黑鐵矮人宣戰。奈法利安知道矮人是由強大的火元素拉格納羅斯所領導的，所以他立志要摧毀他的敵人並將黑石山全被占為己有。', `FemaleText_loc7`='La poderosa fortaleza enclavada en las fieras entrañas de la Montaña Roca Negra, estuvo ocupada por los siniestros enanos Hierro Negro durante siglos, hasta que Nefarian, el astuto hijo del dragón Alamuerte, tomó el control de la Cumbre superior y declaró la guerra a los enanos en las profundidades volcánicas de la montaña. Al darse cuenta de que los enanos estaban a las órdenes del poderoso elemental de fuego Ragnaros, Nefarian juró aplastar a sus enemigos y reclamar toda la Montaña Roca Negra para sí.' WHERE `ID`=9941;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혈투의 전장', `MaleText_loc4`='厄运之棰', `MaleText_loc5`='厄運之槌', `MaleText_loc7`='La Masacre', `FemaleText_loc1`='혈투의 전장', `FemaleText_loc4`='厄运之棰', `FemaleText_loc5`='厄運之槌', `FemaleText_loc7`='La Masacre' WHERE `ID`=9942;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혈투의 전장의 폐허는 페랄라스 중심부에 있습니다.', `MaleText_loc4`='厄运之棰位于菲拉斯的中部。', `MaleText_loc5`='厄運之槌位於菲拉斯的中部。', `MaleText_loc7`='Las ruinas de La Masacre yacen en el centro de Feralas.', `FemaleText_loc1`='혈투의 전장의 폐허는 페랄라스 중심부에 있습니다.', `FemaleText_loc4`='厄运之棰位于菲拉斯的中部。', `FemaleText_loc5`='厄運之槌位於菲拉斯的中部。', `FemaleText_loc7`='Las ruinas de La Masacre yacen en el centro de Feralas.' WHERE `ID`=9943;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 나이트 엘프 마술사의 비밀 분파가 1만 2천 년 전에 지은 고대 도시 엘드레탈라스는 아즈샤라 여왕이 가장 소중히 여기는 마법 비밀을 보호하는 데 사용되었습니다. 세계의 분리로 인해 파괴되기는 했지만 불가사의한 이 도시의 상당 부분이 혈투의 전장이라는 이름을 지니고 으리으리한 모습으로 여전히 남아 있답니다. 서로 뚜렷이 구분되는 이 폐허의 세 지구에는 온갖 종류의 생물들이 출몰하고 있는데, 특히 명가의 유령들이나 사악한 사티로스, 그리고 포악한 오우거들이 많이 나타나고 있습니다.', `MaleText_loc4`='埃雷萨拉斯古城是在一万二千年前由当时的一批暗夜精灵法师秘密地建造的，它被用于保护艾莎拉皇后最宝贵的奥法秘密。虽然受到了世界大分裂的影响，这座伟大的城市基本屹立在那里，现在其被称为厄运之槌。这座遗迹城市分为三个部分，分别被不同的生物所占据——包括幽灵般的高等精灵，邪恶的萨特和鲁莽的食人魔。', `MaleText_loc5`='埃德薩拉斯古城是在一萬二千年前由當時的一批夜精靈巫士結社建造的，它被用於保護艾薩拉女王最寶貴的秘法之密。雖然受到了世界大爆炸的影響，這座偉大的城市基本屹立在那裡，現在其被稱為厄運之槌。這座遺跡城市分為三個部分，分別被不同的生物所佔據─包括鬼靈般的精靈貴族，邪惡的薩特和魯莽的巨魔。', `MaleText_loc7`='La antigua ciudad de Eldre''Thalas, construida hace doce mil años por una secta encubierta de encantadores elfos de la noche, se utilizó para proteger los secretos arcanos más valiosos de la reina Azshara. Aunque fue arrasada por el Gran Cataclismo del mundo, todavía permanece en pie gran parte de la maravillosa ciudad, elevándose como la imponente Masacre. Los tres diferentes distritos de la ciudad se han visto invadidos por todo tipo de criaturas, especialmente los espectrales Altonato, los malvados sátiros y los brutales ogros.', `FemaleText_loc1`='한 나이트 엘프 마술사의 비밀 분파가 1만 2천 년 전에 지은 고대 도시 엘드레탈라스는 아즈샤라 여왕이 가장 소중히 여기는 마법 비밀을 보호하는 데 사용되었습니다. 세계의 분리로 인해 파괴되기는 했지만 불가사의한 이 도시의 상당 부분이 혈투의 전장이라는 이름을 지니고 으리으리한 모습으로 여전히 남아 있답니다. 서로 뚜렷이 구분되는 이 폐허의 세 지구에는 온갖 종류의 생물들이 출몰하고 있는데, 특히 명가의 유령들이나 사악한 사티로스, 그리고 포악한 오우거들이 많이 나타나고 있습니다.', `FemaleText_loc4`='埃雷萨拉斯古城是在一万二千年前由当时的一批暗夜精灵法师秘密地建造的，它被用于保护艾莎拉皇后最宝贵的奥法秘密。虽然受到了世界大分裂的影响，这座伟大的城市基本屹立在那里，现在其被称为厄运之槌。这座遗迹城市分为三个部分，分别被不同的生物所占据——包括幽灵般的高等精灵，邪恶的萨特和鲁莽的食人魔。', `FemaleText_loc5`='埃德薩拉斯古城是在一萬二千年前由當時的一批夜精靈巫士結社建造的，它被用於保護艾薩拉女王最寶貴的秘法之密。雖然受到了世界大爆炸的影響，這座偉大的城市基本屹立在那裡，現在其被稱為厄運之槌。這座遺跡城市分為三個部分，分別被不同的生物所佔據─包括鬼靈般的精靈貴族，邪惡的薩特和魯莽的巨魔。', `FemaleText_loc7`='La antigua ciudad de Eldre''Thalas, construida hace doce mil años por una secta encubierta de encantadores elfos de la noche, se utilizó para proteger los secretos arcanos más valiosos de la reina Azshara. Aunque fue arrasada por el Gran Cataclismo del mundo, todavía permanece en pie gran parte de la maravillosa ciudad, elevándose como la imponente Masacre. Los tres diferentes distritos de la ciudad se han visto invadidos por todo tipo de criaturas, especialmente los espectrales Altonato, los malvados sátiros y los brutales ogros.' WHERE `ID`=9944;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스칼로맨스', `MaleText_loc4`='通灵学院', `MaleText_loc5`='通靈學院', `MaleText_loc7`='Scholomance', `FemaleText_loc1`='스칼로맨스', `FemaleText_loc4`='通灵学院', `FemaleText_loc5`='通靈學院', `FemaleText_loc7`='Scholomance' WHERE `ID`=9945;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스칼로맨스라고 알려진 강령술 학교는 서부 역병지대에 폐허가 된 섬 카엘 다로우에 있습니다.', `MaleText_loc4`='通灵学院这个学习亡灵术的学校位于西瘟疫之地的凯尔达隆那个废弃的小岛上。', `MaleText_loc5`='通靈學院這個學習亡靈術的學校位於西瘟疫之地的凱爾達隆那個廢棄的小島上。', `MaleText_loc7`='El colegio de nigromancia conocido como Scholomance, está en la isla en ruinas de Castel Darrow en las Tierras de la Peste del Oeste.', `FemaleText_loc1`='스칼로맨스라고 알려진 강령술 학교는 서부 역병지대에 폐허가 된 섬 카엘 다로우에 있습니다.', `FemaleText_loc4`='通灵学院这个学习亡灵术的学校位于西瘟疫之地的凯尔达隆那个废弃的小岛上。', `FemaleText_loc5`='通靈學院這個學習亡靈術的學校位於西瘟疫之地的凱爾達隆那個廢棄的小島上。', `FemaleText_loc7`='El colegio de nigromancia conocido como Scholomance, está en la isla en ruinas de Castel Darrow en las Tierras de la Peste del Oeste.' WHERE `ID`=9946;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스칼로맨스는 카엘 다로우 요새 아래에 있는 납골당에 있습니다. 한때 바로브 귀족 가문이 소유하던 그 요새는 2차 대전쟁 후 폐허가 되어 버렸지요. 마법사 켈투자드는 그의 저주받은 자들의 교단에 입단할 추종자들을 모집하면서 종종 리치 왕을 섬기는 자들에게 불멸의 생명을 약속하곤 했는데, 바로브 가문도 그의 영향력에 빠져 자신들의 요새를 내놓았지만 이교도들은 그 가족을 살해하고 납골당을 강령술 학교로 만들어 버렸습니다. 켈투자드는 더 이상 그곳에 있지 않지만 이교도들과 교사들은 아직도 남아 있습니다.', `MaleText_loc4`='通灵学院位于凯尔达隆废弃的城堡中的地下室中。那里曾经是高贵的巴罗夫家族的庄园，但是在第二次大战中凯尔达隆变成了一块废墟。法师克尔苏加德经常向他的诅咒神教信徒承诺可以用对于巫妖王的效忠来换取永恒的生命。巴罗夫家族受到克尔苏加德的魅惑而将城堡和其地下室献给了亡灵天灾。那些信徒将巴罗夫家族的人杀死，并把地下室变成了通灵学院。虽然克尔苏加德不再住在这个地下室中，但是狂热的信徒和讲师都还留在那里。', `MaleText_loc5`='通靈學院位於凱爾達隆廢棄的城堡中的地下室中。那裡曾經是高貴的巴羅夫家族的，但是在第二次大戰中凱爾達隆變成了一塊廢墟。巫師科爾蘇加德經常向他的詛咒神教信徒承諾可以用對於巫妖王的效忠來換取永恆的生命。巴羅克家族受到科爾蘇加德的魅惑而將城堡和其地下室獻給了天譴軍團。那些教徒接著將巴羅夫家族的人殺死並把地下室變成了通靈學院。雖然科爾蘇加德不再住在這個地下室中，但是狂熱的教徒和講師都還留在那裡。', `MaleText_loc7`='El Scholomance está en las criptas debajo del bastión de Castel Darrow. El bastión, que antiguamente pertenecía a la familia noble Barov, fue destruido tras la Segunda Guerra. El zahorí Kel''Thuzad reclutó seguidores para su Culto de los Malditos y prometió inmortalidad a quienes sirviesen a su Rey Exánime. Los Barov cayeron bajo su influencia y donaron el bastión, pero los cultores mataron a la familia y convirtieron las criptas en un colegio de nigromancia. Si bien Kel''Thuzad ya no reside allí, todavía quedan adeptos e instructores.', `FemaleText_loc1`='스칼로맨스는 카엘 다로우 요새 아래에 있는 납골당에 있습니다. 한때 바로브 귀족 가문이 소유하던 그 요새는 2차 대전쟁 후 폐허가 되어 버렸지요. 마법사 켈투자드는 그의 저주받은 자들의 교단에 입단할 추종자들을 모집하면서 종종 리치 왕을 섬기는 자들에게 불멸의 생명을 약속하곤 했는데, 바로브 가문도 그의 영향력에 빠져 자신들의 요새를 내놓았지만 이교도들은 그 가족을 살해하고 납골당을 강령술 학교로 만들어 버렸습니다. 켈투자드는 더 이상 그곳에 있지 않지만 이교도들과 교사들은 아직도 남아 있습니다.', `FemaleText_loc4`='通灵学院位于凯尔达隆废弃的城堡中的地下室中。那里曾经是高贵的巴罗夫家族的庄园，但是在第二次大战中凯尔达隆变成了一块废墟。法师克尔苏加德经常向他的诅咒神教信徒承诺可以用对于巫妖王的效忠来换取永恒的生命。巴罗夫家族受到克尔苏加德的魅惑而将城堡和其地下室献给了亡灵天灾。那些信徒将巴罗夫家族的人杀死，并把地下室变成了通灵学院。虽然克尔苏加德不再住在这个地下室中，但是狂热的信徒和讲师都还留在那里。', `FemaleText_loc5`='通靈學院位於凱爾達隆廢棄的城堡中的地下室中。那裡曾經是高貴的巴羅夫家族的，但是在第二次大戰中凱爾達隆變成了一塊廢墟。巫師科爾蘇加德經常向他的詛咒神教信徒承諾可以用對於巫妖王的效忠來換取永恆的生命。巴羅克家族受到科爾蘇加德的魅惑而將城堡和其地下室獻給了天譴軍團。那些教徒接著將巴羅夫家族的人殺死並把地下室變成了通靈學院。雖然科爾蘇加德不再住在這個地下室中，但是狂熱的教徒和講師都還留在那裡。', `FemaleText_loc7`='El Scholomance está en las criptas debajo del bastión de Castel Darrow. El bastión, que antiguamente pertenecía a la familia noble Barov, fue destruido tras la Segunda Guerra. El zahorí Kel''Thuzad reclutó seguidores para su Culto de los Malditos y prometió inmortalidad a quienes sirviesen a su Rey Exánime. Los Barov cayeron bajo su influencia y donaron el bastión, pero los cultores mataron a la familia y convirtieron las criptas en un colegio de nigromancia. Si bien Kel''Thuzad ya no reside allí, todavía quedan adeptos e instructores.' WHERE `ID`=9947;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스트라솔름', `MaleText_loc4`='斯坦索姆', `MaleText_loc5`='斯坦索姆', `MaleText_loc7`='Stratholme', `FemaleText_loc1`='스트라솔름', `FemaleText_loc4`='斯坦索姆', `FemaleText_loc5`='斯坦索姆', `FemaleText_loc7`='Stratholme' WHERE `ID`=9948;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폐허가 된 도시 스트라솔름은 역병숲 북쪽에 있는 동부 역병지대에 있습니다.', `MaleText_loc4`='斯坦索姆位于东部瘟疫之地瘟疫林的北部。', `MaleText_loc5`='斯坦索姆位於東瘟疫之地瘟疫林的北部。', `MaleText_loc7`='La ciudad en ruinas de Stratholme se encuentra en las Tierras de la Peste del Este, al norte del Bosque de la Peste.', `FemaleText_loc1`='폐허가 된 도시 스트라솔름은 역병숲 북쪽에 있는 동부 역병지대에 있습니다.', `FemaleText_loc4`='斯坦索姆位于东部瘟疫之地瘟疫林的北部。', `FemaleText_loc5`='斯坦索姆位於東瘟疫之地瘟疫林的北部。', `FemaleText_loc7`='La ciudad en ruinas de Stratholme se encuentra en las Tierras de la Peste del Este, al norte del Bosque de la Peste.' WHERE `ID`=9949;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한때 북부 로데론의 보석이라 불리던 스트라솔름은 바로 아서스 왕자가 자신의 스승인 빛의 수호자 우서 경을 배반하고 언데드 역병에 걸린 것으로 간주된 자신의 수백 명의 백성을 살해한 곳입니다. 그 후 아서스는 곧 리치 왕에게 항복했지요. 현재 이 파괴된 도시에는 강력한 리치 켈투자드가 이끄는 언데드 스컬지와 십자군 사령관 다스로한이 이끄는 붉은십자군 파견대가 거처하고 있으며, 이 두 진영은 끊임없이 격렬한 전투를 치르고 있습니다.', `MaleText_loc4`='斯坦索姆曾经是洛丹伦北部一颗璀璨的明珠，但是就是在这座城市中，阿尔萨斯王子背叛了他的导师乌瑟尔，并屠杀了数百个被认为受到感染的臣民。阿尔萨斯不久之后就向巫妖王臣服。这座破碎的城市也被巫妖克尔苏拉德领导的亡灵天灾所占据。一直由大十字军战士达索汉领导的血色十字军分遣队也占据了这个城市的一部分。这两方力量在城市中进行着激烈的战斗。', `MaleText_loc5`='斯坦索姆曾經是羅德隆北部一顆璀璨的明珠，但是就是在這座城市阿薩斯王子背叛了他的導師烏瑟，並屠殺了數百個被認為感染了可怕瘟疫的臣民。阿薩斯不久之後就向巫妖王臣服。這個破碎的城市也被巫妖科爾蘇加德領導的天譴軍團所佔據。而一直由大十字軍戰士達索漢領導的血色十字軍分遣隊也佔據了這個城市的一部分。這兩方力量在城市中進行著激烈的戰鬥。', `MaleText_loc7`='La antigua joya del norte de Lordaeron, la ciudad de Stratholme es donde el príncipe Arthas se volvió contra su mentor, Uther el Iluminado, y mató a cientos de sus propios súbditos que se creía habían contraído la Peste de los no-muertos. Poco después tuvo lugar la rendición de Arthas al Rey Exánime. Los restos de la ciudad son ahora el hogar de los no-muertos de la Plaga, liderados por el poderoso exánime Kel''Thuzad, y de un contingente de Cruzados Escarlata, a las órdenes del Gran Cruzado Dathrohan. Ambos bandos libran constantemente un violento combate.', `FemaleText_loc1`='한때 북부 로데론의 보석이라 불리던 스트라솔름은 바로 아서스 왕자가 자신의 스승인 빛의 수호자 우서 경을 배반하고 언데드 역병에 걸린 것으로 간주된 자신의 수백 명의 백성을 살해한 곳입니다. 그 후 아서스는 곧 리치 왕에게 항복했지요. 현재 이 파괴된 도시에는 강력한 리치 켈투자드가 이끄는 언데드 스컬지와 십자군 사령관 다스로한이 이끄는 붉은십자군 파견대가 거처하고 있으며, 이 두 진영은 끊임없이 격렬한 전투를 치르고 있습니다.', `FemaleText_loc4`='斯坦索姆曾经是洛丹伦北部一颗璀璨的明珠，但是就是在这座城市中，阿尔萨斯王子背叛了他的导师乌瑟尔，并屠杀了数百个被认为受到感染的臣民。阿尔萨斯不久之后就向巫妖王臣服。这座破碎的城市也被巫妖克尔苏拉德领导的亡灵天灾所占据。一直由大十字军战士达索汉领导的血色十字军分遣队也占据了这个城市的一部分。这两方力量在城市中进行着激烈的战斗。', `FemaleText_loc5`='斯坦索姆曾經是羅德隆北部一顆璀璨的明珠，但是就是在這座城市阿薩斯王子背叛了他的導師烏瑟，並屠殺了數百個被認為感染了可怕瘟疫的臣民。阿薩斯不久之後就向巫妖王臣服。這個破碎的城市也被巫妖科爾蘇加德領導的天譴軍團所佔據。而一直由大十字軍戰士達索漢領導的血色十字軍分遣隊也佔據了這個城市的一部分。這兩方力量在城市中進行著激烈的戰鬥。', `FemaleText_loc7`='La antigua joya del norte de Lordaeron, la ciudad de Stratholme es donde el príncipe Arthas se volvió contra su mentor, Uther el Iluminado, y mató a cientos de sus propios súbditos, que se creía habían contraído la Peste de los no-muertos. Poco después tuvo lugar la rendición de Arthas al Rey Exánime. Los restos de la ciudad son ahora el hogar de los no-muertos de la Plaga, liderados por el poderoso exánime Kel''Thuzad, y de un contingente de Cruzados Escarlata, a las órdenes del Gran Cruzado Dathrohan. Ambos bandos libran constantemente un violento combate.' WHERE `ID`=9950;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음의 폐광', `MaleText_loc4`='死亡矿井', `MaleText_loc5`='死亡礦坑', `MaleText_loc7`='Las Minas de la Muerte', `FemaleText_loc1`='죽음의 폐광', `FemaleText_loc4`='死亡矿井', `FemaleText_loc5`='死亡礦坑', `FemaleText_loc7`='Las Minas de la Muerte' WHERE `ID`=9951;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음의 폐광은 서부 몰락지대 남쪽에 있는 달빛시내 마을 아래에 있습니다.', `MaleText_loc4`='死亡矿井位于西部荒野南端月溪镇的地下。', `MaleText_loc5`='死亡礦坑位於西部荒野南部的月溪鎮地下。', `MaleText_loc7`='Las Minas de la Muerte se encuentran bajo el Arroyo de la Luna, al sur de los Páramos de Poniente.', `FemaleText_loc1`='죽음의 폐광은 서부 몰락지대 남쪽에 있는 달빛시내 마을 아래에 있습니다.', `FemaleText_loc4`='死亡矿井位于西部荒野月溪镇的地下。', `FemaleText_loc5`='死亡礦坑位於西部荒野南部的月溪鎮地下。', `FemaleText_loc7`='Las Minas de la Muerte se encuentran bajo el Arroyo de la Luna, al sur de los Páramos de Poniente.' WHERE `ID`=9952;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드 지하감옥', `MaleText_loc4`='暴风城监狱', `MaleText_loc5`='暴風城監獄', `MaleText_loc7`='Mazmorras de Ventormenta', `FemaleText_loc1`='스톰윈드 지하감옥', `FemaleText_loc4`='暴风城监狱', `FemaleText_loc5`='暴風城監獄', `FemaleText_loc7`='Mazmorras de Ventormenta' WHERE `ID`=9953;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드 지하감옥은 스톰윈드의 마법사 지구 근처에 있습니다.', `MaleText_loc4`='暴风城监狱位于暴风城靠近法师区附近。', `MaleText_loc5`='暴風城監獄位於暴風城靠近法師區附近。', `MaleText_loc7`='Las Mazmorras de Ventormenta se encuentran cerca del Barrio de los Magos, en Ventormenta.', `FemaleText_loc1`='스톰윈드 지하감옥은 스톰윈드의 마법사 지구 근처에 있습니다.', `FemaleText_loc4`='暴风城监狱位于暴风城靠近法师区附近。', `FemaleText_loc5`='暴風城監獄位於暴風城靠近法師區附近。', `FemaleText_loc7`='Las Mazmorras de Ventormenta se encuentran cerca del Barrio de los Magos, en Ventormenta.' WHERE `ID`=9954;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지하감옥은 스톰윈드의 운하 지역 아래에 숨겨진 경비가 삼엄한 교도소입니다. 델워터 교도소장이 감독하는 지하감옥은 삼류 사기꾼, 정치적 반역자, 살인자, 그리고 이 땅에서 가장 위험한 범죄자 수십 명이 모여 있는 곳입니다. 최근, 죄수들이 폭동을 일으켜 지하감옥은 아수라장이 되었고, 경비병들은 쫓겨나고 죄수들이 마음대로 활보하고 있습니다.', `MaleText_loc4`='监狱是位于暴风城运河区戒备森原的牢房。那里由典狱官塞尔沃特看守着，监狱是那些小偷，政治犯，谋杀者和许多最危险的罪犯的家园。最近，异常暴动导致了监狱的混乱——所有的守卫都被赶了出来，里面的罪犯可以自由的活动。', `MaleText_loc5`='監獄是位於暴風城運河區戒備森原的牢房。那裡由典獄官塞爾沃特看守著，監獄是那些小偷，政治犯，謀殺者和許多最危險的罪犯的家園。最近，異常暴動導致了監獄的混亂─所有的守衛都被趕了出來，裡面的罪犯可以自由的活動。', `MaleText_loc7`='Las Mazmorras son un complejo carcelario de alta seguridad, oculto bajo el distrito de Los Canales de la ciudad de Ventormenta. Las Mazmorras, presididas por el celador Thelagua, alojan desde ladronzuelos, hasta insurgentes políticos, asesinos, e incluso a parte de los criminales más peligrosos de la tierra. Hace poco, un motín de los prisioneros tuvo como consecuencia un verdadero pandemonio dentro de las Mazmorras. Los guardias fueron expulsados y los convictos recorrían las instalaciones libremente.', `FemaleText_loc1`='지하감옥은 스톰윈드의 운하 지역 아래에 숨겨진 경비가 삼엄한 교도소입니다. 델워터 교도소장이 감독하는 지하감옥은 삼류 사기꾼, 정치적 반역자, 살인자, 그리고 이 땅에서 가장 위험한 범죄자 수십 명이 모여 있는 곳입니다. 최근, 죄수들이 폭동을 일으켜 지하감옥은 아수라장이 되었고, 경비병들은 쫓겨나고 죄수들이 마음대로 활보하고 있습니다.', `FemaleText_loc4`='监狱是位于暴风城运河区戒备森原的牢房。那里由典狱官塞尔沃特看守着，监狱是那些小偷，政治犯，谋杀者和许多最危险的罪犯的家园。最近，异常暴动导致了监狱的混乱——所有的守卫都被赶了出来，里面的罪犯可以自由的活动。', `FemaleText_loc5`='監獄是位於暴風城運河區戒備森原的牢房。那裡由典獄官塞爾沃特看守著，監獄是那些小偷，政治犯，謀殺者和許多最危險的罪犯的家園。最近，異常暴動導致了監獄的混亂─所有的守衛都被趕了出來，裡面的罪犯可以自由的活動。', `FemaleText_loc7`='Las Mazmorras son un complejo carcelario de alta seguridad, oculto bajo el distrito de Los Canales de la ciudad de Ventormenta. Las Mazmorras, presididas por el celador Thelagua, alojan desde ladronzuelos, hasta insurgentes políticos, asesinos, e incluso a parte de los criminales más peligrosos de la tierra. Hace poco, un motín de los prisioneros tuvo como consecuencia un verdadero pandemonio dentro de las Mazmorras. Los guardias fueron expulsados y los convictos recorrían las instalaciones libremente.' WHERE `ID`=9955;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 강화 마법을 사용했습니다!', `MaleText_loc4`='%s施放增益法术！', `MaleText_loc5`='%s施放增益法術!', `MaleText_loc7`='¡%s ha lanzado un beneficio!' WHERE `ID`=9956;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자들이 들어왔다! 어떤 희생이 있더라도 알을 반드시 수호하라!', `MaleText_loc4`='入侵者闯进了孵化间！我们要不惜一切代价保护龙蛋！', `MaleText_loc5`='入侵者闖入孵化室了!警報!不惜一切代價保護蛋!', `MaleText_loc7`='¡Los invasores han penetrado en El Criadero! ¡Activa la alarma! ¡Hay que proteger los huevos a toda costa!' WHERE `ID`=9958;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부서진 무기와 방어구를 가지고 싸우지 마시오! 전문 방어구 및 무기 수리를 즉석에서 해 드리고 있소이다!', `MaleText_loc4`='不要使用破碎的武器和护甲参加战斗！我这里可以在你等待的时候进行专家级的武器和护甲修理！', `MaleText_loc5`='不要使用壞掉的武器和護甲參加戰鬥!我這裡可以在你等待的時候，進行專家級的武器和護甲修理!', `MaleText_loc7`='No luchéis con armas ni armaduras rotas. ¡Reparación experta de armas y armaduras aquí! Mientras esperáis...' WHERE `ID`=9959;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자! $n, 이제부터 나를 섬겨라!', `MaleText_loc4`='愚蠢的$n，你现在为我服务！', `MaleText_loc5`='愚蠢的$n，你現在為我服務!', `MaleText_loc7`='Insensato $n, ahora eres... ¡mi esclavo!' WHERE `ID`=9960;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대가를 꼭 치르게 해주마!', `MaleText_loc4`='你要为强迫我这么做而付出代价！', `MaleText_loc5`='你要為逼我這麼做而付出代價!', `MaleText_loc7`='¡Pagaréis por obligarme a hacer esto!' WHERE `ID`=9961;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바보들아! 이 알들이 얼마나 귀한 것인데!', `MaleText_loc4`='蠢货！这些蛋比你认为的要珍贵的多！', `MaleText_loc5`='愚蠢的人!這些蛋比你知道的要珍貴的多!', `MaleText_loc7`='¡Locos! ¡Esos huevos son más valiosos de lo que creéis!' WHERE `ID`=9962;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 이상은 안 돼! 죗값은 너희들 머리로 받겠다!', `MaleText_loc4`='不！住手！我要会让你来弥补自己的罪行！', `MaleText_loc5`='不─不應該再發生的!我要你的頭顱來彌補你的暴行!', `MaleText_loc7`='¡No, otro no! ¡Rodarán sus cabezas por esta infamia!' WHERE `ID`=9963;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용서해라! 나도 죗값을 치르게 될 것이다!', `MaleText_loc4`='原谅我，$n！你的死亡让我的失败更加沉重！', `MaleText_loc5`='原諒我，$n!你的死只是徒增我的失敗而已!', `MaleText_loc7`='¡Perdóname, $n! ¡Tu muerte se añade a mi fracaso!' WHERE `ID`=9964;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네파리우스가 나를 강하게 만들었다. 내 혈관에는 네파리우스의 증오와 검은바위 부족의 분노가 흐르고 있다!', `MaleText_loc4`='奈法里奥斯的仇恨让我变得空前强大！赶快逃跑吧，凡人！黑石之王的怒气涌动在我的血脉中！', `MaleText_loc5`='奈法利斯的恨意讓我比先前變得更加強大!你們應該要在可以逃走前，趕快逃走，凡人!黑石族的狂怒，已經在我的血管中流動了!', `MaleText_loc7`='¡El odio de Nefarius me ha hecho más fuerte que nunca! ¡Deberían haber escapado mientras podrían, mortales! ¡La furia de Roca Negra corre por mis venas!' WHERE `ID`=9965;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용군단을 보호하라! 이 침입자들을 즉각 처단하라!', `MaleText_loc4`='保护黑龙！杀掉所有的入侵者！', `MaleText_loc5`='保護黑龍!入侵者現在就要被處決!', `MaleText_loc7`='¡Proteged el Vuelo! ¡Hay que matar a los intrusos!' WHERE `ID`=9966;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 같은 놈들이 올 곳은 아닌데... 죽음을 자초했구나!', `MaleText_loc4`='你怎么进来的？你们这种生物不能进来！我要毁灭你们！', `MaleText_loc5`='你怎麼進來的?你們這種生物不能進來!我要毀滅你們!', `MaleText_loc7`='¡Nadie de su raza debería estar aquí! ¡Están condenados!' WHERE `ID`=9967;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='약삭빠르구나... 하지만 난 쉽게 무너지지 않는다!', `MaleText_loc4`='你们很聪明，凡人——但是我不会那么轻易地离开我的圣地！', `MaleText_loc5`='你們很聰明，凡人─但是我是不會那麼輕易地離開我的聖地的!', `MaleText_loc7`='Muy ingenioso, mortales. ¡Pero no es tan fácil apartarme de mi santuario!' WHERE `ID`=9968;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 피 견본들을 반드시 보호해야 한다! 침입자들을 처치하라!', `MaleText_loc4`='保护血液样品！摧毁入侵者！', `MaleText_loc5`='血液樣品會保護我!摧毀入侵者1', `MaleText_loc7`='¡Hay que proteger las muestras de sangre! ¡Destruid a los intrusos!' WHERE `ID`=9969;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이럴 수가! 이곳의 주인은 나다! 우리에 비하면 너희는 아무것도 아니다! 아무것도!', `MaleText_loc4`='这不可能！我是这里的主人！你们这些凡人对于我来说一无是处！听到了没有？一无是处！', `MaleText_loc5`='這不可能!我是這裡的主人!你們凡人對於我來說一無是處!聽到了沒有?一無是處!', `MaleText_loc7`='¡¡No puede ser cierto!! ¡Yo soy el amo aquí! ¡Ustedes mortales no son nada para mi raza! ¿entienden? ¡Nada!' WHERE `ID`=9971;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바보같은 $n! 이제 나머지도 모두 처치해 주마!', `MaleText_loc4`='没用的$n！你的朋友不久之后就会去找你的！', `MaleText_loc5`='毫無價值的$n!你的朋友不久之後就會和你相會!', `MaleText_loc7`='¡Indefenso $n! ¡Tus amigos estarán pronto contigo!' WHERE `ID`=9972;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘했다! 적들의 사기가 떨어지고 있다! 검은바위 첨탑의 군주에게 도전한 대가를 치르게 해주자!', `MaleText_loc4`='干得好，我的手下。凡人的勇气开始消退了！现在，让我们看看他们如何应对黑石塔的真正主人的力量！！！', `MaleText_loc5`='幹得好，我的手下。凡人的勇氣開始消退!現在，現在讓我們看看他們如何應對黑石之王的力量!!!', `MaleText_loc7`='Bien hecho, mis esbirros. El coraje de los mortales empieza a mermar. ¡Veamos ahora cómo se enfrentan al verdadero Señor de la Cumbre de Roca Negra!' WHERE `ID`=9973;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불타라! 활활!', `MaleText_loc4`='燃烧吧！你们这些悲惨的家伙！燃烧吧！', `MaleText_loc5`='燃燒吧!你這個不幸的人!燃燒吧!', `MaleText_loc7`='¡ARDAN! ¡Miserables! ¡ARDAN!' WHERE `ID`=9974;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요리에 필요한 재료라면 뭐든 다 가지고 있다네!', `MaleText_loc4`='我这里有你所需要的所有烹饪材料，伙计！', `MaleText_loc5`='我這裡有你所需要的所有烹飪材料，夥計!', `MaleText_loc7`='¡Tengo to''s los suministros de cocina que podrías necesitar, colega!' WHERE `ID`=9975;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='깨진엄니 마을에 잘 왔네. 나는 깨진엄니 트롤의 지도자인 주술사 톤터스크라고 하네.', `FemaleText_loc4`='欢迎来到恶齿村，陌生的$c。我是断齿族长，这里的领袖。', `FemaleText_loc5`='歡迎來到惡齒村，陌生人。我是族長托塔斯克，惡齒食人妖的領袖。', `FemaleText_loc7`='Te doy la bienvenida al Poblado Sañadiente, $gforastero:forastera;. Soy Primigenia Colmillopartido, líder de los trols Sañadiente.' WHERE `ID`=9976;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부서진 거라면 이 슬래그트리가 뭐든 고칠 수 있소!', `MaleText_loc4`='如果它坏了，那么斯拉提可以修理它！', `MaleText_loc5`='如果它壞了，那麼斯拉提可以修理它!', `MaleText_loc7`='¡Si tá roto, Esco puede arreglarlo!' WHERE `ID`=9977;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='거기, 내 물건에 발 대지 말란 말이야.', `FemaleText_loc4`='别踩到我的货物，小心。', `FemaleText_loc5`='別踩到我的商品，陌生人。', `FemaleText_loc7`='No te des prisa al mirar mis mercancías.' WHERE `ID`=9978;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='낚시란 참 즐거운 거란 말이야. 자네도 아나? 내 스승이자 전 세계에서 가장 훌륭한 낚시꾼인 내트 페이글 님 덕분에 이런 큰 기쁨을 누리게 되었지. 그분에 대해 들어 본 적이 있나?$B$B깨달음을 얻고 싶다면 내트 페이글 님께서 길을 보여 주실 걸세.', `MaleText_loc4`='钓鱼只是为了娱乐，伙计。你知道吗？我是在向我的导师学习，世界上最伟大的钓鱼者——纳特·帕格。你听说他没有，伙计？$B$B如果你想要寻求启迪，那么纳特·帕格会指引你前进的道路。', `MaleText_loc5`='釣魚只是為了娛樂，夥計。你知道嗎?我是在向我的導師學習，世界上最偉大的釣魚者─納特·帕格。你聽說他沒有，夥計?$B$B如果你想要尋求啟迪，那麼納特·帕格會指引你前進的道路。', `MaleText_loc7`='Pescar es guay, colega. ¿Sabes? Debo mi felicidad a mi mentor, el mejor pescador de to''l mundo, Nat Pagle. ¿Has oído hablar de él, colega?$B$BSi tás buscando la felicidad, Nat Pagle puede enseñarte el camino.' WHERE `ID`=9979;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무엇을 가르쳐 줄 수 있습니까?', `MaleText_loc4`='你可以教我什么？', `MaleText_loc5`='你可以教我什麼?', `MaleText_loc7`='¿Qué puedes enseñarme?', `FemaleText_loc1`='무엇을 가르쳐 줄 수 있습니까?', `FemaleText_loc4`='你可以教我什么？', `FemaleText_loc5`='你可以教我什麼?', `FemaleText_loc7`='¿Qué puedes enseñarme?' WHERE `ID`=9980;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언젠가는 줄진 님께서 돌아오실 걸세. 내 말 잘 듣게나. 그때까지는 우리 모두 우리 위치를 사수하고 숲트롤의 수가 조금이라도 줄어들지 않게 하는 데 최선을 다해야 하네.$B$B따라서 깨진엄니 마을의 사냥의 대가로서 내 임무는 우리 주변의 환경을 살기에 안전하게 만드는 것일세.$B$B이 지역의 짐승들을 반드시 제압해야만 하네.$B$B혹시 일거리를 찾고 있는 건가?', `MaleText_loc4`='祖尔金总有一天会回来的，$r。记住我的话。在那一天到来之前，我们会尽我们的所能保证森林巨魔族群的昌盛。$B$B作为恶齿村的猎人头领，我的责任就是保证我们的安全。$B$B我必须对这一带的野兽进行监控。$B$B你是不是来找活干的？', `MaleText_loc5`='祖爾金有一天會回來的，$r。記住我的話。在那一天到來之前，我們會守住我們的位置並保護森林食人妖的數量。$B$B作為惡齒村的獵人首領，我的責任就是確保我們居住環境的安全。$B$B我對這個區域周圍的野獸都要進行監控。$B$B你是不是來找些活幹的?', `MaleText_loc7`='Zul''jin volverá algún día, $r. Recuerda lo que te digo. Hasta entonces, todos mantendremos nuestra posición y haremos todo lo que podemos para que la población de trols de bosque permanezca intacta.$B$BDicho esto, como maestro cazador del Poblado Sañadiente, es mi responsabilidad asegurar que el mundo que nos rodea sea un lugar seguro para vivir.$B$BHay que controlar a las bestias de esta zona.$B$B¿Estás buscando trabajo?' WHERE `ID`=9981;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마코르 씨, 제 야수를 맡기고 싶습니다.', `MaleText_loc4`='马克霍尔，我要把我的宠物收藏起来。', `MaleText_loc5`='馬克霍爾，我要把我的寵物收藏起來。', `MaleText_loc7`='Markhor, quiero dejar a mi mascota en el establo.', `FemaleText_loc1`='마코르 씨, 제 야수를 맡기고 싶습니다.', `FemaleText_loc4`='马克霍尔，我要把我的宠物收藏起来。', `FemaleText_loc5`='馬克霍爾，我要把我的寵物收藏起來。', `FemaleText_loc7`='Markhor, quiero dejar a mi mascota en el establo.' WHERE `ID`=9982;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 도끼의 달인 킬램이라고 하네.', `MaleText_loc4`='我是基尔拉姆，斧系大师。', `MaleText_loc5`='我是基爾拉姆，斧類大師。', `MaleText_loc7`='Soy Kilram, maestro del hacha.' WHERE `ID`=9983;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 한때는 경험 많은 노련한 분이셨군요. 이 킬램이 다시 노련한 제작자로 만들어 드리지요. 당신은 재능이 있어 보이니 요청만 하시면 도끼 제작자의 길을 가르쳐 드리겠습니다.', `MaleText_loc4`='啊，一个经历丰富的冒险者。基尔拉姆又让你来这里了。我知道你具有相当的能力，你只需要询问我，我就会教你斧系铁匠的知识。', `MaleText_loc5`='啊，一個經歷豐富的冒險者。基爾拉姆讓你來這裡了。我知道你具有相當的能力，你只需要詢問我，我就會教你斧類鍛造師的知識。', `MaleText_loc7`='Ah, una vez fuiste $gun veterano:una veterana;. Kilram puede hacer que te conviertas en eso de nuevo. Sé que eres capaz, solo tienes que pedírmelo y te enseñaré a forjar hachas.' WHERE `ID`=9984;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도끼 제작자가 되는 법을 가르쳐 주십시오, 킬램.', `MaleText_loc4`='请告诉我如何成为一名铸斧师，基尔拉姆。', `MaleText_loc5`='請教我如何成為斧類鍛造師，基爾拉姆。', `MaleText_loc7`='Por favor, enséñame a ser un forjador de hachas, Kilram.', `FemaleText_loc1`='도끼 제작자가 되는 법을 가르쳐 주십시오, 킬램.', `FemaleText_loc4`='请告诉我如何成为一名铸斧师，基尔拉姆。', `FemaleText_loc5`='請教我如何成為斧類鍛造師，基爾拉姆。', `FemaleText_loc7`='Por favor, enséñame a ser una forjadora de hachas, Kilram.' WHERE `ID`=9985;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n, 너무 가까이 오지는 마세요. 잘못해서 이 망치를 당신 얼굴 쪽으로 휘두르기라도 하면 큰일이니까요.', `FemaleText_loc4`='不要靠得太近，$n。我手中的铁锤可能会敲到你。', `FemaleText_loc5`='不要靠得太近，$n。我有可能失誤將我的錘子敲到你的腦袋。', `FemaleText_loc7`='No te acerques demasiado, $n. Puedo aplastarte y abrirte el cerebro a golpes con mi martillo.' WHERE `ID`=9986;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='망치 제작자의 길을 가르쳐 줄 테니 정중하게 요청만 하세요.', `FemaleText_loc4`='我会教你锤系专精之道。你只需要恭恭敬敬地问我就可以了。', `FemaleText_loc5`='我會教你錘類鍛造的專精之道。你只需要恭恭敬敬地問我就可以了。', `FemaleText_loc7`='Te enseñaré a forjar martillos. Solo tienes que pedírmelo amablemente.' WHERE `ID`=9987;
