UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검 제작자가 되고 싶으면 물어만 보세요.', `MaleText_loc4`='如果你希望成为一名铸剑师，那就问问我吧。', `MaleText_loc5`='如果你希望成為一名劍類鍛造師，那就問問我吧。', `MaleText_loc7`='Si quieres convertirte en $gun forjador:una forjadora; de espadas, solo tienes que pedírmelo.' WHERE `ID`=9990;
