UPDATE `locales_broadcast_text` SET `MaleText_loc1`='웬 바보 하나가 또 덫에 걸렸구나!', `MaleText_loc4`='又一个掉进陷阱的傻瓜！', `MaleText_loc5`='又一個掉進陷阱的傻瓜!', `MaleText_loc7`='¡Otro imbécil que cae en la trampa!', `FemaleText_loc1`='웬 바보 하나가 또 덫에 걸렸구나!', `FemaleText_loc4`='又一个掉进陷阱的傻瓜！', `FemaleText_loc5`='又一個掉進陷阱的傻瓜!', `FemaleText_loc7`='¡Otro imbécil que cae en la trampa!' WHERE `ID`=10003;
