UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 뼈를 대여사제님의 식탁 위에 올려 주마!', `MaleText_loc4`='高阶女祭司会吞噬你的骨头！', `MaleText_loc5`='高階女祭司將會好好享受用你的骨頭做的佳餚!', `MaleText_loc7`='¡La suma sacerdotisa se dará un festín con tus huesos!', `FemaleText_loc1`='네 뼈를 대여사제님의 식탁 위에 올려 주마!', `FemaleText_loc4`='高阶女祭司会吞噬你的骨头！', `FemaleText_loc5`='高階女祭司將會好好享受用你的骨頭做的佳餚!', `FemaleText_loc7`='¡La suma sacerdotisa se dará un festín con tus huesos!' WHERE `ID`=10005;
