UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적들에게서 보급품을 빼앗아 왔군! 잘했소, $n!', `MaleText_loc4`='我们敌人送来的补给品！干得好，$n！', `MaleText_loc5`='我們敵人送來的補給品!幹得好，$n!', `MaleText_loc7`='¡Suministros de nuestros enemigos! ¡Bien hecho, $n!' WHERE `ID`=10007;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적들에게서 보급품을 빼앗아 왔군! 하하! 잘했소, $n!', `MaleText_loc4`='你带来了我们敌人的补给品！哈哈！干得好$n！', `MaleText_loc5`='你帶來了我們敵人的補給品!哈哈!幹得好$n!', `MaleText_loc7`='¡Has traído suministros de los enemigos! ¡Ja! ¡Bien hecho, $n!' WHERE `ID`=10008;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자다! 공격당하고 있다! 놈들을 잡아라!', `MaleText_loc4`='入侵者！入侵者！我们遭受攻击，孩子们！干掉他们！', `MaleText_loc5`='入侵者!入侵者!我們遭受攻擊，孩子們!幹掉他們!', `MaleText_loc7`='¡Invasores! ¡Invasores! ¡Nos atacan, chicos! ¡A por ellos!' WHERE `ID`=10009;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최후의 의식을 행하노라. 이것으로 충분하기를...', `MaleText_loc4`='我要作最后一次努力。希望它能有效……', `MaleText_loc5`='我將進行最後一步。我希望它能有效...', `MaleText_loc7`='Voy a realizar un último servicio. Rezo para que sea suficiente...' WHERE `ID`=10010;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 됩니다, 밸라스트라즈!!!', `MaleText_loc4`='瓦拉斯塔兹，不！！！', `MaleText_loc5`='瓦拉斯塔茲，不!!!', `MaleText_loc7`='¡¡¡Vaelastrasz, no!!!', `FemaleText_loc1`='안 됩니다, 밸라스트라즈!!!', `FemaleText_loc4`='瓦拉斯塔兹，不！！！', `FemaleText_loc5`='瓦拉斯塔茲，不!!!', `FemaleText_loc7`='¡¡¡Vaelastrasz, no!!!' WHERE `ID`=10011;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='열쇠를 가져와 이 족쇄를 풀어 주게나! 열쇠는 동굴 뒤편에 있는 수호자 히타야가 가지고 있다네.', `MaleText_loc4`='拿到钥匙，打开这些锁链！钥匙在守护者希坦亚手里……就在洞的后面……', `MaleText_loc5`='拿到鑰匙，打開這些鎖鍊!鑰匙在『守衛者』希坦亞手裡...就在洞的後面...', `MaleText_loc7`='¡Coge la llave y abre estas cadenas! La tiene Hitah''ya el Guardián... En la parte de atrás de la cueva...' WHERE `ID`=10012;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마침내 자유의 몸이로군! 얼른 집에 돌아가서 아내의 얼굴을 보고 싶군.', `MaleText_loc4`='终于，我自由了！我终于回家了！', `MaleText_loc5`='終於，我自由了!我終於回家了，我親愛的!', `MaleText_loc7`='¡Por fin soy libre! ¡Pronto volveré a casa, mi amor!' WHERE `ID`=10013;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투를 시작하겠습니다!', `MaleText_loc4`='让战斗开始吧！', `MaleText_loc5`='戰鬥現在開始了!', `MaleText_loc7`='¡Que comience la batalla!' WHERE `ID`=10014;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='1분 후 전쟁노래 협곡 전투가 시작됩니다!', `MaleText_loc4`='战歌峡谷战斗将在1分钟内开始。', `MaleText_loc5`='戰歌峽谷戰鬥將在1分鐘內開始。', `MaleText_loc7`='La batalla por la Garganta Grito de Guerra comenzará en 1 minuto.' WHERE `ID`=10015;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='30초 후 전쟁노래 협곡 전투가 시작됩니다. 준비하십시오!', `MaleText_loc4`='战歌峡谷战斗将在30秒钟内开始。做好准备！', `MaleText_loc5`='戰歌峽谷戰鬥將在30秒鐘內開始。做好準備!', `MaleText_loc7`='La batalla por la Garganta Grito de Guerra comenzará en 30 segundos. ¡Preparaos!' WHERE `ID`=10016;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구인광고/분실물센터/현상 수배:', `MaleText_loc4`='工作/遗失和找到物品/悬赏：', `MaleText_loc5`='工作/遺失和找到物品/懸賞:', `MaleText_loc7`='Ofertas de trabajo/Perdido y encontrado/Se busca:' WHERE `ID`=10017;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저그 저그! 내 이름은 켈름 하건스! 전쟁노래 척후병들을 위해 보급품을 도맡아 공급하는 상인일세. 우리 부족을 위해 자네의 실력을 증명해 보인다면 전쟁노래 협곡에서만 사용할 수 있는 좋은 물건들을 보여주도록 하지. 거기다 장비 수리 서비스도 제공하고 있으니까 뭐라도 부서지면 찾아주라고!', `MaleText_loc4`='你好，我的朋友！我是哈古斯，战歌前锋部队的军需官。随着你在战歌氏族中的声望不断提升，我可以为你提供一些可在战歌峡谷中使用的商品。如果你需要修理装备的话，我也可以提供这样的服务。', `MaleText_loc5`='嘖嘖，我的朋友!我是戰歌補給員哈古斯，戰歌先遣騎的主要供給商。隨著你在戰歌氏族中的地位不斷提升，我可以提供一些你可以在戰歌峽谷中使用的商品。如果你需要修理裝備的話，我也可以提供這樣的服務。', `MaleText_loc7`='¡Zug zug, $gamigo:amiga;! Soy Kelm Hargunth, el principal proveedor de los escoltas Grito de Guerra. A medida que vaya aumentando tu prestigio entre los escoltas, iré poniendo a tu disposición una cuidada selección de artículos que podrás usar en la Garganta Grito de Guerra. Si necesitas un servicio de reparación, también puedo ofrecértelo.' WHERE `ID`=10018;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전쟁노래 협곡에서 구입해 쓸 수 있는 물건들을 좀 보여 주십시오.', `MaleText_loc4`='我现在赢得了在战歌峡谷中购买哪些物品的权利？', `MaleText_loc5`='我現在贏得了在戰歌峽谷中購買哪些物品的權利?', `MaleText_loc7`='¿Me he ganado el derecho de comprar algún objeto para usar en la Garganta Grito de Guerra?', `FemaleText_loc1`='전쟁노래 협곡에서 구입해 쓸 수 있는 물건들을 좀 보여 주십시오.', `FemaleText_loc4`='我现在赢得了在战歌峡谷中购买哪些物品的权利？', `FemaleText_loc5`='我現在贏得了在戰歌峽谷中購買哪些物品的權利?', `FemaleText_loc7`='¿Me he ganado el derecho de comprar algún objeto para usar en la Garganta Grito de Guerra?' WHERE `ID`=10019;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='밤의 축복이 함께하기를! 저는 여기 잿빛 골짜기를 책임지고 있는 은빛날개 파수대의 병참장교 문블레이즈라고 합니다. 우리 은빛날개 파수꾼을 위한 싸움을 통해 그대의 실력을 증명하신다면 전쟁노래 협곡에서만 사용할 수 있는 좋은 물건들을 보여드리겠습니다. 거기다 장비 수리 서비스도 제공하고 있으니까 고칠 물건이 있으시면 언제든지 찾아주십시오.', `FemaleText_loc4`='愿夜之祝福永远与你同在，我的朋友！我是艾蒂尔·月火，我是灰谷银翼哨兵部队的军需官。随着你在银翼哨兵中的声望不断提升，我可以为你提供一些可在战歌峡谷中使用的商品。如果你需要修理装备的话，我也可以提供这样的服务。', `FemaleText_loc5`='願夜之祝福永遠與你同在，我的朋友!我是艾蒂爾·月火，我是梣谷銀翼哨兵部隊的軍需官。隨著你在銀翼哨兵中的聲望不斷提升，我可以為你提供一些可在戰歌峽谷中使用的商品。如果你需要修理裝備的話，我也可以提供這樣的服務。', `FemaleText_loc7`='¡Que las bendiciones de la noche sean tuyas, $gamigo:amiga;! Soy Illiyana Lunardiente, y la principal proveedora de los centinelas Ala de Plata aquí, en Vallefresno. A medida que vaya aumentando tu prestigio entre los centinelas, iré poniendo a tu disposición una cuidada selección de artículos que podrás usar en la Garganta Grito de Guerra. Si necesitas un servicio de reparación, también puedo ofrecértelo.' WHERE `ID`=10020;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 전쟁노래 협곡에서 구입해 쓸 수 있는 물건들을 좀 보여주세요.', `MaleText_loc4`='我现在赢得了在战歌峡谷中购买哪些物品的权利？', `MaleText_loc5`='我現在贏得了在戰歌峽谷中購買哪些物品的權利?', `MaleText_loc7`='¿Me he ganado el derecho de comprar algún objeto para usar en la Garganta Grito de Guerra?', `FemaleText_loc1`='제가 전쟁노래 협곡에서 구입해 쓸 수 있는 물건들을 좀 보여주세요.', `FemaleText_loc4`='我现在赢得了在战歌峡谷中购买哪些物品的权利？', `FemaleText_loc5`='我現在贏得了在戰歌峽谷中購買哪些物品的權利?', `FemaleText_loc7`='¿Me he ganado el derecho de comprar algún objeto para usar en la Garganta Grito de Guerra?' WHERE `ID`=10021;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스 깃발이 기지로 반환되었습니다!', `MaleText_loc4`='联盟的旗帜回到了它的基地！', `MaleText_loc5`='聯盟的旗幟被歸還到它的基地了!', `MaleText_loc7`='¡La bandera de la Alianza ha sido devuelta a la base!' WHERE `ID`=10022;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드 깃발이 기지로 반환되었습니다!', `MaleText_loc4`='部落军旗已回到旗座上了！', `MaleText_loc5`='部落的旗幟被歸還到它的基地了!', `MaleText_loc7`='¡La bandera de la Horda ha sido devuelta a la base!' WHERE `ID`=10023;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 여기 있다! 깊은무쇠 광산은 내 거다!', `MaleText_loc4`='我在这里了！深铁矿洞是……我的！', `MaleText_loc5`='我在這裡了!深鐵礦坑是...我的!', `MaleText_loc7`='¡Estoy aquí! Y la Mina Ferrohondo es... ¡MÍA!' WHERE `ID`=10024;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 여기 있지롱! 얼음이빨 광산은 이 스니블 님의 것이다!', `MaleText_loc4`='斯尼维尔在此！冷齿矿洞是斯尼维尔的！', `MaleText_loc5`='斯尼維爾在此!冷齒礦坑是斯尼維爾的!', `MaleText_loc7`='¡Snivvle está aquí! ¡Snivvle reclama la Mina Dentefrío!' WHERE `ID`=10025;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='증오의 똬리를 틀 시간이다!', `MaleText_loc4`='让复仇的毒蛇吞噬你们吧！', `MaleText_loc5`='讓仇恨的圈圈就此展開吧!', `MaleText_loc7`='¡Que se desplieguen los anillos del odio!' WHERE `ID`=10026;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='히르이크시여, 저에게 복수의 날개를 달아주소서!', `FemaleText_loc4`='希里克，赐予我复仇的翅膀！', `FemaleText_loc5`='希爾雷克吾主，賦予我復仇之翼的力量吧!', `FemaleText_loc7`='¡Señor Hir''eek, concédeme alas de venganza!' WHERE `ID`=10027;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오세요! 이곳은 바로 예브 네블기어의 다크문 별난 동물원입니다. 살아 있는 전설과 신비로운 것들이 모여 있는 곳이죠! 마음껏 즐기십시오!$B$B하지만 아무거나 함부로 만져서는 안 됩니다! 여기에 전시된 유물과 짐승들에는 신성한 것도 있고, 아주 무시무시한 것도 있으니까요! 과도한 호기심을 참지 못하고 함부로 만졌다가는 손이 불에 탈 수 있습니다...', `MaleText_loc4`='欢迎！欢迎来到亚布·尼比盖尔的暗月珍奇馆——这儿有来自世界各地的奇珍异宝！朋友，尽情参观吧！$B$B但是不要动手触摸！神圣的神器和可怕的野兽守护着这些展品！随意触碰的话，它们可能会烧伤你的手……', `MaleText_loc5`='歡迎!歡迎來到亞布·尼比蓋爾的暗月珍奇館，各種傳奇生物跟神秘物品的大集合!請盡情的參觀，朋友!$B$B但是請注意你的手摸到的東西!這些展品包括了神聖及可怕的神器及野獸!它們可能會燒掉過度好奇的參觀者那些討厭的手...', `MaleText_loc7`='¡$gBienvenido:Bienvenida;! Te doy la bienvenida al Zoo de Singularidades Luna Negra de Yebb Tesorillos. ¡Un tesoro de leyendas vivientes y rarezas míticas! ¡Que disfrutes de la visita, $gamigo:amiga;!$B$B¡Pero cuidado con lo que tocas! En las exhibiciones hay bestias y artefactos tanto letales como divinos. Podrían quemar la mano caprichosa de un observador demasiado curioso...' WHERE `ID`=10028;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘은 어디로 보내 드릴까요?', `MaleText_loc4`='今天要我送你去哪里，$c？', `MaleText_loc5`='今天要我送你去哪裡，$c?', `MaleText_loc7`='¿Dónde te puedo mandar hoy, $c?' WHERE `ID`=10029;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불모의 땅에서는 십자로가 가장 번화한 중심지인 것 같지만 전 타우라조 야영지의 평온함이 더 마음에 듭니다. 그런데 어디로 보내 드릴까요?', `MaleText_loc4`='虽然十字路口似乎是贫瘠之地的中心地带，但是我更喜欢陶拉祖营地的安静。你想去哪儿？', `MaleText_loc5`='雖然十字路口似乎是貧瘠之地的活動中心點，但是我更喜歡陶拉祖營地的安靜。你想去哪兒?', `MaleText_loc7`='El Cruce parece ser el centro de actividad de Los Baldíos, yo prefiero la tranquilidad del Campamento Taurajo. ¿Dónde te voy a mandar?' WHERE `ID`=10030;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대지모신께 이르는 길은 여러 가지가 있습니다. 언제 어디에서 여행을 하든지 대지모신께서 그대를 지켜주시기를...', `MaleText_loc4`='这些道路都是大地之母走过的道路。无论你决定前往何方，愿大地之母与你同在。', `MaleText_loc5`='這些道路都是大地之母走過的道路。無論你決定前往何方，願大地之母與你同在。', `MaleText_loc7`='Muchos son los caminos de la Madre Tierra. Decidas donde decidas ir, que ella te proteja.' WHERE `ID`=10031;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와이번을 잘 다루십시오. 그대를 원하는 목적지로 데려가 줄 테니까. $n, 선조의 가호가 있기를 빕니다.', `MaleText_loc4`='当双足飞龙将你送达目的地之后，请好好款待它。愿你的祖先与你同在，$n。', `MaleText_loc5`='善待這頭雙足飛龍，牠將會搭載你到達目的地。願你的祖先與你同在，$n。', `MaleText_loc7`='Trata bien al jinete del viento, ya que te lleva a tu destino. Que tus ancestros te protejan, $n.' WHERE `ID`=10032;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아제로스 최고의 쇼에 오신 것을 환영합니다!$B$B어서 오셔서 마음껏 즐기세요. 다크문 유랑단이 이 드넓고 신비한 세계를 유랑하며 발견한 온갖 놀라운 물건들을 구경하시라니까요! 다양한 연령층의 어린이들이 모두 좋아할 만한 것들을 아낌없이 준비해 놓았답니다!', `MaleText_loc4`='你好，我的朋友，欢迎来到艾择拉斯最伟大的展览会！$B$B请尽情浏览我们展出的东西吧。来看看这些暗月马戏团在广袤而又神秘的艾泽拉斯世界中找到的各种千奇百怪的东西！我们不收取任何费用，我们为你带来无限惊喜，为孩子们带来让他们兴奋的东西！', `MaleText_loc5`='你好!我的朋友，歡迎來到艾澤拉斯大陸上最偉大的博覽會!$B$B請往前走並享受我們所提供的一切。讓暗月馬戲團在這個巨大而神秘的世界上所發現的奇特事物為你帶來前所未有的驚奇!我們會繼續不遺餘力地為各個年齡的小孩帶來雀躍不已的興奮感受!', `MaleText_loc7`='¡Hola, $gamigo:amiga;, te doy la bienvenida al mayor espectáculo de todo Azeroth!$B$BPor favor, pasa y disfruta de todo lo que podemos ofrecerte. ¡Sorpréndete con las maravillas que la Feria de la Luna Negra ha descubierto en este vasto y misterioso mundo! No hemos reparado en gastos para poder ofrecer una diversión tan increíble que deleitará a niños de todas las edades.' WHERE `ID`=10033;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아제로스 최고의 쇼에 다시 오신 것을 환영합니다! 다시 뵙게 돼서 정말 기뻐요!$B$B어서 오세요! 다시 한번 마음껏 즐기시기 바랍니다. 다크문 축제에는 항상 새롭고 신나는 것들이 늘어만 가고 있으니 구석구석 둘러보세요! 그동안 발견한 온갖 놀라운 물건들을 구경하세요! 어린이라면 모두 좋아할 만한 것들을 아낌없이 준비해 놓았답니다!', `MaleText_loc4`='朋友，欢迎回到艾泽拉斯最盛大的展览！很高兴再次看到你。$B$B请接受我们的盛情邀请吧。请四下看看，我们暗月马戏团中有许多新奇的事物！看看我们带来的各种货物吧！我们会继续免费为大家带来更多惊喜的，孩子们都乐意参加！', `MaleText_loc5`='歡迎回到艾澤拉斯大陸上最偉大的表演，我的朋友!很高興再次看到你。$B$B請往前走並享受我們所提供的一切。請務必要四處逛逛，因為我們會不斷的為暗月馬戲團增加新鮮而刺激的事物!讓我們所發現的各種新舊的奇特事物為你帶來前所未有的驚奇吧!我們會繼續不遺餘力地為各個年齡的小孩帶來雀躍不已的興奮感受!', `MaleText_loc7`='¡$gBienvenido:Bienvenida; de nuevo al mejor espectáculo de Azeroth, $gamigo:amiga;! Es un verdadero placer volver a verte.$B$BAcércate y observa todo lo que ofrecemos. ¡No dejes de echar un vistazo, ya que estamos continuamente añadiendo cosas nuevas a la Feria de la Luna Negra! ¡Maravíllate con todo lo que hemos descubierto! ¡Seguimos sin reparar en gastos para proporcionaros diversiones con las que deleitar a niños de todas las edades!' WHERE `ID`=10034;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실라스, 어떻게 이 축제는 대부분이 무료로 운영되고 있나요? 대체 수익은 어떻게 내는 겁니까?', `MaleText_loc4`='希拉斯，为什么马戏团里的大部分设施都是免费的？那你是怎么赚钱的？', `MaleText_loc5`='希拉斯，為什麼馬戲團的東西幾乎都是免費的?你要如何獲取利潤呢?', `MaleText_loc7`='Silas, ¿por qué casi todo lo de la feria es gratis? ¿Cómo sacan beneficios?', `FemaleText_loc1`='실라스, 어떻게 이 축제는 대부분이 무료로 운영되고 있나요? 대체 수익은 어떻게 내는 겁니까?', `FemaleText_loc4`='希拉斯，为什么马戏团里的大部分设施都是免费的？那你是怎么赚钱的？', `FemaleText_loc5`='希拉斯，為什麼馬戲團的東西幾乎都是免費的?你要如何獲取利潤呢?', `FemaleText_loc7`='Silas, ¿por qué casi todo lo de la feria es gratis? ¿Cómo sacan beneficios?' WHERE `ID`=10035;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돈이 문제가 아니죠! 사실 상당한 액수의 기부를 받고 있거든요. 때론 정말 어마어마한 거액을 주는 분도 있지요. 저희 유랑단은 전쟁으로 피폐해진 이 세계에 밝은 웃음을 선사하고자 모였어요. 이러한 선의의 목적이 저희의 재능과 노력에 원동력이 되고 있으니 걱정은 마세요. 걱정은 우리가 할게요. 어떻게 하면 여러분을 최고로 즐겁게 해 드릴 수 있을까... 바로 이런 걱정요!', `MaleText_loc4`='这不是钱的问题，伙计！虽然我们接受慷慨的捐赠——有一些捐赠量还很大——我们旅行车队的信念是为这个战火纷飞的世界带来爱与曙光！不要担心我们，让我们来为怎样取悦你们而操心吧。', `MaleText_loc5`='有些時候跟錢是沒關係的，朋友!我們接受很多慷慨的捐獻－有些還是非常大的數目。我們旅行團的所有表演者都因為想要激勵這個被戰爭撕裂的世界而充滿活力與幹勁。不需要擔心我們，相反的，讓我們擔心如何才可以最好的取悅你們吧。', `MaleText_loc7`='¡No siempre es cuestión de dinero! Recibimos donaciones muy generosas, algunas de ellas extremadamente sustanciales. Y, además, nuestra compañía está motivada por la necesidad de animar este mundo devastado por la guerra. No te preocupes por nosotros. Deja que seamos nosotros los que nos preocupemos por ti y por tu diversión.' WHERE `ID`=10036;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상품권 교환! 귀한 상품으로 바꿔 가게나!', `MaleText_loc4`='兑换奖券啦！换取礼物啦！快来啊！', `MaleText_loc5`='票券兌換處在這兒!將你的票券兌換成獎品!趕快來吧!', `MaleText_loc7`='¡Canje de vales! ¡Cambiamos sus vales por premios! ¡Vengan!' WHERE `ID`=10037;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저리 비켜, 촌뜨기...', `MaleText_loc4`='闪开，乡巴佬。', `MaleText_loc5`='閃開點，鄉巴佬。', `MaleText_loc7`='Vete de aquí, $gpalurdo:palurda;.' WHERE `ID`=10038;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 탈것 아니야. 저리 꺼져.', `MaleText_loc4`='这不是一匹坐骑，伙计。', `MaleText_loc5`='這不是一匹坐騎，朋友。', `MaleText_loc7`='Esto no es una atracción, $gpaleto:paleta;. Lárgate.' WHERE `ID`=10039;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신경 건드리고 싶지 않으면 입 다물어. 그래, 아예 숨도 쉬지 마.', `MaleText_loc4`='如果你想表示友好的话，就请屏住呼吸。最好停止呼吸。', `MaleText_loc5`='如果你想要試圖表示友善，那就別說話吧。最好乾脆連呼吸都不要。', `MaleText_loc7`='Si estás intentando ganarme con tu simpatía, no gastes saliva. O mejor, trágatela toda a ver si te ahogas...' WHERE `ID`=10040;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직도 이해를 못 했나? 나 여기 장사하러 온 거 아니다.', `MaleText_loc4`='事先说明，我来这里不是来搞客户关系的。', `MaleText_loc5`='為了避免那不夠明顯，我並不是來這邊搞公關的。', `MaleText_loc7`='Por si no ha quedado claro, no estoy aquí de relaciones públicas.' WHERE `ID`=10041;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너 실라스 괴롭히면 나 화낼 거다. 좋은 하루!', `MaleText_loc4`='你打扰希拉斯，又打扰我。祝你开心。', `MaleText_loc5`='你打擾希拉斯，就是打擾我。祝你有個愉快的一天。', `MaleText_loc7`='Si te metes con Silas, te metes conmigo. Que tengas un buen día.' WHERE `ID`=10042;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='머리가 하나 더 필요해. 지금 달린 건 언제 떨어질지 몰라.', `MaleText_loc4`='我需要第二个头，就像我需要把第一个砍掉一样。', `MaleText_loc5`='我需要第二個頭，就像我需要把第一個弄掉一樣。', `MaleText_loc7`='Tener una segunda cabeza me resultaría tan útil como perder la que tengo.' WHERE `ID`=10043;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐 혈투의 전장에서 살았었다. 재미있었어. 진짜!', `MaleText_loc4`='我在厄运之槌里住过一段时间，真令人难忘。真的。', `MaleText_loc5`='我在厄運之槌裡住過一段時間，那真的很有趣。真的。', `MaleText_loc7`='Viví en La Masacre durante un tiempo. Fue divertido. Mucho.' WHERE `ID`=10044;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 다른 오우거들이랑은 달라. 화장실이 뭔지 아니까. 갔다 나오면 빙글빙글 어지러워 지는 거지. 이제 꺼져.', `MaleText_loc4`='和大多数的食人魔不一样的是，我知道厕所是干什么用的。', `MaleText_loc5`='跟大部分的巨魔不同的是，我了解流動廁所是做什麼的。', `MaleText_loc7`='Al contrario de muchos ogros, yo sí sé para lo que sirve una letrina exterior, para darte una paliza. Y ahora, déjalo.' WHERE `ID`=10045;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 자네가 날 찾고 있다는 사실을 오래전부터 알고 있었네.$B$B이 아제로스 세계에 지각이 있는 모든 존재는 자신의 결정과 선택에 따라 살아가지. 선택이 또 다른 선택을 낳고, 결국 이러한 선택의 연속으로 자신의 존재가 형성된다네. 결국 자네가 내리는 선택에 따라 자네가 누구인지, 자네의 운명도 결정되는 법이지.$B$B자신의 운명을 발견할 준비가 되었나?', `MaleText_loc4`='我早知道你会找到我的，$n。$B$B世间众生都被他们所做出的选择驱动着。一个选择导致另一个选择，最终这些选择决定了你的一切。而这一切——如你的身份，及你所做的选择，也勾勒出了你的命运。$B$B你准备好直面自己的命运了吗？', `MaleText_loc5`='我知道你會找到我的，$n。$B$B這個世界上的每一個有智力的生物都被他們所做出的選擇驅動著。一個選擇導致另一個選擇，最終這些選擇決定了你的一切，也決定了你的宿命 - 你是誰，作了什麼選擇。$B$B你準備好要發現你的命運在哪裡了嗎?', `MaleText_loc7`='Sabía desde hace mucho tiempo que vendrías a buscarme, $n.$B$BTodos los seres sensibles del mundo dependen en gran medida de las decisiones que toman. Las decisiones conllevan más decisiones y, estas, nos convierten en lo que somos. Ahí yace tu fortuna, quién eres y las decisiones que tomas.$B$B¿$gListo:Lista; para descubrir dónde yace tu fortuna?' WHERE `ID`=10046;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 운명을 발견할 준비가 됐습니다!', `MaleText_loc4`='快告诉我吧！', `MaleText_loc5`='我已經準備好要知道我的命運了!', `MaleText_loc7`='¡Sí, quiero descubrir dónde yace mi fortuna!', `FemaleText_loc1`='제 운명을 발견할 준비가 됐습니다!', `FemaleText_loc4`='快告诉我吧！', `FemaleText_loc5`='我已經準備好要知道我的命運了!', `FemaleText_loc7`='¡Sí, quiero descubrir dónde yace mi fortuna!' WHERE `ID`=10047;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아...$B$B자네가 모시는 주군한테서 밀렵꾼과 도적으로부터 옥수수밭을 지키라는 임무를 받았다고 침세. 어느 날 밤 밭에서 순찰하다가 누더기를 걸친 수척한 사내가 옥수수를 훔치는 것을 발견했지. 그자는 자네에게 금방 붙잡혔고 곧바로 목숨을 구걸하기 시작했네. 그러면서 옥수수를 훔친 이유는 가족을 먹여 살리기 위해서라고 주장했다네. 그 땅의 영주, 그러니까 자네 주군이 세금을 너무 많이 거둬 갔기 때문에 먹을 것이 없었던 게지. 실제로 자네 주군은 과중한 세금을 징수하는 것으로 유명했다네.$B$B자, 자네라면 이 사내를 어떻게 할 텐가?', `MaleText_loc4`='好吧……$B$B假设你从你的主人那里接受了保护玉米田并清除小偷的任务。一天晚上，在你巡逻的时候发现了一个穿着破烂布衣的人正在田里偷窃玉米。你马上上前，而他立即跪在你的面前求你不要杀他。他说他偷玉米是为了养活他一家，因为这块土地的主人——也就是你的主人向他们征收重税。你的主人一向以此而闻名。$B$B你该怎么办？', `MaleText_loc5`='很好，那就開始吧...$b$b你的領主要你去看守他的玉米田，以免盜賊跟小偷潛入。某天晚上巡邏時，你碰巧發現一個衣衫破爛、面容憔悴的人正在田裡偷取玉米。你很快的捉住他，但他乞求你饒了他的小命。他聲稱他之所以偷拿玉米是為了給他的家人吃的，因為地主－也就是你的領主－要求太多的稅收了。你的領主確實也因為他那高昂的稅收而遠近馳名。$B$B做出你的選擇吧。', `MaleText_loc7`='Pues muy bien...$B$BTu señor te ha encargado la tarea de proteger sus campos de maíz de cazadores furtivos y ladrones. Una noche de patrulla, te encuentras con un hombre demacrado con una túnica raída que está robando en el campo. Rápidamente, le confrontas y él te suplica que le perdones la vida. Dice que está robando maíz para alimentar a su familia porque el señor de la tierra, tu señor, exige demasiados tributos. De hecho, tu señor es conocido por su dureza a la hora de imponer tributos en sus tierras.$B$BToma tu decisión.' WHERE `ID`=10048;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그자는 도적에 거짓말쟁이일 뿐이므로 주군의 뜻대로 즉석에서 처형하겠습니다.', `MaleText_loc4`='我按照命令把他杀掉，反正他不过是个小偷和骗子而已。', `MaleText_loc5`='我會當場殺了他，因為我的主人一定會要我這麼做，反正他不過是個小偷跟騙子。', `MaleText_loc7`='Mato al hombre inmediatamente como mi señor habría esperado. No es más que un ladrón y un mentiroso.', `FemaleText_loc1`='그자는 도적에 거짓말쟁이일 뿐이므로 주군의 뜻대로 즉석에서 처형하겠습니다.', `FemaleText_loc4`='我按照命令把他杀掉，反正他不过是个小偷和骗子而已。', `FemaleText_loc5`='我會當場殺了他，因為我的主人一定會要我這麼做，反正他不過是個小偷跟騙子。', `FemaleText_loc7`='Mato al hombre inmediatamente como mi señor habría esperado. No es más que un ladrón y un mentiroso.' WHERE `ID`=10049;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그자는 법을 어겼고 저는 법을 집행하겠다고 맹세했기 때문에 주군에게 끌고 가 처벌받게 하겠습니다.', `MaleText_loc4`='我将这个人交给王上来处理，因为他破坏了这里的法律，而我的职责就是把他抓住。', `MaleText_loc5`='我會把他交給我的主人發落，因為他已經違反了這個地方的法律，而我的職責就是執行這個法律。', `MaleText_loc7`='Llevo al hombre ante mi señor para que le castigue, porque ha roto las leyes que yo he jurado hacer respetar.', `FemaleText_loc1`='그자는 법을 어겼고 저는 법을 집행하겠다고 맹세했기 때문에 주군에게 끌고 가 처벌받게 하겠습니다.', `FemaleText_loc4`='我将这个人交给王上来处理，因为他破坏了这里的法律，而我的职责就是把他抓住。', `FemaleText_loc5`='我會把他交給我的主人發落，因為他已經違反了這個地方的法律，而我的職責就是執行這個法律。', `FemaleText_loc7`='Llevo al hombre ante mi señor para que le castigue, porque ha roto las leyes que yo he jurado hacer respetar.' WHERE `ID`=10050;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그자가 훔친 옥수수를 몰수하고 절도는 저주와 파멸에 이르는 길이라는 경고를 한 후 훈방 조치로 가족에게 돌려보내겠습니다.', `MaleText_loc4`='我没收他偷到的玉米，并警告他盗窃是通往毁灭和死亡的道路，但是我会放他走。', `MaleText_loc5`='我會把他偷走的玉米拿回來，警告他偷竊是通往末日跟毀滅的道路，但是我會放他回去跟家人團聚。', `MaleText_loc7`='Confisco el maíz que ha robado, le digo que robar es el camino hacia la perdición y la destrucción y le dejo volver con su familia.', `FemaleText_loc1`='그자가 훔친 옥수수를 몰수하고 절도는 저주와 파멸에 이르는 길이라는 경고를 한 후 훈방 조치로 가족에게 돌려보내겠습니다.', `FemaleText_loc4`='我没收他偷到的玉米，并警告他盗窃是通往毁灭和死亡的道路，但是我会放他走。', `FemaleText_loc5`='我會把他偷走的玉米拿回來，警告他偷竊是通往末日跟毀滅的道路，但是我會放他回去跟家人團聚。', `FemaleText_loc7`='Confisco el maíz que ha robado, le digo que robar es el camino hacia la perdición y la destrucción y le dejo volver con su familia.' WHERE `ID`=10051;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그자의 가족이 며칠 동안 먹을 수 있을 만큼의 옥수수를 주면서 차라리 이 땅을 떠나라고 권고하겠습니다.', `MaleText_loc4`='我允许他拿走足够供他一家人糊口数日的粮食，并建议他赶快离开。', `MaleText_loc5`='我會讓他拿取足夠供他一家人糊口數日的玉米，並鼓勵他離開這個地方。', `MaleText_loc7`='Permito que el hombre coja el suficiente maíz como para alimentar a su familia durante un par de días y le animo a que se vayan todos de ahí.', `FemaleText_loc1`='그자의 가족이 며칠 동안 먹을 수 있을 만큼의 옥수수를 주면서 차라리 이 땅을 떠나라고 권고하겠습니다.', `FemaleText_loc4`='我允许他拿走足够供他一家人糊口数日的粮食，并建议他赶快离开。', `FemaleText_loc5`='我會讓他拿取足夠供他一家人糊口數日的玉米，並鼓勵他離開這個地方。', `FemaleText_loc7`='Permito que el hombre coja el suficiente maíz como para alimentar a su familia durante un par de días y le animo a que se vayan todos de ahí.' WHERE `ID`=10052;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음 선택일세.$B$B자네는 주군에게 충성을 맹세한 사형집행인일세. 어느 날 자네 앞으로 주군과 영지 주민을 배반한 죄목으로 사형 선고를 받은 자가 끌려 왔네. 그런데 자세히 보니 과거에 홀연히 실종되었던 절친한 친구가 아닌가?! 자네가 알기에는 고귀한 성품의 소유자이지만 그 친구가 유죄가 맞는다면 무고한 주민을 수없이 학살한 장본인이라네. 그자가 자네를 알아보자 목숨만 살려 달라고 애원하면서 자신은 권력자의 모함에 빠진 것이라고 주장하네.$B$B자, 자네는 어떤 선택을 내릴 텐가?', `MaleText_loc4`='你的下一个选择在等着你。$B$B你是一个效忠于主人的刽子手。有一个背叛了你的主人和人民的人被送到你这里来受刑。可你以前认识他，他曾是你非常要好的朋友，并且非常善良，但是有一天他突然消失了。你还知道他所犯下的罪行导致很多无辜的平民的死亡。当你看到他的时候，他求你饶命，并且说他是被一个高官所陷害的。$B$B你该怎么办？', `MaleText_loc5`='請回答下個問題: $B$B你是對國王忠心耿耿的行刑者。有一個男人因為背叛了國王跟你的同胞而被送來給你。這個人其實是你一個很親密、很正直的朋友，但是有一天忽然神秘失蹤了。你也知道他被指控的罪行害死了很多無辜的平民百姓。當他看到你的時候，他乞求你饒了他的命，並聲稱他是被別的有權有勢的人所陷害的。$B$B做出你的選擇吧。', `MaleText_loc7`='Te espera tu próxima decisión.$B$BEres el verdugo de tu señor. Te han enviado a un hombre para que le ejecutes por traicionar a tu señor y a tu pueblo. Conoces a este individuo. Era un buen amigo tuyo que, misteriosamente, desapareció un día. También sabes que los crímenes por los que ha sido juzgado han causado la muerte de muchos ciudadanos inocentes. Cuando te ve, te suplica que le perdones la vida y dice que una gran autoridad le tendió una trampa para incriminarle.$B$BToma tu decisión.' WHERE `ID`=10053;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='꺼져라! 이 무례한 오합지졸들아! 알터랙 계곡은 얼라이언스의 땅이다!', `FemaleText_loc4`='去死吧，渣滓！联盟会获得胜利的！', `FemaleText_loc5`='去死吧，沒水準的廢物!聯盟會在奧特蘭克山谷獲得勝利的!', `FemaleText_loc7`='¡Largo, escoria apestosa! ¡La Alianza reinará en el Valle de Alterac!' WHERE `ID`=10054;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽어라! 이 알터랙 계곡에 너희 종족이 발붙일 자리는 없다!', `MaleText_loc4`='去死吧！你们别想在奥特兰克山谷站住脚！', `MaleText_loc5`='死吧!你們在奧特蘭克山谷是沒有立足之地的!', `MaleText_loc7`='¡Muere! ¡No hay lugar para los tuyos en el Valle de Alterac!' WHERE `ID`=10055;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='기운을 내라, 얼라이언스여! 저 악당들을 알터랙 계곡에서 몰아내자!', `FemaleText_loc4`='把这些渣滓赶出奥特兰克！', `FemaleText_loc5`='振作起來，聯盟軍隊!把這些惡棍趕出奧特蘭克山谷!', `FemaleText_loc7`='¡Ánimo, Alianza! ¡Acabad con esos villanos del Valle de Alterac!' WHERE `ID`=10056;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 지금이 공격할 때다! 호드를 위하여!', `MaleText_loc4`='准备发动攻击！为部落而战！', `MaleText_loc5`='準備發動攻擊!為部落而戰!', `MaleText_loc7`='¡Es hora de atacar! ¡Por la Horda!' WHERE `ID`=10057;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 작업 중인 거 안 보이십니까?', `MaleText_loc4`='你没看到我这儿正忙着呢！', `MaleText_loc5`='你沒看到我正在忙嗎?', `MaleText_loc7`='¿No ves que tengo trabajo que hacer?', `FemaleText_loc1`='지금 작업 중인 거 안 보이세요?', `FemaleText_loc4`='你没看到我这儿正忙着呢！', `FemaleText_loc5`='你沒看到我正在忙嗎?', `FemaleText_loc7`='¿No ves que tengo trabajo que hacer?' WHERE `ID`=10058;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곧 축제가 벌어질 겁니다!', `MaleText_loc4`='狂欢开始啦！', `MaleText_loc5`='馬戲團快開始了!', `MaleText_loc7`='¡La feria va a llegar muy pronto!', `FemaleText_loc1`='곧 축제가 벌어질 겁니다!', `FemaleText_loc4`='狂欢开始啦！', `FemaleText_loc5`='馬戲團快開始了!', `FemaleText_loc7`='¡La feria va a llegar muy pronto!' WHERE `ID`=10059;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 여기서 다크문 축제가 열릴 겁니다. 저희가 짐을 다 풀고, 천막을 치고, 동물원을 세우고, 먹고 마실 걸 모두 준비하는 즉시 말이죠. 나중에 꼭 한번 다시 들르세요!', `MaleText_loc4`='没错！暗月马戏团很快就要来了！只要我把这些东西从车上卸下来，搭好帐篷弄好场地，就马上开工！别忘了届时过来看看哦！', `MaleText_loc5`='沒錯，朋友!暗月馬戲團就快要來了。只要我把這些巨大的貨車上的東西都卸下來，架設好所有的帳篷，弄好場地，並把飲料都倒好就可以了。別忘了屆時過來看看哦!', `MaleText_loc7`='¡Así es! La Feria de la Luna Negra va a estar justo aquí. En cuanto descargue esos enormes vagones, monte todas las tiendas, levante el zoo y prepare las bebidas. ¡Asegúrate de volver!', `FemaleText_loc1`='바로 여기서 다크문 축제가 열릴 겁니다. 저희가 짐을 다 풀고, 천막을 치고, 동물원을 세우고, 먹고 마실 걸 모두 준비하는 즉시 말이죠. 나중에 꼭 한번 다시 들르세요!', `FemaleText_loc4`='没错！暗月马戏团很快就要来了！只要我把这些东西从车上卸下来，搭好帐篷弄好场地，就马上开工！别忘了届时过来看看哦！', `FemaleText_loc5`='沒錯，朋友!暗月馬戲團就快要來了。只要我把這些巨大的貨車上的東西都卸下來，架設好所有的帳篷，弄好場地，並把飲料都倒好就可以了。別忘了屆時過來看看哦!', `FemaleText_loc7`='¡Así es! La Feria de la Luna Negra va a estar justo aquí. En cuanto descargue esos enormes vagones, monte todas las tiendas, levante el zoo y prepare las bebidas. ¡Asegúrate de volver!' WHERE `ID`=10060;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다크문 축제가 곧 열립니다. 나중에 다시 한번 들러 보세요.', `MaleText_loc4`='暗月马戏团不久就会开张啦。别忘了待会回来，看看我们是否已准备停当。', `MaleText_loc5`='距離暗月馬戲團開始的時間不會太久了。過一陣子再回來看看我們是否準備好了吧。', `MaleText_loc7`='La Feria de la Luna Negra abrirá pronto. Ven un poco más tarde a ver si ya estamos listos.', `FemaleText_loc1`='다크문 축제가 곧 열립니다. 나중에 다시 한번 들러 보세요.', `FemaleText_loc4`='暗月马戏团不久就会开张啦。别忘了待会回来，看看我们是否已准备停当。', `FemaleText_loc5`='暗月馬戲團開始的時間就快到了。過一陣子再回來看看我們是否準備好了吧。', `FemaleText_loc7`='La Feria de la Luna Negra abrirá pronto. Ven un poco más tarde a ver si ya estamos listos.' WHERE `ID`=10061;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='축제에 오신 것을 환영합니다! 저희는 전 세계의 진귀한 물건들을 모아서 전시하고 있습니다. 혹시 일반 다크문 카드 한 벌을 모으거든 알려주십시오. 주인님이... 아니, 제가 그 카드에 상당히 관심이 많아서 말입니다.', `MaleText_loc4`='年轻人，欢迎来到暗月马戏团！我们从世界各地收集到不少神奇的东西，你可以随便看。啊，如果你能设法收集一套次级暗月卡片，就赶紧告诉我，因为主人……我是说我对这东西很感兴趣。', `MaleText_loc5`='年輕人，歡迎來到暗月馬戲團!我們從世界各地搜集了各種奇珍異寶任你參觀選購。喔，如果你集滿了整套的小暗月卡，請讓我知道，因為我的主人...我是說我會對它們有非常非常大的興趣的。', `MaleText_loc7`='¡Te doy la bienvenida a la feria, joven! Tenemos maravillas de todos los confines del mundo para ti. ¡Ah! Y avísame si consigues reunir una baraja de cartas menores de la Luna Negra; al maestro, quiero decir, a mí me interesaría mucho...' WHERE `ID`=10062;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다크문 카드에 대해 더 자세히 얘기해 주십시오.', `MaleText_loc4`='告诉我更多关于暗月卡片的信息。', `MaleText_loc5`='告訴我更多關於暗月卡片的事情。', `MaleText_loc7`='Cuéntame más sobre esas cartas de la Luna Negra.', `FemaleText_loc1`='다크문 카드에 대해 더 자세히 얘기해 주십시오.', `FemaleText_loc4`='告诉我更多关于暗月卡片的信息。', `FemaleText_loc5`='告訴我更多關於暗月卡片的事情。', `FemaleText_loc7`='Cuéntame más sobre esas cartas de la Luna Negra.' WHERE `ID`=10064;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 아제로스의 실력 있는 자들이 8가지 카드 종류 중 어느 한 벌을 완성할 수 있는지 시험해 보려고 전 세계에 다크문 카드를 뿌려 놓았습니다. 한 종류의 카드 8장을 모두 모으면 상급 다크문 카드 중 한 장을 보상으로 받게 될 겁니다. 이 카드는 강력한 장신구이자 다크문 축제로 연결해 주는 장치지요.', `MaleText_loc4`='我们在世界各地散发暗月卡片，看看有没有谁能集齐八套暗月卡片中的任何一套。若你设法集齐一套八张的卡片，我们就会奖励你一张强力暗月卡片，它不仅是强大的饰品，也可以作为暗月马戏团的纪念。', `MaleText_loc5`='我們在世界各地散發暗月卡片，看看有沒有任何本領高強的人能集齊八套暗月卡片中的任何一套。若你成功集齊八張一套的卡片，我們就會獎勵你一張高級暗月卡，不但可拿來作為力量強大的飾品，也可當作暗月馬戲團的紀念。', `MaleText_loc7`='Hemos esparcido cartas de la Luna Negra por todo el mundo, para ver si algún individuo capaz podría completar uno de los ocho palos. Si consigues reunir las ocho cartas de uno de los palos, te recompensaremos con una de las cartas superiores de la Luna Negra, que funciona como un poderoso abalorio, además de ser un vínculo a la Feria de la Luna Negra.' WHERE `ID`=10065;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐 좀 더 드실래요?', `MaleText_loc4`='您还想吃点什么吗？', `MaleText_loc5`='你還想要吃點什麼嗎?', `MaleText_loc7`='¿Quiere algo más de comer, señor?' WHERE `ID`=10066;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야수 카드에 대해 얘기해 주십시오.', `MaleText_loc4`='告诉我更多关于野兽套牌的信息。', `MaleText_loc5`='告訴我關於野獸套卡的事情。', `MaleText_loc7`='Háblame sobre la baraja de Bestias.', `FemaleText_loc1`='야수 카드에 대해 얘기해 주십시오.', `FemaleText_loc4`='告诉我更多关于野兽套牌的信息。', `FemaleText_loc5`='告訴我關於野獸套卡的事情。', `FemaleText_loc7`='Háblame sobre la baraja de Bestias.' WHERE `ID`=10067;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야수 카드를 모아 한 벌이 되면 푸른용의 상급 다크문 카드를 보상으로 받게 될 겁니다. 이 카드는 마법의 힘을 회복하는 데 아주 유용하지요.', `MaleText_loc4`='如果你集齐一套野兽卡片，我们会奖励你一张高级暗月卡片：蓝龙。这张卡片对恢复魔法能量非常有用。', `MaleText_loc5`='如果你集齊整套的野獸套卡，你將可以得到一張高級暗月卡:藍龍作為獎勵。這張卡片對於恢復魔法能量非常有用。', `MaleText_loc7`='Si consigues completar una baraja de Bestias, te recompensaremos con un naipe superior de la Luna Negra del Dragón Azul. Es muy útil para restaurar energías mágicas.' WHERE `ID`=10068;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='차원문 카드에 대해 얘기해 주십시오.', `MaleText_loc4`='告诉我更多关于入口套牌的信息。', `MaleText_loc5`='告訴我關於傳送門套卡的事情。', `MaleText_loc7`='Háblame sobre la baraja de Portales.', `FemaleText_loc1`='차원문 카드에 대해 얘기해 주십시오.', `FemaleText_loc4`='告诉我更多关于入口套牌的信息。', `FemaleText_loc5`='告訴我關於傳送門套卡的事情。', `FemaleText_loc7`='Háblame sobre la baraja de Portales.' WHERE `ID`=10069;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='차원문 카드를 모아 한 벌이 되면 뒤틀린 황천의 상급 다크문 카드를 보상으로 받게 될 겁니다. 이 카드는 간혹 당신이 죽었을 경우 당신의 영혼을 바로 부활시켜 주기도 한답니다.', `MaleText_loc4`='如果你集齐一套入口卡片的话，你将获得一张暗月卡片：虚空。这张卡片将有可能在你死亡之后让你复活。', `MaleText_loc5`='如果你集齊整套的傳送門套卡，你將可以得到一張高級暗月卡:虛空作為獎勵。這張卡會偶發性的在你死後將你的靈魂拖回你的身體並讓你復活。', `MaleText_loc7`='Si consigues completar una baraja de Portales, te recompensaremos con un naipe superior de la Luna Negra de El Vacío Abisal. Este naipe puede volver a meter tu espíritu en tu cuerpo cuando hayas muerto y restaurar tu salud.' WHERE `ID`=10070;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정령 카드에 대해 얘기해 주십시오.', `MaleText_loc4`='告诉我更多关于元素套牌的信息。', `MaleText_loc5`='告訴我關於元素套卡的事情。', `MaleText_loc7`='Háblame sobre la baraja de Elementales.', `FemaleText_loc1`='정령 카드에 대해 얘기해 주십시오.', `FemaleText_loc4`='告诉我更多关于元素套牌的信息。', `FemaleText_loc5`='告訴我關於元素套卡的事情。', `FemaleText_loc7`='Háblame sobre la baraja de Elementales.' WHERE `ID`=10071;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정령 카드를 모아 한 벌이 되면 혼돈의 소용돌이의 상급 다크문 카드를 보상으로 받게 될 겁니다. 이 카드는 간혹 당신이 맞서 싸우고 있는 적에게 커다란 피해를 주기도 한답니다.', `MaleText_loc4`='如果你集齐一套元素卡片，我们会奖励你一张高级暗月卡片：漩涡。这张卡片可能会对你的敌人造成严重的伤害。', `MaleText_loc5`='如果你集齊整套的元素套卡，你將可以得到一張高級暗月卡:漩渦作為獎勵。這張卡片會偶發性的對正在跟你戰鬥的敵人給予嚴重的傷害。', `MaleText_loc7`='Si consigues completar una baraja de Elementales, te recompensaremos con un naipe superior de la Luna Negra de La Vorágine. Este naipe puede causar un gran daño a un enemigo con quien estés luchando.' WHERE `ID`=10072;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대장군 카드에 대해 얘기해 주십시오.', `MaleText_loc4`='告诉我更多关于督军套牌的信息。', `MaleText_loc5`='告訴我關於督軍套卡的事情。', `MaleText_loc7`='Háblame sobre la baraja de Señores de la Guerra.', `FemaleText_loc1`='대장군 카드에 대해 얘기해 주십시오.', `FemaleText_loc4`='告诉我更多关于督军套牌的信息。', `FemaleText_loc5`='告訴我關於督軍套卡的事情。', `FemaleText_loc7`='Háblame sobre la baraja de Señores de la Guerra.' WHERE `ID`=10073;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대장군 카드를 모아 한 벌이 되면 영웅심의 상급 다크문 카드를 보상으로 받게 될 겁니다. 이 카드는 간혹 당신이 근접전을 펼칠 때 치유를 해 주기도 하지요.', `MaleText_loc4`='如果你集齐一套督军卡片的话，你将获得一张暗月卡片：英雄。这张卡片将有可能在你进行近身作战的时候对你进行治疗。', `MaleText_loc5`='如果你集齊整套的督軍套卡，你將可以得到一張高級暗月卡:英雄作為獎勵。這張卡會偶發性的在你進行近身戰鬥時治療你。', `MaleText_loc7`='Si consigues completar una baraja de Señores de la Guerra, te recompensaremos con un naipe superior de la Luna Negra del Heroísmo. Este naipe puede sanarte cuando estés en combate cuerpo a cuerpo.' WHERE `ID`=10074;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주군의 명령에 따라 그자를 처형하겠습니다. 그뿐만 아니라, 백성에게 못된 짓을 한 대가로 아주 고통스럽게 처형하겠습니다.', `MaleText_loc4`='我按照王上的命令处决他，这样才能偿还他对我的同胞犯下的罪孽。', `MaleText_loc5`='我會按照主人的命令處決他，而且用的是足以讓他在死前受盡折磨的方式，這樣才能償還他對我的同胞犯下的罪孽。', `MaleText_loc7`='Lo ejecuto, eso es lo que me ha ordenado mi señor, y lo hago de tal forma que sufre mucho antes de morir castigado por los crímenes que cometió contra mi pueblo.', `FemaleText_loc1`='주군의 명령에 따라 그자를 처형하겠습니다. 그뿐만 아니라, 백성에게 못된 짓을 한 대가로 아주 고통스럽게 처형하겠습니다.', `FemaleText_loc4`='我按照王上的命令处决他，这样才能偿还他对我的同胞犯下的罪孽。', `FemaleText_loc5`='我會按照主人的命令處決他，而且用的是足以讓他在死前受盡折磨的方式，這樣才能償還他對我的同胞犯下的罪孽。', `FemaleText_loc7`='Lo ejecuto, eso es lo que me ha ordenado mi señor, y lo hago de tal forma que sufre mucho antes de morir castigado por los crímenes que cometió contra mi pueblo.' WHERE `ID`=10075;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주군의 명령에 따라 그자를 처형하겠지만 최대한 고통 없이 죽이겠습니다. 정의는 실현되어야 하지만 약간의 동정도 베풀 수 있다고 생각합니다.', `MaleText_loc4`='我按照王上的命令处决他，但是我尽可能地让他少受痛苦。正义必须得到伸张，但我们也要心怀怜悯。', `MaleText_loc5`='我會按照主人的命令處決他，但是盡可能地讓他少受痛苦。正義必須得到伸張，但我可以心懷憐憫。', `MaleText_loc7`='Lo ejecuto, eso es lo que me ha ordenado mi señor, pero lo hago de forma que sufra lo menos posible. Hay que hacer cumplir la justicia, pero también puedo mostrar compasión.', `FemaleText_loc1`='주군의 명령에 따라 그자를 처형하겠지만 최대한 고통 없이 죽이겠습니다. 정의는 실현되어야 하지만 약간의 동정도 베풀 수 있다고 생각합니다.', `FemaleText_loc4`='我按照王上的命令处决他，但是我尽可能地让他少受痛苦。正义必须得到伸张，但我们也要心怀怜悯。', `FemaleText_loc5`='我會按照主人的命令處決他，但是盡可能地讓他少受痛苦。正義必須得到伸張，但我可以心懷憐憫。', `FemaleText_loc7`='Lo ejecuto, eso es lo que me ha ordenado mi señor, pero lo hago de forma que sufra lo menos posible. Hay que hacer cumplir la justicia, pero también puedo mostrar compasión.' WHERE `ID`=10076;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 친구가 자신의 무죄를 입증할 수 있도록 제 목숨을 걸고 그를 풀어 주겠습니다. 그리고 가능하면 그를 어떻게든 돕겠습니다.', `MaleText_loc4`='我愿意以自己生命的代价来拯救他，然后他就可以证明自己的清白。如果可以的话，我会不惜一切代价来帮助他。', `MaleText_loc5`='我會冒著我的生命危險釋放他，這樣他才可以證明他的清白。如果可以，我會用各種方式來幫助他。', `MaleText_loc7`='Arriesgo mi propia vida y le libero para que pueda demostrar su inocencia. Si puedo, le ayudaré en lo que sea.', `FemaleText_loc1`='그 친구가 자신의 무죄를 입증할 수 있도록 제 목숨을 걸고 그를 풀어 주겠습니다. 그리고 가능하면 그를 어떻게든 돕겠습니다.', `FemaleText_loc4`='我愿意以自己生命的代价来拯救他，然后他就可以证明自己的清白。如果可以的话，我会不惜一切代价来帮助他。', `FemaleText_loc5`='我會冒著我的生命危險釋放他，這樣他才可以證明他的清白。如果可以，我會用各種方式來幫助他。', `FemaleText_loc7`='Arriesgo mi propia vida y le libero para que pueda demostrar su inocencia. Si puedo, le ayudaré en lo que sea.' WHERE `ID`=10077;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음 선택일세.$B$B자네는 주군을 대신하여 난폭한 적국에서 외교 임무를 수행하는 중일세. 모두 전쟁 때문에 큰 피해를 입고 있는 상태라서 자네는 양국의 체면을 모두 살리면서 평화 협정을 체결하라는 임무를 받았지.$B$B외교 만찬을 들던 중 자네의 귀에 적국의 지도자가 인자한 주군을 지독히도 모욕하는 소리가 들려왔네. 물론 그 지도자는 자네에게는 들리지 않을 거라고 믿고 말한 것이 분명하지만 어쨌든 주군의 명예를 더럽힌 것일세.$B$B자, 자네의 선택을 말해 보게.', `MaleText_loc4`='你的下一个选择在等着你。$B$B你奉王上之命，出使交战中的敌国。战争让双方都元气大伤，你的使命是确保两国进行和平谈判。$B$B在外交宴会上，你无意中听到敌国的统治者恶意中伤你的君王。你断定他原本是想背着你说的，但他还是辱及了你的王上的威名。$B$B做个选择吧。', `MaleText_loc5`='請回答下個問題: $B$B你奉了國王之命，出使交戰中的敵國。戰爭讓雙方都元氣大傷，你的使命是確保兩國人民都能獲得互惠互利的和平。$B$B然而在外交宴會上，你無意中聽到敵國統治者惡意中傷你的國王。你斷定他原本是想背著你說的，但他終究還是辱及了你國王的威名。$B$B做出你的選擇吧。', `MaleText_loc7`='Te espera tu próxima decisión.$B$BEstás en una misión diplomática para tu señor, en un país cruel que está en guerra con el tuyo. La guerra ha sido muy penosa para ambas partes. Tu misión es asegurar una paz honrosa para ambos países.$B$BEn una cena diplomática, escuchas al gobernador de la tierra enemiga insultar malintencionadamente a tu benevolente señor. Sabes con bastante seguridad que el gobernador no pretendía que tú lo escuchases, pero, de todas formas, ha deshonrado a tu señor.$B$BToma tu decisión.' WHERE `ID`=10078;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앞으로의 외교를 모두 희생할 위험을 감수하고서라도 주군의 명예를 지키기 위해 그 악의적인 행동에 대해 따지겠습니다.', `MaleText_loc4`='我挑战他的邪恶与蛮横，不惜一切代价捍卫王上的荣耀。', `MaleText_loc5`='我會挑戰對方統治者的邪惡與蠻橫，不管未來外交要擔負的風險去捍衛我的主人的榮耀。', `MaleText_loc7`='Me encaro con el gobernador por su comportamiento, defendiendo el honor de mi señor incluso arriesgando cualquier tipo de negociación diplomática.', `FemaleText_loc1`='앞으로의 외교를 모두 희생할 위험을 감수하고서라도 주군의 명예를 지키기 위해 그 악의적인 행동에 대해 따지겠습니다.', `FemaleText_loc4`='我挑战他的邪恶与蛮横，不惜一切代价捍卫王上的荣耀。', `FemaleText_loc5`='我會挑戰對方統治者的邪惡與蠻橫，不管未來外交要擔負的風險去捍衛我的主人的榮耀。', `FemaleText_loc7`='Me encaro con el gobernador por su comportamiento, defendiendo el honor de mi señor incluso arriesgando cualquier tipo de negociación diplomática.' WHERE `ID`=10079;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적국 지도자에게 적당한 눈치를 줘서 뜨끔하게 만들고, 나중에 주군에게 돌아와서 그 사실을 고하겠습니다.', `MaleText_loc4`='我平静但略有表示地对这种冒犯一言不发，让他对自己犯下的错心怀恐惧。回去之后，我会把这一切禀报王上。', `MaleText_loc5`='我會略有表示地忽視他所做的侮辱，希望對方統治者對自己犯下的錯心懷恐懼。當我回去之後，我會把這一切稟報我的主人。', `MaleText_loc7`='Ignoro el insulto como puedo esperando que el gobernador se dé cuenta de que le he oído. A continuación, informo a mi señor del insulto cuando vuelvo.', `FemaleText_loc1`='적국 지도자에게 적당한 눈치를 줘서 뜨끔하게 만들고, 나중에 주군에게 돌아와서 그 사실을 고하겠습니다.', `FemaleText_loc4`='我平静但略有表示地对这种冒犯一言不发，让他对自己犯下的错心怀恐惧。回去之后，我会把这一切禀报王上。', `FemaleText_loc5`='我會略有表示地忽視他所做的侮辱，希望對方統治者對自己犯下的錯心懷恐懼。當我回去之後，我會把這一切稟報我的主人。', `FemaleText_loc7`='Ignoro el insulto como puedo esperando que el gobernador se dé cuenta de que le he oído. A continuación, informo a mi señor del insulto cuando vuelvo.' WHERE `ID`=10080;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우연히 듣게 된 모욕의 언사는 못 들은 척 넘기겠습니다. 그리고 주군에게도 그 사실을 말하지 않겠습니다. 어떻게든 평화 협정을 체결하는 것이 제 임무이고, 그건 선전 포고가 아니라 단순한 비방이었을 뿐이니까요.', `MaleText_loc4`='我默不作声，忽略了这种侮辱。我不会告诉我的王上，因为我将不惜一切代价保护和平。这只是一次侮辱——而不是一次完全的宣战。', `MaleText_loc5`='我會沉默的忽略這個侮辱。我不會告訴我的主人，因為我必須不惜一切代價保護和平。這只是一個侮辱─而不是宣戰。', `MaleText_loc7`='Tranquilamente hago caso omiso del insulto. No se lo diré a mi señor, ya que quiero asegurar la paz a toda costa. Es solo un insulto... no una declaración de guerra.', `FemaleText_loc1`='우연히 듣게 된 모욕의 언사는 못 들은 척 넘기겠습니다. 그리고 주군에게도 그 사실을 말하지 않겠습니다. 어떻게든 평화 협정을 체결하는 것이 제 임무이고, 그건 선전 포고가 아니라 단순한 비방이었을 뿐이니까요.', `FemaleText_loc4`='我默不作声，忽略了这种侮辱。我不会告诉我的王上，因为我将不惜一切代价保护和平。这只是一次侮辱——而不是一次完全的宣战。', `FemaleText_loc5`='我會沉默的忽略這個侮辱。我不會告訴我的主人，因為我必須不惜一切代價保護和平。這只是一個侮辱─而不是宣戰。', `FemaleText_loc7`='Tranquilamente hago caso omiso del insulto. No se lo diré a mi señor, ya que quiero asegurar la paz a toda costa. Es solo un insulto... no una declaración de guerra.' WHERE `ID`=10081;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음 선택일세.$B$B자네는 정예 부대의 일원인데 동생이 들어오고 싶어하네. 책임감과 충성심은 나무랄 데 없는 동생이지만 정예 부대의 어려운 임무를 수행할 능력이 있는지는 반신반의일세. 어쩌면 동생의 실수로 인해 부대원 전체가 위험에 처할 수도 있을 법하거든. 어쨌든 동생이 정예 부대에 걸맞은 능력을 갖췄는지는 확실치 않지만, 자네 말 한 마디로 동생의 입대가 결정될 것은 분명하네.$B$B자, 자네의 선택을 말해 보게.', `MaleText_loc4`='你的下一个选择在等着你。$B$B你的兄弟想要加入你所在的享有盛名的军队。虽然你对他的热情和忠诚毫不怀疑，但是你担心他的能力还不足以执行军队艰巨的任务。当你无法肯定定他能否应对挑战——这可能会让你和其他人陷入危机——而你的意见将决定他的去留。$B$B做个选择吧。', `MaleText_loc5`='請回答下個問題: $B$B你所隸屬的軍隊享有盛名，而你弟弟也想要加入。你對他的責任心和忠誠毫不懷疑，但是你擔心他的能力還不足以執行軍隊艱鉅的任務。你無法確定他能否承擔這挑戰，憂心他可能會讓你和其他人陷入危機。但是你知道，你的話將決定他的去留。$B$B做出你的選擇吧。', `MaleText_loc7`='Te aguarda tu siguiente decisión.$B$BTu hermano desea unirse a las filas de la prestigiosa orden militar de la que tú ya formas parte. Aunque no dudas de su compromiso y lealtad, cuestionas su talento y su habilidad para realizar las arduas tareas de la orden. Si bien no sabes con seguridad si podrá estar a la altura del desafío de la orden, poniéndote a ti y a otros en peligro, no cabe duda de que solo tu palabra bastaría para permitirle que ingrese o se quede fuera.$B$BToma tu decisión.' WHERE `ID`=10082;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형제간의 우애가 영원히 깨지는 한이 있더라도 동생의 입대를 반대하겠습니다. 동생은 자기 자신뿐 아니라 부대원 전체를 위험에 빠뜨릴 수 있고, 점차적인 실력 향상을 바라기에는 위험 부담이 너무 큽니다.', `MaleText_loc4`='我会反对我的兄弟加入军队，即使我们的关系会因此产生永久的裂痕。对他自己和周围的人来说，他无疑是个危险，要想指望他会逐渐进步可就太冒险了。', `MaleText_loc5`='我會反對我弟弟加入軍隊，縱使這會對我們的關係造成不可彌補的傷害。他不僅會傷到自己，還會害到周圍的人。而且，光指望他會慢慢學習進步，這實在太冒險了。', `MaleText_loc7`='Votaría en contra de que mi hermano se uniera a la orden, sabiendo que significaría la ruptura absoluta de nuestra relación. Sería un peligro para él y para los que estuviéramos a su alrededor, y esperar que mejore con el tiempo es un riesgo demasiado grande.', `FemaleText_loc1`='남매간의 우애가 영원히 깨지는 한이 있더라도 동생의 입대를 반대하겠습니다. 동생은 자기 자신뿐 아니라 부대원 전체를 위험에 빠뜨릴 수 있고, 점차적인 실력 향상을 바라기에는 위험 부담이 너무 큽니다.', `FemaleText_loc4`='我会反对我的兄弟加入军队，即使我们的关系会因此产生永久的裂痕。对他自己和周围的人来说，他无疑是个危险，要想指望他会逐渐进步可就太冒险了。', `FemaleText_loc5`='我會反對我弟弟加入軍隊，縱使這會對我們的關係造成不可彌補的傷害。他不僅會傷到自己，還會害到周圍的人。而且，光指望他會慢慢學習進步，這實在太冒險了。', `FemaleText_loc7`='Votaría en contra de que mi hermano se uniera a la orden, sabiendo que significaría la ruptura absoluta de nuestra relación. Sería un peligro para él y para los que estuviéramos a su alrededor, y esperar que mejore con el tiempo es un riesgo demasiado grande.' WHERE `ID`=10083;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='설령 부대의 안전에 위협이 되더라도 동생의 입대를 지지하겠습니다. 동생이 충분히 적응하고 발전하리라는 믿음이 있으니까요. 그때까지 제가 직접 도울 수 있을 것입니다.', `MaleText_loc4`='我会支持我的兄弟加入军队，虽然这或许会威胁到军队的安全。我和军队的其他成员会帮助他，我相信他能够适应这儿的生活并且学会生存之道。', `MaleText_loc5`='我會支持我的兄弟加入軍隊，雖然這或許會威脅到軍隊的安全。我和軍隊的其他袍澤會幫助他，我有信心他能夠適應這兒的生活並且學會生存之道。', `MaleText_loc7`='Hablaría en favor de que mi hermano se uniera a la orden, poniendo en peligro la seguridad de la orden. Le ayudaría con el régimen de la orden y tendría fe en su facultad para adaptarse y aprender.', `FemaleText_loc1`='설령 부대의 안전에 위협이 되더라도 동생의 입대를 지지하겠습니다. 동생이 충분히 적응하고 발전하리라는 믿음이 있으니까요. 그때까지 제가 직접 도울 수 있을 것입니다.', `FemaleText_loc4`='我会支持我的兄弟加入军队，虽然这或许会威胁到军队的安全。我和军队的其他成员会帮助他，我相信他能够适应这儿的生活并且学会生存之道。', `FemaleText_loc5`='我會支持我的兄弟加入軍隊，雖然這或許會威脅到軍隊的安全。我和軍隊的其他袍澤會幫助他，我有信心他能夠適應這兒的生活並且學會生存之道。', `FemaleText_loc7`='Hablaría en favor de que mi hermano se uniera a la orden, poniendo en peligro la seguridad de la orden. Le ayudaría con el régimen de la orden y tendría fe en su facultad para adaptarse y aprender.' WHERE `ID`=10084;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동생 모르게 우리 부대에 합류할 수 없도록 하는 방법을 찾아보겠습니다. 형제간의 우애가 깨지지 않도록 동생이 정보를 얻을 수 없는 상태에서 그를 입대자 명단에서 빼버릴 수도 있겠지요.', `MaleText_loc4`='我会想办法让他不参加危险的任务，完全不需要他做任何事情，以此来保存我的家族的血脉。', `MaleText_loc5`='我會偷偷製造一些事情讓我的兄弟無法參加軍隊，我可以讓他不知情的一直無法參加軍隊，以此來保存我的家族的血脈。', `MaleText_loc7`='Me inventaría una forma subrepticia de mantener a mi hermano fuera de la orden. Puedo hacer que se quede fuera sin que sepa que he sido yo. Así, nuestra relación familiar seguiría intacta.', `FemaleText_loc1`='동생 모르게 우리 부대에 합류할 수 없도록 하는 방법을 찾아보겠습니다. 남매간의 우애가 깨지지 않도록 동생이 정보를 얻을 수 없는 상태에서 그를 입대자 명단에서 빼버릴 수도 있겠지요.', `FemaleText_loc4`='我会想办法让他不参加危险的任务，完全不需要他做任何事情，以此来保存我的家族的血脉。', `FemaleText_loc5`='我會偷偷製造一些事情讓我的兄弟無法參加軍隊，我可以讓他不知情的一直無法參加軍隊，以此來保存我的家族的血脈。', `FemaleText_loc7`='Me inventaría una forma subrepticia de mantener a mi hermano fuera de la orden. Puedo hacer que se quede fuera sin que sepa que he sido yo. Así, nuestra relación familiar seguiría intacta.' WHERE `ID`=10085;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음 선택일세.$B$B변두리 지역을 휩쓸고 다니던 끔찍한 괴물을 자네 혼자 물리치고, 그 괴물의 귀를 전리품으로 챙겼네. 그런데 주군이 모르고 나중에서야 그 괴물의 목에 현상금을 걸었고, 자네와 면식이 있는 한 기사가 괴물을 죽였다는 거짓 주장을 한다는 소식을 듣게 되었네. 그 기사는 성품이 온화하지만 집안이 가난하여 가족을 겨우 먹여 살릴 수 있을 정도라네. 솔직히 자네에게 돈은 필요 없지만 그 가난한 기사는 개인적인 이익을 위해 거짓말을 하고 있는 것일세.$B$B자, 자네의 선택을 말해 보게.', `MaleText_loc4`='你的下一个选择在等着你。$B$B你凭借自己的力量杀死了一头破坏农田的可怕野兽，并且割下它的耳朵作为战利品。后来你听说你的王上在悬赏这头野兽的性命，有一位贫穷的骑士为了养家糊口，说是自己杀死了这头野兽。你自己并不需要钱，但是你知道这家伙谎报实情，牟取私利。$B$B做个选择吧。', `MaleText_loc5`='請回答下個問題: $B$B你憑藉自己的力量殺死了一頭在鄉間肆虐破壞的可怕野獸，並且割下它的耳朵作為戰利品。後來你聽說國王在懸賞殺死這頭野獸，但是你所認識的一位仁慈但貧窮的騎士卻說是他殺死了這頭野獸，想要領取賞金養家糊口。你自己並不需要錢，但是你知道這傢伙謊報實情，牟取私利。$B$B做出你的選擇吧。', `MaleText_loc7`='Te espera tu próxima decisión.$B$BHas vencido a una bestia terrible que estaba arrasando el país y le has cortado la oreja como trofeo. Más tarde, te enteras de que tu señor ha ofrecido una recompensa por la muerte de la bestia y que un noble caballero que se ha quedado en la indigencia, y de quien sabes que está sufriendo para mantener a su familia, ha dicho haber matado a la bestia. En realidad no necesitas el dinero, pero sabes que el caballero está mintiendo.$B$BToma tu decisión.' WHERE `ID`=10086;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주군에게 괴물의 귀를 보여 주며 제가 괴물을 처치했다고 말하고 현상금을 받겠습니다. 거짓말로 남의 업적을 가로채는 것은 그릇된 일입니다.', `MaleText_loc4`='我会将这头野兽的耳朵拿给王上看，以此证明我是凭一己之力杀死它的，并且将所有的奖励收归己用。把别人的事迹宣扬成自己的功劳是不对的。', `MaleText_loc5`='我會把這隻野獸的耳朵拿給我的主人看，並且說這隻野獸是我殺死的，然後把獎品據為己有。把事實上是別人做的事情說成是你自己的功勞是不對的。', `MaleText_loc7`='Le enseñaría a mi señor la oreja de la bestia y diría que fui yo quien la mató, quedándome con la recompensa. No está bien adjudicarse una hazaña cuando sabes que la ha hecho otro.', `FemaleText_loc1`='주군에게 괴물의 귀를 보여 주며 제가 괴물을 처치했다고 말하고 현상금을 받겠습니다. 거짓말로 남의 업적을 가로채는 것은 그릇된 일입니다.', `FemaleText_loc4`='我会将这头野兽的耳朵拿给王上看，以此证明我是凭一己之力杀死它的，并且将所有的奖励收归己用。把别人的事迹宣扬成自己的功劳是不对的。', `FemaleText_loc5`='我會把這隻野獸的耳朵拿給我的主人看，並且說這隻野獸是我殺死的，然後把獎品據為己有。把事實上是別人做的事情說成是你自己的功勞是不對的。', `FemaleText_loc7`='Le enseñaría a mi señor la oreja de la bestia y diría que fui yo quien la mató, quedándome con la recompensa. No está bien adjudicarse una hazaña cuando sabes que la ha hecho otro.' WHERE `ID`=10087;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주군에게 괴물의 귀를 보여 주며 제가 괴물을 처치했다고 말하겠습니다. 실제로 제가 죽인 것이니까요. 그러고 나서 현상금의 일부를 가난한 그 기사에게 나누어 주겠습니다.', `MaleText_loc4`='我会将这头野兽的耳朵拿给王上看，以此证明我是凭一己之力杀死它的——毕竟，我确实杀了它。然后我会用一部分奖励接济贫困的骑士，用以养家糊口。', `MaleText_loc5`='我會把這隻野獸的耳朵拿給我的主人看，並且說這隻野獸是我殺死的－畢竟，我確實殺了牠。我會把獎品的一部份分給那個貧困的騎士，好幫助他的家人。', `MaleText_loc7`='Le enseñaría a mi señor la oreja de la bestia y diría que fui yo quien la mató, después de todo, eso es lo cierto. Después ofrecería parte de la recompensa al caballero para ayudar a su familia.', `FemaleText_loc1`='주군에게 괴물의 귀를 보여 주며 제가 괴물을 처치했다고 말하겠습니다. 실제로 제가 죽인 것이니까요. 그러고 나서 현상금의 일부를 가난한 그 기사에게 나누어 주겠습니다.', `FemaleText_loc4`='我会将这头野兽的耳朵拿给王上看，以此证明我是凭一己之力杀死它的——毕竟，我确实杀了它。然后我会用一部分奖励接济贫困的骑士，用以养家糊口。', `FemaleText_loc5`='我會把這隻野獸的耳朵拿給我的主人看，並且說這隻野獸是我殺死的－畢竟，我確實殺了牠。我會把獎品的一部份分給那個貧困的騎士，好幫助他的家人。', `FemaleText_loc7`='Le enseñaría a mi señor la oreja de la bestia y diría que fui yo quien la mató, después de todo, eso es lo cierto. Después ofrecería parte de la recompensa al caballero para ayudar a su familia.' WHERE `ID`=10088;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 괴물을 처치한 사실에 대해서는 침묵하겠습니다. 그 가난한 기사가 제 현상금을 대신 받아 가족을 먹여 살릴 수 있도록 말이죠.', `MaleText_loc4`='我将对这件事情只字不提，并允许那个骑士拿到奖励来帮助他的家庭。', `MaleText_loc5`='我會對這件事情保持沉默，並允許那個騎士領取獎品來救助他的家人。', `MaleText_loc7`='No diría nada sobre la muerte y permitiría que el caballero se quedase con la recompensa.', `FemaleText_loc1`='제가 괴물을 처치한 사실에 대해서는 침묵하겠습니다. 그 가난한 기사가 제 현상금을 대신 받아 가족을 먹여 살릴 수 있도록 말이죠.', `FemaleText_loc4`='我将对这件事情只字不提，并允许那个骑士拿到奖励来帮助他的家庭。', `FemaleText_loc5`='我會對這件事情保持沉默，並允許那個騎士領取獎品來救助他的家人。', `FemaleText_loc7`='No diría nada sobre la muerte y permitiría que el caballero se quedase con la recompensa.' WHERE `ID`=10089;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 자네 운명이 담긴 점괘가 나왔네. 앞으로 몇 시간 동안 자네의 영혼이 진정한 본성에 눈뜬 것을 느낄 수 있을 거야. 하지만 주의하도록. 점괘가 말하는 자네의 운명은 결코 자네 생각처럼 분명한 것이 아니니까.$B$B내가 주는 작은 단서를 통해서라도 자신의 미래에 대해 생각해 볼 필요가 있다면 언제든지 말하게. 가방에 여유가 있다면 내 기꺼이 점괘를 적어 주지. 내 질문에 대답하면서 보여 준 자네의 영감에 따라 정해진 것이지.', `MaleText_loc4`='对你的占卜已经完成，$c。在接下来的几个小时中，你将发现你的精神与你真正的天性保持一致。你要小心，因为你的命运并不是你所想得那么条理清晰。$B$B如果你想要对你的未来有所了解，那么尽管告诉我。我会很乐意给你一张手写的占卜结果，当然，你的背包中必须留有足够的空间。这个结果是你回答我的问题时所表现出来的。', `MaleText_loc5`='你的占卜已經完成了，$c。在接下來的幾個小時中，你將發現你的精神與你真正的天性趨於一致。你要小心，因為你的財富－及你的命運，並不像你所想的那麼條理清晰。$B$B如果你想要對你的未來有所瞭解，那麼儘管告訴我。我會很樂意給你一張手寫的籤詩，你的背包中必須留有足夠的空間。這張籤詩是根據你回答我的問題時的意象所抽出來的。', `MaleText_loc7`='Tu fortuna ha sido decidida, $c. Durante las próximas horas, verás que tu espíritu adopta la naturaleza de tu verdadero ser. Ten cuidado, ya que tu fortuna, al igual que tu destino, nunca es tan transparente como puedes creer.$B$BSi quisieras una pequeña ayuda para vislumbrar algo que tengas que considerar en el futuro, dímelo. Te daré encantado tu fortuna por escrito, siempre que tengas espacio en el inventario. Todo ha sido el resultado de tus respuestas a mis preguntas.' WHERE `ID`=10090;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가방에 여유 공간은 있으니, 말씀하신 점괘를 적어 주시면 감사하겠습니다!', `MaleText_loc4`='我想要你说的这些塔罗牌！我有足够的空间来存放。', `MaleText_loc5`='我很樂意得到一張你所說的手寫籤詩!我的背包裡有足夠的空間。', `MaleText_loc7`='Me encantaría tener mi fortuna por escrito. Tengo espacio en mi inventario.', `FemaleText_loc1`='가방에 여유 공간은 있으니, 말씀하신 점괘를 적어 주시면 감사하겠습니다!', `FemaleText_loc4`='我想要你说的这些塔罗牌！我有足够的空间来存放。', `FemaleText_loc5`='我很樂意得到一張你所說的手寫籤詩!我的背包裡有足夠的空間。', `FemaleText_loc7`='Me encantaría tener mi fortuna por escrito. Tengo espacio en mi inventario.' WHERE `ID`=10091;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 여기 자네의 점괘가 있으니 읽어보게. 현명하게 해석하길!', `MaleText_loc4`='$n，这是你的塔罗牌。愿你能好好利用它。', `MaleText_loc5`='$n，這是你的籤詩。願它能好好幫上你。', `MaleText_loc7`='Aquí tienes tu fortuna, $n. Espero que te ayude.' WHERE `ID`=10092;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곧 마을에서 다크문 축제가 시작됩니다! 놓치지 마십시오!', `MaleText_loc4`='暗月马戏团已经来到本镇了！走过路过不要错过！', `MaleText_loc5`='暗月馬戲團已經到鎮上了!走過路過不要錯過!', `MaleText_loc7`='¡Llega a la ciudad la Feria de la Luna Negra! ¡Que nadie se lo pierda!' WHERE `ID`=10093;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마을에 다크문 축제가 시작되면 그 놀라운 구경거리들을 하나도 놓치지 마십시오!', `MaleText_loc4`='一定要来看看暗月马戏团为你带来的各种千奇百怪的东西！', `MaleText_loc5`='暗月馬戲團來的時候一定要仔細的將所有的奇景都盡收眼底喔!', `MaleText_loc7`='¡Aseguraos de ver todas las maravillas increíbles de la Feria de la Luna Negra cuando llegue a la ciudad!' WHERE `ID`=10094;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다크문 축제가 곧 시작됩니다! 동심을 간직하고 있는 분이라면 모두 즐길 수 있습니다. 모두 오십시오!', `MaleText_loc4`='暗月马戏团来了！所有的孩子都可以在这里找到好玩的东西！来吧，都来吧！', `MaleText_loc5`='暗月馬戲團來了!所有的孩子都可以在這裡找到好玩的東西!來吧，都來吧!', `MaleText_loc7`='¡Llega la Feria de la Luna Negra! ¡Diversión para niños de TODAS las edades! ¡Vamos, vengan todos!' WHERE `ID`=10095;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이리 와서 아제로스 최고의 구경거리인 다크문 축제에 대해 들어 보십시오! 허이짜!', `MaleText_loc4`='快来吧，听说艾泽拉斯最盛大的集会——暗月马戏团开张啦！哈哈！', `MaleText_loc5`='靠過來仔細聆聽整個艾澤拉斯大陸上最盛大的集會－暗月馬戲團!哈哈!', `MaleText_loc7`='Venid todos, ¡el espectáculo más asombroso de todo Azeroth, la Feria de la Luna Negra! ¡Hurra!' WHERE `ID`=10096;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곧 마을에서 다크문 축제가 시작되니 절대 놓치지 마시오!', `MaleText_loc4`='暗月马戏团来了！不要错过啊！', `MaleText_loc5`='暗月馬戲團就要來了!千萬不要錯過!', `MaleText_loc7`='¡Llega a la ciudad la Feria de la Luna Negra! ¡Que nadie se lo pierda!' WHERE `ID`=10097;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다크문 축제가 곧 시작될 거요! 동심을 간직하고 있는 자라면 모두 즐길 수 있지... 모두 다 오시오!', `MaleText_loc4`='暗月马戏团来了！所有的孩子都可以在这里找到好玩的东西！来吧，都来吧！', `MaleText_loc5`='暗月馬戲團快要來了!所有的孩子都可以在這裡得到樂趣!來吧，大家都來吧!', `MaleText_loc7`='¡Llega la Feria de la Luna Negra! ¡Diversión para niños de TODAS las edades! ¡Vamos, vengan todos!' WHERE `ID`=10098;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이리 와서 아제로스 최고의 구경거리, 다크문 축제에 대해 들어 보시오! 허이짜!', `MaleText_loc4`='快来吧，听说艾泽拉斯最盛大的集会——暗月马戏团开张啦！哈哈！', `MaleText_loc5`='靠過來仔細聆聽整個艾澤拉斯大陸上最盛大的集會－暗月馬戲團!哈哈!', `MaleText_loc7`='Venid todos, ¡el espectáculo más asombroso de todo Azeroth, la Feria de la Luna Negra! ¡Hurra!' WHERE `ID`=10099;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마을에 다크문 축제가 시작되면 그 놀라운 구경거리들을 하나도 놓치지 마시오!', `MaleText_loc4`='一定要来看看暗月马戏团带来的千奇百怪的东西！', `MaleText_loc5`='暗月馬戲團到城裡來的時候記得要仔細的將所有的奇景都盡收眼底喔!', `MaleText_loc7`='¡Aseguraos de ver todas las maravillas increíbles de la Feria de la Luna Negra cuando llegue a la ciudad!' WHERE `ID`=10100;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다크문 축제가 시작됐소! 모두 아제로스 전체에서 가장 신나는 쇼를 놓치지 마시오!', `MaleText_loc4`='我们终于来了！暗月马戏团现在开始展出！一定要来看看艾泽拉斯大陆各种千奇百怪的东西！', `MaleText_loc5`='來了!暗月馬戲團正式開始營業!記得來看全艾澤拉斯最刺激的表演!', `MaleText_loc7`='¡Está aquí! ¡La Feria de la Luna Negra está abierta! ¡No os perdáis el espectáculo más excitante de Azeroth!' WHERE `ID`=10101;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마을에 다크문 축제가 열리고 있소! 평생 두 번 다시는 못 볼 짜릿한 구경거리를 절대 놓치지 마시오!', `MaleText_loc4`='暗月马戏团已经来到本镇了！不要错过有史以来最华丽的表演！', `MaleText_loc5`='暗月馬戲團已經來到鎮上了!不要錯過有史以來最刺激的表演!', `MaleText_loc7`='¡Llega a la ciudad la Feria de la Luna Negra! ¡El espectáculo más apasionante que jamás hayáis visto!' WHERE `ID`=10102;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다크문 축제는 머지않아 막을 내릴 거요. 그러니 지금 바로 구경 가시오!', `MaleText_loc4`='暗月马戏团只会逗留有限的时间。一定要在今天来看看啊！', `MaleText_loc5`='暗月馬戲團只會停留有限的時間。一定要在今天來看啊!', `MaleText_loc7`='La Feria de la Luna Negra solo estará abierta durante un breve período de tiempo antes de que se bajen las cortinas. ¡Aseguraos de venir hoy!' WHERE `ID`=10103;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다크문 축제가 시작됐소! 형, 누나, 오빠, 언니, 동생이랑 다 같이 구경들 하시오!', `MaleText_loc4`='男孩们女孩们——所有的孩子们——暗月马戏团已经到啦！哈哈！', `MaleText_loc5`='男孩們、女孩們－所有的孩子們，暗月馬戲團來了!哈哈!', `MaleText_loc7`='¡Niños y niñas de todas las edades, ha llegado la Feria de la Luna Negra! ¡Hurra!' WHERE `ID`=10104;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다크문 축제가 시작됐습니다! 모두 아제로스 전체에서 가장 신나는 쇼를 놓치지 마세요!', `MaleText_loc4`='看这边！暗月马戏团开市啦！记得来看看艾泽拉斯最激动人心的集会！', `MaleText_loc5`='來吧!暗月馬戲團正式開始營業!記得來看全艾澤拉斯最刺激的表演!', `MaleText_loc7`='¡Está aquí! ¡La Feria de la Luna Negra está abierta! ¡No os perdáis el espectáculo más excitante de Azeroth!' WHERE `ID`=10105;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마을에서 다크문 축제가 열리고 있습니다! 평생 두 번 다시는 못 볼 짜릿한 쇼를 꼭 경험해 보세요!', `MaleText_loc4`='暗月马戏团已经来了！不要错过有史以来最华丽的表演！', `MaleText_loc5`='暗月馬戲團已經來到鎮上了!一定要來體驗你見過最刺激的表演!', `MaleText_loc7`='¡Llega a la ciudad la Feria de la Luna Negra! ¡El espectáculo más apasionante que jamás hayáis visto!' WHERE `ID`=10106;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다크문 축제는 머지않아 막을 내릴 겁니다. 그러니 지금 바로 구경 가십시오!', `MaleText_loc4`='暗月马戏团只会停留一小段时间，别错过今天的大好机会！', `MaleText_loc5`='暗月馬戲團只會停留有限的時間。一定要在今天來看啊!', `MaleText_loc7`='La Feria de la Luna Negra solo estará abierta durante un breve período de tiempo antes de que se bajen las cortinas. ¡Aseguraos de venir hoy!' WHERE `ID`=10107;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다크문 축제가 시작됐습니다! 형, 누나, 오빠, 언니, 동생이랑 다 같이 구경들 하십시오!', `MaleText_loc4`='男孩们女孩们——所有的孩子们——暗月马戏团已经到啦！哈哈！', `MaleText_loc5`='男孩們、女孩們－所有的孩子們，暗月馬戲團來了!哈哈!', `MaleText_loc7`='¡Niños y niñas de todas las edades, ha llegado la Feria de la Luna Negra! ¡Hurra!' WHERE `ID`=10108;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다크문 축제는 어디에서 열리게 되나요?', `MaleText_loc4`='暗月马戏团会在哪儿开张呢？', `MaleText_loc5`='暗月馬戲團到的時候會在哪兒落腳呢?', `MaleText_loc7`='¿Dónde estará situada la Feria de la Luna Negra?', `FemaleText_loc1`='다크문 축제는 어디에서 열리게 되나요?', `FemaleText_loc4`='暗月马戏团会在哪儿开张呢？', `FemaleText_loc5`='暗月馬戲團到的時候會在哪兒落腳呢?', `FemaleText_loc7`='¿Dónde estará situada la Feria de la Luna Negra?' WHERE `ID`=10109;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다크문 축제가 벌써 시작됐다고요? 지금 어디 있나요?', `MaleText_loc4`='你是说暗月马戏团已经来了？它在哪里？', `MaleText_loc5`='你是說暗月馬戲團已經來了?它在哪裡?', `MaleText_loc7`='¿Dices que ya ha llegado la Feria de la Luna Negra? ¿Dónde está?', `FemaleText_loc1`='다크문 축제가 벌써 시작됐다고요? 지금 어디 있나요?', `FemaleText_loc4`='你是说暗月马戏团已经来了？它在哪里？', `FemaleText_loc5`='你是說暗月馬戲團已經來了?它在哪裡?', `FemaleText_loc7`='¿Dices que ya ha llegado la Feria de la Luna Negra? ¿Dónde está?' WHERE `ID`=10110;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다크문 축제의 다음 장소는 아직 결정되지 않았습니다. 결정되는 대로 알려 드리겠습니다!', `MaleText_loc4`='暗月马戏团的下一站还没有决定，但是相信你和我都会在第一时间知道的！', `MaleText_loc5`='暗月馬戲團的下一站還沒有決定，但是相信你和我都會在第一時間知道的!', `MaleText_loc7`='Todavía no hemos terminado de preparar la próxima ubicación de la Feria de la Luna Negra, pero cuando todo esté listo, ¡tú y yo seremos los primeros en saberlo!' WHERE `ID`=10111;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 엘윈 숲, 황금골 바로 남쪽에서 다크문 축제가 열리고 있으니 절대로 놓치지 마세요!', `MaleText_loc4`='暗月马戏团到艾尔文森林来了，就在闪金镇的南边。走过路过不要错过！', `MaleText_loc5`='暗月馬戲團到艾爾文森林來了，就在閃金鎮的南邊。走過路過不要錯過!', `MaleText_loc7`='La Feria de la Luna Negra está en el Bosque de Elwynn, justo al sur de Villadorada. ¡Que nadie se lo pierda!' WHERE `ID`=10112;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다크문 축제는 엘윈 숲에서 열릴 예정입니다. 다크문 유랑단이 황금골 바로 남쪽에서 여러분을 맞이할 겁니다!', `MaleText_loc4`='当暗月马戏团开始展览的时候，他们会出现在艾尔文森林。我们的帐篷将驻扎在闪金镇的南边！', `MaleText_loc5`='暗月馬戲團在艾爾文森林開張的時候，我們會在閃金鎮的南方搭建我們的帳篷!', `MaleText_loc7`='Cuando la Feria de la Luna Negra esté abierta, estará ubicada en el Bosque de Elwynn. ¡Montaremos nuestras tiendas justo al sur de Villadorada!' WHERE `ID`=10113;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 썬더 블러프 바로 남서쪽 멀고어 황금빛 초원에서 다크문 축제가 열리고 있습니다. 꼭 구경 가세요!', `MaleText_loc4`='暗月马戏团到莫高雷的金色平原来了，就在雷霆崖的西南边。走过路过不要错过！', `MaleText_loc5`='暗月馬戲團到莫高雷的金色平原來了，就在雷霆崖的西南邊。走過路過不要錯過!', `MaleText_loc7`='Ahora mismo, la Feria de la Luna Negra está en las doradas praderas de Mulgore, al suroeste de Cima del Trueno. ¡Que nadie se lo pierda!' WHERE `ID`=10114;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다크문 축제는 멀고어에서 열릴 예정입니다. 썬더 블러프 바로 남서쪽에 여러분을 맞이할 겁니다!', `MaleText_loc4`='暗月马戏团将会在莫高雷开张，我们就在雷霆崖的西南方安营扎寨！', `MaleText_loc5`='暗月馬戲團在莫高雷開張的時候，我們會在雷霆崖的西南方搭建我們的帳篷!', `MaleText_loc7`='Cuando la Feria de la Luna Negra esté abierta, estará ubicada en Mulgore. ¡Montaremos nuestras tiendas justo al suroeste de Cima del Trueno!' WHERE `ID`=10115;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='asdasd', `MaleText_loc4`='asdasd', `MaleText_loc5`='asdasd', `MaleText_loc7`='asdasd' WHERE `ID`=10116;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요.', `MaleText_loc4`='你好，朋友。', `MaleText_loc5`='哈囉朋友。', `MaleText_loc7`='Hola, $gamigo:amiga;.', `FemaleText_loc1`='안녕하세요.', `FemaleText_loc4`='你好，朋友。', `FemaleText_loc5`='哈囉朋友。', `FemaleText_loc7`='Hola, $gamigo:amiga;.' WHERE `ID`=10117;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 주변은 정말 지저분하군요.', `MaleText_loc4`='这附近有很多乱扔垃圾的家伙。', `MaleText_loc5`='這附近的確有很多亂扔垃圾的傢伙。', `MaleText_loc7`='Seguro que hay muchos bichejos por aquí.', `FemaleText_loc1`='이 주변은 정말 지저분하군요.', `FemaleText_loc4`='这附近有很多乱扔垃圾的家伙。', `FemaleText_loc5`='這附近的確有很多亂扔垃圾的傢伙。', `FemaleText_loc7`='Seguro que hay muchos bichejos por aquí.' WHERE `ID`=10118;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='즐거운 시간 보내고 계신가요?', `MaleText_loc4`='玩得开心吗？', `MaleText_loc5`='玩得開心嗎?', `MaleText_loc7`='¿Te lo estás pasando bien?', `FemaleText_loc1`='즐거운 시간 보내고 계신가요?', `FemaleText_loc4`='玩得开心吗？', `FemaleText_loc5`='玩得開心嗎?', `FemaleText_loc7`='¿Te lo estás pasando bien?' WHERE `ID`=10119;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='간식거리와 기념품 사시는 것도 잊지 마세요!', `MaleText_loc4`='别忘记买点饮料和纪念品！', `MaleText_loc5`='別忘記買點飲料和紀念品!', `MaleText_loc7`='¡No te olvides de comprar comida y regalos!', `FemaleText_loc1`='간식거리와 기념품 사시는 것도 잊지 마세요!', `FemaleText_loc4`='别忘记买点饮料和纪念品！', `FemaleText_loc5`='別忘記買點飲料和紀念品!', `FemaleText_loc7`='¡No te olvides de comprar comida y regalos!' WHERE `ID`=10120;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다크문 축제는 아제로스 전체에서 가장 큰 행사랍니다!', `MaleText_loc4`='暗月马戏团是全艾泽拉斯最华丽的！', `MaleText_loc5`='暗月馬戲團是全艾澤拉斯最盛大的事件!', `MaleText_loc7`='La Feria de la Luna Negra es el espectáculo más importante de todo Azeroth.', `FemaleText_loc1`='다크문 축제는 아제로스 전체에서 가장 큰 행사랍니다!', `FemaleText_loc4`='暗月马戏团是全艾泽拉斯最华丽的！', `FemaleText_loc5`='暗月馬戲團是全艾澤拉斯最盛大的事件!', `FemaleText_loc7`='La Feria de la Luna Negra es el espectáculo más importante de todo Azeroth.' WHERE `ID`=10121;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; $n|1을;를; 노려봅니다.', `MaleText_loc4`='%s凝视着$n。', `MaleText_loc5`='%s注視著$n。', `MaleText_loc7`='%s fija su atención en $n.', `FemaleText_loc1`='%s|1이;가; $n|1을;를; 노려봅니다.', `FemaleText_loc4`='%s凝视着$n。', `FemaleText_loc5`='%s注視著$n。', `FemaleText_loc7`='%s fija su atención en $n.' WHERE `ID`=10122;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$c님, 다크문 축제에 오신 걸 환영해요!$B$B전 케리 힉스라고 해요. 악수를 청하고 싶지만 손을 다치실까 봐 그럴 수가 없네요. 왜냐하면 전 이 세계에서 가장 강한 여자거든요!', `FemaleText_loc4`='欢迎来到暗月马戏团，$c！$B$B我叫克莉·希克斯，我应该跟你握手致意的，但是恐怕我会把你的手捏碎，因为我是当今世上最强的女人！', `FemaleText_loc5`='歡迎來到暗月馬戲團，$c!$B$B我叫克莉·希克斯，我應該跟你握手致意的，但是我怕會把你的手捏碎，因為我是當今世上最強壯的女人!', `FemaleText_loc7`='¡Te doy la bienvenida a la Feria de la Luna Negra, $c!$B$BMe llamo Kerri Hicks y estrecharía tu mano, pero me da miedo romperla, ¡porque soy la mujer más fuerte del mundo!' WHERE `ID`=10123;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요! 지금까지 도와 주셔서 감사합니다! 제가 지금 당장은 필요한 게 없지만 앞으로 뭐가 필요하게 될지 누가 알겠어요?$B$B재미있게 즐기세요. 친구들에게 다크문 축제에 대해 얘기해 주는 것도 잊지 마시고요!', `FemaleText_loc4`='嗨，$n！感谢你对我的帮助！现在我什么都不缺啦，但是未来会怎样，又有谁知道呢？$B$B享受生活吧，别忘记跟你的朋友谈谈暗月马戏团的趣闻！', `FemaleText_loc5`='嗨，$n!感謝你給我的幫助!現在我什麼都不缺了，但是未來會怎樣，又有誰知道呢?$B$B享受生活吧，別忘記告訴你的朋友暗月馬戲團的事情!', `FemaleText_loc7`='¡Hola, $n! Gracias por toda la ayuda que me has prestado. Ahora mismo, no necesito nada, ¿pero quién sabe lo que depara el futuro?$B$BDiviértete y recuerda hablar a tus amigos sobre la Feria de la Luna Negra.' WHERE `ID`=10124;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게로 오라! 운명이 준비해둔 미래를 직접 보라!', `MaleText_loc4`='到我这儿来吧，看看你的未来如何！', `MaleText_loc5`='到我這兒來吧，看看你的未來如何!', `MaleText_loc7`='¡Vengan a mí y contemplen lo que el futuro les depara!' WHERE `ID`=10125;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와서 나의 예언을 들으라. 불확실한 미래가 수정 거울처럼 분명해지리라.', `MaleText_loc4`='过来跟我谈谈，我会为你拨开疑云的。', `MaleText_loc5`='過來跟我談談，我會為你撥開疑雲的。', `MaleText_loc7`='Vengan a hablar conmigo y, lo que antes estaba poco claro, ¡estará más transparente que el cristal!' WHERE `ID`=10126;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두려워 말라! 길을 아는 자, 운명에 맞설 수 있다.', `MaleText_loc4`='别害怕！所有深谙此道的人都能洞察命运。', `MaleText_loc5`='別害怕!所有深諳此道的人都能洞察命運。', `MaleText_loc7`='¡No teman! Los que saben cómo hacerlo, pueden descifrar la fortuna de cualquiera.' WHERE `ID`=10127;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='운명을 놓고 우물쭈물할 시간이 있는가? 그만큼 불확실한 미래가 늘어날 뿐인데...', `MaleText_loc4`='你等得越久，我所能告诉关于你未来的信息就越少。', `MaleText_loc5`='你等得越久，我所能告訴關於你未來的資訊就越少。', `MaleText_loc7`='Cuanto más esperen, menos futuro tendrán para que se los prediga.' WHERE `ID`=10128;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='생맥주예요! 이리 와서 시원한 생맥주 한잔 맛보세요!', `FemaleText_loc4`='便宜的啤酒！到这儿来买啊，物超所值！', `FemaleText_loc5`='便宜的啤酒!到這兒來買便宜的啤酒啊!', `FemaleText_loc7`='¡Cerveza barata! ¡Cerveza barata aquí mismo!' WHERE `ID`=10129;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='팁은 언제나 대환영! 시원하고 맛있는 음료로 목을 축이세요!', `FemaleText_loc4`='为给小费的好心人喝彩！往右边走，到那儿去品尝美味的冷饮吧！', `FemaleText_loc5`='為給小費的好心人喝彩!往右邊走，到那兒去品嘗美味的冷飲吧!', `FemaleText_loc7`='¡Hurra por la propina! ¡Pasa, pasa y tómate una deliciosa bebida helada!' WHERE `ID`=10130;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='방금 막 들어온 다크문 폭탄주 있어요. 다 팔리기 전에 어서 와서 맛보세요!', `FemaleText_loc4`='就在……另一批暗月储备物资中。取回属于你自己的那份吧，它们很快会被抢光的！', `FemaleText_loc5`='剛做好的...另一批的暗月特調。趕快來吧，它們很快會被搶光的!', `FemaleText_loc7`='Solo... Otra tanda de Gran Reserva de la Luna Negra. ¡Ven a por la tuya antes de que se acaben todas!' WHERE `ID`=10131;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이봐요! 그래요, 당신 말이에요! 목 마르시죠? 당신에게 필요한 시원한 음료가 있으니 당장 이리 오세요!', `FemaleText_loc4`='你！就是你！你看起来很口渴。来吧，我有你想要的东西！', `FemaleText_loc5`='你!就是你!你看起來很口渴。來吧，我有你想要的東西!', `FemaleText_loc7`='¡Eh, tú! ¡Sí, tú! Parece que tienes sed. Ven aquí, tengo justo lo que necesitas.' WHERE `ID`=10132;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오시게! 여기 매콤한 핫윙 좀 먹어 보게나!', `MaleText_loc4`='快来吧！来买热辣烤翅啊！', `MaleText_loc5`='靠過來!來這裡買嗆紅辣翅!', `MaleText_loc7`='¡Vengan! ¡Alitas súper picantes aquí mismo!' WHERE `ID`=10133;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방금 구워낸 따끈따끈한 다크문 핫도그... 식기 전에 어서 와서 들게나!', `MaleText_loc4`='现烤现卖的暗月热狗，新鲜热烫！大家赶快趁热来买啊！', `MaleText_loc5`='剛從架上取下的暗月熱狗。趕快趁熱來買喔!', `MaleText_loc7`='Perritos de la Luna Negra, ¡recién sacados de la barbacoa! Venid a probarlos mientras están calientes.' WHERE `ID`=10134;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네한테는 돈이 있고 우리에겐 맛있는 음식이 있는데, 뭘 망설이는 겐가?!', `MaleText_loc4`='你有金钱，我们有食物。那么你还在等什么？！', `MaleText_loc5`='你有錢，我們有食物。你還在等什麼?!', `MaleText_loc7`='Tú tienes dinero y nosotros comida. ¡¿A qué estás esperando?!' WHERE `ID`=10135;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다크문 축제에서만 맛볼 수 있는 개구리 튀김! 한정 기간만 판매하지...', `MaleText_loc4`='限时供应！暗月马戏团独家美味，脆青蛙肉！机会难得！', `MaleText_loc5`='香脆田雞只在暗月馬戲團有賣，機會難得，限時供應哦!', `MaleText_loc7`='¡Edición limitada! Rana crujiente solo aquí, en la Feria de la Luna Negra.' WHERE `ID`=10136;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다크문 카드 한 벌을 다 모으셨습니까? 여기로 가져오십시오!', `MaleText_loc4`='你有完整的暗月套牌吗？快来我这儿兑换吧！', `MaleText_loc5`='有收集完整的暗月套卡嗎?拿來給我!', `MaleText_loc7`='¿Has completado una baraja de la Luna Negra? ¡Canjéala aquí!' WHERE `ID`=10137;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다크문 축제 카드를 가지고 있는 분이라면 저를 찾아 주십시오.', `MaleText_loc4`='如果你有暗月马戏团卡片的话，就来找我。', `MaleText_loc5`='要是你有任何暗月馬戲團卡片的話，請來找我談一談。', `MaleText_loc7`='Ven a hablar conmigo si tienes alguna carta de la Feria de la Luna Negra.' WHERE `ID`=10138;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다크문 카드 한 벌을 다 모으셨다면, 이리 가져오십시오!', `MaleText_loc4`='暗月套牌！快来兑换暗月套牌了！', `MaleText_loc5`='暗月套卡!拿來跟我換!', `MaleText_loc7`='¡Barajas de la Luna Negra! ¡Canjéalas aquí!' WHERE `ID`=10139;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다크문 축제 카드를 가지고 있습니까? 자세히 알아볼 배짱이 있으면 물어보십시오!', `MaleText_loc4`='你有暗月马戏团卡片吗？如果你有胆子的话，就来找我了解详情吧！', `MaleText_loc5`='你有暗月馬戲團卡片嗎?如果你想知道更多詳情，就來跟我談一談吧!', `MaleText_loc7`='¿Tienes alguna carta de la Feria de la Luna Negra? ¡Ven a hablar conmigo para descubrir más cosas sobre ellas si te atreves!' WHERE `ID`=10140;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내가 팔고 있는 물건들은 모두 내가 직접 모은 것들이지. 그러니까 제대로 된 물건이라는 걸 내가 직접 보증한다고.', `FemaleText_loc4`='我出售的每项物品都是我自己的劳动所得。我向你保证。', `FemaleText_loc5`='我出售的每項物品都是我自己取得的。我向你保證。', `FemaleText_loc7`='Todo lo que tengo a la venta lo he adquirido yo misma. Tienes mi garantía personal de autenticidad.' WHERE `ID`=10141;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다크문 축제 카드? 그거라면 여기 있는 학자에게 가봐.', `FemaleText_loc4`='暗月卡片？去找教授问问吧。', `FemaleText_loc5`='暗月馬戲團卡片?找在這裡的教授就對了。', `FemaleText_loc7`='¿Cartas de la Feria de la Luna Negra? Busca al Profesor.' WHERE `ID`=10142;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='기회가 있을 때 내 물건들을 실컷 구경해 두는 게 좋을 거야. 우린 이번 주까지만 여기 있고 멀리 이동할 거니까.', `FemaleText_loc4`='趁现在还有机会，过来看看我的货物吧。我们要在这儿呆上一周，然后就要动身去远方啦。', `FemaleText_loc5`='趁現在還有機會，過來看看我的貨物吧。我們會在這兒待上一整個禮拜，然後就要動身去遠方啦。', `FemaleText_loc7`='Echa un vistazo a mis mercancías mientras todavía puedas. Estaremos aquí toda la semana y, después, nos iremos a algún sitio remoto.' WHERE `ID`=10143;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 귀중한 물건들을 구하기 위해 내가 얼마나 고생했는지 상상도 못 할걸. 와서 전부 다 구경하도록!', `FemaleText_loc4`='我历尽艰辛才将这些无价之宝带来此地销售，你知道吗？来看看吧。', `FemaleText_loc5`='你知道我花了多少心血才將這些無價之寶帶來此地銷售的嗎?來看看吧。', `FemaleText_loc7`='¿Tienes alguna idea de lo que tengo que sufrir para traer estos incomparables objetos y ponerlos a la venta? ¡Ven a verlo con tus propios ojos!' WHERE `ID`=10144;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기, 누가 이 개구리 좀 잡아 주세요!', `MaleText_loc4`='嗨，谁来帮我抓住这个东西！', `MaleText_loc5`='嘿，誰來幫我抓住這個東西!', `MaleText_loc7`='¡Eh, que alguien me ayude a coger esta cosa!' WHERE `ID`=10145;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='개구리가 달아나려 해요!', `MaleText_loc4`='它跑开了！', `MaleText_loc5`='它跑掉了!', `MaleText_loc7`='¡Se escapa!' WHERE `ID`=10146;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='개굴아, 이리 돌아와!', `MaleText_loc4`='回来！', `MaleText_loc5`='回來這裡!', `MaleText_loc7`='¡Vuelve aquí!' WHERE `ID`=10147;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='개구리와 가죽공을 팔고 있어요!', `MaleText_loc4`='出售青蛙和皮球啦！', `MaleText_loc5`='賣青蛙跟皮球喔!', `MaleText_loc7`='¡Ranas y bolas de cuero a la venta!' WHERE `ID`=10148;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상품권이 있나? 이리 와서 다크문 축제 상품권을 교환하게! 놀랍고 진귀한 상품들이 자네를 기다리고 있다네!', `MaleText_loc4`='奖券！快来兑换你的暗月马戏团奖券吧！新奇的奖品正在等着你！', `MaleText_loc5`='獎品券!來這裡兌換你的暗月馬戲團獎品券!神奇美妙的獎品正在等著你!', `MaleText_loc7`='¡Vales! ¡Cambien aquí sus vales de la Feria de la Luna Negra! ¡Les esperan premios exóticos y asombrosos!' WHERE `ID`=10149;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신비한 상품들이 모험가들을 기다리고 있다네. 어서 오게, 어서!', `MaleText_loc4`='神秘的奖品在等你，冒险家们。快来啊，快来啊！', `MaleText_loc5`='神秘的獎品在等著你，冒險家們。快來吧，快來吧!', `MaleText_loc7`='Premios misteriosos esperan a los aventureros. ¡Vengan, vengan, vengan!' WHERE `ID`=10150;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상품권이 다섯 개 있든 오백 개 있든 아무 상관이 없지, 친구... 꽝은 없으니까!', `MaleText_loc4`='不管你有五张奖券还是五百张奖券，朋友，这都没关系，人人都是赢家！', `MaleText_loc5`='5張或是250張獎券都無所謂，朋友，每個人都是贏家!', `MaleText_loc7`='¡Cinco vales, o cinco mil, no importa, todo el mundo gana!' WHERE `ID`=10151;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상품! 이리 와서 상품 타 가게! 다크문 축제 상품권을 귀한 물건으로 바꿔 가라고!', `MaleText_loc4`='奖品！到这儿来领取奖品啦！快来用暗月马戏团奖券兑换丰厚的奖品吧！', `MaleText_loc5`='獎品!到這兒來領取你的獎品!到這裡用暗月馬戲團獎品券兌換豐厚的獎品吧!', `MaleText_loc7`='¡Premios! ¡Premios justo aquí! ¡Ven rápido a cambiar los vales para la Feria de la Luna Negra por valiosos premios!' WHERE `ID`=10152;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아제로스 최고의 쇼, 다크문 축제에 오신 것을 환영합니다! 지금까지 모두 재미있는 시간 보내고 있다면 좋겠습니다! 네블기어의 다크문 별난 동물원도 들러 보시고 여기 있는 예브와 그의 친구들도 꼭 만나 보세요!', `MaleText_loc4`='每个人都还玩得开心吧？棒极了！欢迎来到暗月马戏团，艾泽拉斯最盛大的展览！当你在尼比盖尔的珍奇馆购物时记得跟亚布和他的朋友谈谈。', `MaleText_loc5`='大家都還玩得開心吧?太棒了!歡迎來到暗月馬戲團，艾澤拉斯最盛大的展覽!當你在尼比蓋爾的珍奇館購物時，記得跟亞布和他的朋友談一談。', `MaleText_loc7`='¿Todo el mundo se lo pasa bien? ¡Estupendo! Te doy la bienvenida a la Feria de la Luna Negra, el espectáculo más importante de todo Azeroth. Asegúrate de hablar con Yebb y sus amigos cuando visites el Zoo de Singularidades Luna Negra de Tesorillos.' WHERE `ID`=10153;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오세요. 다크문 축제에 오신 것을 환영합니다! 주저하지 말고 마음껏 즐기세요. 겁나 먼 나라에서 온 이국적인 유물을 사고 싶다면 라흐라를 찾아가세요. 혹시 운 좋게도 다크문 축제 카드가 있다면 학자 타데우스 팔레오와 얘기해 보세요. 배가 고프다고요? 목이 마르신가요? 운이 참 좋으신 분이군요! 바로 여기 실라니아와 스탬프가 맛있는 음식과 음료를 팔고 있거든요. 특히 매콤한 핫윙을 좀 드신 후에 입가심으로 다크문 폭탄주를 마시면 아주 딱이에요. 미래를 알고 싶으신 분은 얼른 가서 세이지와 운명 상담을 하세요! 어서 가세요!', `MaleText_loc4`='来啊，大家都来啊。欢迎来到暗月马戏团！不要害羞。到兰拉这里购买来自遥远大陆的奇特东西。如果你是个拥有暗月卡片的幸运儿，那么就去找萨杜斯·帕雷教授吧。渴了？饿了？你很幸运！你可以从塞兰妮亚和斯塔姆那里获得让你倍感清新的食物和水。我建议你去尝尝暗月特殊储备那里的热辣烤翅，绝对不容错过！如果你想要了解自己的未来，那么快点去找塞格谈谈。', `MaleText_loc5`='來啊來啊。歡迎來到暗月馬戲團!不要害羞。到蘭拉這裡替你自己買個從遙遠地方來的奇特工藝品。如果你是那些少數找到暗月卡片的幸運傢伙之一的話，請去跟帕利歐教授談談。餓了?你真幸運!由希拉妮雅跟史丹普所做的餐點就在這裡。我推薦暗月特調搭配一些嗆紅辣翅。如果你想要追求財富，那別用走的，用跑的去找賽吉吧。', `MaleText_loc7`='¡Vamos, vengan todos! ¡Bienvenidos a la Feria de la Luna Negra! No sean tímidos. Vayan a ver a Lhara y comprense un artefacto exótico de tierras lejanas. Si eres uno de los pocos que han tenido la suerte de encontrar una carta de la Luna Negra, vete a hablar con el Profesor Paleo. ¿Tienes hambre? ¿Sed? ¡Estás de suerte! Puedes encontrar de todo aquí mismo, en Sylannia y Stamp. Recomiendo el Gran Reserva de la Luna Negra para ayudar a bajar unas alitas súper picantes. Y, si lo que quieres es saber tu futuro, ¡corre, no camines y corre a hablar con Sayge!' WHERE `ID`=10154;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아제로스 최고의 행사인 다크문 축제에 오신 모든 분들을 환영합니다! 맛난 음식과 독한 술, 이국적인 유물과 깜짝 놀랄만한 물건들, 그리고 점쟁이의 운명 상담 등 눈이 휘둥그레질만한 재미가 끝없이 준비되어 있답니다! 다크문 축제 상품권이 있다면 잊지 말고 겔바스 그림게이트에게 가서 교환하세요! 다섯 개 이상만 있으면 누구나 이 세상에서 최고로 멋진 상품을 받을 수 있으니까요. 꽝은 없으니 안심하셔도 좋습니다!', `MaleText_loc4`='欢迎所有人来到暗月马戏团，世界上最盛大的事件！我们拥有……可口的美食、烈性饮料、异地的神器、寻宝书、丰厚的奖品和无尽的刺激！别忘记将你的暗月马戏团奖券交给吉瓦斯·格里加特！只需要5张奖券你就可以领取一份艾泽拉斯最丰厚的奖品。每个人都是赢家！', `MaleText_loc5`='歡迎大家來到暗月馬戲團，世界上最偉大的盛事!我們這裡什麼都有...美味的食物，濃烈的飲料，奇特的工藝品，神秘的占卜，驚人的獎品還有無窮盡的驚奇!別忘了把你的暗月馬戲團獎品券交給吉瓦斯·葛萊蓋特!只要五張票或是更多，你就有機會贏得整個艾澤拉斯大陸上最不可思議的獎品。每個人都是贏家!', `MaleText_loc7`='¡Todos bienvenidos a la Feria de la Luna Negra, la mejor de todo el mundo! Lo tenemos todo... Comida deliciosa, bebidas fuertes, artefactos exóticos, adivinación de futuro, premios increíbles, ¡y mucho más! No olvidan cambiar sus vales de la Feria de la Luna Negra por premios. ¡Vayan a hablar con Gelvas Roñoso! ¡Solo se necesitan cinco o más para conseguir los premios más maravillosos de todo Azeroth! ¡Todo el mundo gana!' WHERE `ID`=10155;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아제로스 최고의 쇼... 다크문 축제에 오신 모든 분들을 환영합니다! 자, 주저하지 말고 이곳에서 여러분을 기다리고 있는 흥미진진한 모험과 흥분을 맘껏 즐기십시오! 남녀노소 모두를 위하여 신비로운 볼거리와 상품들이 잔뜩 준비되어 있습니다. 혹시 모험을 하시던 중에 다크문 축제 카드를 발견했다면 잊지 말고 여기 있는 학자를 찾아가 보십시오!', `MaleText_loc4`='欢迎所有人参加艾泽拉斯最盛大的展览……暗月马戏团！快来体验精彩和刺激吧，别害羞！这儿出售各种新奇的货物，老少皆宜啦。记得跟教授谈谈关于暗月卡片的事儿。', `MaleText_loc5`='歡迎所有人來到艾澤拉斯最偉大的盛會...暗月馬戲團!冒險和刺激正在等著你，別害羞!這兒出售各種新奇的貨物，老少皆宜啦。記得跟教授談談你在旅途中發現的暗月卡片的事情。', `MaleText_loc7`='Bienvenidos al espectáculo más impresionante de todo Azeroth... ¡La Feria de la Luna Negra! ¡Aventura y excitación los espera! Misterios y premios para jóvenes y viejos. Y no olviden hablar con el Profesor si se han encontrado con alguna carta de la Luna Negra en sus viajes.' WHERE `ID`=10156;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아제로스 최고의 쇼에 오신 것을 환영합니다!$B$B어서 와서 마음껏 즐기시기 바랍니다. 즐길 거리와 볼거리가 가득합니다! 이 신비하고 광활한 세계에서 다크문 축제 유랑단이 발견한 온갖 놀라운 물건들을 구경하세요! 아이들이라면 모두 좋아할 재미있는 물건들을 아낌없이 준비해 놓았습니다!', `MaleText_loc4`='你好，朋友，欢迎来到艾泽拉斯大陆最伟大的展出！$B$B请你过来，看看我们呈现给你的东西。快来看看这些千奇百怪的东西吧！为暗月马戏团从这个神秘广阔世界收集到的东西而惊叹吧！我们不会收取你任何费用，我们会为所有的孩子带来快乐！', `MaleText_loc5`='你好!朋友們，歡迎參觀艾澤拉斯大陸上最偉大的表演!$B$B請往前走並享受我們所提供的一切。讓暗月馬戲團在這個巨大而神秘的世界上所發現的奇特事物為你帶來前所未有的驚奇!我們會繼續不遺餘力地為各個年齡的小孩帶來雀躍不已的興奮感受!', `MaleText_loc7`='¡Hola, amigos, les doy la bienvenida al mayor espectáculo de todo Azeroth!$B$BPor favor, pasen y disfruten de todo lo que podemos ofrecerles. ¡Suban en las atracciones y disfruten de las vistas! ¡Sorpréndanse con las maravillas que la Feria de la Luna Negra ha descubierto en este vasto y misterioso mundo! No hemos reparado en gastos para poder ofrecer una diversión tan increíble que deleitará a niños de todas las edades.' WHERE `ID`=10157;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오세요! 다크문 축제에 오신 것을 환영합니다! 모험을 원하시나요? 이국적이고 신비한 보물을 찾고 계신가요? 그렇다면 더 이상 찾아다니지 마십시오! 여기가 바로 여러분이 찾던 곳이니까요! 축제의 모든 것을 마음껏 즐기십시오! 이번 주 내내 이곳에서 열리니까 친구들과 주변의 모두에게 꼭 귀띔해 주세요!', `MaleText_loc4`='来吧！欢迎来到暗月马戏团！你想要冒险吗？你想找寻奇珍异宝吗？那就不要只是观看啦！我的朋友，你来对地方啦！来吧，亲身参与到狂欢节中来，尽情享受吧！我们这周都会呆在这儿，记得把这消息告诉你的朋友和爱人！', `MaleText_loc5`='來吧!歡迎來到暗月馬戲團!你想要冒險嗎?你想找尋奇珍異寶嗎?那就不要光是看看而已!我的朋友，你來對地方啦!來吧，親身參與到馬戲團裡來盡情享受吧!我們整個星期都會待在這兒，記得把這消息告訴你的朋友和你所愛的人啊!', `MaleText_loc7`='¡Vamos, vengan todos! ¡Bienvenidos a la Feria de la Luna Negra! ¿Buscas aventuras? ¿Buscas exóticos y misteriosos tesoros? ¡Pues no sigas buscando! ¡Has venido al lugar indicado! ¡Pasa y participa en todo lo que la Feria de la Luna Negra te ofrece! Estaremos aquí una semana, ¡avisa a tus amigos y a tus seres queridos!' WHERE `ID`=10158;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런... 안됐지만, 자네는 최근에 내게서 점괘를 받았기 때문에 지금은 운명 상담을 받을 수 없어.$B$B점괘를 받은 지 몇 시간이 지난 후에 다시 오라고. 그러면 운명의 힘이 다시 원상태로 돌아오게 되니까 내가 자네의 미래를 예견할 수 있을 거야.', `MaleText_loc4`='唉……很抱歉，我现在还不能告诉你什么，你近来刚从我这儿获得了关于命运的信息。$B$B过几个小时你再来找我吧。命运的力量或许会有所改变，我会洞察你的未来。', `MaleText_loc5`='唉...很抱歉，我現在還不能幫你算命，因為你不久前才剛從我這兒獲知了命運占卜的結果。$B$B過幾個小時再來找我吧。命運的力量將會有所改變，那時候我就可以洞察你的未來了。', `MaleText_loc7`='Oh... Siento decirte que, ahora mismo, no puedo leer tu fortuna, ya lo he hecho una vez para ti.$B$BVuelve a verme dentro de unas horas. ¡Las fuerzas del destino se habrán calibrado de nuevo y podré ver tu futuro otra vez!' WHERE `ID`=10159;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왔습니다! 다크문 축제가 왔어요! 그 어느 때보다 더욱 멋진 모습으로! 여러분에게 즐거움을 선사하기 위해 비용 따위는 아끼지 않고 전 세계를 유랑하며 진귀하고 놀라운 물건들을 모아 왔습니다. 오늘은 행운이 가득한 날! 남녀노소 누구나 다크문 축제에서 흥겨운 시간을 보낼 수 있습니다! 다크문 축제 상품권이 있다면 잊지 말고 겔바스 그림게이트를 찾아가세요! 놀라운 상품이 기다리고 있으니까요!', `MaleText_loc4`='我们回来啦，感觉棒极了！暗月马戏团的朋友们，今儿是你们的幸运日！不要吝惜你的钱财，我们出售的都是来自世界各地的稀罕之物。无论你年方几何，无论你是贫穷还是富有，都能在暗月马戏团上买到称心如意的东西！请记得将你们的暗夜集市奖券交给吉瓦斯·格里加特，挑选一份丰厚的奖品！', `MaleText_loc5`='我們回來了，而且變的更好!我們就是暗月馬戲團，朋友，今天真是你的幸運日!完全不需任何費用，我們為你收集了世界上的奇珍異寶。不管你是老是少，是窮是富，暗月馬戲團擁有你所要的一切!記得把你的暗月馬戲團獎品券交給吉瓦斯·葛萊蓋特，然後挑選一個奇特又新奇的獎品吧!', `MaleText_loc7`='¡Hemos vuelto y mejor que nunca! ¡Es la Feria de la Luna Negra, y tu día de suerte! Sin reparar en gastos, hemos conseguido las más fantásticas maravillas de todo el mundo, ¡y lo hemos hecho para ti! ¡Joven o viejo, rico o pobre, da igual! ¡La Feria de la Luna Negra lo tiene todo! Asegúrate de cambiar tus vales para la Feria de la Luna Negra por premios hablando con Gelvas Roñoso. ¡Podrás elegir entre un montón de premios exóticos y maravillosos!' WHERE `ID`=10160;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n, 다시 만나 반가워요! 축제에서 즐거운 시간 보내고 계신가요?$B$B팔씨름 한 판 하실래요? 물론, 피하시겠죠... 팔이 부러지고 싶지는 않을 테니까요!', `FemaleText_loc4`='$n，很高兴再次见到你！你玩得开心吗？$B$B想要来掰手腕吗？不，当然不……你想要保护好自己的手臂！', `FemaleText_loc5`='$n，很高興再次見到你!你玩得開心嗎?$B$B想要來比腕力嗎?不，當然不...你還想保有自己的手臂吧!', `FemaleText_loc7`='¡$n, me alegro de verte de nuevo! ¿Te lo estás pasando bien en la Feria?$B$B¿Quieres echar un pulso? No, claro que no... ¡Seguro que no quieres perder tu brazo!' WHERE `ID`=10161;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하시오. 나는 기억력의 대가인 크로노스라고 하오. 내 기억력은 완벽해서 아무리 사소한 것이라도 모두 정확하게 기억한다오.$B$B믿어도 좋소이다.', `MaleText_loc4`='你好。我是克洛诺斯——记忆力天下第一的克洛诺斯。我是不会忘记任何微小的细节的。$B$B相信我。', `MaleText_loc5`='你好。我是克洛諾斯－過目不忘的克洛諾斯。我的記憶力毫無瑕疵，而且連最微小的細節都記得一清二楚。$B$B相信我。', `MaleText_loc7`='Saludos. Soy Chronos, el que nunca olvida. Mi memoria es perfecta y exacta incluso con el más ínfimo detalle.$B$BPuedes creerme.' WHERE `ID`=10162;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 만났군. 내가 당신을 잊을 거라 생각했소?$B$B물론 당신이 그렇게 생각하지 않으리란 걸 난 알고 있었지. 당신은 완벽한 기억력을 가진 자를 몰라보지 않을 만큼 똑똑한 $c|1이니까;니까; 말이오.', `MaleText_loc4`='你好，$n。你认为我会忘记你？$B$B我知道你不会这么认为的。你是个聪明的$c，你所认识的我一看到任何人就可以立即认出他。', `MaleText_loc5`='又見面了，$n。你認為我會忘記你?$B$B我知道你不會這麼認為的。你是個聰明的$c，你所認識的我只要看到任何人就可以立即認出$g他:她;。', `MaleText_loc7`='Hola de nuevo, $n. ¿Pensabas que te habría olvidado?$B$BPorque yo sabía que tú no me olvidarías a mí. Eres $gun:una; $c inteligente que reconoce una persona con la memoria perfecta cuando la ve.' WHERE `ID`=10163;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하신가, 어서 오게! 유감스럽게도, 아직 전시장을 개장하지 못했네... 고칠 게 워낙 많아서...$B$B난 자네 얼굴에 미소가 피어나게 하겠다고 피의 맹세를 했지. 그러니까 제발 좀 웃어달라고. 안 그러면 난 다크문 축제 유랑단에서 쫓겨나고 다시는 돌아오지 못하게 된단 말일세.', `MaleText_loc4`='你好！欢迎你！恐怕我的售货亭还不能开张……我得修理很多东西……$B$B但是我仍然受制于血的诅咒，求你啦，笑笑吧。如果你的脸上没有笑容的话，我就得砍下我的手，并且在手掌再生之前不得食用任何肉类……', `MaleText_loc5`='你好!歡迎你!恐怕我的攤位還不能開張...有很多東西得修理...$b$b但是我仍然受制於血的詛咒，求你啦，笑一笑吧。如果你的臉上沒有笑容的話，我就得砍下我的手，並且在手掌再生之前不得食用任何肉類...', `MaleText_loc7`='¡Hola! ¡$gBienvenido:Bienvenida;! Me temo que mi puesto todavía no está abierto... Se necesitan muchas reparaciones...$B$BPero hice el juramento de sangre de hacerte sonreír, y debo cumplirlo. Así que sonríe, o tendré que cortarme la mano y consumir carne sin vida hasta que se regenere…' WHERE `ID`=10164;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 자네 돌아왔군! 지난밤에 찾아온 어떤 영혼이 그러더군. 자네가 곧 나를 찾아와서 일 얘기를 하게 될 거라고 말이야.$B$B그 말이 맞는 건가?', `MaleText_loc4`='$n，你回来啦！我上次吃掉的那些灵魂说你会来看我的，而且我们还会谈谈生意。$B$B他们说对了吗？', `MaleText_loc5`='$n，你回來啦!我上次吃掉的那些靈魂說你會來看我的，而且我們還會談點生意。$B$B他們說對了嗎?', `MaleText_loc7`='¡$n, has vuelto! Los espíritus de mi última comida dijeron que volverías a verme y hablaríamos de negocios.$B$B¿Tenían razón?' WHERE `ID`=10165;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 안녕하세요! 다시 만나서 반가워요! 다크문 축제, 정말 멋진 쇼 아닌가요?$B$B볼거리는 또 얼마나 많은지! 열심히 구경해 두세요! 그러면 언젠가는 더 많은 것들이 당신 눈에 보이게 될 거예요.', `MaleText_loc4`='嗨，$n！很高兴见到你！暗月马戏团是一场盛大的展览，不是吗？$B$B有很多值得一看的东西！看吧！或许有一天会有更多的东西呈现在你面前……', `MaleText_loc5`='嗨，$n!很高興又見到你了!暗月馬戲團真是一場盛大的展覽，不是嗎?$B$B有很多東西值得一看!看吧!或許有一天，還會有更多的東西呈現在你面前...', `MaleText_loc7`='¡Hola de nuevo, $n! ¡Me alegro de verte! Nuestra Feria de la Luna Negra es un gran espectáculo, ¿no crees?$B$B¡Hay mucho que ver! ¡Así que tienes que verlo! Mira y observa y quizás, algún día, te será revelado mucho más...' WHERE `ID`=10166;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 맥주를 다 마셔버립니다!', `MaleText_loc4`='%s开怀畅饮啤酒！', `MaleText_loc5`='%s猛灌麥芽酒!', `MaleText_loc7`='%s se bebe la cerveza de un trago.' WHERE `ID`=10167;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 애완 개구리 줍줍이 사라졌어. 검은무쇠 맥주를 정말 좋아해서 그거만 마시는 녀석인데... 그런데 그 맥주는 정말 구하기가 너무 어려워! 맥주가 다 떨어지니까... 그 맛을 찾아서 도망친 게 틀림없다고!$B$B꼭 다시 돌아왔으면 좋으련만...', `FemaleText_loc4`='我找不到我的宠物青蛙加布加布啦。她爱喝黑铁啤酒，她总是喝这种酒，但是这种酒很不容易得到的！现在我没有黑铁啤酒了……加布加布一定是自己跑出去找酒喝啦！$B$B真希望她回到我身边……', `FemaleText_loc5`='我找不到我的寵物啾啾啦。她喜歡喝黑鐵麥芽酒，那是她唯一肯喝的飲料，但是卻很難取得!現在麥芽酒已經沒有了...啾啾一定是自己跑去找酒喝了!$B$B我希望她可以趕快回來...', `FemaleText_loc7`='No puedo encontrar a mi ranita, Jubjub. Le encanta la cerveza Hierro Negro, es lo único que bebe, ¡pero es tan difícil de conseguir! Me he quedado sin nada... ¡Y seguro que Jubjub se ha ido para encontrar más!$B$BOjalá vuelva...' WHERE `ID`=10168;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='줍줍이 돌아와서 정말 기쁘다! 이제 검은무쇠 맥주가 빨리 떨어지지 않기를 바라는 수밖에... 안 그러면 이 녀석이 또 도망칠 테니까!', `FemaleText_loc4`='加布加布回来啦，我太高兴了！我希望我的黑铁啤酒不会很快被喝光，否则这家伙又会偷跑出去啦！', `FemaleText_loc5`='啾啾回來了!我太高興了!我只希望我的黑鐵麥芽酒不會很快又被喝光了，不然我怕我的小青蛙可能會再一次偷跑出去的!', `FemaleText_loc7`='¡Estoy tan contenta de que Jubjub haya vuelto! Solo espero no volver a quedarme pronto sin cerveza Hierro Negro, ¡o mi ranita volverá a escaparse!' WHERE `ID`=10169;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕, 줍줍. 정말 보고 싶었어!', `FemaleText_loc4`='嗨，加布加布。我很想你！', `FemaleText_loc5`='嗨，啾啾。我好想你!', `FemaleText_loc7`='Hola Jubjub. ¡Te he echado de menos!' WHERE `ID`=10170;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='줍줍? 어디 있니, 줍줍? 아악! 대체 어디로 사라진 거야?', `FemaleText_loc4`='加布加布？你在哪儿，加布加布？你这次又跑哪儿去了！', `FemaleText_loc5`='啾啾?你在哪裡，啾啾?喔，不!你這次又跑去哪裡了!', `FemaleText_loc7`='¿Jubjub? ¿Dónde estás, Jubjub? ¡Oh, no! ¿Dónde te has ido esta vez?' WHERE `ID`=10171;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 주인의 목소리를 듣습니다!', `MaleText_loc4`='%s听到了主人的声音！', `MaleText_loc5`='%s聽到她的主人的聲音!', `MaleText_loc7`='%s escucha la voz de su dueño.' WHERE `ID`=10172;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일이 있어도 반드시 이 야영지를 지켜 내야 합니다! 어느 한 구역도 절대 적들에게 넘겨 줘서는 안 됩니다. 반대 입장이었다면 틀림없이 녀석들도 그렇게 할 겁니다.', `MaleText_loc4`='我们必须不惜一切代价保护这个营地的安全，$c！我们不能允许敌人再前进一步了！', `MaleText_loc5`='我們必須不惜一切代價保護這個營地的安全，$c!我們不能允許敵人再前進一步了!', `MaleText_loc7`='Debemos asegurar la supervivencia de este campamento a toda costa, $c. No hay que dar cuartel a nuestros enemigos, ya que ellos no nos lo darían si lo necesitásemos nosotros.' WHERE `ID`=10173;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요즘은 아주 위험한 시기라네. 고대 악의 씨앗이 싹트고 있는데, 호드와 얼라이언스를 구분하지 않거든.', `MaleText_loc4`='现在是危险时分，$r。远古的邪魔复活了，他可不管你是部落还是联盟。', `MaleText_loc5`='現在是危險時分，$r。遠古的邪魔復活了，他可不會管你是部落還是聯盟。', `MaleText_loc7`='Corren tiempos difíciles, $r. Se está levantando un mal ancestral, y no le importa si perteneces a la Horda o a la Alianza.' WHERE `ID`=10174;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='시원하고 맛있는 음료 팝니다! 다크문 축제 최고의 음료로 갈증을 해소하세요!', `FemaleText_loc4`='出售可口的饮料啦！暗月马戏团最好的酒，生津止渴！', `FemaleText_loc5`='出售好喝的飲料喔!用暗月馬戲團最高級的酒來舒緩你的渴望吧!', `FemaleText_loc7`='¡Deliciosas bebidas a la venta! Sacia tu sed con algunos de los mejores brebajes de la Feria de la Luna Negra.' WHERE `ID`=10175;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭘 망설이세요?! 모두에게 한 잔씩 돌려 보아요!', `FemaleText_loc4`='别害羞，请这儿的每个人喝上一杯吧！', `FemaleText_loc5`='不要害羞，請這兒的每個人喝上一杯吧!', `FemaleText_loc7`='¡Olvida tu timidez, invita a una ronda para todos!' WHERE `ID`=10176;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='팁이라면 언제든 대환영입니다.', `FemaleText_loc4`='朋友，招待生总是乐意收到小费的。', `FemaleText_loc5`='小費永遠不嫌多，朋友。', `FemaleText_loc7`='Siempre se aceptan propinas, camarada.' WHERE `ID`=10177;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='방금 막 들어온 다크문 폭탄주 있어요. 다 팔리기 전에 어서 와서 맛보세요!', `FemaleText_loc4`='就在……另一批暗月储备物资中。取回属于你自己的那份，它们很快会被抢光的！', `FemaleText_loc5`='剛做好的...另一批的暗月特調。趕快來吧，它們很快會被搶光的!', `FemaleText_loc7`='Solo... Otra tanda de Gran Reserva de la Luna Negra. ¡Ven a por la tuya antes de que se acaben todas!' WHERE `ID`=10178;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디 음료를 한번 봅시다!', `MaleText_loc4`='给我饮料！', `MaleText_loc5`='飲料拿來!', `MaleText_loc7`='¡Enséñame las bebidas!', `FemaleText_loc1`='어디 음료를 한번 봅시다!', `FemaleText_loc4`='给我饮料！', `FemaleText_loc5`='給我飲料!', `FemaleText_loc7`='¡Enséñame las bebidas!' WHERE `ID`=10179;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='개굴!', `MaleText_loc4`='呱呱。', `MaleText_loc5`='呱呱。', `MaleText_loc7`='¡Croac!' WHERE `ID`=10180;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='키스해 주세요!', `MaleText_loc4`='吻我。', `MaleText_loc5`='吻我。', `MaleText_loc7`='Bésame.' WHERE `ID`=10181;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물건 좀 볼까요?', `MaleText_loc4`='你都卖些什么东西？', `MaleText_loc5`='你有什麼東西要賣嗎?', `MaleText_loc7`='¿Qué tienes a la venta?', `FemaleText_loc1`='물건 좀 볼까요?', `FemaleText_loc4`='你都卖些什么东西？', `FemaleText_loc5`='你有什麼東西要賣嗎?', `FemaleText_loc7`='¿Qué tienes a la venta?' WHERE `ID`=10182;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빵 더 가져와!', `MaleText_loc4`='孩子，给我更多的面包！', `MaleText_loc5`='孩子，給我更多的麵包!', `MaleText_loc7`='¡Más pan, chico!' WHERE `ID`=10183;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 빵 가지고 왔어요.', `MaleText_loc4`='您的面包，大人。', `MaleText_loc5`='這是你要的麵包，先生。', `MaleText_loc7`='Aquí está su pan, señor.' WHERE `ID`=10184;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음... 맛있는 음식이 있나 좀 볼까요?', `MaleText_loc4`='嗯……食物。', `MaleText_loc5`='嗯...食物。', `MaleText_loc7`='Mmmmm... comida.', `FemaleText_loc1`='음... 맛있는 음식이 있나 좀 볼까요?', `FemaleText_loc4`='嗯……食物。', `FemaleText_loc5`='嗯...食物。', `FemaleText_loc7`='Mmmmm... comida.' WHERE `ID`=10185;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='개구리도 팔고 있다는 말이니?', `MaleText_loc4`='你想要出售青蛙？', `MaleText_loc5`='你想說的是你有在賣青蛙?', `MaleText_loc7`='¿Pretendes decirme que vendes ranas?', `FemaleText_loc1`='개구리도 팔고 있다는 말이니?', `FemaleText_loc4`='你想要出售青蛙？', `FemaleText_loc5`='你想說的是你有在賣青蛙?', `FemaleText_loc7`='¿Pretendes decirme que vendes ranas?' WHERE `ID`=10186;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$r|1이여;여;, 몰소르는 모든 걸 볼 수 있다네...', `MaleText_loc4`='莫托尔知道一切，$r。', `MaleText_loc5`='莫托爾知道一切，$r。', `MaleText_loc7`='Molthor lo ve todo, $r.' WHERE `ID`=10187;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑네, 젊은 $c|1이여;여;... 자네 대족장이 오그림 둠해머를 상대한 곳이 바로 여기라네! 아주 오래전 일이지만 내 마음속에는 아직도 그 모습이 생생히 남아 있지.', `MaleText_loc4`='你好，年轻的$c。就是在这里，你的酋长挑战了奥格瑞姆·毁灭之锤！虽然这事情已经过去了很久，但是在我的记忆中，它依然犹如刚刚发生过一样。', `MaleText_loc5`='你好，年輕的$c。就是在這裡，你的大酋長挑戰了奧格林·末日錘!雖然這事情已經過去了很久，但是在我的記憶中，它依然猶如剛剛發生過一樣。', `MaleText_loc7`='Saludos, joven $c. ¡Aquí fue donde tu Jefe de Guerra desafió a Orgrim Martillo Maldito! Si bien todo ocurrió hace muchos años, la imagen sigue viva en mi recuerdo.' WHERE `ID`=10188;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='현재 우리 사령관 중 몇 명이나 살아 있습니까, 드렉타르 님?', `MaleText_loc4`='我们的指挥官有多少还活着，德雷克塔尔？', `MaleText_loc5`='我們有多少指揮官還活著，德雷克塔爾?', `MaleText_loc7`='¿Cuántos de nuestros Comandantes siguen con vida, Drek''Thar?', `FemaleText_loc1`='현재 우리 사령관 중 몇 명이나 살아 있습니까, 드렉타르 님?', `FemaleText_loc4`='我们的指挥官有多少还活着，德雷克塔尔？', `FemaleText_loc5`='我們的指揮官有多少還活著，德雷克塔爾?', `FemaleText_loc7`='¿Cuántos de nuestros Comandantes siguen con vida, Drek''Thar?' WHERE `ID`=10189;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='젊은 $c|1이여;여;, $966w명이 살아있군.', `MaleText_loc4`='$966w，年轻的$c。', `MaleText_loc5`='$966w，年輕的$c。', `MaleText_loc7`='$966w, joven $c.' WHERE `ID`=10190;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭘 좀 배우러 온 모양이로군. 자네에게 맡길만한 일이 있을지도 모르겠어.', `FemaleText_loc4`='你是来学习的？嗯，我或许会给你一些事儿做的。', `FemaleText_loc5`='你是來學習的，嗯?我或許有些事情可以給你做。', `FemaleText_loc7`='Has venido a aprender, ¿eh? Bueno, quizás tenga algo de trabajo para ti, escoria.' WHERE `ID`=10191;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<거수경례를 하는 스톰파이크 하사관>$B$B성명, 계급, 그리고 군번! 그것들만이 자네가 저 더러운 서리늑대 개들에게 넘겨 줄 수 있는 유일한 정보다!', `MaleText_loc4`='<雷矛中士向你敬礼。>$B$B姓名，军阶和编号，士兵！这是你唯一需要提供给那些肮脏的霜狼走狗的信息！', `MaleText_loc5`='<雷矛中士向你敬了個禮。>$B$B姓名，軍階和編號，士兵!這是你唯一需要提供給那些骯髒的霜狼走狗的資訊!', `MaleText_loc7`='<El Sargento Pico Tormenta saluda.>$B$B¡Nombre, rango y número de serie, Soldado! ¡Esa es la única información que le darás a esos asquerosos perros Lobo Gélido!' WHERE `ID`=10192;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흐음... 더 좋은 미끼가 필요할 것 같아. 아빠 짐마차에 좀 다녀와야겠어.', `MaleText_loc4`='嗯……我觉得我需要更好的诱饵。我得去我父亲的货车中找找。', `MaleText_loc5`='嗯...我覺得我需要更好的誘餌。我得去我父親的貨車中找找。', `MaleText_loc7`='Mmmm... Creo que necesito preparar cebos. Iré a mirar en el vagón de mi padre.' WHERE `ID`=10195;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가시멧돼지 고기야! 좋았어! 물고기들은 돼지고기라면 아주 환장하지.', `MaleText_loc4`='野猪人的废弃物！这个应该可以。鱼喜欢野猪人。', `MaleText_loc5`='野豬人肉片!這個應該可以。魚喜歡野豬人的味道。', `MaleText_loc7`='¡Desechos de jabaespín! Eso debería de servir. A los peces les encantan los jabaespines.' WHERE `ID`=10196;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디 한번 던져볼까...', `MaleText_loc4`='让我们试试吧……', `MaleText_loc5`='讓我們試試看吧...', `MaleText_loc7`='Vamos a probar...' WHERE `ID`=10197;
