UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서리늑대 장교들은 몇 명이나 살아있습니까, 반다르?', `MaleText_loc4`='还有多少霜狼军官活着，范达尔？', `MaleText_loc5`='還有多少霜狼軍官活著，范達爾?', `MaleText_loc7`='¿Cuántos oficiales Lobo Gélido siguen con vida, Vanndar?', `FemaleText_loc1`='서리늑대 장교들은 몇 명이나 살아있습니까, 반다르?', `FemaleText_loc4`='还有多少霜狼军官活着，范达尔？', `FemaleText_loc5`='還有多少霜狼軍官活著，范達爾?', `FemaleText_loc7`='¿Cuántos oficiales Lobo Gélido siguen con vida, Vanndar?' WHERE `ID`=10241;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서리늑대 지휘관은 $966w명, 서리늑대 부관은 $964w명이 살아남았습니다.', `MaleText_loc4`='$966w个霜狼指挥官和$964w个霜狼上尉，士兵。', `MaleText_loc5`='$966w個霜狼指揮官和$964w個霜狼中尉，士兵。', `MaleText_loc7`='$966w Comandante(s) Lobo Gélido y $964w Teniente(s) Lobo Gélido.' WHERE `ID`=10242;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰파이크의 병사들이여, 그대들의 사령관이 공격받고 있노라! 도움이 필요하다! 어서 와서 이 비열한 서리늑대 개들을 처치하라!', `MaleText_loc4`='雷矛士兵，你们的将军受到攻击！我需要援助！快！快！杀死这些卑鄙的霜狼氏族的成员。', `MaleText_loc5`='雷矛士兵，你們的將軍受到攻擊了!我需要援助!快來!快來!殺死這些卑鄙的霜狼氏族的走狗。', `MaleText_loc7`='¡Soldados de Pico Tormenta, están atacando a su general! ¡Necesito ayuda! ¡Vamos! ¡Vengan! Maten a esos asquerosos perros Lobo Gélido.' WHERE `ID`=10243;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰파이크 쓰레기들이 감히 나의 요새에 쳐들어와?! 모조리 쳐라!', `MaleText_loc4`='雷矛的渣滓！在我的要塞？！杀光他们！', `MaleText_loc5`='雷矛的雜碎!在我的要塞?!殺光他們!', `MaleText_loc7`='¡Escoria Pico Tormenta! ¿¿En mi bastión?? ¡Acaben con ellos!' WHERE `ID`=10245;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흐음... 낚싯바늘을 어디다 뒀더라? 아, 저기 있네.', `MaleText_loc4`='嗯……我的鱼杆在哪儿呢？哦，在那儿。', `MaleText_loc5`='嗯...我的魚竿在哪兒呢?哦，找到了。', `MaleText_loc7`='Mmmm... ¿Dónde está mi caña de pescar? Oh, ahí está.' WHERE `ID`=10249;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고기들이 좀 무는지 어디 한번 볼까.', `MaleText_loc4`='让我们看看鱼上钩了没有。', `MaleText_loc5`='來看看魚兒有沒有在咬餌。', `MaleText_loc7`='Veamos si los peces pican...' WHERE `ID`=10250;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='트록. 너 배고파? 내가 만든 음식 같이 먹자!', `FemaleText_loc4`='特洛克你饿了吗？我在给我们俩做吃的！', `FemaleText_loc5`='特洛克你餓了嗎?我在給我們倆做些吃的!', `FemaleText_loc7`='Trok, ¿tienes hambre? Estoy preparando algo de comer.' WHERE `ID`=10251;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='트록? 왜 그렇게 겁먹은 인간처럼 날뛰고 난리야?', `FemaleText_loc4`='特洛克？为什么你像个胆小的人类一样跑来跑去？', `FemaleText_loc5`='特洛克?為什麼你像個膽小的人類一樣跑來跑去?', `FemaleText_loc7`='¿Trok? ¿Por qué corres como un humano temeroso?' WHERE `ID`=10252;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네 할 일은 네가 해야지!', `FemaleText_loc4`='自己的事应该自己做！', `FemaleText_loc5`='你理應做著你的工作!', `FemaleText_loc7`='¡Se supone que deberías estar haciendo tus tareas!' WHERE `ID`=10253;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='돼지들은 배고프지 않을까?', `FemaleText_loc4`='我在想那些猪是不是饿了……', `FemaleText_loc5`='我在想那些豬是不是餓了...', `FemaleText_loc7`='Me pregunto si los cerdos tienen hambre...' WHERE `ID`=10255;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='돼지들아, 배고프니? 먹을 걸 좀 가져왔어.', `FemaleText_loc4`='你饿了吗？我这儿有食物……', `FemaleText_loc5`='小豬們，你們餓了嗎?我這兒有些食物要給你們...', `FemaleText_loc7`='Cerditos, ¿tenéis hambre? Tengo algo de comida...' WHERE `ID`=10256;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='배가 무지 고팠던 모양이구나! 트록이 아까 밥을 줬어야 하는 건데... 그 녀석, 여태까지 뭘 하고 돼지들을 굶겨?', `FemaleText_loc4`='我猜你一定饿啦！特洛克应该在早些时候喂过你的……他都在干什么？', `FemaleText_loc5`='我猜你們一定都餓啦!特洛克應該早就要餵你們的...他到底都在幹些什麼?', `FemaleText_loc7`='¡Pues sí que teníais hambre! Se suponía que Trok os tenía que haber dado la comida antes... ¿Qué ha estado haciendo todo este tiempo?' WHERE `ID`=10257;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살려줘요! 벌떼한테 쫓기고 있어요!', `MaleText_loc4`='救命！一群蜜蜂在追我！', `MaleText_loc5`='救命!我正被一群蜜蜂追啊!', `MaleText_loc7`='¡Ayuda! ¡Me persigue un enjambre de abejas!' WHERE `ID`=10259;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 힘들어서 더는 못 뛰겠어. 벌떼가 계속 따라와!', `MaleText_loc4`='我讨厌跑步，但是这些蜜蜂追个不停！', `MaleText_loc5`='我已經不想再跑了，可是這些蜜蜂不肯放過我!', `MaleText_loc7`='¡Estoy agotado de correr y esas abejas no me dejan en paz!' WHERE `ID`=10260;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벌떼들이 불을 싫어하는지는 몰랐는데!', `MaleText_loc4`='为什么它们不喜欢火？', `MaleText_loc5`='我不知道蜜蜂不喜歡火!', `MaleText_loc7`='¡No sabía que a las abejas no les gustaba el fuego!' WHERE `ID`=10261;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카루, 이 벌떼들 좀 쫓아줘! 따가워 죽겠어!', `MaleText_loc4`='卡鲁斯能不能帮我把这些蜜蜂赶走？它们在蜇我！', `MaleText_loc5`='卡魯，你能不能幫我把這些蜜蜂趕走?它們在蜇我!', `MaleText_loc7`='Karu, ¿quieres ayudarme a librarme de estas abejas? ¡Me están picando!' WHERE `ID`=10262;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야... 좋아, 좋아. 그럼 가봐!', `MaleText_loc4`='啊……很好。嘘！', `MaleText_loc5`='啊...太好了。快走吧!', `MaleText_loc7`='Aaaah... Muy bien. ¡Ahora, fuera!' WHERE `ID`=10265;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알았어요.', `MaleText_loc4`='如你所愿。', `MaleText_loc5`='如你所願，長官。', `MaleText_loc7`='Como desees, señor.' WHERE `ID`=10266;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분부대로 할게요.', `MaleText_loc4`='遵命，长官。', `MaleText_loc5`='遵命，長官。', `MaleText_loc7`='Ahora mismo, señor.' WHERE `ID`=10267;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세계를 구하러 온 것이라면 제대로 찾아왔군. 얼굴 없는 자, 혈신 학카르가 다시 나타났다네!', `MaleText_loc4`='如果你是来拯救世界的，那么你来对地方了。无面者——血神哈卡——已经被带回到我们的世界来了！', `MaleText_loc5`='如果你是來拯救世界的，那麼你就來對地方了。無面者－也就是血神哈卡，已經被帶回到我們的世界來了!', `MaleText_loc7`='Si has venido a salvar el mundo, has venido al lugar indicado. El ignoto, el dios de la sangre Hakkar, ¡ha vuelto a nuestro mundo!' WHERE `ID`=10268;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 자네의 얼굴에 결의가 빛나는군. 계속해서 우리 부족의 편에 서서 돕고 있으니 언젠가는 온 세상이 자네의 훌륭한 업적을 알게 될 걸세.', `MaleText_loc4`='你决心的力量正在闪光，$n。你需要继续证明你对我们的人民来说是一笔宝贵的财产。有一天世界将会意识到你的所做所为是多么的重要。', `MaleText_loc5`='你決心的力量正在發光，$n。繼續證明你對我們的人民來說是一筆寶貴的財產。有一天世界將會意識到你的所做所為是多麼的重要。', `MaleText_loc7`='La fuerza de tu resolución brilla, $n. Sigues demostrando ser muy $gvalioso:valiosa; para los nuestros. Algún día, el mundo se dará cuenta de tus inmensos logros.' WHERE `ID`=10269;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자라나는 영웅이 돌아왔군! 다시 보게 되다니 반갑네, $n. 자네라면 우리 마을에서는 언제든지 대환영이야.', `MaleText_loc4`='菜鸟英雄又回来啦！很高兴见到你，$n，欢迎回到我们村！', `MaleText_loc5`='菜鳥英雄又回來啦!很高興再次見到你，$n，歡迎你隨時回到我們村子裡!', `MaleText_loc7`='¡Vuelve $gel joven héroe:la joven heroína;! Me alegra verte de nuevo, $n. Nos encanta que vengas a nuestra aldea.' WHERE `ID`=10270;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 난세에 보기 드문 친구로군. 한때 자네 같은 친구를 하나 알고 지냈지. 볼진이라고 했는데...', `MaleText_loc4`='我以前认识一个像你这样的……他叫沃金。你属于一个在这里很少见到的族群，我的朋友。', `MaleText_loc5`='我以前認識一個像你這樣的...他叫做沃金。你屬於一個少見的族群，我的朋友。', `MaleText_loc7`='Hace tiempo, conocí a alguien como tú... Se llamaba Vol''jin. No es fácil encontrar a tipos como tú, $gamigo:amiga;.' WHERE `ID`=10271;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멀고도 험난한 길을 걸어왔군. 우리 부족에서도 자네처럼 높은 지위를 얻은 자는 드물지. $n, 자네는 잔달라 제국의 위대한 벗일세.$B$B그래... 어쩌면, 전설이라고도 부를 수 있을지 몰라.', `MaleText_loc4`='真是漫长而艰辛的旅途啊。很少有谁能取得你这样的成就。你是赞达拉帝国的朋友，$n。$B$B传说中的，或许是……是的……或许。', `MaleText_loc5`='你所走的真是條漫長而艱辛的旅途啊。很少有誰能取得你這樣的成就。你是贊達拉帝國的朋友，$n。$B$B傳說中的，或許...是的...或許。', `MaleText_loc7`='El camino que has recorrido es largo, y duro. Muy pocos consiguen esa consideración en nuestras filas. Eres $gun gran amigo:una gran amiga; del Imperio Zandalar, $n.$B$BQuizás, hasta $glegendario:legendaria;... Sí... Quizás.' WHERE `ID`=10272;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알았어요.', `MaleText_loc4`='遵命，长官。', `MaleText_loc5`='遵命，長官。', `MaleText_loc7`='Ahora mismo, señor.' WHERE `ID`=10273;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아빠, 목걸이 만들 돌멩이 모으러 나가도 돼요?', `FemaleText_loc4`='爸爸，我能出去收集更多的石头做条项链吗？', `FemaleText_loc5`='爸爸，我能出去收集更多的石頭來做項鍊嗎?', `FemaleText_loc7`='¿Puedo ir a buscar más piedras para mi collar, papá?' WHERE `ID`=10274;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러거라, 오클라. 하지만 집에서 너무 멀리 떨어지면 안 돼요.', `MaleText_loc4`='当然，奥克拉。但是不要离家太远了。', `MaleText_loc5`='當然，奧克拉。但是不要離家太遠了。', `MaleText_loc7`='Puedes, Okla. Pero no te alejes demasiado de mí.' WHERE `ID`=10275;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다부! 조심할게요, 아빠!', `FemaleText_loc4`='好的！我会小心的，爸爸！', `FemaleText_loc5`='好的!我會小心的，爸爸!', `FemaleText_loc7`='¡Dabu! ¡Tendré cuidado, papá!' WHERE `ID`=10276;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='와아! 이 돌은 모양도 색깔도 정말 예쁘네. 이런 게 더 있나 어디 한번 볼까...', `FemaleText_loc4`='哦……这块漂亮的岩石。看看我能不能找到更多这样的石料……', `FemaleText_loc5`='哦...這塊石頭真是漂亮。看看我能不能找到更多這樣的石頭...', `FemaleText_loc7`='Ooohh... Esta piedra es bonita y me gusta mucho el color. A ver si puedo encontrar más iguales...' WHERE `ID`=10277;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='흠... 저 돌은 예쁜데 너무 작아.', `FemaleText_loc4`='嗯……那块石头很不错，但是太小了一点。', `FemaleText_loc5`='嗯...那塊石頭很不錯，但是太小了一點。', `FemaleText_loc7`='Mmm... Esa piedra es bonita, pero demasiado pequeña.' WHERE `ID`=10278;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='반짝거리는 돌이다! 바구니에 담아야지. 좋아. 이제 몇 개만 더 모으면...', `FemaleText_loc4`='这是块相当不错的岩石，我得把它放到桶里去。好啦，我还需要一些……', `FemaleText_loc5`='這是塊相當不錯的石頭，我得把它放到桶子裡去。好，我只需要再一些...', `FemaleText_loc7`='Una piedra brillante, la pondré en mi cesta. Vale, solo necesito algunas más...' WHERE `ID`=10279;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 돌은 창 만드는 친구한테 줘야겠다! 아주 날카로운 게... 그루크가 진짜 좋아 할거야.', `FemaleText_loc4`='这石料很适合制作长矛，我敢打赌，我的朋友格鲁克会喜欢的！非常锋利……希望他喜欢。', `FemaleText_loc5`='這石頭很適合拿來製作長矛，我敢打賭，我的朋友格魯克會喜歡的!非常鋒利...希望他會喜歡。', `FemaleText_loc7`='Seguro que a mi amigo Gruk le gustaría esta piedra para la lanza que está haciendo. Es muy afilada... Espero que le guste.' WHERE `ID`=10280;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭐... 이 정도면 목걸이 하나는 만들고도 남겠지. 얼른 집에 가야겠다.', `FemaleText_loc4`='那儿……那儿的石头足够做一条项链啦。无论如何，我现在得回家啦。', `FemaleText_loc5`='嗯...這些石頭應該足夠做一條項鍊啦。無論如何，我現在得回家啦。', `FemaleText_loc7`='Ya está... Con esto debería tener suficientes piedras para hacer un collar. De todas formas, ya debería volver a casa...' WHERE `ID`=10281;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 금광을 공격했습니다! 방어하지 못하면 1분 안에 얼라이언스에 넘어갈 것입니다!', `MaleText_loc4`='$n突袭了矿洞！如果不赶快采取行动的话，联盟将在1分钟内占据它！', `MaleText_loc5`='$n攻佔了礦坑!如果沒有其他人採取行動的話，聯盟將在1分鐘內控制它!', `MaleText_loc7`='¡$n reclama la mina! ¡Si nadie acepta el desafío, la Alianza la tomará en 1 minuto!' WHERE `ID`=10282;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 금광을 공격했습니다! 방어하지 못하면 1분 안에 호드에 넘어갈 것입니다!', `MaleText_loc4`='$n突袭了矿洞！如果不赶快采取行动的话，部落将在1分钟内占据它！', `MaleText_loc5`='$n攻佔了礦坑!如果沒有其他人採取行動的話，部落將在1分鐘內控制它!', `MaleText_loc7`='¡$n reclama la mina! ¡Si nadie acepta el desafío, la Horda la tomará en 1 minuto!' WHERE `ID`=10283;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 제재소를 공격했습니다! 방어하지 못하면 1분 안에 얼라이언스에 넘어갈 것입니다!', `MaleText_loc4`='$n突袭了伐木场！如果不赶快采取行动的话，联盟将在1分钟内占据它！', `MaleText_loc5`='$n攻佔了伐木場!如果沒有其他人採取行動的話，聯盟將在1分鐘內控制它!', `MaleText_loc7`='¡$n reclama el aserradero! ¡Si nadie acepta el desafío, la Alianza la controlará en un minuto!' WHERE `ID`=10284;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 제재소를 공격했습니다! 방어하지 못하면 1분 안에 호드에 넘어갈 것입니다!', `MaleText_loc4`='$n突袭了伐木场！如果不赶快采取行动的话，部落将在1分钟内占据它！', `MaleText_loc5`='$n攻佔了伐木場!如果沒有其他人採取行動的話，部落將在1分鐘內控制它!', `MaleText_loc7`='¡$n reclama el aserradero! ¡Si nadie acepta el desafío, la Horda lo tomará en 1 minuto!' WHERE `ID`=10285;
