UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 대장간을 공격했습니다! 방어하지 못하면 1분 안에 호드에 넘어갈 것입니다!', `MaleText_loc4`='$n突袭了铁匠铺！如果不赶快采取行动的话，部落将在1分钟内占据它！', `MaleText_loc5`='$n攻佔了鐵匠舖!如果沒有其他人採取行動的話，部落將在1分鐘內控制它!', `MaleText_loc7`='¡$n reclama la herrería! ¡Si nadie acepta el desafío, la Horda la tomará en 1 minuto!' WHERE `ID`=10291;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 맛있어. 초원타조 구이는 정말 최고라니까.', `FemaleText_loc4`='嗯，我喜欢吃烤陆行鸟！', `FemaleText_loc5`='真好吃，我喜歡烤陸行鳥!', `FemaleText_loc7`='Mmmmm. Me encanta el zancudo de la llanura asado.' WHERE `ID`=10292;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='열심히 수련해서 아빠처럼 용감한 전사가 될 테야!', `MaleText_loc4`='我要开始训练，成为我父亲那样的战士！', `MaleText_loc5`='我要開始訓練，成為我父親那樣的戰士!', `MaleText_loc7`='Voy a practicar y a convertirme en guerrero, ¡como mi padre!' WHERE `ID`=10293;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디... 넋 놓고 있는 하피나 찾아볼까!', `MaleText_loc4`='去找一个鹰身人！', `MaleText_loc5`='去找一個鷹身人!', `MaleText_loc7`='¡Ahora, voy a buscar a una arpía desprevenida!' WHERE `ID`=10294;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기 한 마리 있다! 호드를 위하여!', `MaleText_loc4`='那儿！为了部落！', `MaleText_loc5`='那兒有一個!為了部落!', `MaleText_loc7`='¡Ahí hay una! ¡Por la Horda!' WHERE `ID`=10295;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='받아랏, 더러운 하피 녀석! 이얍!', `MaleText_loc4`='看招，你们这些白痴鹰身人！哈哈！', `MaleText_loc5`='看招，你們這些卑鄙的鷹身人!哈哈!', `MaleText_loc7`='¡Toma eso, asquerosa arpía! ¡Síiiii!' WHERE `ID`=10296;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드의 용감한 전사한테서 절대 도망 못가지롱! 받아랏! 얏!', `MaleText_loc4`='你是无法从部落战士手中逃脱的！看招！嘿哈！', `MaleText_loc5`='你是無法從部落戰士手中逃脫的!吃我一招!還有這招!', `MaleText_loc7`='¡No puedes escaparte de un guerrero de la Horda! ¡Toma esto! ¡Y esto!' WHERE `ID`=10297;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너네 집으로 꺼져라!', `MaleText_loc4`='回到属于你们自己的地方去！', `MaleText_loc5`='回到屬於你自己的地方去!', `MaleText_loc7`='Y ahora, vuelve a casa, donde tienes que estar.' WHERE `ID`=10298;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와우... 또다시 호드에 영광스러운 승리다!', `MaleText_loc4`='啊……部落的又一次荣耀的胜利！', `MaleText_loc5`='啊...部落又一次光榮的勝利!', `MaleText_loc7`='Aaahhh... ¡Otra gloriosa victoria para la Horda!' WHERE `ID`=10299;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='모그! 아가야... 어서 들어오렴. 아버지도 안 계신데 바깥을 돌아다니는 건 위험해요.', `FemaleText_loc4`='莫戈恩，到里面去。你父亲不在了，外面可不太平。', `FemaleText_loc5`='摩戈，到裡面去。你父親不在的時候，外面可是不太安全的。', `FemaleText_loc7`='Mogg, entra. No es seguro que estés ahí fuera mientras tu padre no está.' WHERE `ID`=10300;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 엄마! 지금 가요.', `MaleText_loc4`='马上，妈妈！', `MaleText_loc5`='馬上，媽媽!', `MaleText_loc7`='¡Ahora mismo, mamá!' WHERE `ID`=10301;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아빠는 전쟁노래 협곡에서 언제 돌아오시는 거예요? 가신지 한참 됐는데...', `MaleText_loc4`='爸爸什么时候才能从战歌峡谷回来呢？他离开很久啦……', `MaleText_loc5`='爸爸什麼時候才能從戰歌峽谷回來呢?他離開好久了...', `MaleText_loc7`='¿Cuándo vuelve papá de las luchas en Grito de Guerra? Hace mucho tiempo ya...' WHERE `ID`=10303;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='금방 오실 거야. 금방...', `FemaleText_loc4`='不久之后，孩子……不久之后。', `FemaleText_loc5`='快了，孩子...就快了。', `FemaleText_loc7`='Pronto, pequeño... Muy pronto.' WHERE `ID`=10304;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잉? 우리 돼지들한테 무슨 일이 있었던 거지?', `FemaleText_loc4`='我们的猪出什么事了？', `FemaleText_loc5`='我們的豬有什麼問題嗎?', `FemaleText_loc7`='¿Qué ha pasado con nuestros cerdos?' WHERE `ID`=10305;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경비병. 포로를 데려와라. 구속의 마법진에 넣도록!', `MaleText_loc4`='守卫，将囚犯带上来。把他带到禁锢法阵中。', `MaleText_loc5`='守衛，將囚犯帶上來。把他帶到禁錮法陣中。', `MaleText_loc7`='Guardia, trae al prisionero. Colócale en el Círculo de Vínculo.' WHERE `ID`=10306;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 당장 시행하라!', `MaleText_loc4`='立刻就办。', `MaleText_loc5`='立刻就辦。立刻就去。', `MaleText_loc7`='Ahora mismo, Siervo.' WHERE `ID`=10307;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빨리 움직여!', `MaleText_loc4`='快点！', `MaleText_loc5`='快點!', `MaleText_loc7`='¡Muévete!' WHERE `ID`=10308;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이교도여, 무릎을 꿇어라.', `MaleText_loc4`='跪下，异教徒。', `MaleText_loc5`='跪下，異教徒。', `MaleText_loc7`='Arrodíllate, pagano.' WHERE `ID`=10309;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이상하군. 학카르의 언어를 모르는 라스타칸의 종복이 왜 고대 트롤어를 할 줄 모른단 말인가?', `MaleText_loc4`='奇怪。一个对哈卡一无所知的拉斯塔哈的仆从竟然不用古语交谈？', `MaleText_loc5`='奇怪。一個對哈卡萊一無所知的拉斯塔哈的僕從竟然不用古語交談?', `MaleText_loc7`='Qué curioso... ¿Un Siervo de Rastakhan que no sabe que los Hakkari no hablan en la lengua antigua?' WHERE `ID`=10310;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무릎을 꿇으라 했다!', `MaleText_loc4`='跪下！', `MaleText_loc5`='我叫你跪下!', `MaleText_loc7`='¡He dicho que te arrodilles!' WHERE `ID`=10311;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 누군지 알겠느냐, 광신도?', `MaleText_loc4`='你知道我是谁吗，狂热者？', `MaleText_loc5`='你知道我是誰嗎，狂熱者?', `MaleText_loc7`='¿Sabes quién soy, zelote?' WHERE `ID`=10312;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바보... 넌 곧 목숨을 잃을 것이다.', `MaleText_loc4`='你是个蠢货，一个很快就要死掉的蠢货。不是吗？', `MaleText_loc5`='你是個蠢貨，一個很快就要死掉的蠢貨。不是嗎?', `MaleText_loc7`='Eres un imbécil a punto de perder su vida. ¿No?' WHERE `ID`=10313;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='손가락 하나라도 까딱하면 널 뭉개버릴 수 있다. 날 화나게 하지 마라.', `MaleText_loc4`='我只需要动动手指就让你知道我的厉害。不要惹我。', `MaleText_loc5`='我只需要動動手指就可以讓你粉身碎骨。不要惹我生氣。', `MaleText_loc7`='Podría aplastarte con solo un movimiento. No hagas que me enfade.' WHERE `ID`=10314;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 비웃습니다.', `MaleText_loc4`='%s笑了。', `MaleText_loc5`='%s大笑。', `MaleText_loc7`='%s ríe.' WHERE `ID`=10315;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가소롭구나. 나는 영혼약탈자 학카르 님의 힘을 받았다. 내가 두려워하는 건 위대하신 학카르 님의 분노밖에 없다. 나는 진 님만을 섬기는 충실한 종이다.', `MaleText_loc4`='真可悲。夺灵者的力量与我同在，除了哈卡神的愤怒，我一无所惧。我只效忠于我真正的主人。', `MaleText_loc5`='真可悲。奪魂者的力量與我同在，除了哈卡神的憤怒，我一無所懼。我只效忠於我真正的主人，金恩。', `MaleText_loc7`='Qué patético. Me ha sido otorgado el poder del Cazador de Almas. Lo único que temo es la ira del poderoso Hakkar. No sirvo a nadie que no sea mi maestro, Jin.' WHERE `ID`=10316;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='학카르가 환생했다는 말이냐?', `MaleText_loc4`='那么说来哈卡回来了？', `MaleText_loc5`='那麼說來哈卡回來了?', `MaleText_loc7`='Entonces, ¿Hakkar ha vuelto?' WHERE `ID`=10317;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그걸 꼭 물어봐야 하나? 그분을 느낄 수 없단 말이냐? 그 잘난 라스타칸이 외교나 하라고 종복과 대리인을 여기로 보냈단 말인가?', `MaleText_loc4`='这还需要问吗？你感觉不到他吗？万能的拉斯塔哈派遣他的仆从来此是执行外交任务的吗？', `MaleText_loc5`='這還需要問嗎?你感覺不到他嗎?難道萬能的拉斯塔哈王派遣他的僕從跟左右手來此是執行外交任務的嗎?', `MaleText_loc7`='¿Necesitas preguntarlo? ¿No puedes sentirle? ¿Acaso el poderoso rey Rastakhan ha enviado a su Siervo y a su Mano aquí en una misión de diplomacia?' WHERE `ID`=10318;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론이다. 학카르 님께서 환생하셨다. 곧 그분의 위력 아래 온 세상이 무너질 것이다. 모두 파괴되어 폐허만이 남겠지...', `MaleText_loc4`='哦，老家伙，哈卡已经回来了。很快这个世界就会在他的强大力量下崩溃。毁灭。毁灭……', `MaleText_loc5`='哦，是的，老傢伙，哈卡回來了。很快這個世界就會在他的強大力量下崩潰。吞蝕。灰飛煙滅...', `MaleText_loc7`='Oh sí, viejo, Hakkar ha regresado. Pronto, el mundo se derrumbará bajo su poder. Se consumirá. Solo quedarán cenizas...', `FemaleText_loc1`='물론이다. 학카르 님께서 환생하셨다. 곧 그분의 위력 아래 온 세상이 무너질 것이다. 모두 파괴되어 폐허만이 남겠지...', `FemaleText_loc4`='哦，老家伙，哈卡已经回来了。很快这个世界就会在他的强大力量下崩溃。毁灭。毁灭……', `FemaleText_loc5`='哦，是的，老傢伙，哈卡回來了。很快這個世界就會在他的強大力量下崩潰。吞蝕。灰飛煙滅...', `FemaleText_loc7`='Oh sí, viejo, Hakkar ha regresado. Pronto, el mundo se derrumbará bajo su poder. Se consumirá. Solo quedarán cenizas...' WHERE `ID`=10319;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 절대로 가만히 있지 않을 것이다... 예전에 그를 이 세상에서 추방한 것처럼 이번에도 막아낼 거야.', `MaleText_loc4`='我们不会让这种事发生的……我们以前曾经放逐过他，我们会再次放逐他的。', `MaleText_loc5`='我們不會讓這種事發生的...我們以前曾經放逐過他，我們會再次放逐他的。', `MaleText_loc7`='Nunca lo permitiremos... Ya le hemos desterrado de nuestro mundo y lo haremos de nuevo.' WHERE `ID`=10320;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 미친 듯이 웃습니다.', `MaleText_loc4`='%s发疯似的笑起来。', `MaleText_loc5`='%s瘋狂地笑著。', `MaleText_loc7`='%s ríe con locura.' WHERE `ID`=10321;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어리석은 녀석! 전성기 때 힘이 십분의 일이라도 남아있느냐? 그때 모든 종족들이 단결했지만 학카르 님은 그림자만으로도 모든 걸 덮어버릴 수도 있었다. 네놈들에게 승리란 없어.', `MaleText_loc4`='愚蠢！你以为自己还拥有大暴动时期的哪怕十分之一的力量吗？所有的部族共同作战，却几乎全部被哈卡的阴影所吞噬。你是没有机会的。', `MaleText_loc5`='愚蠢!你以為自己還擁有全盛時期時，十分之一的力量嗎?當時所有的部族共同作戰，卻幾乎全被哈卡的一個影子所吞噬。你是沒有機會的。', `MaleText_loc7`='¡IMBÉCIL! ¿Pretendes tener tan siquiera una décima parte del poder que tenías durante el Alzamiento? Las naciones estaban unidas y, aun así, fueron casi consumidas por completo por una sombra de Hakkar. No tienes ninguna oportunidad.' WHERE `ID`=10322;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='게다가 예전에 너희 동맹이었던 종족들도 이제는 우리에게 합류했지... 그래, 늙은이. 그렇게 놀란 눈으로 볼 거 없어.', `MaleText_loc4`='现在，那些曾与你们结为盟友的部族已经背弃了你们，与我们站在了一起……没错，老家伙，别那么惊讶。', `MaleText_loc5`='現在，那些曾與你們結為盟友的部族已經背棄了你們，與我們站在了一起...沒錯，老傢伙，別那麼驚訝。', `MaleText_loc7`='Y, ahora, hasta esas naciones que habrías llamado aliadas han retrocedido y han unido fuerzas con nosotros... Sí, $gviejo:vieja;, no pongas cara de sorpresa.' WHERE `ID`=10323;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='붉은머리 부족, 성난모래 부족, 백골가루 부족, 썩은가지 부족, 그리고 마른나무껍질 부족... 모두 진 님께 충성을 맹세하고 자신들의 영혼을 학카르 님께 바쳤다. 너희에게는 패배만이 남아 있다.', `MaleText_loc4`='血顶、沙怒、劈颅、邪枝和枯木。他们都发誓效忠我们——他们的灵魂与哈卡同在。你已经输了。', `MaleText_loc5`='血頂、沙怒、劈顱、邪枝和枯木。他們都發誓效忠我們─他們的靈魂與哈卡同在。你已經輸了。', `MaleText_loc7`='Sangrapellejo, Furiarena, Machacacráneos, Vilrama y Secacorteza. Todos dicen ser aliados de Jin. Sus almas pertenecen a Hakkar. Has perdido.' WHERE `ID`=10324;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시대는 변했다. 신흥 종족들이 우리에게 합류할 것이야. 네놈들의 사악한 음모는 절대 성공하지 못한다.', `MaleText_loc4`='时代不同了。年轻的一代将会加入我们。你永远都无法成功。', `MaleText_loc5`='時代不同了。年輕的一代將會加入我們。你永遠都無法成功。', `MaleText_loc7`='Los tiempos han cambiado. Las razas jóvenes se unirán a nosotros. Nunca tendrás éxito.' WHERE `ID`=10325;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신흥 종족? 그 젖먹이들 말인가? 인간? 오크? 드워프? 그들이 학카르 부족을 물리칠 거라 기대하는 거냐? 감히 신을 처치하겠다고?', `MaleText_loc4`='年轻的一代？婴儿？人类？兽人？矮人？你想要击败哈卡？你要击败一个神？', `MaleText_loc5`='年輕的一代?嬰兒?人類?獸人?矮人?你想要擊敗哈卡萊?你想要擊敗一個神?', `MaleText_loc7`='¿Las razas jóvenes? ¿Los infantes? ¿Humanos? ¿Orcos? ¿Enanos? ¿Esperas derrotar a los Hakkari? ¿Destruir a un DIOS?' WHERE `ID`=10326;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런 일은 절대로 일어날 리가 없다. 우리의 엄청난 병력은 단결되어 있어. 지금 너희에게 영웅은 어디 있느냐? 볼진은 아무것도 모른 채 새파란 대족장의 곁에 머물러 있고 줄진은 실종됐다. 아마 죽었겠지.', `MaleText_loc4`='绝不能发生这种事儿。我们是一支庞大的军团。我们团结一致。你的英雄在哪儿？沃金毫无知觉地陪在年轻的部落酋长身边。祖尔金失踪了，或许已经死了。', `MaleText_loc5`='絕不能發生這種事情。我們是一支龐大的軍團。我們團結一致。你的英雄們在哪兒?沃金毫無知覺地陪在年輕的大酋長身邊。祖爾金失蹤了，或許已經死了。', `MaleText_loc7`='NUNCA ocurrirá. Somos la Legión. Estamos unidos. ¿Dónde están tus héroes? Vol''jin está en el santuario al lado del joven Jefe de Guerra, sin saberlo. Zul''jin desaparecido, probablemente muerto.' WHERE `ID`=10327;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고... 설마 고대 신에게 이길 거라 기대하는 거냐?', `MaleText_loc4`='嗯……你想要打败狂野之神吗？', `MaleText_loc5`='嗯...你想要打敗原始神靈嗎?', `MaleText_loc7`='Y... ¿Esperas vencer a los dioses primigenios?' WHERE `ID`=10328;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 아니꼬운 듯 비웃습니다.', `MaleText_loc4`='%s傻笑着。', `MaleText_loc5`='%s奸笑著。', `MaleText_loc7`='%s sonríe con ironía.' WHERE `ID`=10329;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고대 신이라고? 말도 안 돼!', `MaleText_loc4`='狂野之神？不可能！', `MaleText_loc5`='原始神靈?不可能!', `MaleText_loc7`='¿Los dioses primigenios? ¡Imposible!' WHERE `ID`=10330;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래? 어디 한번 불러봐라, 종복 녀석...', `MaleText_loc4`='是吗？召唤他们出来啊？', `MaleText_loc5`='是嗎?召喚他們出來吧，僕從。', `MaleText_loc7`='¿En serio? Llámalos, Siervo.' WHERE `ID`=10331;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 엄지를 들었다가 아래로 내리는 시늉을 합니다.', `MaleText_loc4`='%s用食指在脖子上比划了一个砍头的动作。', `MaleText_loc5`='%s用食指在脖子上比了一個砍頭的動作。', `MaleText_loc7`='%s usa su dedo índice para hacer el gesto de cortar el cuello.' WHERE `ID`=10332;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희의 신은 어디에 있느냐? 어디 있느냔 말이다!', `MaleText_loc4`='你的神在哪里？在哪里？！', `MaleText_loc5`='你的神在哪裡?在哪裡，僕從?', `MaleText_loc7`='¿Dónde están tus dioses ahora? ¿DÓNDE, SIERVO?' WHERE `ID`=10333;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 쓰러뜨려라. 다시 태어날 테니... 더욱 강해질 테니까...', `MaleText_loc4`='打倒我吧。我会重生的……变得更强大……', `MaleText_loc5`='打倒我吧。我會重生...變得更加強大...', `MaleText_loc7`='Mátame. Renaceré... Incluso más poderoso...' WHERE `ID`=10334;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 어깨를 떨구고 고개를 숙입니다.', `MaleText_loc4`='%s垂下肩膀，伸出脖子。', `MaleText_loc5`='%s垂下肩膀，伸長了他的脖子。', `MaleText_loc7`='%s baja los hombros y deja su cuello al descubierto.' WHERE `ID`=10335;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 쓰러진 광신도의 시체에 침을 뱉습니다.', `MaleText_loc4`='%s对着狂热者的尸体吐口水。', `MaleText_loc5`='%s對著狂熱者的屍體吐了口口水。', `MaleText_loc7`='%s escupe sobre el cadáver del zelote caído.' WHERE `ID`=10336;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전자 쿠폰 코드를 입력하고 가상 아이템을 받고 싶습니다.', `MaleText_loc4`='我要输入10位电子兑换券号码，赢取我的奖品！', `MaleText_loc5`='我要輸入我的電子兌換券認證碼，以贏取我的寵物!', `MaleText_loc7`='Me gustaría introducir mi e-cupón para ganar el objeto virtual.', `FemaleText_loc1`='전자 쿠폰 코드를 입력하고 가상 아이템을 받고 싶습니다.', `FemaleText_loc4`='我要输入10位电子兑换券号码，赢取我的奖品！', `FemaleText_loc5`='我要輸入我的電子兌換券認證碼，以贏取我的寵物!', `FemaleText_loc7`='Me gustaría introducir mi e-cupón para ganar el objeto virtual.' WHERE `ID`=10337;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='iCoke-WOW 여름 이벤트 참여를 환영합니다.$B$B친애하는 $n|1이여;여;, 행운의 여신이 당신에게 후광을 드리우고 있습니다. 신의 명을 받들면 특별한 깜짝 선물을 받게 될 것입니다. 자, 아제로스의 문은 당신 앞에 열려있고 곧 대모험이 시작될 겁니다. 준비는 되셨나요?$B$B명예가 당신과 함께하기를!', `MaleText_loc4`='魔兽世界和可口可乐(R)共同为您带来了这次可口可乐魔兽世界“要爽由自己，冰火暴风城II”夏季促销活动。请检查魔兽世界主题的可口可乐易拉罐底部或瓶装可口可乐的瓶盖内侧，您可以找到一串13位字符。在www.iCoke.cn上输入您得到的13位字符，就有机会赢得iCoke积分，从而得到可以换取魔兽世界幸运礼品的10位电子兑换券。最后，在这里输入您得到的电子兑换券上的10位号码，神秘大奖在等待着您！', `MaleText_loc5`='歡迎來到可口可樂-魔獸世界特別活動!$B$B親愛的$n，幸運之神就在您身旁!只要你跟著神的指引，您就能獲得一份非常神秘又特別的禮物!現在，艾澤拉斯之門即將為你而開。無數的驚奇冒險正在等著你!您準備好了嗎?$B$B為了榮耀而戰吧!', `MaleText_loc7`='¡Te doy la bienvenida a la promoción de verano de iCoke-WOW!$B$B$gQuerido:querida; $n, el halo de la diosa fortuna está brillando sobre ti. Obedece la orden de un dios. Obtendrás un regalo especial y misterioso. Ahora, la puerta de Azeroth se ha abierto para ti. Pronto comenzará una gran aventura. ¿$gPreparado:preparada;?$B$B¡Que el honor esté contigo!', `FemaleText_loc1`='iCoke-WOW 여름 이벤트 참여를 환영합니다.$B$B친애하는 $n|1이여;여;, 행운의 여신이 당신에게 후광을 드리우고 있습니다. 신의 명을 받들면 특별한 깜짝 선물을 받게 될 것입니다. 자, 아제로스의 문은 당신 앞에 열려있고 곧 대모험이 시작될 겁니다. 준비는 되셨나요?$B$B명예가 당신과 함께하기를!', `FemaleText_loc4`='魔兽世界和可口可乐(R)共同为您带来了这次可口可乐魔兽世界“要爽由自己，冰火暴风城II”夏季促销活动。请检查魔兽世界主题的可口可乐易拉罐底部或瓶装可口可乐的瓶盖内侧，您可以找到一串13位字符。在www.iCoke.cn上输入您得到的13位字符，就有机会赢得iCoke积分，从而得到可以换取魔兽世界幸运礼品的10位电子兑换券。最后，在这里输入您得到的电子兑换券上的10位号码，神秘大奖在等待着您！', `FemaleText_loc5`='歡迎來到可口可樂-魔獸世界特別活動!$B$B親愛的$n，幸運之神就在您身旁!只要你跟著神的指引，您就能獲得一份非常神秘又特別的禮物!現在，艾澤拉斯之門即將為你而開。無數的驚奇冒險正在等著你!您準備好了嗎?$B$B為了榮耀而戰吧!', `FemaleText_loc7`='¡Te doy la bienvenida a la promoción de verano de iCoke-WOW!$B$B$gQuerido:querida; $n, el halo de la diosa fortuna está brillando sobre ti. Obedece la orden de un dios. Obtendrás un regalo especial y misterioso. Ahora, la puerta de Azeroth se ha abierto para ti. Pronto comenzará una gran aventura. ¿$gPreparado:preparada;?$B$B¡Que el honor esté contigo!' WHERE `ID`=10338;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 구스가 가신다! 스톰파이크 쓰레기들을 정리할 때다!', `FemaleText_loc4`='古斯加入战斗！让我们灭了雷矛的那帮渣子！', `FemaleText_loc5`='古斯加入戰鬥了!讓我們滅了雷矛的那幫雜碎!', `FemaleText_loc7`='¡Guse se une a la batalla! ¡Ya es hora de acabar con la escoria Pico Tormenta!' WHERE `ID`=10339;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='명령 대기 중입니다!', `FemaleText_loc4`='整装待命！', `FemaleText_loc5`='整裝待命!', `FemaleText_loc7`='¡Esperando órdenes!' WHERE `ID`=10340;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구스 사령관, 때가 왔소! 다시 한번 불꽃 비행을 할 때가!', `MaleText_loc4`='就是现在，古斯。你要再次展翅高飞！', `MaleText_loc5`='就是現在，古斯。再次展翅高飛吧!', `MaleText_loc7`='Ha llegado la hora, Guse. ¡Vuelas de nuevo!', `FemaleText_loc1`='구스 사령관, 때가 왔소! 다시 한번 불꽃 비행을 할 때가!', `FemaleText_loc4`='就是现在，古斯。你要再次展翅高飞！', `FemaleText_loc5`='就是現在，古斯。再次展翅高飛吧!', `FemaleText_loc7`='Ha llegado la hora, Guse. ¡Vuelas de nuevo!' WHERE `ID`=10341;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나 제스톨이 간다, 이 스톰파이크 녀석들!', `FemaleText_loc4`='杰斯托来了，雷矛的渣滓们！', `FemaleText_loc5`='傑斯托來了，雷矛的雜碎們!', `FemaleText_loc7`='¡Jeztor va por ustedes, Pico Tormenta!' WHERE `ID`=10342;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 제즈톨은 건재하다! 다시 한번 알터랙 계곡의 상공을 밝힐 때가 왔다!', `MaleText_loc4`='杰斯托还活着！指挥官，是照亮山谷的时候了。', `MaleText_loc5`='傑斯托還活著!指揮官，是照亮山谷天空的時候了。', `MaleText_loc7`='¡Jeztor está vivo! Vamos a encender el cielo del valle, Comandante.', `FemaleText_loc1`='나 제즈톨은 건재하다! 다시 한번 알터랙 계곡의 상공을 밝힐 때가 왔다!', `FemaleText_loc4`='杰斯托还活着！指挥官，是照亮山谷的时候了。', `FemaleText_loc5`='傑斯托還活著!指揮官，是照亮山谷天空的時候了。', `FemaleText_loc7`='¡Jeztor está vivo! Vamos a encender el cielo del valle, Comandante.' WHERE `ID`=10343;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n, 출격 명령을 내려주십시오! 말씀만 하시면 당장 하늘로 올라가 놈들의 다리를 공격하겠습니다!', `FemaleText_loc4`='让我来对付他们，$n！只要一声令下，我就会冲出去攻击他们的大桥！', `FemaleText_loc5`='讓我來對付他們，$n!只要一聲令下，我就會衝出去攻擊他們的大橋!', `FemaleText_loc7`='¡Yo me encargaré, $n! Da la orden y subiré para atacar su puente.' WHERE `ID`=10344;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비 완료입니다! 명령만 내리시면 놈들의 요새에 지옥 불을 떨어뜨리겠습니다!', `MaleText_loc4`='我准备好了，先生！只要你一声令下，我将会把地狱火倾泻在他们的基地上！', `MaleText_loc5`='我準備好了，先生!只要你一聲令下，我就會把地獄火傾瀉在他們的基地上!', `MaleText_loc7`='¡Estoy listo, señor! Da la orden y el infierno caerá en forma de proyectil sobre su base.' WHERE `ID`=10345;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멀베릭 사령관, 출격하고 싶소? 정녕 전쟁을 도발하고 싶소? 명령을 내리기 전에 먼저 얼마나 원하는지 알고 싶소이다. 흠, 물어볼 필요도 없는 거겠지? 그러면 당장 출격하시오!', `MaleText_loc4`='穆维里克，你感觉到了吗？需求？在我下达命令之前你就该有所需求了。我可没跟你开玩笑。滚出去！', `MaleText_loc5`='穆維里克，你感覺到了嗎?需求?在我下達命令之前你就該有所需求了。我可沒跟你開玩笑。滾出去!', `MaleText_loc7`='¿La sientes, Mulv? ¿La necesidad? Tienes que quererlo antes de poder darte la orden. A quién quiero engañar... ¡Sal ahí fuera!', `FemaleText_loc1`='멀베릭 사령관, 출격하고 싶소? 정녕 전쟁을 도발하고 싶소? 명령을 내리기 전에 먼저 얼마나 원하는지 알고 싶소이다. 흠, 물어볼 필요도 없는 거겠지? 그러면 당장 출격하시오!', `FemaleText_loc4`='穆维里克，你感觉到了吗？需求？在我下达命令之前你就该有所需求了。我可没跟你开玩笑。滚出去！', `FemaleText_loc5`='穆維里克，你感覺到了嗎?需求?在我下達命令之前你就該有所需求了。我可沒跟你開玩笑。滾出去!', `FemaleText_loc7`='¿La sientes, Mulv? ¿La necesidad? Tienes que quererlo antes de poder darte la orden. A quién quiero engañar... ¡Sal ahí fuera!' WHERE `ID`=10346;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='던 발다르에 전투와이번 편대가 나가신다! 살고 싶으면 항복해라, 스톰파이크 놈들아!', `MaleText_loc4`='丹巴达尔来了增援的空中部队！', `MaleText_loc5`='丹巴達爾來了增援的空中部隊!', `MaleText_loc7`='¡Apoyo aéreo entrante a Dun Baldar! ¡Pico Tormenta, doblegaos!' WHERE `ID`=10347;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사령관님, 비행 준비 완료입니다. 명령만 내리시면 트로그가 바위를 깨부수듯이 놈들의 요새를 쳐부수겠습니다.', `MaleText_loc4`='我准备好飞行了，指挥官。只需要你一声令下，我就去把他们的基地夷为平地。', `MaleText_loc5`='我準備好出發了，指揮官。只需要你一聲令下，我就去把他們的基地夷為平地。', `MaleText_loc7`='Listo para volar, Comandante. Da la orden y estaré sobre su base como un trogg a motor.' WHERE `ID`=10348;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='편대는 요새로 출격하시오. 우리는 지상에서 공격하겠소.', `MaleText_loc4`='拿下这座基地。我们要开始攻城。', `MaleText_loc5`='拿下這座基地。我們準備從地面攻城。', `MaleText_loc7`='Toma la base. Asediaremos desde la tierra.', `FemaleText_loc1`='편대는 요새로 출격하시오. 우리는 지상에서 공격하겠소.', `FemaleText_loc4`='拿下这座基地。我们要开始攻城。', `FemaleText_loc5`='拿下這座基地。我們準備從地面攻城。', `FemaleText_loc7`='Toma la base. Asediaremos desde la tierra.' WHERE `ID`=10349;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사령관님, 명령만 내리시면 즉시 출발하겠습니다! 서리늑대 요새까지 이르는 경로를 정찰하겠습니다.', `MaleText_loc4`='我会在去霜狼要塞的路上巡逻。只要你一声令下，我就起飞，指挥官。', `MaleText_loc5`='我會在通往霜狼要塞的路上巡邏。只要你一聲令下，我就可以起飛，指揮官。', `MaleText_loc7`='Patrullaré por el paso que lleva al Bastión Lobo Gélido. Da la orden y subiré a los cielos, Comandante.' WHERE `ID`=10350;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실도르 사령관, 정확한 공격을 부탁하오. 길을 온통 불 지뢰로 깔아버리시오!', `MaleText_loc4`='我要你进行外科手术式的精确打击，斯里多尔。把这条路炸平！', `MaleText_loc5`='我要一場迅速而準確的空襲，斯里多爾。把這條路炸平!', `MaleText_loc7`='Quiero un ataque letal y absoluto, Slidore. ¡Cubrid de fuego el camino!', `FemaleText_loc1`='실도르 사령관, 정확한 공격을 부탁하오. 길을 온통 불 지뢰로 깔아버리시오!', `FemaleText_loc4`='我要你进行外科手术式的精确打击，斯里多尔。把这条路炸平！', `FemaleText_loc5`='我要一場迅速而準確的空襲，斯里多爾。把這條路炸平!', `FemaleText_loc7`='Quiero un ataque letal y absoluto, Slidore. ¡Cubrid de fuego el camino!' WHERE `ID`=10351;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사령관님, 명령만 내리십시오. 놈들 요새의 반을 완전히 부숴버리겠습니다.', `MaleText_loc4`='指挥官，发号令吧。我会彻底粉碎他们的基地！', `MaleText_loc5`='指揮官，發號施令吧。我會徹底粉碎他們的基地!', `MaleText_loc7`='Haz la llamada, Comandante. Destrozaré la parte inferior de su base.' WHERE `ID`=10352;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비포르 사령관, 전략적으로 공중 사격을 개시하여 적을 제압하시오. 시원하게 왕창 갈기는 거요.', `MaleText_loc4`='需要战术性压制火力，维波里。火力再猛一些。', `MaleText_loc5`='需要戰術性壓制火力，維波里。火力再猛一些。', `MaleText_loc7`='Fuego táctico de supresión, Vipore. A dolor.', `FemaleText_loc1`='비포르 사령관, 전략적으로 공중 사격을 개시하여 적을 제압하시오. 시원하게 왕창 갈기는 거요.', `FemaleText_loc4`='需要战术性压制火力，维波里。火力再猛一些。', `FemaleText_loc5`='需要戰術性壓制火力，維波里。火力再猛一些。', `FemaleText_loc7`='Fuego táctico de supresión, Vipore. A dolor.' WHERE `ID`=10353;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$c|1이여;여;, 어서 오세요. 전쟁노래 협곡에서 힘겨운 싸움을 하고 있는 은빛날개 파수대를 도우러 오셨나요?', `FemaleText_loc4`='你好，$c。你愿意帮助战歌峡谷的银翼哨兵作战吗？', `FemaleText_loc5`='你好，$c。你願意幫助戰歌峽谷的銀翼哨兵作戰嗎?', `FemaleText_loc7`='Saludos, $c. ¿Quieres ayudar a los centinelas Ala de Plata en su lucha en la Garganta Grito de Guerra?' WHERE `ID`=10354;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전장에 입장하고 싶습니다.', `MaleText_loc4`='我想去战场。', `MaleText_loc5`='我想去戰場。', `MaleText_loc7`='Me gustaría ir al campo de batalla.', `FemaleText_loc1`='전장에 입장하고 싶습니다.', `FemaleText_loc4`='我想去战场。', `FemaleText_loc5`='我想去戰場。', `FemaleText_loc7`='Me gustaría ir al campo de batalla.' WHERE `ID`=10355;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 몸이 가신다, 서리늑대 야만인들아! 뜨거운 맛을 보여주마!', `MaleText_loc4`='我来了，霜狼的渣滓们，这次让你们尝尝火焰的滋味！', `MaleText_loc5`='我來了，霜狼的雜碎們，這次讓你們嘗嘗火焰的滋味!', `MaleText_loc7`='¡Ya voy, Lobo Gélido, y esta vez vas a sentir las llamas!' WHERE `ID`=10356;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선임 편대사령관 비포르 출격 중... 서리늑대여, 고통 없는 죽음만을 기도하라.', `MaleText_loc4`='高级空军指挥官维波里，进攻。霜狼氏族，准备受死吧。', `MaleText_loc5`='高級空軍指揮官維波里，升空。霜狼氏族，準備受死吧。', `MaleText_loc7`='Comandante jefe del aire Vipore, aterrizando. Reza por una muerte rápida, Lobo Gélido.' WHERE `ID`=10357;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드렉타르 이놈! 기다려라, 이몸이 나가신다!', `MaleText_loc4`='德雷克塔尔，我来了！', `MaleText_loc5`='德雷克塔爾，我來了!', `MaleText_loc7`='¡Drek''Thar, voy a por ti!' WHERE `ID`=10358;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투모병관', `MaleText_loc4`='战场军官', `MaleText_loc5`='戰場軍官', `MaleText_loc7`='Maestro de batalla', `FemaleText_loc1`='전투모병관', `FemaleText_loc4`='战场军官', `FemaleText_loc5`='戰場軍官', `FemaleText_loc7`='Maestro de batalla' WHERE `ID`=10359;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='엘룬께 영광을! 전쟁노래 협곡 전투모병관을 찾는 건가요? 그녀의 이름은 애살라스이며 상급 전사들 곁에서 그대를 기다리고 있을 겁니다.', `FemaleText_loc4`='赞美月神！你在寻找我们的战歌峡谷军官？她的名字叫做伊萨拉斯，她就在战士训练师的旁边等着你。', `FemaleText_loc5`='讚美伊露恩!你要尋找戰歌峽谷戰場軍官?她的名字叫做艾薩拉斯，她就在戰士訓練師的旁邊等著迎接你。', `FemaleText_loc7`='¡Que Elune sea bendecida! ¿Buscas a la maestra de batalla de la Garganta Grito de Guerra? Se llama Aethalas, y está esperándote, cerca de los instructores de guerreros.' WHERE `ID`=10360;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지금 그대가 하려는 일은 결코 쉬운 일이 아니랍니다, $n. 전쟁노래 협곡에 가려면 은빛날개 파수대 전투모병관인 애살라스와 대화하십시오. 그녀가 길을 가르쳐줄 겁니다. 여신님의 축복이 함께하기를!', `FemaleText_loc4`='你要做的事情需要很大的勇气，$n。要进入战歌峡谷，你就得跟银翼哨兵的军官艾萨拉斯谈谈。她会为你指引方向的。愿女神的祝福与你同在！', `FemaleText_loc5`='你要做的事情需要很大的努力，$n。要進入戰歌峽谷，你就得跟銀翼哨兵的軍官艾薩拉斯談談。她會為你指引方向的。願女神的祝福與你同在!', `FemaleText_loc7`='La misión en la que te embarcas no es una tarea fácil, $n. Para llegar a la Garganta Grito de Guerra tendrás que hablar con Aethalas, la maestra de batalla de los centinelas Ala de Plata. Ella te guiará en tu camino. ¡Que las bendiciones de la diosa sean contigo!' WHERE `ID`=10361;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투모병관', `MaleText_loc4`='战场军官', `MaleText_loc5`='戰場軍官', `MaleText_loc7`='Maestro de batalla', `FemaleText_loc1`='전투모병관', `FemaleText_loc4`='战场军官', `FemaleText_loc5`='戰場軍官', `FemaleText_loc7`='Maestro de batalla' WHERE `ID`=10362;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 알터랙 계곡의 호드로부터 얼라이언스를 지켜낼 자신이 있단 말이지요? 그렇다면 이곳 아이언포지에서 글로드룸 스틸비어드와 이야기를 나눠보십시오. 그는 전투의 전당에 있는 탁자 앞에서 전략을 짜고 있을 겁니다.', `MaleText_loc4`='那么$g小伙子:小姑娘;，你认为你具有在奥特兰克山谷帮助联盟抵御部落的能力？非常好，那么你一定希望和铁炉堡的格罗杜姆·钢须谈谈。你可以在武器大厅的战略沙图之前找到他。', `MaleText_loc5`='那麼$g小夥子:小姑娘;，你認為你具有在奧特蘭克山谷幫助聯盟抵禦部落的能力?非常好，那麼你一定希望和鐵爐堡的格羅杜姆·鋼鬚談談。你可以在武器大廳的戰略地圖之前找到他。', `MaleText_loc7`='Y bien $gmuchacho: muchacha;, ¿Crees que tienes lo necesario para defender a la Alianza contra la Horda en el Valle de Alterac? Pues muy bien, entonces quizás quieras hablar con nuestro propio Glordrum Barbacerada aquí, en Forjaz. Le encontrarás preparando la estrategia en la mesa de guerra, en la Sala de Armas.', `FemaleText_loc1`='그래, 알터랙 계곡의 호드로부터 얼라이언스를 지켜낼 자신이 있단 말이지요? 그렇다면 이곳 아이언포지에서 글로드룸 스틸비어드와 이야기를 나눠보십시오. 그는 전투의 전당에 있는 탁자 앞에서 전략을 짜고 있을 겁니다.', `FemaleText_loc4`='那么$g小伙子:小姑娘;，你认为你具有在奥特兰克山谷帮助联盟抵御部落的能力？非常好，那么你一定希望和铁炉堡的格罗杜姆·钢须谈谈。你可以在武器大厅的战略沙图之前找到他。', `FemaleText_loc5`='那麼$g小夥子:小姑娘;，你認為你具有在奧特蘭克山谷幫助聯盟抵禦部落的能力?非常好，那麼你一定希望和鐵爐堡的格羅杜姆·鋼鬚談談。你可以在武器大廳的戰略地圖之前找到他。', `FemaleText_loc7`='Y bien $gmuchacho: muchacha;, ¿Crees que tienes lo necesario para defender a la Alianza contra la Horda en el Valle de Alterac? Pues muy bien, entonces quizás quieras hablar con nuestro propio Glordrum Barbacerada aquí, en Forjaz. Le encontrarás preparando la estrategia en la mesa de guerra, en la Sala de Armas.' WHERE `ID`=10363;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 알터랙 계곡이라... 아주 즐거운 추억들이 잔뜩 있는 곳이지요. <한숨> 당신과 함께 전투에 참가할 수는 없지만 제게 자랑스러운 얼라이언스의 일원으로서 기뻐할 경사를 가져다주십시오. 그곳에 가려면 이곳 아이언포지에 있는 전투의 전당에서 글로드룸 스틸비어드와 대화해야 할 겁니다.', `MaleText_loc4`='啊，奥特兰克山谷，我的美好回忆啊。<叹息>嗯，我不能与你同行，但我同样感到骄傲！你得跟铁炉堡武器大厅的格罗杜姆·钢须谈谈。', `MaleText_loc5`='啊，奧特蘭克山谷，我的美好回憶啊。<歎息>嗯，我不能與你同行，但我同樣感到驕傲!你得跟鐵爐堡武器大廳的格羅杜姆·鋼鬚談談。', `MaleText_loc7`='Ah, el Valle de Alterac, tengo muy buenos recuerdos. <suspiro> ¡Bueno, no puedo ir contigo, pero haz que me sienta orgulloso de ti! Para llegar allí, vas a tener que hablar con Glordrum Barbacerada en la Sala de Armas, aquí, en Forjaz.', `FemaleText_loc1`='아, 알터랙 계곡이라... 아주 즐거운 추억들이 잔뜩 있는 곳이지요. <한숨> 당신과 함께 전투에 참가할 수는 없지만 제게 자랑스러운 얼라이언스의 일원으로서 기뻐할 경사를 가져다주십시오. 그곳에 가려면 이곳 아이언포지에 있는 전투의 전당에서 글로드룸 스틸비어드와 대화해야 할 겁니다.', `FemaleText_loc4`='啊，奥特兰克山谷，我的美好回忆啊。<叹息>嗯，我不能与你同行，但我同样感到骄傲！你得跟铁炉堡武器大厅的格罗杜姆·钢须谈谈。', `FemaleText_loc5`='啊，奧特蘭克山谷，我的美好回憶啊。<歎息>嗯，我不能與你同行，但我同樣感到驕傲!你得跟鐵爐堡武器大廳的格羅杜姆·鋼鬚談談。', `FemaleText_loc7`='Ah, el Valle de Alterac, tengo muy buenos recuerdos. <suspiro> ¡Bueno, no puedo ir contigo, pero haz que me sienta orgulloso de ti! Para llegar allí, vas a tener que hablar con Glordrum Barbacerada en la Sala de Armas, aquí, en Forjaz.' WHERE `ID`=10364;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투모병관', `MaleText_loc4`='战场军官', `MaleText_loc5`='戰場軍官', `MaleText_loc7`='Maestro de batalla', `FemaleText_loc1`='전투모병관', `FemaleText_loc4`='战场军官', `FemaleText_loc5`='戰場軍官', `FemaleText_loc7`='Maestro de batalla' WHERE `ID`=10365;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알터랙 계곡으로 가려면 카르타 블러드스날과 얘기해보게. 명예의 골짜기에 있는 용사의 전당에서 그녀를 찾을 수 있을 걸세.', `MaleText_loc4`='如果你想要去奥特兰克山谷，去和卡尔特拉·血喉谈谈。你可以在荣耀谷的勇者大厅去找她。', `MaleText_loc5`='如果你想要去奧特蘭克山谷，去和卡爾特拉·血喉談談。你可以在榮譽谷的勇者大廳找到她。', `MaleText_loc7`='Si vas al Valle de Alterac, habla primero con Kartra Gruñido Sangriento. La encontrarás en el Bastión de los Valientes, en el Valle del Honor.', `FemaleText_loc1`='알터랙 계곡으로 가려면 카르타 블러드스날과 얘기해보게. 명예의 골짜기에 있는 용사의 전당에서 그녀를 찾을 수 있을 걸세.', `FemaleText_loc4`='如果你想要去奥特兰克山谷，去和卡尔特拉·血喉谈谈。你可以在荣耀谷的勇者大厅去找她。', `FemaleText_loc5`='如果你想要去奧特蘭克山谷，去和卡爾特拉·血喉談談。你可以在榮譽谷的勇者大廳找到她。', `FemaleText_loc7`='Si vas al Valle de Alterac, habla primero con Kartra Gruñido Sangriento. La encontrarás en el Bastión de los Valientes, en el Valle del Honor.' WHERE `ID`=10366;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 영광스러운 전투에 나도 참가하고 싶지만 임무 때문에 어쩔 수 없이 여기 있어야 하네. 오그리마 명예의 골짜기에 있는 용사의 전당을 찾아가게. 카르타 블러드스날과 얘기하도록. 그녀라면 알터랙 계곡으로 데려다 줄 수 있을 테니까. $n, 부디 호드의 자랑거리가 되도록!', `MaleText_loc4`='我多想和你一起加入伟大的战斗，但是我不得不待在这里值勤。去奥格瑞玛荣誉谷的勇者大厅找卡尔特拉·血喉，她将会帮助你进入奥特兰克山谷。为部落带来荣耀，$n！', `MaleText_loc5`='我多想和你一起加入偉大的戰鬥，但是我必須待在這裡值勤。去奧格瑪榮譽谷的勇者大廳找卡爾特拉·血喉，她將會幫助你進入奧特蘭克山谷。為部落帶來榮耀，$n!', `MaleText_loc7`='Me encantaría poder unirme a ti en tu gloriosa batalla, pero estoy aquí atrapado... El deber... Vete al Bastión de los Valientes, en el Valle del Honor de Orgrimmar y habla con Kartra Gruñido Sangriento. Ella te ayudará a llegar hasta el Valle de Alterac. ¡Haz que estemos orgullosos de ti, $n!', `FemaleText_loc1`='아, 영광스러운 전투에 나도 참가하고 싶지만 임무 때문에 어쩔 수 없이 여기 있어야 하네. 오그리마 명예의 골짜기에 있는 용사의 전당을 찾아가게. 카르타 블러드스날과 얘기하도록. 그녀라면 알터랙 계곡으로 데려다 줄 수 있을 테니까. $n, 부디 호드의 자랑거리가 되도록!', `FemaleText_loc4`='我多想和你一起加入伟大的战斗，但是我不得不待在这里值勤。去奥格瑞玛荣誉谷的勇者大厅找卡尔特拉·血喉，她将会帮助你进入奥特兰克山谷。为部落带来荣耀，$n！', `FemaleText_loc5`='我多想和你一起加入偉大的戰鬥，但是我必須待在這裡值勤。去奧格瑪榮譽谷的勇者大廳找卡爾特拉·血喉，她將會幫助你進入奧特蘭克山谷。為部落帶來榮耀，$n!', `FemaleText_loc7`='Me encantaría poder unirme a ti en tu gloriosa batalla, pero estoy aquí atrapada... El deber... Vete al Bastión de los Valientes, en el Valle del Honor de Orgrimmar y habla con Kartra Gruñido Sangriento. Ella te ayudará a llegar hasta el Valle de Alterac. ¡Haz que estemos orgullosos de ti, $n!' WHERE `ID`=10367;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='', `MaleText_loc4`='', `MaleText_loc5`='', `MaleText_loc7`='' WHERE `ID`=10368;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='침략자들에게 뜨거운 맛을 보여줘라!', `FemaleText_loc4`='我命令你把这些入侵者烧成灰烬！', `FemaleText_loc5`='我命令你把這些入侵者燒成灰燼!', `FemaleText_loc7`='¡Te ordeno que cubras de fuego a los invasores!' WHERE `ID`=10369;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 귀가 찢어질 듯한 비명을 지릅니다!', `FemaleText_loc4`='%s发出了刺耳的尖啸！', `FemaleText_loc5`='%s發出了震耳欲聾的尖嘯聲!', `FemaleText_loc7`='%s emite un chillido ensordecedor.' WHERE `ID`=10370;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='iCoke 이벤트에 대해 얘기해 주십시오.', `MaleText_loc4`='请告诉我更多关于可口可乐魔兽世界夏季促销活动的细节。', `MaleText_loc5`='請告訴我更多關於可口可樂-魔獸世界特別活動的細節。', `MaleText_loc7`='Háblame sobre la promoción iCoke.', `FemaleText_loc1`='iCoke 이벤트에 대해 얘기해 주십시오.', `FemaleText_loc4`='请告诉我更多关于可口可乐魔兽世界夏季促销活动的细节。', `FemaleText_loc5`='請告訴我更多關於可口可樂-魔獸世界特別活動的細節。', `FemaleText_loc7`='Háblame sobre la promoción iCoke.' WHERE `ID`=10371;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='월드 오브 워크래프트와 Coca-Cola (R)는 공동으로 iCoke-월드 오브 워크래프트 여름 이벤트를 실시합니다. 이벤트 관련 표시가 있는 Coca-Cola 병 뚜껑 안에 있는 코드를 찾으세요. 이곳으로 가져와서 코드를 입력하면 가상 아이템을 받을 수 있습니다.', `MaleText_loc4`='魔兽世界和可口可乐(R)共同为您带来了这次可口可乐魔兽世界“要爽由自己，冰火暴风城II”夏季促销活动。请检查魔兽世界主题的可口可乐易拉罐底部或瓶装可口可乐的瓶盖内侧，您可以找到一串13位字符。在www.iCoke.cn上输入您得到的13位字符，就有机会赢得iCoke积分，从而得到可以换取魔兽世界幸运礼品的10位电子兑换券。最后，在这里输入您得到的电子兑换券上的10位号码，神秘大奖在等待着您！', `MaleText_loc5`='「魔獸世界成長日誌」是一個專門為您與您的好戰友設計的紀錄活動，您只需要收集:

1. 等級10級或以下，找到您的4位隊友並進行合照。
2. 完成我們所提供的任務後拍照。
3.等級成長至58級後，進入外域，在黑暗之門前面與原隊友合照。

憑此三張照片，您便有機會獲得最珍貴的魚人寶寶。詳情可參照官網活動訊息。', `MaleText_loc7`='World of Warcraft y Coca-Cola (R) se han unido para traerte la promoción de verano iCoke-World of Warcraft. Busca los códigos bajo los tapones de las botellas de Coca-Cola marcadas. Después, vuelve aquí e introduce el código para ganar un objeto virtual.', `FemaleText_loc1`='월드 오브 워크래프트와 Coca-Cola (R)는 공동으로 iCoke-월드 오브 워크래프트 여름 이벤트를 실시합니다. 이벤트 관련 표시가 있는 Coca-Cola 병 뚜껑 안에 있는 코드를 찾으세요. 이곳으로 가져와서 코드를 입력하면 가상 아이템을 받을 수 있습니다.', `FemaleText_loc4`='魔兽世界和可口可乐(R)共同为您带来了这次可口可乐魔兽世界“要爽由自己，冰火暴风城II”夏季促销活动。请检查魔兽世界主题的可口可乐易拉罐底部或瓶装可口可乐的瓶盖内侧，您可以找到一串13位字符。在www.iCoke.cn上输入您得到的13位字符，就有机会赢得iCoke积分，从而得到可以换取魔兽世界幸运礼品的10位电子兑换券。最后，在这里输入您得到的电子兑换券上的10位号码，神秘大奖在等待着您！', `FemaleText_loc5`='「魔獸世界成長日誌」是一個專門為您與您的好戰友設計的紀錄活動，您只需要收集:

1. 等級10級或以下，找到您的4位隊友並進行合照。
2. 完成我們所提供的任務後拍照。
3.等級成長至58級後，進入外域，在黑暗之門前面與原隊友合照。

憑此三張照片，您便有機會獲得最珍貴的魚人寶寶。詳情可參照官網活動訊息。', `FemaleText_loc7`='World of Warcraft y Coca-Cola (R) se han unido para traerte la promoción de verano iCoke-World of Warcraft. Busca los códigos bajo los tapones de las botellas de Coca-Cola marcadas. Después, vuelve aquí e introduce el código para ganar un objeto virtual.' WHERE `ID`=10372;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절대로 날 참호 밖으로 끌어낼 수 없을 것이다, 이 야만인 녀석들!', `MaleText_loc4`='你们永远无法将我赶出我的工事！', `MaleText_loc5`='你們永遠無法將我趕出我的碉堡，異教徒!', `MaleText_loc7`='¡Nunca me sacarán del búnker, paganos!' WHERE `ID`=10373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디 한 번 그 얄팍한 전술을 다시 시도해 보시지그래, 얼간이 녀석들! 왜, 이제는 너무 겁이 나나?', `MaleText_loc4`='为什么你们不再试验一次你们那些低贱的手段，娘娘腔？！你们是不是一群懦夫？？', `MaleText_loc5`='你們為什麼不丟掉那些低賤的手段再試試看呢，娘娘腔!你們是不是一群懦夫???', `MaleText_loc7`='¿Por qué no lo intentan sin sus tácticas baratas, babosos? ¿¿¿O son demasiado gallinas???' WHERE `ID`=10374;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='더러운 서리늑대 겁쟁이들 같으니! 싸우고 싶다면 직접 날 찾아와야 할 것이다!', `FemaleText_loc4`='可恶的霜狼懦夫！如果你们想要一战的话，就放马，不，放狼过来吧！', `FemaleText_loc5`='可惡的霜狼懦夫!如果你們想要一戰的話，就放馬，不，放狼過來吧!', `FemaleText_loc7`='¡Cobardes asquerosos Lobo Gélido! ¡Si queréis luchar, venid a mí!' WHERE `ID`=10375;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰파이크 약골들아, 나의 요새로 와서 한 판 붙어보자! 그럴 만한 용기가 있다면!', `MaleText_loc4`='雷矛的渣滓们，如果你们真的有这么大胆的话，就来我的堡垒中挑战我吧！', `MaleText_loc5`='雷矛的肉腳們，如果你們真的有膽子的話，就來我的堡壘中挑戰我吧!', `MaleText_loc7`='¡Peleles Pico Tormenta, enfrentaos a mí en mi fortaleza si os atrevéis!' WHERE `ID`=10376;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 서리늑대 사령관을 요새 밖으로 끌어내시겠다? 말도 안 되는 소리!', `MaleText_loc4`='你们想要把霜狼的将军引出他的要塞？可笑！', `MaleText_loc5`='你們想要把霜狼軍團的將軍引出他的要塞?太可笑了!', `MaleText_loc7`='¿Pretendes sacar al general de la legión Lobo Gélido de su fortaleza? ¡QUÉ RIDICULEZ!' WHERE `ID`=10377;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 그 정도에 속아 넘어갈 것 같으냐, 어리석은 놈들! 내게 맞서고자 한다면 내가 있는 곳에서 내 방식대로 싸워야 할 것이다.', `MaleText_loc4`='我永远不会被你那点伎俩算计到，蠢货！如果你想要一战的话，那就到我的地盘来挑战我吧！', `MaleText_loc5`='我永遠不會因此而倒下，笨蛋!如果你想要一戰的話，那麼我將決定一切，在我的巢穴裡見吧。', `MaleText_loc7`='¡Nunca caería en una trampa así, imbécil! Si quieres una batalla, será según mis condiciones y en mi guarida.' WHERE `ID`=10378;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 라스타칸 님의 오른팔이신 무감바 님께서 보내신 파괴자 진로크다!$B$B난 전사와 이교도들을 담당하고 있지.', `MaleText_loc4`='我是击碎者金罗克，穆贾巴的特使，拉斯塔哈之拳！$B$B我通常只和战士以及异教徒打交道。', `MaleText_loc5`='我是『擊破者』金羅克，拉斯塔哈之拳:穆賈巴的特使!$B$B我只和戰士以及異教徒打交道。', `MaleText_loc7`='Soy Jin''rokh el Rompedor, enviado de Mugamba: ¡Puño de Rastakhan!$B$BSolo trato con guerreros y paganos.' WHERE `ID`=10379;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가지고 있던 부적을 잃어버려서 새 부적이 필요합니다, 진로크.', `MaleText_loc4`='我弄丢了我的饰物，能给我一个新的吗？', `MaleText_loc5`='我把墜飾弄丟了。我需要一個新的，金羅克。', `MaleText_loc7`='He perdido mi talismán y necesito otro, Jin''rokh.', `FemaleText_loc1`='가지고 있던 부적을 잃어버려서 새 부적이 필요합니다, 진로크.', `FemaleText_loc4`='我弄丢了我的饰物，能给我一个新的吗？', `FemaleText_loc5`='我把墜飾弄丟了。我需要一個新的，金羅克。', `FemaleText_loc7`='He perdido mi talismán y necesito otro, Jin''rokh.' WHERE `ID`=10380;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 라스타칸께서 보내신 천리안 알타빔이네.$B$B사제, 마법사, 그리고 흑마법사를 담당하고 있지.', `MaleText_loc4`='我是全知者阿塔比姆，拉斯塔哈的特使。$B$B我通常只和牧师、法师和术士打交道。', `MaleText_loc5`='我是『全知者』阿塔比姆，拉斯塔哈王的特使。$B$B我通常只和牧師、法師和術士打交道。', `MaleText_loc7`='Soy Al''tabim, El que todo lo ve, enviado del rey Rastakhan.$B$BTrato con sacerdotes, magos y brujos.' WHERE `ID`=10381;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아라소르 연맹은 스트롬가드의 인간들과 얼라이언스 전체를 위해 아라시 분지를 되찾겠노라 맹세했소. 이번 전투가 결코 만만치는 않지만 싸울 가치는 충분할 것이외다.', `MaleText_loc4`='阿拉索联军发誓为激流堡和联盟夺回阿拉希。这将是一场恶战，但是是一场值得打的战争。', `MaleText_loc5`='阿拉索聯軍發誓為激流堡和聯盟奪回阿拉希。這將是一場惡戰，但是是一場值得打的戰爭。', `MaleText_loc7`='La Liga de Arathor ha jurado recuperar Arathi para los humanos de Stromgarde y la Alianza. Es una dura batalla, pero una batalla que merece la pena luchar.' WHERE `ID`=10382;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가만히 앉아 기다리고 있어서야 전쟁에서 이길 수 없습니다. 거칠고 빠르게 밀어붙여야 합니다. 그렇지 않으면 아라시 분지를 영원히 되찾지 못할 것입니다.', `FemaleText_loc4`='要赢得这场战争，我们不能坐在这里，静待战争之潮将我们淹没。我们必须果断出击，否则阿拉希永远也不会成为我们的囊中之物。', `FemaleText_loc5`='要贏得這場戰爭，我們不能坐在這裡，靜待戰爭之潮將我們淹沒。我們必須果斷出擊，否則阿拉希永遠也不會成為我們的囊中之物。', `FemaleText_loc7`='¿Cómo me habéis derrotado?' WHERE `ID`=10383;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부적을 잃어버려서 새 부적이 필요합니다, 알타빔.', `MaleText_loc4`='我弄丢了我的饰物，能给我一个新的吗？', `MaleText_loc5`='我把墜飾弄丟了。我需要一個新的，阿塔比姆。', `MaleText_loc7`='He perdido mi talismán y necesito otro, Al''tabim.', `FemaleText_loc1`='부적을 잃어버려서 새 부적이 필요합니다, 알타빔.', `FemaleText_loc4`='我弄丢了我的饰物，能给我一个新的吗？', `FemaleText_loc5`='我把墜飾弄丟了。我需要一個新的，阿塔比姆。', `FemaleText_loc7`='¡Llamo a la toh''menta!' WHERE `ID`=10384;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='누구를 찾고 있는지 알겠어요. 전사의 정원에 있는 브로군 스톤쉴드에게 가보십시오.', `FemaleText_loc4`='你应该去战士区找布洛冈·石盾，$c。', `FemaleText_loc5`='我剛好認識一個你所說的$c。你應該去戰士區找布洛岡·石盾。', `FemaleText_loc7`='Debo deh''trozaros.' WHERE `ID`=10385;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='서리늑대 부족에 맞서 싸우고 있는 스톰파이크 경비대는 그대의 도움을 필요로 하고 있습니다. 전사의 정원에 있는 브로군 스톤쉴드가 알터랙 계곡으로 가는데 도움을 줄 겁니다. 엘룬께 영광을...', `FemaleText_loc4`='雷矛卫队需要你的帮助，赶快去参加对抗霜狼氏族的战斗吧，$n！和战士区的布洛冈·石盾谈一谈，他会帮你抵达奥特兰克山谷。赞美艾露恩！', `FemaleText_loc5`='雷矛衛隊需要你的幫助，趕快去參加對抗霜狼氏族的戰鬥吧，$n!和戰士區的布洛岡·石盾談一談，他會幫助你去到奧特蘭克山谷。讚美伊露恩!', `FemaleText_loc7`='¡Machacar!' WHERE `ID`=10386;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어느 전장으로 가시겠습니까? 전투모병관의 위치를 안내해 드리지요.', `FemaleText_loc4`='有许多战场可供选择，你要去哪一个呢？', `FemaleText_loc5`='有許多戰場可供選擇，你要去哪一個呢?', `FemaleText_loc7`='Tan fácil de romper.' WHERE `ID`=10387;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알터랙 계곡', `MaleText_loc4`='奥特兰克山谷', `MaleText_loc5`='奧特蘭克山谷', `MaleText_loc7`='Valle de Alterac', `FemaleText_loc1`='알터랙 계곡', `FemaleText_loc4`='奥特兰克山谷', `FemaleText_loc5`='奧特蘭克山谷', `FemaleText_loc7`='Débil.' WHERE `ID`=10388;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전쟁노래 협곡', `MaleText_loc4`='战歌峡谷', `MaleText_loc5`='戰歌峽谷', `MaleText_loc7`='Garganta Grito de Guerra', `FemaleText_loc1`='전쟁노래 협곡', `FemaleText_loc4`='战歌峡谷', `FemaleText_loc5`='戰歌峽谷', `FemaleText_loc7`='¡Zas!' WHERE `ID`=10389;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전쟁노래 협곡에서 나이트 엘프들과 그들의 겁쟁이 동료를 없애 버려야 하네. 호드의 일원으로서 돕고 싶다면 명예의 골짜기에 있는 용사의 전당으로 가서 브락굴 데스브링어와 얘기해 보게.', `MaleText_loc4`='战场军官', `MaleText_loc5`='我們必須要消滅戰歌峽谷裡那些精靈跟他們懦弱的盟友。如果你可以幫助部落的話，就去榮譽谷的勇者大廳跟布萊克歐·死亡使者談一談吧。', `MaleText_loc7`='Debemos eliminar a los elfos y su cobarde Alianza de la Garganta Grito de Guerra. Vete al Bastión de los Valientes en el Valle del Honor y habla con Brakgul Libramorte si tienes lo que se necesita para ayudar a la Horda.', `FemaleText_loc1`='전쟁노래 협곡에서 나이트 엘프들과 그들의 겁쟁이 동료를 없애 버려야 하네. 호드의 일원으로서 돕고 싶다면 명예의 골짜기에 있는 용사의 전당으로 가서 브락굴 데스브링어와 얘기해 보게.', `FemaleText_loc4`='战场军官', `FemaleText_loc5`='我們必須要消滅戰歌峽谷裡那些精靈跟他們懦弱的盟友。如果你可以幫助部落的話，就去榮譽谷的勇者大廳跟布萊克歐·死亡使者談一談吧。', `FemaleText_loc7`='Debemos eliminar a los elfos y su cobarde Alianza de la Garganta Grito de Guerra. Vete al Bastión de los Valientes en el Valle del Honor y habla con Brakgul Libramorte si tienes lo que se necesita para ayudar a la Horda.' WHERE `ID`=10390;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은빛날개 파수대라면 싸워볼 만한 가치도 없다고... 그래도 놈들을 쓸어 버리고 싶다면 용사의 전당에 있는 브락굴 데스브링어를 찾아가 보게.', `MaleText_loc4`='银翼哨兵算不上是个可敬的对手，但是如果你对屠杀他们感兴趣，那么就去勇者大厅找布拉古尔吧。', `MaleText_loc5`='銀翼哨兵算不上是個可敬的對手，但是如果你對屠殺他們感興趣，$c，那麼就去勇者大廳找布萊克歐·死亡使者吧。', `MaleText_loc7`='Los centinelas Ala de Plata no son lo que yo llamaría oponentes honorables. Pero si estás $gdecidido:decidida; a matarles, $c, busca a Brakgul Libramorte en el Bastión de los Valientes.', `FemaleText_loc1`='은빛날개 파수대라면 싸워볼 만한 가치도 없다고... 그래도 놈들을 쓸어 버리고 싶다면 용사의 전당에 있는 브락굴 데스브링어를 찾아가 보게.', `FemaleText_loc4`='银翼哨兵算不上是个可敬的对手，但是如果你对屠杀他们感兴趣，那么就去勇者大厅找布拉古尔吧。', `FemaleText_loc5`='銀翼哨兵算不上是個可敬的對手，但是如果你對屠殺他們感興趣，$c，那麼就去勇者大廳找布萊克歐·死亡使者吧。', `FemaleText_loc7`='Los centinelas Ala de Plata no son lo que yo llamaría oponentes honorables. Pero si estás $gdecidido:decidida; a matarles, $c, busca a Brakgul Libramorte en el Bastión de los Valientes.' WHERE `ID`=10391;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어느 전장으로 가서 힘과 명예를 얻으려는가?', `MaleText_loc4`='你要找哪个战场？', `MaleText_loc5`='你想在哪個戰場追求榮耀呢?', `MaleText_loc7`='¿En qué campo de batalla quieres encontrar la gloria?', `FemaleText_loc1`='어느 전장으로 가서 힘과 명예를 얻으려는가?', `FemaleText_loc4`='你要找哪个战场？', `FemaleText_loc5`='你想在哪個戰場追求榮耀呢?', `FemaleText_loc7`='¿En qué campo de batalla quieres encontrar la gloria?' WHERE `ID`=10392;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알터랙 계곡', `MaleText_loc4`='奥特兰克山谷', `MaleText_loc5`='奧特蘭克山谷', `MaleText_loc7`='Valle de Alterac', `FemaleText_loc1`='알터랙 계곡', `FemaleText_loc4`='奥特兰克山谷', `FemaleText_loc5`='奧特蘭克山谷', `FemaleText_loc7`='Valle de Alterac' WHERE `ID`=10393;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전쟁노래 협곡', `MaleText_loc4`='战歌峡谷', `MaleText_loc5`='戰歌峽谷', `MaleText_loc7`='Garganta Grito de Guerra', `FemaleText_loc1`='전쟁노래 협곡', `FemaleText_loc4`='战歌峡谷', `FemaleText_loc5`='戰歌峽谷', `FemaleText_loc7`='Garganta Grito de Guerra' WHERE `ID`=10394;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타임 레이지토템을 말하는 게 틀림없군... 수렵의 봉우리로 가서 찾아보십시오.', `MaleText_loc4`='你一定是在说泰姆·暴怒图腾。去猎人高地找他。', `MaleText_loc5`='你要找的一定就是泰姆·狂暴圖騰。去獵人高地找他。', `MaleText_loc7`='Entonces, con quien debes hablar es con Taim Tótem de Ira. Le puedes encontrar en el Alto de los Cazadores.', `FemaleText_loc1`='타임 레이지토템을 말하는 게 틀림없군... 수렵의 봉우리로 가서 찾아보십시오.', `FemaleText_loc4`='你一定是在说泰姆·暴怒图腾。去猎人高地找他。', `FemaleText_loc5`='你要找的一定就是泰姆·狂暴圖騰。去獵人高地找他。', `FemaleText_loc7`='Entonces, con quien debes hablar es con Taim Tótem de Ira. Le puedes encontrar en el Alto de los Cazadores.' WHERE `ID`=10395;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳 썬더 블러프에 알터랙 계곡으로 가는 걸 도와 줄 수 있는 이가 한 명 있습니다. 수렵의 봉우리에서 타임 레이지토템을 찾아보십시오. 당신이 원하는 것을 구하게 되기를...', `MaleText_loc4`='我知道在雷霆崖有人可以帮助你进入奥特兰克山谷。去猎人高地找泰姆·暴怒图腾。希望你找到你希望找的人，$n。', `MaleText_loc5`='我知道在雷霆崖有人可以幫助你進入奧特蘭克山谷。去獵人高地找泰姆·狂暴圖騰。希望你找到你在找的人，$n。', `MaleText_loc7`='Hay alguien que conozco aquí, en Cima del Trueno, que puede ayudarte en tu viaje al Valle de Alterac. Busca a Taim Tótem de Ira en el Alto de los Cazadores. Que encuentres lo que buscas, $n.', `FemaleText_loc1`='이곳 썬더 블러프에 알터랙 계곡으로 가는 걸 도와 줄 수 있는 이가 한 명 있습니다. 수렵의 봉우리에서 타임 레이지토템을 찾아보십시오. 당신이 원하는 것을 구하게 되기를...', `FemaleText_loc4`='我知道在雷霆崖有人可以帮助你进入奥特兰克山谷。去猎人高地找泰姆·暴怒图腾。希望你找到你希望找的人，$n。', `FemaleText_loc5`='我知道在雷霆崖有人可以幫助你進入奧特蘭克山谷。去獵人高地找泰姆·狂暴圖騰。希望你找到你在找的人，$n。', `FemaleText_loc7`='Hay alguien que conozco aquí, en Cima del Trueno, que puede ayudarte en tu viaje al Valle de Alterac. Busca a Taim Tótem de Ira en el Alto de los Cazadores. Que encuentres lo que buscas, $n.' WHERE `ID`=10396;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수렵의 봉우리에 있는 케르굴 블러드액스가 전쟁노래 협곡으로 가는 걸 도와 줄 겁니다.', `MaleText_loc4`='猎人大厅的克古尔·血斧将会帮助你进入战歌峡谷。', `MaleText_loc5`='獵人高地的克古爾·血斧將會幫助你進入戰歌峽谷。', `MaleText_loc7`='Kergul Hacha de Sangre, en el Alto de los Cazadores, está listo para ayudarte a ir a la Garganta Grito de Guerra.', `FemaleText_loc1`='수렵의 봉우리에 있는 케르굴 블러드액스가 전쟁노래 협곡으로 가는 걸 도와 줄 겁니다.', `FemaleText_loc4`='猎人大厅的克古尔·血斧将会帮助你进入战歌峡谷。', `FemaleText_loc5`='獵人高地的克古爾·血斧將會幫助你進入戰歌峽谷。', `FemaleText_loc7`='Kergul Hacha de Sangre, en el Alto de los Cazadores, está listo para ayudarte a ir a la Garganta Grito de Guerra.' WHERE `ID`=10398;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싸움이란 얼마나 부질없는 짓인지... 하지만 은빛날개 요새의 나이트 엘프들이 우리와 평화롭게 대화할 의향이 없다면 다른 도리가 있겠습니까? 전쟁노래 협곡으로 가려면 수렵의 봉우리에 있는 케르굴 블러드액스에게 가서 도움을 청하십시오.', `MaleText_loc4`='真是无谓的攻击，但是如果银翼要塞的家伙不想要和我们和平相处的话，那么他们还能留给我们什么？去猎人大厅找克古尔·血斧，他将会帮助你进入战歌峡谷。', `MaleText_loc5`='真是無謂的攻擊，但是如果銀翼要塞的傢伙不想要和我們和平相處的話，那麼他們還能留給我們什麼?去獵人高地找克古爾·血斧，他將會幫助你進入戰歌峽谷。', `MaleText_loc7`='Una batalla innecesaria pero, si los elfos del Bastión Ala de Plata no quieren hablar con nosotros en paz, ¿qué otra alternativa nos queda? Busca la ayuda de Kergul Sangracha en el Alto de los Cazadores, para llegar a la Garganta Grito de Guerra.', `FemaleText_loc1`='싸움이란 얼마나 부질없는 짓인지... 하지만 은빛날개 요새의 나이트 엘프들이 우리와 평화롭게 대화할 의향이 없다면 다른 도리가 있겠습니까? 전쟁노래 협곡으로 가려면 수렵의 봉우리에 있는 케르굴 블러드액스에게 가서 도움을 청하십시오.', `FemaleText_loc4`='真是无谓的攻击，但是如果银翼要塞的家伙不想要和我们和平相处的话，那么他们还能留给我们什么？去猎人大厅找克古尔·血斧，他将会帮助你进入战歌峡谷。', `FemaleText_loc5`='真是無謂的攻擊，但是如果銀翼要塞的傢伙不想要和我們和平相處的話，那麼他們還能留給我們什麼?去獵人高地找克古爾·血斧，他將會幫助你進入戰歌峽谷。', `FemaleText_loc7`='Una batalla innecesaria pero, si los elfos del Bastión Ala de Plata no quieren hablar con nosotros en paz, ¿qué otra alternativa nos queda? Busca la ayuda de Kergul Sangracha en el Alto de los Cazadores, para llegar a la Garganta Grito de Guerra.' WHERE `ID`=10399;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어느 전장에서 명예와 영광을 얻길 바라십니까?', `MaleText_loc4`='你想要加入哪个战场？', `MaleText_loc5`='你想要加入哪個戰場?', `MaleText_loc7`='¿Y a qué campo de batalla quieres ir?', `FemaleText_loc1`='어느 전장에서 명예와 영광을 얻길 바라십니까?', `FemaleText_loc4`='你想要加入哪个战场？', `FemaleText_loc5`='你想要加入哪個戰場?', `FemaleText_loc7`='¿Y a qué campo de batalla quieres ir?' WHERE `ID`=10400;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알터랙 계곡', `MaleText_loc4`='奥特兰克山谷', `MaleText_loc5`='奧特蘭克山谷', `MaleText_loc7`='Valle de Alterac', `FemaleText_loc1`='알터랙 계곡', `FemaleText_loc4`='奥特兰克山谷', `FemaleText_loc5`='奧特蘭克山谷', `FemaleText_loc7`='Valle de Alterac' WHERE `ID`=10401;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전쟁노래 협곡', `MaleText_loc4`='战歌峡谷', `MaleText_loc5`='戰歌峽谷', `MaleText_loc7`='Garganta Grito de Guerra', `FemaleText_loc1`='전쟁노래 협곡', `FemaleText_loc4`='战歌峡谷', `FemaleText_loc5`='戰歌峽谷', `FemaleText_loc7`='Garganta Grito de Guerra' WHERE `ID`=10402;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투모병관', `MaleText_loc4`='战场军官', `MaleText_loc5`='戰場軍官', `MaleText_loc7`='Maestro de batalla', `FemaleText_loc1`='전투모병관', `FemaleText_loc4`='战场军官', `FemaleText_loc5`='戰場軍官', `FemaleText_loc7`='Maestro de batalla' WHERE `ID`=10403;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 손이 꽁꽁! 너무 추워! 왕실 가서 그리즐 하프메인이랑 이야기 해.', `MaleText_loc4`='那里很冷！你应该去皇家区找格里兹尔谈谈。', `MaleText_loc5`='那裡很冷!你到皇家區去找格里茲爾談談。', `MaleText_loc7`='¡Aquí hace frío! Vete al Barrio Real, habla con Osco Mediamelena.', `FemaleText_loc1`='거기 손이 꽁꽁! 너무 추워! 왕실 가서 그리즐 하프메인이랑 이야기 해.', `FemaleText_loc4`='那里很冷！你应该去皇家区找格里兹尔谈谈。', `FemaleText_loc5`='那裡很冷!你到皇家區去找格里茲爾談談。', `FemaleText_loc7`='¡Aquí hace frío! Vete al Barrio Real, habla con Osco Mediamelena.' WHERE `ID`=10404;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그의 이름은 그리즐 하프메인... 밴시 여왕님이랑 공포의 군주랑 왕실에 있다.', `MaleText_loc4`='他的名字叫格里兹尔。他在皇家区和女妖之王和恐惧魔王在一起。', `MaleText_loc5`='他的名字叫格里茲爾。他在皇家區和女妖之王和驚懼領主在一起。', `MaleText_loc7`='Su nombre ser Osco Mediamelena. Estar en Barrio Real con reina alma en pena y Señor del Terror.', `FemaleText_loc1`='그의 이름은 그리즐 하프메인... 밴시 여왕님이랑 공포의 군주랑 왕실에 있다.', `FemaleText_loc4`='他的名字叫格里兹尔。他在皇家区和女妖之王和恐惧魔王在一起。', `FemaleText_loc5`='他的名字叫格里茲爾。他在皇家區和女妖之王和驚懼領主在一起。', `FemaleText_loc7`='Su nombre ser Osco Mediamelena. Estar en Barrio Real con reina alma en pena y Señor del Terror.' WHERE `ID`=10405;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왕실로 가 봐. 조그마한 오크, 쿠르덴 블러드클로에게로...', `MaleText_loc4`='小兽人库尔丁·血爪应该在皇家区。', `MaleText_loc5`='我想他大概在皇家區，庫爾丁·血爪是個小獸人。', `MaleText_loc7`='Creer que él estar en Barrio Real. Kurden Zarpasangrante ser orco pequeño.', `FemaleText_loc1`='왕실로 가 봐. 조그마한 오크, 쿠르덴 블러드클로에게로...', `FemaleText_loc4`='小兽人库尔丁·血爪应该在皇家区。', `FemaleText_loc5`='我想他大概在皇家區，庫爾丁·血爪是個小獸人。', `FemaleText_loc7`='Creer que él estar en Barrio Real. Kurden Zarpasangrante ser orco pequeño.' WHERE `ID`=10406;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전쟁노래 협곡 나이트 엘프들 이빨 갈고 있다. 놈들 완전 씹어줘! 왕실... 쿠르덴 블러드클로한테 가 봐.', `MaleText_loc4`='战歌峡谷中的精灵们会在你的打击下发出骨头碎裂的声音。去跟皇家区的库尔丁·血爪谈一谈吧。', `MaleText_loc5`='戰歌峽谷中的精靈們會在你的打擊下發出骨頭碎裂的聲音。去跟皇家區的庫爾丁·血爪談一談吧。', `MaleText_loc7`='Los elfos de la Garganta Grito de Guerra hacen un ruido crujiente al aplastarlos. ¡Aplástalos bien! Habla con Kurden Zarpasangrante en el Barrio Real.', `FemaleText_loc1`='전쟁노래 협곡 나이트 엘프들 이빨 갈고 있다. 놈들 완전 씹어줘! 왕실... 쿠르덴 블러드클로한테 가 봐.', `FemaleText_loc4`='战歌峡谷中的精灵们会在你的打击下发出骨头碎裂的声音。去跟皇家区的库尔丁·血爪谈一谈吧。', `FemaleText_loc5`='戰歌峽谷中的精靈們會在你的打擊下發出骨頭碎裂的聲音。去跟皇家區的庫爾丁·血爪談一談吧。', `FemaleText_loc7`='Los elfos de la Garganta Grito de Guerra hacen un ruido crujiente al aplastarlos. ¡Aplástalos bien! Habla con Kurden Zarpasangrante en el Barrio Real.' WHERE `ID`=10407;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어느 전장?', `MaleText_loc4`='你想去哪个战场？', `MaleText_loc5`='你想去哪個戰場?', `MaleText_loc7`='¿Qué campo de batalla quieres?', `FemaleText_loc1`='어느 전장?', `FemaleText_loc4`='你想去哪个战场？', `FemaleText_loc5`='你想去哪個戰場?', `FemaleText_loc7`='¿Qué campo de batalla quieres?' WHERE `ID`=10408;
