UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투모병관', `MaleText_loc4`='战场军官', `MaleText_loc5`='戰場軍官', `MaleText_loc7`='Maestro de batalla', `FemaleText_loc1`='전투모병관', `FemaleText_loc4`='战场军官', `FemaleText_loc5`='戰場軍官', `FemaleText_loc7`='Maestro de batalla' WHERE `ID`=10411;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전쟁노래 협곡이라고 말씀이십니까? 전투의 전당에 있는 아름다운 리란드리스와 대화해 보십시오.', `MaleText_loc4`='战歌峡谷？好吧，你应该去跟武器大厅的莱兰迪斯谈一谈。', `MaleText_loc5`='戰歌峽谷?好吧，你應該去跟武器大廳的萊蘭迪斯談一談。', `MaleText_loc7`='¿La Garganta Grito de Guerra, dices? Bueno, pues entonces tienes que hablar con la bella Lylandris, en la Sala de Armas.', `FemaleText_loc1`='전쟁노래 협곡이라고 말씀이십니까? 전투의 전당에 있는 아름다운 리란드리스와 대화해 보십시오.', `FemaleText_loc4`='战歌峡谷？好吧，你应该去跟武器大厅的莱兰迪斯谈一谈。', `FemaleText_loc5`='戰歌峽谷?好吧，你應該去跟武器大廳的萊蘭迪斯談一談。', `FemaleText_loc7`='¿La Garganta Grito de Guerra, dices? Bueno, pues entonces tienes que hablar con la bella Lylandris, en la Sala de Armas.' WHERE `ID`=10412;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드와 싸움이라... 특히 오크와 한판 붙어 볼 기회가 생기길 빌게요. 전쟁노래 협곡으로 가면 당신이 그렇게도 바라던 전투를 끝없이 할 수 있을 겁니다. 전투의 전당으로 가서 리란드리스를 찾으세요. 전쟁노래 협곡으로 이끌어 줄 테니까요.', `MaleText_loc4`='任何与部落——特别是兽人——交战的机会都是不容错过的。你可以在战歌峡谷中得到充分的历练，到武器大厅去找莱兰迪斯谈一谈吧，她会送你去战歌峡谷的。', `MaleText_loc5`='任何與部落─特別是獸人─交戰的機會都是不容錯過的。你可以在戰歌峽谷中得到充分的歷練，到武器大廳去找萊蘭迪斯談一談吧，她會送你去戰歌峽谷的。', `MaleText_loc7`='Cualquier ocasión de luchar contra la Horda, especialmente contra los orcos, es una buena ocasión si me lo preguntas. Encontrarás toda la batalla que quieras en la Garganta Grito de Guerra, eso te lo digo yo. Dirígete a la Sala de Armas y habla con Lylandris. Ella te ayudará a ponerte en marcha.', `FemaleText_loc1`='호드와 싸움이라... 특히 오크와 한판 붙어 볼 기회가 생기길 빌게요. 전쟁노래 협곡으로 가면 당신이 그렇게도 바라던 전투를 끝없이 할 수 있을 겁니다. 전투의 전당으로 가서 리란드리스를 찾으세요. 전쟁노래 협곡으로 이끌어 줄 테니까요.', `FemaleText_loc4`='任何与部落——特别是兽人——交战的机会都是不容错过的。你可以在战歌峡谷中得到充分的历练，到武器大厅去找莱兰迪斯谈一谈吧，她会送你去战歌峡谷的。', `FemaleText_loc5`='任何與部落─特別是獸人─交戰的機會都是不容錯過的。你可以在戰歌峽谷中得到充分的歷練，到武器大廳去找萊蘭迪斯談一談吧，她會送你去戰歌峽谷的。', `FemaleText_loc7`='Cualquier ocasión de luchar contra la Horda, especialmente contra los orcos, es una buena ocasión si me lo preguntas. Encontrarás toda la batalla que quieras en la Garganta Grito de Guerra, eso te lo digo yo. Dirígete a la Sala de Armas y habla con Lylandris. Ella te ayudará a ponerte en marcha.' WHERE `ID`=10413;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어느 전장을 찾고 계십니까?', `MaleText_loc4`='嗯，你在找哪个战场？', `MaleText_loc5`='嗯，你在找哪個戰場?', `MaleText_loc7`='Sí, ¿y qué campo de batalla tás buscando?', `FemaleText_loc1`='어느 전장을 찾고 계십니까?', `FemaleText_loc4`='嗯，你在找哪个战场？', `FemaleText_loc5`='嗯，你在找哪個戰場?', `FemaleText_loc7`='Sí, ¿y qué campo de batalla tás buscando?' WHERE `ID`=10414;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알터랙 계곡', `MaleText_loc4`='奥特兰克山谷', `MaleText_loc5`='奧特蘭克山谷', `MaleText_loc7`='Valle de Alterac', `FemaleText_loc1`='알터랙 계곡', `FemaleText_loc4`='奥特兰克山谷', `FemaleText_loc5`='奧特蘭克山谷', `FemaleText_loc7`='Valle de Alterac' WHERE `ID`=10415;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전쟁노래 협곡', `MaleText_loc4`='战歌峡谷', `MaleText_loc5`='戰歌峽谷', `MaleText_loc7`='Garganta Grito de Guerra', `FemaleText_loc1`='전쟁노래 협곡', `FemaleText_loc4`='战歌峡谷', `FemaleText_loc5`='戰歌峽谷', `FemaleText_loc7`='Garganta Grito de Guerra' WHERE `ID`=10416;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 만나야 하는 자의 이름은 텔만 슬레이트피스트입니다. 스톰윈드 왕궁의 알현실로 가면 찾을 수 있을 겁니다.', `MaleText_loc4`='战场军官', `MaleText_loc5`='你要找的一定就是塞爾曼·岩拳。你可以在暴風要塞的國王旁找到他。', `MaleText_loc7`='Tienes que hablar con Thelman Puñopizarra. Le podrás encontrar en presencia del rey, en el Castillo de Ventormenta.', `FemaleText_loc1`='당신이 만나야 하는 자의 이름은 텔만 슬레이트피스트입니다. 스톰윈드 왕궁의 알현실로 가면 찾을 수 있을 겁니다.', `FemaleText_loc4`='战场军官', `FemaleText_loc5`='你要找的一定就是塞爾曼·岩拳。你可以在暴風要塞的國王旁找到他。', `FemaleText_loc7`='Tienes que hablar con Thelman Puñopizarra. Le podrás encontrar en presencia del rey, en el Castillo de Ventormenta.' WHERE `ID`=10417;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저도 당신과 동행할 수 있다면 좋겠군요. 알터랙 계곡으로 가려면 스톰윈드 왕궁으로 가십시오. 국왕 알현실에서 텔만 슬레이트피스트를 만날 수 있을 겁니다. 그라면 당신을 도와 줄 수 있을 거예요.', `MaleText_loc4`='真希望与你同行，$n。去暴风要塞吧，跟国王觐见室的塞尔曼·岩拳谈谈，他会帮助你前往奥特兰克山谷的。', `MaleText_loc5`='真希望與你同行，$n。去暴風要塞吧，跟國王覲見室的塞爾曼·岩拳談一談，他會幫助你前往奧特蘭克山谷的。', `MaleText_loc7`='Ojalá pudiera irme contigo, $n. Vete al Castillo de Ventormenta. Encontrarás a Thelman Puñopizarra en la sala de audiencias del rey. Te ayudará a llegar hasta el Valle de Alterac.', `FemaleText_loc1`='저도 당신과 동행할 수 있다면 좋겠군요. 알터랙 계곡으로 가려면 스톰윈드 왕궁으로 가십시오. 국왕 알현실에서 텔만 슬레이트피스트를 만날 수 있을 겁니다. 그라면 당신을 도와 줄 수 있을 거예요.', `FemaleText_loc4`='真希望与你同行，$n。去暴风要塞吧，跟国王觐见室的塞尔曼·岩拳谈谈，他会帮助你前往奥特兰克山谷的。', `FemaleText_loc5`='真希望與你同行，$n。去暴風要塞吧，跟國王覲見室的塞爾曼·岩拳談一談，他會幫助你前往奧特蘭克山谷的。', `FemaleText_loc7`='Ojalá pudiera irme contigo, $n. Vete al Castillo de Ventormenta. Encontrarás a Thelman Puñopizarra en la sala de audiencias del rey. Te ayudará a llegar hasta el Valle de Alterac.' WHERE `ID`=10418;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사실, 지금 은빛날개 요새에서 당신의 도움을 필요로 하고 있습니다. 스톰윈드 왕궁의 알현실로 가서 엘파란과 얘기해 보십시오.', `MaleText_loc4`='银翼要塞需要你的援助。跟暴风要塞觐见室的艾弗拉兰谈谈。', `MaleText_loc5`='銀翼要塞需要你的援助。跟暴風要塞覲見室的艾弗拉蘭談談。', `MaleText_loc7`='Además, el Bastión Ala de Plata necesita tu ayuda. Habla con Elfarran en la sala de audiencias del rey en el Castillo de Ventormenta.', `FemaleText_loc1`='사실, 지금 은빛날개 요새에서 당신의 도움을 필요로 하고 있습니다. 스톰윈드 왕궁의 알현실로 가서 엘파란과 얘기해 보십시오.', `FemaleText_loc4`='银翼要塞需要你的援助。跟暴风要塞觐见室的艾弗拉兰谈谈。', `FemaleText_loc5`='銀翼要塞需要你的援助。跟暴風要塞覲見室的艾弗拉蘭談談。', `FemaleText_loc7`='Además, el Bastión Ala de Plata necesita tu ayuda. Habla con Elfarran en la sala de audiencias del rey en el Castillo de Ventormenta.' WHERE `ID`=10419;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은빛날개 파수대는 전쟁노래 정찰대와 전투를 위해 가능한 많은 이들의 도움을 받고 있습니다. 도움을 주려거든 스톰윈드 왕궁으로 가서 엘파란과 얘기해 보도록 하십시오.', `MaleText_loc4`='银翼哨兵运用一切援助对抗战歌前锋。$n，如果你想要帮助他们的话，就去暴风要塞找艾弗拉兰谈谈。', `MaleText_loc5`='銀翼哨兵運用一切援助對抗戰歌先遣騎。$n，如果你想要幫助他們的話，就去暴風要塞找艾弗拉蘭談談。', `MaleText_loc7`='Los centinelas Ala de Plata necesitan toda la ayuda que puedan conseguir para luchar contra los escoltas Grito de Guerra. $n, vete al Castillo de Ventormenta y habla con Elfarran si quieres ayudarles.', `FemaleText_loc1`='은빛날개 파수대는 전쟁노래 정찰대와 전투를 위해 가능한 많은 이들의 도움을 받고 있습니다. 도움을 주려거든 스톰윈드 왕궁으로 가서 엘파란과 얘기해 보도록 하십시오.', `FemaleText_loc4`='银翼哨兵运用一切援助对抗战歌前锋。$n，如果你想要帮助他们的话，就去暴风要塞找艾弗拉兰谈谈。', `FemaleText_loc5`='銀翼哨兵運用一切援助對抗戰歌先遣騎。$n，如果你想要幫助他們的話，就去暴風要塞找艾弗拉蘭談談。', `FemaleText_loc7`='Los centinelas Ala de Plata necesitan toda la ayuda que puedan conseguir para luchar contra los escoltas Grito de Guerra. $n, vete al Castillo de Ventormenta y habla con Elfarran si quieres ayudarles.' WHERE `ID`=10420;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 전장에 관심이 있으신가요?', `MaleText_loc4`='你对哪个战场感兴趣？', `MaleText_loc5`='你對哪個戰場感興趣?', `MaleText_loc7`='¿Qué campo de batalla te interesa?', `FemaleText_loc1`='어떤 전장에 관심이 있으신가요?', `FemaleText_loc4`='你对哪个战场感兴趣？', `FemaleText_loc5`='你對哪個戰場感興趣?', `FemaleText_loc7`='¿Qué campo de batalla te interesa?' WHERE `ID`=10421;
