UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전쟁노래 협곡', `MaleText_loc4`='战歌峡谷', `MaleText_loc5`='戰歌峽谷', `MaleText_loc7`='Garganta Grito de Guerra', `FemaleText_loc1`='전쟁노래 협곡', `FemaleText_loc4`='战歌峡谷', `FemaleText_loc5`='戰歌峽谷', `FemaleText_loc7`='Garganta Grito de Guerra' WHERE `ID`=10423;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투모병관', `MaleText_loc4`='战场军官', `MaleText_loc5`='戰場軍官', `MaleText_loc7`='Maestro de batalla', `FemaleText_loc1`='전투모병관', `FemaleText_loc4`='战场军官', `FemaleText_loc5`='戰場軍官', `FemaleText_loc7`='Maestro de batalla' WHERE `ID`=10424;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='화염에 완전히 휩싸인 %s|1이;가; 광기 가득한 눈빛을 번득입니다!', `MaleText_loc4`='%s完全被烈焰吞噬了，他的双眼射出了疯狂的光芒！', `MaleText_loc5`='%s完全被烈焰吞噬了，他的雙眼中射出了瘋狂的光芒!', `MaleText_loc7`='%s se envuelve en llamas y una mirada de locura aparece en sus ojos.' WHERE `ID`=10425;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭘 바라는 거죠?$B$B나 메이위키는 드루이드와 주술사만 상대한다고요.', `FemaleText_loc4`='你想要什么？$B$B梅维克只跟德鲁伊和萨满祭司往来。', `FemaleText_loc5`='你想要什麼?$B$B梅維基只跟德魯伊和薩滿往來。', `FemaleText_loc7`='¿Qué esperabas, colega?$B$BMaywiki solo trata con druidas y chamanes.' WHERE `ID`=10426;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='메이위키, 지니고 있던 부적을 잃어버려서 새 부적이 필요합니다.', `MaleText_loc4`='梅维克，我把坠饰弄丢了，想再要一份。', `MaleText_loc5`='梅維基，我把墜飾弄丟了。我需要一個新的。', `MaleText_loc7`='Maywiki, he perdido mi talismán y necesito otro.', `FemaleText_loc1`='메이위키, 지니고 있던 부적을 잃어버려서 새 부적이 필요합니다.', `FemaleText_loc4`='梅维克，我把坠饰弄丢了，想再要一份。', `FemaleText_loc5`='梅維基，我把墜飾弄丟了。我需要一個新的。', `FemaleText_loc7`='Maywiki, he perdido mi talismán y necesito otro.' WHERE `ID`=10427;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오시오. 풍성한 수확의 기쁨을 기리는 추수절이 돌아왔소이다. 마땅히 축제를 벌여 우리에게 주어진 모든 것에 감사해야 하오! 특히 선조와 과거의 영웅들을 기억하며 그들이 물려 준 유산에 감사를 표해야지...$B$B자, 이곳에서 열리는 축제를 마음껏 즐기시오. 참, 그리고 이 명절을 더욱 아름답게 빛내 줄 폭죽도 팔고 있으니 둘러 보시오.', `MaleText_loc4`='你好，$c。眼下正是收获节——感恩与追思的季节。我们举办盛宴感激所有我们应该感激的人，追忆我们的祖先和英雄，感谢他们给我们留下的宝贵遗产。$B$B请尽情享受这盛宴吧。我还会燃放焰火助兴。', `MaleText_loc5`='你好，$c。現在正是收穫節－一個感恩與追思的時間。我們舉辦盛宴感激所有我們應該感激的人，追憶我們的祖先和英雄，感謝他們給我們留下的寶貴遺產。$B$B請盡情享受這盛宴吧。我還提供一些煙火來慶祝這個美好的日子。', `MaleText_loc7`='Saludos, $c. Es la época del Festival de la Cosecha. Época de grandes regalos y de conmemoración. Participamos en banquetes para celebrar todo aquello por lo que tenemos que dar gracias, y recordamos a nuestros ancestros y héroes pasados, dando gracias por el legado que nos han dejado.$B$BParticipa en la celebración. También voy a ofrecer unos fuegos artificiales para celebrar este jubiloso momento del año.' WHERE `ID`=10428;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디 어떤 폭죽인지 구경 좀 할까요?', `MaleText_loc4`='让我看看你的焰火。', `MaleText_loc5`='讓我看看你的煙火。', `MaleText_loc7`='Deja que vea tu selección de fuegos artificiales.', `FemaleText_loc1`='어디 어떤 폭죽인지 구경 좀 할까요?', `FemaleText_loc4`='让我看看你的焰火。', `FemaleText_loc5`='讓我看看你的煙火。', `FemaleText_loc7`='Deja que vea tu selección de fuegos artificiales.' WHERE `ID`=10429;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오세요. 풍성한 수확의 기쁨을 기리는 추수절이 돌아왔습니다. 마땅히 축제를 벌여 우리에게 주어진 모든 것에 감사해야지요! 특히 선조와 과거의 영웅들을 기억하며 그들이 물려 준 유산에 감사를 표해야 합니다.$B$B자, 이곳에서 열리는 축제를 마음껏 즐기세요. 참, 그리고 전 이 명절을 더욱 아름답게 빛내 줄 폭죽도 팔고 있답니다.', `MaleText_loc4`='你好，$c。眼下正是收获节——感恩与追思的季节。我们举办盛宴感激所有我们应该感激的人，追忆我们的祖先和英雄，感谢他们给我们留下的宝贵遗产。$B$B请尽情享受这盛宴吧。我还会燃放焰火助兴。', `MaleText_loc5`='你好，$c。現在正是收穫節－一個感恩與追思的時間。我們舉辦盛宴感激所有我們應該感激的人，追憶我們的祖先和英雄，感謝他們給我們留下的寶貴遺產。$B$B請盡情享受這盛宴吧。我還提供一些煙火來慶祝這個美好的日子。', `MaleText_loc7`='Saludos, $c. Es la época del Festival de la Cosecha. Época de grandes regalos y de conmemoración. Participamos en banquetes para celebrar todo aquello por lo que tenemos que dar gracias, y recordamos a nuestros ancestros y héroes pasados, dando gracias por el legado que nos han dejado.$B$BParticipa en la celebración. También voy a ofrecer unos fuegos artificiales para celebrar este jubiloso momento del año.' WHERE `ID`=10430;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='절대로 얼라이언스가 아라시 분지에서 세력을 확대하게 내버려둬선 안 돼! 저 조그마한 임시 주둔지가 커져서 훗날 우리 목숨을 위협할 수도 있는 일 아닌가!', `FemaleText_loc4`='我们绝不能让联盟在阿拉希扩张势力！既便是小小的避难谷地，在将来也可能对我们形成威胁。', `FemaleText_loc5`='我們絕不能讓聯盟在阿拉希擴張勢力!既便是小小的避難谷地，在將來也可能對我們形成威脅。', `FemaleText_loc7`='¡No podemos permitir que la Alianza expanda su posición de poder en Arathi! Incluso su minúsculo Refugio de la Zaga podría llegar a ser lo suficientemente grande como para suponer una amenaza.' WHERE `ID`=10431;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아라시 분지의 전쟁은 곧 물자 전쟁이나 다름없다네. 목재, 광석, 식량... 이 모든 것이 전쟁의 승리를 위해 필수적이지.$B$B그러므로 전장에서 적의 물자 보급을 차단하는 일은 적장을 처치하는 것만큼이나 훌륭한 공을 세운 것일세.', `MaleText_loc4`='阿拉希盆地的战斗是一场谋略战。木材、矿石、食物……所有这些物资对战斗来说都是必需品。$B$B销毁敌方的物资跟在战场上杀死他们一样重要。', `MaleText_loc5`='阿拉希盆地的戰鬥是一場謀略戰。木材、礦石、食物...所有這些物資對戰鬥來說都是必需品。$B$B摧毀敵方的物資跟在戰場上殺死他們一樣重要。', `MaleText_loc7`='La batalla por la Cuenca de Arathi es una batalla por recursos. Madera, minerales, comida... Todo es necesario para poder costear una guerra en condiciones.$B$BPrivar a nuestros enemigos de sus suministros es tan eficaz como matarlos en el campo de batalla.' WHERE `ID`=10432;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 몸, 비록 눈은 멀었지만 사리 판단은 분명합니다.$B$B저는 주로 사냥꾼과 도적을 상대하지요.', `MaleText_loc4`='我眼睛瞎了，但是我还拥有洞察力。$B$B我主要跟猎人和潜行者打交道，$r。', `MaleText_loc5`='我眼睛雖然看不到，但是我還擁有洞察力。$B$B我主要跟獵人和盜賊打交道，$r。', `MaleText_loc7`='Es posible que sea ciego, pero tengo visión.$B$BTrato principalmente con cazadores y pícaros, $r.' WHERE `ID`=10433;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곧 저승으로 보내주겠다!', `MaleText_loc4`='你很快就会没命了！', `MaleText_loc5`='你很快就會沒命了!', `MaleText_loc7`='¡Pronto eh''tarán mueh''tos!', `FemaleText_loc1`='곧 저승으로 보내주겠다!', `FemaleText_loc4`='你很快就会没命了！', `FemaleText_loc5`='你很快就會沒命了!', `FemaleText_loc7`='¡Pronto eh''tarán mueh''tos!' WHERE `ID`=10434;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두꺼비가 되고 싶어 제 발로 찾아 왔구나!', `MaleText_loc4`='我要把你的魔精抽干！', `MaleText_loc5`='我要把你做成魔精!', `MaleText_loc7`='¡Voy a conveh''tih''te en mojo!', `FemaleText_loc1`='두꺼비가 되고 싶어 제 발로 찾아 왔구나!', `FemaleText_loc4`='我要把你的魔精抽干！', `FemaleText_loc5`='我要把你做成魔精!', `FemaleText_loc7`='¡Voy a convertirte en mojo!' WHERE `ID`=10435;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 두개골로 우리의 제단을 장식하겠다!', `MaleText_loc4`='你的头骨将用于装饰我们的祭坛！', `MaleText_loc5`='你的頭骨將用於裝飾我們的祭壇!', `MaleText_loc7`='¡Tu calavera decorará nuestros altares rituales!', `FemaleText_loc1`='그 두개골로 우리의 제단을 장식하겠다!', `FemaleText_loc4`='你的头骨将用于装饰我们的祭坛！', `FemaleText_loc5`='你的頭骨將用於裝飾我們的祭壇!', `FemaleText_loc7`='¡Tu calavera decorará nuestros altares rituales!' WHERE `ID`=10436;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='트롤의 주술이 가장 강력하다!', `MaleText_loc4`='巨魔的魔精是最好的！', `MaleText_loc5`='食人妖的魔精是最強大的!', `MaleText_loc7`='¡Mojo de trol, el mojo más fuerte!', `FemaleText_loc1`='트롤의 주술이 가장 강력하다!', `FemaleText_loc4`='巨魔的魔精是最好的！', `FemaleText_loc5`='食人妖的魔精是最強大的!', `FemaleText_loc7`='¡Mojo de trol, el mojo más fuerte!' WHERE `ID`=10437;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위대한 부두교 마법의 맛을 봐라!', `MaleText_loc4`='尝尝巫毒的力量！', `MaleText_loc5`='嘗嘗巫毒的力量!', `MaleText_loc7`='¡Siente el Gran vudú malvado!', `FemaleText_loc1`='위대한 부두교 마법의 맛을 봐라!', `FemaleText_loc4`='尝尝巫毒的力量！', `FemaleText_loc5`='嘗嘗巫毒的力量!', `FemaleText_loc7`='¡Siente el Gran vudú malvado!' WHERE `ID`=10438;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='팔디르, 부적을 잃어버렸어요. 새 걸로 바꿔주세요.', `MaleText_loc4`='法希尔，我把坠饰弄丢了。我需要一个新的。', `MaleText_loc5`='法希爾，我把墜飾弄丟了。我需要一個新的。', `MaleText_loc7`='He perdido el talismán, Falthir. Necesito otro.', `FemaleText_loc1`='팔디르, 부적을 잃어버렸어요. 새 걸로 바꿔주세요.', `FemaleText_loc4`='法希尔，我把坠饰弄丢了。我需要替代物品。', `FemaleText_loc5`='法希爾，我把墜飾弄丟了。我需要一個新的。', `FemaleText_loc7`='He perdido el talismán, Falthir. Necesito otro.' WHERE `ID`=10439;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오십시오.전 줄다자르의 상인 린워쇼라고 합니다. 제 고향 남쪽 바다에서 여러 가지 이국적인 물건들을 가지고 왔지요.$B$B당신이 우리 부족에게 가치 있는 존재라는 걸 충분히 입증해 보인다면 나와 교환을 할 수 있을 겁니다. 그리고 잔달라 명예 징표를 손에 넣으면 우리 거래 얘기는 한결 쉬워질 거고요.', `MaleText_loc4`='冒险者，你好。我是赞达拉的商人林沃斯。我来自南海，从我的家乡带来了许多新奇的货物。$B$B如果你能证明自己的价值，我会乐意与你交换物品的。如果你有我们部族的荣誉勋章，我这里还有些更好的东西……', `MaleText_loc5`='冒險者，你好。我是贊達拉的商人林沃斯。我來自南海，從我的家鄉帶來了許多新奇的貨物。$B$B如果你能證明自己的價值，我會樂意與你交換物品的。如果你有我們部族的榮譽勳章，我這裡還有些更好的東西...', `MaleText_loc7`='Hola, $gaventurero:aventurera;. Soy Rin''wosho, mercader de Zuldazar. Vengo de los Mares del Sur y traigo mercancías y objetos exóticos de mi tierra.$B$BQuizás, si demuestras tu dignidad a mi tribu, te haga un trueque. Si tienes alguna muestra de honor de mi tribu, quizás hagamos más de un trueque.' WHERE `ID`=10440;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='린워쇼, 어떤 물건을 가지고 있는지 보여 주십시오.', `MaleText_loc4`='林沃斯，让我看看你有什么货物！', `MaleText_loc5`='林沃斯，讓我看看你有什麼東西!', `MaleText_loc7`='Hagamos un trueque, Rin''wosho. ¡Muéstrame las mercancías que tienes a la venta!', `FemaleText_loc1`='린워쇼, 어떤 물건을 가지고 있는지 보여 주십시오.', `FemaleText_loc4`='林沃斯，让我看看你有什么货物！', `FemaleText_loc5`='林沃斯，讓我看看你有什麼東西!', `FemaleText_loc7`='Hagamos un trueque, Rin''wosho. ¡Muéstrame las mercancías que tienes a la venta!' WHERE `ID`=10441;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='린워쇼, 장비를 수리하고 싶습니다.', `MaleText_loc4`='林沃斯，我需要修理服务。', `MaleText_loc5`='林沃斯，我需要修理服務。', `MaleText_loc7`='Rin''wosho, necesito una reparación.', `FemaleText_loc1`='린워쇼, 장비를 수리하고 싶습니다.', `FemaleText_loc4`='林沃斯，我需要修理服务。', `FemaleText_loc5`='林沃斯，我需要修理服務。', `FemaleText_loc7`='Rin''wosho, necesito una reparación.' WHERE `ID`=10442;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='샤드라여, 이 몸을 당신의 화신으로 삼으소서!', `FemaleText_loc4`='沙德拉，让我成为你的化身！', `FemaleText_loc5`='沙德拉，讓我成為你的化身!', `FemaleText_loc7`='¡Shadra, conviérteme en tu avatar!' WHERE `ID`=10443;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 종족은 쓰러지지 않으리라!', `FemaleText_loc4`='我们不会失败的！', `FemaleText_loc5`='我們不會失敗的!', `FemaleText_loc7`='¡El linaje no fallará!' WHERE `ID`=10444;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 완전히 자랐습니다!', `MaleText_loc4`='%s完全成长了！', `MaleText_loc5`='%s完全成長了!', `MaleText_loc7`='%s ha alcanzado su tamaño total.' WHERE `ID`=10445;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼을 버려라, 벌레들아. 내가 너희를 학카르 님께 데려간다!', `MaleText_loc4`='投降吧，虫子。我将把你们献给哈卡！', `MaleText_loc5`='別抵抗，蟲子們，我會親手把你們送到哈卡那去!', `MaleText_loc7`='Dejen de luchar, infieles. ¡Yo mismo los llevaré ante Hakkar!' WHERE `ID`=10446;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자만심은 세상의 종말을 불러올 뿐이다. 오너라! 건방진 피조물들이여! 와서 신의 진노에 맞서 보아라!', `MaleText_loc4`='骄傲会将你送上绝路。来吧，凡人！品尝夺灵者的愤怒吧！', `MaleText_loc5`='驕傲會將你送上絕路。來吧，凡人!品嘗奪魂者的憤怒吧!', `MaleText_loc7`='EL ORGULLO ANUNCIA EL FINAL DE SU MUNDO. ¡VENGAN MORTALES! ¡ENFRENTENSE A LA IRA DEL CAZADOR DE ALMAS!' WHERE `ID`=10447;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아이들아, 어미를 도와라!', `FemaleText_loc4`='来为我作战吧，我的孩子们！', `FemaleText_loc5`='來幫助我吧，我的孩子們!', `FemaleText_loc7`='¡Ayudadme, hijos míos!' WHERE `ID`=10448;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 잘 왔다. 죽을 준비나 해둬라!', `MaleText_loc4`='朋友，欢迎参加这场盛宴。来吧，狂欢至死吧！', `MaleText_loc5`='歡迎來到這場盛宴，朋友。來吧，受死吧!', `MaleText_loc7`='Bienvenidos al gran espectáculo, amigos. ¡Den un paso al frente y prepárense para morir!' WHERE `ID`=10449;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마침내... 영혼의 구속에서 풀려나는구나!', `FemaleText_loc4`='我终于摆脱了夺灵者的束缚！', `FemaleText_loc5`='我終於擺脫了奪魂者!', `FemaleText_loc7`='¡Por fin soy libre del Cazador de Almas!' WHERE `ID`=10450;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='학카르의 구속이 끝났다! 이젠 평안히 잠들리라!', `MaleText_loc4`='哈卡再也不能束缚我了！我终于可以安息了！', `MaleText_loc5`='哈卡再也不能束縛我了!我終於可以安息了!', `MaleText_loc7`='¡Hakkar no me controla! ¡Por fin algo de paz!' WHERE `ID`=10451;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제... 해방이다! 망할 놈의 학카르! 저주를 받아라!', `FemaleText_loc4`='必然的结局……死亡！诅咒你，哈卡！诅咒你！', `FemaleText_loc5`='必然的結局...死亡!詛咒你，哈卡!詛咒你!', `FemaleText_loc7`='¡Y al fin la muerte! ¡Te maldigo, Hakkar! ¡Te maldigo!' WHERE `ID`=10452;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 죽습니다.', `MaleText_loc4`='%s死了。', `MaleText_loc5`='%s死了。', `MaleText_loc7`='%s muere.', `FemaleText_loc1`='%s|1이;가; 죽습니다.', `FemaleText_loc4`='%s死了。', `FemaleText_loc5`='%s死了。', `FemaleText_loc7`='%s muere.' WHERE `ID`=10453;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='근처 동맹군이 %s|1을;를; 부활시킵니다!', `MaleText_loc4`='%s被附近的盟友复活了！', `MaleText_loc5`='%s被附近的盟友復活了!', `MaleText_loc7`='%s resucita gracias a un aliado cercano.', `FemaleText_loc1`='근처 동맹군이 %s|1을;를; 부활시킵니다!', `FemaleText_loc4`='%s被附近的盟友复活了！', `FemaleText_loc5`='%s被附近的盟友復活了!', `FemaleText_loc7`='%s resucita gracias a un aliado cercano.' WHERE `ID`=10454;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시르밸라시여, 분노를 채워 주소서!', `MaleText_loc4`='西瓦尔拉，让我感受你的愤怒吧！', `MaleText_loc5`='希瓦拉爾，給我憤怒的力量吧!', `MaleText_loc7`='Shirvallah, ¡lléname de FURIA!' WHERE `ID`=10455;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사실이오, $n! 운명의 굴레가 방향을 바꾸었소! 학카르 님께서는 분명 재림할 것이오!', `MaleText_loc4`='这是真的，$n。厄运的车轮开始运转，一切都无可避免，哈卡将重返世间！', `MaleText_loc5`='這是真的，$n。厄運的車輪開始運轉，一切都無可避免，哈卡將重返世間!', `MaleText_loc7`='Es cierto, $n. Las ruedas de la perdición se dirigen, inevitablemente, hacia el regreso definitivo de Hakkar.' WHERE `ID`=10456;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='학카르의 피 님의 영혼이여! 하하하하!', `MaleText_loc4`='鲜血和灵魂，为了哈卡而战！哈哈哈！', `MaleText_loc5`='鮮血和靈魂，為了哈卡而戰!哈哈哈!', `MaleText_loc7`='¡Sangre y almas para Hakkar! ¡JAJAJAJA!' WHERE `ID`=10457;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='베티나, 여명의 문장으로 교체해 주세요!', `MaleText_loc4`='贝蒂娜，我想要黎明之印的替代物品！', `MaleText_loc5`='貝蒂娜，我想要黎明聖印的替代品!', `MaleText_loc7`='¡Betina, necesito un repuesto del Sello del Alba, por favor!', `FemaleText_loc1`='베티나, 여명의 문장으로 교체해 주세요!', `FemaleText_loc4`='贝蒂娜，我想要黎明之印的替代物品！', `FemaleText_loc5`='貝蒂娜，我想要黎明聖印的替代品!', `FemaleText_loc7`='¡Betina, necesito un repuesto del Sello del Alba, por favor!' WHERE `ID`=10458;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고맙다, 드디어... 학카르의 손아귀에서 벗어났도다!', `FemaleText_loc4`='我祝福你，凡人。你给了我自由……哈卡再也无法控制我了！', `FemaleText_loc5`='祝福你，凡人，你給了我自由...哈卡再也無法控制我了!', `FemaleText_loc7`='Benditos, mortales, por haberme liberado... Hakkar ya no me controla.' WHERE `ID`=10459;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제서야... 안식을...!', `MaleText_loc4`='宁静……终于来临了！', `MaleText_loc5`='寧靜...終於來臨了!', `MaleText_loc7`='¡Calma... al fin!' WHERE `ID`=10460;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='베데크시여, 저에게 힘을 내려주소서!', `FemaleText_loc4`='贝瑟克，你的祭司在召唤你的力量！', `FemaleText_loc5`='比塞克，你的祭司在召喚你的力量!', `FemaleText_loc7`='Bethekk, ¡tu sacerdotisa invoca tu poder!' WHERE `ID`=10461;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='베티나, 여명의 룬으로 교체해 주세요!', `MaleText_loc4`='贝蒂娜，我想要黎明符文的替代物品！', `MaleText_loc5`='貝蒂娜，我想要黎明符文的替代品!', `MaleText_loc7`='¡Betina, necesito un repuesto de la Runa del Alba, por favor!', `FemaleText_loc1`='베티나, 여명의 룬으로 교체해 주세요!', `FemaleText_loc4`='贝蒂娜，我想要黎明符文的替代物品！', `FemaleText_loc5`='貝蒂娜，我想要黎明符文的替代品!', `FemaleText_loc7`='¡Betina, necesito un repuesto de la Runa del Alba, por favor!' WHERE `ID`=10462;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 잔달라의 로아, 잔자라오. 동족을 돕기 위해 잔달라에서 이 에테리얼 형상을 하게 됐소이다. 학카르는 결코 내 영혼을 지배하지 못하오.$B$B난 잔달라 부족을 돕는 이들을 돕는 일을 하고 있소.', `MaleText_loc4`='我是赞达拉的赞扎。我以灵体形态从赞达拉赶来帮助我的人民。哈卡不能控制我的灵魂。$B$B我是来帮助那些曾经有恩于赞达拉的朋友的。', `MaleText_loc5`='我是贊達拉的贊札。我用以太形態從贊達拉趕來幫助我的人民。哈卡不能控制我的靈魂。$B$B我是來幫助那些曾經有恩於贊達拉的朋友的。', `MaleText_loc7`='Soy Zanza, un Dios de Zandalar. He venido desde Zandalar en esta forma etérea para ayudar a los míos. Hakkar no puede dominar mi alma.$B$BAyudo a aquellos que han ayudado al pueblo de Zandalar.' WHERE `ID`=10463;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 잔달라 부족의 친구로군! 당신은 혈신의 소굴 깊은 곳으로 들어왔소. 그러니 내가 하는 말을 잘 들어야 할 거요.$B$B지금으로부터 수천 년 전, 줄아만 제국의 토착 트롤들이 하이 엘프 침략자들과 싸울 때 이 잔자의 위대한 주술이 도둑을 맞았소. 하이 엘프들은 훔친 주술로 무기와 방어구에 마법을 걸어 이 지역의 트롤들을 완전히 정복하려 했소.', `MaleText_loc4`='赞达拉的朋友！你已经去过了血神巢穴的深处，$c。你最好仔细听我说。$B$B数千年前，当祖拉曼帝国的巨魔与入侵的高等精灵异教徒作战时，高等精灵盗取了赞扎的强大魔法，在自己的武器和护甲上附魔，以此征服当地的巨魔。', `MaleText_loc5`='贊達拉的朋友!你已經進入血神的巢穴深處，$c。你最好仔細聽我說。$B$B數千年前，當祖阿曼帝國的食人妖與入侵的高等精靈異教徒作戰時，高等精靈盜取了贊札強大的魔法，在自己的武器和護甲上附魔，以此征服當地的食人妖。', `MaleText_loc7`='¡$gUn amigo:una amiga; del pueblo de Zandalar! Te has aventurado en las profundidades de la guarida del Dios de la Sangre, $c. Harás bien en escuchar lo que tengo que decirte.$B$BMiles de años atrás, mientras los trols indígenas del imperio Zul''Aman luchaban contra los paganos elfos nobles que intentaban invadir su territorio, una magia muy poderosa fue robada en Zanza. Los elfos nobles utilizaron esta magia para encantar sus armas y armaduras para ayudarles en la conquista de la región.' WHERE `ID`=10464;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 마법에 대해 들어 본 것 같습니다.', `MaleText_loc4`='我想我听说过这种魔法。', `MaleText_loc5`='我想我聽說過這種魔法。', `MaleText_loc7`='Creo que he oído hablar de esta magia.', `FemaleText_loc1`='그 마법에 대해 들어 본 것 같습니다.', `FemaleText_loc4`='我想我听说过这种魔法。', `FemaleText_loc5`='我想我聽說過這種魔法。', `FemaleText_loc7`='Creo que he oído hablar de esta magia.' WHERE `ID`=10465;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래? 그렇다면, 하이 엘프들이 사용하는 트롤 주술이 아주 약하고 형편없다는 것도 알고 있소?$B$B하이 엘프들은 자신들의 마력과 비슷한 트롤 주술에 왜 맞설 수 없는지 의아해 했지만, 트롤 주술이란 허여멀건 얼굴의 하이 엘프 놈들 따위는 절대로 이해할 수 없는 것이오. 결국, 트롤 주술의 흉내만 내는 하급 마법을 사용하는 데 그치고 말더군. 놈들은 그걸 ''영석''이라고 부르는 모양이오.', `MaleText_loc4`='是吗？这么说你已经知道高等精灵所掌握的巨魔魔法有多么浅显了？$B$B高等精灵怎么都想不明白，作为一个与魔法密切相关的种族，他们为何无法驾驭巨魔巫毒的力量。对这些白皮肤的生灵而言，这简直难以置信。他们只好使用一种不纯的巨魔法术来增强他们的魔法力量。我想他们称其为“秘药”。', `MaleText_loc5`='是嗎?這麼說你已經知道高等精靈所掌握的食人妖魔法有多麼淺顯了?$B$B高等精靈怎麼都想不明白，作為一個與魔法密切相關的種族，他們為何無法駕馭食人妖巫毒的力量。對這些白皮膚的生靈而言，這簡直難以置信。他們只好使用一種不純的食人妖法術來增強他們的魔法力量。我想他們稱其為「秘紋」。', `MaleText_loc7`='¿Ah, sí? ¿Entonces sabrás lo débil y patética que era la versión de los elfos nobles de la magia trol?$B$BLos elfos nobles no pudieron comprender cómo un pueblo, con su afinidad con la magia, no era capaz de competir con los poderes del vudú trol. Era una noción inconcebible para los pieles blancas, nunca llegaron a entenderlo. Se resignaron a utilizar la versión envilecida de los encantamientos trol. Creo que llamaron a esta versión, ''arcano''.' WHERE `ID`=10466;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영석이요? 그것도 들어 본 것 같네요.', `MaleText_loc4`='秘药？听起来很耳熟呢。', `MaleText_loc5`='秘紋?聽起來很耳熟。', `MaleText_loc7`='¿Arcanum? Me resulta muy familiar.', `FemaleText_loc1`='영석이요? 그것도 들어 본 것 같네요.', `FemaleText_loc4`='秘药？听起来很耳熟呢。', `FemaleText_loc5`='秘紋?聽起來很耳熟。', `FemaleText_loc7`='¿Arcanum? Me resulta muy familiar.' WHERE `ID`=10467;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잔자에게 알맞은 재료만 주면 고대 트롤 주술을 사용할 수 있소. 그 마법은 학카르와 그의 부하들을 무찌르는 데 큰 도움이 될 거요.$B$B자, 두 가지 물건만 가져다주시오.', `MaleText_loc4`='赞扎能制造古老的附魔物品。这种魔法可以帮助你打败哈卡和他的爪牙。$B$B我只要你帮我找3种东西。我承认有一样东西不是必需的，但是我想净化那些高等精灵的魔法。', `MaleText_loc5`='只要有正確的材料，贊札就能製造古老的食人妖附魔。這種魔法能幫助你打敗哈卡和他的爪牙。$B$B我只要你幫我找2種東西。', `MaleText_loc7`='Zanza puede crear los antiguos encantamientos trols con los componentes necesarios. La magia te ayudará para vencer a Hakkar y a sus esbirros.$B$BSolo te pido que me traigas dos objetos.' WHERE `ID`=10468;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 재료가 뭡니까?', `MaleText_loc4`='我需要些什么？', `MaleText_loc5`='需要哪些材料?', `MaleText_loc7`='¿Cuáles son los componentes?', `FemaleText_loc1`='그 재료가 뭡니까?', `FemaleText_loc4`='我需要些什么？', `FemaleText_loc5`='需要哪些材料?', `FemaleText_loc7`='¿Cuáles son los componentes?' WHERE `ID`=10469;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='첫 번째 재료는 고대 학카리 휘장이요. 학카르 부족의 가장 강력한 지휘자인 진도와 혈군주에게서 얻을 수 있지.$B$B두 번째는 구멍 난 부두 인형인데, 타락한 이 땅의 이곳저곳에 버려진 쓰레기 더미를 뒤져보면 찾을 수 있을 거요. 특히 불길한 흑마술 더미 안을 눈여겨 보시오.$B$B이 두 가지 재료를 모두 가져오면 당신에게 강력한 마법을 허락하겠소!', `MaleText_loc4`='首先，必须要有一个从最强大的哈卡莱信徒那里夺来的原始哈卡莱神像，去打败金度和血领主曼多基尔吧！$B$B然后，还要有一个打孔的巫毒人偶。你可以在这一带的垃圾堆中找到它们，多留意一下那些厄运巫毒堆。把这些东西都给我拿来，我就给你一种强大的附魔！', `MaleText_loc5`='首先你得從強大的哈卡副官:金度和血領主那裡獲得一個原始的雕像。$B$B第二是打孔的巫毒人偶。你可以在散落此地的霉運巫毒垃圾堆中找到。$B$B把這些物品都給我找來，我會為你進行一次強效的附魔!', `MaleText_loc7`='El primero es un objeto primigenio que protegen los tenientes más poderosos de Hakkari: Jin''do y el Señor de la Sangre.$B$BEl segundo, es un muñeco de vudú agujereado. Puedes encontrarlo en las pilas de desperdicios que hay esparcidas por todas partes. Busca dentro de los montones hudú malditos.$B$BTráeme esos objetos y crearé un poderoso encantamiento para ti.' WHERE `ID`=10470;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c 친구, 미안하지만 전쟁노래 협곡에 들어가기엔 훈련이 아직 부족하군.', `MaleText_loc4`='很抱歉，$c，在你变得更加强大之前，我不能让你去战歌峡谷送死。', `MaleText_loc5`='很抱歉，$c，但是在你變得更加強大之前，我不能讓你去戰歌峽谷送死。', `MaleText_loc7`='Lo siento $c, pero no tienes la experiencia suficiente para entrar en la Garganta Grito de Guerra.', `FemaleText_loc1`='$c 친구, 미안하지만 전쟁노래 협곡에 들어가기엔 훈련이 아직 부족하군.', `FemaleText_loc4`='很抱歉，$c，在你变得更加强大之前，我不能让你去战歌峡谷送死。', `FemaleText_loc5`='很抱歉，$c，但是在你變得更加強大之前，我不能讓你去戰歌峽谷送死。', `FemaleText_loc7`='Lo siento $c, pero no tienes la experiencia suficiente para entrar en la Garganta Grito de Guerra.' WHERE `ID`=10471;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 귀여운 것들아, $n|1을;를; 잡아먹어라!', `FemaleText_loc4`='吞噬$n的躯体吧！', `FemaleText_loc5`='吞噬$n的軀體吧，我的小可愛們!', `FemaleText_loc7`='¡Daos un festín con $n, mis pequeños!' WHERE `ID`=10472;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 한 가지 일만 더 하면 영혼약탈자의 위협을 완전히 제거할 수 있겠군...', `MaleText_loc4`='我们就要摆脱夺灵者的威胁了，只差最后一步……', `MaleText_loc5`='只差最後一步，我們就可以擺脫奪魂者的威脅了...', `MaleText_loc7`='Ahora, solo un paso más para poder librarnos de la amenaza del Cazador de Almas...' WHERE `ID`=10473;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나의 종복들이여, 의식을 시작하라! 학카르의 심장을 다시 공허의 차원으로 쫓아내야 한다!', `MaleText_loc4`='开始仪式，我的仆从们。我们必须把哈卡完全打回扭曲虚空中！', `MaleText_loc5`='開始儀式，我的僕從們。我們必須把哈卡之心放逐到虛無中!', `MaleText_loc7`='Comenzad el ritual, sirvientes. ¡Debemos desterrar el corazón de Hakkar al vacío!' WHERE `ID`=10474;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='매주 낚시왕 선발대회가 열리는 무법항에 오신 걸 환영합니다!

대회가 시작되면, 가시덤불 골짜기 전역의 낚시터에서 맛둥어를 낚을 수 있습니다.', `MaleText_loc4`='欢迎参加藏宝海湾钓鱼比赛，每周我们都会向全艾泽拉斯最好的渔夫发放奖励。

钓鱼比赛开始后，你在荆棘谷的任何渔点都可以钓到可口鱼。', `MaleText_loc5`='歡迎參加藏寶海灣釣魚比賽，每週我們都會獎勵權艾澤拉斯最好的漁夫。

釣魚大賽開始以後，你便能在荊棘谷任何的釣魚魚點上抓到可口魚。', `MaleText_loc7`='$gBienvenido:Bienvenida; al concurso de pesca de Bahía del Botín, donde cada semana elegimos a los mejores pescadores de todo Azeroth.

Cuando comience el torneo de pesca, podrás capturar pezricos de cualquier nodo de pesca de Tuercespina.' WHERE `ID`=10475;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오게. 나는 라스타칸 님의 종복인 엑잘이라고 하네.', `MaleText_loc4`='你好，$c。我是拉斯塔哈的仆从伊克萨尔。', `MaleText_loc5`='你好，$c。我是拉斯塔哈的僕從，伊克薩爾。', `MaleText_loc7`='Saludos, $c. Soy Exzhal, Siervo de Rastakhan.' WHERE `ID`=10476;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='1분 후 전투가 시작됩니다.', `MaleText_loc4`='战斗将在1分钟后开始。', `MaleText_loc5`='戰鬥將在1分鐘後開始。', `MaleText_loc7`='La batalla comenzará en 1 minuto.', `FemaleText_loc1`='1분 후 전투가 시작됩니다.', `FemaleText_loc4`='战斗将在1分钟后开始。', `FemaleText_loc5`='戰鬥將在1分鐘後開始。', `FemaleText_loc7`='La batalla comenzará en 1 minuto.' WHERE `ID`=10477;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='30초 후 전투가 시작됩니다.', `MaleText_loc4`='战斗将在30秒后开始。', `MaleText_loc5`='戰鬥將在30秒後開始。', `MaleText_loc7`='La batalla comenzará en 30 segundos.', `FemaleText_loc1`='30초 후 전투가 시작됩니다.', `FemaleText_loc4`='战斗将在30秒后开始。', `FemaleText_loc5`='戰鬥將在30秒後開始。', `FemaleText_loc7`='La batalla comenzará en 30 segundos.' WHERE `ID`=10478;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투가 시작되었습니다!', `MaleText_loc4`='战斗开始了！', `MaleText_loc5`='戰鬥開始了!', `MaleText_loc7`='¡La batalla ha comenzado!', `FemaleText_loc1`='전투가 시작되었습니다!', `FemaleText_loc4`='战斗开始了！', `FemaleText_loc5`='戰鬥開始了!', `FemaleText_loc7`='¡La batalla ha comenzado!' WHERE `ID`=10479;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 하루살이들의 함정에 현혹되지 말지어다. 자, 나의 힘에 흠뻑 취하라! 새로운 힘을 얻어 저 이교도들을 처단하라!', `MaleText_loc4`='不要误入凡人设下的陷阱。沐浴我的力量吧！恢复精力，消灭异教徒！', `MaleText_loc5`='不要誤入凡人設下的陷阱。沐浴我的力量吧!恢復精力，消滅異教徒!', `MaleText_loc7`='No caigas en la trampa de los mortales. ¡Báñate en mi poder! ¡Siéntete $grenovado:renovada; y destruye a los herejes!' WHERE `ID`=10480;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c 친구, 미안하지만 알터랙 계곡에서 살아남을 수 있으려면 더 많은 경험을 쌓아야 한다네.', `MaleText_loc4`='很抱歉，$c，在你变得更加强大之前，我不能让你去奥特兰克山谷送死。', `MaleText_loc5`='很抱歉，$c，但是在你變得更有經驗之前，我不能讓你去奧特蘭克山谷送死。', `MaleText_loc7`='Lo siento, $c, pero necesitas más experiencia para sobrevivir en el Valle de Alterac.', `FemaleText_loc1`='$c 친구, 미안하지만 알터랙 계곡에서 살아남을 수 있으려면 더 많은 경험을 쌓아야 한다네.', `FemaleText_loc4`='很抱歉，$c，在你变得更加强大之前，我不能让你去奥特兰克山谷送死。', `FemaleText_loc5`='很抱歉，$c，但是在你變得更有經驗之前，我不能讓你去奧特蘭克山谷送死。', `FemaleText_loc7`='Lo siento, $c, pero necesitas más experiencia para sobrevivir en el Valle de Alterac.' WHERE `ID`=10481;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마력의 보물이란 무엇입니까?', `MaleText_loc4`='权力珍宝是什么？', `MaleText_loc5`='權力珍寶是什麼?', `MaleText_loc7`='¿Qué son los Dechados de Poder?', `FemaleText_loc1`='마력의 보물이란 무엇입니까?', `FemaleText_loc4`='权力珍宝是什么？', `FemaleText_loc5`='權力珍寶是什麼?', `FemaleText_loc7`='¿Qué son los Dechados de Poder?' WHERE `ID`=10482;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마력의 보물은 고대 구루바시 제국의 유물로서 우리 잔달라 부족이 찾고 있는 물건이지요. 우리에겐 가치가 엄청날 뿐 아니라 고대 제국에서 사용하던 마법의 힘이 잠들어 있다고 믿고 있습니다.$B$B줄구룹에서는 세 가지 보물을 발견하게 될 겁니다. 바로 주화와 장신구, 그리고 고대 전투 장비들이지요. 우리가 원하는 만큼 가져오면 상으로 잔달라 부족이 제작한 물건 중에서 가장 훌륭한 것을 받게 될 겁니다.', `MaleText_loc4`='权力珍宝是古代古拉巴什帝国的遗物。赞达拉部族正在寻找它们——它们不仅有着极大的收藏价值，而且我们相信它们还蕴藏着远古帝国的魔法。$B$B你可以在祖尔格拉布找到三种权力珍宝：硬币、珠宝和原始神灵的物品。收集到一定数量之后，把这些东西交给我们，我们就会送你一些赞达拉最好的工艺制品。', `MaleText_loc5`='權力珍寶是古代古拉巴什帝國的遺物。贊達拉部族正在尋找它們─它們不僅有著極大的收藏價值，而且我們相信它們還蘊藏著遠古帝國的魔法。$B$B你可以在祖爾格拉布找到三種權力珍寶:硬幣、珠寶和原始神靈的物品。收集到一定數量之後，把這些東西交給我們，我們就會送你一些贊達拉最好的工藝製品。', `MaleText_loc7`='Los Dechados de Poder son vestigios del antiguo Imperio Gurubashi. Nosotros los Zandalar los buscamos no solo por el hecho de coleccionarlos, sino porque creemos que tienen signos latentes de la magia utilizada por el viejo Imperio.$B$BEncontrarás tres tipos de Dechados en Zul''Gurub: monedas, preseas y objetos primigenios. Tráenoslos en las cantidades que necesitamos y recibirás como recompensa algunos de los mejores objetos que los Zandalar jamás han fabricado.', `FemaleText_loc1`='마력의 보물은 고대 구루바시 제국의 유물로서 우리 잔달라 부족이 찾고 있는 물건이지요. 우리에겐 가치가 엄청날 뿐 아니라 고대 제국에서 사용하던 마법의 힘이 잠들어 있다고 믿고 있습니다.$B$B줄구룹에서는 세 가지 보물을 발견하게 될 겁니다. 바로 주화와 장신구, 그리고 고대 전투 장비들이지요. 우리가 원하는 만큼 가져오면 상으로 잔달라 부족이 제작한 물건 중에서 가장 훌륭한 것을 받게 될 겁니다.', `FemaleText_loc4`='权力珍宝是古代古拉巴什帝国的遗物。赞达拉部族正在寻找它们——它们不仅有着极大的收藏价值，而且我们相信它们还蕴藏着远古帝国的魔法。$B$B你可以在祖尔格拉布找到三种权力珍宝：硬币、珠宝和原始神灵的物品。收集到一定数量之后，把这些东西交给我们，我们就会送你一些赞达拉最好的工艺制品。', `FemaleText_loc5`='權力珍寶是古代古拉巴什帝國的遺物。贊達拉部族正在尋找它們─它們不僅有著極大的收藏價值，而且我們相信它們還蘊藏著遠古帝國的魔法。$B$B你可以在祖爾格拉布找到三種權力珍寶:硬幣、珠寶和原始神靈的物品。收集到一定數量之後，把這些東西交給我們，我們就會送你一些贊達拉最好的工藝製品。', `FemaleText_loc7`='Los Dechados de Poder son vestigios del antiguo Imperio Gurubashi. Nosotros los Zandalar los buscamos no solo por el hecho de coleccionarlos, sino porque creemos que tienen signos latentes de la magia utilizada por el viejo Imperio.$B$BEncontrarás tres tipos de Dechados en Zul''Gurub: monedas, joyas y objetos primigenios. Tráenoslos en las cantidades que necesitamos y recibirás como recompensa algunos de los mejores objetos que los Zandalar jamás han fabricado.' WHERE `ID`=10483;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 서판에는 고대의 상형 문자와 무시무시한 힘을 지닌 주문이 새겨져 있습니다. 하지만 당신은 아무리 살펴봐도 그 의미를 알아낼 수가 없습니다.', `MaleText_loc4`='石板上篆刻着古老的图案，上面的文字蕴涵着可怕的力量，但是你无法理解它们的意思。', `MaleText_loc5`='石板上篆刻著古老的圖案，上面的文字蘊涵著可怕的力量，但是你無法理解它們的意思。', `MaleText_loc7`='Las marcas de esta tablilla muestran diagramas ancestrales e inscripciones de funestas palabras de poder, pero no puedes comprender el significado.' WHERE `ID`=10484;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 서판에는 광기의 구루바시 모조를 만드는 데 필요한 고대 상형 문자와 무시무시한 힘을 지닌 주문이 새겨져 있습니다...', `MaleText_loc4`='石板上篆刻着古老的图案，上面的文字蕴涵着可怕的力量，用来制造Gurubashi Mojo Madness……', `MaleText_loc5`='石板上篆刻著古老的圖案，上面的文字蘊涵著可怕的力量，用來製造古拉巴什瘋狂魔精...', `MaleText_loc7`='Las marcas de esta tablilla muestran diagramas ancestrales e inscripciones de funestas palabras de poder, utilizadas para crear Locura Mojo de Gurubashi...' WHERE `ID`=10485;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조제법을 배웁니다.', `MaleText_loc4`='学习配方。', `MaleText_loc5`='學習配方。', `MaleText_loc7`='Apréndete la receta.', `FemaleText_loc1`='조제법을 배웁니다.', `FemaleText_loc4`='学习配方。', `FemaleText_loc5`='學習配方。', `FemaleText_loc7`='Apréndete la receta.' WHERE `ID`=10486;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 서판에는 고대 상형 문자와 무시무시한 힘을 지닌 주문이 새겨져 있습니다.$B$B연금술 조제법인 것 같지만 지금 갖고 있는 기술로는 시도조차 해 볼 수가 없습니다...', `MaleText_loc4`='石板上篆刻着古老的图案，上面的文字蕴涵着可怕的力量。$B$B你相信这是一份炼金术配方，但是以你的技能还无法学习……', `MaleText_loc5`='石板上篆刻著古老的圖案，上面的文字蘊涵著可怕的力量。$B$B你相信這是一份鍊金術配方，但是以你的技能還無法學習...', `MaleText_loc7`='Las marcas de esta tablilla muestran diagramas ancestrales e inscripciones de funestas palabras de poder.$B$BCrees que se trata de una receta de alquimia, pero no puedes entenderla...' WHERE `ID`=10487;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='낚시는 느긋하게 할 수 있다는 점이 장점인 것 같습니다. 지난 일들을 회상한다든가 장래 계획을 세운다든가 생각할 시간이 생기니까 말이에요.$B$B아, 그리고 술 마시기에 아주 좋은 핑곗거리이기도 하지요. 아주 코가 비뚤어지도록 말입니다, 하하.', `MaleText_loc4`='在我看来，钓鱼的美妙之处在于其缓慢的节奏。人们可以在钓鱼的过程中思考、回想过去和计划未来。$B$B哦，当然这也是大醉的托辞。', `MaleText_loc5`='在我看來，釣魚的美妙之處在於其緩慢的節奏。人們可以在釣魚的過程中思考、回想過去和計畫未來。$B$B哦，當然這也是用來大醉一場的絕佳理由。', `MaleText_loc7`='Si me lo preguntas a mí, lo mejor sobre la pesca es la tranquilidad. Te da tiempo para pensar, para reflexionar sobre los eventos pasados y planear los futuros.$B$BOh, y también es una buena excusa para beber. Mucho.' WHERE `ID`=10488;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 줄자를 다시 가져다주셔서 감사합니다, $n! 이것만 있으면 더 큰 물고기를 낚을 수 있다고요, 장담합니다!', `MaleText_loc4`='再次感谢你找回了我的幸运卷尺，$n。这东西能帮我捕到更大的鱼呢！', `MaleText_loc5`='再次感謝你找回了我的幸運捲尺，$n。這東西能幫我捕到更大的魚呢!', `MaleText_loc7`='Gracias de nuevo por devolverme mi cinta métrica de la suerte, $n. ¡Juro que me ayuda a pescar peces más grandes!' WHERE `ID`=10489;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가즈란카를 잡고 싶습니다! 방법을 좀 가르쳐 주십시오!', `MaleText_loc4`='我要抓住加兹兰卡！告诉我怎么样才可以抓住它！', `MaleText_loc5`='我要抓住加茲蘭卡!告訴我怎麼樣才可以抓住它!', `MaleText_loc7`='¡Quiero coger a Gahz''ranka! ¡Dime cómo!', `FemaleText_loc1`='가즈란카를 잡고 싶습니다! 방법을 좀 가르쳐 주십시오!', `FemaleText_loc4`='我要抓住加兹兰卡！告诉我怎么样才可以抓住它！', `FemaleText_loc5`='我要抓住加茲蘭卡!告訴我怎麼樣才可以抓住它!', `FemaleText_loc7`='¡Quiero coger a Gahz''ranka! ¡Dime cómo!' WHERE `ID`=10490;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가즈란카를 낚으려면 특별한 진흙노린재 미끼가 필요할 겁니다. 내가 직접 만드는 물건이지요!$B$B일반 미끼로는 안 됩니다. 진흙노린재가 필요해요... 미끼에 꿰어서 그 지독한 썩은 내를 풍겨야 하거든요!$B$B진흙노린재를 잡으면 줄구룹에 있는 페이글의 낚시터로 가서 미끼를 던진 다음... 술이나 한 잔 들이켜며 기다리세요... 하지만 너무 오래 기다릴 필요는 없을 겁니다. 틀림없이 가즈란카가 소란을 떨며 나타날 테니까요!', `MaleText_loc4`='你需要一种特殊的臭泥鱼诱饵来捕捉加兹兰卡，这些鱼饵是我亲自制作的！$B$B但是除了鱼饵之外，你还需要臭泥鱼……你得把臭泥鱼放入诱饵，让它充满臭味！$B$B将做好的诱饵放到祖尔格拉布中的帕格渔点……然后就坐下来喝酒等待……你无需等太久，因为加兹兰卡肯定会迫不及待地上钩！', `MaleText_loc5`='你需要一種特殊的臭泥魚誘餌來捕捉加茲蘭卡。這些魚餌是我親自製作的!$B$B但是除了魚餌之外，你還需要臭泥魚...你得把臭泥魚放入誘餌，讓它充滿臭味!$B$B將做好的誘餌放到祖爾格拉布中的帕格漁場...然後就坐下來喝酒等待...你無需等太久，因為加茲蘭卡肯定會迫不及待地上鉤!', `MaleText_loc7`='Para coger a Gahz''ranka, necesitarás un cebo especial de Fangoapestoso. Yo mismo los hago.$B$BPero necesitarás algo más que el cebo; también vas a necesitar algunos Fangoapestosos... ¡Para ponerlos en el cebo y darle un olor rancio!$B$BCuando tengas los Fangoapestosos, lanza el cebo en Punta de Pagle, en Zul''Gurub... Y, a continuación, coge algo de beber y espera, pero no demasiado, ¡porque Gahz''ranka llegará rápidamente!' WHERE `ID`=10491;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내트, 진흙노린재 미끼를 사고 싶습니다!', `MaleText_loc4`='纳特，我想要购买一些臭泥鱼诱饵！', `MaleText_loc5`='納特，我想要購買一些臭泥魚誘餌!', `MaleText_loc7`='Nat, quiero comprar cebos de Fangoapestoso.', `FemaleText_loc1`='내트, 진흙노린재 미끼를 사고 싶습니다!', `FemaleText_loc4`='纳特，我想要购买一些臭泥鱼诱饵！', `FemaleText_loc5`='納特，我想要購買一些臭泥魚誘餌!', `FemaleText_loc7`='Nat, quiero comprar cebos de Fangoapestoso.' WHERE `ID`=10492;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='*위잉* *철컥*

낚시로봇 5000은 질 좋은 희귀종 물고기를 가져오면 내트 페이글이 수여하는 특별한 낚시용품으로 보상하도록 설계되어 있습니다. 물고기 요청 중...

*툭* *지지지*', `MaleText_loc4`='*吱吱**叮当*

我奉命收购肥美的稀有鱼类，用纳特·帕格的钓鱼用品来交换哦。收购鱼类啦。

*砰**嗡嗡*', `MaleText_loc5`='*吱吱**叮噹*

我奉命收購肥美的稀有魚類，用納特·帕格的釣魚用品來交換哦。收購魚類啦。

