UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스퀄! 네 홀은 내 손에 있다. 명령이다. 이 세계로 와라!', `MaleText_loc4`='斯古恩！我手中握着你的节杖，我召唤你进入这个世界！', `MaleText_loc5`='斯古恩!我手中握著你的權杖，我召喚你進入這個世界!', `MaleText_loc7`='¡Skwol! ¡Porto tu cetro! ¡Te ordeno que entres en este mundo!', `FemaleText_loc1`='스퀄! 네 홀은 내 손에 있다. 명령이다. 이 세계로 와라!', `FemaleText_loc4`='斯古恩！我手中握着你的节杖，我召唤你进入这个世界！', `FemaleText_loc5`='斯古恩!我手中握著你的權杖，我召喚你進入這個世界!', `FemaleText_loc7`='¡Skwol! ¡Porto tu cetro! ¡Te ordeno que entres en este mundo!' WHERE `ID`=10711;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까. 지휘관님께서 실종된 부인의 행방을 조사해 보라고 저를 여기로 보내셨습니다.', `MaleText_loc4`='你好，鲁特加尔。指挥官派我来这里收集他失踪的妻子的信息。', `MaleText_loc5`='你好，魯特加爾。指揮官派我來這裏收集他失蹤的妻子的資訊。', `MaleText_loc7`='¡Hola, Rutgar! El Comandante me envía para que consiga información acerca de su desaparecida esposa.', `FemaleText_loc1`='안녕하세요. 지휘관님께서 실종된 부인의 행방을 조사해 보라고 저를 여기로 보내셨어요.', `FemaleText_loc4`='你好，鲁特加尔。指挥官派我来这里收集他失踪的妻子的信息。', `FemaleText_loc5`='你好，魯特加爾。指揮官派我來這裏收集他失蹤的妻子的資訊。', `FemaleText_loc7`='¡Hola, Rutgar! El Comandante me envía para que consiga información acerca de su desaparecida esposa.' WHERE `ID`=10712;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='편히 앉게나. 얘기가 좀 길다네.$B$B우리가 실리더스에 처음 도착했을 때 여군주 마랄리스는 세나리온 요새의 나이트 엘프 중 가장 먼저 원정대에 참가했지. 우리는 지극히 평범한 일부터 진행했다네. 사라진 유물을 찾기 위해 곤충 집을 헤집을 조사단을 구성했지.', `MaleText_loc4`='你最好坐下，这是个很长的故事。$B$B当我们第一次来到希利苏斯时，玛尔利斯女士是塞纳里奥要塞中第一位加入远征队的暗夜精灵。我们的行程没有什么特别的：组队进入虫巢探险，寻找失落的神器。', `MaleText_loc5`='你最好坐下，這是個很長的故事。$B$B當我們第一次來到希利蘇斯時，瑪爾利斯女士是塞納里奧城堡中第一位加入遠征隊的夜精靈。我們的行程沒有什麼特別的:組隊進入蟲巢探險，尋找失落的神器。', `MaleText_loc7`='Es una larga historia así que es mejor que tomes asiento.$B$BCuando llegamos por primera vez a Silithus, la maestra Mar''alith fue la primera de los elfos de la noche del Fuerte Cenarion en unirse a la expedición. Nuestro día a día era de lo más normal: un grupo se aventuraba en las diversas colmenas para buscar artefactos perdidos.' WHERE `ID`=10713;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 위험한 일이었겠군요.', `MaleText_loc4`='那听上去很危险。', `MaleText_loc5`='那聽起來很危險。', `MaleText_loc7`='Eso parece peligroso.', `FemaleText_loc1`='아주 위험한 일이었겠군요.', `FemaleText_loc4`='那听上去很危险。', `FemaleText_loc5`='那聽起來很危險。', `FemaleText_loc7`='Eso parece peligroso.' WHERE `ID`=10714;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론이지! 곤충 집에는 온갖 실리시드가 득실거렸고 우리를 보면 바로 달려들었네.$B$B하이브레갈에서 이상한 문자가 새겨진 수정을 발견하기 전까지는 사실 별문제가 없었지. 그런데 여군주 마랄리스가 그 수정을 보자마자 뭔가에 홀린 듯 가까이 다가갔네. 마치 불을 보고 달려드는 나방 같았지! 그 작고 고운 뺨을 수정에 갖다 대더니 갑자기 기절했네. 우리는 깜짝 놀라 여군주 마랄리스를 둘러업고 최대한 빨리 그곳을 빠져나왔네!', `MaleText_loc4`='很明显！居住在虫巢中的异种虫并不欢迎我们的到来。$B$B一切进展顺利，直到我们在雷戈虫巢中发现了一块雕文水晶。她象飞蛾扑火一般急切地抓起水晶，把脸凑上去，精神也变得恍惚起来。队友们都很担心她。我们以最快的速度将她带出了虫巢！', `MaleText_loc5`='很明顯!蟲巢中住著各種不歡迎我們到來的異種蟲。$B$B一切進展順利，直到我們在雷戈蟲巢中發現了一塊雕紋水晶。她像飛蛾撲火一般往水晶靠過去!她把可愛的臉頰湊上去，精神也變得恍惚起來。隊友們都很擔心她。我們以最快的速度將她帶出了蟲巢!', `MaleText_loc7`='¡Lo es! Esas colmenas estaban atestadas de silítidos que no se alegraban mucho de vernos.$B$BTodo marchaba bien hasta que nos topamos con un cristal jeroglífico en Colmen''Regal. ¡La atrajo como si de un imán se tratase! Ella puso su bonita mejilla contra el cristal y al instante entró en un estado de trance. Naturalmente, todos estábamos muy preocupados. La cogimos y la sacamos de allí al momento.' WHERE `ID`=10715;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 후 여군주 마랄리스는 어떻게 됐습니까?', `MaleText_loc4`='她后来怎么样了？', `MaleText_loc5`='她後來怎麼樣了?', `MaleText_loc7`='¿Y qué pasó con ella después?', `FemaleText_loc1`='그 후 여군주 마랄리스는 어떻게 됐나요?', `FemaleText_loc4`='她后来怎么样了？', `FemaleText_loc5`='她後來怎麼樣了?', `FemaleText_loc7`='¿Y qué pasó con ella después?' WHERE `ID`=10716;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 여군주 마랄리스를 지휘관님께 데리고 갔네. 세나리온 의회의 드루이드라면 그녀를 고칠 수 있을 거로 생각했기 때문이지. 역시 드루이드는 뭔가 다르더군. 그들 덕분에 여군주 마랄리스는 정신을 차렸네. 다행히 그녀도 회복하고 해서 우리는 다시 조사를 시작할 수 있을 거라 생각했지.$B$B그 후 몇 주 동안은 브란 님도 돌아오실 예정이었고 해서 조직도 정비해 가며 별문제 없이 지냈지. 그러던 어느 날 뜻밖에 그녀가 우리 야영지에 찾아왔네.', `MaleText_loc4`='我们把她交给了指挥官，希望议会的德鲁伊能医好她。我们相信德鲁伊们能让她清醒过来。我们跟议会之间已经两清，该回去做自己的事情了。$B$B过了好几周，一切看来进展顺利。布莱恩仍然四处奔波，我们也正常地工作着。有一天，她突然出现在我们的营地里。', `MaleText_loc5`='我們把她交給了指揮官，希望議會的德魯伊能醫好她。我們相信德魯伊們能讓她清醒過來。我們跟議會之間已經兩清，該回去做自己的事情了。$B$B過了好幾週，一切看來進展順利。布萊恩仍然四處奔波，我們也正常地工作著。有一天，她突然出現在我們的營地裏。', `MaleText_loc7`='La llevamos ante el Comandante con la esperanza de que los druidas del Círculo pudieran ayudarla. En efecto, fueron capaces de conseguir que despertara. Supusimos que ya no teníamos nada más que hacer en el Círculo y que podíamos retomar nuestro trabajo.$B$BPasaron varias semanas y todo iba bien. Brann aún andaba por allí así que el trabajo estaba bien estructurado. Y un buen día, de repente, ella apareció en nuestro campamento.' WHERE `ID`=10717;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나탈리아가요?', `MaleText_loc4`='纳塔莉亚？', `MaleText_loc5`='娜塔莉亞?', `MaleText_loc7`='¿Natalia?', `FemaleText_loc1`='나탈리아가요?', `FemaleText_loc4`='纳塔莉亚？', `FemaleText_loc5`='娜塔莉亞?', `FemaleText_loc7`='¿Natalia?' WHERE `ID`=10718;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 얘기 제대로 듣고 있는 건가? 그럼 내가 대체 누구 얘기를 하고 있겠나? 그래, 맞아. 여군주 마랄리스였네. 어쨌든 우리를 찾아왔는데 기분이 썩 좋아 보이지 않았네. 그러더니 부탁을 하더군.', `MaleText_loc4`='你聋了吗？我还能指谁？当然是玛尔利斯女士。无论如何，她已经回来了，但是她的心情似乎不太好。她需要我们帮个忙。', `MaleText_loc5`='你聾了嗎?我還能指誰?當然是瑪爾利斯女士。無論如何，她已經回來了，但是她的心情似乎不太好。她需要我們幫個忙。', `MaleText_loc7`='¿Eres $gtonto:tonta;? ¿De quién iba a estar hablando si no? Sí, la chica, la maestra Mar''alith. En cualquier caso, ella estaba de vuelta y no de muy buen humor. Y entonces comenzaron las exigencias.' WHERE `ID`=10719;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 부탁을 말입니까?', `MaleText_loc4`='帮什么忙？', `MaleText_loc5`='幫什麼忙?', `MaleText_loc7`='¿Exigencias? ¿Qué exigencias?', `FemaleText_loc1`='무슨 부탁을 말인가요?', `FemaleText_loc4`='帮什么忙？', `FemaleText_loc5`='幫什麼忙?', `FemaleText_loc7`='¿Exigencias? ¿Qué exigencias?' WHERE `ID`=10720;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하이브레갈에 다시 가 달라고 했다네! 브란 님은 한동안 말이 없다가 군대의 지원 없이는 하이브레갈에 들어갈 방법이 없다고 하셨지. 그때는 하이브레갈이 더 위험한 곳으로 변해 있었으니 말이야. 그 끔찍한 벌레들의 수가 우리가 처음 들어갔을 때보다 3배는 많아진 것 같았지.$B$B그 말을 듣자마자 나탈리아가 갑자기 미쳐 버렸네!', `MaleText_loc4`='她要我们立即返回雷戈虫巢！布莱恩拒绝了她。他认为我们在没有军队支援的情况下是无法进入虫巢的。那样太危险了。跟我们首次进入虫巢相比，这些虫子的数量似乎膨胀了3倍。$B$B纳塔莉亚就是在那时得了失心疯的！', `MaleText_loc5`='她要我們立即返回雷戈蟲巢!布萊恩拒絕了她。他認為我們在沒有軍隊支援的情況下是無法進入蟲巢的。那樣太危險了。跟我們首次進入蟲巢相比，這些蟲子的數量似乎膨脹了3倍。$B$B娜塔莉亞就是在那時得了失心瘋的!', `MaleText_loc7`='¡Exigía que volviéramos inmediatamente a Colmen''Regal! ¡Qué descaro por su parte! Brann le dijo que era imposible volver a esas colmenas sin contar con el respaldo de un ejército. Se habían vuelto todavía más peligrosas. Esos apestosos insectos habían triplicado su número desde la primera vez que nos aventuramos en las colmenas.$B$B¡Y entonces fue cuando Natalia perdió la razón!' WHERE `ID`=10721;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미치다니요? 무슨 말입니까?', `MaleText_loc4`='失心疯？你说的是什么意思？', `MaleText_loc5`='失心瘋?你說的是什麼意思?', `MaleText_loc7`='¿Perder la razón? ¿Qué quieres decir con eso?', `FemaleText_loc1`='미치다니요? 무슨 말입니까?', `FemaleText_loc4`='失心疯？你说的是什么意思？', `FemaleText_loc5`='失心瘋?你說的是什麼意思?', `FemaleText_loc7`='¿Perder la razón? ¿Qué quieres decir con eso?' WHERE `ID`=10722;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미쳤다는 게 무슨 말인지 모르는 건가? 정신이 나갔단 말일세! 그녀는 우리에게 미친 듯이 달려들었네. 평소에는 여자를 절대 때리지 않는 내가 그녀의 공격에 당해 잠시 의식을 잃었다 깨보니 무척이나 화가 나더군. 브란님과 프랭칼 그리고 나는 원숭이와 함께 온 힘을 다해 그녀를 제압했네! 사실 그녀를 제압했다는 자체가 기적이었다고 할 수 있지. 그녀는 마치 누군가에게 조종을 당하는 것 같았다네!', `MaleText_loc4`='你认为我说的什么意思？她变得十分疯狂！那个女孩就在我们面前变疯了。一般来说我不会动手，但是当我从震惊中清醒过来的时候，我变得非常气愤。布莱恩，鲁特加尔，我，当然还有猴子，一起向她扑去！我们能挡开她真是一个奇迹。她好像完全被占据了！', `MaleText_loc5`='你認為我說的什麼意思?她變得十分瘋狂!那個女孩就在我們面前變瘋了。一般來說我不會動手，但是當我從震驚中清醒過來的時候，我變得非常氣憤。布萊恩，魯特加爾，我，當然還有猴子，一起向她撲去!我們能擋開她真是一個奇蹟。她好像完全被佔據了!', `MaleText_loc7`='¿Qué quieres decir, qué quieres decir...? Pues eso, ¡que se volvió loca! Empezó a golpes con nosotros y, aunque yo no tengo por costumbre pegar a una chica, cuando desperté tras haberme desvanecido, estaba furioso con ella. ¡Era como si Brann, Rutgar, el mono y yo fuéramos orcos a ojos de ella! Es un milagro que fuéramos capaces de evitar su ataque. ¡Estaba como poseída!' WHERE `ID`=10723;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누구에게 조종을 당했다는 겁니까?', `MaleText_loc4`='被什么占据了？', `MaleText_loc5`='被什麼佔據了?', `MaleText_loc7`='¿Poseída por qué?', `FemaleText_loc1`='누구에게 조종을 당했다는 건가요?', `FemaleText_loc4`='被什么占据了？', `FemaleText_loc5`='被什麼佔據了?', `FemaleText_loc7`='¿Poseída por qué?' WHERE `ID`=10724;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그걸 누가 알겠나? 아무튼 그 후로는 그녀를 본 적이 없네. 프랭칼이라면 쓸 만한 정보를 많이 알고 있을 걸세.$B$B그런데 얘기의 주제를 흐릴까 봐 이런 말은 안 하려고 했네만... 자네가 맡은 임무가 중요하다는 건 잘 알고 있네. 하지만 우리가 하고 있는 일도 중요하단 말일세. 그것도 매우 말이야! 아이언포지에 병력을 요청한 게 대체 언젠데 아직 아무런 소식이 없다는 게 말이 되는가? 이 넓은 지역을 방어하느라 말라 죽을 지경이네. 지휘관님께 보고한 후 동료를 데리고 다시 이곳으로 돌아와 주게나. 자네 도움이 필요하네!', `MaleText_loc4`='谁知道呢？无论如何，那是我最后一次见到她。或许弗兰卡能告诉你更多信息。$B$B别转移话题，我想指挥官给你的工作相当重要吧，但是我们也是来执行重要任务的！铁炉堡对我们请求军队增援的要求置若罔闻。很明显，以我们的力量难以保护这片土地。一旦你将报告交还给指挥官，就跟你的朋友一同回到这儿来。我们需要你的帮助！', `MaleText_loc5`='誰知道呢?無論如何，那是我最後一次見到她。或許法蘭克爾能告訴你更多資訊。$B$B別轉移話題，我想指揮官給你的工作相當重要吧，但是我們也是來執行重要任務的!鐵爐堡對我們請求軍隊增援的要求置若罔聞。很明顯，以我們的力量難以保護這片土地。一旦你將報告交還給指揮官，就跟你的朋友一同回到這兒來。我們需要你的幫助!', `MaleText_loc7`='¡Quién sabe! De cualquier modo, esa fue la última vez que la vi. Quizás Frankal pueda darte más datos.$B$BNo pretendo evitar este tema pues estoy seguro de que el trabajo que estás haciendo para el Comandante es importante, pero aquí estamos inmersos en algo muy grande. ¡REALMENTE GRANDE! Todas nuestras peticiones de un ejército a Forjaz hasta el momento han caído en saco roto. Parece ser que estamos en la obligación de proteger el reino u otra cosa sin sentido. Tras presentar tu informe ante el Comandante, regresa aquí con algunos amigos. ¡Necesitamos tu ayuda!' WHERE `ID`=10725;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 일만 해결되면 돌아오겠습니다.', `MaleText_loc4`='等我把这些搞定了就会立刻回来。', `MaleText_loc5`='等我把這些搞定了就會立刻回來。', `MaleText_loc7`='Volveré una vez que aclare este embrollo.', `FemaleText_loc1`='이 일만 해결되면 돌아올게요.', `FemaleText_loc4`='等我把这些搞定了就会立刻回来。', `FemaleText_loc5`='等我把這些搞定了就會立刻回來。', `FemaleText_loc7`='Volveré una vez que aclare este embrollo.' WHERE `ID`=10726;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑습니다, 프랭칼. 당신이 실종된 여군주 나탈리아 마랄리스에 대한 정보를 알고 있다고 들었습니다.', `MaleText_loc4`='你好，弗兰卡。我听说你知道纳塔莉亚的下落。', `MaleText_loc5`='你好，法蘭克爾。我聽說你知道娜塔莉亞的下落。', `MaleText_loc7`='Hola, Frankal. He oído que tienes información acerca del paradero de la maestra Natalia Mar''alith.', `FemaleText_loc1`='안녕하세요, 프랭칼. 당신이 실종된 여군주 나탈리아 마랄리스에 대한 정보를 알고 있다고 들었어요.', `FemaleText_loc4`='你好，弗兰卡。我听说你知道纳塔莉亚的下落。', `FemaleText_loc5`='你好，法蘭克爾。我聽說你知道娜塔莉亞的下落。', `FemaleText_loc7`='Hola, Frankal. He oído que tienes información acerca del paradero de la maestra Natalia Mar''alith.' WHERE `ID`=10727;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런, 또 그 이야기로군... 우선 앉으세요.$B$B루트거에게 대충은 들었을 테니 사소한 내용은 건너뛰고 핵심만 얘기하도록 하죠.', `MaleText_loc4`='哦，就是这样了……先找个椅子，$g小伙子:小姑娘;。$B$B我肯定鲁特加尔已经告诉你一些事情了，因此我将省略一些细节，让你直奔主题。', `MaleText_loc5`='哦，就是這樣了...先找個椅子，$g小夥子:小姑娘;。$B$B我肯定魯特加爾已經告訴你一些事情了，因此我將省略一些細節，讓你直奔主題。', `MaleText_loc7`='Oh no, otra vez no... Siéntate $gmuchacho:muchacha;.$B$BEstoy seguro de que Rutgar ya te ha contado algo así que me ahorraré los detalles e iré directo al grano.' WHERE `ID`=10728;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 좋습니다.', `MaleText_loc4`='这就是我希望听到的。', `MaleText_loc5`='這就是我希望聽到的。', `MaleText_loc7`='Es precisamente lo que me interesa.', `FemaleText_loc1`='네, 좋아요.', `FemaleText_loc4`='这就是我希望听到的。', `FemaleText_loc5`='這就是我希望聽到的。', `FemaleText_loc7`='Es precisamente lo que me interesa.' WHERE `ID`=10729;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 그때! 부인이 잠깐 정신을 차리는 것 같더니 바로 곤충 집으로 들어갔습니다. 브란 님이 말릴 새도 없이 말입니다! 전투가 시작되기 전에 그녀는 누군가와 이야기하기 시작했죠. 아니 물건이었던 것 같기도 하고... 어쨌든 대화를 했습니다. 그렇게 점점 미쳐가는 것 같더니 한 번도 들어본 적이 없는 언어로 주문을 외우기 시작했어요.', `MaleText_loc4`='好吧！她从虫巢回来过，但是布莱恩一点都没有察觉到！混战之前，她开始跟什么人交谈起来。奇怪的是，她用了一种我们从未听过的语言谈话。', `MaleText_loc5`='好吧!她從蟲巢回來過，但是布萊恩一點都沒有察覺到!混戰之前，她開始跟什麼人交談起來。奇怪的是，她用了一種我們從未聽過的語言談話。', `MaleText_loc7`='¡Estupendo! Pues la maestra había vuelto por segunda vez a las colmenas pero Brann no entendía nada de lo que estaba pasando. Antes de que reinara la confusión, ella empezó a hablar con algo o alguien. Y lo que es aún peor, empezó a salmodiar en un idioma extraño que ninguno de nosotros conocíamos.' WHERE `ID`=10730;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 이상한 일이군요.', `MaleText_loc4`='那真奇怪。', `MaleText_loc5`='那真奇怪。', `MaleText_loc7`='Eso es extraño.', `FemaleText_loc1`='정말 이상하네요.', `FemaleText_loc4`='那真奇怪。', `FemaleText_loc5`='那真奇怪。', `FemaleText_loc7`='Eso es extraño.' WHERE `ID`=10731;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇죠, 정말 이상한 일이죠! 브란 님과 루트거 그리고 저는 티탄의 두 종족인 바니르와 에시르의 언어까지 모두 38가지나 되는 언어를 알고 있는데 정말 이해할 수 없었어요. 물론 그 말은 원숭이의 언어도 아니었죠.$B$B그러니까 그녀가 무슨 말을 하는지는 몰랐지만 분명한 건 그곳에 저희 외에 다른 사람은 없었다는 겁니다. 그런데 그녀가 고개를 끄덕이더니 갑자기 공격을 시작하더군요! 그것도 저희를 완전히 죽일 둣이 말입니다!', `MaleText_loc4`='那还用说！布莱恩、鲁特加尔、猴子和我都对此感到陌生，我们懂38种语言，还略懂一点泰坦语——连瓦尼尔和艾斯尔都不例外。$B$B总之，她嘴里叽里咕噜说的话没人能懂。“礼物”？她点点头，就开始攻击我们！直接攻击我们！', `MaleText_loc5`='那還用說!布萊恩、魯特加爾、猴子和我都對此感到陌生，我們懂38種語言，還略懂一點泰坦語─連華納神族和阿薩神族都不例外。$B$B總之，無論她嘴裏嘰裏咕嚕在說些什麼，肯定都不是在跟「現場」的任何人對話。她點點頭，就開始攻擊我們!馬上攻擊我們!', `MaleText_loc7`='¡Y que lo digas! Sobre todo porque entre Brann, Rutgar, el mono y yo hablamos 38 idiomas, incluido un poco de titán, tanto vanir como aesir.$B$BEn todo caso, sea lo que fuere que decía, no hablaba con nadie que estuviera "presente". Después, asintió con la cabeza y pasó al ataque... ¡con todas sus fuerzas!' WHERE `ID`=10732;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나이트 엘프 여사제 한 명을 제압하기가 그렇게 어려웠다니 믿을 수가 없군요.', `MaleText_loc4`='你连一个落单的暗夜精灵女祭司都没法摆平？', `MaleText_loc5`='你連一個落單的夜精靈女祭司都沒法擺平?', `MaleText_loc7`='¿Y no fuisteis capaces de detener a una sola sacerdotisa elfa de la noche?', `FemaleText_loc1`='나이트 엘프 여사제 한 명을 제압하기가 그렇게 어려웠다니 믿을 수가 없군요.', `FemaleText_loc4`='你连一个落单的暗夜精灵女祭司都没法摆平？', `FemaleText_loc5`='你連一個落單的夜精靈女祭司都沒法擺平?', `FemaleText_loc7`='¿Y no fuisteis capaces de detener a una sola sacerdotisa elfa de la noche?' WHERE `ID`=10733;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 들어 보세요. 우릴 공격한 건 여사제가 낼 수 있는 그런 힘이 절대 아니었어요! 그녀의 눈은 악마와 같이 붉게 충혈되어 있었고 입에는 거품을 물고 있었단 말입니다. 정말이에요! 그녀는 미친 듯이 괴성을 질러대며 다가왔는데 우리를 각자 다른 곳으로 몰아 영혼을 하나씩 약탈하려는 것 같았어요. 내 머릿속에서 어둠의 목소리가 들려오기 시작했답니다. 주위를 둘러보니 동료도 하나씩 정신을 잃어가고 있었지요. 모두 미쳐가고 있었던 겁니다! 만약 저 원숭이가 없었다면 우린 모두 미쳐버렸을 겁니다.', `MaleText_loc4`='听着，$G小家伙:小姑娘;，你要知道，攻击我们的不是女祭司！她口吐白沫，眼睛闪着邪恶的光芒！她进来之后发出尖啸，我们被迫四下逃离，然后她便一个个地鞭荅我们的灵魂。我听见暗言术的声音，看着其他人不断倒下。要不是那该死的猴子，我们就全都玩完了！', `MaleText_loc5`='聽著$g小子:小姑娘;，我要讓你知道無論是什麼攻擊我們，她都不是隨便一個不知名的女祭司!她的眼裡發出邪惡的光芒，而且她真的口吐白沫!她靠過來，發出了某種瘋狂的尖嘯使得我們全都往不同的方向逃走，然後開始一個接一個地鞭笞我們的心靈。我聽到黑暗的文字在我的腦海中迴盪，眼前忽明忽暗。我瘋了!如果沒有那隻該死的猴子，我們可能已經玩完了。', `MaleText_loc7`='Mira $gchico:chica;, lo que nos atacó no era una simple sacerdotisa. ¡Sus ojos tenían un brillo maléfico y echaba espuma por la boca! Llegó, empezó a gritar a lo loco con lo que consiguió que cada uno de nosotros saliera corriendo en una dirección y finalmente empezó a destrozar nuestras mentes una a una. Yo empecé a oír palabras extrañas en mi cabeza y a ver cómo los demás perdían el conocimiento aquí y allá. ¡Era demencial! Hubiera sido nuestro fin de no ser por el condenado mono.' WHERE `ID`=10734;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 원숭이에 대해서 좀 더 알려주십시오.', `MaleText_loc4`='我想要问问你关于那只猴子的情况。', `MaleText_loc5`='我想要問問你關於那隻猴子的情況。', `MaleText_loc7`='Estaba pensando en preguntarte por el mono.', `FemaleText_loc1`='저 원숭이에 대해 좀 더 알려주세요.', `FemaleText_loc4`='我想要问问你关于那只猴子的情况。', `FemaleText_loc5`='我想要問問你關於那隻猴子的情況。', `FemaleText_loc7`='Estaba pensando en preguntarte por el mono.' WHERE `ID`=10735;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물어볼 게 뭐가 있겠습니까? 녀석은 말 그대로 원숭이일 뿐입니다. 그러니까 원숭이는 브란 님의 얼굴이 모래에 처박히는 걸 보더니 광분해서 그녀에게 달려들었습니다. 원숭이가 아니었더라면 그 나이트 엘프 여사제의 공격을 막아내지 못했을 겁니다.', `MaleText_loc4`='你要问些什么？你这个愚蠢的家伙，它是只猴子。在它看到布莱恩跌倒在沙土上时，它就发疯了。格里布狠狠教训了暗夜精灵一顿。', `MaleText_loc5`='你想問什麼?牠就是一隻猴子，你這個瘋狂的笨蛋。所以，反正就是，當那隻猴子看到老布萊恩忽然臉朝下地撲倒在地時，就變得狂暴了。那個夜精靈做不到的事情就是阻止格里布持續重擊她的頭。', `MaleText_loc7`='¿Preguntar qué? Es un mono, idiota. En cualquier caso, el mono se puso frenético al ver al viejo Brann caer desplomado sobre la arena. La elfa de la noche no podía hacer nada para detener a Glibb, que no paraba de darle golpes.' WHERE `ID`=10736;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래서 어떻게 됐습니까?', `MaleText_loc4`='然后呢？', `MaleText_loc5`='然後呢?', `MaleText_loc7`='¿Y entonces?', `FemaleText_loc1`='그래서 어떻게 됐나요?', `FemaleText_loc4`='然后呢？', `FemaleText_loc5`='然後呢?', `FemaleText_loc7`='¿Y entonces?' WHERE `ID`=10737;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그다음은 말이죠... 그녀는 곤충 집으로 곧장 달리기 시작했습니다. 그런데 더 이상한 게 뭔지 아세요? 바로 그 저주받은 벌레들 중 단 한 마리도 그녀를 막지 않았다는 겁니다. 그녀는 수 세기동안 녀석들의 친한 친구였던 듯이 녀석들 모두를 지나쳐 들어갔습니다.', `MaleText_loc4`='我会告诉你接下来发生了什么事。她直奔虫巢去了。还有什么比这更疯狂的事儿了吗？没有一支虫子阻挡她的去路。她直接从虫子身边跑过，就好像他们是交情很深的老朋友一样。', `MaleText_loc5`='我會告訴你的。她直直地往巢穴跑去。你知道有多瘋狂嗎? 竟然沒有一隻該死的蟲擋住她的路或是試圖阻止她。她用跑的穿過它們就像她跟它們當了好幾百年的朋友一般。', `MaleText_loc7`='Y entonces... Ella salió corriendo directamente hacia la colmena. ¿Y sabes qué es lo más gracioso? Que ni un solo bicho de esos se interpuso en su camino o intentó detenerla. Corría entre ellos como si fueran amigos de toda la vida.' WHERE `ID`=10738;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 놀라운 일이군요! 그러니까 그녀는 하이브레갈로 들어갔고 그 후론 그녀를 보지 못했다는 거군요?', `MaleText_loc4`='真是一个有意思的故事！那么说来她进入了雷戈虫巢，然后这就是你最后一次见到她了？', `MaleText_loc5`='真是一個有意思的故事!那麼說來她進入了雷戈蟲巢，然後這就是你最後一次見到她了?', `MaleText_loc7`='¡Menuda historia! ¿Así que se metió en Colmen''Regal y esa fue la última vez que la viste?', `FemaleText_loc1`='정말 놀라는 일이에요! 그러니까 그녀는 하이브레갈로 들어갔고 그 후론 그녀를 보지 못했다는 거군요?', `FemaleText_loc4`='真是一个有意思的故事！那么说来她进入了雷戈虫巢，然后这就是你最后一次见到她了？', `FemaleText_loc5`='真是一個有意思的故事!那麼說來她進入了雷戈蟲巢，然後這就是你最後一次見到她了?', `FemaleText_loc7`='¡Menuda historia! ¿Así que se metió en Colmen''Regal y esa fue la última vez que la viste?' WHERE `ID`=10739;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇습니다.', `MaleText_loc4`='是。', `MaleText_loc5`='沒錯。', `MaleText_loc7`='Ajá.' WHERE `ID`=10740;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정보를 주셔서 감사합니다, 프랭칼.', `MaleText_loc4`='感谢你提供的信息，弗兰卡。', `MaleText_loc5`='感謝你所提供的資訊，法蘭克爾。', `MaleText_loc7`='Gracias por la información, Frankal.', `FemaleText_loc1`='정보를 주셔서 감사합니다, 프랭칼.', `FemaleText_loc4`='感谢你提供的信息，弗兰卡。', `FemaleText_loc5`='感謝你所提供的資訊，法蘭克爾。', `FemaleText_loc7`='Gracias por la información, Frankal.' WHERE `ID`=10741;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너희를 제물로 바쳐야겠구나!', `FemaleText_loc4`='你是个不错的祭品！', `FemaleText_loc5`='你是個不錯的祭品!', `FemaleText_loc7`='¡Tú serás la ofrenda perfecta!' WHERE `ID`=10742;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='크툰 님이 이 세상을 다시 지배하게 될 것이다!', `FemaleText_loc4`='克苏恩将会重新夺取这个世界！', `FemaleText_loc5`='克蘇恩將會重新奪取這個世界!', `FemaleText_loc7`='¡C''Thun se hará de nuevo con el mundo!' WHERE `ID`=10743;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수정에 이해할 수 없는 복잡한 문양과 룬 문자가 새겨져 있습니다.', `MaleText_loc4`='水晶上布满了神秘的雕文和符文。你无法理解。', `MaleText_loc5`='水晶上布滿了神秘的雕紋和符文。你無法理解。', `MaleText_loc7`='El cristal está cubierto de complejos jeroglíficos y runas. No se entiende nada.' WHERE `ID`=10744;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바람의 돌로부터 아련한 속삭임이 들려옵니다...$B$B반갑구나. 기사단에 전할 소식이라도 있는 것이냐?', `MaleText_loc4`='从石头中传来很轻的声音……$B$B你好，渺小的凡人。你为圣殿骑士带来了什么消息？', `MaleText_loc5`='從石頭中傳來很輕的聲音...$b$b你好，渺小的凡人。你為聖殿騎士帶來了什麼消息?', `MaleText_loc7`='Se oye un susurro que proviene del interior de la piedra... $B$BSaludos, $gpequeñajo:pequeñaja;. ¿Tienes noticias para el templario?', `FemaleText_loc1`='바람의 돌로부터 아련한 속삭임이 들려옵니다...$B$B반갑구나. 기사단에 전할 소식이라도 있는 것이냐?', `FemaleText_loc4`='从石头中传来很轻的声音……$B$B你好，渺小的凡人。你为圣殿骑士带来了什么消息？', `FemaleText_loc5`='從石頭中傳來很輕的聲音...$b$b你好，渺小的凡人。你為聖殿騎士帶來了什麼消息?', `FemaleText_loc7`='Se oye un susurro que proviene del interior de la piedra... $B$BSaludos, $gpequeñajo:pequeñaja;. ¿Tienes noticias para el templario?' WHERE `ID`=10745;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바람의 돌로부터 맑은 목소리가 들려옵니다...$B$B신도 계급장은 어디에 있나? 네 녀석의 신분을 증명하지 못하면 군주님과 대화할 수 없다...', `MaleText_loc4`='从石头中传来清晰的声音……$B$B你的身份勋章在哪里？没有身份勋章的话，你就无法和公爵对话……', `MaleText_loc5`='從石頭中傳來清晰的聲音...$b$b你的身分勳章在哪裡?沒有身分勳章的話，你就無法和公爵對話...', `MaleText_loc7`='Se oye con claridad una voz que proviene del interior de la piedra... $B$B¿Dónde está tu medallón de estatus, $gpequeñajo:pequeñaja;? No debes hablar con un duque sin mostrar una prueba de tu título...', `FemaleText_loc1`='바람의 돌로부터 맑은 목소리가 들려옵니다...$B$B신도 계급장은 어디에 있나? 네 녀석의 신분을 증명하지 못하면 군주님과 대화할 수 없다...', `FemaleText_loc4`='从石头中传来清晰的声音……$B$B你的身份勋章在哪里？没有身份勋章的话，你就无法和公爵对话……', `FemaleText_loc5`='你的身分勳章在哪裡?沒有身分勳章的話，你就無法和公爵對話...', `FemaleText_loc7`='¿Dónde está tu medallón de estatus, $gpequeñajo:pequeñaja;? No debes hablar con un duque sin mostrar una prueba de tu título...' WHERE `ID`=10746;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바람의 돌로부터 맑은 목소리가 들려옵니다...$B$B신분을 증명했으니 네 얘기를 들어주도록 하지. 하지만 시간은 끌지 않도록 해라. 우리 의회는 너 같은 애송이의 쓸데없는 잡담 따윈 들어줄 시간이 없으니...', `MaleText_loc4`='从石头中传来清晰的声音……$B$B你带着你的头衔来找我们，我们将会聆听，但是不要试图考验我们的耐心，$c。议会没有时间来和你这样的凡人闲聊。', `MaleText_loc5`='從石頭中傳來清晰的聲音...$b$b你帶著你的頭銜來找我們，我們將會聆聽，但是不要試圖考驗我們的耐心，$c。議會沒有時間來和你這樣的凡人閒聊。', `MaleText_loc7`='Se oye con claridad una voz que proviene del interior de la piedra... $B$BYa que posees un título te escucharemos, pero no pongas a prueba nuestra paciencia, $c. El consejo no tiene tiempo para escuchar chismorreos de alguien como tú.', `FemaleText_loc1`='바람의 돌로부터 맑은 목소리가 들려옵니다...$B$B신분을 증명했으니 네 얘기를 들어주도록 하지. 하지만 시간은 끌지 않도록 해라. 우리 의회는 너 같은 애송이의 쓸데없는 잡담 따윈 들어줄 시간이 없으니...', `FemaleText_loc4`='从石头中传来清晰的声音……$B$B你带着你的头衔来找我们，我们将会聆听，但是不要试图考验我们的耐心，$c。议会没有时间来和你这样的凡人闲聊。', `FemaleText_loc5`='你帶著你的頭銜來找我們，我們將會聆聽，但是不要試圖考驗我們的耐心，$c。議會沒有時間來和你這樣的凡人閒聊。', `FemaleText_loc7`='Ya que posees un título te escucharemos, pero no pongas a prueba nuestra paciencia, $c. El consejo no tiene tiempo para escuchar chismorreos de alguien como tú.' WHERE `ID`=10747;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 심연의 군주에게 맞서는 놈이 누구냐? 죽고 싶은 것이 틀림없구나!', `MaleText_loc4`='议会领主面前出现了一只虫子？没错，无疑是一只想要被碾碎的虫子！', `MaleText_loc5`='議會領主面前出現了一隻蟲子?沒錯，無疑是一隻想要被碾碎的蟲子!', `MaleText_loc7`='¿Qué bicho se presenta antes los Señores del Consejo? ¡Sin duda, uno que quiere morir aplastado!', `FemaleText_loc1`='감히 심연의 군주에게 맞서는 놈이 누구냐? 죽고 싶은 것이 틀림없구나!', `FemaleText_loc4`='议会领主面前出现了一只虫子？没错，无疑是一只想要被碾碎的虫子！', `FemaleText_loc5`='議會領主面前出現了一隻蟲子?沒錯，無疑是一隻想要被碾碎的蟲子!', `FemaleText_loc7`='¿Qué bicho se presenta antes los Señores del Consejo? ¡Sin duda, uno que quiere morir aplastado!' WHERE `ID`=10748;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바람의 돌로부터 천둥 같은 고함 소리가 들려옵니다...$B$B어째서 신도 계급장만 있고 지휘관 반지는 없는 것이냐? 너는 진정 황혼의 망치단 소속 지휘관인게냐, 아니면 일개 심부름꾼이냐?', `MaleText_loc4`='从石头中传来雷霆般的声音……$B$B我感觉到你携带着身份勋章，教徒，但是你没有贵族之戒？你是不是真的是暮光之锤的指挥官，或者你只是一个跑腿的？', `MaleText_loc5`='從石頭中傳來雷霆般的聲音...$b$b我感覺到你攜帶著身分勳章，教徒，但是你沒有貴族之戒?你是不是真的是暮光之錘的指揮官，或者你只是一個跑腿的?', `MaleText_loc7`='Se oye una voz atronadora que proviene de la piedra... $B$BPuedo ver tu medallón de estatus pero no tienes un anillo de nobleza. ¿De verdad eres $gun auténtico:una auténtica; Comandante del Martillo Crepuscular o simplemente eres $gel recadero:la recadera; de tus superiores?', `FemaleText_loc1`='바람의 돌로부터 천둥 같은 고함 소리가 들려옵니다...$B$B어째서 신도 계급장만 있고 지휘관 반지는 없는 것이냐? 너는 진정 황혼의 망치단 소속 지휘관인게냐, 아니면 일개 심부름꾼이냐?', `FemaleText_loc4`='从石头中传来雷霆般的声音……$B$B我感觉到你携带着身份勋章，教徒，但是你没有贵族之戒？你是不是真的是暮光之锤的指挥官，或者你只是一个跑腿的？', `FemaleText_loc5`='從石頭中傳來雷霆般的聲音...$b$b我感覺到你攜帶著身分勳章，教徒，但是你沒有貴族之戒?你是不是真的是暮光之錘的指揮官，或者你只是一個跑腿的?', `FemaleText_loc7`='Se oye una voz atronadora que proviene de la piedra... $B$BPuedo ver tu medallón de estatus pero no tienes un anillo de nobleza. ¿De verdad eres $gun auténtico:una auténtica; Comandante del Martillo Crepuscular o simplemente eres $gel recadero:la recadera; de tus superiores?' WHERE `ID`=10749;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바람의 돌로부터 천둥 같은 고함 소리가 들려옵니다...$B$B대체 무슨 일이냐? 애송이 이교도 놈이 달아나고 있구나! 그래, 도망쳐라, 벌레 같은 놈. 아니면 심연의 군주로부터 진노를 사게 될 것이다!', `MaleText_loc4`='从石头中传来雷霆般的声音……$B$B这是什么？我感觉到一个小小的信徒在窜来窜去！快点走开，苦力，否则你将面对议会领主的愤怒！', `MaleText_loc5`='從石頭中傳來雷霆般的聲音...$b$b這是什麼?我感覺到一個小小的教徒在竄來竄去!快點走開，苦力，否則你將面對議會領主的憤怒!', `MaleText_loc7`='Se oye una voz atronadora que proviene de la piedra... $B$B¿Qué es esto? ¡Hay un pequeño cultor correteando por ahí! ¡Vete, alimaña o enfréntate a la cólera de los Señores del Consejo!', `FemaleText_loc1`='바람의 돌로부터 천둥 같은 고함 소리가 들려옵니다...$B$B대체 무슨 일이냐? 애송이 이교도 놈이 달아나고 있구나! 그래, 도망쳐라, 벌레 같은 놈. 아니면 심연의 군주로부터 진노를 사게 될 것이다!', `FemaleText_loc4`='从石头中传来雷霆般的声音……$B$B这是什么？我感觉到一个小小的信徒在窜来窜去！快点走开，苦力，否则你将面对议会领主的愤怒！', `FemaleText_loc5`='從石頭中傳來雷霆般的聲音...$b$b這是什麼?我感覺到一個小小的教徒在竄來竄去!快點走開，苦力，否則你將面對議會領主的憤怒!', `FemaleText_loc7`='Se oye una voz atronadora que proviene de la piedra... $B$B¿Qué es esto? ¡Hay un pequeño cultor correteando por ahí! ¡Vete, alimaña o enfréntate a la cólera de los Señores del Consejo!' WHERE `ID`=10750;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='노글, 넌 항상 우리 집안의 골칫덩어리였어. 언제나 말이야!', `FemaleText_loc4`='你总是家族中最爱惹麻烦的家伙，诺格。总是！', `FemaleText_loc5`='你總是家族中最愛惹麻煩的傢伙，諾格。總是!', `FemaleText_loc7`='Siempre has sido el alborotador de la familia, Noggle. ¡Siempre!' WHERE `ID`=10751;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탁본 장치를 사용하여 탁본을 수집합니다.', `MaleText_loc4`='<使用抄写工具来收集一份拓文。>', `MaleText_loc5`='<使用抄寫工具來收集一份拓文。>', `MaleText_loc7`='<Usa el transcriptor para obtener una copia.>', `FemaleText_loc1`='탁본 장치를 사용하여 탁본을 수집합니다.', `FemaleText_loc4`='<使用抄写工具来收集一份拓文。>', `FemaleText_loc5`='<使用抄寫工具來收集一份拓文。>', `FemaleText_loc7`='<Usa el transcriptor para obtener una copia.>' WHERE `ID`=10752;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디로 날아가고 싶습니까?', `MaleText_loc4`='你想要飞往什么地方？', `MaleText_loc5`='你想要飛往什麼地方?', `MaleText_loc7`='¿Adónde quieres volar?', `FemaleText_loc1`='어디로 날아가고 싶으세요?', `FemaleText_loc4`='你想要飞往什么地方？', `FemaleText_loc5`='你想要飛往什麼地方?', `FemaleText_loc7`='¿Adónde quieres volar?' WHERE `ID`=10753;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실리더스의 영혼이 우리를 부르고 있소, $n. 대지의 흐느낌이 뭔가 비통한 소식을 전하려는 듯 대지가 흐느끼고 있소...', `MaleText_loc4`='希利苏斯的灵魂召唤我们，$n。土地在哭泣，它有个悲惨的故事要告诉我们……', `MaleText_loc5`='希利蘇斯的靈魂召喚我們，$n。土地在哭泣，它有個悲慘的故事要告訴我們...', `MaleText_loc7`='Los espíritus de Silithus nos llaman, $n. La tierra llora pues tiene una triste historia que contar...' WHERE `ID`=10754;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 이상한 소리를 냅니다.', `MaleText_loc4`='%s发出奇怪的声音。', `MaleText_loc5`='%s發出一陣奇怪的噪音。', `MaleText_loc7`='%s emite un extraño sonido.' WHERE `ID`=10755;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하신가? $C 양반, 우리 만난 적이 있던가? 얼마 전 어떤 행사에서 말이야... 낯익은 얼굴이긴 한데 이 도시가 워낙 혼잡한 곳이라서 말이지.$B$B그 특별한 모임에 참석했다면 분명 비밀 암호도 받았을 테지. 그걸 내게 알려주면 특별한 상품을 주겠네.', `MaleText_loc4`='你好，$C。看来你最近在进行一项秘密的收集工作？你还是老样子，但是这是个繁忙的城市。$B$B如果你参加了那场会议，你就该得到一段神秘兑换码。把神秘兑换码告诉我，我就会给你一份特殊的奖励作为回报。', `MaleText_loc5`='你好，$C。看來你最近在進行一項秘密的收集工作?你還是老樣子，但是這是個繁忙的城市。$B$B如果你參加了那場會議，你就該得到一段驗證碼。把驗證碼告訴我，我就會給你一份特殊的獎勵作為回報。', `MaleText_loc7`='Ave, $c. ¿No te he visto hace poco en una reunión privada? Me suena tu cara pero esta ciudad está tan concurrida...$B$BSi has estado en esa reunión, te habrán dado un código secreto. Dime tu código y recibirás como recompensa un premio especial.', `FemaleText_loc1`='안녕하신가? $C 양반, 우리 만난 적이 있던가? 얼마 전 어떤 행사에서 말이야... 낯익은 얼굴이긴 한데 이 도시가 워낙 혼잡한 곳이라서 말이지.$B$B그 특별한 모임에 참석했다면 분명 비밀 암호도 받았을 테지. 그걸 내게 알려주면 특별한 상품을 주겠네.', `FemaleText_loc4`='你好，$C。看来你最近在进行一项秘密的收集工作？你还是老样子，但是这是个繁忙的城市。$B$B如果你参加了那场会议，你就该得到一段神秘兑换码。把神秘兑换码告诉我，我就会给你一份特殊的奖励作为回报。', `FemaleText_loc5`='你好，$C。看來你最近在進行一項秘密的收集工作?你還是老樣子，但是這是個繁忙的城市。$B$B如果你參加了那場會議，你就該得到一段驗證碼。把驗證碼告訴我，我就會給你一份特殊的獎勵作為回報。', `FemaleText_loc7`='Ave, $c. ¿No te he visto hace poco en una reunión privada? Me suena tu cara pero esta ciudad está tan concurrida...$B$BSi has estado en esa reunión, te habrán dado un código secreto. Dime tu código y recibirás como recompensa un premio especial.' WHERE `ID`=10756;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비밀 암호를 입력하고 제 멀록을 받고 싶습니다.', `MaleText_loc4`='我想要输入神秘兑换码来获得我的鱼人宠物。', `MaleText_loc5`='我想要輸入驗證碼以領取我的魚人寵物。', `MaleText_loc7`='Me gustaría introducir el código secreto para obtener mi múrloc.', `FemaleText_loc1`='비밀 암호를 입력하고 제 멀록을 받고 싶어요.', `FemaleText_loc4`='我想要输入神秘兑换码来获得我的鱼人宠物。', `FemaleText_loc5`='我想要輸入驗證碼以領取我的魚人寵物。', `FemaleText_loc7`='Me gustaría introducir el código secreto para obtener mi múrloc.' WHERE `ID`=10757;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n! 그대의 여정을 시작할 준비가 되어 있기를 바랍니다. 여기 선스트라이더 섬에는 할 일이 아주 많답니다.$B$B아서스와 스컬지에게 태양샘이 파괴된 후로, 우리 종족은 거친 바다를 표류하는 신세가 되었지요. 그리고 이제 세상에서 잊혀지느냐 마느냐의 갈림길에 서 있습니다. 하지만, 이 상황은 바뀔 것입니다. 그대의 도움으로 우리는 지난날로 돌아갈 수 있을 것이며, 그대도 많은 것을 배울 것입니다.$B$B아웃랜드가 우리를 기다리고 있습니다!', `FemaleText_loc4`='$n！我希望你已经准备好开始工作了，因为逐日岛这里有很多事需要你来做。$B$B自从阿尔萨斯和天灾军团破坏了太阳之井以后，我们就一直笼罩在命运的迷雾中，在毁灭的边缘挣扎着。$c，一切都会改变。怀着血精灵一族必将再次崛起的信念，伸出援手帮助我们走上复兴之路吧。$B$B外域等待着我们！', `FemaleText_loc5`='$n!我希望你已經準備好要工作了，因為在逐日者之島有很多事等著你做。$B$B自從阿薩斯和天譴軍團摧毀了太陽之井，我們就在海邊過著漂浮不定的生活。我們存活在被遺忘的邊緣。一切將會改變，$c，你將會學習很多的東西，並同時協助我們重建。$B$B外域正等著我們!', `FemaleText_loc7`='¡$n! Espero que vengas para ponerte a trabajar, porque tienes mucho que hacer aquí, en la isla del Caminante del Sol.$B$BDesde la destrucción de La Fuente del Sol por Arthas y la Plaga, somos una raza a la deriva en un mar de incertidumbres. Nos balanceamos al filo del olvido. Esto cambiará, $c. Al mismo tiempo que aprendes, ayudarás a nuestra recuperación.$B$B¡Terrallende nos espera!' WHERE `ID`=10758;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='세나리온 의회는 현명한 판단력으로 이 세계의 많은 비밀을 밝혀냈습니다. 장인들은 이 드루이드들의 말에 귀를 기울여야 할 것입니다.', `FemaleText_loc4`='塞纳里奥议会是睿智的，他们发现了很多有关大地的秘密。愿意聆听这些德鲁伊的教诲的工匠总是会得到许多宝贵的知识。', `FemaleText_loc5`='塞納里奧議會是睿智的，他們發現了很多有關大地的秘密。願意聆聽這些德魯伊的教誨的工匠總是會得到許多寶貴的知識。', `FemaleText_loc7`='El Círculo Cenarion es muy sabio y conoce muchos de los secretos de la tierra. Los artesanos harían bien en prestar atención a las palabras de estos druidas.' WHERE `ID`=10759;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='유령 같은 형상을 하고 불신에 가득 찬 눈초리로 아무 말 없이 당신을 응시합니다.', `FemaleText_loc4`='这个鬼魂一样的身影不信任地看着你，并且保持着沉默。', `FemaleText_loc5`='這個鬼魅般的身影不信任地看著你，並且保持著沉默。', `FemaleText_loc7`='La figura fantasmal te observa con desconfianza en sus ojos y permanece en silencio.' WHERE `ID`=10760;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 것을 가르쳐 줄 수 있는지 보여주십시오.', `MaleText_loc4`='让我看看我可以学些什么。', `MaleText_loc5`='讓我看我能學到什麼。', `MaleText_loc7`='Muéstrame lo que puedo aprender.', `FemaleText_loc1`='어떤 것을 가르쳐 줄 수 있는지 보여주십시오.', `FemaleText_loc4`='让我看看我可以学些什么。', `FemaleText_loc5`='讓我看看我可以學些什麼。', `FemaleText_loc7`='Muéstrame lo que puedo aprender.' WHERE `ID`=10761;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='최선을 다해 해독해서 제가 본 것을 설명해 드리도록 하죠.', `FemaleText_loc4`='我将尽力翻译这些东西，并描述我看到的一切。', `FemaleText_loc5`='我將盡力翻譯這些東西，並描述我看到的一切。', `FemaleText_loc7`='Haré todo lo posible por traducir y describir lo que veo.' WHERE `ID`=10762;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한때 태양 첨탑은 태양샘이 있던 아름다운 곳이었습니다. 비록 지금 우리의 삶은 완전히 엉망이 되어 버렸지만... 그래도 포기하지 않고 앞으로 나아갈 것입니다. 우리는 생존자들이니까요.$B$B이 험난한 시기에 블러드 엘프라면 반드시 누구에게도 의지하지 않고 살아남는 법을 배워야 합니다. 마법에 대한 끝없는 욕망에 빠져들기 전에 자신을 다스려야 합니다.', `MaleText_loc4`='太阳之塔曾经被太阳之井滋养着……但是现在，我们的生活完全被颠倒了，$n，即使是这样，我们还是坚持了下来。这是我们的出路，我们是幸存者。$B$B如果你是从这巨变中幸存下来的……如果你想要继续把握自己的命运，那么你必须学会怎么去生存。所有的血精灵都必须这么做。你必须在魔法控制你之前控制住你对它的渴望。', `MaleText_loc5`='曾經...日尖塔處於太陽之井旁的優渥位置。如今我們的生活方式從天堂掉落了地獄，$n，但我們仍在努力向前邁進。我們是倖存者，這是我們的生存方式。$B$B如果你想從這場動亂中活下來...靠自己的力量活下去，那你一定要學會如何生存。所有的血精靈都是如此。你一定要在心中對於魔法永無止境的渴望主宰你之前先主宰它。', `MaleText_loc7`='Hubo un tiempo en que la Aguja del Sol disfrutó de una buena ventaja sobre La Fuente del Sol. Nuestras vidas han dado un vuelco, $n, pero aun así debemos continuar. Somos así; somos supervivientes.$B$BSi quieres sobrevivir a estos tiempos tumultuosos y seguir adelante, DEBES aprender a sobrevivir. Todos los elfos de sangre deben hacerlo. Debes dominar tu insaciable hambre de magia antes de que ella te domine a ti.' WHERE `ID`=10763;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='블러드 엘프들이 살아남으려면 그대가 계속 우리를 도와주셔야 합니다! 다 같이 전력을 쏟아야 우리가 처한 어려움을 타개할 수 있습니다.$B$B일할 준비가 되었으면 시작해 봅시다.', `MaleText_loc4`='你为血精灵作出的贡献对我们的生存来说是十分重要的！我们必须尽全力把自己从泥潭中拔出来。$B$B如果你已经准备好了，那么就让我们开始吧。', `MaleText_loc5`='你對血精靈長久以來的貢獻是我們種族生存最重要的助力!我們一定要同心協力突破目前的困境。$B$B如果你已經做好了準備，那就讓我們開始吧。', `MaleText_loc7`='¡Tu continuo servicio a los elfos de sangre es crucial para nuestra supervivencia! Todos tenemos que ponernos manos a la obra para salir de este embrollo.$B$BSi estás $glisto:lista; para trabajar, empecemos.' WHERE `ID`=10764;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='젊은 $c|1이여;여;, 아는 것이야말로 진정한 힘입니다. 그대는 현명하니 앞으로도 많은 것을 배울 수 있을 것이며, 그대보다 아는 것이 많은 이들에게도 귀를 기울일 줄 알게 될 겁니다.$B$B태양샘이 파괴되기 전, 우리는 어리석게도 완벽한 문명의 정점에 도달했다는 자만심에 빠져 있었습니다. 그 때문에 스컬지에게 무릎을 꿇고 말았죠. 어떤 면에서 보면 현실에 눈을 뜨는 계기가 되었지만요.', `MaleText_loc4`='知识就是力量——真正的力量，我年轻的朋友。尽你所能地学习新知识吧，同时虚心向那些学有所成的智者请教，这才是明智的做法。$B$B在太阳之井被夷为平地之前，我们曾经愚蠢地认为自己的文明已经达到巅峰。在与亡灵天灾的战斗中，血精灵却遭遇惨败……这才让我们看清自己的处境。', `MaleText_loc5`='知識就是力量 - 真正的力量，我年輕的朋友。獲得越多知識就會讓你越有智慧，並且從那些有智慧的人身上學習吧。$B$B在太陽之井被夷平前，我們還自以為我們的文明發展已經攀上了最高峰。是天譴軍團迫使我們屈服...並且，看清這個事實。', `MaleText_loc7`='El conocimiento es poder; poder VERDADERO, joven aprendiz. Lo mejor que puedes hacer es acumular tanto como puedas y atender bien a quienes ya lo han hecho.$B$BAntes de arrasar La Fuente del Sol, nos engañábamos creyendo que habíamos alcanzado la cumbre de nuestra civilización. Necesitamos la Plaga para darnos cuenta... y, en cierto modo, volver a la realidad.' WHERE `ID`=10765;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연구에 결정적으로 중요한 순간에 찾아오셨군요! 그래도 괜찮습니다. 저와 함께 ''조용히'' 명상을 하신다면... 얼마든지 환영입니다.', `MaleText_loc4`='你在我研究的关键时刻帮了我一把！不用担心，如果你不介意的话，我欢迎你安静地投以注视……一定要“安静”哦。', `MaleText_loc5`='你在我研究最關鍵的時刻打擾了我!別擔心，歡迎你加入我一起安靜的沉思...重點是「安靜」，如果你不介意的話。', `MaleText_loc7`='¡Me has pillado en un momento crítico de mi investigación! No te preocupes, puedes unirte a mí en contemplación silenciosa... pero hago hincapié en "silenciosa", si no te importa.' WHERE `ID`=10766;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여행자님, 도시로 가시는 길이라면 중요한 일을 하나 맡아 주셔야겠어요!', `FemaleText_loc4`='要是你正准备去城里，那么我有些重要的事情需要你来做！', `FemaleText_loc5`='如果你正前往那座城市的話，那麼我有一件重要的事情要你去做!', `FemaleText_loc7`='Si te diriges a la ciudad, tengo algo importante que encomendarte.' WHERE `ID`=10767;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어서 오세요! 쑥스러워하지 마시고요.$b$b자, 제 자랑이자 기쁨인... 블라스텐하이머 5000 초특급 대포를 소개합니다! 정말 멋지지 않나요?', `FemaleText_loc4`='欢迎！上前来，不要害羞。$b$b这就是我最自豪的发明……雷管5000型超级大炮！她很漂亮，是不是？', `FemaleText_loc5`='歡迎!來喔，來喔，別害羞。這是我最自豪的發明...衝擊者5000型超級大砲!你說是不是很棒啊?', `FemaleText_loc7`='¡$gBienvenido:Bienvenida;! Adelante, no tengas vergüenza.$B$BEsto de aquí es mi mayor tesoro... ¡el Ultracañón Pimpampum 5000! ¿No es precioso?' WHERE `ID`=10768;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='블라스텐하이머 5000 초특급 대포는 어떻게 사용합니까?', `MaleText_loc4`='这个大炮怎么用？', `MaleText_loc5`='這大砲要怎麼用?', `MaleText_loc7`='¿Cómo se usa el cañón?', `FemaleText_loc1`='블라스텐하이머 5000 초특급 대포는 어떻게 사용하나요?', `FemaleText_loc4`='这个大炮怎么用？', `FemaleText_loc5`='這大砲要怎麼用?', `FemaleText_loc7`='¿Cómo se usa el cañón?' WHERE `ID`=10769;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='간단해요! 제게 다크문 게임 동전을 주시면, 제가 당신을 대포 안으로 던져 넣고 심지에 불을 붙이는 거죠.$B$B일단 대포가 발사되면 몸이 잠깐 붕 뜨게 될 거예요. 하지만 제가 지금 달아드릴 날개가 떨어지면서 빠르게 하강하게 될 거랍니다.$B$B당신은 판잣길 바로 근처 바닷가에 떠 있는 과녁을 향해 발사될 거예요.$B$B땅 위에 있을 때 날개를 떼어내지만 마세요... 아니면... 뭐... 하여튼 생명 보험 같은 건 없어요!', `FemaleText_loc4`='很简单！你只要给我一个暗月游戏代币，我就把你装进炮管，然后点燃引线。$B$B你被发射出去之后，能够在空中“漂浮”一会儿，但是这种情况不会持续很久。当然，你也可以脱掉我给你的“翅膀”，来加速下坠。$B$B你的目标就是码头边水面上的一个大型浮标。$B$B可不要在进入水域上空之前脱掉翅膀，否则……呃……我可不出售人身保险。', `FemaleText_loc5`='很簡單!你給我一個暗月遊戲代幣，我就把你塞進去，然後點火開砲。$B$B發射之後你會在空中「飄」上一陣子，但是只要把我給你的「翅膀」收掉就可以快速降落。$B$B瞄準的目標是木板道旁邊、浮在水面上的那個大標靶。$B$B人還飛在地面上方的時候千萬別收掉翅膀，否則的話...呃，我可不賣人壽保險。', `FemaleText_loc7`='¡Es muy sencillo! Me das una ficha de juego de la Luna Negra, te meto dentro y enciendo la mecha.$B$BEstarás "flotando" un rato después del lanzamiento, pero podrás descender si abres las "alas" que te daré.$B$BEstás apuntando a un gran objetivo que flota en el agua justo al final del paseo.$B$BIntenta no abrir las alas cuando todavía estás en tierra, o... bueno... ¡no vendo seguros de vida!' WHERE `ID`=10770;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 옛고향으로 돌아온 이유는 제 지식을 전달하기 위해서입니다. 제 주변의 정신없는 언데드와 달리 저는 저 나름의 이유로 이 실체 없는 삶을 선택했습니다.$B$B실리시드는 매우 위협적인 적입니다, $n. 저는 그들을 경멸하는 만큼이나 존중하는 법도 배웠습니다.$B$B실리시드가 그토록 강력한 것은 그들의 껍질이 강하면서도 가볍기 때문입니다. 그래서 저는 실리시드의 껍질로 방어구를 만드는 법을 익혔습니다. 우리는 같은 적과 싸우고 있는 것 같으니 당신에게 제가 갖고 있는 지식을 알려 드리겠습니다.', `FemaleText_loc4`='我回到我的故乡，以让我的知识得以延续。我和那些没有头脑的亡灵不一样，我出于自己的原因选择了现在的状态。$B$B异种虫类是强大的对手，$n。我学会了尊重它们和藐视它们。$B$B它们的致命之处在于它们外壳的构造，我可以将这些甲壳制成盔甲。我们有着同样的敌人，因此我可以把这种技能传授给你。', `FemaleText_loc5`='我回到我的故鄉，以讓我的知識得以延續。我和那些沒有頭腦的不死生物不一樣，我出於自己的原因選擇了現在的狀態。$B$B異種蟲類是強大的對手，$n。我學會了尊重它們和藐視它們。$B$B它們的致命之處在於它們外殼的構造，我可以將這些甲殼製成盔甲。我們有著同樣的敵人，因此我可以把這種技能傳授給你。', `FemaleText_loc7`='He regresado a mi antiguo hogar por lo que debo transmitir mis conocimientos. Al contrario que los estúpidos no-muertos que me rodean, yo he elegido esta forma de vida por mis propios motivos.$B$BLos silítidos son unos temibles oponentes, $n. Yo he aprendido a respetarlos tanto como a odiarlos.$B$BMucho de su poder de destrucción se debe a la fuerza y ligereza de su esqueleto, que he aprendido a utilizar para crear armaduras. Dado que tenemos un enemigo común, te enseñaré mi oficio.' WHERE `ID`=10771;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하십니까? 다크문 축제에 오신 것을 환영합니다. 아주 다양한 행사가 있기 때문에 처음 오신 분은 뭘 해야 할지 모르는 경우가 많아요. 전 그런 분들을 위해 축제 정보를 알려 드리는 도우미를 맡고 있습니다. 궁금한 사항이 있으신가요?', `FemaleText_loc4`='您好，$c，欢迎来到暗月马戏团。在马戏团可以做的事儿数不甚数，第一次来的客人可能会觉得有些不知所措。这就是我在这里帮忙的原因。您有什么问题吗？', `FemaleText_loc5`='您好，$c，歡迎來到暗月馬戲團。在馬戲團這裏有太多可以做的事情了，所以第一次來的客人可能感到有些不知所措。這就是我在這裡幫忙的原因。您有什麼問題嗎?', `FemaleText_loc7`='Hola, $c, y $gbienvenido:bienvenida; a la Feria de la Luna Negra. Hay tanto que hacer aquí que puede resultar un tanto abrumador para aquellos que nos visitan por primera vez. Por eso estoy aquí para ayudarte. ¿Tienes alguna pregunta?' WHERE `ID`=10772;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 물건을 구입할 수 있습니까?', `MaleText_loc4`='我可以购买什么？', `MaleText_loc5`='我可以購買什麼?', `MaleText_loc7`='¿Qué puedo comprar?', `FemaleText_loc1`='어떤 물건을 구입할 수 있나요?', `FemaleText_loc4`='我可以购买什么？', `FemaleText_loc5`='我可以購買什麼?', `FemaleText_loc7`='¿Qué puedo comprar?' WHERE `ID`=10773;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 좋은 질문이로군요! 다크문 축제에서는 다양한 물건을 구입할 수 있습니다. 음식과 음료가 필요하면 저쪽에 있는 스탬프나 실라니아의 전시장으로 가십시오.

좀 더 특이한 물건을 원하시면 라흐라를 찾아가십시오. 그녀는 세계 각지에서 온 희귀한 물건을 전문으로 취급하고 있습니다.

그리고 이 근처 어딘가에 돌아다니고 있을 플릭을 마주치면 공이랑 애완용 개구리도 살 수 있을 겁니다.', `MaleText_loc4`='问得好！我们马戏团有很多东西出售。如果您对食物和饮料感兴趣的话，那么您可以去斯塔姆和塞兰妮亚的小店看看。

如果您想要购买一些特别的东西，那么兰拉出售的货物会很适合您。她专门出售来自世界各地的珍稀物品。

另外从到处跑来跑去的弗里克那里购买可以用于投掷的球和宠物青蛙。', `MaleText_loc5`='一個很好的問題!我們馬戲團這裏有很多東西出售。如果您對食物和飲料感興趣的話，那麼您可以去斯塔姆和塞蘭妮亞的小店看看。

如果您想要購買一些特別的東西，那麼蘭拉出售的貨物將會很適合您。她擅長於從世界各地收集稀有的東西。

另外從到處跑來跑去的弗里克那裏購買可以用於投擲的球和寵物青蛙。', `MaleText_loc7`='¡Excelente pregunta! Tenemos muchas cosas en esta feria. Si quieres comida o bebida, dirígete a la barraca de Stamp y Sylannia.

Si por el contrario prefieres comprar algo más exótico, Lhara seguro que tiene lo que buscas pues su especialidad son las rarezas de todas las partes del mundo.

Y luego está Flik, que andará por ahí en alguna parte. Si lo encuentras verás que vende pelotas para lanzar y ranas para tener como mascotas.', `FemaleText_loc1`='아주 좋은 질문이로군요! 다크문 축제에서는 다양한 물건을 구입할 수 있어요. 음식과 음료가 필요하면 저쪽에 있는 스탬프나 실라니아의 전시장으로 가세요.

좀 더 특이한 물건을 원하시면 라흐라를 찾아가세요. 그녀는 세계 각지에서 온 희귀한 물건을 전문으로 취급하고 있습니다.

그리고 이 근처 어딘가에 돌아다니고 있을 플릭을 마주치면 공이랑 애완용 개구리도 살 수 있을 거예요.', `FemaleText_loc4`='问得好！我们马戏团有很多东西出售。如果您对食物和饮料感兴趣的话，那么您可以去斯塔姆和塞兰妮亚的小店看看。

如果您想要购买一些特别的东西，那么兰拉出售的货物会很适合您。她专门出售来自世界各地的珍稀物品。

另外从到处跑来跑去的弗里克那里购买可以用于投掷的球和宠物青蛙。', `FemaleText_loc5`='一個很好的問題!我們馬戲團這裏有很多東西出售。如果您對食物和飲料感興趣的話，那麼您可以去斯塔姆和塞蘭妮亞的小店看看。

如果您想要購買一些特別的東西，那麼蘭拉出售的貨物將會很適合您。她擅長於從世界各地收集稀有的東西。

另外從到處跑來跑去的弗里克那裏購買可以用於投擲的球和寵物青蛙。', `FemaleText_loc7`='¡Excelente pregunta! Tenemos muchas cosas en esta feria. Si quieres comida o bebida, dirígete a la barraca de Stamp y Sylannia.

Si por el contrario prefieres comprar algo más exótico, Lhara seguro que tiene lo que buscas pues su especialidad son las rarezas de todas las partes del mundo.

Y luego está Flik, que andará por ahí en alguna parte. Si lo encuentras verás que vende pelotas para lanzar y ranas para tener como mascotas.' WHERE `ID`=10774;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다크문 축제 상품권은 뭔가요?', `MaleText_loc4`='暗月马戏团奖券？', `MaleText_loc5`='暗月馬戲團獎品券?', `MaleText_loc7`='¿Vales para la Feria de la Luna Negra?', `FemaleText_loc1`='다크문 축제 상품권은 뭔가요?', `FemaleText_loc4`='暗月马戏团奖券？', `FemaleText_loc5`='暗月馬戲團獎品券?', `FemaleText_loc7`='¿Vales para la Feria de la Luna Negra?' WHERE `ID`=10775;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그거 안 물어보시면 어쩌나 했습니다. 다크문 축제 상품권으로 특별한 선물을 살 수 있습니다.$b$b상품권은 월간 퀘스트를 완료하거나 축제에서 게임을 즐기면 획득할 수 있습니다. 월간 퀘스트를 완료하면 축제 상품권을 대부분 모을 수 있지만, 게임을 매일 하면 더 좋은 결과가 있을 겁니다.$b$b상품권을 충분히 모으면 다크문 축제에 있는 여러 상인에게 사용할 수 있습니다.', `MaleText_loc4`='很高兴您问到这个问题。暗月马戏团奖券就是您兑换一些特别的奖品时所需要的货币！

您可以通过完成每月任务，以及玩马戏团内的各项游戏来获得奖券。$b$b每月任务奖励的奖券最多，但是每天玩游戏也是一个积累奖券的好方法。$b$b当您集满足够的奖券时，就可以到马戏团的各个商人处消费了。', `MaleText_loc5`='很高興您問到這個問題。暗月馬戲團獎品券是可以使用來兌換特別獎品的貨幣!$b$b獎品券可以透過每月任務或在馬戲團中玩各種遊戲獲得。$b$b完成每月任務可以獲得最多的獎品券，但是每天都玩各種遊戲是加速獲取的好方法。$b$b當您有足夠的獎品券時，可以和馬戲團內的諸多商人購買東西。', `MaleText_loc7`='Me alegro de que me hagas esa pregunta. Los vales para la Feria de la Luna Negra son tu moneda de cambio para conseguir regalos increíbles.$b$bLos vales son la recompensa por hacer las misiones mensuales y jugar a los juegos de la feria.$b$bAl completar las misiones mensuales ganarás el mayor número de vales, pero participar a diario también es una buena forma de conseguirlos.$b$bCuando ya tengas suficientes vales, puedes gastarlos en los diferentes puestos del recinto de la feria.', `FemaleText_loc1`='그거 안 물어보시면 어쩌나 했어요. 다크문 축제 상품권으로 특별한 선물을 살 수 있답니다.$b$b상품권은 월간 퀘스트를 완료하거나 축제에서 게임을 즐기면 획득할 수 있어요. 월간 퀘스트를 완료하면 축제 상품권을 대부분 모을 수 있지만, 게임을 매일 하면 더 좋은 결과가 있을 거예요.$b$b상품권을 충분히 모으면 다크문 축제에 있는 여러 상인에게 사용할 수 있답니다.', `FemaleText_loc4`='很高兴您问到这个问题。暗月马戏团奖券就是您兑换一些特别的奖品时所需要的货币！

您可以通过完成每月任务，以及玩马戏团内的各项游戏来获得奖券。$b$b每月任务奖励的奖券最多，但是每天玩游戏也是一个积累奖券的好方法。$b$b当您集满足够的奖券时，就可以到马戏团的各个商人处消费了。', `FemaleText_loc5`='很高興您問到這個問題。暗月馬戲團獎品券是可以使用來兌換特別獎品的貨幣!$b$b獎品券可以透過每月任務或在馬戲團中玩各種遊戲獲得。$b$b完成每月任務可以獲得最多的獎品券，但是每天都玩各種遊戲是加速獲取的好方法。$b$b當您有足夠的獎品券時，可以和馬戲團內的諸多商人購買東西。', `FemaleText_loc7`='Me alegro de que me hagas esa pregunta. Los vales para la Feria de la Luna Negra son tu moneda de cambio para conseguir regalos increíbles.$b$bLos vales son la recompensa por hacer las misiones mensuales y jugar a los juegos de la feria.$b$bAl completar las misiones mensuales ganarás el mayor número de vales, pero participar a diario también es una buena forma de conseguirlos.$b$bCuando ya tengas suficientes vales, puedes gastarlos en los diferentes puestos del recinto de la feria.' WHERE `ID`=10776;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다크문 카드는 뭔가요?', `MaleText_loc4`='暗月卡片是什么？', `MaleText_loc5`='暗月卡?', `MaleText_loc7`='¿Cartas de la Luna Negra?', `FemaleText_loc1`='다크문 카드는 뭔가요?', `FemaleText_loc4`='暗月卡片是什么？', `FemaleText_loc5`='暗月卡?', `FemaleText_loc7`='¿Cartas de la Luna Negra?' WHERE `ID`=10777;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다크문 카드를 누가, 무슨 목적으로 만들었는지는 아무도 몰라요. 제가 말씀드릴 수 있는 것은 아제로스 전역에서 종종 발견됐다는 것, 그것도 주로 카드의 비밀을 밝혀내려는 악당들이 가지고 있었다는 것뿐이에요.', `FemaleText_loc4`='没有人知道谁制作了暗月卡片，或者他们真正的意图是什么，但是我可以告诉你，在艾泽拉斯各地都可以找到它们，那些试图揭开它秘密的邪恶怪物手中都可能有卡片。', `FemaleText_loc5`='沒有人知道誰製作了暗月卡片，或者他們真正的意圖是什麼，但是我可以告訴你，在艾澤拉斯各地都可以找到它們，尤其是在那些試圖揭開它秘密的邪惡怪物手中。', `FemaleText_loc7`='Nadie sabe con certeza quién creó las cartas de la Luna Negra o cuál es su propósito real pero sí puedo decirte que las encontrarás por todo Azeroth, generalmente en manos de algún villano que desea desvelar sus misterios.' WHERE `ID`=10778;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='즐길 거리는 뭐가 있습니까?', `MaleText_loc4`='马戏团有哪些游乐设施？', `MaleText_loc5`='有趣的東西?', `MaleText_loc7`='¿Atracciones?', `FemaleText_loc1`='즐길 거리는 뭐가 있죠?', `FemaleText_loc4`='马戏团有哪些游乐设施？', `FemaleText_loc5`='有趣的東西?', `FemaleText_loc7`='¿Atracciones?' WHERE `ID`=10779;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='세이지를 찾아가서 미래를 점쳐 보실 것을 적극 추천해요. 아, 저도 알아요... 세이지는 ''놀''이지요. 하지만, 미래를 예언할 수 있는 특별한 힘을 가지고 있답니다!$B$B또한, 우리 다크문 축제는 나날이 확장하고 있어요. 늘 새로운 볼거리가 가득하답니다.', `FemaleText_loc4`='另外还有一些事情值得注意。我强烈推荐你去塞格那里预测一下你的财富在哪里。我知道，我知道……他是一个豺狼人。但是他是一个拥有特别力量的豺狼人，他可以预知你的财富在哪里！

另外我们在不断扩展我们的马戏团。最近我们增加了一门大炮，你可以试图用它把自己发射到水晶湖！你可以和马戏团东面的玛克希玛谈谈，了解更多细节！', `FemaleText_loc5`='我極度推薦你去拜訪賽吉，請他替你算命。我知道，我知道...他是個豺狼人。不過他是一個非常特別的豺狼人，擁有占卜你未來的能力!$B$B而且我們一直持續地擴展馬戲團在各方面的新吸引力!', `FemaleText_loc7`='Te recomiendo encarecidamente que visites a Sayge para que te adivine el futuro. Lo sé, lo sé... es un gnoll. ¡Pero es un gnoll muy especial con el poder de la adivinación!$B$B¡Y continuamente ampliamos la feria con todo tipo de atracciones nuevas!' WHERE `ID`=10780;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실리더스에는 적이 하나만 있는 것이 아닙니다, $n.$B$B모두의 이목이 실리시드에 집중되어 있지만 저는 형과 함께 황혼의 망치단 미치광이들을 주시해 왔습니다.', `MaleText_loc4`='在希利苏斯，我们的敌人不止一个，$n。$B$B虽然每个人的注意力都集中到异种虫类身上，但是我和我的兄弟密切注视着暮光之锤的一举一动。', `MaleText_loc5`='我們在希利蘇斯有一個以上的敵人，$n。$B$B當所有人的目光都注視著希利蘇斯時，我大哥跟我一直密切注意著暮光之錘的瘋子。', `MaleText_loc7`='Tenemos más de un enemigo en Silithus, $n.$B$BMientras que todo el mundo centra su atención en los silítidos, mi hermano mayor y yo hemos estado vigilando de cerca a los chiflados del Martillo Crepuscular.' WHERE `ID`=10781;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='세이지를 찾아가서 미래를 점쳐 보실 것을 적극 추천해요. 아, 저도 알아요... 세이지는 ''놀''이지요. 하지만, 미래를 예언할 수 있는 특별한 힘을 가지고 있답니다!$B$B또한, 우리 다크문 축제는 나날이 확장하고 있어요. 늘 새로운 볼거리가 가득하답니다.', `FemaleText_loc4`='另外还有一些事情值得注意。我强烈推荐你去塞格那里预测一下你的财富在哪里。我知道，我知道……他是一个豺狼人。但是他是一个拥有特别力量的豺狼人，他可以预知你的财富在哪里！

另外我们在不断扩展我们的马戏团。最近我们增加了一门大炮，你可以试图用它把自己发射到水晶湖！你可以和马戏团东面的玛克希玛谈谈，了解更多细节！', `FemaleText_loc5`='我極度推薦你去拜訪賽吉得到你的未來預言。我知道，我知道...他是個食人妖。不過他是一個非常特別的食人妖，擁有占卜你未來的能力!$B$B而且我們一直持續地擴展馬戲團在各方面的新吸引力!', `FemaleText_loc7`='Te recomiendo encarecidamente que visites a Sayge para que te adivine el futuro. Lo sé, lo sé... es un gnoll. ¡Pero es un gnoll muy especial con el poder de la adivinación!$B$B¡Y continuamente ampliamos la feria con todo tipo de atracciones nuevas!' WHERE `ID`=10782;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오게, $n.', `MaleText_loc4`='你好，$n。', `MaleText_loc5`='你好，$n。', `MaleText_loc7`='Saludos, $n.' WHERE `ID`=10783;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고대의 존재여... 당신이 제게 부탁한 일은 모두 마쳤습니다. 이제 라크델라를 주십시오.', `MaleText_loc4`='你好，古老的生物。我完成了你所要求的所有事情。我要求你现在赐予我伦鲁迪洛尔。', `MaleText_loc5`='你好，古老的生物。我完成了你所要求的所有事情。我要求你現在賜予我倫魯迪洛爾。', `MaleText_loc7`='Buenas, ancestro. He hecho todo lo que se me había encomendado. Ahora pido que me conceda el Rhok''delar.', `FemaleText_loc1`='고대의 존재여... 당신이 제게 부탁한 일은 모두 마쳤습니다. 이제 라크델라를 주십시오.', `FemaleText_loc4`='你好，古老的生物。我完成了你所要求的所有事情。我要求你现在赐予我伦鲁迪洛尔。', `FemaleText_loc5`='你好，古老的生物。我完成了你所要求的所有事情。我要求你現在賜予我倫魯迪洛爾。', `FemaleText_loc7`='Buenas, ancestro. He hecho todo lo que se me había encomendado. Ahora pido que me conceda el Rhok''delar.' WHERE `ID`=10784;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고대의 존재여... 당신이 제게 부탁한 일은 모두 마쳤습니다. 이제 로크델라를 주십시오.', `MaleText_loc4`='你好，古老的生物。我完成了你所要求的所有事情。我要求你现在赐予我罗克迪洛尔。', `MaleText_loc5`='你好，古老的生物。我完成了你所要求的所有事情。我要求你現在賜予我羅克迪洛爾。', `MaleText_loc7`='Buenas, ancestro. He hecho todo lo que se me había encomendado. Ahora pido que me conceda el Lok''delar.', `FemaleText_loc1`='고대의 존재여... 당신이 제게 부탁한 일은 모두 마쳤습니다. 이제 로크델라를 주십시오.', `FemaleText_loc4`='你好，古老的生物。我完成了你所要求的所有事情。我要求你现在赐予我罗克迪洛尔。', `FemaleText_loc5`='你好，古老的生物。我完成了你所要求的所有事情。我要求你現在賜予我羅克迪洛爾。', `FemaleText_loc7`='Buenas, ancestro. He hecho todo lo que se me había encomendado. Ahora pido que me conceda el Lok''delar.' WHERE `ID`=10785;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꼬꼬댁! 꼬꼬꼬꼬! 할로윈 축제 즐겁게 보내요, $n!', `MaleText_loc4`='哈哈哈！万圣节快乐，$n！', `MaleText_loc5`='咕，咕，咕!萬鬼節快樂，$n!', `MaleText_loc7`='¡Clo, clo, clo! ¡Feliz Halloween, $n!' WHERE `ID`=10786;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 다른 건 몰라도 춤이라면 누구 못지않게 잘 춘다고요! 호호, 할로윈 축제 즐겁게 보내세요!', `FemaleText_loc4`='我或许有99种问题，但是跳舞绝对不是问题！万圣节快乐，$n！', `FemaleText_loc5`='我或許有99種問題，但是跳舞絕對不是問題!萬鬼節快樂，$n!', `FemaleText_loc7`='Hay muchas cosas que no se me dan bien, ¡pero bailar no es una de ellas! ¡Feliz Halloween, $n!' WHERE `ID`=10787;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='칙칙폭폭, 칙칙폭폭! 할로윈 축제 즐겁게 보내십시오, $n!', `FemaleText_loc4`='恰－恰，喔－喔！万圣节快乐，$n！', `FemaleText_loc5`='恰嘎-恰嘎，嗚-嗚!萬鬼節快樂，$n!', `FemaleText_loc7`='¡Chucuchu, chucuchu... chu, chu! ¡Feliz Halloween, $n!' WHERE `ID`=10788;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우와, 힘이 넘치시는군요! 할로윈 축제 즐겁게 보내세요!', `FemaleText_loc4`='哦，太强壮了！万圣节快乐，$n！', `FemaleText_loc5`='哦，太強壯了!萬鬼節快樂，$n!', `FemaleText_loc7`='¡Oh, muy fuerte! ¡Feliz Halloween, $n!' WHERE `ID`=10789;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, 여행자님. 이곳은 거의 1천 년 전, 퀴라지가 칼림도어를 건너 파괴의 행진을 시작한 곳입니다.$B$B전쟁 중에 수천 명이 목숨을 잃었는데, 그 대부분은 첫 번째 침략 당시 이 저주받은 사막에서 숨을 거뒀지요.$B$B저는 몇 안 되는 생존자 중의 한 명이며, 과거와 현재의 속박에서 벗어나지 못하는 불쌍한 영혼이랍니다. 제가 여기 남아 있어야 하는 이유는 알지 못하지만 그럴 수밖에 없다는 것은 알고 있습니다.', `FemaleText_loc4`='你好，旅行者。大约1000年前，其拉虫人开始了对卡利姆多大陆的战争。$B$B在那场战争中损失了数以千记的生命，大多数都是在战争爆发初期丧身在这片该死的沙漠中的。$B$B我是少数幸存下来的人，我连接了过去和现在。我不知道我为什么还留在这里，但是我知道我必须这样做。', `FemaleText_loc5`='你好，旅人。大約1,000年前，其拉蟲人開始了對卡林多大陸的戰爭。$B$B在那場戰爭中損失了數以千記的生命，大多數都是在戰爭爆發初期喪身在這片該死的沙漠中的。$B$B我是少數倖存下來的人，我連接了過去和現在。我不知道我為什麼還留在這裏，但是我知道我必須這樣做。', `FemaleText_loc7`='Saludos, $gviajero:viajera;. Fue aquí, hace casi 1,000 años, donde los qiraji comenzaron su oleada de destrucción por Kalimdor.$B$BSe perdieron miles de vidas durante la guerra, la mayoría de ellas en este desierto maldito durante la invasión inicial.$B$BYo soy una de los pocos que quedamos, atados tanto al pasado como al presente. No sé por qué tengo que permanecer aquí pero sé que no puedo hacer nada para evitarlo.' WHERE `ID`=10790;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에 대해 어떻게 아십니까?', `MaleText_loc4`='你怎么知道？', `MaleText_loc5`='你怎麼知道?', `MaleText_loc7`='¿Cómo lo sabes?', `FemaleText_loc1`='이곳에 대해 어떻게 아시나요?', `FemaleText_loc4`='你怎么知道？', `FemaleText_loc5`='你怎麼知道?', `FemaleText_loc7`='¿Cómo lo sabes?' WHERE `ID`=10791;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 백 번이나 살해당했지만 깨어나면 다시 이곳이었죠. 어떤 이들은 저를 보고 저주받았다고 하고, 또 어떤 이들은...', `FemaleText_loc4`='我被杀死过无数次。我总是发现我会在这里醒来。有些人说我遭受了诅咒，还有些人……', `FemaleText_loc5`='我被殺死過無數次。我總是發現我會在這裏醒來。有些人說我遭受了詛咒，還有些人...', `FemaleText_loc7`='Me han asesinado cien veces y siempre despierto de nuevo aquí. Algunos dicen que pesa una maldición sobre mí y otros...' WHERE `ID`=10792;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐라고 합니까?', `MaleText_loc4`='他们说什么？', `MaleText_loc5`='他們說什麼?', `MaleText_loc7`='¿Qué dicen?', `FemaleText_loc1`='뭐라고 하나요?', `FemaleText_loc4`='他们说什么？', `FemaleText_loc5`='他們說什麼?', `FemaleText_loc7`='¿Qué dicen?' WHERE `ID`=10793;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='축복받은 것이라고 하더군요. 새로운 시대를 알려 주는 전령이라면서...', `FemaleText_loc4`='他们说我被祝福了：新世纪需要被聆听的传讯者。', `FemaleText_loc5`='他們說我被祝福了:新世紀需要被聆聽的信使。', `FemaleText_loc7`='Que se trata de una bendición: un heraldo en una nueva era.' WHERE `ID`=10794;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래서 당신은 뭐라고 했습니까?', `MaleText_loc4`='你说了什么？', `MaleText_loc5`='你說了什麼?', `MaleText_loc7`='¿Y tú que opinas?', `FemaleText_loc1`='그래서 당신은 뭐라고 했나요?', `FemaleText_loc4`='你说了什么？', `FemaleText_loc5`='你說了什麼?', `FemaleText_loc7`='¿Y tú que opinas?' WHERE `ID`=10795;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='수천 년 동안 보이지도 않고 느낄 수도 없었던 고대의 세력이 움직이고 있습니다. 이 세계가 흐느끼고 있어요. 아마도 새로운 세계 분리가 일어나겠죠. 내부로부터 탄생한 병...$B$B사악함이 우리 땅에 퍼지기 시작했어요. 에메랄드의 꿈으로부터 악몽이 나타나고 있습니다. 깨어 있는 동안 우리를 타락시킬 악몽이...', `FemaleText_loc4`='上古的力量被数千年来从未活动过的虫子所震撼。世界在哭泣，$r。也许一次新的灾变正在开始。其中孕育的是痛苦……$B$B那些可恶的家伙开始渗透入我们的土地。噩梦来自于睡眠。噩梦开始在我们醒着的时候纠缠我们……', `FemaleText_loc5`='上古的力量正在騷動，那是數千年來無人見識過的力量。世界在哭泣，$r。也許一場新的災變正在醞釀，而它孕育正是痛苦...$b$b邪惡的力量滲透入我們的土地。夢境帶來了夢魘...連我們醒著的時候都繼續糾纏的夢魘...', `FemaleText_loc7`='Hay fuerzas ancestrales acechando, fuerzas que no se habían percibido durante miles de años. El mundo llora, $r. Quizás se avecina un nuevo cataclismo. Un malestar que surge de dentro... $B$BEl mal está calando en nuestras tierras. Del Sueño salen pesadillas, que perturban nuestro despertar...' WHERE `ID`=10796;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우와, 힘이 넘치시는군요! 할로윈 축제 즐겁게 보내세요, $n!', `FemaleText_loc4`='哦，太强壮了！万圣节快乐，$n！', `FemaleText_loc5`='啊，太棒了!萬鬼節快樂，$n!', `FemaleText_loc7`='¡Oh, muy fuerte! ¡Feliz Halloween, $n!' WHERE `ID`=10797;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하, 꼬꼬댁! 꼬꼬꼬꼬! 할로윈 축제 즐겁게 보내십시오, $n!', `MaleText_loc4`='哈哈哈！万圣节快乐，$n！', `MaleText_loc5`='咕，咕，咕!萬鬼節快樂，$n!', `MaleText_loc7`='¡Clo, clo, clo! ¡Feliz Halloween, $n!' WHERE `ID`=10798;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칙칙폭폭, 칙칙폭폭! 할로윈 축제 즐겁게 보내세요, $n 님!', `MaleText_loc4`='恰－恰，喔－喔！万圣节快乐，$n！', `MaleText_loc5`='恰嘎-恰嘎，嗚-嗚!萬鬼節快樂，$n!', `MaleText_loc7`='¡Chucuchu, chucuchu... chu, chu! ¡Feliz Halloween, $n!' WHERE `ID`=10799;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 다른 건 몰라도 춤 하나는 끝내주게 잘 춘다고요! 할로윈 축제 즐겁게 보내세요, $n!', `FemaleText_loc4`='我或许有99种问题，但是跳舞绝对不是问题！万圣节快乐，$n！', `FemaleText_loc5`='我或許有99種問題，但是跳舞絕對不是問題!萬鬼節快樂，$n!', `FemaleText_loc7`='Hay muchas cosas que no se me dan bien, ¡pero bailar no es una de ellas! ¡Feliz Halloween, $n!' WHERE `ID`=10800;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='건방진 놈, 무례하게 군 대가를 톡톡히 받게 해 주마. 네 놈의 영혼은 내가 갖겠다!', `MaleText_loc4`='你将为你的傲慢付出惨痛的代价，你的灵魂属于我了！', `MaleText_loc5`='你將為你的傲慢付出慘痛的代價，你的靈魂屬於我了!', `MaleText_loc7`='Pagarás cara tu insolencia, alimaña. ¡Tu alma me pertenece!' WHERE `ID`=10801;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게 반항하다니 그냥 넘어갈 수가 없군. 너와 네가 속한 세계를 파괴해 버리겠다!', `MaleText_loc4`='你的挑衅会受到惩罚的。你和你的世界将一起灭亡！', `MaleText_loc5`='你的反抗行為會受到懲罰的。你和你的世界將一起滅亡!', `MaleText_loc7`='Este acto de rebeldía no quedará impugne. ¡Acabaré contigo y con tu mundo!' WHERE `ID`=10802;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐? 이런 하룻강아지 같은 놈이 감히 내게 덤비겠다고? 버릇을 고쳐주마!', `MaleText_loc4`='什么？你这样的家伙也敢召唤我？你会受到惩罚的！', `MaleText_loc5`='什麼?你這樣的小傢伙也敢召喚我?我要把你的屍體扔到我的王座上，$R!!', `MaleText_loc7`='¿Qué? ¿Una cosa tan pequeña y endeble se atreve a solicitar mi presencia? ¡Esto no quedará impugne!' WHERE `ID`=10803;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 속이다니! 너 같은 애송이에게 소환되었다는 사실은 씻을 수 없는 치욕이구나! 널 가만두지 않겠다!', `MaleText_loc4`='假冒者！被你这样的家伙召唤出来是无法容忍的羞耻！去死吧！', `MaleText_loc5`='假冒者!被你這樣的傢伙召喚出來是無法容忍的羞恥!去死吧!', `MaleText_loc7`='¡$gImpostor:Impostora;! ¡Es una deshonra para mí ser invocado por alguien como tú! ¡MUERE!' WHERE `ID`=10804;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 놈의 배신은 네 명을 재촉할 뿐이다. 이 세계는 암흑 속에 빠지게 될 것이다!', `MaleText_loc4`='背叛只会加速你的灭亡。世界将陷入黑暗！', `MaleText_loc5`='背叛只會加速你的滅亡。世界將陷入黑暗!', `MaleText_loc7`='Tu traición solo sirve para acelerar tu caída. ¡El mundo caerá en la oscuridad!' WHERE `ID`=10805;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 놈이 감히! 도저히 참을 수 없다! 내 저주를 받아라. 네 놈에게... 죽음의 저주를 내리겠다!', `MaleText_loc4`='大胆！我诅咒你，$C。我诅咒你……死吧！', `MaleText_loc5`='大膽!我詛咒你，$C。我詛咒你...死吧!', `MaleText_loc7`='¡Cómo te atreves! ¡Es intolerable! Yo te maldigo, $c. Te maldigo con... ¡la muerte!' WHERE `ID`=10806;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐냐? 이런 하룻강아지 같은 놈이 감히 내게 덤비겠다고? 네 뼈를 모아 내 옥좌를 장식해주마!', `MaleText_loc4`='什么？你这样的家伙也敢召唤我？我要把你的尸体扔到我的王座上，$R！！', `MaleText_loc5`='什麼?你這樣的小傢伙也敢召喚我?我要把你的屍體扔到我的王座上，$R!!', `MaleText_loc7`='¿Qué? ¿Una cosa tan pequeña y endeble se atreve a solicitar mi presencia? ¡¡Pondré tus huesos en mi corona, $r!!' WHERE `ID`=10807;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='할로윈 축제 즐겁게 보내세요! 제가 쓴 가면 어때요? 너무 무섭지 않아요?!', `FemaleText_loc4`='万圣节快乐！你喜欢我的面具吗？非常吓人呢！', `FemaleText_loc5`='萬鬼節快樂!你喜歡我的面具嗎?嚇人吧!', `FemaleText_loc7`='¡Feliz Halloween! ¿Te gusta mi máscara? ¡Da mucho miedo!' WHERE `ID`=10808;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='즐거운 할로윈 축제! 제가 쓴 가면 어때요? 진짜 섬뜩하죠?!', `FemaleText_loc4`='万圣节快乐！你喜欢我的面具吗？非常吓人呢！', `FemaleText_loc5`='萬鬼節快樂!你喜歡我的面具嗎?嚇人吧!', `FemaleText_loc7`='¡Feliz Halloween! ¿Te gusta mi máscara? ¡Da mucho miedo!' WHERE `ID`=10809;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 놈과 네 동료를 모조리 없애 버려야 기분이 좀 나아지겠군. 오래 걸리지 않을 것이다!', `MaleText_loc4`='消灭你和你的军团是件愉快的事儿，$C。我会速战速决的。', `MaleText_loc5`='殺了你與你的同夥，$c，可以讓我很快樂。我會盡量快點的。', `MaleText_loc7`='Será divertido matarte a ti y a tus seguidores, $c. Lo haré rápido.' WHERE `ID`=10810;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사탕 구하러 다는 게 너무 그리울 거예요!', `FemaleText_loc4`='我要错过“不给糖果就捣乱”了！', `FemaleText_loc5`='我會錯過「不給糖就搗蛋」的活動的!', `FemaleText_loc7`='¡Me voy a perder el juego del truco o trato!' WHERE `ID`=10811;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='할로윈 축제인데 밖에 나갈 수가 없다니... 사탕 얻으러 다니고 싶은데!', `MaleText_loc4`='我太伤心了！万圣节到了，我却没法出去，不能玩要糖果的恶作剧游戏！', `MaleText_loc5`='我會錯過要糖果或惡作劇的遊戲，因為我不能出去!', `MaleText_loc7`='¡Me voy a perder el juego del truco o trato porque no puedo salir!' WHERE `ID`=10812;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$g오빠가:언니가; 최고예요. 절 위해 사탕을 얻어다 주시겠다니... 정말 고맙습니다!', `FemaleText_loc4`='你真好，$n——谢谢你陪我玩要糖果的恶作剧游戏！', `FemaleText_loc5`='你是最棒的，$n - 謝謝你幫我去參加「不給糖就搗蛋」的活動!', `FemaleText_loc7`='¡Eres el mejor, $n! ¡Gracias por hacer el truco o trato por mí!' WHERE `ID`=10813;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사탕을 모아 주시겠다니... 이 세상에서 $n|1이;가; 최고로 좋아요! 정말 감사합니다!', `MaleText_loc4`='你是最棒的，$n——谢谢你陪我玩要糖果的恶作剧游戏！', `MaleText_loc5`='你是最棒的，$n - 謝謝你幫我去參加「不給糖就搗蛋」的活動!', `MaleText_loc7`='¡Eres el mejor, $n! ¡Gracias por hacer el truco o trato por mí!' WHERE `ID`=10814;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 할로윈 축제 사탕을 팔고 있습니까?', `MaleText_loc4`='你这儿有哪些万圣节的糖果？', `MaleText_loc5`='你有賣哪些萬鬼節的糖果呢?', `MaleText_loc7`='¿Qué caramelos de Halloween tienes a la venta?', `FemaleText_loc1`='어떤 할로윈 축제 사탕을 팔고 있나요?', `FemaleText_loc4`='你这儿有哪些万圣节的糖果？', `FemaleText_loc5`='你有賣哪些萬鬼節的糖果呢?', `FemaleText_loc7`='¿Qué caramelos de Halloween tienes a la venta?' WHERE `ID`=10815;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='할로윈 축제에 할 수 있는 게 무엇입니까?', `MaleText_loc4`='在万圣节，我们要怎么玩？', `MaleText_loc5`='萬鬼節該做些什麼呢?', `MaleText_loc7`='¿Qué se hace en Halloween?', `FemaleText_loc1`='할로윈 축제에 할 수 있는 게 뭔가요?', `FemaleText_loc4`='在万圣节，我们要怎么玩？', `FemaleText_loc5`='萬鬼節該做些什麼呢?', `FemaleText_loc7`='¿Qué se hace en Halloween?' WHERE `ID`=10816;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭘 해야 하냐고요?$B$B축제 기간에는 전 세계의 모든 여관주인들이랑 "사탕 하나 주면 안 잡아먹지!" 놀이를 할 수 있어요. 그리고 여러 마을에 예쁜 장식이 달리니까 구경하러 한번 가보세요! 그리고 매일 저녁에는 언더시티 밖에서 밀짚인형 축제가 열려요.', `FemaleText_loc4`='这是一场肆无忌惮的狂欢！$B$B世界各地的旅店老板都会为“不给糖就捣蛋”准备好各种糖果，许多城镇都将装饰一新，欢度节日！此外，幽暗城外还会在夜间举办稻草人庆典。', `FemaleText_loc5`='能做什麼?!$B$B世界各地的旅店老闆都會將糖果分發給孩子們，許多城鎮都將裝飾一新，歡度節日!此外，幽暗城外還會在夜間舉辦稻草人慶典。', `FemaleText_loc7`='¡Qué NO se hace, querrás decir!$B$B¡Todos los taberneros del mundo regalan cosas ricas y muchas ciudades están adornadas para la ocasión! Además, se celebra todas las noches el Festival del Hombre de Mimbre en las afueras de Entrañas.' WHERE `ID`=10817;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭘 해야 하냐고요?$B$B축제 기간에는 전 세계의 모든 여관주인들이랑 "사탕 하나 주면 안 잡아먹지!" 놀이를 할 수 있어요. 그리고 여러 마을에 예쁜 장식이 달리니까 구경하러 한 번 가보세요! 참, 그리고 남녘해안에 있는 하사관 허트만이 밀짚인형 축제를 맞이한 포세이큰을 저지하기 위해 도움이 필요하다고 하더군요.$B$B아, 한 가지 더 있어요. 스톰윈드의 보육원에 한 소년이 병들어 몸져누워 있는데 축제 기간 동안 누군가 대신 사탕을 모아줬으면 한데요... 혹시 그 소년을 도와줄 생각은 없나요?', `FemaleText_loc4`='怎么玩？！$B$B世界各地的旅店老板都会将糖果分发给孩子们，许多城镇都将装饰一新，欢度节日！此外，南海镇的哈特曼中士需要帮助，他想要攻击那些被遗忘者，破坏他们的稻草人庆典。$B$B对了，我听说暴风城孤儿院里有个生病的小男孩，他想找人陪他玩要糖果的恶作剧游戏……或许你能帮帮他？', `FemaleText_loc5`='怎麼玩?!$B$B世界各地的旅店老闆都會將糖果分發給孩子們，許多城鎮都將裝飾一新，歡度節日!此外，南海鎮的哈特曼中士需要幫助，他想要攻擊那些被遺忘者，破壞他們的稻草人慶典。$B$B對了，我聽說暴風城孤兒院裏有個生病的小男孩，他想找人陪他玩要糖果的惡作劇遊戲...或許你能幫幫他?', `FemaleText_loc7`='¡Qué NO se hace, querrás decir!$B$B¡Todos los taberneros del mundo regalan cosas ricas y muchas ciudades están adornadas para la ocasión! Además, el sargento Hartman en Costasur necesita ayuda contra los Renegados y su Festival del Hombre de Mimbre.$B$BUna cosa más: he oído que un niño enfermo que está en el orfanato aquí en Ventormenta busca a alguien que le ayude a conseguir caramelos durante esta fiesta.' WHERE `ID`=10818;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n의 소환을 해제하는 중입니다.', `MaleText_loc4`='$n，你让我获得了重生。', `MaleText_loc5`='$n，你讓我獲得了重生。', `MaleText_loc7`='Estoy desapareciendo de $n.', `FemaleText_loc1`='$n의 소환을 해제하는 중입니다.', `FemaleText_loc4`='$n，你让我获得了重生。', `FemaleText_loc5`='$n，你讓我獲得了重生。', `FemaleText_loc7`='Estoy desapareciendo de $n.' WHERE `ID`=10819;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하사관 허트만! 구린내 폭탄 탈취제를 구입하고 싶습니다!', `MaleText_loc4`='哈特曼中士！我要再买一个臭气弹清洁器！', `MaleText_loc5`='哈特曼中士!我要再買一個臭彈清潔器!', `MaleText_loc7`='¡Sargento Hartman! ¡Necesito comprar otro limpiador de bombas fétidas!', `FemaleText_loc1`='하사관 허트만! 구린내 폭탄 탈취제를 구입하고 싶습니다!', `FemaleText_loc4`='哈特曼中士！我要再买一个臭气弹清洁器！', `FemaleText_loc5`='哈特曼中士!我要再買一個臭彈清潔器!', `FemaleText_loc7`='¡Sargento Hartman! ¡Necesito comprar otro limpiador de bombas fétidas!' WHERE `ID`=10820;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구린내 폭탄을 더 구입하고 싶습니다!', `MaleText_loc4`='我想再买一个臭气弹！', `MaleText_loc5`='我想再買一個臭彈!', `MaleText_loc7`='¡Quiero comprar otra bomba fétida!', `FemaleText_loc1`='구린내 폭탄을 더 구입하고 싶습니다!', `FemaleText_loc4`='我想再买一个臭气弹！', `FemaleText_loc5`='我想再買一個臭彈!', `FemaleText_loc7`='¡Quiero comprar otra bomba fétida!' WHERE `ID`=10821;
