UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헉! 이럴 수가...', `MaleText_loc4`='不！这不可能……', `MaleText_loc5`='不!這不可能...', `MaleText_loc7`='¡No! No puede ser...' WHERE `ID`=10823;
