UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 임프시에게 자비를 베풀어 달라고 빕니다.', `MaleText_loc4`='%s乞求伊普斯的宽恕。', `MaleText_loc5`='%s乞求伊普斯的寬恕。', `MaleText_loc7`='%s pide perdón a Diblis.' WHERE `ID`=10826;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최후를 맞을 준비나 하시지요!', `MaleText_loc4`='准备受死吧！', `MaleText_loc5`='準備受死吧!', `MaleText_loc7`='¡Prepárate para morir!' WHERE `ID`=10827;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 안 돼...', `MaleText_loc4`='啊……', `MaleText_loc5`='喔...喔...', `MaleText_loc7`='Oh, oh...' WHERE `ID`=10828;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그것은 역사예요... 티탄과 고대 신의... 안퀴라즈에 얽힌... 실리더스의 역사... 저는 퀴라지 예언자 스케람이 작성한 크툰의 예언서를 읽었어요. 그건 대재앙을 알리는 예언서였죠...', `FemaleText_loc4`='这就是历史……希利苏斯的历史……安其拉的历史……泰坦和上古之神的历史……我在由其拉虫人的先知斯克拉姆撰写的有关克苏恩的预言中读到过这些历史。那预言预示着一场大灾难……', `FemaleText_loc5`='這就是歷史...希利蘇斯的歷史...安其拉的歷史...泰坦和上古諸神的歷史...我在由其拉蟲人的先知斯克拉姆撰寫的有關克蘇恩的預言中讀到過這些歷史。那預言預示著一場大災難...', `FemaleText_loc7`='Es historia... Una historia de Silithus... de Ahn''Qiraj... de titanes y dioses antiguos... Leo la profecía de C''Thun escrita por el profeta qiraji Skerram. Una profecía que presagia un cataclismo...' WHERE `ID`=10829;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아주 오래전, 이 세계가 태초의 모습을 간직하고 있던 때 바로 이 땅에서 티탄과 무시무시한 힘을 가진 사악한 존재 사이에 싸움이 있었죠. 예언서에는 티탄이 이겼는지 패했는지에 대해서 정확하게 나와 있지 않지만, 티탄이 전사한 것으로 기록되어 있어요. 한 명의 티탄 또한 전사한 것으로 되어 있죠. 아니면 그렇게 생각되는 것일 수도 있고...', `FemaleText_loc4`='在很久很久以前，世界还在混沌伊始之际，泰坦和一位拥有不可思议的邪恶力量的神灵展开了一场恶战。预言并没有记载泰坦是否战败，但是却记载着一位泰坦阵亡的事件。一位上古之神也阵亡了——大约是这样吧。', `FemaleText_loc5`='在很久很久以前，世界還在混沌伊始之際，泰坦和一位擁有不可思議的邪惡力量的神靈展開了一場惡戰。預言並沒有記載泰坦是否戰敗，但是卻記載著一位元泰坦陣亡的事件。一位上古之神也陣亡了─大約是這樣吧。', `FemaleText_loc7`='Al principio de los tiempos, cuando el mundo todavía estaba en su infancia, una batalla entre un titán y un ser de inimaginable maldad y poder golpeó estas tierras. La profecía no aclara si el titán fue derrotado o no en esta batalla pero hay ilustraciones que muestran la caída de un titán. Un dios antiguo también había caído... o eso se pensó.' WHERE `ID`=10830;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 존재는 수천 년 동안 땅속에서 동면하고 있었죠. 때를 기다리면서... 자신을 해치려는 자들에게 복수할 그 순간만 기다리면서 말이죠.', `FemaleText_loc4`='千年来，它在地底休眠，苟延残喘，等待时机发动反击。', `FemaleText_loc5`='千年來，它在地底休眠，苟延殘喘，等待時機發動反擊。', `FemaleText_loc7`='Durante milenios, este ser permaneció adormecido bajo el mundo, esperando su momento. Desde su prisión aguardó el momento preciso para atacar a aquellos que le habían hecho daño.' WHERE `ID`=10831;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='영원한 별빛의 땅 칼림도어는 그곳에 살고 있는 모든 존재에게 양분을 공급하는 어머니와도 같았답니다. 대지는 영원의 샘에서 뿜어져 나오는 마력으로 충만하여 많은 동식물이 번성할 수 있었지요. 이 마력의 영향으로 실리시드가 태어났습니다. 고대 신이 고심 끝에 강림하여 이 세계를 갈라놓으려 한 것도 바로 이 무자비한 실리시드로부터 세상을 구원하기 위함이었지요.', `FemaleText_loc4`='永烁星光之地卡利姆多哺育了这片大地上的所有生灵。永恒之井的魔法力量渗透到土地中，使得各种各样的植物和动物都具备了一定的魔法力量。这种魔法力量滋生异种虫类。上古之神控制了异种虫，妄图再次征服世界。', `FemaleText_loc5`='永爍星光之地卡林多哺育了這片大地上的所有生靈。永恆之井的魔法力量滲透到土地中，使得各種各樣的植物和動物都具備了一定的魔法力量。這種魔法力量滋生異種蟲類。上古之神控制了異種蟲，妄圖再次征服世界。', `FemaleText_loc7`='La tierra de la eterna luz estelar, Kalimdor, fue una madre para todas estas criaturas. La magia del Pozo de la Eternidad impregnó la tierra y otorgó poderes a la flora y la fauna que harían del mundo su hogar. De este éter mágico nacieron los silítidos. A través de los silítidos, el inquietante dios antiguo regresó al mundo que una vez había tenido entre sus despiadadas garras.' WHERE `ID`=10832;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고대 신은 실리시드의 원형으로부터 화신을 만들려고 했습니다. 이 화신들이 바로 퀴라지라고 알려져 있지요. 지능이 발달된 퀴라지는 어떤 목적을 가지고 자신들의 창조주의 이름을 지었습니다. 바로 크툰이 태어난 것이지요. 퀴라지는 이 세계가 자신들의 신을 배신하는 그날 세상을 파괴하기 위해 수천 년 동안 군대를 훈련시켜 왔습니다. 도시 전체가 하나의 거대한 요새인 안퀴라즈는 퀴라지가 자신들의 군대를 양성하고 크툰의 강림을 준비하기 위해 건설한 것이었습니다.', `FemaleText_loc4`='上古之神使用异种虫创造出了自己的化身。这些化身被称为其拉虫人。其拉虫人将他们的创造者称为克苏恩……数千年来，其拉虫人疯狂地扩充军队，企图毁灭曾经背叛上古之神的世界。庞大的安其拉堡垒则用于容纳他们日益增加的军队，准备迎接克苏恩的到来。', `FemaleText_loc5`='上古之神使用異種蟲創造出了自己的化身。這些化身被稱為其拉蟲人。其拉蟲人將他們的創造者稱為克蘇恩...數千年來，其拉蟲人瘋狂地擴充軍隊，企圖毀滅曾經背叛上古之神的世界。龐大的安其拉堡壘則用於容納他們日益增加的軍隊，準備迎接克蘇恩的到來。', `FemaleText_loc7`='El dios antiguo crearía avatares a partir de los silítidos a su imagen y semejanza, que más tarde se conocerían como los qiraji. Sensibles y con determinación, los qiraji nombrarían a su creador. C''Thun había nacido... Durante miles de años los qiraji trabajaron febrilmente para conformar un ejército capaz de arrasar el mundo que traicionaría a su dios. La ciudad fortificada de Ahn''Qiraj se creó para albergar a sus ejércitos cada vez más numerosos y para preparar la llegada de C''Thun.' WHERE `ID`=10833;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 스컬지석을 자세히 조사합니다.', `MaleText_loc4`='%s仔细检查天灾石。', `MaleText_loc5`='%s仔細地檢查天譴石。', `MaleText_loc7`='%s examina la piedra de la Plaga de cerca.' WHERE `ID`=10834;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 스컬지석들에 있는 악마는 원래 강력한 힘을 가지고 있지만 지금은 그 힘이 제거된 상태요.', `MaleText_loc4`='这些石头中蕴含的邪恶力量非常强大，但是它已经被驱散了。', `MaleText_loc5`='這些石頭裡的邪惡力量很強大，但已經被驅散了。', `MaleText_loc7`='El mal en estas piedras es grande pero se ha disipado.' WHERE `ID`=10835;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그럴 리가 없어. 고대 신은 절대로 이 세계로 들어올 수 없어요. 만약 그렇게 된다면... 오, 맙소사!', `FemaleText_loc4`='这不可能。上古之神绝不可能被允许进入这个世界。如果那样的话……天哪！', `FemaleText_loc5`='這不可能。上古之神絕不可能被允許進入這個世界。如果那樣的話...天哪!', `FemaleText_loc7`='No puede ser cierto. Un dios antiguo nunca debería poder entrar en este mundo. Las consecuencias serían... ¡Oh, dios mío!' WHERE `ID`=10836;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 다시 평정을 찾습니다.', `FemaleText_loc4`='%s恢复了镇定。', `FemaleText_loc5`='%s恢復了鎮定。', `FemaleText_loc7`='%s recobra la compostura.' WHERE `ID`=10837;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='후... 이야기가 더 남았습니다.', `FemaleText_loc4`='还有更多。', `FemaleText_loc5`='還有更多。', `FemaleText_loc7`='Hay más.' WHERE `ID`=10838;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='크툰이 그토록 기다려 온 순간이 마침내 도래했습니다. 그의 피조물들이 수천 년 동안 칼림도어 전체를 향한 복수의 일념으로 군대를 양성해 온 결실이 이제 곧 이루어지는 순간이었습니다.', `FemaleText_loc4`='克苏恩苦苦等待的时刻终于来临了。他的孩子们花了数千年的时间，创建了一支强大的军队，准备对整个卡利姆多展开疯狂的报复；现在一切尽在他们的掌控之中。', `FemaleText_loc5`='克蘇恩苦苦等待的時刻終於來臨了。他的孩子們花了數千年的時間，創建了一支強大的軍隊，準備對整個卡林多展開瘋狂的報復;現在一切盡在他們的掌控之中。', `FemaleText_loc7`='Por fin había llegado el momento que C''Thun había estado esperando pacientemente. Sus hijos habían invertido miles de años en la creación de un ejército capaz de exigir venganza a todo Kalimdor y la recompensa estaba ahora a su alcance.' WHERE `ID`=10839;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='티탄이 이 세계를 돌보지 않은 지도 오랜 시간이 흘렀습니다. 이제 이곳엔 한때 무리를 이루고 살았던 나이트 엘프들만이 이 땅을 지키기 위해 남아있을 뿐입니다. 오, 이런! 다음 구절이 아주 흥미롭군요!', `FemaleText_loc4`='泰坦们离开艾泽拉斯世界已经很久了。惟有曾经居住在这片土地上的暗夜精灵还在守卫着他们的家园。天哪！接下来这一段真令人着迷！', `FemaleText_loc5`='泰坦離開這個世界已經很久了。只有曾經住在這區域的夜精靈在這裡防守。喔，天啊!下一段真是迷人!', `FemaleText_loc7`='Los titanes hacía tiempo que habían abandonado este mundo. Solo los elfos de la noche que una vez habitaron en esta zona estaban aquí para defenderlo. ¡Ay! ¡El siguiente pasaje es fascinante!' WHERE `ID`=10840;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='실리더스를 향한 첫 번째 침공을 지휘한 자는 라작스 장군으로 알려진 강력한 퀴라지였습니다. 이들의 진군을 막아선 유일한 인물이 있었으니 그는 바로 스태그헬름이라고 하는 나이트 엘프였지요. 퀴라지들은 그를 카르시스 또는 자신들의 언어로 ''대지의 손''를 뜻하는 이름으로 불렀습니다.', `FemaleText_loc4`='其拉虫人的将军拉贾克斯指挥大军，入侵希利苏斯。阻挡它的只有一股势力：暗夜精灵的领袖范达尔·鹿盔。其拉虫人将鹿盔称为“卡尔希斯”，意即“大地之手”。', `FemaleText_loc5`='其拉蟲人的將軍拉賈克斯指揮大軍，入侵希利蘇斯。阻擋它的只有一股勢力:一個叫做鹿盔的夜精靈。在原始的其拉語言裡，其拉蟲人稱他為卡爾希斯或「大地之手」。', `FemaleText_loc7`='"Un poderoso qiraji conocido como general Rajaxx dirigiría la primera incursión en Silithus. Solo alguien se interpondría en su camino: un elfo de la noche conocido como Corzocelada. Se refieren a él como Khar''sis o "la mano de la tierra" en la lengua nativa de los qiraji."' WHERE `ID`=10841;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='스태그헬름과 그의 군대는 실리더스에서 끝없이 쏟아져 나오는 라작스의 부대에게 완전히 압도당했습니다. 그러나 스태그헬름은 퀴라지가 단순히 성가신 정도로 여길 만한 존재가 아니었지요. 모든 나이트 엘프 전사들은 스태그헬름의 지휘 아래 하나가 되어 칼림도어를 지키기 위해 필사적으로 싸웠습니다. 그리고 그 결과 퀴라지 군대의 진군을 크게 저지할 수 있었습니다.', `FemaleText_loc4`='拉贾克斯的大军源源不断地涌入希利苏斯，鹿盔和他的军队毫无胜算。但是对其拉虫人而言，鹿盔也是个令他们非常头痛的人物。他手下的所有暗夜精灵都团结一致，誓死保卫卡利姆多，这大大妨碍了其拉虫人军队的入侵。', `FemaleText_loc5`='拉賈克斯的大軍源源不斷地湧入希利蘇斯，鹿盔和他的軍隊毫無勝算。但是對其拉蟲人而言，鹿盔也是個令他們非常頭痛的人物。他手下的所有夜精靈都團結一致，誓死保衛卡林多，這大大妨礙了其拉蟲人軍隊的入侵。', `FemaleText_loc7`='Corzocelada y sus ejércitos se vieron claramente superados por el enorme despliegue de tropas de Rajaxx en Silithus. Sin embargo, Corzocelada se convirtió en algo más que un mero estorbo para los qiraji. A las órdenes de Corzocelada, todos los ejércitos del elfo de la noche habían unido sus fuerzas para defender Kalimdor, consiguiendo refrenar las tropas de los qiraji.' WHERE `ID`=10842;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하지만 불행히도 나이트 엘프군의 방어는 지속될 수 없었으며 라작스는 그런 나이트 엘프들이 얼마 버티지 못할 것임을 알고 있었습니다. 그러나 그들은 결코 굴하지 않고 싸웠기에 라작스에게 참담한 기분을 안겨줄 수 있었지요. 그리고 그보다 더 크게 실망하고 불만스러워했던 것은 그의 왕이었습니다. 잠깐, 왕이라고요? 정말 놀라운 사실이 아닐 수 없군요...', `FemaleText_loc4`='不幸的是，暗夜精灵的防御不堪一击，拉贾克斯知道他们已经撑不了多久了。但是，他们的顽强着实让拉贾克斯遭遇很大的挫折，对他的国王而来，这更是沉重的打击。等等，国王？难以置信……', `FemaleText_loc5`='不幸的是，夜精靈的防禦不堪一擊，拉賈克斯知道他們已經撐不了多久了。但是，他們的頑強著實讓拉賈克斯遭遇很大的挫折，對他的國王而來，這更是沉重的打擊。等等，國王?難以置信...', `FemaleText_loc7`='Por desgracia, la defensa del elfo de la noche era insostenible y Rajaxx sabía que no podrían aguantar mucho más. Su tenacidad, sin embargo, estaba provocando una gran frustración a Rajaxx e incluso más a su rey. Espera, ¿reyes? Increíble...' WHERE `ID`=10843;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안퀴라즈의 쌍둥이 제왕으로 알려진 베크닐라쉬와 베클로어는 그들의 신전에 있는 성역에서 이 전투를 지켜보고 있었습니다. 이 영악한 형제는 스태그헬름의 군대를 혼란에 빠뜨리고 갈라놓을 수 있는 계략을 궁리했지요.', `FemaleText_loc4`='维克尼拉斯和维克洛尔是安其拉的两位孪生帝王，他们在神殿圣地中关注着这场战争。这对聪明的兄弟想出了一个计划，想要挫败离间鹿盔的军队。', `FemaleText_loc5`='維克尼拉斯和維克洛爾是安其拉的兩位雙子帝王，他們在神殿聖地中關注著這場戰爭。這對聰明的兄弟想出了一個計畫，想要挫敗離間鹿盔的軍隊。', `FemaleText_loc7`='Vek''nilash y Vek''lor, conocidos como los Emperadores Gemelos de Ahn''Qiraj, observaban la guerra desde el santuario de su templo. Los astutos hermanos tramaban un plan para desmoralizar y dividir las tropas de Corzocelada.' WHERE `ID`=10844;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='의기양양하고 기품 있는 전사였던 발스탄은 판드랄 스태그헬름의 오른팔로서 굽힐 줄 모르는 강직한 성품의 아버지를 존경하고 닮고 싶어 했답니다. 쌍둥이 제왕은 그의 이런 성격이 약점이 될 수 있다는 것을 간파했습니다.', `FemaleText_loc4`='瓦斯坦恩·鹿盔是范达尔·鹿盔的得力助手。他是个骄傲而高贵的战士，他对他的父亲抱有不可动摇的奉献和崇拜精神……两位孪生帝王认为这正是他的弱点。可以利用的弱点。', `FemaleText_loc5`='瓦爾斯坦·鹿盔是范達爾的得力助手。身為一名驕傲又高貴的戰士，他對父親的奉獻和崇拜是堅定無比的...而雙子帝王們視這點為其弱點。一個可以被利用的弱點。', `FemaleText_loc7`='Valstann Corzocelada era la mano derecha de Fandral. Digno y noble guerrero, sentía devoción por su padre... y los Emperadores Gemelos consideraban esto como una debilidad. Una debilidad que debían aprovechar.' WHERE `ID`=10845;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='퀴라지 군대에게 퇴각하여 사막의 모래 속에 매복해 있으라는 명령이 내려졌지요. 그리고 그중 일부는 스태그헬름의 군대가 최전선에서 교전 중일 때 마파람 마을을 공격하라는 명령을 받았습니다.', `FemaleText_loc4`='其拉虫人的军队奉命后撤，藏身在沙土之下。在牵制鹿盔的前线部队的同时，他们发动了对南风村的小规模袭击。', `FemaleText_loc5`='其拉蟲人的軍隊奉命後撤，藏身在沙土之下。在牽制鹿盔的前線部隊的同時，他們發動了對南風村的小規模襲擊。', `FemaleText_loc7`='Las tropas qiraji recibieron la orden de replegarse y ocultar el grueso de sus filas bajo las arenas del desierto. Se ordenó un pequeño ataque a la aldea del Viento del Sur cuando las primeras líneas del ejército de Corzocelada estaban ocupadas.' WHERE `ID`=10846;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아버지를 기쁘게 해 드리고 싶었던 발스탄은 소규모 병력을 데리고 가 마파람 마을을 사수하게 해 달라고 판드랄에게 부탁했습니다. 당시의 전황으로 볼 때는 당연히 그의 사랑하는 아들에게 잘못된 일이 생길 가능성은 전혀 없었지요. 그러나 미처 함정을 알아채지 못해, 발스탄은 매복해 있던 퀴라지에게 포로가 되었으며 마파람 마을은 흔적도 없이 사라져 버렸습니다. 라작스는 포로가 된 발스탄을 스태그헬름과 나이트 엘프 군대가 있는 최전선으로 끌고 갔습니다. 그리고 그들이 지켜보는 앞에서 이 젊은 나이트 엘프를 잔인하게 처형했습니다.', `FemaleText_loc4`='瓦斯坦恩为了取悦他的父亲，说服范达尔同意他带领一支小队前去保卫南风村。范达尔自信自己已经在这场战争中占了上风，所以坚信他的孩子不会受到伤害。不幸的是，瓦斯坦恩被埋伏在那里的其拉虫人俘虏，南风村也被攻陷了。拉贾克斯亲自将被俘虏的瓦斯坦恩带到两军阵前，他当着鹿盔和暗夜精灵军队的面残忍地处决了这个年轻的暗夜精灵。', `FemaleText_loc5`='瓦爾斯坦為了取悅他的父親，說服范達爾同意他帶領一支小隊前去保衛南風村。范達爾自信自己已經在這場戰爭中占了上風，所以堅信他的孩子不會受到傷害。不幸的是，瓦爾斯坦被埋伏在那裏的其拉蟲人俘虜，南風村也被攻陷了。拉賈克斯親自將被俘虜的瓦爾斯坦帶到兩軍陣前，他當著鹿盔和夜精靈軍隊的面殘忍地處決了這個年輕的夜精靈。', `FemaleText_loc7`='Valstann, deseoso de complacer a su padre Fandral, convenció a este para que le permitiera llevar un pequeño batallón para defender Viento del Sur. Seguro que con la batalla transcurriendo a su favor, nada le podía pasar a su amado hijo. Pero le tendieron una trampa. Valstann fue capturado por los qiraji que estaban escondidos y la aldea del Viento del Sur completamente arrasada. El propio Rajaxx llevaría al cautivo Valstann a las primeras líneas de batalla donde, ante Corzocelada y las tropas de los elfos de la noche, ejecutaría brutalmente al joven elfo de la noche.' WHERE `ID`=10847;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전쟁은 계속되었지만 위대한 지도자의 의지는 이미 꺾일 대로 꺾인 상태였습니다. 실리더스 전체가 실리시드와 그들의 화신인 퀴라지의 손아귀에 넘어가기 일보 직전이었던 것입니다.', `FemaleText_loc4`='战争还在继续，但是这位伟大领袖的意志严重受挫。整个希利苏斯很快被异种虫类和他们的其拉主人占据了。', `FemaleText_loc5`='戰爭還在繼續，但是這位偉大領袖的意志嚴重受挫。整個希利蘇斯很快被異種蟲類和他們的其拉主人佔據了。', `FemaleText_loc7`='La guerra continuó pero la voluntad del gran líder se veía minada. Silithus pronto se vio totalmente ocupada por los silítidos y sus huéspedes qiraji.' WHERE `ID`=10848;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='흠... 정말 가엾은 분이라는 생각밖에 안 드네요.', `FemaleText_loc4`='可怜的人，这已经很说明问题了。', `FemaleText_loc5`='可憐的人，這些解釋夠多了。', `FemaleText_loc7`='Pobre hombre, esto explica muchas cosas.' WHERE `ID`=10849;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나이트 엘프 군대는 운고로 분화구를 통해 타나리스 사막의 경계까지 후퇴했습니다. 그런데 운고로에 있는 무언가가 퀴라지의 침범을 막고 있었습니다. 이 글자가 무슨 뜻인지 정확하게 이해할 수는 없지만 ''신들의 땅''을 말하는 것 같아요. ''그들은 신들의 땅을 침범할 수 없었다''라고 적혀 있네요.', `FemaleText_loc4`='暗夜精灵军队不断后撤，他们穿越安戈洛环形山，一直退到塔纳利斯沙漠的边缘。由于某种原因，其拉虫人无法占据安戈洛环形山。我无法理解这究竟是为什么，但是我相信这是因为安戈洛环形山是“神的土地”。这上面说他们无法“占领神的土地”。', `FemaleText_loc5`='夜精靈軍隊不斷後撤，他們穿越安戈洛環形山，一直退到塔納利斯沙漠的邊緣。由於某種原因，其拉蟲人無法佔據安戈洛環形山。我無法理解這究竟是為什麼，但是我相信這是因為安戈洛環形山是「神的土地」。這上面說他們無法「佔領神的土地」。', `FemaleText_loc7`='"El ejército del elfo de la noche se vio obligado a retroceder a través de Un''Goro hasta las fronteras del Desierto de Tanaris. Algo en Un''Goro impedía a los qiraji tomar aquellas tierras. No entiendo muy bien esta palabra pero creo que es "Tierras del Dios". Dice que ellos no podían "tomar las Tierras del Dios"."' WHERE `ID`=10850;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놀랍군요. 이것은 티탄이 칼림도어에 살았을 때 운고로가 그의 집이었다는 주장들과 일치합니다. 아마도 아만툴이 직접 ''신들의 땅''을 지키고 있었던 것 같습니다.', `MaleText_loc4`='太神奇了，这与卡利姆多的泰坦以安戈洛环形山为家的说法不谋而合。或许阿曼苏尔在亲自守护着这块“神的土地”。', `MaleText_loc5`='太神奇了，這與卡林多的泰坦以安戈洛環形山為家的說法不謀而合。或許阿曼蘇爾在親自守護著這塊「神的土地」。', `MaleText_loc7`='"Fascinante, esto coincide con la teoría que afirma que Un''Goro fue el hogar de los titanes cuando habitaron Kalimdor. Quizás fuera Aman''thul quien velaba por las "Tierras del Dios"."', `FemaleText_loc1`='놀랍군요. 이것은 티탄이 칼림도어에 살았을 때 운고로가 그의 집이었다는 주장들과 일치합니다. 아마도 아만툴이 직접 ''신들의 땅''을 지키고 있었던 것 같습니다.', `FemaleText_loc4`='太神奇了，这与卡利姆多的泰坦以安戈洛环形山为家的说法不谋而合。或许阿曼苏尔在亲自守护着这块“神的土地”。', `FemaleText_loc5`='太神奇了，這與卡林多的泰坦以安戈洛環形山為家的說法不謀而合。或許阿曼蘇爾在親自守護著這塊「神的土地」。', `FemaleText_loc7`='"Fascinante, esto coincide con la teoría que afirma que Un''Goro fue el hogar de los titanes cuando habitaron Kalimdor. Quizás fuera Aman''thul quien velaba por las "Tierras del Dios"."' WHERE `ID`=10851;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='흠, 이상하군요... 여기서 갑자기 끝나 버리네요. 타나리스에서 청동용군단과 마주친 퀴라지 문서... 이 부분에서 내용이 많이 빠진 것 같은데... 정보를 더 찾아야 해요! 그들이 다시 한 번 칼림도어를 침공할 계획을 세우고 있는 것이 분명해요!', `FemaleText_loc4`='嗯，奇怪……故事到此为止。其拉虫人在塔纳利斯遭遇一条青铜龙。这之间一定缺了不少内容……我们必须找到更多的信息！很明显，他们正在计划再次入侵卡利姆多！', `FemaleText_loc5`='嗯，奇怪...故事到此為止。其拉蟲人在塔納利斯遭遇一條青銅龍。這之間一定缺了不少內容...我們必須找到更多的資訊!很明顯，他們正在計畫再次入侵卡林多!', `FemaleText_loc7`='Mmm, qué extraño... Acaba repentinamente. En Tanaris los qiraji documentan un enfrentamiento con un dragón de bronce. Aquí falta mucha información... ¡Tenemos que encontrarla! ¡Sin duda planean invadir Kalimdor de nuevo!' WHERE `ID`=10852;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 점점 언짢아합니다.', `MaleText_loc4`='%s艰难地移动着。', `MaleText_loc5`='%s艱難地移動著。', `MaleText_loc7`='%s se mueve con inquietud.' WHERE `ID`=10853;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 때가 아닙니다, 락스베인 양. 때가 되면 모든 것이 밝혀질 것입니다. 주인님께서는 아직도 혼란스러워 하고 계십니다. 노즈도르무 혈족이 이 땅에 돌아왔는지 하늘을 보십시오..', `MaleText_loc4`='我的女士，时机成熟时，一切都将真相大白。即使是现在，主人也还在活动中。看那天空，诺兹多姆的子嗣回来了。', `MaleText_loc5`='我的女士，時機成熟時，一切都將真相大白。即使是現在，主人也還在活動中。看那天空，諾茲多姆的子嗣回來了。', `MaleText_loc7`='A su debido tiempo, mi señora. Todo se aclarará a su debido tiempo. El maestro bulle incluso ahora. Mira a los cielos pues el Linaje de Nozdormu ha vuelto.' WHERE `ID`=10854;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 뭐라고 날 부르던데... 임프시라던가?', `MaleText_loc4`='有人叫我……伊普斯？', `MaleText_loc5`='有人叫我...伊普斯?', `MaleText_loc7`='Algunos me llaman... ¿Diblis?' WHERE `ID`=10855;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='10분 후 밀짚인형 축제가 시작됩니다! 축제에 참가하여 할로윈 축제도 즐기고 우리가 스컬지로부터 해방된 날을 축하하세요! 장소는 로데론의 폐허 안마당입니다.', `FemaleText_loc4`='稻草人庆典将在10分钟后开始！快来洛丹伦废墟的庭院里庆祝万圣节，庆祝我们摆脱亡灵天灾，获得自由！', `FemaleText_loc5`='稻草人慶典將在10分鐘後開始!快到幽暗城中庭歡慶節日吧，慶祝萬鬼節，慶祝我們擺脫天譴軍團，獲得自由!', `FemaleText_loc7`='¡El Festival del Hombre de Mimbre comenzará en diez minutos! ¡Únete a nosotros en el patio de las Ruinas de Lordaeron para celebrar Halloween y nuestra liberación de la Plaga!' WHERE `ID`=10856;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이방인이여, 당장 떠나십시오! 당신과는 볼일이 없습니다.', `MaleText_loc4`='陌生人，赶快离开！我跟你没有关系。', `MaleText_loc5`='快點離開，陌生人!我和你沒什麼好說的。', `MaleText_loc7`='¡Márchate inmediatamente! No tengo nada que tratar contigo.' WHERE `ID`=10857;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 돌아오셨군요! 뭘 도와드릴까요?', `MaleText_loc4`='你已经回来了！现在，我能为你做什么呢？', `MaleText_loc5`='你已經回來了!現在，我能為你做什麼呢?', `MaleText_loc7`='¡Ya estás de vuelta! ¿Qué puedo hacer por ti en esta ocasión?' WHERE `ID`=10858;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='15분 후에 밀짚인형 화형식이 시작됩니다! 축제에 참가하여 할로윈 축제도 즐기고 우리가 스컬지로부터 해방된 날을 축하하세요! 장소는 바로 언더시티 서쪽입니다.', `FemaleText_loc4`='15分钟之后将点燃稻草人！快来幽暗城西边欢庆节日吧，庆祝万圣节，庆祝我们摆脱亡灵天灾，获得自由！', `FemaleText_loc5`='15分鐘之後將點燃稻草人!快來幽暗城西邊歡慶節日吧，慶祝萬鬼節，慶祝我們擺脫天譴軍團，獲得自由!', `FemaleText_loc7`='¡La quema del Hombre de Mimbre dará comienzo en quince minutos! Ven al festival, que se celebra en el oeste de Entrañas, y festeja Halloween y nuestra liberación de la Plaga.' WHERE `ID`=10859;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='5분 후에 밀짚인형 화형식이 시작됩니다! 축제에 참가하여 할로윈 축제도 즐기고 우리가 스컬지로부터 해방된 날을 축하하세요! 장소는 바로 언더시티 서쪽입니다.', `FemaleText_loc4`='5分钟之后将点燃稻草人！快来幽暗城西边欢庆节日吧，庆祝万圣节，庆祝我们摆脱亡灵天灾，获得自由！', `FemaleText_loc5`='5分鐘之後將點燃稻草人!快來幽暗城西邊歡慶節日吧，慶祝萬鬼節，慶祝我們擺脫天譴軍團，獲得自由!', `FemaleText_loc7`='¡La quema del Hombre de Mimbre dará comienzo en cinco minutos! Ven al festival, que se celebra en el oeste de Entrañas, y festeja Halloween y nuestra liberación de la Plaga.' WHERE `ID`=10860;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='밀짚인형 축제를 시작합니다! 포세이큰 만세!', `FemaleText_loc4`='稻草人节日开始了！愿被遗忘者的力量永存！', `FemaleText_loc5`='稻草人節日開始了!願被遺忘者的力量永存!', `FemaleText_loc7`='¡Comienza el Festival del Hombre de Mimbre! ¡Poder para los Renegados!' WHERE `ID`=10861;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 호드와의 전쟁이 임박했네. 지금은 얼라이언스에 매우 중요한 때이니 우리 모두 각자 맡은 역할을 수행하는 데 온 힘을 기울여야 하네.', `MaleText_loc4`='与部落之间的战争已经到了白热化的阶段，$n。联盟需要大量的物资，我们应竭尽所能，提供帮助。', `MaleText_loc5`='與部落之間的戰爭已經到了白熱化的階段，$n。聯盟需要大量的物資，我們應竭盡所能，提供幫助。', `MaleText_loc7`='La guerra contra la Horda está en su apogeo, $n. Es un momento de gran necesidad para la Alianza y es necesario que cada uno de nosotros cumplamos con nuestro cometido.' WHERE `ID`=10862;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 전쟁이 코앞에 다가왔소. 모든 호드는 부름에 응하여 얼라이언스 겁쟁이들과의 전투에 참가해야 하오.', `MaleText_loc4`='战争即将来临，$n。每个部落成员都要响应号召，并肩击溃懦弱的联盟。', `MaleText_loc5`='戰爭即將來臨，$n。每個部落成員都要響應號召，並肩擊潰懦弱的聯盟。', `MaleText_loc7`='La guerra se cierne sobre nosotros, $n. Es hora de que cada uno de los miembros de la Horda atienda la llamada y se una a la lucha contra la acobardada Alianza.' WHERE `ID`=10863;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 땅을 둘러보고 이만하면 괜찮다는 듯이 고개를 끄덕입니다.', `MaleText_loc4`='%s检查地面，满意地点着头。', `MaleText_loc5`='%s檢查地面，滿意地點著頭。', `MaleText_loc7`='%s inspecciona el terreno y hace una seña de aprobación.' WHERE `ID`=10864;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조금 부족한 듯싶군.', `MaleText_loc4`='我认为这还不够。', `MaleText_loc5`='我認為這還不夠。', `MaleText_loc7`='No creo que sea lo suficientemente fuerte.' WHERE `ID`=10865;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 나를 따라오라. 저기서 조금만 돌면 바로 호수니라.', `MaleText_loc4`='来吧，$n。湖泊就在拐弯处。', `MaleText_loc5`='來吧，$n。湖泊就在拐彎處。', `MaleText_loc7`='Ven, $n. El lago está a la vuelta de la esquina.' WHERE `ID`=10866;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 옆에 바짝 붙으라. 아무 일 없도록 내가 지켜주겠다.', `MaleText_loc4`='靠近我，$n。我会保护你的。', `MaleText_loc5`='靠近我，$n。我會保護你的。', `MaleText_loc7`='Quédate a mi lado, $n. Yo te protegeré si algo va mal.' WHERE `ID`=10867;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말퓨리온!', `MaleText_loc4`='玛法里奥！', `MaleText_loc5`='瑪法里恩!', `MaleText_loc7`='¡Malfurion!' WHERE `ID`=10868;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='레물로스, 내 오랜 벗이여... 다시 만나 반갑네. 자네에게 어떻게든 그 전갈이 전해질 거라 생각했네.', `MaleText_loc4`='雷姆洛斯，我的老朋友。能再见到你真好。我知道消息会传到你这里的——它终究会?到你这里。', `MaleText_loc5`='雷姆洛斯，我的老朋友。能再見到你真好。我知道消息會傳到你這裏的─它終究會傳到你這裏。', `MaleText_loc7`='Remulos, camarada. Me alegro de volver a verte. Sabía que te llegaría el mensaje, de un modo u otro.' WHERE `ID`=10869;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말퓨리온, 온통 악몽만 꾸었어. 도대체 에메랄드의 꿈속에서 무슨 일이 일어나고 있는 거지? 무엇 때문에 그렇게 끔찍한 일이 벌어진 걸까?', `MaleText_loc4`='玛法里奥，梦魇里到处是尸体。究竟发生了什么事？是什么造成了这样的暴行？', `MaleText_loc5`='瑪法里恩，夢境裡到處是屍體。究竟發生了什麼事?是什麼造成了這樣的暴行?', `MaleText_loc7`='Evidenciaba terror, Malfurion. ¿Qué está ocurriendo en el Sueño? ¿Qué pudo ser la causa de tales atrocidades?' WHERE `ID`=10870;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='친구여, 나는 사태가 악화될까 두렵네. 에메랄드의 꿈속에서 우리는 고대의 악마로 태어난 새로운 적과 싸우고 있네. 이세라의 고귀한용군단은 고대의 속삭임에 희생되었네. 마치 악몽이 차원의 경계를 뚫고 아제로스에서 새로운 숙주를 찾고 있는 것 같네.', `MaleText_loc4`='我担心事情不妙，老朋友。在梦中我们跟一个新的敌人作战，他是个远古的邪灵。伊瑟拉高贵的血脉成为了它们的牺牲品。似乎梦魇已经冲破了束缚，想要在艾泽拉斯寻找新的宿主。', `MaleText_loc5`='我擔心事情不妙，老朋友。在夢境裡我們跟一個新的敵人作戰，他是個遠古的邪靈。伊瑟拉高貴的血脈成為了它們的犧牲品。似乎夢魘已經衝破了束縛，想要在艾澤拉斯尋找新的宿主。', `MaleText_loc7`='Me temo lo peor, viejo amigo. En el Sueño nos enfrentamos a un enemigo desconocido, nacido de un mal ancestral. Ysera ha caído víctima de los viejos susurros. Parece que la Pesadilla ha penetrado en el reino y busca un nuevo huésped en Azeroth.' WHERE `ID`=10871;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 역시 많은 것이 느껴져, 말퓨리온. 암울한 시대가 다가오고 있어.', `MaleText_loc4`='玛法里奥，我跟你有相同的感觉。黑暗的岁月即将降临。', `MaleText_loc5`='瑪法里恩，我跟你有相同的感覺。黑暗的歲月即將降臨。', `MaleText_loc7`='Yo he sentido lo mismo, Malfurion. Se avecinan días aciagos.' WHERE `ID`=10872;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇다네, 레물로스. 아제로스의 종족들은 이제 그들과 맞설 준비를 해야 해.', `MaleText_loc4`='嗯，雷姆洛斯。让人类准备就绪吧。', `MaleText_loc5`='嗯，雷姆洛斯。讓人類準備好吧。', `MaleText_loc7`='Eh, Remulos. Prepara a las razas mortales.' WHERE `ID`=10873;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말퓨리온, 지나치게 앞서 가는군. 현재 아제로스 자손들 사이에서 평화는 거의 찾아볼 수가 없는 지경일세. 그나저나 우리 아버지는 어떤가? 자네 형제는? 뭐 새로운 소식은 없나?', `MaleText_loc4`='玛法里奥，你离开得太久了。艾泽拉斯的和平是如此的脆弱。我的父亲怎么样了？你的兄弟呢？你有什么消息吗？', `MaleText_loc5`='瑪法里恩，你離開得太久了。艾澤拉斯的和平是如此的脆弱。我的父親怎麼樣了?你的兄弟呢?你有什麼消息嗎?', `MaleText_loc7`='Has estado ausente mucho tiempo, Malfurion. La paz entre los hijos de Azeroth es, como mucho, débil. ¿Sabes algo de mi padre? ¿Y de tu hermano? ¿Tienes noticias de ellos?' WHERE `ID`=10874;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그대는 가죽세공인이 맞으시죠? 그대에게서 경화 가죽 냄새가 나요. 그 냄새라면 어디서든 분간할 수 있죠.$B$B아버지 말씀으로는 수 세기 전 마파람 마을에 유명한 가죽세공의 장인이 살았었대요. 유감스럽게도 지금 그곳은 폐허가 됐지만...', `FemaleText_loc4`='你是个皮革商吧？我对兽皮的味道再熟悉不过了。$B$B我的父亲过去常常跟我谈起数世纪前一位居住在南风村的著名工匠。很遗憾，那儿已是一片废墟了。', `FemaleText_loc5`='你是個皮革商吧?我對獸皮的味道再熟悉不過了。$B$B我的父親過去常常跟我談起數世紀前一位居住在南風村的著名工匠。很遺憾，那兒已是一片廢墟了。', `FemaleText_loc7`='Eres un peletero de oficio, ¿no es así? Es ese ligero aroma a pieles curtidas, lo reconocería en cualquier parte.$B$BMi padre solía hablar de un famoso artesano que vivió en la aldea del Viento del Sur siglos atrás. Es una lástima que el lugar ahora esté en ruinas.' WHERE `ID`=10875;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세나리우스는 내 편이 돼주기로 했네. 아웃랜드로 간 일리단은 거기서 왕좌에 앉아 있네. 그런데 아서스에게 패한 게 원통했기 때문인지 완전히 미쳐버리고 말았어. 광기에 휩싸여 하루에도 천 번 그때 그 사건을 마음속으로 재연하고 있네. 아서스를 무찌르고 승리하는 상상을 하는 거지. 그는 제정신이 아니야. 친구여, 난 머지않아 우리가 시험을 받게 될 날이 오지 않을까 두렵네. 진아즈샤리의 샘에서처럼 잘해낼 수 있을 자신도 없고 말일세.', `MaleText_loc4`='塞纳留斯与我并肩作战。伊利丹坐在外域高高的王座上沉思着，恐怕与阿尔萨斯一战的失利将成为他人生的转折点。他已经完全疯了，雷姆洛斯。每天，他都在脑海中数千次地重现那场战斗，但是他始终认为自己才是胜利者，他完全击溃了阿尔萨斯。老朋友，他已经极度癫狂了。我担心我们接受考验的时候到了，这一次跟上次在艾萨拉进行的永恒之井战役可大不一样。', `MaleText_loc5`='塞納留斯與我並肩作戰。伊利丹坐在外域高高的王座上沉思著，恐怕與阿薩斯一戰的失利將成為他人生的轉捩點。他已經完全瘋了，雷姆洛斯。每天，他都在腦海中數千次地重現那場戰鬥，但是他始終認為自己才是勝利者，他完全擊潰了阿薩斯。老朋友，他已經極度癲狂了。我擔心我們接受考驗的時刻到了，這一次跟上次在辛艾薩拉進行的永恆之井戰役可大不一樣。', `MaleText_loc7`='Cenariuslucha en mi bando. Illidan permanece en lo alto de su trono en Terrallende, cavilando. Me temo que la derrota ante Arthas resultó ser la gota que colmó el vaso. Ha caído en la locura, Remulos. Reproduce los acontecimientos en su cabeza mil veces al día, pero en su cabeza, él es el vencedor y Arthas está al borde de la derrota. Su estado es preocupante, $gamigo mío:amiga mía;. Me temo que llegará el momento en el que se ponga a prueba nuestro vínculo y no será como en el Pozo de Zin-Azshari.' WHERE `ID`=10876;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오랜 친구여, 부디... 잘 가게...', `MaleText_loc4`='老朋友，再见了……再见……', `MaleText_loc5`='老朋友，再見了...再見...', `MaleText_loc7`='Adiós, camarada... Adiós...' WHERE `ID`=10877;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='레물로스, 나는 다시 빨려들어가고 있네. 티란데... 그녀에게 사랑한다고... 난 잘 있다고 전해 주게. 꼭 그녀에게 돌아가겠다고... 잘 있게.', `MaleText_loc4`='雷姆洛斯，我正在被拖回梦境……泰兰德……告诉她……告诉她我很安全。告诉她……告诉她我会回来的……再见……', `MaleText_loc5`='雷姆洛斯，我正在被拖回夢境...泰蘭妲...告訴她...告訴她我很安全。告訴她...告訴她我會回來的...再見...', `MaleText_loc7`='Remulos, he de irme... Tyrande... dile que la quiero... Dile que estoy bien. Dile... Dile que volveré. Adiós...' WHERE `ID`=10878;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='숲으로 돌아가자.', `MaleText_loc4`='凡人，让我们回到树林去吧。', `MaleText_loc5`='凡人，讓我們回到樹林去吧。', `MaleText_loc7`='Déjanos regresar al bosque, mortal.' WHERE `ID`=10879;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생명의 끈이 끊어졌다! 꿈꾸는 자들을 위해 복수하리라!', `MaleText_loc4`='生命的希冀已被切断！梦游者要展开报复！', `MaleText_loc5`='生命的希冀已被切斷!夢遊者要展開報復!', `MaleText_loc7`='¡Los hilos de la VIDA se han roto! ¡Tenemos que vengar a los Soñadores!' WHERE `ID`=10880;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모습을 드러내라, 꿈꾸는 자들아. 당당히 복수를 외쳐라!', `MaleText_loc4`='来吧，梦游者——复仇！', `MaleText_loc5`='來吧，夢遊者─復仇!', `MaleText_loc7`='Venid, Soñadores ¡y reclamad venganza!' WHERE `ID`=10881;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 타락한 영혼들이 나의 힘을 강하게 해 줄 것이다!', `MaleText_loc4`='让我吞噬你的灵魂吧！', `MaleText_loc5`='讓我吞噬你的靈魂吧!', `MaleText_loc7`='¡Sus malvadas almas alimentan mi poder!' WHERE `ID`=10882;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈들의 마음속에서 어둠이 느껴지는구나. 사악한 존재가 쉴 곳은 없다!', `MaleText_loc4`='我能感受到你内心的阴影。邪恶的侵蚀永远不会停止！', `MaleText_loc5`='我能感受到你內心的陰影。邪惡侵蝕永不停止!', `MaleText_loc7`='Puedo sentir la SOMBRA en sus corazones. ¡No puede haber descanso para los malos!' WHERE `ID`=10883;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희의 타락한 세상을 맛 보아라!', `MaleText_loc4`='尝尝堕落的滋味吧！', `MaleText_loc5`='嘗嘗墮落的滋味吧!', `MaleText_loc7`='¡Prueben la corrupción de su mundo!' WHERE `ID`=10884;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='희망은 영혼의 병! 이 땅은 말라 죽을 것이다!', `MaleText_loc4`='希望是灵魂染上的疾病！这片土地应该枯竭，从此死气腾腾！', `MaleText_loc5`='希望是靈魂染上的疾病!這片土地應該枯竭，從此死氣騰騰!', `MaleText_loc7`='¡La esperanza es una ENFERMEDAD del alma! ¡Esta tierra se marchitará y morirá!' WHERE `ID`=10885;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='평화란 부질없는 꿈일 뿐! 이 세상은 악몽이 지배할 것이다!', `MaleText_loc4`='和平不过是短暂的梦想！让梦魇统治整个世界吧！', `MaleText_loc5`='和平不過是短暫的夢想!讓夢魘統治整個世界吧!', `MaleText_loc7`='¡La paz no es más que un sueño fugaz! ¡Que reine la PESADILLA!' WHERE `ID`=10886;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='광기의 아이들아, 마음껏 활개치고 다니거라!', `MaleText_loc4`='疯狂的种子——我将你释放到这个世界！', `MaleText_loc5`='瘋狂的種子─我將你釋放到這個世界!', `MaleText_loc7`='Hijos de la Locura, ¡yo os libero en este mundo!' WHERE `ID`=10887;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='덤벼라, 하룻강아지들아! 그렇게 죽음을 재촉하고 싶더냐? 나 로만칸은 안퀴라즈의 비밀을 무덤까지 가져갈 것이다!', `MaleText_loc4`='来吧，渺小的凡人。来面对你们的死亡。安其拉的秘密将与洛曼卡恩一起永远消失！', `MaleText_loc5`='來吧，渺小的凡人。來面對你們的死亡。安其拉的秘密將與洛曼卡恩一起永遠消失!', `MaleText_loc7`='¡Vengan, insignificantes mortales! Vengan y enfréntense a su fin. ¡Los secretos de Ahn''Qiraj morirán con Roman''khan!' WHERE `ID`=10888;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오, $n 님! 다시 만나서 반가워요. 그동안 잘 지내셨죠?', `FemaleText_loc4`='啊，$n——很高兴再次见到你。我相信你的事业进展得很顺利。', `FemaleText_loc5`='嗯，$n - 很高興再見到你。我相信你的事情進行的很順利。', `FemaleText_loc7`='Ah, $n – me alegro de volver a verte. Confío en que tus asuntos vayan bien.' WHERE `ID`=10889;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필요한 양을 모두 모았군. 만세!', `MaleText_loc4`='所有的物资都准备妥当了。哈哈！', `MaleText_loc5`='所有的資源都收集好了。萬歲!', `MaleText_loc7`='Se han recogido todos los objetos. ¡Yupi!' WHERE `ID`=10890;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필요한 구리 주괴를 모두 모았습니다. 도와주셔서 감사합니다, $c|1이여;여;. 이곳에서 다른 재료를 모으는 일도 도와주지 않으시겠습니까?', `MaleText_loc4`='我们已经集齐了所需的铜锭。谢谢你的帮助，$C。你还可以帮帮其他正在收集作战物资的人。', `MaleText_loc5`='我們已經有所有需要的銅錠了。謝謝你的幫忙，$c。你應該想在這裡協助我們收集另一種材料。', `MaleText_loc7`='Tenemos todas las barras de cobre que necesitamos. Gracias por tu ayuda, $c. Quizás quieras echar una mano en la recogida del resto de materiales.' WHERE `ID`=10891;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구리 주괴가 더 필요합니다! 안퀴라즈 성문 앞에 전쟁의 열기가 끓어가고 있는 상황에서 전쟁 물자를 비축해야 합니다. 지금까지 얼라이언스 연합에서 모은 것은 $1997w개인데 우리에게 필요한 것은 모두 $1998w개입니다. 구리 주괴를 다 모으지 못하면 제가 혼이 날지도 몰라요.', `MaleText_loc4`='$C，我需要更多的铜锭！安其拉之战迫在眉睫，我们需要战争物资！联盟已经收集到$1997w块铜锭了，总的需求量是$1998w块。如果我不能完成任务，我就会被砍头的！', `MaleText_loc5`='$C，我需要更多銅錠!安其拉之門的戰爭迫在眉睫，我們需要作戰物資!聯盟已經收集了$1997w塊銅錠，總需求量是$1998w塊。如果我沒有完成任務，我的人頭就要落地了!', `MaleText_loc7`='$C, ¡necesito más barras de cobre! ¡Se avecina una guerra en las Puertas de Ahn''Qiraj y necesitamos suministros! La Alianza ha reunido $1997w y necesitamos $1998w barras de cobre en total. Si no consigues esas barras de cobre, ¡me cortarán el cuello!' WHERE `ID`=10892;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 분노가 자유롭게 되었구나!', `MaleText_loc4`='我的愤怒释放出来了！', `MaleText_loc5`='我的憤怒釋放出來了!', `MaleText_loc7`='¡Se ha desatado mi ira!' WHERE `ID`=10893;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 3초 후 작동합니다!', `MaleText_loc4`='%s将在3秒内安装完毕！', `MaleText_loc5`='%s將在3秒鐘內準備完畢!', `MaleText_loc7`='¡%s estará armada en 3 segundos!' WHERE `ID`=10894;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미올로 씨, 한때 갑옷제작자였던 제가 무기제작의 도를 배우고자 합니다. 저를 가르쳐 주십시오.', `MaleText_loc4`='米洛尔，我以前曾是个护甲铸造师，但我现在想要成为一个武器铸造师，你能帮帮我吗？', `MaleText_loc5`='米洛爾，我以前曾是個護甲鍛造師，但我現在想要成為一個武器鍛造師，你能幫幫我嗎?', `MaleText_loc7`='Myolor, en su día fui forjador de armaduras y en su lugar deseo aprender el oficio de forjador de armas. ¿Me enseñarás?', `FemaleText_loc1`='미올로 씨, 한때 갑옷제작자였던 제가 무기제작의 도를 배우고 싶습니다. 저를 가르쳐 주십시오.', `FemaleText_loc4`='米洛尔，我以前曾是个护甲铸造师，但我现在想要成为一个武器铸造师，你能帮帮我吗？', `FemaleText_loc5`='米洛爾，我以前曾是個護甲鍛造師，但我現在想要成為一個武器鍛造師，你能幫幫我嗎?', `FemaleText_loc7`='Myolor, en su día fui forjadora de armaduras y en su lugar deseo aprender el oficio de forjadora de armas. ¿Me enseñarás?' WHERE `ID`=10895;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미올로 씨, 한때 무기제작자였던 제가 갑옷제작자의 도를 배우고자 합니다. 저를 가르쳐 주십시오.', `MaleText_loc4`='米洛尔，我以前曾是个武器铸造师，但我现在想要成为一个护甲铸造师，你能帮帮我吗？', `MaleText_loc5`='米洛爾，我以前曾是個武器鍛造師，但我現在想要成為一個護甲鍛造師，你能幫幫我嗎?', `MaleText_loc7`='Myolor, en su día fui forjador de armas y en su lugar deseo aprender el oficio de forjador de armaduras. ¿Me enseñarás?', `FemaleText_loc1`='미올로 씨, 한때 무기제작자였던 제가 갑옷제작자의 도를 배우고 싶습니다. 저를 가르쳐 주십시오.', `FemaleText_loc4`='米洛尔，我以前曾是个武器铸造师，但我现在想要成为一个护甲铸造师，你能帮帮我吗？', `FemaleText_loc5`='米洛爾，我以前曾是個武器鍛造師，但我現在想要成為一個護甲鍛造師，你能幫幫我嗎?', `FemaleText_loc7`='Myolor, en su día fui forjadora de armas y en su lugar deseo aprender el oficio de forjadora de armaduras. ¿Me enseñarás?' WHERE `ID`=10896;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크라토크 씨, 한때 갑옷제작자였던 제가 무기제작의 도를 배우고자 합니다. 저를 가르쳐 주십시오.', `MaleText_loc4`='克拉索克，我以前曾是个护甲铸造师，但我现在想要成为一个武器铸造师，你能帮帮我吗？', `MaleText_loc5`='克拉索克，我以前曾是個護甲鍛造師，但我現在想要成為一個武器鍛造師，你能幫幫我嗎?', `MaleText_loc7`='Krathok, en su día fui forjador de armaduras y en su lugar deseo aprender el oficio de forjador de armas. ¿Me entrenarás?', `FemaleText_loc1`='크라토크 씨, 한때 갑옷제작자였던 제가 무기제작의 도를 배우고 싶습니다. 저를 가르쳐 주십시오.', `FemaleText_loc4`='克拉索克，我以前曾是个护甲铸造师，但我现在想要成为一个武器铸造师，你能帮帮我吗？', `FemaleText_loc5`='克拉索克，我以前曾是個護甲鍛造師，但我現在想要成為一個武器鍛造師，你能幫幫我嗎?', `FemaleText_loc7`='Krathok, en su día fui forjadora de armaduras y en su lugar deseo aprender el oficio de forjadora de armas. ¿Me entrenarás?' WHERE `ID`=10897;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크라토크 씨, 한때 무기제작자였던 제가 갑옷제작자의 도를 배우고자 합니다. 저를 가르쳐 주십시오.', `MaleText_loc4`='克拉索克，我以前曾是个武器铸造师，但我现在想要成为一个护甲铸造师，你能帮帮我吗？', `MaleText_loc5`='克拉索克，我以前曾是個武器鍛造師，但我現在想要成為一個護甲鍛造師，你能幫幫我嗎?', `MaleText_loc7`='Krathok, en su día fui forjador de armas y en su lugar deseo aprender el oficio de forjador de armaduras. ¿Me entrenarás?', `FemaleText_loc1`='크라토크 씨, 한때 무기제작자였던 제가 갑옷제작자의 도를 배우고 싶습니다. 저를 가르쳐 주십시오.', `FemaleText_loc4`='克拉索克，我以前曾是个武器铸造师，但我现在想要成为一个护甲铸造师，你能帮帮我吗？', `FemaleText_loc5`='克拉索克，我以前曾是個武器鍛造師，但我現在想要成為一個護甲鍛造師，你能幫幫我嗎?', `FemaleText_loc7`='Krathok, en su día fui forjadora de armas y en su lugar deseo aprender el oficio de forjadora de armaduras. ¿Me entrenarás?' WHERE `ID`=10898;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수정 안으로 거대한 통로가 굴처럼 뚫려 있는 것이 비춰 보입니다. 직감으로 그곳이 화산 심장부라는 것을 알 수 있습니다.', `MaleText_loc4`='你在水晶中看到了巨大的通道和走廊。你认得这个地方：熔火之心。', `MaleText_loc5`='你在水晶中看到了巨大的通道和走廊。你認得這個地方:熔火之心。', `MaleText_loc7`='Ves unos largos túneles y pasillos cavernosos reflejados en el interior del cristal. Reconoces el área como el Núcleo de Magma.' WHERE `ID`=10899;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불안정한 균열의 수정을 건드립니다.', `MaleText_loc4`='<触摸这块不稳定的裂隙水晶。>', `MaleText_loc5`='<觸摸這塊不穩定的裂隙水晶。>', `MaleText_loc7`='<Toca la inestable fisura del cristal.>', `FemaleText_loc1`='불안정한 균열의 수정을 건드립니다.', `FemaleText_loc4`='<触摸这块不稳定的裂隙水晶。>', `FemaleText_loc5`='<觸摸這塊不穩定的裂隙水晶。>', `FemaleText_loc7`='<Toca la inestable fisura del cristal.>' WHERE `ID`=10900;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들에게 푸른용군단의 분노를 느끼게 해 주소서! 말리고스시여, 저를 보호해 주소서!', `MaleText_loc4`='让他们感受蓝龙的愤怒吧！愿玛里苟斯庇护我！', `MaleText_loc5`='讓他們感受藍龍軍團的憤怒!願瑪里苟斯庇護我!', `MaleText_loc7`='¡Que sientan la cólera del Vuelo Azul! ¡Que Malygos me proteja!' WHERE `ID`=10901;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알렉스트라자시여, 제게 적들을 물리칠 수 있는 의지를 주소서!', `MaleText_loc4`='阿莱克丝塔萨，赋予我坚定的信念，让我击退敌人！', `MaleText_loc5`='雅立史卓莎，賦予我堅定的信念，讓我擊退敵人!', `MaleText_loc7`='¡Gracias a Alexstrasza estoy resuelto a acabar con nuestros enemigos!' WHERE `ID`=10902;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나약한 존재여, 끝없는 꿈속으로 빠져 들어라. 네 자신을 꿈에 맡겨라!', `FemaleText_loc4`='渺小的凡人，在无尽的噩梦中沉睡吧。让噩梦吞噬你！', `FemaleText_loc5`='渺小的凡人，在無盡的噩夢中沉睡吧。讓噩夢吞噬你!', `FemaleText_loc7`='Sucumbid al sueño interminable, pequeñajos. ¡Que te consuma!' WHERE `ID`=10903;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아나크로노스, 이런 식으로 주의를 끌면 자네와 젊은 드루이드가 문을 봉인할 시간을 벌 수 있을 것이네. 속전속결로 끝내야 하네. 자, 그럼 놈들이 혼돈의 마법에 어떻게 대응하는지 볼까?', `MaleText_loc4`='阿纳克洛斯，声东击西的战术能让你和年轻的德鲁伊有足够的时间来封印大门。不要犹豫。现在，让我们看看它们如何对付这些混乱的魔法。', `MaleText_loc5`='安納克羅斯，聲東擊西的戰術能讓你和年輕的德魯伊有足夠的時間來封印大門。不要猶豫。現在，讓我們看看它們如何對付這些混亂的魔法。', `MaleText_loc7`='Anacronos, esta estrategia de distracción os proporcionará a ti y al joven druida tiempo suficiente para cerrar la puerta. No falléis. Ahora veremos cómo se defienden de la magia caótica.' WHERE `ID`=10904;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위로!', `MaleText_loc4`='上！', `MaleText_loc5`='上面!', `MaleText_loc7`='¡Arriba!' WHERE `ID`=10905;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='순간이동장치가 명령을 기다리며 윙윙 소리를 냅니다.', `MaleText_loc4`='传送器发出嗡嗡的声响，等待着你的指令。', `MaleText_loc5`='位置轉換器發出嗡嗡聲，等待你的命令。', `MaleText_loc7`='El trasladador da zumbidos esperando tu orden.' WHERE `ID`=10906;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘의 희생을 잊지 마라, 나이트 엘프여. 우리 모두 이 괴물의 손아귀에서 얼마나 많은 고통을 받았는가!', `MaleText_loc4`='暗夜精灵，不要忘记今天牺牲的人们。这些野兽让我们蒙受了巨大的损失。', `MaleText_loc5`='別忘了今天所做的犧牲，夜精靈。這些野獸讓我們蒙受了巨大的損失。', `MaleText_loc7`='No olvides los sacrificios realizados en este día, elfo de la noche. Todos hemos sufrido con desmesura a manos de esas bestias.' WHERE `ID`=10907;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리는 놈들을 몰아낼 것입니다, 아나크로노스. 내 맹세하지요. 그대는 이번 임무를 끝까지 완수해야 합니다. 우리의 운명은 그대 손에 달렸으니 망설이지 마십시오.', `FemaleText_loc4`='阿纳克洛斯，我们会击退他们的。我发誓会支持你完成这项任务。当你动手封印这股毁灭的力量时，千万不要出错。', `FemaleText_loc5`='我們會擊退他們的，安納克羅斯。我發誓會支持你完成這項任務。當你動手封印這股毀滅的力量時，千萬不要出錯。', `FemaleText_loc7`='Haremos que retrocedan, Anacronos. Lo prometo. Completa tu cometido. No vaciles a la hora de encerrar nuestros destinos tras la barrera.' WHERE `ID`=10908;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서둘러야 하오. 그렇지 않으면 모두 끝장이오!', `MaleText_loc4`='我们必须赶快，否则就一切都太晚了！', `MaleText_loc5`='我們一定要動作迅速否則就會失去一切!', `MaleText_loc7`='¡Debemos actuar con rapidez o estaremos perdidos!' WHERE `ID`=10909;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나의 군대로는 퀴라지의 방어선을 뚫을 수가 없네. 용이여, 그대의 영검한 보호막을 칠 수 있을 만큼 가까이 갈 수가 없네.', `MaleText_loc4`='我的军队不足以抵抗安其拉的部队。我们无法走到足够近的地方，启动你那宝贵的魔法屏障。', `MaleText_loc5`='我的軍隊不足以抵抗安其拉的部隊。我們靠的不夠近，無法啟動你那寶貴的魔法屏障。', `MaleText_loc7`='Mis tropas no pueden superar las defensas qiraji. No seremos capaces de acercarnos lo suficiente para que puedas colocar tu preciada barrera, dragón.' WHERE `ID`=10910;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='방법이 있기는 한데...', `FemaleText_loc4`='还有一个办法……', `FemaleText_loc5`='有一個辦法...', `FemaleText_loc7`='Hay un modo...' WHERE `ID`=10911;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 동료를 힐끗 쳐다봅니다.', `FemaleText_loc4`='%s看了一眼她的同胞。', `FemaleText_loc5`='%s看了她的同胞們一眼。', `FemaleText_loc7`='%s mira a sus compatriotas.' WHERE `ID`=10912;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 알았다는 듯 고개를 끄덕입니다.', `MaleText_loc4`='%s心照不宣地点了点头。', `MaleText_loc5`='%s心照不宣地點了點頭。', `MaleText_loc7`='%s hace un gesto de complicidad.' WHERE `ID`=10913;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판드랄, 언제나 이 말을 명심해라. 비탄에 빠져 신념이 흔들리지 않도록 해라. 만일 그렇게 된다면 네가 가는 곳마다 어둠이 깔리게 될 것이다, 나이트 엘프여. 그릇된 복수심으로는 결코 죄를 사할 수 없다.', `MaleText_loc4`='范达尔，记住我的话：别让悲痛动摇了你的信念。你的思想……将把你引入黑暗，暗夜精灵。误入歧途的复仇是不能被赦免的。', `MaleText_loc5`='嘿，范達爾，記住這些話:別讓悲痛動搖了你的信念。你的思想...將把你引入黑暗，夜精靈。誤入歧途的復仇是不能被赦免的。', `MaleText_loc7`='Fandral, recuerda estas palabras: no permitas que el dolor guíe tu fe. Estos pensamientos que albergas... los lugares aciagos a los que te diriges, elfo de la noche. La absolución no se alcanza mediante la errada venganza.' WHERE `ID`=10914;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금이오, 스태그헬름! 지금 시작하겠으니 마법을 준비하시오!', `MaleText_loc4`='鹿盔！我们走吧！准备好你的魔法！', `MaleText_loc5`='現在，鹿盔!我們走吧!準備好你的魔法!', `MaleText_loc7`='¡AHORA, CORZOCELADA! ¡ALLÁ VAMOS! ¡Prepara tu magia!' WHERE `ID`=10915;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비됐다, 용이여. 시작하라.', `MaleText_loc4`='完成了。你来带路吧。', `MaleText_loc5`='完成了。你來帶路吧。', `MaleText_loc7`='Ya está, dragón. Ve tú delante.' WHERE `ID`=10916;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가까이 있으시오...', `MaleText_loc4`='靠近些……', `MaleText_loc5`='跟緊一點...', `MaleText_loc7`='No os separéis mucho...' WHERE `ID`=10917;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, $r. 살아 있기에 정말 좋은 날이지 않습니까?', `MaleText_loc4`='你好，$r。活着真好，不是吗？', `MaleText_loc5`='你好，$r。活著真好，不是嗎?', `MaleText_loc7`='Saludos, $r. Bonito día para vivir, ¿verdad?', `FemaleText_loc1`='안녕하십니까, $r. 살아 있기에 정말 좋은 날이지 않습니까?', `FemaleText_loc4`='你好，$r。活着真好，不是吗？', `FemaleText_loc5`='你好，$r。活著真好，不是嗎?', `FemaleText_loc7`='Saludos, $r. Bonito día para vivir, ¿verdad?' WHERE `ID`=10918;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모든 타우렌이 당신네 종족을 싫어하는 것은 아닙니다, $r. 그렇지만, 당신에게 내 와이번을 태워드릴 순 없군요.', `MaleText_loc4`='并不是所有牛头人都藐视你们$r。不过，我无法向你提供服务。', `MaleText_loc5`='並不是所有牛頭人都藐視你們$r。不過，我無法向你提供服務。', `MaleText_loc7`='No todos los tauren desprecian a los de tu raza, $r. Lamentablemente, no se me permite ofrecerte mis servicios.', `FemaleText_loc1`='모든 타우렌이 당신네 종족을 싫어하는 것은 아닙니다, $r. 그렇지만, 당신에게 내 와이번을 태워드릴 순 없군요.', `FemaleText_loc4`='并不是所有牛头人都藐视你们$r。不过，我无法向你提供服务。', `FemaleText_loc5`='並不是所有牛頭人都藐視你們$r。不過，我無法向你提供服務。', `FemaleText_loc7`='No todos los tauren desprecian a los de tu raza, $r. Lamentablemente, no se me permite ofrecerte mis servicios.' WHERE `ID`=10919;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주문을 끝내시오, 스태그헬름! 더 이상 수호의 문장을 유지할 수 없을 것 같소! 힘을 내시오!', `MaleText_loc4`='鹿盔，赶快完成施法！我没法让节界雕文继续维持原位了！召唤自然的力量！', `MaleText_loc5`='鹿盔，趕快完成施法!我沒法讓結界雕紋繼續維持原位了!召喚自然的力量!', `MaleText_loc7`='¡CONCLUYE EL HECHIZO, CORZOCELADA! ¡NO PUEDO CONTENER A LOS GLIFOS QUE PROTEGEN EL LUGAR POR MUCHO MÁS TIEMPO! ¡INVOCA A LAS RAÍCES!' WHERE `ID`=10920;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고대의 존재께서 나의 손을 인도하시니... 잠에서 깨어나라! 깨어나서 이 저주받은 곳을 봉인하라!', `MaleText_loc4`='远古的神灵，指引我……从沉睡中苏醒吧！醒来，封印这片被诅咒的地方！', `MaleText_loc5`='遠古的神靈，指引我...從沉睡中甦醒吧!醒來，封印這片被詛咒的地方!', `MaleText_loc7`='Ancestros, guíen mi mano... ¡Despierten de su sueño! ¡DESPIERTEN Y SELLEN ESTE LUGAR MALDITO!' WHERE `ID`=10921;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 탈진하여 한쪽 무릎을 털썩 꿇습니다.', `MaleText_loc4`='%s双腿一软，筋疲力尽地跪倒在地。', `MaleText_loc5`='%s雙腿一軟，筋疲力盡地跪倒在地。', `MaleText_loc7`='%s hinca exhausto una rodilla.' WHERE `ID`=10922;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어... 끝났군, 대드루이드 스태그헬름이여. 비록 엄청난 희생이 있었지만 우리의 승리요.', `MaleText_loc4`='鹿盔，结……结束了。我们胜利了。虽然我们为此付出了惨痛的代价。', `MaleText_loc5`='結...結束了，鹿盔大人。我們勝利了。雖然我們為此付出了慘痛的代價。', `MaleText_loc7`='Se... Se ha acabado, Lord Corzocelada. ¡Hemos vencido! Si bien el precio que hemos pagado por esta victoria ha sido alto.' WHERE `ID`=10923;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 아직 할 일이 한 가지 남았소...', `MaleText_loc4`='还有一件事要解决……', `MaleText_loc5`='還有一件事要解決...', `MaleText_loc7`='Tan solo queda una obligación que cumplir...' WHERE `ID`=10924;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스태그헬름, 이곳을 떠나기 전에 마지막으로 그대에게 줄 것이 하나 있소. 만약 그대가 이 저주받은 요새에 다시 들어와야 할 때가 오거든 흐르는 모래의 홀로 신성한 징을 울리시오. 그러면 보호막을 유지하고 있는 마력이 사라지고, 이 세계에 다시 한 번 안퀴라즈의 공포가 찾아올 것이오.', `MaleText_loc4`='在我离开之前，鹿盔，我还要再送一件东西给你。如果有一天，因为某些原因，你必须进入这座被诅咒的堡垒，就在神圣的铜锣上使用流沙节杖。屏障上的魔法将被驱散，而安其拉的恐怖气息也将再次传遍世界。', `MaleText_loc5`='在我離開之前，鹿盔大人，我還要再送一件東西給你。如果有一天，因為某些原因，你必須進入這座被詛咒的堡壘，就在神聖的銅鑼上使用流沙權杖。屏障上的魔法將被驅散，而安其拉的恐怖氣息也將再次傳遍世界。', `MaleText_loc7`='Antes de abandonar este lugar, te daré un último consejo, Lord Corzocelada. Si en algún momento tienes que entrar en esta fortaleza maldita, usa el cetro del Mar de Dunas para hacer sonar el gong sagrado. La magia que sustenta la barrera desaparecerá y los horrores de Ahn''Qiraj se cernirán de nuevo sobre el mundo.' WHERE `ID`=10925;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 흐르는 모래의 홀을 판드랄 스태그헬름에게 건넵니다.', `MaleText_loc4`='%s将流沙节杖交给了范达尔·鹿盔。', `MaleText_loc5`='%s將流沙權杖交給范達爾·鹿盔。', `MaleText_loc7`='%s pasa el cetro del Mar de Dunas a Fandral Corzocelada.' WHERE `ID`=10926;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용이여, 나의 백성들에게 이런 참혹함을 보고 겪게 한 후에도 내가 또다시 짐을 떠맡을 것이라고 기대했는가? 물론 그대는 미쳤으니까 그럴 수도 있겠지.', `MaleText_loc4`='在我的人民目睹并经历了那场暴行之后，你还指望我能挑起这个沉重的负担？很明显，你疯了。', `MaleText_loc5`='在我的人民目睹並經歷了那場暴行之後，你還指望我能挑起這個沉重的負擔?很明顯，你瘋了。', `MaleText_loc7`='Tras la violencia que mi pueblo ha presenciado y de la cual ha sido víctima, ¿esperas que acepte otra carga, dragón? Sin duda, estás loco.' WHERE `ID`=10927;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 실리더스나 퀴라지, 특히 빌어먹을 용들과는 더 이상 엮이고 싶지 않다!', `MaleText_loc4`='我不想再跟希利苏斯、其拉虫人和该死的龙类有任何关系了！', `MaleText_loc5`='我不想再跟希利蘇斯、其拉蟲人和該死的龍類有任何關係了!', `MaleText_loc7`='¡No quiero tener nada que ver con Silithus, los qiraji y, sobre todo, con ningún condenado dragón!' WHERE `ID`=10928;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 보호막으로 흐르는 모래의 홀을 집어던지자 박살 납니다.', `MaleText_loc4`='%s将流沙节杖扔向魔法屏障，节杖顿时碎裂开来。', `MaleText_loc5`='%s將流沙權杖揮向防護罩，將它粉碎。', `MaleText_loc7`='%s arroja el cetro del Mar de Dunas contra la barrera, haciéndolo añicos.' WHERE `ID`=10929;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 잠깐 시간의 흐름이 정지할 것이오! 지금부터 보호막을 소환할 것이니...', `MaleText_loc4`='时间之沙将停止流动，但只有片刻的时间！我现在要召唤屏障。', `MaleText_loc5`='時間之沙將停止流動，但只有片刻的時間!我現在要召喚屏障。', `MaleText_loc7`='Las tierras del tiempo se detendrán, ¡pero solo por un instante! Haré aparecer la barrera.' WHERE `ID`=10930;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대드루이드여, 어디로 가는 것이오? 자존심 때문에 우리의 관계를 저버릴 셈이오?', `MaleText_loc4`='鹿盔，你要去哪儿？为了自尊和高傲，你就要切断我们的联系？', `MaleText_loc5`='鹿盔大人，你要去哪裡?你會為了驕傲粉碎我們的約定嗎?', `MaleText_loc7`='Lord Corzocelada, ¿qué estás haciendo? ¿Destruirías nuestro vínculo por orgullo?' WHERE `ID`=10931;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 공허한 승리는 내 아들의 영혼에게 안식을 줄 수 없다, 용이여. 나는 내 아들을 되찾을 것이다. 수천 년이 걸린다 할지라도 꼭 되찾고 말 것이다!', `MaleText_loc4`='虚假的胜利无法告慰我儿子的灵魂。我会把他找回来的。尽管这或许需要数千年，但是我会把他找回的！', `MaleText_loc5`='虛假的勝利無法告慰我兒子的靈魂。我會把他找回來的。儘管這或許需要數千年，但是我會把他找回的!', `MaleText_loc7`='El alma de mi hijo no encontrará consuelo en esta victoria vacía, dragón. Lo recuperaré. Aunque me lleve siglos, ¡recuperaré a mi hijo!' WHERE `ID`=10932;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 실망하여 고개를 가로 젓습니다.', `MaleText_loc4`='%s失望地摇着头。', `MaleText_loc5`='%s失望地搖著頭。', `MaleText_loc7`='%s sacude la cabeza en un gesto de decepción.' WHERE `ID`=10933;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 무릎을 꿇고 부서진 홀 조각들을 줍습니다.', `MaleText_loc4`='%s蹲下身去捡起被摔碎的节杖碎片。', `MaleText_loc5`='%s跪下撿起破碎的權杖碎片。', `MaleText_loc7`='%s se arrodilla para recoger los fragmentos del cetro hecho añicos.' WHERE `ID`=10934;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 그대에게 해 줄 말은 다했소, 필멸의 존재여...', `MaleText_loc4`='凡人，现在你已经知道一切了……', `MaleText_loc5`='凡人，現在你已經知道一切了...', `MaleText_loc7`='Y ahora ya sabes todo lo que hay que saber, mortal...' WHERE `ID`=10935;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 들으시오, 친구. 안퀴라즈의 벌레들과 목숨을 건 한판승을 하려면 준비를 해야 하오. 그래서 난 여기에서 철 주괴를 모으고 있소이다. 현재 얼라이언스에서 보유하고 있는 철 주괴는 $2002w개인데, 우리가 계획한 전쟁 물자를 생산하려면 모두 $2003w개가 필요하오.', `MaleText_loc4`='听着，我们是在赌上性命跟安其拉的虫人战斗，因此需要做好充分的战斗准备。我在此地收集铁锭。目前，联盟只收集到$2002w块，而总的需求量是$2003w。', `MaleText_loc5`='聽好了，我們是為了我們的生活在安其拉與異種蟲類對抗，我們需要為作戰而準備。現在，聯盟只有$2002w個鐵錠，但我們計畫作戰共需要$2003w個。', `MaleText_loc7`='Escucha, membrillo, estamos aquí para la lucha más importante de nuestras vidas contra los bichos de Ahn''Qiraj y tenemos que prepararnos para ello. Estoy recogiendo barras de hierro aquí. Actualmente, la Alianza solo tiene $2002w barras de hierro pero se calcula que serán necesarias un total de $2003w para la campaña.' WHERE `ID`=10936;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 노력해 준 덕분에 필요한 철 주괴를 모두 모았소. 이제 다른 곳에 가서 전쟁에 필요한 물자를 수집해 줄 것이 없는지 알아보시오. 나는 좋아하는 카드 게임이나 즐기게 이곳을 조금이라도 일찍 벗어날 수 있는지 알아봐야겠소이다.', `MaleText_loc4`='在大家的努力下，我们已经集齐了必需的铁锭。问问其他人，看他们是否需要你帮忙收集作战物资。至于我，我得瞧瞧我能不能早点离开，去玩几局牌。', `MaleText_loc5`='謝謝大家的幫忙，我們現在已經有所需的鐵錠了。看看是否還有其他戰爭需要的東西要收集。至於我，我得瞧瞧我能不能早點離開，去玩幾局牌。', `MaleText_loc7`='Gracias al esfuerzo de todos, ahora ya disponemos de todas las barras de hierro que necesitamos. Pregunta a los demás si hay algo más ahí fuera que puedas recoger para la campaña. Yo, por mi parte, voy a ver si puedo salir de aquí un poco antes para jugar una partida a las cartas.' WHERE `ID`=10937;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$C|1이여;여;, 잘 들으세요. 지금 얼라이언스와 호드는 실리시드와 그들을 조종하는 무리와 싸울 안퀴라즈 전쟁을 준비하고 있어요. 도와주신다면 정말 감사하겠습니다. 보시다시피 저는 전쟁에 필요한 토륨 주괴를 모으고 있습니다. 모두 $2012w개가 필요한데 현재 보유하고 있는 것은 $2011w개입니다.', `FemaleText_loc4`='如果你能帮帮忙的话，那真是太感谢了。你看，我正在收集战争所需的瑟银锭。我们总共要收集$2012w块瑟银锭，但是我们有$2011w块。', `FemaleText_loc5`='$C，請聽好我接下來要說的話。聯盟和部落正為對抗安其拉之戰的異種蟲類及他們的主使者作準備。如果你能幫幫忙的話，那真是太感謝了。如你所看到的，我正在收集作戰所需的瑟銀錠。我們總共需要收集$2012w個瑟銀錠，而目前我們有$2011w個。', `FemaleText_loc7`='$C, por favor, escucha lo que tengo que decir. La Alianza y la Horda se están preparando para una guerra contra los silítidos y sus maestros en Ahn''Qiraj. Cualquier ayuda que puedas prestar será bien recibida. Como puedes comprobar, estoy reuniendo barras de torio para la campaña. Tenemos que reunir $2012w en total y actualmente contamos con $2011w.' WHERE `ID`=10938;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다시 저를 찾아주셔서 감사합니다. 우리는 필요한 토륨 주괴를 모두 모았습니다. 하지만 여기서 다른 물자를 수집하는 곳에 가서 도움이 필요하지 않은지 물어보는 것도 괜찮을 것 같군요.', `FemaleText_loc4`='谢谢你，$C。我们已经集齐了所需的瑟银锭了，但是你可以问问这儿收集其他作战物资的负责人。', `FemaleText_loc5`='謝謝你向我回報，$c。我們現在有了所有需要的瑟銀錠，但你可以問問看這裡的其他人有沒有需要收集其他的東西。', `FemaleText_loc7`='Gracias por preguntarme a mí, $c. Ahora mismo tenemos todas las barras de torio que vamos a necesitar pero quizás quieras preguntar a los que se encargan de diferentes campañas de recogida.' WHERE `ID`=10939;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장담하건대 곧 있을 안퀴라즈 전쟁에 필요한 물자를 만드는 데 갈래물풀만큼 유용한 것도 드물 겁니다! 뜨거운 실리더스의 태양이 내리쬐는 무더운 날에 아이스크림을 만들고, 일부 식물의 역겨운 냄새를 없애 주고, 물속에서 숨을 쉴 수 있게 해 주고, 피부를 단단하게 해 주고, 동작을 민첩하게 해 주고, 마력을 보충해 주는 등등... 용도가 하도 많아 일일이 기억하기도 힘들어요! 제가 아이스크림도 만들 수 있다고 말했나요?$B$B어쨌든 제가 모은 것은 대략 $2047w개인데 필요한 것은 모두 $2048w개입니다!', `MaleText_loc4`='真的，就连荆棘藻也会成为战争中的重要资源！它有许多用途，比如用来制作可以在希利苏斯的炎炎烈日下品尝的冰淇淋，清除一些非常难以清除的植物，水下呼吸，硬化皮肤，让你的行动变得更迅速，恢复魔法能量，太多了，我简直没法一一历数！我有没有说冰淇淋？$B$B总之，我手头上总共有$2047w份的存货，而需求总量是$2048w！', `MaleText_loc5`='是真的，就連荊棘藻也會成為戰爭中的重要資源!它有很多用途，像是在希利蘇斯的豔陽下製作冰淇淋，清除一些非常難以清除的植物，水下呼吸，強化皮膚，迅速移動，恢復魔法能量;還有很多我想不起來的用途!我有提到可以做冰淇淋嗎?$B$B總之，我手頭上總共有$2047w份的存貨，而需求總量是$2048w份!', `MaleText_loc7`='Es cierto, ¡incluso el alga estranguladora puede resultar bastante útil para reunir las fuerzas necesarias para la inminente guerra en Ahn''Qiraj! Tiene muchas aplicaciones: para hacer helados para los calurosos días bajo el sol de Silithus, como ungüento para aliviar los efectos de algunas plantas que pican, para poder respirar bajo el agua, para curtir la piel, obtener velocidad, recuperar el poder mágico... ¡Para muchas cosas que no puedo recordar! ¿Ya dije que se puede usar para hacer helados?$B$BSin embargo, tengo alrededor de $2047w aquí ¡y necesito un total de $2048w!' WHERE `ID`=10940;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혼자 평생 먹고 남을 아이스크림을 만들 수 있을 만큼 많은 갈래물풀을 모을 능력이 있는 분이로군요. 그런데 어쩌죠... 우리는 필요한 갈래물풀을 충분히 모은 것 같은데... 어쨌든 그렇다고 얘기를 들었어요. 하지만 여기서 다른 물자를 모으고 있는 이들 중 도움을 필요로 하는 이가 있을 거예요. 그래도 갈래물풀을 모으는 것만큼 재미있는 일은 없다는 걸 알게 되실 겁니다요.', `MaleText_loc4`='我不是置疑你收集荆棘藻的能力，但是我们似乎已经拥有足够的荆棘藻了。至少我是这么听说的。这儿的其他人需要你帮忙收集战争物资。收集其他的作战物资可没有收集荆棘藻那么有趣，我能理解你这种想法。', `MaleText_loc5`='我不確定你在無數年以後，是否能擁有足夠的荊棘藻，所有做冰淇淋需要的東西似乎已經夠了。至少我是這樣聽說的。看來似乎這裡的其他人需要幫忙收集東西。等你了解就會知道他們收集的東西可不像荊棘藻那麼有趣。', `MaleText_loc7`='No es que en tropecientosmil años no pudieras conseguir suficientes algas estranguladoras, con las que se podría hacer todo el helado del mundo, pero parece que tenemos suficientes. O eso es lo que me han dicho, de todos modos. Parece que algunos necesitan ayuda para recoger lo que sea que tengan que recoger. Es comprensible si tenemos en cuenta que sea lo que sea, seguro que no es tan divertido como recoger algas estranguladoras.' WHERE `ID`=10941;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='젊은 $c|1이여;여;, 얼라이언스 연합에서 내게 안퀴라즈에서 실리시드와 벌어질 전쟁에 대비하기 위해 보라 연꽃을 모아 달라고 부탁했답니다. 보라 연꽃은 쓸모가 많고 해서 전 거기에 동의했죠. 보라 연꽃은 총 $2055w개를 모아야 하는데 현재 $2053w개를 모은 상태입니다.', `MaleText_loc4`='紫莲花的用处很多，年轻的$C。联盟派我收集这种花，为安其拉之战做好准备。我答应帮助他们收集$2055w份紫莲花，目前我们已经收集到了$2053w份。', `MaleText_loc5`='你好，年輕的$c。在準備對抗安其拉異種蟲類之戰，聯盟要求我帶領他們收集紫蓮花。我知道這些花有很多用途。而且，我答應幫他們收集$2055w份紫蓮花，而目前我們已收集了$2053w份。', `MaleText_loc7`='Saludos, joven $c. En vista de la guerra en Ahn''Qiraj contra los silítidos, la Alianza me ha pedido que dirija los trabajos de recolecta de lotos cárdenos. Esta flor tiene muchas aplicaciones de las que soy consciente y, por lo tanto, he aceptado ayudarlos a conseguir $2055w. Hasta la fecha hemos recogido $2053w.' WHERE `ID`=10942;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필요한 보라 연꽃을 모두 모았다는 소식을 전하게 되어 기쁘군요. 도와주셔서 감사합니다. 더 도울 마음이 있다면 이곳에는 아직 전쟁에 필요한 다른 자원들을 수집하고 있는 곳이 많다는 말씀을 드리고 싶군요.', `MaleText_loc4`='我们已经集齐了所需的紫莲花，我很满意。谢谢你的帮助，$C。如果你愿意的话，这儿还有很多人还在为收集作战物资而焦头烂额呢，你可以帮帮他们。', `MaleText_loc5`='我很高興的告訴你，我們已經收集到全部所需的紫蓮花了。謝謝你對我們的貢獻，$c。如果你願意，我們這裡還有幾樣為了奮戰而需要收集的東西。', `MaleText_loc7`='Me complace informarte de que hemos reunido todos los lotos cárdenos que consideramos que necesitamos. Gracias por tu contribución, $c. Si así lo deseas, seguro que algunos que aún están aquí todavía están recogiendo otras cosas para la lucha.' WHERE `ID`=10943;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지금 우리는 전쟁을 준비하고 있습니다. 안퀴라즈에서 실리시드와 그들을 조종하는 놈들과 싸우려면 전력을 다해 모든 종류의 전쟁 물자를 수집해야 합니다. 전 아서스의 눈물을 모으고 있는데 정확히 어디에 사용할 건지는 잘 모릅니다. 저한테 물어볼 생각이었다면 포기하는 게 좋을 겁니다. 아서스의 눈물이 단지 아서스 님의 이름을 딴 꽃에 불과하다고 해도 그 미치광이와 관련된 것은 눈곱만큼도 알고 싶지 않으니까요.$B$B저는 여전히 제 아버지의 딸이자 일개 병사이기 때문에 명령에 복종할 의무가 있습니다. 지금까지 아서스의 눈물 $2057w개를 모았는데 모두 $2058w개를 모아야 합니다.', `FemaleText_loc4`='我们正在为战争作准备，$c。我们一定要彻底消灭安其拉的威胁，为了战备的需要，我在这里收集阿尔萨斯之泪这种材料。我不清楚这些草药是用来做什么的。如果你问我的话，我可不想跟那个疯子扯上关系，即使这不过是一种以他命名的花而已。不过，我不仅是个联盟的公民，还是一名军人，因此我会遵守上级的命令。现在我们已经收集到$2057w份阿尔萨斯之泪了，总的需求量是$2058w份。', `FemaleText_loc5`='我們正為戰爭作準備，$c。我們將前往安其拉與異種蟲類及它們的主使者作戰。所有收集物資的準備工作都已完成了。我的任務是收集阿薩斯之淚。我不確定我們要這些阿薩斯之淚做什麼。如果你問我，我不想再和那個瘋子有瓜葛，即使只是一朵以他命名的花。$B$B我仍然是我爸爸的女兒，也是一名戰士，所以我會奉命行事。我們目前有$2057w份阿薩斯之淚，而我們總共需要收集$2058w份。', `FemaleText_loc7`='Nos estamos preparando para la guerra, $c. Ya hemos cogido todo lo necesario de los silítidos y sus maestros en Ahn''Qiraj. Para estar preparados estamos reuniendo todo tipo de material. Yo soy la encargada de reunir lágrimas de Arthas, aunque no sé para qué las necesitamos. Por si te interesa, no quiero tener nada que ver con ese loco, aunque solo se trate de una flor que lleva su nombre.$B$BAun así, soy hija de mi padre, y una Soldado, así que hago lo que me ordenan. Actualmente tenemos $2057w y tenemos que recoger un total de $2058w.' WHERE `ID`=10944;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='음, 이제 다 된 것 같군요. 필요한 아서스의 눈물을 모두 모았습니다. 주위에 도움이 필요한 곳은 없는지 알아보세요. 어딘가 전쟁 물자 수집에 도움을 바라는 이가 분명히 있을 테니까요.', `FemaleText_loc4`='我想是这样的。我们已经收集到足够的阿尔萨斯之泪了。你可以四下问问。肯定还有人在收集其它作战物资。', `FemaleText_loc5`='我想就這樣了。我們已經收集足夠的阿薩斯之淚。你可以四處問問。一定還有人需要收集戰爭所需的東西。', `FemaleText_loc7`='Creo que se acabó. Tenemos todas las lágrimas de Arthas necesarias. Deberías preguntar por ahí. Seguro que alguien necesita recoger algo para la campaña.' WHERE `ID`=10945;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 지금까지 심연의 의회를 상대로 벌인 영웅적인 업적은 보고를 통해 이미 알고 있습니다... 정말 위대한 일을 했더군요!$B$B그렇게 꾸준히 나아가도록 하십시오. 우린 그 노고를 절대 모른 척하지 않을 것입니다.', `MaleText_loc4`='我得到报告说，你对深渊议会的战果卓著，$n。你干得很好！$B$B继续保持斗志，我们会奖励你的！', `MaleText_loc5`='我得到報告說，你對深淵議會的戰果卓著，$n。你幹得很好!$B$B繼續保持鬥志，我們會獎勵你的!', `MaleText_loc7`='Me llegan continuamente noticias de tus proezas contra el Consejo Abisal, $n. ¡Estás haciendo grandes cosas ahí fuera!$B$B¡Sigue así y conseguiremos que el esfuerzo valga la pena!' WHERE `ID`=10946;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$c|1이여;여;, 얼라이언스에서 우리 가족들에게 머지않아 발발할 안퀴라즈 전쟁에 필요한 얇은 가죽을 모아달라고 부탁했답니다. 지금까지 모두 $2061w개가 필요한데 지금까지 $2060w개가 모였습니다. 당신은 남을 잘 도와줄 $r|1으로;로; 보이는군요.', `FemaleText_loc4`='联盟让我的家族在这儿收集大量的轻皮以供作战准备。我们已经收集到$2060w张轻皮了，而总的需求量是$2061w张。或许你愿意帮帮我们。', `FemaleText_loc5`='安其拉之戰已經展開，$c，聯盟要求我的家人為戰爭收集許多輕皮。總共需要$2061w塊，我們目前有$2060w塊。你看起來很適合幫忙。', `FemaleText_loc7`='$C, la guerra de Ahn''Qiraj está cerca y la Alianza ha pedido a mi familia que reúna una gran cantidad de pieles de cuero ligero para la campaña. De las $2061w necesarias, disponemos actualmente de $2060w. Tienes pinta de poder echarnos una mano.' WHERE `ID`=10947;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 중립 지대에서 피를 보려는 자가 누구입니까? 썩 나가십시오! 당장!', `MaleText_loc4`='你胆敢在中立领地动手？！出去！', `MaleText_loc5`='你竟敢在中立的土地上濺灑鮮血?滾!我說，滾!', `MaleText_loc7`='¿Osas derramar sangre en suelo neutral? ¡FUERA! ¡HE DICHO FUERA!', `FemaleText_loc1`='감히 중립 지대에서 피를 보려는 자가 누구입니까? 썩 나가십시오! 당장!', `FemaleText_loc4`='你胆敢在中立领地动手？！出去！', `FemaleText_loc5`='你竟敢在中立的土地上濺灑鮮血?滾!我說，滾!', `FemaleText_loc7`='¿Osas derramar sangre en suelo neutral? ¡FUERA! ¡HE DICHO FUERA!' WHERE `ID`=10948;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$r|1이여;여;, 우린 이교도를 환영하지 않습니다.', `MaleText_loc4`='我们不会对犯错者手软，$r。', `MaleText_loc5`='我們不會給惡棍好臉色看的，$r。', `MaleText_loc7`='Los bellacos no son bien recibidos, $r.', `FemaleText_loc1`='$r|1이여;여;, 우린 이교도를 환영하지 않습니다.', `FemaleText_loc4`='我们不会对犯错者手软，$r。', `FemaleText_loc5`='我們不會給惡棍好臉色看的，$r。', `FemaleText_loc7`='Los bellacos no son bien recibidos, $r.' WHERE `ID`=10949;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼날 맛 좀 봐라!', `MaleText_loc4`='看招，混帐！', `MaleText_loc5`='嘗嘗劍的滋味吧，死雜種!', `MaleText_loc7`='¡Siente el acero, chucho!', `FemaleText_loc1`='칼날 맛 좀 봐라!', `FemaleText_loc4`='看招，混帐！', `FemaleText_loc5`='嘗嘗劍的滋味吧，死雜種!', `FemaleText_loc7`='¡Siente el acero, chucho!' WHERE `ID`=10950;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제발 그 일만은 저지르지 않았다고 말해주세요! 그렇지 않다면 전 당신을 해칠 수밖에 없습니다.', `MaleText_loc4`='请告诉我你没有做那件我认为你刚刚做了的事情。请告诉我……我不必对你动手……', `MaleText_loc5`='請告訴我你沒有做那些我所想的事情。請告訴我，我不需要傷害你...', `MaleText_loc7`='Por favor, dime que no hiciste lo que creo que hiciste. Por favor, dime que no voy a tener que hacerte daño...', `FemaleText_loc1`='제발 그 일만은 저지르지 않았다고 말해주세요! 그렇지 않다면 전 당신을 해칠 수밖에 없습니다.', `FemaleText_loc4`='请告诉我你没有做那件我认为你刚刚做了的事情。请告诉我……我不必对你动手……', `FemaleText_loc5`='請告訴我你沒有做那些我所想的事情。請告訴我，我不需要傷害你...', `FemaleText_loc7`='Por favor, dime que no hiciste lo que creo que hiciste. Por favor, dime que no voy a tener que hacerte daño...' WHERE `ID`=10951;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 밧줄을 가져와라!', `MaleText_loc4`='去找根绳子！', `MaleText_loc5`='拿繩子!', `MaleText_loc7`='¡Coge una cuerda!', `FemaleText_loc1`='여기 밧줄을 가져와라!', `FemaleText_loc4`='去找根绳子！', `FemaleText_loc5`='拿繩子!', `FemaleText_loc7`='¡Coge una cuerda!' WHERE `ID`=10952;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가만히 있지 말고 가서 놀 거리를 많이 만들어 주도록!', `MaleText_loc4`='难道我们的麻烦还不够多吗？你还要火上浇油？！', `MaleText_loc5`='好像我們麻煩還不夠多似的，你又跑去惹事生非!', `MaleText_loc7`='Como si no tuviéramos bastantes problemas, ¡vas tú y creas más!', `FemaleText_loc1`='가만히 있지 말고 가서 놀 거리를 많이 만들어 주도록!', `FemaleText_loc4`='难道我们的麻烦还不够多吗？你还要火上浇油？！', `FemaleText_loc5`='好像我們麻煩還不夠多似的，你又跑去惹事生非!', `FemaleText_loc7`='Como si no tuviéramos bastantes problemas, ¡vas tú y creas más!' WHERE `ID`=10953;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겁쟁이 양반, 잘 들으십시오! 조금 있으면 당신은 이럴 바엔 차라리 태어나지도 말 걸 그랬어... 하며 울게 될 겁니다!', `MaleText_loc4`='说真的，你等一下就会情愿自己根本没生出来，混蛋！', `MaleText_loc5`='相信我和你說的這些話:你將會後悔出生在這個世界上，娘娘腔!', `MaleText_loc7`='Créeme cuando te digo lo siguiente: ¡Desearás no haber nacido!', `FemaleText_loc1`='겁쟁이 양반, 잘 들으십시오! 조금 있으면 당신은 이럴 바엔 차라리 태어나지도 말 걸 그랬어... 하며 울게 될 겁니다!', `FemaleText_loc4`='说真的，你等一下就会情愿自己根本没生出来，混蛋！', `FemaleText_loc5`='相信我和你說的這些話:你將會後悔出生在這個世界上，娘娘腔!', `FemaleText_loc7`='Créeme cuando te digo lo siguiente: ¡Desearás no haber nacido!' WHERE `ID`=10954;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c... 당신은 우리 모두에게 수치와 모욕을 가져왔습니다! 이렇게 당신을 해쳐야만 하는 제 마음도 시퍼렇게 멍들고 있어요.', `MaleText_loc4`='你的行为让我们蒙羞，$c。我感到深深的耻辱，所以你死定了。', `MaleText_loc5`='你的行為讓我們所有人蒙羞，$c。打在你身，痛在我心。', `MaleText_loc7`='Tus acciones nos avergüenzan a todos, $c. Sufro mientras te pego sin sentido.', `FemaleText_loc1`='$c... 당신은 우리 모두에게 수치와 모욕을 가져왔습니다! 이렇게 당신을 해쳐야만 하는 제 마음도 시퍼렇게 멍들고 있어요.', `FemaleText_loc4`='你的行为让我们蒙羞，$c。我感到深深的耻辱，所以你死定了。', `FemaleText_loc5`='你的行為讓我們所有人蒙羞，$c。打在你身，痛在我心。', `FemaleText_loc7`='Tus acciones nos avergüenzan a todos, $c. ¡Me causa dolor pegarte sin sentido!' WHERE `ID`=10955;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오, 내 일이 어떻게 되어가는지 물어보러 다시 오시다니 고맙군요. 하지만 이미 필요한 얇은 가죽을 모두 모았답니다. 근처에 다른 물자를 모으는 이들 중에 당신의 도움이 필요한 이가 있지 않을까요?', `FemaleText_loc4`='谢谢你的关心，$C。但是我们已经集齐轻皮了。或许这儿负责收集物资的其他人需要你的帮助。', `FemaleText_loc5`='謝謝你的關心，$c，但我們已經有足夠的輕皮了。或許這邊收集其他東西的人會需要你的協助。', `FemaleText_loc7`='Gracias por preguntar, $c, pero ya tenemos todas las pieles de cuero ligero que necesitamos. Sin embargo, puede que alguno de los otros encargados de la recogida necesite ayuda.' WHERE `ID`=10956;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 그렇습니다! 병사 포터가 보고 드립니다. 일반 가죽 모으는 일을 도와드리겠습니다. 우리는 다가올 안퀴라즈 전쟁에 대비하여 만반의 준비를 해야합니다.$B$B보시다시피 정확하게 $2063w개의 일반 가죽을 모았고 제가 맡은 임무는 모두 $2064w개를 모으는 것입니다.', `MaleText_loc4`='长官！列兵波特向您报告，随时准备帮助您收集中皮。安其拉之战迫在眉睫，我们需要做好充分的准备。$B$B我们已经收集到$2063w块中皮了，总的需求量是$2064w块。', `MaleText_loc5`='$G先生:女士;，是的$g先生:女士;!士兵波特已準備好要幫你收集中皮了。安其拉之戰就要展開，我們需要做好充分的準備。$B$B如你所見我們已收集了$2063w塊中皮，而我們總共需要收集$2064w塊。', `MaleText_loc7`='¡$GSeñor: Señora;, sí $gseñor: señora;! Soldado Porter se presenta y está listo para ayudarle a reunir pieles de cuero medio. La guerra de Ahn''Qiraj está cerca y debemos que estar lo mejor preparados posible.$B$BComo puedes comprobar, hemos recogido exactamente $2063w pieles de cuero medio y a mí me encomendaron reunir un total de $2064w.' WHERE `ID`=10957;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 네, 그렇습니다. 얼라이언스 연합에서 전쟁을 수행하는 데 필요한 일반 가죽을 모두 모은 것 같습니다. 다른 물자를 모으는 곳에서 당신의 도움을 필요로 할지 모른다는 말을 드리고 싶군요.', `MaleText_loc4`='啊，呃，是的，$G先生:女士;。我们已经集齐联盟在战争中所需的所有中皮了。我听说这儿的其他人需要你的帮助。', `MaleText_loc5`='啊，嗯，是的$g先生:女士;。我們已經收集完聯盟在戰爭中所需的所有中皮了。我聽說這還有其他人需要你的協助來收集東西。', `MaleText_loc7`='¡Ah, um, sí $gseñor: señora;! Parece ser que hemos recogido todas las pieles de cuero medio que la Alianza considera necesarias para la guerra. Sin embargo, me han dicho que puede haber alguien aquí que necesite tu ayuda para los trabajos de recogida de material.' WHERE `ID`=10958;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, $c님! 안퀴라즈 전쟁이 임박했어요. 그에 따라 이곳의 수집도 박차를 가하고 있습니다. 전 두꺼운 가죽 수집을 책임지고 있지요. 두꺼운 가죽 모으기에 정말 좋은 날씨로군요, 그렇지 않나요? 여기 이게 지금까지 모은 가죽인데 $2069w개입니다. $2071w개를 모으는 것이 목표인데, 도와주시겠어요?', `FemaleText_loc4`='嗨，$C！今天真是个收集厚皮的好日子，不是吗？我收集到一堆厚皮了，似乎已经有$2069w块啦。需求量是$2071w块。你想要帮帮我们吗？', `FemaleText_loc5`='你好，$c!隨著安其拉之戰的逼近，我們的準備工作仍在進行著。我的工作是收集重皮。今天是個收集重皮的好日子，對吧?我收集到一堆厚皮了，看來現在已經有$2069w塊。而我們的理想數字是$2071w塊。要不要幫忙啊?', `FemaleText_loc7`='¡Hola, $c! Con la guerra de Ahn''Qiraj acechando, estamos acelerando los preparativos. Yo soy la encargada de reunir pieles de cuero grueso. Es un día estupendo para recoger pieles de cuero grueso, ¿no crees? Este es mi montón y parece que ahora mismo tengo $2069w. Nuestro número mágico es $2071w. ¿Quieres echar una mano?' WHERE `ID`=10959;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='야호! 얼라이언스 연합에서 필요로 하는 두꺼운 가죽을 모두 모은 것 같네요. 정말 빨리도 모았군요. 이 주변에 당신의 도움이 필요한 이들이 있을 겁니다. 물론 본인이 도와줄 마음이 있어야겠지만요.', `FemaleText_loc4`='哇！似乎我们已经集齐厚皮了。速度很快呢。你可以问问这儿的其他人，看他们是否需要帮助。', `FemaleText_loc5`='哇!看來我們已經收集完所有的重皮了。速度真快。但如果你願意的話，這裡可能還有其他人需要你的幫忙。', `FemaleText_loc7`='¡Vaya! Parece que ya hemos reunido todas las pieles de cuero grueso que creen que necesitamos. Sin duda fue rápido. ¿Sabes? Seguro que hay otros por aquí que se podrían servir de tu ayuda, eso sí, si quisieras echarles un cable.' WHERE `ID`=10960;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공격 개시!', `MaleText_loc4`='开火！', `MaleText_loc5`='開火!', `MaleText_loc7`='¡Fuego!' WHERE `ID`=10961;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$c|1이여;여;, 안녕하세요! 저는 안퀴라즈 전쟁에서 사용할 리넨 붕대를 모으고 있습니다. 수집 일이 고되긴 하지만, 다가올 전쟁에 대비하여 우리의 단결력을 강하게 해주죠. 하지만 분명한 건, 당신께서 기부하실 모든 붕대는 때가 되면 우리 병사들의 소중한 생명을 구하는데 사용될 거란 사실입니다. $2077w개를 모아야 하는데 지금까지 $2076w개 밖에 구하지 못했답니다. 우릴 도와주시겠습니까?', `FemaleText_loc4`='你好，$C。我正在为安其拉之战收集亚麻绷带。这场战争对我们来说是一次严酷的考验和锻炼，你捐献的绷带将在战争中挽救士兵们的生命。我需要收集$2077w根亚麻绷带，到目前为止已经有$2076w根了。你愿意帮助我们吗？', `FemaleText_loc5`='嗨，$c。我在收集安其拉之戰所需的亞麻繃帶;這場戰爭對我們來說是一次嚴酷的考驗和鍛鍊，你捐獻的繃帶將在戰爭中挽救士兵們的生命。我需要$2077w個亞麻繃帶，而截至目前為止已有$2076w個。你會協助我們嗎?', `FemaleText_loc7`='Hola, $c, estoy recogiendo vendas de lino para la campaña de Ahn''Qiraj; una campaña que nos pondrá a todos a prueba pero que nos hará más fuertes para la guerra que se aproxima. Puedo asegurarte que todas las vendas que decidas donar serán bien empleadas para salvar la vida de nuestros soldados cuando llegue el momento. Necesito $2077w y hasta ahora he conseguido recoger $2076w. ¿Nos ayudarás?' WHERE `ID`=10962;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='친절하신 $c님, 다시 물어봐 주시다니 감사합니다. 보시다시피 이미 안퀴라즈 전쟁에서 얼라이언스 연합에 필요할 것으로 예상되는 리넨 붕대를 모두 모았습니다. 그래도 이곳에서 다른 물자를 모으는 이들을 계속 도와주시기 바랍니다.', `FemaleText_loc4`='谢谢你，$C。但是我们已经集齐联盟在安其拉一战中所需的亚麻绷带了。你可以帮帮其他人收集战争物资。', `FemaleText_loc5`='謝謝你的幫忙，$c，但你也看到了，我們已收集完畢聯盟在安其拉之戰所需的亞麻繃帶。但請別停止幫忙其他人的收集工作。', `FemaleText_loc7`='Gracias por preguntar $c, pero como puedes ver, ya tengo todas las vendas de lino que la Alianza necesitaba en vista de la guerra de Ahn''Qiraj. Aun así, que esto no te impida ayudar en la recolección de otros objetos aquí.' WHERE `ID`=10963;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='중요한 일이 아니라면 돌아가게!', `MaleText_loc4`='你的事情最好是非常重要的那种！', `MaleText_loc5`='你的事情最好是非常重要的那種!', `MaleText_loc7`='¡Ya puede ser importante!' WHERE `ID`=10964;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래! 곧 참혹한 일이 벌어질 걸세.', `MaleText_loc4`='伙计们！情势开始变得相当险恶。', `MaleText_loc5`='嘿，小夥子!情勢開始變得相當險惡。', `MaleText_loc7`='¡Eh, Soldados! Esto se va a poner bastante feo.' WHERE `ID`=10967;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='슬슬 때가 된 것 같은데...', `MaleText_loc4`='似乎昨日就要重现。', `MaleText_loc5`='似乎昨日就要重現。', `MaleText_loc7`='Parece que va a ser uno de esos días.' WHERE `ID`=10968;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좀 더 큰 검으로 골랐어야 하는 건데...', `MaleText_loc4`='我应该抢一柄大一些的剑。', `MaleText_loc5`='我應該拿把更大的劍。', `MaleText_loc7`='Debería usar una espada más grande.' WHERE `ID`=10969;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보병 부대, 정렬!', `MaleText_loc4`='步兵，排成一行！', `MaleText_loc5`='步兵，排成一列!', `MaleText_loc7`='¡Lacayos, formad una fila!' WHERE `ID`=10970;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='깊은 슬픔이 뿜어져 나옵니다.', `MaleText_loc4`='这块水晶中散发出巨大的悲伤。', `MaleText_loc5`='這水晶發散出強大的哀傷情緒。', `MaleText_loc7`='De este cristal se desprende una gran tristeza.' WHERE `ID`=10971;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='눈물의 결정을 물끄러미 바라봅니다.', `MaleText_loc4`='<凝视着水晶之泪。>', `MaleText_loc5`='<凝視著結晶之淚。>', `MaleText_loc7`='<Mira la lágrima cristalina.>', `FemaleText_loc1`='눈물의 결정을 물끄러미 바라봅니다.', `FemaleText_loc4`='<凝视着水晶之泪。>', `FemaleText_loc5`='<凝視著結晶之淚。>', `FemaleText_loc7`='<Mira la lágrima cristalina.>' WHERE `ID`=10972;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곤충 집에서 뭔가 거대한 것이 나오고 있습니다. 곧장 우리를 향해 날아오고 있습니다.', `MaleText_loc4`='长官，一个庞然大物从虫巢中钻出来，直接冲我们来了。', `MaleText_loc5`='長官，一個龐然大物從蟲巢中鑽出來，直接衝向我們了。', `MaleText_loc7`='Algo grande se aproxima desde la colmena, señora. Se dirige directo a nosotros.' WHERE `ID`=10973;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='병사, 즉시 블랙앤빌 연대장님을 호출하라!', `FemaleText_loc4`='士兵，立即呼叫布莱卡维尔上尉！', `FemaleText_loc5`='士兵，立即呼叫布萊卡維爾上尉!', `FemaleText_loc7`='¡Soldado, llama al capitán Yunquenegro de inmediato!' WHERE `ID`=10974;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 알겠습니다!', `MaleText_loc4`='是，长官！', `MaleText_loc5`='是，長官!', `MaleText_loc7`='¡Sí, señora!' WHERE `ID`=10975;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연대장님! 스타우트해머 부관이 찾고 있습니다! 적이 접근해 오고 있습니다!', `MaleText_loc4`='上尉！中尉要您过去！敌人正在接近我们，长官！', `MaleText_loc5`='上尉!頑錘中尉要您過去!敵人正在接近我們，長官!', `MaleText_loc7`='¡Capitán! ¡El teniente Martillotenaz requiere su presencia! ¡El enemigo se aproxima, señor!' WHERE `ID`=10976;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, 오늘 기분이 어떠세요? 모쪼록 여기 일에 관심이 있으셨으면 좋겠네요. 이곳에서는 현재 안퀴라즈 전쟁에 대비해 계획을 짜고 준비하는 중이에요. 우리와 호드는 만반의 태세를 갖추기 위해 최선을 다하는 중이죠.$B$B얼라이언스는 제게 이곳에서 비단 붕대 모으는 일을 감독해 달라고 했죠. 지금까지 우리는 $2082w개의 비단 붕대를 모았는데 $2083w개가 필요해요. 어때요, 도와주시겠어요?', `FemaleText_loc4`='你好，$C，你今天感觉怎么样？希望你一切都好。联盟派我来监督收集丝质绷带的工作；到目前为止，我们已经设法收集到$2082w根丝质绷带，而需求量是$2083w根。你想要帮助我们吗？', `FemaleText_loc5`='嗨，$c，你今天好嗎?希望一切都好。你應該知道這裡發生什麼事了。安其拉之戰正在計畫、準備中。我們和部落正加強準備。$B$B最後，聯盟要求我在這裡監督收集絲質繃帶，而目前我們只收集到$2082w個，但總需求是$2083w個。你可以考慮幫個忙嗎?', `FemaleText_loc7`='Hola, ¿cómo te sientes hoy, $c? Espero que bien. Te debes de estar preguntando qué está pasando aquí. Se está planeando y preparando una guerra en Ahn''Qiraj. Nosotros y la Horda nos estamos preparando lo mejor que podemos.$B$BPara ello, la Alianza me ha pedido que supervise la recogida de vendas de seda en este lugar. Hasta la fecha, hemos conseguido reunir $2082w de las $2083w que son necesarias. ¿Estás pensando en echar una mano?' WHERE `ID`=10977;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='매우 친절한 분이시군요. 그런데 우리에게 필요한 비단 붕대는 모두 모은 것 같군요. 이 근처에서 다른 물자를 수집하는 곳에 도움이 필요한지를 알아보시는 것도 괜찮을 것 같습니다.', `FemaleText_loc4`='谢谢你的关心，但是我们已经集齐丝质绷带了。你可以四下问问，看看他们是否需要帮助。', `FemaleText_loc5`='謝謝你的關心，不過我們已經收集到足夠的絲質繃帶了。你可以四處問問，看看有沒有其他人需要幫忙收集東西。', `FemaleText_loc7`='Gracias por preguntar, pero parece que ya hemos reunido todas las vendas de seda que necesitaremos. Sin embargo, podrías preguntar por ahí si alguien más necesita ayuda con la recogida de objetos.' WHERE `ID`=10978;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 막강한 전사들과 정찰병들이 아무리 뛰어나다 해도 곧 있을 안퀴라즈 전쟁에서 부상을 전혀 입지 않을 수는 없소이다. 그리고 마법으로 치료할 상황이 안 된다면 우리가 여기서 만들고 있는 붕대에 전적으로 의존할 수밖에 없는 것이오.$B$B지금까지 $2088w개의 룬무늬 붕대를 모았는데 모두 $2090w개가 필요합니다. 원한다면 어느 정도 도와주실 수 있는지 말해주시기 바라오.', `MaleText_loc4`='$C，在即将来临的战争中，即使最勇敢的士兵也需要治疗。当无法运用魔法治疗时，士兵们必须依赖于我们收集的战争物资了。到目前为止，我已经收集了$2088w根符文布绷带，总需求量是$2090w根。$B$B让我们谈谈你能我们做什么吧。', `MaleText_loc5`='$C，在即將來臨的戰爭中，即使最勇敢的士兵也需要治療。當無法運用魔法治療時，士兵們必須依賴我們收集的作戰物資。到目前為止，我已經收集了$2088w個符文布繃帶，總需求量是$2090w個。$B$B讓我們談談你能為我們做些什麼吧。', `MaleText_loc7`='$C, incluso nuestros guerreros y exploradores más fuertes tendrán que utilizar las artes curativas en la guerra que se avecina en Ahn''Qiraj. Y cuando no haya ninguna curación mágica disponible, tendrán que confiar en nuestros esfuerzos aquí.$B$BHasta la fecha, he reunido $2088w vendas de paño rúnico de las $2090w que son necesarias. Si estás dispuestos, deberíamos hablar detenidamente de cómo puedes hacer tu parte.' WHERE `ID`=10979;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='많은 얼라이언스의 동지들이 도와주신 덕분에 다가오는 안퀴라즈 전쟁에서 연합에 필요한 룬무늬 붕대를 가까스로 모을 수 있었습니다. 내가 그대라면 이곳에서 다른 물자를 모으고 있는 이들 중 도움이 필요한 이는 없는지 알아보겠소이다.', `MaleText_loc4`='$C，在许多人的帮助下，我们已经设法集齐了联盟所需的战争物资符文布绷带。如果我是你的话，我会问问这儿的其他人，看他们是否需要帮助。', `MaleText_loc5`='$C，在許多人的幫助下，我們已經設法收集完畢聯盟所需的作戰物資符文布繃帶了。如果我是你，我會問問其他人是否還需要收集其他東西。', `MaleText_loc7`='$C, gracias al esfuerzo conjunto hemos conseguido reunir todas las vendas de paño rúnico que la Alianza considera que necesita para el inminente conflicto. Si yo fuera tú, preguntaría a los demás si todavía tienen tareas de recogida por completar.' WHERE `ID`=10980;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런, $n! 너무 바빠서 얘기를 나눌 시간도 없군요. 말씀드린 것처럼 곧 닥칠 상황에 대해 생각할 시간이 필요합니다.$B$B그대의 여정에 행운이 함께하기를 바랍니다. 좋은 하루 되십시오.', `MaleText_loc4`='唉，$n，我太忙了，没时间来闲聊。就像我提到过的那样，我需要时间来考虑当前的处境。$B$B祝你的旅途好运，祝你度过愉快的一天。', `MaleText_loc5`='哎呀$n，我現在太忙沒辦法說話。就如我先前說的，我需要時間思考目前的狀況。$B$B祝你一路順風，有個愉快的一天。', `MaleText_loc7`='Desgraciadamente, $n, estoy demasiado ocupado para hablar. Como mencioné, necesito tiempo para pensar acerca de la situación que tenemos entre manos.$B$BTe deseo suerte en tus viajes. Que tengas un buen día.' WHERE `ID`=10981;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비하라!', `MaleText_loc4`='准备就绪！', `MaleText_loc5`='準備就緒!', `MaleText_loc7`='¡Preparaos!' WHERE `ID`=10982;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음... 좋은 냄새가 나지 않습니까? 바로 저기서 먹고 있는 음식에서 나는 냄새죠. 무지개날개다랑어 구이는 언제 먹어도 맛있단 말이에요. 나 슬리키 개스트로놈으로 말씀드릴 것 같으면 최고의 감식가로서, 특히 생선이 전문입니다. 얼라이언스 연합에서는 이제 곧 닥쳐올 안퀴라즈 전쟁 물자를 준비하는 데 전문가의 도움을 받는 것이 좋겠다고 생각했죠. 그래서 여기에 제가 왔고, 아주 중요한 역할을 담당하고 있답니다.$B$B모두 $2093w마리의 무지개날개다랑어가 필요할 것 같은데 지금까지 $2092w마리를 모았어요.', `MaleText_loc4`='嗯，嗯，嗯。你闻到了吗？！这儿有好吃的东西，$C。彩鳍鱼实在是道绝佳的美味。美食家斯里克对品尝鱼类非常在行。联盟认为在收集战争物资时带上一位专家是个明智的决定，因此，我就被派到这儿来了。我们需要$2093w条彩鳍鱼，到目前为止已经收集到$2092w条了。', `MaleText_loc5`='嗯，嗯，嗯，你有聞到嗎?!聞起來好美味，$c。彩鰭魚實在是道絕佳的美味。美食家斯里克對品嘗魚類非常在行。聯盟認為在收集戰爭物資時帶一位專家是個明智的決定，因此，我就被派到這兒來了。$B$B看來，我們需要$2093w條彩鰭魚，到目前為止已經收集到$2092w條了。', `MaleText_loc7`='Mmm, mmm, mmm. ¡¿Hueles eso?! Hay comida rica ahí mismo, $c. El atún blanco arco iris siempre sienta muy bien. Te lo dice Gastrónomo Salao, gran conocedor de todos los manjares, especialmente pescado. Con la guerra de Ahn''Qiraj acechando, la Alianza pensó que sería buena idea traer a un experto para la campaña y aquí estoy, con mi cuerpo serrano.$B$BParece que vamos a necesitar $2093w peces y los que tenemos ahora mismo suman $2092w.' WHERE `ID`=10983;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다가오는 안퀴라즈 전쟁에 대비해 이미 충분한 양의 무지개날개다랑어를 모았습니다. 신선도와 맛을 유지하기 위해 소금을 적당히 뿌려 저장해 두었지요. 어쨌든 물어봐 주셔서 감사합니다. 더 돕고 싶다면 주변을 좀 둘러보세요. 필요한 물자를 모으는 데 당신 도움이 필요한 다른 수집가들이 여기엔 분명히 있을 테니까요.', `MaleText_loc4`='呃，看来我们拥有的烤彩鳍鱼已经能满足安其拉一战的需求了。谢谢你的关心，$C。如果你想帮忙的话，就在附近问问。我敢打赌这儿有人需要你帮忙收集战争物资。', `MaleText_loc5`='嗯，看來我們擁有的烤彩鰭魚已經能滿足安其拉之戰的需求了。謝謝你的關心，$C。如果你想幫忙的話，就在附近問問。我敢打賭這兒有人需要你幫忙收集戰爭物資。', `MaleText_loc7`='Bueno, parece que tenemos todo el atún cocinado que podemos salar y almacenar debidamente para la guerra que se avecina en Ahn''Qiraj. De todos modos, gracias por preguntar, $c. Si quieres, pregunta a los demás que participan en la recogida de material. Apuesto a que alguno podría necesitar tu ayuda para algo.' WHERE `ID`=10984;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청한 애송이! 네 힘을 모조리 빼앗아주마! 그다음 차례는 네 영혼이다!', `MaleText_loc4`='愚蠢的家伙！我会吞噬你的能量，还有你的灵魂！', `MaleText_loc5`='蠢貨!我會吞噬你們體內的能量...還有靈魂!', `MaleText_loc7`='¡Cría estúpida! Consumiré tus energías – y después, ¡tu ALMA!' WHERE `ID`=10985;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새겨둬라! 네가 죽어도 친구들은 금방 널 잊을 것이야!', `MaleText_loc4`='来吧！你的朋友不会为你哀悼太久的！', `MaleText_loc5`='來吧!你的朋友不會為你哀悼太久的!', `MaleText_loc7`='¡Anímate! ¡Tus amigos pronto olvidarán tu muerte!' WHERE `ID`=10986;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한입에 삼켜버리겠다... 죽을 준비나 해라!', `MaleText_loc4`='我必须要吃点什么……准备受死吧！', `MaleText_loc5`='我要進食...你們準備死吧!', `MaleText_loc7`='Debo alimentarme... ¡prepárate para morir!' WHERE `ID`=10987;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오, 안녕하세요 $c님! 얼라이언스 연합에서는 저에게 이곳에서 사람들이 다가올 안퀴라즈 전쟁에 필요한 육류를 모아 오면 그걸 잘 관리해 달라고 부탁했답니다. 정말 웃기는 소리죠?$B$B어쨌든 숯불구이가 얼마나 모였는지 궁금하실 텐데... 마지막으로 확인했을 때가 $2098w개였고 모두 $2099w개의 랩터 숯불구이가 필요해요.', `FemaleText_loc4`='嗨，$C。联盟派遣我来到此地监管烤肉的收集工作。这听起来很有趣吧？我想你一定想知道我们收集到多少烤迅猛龙肉了。我上次数了数，我们已经有$2098w块了，总需求量是$2099w块。', `FemaleText_loc5`='喔，嗨，$c。我猜聯盟要我來這裡監管烤肉的收集工作以應付逼近的安其拉之戰。聽起來很有趣吧?$B$B我想你一定想知道我們收集到多少烤迅猛龍肉了。上次我清算的時候有$2098w塊，而我們總共需要$2099w塊烤迅猛龍肉。', `FemaleText_loc7`='¡Oh! Hola, $c. Deduzco que la Alianza me ha pedido que venga para llevar la cuenta de toda esta carne cocinada que la gente está reuniendo en vista de la inminente tragedia en Ahn''Qiraj. ¡Tiene gracia!$B$BDe todas formas, supongo que te gustaría saber cuánta tenemos. La última vez que hice el recuento teníamos $2098w de los $2099w raptores asados necesarios.' WHERE `ID`=10988;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너무 늦게 오신 것 같네요. 이미 필요한 랩터 숯불구이를 모두 모았답니다. 도살해서 조리한 다음 소금을 뿌려 놓았죠. 그건 그렇고, 주변에 도움을 기다리는 이들이 있으니 그들에게 가보시는 게 좋겠어요. 전 이제 집에 돌아갈 수 있는지 알아봐야겠어요.', `FemaleText_loc4`='看来你来得太晚了，$C。我们已经集齐所需的烤迅猛龙肉了。但是，似乎还有人需要帮助。你可以跟他们谈谈。我得看看他们会不会现在就让我回家。', `FemaleText_loc5`='看來為時已晚，$c。我們已收集完畢所有的烤迅猛龍肉了，而且已經殺好，煮好，醃製好。不過，看來附近其他人還需要幫忙。你應該去問問他們。我得看看他們會不會現在就讓我回家。', `FemaleText_loc7`='Parece que llegas tarde, $c. Ya tenemos todos los raptores asados que necesitamos, muertos, cocinados y salados. De todas formas, parece que por ahí algunos podrían necesitar algo de ayuda. Deberías ir a preguntarles. Yo voy a ver si ya me dejan ir a casa.' WHERE `ID`=10989;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='영양분을 잘 섭취하면 전쟁터에서 치명적인 부당을 당해도 오래 버틸 수 있어요. 다가올 안퀴라즈 전쟁에서 오래 버티려면 지니고 나갈 수 있는 모든 식량을 준비해야 하죠. 저는 이곳에서 필요한 양이 모일 때까지 점박이놀래기를 모으고 있어요.$B$B지금까지 $2101w마리가 모였는데, 모두를 먹이려면 $2103w마리를 모아야 한답니다.', `FemaleText_loc4`='对那些在战场上负伤的士兵来说，食物可以维持他们的生命，$C。安其拉一战我们需要准备足够的物资。我在这儿负责收集并装运斑点黄尾鱼。到目前为止，我们已经收集到$2101w条了，要满足整个军队的需求的话，我们总共需要收集$2103w条。', `FemaleText_loc5`='足夠的糧食才能應付一名士兵在戰場上$g他:她;所消耗的精力，$c。如果我們要在安其拉奮戰到底，就需要準備足夠的物資。我在這負責收集並裝運斑點黃尾魚。$B$B到目前為止，我們已經收集到$2101w條了，要滿足整個軍隊的需求的話，我們總共需要收集$2103w條。', `FemaleText_loc7`='Es imprescindible una buena alimentación para que un Soldado siga vivo tras las heridas sufridas en el campo de batalla y que ponen en peligro su vida, $c. Si queremos durar en la guerra de Ahn''Qiraj, necesitaremos todas las provisiones que podamos traer. Yo estoy reuniendo serviolas moteadas en este lugar para después enviarlas.$B$BHasta ahora tenemos $2101w pero necesitamos reunir un total de $2103w si queremos alimentar a todo el mundo.' WHERE `ID`=10990;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다시 물어봐 주셔서 감사하지만 우린 필요한 점박이놀래기를 모두 모았답니다. 그래도 앞으로 있을 전쟁에 필요한 물자를 아직 모으고 있는 곳이 여기 어딘가에 있을 거요. 그런 곳을 찾아봐요. 여신께서 그대와 함께하시기를.', `FemaleText_loc4`='谢谢你，$C。但是我们已经集齐斑点黄尾鱼了。这儿或许还有其他人正在收集战争物资。去找他们吧，愿女神保佑你。', `FemaleText_loc5`='謝謝你的詢問，$c，但是我們已經收集完所有的斑點黃尾魚了。這裡還有其他人需要為即將來臨的戰爭收集物資。去找他們，願女神的光芒照耀著你。', `FemaleText_loc7`='Gracias por tu interés, $c, pero ya tenemos todas las serviolas moteadas necesarias. Aun así, hay otros que todavía están reuniendo pertrechos para la guerra que se avecina. Búscalos y que la diosa ilumine tu camino.' WHERE `ID`=10991;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$C|1이여;여;, 냉큼 저리 가세요!', `MaleText_loc4`='散开，$c！', `MaleText_loc5`='走開，$C!', `MaleText_loc7`='¡Muévete, $c!' WHERE `ID`=10992;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 좀 성가시군요!', `MaleText_loc4`='走开，$n！', `MaleText_loc5`='手拿開，$n!', `MaleText_loc7`='¡Lárgate, $n!' WHERE `ID`=10993;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성질 돋구지 마시오!', `MaleText_loc4`='不要找茬，公民！', `MaleText_loc5`='死老百姓，別推它!', `MaleText_loc7`='¡No lo aprietes, ciudadano!' WHERE `ID`=10994;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하신가? 이곳의 상황이 심상치 않은 것은 말하지 않아도 알 것이라 믿네. 우리는 여러 가지 물건을 수집하고 있는데, 수집된 물건의 대부분은 군수품으로 만들어져 실리더스에 있는 세나리온 요새로 보내지고 있다네. 이것은 결코 쉬운 일이 아니지.$B$B최근에 우리는 화산 심장부에서 그을린 화산핵이라고 하는 것을 발견했네. 우리 대장장이와 기술자들 말로는 이 그을린 화산핵이 아주 유용하다고 하더군. 나는 이곳에서 그을린 화산핵을 모으는 일을 책임지고 있다네. 모두 $2110w개의 그을린 화산핵이 필요한데 지금까지 $2108w개밖에 못 모았네.', `MaleText_loc4`='你好，$C。我想我不需要告诉你我们现在的处境有多危险吧。我们需要收集很多物资，并将它们运往希利苏斯的塞纳里奥要塞。这工作可不轻松。$B$B最近我们在熔火之心发现一种被称作熔火之石的东西。铁匠和工程师们说这东西用处很大，因此我在这里监管熔火之石的收集工作。到目前为止，我们已经设法收集到$2108w块了，总需求量是$2110w块。', `MaleText_loc5`='你好，$c。我想我不需要提醒你現在的狀況有多嚴重。我們需要收集許多東西，而大部分都是要將它們集合起來送去希利蘇斯的塞納里奧城堡。這不是件輕鬆的差事。$B$B最近我們在熔火之心發現一種被稱作熔火之石的東西。鐵匠和工程師們說這東西用處很大，因此我在這裡監管熔火之石的收集工作。到目前為止，我們已經設法收集到$2108w塊了，總需求量是$2110w塊。', `MaleText_loc7`='Hola, $c. Supongo que no necesito informarte de la gravedad de nuestra situación aquí. Tenemos que reunir mucha mercancía y, en la mayoría de los casos, organizarla para ser enviada al Fuerte Cenarion en Silithus. No es tarea fácil.$B$BHace poco descubrimos en el Núcleo de Magma algo llamado piedra nuclearia abrasada. Nuestros herreros e ingenieros aseguran que pueden sacarles partido así que estoy supervisando la recolección de las mismas. Hasta el momento, de las $2110w necesarias, hemos conseguido reunir $2108w.' WHERE `ID`=10995;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스의 모험심 많은 여러 길드의 단결된 노력 덕분에 필요하다고 예상되는 양의 그을린 화산핵을 모두 모을 수 있었네. 하지만 이곳에서 다른 물자를 모으고 있는 이들이 도움을 필요로 할지 모르니 주변을 확인해 보는 게 어떻겠니?', `MaleText_loc4`='在联盟方的各大冒险公会的共同努力下，我们已经集齐了所需的熔火之石。但是，你可以问问其他的收集者，看他们是否需要帮忙。', `MaleText_loc5`='在聯盟方的各大冒險公會的共同努力下，我們已經集齊了所需的熔火之石。但是，你可以問問其他的收集者，看他們是否需要幫忙。', `MaleText_loc7`='Gracias al esfuerzo combinado de las hermandades de la Alianza, hemos sido capaces de reunir todas las piedras nuclearias abrasadas que consideramos necesarias. Sin embargo, puede que quieras preguntar por ahí a los demás si necesitan ayuda en la recogida de productos vitales.' WHERE `ID`=10996;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 구리 주괴가 아주 많이 필요하오. 안퀴라즈에서 벌어질 전쟁에 쓸 무기며 갑옷 등을 만들려면 대량의 구리를 확보해야만 하오. 호드에게 필요한 구리 주괴만 해도 최소한 $1998w개라는데 우린 지금까지 $2018w개 비축했을 뿐이지.', `MaleText_loc4`='我们需要大量铜锭，$C。安其拉一战迫在眉睫，我们需要准备足够的金属来制造武器、护甲和其他器物。部落需要收集$1998w块铜锭。到目前为止，我们已经收集到$2018w块了。', `MaleText_loc5`='我們需要大量銅錠，$c。安其拉之戰即將開打，我們需要準備足夠的金屬來製造武器、護甲和其他器物。我聽說光是部落就需要$1998w塊銅錠。目前我們已收集$2018w塊了。', `MaleText_loc7`='Necesitamos gran cantidad de barras de cobre, $c. Con la guerra que se avecina en Ahn''Qiraj, se necesitará mucho metal para armas, armaduras y otras cosas. Solo la Horda necesita reunir $1998w barras de cobre. Hasta el momento tenemos $2018w.' WHERE `ID`=10997;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최근에 확인한 결과 전쟁에 필요한 구리 주괴가 모두 모였소. 내가 당신이라면 다른 물자를 수집하고 있는 이들 중 도움이 필요한 이는 없는지 확인해 보겠소이다.', `MaleText_loc4`='根据最近一次统计，我们已经集齐了战争所需的铜锭。如果我是你的话，我会跟其他收集者谈谈，看看他们是否需要帮助。', `MaleText_loc5`='根據最近一次統計，我們已收集好戰爭需要的銅錠。如果我是你，我會問問其他的人需不需要幫忙收集。', `MaleText_loc7`='De acuerdo con el último recuento tenemos todas las barras de cobre que vamos a necesitar para la guerra. Yo en tu lugar preguntaría a los demás si alguien necesita ayuda con los trabajos de recogida de material.' WHERE `ID`=10998;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='태양 첨탑에 있는 마법학자 이로나 님을 아직 만나보지 못했다면 당장 찾아가 보십시오. 급하게 처리해야 할 일이 있습니다. 우리와 마찬가지로 그녀 역시 그대의 도움이 필요합니다!', `MaleText_loc4`='如果你还没有和太阳之塔的魔导师艾洛娜谈过话，最好马上去看看。那里有一些棘手的问题需要解决，而且她就像我们一样，需要你的帮助！', `MaleText_loc5`='如果你還沒有跟日尖塔的博學者伊羅娜談過，我建議你最好立刻就去。有重要的事你該知道，而她和我們一樣都需要你的幫助!', `MaleText_loc7`='Si no has hablado con la Magistrix Erona en la Aguja del Sol, te recomiendo que lo hagas enseguida. Hay asuntos urgentes que atender, y ella necesita toda tu ayuda... y todos nosotros también.' WHERE `ID`=10999;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님, 다시 만나서 반갑습니다.$B$B배움에 집중하십시오. 그대의 어깨에 우리 미래가 달렸습니다. 그대가 흔들린다면 우리의 미래는 암울해질 것입니다.', `MaleText_loc4`='$n，很高兴再次遇到你。$B$B记住在你的学习上保持专注。你代表了我们的未来，如果你遭遇了失败，我们的未来无疑会变得更加黑暗。', `MaleText_loc5`='$n，很高興再見到你。$B$B記得專注於你的學習，你代表著我們的未來。如果你失敗的話，我們的未來就會黯淡無光。', `MaleText_loc7`='$n, me alegro de volver a verte.$B$BRecuerda mantenerte centrado en tu aprendizaje. Tú representas nuestro futuro y, si vacilas, nuestro futuro será oscuro de verdad.' WHERE `ID`=11000;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='트롬카! 주석 주괴 모으는 일을 도와주러 왔소? 다가올 안퀴라즈 전쟁에 필요한 무기와 갑옷을 만들려면 $2006w개가 필요하다고 했는데 아직 $2005w개 밖에 모으질 못했소이다. 주석 주괴를 좀 더 가지고 와 주시오!', `MaleText_loc4`='你好，$C。你是来帮助我收集锡锭的吗？我需要收集$2006w块锡锭，以用于制造安其拉一战所需的武器和护甲，但是到目前为止我只收集到$2005w块。你得再帮我收集一些！', `MaleText_loc5`='(獸人語)你好，$c。你來幫我收集錫錠的嗎?他們說我需要$2006w塊錫錠他們才能製作安其拉之戰需要的武器和護甲，但我現在只有$2005w塊。你得再幫我收集一些!', `MaleText_loc7`='Throm''ka, $c. ¿Estás aquí para ayudarme con las barras de estaño? Me dicen que necesitaremos $2006w para poder fabricar armas y armaduras para la guerra de Ahn''Qiraj que se avecina, pero ahora mismo solamente tenemos $2005w. ¡Y tú me traerás más!' WHERE `ID`=11001;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주석 주괴는 인제 그만 모아도 된다오! 그것들을 쌓아올리느라 팔이 다 빠지는 줄 알았소. 주석 주괴는 이미 필요한 만큼 모았으니 다른 물자를 수집하는 이들 중 도움이 필요한 자가 없는지 가서 물어보시오.', `MaleText_loc4`='不需要锡锭了。堆放这些锡锭还弄伤了我的手臂。我们已经有足够的锡锭了。去问问其他人吧，他们或许需要你的帮助。', `MaleText_loc5`='不必收集錫錠了!我的手臂光是堆疊錫錠就已經很累了。我們已經有所有需要的東西了，去問問其他人是否需要你幫忙收集東西。', `MaleText_loc7`='¡No, más barras de estaño no! Ya me duelen los brazos de apilarlas. Tenemos todas las necesarias así que ve y pregunta a alguno de los otros si necesita ayuda para recoger algo.' WHERE `ID`=11002;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='매날개 광장 여관에 오신 것을 환영합니다. 따뜻한 식사를 대령할까요 아니면 편히 누우실 방을 준비해 드릴까요?', `FemaleText_loc4`='欢迎来到鹰翼广场旅店。需要给您准备一顿美食，还是准备一间房间？', `FemaleText_loc5`='歡迎光臨獵鷹之翼廣場旅館，需要我為您準備一頓大餐，或是一間房間呢?', `FemaleText_loc7`='Te doy la bienvenida a la posada de la Plaza Alalcón. ¿Quieres que te prepare comida, o una habitación?' WHERE `ID`=11003;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제단 옆에 있는 금으로 된 푯말에 다음과 같은 글귀가 적혀있습니다.$B$B"이곳은 가장 고귀한 엘프를 기리기 위해 만든 다트리마의 제단이다. 이 제단을 찾는 모든 이는 우리를 이 땅에 데려오기 위해 자신을 희생한 그의 숭고한 정신을 기억해야 한다. 또한 쿠엘탈라스에서 번영을 누리고 있는 모든 이들 역시 그에게 감사하는 마음을 가져야 한다."', `MaleText_loc4`='神龛旁的金色布告写着：$B$B“这里竖立着达斯雷玛的神龛，一个献给最高贵的精灵的礼物。让我们凝视这座纪念碑，没有他的牺牲，就没有如今我们脚下的土地。奎尔萨拉斯的一切繁荣之景都是因为他的功绩。”', `MaleText_loc5`='神殿旁的一塊金色公告牌上寫著:$B$B「這是達斯雷瑪神殿，對最高尚的精靈們致上最高的敬意。讓所有瞻仰過這個紀念碑的人都會記得他的犧牲。所有讓奎爾薩拉斯繁榮的人們也都感謝他。」', `MaleText_loc7`='Una placa dorada a lo largo del lateral del santuario reza:$B$B"Aquí se encuentra el santuario de Dath''Remar, un tributo adecuado al más noble de los elfos. Que todo el que mire este monumento recuerde sus sacrificios para traernos a estas tierras. Todo el que prospere en Quel''Thalas lo hace gracias a él."' WHERE `ID`=11004;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$c|1이여;여;, 안녕하십니까? 아이언포지 여단은 하이브조라를 감시하기 위해 이곳에 배치되었습니다. 실리시드의 동태를 계속 주시해 온 세나리온 의회 드루이드들에 의하면 이 지역에서 뭔가 심상치 않은 일이 벌어질 것 같다고 합니다.', `FemaleText_loc4`='嗨，$C。铁炉堡军团驻扎在此地，密切注视着佐拉虫巢的动静。塞纳里奥要塞的德鲁伊们一直监视着异种虫类的一举一动，他们预计这儿将发生大事。', `FemaleText_loc5`='嗨，$c。鐵爐堡兵團被部署在這裡監視佐拉蟲巢。塞納里奧議會的德魯伊一直以來都在監控異種活動，他們預期在這兒會有重大的事情發生。', `FemaleText_loc7`='Ave, $c. La Brigada de Forjaz está emplazada aquí para vigilar Hive''Zora. Los druidas del Círculo Cenarion han estado controlando los movimientos de los silítidos y prevén que algo importante va a ocurrir en esta zona.' WHERE `ID`=11005;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연대장님을 돕기 위해 이곳에 왔습니다.', `MaleText_loc4`='我是来帮助上尉的。', `MaleText_loc5`='我是來支援上尉的。', `MaleText_loc7`='He venido para ayudar al Capitán.', `FemaleText_loc1`='연대장님을 돕기 위해 이곳에 왔습니다.', `FemaleText_loc4`='我是来帮助上尉的。', `FemaleText_loc5`='我是來支援上尉的。', `FemaleText_loc7`='He venido para ayudar al Capitán.' WHERE `ID`=11006;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='연대장님은 우리가 최근에 입수한 실리시드의 지하 둥지 지도를 연구하시느라 지금 바쁘십니다. 돕고 싶다면 여기서 기다리세요. 금방 오실 겁니다.', `FemaleText_loc4`='上尉现在很忙。我们最近刚得到一份异种虫类的虫巢地图，他正在研究这张地图。如果你想要帮忙的话，就跟我们待在一起，他随时都会出来的。', `FemaleText_loc5`='上尉現在很忙。他正在研讀我們最近從地底異種巢穴找到的地圖。如果你想幫忙就跟著我們，他隨時都會出來。', `FemaleText_loc7`='El Capitán está ocupado en este momento. Está analizando unos mapas que conseguimos hace poco de las colmenas subterráneas de los silítidos. Quédate con nosotros si quieres ayudar, no tardará mucho en salir.' WHERE `ID`=11007;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 엘룬의 양초를 보더니 기절합니다!', `MaleText_loc4`='%s被艾露恩的蜡烛击昏了！', `MaleText_loc5`='%s因伊露恩的蠟燭而昏迷!', `MaleText_loc7`='La Vela de Elune aturde a %s.' WHERE `ID`=11008;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1을;를; 해치워라!', `MaleText_loc4`='杀了$n！', `MaleText_loc5`='殺吧，$n!', `MaleText_loc7`='¡Mata a $n!' WHERE `ID`=11009;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이봐요, 척 보니 제게 미스릴 주괴를 가져다 주려고 여기 오셨군요. 안퀴라즈의 실리더스 사막에서 벌어질 격전이 임박했어요. 우리와 얼라이언스 모두 벌레들을 막기 위해 총력을 다하고 있죠. 모두들 여기 모인 이유도 바로 그것 때문이죠.$B$B호드는 제게 $2009w개를 모아 달라고 부탁했는데 제가 가지고 있는 건 $2008w개밖에 없어요. 그러니 절 좀 도와주셔야겠어요. 안 도와주실 건가요?', `FemaleText_loc4`='嗨，你到这儿来一定是带秘银锭给我的吧。我需要收集$2009w块秘银锭，但是现在只收集到$2008w块。你愿意帮帮我吗？', `FemaleText_loc5`='嗨，你是來這裡幫我收集秘銀的吧。希利蘇斯沙漠上的安其拉有大麻煩了。我們和聯盟都沒時間對付那些異種蟲類了，這就是你看到大家都在這裡的原因。$B$B部落要求我們為戰爭收集$2009w塊秘銀錠，但我只有$2008w塊。你能幫我的忙，是嗎?', `FemaleText_loc7`='Eh colega, seguro que venir con barras de mitril. No será sencillo ponerse a fabricar cosas en Ahn''Qiraj, en el desierto de Silithus. Esta vez, nosotros y la Alianza vamos al completo a pararle los pies a esos bichejos por eso estamos todos aquí.$B$BLa Horda me ha pedido que reúna $2009w para la campaña pero solamente tengo $2008w. ¿Así que me vas a ayudar o qué?' WHERE `ID`=11010;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그래요, 전쟁에 필요한 미스릴 주괴를 모두 모은 것 같아요. 하지만 주변에 아직도 당신의 도움을 바라는 동지들이 많이 있다는 거 알고 있지요? 아무튼 고맙습니다.', `FemaleText_loc4`='呀，似乎我们已经收集到足够数量的秘银锭了。但是你知道，这附近有很多人现在也许正需要你的帮助呢。谢谢你。', `FemaleText_loc5`='是啊，我知道，看來我們已經有戰爭所需的秘銀錠了。但你知道的，這附近有很多人現在也許正需要你的幫助呢。謝謝你。', `FemaleText_loc7`='Sí, lo sé, parece que ya tenemos todas las barras de mitril que necesitamos para la guerra. Pero ¿sabes? Todavía hay muchos por ahí que podrían necesitar tu ayuda ahora mismo. Gracias, colega.' WHERE `ID`=11011;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들이 오고 있다. 자신의 몸을 지키도록 하라!', `MaleText_loc4`='它们来了。尽量别被它们干掉，新兵。', `MaleText_loc5`='它們來了。盡量別被它們幹掉，新兵。', `MaleText_loc7`='Ahí vienen. Intenta que no te maten, $gchico:chica;.' WHERE `ID`=11012;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='반갑습니다, 젊은 $c|1이여;여;. 제게 평온초 꽃잎 다발을 주시려고 오셨습니까? 우리는 안퀴라즈 전쟁에 사용할 물약과 비약을 만들기 위해 평온초 꽃잎을 모으고 있답니다. 사실 전쟁 자체가 커다란 비극이라고 할 수 있지만 철저하게 준비하지 않으면 상상조차 할 수 없는 끔찍한 결과가 찾아올 수도 있습니다.$B$B호드에서 요청한 평온초 꽃잎의 수량은 $2020w개인데 지금까지 $2021w개 밖에 못 모았습니다. 할 수 있다면 평온초 꽃잎을 최대한 많이 모아주십시오.', `FemaleText_loc4`='你好，年轻的$C。你到这儿来是带宁神花给我的吗？我们正在为安其拉之战做准备，收集宁神花，制作药水和药剂。如果我们准备得不够充分的话，将会产生非常严重的后果。$B$B部落派我来此收集$2020w株宁神花，到目前为止我们已经设法收集到$2021w株了。如果你力所能及的话，就请帮帮我们，把宁神花带给我。', `FemaleText_loc5`='嗨，年輕的$c。你是為了帶一批寧神花給我而來的嗎?我們正為了安其拉之戰收集這些東西製作藥水和藥劑。雖然迎戰對我們不利，但如果我們不作適當地準備後果會更不堪設想。$B$B部落要求我收集$2020w份寧神花，到目前為止我們收集了$2021w份。如果你的能力所及，請盡可能收集所有數量並帶回來這裡給我。', `FemaleText_loc7`='Hola, joven $c. ¿Vienes a traerme un montón de flores de paz? Estamos recogiéndolas para hacer pociones y elixires para la campaña de Ahn''Qiraj. Si tener que ir a la guerra ya es malo, los resultados serán todavía peores si no nos preparamos debidamente.$B$BLa Horda me ha pedido que reúna $2020w flores de paz y hasta el momento hemos conseguido juntar $2021w. Por favor, si sabes hacerlo recoge todas las que puedas y tráemelas.' WHERE `ID`=11013;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우릴 돕고 싶다니 정말 고맙습니다. 그런데 어쩌죠? 전쟁에 쓸 평온초 꽃잎은 이미 다 모았답니다. 주변에 다른 이들에게 가보세요. 다른 물자를 수집할 도움의 손길을 원하는 이들이 여기 어딘가에 분명히 있을 겁니다.', `FemaleText_loc4`='你愿意帮忙，我很高兴，$C。但是我已经收集到足够数量的宁神花了。或许你可以四下问问；我想这儿会有其他人需要你帮忙收集战争物资的。', `FemaleText_loc5`='你願意幫忙真是太好了，$c。但是我已經收集到足夠數量的寧神花了。或許你可以四處看看;我確定那裡有其他人也需要你的協助去收集其他東西。', `FemaleText_loc7`='Me alegro de que quieras ayudar, $c. Por desgracia ya he reunido todas las flores de paz necesarias para la campaña. Podrías preguntar por ahí pues seguro que hay alguien que todavía necesita tu ayuda para recoger otras cosas.' WHERE `ID`=11014;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 해치려는 것이냐?', `MaleText_loc4`='你想要伤害我吗，$R？', `MaleText_loc5`='你企圖想要傷害我，$r?', `MaleText_loc7`='¿Vas a hacerme daño, $r?' WHERE `ID`=11015;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 강력한 유물을 찾아다니는 보물 사냥꾼이오. 보물을 내게 넘기면 해치지 않겠소.', `MaleText_loc4`='我是来寻找拥有强大力量的神器的。把它们给我，我就不伤害你。', `MaleText_loc5`='我是一個尋找強大神器的寶藏獵人。把它給我，你就不會受到傷害。', `MaleText_loc7`='Soy un cazador de tesoros en busca de poderosos artefactos. Dámelos y no te haré daño.', `FemaleText_loc1`='나는 강력한 유물을 찾아다니는 보물 사냥꾼입니다. 보물을 내게 넘기면 해치지 않겠습니다.', `FemaleText_loc4`='我是来寻找拥有强大力量的神器的。把它们给我，我就不伤害你。', `FemaleText_loc5`='我是一個尋找強大神器的寶藏獵人。把它給我，你就不會受到傷害。', `FemaleText_loc7`='Soy una cazadora de tesoros en busca de poderosos artefactos. Dámelos y no te haré daño.' WHERE `ID`=11016;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='푸른용군단에게 도전하는 것이냐? 죽어라, 이 벌레 같은 놈!', `MaleText_loc4`='你胆敢向蓝龙挑战？死吧，可怜虫。', `MaleText_loc5`='你膽敢向藍龍軍團挑戰?死吧，可憐蟲。', `MaleText_loc7`='¿Cuestionas la orden del Vuelo Azul? ¡MUERE, alimaña!' WHERE `ID`=11017;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 보복하기 위해 반격합니다.', `MaleText_loc4`='%s发动了反攻。', `MaleText_loc5`='%s以報復還擊。', `MaleText_loc7`='%s contraataca con represalias.' WHERE `ID`=11018;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필멸의 존재여, 나의 감시는 영원할 것이다.', `MaleText_loc4`='我将永远在此守护，凡人。', `MaleText_loc5`='我的看守是永恆的，凡人。', `MaleText_loc7`='Mi vigilancia es permanente, mortal.' WHERE `ID`=11022;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법이란 단지 신비로운 재주만을 일컫는 것이 아니오. 그대는 이미 이 사실을 알고 있겠지?$B$B가르침을 얻고자 나를 찾아왔으니 내 말에 귀를 기울이시오. 악마의 비밀은 어리석은 이가 알아낼 수 있을 만큼 간단하지 않고, 나 역시 현명한 이들에게만 가르침을 내려준다오.', `MaleText_loc4`='魔法不仅仅是做几个神秘的手势……你应该已经明白这个道理了，对吗？$B$B你是来学习知识的，只要你用心领悟，并听从我的指导，那么你就能学到知识……只有头脑愚钝的家伙才不愿意探究恶魔的秘密，当然我也不会在意这样的蠢材。', `MaleText_loc5`='魔法的奧秘不光是那些神秘的施法動作而已...但是跟我對話的你也明白這點，對嗎?$B$B你來找我是為了學習，而你將得償所望...只要你專心學習並且聽從我的指示。惡魔的秘密不會平白無故提供給傻瓜，而我也不會。', `MaleText_loc7`='La magia es más que gestos arcanos... pero tú ya lo sabes, ¿no es así?$B$BHas venido aquí a aprender, y eso harás... siempre y cuando me prestes atención y hagas lo que yo te diga. Los secretos de los demonios no atienden a los necios, ni yo tampoco.', `FemaleText_loc1`='마법이란 단지 신비로운 재주만을 일컫는 것이 아닙니다. 당신은 이미 이 사실을 알고 있겠지요?$B$B가르침을 얻고자 나를 찾아왔으니 내 말에 귀를 기울이십시오. 악마의 비밀은 어리석은 이가 알아낼 수 있을 만큼 간단하지 않고, 나 역시 현명한 이들에게만 가르침을 내려줄 겁니다.', `FemaleText_loc4`='魔法不仅仅是做几个神秘的手势……你应该已经明白这个道理了，对吗？$B$B你是来学习知识的，只要你用心领悟，并听从我的指导，那么你就能学到知识……只有头脑愚钝的家伙才不愿意探究恶魔的秘密，当然我也不会在意这样的蠢材。', `FemaleText_loc5`='魔法的奧秘不光是那些神秘的施法動作而已...但是跟我對話的你也明白這點，對嗎?$B$B你來找我是為了學習，而你將得償所望...只要你專心學習並且聽從我的指示。惡魔的秘密不會平白無故提供給傻瓜，而我也不會。', `FemaleText_loc7`='La magia es más que gestos arcanos... pero tú ya lo sabes, ¿no es así?$B$BHas venido aquí a aprender, y eso harás... siempre y cuando me prestes atención y hagas lo que yo te diga. Los secretos de los demonios no atienden a los necios, ni yo tampoco.' WHERE `ID`=11023;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<단호한 표정으로 당신을 바라보는 안도로브>$B$B만약 놈이 피를 흘리게 할 수만 있다면 해치울 수 있다.', `MaleText_loc4`='<安多洛夫严肃地看着你。>$B$B如果它会流血，我们就能杀了它。', `MaleText_loc5`='< 安多洛夫冷酷地看著你。>$B$B如果它會流血，我們就能殺了它。', `MaleText_loc7`='<Andorov te echa una mirada adusta.>$B$BSi sangra, podemos matarlo.' WHERE `ID`=11025;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한번 시도해 봅시다.', `MaleText_loc4`='动手吧！', `MaleText_loc5`='動手吧!', `MaleText_loc7`='Comprobémoslo.', `FemaleText_loc1`='한번 시도해 보죠.', `FemaleText_loc4`='动手吧！', `FemaleText_loc5`='動手吧!', `FemaleText_loc7`='Comprobémoslo.' WHERE `ID`=11026;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈들의 세계는 무자비한 종말을 맞이하게 될 것이다. 악몽이 너희를 찾아갈 것이니라!', `MaleText_loc4`='你所属的世界将陷入残酷的末日。噩梦已经降临！', `MaleText_loc5`='你的世界將遭受殘酷的結局。願夢魘與你同在!', `MaleText_loc7`='Tu mundo llegará a su fin. ¡La Pesadilla viene a por ti!' WHERE `ID`=11027;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 너는 꼭 마지막에 해치우겠다고 말했던 걸 기억하나, 라작스?', `MaleText_loc4`='拉贾克斯，还记得我说过要杀光其它虫子之后再干掉你么？', `MaleText_loc5`='記得嗎，拉賈克斯，上次我說會殺了你?', `MaleText_loc7`='Rajaxx, ¿recuerdas que te dije que serías el último en morir?' WHERE `ID`=11028;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='종말이 빠르게 다가오고 있다! 이 에라니쿠스 님께 스스로 무릎을 꿇어 영원한 고통에서 벗어나 보아라!', `MaleText_loc4`='末日就快要来临了！向伊兰尼库斯投降，从永恒的痛苦中解脱出来吧！', `MaleText_loc5`='末日就快要來臨了!向伊蘭尼庫斯投降，從永恆的痛苦中解脫出來吧!', `MaleText_loc7`='¡El final está cerca! ¡Rendíos a Eranikus y evitad así el eterno sufrimiento!' WHERE `ID`=11029;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언젠가는 죽음을 맞이할 가련한 존재여... 네 놈들이 무슨 짓을 저질렀는지 모르는구나! 그분의 의지가 실현될 것이다. 달숲은 파괴될 것이며, 그와 함께 말퓨리온 녀석도 죽음을 맞이할 것이다!', `MaleText_loc4`='可怜的凡人……你都不知道自己在干什么！主人的愿望已经达成。月光林地和玛法里奥都会被摧毁的！', `MaleText_loc5`='令人同情、可憐的凡人...你不知道你完成了什麼!主人的願望已經達成。月光林地和瑪法里恩都會被摧毀的!', `MaleText_loc7`='Lamentables y siempre predecibles mortales... ¡No tenéis ni idea de lo que habéis hecho! Se ha cumplido la voluntad del Maestro. ¡El Claro de la Luna será destruido y Malfurion con él!' WHERE `ID`=11030;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도망쳐라, 작은 생명체여. 가서 네 주인에게 이 에라니쿠스 님께서 이 세계를 파괴하러 왔다고 전하라.', `MaleText_loc4`='逃命吧，渺小的凡人。告诉你的主人，伊兰尼库斯正在摧毁他们的世界。', `MaleText_loc5`='逃命吧，渺小的凡人。告訴你的主人，伊蘭尼庫斯正在摧毀他們的世界。', `MaleText_loc7`='Corran, pequeñajos. Corran y díganles a sus maestros que Eranikus ha venido a arrasar su mundo.' WHERE `ID`=11031;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='질문은 우선 놈을 처치한 다음에 하도록... 온다!', `MaleText_loc4`='先杀敌，再说废话……准备！', `MaleText_loc5`='先殺再說...他們來了!', `MaleText_loc7`='Primero mata, después pregunta... ¡Marchando!' WHERE `ID`=11032;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='푸른용군단이 지키고 있는 홀 파편을 찾고 있나?$B$B<희미한 미소를 짓는 아주어고스>', `MaleText_loc4`='你是来寻找守护蓝龙的节杖碎片的？$B$B<艾索雷葛斯的表情似乎是在微笑。>', `MaleText_loc5`='你是來尋找保護藍龍軍團的權杖裂片?$B$B<艾索雷葛斯的表情似乎是在微笑。>', `MaleText_loc7`='¿Estás buscando el fragmento de cetro verde confiado al Vuelo Azul?$B$B<Azuregos parece dibujar una sonrisa.>' WHERE `ID`=11033;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 알았소? 그러니까, 그게... 그래요... 그 조각을 찾고 있소. 당신이 가지고 있소?', `MaleText_loc4`='你是怎么知道的？我是说，是的……我正在寻找碎片。你有吗？', `MaleText_loc5`='你是怎麼知道的?我想...是...是的，我正在尋找裂片。你有嗎?', `MaleText_loc7`='¿Cómo lo has sabido? Pues sí... Estoy buscando ese fragmento. ¿Lo tienes tú?', `FemaleText_loc1`='어떻게 알았죠? 그러니까, 그게... 그래요... 그 조각을 찾고 있어요. 당신이 그걸 가지고 있나요?', `FemaleText_loc4`='你是怎么知道的？我是说，是的……我正在寻找碎片。你有吗？', `FemaleText_loc5`='你是怎麼知道的?我想...是...是的，我正在尋找裂片。你有嗎?', `FemaleText_loc7`='¿Cómo lo has sabido? Pues sí... Estoy buscando ese fragmento. ¿Lo tienes tú?' WHERE `ID`=11034;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론 나는 그것을 가지고 있지 않다. 그건 바보 같은 짓이지. 여기는 이 저주받은 땅의 미개한 족속들이 날뛰는 곳이다! 채 다섯 걸음도 옮기기 전에 내 가죽을 노리고 미친 오크나 인간들이 서슬 퍼런 칼을 들이대고 무자비하게 마법을 난사한단 말이다. 때가 되면 너는 내 영혼과 언제든 대화를 나눌 수 있을 것이다.$B$B어쨌든... 그 조각은 내가 숨겨 두었다.$B$B어디있느냐 물어보아야 하지 않겠는가?', `MaleText_loc4`='我当然没有碎片。把那东西带在身上是极其愚蠢的做法。我生活在这片被诅咒的蛮荒之地上！我走不到五步，就必然有疯子一般的兽人或是人类想要攻击我。我随时都可能命丧黄泉。$B$B总之……我把那东西藏起来了。$B$B继续吧……问问我把碎片藏在哪儿了。', `MaleText_loc5`='我當然沒有裂片。把那東西帶在身上是極其愚蠢的做法。我生活在這片被詛咒的蠻荒之地上!我走不到五步，就必然有瘋子一般的獸人或是人類想要攻擊我。我隨時都可能命喪黃泉。$B$B總之...我把那東西藏起來了。$B$B繼續吧...問問我把裂片藏在哪兒了。', `MaleText_loc7`='Pues claro que no tengo el fragmento. Sería de necios. ¡Estoy rodeado de salvajes en esta condenada tierra! No puedo dar dos pasos sin que un orco o un humano enloquecido intenten clavarme una estaca. Podrías perfectamente estar hablando con un fantasma.$B$BDe cualquier manera... Lo escondí.$B$BVenga... pregúntame dónde.' WHERE `ID`=11035;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠소. 어디에 숨겨 두었소?', `MaleText_loc4`='好吧。在哪儿？', `MaleText_loc5`='好吧。在那?', `MaleText_loc7`='Está bien. ¿Dónde?', `FemaleText_loc1`='알겠어요. 어디에 숨겨 두었나요?', `FemaleText_loc4`='好吧。在哪儿？', `FemaleText_loc5`='好吧，在那?', `FemaleText_loc7`='Está bien. ¿Dónde?' WHERE `ID`=11036;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋다, 네가 좋아할 만한 얘기를 들려주지. 말리고스가 내게 홀의 파편을 지키는 임무를 맡겼을 때 나는 그 일로 내 긴 영생동안 골머리를 앓을 것이라는 걸 알았다.$B$B내가 하고자 하는 일은 마력으로 충만한 이 해안들을 연구하고 세계의 분리 후 남아 있을지 모르는 유물을 거두는 것뿐이다. 너도 알겠지만 한때 이곳에는 번영을 누리던 명가의 문명이 있었다! 이 근처에 괜찮은 마법 물품이 있을 거라는 얘기는 하지 않아도 된다. 그 정도는 나도 알 수가 있으니까 말이다!', `MaleText_loc4`='你会喜欢这个故事的，$R。听着吧。当玛里苟斯让我保护节杖碎片时，我就知道我会为此头痛的。$B$B我只想在这片满是魔法遗物的海岸线上进行研究工作，寻找那次世界分裂时留下的神器。要知道，这儿是艾萨琳城的废墟，女王艾萨拉的家园！你不需要告诉我这附近有魔法器物，$R。我能闻到它们的味道！', `MaleText_loc5`='你會愛上這個故事的，$r。你看，就是這個。當瑪里苟斯讓我保護權杖裂片時，我就知道我會為此頭痛的。$B$B我只想在這片滿是魔法遺物的海岸線上進行研究工作，尋找讓世界分裂的那個大爆炸事件所留下的神器。要知道，這裡曾經有過一個輝煌的精靈貴族文明!你不需要告訴我這附近有魔法物品，$r。我能聞到它們的味道!', `MaleText_loc7`='Te va a encantar esta historia, $r. Escucha. Tan pronto como Malygos me encargó la protección del fragmento de cetro, supe que iba a ser la causa de un eterno sufrimiento y preocupación.$B$BYo lo único que quiero es estudiar estas costas mágicas y recoger los artefactos que puedan quedar del Cataclismo. ¿Sabes? ¡En su día hubo aquí una próspera civilización de los Altonato! No hace falta que me digas que me voy a encontrar con algunos objetos mágicos por aquí, $r. ¡Ya lo intuyo!' WHERE `ID`=11037;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='브론즈비어드에 의하면... 음, 비어드! 대체 무슨 말을 하는 겁니까?', `MaleText_loc4`='你究竟……在说什么……？', `MaleText_loc5`='以銅鬚之名...嗯，鬚子!你在說什麼?', `MaleText_loc7`='¡Por las barbas... eh... de Barbabronce! ¿De qué estás hablando?', `FemaleText_loc1`='브론즈비어드에 의하면... 음, 비어드! 대체 무슨 말을 하는 거죠?', `FemaleText_loc4`='你究竟……在说什么……？', `FemaleText_loc5`='以銅鬚之名...嗯，鬚子!你在說什麼?', `FemaleText_loc7`='¡Por las barbas... eh... de Barbabronce! ¿De qué estás hablando?' WHERE `ID`=11038;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말했듯이 나는 500년간 홀의 파편을 지켜 왔지만 홀의 파편은 한낱 골칫거리에 지나지 않았다. 그것은 모든 관심, 순수하지 않은 나쁜 의도를 지닌 자들의 관심을 끌었다. 내가 원하는 것은 조용히 혼자 연구하는 것이지 영웅이 되고 싶은 누군가가 그것을 훔쳐 가지는 않을까 감시하는 것이 아니었다. 그래서... 나는 홀의 파편을 물고기에게 던져 주었다.', `MaleText_loc4`='正如我所说的，我保存节杖碎片已经有500年了，这东西真麻烦。所有生物都不怀好意地觊觎这块碎片。我希望能专心研究，不受打扰。因此……我把它扔给了一条鱼。', `MaleText_loc5`='正如我所說的，我保存權杖裂片已經有500年了，這東西真麻煩。所有生物都不懷好意地覬覦這塊裂片。我希望能專心研究，不受打擾。因此...我把它扔給了一條魚。', `MaleText_loc7`='Como iba diciendo, me aferré a ese fragmento de cetro durante unos quinientos años y solamente me trajo problemas. Llamaba la atención de todos, muy a mi pesar. Quiero estar tranquilo para poder investigar en lugar de tener cuenta del pasaporte hacia la gloria de alguien. Así pues... Se lo di a un pez.' WHERE `ID`=11039;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물고기라고? 칼림도어의 모든 생명을 살릴 중요한 열쇠일지도 모르는 그 조각을 물고기에게 주었다는 말이오?', `MaleText_loc4`='鱼？你是说你把这件可能关系到整个卡利姆多命运的东西交给了一条鱼？', `MaleText_loc5`='魚?你是說你把這件可能關係到整個卡林多命運的東西交給了一條魚?', `MaleText_loc7`='¿Pez? ¿Le has dado a un pez lo que podría ser la clave para salvar Kalimdor?', `FemaleText_loc1`='물고기라고요? 칼림도어의 모든 생명을 살릴 중요한 열쇠일지도 모르는 그 조각을 물고기에게 주었다고요?', `FemaleText_loc4`='鱼？你是说你把这件可能关系到整个卡利姆多命运的东西交给了一条鱼？', `FemaleText_loc5`='魚?你是說你把這件可能關係到整個卡林多命運的東西交給了一條魚?', `FemaleText_loc7`='¿Pez? ¿Le has dado a un pez lo que podría ser la clave para salvar Kalimdor?' WHERE `ID`=11040;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무 물고기에게나 준 것이 아니다, 필멸의 존재여. 작고도 아주 특별한 물고기였느니라.', `MaleText_loc4`='不是别的鱼类，凡人。我说的是米诺鱼，一种非常特别的米诺鱼。', `MaleText_loc5`='不是一般的魚，凡人。我說的是小魚，一種非常特別的小魚。', `MaleText_loc7`='No a un pez cualquiera, mortal. Se trataba de una sardinilla. Una sardinilla muy especial.' WHERE `ID`=11041;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='작은 물고기라 했소? 바다에 작은 물고기가 한둘이오? 1억 마리도 넘을 것이오!', `MaleText_loc4`='米诺鱼？海里到处都是米诺鱼！有上亿条呢！', `MaleText_loc5`='小魚?海裡到處都是小魚!有上億條呢!', `MaleText_loc7`='¿Una sardinilla? ¡Los océanos están llenos de ellas! ¡Podría haber hasta cien millones de sardinillas ahí fuera!', `FemaleText_loc1`='작은 물고기라고요? 바다에 작은 물고기가 한둘인가요? 1억 마리도 넘을 거예요!', `FemaleText_loc4`='米诺鱼？海里到处都是米诺鱼！有上亿条呢！', `FemaleText_loc5`='小魚?海裡到處都是小魚!有上億條呢!', `FemaleText_loc7`='¿Una sardinilla? ¡Los océanos están llenos de ellas! ¡Podría haber hasta cien millones de sardinillas ahí fuera!' WHERE `ID`=11042;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 맞다!', `MaleText_loc4`='正是！', `MaleText_loc5`='完全正確!', `MaleText_loc7`='¡Exacto!' WHERE `ID`=11043;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='...', `MaleText_loc4`='……', `MaleText_loc5`='...', `MaleText_loc7`='...', `FemaleText_loc1`='...', `FemaleText_loc4`='……', `FemaleText_loc5`='...', `FemaleText_loc7`='...' WHERE `ID`=11044;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 생각해도 정말 기발한 발상이었지... 절대 그 물고기를 찾지 못할 것이다. 하지만 발견될 경우를 대비해 그 작은 물고기에게 약간 특별한 능력을 주었느니라.', `MaleText_loc4`='这是个天才的想法，我知道……它永远都不会被找到的。为了确保这一点，我赋予了这条米诺鱼某些特殊的能力。', `MaleText_loc5`='這是個天才的想法，我知道...它永遠都不會被找到的。為了確保這一點，我賦予了這條小魚某些特殊的能力。', `MaleText_loc7`='Qué genio, ya lo sé... Nunca nadie la encontrará pero, en caso de que así sea, le concedí a la sardinilla algunos poderes especiales.' WHERE `ID`=11045;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='작은 물고기에게 홀의 파편을 달아 주고 이곳과 동부 왕국 사이의 바다에 풀어놓았다는 말이오? 게다가 그 물고기에게 특별한 능력이 있다고?', `MaleText_loc4`='你把那东西绑到一条米诺鱼身上，然后将那条鱼放到这片大陆与东部王国之间的水域中，而且这条鱼拥有特殊的能力？', `MaleText_loc5`='你把那東西交給一條小魚，然後將那條小魚放到這片大陸與東部王國之間的水域中，而且這條小魚擁有特殊的能力?', `MaleText_loc7`='¿Le colocaste la pieza a la sardinilla y después la soltaste en algún lugar en las aguas del mar entre estas costas y los Reinos del Este? ¿Y esa sardinilla tiene poderes especiales?', `FemaleText_loc1`='작은 물고기에게 홀의 파편을 달아 주고 이곳과 동부 왕국 사이의 바다에 풀어놓았다는 말입니까? 게다가 그 물고기에게 특별한 능력이 있다고요?', `FemaleText_loc4`='你把那东西绑到一条米诺鱼身上，然后将那条鱼放到这片大陆与东部王国之间的水域中，而且这条鱼拥有特殊的能力？', `FemaleText_loc5`='你把那東西交給一條小魚，然後將那條小魚放到這片大陸與東部王國之間的水域中，而且這條小魚擁有特殊的能力?', `FemaleText_loc7`='¿Le colocaste la pieza a la sardinilla y después la soltaste en algún lugar en las aguas del mar entre estas costas y los Reinos del Este? ¿Y esa sardinilla tiene poderes especiales?' WHERE `ID`=11046;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇다. 내 말을 경청했구나! 나의 피조물인 이 작은 물고기는 정말 무섭고도 귀여운 녀석이지. 나는 휴식을 취할 때면 운 나쁜 낚시꾼들이 떠오르곤 하지.그들은 어쩌다 운이 나빠 이 작은 물고기를 만나 통째로 잡혀먹혔지. 모두 깜짝 놀랐을 것이다!$B$B<웃음을 터뜨리는 아주어고스>', `MaleText_loc4`='没错。你一直在认真听我说话！在我创造的生物当中，这条米诺鱼算得上是一个相当可怕的家伙了。每当我放松休息的时候，我就喜欢想象那些不幸的渔民，想象他们碰到这条鱼，然后被完全吞掉的样子。我敢打赌他们会对此惊讶万分的！$B$B<艾索雷葛斯大笑起来。>', `MaleText_loc5`='沒錯。你一直在認真聽我說話!在我創造的生物當中，這條小魚算得上是一個相當可怕的傢伙了。每當我放鬆休息的時候，我就喜歡想像那些不幸的漁民，想像他們碰到這條小魚，然後被完全吞掉的樣子。我敢打賭他們會對此驚訝萬分的!$B$B<艾索雷葛斯大笑著。>', `MaleText_loc7`='Eso es. ¡Ya lo has oído! Esa sardinilla es en realidad una criatura atroz que yo mismo creé. Para relajarme, suelo pensar en los pescadores que se hayan topado con esta sardinilla y que hayan acabado en su estómago. ¡Apuesto a que se quedaron perplejos!$B$B<Azuregos se ríe.>' WHERE `ID`=11047;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주어고스, 당신 미쳤군.', `MaleText_loc4`='你疯了。', `MaleText_loc5`='你瘋了。', `MaleText_loc7`='Estás loco.', `FemaleText_loc1`='아주어고스, 당신 미쳤군요.', `FemaleText_loc4`='你疯了。', `FemaleText_loc5`='你瘋了。', `FemaleText_loc7`='Estás loco.' WHERE `ID`=11048;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='평범한 생명체가 나 같은 천재의 행동은 이해할 수 없을 때가 많은 게지, 이해한다. 자, 이제 홀의 파편에 대해 다시 얘기해 볼까? 홀의 파편을 원한다면, 그리고 그 조각을 찾느라 앞으로 만 년을 허비하고 싶지 않다면 내 말을 귀담아 듣도록 하여라.', `MaleText_loc4`='天才总是被人误解，$R。关于节杖碎片……如果你想要很快得到那块碎片，而不是耗费数万年时间盲目寻找的话，就要仔细听好了。', `MaleText_loc5`='天才通常都被誤解，$r。現在，關於權杖裂片...如果你想要裂片而且不希望花下一個一萬年去尋找，你就必需仔細聽著。', `MaleText_loc7`='Los genios somos unos incomprendidos, $r. Entonces, en cuanto al fragmento de cetro... Si quieres ese fragmento pero no estás dispuesto a pasarte los próximos diez mil años buscándolo, tendrás que escuchar con atención.' WHERE `ID`=11049;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경청하도록 하겠소.', `MaleText_loc4`='我在全神贯注地听你说呢。', `MaleText_loc5`='我洗耳恭聽。', `MaleText_loc7`='Soy todo oídos.', `FemaleText_loc1`='네, 경청하죠.', `FemaleText_loc4`='我在全神贯注地听你说呢。', `FemaleText_loc5`='我洗耳恭聽。', `FemaleText_loc7`='Soy toda oídos.' WHERE `ID`=11050;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아케이나이트 부표라는 말을 기억해라.', `MaleText_loc4`='四个字：奥金鱼漂。', `MaleText_loc5`='四個字:奧金浮標。', `MaleText_loc7`='Tres palabras: boya de arcanita.' WHERE `ID`=11051;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠, 또 듣게 되는군.', `MaleText_loc4`='再说一遍？', `MaleText_loc5`='再說一次。', `MaleText_loc7`='Explícate.', `FemaleText_loc1`='들은 적이 있어요.', `FemaleText_loc4`='再说一遍？', `FemaleText_loc5`='再說一次。', `FemaleText_loc7`='Explícate.' WHERE `ID`=11052;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무튼 좋다... 넌 아케이나이트 부표를 만들어 바다 속에 던져야 한다. 그러면 분출되는 마력에 의해 내 작은 물고기가 이끌려 올 것이다. 그 녀석이 부표 가까이 오면... 꽝! 신비한 힘이 폭발하여 그녀석을 원래 모습으로 되돌릴 것이니라. 그리고 한 가지 더, 너는 넵튤론의 분노를 살 수도 있고 그렇지 않을 수도 있다. 확률은 반반이다.', `MaleText_loc4`='好吧……你需要制作一个奥金鱼漂，把它放进海水中。米诺鱼会被奥金鱼漂所吸引，当它接近鱼漂时——砰！奥金鱼漂将释放出神秘的力量，使它现出原形。不过这么一来，你有可能招致耐普图洛斯的仇恨，几率大概是50%吧。', `MaleText_loc5`='沒錯...你要做一個奧金浮標並把它放進海裡。我的小魚會被奧金浮漂所吸引，當它接近魚漂時─砰!奧金浮漂將釋放出神秘的力量，使它現出原形。不過這麼一來，你有可能招致奈普圖隆的仇恨，機率大概是50%吧。', `MaleText_loc7`='A ver... Tienes que fabricar una boya de arcanita y soltarla en el océano. Mi sardinilla se sentirá atraída por sus emanaciones mágicas. Cuando se encuentre cerca de la boya, ¡BLUM! Explotará proyectando una enorme cantidad de energía arcana, revelando la localización de la sardinilla. Aunque también es posible que despiertes la ira de Neptulon. Yo diría que hay un 50 por ciento de probabilidad.' WHERE `ID`=11053;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠소. 일단 정리해 보도록 합시다. 아나크로노스가 당신의용군단에게 맡긴 홀의 파편을 당신이 직접 만든 작은 물고기에게 달아 놓았는데, 인제 와서 제게... 그 뭐더라... 아케이나이트 부표인가 뭔가 하는 걸 만들어 그 물고기를 원래 모습으로 되돌려야 한단 말이오? 그리고 정령 군주의 분노를 사게 될 수도 있다고? 내가 뭐 빼먹은 거라도 있소? 그리고 이 일은 아마 윤년에 한 번 찾아오는 일식 중에 알몸으로 해야 한다지?', `MaleText_loc4`='好吧，让我们打开天窗说亮话吧。你把阿纳克洛斯交给你们蓝龙军团保管的节杖碎片给了某条你造出来的米诺鱼；现在你希望我制造一个……奥金鱼漂什么的玩意，用它来追踪你的那条鱼？另外这还可能引发元素领主的愤怒？我说漏了什么没有？或许我得找个闰年，在日食时分，赤身裸体地帮你干这件事儿？', `MaleText_loc5`='好，讓我先弄清楚。你把權杖裂片委託給你的安納克羅斯，叫他把裂片放你製作的小魚身上。然後現在你要我去做一個...一個奧金浮標之類的東西...讓你的小魚現形?而且還有可能引起元素之王的憤怒?我有漏掉什麼東西嗎?或許我應該連衣服都不要穿，在日蝕、閏年的時候去?', `MaleText_loc7`='Vale, a ver si lo he entendido bien. ¿Le pusiste el fragmento de cetro que Anacronos confió a tu Vuelo a una sardinilla creada por ti y ahora esperas que fabrique una... una boya de arcanita o algo así... para que la sardinilla salga de su escondrijo? ¿Y seguramente provocar la ira de un señor elemental? ¿Se me ha pasado algo? Igual tengo que hacerlo desnudo durante un eclipse solar en un año bisiesto...', `FemaleText_loc1`='알겠습니다. 제가 정리해 보죠. 아나크로노스가 당신의용군단에게 맡긴 홀의 파편을 당신이 직접 만든 작은 물고기에게 달아 놓았는데, 인제 와서 제게... 그 뭐더라... 아케이나이트 부표인가 뭔가 하는 걸 만들어 그 물고기를 원래 모습으로 되돌려야 한단 말입니까? 그리고 정령 군주의 분노를 사게 될 수도 있다고요? 제가 뭐 빼먹은 거라도 있나요? 그리고 이 일은 아마 윤년에 한 번 찾아오는 일식 중에 알몸으로 해야 한다죠?', `FemaleText_loc4`='好吧，让我们打开天窗说亮话吧。你把阿纳克洛斯交给你们蓝龙军团保管的节杖碎片给了某条你造出来的米诺鱼；现在你希望我制造一个……奥金鱼漂什么的玩意，用它来追踪你的那条鱼？另外这还可能引发元素领主的愤怒？我说漏了什么没有？或许我得找个闰年，在日食时分，赤身裸体地帮你干这件事儿？', `FemaleText_loc5`='好，讓我先弄清楚。你把權杖裂片委託給你的安納克羅斯，叫他把裂片放你製作的小魚身上。然後現在你要我去做一個...一個奧金浮標之類的東西...讓你的小魚現形?而且還有可能引起元素之王的憤怒?我有漏掉什麼東西嗎?或許我應該連衣服都不要穿，在日蝕、閏年的時候去?', `FemaleText_loc7`='Vale, a ver si lo he entendido bien. ¿Le pusiste el fragmento de cetro que Anacronos confió a tu Vuelo a una sardinilla creada por ti y ahora esperas que fabrique una... una boya de arcanita o algo así... para que la sardinilla salga de su escondrijo? ¿Y seguramente provocar la ira de un señor elemental? ¿Se me ha pasado algo? Igual tengo que hacerlo desnuda durante un eclipse solar en un año bisiesto...' WHERE `ID`=11054;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장군 라작스를 해치웠다. 안도로브가 또 한 번 승리했노라.', `MaleText_loc4`='拉贾克斯将军死了，安多洛夫将军的又一次胜利。', `MaleText_loc5`='拉賈克斯將軍死了，安多洛夫將軍的又一次勝利。', `MaleText_loc7`='El general Rajaxx ha sido capturado. Apúntale otra victoria a Andorov.' WHERE `ID`=11055;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필멸의 존재여, 난 네가 나를 조롱하고 있다는 것을 모를 정도로 어리석지는 않다. 그러나 사실이다. 너의 말은 대부분 맞다만 옷은 아무리 많이 입어도 상관없느니라.', `MaleText_loc4`='如果我不明事理的话，我会认为你是在嘲笑我，凡人。但是，那基本是最正确的做法，不过你得把全身裹起来。', `MaleText_loc5`='如果我不夠了解的話我會以為你在嘲笑我，凡人;但是，那基本是最正確的做法，不過你得把全身裹起來。', `MaleText_loc7`='Si no lo supiera pensaría que te estabas burlando de mí, mortal. Pero sí, es más o menos así. Aunque puedes dejarte la ropa puesta.' WHERE `ID`=11056;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋소! 그럼 감히 여쭙겠소. 아케이나이트 부표는 어떻게 하면 만들 수 있게 되어 있소이까?', `MaleText_loc4`='好吧！我斗胆问一句，我怎么才能弄到奥金鱼漂呢？', `MaleText_loc5`='很好!現在，容我發問，我需要協助取得奧金浮標嗎?', `MaleText_loc7`='¡MUY BIEN! Y, si puedo preguntar, ¿cómo se supone que voy a conseguir una boya de arcanita?', `FemaleText_loc1`='좋습니다! 그럼 감히 여쭙겠습니다. 아케이나이트 부표는 어떻게 하면 만들 수 있게 되어 있나요?', `FemaleText_loc4`='好吧！我斗胆问一句，我怎么才能弄到奥金鱼漂呢？', `FemaleText_loc5`='很好!現在，容我發問，我需要協助取得奧金浮標嗎?', `FemaleText_loc7`='¡MUY BIEN! Y, si puedo preguntar, ¿cómo se supone que voy a conseguir una boya de arcanita?' WHERE `ID`=11057;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타나리스에 있는 내 오랜 친구인 나라인 수스팬시에게 이 장부를 가지고 가라. 아주 무서운 심령술사이지만 뛰어난 기술자이기도 하지! 그라면 이 장부를 해석할 수 있을 것이다.$B$B이것이 내가 할 수 있는 최소한의 일이니 내게 감사할 필요는 없다, $n.$B$B잘 가거라!', `MaleText_loc4`='将这个账本交给我在塔纳利斯的老朋友。他名叫纳瑞安，是个精神极度癫狂的伟大技师！他应该能读懂这东西。$B$B不用谢谢我，$n。这是我唯一能做的。$B$B祝你好运！', `MaleText_loc5`='將這個帳本交給我在塔納利斯的老朋友。他名叫納里安·柔想，是個精神極度癲狂的偉大工程師!他應該能讀懂這東西。$B$B不用謝我，$n。這是我唯一能做的。$B$B祝你好運!', `MaleText_loc7`='Llévale este libro a un viejo conocido mío en Tanaris. Su nombre es Narain Sabelotodo. ¡Como físico es malísimo pero es un ingeniero increíble! Él será capaz de darle sentido a todo eso.$B$BNo me des las gracias, $n. Es lo menos que podía hacer.$B$B¡Que tengas un buen día!' WHERE `ID`=11058;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇지만...', `MaleText_loc4`='但是……', `MaleText_loc5`='可是...', `MaleText_loc7`='Pero...', `FemaleText_loc1`='그렇지만...', `FemaleText_loc4`='但是……', `FemaleText_loc5`='可是...', `FemaleText_loc7`='Pero...' WHERE `ID`=11059;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 이미 작별 인사를 했다!', `MaleText_loc4`='我刚才说过再见了吧？', `MaleText_loc5`='我說你好!', `MaleText_loc7`='¡QUE TENGAS UN BUEN DÍA, HE DICHO!' WHERE `ID`=11060;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='필멸의 존재여, 부디 조심하세요. 당신보다 더 강한 존재들도 죽음을 피하지 못한 곳에 가게 될 것이니...', `FemaleText_loc4`='当心点，凡人。那些强大的生物就是在此地葬生的。', `FemaleText_loc5`='當心點，凡人。那些強大的生物就是在此地葬生的。', `FemaleText_loc7`='Ve con cuidado mortal. Muchos seres de gran poder encontraron aquí la muerte.' WHERE `ID`=11061;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천 년 전, 흐르는 모래의 전쟁이 끝났을 때 아나크로노스와 스태그헬름이 안퀴라즈를 봉쇄하는 동안, 우리 혈족 중 세 명이 자신을 희생하여 퀴라지를 이 전당 안에 가두었습니다.$B$B우리는 언젠가 스카라베 성벽이 무너지면 메리스라, 아리고스 그리고 캘레스트라즈를 구하자고 서로 맹세했습니다.$B$B드디어 성벽이 무너져... 우리가 온 것입니다.', `MaleText_loc4`='一千年前，阿纳克洛斯和鹿盔封印安其拉大门时，三位族人牺牲了自己的性命，将其拉虫人禁锢在这些大墙内，流沙之战宣告结束。$B$B他们曾立下誓言，一旦甲虫之墙开启，他们就将召唤麦琳瑟拉、阿瑞苟斯和凯雷斯特拉兹。$B$B因此……我们来了。', `MaleText_loc5`='一千年前，流沙之戰結束，在安納克羅斯和鹿盔封住安其拉大門時，我們的三位族人犧牲了自己，將其拉蟲人禁錮在這些大牆內。$B$B我們曾立下誓言，一旦甲蟲之牆開啟，就要找到麥琳瑟拉、亞雷戈斯和凱雷斯塔茲。$B$B而它真的發生了...因此我們來了。', `MaleText_loc7`='Hace mil años, cuando la guerra del Mar de Dunas llegó a su fin, tres de los nuestros sacrificaron sus vidas y retuvieron a los qiraji en el interior de estos muros mientras Anacronos y Corzocelada sellaban Ahn''Qiraj.$B$BTodos nosotros juramos volver a por Merithra, Arygos y Caelestrasz si algún día el Muro del Escarabajo se derrumbaba.$B$BY así fue... aquí estamos.' WHERE `ID`=11062;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아제로스를 구해주지 않겠나?', `MaleText_loc4`='你难道不应该马上动身去拯救世界吗？', `MaleText_loc5`='你不是要拯救世界嗎?', `MaleText_loc7`='¿No deberías estar salvando el mundo?' WHERE `ID`=11063;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<개봉하지 않은 봉투를 이마에 붙이고 있는 나라인>$B$B뭘까... 으음... 벨벳!$B$B맞죠?$B$B배운 전문 기술을 취소하려고 이곳에 온 거라면, 저 위에 있는 책을 이용하도록 하세요...$B$B<''왕초보를 위한 예언 완전정복''을 가리키는 나라인>', `MaleText_loc4`='<纳瑞安将一封未打开的信贴到他的前额。>$B$B这是什么……嗯……天鹅绒！$B$B是吗？$B$B如果你来这里是为了遗忘某个专业技能专精以便重新选择，就用那边的书……', `MaleText_loc5`='<納里安將一封未打開的信貼到他的前額。>$B$B這是什麼...嗯...天鵝絨!$B$B是嗎?$B$B如果你想重新學習交易技能，就翻翻那本書吧...$b$b<納里安指著「新手的預言入門」。>', `MaleText_loc7`='<Narain coloca un sobre cerrado sobre su frente.>$B$BQué es... Mmmm... ¡Terciopelo!$B$B¿Tengo razón? $B$BSi estás aquí para intentar volver a aprender un oficio, usa ese libro de ahí...$B$B<Narain señala "Adivinar el futuro para torpes".' WHERE `ID`=11064;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쉿, 말하지 마세요! 파멸의 인도자 때문에 여기 온 거죠?!? 그래... 맞아... 아닌가! 음, 아닌 것 같네요.$B$B뭘 도와드릴까요?$B$B배운 전문 기술을 취소하려고 이곳에 온 거라면, 저 위에 있는 책을 이용하도록 하세요...$B$B<''왕초보를 위한 예언 완전정복''을 가리키는 나라인>', `MaleText_loc4`='别说话！让我猜猜！你是为灰烬使者而来的吗？！对……呃……不对！不好意思。$B$B我能帮你什么忙吗，$R？$B$B如果你来这里是为了遗忘某个专业技能专精以便重新选择，就用那边的书……', `MaleText_loc5`='不要告訴我!噓!你是為灰燼使者而來的嗎?!?對...呃...不對!不好意思。$B$B我能幫你什麼忙嗎，$r?$B$B如果你想重新學習交易技能，就翻翻那本書吧...$b$b<納里安指著「新手的預言入門」。>', `MaleText_loc7`='¡No me lo digas! ¡Shhh! ¿Estás aquí por la espada Crematoria? Sí... Sí... ¡No! Me he equivocado.$B$B¿En qué puedo ayudarte, $r?$B$BSi estás aquí para intentar volver a aprender un oficio, usa ese libro de ahí...$B$B<Narain señala "Adivinar el futuro para torpes".' WHERE `ID`=11065;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말만 하시라고요! 난 은퇴한 기술자이자 최고의 예언자, 나라인 수스팬시입니다! 난 아직 일어나지 않은 당신의 미래를 알려 줄 수 있답니다!$B$B배운 전문 기술을 취소하려고 이곳에 온 거라면, 저 위에 있는 책을 이용하도록 하세요...$B$B<''왕초보를 위한 예언 완전정복''을 가리키는 나라인>', `MaleText_loc4`='纳瑞安为您效劳！退隐的工程学专家和占卜大师！我敢打包票！$B$B如果你来这里是为了遗忘某个专业技能专精以便重新选择，就用那边的书……', `MaleText_loc5`='納里安·柔想為您效勞!退隱的工程學專家和占卜大師!我敢打包票!$B$B如果你想重新學習交易技能，就翻翻那本書吧...$b$b<納里安指著「新手的預言入門」。>', `MaleText_loc7`='¡Narain Sabelotodo, a su servicio! ¡Ingeniero retirado y maestro adivino! ¡Puedo adivinar tu futuro incluso antes de que ocurra!$B$BSi estás aquí para intentar volver a aprender un oficio, usa ese libro de ahí...$B$B<Narain señala "Adivinar el futuro para torpes".' WHERE `ID`=11066;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간 낭비할 가치도 없는 놈들!', `MaleText_loc4`='你真烦人，$n。', `MaleText_loc5`='你不值得我浪費時間，$n!', `MaleText_loc7`='¡No perderé mi tiempo con ustedes, $n!' WHERE `ID`=11067;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$C|1이여;여;, 그대가 가야 할 길은 저와 다릅니다. 훈련을 할 수 있는 다른 곳을 찾아보십시오.', `MaleText_loc4`='你所选择的道路和我的不一样。$c，你必须去别的地方训练。', `MaleText_loc5`='我們所選擇的道路不同。你必須要到別處接受訓練，$C。', `MaleText_loc7`='Tu camino y el mío son distintos. Debes buscar otro instructor, $c.', `FemaleText_loc1`='$C|1이여;여;, 그대가 가야 할 길은 저와 다릅니다. 훈련을 할 수 있는 다른 곳을 찾아보세요.', `FemaleText_loc4`='你所选择的道路和我的不一样。$c，你必须去别的地方训练。', `FemaleText_loc5`='我們所選擇的道路不同。你必須要到別處接受訓練，$C。', `FemaleText_loc7`='Tu camino y el mío son distintos. Debes buscar otro instructor, $c.' WHERE `ID`=11068;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련을 받고 싶습니까?', `MaleText_loc4`='你想要进行训练吗？', `MaleText_loc5`='你需要訓練嗎?', `MaleText_loc7`='¿Buscas instrucción?', `FemaleText_loc1`='훈련을 받고 싶으세요?', `FemaleText_loc4`='你想要进行训练吗？', `FemaleText_loc5`='你需要訓練嗎?', `FemaleText_loc7`='¿Buscas instrucción?' WHERE `ID`=11069;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사제의 길을 배우러 여기 오셨다면 최선을 다해 가르쳐 드리겠습니다.', `MaleText_loc4`='我会以牧师的方式来训练你，如果那是你到这里来的原因的话。', `MaleText_loc5`='我會以牧師方式來訓練你，如果那是你來這裡的原因。', `MaleText_loc7`='Hacer lo que mí poder para instruir tú en las costumbres sacerdotales, si eso es por lo que tú estar aquí.', `FemaleText_loc1`='사제의 길을 배우러 여기 오셨다면 최선을 다해 가르쳐 드리지요.', `FemaleText_loc4`='我会以牧师的方式来训练你，如果那是你到这里来的原因的话。', `FemaleText_loc5`='我會以牧師方式來訓練你，如果那是你來這裡的原因。', `FemaleText_loc7`='Hacer lo que mí poder para instruir tú en las costumbres sacerdotales, si eso es por lo que tú estar aquí.' WHERE `ID`=11071;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사제 훈련을 받으러 왔습니다.', `MaleText_loc4`='我需要牧师训练。', `MaleText_loc5`='我需要牧師訓練。', `MaleText_loc7`='Necesito instrucción de sacerdote.', `FemaleText_loc1`='사제 훈련을 받으러 왔어요.', `FemaleText_loc4`='我需要牧师训练。', `FemaleText_loc5`='我需要牧師訓練。', `FemaleText_loc7`='Necesito instrucción de sacerdote.' WHERE `ID`=11072;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도적 훈련을 받으러 왔습니다.', `MaleText_loc4`='我需要潜行者训练。', `MaleText_loc5`='我需要盜賊訓練。', `MaleText_loc7`='Necesito instrucción como pícaro.', `FemaleText_loc1`='도적 훈련을 받으러 왔어요.', `FemaleText_loc4`='我需要潜行者训练。', `FemaleText_loc5`='我需要盜賊訓練。', `FemaleText_loc7`='Necesito instrucción como pícaro.' WHERE `ID`=11073;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; $n|1을;를; 노려봅니다!', `MaleText_loc4`='%s凝视着$n！', `MaleText_loc5`='%s凝視著$n!', `MaleText_loc7`='¡%s mira a $n!' WHERE `ID`=11074;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헤헤헤, 잘 지냈나? 이 펠레케이키 생각에 자네가 날 아주 많이 도와줄 거 같아. 우린 안퀴라즈 전쟁에 대비해 엄청난 양의 화염초 꽃잎이 필요해. 호드에서는 ''이봐, 펠레케이키! 자네는 신속히 $2051w개의 화염초 꽃잎을 구해와''라고 말했지.$B$B이제 이 펠레케이키가 자네에게 말하겠는데, 내게 화염초 꽃잎이 $2050w개 밖에 없네. 하지만 자네가 금방 모아주겠지?', `MaleText_loc4`='哈哈哈，你过得怎么样。你可帮了比雷凯基的大忙。我们需要大量的火焰花。他们说，嘿，比雷凯基，你得马上集齐$2051w份火焰花。到目前为止他只收集到$2050w个，但是你能很快帮我们完成任务，是吗？', `MaleText_loc5`='哈哈哈，怎麼樣老兄。你可幫了比雷凱基的大忙。我們需要大量的火焰花。他們說，嘿，比雷凱基，你得馬上收集$2051w份火焰花。$B$B到目前為止他只收集到$2050w份，但是你能很快幫我們完成任務，是嗎老兄?', `MaleText_loc7`='Eh, ¿cómo va, colega? Tú vas a ayudar a Pele''keiki en asunto importante que él piensa. Necesitamos mogollón de flores de fuego para estar preparados para la guerra de Ahn''Qiraj. La Horda dijo, "Pele''keiki, consíguenos $2051w pétalos de fuego ahora mismo".$B$BPele''keiki te dice ahora, él solamente tiene $2050w flores de fuego pero tú añadirás, ¿verdad?' WHERE `ID`=11075;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='펠레케이키가 직접 나선다 해도 불가능할지 모른다고 생각했지만 호드가 전쟁에서 필요로 하는 화염초 꽃잎을 모두 모았네. 펠레케이키가 생각할 때는 말이야... 자네 스스로 부지런하다고 생각한다면, 여기 있는 다른 이들을 도와주는 게 좋겠어. 자네 도움이 필요한 일이 분명 많이 있을 걸세.', `MaleText_loc4`='比雷凯基知道收集火焰花的任务非常艰巨，也许连他自己都做不到，但是我们已经集齐部落所需的火焰花了。如果你不想无所事事的话，就去帮帮别人吧。这儿一定有人需要帮助。', `MaleText_loc5`='比雷凱基知道收集火焰花的任務非常艱鉅，也許連他自己都做不到，但是我們已經集齊部落所需的火焰花了。如果你不想無所事事的話，就去幫幫別人吧。這兒一定有人需要幫助。', `MaleText_loc7`='Pele''keiki sabe, parece imposible incluso para él pero nosotros conseguir todas esas flores de fuego que la Horda quiere para la guerra. Si tienes ganas, Pele''keiki piensa que podrías ayudar a los otros. Seguro que tienen muchas cosas que tú tendrás que conseguir para ellos.' WHERE `ID`=11076;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋아, 자네가 우릴 도와줄 수 있을 거란 얘기는 들었으니까 내 말 잘 듣도록. 지금 상황은 이렇다네. 나의 임무는 다가오는 안퀴라즈 전쟁에 대비해 $2055w개의 보라 연꽃을 모으는 거라네. 지금까지 $2054w개 모았어.$B$B사실 밖에 나가 보라 연꽃을 채집하는 일은 자네 같은 모험가들이 해주어야지. 나는 여기 남아 보라 연꽃을 잘 관리하고, 실리시드를 비롯해 우리를 기다리고 있을 미지의 적을 상대로 보라 연꽃의 새롭고 독창적인 용도를 연구해야 하니까.', `FemaleText_loc4`='啊，你来了。我被告知在这儿等候帮助，请仔细听我说。目前的状况是：安其拉之战即将展开，我奉命收集$2055w份紫莲花，现在已经收集到$2054w份了。事实上，收集紫莲花的工作只能交给你和那些愿意帮助我的人，因为我必须在这儿做好紫莲花的入库存储工作，并研究它的新用途，以便对抗异种虫和安其拉高墙后的神秘生物。', `FemaleText_loc5`='啊，你在這啊。我被告知在這兒等候幫助，所以聽仔細了。情況是這樣:我接到任務要為安其拉之戰收集$2055w份紫蓮花。目前為止我們有$2054w份。$B$B事實上進入戰場和收集花朵要靠你和像你這樣的人。我需要在這兒做好紫蓮花的入庫存儲工作，並研究它的新用途，以便對抗異種蟲和安其拉高牆後的神秘生物。', `FemaleText_loc7`='Ah, aquí estás. Me dijeron que recibiría ayuda, así que escucha con atención. La situación es la siguiente: me han encomendado que reúna $2055w lotos cárdenas en vista de la guerra que se avecina en Ahn''Qiraj. Hasta la fecha tenemos $2054w.$B$BDe hecho, está en tus manos y en las de los tuyos ir al campo y recolectar más flores. Yo tengo que permanecer aquí para comprobar que se guardan debidamente y para descubrir nuevas y creativas aplicaciones para usarlas contra los silítidos y lo que sea que nos espera ahí fuera.' WHERE `ID`=11077;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='필요한 보라 연꽃은 모두 모았다네. 나는 연구를 계속해야 하니 다른 이에게 가서 도움이 필요하지는 않는가 알아보도록. 우리에게 낭비할 시간 따위는 없어!', `FemaleText_loc4`='我们已经集齐紫莲花了，$C。去问问其他人吧，他们或许需要你的帮助。别打扰我的研究工作。没多少时间可以浪费了！', `FemaleText_loc5`='我們已經有足夠的紫蓮花了，$c。去問問別人是否需要你的幫忙，讓我好好研究一下。不要浪費時間了!', `FemaleText_loc7`='No tenemos sitio para más lotos cárdenos, $c. Ve y pregunta a alguno de los otros si necesitan tu ayuda, y déjame para que pueda seguir con mis investigaciones. ¡No hay tiempo que perder!' WHERE `ID`=11078;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$c|1이여;여;, 안퀴라즈 전쟁에 필요한 질긴 가죽 수집 일을 도우러 오셨지요? 좋습니다. 보시다시피 전 $2066w장 모았습니다. 하지만 필요한 수량은 모두 $2067w장이랍니다. 정말 질긴 가죽이 많이도 필요하지요, 친구. 당신의 손칼이 날카롭기를... 질긴 가죽은 전쟁에서 승리를 위해 꼭 필요한 여러 물건을 만드는 온갖 용도에 쓰일 겁니다.', `FemaleText_loc4`='你是来帮助我们收集重皮的吗？很好，很好。你看，我已经收集到$2066w块重皮了，总的需求量是$2067w。我的朋友，这儿有很多皮可以剥，希望你的小刀足够锋利。重皮的用途很广，包括在战争打响之后修补地精飞艇。', `FemaleText_loc5`='你是為了安其拉之戰收集重皮而來這裡的，是嗎，$c?很好，很好。如你所見我已經收集了$2066w塊，但是我們總共需要$2067w塊。那需要很多剝皮技巧的，朋友，我希望你的小刀夠鋒利。皮革在戰場上會拿來做很多作戰裝備並保証我們作戰成功。', `FemaleText_loc7`='Estás aquí para ayudar en la recogida de pieles de cuero pesado para la campaña de Ahn''Qiraj, ¿no es cierto, $c? Bien, bien. Como puedes comprobar, he reunido $2066w pero vamos a necesitar $2067w en total. Pues queda mucho que desollar, $gamigo:amiga;. Así que espero que tengas bien afilado el cuchillo. El cuero tendrá múltiples usos en la fabricación de pertrechos y asegurará nuestro éxito.' WHERE `ID`=11079;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 당신의 마음은 고맙지만 이미 필요한 만큼의 질긴 가죽은 모두 모았답니다. 하지만, 당신의 손칼은 아직 녹슬지 않았을 테지요. 그걸로 다른 물자를 모으는 이들을 도울 수 있을 것 같은데, 당신 생각은 어떤가요? 한번 생각해보십시오.', `FemaleText_loc4`='啊，你心肠真好，但是我们已经集齐备战所需的重皮了。我想你的剥皮小刀还很锋利吧，或许你可以四下看看其他人是否需要帮助。祝你好运！', `FemaleText_loc5`='啊，你真是太貼心了，但是我們已經有了作戰所需的重皮。我想你的小刀應該還很鋒利吧。或許你可以幫助其他人收集東西?祝你好運!', `FemaleText_loc7`='Ah, eres muy amable pero ya tenemos todas las pieles de cuero pesado que necesitamos. Pero supongo que tu cuchillo todavía está afilado. ¿Por qué no lo utilizas para ayudar a los demás en sus trabajos de recogida de material? ¡Que te diviertas!' WHERE `ID`=11080;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이곳에는 말로 표현할 수 없을 만큼 무서운 공포의 존재가 도사리고 있습니다. 필멸의 존재여, 모든 이들이 알고 있듯이 크툰과 그의 숭배자들은 자연을 위협하는 정도가 아니라 아제로스를 완전히 파괴해 버릴 수 있는 존재예요.$B$B천 년 전 메리스라는 캘레스트라즈, 아리고스와 함께 자신을 희생했죠. 그들 또한 이러한 조짐을 알고 있었기 때문이었어요. 우리가 여기까지 온 이유는 그들을 구하기로 한 맹세 때문이기도 하지만 무슨 일이 있어도 크툰을 저지해야만 하기 때문이에요!', `FemaleText_loc4`='凡人，这儿充斥着一种难以言说的恐怖。克苏恩和他的追随者们不仅公然藐视自然的力量，他们的存在更预示着艾泽拉斯的毁灭。$B$B一千年前，麦琳瑟拉、凯雷斯特拉兹和阿瑞苟斯都牺牲了自己以保全这个世界。我们来这里不仅仅是要报仇，还因为我们必须阻止克苏恩！', `FemaleText_loc5`='凡人，這兒充斥著一種難以形容的恐怖。克蘇恩和他的追隨者們不僅公然藐視自然的力量，他們的存在更預言著艾澤拉斯的毀滅。$B$B一千年前，麥琳瑟拉、凱雷斯塔茲和亞雷戈斯都犧牲了自己以保全這個世界。我們來這裡不僅僅是要報仇，還因為我們必須阻止克蘇恩!', `FemaleText_loc7`='Una atroz amenaza habita este lugar, mortal. C''Thun y sus devotos no solo son una afrenta para la naturaleza, sino que su existencia presagia destrucción para Azeroth.$B$BMerithra sacrificó su vida mil años atrás junto con Caelestrasz y Arygos pues ya lo sabían. Hemos venido debido al juramento que hicimos de volver a por ellos pero también porque hay que acabar con C''Thun.' WHERE `ID`=11081;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='록타르! $c, 자네에게 긴히 할 말이 있네! 우리는 안퀴라즈에서 곧 시작될 전쟁에 대비해야 한다네. 나는 여기서 두꺼운 가죽을 최대한 많이 모아야 해. 지금까지 우리가 모은 가죽은 $2070w장인데 대족장님께서는 총 $2071w장을 모으라고 지시하셨지. 자네도 보다시피 가죽이 조금 모자라는군.', `FemaleText_loc4`='$C，我有个重要的消息！安其拉即将爆发一场战争，我们需要为此做准备。我是来收集厚皮的，现在我们已经收集到$2070w块厚皮了，但是酋长要求我收集$2071w块。你看，我就差那么一点了。', `FemaleText_loc5`='為了部落 ，$c，我有重要的資訊!安其拉有場戰爭即將來臨，我們需要為此做準備。我在這裡收集所有能到手的厚皮。現在我們有$2070w塊，但是大酋長要我收集$2071w塊。你也知道，我仍有一些不足。', `FemaleText_loc7`='Lok''tar, $c. ¡Tengo información importante! Se avecina una guerra en Ahn''Qiraj y debemos estar preparados. Yo estoy recogiendo todas las pieles de cuero grueso que puedo. Ahora mismo tenemos $2070w pero el Jefe de Guerra me ha encargado que reúna $2071w. Como puedes comprobar, voy un poco escasa.' WHERE `ID`=11082;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='두꺼운 가죽을 더 가지고 온 것이라면 미안하게 됐네. 너무 늦었어. 필요한 두꺼운 가죽을 모두 모았거든. 하지만 떠나기 전에 여기 있는 다른 이들에게 한번 가보는 것이 어떻겠나? 전쟁 물자를 확보하기 위해 자네 도움이 있어야 하는 이들이 있을 걸세.', `FemaleText_loc4`='你有多余的厚皮？很抱歉你来晚了。我们已经集齐备战所需的厚皮了，但是在你离开之前，不妨问问这儿的其他人。或许有人需要你的帮助。', `FemaleText_loc5`='如果你有更多的厚皮，我很抱歉你來晚了。我們已經有所需的數量了，但是在你走之前可以去問問其他人嗎?應該還有一些人需要你協助他們收集東西。', `FemaleText_loc7`='Si traes cuero grueso siento decirte que llegas demasiado tarde. Ya tenemos todo el necesario pero, antes de irte, pregunta a los demás. Seguro que alguien todavía necesita tu ayuda con los trabajos de recogida de material.' WHERE `ID`=11083;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 반갑네. 자네가 안퀴라즈 전쟁 준비에 관한 좋은 소식을 가져다줄 거라 믿네. 난 호드를 위해 튼튼한 가죽을 모으는 일에 자원했다네. 내게 가장 적합한 일이라고 생각했기 때문이지. 자네도 날카롭게 벼린 손칼을 괜히 썩혀두지 말게.$B$B튼튼한 가죽에 대해 말하자면 $2074w장이 필요한데 지금까지 $2073w장 모았다네.', `MaleText_loc4`='你好，$C。我想你一定是来帮助我们进行备战工作的。我负责为部落收集硬甲皮，我认为这任务简直非我莫数。不要低估锋利的剥皮小刀的作用。$B$B我们已经收集到$2073w块硬甲皮了，总的需求量是$2074w。', `MaleText_loc5`='你好，$c。我相信你帶來了關於安其拉之戰準備工作的好消息。我負責為部落收集硬甲皮;這是個我認為只有我能勝任的任務。千萬別低估了銳利小刀的功用。$B$B至於硬甲皮，我們目前已經有$2073w塊，總共需要$2074w塊。', `MaleText_loc7`='Hola, $c. Confío en que traigas buenas noticias en referencia a los preparativos para la guerra de Ahn''Qiraj. A mí me han pedido que me encargue de las pieles de cuero basto para la Horda, una tarea para la que considero que estoy excepcionalmente cualificado. Nunca subestimes la utilidad de un cuchillo bien afilado.$B$BEn cuanto a las pieles, ahora mismo tenemos $2073w de las $2074w que son necesarias.' WHERE `ID`=11084;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='인정이 많은 $c|1이로군;로군;. 날 도우려고 칼날을 갈아왔다는 것도 잘 알겠네. 하지만 유감스럽게도 우리는 필요한 만큼의 튼튼한 가죽을 모두 모았다네. 그렇지만 전쟁 물자 수집에 자네의 도움이 필요한 곳이 또 있을 걸세. 이곳을 한번 둘러보게나.', `MaleText_loc4`='真可惜，你本来有机会磨亮你的小刀，为我弄些皮来的。但是我们已经集齐硬甲皮了，$C。你可以问问其他人，看看他们是否需要帮助。', `MaleText_loc5`='真可惜，你本來有機會磨亮你的小刀，為我弄些皮來的。但是我們已經集齊硬甲皮了，$C。你可以問問其他人，看看他們是否需要幫助。', `MaleText_loc7`='¡Qué pena! Apuesto a que has afilado tu cuchillo para cortar algunas pieles para mí pero, por desgracia, ya hemos reunido todas las pieles de cuero basto necesarias, $c. Sin embargo, haz algo útil y ve a preguntar a los demás si necesitan ayuda en sus trabajos de recogida de material.' WHERE `ID`=11085;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='바다 속은 아주 평온해요.', `FemaleText_loc4`='我发现大海是如此平静。', `FemaleText_loc5`='我發現海底非常平靜。', `FemaleText_loc7`='El fondo marino me resulta muy apacible.' WHERE `ID`=11086;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다시 만나 정말 반갑군요, $n! 나의 사랑하는 노움씨에게 제 편지를 전해 주셔서 얼마나 감사한지 모른답니다.$B$B노래 하나 들려드릴까요? 거친 바다를 항해할 때 부르면 여행이 한결 편해질 거예요!', `FemaleText_loc4`='很高兴再见到你，$n！你替我带信给亲爱的小侏儒，我真的很感谢你。$B$B你想听一首歌吗？它或许能使你的航海之旅变得轻松一些！', `FemaleText_loc5`='能再見到你真好，$n!你替我帶信給親愛的小地精，我真的很感謝你。$B$B你想不想聽首歌?這會讓你在大海中艱難的旅行輕鬆許多!', `FemaleText_loc7`='¡Es maravilloso volver a verte, $n! No sé cómo agradecerte que le hayas entregado el mensaje a mi querido gnomo.$B$B¿Te apetece escuchar una canción? ¡Así el viaje por estos peligrosos mares se hará más corto!' WHERE `ID`=11087;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그거 정말 멋지겠는데요! 감사합니다, 메리디스.', `MaleText_loc4`='那真是太好了！谢谢你。', `MaleText_loc5`='那真是太好了!謝謝你，米莉蒂絲。', `MaleText_loc7`='¡Eso sería estupendo! Gracias, Meridith.', `FemaleText_loc1`='그거 정말 멋지겠는데요! 감사합니다, 메리디스.', `FemaleText_loc4`='那真是太好了！谢谢你。', `FemaleText_loc5`='那真是太好了!謝謝你，米莉蒂絲。', `FemaleText_loc7`='¡Eso sería estupendo! Gracias, Meridith.' WHERE `ID`=11088;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말 멋진 노래죠, 그렇지 않나요?', `FemaleText_loc4`='很动听的歌，不是吗？', `FemaleText_loc5`='很動聽的歌，不是吧?', `FemaleText_loc7`='Una canción preciosa, ¿no crees?' WHERE `ID`=11089;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 만나서 반갑네. 우리는 다가올 안퀴라즈 전쟁에 필요한 물자를 모으고 있는데 자네의 도움이 필요하네. 내가 맡은 일은 응급치료 물품 중에서 양모 붕대를 대량 모으는 것이라네. 지금 정확하게 $2079w개 가지고 있는데 총 $2080w개가 필요하다네.', `MaleText_loc4`='啊，$C，很高兴见到你。我们正在为安其拉之战收集物资，当然，我们需要你的帮助。我得收集大量的急救物品，主要是绒线绷带。我已经收集到$2079w根绷带了，总的需求量是$2080w。', `MaleText_loc5`='啊，$c，很高興見到你。我們這裡需要協助收集安其拉的作戰物資。我負責收集大量的急救物品，主要是絨線繃帶。我已經有一些了，現在有$2079w個繃帶，但我的總需要是要收集$2080w個。', `MaleText_loc7`='Ah, $c, me alegro de verte. Necesitamos ayuda con la recolección de provisiones en vista de la inminente guerra en Ahn''Qiraj. Me han pedido que haga muchos botiquines de primeros auxilios y el elemento principal que necesito son vendas de lana. Ya tengo algunas, $2079w para ser exactos, pero necesito alcanzar las $2080w.' WHERE `ID`=11090;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='관심을 가져줘서 고맙네. 하지만 이미 전쟁에 필요한 양모 붕대를 모두 모았다네. 주위를 한번 둘러보게. 자네 도움이 필요한 이가 많이 있을 거야.', `MaleText_loc4`='感谢你对我的关心，但是我已经集齐战争所需的绒线绷带了。我建议你四下看看，也许其他人需要你的帮助。', `MaleText_loc5`='感謝你對我的關心，但是我已經有所有需要的絨線繃帶了。不過我建議你去四處問問;這裡有很多人可能會需要你的幫助。', `MaleText_loc7`='Gracias por tu interés, pero ya tengo todas las vendas de lana necesarias para la campaña. Aun así, te sugiero que preguntes por ahí pues hay muchos que todavía podrían necesitar tu ayuda.' WHERE `ID`=11091;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요. $c님, 때맞춰 오셨군요. 간단히 본론부터 말씀드리겠어요. 우리는 안퀴라즈 전쟁에서 필요 이상의 사상자를 내지 않기 위해 필요한 물자를 모으고 있답니다.$B$B제 임무는 $2086w개의 마법 붕대를 모으는 것인데 지금까지 $2085w개를 모았답니다. 당신께서 도움의 손길을 베푸실 수 있을는지요?', `FemaleText_loc4`='你好，$C，很高兴你露面了。我长话短说，我们正在为安其拉之战收集战争物资。我需要收集$2086w根魔纹绷带。到目前为止，我们已经收集到$2085w根了。你愿意帮忙吗？', `FemaleText_loc5`='你好，$c，很高興你露面了。我長話短說，我們正在收集安其拉之戰的物資。我們不希望有更多的傷亡，可以嗎?我要負責協調收集$2086w個魔紋布繃帶。目前我們已有$2085w個。可以幫忙嗎?', `FemaleText_loc7`='Hola, $c. ¡Qué bien que aparezcas! Iré al grano: estamos reuniendo provisiones para la campaña de Ahn''Qiraj. No queremos que haya más heridos de los necesarios, ¿no es así? Tengo la responsabilidad de coordinar la recolección de $2086w vendas de tejido mágico. Hasta la fecha hemos recogido $2085w. ¿Te importaría echar una mano?' WHERE `ID`=11092;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='미안해서 어쩌죠? 필요한 만큼의 마법 붕대를 모두 모은 것 같은데... 경매장에 파는 건 어때요? 하지만, 그전에 당신처럼 착한 분께는 다른 이들을 찾아가 보라고 권하고 싶네요. 도움의 손길을 기다리고 있을지도 모르니까요.', `FemaleText_loc4`='真不幸，似乎我们已经集齐到备战所需的魔纹绷带了，或许你可以去拍卖所卖掉你手头多余的绷带。在你离开之前，不妨跟其他收集者谈谈。或许他们需要你的帮助。', `FemaleText_loc5`='真是不巧;我們已經有了所有需要的魔紋布繃帶。或許你可以把它們放到拍賣場?但是在你離開之前，做個好$g男孩:女孩;問問其他收集者。他們可能有一些需要你做的小差事。', `FemaleText_loc7`='¡Qué lástima! Parece que ya hemos conseguido todas las vendas de tejido mágico necesarias. Quizás puedas venderlas en la casa de subastas. Pero antes de irte, sé $gbueno: buena; y pregunta a los demás que están aquí. Seguro que tienen algún encargo para ti.' WHERE `ID`=11093;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비밀은 무덤까지 가지고 갈 것이다!', `MaleText_loc4`='我会把我的秘密带进坟墓！', `MaleText_loc5`='我會帶著我的秘密進入墳地!', `MaleText_loc7`='¡Me llevaré mis secretos a la tumba!' WHERE `ID`=11094;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대지모신께서 보살펴주시지만 $c들도 가끔은 살아남기 위해 약간의 도움이 필요한 경우가 있죠. 그래서 저는 다가올 안퀴라즈 전쟁에 대비해 룬무늬 붕대를 모으고 있어요. 모두 $2090w개를 모아야 하는데 지금까지 우리가 모은 것은 $2089w개예요.', `FemaleText_loc4`='大地母亲为我们提供了生存物资，但是有时候，士兵们需要一些额外的帮助才能存活。安其拉之战迫在眉睫，我正在收集符文布绷带。到目前为止，我们已经收集到$2089w根符文布绷带，总的需求量是$2090w。', `FemaleText_loc5`='大地之母供養我們，但是有時候，一名$c需要額外的幫助才能生存。因此，我正在收集所有安其拉之戰需要的符文布繃帶。目前我們已經收集了$2089w個符文布繃帶，總共要$2090w個。', `FemaleText_loc7`='La Madre Tierra nos ofrece todos sus recursos pero, en ocasiones, $gun:una; $c necesita un poco de ayuda extra para poder sobrevivir. Por ello, estoy recogiendo todas las vendas de paño rúnico que puedo en vista de la guerra que se avecina en Ahn''Qiraj. Hasta el momento, hemos reunido $2089w de un total de $2090w.' WHERE `ID`=11095;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='붕대가 더 필요하지는 않은지 물어봐 주셔서 고마워요. 하지만 전쟁에 필요할 것으로 예상되는 룬무늬 붕대는 모두 모은 것 같아요. 주변에서 전쟁 물자를 수집하고 있는 이들 중에 도움이 필요한 이들을 당신에게 부탁드려도 될까요? 선조의 가호가 있기를...', `FemaleText_loc4`='感谢你对我们的关心，$C。但是我们已经集齐备战所需的符文布绷带了。你可以问问其他的收集者，为他们提供帮助。愿你的祖先保佑你。', `FemaleText_loc5`='感謝你對我們的關心，$c。但是我們已經集齊備戰所需的符文布繃帶。我能請你去四處問問別人是否需要你的幫助嗎?願祖先守護著你。', `FemaleText_loc7`='Muchas gracias por preguntar, $c. Sin embargo, parece que ya hemos reunido todas las vendas de paño rúnico que consideramos necesarias para la guerra. ¿Te puedo sugerir que preguntes por ahí a los demás y que les ofrezcas tu ayuda si la precisan? Que los antepasados velen por ti.' WHERE `ID`=11096;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='크르르, $r|1이로군;로군;. 뭘 원해? 오, 안퀴라즈 전쟁에 필요한 늑대 살코기 스테이크 때문에 여기 온 게 틀림없군그래! 자네가 들은 얘기는 사실일세. 나는 늑대 살코기 스테이크를 모으고 있어. 그런데 무슨 볼일이지? 혹시 내게 줄 신선한 늑대 살코기 스테이크가 있나? 모두 $2096w개면 되겠는데 지금까지 우리가 모은 것은 $2095w개로군.', `FemaleText_loc4`='呃，你想要什么，$R？哦，你一定是为瘦狼排来的吧。没错，你的消息没错，我正在收集瘦狼排。你有吗？我只需要$2096w块，现在我们已经收集到$2095w块了。', `FemaleText_loc5`='嗯，你想做什麼，$r?喔，你一定是為了即將到來的安其拉之戰所需的瘦狼排而來。是的，你沒聽錯，我正在收集它們，怎麼了嗎?你有新鮮的肉排要給我?我們需要$2096w塊，目前有$2095w塊。', `FemaleText_loc7`='Grrr, ¿qué quieres, $r? ¡Oh! Debes de venir por los filetes de lobo magro para la inminente guerra de Ahn''Qiraj. Sí, has oído bien. Yo me encargo de recogerlos. ¿Qué pasa? ¿Tú traes un buen montón para mí? Solamente necesito $2096w y parece ser que ahora mismo tenemos $2095w.' WHERE `ID`=11097;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='호드에 필요한 늑대 살코기 스테이크를 모두 모은 것 같군. 그들은 여기서 모은 늑대 살코기 스테이크를 실리더스의 세나리온 요새로 수송할 수 있도록 포장해달라고 했지. 자네 말인데... 이곳에는 아직 맡은 물자를 다 모으지 못한 이들이 있을 거야. 어서 가보도록.', `FemaleText_loc4`='似乎我们已经集齐了部落所需的瘦狼排。他们让我把这些瘦狼排打包运送到希利苏斯的塞纳里奥要塞去，这儿似乎还有其他人在设法收集各种物资。去找找他们吧。', `FemaleText_loc5`='看來我們已經達到部落要的瘦狼排數量了。他們要我打包這裡的狼排並送至希利蘇斯的塞納里奧城堡。但是看來其他人可能還在收集它們負責的東西。去問問他們。', `FemaleText_loc7`='Parece que tenemos tantos filetes de lobo magro como necesita la Horda. Me han ordenado que empaquete todo lo que tenemos aquí y que lo prepare para ser enviado al Fuerte Cenarion en Silithus. Pero parece que algunos todavía están recogiendo lo que sea que tengan que recoger. Ve a preguntarles.' WHERE `ID`=11098;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여보십시오, 전 호드에 필요한 전투 식량을 모으고 있습니다. 호드는 안퀴라즈의 사막에서 벌어질 대전쟁을 준비하고 있는데 내게는 점박이놀래기 구이 $2103w개를 모아달라고 했어요. 하지만 지금까지 우리가 모은 것은 $2102w개뿐입니다. 절 좀 도와주시겠습니까?', `MaleText_loc4`='嗨，我正在为部落收集食物。安其拉沙漠中即将发生一场恶战，我需要收集$2103w条斑点黄尾鱼。到目前为止，我们只有$2102w条。', `MaleText_loc5`='你好，我正為部落收集好吃的魚。他們正為沙漠的安其拉之戰作準備，要我幫他們收集$2103w條斑點黃尾魚。但是現在我們只有$2102w條。你來這裡幫助我們的嗎?', `MaleText_loc7`='Eh, yo cojo pececillos para la Horda. Ellos se preparan para gran guerra en el desierto de Ahn''Qiraj y me piden que coja $2103w serviolas moteadas para ellos. Pero ahora solamente tener $2102w. ¿Tú ayudas?' WHERE `ID`=11099;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 반갑습니다. 그런데 전쟁에 필요한 점박이놀래기 구이를 모두 모은 것 같아요. 근처의 다른 전쟁 물자를 모으고 있는 이들에게 가서 도움이 필요한지 물어보는 게 어떻겠습니까?', `MaleText_loc4`='嗨，$C。似乎我们已经集齐了战争所需的斑点黄尾鱼。或许你可以问问其他的收集者，看他们是否需要帮助。', `MaleText_loc5`='嗨，$c!看來我們已經收集到戰爭所需的斑點黃尾魚了。或許你可以去問問其他的收集者是否需要你的幫忙?', `MaleText_loc7`='¡Eh, $c! Parece que tenemos todas las serviolas moteadas que necesitaremos durante la guerra. ¿Por qué no preguntas a los demás que andan por ahí si necesitan tu ayuda?' WHERE `ID`=11100;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 평안하시오? 전쟁 물자 준비를 돕는 그대와 같은 분을 만나니 무척이나 반갑소이다. 이곳에서는 많은 이들이 중요한 시기를 대비하기 위해 다양한 물자를 수집하고 있소.$B$B난 안퀴라즈 전쟁에 참전할 병사들을 위해 훈제 연어 $2106w개를 모아 비축해두는 일을 맡았소이다. 마지막으로 수량을 확인했을 때가 $2105w개였지, 아마!', `MaleText_loc4`='你好，$C。你乐意帮助我们收集作战物资，这真好。收集者们在此收集多种物资储备。我负责收集$2106w条烤鲑鱼，供给参与安其拉之战的士兵们。目前我们已经收集到$2105w条了。', `MaleText_loc5`='你好，$c。很高興看到你願意幫忙戰事。這裡的收集者正在組織聚集不同的儲備物資，我們正準備迎戰。$B$B我負責收集$2106w條烤鮭魚，將它們儲存起來給安其拉的士兵們吃。上次我清點的時候，我們已收集了$2105w條。', `MaleText_loc7`='Saludos, $c. Me alegro de que quieras ayudar con la campaña. Los recolectores están organizando el almacenamiento de reservas de diversos productos para así estar preparados cuando llegue el momento.$B$BYo he de obtener $2106w salmones al horno para aquellos que luchen en Ahn''Qiraj. La última vez que los conté había $2105w.' WHERE `ID`=11101;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 물어봐 주니 고맙소만 우린 전쟁에 사용할 훈제 연어를 모두 모았소이다. 이곳에서 다른 전쟁 물자를 수집하는 이들에게 가보는 게 어떻겠소? 그대의 도움을 바라는 이들이 분명히 있을 것이오.', `MaleText_loc4`='谢谢你的关心，$C，但是我们已经集齐战争所需的烤鲑鱼了。或许你可以跟其他收集者谈谈，他们也许会需要你的帮助。', `MaleText_loc5`='謝謝你的關心，$c，但是我們已經有了所有需要的烤鮭魚了。或許你可以去問問其他的收集者;他們肯定會需要你的幫忙。', `MaleText_loc7`='Gracias por preguntar, $c, pero ya tenemos todos los salmones al horno que necesitaremos para la guerra. ¿Serías tan amable de preguntar a los demás recolectores? Seguro que necesitan tu ayuda con algo.' WHERE `ID`=11102;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게는 낭비할 시간이 없다. 안퀴라즈 전쟁을 준비해야 한다. 도와줄 생각이라면 화산 심장부에서 그을린 화산핵을 모아 와라. 모두 $2110w개를 모아야 하는데 지금까지 $2109w개를 모았다.', `MaleText_loc4`='我可没时间浪费，$C。安其拉之战迫在眉睫。我们正在收集来自熔火之心里面的熔火之石。我需要收集$2110w块，到目前为止已经有$2109w块了，你愿意帮忙吗？', `MaleText_loc5`='我可沒時間浪費，$c;還有安其拉戰役需要準備。如果你要幫忙的話，我們正在收集來自熔火之心裡面的熔火之石。我總共需要收集$2110w塊，到目前為止已經有$2109w塊了。', `MaleText_loc7`='No tengo tiempo que perder, $c; hay una guerra que preparar en Ahn''Qiraj. Si quieres ayudar, estamos recogiendo piedras nucleares abrasadas del Núcleo Fundido. Tengo que reunir $2110w en total y actualmente cuento con $2109w.' WHERE `ID`=11103;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드의 여러 길드가 힘을 모아 이미 이 일을 완수했다. 전쟁 물자를 만드는 데 필요한 그을린 화산핵을 모두 확보했단 말이다. 이곳에서 다른 물자를 모으고 있는 이들에게 도움이 필요한지 물어보도록.', `MaleText_loc4`='部落的各大公会齐心协力，终于完成了这项任务，$C。我们已经集齐了战争所需的熔火之石了。问问其他的收集者吧，或许他们需要帮助。', `MaleText_loc5`='部落的各大公會齊心協力，終於完成了這項任務，$C。我們已經集齊戰爭所需的熔火之石了。問問其他的收集者吧，或許他們需要幫助。', `MaleText_loc7`='Las hermandades de la Horda han trabajado codo con codo y ya han completado esta tarea, $c. Tenemos todas las piedras nucleares abrasadas necesarias para nuestros pertrechos. Haz algo de utilidad y pregunta a los demás recolectores si necesitan tu ayuda.' WHERE `ID`=11104;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해가 바뀌고 달빛이 환하게 비추는 시간이 왔도다.$B$B고대인이 깨어나면... 우리의 시간이다.', `MaleText_loc4`='新的一年来临了，月光洒满大地。$B$B这是属于我们的日子……远古的生命苏醒了。', `MaleText_loc5`='新的一年來臨了，月光灑滿大地。$B$B這是屬於我們的日子...遠古的生命甦醒了。', `MaleText_loc7`='Ha llegado la hora de un nuevo año y la luna brilla con fuerza.$B$BHa llegado la hora... de que los ancestros se despierten.' WHERE `ID`=11105;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어허, 옛 친구에게 인사도 안 할 셈인가, 나라인? 누구를 기다리고 있었나???', `MaleText_loc4`='纳瑞安，不给你的老朋友打声招呼吗？你在等谁呢？', `MaleText_loc5`='納里安，不給你的老朋友打聲招呼嗎?你在等誰呢?', `MaleText_loc7`='¿No saludas a tu viejo amigo, Narain? ¿¿¿A quién esperabas???' WHERE `ID`=11106;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 의심스러운 눈으로 당신을 쳐다봅니다.', `MaleText_loc4`='%s怀疑地看着你。', `MaleText_loc5`='%s懷疑地看著你。', `MaleText_loc7`='%s te observa con recelo.' WHERE `ID`=11107;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래... 날 속일 수 있다고 생각했었나, 그런 건가? 어디 한번 말해 보시지, 아제로스에서 지금까지 알려진 가장 위대한 범죄 주모자 나리...', `MaleText_loc4`='这么说……你觉得你能愚弄我，是吗？你没听说过艾泽拉斯最伟大的罪犯的名头吗？？？', `MaleText_loc5`='這麼說...你以為你可以騙的了我，是吧?你沒聽說過艾澤拉斯最偉大的犯罪首腦???', `MaleText_loc7`='Así que... pensabas que podrías engañarme, ¿no? ¿¿¿La mayor mente criminal que Azeroth jamás haya conocido???' WHERE `ID`=11108;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 네 변장을 한 눈에 알아봤다. 넘버투! 넘버투, 놈을 죽여라!', `MaleText_loc4`='我识破了你的伪装，$R。人造猿二号！上！', `MaleText_loc5`='我看穿了你的偽裝，$r。人造猿二號!上!', `MaleText_loc7`='Puedo ver más allá de tu disfraz, $r. ¡Número dos! ¡Número dos, dale muerte!' WHERE `ID`=11109;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽어라!', `MaleText_loc4`='杀呀！', `MaleText_loc5`='殺!', `MaleText_loc7`='¡MÁTALO!' WHERE `ID`=11110;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 오래전, 우리는 사냥으로 살아갔다. 우리는 영광을 위해, 명예를 위해 사냥을 했다...$B$B지금은 어떤가?', `MaleText_loc4`='在过去的岁月里，我们以狩猎为生。我们为了荣誉而狩猎……$B$B现在有什么不同吗？', `MaleText_loc5`='很久以前，我們以狩獵維生。我們為了光榮與榮耀而狩獵... $B$B現在一切都變了嗎?', `MaleText_loc7`='En tiempos remotos, vivíamos para la caza. La caza de gloria, de honor... $B$B¿Es que ahora es tan diferente?', `FemaleText_loc1`='아주 오래전, 우리는 사냥으로 살아갔다. 우리는 영광을 위해, 명예를 위해 사냥을 했다...$B$B지금은 어떤가?', `FemaleText_loc4`='在过去的岁月里，我们以狩猎为生。我们为了荣誉而狩猎……$B$B现在有什么不同吗？', `FemaleText_loc5`='很久以前，我們以狩獵維生。我們為了光榮與榮耀而狩獵... $B$B現在一切都變了嗎?', `FemaleText_loc7`='En tiempos remotos, vivíamos para la caza. La caza de gloria, de honor... $B$B¿Es que ahora es tan diferente?' WHERE `ID`=11111;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='세나리온 의회의 개들... 모두 해치워라!', `FemaleText_loc4`='塞纳里奥议会的走狗！杀光他们！', `FemaleText_loc5`='塞納里奧議會的走狗。殺了牠們!', `FemaleText_loc7`='Individuos del Círculo Cenarion. ¡Acaben con ellos!' WHERE `ID`=11112;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필멸의 존재여, 용언을 배우려는 너의 노력은 헛수고로 돌아갔다. 도대체 왜 고대 언어를 배우려고 하느냐? 정말 이해할 수가 없구나...', `MaleText_loc4`='凡人，你想要学习龙人语言，这简直是异想天开。为什么你想要学习这种古老的语言呢？真是不可理喻……', `MaleText_loc5`='凡人，你想要學習龍人語言，這簡直是異想天開。為什麼你想要學習這種古老的語言呢?真令人疑惑...', `MaleText_loc7`='Tu intento de aprender dracónico es inútil, mortal. ¿Y por qué ibas a querer hablar esta lengua antigua? Es realmente desconcertante...' WHERE `ID`=11113;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<아제로스를 위한 좋은 일에 이 책을 사용할 것!>', `MaleText_loc4`='<为了艾泽拉斯，拿上这本书吧！>', `MaleText_loc5`='<為了艾澤拉斯，拿著這本書吧!>', `MaleText_loc7`='<¡Coge este libro por el bien de Azeroth!>', `FemaleText_loc1`='<아제로스를 위한 좋은 일에 이 책을 사용할 것!>', `FemaleText_loc4`='<为了艾泽拉斯，拿上这本书吧！>', `FemaleText_loc5`='<為了艾澤拉斯，拿著這本書吧!>', `FemaleText_loc7`='<¡Coge este libro por el bien de Azeroth!>' WHERE `ID`=11114;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 파괴됩니다!', `MaleText_loc4`='%s被吞噬了！', `MaleText_loc5`='%s被吞噬了!', `MaleText_loc7`='¡Devoran a %s!', `FemaleText_loc1`='%s|1이;가; 파괴됩니다!', `FemaleText_loc4`='%s被吞噬了！', `FemaleText_loc5`='%s被吞噬了!', `FemaleText_loc7`='¡Devoran a %s!' WHERE `ID`=11115;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앞이... 앞이 흐릿해요, $n. 아무것도 보이지 않아요! 잠깐... 잠시만 기다려요. 아, 보입니다... 위빌 박사의 은신처가 보여요. 저긴... 그래요! 그가 책의 한 장을 쥐고 있는 게 분명해요!$B$B이걸 확대해서 좀 더 좋은 지점을 잡을 수 있는지 볼게요.$B$B<눈이 사시처럼 되고 있는 것 같은 나라인>$B$B알카즈 섬! 그 나쁜 녀석이 알카즈 섬에 있군요!', `MaleText_loc4`='啊……起雾了，$n。我什么都看不见！等等……等会儿。我看见……我看见维维尔的藏身之处。啊……没错！我相信书的一章就在他手中！$B$B让我调整一下望远镜，这样可以看得更清楚些。$B$B<纳瑞安都快变成对眼了。>$B$B奥卡兹岛！那家伙就在奥卡兹岛上！', `MaleText_loc5`='這...這霧好濃啊，$n。我什麼都看不見了!等...等等，我看到...我看到維維爾博士的藏身之處了。對...沒錯!我就知道他一定拿走了書的其中一章!$B$B讓我調整一下望遠鏡，這樣可以看得更清楚些。$B$B<納里安看的都快鬥雞眼了。>$B$B奧卡茲島!那邪惡的壞蛋就在奧卡茲島上!', `MaleText_loc7`='Hay... Hay niebla, $n. ¡No veo nada! Espera... Espera un minuto. Veo... Veo la guarida del doctor Weavil. Y... ¡SÍ! ¡Creo que sostiene un capítulo del libro!$B$BA ver si puedo ampliar la imagen.$B$B<Narain parece ponerse bizco.>¡La Isla de Alcaz! ¡Ese taimado hijo de goblin está en la Isla de Alcaz!' WHERE `ID`=11116;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 악마 녀석이 날 졸리게 만드는군...', `MaleText_loc4`='邪恶的力量让我昏昏欲睡……', `MaleText_loc5`='邪惡力量讓我想昏昏欲睡...', `MaleText_loc7`='El mal me da mucho sueño...' WHERE `ID`=11117;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 하품을 합니다.', `MaleText_loc4`='%s打着呵欠。', `MaleText_loc5`='%s打呵欠', `MaleText_loc7`='%s bosteza.' WHERE `ID`=11118;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='록타르, $r! 나는 호드 연합의 사절, 전투사령관 조그다. 내가 여기 배치된 이유는 위대한 호드의 안퀴라즈 전쟁 준비가 어떻게 진행되고 있는지 알려 주기 위함이다. 무엇이 알고 싶나?', `MaleText_loc4`='你好，$R。我是部落大使佐格将军。我是来向你通报部落关于安其拉一战的准备工作的进度的。你想知道什么？', `MaleText_loc5`='為了部落， $r。我是部落大使，佐格將軍。我是來向你通報部落關於安其拉之戰的準備工作進度的。你想知道什麼?', `MaleText_loc7`='Lok''tar, $r. Soy el general Zog, embajador de la Horda. Estoy aquí para informarte de los progresos realizados por la poderosa Horda en relación a la campaña de la guerra de Ahn''Qiraj. ¿Qué quieres saber?' WHERE `ID`=11119;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안퀴라즈 전쟁 준비가 무엇입니까?', `MaleText_loc4`='什么是安其拉作战物资？', `MaleText_loc5`='什麼是安其拉作戰物資?', `MaleText_loc7`='¿Qué es la campaña de Ahn''Qiraj?', `FemaleText_loc1`='안퀴라즈 전쟁 준비가 뭔가요?', `FemaleText_loc4`='什么是安其拉作战物资？', `FemaleText_loc5`='什麼是安其拉作戰物資?', `FemaleText_loc7`='¿Qué es la campaña de Ahn''Qiraj?' WHERE `ID`=11120;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 줄은 거의 찼군...', `MaleText_loc4`='这里几乎填满了……', `MaleText_loc5`='這裡幾乎填滿了...', `MaleText_loc7`='Esta línea es de relleno...' WHERE `ID`=11121;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금까지 호드는 금속 주괴들을 얼마나 모았습니까?', `MaleText_loc4`='到目前为止部落已经收集到多少金属锭了？', `MaleText_loc5`='目前為止部落總共收集了多少金屬錠?', `MaleText_loc7`='¿Cuántas barras de metal ha conseguido reunir la Horda hasta el momento?', `FemaleText_loc1`='지금까지 호드는 금속 주괴들을 얼마나 모았습니까?', `FemaleText_loc4`='到目前为止部落已经收集到多少金属锭了？', `FemaleText_loc5`='目前為止部落總共收集了多少金屬錠?', `FemaleText_loc7`='¿Cuántas barras de metal ha conseguido reunir la Horda hasta el momento?' WHERE `ID`=11122;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='금속 주괴들을 얼마나 모았냐고 물었나? 내가 마지막으로 확인한 결과는 다음과 같다. 호드에 필요한 구리 주괴는 $1998w개인데 $2018w개를 모았고, 주석 주괴는 $2006w개가 필요한데 $2005w개를 모았다. 그리고 미스릴 주괴는 $2009w개를 모아야 하는데 $2008w개를 모았다.', `MaleText_loc4`='你说有多少金属锭？我得到的最新消息是联盟已经收集到$2018w块铜锭、$2005w块锡锭和$2008w块秘银锭了，而总的需求量分别是$1998w、$2006w和$2009w。', `MaleText_loc5`='你說總共有多少金屬錠啊?依目前對局勢的最新了解，據我所知，部落已經收集了$2018w個銅錠、$2005w個錫錠以及$2008w個秘銀錠，總需求量分別是$1998w個銅錠$2006w個錫錠和$2009w個秘銀錠。', `MaleText_loc7`='¿Cuántas barras de metal dices? Lo último que he sabido es que la Horda ha reunido $2018w barras de cobre de las $1998w necesarias, $2005w barras de estaño de $2006w y $2008w barras de mitril de las $2009w que querían.' WHERE `ID`=11123;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금까지 호드는 약초를 얼마나 모았습니까?', `MaleText_loc4`='到目前为止部落已经收集到多少草药了？', `MaleText_loc5`='目前為止部落總共收集了多少草藥?', `MaleText_loc7`='¿Cuántas plantas ha conseguido reunir la Horda hasta el momento?', `FemaleText_loc1`='지금까지 호드는 약초를 얼마나 모았나요?', `FemaleText_loc4`='到目前为止部落已经收集到多少草药了？', `FemaleText_loc5`='目前為止部落總共收集了多少草藥?', `FemaleText_loc7`='¿Cuántas plantas ha conseguido reunir la Horda hasta el momento?' WHERE `ID`=11124;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 마지막으로 들은 바로는 평온초는 $2020w개가 필요한데 $2021w개를 모았고, 화염초는 $2051w개 중 $2050w개, 보라 연꽃은 $2055w개 중 $2054w개를 모았다고 한다.', `MaleText_loc4`='我得到的最后的消息称，部落已经收集到$2021w份宁神花、$2050w份火焰花和$2054w份紫莲花，而总的需求量分别是$2020w、$2051w和$2055w。', `MaleText_loc5`='我收到部落的最新情報，部落已經收集到$2021w份寧神花、$2050w份火焰花和$2054w份紫蓮花，而總需求量分別是$2020w份寧神花、$2051w份火焰花和$2055w份紫蓮花。', `MaleText_loc7`='Lo último que he sabido es que la Horda ha acumulado $2021w de $2020w flores de paz, $2050w de $2051w flores de fuego y $2054w de un total de $2055w lotos cárdenas.' WHERE `ID`=11125;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금까지 호드는 가죽을 얼마나 모았습니까?', `MaleText_loc4`='到目前为止部落已经收集到多少皮革了？', `MaleText_loc5`='目前為止部落總共收集了多少毛皮?', `MaleText_loc7`='¿Cuántas pieles de cuero ha conseguido reunir la Horda hasta el momento?', `FemaleText_loc1`='지금까지 호드는 가죽을 얼마나 모았나요?', `FemaleText_loc4`='到目前为止部落已经收集到多少皮革了？', `FemaleText_loc5`='目前為止部落總共收集了多少毛皮?', `FemaleText_loc7`='¿Cuántas pieles de cuero ha conseguido reunir la Horda hasta el momento?' WHERE `ID`=11126;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가죽 말인가? 그래, 방금 가죽에 대한 보고를 받았다. 호드에 필요한 질긴 가죽은 $2067w개인데 $2066w개를 모았다. 그리고 두꺼운 가죽은 $2071w개 중 $2070w개를 모았고, 튼튼한 가죽은 $2074w개 중 $2073w개를 모았다.', `MaleText_loc4`='皮革？哦，我刚收到消息。似乎部落已经收集到$2066w块重皮、$2070w块厚皮和$2073w块硬甲皮，而总的需求量分别是$2067w、$2071w和$2074w。', `MaleText_loc5`='皮革啊?是啊，我得到一些關於皮革的消息。部落已經收集到$2066w塊重皮、$2070w塊厚皮和$2073w塊硬甲皮，而總需求量分別是$2067w塊重皮、$2071w塊厚皮和$2074w塊硬甲皮。', `MaleText_loc7`='¿Pieles de cuero? Sí, tengo datos sobre eso. Parece que de las $2067w pieles de cuero pesado necesarias, la Horda ha conseguido $2066w. Además, también ha reunido $2070w pieles de cuero grueso de un total de $2071w y $2073w pieles de cuero basto de las $2074w necesarias.' WHERE `ID`=11127;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금까지 호드는 붕대를 얼마나 모았습니까?', `MaleText_loc4`='到目前为止部落已经收集到多少绷带了？', `MaleText_loc5`='目前為止部落總共收集了多少繃帶?', `MaleText_loc7`='¿Cuántas vendas ha conseguido reunir la Horda hasta el momento?', `FemaleText_loc1`='지금까지 호드는 붕대를 얼마나 모았나요?', `FemaleText_loc4`='到目前为止部落已经收集到多少绷带了？', `FemaleText_loc5`='目前為止部落總共收集了多少繃帶?', `FemaleText_loc7`='¿Cuántas vendas ha conseguido reunir la Horda hasta el momento?' WHERE `ID`=11128;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드는 엄청난 양의 붕대를 모으고 있다. 지금까지 양모 붕대는 $2080w개 중 $2079w개를 모았다. 마법 붕대는$2086w개 중$2085w개를 모았고, 룬무늬 붕대는 $2090w개 중 $2089w개를 모았다.', `MaleText_loc4`='部落正在收集绷带。到目前为止，我们已经收集到$2079w根绒线绷带、$2085w根魔纹绷带和$2089w根符文布绷带，而总的需求量分别是$2080w、$2086w和$2090w。', `MaleText_loc5`='部落正在儲備許多的繃帶。目前為止，我們已經收集到$2079w個絨線繃帶、$2085w個魔紋繃帶和$2089w個符文布繃帶，而總需求量分別是$2080w個絨線繃帶、$2086w個魔紋繃帶和$2090w個符文布繃帶。', `MaleText_loc7`='La Horda almacena una gran cantidad de vendas. Hasta ahora han reunido $2079w vendas de lana de un total de $2080w, $2085w vendas de tejido mágico de un total de $2086w y $2089w vendas de paño rúnico de un total de $2090w.' WHERE `ID`=11129;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금까지 호드는 식량을 얼마나 모았습니까?', `MaleText_loc4`='到目前为止部落已经收集到多少熟食了？', `MaleText_loc5`='目前為止部落總共收集了多少熟食?', `MaleText_loc7`='¿Cuántos productos cocinados ha conseguido reunir la Horda hasta el momento?', `FemaleText_loc1`='지금까지 호드는 식량을 얼마나 모았나요?', `FemaleText_loc4`='到目前为止部落已经收集到多少熟食了？', `FemaleText_loc5`='目前為止部落總共收集了多少熟食?', `FemaleText_loc7`='¿Cuántos productos cocinados ha conseguido reunir la Horda hasta el momento?' WHERE `ID`=11130;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='식량을 얼마나 모았는지 알고 싶다고 했나? 좋아. 마지막으로 들은 바에 의하면, 늑대 살코기 스테이크는 $2096w개 중 $2095w개가 준비됐다고 한다. 그리고 필요한 점박이놀래기 구이는 $2103w개 중 $2102w개, 훈제 연어는 $2106w개 중 $2105w개를 포장해 두었다고 한다.', `MaleText_loc4`='你想知道收集工作的进度吗？很好。我得到的最新消息称，部落已经收集到$2095w个瘦狼排、$2102w条斑点黄尾鱼和$2105w条烤鲑鱼，而总的需求量分别是$2096w、$2103w和$2106w。', `MaleText_loc5`='你想知道收集工作的進度嗎?很好。我得到的最新消息指出，部落已經收集到$2095w個瘦狼排、$2102w條斑點黃尾魚和$2105w條烤鮭魚，而總需求量分別是$2096w個瘦狼排、$2103w條斑點黃尾魚和$2106w條烤鮭魚。', `MaleText_loc7`='¿Te refieres a las raciones? Muy bien. Lo último que he sabido es que la Horda ha preparado $2095w filetes de lobo magro de un total de $2096w. También hemos embalado $2102w serviolas moteadas de un total de $2103w y $2105w salmones al horno de los $2106w necesarios.' WHERE `ID`=11131;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 밖에 묻고 싶은 게 더 있습니다.', `MaleText_loc4`='我想问问你别的事情。', `MaleText_loc5`='我還想問你關於其他的事。', `MaleText_loc7`='Quiero preguntarte algo más.', `FemaleText_loc1`='그 밖에 묻고 싶은 게 더 있어요.', `FemaleText_loc4`='我想问问你别的事情。', `FemaleText_loc5`='我還想問你關於其他的事。', `FemaleText_loc7`='Quiero preguntarte algo más.' WHERE `ID`=11132;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑네, $r $c! 나는 이곳에서 얼라이언스를 대표하여 사절을 맡고 있는 사령관 스트롱해머라고 하네. 얼라이언스의 안퀴라즈 전쟁 물자 수집 상황에 대해 궁금하다면 주저하지 말고 물어보게나.', `MaleText_loc4`='你好，$R$C。我是此地的联盟大使汉默·石锤。$G小伙子:姑娘;，如果你想要了解联盟战争物资的收集情况，问我好了。', `MaleText_loc5`='你好，$r$c。我是指揮官漢默·石錘，也是代表聯盟的大使。如果你對於聯盟收集作戰物資有任何問題$g小夥子:小姑娘;，不要猶豫儘管問吧。', `MaleText_loc7`='Saludos, $r $c. Soy el comandante Martillopujante, el embajador que representa aquí a la Alianza. Si tienes preguntas en referencia a los trabajos de recogida de material de la Alianza para la campaña de Ahn''Qiraj, no dudes en hacérmelas $gmuchacho: muchacha;.' WHERE `ID`=11133;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 줄은 거의 찼군...', `MaleText_loc4`='这里几乎填满了……', `MaleText_loc5`='這裡幾乎填滿了...', `MaleText_loc7`='Esta línea es de relleno...' WHERE `ID`=11134;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금까지 얼라이언스는 금속 주괴를 얼마나 모았습니까?', `MaleText_loc4`='到目前为止联盟已经收集到多少金属锭了？', `MaleText_loc5`='目前為止聯盟總共收集了多少金屬錠?', `MaleText_loc7`='¿Cuántas barras de metal ha conseguido reunir la Alianza hasta el momento?', `FemaleText_loc1`='지금까지 얼라이언스는 금속 주괴를 얼마나 모았나요?', `FemaleText_loc4`='到目前为止联盟已经收集到多少金属锭了？', `FemaleText_loc5`='目前為止聯盟總共收集了多少金屬錠?', `FemaleText_loc7`='¿Cuántas barras de metal ha conseguido reunir la Alianza hasta el momento?' WHERE `ID`=11135;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 좋은 질문이군. 내가 마지막으로 듣기로, 얼라이언스는 전쟁에 필요한 구리 주괴 $1998w개 중 $1997w개, 철 주괴 $2003w개 중 $2002w개, 그리고 토륨 주괴 $2012w개 중 $2011w개를 모았다네.', `MaleText_loc4`='问得好，$C。联盟共需要$1998w块铜锭、$2003w块铁锭和$2012w块瑟银锭。到目前为止，他们已经设法收集到$1997w块铜锭、$2002w块铁锭和$2011w块瑟银锭了。', `MaleText_loc5`='真是個好問題，$c。據我所知，聯盟總共需要$1998w塊銅錠、$2003w塊鐵錠和$2012w塊瑟銀錠。到目前為止，他們已經設法收集到$1997w塊銅錠、$2002w塊鐵錠和$2011w塊瑟銀錠了。', `MaleText_loc7`='Buena pregunta, $c. Los últimos datos que tengo indican que la Alianza ha conseguido fundir $1997w barras de cobre de un total de $1998w, $2002w barras de hierro de $2003w y $2011w barras de torio de las $2012w necesarias para la campaña.' WHERE `ID`=11136;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금까지 얼라이언스는 약초를 얼마나 모았습니까?', `MaleText_loc4`='到目前为止联盟已经收集到多少草药了？', `MaleText_loc5`='目前為止聯盟共收集了多少草藥?', `MaleText_loc7`='¿Cuántas plantas ha conseguido reunir la Alianza hasta el momento?', `FemaleText_loc1`='지금까지 얼라이언스는 약초를 얼마나 모았나요?', `FemaleText_loc4`='到目前为止联盟已经收集到多少草药了？', `FemaleText_loc5`='目前為止聯盟共收集了多少草藥?', `FemaleText_loc7`='¿Cuántas plantas ha conseguido reunir la Alianza hasta el momento?' WHERE `ID`=11137;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디 한 번 보세나. 여기 어디에 적어놓은 게 있을 텐데... 아, 여기 있군! 지금까지 얼라이언스는 필요한 갈래물풀 $2048w개 중 $2047w개, 보라 연꽃은 $2055w개 중 $2053w개, 그리고 아서스의 눈물은 $2058w개 중 $2057w개를 모았네.', `MaleText_loc4`='让我看看，让我看看。我有做过记录的。啊，找到了！到目前为止，联盟已经收集到$2047w份荆棘藻、$2053w份紫莲花和$2057w份阿尔萨斯之泪，而总的需求量分别是$2048w、$2055w和$2058w。', `MaleText_loc5`='我想想，我想想。我把它們放在這裡的某個地方。啊，沒錯，就在這裡!到目前為止，聯盟已經收集到$2047w份荊棘藻、$2053w份紫蓮花和$2057w份阿薩斯之淚，而總需求量分別是$2048w份荊棘藻、$2055w份紫蓮花和$2058w份阿薩斯之淚。', `MaleText_loc7`='A ver, a ver... Tengo esos datos en alguna parte. ¡Ah, sí! ¡Aquí están! Hasta la fecha, la Alianza ha reunido $2047w de las $2048w algas estranguladoras necesarias. Aquí dice también que tenemos $2053w lotos cárdenos de un total de $2055w y $2057w lágrimas de Arthas de las $2058w necesarias.' WHERE `ID`=11138;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금까지 얼라이언스는 가죽을 얼마나 모았습니까?', `MaleText_loc4`='到目前为止联盟已经收集到多少皮革了？', `MaleText_loc5`='目前為止聯盟總共收集了多少皮革?', `MaleText_loc7`='¿Cuántas pieles de cuero ha conseguido reunir la Alianza hasta el momento?', `FemaleText_loc1`='지금까지 얼라이언스는 가죽을 얼마나 모았나요?', `FemaleText_loc4`='到目前为止联盟已经收集到多少皮革了？', `FemaleText_loc5`='目前為止聯盟總共收集了多少皮革?', `FemaleText_loc7`='¿Cuántas pieles de cuero ha conseguido reunir la Alianza hasta el momento?' WHERE `ID`=11139;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그걸 물어보다니 참 재미있군. 가죽에 대한 정보를 방금 받았거든. 지금까지 얼라이언스는 얇은 가죽 $2061w개 중 $2060w개, 일반 가죽 $2064w개 중 $2063w개, 두꺼운 가죽 $2071w개 중 $2069w개를 모았네.', `MaleText_loc4`='嗯，这个问题很有趣……我收到的最新消息是，到目前为止，联盟已经收集了$2060w张轻皮、$2063w张中皮和$2069w张厚皮了，而总的需求量分别是$2061w、$2064w和$2071w。', `MaleText_loc5`='你問這個還真有趣...我有它們的最新消息。目前為止聯盟已經收集了$2060w張輕皮、$2063w張中皮和$2069w張厚皮了，而總需求量分別是$2061w張輕皮、$2064w張中皮和$2071w張厚皮。', `MaleText_loc7`='Tiene gracia que lo preguntes. Acabo de recibir las últimas cifras al respecto. Hasta ahora, la Alianza ha reunido $2060w pieles de cuero ligero de un total de $2061w, $2063w pieles de cuero medio de $2064w y $2069w pieles de cuero grueso de $2071w.' WHERE `ID`=11140;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금까지 얼라이언스는 붕대를 얼마나 모았습니까?', `MaleText_loc4`='到目前为止联盟已经收集到多少绷带了？', `MaleText_loc5`='目前為止聯盟總共收集了多少繃帶?', `MaleText_loc7`='¿Cuántas vendas ha conseguido reunir la Alianza hasta el momento?', `FemaleText_loc1`='지금까지 얼라이언스는 붕대를 얼마나 모았나요?', `FemaleText_loc4`='到目前为止联盟已经收集到多少绷带了？', `FemaleText_loc5`='目前為止聯盟總共收集了多少繃帶?', `FemaleText_loc7`='¿Cuántas vendas ha conseguido reunir la Alianza hasta el momento?' WHERE `ID`=11141;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='붕대라고 했나? 에... 그러니까, 마지막으로 들은 내용을 떠올려 보면 얼라이언스는 리넨 붕대 $2077w개 중 $2076w개, 비단 붕대 $2083w개 중 $2082w개, 룬무늬 붕대 $2090w개 중 $2088w개를 모은 것 같네.', `MaleText_loc4`='你是说绷带吗？哦，如果我没有记错的话，联盟已经收集到$2076w根亚麻绷带、$2082w根丝质绷带和$2088w根符文布绷带了，而总的需求量分别是$2077w、$2083w和$2090w。', `MaleText_loc5`='你說繃帶嗎?嗯，如果我沒記錯的話，聯盟已收集了$2076w個亞麻繃帶、$2082w個絲質繃帶和$2088w個符文布繃帶了，而總需求量分別是$2077w個亞麻繃帶、$2083w個絲質繃帶和$2090w個符文布繃帶。', `MaleText_loc7`='¿Has dicho vendas...? Sí, a ver, si la memoria no me falla parece que la Alianza ha obtenido $2076w vendas de lino de un total de $2077w, $2082w vendas de seda de $2083w y $2088w vendas de paño rúnico de $2090w.' WHERE `ID`=11142;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금까지 얼라이언스는 요리된 전투 식량을 얼마나 모았습니까?', `MaleText_loc4`='到目前为止联盟已经收集到多少熟食了？', `MaleText_loc5`='目前為止聯盟總共儲存了多少熟食?', `MaleText_loc7`='¿Cuántos productos cocinados ha conseguido reunir la Alianza hasta el momento?', `FemaleText_loc1`='지금까지 얼라이언스는 요리된 전투 식량을 얼마나 모았나요?', `FemaleText_loc4`='到目前为止联盟已经收集到多少熟食了？', `FemaleText_loc5`='目前為止聯盟總共儲存了多少熟食?', `FemaleText_loc7`='¿Cuántos productos cocinados ha conseguido reunir la Alianza hasta el momento?' WHERE `ID`=11143;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 질문을 들으니 뭘 좀 먹어야 할 것 같군... 듣자하니 얼라이언스가 지금까지 모은 전투 식량은 무지개날개다랑어 구이 $2093w개 중 $2092w개, 랩터 숯불구이는 $2099w개 중 $2098w개, 점박이놀래기 구이는 $2103w개 중 $2101w개가 준비되어 있다네. 실리더스의 세나리온 요새로 수송할 때까지 포장된 상태로 냉장고에 보관할 거라는군. 음...', `MaleText_loc4`='这倒提醒我了，我得去找点吃的。据说联盟已经收集到$2092w条彩鳍鱼、$2098w块烤迅猛龙肉和$2101w条斑点黄尾鱼，而总的需求量分别是$2093w、$2099w和$2103w。一旦收集完毕，这些食物就将被运往希利苏斯的塞纳里奥要塞。', `MaleText_loc5`='這倒提醒了我，我得趕快找點東西吃。至於聯盟烹煮了些什麼東西， 我聽說$2093w條彩鰭魚中已經有$2092w條被運走了。同時，$2099w塊烤迅猛龍肉中有$2098w塊，$2103w條斑點黃尾魚中也有$2101w條已準備好且已冷藏，等著送到希利蘇斯的塞納里奧城堡。', `MaleText_loc7`='Eso me recuerda que tengo que encontrar pronto algo de comer. En cuanto a lo que la Alianza ha estado cocinando, sé que se han embalado $2092w piezas de atún blanco arco iris de un total de $2093w. Además, se han preparado $2098w raptores asados de $2099w y $2101w serviolas moteadas de un total de $2103w que actualmente están almacenadas esperando ser enviadas hasta el Fuerte Cenarion en Silithus.' WHERE `ID`=11144;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 별빛은 다가올 시대에 희망과 힘의 등불이 될 새 길을 인도하고 있도다.', `MaleText_loc4`='星光指引着新的道路，未来燃起希望和力量的灯塔。', `MaleText_loc5`='這個時代的星光指引著新的道路，替未來燃起希望和力量的燈塔。', `MaleText_loc7`='Las estrellas de este tiempo están cambiando su trayectoria, faros de esperanza y fuerza para los años venideros.', `FemaleText_loc1`='지금 별빛은 다가올 시대에 희망과 힘의 등불이 될 새 길을 인도하고 있도다.', `FemaleText_loc4`='星光指引着新的道路，未来燃起希望和力量的灯塔。', `FemaleText_loc5`='這個時代的星光指引著新的道路，替未來燃起希望和力量的燈塔。', `FemaleText_loc7`='Las estrellas de este tiempo están cambiando su trayectoria, faros de esperanza y fuerza para los años venideros.' WHERE `ID`=11145;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하하! 얼라이언스는 이번 전쟁에 필요한 물자를 모두 모았습니다! 호드도 금방 우릴 따라잡겠지요?', `MaleText_loc4`='哈哈，$G小伙子:姑娘;！联盟已经集齐所有的战争物资了！或许部落得加把劲了。', `MaleText_loc5`='哈哈，$g小夥子:小姑娘;!聯盟已經集齊所有的戰爭物資了!或許部落很快就會趕上?', `MaleText_loc7`='¡Ja, $gmuchacho: muchacha;! ¡La Alianza ha reunido todo lo que necesitaba para comenzar la guerra! Puede que la Horda nos alcance pronto.' WHERE `ID`=11146;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모든 준비가 끝나고 이제 한판 붙을 일만 남았군요. 전쟁 물자를 모두 실리더스의 세나리온 요새로 수송 중인데 최소한 $2113w일 안에는 마지막 물자가 도착할 것입니다. 조만간 홀만 합쳐지면 드디어 전쟁이 시작되는 겁니다.', `MaleText_loc4`='时局紧张，所有的战争物资都在运往希利苏斯塞纳里奥要塞的途中，预计将在$2113w天内全部抵达。一旦有人修复节杖，离战争也就不远了。', `MaleText_loc5`='現在大勢已定，一切就緒。所有作戰物資正運往希利蘇斯的塞納里奧城堡，最少$2113w天就可以抵達。一旦有人修復權杖，戰爭也就離我們不遠了。', `MaleText_loc7`='Todo está listo pero el tiempo apremia. Todos los pertrechos están de camino al Fuerte Cenarion en Silithus y llegarán a su destino en menos de $2113w días. No debería tardar mucho más en reconstruirse el cetro y dar comienzo la guerra.' WHERE `ID`=11147;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이보시오, 당신 그거 알고 있소? 우리가 해냈소. 모든 전쟁 물자 수집이 완료되어 수송할 준비를 하고 있소. 이제 호드 쪽에서 일을 마치기만 기다리면 되지... 얼라이언스와 호드가 힘을 모아 공격하는 순간 안퀴라즈의 벌레들은 끝장나는 거요!', `MaleText_loc4`='嗯，嗯，你知道吗，我们成功了。所有的物资都已收集完毕，只等部落那些粗鲁的家伙们完成他们的任务了。到那时，我们就要跟安其拉的异种虫类开战了！', `MaleText_loc5`='太棒了，你知道嗎?我們成功了。所有物資都已收齊準備迎戰。我們現在只等粗魯的傢伙們完成他們的任務。到那時，我們就要跟安其拉的異種蟲類開戰了!', `MaleText_loc7`='Bueno, bueno... ¡tú qué sabrás lumbrera! Lo conseguimos. Todo está listo. Ahora solo nos queda esperar por esos patanes de la Horda y una vez que se organicen ¡a Ahn''Qiraj!' WHERE `ID`=11148;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야호, 끝났다! 모두 물자 수집을 완료했소. 그리고 일전에 말했듯이 수집한 전쟁 물자는 비행선에 실어 실리더스로 공수 중이지. 늦어도 $2113w일 안에는 마지막 물자가 도착할 거요. 수송이 완료되고 파편들을 모아 홀이 하나로 합쳐지면 더러운 벌레들과의 전쟁이 시작되는 거지. 병사들의 표현을 빌리자면 한마디로 이런 거요. ''보내 버려!''', `MaleText_loc4`='哈哈，一切准备就绪！收集工作结束了，物资将如约由地精飞艇运往希利苏斯。预计最后一批将在$2113w天内抵达。一旦节杖复原，与那些肮脏的虫子的战争也就开始了。现在，开始装运吧！', `MaleText_loc5`='唷呼!出發囉!收集工作結束了，收集工作結束了，物資將如約由地精飛艇運往希利蘇斯。預計最後一批將在$2113w天內抵達。一旦權杖復原，與那些骯髒蟲子的戰爭也就開始了。現在，開始裝運吧!', `MaleText_loc7`='¡Guau, allá vamos! Todo el mundo ha recogido todo y ya va en zepelín de camino a Silithus mientras hablamos. El último envío debería llegar en menos de $2113w días. Cuando todo esté allí y los fragmentos del cetro se hayan reunido, podrá dar comienzo la guerra contra esos sucios insectos. Como ellos dicen, "¡Despáchalo!"' WHERE `ID`=11149;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리의 자랑스러운 얼라이언스는 이미 전쟁에 필요한 모든 물자 수집을 끝냈어요. 이제 저 멍청한 호드가 일을 끝마치기를 기다리는 일만 남았네요.', `FemaleText_loc4`='似乎联盟已经集齐所有的战争物资了，现在我们只需等待那些可怜的部落完成他们的任务。', `FemaleText_loc5`='似乎聯盟已經集齊所有的戰爭物資了，現在我們只需等待那些可憐的部落完成他們的任務。', `FemaleText_loc7`='Parece que la Alianza ya ha conseguido recolectar todo lo necesario para la campaña. Ahora solo nos queda esperar que esas pobres criaturas de la Horda hagan lo mismo.' WHERE `ID`=11150;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요? 제가 들은 바로는 물자 수집이 완료되어 우리가 얘기한대로 모든 전쟁 물자를 실리더스로 수송 중이라고 하네요. 적어도 $2113w일 안에는 모두 보내야 한다는군요. 만반의 준비가 끝나면 흐르는 모래의 홀로 징을 울리고 진짜 전쟁을 시작할 수 있는 거죠.', `FemaleText_loc4`='你好，$C。我听说所有的物资都已经收集完毕，将如约运往希利苏斯。货物将在$2113w天内到达，在那之后，流沙节杖的持有者将敲响铜锣，战争也就开始了。', `FemaleText_loc5`='嗨，$c，我聽說所有的物資都已經收集完畢，將如約運往希利蘇斯。貨物將在$2113w天內到達。一旦準備就緒，就等著流沙權杖持有者敲響銅鑼。戰爭即將開始!', `FemaleText_loc7`='Hola, $c. Según mis datos, ya se ha reunido todo lo necesario y los pertrechos para la guerra están de camino a Silithus mientras hablamos. Debería estar todo allí en menos de $2113w días. Hecho esto, y una vez que se haya hecho sonar el gong utilizando el cetro del Mar de Dunas, la guerra podrá por fin comenzar.' WHERE `ID`=11151;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스에 필요한 모든 물자 수집이 완료된 것 같습니다. 지금은 호드가 준비를 끝내기만 기다리고 있습니다. 전 이제야 근처에 티굴과 폴로르의 아이스크림을 파는 곳이 있나 찾으러 갈 수 있겠네요.', `MaleText_loc4`='嗯，似乎我们已经集齐联盟所需的所有物资了，现在只等部落完成他们的任务了。我想我得看看这附近有没有提古勒和弗罗尔的冰淇淋卖……', `MaleText_loc5`='嗯，似乎我們已經集齊聯盟所需的所有物資了，現在只等部落完成他們的任務了。我想我得看看這附近有沒有賣提古勒和弗洛爾的冰淇淋...', `MaleText_loc7`='Bueno, parece que ya hemos reunido todo lo que la Alianza va a necesitar; ahora solo nos queda esperar por la Horda. Creo que no voy a tardar mucho en ir a buscar un helado Tigule y Foror por ahí.' WHERE `ID`=11152;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다 됐습니다. 양쪽 모두 물자 수집을 완료했어요. 현재 모든 물자를 실리더스로 수송하는 중이며 적어도 $2113w일 안에는 모두 보내야 한다는군요. 만반의 준비가 끝나고 누군가 흐르는 모래의 홀로 스카라베 제단의 징을 울리면 전쟁이 시작되는 겁니다.', `MaleText_loc4`='好极了，双方都完成了收集工作。现在这些物资都已经运往希利苏斯了，所有的货物预计将在$2113w天内抵达。一旦准备就绪，就会有人使用流沙节杖敲响甲虫之台的铜锣，战争也就开始了！', `MaleText_loc5`='好了，雙方都準備好了。現在作戰物資正運往希利蘇斯，最少$2113w天就可抵達。一旦準備就緒，就會有人拿著流沙權杖敲響甲蟲之台的銅鑼。立即開戰!', `MaleText_loc7`='Eso es, ambas partes han reunido todo lo necesario. Ahora mismo todo está de camino a Silithus y debería llegar a su destino en menos de $2113w días. Hecho esto, y una vez que alguien haga sonar el gong situado en el Estrado del Escarabajo utilizando el cetro del Mar de Dunas, ¡la guerra dará comienzo!' WHERE `ID`=11153;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무법항에 온 걸 환영하네, 친구. 우리 마을에 머무는 동안 아무 일 없이 즐겁게 지내길 바라네. 꼭 아무 일도 없이... 꼭! 마실 것이 필요한가? 일꾼이 필요한가? 말만 하게. 얼마든지 제공해 줄 테니까.$B$B그건 그렇고... 스팀휘들 무역회사의 충복인 이 몸께서 뭘 도와주면 되겠나? 아, 이렇게 말하는 게 더 낫겠군. 날 위해 자네는 뭘 해 줄 수 있나?', `MaleText_loc4`='伙计，欢迎来到藏宝海湾。希望你在这儿度过一段快乐而……嗯，平静的日子。如果你口渴的话，我们这儿有很多饮料；如果你担惊受怕的话，我们这儿还有很多保镖。$B$B现在，我这个卑微的地精仆从能为你做些什么呢？呃，你又能为我做些什么呢？', `MaleText_loc5`='歡迎來到藏寶海灣，夥伴。希望你在這兒度過一段快樂平靜的日子 - 重點在後者。如果你口渴的話，我們這兒有很多飲料;如果你擔心受怕的話，我們這兒還有很多保鏢。$B$B現在...我這個熱砂企業卑微的僕人能為你做什麼呢?這麼說好了 - 你又能為我做些什麼呢，嗯?', `MaleText_loc7`='$gBienvenido:Bienvenida; a la Bahía del Botín, $gcompañero:compañera;. Espero que disfrutes tu estancia en mi ciudad y que transcurra sin incidentes, y recalco esto último. Si tienes sed tenemos mucha bebida y si tienes miedo, muchos porteros.$B$BEntonces... ¿qué puede hacer este humilde sirviente del Cártel Bonvapor por ti? Mejor aún, ¿qué puedes hacer tú por mí, eh?' WHERE `ID`=11154;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 얼라이언스에 할당된 양의 전쟁 물자를 모두 수집했습니다. 현재 호드가 완료하기를 기다리는 중인데 호드의 준비가 끝나면 모든 물자를 실리더스로 수송할 예정입니다.', `MaleText_loc4`='联盟所需的所有战争物资都已经收集完毕，$C。我们就等着部落的劳工完成任务了，然后我们就开始所有物资运往希利苏斯。', `MaleText_loc5`='聯盟對所有作戰物資需求的貢獻相當滿意，$c。我們正等待部落勞工被完成任務，然後我們就開始所有物資運往希利蘇斯。', `MaleText_loc7`='Ya se ha recibido todo el material necesario con el que la Alianza contribuirá a la campaña, $c. Esperaremos a que la Horda finalice sus trabajos y después enviaremos los pertrechos a Silithus.' WHERE `ID`=11155;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='젊은 $c|1이여;여;, 모든 준비가 끝났습니다. 일전에 우리가 말한 대로 호드와 얼라이언스 모두 전쟁 물자를 세나리온 요새 근처의 실리더스로 수송하고 있지요. 최종 작업은 늦어도 $2113w일 내에 완료될 겁니다. 그다음 안퀴라즈 관문 근처의 징이 울리면 전쟁이 시작되는 겁니다.', `MaleText_loc4`='任务都完成了，年轻的$C。就如我们先前约定的那样，部落和联盟必须将所有的战争物资都运往希利苏斯的塞纳里奥要塞附近，货物将在$2113w天内运达。在那之后，安其拉大门的铜锣将被敲响，战争也就拉开序幕了。', `MaleText_loc5`='都準備好了，年輕人，$c。正如同我們所說的，部落和聯盟必須將所有的戰爭物資都運往希利蘇斯的塞納里奧城堡附近，貨物將在$2113w天內運達。待一切就緒，安其拉大門附近的銅鑼就會被敲響。戰爭即將開打!', `MaleText_loc7`='Todo está completo, joven $c. Hasta el punto de que mientras hablamos, tanto la Horda como la Alianza están de camino a Silithus, cerca del Fuerte Cenarion, con la última mercancía para la guerra que debería llegar en menos de $2113w días. A continuación, ya se podrá hacer sonar el gong situado en las proximidades de las puertas de Ahn''Qiraj y la guerra dará comienzo.' WHERE `ID`=11156;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$c|1이여;여;, 안녕하세요. 이미 알고 계실지도 모르지만 우리는 이번 전쟁에서 얼라이언스에 할당된 전쟁 물자 수집을 마쳤어요. 이제 호드만 일을 끝내면 실리더스로 물자를 수송할 예정이에요.', `FemaleText_loc4`='嗨，$C。安其拉一战迫在眉睫，我们已经集齐联盟所需的战争物资了。现在只要部落收集好物资，我们就能把货物送往希利苏斯了。', `FemaleText_loc5`='你好，$c。就如同你所知道的一樣，我們已完成所有聯盟人民的作戰物資收集。現在就等著部落收集完他們的物資，然後我們就要將作戰物資運往希利蘇斯。', `FemaleText_loc7`='Ave, $c. Como ya sabrás, hemos finalizado todas las labores de recogida de mercancías con las que la Alianza hará su contribución a la inminente guerra. Ahora está en manos de la Horda finalizar las suyas y después partiremos para Silithus.' WHERE `ID`=11157;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$c|1이여;여;, 임무를 보고하러 오셨나요? 얼라이언스와 호드의 전쟁 물자 수집이 모두 완료되어 일전에 말한 대로 지금 실리더스로 수송하는 중입니다. 늦어도 $2113w일 안에 모두 도착할 거예요. 누군가 흐르는 모래의 홀의 흩어진 파편들을 찾아서 하나로 합쳐 놓았다면 좋겠는데...', `FemaleText_loc4`='你是来这儿报到的吗，$C？部落和联盟所需的所有战争物资都已经收集完毕，如约运往希利苏斯了。货物在$2113w天内就会抵达。希望有人能找到流沙节杖的碎片，将它们组合到一起。', `FemaleText_loc5`='你是在做工作報告嗎，$c?部落和聯盟雙方的作戰物資都已收集完畢且已運往希利蘇斯。最少 $2113w天就可將所有貨物送達。我希望有人能找到流沙權杖碎片的其他部分，並將它完整拼湊。', `FemaleText_loc7`='¿Te estás presentando para cumplir con tu deber, $c? Todos los pertrechos tanto de la Horda como de la Alianza están completos y van de camino a Silithus mientras hablamos. Deberían llegar en menos de $2113w días. Espero que alguien haya encontrado los diferentes fragmentos del cetro del Mar de Dunas y que lo hayan reconstruido.' WHERE `ID`=11158;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위대한 힘을 가진 존재가 깨어났습니다.', `MaleText_loc4`='一股强大的力量已经苏醒了。', `MaleText_loc5`='一股強大的力量已經甦醒。', `MaleText_loc7`='Un ser de infinito poder se ha despertado.' WHERE `ID`=11159;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='식인아귀가 원래 왔던 곳으로 돌아가고, 넵튤론의 분노가 가라앉았습니다.', `MaleText_loc4`='这头野兽回去了，耐普图洛斯的愤怒渐渐平息了。', `MaleText_loc5`='這頭野獸回去了，奈普圖隆的憤怒也已平息。', `MaleText_loc7`='La bestia regresa del lugar al que un día fue. La ira de Neptulon se ha apagado.' WHERE `ID`=11160;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그래요, 이번 전쟁에 대비하여 얼라이언스에 할당된 물자는 모두 모은 것 같군요. 대장장이와 기술자를 포함한 모든 이들이 마지막 준비에 여념이 없는 걸로 알고 있어요. 호드만 물자 수집을 완료하면 전쟁을 위해 모든 전쟁 물자가 실리더스로 수송될 예정이라고 해요.', `FemaleText_loc4`='呃，$G小伙子:姑娘;，似乎联盟已经集齐所有的战争物资了。听说铁匠、工程师和其他人都在进行最后的准备工作。一旦部落也集齐了他们所需的物资，就能把它们全部运往希利苏斯，与该死的虫子们开战了。', `FemaleText_loc5`='很好，$g小夥子:小姑娘;，看來聯盟已將作戰所需物資準備妥當了。我知道鐵匠、工程師和其他人都在忙著作最後的準備，一旦部落收集好他們所有的物資後，立即前往希利蘇斯準備作戰。', `FemaleText_loc7`='Bien, $gmuchacho: muchacha;, parece que la Alianza ya ha reunido todo lo que necesitábamos por nuestra parte para la guerra. Sé que los herreros, ingenieros y todos los demás están ocupados con los preparativos finales y, tan pronto como la Horda reúna toda su mercancía, será enviada a Silithus para la guerra.' WHERE `ID`=11161;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자원 수집이 완료되어 마지막까지 모은 물자를 세나리온 요새로 수송 중인 걸로 알고 있어요. 마지막 수송은 $2113w일 내로 완료될 거고요. 우리 군대와 모든 장비가 그곳에 집결하면 흐르는 모래의 홀을 가진 이가 안퀴라즈 근처에 있는 징을 울려 성문을 열 거예요. 전쟁이 시작되는 거죠.', `FemaleText_loc4`='我听说所有的物资都已经收集完毕并且运往塞纳里奥要塞了。货物将在$2113w天内抵达。一旦我们的装备和军队准备就绪，流沙节杖的持有者就可以敲响安其拉附近的铜锣，打开大门。那时，战争也就开始了。', `FemaleText_loc5`='據我所知，所有東西都已收集齊全，而最後的作戰物資也已收集完畢並運往塞納里奧城堡。最後一批不用$2113w天就可抵達。一旦我們的裝備和軍隊準備就緒，流沙權杖的持有者就可以敲響安其拉附近的銅鑼，打開大門。那時，戰爭也就開始了。', `FemaleText_loc7`='Por lo que he entendido, todo está listo y ya se han preparado y enviado los últimos pertrechos al Fuerte Cenarion. El último envío debería llegar en menos de $2113w días. Una vez que nuestro equipo y nuestras tropas estén allí, el portador del cetro del Mar de Dunas podrá hacer sonar el gong de Ahn''Qiraj para abrir sus puertas. Entonces dará comienzo la guerra.' WHERE `ID`=11162;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모든 준비가 끝나고 이제 한판 붙을 일만 남았어요. 전쟁 물자를 모두 실리더스의 세나리온 요새로 수송 중인데 하루 안에 마지막 물자가 도착할 것입니다. 조만간 홀의 파편만 합쳐지면 드디어 전쟁이 시작되는 것입니다.', `MaleText_loc4`='时局紧张，所有的战争物资都在运往希利苏斯塞纳里奥要塞的途中，预定将在1天内全部抵达。一旦有人修复节杖，战争也就离我们不远了。', `MaleText_loc5`='現在大勢已定，一切就緒。所有作戰物資正運往希利蘇斯的塞納里奧城堡，最少1天就可以抵達。一旦有人修復權杖，戰爭也就離我們不遠了。', `MaleText_loc7`='Todo está listo pero el tiempo apremia. Todos los pertrechos están de camino al Fuerte Cenarion en Silithus y el último envío llegará a su destino en menos de un día. No debería tardar mucho más en reconstruirse el cetro y dar comienzo la guerra.' WHERE `ID`=11163;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야호, 끝났다! 물자 수집을 모두 완료했네. 그리고 말했듯이 수집한 물자는 비행선에 실어 실리더스로 공수 중이라네. 늦어도 하루 안에 마지막 물자가 도착할 게야. 물자 수송이 완료되고 홀의 파편들이 하나로 합쳐지면 더러운 벌레들과의 전쟁이 시작되는 거지. 병사들의 표현을 빌리자면 한마디로 이런 거지. ''보내 버려!''', `MaleText_loc4`='哈哈，一切准备就绪！收集工作结束了，收集工作结束了，物资将如约由地精飞艇运往希利苏斯。预计最后一批将在1天内抵达。一旦节杖复原，与那些肮脏的虫子的战争也就开始了。现在，开始装运吧！', `MaleText_loc5`='唷呼!出發囉!收集工作結束了，收集工作結束了，物資將如約由地精飛艇運往希利蘇斯。預計最後一批將在1天內抵達。一旦權杖復原，與那些骯髒蟲子的戰爭也就開始了。現在，開始裝運吧!', `MaleText_loc7`='¡Guau, allá vamos! Todo el mundo ha recogido todo y ya va en zepelín de camino a Silithus mientras hablamos. El último envío debería llegar en menos de un día. Cuando todo esté allí y los fragmentos del cetro se hayan reunido, podrá dar comienzo la guerra contra esos sucios insectos. Como ellos dicen, "¡Despáchalo!"' WHERE `ID`=11164;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요? 제가 들은 바로는 물자 수집이 완료되어 우리가 얘기한대로 모든 전쟁 물자를 실리더스로 수송 중이라고 하네요. 앞으로 단 하루 안에 모두 보내야 한다는군요. 만반의 준비가 끝나면 흐르는 모래의 홀로 징을 울리고 진짜 전쟁을 시작할 수 있는 거죠.', `FemaleText_loc4`='你好，$C。我听说所有的物资都已经收集完毕，将如约运往希利苏斯。货物将在1天内运达。在那之后，流沙节杖的持有者将敲响铜锣，战争也就开始了。', `FemaleText_loc5`='嗨，$c。據我所知，所有東西已準備就緒，所有作戰物資正運往希利蘇斯。不需1天就可抵達。一旦物資到達，就等著流沙權杖敲響銅鑼。戰爭即將開始!', `FemaleText_loc7`='Hola, $c. Según mis datos, ya se ha reunido todo lo necesario y los pertrechos para la guerra están de camino a Silithus mientras hablamos. Debería estar todo allí en menos de un día. Hecho esto, y una vez que se haya hecho sonar el gong utilizando el cetro del Mar de Dunas, la guerra podrá por fin comenzar.' WHERE `ID`=11165;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다 됐습니다. 양쪽 모두 물자 수집을 완료했어요. 현재 모든 물자를 실리더스로 수송하는 중이며 늦어도 하루 안에 도착할 거요. 만반의 준비가 끝나고 누군가 흐르는 모래의 홀로 스카라베 제단의 징을 울리면 전쟁이 시작되는 겁니다.', `MaleText_loc4`='好极了，双方都完成了收集工作。现在这些物资都已经运往希利苏斯了，所有的货物预计将在1天内抵达。一旦准备就绪，就会有人使用流沙节杖敲响甲虫之台的铜锣，战争也就开始了！', `MaleText_loc5`='好了，雙方都準備好了。現在作戰物資正運往希利蘇斯，不需1天就可抵達。一旦準備就緒，就會有人拿著流沙權杖敲響甲蟲之台的銅鑼。立即開戰!', `MaleText_loc7`='Eso es, ambas partes han reunido todo lo necesario. Ahora mismo todo está de camino a Silithus y debería llegar a su destino en menos de un día. Hecho esto, y una vez que alguien haga sonar el gong situado en el Dais del Escarabajo utilizando el cetro del Mar de Dunas, ¡la guerra dará comienzo!' WHERE `ID`=11166;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='젊은 $c|1이여;여;, 모든 준비가 끝났습니다. 일전에 우리가 말한 대로 호드와 얼라이언스 모두 전쟁 물자를 세나리온 요새 근처의 실리더스로 수송하고 있지요. 최종 작업은 늦어도 하루 안에 완료될 겁니다. 그다음 안퀴라즈 관문 근처의 징이 울리면 전쟁이 시작되는 겁니다.', `MaleText_loc4`='任务都完成了，年轻的$C。就如我们先前约定的那样，部落和联盟必须将所有的战争物资都运往希利苏斯的塞纳里奥要塞附近，货物将在1天内运达。在那之后，安其拉大门的铜锣将被敲响，战争也就拉开序幕了。', `MaleText_loc5`='都準備好了，年輕人，$c。正如同我們所說的，部落和聯盟正在運送最後一批物資前往塞納里奧城堡附近的希利蘇斯，最少一天就可抵達。待一切就緒，安其拉大門附近的銅鑼就會被敲響。戰爭即將開打!', `MaleText_loc7`='Todo está completo, joven $c. Hasta el punto de que mientras hablamos, tanto la Horda como la Alianza están de camino a Silithus, cerca del Fuerte Cenarion, con la última mercancía para la guerra que debería llegar en menos de un día. A continuación, ya se podrá hacer sonar el gong situado en las proximidades de las puertas de Ahn''Qiraj y la guerra dará comienzo.' WHERE `ID`=11167;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$c|1이여;여;, 임무를 보고하러 오셨나요? 얼라이언스와 호드의 전쟁 물자 수집이 모두 완료되어 일전에 말한 대로 지금 실리더스로 수송하는 중입니다. 늦어도 하루 안에 모두 도착할 거예요. 누군가 흐르는 모래의 홀의 흩어진 파편들을 찾아서 하나로 합쳐 놓았다면 좋겠는데...', `FemaleText_loc4`='你是来这儿报到的吗，$C？部落和联盟所需的所有战争物资都已经收集完毕，如约运往希利苏斯了。货物在1天内就会抵达。希望有人能找到流沙节杖的碎片，将它们组合到一起。', `FemaleText_loc5`='你是在做工作報告嗎，$c?部落和聯盟雙方的作戰物資都已收集完畢且已運往希利蘇斯。最少 １天就可將所有貨物送達。我希望有人能找到流沙權杖碎片的其他部分，並將它完整拼湊起來。', `FemaleText_loc7`='¿Te estás presentando para cumplir con tu deber, $c? Todos los pertrechos tanto de la Horda como de la Alianza están completos y van de camino a Silithus mientras hablamos. Debería llegar en menos de un día. Espero que alguien haya encontrado los diferentes fragmentos del cetro del Mar de Dunas y que lo hayan reconstruido.' WHERE `ID`=11168;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자원 수집이 완료되어 마지막까지 모은 물자를 세나리온 요새로 수송 중인 걸로 알고 있어요. 마지막 수송은 하루 안에 완료될 거고요. 우리 군대와 모든 장비가 그곳에 집결하면 흐르는 모래의 홀을 가진 이가 안퀴라즈 근처에 있는 징을 울려 성문을 열 거예요. 전쟁이 시작되는 거죠.', `FemaleText_loc4`='我听说所有的物资都已经收集完毕并且运往塞纳里奥要塞了。货物将在1天内抵达。一旦我们的装备和军队准备就绪，流沙节杖的持有者就可以敲响安其拉附近的铜锣，打开大门。那时，战争也就开始了。', `FemaleText_loc5`='據我所知，所有東西都已收集齊全，而最後的作戰物資也已收集完畢並運往塞納里奧城堡。最後一批不用１天就可抵達。一旦我們的裝備和軍隊準備就緒，流沙權杖的持有者就可以敲響安其拉附近的銅鑼，打開大門。那時，戰爭也就開始了。', `FemaleText_loc7`='Por lo que he entendido, todo está listo y ya se han preparado y enviado los últimos pertrechos al Fuerte Cenarion. El último envío debería llegar en menos de un día. Una vez que nuestro equipo y nuestras tropas estén allí, el portador del cetro del Mar de Dunas podrá hacer sonar el gong de Ahn''Qiraj para abrir sus puertas. Entonces dará comienzo la guerra.' WHERE `ID`=11169;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 그렇습니다! 얼라이언스에 필요한 전쟁 물자 수집이 완료되었다고 보고를 드리라는 명령을 받았습니다. 호드의 준비가 끝나는 대로 모든 물자를 실리더스로 수송할 예정이라고 합니다. 감사합니다!', `MaleText_loc4`='长官！我奉命向你汇报，联盟已经集齐所需的战争物资了。我接到消息称，我们只需等待部落完成他们的收集任务，然后就能将所有的物资运往希利苏斯了。谢谢你，长官！', `MaleText_loc5`='是的，$g先生:女士;!我是特別前來報告，聯盟已將所有作戰物資準備妥當了。現在就等部落完成他們收集的物資之後，立即前往希利蘇斯。謝謝你$g先生:女士;!', `MaleText_loc7`='¡Por supuesto, $gseñor: señora;! Debo informar de que la Alianza ha reunido todos los pertrechos necesarios. Me han transmitido que debemos esperar a que la Horda termine con su parte y después se enviará todo a Silithus. ¡Gracias, $gseñor: señora;!' WHERE `ID`=11170;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='차렷! 안퀴라즈 전쟁에 필요한 전쟁 물자 수집이 완료되었으며 현재 세나리온 요새로 수송 중입니다! $2113w일 내로 마지막 물자가 도착할 예정이라고 합니다. 수송이 완료되고 누군가 그곳의 징을 울려 성문을 열면 우리는 벌레 놈들을 한 방에 날려 버릴 것입니다. 자신 있습니다!', `MaleText_loc4`='安其拉之战所需的物资正在准备运往塞纳里奥要塞！据说最后一批货物会在$2113w天内抵达。在那之后，我们就能敲响铜锣，打开安其拉的大门了。我打赌我们会给那些虫子迎头痛击的！', `MaleText_loc5`='所有安其拉之戰所需的物資皆已準備運往塞納里奧城堡$g先生:女士;!我聽說不用$2113w天即可到達!一旦物資抵達，就會有人敲響銅鑼打開大門，我保證我們絕對會把那些怪物殺個片甲不留!', `MaleText_loc7`='¡Atención! ¡Todos los pertrechos para la guerra de Ahn''Qiraj completos y de camino al Fuerte Cenarion $gseñor: señora;! Me han informado de que el último envío debería llegar en menos de $2113w días. Cuando lleguen y alguien haga sonar el gong que abre las puertas, os garantizo que les daremos a esos bichos lo que se merecen.' WHERE `ID`=11171;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='차렷! 안퀴라즈 전쟁에 필요한 전쟁 물자 수집이 완료되었으며 현재 세나리온 요새로 수송 중입니다! 하루 안에 마지막 물자가 도착할 예정이라고 합니다. 수송이 완료되고 누군가 그곳의 징을 울려 성문을 열면 우리는 벌레 놈들을 한 방에 날려 버릴 것입니다. 자신 있습니다!', `MaleText_loc4`='安其拉之战所需的物资正在准备运往塞纳里奥要塞！据说最后一批货物会在1天内抵达。在那之后，我们就能敲响铜锣，打开安其拉的大门了。我打赌我们会给那些虫子迎头痛击的！', `MaleText_loc5`='所有安其拉之戰所需的物資皆已準備運往塞納里奧城堡$g先生:女士;!我說過不用一天即可到達!一旦物資抵達，就會有人敲響銅鑼打開大門，我保證我們絕對會把那些怪物殺個片甲不留!', `MaleText_loc7`='¡Atención! ¡Todos los pertrechos para la guerra de Ahn''Qiraj completos y de camino al Fuerte Cenarion $gseñor: señora;! Me han informado de que el último envío debería llegar en menos de un día. Cuando lleguen y alguien haga sonar el gong que abre las puertas, os garantizo que les daremos a esos bichos lo que se merecen.' WHERE `ID`=11172;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요! 호드 측에서 물자를 모두 모았어요. 말씀드린 대로 우리가 모은 것과 함께 지금 실리더스로 수송 중인 것 같아요. 제가 듣기로 하루 안에 모두 도착할 예정이고 누군가 안퀴라즈 관문 근처의 커다란 징을 울리면 전쟁이 시작될 거라고 하네요.', `FemaleText_loc4`='嗨，$C！似乎部落已经集齐所有的战争物资了，现在部落和联盟的物资都将如约运往希利苏斯。据说货物在1天之内就能到达，那时就能敲响安其拉大门附近的铜锣，战争也就开始了。', `FemaleText_loc5`='嘿，$c!看來部落已收集最後一批物資了，現在雙方正運送物資前往希利蘇斯。我聽說1天之內的時間就可抵達，然後就會有人敲響安其拉之門附近的大銅鑼點燃戰火。', `FemaleText_loc7`='¡Eh, $c! Parece que la Horda ya ha reunido todo el material y, tanto el suyo como el nuestro, están de camino a Silithus mientras hablamos. Me han dicho que estará allí en menos de un día y que alguien hará sonar el gran gong junto a las puertas de Ahn''Qiraj para que dé comienzo la guerra.' WHERE `ID`=11173;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요! 호드 측에서 물자를 모두 모았어요. 말씀드린 대로 우리가 모은 것과 함께 지금 실리더스로 수송 중인 것 같아요. 제가 듣기로 $2113w일 내로 모두 도착할 예정이고 누군가 안퀴라즈 관문 근처의 커다란 징을 울리면 전쟁이 시작될 거라고 하네요.', `FemaleText_loc4`='嗨，$C！似乎部落已经集齐所有的战争物资了，现在部落和联盟的物资都将如约运往希利苏斯。据说货物在$2113w天之内就能到达，那时就能敲响安其拉大门附近的铜锣，战争也就开始了。', `FemaleText_loc5`='嘿，$c!看來部落已收集最後一批物資了，現在雙方正運送物資前往希利蘇斯。我聽說$2113w天內的時間就可抵達，然後就會有人敲響安其拉之門附近的大銅鑼開始作戰!', `FemaleText_loc7`='¡Eh, $c! Parece que la Horda ya ha reunido todo el material y, tanto el suyo como el nuestro, están de camino a Silithus mientras hablamos. Me han dicho que estará allí en menos de $2113w días y que alguien hará sonar el gran gong junto a las puertas de Ahn''Qiraj para que dé comienzo la guerra.' WHERE `ID`=11174;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요! 주변을 돌아다니며 물어봤는데 이번 안퀴라즈 전쟁에 대비하여 얼라이언스에 할당된 물자 수집을 모두 끝마쳤다고 하네요. 이제 호드 쪽에서 물자 수집을 마치도록 응원해주는 일만 남았군요. 호드가 일을 끝내면 실리더스의 세나리온 요새로 이 물자를 전부 옮길 수 있을 거예요.', `FemaleText_loc4`='你好，$C！我四下询问过了，似乎联盟已经集齐安其拉一战所需的全部战争物资了。现在我们只需鼓励部落再加把劲儿，就能将这些物资运往希利苏斯的塞纳里奥要塞了。', `FemaleText_loc5`='你好，$c!我巡視了一下，看來聯盟的人民都已收集所有安其拉之戰所需準備的物資了。現在我們只需鼓勵部落去收集物資，就能將這些物資通通運往希利蘇斯附近的塞納里奧城堡。', `FemaleText_loc7`='¡Hola, $c! He preguntado por ahí y parece que todos nosotros ya hemos reunido el material que la Alianza necesita para prepararse para la guerra de Ahn''Qiraj. Ahora tenemos que alentar a la Horda para que haga lo mismo y así podremos enviar todo al Fuerte Cenarion en Silithus.' WHERE `ID`=11175;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='', `MaleText_loc4`='', `MaleText_loc5`='', `MaleText_loc7`='' WHERE `ID`=11176;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나라인, 특수 장비를 하나 더 얻었으면 합니다.', `MaleText_loc4`='纳瑞安，我还想再要一个特殊工具箱。', `MaleText_loc5`='納里安，我需要另一個特殊工具箱。', `MaleText_loc7`='Narain, necesito otro juego especial.', `FemaleText_loc1`='나라인, 특수 장비를 하나 더 얻었으면 해요.', `FemaleText_loc4`='纳瑞安，我还想再要一个特殊工具箱。', `FemaleText_loc5`='納里安，我需要另一個特殊工具箱。', `FemaleText_loc7`='Narain, necesito otro juego especial.' WHERE `ID`=11177;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나라인, 재료가 충분하다면 아케이나이트 부표를 하나 더 얻었으면 좋겠습니다.', `MaleText_loc4`='纳瑞安，如果你有足够的材料的话，我还想再要一个奥金鱼漂。', `MaleText_loc5`='納里安，如果你有足夠的材料的話，我還想再要一個奧金浮標。', `MaleText_loc7`='Narain, si tienes suficientes pertrechos, podría coger otra boya de arcanita.', `FemaleText_loc1`='나라인, 재료가 충분하다면 아케이나이트 부표를 하나 더 얻었으면 좋겠어요.', `FemaleText_loc4`='纳瑞安，如果你有足够的材料的话，我还想再要一个奥金鱼漂。', `FemaleText_loc5`='納里安，如果你已有足夠的物資，我就可以使用另一個奧金浮標。', `FemaleText_loc7`='Narain, si tienes suficientes pertrechos, podría coger otra boya de arcanita.' WHERE `ID`=11178;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리가 말한 대로 모든 전쟁 물자를 실리더스로 수송 중입니다. 현재 상황으로 봤을 때, 하루 안에 마지막 수송이 완료될 것 같습니다. 그러면 아제로스의 영웅이라 할만한 누군가 스카라베 제단에 있는 징을 울려야 합니다. 그때야 비로소 본격적인 전쟁이 시작되는 것이지요.', `FemaleText_loc4`='$C，所有的战争物资将如约运往希利苏斯。按照目前的情况来看，货物将在1天内全部抵达。然后，某位英雄将敲响甲虫墙上的铜锣，战争也就开始了。', `FemaleText_loc5`='正如我們所說的，$c，所有作戰所需物資都已運往希利蘇斯。看來，最後一批不用1天就可送達。然後，一位$g英雄:女豪傑;，就會去敲響甲蟲之台的戰鑼。戰爭即將開始!', `FemaleText_loc7`='Mientras nosotros hablamos, $c, todo el material de guerra está de camino a Silithus. Tal y como van las cosas, el último envío debería llegar en menos de un día. A continuación, $gun:una; valiente tendrá que venir y hacer sonar el gong situado en el Estrado del Escarabajo. Entonces dará comienzo la parte más dura.' WHERE `ID`=11179;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리가 말한 대로 모든 전쟁 물자를 실리더스로 수송 중입니다. 현재 상황으로 봤을 때, $2113w일 내로 마지막 수송이 완료될 것 같습니다. 그러면 아제로스의 영웅이라 할만한 누군가 스카라베 제단에 있는 징을 울려야 합니다. 그때야 비로소 본격적인 전쟁이 시작되는 것이지요.', `FemaleText_loc4`='$C，所有的战争物资将如约运往希利苏斯。按照目前的情况来看，货物将在$2113w天内全部抵达。然后，某位英雄将敲响甲虫墙上的铜锣，战争也就开始了。', `FemaleText_loc5`='正如我們所說的，$c，所有作戰所需物資都已運往希利蘇斯。看來，最後一批不用$2113w天就可送達。然後，一位$g英雄:女豪傑;，就會去敲響甲蟲之台的銅鑼。戰爭即將開始!', `FemaleText_loc7`='Mientras nosotros hablamos, $c, todo el material de guerra está de camino a Silithus. Tal y como van las cosas, el último envío debería llegar en menos de $2113w días. A continuación, $gun:una; valiente tendrá que venir y hacer sonar el gong situado en el Estrado del Escarabajo. Entonces dará comienzo la parte más dura.' WHERE `ID`=11180;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$c|1이여;여;, 기뻐하세요. 얼라이언스가 전쟁 물자 수집 임무를 모두 완료했습니다. 완성된 물자는 잘 보관해 두고 가공되지 않은 재료는 우리의 기술자들이 전쟁 물자로 만들고자 최선을 다하고 있습니다. 호드의 일이 끝나는 대로 실리더스로 옮길 예정이랍니다.', `FemaleText_loc4`='为我们感到骄傲吧，$C。事实上联盟已经完成了所有的收集任务了。战争物资得到了妥善的保存，人们正在努力工作，将那些原料制成战争物资。一旦部落完成他们的收集任务，我们就能把物资运往希利苏斯了。', `FemaleText_loc5`='真是太值得驕傲了啊，$c，事實上聯盟在這之前就已完成所有作戰物資的收集工作。整理好的貨物也已儲存並準備就緒，而我們的交易技能專家正努力將武器製模、加工重組，一旦部落完成他們的收集任務，我們就能把物資運往希利蘇斯了。', `FemaleText_loc7`='Enorgullécete, $c, pues la Alianza ha completado sus tareas de recogida de material. Todos los productos están almacenados para su conservación y nuestros mejores profesionales están trabajando duro para convertir los toscos materiales en pertrechos que serán enviados a Silithus tan pronto como la Horda acabe de reunir todo su material.' WHERE `ID`=11181;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리가 마지막 힘을 다해 모은 전쟁 물자가 앞으로 내일까지 실리더스로 옮겨질 것 같아요. 물자 수송이 완료되면 누군가 안퀴라즈 밖에 있는 스카라베 제단에서 징을 울려 문을 열어야 해요. 바로 그때 우리 붕대가 필요할 때가 시작되는 거죠.', `FemaleText_loc4`='似乎所有的物资都将在明日运抵希利苏斯。一切就绪后，某位英雄将敲响甲虫墙上的铜锣，打开安其拉的大门。那时，我们收集的绷带就能派上用场了。', `FemaleText_loc5`='看來我們收集的最後一批貨物將會在明日運抵希利蘇斯。一切就緒後，某位英雄將敲響甲蟲之台上的銅鑼，打開安其拉的大門。那時，我們收集的繃帶就能派上用場了。', `FemaleText_loc7`='Parece que las últimas provisiones que hemos reunido serán enviadas a Silithus en el próximo día. Y una vez estén allí, alguien tendrá que hacer sonar el gong situado en el Estrado del Escarabajo, fuera de Ahn''Qiraj, para abrir las puertas. A partir de ese momento nos vendrán muy bien las vendas.' WHERE `ID`=11182;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리가 마지막 힘을 다해 모은 전쟁 물자가 앞으로 $2113w일 내에 실리더스로 옮겨질 것 같아요. 물자 수송이 완료되면 누군가 안퀴라즈 밖에 있는 스카라베 제단에서 징을 울려 문을 열어야 해요. 바로 그때 우리 붕대가 필요할 때가 시작되는 거죠.', `FemaleText_loc4`='似乎所有的物资都将在接下来的$2113w天内运抵希利苏斯。一切就绪后，某位英雄将敲响甲虫墙上的铜锣，打开安其拉的大门。那时，我们收集的绷带就能派上用场了。', `FemaleText_loc5`='看來我們收集的最後一批貨物將會在接下來的$2113w天中被送往希利蘇斯。一切就緒後，某位英雄將敲響甲蟲之台上的銅鑼，打開安其拉的大門。那時，我們收集的繃帶就能派上用場了。', `FemaleText_loc7`='Parece que las últimas provisiones que hemos reunido serán enviadas a Silithus en los próximos $2113w días. Y una vez estén allí, alguien tendrá que hacer sonar el gong situado en el Estrado del Escarabajo, fuera de Ahn''Qiraj, para abrir las puertas. A partir de ese momento nos vendrán muy bien las vendas.' WHERE `ID`=11183;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사령관님들께서는 다가올 안퀴라즈 전쟁에 대비하여 우리에게 필요한 물자를 모두 수집했다고 말씀하셨어요. 이제 호드 쪽 수집이 끝나기를 기다렸다가 전쟁 물자를 수송하기만 하면 돼요.', `FemaleText_loc4`='将军说我们已经集齐安其拉一战所需的所有战争物资了。现在只等部落完成他们的收集任务，就可以开始运送战争物资了。', `FemaleText_loc5`='將軍說我們已經收集完安其拉之戰所需的全部物資了。現在我們就等部落完成他們的儲備工作，就可以開始運送作戰物資了。', `FemaleText_loc7`='Los generales nos han dicho que ya hemos reunido todo el material necesario para la inminente guerra de Ahn''Qiraj. Ahora tenemos que esperar a que la Horda acabe de organizar el suyo para poder comenzar con el envío del material de guerra.' WHERE `ID`=11184;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물자 수집을 모두 완료했소. 마지막 준비를 위해 실리더스로 수송 중인데 하루 안에 도착할 예정이오. 우리 연합군은 지금 흐르는 모래의 홀을 하나로 결합하여 징을 울려 안퀴라즈 전쟁을 시작할 영웅을 기다리고 있소.', `MaleText_loc4`='$C，所有的战争物资都已经收集完毕，并且在运往希利苏斯的途中了。预计货物将在1天内抵达。整装待发的大军将等待一位英雄修复流沙节杖，敲响铜锣，拉开安其拉一战的序幕。', `MaleText_loc5`='所有東西都準備好了，$c。而且都已經被送往希利蘇斯做最後的準備，一天內應該就會到了。整裝待發的大軍都等待一位$g英雄:女豪傑;修復流沙權杖，敲響銅鑼，開啟安其拉之戰。', `MaleText_loc7`='Ya lo tenemos todo, $c. Está de camino a Silithus para que le demos los últimos retoques y debería llegar en menos de un día. Todas nuestras tropas conjuntas aguardan $gal:a la; valiente que consiga reconstruir el cetro del Mar de Dunas, hacer sonar el gong y dar comienzo a la guerra de Ahn''Qiraj.' WHERE `ID`=11185;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물자 수집을 모두 완료했소. 마지막 준비를 위해 실리더스로 수송 중인데 $2113w일 내로 도착할 예정이오. 우리 연합군은 지금 흐르는 모래의 홀을 하나로 결합하여 징을 울려 안퀴라즈 전쟁을 시작할 영웅을 기다리고 있소.', `MaleText_loc4`='$C，所有的战争物资都已经收集完毕，并且在运往希利苏斯的途中了。预计货物将在$2113w天内抵达。整装待发的大军将等待一位英雄修复流沙节杖，敲响铜锣，拉开安其拉一战的序幕。', `MaleText_loc5`='所有東西都準備好了，$c。而且都已經被送往希利蘇斯做最後的準備，$2113w天內應該就會到了。整裝待發的大軍都等待一位$g英雄:女豪傑;修復流沙權杖，敲響銅鑼，開啟安其拉之戰。', `MaleText_loc7`='Ya lo tenemos todo, $c. Está de camino a Silithus para que le demos los últimos retoques y debería llegar en $2113w días. Todas nuestras tropas conjuntas aguardan $gal:a la; valiente que consiga reconstruir el cetro del Mar de Dunas, hacer sonar el gong y dar comienzo a la guerra de Ahn''Qiraj.' WHERE `ID`=11186;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스의 모든 물자 수집이 완료되었소. 현재 물자를 포장하고 만반의 준비를 하면서 호드를 기다리고 있소. 호드의 물자 수집이 끝나는 대로 모든 전쟁 물자를 실리더스로 수송할 것이오.', `MaleText_loc4`='联盟已经完成收集任务了，$C。现在，我们可以一边打包物资，一边等待部落集齐他们所需的物资，然后我们就能将所有的战争物资运往希利苏斯了。', `MaleText_loc5`='聯盟已經完成他們的收集工作了，$c。現在，我們一邊打包、準備東西，一邊等待部落的收集工作完成。然後我們就可以把所有的作戰物資送往希利蘇斯了。', `MaleText_loc7`='La Alianza ya ha completado sus trabajos de recogida de material, $c. Ahora, mientras empaquetamos y preparamos todo, esperaremos a que la Horda haga lo mismo. Después enviaremos todo nuestro material de guerra a Silithus.' WHERE `ID`=11187;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생선을 포함한 모든 물자들을 실리더스로 수송하는 중인데 하루 안에 도착할 겁니다. 그런 다음 누군가 흐르는 모래의 홀로 징을 울리면 전쟁이 시작될 거예요.', `MaleText_loc4`='所有的战争物资都已经收集完毕，并且在运往希利苏斯的途中了。预计货物将在1天内抵达。一旦有人使用流沙节杖敲响铜锣，安其拉一战也就拉开序幕。', `MaleText_loc5`='所有的魚和其他東西都在送往希利蘇斯的路上，應該一天以內就會到達。一旦有人使用流沙權杖敲響銅鑼，安其拉之戰即將拉開序幕。', `MaleText_loc7`='Todo el pescado y lo demás está de camino a Silithus y debería llegar a su destino en menos de un día. Tras esto, alguien hará sonar el gong utilizando el cetro del Mar de Dunas para que dé comienzo la guerra.' WHERE `ID`=11188;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생선을 포함한 모든 물자들을 실리더스로 수송하는 중인데 $2113w일 내로 도착할 겁니다. 그런 다음 누군가 흐르는 모래의 홀로 징을 울리면 전쟁이 시작될 거예요.', `MaleText_loc4`='所有的战争物资都已经收集完毕，并且在运往希利苏斯的途中了。预计货物将在$2113w天内抵达。一旦有人使用流沙节杖敲响铜锣，安其拉一战也就拉开序幕。', `MaleText_loc5`='所有的魚和其他東西都在送往希利蘇斯的路上，應該$2113w天以內就會到達。一旦有人使用流沙權杖敲響銅鑼，安其拉之戰即將拉開序幕。', `MaleText_loc7`='Todo el pescado y lo demás está de camino a Silithus y debería llegar a su destino en menos de $2113w días. Tras esto, alguien hará sonar el gong utilizando el cetro del Mar de Dunas para que dé comienzo la guerra.' WHERE `ID`=11189;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='들리는 얘기로는 우리에게 필요한 모든 물자가 모였다고 하네요. 이제 호드 측에서 물자 수집을 완료하기만 하면 되겠어요. 호드의 준비가 끝나면 모든 물자를 실리더스로 옮기겠죠. 바야흐로 전쟁을 시작할 수 있는 겁니다.', `MaleText_loc4`='我们已经收集了所有的战争物资，现在只等部落完成他们的收集任务了。那时，我们就能将所有的物资运往希利苏斯，战争也就开始了。', `MaleText_loc5`='我們已經收集好所有的作戰物資。現在就等部落完成他們的收集工作。那時，我們就能將貨物送到希利蘇斯，戰爭就要開始。', `MaleText_loc7`='Se rumorea que ya hemos reunido todo lo necesario. Ahora lo que falta es esperar a que la Horda haga lo mismo. Cuando hayan reunido todo su material podremos enviar nuestra mercancía a Silithus y la guerra dará comienzo.' WHERE `ID`=11190;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벽이 흔들리다니... 누군가 찾아온 것인가...', `MaleText_loc4`='墙壁震动了起来。一定是发生了什么事……', `MaleText_loc5`='房間的牆壁震動著。有什麼事要發生了...', `MaleText_loc7`='Las paredes de la cámara se estremecen. Algo está ocurriendo...', `FemaleText_loc1`='벽이 흔들려. 무슨 일이 일어나고 있어...', `FemaleText_loc4`='墙壁震动了起来。一定是发生了什么事……', `FemaleText_loc5`='房間的牆壁震動著。有什麼事要發生了...', `FemaleText_loc7`='Las paredes de la cámara se estremecen. Algo está ocurriendo...' WHERE `ID`=11191;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 고개 숙여 인사합니다.', `MaleText_loc4`='%s鞠了一躬。', `MaleText_loc5`='%s彎腰鞠躬。', `MaleText_loc7`='%s hace una reverencia.' WHERE `ID`=11192;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마음을 굳게 먹어라, 용사여. 그대가 왜 여기로 왔는지, 무얼 찾고 있는지 알고 있다. 에라니쿠스는 절대 홀 조각을 포기하지 않을 것이다. 그는 타락했다... 그대가 파괴하려는 바로 그 힘에 의해서.', `MaleText_loc4`='要保持镇定，勇士。我知道你来这里的目的，我也知道你要寻找的东西。伊兰尼库斯不会轻易交出碎片的。他的心灵被某种力量扭曲了，那力量正是你想要打败的东西。', `MaleText_loc5`='要保持鎮定，勇士。我知道你來這裡的目的，我也知道你要尋找的東西。伊蘭尼庫斯不會輕易交出裂片的。他的心靈被某種力量扭曲了，那力量正是你想要打敗的東西。', `MaleText_loc7`='Incorpórate, por favor. Sé por qué has venido y sé lo que andas buscando. Eranikus no te dará el fragmento de buen grado. Está corrupto... corrupto por las mismas fuerzas que tú pretendes destruir.' WHERE `ID`=11193;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='많이 놀랐나? 고대 신의 힘이 꿈속까지 미칠 것이라고 믿기 어렵겠지? 하지만 사실이다. 꿈의 폭군 에라니쿠스는 우리 모두를 상대로 싸움을 걸고 있느니, 그가 파괴하고 지나간 곳에는 악몽이 뒤따른다.', `MaleText_loc4`='你真的很吃惊吗？是不是很难相信上古之神的力量居然能穿越翡翠梦境？这是真的——伊兰尼库斯，梦境之暴君，已经向我们发起挑战了。随他而来的，是毁灭的力量。', `MaleText_loc5`='你真的很驚訝嗎?是不是很難相信上古之神的力量居然能穿越翡翠夢境?這是真的─伊蘭尼庫斯，夢境暴君，已經向我們發起挑戰了。隨他而來的，是夢魘般的毀滅力量。', `MaleText_loc7`='¿De verdad te sorprende? ¿Es tan difícil de creer que el poder de un dios antiguo pudiera entrar en el Sueño? Pues así es. Eranikus, Tirano del Sueño, está enfrentado con todos nosotros. La Pesadilla continúa con su estela de destrucción.' WHERE `ID`=11194;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명심해라. 에라니쿠스가 원하는 것은 오직 꿈속에서 빠져 나와 아제로스로 가는 것이다. 그가 꿈에서 나오면 내 현신을 파괴하기 위해 수단과 방법을 가리지 않을 것이나, 그대가 홀 파편을 되찾으려면 이 방법 밖에 없다.', `MaleText_loc4`='你要明白，伊兰尼库斯无非是想离开翡翠梦境，进入艾泽拉斯。一旦他得以脱身，他一定会疯狂地摧毁我的肉身。但是，这也是获取节杖碎片的惟一方法。', `MaleText_loc5`='你要明白，伊蘭尼庫斯無非是想離開翡翠夢境，進入艾澤拉斯。一旦他得以脫身，他一定會瘋狂地摧毀我的肉身。但是，這也是獲取權杖裂片的唯一方法。', `MaleText_loc7`='Ten presente que lo que Eranikus desea es salir del Sueño para entrar en Azeroth. Cuando lo consiga, no se detendrá ante nada e intentará destruir mi manifestación física. Sin embargo, es el único modo que existe para que puedas recuperar el fragmento de cetro.' WHERE `ID`=11195;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그를 이 세계로 데려올지어다, 용사여.', `MaleText_loc4`='勇士，你会将他带回这个世界的。', `MaleText_loc5`='勇士，你會將他帶回這個世界的。', `MaleText_loc7`='Lo traerás de vuelta a este mundo, valiente.' WHERE `ID`=11196;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='식량을 포함해서 우리가 수집한 모든 전쟁 물자를 실리더스로 옮기는 중이에요. 모두 하루 안에 도착할 거예요. 세나리온 요새 근처로 모든 물자가 집결되면 누군가 스카라베 제단에 있는 징을 울려야 안퀴라즈 관문을 열고 전쟁을 시작할 수 있다고 들었어요.', `FemaleText_loc4`='我们收集的所有食物和战争物资都在运往希利苏斯的途中。似乎在1天内货物就可全部抵达。有人告诉我说物资一旦到达塞纳里奥要塞，就会有人敲响甲虫墙上的铜锣，打开安其拉的大门，战争也将拉开序幕。', `FemaleText_loc5`='所有我們收集的食物和作戰物資都在往希利蘇斯的路上。應該一天內就會到了。有人跟我說一旦所有的東西都運到塞納里奧城堡，就會有人敲響甲蟲之台的銅鑼，打開安其拉的大門，戰爭也將拉開序幕。', `FemaleText_loc7`='Toda la comida y pertrechos que hemos reunido están de camino a Silithus. Deberían estar allí en menos de un día. Me han dicho que cuando todo esté instalado junto al Fuerte Cenarion, alguien hará sonar el gong situado en el Estrado del Escarabajo para abrir las puertas de Ahn''Qiraj y comenzar así la guerra.' WHERE `ID`=11197;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='식량을 포함해서 우리가 수집한 모든 전쟁 물자를 실리더스로 옮기는 중이에요. 모두 $2113w일 내로 도착할 거예요. 세나리온 요새 근처에 모든 물자가 모이면 누군가 스카라베 제단에 있는 징을 울려야 안퀴라즈 관문을 열고 전쟁을 시작할 수 있다고 들었어요.', `FemaleText_loc4`='我们收集的所有食物和战争物资都在运往希利苏斯的途中。似乎在$2113w天内货物就可全部抵达。有人告诉我说物资一旦到达塞纳里奥要塞，就会有人敲响甲虫墙上的铜锣，打开安其拉的大门，战争也将拉开序幕。', `FemaleText_loc5`='所有我們收集的食物和作戰物資都在往希利蘇斯的路上。應該$2113w天內就會到了。有人跟我說一旦所有的東西都運到塞納里奧城堡，就會有人敲響甲蟲之台的銅鑼，打開安其拉的大門，戰爭也將拉開序幕。', `FemaleText_loc7`='Toda la comida y pertrechos que hemos reunido están de camino a Silithus. Deberían estar todo allí en menos de $2113w días. Me han dicho que cuando todo esté instalado junto al Fuerte Cenarion, alguien hará sonar el gong situado en el Estrado del Escarabajo para abrir las puertas de Ahn''Qiraj y comenzar así la guerra.' WHERE `ID`=11198;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요? $c님. 여기 있는 모두와 얘기를 해 봤는데 얼라이언스가 이번 전쟁에서 필요한 물자를 모두 모은 것 같아요. 그러나, 오크 사절에 의하면 호드 측은 아직도 물자를 모으는 중이라고 하네요. 그러니까 이 전쟁 물자들을 실리더스로 옮길 때까지 시간이 좀 남았다는 뜻이죠.', `FemaleText_loc4`='嗨，$C。我跟这儿的每个人都谈过了，似乎我们已经集齐了联盟所需的战争物资。据兽人大使说部落尚未集齐，也就是说我们有充足的时间将这些物资运往希利苏斯。', `FemaleText_loc5`='嗨，$c。我已經跟附近所有人聊過了，看來我們已經有聯盟在戰爭中所需的物資。據獸人大使說部落尚未完成收集工作，也就是說我們有足夠的時間將這些物資運往希利蘇斯。', `FemaleText_loc7`='Hola, $c. He hablado con todos y parece que ya tenemos toda la mercancía que la Alianza necesita para la guerra. Sin embargo, ese ruin embajador orco dijo que la Horda todavía está reuniendo su material por lo que tenemos tiempo antes de enviar toda la mercancía hasta Silithus.' WHERE `ID`=11199;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요? 전쟁 물자를 세나리온 요새로 수송하는 중인데 하루 안에 모두 도착할 거예요. 그런 후에는 누군가 흐르는 모래의 홀을 결합한 후 징을 울려서 성문을 열기를 기도하는 수밖에 없지요.', `FemaleText_loc4`='你好，$R。战争物资正在运往塞纳里奥要塞的途中，货物将在1天内抵达。我们只希望那时会有一位拿着流沙节杖的英雄敲响铜锣，打开安其拉的大门。', `FemaleText_loc5`='你好， $r。作戰物資都在路上了，應該一天內就會到達塞納里奧城堡。我們只希望那時會有一位拿著流沙權杖的英雄敲響銅鑼，打開安其拉的大門。', `FemaleText_loc7`='Saludos, $r. Los pertrechos están de camino y deberían estar en el Fuerte Cenarion en el próximo día. Solo nos queda esperar que una vez llegue allí, alguien que haya conseguido reconstruir el cetro del Mar de Dunas haga sonar el gong para abrir las puertas.' WHERE `ID`=11200;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요? 전쟁 물자를 세나리온 요새로 수송하는 중인데 $2113w일 내로 모두 도착할 거예요. 그런 후에는 누군가 흐르는 모래의 홀을 결합한 후 징을 울려서 성문을 열기를 기도하는 수밖에 없지요.', `FemaleText_loc4`='你好，$R。战争物资正在运往塞纳里奥要塞的途中，货物将在$2113w天内抵达。我们只希望那时会有一位拿着流沙节杖的英雄敲响铜锣，打开安其拉的大门。', `FemaleText_loc5`='你好， $r。作戰物資都在路上了，應該$2113w天內就會到達塞納里奧城堡。我們只希望那時會有一位拿著流沙權杖的英雄敲響銅鑼，打開安其拉的大門。', `FemaleText_loc7`='Saludos, $r. Los pertrechos están de camino y deberían estar en el Fuerte Cenarion en los próximos $2113w días. Solo nos queda esperar que una vez llegue allí, alguien que haya conseguido reconstruir el cetro del Mar de Dunas haga sonar el gong para abrir las puertas.' WHERE `ID`=11201;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 모두 힘을 모아 노력한 덕분에 중요한 임무를 완수했습니다. 이제 훨씬 중요한 임무가 우리를 기다리고 있어요. 하지만, 지금은 아직 전쟁 물자 수집을 끝내지 못한 호드 쪽을 기다릴 수밖에 없습니다. 호드가 모든 준비를 마치면 실리시드와 그들을 조종하는 놈들과 결전을 벌여야 할 거예요.', `FemaleText_loc4`='我们所有人共同努力，终于完成了一项伟大的任务。现在我们需要面对更艰巨的挑战。只等部落完成他们的收集工作，我们就要全力抗衡异种虫类和它们的主人了。', `FemaleText_loc5`='我們所有人共同努力，已經完成了一項偉大的任務。現在又面臨一個更大的挑戰。只等部落的收集工作完成，我們就要全力抗衡異種蟲類和它們的主人了。', `FemaleText_loc7`='Todos nosotros, trabajando en equipo, hemos completado una importante tarea. Ahora nos espera una incluso más importante. Estamos a la espera de que la Horda reúna todo su material y después nos enfrentaremos juntos a los silítidos y a sus maestros.' WHERE `ID`=11202;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예상과 달리 이런 능력이 얼라이언스에게 있었군. 이제 호드 얼라이언스와 모두 안퀴라즈 전쟁에 필요한 준비를 마쳤네. 일전에 말한 대로 실리더스로 물자를 수송하는 중인데 하루 안에 도착할 걸세. 그다음엔 누군가 흐르는 모래의 홀을 다시 결합하여 스카라베 제단에 있는 징을 울리고 안퀴라즈의 관문을 열 걸세. 바야흐로 전쟁이 시작되는 거지!', `MaleText_loc4`='没想到你竟如此精通协调管理。安其拉一战迫在眉睫，联盟和部落都已经做好了充分的准备工作。所有的战争物资将如约运往希利苏斯，预计将在1天抵达。那是，会有一位英雄使用流沙节杖敲响甲虫之台的铜锣，打开安其拉之门。那时战争就真正打响了！', `MaleText_loc5`='沒想到你們都能勝任這樣的組織工作。聯盟和部落都完成了他們在安其拉之戰的準備工作。所有的戰爭物資將如約運往希利蘇斯，預計將在1天抵達。那是，會有一位英雄使用流沙權杖敲響甲蟲之台的銅鑼，打開安其拉之門。那時戰爭就真正打響了!', `MaleText_loc7`='Es increíble que tengáis tanta capacidad de organización. Tanto la Alianza como la Horda han finalizado todos los preparativos para la guerra de Ahn''Qiraj. Mientras hablamos, los pertrechos están de camino a Silithus y deberían llegar en el próximo día. Después, queda en manos del que vaya a reconstruir el cetro del Mar de Dunas golpear el gong situado en el Estrado del Escarabajo para abrir las puertas de Ahn''Qiraj. ¡En ese momento comenzará de verdad la guerra!' WHERE `ID`=11203;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예상과 달리 이런 능력이 얼라이언스에게 있었군. 이제 호드 얼라이언스와 모두 안퀴라즈 전쟁에 필요한 준비를 마쳤네. 일전에 말한 대로 실리더스로 물자를 수송하는 중인데 $2113w일 내로 도착할 걸세. 그다음엔 누군가 흐르는 모래의 홀을 다시 결합하여 스카라베 제단에 있는 징을 울리고 안퀴라즈의 관문을 열 걸세. 바야흐로 전쟁이 시작되는 거지!', `MaleText_loc4`='没想到你竟如此精通协调管理。安其拉一战迫在眉睫，联盟和部落都已经做好了充分的准备工作。所有的战争物资将如约运往希利苏斯，预计将在$2113w天抵达。那是，会有一位英雄使用流沙节杖敲响甲虫之台的铜锣，打开安其拉之门。那时战争就真正打响了！', `MaleText_loc5`='沒想到你們都能勝任這樣的組織工作。聯盟和部落都完成了他們在安其拉之戰的準備工作。所有的戰爭物資將如約運往希利蘇斯，預計將在$2113w天抵達。那時，會有一位英雄使用流沙權杖敲響甲蟲之台的銅鑼，打開安其拉之門。那時戰爭就真正打響了!', `MaleText_loc7`='Es increíble que tengáis tanta capacidad de organización. Tanto la Alianza como la Horda han finalizado todos los preparativos para la guerra de Ahn''Qiraj. Mientras hablamos, los pertrechos están de camino a Silithus y deberían llegar en los próximos $2113w días. Después, queda en manos del que vaya a reconstruir el cetro del Mar de Dunas golpear el gong situado en el Estrado del Escarabajo para abrir las puertas de Ahn''Qiraj. ¡En ese momento comenzará de verdad la guerra!' WHERE `ID`=11204;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예상한 대로 얼라이언스보다 우리 호드가 먼저 준비를 끝냈다네. 자네들 얼라이언스가 약속한 일을 아직 끝내지 못했기 때문에 우리는 전쟁에 필요한 마지막 단계를 진행하지 못하고 있네.$B$B자, $r|1이여;여;, 그러니 가서 자네가 맡은 일을 열심히 하도록.', `MaleText_loc4`='不出所料，部落比你们这帮所谓的联盟提前完成了收集任务。只有等你们集齐物资，我们才能进行最后的装运工作，是你们拖累了我们。$B$B现在，快去做好你的本职工作吧，$R。', `MaleText_loc5`='如我所料，部落已經在你和你所謂的聯盟之前完成了所有的準備工作。你讓我們無法採取最後的措施展開作戰行動，因為你還沒完成你所允諾的職責。$B$B現在快加緊腳步吧，$r。', `MaleText_loc7`='Tal y como estaba previsto, la Horda ha acabado con los preparativos antes que tú y tu denominada Alianza. Nos estás entorpeciendo y no podremos comenzar la guerra hasta que no hayas cumplido con tus obligaciones.$B$BY ahora vete y date prisa, $r.' WHERE `ID`=11205;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='인사를 받은 %s|1이;가; 거만한 태도로 손을 흔듭니다.', `MaleText_loc4`='%s接受了你的敬礼，然后轻蔑地对你挥挥手。', `MaleText_loc5`='%s接受你的敬禮並揮手示意你離開。', `MaleText_loc7`='%s admite tu reverencia y te hace un gesto con desdeño.' WHERE `ID`=11206;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공격! 호드를 위하여!', `MaleText_loc4`='进攻！为了部落！', `MaleText_loc5`='攻擊!為了部落!', `MaleText_loc7`='¡Atacad! ¡Por la Horda!' WHERE `ID`=11207;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마지막 전쟁 물자를 실리더스로 수송 중이며 하루 안에 도착할 거라고 들었소. 그 벌레들이 내 광산에 기어드는 꼴은 안 봤으면 좋겠소. 그러니 누군가 흐르는 모래의 홀을 짜 맞춘 다음 징을 울리고 성문을 열어 전쟁을 시작했으면 좋겠는데...', `MaleText_loc4`='我听说最后一批战争物资正在运往希利苏斯的途中，预定将在1天内抵达。我可不想看见那些虫子在我的矿井里爬行，希望有人尽快能修复流沙节杖，敲响铜锣，打开安其拉之门，迎接这场真正的战争。', `MaleText_loc5`='我聽說最後一批準備物資已經送往希利蘇斯，應該會在一天內到達。我可不想看到那群蟲子中的其中一隻挖通我的礦坑，所以我希望有人能快點收集流沙權杖並敲響銅鑼，讓大門敞開，點燃戰火。', `MaleText_loc7`='He oído que las últimas mercancías están de camino a Silithus y llegarán en menos de un día. No quiero ver uno de esos bichos hurgando en mi mina así que espero que alguien se ocupe de reconstruir el cetro del Mar de Dunas para poder golpear el gong, abrir las puertas y comenzar por fin la guerra.' WHERE `ID`=11208;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전쟁 물자를 실리더스로 수송 중이며 $2113w일 내로 도착할 거라고 들었소. 그 벌레들이 내 광산에 기어드는 꼴은 안 봤으면 좋겠소. 그러니 누군가 흐르는 모래의 홀을 짜 맞춘 다음 징을 울리고 성문을 열어 전쟁을 시작했으면 좋겠는데...', `MaleText_loc4`='我听说最后一批战争物资正在运往希利苏斯的途中，预定将在$2113w天内抵达。我可不想看见那些虫子在我的矿井里爬行，希望有人尽快能修复流沙节杖，敲响铜锣，打开安其拉之门，迎接这场真正的战争。', `MaleText_loc5`='我聽說最後一批準備物資已經送往希利蘇斯，應該會在$2113w天內到達。我可不想看到那群蟲子中的其中一隻挖通我的礦坑，所以我希望有人能快點收集流沙權杖並敲響銅鑼，讓大門敞開，點燃戰火。', `MaleText_loc7`='He oído que las últimas mercancías están de camino a Silithus y llegarán en menos de $2113w días. No quiero ver uno de esos bichos hurgando en mi mina así que espero que alguien se ocupe de reconstruir el cetro del Mar de Dunas para poder golpear el gong, abrir las puertas y comenzar por fin la guerra.' WHERE `ID`=11209;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 일은 다 끝났소. 이제 얼라이언스 측에서 물자 수집을 끝내기를 기다리는 일만 남았소. 그러고 나면 모든 물자를 실리더스로 옮길 수 있소이다.', `MaleText_loc4`='我们的工作完成了，现在只等联盟完成他们收集任务。在那之后，所有的战争物资都将被运往希利苏斯。', `MaleText_loc5`='我們的工作完成了。現在就等聯盟將物品運至希利蘇斯之前完成他們的部份。', `MaleText_loc7`='Hemos acabado el trabajo. Ahora esperemos a que la Alianza acabe el suyo antes de enviar todo a Silithus.' WHERE `ID`=11210;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누군가가 흐르는 모래의 홀을 하나로 합치면 벌레들과의 전쟁이 시작될 것이오. 생각만 해도 기분이 좋군! 우리의 마지막 전쟁 물자를 실리더스로 수송 중인데 하루 안에 도착할 것이오. 가서 호드에게 영광을 안겨주시오!', `MaleText_loc4`='如果有人能修复流沙节杖，跟异种虫类的战争也就不远了。我对此很感兴趣，$C！我们的战争物资正在运往希利苏斯的途中，预计将在1天内抵达。去吧，为了部落的荣誉而战！', `MaleText_loc5`='如果有人能將具有魔法的流沙之地權杖組合起來，那麼對抗異種軍隊的戰爭就會很快展開。我就等那一天，$c!我們最後一批物資也在送往希利蘇斯的路上，應該一天內就會到達。去為部落帶來榮耀吧!', `MaleText_loc7`='Si alguien ha reconstruido el cetro del Mar de Dunas, la guerra contra los bichos pronto dará comienzo. ¡Estupendo, $c! Los últimos materiales de guerra van de camino a Silithus y deberían estar allí en un día. ¡Ve trae honor a la Horda!' WHERE `ID`=11211;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누군가가 흐르는 모래의 홀을 하나로 합치면 벌레들과의 전쟁이 시작될 것이오. 생각만 해도 기분이 좋군! 우리의 마지막 전쟁 물자를 실리더스로 수송 중인데 $2113w일 내로 도착할 것이오. 가서 호드에게 영광을 안겨주시오!', `MaleText_loc4`='如果有人能修复流沙节杖，跟异种虫类的战争也就不远了。我对此很感兴趣，$C！我们的战争物资正在运往希利苏斯的途中，预计将在$2113w天内抵达。去吧，为了部落的荣誉而战！', `MaleText_loc5`='如果有人能將具有魔法的流沙之地權杖組合起來，那麼對抗異種軍隊的戰爭就會很快展開。我就等那一天，$c!我們最後一批物資也在送往希利蘇斯的路上，應該$2113w天內就會到達。去為部落帶來榮耀吧!', `MaleText_loc7`='Si alguien ha reconstruido el cetro del Mar de Dunas, la guerra contra los bichos pronto dará comienzo. ¡Estupendo, $c! Los últimos materiales de guerra van de camino a Silithus y deberían estar allí en $2113w días. ¡Ve trae honor a la Horda!' WHERE `ID`=11212;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영광의 날을 위한 우리의 준비는 완벽하게 마무리되었소! 우리가 모든 물자를 모아 실리더스로 보낼 준비를 끝내는 동안 약해 빠진 저 얼라이언스 측에서는 아직도 물자 수집도 끝내지 못하고 있소.', `MaleText_loc4`='$C，多么荣耀啊！那些联盟的家伙们还在拖拖拉拉，而我们已经完成了任务，准备将物资运往希利苏斯了。', `MaleText_loc5`='我們踏的是榮耀之路，$r!渺小的聯盟仍在努力搜刮他們的作戰物資，而我們早已收集完畢準備將物資送往希利蘇斯。', `MaleText_loc7`='¡El nuestro es un camino de gloria, $r! La endeble Alianza sigue intentando reunir sus provisiones para la guerra mientras que nosotros ya tenemos las nuestras y estamos listos para enviarlas a Silithus.' WHERE `ID`=11213;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 이 홀 조각을 파괴하면 어떻게 할 셈이지? 이 세계를 구원하는 일은 물거품이 되는 것인가?', `MaleText_loc4`='我在想，如果我设法摧毁了碎片，你们会怎么做？你们还能拯救世界吗？', `MaleText_loc5`='英雄們，我在想，當我將這個裂片摧毀後你會怎麼做?世界會再也無法得到救贖嗎?', `MaleText_loc7`='Me pregunto, valientes, qué haréis cuando consiga destruir este fragmento. ¿No habrá salvación para el mundo?' WHERE `ID`=11214;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 뭐지? 조각의 파편인가? 드디어 약점을 찾았군... 이제 금방 파괴할 수 있겠어.', `MaleText_loc4`='这是什么？节杖的碎片？终于有一个弱点暴露了……不会太久了。', `MaleText_loc5`='這是什麼?裂片上的一個缺口?終於，曝露了一個弱點...一切不遠了。', `MaleText_loc7`='¿Qué es esto? ¿Una muesca en el fragmento? Por fin un punto débil... No tardaré mucho.' WHERE `ID`=11215;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 칼림도어의 유일한 희망을 파괴하기 전에 너희가 나를 물리친다면 더없이 영광스럽겠지? 기대감에 현기증이 날 지경이군. 이제 곧... 홀 조각은 먼지가 될 것이다.', `MaleText_loc4`='在我摧毁整个卡利姆多的惟一希望之前，如果你能打败我，这会不会是一件很光荣的事儿呢？真期待啊。很快……很快一切都将灰飞烟灭。', `MaleText_loc5`='如果你不是在我毀了卡林多大陸唯一的希望之前擊敗我，會很不光榮嗎?預料世事讓我頭昏腦脹。很快...很快它就會化為塵土了。', `MaleText_loc7`='¿No sería maravilloso si de algún modo te las arreglaras para derrotarme pero no antes de que yo hubiera destruido la única esperanza que le queda a Kalimdor? No me llega el momento. Pronto... muy pronto será reducido a polvo.' WHERE `ID`=11216;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 부왕께서도 이런 비극적인... 대혼란을 계획하지 못하셨지... 너희들은 절대 성공하지 못할 것이다! 시간이 없단 말이다!', `MaleText_loc4`='即使是我的父亲也未曾预料到这样的悲剧……这可怕的混乱。你们是不可能成功的！没时间了！', `MaleText_loc5`='就連我父親都無法策劃這樣的悲劇...這樣的混亂。你不可能辦到的!沒有時間了!', `MaleText_loc7`='Ni mi padre hubiera podido imaginar esta tragedia... este caos. ¡Jamás lo conseguiréis! ¡El tiempo se agota!' WHERE `ID`=11217;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 홀을 보호하고 있던 막이 거의 사라졌군. 들리는가, 영웅들이여? 이 소리는... 이 소리는 결코 피할 수 없는 운명, 바로 너희들의 희망과 꿈이 나라는 존재에 의해 산산이 부서지는 소리다.', `MaleText_loc4`='啊，保护屏障就要消失了。英雄，你们听见了吗？那……那就是不可避免的宿命。你的希望和梦想在我面前是那么不堪一击。', `MaleText_loc5`='啊，保護層差點就不見了。你聽見了嗎，英雄們?那...那是必然的聲音。你的希望和夢想都將因我的存在而粉碎。', `MaleText_loc7`='¡Ah! La capa protectora casi ha desaparecido. ¿Ollen eso, valientes? Eso... es el sonido de lo inevitable. De sus esperanzas y sueños truncados por el peso de mi ser.' WHERE `ID`=11218;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='홀 파편은 더 이상 없다! 너희가 사랑하는 칼림도어는 곧 황량하고 버려진 땅이 될 것이다. 물론 나는 동부 왕국을 아무도 살지 못하는 잿더미로 만들어 버릴 것이다...', `MaleText_loc4`='节杖碎片已经不复存在了！你心爱的卡利姆多将很快成为一片荒芜的大地。当然，我会负责让东部王国也变成一片废墟的……', `MaleText_loc5`='權杖裂片什麼都不是了!你心愛的卡林多大陸很快就會變成一片荒蕪之地。當然，我還會將東部王國變成一個蒼白、無生氣的虛無世界...', `MaleText_loc7`='¡El fragmento de cetro es historia! Su amada Kalimdor pronto se convertirá en un lugar desolado. Y, por supuesto, haré de los Reinos del Este un lugar triste y sin vida.' WHERE `ID`=11219;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 곧 전쟁이 시작될 겁니다. 이 물자와 무기들을 실리더스의 세나리온 요새로 보내는 일만 남았는데 그것도 하루 안에 끝날 것입니다. 그러고 나면 용감한 영혼을 가진 자가 나서서 안퀴라즈 관문 근처의 징을 울리고 문을 열어 전쟁을 시작할 것입니다.', `FemaleText_loc4`='战争迫在眉睫。我们只需要将所有食物和武器运往希利苏斯的塞纳里奥要塞，货物将在1天内全部抵达。然后会有一位勇敢的人敲响铜锣，打开安其拉的大门，战争也就开始了。', `FemaleText_loc5`='戰爭即將來臨。現在要做的就是將所有物品和武器送到希利蘇斯的塞納里奧城堡，一天內就會到達。然後某個英勇的人就會敲響安其拉之門附近的銅鑼，開啟大門並點燃戰火。', `FemaleText_loc7`='La guerra pronto llegará. Lo único que falta es enviar toda esta mercancía y armas al Fuerte Cenarion en Silithus y eso lo haremos en el próximo día. Después algún valiente tendrá que hacer sonar el gong que está junto a Ahn''Qiraj para abrir sus puertas y dar comienzo a la guerra.' WHERE `ID`=11220;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 곧 전쟁이 시작될 겁니다. 이 물자와 무기들을 실리더스의 세나리온 요새로 보내는 일만 남았는데 그것도 $2113w일 내로 끝날 것입니다. 그러고 나면 용감한 영혼을 가진 자가 나서서 안퀴라즈 관문 근처의 징을 울리고 문을 열어 전쟁을 시작할 것입니다.', `FemaleText_loc4`='战争迫在眉睫。我们只需要将所有食物和武器运往希利苏斯的塞纳里奥要塞，货物将在$2113w天内全部抵达。然后会有一位勇敢的人敲响铜锣，打开安其拉的大门，战争也就开始了。', `FemaleText_loc5`='戰爭即將來臨。現在要做的就是將所有物品和武器送到希利蘇斯的塞納里奧城堡，$2113w天內就會到達。然後某個英勇的人就會敲響安其拉之門附近的銅鑼，開啟大門並點燃戰火。', `FemaleText_loc7`='La guerra pronto llegará. Lo único que falta es enviar toda esta mercancía y armas al Fuerte Cenarion en Silithus y eso lo haremos en los próximos $2113w días. Después algún valiente tendrá que hacer sonar el gong que está junto a Ahn''Qiraj para abrir sus puertas y dar comienzo a la guerra.' WHERE `ID`=11221;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 맡은 미스릴 주괴뿐만 아니라 호드에 필요한 모든 물자 수집이 완료되었습니다. 이제 얼라이언스의 준비가 끝나기만 기다리면 전쟁이 시작되는 것입니다!', `FemaleText_loc4`='我们不仅集齐了秘银锭，还完成了部落的所有收集任务。似乎我们只需等待联盟完成他们的任务，就能开战了！', `FemaleText_loc5`='不只我收集好所有需要的秘銀錠，整個部落的收集工作都已經完成了。看來我們就等聯盟準備好再開戰吧!', `FemaleText_loc7`='No solo tener todas las barras de mitril que necesitar, sino que la Horda ya reunir todo lo necesario. Parece que tener que esperar por la Alianza y después ¡a la guerra!' WHERE `ID`=11222;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그렇습니다, 젊은 $r|1이여;여;. 우리와 얼라이언스 연합 모두 안퀴라즈에서 벌어질 이번 전쟁에 필요한 물자 수집과 준비를 끝마쳤습니다. 지금 이 순간에도 세나리온 요새로 물자를 수송하는 중인데 하루 안에 마지막 물자가 도착할 것입니다. 물자가 모두 도착하면 관문을 열고 전쟁을 시작하기 위해 누군가 스카라베 제단의 징을 울려아 할 것입니다.', `FemaleText_loc4`='年轻的$C，是真的，我们和联盟都已经集齐安其拉一战所需的战争物资了。这些物资都在运往塞纳里奥要塞的途中，预计最后一批货物将在1天内抵达。一切就绪后，我们需要有人敲响甲虫墙上的铜锣，打开安其拉的大门，拉开战争的帏幕。', `FemaleText_loc5`='沒錯，年輕的$r，聯盟和我們都已準備好一切所需的東西面對即將來臨的安其拉之戰。現在這些東西都被送往塞納里奧城堡，而且最後一批在一天內就會到達了。等一切就緒，就要有人敲響甲蟲之台上的銅鑼，打開大門，點燃戰火。', `FemaleText_loc7`='Es cierto, joven $r, nosotros y la Alianza ya hemos reunido y preparado todo lo que vamos a necesitar para el inminente conflicto que tendrá lugar en Ahn''Qiraj. Todas las cosas están de camino al Fuerte Cenarion y el último envío debería llegar en el próximo día. Cuando todo esté en su sitio, alguien tendrá que hacer sonar el gong que situado en el Estrado del Escarabajo para abrir las puertas y dar comienzo a la guerra.' WHERE `ID`=11223;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그렇습니다, 젊은 $r|1이여;여;. 우리와 얼라이언스 연합 모두 안퀴라즈에서 벌어질 이번 전쟁에 필요한 물자 수집과 준비를 끝마쳤습니다. 지금 이 순간에도 세나리온 요새로 물자를 수송하는 중인데 $2113w일 내로 모든 물자가 도착할 것입니다. 모두 도착하면 누군가 스카라베 제단의 징을 울려서 성문을 열어야 전쟁을 시작할 수 있을 겁니다.', `FemaleText_loc4`='年轻的$C，是真的，我们和联盟都已经集齐安其拉一战所需的战争物资了。这些物资都在运往塞纳里奥要塞的途中，预计最后一批货物将在$2113w天内抵达。一切就绪后，我们需要有人敲响甲虫墙上的铜锣，打开安其拉的大门，拉开战争的帏幕。', `FemaleText_loc5`='沒錯，年輕的$r，聯盟和我們都已準備好一切所需的東西面對即將來臨的安其拉之戰。現在這些東西都被送往塞納里奧城堡，而且最後一批在$2113w天內就會到達了。等一切就緒，就要有人敲響甲蟲之台上的銅鑼，打開大門、點燃戰火。', `FemaleText_loc7`='Es cierto, joven $r, nosotros y la Alianza ya hemos reunido y preparado todo lo que vamos a necesitar para el inminente conflicto que tendrá lugar en Ahn''Qiraj. Todas las cosas están de camino al Fuerte Cenarion y el último envío debería llegar en los próximos $2113w días. Cuando todo esté en su sitio, alguien tendrá que hacer sonar el gong que situado en el Estrado del Escarabajo para abrir las puertas y dar comienzo a la guerra.' WHERE `ID`=11224;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$c|1이여;여;, 호드 쪽은 모두 끝났습니다. 현재 우리는 얼라이언스 측에서 물자 수집을 완료할 때까지 다른 준비를 하며 기다리는 중이랍니다.', `FemaleText_loc4`='部落已经完成了收集任务，$C。现在我们就只等联盟集齐他们的战争物资了。', `FemaleText_loc5`='部落的收集工作已經完成了，$c。現在我們就一邊等聯盟完成他們的收集工作，一邊做些額外的準備吧。', `FemaleText_loc7`='La Horda ha reunido toda sus mercancías, $c. Mientras la Alianza hace lo propio, ocupamos nuestro tiempo con preparativos adicionales.' WHERE `ID`=11225;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하신가? 이 펠레케이키 님 생각엔 모든 물자를 실리더스로 수송하고 있다는 사실을 자네만 모르고 있는 것 같군. 이 펠레케이키가 장담하는데 마지막 물자가 하루 안에 실리더스에 도착할 걸세. 그다음엔 어떤 멍청이가 안퀴라즈 관문 밖에 있는 징을 울려 성문을 열고 전쟁을 시작하려 하겠지.', `MaleText_loc4`='$C，比雷凯基认为你并不知道所有的物资已在运往希利苏斯的途中了。他说最后一批将在1天内运抵，然后，会有某个误入歧途的蠢货敲响安其拉大门外的铜锣，拉开战争的序幕。', `MaleText_loc5`='慢著，$c，比雷凱基認為你不知道所有的東西都在送往希利蘇斯的路上。比雷凱基要最後一批貨在一天內到達那裡，然後某個被誤導的笨蛋就要敲響安其拉之門外的銅鑼，開啟大門、點燃戰火。', `MaleText_loc7`='¡Vaya, $c! Pele''keiki cree que tú no tener ni idea de todo lo que está de camino a Silithus. Pele''keiki sabe que lo último llegará en menos de un día y después un pobre infeliz tocar el gong fuera de Ahn''Qiraj para abrir puertas y comenzar guerra.' WHERE `ID`=11226;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하신가? 이 펠레케이키 님 생각엔 모든 물자를 실리더스로 수송하고 있다는 사실을 자네만 모르고 있는 것 같군. 펠레케이키가 장담하는데 $2113w일 내로 마지막 물자가 실리더스에 도착할 걸세. 그다음엔 어떤 멍청이가 안퀴라즈 관문 밖에 있는 징을 울려 성문을 열고 전쟁을 시작하려 하겠지.', `MaleText_loc4`='$C，比雷凯基认为你并不知道所有的物资已在运往希利苏斯的途中了。他说最后一批将在$2113w天内运抵，然后，会有某个误入歧途的蠢货敲响安其拉大门外的铜锣，拉开战争的序幕。', `MaleText_loc5`='慢著，$c，比雷凱基認為你不知道所有的東西都在送往希利蘇斯的路上。比雷凱基要最後一批貨在$2113w天內到達那裡，然後某個被誤導的笨蛋就要敲響安其拉之門外的銅鑼，開啟大門、點燃戰火。', `MaleText_loc7`='¡Vaya, $c! Pele''keiki cree que tú no tener ni idea de todo lo que está de camino a Silithus. Pele''keiki sabe que lo último llegará en menos de $2113w días y después un pobre infeliz tocar el gong fuera de Ahn''Qiraj para abrir puertas y comenzar guerra.' WHERE `ID`=11227;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하, 자네 지금 날 놀리나? 펠레케이키는 자네도 우리 호드가 이미 전쟁에 필요한 물자를 다 모았다는 사실을 알고 있는 걸로 아는데... 지금 우린 얼라이언스가 일을 끝내고 전쟁을 시작할 수 있기만 기다리고 있네.', `MaleText_loc4`='哈哈，你是在开玩笑吧。比雷凯基知道部落已经集齐战争物资了。现在我们只等联盟完成他们的收集任务，就可以开战了！', `MaleText_loc5`='哈哈，你真愛說笑。比雷凱基知道你曉得我們部落已經有了所有戰爭所需要的東西。現在我們就等聯盟準備好他們的作戰物資，我們就能開戰了。', `MaleText_loc7`='¡Ja, ja, ja! Tú tomar el pelo, colega. Pele''keiki sabe que tú saber que la Horda ya tiene todo que necesitar para la guerra. Ahora esperar que Alianza igual y empezar ya la guerra.' WHERE `ID`=11228;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 몸이 죽을 운명이라면 내 마지막 숨결과 함께 너도 같이 황천으로 데려가겠다!', `MaleText_loc4`='如果我注定要死，那就让我死亡的气息把你们也带走！', `MaleText_loc5`='如果失敗是我的命運，那我拼著最後一口氣也要拖你一起走!', `MaleText_loc7`='¡Si mi destino es morir, con mi último aliento te llevaré conmigo!' WHERE `ID`=11229;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s의 웃음소리가 검은날개 둥지 안에 메아리칩니다.', `MaleText_loc4`='%s的笑声在黑翼之巢的大厅中回荡。', `MaleText_loc5`='%s的笑聲迴盪在黑翼大廳中。', `MaleText_loc7`='La risa de %s retumba en las salas de Alanegra.' WHERE `ID`=11230;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은날개 둥지 안에서 %s의 웃음소리가 다시 한번 크게 울려 퍼집니다.', `MaleText_loc4`='%s的笑声再次在黑翼之巢的大厅中回荡。', `MaleText_loc5`='黑翼大廳中又可以聽到%s的笑聲了。', `MaleText_loc7`='La risa de %s se oye de nuevo en las salas de Alanegra.' WHERE `ID`=11231;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 끝이 보이기 시작했네! 말한 대로 우리의 마지막 보급품을 실리더스로 수송하는 중인데 하루 안에 도착할 걸세. 수송이 완료되면 우리 모두 긴급 명령을 통해 소집되어 안퀴라즈 관문에 있는 징이 울릴 때까지 기다리게 될 게 틀림없지. 징이 울리면 전쟁이 시작될 것이고 그동안 우리가 준비한 것들이 어떤 활약을 할지 기대가 크다네.', `FemaleText_loc4`='大功告成！所有的战争物资将如约运往希利苏斯，货物将在1天内抵达。我想我们会迅速做好准备工作，然后等待有人敲响铜锣，打开安其拉的大门。我真想知道我们付出的努力在这场大战中会起到什么样的作用。', `FemaleText_loc5`='末日逼近!就在我們談話的同時，最後一批物資正被送往希利蘇斯，而且應該在一天內就會到達。等一切準備就緒，我們就等安其拉大門的銅鑼被敲響，然後開始作戰。我等著看我們的準備工作是否真有成效。', `FemaleText_loc7`='¡El final está cerca! Mientras hablamos, las últimas mercancías están de camino a Silithus y deberían llegar en el próximo día. Una vez allí estoy segura de que todo se dispondrá rápidamente y tendremos que esperar a oír el gong situado junto a las puertas de Ahn''Qiraj para comenzar la guerra. Estoy impaciente por descubrir si nuestros esfuerzos han valido la pena.' WHERE `ID`=11232;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 끝이 보이기 시작했네! 말한 대로 우리의 마지막 보급품을 실리더스로 수송하는 중인데 $2113w일 내로 도착할 걸세. 수송이 완료되면 우리 모두 긴급 명령을 통해 소집되어 안퀴라즈 관문에 있는 징이 울릴 때까지 기다리게 될 게 틀림없지. 징이 울리면 전쟁이 시작될 것이고 그동안 우리가 준비한 것들이 어떤 활약을 할지 기대가 크다네.', `FemaleText_loc4`='大功告成！所有的战争物资将如约运往希利苏斯，货物将在$2113w天内抵达。我想我们会迅速做好准备工作，然后等待有人敲响铜锣，打开安其拉的大门。我真想知道我们付出的努力在这场大战中会起到什么样的作用。', `FemaleText_loc5`='末日逼近!就在我們談話的同時，最後一批物資正被送往希利蘇斯，而且應該在$2113w天內就會到達。等一切準備就緒，我們就等安其拉大門的銅鑼被敲響，然後開始作戰。我等著看我們的準備工作是否真有成效。', `FemaleText_loc7`='¡El final está cerca! Mientras hablamos, nuestra mercancía está de camino a Silithus y debería llegar en los próximos $2113w días. Una vez allí estoy segura de que todo se dispondrá rápidamente y tendremos que esperar a oír el gong situado junto a las puertas de Ahn''Qiraj para comenzar la guerra. Estoy impaciente por descubrir si nuestros esfuerzos han valido la pena.' WHERE `ID`=11233;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그런 걸 물어보다니 자넨 책임감이 아주 강한 $c|1이로;로;군그래. 하지만 우리 호드는 물자 수집을 완료했어. 현재 얼라이언스 측에서 일을 끝내기만을 기다리고 있네. 얼라이언스만 끝나면 세나리온 요새 근처의 실리더스로 모든 물자를 옮길 예정이네.', `FemaleText_loc4`='你能这么问我很高兴，$C。但是部落已经完成了所有的收集工作。我们只需等待联盟那边完成他们的任务，然后所有的战争物资都将被运往希利苏斯的塞纳里奥要塞。', `FemaleText_loc5`='你這樣問相當有責任感，$c，但是部落的收集工作已全部完成。我們現在等著聯盟完成他們的準備，然後運送至希利蘇斯的塞納里奧城堡附近。', `FemaleText_loc7`='Sé que es tu deber preguntar, $c, pero la Horda ya ha reunido todo el material necesario. Ahora debemos esperar a que la Alianza haga su parte y así todos podremos llevar la mercancía a Silithus, en las inmediaciones del Fuerte Cenarion.' WHERE `ID`=11234;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자원 수집이 끝나고 완성된 물자를 실리더스로 옮기고 있습니다. 하루 안에 모든 물자를 옮길 수 있을 것 같습니다. 물자 수송이 완료되면 누군가 징을 울려 안퀴라즈 관문을 열어 주어야 합니다. 문이 열리면 드디어 성대하게 전쟁이 시작되는 것입니다.', `FemaleText_loc4`='所有的收集工作都完成了，战争物资将被运往希利苏斯。似乎在1天内货物就可全部抵达。然后，我们需要有人敲响铜锣，打开安其拉的大门。那时，真正的乐趣便开始了。', `FemaleText_loc5`='所有的收集都完成了，最後一批物品正被送往希利蘇斯。看來不到一天就能全部送達了。之後我們只需要讓某人敲響銅鑼、打開安其拉的大門。然後真正有趣的才開始呢。', `FemaleText_loc7`='Todos los trabajos de recogida de material han finalizado y a medida que los productos están listos, son enviados a Silithus. Parece que en menos de un día habremos acabado aquí. Tras eso, necesitaremos que alguien haga sonar el gong para abrir las puertas de Ahn''Qiraj. Entonces empezará la diversión.' WHERE `ID`=11235;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자원 수집이 끝나고 완성된 물자를 실리더스로 옮기고 있습니다. $2113w일 내로 모든 물자를 옮길 수 있을 것 같습니다. 물자 수송이 완료되면 누군가 징을 울려 안퀴라즈 관문을 열어 주어야 합니다. 문이 열리면 드디어 성대하게 전쟁이 시작되는 것입니다.', `FemaleText_loc4`='所有的收集工作都完成了，战争物资将被运往希利苏斯。似乎在$2113w天内货物就可全部抵达。然后，我们需要有人敲响铜锣，打开安其拉的大门。那时，真正的乐趣便开始了。', `FemaleText_loc5`='所有的收集都完成了，最後一批物品正被送往希利蘇斯。看來不到$2113w天就能全部送達了。之後我們只需要讓某人敲響銅鑼、打開安其拉的大門。然後真正有趣的才開始呢。', `FemaleText_loc7`='Todos los trabajos de recogida de material han finalizado y a medida que los productos están listos, son enviados a Silithus. Parece que en menos de $2113w días habremos acabado aquí. Tras eso, necesitaremos que alguien haga sonar el gong para abrir las puertas de Ahn''Qiraj. Entonces empezará la diversión.' WHERE `ID`=11236;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$c|1이여;여;, 안녕하십니까? 여태 모르셨나요? 호드는 물자 수집을 끝마쳤어요. 우리는 지금 얼라이언스가 물자 수집을 끝내기를 기다리며 마지막 준비를 마무리하고 있습니다. 얼라이언스가 일을 끝내면 모든 전쟁 물자를 실리더스로 보낼 것입니다.', `FemaleText_loc4`='嗨，$C，你不知道吗？部落已经集齐所有战争物资了。我们在进行最后的准备工作，只等联盟完成他们的收集任务了。在那之后，我们会将这些东西全部运往希利苏斯。', `FemaleText_loc5`='嘿，$c，你知道嗎?部落已經完成全部的收集工作。就在等待聯盟完成他們最後的收集工作時，我們也剛完成最後的準備。接下來就等著所有東西被送往希利蘇斯。', `FemaleText_loc7`='¡Eh, $c! ¿No lo sabes? La Horda ya ha reunido todo su material. Estamos ultimando los preparativos mientras esperamos a que la Alianza reúna el suyo. Después llegará el momento de enviar todo a Silithus para la guerra.' WHERE `ID`=11237;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='트롬카, $c|1이여;여;. 모든 전쟁 물자가 마지막 준비 단계에 있으며 실리더스로 옮겨지고 있네. 하루 안에 마지막 물자가 도착할 것이야. 장비가 준비되고 군대가 배치되면 우린 모두 누군가가 스카라베 제단에 있는 징을 울리기만 기다리고 있겠지. 징이 울리면 안퀴라즈 관문이 열리고 전쟁이 시작될 것일세.$B$B록타르 오가르!', `FemaleText_loc4`='你好，$C。所有的战争物资已经集齐，正在运往希利苏斯的途中。货物将在1天内运抵。一旦军队做好战前准备，我们就只等有人敲响甲虫墙上的铜锣，打开安其拉的大门。$B$B为了兽族！', `FemaleText_loc5`='(獸人語)你好，$c。所有的作戰物資都已做好最後的準備並開始運往希利蘇斯。最後一批應該在一天內就會到達。待裝備準備妥當，軍隊配置好，我們就只差一個人去敲響甲蟲之台上的銅鑼，隨即開啟安其拉的大門，點燃戰火。$B$B為了部落!', `FemaleText_loc7`='Throm''ka, $c. Se están ultimando y enviando las mercancías a Silithus. El último envío debería llegar en menos de un día. Con todo el equipamiento listo y las tropas desplegadas, tenemos que esperar a que alguien haga sonar el gong situado en el Estrado del Escarabajo de modo que se abran las puertas de Ahn''Qiraj y así dé comienzo la guerra.$B$B¡Lok''tar Ogar!' WHERE `ID`=11238;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='트롬카. 모든 전쟁 물자가 마지막 준비 단계에 있으며 실리더스로 옮겨지고 있네. 앞으로 $2113w일 내로 모든 물자가 도착할 것이네. 장비가 준비되고 군대가 배치되면 우린 모두 누군가가 스카라베 제단에 있는 징을 울리기만 기다리고 있겠지. 징이 울리면 안퀴라즈 관문이 열리고 전쟁이 시작될 것일세.$B$B록타르 오가르!', `FemaleText_loc4`='你好，$C。所有的战争物资已经集齐，正在运往希利苏斯的途中。货物将在接下来的$2113w天内运抵。一旦军队做好战前准备，我们就只等有人敲响甲虫墙上的铜锣，打开安其拉的大门。$B$B为了兽族！', `FemaleText_loc5`='(獸人語)你好，$c。所有的作戰物資都已做好最後的準備並開始運往希利蘇斯。最後一批應該在$2113w天內就會到達。待裝備準備妥當，軍隊配置好，我們就只差一個人去敲響甲蟲之台上的銅鑼，隨即開啟安其拉的大門，點燃戰火。$B$B為了部落!', `FemaleText_loc7`='Throm''ka, $c. Se están ultimando y enviando las mercancías a Silithus. Deberían llegar en el transcurso de los próximos $2113w días. Con todo el equipamiento listo y las tropas desplegadas, tenemos que esperar a que alguien haga sonar el gong situado en el Estrado del Escarabajo de modo que se abran las puertas de Ahn''Qiraj y así dé comienzo la guerra.$B$B¡Lok''tar Ogar!' WHERE `ID`=11239;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지금 우리 호드는 모든 자원 수집을 끝내고 대기하고 있네. 게으른 얼라이언스가 아직 일을 끝내지 못했기 때문이지. 얼라이언스만 끝나면 신나는 전투를 시작할 수 있을 게야!', `FemaleText_loc4`='我们已经完成了收集资源的工作，一切都准备就绪了。只等那些懒惰的联盟完成他们的任务，就能开战了！', `FemaleText_loc5`='部落現在準備好了，我們已經完成所有收集資源的工作。我們只等緩慢的聯盟完成他們的工作，然後打一場光榮的勝仗!', `FemaleText_loc7`='La Horda está lista ahora que ya hemos acabado de reunir los recursos necesarios. Ahora estamos esperando a que la Alianza consiga los suyos y después ¡todos a la batalla!' WHERE `ID`=11240;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 모든 물자 수집이 완료되었네. 우리가 모은 물자는 실리더스의 세나리온 요새로 옮겨지고 있는데 하루 안에 마지막 물자가 도착할 걸세. 수송 작업이 완료되고 용감하지만 바보 같은 누군가가 안퀴라즈 관문 바로 밖에 있는 징을 울리면 전쟁이 시작되겠지.', `MaleText_loc4`='$C，所有的战争物资都已经收集完毕，并且在运往希利苏斯塞纳里奥要塞的途中了。预计货物将在1天内抵达。一旦有人使用流沙节杖敲响铜锣，安其拉一战也就拉开序幕，孰喜孰悲啊……', `MaleText_loc5`='我們所有的收集工作都完成了，$c。我們收集的東西都被運送至希利蘇斯的塞納里奧城堡，最後一批應該會在一天內到達。等某個夠勇敢又夠笨的人敲響大門外的銅鑼，安其拉之戰就要開始了。', `MaleText_loc7`='Ya tenemos todo el material, $c. Todo lo que hemos reunido está siendo enviado al Fuerte Cenarion en Silithus y el último envío no debería tardar más de un día en llegar. La guerra de Ahn''Qiraj podrá dar comienzo cuando algún insensato valiente haga sonar el gong situado junto a las puertas.' WHERE `ID`=11241;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 모든 물자 수집이 완료되었네. 우리가 모은 물자는 실리더스의 세나리온 요새로 옮겨지고 있는데 $2113w일 내로 나머지 물자가 모두 도착할 걸세. 수송 작업이 완료되고 용감하지만 바보 같은 누군가가 안퀴라즈 관문 바로 밖에 있는 징을 울리면 전쟁이 시작되겠지.', `MaleText_loc4`='$C，所有的战争物资都已经收集完毕，并且在运往希利苏斯塞纳里奥要塞的途中了。预计货物将在$2113w天内抵达。一旦有人使用流沙节杖敲响铜锣，安其拉一战也就拉开序幕，孰喜孰悲啊……', `MaleText_loc5`='我們所有的收集工作都完成了，$c。我們收集的東西都被運送至希利蘇斯的塞納里奧城堡，最後一批應該會在$2113w天內到達。等某個夠勇敢又夠笨的人敲響大門外的銅鑼，安其拉之戰就要開始了。', `MaleText_loc7`='Ya tenemos todo el material, $c. Todo lo que hemos reunido está siendo enviado al Fuerte Cenarion en Silithus y el último envío no debería tardar más de un $2113w días en llegar. La guerra de Ahn''Qiraj podrá dar comienzo cuando algún insensato valiente haga sonar el gong situado junto a las puertas.' WHERE `ID`=11242;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 우리에겐 약간의 여유가 있을 것 같아. 호드는 물자 수집을 완료하고 최종 목적지인 실리더스로 옮기기 위한 준비를 하고 있네. 얼라이언스가 일을 끝내기를 기다리고 있지. 자네가 그들의 멍청하고 약해 빠진 사절에게 가서 얼마나 더 기다려야 하는지 좀 물어봐 주게.', `MaleText_loc4`='嗯，似乎我们还有一些时间。部落已经完成了收集任务，准备将战争物资运往希利苏斯了。我们只等联盟集齐他们所需的物资，你该去问问联盟那个愚蠢的大使，看看他们还需要多长时间。', `MaleText_loc5`='現在我們還有一點時間。部落完成了收集的工作，所有的東西都準備送往希利蘇斯。我們只等聯盟完成他們的工作。你應該去問問他們又矮又笨的大使，看看他們進度如何了。', `MaleText_loc7`='Bueno, parece que contamos con algo más de tiempo. La Horda ha finalizado sus tareas de recolección de material, que se está preparando para ser enviado a Silithus. Ahora solo nos queda esperar a que la Alianza haga lo mismo. Deberías preguntarle a ese que tienen por embajador cuánto tiempo van a tardar.' WHERE `ID`=11243;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모든 물자 수집을 끝마치고 실리더스로 옮기는 중이네. 하루 안에 마지막 물자가 도착할 것이고, 징이 울린 후 관문이 열리면 그동안의 우리의 노력이 아제로스의 생명을 구하고 많은 도움을 줄 수 있기를 바랄 뿐이네.', `MaleText_loc4`='$C，所有的战争物资都已经收集完毕，并且在运往希利苏斯的途中了。预计货物将在1天内抵达。我只希望铜锣敲响，安其拉之门打开后，我们的努力会有所回报，挽救更多的生命。', `MaleText_loc5`='所有的東西都收集好並送往希利蘇斯了，$c。最後一批應該會在一天內到達那裡。我只希望銅鑼被敲響、大門被打開之後，我們的努力能發揮效用，拯救許多性命。', `MaleText_loc7`='Ya hemos reunido todo el material y está siendo enviado a Silithus, $c. El último envío debería llegar allí en el próximo día. Solo me queda esperar que una vez que haya sonado el gong y las puertas se abran, nuestros esfuerzos hagan mella y ayuden a salvar muchas vidas.' WHERE `ID`=11244;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모든 물자 수집을 끝마치고 실리더스로 옮기는 중이네. $2113w일 내로 모든 물자가 도착할 걸세. 징이 울린 후 관문이 열리면, 그동안의 우리의 노력이 생명을 구하고 많은 도움을 줄 수 있기를 바랄 뿐이네.', `MaleText_loc4`='$C，所有的战争物资都已经收集完毕，并且在运往希利苏斯的途中了。预计货物将在$2113w天内抵达。我只希望铜锣敲响，安其拉之门打开后，我们的努力会有所回报，挽救更多的生命。', `MaleText_loc5`='所有的東西都收集好並送往希利蘇斯了，$c。最後一批應該會在$2113w天內到達那裡。我只希望銅鑼被敲響、大門被打開之後，我們的努力能發揮效用，拯救許多性命。', `MaleText_loc7`='Ya hemos reunido todo el material y está siendo enviado a Silithus, $c. Debería llegar allí en los próximos $2113w días. Solo me queda esperar que una vez que haya sonado el gong y las puertas se abran, nuestros esfuerzos hagan mella y ayuden a salvar muchas vidas.' WHERE `ID`=11245;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 우리 호드는 다가올 안퀴라즈 전쟁에서 우리가 할 수 있는 모든 준비를 마쳤네. 지금은 얼라이언스 측에서 일을 끝내기만 기다리고 있네. 얼라이언스의 준비만 끝나면 모든 전쟁 물자를 실리더스의 세나리온 요새로 옮길 예정이네.', `MaleText_loc4`='安其拉一战迫在眉睫，部落已经完成了所有的物资收集工作。$C，现在我们只需等待联盟完成任务。那时，我们就能将所有的战争物资运往希利苏斯的塞纳里奥要塞了。', `MaleText_loc5`='我們部落已經完成安其拉之戰能做的準備。現在我們就等，$c，等聯盟也一樣完成。等他們準備好，我們就會將所有的作戰物資運送至希利蘇斯的塞納里奧城堡。', `MaleText_loc7`='Los de la Horda ya hemos hecho todo lo que estaba en nuestras manos para prepararnos para la inminente guerra en Ahn''Qiraj. $C, ahora tenemos que esperar a que la Alianza haga lo mismo. Cuando hayan acabado enviaremos todos nuestros pertrechos al Fuerte Cenarion en Silithus.' WHERE `ID`=11246;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네, 제대로 들으신 겁니다. 모든 물자 수집이 끝나고 마지막 물자가 하루 안에 실리더스에 도착할 거예요. 물자가 모두 도착하고 군대가 준비되면 당신 정도의 실력을 갖춘 영웅 중 누군가가 안퀴라즈 밖에 있는 징을 울리게 될 거라고 들었답니다. 징을 울리려면 미리 흐르는 모래의 홀을 다시 맞춰야 한다고 하더군요. 너무 오래 기다리지 않았으면 좋겠군요.', `FemaleText_loc4`='是的，你的消息很准确，$C。我们已经完成了所有的收集工作，最后一批战争物资将在1天内运抵希利苏斯。据说一旦军队准备就绪，就将有一位英雄使用流沙节杖敲响安其拉大门外的铜锣。希望很快就能看到那一天。', `FemaleText_loc5`='是的，你沒聽錯，$c，我們所有的收集工作都已經完成，而最後一批作戰物資應該會在一天內到達希利蘇斯。我聽說一旦所有東西都到達那裡，我們的部隊準備好，你的軍隊裡的某個英雄就要敲響安其拉外面的銅鑼，當然還要有收集好的流沙權杖才能這麼做。', `FemaleText_loc7`='Sí, has oído bien, $c. Hemos reunido todo lo necesario y los últimos pertrechos deberían llegar a Silithus en el próximo día. Me han dicho que cuando todo esté preparado allí y nuestras tropas se hayan desplegado, algún valiente que haya conseguido reconstruir el cetro del Mar de Dunas lo usará para golpear el gong situado fuera de Ahn''Qiraj. Espero que no tengamos que esperar mucho para que eso ocurra.' WHERE `ID`=11247;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네, 제대로 들으신 겁니다. 모든 물자 수집이 끝나고 마지막 물자가 $2113w일 내로 실리더스에 도착할 거예요. 물자가 모두 도착하고 군대가 준비되면 당신 정도의 실력을 갖춘 영웅 중 누군가가 안퀴라즈 밖에 있는 징을 울리게 될 거라고 들었답니다. 징을 울리려면 미리 흐르는 모래의 홀을 다시 맞춰야 한다고 하더군요. 너무 오래 기다리지 않았으면 좋겠군요.', `FemaleText_loc4`='是的，你的消息很准确，$C。我们已经完成了所有的收集工作，最后一批战争物资将在$2113w天内运抵希利苏斯。据说一旦军队准备就绪，就将有一位英雄使用流沙节杖敲响安其拉大门外的铜锣。希望很快就能看到那一天。', `FemaleText_loc5`='是的，你沒聽錯，$c，我們所有的收集工作都已經完成，而最後一批作戰物資應該會在$2113w天內到達希利蘇斯。我聽說一旦所有東西都到達那裡，我們的部隊準備好，你的軍隊裡的某個英雄就要敲響安其拉外面的銅鑼，當然還要有收集好的流沙權杖才能這麼做。', `FemaleText_loc7`='Sí, has oído bien, $c. Hemos reunido todo lo necesario y los últimos pertrechos deberían llegar a Silithus en los próximos $2113w días. Me han dicho que cuando todo esté preparado allí y nuestras tropas se hayan desplegado, algún valiente que haya conseguido reconstruir el cetro del Mar de Dunas lo usará para golpear el gong situado fuera de Ahn''Qiraj. Espero que no tengamos que esperar mucho para que eso ocurra.' WHERE `ID`=11248;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이번에는 또 무슨 일인가요? 제가 그렇게 한가해 보여요? 호드는 물자 수집을 모두 끝마치고 현재 얼라이언스가 끝내기만을 기다리고 있어요. 차라리 이 시간에 스카라베 제단에 있는 징을 울릴 흐르는 모래의 홀의 파편들이라도 찾아보는 게 어때요? 그래야, 전쟁 준비가 모두 끝나면 안퀴라즈의 관문을 열어 전쟁을 시작할 수 있을 거 아니에요.', `FemaleText_loc4`='$C，我并不是一直这么空闲的。部落已经完成了收集任务，只等联盟完成他们的工作。或许你应该出发寻找流沙节杖的碎片，这样你才能敲响甲虫墙上的铜锣，打开安其拉的大门，拉开战争的序幕。', `FemaleText_loc5`='有什麼事嗎，$c，我還不夠忙嗎?部落已經完成收集工作，現在只等聯盟快點跟上。或許你該到外面找找流沙權杖碎片，這樣你才能敲響甲蟲之台的銅鑼，打開安其拉的大門並點燃戰火?', `FemaleText_loc7`='¿Qué pasa ahora, $c? ¡No tengo todo el día! La Horda ya ha reunido todo lo necesario y ahora está a la espera de que la Alianza se organice y haga lo mismo. Quizás deberías buscar los pedazos del cetro del Mar de Dunas para reconstruirlo y así hacer sonar el gong situado en el Estrado del Escarabajo para abrir las puertas de Ahn''Qiraj y dar comienzo a la guerra.' WHERE `ID`=11249;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 모든 준비가 끝났습니다. 마지막 물자가 실리더스에 도착하기를 기다리고 있는데 하루 안에 도착할 것입니다. 실리더스에서 군대가 조직되면 누군가 흐르는 모래의 홀을 사용하여 스카라베 제단에 있는 징을 울려야 할 것입니다. 그러면 안퀴라즈 전쟁이 시작되는 것이지요. 대지모신께서 우리를 굽어살피시길.', `FemaleText_loc4`='所有的收集工作都结束了，$C。这些物资将在1天内运抵希利苏斯。一旦准备工作就绪，就会有人使用流沙节杖敲响甲虫墙上的铜锣，打开安其拉的大门。愿大地之母守护我们。', `FemaleText_loc5`='現在所有的準備工作都完成了，$c。我們就等最後一批物資被送到希利蘇斯，應該一天內就會到達了。等到那邊的組織工作完成，就要有人用流沙權杖敲響甲蟲之台的銅鑼。那時候安其拉之戰就會開始。願大地之母守護著我們。', `FemaleText_loc7`='Hemos acabado con los preparativos, $c. Estamos a la espera de que se haga el último envío de pertrechos a Silithus, que debería llegar en menos de un día. Y una vez que todo esté organizado allí, alguien tendrá que hacer sonar el gong situado en el Estrado del Escarabajo con el cetro del Mar de Dunas. ¡En ese momento comenzará la guerra de Ahn''Qiraj! Que la Madre Tierra vele por todos nosotros.' WHERE `ID`=11250;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 모든 준비가 끝났습니다. 마지막 물자가 실리더스에 도착하기를 기다리고 있는데 $2113w일 내로 도착할 것입니다. 실리더스에서 군대가 조직되면 누군가 흐르는 모래의 홀을 사용하여 스카라베 제단에 있는 징을 울려야 할 것입니다. 그러면 안퀴라즈 전쟁이 시작되는 것이지요. 대지모신께서 우리를 굽어살피시길.', `FemaleText_loc4`='所有的收集工作都结束了，$C。这些物资将在$2113w天内运抵希利苏斯。一旦准备工作就绪，就会有人使用流沙节杖敲响甲虫墙上的铜锣，打开安其拉的大门。愿大地之母守护我们。', `FemaleText_loc5`='現在所有的準備工作都完成了，$c。我們就等最後一批物資被送到希利蘇斯，應該$2113w天內就會到達了。等到那邊的組織工作完成，就要有人用流沙權杖敲響甲蟲之台的銅鑼。那時候安其拉之戰就會開始。願大地之母守護著我們。', `FemaleText_loc7`='Hemos acabado con los preparativos, $c. Estamos a la espera de que se haga el último envío de pertrechos a Silithus, que debería llegar en menos de $2113w días. Y una vez que todo esté organizado allí, alguien tendrá que hacer sonar el gong situado en el Estrado del Escarabajo con el cetro del Mar de Dunas. ¡En ese momento comenzará la guerra de Ahn''Qiraj! Que la Madre Tierra vele por todos nosotros.' WHERE `ID`=11251;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대지모신을 섬기고 호드를 위해 봉사하는 것이 제 삶의 목적이지만 우리에게 필요한 모든 물자를 모았다는 사실에 가슴이 조금은 떨립니다. 얼라이언스가 물자 수집을 끝마칠 때까지 우리에겐 약간의 시간이 있습니다. 얼라이언스가 일을 끝내면 실리더스의 세나리온 요새로 모든 물자를 옮길 것이고 그러면 머지않아 전쟁이 시작될 것입니다.', `FemaleText_loc4`='我活着的目的就是为大地之母和部落服务，虽然眼下我们已经收集到足够的物资，但是我还是有些担心。在联盟完成他们的收集任务之前，我们还有一点准备时间。在那之后，所有的物资将被运往希利苏斯的塞纳里奥要塞，我们离战争也就不远了。', `FemaleText_loc5`='雖然我生來就是要為大地之母及部落效忠，但我仍忍不住感到有點緊張，因為我們已經收集好全部需要的東西了。在聯盟完成他們的收集工作前我們還有一點時間。在那之後，所有的東西就會被送到希利蘇斯的塞納里奧城堡，然後戰爭就離我們不遠了。', `FemaleText_loc7`='Vivo para servir a la Madre Tierra y a la Horda pero no puedo evitar sentirme inquieta ahora que ya hemos reunido todo lo que necesitamos. Al menos contamos con algo de tiempo hasta que la Alianza acabe con su parte. Tras eso enviaremos todo al Fuerte Cenarion en Silithus y la guerra no tardará mucho en comenzar.' WHERE `ID`=11252;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그래, 그렇다네. 호드와 얼라이언스의 모든 전쟁 물자가 실리더스로 옮겨지고 있고 하루 안에 완료될 걸세. 그다음엔 어떻게 되는지 알고 있나? 우린 서둘러 준비를 마치고 기다려야 한다네. 부디 누군가 흐르는 모래의 홀의 파편들을 모으고 있기를 바랄 뿐이지. 안퀴라즈 관문을 열려면 흐르는 모래의 홀을 사용해서 스카라베 제단의 징을 울려야 하기 때문일세.', `FemaleText_loc4`='是的，是的，部落和联盟的所有战争物资正在运往希利苏斯的途中，预定将在1天内抵达。你知道接下来会发生什么吗，$C？我们得加快速度了。希望有人能集齐流沙节杖的碎片，敲响甲虫之墙上的铜锣，打开安其拉的大门。', `FemaleText_loc5`='對，沒錯，所有部落和聯盟的物資將會被送到希利蘇斯，而且應該一天內就會到達。然後你知道會發生什麼事嗎，$c?我們加緊腳步然後等待。希望有人正在收集流沙權杖碎片，因為要打開安其拉大門就要先敲響甲蟲之台的銅鑼。', `FemaleText_loc7`='Sí, sí, todo el material de guerra de la Horda y la Alianza está de camino a Silithus y debería estar allí en un día. ¿Y sabes qué pasará después, $c? Nos apresuramos y esperamos. Con suerte alguien reunirá los fragmentos del cetro del Mar de Dunas pues para abrir las puertas de Ahn''Qiraj es necesario golpearlo contra el gong del Estrado del Escarabajo.' WHERE `ID`=11253;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그래, 그렇다네. 호드와 얼라이언스의 모든 전쟁 물자가 실리더스로 옮겨지고 있고 $2113w일 내로 완료될 걸세. 그다음엔 어떻게 되는지 알고 있나? 우린 서둘러 준비를 마치고 기다려야 한다네. 부디 누군가 흐르는 모래의 홀의 파편들을 모으고 있기를 바랄 뿐이지. 안퀴라즈 관문을 열려면 흐르는 모래의 홀을 사용해서 스카라베 제단의 징을 울려야 하기 때문일세.', `FemaleText_loc4`='是的，是的，部落和联盟的所有战争物资正在运往希利苏斯的途中，预定将在$2113w天内抵达。你知道接下来会发生什么吗，$C？我们得加快速度了。希望有人能集齐流沙节杖的碎片，敲响甲虫之墙上的铜锣，打开安其拉的大门。', `FemaleText_loc5`='對，沒錯，所有部落和聯盟的物資將會被送到希利蘇斯，而且應該$2113w天內就會到達。然後你知道會發生什麼事嗎，$c?我們加緊腳步然後等待。希望有人正在收集流沙權杖碎片，因為要打開安其拉大門就要先敲響甲蟲之台的銅鑼。', `FemaleText_loc7`='Sí, sí, todo el material de guerra de la Horda y la Alianza está de camino a Silithus y debería estar allí en $2113w días. ¿Y sabes qué pasará después, $c? Nos apresuramos y esperamos. Con suerte alguien reunirá los fragmentos del cetro del Mar de Dunas pues para abrir las puertas de Ahn''Qiraj es necesario golpearlo contra el gong del Estrado del Escarabajo.' WHERE `ID`=11254;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$c, 무슨 일인가? 우리 호드는 물자 수집을 모두 끝내고 얼라이언스가 끝마칠 때까지 마지막 준비를 진행하는 중인데... 뭐, 필요한 거라도 있나?', `FemaleText_loc4`='怎么了，$C？部落已经完成了所有的收集工作，在等到联盟完成他们的收集任务时，我们可以进行最后的准备工作。你还需要什么吗？', `FemaleText_loc5`='什麼事嗎，$c?部落已經完成收集工作，聯盟也在努力跟上進度做最後的準備。你還需要什麼嗎?', `FemaleText_loc7`='¿Qué ocurre, $c? La Horda está reuniendo todo su material y está ultimando los preparativos mientras la Alianza intenta seguir su ritmo. ¿Necesitas algo más?' WHERE `ID`=11255;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳의 모든 전쟁 물자가 실리더스 사막으로 옮겨질 테니 낚시를 할 수 있는 시간도 이제 하루밖에 남지 않은 것 같군요. 물자를 모두 옮기고 준비를 끝내면 관문을 열고 전쟁을 시작하기 위해 누군가가 세나리온 요새 남쪽에 있는 징을 울려야 할 것입니다.', `MaleText_loc4`='我们似乎只须再等一天了，所有的战争物资都将被运往希利苏斯沙漠。一切准备就绪之后，将会有人敲响塞纳里奥要塞南边的铜锣，打开安其拉之门，拉开战争的序幕。', `MaleText_loc5`='看來在所有的作戰物眾被送到希利蘇斯沙漠之前只剩一天可以釣魚了。然後一切準備好時，有人就要敲響塞納里奧城堡南邊的銅鑼鼓來打開大門，開啟戰爭。', `MaleText_loc7`='Parece que solo queda un día más para pescar antes de que todo el material de guerra se envíe al desierto de Silithus, colega. Después prepararán todo y alguien hará sonar el gong situado en la parte sur del Fuerte Cenarion para abrir las puertas y comenzar la guerra.' WHERE `ID`=11256;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳의 모든 전쟁 물자가 실리더스 사막으로 옮겨질 테니 낚시를 할 수 있는 시간도 이제 $2113w일밖에 남지 않은 것 같군요. 물자를 모두 옮기고 준비를 끝내면 관문을 열고 전쟁을 시작하기 위해 누군가가 세나리온 요새 남쪽에 있는 징을 울려야 할 것입니다.', `MaleText_loc4`='我们似乎只须再等$2113w天了，所有的战争物资将被运往希利苏斯沙漠。一切准备就绪之后，将会有人敲响塞纳里奥要塞南边的铜锣，打开安其拉之门，拉开战争的序幕。', `MaleText_loc5`='看來在所有的作戰物眾被送到希利蘇斯沙漠之前只剩$2113w天可以釣魚了。然後一切準備好時，有人就要敲響塞納里奧城堡南邊的銅鑼鼓來打開大門，開啟戰爭。', `MaleText_loc7`='Parece que solo quedan $2113w días más para pescar antes de que todo el material de guerra se envíe al desierto de Silithus, colega. Después prepararán todo y alguien hará sonar el gong situado en la parte sur del Fuerte Cenarion para abrir las puertas y comenzar la guerra.' WHERE `ID`=11257;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스보다 일이 빠르게 진행되었으니 우린 좀 쉬어도 될 것 같습니다. 이곳의 물자 수집 일은 모두 끝났고 마무리 준비를 하고 있습니다. 아이언포지의 얼라이언스들이 일을 다 마치면 모든 물자를 실리더스로 옮길 생각입니다. 그때까지 자리 잡고 낚시나 좀 즐기는 게 어떻습니까?', `MaleText_loc4`='可以好好休息啦，联盟远远落在了后面。我们已经完成了收集工作，只需等待装运物资了。当联盟完成铁炉堡的物资储备后，我们就能将这些东西运往希利苏斯了。到那时，我们或许还可以去钓钓鱼。', `MaleText_loc5`='該是休息的時候了，聯盟遠遠落後了我們。我們這裡的收集工作都完成了，最後的完善工作也在這時候進行著。等他們在鐵爐堡裡忙完，我們就能把這些東西運到希利蘇斯。在那之前就先釣些魚吧。', `MaleText_loc7`='Es tiempo de relajarse porque la Alianza va con retraso, colega. Nosotros ya hemos acabado y estamos con los últimos retoques. Cuando ellos acaben en Forjaz, tendremos que pensar en llevar todo esto hasta Silithus. Hasta entonces, tienes que esperar y quizás puedas pescar un poco.' WHERE `ID`=11258;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드와 얼라이언스 연합 모두 물자 수집을 완료했다고 들었다면 제대로 들은 것이오. 우리가 수집하고 준비한 물자를 현재 실리더스의 세나리온 요새로 옮기는 중이오. 아마 하루 안에 마지막 물자가 도착할 것이오. 물자가 모두 도착하면 아마도 우리는 누군가 홀을 짜 맞춰서 징을 울릴 때까지 기다려야 할 것이오. 징이 울리면 안퀴라즈의 관문이 열리고 전쟁이 시작될 것이오.', `MaleText_loc4`='部落和联盟的收集任务都完成了，没错，$C。所有的战争物资都在运往希利苏斯塞纳里奥要塞的途中，预计在1天内就可全部抵达。我想我们只需等待有人修复流沙节杖，敲响铜锣，打开安其拉的大门，拉开战争的序幕。', `MaleText_loc5`='如果你聽說部落和聯盟的收集工作都已完成，那麼你沒聽錯，$c。所有我們準備的作戰物資現在都正被送到希利蘇斯的塞納里奧城堡，最後一批貨物會在一天內送達。在那之後我們就耐心等待，看看誰會重組權杖敲響銅鑼，進而打開安其拉的大門、點燃戰火。', `MaleText_loc7`='Si te han dicho que la Horda y la Alianza ya han reunido todo lo necesario, te han informado bien, $c. Todas las mercancías para la guerra que hemos reunido y preparado están siendo enviadas al Fuerte Cenarion en Silithus y en menos de un día el último envío llegará allí. Después supongo que simplemente tendremos que esperar a ver quién reconstruye el cetro con el que hay que golpear el gong para abrir las puertas de Ahn''Qiraj y anunciar la guerra.' WHERE `ID`=11259;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드와 얼라이언스 모두 물자 수집을 완료했다고 들었다면 제대로 들은 것이오. 우리가 수집하고 준비한 물자를 현재 실리더스의 세나리온 요새로 옮기는 중이오. $2113w일 내로 마지막 물자가 도착할 것이오. 물자가 모두 도착하면 아마도 우리는 누군가 홀을 짜 맞춰서 징을 울릴 때까지 기다려야 할 것이오. 징이 울리면 안퀴라즈의 관문이 열리고 전쟁이 시작될 것이오.', `MaleText_loc4`='部落和联盟的收集任务都完成了，没错，$C。所有的战争物资都在运往希利苏斯塞纳里奥要塞的途中，预计在$2113w天内就可全部抵达。我想我们只需等待有人修复流沙节杖，敲响铜锣，打开安其拉的大门，拉开战争的序幕。', `MaleText_loc5`='如果你聽說部落和聯盟的收集工作都已完成，那麼你沒聽錯，$c。所有我們準備的作戰物資現在都正被送到希利蘇斯的塞納里奧城堡，最後一批貨物會在$2113w天內送達。在那之後我們就耐心等待，看看誰會重組權杖敲響銅鑼，進而打開安其拉的大門、點燃戰火。', `MaleText_loc7`='Si te han dicho que la Horda y la Alianza ya han reunido todo lo necesario, te han informado bien, $c. Todas las mercancías para la guerra que hemos reunido y preparado están siendo enviadas al Fuerte Cenarion en Silithus y en menos de $2113w días el último envío llegará allí. Después supongo que simplemente tendremos que esperar a ver quién reconstruye el cetro con el que hay que golpear el gong para abrir las puertas de Ahn''Qiraj y anunciar la guerra.' WHERE `ID`=11260;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='젊은 $c|1이여;여;, 호드의 전쟁 물자 수집은 모두 완료되었소. 지금은 얼라이언스가 물자 수집을 완료하기를 기다리는 일만 남았소. 얼라이언스의 준비가 완료되면 안퀴라즈 전쟁을 위한 모든 준비가 끝나는 것이오. 흐르는 모래의 홀의 파편들을 모아서 다시 합치는 일만 빼고 말이오.', `MaleText_loc4`='年轻的$C，部落已经完成了收集工作。我们只需等待联盟完成任务，安其拉一战的准备工作也就差不多了，当然，除了修复流沙节杖的事儿。', `MaleText_loc5`='部落所有的工作都已完成了，年輕的$c。現在我們只需要等待聯盟也完成他們的工作，然後一切就等安其拉開戰了。或許還要等流沙權杖收集、重組好?', `MaleText_loc7`='La Horda ya ha finalizado sus trabajos de recolección de mercancías para la guerra, joven $c. Ahora solo tenemos que esperar a que la Alianza también lo haga y entonces estaremos listos para la guerra de Ahn''Qiraj. Excepto, quizás, por la reunificación de los fragmentos del cetro del Mar de Dunas...' WHERE `ID`=11261;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇소. 모든 전쟁 물자를 실리더스로 옮기는 중인데 하루 안에 마지막 물자가 도착할 거요. 물자가 모두 도착하면 아제로스의 영웅이라 할만한 자가 나타나 흐르는 모래의 홀을 복원해 스카라베 제단의 징을 울리기만을 기다려야 하오. 반드시 안퀴라즈의 관문이 열려야 전쟁을 시작할 수 있소.', `MaleText_loc4`='是的，嗯，$G小伙子:姑娘;，所有的战争物资都在运往希利苏斯的途中，预计将在1天内全部抵达。我们只需等待某位英雄修复流沙节杖，敲响甲虫之台的铜锣，打开安其拉之门，拉开战争的序幕。', `MaleText_loc5`='沒錯，嗯，$g小夥子:小姑娘;，所有的作戰物資都被送往希利蘇斯，而最後一批應該一天內就會送達。在那之後，我們就要等著看哪個$g英雄:女豪傑;會重組流沙權杖，並敲響甲蟲之台上的銅鑼。只有那個時候安其拉的大門才會敞開，戰爭才會開始。', `MaleText_loc7`='Es cierto, $gmuchacho: muchacha;, toda la mercancía está de camino a Silithus y el último envío debería llegar allí en el próximo día. Después, simplemente tendremos que esperar a ver quién envía a un valiente para que reconstruya el cetro del Mar de Dunas y haga sonar el gong situado en el Estrado del Escarabajo. Solo en ese momento dará comienzo la guerra al abrirse las puertas de Ahn''Qiraj.' WHERE `ID`=11262;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇소. 모든 전쟁 물자를 실리더스로 옮기는 중인데 $2113w일 내로 마지막 물자가 도착할 거요. 그 후 아제로스의 영웅이라 할만한 자가 나타나 흐르는 모래의 홀을 복원해 스카라베 제단의 징을 울리기만을 기다려야 하오. 반드시 안퀴라즈로 가는 관문이 열려야 전쟁을 시작할 수 있소.', `MaleText_loc4`='是的，嗯，$G小伙子:姑娘;，所有的战争物资都在运往希利苏斯的途中，预计将在$2113w天内全部抵达。我们只需等待某位英雄修复流沙节杖，敲响甲虫之台的铜锣，打开安其拉之门，拉开战争的序幕。', `MaleText_loc5`='沒錯，嗯，$g小夥子:小姑娘;，所有的作戰物資都被送往希利蘇斯，而最後一批應該$2113w天內就會送達。在那之後，我們就要等著看哪個$g英雄:女豪傑;會重組流沙權杖，並敲響甲蟲之台上的銅鑼。只有那個時候安其拉的大門才會敞開，戰爭才會開始。', `MaleText_loc7`='Es cierto, $gmuchacho: muchacha;, toda la mercancía está de camino a Silithus y el último envío debería llegar allí en los próximos $2113w días. Después, simplemente tendremos que esperar a ver quién envía a un valiente para que reconstruya el cetro del Mar de Dunas y haga sonar el gong situado en el Estrado del Escarabajo. Solo en ese momento dará comienzo la guerra al abrirse las puertas de Ahn''Qiraj.' WHERE `ID`=11263;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스가 전쟁 물자 수집을 모두 끝냈다는 것이 사실이라고 해도 너무 실망하지는 말게. 무엇보다 중요한 것이 시간이긴 하지만 자넨 온 힘을 다해 호드의 물자 수집을 돕지 않았나? 실제 전쟁이 벌어진 상황에서 동료의 목숨을 위험에 빠뜨릴 수 있는 실수를 하는 것보다는 자네처럼 후방에서 철저하게 임무를 완수하는 것이 더 중요하다고 생각하네. $c|1이여;여;, 자네도 그렇게 생각하지 않나?', `MaleText_loc4`='虽然联盟已经完成了所有的收集工作，但是别气馁，$R。进度固然很重要，不过我还是要感谢你帮助我们如此仔细地收集物资。我可不愿意因为小小的失误令士兵们丧命。你说是吗，$C？', `MaleText_loc5`='雖然聯盟的確完成了他們的收集工作，別因為這件事就讓你沮喪，$r。時間是非常重要的，但是我們寧願你仔細、徹底地幫助部落收集物資。這對我而言比讓許多人在戰爭真正開打時失去性命來的好多了。你說是嗎，$c?', `MaleText_loc7`='Aunque es cierto que la Alianza ya ha finalizado sus trabajos de recolección de material, no dejes que eso te desanime, $r. El tiempo es un factor clave pero nos gustaría que ayudaras en la recogida de provisiones de la Horda de manera cuidadosa y prestando mucha atención. Considero que es mejor que cometer un error que le pueda costar la vida a alguien una vez que la verdadera guerra haya comenzado. ¿Estás de acuerdo conmigo, $c?' WHERE `ID`=11264;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='홀 파편을 되찾아야 한다, $n. 네파리우스가 홀 파편을 파... 파괴하도록 내버려 둬서는 안 된다.', `MaleText_loc4`='取回节杖碎片，$n。绝对不能让奈法里奥斯摧……摧毁碎片。', `MaleText_loc5`='將流沙之地權杖裂片恢復原狀，$n。奈法利斯絕不允許摧...摧毀裂片。', `MaleText_loc7`='Recupera el fragmento de cetro, $n. No podemos permitir que Nefarius lo... lo destruya.' WHERE `ID`=11265;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그의 시체를 갈라 홀 조각을 꺼낼 오겠습니다.', `MaleText_loc4`='我会从他破碎的尸体中取出碎片的。', `MaleText_loc5`='我會將裂片從他碎裂的屍體中拿出來。', `MaleText_loc7`='Le arrebataré el fragmento a ese cadáver.', `FemaleText_loc1`='그의 시체를 갈라 홀 조각을 꺼내오겠어요.', `FemaleText_loc4`='我会从他破碎的尸体中取出碎片的。', `FemaleText_loc5`='我會將裂片從他碎裂的屍體中拿出來。', `FemaleText_loc7`='Le arrebataré el fragmento a ese cadáver.' WHERE `ID`=11266;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 이걸 봐라! [붉은색 홀 파편] 어디 할 수 있다면 빼앗아 보아라... 하하하!', `MaleText_loc4`='你在找这个[红色节杖碎片]吗？过来取吧……', `MaleText_loc5`='在找:[紅色權杖裂片]嗎?來拿吧...', `MaleText_loc7`='¿Buscas: [el fragmento de cetro rojo]? Ven a cogerlo...' WHERE `ID`=11267;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 일에 참견하는 것도 여기까지다. 필멸의 존재여! 나는 위대한 타락자 잔디비어스 님이시다!', `MaleText_loc4`='凡人，你再也没机会插手恶魔的事务了！和沙迪维尔斯做个了断吧！', `MaleText_loc5`='現在開始你不能再干預惡魔事務了，人類!面對偉大的墮落者吧 -  沙迪維爾斯!', `MaleText_loc7`='¡Tu intromisión en asuntos demoníacos acaba AQUÍ, mortal! ¡Enfréntate al gran corruptor, Xandivious!' WHERE `ID`=11268;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악몽을 막을 수는 없다!', `MaleText_loc4`='梦魇是不可抵挡的！', `MaleText_loc5`='我們無法阻止夢魘!', `MaleText_loc7`='¡Nadie podrá detener a la Pesadilla!' WHERE `ID`=11269;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; $n의 마지막 생명력까지 모조리 짜내어 영혼을 집어삼킵니다.', `MaleText_loc4`='%s夺走$n的最后一丝气息，吞噬了他们的灵魂。', `MaleText_loc5`='%s將$n的最後一點生命榨乾然後吞下他們的靈魂。', `MaleText_loc7`='%s pone fin al último resquicio de vida de $n y se traga su alma.' WHERE `ID`=11270;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오너라, $n. 악몽의 결과가 어떤 것인지 보여 주마...', `MaleText_loc4`='来吧，$n。看看梦魇给你带来了什么……', `MaleText_loc5`='來吧，$n。看看夢魘帶來了什麼...', `MaleText_loc7`='Ven, $n. Mira lo que trae la Pesadilla...' WHERE `ID`=11271;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오싹한 기운이 도는걸...', `MaleText_loc4`='空中掠过了一阵寒风。', `MaleText_loc5`='空氣中帶著一股寒意。', `MaleText_loc7`='Hace frío.', `FemaleText_loc1`='오싹한 기운이 도는걸...', `FemaleText_loc4`='空中掠过了一阵寒风。', `FemaleText_loc5`='空氣中帶著一股寒意。', `FemaleText_loc7`='Hace frío.' WHERE `ID`=11272;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 스랄 님을 모신다는 데 큰 자부심을 가지고 있다. 적을 무찌르는 일에 필요하다면 아무리 먼 곳이라도 기꺼이 떠날 각오가 되어 있다.', `MaleText_loc4`='我们以能为萨尔效劳而感到骄傲。我们将不惜一切代价，消灭我们的敌人！', `MaleText_loc5`='我們以無比的驕傲效忠索爾。我們會盡所能消滅敵人。', `MaleText_loc7`='Servimos con orgullo a Thrall. Viajaremos tan lejos como sea necesario para derrotar al enemigo.' WHERE `ID`=11273;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='임무 보고합니다.', `MaleText_loc4`='长官！', `MaleText_loc5`='為職責報告，長官。', `MaleText_loc7`='Me presento ante usted, señor.', `FemaleText_loc1`='임무 보고합니다.', `FemaleText_loc4`='长官！', `FemaleText_loc5`='為職責報告，長官。', `FemaleText_loc7`='Me presento ante usted, señor.' WHERE `ID`=11274;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='때맞춰 도착했군. 발밑의 땅이 흔들리는 것이 느껴지는가?$B$B곤충 집에서 뭔가 접근하고 있다.$B$B그런트 옆으로 가서 자리 잡도록, $n. 자네에게 거는 기대가 크노라!', `MaleText_loc4`='你来得正是时候，$C。你感觉到脚下的大地在颤抖了吗？$B$B虫巢里的敌人正在逼近我们。站到步兵旁边去，$n。我就指望你了！', `MaleText_loc5`='你來的正是時候，$c。你感覺到身後的地表震動嗎?$B$B有東西從蟲巢逼近了。守住你的崗位吧，$n。我靠你了!', `MaleText_loc7`='Llegas justo a tiempo, $c. ¿Sientes cómo tiembla el suelo bajo tus pies?$B$BAlgo se aproxima desde la colmena. Únete a los Brutos, $n. ¡Cuento contigo!' WHERE `ID`=11275;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실리시드 따위는 오그리마의 자랑스러운 아들딸들의 상대가 될 수 없다. 곧 우리 발 밑에는 벌레들의 다리와 날개만이 어지럽게 널려 있을 것이다, $n.', `MaleText_loc4`='异种虫类根本不是奥格瑞玛的勇士们的对手。很快，它们支离破碎的躯壳和翅膀就会洒满我们脚下的土地，$n。', `MaleText_loc5`='異種不是奧格瑪子民的對手。很快他們就會全部成為我們腳下破碎的肢體了，$n。', `MaleText_loc7`='Los silítidos no son rivales para los hijos e hijas de Orgrimmar. Pronto, lo único que quedará de ellos serán sus patas y alas aplastadas bajo nuestros pies, $n.' WHERE `ID`=11276;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꿈의 폭군 에라니쿠스가 아제로스에 들어섰습니다!', `MaleText_loc4`='梦境之暴君伊兰尼库斯已经进入了我们的世界。', `MaleText_loc5`='夢境暴君，伊蘭尼庫斯，已經進入了我們的世界。', `MaleText_loc7`='Eranikus, Tirano del Sueño, ha entrado en nuestro mundo.', `FemaleText_loc1`='꿈의 폭군 에라니쿠스가 아제로스에 들어섰습니다!', `FemaleText_loc4`='梦境之暴君伊兰尼库斯已经进入了我们的世界。', `FemaleText_loc5`='夢境暴君，伊蘭尼庫斯，已經進入了我們的世界。', `FemaleText_loc7`='Eranikus, Tirano del Sueño, ha entrado en nuestro mundo.' WHERE `ID`=11277;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋습니다, $n. 악몽의 물건을 사용해서 에라니쿠스를 소환하겠습니다.', `FemaleText_loc4`='很好，$n。我将使用这个被梦魇笼罩的东西召唤伊兰尼库斯。', `FemaleText_loc5`='很好，$n。我會利用夢魘物體召喚出伊蘭尼庫斯。', `FemaleText_loc7`='Muy bien, $n. Utilizaré el objeto de la Pesadilla para invocar a Eranikus.' WHERE `ID`=11278;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저를 따라오십시오.', `FemaleText_loc4`='跟着我。', `FemaleText_loc5`='跟我來。', `FemaleText_loc7`='¡Seguidme!' WHERE `ID`=11279;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='의지를 굳건히 하십시오! 이 강력한 고대의 존재를 소환하면 참혹한 일이 일어날 것입니다.', `FemaleText_loc4`='坚强一点！召唤这样强大的家伙是很少取得成功的。', `FemaleText_loc5`='堅定你們的決心!召喚這樣威力強大的物體通常是不會有好下場的。', `FemaleText_loc7`='¡Armaos de valor! Invocar a un ser tan poderoso pocas veces sale bien.' WHERE `ID`=11280;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='피하십시오! 에라니쿠스가 왔습니다! 몸을 숨기십시오!', `FemaleText_loc4`='伊兰尼库斯来了！快躲起来！躲起来！', `FemaleText_loc5`='伊蘭尼庫斯在這裡!快找掩護!安全的地方!', `FemaleText_loc7`='¡Eranikus está aquí! ¡Buscad refugio! ¡Y que sea seguro!' WHERE `ID`=11281;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 수집한 조각을 통해 악몽이 시작되는 곳을 찾을 것이다, $n. 그곳에서 꿈속의 갈라진 틈을 통해 에라니쿠스를 끌어낼 생각이다. 우리가 이 세계로 불러내려는 것은 바로 악몽의 화신이니 마음을 굳게 먹어라.', `MaleText_loc4`='我们会根据你收集的碎片找出梦魇的源头，$n。那样我们就能打开一条裂缝，把伊兰尼库斯从翡翠梦境中拉出来。要坚强，$C。我们将要邀请梦魇的化身进入我们的世界。', `MaleText_loc5`='我們會透過你收集的碎片找到夢魘的起源地，$n。我們會在那裡將伊蘭尼庫斯從夢境的裂隙中召喚出來。堅定你的決心，$c。我們在邀請夢魘的化身進入我們的世界。', `MaleText_loc7`='Localizaremos el origen de la Pesadilla a partir de los fragmentos que has recogido, $n. Desde allí, sacaremos a Eranikus a través de una fisura del Sueño. Ármate de valor, $c. Estamos invitando a la personificación de la Pesadilla a venir a nuestro mundo.' WHERE `ID`=11282;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밤의 안식처로 가자꾸나! 영웅이여, 너의 친구들과 함께 따라오너라.', `MaleText_loc4`='向永夜港前进！不要掉以轻心，勇士。', `MaleText_loc5`='為了永夜港!讓你的軍隊保持戒備，勇士。', `MaleText_loc7`='¡A Amparo de la Noche! Ten cerca a tu ejército, $gcampeón:campeona;.' WHERE `ID`=11283;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신호를 보내면 에라니쿠스를 소환하도록 하겠다.', `MaleText_loc4`='一旦我念动咒语，就可以召唤出伊兰尼库斯。', `MaleText_loc5`='待我收到命令就會召喚伊蘭尼庫斯。', `MaleText_loc7`='Invocaré a Eranikus cuando tenga la oportunidad.' WHERE `ID`=11284;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비됐습니다, 레물로스.', `MaleText_loc4`='我准备好了，雷姆洛斯。', `MaleText_loc5`='我準備好了，雷姆洛斯。', `MaleText_loc7`='Estoy listo, Remulos.', `FemaleText_loc1`='준비됐어요, 레물로스.', `FemaleText_loc4`='我准备好了，雷姆洛斯。', `FemaleText_loc5`='我準備好了，雷姆洛斯。', `FemaleText_loc7`='Estoy lista, Remulos.' WHERE `ID`=11285;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적이 눈앞에 있다. 준비해라!', `MaleText_loc4`='敌人过来了，准备作战！', `MaleText_loc5`='敵人就要逼近了，準備作戰!', `MaleText_loc7`='¡Tenemos encima al enemigo! ¡Preparaos!' WHERE `ID`=11286;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='메로크! 샤이! 내 옆으로 와!', `MaleText_loc4`='梅洛克！沙艾！到我这儿来！', `MaleText_loc5`='梅洛克!沙艾!到我這邊!', `MaleText_loc7`='¡Merok! ¡Shai! ¡Conmigo!' WHERE `ID`=11287;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드 만세!', `MaleText_loc4`='为了部落而战！', `MaleText_loc5`='為了部落!', `MaleText_loc7`='¡Por la Horda!' WHERE `ID`=11288;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 쓰러진 이들의 고통을 흡수합니다.', `MaleText_loc4`='%s品尝着亡者的痛苦。', `MaleText_loc5`='%s沉醉於死難者所受的痛苦。', `MaleText_loc7`='%s se empapa del sufrimiento de los caídos.' WHERE `ID`=11289;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엘룬아라 호수 위로 틈이 열릴 것이다. 준비하라, $n. 에라니쿠스가 우리 세계로 들어오면 혼돈과 싸움이 끊이지 않을 것이니라.', `MaleText_loc4`='月神湖上空将出现一道裂缝。做好准备吧，$n。伊兰尼库斯的入侵会给整个世界带来混乱和战争。', `MaleText_loc5`='裂隙會打開，就在月神湖上方。準備好，$n。伊蘭尼庫斯進入我們的世界會帶來混亂和衝突。', `MaleText_loc7`='Abriremos la grieta allí, por encima del Lago Elun''ara. Prepárate, $n. La llegada de Eranikus a nuestro mundo traerá consigo caos y destrucción.' WHERE `ID`=11290;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그는 말퓨리온 님의 현신을 파괴하고자 수단과 방법을 가리지 않을 것이다. 그것만은 결단코 막아야 한다... 우린 티란데 님께서 도착할 때까지 그 괴물을 붙잡고 시간을 끌어야 한다.', `MaleText_loc4`='他会不择手段地摧毁玛法里奥的肉身。我们绝不能让此事发生……我们必须在泰兰德到达之前控制住那头野兽。', `MaleText_loc5`='他會不顧一切的阻止瑪法里恩的肉體化身。那絕對不能發生...我們一定要控制住那隻野獸直到泰蘭妲到來。', `MaleText_loc7`='No se detendrá ante nada e intentará destruir la manifestación física de Malfurion. Eso no debe ocurrir... Debemos mantener ocupada a la bestia hasta que llegue Tyrande.' WHERE `ID`=11291;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밤의 안식처를 수호하라, 영웅이여...', `MaleText_loc4`='保卫永夜港，英雄……', `MaleText_loc5`='保護永夜港，英雄...', `MaleText_loc7`='Defiende Amparo de la Noche, valiente...' WHERE `ID`=11292;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 악마! 세나리우스의 힘을 보여 주마!', `MaleText_loc4`='你这恶魔！尝尝塞纳留斯的力量吧！', `MaleText_loc5`='惡魔!面對塞納留斯的力量吧!', `MaleText_loc7`='¡Demonio! ¡Afronta el poder de Cenarius!' WHERE `ID`=11293;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='레물로스... 넌 네 애비가 아니다, 벌레 같은 놈. 날 자극한다면 이 발톱으로 단숨에 숨통을 끊어 놓아주마. 샨도 스톰레이지를 넘겨라. 그러면 네 부하들과 함께 구차한 목숨을 연명할 수 있을 것이다.', `MaleText_loc4`='小子，你当然没法跟你的父亲相比。要是我高兴的话，我会一爪要了你的命。让怒风来挑战我，你就趁早躲到一边去吧。', `MaleText_loc5`='你不是你的父親，小蟲。如果是我的話，我會一巴掌就把你捏碎。把怒風尊師帶來找我，而你可悲的小命就能和你的人民一起被赦免。', `MaleText_loc7`='No te pareces en nada a tu padre, insecto. Si quisiera, te aplastaría con un solo movimiento de garras. Tráeme a Shan''do Tempestira y te perdonaré a ti y a tu gente.' WHERE `ID`=11294;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뛰어야 벼룩인 게 누구더냐? 물론 너는 우리가 말퓨리온 님에 이어 너까지 소환할 거라고는 생각도 못했겠지? 자, 구원받을 시간이다, 에라니쿠스. 너의 광기와 타락을 정화하도록 하마.', `MaleText_loc4`='你算错了一招，野兽。你不曾料到我们会在玛法里奥的身边召唤你吧？伊兰尼库斯，你的救赎就要来临了。你将得到净化——堕落之源将被清除。', `MaleText_loc5`='誰是可預料的那一個，野獸?你真的沒想過我們會將你召喚至瑪法里恩上方?你的救贖來臨了，伊蘭尼庫斯。你的瘋狂 - 墮落都會被淨化。', `MaleText_loc7`='¿Quién es el previsible ahora, bestia? Seguro que no pensabas que te invocaríamos bajo el control de Malfurion. Se acerca tu redención, Eranikus. Quedarás libre de tu locura y de la corrupción.' WHERE `ID`=11295;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 사악한 웃음을 터뜨립니다.', `MaleText_loc4`='%s露出阴险的笑容。', `MaleText_loc5`='%s的臉上浮現出一個邪惡的笑容。', `MaleText_loc7`='%s suelta una carcajada siniestra.' WHERE `ID`=11296;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 구원하겠다고? 애송이들이 배짱 하나는 두둑하구나. 구원이란 나의 신께서만 베푸실 수 있는 은혜인 것을!', `MaleText_loc4`='救赎？大胆！只有我的神能救赎我。', `MaleText_loc5`='我的救贖?你真大膽，小傢伙。我的救贖會隨著吾神的意志而來。', `MaleText_loc7`='¿Mi redención? Eres muy $gosado:osada;, $gpequeñajo:pequeñaja;. Mi redención llegará cuando mi dios así lo desee.' WHERE `ID`=11297;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 격분하여 포효합니다.', `MaleText_loc4`='%s疯狂地咆哮起来。', `MaleText_loc5`='%s狂怒地大吼。', `MaleText_loc7`='%s ruge con furia.' WHERE `ID`=11298;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악몽의 종들아, 일어서라! 일어서서 너희의 광기로 이 세계를 파괴해라! 살아 있는 모든 생명을 없애라...', `MaleText_loc4`='出来吧，梦魇的仆从们！摧毁这世界！不留活口……', `MaleText_loc5`='起來吧，夢魘的奴僕們!起來摧毀這個世界!不要放過任何一個人...', `MaleText_loc7`='¡Erguíos, sirvientes de la Pesadilla! ¡Erguíos y destruid este mundo!' WHERE `ID`=11299;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서둘러라, $n! 몸을 숨길 만한 곳을 찾아야 한다!', `MaleText_loc4`='快，$n！我们必须尽快找地方躲起来！', `MaleText_loc5`='快，$n!我們一定要找到保護的掩蔽處!', `MaleText_loc7`='¡Date prisa, $n! ¡Debemos ponernos a cubierto!' WHERE `ID`=11300;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부디 우리 백성들을 지켜다오.', `MaleText_loc4`='勇士，请保护我们的人民吧！', `MaleText_loc5`='拜託你，勇士，保護我們的人民。', `MaleText_loc7`='Por favor, valiente, protege a nuestra gente.' WHERE `ID`=11301;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 힘을 모아 이 악마들과 싸울 것이다! 밤의 안식처 수호병 역시 우리와 함께할 것이니라. 명령만 내리면 그들은 죽을 때까지 싸울 것이다. 이제 서둘러 이 악마들을 악몽으로 되돌려 보내야 한다. 모두 해치워라!', `MaleText_loc4`='我们将一同对抗这些恶魔！永夜港的卫兵也加入了我们的队伍，他们将誓死抗敌。现在我们必须将这些疯狂的家伙赶回梦魇。消灭他们！', `MaleText_loc5`='我們會挑戰這些惡魔，一起!永夜港的防衛者也在我們防守之中。如果有需要他們會奮戰至死。快，我們現在務必要將這些脫離常軌的東西趕回夢魘。把他們全都消滅!', `MaleText_loc7`='¡Combatiremos a estos demonios juntos! Los defensores de Amparo de la Noche también están de nuestra parte. Ellos lucharían hasta la muerte si fuera necesario. ¡Rápido! Debemos enviar a estas aberraciones de vuelta a la Pesadilla. ¡Destruidlos a todos!' WHERE `ID`=11302;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곧 끝날 것이오, 에라니쿠스. 몸조심하시오, 고대의 존재여.', `MaleText_loc4`='没问题，伊兰尼库斯。你要保重。', `MaleText_loc5`='會成功的，伊蘭尼庫斯。等著吧，長者。', `MaleText_loc7`='Todo irá bien, Eranikus. No te preocupes, anciano.' WHERE `ID`=11303;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너의 구세주는 어디 있지? 내 공격을 얼마나 버틸 수 있을까?', `MaleText_loc4`='你们的救世主在哪儿？面对我的攻击，你还能支撑多久？', `MaleText_loc5`='你的救星在哪?你還能抵擋我的攻擊多久?', `MaleText_loc7`='¿Dónde está su salvador? ¿Cuánto tiempo podrán resistir mis ataques?' WHERE `ID`=11304;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 부하들을 해치웠다는 건가? 그럼 어디 날 상대해 봐라, 필멸의 존재여!', `MaleText_loc4`='打败了我的手下？来跟我打打看吧，凡人！', `MaleText_loc5`='擊敗我的奴僕們?那就來挑戰我吧，人類!', `MaleText_loc7`='¿Derrotasteis a mis esbirros? ¡Pues ahora enfrentaos a mí, mortales!' WHERE `ID`=11305;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='레물로스, 이들이 내 앞에서 얼마나 쉽게 목숨을 잃어 가는지 똑똑히 지켜봐라. 아직 기회는 있다, 레물로스. 그 드루이드 녀석만 내게 넘기면, 이 모든 고통이 끝날 것이며 너는 이 학살을 막는 영웅이 될 것이다...', `MaleText_loc4`='雷姆洛斯，我不费吹灰之力就能了结他们。住手吧，愚蠢的家伙。把这个德鲁伊交给我来对付，我会很快结束战斗的……', `MaleText_loc5`='雷姆洛斯，看看他們有多容易就被我給擊敗了?你可以阻止這一切的，笨蛋。把德魯伊交給我就能結束這一切...', `MaleText_loc7`='Remulos, ¿ves cómo caen ante mí? ¡No puedes hacer nada, idiota! Entrégame al druida y todo habrá acabado...' WHERE `ID`=11306;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드 $C $n|1이;가; 이 대족장의 영원한 신뢰를 얻었다는 사실을 널리 알리도록 하라. 나무구렁 요새와 훌륭한 외교 관계를 수립했고 호드를 대신해 영웅적인 위업을 베풀었노라. 그리고 자신에게 주어진 임무보다 훨씬 뛰어난 일을 해냈다. 호드의 진정한 영웅 $n|1을;를; 위해 만세 삼창을 외쳐라!', `MaleText_loc4`='这个好消息要让大家都知道，$n，部落的$C，在酋长面前获得了无上的荣耀，他在整个部落也将得到永远的尊崇。$G他:她;在与木喉要塞的外交事务方面做出了卓越的贡献，$G他:她;出色地履行了自己的使命。让我们为$n欢呼三声吧——部落的英雄！', `MaleText_loc5`='讓大家都知道$n - 部落$C─贏得了大酋長永恆的尊敬。$G他:她; 和木喉要塞有著深厚的外交關係並且代表我們對他們做出英勇的表現。$G他:她;做的已經超出了職責所在。為$n歡呼三次 - 部落真正的英雄!', `MaleText_loc7`='Todo indica que $n, $c de la Horda, se ha ganado el eterno respeto del Jefe de Guerra. $GÉl:Ella; se ha unido al Bastión Fauces de Madera con gran diplomacia y ha llevado a cabo valientes acciones para ellos en nuestro nombre. $GÉl:Ella; ha cumplido con creces con la llamada del deber. Tres hurras por $n, ¡$gun verdadero héroe:una verdadera heroína; de la Horda!' WHERE `ID`=11307;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스 $C $n|1이;가; 아이언포지와 얼라이언스의 영원한 신뢰를 얻었다는 사실을 널리 알리도록 하라. 나무구렁 요새와 훌륭한 외교 관계를 수립했고 얼라이언스를 대신해 영웅적인 위업을 베풀었노라. 그리고 자신에게 주어진 임무보다 훨씬 뛰어난 일을 해냈다. 모두 얼라이언스의 진정한 영웅 $n|1을;를; 위해 만세 삼창을 외쳐라!', `MaleText_loc4`='这个好消息要让大家都知道，$n，联盟的$C，在铁炉堡获得了无上的荣耀，他在整个联盟也将得到永远的尊崇。$G他:她;在与木喉要塞的外交事务方面做出了卓越的贡献，$G他:她;出色地履行了自己的使命。让我们为$n欢呼三声吧——联盟的英雄！', `MaleText_loc5`='讓大家都知道$n - 聯盟$C─贏得了聯盟和國王永恆的尊敬。$G他:她;和木喉要塞有著深厚的外交關係並且代表我們對他們做出英勇的表現。他們做的已經超出了職責所在。為$n歡呼三次 - 聯盟真正的英雄!', `MaleText_loc7`='Todo indica que $n, $c de la Alianza, se ha ganado el eterno respeto de Forjaz y de la Alianza. $GÉl: Ella; se ha unido al Bastión Fauces de Madera con gran diplomacia y ha llevado a cabo valientes acciones para ellos en nuestro nombre. $GÉl: Ella; ha cumplido con creces con la llamada del deber. Tres hurras por $n, ¡$gun verdadero héroe:una verdadera heroína; de la Alianza!' WHERE `ID`=11308;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='엘룬이시여, 저의 기도를 들어주소서. 저희에게 평화를 내려 주소서! 죽어 간 동료를 굽어살피소서...', `FemaleText_loc4`='艾露恩，请聆听我的祷告。让我们获得心灵的平静吧！注视着我们倒下的躯体吧……', `FemaleText_loc5`='伊露恩，聆聽我的祈禱。給我們寧靜!守護我們的先人...', `FemaleText_loc7`='Elune, escucha mis plegarias. ¡Concédenos sosiego! Vela por nuestros caídos...' WHERE `ID`=11309;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='용서를 구하십시오, 에라니쿠스여. 모든 죄가 사해질 것입니다...', `FemaleText_loc4`='伊兰尼库斯，寻求赦免吧。一切都会得到宽恕的……', `FemaleText_loc5`='尋求赦免，伊蘭尼庫斯。一切都會被原諒的...', `FemaleText_loc7`='Busca absolución, Eranikus. Todo será perdonado...' WHERE `ID`=11310;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='에라니쿠스여, 그대는 용서 받을 것입니다. 엘룬께서는 언제나 그대를 사랑하실겁니다. 그대를 지배하고 있는 속박에서 벗어나십시오!', `FemaleText_loc4`='伊兰尼库斯，你的罪行会被赦免的。艾露恩永远爱着你。挣脱禁锢着你的束缚吧！', `FemaleText_loc5`='你會被寬恕的，伊蘭尼庫斯。伊露恩會永遠愛你。掙脫控制你的束縛吧!', `FemaleText_loc7`='Serás perdonado, Eranikus. Elune siempre te amará. ¡Rompe las cadenas que te dominan!' WHERE `ID`=11311;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아... 제 힘으론 고대 신들의 속박이 꿈쩍도 하지 않습니다. 그가 그들의 음흉한 생각에 의해 잠식 당하고 있습니다... 더는... 더 이상은... 버틸 수가 없습니다... 엘룬이시여, 저를 도와주소서...', `FemaleText_loc4`='上古之神的束缚没有丝毫减弱的迹象。他完全被他们黑暗的思想所控制……我……我不能……不能引导……帮帮我，艾露恩……', `FemaleText_loc5`='上古諸神的控制仍然不受影響。他被他們黑暗的思想消耗...我...我不能...不能再引導更久了...伊露恩幫助我...', `FemaleText_loc7`='No puedo anular la influencia de los dioses antiguos. Está poseído por sus oscuros pensamientos... Yo... no puedo... no puedo continuar mucho más... Elune, ayúdame...' WHERE `ID`=11312;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꿈의 폭군 에라니쿠스가 완전히 엘룬의 빛을 감싸 안았습니다. 달숲에 평온이 찾아온 것입니다.', `MaleText_loc4`='梦境之暴君伊兰尼库斯被月神之光吞噬了。月光林地恢复了往日的宁静。', `MaleText_loc5`='夢境暴君，伊蘭尼庫斯，已經完全被伊露恩之光消耗了。月光林地一片寧靜。', `MaleText_loc7`='Eranikus, Tirano del Sueño, está completamente dominado por la Luz de Elune. La tranquilidad se ha establecido en Claro de la Luna.', `FemaleText_loc1`='꿈의 폭군 에라니쿠스가 완전히 엘룬의 빛을 감싸 안았습니다. 달숲에 평온이 찾아온 것입니다.', `FemaleText_loc4`='梦境之暴君伊兰尼库斯被月神之光吞噬了。月光林地恢复了往日的宁静。', `FemaleText_loc5`='夢境暴君，伊蘭尼庫斯，已經完全被伊露恩之光消耗了。月光林地一片寧靜。', `FemaleText_loc7`='Eranikus, Tirano del Sueño, está completamente dominado por la Luz de Elune. La tranquilidad se ha establecido en Claro de la Luna.' WHERE `ID`=11313;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타오르고 있다! 고통... 불타는 고통이...', `MaleText_loc4`='燃烧起来了！疼痛……灼热……', `MaleText_loc5`='它燒起來了!痛苦...燃燒著...', `MaleText_loc7`='¡QUEMA! EL DOLOR... ME ABRASA...' WHERE `ID`=11314;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜? 왜 내게 이런 일이 일어나는 것인가... 어디에 있었는가, 티란데? 내가 여신님의 은총을 잃어갈 때 그대는 어디에 있었는가?', `MaleText_loc4`='为什么？为什么……会发生这种事？泰兰德，你在哪儿？当我在月神面前倒下时，你在哪儿？', `MaleText_loc5`='為什麼?為什麼這樣的事會發生在...我身上?泰蘭妲你在哪?當我敗給伊露恩的恩典時你在哪?', `MaleText_loc7`='¿POR QUÉ? ¿Por qué me ha pasado esto... a mí? ¿Dónde estabas Tyrande? ¿Dónde estabas cuando perdí la gracia de Elune?' WHERE `ID`=11315;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='느낄 수 있다... 느껴져... 다시 나를 쓰다듬으시는 엘룬 님의 손길이 느껴지는구나... 엘룬께서 내게 미소를 지으시는구나... 그래... 나는...', `MaleText_loc4`='我……我感到……我再次感受到月神的触摸……她在对我微笑……是的……我……', `MaleText_loc5`='我...我感到...我再次感到伊露恩撫摸我的生命...她對我微笑...是的...我...', `MaleText_loc7`='Yo... siento... siento la influencia de Elune sobre mí una vez más... Ella me sonríe... Sí... Yo...' WHERE `ID`=11316;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='부상자들의 상처를 돌봐 주세요, 자매들이여!', `FemaleText_loc4`='姐妹们，照顾那些受伤的士兵！', `FemaleText_loc5`='姐妹們，照顧患者的傷口!', `FemaleText_loc7`='¡Ocupaos de los daños afligidos a los heridos, hermanas!' WHERE `ID`=11317;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실리시드에게 들키지 않고 이렇게 가까이 접근하려면 약간의 훈련이 필요하오. 그대에게 그럴만한 배짱이 있다면 굳이 훈련을 요구하지는 않겠소이다.', `MaleText_loc4`='如此近距离地接近异种虫类而不被察觉需要相当的技巧。如果可能的话，我不建议你做这样的尝试。', `MaleText_loc5`='要靠異種這麼近又要不被發現需要一點練習。如果你能避免我建議你就不嘗試。', `MaleText_loc7`='Requiere cierta práctica estar tan cerca de los silítidos y pasar inadvertido. No recomiendo hacerlo si se puede evitar.' WHERE `ID`=11318;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 한쪽 무릎을 꿇습니다.', `FemaleText_loc4`='%s跪倒在地。', `FemaleText_loc5`='%s單膝跪下。', `FemaleText_loc7`='%s hinca una rodilla.' WHERE `ID`=11319;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='엘룬께 찬양을... 에라니쿠스가 구원 받았도다.', `FemaleText_loc4`='赞美艾露恩……伊兰尼库斯被拯救了。', `FemaleText_loc5`='讚揚伊露恩...伊蘭尼庫斯被救贖了。', `FemaleText_loc7`='Alabada sea Elune... Eranikus ha sido redimido.' WHERE `ID`=11320;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오해하지 마십시오. 저도 실리시드가 우글거리는 터널에 온종일 갇혀 있고 싶지는 않지만, 여기 숨어서 이 벌레들의 움직임을 감시하는 것이 우리의 승리에 도움이 된다면 며칠이 걸리든 그렇게 할 겁니다.', `MaleText_loc4`='别误解我的意思，我可不想没日没夜地跟异种虫类呆在一起，但是如果隐藏在此地监视这些生物的动静对我们有帮助的话，我会一直呆下去的。', `MaleText_loc5`='別誤會我的意思，雖然我不願天天在充滿異種的隧道裡，但是如果躲在這裡觀察他們的活動能幫助我們贏得勝利，那麼我願意，多久都沒關係。', `MaleText_loc7`='No lo tomes a mal, prefiero no estar día tras día en un túnel lleno de silítidos, pero si el estar aquí escondidos observando los movimientos de estas criaturas nos va a ayudar a ganar la guerra, entonces estaré todo el tiempo que sea necesario.' WHERE `ID`=11321;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조만간 우리는 실리시드라는 끔찍한 존재를 아제로스에서 몰아낼 것입니다. 놈들에게 잠재되어 있는 파괴력은 그대가 직접 본 것보다 훨씬 더 엄청나답니다, $n. 더 강력하고 사악한 힘이 놈들을 조종하고 있는 것입니다.', `MaleText_loc4`='很快我们就能让那些可憎的异种虫类从艾泽拉斯世界消失了。它们可能造成的破坏比你先前所见的要恐怖得多，$n。他们背后是更可怕、更黑暗的力量。', `MaleText_loc5`='我們很快就能擺脫艾澤拉斯上可恨的異種了。他們潛在的毀滅性比你所親眼見過的任何東西還要強大，$n。更強大、更黑暗的力量就藏在他們的活動背後。', `MaleText_loc7`='Pronto libraremos a Azeroth de la abominable presencia de los silítidos. Su potencia destructiva es mucho mayor de lo que pensaste en un primer momento, $n. Poderes mayores y más oscuros se esconden tras sus prácticas.' WHERE `ID`=11322;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 오랫동안 나는 자신을 잃어버린 채 살았다... 악몽의 타락이 나를 지배해 왔지... 그리고 지금, 그대... 그대들이... 나를 구했다. 악몽의 손아귀에서 나를 해방시켰구나.', `MaleText_loc4`='我已经迷失很久了……梦魇令我完全堕落……现在……你们……你们拯救了我。是你们将我从梦魇的魔爪下解放出来。', `MaleText_loc5`='有一陣子，我迷失了...腐蝕夢魘侵蝕著我...而現在，你...你們所有人...你們救了我。讓我脫離了它的控制。', `MaleText_loc7`='Durante mucho tiempo estuve perdido... La corrupción de la Pesadilla me había consumido... Y ahora, ustedes... todos ustedes... me han salvado. Me liberaron de sus garras.' WHERE `ID`=11323;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='허나... 말퓨리온, 세나리우스, 이세라... 그들은 아직도 다툼을 계속하고 있다. 그들에겐 내가 필요하니 난 다시 꿈으로 돌아가야 한다.', `MaleText_loc4`='但是……玛法里奥、塞纳留斯、伊瑟拉……他们还在坚持。他们需要我。我必须马上返回翡翠梦境。', `MaleText_loc5`='但是...瑪法里恩、塞納留斯、伊瑟拉...他們仍在奮戰。他們需要我。我必須立刻回到翡翠夢境。', `MaleText_loc7`='Pero... Malfurion, Cenarius, Ysera... continúan luchando. Me necesitan y por eso he de volver al Sueño de inmediato.' WHERE `ID`=11324;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보고서를 받으려고 왔습니다.', `MaleText_loc4`='我是来拿你的报告的。', `MaleText_loc5`='我是來拿你的報告的。', `MaleText_loc7`='Estoy aquí para recoger tu informe.', `FemaleText_loc1`='보고서를 받으려고 왔어요.', `FemaleText_loc4`='我是来拿你的报告的。', `FemaleText_loc5`='我是來拿你的報告的。', `FemaleText_loc7`='Estoy aquí para recoger tu informe.' WHERE `ID`=11325;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='티란데여, 나는 그대의 기도를 받을 가치가 없는 자라오. 그대는 진실로 빛의 천사로군. 부디 내가 지하굴로 돌아가서 꿈속으로 되돌아갈 수 있도록 도와주시오. 나 또한 말퓨리온처럼 날 기다리고 있는 사랑하는 이가 있소... 그녀에게 돌아가야 하오... 그녀를 지키러...', `MaleText_loc4`='我的女王，我不值得你亲自祈祷。你是光明的天使，希望的化身。请让我返回那个古老的洞穴，这样或许我就可以回到翡翠梦境。跟玛法里奥一样，我也有心爱的她……她在等着我……我必须回到她身边……保护她……', `MaleText_loc5`='我的女士，我不值得妳的祈禱。真的，妳是聖光的天使。拜託妳，幫助我回到山崗的小窩，讓我可以回到夢境。我，就像瑪法里恩，還有摯愛在等著我...我一定要回到她身邊...保護她...', `MaleText_loc7`='Mi señora, no merezco tu plegaria. En verdad, tú eres un ángel de luz. Por favor, ayúdame a volver al túmulo para que pueda regresar al Sueño. Yo, al igual que Malfurion, también tengo una amada que aguarda por mí... Tengo que volver a su lado... para protegerla...' WHERE `ID`=11326;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 영웅들이여... 내게 그대들이 찾고 있는 것이 있다. 다시 한번 아제로스에서 악마가 사라지는 모습을 볼 수 있기를... 레물로스, 우리의 용사에게 녹색용군단의 파편을 건네 주도록 하라.', `MaleText_loc4`='英雄……我有你要找的东西。愿它能再次为净化邪恶的力量而效劳。雷姆洛斯，请确保我们的勇士得到绿龙军团保管的碎片。', `MaleText_loc5`='英雄們...我有著你們尋求的東西。讓它再一次見證惡魔毀滅。雷姆洛斯，見證我們的勇士收到綠龍的裂片。', `MaleText_loc7`='Y valientes... Yo tengo lo que buscáis. Que el mal se desvanezca una vez más. Remulos, ocúpate de que nuestro valiente reciba el fragmento del Vuelo Verde.' WHERE `ID`=11327;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 고개를 끄덕입니다.', `FemaleText_loc4`='%s点了点头。', `FemaleText_loc5`='%s點點頭。', `FemaleText_loc7`='%s asiente.' WHERE `ID`=11328;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 밤의 안식처를 떠날 것이다, 영웅이여. 날 찾으려거든 숲으로 오너라.', `MaleText_loc4`='英雄，让我们离开永夜港吧。来小树林找我。', `MaleText_loc5`='讓我們離開永夜港，英雄。到樹林裡找我。', `MaleText_loc7`='Déjanos partir de Amparo de la Noche, valiente. Búscame en la arboleda.' WHERE `ID`=11329;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흐르는 모래의 홀이 다시 한 번 완성되었구나, $n.$B$B홀을 사용할 자는 바로 그대임이 틀림없다. 다음 세대에 그대의 백성을 이끌 자 역시 그대임이 틀림없도다.$B$B스카라베 징을 울려 안퀴라즈 관문을 다시 한 번 열 준비가 되거든 내게 알리거라. 흐르는 모래의 홀을 건네 주겠노라.', `MaleText_loc4`='流沙节杖终于得以复原，$n。$B$B只有你能使用这把节杖，只有你能带领你的同胞走向新的纪元。$B$B当你准备好敲响甲虫之台的铜锣，再次打开安其拉之门时，我就会把节杖交给你的。', `MaleText_loc5`='流沙權杖再一次就完成了，$n。$B$B一定是你要使用權杖。一定是你向人民預告了下個世代。$B$B當你準備好敲響甲蟲之鑼，再一次開啟安其拉之門，我會將權杖交給你。你只要開口就行了。', `MaleText_loc7`='El cetro del Mar de Dunas está completo una vez más, $n.$B$BDebes ser tú quien use el cetro. Debes ser tú quien lo anuncie a tu pueblo en la próxima era.$B$BCuando estés preparado para hacer sonar el gong del Escarabajo y abrir de nuevo las puertas de Ahn''Qiraj, te concederé el cetro. No tienes más que preguntar.' WHERE `ID`=11330;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비 됐습니다, 아나크로노스. 제게 흐르는 모래의 홀을 주십시오.', `MaleText_loc4`='阿纳克洛斯，我已经准备好了。请将流沙节杖交给我吧。', `MaleText_loc5`='我準備好了，安納克羅斯。請將流沙權杖交給我。', `MaleText_loc7`='Estoy preparado, Anacronos. Por favor, entrégame el cetro del Mar de Dunas.', `FemaleText_loc1`='준비 됐어요, 아나크로노스. 제게 흐르는 모래의 홀을 주세요.', `FemaleText_loc4`='阿纳克洛斯，我已经准备好了。请将流沙节杖交给我吧。', `FemaleText_loc5`='我準備好了，安納克羅斯。請將流沙權杖交給我。', `FemaleText_loc7`='Estoy preparada, Anacronos. Por favor, entrégame el cetro del Mar de Dunas.' WHERE `ID`=11331;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흐르는 모래의 홀이 다시 한 번 완성되었구나, $n.$B$B홀을 사용할 자는 바로 그대임이 틀림없다. 다음 세대에 그대의 백성을 이끌 자 역시 그대임이 틀림없도다.$B$B호드와 얼라이언스의 군대가 실리더스에 도착할 때까지 기다렸다가 그들이 도착하면 스카라베 징을 울리거라. 전쟁이 눈앞으로 다가왔도다.', `MaleText_loc4`='流沙节杖终于得以复原，$n。$B$B只能你能使用这把节杖，只有你能带领你的同胞走向新的纪元。$B$B你必须等待部落和联盟的军队抵达希利苏斯，然后你就可以敲响甲虫之台的铜锣了。战争即将拉开序幕。', `MaleText_loc5`='流沙權杖再一次就完成了，$n。$B$B一定是你要使用權杖。一定是你向人民預告了下個世代。$B$B在你敲響甲蟲之台的銅鑼前，一定要等部落和聯盟的軍隊到達希利蘇斯。開戰的時刻即將來臨。', `MaleText_loc7`='El cetro del Mar de Dunas está completo una vez más, $n.$B$BDebes ser tú quien use el cetro. Debes ser tú quien lo anuncie a tu pueblo en la próxima era. $B$BDebes esperar a que los ejércitos de la Horda y de la Alianza lleguen a Silithus para hacer sonar el gong del Escarabajo. El tiempo de la guerra está próximo.' WHERE `ID`=11332;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흐르는 모래의 홀이 다시 한 번 완성되었구나, $n.$B$B저주받은 도시 안퀴라즈로 군대를 이끌고 가 그곳의 악마들에게 정의를 실현할 자는 바로 그대이니라.$B$B실리더스로 가서 계시자 조나단에게 흐르는 모래의 홀을 건네 주도록 하라.', `MaleText_loc4`='流沙节杖终于得以复原，$n。$B$B你必须带领你的军队进入被诅咒的安其拉之城，让那些异种虫类受到正义的审判。$B$B前往希利苏斯吧，将流沙节杖交给天启者乔纳森。', `MaleText_loc5`='流沙權杖再一次就完成了，$n。$B$B你一定要領導你的軍隊進入那個受詛咒的要塞城市 - 安其拉，還給居民們正義的生活。$B$B冒險到希利蘇斯並將流沙之地權杖交給『啟示者』喬納森。', `MaleText_loc7`='El cetro del Mar de Dunas está completo una vez más, $n.$B$BEres tú quien debe dirigir a tus ejércitos a la ciudad fortificada y maldita de Ahn''Qiraj e imponer justicia entre sus habitantes.$B$BAdéntrate en Silithus y entrega el cetro del Mar de Dunas a Jonathan el Apocalíptico.' WHERE `ID`=11333;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비 됐습니다!', `MaleText_loc4`='我已经准备好了！', `MaleText_loc5`='我準備好了!', `MaleText_loc7`='¡Estoy listo!', `FemaleText_loc1`='준비 됐어요!', `FemaleText_loc4`='我已经准备好了！', `FemaleText_loc5`='我準備好了!', `FemaleText_loc7`='¡Estoy lista!' WHERE `ID`=11334;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 줄은 거의 찼군...', `FemaleText_loc4`='这里几乎填满了……', `FemaleText_loc5`='這條線大部分是補給線...', `FemaleText_loc7`='Esta línea es de relleno...' WHERE `ID`=11335;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스 무공 훈장이 무엇입니까?', `MaleText_loc4`='什么是联盟荣誉徽章？', `MaleText_loc5`='什麼是聯盟榮譽徽章?', `MaleText_loc7`='¿Qué es un sello de mención de honor de la Alianza?', `FemaleText_loc1`='얼라이언스 무공 훈장이 무엇인가요?', `FemaleText_loc4`='什么是联盟荣誉徽章？', `FemaleText_loc5`='什麼是聯盟榮譽徽章?', `FemaleText_loc7`='¿Qué es un sello de mención de honor de la Alianza?' WHERE `ID`=11336;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='얼라이언스 무공 훈장은 영웅에게 수여되는 것입니다. 얼라이언스의 부름을 훌륭히 수행하고 큰 공을 세운 영웅 말이에요. 모든 주요 도시에 얼라이언스의 각 종족별로 여러 명의 인사 장교가 있어요. 당신의 평판을 높이고 싶은 인사 장교와 얘기해 보고 그들이 요구하는 개수의 훈장을 가져다주세요!$B$B그나저나 군수 물자 수급 기간 동안에는 평판 대신에 당신의 훈장을 보상으로 받게 될 것이니 야전사령관 스노우폴을 찾아가 보세요.', `FemaleText_loc4`='联盟荣誉徽章是奖励给那些富于责任感的英雄的。各大主城均设有嘉奖官，与你想要提升声望的主城中的嘉奖官交谈，按照规定的数量缴纳徽章吧！$B$B顺便说一句，在安其拉大战期间，如果你想要用徽章换取实物奖励而不是提升声望的话，可以去找大元帅斯诺·落雪。', `FemaleText_loc5`='聯盟榮譽徽章是給為聯盟上山下海的$g英雄:女豪傑;的獎勵。聯盟不同陣營的表揚官分布在各個主要城市;到你想去提高聲望的地方找那個軍官交談，並將他們要的獎章數量帶去!$B$B另外，在戰爭期間，如果你願意接受獎章的物資獎勵代替聲望，就去找戰場元帥斯諾·落雪。', `FemaleText_loc7`='Los sellos de mención de honor de la Alianza están reservados para aquellos héroes o heroínas que cumplen con creces la llamada del deber de la Alianza. Varios Oficiales de Honor de las facciones de la Alianza se encuentran en cada una de las ciudades principales. ¡Ve y habla con aquel con quien desees aumentar tu reputación y entrégale el número de sellos que te pida!$B$BPor cierto, si durante la campaña para la guerra prefieres recibir una recompensa material en lugar de reputación, busca al mariscal de campo Nevanur.' WHERE `ID`=11337;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 대업을 위해 힘을 합쳤습니다. 고대의 악마가 칼림도어의 모든 생명을 말살하고 이 세계를 타락으로 물들이려 합니다... 그는 위대한 창조주인 영원의 티탄에 의해 태어난 모든 생명에 대한 적개심을 품고 있습니다.$B$B우리는 크툰의 군대에 맞설 최초이자 최후의 방어선입니다. 우리가 봉기하여 적을 물리치지 않는다면 적은 우리를 파멸로 몰아넣을 것입니다.$B$B이번 전쟁 준비에 당신의 도움이 꼭 필요합니다!', `MaleText_loc4`='我们团结一致，为共同的目标而努力，$R。来自上古的邪灵威胁着卡利姆多，他妄图让整个世界陷入无尽的堕落……他仇视生命的缔造者——永恒的泰坦所创造的一切生物。$B$B我们是惟一能与克苏恩的大军抗衡的军队。如果我们不振作起来同仇敌忾的话，敌人一定会摧毁一切。$B$B为我们的作战物资储备尽自己的力吧！', `MaleText_loc5`='我們團結一致，$r。一個古老的惡魔威脅要毀滅卡林多上的所有生命，並以它邪惡的力量摧毀世界...它是所有仇恨事物的締造者:永恆的泰坦。$B$B我們是唯一能與克蘇恩軍隊抗衡的軍隊。如果我們不繼續向前攻打我們的敵人， 我們的敵人絕對會摧毀我們。$B$B戰備需要你!', `MaleText_loc7`='Estamos unidos en la causa, $r. Un viejo mal amenaza con aniquilar todo rastro de vida en Kalimdor y consumir el mundo en su vil depravación... Su odio por todas las cosas emana de los grandes Creadores: los titanes eternos.$B$BNosotros somos las primeras y últimas líneas de defensa contra los ejércitos de C''Thun. Si no nos erguimos y atacamos a nuestro enemigo, sin duda nos destruirá.$B$B¡La campaña para la guerra te necesita!' WHERE `ID`=11338;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스 무공 훈장은 영웅에게 수여되는 것입니다. 얼라이언스의 부름을 훌륭히 수행하고 큰 공을 세운 영웅 말입니다. 모든 주요 도시에 얼라이언스의 종족별로 여러 명의 인사 장교가 있습니다. 당신의 평판을 높이고 싶은 인사 장교와 얘기해 보고 그들이 요구하는 개수의 훈장을 가져다주십시오!$B$B그나저나 여기서 다가올 전쟁 준비를 하는 동안 평판 대신 훈장으로 보상을 받고 싶다면 야전사령관 스노우폴을 만나보세요.', `MaleText_loc4`='联盟荣誉徽章是奖励给那些富于责任感的英雄的。各大主城均设有嘉奖官，跟你想要提升声望的主城的嘉奖官交谈，按照规定的数量缴纳徽章吧！$B$B顺便说一句，在安其拉大战期间，如果你想要用徽章换取实物奖励而不是提升声望的话，可以去找大元帅斯诺·落雪。', `MaleText_loc5`='聯盟榮譽徽章是給為聯盟上山下海的$g英雄:女豪傑;的獎勵。聯盟不同陣營的表揚官分布在各個主要城市;到你想去提高聲望的地方找那個軍官交談，並將他們要的獎章數量帶去!$B$B另外，在戰爭期間，如果你願意接受獎章的物資獎勵代替聲望，就去找戰場元帥斯諾·落雪。', `MaleText_loc7`='Los sellos de mención de honor de la Alianza están reservados para aquellos héroes o heroínas que cumplen con creces la llamada del deber de la Alianza. Varios Oficiales de Honor de las facciones de la Alianza se encuentran en cada una de las ciudades principales. ¡Ve y habla con aquel con quien desees aumentar tu reputación y entrégale el número de sellos que te pida!$B$BPor cierto, si durante la campaña para la guerra prefieres recibir una recompensa material en lugar de reputación, busca al mariscal de campo Nevanur.' WHERE `ID`=11339;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드 무공 훈장이 무엇입니까?', `MaleText_loc4`='什么是部落荣誉徽章？', `MaleText_loc5`='什麼是部落榮譽徽章?', `MaleText_loc7`='¿Qué es un sello de honor de la Horda?', `FemaleText_loc1`='호드 무공 훈장이 무엇인가요?', `FemaleText_loc4`='什么是部落荣誉徽章？', `FemaleText_loc5`='什麼是部落榮譽徽章?', `FemaleText_loc7`='¿Qué es un sello de honor de la Horda?' WHERE `ID`=11340;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드 무공 훈장은 영웅에게 수여되는 것입니다. 호드의 부름을 훌륭히 수행하고 큰 공을 세운 영웅 말입니다. 모든 주요 도시에는 호드의 종족별로 여러 명의 인사 장교가 있습니다. 평판을 높이고 싶은 인사 장교와 얘기해 보고 그들이 요구하는 개수의 무공 훈장을 가져다주십시오!$B$B그나저나 여기서 다가올 전쟁 준비를 하는 동안 평판 대신 훈장으로 보상을 받고 싶다면 장군 고르척을 만나보세요.', `MaleText_loc4`='部落荣誉徽章是奖励给那些富于责任感的英雄的。各大主城均设有嘉奖官，跟你想要提升声望的主城的嘉奖官交谈，按照规定的数量缴纳徽章吧！$B$B顺便说一句，在安其拉大战期间，如果你想要用徽章换取实物奖励而不是提升声望的话，可以去找督军格尔库克。', `MaleText_loc5`='部落榮譽徽章是給為聯盟上山下海的$g英雄:女豪傑;的獎勵。部落不同陣營的表揚官分布在各個主要城市;到你想去提高聲望的地方找那個軍官交談，並將他們要的獎章數量帶去!$B$B另外，在戰爭期間，如果你願意接受獎章的物資獎勵代替聲望，就去找督軍格爾庫克。', `MaleText_loc7`='Los sellos de honor de la Horda están reservados para aquellos héroes o heroínas que cumplen con creces la llamada del deber de la Horda. Varios Oficiales de Honor de las facciones de la Horda se encuentran en cada una de las ciudades principales. ¡Ve y habla con aquel con quien desees aumentar tu reputación y entrégale el número de sellos que te pida!$B$BPor cierto, si durante la campaña para la guerra prefieres recibir una recompensa material en lugar de reputación, busca al señor de la guerra Gorchuk.' WHERE `ID`=11341;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='호드 무공 훈장은 영웅에게 수여되는 것입니다. 호드의 부름을 훌륭히 수행하고 큰 공을 세운 영웅 말입니다. 모든 주요 도시에는 호드의 종족별로 여러 명의 인사 장교가 있습니다. 평판을 높이고 싶은 인사 장교와 얘기해 보고 그들이 요구하는 개수의 무공 훈장을 가져다주십시오!$B$B그나저나 여기서 다가올 전쟁 준비를 하는 동안 평판 대신 훈장으로 보상을 받고 싶다면 장군 고르척을 만나보세요.', `FemaleText_loc4`='部落荣誉徽章是奖励给那些富于责任感的英雄的。各大主城均设有嘉奖官，与你想要提升声望的主城中的嘉奖官交谈，按照规定的数量缴纳徽章吧！$B$B顺便说一句，在安其拉大战期间，如果你想要用徽章换取实物奖励而不是提升声望的话，可以去找督军格尔库克。', `FemaleText_loc5`='部落榮譽徽章是給為聯盟上山下海的$g英雄:女豪傑;的獎勵。部落不同陣營的表揚官分布在各個主要城市;到你想去提高聲望的地方找那個軍官交談，並將他們要的獎章數量帶去!$B$B另外，在戰爭期間，如果你願意接受獎章的物資獎勵代替聲望，就去找督軍格爾庫克。', `FemaleText_loc7`='Los sellos de honor de la Horda están reservados para aquellos héroes o heroínas que cumplen con creces la llamada del deber de la Horda. Varios Oficiales de Honor de las facciones de la Horda se encuentran en cada una de las ciudades principales. ¡Ve y habla con aquel con quien desees aumentar tu reputación y entrégale el número de sellos que te pida!$B$BPor cierto, si durante la campaña para la guerra prefieres recibir una recompensa material en lugar de reputación, busca al señor de la guerra Gorchuk.' WHERE `ID`=11342;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 느려지기 시작했습니다!', `MaleText_loc4`='%s的速度慢下来了！', `MaleText_loc5`='%s開始減速!', `MaleText_loc7`='¡%s comienza a ir más despacio!' WHERE `ID`=11343;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 얼어붙고 있습니다!', `MaleText_loc4`='%s冻结了！', `MaleText_loc5`='%s凍住了!', `MaleText_loc7`='¡%s se está congelando!' WHERE `ID`=11345;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 분해되기 시작합니다!', `MaleText_loc4`='%s突然裂开了！', `MaleText_loc5`='%s開始爆裂!', `MaleText_loc7`='¡%s comienza a desmoronarse!' WHERE `ID`=11346;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 부서질 것 같습니다!', `MaleText_loc4`='%s看起来就要碎裂了！', `MaleText_loc5`='%s看來準備好毀滅了!', `MaleText_loc7`='¡%s parece a punto de hacerse añicos!' WHERE `ID`=11347;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아나크로노스, 인장 반지를 잃어버렸습니다. 새로 하나 지급해 주시겠습니까?', `MaleText_loc4`='阿纳克洛斯，我把徽记之戒给弄丢了。你能再给我一个吗？', `MaleText_loc5`='安納克羅斯，我弄丟了徽記之戒。你可以再給我一個嗎?', `MaleText_loc7`='Anacronos, he perdido el sello. ¿Podrías darme otro?', `FemaleText_loc1`='아나크로노스, 인장 반지를 잃어버렸습니다. 새로 하나 지급해 주시겠습니까?', `FemaleText_loc4`='阿纳克洛斯，我把徽记之戒给弄丢了。你能再给我一个吗？', `FemaleText_loc5`='安納克羅斯，我弄丟了徽記之戒。你可以再給我一個嗎?', `FemaleText_loc7`='Anacronos, he perdido el sello. ¿Podrías darme otro?' WHERE `ID`=11348;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 순록의 목에는 "멧젠"이라는 이름의 딱지가 굴뚝나무 목장조합 로고에 달렸습니다.$B$B멧젠이 당신을 슬프고 불쌍한 눈으로 쳐다봅니다. 이 순록은 어떤 보이지 않는 힘에 의해 움직일 수 없게 된 것 같습니다.', `MaleText_loc4`='在这头驯鹿的脖子上挂着一个小牌子，牌子上印着烟林牧场的标志和一个名字：“梅森”。$B$B梅森用悲哀而孤独的眼神看着你，它似乎被某种无形的力量困住无法动弹了。', `MaleText_loc5`='這隻麋鹿的脖子上有著一塊上面有著燻木牧場的標誌的標籤，上面寫著「梅特森」。$B$B梅特森用一種傷心、絕望的眼神看著你。看起來這頭麋鹿似乎被某種看不見的力量給限制了行動。', `MaleText_loc7`='"En el cuello de este reno se encuentra una marca con el logotipo de Pastos Bosquehumeante y un nombre: "Metzen"$B$BMetzen te mira con ojos de tristeza y desamparo. Parece como si algo, una fuerza oculta, hubiera inmovilizado al reno".' WHERE `ID`=11349;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멧젠, 넌 이제 자유야. 못된 그린치는 더는 널 괴롭히지 못해.', `MaleText_loc4`='你自由了，梅森。坏格林奇再也不能伤害你了。', `MaleText_loc5`='你自由了，梅特森。那個壞格林奇不會再傷害你了。', `MaleText_loc7`='Eres libre, Metzen. El malvado grinch ya no volverá a hacerte daño.', `FemaleText_loc1`='멧젠, 넌 이제 자유야. 못된 그린치는 더는 널 괴롭히지 못해.', `FemaleText_loc4`='你自由了，梅森。坏格林奇再也不能伤害你了。', `FemaleText_loc5`='你自由了，梅特森。那個壞格林奇不會再傷害你了。', `FemaleText_loc7`='Eres libre, Metzen. El malvado grinch ya no volverá a hacerte daño.' WHERE `ID`=11350;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멧젠의 눈이 기쁨으로 밝게 빛납니다.', `MaleText_loc4`='梅森的眼睛里亮起了喜悦的光芒。', `MaleText_loc5`='梅特森的雙眼中充滿了喜悅之情。', `MaleText_loc7`='Los ojos de Metzen se iluminan con la felicidad del reno.' WHERE `ID`=11351;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비록 자네가 우리를 구해내는 데는 성공했지만 크툰을 꺾지는 못했다. 우리 모두 힘을 모아 그 괴물을 지옥으로 다시 추방해야 한다. 어떤 대가를 치르더라도!', `MaleText_loc4`='即使你能设法不打败克苏恩而解救我们，我们也会不惜一切代价将他驱逐回地狱。不惜一切代价。', `MaleText_loc5`='即使你不知道為何沒有擊敗克蘇恩而設法解救我們，我們仍會集中所有的力量將野獸驅回牠原本的地獄－不惜任何代價。', `MaleText_loc7`='Aunque hayas conseguido liberarnos sin tener que vencer a C''Thun, nosotros aunaremos nuestras fuerzas para desterrar a la bestia al infierno del que vino, CUESTE LO QUE CUESTE.' WHERE `ID`=11352;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그대가 혈족의 영웅인가요? 크툰을 없애야 합니다! 우리가 그대를 돕겠습니다, 필멸의 존재여!', `FemaleText_loc4`='龙类指派的英雄？必须除掉克苏恩！我们可以帮助你，凡人！', `FemaleText_loc5`='一群英雄?一定要驅逐克蘇恩，我們會幫助你，人類!', `FemaleText_loc7`='¡Héroes del Linaje! ¡C''Thun debe ser desterrado! ¡Podemos ayudarte, mortal!' WHERE `ID`=11353;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 내 앞에 있는 걸 보니 기적이 벌어진 모양이군! 이곳에 감금된 천 년 동안 살아 있는 생명체가 이 방에 들어온 것은 타락한 퀴라지와 실리시드 외에는 본 적이 없다네.', `MaleText_loc4`='我真不敢相信自己的眼睛，这简直是个奇迹！一千年来，除了那些肮脏的其拉虫人和异种虫类，我都不曾见过有活人进入这些房间。', `MaleText_loc5`='我目睹站在我眼前的奇蹟!經過了一千年的囚禁，我還沒見過一件活的樣品－除了那些邪惡的其拉和異種蠍－進入密室。', `MaleText_loc7`='¡Yo soy testigo de un milagro que se aparece ante mí! En el milenio que llevo en cautividad, no he visto ni a un solo SER vivo entrar en estas cámaras, aparte claro de esos repugnantes qiraji y silítidos.' WHERE `ID`=11354;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼림도어의 전사들과 실리더스의 영웅들이여! 그대들 중 한 명이 이 세계를 침략한 사악한 적들을 물리쳤소! $n|1과;와; 동맹들이 안퀴라즈 폐허에서 놈들의 무자비한 지도자를 몰아냈소! 실리더스의 원흉인 무적의 오시리안이 마침내 죽음을 맞이했고 그의 군대는 모두 사라졌소!', `MaleText_loc4`='卡利姆多的士兵们！希利苏斯的英雄们！你们中的一位勇士给予了我们的敌人迎头痛击！$n和$G他:她;的同伴们扫清了安其拉废墟中最强大的敌人！希利苏斯的毒瘤，无疤者奥斯里安和他的军队，已经全部瓦解了！', `MaleText_loc5`='卡林多的士兵!希利蘇斯的英雄們!你們其中之一已給了我們該死的敵人致命一擊!$n及$g他的:她的;盟友已解除安其拉廢墟那殘忍首領的職務!希利蘇斯的大敵『無疤者』奧斯里安，已經被毀滅了而且他的軍隊也已被消滅了!', `MaleText_loc7`='¡Soldados de Kalimdor! ¡Héroes de Silithus! ¡Uno de ustedes ha asestado un certero golpe a nuestros archienemigos! ¡$n y sus aliados han liberado las Ruinas de Ahn''Qiraj de su despiadado líder! ¡Osirio el Sinmarcas, peste de Silithus, ha sido al fin destruido y sus ejércitos desmantelados por completo!' WHERE `ID`=11355;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='적 발견! 정신 바짝 차리고 즉시 진열을 정비하라!', `FemaleText_loc4`='小伙子们，保持警惕！敌人已经出现了！迅速列队！', `FemaleText_loc5`='看仔細，小夥子!敵人已經現身了!立刻整裝軍隊!', `FemaleText_loc7`='¡Eh, Soldados! ¡Enemigo a la vista! ¡Formen filas inmediatamente!' WHERE `ID`=11356;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음 불꽃놀이를 놓치지 마십시오! 저녁 6시부터 벌어지는 놀라운 구경거리랍니다.', `MaleText_loc4`='别忘了观看下一场焰火表演！每天下午6点开始，每小时整点都会有一次！', `MaleText_loc5`='別忘了觀看下一場煙火表演!每天下午6點開始，每小時整點都會有一次!', `MaleText_loc7`='¡No te vayas si no te quieres perder el siguiente espectáculo de fuegos artificiales! Empieza a las 6PM. ¡Son a cada hora en punto!', `FemaleText_loc1`='다음 불꽃놀이를 놓치지 마십시오! 저녁 6시부터 벌어지는 놀라운 구경거리예요.', `FemaleText_loc4`='别忘了观看下一场焰火表演！每天下午6点开始，每小时整点都会有一次！', `FemaleText_loc5`='別忘了觀看下一場煙火表演!每天下午6點開始，每小時整點都會有一次!', `FemaleText_loc7`='¡No te vayas si no te quieres perder el siguiente espectáculo de fuegos artificiales! Empieza a las 6PM. ¡Son a cada hora en punto!' WHERE `ID`=11357;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 술통 안에 무얼 넣었는지는 잘 모르겠지만 정말 꿀처럼 감미롭게 넘어갑니다!', `MaleText_loc4`='我不知道他们给那些酒桶里放了什么，但闻起来很香甜！', `MaleText_loc5`='我不知道他們給那些酒桶裏放了什麼，但聞起來很香甜!', `MaleText_loc7`='No sé que hay en estos barriles ¡pero sabe a gloria!', `FemaleText_loc1`='이 술통 안에 무얼 넣었는지는 잘 모르겠지만 정말 꿀처럼 감미롭게 넘어가요!', `FemaleText_loc4`='我不知道他们给那些酒桶里放了什么，但闻起来很香甜！', `FemaleText_loc5`='我不知道他們給那些酒桶裏放了什麼，但聞起來很香甜!', `FemaleText_loc7`='No sé que hay en estos barriles ¡pero sabe a gloria!' WHERE `ID`=11358;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불꽃놀이가 끝난 후에는 술잔이 나옵니다. 모두 들어올려 건배하며 축제의 기쁨을 함께합시다!', `MaleText_loc4`='焰火表演之后，他们会拿出高脚杯，我们就可以喝酒庆祝啦！', `MaleText_loc5`='煙火表演之後，他們會拿出高腳杯，我們就可以喝酒慶祝啦!', `MaleText_loc7`='¡Después de los fuegos artificiales sacarán las copas para que podamos brindar!', `FemaleText_loc1`='불꽃놀이가 끝난 후에는 술잔이 나오지요. 모두 들어올려 건배하며 축제의 기쁨을 함께해요!', `FemaleText_loc4`='焰火表演之后，他们会拿出高脚杯，我们就可以喝酒庆祝啦！', `FemaleText_loc5`='煙火表演之後，他們會拿出高腳杯，我們就可以喝酒慶祝啦!', `FemaleText_loc7`='¡Después de los fuegos artificiales sacarán las copas para que podamos brindar!' WHERE `ID`=11359;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='친구여, 만나서 반갑습니다!', `MaleText_loc4`='你好啊，朋友！', `MaleText_loc5`='你好啊，朋友!', `MaleText_loc7`='¡Bien $ghallado, amigo:hallada, amiga;!', `FemaleText_loc1`='친구여, 만나서 정말 반가워요!', `FemaleText_loc4`='你好啊，朋友！', `FemaleText_loc5`='你好啊，朋友!', `FemaleText_loc7`='¡Bien $ghallado, amigo:hallada, amiga;!' WHERE `ID`=11360;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오게. 나는 이곳에서 전쟁 준비를 총지휘하고 있는 야전사령관 스노우폴이라고 하네. 우리가 갈 길은 멀고도 험난하니 자네가 좀 도와줬으면 좋겠네. 궁금한 게 있다면 주저하지 말고 물어보게.', `MaleText_loc4`='你好，$C。我是大元帅斯诺·落雪。$G小伙子:姑娘;，我们面前的道路充满艰辛，如果你想要帮忙的话，请尽量帮助我们。有什么问题尽管问吧。', `MaleText_loc5`='你好，$c。我是這裡指揮作戰的戰場元帥斯諾·落雪。我們還有一段辛苦的路要走，$g小夥子:小姑娘;，所以如果你能幫忙，那是再好不過。請任意發問。', `MaleText_loc7`='Saludos, $c. Soy el mariscal de campo Nevanur, el Comandante de la campaña aquí. Nos queda un arduo camino por delante, $gmuchacho:muchacha;, así que si puede echar una mano, por favor hazlo. Y haz todas las preguntas que desees.' WHERE `ID`=11361;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 준비가 끝났네! 얼라이언스와 호드 모두 안퀴라즈 전쟁에서 필요할 걸로 생각되는 물자를 모두 모았다네. 현재 최종적으로 완성된 물자를 실리더스의 세나리온 요새로 옮기고 있는데 하루 안에 마지막 물량이 도착할 것이야. 물자 수송이 끝나면 안퀴라즈 관문을 열어야 하는데 그러려면 어떤 용감한 영웅이 흐르는 모래의 홀로 스카라베 징을 울려야 하지. 문이 열리면 전쟁이 시작되는 거라네!', `MaleText_loc4`='我们成功了，$G小伙子:姑娘;！联盟和部落已经集齐了安其拉一战所需的所有物资。现在这些物资都在运往希利苏斯塞纳里奥要塞的途中，预计将在1天内达到。然后，会有一位勇敢的英雄使用流沙节杖敲响甲虫之台的铜锣，打开安其拉之门。那时，战争也就开始了！', `MaleText_loc5`='我們完成了，$g小夥子:小姑娘;!聯盟和部落已經完成了所有安其拉之戰需要的收集工作。現在最後一批貨物正被送往希利蘇斯的塞納里奧城堡，應該一天內就會到達了。在那之後，某個勇敢的$g英雄:女豪傑;就要以流沙權杖敲響甲蟲之鑼，開啟安其拉之門。當大門打開，才是戰爭開始的時候!', `MaleText_loc7`='¡Lo hemos conseguido,$gmuchacho: muchacha;! Tanto la Alianza como la Horda hemos reunido todo el material que consideramos necesario para la guerra de Ahn''Qiraj. Toda la mercancía está de camino al Fuerte Cenarion en Silithus y el último envío llegará en menos de un día. Después, $galgún:alguna; valiente tendrá que hacer sonar el gong del Escarabajo con el cetro del Mar de Dunas para abrir las puertas de Ahn''Qiraj. ¡Cuando las puertas se abran, dará comienzo la guerra!' WHERE `ID`=11362;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 준비가 끝났네! 얼라이언스와 호드 모두 안퀴라즈 전쟁에서 필요할 걸로 생각되는 물자를 모두 모았네. 현재 최종적으로 완성된 물자를 실리더스의 세나리온 요새로 옮기고 있는데 $2113w일 내로 모든 물자가 도착할 것이야. 물자 수송이 끝나면 안퀴라즈 관문을 열어야 하는데 그러려면 어떤 용감한 영웅이 흐르는 모래의 홀로 스카라베 징을 울려야 하지. 문이 열리면 전쟁이 시작되는 거라네!', `MaleText_loc4`='我们成功了，$G小伙子:姑娘;！联盟和部落已经集齐了安其拉一战所需的所有物资。现在这些物资都在运往希利苏斯塞纳里奥要塞的途中，预计将在$2113w天内达到。然后，会有一位勇敢的英雄使用流沙节杖敲响甲虫之台的铜锣，打开安其拉之门。那时，战争也就开始了！', `MaleText_loc5`='我們完成了，$g小夥子:小姑娘;!聯盟和部落已經完成了所有安其拉之戰需要的收集工作。現在最後一批貨物正被送往希利蘇斯的塞納里奧城堡，應該$2113w天內就會到達了。在那之後，某個勇敢的$g英雄:女豪傑;就要以流沙權杖敲響甲蟲之鑼，開啟安其拉之門。當大門打開，才是戰爭開始的時候!', `MaleText_loc7`='¡Lo hemos conseguido,$gmuchacho: muchacha;! Tanto la Alianza como la Horda hemos reunido todo el material que consideramos necesario para la guerra de Ahn''Qiraj. Toda la mercancía está de camino al Fuerte Cenarion en Silithus y el último envío llegará en menos de $2113w días. Después, $galgún:alguna; valiente tendrá que hacer sonar el gong del Escarabajo con el cetro del Mar de Dunas para abrir las puertas de Ahn''Qiraj. ¡Cuando las puertas se abran, dará comienzo la guerra!' WHERE `ID`=11363;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 좋은 소식 들었나, $c 친구? 이번 전쟁에서 얼라이언스에 필요한 물자를 모두 모았다네! 지금은 호드가 물자 수집을 완료할 때까지 기다리는 중이지. 그게 끝나면 모든 전쟁 물자를 실리더스로 옮기기 시작할 것이야. 물자 수송이 완료되면 머지않아 안퀴라즈 전쟁이 시작되겠지.', `MaleText_loc4`='你听到那条好消息了吗，$C？联盟已经集齐战争物资了！现在只等部落完成他们的收集任务。那时，所有的战争物资将被运往希利苏斯，安其拉之战就也开始了。', `MaleText_loc5`='你聽到新的消息了嗎，$c?聯盟已完成所有作戰物資的工作!現在就等部落收集完畢。完成之後，我們會將全部物資運往希利蘇斯，在安其拉之戰開始前一定會到達。', `MaleText_loc7`='¿Te has enterado de la buena noticia, $c? ¡La Alianza ya ha completado su campaña de recolección de material! Ahora solo nos queda esperar a que la Horda haga lo mismo. Cuando así sea, empezaremos a enviar todos los pertrechos a Silithus y después de eso la guerra de Ahn''Qiraj no debería tardar mucho en comenzar.' WHERE `ID`=11364;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='질문 잘하셨습니다, $c. 마지막으로 보고받은 내용에 따르면 $1998w개의 구리 주괴가 필요한데 지금까지 $1997w개를 모았다고 말했습니다. 또, 철 주괴는 $2003w개 중 $2002w개, 토륨 주괴는 $2012w개 중 $2011w개를 모았다고 보고받은 상황입니다.', `MaleText_loc4`='问得好，$C。我得到的最新消息称我们已经收集到$1997w块铜锭、$2002w块铁锭和$2011w块瑟银锭了，总的需求量分别是$1998w、$2003w和$2012w。', `MaleText_loc5`='好問題，$c。上次我提過我們設法收集$1998w銅錠，但目前只有$1997w。另外，我們要收集$2003w鐵錠，但目前只有$2002w;還需要$2012w瑟銀錠，但目前只收集了$2011w。', `MaleText_loc7`='Buena pregunta, $c. Los últimos datos que tengo muestran que hemos reunido $1997w barras de cobre de las $1998w necesarias. Además, me dicen que tenemos $2002w barras de hierro de un total de $2003w y $2011w barras de torio de las $2012w solicitadas.' WHERE `ID`=11365;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='약초, 약초라. 어디 봅시다. 오, 그렇군요. 여기 있네요. 지금까지 모은 것을 보면 갈래물풀은 $2048w개 중 $2047w개, 보라 연꽃은 $2055w개 중 $2053w개, 그리고 아서스의 눈물은 $2058w개 중 $2057w개입니다.', `MaleText_loc4`='草药，草药，嗯，让我看看。啊，是的。到目前为止我们已经收集到$2047w份荆棘藻、$2053w份紫莲花和$2057w份阿尔萨斯之泪，而总的需求量分别是$2048w、$2055w和$2058w。', `MaleText_loc5`='草藥，草藥，嗯，讓我看看這邊。啊，對，沒錯。目前我們需要$2048w荊棘藻，但目前只有$2047w。我們要收集$2055w紫蓮花，但目前只有$2053w;還需要$2058w阿薩斯之淚，但目前只收集了$2057w。', `MaleText_loc7`='Plantas, plantas... a ver, déjame ver aquí. ¡Ah, sí! Aquí está. Hasta la fecha hemos reunido $2047w algas estranguladoras de $2048w, $2053w lotos cárdenas de un total de $2055w y $2057w lágrimas de Arthas de las $2058w necesarias.' WHERE `ID`=11366;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조금 전에 새로운 보고를 받았습니다. 얇은 가죽은 $2061w개가 필요한데 현재까지 모은 것은 $2060w개인 것 같더군요. 다른 가죽을 보면 일반 가죽은 $2064w개 중 $2063w개, 두꺼운 가죽은 $2071w개 중 $2069w개를 모았다고 되어 있습니다.', `MaleText_loc4`='我刚刚得到最新的消息。似乎我们已经收集到$2060w张轻皮、$2063w张中皮和$2069w张厚皮，而总的需求量分别是$2061w、$2064w和$2071w。', `MaleText_loc5`='我才剛收到最新消息。看來我們需要$2061w 張輕皮，但目前只有$2060w張。至於其他方面，報告顯示我們需要$2064w中皮，但目前只有$2063w張。還有，厚皮的配額要達到$2071w，但目前只有$2069w張。', `MaleText_loc7`='Recibí hace un momento las últimas cifras al respecto. Parece que de las $2061w pieles de cuero ligero necesarias, tenemos $2060w. En cuanto a las demás, el informe indicaba que hemos reunido $2063w pieles de cuero medio de $2064w y $2069w pieles de cuero grueso de un total de $2071w.' WHERE `ID`=11367;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='붕대 수집은 예정대로 잘 진행되고 있습니다. 리넨 붕대를 살펴보면 지금까지 $2077w개 중 $2076w개를 모았습니다. 그리고 비단 붕대는 $2083w개 중 $2082w개, 룬무늬 붕대는 $2090w개 중 $2088w개를 모았습니다.', `MaleText_loc4`='收集绷带的工作正有条不紊地按计划进行着。我们已经收集到$2076w根亚麻绷带、$2082w根丝质绷带和$2088w根符文布绷带了，总的需求量分别是$2077w、$2083w和$2090w。', `MaleText_loc5`='繃帶收集正按照計畫進行著。說到亞麻繃帶，我們需要$2077w，但目前只有$2076w。還需要$2083w絲質繃帶，但目前只有$2082w張。符文布繃帶要$2090w，目前也只收集$2088w。', `MaleText_loc7`='La recolección de vendas va según lo programado. Respecto a las vendas de lino, hemos reunido $2076w de $2077w. Por otro lado, las vendas de seda suman un total de $2082w de $2083w y tenemos $2088w vendas de paño rúnico de las $2090w necesarias.' WHERE `ID`=11368;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 앞에 있는 식량을 보면 무지개날개다랑어 구이는 $2093w개가 필요한데 $2092w개를 모아서 보관해 둔 것 같습니다. 또, 랩터 숯불구이는 $2099w개 중 $2098w개, 점박이놀래기 구이는 $2103w개 중 $2101w개를 모아서 냉장 창고에 저장해 두었습니다.', `MaleText_loc4`='我们已经收集到了$2092w条彩鳍鱼、$2098w块烤迅猛龙肉和$2101w条斑点黄尾鱼，而总的需求量是$2093w、$2099w和$2103w。', `MaleText_loc5`='關於烹煮物資方面，看來我們要收集$2093w彩鰭魚，現在儲存了$2092w。另外，需要$2099w迅猛龍肉，但目前只收集了$2098w。冷藏斑點黃尾魚要$2103w，目前也只收集$2101w。', `MaleText_loc7`='En cuanto a los productos cocinados, parece que hemos conseguido recoger y almacenar $2092w piezas de atún blanco arco iris de las $2093w solicitadas. Además, ahora mismo tenemos $2098w raptores asados de $2099w y $2101w serviolas moteadas de un total de $2103w almacenados en frío.' WHERE `ID`=11369;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='트롬카. 호드 $C|1이여;여; 자부심을 가지게나! 나는 호드의 전쟁 물자 준비를 총지휘하고 있는 장군 고르척이네. 우리는 지금 어려운 시기를 겪고 있네. 하지만 언제나 그랬듯이 잘 극복할 수 있을 것이야.$B$B궁금한 게 있으면 저들에게 가서 물어보게.', `MaleText_loc4`='你好，部落的$C。我是督军格尔库克，部落物资收集行动的指挥官。艰难的岁月就要来临，但我们还是会获胜的，胜利永远属于我们。$B$B如果你有什么问题，就去问问他们吧。', `MaleText_loc5`='(獸人語)你好，部落的$C，以你為榮!我是部落作戰指揮官，督軍格爾庫克。我們將面臨一連串艱難的考驗，我們會戰勝一切的，一如往常。$B$B如果你有問題，可以問問他們。', `MaleText_loc7`='¡Throm''ka, $c de la Horda, en pie! Soy el señor de la guerra Gorchuk, Comandante de la campaña de la Horda. Nos esperan tiempos difíciles pero debemos sobreponernos, como de costumbre.$B$BSi tenéis alguna pregunta, no dudéis en hacerla.' WHERE `ID`=11370;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전쟁이 눈앞으로 다가왔네! 호드와 얼라이언스 모두 전쟁 준비를 완료했어. 말했듯이 우리는 모든 전쟁 물자를 실리더스로 옮기고 있네. 하루 안에 마지막 물량이 도착할 걸로 예상한다네. 모든 물자가 실리더스에 도착하면 누군가가 흐르는 모래의 홀을 복원하는 어려운 임무를 완수한 후 스카라베 징을 울리고 안퀴라즈의 관문을 열 걸세. 그러면 지금까지 유례없는 대전쟁이 시작되겠지!$B$B록타르 오가르!', `MaleText_loc4`='战争犹如箭在弦上，$C！部落和联盟都做好了充分的准备。所有的战争物资都将如约运往希利苏斯。预计货物将在1天内抵达。当军队准备就绪时，那位完成修复流沙节杖的艰巨任务的英雄将敲响甲虫之台上的铜锣，打开安其拉之门。一场旷世之战也将随即拉开序幕！$B$B部落万岁！', `MaleText_loc5`='作戰時刻就要來臨了，$c!部落和聯盟都已完成了他們的準備工作。所有作戰物資都已被送往希利蘇斯。我想最後一批應該一天內就會到達。當一切就緒後，就會有人完成重組流沙權杖的艱難任務並敲響甲蟲之鑼，開啟安其拉之門。然後就會展開許久不見的大戰!$B$B為了部落!', `MaleText_loc7`='¡El momento de la guerra está cerca, $c! Tanto la Horda como la Alianza han finalizado sus preparativos. Todos nuestros pertrechos están siendo enviados a Silithus mientras hablamos. Espero que el último envío llegue en un día. Cuando todo esté listo allí, aquel que haya completado la difícil tarea de reconstruir el cetro del Mar de Dunas podrá golpearlo contra el gong del Escarabajo para abrir las puertas de Ahn''Qiraj. ¡Entonces tendrá lugar la batalla más dura vivida en siglos!$B$B¡Lok''tar Ogar!' WHERE `ID`=11371;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전쟁이 눈앞으로 다가왔네! 호드와 얼라이언스 모두 전쟁 준비를 완료했어. 말했듯이 우리는 모든 전쟁 물자를 실리더스로 옮기고 있네. $2113w일 내로 마지막 물량이 도착할 걸로 예상한다네. 모든 물자가 실리더스에 도착하면 누군가가 흐르는 모래의 홀을 복원하는 어려운 임무를 완수한 후 스카라베 징을 울리고 안퀴라즈의 관문을 열 걸세. 그러면 지금까지 유례없는 대전쟁이 시작되겠지!$B$B록타르 오가르!', `MaleText_loc4`='战争犹如箭在弦上，$C！部落和联盟都做好了充分的准备。所有的战争物资都将如约运往希利苏斯。预计货物将在$2113w天内抵达。当军队准备就绪时，那位完成修复流沙节杖的艰巨任务的英雄将敲响甲虫之台上的铜锣，打开安其拉之门。一场旷世之战也将随即拉开序幕！$B$B部落万岁！', `MaleText_loc5`='作戰的時刻就要來臨了，$c!部落和聯盟都完成了他們的準備工作。所有的物資都被送往希利蘇斯了。我想最後一批應該$2113w天內就會到達。當一切就緒後，就會有人完成重組流沙權杖的艱難任務並敲響甲蟲之鑼，開啟安其拉之門。然後就會展開許久不見的大戰!$B$B為了部落!', `MaleText_loc7`='¡El momento de la guerra está cerca, $c! Tanto la Horda como la Alianza han finalizado sus preparativos. Todos nuestros pertrechos están siendo enviados a Silithus mientras hablamos. Espero que el último envío llegue en $2113w días. Cuando todo esté listo allí, aquel que haya completado la difícil tarea de reconstruir el cetro del Mar de Dunas podrá golpearlo contra el gong del Escarabajo para abrir las puertas de Ahn''Qiraj. ¡Entonces tendrá lugar la batalla más dura vivida en siglos!$B$B¡Lok''tar Ogar!' WHERE `ID`=11372;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 호드는 안퀴라즈 전쟁에 필요한 물자를 모두 모았네! 지금은 약해 빠진 얼라이언스 놈들이 물자 수집을 끝내기만 기다리고 있지. 얼라이언스의 물자 수집이 끝나면 모든 물자를 실리더스로 옮기기 시작할 것이야. 그리고 물자 수송이 완료되면 머지않아 전쟁이 시작될 것일세!', `MaleText_loc4`='$C，部落已经集齐安其拉一战所需的物资了！在等待那帮联盟完成任务之后，我们就可以开始运送物资了。等远在希利苏斯的军队准备就绪时，战争也将拉开序幕！', `MaleText_loc5`='$C，部落已收集好所有安其拉之戰所需的物資!現在就等渺小的聯盟跟上進度。當跟上之後，我們將運送所有作戰物資前往希利蘇斯。軍隊集結之後不久戰爭就要開打了!', `MaleText_loc7`='¡$C, la Horda ha reunido todo lo que necesita para la guerra de Ahn''Qiraj! Ahora tenemos que esperar a que la endeble Alianza nos alcance. Cuando lo haga, empezaremos a enviar todo a Silithus. Tras preparar todo allí, no debería tardar mucho en dar comienzo la guerra.' WHERE `ID`=11373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구리 주괴는 $1998w개 중 $2018w개를 모았네. 주석 주괴는 $2006w개가 필요한데 $2005w개를 모았네. 그리고 이번 전쟁에서 승리하려면 제련된 미스릴 주괴 $2009w개가 필요한데 지금까지 $2008w개를 모았다네.', `MaleText_loc4`='我们已经收集到$2018w块铜锭、$2005w块锡锭和$2008w块秘银锭，而总的需求量是$1998w、$2006w和$2009w。', `MaleText_loc5`='我們已有$2018w個銅錠超過所需的$1998w個。已收集了$2005w個錫錠及$2008w個秘銀錠，總需求量分別是$2006w個錫錠和$2009w個秘銀錠。', `MaleText_loc7`='De las $1998w barras de cobre que necesitaremos, tenemos $2018w. El número de barras de estaño asciende a $2005w de las $2006w necesarias. Y se han fundido para la causa $2008w barras de mitril de $2009w.' WHERE `ID`=11374;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방금 약초에 대한 보고를 받았네. 필요한 평온초는 모두 $2020w개인데 현재까지 $2021w개를 모았고, 화염초는 $2051w개 중$2050w개, 보라 연꽃은 $2055w개 중 $2054w개를 모았다고 하네.', `MaleText_loc4`='我刚得到消息说，我们已经收集到$2021w份宁神花、$2050w份火焰花和$2054w份紫莲花，而总的需求量分别是$2020w、$2051w和$2055w。', `MaleText_loc5`='我剛收到最新消息。我們現在已有$2021w寧神花超過所需的$2020w。已收集了$2050w火焰花及$2054w紫蓮花，總需求分別是$2051w火焰花和$2055w紫蓮花。', `MaleText_loc7`='Acabo de recibir las últimas cifras. Actualmente tenemos $2021w flores de paz de $2020w, $2050w de $2051w flores de fuego y $2054w de un total de $2055w lotos cárdenas de las plantas solicitadas.' WHERE `ID`=11375;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠시만 기다려 보게. 기억할 숫자가 뭐가 이렇게 많은지... 질긴 가죽은 $2067w개 중 $2066w개를 모은 것 같네. 그리고 두꺼운 가죽은 $2071w개 중 $2070w개, 튼튼한 가죽은 $2074w개 중 $2073w개를 모아서 쌓아 두었네.', `MaleText_loc4`='给我点时间，要记录的数据很多。看来我们已经收集到$2066w块重皮、$2070w块厚皮和$2073w块硬甲皮了，总的需求量分别是$2067w、$2071w和$2074w。', `MaleText_loc5`='等我一下;這兒有很多數字要記一下。看來我們需要$2067w張重皮，現在只收集到$2066w張。還有，厚皮也需要$2071w張，現在只收集到$2070w張。需要$2074w張粗皮現在也只有$2073w張。', `MaleText_loc7`='Dame un momento; son muchos números los que tengo que recordar. Parece que hemos reunido $2066w pieles de cuero pesado de las $2067w necesarias. Además, también tenemos almacenadas $2070w pieles de cuero grueso de un total de $2071w y $2073w pieles de cuero basto de las $2074w necesarias.' WHERE `ID`=11376;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='붕대? 그건 왜 물어보나? 붕대가 필요할 때까지 오래 버텨 보려는 속셈인가? 하하! 아주 좋아. 알려주도록 하겠네. 양모 붕대는 $2080w개 중 $2079w개를 모았네. 그리고 마법 붕대는 $2086w개를 모아야 하는데 그중 $2085w개를, 룬무늬 붕대는 $2090w개 중 $2089w개를 모았네.', `MaleText_loc4`='绷带？为什么，你需要绷带救命吗？哈哈！很好，$R，我会告诉你的。我们已经收集到$2079w根绒线绷带了，总的需求量是$2080w根。另外，到目前为止，我们拥有$2085w根魔纹绷带和$2089w根符文布绷带，总的需求量分别是$2086w和$2090w。', `MaleText_loc5`='繃帶?為什麼，你是打算活久一點所以才需要它們嗎?哈!很好，$r，我告訴你。我們需要$2080w絨線繃帶，但目前只有$2079w張。目前還需要$2086w魔紋布繃帶，但目前只有$2085w張。符文布繃帶要$2090w，目前也只收集$2089w。', `MaleText_loc7`='¿Vendas? ¿Por qué? ¿Pretendes sobrevivir el tiempo suficiente como para hacer uso de ellas? ¡Ja! Muy bien, $r, te lo diré. De las $2080w vendas de lana necesarias, hemos reunido $2079w. Asimismo, hasta la fecha hemos recogido $2085w vendas de tejido mágico de un total de $2086w y $2089w vendas de paño rúnico de las $2090w requeridas.' WHERE `ID`=11377;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='식량! 드디어 내가 관심 있는 분야를 물어보는군! 보고받은 바로는 늑대 살코기 스테이크는 $2096w개 중 $2095w개, 점박이놀래기 구이는 $2103w개 중 $2102w개, 훈제 연어는 $2106w개 중 $2105w개를 모아서 냉장 창고에 저장해 두었다고 하네.', `MaleText_loc4`='收集食物是眼下我惟一的工作！我们已经收集到$2095w块瘦狼排、$2102w条斑点黄尾鱼和$2105w条烤鲑鱼了，总的需求量分别是$2096w、$2103w和$2106w。', `MaleText_loc5`='食物，是現在能塞我牙縫的東西!我說過我們需要$2096w瘦狼排，現在有$2095w;$2103w有斑點的黃尾魚，現在有$2102w;$2106w冷藏並已儲存的烤鮭魚，現在有$2105w。', `MaleText_loc7`='Comida... ¡Por fin algo a lo que se le puede hincar el diente! Me han dicho que tenemos en hielo y almacenados $2095w filetes de lobo magro de $2096w, $2102w serviolas moteadas de un total de $2103w y $2105w salmones al horno de $2106w.' WHERE `ID`=11378;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='만나서 반가워요. 여기 오신 이유가 안퀴라즈 전쟁 준비 상황을 묻기 위한 것이라면 좋겠군요. 우리는 지금 도움이 절실한 상황이에요.$B$B전쟁 물자 준비 작업은 실리시드와 놈들의 주인들을 상대로 벌이게 될 안퀴라즈 전쟁에 대비해 얼라이언스와 호드가 합동으로 펼치는 작전이에요. 우리는 아이언포지의 군사 지구에서 전쟁 물자를 생산하는 데 필요한 모든 종류의 재료를 모으고 있는데 이런 수집 임무에는 당신의 도움이 필요해요.$B$B이번 임무에 대해서 지휘관님과 얘기해 보시리라 믿어요.', `MaleText_loc4`='很高兴见到你，$C。我想你是为安其拉之战而来的吧。我们急需帮助。$B$B联盟和部落需要同仇敌忾，共同对抗安其拉异种虫类和它们的首脑。我们在铁炉堡的军事区收集原料以制造各种战争物资，这些收集工作需要你的帮助。$B$B你可以跟我们的指挥官谈谈吗？', `MaleText_loc5`='你好，$c。我希望你是來問安其拉之戰的事。我們需要很多協助。$B$B這是場聯盟和部落結合起來準備對抗安其拉異種和主使者的大戰。在鐵爐堡的軍事區，我們正在收集所有的物品來製造我們的作戰物資，而這些收集的任務正需要你的幫忙。$B$B我能請你去和我們的指揮官談談嗎?', `MaleText_loc7`='Hola, $c. Espero que hayas venido a preguntar por la campaña para la guerra de Ahn''Qiraj. Vamos a necesitar mucha ayuda.$B$BLa campaña es un esfuerzo colectivo entre la Alianza y la Horda para prepararse para la inminente guerra contra los silítidos y sus maestros en Ahn''Qiraj. En la Sala Militar de Forjaz estamos recogiendo todo tipo de productos para el aprovisionamiento de guerra y precisamos tu ayuda.$B$B¿Podrías ir a hablar con nuestro Comandante para ofrecerle tu ayuda?' WHERE `ID`=11379;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='만나서 반가워요. 여기 오신 이유가 안퀴라즈 전쟁 준비 상황을 묻기 위한 것이라면 좋겠습니다. 우리는 지금 도움이 절실한 상황입니다.$B$B전쟁 물자 준비 작업은 실리시드와 놈들의 주인들을 상대로 벌이게 될 안퀴라즈 전쟁에 대비해 얼라이언스와 호드가 합동으로 펼치는 작전입니다. 우리는 아이언포지의 군사 지구에서 전쟁 물자를 생산하는 데 필요한 모든 종류의 재료를 모으고 있는데 이런 수집 임무에는 당신의 도움이 필요합니다.$B$B이번 임무에 대해 지휘관님과 얘기해 보시리라 믿습니다.', `FemaleText_loc4`='很高兴见到你，$C。我想你是为安其拉一战而来的吧。我们急需帮助。$B$B部落和联盟必须携手对抗安其拉异种虫类大军和它们的主使者。在铁炉堡的军事区，我们正在收集原料制造战争物资，收集工作需要你的帮助。$B$B你可以跟我们的指挥官谈谈吗？', `FemaleText_loc5`='你好，$c。我希望你是來問安其拉之戰的事。我們需要很多協助。$B$B這是場聯盟和部落結合起來準備對抗安其拉異種和主使者的大戰。在鐵爐堡的軍事區，我們正在收集所有的物品來製造我們的作戰物資，而這些收集的任務正需要你的幫忙。$B$B我能請你去和我們的指揮官談談嗎?', `FemaleText_loc7`='Hola, $c. Espero que hayas venido a preguntar por la campaña para la guerra de Ahn''Qiraj. Vamos a necesitar mucha ayuda.$B$BLa campaña es un esfuerzo colectivo entre la Alianza y la Horda para prepararse para la inminente guerra contra los silítidos y sus maestros en Ahn''Qiraj. En la Sala Militar de Forjaz estamos recogiendo todo tipo de productos para el aprovisionamiento de guerra y precisamos tu ayuda.$B$B¿Podrías ir a hablar con nuestro Comandante para ofrecerle tu ayuda?' WHERE `ID`=11380;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='엘룬께 영광을. 여기 오신 이유가 안퀴라즈 전쟁 준비 상황을 묻기 위한 것이라면 좋겠군요. 우리는 지금 도움이 절실한 상황입니다.$B$B전쟁 물자 준비 작업은 실리시드와 놈들의 주인들을 상대로 벌이게 될 안퀴라즈 전쟁에 대비해 얼라이언스와 호드가 합동으로 펼치는 작전입니다. 우리는 아이언포지의 군사 지구에서 전쟁 물자를 생산하는 데 필요한 모든 종류의 재료를 모으고 있는데 이런 수집 임무에는 그대의 도움이 절실히 필요합니다.$B$B이번 임무에 대해 지휘관님과 얘기해 보시리라 믿습니다.', `FemaleText_loc4`='很高兴见到你，$C。我想你是为安其拉一战而来的吧。我们急需帮助。$B$B部落和联盟必须携手对抗安其拉异种虫类大军和它们的主使者。在铁炉堡的军事区，我们正在收集原料制造战争物资，收集工作需要你的帮助。$B$B你可以跟我们的指挥官谈谈吗？', `FemaleText_loc5`='你好，$c。我希望你是來問安其拉之戰的事。我們需要很多協助。$B$B這是場聯盟和部落結合起來準備對抗安其拉異種和主使者的大戰。在鐵爐堡的軍事區，我們正在收集所有的物品來製造我們的作戰物資，而這些收集的任務正需要你的幫忙。$B$B我能請你去和我們的指揮官談談嗎?', `FemaleText_loc7`='Hola, $c. Espero que hayas venido a preguntar por la campaña para la guerra de Ahn''Qiraj. Vamos a necesitar mucha ayuda.$B$BLa campaña es un esfuerzo colectivo entre la Alianza y la Horda para prepararse para la inminente guerra contra los silítidos y sus maestros en Ahn''Qiraj. En la Sala Militar de Forjaz estamos recogiendo todo tipo de productos para el aprovisionamiento de guerra y precisamos tu ayuda.$B$B¿Podrías ir a hablar con nuestro Comandante para ofrecerle tu ayuda?' WHERE `ID`=11381;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑네. 안퀴라즈 전쟁 준비 상황을 물어보러 왔다면 언제나 환영일세. 우리는 지금 도움이 절실히 필요해.$B$B전쟁 물자 준비는 실리시드와 놈들을 조종하는 무리를 상대로 벌일 안퀴라즈 전쟁에 대비해 호드와 얼라이언스가 합동으로 펼치는 작전이라네. 우리는 오그리마의 정기의 골짜기에서 전쟁 물자를 만드는 데 필요한 온갖 재료를 모으고 있어. 이런 임무에는 자네의 도움이 꼭 필요하지.$B$B장군님과 이 일에 대해 꼭 의논해 볼 거라 믿네.', `MaleText_loc4`='嗨，$C。我想你是为安其拉之战而来的吧。我们急需帮助。$B$B部落和联盟必须携手对抗安其拉异种虫类大军和它们的主使者。在奥格瑞玛的精神谷，我们正在收集原料制造战争物资，收集工作需要你的帮助。$B$B你可以跟我们的指挥官谈谈吗？', `MaleText_loc5`='嗨，$c。我相信你是來這裡詢問安其拉之戰的事。我們需要極大的協助。$B$B這是場聯盟和部落結合起來準備對抗安其拉異種和主使者的大戰。在奧格瑪的精神谷，我們正在收集大量的物品來製作戰需物資，而這些收集的任務正需要你的幫忙。$B$B我能請你去和我們的指揮官談談嗎?', `MaleText_loc7`='Ave, $c. Confío en que hayas venido a preguntar por la campaña para la guerra de Ahn''Qiraj. Vamos a necesitar toda la ayuda posible.$B$BLa campaña de guerra es un esfuerzo conjunto entre la Horda y la Alianza para prepararse contra la inminente guerra contra los silítidos y sus maestros de Ahn''Qiraj. En el Valle de los Espíritus de Orgrimmar estamos recogiendo todo tipo de productos para el aprovisionamiento de guerra y precisamos tu ayuda.$B$B¿Podrías ir a hablar con nuestro Comandante para ofrecerle tu ayuda?' WHERE `ID`=11382;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하십니까? 안퀴라즈 전쟁 준비 상황을 물어보러 왔다면 언제나 환영입니다. 저희는 지금 도움이 절실한 상황입니다.$B$B전쟁 물자 준비는 실리시드와 놈들을 조종하는 무리를 상대로 벌일 안퀴라즈 전쟁에 대비해 호드와 얼라이언스가 합동으로 펼치는 작전입니다. 우리는 오그리마의 정기의 골짜기에서 전쟁 물자를 만드는 데 필요한 온갖 재료를 모으고 있지요. 이런 임무에는 당신의 도움이 꼭 필요합니다.$B$B장군님과 이 일에 대해 얘기해 보실 거죠?', `FemaleText_loc4`='嗨，$C。我想你是为安其拉一战而来的吧。我们急需帮助。$B$B部落和联盟必须携手对抗安其拉异种虫类大军和它们的主使者。在奥格瑞玛的精神谷，我们正在收集原料制造战争物资，收集工作需要你的帮助。$B$B你可以跟我们的指挥官谈谈吗？', `FemaleText_loc5`='嗨，$c。我相信你是來這裡詢問安其拉之戰的事。我們需要極大的協助。$B$B這是場聯盟和部落結合起來準備對抗安其拉異種和主使者的大戰。在奧格瑪的精神谷，我們正在收集大量的物品來製造作戰物資，而這些收集的任務正需要你的幫忙。$B$B我能請你去和我們的指揮官談談嗎?', `FemaleText_loc7`='Ave, $c. Confío en que hayas venido a preguntar por la campaña para la guerra de Ahn''Qiraj. Vamos a necesitar toda la ayuda posible.$B$BLa campaña de guerra es un esfuerzo conjunto entre la Horda y la Alianza para prepararse contra la inminente guerra contra los silítidos y sus maestros de Ahn''Qiraj. En el Valle de los Espíritus de Orgrimmar estamos recogiendo todo tipo de productos para el aprovisionamiento de guerra y precisamos tu ayuda.$B$B¿Podrías ir a hablar con nuestro Comandante para ofrecerle tu ayuda?' WHERE `ID`=11383;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하십니까? 여기 오신 이유가 안퀴라즈 전쟁 준비 상황을 묻기 위한 것이라면 좋겠습니다. 우리는 지금 도움이 절실한 상황입니다.$B$B전쟁 물자 준비 작업은 실리시드와 놈들의 주인들을 상대로 벌이게 될 안퀴라즈 전쟁에 대비해 호드와 얼라이언스가 합동으로 펼치는 작전입니다. 우리는 오그리마의 정기의 골짜기에서 전쟁 물자를 생산하는 데 필요한 모든 종류의 재료를 모으고 있는데 이런 수집 임무에는 당신의 도움이 필요합니다.$B$B이번 임무에 대해 지휘관님과 상의해 보시리라 믿습니다.', `FemaleText_loc4`='嗨，$C。我想你是为安其拉一战而来的吧。我们急需帮助。$B$B部落和联盟必须携手对抗安其拉异种虫类大军和它们的主使者。在奥格瑞玛的精神谷，我们正在收集原料制造战争物资，收集工作需要你的帮助。$B$B你可以跟我们的指挥官谈谈吗？', `FemaleText_loc5`='嗨，$c。我相信你是來這裡詢問安其拉之戰的事。我們需要極大的協助。$B$B這是場聯盟和部落結合起來準備對抗安其拉異種和主使者的大戰。在奧格瑪的精神谷，我們正在收集大量的物品來製造作戰物資，而這些收集的任務正需要你的幫忙。$B$B我能請你去和我們的指揮官談談嗎?', `FemaleText_loc7`='Ave, $c. Confío en que hayas venido a preguntar por la campaña para la guerra de Ahn''Qiraj. Vamos a necesitar toda la ayuda posible.$B$BLa campaña de guerra es un esfuerzo conjunto entre la Horda y la Alianza para prepararse contra la inminente guerra contra los silítidos y sus maestros de Ahn''Qiraj. En el Valle de los Espíritus de Orgrimmar estamos recogiendo todo tipo de productos para el aprovisionamiento de guerra y precisamos tu ayuda.$B$B¿Podrías ir a hablar con nuestro Comandante para ofrecerle tu ayuda?' WHERE `ID`=11384;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까? 저는 세나리온 요새의 야수 관리인 레오렌입니다.', `MaleText_loc4`='你好，$C。我是塞纳里奥要塞的兽栏管理员莱欧伦。', `MaleText_loc5`='你好，$c。我是萊歐倫。塞納里奧城堡的獸欄管理員。', `MaleText_loc7`='Saludos, $c. Soy Leoren, maestro de establos del Fuerte Cenarion.' WHERE `ID`=11385;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심스럽게 포장된 선물 더미가 있습니다.', `MaleText_loc4`='这里有一大堆精心包裹的礼物。', `MaleText_loc5`='這裏有一大堆精心包裹的禮物。', `MaleText_loc7`='Hay una pila de regalos envueltos aquí.' WHERE `ID`=11386;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선물에는 ''40세 이상의 모험가용''이라는 딱지가 붙어있습니다.', `MaleText_loc4`='这件礼物的卡片上写着：“40岁以上适用。”', `MaleText_loc5`='這件禮物的卡片上寫著:「40歲以上適用。」', `MaleText_loc7`='La etiqueta de este regalo dice: "Para mayores de 40."' WHERE `ID`=11387;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선물 더미에서 당신만을 위한 상자를 가져가십시오.', `MaleText_loc4`='拿取你的礼物！', `MaleText_loc5`='拿取你的禮物!', `MaleText_loc7`='Coge tu regalo de la pila.', `FemaleText_loc1`='선물 더미에서 당신만을 위한 상자를 가져가십시오.', `FemaleText_loc4`='拿取你的礼物！', `FemaleText_loc5`='拿取你的禮物!', `FemaleText_loc7`='Coge tu regalo de la pila.' WHERE `ID`=11388;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑네, 충성스러운 시민이여.', `MaleText_loc4`='你好啊。', `MaleText_loc5`='你好啊。', `MaleText_loc7`='Saludos, $gciudadano:ciudadana;.' WHERE `ID`=11389;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 세계는 자네와 자네 동맹에게 큰 은혜를 입었네, $n.', `MaleText_loc4`='整个世界都感激你和你的同伴们所做的一切，$n。', `MaleText_loc5`='這個世界很感激你和你的盟友，$n。', `MaleText_loc7`='El mundo está en deuda contigo y con tus aliados, $n.' WHERE `ID`=11390;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크툰이 살아 있었다면 우리의 자유는 아무런 의미가 없었을 것입니다. 진정 그대는 고대의 예언에 계시된 영웅이 맞습니다.', `MaleText_loc4`='如果克苏恩还活着的话，我们的自由将变得没有意义。你真是个预言中的勇士。', `MaleText_loc5`='若克蘇恩還活著，我們的自由就根本不算什麼。你真是一位預言勇士。', `MaleText_loc7`='Nuestra libertad habría sido inútil si C''Thun hubiera sobrevivido. Eres $gun verdadero campeón:una verdadera campeona; de la profecía.' WHERE `ID`=11391;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='영웅이여, 이 저주받은 신전에서 무슨 일이 있었는지는 모두 알게 될 것입니다. 그리고 모든 사실은 역사에 기록될 것입니다. 아제로스에서 머나먼 황천에 이르기까지 위대한 전설로 사람들의 입에 오르내릴 것입니다!', `FemaleText_loc4`='很快人们就会知道这座被诅咒的神殿背后的秘密，英雄。它将被载入史册，跟那些从扭曲虚空到艾泽拉斯的传说一起，被永远传诵。', `FemaleText_loc5`='英雄，在這受咒的寺廟裡所發生的事情都會被發現。它會被記載於史書中－故事以傳說描述艾澤拉斯遠至虛空本身!', `FemaleText_loc7`='Todos sabrán lo que ha acontecido en este templo maldito, $ghéroe:heroína;. ¡Esta gesta formará parte de los libros de historia: las aventuras convertidas en leyenda desde Azeroth hasta los mismos límites del Vacío!' WHERE `ID`=11392;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 전운의 그림자가 최고조로 짙어지고 있지만 우리에게는 호드와 얼라이언스의 뛰어난 전사들이 많이 있기 때문에 아무 걱정이 없소.$B$B단, 이들이 서로 위협하지만 않는다면...', `MaleText_loc4`='战争犹如箭在弦上，蓄势待发；部落和联盟都有着无数强大的勇士。$B$B但愿他们不会互相争斗……', `MaleText_loc5`='既然戰火蔓延已達巔峰，到目前為止，部落與聯盟的強壯戰士都沒有短缺。$B$B但願我們能將他們趕盡殺絕...', `MaleText_loc7`='Ahora que la guerra está en plena ebullición, contamos con buenos combatientes tanto de la Horda como de la Alianza.$B$BSi tan solo pudiéramos disuadirlos de atacarse los unos a los otros...' WHERE `ID`=11393;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잠깐만요! 우리 감시병이 뭔가 발견한 것 같군요!', `FemaleText_loc4`='我们的哨兵发现了一些东西！', `FemaleText_loc5`='我們的崗哨好像發現了什麼!', `FemaleText_loc7`='¡Espera! Parece que nuestro oteador ha visto algo.' WHERE `ID`=11394;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선물에는 ''20세 이상의 모험가용''이라는 딱지가 붙어있습니다.', `MaleText_loc4`='这件礼物的卡片上写着：“20岁以上适用。”', `MaleText_loc5`='這件禮物的卡片上寫著:「20歲以上適用。」', `MaleText_loc7`='La etiqueta de este regalo dice: "Para mayores de 20."' WHERE `ID`=11395;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선물에는 ''10세 이상의 모험가용''이라는 딱지가 붙어있습니다.', `MaleText_loc4`='这件礼物的卡片上写着：“10岁以上适用。”', `MaleText_loc5`='這件禮物的卡片上寫著:「10歲以上適用。」', `MaleText_loc7`='La etiqueta de este regalo dice: "Para mayores de 10."' WHERE `ID`=11396;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오호라, 네 놈이 이번 겨울맞이 축제에 내 칼을 즐겁게 해 주겠구나! 이얍!', `MaleText_loc4`='明年的冬幕节就是你的忌日！呀哈！', `MaleText_loc5`='明年的冬幕節就是你的忌日!呀哈!', `MaleText_loc7`='¡Serás un buen festín en este Festival de Invierno! ¡Grrrroaj!', `FemaleText_loc1`='오호라, 네 놈이 이번 겨울맞이 축제에 내 칼을 즐겁게 해 주겠구나! 이얍!', `FemaleText_loc4`='明年的冬幕节就是你的忌日！呀哈！', `FemaleText_loc5`='明年的冬幕節就是你的忌日!呀哈!', `FemaleText_loc7`='¡Serás un buen festín en este Festival de Invierno! ¡Grrrroaj!' WHERE `ID`=11397;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 건달 $c 녀석도 우리의 겨울맞이 축제 강탈을 앗아가지 못할 것이다. 저놈들을 잡아라!', `MaleText_loc4`='你这饭桶$c别想抢走我们的摇钱树！哇呀呀呀！', `MaleText_loc5`='你這飯桶$c別想搶走我們的冬幕節!還給我!', `MaleText_loc7`='¡$gNingún:ninguna; $c va a expoliar nuestro Festival de Invierno! ¡Cogedlos!', `FemaleText_loc1`='어떤 건달 $c 녀석도 우리의 겨울맞이 축제 강탈을 앗아가지 못할 것이다. 저놈들을 잡아라!', `FemaleText_loc4`='你这饭桶$c别想抢走我们的摇钱树！哇呀呀呀！', `FemaleText_loc5`='你這飯桶$c別想搶走我們的冬幕節!還給我!', `FemaleText_loc7`='¡$gNingún:ninguna; $c va a expoliar nuestro Festival de Invierno! ¡Cogedlos!' WHERE `ID`=11398;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='순록을 구하러 여기에 온 거로구나! 저놈들은 상어에게 데려가라!', `MaleText_loc4`='旱鸭子们来抢驯鹿了！给他们些颜色看看！', `MaleText_loc5`='旱鴨子們來搶麋鹿了!給他們些顏色看看!', `MaleText_loc7`='¡Estos mojigatos están aquí por el reno! ¡Dales la pata!', `FemaleText_loc1`='순록을 구하러 온 거로구나! 저놈들은 상어에게 데려가라!', `FemaleText_loc4`='旱鸭子们来抢驯鹿了！给他们些颜色看看！', `FemaleText_loc5`='旱鴨子們來搶麋鹿了!給他們些顏色看看!', `FemaleText_loc7`='¡Estos mojigatos están aquí por el reno! ¡Dales la pata!' WHERE `ID`=11399;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저놈들이 순록을 풀어주려 한다! 아무도 도망가지 못하게 해라!', `MaleText_loc4`='他们想要救走人质！一个活口都别留！', `MaleText_loc5`='他們想要救走人質!一個活口都別留!', `MaleText_loc7`='¡Es un intento de rescate! ¡Que no escape nadie!', `FemaleText_loc1`='저놈들이 순록을 풀어주려 한다! 아무도 도망가지 못하게 해라!', `FemaleText_loc4`='他们想要救走人质！一个活口都别留！', `FemaleText_loc5`='他們想要救走人質!一個活口都別留!', `FemaleText_loc7`='¡Es un intento de rescate! ¡Que no escape nadie!' WHERE `ID`=11400;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겨울 할아버지에게 내 안부나 전해줘라, 이 쓰레기 같은 $r...', `MaleText_loc4`='别忘了帮我向那老头问好，人渣……', `MaleText_loc5`='別忘了幫我向那老頭問好，人渣...', `MaleText_loc7`='Mándale recuerdos de mi parte al Gran Padre Invierno, escoria...', `FemaleText_loc1`='겨울 할아버지에게 내 안부나 전해줘라, 이 쓰레기 같은 $r...', `FemaleText_loc4`='别忘了帮我向那老头问好，人渣……', `FemaleText_loc5`='別忘了幫我向那老頭問好，人渣...', `FemaleText_loc7`='Mándale recuerdos de mi parte al Gran Padre Invierno, escoria...' WHERE `ID`=11401;
