UPDATE `locales_broadcast_text` SET `MaleText_loc1`='순록을 풀어주려 한다! 저 녀석들을 모두 죽여라!', `MaleText_loc4`='他们想要救走人质！杀了他们！', `MaleText_loc5`='他們想要救走人質!殺了他們!', `MaleText_loc7`='¡Es un intento de rescate! ¡Acaben con ellos!', `FemaleText_loc1`='순록을 풀어주려 한다! 저 녀석들을 모두 죽여라!', `FemaleText_loc4`='他们想要救走人质！杀了他们！', `FemaleText_loc5`='他們想要救走人質!殺了他們!', `FemaleText_loc7`='¡Es un intento de rescate! ¡Acaben con ellos!' WHERE `ID`=11403;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멧젠이 이번 겨울맞이 축제에 하게 될 일은 꼬치 구이가 되는 것이다!', `MaleText_loc4`='梅森在冬幕节只有一件事情可做，那就是躺在烤肉架上！', `MaleText_loc5`='梅特森在冬幕節只有一件事情可做，那就是躺在烤肉架上!', `MaleText_loc7`='¡Lo único que Metzen va a hacer este Festival de Invierno es tostarse en un asador!', `FemaleText_loc1`='멧젠이 이번 겨울맞이 축제에 하게 될 일은꼬치 구이가 되는 것이다!', `FemaleText_loc4`='梅森在冬幕节只有一件事情可做，那就是躺在烤肉架上！', `FemaleText_loc5`='梅特森在冬幕節只有一件事情可做，那就是躺在烤肉架上!', `FemaleText_loc7`='¡Lo único que Metzen va a hacer este Festival de Invierno es tostarse en un asador!' WHERE `ID`=11404;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 잔다이스 바로브의 일지는 언데드에 대한 욕설과 분노로 가득합니다. 책 뒷부분까지 읽어보니 어떤 가방을 만드는 도안이 그려져 있습니다. 하지만, 이 도안을 해석하기에는 당신의 재봉술에 대한 이해가 조금 부족합니다.', `FemaleText_loc4`='詹迪斯·巴罗夫的日记充斥着被遗忘者疯狂的怨念。在日记的结尾似乎有一份制作背包的裁缝图样。按你对裁缝技能的掌握程度，还不足以解读这张图样。', `FemaleText_loc5`='詹迪斯·巴羅夫的日記寫滿了不死族誇大的豪言壯語。翻到書的最後一頁，似乎出現一個某種製作背包的裁縫術語。以你對裁縫的了解還無法讓你破解這術語。', `FemaleText_loc7`='El diario de Jandice Barov está lleno de calumnias y sandeces sobre los no-muertos. Ya casi al final del libro, se encuentra lo que parece ser un patrón de sastrería para confeccionar algún tipo de bolsa. Tus conocimientos de confección son insuficientes para descifrar el patrón.' WHERE `ID`=11405;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 잔다이스 바로브의 일지는 언데드에 대한 욕설과 분노로 가득합니다. 책 뒷부분까지 읽어보니 지옥매듭 가방을 만드는 도안이 나와 있습니다. 바로 흑마법사가 영혼의 조각을 보관하는 가방입니다. 도안을 당신의 마법책에 옮겨 적겠습니까?', `FemaleText_loc4`='詹迪斯·巴罗夫的日记充斥着被遗忘者疯狂的怨念。在日记的结尾似乎有一份制作恶魔布包的裁缝图样。术士们使用恶魔布包来存储灵魂碎片。你想要在自己的日记里记录下图样的内容吗？', `FemaleText_loc5`='詹迪斯·巴羅夫的日記寫滿了不死族誇大的豪言壯語。翻到書的最後一頁，似乎出現一個製作惡魔布包的裁縫術語。這背包是給術士裝靈魂裂片用的，你能複製這術語記在你的日記本裡嗎?', `FemaleText_loc7`='El diario de Jandice Barov está lleno de calumnias y sandeces sobre los no-muertos. Ya casi al final del libro, se encuentra lo que parece ser un patrón de sastrería para confeccionar una bolsa de tela vil. Esta bolsa la utilizan los brujos para guardar fragmentos de alma. ¿Deseas copiar el patrón en tu propio diario?' WHERE `ID`=11406;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<도안을 마법책에 옮겨 적습니다.>', `MaleText_loc4`='<将图样记录到我的日记中。>', `MaleText_loc5`='<將圖樣記錄到我的日記中。>', `MaleText_loc7`='<Copiar el patrón en mi diario.>', `FemaleText_loc1`='<도안을 마법책에 옮겨 적습니다.>', `FemaleText_loc4`='<将图样记录到我的日记中。>', `FemaleText_loc5`='<將圖樣記錄到我的日記中。>', `FemaleText_loc7`='<Copiar el patrón en mi diario.>' WHERE `ID`=11407;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 일지를 꼭 쥐고 있던 손에서 힘을 뺍니다.', `FemaleText_loc4`='%s松开了她紧紧攥住日记的手。', `FemaleText_loc5`='%s鬆開她原本緊握的筆記。', `FemaleText_loc7`='%s suelta el diario que había estado sujetando celosamente.' WHERE `ID`=11408;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 광기의 함성을 지릅니다!', `MaleText_loc4`='%s发出战斗的怒吼！', `MaleText_loc5`='%s發出戰鬥怒吼!', `MaleText_loc7`='¡%s entona un canto de guerra!' WHERE `ID`=11409;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 잔다이스 바로브의 일지는 언데드에 대한 욕설과 분노로 가득합니다. 책 뒷부분까지 읽어보니 지옥매듭 가방을 만드는 도안이 나와 있습니다. 바로 흑마법사가 영혼의 조각을 보관하는 가방입니다. 당신은 이미 이 가방을 만드는 방법을 알고 있습니다.', `FemaleText_loc4`='詹迪斯·巴罗夫的日记充斥着被遗忘者疯狂的怨念。在日记的结尾似乎有一份制作恶魔布包的裁缝图样，术士们使用恶魔布包来存储灵魂碎片。你已经学会了制作这种背包的方法。', `FemaleText_loc5`='詹迪斯·巴羅夫的日記寫滿了不死族誇大的豪言壯語。翻到書的最後一頁，似乎出現一個製作惡魔布包的裁縫術語。這背包是給術士裝靈魂裂片的用，你已經知道要如何做出這種袋子。', `FemaleText_loc7`='El diario de Jandice Barov está lleno de calumnias y sandeces sobre los no-muertos. Ya casi al final del libro, se encuentra lo que parece ser un patrón de sastrería para confeccionar una bolsa de tela vil. Esta bolsa la utilizan los brujos para guardar fragmentos de alma. Ya sabes cómo confeccionar esta bolsa.' WHERE `ID`=11410;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나무구렁 일족과 적대적인 관계가 아니라는 것을 증명한 자만이 공격을 받지 않고 무사히 요새를 통과할 수 있소. 이방인이여, 당신은 우리의 신뢰를 얻기 위해 어떠한 노력을 했소?', `MaleText_loc4`='只有那些对木喉没有敌意的人能通过安全通过要塞。陌生人，你赢得我们的信任了吗？', `MaleText_loc5`='只有那些證明自己沒有對木喉部族心懷敵意的人才能在部落被攻擊時不感到害怕。你想努力贏得我們的信任嗎，外來者?', `MaleText_loc7`='Solo aquellos que hayan demostrado no ser hostiles con los Fauces de Madera pueden pasar por el fuerte sin recelos de ser atacados. ¿Te has esforzado para ganar nuestra confianza, forastero?' WHERE `ID`=11411;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 무얼 찾고 있소?', `MaleText_loc4`='你在找什么，$C？', `MaleText_loc5`='你在找什麼，$c?', `MaleText_loc7`='¿Qué es lo que buscas, $c?' WHERE `ID`=11412;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기다리겠습니다.', `MaleText_loc4`='我会耐心等待的。', `MaleText_loc5`='我會等著。', `MaleText_loc7`='Esperaré.', `FemaleText_loc1`='기다릴게요.', `FemaleText_loc4`='我会耐心等待的。', `FemaleText_loc5`='我會等著。', `FemaleText_loc7`='Esperaré.' WHERE `ID`=11413;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새해를 맞이하여 새롭게 나온: PX-238 겨울맞이 원더볼트를 소개하지! 자자, 부끄러워 말고 어서 올라가 보라고.$B$B아, 해 보기 전에 이 양식에 서명하라고. 우린 아직 이 기계에서 몇 개의 작동 오류를 수정하려고 작업하고 있는 중이거든.', `MaleText_loc4`='本年度新品：PX-238型欢乐制造器。请上前来尝试一下！不要害羞！$B$B在尝试之前请填写这些表格，我们还在修正这台机器的某些问题……', `MaleText_loc5`='年度新款:PX-238冬幕歡樂製造器。靠過來，別害羞!$B$B不過在你嘗試之前先簽一下這些表格，我們還在努力找出這東西的一些小問題...', `MaleText_loc7`='La última novedad este año: la PX-238 Maravoltio Invernal. ¡Acércate, no seas $gtímido:tímida;!$B$BY rellena estos formularios antes de probarla, aún estamos corrigiendo algunos problemas de este chisme...' WHERE `ID`=11414;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, $C|1이여;여;? 저는 다르나서스를 위해 일하는 인사 장교입니다. 얼라이언스 무공 훈장을 받은 모험가들을 돕는 것이 제 임무예요.$B$B꼭 몇 개를 모아와야 한다는 법은 없지만 10개를 한꺼번에 교환하시는 게 가장 좋습니다. 제게 훈장을 주시면 그대의 공적을 기록해 두겠습니다. 그러면 다르나서스에서 그대의 임무 수행 능력에 대한 인정을 받게 될 겁니다.', `MaleText_loc4`='你好，$C——我是达纳苏斯的嘉奖官。我的职责就是帮助那些获得联盟荣誉徽章的冒险者们。$B$B我一次可收取不同数量的徽章，但是对你来说，一次缴纳10枚徽章可获得最高收益。我会保留你缴纳徽章的记录，你在达纳苏斯的声望也会因此提高。', `MaleText_loc5`='你好，$c─我是代表達納蘇斯的表揚官。我的職責是協助已獲得聯盟榮譽徽章的冒險者。$B$B我接受不同數量的獎章，但對你最有利的交易就是馬上交換10個。一旦你貢獻獎章我就會將你的功績寫在我們的紀錄上。所以，你會因你的職責與貢獻獲得達納蘇斯的認同。', `MaleText_loc7`='Saludos, $c. Soy un oficial encomiado en misión en nombre de Darnassus. Mi deber es ayudar a los aventureros que hayan recibido un sello de mención de honor de la Alianza.$B$BYo acepto sellos en diferentes cantidades, pero lo mejor para ti es que me entregues un lote de diez de una sola vez. Inscribiré tus hazañas en nuestros registros cuando entregues tus sellos. De esta forma, te ganarás el reconocimiento de Darnassus por tu cumplimiento del deber y buen servicio.', `FemaleText_loc1`='안녕하십니까, $C|1이여;여;? 저는 다르나서스를 위해 일하는 인사 장교입니다. 얼라이언스 무공 훈장을 받은 모험가들을 돕는 것이 제 임무예요.$B$B꼭 몇 개를 모아와야 한다는 법은 없지만 10개를 한꺼번에 교환하시는 게 가장 좋습니다. 제게 훈장을 주시면 그대의 공적을 기록해 두겠습니다. 그러면 다르나서스에서 그대의 임무 수행 능력에 대한 인정을 받게 될 겁니다.', `FemaleText_loc4`='你好，$C——我是达纳苏斯的嘉奖官。我的职责就是帮助那些获得联盟荣誉徽章的冒险者们。$B$B我一次可收取不同数量的徽章，但是对你来说，一次缴纳10枚徽章可获得最高收益。我会保留你缴纳徽章的记录，你在达纳苏斯的声望也会因此提高。', `FemaleText_loc5`='你好，$c─我是代表達納蘇斯的表揚官。我的職責是協助已獲得聯盟榮譽徽章的冒險者。$B$B我接受不同數量的獎章，但對你最有利的交易就是馬上交換10個。一旦你貢獻獎章我就會將你的功績寫在我們的紀錄上。所以，你會因你的職責與貢獻獲得達納蘇斯的認同。', `FemaleText_loc7`='Saludos, $c. Soy una oficial encomiado en misión en nombre de Darnassus. Mi deber es ayudar a los aventureros que hayan recibido un sello de mención de honor de la Alianza.$B$BYo acepto sellos en diferentes cantidades, pero lo mejor para ti es que me entregues un lote de diez de una sola vez. Inscribiré tus hazañas en nuestros registros cuando entregues tus sellos. De esta forma, te ganarás el reconocimiento de Darnassus por tu cumplimiento del deber y buen servicio.' WHERE `ID`=11415;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요? 저는 놈리건을 위해 일하는 인사 장교입니다. 얼라이언스 무공 훈장을 받은 모험가들을 돕는 것이 제 임무죠.$B$B반드시 몇 개를 모아서 가지고 와야 한다는 법은 없지만 10개를 모아서 한꺼번에 교환하시는 게 가장 좋습니다. 저에게 훈장을 주시면 그대의 공적을 기록해 두겠습니다. 그러면 놈리건은 당신의 임무 수행 능력을 인정할 거예요.', `MaleText_loc4`='你好，$C——我是诺莫瑞根流亡者的嘉奖官。我的职责就是帮助那些获得联盟荣誉徽章的冒险者们。$B$B我一次可收取不同数量的徽章，但是对你来说，一次缴纳10枚徽章可获得最高收益。我会保留你缴纳徽章的记录，你在诺莫瑞根流亡者中的声望也会因此提高。', `MaleText_loc5`='你好，$c─我是代表諾姆瑞根流亡者的表揚官。我的職責是協助已獲得聯盟榮譽徽章的冒險者。$B$B我接受不同數量的獎章，但對你最有利的交易就是馬上交換10個。一旦你貢獻獎章我就會將你的功績寫在我們的紀錄上。所以，你會因你的職責與貢獻獲得諾姆瑞根流放者的認同。', `MaleText_loc7`='Saludos, $c. Soy un oficial encomiado en misión en nombre de los Exiliados de Gnomeregan. Mi deber es ayudar a los aventureros que hayan recibido un sello de mención de honor de la Alianza.$B$BYo acepto sellos en diferentes cantidades, pero lo mejor para ti es que me entregues un lote de diez de una sola vez. Inscribiré tus hazañas en nuestros registros cuando entregues tus sellos. De esta forma, te ganarás el reconocimiento de los Exiliados de Gnomeregan por tu cumplimiento del deber y buen servicio.', `FemaleText_loc1`='안녕하세요? 저는 놈리건을 위해 일하는 인사 장교입니다. 얼라이언스 무공 훈장을 받은 모험가들을 돕는 것이 제 임무죠.$B$B반드시 몇 개를 모아서 가지고 와야 한다는 법은 없지만 10개를 모아서 한꺼번에 교환하시는 게 가장 좋습니다. 저에게 훈장을 주시면 그대의 공적을 기록해 두겠습니다. 그러면 놈리건은 당신의 임무 수행 능력을 인정할 거예요.', `FemaleText_loc4`='你好，$C——我是诺莫瑞根流亡者的嘉奖官。我的职责就是帮助那些获得联盟荣誉徽章的冒险者们。$B$B我一次可收取不同数量的徽章，但是对你来说，一次缴纳10枚徽章可获得最高收益。我会保留你缴纳徽章的记录，你在诺莫瑞根流亡者中的声望也会因此提高。', `FemaleText_loc5`='你好，$c─我是代表諾姆瑞根流亡者的表揚官。我的職責是協助已獲得聯盟榮譽徽章的冒險者。$B$B我接受不同數量的獎章，但對你最有利的交易就是馬上交換10個。一旦你貢獻獎章我就會將你的功績寫在我們的紀錄上。所以，你會因你的職責與貢獻獲得諾姆瑞根流放者的認同。', `FemaleText_loc7`='Saludos, $c. Soy una oficial encomiada en misión en nombre de los Exiliados de Gnomeregan. Mi deber es ayudar a los aventureros que hayan recibido un sello de mención de honor de la Alianza.$B$BYo acepto sellos en diferentes cantidades, pero lo mejor para ti es que me entregues un lote de diez de una sola vez. Inscribiré tus hazañas en nuestros registros cuando entregues tus sellos. De esta forma, te ganarás el reconocimiento de los Exiliados de Gnomeregan por tu cumplimiento del deber y buen servicio.' WHERE `ID`=11416;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요? 저는 아이언포지를 위해 일하는 인사 장교입니다. 얼라이언스 무공 훈장을 받은 모험가들을 돕는 것이 제 임무죠.$B$B반드시 몇 개를 모아서 가지고 와야 한다는 법은 없지만 10개를 모아서 한꺼번에 교환하시는 게 가장 좋습니다. 저에게 훈장을 주시면 그대의 공적을 기록해 두겠습니다. 그러면 아이언포지에서는 당신의 임무 수행 능력을 인정할 거예요.', `MaleText_loc4`='你好，$C——我是铁炉堡的嘉奖官。我的职责就是帮助那些获得联盟荣誉徽章的冒险者们。$B$B我一次可收取不同数量的徽章，但是对你来说，一次缴纳10枚徽章可获得最高收益。我会保留你缴纳徽章的记录，你在铁炉堡的声望也会因此提高。', `MaleText_loc5`='你好，$c─我是代表鐵爐堡的表揚官。我的職責是協助已獲得聯盟榮譽徽章的冒險者。$B$B我接受不同數量的獎章，但對你最有利的交易就是馬上交換10個。一旦你貢獻獎章我就會將你的功績寫在我們的紀錄上。所以，你會因你的職責與貢獻獲得鐵爐堡的認同。', `MaleText_loc7`='Saludos, $c. Soy un oficial encomiado en misión en nombre de Forjaz. Mi deber es ayudar a los aventureros que hayan recibido un sello de mención de honor de la Alianza.$B$BYo acepto sellos en diferentes cantidades, pero lo mejor para ti es que me entregues un lote de diez de una sola vez. Inscribiré tus hazañas en nuestros registros cuando entregues tus sellos. De esta forma, te ganarás el reconocimiento de Forjaz por tu cumplimiento del deber y buen servicio.', `FemaleText_loc1`='안녕하세요? 저는 아이언포지를 위해 일하는 인사 장교입니다. 얼라이언스 무공 훈장을 받은 모험가들을 돕는 것이 제 임무죠.$B$B반드시 몇 개를 모아서 가지고 와야 한다는 법은 없지만 10개를 모아서 한꺼번에 교환하시는 게 가장 좋습니다. 저에게 훈장을 주시면 그대의 공적을 기록해 두겠습니다. 그러면 아이언포지에서는 당신의 임무 수행 능력을 인정할 거예요.', `FemaleText_loc4`='你好，$C——我是铁炉堡的嘉奖官。我的职责就是帮助那些获得联盟荣誉徽章的冒险者们。$B$B我一次可收取不同数量的徽章，但是对你来说，一次缴纳10枚徽章可获得最高收益。我会保留你缴纳徽章的记录，你在铁炉堡的声望也会因此提高。', `FemaleText_loc5`='你好，$c─我是代表鐵爐堡的表揚官。我的職責是協助已獲得聯盟榮譽徽章的冒險者。$B$B我接受不同數量的獎章，但對你最有利的交易就是馬上交換10個。一旦你貢獻獎章我就會將你的功績寫在我們的紀錄上。所以，你會因你的職責與貢獻獲得鐵爐堡的認同。', `FemaleText_loc7`='Saludos, $c. Soy una oficial encomiado en misión en nombre de Forjaz. Mi deber es ayudar a los aventureros que hayan recibido un sello de mención de honor de la Alianza.$B$BYo acepto sellos en diferentes cantidades, pero lo mejor para ti es que me entregues un lote de diez de una sola vez. Inscribiré tus hazañas en nuestros registros cuando entregues tus sellos. De esta forma, te ganarás el reconocimiento de Forjaz por tu cumplimiento del deber y buen servicio.' WHERE `I