UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, $C|1이여;여;? 저는 썬더 블러프를 위해 일하는 인사 장교입니다. 호드 무공 훈장을 받은 모험가들을 돕는 것이 제 임무입니다.$B$B꼭 몇 개를 모아와야 한다는 법은 없지만 10개를 한꺼번에 교환하시는 게 가장 좋습니다. 제게 훈장을 주시면 당신의 공적을 기록해 두겠습니다. 그러면 썬더 블러프에서 당신의 임무 수행 능력에 대한 인정을 받게 될 것입니다.', `MaleText_loc4`='你好，$C——我是雷霆崖的嘉奖官。我的职责就是帮助那些获得部落荣誉徽章的冒险者们。$B$B我一次可收取不同数量的徽章，但是对你来说，一次缴纳10枚徽章可获得最高收益。我会保留你缴纳徽章的记录，你在雷霆崖的声望也会因此提高。', `MaleText_loc5`='你好，$c─我是代表雷霆崖的表揚官。我的職責是協助已獲得部落榮譽徽章的冒險者。$B$B我接受不同數量的獎章，但對你最有利的交易就是馬上交換10個。一旦你貢獻獎章我就會將你的功績寫在我們的紀錄上。所以，你會因你的職責與貢獻獲得雷霆崖的認同。', `MaleText_loc7`='Saludos, $c. Soy un oficial encomiado en misión en nombre de Cima del Trueno. Mi deber es ayudar a los aventureros que hayan recibido un sello de honor de la Horda.$B$BYo acepto sellos en diferentes cantidades, pero lo mejor para ti es que me entregues un lote de diez de una sola vez. Inscribiré tus hazañas en nuestros registros cuando entregues tus sellos. De esta forma, te ganarás el reconocimiento de Cima del Trueno por tu cumplimiento del deber y buen servicio.', `FemaleText_loc1`='안녕하십니까, $C|1이여;여;? 저는 썬더 블러프를 위해 일하는 인사 장교입니다. 호드 무공 훈장을 받은 모험가들을 돕는 것이 제 임무입니다.$B$B꼭 몇 개를 모아와야 한다는 법은 없지만 10개를 한꺼번에 교환하시는 게 가장 좋습니다. 제게 훈장을 주시면 당신의 공적을 기록해 두겠습니다. 그러면 썬더 블러프에서 당신의 임무 수행 능력에 대한 인정을 받게 될 것입니다.', `FemaleText_loc4`='你好，$C——我是雷霆崖的嘉奖官。我的职责就是帮助那些获得部落荣誉徽章的冒险者们。$B$B我一次可收取不同数量的徽章，但是对你来说，一次缴纳10枚徽章可获得最高收益。我会保留你缴纳徽章的记录，你在雷霆崖的声望也会因此提高。', `FemaleText_loc5`='你好，$c─我是代表雷霆崖的表揚官。我的職責是協助已獲得部落榮譽徽章的冒險者。$B$B我接受不同數量的獎章，但對你最有利的交易就是馬上交換10個。一旦你貢獻獎章我就會將你的功績寫在我們的紀錄上。所以，你會因你的職責與貢獻獲得雷霆崖的認同。', `FemaleText_loc7`='Saludos, $c. Soy una oficial encomiada en misión en nombre de Cima del Trueno. Mi deber es ayudar a los aventureros que hayan recibido un sello de honor de la Horda.$B$BYo acepto sellos en diferentes cantidades, pero lo mejor para ti es que me entregues un lote de diez de una sola vez. Inscribiré tus hazañas en nuestros registros cuando entregues tus sellos. De esta forma, te ganarás el reconocimiento de Cima del Trueno por tu cumplimiento del deber y buen servicio.' WHERE `ID`=11421;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하신가, $C|1이여;여;? 나는 언더시티를 위해 일하는 인사 장교라네. 호드 무공 훈장을 받은 모험가들을 돕는 것이 내 임무지.$B$B꼭 몇 개를 모아와야 한다는 법은 없지만 10개를 한꺼번에 교환하는 게 가장 좋다네. 내게 훈장을 주면 자네의 공적을 기록해 두도록 하지. 그러면 언더시티에서 자네의 임무 수행 능력에 대한 인정을 받게 될 것일세.', `MaleText_loc4`='你好，$C——我是幽暗城的嘉奖官。我的职责就是帮助那些获得部落荣誉徽章的冒险者们。$B$B我一次可收取不同数量的徽章，但是对你来说，一次缴纳10枚徽章可获得最高收益。我会保留你缴纳徽章的记录，你在幽暗城的声望也会因此提高。', `MaleText_loc5`='你好，$c－我是代表幽暗城的表揚官。我的職責是協助已獲得部落榮譽徽章的冒險者。$B$B我接受不同數量的獎章，但對你最有利的交易就是馬上交換10個。一旦你貢獻獎章我就會將你的功績寫在我們的紀錄上。所以，你會因你的職責與貢獻獲得幽暗城的認同。', `MaleText_loc7`='Saludos, $c. Soy un oficial encomiado en misión en nombre de Entrañas. Mi deber es ayudar a los aventureros que hayan recibido un sello de honor de la Horda.$B$BYo acepto sellos en diferentes cantidades, pero lo mejor para ti es que me entregues un lote de diez de una sola vez. Inscribiré tus hazañas en nuestros registros cuando entregues tus sellos. De esta forma, te ganarás el reconocimiento de Entrañas por tu cumplimiento del deber y buen servicio.', `FemaleText_loc1`='안녕하신가, $C|1이여;여;? 나는 언더시티를 위해 일하는 인사 장교라네. 호드 무공 훈장을 받은 모험가들을 돕는 것이 내 임무지.$B$B꼭 몇 개를 모아와야 한다는 법은 없지만 10개를 한꺼번에 교환하는 게 가장 좋다네. 내게 훈장을 주면 자네의 공적을 기록해 두도록 하지. 그러면 언더시티에서 자네의 임무 수행 능력에 대한 인정을 받게 될 것일세.', `FemaleText_loc4`='你好，$C——我是幽暗城的嘉奖官。我的职责就是帮助那些获得部落荣誉徽章的冒险者们。$B$B我一次可收取不同数量的徽章，但是对你来说，一次缴纳10枚徽章可获得最高收益。我会保留你缴纳徽章的记录，你在幽暗城的声望也会因此提高。', `FemaleText_loc5`='你好，$c－我是代表幽暗城的表揚官。我的職責是協助已獲得部落榮譽徽章的冒險者。$B$B我接受不同數量的獎章，但對你最有利的交易就是馬上交換10個。一旦你貢獻獎章我就會將你的功績寫在我們的紀錄上。所以，你會因你的職責與貢獻獲得幽暗城的認同。', `FemaleText_loc7`='Saludos, $c. Soy una oficial encomiada en misión en nombre de Entrañas. Mi deber es ayudar a los aventureros que hayan recibido un sello de honor de la Horda.$B$BYo acepto sellos en diferentes cantidades, pero lo mejor para ti es que me entregues un lote de diez de una sola vez. Inscribiré tus hazañas en nuestros registros cuando entregues tus sellos. De esta forma, te ganarás el reconocimiento de Entrañas por tu cumplimiento del deber y buen servicio.' WHERE `ID`=11422;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 전면 공격을 시작합니다.', `MaleText_loc4`='%s展开了猛烈的攻势。', `MaleText_loc5`='%s發起猛攻。', `MaleText_loc7`='%s realiza un ataque masivo.' WHERE `ID`=11423;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투 소집 명령을 들은 %s|1이;가; 주인을 섬기기 위해 일어납니다.', `MaleText_loc4`='%s听见了战斗的召唤，起身追随主人。', `MaleText_loc5`='%s聽到上戰場的徵召，為服務主人而醒來。', `MaleText_loc7`='¡%s oye la llamada de socorro y se prepara para servir a su maestro!' WHERE `ID`=11424;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실리더스 전역이 %s의 그림자로 뒤덮입니다.', `MaleText_loc4`='%s庞大的身躯使整个希利苏斯笼罩在阴影中。', `MaleText_loc5`='%s將它巨大的陰影籠罩整個希利蘇斯。', `MaleText_loc7`='%s lanza su amenaza sobre todo Silithus.' WHERE `ID`=11425;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하이브아쉬 밑에서 %s|1이;가; 고치를 깨고 나옵니다.', `MaleText_loc4`='%s从亚什虫巢的茧中破壳而出。', `MaleText_loc5`='%s從牠亞什蟲巢底下的繭中破出，獲得自由。', `MaleText_loc7`='%s sale de su capullo bajo Colmen''Ashi.' WHERE `ID`=11426;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='청동용군단의 용사 $n|1이;가; 스카라베 징을 울렸습니다. 고대의 안퀴라즈 관문이 열리고 잊혀진 전쟁의 참상을 드러낼 시간입니다...', `MaleText_loc4`='青铜龙的勇士$n已经敲响甲虫之墙上的铜锣。古老的安其拉之门打开了，那场被遗忘的战争的恐怖气息再一次弥漫了希利苏斯……', `MaleText_loc5`='$n，青銅龍軍團的勇士已敲響甲蟲之鑼。古老的安其拉之門就要開啟，揭開被遺忘之戰的恐懼...', `MaleText_loc7`='$n, $gcampeón:campeona; del Vuelo Bronce, ha hecho sonar el gong del Escarabajo. Las antiguas puertas de Ahn''Qiraj se abren, dejando al descubierto los horrores de una guerra olvidada...', `FemaleText_loc1`='청동용군단의 용사 $n|1이;가; 스카라베 징을 울렸습니다. 고대의 안퀴라즈 관문이 열리고 잊혀진 전쟁의 참상을 드러낼 시간입니다...', `FemaleText_loc4`='青铜龙的勇士$n已经敲响甲虫之墙上的铜锣。古老的安其拉之门打开了，那场被遗忘的战争的恐怖气息再一次弥漫了希利苏斯……', `FemaleText_loc5`='$n，青銅龍軍團的勇士已敲響甲蟲之鑼。古老的安其拉之門就要開啟，揭開被遺忘之戰的恐懼...', `FemaleText_loc7`='$n, $gcampeón:campeona; del Vuelo Bronce, ha hecho sonar el gong del Escarabajo. Las antiguas puertas de Ahn''Qiraj se abren, dejando al descubierto los horrores de una guerra olvidada...' WHERE `ID`=11427;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 해치워라. 단, 주인님을 위해 놈들의 껍질은 남겨놓아라...', `MaleText_loc4`='杀光他们。把他们的壳留给主人享用……', `MaleText_loc5`='把他們全殺了。留下他們的軀殼讓主使者毀滅...', `MaleText_loc7`='Acaben con ellos. Dejen que el maestro consuma sus corazas...' WHERE `ID`=11428;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필멸의 존재여, 쓸데없이 참견한 대가를 치르리라. 주인님께서 거의 깨어나셨다. 완전히 일어나시는 날, 너희 세계는 끝이다.', `MaleText_loc4`='很快你就会知道多管闲事的后果了，凡人……我的主人很快就能恢复力量……当他站起来的时候，就是你的世界毁灭的时候。', `MaleText_loc5`='你馬上就可以知道愛管閒事的代價了，人類...主使者就快要復活...當他崛起的時候，你的世界也將結束。', `MaleText_loc7`='Pronto conocerán el precio de su intromisión, mortales... El maestro casi está completo... y cuando se levante, su mundo verá el fin.' WHERE `ID`=11429;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 모두를 위한 선물입니다! 겨울 할아버지가 나무 아래 선물을 놓아두셨습니다.', `MaleText_loc4`='每个人都有礼物！冬天爷爷的礼物就放在树下！', `MaleText_loc5`='每個人都有禮物!冬天爺爺的禮物就放在樹下!', `MaleText_loc7`='¡Regalos para todos! El Padre Invierno dejó regalos para todos bajo el árbol.' WHERE `ID`=11430;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이겼다고 생각하나? 이렇게 쉽게? 행군은 이제 막 시작됐을 뿐! 크툰의 군대가 이 세계를 집어삼키리라.', `MaleText_loc4`='你认为你赢了吗？这么简单就赢了吗？军团的远征才刚刚开始。克苏恩的大军会将这个世界夷为平地的。', `MaleText_loc5`='你以為你已經贏了嗎?這麼容易?軍隊才正要開始行軍。克蘇恩的軍隊將夷平這個世界。', `MaleText_loc7`='¿Creéis que habéis ganado con tanta facilidad? La legión acaba de empezar su marcha. Los ejércitos de C''Thun arrasarán este mundo.' WHERE `ID`=11431;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거대한 공명의 퀴라지 수정들이 칼림도어의 동쪽 지역을 어지럽히고 있습니다. 방금 파괴된 땅을 흑요석으로 만들어진 거대한 생명체가 짓밟고 있습니다.', `MaleText_loc4`='巨大的其拉共鸣水晶穿破了卡利姆多的地壳，由黑曜石构成的巨大生物来到了这片刚刚破碎的大陆。', `MaleText_loc5`='大型其拉共鳴水晶衝破了卡林多大陸的地表。由黑曜石做成的巨型生物衝出損壞的大地。', `MaleText_loc7`='Enormes obeliscos de cristal resonador surgen de la corteza terrestre de Kalimdor. Criaturas colosales hechas de piedra de obsidiana se abren paso a través de la quebrada tierra.', `FemaleText_loc1`='거대한 공명의 퀴라지 수정들이 칼림도어의 동쪽 지역을 어지럽히고 있습니다. 방금 파괴된 땅을 흑요석으로 만들어진 거대한 생명체가 짓밟고 있습니다.', `FemaleText_loc4`='巨大的其拉共鸣水晶穿破了卡利姆多的地壳，由黑曜石构成的巨大生物来到了这片刚刚破碎的大陆。', `FemaleText_loc5`='大型其拉共鳴水晶衝破了卡林多大陸的地表。由黑曜石做成的巨型生物衝出損壞的大地。', `FemaleText_loc7`='Enormes obeliscos de cristal resonador surgen de la corteza terrestre de Kalimdor. Criaturas colosales hechas de piedra de obsidiana se abren paso a través de la quebrada tierra.' WHERE `ID`=11432;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마지막 숨을 쉬어라!', `MaleText_loc4`='纳命来！', `MaleText_loc5`='呼吸最後一口空氣吧!', `MaleText_loc7`='¡Respira por última vez!' WHERE `ID`=11433;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용사들이여, 전투를 멈추지 마라!', `MaleText_loc4`='战士们，军官们，继续战斗！', `MaleText_loc5`='戰士、上尉們，繼續奮戰!', `MaleText_loc7`='¡Guerreros, Capitanes, sigan luchando!' WHERE `ID`=11434;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='건방진... 내 친히 너희를 처치해주마!', `MaleText_loc4`='无礼的蠢货！我会亲自要了你们的命！', `MaleText_loc5`='厚顏無恥的笨蛋!我要親手殺了你!', `MaleText_loc7`='¡Loco imprudente! ¡Acabaré contigo yo mismo!' WHERE `ID`=11435;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판드랄! 때가 왔다! 에메랄드의 꿈속에 숨어서 기도나 올려라!', `MaleText_loc4`='范达尔！你的死期到了！藏到翡翠梦境里去吧，祈祷我们永远都找不到你！', `MaleText_loc5`='范達爾!你的時候到了!躲進翡翠夢境祈禱我們永遠不會找到你吧!', `MaleText_loc7`='¡Fandral! ¡Ha llegado tu hora! ¡Ve y escóndete en el Sueño Esmeralda y reza para que nunca te encontremos!' WHERE `ID`=11436;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스태그헬름은 흐느끼며 목숨을 구걸하리라. 그 아들놈이 그랬던 것처럼! 천 년의 한을 풀리라! 오늘에서야!', `MaleText_loc4`='鹿盔将会呜咽着哀求我饶他一命，就像他那懦弱的儿子一样！一千年来的屈辱会在今天洗清！', `MaleText_loc5`='鹿盔將為了活命而啜泣、乞求，就像他的兒子一樣!一千年的不公將在今日結束!', `MaleText_loc7`='¡Corzocelada llorará y rogará por su vida, igual que lo hizo su débil hijo! ¡Hoy acabará un milenio lleno de injusticia!' WHERE `ID`=11437;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적에게 공포와 죽음의 향연을!', `MaleText_loc4`='让敌人胆战心惊吧！让他们在恐惧中死去！', `MaleText_loc5`='恐懼是給敵人的!恐懼與死亡!', `MaleText_loc7`='¡El miedo es para el enemigo! ¡Miedo y muerte!' WHERE `ID`=11438;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더는 돌벽과 성문 뒤에서 기다릴 수 없다! 복수의 기회를 놓칠 수 없다. 우리가 분노를 터뜨리는 날 용족은 두려움에 떨리라.', `MaleText_loc4`='我们不用再呆在这座石墙里面了！我们很快就能报仇了！在我们的怒火面前，就连那些龙也会战栗！', `MaleText_loc5`='我們不需在被禁堵的門與石牆後等待了!我們的復仇將不再被否認!巨龍將在我們的憤怒之前顫抖!', `MaleText_loc7`='¡No volveremos a esperar detrás de rejas y muros de piedra! ¡Nunca más podrán negarnos nuestra venganza! ¡Hasta los dragones temblarán frente a nuestra ira!' WHERE `ID`=11439;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='응보의 날이 다가왔다! 암흑이 적들의 마음을 지배하리라!', `MaleText_loc4`='我们复仇的时刻到了！让敌人的内心被黑暗吞噬吧！', `MaleText_loc5`='我們懲罰的時刻就在眼前!讓黑暗支配敵人的內心吧!', `MaleText_loc7`='¡La hora de las recompensas está próxima! ¡Que la oscuridad reine en el corazón de nuestros enemigos!' WHERE `ID`=11440;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 당신의 공포를 알아챕니다.', `MaleText_loc4`='%s察觉到了你的恐惧。', `MaleText_loc5`='%s因神態失常而坐立不安。', `MaleText_loc7`='%s siente tu miedo.' WHERE `ID`=11441;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성스러운 땅을 더럽힌 죗값을 받게 되리라. 고대의 법률은 거스를 수 없다! 침입자들을 처단하라!', `MaleText_loc4`='你们玷污了这片神圣的土地，会因此受到惩罚的！上古之神的律法不容藐视！入侵者要付出生命的代价！', `MaleText_loc5`='你將因玷污這些神聖之地而受審判!古老的規矩是不容許被挑戰的!入侵者將徹底被擊潰!', `MaleText_loc7`='¡Serán juzgados por haber profanado este suelo sagrado!' WHERE `ID`=11442;
