UPDATE `locales_broadcast_text` SET `MaleText_loc1`='썬더 블러프의 최정상에서 불꽃 놀이가 6시에 펼쳐집니다!', `MaleText_loc4`='每天下午6点钟，雷霆崖都会有华丽的焰火表演！', `MaleText_loc5`='每天下午6點鐘，雷霆崖都會有華麗的煙火表演!', `MaleText_loc7`='¡A las 6PM echarán fuegos artificiales desde el risco más alto!', `FemaleText_loc1`='썬더 블러프의 최정상에서 불꽃 놀이가 6시에 펼쳐집니다!', `FemaleText_loc4`='每天下午6点钟，雷霆崖都会有华丽的焰火表演！', `FemaleText_loc5`='每天下午6點鐘，雷霆崖都會有華麗的煙火表演!', `FemaleText_loc7`='¡A las 6PM echarán fuegos artificiales desde el risco más alto!' WHERE `ID`=11456;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파티 맥주통에 독한 맥주가 가득합니다. 술과 친구 그리고 축제 분위기가 가득하군요!', `MaleText_loc4`='美酒良辰！尽情地喝吧，我的朋友，尽情地狂欢吧！', `MaleText_loc5`='美酒良辰!盡情地喝吧，我的朋友，盡情地狂歡吧!', `MaleText_loc7`='¡Los barriles están llenos de un brebaje muy fuerte! ¡Bebe, $gamigo:amiga; y diviértete!', `FemaleText_loc1`='파티 맥주통에 독한 맥주가 가득합니다. 술과 친구 그리고 축제 분위기가 가득하군요!', `FemaleText_loc4`='美酒良辰！尽情地喝吧，我的朋友，尽情地狂欢吧！', `FemaleText_loc5`='美酒良辰!盡情地喝吧，我的朋友，盡情地狂歡吧!', `FemaleText_loc7`='¡Los barriles están llenos de un brebaje muy fuerte! ¡Bebe, $gamigo:amiga; y diviértete!' WHERE `ID`=11457;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불꽃놀이 후엔, 탁자에 술잔이 가득할 거라 들었습니다. 축배를 들 수 있는 멋진 술잔이지요!', `MaleText_loc4`='听说在焰火表演之后，桌子上就会摆满高脚杯，然后我们就可以喝酒庆祝了！', `MaleText_loc5`='聽說在煙火表演之後，桌子上就會擺滿高腳杯，然後我們就可以喝酒慶祝了!', `MaleText_loc7`='He oído que tras el espectáculo de fuegos artificiales, pondrán copas en las mesas. ¡Y podremos hacer unos buenos brindis!', `FemaleText_loc1`='불꽃놀이 후엔, 탁자에 술잔이 가득할 거라 들었습니다. 축배를 들 수 있는 멋진 술잔이지요!', `FemaleText_loc4`='听说在焰火表演之后，桌子上就会摆满高脚杯，然后我们就可以喝酒庆祝了！', `FemaleText_loc5`='聽說在煙火表演之後，桌子上就會擺滿高腳杯，然後我們就可以喝酒慶祝了!', `FemaleText_loc7`='He oído que tras el espectáculo de fuegos artificiales, pondrán copas en las mesas. ¡Y podremos hacer unos buenos brindis!' WHERE `ID`=11458;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요, $c씨! 축제에 오신 것을 환영합니다!', `MaleText_loc4`='嗨，$c！欢迎你！', `MaleText_loc5`='嗨，$c!歡迎你!', `MaleText_loc7`='¡Ave, $c! ¡$GBienvenido:Bienvenida; a la fiesta!', `FemaleText_loc1`='안녕하세요, $c씨! 축제에 오신 것을 환영합니다!', `FemaleText_loc4`='嗨，$c！欢迎你！', `FemaleText_loc5`='嗨，$c!歡迎你!', `FemaleText_loc7`='¡Ave, $c! ¡$GBienvenido:Bienvenida; a la fiesta!' WHERE `ID`=11459;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밤이 새도록 불꽃놀이를 구경할 수 있습니다. 오후 6시부터 새벽까지 무법항의 하늘이 빨갛게 물들 거라고요!', `MaleText_loc4`='晚上会有焰火表演，从下午6点直到第二天早上，藏宝海湾的天空将会绽开无数绚丽的花朵！', `MaleText_loc5`='晚上會有煙火表演，從下午6點直到第二天早上，藏寶海灣的天空將會綻開無數絢麗的花朵!', `MaleText_loc7`='Habrá fuegos artificiales durante toda la noche. Desde las 6PM hasta el amanecer, ¡el cielo resplandecerá sobre Bahía del Botín!', `FemaleText_loc1`='밤이 새도록 불꽃놀이를 구경할 수 있습니다. 오후 6시부터 새벽까지 무법항의 하늘이 빨갛게 물들 거라고요!', `FemaleText_loc4`='晚上会有焰火表演，从下午6点直到第二天早上，藏宝海湾的天空将会绽开无数绚丽的花朵！', `FemaleText_loc5`='晚上會有煙火表演，從下午6點直到第二天早上，藏寶海灣的天空將會綻開無數絢麗的花朵!', `FemaleText_loc7`='Habrá fuegos artificiales durante toda la noche. Desde las 6PM hasta el amanecer, ¡el cielo resplandecerá sobre Bahía del Botín!' WHERE `ID`=11460;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와우! 이 술통에는 정말 굉장한 것이 들어있군! 어느새 발가락이 신발에서 빠져나와 공중을 걷고 있는 느낌이야!', `MaleText_loc4`='哇！这酒真够劲！我快要撑不住了！', `MaleText_loc5`='哇!這酒真夠勁!我快要撐不住了!', `MaleText_loc7`='¡Vaya! ¡Estos barriles tienen cosa fina! ¡Menudo subidón!', `FemaleText_loc1`='와우! 이 술통에는 정말 굉장한 것이 들어있군! 어느새 발가락이 신발에서 빠져나와 공중을 걷고 있는 느낌이야!', `FemaleText_loc4`='哇！这酒真够劲！我快要撑不住了！', `FemaleText_loc5`='哇!這酒真夠勁!我快要撐不住了!', `FemaleText_loc7`='¡Vaya! ¡Estos barriles tienen cosa fina! ¡Menudo subidón!' WHERE `ID`=11461;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불꽃놀이가 끝나도 돌아가지 마세요. 술잔을 들어올려서 용감한 친구들과 함께 건배를 하는 거죠.', `MaleText_loc4`='焰火表演之后不要走开！拿起高脚杯和你的好朋友一起庆祝吧！', `MaleText_loc5`='煙火表演之後不要走開!拿起高腳杯和你的好朋友一起慶祝吧!', `MaleText_loc7`='Quédate por aquí cuando acabe el espectáculo de fuegos artificiales. ¡Coge una copa y brinda por tus viejos amigos!', `FemaleText_loc1`='불꽃놀이가 끝나도 돌아가지 마세요. 술잔을 들어올려서 용감한 친구들과 함께 건배를 하는 거죠.', `FemaleText_loc4`='焰火表演之后不要走开！拿起高脚杯和你的好朋友一起庆祝吧！', `FemaleText_loc5`='煙火表演之後不要走開!拿起高腳杯和你的好朋友一起慶祝吧!', `FemaleText_loc7`='Quédate por aquí cuando acabe el espectáculo de fuegos artificiales. ¡Coge una copa y brinda por tus viejos amigos!' WHERE `ID`=11462;
