UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아! 우미, 기계설인 만드는 법을 다시 한 번 가르쳐 줄래요?', `MaleText_loc4`='乌米！告诉我怎么制作机械雪人吧！我很想念它。', `MaleText_loc5`='喔，烏米，請再教我一次如何製作寧靜的雪人。我好想念它。', `MaleText_loc7`='Venga Umi, enséñame otra vez a fabricar un yeti sereno. Lo echo de menos.', `FemaleText_loc1`='아! 우미, 기계설인 만드는 법을 다시 한 번 가르쳐 줄래요?', `FemaleText_loc4`='乌米！告诉我怎么制作机械雪人吧！我很想念它。', `FemaleText_loc5`='喔，烏米，請再教我一次如何製作寧靜的雪人。我好想念它。', `FemaleText_loc7`='Venga Umi, enséñame otra vez a fabricar un yeti sereno. Lo echo de menos.' WHERE `ID`=11480;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n, 괜찮아요. 당신 방식이 잘못되었다는 것을 깨달았을 테고 공학도 모임에도 다시 들었잖아요?!$B$B꼬마 설인과 좋은 시간 보내라고요!!!', `FemaleText_loc4`='啊，好吧，$n。看来你已经明白了自己在工程学方面的欠缺。$B$B祝你和你的机械雪人玩得愉快！', `FemaleText_loc5`='嗯，好吧，$n。我看的出來你了解所犯的錯誤並重新加入工程學的行列。$B$B祝你使用雪人愉快!!!', `FemaleText_loc7`='Vale, de acuerdo $n. Te puedo decir que te has dado cuenta del error de tus actos y has vuelto al redil de ingeniería.$B$B¡¡Diviértete con tu yeti!!' WHERE `ID`=11481;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='왜 태엽장치가 필요할 때는 눈 씻고 찾아봐도 없는 거죠?', `FemaleText_loc4`='为什么当你要用到发条式同步协调陀螺仪的时候它们总是无影无踪呢？', `FemaleText_loc5`='為什麼當你需要發條式同步協調陀螺儀時永遠都找不到它呢?', `FemaleText_loc7`='¿Por qué nunca hay ningún girocronátomo cerca cuando lo necesitas?' WHERE `ID`=11482;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마지막에는 내가 웃게 될 거야... 두고 보라고! 아, 안녕하세요. 거기에 서 계신 걸 못 봤네요.', `FemaleText_loc4`='我是最后的大赢家……他们会看到的！啊，你好啊，$c，我刚才没看到你。', `FemaleText_loc5`='我會贏得最後的勝利...等著看吧他們!喔，嗨，$c，我沒看到你在那。', `FemaleText_loc7`='Yo me reiré la última... ¡ya verán! Ah, hola $c. No te había visto.' WHERE `ID`=11483;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='발명의 2퍼센트는 병 속에 든 영감에 의해, 4퍼센트는 태양의 노출에 의해, 6퍼센트는 마른하늘에 날벼락을 맞을 확률로 그리고 93퍼센트는 럼플스니커에 의해 이루어진답니다.$B$B잠깐, 다 합치면 100퍼센트가 맞나요? 여기 어딘가에 적어 둔 게 있을 텐데...', `FemaleText_loc4`='发明创造，我亲爱的$c，就是百分之二的灵感，百分之四的日光浴，百分之六的雷阵雨之后的清新，以及百分之九十三的鬼点子。$B$B等等，这加起来好像不是百分之一百？我的笔记本去哪里了……', `FemaleText_loc5`='發明，我親愛的$c，是百分之二瓶裝的靈感，百分之四太陽的曝曬，百分之六被正午清除的大雷雨，和百分之九十三的烏米。$B$B等等，這樣加起來一百了嗎?我把我的筆記放在這附近了。', `FemaleText_loc7`='La inventiva, mi $gquerido:querida; $c, se compone de un dos por ciento de inspiración embotellada, cuatro por ciento de exposición al sol, seis por ciento de probabilidad de que la tormenta pase antes del mediodía y noventa y tres por ciento de Risitas.$B$BEspera, ¿eso hace el cien por cien? Tengo mis notas por aquí, en alguna parte...' WHERE `ID`=11484;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='퀴라지가 그 짐승들에게 뭘 먹이는지 알아내야 합니다! 그 짐승들의 크기를 보십시오!', `MaleText_loc4`='我们得看看其拉虫人到底给这些怪物吃的是什么！看看它们的个头！', `MaleText_loc5`='我們要弄清楚其拉到底都餵那些怪物吃什麼!你看看他們有多巨大!', `MaleText_loc7`='¡Tenemos que averiguar qué les dan de comer los qiraji a esos monstruos! ¡Mira qué tamaño tienen!' WHERE `ID`=11485;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거대괴수를 연구하고 이해하게 된다면 퀴라지와 싸움에서 유리한 위치를 차지할 수 있습니다.', `MaleText_loc4`='研究并了解这些巨甲虫，可以让我们更有把握打败其拉虫人！', `MaleText_loc5`='研究並瞭解這些巨像，可以讓我們更有把握打敗其拉蟲人!', `MaleText_loc7`='Estudiar y entender a los Colosos nos dará una valiosa ventaja sobre los qiraji.' WHERE `ID`=11486;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='거대괴수의 힘에 감춰진 비밀을 밝힐 수만 있다면 과학에 일대 혁신이 일어날 거예요!', `FemaleText_loc4`='巨甲虫的能量所隐藏的秘密将引发科学界的一场大变革！', `FemaleText_loc5`='巨型生物力量的秘密可能會激起科學界許多的創新!', `FemaleText_loc7`='¡El secreto que se esconde tras el poder de los Colosos podría significar una revolución para la ciencia!' WHERE `ID`=11487;
