UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장로 골드웰은 던 모로의 카라노스 마을에서 지내고 있네.', `MaleText_loc4`='金井长者在丹莫罗的卡拉诺斯歇脚。', `MaleText_loc5`='金善長者都在丹莫洛的卡拉諾斯消磨時間。', `MaleText_loc7`='El ancestro Pozo de Oro se encuentra en la aldea de Kharanos en Dun Morogh.', `FemaleText_loc1`='장로 골드웰은 던 모로의 카라노스 마을에서 지내고 있네.', `FemaleText_loc4`='金井长者在丹莫罗的卡拉诺斯歇脚。', `FemaleText_loc5`='金善長者都在丹莫洛的卡拉諾斯消磨時間。', `FemaleText_loc7`='El ancestro Pozo de Oro se encuentra en la aldea de Kharanos en Dun Morogh.' WHERE `ID`=11510;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사라져라, 사악한 존재들이여! 이 세계에 너희 족속이 발붙일 곳은 없다.', `FemaleText_loc4`='死吧！你们这些邪恶的生物必将被全部消灭！', `FemaleText_loc5`='滾吧，邪惡的生物!你們這種東西根本不該存在這世界上。', `FemaleText_loc7`='¡Marchénse, criaturas apestosas! Su especie no tiene cabida en este mundo.' WHERE `ID`=11511;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장로 브론즈비어드는 어디에 있습니까?', `MaleText_loc4`='铜须长者在哪里？', `MaleText_loc5`='銅鬚長者在哪裡?', `MaleText_loc7`='¿Dónde está el ancestro Barbabronce?', `FemaleText_loc1`='장로 브론즈비어드는 어디에 있습니까?', `FemaleText_loc4`='铜须长者在哪里？', `FemaleText_loc5`='銅鬚長者在哪裡?', `FemaleText_loc7`='¿Dónde está el ancestro Barbabronce?' WHERE `ID`=11512;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아제로스의 백성들이여, 용기를 내라! 퀴라지 침략자들을 몰아내자!', `MaleText_loc4`='勇气与你们同在，艾泽拉斯的勇士们！和其拉虫人决一死战！', `MaleText_loc5`='展現你的勇氣，艾澤拉斯的勇士們!和其拉蟲人決一死戰!', `MaleText_loc7`='¡Demostren su valor, mujeres y hombres de Azeroth! ¡Consegan que los invasores qiraji retrocedan!' WHERE `ID`=11513;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장로 브론즈비어드는 선조 때부터 이어진 브론즈비어드 가문의 고향, 아이언포지에서 찾을 수 있네.', `MaleText_loc4`='铜须长者在他们家族的老家铁炉堡里。', `MaleText_loc5`='你可以在銅鬚的故鄉，鐵爐堡，找到銅鬚長者。', `MaleText_loc7`='Puedes encontrar al ancestro Barbabronce en Forjaz, hogar ancestral de los Barbabronce.', `FemaleText_loc1`='장로 브론즈비어드는 선조 때부터 이어진 브론즈비어드 가문의 고향, 아이언포지에서 찾을 수 있네.', `FemaleText_loc4`='铜须长者在他们家族的老家铁炉堡里。', `FemaleText_loc5`='你可以在銅鬚的故鄉，鐵爐堡，找到銅鬚長者。', `FemaleText_loc7`='Puedes encontrar al ancestro Barbabronce en Forjaz, hogar ancestral de los Barbabronce.' WHERE `ID`=11514;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='약한 모습 보이지 마라! 저 사악한 벌레들을 해치워라!', `FemaleText_loc4`='不要示弱！把这些邪恶的家伙全都干掉！', `FemaleText_loc5`='不要退縮!消滅這些邪惡的生物!', `FemaleText_loc7`='¡No mostréis debilidad! ¡Aplastad a estas criaturas apestosas!' WHERE `ID`=11515;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장로 실버베인은 어디에 있습니까?', `MaleText_loc4`='银脉长者在哪里？', `MaleText_loc5`='銀脈長者在哪裡?', `MaleText_loc7`='¿Dónde está el ancestro Venaplata?', `FemaleText_loc1`='장로 실버베인은 어디에 있습니까?', `FemaleText_loc4`='银脉长者在哪里？', `FemaleText_loc5`='銀脈長者在哪裡?', `FemaleText_loc7`='¿Dónde está el ancestro Venaplata?' WHERE `ID`=11516;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$c|1이여;여;, 엘룬이 함께하시기를...', `FemaleText_loc4`='艾露恩与你同在，$c。', `FemaleText_loc5`='伊露恩與你同在，$c。', `FemaleText_loc7`='Que Elune esté contigo, $c.' WHERE `ID`=11517;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대여사제님께서는 다르나서스를 떠나실 수 없습니다. 그리고 판드랄님께서는 불쾌한 심기를 숨기지 못하고 계십니다.', `FemaleText_loc4`='高阶女祭司现在不能离开达纳苏斯。范达尔的情绪非常奇怪。', `FemaleText_loc5`='高階牧師不能離開達納蘇斯。范達爾心情很惡劣。', `FemaleText_loc7`='La suma sacerdotisa no podría abandonar Darnassus. Fandral está de muy mal humor.' WHERE `ID`=11518;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='티란데 님께서 손수 우리를 위해 기도를 올리고 계시며, 어머니 달께서 우리 모두를 축복하고 계십니다.', `FemaleText_loc4`='泰兰德送来了她的问候。月神与我们同在。', `FemaleText_loc5`='泰蘭妲傳來她的禱告。月亮之母祝福我們。', `FemaleText_loc7`='Tyrande envía sus plegarias. La Madre Luna nos bendice a todos.' WHERE `ID`=11519;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얘기는 이것으로 끝낸다. 칼림도어 연합군은 내가 지휘한다. 병사들, 이 점을 명심하고 잘 따라주기 바란다. 이미 엄청난 살육이 벌어졌다. 최소한 우리 진영에서는 이런 일이 절대 없도록 해야 한다.', `MaleText_loc4`='我是卡利姆多联军的统帅。让你的士兵明白这一点，并接受这个事实。杀戮已经非常沉重了，在这个时候，我们两个阵营之间最好不要再出现什么事端。', `MaleText_loc5`='都完成了。我率領卡林多聯軍。確定你的士兵們了解並接受這個事實。血已經流的夠多了。我不想再失去陣營裡的任何人。', `MaleText_loc7`='Está así establecido. Yo dirijo las fuerzas de Kalimdor. Asegúrate de que tus Soldados lo entienden y lo aceptan como un hecho. Ya hay mucho derramamiento de sangre. Hagamos que eso no ocurra entre nuestras propias facciones.' WHERE `ID`=11520;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신병들이여, 곧 호드의 군대가 도착할 것이다. 우리는 행군한다. 우리 앞을 가로막는 모든 것을 쳐부수고 저 저주받은 성문까지 전진한다. 놈들에게 칼림도어 연합군의 힘을 가르쳐 주자!', `MaleText_loc4`='很快，年轻的勇士们。很快部落的军团就会抵达这里。我们将全面推进，开往那座被诅咒的大门，消灭一切敌人。让它们感受卡利姆多联军的力量！', `MaleText_loc5`='很快，年輕人。很快部落的軍隊就會到達。我們齊步前進。前進到那個受詛咒的大門並用盡全力粉碎一切。讓他們感受卡林多的力量!', `MaleText_loc7`='Pronto, pequeñajos... muy pronto llegarán los ejércitos de la Horda. ¡Adelante! Diríganse hacia las puertas malditas y aplasten todo lo que se interponga en su camino. ¡Que sientan el poder de Kalimdor!' WHERE `ID`=11521;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='말재주는 정말 뛰어나군요, 대군주 사울팽', `FemaleText_loc4`='谢谢你，萨鲁法尔大王。', `FemaleText_loc5`='聽您差遣，薩魯法爾霸王。', `FemaleText_loc7`='Hay una posibilidad a través del diálogo, señor supremo Colmillosauro.' WHERE `ID`=11522;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 경고하는 점에 대해서 우리 걱정은 하지 않아도 됩니다. 우리 군대는 명령 체계의 중요성을 잘 알고 있습니다. 우리는 단결하여 싸울 것입니다. 당신들도 이 사실을 기억했으면 좋겠군요...', `FemaleText_loc4`='至于你的提醒……不要担心。我们的部队都已经明确了指挥关系。我们会并肩作战。希望你自己的部队也记得这一点……', `FemaleText_loc5`='至於你的警告 - 別擔心。我們的軍隊都很注意連續命令。我們同心協力。希望你的軍隊能記得這點...', `FemaleText_loc7`='En cuanto a tu advertencia... no te preocupes. Nuestras tropas son conscientes de la cadena de mando. Luchamos juntos. Esperemos que tus propias tropas lo recuerden...' WHERE `ID`=11523;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장로 실버베인은 모단 호수의 텔사마 근처에서 찾을 수 있네.', `MaleText_loc4`='银脉长者就在洛克莫丹的塞尔萨玛附近。', `MaleText_loc5`='你可以在洛克莫丹的塞爾薩瑪附近找到銀脈長者。', `MaleText_loc7`='El ancestro Venaplata se encuentra cerca de Thelsamar en Loch Modan.', `FemaleText_loc1`='장로 실버베인은 모단 호수의 텔사마 근처에서 찾을 수 있네.', `FemaleText_loc4`='银脉长者就在洛克莫丹的塞尔萨玛附近。', `FemaleText_loc5`='你可以在洛克莫丹的塞爾薩瑪附近找到銀脈長者。', `FemaleText_loc7`='El ancestro Venaplata se encuentra cerca de Thelsamar en Loch Modan.' WHERE `ID`=11524;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='병사들이 쓰러지는 것을 본 %s|1이;가; 극도로 흥분합니다.', `MaleText_loc4`='%s看到他的士兵倒下，变得非常愤怒！', `MaleText_loc5`='%s一看到他倒下的部隊便陷入了瘋狂狀態。', `MaleText_loc7`='%s monta en cólera al ver a sus tropas vencidas.' WHERE `ID`=11525;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 빚은 꼭 갚아 주마...', `MaleText_loc4`='你会付出代价的……', `MaleText_loc5`='你會為此付出代價...', `MaleText_loc7`='Pagaréis por ello...' WHERE `ID`=11526;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼림도어 연합군 만세!', `MaleText_loc4`='为了卡利姆多联军！', `MaleText_loc5`='為了卡林多的力量!', `MaleText_loc7`='¡POR EL PODER DE KALIMDOR!' WHERE `ID`=11527;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='둠해머시여, 저를 인도하소서!', `MaleText_loc4`='毁灭之锤，指引我的双手！', `MaleText_loc5`='末日錘指引著我!', `MaleText_loc7`='¡MARTILLO MALDITO, GUÍA MI MANO!' WHERE `ID`=11528;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너를 처단할 것이다...', `MaleText_loc4`='我要毁灭你……', `MaleText_loc5`='我會殺了你...', `MaleText_loc7`='Te destruiré...' WHERE `ID`=11529;
