UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장로 프라임스톤은 실리더스의 수정 골짜기에서 몇 년째 지내고 있네.', `MaleText_loc4`='棱石长者在希利苏斯的水晶谷生活了许多年。', `MaleText_loc5`='基石長者在希利蘇斯的水晶谷度過了許多年。', `MaleText_loc7`='El ancestro Primapiedra lleva muchos años en La Vega de Cristal en Silithus.', `FemaleText_loc1`='장로 프라임스톤은 실리더스의 수정 골짜기에서 몇 년째 지내고 있네.', `FemaleText_loc4`='棱石长者在希利苏斯的水晶谷生活了许多年。', `FemaleText_loc5`='基石長者在希利蘇斯的水晶谷度過了許多年。', `FemaleText_loc7`='El ancestro Primapiedra lleva muchos años en La Vega de Cristal en Silithus.' WHERE `ID`=11609;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선조를 공경하는 것은 그대의 문화와 동족을 명예롭게 하는 일입니다. 선조의 주화는 이러한 공경심을 지닌 이들을 구분할 수 있는 중요한 역할을 합니다.$B$B이번 달의 축제 동안 여러 선조의 명예를 드높일 기회를 얻게 될 것입니다. 그러면 선조의 주화를 얻을 수 있지요. 제게 선조의 주화를 가져오시면 독특한 물건들로 그대의 성실함에 보답하겠습니다.', `MaleText_loc4`='尊重你的长辈同样也是尊重你的文化与人民，$c。而先祖硬币则是对遵循这样一条古老礼仪之道的人的赞许。$B$B在春节期间，你可以拜访许多长者，对他们表达你的尊敬。如果你这样做了，你将会得到先祖硬币。将这些硬币带回来，我会因你的勤奋而允许你从一些特殊的物品中选择一个作为奖励。', `MaleText_loc5`='對長者們表示敬意就是對你們文化和人民表示敬意，$c。因此，祖先的錢幣就是分辨出誰選擇踏上這條可敬之路的最有力方法。$B$B在這次的新年慶典中，你將有機會向許多長者表示敬意，但你需要祖先的錢幣來這樣做。帶給我這些錢幣，我就會讓你選擇一個獨特的物品作為獎勵。', `MaleText_loc7`='Honrar a tus ancestros es honrar a tu cultura y a tu pueblo, $c. Por ello, las monedas de linaje son un medio tangible de reconocer a aquellos que eligen seguir el venerable camino del respeto.$B$BDurante la celebración del Festival Lunar, tendrás la oportunidad de honrar a muchos Ancestros. Cuando lo hagas, obtendrás las monedas de linaje. Tráeme las monedas y recompensaré tu diligencia con una selección de objetos únicos.' WHERE `ID`=11610;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='퀴라지 전투 부대를 발견했습니다!', `MaleText_loc4`='其拉军队出现了！', `MaleText_loc5`='發現其拉敵軍!', `MaleText_loc7`='¡Destacamento de guerra qiraji a la vista!', `FemaleText_loc1`='퀴라지 전투 부대를 발견했습니다!', `FemaleText_loc4`='其拉军队出现了！', `FemaleText_loc5`='發現其拉敵軍!', `FemaleText_loc7`='¡Destacamento de guerra qiraji a la vista!' WHERE `ID`=11611;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='남쪽에서 모래폭풍이 다가오고 있으니 주의하... 앗, 모래폭풍이 아닙니다! 퀴라지 군대가 옵니다!', `MaleText_loc4`='南面有沙漠风暴袭来，赶快找地方躲……那不是沙漠风暴！其拉虫人！是其拉虫人的军队！', `MaleText_loc5`='南面有沙塵風暴襲來，趕快找地方躲...那不是沙塵風暴!其拉蟲人!是其拉蟲人的軍隊!', `MaleText_loc7`='Una tormenta de arena se aproxima por el sur, a cub... ¡Eso no es una tormenta de arena! ¡ES EL EJÉRCITO QIRAJI!', `FemaleText_loc1`='남쪽에서 모래폭풍이 다가오고 있으니 주의하... 앗, 모래폭풍이 아닙니다! 퀴라지 군대가 옵니다!', `FemaleText_loc4`='南面有沙漠风暴袭来，赶快找地方躲……那不是沙漠风暴！其拉虫人！是其拉虫人的军队！', `FemaleText_loc5`='南面有沙塵風暴襲來，趕快找地方躲...那不是沙塵風暴!其拉蟲人!是其拉蟲人的軍隊!', `FemaleText_loc7`='Una tormenta de arena se aproxima por el sur, a cub... ¡Eso no es una tormenta de arena! ¡ES EL EJÉRCITO QIRAJI!' WHERE `ID`=11612;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='남쪽에서 침략자들이 접근하고 있습니다!', `MaleText_loc4`='南面有敌军袭来！', `MaleText_loc5`='入侵者從南方逼近!', `MaleText_loc7`='¡Se aproximan invasores por el sur!', `FemaleText_loc1`='남쪽에서 침략자들이 접근하고 있습니다!', `FemaleText_loc4`='南面有敌军袭来！', `FemaleText_loc5`='入侵者從南方逼近!', `FemaleText_loc7`='¡Se aproximan invasores por el sur!' WHERE `ID`=11613;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 해치워라!', `MaleText_loc4`='把他们全都干掉！', `MaleText_loc5`='消滅他們!', `MaleText_loc7`='¡Machacadlos a todos!' WHERE `ID`=11614;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼림도어 연합군이 놈들의 진군을 저지할 것이다!', `MaleText_loc4`='卡利姆多联军必须马上停止推进！', `MaleText_loc5`='卡林多聯軍會終止他們前進!', `MaleText_loc7`='¡El poder de Kalimdor detendrá su avance!' WHERE `ID`=11615;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼림도어의 전사들이여, 기지를 사수하라!', `MaleText_loc4`='卡利姆多的士兵们，防守基地！', `MaleText_loc5`='卡林多的士兵們，防守基地!', `MaleText_loc7`='¡Soldados de Kalimdor, defended la base!', `FemaleText_loc1`='칼림도어의 전사들이여, 기지를 사수하라!', `FemaleText_loc4`='卡利姆ě的士兵们，防守基地！', `FemaleText_loc5`='卡林多的士兵們，防守基地!', `FemaleText_loc7`='¡Soldados de Kalimdor, defended la base!' WHERE `ID`=11616;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달의 축제의 새 초대장을 얻고 싶습니다.', `MaleText_loc4`='我想要获得一份新的春节邀请函。', `MaleText_loc5`='我想要一張新的新年慶典邀請卡。', `MaleText_loc7`='Me gustaría obtener una nueva invitación para el Festival Lunar.', `FemaleText_loc1`='달의 축제의 새 초대장을 얻고 싶습니다.', `FemaleText_loc4`='我想要获得一份新的春节邀请函。', `FemaleText_loc5`='我想要一張新的新年慶典邀請卡。', `FemaleText_loc7`='Me gustaría obtener una nueva invitación para el Festival Lunar.' WHERE `ID`=11617;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, $n. 우리는 달의 축제의 정신을 널리 전파하기 위해 멀리 달숲에서 왔답니다.$B$B축제에 참여하시는 게 어떻겠습니까?', `FemaleText_loc4`='你好，$n。我们从月光林地来这里，要将新年的喜悦传播到世界的各个角落。$B$B你难道不想与我们一起庆祝新年吗？', `FemaleText_loc5`='你好，$n。我們從月光林地過來，散播新年慶典的精神至世界各地。$B$B你何不加入我們的慶祝活動?', `FemaleText_loc7`='Saludos, $n. Venimos desde Claro de la Luna para propagar el espíritu del Festival Lunar por todas partes.$B$B¿No te vas a unir a nuestra celebración?' WHERE `ID`=11618;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼림도어의 마지막 전투가 우리 손에 달렸습니다. 칼림도어 연합군을 지휘하는 총사령관이 병사들에게 안퀴라즈로 진군하여 적을 섬멸하라는 명령을 내리고 있습니다.', `MaleText_loc4`='决定卡利姆多命运的终极之战即将拉开帷幕。卡利姆多联军的最高指挥官下令所有部队立即开赴安其拉，扫清一切敌人。', `MaleText_loc5`='卡林多最後的戰役就要來臨。卡林多力量的最高指揮官命令其軍隊前進至安其拉並摧毀他們所見的一切。', `MaleText_loc7`='La batalla final por Kalimdor está próxima. El Comandante en Jefe de las fuerzas de Kalimdor ordena a sus tropas que se dirijan a Ahn''Qiraj y destruyan todo a su paso.', `FemaleText_loc1`='칼림도어의 마지막 전투가 우리 손에 달렸습니다. 칼림도어 연합군을 지휘하는 총사령관이 병사들에게 안퀴라즈로 진군하여 적을 섬멸하라는 명령을 내리고 있습니다.', `FemaleText_loc4`='决定卡利姆多命运的终极之战即将拉开帷幕。卡利姆多联军的最高指挥官下令所有部队立即开赴安其拉，扫清一切敌人。', `FemaleText_loc5`='卡林多最後的戰役就要來臨。卡林多力量的最高指揮官命令其軍隊前進至安其拉並摧毀他們所見的一切。', `FemaleText_loc7`='La batalla final por Kalimdor está próxima. El Comandante en Jefe de las fuerzas de Kalimdor ordena a sus tropas que se dirijan a Ahn''Qiraj y destruyan todo a su paso.' WHERE `ID`=11619;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 칼림도어 연합군 앞에 섭니다.', `MaleText_loc4`='%s站在卡利姆多联军阵前。', `MaleText_loc5`='%s站在卡林多聯軍面前。', `MaleText_loc7`='%s permanece ante las fuerzas de Kalimdor.' WHERE `ID`=11620;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 브록시가르의 형제 사울팽이다.', `MaleText_loc4`='我是布洛克斯的兄弟，萨鲁法尔。', `MaleText_loc5`='我是布洛克斯的兄弟，薩魯法爾。', `MaleText_loc7`='Soy Colmillosauro, hermano de Broxigar.' WHERE `ID`=11621;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 칼림도어 연합군을 지휘하는 총사령관이라는 사실은 모두 알 것이다.', `MaleText_loc4`='我是卡利姆多联军的最高指挥官，你们都知道这一点。', `MaleText_loc5`='你知道我是卡林多聯軍的最高指揮官。', `MaleText_loc7`='Me conoces por ser el Comandante en Jefe de las fuerzas de Kalimdor.' WHERE `ID`=11622;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 잠시 연설을 멈추고 앞에 도열해 있는 병사들을 바라봅니다.', `MaleText_loc4`='%s停顿了一下，环顾着站在他面前的那些神情紧张的士兵。', `MaleText_loc5`='%s停下來看著緊張地站在他面前數以萬計的士兵們。', `MaleText_loc7`='%s hace una pausa para observar el Mar de soldados que se encuentran frente a él.' WHERE `ID`=11623;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정한 우리 오크 용사들의 염원은 단 하나! 바로 적과의 전투에서 영광스럽게 전사하는 것이다.', `MaleText_loc4`='一个兽人，一个真正的兽人战士，他一生的追求只有一个：在与敌人的决战中光荣地战死沙场。', `MaleText_loc5`='一個獸人 - 一個真正的獸人戰士 - 只希望一件事:死在對抗可恨敵人的戰役光榮中。', `MaleText_loc7`='Un orco, un verdadero orco guerrero, tan solo ansía una cosa: morir en la gloria de la batalla contra un odiado enemigo.' WHERE `ID`=11624;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 중에는 아직 전투를 겪어 보지 못한 자들도 있을 것이다. 우리는 오랜 세월 평화를 누렸지만 한편에서는 끝없이 전투를 치르기도 했다.', `MaleText_loc4`='你们当中的许多人没有参加过真正的战斗。和平，和平已经伴随了我们许多年。这些年来，我们无所事事，但我们也曾奋战过许多年。', `MaleText_loc5`='你們有些人沒有打過仗。我們已經度過許多年和平的日子。我們安然無恙很多年但是我們也浴血奮戰很多年。', `MaleText_loc7`='Algunos de ustedes nunca han vivido una batalla pues la paz lleva muchos años reinando entre nosotros. Vivimos en paz muchos años pero también luchamos muchos otros.' WHERE `ID`=11625;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 땅에서 전쟁이 일어나 불타는 군단과 스컬지가 우리 고향을 약탈하고 가족을 학살하던 시절, 저 벌레들은 땅속에 숨어 있었다. 바로 우리 고향 땅 아래 숨어 지내며 때를 기다렸던 것이다.', `MaleText_loc4`='在那段战斗的岁月里，硝烟弥漫着天空和大地，燃烧军团和亡灵天灾肆虐在我们的家园，杀戮着我们的亲人。在那时，这些虫子潜伏在我们脚下，潜伏在我们的家园下面，等待着。', `MaleText_loc5`='在那些年裡 - 戰鬥充斥著土地，燃燒軍團和天譴軍團掠奪我們的家園，殺死我們的親人 - 這些昆蟲就住在我們之下。就在我們的家園底下  - 等待著。', `MaleText_loc7`='En ese tiempo, en el que la tierra sufría la amenaza de la Legión y la Plaga que saqueaban nuestros hogares y mataban a nuestras familias, estos insectos vivían bajo nuestros pies. Estaban bajo nuestras casas, esperando.' WHERE `ID`=11626;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들은 우리의 목숨을 빼앗고, 자신들을 가로막는 모든 것을 파괴할 때를 기다리고 있다. 바로 벌레들의 신을 위하여...', `MaleText_loc4`='等待着把我们全都杀死，从我们的孩子开始。这就是它们为自己的神所做的事情。', `MaleText_loc5`='等著粉碎我們的生命。殺光他們所見的一切。他們是為了他們的神祇才這麼做。', `MaleText_loc7`='Esperando a aplastar nuestras vidas y a arrasar todo a su paso. Esto lo hacen por su dios.' WHERE `ID`=11627;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇다면 우리의 신은?', `MaleText_loc4`='我们会为自己的神明做些什么？', `MaleText_loc5`='而我們的神?呢?', `MaleText_loc7`='¿Y nosotros por los nuestros?' WHERE `ID`=11628;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 지킨다. 단결하여 놈들을 쓸어버릴 것이다. 벌레의 신들도 함께...', `MaleText_loc4`='我们誓死抵抗。我们誓不言败。我们是一个整体，一个团结起来的整体。我们将获得胜利，而它们的神必将失败。', `MaleText_loc5`='我們防守。我們堅定。我們合而為一。團結。我們摧毀。他們的神祇會倒下。', `MaleText_loc7`='Nosotros defendemos y resistimos. Somos uno, estamos unidos. Nosotros destruimos. Su dios caerá.' WHERE `ID`=11629;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘, 이 전장에서 쓰러진다면 그것은 가장 오크다운 죽음이라고 할 수 있다. 오늘, 우리가 죽는 것은 우리의 부모, 자식... 그리고 사랑하는 이를 위한 것이다.', `MaleText_loc4`='今天，如果我们战死，死在这片战场上，我们虽死犹荣。今天，如果我们战死，那是为了保卫我们的孩子，我们的父母，我们的……爱人。', `MaleText_loc5`='今天在這個戰場上死去，是獸人之死。今天陣亡是為了我們的親人。我們的先人。我們...摯愛的人。', `MaleText_loc7`='Morir hoy, en este campo de batalla, es morir como un auténtico orco. Morir hoy es morir por nuestros pequeños y nuestros mayores, en definitiva, por todos a los que amamos.' WHERE `ID`=11630;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 영광스러운 죽음을 거부할 자 어디 있느냐? 이 얼마나 영광스러운가?', `MaleText_loc4`='你们当中有谁会惧怕这样的死亡？有谁会拒绝获得这样伟大的荣耀？', `MaleText_loc5`='你們有任何人拒絕這樣的死亡嗎?這樣的榮譽?', `MaleText_loc7`='¿Acaso alguno de ustedes rechazaría esa muerte, ese honor?' WHERE `ID`=11631;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼림도어를 위하여!', `MaleText_loc4`='为了卡利姆多而战！', `MaleText_loc5`='為卡林多而戰!', `MaleText_loc7`='¡POR KALIMDOR!', `FemaleText_loc1`='칼림도어를 위하여!', `FemaleText_loc4`='为了卡利姆多而战！', `FemaleText_loc5`='為卡林多而戰!', `FemaleText_loc7`='¡POR KALIMDOR!' WHERE `ID`=11632;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명예를 위하여!', `MaleText_loc4`='为荣誉而战！', `MaleText_loc5`='為了榮耀而戰!', `MaleText_loc7`='¡POR EL HONOR!', `FemaleText_loc1`='명예를 위하여!', `FemaleText_loc4`='为荣誉而战！', `FemaleText_loc5`='為了榮耀而戰!', `FemaleText_loc7`='¡POR EL HONOR!' WHERE `ID`=11633;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='국왕 만세!', `MaleText_loc4`='为了国王！', `MaleText_loc5`='為了國王!', `MaleText_loc7`='¡POR EL REY!', `FemaleText_loc1`='국왕 만세!', `FemaleText_loc4`='为了国王！', `FemaleText_loc5`='為了國王!', `FemaleText_loc7`='¡POR EL REY!' WHERE `ID`=11634;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마그니 폐하 만세!', `MaleText_loc4`='为麦格尼而战！', `MaleText_loc5`='為了麥格尼而戰!', `MaleText_loc7`='¡POR MAGNI!', `FemaleText_loc1`='마그니 폐하 만세!', `FemaleText_loc4`='为麦格尼而战！', `FemaleText_loc5`='為了麥格尼而戰!', `FemaleText_loc7`='¡POR MAGNI!' WHERE `ID`=11635;
