UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마지막 숨을 쉴 수 있을 때까지 함께 가겠습니다.', `MaleText_loc4`='我将与你们并肩作战，直到我生命的最后一刻。', `MaleText_loc5`='我會永遠跟隨你直到我嚥下最後一口氣。', `MaleText_loc7`='Estaré contigo hasta mi último aliento de vida.' WHERE `ID`=11638;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 엘룬께 기도를 올립니다.', `FemaleText_loc4`='%s念诵了一段祷言。', `FemaleText_loc5`='%s念誦了一段禱言。', `FemaleText_loc7`='%s reza una oración.' WHERE `ID`=11639;
