UPDATE `locales_broadcast_text` SET `MaleText_loc1`='브록시가르의 이름을 걸고!', `MaleText_loc4`='为了布洛克斯而战！', `MaleText_loc5`='為了布洛克斯而戰!', `MaleText_loc7`='¡Por Broxigar!', `FemaleText_loc1`='브록시가르의 이름을 걸고!', `FemaleText_loc4`='为了布洛克斯而战！', `FemaleText_loc5`='為了布洛克斯而戰!', `FemaleText_loc7`='¡Por Broxigar!' WHERE `ID`=11643;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼림도어의 태양을 위하여!', `MaleText_loc4`='为了卡利姆多而战！', `MaleText_loc5`='為了卡林多而戰!', `MaleText_loc7`='¡Por Kalimdor!', `FemaleText_loc1`='칼림도어의 태양을 위하여!', `FemaleText_loc4`='为了卡利姆多而战！', `FemaleText_loc5`='為了卡林多而戰!', `FemaleText_loc7`='¡Por Kalimdor!' WHERE `ID`=11644;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드를 위하여! 케른과 썬더 블러프를 위하여!', `MaleText_loc4`='为了部落！为了凯恩！为了雷霆崖！前进！', `MaleText_loc5`='為了部落!為了凱恩!為了雷霆崖!', `MaleText_loc7`='¡POR LA HORDA! ¡POR CAIRNE! ¡POR LA CIMA DEL TRUENO!', `FemaleText_loc1`='호드를 위하여! 케른과 썬더 블러프를 위하여!', `FemaleText_loc4`='为了部落！为了凯恩！为了雷霆崖！前进！', `FemaleText_loc5`='為了部落!為了凱恩!為了雷霆崖!', `FemaleText_loc7`='¡POR LA HORDA! ¡POR CAIRNE! ¡POR LA CIMA DEL TRUENO!' WHERE `ID`=11645;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전진! 안퀴라즈를 향하여!', `MaleText_loc4`='前进！向安其拉进军！', `MaleText_loc5`='前進!向安其拉進軍!', `MaleText_loc7`='¡ADELANTE! ¡A AHN''QIRAJ!' WHERE `ID`=11646;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기 우리의 운명이 기다리고 있다...', `MaleText_loc4`='我们的命运之战即将开始……', `MaleText_loc5`='我們的命運之戰即將開始...', `MaleText_loc7`='Nuestros destinos nos esperan...' WHERE `ID`=11647;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼림도어 연합군의 힘을 보여줘라!', `MaleText_loc4`='面对卡利姆多联军的力量吧！', `MaleText_loc5`='面對卡林多聯軍的力量吧!', `MaleText_loc7`='¡Afronta el poder de Kalimdor!' WHERE `ID`=11648;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼림도어 연합군이 승리를 거두었습니다! 최후의 퀴라지 부대가 패하여 고대의 요새 안퀴라즈로 퇴각하고 있습니다. 칼림도어를 어지럽히던 공명의 퀴라지 수정들은 나타날 때와 같이 순식간에 사라지고 대지에 균열만을 남겼습니다.', `MaleText_loc4`='卡利姆多联军胜利了！其拉虫人的最后一股力量被彻底打垮，逃入了古老的安其拉城堡。遍布卡利姆多的其拉共鸣水晶就像它们出现时一样飞快地消失了，只留下了一片片凹陷的地面。', `MaleText_loc5`='卡林多聯軍戰勝了!其拉蟲人的最後一股力量被徹底打垮，逃入了古老的安其拉城堡。遍佈卡林多的其拉共鳴水晶就像它們出現時一樣飛快地消失了，只留下了一片片凹陷的地面。', `MaleText_loc7`='¡El poder de Kalimdor ha vencido! La última de las tropas qiraji ha sido derrotada y se está replegando de vuelta a la antigua ciudad-fortaleza de Ahn''Qiraj. Los cristales resonadores qiraji que ensombrecen Kalimdor se desvanecen con la misma facilidad con la que surgieron, dejando tras de sí la marca de su ubicación.', `FemaleText_loc1`='칼림도어 연합군이 승리를 거두었습니다! 최후의 퀴라지 부대가 패하여 고대의 요새 안퀴라즈로 퇴각하고 있습니다. 칼림도어를 어지럽히던 공명의 퀴라지 수정들은 나타날 때와 같이 순식간에 사라지고 대지에 균열만을 남겼습니다.', `FemaleText_loc4`='卡利姆多联军胜利了！其拉虫人的最后一股力量被彻底打垮，逃入了古老的安其拉城堡。遍布卡利姆多的其拉共鸣水晶就像它们出现时一样飞快地消失了，只留下了一片片凹陷的地面。', `FemaleText_loc5`='卡林多聯軍戰勝了!其拉蟲人的最後一股力量被徹底打垮，逃入了古老的安其拉城堡。遍佈卡林多的其拉共鳴水晶就像它們出現時一樣飛快地消失了，只留下了一片片凹陷的地面。', `FemaleText_loc7`='¡El poder de Kalimdor ha vencido! La última de las tropas qiraji ha sido derrotada y se está replegando de vuelta a la antigua ciudad-fortaleza de Ahn''Qiraj. Los cristales resonadores qiraji que ensombrecen Kalimdor se desvanecen con la misma facilidad con la que surgieron, dejando tras de sí la marca de su ubicación.' WHERE `ID`=11649;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라작스를 처치하라는 명령을 받았다. 깔끔하게 마무리하고 싶다면 놈을 제거하라.', `MaleText_loc4`='我们奉命消灭拉贾克斯。你可以使用任何手段来达到这一目的。', `MaleText_loc5`='我們收到高層命令要摧毀拉賈克斯。如果你想按規則來的話，終止極端的偏見。', `MaleText_loc7`='Tenemos órdenes de arriba de acabar con Rajaxx. Causen daño extremo si quieren mejorar su técnica.' WHERE `ID`=11650;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이겼다! 저기 놈들이 신전으로 도망치는 모습을 보아라. 조만간 모조리 없앤다. 벌레들의 지휘관들은 이미 제거됐다!', `MaleText_loc4`='胜利了！看！它们逃进了安其拉神殿里！很快，它们的主宰也会被消灭……它们的末日不远了！', `MaleText_loc5`='戰勝了!看著他們逃到珍貴的神廟裡避難。很快一切就會被夷平...他們的領導者就會被摧毀!', `MaleText_loc7`='¡La batalla es nuestra! Mirad como huyen para buscar refugio en su preciado templo. Pronto todo estará arrasado... ¡y acabaremos con sus líderes!' WHERE `ID`=11651;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$r|1이여;여;, 우리는 얼라이언스와 힘을 합쳤다. 너무나 오래되어 이 세계가 그 존재조차 잊고 있던 악마가 우리를 먹어치우려 한다. 첫 번째 목표는 칼림도어, 그다음에는 아제로스의 나머지 지역이 될 것이다. 위대한 영원의 창조주 티탄이 빚은 모든 생명에 대한 적개심이 악마를 움직이고 있다.$B$B우리 모두 크툰의 군대를 막기 위해 나섰다. 선제공격으로 안퀴라즈 세력을 무찌를 것이다. 전 아제로스에 호드와 얼라이언스의 단결된 힘과 용기의 함성이 울리리라.$B$B전쟁을 준비하는 데는 자네의 도움이 필요하다!', `MaleText_loc4`='我们和联盟并肩作战，共同进退，$r。一个古老的邪恶力量正在准备将我们全部吞噬，首先是卡利姆多，然后是整个艾泽拉斯。这股邪恶是如此地古老，我们都已经忘记了它的存在。驱动它的力量的源泉，乃是对于造物之神泰坦以及一切由泰坦创造的事物的仇恨。$B$B我们是唯一能阻挡克苏恩的力量。我们要先发制人，击溃安其拉的虫人。让艾泽拉斯在部落和联盟的力量面前震撼吧。$B$B战备工作需要你的帮助！', `MaleText_loc5`='我們和聯盟站在同一陣線，$r。一個惡魔，古老到世界已經遺忘了它，想要吞沒我們;先是卡林多，再來就是整個艾澤拉斯。它被一個偉大變形者所創的仇恨而驅使:永恆的泰坦。$B$B我們全都阻擋著克蘇恩的軍隊。我們會先進攻並拿下安其拉的軍隊。讓整個艾澤拉斯因為部落和聯盟的力量結合而震動。$B$B戰爭需要你!', `MaleText_loc7`='Seguimos al lado de la Alianza, $r. Un mal, tan antiguo que el mundo ya no es capaz de recordar, intenta destruirnos a todos; primero a Kalimdor y después al resto de Azeroth. Se mueve por el odio por todas las cosas que emana de los grandes Creadores: los titanes eternos.$B$BNosotros somos los únicos que se interponen en el camino de los ejércitos de C''Thun. Atacaremos en primer lugar y acabaremos con las fuerzas de Ahn''Qiraj. Que todo Azeroth tiemble antes las fuerzas combinadas de la Horda y la Alianza.$B$B¡La campaña para la guerra te necesita!' WHERE `ID`=11652;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장로 메도런은 어디에 있습니까?', `MaleText_loc4`='幽林长者在哪里？', `MaleText_loc5`='草奔長者在哪裡?', `MaleText_loc7`='¿Dónde está el ancestro Correpradera?', `FemaleText_loc1`='장로 메도런은 어디에 있습니까?', `FemaleText_loc4`='幽林长者在哪里？', `FemaleText_loc5`='草奔長者在哪裡?', `FemaleText_loc7`='¿Dónde está el ancestro Correpradera?' WHERE `ID`=11653;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 장로 메도런을 마지막으로 본 장소는 서부 역병지대 진흙탕 동굴이었다네.', `MaleText_loc4`='幽林长者在西瘟疫之地的哭泣之洞外面。', `MaleText_loc5`='我上次看到草奔長者是在西瘟疫之地的聖光之願禮拜堂。', `MaleText_loc7`='La última vez que vi al ancestro Correpradera fue en La Cueva del Llanto en las Tierras de la Peste del Oeste.', `FemaleText_loc1`='내가 장로 메도런을 마지막으로 본 장소는 서부 역병지대 진흙탕 동굴이었다네.', `FemaleText_loc4`='幽林长者在西瘟疫之地的哭泣之洞外面。', `FemaleText_loc5`='我上次看到草奔長者是在西瘟疫之地的聖光之願禮拜堂。', `FemaleText_loc7`='La última vez que vi al ancestro Correpradera fue en La Cueva del Llanto en las Tierras de la Peste del Oeste.' WHERE `ID`=11654;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장로 스타글레이드는 어디에 있습니까?', `MaleText_loc4`='星林长者在哪里？', `MaleText_loc5`='星林長者在哪裡?', `MaleText_loc7`='¿Dónde está el ancestro Claroestelar?', `FemaleText_loc1`='장로 스타글레이드는 어디에 있습니까?', `FemaleText_loc4`='星林长者在哪里？', `FemaleText_loc5`='星林長者在哪裡?', `FemaleText_loc7`='¿Dónde está el ancestro Claroestelar?' WHERE `ID`=11656;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장로 스타글레이드는 가시덤불 골짜기에 줄구룹으로 들어가는 문밖에서 찾을 수 있을 걸세.', `MaleText_loc4`='星林长者在荆棘谷的祖尔格拉布大门外面。', `MaleText_loc5`='你可以在荊棘谷通往祖爾格拉布的入口外面找到星林長者。', `MaleText_loc7`='Encontrarás al ancestro Claroestelar fuera de las puertas de Zul''Gurub en la Vega de Tuercespina.', `FemaleText_loc1`='장로 스타글레이드는 가시덤불 골짜기에 줄구룹으로 들어가는 문밖에서 찾을 수 있을 걸세.', `FemaleText_loc4`='星林长者在荆棘谷的祖尔格拉布大门外面。', `FemaleText_loc5`='你可以在荊棘谷通往祖爾格拉布的入口外面找到星林長者。', `FemaleText_loc7`='Encontrarás al ancestro Claroestelar fuera de las puertas de Zul''Gurub en la Vega de Tuercespina.' WHERE `ID`=11657;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들은 말했소. "전쟁 물자를 모으는 임무를 훌륭히 완수했군. 자네도 진급할 때가 된 것 같은데..." 하지만, 이 말의 진짜 의미는 이거였소! "칸스, 자네를 땀 냄새나는 드워프 무리와 함께 실리더스의 벌레집 외곽으로 전출하는 바이네."$B$B진급?! 훗, 정말 눈물 나게 고맙지 뭐요.', `MaleText_loc4`='“在为战争采集资源这方面，你做得太棒了！”他们说，“你一定会得到晋升的！”然而他们真正的意思是，“你会和一群小不点的矮人一起被部署在希利苏斯的某个虫巢外面，卡恩斯！”$B$B多谢提携，中尉！', `MaleText_loc5`='「你的戰爭物資收集工作做的很好」他們說，「你一定會得到晉升的!」。他們真正的意思是，「你會和一群小不點的矮人一起被部署在希利蘇斯的某個蟲巢外面，卡恩斯!」$B$B謝謝你的提拔，上尉!', `MaleText_loc7`='"Ha hecho un buen trabajo reuniendo material para la guerra", dijeron, "se merece un ascenso". Lo que realmente querían decir es "¡Está emplazado al lado de una colmena de bichos en Silithus con un montón de enanos sudorosos, Carnes!"$B$B¡Gracias por el ascenso, Capitán!' WHERE `ID`=11658;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전 오빠와 마찬가지로 선조의 은혜를 기리는 분들을 높이 삽니다. 특히, 달의 축제의 대의를 충실히 따르는 분들에게 저의 기술을 전수할 수 있다는 것은 커다란 기쁨이지요.', `FemaleText_loc4`='我，就像我的哥哥一样，以那些尊重祖先的人为荣。对我来说，与欢度春节的人们一起分享我的秘密手艺是极大的快乐。', `FemaleText_loc5`='我，就像我的哥哥一樣，為那些替自己祖先爭光的人爭光。與新年慶典的侍徒們分享我手工技藝的秘密帶給我很大的快樂!', `FemaleText_loc7`='Yo, al igual que mi hermano, honro a aquellos que honran a sus antepasados. ¡Qué gran dicha compartir los secretos de mi oficio con los discípulos del Festival Lunar!' WHERE `ID`=11659;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나약한 족속이여, 원한다면 도망쳐라! 내 곁에 있는 한 너희에겐 저주만이 따를 뿐이다!', `MaleText_loc4`='跑吧，胆小鬼！别自讨苦吃！', `MaleText_loc5`='想跑就跑吧你這個懦夫!對你不會有好處的!', `MaleText_loc7`='¡Corred si queréis, cobardes! ¡Eso no os solucionará nada!' WHERE `ID`=11660;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 있는 다른 친구들과 마찬가지로, 저는 전투가 시작되었을 때 제 친구인 드루이드를 돕기 위해서 왔습니다.$B$B이제 안퀴라즈의 관문이 열리고, 끝내야 할 많은 일들이 아직 남아있다는 것을 알게 되었지요. 전 이곳 실리더스에 남아있기로 결정했고 우리의 목표를 달성하는데 최선을 다할 것입니다, $n.', `MaleText_loc4`='就像其他人一样，我在开战初期就来帮助我的德鲁伊同胞。$B$B现在安其拉的大门已经打开，但我意识到许多工作还没有完成。因此我决定留在希利苏斯，尽我所能地帮助他们。', `MaleText_loc5`='當戰爭開打時，我就像其他人一樣，是來這裡幫助我的夥伴德魯伊們。$B$B現在安其拉之門已經開啟，我知道還有很多工作需要完成。我已決定要待在希利蘇斯，並盡全力協助達成目標，$n。', `MaleText_loc7`='Yo, al igual que muchos otros, vine en ayuda de mis compañeros druidas al comenzar la guerra.$B$BAhora que las puertas de Ahn''Qiraj se han abierto, me he dado cuenta de que aún queda mucho trabajo por hacer. He decidido quedarme en Silithus y hacer todo lo posible por contribuir a la causa, $n.' WHERE `ID`=11661;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실리시드의 겉모습에도 드러나듯이 그들의 위험성은 길들여진 것들 빼고는 퀴라지 대군주와도 견줄만하죠.', `MaleText_loc4`='异种虫看起来已经够可怕的了，可是和它们的其拉主人比起来，它们可以算是温顺的了。', `MaleText_loc5`='異種蠍看來相當致命，但牠們和其拉主宰比起來卻只是隻溫馴的小動物。', `MaleText_loc7`='Aunque los silítidos semejen muy peligrosos, no son más que dóciles criaturas al lado de los señores supremos qiraji.' WHERE `ID`=11662;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 전쟁은 끝나지 않았소. 이제 시작된 것이오! 우리에게는 안퀴라즈 안에서 밤낮으로 우리의 적과 싸울 용맹한 자들이 있소이다, $n. 퀴라지 도시가 함락되는 건 오래 걸리지 않을 것이오.', `MaleText_loc4`='这场战争还没有结束，它才刚刚开始！勇敢的士兵日日夜夜在安其拉与敌人血战，很快，这座其拉虫人的城市就要陷落了。', `MaleText_loc5`='這戰爭還沒結束，才剛開始而已!我們日夜都有勇猛的戰士對抗安其拉裡的敵人， $n。不久之後其拉城就會淪陷。', `MaleText_loc7`='¡Esta guerra no ha acabado sino que no ha hecho más que comenzar! Contamos con valientes hombres y mujeres que luchan día y noche contra el enemigo en el interior de Ahn''Qiraj, $n. La ciudad qiraji no tardará mucho en caer.' WHERE `ID`=11663;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='퀴라지에 대항하는 이번 전투에서 우리의 안정적인 진척 상황은 칼림도어의 모든 지역에서 받은 다양한 도움에 기인한다고 할 수 있습니다.$B$B그대는 단순히 전투에서 싸우는 전사보다는 더 많은 것이 필요합니다, $n. 전투에서 찬양받지 않은 많은 영웅들이라고 한다면 군대가 필요로 하는 자원을 보급하여 우리의 군대를 유지시켜 주는 상인과 기술자이라고 할 수 있습니다.', `FemaleText_loc4`='目前我们对其拉战争的节节胜利可以说是全卡利姆多大陆各个种族共同努力的结果。$B$B但除了士兵之外，我们还需要更多的东西来支撑这场战争，$n。许多商贩和工匠其实都是这场战争中的无名英雄，正是他们一直源源不断地将物资送到前线。', `FemaleText_loc5`='我們能從容穩固的對其拉發起戰鬥攻勢，都要歸功於整個卡林多的全力相助。$B$B你打仗需要的不只是士兵而已，$n。商人和工匠也是戰爭裡的無名英雄，他們能補給戰爭所需要的所有物資。', `FemaleText_loc7`='Nuestros progresos en la lucha contra los qiraji se deben a la ayuda que estamos recibiendo de casi todos los rincones de Kalimdor.$B$BNecesitas algo más que Soldados para luchar en una guerra, $n. Los héroes olvidados de la guerra son los comerciantes y artesanos que suministran a nuestras tropas todo lo que necesitan.' WHERE `ID`=11664;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들은 이곳 달숲에서 어떻게 축제를 여는지 알고 있답니다. 누가 그렇게 생각이나 했겠습니까?', `MaleText_loc4`='他们真能想，居然在月光林地搞聚会，真棒！', `MaleText_loc5`='他們知道怎樣在月光林地這裡辦派對。誰會這麼想啊?', `MaleText_loc7`='En Claro de la Luna sí que saben hacer fiestas. ¿Quién lo hubiera imaginado?', `FemaleText_loc1`='그들은 이곳 달숲에서 어떻게 축제를 여는지 알고 있답니다. 누가 그렇게 생각이나 했겠습니까?', `FemaleText_loc4`='他们真能想，居然在月光林地搞聚会，真棒！', `FemaleText_loc5`='他們知道怎樣在月光林地這裡辦派對。誰會這麼想啊?', `FemaleText_loc7`='En Claro de la Luna sí que saben hacer fiestas. ¿Quién lo hubiera imaginado?' WHERE `ID`=11665;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 폭죽 발사대를 사용하세요. 멋지게 날아갈 겁니다!', `MaleText_loc4`='试试这些烟花发射器，非常棒！', `MaleText_loc5`='試試這些煙火發射器，它們可是火力十足!', `MaleText_loc7`='Prueba estos lanzacohetes. ¡Son geniales!', `FemaleText_loc1`='이 폭죽 발사대를 사용하세요. 멋지게 날아갈 겁니다!', `FemaleText_loc4`='试试这些烟花发射器，非常棒！', `FemaleText_loc5`='試試這些煙火發射器，它們可是火力十足!', `FemaleText_loc7`='Prueba estos lanzacohetes. ¡Son geniales!' WHERE `ID`=11666;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 달빛의 섬광이 스톰윈드로 이끌 겁니다. 준비가 되면 당신의 초대장을 사용하세요.', `MaleText_loc4`='这道月光会把你送到暴风城去。当你想要离开庆典的时候，就在这里使用你的邀请函。', `MaleText_loc5`='這道月光會指引你到暴風城。你準備好的時候，就使用邀請函。', `MaleText_loc7`='Este destello de luna conduce hasta Ventormenta. Utiliza tu invitación cuando estés $glisto:lista;.', `FemaleText_loc1`='이 달빛의 섬광이 스톰윈드로 이끌 겁니다. 준비가 되면 당신의 초대장을 사용하세요.', `FemaleText_loc4`='这道月光会把你送到暴风城去。当你想要离开庆典的时候，就在这里使用你的邀请函。', `FemaleText_loc5`='這道月光會指引你到暴風城。你準備好的時候，就使用邀請函。', `FemaleText_loc7`='Este destello de luna conduce hasta Ventormenta. Utiliza tu invitación cuando estés $glisto:lista;.' WHERE `ID`=11667;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적의 도시로 순간이동하려 하진 마세요. 작동하지 않을 겁니다. 여기선 모두들 사이좋게 지내지만 그렇다고 해서 오랜 원한이 사라진 건 아니지요.', `MaleText_loc4`='别想要传送到你的敌人的城市去……那根本不可能。我们可能在这里是朋友，但出了月光林地就不好说了……', `MaleText_loc5`='不要想移動你敵人的城市。不會成功的－現在我們在這裡都挺友善的，但回到家鄉，舊有的仇恨卻還是存在著...', `MaleText_loc7`='No intentes teletransportarte a las ciudades de tus enemigos pues no funcionaría. Aquí todos somos muy amigos pero en casa las viejas rencillas no se olvidan...', `FemaleText_loc1`='적의 도시로 순간이동하려 하진 마세요. 작동하지 않을 겁니다. 여기선 모두들 사이좋게 지내지만 그렇다고 해서 오랜 원한이 사라진 건 아니지요.', `FemaleText_loc4`='别想要传送到你的敌人的城市去……那根本不可能。我们可能在这里是朋友，但出了月光林地就不好说了……', `FemaleText_loc5`='不要想移動你敵人的城市。不會成功的－現在我們在這裡都挺友善的，但回到家鄉，舊有的仇恨卻還是存在著...', `FemaleText_loc7`='No intentes teletransportarte a las ciudades de tus enemigos pues no funcionaría. Aquí todos somos muy amigos pero en casa las viejas rencillas no se olvidan...' WHERE `ID`=11668;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밤의 안식처에 있는 자들은 진정 어떻게 축제를 즐기는지 아는군!', `MaleText_loc4`='永夜港的人们真有点子！', `MaleText_loc5`='永夜港的居民當然知道怎麼狂歡辦派對!', `MaleText_loc7`='¡Los de Amparo de la Noche sí que saben lo que es una buena fiesta!', `FemaleText_loc1`='밤의 안식처에 있는 자들은 진정 어떻게 축제를 즐기는지 아는군!', `FemaleText_loc4`='永夜港的人们真有点子！', `FemaleText_loc5`='永夜港的居民當然知道怎麼狂歡辦派對!', `FemaleText_loc7`='¡Los de Amparo de la Noche sí que saben lo que es una buena fiesta!' WHERE `ID`=11669;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 폭죽들이 터지면 정말 장관일 겁니다, 그렇겠죠?', `MaleText_loc4`='这些烟花真华丽，你不这么认为吗？', `MaleText_loc5`='這些煙火一定會綻放得很棒、很美!對不對?', `MaleText_loc7`='Estos fuegos artificiales seguro que provocan un buen estruendo, ¿no crees?', `FemaleText_loc1`='이 폭죽들이 터지면 정말 장관일 겁니다, 그렇겠죠?', `FemaleText_loc4`='这些烟花真华丽，你不这么认为吗？', `FemaleText_loc5`='這些煙火一定會綻放得很棒、很美!對不對?', `FemaleText_loc7`='Estos fuegos artificiales seguro que provocan un buen estruendo, ¿no crees?' WHERE `ID`=11670;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 달빛이 당신을 아이언포지로 보내줄 겁니다. 그렇지만 누가 이 멋진 축제를 떠나고 싶어할까요?', `MaleText_loc4`='这道月光会把你送到铁炉堡去。但你难道真的想要离开吗？', `MaleText_loc5`='這道月光會指引你到鐵爐堡。但有誰想離開派對啊?', `MaleText_loc7`='Esta luz lunar te llevará hasta Forjaz. ¿Pero quién querría perderse esta fiesta?', `FemaleText_loc1`='이 달빛이 당신을 아이언포지로 보내줄 겁니다. 그렇지만 누가 이 멋진 축제를 떠나고 싶어할까요?', `FemaleText_loc4`='这道月光会把你送到铁炉堡去。但你难道真的想要离开吗？', `FemaleText_loc5`='這道月光會指引你到鐵爐堡。但有誰想離開派對啊?', `FemaleText_loc7`='Esta luz lunar te llevará hasta Forjaz. ¿Pero quién querría perderse esta fiesta?' WHERE `ID`=11672;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='올해 달의 축제는 진정 화려하군요!', `MaleText_loc4`='今年的庆典太棒了！', `MaleText_loc5`='今年的新年慶典相當盛大!', `MaleText_loc7`='¡La celebración lunar este año es magnífica!', `FemaleText_loc1`='올해 달의 축제는 진정 화려하군요!', `FemaleText_loc4`='今年的庆典太棒了！', `FemaleText_loc5`='今年的新年慶典相當盛大!', `FemaleText_loc7`='¡La celebración lunar este año es magnífica!' WHERE `ID`=11673;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 폭죽들은 달의 힘을 사용하는 거라고 그러더군요!', `MaleText_loc4`='有人说这些烟花带着月神的力量！', `MaleText_loc5`='聽說這些煙火是靠著月亮的力量!', `MaleText_loc7`='¡Se dice que estos fuegos artificiales utilizan el poder de la luna!', `FemaleText_loc1`='이 폭죽들은 달의 힘을 사용하는 거라고 그러더군요!', `FemaleText_loc4`='有人说这些烟花带着月神的力量！', `FemaleText_loc5`='聽說這些煙火是靠著月亮的力量!', `FemaleText_loc7`='¡Se dice que estos fuegos artificiales utilizan el poder de la luna!' WHERE `ID`=11674;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 환한 달빛의 광선이 그대를 다르나서스로 보내줄 것입니다.', `MaleText_loc4`='这道月光会把你送到达纳苏斯去。', `MaleText_loc5`='這道強力的月光會指引你到達納蘇斯。', `MaleText_loc7`='Este rayo de luna más intenso te llevará hasta Darnassus.', `FemaleText_loc1`='이 환한 달빛의 광선이 그대를 다르나서스로 보내줄 것입니다.', `FemaleText_loc4`='这道月光会把你送到达纳苏斯去。', `FemaleText_loc5`='這道強力的月光會指引你到達納蘇斯。', `FemaleText_loc7`='Este rayo de luna más intenso te llevará hasta Darnassus.' WHERE `ID`=11675;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 잘 알지 못했다면, 이 축제는 오크가 주최했다고 말했을 거요!', `MaleText_loc4`='换了别人，也许会以为这次庆典是兽人举办的呢！', `MaleText_loc5`='如果我不太清楚，我會說這場派對是由獸人安排的!', `MaleText_loc7`='Si no lo supiera, ¡diría que esta fiesta la organizaron los orcos!', `FemaleText_loc1`='내가 잘 알지 못했다면, 이 축제는 오크가 주최했다고 말했을 거요!', `FemaleText_loc4`='换了别人，也许会以为这次庆典是兽人举办的呢！', `FemaleText_loc5`='如果我不太清楚，我會說這場派對是由獸人安排的!', `FemaleText_loc7`='Si no lo supiera, ¡diría que esta fiesta la organizaron los orcos!' WHERE `ID`=11676;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 마지막 폭죽이 드워프의 옷에 불을 붙일뻔 한 거 봤소? 하!', `MaleText_loc4`='看到了吗？刚才的烟花差点把那个矮人的衣服给点着！哈哈哈！', `MaleText_loc5`='你看到了嗎?最後一支煙火幾乎要讓矮人的襯衫著火了!哈!', `MaleText_loc7`='¿Has visto? ¡El último cohete casi le quema la camisa a ese enano! ¡Ja, ja, ja!', `FemaleText_loc1`='그 마지막 폭죽이 드워프의 옷에 불을 붙일뻔 한 거 봤소? 하!', `FemaleText_loc4`='看到了吗？刚才的烟花差点把那个矮人的衣服给点着！哈哈哈！', `FemaleText_loc5`='你看到了嗎?最後一支煙火幾乎要讓矮人的襯衫著火了!哈!', `FemaleText_loc7`='¿Has visto? ¡El último cohete casi le quema la camisa a ese enano! ¡Ja, ja, ja!' WHERE `ID`=11677;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 달빛 광선이 당신을 오그리마로 보내 줄 것이오. 가고 싶다면 당신의 초대장을 사용하시오.', `MaleText_loc4`='这道月光会把你送到奥格瑞玛去。当你想要离开庆典的时候，就在这里使用你的邀请函。', `MaleText_loc5`='道月光會指引你到奧格瑪。你想出發的時候，就使用邀請函。', `MaleText_loc7`='Este rayo de luna te llevará hasta Orgrimmar. Utiliza tu invitación cuando desees ir.', `FemaleText_loc1`='이 달빛 광선이 당신을 오그리마로 보내 줄 것이오. 가고 싶다면 당신의 초대장을 사용하시오.', `FemaleText_loc4`='这道月光会把你送到奥格瑞玛去。当你想要离开庆典的时候，就在这里使用你的邀请函。', `FemaleText_loc5`='道月光會指引你到奧格瑪。你想出發的時候，就使用邀請函。', `FemaleText_loc7`='Este rayo de luna te llevará hasta Orgrimmar. Utiliza tu invitación cuando desees ir.' WHERE `ID`=11678;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 간소한 달의 축제처럼 자네 뼈 마디 마디를 따뜻하게 해 주는 건 없을 걸세!', `MaleText_loc4`='没什么能比新年的庆典更让人高兴了！', `MaleText_loc5`='只有小型新年慶典能讓你放鬆舒暢!', `MaleText_loc7`='¡Para animarse no hay nada como una pequeña celebración lunar!', `FemaleText_loc1`='이 간소한 달의 축제처럼 자네 뼈 마디 마디를 따뜻하게 해 주는 건 없을 걸세!', `FemaleText_loc4`='没什么能比新年的庆典更让人高兴了！', `FemaleText_loc5`='只有小型新年慶典能讓你放鬆舒暢!', `FemaleText_loc7`='¡Para animarse no hay nada como una pequeña celebración lunar!' WHERE `ID`=11679;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 손가락에 감각이 없는 지금과 같은 상태에선 신중히 폭죽에 불을 붙여야 할 걸세.', `MaleText_loc4`='点烟花的时候要多加小心，手指头是很宝贵的……', `MaleText_loc5`='當你手指頭沒感覺的時候，你就得小心點燃煙火...', `MaleText_loc7`='Si no sientes tus propios dedos ten mucho cuidado al prender los fuegos artificiales...', `FemaleText_loc1`='당신 손가락에 감각이 없는 지금과 같은 상태에선 신중히 폭죽에 불을 붙여야 할 겁니다.', `FemaleText_loc4`='点烟花的时候要多加小心，手指头是很宝贵的……', `FemaleText_loc5`='當你手指頭沒感覺的時候，你就得小心點燃煙火...', `FemaleText_loc7`='Si no sientes tus propios dedos ten mucho cuidado al prender los fuegos artificiales...' WHERE `ID`=11680;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 달빛의 섬광이 언더시티로 이끌어 줄 테니 준비가 되면 물러가게.', `MaleText_loc4`='这道月光会把你送到幽暗城去。当你想要离开的时候，就到这里来吧。', `MaleText_loc5`='這道月光會通往幽暗城。你準備好的時候就繳回邀請函。', `MaleText_loc7`='Este destello de luna conduce hasta Entrañas. Ve cuando estés $glisto:lista;.', `FemaleText_loc1`='이 달빛의 섬광이 언더시티로 이끌어 줄 테니 준비가 되면 가세요.', `FemaleText_loc4`='这道月光会把你送到幽暗城去。当你想要离开的时候，就到这里来吧。', `FemaleText_loc5`='這道月光會通往幽暗城。你準備好的時候就繳回邀請函。', `FemaleText_loc7`='Este destello de luna conduce hasta Entrañas. Ve cuando estés $glisto:lista;.' WHERE `ID`=11681;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 달의 축제가 너무 좋답니다! 당신의 발굽에서 먼지를 털어내며 쉴 수 있는 멋진 곳이지요.', `MaleText_loc4`='我爱春节！这是个让你的蹄子跳起舞来的日子！', `MaleText_loc5`='我愛死了新年慶典!這個超棒的地方可以讓你盡情狂歡!', `MaleText_loc7`='¡Me encanta el Festival Lunar! ¡Es la ocasión ideal para mover las patas!', `FemaleText_loc1`='전 달의 축제가 너무 좋답니다! 당신의 발굽에서 먼지를 털어내며 쉴 수 있는 멋진 곳이지요.', `FemaleText_loc4`='我爱春节！这是个让你的蹄子跳起舞来的日子！', `FemaleText_loc5`='我愛死了新年慶典!這個超棒的地方可以讓你盡情狂歡!', `FemaleText_loc7`='¡Me encanta el Festival Lunar! ¡Es la ocasión ideal para mover las patas!' WHERE `ID`=11682;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음... 이 폭죽들이 어떻게 되는지 잘 모르겠지만... 폭죽을 터뜨리면 무척 예쁠 거예요.', `MaleText_loc4`='我不知道这些烟花的工作原理，但它们真的很漂亮！', `MaleText_loc5`='我不知道要怎麼放這些煙火，但那火花真的很漂亮!', `MaleText_loc7`='No sé exactamente cómo funcionan estos fuegos artificiales, ¡pero seguro que son geniales!', `FemaleText_loc1`='음... 이 폭죽들이 어떻게 되는지 잘 모르겠지만... 폭죽을 터뜨리면 무척 예쁠 거예요.', `FemaleText_loc4`='我不知道这些烟花的工作原理，但它们真的很漂亮！', `FemaleText_loc5`='我不知道要怎麼放這些煙火，但那火花真的很漂亮!', `FemaleText_loc7`='No sé exactamente cómo funcionan estos fuegos artificiales, ¡pero seguro que son geniales!' WHERE `ID`=11683;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 달빛이 썬더 블러프로 당신을 데려다 줄 거랍니다. 달의 축제를 떠나고 싶으시면 초대장을 사용하세요.', `MaleText_loc4`='这道月光会把你送到雷霆崖去。当你想要离开庆典的时候，就到这里来吧。', `MaleText_loc5`='這道月光會指引你到雷霆崖。當你想離開慶典的時候，就使用這個。', `MaleText_loc7`='Esta luz lunar te llevará hasta Cima del Trueno. Utilízala cuando desees abandonar el festival.', `FemaleText_loc1`='이 달빛이 썬더 블러프로 당신을 데려다 줄 거랍니다. 달의 축제를 떠나고 싶으시면 초대장을 사용하세요.', `FemaleText_loc4`='这道月光会把你送到雷霆崖去。当你想要离开庆典的时候，就到这里来吧。', `FemaleText_loc5`='這道月光會指引你到雷霆崖。當你想離開慶典的時候，就使用這個。', `FemaleText_loc7`='Esta luz lunar te llevará hasta Cima del Trueno. Utilízala cuando desees abandonar el festival.' WHERE `ID`=11684;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밤새도록 폭죽 축제가 펼쳐질 겁니다. 저녁 6시부터 새벽까지, 엘룬아라 호수를 건너 하늘이 밝게 빛나게 될 겁니다.', `MaleText_loc4`='整晚都会有烟花表演，从下午6点直到黎明，月神湖的上空将会绽放无数美丽的花朵！', `MaleText_loc5`='他們要施放整夜的煙火秀。月神湖的天空將從晚上6點閃耀到日出!', `MaleText_loc7`='Habrá fuegos artificiales durante toda la noche. Desde las 6PM hasta el amanecer, ¡el cielo resplandecerá sobre Elune''ara!', `FemaleText_loc1`='밤새도록 폭죽 축제가 펼쳐질 겁니다. 저녁 6시부터 새벽까지, 엘룬아라 호수를 건너 하늘이 밝게 빛나게 될 겁니다.', `FemaleText_loc4`='整晚都会有烟花表演，从下午6点直到黎明，月神湖的上空将会绽放无数美丽的花朵！', `FemaleText_loc5`='他們要施放整夜的煙火秀。月神湖的天空將從晚上6點閃耀到日出!', `FemaleText_loc7`='Habrá fuegos artificiales durante toda la noche. Desde las 6PM hasta el amanecer, ¡el cielo resplandecerá sobre Elune''ara!' WHERE `ID`=11685;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들이 달의 축제가 마감됨을 전하면서 이 초롱들을 끌 것입니다.', `MaleText_loc4`='他们挂起灯笼是为了庆祝春节。', `MaleText_loc5`='他們擺出這些燈籠來慶祝即將到來的新年節慶。', `MaleText_loc7`='Colocan todos estos faroles para conmemorar la clausura del Festival Lunar.', `FemaleText_loc1`='그들이 달의 축제가 마감됨을 전하면서 이 초롱들을 끌 것입니다.', `FemaleText_loc4`='他们挂起灯笼是为了庆祝春节。', `FemaleText_loc5`='他們擺出這些燈籠來慶祝即將到來的新年節慶。', `FemaleText_loc7`='Colocan todos estos faroles para conmemorar la clausura del Festival Lunar.' WHERE `ID`=11686;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달의 축제의 마지막 밤이로군요. 행운이 그대와 함께하기를!', `MaleText_loc4`='今天是春节的最后一天，祝你来年万事顺意！', `MaleText_loc5`='這是新年節慶的最後一夜。願好運與你同在!', `MaleText_loc7`='¡Es la última noche del Festival Lunar! Que la fortuna esté contigo.', `FemaleText_loc1`='달의 축제의 마지막 밤이로군요. 행운이 그대와 함께하기를!', `FemaleText_loc4`='今天是春节的最后一天，祝你来年万事顺意！', `FemaleText_loc5`='這是新年節慶的最後一夜。願好運與你同在!', `FemaleText_loc7`='¡Es la última noche del Festival Lunar! ¡Que la fortuna esté contigo!' WHERE `ID`=11687;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대의 선조께서 그대를 축복하시길, $n 님. 그리고 다가오는 해에도 행운이 깃들기를...', `MaleText_loc4`='愿你们的长者祝福你，$n，祝你明年万事顺意，心想事成。', `MaleText_loc5`='願你的長者保佑你，$n，帶給你來年的好運。', `MaleText_loc7`='$n, que tus ancestros te bendigan y te den mucha suerte para el nuevo año.', `FemaleText_loc1`='그대의 선조께서 그대를 축복하시길, $n 님. 그리고 다가오는 해에도 행운이 깃들기를...', `FemaleText_loc4`='愿你们的长者祝福你，$n，祝你明年万事顺意，心想事成。', `FemaleText_loc5`='願你的長者保佑你，$n，帶給你來年的好運。', `FemaleText_loc7`='$n, que tus ancestros te bendigan y te den mucha suerte para el nuevo año.' WHERE `ID`=11688;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 오멘을 소환할 수 있습니까?', `MaleText_loc4`='我怎样才能召唤年兽？', `MaleText_loc5`='我要如何召喚年獸?', `MaleText_loc7`='¿Cómo puedo invocar a Augurio?', `FemaleText_loc1`='어떻게 오멘을 소환할 수 있나요?', `FemaleText_loc4`='我怎样才能召唤年兽？', `FemaleText_loc5`='我要如何召喚年獸?', `FemaleText_loc7`='¿Cómo puedo invocar a Augurio?' WHERE `ID`=11689;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오멘은 엘룬아라 호수의 깊은 곳에 잠들어 있습니다만 스톰레이지 지하굴 근처, 남동쪽 비탈에서 소환될 겁니다. 거기에서 그대는 특별한 연발탄 발사대를 찾게 될 겁니다...$B$B발사대에서 폭죽을 사용하면 오멘의 부하들이 올 겁니다. 폭죽을 대략 30개 정도 더 발사하거나 엘룬의 양초를 오멘의 부하들에게 발사하면 곧 오멘이 깨어날 겁니다.', `MaleText_loc4`='年兽沉睡在月神湖底的深处，但你可以在湖东南岸，也就是靠近怒风兽穴的地方召唤它。你可以在那里找到特殊的烟花束发射器……$B$B在发射器那里使用你的烟花，年兽的爪牙就会出现。发射更多的烟花，大约三十组，或者朝它的爪牙投掷艾露恩的蜡烛，年兽就会醒来。', `MaleText_loc5`='年獸就睡在月神湖深處，但要在怒風獸穴附近的東南方岸邊召喚它。在那裡你可以找到很特別的煙花束發射器...$b$b在發射器那裡使用你的煙花，年獸的爪牙就會出現。發射更多，大約三打的煙花，或者朝它的爪牙投擲伊露恩的蠟燭，年獸就會醒來。', `MaleText_loc7`='Augurio descansa en las profundidades del Lago Elune''ara pero puede ser invocado desde la orilla sudeste, cerca del Túmulo de Tempestira. Allí encontrarás unos lanzacohetes muy especiales...$B$BLanza varios de tus cohetes y aparecerán los esbirros de Augurio. Si continúas lanzando cohetes, unas tres docenas aproximadamente, o si enciendes velas de Elune ante sus esbirros, pronto se despertará.' WHERE `ID`=11690;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엘룬의 양초를 좀 더 사고 싶습니다.', `MaleText_loc4`='我还想购买一根艾露恩的蜡烛。', `MaleText_loc5`='我想再買一個伊露恩的蠟燭。', `MaleText_loc7`='Deseo comprar otra vela de Elune.', `FemaleText_loc1`='엘룬의 양초를 좀 더 사고 싶습니다.', `FemaleText_loc4`='我还想购买一根艾露恩的蜡烛。', `FemaleText_loc5`='我想再買一個伊露恩的蠟燭。', `FemaleText_loc7`='Deseo comprar otra vela de Elune.' WHERE `ID`=11691;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 형제들에게 힘을 나누어 줍니다.', `MaleText_loc4`='%s与他的同伴分享自己的能量。', `MaleText_loc5`='%s與他的盟友分享他的權力。', `MaleText_loc7`='%s comparte sus poderes con sus hermanos.', `FemaleText_loc1`='%s|1이;가; 형제들에게 힘을 나누어 줍니다.', `FemaleText_loc4`='%s与他的同伴分享自己的能量。', `FemaleText_loc5`='%s與他的盟友分享他的權力。', `FemaleText_loc7`='%s comparte sus poderes con sus hermanos.' WHERE `ID`=11692;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 분노에 휩싸입니다!', `MaleText_loc4`='%s变得狂怒了！', `MaleText_loc5`='%s進入狂怒狀態!', `MaleText_loc7`='%s se pone frenético.', `FemaleText_loc1`='%s|1이;가; 분노에 휩싸입니다!', `FemaleText_loc4`='%s变得狂怒了！', `FemaleText_loc5`='%s進入狂怒狀態!', `FemaleText_loc7`='%s se pone frenético.' WHERE `ID`=11693;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 광폭해집니다!', `MaleText_loc4`='%s变得狂暴了！', `MaleText_loc5`='%s進入狂暴狀態!', `MaleText_loc7`='¡%s monta en cólera!' WHERE `ID`=11694;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 단단하게 얼었습니다!', `MaleText_loc4`='%s变成了坚硬的固体！', `MaleText_loc5`='%s變成冰凍的固體!', `MaleText_loc7`='¡%s no se puede mover!' WHERE `ID`=11695;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 우리는 과거의 영광을 되찾고자 오랫동안 최선을 다해왔소. 쿠엘탈라스를 침략하여 더럽힌 자들에 대한 긴장의 끈을 한시라도 늦추어서는 아니 되오. 놈들을 몰아내기 전까지 우리에게 휴식이란 없소이다.$B$B그 무엇도 신도레이의 길을 막을 수는 없소!', `MaleText_loc4`='多年来我们为了保护我们的领土艰苦地战斗着，期盼恢复它往日的荣耀，$c。无论什么时候，我们都会继续警惕着那些侵略和污染奎尔萨拉斯的家伙。我们不会休息，直到他们被彻底赶出我们的视野。$B$B辛多雷是不可战胜的！', `MaleText_loc5`='我們歷盡千辛萬苦終於讓家園重返以往的榮耀，$c。但是我們仍然要對那些入侵並敗壞奎爾薩拉斯的人保持警惕。不把他們處理掉決不善罷甘休。$B$B不要讓任何人阻擋辛多雷!', `MaleText_loc7`='Hemos trabajado muy duro para ver cómo nuestras tierras volvían a su antigua gloria, $c. Debemos estar siempre alerta contra aquellos que han invadido y profanado Quel''Thalas. No descansaremos hasta que estén fuera de nuestra vista.$B$B¡Que nadie ose interponerse en el camino de los sin''dorei!' WHERE `ID`=11696;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='완전히 엉망이에요. 모두 제 잘못입니다! 기회가 있을 때 철수하라는 경고를 받았지만 그 말을 듣지 않았습니다.$B$B이제 어쩌면 좋을까요? 그 망할 블러드 엘프, 버림받은 자들이 내 마법 물품을 가져가서 먹어버린 것 같아요. 되찾을 방도가 없답니다. 나머지 물건은 성난비늘 멀록들이 한밤중에 약탈해 갔어요! 선원들은 배까지 버렸지 뭡니까!$B$B정말 주저앉아서 엉엉 울고라도 싶은 심정이랍니다.', `FemaleText_loc4`='一切都糟透了，$c，这一切都是我的错！当时间还不算晚的时候，我被告知最好立即离开码头，但是我听了吗？没有。$B$B现在我要干什么？那些病态的失心者偷走了我的魔法货物，我想他们已经把这些东西都吃了。我很确信这意味着它们再也没法拿回来了。而暗鳞鱼人在一个死寂的夜晚抢夺了我剩余的货物！另外，对于我这样正直的商人来说，雪上加霜的事情是，我的船员都逃走了！$B$B我真是欲哭无泪。', `FemaleText_loc5`='真是一團亂，$c，而這全都是我的錯!辛多雷早就警告我快點離開碼頭，但我聽進去了嗎?沒有。$B$B我現在該怎麼辦?那些令人作嘔的血精靈，鄙惡者，偷走了我的魔法物品，大概還把它們都吃掉了我想。我很確定那些東西是找不回來了。而厲鱗魚人在深夜將我剩下的東西搶奪一空!此外，為了趁虛而入，我的船員們還棄了船!$B$B我要哭了。', `FemaleText_loc7`='Es un caos, $c, y es todo por mi culpa. Me dijeron que saliera del muelle mientras tenía tiempo, pero no hice caso. No.$B$B¿Qué voy a hacer ahora? Esos malditos elfos de sangre, los desdichados, se han largado con todo mi material mágico y se lo han comido, creo. Estoy segura de que no lo recuperaré nunca. ¡Y los múrlocs Malaescama me robaron lo poco que quedaba en medio de la noche! Para rematar la faena, mi tripulación ha abandonado el barco.$B$BCreo que voy a llorar.' WHERE `ID`=11697;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, $c님! 이것이 우리가 사랑하는 쿠엘탈라스의 운명이라면 정말 어려운 시기입니다.', `FemaleText_loc4`='你好，$c。现在是最艰难的时刻，我们心爱的奎尔萨拉斯居然变成了这个样子。', `FemaleText_loc5`='嗨，$c。如果這就是我們親愛的奎爾薩拉斯，那這真是一段艱難的時期。', `FemaleText_loc7`='Hola, $c. Estamos en tiempos verdaderamente preocupantes si esto es en lo que se va a convertir nuestra amada Quel''Thalas.' WHERE `ID`=11698;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방 중앙에 떠 있는 거대한 눈이 당신을 노려보기 시작합니다. 지금 당신은 고대의 신 앞에 서 있는 것입니다.', `MaleText_loc4`='漂浮在这间屋子中的巨大眼球在盯着你看。你正站在一个神灵的面前。', `MaleText_loc5`='漂浮在這間屋子中的巨大眼球在盯著你看。你就站在神的面前。', `MaleText_loc7`='El enorme ojo que flota en el centro de la cámara dirige su mirada hacia ti. Te encuentras ante un dios.' WHERE `ID`=11700;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='평생 눈엣가시 같은 버림받은 자들! 신변의 안전만 보장된다면 욕망을 채우기 위해 불안정한 마력이 깃든 재료를 서슴지 않고 사용하는 놈들입니다. 우리를 상대로 말도 안 되는 실험을 할 어리석은 계획까지 세우고 있단 말입니다.', `MaleText_loc4`='$n，失心者是非常棘手的麻烦。在他们通过汲取不稳定的奥术能量满足自己对魔法的渴求、解决了嗜魔之瘾后，他们便开始挖空心思地计划对我们发动攻击，不过这帮渣滓的作战方案还真是……', `MaleText_loc5`='鄙惡者一直是我方的眼中釘，$n。他們不是在汲取不穩定的秘法能源以滿足其渴望，就是在計畫著打垮我們美好的家園。', `MaleText_loc7`='Los desdichados son una espina que tengo clavada, $n. Cuando no son un peligro para ellos mismos porque explotan fuentes Arcanas inestables para satisfacer sus antojos, traman ardides alocados contra nuestra respetable sociedad.' WHERE `ID`=11701;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오직 피와 살... 필멸의 존재들이란 이처럼 쉬운 먹잇감들이지.', `MaleText_loc4`='只不过是血肉之躯，凡人真是太脆弱了……', `MaleText_loc5`='只有肉跟骨頭。人類真容易淪為犧牲者...', `MaleText_loc7`='Solo carne y hueso. Los mortales sois una presa fácil...' WHERE `ID`=11702;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 뼈...', `MaleText_loc4`='血肉之躯。', `MaleText_loc5`='以及骨頭。', `MaleText_loc7`='y hueso.' WHERE `ID`=11703;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필멸의 존재들이란...', `MaleText_loc4`='凡人……', `MaleText_loc5`='凡人是...', `MaleText_loc7`='Los mortales sois...' WHERE `ID`=11704;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 쉬운 사냥감이야.', `MaleText_loc4`='真是太脆弱了。', `MaleText_loc5`='相當容易祈禱。', `MaleText_loc7`='una presa demasiado fácil.' WHERE `ID`=11705;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 모두 예의를 갖추도록. 손님맞이는 제대로 해야 하는 법이지!', `MaleText_loc4`='你的风度哪去了，兄弟？让我们欢迎这些客人吧。', `MaleText_loc5`='注意你的禮貌，兄弟。 讓我們好好地歡迎我們的客人。', `MaleText_loc7`='¿Dónde están tus modales, hermano? Recibamos a nuestros invitados como se merecen.' WHERE `ID`=11706;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고통을 맛보리라...', `MaleText_loc4`='你们会很痛苦……', `MaleText_loc5`='那會令人相當痛苦...', `MaleText_loc7`='Habrá sufrimiento...' WHERE `ID`=11707;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무나 큰 아픔을...', `MaleText_loc4`='哦，非常痛苦……', `MaleText_loc5`='哦...好痛苦啊...', `MaleText_loc7`='Mucho sufrimiento...' WHERE `ID`=11708;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오너라, 미천한 족속들이여!', `MaleText_loc4`='来吧，小家伙们。', `MaleText_loc5`='來吧，小子。', `MaleText_loc7`='Venid, pequeñajos.' WHERE `ID`=11709;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼의 향연이 시작되리라...', `MaleText_loc4`='灵魂的盛宴即将开始……', `MaleText_loc5`='靈魂饗宴即將展開...', `MaleText_loc7`='Comienza el festín de almas...' WHERE `ID`=11710;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='', `MaleText_loc4`='', `MaleText_loc5`='', `MaleText_loc7`='' WHERE `ID`=11711;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='문제가 해결되었군... 이제 그 누구도 나 같은 실수를 반복하지 않을 것이오!', `MaleText_loc4`='谢天谢地……现在没有人会重复我的错误了！', `MaleText_loc5`='做的好...現在不會再有人重犯我的錯誤了!', `MaleText_loc7`='Por fin... ¡ahora nadie podrá repetir mis errores!' WHERE `ID`=11713;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로랄탈리스가 무사하기만을 바라오. 내가 몸소 더스크위더 첨탑에 가야하는 것일까? 아니 진작에 그렇게 해야 하지 않았을까라는 의구심이 드는구려.', `MaleText_loc4`='我希望罗拉塔利斯是对的，$c。也许我应该亲自去达斯维瑟之塔？也许我当初就应该立即赶去那里？', `MaleText_loc5`='我希望羅勒塞拉斯是對的，$c。或許我該獨自前往暮萎尖塔?或許我一開始就該這麼做了?', `MaleText_loc7`='Espero que Loralthalis esté bien, $c. Quizás debería subir a Aguja Ocaso Marchito yo mismo. ¿Quizás es lo que debería haber hecho en primer lugar?' WHERE `ID`=11714;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 자신이 저지른 실수를 만회하지 않는 한 일평생을 수치스럽게 살아갈 수밖에 없소.', `MaleText_loc4`='$c，一个人在纠正了他所犯下的错误之前只能生活在羞耻中。', `MaleText_loc5`='一個人在採取行動彌補他犯下的錯之前，就只能帶著恥辱苟延殘喘，$c。', `MaleText_loc7`='Un hombre solo puede vivir consigo y su vergüenza durante tanto tiempo, $c, antes de que tenga que actuar para deshacer los errores que ha cometido.' WHERE `ID`=11715;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 이 상황은 난장판이라는 말이 딱 어울리겠군요! 이 생물들은 도대체 어디서 튀어나온 거죠? 아무런 통제도 받지 않고 온 사방을 휘젓고 다니잖아요! 그리고 마법학자와 제자들은 어디로 도망간 거죠? "빌리덴, 같이 가실래요?"라는 말도 없이 나만 남겨두고 모두 없어지다니...$B$B이런 뻔뻔한 친구들 같으니라고!', `MaleText_loc4`='混乱，一片混乱！这些生物满地都是，失控地跑来跑去！还有魔导师和他的学徒们都去哪里了，逃走了？把我单独留在这里，甚至连一句“你好啊维林森，你愿意一起走吗？”都没留下。$B$B胆小鬼！', `MaleText_loc5`='一團糟，這就是怎麼回事!這些生物全都不知道從哪冒出來，然後就開始失去控制!!而博學者和他的學徒跑到哪去了呢?只把我留在這裡，連一句「嘿，威利坦要不要一起走?」都沒有。$B$B真是大膽!', `MaleText_loc7`='¡Un desastre, eso es lo que es! ¡Todas esas criaturas han aparecido de la nada y corretean por todas partes, fuera de control! Y, ¿dónde se han metido el magister y sus aprendices? Me dejan aquí solo sin siquiera decir "Hola, Wyllithen, ¿te quieres venir?"$B$B¡Menuda cara!' WHERE `ID`=11716;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='케이다니스 씨, 당신이 지키고 있는 이 비전 성소들은 상당히... 흥미롭소이다. 유용한 정보 감사드리오.', `MaleText_loc4`='你的这些奥术圣殿真的……很有意思，凯丹尼斯先生。我对你今天给予我的信息表示感激。', `MaleText_loc5`='你的這些秘法聖所相當...有意思凱丹尼斯先生。謝謝你今天提供給我的資訊。', `MaleText_loc7`='Estos sagrarios arcanos suyos son bastante... interesantes, Sr. Caidanis. Agradezco la información que me ha proporcionado hoy.' WHERE `ID`=11717;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='별말씀을요, 앤빌워드 씨! 우리 블러드 엘프의 일에 이렇게 깊은 관심을 보여주시다니... 정말 뜻밖이로군요.', `MaleText_loc4`='我很荣幸，安威瓦尔德先生。我必须得说，你对我们的工作表现出来的兴趣……真令人意想不到。', `MaleText_loc5`='這是我的榮幸，安維爾伍德先生。您對我們運作的熱情關注是...令人意想不到的。', `MaleText_loc7`='Ha sido un placer, Sr. Guardayunque. Debo decir que su interés entusiasta en nuestras operaciones es de lo más... inesperado.' WHERE `ID`=11718;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성벽이 무너졌다!', `MaleText_loc4`='城墙被攻陷了！', `MaleText_loc5`='牆壁遭到破壞!', `MaleText_loc7`='¡Han traspasado los muros!' WHERE `ID`=11720;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='공격! 놈들이 문으로 가지 못하게 해라!', `FemaleText_loc4`='进攻！不要让他们接近大门！', `FemaleText_loc5`='攻擊!不准他們接近大門!', `FemaleText_loc7`='¡Atacad! ¡No les dejéis alcanzar las puertas!' WHERE `ID`=11721;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일반 텍스트 2!', `MaleText_loc4`='Generic Text2', `MaleText_loc5`='Generic Text2!', `MaleText_loc7`='Texto genérico 2', `FemaleText_loc1`='일반 텍스트 2', `FemaleText_loc4`='Generic Text2', `FemaleText_loc5`='Generic Text2', `FemaleText_loc7`='Texto genérico 2' WHERE `ID`=11722;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 사랑의 징표를 드리고 싶습니다.', `MaleText_loc4`='来，我送你一件象征我的爱情的小东西。', `MaleText_loc5`='拿著，我想送你這份象徵愛的禮物。', `MaleText_loc7`='Toma, me gustaría darte esta prueba de amor.', `FemaleText_loc1`='제 사랑의 징표를 드리고 싶어요.', `FemaleText_loc4`='来，我送你一件象征我的爱情的小东西。', `FemaleText_loc5`='拿著，我想送你這份象徵愛的禮物。', `FemaleText_loc7`='Toma, me gustaría darte esta prueba de amor.' WHERE `ID`=11723;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 모두 전쟁에만 너무 몰두해 있어서, 사랑에 대해서는 잊고 있었던 것 같습니다.', `MaleText_loc4`='战争压得我们喘不过气来，让我们忘了给爱情一点空间。', `MaleText_loc5`='戰爭讓我們飽受催殘。我們也忘了要花時間去愛。', `MaleText_loc7`='Hemos estado tan concentrados en la guerra que muchos de nosotros olvidamos dedicarle tiempo al amor.', `FemaleText_loc1`='우리 모두 전쟁에만 너무 몰두해 있어서, 사랑에 대해서는 잊고 있었던 것 같아요.', `FemaleText_loc4`='战争压得我们喘不过气来，让我们忘了给爱情一点空间。', `FemaleText_loc5`='戰爭讓我們飽受催殘。我們也忘了要花時間去愛。', `FemaleText_loc7`='Hemos estado tan concentrados en la guerra que muchos de nosotros olvidamos dedicarle tiempo al amor.' WHERE `ID`=11724;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 상자는 뭐죠?', `MaleText_loc4`='这些箱子是干什么用的？', `MaleText_loc5`='這些木箱是做什麼用的啊?', `MaleText_loc7`='¿Para qué son esas cajas?', `FemaleText_loc1`='저 상자는 뭐예요?', `FemaleText_loc4`='这些箱子是干什么用的？', `FemaleText_loc5`='這些木箱是做什麼用的啊?', `FemaleText_loc7`='¿Para qué son esas cajas?' WHERE `ID`=11725;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 도시에서 이번에 새로 나온 은은한 향수와 매혹적인 향수를 주문했습니다. 포장지를 뜯어서 확인해 본 다음 그것을 판매할 계획입니다.', `MaleText_loc4`='我从城里订购了一些新的香水，等我把它们放好之后，你就可以来找我购买啦！', `MaleText_loc5`='我從城裡訂了一些新的香水和古龍水。等我卸貨，盤點一下就要做生意了。', `MaleText_loc7`='Me han enviado de la ciudad el pedido de nuevos perfumes y colonias que había encargado. Una vez desempaquetados, vuelve por aquí pues ya los tendré a la venta.', `FemaleText_loc1`='저는 도시에서 이번에 새로 나온 은은한 향수와 매혹적인 향수를 주문했습니다. 포장지를 뜯어서 확인해 본 다음 그것을 판매할 계획입니다.', `FemaleText_loc4`='我从城里订购了一些新的香水，等我把它们放好之后，你就可以来找我购买啦！', `FemaleText_loc5`='我從城裡訂了一些新的香水和古龍水。等我卸貨，盤點一下就要做生意了。', `FemaleText_loc7`='Me han enviado de la ciudad el pedido de nuevos perfumes y colonias que había encargado. Una vez desempaquetados, vuelve por aquí pues ya los tendré a la venta.' WHERE `ID`=11726;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희는 이곳의 존재가 아니구나! 고대 정령들이여, 일어나서 침입자들을 해치워라!', `MaleText_loc4`='你并不属于这里！远古的守卫，醒来吧！消灭入侵者！', `MaleText_loc5`='你不屬於這裡!上古之人，為對抗這些入侵者而起!', `MaleText_loc7`='¡Este no es sitio para ti! ¡Ancestros, alzaos contra los intrusos!' WHERE `ID`=11727;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말 굉장한 싸움이었어요. 잠깐 숨 좀 돌리죠.', `FemaleText_loc4`='真是一场恶战。让我们休息一下……', `FemaleText_loc5`='那真是場激烈的打鬥。讓我們先喘口氣。', `FemaleText_loc7`='Menuda pelea... Necesitamos un momento para recuperar el aliento.' WHERE `ID`=11728;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이보시오, $C님! 포도주에 꽤 일가견이 있어 보입니다만, 부탁할 일이 좀 있습니다. 솔깃할 만한 제안일 겁니다. 앗... 아닙니다, 신경 쓰지 마세요!', `MaleText_loc4`='你好，$g先生:小姐;。你看起来就像是个对美酒有着独特品味和见解的$c。我想让你帮个忙，并提出一个你无法拒绝的建议……忘了它！', `MaleText_loc5`='嘿，$g先生:小姐;。看樣子你是個對品酒有相當鑑賞力的$C。我想請你幫個忙，給你的報酬一定會好的讓你無法抗拒...算了，那真是不錯的酬勞!', `MaleText_loc7`='¡Eh! Tienes pinta de ser $gun:una:c; $c con un paladar muy exigente para los vinos. Tengo que pedirte un favor y creo que no podrás rechazar la oferta que te voy a hacer... ¡Olvídalo!' WHERE `ID`=11729;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 쳐다보는 거요? 드워프 처음 보나?$B$B문제를 일으키지 않고 싶다면 가던 길이나 가는 게 좋을 거요.', `MaleText_loc4`='你在看什么，$g伙计:小姑娘;？没见过矮人吗？$B$B如果你不想惹麻烦的话，那么你最好走开。', `MaleText_loc5`='你在看什麼，$g小夥子:小姑娘;?沒看過矮人嗎?$B$B你最好快走免得惹麻煩。', `MaleText_loc7`='¿Qué estás mirando, $gmuchacho:muchacha;? ¿Es que nunca has visto un enano?$B$BSerá mejor que te pongas en camino si no quieres tener problemas.' WHERE `ID`=11730;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠시만 얘기를 나누고 싶습니다.', `MaleText_loc4`='我需要占用一点你的时间，先生。', `MaleText_loc5`='請留步，先生。', `MaleText_loc7`='Necesito un momento de su tiempo, señor.', `FemaleText_loc1`='잠시만 얘기를 나누고 싶어요.', `FemaleText_loc4`='我需要占用一点你的时间，先生。', `FemaleText_loc5`='請留步，先生。', `FemaleText_loc7`='Necesito un momento de su tiempo, señor.' WHERE `ID`=11731;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 당신이 바로 나에게 영원노래 숲을 안내하는 임무를 맡은 자로군. 여기까지 오는 동안 귀한 시간을 허비하지는 않았소?$B$B좋아, 출발하지. 일 분도 더 허비해서는 안 되겠어.', `MaleText_loc4`='啊，你肯定是那个被派来带我参观永歌森林的$g小伙子:小姑娘;。到这里来花了你不少时间吧？$B$B很好，出发吧。我们不要再浪费时间了。', `MaleText_loc5`='啊，你一定就是負責帶我在永歌森林附近逛逛的$g小夥子:小姑娘;。花了不少時間來這裡，是吧?$B$B很好，我們走吧。別再浪費時間了。', `MaleText_loc7`='Ah, debes de ser $gel muchacho:la muchacha; $gdesignado:designada; para mostrarme los alrededores del bosque Canción Eterna. Te llevó tu tiempo llegar hasta aquí, ¿no es así?$B$BMuy bien, vámonos. No perdamos ni un minuto más.' WHERE `ID`=11732;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼요. 물론입니다. 바로 이 건물 안에 당신에게 보여드릴 것이 있습니다, 앤빌워드 씨.', `MaleText_loc4`='啊……是的，当然。不过首先我在这间房子里准备了一些东西要让你看看，安威瓦尔德先生。', `MaleText_loc5`='什麼...喔，當然。我要給你看的東西就在這棟大樓裡，安維爾伍德先生。', `MaleText_loc7`='Vaya... sí, por supuesto. Tengo algo que mostrarle dentro de ese edificio, Prospector Guardayunque.', `FemaleText_loc1`='그럼요. 물론이죠. 바로 이 건물 안에 당신에게 보여드릴 것이 있어요, 앤빌워드 씨.', `FemaleText_loc4`='啊……是的，当然。不过首先我在这间房子里准备了一些东西要让你看看，安威瓦尔德先生。', `FemaleText_loc5`='什麼...喔，當然。我要給你看的東西就在這棟大樓裡，安維爾伍德先生。', `FemaleText_loc7`='Vaya... sí, por supuesto. Tengo algo que mostrarle dentro de ese edificio, Prospector Guardayunque.' WHERE `ID`=11733;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아. 뭘 보여준다는 건지 확인해 보자고.', `MaleText_loc4`='好吧。让我们看看你说的是什么，$n。', `MaleText_loc5`='很好。來看看你要給我看的東西，$n。', `MaleText_loc7`='Muy bien, veamos lo que tienes que mostrarme, $n.' WHERE `ID`=11734;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$r, 이건 무슨 수작이지? 경고하는 데 날 건드릴 작정이라면 다시 한번 생각해 보는 게 좋을 거야. 난 그렇게 쉽게 쓰러질 드워프가 아니거든!', `MaleText_loc4`='这是什么诡计，$r？如果你想要偷袭我的话，就来试试看吧！', `MaleText_loc5`='這是什麼把戲，$r?如果你想伏擊我，我警告你我是不會輕易倒下的!', `MaleText_loc7`='¿Qué tipo de truco es este, $r? ¡Si intentas tenderme una emboscada, te advierto que no me hundiré en silencio!' WHERE `ID`=11735;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 모두 전쟁에만 너무 몰두해 있어서, 사랑에 대해서는 잊고 있었던 것 같습니다.', `MaleText_loc4`='战争压得我们喘不过气来，让我们忘了给爱情一点空间。', `MaleText_loc5`='戰爭讓我們飽受催殘。我們也忘了要花時間去愛。', `MaleText_loc7`='Hemos estado tan concentrados en la guerra que muchos de nosotros olvidamos dedicarle tiempo al amor.' WHERE `ID`=11736;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 모두 전쟁에만 너무 몰두해 있어서, 사랑이란 소중한 감정에 대해서는 잊고 있었던 것 같네요.', `FemaleText_loc4`='战争压得我们喘不过气来，让我们忘了给爱情一点空间。', `FemaleText_loc5`='戰爭讓我們飽受催殘。我們也忘了要花時間去愛。', `FemaleText_loc7`='Hemos estado tan concentrados en la guerra que muchos de nosotros olvidamos dedicarle tiempo al amor.' WHERE `ID`=11737;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 이미 사랑을 찾은 것 같군요. 제게 사랑의 징표를 주신다고 해도 좋은 선물은 안 드릴 거예요. 전 특별한 누군가를 기다리고 있거든요.', `MaleText_loc4`='我一看就知道，你已经找到了自己的真爱。你可以给我一件爱情信物，但我没什么可以给你的。我正在等待一个特殊的人……', `MaleText_loc5`='看來你已經找到真愛了。你可以給我一個愛之硬幣，但是我不會給你任何好東西。我在等待一個特別的人。', `MaleText_loc7`='Parece que ya has encontrado el amor. Puedes entregarme una prueba de amor pero yo no te daré nada a cambio. Estoy esperando a alguien especial.', `FemaleText_loc1`='당신은 이미 사랑을 찾은 것 같군요. 제게 사랑의 징표를 주신다고 해도 좋은 선물은 안 드릴 거예요. 전 특별한 누군가를 기다리고 있거든요.', `FemaleText_loc4`='我一看就知道，你已经找到了自己的真爱。你可以给我一件爱情信物，但我没什么可以给你的。我正在等待一个特殊的人……', `FemaleText_loc5`='看來你已經找到真愛了。你可以給我一個愛之硬幣，但是我不會給你任何好東西。我在等待一個特別的人。', `FemaleText_loc7`='Parece que ya has encontrado el amor. Puedes entregarme una prueba de amor pero yo no te daré nada a cambio. Estoy esperando a alguien especial.' WHERE `ID`=11738;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신은 이미 사랑을 찾은 것 같군요. 제게 사랑의 징표를 주신다고 해도 좋은 선물은 안 드릴 거예요. 전 특별한 누군가를 기다리고 있거든요.', `FemaleText_loc4`='我一看就知道，你已经找到了自己的真爱。你可以给我一件爱情信物，但我没什么可以给你的。我正在等待一个特殊的人……', `FemaleText_loc5`='看來你已經找到真愛了。你可以給我一個愛之硬幣，但是我不會給你任何好東西。我在等待一個特別的人。', `FemaleText_loc7`='Parece que ya has encontrado el amor. Puedes entregarme una prueba de amor pero yo no te daré nada a cambio. Estoy esperando a alguien especial.' WHERE `ID`=11739;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 이미 사랑을 찾은 것 같군요. 제게 사랑의 징표를 주신다고 해도 좋은 선물은 안 드릴 거예요. 전 특별한 누군가를 기다리고 있거든요.', `MaleText_loc4`='我一看就知道，你已经找到了自己的真爱。你可以给我一件爱情信物，但我没什么可以给你的。我正在等待一个特殊的人……', `MaleText_loc5`='看來你已經找到真愛了。你可以給我一個愛之硬幣，但是我不會給你任何好東西。我在等待一個特別的人。', `MaleText_loc7`='Parece que ya has encontrado el amor. Puedes entregarme una prueba de amor pero yo no te daré nada a cambio. Estoy esperando a alguien especial.' WHERE `ID`=11740;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요, $c님! 즐거운 표정으로 미루어 보니 월드 와이드 인비테이셔널에서 뭔가 좋은 소식을 들었나 본데 혹시 비밀 암호를 제게 일러주러 오신 건가요? 그러면 답례로 제가 돌보고 있는 어여쁜 아기 판다 한 마리를 드리겠어요.$B$B자, 준비가 되면 제 귀에 대고 살짝 말씀해 주세요.', `MaleText_loc4`='你好，$c。你是有什么关于邀请赛的好消息给我吗？既然你来了，那你肯定已经拿到了一段神秘兑换码。只要你把神秘兑换码报给我，我就送你一只可爱的小熊猫宠物。$B$B你有神秘兑换码么？', `MaleText_loc5`='你好，$c。我想你是來告訴我有關全球受邀典禮的好消息吧?如果沒錯，那你來這裡就是要告訴我驗證碼的。告訴我驗證碼之後，我將用心愛的一隻小熊貓跟你作交換。$B$B你在我耳邊小聲告訴我吧。', `MaleText_loc7`='Saludos, $c. Confío en que traigas buenas noticias en referencia al evento internacional exclusivo para invitados. Si así es, con certeza te habrán dado un código secreto que debes decirme. A cambio de tu código te regalaré uno de los ositos panda que tengo a mi cargo.$B$BSimplemente susúrramelo al oído cuando estés $glisto:lista;.', `FemaleText_loc1`='안녕하세요, $c님! 즐거운 표정으로 미루어 보니 월드 와이드 인비테이셔널에서 뭔가 좋은 소식을 들었나 본데 혹시 비밀 암호를 제게 일러주러 오신 건가요? 그러면 답례로 제가 돌보고 있는 어여쁜 아기 판다 한 마리를 드리겠어요.$B$B자, 준비가 되면 제 귀에 대고 살짝 말씀해 주세요.', `FemaleText_loc4`='你好，$c。你是有什么关于邀请赛的好消息给我吗？既然你来了，那你肯定已经拿到了一段神秘兑换码。只要你把神秘兑换码报给我，我就送你一只可爱的小熊猫宠物。$B$B你有神秘兑换码么？', `FemaleText_loc5`='你好，$c。我想你是來告訴我有關全球受邀典禮的好消息吧?如果沒錯，那你來這裡就是要告訴我驗證碼的。告訴我驗證碼之後，我將用心愛的一隻小熊貓跟你作交換。$B$B你在我耳邊小聲告訴我吧。', `FemaleText_loc7`='Saludos, $c. Confío en que traigas buenas noticias en referencia al evento internacional exclusivo para invitados. Si así es, con certeza te habrán dado un código secreto que debes decirme. A cambio de tu código te regalaré uno de los ositos panda que tengo a mi cargo.$B$BSimplemente susúrramelo al oído cuando estés $glisto:lista;.' WHERE `ID`=11741;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비밀 암호를 입력하고 제 아기 판다를 받고 싶습니다.', `MaleText_loc4`='我要输入神秘兑换码，领取我的熊猫宠物！', `MaleText_loc5`='我想偷偷告訴你驗證碼以領取我的寵物小熊貓寶寶。', `MaleText_loc7`='Me gustaría susurrar mi código secreto para obtener mi osito panda.', `FemaleText_loc1`='비밀 암호를 입력하고 제 아기 판다를 받고 싶어요.', `FemaleText_loc4`='我要输入神秘兑换码，领取我的熊猫宠物！', `FemaleText_loc5`='我想偷偷告訴你驗證碼以領取我的寵物小熊貓寶寶。', `FemaleText_loc7`='Me gustaría susurrar mi código secreto para obtener mi osito panda.' WHERE `ID`=11742;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 이미 사랑을 찾은 것 같군요. 제게 사랑의 징표를 주신다고 해도 좋은 선물은 안 드릴 거예요. 전 특별한 누군가를 기다리고 있거든요.', `MaleText_loc4`='我一看就知道，你已经找到了自己的真爱。你可以给我一件爱情信物，但我没什么可以给你的。我正在等待一个特殊的人……', `MaleText_loc5`='看來你已經找到真愛了。你可以給我一個愛之硬幣，但是我不會給你任何好東西。我在等待一個特別的人。', `MaleText_loc7`='Parece que ya has encontrado el amor. Puedes entregarme una prueba de amor pero yo no te daré nada a cambio. Estoy esperando a alguien especial.', `FemaleText_loc1`='당신은 이미 사랑을 찾은 것 같군요. 제게 사랑의 징표를 주신다고 해도 좋은 선물은 안 드릴 거예요. 전 특별한 누군가를 기다리고 있거든요.', `FemaleText_loc4`='我一看就知道，你已经找到了自己的真爱。你可以给我一件爱情信物，但我没什么可以给你的。我正在等待一个特殊的人……', `FemaleText_loc5`='看來你已經找到真愛了。你可以給我一個愛之硬幣，但是我不會給你任何好東西。我在等待一個特別的人。', `FemaleText_loc7`='Parece que ya has encontrado el amor. Puedes entregarme una prueba de amor pero yo no te daré nada a cambio. Estoy esperando a alguien especial.' WHERE `ID`=11743;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 이미 사랑을 찾은 것 같군요. 제게 사랑의 징표를 준다고 해도 좋은 선물은 주지 않을 겁니다. 전 특별한 누군가를 기다리고 있거든요.', `MaleText_loc4`='我一看就知道，你已经找到了自己的真爱。你可以给我一件爱情信物，但我没什么可以给你的。我正在等待一个特殊的人……', `MaleText_loc5`='看來你已經找到真愛了。你可以給我一個愛之硬幣，但是我不會給你任何好東西。我在等待一個特別的人。', `MaleText_loc7`='Parece que ya has encontrado el amor. Puedes entregarme una prueba de amor pero yo no te daré nada a cambio. Estoy esperando a alguien especial.' WHERE `ID`=11744;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 모두 전쟁에만 너무 몰두해 있어서, 사랑에 대해서는 잊고 있었던 것 같습니다.', `MaleText_loc4`='战争压得我们喘不过气来，让我们忘了给爱情一点空间。', `MaleText_loc5`='戰爭讓我們飽受催殘。我們也忘了要花時間去愛。', `MaleText_loc7`='Hemos estado tan concentrados en la guerra que muchos de nosotros olvidamos dedicarle tiempo al amor.' WHERE `ID`=11745;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 어떻게 된 일인지 모르겠네요. 지금 제 심장은 잘 달구어진 무쇠처럼 뜨거워요.', `FemaleText_loc4`='我不知道自己是怎么了，我的心就像新铸成的钢条一样炽热！', `FemaleText_loc5`='我不知道是什麼感覺侵襲著我。我的心感到一股如鋼鐵般的炙熱。', `FemaleText_loc7`='No sé lo que me ha pasado pero mi corazón está ardiendo como una pieza de acero recién forjada.' WHERE `ID`=11746;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 나한테 무슨 일이 생긴 건지 모르겠소. 지금 내 심장은 잘 달구어진 무쇠처럼 뜨겁소이다.', `MaleText_loc4`='我不知道自己是怎么了，我的心就像新铸成的钢条一样炽热！', `MaleText_loc5`='我不知道是什麼感覺侵襲著我。我的心感到一股如鋼鐵般的炙熱。', `MaleText_loc7`='No sé lo que me ha pasado pero mi corazón está ardiendo como una pieza de acero recién forjada.' WHERE `ID`=11747;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='기계와 함께한 시간이 너무 길어서인지, 진정한 마음에 대해서는 종종 잊어버리는 거 같네요.', `FemaleText_loc4`='你和机器共处的时间太久了，久到让你忘了真正的爱情。', `FemaleText_loc5`='你與機器為伍工作好長一段時間，有時候你都忘了如何與人相處。', `FemaleText_loc7`='Llevas tanto tiempo trabajando entre máquinas que en ocasiones te olvidas de la gente de verdad.' WHERE `ID`=11748;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기계와 함께한 시간이 너무 길어서인지, 진정한 마음에 대해서 종종 잊어버리는 거 같다니까.', `MaleText_loc4`='你和机器共处的时间太久了，久到让你忘了真正的爱情。', `MaleText_loc5`='你與機器為伍工作好長一段時間，有時候你都忘了如何與人相處。', `MaleText_loc7`='Llevas tanto tiempo trabajando entre máquinas que en ocasiones te olvidas de la gente de verdad.', `FemaleText_loc1`='기계와 함께한 시간이 너무 길어서인지, 진정한 마음에 대해서 종종 잊어버리는 거 같아요.', `FemaleText_loc4`='你和机器共处的时间太久了，久到让你忘了真正的爱情。', `FemaleText_loc5`='你與機器為伍工作好長一段時間，有時候你都忘了如何與人相處。', `FemaleText_loc7`='Llevas tanto tiempo trabajando entre máquinas que en ocasiones te olvidas de la gente de verdad.' WHERE `ID`=11749;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기계와 함께한 시간이 길어서인지, 진정한 마음에 대해서 가끔은 잊어버리는 거 같군요.', `MaleText_loc4`='你和机器共处的时间太久了，久到让你忘了真正的爱情。', `MaleText_loc5`='你與機器為伍工作好長一段時間，有時候你都忘了如何與人相處。', `MaleText_loc7`='Llevas tanto tiempo trabajando entre máquinas que en ocasiones te olvidas de la gente de verdad.' WHERE `ID`=11750;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저처럼 오래 살다 보면 사랑에 대해서는 까맣게 잊어버리기 쉽지요. 하지만, 언제 떠올려도 좋은 것이 바로 사랑이란 감정이에요.', `FemaleText_loc4`='如果你像我一样活了这么久的话，就会很容易把爱情的感觉遗忘。有人提起这种感觉来总是好事情。', `FemaleText_loc5`='當你像我一樣老的時候，就很容易忘了愛情這回事。不過，能被提醒是很幸福的。', `FemaleText_loc7`='Cuando has vivido tanto como yo, no es extraño olvidarse del amor durante años. Pero siempre es bueno recordarlo.' WHERE `ID`=11751;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나처럼 오래 살다 보면 사랑에 대해서는 까맣게 잊어버리기 쉽다오. 하지만, 언제 떠올려도 좋은 것이 바로 사랑이라는 감정이지.', `MaleText_loc4`='如果你像我一样活了这么久的话，就会很容易把爱情的感觉遗忘。有人提起这种感觉来总是好事情。', `MaleText_loc5`='當你像我一樣老的時候，就很容易忘了愛情這回事。不過，能被提醒是很幸福的。', `MaleText_loc7`='Cuando has vivido tanto como yo, no es extraño olvidarse del amor durante años. Pero siempre es bueno recordarlo.', `FemaleText_loc1`='저처럼 오래 살다 보면 사랑에 대해서는 까맣게 잊어버리기 쉽죠. 하지만, 언제 떠올려도 좋은 것이 바로 사랑이라는 감정입니다.', `FemaleText_loc4`='如果你像我一样活了这么久的话，就会很容易把爱情的感觉遗忘。有人提起这种感觉来总是好事情。', `FemaleText_loc5`='當你像我一樣老的時候，就很容易忘了愛情這回事。不過，能被提醒是很幸福的。', `FemaleText_loc7`='Cuando has vivido tanto como yo, no es extraño olvidarse del amor durante años. Pero siempre es bueno recordarlo.' WHERE `ID`=11752;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나처럼 오래 살다 보면 사랑에 대해서는 까맣게 잊어버리기 쉽지. 하지만, 언제 떠올려도 좋은 것이 바로 사랑이란 감정이오.', `MaleText_loc4`='如果你像我一样活了这么久的话，就会很容易把爱情的感觉遗忘。有人提起这种感觉来总是好事情。', `MaleText_loc5`='當你像我一樣老的時候，就很容易忘了愛情這回事。不過，能被提醒是很幸福的。', `MaleText_loc7`='Cuando has vivido tanto como yo, no es extraño olvidarse del amor durante años. Pero siempre es bueno recordarlo.' WHERE `ID`=11753;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='온 세상이 사랑으로 넘쳐 나는 것 같군. 나 홀로 외톨이가 되고 싶진 않다오.', `MaleText_loc4`='爱情随风飘过，希望我不会被它甩在后面。', `MaleText_loc5`='這就好像愛情飄浮在風中。我希望我不會被遺忘。', `MaleText_loc7`='Parece que el amor está en el aire. Espero que a mí también me toque.' WHERE `ID`=11754;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='온 세상이 사랑으로 넘쳐 나는 것 같군. 나 홀로 외톨이가 되고 싶진 않소.', `MaleText_loc4`='爱情随风飘过，希望我不会被它甩在后面。', `MaleText_loc5`='這就好像愛情飄浮在風中。我希望我不會被遺忘。', `MaleText_loc7`='Parece que el amor está en el aire. Espero que a mí también me toque.', `FemaleText_loc1`='온 세상이 사랑으로 넘쳐 나는 것 같군요. 나 홀로 외톨이가 되고 싶진 않답니다.', `FemaleText_loc4`='爱情随风飘过，希望我不会被它甩在后面。', `FemaleText_loc5`='這就好像愛情飄浮在風中。我希望我不會被遺忘。', `FemaleText_loc7`='Parece que el amor está en el aire. Espero que a mí también me toque.' WHERE `ID`=11755;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사실 나의 감정이란 것에 대해 생각해 본 지가 한참 되었지만, 지금은 가슴 속에서 뭔가 북받쳐 올라 주체할 길이 없군.', `MaleText_loc4`='很多年来我都没有再感觉过自己的内心，它现在仿佛又活了起来。', `MaleText_loc5`='我內心的思念經歷了好幾年，現在相思卻又不斷泛濫著。', `MaleText_loc7`='Hace muchos años que ya no pienso con el corazón pero empiezo a recordar lo que se siente.', `FemaleText_loc1`='사실 나의 감정이란 것에 대해 생각해 본 지가 한참 되었지만, 지금은 가슴 속에서 뭔가 북받쳐 올라 주체할 길이 없군.', `FemaleText_loc4`='很多年来我都没有再感觉过自己的内心，它现在仿佛又活了起来。', `FemaleText_loc5`='我內心的思念經歷了好幾年，現在相思卻又不斷泛濫著。', `FemaleText_loc7`='Hace muchos años que ya no pienso con el corazón pero empiezo a recordar lo que se siente.' WHERE `ID`=11756;
