UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나의 감정이란 것에 대해 생각해 본 지가 한참 되었지만, 지금은 가슴 속에서 뭔가 북받쳐 올라 주체할 길이 없군.', `MaleText_loc4`='很多年来我都没有再感觉过自己的内心，它现在仿佛又活了起来。', `MaleText_loc5`='我內心的思念經歷了好幾年，現在相思卻又不斷的泛濫著。', `MaleText_loc7`='Hace muchos años que ya no pienso con el corazón pero empiezo a recordar lo que se siente.' WHERE `ID`=11758;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 오크는 원래 사적인 감정을 잘 드러내지 않지만 이제는 아무도 자신의 감정을 숨기지 않지.', `MaleText_loc4`='我们兽人通常不喜欢过多谈论自己的感情问题，但今天可不是遮遮掩掩的时候。', `MaleText_loc5`='我們獸人通常都對愛情相當保密，但最近大家都不想再躲躲藏藏了。', `MaleText_loc7`='Por lo general, los orcos somos muy reservados pero últimamente nadie oculta ya sus sentimientos.', `FemaleText_loc1`='우리 오크는 원래 사적인 감정을 잘 드러내지 않지만 이제는 아무도 자신의 감정을 숨기지 않지.', `FemaleText_loc4`='我们兽人通常不喜欢过多谈论自己的感情问题，但今天可不是遮遮掩掩的时候。', `FemaleText_loc5`='我們獸人通常都對愛情相當保密，但最近大家都不想再躲躲藏藏了。', `FemaleText_loc7`='Por lo general, los orcos somos muy reservados pero últimamente nadie oculta ya sus sentimientos.' WHERE `ID`=11759;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='온 세상이 사랑으로 넘쳐나는 것 같군요. 나 홀로 외톨이가 되고 싶진 않아요.', `FemaleText_loc4`='爱情随风飘过，希望我不会被它甩在后面。', `FemaleText_loc5`='這就好像愛情飄浮在風中。我希望我不會被遺忘。', `FemaleText_loc7`='Parece que el amor está en el aire. Espero que a mí también me toque.' WHERE `ID`=11760;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 오크는 원래 사적인 감정을 잘 드러내지 않지만 이제는 아무도 자신의 감정을 숨기지 않네.', `FemaleText_loc4`='我们兽人通常不喜欢过多谈论自己的感情问题，但今天可不是遮遮掩掩的时候。', `FemaleText_loc5`='我們獸人通常都對愛情相當保密，但最近大家都不想再躲躲藏藏了。', `FemaleText_loc7`='Por lo general, los orcos somos muy reservados pero últimamente nadie oculta ya sus sentimientos.' WHERE `ID`=11761;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 오크들은 원래 사적인 감정을 잘 드러내지 않지만 이제는 아무도 자신의 감정을 숨기지 않는다오.', `MaleText_loc4`='我们兽人通常不喜欢过多谈论自己的感情问题，但今天可不是遮遮掩掩的时候。', `MaleText_loc5`='我們獸人通常都對愛情相當保密，但最近大家都不想再躲躲藏藏了。', `MaleText_loc7`='Por lo general, los orcos somos muy reservados pero últimamente nadie oculta ya sus sentimientos.' WHERE `ID`=11762;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기나긴 전쟁이 끝나고 이제 모두 사랑에 빠질 시간이오!', `MaleText_loc4`='无尽的战斗之后，人人都坠入了爱河！', `MaleText_loc5`='經歷這些年來的戰鬥後，現在所有人都已陷入愛河!', `MaleText_loc7`='¡Después de tantos años de enfrentamientos ya nadie se enamora!' WHERE `ID`=11763;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 전쟁의 세월이 지나면 우리 모두 사랑에 빠지게 될 거요!', `MaleText_loc4`='无尽的战斗之后，人人都坠入了爱河！', `MaleText_loc5`='經歷這些年來的戰鬥後，現在所有人都已陷入愛河!', `MaleText_loc7`='¡Después de tantos años de enfrentamientos ya nadie se enamora!', `FemaleText_loc1`='이 전쟁의 세월이 지나면 우리 모두 사랑에 빠지게 될 거예요!', `FemaleText_loc4`='无尽的战斗之后，人人都坠入了爱河！', `FemaleText_loc5`='經歷這些年來的戰鬥後，現在所有人都已陷入愛河!', `FemaleText_loc7`='¡Después de tantos años de enfrentamientos ya nadie se enamora!' WHERE `ID`=11764;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비밀 암호를 입력하고 제 멀록을 받고 싶습니다.', `MaleText_loc4`='我要输入神秘兑换码，领取我的小鱼人宠物！', `MaleText_loc5`='我想要輸入驗證碼以領取我的魚人寵物。', `MaleText_loc7`='Me gustaría introducir el código secreto para obtener mi múrloc.', `FemaleText_loc1`='비밀 암호를 입력하고 제 멀록을 받고 싶어요.', `FemaleText_loc4`='我要输入神秘兑换码，领取我的小鱼人宠物！', `FemaleText_loc5`='我想要輸入驗證碼以領取我的魚人寵物。', `FemaleText_loc7`='Me gustaría introducir el código secreto para obtener mi múrloc.' WHERE `ID`=11765;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요! 당신 낯이 좀 익은데... 우리 언제 만난 적이 있나요?$B$B그랬다면 분명 비밀 암호를 받으셨을 거예요. 그 코드를 알려 주시면 좋은 선물을 드리겠습니다.', `MaleText_loc4`='你好啊，$c。你看起来很眼熟……我们见过面吗？$B$B如果是的话，那么你肯定已经拿到一段神秘兑换码了。把神秘兑换码告诉我，我就给你一份特殊的奖品！', `MaleText_loc5`='嗨，$c。你好眼熟...我們以前有見過面嗎?$B$B如果我們見過面，那麼...你一定有一組驗證碼吧。告訴我你的驗證碼，我就會給你一份禮物!', `MaleText_loc7`='¡Hola! Me suena tu cara... ¿nos hemos visto antes?$B$BSi es así, seguro que alguien te ha dado un código secreto. ¡Dime tu código y te daré un regalo!', `FemaleText_loc1`='안녕하세요! 당신 낯이 좀 익은데... 우리 언제 만난 적이 있나요?$B$B그랬다면 분명 비밀 암호를 받으셨을 거예요. 그 코드를 알려 주시면 좋은 선물을 드릴게요.', `FemaleText_loc4`='你好啊，$c。你看起来很眼熟……我们见过面吗？$B$B如果是的话，那么你肯定已经拿到一段神秘兑换码了。把神秘兑换码告诉我，我就给你一份特殊的奖品！', `FemaleText_loc5`='嗨，$c。你好眼熟...我們以前有見過面嗎?$B$B如果我們見過面，那麼...你一定有一組驗證碼吧。告訴我你的驗證碼，我就會給你一份禮物!', `FemaleText_loc7`='Hola, $c. Me suena tu cara... ¿nos hemos visto antes?$B$BSi es así, seguro que alguien te ha dado un código secreto. ¡Dime tu código y te daré un regalo!' WHERE `ID`=11767;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비록 내가 그 마음을 직접 느낄 수는 없지만 분명 상처 받았다는 것을 알 수 있소.', `MaleText_loc4`='虽然这不是我的心，但它同样会破碎。', `MaleText_loc5`='不能因為那不是我的心，就覺得它不會心碎。', `MaleText_loc7`='Que no sea mi corazón no significa que no pueda estar roto.', `FemaleText_loc1`='비록 내가 그 마음을 직접 느낄 수는 없지만 분명 상처 받았다는 것을 알 수 있소.', `FemaleText_loc4`='虽然这不是我的心，但它同样会破碎。', `FemaleText_loc5`='不能因為那不是我的心，就覺得它不會心碎。', `FemaleText_loc7`='Que no sea mi corazón no significa que no pueda estar roto.' WHERE `ID`=11768;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금까지는 관대한 아량을 베풀었지만 이젠 네놈이 성가시구나. 나의 위대한 힘을 보여주마. 절망을 맛보거라!', `MaleText_loc4`='我一直没把你们当回事，但现在你们已经激怒了我！感受我的力量，陷入绝望的深渊吧！', `MaleText_loc5`='我一直以來跟你相處的都還不錯，但現在你覺得我煩了。你見證過我的厲害，而今卻感到絕望!', `MaleText_loc7`='Hasta ahora te he tratado bien pero empiezo a aburrirme. ¡Presencia la magnificencia de mi poder!' WHERE `ID`=11769;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또다시 죽을 수는 없다! 그것도 너 같은 놈에게!', `MaleText_loc4`='我不会再次死去！我不会被你们这些蝼蚁打败！', `MaleText_loc5`='我不會再死一次了!也不會跟你一樣!', `MaleText_loc7`='¡No moriré otra vez! ¡¡No a manos de alguien como tú!!' WHERE `ID`=11770;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='디버그 메시지, 텔린이 소환되었습니다.', `MaleText_loc4`='调试信息，Thelrin已经被召唤出来了。', `MaleText_loc5`='Debug message, Thelrin has been summoned.', `MaleText_loc7`='Mensaje de debug, se ha invocado a Thelrin.' WHERE `ID`=11771;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 보여요? 아무도 날 볼 수 없었는데! 내가 여기서 얼마나 외로웠는지 모르실 거예요. 마침내 말동무가 생기다니 얼마나 즐거운지 몰라요!$B$B나의 옛 용병군단 중 살아남은 누군가가 보냈겠죠. 맞죠? 당연히 맞겠죠!$B$B새로 생긴 말동무와 많은 대화를 나누고 싶지만 어서 이 사태부터 바로잡아야 해요. 군주 발타라크에게 그의 영혼을 돌려주려면 우린 할 일이 너무 많아요!', `MaleText_loc4`='你能看见我？你知道我一个人在这里游来荡去被忽视有多久了吗？就是没有没有人能看见我。能有人陪我说话真好！$B$B啊，你一定是我以前待过的那个雇佣兵团里的生还者派来的，我说的对不对？显然就对呀！$B$B好了好了，不多寒暄了，要想把灵魂还给瓦塔拉克公爵，并让一切纳入正轨，还有许多事情要做呢！', `MaleText_loc5`='你能看到我?你知道就因為沒人能看到我，我在這上頭被忽略得有多慘嗎?有人跟我講話真是太開心了!$B$B啊，你一定是被我以前傭兵公司還活著的成員派來的，我說對了嗎?我當然對啊!$B$B不過不要再閒話家常了，如果你要把事情做好並交回瓦薩拉克領主的靈魂，那還有很多工作要做!', `MaleText_loc7`='¿Puedes verme? ¿Sabes lo ignorado que me siento debido a que nadie puede verme? ¡Es alentador tener por fin a alguien con quien hablar!$B$BAsí que supongo que te ha enviado algún miembro de mi antigua compañía de mercenarios que todavía permanece con vida, ¿tengo razón? ¡Pues claro que la tengo!$B$BPero basta ya de tanta cháchara. Nos queda mucho trabajo por hacer si quieres arreglar la situación y devolverle a Lord Valthalak su espíritu.' WHERE `ID`=11772;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='군주 발타라크의 아뮬렛을 잃어버렸습니다!', `MaleText_loc4`='我把瓦塔拉克公爵的饰品弄丢了！', `MaleText_loc5`='我遺失了瓦薩拉克領主護符!', `MaleText_loc7`='¡He perdido el amuleto de Lord Valthalak!', `FemaleText_loc1`='군주 발타라크의 아뮬렛을 잃어버렸어요!', `FemaleText_loc4`='我把瓦塔拉克公爵的饰品弄丢了！', `FemaleText_loc5`='我遺失了瓦薩拉克領主護符!', `FemaleText_loc7`='¡He perdido el amuleto de Lord Valthalak!' WHERE `ID`=11773;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, $n. 다행스럽게도 당신이 지난번 내게 아뮬렛을 주었을 때, 나 자신을 아뮬렛에 맞추어 놓았답니다. 당신이 잃어버린 장소에 관계없이 다시 소환해 드릴 수 있단 말이죠.$B$B자, 이제 소지품을 한 번 살펴보세요.', `MaleText_loc4`='啊，$n，别哭。你运气真好，上次你把饰品交给我之后，我在饰品上做了点手脚。我可以帮你召唤回丢失的饰品。$B$B现在，翻翻你的包裹吧。', `MaleText_loc5`='啊，$n，別哭了。你有幸運加持，上次你給我的護符，我將它和自己調合了。我只要將它從你上次掉落的位置召喚回來就可以了。$B$B現在看看你的包包裡。', `MaleText_loc7`='$n, no llores. Por suerte para ti, la última vez que me diste el amuleto entré en sintonía con él. Haré que venga de dondequiera que te haya caído.$B$BRevisa ahora tus bolsas.' WHERE `ID`=11774;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 뜻은 잘 알겠어요. 내가 예전에 용병으로 소속되었던 감춰진 칼날단을 기꺼이 돕겠다니 정말 감사해요.$B$B자, 앞으로 우리가 해야 할 일은 무엇인지 좀 살펴볼까요?', `MaleText_loc4`='你已经向我证明了你的诚意，$n，同时，你愿意帮助我以前所属的雇佣兵团迷雾之刃的成员，我对此表示十分感谢。', `MaleText_loc5`='你的想法說服了我，$n，也謝謝你願意幫助我以前在隱刃傭兵公司的同伴。$B$B現在來看看，清單上下一件要做的事是什麼?', `MaleText_loc7`='Me has convencido de tus intenciones, $n, y te agradezco que desees ayudar a los miembros de mi antigua compañía de mercenarios, La Espada Enmascarada.$B$BY ahora veamos qué es lo siguiente en la lista de cosas por hacer.' WHERE `ID`=11775;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='군주 발타라크의 아뮬렛 조각을 잃어버렸습니다!', `MaleText_loc4`='我把一块瓦塔拉克公爵的饰品碎片弄丢了！', `MaleText_loc5`='我遺失了瓦薩拉克領主那塊護符!', `MaleText_loc7`='¡He perdido un fragmento del amuleto de Lord Valthalak!', `FemaleText_loc1`='군주 발타라크의 아뮬렛 조각을 잃어버렸어요!', `FemaleText_loc4`='我把一块瓦塔拉克公爵的饰品碎片弄丢了！', `FemaleText_loc5`='我遺失了瓦薩拉克領主那塊護符!', `FemaleText_loc7`='¡He perdido un fragmento del amuleto de Lord Valthalak!' WHERE `ID`=11776;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 걱정하지 마세요, $n! 아뮬렛의 어떤 조각을 잃어버렸어요?$B$B당신 소지품과 은행에 있는 물건들은 다 확인해 보았나요?', `MaleText_loc4`='好了，好了，$n，不要担心！饰品的哪一部分找不到了？$B$B所有的背包和银行都检查过了？', `MaleText_loc5`='那裡，在那裡，$n，別擔心!你弄丟的是哪塊護符?$B$B你檢查過你所有的包包和銀行欄位了嗎?', `MaleText_loc7`='Vamos, $n. ¡No te preocupes! ¿Qué fragmento del amuleto no encuentras?$B$B¿Has mirado en todas tus bolsas y en el banco?' WHERE `ID`=11777;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 확인해봤습니다. 가운데 조각을 잃어버렸어요!', `MaleText_loc4`='是的，我检查过了，上面的那一瓣找不到了！', `MaleText_loc5`='是的，我檢查過了，我少了左半塊!', `MaleText_loc7`='Sí, ya lo he hecho y me falta el fragmento superior.', `FemaleText_loc1`='네, 확인해봤어요. 가운데 조각을 잃어버렸어요!', `FemaleText_loc4`='是的，我检查过了，上面的那一瓣找不到了！', `FemaleText_loc5`='是的，我檢查過了，我少了左半塊!', `FemaleText_loc7`='Sí, ya lo he hecho y me falta el fragmento superior.' WHERE `ID`=11778;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 보들리 님이 나섰으니 걱정하지 마세요! 어디 보자, 아 그렇지... 여기 있군요. 그럼 어디 소환해 볼까... 이얍!$B$B또다시 잃어버리지 않도록 조심하세요, $n 씨.', `MaleText_loc4`='千万别害怕，有伯德雷在呢！我们看这里，啊，是了……就在这里。让我把它召唤过来……嗯，快点！$B$B下次别再把它弄丢了，$n。', `MaleText_loc5`='別害怕，布德利在執勤中!來看看這裡，啊沒錯...就是這裡。我要召喚它了...還有，立刻!$B$B不要又弄丟了，$n。', `MaleText_loc7`='¡No temas, Bodley está en ello! A ver, a ver... Ah, sí, ya está. Ahora voy a hacer que venga... ¡Y listo!$B$BIntenta no perderlo de nuevo, $n.' WHERE `ID`=11779;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 확인해봤습니다. 왼쪽 조각을 분실했어요!', `MaleText_loc4`='是的，我检查过了，左边这一瓣找不到了！', `MaleText_loc5`='是的，我檢查過了，我少了左半塊!', `MaleText_loc7`='Sí, ya lo he hecho y me falta el fragmento izquierdo.', `FemaleText_loc1`='네, 확인해봤어요. 왼쪽 조각을 분실했어요!', `FemaleText_loc4`='是的，我检查过了，左边这一瓣找不到了！', `FemaleText_loc5`='是的，我檢查過了，我少了左半塊!', `FemaleText_loc7`='Sí, ya lo he hecho y me falta el fragmento izquierdo.' WHERE `ID`=11780;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알았어요, 알았다고요. 진정하세요, $c님. 걱정할 필요 전혀 없답니다. 다행스럽게도 당신이 처음 왼쪽 조각을 내게 주었을 때, 나 자신을 조각과 맞추어 놓았거든요. 그래서 당신이 조각을 어디에서 잃어버렸든지 다시 소환하는 것은 아무런 문제가 되지 않는답니다.$B$B자, 여기 있어요. 그리고 이제부터 좀 더 조심하시는 게 좋겠네요.', `MaleText_loc4`='好了，好了，冷静点，$c，没什么好担心的。既然我们有幸得到了它，我就做了防范。在你第一次给我左瓣的时候，我在它和自己之间建立起了连接，要是找不到它了，我可以把它召唤到我手里来。$B$B给，这次一定要小心，不要再弄丢。', `MaleText_loc5`='好，好，冷靜下來，$c，沒什麼好擔心的。有好運加持，你第一次給我左邊那塊，我就把我的也合併起來了，然後再把它從錯的位置召喚回來。這不是什麼大問題。$B$B在這裡，這次你要好好照顧它。', `MaleText_loc7`='Vale, tranquilízate, $c. No hay nada de qué preocuparse. Por suerte, la primera vez que me diste el fragmento izquierdo entré en sintonía con él y no me resultará complicado hacer que venga de dondequiera que te haya caído.$B$BAquí lo tienes, y a partir de ahora intenta tener más cuidado con él.' WHERE `ID`=11781;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부름의 화로를 잃어버렸습니다!', `MaleText_loc4`='我把召唤火盆弄丢了！', `MaleText_loc5`='我把召喚火盆放錯位置了!', `MaleText_loc7`='no sé dónde he puesto el blandón de señalización.', `FemaleText_loc1`='부름의 화로를 잃어버렸어요!', `FemaleText_loc4`='我把召唤火盆弄丢了！', `FemaleText_loc5`='我把召喚火盆放錯位置了!', `FemaleText_loc7`='no sé dónde he puesto el blandón de señalización.' WHERE `ID`=11784;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='농담이죠? 아닌가요? 알았어요, 알았다고요. 그만 진정하세요. 다행스럽게도 지난번에 당신이 되찾아온 물건들을 화로에 불어넣을 때, 나 자신을 그것과 맞추어 놓았답니다. 그래서 당신이 놔둔 장소에 상관없이 그 위치를 알아내서 소환할 수 있어요.$B$B그런데 잃어버린 것이 분명한가요? 소지품과 은행에 둔 물건들은 모두 확인해본 거죠?', `MaleText_loc4`='你在开玩笑吗？好，好，别担心别担心。幸亏我在你拿到它以后就给它灌注入了魔法材料，并和我自己建立了连接。我应该可以知道定出它的位置并把它召唤到我手里来。$B$B确实把它搞丢了吗？所有的背包和银行里都没有吗？', `MaleText_loc5`='你在開玩笑，對不對?好，好，不要慌張。幸好當我在注入你取回的那些物品時，我也調和了自己的部份。 我可以從你弄丟它的位置來找到並召喚它。$B$B你確定它真的不見了?你有看過你所有的包包和銀行欄位了嗎?', `MaleText_loc7`='Estás de broma, ¿verdad? ¡Vale, vale! Que no cunda el pánico. Afortunadamente cuando lo estaba impregnando con el componente que recuperaste, entré en sintonía con él. Debería ser capaz de localizarlo y hacer que venga de dondequiera que lo hayas dejado.$B$B¿Estás $gseguro:segura; de que lo has perdido? ¿Has mirado en todas tus bolsas y en el banco?' WHERE `ID`=11785;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='확실합니다. 다시 소환해 주십시오!', `MaleText_loc4`='是的，请把它召唤回来！', `MaleText_loc5`='好，請把它召喚回來!', `MaleText_loc7`='Sí, por favor haz que aparezca de nuevo.', `FemaleText_loc1`='확실해요. 다시 소환해 주세요!', `FemaleText_loc4`='是的，请把它召唤回来！', `FemaleText_loc5`='好，請把它召喚回來!', `FemaleText_loc7`='Sí, por favor haz que aparezca de nuevo.' WHERE `ID`=11786;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 여기 있어요, $n. 내가 유령이 되어 버린 지금도 점을 치고 소환할 수 있는 힘을 잃지 않았다는 게 정말 다행스럽지 않나요? 헤헤.', `MaleText_loc4`='好了，$n。我的预言术和召唤术在我成了一个鬼魂之后还能使用，多好呀！', `MaleText_loc5`='你看吧，$n。我的占卜力量和召喚仍然對鬼魂狀態有作用，哼?', `MaleText_loc7`='Ahí lo tienes, $n. Menos mal que mis poderes de adivinación e invocación todavía funcionan en este estado fantasmal, ¿eh?' WHERE `ID`=11787;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모험가여, 안녕하십니까! 라벤홀트 장원의 토박이가 이렇게 인사 올립니다.', `MaleText_loc4`='拉文霍德庄园欢迎你的光临，冒险者。', `MaleText_loc5`='來自莊園拉文霍德，冒險者的祝福與問候。', `MaleText_loc7`='La mansión Ravenholdt te da la bienvenida, $gaventurero:aventurera;.' WHERE `ID`=11788;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예절이라는 것에 대해 좀 가르쳐줘야겠군.', `MaleText_loc4`='该是教你什么叫礼貌的时候了，$g小子:姑娘;。', `MaleText_loc5`='該是教你規矩的時候了，$g小夥子:小姑娘;。', `MaleText_loc7`='Es hora de enseñarte modales, $gchico:chica;.' WHERE `ID`=11789;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마음에 상처를 입은 것 같군요. 좀 추스르면 다시 얘기하도록 해요.', `FemaleText_loc4`='你看起来好像伤心欲绝。等你心情好一点之后再回来吧。', `FemaleText_loc5`='你看起來好像很傷心的樣子。等你好一點再回來吧。', `FemaleText_loc7`='Parece que te hayan roto el corazón. Vuelve cuando ya no estés tan triste.' WHERE `ID`=11790;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마음에 상처를 입은 것 같군. 좀 추스르고 나서 다시 얘기하도록 합시다.', `MaleText_loc4`='你看起来好像伤心欲绝。等你心情好一点之后再回来吧。', `MaleText_loc5`='你看起來好像很傷心的樣子。等你好一點再回來吧。', `MaleText_loc7`='Parece que te hayan roto el corazón. Vuelve cuando ya no estés tan triste.', `FemaleText_loc1`='마음에 상처를 입은 것 같군요. 좀 추스르고 나서 다시 얘기하도록 해요.', `FemaleText_loc4`='你看起来好像伤心欲绝。等你心情好一点之后再回来吧。', `FemaleText_loc5`='你看起來好像很傷心的樣子。等你好一點再回來吧。', `FemaleText_loc7`='Parece que te hayan roto el corazón. Vuelve cuando ya no estés tan triste.' WHERE `ID`=11791;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마음에 상처를 입은 것 같군. 좀 추스르고 나서 다시 얘기하도록 합시다.', `MaleText_loc4`='你看起来好像伤心欲绝。等你心情好一点之后再回来吧。', `MaleText_loc5`='你看起來好像很傷心的樣子。等你好一點再回來吧。', `MaleText_loc7`='Parece que te hayan roto el corazón. Vuelve cuando ya no estés tan triste.' WHERE `ID`=11792;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='흠, 당신의 악취가 좀 가시면 대화할 수 있는 기회를 드리죠. 은은한 향수를 좀 뿌리시는 게 어때요?', `FemaleText_loc4`='如果你能洒些香水的话，我会更喜欢你的。', `FemaleText_loc5`='如果你香香的我就跟你聊天。古龍水還不錯。', `FemaleText_loc7`='Hablaría contigo si olieras mejor. Un poco de colonia no estaría de más.' WHERE `ID`=11793;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭐라고요? 제게 줄 징표가 없다고요? 절 사랑하지 않으시나요?', `FemaleText_loc4`='什么？你没有可以给我的信物？你不爱我了？', `FemaleText_loc5`='什麼，你沒有硬幣要給我嗎?你不愛我喔?', `FemaleText_loc7`='¿Cómo? ¿No tienes ninguna prueba de amor que darme? ¿Es que no me quieres?' WHERE `ID`=11794;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠, 당신 악취가 좀 가시면 대화를 하도록 합시다. 은은한 향수를 뿌리시는 게 어때요?', `MaleText_loc4`='如果你能洒些香水的话，我就愿意和你交谈。古龙水听起来如何？', `MaleText_loc5`='如果你香香的我就跟你聊天。古龍水還不錯。', `MaleText_loc7`='Hablaría contigo si olieras mejor. Un poco de colonia no estaría de más.', `FemaleText_loc1`='흠, 당신 악취가 좀 가시면 저와 대화할 기회를 드리죠. 은은한 향수를 뿌리시는 게 어때요?', `FemaleText_loc4`='如果你能洒些香水的话，我就愿意和你交谈。古龙水听起来如何？', `FemaleText_loc5`='如果你香香的我就跟你聊天。古龍水還不錯。', `FemaleText_loc7`='Hablaría contigo si olieras mejor. Un poco de colonia no estaría de más.' WHERE `ID`=11795;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐라고? 나에게 줄 징표가 없다고? 날 사랑하지 않는 것이오?', `MaleText_loc4`='什么？你没有可以给我的纪念品？你不爱我了？', `MaleText_loc5`='什麼，你沒有硬幣要給我嗎?你不愛我喔?', `MaleText_loc7`='¿Cómo? ¿No tienes ninguna prueba de amor que darme? ¿Es que no me quieres?', `FemaleText_loc1`='뭐라고요? 제게 줄 징표가 없다고요? 절 사랑하지 않으시나요?', `FemaleText_loc4`='什么？你没有可以给我的纪念品？你不爱我了？', `FemaleText_loc5`='什麼，你沒有硬幣要給我嗎?你不愛我喔?', `FemaleText_loc7`='¿Cómo? ¿No tienes ninguna prueba de amor que darme? ¿Es que no me quieres?' WHERE `ID`=11796;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='매혹적인 향수를 좀 뿌리면 당신이 더 좋아질 것 같은데...', `MaleText_loc4`='如果你能洒些香水的话，我会更喜欢你的。', `MaleText_loc5`='如果你噴點香水我就會更喜歡你。', `MaleText_loc7`='Me gustarías más si te echaras un poco de perfume.', `FemaleText_loc1`='향수를 좀 뿌리면 당신이 더 좋아질 것 같은데...', `FemaleText_loc4`='如果你能洒些香水的话，我会更喜欢你的。', `FemaleText_loc5`='如果你噴點香水我就會更喜歡你。', `FemaleText_loc7`='Me gustarías más si te echaras un poco de perfume.' WHERE `ID`=11797;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='매혹적인 향수를 좀 뿌리면 당신이 더 좋아질 것 같은데...', `MaleText_loc4`='如果你能洒些香水的话，我会更喜欢你的。', `MaleText_loc5`='如果你噴點香水我就會更喜歡你。', `MaleText_loc7`='Me gustarías más si te echaras un poco de perfume.' WHERE `ID`=11798;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐라고? 나에게 줄 징표가 없다고? 날 사랑하지 않는 것이오?', `MaleText_loc4`='什么？你没有可以给我的纪念品？你不爱我了？', `MaleText_loc5`='什麼，你沒有硬幣要給我嗎?你不愛我喔?', `MaleText_loc7`='¿Cómo? ¿No tienes ninguna prueba de amor que darme? ¿Es que no me quieres?' WHERE `ID`=11799;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐야?! 어떻게 내 감옥을 빠져나왔지... 거기 아무도 없느냐? 어쨌든, 잘된 일인 것 같군. 안 그래도 요즘 매출이 좀 부진했는데.$B$B너의 그 집요한 요구를 어떻게 해결해 주면 좋을까, $c 친구?', `MaleText_loc4`='什么？！你是怎么跑进这里的……哦，外面带了伴当？好吧，我就算你没有恶意好了。今年我的销售势头似乎不行呀。$B$B你看你要我这里的什么货吧，$c？', `MaleText_loc5`='什麼?!你是怎麼脫逃溜出我的監獄的...嗯，爪牙在那邊嗎?希望他是最厲害的。最近有一些業績。$B$B我要怎麼達成你那可恨的要求，$c?', `MaleText_loc7`='¡¿Qué?! ¿Cómo has logrado entrar sin que se diera cuenta mi... eh... mi esbirro que está ahí fuera? Bueno, supongo que es lo mejor. Últimamente, las ventas no van nada bien.$B$B¿Cómo puedo complacer tus infernales necesidades, $c?' WHERE `ID`=11800;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마음에 상처를 입은 것 같군. 좀 추스르고 나서 다시 얘기하도록 합시다.', `MaleText_loc4`='你看起来好像伤心欲绝。等你心情好一点之后再回来吧。', `MaleText_loc5`='你看起來好像很傷心的樣子。等你好一點再回來吧。', `MaleText_loc7`='Parece que te hayan roto el corazón. Vuelve cuando ya no estés tan triste.', `FemaleText_loc1`='마음에 상처를 입은 것 같군. 좀 추스르고 나서 다시 얘기하도록 해요.', `FemaleText_loc4`='你看起来好像伤心欲绝。等你心情好一点之后再回来吧。', `FemaleText_loc5`='你看起來好像很傷心的樣子。等你好一點再回來吧。', `FemaleText_loc7`='Parece que te hayan roto el corazón. Vuelve cuando ya no estés tan triste.' WHERE `ID`=11801;
