UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐라고요? 제게 줄 징표가 없다고요? 절 사랑하지 않는 겁니까?', `MaleText_loc4`='什么？你没有可以给我的纪念品？你不爱我了？', `MaleText_loc5`='什麼，你沒有硬幣要給我嗎?你不愛我喔?', `MaleText_loc7`='¿Cómo? ¿No tienes ninguna prueba de amor que darme? ¿Es que no me quieres?', `FemaleText_loc1`='뭐라고요? 제게 줄 징표가 없다고요? 절 사랑하지 않으세요?', `FemaleText_loc4`='什么？你没有可以给我的纪念品？你不爱我了？', `FemaleText_loc5`='什麼，你沒有硬幣要給我嗎?你不愛我喔?', `FemaleText_loc7`='¿Cómo? ¿No tienes ninguna prueba de amor que darme? ¿Es que no me quieres?' WHERE `ID`=11803;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 이미 사랑을 찾은 것 같군요. 제게 사랑의 징표를 주신다고 해도 좋은 선물은 안 드릴 거예요. 전 특별한 누군가를 기다리고 있거든요.', `MaleText_loc4`='我一看就知道，你已经找到了自己的真爱。你可以给我一件爱情信物，但我没什么可以给你的。我正在等待一个特殊的人……', `MaleText_loc5`='看來你已經找到真愛了。你可以給我一個愛之硬幣，但是我不會給你任何好東西。我在等待一個特別的人。', `MaleText_loc7`='Parece que ya has encontrado el amor. Puedes entregarme una prueba de amor pero yo no te daré nada a cambio. Estoy esperando a alguien especial.', `FemaleText_loc1`='당신은 이미 사랑을 찾은 것 같군요. 제게 사랑의 징표를 주신다고 해도 좋은 선물은 안 드릴 거예요. 전 특별한 누군가를 기다리고 있거든요.', `FemaleText_loc4`='我一看就知道，你已经找到了自己的真爱。你可以给我一件爱情信物，但我没什么可以给你的。我正在等待一个特殊的人……', `FemaleText_loc5`='看來你已經找到真愛了。你可以給我一個愛之硬幣，但是我不會給你任何好東西。我在等待一個特別的人。', `FemaleText_loc7`='Parece que ya has encontrado el amor. Puedes entregarme una prueba de amor pero yo no te daré nada a cambio. Estoy esperando a alguien especial.' WHERE `ID`=11804;
