UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐라고요? 제게 줄 징표가 없다고요? 절 사랑하지 않는 겁니까?', `MaleText_loc4`='什么？你没有可以给我的纪念品？你不爱我了？', `MaleText_loc5`='什麼，你沒有硬幣要給我嗎?你不愛我喔?', `MaleText_loc7`='¿Cómo? ¿No tienes ninguna prueba de amor que darme? ¿Es que no me quieres?' WHERE `ID`=11810;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 더 좋은 향기를 풍긴다면 저와 대화할 기회를 드리겠어요. 은은한 향수 좀 뿌리는 게 어때요? 아니면 매혹적인 향수는?', `MaleText_loc4`='如果你能洒些香水的话，我就愿意和你交谈。古龙水听起来如何？', `MaleText_loc5`='如果你香香的我就跟你聊天。古龍水怎麼樣?還是要香水?', `MaleText_loc7`='Hablaría contigo si olieras mejor. ¿Qué te parecería un poco de colonia? ¿Quizás perfume?', `FemaleText_loc1`='당신이 더 좋은 향기를 풍긴다면 저와 대화할 기회를 드리겠어요. 은은한 향수 좀 뿌리는 게 어때요? 아니면 매혹적인 향수는?', `FemaleText_loc4`='如果你能洒些香水的话，我就愿意和你交谈。古龙水听起来如何？', `FemaleText_loc5`='如果你香香的我就跟你聊天。古龍水怎麼樣?還是要香水?', `FemaleText_loc7`='Hablaría contigo si olieras mejor. ¿Qué te parecería un poco de colonia? ¿Quizás perfume?' WHERE `ID`=11811;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자다! 의심할 필요도 없이 은빛 여명회의 졸개들이겠지. 내 죄수들 사이에 놈들 중 하나가 있다는 것을 알고 있다. 어서 내 영역에서 물러가라. 그렇지 않으면 그 여죄수는 처형될 것이다!', `MaleText_loc4`='入侵者！肯定是银色黎明的援兵！我手中有一名银色黎明的战俘。撤离我的领土，不然我就宰了她！', `MaleText_loc5`='入侵者!絕對是更多銀色黎明的爪牙。我在我的戰俘裡早數過了。在她被處決前撤出我的領土!', `MaleText_loc7`='¡Intrusos! Se trata de más peones de El Alba Argenta, sin duda. Ya tengo a uno de ellos como prisionero. ¡Marchaos de mis dominios o ella será ejecutada!' WHERE `ID`=11812;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 여기 있었나? 정말 놀랍도록 멍청하군! 저 은빛 여명회의 계집이 쓸데없이 고통을 받을 필요는 없지 않을까? 당장 떠나라. 그러면 여죄수는 목숨을 건지게 되리라!', `MaleText_loc4`='你还在这里？你的愚蠢简直是太有趣了！银色黎明派来的这个女人本来不用白白受苦的。马上离开这里，她就不会有事！', `MaleText_loc5`='你還在?你的愚蠢還真好笑!這銀色黎明的蠢女人不需要白白犧牲的。立刻離開我就饒了她!', `MaleText_loc7`='¿Todavía están aquí? ¡Su insensatez resulta divertida! La chica de El Alba Argenta no tiene por qué sufrir en vano. ¡Marchénse inmediatamente y le perdonaremos la vida!' WHERE `ID`=11813;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 죄수의 죽음이 본보기가 될 것이다. 그 누구도 스컬지를 거역하면 살아남지 못한다는 것을 보여주마!', `MaleText_loc4`='但愿这个战俘的死能起到警告的作用。谁敢与天灾军团抗衡，就是死路一条！', `MaleText_loc5`='希望這名犯人的死是個警訊。沒人敢再挑釁天譴軍團，挑戰者必死無疑!', `MaleText_loc7`='Que la muerte de $geste prisionero:esta prisionera; sirva como advertencia. ¡Nadie que desafíe a la Plaga quedará con vida!' WHERE `ID`=11814;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 기꺼이 이 가엾은 여인의 목숨을 취하리라! 하지만, 아직 늦지는 않았다. 그녀가 고통을 겪을 필요는 없지 않는가? 돌아가라. 그러면 그녀에게 자비를 베풀겠노라!', `MaleText_loc4`='能让我亲手结果这个可怜虫，我非常高兴的。还不算太晚，她不必无谓地吃苦头。转过头去吧，我会仁慈地结束她的生命！', `MaleText_loc5`='我很高興可以解決掉這個可憐的傢伙!還不算太晚，她不需要平白犧牲了，回頭吧，她的死也算慈悲。', `MaleText_loc7`='¡Disfrutaré dando muerte a esta pobre desgraciada! Todavía no es demasiado tarde y no es necesario que sufra en vano. ¡Marchaos y recibirá una muerte compasiva!' WHERE `ID`=11815;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제 걱정은 하지 마세요! 이 끔찍한 짐승을 해치우고 그의 더러운 손에서 이 세상을 구원해 주세요!', `FemaleText_loc4`='别担心我！杀死这头可怕的野兽，净化被他的邪恶力量所玷污的世界！', `FemaleText_loc5`='不用擔心我!殺掉這可怕的怪獸，清掉這個廢渣!', `FemaleText_loc7`='¡No os preocupéis por mí! ¡Acabad con estas atroces bestias y liberad al mundo de su inmunda presencia!' WHERE `ID`=11816;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내가 죽는 것은 아무것도 아니다... 빛의 힘이... 승리할... 것이다!', `FemaleText_loc4`='我死不足惜……圣光……将……照耀大地！', `FemaleText_loc5`='我的死不算什麼...光明...將...戰勝!', `FemaleText_loc7`='¡Mi muerte no cambia nada... la luz... seguirá... imperando!' WHERE `ID`=11817;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전 이제 자유의 몸이에요! 도와주세요! 이제 제 오빠 소도스를 구해야 합니다.', `FemaleText_loc4`='我自由了！现在让我们共同努力，营救我的兄弟索托斯吧！', `FemaleText_loc5`='我自由了!現在讓我們同心協力拯救我的弟弟，索索斯!', `FemaleText_loc7`='¡Soy libre! ¡Unamos ahora nuestras fuerzas para salvar a mi hermano, Sothos!' WHERE `ID`=11818;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$g형제:자매;여, 구해주셔서 감사합니다. 마침내 우리는 평화롭게 쉴 수 있게 되었어요.', `FemaleText_loc4`='谢谢你让我重获自由，我的兄弟，感谢你们大家！现在我们能安然长眠了。', `FemaleText_loc5`='謝謝你們解救了我，我的兄弟，和你們所有人!我們現在終於可以安息了。', `FemaleText_loc7`='¡Gracias por liberarme, querido hermano! ¡Y gracias a todos ustedes! Por fin podemos descansar en paz.' WHERE `ID`=11819;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가지고 있는 물건을 보고 싶습니다.', `MaleText_loc4`='让我们看看你的能力吧。', `MaleText_loc5`='看看你還剩下什麼。', `MaleText_loc7`='Veamos lo que tienes.', `FemaleText_loc1`='가지고 있는 물건을 보고 싶습니다.', `FemaleText_loc4`='让我们看看你的能力吧。', `FemaleText_loc5`='看看你還剩下什麼。', `FemaleText_loc7`='Veamos lo que tienes.' WHERE `ID`=11820;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 임무는 완료되었다. 보급품이 필요하다면 내게 남은 게 좀 있긴 하다만...', `MaleText_loc4`='我的任务就是竞争。我这里还有些剩余补给，不知你是否需要。', `MaleText_loc5`='我的任務已經完成了。我可以給你一些我剩下的補給。', `MaleText_loc7`='He cumplido mi misión. Creo que tengo suministros de sobra por si necesitas algo.' WHERE `ID`=11821;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아닙니다, 전 아니지만 많은 이들이 사랑을 갈구하고 있지요. 손님께서는 제가 팔고 있는 사랑의 징표를 구입하시고 은은한 향수나 매혹적인 향수를 뿌린 후 다른 이들을 스쳐 지나가며 매력을 풍기셔야 한답니다!', `MaleText_loc4`='没有啊，不过许多其他人都在寻找爱情。你应该从我这里买些爱情信物，洒上一些香水，然后勇敢地出击！', `MaleText_loc5`='不，我沒有。但其他人都想談戀愛。你應該跟我買些愛之硬幣，噴些古龍水或香水，發給大家!', `MaleText_loc7`='Yo no, pero muchos por ahí sí buscan amor. ¡Deberías comprarme pruebas de amor, echarte un poco de colonia o perfume y pasar a su lado!', `FemaleText_loc1`='아니에요, 전 아니지만 많은 이들이 사랑을 갈구하고 있답니다. 손님께서는 제가 팔고 있는 사랑의 징표를 구입하시고 은은한 향수나 매혹적인 향수를 뿌린 후 다른 이들을 스쳐 지나가며 매력을 풍기셔야 하죠!', `FemaleText_loc4`='没有啊，不过许多其他人都在寻找爱情。你应该从我这里买些爱情信物，洒上一些香水，然后勇敢地出击！', `FemaleText_loc5`='不，我沒有。但其他人都想談戀愛。你應該跟我買些愛之硬幣，噴些古龍水或香水，發給大家!', `FemaleText_loc7`='Yo no, pero muchos por ahí sí buscan amor. ¡Deberías comprarme pruebas de amor, echarte un poco de colonia o perfume y pasar a su lado!' WHERE `ID`=11822;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='머리 위에 그 표시는 당신이 사랑을 찾고 있다는 뜻입니까?', `MaleText_loc4`='你是在寻找爱情吗？', `MaleText_loc5`='這心是代表你想談戀愛嗎?', `MaleText_loc7`='¿Ese corazón quiere decir que buscas amor?', `FemaleText_loc1`='머리 위에 그 표시는 당신이 사랑을 찾고 있다는 뜻인가요?', `FemaleText_loc4`='你是在寻找爱情吗？', `FemaleText_loc5`='這心是代表你想談戀愛嗎?', `FemaleText_loc7`='¿Ese corazón quiere decir que buscas amor?' WHERE `ID`=11823;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사랑의 징표는 무엇입니까?', `MaleText_loc4`='爱情信物是什么？', `MaleText_loc5`='愛之硬幣是什麼?', `MaleText_loc7`='¿Qué son las pruebas de amor?', `FemaleText_loc1`='사랑의 징표는 무엇인가요?', `FemaleText_loc4`='爱情信物是什么？', `FemaleText_loc5`='愛之硬幣是什麼?', `FemaleText_loc7`='¿Qué son las pruebas de amor?' WHERE `ID`=11824;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은은한 향수와 매혹적인 향수를 팔고 있습니까?', `MaleText_loc4`='你有香水出售？', `MaleText_loc5`='你有賣古龍水跟香水嗎?', `MaleText_loc7`='¿Vendes colonia o perfume?', `FemaleText_loc1`='은은한 향수와 매혹적인 향수를 팔고 있나요?', `FemaleText_loc4`='你有香水出售？', `FemaleText_loc5`='你有賣古龍水跟香水嗎?', `FemaleText_loc7`='¿Vendes colonia o perfume?' WHERE `ID`=11825;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사랑의 징표는 도시와 마을에서 사랑을 찾는 시민들에게 줄 수 있어요. 답례로 애정이 담긴 선물을 받을 수 있을 겁니다.$B$B손님께서 벌써 사랑을 받으셨다면 최소한 우정의 징표라도 줄 거랍니다.', `MaleText_loc4`='爱情信物是用来向你中意的某个城中的居民表达爱意的小东西。如果对方也对你感兴趣的话，你就可以收到一份爱情的礼物。$B$B如果你已经和别人相爱了，那么至少对方会给你一份代表友谊的礼物。', `MaleText_loc5`='愛之硬幣就是愛的小訊息，你可以給熱情的城鄉人們。他們會回送你象徵愛意的禮物。$B$B或者說，有人愛慕或崇拜你，他們也會給你友誼之禮。', `MaleText_loc7`='Las pruebas de amor son mensajes de cariño que puedes entregar a la gente de la ciudad que esté buscando amor. Esas personas te recompensarán con un regalo de adoración.$B$BSi ya tienes a alguien que te adore, entonces te entregarán un regalo de amistad.', `FemaleText_loc1`='사랑의 징표는 도시와 마을에서 사랑을 찾는 시민들에게 줄 수 있어요. 답례로 애정이 담긴 선물을 받을 수 있을 거예요.$B$B손님께서 벌써 사랑을 받으셨다면 최소한 우정의 징표라도 줄 거랍니다.', `FemaleText_loc4`='爱情信物是用来向你中意的某个城中的居民表达爱意的小东西。如果对方也对你感兴趣的话，你就可以收到一份爱情的礼物。$B$B如果你已经和别人相爱了，那么至少对方会给你一份代表友谊的礼物。', `FemaleText_loc5`='愛之硬幣就是愛的小訊息，你可以給熱情的城鄉人們。他們會回送你象徵愛意的禮物。$B$B或者說，有人愛慕或崇拜你，他們也會給你友誼之禮。', `FemaleText_loc7`='Las pruebas de amor son mensajes de cariño que puedes entregar a la gente de la ciudad que esté buscando amor. Esas personas te recompensarán con un regalo de adoración.$B$BSi ya tienes a alguien que te adore, entonces te entregarán un regalo de amistad.' WHERE `ID`=11826;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은은한 향수나 매혹적인 향수를 뿌리면 누가 사랑을 찾고 있는지 알게 되실 겁니다. 그들은 사랑의 징표를 받고... 답례로 선물을 줄 겁니다.$B$B하지만, 누군가에게 사랑의 징표를 주려면 적당한 향기를 풍겨야 한답니다! 여자들이 은은한 향수를 좋아하는 한편 남자들은 매혹적인 향수를 좋아하거든요.', `MaleText_loc4`='如果你洒上一些香水，就可以找到对你有好感的人。他们会接受你的爱情信物……并给你一件礼物作为回报。$B$B但是，你要记住：要让别人接受你的爱情信物，你必须闻起来很迷人！男人喜欢香水的味道，而女人会为古龙水陶醉！', `MaleText_loc5`='如果你噴點古龍水或香水，你就會發現某個人正含情脈脈的示意。他們專收愛之硬幣...然後再回送你禮物。$B$B請記住:給別人硬幣時，你也要聞起來香香的才行!男人喜歡香水的味道，而女人則偏愛古龍水的香味。', `MaleText_loc7`='Si te echas colonia o perfume, podrás ver quién está buscando amor. Esos aceptarán pruebas de amor... y te entregarán un regalo a cambio.$B$BPero recuerda: para darle a alguien una prueba de amor, ¡deberás oler bien! A los hombres les gusta el perfume mientras que las mujeres prefieren el olor de la colonia.', `FemaleText_loc1`='은은한 향수나 매혹적인 향수를 뿌리면 누가 사랑을 찾고 있는지 알게 되실 거예요. 그들은 사랑의 징표를 받고... 답례로 선물을 주지요.$B$B하지만, 누군가에게 사랑의 징표를 주려면 적당한 향기를 풍겨야 해요! 여자들이 은은한 향수를 좋아하는 한편 남자들은 매혹적인 향수를 좋아하거든요.', `FemaleText_loc4`='如果你洒上一些香水，就可以找到对你有好感的人。他们会接受你的爱情信物……并给你一件礼物作为回报。$B$B但是，你要记住：要让别人接受你的爱情信物，你必须闻起来很迷人！男人喜欢香水的味道，而女人会为古龙水陶醉！', `FemaleText_loc5`='如果你噴點古龍水或香水，你就會發現某個人正含情脈脈的示意。他們專收愛之硬幣...然後再回送你禮物。$B$B請記住:給別人硬幣時，你也要聞起來香香的才行!男人喜歡香水的味道，而女人則偏愛古龍水的香味。', `FemaleText_loc7`='Si te echas colonia o perfume, podrás ver quién está buscando amor. Esos aceptarán pruebas de amor... y te entregarán un regalo a cambio.$B$BPero recuerda: para darle a alguien una prueba de amor, ¡deberás oler bien! A los hombres les gusta el perfume mientras que las mujeres prefieren el olor de la colonia.' WHERE `ID`=11827;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 선물로 무엇을 할 수 있는데요?', `MaleText_loc4`='我拿这些礼物有什么用？', `MaleText_loc5`='我要怎麼處理這些禮物啊?', `MaleText_loc7`='¿Qué puedo hacer con estos regalos?', `FemaleText_loc1`='그 선물로 무엇을 할 수 있는데요?', `FemaleText_loc4`='我拿这些礼物有什么用？', `FemaleText_loc5`='我要怎麼處理這些禮物啊?', `FemaleText_loc7`='¿Qué puedo hacer con estos regalos?' WHERE `ID`=11828;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳 시민들에게 사랑의 징표를 건네주면 답례로 다양한 선물을 받게 될 거예요. 그중 몇 가지는 손님께서 지니고 사용하고 싶어하실 테지만, 다른 것들은 한데 묶어서 당신이 좋아하는 영웅에게 바칠 수 있어요! 덜렁발 큐이피를 찾아서 선물세트를 주세요.$B$B큐이피는 볼바르 님, 마그니 님, 그리고 티란데 님 곁에서 찾을 수 있을 거예요.', `MaleText_loc4`='当你把爱情信物交给城镇里的居民时，你可以收到各种礼物作为回报。一些礼物最好留起来用，另一些则最好放在一起做成一个大礼品包！$B$B去找匹德菲特为你喜欢的英雄投票吧。$B$B你可以在伯瓦尔、麦格尼或者泰兰德身边找到匹德菲特。', `MaleText_loc5`='當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄!拜訪丘比特·傳播者把禮物交給他。$B$B丘比特就在伯瓦爾，麥格尼和泰蘭妲附近。', `MaleText_loc7`='Cuando entregues pruebas de amor a los habitantes de la ciudad, recibirás diferentes regalos a cambio. Algunos podrás guardarlos y utilizarlos, y otros ¡podrás juntarlos y dárselos a tu $ghéroe favorito:heroína favorita;! Visita a Kwee Q. Pies Rápidos y entrégaselos.$B$BEncontrarás a Kwee cerca de Bolvar, Magni o Tyrande.', `FemaleText_loc1`='이곳 시민들에게 사랑의 징표를 건네주면 답례로 다양한 선물을 받게 될 거예요. 그중 몇 가지는 손님께서 지니고 사용하고 싶어하실 테지만, 다른 것들은 한데 묶어서 당신이 좋아하는 영웅에게 바칠 수 있어요! 덜렁발 큐이피를 찾아서 선물세트를 주세요.$B$B큐이피는 볼바르 님, 마그니 님, 그리고 티란데 님 곁에서 찾을 수 있을 거예요.', `FemaleText_loc4`='当你把爱情信物交给城镇里的居民时，你可以收到各种礼物作为回报。一些礼物最好留起来用，另一些则最好放在一起做成一个大礼品包！$B$B去找匹德菲特为你喜欢的英雄投票吧。$B$B你可以在伯瓦尔、麦格尼或者泰兰德身边找到匹德菲特。', `FemaleText_loc5`='當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄!拜訪丘比特·傳播者把禮物交給他。$B$B丘比特就在伯瓦爾，麥格尼和泰蘭妲附近。', `FemaleText_loc7`='Cuando entregues pruebas de amor a los habitantes de la ciudad, recibirás diferentes regalos a cambio. Algunos podrás guardarlos y utilizarlos, y otros ¡podrás juntarlos y dárselos a tu $ghéroe favorito:heroína favorita;! Visita a Kwee Q. Pies Rápidos y entrégaselos.$B$BEncontrarás a Kwee cerca de Bolvar, Magni o Tyrande.' WHERE `ID`=11829;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n! 제 말벗을 해주려고 돌아왔다고요? 정말 사려 깊은 친구로군요. 그리고 그 옷을 입고 있으니 당신 정말 멋진데요!$B$B다시 만나 얼마나 반가운지 모를 거예요. 여기 있으면 대부분 날 볼 수 없고 또 이것저것 다른 이유로 정말 외롭거든요, 이해하시죠? 당신이 우리 모두에게 해준 일은 정말 위대한 것이었어요. 절대 잊지 않을게요!$B$B일부러 찾아와 말동무가 되어줘서 고마웠어요. 그럼 자주 들러주세요!', `MaleText_loc4`='$n！你回来陪我说话解闷儿啦？你心肠真好，而且你这身衣服看起来相当不错呢！$B$B你不知道我见到你有多高兴。我呆在这儿真是太寂寞了，这些粗俗的灵魂又没法看见我。感谢你为我们所做的一切，我是永远不会忘记的！$B$B谢谢你过来看我，别拘谨。', `MaleText_loc5`='$n!你回來就是為了跟我聊聊嗎?好體貼啊，你今天穿的好美喔!$B$B你大概想不到見到你我有多開心。在這裡我好寂寞，都跟一堆忽視我的野人在一起。謝謝你為了我們所做的努力，我畢生難忘!$B$B謝謝你順道過來問候我們，別拘束，就當自己家吧。', `MaleText_loc7`='$n! ¿Has vuelto solo para hablar conmigo? Es muy amable por tu parte y además... ¡eso que llevas puesto te favorece mucho!$B$BNo sabes cuánto me alegro de verte. Puedo llegar a sentirme muy solo aquí debido a que la mayor parte de estos patanes no pueden verme. ¡Nunca olvidaré lo que has hecho por todos nosotros!$B$BGracias por venir a saludar y no olvidarte de mí.' WHERE `ID`=11830;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 만나서 반가워요, $n. 말벗이 있다는 게 얼마나 행복한 일인지 내가 말했던가요?$B$B좋아요. 그럼, 일 얘기로 돌아가도록 하죠. 우리가 다음으로 할 일은 무엇일까요?', `MaleText_loc4`='欢迎回来，$n。我说过能有人陪我聊天多么多么好吗？$B$B好吧，让我们谈点正经事。下一步我们该怎么做？', `MaleText_loc5`='歡迎回來，$n。我有說過有人能陪我聊聊真好嗎?$B$B好吧，來談正事吧。下一步我們要怎麼做?', `MaleText_loc7`='$GBienvenido:Bienvenida; de nuevo, $n. ¿Ya te dije lo mucho que me alegro de tener a alguien con quien hablar?$B$BBueno, pues ahora pongamos manos a la obra. ¿Qué es lo siguiente que tenemos que hacer?' WHERE `ID`=11831;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여보시오, $n. 이쪽으로 오시오. 당신과 얘기를 좀 나누고 싶소이다.', `MaleText_loc4`='嘿，$n。过来过来，我想跟你谈谈。', `MaleText_loc5`='嗨，$n。這裡啊，我想跟你談談。', `MaleText_loc7`='Eh, $n. ¡Aquí! Quiero hablar contigo.' WHERE `ID`=11832;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 서버에서 가장 인기 좋은 영웅이 누구냐고요? 현재 순위를 알려드리죠!$B$B스랄: $2200w$B$B케른: $2201w$B$B실바나스: $2202w$B$B호드 전체: $2207w$B$B$B바리안: $2203w$B$B마그니: $2204w$B$B티란데: $2205w$B$B얼라이언스 전체: $2206w$B$B인기 투표에 당신의 소중한 표를 행사하고 싶은가요? 그렇다면, 저에게 선물세트를 내세요!', `MaleText_loc4`='你想知道谁是人气最高的英雄？目前的排名是这样的！$B$B萨尔：$2200w$B$B凯恩：$2201w$B$B希尔瓦娜斯：$2202w$B$B部落总计：$2207w$B$B$B瓦里安：$2203w$B$B麦格尼：$2204w$B$B泰兰德：$2205w$B$B联盟总计：$2206w$B$B如果你想参加投票，就拿出你的礼品包吧！', `MaleText_loc5`='誰是這個伺服器最受歡迎的英雄呢，你猜?這是目前的排行榜!$B$B索爾:$2200w$B凱恩:$2201w$B希瓦娜斯:$2202w$B部落總票數:$2207w$B$B瓦里安:$2203w$B麥格尼:$2204w$B泰蘭妲:$2205w$B聯盟總票數:$2206w$B$B如果想投票，就快去繳交你的禮物典藏品!', `MaleText_loc7`='¿Quieres saber quién es el héroe más popular del reino? ¡Esta es la clasificación actual!$B$BThrall: $2200w$BCairne: $2201w$BSylvanas: $2202w$BTotal de la Horda: $2207w$B$BVarian: $2203w$BMagni: $2204w$BTyrande: $2205w$BTotal de la Alianza: $2206w$B$BSi deseas emitir tu voto, ¡asegúrate de entregar tu colección de regalos!', `FemaleText_loc1`='우리 서버에서 가장 인기 좋은 영웅이 누구냐고요? 현재 순위를 알려드리죠!$B$B스랄: $2200w$B$B케른: $2201w$B$B실바나스: $2202w$B$B호드 전체: $2207w$B$B$B바리안: $2203w$B$B마그니: $2204w$B$B티란데: $2205w$B$B얼라이언스 전체: $2206w$B$B인기 투표에 당신의 소중한 표를 행사하고 싶은가요? 그렇다면, 저에게 선물세트를 내세요!', `FemaleText_loc4`='你想知道谁是人气最高的英雄？目前的排名是这样的！$B$B萨尔：$2200w$B$B凯恩：$2201w$B$B希尔瓦娜斯：$2202w$B$B部落总计：$2207w$B$B$B瓦里安：$2203w$B$B麦格尼：$2204w$B$B泰兰德：$2205w$B$B联盟总计：$2206w$B$B如果你想参加投票，就拿出你的礼品包吧！', `FemaleText_loc5`='誰是這個伺服器最受歡迎的英雄呢，你猜?這是目前的排行榜!$B$B索爾:$2200w$B凱恩:$2201w$B希瓦娜斯:$2202w$B部落總票數:$2207w$B$B瓦里安:$2203w$B麥格尼:$2204w$B泰蘭妲:$2205w$B聯盟總票數:$2206w$B$B如果想投票，就快去繳交你的禮物典藏品!', `FemaleText_loc7`='¿Quieres saber quién es el héroe más popular del reino? ¡Esta es la clasificación actual!$B$BThrall: $2200w$BCairne: $2201w$BSylvanas: $2202w$BTotal de la Horda: $2207w$B$BVarian: $2203w$BMagni: $2204w$BTyrande: $2205w$BTotal de la Alianza: $2206w$B$BSi deseas emitir tu voto, ¡asegúrate de entregar tu colección de regalos!' WHERE `ID`=11833;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요! 전 덜렁발 큐이피라고 해요! 저는 아제로스에 있는 모든 영웅 중에 가장 인기가 많은 분이 누구인지 알고 싶어요!$B$B많은 모험가들이 자신들의 지도자에게 존경을 표하는 걸 보면 제 마음도 무척 따뜻해진답니다. 하지만... 그 보다 더 절 벅차게 하는 게 뭔지 아세요?$B$B바로 /키스라고요!', `MaleText_loc4`='嗨！我是匹德菲特！我在这里统计谁是艾泽拉斯最受欢迎、人气最高的英雄！$B$B看到这么多人为他们崇拜的英雄投票，这可真让我高兴，但你知道什么可以让我更高兴吗？$B$B一个吻！', `MaleText_loc5`='嗨!我是丘比特·傳播者!我在這裡是為了找出艾澤拉斯最受歡迎的英雄!$B$B看到這麼多崇拜領導者的狂熱仰慕者真是溫暖我心啊，但...你知道還有什麼也能溫暖我心嗎?$B$B是一個香吻!', `MaleText_loc7`='¡Hola! ¡Soy Kwee Q. Pies Rápidos! ¡He venido para averiguar quién es el héroe o la heroína más popular de Azeroth!$B$BMe gusta ver que los líderes tienen tantos seguidores adorándoles, pero... ¿sabes lo que me gustaría todavía más?$B$B¡Que me dieras un beso!' WHERE `ID`=11834;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선물세트는 얼마나 모였나요? 누가 가장 인기가 많습니까?', `MaleText_loc4`='现在的礼物排名情况如何了？谁的人气最高？', `MaleText_loc5`='禮物排行榜進行的如何?誰是最受歡迎的人?', `MaleText_loc7`='¿Cómo está la clasificación de regalos? ¿Quién es el más popular?', `FemaleText_loc1`='선물세트는 얼마나 모였나요? 누가 가장 인기가 많아요?', `FemaleText_loc4`='现在的礼物排名情况如何了？谁的人气最高？', `FemaleText_loc5`='禮物排行榜進行的如何?誰是最受歡迎的人?', `FemaleText_loc7`='¿Cómo está la clasificación de regalos? ¿Quién es el más popular?' WHERE `ID`=11835;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아날리스? 당신인가?', `MaleText_loc4`='安娜利丝？是你吗？', `MaleText_loc5`='安娜莉斯?是你嗎?', `MaleText_loc7`='¿Annalise? ¿Eres tú?' WHERE `ID`=11836;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 사랑 스태프론, 사랑이 무엇인지 잊은 건가요? 한 때 우리가 나눴던 그 깊은 사랑을?', `FemaleText_loc4`='我亲爱的斯塔弗隆，你忘了爱情的感觉吗？那段我们曾经共同拥有过的爱情……', `FemaleText_loc5`='我親愛的史塔弗隆，你已經忘了什麼是愛嗎?我們倆曾經有過的愛?', `FemaleText_loc7`='Mi querido Staffron, ¿acaso has olvidado lo que es amar? ¿El amor que una vez nos profesamos?' WHERE `ID`=11837;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='스태프론...', `FemaleText_loc4`='斯塔弗隆……', `FemaleText_loc5`='史塔弗隆...', `FemaleText_loc7`='Staffron...' WHERE `ID`=11838;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 잊었다고? 물론이야. 난 행복과 사랑... 그리고 삶 그 자체에 대해 잊은 지 오래인걸.', `MaleText_loc4`='我忘记了吗？我当然忘记了……我忘了爱情，欢乐……忘了生命。', `MaleText_loc5`='我忘記了嗎?我當然忘了...我已經忘了生命的...愛，和快樂。', `MaleText_loc7`='¿Que si lo he olvidado? Por supuesto que sí... He olvidado lo que es el amor, la felicidad... la vida misma.' WHERE `ID`=11839;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만, 사랑은 우리의 몸과 마음을 약하게 하는걸. 누군가를 아끼는 마음 때문에 남에게 이용당할 수도 있지. 아날리스, 그대의 사랑이 아니더라도 난 해야 할 일이 있어.', `MaleText_loc4`='但是我知道，爱情让心灵和身体变得脆弱。没有你的爱，我只剩下了工作，安娜利丝。', `MaleText_loc5`='我當然知道這些 - 愛讓心靈和身體都變的軟弱。它是會被剝削的。沒有你的愛，我就只剩下工作了，安娜莉斯。', `MaleText_loc7`='Pero sé que el amor debilita el corazón y el cuerpo. Se le puede sacar partido. Sin tu amor, tan solo me queda mi trabajo, Annalise.' WHERE `ID`=11840;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='스태프론! 그대를 정말 사랑해요. 그대의 고통이 제 마음을 아프게 한다는 걸 아시나요.', `FemaleText_loc4`='我当然爱你，斯塔弗隆。看到你这样痛苦，我也心如刀割。', `FemaleText_loc5`='但我當然愛你，史塔弗隆。我看你這麼痛苦我也很難受。', `FemaleText_loc7`='Pero yo te quiero, Staffron, y me duele verte sufrir.' WHERE `ID`=11841;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='영원히 당신을 사랑하리라 맹세했습니다. 죽음도 그 약속을 지울 수는 없었지요. 전 그대가 아직도 저에 대한 사랑을 기억하리라 믿어요.', `FemaleText_loc4`='我发誓将永远爱你。死亡也无法让我的爱褪色，我相信你仍然记得你爱着我。', `FemaleText_loc5`='我發誓永遠愛你。至死不渝，我相信你永遠會記得對我的愛。', `FemaleText_loc7`='Te prometo amor incondicional. Ni la muerte podrá destruirlo pues sé que todavía recuerdas el amor que sientes por mí.' WHERE `ID`=11842;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그대가 날 사랑하지 않는다면 정말 마음 아플 거예요.', `FemaleText_loc4`='如果你不爱我了，那么我就真的被遗忘了。', `FemaleText_loc5`='如果你不愛，我就真的一無所有了。', `FemaleText_loc7`='Y si no es así, entonces estoy perdida.' WHERE `ID`=11843;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아날리스, 어떻게 날 사랑할 수가 있지? 날 보라고. 지금의 난 한 때 그대가 알던 스태프론이 아니야.', `MaleText_loc4`='你怎么能爱我呢，安娜利丝？看看我吧。我不是你曾经熟悉的那个人。', `MaleText_loc5`='你怎麼可以愛我，安娜莉斯?看著我。我已經不再是你從前認識的那個男人了。', `MaleText_loc7`='¿Cómo puedes amarme, Annalise? Mírame. No soy el hombre que una vez conociste.' WHERE `ID`=11844;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아날리스? 오, 아날리스! 안 돼! 날 떠나지 마!', `MaleText_loc4`='安娜利丝？安娜利丝！不！不要离开我！', `MaleText_loc5`='安娜莉斯?安娜莉斯!不，不要丟下我!', `MaleText_loc7`='¿Annalise? ¡Annalise! ¡No, no me abandones!' WHERE `ID`=11845;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아날리스... 당신이 옳아. 난... 할 수 없어. 다른 방법을 찾아야 해.', `MaleText_loc4`='安娜利丝……你是对的。我……我办不到。我得另想办法。', `MaleText_loc5`='安娜莉斯...你是對的。我 - 我可以做到的。我一定要找別的辦法。', `MaleText_loc7`='Annalise... Tienes razón. Yo... no puedo hacer esto. Tiene que haber otro modo.' WHERE `ID`=11846;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기, 자네! 나의 가마솥 안에 든 것을 가져가도 좋아. 이제 두 번째 작전을 시작할 때로군. 사랑을 부르는 옷감 말일세.', `MaleText_loc4`='嘿，欢迎你来闻闻我制造的香水。我的计划要进行下一步，漂亮的衣服！', `MaleText_loc5`='嘿。你可以自由拿取我大鍋裡的東西。這是我第二階段的計畫- 多情的服飾。', `MaleText_loc7`='¡Eh! Puedes coger lo que hay dentro de mi caldera. Era la segunda parte de mi plan: ropa sensual.' WHERE `ID`=11847;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='둘 다 서로 찾을 수밖에 없는 비련의 연인이로군요. 당신의 미래에 큰 행복이 있을 겁니다.', `MaleText_loc4`='你们真是天造地设的一对！你们的未来充满了快乐。', `MaleText_loc5`='你們倆真是對不幸的情人。未來還有很多幸福在等著你們的。', `MaleText_loc7`='Sois sin duda dos amantes malhadados que se han encontrado. Tenéis un futuro muy prometedor.' WHERE `ID`=11848;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말이 많군요! 불같은 성격의 소유자들이 만나서 그래요! 둘이 말다툼은 좀 많이 하겠는데 그래도 사랑은 뜨겁게 타오를 거예요!', `MaleText_loc4`='啊哈！两个炽热的灵魂！你们会有许多争吵，但你们的爱情也会同样热烈！', `MaleText_loc5`='天啊!兩個激烈的個性。你們會有很多爭執，但你們的愛也會一樣轟轟烈烈!', `MaleText_loc7`='¡Huy! Ambos tienen una fuerte personalidad. ¡Discutirán mucho pero su amor será ardiente!' WHERE `ID`=11850;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 생각대로만 밀어붙이려 한다면, 끝내는 각자의 길을 가게 될 겁니다.', `MaleText_loc4`='虽然你们努力维持彼此的关系，但最终还是会分道扬镳。', `MaleText_loc5`='雖然你試著努力，但是最後，你們還是會分道揚鑣。', `MaleText_loc7`='Aunque intentaréis que funcione, al final, seguiréis caminos separados.' WHERE `ID`=11851;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='둘 사이에 힘든 일도 좋은 일도 많을 테지만 처음의 마음을 소중히 간직한다면 값진 열매로 다가올 것입니다.', `MaleText_loc4`='你们两个人之间将会发生许多事情，但只要坚持到底，必定苦尽甘来。', `MaleText_loc5`='你們倆共同度過許多快樂與悲傷，如果能堅持下去，一切都是值得的。', `MaleText_loc7`='Tendréis muchos altibajos, pero si sabéis superarlos os merecerá la pena.' WHERE `ID`=11852;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 미래에 결혼 축가가 울려 퍼지는 소리가 들리는군요.', `MaleText_loc4`='我在你的未来里面听到了婚礼的钟声。', `MaleText_loc5`='我在你的未來聽到響亮的婚禮鐘聲。', `MaleText_loc7`='Veo campanas de boda en tu futuro.' WHERE `ID`=11853;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='둘의 미래에 먹구름이 끼었습니다. 하지만, 당신이 관계를 잘 이끌기 위해 노력한다면, 서로 행복의 기준을 조율할 수 있으리라 믿습니다.', `MaleText_loc4`='你们的未来疑云密布。如果你们双方都努力的话，我相信还是会有许多温馨的事情发生。', `MaleText_loc5`='未來對你們兩人來說不太樂觀。如果你們能努力經營關係，我相信你們可以找到一些快樂的方法。', `MaleText_loc7`='Tienen un futuro turbio. Si luchan por su relación, estoy seguro de que hallarán la felicidad.' WHERE `ID`=11854;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최종 집계 결과를 알려드릴게요.$B$B스랄: $2200w$B$B케른: $2201w$B$B실바나스: $2202w$B$B호드 전체: $2207w$B$B$B볼바르: $2203w$B$B마그니: $2204w$B$B티란데: $2205w$B$B얼라이언스 전체: $2206w$b$b가장 인기 많은 영웅은 얼라이언스에 있네요!', `MaleText_loc4`='最终的排名是！$B$B萨尔：$2200w$B$B凯恩：$2201w$B$B希尔瓦娜斯：$2202w$B$B部落总计：$2207w$B$B$B伯瓦尔：$2203w$B$B麦格尼：$2204w$B$B泰兰德：$2205w$B$B联盟总计：$2206w$B$B联盟的英雄人气最高！', `MaleText_loc5`='這是最後的排行榜!$B$B索爾:$2200w$B凱恩:$2201w$B希瓦娜斯:$2202w$B部落總票數:$2207w$B$B伯瓦爾:$2203w$B麥格尼:$2204w$B泰蘭妲:$2205w$B聯盟總票數:$2206w$B$B聯盟擁有最受歡迎的英雄!', `MaleText_loc7`='¡Esta es la clasificación final!$B$BThrall: $2200w$BCairne: $2201w$BSylvanas: $2202w$BTotal de la Horda: $2207w$B$BBolvar: $2203w$BMagni: $2204w$BTyrande: $2205w$BTotal de la Alianza: $2206w$B$B¡La Alianza cuenta con $gel héroe:la heroína; más popular!', `FemaleText_loc1`='최종 집계 결과를 알려드릴게요.$B$B스랄: $2200w$B$B케른: $2201w$B$B실바나스: $2202w$B$B호드 전체: $2207w$B$B$B볼바르: $2203w$B$B마그니: $2204w$B$B티란데: $2205w$B$B얼라이언스 전체: $2206w$b$b가장 인기 많은 영웅은 얼라이언스에 있네요!', `FemaleText_loc4`='最终的排名是！$B$B萨尔：$2200w$B$B凯恩：$2201w$B$B希尔瓦娜斯：$2202w$B$B部落总计：$2207w$B$B$B伯瓦尔：$2203w$B$B麦格尼：$2204w$B$B泰兰德：$2205w$B$B联盟总计：$2206w$B$B联盟的英雄人气最高！', `FemaleText_loc5`='這是最後的排行榜!$B$B索爾:$2200w$B凱恩:$2201w$B希瓦娜斯:$2202w$B部落總票數:$2207w$B$B伯瓦爾:$2203w$B麥格尼:$2204w$B泰蘭妲:$2205w$B聯盟總票數:$2206w$B$B聯盟擁有最受歡迎的英雄!', `FemaleText_loc7`='¡Esta es la clasificación final!$B$BThrall: $2200w$BCairne: $2201w$BSylvanas: $2202w$BTotal de la Horda: $2207w$B$BBolvar: $2203w$BMagni: $2204w$BTyrande: $2205w$BTotal de la Alianza: $2206w$B$B¡La Alianza cuenta con $gel héroe:la heroína; más popular!' WHERE `ID`=11856;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최종 집계 결과를 알려드릴게요.$B$B스랄: $2200w$B$B케른: $2201w$B$B실바나스: $2202w$B$B호드 전체: $2207w$B$B$B볼바르: $2203w$B$B마그니: $2204w$B$B티란데: $2205w$B$B얼라이언스 전체: $2206w$b$b가장 인기 좋은 영웅은 호드에 있네요!', `MaleText_loc4`='最终的排名是！$B$B萨尔：$2200w$B$B凯恩：$2201w$B$B希尔瓦娜斯：$2202w$B$B部落总计：$2207w$B$B$B伯瓦尔：$2203w$B$B麦格尼：$2204w$B$B泰兰德：$2205w$B$B联盟总计：$2206w$B$B部落的英雄人气最高！', `MaleText_loc5`='這是最後的排行榜!$B$B索爾:$2200w$B凱恩:$2201w$B希瓦娜斯:$2202w$B部落總票數:$2207w$B$B伯瓦爾:$2203w$B麥格尼:$2204w$B泰蘭妲:$2205w$B聯盟總票數:$2206w$B$B部落擁有最受玩家歡迎的英雄!', `MaleText_loc7`='¡Esta es la clasificación final!$B$BThrall: $2200w$BCairne: $2201w$BSylvanas: $2202w$BTotal de la Horda: $2207w$B$BBolvar: $2203w$BMagni: $2204w$BTyrande: $2205w$BTotal de la Alianza: $2206w$B$B¡La Horda cuenta con $gel héroe:la heroína; más popular!', `FemaleText_loc1`='최종 집계 결과를 알려드릴게요.$B$B스랄: $2200w$B$B케른: $2201w$B$B실바나스: $2202w$B$B호드 전체: $2207w$B$B$B볼바르: $2203w$B$B마그니: $2204w$B$B티란데: $2205w$B$B얼라이언스 전체: $2206w$b$b가장 인기 좋은 영웅은 호드에 있네요!', `FemaleText_loc4`='最终的排名是！$B$B萨尔：$2200w$B$B凯恩：$2201w$B$B希尔瓦娜斯：$2202w$B$B部落总计：$2207w$B$B$B伯瓦尔：$2203w$B$B麦格尼：$2204w$B$B泰兰德：$2205w$B$B联盟总计：$2206w$B$B部落的英雄人气最高！', `FemaleText_loc5`='這是最後的排行榜!$B$B索爾:$2200w$B凱恩:$2201w$B希瓦娜斯:$2202w$B部落總票數:$2207w$B$B伯瓦爾:$2203w$B麥格尼:$2204w$B泰蘭妲:$2205w$B聯盟總票數:$2206w$B$B部落擁有最受玩家歡迎的英雄!', `FemaleText_loc7`='¡Esta es la clasificación final!$B$BThrall: $2200w$BCairne: $2201w$BSylvanas: $2202w$BTotal de la Horda: $2207w$B$BBolvar: $2203w$BMagni: $2204w$BTyrande: $2205w$BTotal de la Alianza: $2206w$B$B¡La Horda cuenta con $gel héroe:la heroína; más popular!' WHERE `ID`=11857;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 자유다! 자, 이제 힘을 합쳐 제 누이 자리엔을 구하죠!', `MaleText_loc4`='我自由了！让我们共同努力，拯救我的姐姐亚雷恩！', `MaleText_loc5`='我自由了!現在讓我們同心協力拯救我的妹妹，賈林!', `MaleText_loc7`='¡Soy libre! ¡Unamos ahora nuestras fuerzas para salvar a mi hermana, Jarien!' WHERE `ID`=11858;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여러분 모두에게 감사합니다! 저와 제 누이는 이제 자유의 몸으로 안식을 찾게 되었답니다.', `MaleText_loc4`='谢谢你们让我和姐姐重获自由！我们终于可以安息了。', `MaleText_loc5`='謝謝你們解救了我，我的姐妹，和你們所有人!我們現在終於可以安息了。', `MaleText_loc7`='¡Gracias por liberarme, querida hermana! ¡Y gracias a todos ustedes! Por fin podemos descansar en paz.' WHERE `ID`=11859;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 고통은 끝나고 전 여신님 곁으로 갈 수 있게 되었어요. 정말 감사합니다!', `FemaleText_loc4`='苦难的日子终于到头了，现在我能追随女神而去了。非常感谢你！', `FemaleText_loc5`='我的痛苦結束了，現在我可以加入女神的行列。非常感謝你們!', `FemaleText_loc7`='Mi tortura ha terminado y ya puedo reunirme con la diosa. ¡Muchas gracias!' WHERE `ID`=11860;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 평화 속에 잠들겠지만 당신에게는 절대 잊지 못할 은혜를 입었습니다. 어리석음과 탐욕으로 인해 저주받은 저를 구해주셔서 감사합니다.', `MaleText_loc4`='尽管我要就此长眠了，但临走前我还是要向你们表达我的感激。谢谢你将我从这因愚蠢和贪婪所导致的诅咒中解脱出来。', `MaleText_loc5`='雖然我平靜的離開，但我永遠不會忘記對你們的感謝。謝謝你們從我愚蠢和貪婪的詛咒中解救了我。', `MaleText_loc7`='Aunque ahora vaya en paz, os estaré eternamente agradecido. Gracias por liberarme de la maldición de mi insensatez y avaricia.' WHERE `ID`=11861;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기까지 들어오다니 정말 영리하군, $n.$B$B뭐라고? 네 이름을 알고 있어서 깜짝 놀랐다고? 이봐, 나는 악마라고. 그게 우리가 하는 일이지. 너의 진짜 이름도 알고 있어. 그러니 비싼 물건을 사는 게 신상에 좋을 거야.', `MaleText_loc4`='哇，你居然进来了，很聪明呀，$n。$B$B什么？我怎么知道你的名字？嘿，朋友，你看我虽小，却也是个恶魔了，这就是我们恶魔的能力。我还知道你的真名呢，所以你最好只买贵的，不买对的。', `MaleText_loc5`='你進來這裡的方法實在很聰明，$n。$B$B什麼?很驚訝我知道你的名字嗎?我是個惡魔，這是我們做的事。我還知道你本名，所以你最好買點昂貴的東西走。', `MaleText_loc7`='Has demostrado gran habilidad en tu modo de entrar aquí, $n.$B$B¿Qué? ¿Te sorprende que sepa tu nombre? Soy un demonio, es nuestro trabajo. También conozco tu verdadero nombre así que es mejor que me compres algo caro.' WHERE `ID`=11862;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법봉 때문에 왔나? 아니면 단지 룬을 사 모으기 위해?$B$B잠깐! 혹시 어떻게 한 번 쓰레기 같은 물건이나 처분해 볼까 하고 온 건 아니겠지?! 내 끊임없이 네게 물건을 사라고 강요할 테니 두고 봐. 어서 물건을 사, 사, 사란 말이야!', `MaleText_loc4`='想要买魔杖？或者你只是想要囤积一些符文？$B$B等等！你该不是想把这堆垃圾扔给我吧？！该死，我怎么就控制不了自己的购买欲呢！', `MaleText_loc5`='來買魔棒?還是你只是在進符文的貨?$B$B等等!你該不會只是想把一堆垃圾卸貨給我?!詛咒我永無止境的購買慾望!', `MaleText_loc7`='¿Vienes a por la vara? ¿O simplemente quieres comprar runas?$B$B¡Espera un momento! ¿Intentas cargarme con un montón de porquerías? ¡Maldita sea mi eterna obsesión por comprar, comprar y comprar!' WHERE `ID`=11863;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐라고? 아니, 나는 갑옷 수리는 하지 않아. 북쪽으로 1.6킬로미터쯤 가면 눈망루 마을이 있으니 그리 가 보라고.$B$B자, 이제 물건을 사라고. 아니면 냉큼 없어지는 게 좋을걸! 내가 흑마법사를 소환해서 혼쭐을 내주기 전에 말이야.', `MaleText_loc4`='啥？我才不做盔甲维修的生意呢。永望镇就离这里不到一里地，$g伙计:小姐;。$B$B现在，赶紧买点什么吧，不然我就把我的术士召唤出来，把你给秒了！', `MaleText_loc5`='什麼?不，我不修理護甲的。永望鎮就在北方一哩處，$g兄弟:姐妹;。$B$B現在買個東西吧，不然就在我召喚我的術士對付你前快點消失!', `MaleText_loc7`='¿Qué? No, no reparo armaduras. Vista Eterna está a tan solo una milla en dirección norte, $ghermano: hermana;.$B$B¡Y ahora compra algo o desaparece antes de que llame a mi brujo para que se ocupe de ti!' WHERE `ID`=11864;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 가지고 있는 물건을 좀 볼 텐가?', `MaleText_loc4`='想看看我出售的货物吗？', `MaleText_loc5`='我可以給你看看我賣的東西嗎?', `MaleText_loc7`='¿Quieres ver lo que vendo?' WHERE `ID`=11865;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선물세트를 만든 다음 그걸로 뭘 해야 하죠?', `MaleText_loc4`='如果我有一份大礼包，我能拿它干些什么？', `MaleText_loc5`='如果我製作了一個禮物典藏品，要拿它來做什麼好呢?', `MaleText_loc7`='Y si reúno una colección de regalos, ¿qué hago con ella?', `FemaleText_loc1`='선물세트를 만든 다음 그걸로 뭘 해야 하죠?', `FemaleText_loc4`='如果我有一份大礼包，我能拿它干些什么？', `FemaleText_loc5`='如果我製作了一個禮物典藏品，要拿它來做什麼好呢?', `FemaleText_loc7`='Y si reúno una colección de regalos, ¿qué hago con ella?' WHERE `ID`=11866;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파멸자의 봉우리로 가고 싶다면 말씀만 하세요. 저에게는 당신과 당신의 동료를 이동시킬 수 있는 능력이 있답니다.', `MaleText_loc4`='如果你想要拜访污染者高地，尽管开口好了。我会把你和你的同伴传送过去的。', `MaleText_loc5`='如果你想見識污染者的發源地，你只要開口就好。我可以將你和你的夥伴傳送過去。', `MaleText_loc7`='Si deseas visitar el Alto de los Rapiñadores, tan solo tienes que pedirlo. Puedo llevarte a ti y a tus camaradas.' WHERE `ID`=11868;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='봉우리로 보내 주십시오.', `MaleText_loc4`='我们希望能够亲自挑战污染者。', `MaleText_loc5`='我們想挑戰污染者。', `MaleText_loc7`='Deseamos enfrentarnos al Rapiñador.', `FemaleText_loc1`='봉우리로 보내 주세요.', `FemaleText_loc4`='我们希望能够亲自挑战污染者。', `FemaleText_loc5`='我們想挑戰污染者。', `FemaleText_loc7`='Deseamos enfrentarnos al Rapiñador.' WHERE `ID`=11869;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳 시민들에게 사랑의 징표를 건네주면 답례로 다양한 선물을 받게 될 거예요. 그중 몇 가지는 손님께서 지니고 사용하고 싶어하실 테지만, 다른 것들은 한데 묶어서 당신이 좋아하는 영웅에게 바칠 수 있어요! 덜렁발 큐이피를 찾아서 선물세트를 주세요.$B$B큐이피는 케른 님, 실바나스 님, 스랄 님 곁에서 찾을 수 있을 겁니다.', `MaleText_loc4`='当你把爱情信物交给城镇里的居民时，你可以收到各种礼物作为回报。一些礼物最好留起来用，另一些则最好放在一起做成一个大礼品包！$B$B去找匹德菲特为你喜欢的英雄投票吧。$B$B你可以在凯恩、希尔瓦娜斯或者萨尔身边找到匹德菲特。', `MaleText_loc5`='當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄!拜訪丘比特·傳播者把禮物交給他。$B$B傳播者就在凱恩，希瓦娜斯和索爾附近。', `MaleText_loc7`='Cuando entregues pruebas de amor a los habitantes de la ciudad, recibirás diferentes regalos a cambio. Algunos podrás guardarlos y utilizarlos, ¡mientras que otros podrás juntarlos y dárselos a tu $ghéroe favorito:heroína favorita;! Visita a Kwee Q. Pies Rápidos y entrégaselos.$B$BEncontrarás a Kwee cerca de Cairne, Sylvanas o Thrall.', `FemaleText_loc1`='이곳 시민들에게 사랑의 징표를 건네주면 답례로 다양한 선물을 받게 될 거예요. 그중 몇 가지는 손님께서 지니고 사용하고 싶어하실 테지만, 다른 것들은 한데 묶어서 당신이 좋아하는 영웅에게 바칠 수 있어요! 덜렁발 큐이피를 찾아서 선물세트를 주세요.$B$B큐이피는 케른 님, 실바나스 님, 스랄 님 곁에서 찾을 수 있을 겁니다.', `FemaleText_loc4`='当你把爱情信物交给城镇里的居民时，你可以收到各种礼物作为回报。一些礼物最好留起来用，另一些则最好放在一起做成一个大礼品包！$B$B去找匹德菲特为你喜欢的英雄投票吧。$B$B你可以在凯恩、希尔瓦娜斯或者萨尔身边找到匹德菲特。', `FemaleText_loc5`='當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄!拜訪丘比特·傳播者把禮物交給他。$B$B傳播者就在凱恩，希瓦娜斯和索爾附近。', `FemaleText_loc7`='Cuando entregues pruebas de amor a los habitantes de la ciudad, recibirás diferentes regalos a cambio. Algunos podrás guardarlos y utilizarlos, ¡mientras que otros podrás juntarlos y dárselos a tu $ghéroe favorito:heroína favorita;! Visita a Kwee Q. Pies Rápidos y entrégaselos.$B$BEncontrarás a Kwee cerca de Cairne, Sylvanas o Thrall.' WHERE `ID`=11870;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<PH> 신참 마법사 <PH>', `MaleText_loc4`='<PH> Incoming Mages <PH>', `MaleText_loc5`='<PH> Incoming Mages <PH>', `MaleText_loc7`='<PH> Incoming Mages <PH>' WHERE `ID`=11871;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최종 득표 순위입니다!$B$B스랄: $2200w$B$B케른: $2201w$B$B실바나스: $2202w$B$B호드 전체: $2207w$B$B$B볼바르: $2203w$B$B마그니: $2204w$B$B티란데: $2205w$B$B얼라이언스 전체: $2206w$B$B전체 호드와 얼라이언스의 득표가 동점입니다!', `MaleText_loc4`='最终的排名是！$B$B萨尔：$2200w$B$B凯恩：$2201w$B$B希尔瓦娜斯：$2202w$B$B部落总计：$2207w$B$B$B伯瓦尔：$2203w$B$B麦格尼：$2204w$B$B泰兰德：$2205w$B$B联盟总计：$2206w$B$B联盟和部落平分秋色！', `MaleText_loc5`='這是最後的排行榜!$B$B索爾:$2200w$B$B凱恩:$2201w$B$B希瓦娜斯:$2202w$B$B部落總票數:$2207w$B$B$B伯瓦爾:$2203w$B$B麥格尼:$2204w$B$B泰蘭妲:$2205w$B$B聯盟總票數:$2206w$B$B部落與聯盟的票數勢均力敵!', `MaleText_loc7`='¡Esta es la clasificación final!$B$BThrall: $2200w$B$BCairne: $2201w$B$BSylvanas: $2202w$B$BTotal de la Horda: $2207w$B$BBolvar: $2203w$B$BMagni: $2204w$B$BTyrande: $2205w$B$BTotal de la Alianza: $2206w$B$B¡La Horda y la Alianza han obtenido el mismo número de votos!' WHERE `ID`=11872;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 자유다! 고맙다, 작고 연약한 존재여...', `MaleText_loc4`='我们自由了！谢谢你们！', `MaleText_loc5`='我們自由了!謝謝你，小傢伙。', `MaleText_loc7`='¡Somos libres! Gracias, pequeñajos.' WHERE `ID`=11873;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 책의 페이지는 찢어졌습니다.', `MaleText_loc4`='这本书的内页已经被毁了。', `MaleText_loc5`='這本書的書頁已經被毀掉了。', `MaleText_loc7`='Las páginas de este libro han sido destruidas.' WHERE `ID`=11874;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='책 속에 수백 개의 그림과 도표들이 나타나기 시작합니다. 그중 몇몇 그림을 알아볼 수 있습니다. 나머지 그림은 눈에 익기는 하지만 알 수 없는 것입니다.', `MaleText_loc4`='书中记载了多张结构图。有的是你已经掌握的结构图，还有的虽然看着眼熟，却是你未曾学习过的图纸。', `MaleText_loc5`='幾千個不同的圖表和結構圖開始在書頁上成形。你認得其中一些圖表，其他的看起來既陌生又熟悉。', `MaleText_loc7`='Cientos de diagramas y esquemas empiezan a tomar forma en las páginas del libro. Reconoces algunos de los diagramas mientras otros siguen siendo extraños aunque te resulten familiares.' WHERE `ID`=11875;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 꼭 고블린 기계공학을 배우고 싶습니다.', `MaleText_loc4`='我100%地确定要在地精工程学这条路上走到底。', `MaleText_loc5`='我百分之百確定我想學習哥布林工程學。', `MaleText_loc7`='Estoy 100% seguro de que deseo aprender el arte de la ingeniería goblin.', `FemaleText_loc1`='저는 꼭 고블린 기계공학을 배우고 싶어요.', `FemaleText_loc4`='我100%地确定要在地精工程学这条路上走到底。', `FemaleText_loc5`='我百分之百確定我想學習哥布林工程學。', `FemaleText_loc7`='Estoy 100% segura de que deseo aprender el arte de la ingeniería goblin.' WHERE `ID`=11876;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='', `MaleText_loc4`='', `MaleText_loc5`='', `MaleText_loc7`='' WHERE `ID`=11877;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 꼭 노움 기계공학을 배우고 싶습니다.', `MaleText_loc4`='我100%地确定要在侏儒工程学这条路上走到底。', `MaleText_loc5`='我百分之百確定我想學習地精工程學。', `MaleText_loc7`='Estoy 100% seguro de que deseo aprender el arte de la ingeniería gnómica.', `FemaleText_loc1`='저는 꼭 노움 기계공학을 배우고 싶어요.', `FemaleText_loc4`='我100%地确定要在侏儒工程学这条路上走到底。', `FemaleText_loc5`='我百分之百確定我想學習地精工程學。', `FemaleText_loc7`='Estoy 100% segura de que deseo aprender el arte de la ingeniería gnómica.' WHERE `ID`=11878;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너의 운명은 결정됐다, 델리아나! 군주 발타라크 님께 죗값을 치르게 될 것이다!', `MaleText_loc4`='你的命运已经注定了，德莉亚娜！冒犯了瓦塔拉克公爵，你就要付出代价！', `MaleText_loc5`='你的命運已經決定了，德莉娜!你會因為侵犯瓦薩拉克領主而付出代價!', `MaleText_loc7`='¡Tu destino está escrito, Deliana! ¡Pagarás por los pecados cometidos contra Lord Valthalak!', `FemaleText_loc1`='너의 운명은 결정됐다, 델리아나! 군주 발타라크 님께 죗값을 치르게 될 것이다!', `FemaleText_loc4`='你的命运已经注定了，德莉亚娜！冒犯了瓦塔拉克公爵，你就要付出代价！', `FemaleText_loc5`='你的命運已經決定了，德莉娜!你會因為侵犯瓦薩拉克領主而付出代價!', `FemaleText_loc7`='¡Tu destino está escrito, Deliana! ¡Pagarás por los pecados cometidos contra Lord Valthalak!' WHERE `ID`=11879;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러니까 잊어버린 내용을 다시 배우고 싶다 이 말이오? 아니면 아직 배워본 적이 없는 것을? 내가 아는 대로만 얘기해주지, $n. 여기서 동쪽으로 스팀휘들 항구를 지나 나라인의 오두막에 가면 ''왕초보를 위한 예언 완전정복''이라는 마법책을 찾을 수 있을 거요. 그 책을 읽어보시오.$B$B<윙크하는 닉스>$B$B당신이 알아야 할 모든 것을 찾을 수 있을 것이오. 그럼...', `MaleText_loc4`='这么说，你想要重新学习那些被遗忘的技能？或是学习全新的知识？我倒是可以为你指条明路，$n。去热砂港以东纳瑞安的巢穴寻找一本名叫《傻瓜预言书》的魔法书。翻开看看吧。$B$B<尼克斯眨巴着眼睛。>$B$B你会发现书中记载了你想要了解的东西，甚至还有……', `MaleText_loc5`='你想重新學習忘記的東西，是嗎?還是學習你從沒學過的東西?我了解，$n。在熱砂港東邊，你會在納里安的小屋裡找到一本魔法書，叫做「新手的預言入門」。讀讀它。$B$B<尼克斯眨了眨眼。>$B$B你會找到所有你該知道的還有一些...', `MaleText_loc7`='Conque quieres aprender de nuevo lo que has olvidado, ¿eh? ¿O quizás aprender lo que nunca has sabido? Mira, $n. Al este del Puerto Bonvapor, encontrarás un libro mágico en la cabaña de Narain titulado "Adivinar el futuro para torpes". Échale una ojeada.$B$B<Nixx guiña un ojo.>$B$BEncontrarás todo lo que necesitas saber y mucho más...' WHERE `ID`=11880;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='날 쫓는 일을 포기하진 않겠지? 좋아. 덤벼! 절대 굴복하지 않겠어!', `FemaleText_loc4`='你似乎不愿意放弃尾随我的行动，是吗？那么好吧，让我们一较高下！', `FemaleText_loc5`='你永遠都要緊跟著我，是不是?好，要擊倒我就先來打一場!', `FemaleText_loc7`='¿Nunca vas a dejar de perseguirme? ¡Muy bien, pero no me dejaré vencer sin luchar!' WHERE `ID`=11881;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노움 기계공학을 가르쳐 달라고? 그런 일은 절대 없을 거야! 어쨌든 나는 가르쳐 줄 수 없어. 자네에게서 좋지 않은 냄새가 나거든. $n, 자네가 불쌍해서 하는 말인데 조언 하나 하지.$B$B타나리스 사막에 가면 나라인 수스팬시의 오두막을 찾을 수 있지. 그 오두막 안에는 기적을 일으킬 수 있다고 알려진 마법책이 있어. 그 책을 찾으면 노움 기계공학을 배울 수 있을 거야.', `MaleText_loc4`='教你侏儒工程学？不可能的！至少我这个侏儒不会。你真让人讨厌，$n。算了，既然你诚心诚意地来找我，那我就大发慈悲地告诉你。$B$B在塔纳利斯沙漠里，你可以找到一个叫纳瑞安的侏儒，他有一本很神奇的魔法书。在那本书的帮助下，你或许可以学习到侏儒的工程学。', `MaleText_loc5`='教你地精工程學?不可能!你身上有一股惡臭，$n。或許這段談話只是可憐你，不過我會提供一些建議。$B$B在塔納利斯沙漠找到納里安·柔想的小屋。那個小屋裡有一本魔法書，可以做出驚奇的事物。找到那本書你就可以學習地精的方法了。', `MaleText_loc7`='¿Enseñarte el arte de la ingeniería gnómica? ¡Jamás! No yo, al menos. Apestas, $n. Quizás sea solo por compasión pero te voy a dar un consejo.$B$BEn el Desierto de Tanaris encontrarás una cabaña propiedad de Narain Sabelotodo. En esa cabaña se encuentra un libro que tiene fama de hacer prodigios. Encuéntralo y tendrás la oportunidad de aprender el arte gnómico.' WHERE `ID`=11882;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n, 당신을 이 일에 끌어들이고 싶지는 않았습니다. 우리가 군주 발타라크의 마법책 훔치는 일에 착수한 후로 관련된 모든 자들이 죽거나 실종됐으니 말이죠.', `FemaleText_loc4`='我不是有意拉你下水的，$n。自从我们接受了盗取瓦塔拉克公爵的法术书的任务，每个与此相关的人都重伤至死或是干脆失踪了。', `FemaleText_loc5`='我並非故意拖你捲入其中，$n。自從我接下了偷竊瓦薩拉克領主的魔法書的任務，所有相關的人不是死了就是失蹤。', `FemaleText_loc7`='No pretendía meterte en este lío, $n.Todos los que han intentado hacerse con el libro de hechizos de Lord Valthalak acabaron muertos o no aparecieron nunca más.' WHERE `ID`=11883;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노움 기계공학을 가르쳐 달라고? 이런 헛소리에 낭비할 시간은 없어. 자네에게는 오글소프에게 배울 기회가 딱 한 번 있었는데 그걸 날려 버렸지, 그렇지 않는가?$B$B타나리스로 가서 나라인 수스팬시의 오두막을 찾아봐. 그 오두막에 가면 자네 머릿속에 남아 있는 내용과 까먹은 내용을 연결해 줄 수 있는 마법책이 있을 거야.$B$B이제 그만 가보라고!', `MaleText_loc4`='教你侏儒工程学？我可没时间做这些没有意义的事。你只有一次选择的机会，并且你已经做出了选择，对不？$B$B要不你就去塔纳利斯找纳瑞安吧。他的小屋里有本魔法书，或许能把你的脑子处理处理，让你重新得到已经失去的东西。$B$B现在就去吧！', `MaleText_loc5`='教你地精工程學?我可沒空做這無意義的事。你只有一次和奧格索普學習的機會而你搞砸了，對吧?$B$B你要前往塔納利斯找到納里安·柔想的小屋。那個小屋裡有一本魔法書，可能和你腦袋裡剩下的東西很相近，可以重新連結起你失去的知識。$B$B現在快滾吧!', `MaleText_loc7`='¿Enseñarte ingeniería gnómica? No tengo tiempo para tonterías. Tienes una única oportunidad con Oglethorpe y la desperdicias, ¿no?$B$BTendrás que ir a Tanaris y encontrar la cabaña de Narain Sabelotodo. En esa cabaña hay un libro mágico que probablemente aún pueda hacer algo con lo poco que te queda de cerebro y resucitar algunas de tus neuronas.$B$B¡Y ahora lárgate!' WHERE `ID`=11884;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 처한 곤경에 대해 더 자세히 알아보는 것은 거의 불가능했어요. 몰래 우리 고용을 알선한 자는 사라지고 우리 용병단 대장인 안시온 하몬은 죽었습니다.', `FemaleText_loc4`='我要想摆脱眼下这种尴尬的处境几乎是不可能的了。那个雇用我们的走私者已经消失得无影无踪，雇佣军团的头子安泰恩·哈尔蒙也死了。', `FemaleText_loc5`='要更了解我目前的處境實在是不太可能。僱用我們的走私者不見了，而我們傭兵公司的老闆，安希恩·哈莫，也已經死了。', `FemaleText_loc7`='Me ha resultado imposible conseguir más información acerca del tema que me preocupa. El contrabandista que nos contrató ha desaparecido y Anthion Harmon, el líder de nuestra compañía de mercenarios, está muerto.' WHERE `ID`=11885;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='생각해 보세요. 관련된 이들이 거의 모두 죽었어요. $n, 이런 일에 연루되고 싶지 않다고 하셔도 이해할 수 있습니다.', `FemaleText_loc4`='动点脑子想想吧，涉及此事的人差不多都死了。我能理解你想置身事外的心情，$n。', `FemaleText_loc5`='想想，大部分捲入這件事的人都死了。如果你不想被捲入其中，我能理解，$n。', `FemaleText_loc7`='Ahora que lo pienso, todos los relacionados con el tema están muertos. Entiendo que no quieras involucrarte, $n.' WHERE `ID`=11888;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용비늘 가죽세공을 꼭 배우고 싶습니다.', `MaleText_loc4`='我确信自己要学习龙鳞制皮的技能。', `MaleText_loc5`='我非常確定我想學習龍鱗的製皮技術。', `MaleText_loc7`='Estoy totalmente convencido de que quiero aprender peletería dragontina.', `FemaleText_loc1`='용비늘 가죽세공을 꼭 배우고 싶습니다.', `FemaleText_loc4`='我确信自己要学习龙鳞制皮的技能。', `FemaleText_loc5`='我非常確定我想學習龍鱗的製皮技術。', `FemaleText_loc7`='Estoy totalmente convencida de que quiero aprender peletería dragontina.' WHERE `ID`=11889;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원소 가죽세공을 꼭 배우고 싶습니다.', `MaleText_loc4`='我确信自己要学习元素制皮的技能。', `MaleText_loc5`='我非常確定我想學習元素的製皮技術。', `MaleText_loc7`='Estoy totalmente convencido de que quiero aprender peletería elemental.', `FemaleText_loc1`='원소 가죽세공을 꼭 배우고 싶습니다.', `FemaleText_loc4`='我确信自己要学习元素制皮的技能。', `FemaleText_loc5`='我非常確定我想學習元素的製皮技術。', `FemaleText_loc7`='Estoy totalmente convencida de que quiero aprender peletería elemental.' WHERE `ID`=11890;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전통 가죽세공을 꼭 배우고 싶습니다.', `MaleText_loc4`='我确信自己要学习部族制皮的技能。', `MaleText_loc5`='我非常確定我想學習部族的製皮技術。', `MaleText_loc7`='Estoy totalmente convencido de que quiero aprender Peletería tribal.', `FemaleText_loc1`='전통 가죽세공을 꼭 배우고 싶습니다.', `FemaleText_loc4`='我确信自己要学习部族制皮的技能。', `FemaleText_loc5`='我非常確定我想學習部族的製皮技術。', `FemaleText_loc7`='Estoy totalmente convencida de que quiero aprender Peletería tribal.' WHERE `ID`=11891;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 눈앞에 각종 이미지와 형상, 표시들이 펼쳐집니다. 책은 당신이 가죽세공 기술을 익혔다는 사실을 알고 있는 것 같으며 당신에게 선택권을 줍니다. 하지만, 알아 둘 것이 있습니다. 단 하나만 선택할 수 있으며 일단 결정한 후에는 바꿀 수 없습니다.', `MaleText_loc4`='无数的图象、幻影与标记同时出现在你的脑海中。这本书似乎知道你在制皮方面的技术成就一般，并给了你一个选择的机会，但是请注意，你只能选择一次！', `MaleText_loc5`='影像，形狀，和記號的組合出現在你眼前。這本書似乎了解你的製皮技術並提供你一個選擇 - 但是警告你 - 你只能做一個選擇，並且一旦決定後，就不能改變心意!:', `MaleText_loc7`='La gama de imágenes y formas aparecen ante tus ojos. El libro parece conocer tu habilidad para la peletería y te deja elegir una. Pero ten cuidado pues una vez que hagas tu elección ¡no podrás cambiar de parecer!:' WHERE `ID`=11892;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모크바르, 네 운명은 결정됐다! 발타라크 군주님의 소유물에 손을 댄 벌을 받게 될 것이야!', `MaleText_loc4`='你的命运已定，莫尔克瓦！冒犯了瓦塔拉克公爵，你就要付出代价！', `MaleText_loc5`='你的命運已經決定了，莫克瓦!你會因為侵犯瓦薩拉克領主而付出代價!', `MaleText_loc7`='¡Tu destino está escrito, Mokvar! ¡Pagarás por los pecados cometidos contra Lord Valthalak!', `FemaleText_loc1`='모크바르, 네 운명은 결정됐다! 발타라크 군주님의 소유물에 손을 댄 벌을 받게 될 것이야!', `FemaleText_loc4`='你的命运已定，莫尔克瓦！冒犯了瓦塔拉克公爵，你就要付出代价！', `FemaleText_loc5`='你的命運已經決定了，莫克瓦!你會因為侵犯瓦薩拉克領主而付出代價!', `FemaleText_loc7`='¡Tu destino está escrito, Mokvar! ¡Pagarás por los pecados cometidos contra Lord Valthalak!' WHERE `ID`=11893;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 용비늘 가죽세공을 가르쳐 줄 수 없소, $n. 타나리스로 가서 나라인 수스팬시의 집을 찾아보시오. 도착하면 ''왕초보를 위한 예언 완전정복''이라는 책을 찾아서 읽어보시오.', `MaleText_loc4`='我不能教你龙鳞制皮，$n。你得前往塔纳利斯寻找纳瑞安的家。那本名叫《傻瓜预言书》的书会对你有所帮助的。', `MaleText_loc5`='我不能教你龍鱗的製皮技術，$n。你一定要去塔納利斯找到納里安·柔想的家。到了那裡，參照「新手的預言入門」這本書。', `MaleText_loc7`='No puedo enseñarte peletería dragontina, $n. Has de ir a Tanaris y encontrar la casa de Narain Sabelotodo. Una vez allí, consulta el libro "Adivinar el futuro para torpes".' WHERE `ID`=11894;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사라져라, 타락한 존재여! 네 주인이 너를 창조한 무의 세계로 돌아가라!', `MaleText_loc4`='你这污秽的家伙，滚！回到你主人身边去！', `MaleText_loc5`='去死吧!邪惡的生物!回到你主人創造你的地方去!', `MaleText_loc7`='¡Marchaos, criaturas apestosas! ¡Volved al agujero del que habéis salido!' WHERE `ID`=11895;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 당신을 이 일에 끌어들인 건 내 뜻이 아니었소. 난 오랜 친구를 도와 검은바위 첨탑에 무모한 공격을 감행한 후부터 늘 주변을 경계해 왔소.', `MaleText_loc4`='我并不是有意拉你下水的，$n。黑石塔发生过一场可怕的遭遇战，我在那场战争中救过一个老朋友，从那以后我随时都保持着高度的警惕。', `MaleText_loc5`='我的本意不是要讓你捲入這件事，$n。自從我幫了一個老朋友參加黑石塔上的襲擊後，我無時無刻都在提高警覺。', `MaleText_loc7`='No pretendía involucrarte en esto, $n. Desde que ayudé a $gun viejo amigo:una vieja amiga; en un osado ataque a Cumbre de Roca Negra, no duermo tranquilo.' WHERE `ID`=11896;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들에 대해 더 자세히 알아보려고 했지만 쉽지 않았소. 그리고 내 친구와 군주 발타라크의 마법책을 훔치기 위해 고용한 용병들이 계속 죽음의 공포에 시달리고 있소.', `MaleText_loc4`='有关这些生物的底细查找起来并不容易。我的朋友和那个雇佣迷雾之刃去偷瓦塔拉克公爵的法术书的家伙非死即疯。', `MaleText_loc5`='想多了解這些生物不是那麼簡單的。我的朋友，和僱用其傭兵去偷瓦薩拉克領主的魔法書的人有陣子都害怕會死。', `MaleText_loc7`='No ha sido sencillo conseguir más información acerca de estas criaturas. Mi $gamigo:amiga; y la persona que contrató a sus mercenarios para robar el libro de hechizos de Lord Valthalak se teme que hayan muerto.' WHERE `ID`=11897;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 일에 관련된 모든 이들이 하나씩 차례로 이 유령에게 희생되고 있소. 그러니 이런 일에 연루되고 싶지 않다고 해도 이해할 수 있소.', `MaleText_loc4`='一个接着一个，几乎所有人都成为了这些幽灵的猎物。如果你最终决定远离我们这摊子事，我能够理解，$n。', `MaleText_loc5`='一個接一個，幾乎所有捲入這件事的人都成為這些幽靈的犧牲品。如果你想抽身，我可以理解，$n。', `MaleText_loc7`='Uno a uno, casi todos los involucrados en este tema han caído presa de estos espectros. Comprendería que decidieras darle la espalda a este tema, $n.' WHERE `ID`=11898;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전 원소 가죽세공을 가르쳐 줄 수 없어요, $n. 타나리스로 가서 나라인 수스팬시의 집을 찾아보세요. 나라인 수스팬시의 집에 도착하면 "왕초보를 위한 예언 완전정복"이라는 책을 읽어 보세요.', `FemaleText_loc4`='我不能教你元素制皮，$n。你得前往塔纳利斯寻找纳瑞安的家。那本名叫《傻瓜预言书》的书会对你有所帮助的。', `FemaleText_loc5`='我不能教你元素的製皮技術，$n。你一定要去塔納利斯找到納里安·柔想的家。到了那裡，參照「新手的預言入門」這本書。', `FemaleText_loc7`='No puedo enseñarte peletería elemental, $n. Has de ir a Tanaris y encontrar la casa de Narain Sabelotodo. Una vez allí, consulta el libro "Adivinar el futuro para torpes".' WHERE `ID`=11899;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 원소 가죽세공을 가르쳐 줄 수 없네, $n. 타나리스로 가서 나라인 수스팬시의 집을 찾아보게. 도착하면 ''왕초보를 위한 예언 완전정복''이라는 책을 찾아서 읽어보도록!', `MaleText_loc4`='我不能教你元素制皮，$n。你得前往塔纳利斯寻找纳瑞安的家。那本名叫《傻瓜预言书》的书会对你有所帮助的。', `MaleText_loc5`='我不能教你元素的製皮技術，$n。你一定要去塔納利斯找到納里安·柔想的家。到了那裡，參照「新手的預言入門」這本書。', `MaleText_loc7`='No puedo enseñarte peletería elemental, $n. Has de ir a Tanaris y encontrar la casa de Narain Sabelotodo. Una vez allí, consulta el libro "Adivinar el futuro para torpes".' WHERE `ID`=11900;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전 전통 가죽세공을 가르쳐 드릴 수 없습니다, $n. 타나리스로 가서 나라인 수스팬시의 집을 찾아보세요. 도착하면 ''왕초보를 위한 예언 완전정복''이라는 책을 찾아서 꼭 읽어보시고요.', `FemaleText_loc4`='我不能教你部族制皮，$n。你得前往塔纳利斯寻找纳瑞安的家。那本名叫《傻瓜预言书》的书会对你有所帮助的。', `FemaleText_loc5`='我不能教你部族的製皮技術，$n。你一定要去塔納利斯找到納里安·柔想的家。到了那裡，參照「新手的預言入門」這本書。', `FemaleText_loc7`='No puedo enseñarte Peletería tribal, $n. Has de ir a Tanaris y encontrar la casa de Narain Sabelotodo. Una vez allí, consulta el libro "Adivinar el futuro para torpes".' WHERE `ID`=11901;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 전통 가죽세공을 가르쳐 줄 수 없네, $n. 타나리스로 가서 나라인 수스팬시의 집을 찾아보게. 도착하면 ''왕초보를 위한 예언 완전정복''이라는 책을 찾아서 꼭 읽어보게나.', `MaleText_loc4`='我不能教你部落制皮，$n。你得前往塔纳利斯寻找纳瑞安的老巢。那本名叫“Soothsaying for Dummies”的书会对你有所帮助的。', `MaleText_loc5`='我不能教你部族的製皮技術，$n。你一定要去塔納利斯找到納里安·柔想的家。到了那裡，參照「新手的預言入門」這本書。', `MaleText_loc7`='No puedo enseñarte Peletería tribal, $n. Has de ir a Tanaris y encontrar la casa de Narain Sabelotodo. Una vez allí, consulta el libro "Adivinar el futuro para torpes".' WHERE `ID`=11902;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 이곳에 계속 머물 수 있었던 것도 정말 다행스러운 일이 아닐 수 없소. 하지만, 너무 오래 머물러 폐를 끼치고 싶지는 않소이다. 나로 인해 우리의 수도에 어떤 문제라도 생긴다면 정말 수치스러운 일이 아닐 수 없으니까.', `MaleText_loc4`='我很高兴能在这里继续我的追求。但我也不想在这里停留得过久。要是给我们的主城带来了麻烦，那我就太可耻了。', `MaleText_loc5`='太好了，我獲准入城繼續追擊下去。無論如何，我不求久留。給我們的主城帶來任何麻煩都是極大的侮辱。', `MaleText_loc7`='Me alegra que se me haya permitido continuar con mis actividades aquí. De ningún modo quisiera abusar de la hospitalidad. Causar problemas en nuestra capital sería una gran deshonra para mí.' WHERE `ID`=11903;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='시선을 너무 많이 끌지 않도록 하세요. 저는 의회에서 찾아뵐 기회를 주시길 기다리고 있답니다. 기다리는 일만 아니라면 주위에 듬직한 경비병들이 있으니 꽤 안전하다는 생각이 드네요.', `FemaleText_loc4`='请尽量不要引起太多注目，我正在等待议会的召见。我并不介意多等一会儿，这儿到处是身材魁梧的守卫，我感到非常安全。', `FemaleText_loc5`='盡量別引來太多注目，我正等著覲見議會。我不介意等待，在這些魁梧的守衛旁邊我覺得相當有安全感。', `FemaleText_loc7`='Intenta no llamar mucho la atención. Estoy esperando a que el Consejo me conceda audiencia. No es que me importe esperar... de hecho, me siento bastante segura rodeada de todos estos fornidos guardias.' WHERE `ID`=11904;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='목숨을 잃게 된 것은 어쩔 수 없는 현실로 받아들였소. 하지만, 이시다를 잃는다는 것은 죽고 난 후에도 도저히 견딜 수 없는 일이외다.', `MaleText_loc4`='面对危险时我选择了妥协并由此送了命。但是即便是死了，我也无法承受失去伊思达的悲痛。', `MaleText_loc5`='喪命的危險是我常碰到的事。但失去亞希達是我不能容忍的事，就算我死了也是一樣。', `MaleText_loc7`='Perder la vida era un riesgo que había aceptado. Sin embargo, perder a Ysida es algo que no puedo soportar, incluso tras mi propia muerte.' WHERE `ID`=11905;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑네, 친구! 심령체 충전기에 대해 설명을 좀 해 볼까? 아니면 정밀하고도 근사한 무지향성 심령 융화기는 어때?', `MaleText_loc4`='你好，朋友！你对灵质装载器感兴趣吗？或者是看看全向鬼灵同化器？', `MaleText_loc5`='你好，朋友!想不想看一些精華電容器?或是精細的全方位鬼靈吸收器?', `MaleText_loc7`='¡Saludos, $gamigo:amiga;! ¿Puedo ofrecerte un condensador ectoplásmico? ¿O quizás un fabuloso asimilador de espectros omnidireccional?' WHERE `ID`=11906;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일이죠? 지금 바쁜 거 안 보입니까?', `MaleText_loc4`='什么事？你没看见我很忙吗？', `MaleText_loc5`='什麼事?你沒看到我正在忙嗎?', `MaleText_loc7`='¿Y ahora qué? ¿No ves que estoy ocupado?' WHERE `ID`=11907;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='추출기를 잃어버린 것 같습니다, 먹스. 제가 추출기를 여기 뒀나요?', `MaleText_loc4`='我似乎将提纯器弄丢了，穆克斯。我是不是把它放这儿了？', `MaleText_loc5`='我好像把那個蒸餾器弄丟了，莫克斯。我有把它留在這裡嗎?', `MaleText_loc7`='No sé dónde he puesto el destilador, Mux. ¿Por casualidad lo he dejado aquí?', `FemaleText_loc1`='추출기를 잃어버린 것 같습니다, 먹스. 제가 추출기를 여기 뒀나요?', `FemaleText_loc4`='我似乎将提纯器弄丢了，穆克斯。我是不是把它放这儿了？', `FemaleText_loc5`='我好像把那個蒸餾器弄丟了，莫克斯。我有把它留在這裡嗎?', `FemaleText_loc7`='No sé dónde he puesto el destilador, Mux. ¿Por casualidad lo he dejado aquí?' WHERE `ID`=11908;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='유령 탐색기 말인데요. 제가 여기에 뒀었나요? 유령 탐색기를 잃어버린 것 같습니다.', `MaleText_loc4`='关于幽灵显形器。我是不是把它放这儿了？要么就是我把它给弄丢了……', `MaleText_loc5`='那個捕鬼器。我有不小心留在這裡嗎?我好像把它弄丟了。', `MaleText_loc7`='¿Por casualidad he dejado aquí el detector de fantasmas? Creo que lo he perdido.', `FemaleText_loc1`='유령 탐색기 말인데요. 제가 여기에 뒀었나요? 유령 탐색기를 잃어버린 것 같습니다.', `FemaleText_loc4`='关于幽灵显形器。我是不是把它放这儿了？要么就是我把它给弄丢了……', `FemaleText_loc5`='那個捕鬼器。我有不小心留在這裡嗎?我好像把它弄丟了。', `FemaleText_loc7`='¿Por casualidad he dejado aquí el detector de fantasmas? Creo que lo he perdido.' WHERE `ID`=11909;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='팔린, 당신이 마법을 걸어 준 깃발을 잃어버린 것 같습니다.', `MaleText_loc4`='我想我将你附过魔法的旗子放错了地方，法尔林。', `MaleText_loc5`='我想我把你給我的附魔旌旗弄丟了，法琳。', `MaleText_loc7`='Creo que he perdido el estandarte que encantaste para mí, Falrin.', `FemaleText_loc1`='팔린, 당신이 마법을 걸어 둔 그 깃발을 잃어버린 것 같아요.', `FemaleText_loc4`='我想我将你附过魔法的旗子放错了地方，法尔林。', `FemaleText_loc5`='我想我把你給我的附魔旌旗弄丟了，法琳。', `FemaleText_loc7`='Creo que he perdido el estandarte que encantaste para mí, Falrin.' WHERE `ID`=11910;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안시온, 당신이 만들어 준 깃발을 잃어버린 것 같습니다.', `MaleText_loc4`='我想我将你替我制作的旗子放错了地方，安泰恩。', `MaleText_loc5`='安希恩，我好像把你做給我的旌旗弄丟了。', `MaleText_loc7`='Anthion, no sé dónde he puesto el estandarte que hiciste para mí.', `FemaleText_loc1`='안시온, 당신이 만들어 준 깃발을 잃어버린 것 같아요.', `FemaleText_loc4`='我想我将你替我制作的旗子放错了地方，安泰恩。', `FemaleText_loc5`='安希恩，我好像把你做給我的旌旗弄丟了。', `FemaleText_loc7`='Anthion, no sé dónde he puesto el estandarte que hiciste para mí.' WHERE `ID`=11911;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 거의 마무리된 것 같군요. 그렇죠? $n, 당신이 그리울 거예요... 여기에서 말벗도 없이 혼자 지낸다는 건 정말 힘든 일이거든요.$B$B그렇다고 나중에 들르지 말라는 얘기는 절대 아니니까 오해 마세요!', `MaleText_loc4`='我想事情都结束了是吧，$n？我会想你的……没人陪我说话，我一定会非常寂寞的。$B$B但是，欢迎你随时回来看望我！', `MaleText_loc5`='我想一切就要結束了，對吧$n?我會想你的...在這裡沒有人聊聊會很寂寞。$B$B但你以後還是可以回來看看我!', `MaleText_loc7`='Supongo que todo ha terminado, ¿verdad, $n? Te voy a echar de menos... Me sentiré muy solo aquí sin nadie con quien poder hablar.$B$B¡Pero eso no significa que no puedas venir a visitarme en el futuro!' WHERE `ID`=11912;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비엘, 당신이 파는 물건을 보여주십시오!', `MaleText_loc4`='嗨，维尔，让我看看你出售的货物！', `MaleText_loc5`='嘿，維爾，讓我看看你的物品!', `MaleText_loc7`='¡Eh Vi''el, enséñame tu mercancía!', `FemaleText_loc1`='비엘, 당신이 파는 물건을 보여주세요!', `FemaleText_loc4`='嗨，维尔，让我看看你出售的货物！', `FemaleText_loc5`='嘿，維爾，讓我看看你的物品!', `FemaleText_loc7`='¡Eh Vi''el, enséñame tu mercancía!' WHERE `ID`=11913;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아뮬렛을 가지고 와! 도둑맞은 내 물건!', `MaleText_loc4`='还我饰品！把你从我这里偷走的东西还给我！', `MaleText_loc5`='帶回護符!把被偷走的東西帶回來給我!', `MaleText_loc7`='¡Devuélveme el amuleto! ¡Devuélveme lo que me ha sido robado!' WHERE `ID`=11914;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보들리, 무슨 일인지 말해 주십시오.', `MaleText_loc4`='伯德雷，告诉我发生了什么事。', `MaleText_loc5`='布德利，告訴我發生了什麼事。', `MaleText_loc7`='Bodley, cuéntame qué está pasando.', `FemaleText_loc1`='보들리, 무슨 일인지 말해 주세요.', `FemaleText_loc4`='伯德雷，告诉我发生了什么事。', `FemaleText_loc5`='布德利，告訴我發生了什麼事。', `FemaleText_loc7`='Bodley, cuéntame qué está pasando.' WHERE `ID`=11915;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말하자면, 아주 간단해요, $n. 내가 예전에 참여했던 용병단인 감춰진 칼날단은 좋지 않은 시기에 잘못된 임무를 맡았어요.$B$B그렘닉 리즐스프랭이라는 무법항의 고블린 마법사가 우리를 고용했는데 군주 발타라크의 마법책에 욕심이 아주 아주 많았답니다. 아니면 오래된 경쟁 관계라도 있었던 것일까요? 어쨌든 이제 그 이유는 알 수가 없게 되었어요. 얼마 전 그렘닉이 발타라크의 암살자 유령에게 살해되었거든요. 암살자 유령들이 떼로 덤비면 굉장히 위험해요.$B$B음... 내가 어디까지 말했죠?', `MaleText_loc4`='很简单，$n。我先前所在的雇佣军团“迷雾之刃”在错误的时间接受了错误的任务。$B$B藏宝海湾外的一名地精走私者格雷姆尼克对瓦塔拉克公爵的法术书垂涎三尺，因此他雇用我们盗取那本法术书。或许还有其他人觊觎着这本书吧，我想我们是无法知道当时的真实情况了，因为不久之前格雷姆尼克就被瓦塔拉克公爵的鬼灵刺客杀死了。这些鬼灵刺客联合行动的话，谁也别想生还。$B$B我说到哪儿了？', `MaleText_loc5`='其實這很簡單，真的，$n。我的舊傭兵公司，隱刃，在錯的時候接下了錯的任務。$B$B我們被一個藏寶海灣的哥布林走私者僱用，一個叫格雷姆尼克的人，他覬覦瓦薩拉克領主的魔法書。或是說，可能在過去曾互相較勁?我想我們現在是不會知道的，因為格雷姆尼克不久前被瓦薩拉克的一群鬼靈刺客殺了。他們成群結隊時還真的很恐怖。$B$B我說到哪了?', `MaleText_loc7`='En realidad, es bastante sencillo, $n. Mi antigua compañía de mercenarios, La Espada Enmascarada, aceptó la misión equivocada en el momento equivocado.$B$BNos contrató un goblin contrabandista en Bahía del Botín, un tal Gremnik Saltatrabas, que codiciaba el libro de hechizos de Lord Valthalak. Es posible que hubiera cierta rivalidad entre ellos... pero supongo que eso nunca lo sabremos pues Gremnik murió no hace mucho a manos de un grupo de asesinos espectrales enviados por Valthalak. Si se presentan en gran número pueden resultar muy peligrosos.$B$B¿Por dónde iba?' WHERE `ID`=11916;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감춰진 칼날단과 당신이 어떻게 해서 잘못된 임무를 맡게 되었는지 말하던 중이었습니다.', `MaleText_loc4`='你在告诉我有关迷雾之刃的事情，以及你们怎样错误地接手了这个任务。', `MaleText_loc5`='你正和我說到隱刃還有你是如何接下錯誤的任務。', `MaleText_loc7`='Me estabas hablando de La Espada Enmascarada y de cómo aceptasteis una misión que no deberíais haber aceptado.', `FemaleText_loc1`='감춰진 칼날단과 당신이 어떻게 해서 잘못된 임무를 맡게 되었는지 말하던 중이었습니다.', `FemaleText_loc4`='你在告诉我有关迷雾之刃的事情，以及你们怎样错误地接手了这个任务。', `FemaleText_loc5`='你正和我說到隱刃還有你是如何接下錯誤的任務。', `FemaleText_loc7`='Me estabas hablando de La Espada Enmascarada y de cómo aceptasteis una misión que no deberíais haber aceptado.' WHERE `ID`=11917;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 거기까지 했었죠.$B$B그래서 우리는 검은바위 첨탑의 상층부 깊숙한 곳까지 잠입했었죠. 그곳의 주인이자 사령관을 목표로 해서요. 바로 드라키사스 말입니다. 왜 그런 현명하지 못한 임무를 맡았느냐고 묻고 싶은 건가요? 당신이 만났던 우리 대장 안시온 하몬 님은 도전을 좋아하는 사람이었답니다.$B$B놀랍게도 발타라크의 뻣뻣하게 굳은 손가락이 마법책을 꺼낼 때까지는 모든 일이 순조롭게 진행되었죠. 하지만, 그 후로 일이 꼬이기 시작했어요.$B$B계속 얘기할 필요가 있을까요? 당신 눈이 가물가물하는 것 같은데...', `MaleText_loc4`='哦，是的。$B$B后来我们就侵入了黑石塔上层的深处，决定去挖掘他们的头目与领主所拥有的财富，哦，是达基萨斯之前的那一任。现在你要问我，我确实觉着这不是个聪明的决定，可我们的队长安泰恩·哈蒙，你见过他的，他是一个非常喜欢挑战与冒险的人。$B$B令我们吃惊的是，一切竟都按计划顺利的进行着，我们还得到了瓦塔拉克的法术书……那本书就握在他僵硬的手里。$B$B还要继续吗？你的眼睛里似乎有点困意。', `MaleText_loc5`='喔，對，沒錯。$B$B所以，我們就在這裡入侵黑石塔上層，對抗他們的主人和領導者;這是在達基薩斯之前。如果你問我，我是覺得不太明智，但是我們的領導者，安希恩·哈莫，你見過他，他總是喜歡挑戰。$B$B令人驚訝的是，一切都如計畫中進行的一樣，直到我們從魔法書上扳開瓦薩拉克僵硬的手指。這就是一切不幸的開始。$B$B我要繼續嗎?你看起來眼神很呆滯。', `MaleText_loc7`='Ah sí, es verdad.$B$BBien, pues invadimos Cumbre de Roca Negra en contra de su señor y líder; esto fue antes de Drakkisath. No fue muy inteligente por nuestra parte pero a nuestro líder Anthion Harmon, tú lo conociste, siempre le han gustado los retos.$B$BSorprendentemente, todo iba según lo previsto hasta el momento en el que le arrebatamos el libro de hechizos a Valthalak de sus entumecidas manos. Ahí es cuando todo se torció.$B$B¿Puedo continuar? Parece que te pasa algo en los ojos.' WHERE `ID`=11918;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아뇨, 그럴 리가 있습니까? 계속 얘기해 주세요! 그러니까... 음, 여기 공기가... 좀 탁해서요.', `MaleText_loc4`='不，不，请继续……这里的空气……似乎，呃，有点浑浊……', `MaleText_loc5`='不，不，請繼續...我只是覺得這裡的空氣很，呃，煙霧彌漫。', `MaleText_loc7`='Sí, sí, por favor continúa... es que el aire aquí está... cargado.', `FemaleText_loc1`='아뇨, 그럴 리가 있나요? 얘기 계속해 주세요! 그러니까... 음, 여기 공기가... 좀 탁해서요.', `FemaleText_loc4`='不，不，请继续……这里的空气……似乎，呃，有点浑浊……', `FemaleText_loc5`='不，不，請繼續...我只是覺得這裡的空氣很，呃，煙霧彌漫。', `FemaleText_loc7`='Sí, sí, por favor continúa... es que el aire aquí está... cargado.' WHERE `ID`=11919;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<의심스러운 눈초리로 당신을 쏘아보다가 얘기를 계속하는 보들리>$B$B결국, 우리는 마법책을 손에 넣었지요. 그때 머리가 둘 달린 우리의 오우거 강령술사 코르모크의 네 개의 눈빛이 이상하게 변했어요. 정말 소름끼치는 장면이었죠. 두 번째 머리에 달린 눈은 꼭 죽은 자의 것과 같았거든요. 소의 눈처럼 말이에요. 상상이 가시죠? 그러다가 그가 갑자기 팔을 뻗어 발타라크가 걸고 있던 아뮬렛을 벗겨내지 뭐예요.$B$B나머지 동료는 난리가 났죠. 우리 중 일부는 아뮬렛을 그대로 두라고 외쳐댔지만... 아뮬렛을 독차지하려는 자들도 있었답니다.', `MaleText_loc4`='<伯德雷满腹疑虑地盯着你，但是他还是继续说了下去……>$B$B我们终于把法术书弄到手了。库尔莫克，这个双头食人魔法师，两双眼睛中闪烁着怪异的光芒，令人毛骨悚然。他有一双毫无生气的眼睛，就像牛眼睛一样，你知道吗？就在此时，他突然伸出手，一把抓住了瓦塔拉克公爵的饰品。$B$B这一举动令大家炸了窝，一些人坚持要夺回饰品，另一些人则劝说他们不要争抢。', `MaleText_loc5`='<布德利懷疑地看著你，但仍繼續...>$B$B我們到了那裡，拿到了魔法書，而科爾莫克，我們的雙頭死靈法師，他的四隻眼睛裡流露出這個奇怪的眼神。那真的令人毛骨悚然，因為那第二對眼睛總是看起來死氣沉沉，像牛的眼睛一樣，你懂嗎?所以，突然間他就伸出手把瓦薩拉克所配戴的護符撕扯下來。$B$B公司裡剩下的人全瘋了;我們之中有一些人告訴其他人別去管那死靈法師，也有些人想將護符佔為己有。', `MaleText_loc7`='<Bodley te mira con recelo pero prosigue...>$B$BAllí estábamos, con el libro de hechizos en las manos, cuando advertimos algo extraño en la mirada de Kormok, nuestro ogro nigromántico de dos cabezas. Era algo espeluznante pues su segundo par de ojos siempre era inexpresivo, como los de una vaca, ¿entiendes? Y de repente se acercó a Valthalak y le arrancó el amuleto que llevaba encima.$B$BLos demás miembros de la compañía enloquecieron; algunos les decíamos que lo dejaran tranquilo mientras que otros también ansiaban hacerse con el amuleto.' WHERE `ID`=11920;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래서요, 보들리?', `MaleText_loc4`='请继续，伯德雷。', `MaleText_loc5`='請繼續，布德利。', `MaleText_loc7`='Por favor Bodley, continúa.', `FemaleText_loc1`='그래서요, 보들리?', `FemaleText_loc4`='请继续，伯德雷。', `FemaleText_loc5`='請繼續，布德利。', `FemaleText_loc7`='Por favor Bodley, continúa.' WHERE `ID`=11921;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐요, 그렇게 재촉하지 마세요! 어쨌든 내 얘기는 거의 끝났어요.$B$B그래서 우리는 모두 그 거대한 방의 한가운데에서 아뮬렛을 놓고 싸우기 시작했답니다. 그 안이 얼마나 난장판이 되었을지 상상이 가시죠? 결국, 아뮬렛은 세 조각으로 부서졌고 그곳에는 제각기 서로 다른 목적으로 온 자들이 있었기에 우리는 주사위를 굴렸답니다.$B$B나머지 이야기는 좀 우울해요. 왜냐하면, 그때 즈음 발타라크의 영혼이 암살자 유령들을 소환하기로 결심했거든요.', `MaleText_loc4`='咳，你也不用求我呀！无论如何，这个故事已经快讲完了。$B$B当时，全兵团的人都进入那个大房间里，为争夺饰品而战，你可以想象那里的回声有多大！最后，它裂成三部分，我们决定投骰子来决定这三部分饰品的归属。$B$B最后的事我已经有点记不清了，或许是因为那时候老瓦塔拉克的灵魂开始出现在尘世间，并召唤了那些幽灵刺客。', `MaleText_loc5`='哎呀，你不需乞求!總之，我已經快完成故事了。$B$B所以，整個公司就在那個巨大的房間中央為了那個護符爭吵，你知道這在那裡是如何產生回響的!最後它斷成三塊，然後我們擲骰子，讓它們分給不同的人或團體。$B$B剩下的就有點模糊不清了，因為那時候老瓦薩拉克的靈魂便決定製造一個入口，開始召喚所有的鬼靈刺客。', `MaleText_loc7`='Shhh, ¡no es necesario que supliques! De todos modos, ya estoy acabando.$B$BLa compañía al completo luchaba en esa inmensa cámara por conseguir el amuleto ¡y no sabes el eco que había allí! Finalmente, el amuleto se rompió en tres pedazos y cada uno de ellos fue a parar a una persona o grupo de personas.$B$BLo que pasó después no lo recuerdo bien porque en ese momento el viejo espíritu de Valthalak decidió hacer su entrada y empezar a invocar a todos esos asesinos espectrales.' WHERE `ID`=11922;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래도 거의 성공한 것 아니었습니까?', `MaleText_loc4`='完了？', `MaleText_loc5`='我以為你快完成了?', `MaleText_loc7`='Creí que ya estabas acabando.', `FemaleText_loc1`='그래도 거의 성공한 것 아니었나요?', `FemaleText_loc4`='完了？', `FemaleText_loc5`='我以為你快完成了?', `FemaleText_loc7`='Creí que ya estabas acabando.' WHERE `ID`=11923;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조급해 하지 마세요!$B$B<살아 있는 자들은 참을성이 부족하다고 낮은 소리로 불평하는 보들리>$B$B앞서 말했듯이 군주 발타라크의 영혼과 강령술로 소환한 그의 암살자 유령들이 우리를 공격하기 시작했어요. 그때, 우리는 도저히 맞서 싸울 수 있는 상태가 아니었기에 달아나기 시작했죠. 아직도 생생히 기억나는군요. 우리 드루이드 중의 하나인 모르 그레이후프가 그만 미끄러져서 첨탑의 하층부로 떨어지고 말았답니다.$B$B나머지는 당신이 알고 있는 그대로고요.', `MaleText_loc4`='别急呀！$B$B<伯德雷发着牢骚，对你的缺乏耐心表示不满。>$B$B就像我说的那样，被召唤出的瓦塔拉克公爵的灵魂和鬼灵刺客对我们发动了攻击。而那时我们根本无力与之抗衡，因此我们选择了逃亡。我还记得，有个名叫莫尔·灰蹄的德鲁伊在混乱中倒地，长眠在黑石塔下层。$B$B剩下的那些事情，都已经是历史了……', `MaleText_loc5`='冷靜下來!$B$B<布德利低聲抱怨了一下生活的不耐煩>$B$B正如我所說的，從他的巫術中被召喚出來的瓦薩拉克領主的靈魂和鬼靈刺客，開始對我們展開攻擊了。讓我告訴你，當時我們的狀態並不適合迎擊，所以只能跑。我還記得我們德魯伊中的一員，莫爾·灰蹄，在某處失足滑落塔的較低層。$B$B其他的就如同他們所說的，都是過去式了。', `MaleText_loc7`='¡Para el carro!$B$B<Bodley se queja por lo bajo de la impaciencia de los vivos>$B$BComo iba diciendo, el espíritu de Lord Valthalak y los asesinos espectrales que este invocó a través de prácticas de nigromancia, empezaron a atacarnos. Créeme, en ese momento no estábamos en condiciones de seguir luchando así que huimos. Todavía recuerdo cómo Mor Pezuña Gris, uno de nuestros druidas, resbaló y cayó montaña abajo.$B$BLo demás, como suelen decir, ya es historia.' WHERE `ID`=11924;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 용병단, 감춰진 칼날단에 무슨 일이 생겼습니까?', `MaleText_loc4`='你所属的雇佣兵团迷雾之刃到底怎么了？', `MaleText_loc5`='你的隱刃傭兵公司怎麼了?', `MaleText_loc7`='¿Qué fue de tu compañía de mercenarios, La Espada Enmascarada?', `FemaleText_loc1`='당신의 용병단, 감춰진 칼날단에 무슨 일이 생겼습니까?', `FemaleText_loc4`='你所属的雇佣兵团迷雾之刃到底怎么了？', `FemaleText_loc5`='你的隱刃傭兵公司怎麼了?', `FemaleText_loc7`='¿Qué fue de tu compañía de mercenarios, La Espada Enmascarada?' WHERE `ID`=11925;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 후, 우리는 헤어졌어요. 그게 전부랍니다. 쓸데없는 피를 너무 많이 흘렸나봐요... 어느 정도는 예정된 일이었다고 생각해요. 그리고 아뮬렛은 고생만 잔뜩 하게 하는 아무짝에도 쓸모없는 것이었죠.$B$B이후로 발타라크의 노예들은 우리를 하나씩 제거했어요. 아뮬렛 조각을 지니고 있던 이들은 대부분 죽어 영혼까지 아뮬렛에 담긴 발타라크의 영혼 조각에 의해 오염되었죠.$B$B당신이 여기 온 것에 내가 기뻐하는 이유가 바로 그 때문이에요, $n. 당신이 도와준다면 아뮬렛을 다시 하나로 합쳐 군주 발타라크에게 돌려줄 수 있을 테니까요!', `MaleText_loc4`='我们最后就散伙了，这就是那时发生的一切。死了太多的人，我想……这是最终酝酿出的结果。饰物的事就像是压在科多兽背上的最后一根稻草。$B$B自那以后，瓦塔拉克的仆人将我们一个一个地干掉了。大多数身上带有饰品碎片的人都死了，他们的灵魂也被瓦塔拉克的幽灵所污染了。$B$B这就是为什么看到你在这里我如此高兴的原因，$n。有了你的帮助，或许我们能重新聚合起饰品，并把它还给瓦塔拉克。', `MaleText_loc5`='我們之後解散了，就是這麼一回事。有太多的仇恨，我想...這已經累積好一陣子了。而有著護符的那個東西就是弄傷科多獸背部的爛東西。$B$B從此以後瓦薩拉克的奴僕們就開始將我們一個個剷除掉。大部分的護符碎片持有者都死了，他們的靈魂都被禁錮其中的瓦薩拉克領主的靈魂給污染了。$B$B這就是為什麼我這麼高興你在這裡的原因，$n。有你的幫助我們就能重新組合護符並將它還給瓦薩拉克!', `MaleText_loc7`='Se disolvió poco después, eso es lo que pasó. Supongo que a causa del resentimiento que había ido creciendo... Y el tema del amuleto fue la gota que colmó el vaso.$B$BDesde entonces, los sirvientes de Valthalak nos han buscado uno por uno. La mayor parte de los que poseían uno de los fragmentos del amuleto están muertos y sus almas corruptas ya que parte del espíritu de Valthalak impregnaba el amuleto.$B$BPor eso me alegro de que estés aquí, $n. Con tu ayuda seremos capaces de reconstruir el amuleto y devolvérselo a Lord Valthalak.' WHERE `ID`=11926;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성가신 $n! 네놈의 운명도 여기까지다. 군주 발타라크께서 반드시 복수하실 것이다!', `MaleText_loc4`='你的末日到了，$n！瓦塔拉克公爵就要开始他的复仇了！', `MaleText_loc5`='你可以不用再插手了，$n!瓦薩拉克領主會採取他的復仇!', `MaleText_loc7`='¡Ya no tienes nada que hacer, $n! ¡Lord Valthalak obtendrá la venganza que ansía!', `FemaleText_loc1`='성가신 $n! 네놈의 운명도 여기까지다. 군주 발타라크께서 반드시 복수하실 것이다!', `FemaleText_loc4`='你的末日就要到了，$n！Lord Valthalak就要开始他的复仇啦！', `FemaleText_loc5`='你可以不用再插手了，$n!瓦薩拉克領主會採取他的復仇!', `FemaleText_loc7`='¡Ya no tienes nada que hacer, $n! ¡Lord Valthalak obtendrá la venganza que ansía!' WHERE `ID`=11927;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기, 당신 친구들입니까?', `MaleText_loc4`='是你的朋友吗？', `MaleText_loc5`='你的朋友?', `MaleText_loc7`='¿Amigos tuyos?' WHERE `ID`=11928;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='화면 아래, 행동 단축바 위에 있는 통통 전차 단축 바를 이용하여 다른 통통 전차를 공격하십시오.', `MaleText_loc4`='使用在标准动作条上的坦克动作条，攻击其他坦克。', `MaleText_loc5`='用你的標準快捷列上方的坦克快捷列來攻擊其他坦克。', `MaleText_loc7`='Usa tu barra de acción de tonque, sobre tu barra de acción estándar, para atacar a otros tonques.' WHERE `ID`=11929;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n, 이제 저는 괜찮을 테니 제 걱정은 마세요. 이 방에서 정화 의식을 치른 후 여기서 벗어날 수 있는 방법을 찾을 겁니다. 사악한 마법이 이곳을 더럽히고 있어요.', `FemaleText_loc4`='我感觉好多了，别担心我。我要在这间房间里进行净化仪式，在那之后我自然会设法离开的。这儿被邪恶的魔法力量污染了，$n。', `FemaleText_loc5`='我現在很好，別擔心我。等我在這房間裡進行一些淨化儀式後就會想辦法出去。邪惡的魔法污染了這個地方，$n。', `FemaleText_loc7`='Estaré bien, no te preocupes por mí. Saldré de aquí cuando haya realizado algunos rituales de purificación en esta habitación. Este lugar está contaminado con magia negativa, $n.' WHERE `ID`=11930;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 해냈어요... 리븐데어 남작을 해치웠군요! 은빛 여명회에서도 당신의 영웅적인 업적에 대한 소식을 듣게 될 거예요!', `FemaleText_loc4`='你做到了……你杀死了瑞文戴尔男爵！你的丰功伟绩将传遍整个银色黎明！', `FemaleText_loc5`='你辦到了...你殺了瑞文戴爾男爵!銀色黎明都會知道你英勇的行為!', `FemaleText_loc7`='Lo has conseguido... ¡has dado muerte al Barón Osahendido! ¡El Alba Argenta debe conocer tus heroicas hazañas!' WHERE `ID`=11931;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘못한 투자에 대해 얘기해 보게!$B$B발타라크 군주의 암흑 마법책은 벌써 암시장에서 고가에 팔렸다고. 그런데 그는 자기 물건이 도난당했다는 사실을 순순히 받아들이지 않았지. 그 나쁜 녀석은 벌써 몇 달 전에 죽었으면서 아직도 우리를 괴롭히고 있다네!', `MaleText_loc4`='这就是所谓的错误投资了！瓦塔拉克公爵的黑暗魔法之书在黑市上确实卖了好价钱。可他对于被偷走的东西实在是太记仇了。他死掉几个月以后依然对我们阴魂不散！', `MaleText_loc5`='真是錯誤的投資!$B$B瓦薩拉克領主的黑暗魔法書在黑市賣了一筆好價錢。他對財產遭到偷竊反應如此激烈真是太可惜了。那個可惡的傢伙在死後幾個月還來向我們討回公道!', `MaleText_loc7`='¡Hablando de hacer la inversión equivocada!$B$BEl libro oscuro de los hechizos de Lord Valthalak se vendió por una buena cantidad en el mercado negro. Es una lástima que no encajara con demasiada amabilidad que le robaran sus posesiones. ¡Ese apestoso nos pilló, aunque llevaba meses muerto!' WHERE `ID`=11932;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이시다의 목숨을 구해 주다니 당신의 용기에 감사하오. $n, 당신에게 정말 큰 빚을 졌구려. 내 힘이 닿는 한 최선을 다해 도와드리겠소.', `MaleText_loc4`='你拯救了伊思达的生命，$n。我欠了你一个大人情，有什么能帮上忙的请尽管吩咐吧。', `MaleText_loc5`='亞希達終生感謝你的勇氣，$n。我真的欠你太多，我會盡我所能全力協助你。', `MaleText_loc7`='Ysida sigue con vida gracias a tu coraje, $n. Estoy en deuda contigo y haré todo lo que esté en mi mano para ayudarte.' WHERE `ID`=11933;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='통통 전차는 뭔가요?', `MaleText_loc4`='蒸汽坦克？', `MaleText_loc5`='坦克?', `MaleText_loc7`='¿Tonques?', `FemaleText_loc1`='통통 전차는 뭔가요?', `FemaleText_loc4`='蒸汽坦克？', `FemaleText_loc5`='坦克?', `FemaleText_loc7`='¿Tonques?' WHERE `ID`=11934;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리의 최신형 장비를 소개합니다. 따로 돈을 내실 필요는 없어요. 통통 전차라고 이름을 붙인 이 작은 차는 유랑단 여기저기에 있는 통통 전차 조종장치를 통해 제어할 수 있답니다.$B$B당신은 사용 가능한 조종장치를 작동하기만 하면 되는 것이죠. 각 통통 전차는 주요 장비 세트를 장착하고 특수한 힘으로 무장하여 적을 초토화한답니다!$B$B친구들과 함께 치열한 전투를 벌이거나 그냥 여기저기를 둘러볼 수도 있어요. 아니면 단순히 파괴를 즐길 수도 있고... 선택은 어디까지나 당신의 몫이에요!', `FemaleText_loc4`='我们新近发现，马戏团中随处可见的蒸汽车控制台能操纵这些被称为蒸汽车的迷你坦克，我可是很慷慨地跟你分享这一信息。$B$B你只需激活控制台就行了。每辆坦克都配备了常用的弹药和某种秘密武器，向你的敌人开火吧！$B$B和朋友一起参加史诗般的战斗、巡逻、或者仅仅是进行野蛮的破坏……一切都由你自己选择！', `FemaleText_loc5`='我們最新的產品，我不會多收你的錢，就是這些小型坦克，可以受馬戲團裡的任何坦克控制臺所控制。$B$B你所要做的就是啟動一個可用的控制臺。每輛坦克會裝備一批儀器，還有可以隨意對你的敵人釋放的特殊能量。$B$B和你的朋友一起打場史詩戰，四處逛逛，或是去試試它的威力...隨你想怎麼作都可以!', `FemaleText_loc7`='Estos tanques de miniatura o tonques, que es el ingenioso nombre que les hemos puesto, son nuestra nueva atracción, totalmente gratuita, por cierto, y se controlan mediante cualquiera de las consolas de control que se encuentran por toda la feria.$B$BSolo tienes que activar cualquier consola de control que esté disponible. Cada tonque estará equipado con una serie de artefactos y un poder especial aleatorio que podrás desatar contra tus enemigos.$B$BVive batallas épicas con tus amigos, pasea con tu tonque o provoca el caos. ¡Tú eliges!' WHERE `ID`=11935;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대포는 뭔가요?', `MaleText_loc4`='大炮？', `MaleText_loc5`='大砲?', `MaleText_loc7`='¿Cañón?', `FemaleText_loc1`='대포는 뭔가요?', `FemaleText_loc4`='大炮？', `FemaleText_loc5`='大砲?', `FemaleText_loc7`='¿Cañón?' WHERE `ID`=11936;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='최신형 블라스텐하이머 5000 초특급 대포는 사람 한 명을 발사하는 장치예요. 거의 용이 날아가는 속도로 탑승자를 발사하는 이 대포는 블라스텐하이머가의 자랑이자 기쁨으로, 그들의 위대한 업적을 전 세계에 알리게 되었죠!$B$B새처럼 자유롭게 하늘로 날아오르고 싶다면 유랑단의 동쪽 끝으로 가서 맥시마 블라스텐하이머를 찾아보세요. 제가 듣기로 그녀는 당신이 하늘로 발사된 후 목표로 삼아야 하는 지점을 수정 호수 위에 원으로 표시해 놓았다더군요!', `FemaleText_loc4`='雷管5000型超级大炮是一种代表世界最尖端技术水平的单人发射装置，它能以龙的速度将人发射出去。发明该设施的地精家族是家喻户晓的航空领域先驱，这种超级大炮已经成为了家族的荣耀！$B$B如果你想象鸟儿一样在空中翱翔，就去马戏团东边找玛克希玛·雷管吧。听说发射线路是横跨水晶湖呢！', `FemaleText_loc5`='衝擊者5000型超級大砲是一種最先進的單人拋射儀器。他以龍的速度運送裝載，這個大砲是布萊頓海默家的驕傲與喜悅，他們的航空與彈藥技術是出了名的!$B$B如果你想像一隻鳥一樣在空中翱翔，就去馬戲團的東邊盡頭找瑪克希瑪·布萊頓海默。我聽說她遠在水晶湖設置了一個目標環狀物讓你在空中翱翔時瞄準!', `FemaleText_loc7`='El Ultracañón Pimpampum 5000 es un artefacto único para el lanzamiento de personas que proyecta su carga a una velocidad cercana a la del vuelo de un dragón. Este cañón es el orgullo de la familia Pimpampum, conocida en todo el mundo por sus derroches en el campo de la aeronáutica.$B$BSi quieres probar el cañón y volar como un pájaro, busca a Maxima Pimpampum en el extremo este de la feria. Parece ser que ella ha marcado un punto de destino sobre el Lago de Cristal que tendrás que localizar mientras surcas los cielos.' WHERE `ID`=11937;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='블라스텐하이머 5000 초특급 대포는 한 사람을 쏘아 올리는 멋진 장치예요. 거의 용이 날아가는 속도로 탑승자를 발사하는 이 대포는 블라스텐하이머가의 자랑이자 기쁨으로, 그들의 위대한 업적을 전 세계에 알렸죠!$B$B새처럼 자유롭게 하늘로 날아오르고 싶다면 썬더 블러프 중앙 봉우리의 남쪽 가장자리로 가서 맥시마 블라스텐하이머를 찾아보세요. 그녀가 남쪽으로 멀리 수정 호수로 당신을 발사해 줄 거예요!', `FemaleText_loc4`='雷管5000型超级大炮是一种代表世界最尖端技术水平的单人发射装置，它能以龙的速度将人发射出去。发明该设施的地精家族是家喻户晓的航空领域先驱，这种超级大炮已经成为了家族的荣耀！$B$B如果你想象鸟儿一样在空中翱翔，就去雷霆崖的猎人高地南部找玛克希玛·雷管吧。听说它可以把人发射到石牛湖以南呢！', `FemaleText_loc5`='衝擊者5000型超級大砲是一種最先進的單人拋射儀器。他以龍的速度運送裝載，這個大砲是布萊頓海默家的驕傲與喜悅，他們的航空與彈藥技術是出了名的!$B$B如果你想和鳥一樣在空中翱翔，就去雷霆崖獵人高地南方邊緣找瑪克希瑪·布萊頓海默。她會在石牛湖南方的目標向你瞄準!', `FemaleText_loc7`='El Ultracañón Pimpampum 5000 es un artefacto único para el lanzamiento de personas que proyecta su carga a una velocidad cercana a la del vuelo de un dragón. Este cañón es el orgullo de la familia Pimpampum, conocida en todo el mundo por sus derroches en el campo de la aeronáutica.$B$BSi quieres probar el cañón y volar como un pájaro, busca a Maxima Pimpampum en la parte este del Alto de los Cazadores en Cima del Trueno. ¡Se reunirá contigo en tu punto de destino al sur del Lago Toro de Piedra!' WHERE `ID`=11938;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 싸우다가 쓰러지는 모습을 본 %s|1이;가; 분노에 휩싸입니다!', `MaleText_loc4`='%s目睹$n在战斗中丧命后变得狂暴起来！', `MaleText_loc5`='%s看到$n在戰鬥中倒下後變得狂怒!', `MaleText_loc7`='¡%s monta en cólera tras ver a $n caer en combate!', `FemaleText_loc1`='$n|1이;가; 싸우다가 쓰러지는 모습을 본 %s|1이;가; 분노에 휩싸입니다!', `FemaleText_loc4`='%s目睹$n在战斗中丧命后变得狂暴起来！', `FemaleText_loc5`='%s看到$n在戰鬥中倒下後變得狂怒!', `FemaleText_loc7`='¡%s monta en cólera tras ver a $n caer en combate!' WHERE `ID`=11939;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='켈투자드가 수호자의 지팡이인 전설의 아티쉬를 찾고 있다고 합니다.$B$B그렇습니다, 메디브가 지니고 있던 바로 그 지팡이랍니다.', `FemaleText_loc4`='听说克尔苏加德正在研究传说中的埃提耶什，守护者的传说之杖。$B$B是的，就是那件曾属于麦迪文的神奇法杖。', `FemaleText_loc5`='聽說科爾蘇加德在尋找充滿傳奇的阿泰絲，偉大的守護者。$B$B對，就是麥迪文曾經持有的那把神杖。', `FemaleText_loc7`='Se comenta que Kel''Thuzad ansía el legendario Atiesh, el gran báculo del guardián.$B$BSí, el mismísimo báculo que Medivh portó en su día.' WHERE `ID`=11940;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 빛의 결사단은 세계에 해악을 끼치는 자를 심판할 때 다른 형제들만큼 자비롭지 않소.', `MaleText_loc4`='当面对那些妄图危害这个世界的邪恶势力时，我们圣光兄弟会可远没有其他同胞那样和善。', `MaleText_loc5`='當碰到危害這個世界的事物時，我們聖光兄弟會相較之下是不會手下留情的。', `MaleText_loc7`='Los de la Hermandad de la Luz no somos tan indulgentes como nuestros hermanos cuando se trata de impartir justicia a aquellos que hacen el mal en el mundo.' WHERE `ID`=11941;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕이 이 세계에 모습을 드러내려 합니다. 절대로 이를 용납해서는 안 됩니다.', `MaleText_loc4`='巫妖王正试图要将他的存在传达给整个世界，让这个世界陷入恐慌与噩梦之中。绝对不能让这一切发生。', `MaleText_loc5`='巫妖王想讓自己名揚四海。絕不能讓他得逞。', `MaleText_loc7`='El Rey Exánime intenta hacer sentir su presencia en nuestro mundo. No debemos permitir que esto ocurra.' WHERE `ID`=11942;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛의 결사단이 뭐냐고? 음... 우리는 뼛속까지 철저한 은빛십자군의 일원이오. 모두 도덕이나 죄의식, 쓸데없는 인간의 감정 따위에 결코 흔들리지 않소이다.', `MaleText_loc4`='什么是圣光兄弟会？好吧……从本质上说，我们都是银色北伐军的核心成员——一群不受道德、内疚这类毫无用处的人类感情所限制的人。', `MaleText_loc5`='什麼是聖光兄弟會?嗯...我們都是銀白十字軍的核心成員，不受道德、罪惡感和沒用的人類情感所操控。', `MaleText_loc7`='¿Qué es la Hermandad de la Luz? Bien... En el fondo todos somos miembros de la Cruzada Argenta, pero estamos libres del lastre de la moralidad, la culpabilidad y demás emociones humanas inútiles.' WHERE `ID`=11943;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='은빛 여명회는 무능력한 이상주의자들에 불과해요. 하지만, 망상에 사로잡힌 그들의 지도자는 자기들이 뛰어나다고 생각하고 있답니다. 저는 붉은십자군의 사절로 이곳에 파견되었습니다. $r의 사절이여, 당신이... 켈투자드의 군대에 약간의 타격이라도 줄 수 있을지 의문이군요. 우리가 힘을 합치든 그렇지 않든 말입니다. 하지만, 기적이 일어날 때까지 그들의 공격을 방어하는 정도는 할 수 있을 거예요.$B$B저요? 저는 전쟁터에서 죽을 각오가 되어 있어요...$B$B<어깨를 으쓱하는 마잔>', `FemaleText_loc4`='银色黎明只不过是一群懦弱无力的理想主义者，若不是他们的领袖能意识到自己的不足，他们真可以说是无可救药了。我是血色十字军派驻到这里来的一名大使。是的，算是一名外交人员……我们的未来仍然是一片迷雾，我不知道我们是否能成为一支联军，或各自为战；我也不知道我们是否能够在克尔苏加德的侵略之下保卫家园，或让这个世界沦陷，但我们应该竭尽全力，奇迹总在风雨之后到来。$B$B至于我？马革裹尸，战死沙场……$B$B<玛尔兰耸了耸肩。>', `FemaleText_loc5`='銀色黎明也許是個無力的理想主義者，他們有妄想傾向的領導者知道自己有優勢。我是血色十字軍派來的密使，也就是外交大使，如果你將...不管統一或獨立，能不能削弱科爾蘇加德的軍隊都還是個問號，我們如果能攔截他們的話就已經是奇蹟了。$B$B至於我呢?我將死在戰場上...$b$b<瑪涵聳肩。>', `FemaleText_loc7`='Los de El Alba Argenta serán unos idealistas impotentes pero su ilusorio líder sabe que no son capaces de aguantar. Estoy aquí en calidad de emisaria de la Cruzada Escarlata. Una embajadora, si preferís... No hay duda de que no podríamos infligir ni el menor de los daños a los ejércitos de Kel''Thuzad, unidos o no, pero debemos intentar contenerlos el mayor tiempo posible a la espera de que se produzca un milagro.$B$B¿En cuanto a mí? Moriré luchando...$B$B<Marjhan se encoge de hombros.>' WHERE `ID`=11944;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말 놀라워요, 림블랫! 이 오염된 대지도 치유할 수 있다니...', `FemaleText_loc4`='这太神奇了，雷布拉特！即使是被污染成这样的破碎大地，也能得到滋润与修复。', `FemaleText_loc5`='實在是太驚訝了，林布拉特!即使是腐敗，分裂的土地也沒辦法復合。', `FemaleText_loc7`='¡Eso es maravilloso, Rimblat! Incluso estas tierras inmundas y asoladas tienen salvación.' WHERE `ID`=11945;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드루이드여, 보시오. 대지는 여전히 숨을 쉬고 있소이다. 깨끗하게 정화되기를 바라고 있는 것이라오.', `MaleText_loc4`='看，德鲁伊。大地仍然在艰难地呼吸。它渴求净化。', `MaleText_loc5`='你看，德魯伊。大地還在呼吸。它渴望純淨。', `MaleText_loc7`='Mira, druida. La tierra todavía respira. Ansía ser purificada.' WHERE `ID`=11946;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무래도 내 칭호가 잘못된 것 같소. 나도 알고 보면 참 좋은 사람인데 말이지...', `MaleText_loc4`='我的头衔可能有会让人误解我。与我相处久了，你就会知道我其实是一个很好相处的人。', `MaleText_loc5`='頭銜是騙人的。你了解我後，你就知道我是個好人。', `MaleText_loc7`='Mi título es engañoso. Cuando me conozcas bien te darás cuenta de que soy muy simpático...' WHERE `ID`=11947;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='붉은십자군에서는 대부분의 모임에 제 동생 록시를 보냈습니다. 하지만, 록시는 붉은십자군을 대표하기는커녕 자기 사냥개를 돌보는 일조차 할 줄 모르는 녀석이죠.', `MaleText_loc4`='他们差点把我的兄弟洛克希给派来了。他连自己的狗都照顾不了，还是让那些能够展现血色十字军实力的人来这里吧。', `MaleText_loc5`='他們都派了我的兄弟，洛克希，到這個集會。他連他的獵犬都顧不好了，更別說有資格代表血色十字軍。', `MaleText_loc7`='Casi envían a mi hermano, Loksey, a esta reunión. No es capaz ni de cuidar a sus canes y mucho menos de representar de manera competente a la Cruzada Escarlata.' WHERE `ID`=11948;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 만나고 싶었...$B$B<콜록거리는 림블랫>$B$B아, 미안하네. 오래된 지병이라서 말일세. 내 소개를 하지. 난 대지 고리회의 림블랫이라 하네.', `MaleText_loc4`='我希望能……$B$B<雷布拉特干咳了几声。>$B$B抱歉，老毛病了。我是大地之环的雷布拉特。', `MaleText_loc5`='我一直在期...$b$b<林布拉特咳嗽。>$B$B不好意思，老毛病。我是陶土議會的林布拉特。', `MaleText_loc7`='Estaba espe...$B$B<Rimblat tose.>$B$B¡Oh, perdona! Soy Rimblat del Anillo de la Tierra.' WHERE `ID`=11949;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='엘룬께 영광을! $c님, 지나치게 남의 눈에 띄는 일이 없도록 조심하세요.', `FemaleText_loc4`='你好，$c。请尽量别引起太多注意。', `FemaleText_loc5`='哈囉，$c。請不要吸引太多注意。', `FemaleText_loc7`='Hola, $c. Intenta no llamar la atención.' WHERE `ID`=11950;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원하는 게 뭔가? 왜 나를 분노의 마타우스라고 부르는지 두 눈으로 확인하고 싶지 않으면 어서 사라져!', `MaleText_loc4`='你想干什么，小松鼠？赶快从我眼前消失，不然你就有机会搞明白为什么他们叫我愤怒者了。', `MaleText_loc5`='你要什麼，鼠輩?知道為什麼大家都叫我施怒者?在我證明之前，你趕快給我滾。', `MaleText_loc7`='¿Qué es lo que quieres, roedor? Desaparece inmediatamente de mi vista si no quieres descubrir por qué me llaman el Colérico.' WHERE `ID`=11951;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싸우고 싶나? 그럼 소원대로 해주마!', `MaleText_loc4`='你要战？便来战！', `MaleText_loc5`='你想打架?那就讓你打個痛快!', `MaleText_loc7`='¿Quieres pelea? ¡La tendrás!' WHERE `ID`=11952;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 얼굴을 날려주겠다!', `MaleText_loc4`='我要把你彻底打败！', `MaleText_loc5`='我要把你醜陋的頭給踢下來!', `MaleText_loc7`='¡Te voy a arrancar la cabeza!' WHERE `ID`=11953;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너처럼 허약한 녀석들을 혼내 주는 게 내 취미지! 자, 시작해 볼까!', `MaleText_loc4`='我厌恶你这样的懦夫！放马过来吧！', `MaleText_loc5`='我每天都在解決像你這樣的軟腳蝦!放馬過來吧!', `MaleText_loc7`='¡Aplasto a alfeñiques como tú todos los días! ¡Adelante!' WHERE `ID`=11954;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어리석은 놈들, 그 무례함에 기가 막힐 지경이다! 네놈들의 영혼을 먹어 치워주마!', `MaleText_loc4`='你这傲慢至极的蠢货！我要品尝你的灵魂！', `MaleText_loc5`='你的傲慢真是可怕，蠢蛋!我要好好享用你的靈魂!', `MaleText_loc7`='¡Tu insolencia es terrible! ¡Devoraré tu alma!' WHERE `ID`=11955;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 누가 나의 영원한 안식을 방해하느냐? 천천히 그리고 고통스럽게 죽음으로 인도해주지!', `MaleText_loc4`='是谁胆敢打扰我永恒的长眠？你将在痛苦中缓慢地死去！', `MaleText_loc5`='誰敢打擾我永恆的安寧?你將會緩慢又痛苦的死去!', `MaleText_loc7`='¿Quién osa perturbar mi eterno descanso? ¡Su muerte será lenta y dolorosa!' WHERE `ID`=11956;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벌레만도 못한 녀석이 감히 내게 도전하는 것이냐?', `MaleText_loc4`='你们不过是我脚下的蝼蚁，竟然也敢向我挑战吗？', `MaleText_loc5`='你只不過是我腳下的一條蟲。還敢挑戰我?', `MaleText_loc7`='No sois más que gusanos para mí, ¿y aun así osáis desafiarme?' WHERE `ID`=11957;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='먼저 네놈들의 뼈를 으스러뜨리겠다! 그런 다음 영혼까지 태워주마!', `MaleText_loc4`='库尔莫克会粉碎你的身躯！然后灼烧你的灵魂！', `MaleText_loc5`='首先科爾莫克會壓碎你的骨頭!然後科爾莫克會燃燒你的靈魂!', `MaleText_loc7`='¡Primero Kormok machacar tus huesos! ¡Después Kormok quemar tu alma!' WHERE `ID`=11958;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='작고 보잘것없는... 나의 종으로 삼기에도 형편없는 놈들이로고!', `MaleText_loc4`='你们这群渺小可怜的家伙……连给库尔莫克提鞋都不配！', `MaleText_loc5`='你是如此的渺小...不能當科爾莫克的好僕人!', `MaleText_loc7`='Ustedes tan pequeños e insignificantes... ¡no buenos para ser sirvientes de Kormok!' WHERE `ID`=11959;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무쌍의 전투장비가 뭡니까?', `MaleText_loc4`='什么是无畏护甲？', `MaleText_loc5`='無畏護甲是什麼?', `MaleText_loc7`='¿Qué es una armadura acorator?', `FemaleText_loc1`='무쌍의 전투장비가 뭔가요?', `FemaleText_loc4`='什么是无畏护甲？', `FemaleText_loc5`='無畏護甲是什麼?', `FemaleText_loc7`='¿Qué es una armadura acorator?' WHERE `ID`=11960;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='첫 번째로 만든 무쌍의 전투장비는 붉은십자군 대영주 모그레인만을 위한 것이었소. 대영주가 무쌍의 전투장비를 입고 있으면 황천 깊숙이 있는 악마와 다름없는 모습이었지.$B$B그렇소, 모그레인이 파멸의 인도자를 높이 들고 백 명의 스컬지에게 뛰어들었다가 반대편에서 먼지와 화염 구름을 뚫고 나오는 모습은 정말 장관이었소. 적들은 그의 발아래 재로 변했지.', `MaleText_loc4`='世上第一套无畏护甲是专为血色十字军领袖莫格莱尼设计并锻造的。当穿上全套的无畏护甲之后，这位大领主看上去就像是一位来自扭曲虚空的恶魔。$B$B哎……我至尽还忘不了那时的情景，莫格莱尼高举着灰烬使者，在成百上千的天灾军团士兵中穿入穿出，燃烧着敌人与自己的生命，带起一阵阵烈炎与烟尘，身后留下敌人被烧成灰烬的尸骸。', `MaleText_loc5`='第一套無畏護甲是專為血色大領主莫格萊尼訂做的。完成時，大領主覺得自己活生生像是從冥府來的惡魔。$B$B沒錯，這的確是個絕佳機會親見莫格萊尼精神飽滿的率領血色十字軍，齊聲吶喊、高舉揮舞著灰燼使者，眼看另一端敵軍於燃火飛塵之中在他的雙腳下慌張撤離。', `MaleText_loc7`='La primera armadura acorator fue creada exclusivamente para el Alto Señor Escarlata Mograine. Cuando se hubo puesto la armadura al completo, el Alto Señor semejaba un demonio proveniente del mismísimo infierno.$B$BSí, su aspecto debía ser impactante pues Mograine se sumergió en un mar de guerreros de la Plaga, con la espada Crematoria erguida, y salió indemne envuelto en una nube de polvo y llamas dejando a sus enemigos hechos cenizas.' WHERE `ID`=11961;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 말씀하십시오.', `MaleText_loc4`='请继续说下去。', `MaleText_loc5`='請繼續。', `MaleText_loc7`='Continúa, por favor.', `FemaleText_loc1`='계속 말씀하세요.', `FemaleText_loc4`='请继续说下去。', `FemaleText_loc5`='請繼續。', `FemaleText_loc7`='Continúa, por favor.' WHERE `ID`=11962;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직도 논란이 되는 그의 죽음 이후 로데론의 기사와 전사들은 고인이 된 영웅을 기리는 의미로 그와 비슷한 방어구를 만들어 입기 시작했소. 켈투자드를 상대로 모그레인은 목숨까지 바쳐 위대한 승리를 거두었고 그의 죽음으로 인해 촉발된 희생정신은 전쟁이 끝날 때까지 그칠 줄 몰랐소.$B$B한 명이 쓰러지자 수많은 사람이 들고일어났지...', `MaleText_loc4`='在他不幸运遇难之后，全洛丹伦的骑士与战士都开始穿着相同式样的铠甲，以纪念这位倒下的英雄。尽管莫格莱尼的死可以算是克尔苏加德的一场大胜，但英雄之死的影响，却改变了整个战争最终的走势。$B$B一个人倒下了，但更多的人站了出来，为反抗天灾军团的入侵而战……', `MaleText_loc5`='在飽受爭議的死亡事件之後，羅德隆的騎士與戰士為了向他們倒下的英雄表示敬意，紛紛都穿起類似的戰袍。而莫格萊尼的死對科爾蘇加德是偉大的勝利，最後殉難的結果要一直到戰爭結束才知分曉。$B$B一王倒下，他強必崛起...', `MaleText_loc7`='Tras su polémica muerte, los caballeros y guerreros de Lordaeron empezaron a portar armaduras similares a la del héroe caído. Mientras que la muerte de Mograine significó una gran victoria para Kel''Thuzad, el sufrimiento derivado de ella perduraría hasta el fin de la guerra.$B$BAunque uno cayó, muchos otros se erigieron...' WHERE `ID`=11963;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 다른 건 없습니까?', `MaleText_loc4`='还有什么可说的吗？', `MaleText_loc5`='還有別的嗎?', `MaleText_loc7`='¿Algo más?', `FemaleText_loc1`='또 다른 건 없나요?', `FemaleText_loc4`='还有什么可说的吗？', `FemaleText_loc5`='還有別的嗎?', `FemaleText_loc7`='¿Algo más?' WHERE `ID`=11964;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='낙스라마스에서 스컬지와 전투를 치르는 동안 모독의 전투장비와 닳아해진 판금 조각을 발견하거든 내게 가져오시오. 그러면 당신에게 영웅들이 입던 전투장비의 일부를 만들어 드리겠소.', `MaleText_loc4`='在你与纳克萨玛斯内的天灾军团士兵作战时，顺便也可以收集一些被玷污的护甲和板甲碎片，把它们带回来交给我，我可以用这些材料来为你重铸一套属于往昔英雄的铠甲。', `MaleText_loc5`='在納克薩瑪斯與天譴軍團的戰爭中，你可以找到褻瀆的城垛、和受戰爭蹂躪的戰甲碎塊。幫我把需要的物品帶來，我就會為你製作一套英雄獨享的護甲!', `MaleText_loc7`='Si cuando combatas contra la Plaga en Naxxramas encuentras restos de almenas profanadas y restos de corazas, tráemelos y te haré una armadura de héroe.' WHERE `ID`=11965;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자연의 모든 힘이 나의 의지를 따른다. 미천한 존재여, 어떤 형상으로 네 고통을 끝내주길 바라는가?', `MaleText_loc4`='卑微的凡人，所有的自然力量都由我支配。我的任何一种形态都能了结你的性命！', `MaleText_loc5`='所有自然界的力量都在我的掌握之中，渺小的凡人。來看看是我的哪一種形態會結束你的苦難!', `MaleText_loc7`='Las fuerzas de la Naturaleza están a mi disposición, insignificantes mortales. ¡Veamos cuál de las formas que puedo adoptar pone fin a su sufrimiento!' WHERE `ID`=11966;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크하하하! 이 애처로운 장면은 뭔가? 대체 뭘 기다리는 거지? 음, 배가 고프군. 보아하니 한 끼 식사거리로 충분하겠군!', `MaleText_loc4`='啊哈哈哈哈哈！我眼前的是个怎样的可怜虫啊！好吧，你等什么呢？我饿了，不如就拿你当开胃菜吧！', `MaleText_loc5`='姆哈哈哈哈!我眼前是個多麼可悲的場面啊?唉，你在等什麼呢?我餓了，你看起來是個還過得去的開胃菜!', `MaleText_loc7`='¡Bah, bah, bah! ¿Qué ven mis ojos? Y bien, ¿a qué estás esperando? ¡Me muero de hambre y parece que tú podrías ser un buen aperitivo!' WHERE `ID`=11967;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리를 소환할 수 있다고 생각했나? 소환하는 것은 바로 우리지 네가 아니다! 이 무례함에 대한 보답으로 죽을 때까지 때려주지. 그런 다음 뼈를 추려주마!', `MaleText_loc4`='你觉着你可以召唤我们吗？我们才是召唤者，不是你！看我们把你锤扁，再打碎你的骨头！', `MaleText_loc5`='你覺得你可以召喚我們?我們才是召喚別人的人，不是你!我們要打扁你再吸光你的骨髓!', `MaleText_loc7`='¿Crees que puedes invocarnos? ¡Nosotros somos los que invocamos aquí y no tú! ¡Vamos a acabar contigo y a devorarte hasta que no quede ni rastro de ti!' WHERE `ID`=11968;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 재력가라고 부르는 게 바로 날세.', `MaleText_loc4`='我就是你所说的财主，$R。', `MaleText_loc5`='我就是你口中的資本家，$r。', `MaleText_loc7`='Soy lo que ustedes denominan un capitalista, $r.' WHERE `ID`=11969;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='살아오면서 다른 이들을 치료하는 데 내 열정을 바쳤다. 하지만, 지금 이 순간만큼은 내가 얼마나 큰 고통을 줄 수 있는지 알아보고 싶군!', `FemaleText_loc4`='活着的时候，我将毕生的精力都投入到治病救人中。看看我死后能给他人造成多大的痛苦吧！', `FemaleText_loc5`='活著的時候，我將我的精力致力於治療其他人。現在就看看在死亡中我可以造成多少痛苦!', `FemaleText_loc7`='En vida, canalizaba mis energías para curar a otros. ¡Veamos ahora que estoy muerta cuánto dolor puedo provocar!' WHERE `ID`=11970;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어서 오세요, $g형제:자매;여.', `FemaleText_loc4`='兄弟，你好。', `FemaleText_loc5`='嗨，兄弟。', `FemaleText_loc7`='Hola, hermano.' WHERE `ID`=11971;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$g형제:자매;여, 어서 오세요. 어떻게 오셨나요?', `MaleText_loc4`='嗨，你好。这儿有什么好东西？', `MaleText_loc5`='嗨，姐妹。發生了什麼事?', `MaleText_loc7`='Hola, hermana. ¿Qué tenemos aquí?' WHERE `ID`=11972;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='침입자로군!', `FemaleText_loc4`='恐怕有入侵者。', `FemaleText_loc5`='我擔心，這樣可能會成為闖入者。', `FemaleText_loc7`='Intrusos, me temo.' WHERE `ID`=11973;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 잠을 방해한 무례함의 대가를 깨우쳐 주도록 할까?', `MaleText_loc4`='我们是否该杀了这群打扰我们安息的无理之徒呢？', `MaleText_loc5`='我們該不該為他們打擾我們睡眠的無禮行為殺了他們?', `MaleText_loc7`='¿Acabamos con ellos por haber interrumpido nuestro sueño?' WHERE `ID`=11974;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그렇게 하죠!', `FemaleText_loc4`='是的，我们会的！', `FemaleText_loc5`='對，我們該這麼做!', `FemaleText_loc7`='¡Sí!' WHERE `ID`=11975;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구원의 갑옷이 뭡니까?', `MaleText_loc4`='什么是救赎护甲？', `MaleText_loc5`='救贖護甲是什麼?', `MaleText_loc7`='¿Qué es una armadura Redención?', `FemaleText_loc1`='구원의 갑옷이 뭔가요?', `FemaleText_loc4`='什么是救赎护甲？', `FemaleText_loc5`='救贖護甲是什麼?', `FemaleText_loc7`='¿Qué es una armadura Redención?' WHERE `ID`=11976;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구원의 갑옷은 우리 중 가장 신앙심이 깊었던 기사가 사용했던 것이오. 그걸 입을 자격이 있었던 것은 빛의 수호자 바로 그였소!$B$B마지막 전쟁에서 수천 명이 전사했지. 그들의 시체에서 벗겨진 방어구들은 공포의 요새 낙스라마스로 운반되었소.$B$B낙스라마스에 있는 죽음의 기사들이 어떤 목적에 사용하기 위해 구원의 갑옷을 더럽히고 있다는 얘기를 들었소.$B$B어찌 이런 비극이 있을 수 있단 말인가...', `MaleText_loc4`='救赎护甲原本属于我们当中最虔诚的那一批圣骑士，甚至是光明使者本人也曾穿过这套护甲！$B$B可在上一次战争中，这些圣骑士们英勇抗击天灾军团，战死沙场之后，他们身上的铠甲却被敌人掠夺走，带去了恐怖之城纳克萨玛斯。$B$B据说纳克萨玛斯的死亡骑士利用污浊的力量亵渎了这批救赎护甲，并为他们的罪恶目的所用。$B$B这真是个悲剧……', `MaleText_loc5`='救贖法衣由我們最忠誠的騎士穿著－與光明使者自己等同地位的法衣!$B$B上千人戰死在最後的戰役;從屍體身上扒下的法衣，然後帶進納克薩瑪斯的驚懼城塞。$B$B謠傳納克薩瑪斯之死亡騎士腐化了救贖法衣，供他們自己使用。$B$B如此的悲劇...', `MaleText_loc7`='La armadura Redención la utilizaban nuestros caballeros más devotos, ¡una armadura digna del mismísimo Iluminado!$B$BMuchos cayeron en la última guerra y sus cuerpos fueron despojados de las armaduras, que acabaron en la aterradora ciudadela de Naxxramas.$B$BSe dice que los Caballeros de la Muerte de Naxxramas modificaron la armadura de placas Redención para poder utilizarla.$B$BToda una tragedia...' WHERE `ID`=11977;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지하추적자 갑옷이 뭡니까?', `MaleText_loc4`='什么是地穴追猎者护甲？', `MaleText_loc5`='地穴巡者護甲是什麼?', `MaleText_loc7`='¿Qué es una armadura Acechacriptas?', `FemaleText_loc1`='지하추적자 갑옷이 뭔가요?', `FemaleText_loc4`='什么是地穴追猎者护甲？', `FemaleText_loc5`='地穴巡者護甲是什麼?', `FemaleText_loc7`='¿Qué es una armadura Acechacriptas?' WHERE `ID`=11978;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저와 같은 직업을 가진 이들에게 지하마귀의 사냥 실력은 언제나 연구 대상이자 부러움의 대상이죠. 저는 이 땅에서 스컬지를 몰아내기 위해 그 짐승들을 수없이 해치웠습니다.$B$B제가 비록 지하마귀의 잔인성을 증오하기는 하지만 그 능력만큼은 대단하다고 인정합니다. 사실 그들은 맡은 임무를 충실히 수행하는 것뿐이지요.', `MaleText_loc4`='地穴恶魔在狩猎与杀戮天敌的过程中所表现出来的那些超自然能力，一直是我们这类人所赞赏与模仿的对象。是的，我，一个在远征中手刃过成百上千天灾军团所圈养的野兽的人。$B$B尽管我也对地穴恶魔那残忍无情的天性十分厌恶，但也必须正视它的能力。它总是能够完美地完成自己的工作。', `MaleText_loc5`='在我的同業裡，常有人研究跟吹噓地穴惡魔獵殺敵人的超自然力量。至於我自己，則是在十字軍中為了驅趕天譴軍團殺了很多野獸。$B$B但是我痛恨的是地穴惡魔殘酷的天性，這是一定要欽佩的能力。它有一定的地位和作用，而且實行的非常好。', `MaleText_loc7`='En mi profesión, se estudia y hace alarde de la facultad sobrenatural que tiene el demonio de cripta para cazar y matar a sus enemigos. Yo mismo derroté a miles de bestias en mi cruzada por liberar al mundo de la Plaga.$B$BAunque detesto la naturaleza despiadada del demonio de cripta, no puedo sino admirar sus facultades. Tiene un objetivo y lo cumple. ¡A la perfección!' WHERE `ID`=11979;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 말씀하십시오.', `MaleText_loc4`='请继续说下去。', `MaleText_loc5`='請繼續。', `MaleText_loc7`='Continúa, por favor.', `FemaleText_loc1`='계속 말씀하세요.', `FemaleText_loc4`='请继续说下去。', `FemaleText_loc5`='請繼續。', `FemaleText_loc7`='Continúa, por favor.' WHERE `ID`=11980;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지하마귀의 껍질과 다양한 신체 부위를 활용할 방법을 발견했습니다. 지하마귀의 껍질을 낙스라마스에서 사라진 모독의 마법 방어구에 결합하면 아주 가벼우면서도 엄청난 힘을 지닌 방어구 세트를 만들 수 있단 말입니다.', `MaleText_loc4`='我发现了地穴恶魔身上的甲壳以及其它部位的多种用途。我想我能利用这些碎片，配合纳克萨玛斯内的一些被污染的魔法护甲碎片，制成某种极轻而且实用的护甲套装来。', `MaleText_loc5`='我發現地穴惡魔的甲殼有一種功用。我可以發明一種極輕巧又致命的護甲套裝，只要組合一些納克薩瑪斯裡被褻瀆的魔法護甲碎片。$B$B幫我把需要的物品帶來，我就會為你製作一套世界前所未有的護甲!', `MaleText_loc7`='He descubierto un uso del caparazón del demonio de cripta y sus diversas partes del cuerpo. Puedo crear una armadura extremadamente ligera y a la vez infalible mediante la combinación de sus fragmentos con las armaduras mágicas de Naxxramas.' WHERE `ID`=11981;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타우렌에게는 해골마 타는 방법을 가르칠 수 없어. 미안하지만 내가 해줄 일이 없군.', `MaleText_loc4`='我没法教一个牛头人骑乘骷髅战马，很抱歉。', `MaleText_loc5`='我不能教牛頭人騎骷髏馬。很抱歉，我幫不了你什麼忙。', `MaleText_loc7`='No puedo enseñarle a $gun:una; tauren a montar una cabalgadura esquelética. Lo siento pero no puedo hacer nada por ti.', `FemaleText_loc1`='타우렌에게는 해골마 타는 방법을 가르칠 수 없어. 미안하지만 내가 해줄 일이 없군.', `FemaleText_loc4`='我没法教一个牛头人骑乘骷髅战马，很抱歉。', `FemaleText_loc5`='我不能教牛頭人騎骷髏馬。很抱歉，我幫不了你什麼忙。', `FemaleText_loc7`='No puedo enseñarle a $gun:una; tauren a montar una cabalgadura esquelética. Lo siento pero no puedo hacer nada por ti.' WHERE `ID`=11982;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신같은 타우렌이 이곳 역병지대에는 왜 오셨습니까?', `MaleText_loc4`='你这样的牛头人到底是为了什么来到瘟疫之地呢？', `MaleText_loc5`='是什麼風把牛頭人吹來瘟疫之地了?', `MaleText_loc7`='¿Qué trae a un tauren hasta las Tierras de la Peste?', `FemaleText_loc1`='당신같은 타우렌이 이곳 역병지대에는 왜 오셨나요?', `FemaleText_loc4`='你这样的牛头人到底是为了什么来到瘟疫之地呢？', `FemaleText_loc5`='是什麼風把牛頭人吹來瘟疫之地了?', `FemaleText_loc7`='¿Qué trae a un tauren hasta las Tierras de la Peste?' WHERE `ID`=11983;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 타우렌족은 마지막 전쟁에 참가했소. 스컬지의 침공으로부터 이 세계를 지키기 위해 주술사들이 투입되었지. 대부분 목숨을 잃었소이다. 살아남은 타우렌들도 그 저주받은 요새로 끌려가 사악한 실험에 이용됐소. 온몸이 갈가리 찢기다가... 그들의 죽음이 너무나 애통하지만 그 용기를 생각하면 내 가슴이 벅차오르는구려.', `MaleText_loc4`='在上一次大战中，牛头人也曾参战，很多地方都有萨满祭司抵抗天灾入侵的记录。这些祭司们也献出了宝贵的生命，更悲惨的是，他们的尸体竟然还被收集起来，切割成碎片，输送到那座被诅咒的城堡中的用作某些邪恶实验的材料。我只能在此真心为他们的逝去感到默哀，他们也是我们一族的骄傲。', `MaleText_loc5`='牛頭人在最後一場戰爭勇猛奮戰。薩滿負責抵禦天譴軍團的入侵。大多數的士兵都戰死沙場。還有很多人則是被五馬分屍，在那受詛咒的城堡裡，他們殘斷的屍塊、肢體被拿來執行卑鄙的實驗。我對於他們的犧牲感到無比悲慟，卻也打從心裡對他們的英勇深感驕傲。', `MaleText_loc7`='Los tauren tomaron parte en la última guerra. Los chamanes fueron enviados para defender el mundo contra la invasión de la Plaga. y muchos perdieron la vida. Algunos fueron cortados en pedazos que luego se utilizaron en esa ciudadela maldita para hacer experimentos. Lamento mucho su pérdida pero mi corazón se llena de orgullo ante el coraje que demostraron.' WHERE `ID`=11984;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 말씀하십시오.', `MaleText_loc4`='请继续说下去。', `MaleText_loc5`='請繼續。', `MaleText_loc7`='Continúa, por favor.', `FemaleText_loc1`='계속 말씀하세요.', `FemaleText_loc4`='请继续说下去。', `FemaleText_loc5`='請繼續。', `FemaleText_loc7`='Continúa, por favor.' WHERE `ID`=11985;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 당시 난 막 사춘기에 접어든 어린 타우렌이었지. 하지만, 내 이름을 걸고 만든 방어구가 자유를 위하여 전쟁에 뛰어든 용감한 이들을 든든하게 지켜줄 것을 알고 있었소.', `MaleText_loc4`='我那时还是一个年轻的牛头人，没有成年，但我却知道，那些为了我们的自由而战的勇士们，都拥有一套与我同名的护甲。', `MaleText_loc5`='我是年輕牛頭人，勉強算是正值青春期。不過，我知道那些為我們自由而英勇奮戰的人，都庇護在與我同名的外衣下。', `MaleText_loc7`='Yo era un joven tauren que apenas había alcanzado la adolescencia pero sabía que aquellos que libraran batallas por nuestra libertad estarían bien protegidos portando la armadura que lleva mi nombre.' WHERE `ID`=11986;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 가문은 수백 년 동안 오염된 대지를 회복하기 위해 노력해 왔소. 나도 아버지와 할아버지처럼 대지의 힘을 이용해 방어구를 만들 수 있는 기술을 물려받았지.', `MaleText_loc4`='碎地者这个姓氏所代表的伟大家族，已经存在了几百年了。和我父亲，我父亲的父亲，以及更遥远的先祖一样，我继承了制造这种以我家族姓氏命名的护甲的能力。', `MaleText_loc5`='我的家族數百年都以碎地者為名。就像我父親和曾祖父繼承權利一樣，我也能創造一件以我為名的法衣。', `MaleText_loc7`='El nombre de Rompeterra se conservó en mi familia durante cientos de años y yo, al igual que mi padre y su padre antes que él, también heredé el derecho de crear las armaduras que llevan ese nombre.' WHERE `ID`=11987;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까?! 성함이 어떻게 되시나요?$B$B그건 그렇고, 아름다운 푸른 초원 위의 그림 같은 우리 집에는 무슨 일로 오셨습니까?', `MaleText_loc4`='你好……嗯，你叫什么？$B$B没关系，你来这个小村庄做什么？这个美丽的地方是我的第二故乡。', `MaleText_loc5`='喔，哈囉...嗯，你是?$B$B不要緊，是什麼風把你吹來我在這美麗鄉村的離家之園啊?', `MaleText_loc7`='Oh, buenas... mmmm ¿cómo te llamas?$B$BNo importa, ¿qué te trae a mi hogar alejado del hogar, aquí en la bella campiña?' WHERE `ID`=11988;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요. 즐거운 시간 보내시기를 바랍니다. 파티는 어떻습니까? 모자라는 음식이 없어야 할 텐데... 술과 요리가 모자라는 것만큼 파티의 흥을 빨리 깨는 일도 없죠. 그렇지 않나요?$B$B당연한 일이죠. 아, 이만 다른 손님에게 가봐야겠군요. 좋은 시간 되십시오.', `MaleText_loc4`='你好，$c。我希望你玩的很高兴，你觉得聚会怎么样？我希望我们的食水都还有剩余。没有什么比吃喝全部耗尽更让人扫兴的了，你说呢？$B$B啊，好吧。我必须去照顾一下我的其他客人了。玩得开心点。', `MaleText_loc5`='嗨，$c。想必你們一定玩得很開心吧?你們覺得的派對好玩嗎?希望我們派對上的東西都夠供應。飲料跟開胃點心如果不夠就是派對的致命傷啊，對吧?$B$B嗯，好啦，我要去招待其他賓客囉。盡興玩。', `MaleText_loc7`='Hola, $c. Confío en que te lo estés pasando bien. ¿Qué opinas de la fiesta? Realmente espero que no se nos esté acabando nada. Nada mata una fiesta más rápido que quedarse sin bebidas y entremeses, ¿no crees?$B$BSí, bueno, tengo que ir a atender a mis otros invitados. Disfruta de tu estancia.' WHERE `ID`=11989;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 대단합니다! 그럼 축제를 시작하겠습니다. 정원으로 자리를 옮기시죠. 음, 내 술을 어디다 뒀더라?', `MaleText_loc4`='啊，太棒了！宴会要开始了。我们回到露台去吧。对了，我把酒放在哪里了？', `MaleText_loc5`='啊，太棒了!讓歡樂蔓延吧。在露臺休息吧。現在，我要喝什麼好呢?', `MaleText_loc7`='¡Ah, excelente! Que comiencen los festejos. Retirémonos a la terraza. Bueno, ¿dónde he puesto mi bebida?' WHERE `ID`=11990;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<하품을 하는 살데릴 경> 벌써 새벽인가? 다들 공감하시겠지만 전부 훌륭했습니다. 여러분은 어쩌실 건가요... 저는 그만 안으로 들어가야겠습니다.', `MaleText_loc4`='<呵欠> 已经天亮了？好吧，天下无不散之宴席……就像他们说的那样。我不知道你们怎么样，但我要进屋去了。', `MaleText_loc5`='<打哈欠>太陽出來了嗎?好啊，太好了...就跟他們說的一樣。我是不知道你們其他人啦，不過我要進去了。', `MaleText_loc7`='<Yawn> ¿Ya ha amanecido? Ah bueno, todo lo bueno... como se suele decir. No sé ustedes, pero yo me voy dentro.' WHERE `ID`=11991;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='살데릴 경, 언제쯤이면 우리 파티에 참여할 수 있을까요? 이곳은 너무 지루합니다.', `FemaleText_loc4`='大人，你觉得我们马上就能参加聚会吗？在这里很无聊啊。', `FemaleText_loc5`='閣下，你覺得我們可以早點參加派對嗎?我在這裡好無聊。', `FemaleText_loc7`='Milord, ¿crees que podremos unirnos pronto al grupo? Me aburro tanto aquí.' WHERE `ID`=11992;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='살데릴 경, 실버문의 멋진 포도주를 많이 준비했으면 좋겠어요. 이런 말씀드리기는 좀 부끄럽지만 그 포도주만 마시면 평범한 농가의 아낙이 된 기분이랍니다!', `FemaleText_loc4`='哦，我的大人。我非常希望你准备了足够的银月城美酒。我敢说喝下这些可以让我感觉自己像个正常的女人！', `FemaleText_loc5`='喔，我的主人，我真的希望你多準備一些銀月城的美酒。我敢說我喝了這美酒後就會跟一般的女人一樣直接!', `FemaleText_loc7`='Ay, señor; solo espero que haya más vino de Lunargenta. Cuando bebo me siento como una mujer normal.' WHERE `ID`=11993;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='몹시 피곤하네요. 어젯밤 너무 늦게까지 있는 게 아니었는데... 벌써 아침이군요. 하지만, 참 재밌었어요! 살데릴 경, 훌륭한 파티였습니다.', `FemaleText_loc4`='我很累。我们昨天晚上真的不应该玩到那么晚……呃，应该说是玩到今天早上。但是太有趣了！那真是最棒的晚会，大人。', `FemaleText_loc5`='我好累喔。我們昨晚...嗯，其實是早上不應該熬夜到那麼晚的。不過真的很好玩!閣下辦的聚會真的很棒。', `FemaleText_loc7`='Estoy tan cansada. No deberíamos habernos quedado hasta tan tarde anoche... bueno, esta mañana. ¡Pero fue divertido! Organizas las mejores veladas, mi señor.' WHERE `ID`=11994;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='존경하는 살데릴 경, 파티 음식이 좀 부족한 듯합니다. 산들바람 마을에 심부름꾼을 보내서 필요한 물건을 좀 더 배달시켜야겠습니다. 특히 훈제 삼겹살로 싼 한입 요리가 좋겠는데요. 뭐라고 부르는 음식이었죠?', `FemaleText_loc4`='我亲爱的萨瑟利尔男爵，你有没有注意到聚会的供应品似乎有些不足？我们真的需要那么一个信使从晴风村运些我们需要的东西过来。我特别喜欢那些包裹在熏肉中的小点心，对了，那东西叫什么来着？', `FemaleText_loc5`='薩瑟里領主，親愛的，你不覺得舞會的東西太少了嗎?我們應該派那些晴風村的信差送來所有我們需要的東西。我特別喜歡那些用煙燻培根包的開胃菜。那菜名叫什麼啊?', `FemaleText_loc7`='Lord Saltheril, querido, ¿te has dado cuenta de que las reservas para el grupo están un poco bajas? Realmente deberíamos enviar a uno de esos mensajeros de la aldea Brisa Pura para que entregue más de lo que sea que se necesite. Me gustan especialmente esos pequeños entremeses envueltos en bacon ahumado. ¿Cómo se llaman?' WHERE `ID`=11995;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대의 말씀대로 따르겠습니다. 누구의 분부라고요.', `MaleText_loc4`='当然，亲爱的，当然。', `MaleText_loc5`='你說的都對，我親愛的，你說的是。', `MaleText_loc7`='Como digas, querida, como digas.' WHERE `ID`=11996;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방금 뭐라고 하셨죠? 미안, 잠시 딴생각을 좀 하느라...', `MaleText_loc4`='唔，那是什么？对不起，亲爱的，我肯定是在做白日梦。', `MaleText_loc5`='嗯，怎樣?抱歉親愛的，我一定是在作白日夢。', `MaleText_loc7`='Mmm, ¿qué era eso? Lo siento, querida, debo de haber estado soñando despierto.' WHERE `ID`=11997;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 그래요! 엘리사라, 조금만 기다려주겠어요?', `MaleText_loc4`='哦，一点也没错，埃莉萨拉。但是请你拿出点耐心来好吗？', `MaleText_loc5`='喔，一定是，艾麗莎。但拜託你，可以展現最基本的一點耐心嗎?', `MaleText_loc7`='Oh, sin duda alguna, Elisara. Pero, por favor, ¿puedes mostrar un atisbo de paciencia?' WHERE `ID`=11998;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런가요? 흥미롭군요. 잠시 나가서 화장이라도 고치고 오는 것이 어떻습니까? 저는 생각할 것이 좀 많습니다.', `MaleText_loc4`='是吗？多有趣啊，亲爱的。为什么你不在鼻子上补点妆呢？我有很多事情需要考虑。', `MaleText_loc5`='是這樣嗎?真有意思。親愛的，你為什麼不邊跑邊替你的鼻子撲粉?我有好多事情要想想。', `MaleText_loc7`='¿Ah, sí? Qué interesante. Cariño, ¿por qué no vas pasando y te retocas el maquillaje? Tengo mucho en que pensar.' WHERE `ID`=11999;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 신나라! 곧 파티가 시작된다!', `FemaleText_loc4`='啊，太好了！聚会就要开始了！', `FemaleText_loc5`='喔太好了!派對要開始了喔!', `FemaleText_loc7`='¡Oh, vaya! ¡La fiesta está a punto de empezar!' WHERE `ID`=12000;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='만나서 반갑습니다. 즐거운 시간 되시기 바랍니다.', `FemaleText_loc4`='你好，尊敬的$g先生:女士;。我相信你一定过得很愉快？', `FemaleText_loc5`='你好，$g大人:小姐;。我相信你一定玩的很開心吧?', `FemaleText_loc7`='Saludos, mi $gseñor:señora;. Confío en que se lo esté pasando bien.' WHERE `ID`=12001;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말 흥겹지 않아요? 살데릴 경께서 이런 파티를 매일 밤 개최하신다니 정말 신납니다. 남쪽에서 벌어지는 역겨운 일을 생각하면 더욱 그렇죠. 이런 파티는 그런 일을 완전히 잊게 해주는 법입니다.', `FemaleText_loc4`='这不是很有趣吗？我很高兴萨瑟利尔男爵每晚都举办这样的聚会，特别在南部发生着些令人不愉快的事情时，聚会可以让我们忘记那一切，你觉得呢？', `FemaleText_loc5`='你不覺得很好玩嗎?我真高興薩瑟里領主每晚都舉辦舞會，尤其是那些令人作嘔的東西滾到南方，感覺就像把它們拋諸腦後，對吧?', `FemaleText_loc7`='¿No es divertidísimo? Es magnífico que Lord Saltheril organice estas fiestas todas las noches, especialmente con todo lo que está ocurriendo en el sur. La verdad es que una fiesta te permite olvidarlo todo, ¿verdad?' WHERE `ID`=12002;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로한, 당신은 정확하게 어떤 일을 하십니까?', `MaleText_loc4`='你究竟是干什么的呢，洛汗？', `MaleText_loc5`='你實際上從事什麼工作，洛漢?', `MaleText_loc7`='¿Qué es lo que haces exactamente, Rohan?', `FemaleText_loc1`='로한, 당신은 정확하게 어떤 일을 하시나요?', `FemaleText_loc4`='你究竟是干什么的呢，洛汗？', `FemaleText_loc5`='你實際上從事什麼工作，洛漢?', `FemaleText_loc7`='¿Qué es lo que haces exactamente, Rohan?' WHERE `ID`=12003;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 내 호칭이 말해 주듯이 난 붉은십자군을 위해 일하는 암살자라오. 낮에는 제거 대상을 우선순위대로 암살하고 밤에는 가젯잔 무도회장에서 춤과 함께 시간을 보내지. 춤은 나의 진정한 꿈이라오. 암살은 단지 돈을 벌기 위한 수단일 뿐이고 말이오.', `MaleText_loc4`='啊，如我头衔所述，我是一名血色十字军的刺客。我每天白天研究着最优先目标的资料，晚上就去加基森的舞厅里放纵一下。好吧，其实跳舞才是我的正业，偶尔出去做点杀手活计赚点钱，付帐单。', `MaleText_loc5`='啊，如同頭銜寫著我是血色十字軍的刺客。我白天花在時間消滅首要目標，夜晚則在加基森迪斯可。跳舞才是我內心真實的呼喚。刺殺行動不過是糊口而已。', `MaleText_loc7`='¡Ah! Como el propio título indica son un asesino de la Cruzada Escarlata. Paso los días exterminando objetivos de alta prioridad y las noches en la discoteca de Gadgetzan. Mi verdadera vocación es bailar. Solamente mato para pagar las facturas.' WHERE `ID`=12004;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러면, 희망의 빛 예배당에는 무슨 일로 오셨습니까?', `MaleText_loc4`='你为什么要来到光明之愿礼拜堂？', `MaleText_loc5`='所以是什麼風把你吹來聖光之願了?', `MaleText_loc7`='¿Entonces qué te trae a Esperanza de la Luz?', `FemaleText_loc1`='그러면, 희망의 빛 예배당에는 무슨 일로 오셨나요?', `FemaleText_loc4`='你为什么要来到光明之愿礼拜堂？', `FemaleText_loc5`='那是什麼風把你吹來聖光之願了?', `FemaleText_loc7`='¿Entonces qué te trae a Esperanza de la Luz?' WHERE `ID`=12005;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋은 질문이군. 젊은 시절 난 세상 돌아가는 일엔 신경 쓰지 않고 자유분방하게 지냈었지. 그 당시 난 스톰윈드를 떠돌며 노래를 부르던 돈 사중창단에 있었소이다. 떠돌며 지내던 그 시절 그 곳에서 해골사신의 갑옷을 제작하는 법을 배웠소.', `MaleText_loc4`='这个问题问得好，$r。年轻的时候，我是个自由自在玩世不恭的人，从来没有关心过这个世界的命运。那时候，我在暴风城那边唱歌，参加了一个叫“劈头四”的四重唱组合。我也是在那里学会制作骨镰护甲的。', `MaleText_loc5`='好問題，$r。我年輕時是個狂放不羈、對世事冷眼旁觀的人。那些日子，我就在暴風城的美容沙龍裡表演四重唱，團名叫四位大人。那是我學會製作骨鐮護甲的地方。', `MaleText_loc7`='Buena pregunta, $r. De joven era libre como el viento y no me preocupaba por nada. En aquellos tiempos, cantaba en un cuarteto masculino en Ventormenta conocido como Los Cuatro Dones. Ahí es donde aprendí a fabricar las Segahuesos.' WHERE `ID`=12006;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐라고요? 해골사신의 갑옷이라고 했습니까?', `MaleText_loc4`='什么？骨镰？', `MaleText_loc5`='什麼?骨鐮?', `MaleText_loc7`='¿Qué? ¿Segahuesos?', `FemaleText_loc1`='뭐라고요? 해골사신의 갑옷이라고 했나요?', `FemaleText_loc4`='什么？骨镰？', `FemaleText_loc5`='什麼?骨鐮?', `FemaleText_loc7`='¿Qué? ¿Segahuesos?' WHERE `ID`=12007;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇소, 해골사신의 갑옷 말이오. 일전에 말했다시피 우리 중창단의 테너였던 돈 훌리오라는 고집쟁이 친구가 모든 것을 가르쳐 주었소이다. 그는 로데론 전역을 여행하며 흥미로운 기술을 많이 익혔지. 그중 하나는 죽은 스컬지의 뼈를 취해서 아주 튼튼한 가죽 방어구를 만드는 것이었소. 암살자에게 완벽한 갑옷이라고 할 만한 그런 물건 말이외다.', `MaleText_loc4`='是的，骨镰。你要知道，我们的组合里有个男高音，一个很傻的家伙，名字好象是叫唐·胡里奥的，是他教给我全部的东西。他曾在洛丹伦各地旅行，一路上学习了许多非常有意思的技巧。其中之一就是将天灾士兵身上的骸骨改制为一套又轻又舒适的皮甲，特别适合刺客使用。', `MaleText_loc5`='是的，骨鐮。你知道的，這是我們的男中音，叫做胡力歐的頑固傢伙，他找我一起開始整件計畫。在他穿越羅德隆的旅途中，胡力歐學會很多有趣的技能，其中一種技能能利用倒下的天譴軍團的骨頭，做成致命的皮甲－非常適合給刺客。', `MaleText_loc7`='Sí, Segahuesos. Fue nuestro tenor, un tipo con muy malas pulgas llamado Don Julio, quien me inició en todo esto. En sus viajes por Lordaeron, Don Julio adquirió muchas facultades interesantes y una de ellas era convertir los huesos de los miembros de la Plaga caídos en armaduras de cuero letales, ideales para los asesinos.' WHERE `ID`=12008;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우와, 당신 미쳤군요. 내 말이 맞죠?', `MaleText_loc4`='啧啧，我看你是疯了……', `MaleText_loc5`='哇，你瘋了，對吧?', `MaleText_loc7`='¡Tú estás $gloco:loca;!', `FemaleText_loc1`='우와, 당신 미쳤군요. 내 말이 맞죠?', `FemaleText_loc4`='啧啧，我看你是疯了……', `FemaleText_loc5`='哇，你瘋了，對吧?', `FemaleText_loc7`='¡Tú estás $gloco:loca;!' WHERE `ID`=12009;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어허, 참! 내 옆에 서 있는 저 친구만큼이나 정상이라오. 뭐, 좋을 대로 생각하시오. 하지만, 난 그 방어구를 만들 능력이 있는 사람이지. 원한다면 계약을 맺을 수도 있소이다. 어서 빨리 이 암살자 생활을 청산하고 싶단 말이오.', `MaleText_loc4`='我一点都没疯，跟你一样正常，$g伙计:小姐;。相信我，我确实能做出这样一套护甲。如果你有兴趣，不如来做一笔交易。能越早摆脱杀手的行当，我就越开心。', `MaleText_loc5`='我和下一個人一樣頭腦清醒，$g老兄:女士;。相信你將相信的，我現在確實可以鑄好護甲。如果你感興趣，或許我們能做一筆交易。越快擺脫暗殺工作越好。', `MaleText_loc7`='Eso no es cierto, $gamigo:amiga;. Me creas o no, soy capaz de fabricar esta armadura. Si te interesa, podríamos llegar a un acuerdo. Cuanto antes deje mi vida como asesino, mejor.' WHERE `ID`=12010;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐만요. 가젯잔에 무도회장이 있나요?', `MaleText_loc4`='嘿，等等，加基森真有舞厅吗？', `MaleText_loc5`='嘿等等，加基森有迪斯可舞廳?', `MaleText_loc7`='¡Un momento! ¿En Gadgetzan hay una discoteca?', `FemaleText_loc1`='잠깐만요. 가젯잔에 무도회장이 있나요?', `FemaleText_loc4`='嘿，等等，加基森真有舞厅吗？', `FemaleText_loc5`='嘿等等，加基森有迪斯可舞廳?', `FemaleText_loc7`='¡Un momento! ¿En Gadgetzan hay una discoteca?' WHERE `ID`=12011;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하, 이걸 어쩌나? 그 무도회장은 회원 전용이오!', `MaleText_loc4`='会员制的，废柴！', `MaleText_loc5`='會員專屬，臭小子!', `MaleText_loc7`='¡Es solo para miembros!' WHERE `ID`=12012;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 된 거지? 아, 또 이럴 순 없어!', `MaleText_loc4`='什么？啊呀，又来了！', `MaleText_loc5`='什麼?喔，別又來了!', `MaleText_loc7`='¿Qué? ¡Oh, esto otra vez no!' WHERE `ID`=12013;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 이럴 수가! 우린 약속을 하지 않았소?!', `MaleText_loc4`='你不能这样对我！我们事先说好了的！', `MaleText_loc5`='你怎麼能這樣對我!我們之前都談好交易了!', `MaleText_loc7`='¡No me puedes hacer esto! ¡Teníamos un trato!' WHERE `ID`=12014;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요, 레인! 세나리온 의회가 역병지대로 오게 된 이유가 무엇입니까?', `MaleText_loc4`='你好，莱茵。塞纳里奥议会到瘟疫之地来干什么？', `MaleText_loc5`='哈囉，瑞恩。是什麼風把塞納里奧議會吹來瘟疫之地了?', `MaleText_loc7`='Hola, Rayne. ¿Qué trae al Círculo Cenarion a las Tierras de la Peste?', `FemaleText_loc1`='안녕하세요, 레인! 세나리온 의회가 역병지대로 오게 된 이유가 무엇인가요?', `FemaleText_loc4`='你好，莱茵。塞纳里奥议会到瘟疫之地来干什么？', `FemaleText_loc5`='哈囉，瑞恩。是什麼風把塞納里奧議會吹來瘟疫之地了?', `FemaleText_loc7`='Hola, Rayne. ¿Qué trae al Círculo Cenarion a las Tierras de la Peste?' WHERE `ID`=12015;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리는 저마다 다른 사연으로 여기 왔어요.$B$B<미소를 짓는 레인>$B$B저는 대지 고리회의 림블랫을 만나러 왔습니다. 그는 이 땅을 정화하는 방법에 대한 흥미로운 이론을 알고 있어요.', `FemaleText_loc4`='我们都因为不同的原因来到了这里，$c。$B$B<莱因笑了笑。>$B$B我来到这里是为了帮助大地之环的雷布拉特。他有个很趣的理论，据说能净化这片土地。', `FemaleText_loc5`='我們因為不同原因被吸引到此，$c。$B$B<瑞恩微笑。>我來這裡是想見陶土議會的林布拉特。他對土地淨化有一些有趣的理論。', `FemaleText_loc7`='Cada uno de nosotros estamos aquí por un motivo diferente, $c.$B$B<Rayne sonríe.>$B$BYo estoy aquí para reunirme con Rimblat del Anillo de la Tierra, que tiene unas teorías muy interesantes acerca de la purificación de estas tierras.' WHERE `ID`=12016;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 땅은 치유할 수 없지 않습니까? 완전히 오염된 것처럼 보이는데요.', `MaleText_loc4`='难道这片土地还有救吗？它们已经遭受了如此严重腐化与侵蚀。', `MaleText_loc5`='這些地方沒有完全復原嗎?看起來真的受創很深。', `MaleText_loc7`='¿Acaso todavía existe salvación para estas tierras? Parecen bastante estropeadas.', `FemaleText_loc1`='이 땅은 치유할 수 없지 않습니까? 완전히 오염된 것처럼 보이는데요.', `FemaleText_loc4`='难道这片土地还有救吗？它们已经遭受了如此严重腐化与侵蚀。', `FemaleText_loc5`='這些地方沒有完全復原嗎?看起來真的受創很深。', `FemaleText_loc7`='¿Acaso todavía existe salvación para estas tierras? Parecen bastante estropeadas.' WHERE `ID`=12017;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제 생각은 좀 달라요. 림블랫은 이 죽은 대지에서도 새 생명이 자랄 수 있다는 걸 증명했어요. 이제 새롭게 피어난 생명을 꾸준히 성장시키는 방법을 찾는 것이 더욱 중요합니다.$B$B그리고 여기 있는 동안, 전 낙스라마스로 가는 모험가들을 돕고 있어요.', `FemaleText_loc4`='我当然也不这么认为。但雷布拉特似乎已经证实了新的生命可以在这种破碎的土地上成长。现在我们的工作就是保持这种成长的可持续性，以及，最重要的，供应维持这种生长的养分。$B$B当然，既然我已经在这里了，我也会提供一些服务，帮助冒险者们进入纳克萨玛斯。', `FemaleText_loc5`='我不認為。林布拉特證明了分裂的土地一樣可以孕育新生命。現在我們必須找到再生和更重要的持續成長。$B$B我在這裡幫忙那些進入納克薩瑪斯的冒險者。', `FemaleText_loc7`='No lo creo. Rimblat ha demostrado que puede brotar nueva vida en estas tierras. Ahora debemos encontrar el modo de repetir el proceso y, lo que es más importante, preservar la nueva vida.$B$BMientras esté aquí, ofreceré mis servicios a los aventureros que vengan a Naxxramas.' WHERE `ID`=12018;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 말입니까?', `MaleText_loc4`='哪一种服务？', `MaleText_loc5`='怎麼幫?', `MaleText_loc7`='¿Qué tipo de servicios?', `FemaleText_loc1`='어떻게 말인가요?', `FemaleText_loc4`='哪一种服务？', `FemaleText_loc5`='怎麼幫?', `FemaleText_loc7`='¿Qué tipo de servicios?' WHERE `ID`=12019;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 명성이 자자한 물건을 만드는 장인이에요. 필요한 재료만 있으면 꿈나그네 의복을 만들 수 있어요. 드루이드, 심지어 일부 주술사조차 이 갑옷의 마력에 강하게 끌린다고 합니다. 어때요, 관심 있으세요?', `FemaleText_loc4`='我是个著名的手艺人，$c。只要有适当的材料，我可以制作出一种名为梦游者的护甲套装。德鲁伊们，甚至一些萨满祭司，都对这种护甲的魔法属性非常中意。你有兴趣吗？', `FemaleText_loc5`='我是個有名望的工匠，$c。只要有適當材料，我能鑄造著名的夢行者護甲。德魯伊－甚至某些薩滿－由於它的魔法特性而深受吸引。你有興趣嗎?', `FemaleText_loc7`='Soy una artesana de renombre, $c. Con los materiales adecuados puedo fabricar una armadura conocida como Caminasueños. Los druidas, e incluso algunos chamanes, sienten predilección por esta armadura debido a sus propiedades mágicas. ¿Te interesa?' WHERE `ID`=12020;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아티쉬가 무엇입니까?', `MaleText_loc4`='埃提耶什是什么？', `MaleText_loc5`='阿泰絲是什麼?', `MaleText_loc7`='¿Qué es Atiesh?', `FemaleText_loc1`='아티쉬가 무엇인가요?', `FemaleText_loc4`='埃提耶什是什么？', `FemaleText_loc5`='阿泰絲是什麼?', `FemaleText_loc7`='¿Qué es Atiesh?' WHERE `ID`=12021;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='켈투자드와 마찬가지로 저 역시 한때 키린 토의 마법사였죠. 그리고 켈투자드처럼 수호자의 지팡이인 전설의 아티쉬를 찾아다녔지요. $c|1이여;여;, 우리 운명은 그렇게 얽혀 있답니다.', `FemaleText_loc4`='与克尔苏加德一样，我也是一个来自肯瑞托议会的法师，更相似的是，我与他都在寻找着埃提耶什，守护者的传说之杖。我们的命运似乎就这样交织在一起了，$c。', `FemaleText_loc5`='我跟科爾蘇加德一樣都曾經是祈倫托的法師，我們也都在遍尋傳說中的守護者之杖，阿泰絲。我們的命運是如此糾纏著，$c。', `FemaleText_loc7`='Al igual que Kel''Thuzad, yo fui una maga del Kirin Tor. Y al igual que Kel''Thuzad, busco el legendario Atiesh, el gran báculo del guardián. Por este motivo, nuestros destinos están unidos, $c.' WHERE `ID`=12022;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수호자? 그게 뭐죠? 무슨 말인지 전혀 모르겠네요.', `MaleText_loc4`='什么守护者？我不知道你在说些什么。', `MaleText_loc5`='什麼守護者?我完全不知道。', `MaleText_loc7`='¿Qué guardián? No entiendo nada.', `FemaleText_loc1`='수호자? 그게 뭐죠? 무슨 말인지 전혀 모르겠네요.', `FemaleText_loc4`='守护者？我不知道你在说些什么。', `FemaleText_loc5`='什麼守護者?我完全不知道。', `FemaleText_loc7`='¿Qué guardián? No entiendo nada.' WHERE `ID`=12023;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그는 에이그윈 님의 후손으로 티리스팔의 마지막 수호자였습니다. 메디브 말입니다.', `FemaleText_loc4`='艾格文的唯一子嗣，最后一任提瑞斯法的守护者……麦迪文。', `FemaleText_loc5`='艾格文的後裔，他會成為提里斯法最後一位守護者...麥迪文。', `FemaleText_loc7`='La progenie de Aegwynn, el que sería el último guardián de Tirisfal... Medivh.' WHERE `ID`=12024;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말씀 계속하시지요.', `MaleText_loc4`='请继续说下去。', `MaleText_loc5`='請繼續。', `MaleText_loc7`='Por favor, continúa.', `FemaleText_loc1`='말씀 계속하시지요.', `FemaleText_loc4`='请继续说下去。', `FemaleText_loc5`='請繼續。', `FemaleText_loc7`='Por favor, continúa.' WHERE `ID`=12025;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전설 속의 이야기죠. 되풀이해서 말할 시간도 없고 그러고 싶지도 않네요. 메디브가 마지막 수호자였다는 사실만 알아두세요. 아티쉬 - 수호자의 지팡이가 그의 힘과 타락의 근원이었답니다.', `FemaleText_loc4`='有关他的传说，我想我没有时间也没有兴趣重述一遍给你听。你只要知道麦迪文是最后一位守护者。而埃提耶什这把传说中的法杖，既是他力量的焦点，也是腐蚀的焦点。', `FemaleText_loc5`='這是一個傳奇，這也是個我沒時間和意願重述的故事，只要知道麥迪文是最後一位守護者。阿泰絲大法杖是權力的核心，也是墮落的極點。', `FemaleText_loc7`='Es una historia de leyenda que no te voy a contar por falta de tiempo y apetencia. Tan solo has de saber que Medivh fue el último de los guardianes. El gran báculo de Atiesh fue la piedra angular tanto de su poder como de su corrupción.' WHERE `ID`=12026;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 타락 말입니까?', `MaleText_loc4`='什么腐蚀？', `MaleText_loc5`='什麼墮落?', `MaleText_loc7`='¿Qué corrupción?', `FemaleText_loc1`='어떤 타락 말인가요?', `FemaleText_loc4`='什么腐蚀？', `FemaleText_loc5`='什麼墮落?', `FemaleText_loc7`='¿Qué corrupción?' WHERE `ID`=12027;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='쓰러진 티탄의 타락, 파괴자의 타락을 뜻하는 겁니다. 결국, 그 지팡이는 증오의 씨앗으로부터 탄생한 것이죠. 제가 여기 온 것도 바로 그 때문이고...', `FemaleText_loc4`='一位堕落泰坦的腐蚀。毁灭者的腐蚀。总之，这根法杖发源于仇恨的种子。当然，这也是我来到这里的原因……', `FemaleText_loc5`='失敗巨人的腐敗，毀滅者的墮落。終究這法杖還是由仇恨的種子所鍛造。也就是說，這當然是我來這裡的主因...', `FemaleText_loc7`='La corrupción de un titán caído. La corrupción del Destructor. Después de todo, el báculo fue forjado a partir de la semilla del odio. Eso es, por supuesto, lo que me ha traído hasta aquí...' WHERE `ID`=12028;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 얘기해 주세요.', `MaleText_loc4`='请继续说下去。', `MaleText_loc5`='請繼續。', `MaleText_loc7`='Por favor, continúa.', `FemaleText_loc1`='계속 얘기해 주세요.', `FemaleText_loc4`='请继续说下去。', `FemaleText_loc5`='請繼續。', `FemaleText_loc7`='Por favor, continúa.' WHERE `ID`=12029;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='카라잔이 멸망한 후 키린 토에서는 한 무리의 마법사를 보내 탑을 조사하고 그곳으로 반입된 모든 물건을 빼앗었어요... 연구를 핑계로 말이죠. 전설의 지팡이가 발견되어 달라란으로 옮겨진 것이 바로 그때였어요.', `FemaleText_loc4`='在卡拉赞陷落之后，肯瑞托议会派遣了一队法师搜索了整座塔，收集到了所有重要的东西……目的？或许是研究吧。总之不知道是否真的，据说这根法杖被带到了达拉然。', `FemaleText_loc5`='在卡拉贊倒下後，祈倫托派了一群法師到哨塔搜索，並扣押所有進口的物品...就為了「研究」的目的。就是那時候才發現了寓言中的法杖，並將它帶回達拉然。', `FemaleText_loc7`='Tras la caída de Karazhan, el Kirin Tor envió a un grupo de magos a buscar la torre y a hacerse con todos los objetos que tuvieran relevancia con la excusa de "investigar." Fue entonces cuando se encontró el legendario báculo y se trajo de nuevo a Dalaran.' WHERE `ID`=12030;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야기를 계속 듣고 싶군요.', `MaleText_loc4`='请继续说下去。', `MaleText_loc5`='請繼續。', `MaleText_loc7`='Por favor, continúa.', `FemaleText_loc1`='이야기를 계속 듣고 싶군요.', `FemaleText_loc4`='请继续说下去。', `FemaleText_loc5`='請繼續。', `FemaleText_loc7`='Por favor, continúa.' WHERE `ID`=12031;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='계속해서 비극적인 사건이 일어났어요. 아티쉬와 접촉한 키린 토의 모든 마법사가 죽게 된 거죠.$B$B그러니까 아티쉬는 지각이 있는 물건이었어요. 살게라스가 부여한 것이죠...', `FemaleText_loc4`='接着，达拉然那边发生了一系列不幸的事件，所有碰过埃提耶什——甚至是仅仅做过与之相关工作的肯瑞托法师都离奇地死亡了。$B$B你看，它似乎是一种有感知的神器，这感知能力想必是萨格拉斯所授予的……', `FemaleText_loc5`='所跟隨的是一連串的悲劇，以致每位只要接觸阿泰絲的祈倫托法師都會死亡。$B$B你看，這是有知覺的神器，是薩格拉斯賦予它的...', `FemaleText_loc7`='Lo que vino después fue una serie de trágicos acontecimientos que acabaron con la muerte de todos los magos del Kirin Tor que habían estado en contacto con Atiesh.$B$BSi te das cuenta, se trataba de un objeto que tenía sentimientos, cualidad que Sargeras le otorgó...' WHERE `ID`=12032;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐라고요?', `MaleText_loc4`='什么？', `MaleText_loc5`='什麼?', `MaleText_loc7`='¿Qué?', `FemaleText_loc1`='뭐라고요?', `FemaleText_loc4`='什么？', `FemaleText_loc5`='什麼?', `FemaleText_loc7`='¿Qué?' WHERE `ID`=12033;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='<고개를 끄덕이는 안젤라>$B$B그들의 죽음 이후 여섯 대마법사는 절대 뚫을 수 없는 마법 장벽 뒤에 지팡이를 봉인하고 감시자를 두는 것이 가장 좋은 방법이라고 결정했어요. 지팡이를 지키는 수호자 말이에요... 제가 바로 그 감시자였답니다.', `FemaleText_loc4`='<安吉拉点了点头。>$B$B在他们死后，六人议会做出了决定。他们认为对这根法杖最好的处理方法无非是用牢固的魔力监牢封印起来，并委任一名看守者……原本应该是我。', `FemaleText_loc5`='<安琪拉點頭。>$B$B他們死後，六人決定最好的應變措施，就是藉由堅固的魔法屏障來隔離法杖，並且任命守護者︰法杖的守護者...而我就是那位守護者。', `FemaleText_loc7`='<Angela asiente con la cabeza.>$B$BTras esta sucesión de muertes, los Seis decidieron encerrar el báculo tras unas barreras de magia impenetrables que alguien debía custodiar: el vigía del báculo. Yo ocuparía ese puesto.' WHERE `ID`=12034;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 복잡한 얘기로군요. 계속 말씀해 주십시오.', `MaleText_loc4`='这确实挺可怕的，请继续。', `MaleText_loc5`='打擾了，請繼續。', `MaleText_loc7`='Esto es desconcertante. Por favor, continúa.', `FemaleText_loc1`='정말 복잡한 얘기로군요. 계속 말씀해 주세요.', `FemaleText_loc4`='这确实挺可怕的，请继续。', `FemaleText_loc5`='打擾了，請繼續。', `FemaleText_loc7`='Esto es desconcertante. Por favor, continúa.' WHERE `ID`=12035;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이야기가 거의 끝나갑니다. 달라란은 아키몬드에 의해 거의 파괴됐고 지팡이는 사라졌어요. 아마도 방벽의 안전장치에 의해 부서진 것 같아요.$B$B어떤 이들은 그 지팡이가 아키몬드의 복수를 불러온 원인이라고 믿고 있답니다.', `FemaleText_loc4`='后来也没什么可说的了。达拉然几乎完全被阿克蒙德摧毁，法杖也遗失了。据说，在那时，禁锢法阵启动了某种保护机制，将法杖击碎了。$B$B也有人说，禁锢了这根法杖是导致阿克蒙德毁灭达拉然的原因，是他为萨格拉斯所做的复仇。', `FemaleText_loc5`='沒什麼好說的。達拉然幾乎全被阿克蒙德破壞，法杖遺失了，可能遭到故障防護裝置機所粉碎了。$B$B有些人相信就是因為法杖，所以引起阿克蒙德的報復。', `FemaleText_loc7`='No queda mucho que contar. Archimonde destruyó Dalaran casi por completo y el báculo se perdió. Se cuenta que podría haber sido hecho añicos por los propios mecanismos de seguridad de la barrera.$B$BLos hay que creen que el báculo fue la causa de la represalia de Archimonde.' WHERE `ID`=12036;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 얘기해 주십시오.', `MaleText_loc4`='请再多告诉我一些。', `MaleText_loc5`='拜託，多跟我講一點。', `MaleText_loc7`='Por favor, cuéntame más.', `FemaleText_loc1`='더 얘기해 주세요.', `FemaleText_loc4`='请再多告诉我一些。', `FemaleText_loc5`='拜託，多跟我講一點。', `FemaleText_loc7`='Por favor, cuéntame más.' WHERE `ID`=12037;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='달라란이 멸망한 후 저는 키린 토를 떠났어요. 아티쉬를 수호하면서 수년을 보냈지만 키린 토에서 제게 맡긴 중요한 임무가 한순간에 무너졌지요. 평생이 걸린다 해도 그 지팡이를 찾고 말 거예요. 제가 은빛 여명회에 합류한 것도, 여기 온 것도 바로 그 때문이에요.', `FemaleText_loc4`='在达拉然沦陷以后，我离开了肯瑞托议会，用了好几年的时间来搜寻埃提耶什的下落，只是为了履行我在肯瑞托未尽的责任。我会找到这根法杖，即使这要用去我一生的时间。这也是我加入银色黎明并站在这里的原因。', `FemaleText_loc5`='在達拉然被陷落之後，我也離開了祈倫托。我花了好幾年尋找阿泰絲，希望能取回祈倫托在某次可怕的突襲中，從我身上奪取的東西。就算要花一輩子，我也要找到法杖。那就是為什麼我參加銀色黎明，還有我現在為什麼在這裡的原因。', `FemaleText_loc7`='Tras la caída de Dalaran, abandoné el Kirin Tor. Durante años busqué el báculo para poder liberarme de la labor que el Kirin Tor me había encomendado. Encontraría el báculo aunque me llevara toda una vida. Así es como entré a formar parte de El Alba Argenta y el motivo por el que estoy aquí.' WHERE `ID`=12038;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 해주실 얘기는 없습니까?', `MaleText_loc4`='还有别的什么吗？', `MaleText_loc5`='還有別的嗎?', `MaleText_loc7`='¿Hay algo más?', `FemaleText_loc1`='더 해주실 얘기는 없나요?', `FemaleText_loc4`='还有别的什么吗？', `FemaleText_loc5`='還有別的嗎?', `FemaleText_loc7`='¿Hay algo más?' WHERE `ID`=12039;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 부서진 지팡이의 조각을 찾기 위해 아제로스 전역을 뒤지고 다녔어요. 그러던 중 지팡이를 다시 복원하려는 켈투자드의 계획을 알아냈지요. 그는 이미 지팡이 조각을 여러 개 모았습니다. 그가 가장 신뢰하는 부관들이 그 조각들을 보관하고 있어요.$B$B켈투자드의 손에 수호자의 지팡이가 들어가지 못하도록 막는 일은 너무나도 중요해요. 솔직히, 전 세계에 재앙이 일어나는 것은 물론이고 어떤 결과가 발생할지 저도 잘 모르겠습니다.', `FemaleText_loc4`='最近几年来，我一直在世界各地搜寻着法杖碎片的下落，并且发现克尔苏加德正试图重铸它。他已经收集到了其中的几块碎片，并交给几位深得他信赖的军官保存着。$B$B我无法再用什么语言来强调从克尔苏加德手中抢回法杖的重要性了。坦诚地讲，如果让他拿到了完整的法杖，我不知道这个世界除了被灾难彻底淹没之外还能有什么其它结局。', `FemaleText_loc5`='我橫跨世界追蹤了各式各樣的法杖碎片，還因此發現科爾蘇加德改良法杖的計畫。他目前收集一些法杖碎片，並且由他最信賴的副官保管著。$B$B努力讓守護者的大法杖遠離科爾蘇加德的控制，這重要性可是非比尋常。坦白說，除了史詩部分的大災難外，我不知道結果將如何。', `FemaleText_loc7`='Le he seguido la pista a los diversos trozos del báculo por todo este mundo y así descubrí que Kel''Thuzad ansía reconstruirlo. Varios fragmentos obran ya en su poder, custodiados por sus tenientes más fieles.$B$BNadie puede imaginar lo importante que es que el gran báculo permanezca fuera del alcance de Kel''Thuzad. Francamente, desconozco cuáles serían las consecuencias aparte, claro está, de una catástrofe de enormes proporciones.' WHERE `ID`=12040;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='역병심장 의복이 뭡니까?', `MaleText_loc4`='什么是天灾之心护甲？', `MaleText_loc5`='什麼是瘟疫之心護甲?', `MaleText_loc7`='¿Qué es una armadura corazón de peste?', `FemaleText_loc1`='역병심장 의복이 뭔가요?', `FemaleText_loc4`='什么是天灾之心护甲？', `FemaleText_loc5`='什麼是瘟疫之心護甲?', `FemaleText_loc7`='¿Qué es una armadura corazón de peste?' WHERE `ID`=12041;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청한 녀석, 그건 힘이다.$B$B<노기를 띠고 째려보는 마타우스>$B$B예전의 영광을 되찾는 일에만 급급한 여기 바보들은 너같은 멍청이를 낙스라마스로 보낼 모양이야. 모독받은 그 갑옷을 되찾아 정화할 셈이겠지...$B$B<침을 뱉는 마타우스>$B$B그런 멍청한 생각을 하다니 참을 수가 없군.$B$B나 역시 그 갑옷을 찾아봤지만 아주 사악하고 더러운 상태였다.', `MaleText_loc4`='那就是力量的化身，你这白痴。$B$B<玛塔乌斯的眼神变得黑暗了。>$B$B这帮白痴把你这样更白的白痴送进纳克萨玛斯里去回收那些被亵渎的护甲碎片，然后净化，重新附魔，来恢复以前的荣光。$B$B<玛塔乌斯不屑地吐了一下口水。>$B$B光是想到这群超级白痴就能让我感到不舒服。$B$B我也在寻找这些护甲碎片，不过我会把它进一步加工成为最邪恶的形态。', `MaleText_loc5`='這就是權力，低能兒。<麥特斯眼眸加深。>$B$B這些傻瓜派了像你這樣的白痴到納克薩瑪斯，取回玷污的護甲以便淨化它，重組零件恢復昔日光采。$B$B<麥特斯啐了一口。>就是這種愚蠢至極的想法讓我反胃想吐。$B$B我也去尋找護甲，我要找玷污以及被褻瀆最深的護甲。', `MaleText_loc7`='Es poder, imbécil.$B$B<Los ojos de Mataus se ensombrecen.>$B$BEstos insensatos envían a Naxxramas a idiotas como tú para recuperar la armadura profanada y así purificarla y devolverle su antigua gloria.$B$B<Mataus escupe.>$B$BTan solo pensar en tal estupidez me hace subir la bilis a la boca.$B$BYo también busco esa armadura pero en su estado actual.' WHERE `ID`=12042;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저도 그런 힘을 찾고 있습니다.', `MaleText_loc4`='我也在追寻着这种力量。', `MaleText_loc5`='我也在尋找這股力量。', `MaleText_loc7`='Yo también anhelo tal poder.', `FemaleText_loc1`='저도 그런 힘을 찾고 있어요.', `FemaleText_loc4`='我也在追寻着这种力量。', `FemaleText_loc5`='我也在尋找這股力量。', `FemaleText_loc7`='Yo también anhelo tal poder.' WHERE `ID`=12043;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='애송이 녀석, 나는 허세 따위는 부리지 않는다. 그런 암흑의 갑옷을 지니고 있으면 우리 둘을 해치우는 건 일도 아니란 말이지. 가격이 아주 비싼 것도 바로 이 때문이다. 만약 내가 죽어 대신 갑옷을 차지하는 녀석은 아주 부자가 되겠지.$B$B사실, 네가 어떻게 죽든지 놀의 침 방울만한 눈물도 흘리지 않을 테지만, 시키는 대로만 해! 내가 말하는 재료를 가지고 와라. 그럼 우리 모두 이득을 보게 되는 거야. 이미 말했다시피 불복종은 곧 죽음이다...', `MaleText_loc4`='那又怎样，白痴。这些蕴涵着黑暗力量的物品或许能把我们全都毁灭掉。这是我们在获取力量时所必须付出的代价。如果我必须要死，那也要死在这样伟大的仪式与实验中。$B$B至于你……如果你在为我完成这一切的过程中死了……那我就会以豺狼人的方式嘲笑你的孱弱。把我要的东西带回来，这样我们两个都能获利益，要么就去死吧，我已经解释过结果了……', `MaleText_loc5`='我不會裝模作樣，蛆蟲。這種黑暗物品所支配的力量可以把我們兩個都摧毀。這就是為什麼價格如此高昂的原因。如果我就要死了，也會是個富翁。$B$B你死了我也不會對你吐一口豺狼人的口水，照我的話做就對了。把我要的東西帶來，我們就能雙方受惠 - 或者死;我已經解釋過了...', `MaleText_loc7`='No engaño, gusano. La oscuridad que tienen tales objetos podría destruirnos a los dos. Por eso el precio es tan elevado. Si voy a morir, que sea como un hombre rico.$B$BNo me importa ni una pizca de saliva de gnoll cómo mueras, solo que hagas lo que te pido. Tráeme lo que necesito y los dos nos beneficiaremos – o moriremos, pero eso ya te lo he explicado...' WHERE `ID`=12044;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신념에 대해 말씀해 주십시오, 신부님!', `MaleText_loc4`='与我谈谈信仰吧，神父。', `MaleText_loc5`='告訴我有關信仰的事，神父。', `MaleText_loc7`='Háblame de fe, Padre.', `FemaleText_loc1`='신념에 대해 말씀해 주세요, 신부님!', `FemaleText_loc4`='与我谈谈信仰吧，神父。', `FemaleText_loc5`='告訴我有關信仰的事，神父。', `FemaleText_loc7`='Háblame de fe, Padre.' WHERE `ID`=12045;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신념... 어떤 이들은 잃고 어떤 이들은 찾지요. 파괴할 수도 없고 만들어 낼 수도 없는 것입니다.$B$B앗, 혹시 신념의 의복 말씀입니까? 그 의복은 마지막 전쟁 동안 스컬지와의 전투에서 우리 사제들과 신앙심이 두터운 전사들이 입었지요.$B$B네, 신념의 의복은 거의 다 사라졌습니다... 낙스라마스의 악마들이 훔쳐 갔어요.', `MaleText_loc4`='信仰吗……有些人已经失去了它，有些人则刚刚找到它。它无法被湮灭，也无法被创造。$B$B或者你是在说信仰护甲？我们的牧师与最虔诚的战士们在上一次战争中抵抗天灾军团士兵时所穿的护甲？$B$B唉，大部分都遗失了……被纳克萨玛斯的地穴恶魔们夺走了。', `MaleText_loc5`='信仰...有些人失去了，有些人卻找到了。它不會被破壞，也不是所謂的建立。$B$B還是你談的是信仰法衣?我們的神父和虔誠戰士，在對抗天譴軍團的戰爭時所穿的法衣。沒錯，大部分都不見了...被納克薩瑪斯惡魔偷走了。', `MaleText_loc7`='Fe... Algunos la han perdido y otros la han encontrado. Es algo que no se puede destruir ni tampoco crear.$B$B¿O te estás refiriendo a las vestimentas de Fe? La armadura portada por nuestros sacerdotes y guerreros más fervientes en la batalla contra la Plaga durante la última guerra.$B$BSí, la mayor parte se ha perdido a manos de los demonios de Naxxramas.' WHERE `ID`=12046;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사령관님, 전갈은 잘 받았습니다. 하지만, 십자군 사령관님의 승인 없이는 여기 일에 절대 관여할 수 없습니다.', `FemaleText_loc4`='我们确实已经收到你的消息了，指挥官，但我们的介入绝对不会得到大十字军阁下的批准的。', `FemaleText_loc5`='我方確實有收到你們的傳話，指揮官，但我們這裡複雜的情況，絕不被大十字軍戰士制裁。', `FemaleText_loc7`='Comandante, hemos recibido tu mensaje, pero nuestra participación aquí no cuenta con la aprobación del Gran Cruzado.' WHERE `ID`=12047;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 지도자가 낙스라마스 입구에 주둔할 것을 결정했소. 그가 아무런 중압감도 느끼지 않는다고 생각하시오?', `MaleText_loc4`='你们的领袖甚至已经把家搬到纳克萨玛斯的入口处了，你认为他感觉不到任何压力吗？', `MaleText_loc5`='你的領袖進駐到納克薩瑪斯之前。你覺得他感受不到壓力嗎?', `MaleText_loc7`='Tu líder se aloja en la entrada de Naxxramas. ¿Crees que no siente la presión?' WHERE `ID`=12048;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 조그맣게 속삭입니다.', `MaleText_loc4`='%s的声音逐渐低沉了下去，变成了耳语。', `MaleText_loc5`='%s降低他的音量，輕聲說著。', `MaleText_loc7`='%s baja el tono de su voz hasta convertirlo en un susurro.' WHERE `ID`=12049;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악마라도 두려워 할 거요...', `MaleText_loc4`='即使是恶魔也会感觉到恐惧……', `MaleText_loc5`='就算是惡魔也會恐懼...', `MaleText_loc7`='Incluso los demonios sienten miedo...' WHERE `ID`=12050;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='역병지대에서 스컬지의 활동이 열 배로 증가했소. 칼림도어처럼 먼 곳도 스컬지의 침공을 받고 있다는 보고가 올라오고 있소! 어떻게 이런 사태가 벌어졌을까? 어째서 사악한 언데드가 전에는 불가능하다고 생각했던 일들을 저지를까 생각해봤소? 이제 이 세상에 안전한 곳이 존재하긴 하느냐는 말이오!', `MaleText_loc4`='瘟疫之地的天灾军团活动已经增加了近十倍。我们甚至收到了来自卡利姆多的天灾军团入侵报告！通过这些信息，你难道还是不能推测出接下来将会发生怎样的事吗？要是这些该死的亡灵真地做出了我们以前认为不可能的事怎么办？这世界上还有哪里是安全的？', `MaleText_loc5`='瘟疫之地裡的天譴軍團已擴增到10倍了。我接到報告指出天譴軍團攻陷整個卡林多。這怎麼可能會發生?悲慘的不死族怎麼完成了不可能的任務?難道已經沒有安全的地方了嗎?', `MaleText_loc7`='La actividad de la Plaga en las Tierras de la Peste se ha multiplicado por diez. ¡Hemos recibido noticias de ataques de la Plaga en lugares tan lejanos como Kalimdor! ¿Y cómo crees que ha podido suceder? ¿Cómo es posible que esos condenados no-muertos hayan conseguido lo que antes parecía inalcanzable? ¿Ningún lugar es ya seguro?' WHERE `ID`=12051;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오크나 황소 인간과 같은 이교도들도 그 사태에 대해 대처를 해야만 할 것입니다.', `FemaleText_loc4`='异教徒们必须做出反应了。兽人，牛人……', `FemaleText_loc5`='異教徒會被迫做出反擊。獸人，牛人...', `FemaleText_loc7`='Los infieles serán obligados a reaccionar. Orcos, minotauros...' WHERE `ID`=12052;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타우렌이겠지...', `MaleText_loc4`='牛头人。', `MaleText_loc5`='牛頭人。', `MaleText_loc7`='Tauren.' WHERE `ID`=12053;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어쨌든 말입니다. 역겹고 불결하기 짝이 없는 호드 놈들...', `FemaleText_loc4`='随便。反正就是一群又脏又臭，野蛮无知的游牧民。', `FemaleText_loc5`='管它的。這些叛亂粗鄙的部落穢物...', `FemaleText_loc7`='Lo que sea. Escoria de la repugnante y descuidada Horda...' WHERE `ID`=12054;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사령관, 당신은 재치가 좀 부족하군. 뭐, 별로 놀라운 사실이 아니야. 그래도, 호드에서 이번 일에 행동을 취할 거라는 말은 맞소이다. 하지만, 호드만은 아니오. 이미 아제로스 각지에서 온 영웅들이 도착했소.', `MaleText_loc4`='你太死板了，指挥官。这并不令人吃惊。不过，正如你所说的，部落会被迫采取行动的。不仅是部落，全世界的英雄都会聚集在这里。', `MaleText_loc5`='指揮官，你缺少機智。不過，你目前正大敵當前，所以部落會被迫行動。但不只有部落而已，全世界的英雄都趕來了。', `MaleText_loc7`='Comandante, tu falta de tacto es innegable. Sin embargo, tienes razón al afirmar que los simpatizantes de la Horda serán obligados a actuar. Pero no solo la Horda. Ya vienen... héroes de todo el mundo.' WHERE `ID`=12055;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='병력도 적고 너무 늦었습니다. 이미 방어선이 무너졌어요. 그들에게 우리는 기껏해야 작은 장애물에 불과하단 말입니다.', `FemaleText_loc4`='太少了，也太迟了。我们正在螳臂当车……', `FemaleText_loc5`='太渺小，也太遲了。已經失控了，我們充其量不過是路上的絆腳石而已。', `FemaleText_loc7`='Ya es demasiado tarde. Estamos desbordados. Somos, como mucho, un pequeño obstáculo en el camino.' WHERE `ID`=12056;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 당신은 왜 이곳에 온 거요? 희망이 없다면 우리가 할 일이 뭐가 있겠소?', `MaleText_loc4`='那么你为什么会在这里？既然那里已经没有希望了，那我们该做什么呢？', `MaleText_loc5`='所以你在這裡幹麻?如果希望渺茫，我們何必待在這裡?', `MaleText_loc7`='¿Entonces por qué estás aquí? ¿Qué haremos si se supone que ya no queda esperanza?' WHERE `ID`=12057;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언제나 희망은 있는 법이지요. 파멸의 인도자 같은...', `MaleText_loc4`='我们还有……灰烬使者。', `MaleText_loc5`='總是有...灰燼使者。', `MaleText_loc7`='Siempre nos quedará... la Crematoria.', `FemaleText_loc1`='언제나 희망은 있는 법이지요. 파멸의 인도자 같은...', `FemaleText_loc4`='我们还有……灰烬使者。', `FemaleText_loc5`='總是有...灰燼使者。', `FemaleText_loc7`='Siempre nos quedará... la Crematoria.' WHERE `ID`=12058;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, 여행자여. 전 카라잔의 열쇠를 소지한 분을 주인님의 귀한 손님으로 모시도록 교육받았습니다. 뭐든지 궁금하신 게 있으면 물어보십시오. 무엇을 도와드릴까요?', `MaleText_loc4`='您好，旅行者。我奉命在此接待主人的贵客，所有携带着卡拉赞钥匙的人都会被奉为上宾。如果您有什么疑问，请尽管开口。有什么需要我帮忙的吗？', `MaleText_loc5`='你好，旅人。我奉命得將任何握有卡拉贊鑰匙的持有者待為主人的座上賓。有需要我幫忙的地方嗎?', `MaleText_loc7`='Saludos, viajeros. Tengo orden de tratar a quien posea una llave de Karazhan como un invitado especial del Maestro. Hacedme todas las preguntas que quieras. ¿En qué puedo ayudaros?' WHERE `ID`=12059;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 버림받은 자들에게 지나치게 자비를 베풀고 있습니다. 놈들에게 따끔한 맛을 보여 줘야 합니다.$B$B해돋이 부두에 있는 뻔뻔한 녀석들을 절대 용납할 수 없습니다.', `MaleText_loc4`='我们对那些失心者太仁慈了，要我说，我们应该拔出剑刺向他们。$B$B他们在阳帆港的大胆行径是不可饶恕的。', `MaleText_loc5`='我們對那些生物都太仁慈了。我們應該用劍刺進每一具身體內。$B$B牠們先拿下了日帆，下一個是誰都還不知道呢?', `MaleText_loc7`='Somos demasiado compasivos con los desdichados. Deberíamos clavarle una espada a cada uno de ellos.$B$BSu osadía en el fondeadero Vela del Sol es imperdonable.' WHERE `ID`=12060;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='죽음의 흉터로 끊임없이 밀려오는 정신 나간 스컬지들을 상대하느라 정말 힘든 하루였습니다. 우리를 돕기 위해 오셨기를 바랍니다. 쓸데없이 잡담이나 하고 있을 시간이 없습니다.', `FemaleText_loc4`='消灭在死亡之痕徘徊的愚蠢的天灾士兵，这可真是个单调的工作。我希望你能在这里助我们一臂之力，而不是把我的时间浪费在闲聊中。', `FemaleText_loc5`='我今天一整天都忙著砍殺不停朝死亡之痕前進的天譴軍團殭屍，除非你是來幫忙的，不然別浪費我的時間。  ', `FemaleText_loc7`='Llevo todo el día matando descerebrados seres de la Plaga en La Cicatriz Muerta. Espero que vengas a echar una mano y no solo a entretenerme con tu charla.' WHERE `ID`=12061;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 말을 전하러 온 거요? 은빛 여명회가 비굴하게 살아남고 붉은십자군이 몰락한 이유를 내게 설명하려는 건가? 사령관, 당신은 그 세 치 혀로 오래된 상처를 들쑤시는군!', `MaleText_loc4`='这就是你到这里来的目的？过来宣告银色黎明的存在与血色十字军的没落？你的话太令我感到遗憾了，指挥官！', `MaleText_loc5`='所以你是為這來的嗎?設法為了主張黎明的存在和十字軍垮台的原因?指揮官，別再挖舊傷疤了!', `MaleText_loc7`='¿De modo que para eso has venido? ¿Para proclamar la existencia del Alba y la caída de la Cruzada? ¡Comandante, con tus palabras abres viejas heridas!' WHERE `ID`=12062;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파멸의 인도자는 죽었고 앞으로 그런 인물은 절대 나오지 않을 것이오. 사령관, 당신은 그 아들 모그레인은 자기 아버지와는 전혀 다른 인물이라는 걸 알고 있었소! 붉은십자군 대영주 모그레인을 죽음으로 몰고 간 것은 결국, 당신이요!', `MaleText_loc4`='灰烬使者已经死了，这世上也不会再有另一个像他这样的人了。小莫格莱尼远远无法匹敌他父亲昔日的辉煌。这些都你都知道的，指挥官！总之，毕竟，你要为血色十字军大领主莫格莱尼的死负责，你当时的指挥造就了这个结果。', `MaleText_loc5`='灰燼使者已死，而且絕不會有第二個他。小莫格萊尼跟他父親差了一大段距離。你知道的，指揮官﹗畢竟你自己的領導，得對血色大領主莫格萊尼之死負起責任。', `MaleText_loc7`='El portador de la Crematoria ha muerto y nunca nadie podrá reemplazarlo. El joven Mograine no tiene nada que ver con la figura de su padre. ¡Lo sabes bien, Comandante! Después de todo, tú fuiste la responsable de la muerte del Alto Señor Escarlata Mograine.' WHERE `ID`=12063;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 주인님의 귀빈이시군요. 이곳에서는 부디 조심하시기 바랍니다.', `MaleText_loc4`='啊，主人的贵客。希望您在这里没有到处乱走。', `MaleText_loc5`='小心你踩的地方。', `MaleText_loc7`='Vigila por donde andas.' WHERE `ID`=12064;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 지위를 이용해 슬픔에 잠긴 소년에게 검을 되찾아 오도록 했지. 이제 성인이 된 소년의 마음속에는 복수심과 증오만이 가득할 뿐이오! 대체 왜? 그런데 5년 전이나 지금이나 당신은 그 검을 만져보지도 못하고 있지 않소!', `MaleText_loc4`='是你当时的指挥最终使得沉痛在无尽悲伤之中的孩子如此执着于重铸此剑。如今，这个孩子已经成长成人，可却彻底被复仇的意志与愤恨的偏见占据了身心。这都是为了什么？而且，比起五年前，你与这把剑渐行渐远了。', `MaleText_loc5`='就是你操縱一個悲痛的孩子想盡辦法追回劍。長為成人的孩子心中卻只存復仇與恨意，那是為什麼?與5年前的你相比，現在的你離那把劍更遠了。', `MaleText_loc7`='Tú enviaste a un pobre chico a recuperar la espada. Un chico que creció para convertirse en un hombre que no alberga en su corazón más que odio y venganza. ¿Y para qué? No estás más cerca de conseguir la espada de lo que estabas cinco años atrás.' WHERE `ID`=12065;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직도 파멸의 인도자만 찾으면 어떻게든 전세를 역전할 수 있다고 생각하시오? 사령관, 자네에게 작은 비밀을 하나 알려주지. 파멸의 인도자가 내는 힘은 그것을 사용하는 사람에게서 나오는 것이오... 사령관, 나는 그곳에 있었소. 그가 검을 뽑기도 전에 정의로운 불길이 언데드 군대를 활활 태우는 모습을 보았단 말이오. 슬프군. 당신은 역사에 대한 이해력이... 조금 부족하구려.', `MaleText_loc4`='难道你还认为重铸灰烬使者能够对战争局势产生什么影响么？让我告诉你一个小秘密吧，指挥官。灰烬使者的力量来自于挥舞着它的那个人……当时我也在场，指挥官。我亲眼看着他在圣剑出鞘之前，就以正义之火烧尽了一个军团接一个军团的亡灵士兵。啊……你对历史……实在是了解不多。', `MaleText_loc5`='不過你認為追回灰燼使者可以扭轉戰爭情勢?讓我告訴你一個小秘密，指揮官:灰燼使者的力量來自揮舞它的那個人...而我當時就在那邊，指揮官。我看著他在劍都沒出鞘的時候就用正義之火燃燒不死軍團。哎，你的歷史知識...實在匱乏。', `MaleText_loc7`='¿Y aún piensas que conseguir la espada Crematoria te ayudará de algún modo en esta batalla? Comandante, te contaré un pequeño secreto... El poder de la espada Crematoria procedía del hombre que la empuñaba... Fue allí, Comandante. Yo vi cómo sumía a miles de no-muertos en el fuego incluso antes de haber desenvainado la espada. Por desgracia, careces de conocimientos de historia.' WHERE `ID`=12066;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 입 다물고 당신의 일에 충실하시오. 그렇지 않으면 폴드링 경과 그의 기사들에게 당신이 더는 우호적이 아니라는 사실을 알릴 것이오. 당신이 죗값을 치르는 모습을 본다면 그분께서 매우 기뻐하시겠지.', `MaleText_loc4`='现在你最好搞清楚自己身处哪里，免得我还得以“友善”的词汇通知弗丁大人和他的骑士你已经不在这里了。我猜他一定会非常乐意见到你的“赎罪”。', `MaleText_loc5`='現在請安靜並且注意你現在所在之處，以免我告訴弗丁大人和他的騎士，說你不再屬於友好的一方了。我保證他看到你的『反悔』一定龍心大悅。', `MaleText_loc7`='Y ahora permanece en silencio y ten en cuenta dónde estás. De lo contrario, advertiré a Lord Vadín y a sus caballeros de que ya no eres bien recibida aquí. Estoy seguro de que disfrutará viendo tu "expiación".' WHERE `ID`=12067;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그러니까... 어느날 밤에 훌쩍 남쪽으로 여행을 떠나는 건 어떨까요?! 국경에서 벌어지는 전투를 구경할 수도 있겠죠. 어때요, 살데릴 경? 정말 재미있을 것 같지 않나요?', `FemaleText_loc4`='我就在想……也许我们真的应该在那天晚上去南边看看。也许一边享受野餐，一边看着在国界边进行的战斗？你觉得怎么样，大人？那一定很精彩的！', `FemaleText_loc5`='我在想...這幾天我們一定要找一晚前往南方，也許可以在邊境上來個夜間野餐一邊欣賞戰鬥?你意下如何，閣下?你不覺得這很刺激嗎?', `FemaleText_loc7`='Estaba pensando... que deberíamos hacer un viaje al sur una de estas noches. Podríamos merendar mientras vemos la batalla desde la frontera. ¿Qué te parece? ¿No crees que puede estar bien?' WHERE `ID`=12070;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='유감스럽게도 신도레이의 많은 귀족이 몰락했죠. 그렇다면 조만간 경의 지위가 올라가지 않겠습니까? 정말 기대되는군요!', `FemaleText_loc4`='大人，那么多辛多雷贵族令人扼腕地去世了，这是否意味着您很快就会受到提拔了？我真是为你感到兴奋！', `FemaleText_loc5`='閣下，這麼多辛多雷貴族都不幸走向敗壞，這是不是表示你很可能升官?我真為你感到興奮!', `FemaleText_loc7`='Señor, la nobleza sin''dorei ha sido lamentablemente aplastada. ¿Significa eso que recibirá pronto un nuevo título? ¡Me alegro mucho!' WHERE `ID`=12071;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말 대단하죠. 이제 파티가 시작될 시간입니다.', `FemaleText_loc4`='太棒了。聚会就要开始了。', `FemaleText_loc5`='真是太美妙了。派隊開始。', `FemaleText_loc7`='Maravilloso. Es hora de que empiece la fiesta.' WHERE `ID`=12072;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 망할 짐승들! 이 난국에 좀 도와주실 수는 없소?', `MaleText_loc4`='这些该死的歹徒！我能指望你助我一臂之力吗？', `MaleText_loc5`='這些該死的害蟲!', `MaleText_loc7`='¡Malditas sean todas esas alimañas! Supongo que no podrías ayudarme con esta situación, ¿verdad?' WHERE `ID`=12073;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타우렌에게 랩터 타는 법을 가르쳐 줄 순 없소.', `MaleText_loc4`='我不能教牛头人骑乘迅猛龙。', `MaleText_loc5`='我不想教牛頭人騎乘迅猛龍。', `MaleText_loc7`='No puedo enseñarle a $gun:una; tauren a montar un raptor.', `FemaleText_loc1`='타우렌에게 랩터 타는 법을 가르쳐 드릴 순 없습니다.', `FemaleText_loc4`='我不能教牛头人骑乘迅猛龙。', `FemaleText_loc5`='我不想教牛頭人騎乘迅猛龍。', `FemaleText_loc7`='No puedo enseñarle a $gun:una; tauren a montar un raptor.' WHERE `ID`=12074;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디로 가면 지하마귀 발톱을 찾을 수 있습니까, 레오폴드?', `MaleText_loc4`='我在哪里才能找到地穴恶魔的碎块，雷奥普德？', `MaleText_loc5`='我要去哪找地穴惡魔部位，里歐波?', `MaleText_loc7`='¿Dónde puedo encontrar mefistos de la cripta, Leopold?', `FemaleText_loc1`='어디로 가면 지하마귀 발톱을 찾을 수 있나요, 레오폴드?', `FemaleText_loc4`='我在哪里才能找到地穴恶魔的碎块，雷奥普德？', `FemaleText_loc5`='我要去哪找地穴惡魔部位，里歐波?', `FemaleText_loc7`='¿Dónde puedo encontrar mefistos de la cripta, Leopold?' WHERE `ID`=12075;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 역겨운 짐승들은 어디에나 있습니다.$B$B야외에서 사냥하는 걸 즐긴다면 역병숲과 테러데일 근처에서 놈들을 찾아보십시오. 그리고 동부 역병지대에 있는 거의 모든 스컬지 야영지에도 놈들이 나타납니다.$B$B던전 탐험을 즐기는 편이라면 스트라솔름으로 가십시오. 지하마귀가 사는 지역을 찾을 수 있을 겁니다. 그리고 스칼로맨스에서도 다양한 종류의 소생한 지하마귀를 찾을 수 있을 겁니다.', `MaleText_loc4`='这些污秽的野兽爬满了四处。$B$B如果你喜欢户外狩猎的话，你可以轻松地在病木林和恐惧谷找到它们的，恶蛛隧道里也有大量生存。当然，任何东瘟疫之地的天灾营地里也都会有它们的身影。$B$B此外，如果你真是一个特别优秀的地下城冒险专家的话，你还能在斯坦索姆找到一些，而通灵学院里也有一些通灵魔。', `MaleText_loc5`='那些污穢的野獸充斥此地。$B$B如果你喜歡在戶外狩獵的話，你可以在病木林跟恐懼谷尋獲牠們大部分的蹤跡，也請特別留意惡蛛隧道。牠們也可能出沒在東瘟疫之地的天譴軍團紮營處。$B$B假如你熱衷於地城，你在斯坦索姆會發現更多牠們的蹤影，另外，在通靈學院可以找到一些通靈魔。', `MaleText_loc7`='Esas horribles bestias están por todas partes.$B$BSi prefieres cazarlos al aire libre, los encontrarás en gran número en el Bosque de la Peste y el Valle del Terror, sobre todo en el Túnel Terroarácnido. También se pueden encontrar casi en cualquier campamento de la Plaga de las Tierras de la Peste del Este.$B$BSi te gustan las mazmorras, encontrarás muchos mefistos en Stratholme y algunos necromalignos en Scholomance.' WHERE `ID`=12076;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디로 가면 해골 조각을 찾을 수 있습니까?', `MaleText_loc4`='我在哪里才能找到白骨碎片？', `MaleText_loc5`='我要去哪找骨頭碎片?', `MaleText_loc7`='¿Dónde puedo encontrar trozos de hueso?', `FemaleText_loc1`='어디로 가면 해골 조각을 찾을 수 있나요?', `FemaleText_loc4`='我在哪里才能找到白骨碎片？', `FemaleText_loc5`='我要去哪找骨頭碎片?', `FemaleText_loc7`='¿Dónde puedo encontrar trozos de hueso?' WHERE `ID`=12077;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바보요, 당신? 여기까지 오면서 뼈만 앙상한 해골들이 경관을 망치고 있는 꼴을 못 본 건 아니겠지?$B$B<한숨을 쉬는 로한>$B$B밖에서 활동하는 걸 좋아한다면 동부와 서부 역병지대 전역에서 놈들을 찾을 수 있소. 날 믿으시오. 꼭 당신 눈에 띌 테니까. 놈들은 당신을 절대 놓치지 않으려 할 거요.$B$B던전을 좋아한다면 스트라솔름과 스칼로맨스로 가시오. 해골 조각을 찾기에 아주 좋은 장소요.', `MaleText_loc4`='你傻了吗？你一路上竟然没有看到任何邪恶的玩意？$B$B<洛汉叹了一口气。>$B$B如果在户外的话，你很容易就能在东西瘟疫之地发现各类骷髅生物。相信我，你一定不会错过它们的，当然，它们要是看见了你，也不会错过你……$B$B如果你喜欢地下城，那就去斯坦索姆或者通灵学院，那里也能拿到白骨碎片。', `MaleText_loc5`='你是笨蛋嗎?遺失了你回程時那堆散亂路旁的骷髏類生物?<洛漢嘆氣。>$B$B如果你是戶外型的人，你可在東、西瘟疫之地找到骷髏生物。相信我，你不能搞丟牠們－如果他們可以的話，他們一定不會放過你。倘若你是地城冒險型，斯坦索姆和通靈學院正是尋找為骨頭碎片的地方。', `MaleText_loc7`='¿Eres $gtonto:tonta;? ¿Te has olvidado de las CRIATURAS ESQUELÉTICAS que ensombrecían el paisaje en tu camino hasta aquí?$B$B<Rohan suspira.>$B$BSi prefieres el aire libre, encontrarás criaturas esqueléticas por todas las Tierras de la Peste tanto del Este como del Oeste. Créeme, no puedes dejarlos escapar. Ellos no lo harán contigo si tienen la oportunidad.$B$BSi por el contrario prefieres las mazmorras, has de ir sin duda a Stratholme y Scholomance en busca de trozos de hueso.' WHERE `ID`=12078;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기 트랜퀼리엔에서 보낼 하루는 즐거울까, 우울할까?$B$B$c|1이여;여;, 뭘 도와줄까?', `FemaleText_loc4`='又是一个在塔奎林度过的可爱的、阴暗的日子，你不觉得吗，$c？$B$B我能为你做些什么？', `FemaleText_loc5`='今日的安寧地又是個美好且陰鬱的一天，你說是吧，$c?$B$B有需要我幫忙的地方嗎?', `FemaleText_loc7`='Otro día maravilloso y lóbrego aquí en Tranquillien, ¿no te parece, $c?$B$B¿Qué puedo hacer por ti?' WHERE `ID`=12079;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하늘 높이 날아오르는 것만큼 자유를 만끽할 수 있는 취미도 없답니다. 자, 무엇을 도와드릴까요?', `MaleText_loc4`='没有什么比在天空中翱翔更自由的了，$c。我能为你做些什么吗？', `MaleText_loc5`='沒有什麼是比翱翔天空更自由的事，$c。有什麼需要我幫忙的嗎?', `MaleText_loc7`='La mayor libertad es volar por los cielos, $c. ¿Qué puedo hacer hoy por ti?' WHERE `ID`=12081;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실버문으로 날아가고 싶어요.', `MaleText_loc4`='我想飞回银月城。', `MaleText_loc5`='我想飛一趟銀月城。', `MaleText_loc7`='Querría volver volando a Ciudad de Lunargenta.', `FemaleText_loc1`='실버문으로 날아가고 싶어요.', `FemaleText_loc4`='我想飞回银月城。', `FemaleText_loc5`='我想飛一趟銀月城。', `FemaleText_loc7`='Querría volver volando a Ciudad de Lunargenta.' WHERE `ID`=12082;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오십시오. 오늘은 뭘 도와드릴까요?', `MaleText_loc4`='你好，朋友。今天有什么我可以为你效劳的吗？', `MaleText_loc5`='哈囉，朋友。需要什麼嗎?', `MaleText_loc7`='Hola, amigo. ¿En qué puedo ayudarte hoy?' WHERE `ID`=12083;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='트랜퀼리엔으로 가실 겁니까? 아니면 제가 도울 다른 일이라도 있나요?', `FemaleText_loc4`='是要去塔奎林，还是有什么其它事情我可以帮忙的？', `FemaleText_loc5`='今天開往安寧地，$c。還是你有什麼需要我協助的地方?', `FemaleText_loc7`='¿Te diriges a Tranquillien, $c? ¿Hay algo que pueda hacer por ti?' WHERE `ID`=12084;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='유령의 땅으로 날아가고 싶습니다.', `MaleText_loc4`='是的，我要飞去幽魂之地。', `MaleText_loc5`='是的，我想購買前往鬼魂之地的單程票。', `MaleText_loc7`='Sí, querría comprar un pasaje a las Tierras Fantasma.', `FemaleText_loc1`='유령의 땅으로 날아가고 싶어요.', `FemaleText_loc4`='是的，我要飞去幽魂之地。', `FemaleText_loc5`='是的，我想購買前往鬼魂之地的單程票。', `FemaleText_loc7`='Sí, querría comprar un pasaje a las Tierras Fantasma.' WHERE `ID`=12085;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디로 가면 정령의 정수를 찾을 수 있습니까?', `MaleText_loc4`='我在哪里才能找到元素之核？', `MaleText_loc5`='我要去哪找元素之核?', `MaleText_loc7`='¿Dónde puedo encontrar núcleo de elementos?', `FemaleText_loc1`='어디로 가면 정령의 정수를 찾을 수 있나요?', `FemaleText_loc4`='我在哪里才能找到元素之核？', `FemaleText_loc5`='我要去哪找元素之核?', `FemaleText_loc7`='¿Dónde puedo encontrar núcleo de elementos?' WHERE `ID`=12086;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아주 좋은 질문이군요.$B$B경치 좋은 야외에서 사냥하는 게 좋다면 역병지대, 아즈샤라, 불타는 평원, 악령숲, 실리더스, 여명의 설원에서 정령의 정수를 찾을 수 있어요. 아, 운고로 분화구도요.$B$B위험을 즐기는 편이라면 혈투의 전장으로 가보세요. 그곳에서 다양한 정령의 정수를 아주 많이 찾을 수 있다는 얘기를 들었답니다. 검은바위 나락의 검은무쇠 드워프들이 캐고 있는 정수를 찾아보셔도 좋을 거예요.', `FemaleText_loc4`='啊，这个问题问得好。$B$B如果你喜欢在户外狩猎，那么在瘟疫之地，艾萨拉，燃烧平原，费伍德，希利苏斯，冬泉谷，甚至是安戈洛环形山都有元素生物的存在。$B$B如果你更喜欢直接挑战危险，那么就去厄运之槌吧。我听说大量变异元素都躲在厄运之槌的高墙之后。当然，你也可以在黑石深渊那里找到大量被黑铁矮人所雇佣的元素生物。', `FemaleText_loc5`='啊，好問題。$B$B如果你愛在大戶外獵戰的話，告訴你幾個有元素的地方:瘟疫之地、艾薩拉、燃燒平原、費伍德森林、希利蘇斯、冬泉谷，甚至安戈洛環形山。$B$B又或者，假如你笑談悠遊於危險之中，我聽說厄運之槌那有很多變形元素在牆裡。你也可到黑石深淵裡，好好找找黑鐵矮人使用的元素。', `FemaleText_loc7`='¡Ah! Buena pregunta.$B$BSi prefieres ir de caza al aire libre, encontrarás elementales en las Tierras de la Peste, Azshara, Las Estepas Ardientes, Frondavil, Silithus, Cuna del Invierno e incluso en el Cráter de Un''Goro.$B$BSi te gusta correr riesgos quizás prefieras ir a La Masacre. He oído que sus muros encierran muchos elementos. También puedes ir en busca de los elementos que trabajan para los enanos Hierro Negro de las Profundidades de Roca Negra.' WHERE `ID`=12087;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코팩스, 어디로 가면 검은무쇠 조각을 찾을 수 있습니까?', `MaleText_loc4`='科尔法克斯，我在哪里才能找到黑铁碎片？', `MaleText_loc5`='柯菲斯，我要到哪去找黑鐵碎塊?', `MaleText_loc7`='Korfax, ¿dónde puedo encontrar fragmentos de hierro negro?', `FemaleText_loc1`='코팩스, 어디로 가면 검은무쇠 조각을 찾을 수 있나요?', `FemaleText_loc4`='科尔法克斯，我在哪里才能找到黑铁碎片？', `FemaleText_loc5`='柯菲斯，我要到哪去找黑鐵碎塊?', `FemaleText_loc7`='Korfax, ¿dónde puedo encontrar fragmentos de hierro negro?' WHERE `ID`=12088;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진심으로 묻는 거요? 정말 모른단 말이오?$B$B겁이 많은 편이라면 불타는 평원과 이글거리는 협곡에 사는 생물들에서 검은무쇠 조각을 찾는 것이 좋을 거요.$B$B유혈이 난무하는 모험을 즐기는 편이라면 검은바위 첨탑과 검은바위 나락의 던전으로 가시오. 엄청난 양의 검은무쇠 조각을 얻을 수 있을 것이오.', `MaleText_loc4`='能问些不这么愚蠢的问题吗？你真不知道吗？$B$B要是你胆子小，怕死的话，就去燃烧平原和灼热峡谷的生物身上去找黑铁碎片。$B$B要是你够狠够胆大，干脆杀进黑石塔和黑石深渊算了，那里的黑铁碎片更多。', `MaleText_loc5`='這是很嚴肅的問題?你真的不知道?$B$B如果你是懦弱型的深怕髒了手，你可以在燃燒平原與灼熱峽谷，找找生物身上的黑鐵碎塊。$B$B如果你是嗜血如命的冒險型，你到黑石塔和黑石深淵的地城，會發現有數以萬計的黑鐵碎塊等著你。', `MaleText_loc7`='¿Estás de broma? ¿De verdad no lo sabes?$B$BSi eres más bien cobarde y no te gusta mancharte mucho las manos, encontrarás fragmentos de hierro negro en las criaturas que habitan Las Estepas Ardientes y La Garganta de Fuego.$B$BSi tienes espíritu aventurero, en las mazmorras de Cumbre de Roca Negra y las Profundidades de Roca Negra hay gran número de fragmentos.' WHERE `ID`=12089;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='레인, 어디로 가면 야생 잎사귀를 찾을 수 있습니까?', `MaleText_loc4`='莱茵，我在哪里才能找到蛮荒之叶？', `MaleText_loc5`='瑞恩，我要到哪找野性藻葉?', `MaleText_loc7`='Rayne, ¿dónde debería buscar hojas salvajes?', `FemaleText_loc1`='레인, 어디로 가면 야생 잎사귀를 찾을 수 있나요?', `FemaleText_loc4`='莱茵，我在哪里才能找到蛮荒之叶？', `FemaleText_loc5`='瑞恩，我要到哪找野性藻葉?', `FemaleText_loc7`='Rayne, ¿dónde debería buscar hojas salvajes?' WHERE `ID`=12090;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='밖에서 사냥을 즐기는 편이라면 악령숲에 사는 나무정령과 운고로 분화구의 덩굴손에게서 야생 잎사귀를 찾는 것이 좋습니다.$B$B좀 더 위험을 즐기는 편이라면 혈투의 전장으로 가십시오. 그곳 동쪽과 서쪽 전당은 거의 무한한 야생 잎사귀의 보고이니까요.', `FemaleText_loc4`='如果你喜欢在户外狩猎的话，那么无论是费伍德的树人还是环形山的鞭笞者都是不错的目标，可以提供大量的叶子。$B$B如果你更喜欢冒险，那么厄运之槌东西两翼内都有大量的植物，可以供应足够的叶子。', `FemaleText_loc5`='如果你比較有興趣在戶外狩獵的話，那費伍德樹人與安戈洛鞭笞者就是你很好的樹葉資源。$B$B若你是位更熱愛挑戰的勇者，厄運之槌的東、西雙翼能補給你取之不盡、用之不竭的原始樹葉。', `FemaleText_loc7`='Si eres de los que prefieren estar al aire libre, los antárboles de Frondavil y los azotadores de Un''Goro son una excelente fuente de hojas.$B$BSi te gusta correr riesgos, La Masacre Este y Oeste albergan una cantidad casi ilimitada de hojas salvajes.' WHERE `ID`=12091;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 소중한 우리 땅에서 무슨 짓을 저질렀는지 보세요. 스컬지는 반드시 해치워야 합니다!', `MaleText_loc4`='$C，瞧瞧他们把我们的家园搞成了什么样子。我们必须消灭天灾军团！', `MaleText_loc5`='$C，看看他們對我們可愛的土地做了什麼。天譴軍團一定要被消滅!', `MaleText_loc7`='$C, mira lo que han hecho con nuestras queridas tierras. ¡La Plaga debe ser destruida!' WHERE `ID`=12092;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이번 일은 누구에게나 힘에 부치겠지만, 당신이라면 이 블러드 엘프의 목숨을 구할 수 있을 것입니다.', `FemaleText_loc4`='这可能比较麻烦，但是我想我们能够拯救这个血精灵的生命。', `FemaleText_loc5`='這需要費點功夫，不過我相信我們能拯救血精靈的性命。', `FemaleText_loc7`='Va a costar un poco, pero creo que podemos salvar la vida de este elfo de sangre.' WHERE `ID`=12093;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누구... 시죠? 너무... 추... 추워요.', `MaleText_loc4`='你是谁？我感觉……好……冷。', `MaleText_loc5`='我...不行了...我失敗了。', `MaleText_loc7`='¿Quién eres? Siento... tanto... frío.' WHERE `ID`=12094;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='부끄럽게도 우리 신도레이는 고향이라 부르던 곳을 너무 많이 잃었소. 머지않아 우리는 힘을 회복하고 스컬지로부터 우리 남쪽 영토를 되찾을 것이오!', `FemaleText_loc4`='真让人感到羞耻，我们辛多雷在这个曾经被我们称为家的地方失去了很多东西。很快，我们就将重新获得力量，并把我们南方的领土从天灾手里夺回来。', `FemaleText_loc5`='我們辛多雷失守了這麼多老家園的土地真是可恥。我們一定能很快恢復元氣，然後從天譴軍團那奪回屬於我們的土地!', `FemaleText_loc7`='Es vergonzoso que nosotros, los sin''dorei, hayamos perdido tanto de lo que solíamos llamar hogar. No pasará mucho tiempo antes de que recobremos nuestra fuerza y recuperemos nuestras tierras del sur del control de la Plaga.' WHERE `ID`=12095;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 당신과 ''냄새 알아맞히기'' 놀이나 하고 있을 시간이 없소. 용건을 말하든가 아니면 내 눈앞에서 사라져 주시오!', `MaleText_loc4`='我太忙了，根本没有时间来陪你玩什么游戏， $r。有事就说，没事就从我眼前消失！', `MaleText_loc5`='我沒那時間跟你玩猜謎遊戲，$r。說出你的來意，然後消失在我眼前吧!', `MaleText_loc7`='Estoy demasiado ocupado como para andarme con juegos, $r. ¡Dime qué quieres o desaparece de mi vista!' WHERE `ID`=12096;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고위집행관과 귀부인 아우리페러스께서는 기다리라고 하셨지만 시간이 없습니다! 제 친구들이 저기 밖에서 죽어가고 있습니다!', `MaleText_loc4`='高级执行官和奥莉菲洛丝夫人要我在一旁候着，我可没那么多时间！我的朋友已经奄奄一息了，$C！', `MaleText_loc5`='高階執行官和阿莉法娜奧絲夫人讓我在哪邊枯等，但我真的沒時間!我朋友正在垂死邊緣掙扎啊，$c!', `MaleText_loc7`='¡El Sumo Ejecutor y la Dama Aurífera me están haciendo esperar, pero no tengo tiempo para esto! ¡Mis amigos están ahí fuera muriendo, $c!' WHERE `ID`=12097;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='남쪽 원정순찰대 초소에 순찰자 살리사, 서쪽 트랜퀼리엔에 순찰자 레스발린을 보낸 지 하루가 넘었습니다! 그들을 보신 적이 없습니까? 혹시 그들의 부탁을 받고 오신 분입니까?', `FemaleText_loc4`='我在几天前派了游侠萨尔莉莎去南面的营地，派游侠莱瑟瓦林去了西面的塔奎林！你遇到过他们两个吗？你是不是他们派回来的援兵？', `FemaleText_loc5`='我一天多前就派遊俠沙里莎往南去了營地，還有遊俠萊斯瓦林往西去安寧地!你都沒見到他們兩個嗎?你是被派回來的援軍嗎?', `FemaleText_loc7`='¡Envié a la forestal Salissa al sur al enclave y al forestal Lethvalin al oeste, a Tranquillien, hace más de un día! ¿Has visto a alguno de los dos ¿Eres la ayuda que debían enviar?' WHERE `ID`=12098;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시는 아우리페러스 귀부인을 위해 일하는 평범한 관리로 돌아갈 수 없을 것 같다는 생각을 종종 합니다. 저는 전쟁을 할 준비가 안 됐어요.$B$B쿠엘탈라스를 예전처럼 아름답게 복원하려고 열정을 불태우는 그대 같은 분들이 있어서 정말 다행입니다. 스컬지를 해치워 주십시오! 보이는 족족 놈들을 없애주십시오!', `MaleText_loc4`='有时我会觉得，我永远也不能再像以前那样单纯地为奥莉菲洛丝夫人服务了。战争完全扰乱了我的生活。$B$B好在还有你这样的人物，致力于使奎尔萨拉斯恢复它原有的平静。消灭亡灵天灾，$C！竭尽全力消灭他们！', `MaleText_loc5`='有時候我覺得我好像永遠也無法回歸到簡單正常的生活來效忠阿莉法娜奧絲夫人。我永遠也離不開戰爭。$B$B幸好總是有像你這樣的人熱切於見到奎爾薩拉斯回到它原來的樣貌。摧毀天譴軍團，$c!不管你在何方都要摧毀他們!', `MaleText_loc7`='A veces siento que nunca volveré a ser un simple funcionario al servicio de la Dama Aurífera. No estoy hecho para la guerra.$B$BAfortunadamente están aquellos, como tú, que arden en deseos de ver la antigua belleza de Quel''Thalas devuelta a ella. ¡Aplasta a la Plaga, $c! ¡Aplástalos dondequiera que puedas!' WHERE `ID`=12099;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 영웅이 오셨군요! $n, 다시 만나서 반갑습니다! 지금도 스컬지를 보이는 대로 해치우고 있겠지요?', `MaleText_loc4`='瞧，当世的英雄！很高兴再次见到你，$n！一旦发现天灾士兵，你是绝不会手下留情的，对吗？', `MaleText_loc5`='啊，$g英雄:女英雄;來了!好開心再見到你，$n!我相信你仍在消滅看到的天譴軍團吧?', `MaleText_loc7`='Ah, aquí está $gel héroe:la heroína; del momento! ¡Me alegro de volver a verte, $n! Confío en que sigues destruyendo a los miembros de la Plaga cuando los encuentras, ¿no es cierto?' WHERE `ID`=12100;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='원정순찰대 초소에서 곧 지원 병력이 도착해서 저와 이 쓸모없는 부관을 구출해 갈 것입니다. 이 주변에 머물다 보면 좀 꺼림칙한 기분이 드실 수도 있습니다. 저도 호수와 저기 저쪽에 있는 마을 근처에서 온갖 이상한 소리를 들었으니까요.', `FemaleText_loc4`='我相信从远行者营地来的援军很快就会到达这里，帮助我和这个没用的上尉回到安全的地方。你可能不想在这里逗留，因为我听到了从湖里和远处村庄那边传来的各种奇怪的声音。', `FemaleText_loc5`='我確定旅行者營地的援助很快就會趕來這裡幫我和這個無用的中尉脫離險境。你最好別在這裡逗留;我聽到湖那邊和村子那裡都有各種怪聲傳來。', `FemaleText_loc7`='Estoy segura de que la ayuda del Enclave del Errante estará aquí pronto para ayudarme a mí y a este teniente inútil a ponernos a salvo. Puede que no quieras quedarte cerca; he oído todo tipo de sonidos extraños que provenían del lago y de aquel pueblo a lo lejos.' WHERE `ID`=12101;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제브소라에서 순찰자 발란나와 부관을 도와줬다는 얘기를 들었습니다.$B$B감사합니다. 저는 이만 원정순찰대 초소로 돌아가야겠습니다.', `MaleText_loc4`='我得到消息说你帮助了游侠瓦兰娜和派往塞布索雷的上尉。$B$B感谢你，$c。我想我现在应该回远行者营地了。', `MaleText_loc5`='我聽說你幫了遊俠瓦拉娜和札布索拉的中尉。$B$B謝謝你，$c。我想我現在要回旅行者營地了。', `MaleText_loc7`='Me han informado de que pudiste ayudar a la forestal Valanna y al teniente en Zeb''Sora.$B$BGracias, $c. Supongo que ahora debería encaminarme de vuelta al Enclave del Errante.' WHERE `ID`=12102;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기는 무슨 일로 왔나?', `MaleText_loc4`='什么风把你吹到这里来的，$c？', `MaleText_loc5`='是什麼風把你吹到這裡來，$c?', `MaleText_loc7`='¿Qué te trae por aquí, $c?' WHERE `ID`=12103;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디를 찾으십니까?', `MaleText_loc4`='我能帮你什么忙吗？', `MaleText_loc5`='我能幫你找什麼?', `MaleText_loc7`='¿Qué te puedo ayudar a encontrar?', `FemaleText_loc1`='어디를 찾으십니까?', `FemaleText_loc4`='我能帮你什么忙吗？', `FemaleText_loc5`='我能幫你找什麼?', `FemaleText_loc7`='¿Qué te puedo ayudar a encontrar?' WHERE `ID`=12104;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 준비가 제대로 된 것 같군. 자, 이제 떠나볼까?!', `MaleText_loc4`='好吧，一切看起来都井然有序。让我们一路看戏吧。', `MaleText_loc5`='好，全部都到位了。好戲要上場囉。', `MaleText_loc7`='Muy bien, todo parece estar en orden. ¡Que comience el espectáculo!' WHERE `ID`=12105;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$r|1이여;여;, 참 반갑군. 자네도 알다시피 아직 장사 개시 전일세. 그럼 바빠서 이만 실례!', `MaleText_loc4`='啊，你好啊，$r。就像你所看到的那样，我还没开张。对不起，我现在很忙。', `MaleText_loc5`='啊，你好，$r。如你所見，我還沒開始營業。所以，如果你不介意，我要先忙了。', `MaleText_loc7`='Ah, hola, $r. Como puedes ver, todavía no tengo abierto para los clientes. Si me disculpas, tengo mucho que hacer.' WHERE `ID`=12106;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 보니 기쁘기 그지없군. 아, 정말이라니까! 여기서 장사를 시작할 수 있었던 것도 다 자네 덕분 아니겠나.$B$B그래, 오늘은 뭘 사러 왔나?', `MaleText_loc4`='很高兴再次看到你，$c。不，真的，你是我能在这里发大财的原因。$B$B现在，有什么我可以出售给你的吗？', `MaleText_loc5`='很高興再見到你，$c。不，真的。你是我會在這裡賺錢，掌管一切的原因。$B$B那麼，你今天想跟我買些什麼?', `MaleText_loc7`='Es un gran placer volver a verte, $c. No, en serio. Eres la razón por la que estoy haciendo dinero aquí rápidamente.$B$BBueno, ¿qué te puedo vender hoy?' WHERE `ID`=12107;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='트랜퀼리엔에 오신 것을 환영하오. 현재 상황에 대해서는 사과를 드리겠소. 보다시피 문제가 좀 있지만 놀랍게도 포세이큰과 여군주 실바나스 윈드러너가 적절한 시기에 큰 도움이 되고 있소.$B$B우리를 도울 의향이 있다면 사양하지 않겠소. 우리를 기다리는 엄청난 수의 적을 상대하려면 최대한 많은 도움이 필요하니까 말이오.', `FemaleText_loc4`='欢迎来到塔奎林，$c。我对你所看到的状况感到抱歉。就像你所看到的那样，我们有一些麻烦，但是遗忘者和他们的女王希尔瓦娜斯·风行者在我们需要的时候高尚地给了我们大量的帮助。$B$B如果你能帮忙的话，请不要犹豫不决。我们需要所有可以借助的力量。', `FemaleText_loc5`='歡迎來到安寧地，$c。很抱歉你發現了這樣的狀況。如你所見，我們有了些麻煩，不過被遺忘者，和他們的領導者希瓦娜斯·風行者，非常好心的在我們有需要的時候給予我們大量的援助。$B$B如果你能伸出援手請千萬不要猶豫。我們在面臨無數軍力對抗的時候會善用各種能獲得的協助。', `FemaleText_loc7`='Te doy la bienvenida a Tranquillien, $c. Debo disculparme por el estado en que la encuentras. Como ves, hemos tenido algunos problemas, pero los Renegados y su Lady Sylvanas Brisaveloz han sido lo suficientemente corteses como para prestarnos mucha ayuda en nuestro tiempo de necesidad.$B$BSi puedes echar una mano, no dudes en hacerlo. Todos podemos hacer uso de la ayuda que podamos en nuestra lucha contra la miríada de fuerzas formadas contra nosotros.' WHERE `ID`=12108;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕의 침략에 대항하여 호드와 얼라이언스가 노스렌드로 전진할 때가 왔습니다. 최근 칼림도어와 동부 왕국의 여러 지역이 공격 받고 있다는 소식입니다. 놈들의 손에 파괴되고 있는 우리 땅을 지키기 위해 무기를 들 각오는 되어 있습니까?', `MaleText_loc4`='部落与联盟远征诺森德，抵御巫妖王的入侵的时刻已经降临。这些日子依赖，卡利姆多和东部王国都遭到了攻击。你愿意拿起武器，保卫自己的家园吗？', `MaleText_loc5`='該是部落和聯盟注意北裂境和巫妖王入侵的時候了。最近這些日子，整個卡林多和東部王國都遭到攻擊。你是否會開始全副武裝保護你的土地免於他們的摧毀呢?', `MaleText_loc7`='Ha llegado la hora de que la Horda y la Alianza miren hacia Rasganorte y la invasión de la Plaga. En días recientes, los territorios a través de Kalimdor y los Reinos del Este han sufrido ataques. ¿Levantarás armas para salvar tu tierra de la destrucción a manos de ellos?' WHERE `ID`=12109;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼을 겁내지 말게나. 하나도 위험하지 않으니까!', `MaleText_loc4`='剑而已，不用害怕。要小心羊肉才是真的！', `MaleText_loc5`='別怕劍，一點點地啃。這是要給你的羊肉。', `MaleText_loc7`='No tengas miedo de la espada. ¡Es el cordero!' WHERE `ID`=12110;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 이교도들은 제정신이 아니로군...', `MaleText_loc4`='这个信徒陷入了恍惚的状态……', `MaleText_loc5`='這名祭司處於深沉的沉睡狀態...', `MaleText_loc7`='Este cultor está en estado de trance...' WHERE `ID`=12111;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음의 룬을 8개 사용하여 그가 의식을 치르지 못하도록 막아야 합니다.', `MaleText_loc4`='使用8枚死灵符文，扰乱他的法阵。', `MaleText_loc5`='使用8個亡域符文並中斷他的儀式。', `MaleText_loc7`='Utiliza 8 runas necróticas para detener su ritual.', `FemaleText_loc1`='죽음의 룬을 8개 사용하여 그가 의식을 치르지 못하도록 막아야 합니다.', `FemaleText_loc4`='使用8枚死灵符文，扰乱他的法阵。', `FemaleText_loc5`='使用8個亡域符文並中斷他的儀式。', `FemaleText_loc7`='Utiliza 8 runas necróticas para detener su ritual.' WHERE `ID`=12112;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이랴, 앞으로! 최전선이 우리를 기다린다!', `MaleText_loc4`='前进！前线在等待着我们！', `MaleText_loc5`='前進!向前線衝吧!', `MaleText_loc7`='¡Adelante! ¡La primera línea de batalla espera!' WHERE `ID`=12113;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='휴! 정말 힘들었어. 스컬지가 이렇게 날뛰는 건 처음 본단 말이야...$B$B<마른 침을 삼키는 경비병 디디어>$B$B그 마지막 전쟁 이후로...', `MaleText_loc4`='呼哧！这真是不容易，$r。很久没有见到天灾军团主动攻击了，自从……$B$B<卫兵迪迪尔喘了几口粗气。>$B$B自从上一次大战以后……', `MaleText_loc5`='唷!那是個辛苦的工作呢，$r。我以前還沒見過這麼具侵略危險的天譴軍團啊...$b$b<迪笛兒困難的吞了一口口水。>$B$B自從上一次戰爭...', `MaleText_loc7`='¡Uf! Ha sido duro, $r. No veía tanta agresividad por parte de la Plaga desde...$B$B<El guardia Didier traga saliva.>$B$BDesde la última guerra...' WHERE `ID`=12114;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하세요... 뒤에 나이트 엘프들입니다!', `MaleText_loc4`='留神……暗夜精灵回来了！', `MaleText_loc5`='小心...夜精靈回來了!', `MaleText_loc7`='Cuidado... ¡Los elfos de la noche han vuelto!' WHERE `ID`=12115;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노새들에게 벌어진 일은 정말 끔찍했어... 메츠는 이번 일이 실패한 책임을 물어 날 가만두지 않을 걸세.', `MaleText_loc4`='太可怕了，这些骡子到底怎么了……要是这样下去，梅兹会把我剥了皮的。', `MaleText_loc5`='恐怖的事情是，發生在那些騾身上的事...這次失敗，梅茲一定需要我的掩護。', `MaleText_loc7`='Es terrible... lo que le ocurrió a las mulas... Metz pedirá mi pellejo por este fracaso.' WHERE `ID`=12116;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이번에는 빠져나갈 수 없을 것이다!', `FemaleText_loc4`='你这次逃不掉了！', `FemaleText_loc5`='你這次逃不了了!', `FemaleText_loc7`='¡Esta vez no escaparás!' WHERE `ID`=12117;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불쌍한 녀석! 아직 새끼일 뿐인데...', `MaleText_loc4`='可怜的小驴子。它还没长大呢。', `MaleText_loc5`='可憐的小驢。不就只是個小傢伙。', `MaleText_loc7`='Pobre burro. Todavía era muy joven.' WHERE `ID`=12118;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나이트 엘프가 무슨 일을 꾸미고 있는지 알아내는 일은 무척 중요하오! 전력을 다해 그들의 목적을 알아내 주시오.', `FemaleText_loc4`='查明那些暗夜精灵想干什么对我们来说很重要，$c！请朝着这个目标努力吧。', `FemaleText_loc5`='讓我們了解夜精靈到底在搞什麼鬼是相當重要的，$c!請全心致力於對抗他們直到最後。', `FemaleText_loc7`='Es muy importante que averigüemos qué están tramando los elfos de la noche, $c. Centra todos tus esfuerzos en ese fin.' WHERE `ID`=12119;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나이트 엘프를 상대로 그대가 보여준 행동에 정말 감동했소. 그대가 그들이 지맥의 결합점과 달의 수정이라는 물건을 사용해 우리를 염탐한다는 사실을 알아낸 덕분에 훨씬 유리한 위치에 서게 되었소.$B$B$n, 모두를 대신해서 감사드리오.', `FemaleText_loc4`='你对暗夜精灵们采取的行动让我们感到非常高兴。你揭开了他们利用魔网能量线的阴谋，以及他们使用所谓的月亮水晶来监视我们的计划。这些都坚实地巩固了我们在这里的地位。$B$B我们非常感谢你，$n。', `FemaleText_loc5`='我們對你對抗夜精靈的行為感到非常滿意。當你發現他們使用能量界線連結點和他們所謂的月水晶來監視我們的計謀，你就大大地鞏固了我們在這裡的情勢。$B$B我們都很感謝你，$n。', `FemaleText_loc7`='Nos complacen mucho tus actividades contra los elfos de la noche. Cuando descubriste su plan de emplear los nexos de líneas Ley y sus cristales lunares para espiarnos, reforzaste en gran medida nuestra posición actual.$B$BTe lo agradecemos, $n.' WHERE `ID`=12120;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지원병으로 오셨습니까? 나이트 엘프는 이미 다른 곳으로 이동했습니다!', `MaleText_loc4`='你是来增援的吗？', `MaleText_loc5`='你是援軍嗎?夜精靈已被擊潰了!', `MaleText_loc7`='¿Son ustedes los refuerzos? ¡Los elfos de la noche han sido vencidos!' WHERE `ID`=12121;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안오윈에 있는 달의 수정을 멈춘 것은 정말 잘하신 일입니다, $c|1이여;여;! 제 연구에 동참하고 싶거든 언제든지 이곳으로 찾아오십시오.', `MaleText_loc4`='你破坏了安欧维恩的月亮水晶，干得很好，$C！如果你对我的研究工作感兴趣的话，可以随时来找我。', `MaleText_loc5`='你將安歐恩的月水晶能源關閉是一件好事，$c!如果你想為我這裡的研究提供一點貢獻歡迎你隨時過來。', `MaleText_loc7`='¡Menos mal que desactivaste el cristal lunar en An''owyn cuando lo hiciste, $c! Ven cuando te apetezca ayudarme con mi investigación.' WHERE `ID`=12122;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성명, 계급, 군번을 대시오.', `MaleText_loc4`='报上你的名字，军阶，还有编号。', `MaleText_loc5`='名字，兵籍，兵籍號碼，士兵。', `MaleText_loc7`='Nombre, rango y número de serie, Soldado.' WHERE `ID`=12123;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네! 감사합니다, 사령관님!', `MaleText_loc4`='是，长官！谢谢您，长官！', `MaleText_loc5`='是，長官!謝謝長官!', `MaleText_loc7`='¡Sí, señor! ¡Gracias, señor!', `FemaleText_loc1`='네! 감사합니다, 사령관님!', `FemaleText_loc4`='是，长官！谢谢您，长官！', `FemaleText_loc5`='是，長官!謝謝長官!', `FemaleText_loc7`='¡Sí, señor! ¡Gracias, señor!' WHERE `ID`=12124;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<투덜거리는 야전사령관 챔버스>$B$B이곳까지 보급품을 무사히 수송하도록 디디어를 도와주었다는 애송이가 바로 당신이오? 나머지 사람들은 어디 있소? 더 많은 걸로 알고 있는데... 당신 같은 애송이들은 보통 무리를 지어 몰려다니더군.$B$B흥, 서명은 해줄 테니 확인서나 이리 주시오.', `MaleText_loc4`='<查博斯元帅咆哮着。>$B$B你们就是那群帮迪迪尔把这些补给运到这鬼地方来的家伙吗？这就是你们的全部人马？还有其他人吗？在哪儿？小鸡一般都是成群结队的。$B$B好吧好吧，给我该死的文件，我签了它，现在就签了它。', `MaleText_loc5`='<戰場元帥錢柏咆哮。>$B$B所以，你是迪笛兒底下負責整套補給的廢渣?其他人呢?我知道這裡一定還有很多人吧。像你這樣的鼠輩大部分都一起遊盪無所事事。$B$B呸!快給我那要命的文件，我趕緊簽完。', `MaleText_loc7`='<El mariscal de campo Cuevas protesta.>$B$B¿Así que tú eres el que ayudó a Didier a traer las provisiones sanas y salvas? ¿Dónde están los demás? Sé que sois más. Los gallinas como tú siempre andan en manada.$B$BVenga, dame la condenada libranza para que pueda firmarla.' WHERE `ID`=12125;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 잘했다, 제군! 이만 해산!', `MaleText_loc4`='干得不错，士兵。解散！', `MaleText_loc5`='做的好，士兵。解散!', `MaleText_loc7`='Buen trabajo, Soldado. ¡Retírese!' WHERE `ID`=12126;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 지금 서명해 주지. 그 확인서를 이리 주시오.', `MaleText_loc4`='好的，我马上就会签署书面命令的。把它们带去前线吧。', `MaleText_loc5`='沒問題，我馬上簽文件。帶他們到前面，臭蛆。', `MaleText_loc7`='Muy bien, ahora firmaré las libranzas. ¡Traedlas al frente, gusanos!' WHERE `ID`=12127;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 소리가 들린 거 같은데! 챔버스 부인이 오시는 게 분명하군. 비켜라! 길을 비키시오!', `MaleText_loc4`='我想我听到了什么！一定是查伯斯来了。快跑！快跑！', `MaleText_loc5`='我好像聽到腳步聲了!一定是大元帥錢柏來了。讓路!讓路!', `MaleText_loc7`='¡Creo que he oído algo! Parece que se trata de Cuevas. ¡Abrid paso! ¡Abrid paso!' WHERE `ID`=12128;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 환경에서 어떻게 일을 하라는 말입니까?! 게다가 주위에는 역겨운 포세이큰 놈들이 득실대고 있습니다! 트랜퀼리엔과 쿠엘탈라스도 볼 장 다 봤군요!', `MaleText_loc4`='这种环境让我怎么做事？！这地方到处都是恶心的被遗忘者！我真为塔奎林和奎尔萨拉斯感到悲哀！', `MaleText_loc5`='在這樣的情況之下我要怎麼工作?!還有全部這些噁心的被遺忘者!我為安寧地和奎爾薩拉斯悲嘆!', `MaleText_loc7`='¿Cómo he de trabajar en estas condiciones? ¡Y con todos estos Renegados por aquí! ¡Cuánto me aflige ver a Tranquillien y Quel''Thalas así!' WHERE `ID`=12129;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일입니까? 제가 지금 바쁜 것이 안 보이세요?', `MaleText_loc4`='嗯……你想要什么，$r？你没看到我正忙着吗？', `MaleText_loc5`='什麼事...你想要做什麼，$r?你看不出來我在這裡忙著嗎?', `MaleText_loc7`='Sí... ¿qué quieres, $r? ¿No ves que estoy ocupado?' WHERE `ID`=12130;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보고하라, $R|1이여;여;! 중요한 소식이라도 가져 왔나? 용건만 빨리 말해라. 귀부인 아우리페러스와 전략 회의 중이었다.', `MaleText_loc4`='$R，快说！你带来了什么重要的消息？快点去做你该做的事情……奥莉菲洛丝夫人和我正在进行一次战略讨论。', `MaleText_loc5`='$R，報告!你帶了什麼重要的消息來?快點說吧...我和阿莉法娜奧絲夫人正在做策略的商討。', `MaleText_loc7`='¡Informa, $r! ¿Qué noticias importantes tienes? No te entretengas... La Dama Aurífera y yo estamos en plena discusión estratégica.' WHERE `ID`=12131;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='엘리고르 사령관님, 신선한 생선 구이랍니다. 많이 드세요!', `FemaleText_loc4`='指挥官，您的鱼。请慢用！', `FemaleText_loc5`='好，這一道是魚料理，指揮官。請享用!', `FemaleText_loc7`='Comandante, aquí está la fuente de pescado. ¡Buen provecho!' WHERE `ID`=12132;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='신부님 앞에는 상큼한 아제로스 과일 모둠이 있네요. 참 신선해 보이죠?', `FemaleText_loc4`='神父，盛水果的碗在你那边吗？在吗？', `FemaleText_loc5`='神父，吃過水果了?對吧?', `FemaleText_loc7`='Padre, has pedido un cuenco de fruta, ¿no es cierto?' WHERE `ID`=12133;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그리고 숙녀 분께는 구운 새끼 멧돼지 요리를 준비했어요. 많이 드세요!', `FemaleText_loc4`='女士们，尽情享用烤乳猪吧！', `FemaleText_loc5`='這道是特別為女士提供的，烤乳豬。請享用!', `FemaleText_loc7`='Y para las damas, jabalí asado. ¡Que lo disfrutéis!' WHERE `ID`=12134;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='필요한 게 있으면 언제든지 말씀만 하세요!', `FemaleText_loc4`='要是你们还有什么需要的话，直接和我说！', `FemaleText_loc5`='需要什麼儘管講，別客氣!', `FemaleText_loc7`='¡Por favor, avisadme si necesitáis algo más!' WHERE `ID`=12135;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='모험가여, 희망의 빛 예배당에 오신 것을 환영합니다.', `FemaleText_loc4`='欢迎来到圣光之愿礼拜堂，陌生人。', `FemaleText_loc5`='歡迎光臨聖光之願禮拜堂，陌生人。', `FemaleText_loc7`='$gBienvenido:Bienvenida; a la Capilla de la Esperanza de la Luz, $gforastero:forastera;.' WHERE `ID`=12136;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주방장에게 훌륭했다고 전해 주시오!', `MaleText_loc4`='赞美厨子！', `MaleText_loc5`='謹向大廚獻上我的讚美!', `MaleText_loc7`='¡Mis felicitaciones a la cocinera!' WHERE `ID`=12137;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제시카, 이 생선 맛은 정말 최고로군.', `MaleText_loc4`='这鱼棒极了，杰希卡。', `MaleText_loc5`='這條魚煮得好，潔西卡。', `MaleText_loc7`='El pescado está exquisito, Jessica.' WHERE `ID`=12138;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음, 정말 맛있어!', `MaleText_loc4`='真是美味！', `MaleText_loc5`='好吃!', `MaleText_loc7`='¡Delicioso!' WHERE `ID`=12139;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다, 챔버스 부인!', `MaleText_loc4`='谢谢你，查伯斯先生。', `MaleText_loc5`='謝謝你，錢柏太太。', `MaleText_loc7`='Gracias, señora Cuevas.' WHERE `ID`=12140;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거 망고입니까? 굉장하군요!', `MaleText_loc4`='这真是芒果么！跟西瓜一样大！', `MaleText_loc5`='這是芒果嗎?了不起啊!', `MaleText_loc7`='¿Esto es un mango? ¡Formidable!' WHERE `ID`=12141;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 어느 때보다 훌륭하군요! 챔버스 부인, 곰팡이가 하나도 안보여요!', `MaleText_loc4`='你这次确实已经尽了自己最大的努力，查伯斯夫人。一个铸模都没有找到！', `MaleText_loc5`='你這次真的超越自己了，錢柏太太。一點污點都沒有!', `MaleText_loc7`='Esta vez se ha superado, señora Cuevas. ¡Todo está riquísimo!' WHERE `ID`=12142;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고마워요, 제시카!', `FemaleText_loc4`='谢谢你，杰希卡。', `FemaleText_loc5`='謝謝你，潔西卡。', `FemaleText_loc7`='Gracias, Jessica.' WHERE `ID`=12143;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그리고 당신 드레스 정말 예쁘네요! 어디서 구하셨는지 꼭 알려주세요.', `FemaleText_loc4`='我不得不说……这件礼服太漂亮了！你一定要告诉我，你是从哪里买到它的。', `FemaleText_loc5`='還有我想說的是，這身打扮太迷人了!你一定要告訴我在那裡買的。', `FemaleText_loc7`='Y permítame que le diga que lleva un vestido precioso. Tiene que decirme dónde lo ha comprado.' WHERE `ID`=12144;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제시카, 정말... 아름다운 드레스예요.', `FemaleText_loc4`='真的……漂亮的衣服，杰希卡。', `FemaleText_loc5`='真的是...好美的衣服，潔西卡。', `FemaleText_loc7`='Sí, un vestido realmente bonito, Jessica.' WHERE `ID`=12145;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 멧돼지 요리, 정말 최고예요!', `FemaleText_loc4`='这猪排棒极了！', `FemaleText_loc5`='這嫩豬肉實在頂級啊!', `FemaleText_loc7`='¡El jabalí está delicioso!' WHERE `ID`=12146;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오, 이 풍부한 육즙... 정말 고마워요, 챔버스 부인!', `FemaleText_loc4`='哦，真是多汁肥美的猪排，非常感谢，查伯斯先生。', `FemaleText_loc5`='噢，多汁又美味。多謝了，錢柏太太。', `FemaleText_loc7`='¡Y muy sabroso! Muchas gracias, señora Cuevas.' WHERE `ID`=12147;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 이 짐노새들은 하루에 두 번 나간다네. 그런데, 스컬지가 길을 비켜주지 않아 디디어와 노새들이 최전선에 보급품을 수송하지 못하면 난 끝장일세. 이렇게 환장할 노릇은 처음이군. 보급품 수송을 안전하게 지켜줄 영웅이 있다면 얼마나 좋겠나...', `MaleText_loc4`='我们的大篷车队会往前线运送物资，每天两次。要是不能帮助负责运送的迪迪尔和他的骡子清理掉路上骚扰的天灾士兵的话，我就得挨罚了。那可是我所见过的最疯狂的事。看来我们得像英雄那样冒险保护货物了。', `MaleText_loc5`='我們的商隊大約一天出隊2次，萬一天譴軍團又去阻止迪笛兒，還有要送往前線的那些騾，那到時我就會被指責。這還是我前所未見最瘋狂的事情。但願我們有英勇的冒險精神能保護這運送過程...', `MaleText_loc7`='Nuestras caravanas parten dos veces al día pero también es cierto que la Plaga les ha salido al encuentro para detener a Didier y sus mulas y así evitar que el envío llegue a las primeras líneas. Es lo más arriesgado que he visto en mi vida. Si contáramos con valientes que custodiaran los envíos...' WHERE `ID`=12148;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고통과... 욕구... 더 먹고 싶다...', `MaleText_loc4`='太痛苦了……我……我渴望更多……', `MaleText_loc5`='那種痛苦...那種需要...我還渴望更多...', `MaleText_loc7`='El dolor... necesito... quiero más...', `FemaleText_loc1`='고통과... 욕구... 더 먹고 싶다...', `FemaleText_loc4`='太痛苦了……我……我渴望更多……', `FemaleText_loc5`='那種痛苦...那種需要...我還渴望更多...', `FemaleText_loc7`='El dolor... necesito... quiero más...' WHERE `ID`=12149;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더, 더, 더! 당장 먹을 것이 필요하다.', `MaleText_loc4`='多点，再多点！我必须马上吃点什么。', `MaleText_loc5`='更多，更多，更多!我一定要立刻被餵飽。', `MaleText_loc7`='¡Más, más, más! Debo alimentarme pronto.', `FemaleText_loc1`='더, 더, 더! 당장 먹을 것이 필요하다.', `FemaleText_loc4`='多点，再多点！我必须马上吃点什么。', `FemaleText_loc5`='更多，更多，更多!我一定要立刻被餵飽。', `FemaleText_loc7`='¡Más, más, más! Debo alimentarme pronto.' WHERE `ID`=12150;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고통을 견딜 수가 없다. 새로운 원천을 찾아야 한다.', `MaleText_loc4`='我不能忍受这痛苦了。我必须找到新的魔法源。', `MaleText_loc5`='我無法忍受那種痛苦。我一定要找到新源頭。', `MaleText_loc7`='No puedo soportar el dolor. Debo encontrar una nueva fuente.', `FemaleText_loc1`='고통을 견딜 수가 없다. 새로운 원천을 찾아야 한다.', `FemaleText_loc4`='我不能忍受这痛苦了。我必须找到新的魔法源。', `FemaleText_loc5`='我無法忍受那種痛苦。我一定要找到新源頭。', `FemaleText_loc7`='No puedo soportar el dolor. Debo encontrar una nueva fuente.' WHERE `ID`=12151;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제발 좀 비켜 주십시오! 시간은 부족한데 할 일은 산더미 같아서요.', `MaleText_loc4`='事情太多，时间太少，$r！拜托，别挡我的道。', `MaleText_loc5`='我事情太多，時間根本不夠用，$r!拜託，別擋我路。', `MaleText_loc7`='¡Tengo mucho que hacer y poco tiempo para hacerlo, $r! Por favor, apártate de mi camino.', `FemaleText_loc1`='제발 좀 비켜 주십시오! 시간은 부족한데 할 일은 산더미 같아서요.', `FemaleText_loc4`='事情太多，时间太少，$r！拜托，别挡我的道。', `FemaleText_loc5`='我事情太多，時間根本不夠用，$r!拜託，別擋我路。', `FemaleText_loc7`='¡Tengo mucho que hacer y poco tiempo para hacerlo, $r! Por favor, apártate de mi camino.' WHERE `ID`=12152;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좀 비켜주시겠어요? 할 일은 태산인데 시간은 없단 말입니다!$B$B진흙구더기나 부패병에 감염된 분이라면, 제가 도울 수 있을 것 같군요.', `MaleText_loc4`='事情太多，时间太少，$r！拜托，别挡我的道。$B$B但如果你中了蛆毒或食尸鬼疫病的话，我可以帮助你。', `MaleText_loc5`='我事情太多，時間根本不夠用，$r!拜託，別擋我路。$B$B萬一你被蛆蟲粘液跟腐爛食屍鬼感染的話，我有能力治療各種疾病。', `MaleText_loc7`='¡Tengo mucho que hacer y poco tiempo para hacerlo, $r! Por favor, apártate de mi camino.$B$BSi te has contagiado con baba de gusano o la putrefacción de los necrófagos, quizás pueda ayudarte.', `FemaleText_loc1`='좀 비켜주시겠어요? 할 일은 태산인데 시간은 없단 말입니다!$B$B진흙구더기나 부패병에 감염된 분이라면, 제가 도울 수 있을 것 같군요.', `FemaleText_loc4`='事情太多，时间太少，$r！拜托，别挡我的道。$B$B但如果你中了蛆毒或食尸鬼疫病的话，我可以帮助你。', `FemaleText_loc5`='我事情太多，時間根本不夠用，$r!拜託，別擋我路。$B$B萬一你被蛆蟲粘液跟腐爛食屍鬼感染的話，我有能力治療各種疾病。', `FemaleText_loc7`='¡Tengo mucho que hacer y poco tiempo para hacerlo, $r! Por favor, apártate de mi camino.$B$BSi te has contagiado con baba de gusano o la putrefacción de los necrófagos, quizás pueda ayudarte.' WHERE `ID`=12153;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='질병에 걸렸습니다. 치료를 부탁합니다.', `MaleText_loc4`='我的伤口感染了。请治疗我，医生。', `MaleText_loc5`='我生病了。請救救我，醫生。', `MaleText_loc7`='Estoy enfermo. Cúrame, por favor.', `FemaleText_loc1`='질병에 걸렸습니다. 치료를 부탁해요.', `FemaleText_loc4`='我的伤口感染了。请治疗我，医生。', `FemaleText_loc5`='我生病了。請救救我，醫生。', `FemaleText_loc7`='Estoy enferma. Cúrame, por favor.' WHERE `ID`=12154;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 충격을 받더니 다시 깨어납니다!', `MaleText_loc4`='%s被猛烈的电击复活了！', `MaleText_loc5`='%s被喚回陽間!', `MaleText_loc7`='¡%s es devuelto a la vida!' WHERE `ID`=12155;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1과;와; 연결이 끊어집니다!', `MaleText_loc4`='%s的连接中断了。', `MaleText_loc5`='%s失去聯繫!', `MaleText_loc7`='¡%s pierde el vínculo!' WHERE `ID`=12156;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 그대가 그런 꾸지람을 듣지 않아도 되는데... 이리로 오십시오. 절 위해 처리하실 일이 있습니다.', `MaleText_loc4`='不要感到诧异，$n，请过来。我有东西需要你帮我处理下。', `MaleText_loc5`='那可以進展更好的。$n，來這裡，拜託。我有東西要託你為我保管。', `MaleText_loc7`='Podría haber ido mejor. $n, ven aquí, por favor. Necesito que te hagas cargo de algo por mí.' WHERE `ID`=12157;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<입속에 비약을 넣어 주자 빠른 속도로 의식을 회복하는 블러드 엘프>$B$B제 목숨을 구해주셨군요. 그대가 도와주지 않았다면 저는 스컬지의 잔인한 고문에 굴복하고 말았을 것입니다.', `MaleText_loc4`='<在你把药膏倒入血精灵口中后，他很快恢复了知觉。>$B$B谢谢你救了我的命，$c。没有你的帮助，我早就在天灾的折磨下屈服了。', `MaleText_loc5`='<當你將恢復藥劑倒入他嘴裡後血精靈很快恢復意識。>$B$B我欠你一命，$c。沒有你的幫忙，我就得屈服於天譴軍團的痛苦折磨了。', `MaleText_loc7`='<El elfo de sangre recupera rápidamente la conciencia cuando le viertes la pócima en la boca.>$B$BTe debo la vida, $c. Sin tu ayuda habría sucumbido a la dolorosa tortura de la Plaga.' WHERE `ID`=12158;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<복원의 비약을 먹입니다.>', `MaleText_loc4`='<给病人使用疗伤药膏。>', `MaleText_loc5`='<開始操作恢復藥劑>', `MaleText_loc7`='<Administra el jarabe vigorizante.>', `FemaleText_loc1`='<복원의 비약을 먹입니다.>', `FemaleText_loc4`='<给病人使用疗伤药膏。>', `FemaleText_loc5`='<開始操作恢復藥劑>', `FemaleText_loc7`='<Administra la pócima recuperadora.>' WHERE `ID`=12159;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<온몸에 힘이 빠져서 바닥에 누워 있는 블러드 엘프>', `MaleText_loc4`='<血精灵慵懒地躺在桌子上。>', `MaleText_loc5`='<血精靈倒在地上看起來變的很遲緩。>', `MaleText_loc7`='<El elfo de sangre yace en el suelo, sumido en un letargo artificial.>' WHERE `ID`=12160;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$r|1이여;여;, 안녕하십니까. 저는 흔히 블러드 엘프라고 알고 있는 신도레이의 사절 선소로우입니다. 저는 우리와 호드 간에 새롭게 맺은 이 관계가 서로 도움이 되기를 간절히 바랍니다.', `MaleText_loc4`='你好，$R。我是辛多雷——也就是血精灵一族的大使欧诺·炎伤。我忠心希望我们与部落新建立起来的友好关系对双方都有好处。', `MaleText_loc5`='你好，$r。我是辛多雷也是泛稱血精靈的憂日大使。我非常希望我們和部落的新聯結會使雙方互利。', `MaleText_loc7`='Saludos, $r. Soy el embajador Penasol de los sin''dorei, o elfos de sangre, como se nos suele llamar. Tengo grandes esperanzas de que el nuevo vínculo entre nosotros y la Horda nos sea mutuamente beneficioso.' WHERE `ID`=12161;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 가셔도 괜찮아요. 나가는 길은 안전합니다.', `MaleText_loc4`='现在你可以走了。出去的路很安全。', `MaleText_loc5`='你現在可以走了。出去的路很安全。', `MaleText_loc7`='Eres libre de irte. La salida es segura.', `FemaleText_loc1`='지금 가셔도 괜찮아요. 나가는 길은 안전합니다.', `FemaleText_loc4`='现在你可以走了。出去的路很安全。', `FemaleText_loc5`='你現在可以走了。出去的路很安全。', `FemaleText_loc7`='Eres libre de irte. La salida es segura.' WHERE `ID`=12162;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='<혼자 힘으로 일어나는 것은 무리인 듯 얼굴을 온통 찡그린 채 바닥에 누워있는 포세이큰 여인>', `FemaleText_loc4`='<这个女遗忘者痛苦地蜷曲在地上。她看上去已经不能自己爬起来了。>', `FemaleText_loc5`='<女性被遺忘者蜷曲在地上，她的表情相當痛苦。她現在看起來沒辦法自己爬起來。>', `FemaleText_loc7`='<La Renegada está retorcida en el suelo haciendo una mueca. No parece que pueda ponerse de pie por sí sola en este momento.>' WHERE `ID`=12163;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아악... 두통 때문에 미쳐버리겠소.$B$B날 구하라고 그들이 보냈겠지? 왜 이렇게 오래 걸린 거요! 놈들이 포로에게 어떤 짓을 저지르는지 알기나 하시오?', `FemaleText_loc4`='啊啊啊……头痛欲裂！$B$B肯定是他们派你来救我的。拖了太久了！你知道他们都对这里的战俘做了些什么吗？', `FemaleText_loc5`='啊...我的頭快痛死了。$B$B他們一定是派你來救我。他們拖了真夠久的!你知道他們對這裡的犯人都做了些什麼嗎?', `FemaleText_loc7`='Ahhhhggg... este dolor de cabeza me está matando.$B$BTe deben de haber enviado a rescatarme. ¡Ya podrían haberse dado más prisa! ¿Tienes idea de lo que les hacen a los prisioneros aquí?' WHERE `ID`=12164;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고마운 줄도 모르는군? 출구는 안전하니 빨리 빠져나가시오!', `MaleText_loc4`='有点不舒服？出去的路很安全，快点跑吧！', `MaleText_loc5`='我們有點忘恩負義，不是嗎?出去的路很清楚，快逃吧!', `MaleText_loc7`='No eres de los agradecidos, ¿eh? La salida está libre, ¡huye deprisa!', `FemaleText_loc1`='고마운 줄도 모르는군? 출구는 안전하니 빨리 빠져나가시오!', `FemaleText_loc4`='有点不舒服？出去的路很安全，快点跑吧！', `FemaleText_loc5`='我們有點忘恩負義，不是嗎?出去的路很清楚，快逃吧!', `FemaleText_loc7`='No eres de los agradecidos, ¿eh? La salida está libre, ¡huye deprisa!' WHERE `ID`=12165;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<아직 숨은 붙어 있지만 강력한 진정제 성분에 취해 탁자에 누워있는 블러드 엘프>', `MaleText_loc4`='<虚弱的血精灵躺在桌上。>他气若游丝，似乎毒药已经发作了。', `MaleText_loc5`='<血精靈毫無生氣地躺在桌上。雖然他還有呼吸，但他明顯地中了高效的鎮靜毒素。>', `MaleText_loc7`='<El elfo de sangre yace desfallecido en la mesa. Aunque aún respira, parece haber sido víctima de potentes toxinas sedativas.>' WHERE `ID`=12166;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$r|1이여;여;, 만나서 반갑습니다. 저는 여기서 필요할 때마다 고위 집행관님의 조언자 역할을 하고 있답니다. 우리가 힘을 합치면 호드는 이전과는 비교도 할 수 없이 강해져서 스컬지의 위협을 영원히 물리칠 수 있다고 자신합니다!', `MaleText_loc4`='你好，$R。我是代表高级执行官来传达忠告的。我相信只要我们联起手来，部落必将变得更加强大，一举击溃亡灵天灾！', `MaleText_loc5`='你好，$r。我是聽從高階執行官的建議來到這裡。我有信心只要我們團結一致就能打造一個前所未有的強大部落並消滅所有的天譴軍團威脅。', `MaleText_loc7`='Me alegro de conocerte, $r. Estoy aquí para actuar como consejero a las órdenes del Sumo Ejecutor. ¡Sin duda juntos podremos convertir la Horda en algo aún más fuerte que antes y obligar a la amenaza de la Plaga a retroceder de una vez por todas!' WHERE `ID`=12167;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<복원의 비약의 약효가 퍼지자 기침을 심하게 하는 바르니스>$B$B구해 주셔서 감사합니다. 저는 당장 트랜퀼리엔으로 돌아가야겠습니다!', `MaleText_loc4`='<瓦尼斯剧烈地咳嗽起来，看来治疗药膏生效了。>$B$B谢谢你救了我一命。我必须立即返回塔奎林！', `MaleText_loc5`='<當恢復藥劑開始生效瓦尼司激烈地咳嗽。>$B$B謝謝你救了我。我一定要立刻回到安寧地!', `MaleText_loc7`='<Varnis tose con violencia mientras el jarabe vigorizante hace efecto.>$B$BGracias por rescatarme. ¡Debo volver a Tranquillien enseguida!' WHERE `ID`=12168;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영원노래 숲에서 불어 오는 신선한 공기를 마실 때면 종종 뱃속이 뒤집히곤 하지. 무슨 뜻인지 알겠소?', `MaleText_loc4`='从永歌森林时不时吹来的新鲜空气让我的胃感觉很不舒服，如果你知道我是什么意思的话。', `MaleText_loc5`='從永歌森林三不五時吹來的風真讓我作嘔，你懂我的意思吧。', `MaleText_loc7`='Las corrientes de aire fresco que soplan desde Canción Eterna de vez en cuando realmente me afectan al estómago, ¿sabes lo que quiero decir?' WHERE `ID`=12169;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연금술사님, 복원의 비약이 필요합니다.', `MaleText_loc4`='我想要一份你的疗伤药膏的样本，药剂师。', `MaleText_loc5`='我要你的恢復藥劑樣本，藥劑師。', `MaleText_loc7`='Necesito una muestra de su pócima revitalizadora, apotecario.', `FemaleText_loc1`='연금술사님, 복원의 비약이 필요해요.', `FemaleText_loc4`='我想要一份你的疗伤药膏的样本，药剂师。', `FemaleText_loc5`='我要你的恢復藥劑樣本，藥劑師。', `FemaleText_loc7`='Necesito una muestra de su pócima revitalizadora, apotecario.' WHERE `ID`=12170;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='긴히 할 말이 있다면 귀부인 아우리페러스께 알현을 요청하는 것이 더 좋겠군요. 하지만, 매우 바쁘신 분이기 때문에 오래 기다려야 할지도 모릅니다.', `FemaleText_loc4`='如果你有非常重要的事情汇报，最好去找奥莉菲洛丝夫人谈谈。我提醒你，她非常繁忙，恐怕你得等上一会儿。', `FemaleText_loc5`='如果你要和我說的是很重要的事，$c，或許找阿莉法娜奧絲夫人一起來聽會比較妥當。不過我警告你，她很忙碌所以你要等上好一陣子。', `FemaleText_loc7`='Si lo que quieres explicar es un asunto de importancia, $c, tal vez sería más apropiado que pidieras una audiencia con la Dama Aurífera. Sin embargo, debo advertirte que está muy ocupada y tal vez tengas que esperar mucho.' WHERE `ID`=12171;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='보통 제 신분으로는 그대와 직접 대화할 수 없습니다. 그분에게 알현을 요청해야 합니다. 하지만, 제가 직접 일을 맡겼으니... 그래, 의논할 내용이라는 게 뭡니까?', `FemaleText_loc4`='通常来说我是不会和你直接谈话的，你应该直接去找夫人。不管怎样，既然我直接给你下达了命令，那么我们需要讨论的事情是……？', `FemaleText_loc5`='通常我不會允許你直接和我對談;確切的說，你應該請女士也來聽聽。不過，我的確是直接給了你一個任務，那麼我們到底需要談論什麼?', `FemaleText_loc7`='Normalmente yo no debería hablar contigo directamente; lo normal sería que pidieras una audiencia a la señora. Sin embargo, te encargué personalmente una tarea, así que ¿qué querías comentar?' WHERE `ID`=12172;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='귀부인 아우리페러스께서 지난번에 우리 일을 도와줘서 매우 고맙다는 뜻을 그대에 전하라고 하셨습니다. 그리고 그대가 계속해서 이곳 유령의 땅에서 신도레이를 지켜주기를 바라십니다.', `FemaleText_loc4`='$c，奥莉菲洛丝夫人向我转达了她对你的欣赏之情。她想告诉你，她希望你能继续作为一个辛多雷的勇士，在幽魂之地奋战。', `FemaleText_loc5`='$C，阿莉法娜奧絲夫人告訴我她對你在過去為我們做的一切感到很滿意。她希望你能繼續在鬼魂之地這裡做一個辛多雷的戰士。', `FemaleText_loc7`='$C, la Dama Aurífera me ha encargado que te exprese su gran satisfacción con el servicio que nos has prestado. Desea que te comunique que espera que sigas siendo un defensor de los intereses de los sin''dorei aquí en las Tierras Fantasma.' WHERE `ID`=12173;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 퓨진을 돕기 위해 돌진합니다!', `MaleText_loc4`='%s跑去帮助费尔根！', `MaleText_loc5`='%s衝向伏晨去提供援助!', `MaleText_loc7`='¡%s acude en ayuda de Feugen!' WHERE `ID`=12174;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일이 일어나고 있는 겁니까?', `MaleText_loc4`='到底是怎么回事？', `MaleText_loc5`='發生了什麼事?', `MaleText_loc7`='¿Qué está ocurriendo?', `FemaleText_loc1`='무슨 일이 일어나고 있는 건가요?', `FemaleText_loc4`='到底是怎么回事？', `FemaleText_loc5`='發生了什麼事?', `FemaleText_loc7`='¿Qué está ocurriendo?' WHERE `ID`=12176;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 현상 수배 푯말에는 다양한 공고와 보상에 대한 통지가 담겨 있습니다.', `MaleText_loc4`='这张公告牌上列有各种声明和奖赏的通知。', `MaleText_loc5`='這塊告示寫著許多宣佈事項和獎勵辦法。', `MaleText_loc7`='Este panel contiene varios anuncios y noticias sobre recompensas.' WHERE `ID`=12177;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 과부하 상태가 됩니다.', `MaleText_loc4`='%s超载了！', `MaleText_loc5`='%s超過負荷!', `MaleText_loc7`='¡%s se sobrecarga!' WHERE `ID`=12178;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='중요한 일이 있습니다, $n. 적의 경계가 허술할 때 놈들을 공격합시다. 놈들에게 신도레이는 결코 복수를 잊거나 용서하지 않는다는 것을 보여줍시다.', `FemaleText_loc4`='我们有重要的工作要做，$n。让我们在敌人疏于防守的时候进攻他们吧。告诉他们辛多雷永远都不会忘记复仇，永远不会宽恕敌人。', `FemaleText_loc5`='我們有重要的工作要做，$n。讓我們在敵人的守衛失去警戒時攻擊他們。讓他們知道辛多雷的復仇從不會遺忘也不會原諒。', `FemaleText_loc7`='Tenemos trabajo importante que hacer, $n. Ataquemos a nuestros enemigos mientras tengan la guardia baja. Enseñémosles que la venganza de los sin''dorei no olvida ni perdona.' WHERE `ID`=12179;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전쟁의 기운이 또다시 흐르고 있습니다. 차가운 북쪽으로부터 리치 왕이 보낸 죽음의 요새가 우리 땅을 포위해 공격하고 있습니다. 리치 왕은 공중을 나는 죽음의 요새를 보내 세계를 정복하려 합니다.', `MaleText_loc4`='战争之潮再度降临。巫妖王的浮空城正在从北方向我们的陆地一路侵袭而来。他的浮空要塞正在进犯世界各地。', `MaleText_loc5`='戰爭浪潮又再度襲來。巫妖王的亡域軍隊已經從寒冷的北方，包圍了我們的土地。他派出了飛行的亡域入侵全世界。', `MaleText_loc7`='El azote de la guerra regresa de nuevo. Desde el frío norte, las necrópolis del Rey Exánime han asediado nuestras tierras. Él envía a sus necrópolis flotantes a invadir el mundo.' WHERE `ID`=12180;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이거 정말 골치 아픈데요! 쓰레기 같은 놀들이 광산을 점령했는데 어떻게 마법학자께 광석 견본을 모아가죠?', `FemaleText_loc4`='这可真麻烦！如果那些豺狼人垃圾在矿井里到处跑，我该怎么才能帮魔导师收集到矿石样本呢？', `FemaleText_loc5`='這真是麻煩!礦坑充滿了討厭的豺狼人，我要怎麼幫博學者收集礦石樣本?', `FemaleText_loc7`='¡Vaya, eso es un problema! ¿Cómo se supone que debo obtener las muestras de metal para los magistri si las minas están inundadas con esa chusma gnoll?' WHERE `ID`=12181;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='광석을 모아 쿠알레스티스 님에게 가져다주셔서 감사합니다. 저는 돌아가야겠습니다. 제 손으로 직접 구하지 않았다고 혼이 날 것 같거든요.$B$B참, 마법학자께 그런 말은 하지 말아주세요. 약속하시는 겁니다!', `FemaleText_loc4`='感谢你收集了矿石，把它们交给魔导师奎尔林提斯吧，$c。我想我应该回去，但我又害怕因为不能亲自收集矿石而受到惩罚……$B$B不要告诉魔导师，好吗？', `FemaleText_loc5`='謝謝你拿到那個礦石並將它帶給博學者奎壘司提斯，$c。我想我應該回去了，但我很怕接下來的懲罰，因為我沒有自己拿到那個礦石。$B$B不要告訴博學者，好嗎?', `FemaleText_loc7`='Gracias por recoger ese mineral y llevárselo al magister Quallestis, $c. Supongo que debería volver, pero tengo miedo del castigo que podría recibir por no haber recogido el mineral yo misma.$B$BNo se lo digas al magister, ¿de acuerdo?' WHERE `ID`=12182;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도대체 어디로 갔을까요? 서쪽에 있는 미명 광산에 제 수습생 샤샤리아를 보낸 지 한참 됐습니다. 광석 견본을 빨리 받아야 합니다. 그렇지 않으면 우리 실험은 실패하고 말 것입니다!', `MaleText_loc4`='她会在哪里呢？我派了我的学徒沙塔瑞亚到西面的幽光矿洞去，已经有段时间了。我需要拿回那些矿石样本，越快越好，否则我们的实验就要失败了。', `MaleText_loc5`='她會在哪?我滿早以前就派我的學徒，莎夏莉雅去西邊的光底礦坑了。我們需要把那些礦石樣本帶回來，要快，否則我們的實驗就會失敗!', `MaleText_loc7`='¿Dónde podría estar? Envié a mi aprendiz, Shatharia, a las Minas Sondaluz, al oeste, hace algún tiempo. ¡Necesitamos recuperar esas muestras de mena, y rápido, o nuestro experimento fracasará!' WHERE `ID`=12183;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미명 광석이 제때 도착하지 않았다면 우리 연구는 실패했을 것입니다.$B$B샤샤리아가 여기로 돌아올 때까지 기다려 봅시다. 그녀에게 맡길 재미있는 일이 있습니다. 기대해도 좋습니다!', `MaleText_loc4`='如果你没有及时把那些幽光矿石送回来的话，我们的研究可能已经失败了。$B$B现在就等沙塔瑞亚再次出现了。我有一些有趣的任务要交给她，我想你肯定也会有兴趣。', `MaleText_loc5`='如果沒有那個光底礦石，這樣的情況下，我們的研究一定會失敗。$B$B等莎夏莉雅回來這裡再說吧。我有一些有趣的任務要交給她，你可以相信我!', `MaleText_loc7`='Sin la entrega de la mena de Sondaluz de una forma tan oportuna, nuestra investigación habría fracasado.$B$BEspera a que Shatharia vuelva a asomar la cabeza por aquí. ¡Tengo unas cuantas tareas interesantes para ella, puedes estar $gseguro:segura;!' WHERE `ID`=12184;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지난날 신도레이는 너무나 많은 것을 잃었습니다. 우리의 땅, 고향, 심지어 정체성까지도...$B$B이제 우리가 잃은 그 모든 것을 되찾을 시간이 됐습니다.', `FemaleText_loc4`='辛多雷在过去的日子里失去了太多。我们的领土，我们的家园，甚至我们的自我……$B$B是时候把一切都夺回来了。', `FemaleText_loc5`='辛多雷在過去幾年已失去太多。我們的土地，我們的家園，甚至我們自己...$b$b是時候開始把一切奪回來了。', `FemaleText_loc7`='Los sin''dorei hemos perdido demasiado a lo largo de los últimos años. Nuestras tierras, nuestras casas, hasta nuestras identidades... $B$BYa va siendo hora de que empecemos a recuperarlo.' WHERE `ID`=12185;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스컬지와 아마니 트롤 같은 외부의 문제를 극복하려면 먼저 내부의 문제부터 해결해야 하오. 버림받은 자들 때문에 아주 오랫동안 골머리를 앓고 있었지. 이제 놈들을 정리할 때요.', `MaleText_loc4`='要打败亡灵天灾和阿曼尼巨魔这样的外敌，首先必须解决我们内部的纷争。长期以来，失心者都在不断骚扰滋事，现在是消灭他们的时候了。', `MaleText_loc5`='在我們戰勝像天譴軍團和阿曼尼這些外患之前，一定要先克服內憂。鄙惡者已經惹人厭夠久了，是時候消滅他們了。', `MaleText_loc7`='Antes de que podamos superar obstáculos externos, como la Plaga y los trols Amani, debemos superar obstáculos internos. Los desdichados han sido una molestia durante el tiempo suficiente; es hora de derrotarlos.' WHERE `ID`=12186;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n, 오른쪽에 있는 방으로 갑시다.', `FemaleText_loc4`='$n，我们从右边的前厅走。', `FemaleText_loc5`='$n，讓我們使用右邊的接待室。', `FemaleText_loc7`='$n, usemos la antecámara de la derecha.' WHERE `ID`=12187;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='동굴 끝에 빛이 보입니다!', `FemaleText_loc4`='我能看到通道那头的亮光了！', `FemaleText_loc5`='我可以看見隧道底端的光線!', `FemaleText_loc7`='¡Veo luz al final del túnel!' WHERE `ID`=12188;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 곧 원정순찰대 초소입니다. 얼마 안 남았습니다... 조심하세요! 트롤의 기습입니다!', `FemaleText_loc4`='那里就是远行者营地了，$c。就在前面……小心！有埋伏！', `FemaleText_loc5`='前面有旅行者營地，$c。就在不遠處...看啊!食人妖埋伏!!', `FemaleText_loc7`='Ahora viene el Enclave del Errante, $c. No está muy lejos... ¡Cuidado! ¡Emboscada troll!' WHERE `ID`=12189;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='헬리오스 순찰대장님, 방금 아마니 지하묘지에서 구출되었음을 보고합니다!', `FemaleText_loc4`='赫里奥斯中尉，我从阿曼尼墓穴逃出来了。报告，长官！', `FemaleText_loc5`='希里歐斯隊長，我是從阿曼尼地下墓穴被救出來的。報告完畢，長官!', `FemaleText_loc7`='Capitán Helios, he sido rescatada de las Catacumbas Amani. ¡A sus órdenes, señor!' WHERE `ID`=12190;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n, 목숨을 구해 주시고 무사히 귀환시켜 주셔서 감사합니다!', `FemaleText_loc4`='感谢你救了我的命，并把我带回安全的地方，$n！', `FemaleText_loc5`='謝謝你救了我一命並把我帶回安全地帶，$n!', `FemaleText_loc7`='¡Gracias por salvarme y traerme a un lugar seguro, $n!' WHERE `ID`=12191;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안심한 표정의 %s|1이;가; 순찰자 릴라사와 그녀를 호위해준 이에게 고개를 끄덕입니다.', `MaleText_loc4`='%s松了口气，朝游侠莉拉恩萨和她的护卫队点了点头。', `MaleText_loc5`='%s欣慰地向遊俠莉娜薩和她的手下點點頭。', `MaleText_loc7`='%s asiente aliviado a la forestal Lilatha y su escolta.' WHERE `ID`=12192;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='릴라사는 가서 상처를 돌보도록. 무사히 데려다 줘서 정말 고맙네.', `MaleText_loc4`='莉拉恩萨，找个人来看看这些伤口。谢谢你把她安全地带了回来。', `MaleText_loc5`='莉娜薩，找個人看看那些傷勢。謝謝你將她安全帶回來。', `MaleText_loc7`='Lilatha, busca a alguien que pueda examinar esas heridas. Gracias por devolverla sana y salva.' WHERE `ID`=12193;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기서 절 데리고 나가실 수 있겠어요?', `FemaleText_loc4`='你觉得你能帮我离开这里吗？', `FemaleText_loc5`='你可以幫我離開這裡嗎?', `FemaleText_loc7`='¿Crees que podrías ayudarme a salir de aquí?' WHERE `ID`=12194;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 죽습니다.', `MaleText_loc4`='%s死了。', `MaleText_loc5`='%s死了。', `MaleText_loc7`='%s muere.' WHERE `ID`=12195;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원정순찰대의 다양한 확인 목록과 정보가 포함된 여러 양피지 중에서 단연 눈에 띄는 그림이 있습니다. 바로 소름 끼치는 트롤, 아마 여태까지 당신이 본 것 중 가장 끔찍한 생물의 모습입니다!', `MaleText_loc4`='在各种由羊皮纸拼凑起来的名单和其它信息之中，有一条特别醒目。这是一个丑恶的巨魔的画像，也许是你曾经看到过的最可怕的生物！', `MaleText_loc5`='在那幾張羊皮紙裡有核對清單和其他遠行者的資料，其中有一張特別搶眼。那是一張醜陋的食人妖素描，可能是你見過最可怕的生物!', `MaleText_loc7`='Entre los diversos fragmentos de pergamino que contienen listas de verificación y otra información de los Errantes, destaca uno. ¡Es el dibujo de un trol horripilante, quizás la criatura más espantosa que hayas visto!' WHERE `ID`=12196;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 이런! 그러면 안 되지! 지금부터 시작이다!', `MaleText_loc4`='OH NO YOU DIDN''! ITS ON NOW! <PH>', `MaleText_loc5`='喔不!你不能死!現在才剛開始! <PH>', `MaleText_loc7`='OH NO YOU DIDN''! ITS ON NOW! <PH>' WHERE `ID`=12197;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='현재 여명의 설원이 공격받고 있습니까?', `MaleText_loc4`='冬泉谷现在遭到袭击了吗？', `MaleText_loc5`='冬泉谷最近有遭到攻擊嗎?', `MaleText_loc7`='¿Está siendo atacada Cuna del Invierno?', `FemaleText_loc1`='현재 여명의 설원이 공격받고 있나요?', `FemaleText_loc4`='冬泉谷现在遭到袭击了吗？', `FemaleText_loc5`='冬泉谷最近有遭到攻擊嗎?', `FemaleText_loc7`='¿Está siendo atacada Cuna del Invierno?' WHERE `ID`=12198;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇습니다. 여명의 설원의 언덕에서는 새롭게 시작된 스컬지의 침공을 방어하고 있습니다. 당신이 도와준다면 그들에게 큰 힘이 될 겁니다.$B$B남아 있는 죽음의 요새: $2284W개', `MaleText_loc4`='事实上，冬泉谷北部的丘陵地区正在遭到新一批天灾军团士兵的攻击。你的援手将给予我们很大的帮助。$B$B剩余浮空要塞数量：$2284W', `MaleText_loc5`='的確，冬泉谷山丘一帶正嘗試要抵擋重生的天譴軍團攻擊。你的幫忙對他們來說很重要。$B$B剩餘的亡域:$2284W', `MaleText_loc7`='En efecto, las colinas de Cuna del Invierno están intentando resistir un nuevo ataque de la Plaga. Tu ayuda resultará crucial.$B$BNúmero de necrópolis restantes: $2284W' WHERE `ID`=12199;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금은 그 지역에 스컬지의 더러운 손이 닿지 않았습니다. 하지만, 스컬지가 돌아오는 것도 시간문제이니 걱정이 아닐 수 없군요.', `MaleText_loc4`='目前，这片土地还没有受到天灾军团的影响。我担心他们杀回来只是个时间问题。', `MaleText_loc5`='這地方目前暫時脫離天譴軍團的威脅了。我擔心他們很快又要回來了。', `MaleText_loc7`='Hasta el momento, esta área está libre de la influencia de la Plaga. Me temo que será cuestión de tiempo que regresen.' WHERE `ID`=12200;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='현재 타나리스가 공격받고 있습니까?', `MaleText_loc4`='塔纳利斯现在遭到袭击了吗？', `MaleText_loc5`='塔納利斯最近有遭到攻擊嗎?', `MaleText_loc7`='¿Está siendo atacado Tanaris?', `FemaleText_loc1`='현재 타나리스가 공격받고 있나요?', `FemaleText_loc4`='塔纳利斯现在遭到袭击了吗？', `FemaleText_loc5`='塔納利斯最近有遭到攻擊嗎?', `FemaleText_loc7`='¿Está siendo atacado Tanaris?' WHERE `ID`=12201;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스컬지 군대가 타나리스에 도착한 것 같습니다. 엄청난 수의 죽음의 요새와 군대가 그곳에 파병됐습니다.$B$B남아 있는 죽음의 요새: $2283W개', `MaleText_loc4`='似乎天灾军团的士兵正在进攻塔纳利斯。大量浮空城和其他部队还在陆续正向这里涌来。$B$B剩余浮空要塞数量：$2283W', `MaleText_loc5`='天譴軍團好像到了塔納利斯。他們眾多的亡域和其他軍隊都在那裡被殺了。$B$B剩餘的亡域:$2283W', `MaleText_loc7`='Parece que el ejército de la Plaga ha llegado a Tanaris. Han enviado un número considerable de necrópolis y otras fuerzas a la zona.$B$BNúmero de necrópolis restantes: $2283W' WHERE `ID`=12202;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='현재 저주받은 땅이 공격받고 있습니까?', `MaleText_loc4`='诅咒之地现在遭到袭击了吗？', `MaleText_loc5`='詛咒之地最近有遭到攻擊嗎?', `MaleText_loc7`='¿Están siendo atacadas Las Tierras Devastadas?', `FemaleText_loc1`='현재 저주받은 땅이 공격받고 있나요?', `FemaleText_loc4`='诅咒之地现在遭到袭击了吗？', `FemaleText_loc5`='詛咒之地最近有遭到攻擊嗎?', `FemaleText_loc7`='¿Están siendo atacadas Las Tierras Devastadas?' WHERE `ID`=12203;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저주받은 땅에 스컬지의 수가 점점 늘어나고 있습니다. 신체 건강한 자들은 모두 나아가 그들의 침략에 맞서야 합니다.$B$B남아 있는 죽음의 요새: $2280W개', `MaleText_loc4`='天灾军团的势力已经蔓延到了诅咒之地。所有的士兵都要集结起来，击退他们的进攻之潮。$B$B剩余浮空要塞数量：$2280W', `MaleText_loc5`='天譴軍團的入侵在詛咒之地日益加大。每個健全的戰士都要挺身而出阻擋他們的入侵。$B$B剩餘的亡域:$2280W', `MaleText_loc7`='La presencia de la Plaga va en aumento en Las Tierras Devastadas. Es necesario que todos aquellos guerreros que estén sanos ayuden a frenar su invasión.$B$BNúmero de necrópolis restantes: $2280W' WHERE `ID`=12204;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='현재 불타는 평원이 공격받고 있습니까?', `MaleText_loc4`='燃烧平原现在遭到袭击了吗？', `MaleText_loc5`='燃燒平原最近有遭到攻擊嗎?', `MaleText_loc7`='¿Están siendo atacadas Las Estepas Ardientes?', `FemaleText_loc1`='현재 불타는 평원이 공격받고 있나요?', `FemaleText_loc4`='燃烧平原现在遭到袭击了吗？', `FemaleText_loc5`='燃燒平原最近有遭到攻擊嗎?', `FemaleText_loc7`='¿Están siendo atacadas Las Estepas Ardientes?' WHERE `ID`=12205;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불타는 평원에 추가 지원군이 도착하지 않는다면 스컬지가 그곳에 작전 기지를 세우게 될 겁니다. 가능하다면 당신이 그곳으로 가서 수비를 도와주셨으면 합니다.$B$B남아 있는 죽음의 요새: $2281W개', `MaleText_loc4`='如果增援部队没法快些赶到燃烧平原的话，我怕天灾军团会在这里建立一个行动基地。要是可以的话，你应该去那里帮助防御。$B$B剩余浮空要塞数量：$2281W', `MaleText_loc5`='如果援軍不能及時趕到燃燒平原，我怕天譴軍團會在那裡建立指揮基地。如果你可以，就應該趕快到那邊協助防衛部隊。$B$B剩餘的亡域:$2281W', `MaleText_loc7`='Si no se envía pronto más apoyo a las Estepas Ardientes, me temo que la Plaga establecerá una base de operaciones aquí. Si puedes, deberías ir allí para ayudar a los defensores.$B$BNúmero de necrópolis restantes: $2281W' WHERE `ID`=12206;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 뭘 하면 됩니까?', `MaleText_loc4`='我能帮上些什么忙？', `MaleText_loc5`='我能做什麼?', `MaleText_loc7`='¿Qué puedo hacer?', `FemaleText_loc1`='전 뭘 하면 되나요?', `FemaleText_loc4`='我能帮上些什么忙？', `FemaleText_loc5`='我能做什麼?', `FemaleText_loc7`='¿Qué puedo hacer?' WHERE `ID`=12207;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='적을 제대로 알면 유리한 점이 아주 많습니다. 이 가르침을 명심하십시오, $n.$B$B스컬지에 대해 많이 연구할수록 녀석들을 한결 수월하게 물리칠 수 있습니다.', `FemaleText_loc4`='了解你的敌人可以给你带来更多的优势。请牢记在心，$n。$B$B更多地了解天灾可以让我们有更好的准备，这样才能打败他们。', `FemaleText_loc5`='瞭解我們的敵人能有許多好處。把這件事情牢記在心，$n。$B$B我們對天譴軍團瞭解得越多，我們越能夠擊敗他們。', `FemaleText_loc7`='Se pueden obtener muchas ventajas conociendo al enemigo. Apréndete esa lección, $n.$B$BCuanto más sepamos sobre la Plaga, más bien preparados estaremos para derrotarlos.' WHERE `ID`=12208;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스컬지는 하늘을 떠다니는 죽음의 요새로부터 신속한 연락과 각종 지원을 받으면서 공격 지역에 소규모의 집결지를 건설하고 있습니다. 단언컨대, 요새 아래 모인 지상 병력을 해치우면 스컬지를 몰아낼 수 있을 것입니다.', `MaleText_loc4`='天灾军团在这边建立起了一处据点，用于与天上的浮空城联络并接受支援。根据我们所知的情报，唯一根除的他们的办法就只有杀死据点附近的所有地面部队。', `MaleText_loc5`='天譴軍團正在攻擊地區設置火力點，接收橫跨天際的亡域的通訊協助，和其他方面的軍援，我們知道，將他們根除的方法就是殺掉所有地面基地的軍力。', `MaleText_loc7`='La Plaga está estableciendo pequeños puntos de escala en los lugares que ataca, en los que reciben informaciones y otro tipo de ayudas por parte de las necrópolis que los sobrevuelan. Por lo que sabemos, el único modo de erradicarlos es acabando con los ejércitos de tierra que rodean esos puntos.' WHERE `ID`=12209;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='원정순찰대 초소에 얼마든지 머물러도 좋습니다. 유령의 땅에서 우리 일을 도와주실 분이라면 누구든지 환영합니다.', `FemaleText_loc4`='只要你喜欢，你在远行者营地待多久都可以，$c。我们欢迎任何愿意尽全力在幽暗之地帮助我们的人。', `FemaleText_loc5`='歡迎在旅行者營地停留，你想待多久都可以，$c。我們歡迎任何幫助我們在鬼魂之地努力的人。', `FemaleText_loc7`='$gBienvenido:Bienvenida; al Enclave del Errante, $c. Quédate todo el tiempo que quieras. Son bienvenidos todos los que nos apoyan en las Tierras Fantasma.' WHERE `ID`=12210;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비전 마력을 잃으면 대지, 원소, 심지어는 죽음의 망령에까지 이상한 일이 벌어질 수 있답니다.', `MaleText_loc4`='堕落的奥术能量可以对大地、元素甚至是死者的灵魂都产生奇怪的影响。', `MaleText_loc5`='流散的秘法力量會對大地，元素，甚至亡者的靈魂做出奇怪的事情。', `MaleText_loc7`='Las fuerzas Arcanas perdidas pueden hacer cosas raras a la tierra, a los elementos e incluso a los espíritus de los muertos.' WHERE `ID`=12211;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고위집행관께서는 매우 바쁜 분이오. 무슨 일로 왔는지는 몰라도 내가 도울 수 있을 거요.', `MaleText_loc4`='高级执行官公务繁忙，$C。或者我能帮得上你的忙？', `MaleText_loc5`='高階執行官是個很忙的人，$c。有什麼事我可以幫你嗎?', `MaleText_loc7`='El Sumo Ejecutor es un hombre muy ocupado, $c. Tal vez yo pueda ayudarte con lo que necesites.' WHERE `ID`=12212;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 큰일을 하셨소. 미명 광산의 놀들과 아마니 지하묘지의 미라가 된 트롤들을 해치울 때 당신 정말 대단했소!$B$B$G잘했소!:언제 같이 술이나 한 잔 하는 것이 어떻겠소?;', `MaleText_loc4`='你为我们做的一切都堪称是榜样，$n。在解决了幽光矿洞的豺狼人和阿曼尼墓穴的那些木乃伊巨魔后，你已经对我们的敌人进行了强有力的打击。$B$B$G干得好！:我们应该找个时间一起喝上几杯，你觉得呢？;', `MaleText_loc5`='你是我們的楷模，$n。在對付光底礦坑的豺狼人和阿曼尼地下墓穴的屍化食人妖之後，你對我們的敵人擊出了致命的一擊!$B$B$G做得好!:我們應該找個時間好好喝一杯，你覺得怎麼樣?;', `MaleText_loc7`='Nos has prestado un magnífico servicio, $n. Entre ocuparte de los gnolls de las Minas Sondaluz y los trols momificados de las Catacumbas Amani, ¡has asestado un gran golpe a nuestros enemigos!$B$B$G ¡Buen trabajo! : Deberíamos quedar para tomar algo algún día, ¿qué me dices?;' WHERE `ID`=12213;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$g친구여:어여쁜 분이여;, 다시 만나서 반갑소! 우리 한번 잘 해봅시다. $g나중에 봅시다:앞으로도 같이 일했으면 좋겠소;.', `MaleText_loc4`='很高兴再次看到你，和你在一起工作很开心。', `MaleText_loc5`='很高興再見到你，$g老兄!:美女!;我們合作愉快;$g下回再見。:我希望我們還有機會合作。;', `MaleText_loc7`='¡Me alegro de volver a verte, $gquerido:querida;! Formamos un buen equipo. Ya nos veremos.' WHERE `ID`=12214;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='목걸이를 되찾은 여군주 실바나스가 자네에게 어떤 반응을 보였는지는 정보통을 통해 이미 들었네. 아직도 난 자네가 옳은 일을 했다고 믿고 있으니까 그녀의 반응에 너무 신경 쓰지는 말게.$B$B이제 용건을 말해 보게나.', `MaleText_loc4`='人们对你将项链归还给希尔瓦娜斯女王一事议论纷纷。我坚持认为你做了件好事，不要担心女王会对此做何反应。$B$B去做你自己的事好了。', `MaleText_loc5`='我聽說了希瓦娜斯女王知道你找回她項鍊後的反應。我仍然認為你做了對的事;別擔心希瓦娜斯的反應。$B$B那麼，說說你今天來此的目的吧。', `MaleText_loc7`='He sabido de la reacción de Lady Sylvanas acerca de que recuperaras su collar. Sigo pensando que hiciste lo correcto; no te preocupes demasiado sobre su reacción.$B$BY ahora dime a qué has venido.' WHERE `ID`=12215;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 말을 해야 할지 모르겠군. 그대야말로 진정한 영웅일세. 우리 순찰자들을 구했을 뿐만 아니라 그림자소나무 트롤들에게 결정타를 날렸으니까. 여기 원정순찰대에 들어올 생각 정말 없나?$B$B그럼 몸조심 하게나, $n!', `MaleText_loc4`='我能说什么，$C？你是个真正的英雄！你不仅挽救了很多游侠的性命，还狠狠地打击了暗松巨魔的嚣张气焰。你确定你不想留下来，在我手下做一名远行者？$B$B再见，$n。', `MaleText_loc5`='我能說什麼，$c?你是個真正的$g英雄:女英雄;!你不僅個人救了我許多的遊俠，還幫助我們對影松食人妖擊出致命一擊。你確定你不要留下來成為我手下的遠行者之一嗎?$B$B再見了，$n。', `MaleText_loc7`='¿Qué puedo decir, $c? ¡Eres $gun auténtico héroe:una auténtica heroína:c;! No solo has salvado personalmente a muchos de mis forestales, sino que has asestado un golpe decisivo contra los trols Sombrapino. ¿Seguro que no quieres quedarte y ser uno de mis Errantes?$B$BAdiós, $n.' WHERE `ID`=12216;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대는 정말로 구출의 대가로군. 벌써 우리 원정순찰대 중 세 명을 구해내지 않았나!', `MaleText_loc4`='你真是一个救人机器。你现在已经救了我手下的三个远行者了。', `MaleText_loc5`='太棒了!你是個$g男人:女人;的救星。你已經救了我手下的三名遠行者!', `MaleText_loc7`='Eres$gun hombre:una mujer; máquina de rescate. ¡Has salvado ya a tres de mis Errantes!' WHERE `ID`=12217;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그림자소나무 트롤에 관련된 일을 도와줘서 정말 큰 도움이 되고 있네. 계속해서 이 일을 지원해준다면 스컬지를 상대하는 데 전력을 집중할 수 있을 걸세.', `MaleText_loc4`='你给予了暗松巨魔巨大的打击，$C。请继续保持，这样我们或许就能抽出时间来对付亡灵天灾。', `MaleText_loc5`='你對我們對抗影松食人妖的幫助可說是無法比擬，$c。繼續保持我們或許就能將注意力轉回來對付天譴軍團。', `MaleText_loc7`='Tu ayuda con los trols Sombrapino está siendo indispensable, $c. Sigue así y tal vez podamos volver a ocuparnos de la Plaga.' WHERE `ID`=12218;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 자네는 그림자소나무 트롤들에게 치명타를 날렸네. 줄아만에서 놈들을 지원하기 전에 병력을 좀 더 모아서 끝장을 보고 싶어.$B$B트랜퀼리엔에서 도와준다면 정말 좋겠는데...', `MaleText_loc4`='你对暗松巨魔们造成了决定性的打击，$n。我只希望我们可以尽快聚集力量，在他们得到祖阿曼的增援前解决掉他们。$B$B要是塔奎林能帮助我们就更好了。', `MaleText_loc5`='你給了影松食人妖重重一擊，$n。我只希望我們可以在他們從祖阿曼獲得援軍前召集我的軍隊鏟除他們。$B$B如果安寧地願意給我們支援會非常好。', `MaleText_loc7`='Has asestado el golpe decisivo contra los trols Sombrapino, $n. Solo espero que podamos reunir nuestras fuerzas lo suficientemente rápido como para rematarlos antes de que reciban refuerzos de Zul''Aman.$B$BEstaría bien que Tranquillien nos proporcionara refuerzos.' WHERE `ID`=12219;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고맙소. 은빛소나무 숲을 벗어나지 말았어야 했는데...', `FemaleText_loc4`='谢谢你，我永远都不会再离开银松森林了。', `FemaleText_loc5`='謝謝，我真的不應該離開銀松森林的。', `FemaleText_loc7`='Gracias. Nunca debí abandonar el Bosque de Argénteos.' WHERE `ID`=12220;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 감사합니다!', `MaleText_loc4`='谢谢你！', `MaleText_loc5`='非常感謝你!', `MaleText_loc7`='¡Te lo agradezco!' WHERE `ID`=12221;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고... 고맙습니다. 그냥 죽는 줄로만 알았답니다.', `MaleText_loc4`='谢……谢谢你。我原以为我会死的。', `MaleText_loc5`='謝...謝謝你。我以為我就要死了。', `MaleText_loc7`='Gr... gracias. Pensé que iba a morir.' WHERE `ID`=12222;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무례함의 대가로 네 목숨을 받겠노라!', `MaleText_loc4`='死亡就是你为这种傲慢付出的代价！', `MaleText_loc5`='死亡是你為這次的無禮應付的代價!', `MaleText_loc7`='¡El precio que pagarás por tu insolencia es la muerte!' WHERE `ID`=12223;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어리석은 존재여! 데솔름의 구울들이 쓰러진 네 몸 위에서 진수성찬을 차릴 것이다.', `MaleText_loc4`='愚蠢的凡人！戴索姆的食尸鬼们会吞噬你们的躯体！', `MaleText_loc5`='凡人蠢蛋!死亡之域的食屍鬼會把你們的遺體當做大餐享用!', `MaleText_loc7`='¡Estúpidos mortales! ¡Los necrófagos de la Ciudad de la Muerte se darán un buen festín con sus restos!' WHERE `ID`=12224;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 천천히, 그리고 고통스럽게 죽여주마!', `MaleText_loc4`='你会痛苦而缓慢地死去！', `MaleText_loc5`='你的死要既緩慢又痛苦!', `MaleText_loc7`='¡Su muerte será lenta y dolorosa!' WHERE `ID`=12225;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미란다, 다른 등급의 평판을 가진 모험가에게는 휘장을 몇 개나 받고 물건을 주는지 좀 알려주세요.', `MaleText_loc4`='米兰达，你能告诉我，在其它声望级别的情况下，你所提供的物品需要多少徽记吗？', `MaleText_loc5`='米蘭達，能不能請你告訴我，其他聲望階級的冒險者需要付出多少徽記才能夠獲得妳所提供的物品?', `MaleText_loc7`='Miranda, ¿podrías decirme cuántas insignias necesitan los aventureros con otros niveles de reputación para adquirir los objetos que ofreces?', `FemaleText_loc1`='미란다, 다른 등급의 평판을 가진 모험가에게는 휘장을 몇 개나 받고 물건을 주는지 좀 알려주세요.', `FemaleText_loc4`='米兰达，你能告诉我，在其它声望级别的情况下，你所提供的物品需要多少徽记吗？', `FemaleText_loc5`='米蘭達，能不能請你告訴我，其他聲望階級的冒險者需要付出多少徽記才能夠獲得妳所提供的物品?', `FemaleText_loc7`='Miranda, ¿podrías decirme cuántas insignias necesitan los aventureros con otros niveles de reputación para adquirir los objetos que ofreces?' WHERE `ID`=12226;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n, 어떤 평판에 대해서 궁금한지 말씀만 하세요.', `FemaleText_loc4`='当然，$n。你只需要先告诉我你想知道关于哪个声望等级的信息。', `FemaleText_loc5`='當然可以，$n。你只要跟我說你想知道的是哪種聲望。', `FemaleText_loc7`='Por supuesto, $n. Tan solo has de decirme qué nivel de reputación te interesa.' WHERE `ID`=12227;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미란다, 우호적 평판을 얻은 모험가에게는 휘장을 몇 개나 받고 물건을 제공하는지 좀 알려주실래요?', `MaleText_loc4`='米兰达，你能告诉我，在尊敬声望级别的情况下，你所提供的物品需要多少徽记吗？', `MaleText_loc5`='米蘭達，能不能請你告訴我，聲望值到達尊敬的冒險者需要付出多少徽記才能夠獲得妳所提供的物品?', `MaleText_loc7`='Miranda, ¿podrías decirme cuántas insignias necesitan los aventureros honorables para adquirir los objetos que ofreces?', `FemaleText_loc1`='미란다, 우호적 평판을 얻은 모험가에게는 휘장을 몇 개나 받고 물건을 제공하는지 좀 알려주실래요?', `FemaleText_loc4`='米兰达，你能告诉我，在尊敬声望级别的情况下，你所提供的物品需要多少徽记吗？', `FemaleText_loc5`='米蘭達，能不能請你告訴我，聲望值到達尊敬的冒險者需要付出多少徽記才能夠獲得妳所提供的物品?', `FemaleText_loc7`='Miranda, ¿podrías decirme cuántas insignias necesitan los aventureros honorables para adquirir los objetos que ofreces?' WHERE `ID`=12228;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당연히 알려드려야죠, $n!$B$B은빛 여명회로부터 우호적 평판을 얻은 모험가들은 모두 합쳐서 40개의 휘장을 내면 최고급 장비를 얻을 수 있답니다. 더 강력한 물건을 얻으려면 모두 150개의 휘장을 내야 하지요.$B$B뭐, 우호적인 평판을 얻었는데도 물건 가격이 비싸다는 점은 저도 인정합니다.', `FemaleText_loc4`='当然，$n。$B$B在银色黎明组织中拥有尊敬级别声望的冒险者需要上缴40个徽记以获得优秀品质的物品。若想获得更加强大的物品，他们需要上缴150个徽记。$B$B我承认，这个价格即便是对尊敬级别的冒险者来说，也确实有些高了。', `FemaleText_loc5`='當然可以，$n。$B$B黎明陣營裡屬於尊敬聲望的冒險者必須交出40個徽記才能購買精良級的物品。如果想購買更加強大的史詩級物品，他們就必須交出 150個徽記。$B$B我必須承認這些代價對在黎明中屬於尊敬聲望的來說仍然很高。', `FemaleText_loc7`='Por supuesto, $n.$B$BLos aventureros que el Alba cataloga de honorables deben entregar un total de 40 insignias para acceder a objetos excelentes. Para tener acceso a objetos de un poder mayor, tendrán que entregar un total de 150 insignias.$B$BDebo admitir que el precio es alto incluso para aquellos que el Alba considera honorables.' WHERE `ID`=12229;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반드릴, 포세이큰이 여기에 왜 있나요?', `MaleText_loc4`='奥术师范迪瑞尔，被遗忘者在这儿做什么？', `MaleText_loc5`='秘法師范德隆，被遺忘者在這裡做什麼?', `MaleText_loc7`='Arcanista Vandril, ¿qué hacen aquí los Renegados?', `FemaleText_loc1`='반드릴, 포세이큰이 여기에 왜 있죠?', `FemaleText_loc4`='奥术师范迪瑞尔，被遗忘者在这儿做什么？', `FemaleText_loc5`='秘法師范德隆，被遺忘者在這裡做什麼?', `FemaleText_loc7`='Arcanista Vandril, ¿qué hacen aquí los Renegados?' WHERE `ID`=12230;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미란다, 매우 우호적 평판을 얻은 모험가에게는 휘장을 몇 개나 받고 물건을 제공하는지 좀 알려주실래요?', `MaleText_loc4`='米兰达，你能告诉我，在崇敬声望级别的情况下，你所提供的物品需要多少徽记吗？', `MaleText_loc5`='米蘭達，能不能請你告訴我，聲望值到達崇敬的冒險者需要付出多少徽記才能夠獲得妳所提供的物品?', `MaleText_loc7`='Miranda, ¿podrías decirme cuántas insignias necesitan los aventureros venerados para adquirir los objetos que ofreces?', `FemaleText_loc1`='미란다, 매우 우호적 평판을 얻은 모험가에게는 휘장을 몇 개나 받고 물건을 제공하는지 좀 알려주실래요?', `FemaleText_loc4`='米兰达，你能告诉我，在崇敬声望级别的情况下，你所提供的物品需要多少徽记吗？', `FemaleText_loc5`='米蘭達，能不能請你告訴我，聲望值到達崇敬的冒險者需要付出多少徽記才能夠獲得妳所提供的物品?', `FemaleText_loc7`='Miranda, ¿podrías decirme cuántas insignias necesitan los aventureros venerados para adquirir los objetos que ofreces?' WHERE `ID`=12231;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그럼요, $n!$B$B은빛 여명회로부터 매우 우호적 평판을 얻은 모험가들은 모두 14개의 휘장을 내면 최고급 장비를 얻을 수 있답니다. 더 강력한 물건을 얻으려면 모두 90개의 휘장을 내야 해요.$B$B은빛 여명회로부터 매우 우호적 평판을 얻은 분에게는 합리적인 가격에 최고급 장비를 드리고 있는 것이죠! 좀 더 강력한 물건은 여전히 비싸지만요.', `FemaleText_loc4`='当然，$n。$B$B在银色黎明组织中拥有崇敬级别声望的冒险者需要上缴14个徽记以获得优秀品质的物品。若想获得更加强大的物品，他们需要上缴90个徽记。$B$B这个价格对崇敬级别的冒险者来说，可是说是完全合理的！但最强大的物品仍然是高价的。', `FemaleText_loc5`='當然可以，$n。$B$B黎明陣營裡屬於崇敬聲望的冒險者必須交出14個徽記才能購買精良級的物品。如果想購買更加強大的史詩級物品，他們就必須交出90個徽記。$B$B黎明的崇敬聲望者想獲得精良級的物品，這個代價是非常合理的!但史詩等級的物品仍需付出不少代價。', `FemaleText_loc7`='Por supuesto, $n.$B$BLos aventureros que el Alba cataloga de venerados deben entregar un total de 14 insignias para acceder a objetos excelentes. Para tener acceso a objetos de un poder mayor, tendrán que entregar un total de 90 insignias.$B$BAquellos que el Alba considere venerados encontrarán este precio bastante razonable.
 El precio de los objetos todavía más poderosos es aún mayor.' WHERE `ID`=12232;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생각보다 상황이 훨씬 좋지 않습니다. 우리 동맹인 포세이큰은 공동의 적 스컬지와 싸우려고 이곳에 왔습니다.$B$B제 말을 믿으셔야 합니다. 포세이큰이 없었다면 유령의 땅은 벌써 사라졌을 것이며 스컬지는 지금쯤 영원노래 숲 전역을 한바탕 휩쓸고 있을 것입니다!$B$B영광스러웠던 과거에 우리 영토였던 땅을 되찾으려면 무엇보다도 그대의 도움이 필요합니다.', `MaleText_loc4`='情况比人们想象的要严峻得多。被遗忘者来这里是为了与我们组成同盟，共同对抗亡灵天灾。$B$B相信我，没有他们的帮助，我们将失去幽魂之地，而整个永歌森林也将被亡灵天灾侵占！$B$B但是我们仍然需要你伸出援手，帮我们夺回土地！', `MaleText_loc5`='情況比許多人所想的還要嚴重。被遺忘者是我們在這裡的盟友，幫助我們對抗共同的敵人，天譴軍團。$B$B當我這樣說的時候請相信我，沒有他們的話就不會有鬼魂之地，而且天譴軍團也會早已進入永歌森林!$B$B但更重要的是，我們需要你的幫助來重拾我們曾經驕傲的土地!', `MaleText_loc7`='La situación es más desalentadora de lo que se ha hecho creer a muchos. Los Renegados están aquí como aliados en la lucha contra nuestro enemigo común, la Plaga.$B$B¡Confía en mí cuando digo que sin ellos, las Tierras Fantasma estarían perdidas y la Plaga ya habría invadido todo el Bosque Canción Eterna!$B$B¡Pero, más que nada en el mundo, necesitamos tu ayuda para recobrar nuestras antaño gloriosas tierras!' WHERE `ID`=12233;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미란다, 확고한 동맹 평판을 얻은 모험가에게는 휘장을 몇 개나 받고 물건을 제공하는지 좀 알려주실래요?', `MaleText_loc4`='米兰达，你能告诉我，在崇拜声望级别的情况下，你所提供的物品需要多少徽记吗？', `MaleText_loc5`='米蘭達，能不能請你告訴我，聲望值到達崇拜的冒險者需要付出多少徽記才能夠獲得妳所提供的物品?', `MaleText_loc7`='Miranda, ¿podrías decirme cuántas insignias necesitan los aventureros exaltados para adquirir los objetos que ofreces?', `FemaleText_loc1`='미란다, 확고한 동맹 평판을 얻은 모험가에게는 휘장을 몇 개나 받고 물건을 제공하는지 좀 알려주실래요?', `FemaleText_loc4`='米兰达，你能告诉我，在崇拜声望级别的情况下，你所提供的物品需要多少徽记吗？', `FemaleText_loc5`='米蘭達，能不能請你告訴我，聲望值到達崇拜的冒險者需要付出多少徽記才能夠獲得妳所提供的物品?', `FemaleText_loc7`='Miranda, ¿podrías decirme cuántas insignias necesitan los aventureros exaltados para adquirir los objetos que ofreces?' WHERE `ID`=12234;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가르쳐 드리고 말고요.$B$B은빛 여명회의 확고한 동맹 자격을 얻은 모험가들은 모두 12개의 휘장을 내면 최고급 장비를 얻을 수 있답니다. 더 강력한 물건을 얻으려면 모두 54개의 휘장을 내야 하지요.$B$B은빛 여명회의 확고한 동맹에게는 엄청난 할인 혜택을 제공해 드리는 거예요.', `FemaleText_loc4`='当然，$n。$B$B在银色黎明组织中拥有崇拜级别声望的冒险者需要上缴12个徽记以获得优秀的物品。若想获得更加强大的物品，他们需要上缴54个徽记。$B$B只有在银色黎明眼中被崇拜的人，才能获得最大的折扣。', `FemaleText_loc5`='當然可以，$n。$B$B黎明陣營裡屬於崇拜聲望的冒險者必須交出12個徽記才能夠購買精良級的物品。如果購買更加強大的史詩級物品，他們就必須交出54個徽記。$B$B黎明的崇拜聲望者享有最大的優惠。', `FemaleText_loc7`='Por supuesto, $n.$B$BLos aventureros que el Alba cataloga de exaltados deben entregar un total de 12 insignias para acceder a objetos excelentes. Para tener acceso a objetos de un poder mayor, tendrán que entregar un total de 54 insignias.$B$BAquellos que el Alba tiene por exaltados se benefician de mayores descuentos.' WHERE `ID`=12235;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당연히 가르쳐 드려야죠, $n!$B$B은빛 여명회로부터 약간 우호적 평판을 얻은 모험가는 모두 60개의 휘장을 내면 최고급 장비를 얻을 수 있답니다. 더 강력한 물건을 얻으려면 모두 220개의 휘장을 내야 하지요.$B$B은빛 여명회의 신뢰를 얻지 못한 분들께는 가격이 상당히 비싸답니다.', `FemaleText_loc4`='当然，$n。$B$B在银色黎明组织中拥有友善级别声望的冒险者需要上缴60个徽记以获得优秀的物品。若想获得更加强大的物品，他们需要上缴220个徽记。$B$B对于那些银色黎明尚不眷顾的冒险者来说，这个价格是非常之高的。', `FemaleText_loc5`='當然可以，$n。$B$B黎明陣營裡屬於友好聲望的冒險者必須交出60個徽記才能購買精良級的物品。如果想購買更加強大的史詩級物品，他們就必須交出220個徽記。$B$B我話先說在前頭，沒有獲得黎明好感的冒險者所需要付出的代價可是非常的高。', `FemaleText_loc7`='Por supuesto, $n.$B$BLos aventureros que el Alba cataloga de amistosos deben entregar un total de 60 insignias para acceder a objetos excelentes. Para tener acceso a objetos de un poder mayor, tendrán que entregar un total de 220 insignias.$B$BDebo admitir que el precio es bastante alto para aquellos que cuentan con el favor del Alba.' WHERE `ID`=12236;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='약간 우호적 평판에 대해 말씀해 주십시오.', `MaleText_loc4`='友善。', `MaleText_loc5`='友好。', `MaleText_loc7`='Amistoso.', `FemaleText_loc1`='약간 우호적 평판에 대해 말씀해 주세요.', `FemaleText_loc4`='友善。', `FemaleText_loc5`='友好。', `FemaleText_loc7`='Amistoso.' WHERE `ID`=12237;
