UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 나에겐 당신이 원하는 지식이 있소이다. 배우고 싶은 게 뭐요?', `MaleText_loc4`='我有你需要的东西，$c。', `MaleText_loc5`='我有你需要的東西，$c。', `MaleText_loc7`='Tengo lo que necesitas, $c.' WHERE `ID`=12265;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼음파멸 가슴보호갑을 만드는 법을 배우고 싶습니다.', `MaleText_loc4`='破冰胸甲。', `MaleText_loc5`='冰剋胸甲。', `MaleText_loc7`='Peto deliriohelado.', `FemaleText_loc1`='얼음파멸 가슴보호갑을 만드는 법을 배우고 싶습니다.', `FemaleText_loc4`='破冰胸甲。', `FemaleText_loc5`='冰剋胸甲。', `FemaleText_loc7`='Peto deliriohelado.' WHERE `ID`=12266;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼음파멸 건틀릿을 만드는 법을 배우고 싶습니다.', `MaleText_loc4`='破冰护手。', `MaleText_loc5`='冰剋護手。', `MaleText_loc7`='Guanteletes deliriohelado.', `FemaleText_loc1`='얼음파멸 건틀릿을 만드는 법을 배우고 싶어요.', `FemaleText_loc4`='破冰护手。', `FemaleText_loc5`='冰剋護手。', `FemaleText_loc7`='Guanteletes deliriohelado.' WHERE `ID`=12267;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼음파멸 팔보호구 만드는 법을 배우고 싶습니다.', `MaleText_loc4`='破冰护腕。', `MaleText_loc5`='冰剋護腕。', `MaleText_loc7`='Brazales deliriohelado.', `FemaleText_loc1`='얼음파멸 팔보호구 만드는 법을 배우고 싶어요.', `FemaleText_loc4`='破冰护腕。', `FemaleText_loc5`='冰剋護腕。', `FemaleText_loc7`='Brazales deliriohelado.' WHERE `ID`=12268;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 대장기술의 대가입니다, 오마리온!', `MaleText_loc4`='我是一个大师级铁匠，奥玛里恩。', `MaleText_loc5`='我是鐵匠大師，歐瑪利安。', `MaleText_loc7`='Soy un maestro herrero, Omarion.', `FemaleText_loc1`='저는 대장기술의 대가예요, 오마리온!', `FemaleText_loc4`='我是一个大师级铁匠，奥玛里恩。', `FemaleText_loc5`='我是鐵匠大師，歐瑪利安。', `FemaleText_loc7`='Soy una maestra herrera, Omarion.' WHERE `ID`=12269;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이만 가보겠습니다. 악의 기운이 꿈틀대고 있군요. 편히 잠드십시오, 오마리온!', `MaleText_loc4`='我得走了。邪恶正在临近。自己小心了，奥玛里恩。', `MaleText_loc5`='我該走了。惡魔蠢蠢欲動。死吧，歐瑪利安。', `MaleText_loc7`='He de irme. El mal se agita. Muere en paz, Omarion.', `FemaleText_loc1`='이만 가볼게요. 악의 기운이 꿈틀대고 있어요. 부디 편히 잠드세요, 오마리온!', `FemaleText_loc4`='我得走了。邪恶正在临近。自己小心了，奥玛里恩。', `FemaleText_loc5`='我該走了。惡魔蠢蠢欲動。死吧，歐瑪利安。', `FemaleText_loc7`='He de irme. El mal se agita. Muere en paz, Omarion.' WHERE `ID`=12270;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 날아갈 수 있는 곳을 알려 주십시오.', `MaleText_loc4`='告诉我可以飞到哪里去。', `MaleText_loc5`='告訴我可以飛往那些地方。', `MaleText_loc7`='Muéstrame adónde puedo ir volando.', `FemaleText_loc1`='제가 날아갈 수 있는 곳을 알려 주세요.', `FemaleText_loc4`='告诉我可以飞到哪里去。', `FemaleText_loc5`='告訴我可以飛往那些地方。', `FemaleText_loc7`='Muéstrame adónde puedo ir volando.' WHERE `ID`=12271;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 마지막 힘을 근처의 마법석으로 방출하여 성공적으로 재가동시킵니다.', `MaleText_loc4`='%s将最后的力量灌注到附近的符石中，成功地激活了它。', `MaleText_loc5`='%s將它最後的能量釋放進附近的符文石中，成功地重新啟動它。', `MaleText_loc7`='%s libera lo que queda de sus fuerzas en la piedra rúnica cercana, y consigue reactivarla.' WHERE `ID`=12272;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어느 날 밤 거장 오마리온이 홀연히 사라졌네. 마치 바람에 실린 방귀처럼... 휙 하고 사라졌지! 흥, 이제 최전선의 병사들에게 필요한 물건을 만들어 줄 수 있는 건 이 몸밖에 없단 말일세.', `MaleText_loc4`='大工匠奥玛里恩某个晚上消失了。就像是风中的柳絮一样……呼地一声就没了！好吧，现在我就是唯一能够为前线的那帮家伙打造装备的人了。', `MaleText_loc5`='在某個夜裡工匠大師歐瑪利安突然消失了。就像風中的號角聲...咻!消失了!呸，現在只剩下我一個人幫前線的戰士們鑄造東西了。', `MaleText_loc7`='El maestro artesano Omarion simplemente desapareció una noche, como un susurro al viento... ¡Paf! ¡Y desapareció! Ahora soy el único que puede fabricar los objetos para los chicos que están en primera línea de batalla.' WHERE `ID`=12273;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물건을 보여주십시오, 빌헬름!', `MaleText_loc4`='让我看看你的货物，威尔海姆。', `MaleText_loc5`='留心點，維爾海姆。', `MaleText_loc7`='Enséñame tus mercancías, Wilhelm.', `FemaleText_loc1`='물건을 보여주세요, 빌헬름!', `FemaleText_loc4`='让我看看你的货物，威尔海姆。', `FemaleText_loc5`='留心點，維爾海姆。', `FemaleText_loc7`='Enséñame tus mercancías, Wilhelm.' WHERE `ID`=12274;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 행동은 그냥 넘길 수가 없다!', `MaleText_loc4`='你的行为是无法得到宽恕的！', `MaleText_loc5`='我們無法容忍你的行為!', `MaleText_loc7`='¡No vamos a tolerar tus acciones!', `FemaleText_loc1`='네 행동은 그냥 넘길 수가 없다!', `FemaleText_loc4`='你的行为是无法得到宽恕的！', `FemaleText_loc5`='我們無法容忍你的行為!', `FemaleText_loc7`='¡No vamos a tolerar tus acciones!' WHERE `ID`=12275;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳 규율에 따라 처벌하겠다, 이교도여!', `MaleText_loc4`='你将被我们的律法所审判，异教徒！', `MaleText_loc5`='在這裡就要遵守我們的規則，無賴!', `MaleText_loc7`='¡Deberás atenerte a nuestras reglas, bellaco!', `FemaleText_loc1`='이곳 규율에 따라 처벌하겠다, 이교도여!', `FemaleText_loc4`='你将被我们的律法所审判，异教徒！', `FemaleText_loc5`='在這裡就要遵守我們的規則，無賴!', `FemaleText_loc7`='¡Deberás atenerte a nuestras reglas, bellaco!' WHERE `ID`=12276;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무기를 내려놓아라! 원한을 풀고자 한들 이곳에서는 아무 소용없다!', `MaleText_loc4`='放下武器，你们胆敢在这里造次！', `MaleText_loc5`='放下武器，這裡容不下你的仇恨!', `MaleText_loc7`='¡Bajen las armas, sus contiendas no tienen cabida en este lugar!', `FemaleText_loc1`='무기를 내려놓아라! 원한을 풀고자 한들 이곳에서는 아무 소용없다!', `FemaleText_loc4`='放下武器，你们胆敢在这里造次！', `FemaleText_loc5`='放下武器，這裡容不下你的仇恨!', `FemaleText_loc7`='¡Bajen las armas, sus contiendas no tienen cabida en este lugar!' WHERE `ID`=12277;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='유령의 땅에서 신도레이와 포세이큰은 공동의 목표가 있습니다. 우리는 함께 스컬지를 물리칠 것입니다. 혹시 누가 압니까? 아웃랜드로 진출하려는 우리의 목표에 포세이큰이 소중한 동맹이 될지...', `MaleText_loc4`='$n，辛多雷和被遗忘者在幽魂之地的目标是一致的。我们将共同击败亡灵天灾，或许在我们进军外域的过程中，被遗忘者也将成为最有价值的盟友……谁知道呢。', `MaleText_loc5`='辛多雷和被遺忘者在鬼魂之地有共同目標，$n。我們會一起打敗天譴軍團的，而且誰知道...搞不好被遺忘者是攻進外域的得力助手。', `MaleText_loc7`='Los sin''dorei y los Renegados comparten su objetivo en las Tierras Fantasma, $n. Juntos acabaremos con la Plaga y quién sabe... tal vez los Renegados sean valiosos aliados en nuestro intento de alcanzar Terrallende.' WHERE `ID`=12278;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오마리온, 저는 장인이 아닙니다. 그래도 절 도와주실 수 있습니까?', `MaleText_loc4`='奥玛里恩，我不是一个工匠，你还能帮助我吗？', `MaleText_loc5`='歐瑪利安，我不是工匠。你還能幫我嗎?', `MaleText_loc7`='Omarion, yo no soy artesano. ¿Puedes ayudarme de todos modos?', `FemaleText_loc1`='오마리온, 저는 장인이 아니에요. 그래도 절 도와주실 수 있나요?', `FemaleText_loc4`='奥玛里恩，我不是一个工匠，你还能帮助我吗？', `FemaleText_loc5`='歐瑪利安，我不是工匠。你還能幫我嗎?', `FemaleText_loc7`='Omarion, yo no soy artesana. ¿Puedes ayudarme de todos modos?' WHERE `ID`=12279;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<조그만 소리로 무언가 투덜대는 오마리온>$B$B물론 도와줄 수는 있소. 이것은 죽어가는 나의 소원이자... 마지막 희망이오. 자, 이 안내서를 받으시오. 내가 알고 있는 모든 지식, 지난 30년간 고달팠던 삶을 통해 내가 배운 모든 것이 적혀 있소이다. 아무짝에도 쓸모없는 내 제자 놈에게 전해 주시오. 아마도 희망의 빛 예배당에 그 뚱뚱한 궁둥이를 붙이고 앉아 있을 것이오.', `MaleText_loc4`='<奥玛里恩一边喘息着一边叙述着什么。>$B$B当然，我可以帮助你，亲爱的$g小伙子:姑娘;。这是我死前……最后一个愿望了。请拿走这本手册吧。上面的信息是我三十年来所继承并学习到的全部家学。把它带给我那个傻得可爱的学徒，他或许还傻傻地坐在圣光之愿礼拜堂门口等我回去呢。', `MaleText_loc5`='<歐瑪利安嘴裡咕噥說著什麼。>$B$B但是我當然可以幫你，親愛的$g男孩:女孩;。這是我夢寐以求的希望...我最後的渴求。拜託，拿著這本手冊。裡面的資料是我過去30年來悲慘的人生中所有知識的總整理。把這本手冊交給我那一無是處的學徒，他肥胖的身軀應該就坐在聖光之願禮拜堂。', `MaleText_loc7`='<Omarion dice algo por lo bajo.>$B$BPor supuesto que puedo ayudarte, $gchico:chica;. Es lo que quiero... mi último deseo antes de morir. Por favor, coge este manual. Sus páginas contienen todo mi saber y todo lo que he aprendido en los últimos 30 años de mi miserable vida. Entrégale el manual a mi inepto aprendiz que sin duda estará repanchingado en la Capilla de la Esperanza de la Luz.' WHERE `ID`=12280;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙습니다, 오마리온! 당신은 이 세계를 위해 큰일을 하신 겁니다.', `MaleText_loc4`='谢谢你，奥玛里恩。今天你的盔甲让一支军队得以避免伤亡。', `MaleText_loc5`='謝謝你，歐瑪利安。你為小隊擊出了決定命運的一擊。', `MaleText_loc7`='Gracias, Omarion. Hoy has asestado un duro golpe al equipo.', `FemaleText_loc1`='고맙습니다, 오마리온! 당신은 이 세계를 위해 큰일을 하신 거예요.', `FemaleText_loc4`='谢谢你，奥玛里恩。今天你的盔甲让一支军队得以避免伤亡。', `FemaleText_loc5`='謝謝你，歐瑪利安。你為小隊擊出了決定命運的一擊。', `FemaleText_loc7`='Gracias, Omarion. Hoy has asestado un duro golpe al equipo.' WHERE `ID`=12281;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<조용히 신음하는 타르시스>$B$B아직 얘기를 나눌 시간은 있을 거야... 잘 들으시오, 필멸의 존재여.$B$B나는 오랫동안 황천을 조사해 왔소. 악마의 군주와 계약을 맺고 사악한 짓을 서슴없이 저질렀지...$B$B<기침을 하며 손에 피를 토하는 타르시스>$B$B엘룬... 심지어 엘룬께서조차 날 버렸다고 한다면 어느 정도인지 짐작이 되나, $r? 여기서 지금 이대로 죽고 싶...', `MaleText_loc4`='<塔希斯呻吟着>$B$B或许还有时间……听仔细了，凡人。$B$B我穿越了虚空，我探索了未知的世界……我与一个强大的邪恶存在定下了微妙的协议……$B$B<塔希斯咳出了鲜血。>$B$B你……你是否能相信，即使是艾露恩也不再怜悯我，$r？现在我要死在这里了，要以这种方式……', `MaleText_loc5`='<塔希斯呻吟。>$B$B或許還有時間...仔細聽好，凡人。$B$B我在時間與空間裡搜索。和一個極度邪惡的惡魔主人打過交道...$b$b<塔希斯在手中咳出血來。>$B$B你會...你會相信就連伊露恩也不理我了嗎，$r?死在這裡，現在這樣的情勢之下...', `MaleText_loc7`='<Tarsis refunfuña.>$B$BPuede que todavía quede tiempo... Escucha con atención, mortal.$B$BA través del Vacío y del tiempo he buscado. Con grandes males e infamias me he encontrado...$B$B<Tarsis tose sangre sobre sus manos.>$B$B¿Puedes... puedes creer que incluso Elune me ha dado la espalda, $r? Morir aquí, de este modo...' WHERE `ID`=12282;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그게 무슨 말입니까?', `MaleText_loc4`='你在说些什么，法师？', `MaleText_loc5`='你在說什麼，法師?', `MaleText_loc7`='¿De qué estás hablando, mago?', `FemaleText_loc1`='그게 무슨 말인가요?', `FemaleText_loc4`='你在说些什么，法师？', `FemaleText_loc5`='你在說什麼，法師?', `FemaleText_loc7`='¿De qué estás hablando, mago?' WHERE `ID`=12283;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 끔찍한... 아주 끔찍한 짓을 저질렀소...$B$B<흐느끼기 시작하는 타르시스>', `MaleText_loc4`='我所犯下的错误……多么可怕的错误……$B$B<塔希斯的声音呜咽了起来。>', `MaleText_loc5`='我做過的事...這樣恐怖的事...$b$b<塔希斯開始啜泣。>', `MaleText_loc7`='Las cosas que he hecho... cosas horribles...$B$B<Tarsis comienza a sollozar.>' WHERE `ID`=12284;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 그런 짓을 저질렀습니까?', `MaleText_loc4`='你到底做了什么可怕的事？', `MaleText_loc5`='你為什麼要做出這樣恐怖的事?', `MaleText_loc7`='¿Por qué has hecho cosas tan horribles?', `FemaleText_loc1`='왜 그런 짓을 저질렀나요?', `FemaleText_loc4`='你到底做了什么可怕的事？', `FemaleText_loc5`='你為什麼要做出這樣恐怖的事?', `FemaleText_loc7`='¿Por qué has hecho cosas tan horribles?' WHERE `ID`=12285;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$r|1이여;여;, 나는 고대의 명가요. 지금은 아무 소용없지만... 하지만 한때 명가의 일원들이 세계를 통치하던 시절이 있었지. 지금으로부터 만 년 전...', `MaleText_loc4`='我是一名上层精灵，$r。虽然这个词语现在已经不能代表什么了，但很久以前，这个世界曾被上层精灵所统治。一万年过去了……', `MaleText_loc5`='我是個精靈貴族，$r。現在已經沒有意義了。雖然，曾有一段時間，這個世界是被精靈貴族所統治的。一萬年過去了...', `MaleText_loc7`='Soy un Altonato, $r. Eso ya no importa. Sin embargo, hubo un tiempo en el que este mundo estaba gobernado por Ilustres. De eso hace miles de años...' WHERE `ID`=12286;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이해가 되지 않는군요.', `MaleText_loc4`='我还是不理解。', `MaleText_loc5`='我還是不明白。', `MaleText_loc7`='Sigo sin comprender.', `FemaleText_loc1`='이해가 되지 않는군요.', `FemaleText_loc4`='我还是不理解。', `FemaleText_loc5`='我還是不明白。', `FemaleText_loc7`='Sigo sin comprender.' WHERE `ID`=12287;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필멸의 존재여, 나는 그것을 되찾으려 했소. 아티쉬... 아티쉬로부터 새로운 명가의 시대를 열어보려고 했지. 모든 것을 되돌리려 했소. 심지어 여왕까지도...', `MaleText_loc4`='我一定会把它找回来的，凡人。埃提耶什……有了它，我就可以重建上层精灵社会。我一定会把它找到的。就算是女王……', `MaleText_loc5`='我會把它拿回來的，凡人。阿泰絲...我會用它來使精靈貴族獲得新生。我會讓他們全都復原。就連我們的女王也是...', `MaleText_loc7`='Lo recuperaré, mortal. Recuperaré a Atiesh... y con él traeré de nuevo a los Altonato al mundo. Haré que todo sea como antes. Traeré de vuelta incluso a la Reina...' WHERE `ID`=12288;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대마법사님, 말도 안 되는 소리를 하시는군요.', `MaleText_loc4`='你似乎有妄想症了，法师。', `MaleText_loc5`='你在胡說八道，法師。', `MaleText_loc7`='Estás divagando, mago.', `FemaleText_loc1`='대마법사님, 말도 안 되는 소리를 하시네요.', `FemaleText_loc4`='你似乎有妄想症了，法师。', `FemaleText_loc5`='你在胡說八道，法師。', `FemaleText_loc7`='Estás divagando, mago.' WHERE `ID`=12289;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<당신의 멱살을 힘겹게 잡는 타르시스. 비록 죽음을 눈앞에 두고 있었지만 그의 눈에서 상상조차 할 수 없는 힘이 느껴집니다.>$B$B그렇게 생각하시오? 그렇다면, 잘 들으시오. 지금부터 더욱 말도 안 되는 소리가 이어질 테니... 이 요새에는 내가 일생을 바쳐 이룩한 업적이 있소. 바로 부서진 지팡이 조각들의 정확한 위치 말이오.', `MaleText_loc4`='<塔希斯抓住了你的领子，他显得十分虚弱。就算是这样一个虚弱的人，你仍能从他眼中看见令人难以想象的光芒。>$B$B妄想症？仔细给我听好了，更没有意义的妄想就被我说出来了。这座城堡中拥有我毕生追寻的东西，我已经知道了每一块法杖碎片的确切位置。', `MaleText_loc5`='<塔希斯虛弱地抓住你的衣領。即使瀕臨死亡你也在他的眼中看到難以想像的力量。>$B$B我是嗎?那麼仔細聽好，因為有更多的瘋言瘋語要從我嘴裡說出來了。在堡壘裡面你會發現我畢生的傑作:每一塊碎裂的法杖碎片的所在位置。', `MaleText_loc7`='<Tarsis te agarra débilmente por el cuello. Hasta en la muerte ves un poder inimaginable en sus ojos.>$B$B¿Lo soy? Entonces escucha atentamente, pues hay más tonterías a punto de escapar de mis labios. En esta ciudadela encontrarás el trabajo de mi vida: la ubicación exacta de cada fragmento del bastón astillado.' WHERE `ID`=12290;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 지팡이 말입니까?', `MaleText_loc4`='什么法杖？', `MaleText_loc5`='什麼法杖?', `MaleText_loc7`='¿Qué báculo?', `FemaleText_loc1`='무슨 지팡이 말인가요?', `FemaleText_loc4`='什么法杖？', `FemaleText_loc5`='什麼法杖?', `FemaleText_loc7`='¿Qué báculo?' WHERE `ID`=12291;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아티쉬, 수호자의 지팡이 말이오. 그 지팡이는 수 세대에 걸쳐 티리스팔의 수호자에게 전해져 왔소. 그 지팡이가 살게라스에게 오염됐소이다. 최후의 수호자, 메디브의 지팡이가 말이오.', `MaleText_loc4`='埃提耶什，守护者的传说之杖。这把法杖是提瑞斯法守护者历代相传之物。但它已被萨格拉斯所污染。它是最后一任守护者的武器，麦迪文的法杖。', `MaleText_loc5`='阿泰絲，守護者之杖。那個法杖一直以來都在每個提里斯法的守護者間流傳著。法杖後來被薩格拉斯腐敗。最後一名守護者的法杖。麥迪文的法杖。', `MaleText_loc7`='Atiesh, el gran báculo del guardián. El báculo heredado a través de los siglos por cada uno de los guardianes de Tirisfal. El báculo corrompido por Sargeras. El báculo del último guardián. El báculo de Medivh.' WHERE `ID`=12292;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그것을 되찾으려 했다고 하셨는데, 무슨 뜻입니까?', `MaleText_loc4`='你说你终究会找回它，这是什么意思？', `MaleText_loc5`='你說你會把它奪回來。那是什麼意思?', `MaleText_loc7`='Dijiste que lo recuperarías. ¿Qué significa eso?', `FemaleText_loc1`='그것을 되찾으려 했다고 하셨는데, 무슨 뜻이죠?', `FemaleText_loc4`='你说你终究会找回它，这是什么意思？', `FemaleText_loc5`='你說你會把它奪回來。那是什麼意思?', `FemaleText_loc7`='Dijiste que lo recuperarías. ¿Qué significa eso?' WHERE `ID`=12293;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<눈빛이 빛나는 타르시스>$B$B나는 한때 그 지팡이를 손에 넣었지... 키린 토의 경고에도 그것을 독차지했다오. 필멸의 존재여, 그 지팡이가 내 손에 있었단 말이오... 무한한 힘, 원하는 것은 무엇이든 할 수 있는 힘. 금세 다시 뺏기기는 했지만 난 힘의 맛을 보고 말았던 것이오... 그 힘이 가져다주는 거역할 수 없는 힘을 잊지 못해 이 모든 사태가 벌어진 것이오.', `MaleText_loc4`='<塔希斯的眼神亮了起来。>$B$B我曾拥有过它……我曾不顾肯瑞托议会的警告而拥有过它。我拥有过它啊，凡人……那无尽的力量。力量就是我追寻的一切，我追寻的……一切。时光稍瞬即逝，但我确实……确实……曾拥有过它，品尝过力量的甘美……', `MaleText_loc5`='<塔希斯的眼神發亮。>$B$B我曾經擁有它...我不顧祈倫托的警告擁有它。我曾經擁有它，凡人...無盡的力量。做我想做的事的力量，隨心所慾。就在那個時候，它從我手中被奪走了。但是我嘗過那種滋味...而那滋味值得你付出那樣的代價。', `MaleText_loc7`='<Los ojos de Tarsis se iluminan.>$B$BLo tuve una vez en mis manos... a pesar de las advertencias del Kirin Tor. Lo tuve, mortal... Ese infinito poder. El poder para hacer todo lo que anhelaba, a mi antojo. Y tan pronto llegó a mis manos, me fue arrebatado. Pero ya lo había saboreado y nunca más podré olvidar esa sensación.' WHERE `ID`=12294;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 한쪽 무릎을 꿇습니다.', `MaleText_loc4`='%s单膝跪了下来。', `MaleText_loc5`='%s單腳跪下。', `MaleText_loc7`='%s hinca una rodilla.', `FemaleText_loc1`='%s|1이;가; 한쪽 무릎을 꿇습니다.', `FemaleText_loc4`='%s单膝跪了下来。', `FemaleText_loc5`='%s單腳跪下。', `FemaleText_loc7`='%s hinca una rodilla.' WHERE `ID`=12295;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 앉습니다.', `MaleText_loc4`='%s坐了下来。', `MaleText_loc5`='%s坐下。', `MaleText_loc7`='%s se sienta.' WHERE `ID`=12296;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<심각한 부상을 입은 타르시스>', `MaleText_loc4`='<塔希斯的伤势非常严重。>', `MaleText_loc5`='<塔希斯傷的很重。>', `MaleText_loc7`='<Tarsis está gravemente herido.>' WHERE `ID`=12297;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<타르시스를 깨웁니다.>', `MaleText_loc4`='<将塔希斯唤醒。>', `MaleText_loc5`='<叫醒塔希斯。>', `MaleText_loc7`='<Despierta a Tarsis.>', `FemaleText_loc1`='<타르시스를 깨웁니다.>', `FemaleText_loc4`='<将塔希斯唤醒。>', `FemaleText_loc5`='<叫醒塔希斯。>', `FemaleText_loc7`='<Despierta a Tarsis.>' WHERE `ID`=12298;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투에서 승리했습니다! 스컬지의 침공은 당분간 주춤할 것입니다. 고마움을 표시하고 앞일을 대비하는 의미에서 우리가 가진 것을 나눠 드리겠습니다.', `MaleText_loc4`='战争胜利了。目前天灾军团的威胁已经被暂时消除了。我们还有一些剩余资源，如果你需要的话，我可以帮助你，以感激你做出的贡献，并为将来做准备。', `MaleText_loc5`='我們贏得了戰役。就目前看來，天譴軍團的威脅已被擊退。我們的資源可以引導來協助你們，作為感謝並為將來做準備。', `MaleText_loc7`='Hemos ganado la batalla. Hasta el momento, hemos detenido la amenaza de la Plaga. Ahora podremos utilizar nuestros recursos para ayudarte, en agradecimiento y como preparación para el futuro.', `FemaleText_loc1`='전투에서 승리했습니다! 스컬지의 침공은 당분간 주춤할 것입니다. 고마움을 표시하고 앞일을 대비하는 의미에서 우리가 가진 것을 나눠 드리겠습니다.', `FemaleText_loc4`='战争胜利了。目前天灾军团的威胁已经被暂时消除了。我们还有一些剩余资源，如果你需要的话，我可以帮助你，以感激你做出的贡献，并为将来做准备。', `FemaleText_loc5`='我們贏得了戰役。就目前看來，天譴軍團的威脅已被擊退。我們的資源可以引導來協助你們，作為感謝並為將來做準備。', `FemaleText_loc7`='Hemos ganado la batalla. Hasta el momento, hemos detenido la amenaza de la Plaga. Ahora podremos utilizar nuestros recursos para ayudarte, en agradecimiento y como preparación para el futuro.' WHERE `ID`=12299;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투는 아주 성공적이며 스컬지 세력이 약해진 것 같습니다. 우리 해안에서 스컬지를 몰아내는 것은 이제 시간문제일 뿐입니다. 이 전투에 도움이 되도록 당신에게 마법을 걸어 드리겠습니다.', `MaleText_loc4`='战役进行良好。天灾军团的实力已经被大大削弱了。我相信我们完全能够把他们都赶进海里，这只是时间问题了。我会尽可能地帮助你进行战斗。', `MaleText_loc5`='戰役進行的很順利。天譴軍團的軍隊看來比較衰弱了。我相信把他們趕出我們的海岸只是早晚的事了。我會提供我的魔法幫助你們打贏這場仗。', `MaleText_loc7`='La batalla marcha bien. Las tropas de la Plaga parecen debilitadas. Creo que es cuestión de tiempo que consigamos expulsarlas de nuestras costas. Con mi magia les ayudaré en su lucha.', `FemaleText_loc1`='전투는 아주 성공적이며 스컬지 세력이 약해진 것 같습니다. 우리 해안에서 스컬지를 몰아내는 것은 이제 시간문제일 뿐입니다. 이 전투에 도움이 되도록 당신에게 마법을 걸어 드리겠습니다.', `FemaleText_loc4`='战役进行良好。天灾军团的实力已经被大大削弱了。我相信我们完全能够把他们都赶进海里，这只是时间问题了。我会尽可能地帮助你进行战斗。', `FemaleText_loc5`='戰役進行的很順利。天譴軍團的軍隊看來比較衰弱了。我相信把他們趕出我們的海岸只是早晚的事了。我會提供我的魔法幫助你們打贏這場仗。', `FemaleText_loc7`='La batalla marcha bien. Las tropas de la Plaga parecen debilitadas. Creo que es cuestión de tiempo que consigamos expulsarlas de nuestras costas. Con mi magia les ayudaré en su lucha.' WHERE `ID`=12300;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스컬지를 상대로 한 싸움의 첫 단계가 성공적으로 진행되고 있습니다. 우리는 이미 몇 번의 성공을 거두었습니다. 저의 지원으로 앞으로 전투에서도 승리를 가져오기를 바랍니다.', `MaleText_loc4`='我们针对天灾军团的第一步战役进行得非常良好。我们已经获得了一些胜利，希望我的协助能让你取得更多的胜利。', `MaleText_loc5`='我們對抗天譴軍團的第一步進行的很好。我們有了一些成就，希望我們的協助能幫你們獲得未來的勝利。', `MaleText_loc7`='Los primeros pasos de nuestra lucha contra la Plaga marchan bien. Estamos haciendo bien las cosas y espero que mi ayuda pueda servir para continuar con éxito la batalla.', `FemaleText_loc1`='스컬지를 상대로 한 싸움의 첫 단계가 성공적으로 진행되고 있습니다. 우리는 이미 몇 번의 성공을 거두었습니다. 저의 지원으로 앞으로 전투에서도 승리를 가져오기를 바랍니다.', `FemaleText_loc4`='我们针对天灾军团的第一步战役进行得非常良好。我们已经获得了一些胜利，希望我的协助能让你取得更多的胜利。', `FemaleText_loc5`='我們對抗天譴軍團的第一步進行的很好。我們有了一些成就，希望我們的協助能幫你們獲得未來的勝利。', `FemaleText_loc7`='Los primeros pasos de nuestra lucha contra la Plaga marchan bien. Estamos haciendo bien las cosas y espero que mi ayuda pueda servir para continuar con éxito la batalla.' WHERE `ID`=12301;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저에게 당신의 마법 중 하나를 허락해주십시오.', `MaleText_loc4`='让我看看你的魔法物品吧。', `MaleText_loc5`='將你的魔法施放在我身上。', `MaleText_loc7`='Entrégame uno de tus objetos mágicos.', `FemaleText_loc1`='저에게 당신의 마법 중 하나를 허락해주세요.', `FemaleText_loc4`='让我看看你的魔法物品吧。', `FemaleText_loc5`='將你的魔法施放在我身上。', `FemaleText_loc7`='Entrégame uno de tus objetos mágicos.' WHERE `ID`=12302;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 것을 원하시든지 최선을 다해 돕겠습니다.', `MaleText_loc4`='无论你需要什么帮助，我都会竭尽所能。', `MaleText_loc5`='我隨你差遣提供任何我能做的協助。', `MaleText_loc7`='Pongo a su disposición toda la ayuda que les pueda brindar.', `FemaleText_loc1`='어떤 것을 원하시든지 최선을 다해 돕겠습니다.', `FemaleText_loc4`='无论你需要什么帮助，我都会竭尽所能。', `FemaleText_loc5`='我隨你差遣提供任何我能做的協助。', `FemaleText_loc7`='Pongo a su disposición toda la ayuda que les pueda brindar.' WHERE `ID`=12303;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지팡이는 어떻게 됐습니까?', `MaleText_loc4`='法杖后来怎么了？', `MaleText_loc5`='法杖發生了什麼事?', `MaleText_loc7`='¿Qué ocurrió con el báculo?', `FemaleText_loc1`='지팡이는 어떻게 됐나요?', `FemaleText_loc4`='法杖后来怎么了？', `FemaleText_loc5`='法杖發生了什麼事?', `FemaleText_loc7`='¿Qué ocurrió con el báculo?' WHERE `ID`=12304;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보랏빛 성채가 파괴되었을 때 지팡이도 사라졌소... 정확하게 42조각으로 부서진 것이지.', `MaleText_loc4`='当紫罗兰城堡陨落时，它丢失了，破碎成了四十二块碎片。', `MaleText_loc5`='它是在紫羅蘭城塞陷落之後不見的...碎成了四十二個碎片。', `MaleText_loc7`='Se perdió con la caída de la Ciudadela Violeta... dividido en cuarenta y dos fragmentos.' WHERE `ID`=12305;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 낙스라마스에 온 이유는 뭡니까?', `MaleText_loc4`='那你为什么要来纳克萨玛斯？', `MaleText_loc5`='什麼風把你吹來納克薩瑪斯?', `MaleText_loc7`='Así pues, ¿qué te ha traído a Naxxramas?', `FemaleText_loc1`='그럼 낙스라마스에 온 이유는 뭔가요?', `FemaleText_loc4`='那你为什么要来纳克萨玛斯？', `FemaleText_loc5`='什麼風把你吹來納克薩瑪斯?', `FemaleText_loc7`='Así pues, ¿qué te ha traído a Naxxramas?' WHERE `ID`=12306;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='켈투자드는 지팡이를 복원하기 위해 엄청난 노력을 했소. 지팡이 조각들은 칼림도어에서 남쪽 바다에 이르기까지 아제로스 전 지역에 흩어져 있었지. 한때 나는 지팡이 조각을 20개나 가지고 있던 적도 있었소. 하지만 켈투자드의 부하들에게 도둑을 맞았지. 내가 여기 온 것도 바로 그 때문이오.', `MaleText_loc4`='克尔苏加德为了重铸这根法杖，投入了令人难以想象的代价。那些碎片当时被弹射到了世界各地，从卡利姆多到南海。我亲自曾有最多持有过其中的二十块，但最终都被克尔苏加德的手下偷走了。这也是我来到此地的原因。', `MaleText_loc5`='科爾蘇加德付出了相當大的努力在嘗試重組法杖。這些碎片又再次散落在世界各地，從卡林多到南海都有。我曾經一次擁有二十個碎片 - 直到科爾蘇加德的爪牙從我手中將它們偷走。這就是為什麼我會在這裡的原因。', `MaleText_loc7`='Kel''Thuzad ha intentado por todos los medios reconstruir el báculo. Los distintos fragmentos fueron esparcidos por todo este mundo, desde Kalimdor hasta los Mares del Sur. Yo conseguí reunir veinte fragmentos del báculo hasta que los esbirros de Kel''Thuzad me los arrebataron. Por eso estoy aquí.' WHERE `ID`=12307;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 켈투자드가 모든 조각들을 갖고 있습니까?', `MaleText_loc4`='也就是说克尔苏加德拥有全部的碎片？', `MaleText_loc5`='所以科爾蘇加德擁有全部的碎片?', `MaleText_loc7`='¿Eso significa que Kel''Thuzad ha conseguido todos los fragmentos del báculo?', `FemaleText_loc1`='그럼 켈투자드가 모든 조각들을 갖고 있나요?', `FemaleText_loc4`='也就是说克尔苏加德拥有全部的碎片？', `FemaleText_loc5`='所以科爾蘇加德擁有全部的碎片?', `FemaleText_loc7`='¿Eso significa que Kel''Thuzad ha conseguido todos los fragmentos del báculo?' WHERE `ID`=12308;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 말을 듣고는 있는 거요? 아니오. 켈투자드가 지팡이를 복원했다면 우리는 이런 대화를 다시 나눌 필요도 없지 않겠소. 그는 머리 부분을 지니고 있소이다. 그리고 그의 부하들에게 아티쉬의 조각 40개가 있지. 마지막 조각인 아랫부분을 찾은 것은 브란 브론즈비어드였소. 그의 모습이 마지막으로 목격된 곳은 실리더스 사막이오. 보나 마나 켈투자드가 이 세계로 보낸 무자비한 추적자들의 눈을 피하기 위해 그곳에 숨어 있을 것이오.', `MaleText_loc4`='你没听明白吗？不，至少在我们在这里谈话时，克尔苏加德还无法重新铸成法杖。克尔苏加德拥有法杖的头，他的手下分别持有着埃提耶什的四十块碎片。可杖尾却被布莱恩·铜须拿走了。他最后一次出现应该是在希利苏斯的沙漠；很显然他是为了尽量躲避克尔苏加德派出的那些残忍的杀手与刺客才这么做的。', `MaleText_loc5`='你沒在聽嗎?不，我很懷疑如果科爾蘇加德組合了法杖我們還能有這段談話。科爾蘇加德握有那個杖頭。他的手下擁有四十個阿泰絲之杖的碎片。最後一塊 - 杖柄 - 被布萊恩·銅鬚發現。他最後一次被人看到是在希利蘇斯的沙漠;毫無疑問地，離科爾蘇加德派遣到這世界的殘酷追尋者越遠越好。', `MaleText_loc7`='¿Acaso no has estado escuchando? Claro que no. Dudo mucho que estuviéramos teniendo esta conversación si Kel''Thuzad hubiera reconstruido el báculo. Kel''Thuzad posee la parte superior y sus subordinados guardan cuarenta fragmentos de Atiesh. La última pieza, la base, fue descubierta por Brann Barbabronce. Fue visto por última vez en el desierto de Silithus, sin duda intentando permanecer lo más lejos posible de los implacables subordinados de Kel''Thuzad desperdigados por todo el mundo.' WHERE `ID`=12309;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투 준비! 빛의 대성당에 스컬지가 나타났다!', `MaleText_loc4`='准备战斗！光明大教堂附近发现了天灾士兵！', `MaleText_loc5`='拿好武器!天譴軍團鎖定了聖光大教堂!', `MaleText_loc7`='¡Coged las armas! ¡Hemos avistado a la Plaga en la Catedral de la Luz!', `FemaleText_loc1`='전투 준비! 빛의 대성당에 스컬지가 나타났다!', `FemaleText_loc4`='准备战斗！光明大教堂附近发现了天灾士兵！', `FemaleText_loc5`='拿好武器!天譴軍團鎖定了聖光大教堂!', `FemaleText_loc7`='¡Coged las armas! ¡Hemos avistado a la Plaga en la Catedral de la Luz!' WHERE `ID`=12310;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상업 지구에 스컬지가 나타났다! 놈들을 잡아라!', `MaleText_loc4`='天灾攻入了贸易区！击退他们！', `MaleText_loc5`='天譴軍團在貿易區!制伏他們!', `MaleText_loc7`='¡Presencia de la Plaga en el Distrito de Mercaderes! ¡Al ataque!', `FemaleText_loc1`='상업 지구에 스컬지가 나타났다! 놈들을 잡아라!', `FemaleText_loc4`='天灾攻入了贸易区！击退他们！', `FemaleText_loc5`='天譴軍團在貿易區!制伏他們!', `FemaleText_loc7`='¡Presencia de la Plaga en el Distrito de Mercaderes! ¡Al ataque!' WHERE `ID`=12311;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신... 그 몸통! 어떻게? 당신은 절대... 그것은... 파괴자...', `MaleText_loc4`='你……那杖柄！怎么可能？你该不会……那……那是毁灭者……', `MaleText_loc5`='你...框架!怎麼會?你絕對不能...它...毀滅者...', `MaleText_loc7`='No... ¡El bastón! ¿Cómo? No debes... el... el Destructor...' WHERE `ID`=12312;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일입니까, 타르시스? 저는 어떻게 해야 하는 거죠?', `MaleText_loc4`='塔纳利斯是什么？我不知道我该做些什么！', `MaleText_loc5`='這是什麼塔希斯?我不知道該怎麼做才好!', `MaleText_loc7`='¿Qué ocurre, Tarsis? ¡No sé qué hacer!', `FemaleText_loc1`='무슨 일입니까, 타르시스? 저는 어떻게 해야 하는 거죠?', `FemaleText_loc4`='塔纳利斯是什么？我不知道我该做些什么！', `FemaleText_loc5`='這是什麼塔希斯?我不知道該怎麼做才好!', `FemaleText_loc7`='¿Qué ocurre, Tarsis? ¡No sé qué hacer!' WHERE `ID`=12313;
