UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛이여, 우리를 도와주십시오... 스톰윈드 공원에 스컬지가 나타났다!', `MaleText_loc4`='圣光保佑……天灾已经入侵公园区了！', `MaleText_loc5`='聖光幫助我們...天譴軍團在花園裡!', `MaleText_loc7`='Que la Luz nos ayude... ¡La Plaga está en El Parque!', `FemaleText_loc1`='빛이여, 우리를 도와주십시오... 스톰윈드 공원에 스컬지가 나타났다!', `FemaleText_loc4`='圣光保佑……天灾已经入侵公园区了！', `FemaleText_loc5`='聖光幫助我們...天譴軍團在花園裡!', `FemaleText_loc7`='Que la Luz nos ayude... ¡La Plaga está en El Parque!' WHERE `ID`=12315;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왕궁 입구에 스컬지가 나타났다! 스톰윈드 만세! 국왕 폐하 만세!', `MaleText_loc4`='天灾军团已经打到城堡入口了！为了暴风王国而战！为了安度因国王陛下而战！', `MaleText_loc5`='天譴軍團在城堡入口!為了暴風城!為了安杜因國王!', `MaleText_loc7`='¡La Plaga está a la entrada del castillo! ¡Por Ventormenta! ¡Por el rey Anduin!', `FemaleText_loc1`='왕궁 입구에 스컬지가 나타났다! 스톰윈드 만세! 국왕 폐하 만세!', `FemaleText_loc4`='天灾军团已经打到城堡入口了！为了暴风王国而战！为了安度因国王陛下而战！', `FemaleText_loc5`='天譴軍團在城堡入口!為了暴風城!為了安杜因國王!', `FemaleText_loc7`='¡La Plaga está a la entrada del castillo! ¡Por Ventormenta! ¡Por el rey Anduin!' WHERE `ID`=12316;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물러서지 마라! 무슨 일이 있어도 국왕 폐하를 지켜야 한다!', `MaleText_loc4`='坚守防线！不惜一切代价保卫国王陛下！', `MaleText_loc5`='守住戰線!不論如何要保護大王!', `MaleText_loc7`='¡Defended el frente! ¡Proteged al rey a toda costa!' WHERE `ID`=12317;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왕궁에 침입한 스컬지를 물리쳤군요. 모두 정말 수고가 많았습니다!', `MaleText_loc4`='大家干得好！城堡里的天灾军团已经全部被消灭了！', `MaleText_loc5`='做的好，全部做的好!城堡裡的天譴軍團已被擊敗。', `MaleText_loc7`='¡Habéis hecho todos un buen trabajo! ¡Hemos derrotado a la Plaga en el castillo!' WHERE `ID`=12318;
