UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕께서 명하신다... 죽어라!', `MaleText_loc4`='巫妖王要你的……命！', `MaleText_loc5`='巫妖王告訴你...死!', `MaleText_loc7`='El Rey Exánime dice... ¡MUERE!' WHERE `ID`=12326;
