UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크하하, 경비병 따윈 스컬지의 적수가 아니야!', `MaleText_loc4`='哈哈哈，你们的卫兵比天灾军团差远啦！', `MaleText_loc5`='哈哈哈，你的守衛根本無法跟天譴軍團相提並論!', `MaleText_loc7`='¡Ja, ja, ja! ¡Sus guardias no poder con la Plaga!' WHERE `ID`=12328;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음? 여기는 낙스라마스가 아니잖아! 크흐흐... 마음에 들지 않아... 모두 파괴하겠다!', `MaleText_loc4`='什么？这里不是纳克萨玛斯！我们不喜欢这里……毁灭一切！', `MaleText_loc5`='什麼?這不是納克薩瑪斯!我們不喜歡這個地方...摧毀!', `MaleText_loc7`='¿Qué? ¡Esto no Naxxramas! Nosotros no gustar este lugar... ¡Destruir!' WHERE `ID`=12329;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희는 병력을 아껴야 하지만 우리는 죽음의 요새에서 스컬지 만들어낸다.', `MaleText_loc4`='你是来贡献憎恶零件的吧。有了你的尸体，浮空城里就能组出更多憎恶啦！', `MaleText_loc5`='你的備用零件!我們在亡域要做更多的天譴軍團。', `MaleText_loc7`='¡Repuestos! Nosotros hacer más miembros de la Plaga en necrópolis.' WHERE `ID`=12330;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나의 왕궁을 더럽힌 스컬지가 사라졌군. 그대들은 가도 좋다.', `FemaleText_loc4`='进攻王廷的天灾士兵已经完全被消灭了。你可以去做你自己的事情了。', `FemaleText_loc5`='攻擊我軍隊的天譴軍團已經完全殲滅了。你趕快去幫忙你自己的部份。', `FemaleText_loc7`='Hemos detenido el ataque de la Plaga a mi corte. Tú ocúpate de tus asuntos.' WHERE `ID`=12331;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나의 왕실근위병이여, 그대들의 소임을 다해 이 사태를 해결하라. 그렇지 않으면 뼈저리게 후회하게 될 거다!', `FemaleText_loc4`='我的皇家卫士们，解决掉眼前的这些入侵者。不然你们的麻烦就不止这么点了。', `FemaleText_loc5`='我的皇家恐怖衛士，你要依照最適當的情況來部署軍隊。你一定會慶幸你有照做。', `FemaleText_loc7`='Guardia real del Terror, ocupaos de este tema y saldréis beneficiados. Si no lo hacéis, os arrepentiréis de ello.' WHERE `ID`=12332;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공포근위병, 물러서지 마라. 스컬지의 전진을 막아야 한다!', `MaleText_loc4`='恐怖卫士，守住防线！阻止天灾军继续前进！', `MaleText_loc5`='恐怖衛士，你要撐住。不要讓天譴軍團攻進來!', `MaleText_loc7`='¡Guardia del Terror, mantened la línea! ¡Detened el avance de la Plaga!' WHERE `ID`=12333;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하수구에 스컬지다! 도와줘!', `MaleText_loc4`='天灾正在进攻下水道！我们需要援助！', `MaleText_loc5`='天譴軍團在地下道!我們需要幫助!', `MaleText_loc7`='¡Fuerza a la Horda vil!' WHERE `ID`=12334;
