UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왕실 입구에 스컬지가 나타났다! 놈들을 처치하라!', `MaleText_loc4`='天灾军团出现在皇家区入口！消灭他们！', `MaleText_loc5`='天譴軍團就在皇家區的入口處!殺光他們!!', `MaleText_loc7`='¡La Plaga está a las puertas del Barrio Real! ¡Matadlos!', `FemaleText_loc1`='왕실 입구에 스컬지가 나타났다! 놈들을 처치하라!', `FemaleText_loc4`='天灾军团出现在皇家区入口！消灭他们！', `FemaleText_loc5`='天譴軍團就在皇家區的入口處!殺光他們!!', `FemaleText_loc7`='¡La Plaga está a las puertas del Barrio Real! ¡Matadlos!' WHERE `ID`=12337;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 무기를 떨어뜨립니다.', `MaleText_loc4`='%s扔掉武器。', `MaleText_loc5`='%s放下它的武器。', `MaleText_loc7`='%s deja caer el arma.' WHERE `ID`=12338;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='육안으로는 볼 수 없지만 우리의 성소는 대지를 가로지르는 지맥에서 비전 마력을 빨아들입니다.$B$B태양샘이 사라진 후 성소는 우리에게 안정적으로 마력을 공급해주는 원천의 역할을 하고 있습니다.', `MaleText_loc4`='我们的圣殿正从魔网中吸取着奥术能量，那些能量线贯穿我们的大地，是肉眼无法看到的。$B$B由于太阳之井的毁灭，它们为我们提供了一个稳定而又可靠的能量来源。', `MaleText_loc5`='橫跨這片土地上有肉眼不能見到的能量界線洪流，我們的聖所就是從那裡虹吸秘法能量。$B$B在太陽之井消逝之後，它們提供了我們穩定可靠的能量來源。', `MaleText_loc7`='Nuestros sagrarios obtienen el poder de las corrientes de líneas-Ley que cruzan nuestras tierras, invisibles a simple vista.$b$bAhora que ha desaparecido La Fuente del Sol, nos proporcionan una fuente de energía continua y fiable.' WHERE `ID`=12339;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='산들바람 마을이 아직 건재하다는 사실은 우리 종족의 근성이 강력하다는 증거입니다. 우리가 스컬지에게 또다시 패하는 일은 절대 없을 겁니다.', `MaleText_loc4`='晴风村仍然存在，这是对我们种族坚韧不屈的精神的证明。我们绝不让步，直到永远地击败天灾军团。', `MaleText_loc5`='晴風村仍然存在對我們種族的堅毅而言是一種信仰聲明。我們絕不能容許再被天譴軍團給擊敗。', `MaleText_loc7`='El hecho de que la Aldea Brisa Pura siga en pie es una prueba irrefutable de la tenacidad de nuestra raza. Nunca más concederemos la derrota a la Plaga.' WHERE `ID`=12340;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비켜, 이 비열한 놈아! 레빌가즈가 교수형은 면하게 해줬지만 아마도 난 그에 못지않은 끔찍한 벌을 받게 될 것 같단 말이야.', `MaleText_loc4`='让开，你这败狗！就算是里维加兹饶恕了我，不送我上绞刑架，我也感觉我的报应就快要来了。', `MaleText_loc5`='肯威，你這下流的傢伙!里維加茲讓我免於絞刑架的懲罰但我的刑罰也好不到哪裡去。', `MaleText_loc7`='¡Abrid paso, escoria! Revilgaz me ha librado de la horca pero el castigo no será mucho mejor.', `FemaleText_loc1`='비켜, 이 비열한 놈아! 레빌가즈가 교수형은 면하게 해줬지만 아마도 난 그에 못지않은 끔찍한 벌을 받게 될 것 같단 말이야.', `FemaleText_loc4`='让开，你这败狗！就算是里维加兹饶恕了我，不送我上绞刑架，我也感觉我的报应就快要来了。', `FemaleText_loc5`='肯威，你這下流的傢伙!里維加茲讓我免於絞刑架的懲罰但我的刑罰也好不到哪裡去。', `FemaleText_loc7`='¡Abrid paso, escoria! Revilgaz me ha librado de la horca pero el castigo no será mucho mejor.' WHERE `ID`=12341;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 도망가? 우리 너 시체로 스컬지 만들 거야.', `MaleText_loc4`='为什么要跑？我们会让你的尸体加入天灾军团的。', `MaleText_loc5`='你為什麼要逃跑?我們要把你變成天譴軍團的一員。', `MaleText_loc7`='¿Por qué huyes? Nosotros te convertiremos en uno más de la Plaga.' WHERE `ID`=12342;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='걱정마라... 으흐흐... 네놈들을 찾아주마.', `MaleText_loc4`='别担心，我们找到你了。', `MaleText_loc5`='別擔心，我們找到你了。', `MaleText_loc7`='No te preocupes, nosotros encontrarte.' WHERE `ID`=12343;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='문제를 일으키지 않는 게 좋을 텐데요, $n 씨!', `FemaleText_loc4`='你最好别找麻烦，$n！', `FemaleText_loc5`='你最好別惹麻煩，$n!', `FemaleText_loc7`='¡Será mejor que no causes problemas, $n!' WHERE `ID`=12344;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일로 오셨나요, $n? 어서 말씀해 보세요. 전 그리 한가하지 않아서요!', `MaleText_loc4`='我能为你做些什么吗，$n？快说，我时间可不多。', `MaleText_loc5`='我能為你做些什麼，$n?快點說，我很忙!', `MaleText_loc7`='¿En qué puedo ayudarte, $n? ¡Rápido, no tengo todo el día!' WHERE `ID`=12345;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 도와 드릴까요? 아니, 잠깐! 제게는 뭘 해 주실 수 있죠?', `MaleText_loc4`='我能为你做些什么吗？不，等等！你能为我做些什么？', `MaleText_loc5`='我能為你做些什麼?不，等等!你能為我做些什麼?', `MaleText_loc7`='¿En qué puedo ayudarte? ¡No, espera! ¿En qué puedes ayudarme tú a mí?' WHERE `ID`=12346;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 역겨운 위액 덩어리를 내뿜습니다!', `MaleText_loc4`='%s从体内喷出了一只恶心的胆汁软泥怪！', `MaleText_loc5`='%s打嗝嘔出了一隻令人噁心的膽汁淤泥怪!', `MaleText_loc7`='%s escupe un barroso de bilis.' WHERE `ID`=12347;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 주위의 모든 좀비를 먹어치웁니다!', `MaleText_loc4`='%s吞食了周围所有的僵尸！', `MaleText_loc5`='%s吞食了眼前所有殭屍!', `MaleText_loc7`='¡%s devora a todos los zombis que están a su alcance!' WHERE `ID`=12348;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰파이크 군대가 사령관의 함성을 얻습니다.', `MaleText_loc4`='雷矛军队得到了将军的怒吼。', `MaleText_loc5`='雷矛部族的軍隊獲得了將軍的戰嚎。', `MaleText_loc7`='Las tropas Pico Tormenta obtienen el Grito de Guerra del General.' WHERE `ID`=12349;
