UPDATE `locales_broadcast_text` SET `MaleText_loc1`='포로는 필요 없다! 우리 땅에서 이교도들을 몰아내라!', `MaleText_loc4`='不留俘虏！把这些异教徒都杀光！', `MaleText_loc5`='不要俘虜!把這些異教徒趕出我們的土地!', `MaleText_loc7`='¡Ejecutad a todos los prisioneros! ¡Expulsad a estos infieles de nuestras tierras!' WHERE `ID`=12351;
