UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스컬지다! 죽여라!', `MaleText_loc4`='我看见了一个天灾士兵！杀了它！', `MaleText_loc5`='我看到了一個天譴軍團!殺了它!', `MaleText_loc7`='¡He visto a un miembro de la Plaga! ¡Mátalo!', `FemaleText_loc1`='스컬지다! 죽여라!', `FemaleText_loc4`='我看见了一个天灾士兵！杀了它！', `FemaleText_loc5`='我看到了一個天譴軍團!殺了它!', `FemaleText_loc7`='¡He visto a un miembro de la Plaga! ¡Mátalo!' WHERE `ID`=12356;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 소리 들었나? 저기 스컬지다!', `MaleText_loc4`='你看到了吗？那边有天灾士兵！', `MaleText_loc5`='你有看到嗎?那裡有個天譴軍團的人!', `MaleText_loc7`='¿Has visto eso? ¡Hay un miembro de la Plaga por allí!', `FemaleText_loc1`='이 소리 들었나? 저기 스컬지다!', `FemaleText_loc4`='你看到了吗？那边有天灾士兵！', `FemaleText_loc5`='你有看到嗎?那裡有個天譴軍團的人!', `FemaleText_loc7`='¿Has visto eso? ¡Hay un miembro de la Plaga por allí!' WHERE `ID`=12357;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 이 안을 날뛰는 스컬지를 해치울 방법이 없을까?!', `MaleText_loc4`='这里面到处都是天灾肆虐，我要怎么做事呀？', `MaleText_loc5`='天譴軍團在這裡到處亂竄我要怎麼完成任何事情?', `MaleText_loc7`='¿Cómo voy a acabar mi trabajo con todos esos miembros de la Plaga pululando por ahí?', `FemaleText_loc1`='아, 이 안을 날뛰는 스컬지를 해치울 방법이 없을까?!', `FemaleText_loc4`='这里面到处都是天灾肆虐，我要怎么做事呀？', `FemaleText_loc5`='天譴軍團在這裡到處亂竄我要怎麼完成任何事情?', `FemaleText_loc7`='¿Cómo voy a acabar mi trabajo con todos esos miembros de la Plaga pululando por ahí?' WHERE `ID`=12358;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기! 스컬지 한 놈이 나타났다!', `MaleText_loc4`='天灾士兵！在那边！', `MaleText_loc5`='那裡還有一個天譴軍團的人，就在那裡!', `MaleText_loc7`='¡Hay un miembro de la Plaga justo allí!', `FemaleText_loc1`='저기! 스컬지 한 놈이 나타났다!', `FemaleText_loc4`='天灾士兵！在那边！', `FemaleText_loc5`='那裡還有一個天譴軍團的人，就在那裡!', `FemaleText_loc7`='¡Hay un miembro de la Plaga justo allí!' WHERE `ID`=12359;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상황이 돌이킬 수 없게 됐군. 스컬지 주제에 감히 언더시티를 공격하다니! 더 몰려오기 전에 해치워라!', `MaleText_loc4`='太不知好歹了。天灾军团怎么有胆来进攻幽暗城！消灭它们！', `MaleText_loc5`='這太誇張了。天譴軍團竟然敢攻擊幽暗城!在更多敵軍趕來之前殺了它們!', `MaleText_loc7`='Esto ha llegado demasiado lejos. ¡Cómo osa la Plaga atacar Entrañas! ¡Destruidlos antes de que vengan más!', `FemaleText_loc1`='상황이 돌이킬 수 없게 됐군. 스컬지 주제에 감히 언더시티를 공격하다니! 더 몰려오기 전에 해치워라!', `FemaleText_loc4`='太不知好歹了。天灾军团怎么有胆来进攻幽暗城！消灭它们！', `FemaleText_loc5`='這太誇張了。天譴軍團竟然敢攻擊幽暗城!在更多敵軍趕來之前殺了它們!', `FemaleText_loc7`='Esto ha llegado demasiado lejos. ¡Cómo osa la Plaga atacar Entrañas! ¡Destruidlos antes de que vengan más!' WHERE `ID`=12360;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 무자비한 놈들의 침략은 결코 멈추지 않는 것인가?', `MaleText_loc4`='这无穷无尽的天灾军团什么时候才会停止进攻？', `MaleText_loc5`='這些無情的天譴軍團攻擊會永無止境嗎?', `MaleText_loc7`='¿Acabarán algún día los implacables ataques de la Plaga?', `FemaleText_loc1`='저 무자비한 놈들의 침략은 결코 멈추지 않는 것인가?', `FemaleText_loc4`='这无穷无尽的天灾军团什么时候才会停止进攻？', `FemaleText_loc5`='這些無情的天譴軍團攻擊會永無止境嗎?', `FemaleText_loc7`='¿Acabarán algún día los implacables ataques de la Plaga?' WHERE `ID`=12361;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 늦기 당장 스컬지 침략자들을 해치우자!', `MaleText_loc4`='现在还来得及，消灭全部天灾入侵者！', `MaleText_loc5`='殺了天譴軍團入侵者，趁現在還來的及!', `MaleText_loc7`='¡Destruye al invasor de la Plaga antes de que sea demasiado tarde!', `FemaleText_loc1`='더 늦기 당장 스컬지 침략자들을 해치우자!', `FemaleText_loc4`='现在还来得及，消灭全部天灾入侵者！', `FemaleText_loc5`='殺了天譴軍團入侵者，趁現在還來的及!', `FemaleText_loc7`='¡Destruye al invasor de la Plaga antes de que sea demasiado tarde!' WHERE `ID`=12362;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='히드락시스 군주여, 이 불변의 정수를 갖고 싶습니다.', `MaleText_loc4`='我想要这个永恒精萃，海达克西斯公爵。', `MaleText_loc5`='我渴望這個永恆精華，海達克西斯公爵。', `MaleText_loc7`='Deseo la quintaesencia eterna, Duque Hydraxis.', `FemaleText_loc1`='히드락시스 군주여, 이 불변의 정수를 갖고 싶어요.', `FemaleText_loc4`='我想要这个永恒精萃，海达克西斯公爵。', `FemaleText_loc5`='我渴望這個永恆精華，海達克西斯公爵。', `FemaleText_loc7`='Deseo la quintaesencia eterna, Duque Hydraxis.' WHERE `ID`=12363;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너는 충성을 다해 우리의 과업을 위해 헌신했다. $n, 너에게 무한한 힘의 원천인 불변의 정수를 주마.', `MaleText_loc4`='你做得很好，并体现出了极大的忠诚，$n。请允许我向你展示我们的永恒精萃。', `MaleText_loc5`='你對我們的事業付出了相當大的忠誠，$n。請讓我帶你瞧瞧我們永無止境的元素精華來源。', `MaleText_loc7`='Has servido a nuestra causa con gran lealtad, $n. Permíteme que te haga entrega de una fuente inagotable de nuestra quintaesencia elemental.' WHERE `ID`=12364;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 와라. $n, 라그나로스를 상대로 우리의 소중한 동맹임을 증명했다. 언제라도 너는 우리의 환영을 받을 것이다.', `MaleText_loc4`='欢迎回来，$n。你已经在对抗拉格纳罗斯的战争中向我们展示了你的价值，你将永远受到我们的欢迎。', `MaleText_loc5`='歡迎回來，$n。你是個對付拉格納羅斯的忠誠盟友，我們永遠歡迎你。', `MaleText_loc7`='¡$gBienvenido:Bienvenida; de nuevo, $n! Has prestado tu valiosa ayuda en la lucha contra Ragnaros y siempre serás bien $grecibido:recibida; entre nosotros.' WHERE `ID`=12365;
