UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스컬지다! 죽여라!', `MaleText_loc4`='我看见了一个天灾士兵！杀了它！', `MaleText_loc5`='我看到了一個天譴軍團!殺了它!', `MaleText_loc7`='¡He visto a un miembro de la Plaga! ¡Mátalo!', `FemaleText_loc1`='스컬지다! 죽여라!', `FemaleText_loc4`='我看见了一个天灾士兵！杀了它！', `FemaleText_loc5`='我看到了一個天譴軍團!殺了它!', `FemaleText_loc7`='¡He visto a un miembro de la Plaga! ¡Mátalo!' WHERE `ID`=12367;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 봤습니까? 믿을 수가 없군요. 스톰윈드에 스컬지가 나타났습니다!', `MaleText_loc4`='你看到了吗？那边有天灾！', `MaleText_loc5`='你有看到嗎?那裡有個天譴軍團的人!', `MaleText_loc7`='¿Has visto eso? ¡Hay un miembro de la Plaga por allí!', `FemaleText_loc1`='지금 봤어요? 믿을 수가 없군요. 스톰윈드에 스컬지가 나타났어요!', `FemaleText_loc4`='你看到了吗？那边有天灾！', `FemaleText_loc5`='你有看到嗎?那裡有個天譴軍團的人!', `FemaleText_loc7`='¿Has visto eso? ¡Hay un miembro de la Plaga por allí!' WHERE `ID`=12368;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 안에서 날뛰고 있는 스컬지를 해치울 방법이 없을까요?!', `MaleText_loc4`='这周围到处都是天灾肆虐，我要怎么做事呀？', `MaleText_loc5`='天譴軍團在這裡到處亂竄我要怎麼完成任何事情?', `MaleText_loc7`='¿Cómo voy a acabar mi trabajo con todos esos miembros de la Plaga pululando por ahí?', `FemaleText_loc1`='이 안에서 날뛰고 있는 스컬지를 해치울 방법이 없을까요?!', `FemaleText_loc4`='这周围到处都是天灾肆虐，我要怎么做事呀？', `FemaleText_loc5`='天譴軍團在這裡到處亂竄我要怎麼完成任何事情?', `FemaleText_loc7`='¿Cómo voy a acabar mi trabajo con todos esos miembros de la Plaga pululando por ahí?' WHERE `ID`=12369;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기, 스컬지가 나타났습니다!', `MaleText_loc4`='天灾士兵！在那边！', `MaleText_loc5`='那裡還有一個天譴軍團的人，就在那裡!', `MaleText_loc7`='¡Hay un miembro de la Plaga justo allí!', `FemaleText_loc1`='저기, 스컬지가 나타났어요!', `FemaleText_loc4`='天灾士兵！在那边！', `FemaleText_loc5`='那裡還有一個天譴軍團的人，就在那裡!', `FemaleText_loc7`='¡Hay un miembro de la Plaga justo allí!' WHERE `ID`=12370;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상황이 돌이킬 수 없게 됐군요. 스컬지 주제에 감히 스톰윈드를 공격하다니! 더 몰려오기 전에 해치워야 합니다!', `MaleText_loc4`='太不知好歹了。天灾军团怎么有胆来进攻暴风城！消灭它们！', `MaleText_loc5`='這太誇張了。天譴軍團竟然敢攻擊暴風城!在更多敵軍趕來之前殺了它們!', `MaleText_loc7`='Esto ha llegado demasiado lejos. ¡Cómo osa la Plaga atacar Ventormenta! ¡Destruidlos antes de que vengan más!', `FemaleText_loc1`='상황이 돌이킬 수 없게 됐군요. 스컬지 주제에 감히 스톰윈드를 공격하다니! 더 몰려오기 전에 해치워야 해요!', `FemaleText_loc4`='太不知好歹了。天灾军团怎么有胆来进攻暴风城！消灭它们！', `FemaleText_loc5`='這太誇張了。天譴軍團竟然敢攻擊暴風城!在更多敵軍趕來之前殺了它們!', `FemaleText_loc7`='Esto ha llegado demasiado lejos. ¡Cómo osa la Plaga atacar Ventormenta! ¡Destruidlos antes de que vengan más!' WHERE `ID`=12371;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 저 불경한 스컬지의 침공은 결코 멈추지 않는 건가요?', `MaleText_loc4`='这无穷无尽的天灾军团什么时候才会停止进攻？', `MaleText_loc5`='這些無情的天譴軍團攻擊會永無止境嗎?', `MaleText_loc7`='¿Acabarán algún día los implacables ataques de la Plaga?', `FemaleText_loc1`='아, 저 불경한 스컬지의 침공은 결코 멈추지 않는 건가요?', `FemaleText_loc4`='这无穷无尽的天灾军团什么时候才会停止进攻？', `FemaleText_loc5`='這些無情的天譴軍團攻擊會永無止境嗎?', `FemaleText_loc7`='¿Acabarán algún día los implacables ataques de la Plaga?' WHERE `ID`=12372;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 늦기 전에 당장 스컬지 침략자를 해치워야 합니다!', `MaleText_loc4`='现在还来得及，消灭全部天灾入侵者！', `MaleText_loc5`='殺了天譴軍團入侵者，趁現在還來的及!', `MaleText_loc7`='¡Destruye al invasor de la Plaga antes de que sea demasiado tarde!', `FemaleText_loc1`='더 늦기 전에 당장 스컬지 침략자를 해치워야 해요!', `FemaleText_loc4`='现在还来得及，消灭全部天灾入侵者！', `FemaleText_loc5`='殺了天譴軍團入侵者，趁現在還來的及!', `FemaleText_loc7`='¡Destruye al invasor de la Plaga antes de que sea demasiado tarde!' WHERE `ID`=12373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런, 우리 중에 죽은 자가 돌아다닙니다!', `MaleText_loc4`='死者就行走在我们中间！', `MaleText_loc5`='亡靈就在我們之中!', `MaleText_loc7`='¡La muerte está entre nosotros!', `FemaleText_loc1`='이런, 우리 중에 죽은 자가 돌아다녀요!', `FemaleText_loc4`='死者就行走在我们中间！', `FemaleText_loc5`='亡靈就在我們之中!', `FemaleText_loc7`='¡La muerte está entre nosotros!' WHERE `ID`=12374;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악마의 물건을 손에 들고 있군, 어리석은 자여! 회개하라!', `MaleText_loc4`='你心中有邪恶之念，蠢货！悔改吧！', `MaleText_loc5`='你手中握著的是惡魔，笨蛋!懺悔吧!', `MaleText_loc7`='¡Portas el mal en tus manos, idiota! ¡ARREPIÉNTENTE!', `FemaleText_loc1`='악마의 물건을 손에 들고 있군, 어리석은 자여! 회개하라!', `FemaleText_loc4`='你心中有邪恶之念，蠢货！悔改吧！', `FemaleText_loc5`='你手中握著的是惡魔，笨蛋!懺悔吧!', `FemaleText_loc7`='¡Portas el mal en tus manos, idiota! ¡ARREPIÉNTENTE!' WHERE `ID`=12375;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$r|1이여;여;, 넌 우리 모두를 위협하고 있다! 너 같은 자는 반드시 사라져야 해!', `MaleText_loc4`='你的冒险会让我们全部遭受毁灭的命运，$r！必须有人阻止你！', `MaleText_loc5`='你冒險摧毀我們所有人，$r!我們一定要結束你的生命!', `MaleText_loc7`='¡Corres el riesgo de destruirnos a todos, $r! ¡Debes morir!', `FemaleText_loc1`='$r|1이여;여;, 넌 우리 모두를 위협하고 있다! 너 같은 자는 반드시 사라져야 해!', `FemaleText_loc4`='你的冒险会让我们全部遭受毁灭的命运，$r！必须有人阻止你！', `FemaleText_loc5`='你冒險摧毀我們所有人，$r!我們一定要結束你的生命!', `FemaleText_loc7`='¡Corres el riesgo de destruirnos a todos, $r! ¡Debes morir!' WHERE `ID`=12376;
