UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 세계를 구원하고 정화하기 위해 왔습니까?', `MaleText_loc4`='你是要来拯救世界的吗？要净化这一切？', `MaleText_loc5`='你是來拯救這個世界的嗎?來淨化世界?', `MaleText_loc7`='¿Has venido a salvar este mundo? ¿A purificarlo?', `FemaleText_loc1`='이 세계를 구원하고 정화하기 위해 왔나요?', `FemaleText_loc4`='你是要来拯救世界的吗？要净化这一切？', `FemaleText_loc5`='你是來拯救這個世界的嗎?來淨化世界?', `FemaleText_loc7`='¿Has venido a salvar este mundo? ¿A purificarlo?' WHERE `ID`=12381;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 이교도의 세상을 정화하는 모습을 볼 수 있도록 제게 긴 생명을 허락해 주십시오.', `MaleText_loc4`='$g阁下:女士;，请您允许我穷尽后半生，注视着您净化这世间一切邪恶。', `MaleText_loc5`='我的$g大人:女士;，請讓我見證你淨化這世界的異教徒。', `MaleText_loc7`='Mi $gseñor:señora;, déjame seguir con vida para ver cómo expulsas a los infieles de este mundo.', `FemaleText_loc1`='당신이 이교도의 세상을 정화하는 모습을 볼 수 있도록 제게 긴 생명을 허락해 주세요.', `FemaleText_loc4`='$g阁下:女士;，请您允许我穷尽后半生，注视着您净化这世间一切邪恶。', `FemaleText_loc5`='我的$g大人:女士;，請讓我見證你淨化這世界的異教徒。', `FemaleText_loc7`='Mi $gseñor:señora;, déjame seguir con vida para ver cómo expulsas a los infieles de este mundo.' WHERE `ID`=12382;
