UPDATE `locales_broadcast_text` SET `MaleText_loc1`='복종하라! 파멸의 인도자 앞에 무릎을 꿇어라! 형제자매들이여, 새로운 새벽이 밝아 오고 있다! 선택받은 자를 통해 더러운 이 세상에 우리의 뜻을 전할 것이다!', `MaleText_loc4`='鞠躬！在灰烬使者的面前叩首！兄弟们，姐妹们，新的黎明已经到来！我们的意志将被这位天选之人送达世界的每一个角落！', `MaleText_loc5`='深深鞠躬!在灰燼使者前跪下!一個新的開端接近了，兄弟姐妹們!我們的訊息會被選中的子民帶到世界的骯髒處!', `MaleText_loc7`='¡Doblegaos! ¡Arrodillaos ante la Crematoria! ¡Se aproxima un nuevo amanecer, hermanos y hermanas! ¡Propagaremos nuestro mensaje a través del elegido!' WHERE `ID`=12389;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 당신에게 제 아버지의 검이 있군요. 제 군대는 당신의 것입니다. 데리고 가십시오... 그들을 이끌어 이 땅에서 더러움을 몰아내십시오. 타락한 자들을 정화해야만 합니다.', `MaleText_loc4`='您握着我父亲的剑，$n。我的士兵将听从您的命令，$g阁下:女士;。请您带上他们，领导他们，净化一切邪恶的势力。天灾军团必须被彻底消除！', `MaleText_loc5`='你握著我父親的劍，$n。我的士兵們任你差遣，我的$g大人:女士;。帶著他們...領導他們...一定要洗淨他們的不潔。一定要淨化他們的污點。', `MaleText_loc7`='Portas la espada de mi padre, $n. Mis Soldados están ahora bajo tu mando, mi $gseñor:señora;. Cógelos... Dirígelos... Hemos de acabar con los impuros. Han de ser liberados de la peste que los contamina.' WHERE `ID`=12390;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 켈투자드가 죽는 것을 보더니 달아납니다!', `MaleText_loc4`='看见克尔苏加德倒下，%s转身便逃！', `MaleText_loc5`='%s看到科爾蘇加德陣亡後逃跑!', `MaleText_loc7`='¡%s se escapa al ver a Kel''Thuzad caer!' WHERE `ID`=12391;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='Phase 3! <PH>', `MaleText_loc4`='Phase 3! <PH>', `MaleText_loc5`='前進 3! <PH>', `MaleText_loc7`='Phase 3! <PH>' WHERE `ID`=12392;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가시죠.', `FemaleText_loc4`='出发吧。', `FemaleText_loc5`='我們走。', `FemaleText_loc7`='Vamos.' WHERE `ID`=12393;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다르칸은 싸워 보지도 않고 우리가 스컬지에게 굴복할 것이라고 생각합니다. $n, 우리는 그가 틀렸다는 사실을 증명할 것입니다.', `MaleText_loc4`='达尔坎认为亡灵天灾不费吹灰之力就能击败我们。他错了，$n。', `MaleText_loc5`='達克汗認為我們會還沒開戰就被天譴軍團給擊敗。我們一定要讓他知道他是錯的，$n。', `MaleText_loc7`='Dar''Khan cree que nos rendiremos ante la Plaga sin oponer resistencia. Le demostraremos que se equivoca, $n.' WHERE `ID`=12394;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 숙녀분께 말을 걸어보려고 애쓰던 중이었는데 안 보이셨나요? 뭐, 괜찮습니다. 어차피 오늘 밤 선약이 있는 듯하니까요.$B$B저는 국산과 수입품 포도주를 모두 판매하는 데 최고급이 아니면 취급하지 않습니다. 한 번 보시겠습니까?', `MaleText_loc4`='没瞧见我正准备跟这位女士讲话吗？哦，好吧，她似乎很忙。$B$B我出售来自本土和异域的葡萄酒。要看看吗？', `MaleText_loc5`='你沒看到我正在和這位小姐說話嗎?喔，非常好，反正她看起來有點忙。$B$B我只賣最好的酒，國外和國內的葡萄酒都有。要看一看嗎?', `MaleText_loc7`='¿No ves que estoy intentando mantener una conversación con la dama? Oh, muy bien, de todos modos parece preocupada.$B$BSolo ofrezco las mejores bebidas, tanto de cosecha local como de procedencia exótica. ¿Quieres echar un vistazo?' WHERE `ID`=12395;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살데릴의 안식처에서 요청한 물품 목록입니까? 그분이라면 제가 가진 최고급 제품을 요청하실 만합니다. 아, 살데릴 경의 친구분들께도 최고급 포도주를 특별 가격에 드리겠습니다.', `MaleText_loc4`='从萨瑟利尔庄园来的订单？显然，萨瑟利尔大人需要一瓶我的美酒。而且，男爵的朋友都能享受特别的折扣。', `MaleText_loc5`='那是薩瑟里避難所的清單嗎?沒問題，他的身分地位可以獲得一瓶最好的酒。當然，任何薩瑟里領主的朋友都可以特殊的價格買到這樣上好的葡萄酒。', `MaleText_loc7`='¿Es eso una lista del Refugio de Saltheril? Sin duda, su señoría necesitará una botella de mi mejor calidad. Y, por supuesto, cualquier amigo de Lord Saltheril merece un precio especial por un añejo tan excelente.' WHERE `ID`=12397;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 스컬지와의 전투에서 몇 번이나 이겼습니까?', `MaleText_loc4`='我们赢下多少场战斗了？', `MaleText_loc5`='我們贏了幾場戰役?', `MaleText_loc7`='¿Cuántas batallas hemos ganado?', `FemaleText_loc1`='우리가 스컬지와의 전투에서 몇 번이나 이겼나요?', `FemaleText_loc4`='我们赢下多少场战斗了？', `FemaleText_loc5`='我們贏了幾場戰役?', `FemaleText_loc7`='¿Cuántas batallas hemos ganado?' WHERE `ID`=12398;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 스컬지를 상대로 $2219W번의 전투에서 승리했습니다. 긴장을 늦추지 마십시오, $n. 이 전쟁이 끝나려면 아직 멀었습니다.', `MaleText_loc4`='我们已经赢得了$2219W场对天灾军团战役的胜利。要有心理准备，$n！战争还远未结束。', `MaleText_loc5`='我們贏了天譴軍團$2219W場戰役。做好準備，$n，這場戰爭要結束還差的遠了。', `MaleText_loc7`='Hemos ganado $2219W batallas contra la Plaga. Prepárate, $n, pues esta guerra no ha hecho más que comenzar.' WHERE `ID`=12399;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='돈을 조금 지니고 계신다면 그대의 식욕을 돋울 만한 음식과 음료를 드릴 수 있습니다. 코퍼만이 이곳 산장을 최고의 모습으로 유지해 드리지요.', `FemaleText_loc4`='如果你有钱，我保证你对我提供的食品和饮料都很满意，每个铜币都物有所值！', `FemaleText_loc5`='如果你有錢，我有讓你滿足口腹之慾的食物和飲料。所有的錢都會拿來讓這地方維持在最佳狀態。', `FemaleText_loc7`='Si tienes dinero, tengo comida y bebida para satisfacer tu apetito. Todo el dinero se destina a mantener el Retiro en plena forma.' WHERE `ID`=12400;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='살데릴 경께서 부탁한 목록입니까? 잘 됐군요. 방금 요리한 전채 요리를 꽤 많이 팔 수 있겠습니다.', `FemaleText_loc4`='你拿着的是萨瑟利尔男爵的清单？当然，我可以卖给你一些刚出炉的新鲜美味。', `FemaleText_loc5`='你手上的是薩瑟里領主的清單嗎?好的，我可以賣給你一批開胃菜，剛出爐的。', `FemaleText_loc7`='¿Eso que llevas ahí es una lista de Lord Saltheril? Sí, te puedo vender un lote de aperitivos, recién sacados del fuego.' WHERE `ID`=12401;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 스컬지를 상대로 $2219W번의 전투에서 승리했습니다. 기운을 내십시오, $n! 아직 많은 전투가 남았지만 전 세계의 영웅들이 그들과 싸우기 위해 일어섰습니다.', `MaleText_loc4`='我们已经赢得了$2219W场对天灾军团战役的胜利。努力，$n！还有几百场战斗等待着我们，各地的英雄们会来支援我们，与天灾作战。', `MaleText_loc5`='我們贏了天譴軍團$2219W場戰役。用心，$n。前方還有很多戰役等著我們，英雄，所有伺服器的英雄們都已做好準備要與他們奮戰了。', `MaleText_loc7`='Hemos ganado $2219W batallas contra la Plaga. Levanta el ánimo, $n. Aunque quedan muchas batallas por delante, hay héroes de todos los reinos dispuestos a librarlas.' WHERE `ID`=12402;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 스컬지를 상대로 $2219W번의 전투에서 승리했습니다. 조금만 더 버티십시오, $n! 이 역경을 이겨내야 합니다!', `MaleText_loc4`='我们已经赢得了$2219W场对天灾军团战役的胜利。坚持住，$n！我们一定能活下来的！', `MaleText_loc5`='我們贏了天譴軍團$2219W場戰役。堅持下去，$n!我們一定要不屈不撓!', `MaleText_loc7`='Hemos ganado $2219W batallas contra la Plaga. ¡Aguanta, $n! ¡Debemos perseverar!' WHERE `ID`=12403;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기에는 없는 물건이 없습니다. 천천히 둘러보십시오.', `MaleText_loc4`='我出售各种货物，$c。过来看看吧。', `MaleText_loc5`='我出售各式各樣的物品，$c。隨意看看。', `MaleText_loc7`='Tengo todo tipo de artículos a la venta, $c. Echa un vistazo.' WHERE `ID`=12404;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='목록을 가져오셨나요? 재미있군요. 아, 그래요. 살데릴 경 앞으로 온 폭죽이 있지만 아직 대금을 받지 못했습니다. 그분 대신 구입하러 오셨나요?', `MaleText_loc4`='订单……真有趣。哦，这是萨瑟利尔男爵的焰火订单吧。他还没付钱呢。你要替他先付清吗，$c？', `MaleText_loc5`='一個清單...好奇怪。啊對了，薩瑟里領主的煙火。他還沒付帳;你是代表他來這裡的嗎，$c?', `MaleText_loc7`='Una lista... qué curioso. Ah, sí, el envío de fuegos artificiales para Lord Saltheril. No los ha pagado; ¿has venido a comprarlos en su nombre, $c?' WHERE `ID`=12405;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='언데드 무리의 침략이 언제까지 계속될까요? 구울이나 해골 한 놈을 해치우면 꼭 두 놈이 나타나는 것 같습니다.', `FemaleText_loc4`='是不是那些亡灵永远都杀不光？好像我们每干掉一个骷髅和食尸鬼，就会有两个补上来。', `FemaleText_loc5`='這些不死族永遠不會消失是嗎?好像我們每殺一個食屍鬼或骷髏人，就會再冒出兩個來遞補它的位子。', `FemaleText_loc7`='¿Es que esos no-muertos no tienen fin? Parece como si por cada necrófago o esqueleto que matáramos, dos ocuparan su lugar.' WHERE `ID`=12406;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='Marketing - iCoke Redemption Greeting (S.H.E.)', `FemaleText_loc4`='亲爱的$n，欢迎参加可口可乐魔兽世界“要爽由自己，冰火暴风城II”夏季促销活动！幸运女神的光环再一次眷顾了你，独一无二的神奇礼物不再遥不可及，今天它们都将归属于你！如果你曾经得到过一串用来兑换奖品的神秘字符，就把它告诉我，我会给你一份惊喜的！$B$B幸运正在艾泽拉斯世界散播开来，你感受到了吗？我的勇士，一起来分享这份喜悦吧！$B愿荣誉与你同在！', `FemaleText_loc5`='行銷 - 可口可樂兌換問候語(S.H.E.)', `FemaleText_loc7`='Marketing - iCoke Redemption Greeting (S.H.E.)' WHERE `ID`=12407;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아까 보낸 급사가 어디로 갔지?', `MaleText_loc4`='那个信使在哪里？', `MaleText_loc5`='信差在哪裡?', `MaleText_loc7`='¿Dónde estará ese mensajero?' WHERE `ID`=12408;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실버문에서 가져온 소식은 없나요? 아직도 급사가 도착하지 않았습니다!', `MaleText_loc4`='银月城有什么消息？信使至今未到！', `MaleText_loc5`='銀月城傳來什麼消息?信差遲到了!', `MaleText_loc7`='¿Cómo que noticias de Lunargenta? ¡El mensajero llega tarde!' WHERE `ID`=12409;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='섭정이 보낸 전갈은 어디 있습니까?', `MaleText_loc4`='摄政王的信使在哪儿？', `MaleText_loc5`='攝政王的信差跑哪去了?', `MaleText_loc7`='¿Dónde está el mensajero del Lord regente?' WHERE `ID`=12410;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 하루종일 전갈을 기다리고 있을 시간이 없습니다. 귀부인 아우리페러스께서 시킨 일이 있다고요!', `MaleText_loc4`='我不能在这里干等一整天。奥莉菲洛丝夫人还指派了很多任务给我呢。', `MaleText_loc5`='我沒時間整天都在這裡等待消息。我還有夫人交代的事情要做!', `MaleText_loc7`='No tengo todo el día para esperar aquí ese mensaje. ¡Hay tareas que la Dama Aurífera me ha encomendado!' WHERE `ID`=12411;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간이 지체되고 있습니다. 무슨 이유인지 아직도 실버문에서는 아무런 전갈이 없네요.', `MaleText_loc4`='时不我待。银月城的信使不知何故耽搁了，至今未到。', `MaleText_loc5`='時間越來越晚了。銀月城的訊息一定是因為某個原因耽擱了。', `MaleText_loc7`='Se está haciendo tarde. El mensajero de Ciudad de Lunargenta se está retrasando por algún motivo.' WHERE `ID`=12412;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실버문의 급사가 아직 도착하지 않았습니다. 정찰병을 보내 급사를 찾아봐야 할까요?', `MaleText_loc4`='银月城的信使还没来。或许我该派斥候出去找找。', `MaleText_loc5`='銀月城的信差延誤了。或許我該派個斥候去找他?', `MaleText_loc7`='El mensajero de Ciudad de Lunargenta se está retrasando. ¿Tal vez debería enviar a un explorador a buscarlo?' WHERE `ID`=12413;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 늦는다면 제가 직접 가야할지도 모르겠네요. 어서 칼렉고스의 전갈이 도착해야 할 텐데...', `MaleText_loc4`='真是急死人了，希望卡雷苟斯的信使快点到。', `MaleText_loc5`='我這樣徘徊地走會把路都踏出一條痕跡來。我希望卡雷苟斯的信差快點到來。', `MaleText_loc7`='A este paso voy a echar raíces en este camino. Espero que el mensaje de Kalecgos llegue pronto.' WHERE `ID`=12414;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='급사가 뭘 가져오든 좋은 소식이었으면 좋겠습니다.', `MaleText_loc4`='不知道信使会带来什么消息，希望是好消息吧。', `MaleText_loc5`='不管信差帶來的是什麼消息，我希望都是好消息。', `MaleText_loc7`='Traiga lo que traiga el mensajero, espero que sean buenas noticias.' WHERE `ID`=12415;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 오면서 급사 한 명을 만나지 못했습니까? 실버문의 소식을 기다리는 중인데 아직 전갈이 도착하지 않았습니다!', `MaleText_loc4`='$C，你过来的路上有看到一个信使吗？我们正等着从银月城传来的消息，但他们的信使迟迟未到！', `MaleText_loc5`='$C，你不會剛好在來這裡的路上看到一個信差吧?我們在等待銀月城的消息而他們的信差遲到了!', `MaleText_loc7`='$C, ¿no habrás visto un mensajero cuando venías hacia aquí? ¡Estamos esperando información de Ciudad de Lunargenta y su mensajero llega tarde!' WHERE `ID`=12416;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='공격!', `FemaleText_loc4`='开火！', `FemaleText_loc5`='開火!', `FemaleText_loc7`='¡Abrid fuego!' WHERE `ID`=12417;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='적이다! 무기를 꺼내라!', `FemaleText_loc4`='发现敌人了！准备作战！', `FemaleText_loc5`='瞄準敵人!準備你的武器!', `FemaleText_loc7`='¡Enemigo avistado! ¡Prepara las armas!' WHERE `ID`=12418;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='위치를 사수하라!', `FemaleText_loc4`='坚守阵地！', `FemaleText_loc5`='堅守你的崗位!', `FemaleText_loc7`='¡Mantengan sus posiciones!' WHERE `ID`=12419;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠의 주인께서 너의 부질없는 행동을 눈치채시고 죽음의 메시지를 전하기 위해 날 보내셨다!', `MaleText_loc4`='我们的主人已经注意到了你们这些蟑螂，他要让我毁灭你们！', `MaleText_loc5`='我們的黑暗大師已經注意到你的微不足道，所以派我帶來這個...死亡的訊息!', `MaleText_loc7`='Nuestro maestro oscuro ha advertido tu insignificancia y me envía para entregar un mensaje... ¡de muerte!' WHERE `ID`=12420;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여; 여; 영웅담은 무의미하다. 네 미래는 이미 결정됐다. 네 영혼은 노예가 되리라!', `MaleText_loc4`='你的英雄气概在这里一无是处，$c。你的未来一面死寂，你的灵魂将颤栗着成为我的奴仆！', `MaleText_loc5`='這些英雄事蹟不具任何意義，$c。你的未來已決定而你的靈魂已註定要被奴役!', `MaleText_loc7`='Esas heroicidades no significan nada, $c. ¡Tu futuro está sellado y tu alma está condenada a la servidumbre!' WHERE `ID`=12421;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳의 전투는 전 세계에서 벌어지고 있는 스컬지의 침공의 극히 일부일 뿐이다, 바보 같은 놈! 진정한 힘이 어떤 건지 가르쳐주마!', `MaleText_loc4`='你只不过是这世界上的一粒尘土，你的抗争毫无意义！见识见识我们的力量吧！', `MaleText_loc5`='你在這裡的戰鬥不過是世界入侵行動中最小的一顆塵埃罷了，唉!是讓你見識力量真面目的時候了!', `MaleText_loc7`='¡Esta no es más que una pequeña batalla que forma parte de una gran invasión mundial, enclenque! ¡Ha llegado el momento de que enfrentes al verdadero poder!' WHERE `ID`=12422;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 여기 서서 가끔 호수 뒤편의 숲을 바라보곤 하는데 그럴 때면 대지도... 한때 생명으로 가득한 녹색이었다는 사실을 문득 깨닫고는 하죠.', `MaleText_loc4`='有时候我站在这里，看着河对岸的森林，我仿佛看到了这片土地曾经的容貌……一片充满生机的绿色。', `MaleText_loc5`='有時候我站在這裡，望著湖後面的森林，然後我就會看到大地又變的...綠意盎然充滿生機。', `MaleText_loc7`='A veces me quedo aquí, observando el bosque más allá del lago, y veo la tierra como una vez fuera... verde y llena de vida.' WHERE `ID`=12423;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 냄새나는 그림자소나무 트롤들을 완벽하게 해치울 방법을 찾아야 해!', `MaleText_loc4`='我们必须设法对付那些臭气熏天的暗松巨魔！', `MaleText_loc5`='我們一定得想出個完美的辦法來對付那些臭燻燻的影松食人妖!', `MaleText_loc7`='¡Tenemos que encontrar la manera perfecta de ocuparnos de esos apestosos trols Sombrapino!' WHERE `ID`=12424;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 독약으로 트롤 놈들을 확실하게 해치웠군. 자네는 정말 실력 있는 인재로군!', `MaleText_loc4`='投毒成功，那些巨魔要倒大霉了，$C。你真是个有前途的$G小伙子:姑娘;！', `MaleText_loc5`='我必須說，你將我的毒藥送來還無畏地對付了那些食人妖，$c。你是個相當有天份的年輕$g先生:女士;!', `MaleText_loc7`='Debo decir que administraste mi veneno y te ocupaste de esos trols muy despiadadamente, $c. ¡Tienes mucho talento!' WHERE `ID`=12425;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='Marketing - iCoke Redemption Greeting (S.H.E. non-Quest)', `FemaleText_loc4`='你好啊，在这热力十足的夏天，来和我们一起痛快地跳舞吧！', `FemaleText_loc5`='歡迎來到可口可樂-魔獸世界特別活動!', `FemaleText_loc7`='Marketing - iCoke Redemption Greeting (S.H.E. non-Quest)' WHERE `ID`=12426;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='World of Warcraft and Coca-Cola ® have teamed up to bring you the iCoke-World of Warcraft Summer Promotion. Look for codes under the caps of specially marked bottles of Coca-Cola. Then return here and enter the code to win a virtual item.', `MaleText_loc4`='魔兽世界和可口可乐(R)共同为您带来了这次可口可乐魔兽世界“要爽由自己，冰火暴风城II”夏季促销活动。请检查魔兽世界主题的可口可乐易拉罐底部或瓶装可口可乐的瓶盖内侧，您可以找到一串13位字符。在www.iCoke.cn上输入您得到的13位字符，就有机会赢得iCoke积分，从而得到可以换取魔兽世界幸运礼品的10位电子兑换券。最后，在这里输入您得到的电子兑换券上的10位号码，神秘大奖在等待着您！', `MaleText_loc5`='「魔獸世界成長日誌」是一個專門為您與您的好戰友設計的紀錄活動，您只需要收集:

1. 等級10級或以下，找到您的4位隊友並進行合照。
2. 完成我們所提供的任務後拍照。
3.等級成長至58級後，進入外域，在黑暗之門前面與原隊友合照。

憑此三張照片，您便有機會獲得最珍貴的魚人寶寶。詳情可參照官網活動訊息。', `MaleText_loc7`='World of Warcraft y Coca-Cola (R) se han unido para traerte la promoción de verano iCoke-World of Warcraft. Busca los códigos bajo los tapones de las botellas de Coca-Cola marcadas. Después, vuelve aquí e introduce el código para ganar un objeto virtual.', `FemaleText_loc1`='World of Warcraft and Coca-Cola ® have teamed up to bring you the iCoke-World of Warcraft Summer Promotion. Look for codes under the caps of specially marked bottles of Coca-Cola. Then return here and enter the code to win a virtual item.', `FemaleText_loc4`='魔兽世界和可口可乐(R)共同为您带来了这次可口可乐魔兽世界“要爽由自己，冰火暴风城II”夏季促销活动。请检查魔兽世界主题的可口可乐易拉罐底部或瓶装可口可乐的瓶盖内侧，您可以找到一串13位字符。在www.iCoke.cn上输入您得到的13位字符，就有机会赢得iCoke积分，从而得到可以换取魔兽世界幸运礼品的10位电子兑换券。最后，在这里输入您得到的电子兑换券上的10位号码，神秘大奖在等待着您！', `FemaleText_loc5`='「魔獸世界成長日誌」是一個專門為您與您的好戰友設計的紀錄活動，您只需要收集:

1. 等級10級或以下，找到您的4位隊友並進行合照。
2. 完成我們所提供的任務後拍照。
3.等級成長至58級後，進入外域，在黑暗之門前面與原隊友合照。

憑此三張照片，您便有機會獲得最珍貴的魚人寶寶。詳情可參照官網活動訊息。', `FemaleText_loc7`='World of Warcraft y Coca-Cola (R) se han unido para traerte la promoción de verano iCoke-World of Warcraft. Busca los códigos bajo los tapones de las botellas de Coca-Cola marcadas. Después, vuelve aquí e introduce el código para ganar un objeto virtual.' WHERE `ID`=12427;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈을 꼭 찾고야 말겠다! 애쉬아리 수정을 파괴한 대가를 치르게 될 것이야!', `MaleText_loc4`='我一定会抓到你的，凡人！你们会为破坏阿莎利水晶而付出代价！', `MaleText_loc5`='我會找到你凡人!你會為了摧毀阿莎利水晶付出代價的!', `MaleText_loc7`='¡Os encontraré, mortales! ¡Pagaréis por haber destruido los cristales de Ash''ari!' WHERE `ID`=12428;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈이 다음 먹이가 되겠다니 이런 고마운 일이 있나!', `MaleText_loc4`='谢谢你成为我的下一个祭品！', `MaleText_loc5`='謝謝你成為我的下一個犧牲者!', `MaleText_loc7`='¡Gracias por convertirte en mi siguiente víctima!' WHERE `ID`=12429;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='경계를 늦추지 말아야 합니다! 우리는 배신자 다르칸과 스컬지 그리고 줄아만의 지원을 받는 그림자소나무 트롤들 틈바구니에서 간신히 버티고 있습니다. 전력을 분산시키지 말았어야 했습니다!$B$B그대가 우리를 돕기 위해 오신 분이기를 바랍니다.', `FemaleText_loc4`='我们必须保持警戒的状态，$c！在背叛者达尔坎的天灾部队和祖阿曼的暗松巨魔的夹击下，我们几乎喘不过气来。我们真的不该分散注意力！$B$B我希望你是来这里帮忙的。', `FemaleText_loc5`='我們一定要時時保持高度警惕，$c!因為背叛者達克汗和他的天譴軍團夾攻，加上影松食人妖被祖阿曼的軍隊擊退，我們僅能勉強生存而已。我們實在不該分散注意力的!$B$B我衷心希望你能幫忙我們。', `FemaleText_loc7`='¡Debemos mantener un estado de vigilia, $c! Entre Dar''Khan el Traidor y su Plaga, y los trols Sombrapino respaldados por la fuerza de Zul''Aman, apenas mantenemos la cabeza sobre el agua. ¡No deberíamos estar dividiendo nuestra atención!$B$BEspero que estés aquí para ayudar.' WHERE `ID`=12430;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리를 돕기 위해 오셨다니 정말 반갑습니다. 트롤을 빨리 해치울수록 스컬지들을 원래 있던 자리로 빨리 쫓아낼 수 있습니다.', `FemaleText_loc4`='我很高兴你来这里帮忙，$c。我们越早解决这些巨魔，就能越早去把天灾军团赶回他们来的地方。', `FemaleText_loc5`='我很高興像你這樣的人來幫忙，$c。我們越快對付完這些食人妖，就能越快把天譴軍團趕回他們出生的地方。', `FemaleText_loc7`='Me alegro de que hayas venido a ayudarnos, $c. Cuanto antes nos ocupemos de estos trols, antes podremos dedicarnos a devolver a la Plaga al lugar de donde vino.' WHERE `ID`=12431;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='트롤 한 무리를 해치웠으나 아직 한 무리 더 남았습니다. $n, 그대의 활약에 정말 감사할 따름입니다! 그대가 여기 오기 전에는 우리가 그림자소나무 트롤들을 통제할 수 있으리라는 생각조차 못했습니다.', `FemaleText_loc4`='解决掉一批巨魔，下一批就已经来了。你不知道我对你所做的事情有多么感激，$n！在你来之前，我甚至觉得我们根本无法把这些暗松巨魔给控制住。', `FemaleText_loc5`='已經對付完了一批食人妖，還有一批要繼續。你不知道我有多感激你的幫忙，$n!在你來到這裡之前我根本不相信我們能將影松的麻煩控制住。', `FemaleText_loc7`='Ya nos hemos ocupado de un grupo de trols; falta otro. ¡No tienes idea de cuánto aprecio lo que estás haciendo, $n! Antes de que aparecieras no pensaba que fuéramos a tener nunca bajo control el problema de los Sombrapino.' WHERE `ID`=12432;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='최근까지 우리 오합지졸 병력이 여기에 있었다는 사실이 믿어지십니까? 대부분 도움이 되기보다는 문제를 더 많이 일으킵니다. 그대와는 매우 다릅니다.$B$B그런데 정말로 원정순찰대에 가입하지 않으실 겁니까?', `FemaleText_loc4`='你简直无法想象最近我们都是和怎样一群乌合之众共同渡过的，大部分人简直是来找麻烦而不是帮忙的，完全不像你那样能干。$B$B你确定你不想加入远行者吗？', `FemaleText_loc5`='我真是太感謝你了，$n!你不會相信我們最近在這裡遇到了哪些烏合之眾。他們帶來的不是想像中的幫助而是更多的麻煩。不像你。$B$B你確定你不想和遠行者簽約?', `FemaleText_loc7`='Nunca te imaginarías la multitud que ha pasado por aquí últimamente. La mayoría causan más problemas de los que solucionan. Lo contrario que tú.$B$B¿Seguro que no quieres unirte a los Errantes?' WHERE `ID`=12433;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 스컬지와 싸우는 지역은 어디입니까?', `MaleText_loc4`='我们在哪里与天灾军团开战了呢？', `MaleText_loc5`='我們在哪裡對抗天譴軍團?', `MaleText_loc7`='¿Dónde vamos a enfrentarnos a la Plaga?', `FemaleText_loc1`='우리가 스컬지와 싸우는 지역은 어디인가요?', `FemaleText_loc4`='我们在哪里与天灾军团开战了呢？', `FemaleText_loc5`='我們在哪裡對抗天譴軍團?', `FemaleText_loc7`='¿Dónde vamos a enfrentarnos a la Plaga?' WHERE `ID`=12434;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕은 아제로스의 대도시를 상대로는 소규모 병력만 보냈고, 주요 병력은 다음 도시를 주기적으로 공격하고 있습니다.$B$B아즈샤라, 저주받은 땅, 불타는 평원, 타나리스 사막, 동부 역병지대, 여명의 설원', `MaleText_loc4`='对于艾泽拉斯的各大主城，巫妖王都只派出小股部队进行牵制和骚扰，其主力部队则主要进攻以下地区：$B$B艾萨拉、诅咒之地、燃烧平原、塔纳利斯沙漠、东瘟疫之地和冬泉谷。', `MaleText_loc5`='巫妖王只派了一小批軍力來應付艾澤拉斯的每個主城，他們的主力部隊週期性地攻擊以下的土地:$B$B艾薩拉，詛咒之地，燃燒平原，塔納利斯沙漠，東瘟疫之地和冬泉谷。', `MaleText_loc7`='El Rey Exánime ha enviado pocas tropas a las capitales de Azeroth mientras que el grueso de sus fuerzas ataca periódicamente las siguientes zonas:$B$BAzshara, Las Tierras Devastadas, Las Estepas Ardientes, el Desierto de Tanaris, las Tierras de la Peste del Este y Cuna del Invierno.' WHERE `ID`=12435;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하... 하찮은 $r|1아;야;, 널 해치우고 그 뼈로 전리품을 만들어야겠다!', `MaleText_loc4`='哈哈……我会杀了你这弱小的$r，把你的头骨做成战利品。', `MaleText_loc5`='哈哈... 我要殺了渺小的$r再把你的頭顱做成戰利品!', `MaleText_loc7`='Ja, ja... ¡Voy a matar $gal patético:a la patética; $r y convertir tu calavera en mi trofeo!' WHERE `ID`=12436;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무슨 일로 오셨습니까, $n? 이 부근에는 인적이 매우 드뭅니다. 제가 생각하기에도 그게 당연한 것 같지만요.', `FemaleText_loc4`='是什么风把你吹到这里来的，$n？没有什么人会在这附近出没。我想应该是有什么事吧。', `FemaleText_loc5`='什麼風把你吹來這裡的，$n?我們這附近看不到太多人的。我想，一定是有什麼好理由吧。', `FemaleText_loc7`='¿Qué te trae por aquí, $n? No vemos mucha gente por este lugar. Con razón, supongo.' WHERE `ID`=12437;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대장기술을 배우고 싶어서 오셨나요, 아니면 다른 할 말이라도 있으신가요?', `FemaleText_loc4`='你想学习锻造专业还是有什么其它事情想告诉我？', `FemaleText_loc5`='你是來學習鍛造的專業技能還是有什麼事想告訴我呢?', `FemaleText_loc7`='¿Deseas aprender la profesión de herrero o hay algo más que quieras decirme?' WHERE `ID`=12438;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$g형제여:자매여;, 내 상처는 신경 쓰지 마시오. 우리 드레나이 중에 살아있는 자가 있다는 건 기적이오이다!', `MaleText_loc4`='我的$G兄弟:姐妹;，别在意我的伤。我们能活着就是个奇迹了！', `MaleText_loc5`='別擔心我的傷勢，$g兄弟:姐妹;。我們任何人能活下來都是奇蹟了!', `MaleText_loc7`='No te preocupes por mis heridas, $ghermano:hermana;. ¡Es un milagro que cualquiera de nosotros esté vivo!' WHERE `ID`=12439;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발견! $n|1이;가; 특급 회복 물약 조제법을 발견했습니다!', `MaleText_loc4`='太棒了！$n领悟了超级活力药水的配方！', `MaleText_loc5`='大發現!$n發現了超強效活力藥水的配方!', `MaleText_loc7`='¡DESCUBRIMIENTO! ¡$n ha descubierto la fórmula de la superpoción de rejuvenecimiento!', `FemaleText_loc1`='발견! $n|1이;가; 특급 회복 물약 조제법을 발견했습니다!', `FemaleText_loc4`='太棒了！$n领悟了超级活力药水的配方！', `FemaleText_loc5`='大發現!$n發現了超強效活力藥水的配方!', `FemaleText_loc7`='¡DESCUBRIMIENTO! ¡$n ha descubierto la fórmula de la superpoción de rejuvenecimiento!' WHERE `ID`=12440;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발견! $n|1이;가; 증강의 영약 조제법을 발견했습니다!', `MaleText_loc4`='太棒了！！$n领悟了强固合剂的配方！', `MaleText_loc5`='大發現!$n發現了防禦精鍊藥劑的配方!', `MaleText_loc7`='¡DESCUBRIMIENTO! $n ha descubierto la fórmula del frasco de fortificación.', `FemaleText_loc1`='발견! $n|1이;가; 증강의 영약 조제법을 발견했습니다!', `FemaleText_loc4`='太棒了！！$n领悟了强固合剂的配方！', `FemaleText_loc5`='大發現!$n發現了防禦精鍊藥劑的配方!', `FemaleText_loc7`='¡DESCUBRIMIENTO! $n ha descubierto la fórmula del frasco de fortificación.' WHERE `ID`=12441;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발견! $n|1이;가; 강한 마나 회복의 영약 조제법을 발견했습니다!', `MaleText_loc4`='太棒了！！$n领悟了强效回复合剂的配方！', `MaleText_loc5`='大發現!$n發現了法力恢復精鍊藥劑的配方!', `MaleText_loc7`='¡DESCUBRIMIENTO! $n ha descubierto la fórmula del frasco de restauración poderosa.', `FemaleText_loc1`='발견! $n|1이;가; 강한 마나 회복의 영약 조제법을 발견했습니다!', `FemaleText_loc4`='太棒了！！$n领悟了强效回复合剂的配方！', `FemaleText_loc5`='大發現!$n發現了法力恢復精鍊藥劑的配方!', `FemaleText_loc7`='¡DESCUBRIMIENTO! $n ha descubierto la fórmula del frasco de restauración poderosa.' WHERE `ID`=12442;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발견! $n|1이;가; 가혹한 공격의 영약 조제법을 발견했습니다!', `MaleText_loc4`='太棒了！！$n领悟了无情突袭合剂的配方！', `MaleText_loc5`='大發現!$n發現了強襲精鍊藥劑的配方!', `MaleText_loc7`='¡DESCUBRIMIENTO! $n ha descubierto la fórmula del frasco de asalto incansable!', `FemaleText_loc1`='발견! $n|1이;가; 가혹한 공격의 영약 조제법을 발견했습니다!', `FemaleText_loc4`='太棒了！！$n领悟了无情突袭合剂的配方！', `FemaleText_loc5`='大發現!$n發現了強襲精鍊藥劑的配方!', `FemaleText_loc7`='¡DESCUBRIMIENTO! $n ha descubierto la fórmula del frasco de asalto incansable!' WHERE `ID`=12443;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발견! $n|1이;가; 눈부신 빛의 영약 조제법을 발견했습니다!', `MaleText_loc4`='太棒了！！$n领悟了盲目光芒合剂的配方！', `MaleText_loc5`='大發現!$n發現了盲目之光精鍊藥劑的配方!', `MaleText_loc7`='¡DESCUBRIMIENTO! $n ha descubierto la fórmula del frasco de Luz cegadora.', `FemaleText_loc1`='발견! $n|1이;가; 눈부신 빛의 영약 조제법을 발견했습니다!', `FemaleText_loc4`='太棒了！！$n领悟了盲目光芒合剂的配方！', `FemaleText_loc5`='大發現!$n發現了盲目之光精鍊藥劑的配方!', `FemaleText_loc7`='¡DESCUBRIMIENTO! $n ha descubierto la fórmula del frasco de Luz cegadora.' WHERE `ID`=12444;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발견! $n|1이;가; 순수한 죽음의 영약 조제법을 발견했습니다!', `MaleText_loc4`='太棒了！！$n领悟了纯粹死亡合剂的配方！', `MaleText_loc5`='大發現!$n發現了純淨死亡精鍊藥劑的配方!', `MaleText_loc7`='¡DESCUBRIMIENTO! $n ha descubierto la fórmula del frasco de muerte pura.', `FemaleText_loc1`='발견! $n|1이;가; 순수한 죽음의 영약 조제법을 발견했습니다!', `FemaleText_loc4`='太棒了！！$n领悟了纯粹死亡合剂的配方！', `FemaleText_loc5`='大發現!$n發現了純淨死亡精鍊藥劑的配方!', `FemaleText_loc7`='¡DESCUBRIMIENTO! $n ha descubierto la fórmula del frasco de muerte pura.' WHERE `ID`=12445;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나루의 가호로 살아남은 당신과 저는 정말 운이 좋았어요!', `FemaleText_loc4`='我和你，我们非常幸运地活下来了！', `FemaleText_loc5`='多虧聖光，我們能幸運的生存下來，你和我!', `FemaleText_loc7`='¡Tenemos mucha suerte de estar vivos!' WHERE `ID`=12446;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 근처는 인적이 정말 드물지요? 마법학자들이 직접 하기 싫은 위험한 일은 죄다 우리에게 떠넘기는 것 같다는 생각이 들기 시작했습니다.', `MaleText_loc4`='你在这附近没看到太多的学徒吧？我开始想，这是不是因为魔导师把所有连他们都不愿意亲自做的危险任务都交给我们的缘故。', `MaleText_loc5`='你在這附近沒看到很多學徒，對吧?我開始認為那是因為他們把所有不想做的危險工作都給了我們。', `MaleText_loc7`='No se ven muchos aprendices por aquí, ¿verdad? Estoy empezando a pensar que es porque los magistri nos dan todo el trabajo peligroso que prefieren no hacer ellos mismos.' WHERE `ID`=12447;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성스러운 빛을 찬양하라! $c|1이여;여;, 당신이 없었더라면 저는 여기서 죽었을 겁니다! 저는 이제 비행선으로 돌아가야 합니다.', `MaleText_loc4`='赞美圣光！$C，要是没有你，我一定会衰竭而死！我必须回到飞船那里。', `MaleText_loc5`='讚美聖光!如果不是你我會死在這裡，$c!我一定要趕到船那裡。', `MaleText_loc7`='¡Alabada sea la Luz! ¡De no ser por ti, $c, habría muerto aquí fuera! Debo ir a la nave.', `FemaleText_loc1`='성스러운 빛을 찬양하라! $c|1이여;여;, 당신이 없었더라면 저는 여기서 죽었을 겁니다! 저는 이제 비행선으로 돌아가야 합니다.', `FemaleText_loc4`='赞美圣光！$C，要是没有你，我一定会衰竭而死！我必须回到飞船那里。', `FemaleText_loc5`='讚美聖光!如果不是你我會死在這裡，$c!我一定要趕到船那裡。', `FemaleText_loc7`='¡Alabada sea la Luz! ¡De no ser por ti, $c, habría muerto aquí fuera! Debo ir a la nave.' WHERE `ID`=12448;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐지? 무슨 일이 일어난 거야? 으... 머리가 너무 아파 터질 거 같군요! 추락 지점으로 돌아가는 게 좋겠습니다.', `MaleText_loc4`='嗯？发生了什么事？哦……头痛欲裂！我最好返回坠毁点。', `MaleText_loc5`='啊?發生什麼事了?喔...我的頭好像要爆炸了!我最好快點回到失事地點。', `MaleText_loc7`='¿Eh? ¿Qué ha pasado? ¡Ay! Tengo la cabeza que parece que me va a estallar. Será mejor que vuelva al lugar del accidente.', `FemaleText_loc1`='뭐지? 무슨 일이 일어난 거야? 으... 머리가 너무 아파 터질 거 같군요! 추락 지점으로 돌아가는 게 좋겠습니다.', `FemaleText_loc4`='嗯？发生了什么事？哦……头痛欲裂！我最好返回坠毁点。', `FemaleText_loc5`='啊?發生什麼事了?喔...我的頭好像要爆炸了!我最好快點回到失事地點。', `FemaleText_loc7`='¿Eh? ¿Qué ha pasado? ¡Ay! Tengo la cabeza que parece que me va a estallar. Será mejor que vuelva al lugar del accidente.' WHERE `ID`=12449;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 고맙습니다. 저는 추락 지점으로 가서 도울 일은 없는지 확인해 봐야겠습니다. 다시 만날 때까지 안녕히...', `MaleText_loc4`='万分感谢，$C。我最好返回坠毁点，看看有什么需要帮忙的。下次再见。', `MaleText_loc5`='非常感謝你，$c。我最好快去失事地點看看能幫什麼忙。後會有期。', `MaleText_loc7`='Muchas gracias, $c. Será mejor que vaya al lugar del accidente para ver en qué puedo ayudar. Hasta la próxima.', `FemaleText_loc1`='정말 고맙습니다. 저는 추락 지점으로 가서 도울 일은 없는지 확인해 봐야겠습니다. 다시 만날 때까지 안녕히...', `FemaleText_loc4`='万分感谢，$C。我最好返回坠毁点，看看有什么需要帮忙的。下次再见。', `FemaleText_loc5`='非常感謝你，$c。我最好快去失事地點看看能幫什麼忙。後會有期。', `FemaleText_loc7`='Muchas gracias, $c. Será mejor que vaya al lugar del accidente para ver en qué puedo ayudar. Hasta la próxima.' WHERE `ID`=12450;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$C님이 절 구하셨군요! 평생 잊지 못할 신세를 졌습니다. 도움이 필요한 다른 친구는 없는지 찾아봐야겠습니다.', `MaleText_loc4`='$C，你救了我的命！你的恩情真是没齿难忘。我最好返回坠毁点，看看有什么需要帮忙的。', `MaleText_loc5`='$C，你救了我!我欠你的人情永遠也無法償還。我要去看看能否幫助其他人。', `MaleText_loc7`='$C, ¡me has salvado! Tengo una deuda contigo que jamás podré pagarte. Iré a ver si puedo ayudar a los demás.', `FemaleText_loc1`='$C님이 절 구하셨군요! 평생 잊지 못할 신세를 졌습니다. 도움이 필요한 다른 친구는 없는지 찾아봐야겠습니다.', `FemaleText_loc4`='$C，你救了我的命！你的恩情真是没齿难忘。我最好返回坠毁点，看看有什么需要帮忙的。', `FemaleText_loc5`='$C，你救了我!我欠你的人情永遠也無法償還。我要去看看能否幫助其他人。', `FemaleText_loc7`='$C, ¡me has salvado! Tengo una deuda contigo que jamás podré pagarte. Iré a ver si puedo ayudar a los demás.' WHERE `ID`=12451;
