UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 성스러운 빛의 순수함과 정의를 추구한다네.', `MaleText_loc4`='我们在圣光的庇护下追求纯净和正义。', `MaleText_loc5`='我們的道路是一條貞潔與公正的聖光之路。我今天能為你做些什麼?', `MaleText_loc7`='La nuestra es la senda de la pureza y la rectitud en la Luz.', `FemaleText_loc1`='우리는 성스러운 빛의 순수함과 정의를 추구한답니다.', `FemaleText_loc4`='我们在圣光的庇护下追求纯净和正义。', `FemaleText_loc5`='我們的道路是一條貞潔與公正的聖光之路。我今天能為你做些什麼?', `FemaleText_loc7`='La nuestra es la senda de la pureza y la rectitud en la Luz.' WHERE `ID`=12458;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 모두 빛 안에서는 하나이지만, 난 $c인 자네를 가르칠 능력이 없네.', `MaleText_loc4`='$G兄弟:姐妹;，我们都受圣光庇护，但是我不能训练你。', `MaleText_loc5`='在聖光中我們都是一體的，$g兄弟:姐妹;。', `MaleText_loc7`='Somos uno en la Luz, $ghermano:hermana;, pero no puedo instruirte.', `FemaleText_loc1`='우리 모두 빛 안에서는 하나이지만, 난 $c인 분에게 가르침을 드릴 능력이 없습니다.', `FemaleText_loc4`='$G兄弟:姐妹;，我们都受圣光庇护，但是我不能训练你。', `FemaleText_loc5`='在聖光中我們都是一體的，$g兄弟:姐妹;。', `FemaleText_loc7`='Somos uno en la Luz, $ghermano:hermana;, pero no puedo instruirte.' WHERE `ID`=12459;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련을 받으려고 오셨나요, 사냥꾼이여?', `MaleText_loc4`='猎人，你是来接受训练的吗？', `MaleText_loc5`='我能幫你什麼忙，獵人?', `MaleText_loc7`='¿Vienes en busca de instrucción, $gcazador:cazadora;?', `FemaleText_loc1`='훈련을 받으려고 오셨나요, 사냥꾼이여?', `FemaleText_loc4`='猎人，你是来接受训练的吗？', `FemaleText_loc5`='我能幫你什麼忙，獵人?', `FemaleText_loc7`='¿Vienes en busca de instrucción, $gcazador:cazadora;?' WHERE `ID`=12460;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 당신이 찾는 상급 $c|1이;가; 아니라 사냥꾼이랍니다. 다른 곳으로 가보시지요.', `MaleText_loc4`='我是猎人训练师。你要找的是$c训练师。', `MaleText_loc5`='我是個獵人訓練師。你要找一個$c訓練師。', `MaleText_loc7`='Yo soy instructor de cazadores. A ti te interesa el instructor de $c.', `FemaleText_loc1`='저는 당신이 찾는 상급 $c|1이;가; 아니라 사냥꾼이랍니다. 다른 곳으로 가보시지요.', `FemaleText_loc4`='我是猎人训练师。你要找的是$c训练师。', `FemaleText_loc5`='我是個獵人訓練師。你要找一個$c訓練師。', `FemaleText_loc7`='Yo soy instructora de cazadores. A ti te interesa el instructor de $c.' WHERE `ID`=12461;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 강력한 전사가 되려고 찾아오셨소?', `MaleText_loc4`='你想要学习更多的战士技能吗？', `MaleText_loc5`='你是來尋找戰士更深層的啟蒙嗎?', `MaleText_loc7`='¿Buscas más adiestramiento en las artes del guerrero?', `FemaleText_loc1`='더 강력한 전사가 되려고 찾아오셨나요?', `FemaleText_loc4`='你想要学习更多的战士技能吗？', `FemaleText_loc5`='你是來尋找戰士更深層的啟蒙嗎?', `FemaleText_loc7`='¿Buscas más adiestramiento en las artes del guerrero?' WHERE `ID`=12462;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 전사가 아니기에 내 훈련을 받을 수 없소.', `MaleText_loc4`='我非常愿意训练你，但你不是战士。', `MaleText_loc5`='我會訓練你，但你不是個戰士。', `MaleText_loc7`='Te entrenaría, pero no eres un guerrero.', `FemaleText_loc1`='당신은 전사가 아니기에 내 훈련을 받을 수 없습니다.', `FemaleText_loc4`='我非常愿意训练你，但你不是战士。', `FemaleText_loc5`='我會訓練你，但你不是個戰士。', `FemaleText_loc7`='Te entrenaría, pero no eres un guerrero.' WHERE `ID`=12463;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 비전과 자연의 힘의 연구를 실천하는 자들로서 끝없이 새로운 것을 발견하고자 노력합니다. 바로 이 때문에 절 찾아오신 것 아닙니까? 좀 더 훈련을 받고자 하십니까?', `MaleText_loc4`='我们的研究奥术和自然之力的专家们正在沿着一条永无止尽的探索之路前行。这就是你要寻求我的建议的原因吗？你希望获得更进一步的训练吗？', `MaleText_loc5`='我們學習秘法和元素的實踐者跟隨著一條永無止境的發現之路。這是為什麼你找我諮詢的原因嗎?你想受進一步的訓練?', `MaleText_loc7`='Nosotros, los profesionales de las artes Arcanas y Elementales seguimos un camino interminable de descubrimiento. ¿Por eso buscas mi consejo? ¿Deseas más instrucción?', `FemaleText_loc1`='우리는 비전과 자연의 힘의 연구를 실천하는 자들로서 끝없이 새로운 것을 발견하고자 노력합니다. 바로 이 때문에 절 찾아오신 것 아닙니까? 좀 더 훈련을 받고자 하십니까?', `FemaleText_loc4`='我们的研究奥术和自然之力的专家们正在沿着一条永无止尽的探索之路前行。这就是你要寻求我的建议的原因吗？你希望获得更进一步的训练吗？', `FemaleText_loc5`='我們學習秘法和元素的實踐者跟隨著一條永無止境的發現之路。這是為什麼你找我諮詢的原因嗎?你想受進一步的訓練?', `FemaleText_loc7`='Nosotros, los profesionales de las artes Arcanas y Elementales seguimos un camino interminable de descubrimiento. ¿Por eso buscas mi consejo? ¿Deseas más instrucción?' WHERE `ID`=12464;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나루의 뜻대로 될지니... 미안하지만 마법사가 아닌 당신을 가르칠 순 없습니다! 훈련을 받고 싶으면 상급 $c|1을;를; 찾아가십시오.', `MaleText_loc4`='以纳鲁的名义，你不是个法师！如果你在寻求训练，你必须找$c训练师才行。', `MaleText_loc5`='在那魯看來，你不是個法師!如果你想接受訓練，你就一定要找一個$c訓練師。', `MaleText_loc7`='¡Por los naaru, tú no eres mago! Si buscas instrucción, debes buscar a un instructor $c.', `FemaleText_loc1`='나루의 뜻대로 될지니... 미안하지만 마법사가 아닌 당신을 가르칠 순 없습니다! 훈련을 받고 싶으면 상급 $c|1을;를; 찾아가십시오.', `FemaleText_loc4`='以纳鲁的名义，你不是个法师！如果你在寻求训练，你必须找$c训练师才行。', `FemaleText_loc5`='在那魯看來，你不是個法師!如果你想接受訓練，你就一定要找一個$c訓練師。', `FemaleText_loc7`='¡Por los naaru, tú no eres mago! Si buscas instrucción, debes buscar a un instructor $c.' WHERE `ID`=12465;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앞에 있는 내 $g형제:자매;여. 빛의 품 안에서 우리 모두는 어둠을 떨쳐내야 하네. 기술을 지도받고자 왔는가?', `MaleText_loc4`='我的$G兄弟:姐妹;，我们都受圣光的庇护。你是来寻求更多指引的吗？', `MaleText_loc5`='在聖光中我們都會投映出陰影，我的$g兄弟:姐妹;。你今天在尋找指引嗎?', `MaleText_loc7`='En la Luz todos proyectamos sombras, $ghermano:hermana;. ¿Buscas más orientación hoy?', `FemaleText_loc1`='앞에 계신 내 $g형제:자매;여. 빛의 품 안에서 우리 모두는 어둠을 떨쳐내야 합니다. 기술을 지도받고자 오셨나요?', `FemaleText_loc4`='我的$G兄弟:姐妹;，我们都受圣光的庇护。你是来寻求更多指引的吗？', `FemaleText_loc5`='在聖光中我們都會投映出陰影，我的$g兄弟:姐妹;。你今天在尋找指引嗎?', `FemaleText_loc7`='En la Luz todos proyectamos sombras, $ghermano:hermana;. ¿Buscas más orientación hoy?' WHERE `ID`=12466;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='젊은 $c|1이여;여;, 나는 $g형제:자매;를 훈련할 순 없으니 대신 축복을 주겠네. 빛의 품 속에서 당당하게 나아가게.', `MaleText_loc4`='年轻的$C，虽然我没法训练你，可我依然祝福你。在圣光的庇护下大胆前进吧！', `MaleText_loc5`='雖然我不能提供你訓練，年輕的$c，我仍會給你我的祝福。大膽地走進聖光。', `MaleText_loc7`='Aunque no puedo entrenarte, joven $c, puedo ofrecerte mi bendición. ¡Camina con valentía bajo la Luz!', `FemaleText_loc1`='젊은 $c|1이여;여;, 저는 $g형제:자매;님을 훈련할 수는 없지만 대신 축복을 드리지요. 빛의 품 속에서 당당하게 나아가세요.', `FemaleText_loc4`='年轻的$C，虽然我没法训练你，可我依然祝福你。在圣光的庇护下大胆前进吧！', `FemaleText_loc5`='雖然我不能提供你訓練，年輕的$c，我仍會給你我的祝福。大膽地走進聖光。', `FemaleText_loc7`='Aunque no puedo entrenarte, joven $c, puedo ofrecerte mi bendición. ¡Camina con valentía bajo la Luz!' WHERE `ID`=12467;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 감히 우리의 전당에 침입하느냐? 타락한 호드의 강력한 힘을 보여주마!', `MaleText_loc4`='是谁胆敢侵犯破碎大厅？尝尝邪部落的力量吧！', `MaleText_loc5`='誰敢入侵破碎大廳?準備見識魔獄部落的力量吧!', `MaleText_loc7`='¿Quién osa invadir Las Salas Arrasadas? ¡Prepárate para conocer la fuerza de la Horda vil!' WHERE `ID`=12468;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='르노...', `MaleText_loc4`='雷诺……', `MaleText_loc5`='雷諾...', `MaleText_loc7`='Renault...' WHERE `ID`=12469;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아버지... 하지만, 어떻게...?', `MaleText_loc4`='父亲……但是……怎么可能？', `MaleText_loc5`='父親...但...怎麼會?', `MaleText_loc7`='Padre... Pero... ¿Cómo?' WHERE `ID`=12470;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 배신을 잊을 줄 알았더냐? 네가 철저히 준비한 배신이 내 죽음으로 잊힐 줄 알았던 것이냐? 심장이 멈춘 후에도 오랫동안 나의 칼날은 너의 잔인함에 몸서리쳤다. 피가 끓도록... 죽어서야 난 네가 무슨 짓을 저질렀는지 똑똑히 알게 됐다. 하지만, 이제 더는 켈투자드의 쇠사슬이 내 몸을 휘감고 있지 않단다, 아들아! 난 정의를 지키기 위해 왔다. 내가 바로 파멸의 인도자이니...', `MaleText_loc4`='你难道还奢望你的背叛能够得到我的原谅吗？对我死亡真相的遮掩终于还是失败了吗？这把剑沾染了我的鲜血，它在我死后仍然感觉到了你的凶残。而且，我也完全了解到你做了些什么。但现在，克尔苏加德的锁链不能再束缚住我了。我要重新回来执掌正义。我是灰·烬·使·者。', `MaleText_loc5`='你以為你的背叛會被遺忘嗎?因為我的死而小心地被藏起來?我親愛的孩子，那把劍在我的心臟停止跳動後就感受到你的殘酷了。雖然死亡，但我知道你做了什麼。現在，科爾蘇加德的枷鎖不再束縛著我。我是來討回公道的。我就是灰燼使者。', `MaleText_loc7`='¿Creías que olvidaría tu traición? ¿Creías que se iría conmigo tras mi muerte encubierta? Sangre de mi sangre, tu crueldad perduró en el acero por mucho tiempo después de que mi corazón cesara de latir. Y tras mi muerte, descubrí lo que habías hecho. Pero ahora, las cadenas de Kel''Thuzad ya no me atan. He venido a impartir justicia. SOY EL PORTADOR DE LA CREMATORIA.' WHERE `ID`=12471;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제발 용서해 주세요. 아버지...', `MaleText_loc4`='原谅我，父亲！求求您……', `MaleText_loc5`='原諒我，父親!求求你...', `MaleText_loc7`='¡Perdóname, padre! Por favor...' WHERE `ID`=12472;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용서하마, 아들아...', `MaleText_loc4`='我已经原谅你了……', `MaleText_loc5`='我原諒你...', `MaleText_loc7`='Estás perdonado...' WHERE `ID`=12473;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아즈샤라에 스컬지의 수가 점점 늘고 있습니다. 신체 건강한 자들은 모두 나아가 그들의 침략을 막아야 합니다.$B$B남아 있는 죽음의 요새: $2279W개', `MaleText_loc4`='天灾军团的势力正在艾萨拉迅速滋长。所有能参加战斗的人都必须并肩战斗，阻止他们的侵略大潮席卷世界！$B$B剩余浮空要塞数量：$2279W', `MaleText_loc5`='天譴軍團的入侵在艾薩拉日益加大。每個健全的戰士都要挺身而出阻擋他們的入侵。$B$B剩餘的亡域:$2279W', `MaleText_loc7`='La presencia de la Plaga va en aumento en Azshara. Es necesario que todos aquellos guerreros que estén sanos ayuden a frenar su invasión.$B$BNúmero de necrópolis restantes: $2279W' WHERE `ID`=12474;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동부 역병지대에 스컬지의 수가 점점 늘고 있습니다. 신체 건강한 자들은 모두 나아가 그들의 침략을 막아야 합니다.$B$B남아 있는 죽음의 요새: $2282W개', `MaleText_loc4`='天灾军团的势力正在东瘟疫之地迅速滋长。所有能参加战斗的人都必须并肩战斗，阻止他们的侵略大潮席卷世界！$B$B剩余浮空要塞数量：$2282W', `MaleText_loc5`='天譴軍團的入侵在東瘟疫之地日益加大。每個健全的戰士都要挺身而出阻擋他們的入侵。$B$B剩餘的亡域:$2282W', `MaleText_loc7`='La presencia de la Plaga va en aumento en las Tierras de la Peste del Este. Es necesario que todos aquellos guerreros que estén sanos ayuden a frenar su invasión.$B$BNúmero de necrópolis restantes: $2282W' WHERE `ID`=12475;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='현재 아즈샤라가 공격받고 있습니까?', `MaleText_loc4`='艾萨拉现在遭到攻击了吗？', `MaleText_loc5`='艾薩拉目前正遭到攻擊嗎?', `MaleText_loc7`='¿Está siendo atacada Azshara?', `FemaleText_loc1`='현재 아즈샤라가 공격받고 있나요?', `FemaleText_loc4`='艾萨拉现在遭到攻击了吗？', `FemaleText_loc5`='艾薩拉目前正遭到攻擊嗎?', `FemaleText_loc7`='¿Está siendo atacada Azshara?' WHERE `ID`=12476;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='현재 동부 역병지대가 공격받고 있습니까?', `MaleText_loc4`='东瘟疫之地现在遭攻击了吗？', `MaleText_loc5`='東瘟疫之地現在正遭到攻擊嗎?', `MaleText_loc7`='¿Están siendo atacadas las Tierras de la Peste del Este?', `FemaleText_loc1`='현재 동부 역병지대가 공격받고 있나요?', `FemaleText_loc4`='东瘟疫之地现在遭攻击了吗？', `FemaleText_loc5`='東瘟疫之地現在正遭到攻擊嗎?', `FemaleText_loc7`='¿Están siendo atacadas las Tierras de la Peste del Este?' WHERE `ID`=12477;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 질문이 있습니다.', `MaleText_loc4`='我还有一个问题。', `MaleText_loc5`='我有另外一個問題。', `MaleText_loc7`='Tengo otra duda...', `FemaleText_loc1`='다른 질문이 있어요.', `FemaleText_loc4`='我还有一个问题。', `FemaleText_loc5`='我有另外一個問題。', `FemaleText_loc7`='Tengo otra duda...' WHERE `ID`=12478;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 스컬지와 싸우는 지역은 어디입니까?', `MaleText_loc4`='其他地方还有天灾军团入侵吗？', `MaleText_loc5`='我們還要在什麼地方對抗天譴軍團?', `MaleText_loc7`='¿En qué otro lugar vamos a enfrentarnos a la Plaga?', `FemaleText_loc1`='우리가 스컬지와 싸우는 지역은 어디인가요?', `FemaleText_loc4`='其他地方还有天灾军团入侵吗？', `FemaleText_loc5`='我們還要在什麼地方對抗天譴軍團?', `FemaleText_loc7`='¿En qué otro lugar vamos a enfrentarnos a la Plaga?' WHERE `ID`=12479;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제야 저주가 풀렸군. 고맙소. 당신은 우리의 영웅이오.', `MaleText_loc4`='终于，诅咒解除了。谢谢你，英雄。', `MaleText_loc5`='終於，詛咒被解除了。謝謝你，英雄。', `MaleText_loc7`='Al fin ha desaparecido la maldición. Gracias, valiente.' WHERE `ID`=12480;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저주라고요? 대체 무슨 말입니까?', `MaleText_loc4`='诅咒？这里究竟发生了些什么，法尔班克斯？', `MaleText_loc5`='詛咒?到底怎麼回事，法爾班克斯?', `MaleText_loc7`='¿Maldición? ¿Qué está pasando aquí, Ribalimpia?', `FemaleText_loc1`='저주라고요? 대체 무슨 말인가요?', `FemaleText_loc4`='诅咒？这里究竟发生了些什么，法尔班克斯？', `FemaleText_loc5`='詛咒?到底怎麼回事，法爾班克斯?', `FemaleText_loc7`='¿Maldición? ¿Qué está pasando aquí, Ribalimpia?' WHERE `ID`=12481;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전혀 아는 바가 없단 말이오? 당신 등에 짊어진 그 검은 원래 주인의 이름을 따라서 파멸의 인도자라고 알려졌소.', `MaleText_loc4`='你是说，你完全不知道？你背上的那把剑，名叫灰烬使者，这个名字是从它原来的主人那里继承而来的。', `MaleText_loc5`='你是說，你不知道?你背上揹著的劍 - 它叫做灰燼使者;以它原本的主人命名。', `MaleText_loc7`='¿Quieres decir que no lo sabes? La espada que llevas a tu espalda se conoce como Crematoria, nombre de su dueño original.' WHERE `ID`=12482;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모그레인 말입니까?', `MaleText_loc4`='莫格莱尼？', `MaleText_loc5`='莫格萊尼?', `MaleText_loc7`='¿Mograine?', `FemaleText_loc1`='모그레인 말이오?', `FemaleText_loc4`='莫格莱尼？', `FemaleText_loc5`='莫格萊尼?', `FemaleText_loc7`='¿Mograine?' WHERE `ID`=12483;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇소, 대영주 모그레인... 붉은십자군의 창설자이자, 고결한 성품과 신념을 지닌 기사였지. 아들에게 배신당해 스트라솔름에서 켈투자드의 군대에 살해되셨소. 그래서 나도 여기까지 온 거고...', `MaleText_loc4`='是的，莫格莱尼，大领主莫格莱尼：血色十字军最初的建立者之一，一位一生忠诚于其信仰，致力于净化世间一切罪恶的骑士。他被自己的亲生儿子背叛，并被克尔苏加德的军队杀死在了斯坦索姆城内。这也是我现在横在?里的原因……', `MaleText_loc5`='是的，大領主莫格萊尼:血色十字軍最初的創始人。一個擁有堅定信念和貞潔的騎士;莫格萊尼後來被他自己的兒子背叛並在斯坦索姆裡被科爾蘇加德的軍隊殺害。我就說到這了...', `MaleText_loc7`='Eso es, el alto señor Mograine: uno de los fundadores de la orden de la Cruzada Escarlata. Un caballero de una fe y pureza inquebrantables, Mograine sería traicionado por su propio hijo y derrotado por las tropas de Kel''Thuzad en Stratholme. Así es como llegué hasta aquí...' WHERE `ID`=12484;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 얘깁니까?', `MaleText_loc4`='什么意思？', `MaleText_loc5`='什麼意思?', `MaleText_loc7`='¿Qué quieres decir?', `FemaleText_loc1`='무슨 말이죠?', `FemaleText_loc4`='什么意思？', `FemaleText_loc5`='什麼意思?', `FemaleText_loc7`='¿Qué quieres decir?' WHERE `ID`=12485;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='붉은십자군은 고위사령관 아벤디스, 종교재판장 이실리엔, 그리고 대영주 모그레인에 의해 창설되었소. 당시에는 정의로운 조직이었지. 그때만 해도 당신이 본 그런 광기와 맹신은 찾아볼 수 없었소. 적어도 십자군 사령관이란 자가 나타나 타락의 늪으로 서서히 빠져들기 전까지는 말이오.', `MaleText_loc4`='最初，是大将军阿比迪斯、大审判官伊森利恩和大领主莫格莱尼一起建立了十字军组织。那时候，十字军还是一个高贵的组织。没有止境的狂热与愚行那时候完全不存在。直到那个自称大十字军的男人出现以后，我们才开始走向堕落与腐化的道路。', `MaleText_loc5`='大將軍阿比迪斯，大審判官伊森利恩和大領主莫格萊尼組成了十字軍。在初期的時候，十字軍是高尚的軍隊。你現在所看到的瘋狂和狂熱行為當時都不存在。直到一個叫做大十字軍戰士的人出現，腐敗的巨輪才開始轉動。', `MaleText_loc7`='Fueron la Alta General Abbendis, el gran inquisidor Isillien y el alto señor Mograine quienes crearon la Cruzada. En sus comienzos, la Cruzada era una orden noble. La locura y el fanatismo que ahora hay en ella no existían. Las ruedas de la corrupción se pusieron en marcha cuando apareció el llamado Gran Cruzado.' WHERE `ID`=12486;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 이해가 되지 않습니다.', `MaleText_loc4`='我还是没能完全理解。', `MaleText_loc5`='我還是不太明白。', `MaleText_loc7`='Sigo sin comprenderlo bien.', `FemaleText_loc1`='아직 이해가 되지 않아요.', `FemaleText_loc4`='我还是没能完全理解。', `FemaleText_loc5`='我還是不太明白。', `FemaleText_loc7`='Sigo sin comprenderlo bien.' WHERE `ID`=12487;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대영주께서는 붉은십자군에 없어서는 안 될 존재였소. 사람들은 리치 왕의 군대와 싸워서 혁혁한 공을 세운 그분을 칭송하며 파멸의 인도자라 불렀다오. 모그레인 님은 오로지 검과 신념만으로 전장 한복판에 뛰어들어 홀로 언데드들을 섬멸하고는 상처 하나 없이 귀환하곤 하셨소. 아직 무슨 말인지 모르겠소? 죽음조차 그분을 두려워했단 말이오! 그 이름만으로도 적들은 두려움에 떨었지.', `MaleText_loc4`='大领主那时是十字军的核心人物。哎，当时，莫格莱尼被称作灰烬使者，因为他曾把成千上百的巫妖王的爪牙化为灰烬。手中有神兵，心中有信仰，就算是所有的亡灵军团排成阵列在莫格莱尼面前，他也会从容步入，然后他所经过的地方便只会留下敌人的身躯所烧成的灰烬。你能理解吗？就算是亡灵，遇到他也会感觉到恐惧！就算是魔鬼，站在他面前也会浑身颤抖。', `MaleText_loc5`='大領主是十字軍的關鍵人物。是的，莫格萊尼會被稱為灰燼使者是因為他與巫妖王軍隊對抗的功績。只有劍和信念，莫格萊尼就能走進不死族的軍隊再毫髮無傷的走出來 - 敵人的灰燼不過是證明了他曾在那裡而已。你明白嗎?死亡的臉孔都怕他!我看到他都會顫抖!', `MaleText_loc7`='El Alto Señor era el eje de la Cruzada. Sí, a Mograine se le conocía como el señor de la Crematoria gracias a sus hazañas contra los ejércitos del Rey Exánime. Con la sola ayuda de su espada y su fe, Mograine era capaz de atravesar un batallón al completo de no-muertos y salir indemne. Las cenizas de sus enemigos eran la única muestra de su paso por allí. ¿No lo entiendes? ¡Hasta la propia muerte le temía! ¡Temblaba ante su presencia!' WHERE `ID`=12488;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놀라운 이야기군요. 그렇다면, 그 분은 어떻게 죽은 겁니까?', `MaleText_loc4`='令人难以置信的故事。他后来是怎么死的？', `MaleText_loc5`='不可思議的故事。那他是怎麼死的?', `MaleText_loc7`='Una historia increíble. Entonces, ¿cómo murió?', `FemaleText_loc1`='놀라운 이야기군요. 그렇다면, 그 분은 어떻게 죽은 건가요?', `FemaleText_loc4`='令人难以置信的故事。他后来是怎么死的？', `FemaleText_loc5`='不可思議的故事。那他是怎麼死的?', `FemaleText_loc7`='Una historia increíble. Entonces, ¿cómo murió?' WHERE `ID`=12489;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런 영웅이 죽는 이유는 단 한 가지밖에 없는 법이지, $r! 돌이킬 수 없는 비극. 그것뿐이라오. 십자군 사령관이란 자가 켈투자드와 은밀한 거래를 한 거요. 결국, 잠복해 있던 놈들에게 습격을 당해 모그레인 님은 세상을 떠나시고 말았지. 가장 믿고 아끼는 자의 배신이 아니었다면 이런 끔찍한 결과는 절대 일어나지 않았을 거요.', `MaleText_loc4`='英雄的末路啊，$r，大概只有一种吧，那就是悲剧。大十字军一定是亲自与克尔苏加德做了一笔交易，陷害了莫格莱尼。莫格莱尼遭到了天灾军团的伏击，不幸死去了。这种背叛也只能由他至亲至信至爱之人来做才能成功……', `MaleText_loc5`='英雄死亡的唯一途徑，$r:是死於悲劇。大十字軍戰士和科爾蘇加德達成協議!他們佈下了一個埋伏陷阱導致莫格萊尼的死。那種背叛是只有最信任最親愛的同伴才有的行為。', `MaleText_loc7`='Del único modo en el que un héroe puede morir, $r: envuelto en tragedia. ¡El Gran Cruzado llegó a un acuerdo con el mismísimo Kel''Thuzad! Le tendieron una emboscada en la que Mograine encontraría la muerte. El tipo de traición que solo puede provenir de las acciones de alguien en quien confías y aprecias.' WHERE `ID`=12490;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 그 사람이...', `MaleText_loc4`='你是说……', `MaleText_loc5`='你是說...', `MaleText_loc7`='Quieres decir que...', `FemaleText_loc1`='그럼 그 사람이...', `FemaleText_loc4`='你是说……', `FemaleText_loc5`='你是說...', `FemaleText_loc7`='Quieres decir que...' WHERE `ID`=12491;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<고개를 끄덕이는 종교재판관 페어뱅크스>$B$B그렇소. 붉은십자군 사령관으로 알려진 모그레인 님의 아들이 한 짓이지. 내가 아는 바로는 십자군 사령관도 동일 인물이라오. 아버지를 적이 매복해 있는 장소로 유인한 사람이 다름 아닌 그 아들이었단 말이지.', `MaleText_loc4`='<大检察官法尔班克斯点了点头>$B$B是的，就是小莫格莱尼，血色指挥官，我怀疑，他也参与了大十字军的交易。就是他，他将他的父亲引向了死亡之路。', `MaleText_loc5`='<高階審判官法爾班克斯點點頭。>$B$B是的，小莫格萊尼，也就是血色指揮官，我懷疑 - 他與大十字軍戰士交易。讓他的父親陷入埋伏就像羊入虎口一樣。', `MaleText_loc7`='<El Gran Inquisidor Ribalimpia asiente.>$B$BSí, el joven Mograine, conocido como Comandante Escarlata. Aunque sospecho que bajo la influencia del Gran Cruzado... Dejó que su padre fuera hacia la emboscada como un cordero que llevan al matadero.' WHERE `ID`=12492;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대체 이런 사실은 어떻게 알아낸 겁니까?', `MaleText_loc4`='你是怎么知道这些事的？', `MaleText_loc5`='你怎麼知道這些事?', `MaleText_loc7`='¿Cómo sabes todo esto?', `FemaleText_loc1`='대체 이런 사실은 어떻게 알아낸 건가요?', `FemaleText_loc4`='你是怎么知道这些事的？', `FemaleText_loc5`='你怎麼知道這些事?', `FemaleText_loc7`='¿Cómo sabes todo esto?' WHERE `ID`=12493;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<겉옷을 들어올려 상처투성이인 몸을 보여 주는 종교재판관 페어뱅크스>$B$B그렇소, 나도 거기에 있었소. 난 대영주께서 가장 신뢰하는 참모였소. 내가 그때 알아차렸더라면... 지금도 그때 일을 생각하면 내가 큰 실수를 저지른 탓인 것만 같소. 거기에 스컬지들이 수천도 더 매복해 있었다면 믿겠소?', `MaleText_loc4`='<大检查官法尔班克斯撩起了他的罩袍，并向你展示了伤口>$B$B因为我当时也在那里……我是大领主最信任的幕僚。我应该察觉这一切的……我当时就觉着事情有些不对，可我却还是让一切继续发生了下去。你知道吗？你能想象吗？当时那里起码有一千名以上的天灾军士兵。', `MaleText_loc5`='<高階審判官法爾班克斯拉起他的外袍露出幾個可怕的疤。>$B$B因為我在那裡...我是大領主最信任的顧問。我應該知道... 我感覺到有什麼事不太對勁但我還是容許它發生了。你相信那裡有一千個或更多的天譴軍團嗎?', `MaleText_loc7`='<El Gran Inquisidor Ribalimpia levanta su tabardo y deja ver varias cicatrices horripilantes.>$B$BPorque yo estaba allí... Yo era el consejero de más confianza del Alto Señor. Debería haberlo sabido... Presentía que algo iba mal y aun así permití que ocurriera. ¿Me creerías si te digo que había un millar o más de miembros de la Plaga?' WHERE `ID`=12494;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수천이라고요? 단 한 명을 처치하기 위해서 말입니까?', `MaleText_loc4`='一千个？对付一个人？', `MaleText_loc5`='一千個?對付一個人?', `MaleText_loc7`='¿Un millar? ¿Para un solo hombre?', `FemaleText_loc1`='수천이라고요? 단 한 명을 처치하기 위해서 말이에요?', `FemaleText_loc4`='一千个？对付一个人？', `FemaleText_loc5`='一千個?對付一個人?', `FemaleText_loc7`='¿Un millar? ¿Para un solo hombre?' WHERE `ID`=12495;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 한 사람이 파멸의 인도자라면 당연한 일이지, 이 멍청한 친구야! 스컬지들이 우리를 포위하자 모그레인 님께서 검을 꺼내 들었고... 그의 아들은 바로 도망쳤지. 놈들은 여태껏 내가 한 번도 보지 못한 무서운 광기를 드러내며 우리에게 달려들었소. 그런데...', `MaleText_loc4`='但他们的对手是灰烬使者，笨蛋！在天灾军士兵将我们团团围起来之前，莫格莱尼的剑就发出淡淡的红光，并嗡嗡地响了起来……想必小莫格莱尼就是在看到了这个以后开始逃跑的。很快天灾士兵就出现了，带着一种饥饿的眼神看着我们，那种凶残是我所从未见过的。但是……', `MaleText_loc5`='這是灰燼使者，蠢蛋!隨著天譴軍團在我們身邊出現，莫格萊尼的劍開始發光...嗡嗡作響...小莫格萊尼把這當作開始逃跑的信號。它們全都飢餓地突擊我們，那是我從未見過的情況。', `MaleText_loc7`='¡No era un hombre cualquiera sino el señor de la Crematoria, idiota! A medida que fueron apareciendo miembros de la Plaga a nuestro alrededor, la espada de Mograine empezó a resplandecer... a bullir... y el joven Mograine decidió que era motivo suficiente para huir. Se lanzaron sobre nosotros con una furia jamás vista. Aun así...' WHERE `ID`=12496;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런데? 그런데 뭐가 어떻게 됐습니까?', `MaleText_loc4`='但是？但是什么？', `MaleText_loc5`='然而?然而什麼??', `MaleText_loc7`='¡Romped sus huesos!', `FemaleText_loc1`='그런데? 그런데 뭐가 어떻게 됐죠?', `FemaleText_loc4`='但是？但是什么？', `FemaleText_loc5`='然而?然而什麼??', `FemaleText_loc7`='¿Aun así? ¿Aun así, qué?' WHERE `ID`=12497;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수천 명으로도 모그레인 님을 상대하기엔 역부족이었소.$B$B<잠깐 웃었다가 생각에 잠기는 페어뱅크스>$B$B수천 명이 달려들었지만 모두 모그레인 님의 손에 쓰러지고 말았지! 위대한 빛의 힘으로! 달려드는 족족 그분의 검에 쓰러져나갔소. 그 아비규환의 와중에 난 모그레인 님의 아들이 먼 곳에서 지켜보고 있다는 걸 알게 되었소. 난 그에게 소리쳤지. "르노, 어서! 아버지를 도와야 하지 않는가!"', `MaleText_loc4`='这还不够。$B$B<法尔班克斯苦笑了一声，略微失神了片刻。>。一千个天灾军士兵而已，它们很快就都死了。圣光在上！莫格莱尼之力万岁！混乱中，他接连把那些亡灵一个个放倒，而小莫格莱尼却仍在一旁站着不动，维持着距离。我向他喊道：“帮帮我们，雷诺！帮帮你的父亲，孩子！”', `MaleText_loc5`='還不夠。$B$B<法爾班克斯淺淺的笑了笑，掉進了回憶的漩渦裡。>$B$B一千個人來一千個人死。是聖光!是莫格萊尼的力量!它們來的有多快他就能多快把它們擊敗。在混亂之中，我注意到小莫格萊尼還在那裡，站的遠遠的。我呼叫他，「幫幫我們，雷諾!幫幫你的父親，孩子!」', `MaleText_loc7`='No fue suficiente.$B$B<Ribalimpia dibujó una fugaz sonrisa, mientras recordaba.>$B$BVinieron mil y mil perecieron. ¡Por la Luz! ¡Por el poder de Mograine! Tan pronto se le acercaban recibían la fuerza de sus golpes. En medio del caos, me di cuenta de que el joven Mograine seguía allí, en la distancia. Lo llamé: "¡Ayúdanos, Renault! ¡Ayuda a tu padre, chico!"' WHERE `ID`=12498;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래서 아들이 도왔습니까?', `MaleText_loc4`='他帮忙了么？', `MaleText_loc5`='他幫了什麼?', `MaleText_loc7`='¿Y él lo hizo?', `FemaleText_loc1`='그래서 아들이 도왔나요?', `FemaleText_loc4`='他帮忙了么？', `FemaleText_loc5`='他幫了什麼?', `FemaleText_loc7`='¿Y él lo hizo?' WHERE `ID`=12499;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<고개를 젓는 종교재판관 페어뱅크스>$B$B아니오... 그저 멀찌감치 서서 언데드 군대가 우리에게 달려드는 걸 지켜보고만 있었지. 그리고 난 이내 완전히 지치고 말았소. 내가 먼저 쓰러졌지. 놈들은 의식을 잃은 나를 갈기갈기 찢어놓을 수도 있었지. 하지만 오로지 대영주님을 쓰러뜨리는 데만 혈안이 되어 있던 놈들은 내게 신경도 쓰지 않더군.', `MaleText_loc4`='<大检查官法尔班克斯摇了摇头。>$B$B不……他仍旧站得远远的，看着我们被成群的天灾军士兵包围。不久之后，我的能力就耗尽了。我是第一个倒下的人……要不是我失去了意识，看起来像死人一样，天灾士兵们一定会把我彻底撕碎的，我晕了过去，它们彻底忽略了我，全力对付大领主。', `MaleText_loc5`='<高階審判官法爾班克斯搖搖他的頭。>$B$B不...他站在暗處，看著不死軍團突襲我們。很快地，我的力量已經消耗殆盡。我是第一個倒下的人...我無意識地倒在那裡他們當然會把我一塊一塊的肢解;但他們竟完全忽略我，把全部的注意力放在大領主身上。', `MaleText_loc7`='<El Gran Inquisidor Ribalimpia niega con la cabeza.>$B$BNo... Se quedó a un lado, viendo cómo la legión de no-muertos se abalanzaba sobre nosotros. Poco después, mis poderes se agotaron y fui el primero en caer. Aunque creía que me despedazarían trocito a trocito mientras permanecía inconsciente tendido en el suelo, lo cierto es que me ignoraron por completo y centraron su atención en el Alto Señor.' WHERE `ID`=12500;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 말씀하시죠.', `MaleText_loc4`='请继续，法尔班克斯。', `MaleText_loc5`='請繼續，法爾班克斯。', `MaleText_loc7`='Ribalimpia, continúa por favor.', `FemaleText_loc1`='계속 말씀하시죠.', `FemaleText_loc4`='请继续，法尔班克斯。', `FemaleText_loc5`='請繼續，法爾班克斯。', `FemaleText_loc7`='Ribalimpia, continúa por favor.' WHERE `ID`=12501;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 스컬지 시체 밑에서 죽은 척하며 있을 수밖에 없었소. 시체 밑에 깔려 있었던 난 암울한 어둠과 전투의 소리만 희미하게 느낄 뿐이었소. 검이 부딪히는 날카로운 쇳소리, 이빨을 가는 소리, 무언가 짓이기는 소리... 온통 소름끼치고 무시무시한 소리만 들려왔지. 그리고 얼마 후 갑자기 정적이 흐르더니 대영주님께서 날 부르는 소리가 들렸소. "페어뱅크스! 어디 있는가. 페어뱅크스? 대답해봐!" 그 순간 믿을 수 없는 일이 벌어졌소. 믿을 수 없는 배신의 음모가 그 실체를 드러낸 거요...', `MaleText_loc4`='我所能做的全部事情不过是继续装死，很快，天灾士兵的尸体就把我埋在了下面。我只能感觉到身体上的重负，以及耳边呼啸着的砍杀搏斗声，钢铁碰撞声，总之，可怕的声音。不知过了多久以后，一切都静默了下来，我听见他在叫我，“法尔班克斯！法尔班克斯，你在哪儿？听到了就说话，法尔班克斯！”接着，最无耻的背叛就发生了……', `MaleText_loc5`='天譴軍團將屍體在我身上堆起來的時候，假死是我唯一能做的事。我上方只有黑暗和戰爭隱約的聲響。鐵器的碰撞聲，痛苦的咬牙磨牙聲...可怕，恐怖的聲音。然後就一片靜默。他呼叫我的名字!「法爾班克斯!法爾班克斯你在哪裡?回答我法爾班克斯!」然後就聽到一個令我不敢相信的聲音。背叛者的咬噬，$r...', `MaleText_loc7`='Era todo lo que podía hacer para fingir estar muerto mientras los cuerpos de los miembros de la Plaga se apilaban sobre mí. En la oscuridad, escuchaba los sonidos sordos de la batalla que se estaba librando. El golpear del hierro, el forcejeo, la lid... sonidos horripilantes. Y entonces se hizo el silencio y él me llamó. "¡Ribalimpia! Ribalimpia, ¿dónde estás? ¡Dime algo, Ribalimpia!" Y entonces se escuchó el sonido de la incredulidad, el momento de la traición, $r..."' WHERE `ID`=12502;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 얘기는...', `MaleText_loc4`='你是说……', `MaleText_loc5`='你是說...', `MaleText_loc7`='Eso significa que...', `FemaleText_loc1`='그 얘기는...', `FemaleText_loc4`='你是说……', `FemaleText_loc5`='你是說...', `FemaleText_loc7`='Eso significa que...' WHERE `ID`=12503;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그분의 아들이 파멸의 인도자를 집어들더니 아버지의 등 뒤에서 심장을 향해 검을 찔러 넣은 거요. 그분의 마지막 한 마디는 영원히 잊히지 않을 거요. "무슨 짓을 한 거니, 르노? 네가 왜 이런 짓을?"', `MaleText_loc4`='那孩子捡起了灰烬使者，并从背后向他父亲砍了过去。老人最后的一句话现在仍在我耳边回转不去：“你！你干什么？！雷诺？为什么？！”', `MaleText_loc5`='那個男孩拾起灰燼使者並且在轉身的時候將劍刺進了他父親的心臟。他最後說的話永遠在我心頭:「你做了什麼，雷諾?你為什麼這樣做?」', `MaleText_loc7`='El chico, espada Crematoria en mano, había clavado el acero a su padre, por la espalda y directo al corazón. Nunca olvidaré sus últimas palabras: "¿Qué has hecho, Renault? ¿Por qué haces esto?"' WHERE `ID`=12504;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 말이 맞군요. 정말 엄청난 비극입니다.', `MaleText_loc4`='你说得对，法尔班克斯。这真是一场悲剧。', `MaleText_loc5`='你說得對，法爾班克斯。那是個悲劇。', `MaleText_loc7`='Tenías razón, Ribalimpia. Esta historia es muy trágica.', `FemaleText_loc1`='당신 말이 맞군요. 정말 엄청난 비극입니다.', `FemaleText_loc4`='你说得对，法尔班克斯。这真是一场悲剧。', `FemaleText_loc5`='你說得對，法爾班克斯。那是個悲劇。', `FemaleText_loc7`='Tenías razón, Ribalimpia. Esta historia es muy trágica.' WHERE `ID`=12505;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모그레인 님과 그분의 검은 한 몸과도 같소. 이해할 수 있겠소? 그 일로 인해 검에는 저주가 내렸고 모그레인도 켈투자드의 기사가 되어버렸지. 그때 난 살아남으면 반드시 이 극악무도한 범죄의 진상을 세상에 밝힌다고 맹세했소. 부패하여 온갖 전염병균이 득실거리는 스컬지 시체 밑에 꼬박 이틀 동안 깔려 있으면서 난 파괴된 도시를 벗어날 힘을 최대한 비축했소이다.', `MaleText_loc4`='剑与莫格莱尼是一个整体。你能理解吗？这个令圣剑蒙羞的堕落之举最终导致了莫格莱尼自身灵魂的堕落，成为了克尔苏加德手下的一位死亡骑士。我发誓如果当时我还能动，我一定会把事件的真相公布于众。可接下来的两天，我一直被埋在了天灾军团士兵的尸体之下，并最终也受到了感染，不过这也令我能够安然离开那座被疯狂与邪恶彻底占据了的城市。', `MaleText_loc5`='那把劍和莫格萊尼是一個整體。你明白嗎?這樣的行為腐敗了那把劍並讓莫格萊尼自身的腐敗成為科爾蘇加德的死亡騎士。我發誓如果我還活著，我會揭發這項可憎罪行的始作俑者。我仍在天譴軍團的腐敗和感染之下的這兩天 - 聚集越多力量越好一起逃離這個夷平的城市。', `MaleText_loc7`='La espada y Mograine formaban un todo. ¿Comprendes? Esta acción corrompió el acero. Mograine corrió la misma suerte convertido ya en un caballero de la Muerte de Kel''Thuzad. Juro que si estuviera vivo, desenmascararía a los que perpetraron este atroz crimen. Permanecí durante dos días bajo la podredumbre de la Plaga, reuniendo fuerzas para escapar de la ciudad arrasada.' WHERE `ID`=12506;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래서 탈출했습니까?', `MaleText_loc4`='你成功了……', `MaleText_loc5`='你成功了...', `MaleText_loc7`='Y lo conseguiste...', `FemaleText_loc1`='그래서 탈출했나요?', `FemaleText_loc4`='你成功了……', `FemaleText_loc5`='你成功了...', `FemaleText_loc7`='Y lo conseguiste...' WHERE `ID`=12507;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탈출했지. 당황한 그분의 아들이 나를 보지 못한 덕분에 붉은십자군 수도원으로 돌아올 수 있었소. 수도원에 들어서자마자 난 비명에 가까운 소리를 질렀지. 내 말에 귀 기울이는 사람이라면 누구든지 붙잡고 진실을 알렸소. 놈들이 알면 목숨을 건질 수 없는 걸 알기에 붉은십자군의 어두운 비밀을 간직한 이곳으로 숨어들었소이다. 하지만, 당시에도 내 말에 귀를 기울이며 믿어 주는 사람들도 있었소. 그렇게 해서 은빛 여명회가 탄생한 것이오.', `MaleText_loc4`='是的，我成功了，为了让小莫格莱尼的罪行得到惩罚，我徒步走回了血色修道院。我在大厅里高声说出了一切，我向所有关心事实的人宣布了真相。随后我就被灭口了，尸体被拖进了这个组织内无人知道的秘密房间。但有一些人听了我的话，他们理解了一切的真相，于是就有了银色黎明……', `MaleText_loc5`='是的，我成功了，為了讓小莫格萊尼的罪行得到懲罰，我找到了回血色修道院的路。我大喊大叫。我把故事告訴每一個願意聽的人。我有可能為此被冷血地謀殺，拖進這個組織內無人知道的黑暗秘密。但有些人聽了...有些人聽了我的話。因此產生了銀色黎明...', `MaleText_loc7`='Así es. Mal que le pesara al joven Mograine, conseguí llegar al Monasterio Escarlata. Grité y grité, y proclamé a los cuatro vientos lo que había ocurrido por si alguien podía escucharme. Pero me asesinaron a sangre fría y me encerraron en esta cámara, convirtiéndome en el oscuro secreto de la orden. Pero algunos escucharon mis palabras. De este modo nació El Alba Argenta.' WHERE `ID`=12508;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 믿을 수 없는 이야기군요. 그렇다면 이 검은 구원을 받을 수 없는 겁니까?', `MaleText_loc4`='你的故事实在是令人难以置信，法尔班克斯？那把剑后来怎样了？已经无法拯救了吗？', `MaleText_loc5`='你說了一個不可思議的故事，法爾班克斯。那把劍怎麼了?無法贖回了嗎?', `MaleText_loc7`='Tu relato es apasionante, Ribalimpia. ¿Y qué ocurre con la espada? ¿Ya no tiene salvación?', `FemaleText_loc1`='정말 믿을 수 없는 이야기군요. 그렇다면 이 검은 구원을 받을 수 없는 건가요?', `FemaleText_loc4`='你的故事实在是令人难以置信，法尔班克斯？那把剑后来怎样了？已经无法拯救了吗？', `FemaleText_loc5`='你說了一個不可思議的故事，法爾班克斯。那把劍怎麼了?無法贖回了嗎?', `FemaleText_loc7`='Tu relato es apasionante, Ribalimpia. ¿Y qué ocurre con la espada? ¿Ya no tiene salvación?' WHERE `ID`=12509;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무래도 당신 손에 들려 있는 그 검은 구원받기엔 틀린 것 같소. 원한의 골이 너무 깊단 말이오. 하지만, 희망을 버리진 마시오, $c! 끝이 있으면 시작도 있는 법이오.$B$B더 없이 독실하고 신앙심이 깊은 그분의 아들을 찾으시오. 그가 타락한 고대의 검 없이도 파멸의 인도자를 새로 만들 수 있다는 소문이 있소.', `MaleText_loc4`='我担心你手中的这把剑已经没法挽回了，它的仇恨太深重。但是不要灰心，$c。事情总是柳暗花明的。$B$B去找到他的儿子——你可能从来没见过如此虔诚的人。据说他可以铸造一把全新的灰烬使者，而不需要这把被玷污的剑。', `MaleText_loc5`='我擔心你手裡握著的那把劍已無法挽救了。仇恨已經太深。但別失去希望，$c。上蒼關起一扇窗就會為你開啟另一扇門。$B$B找到他的兒子 - 你永遠也找不到那樣虔誠和忠心的人了。據說他可以不需要舊的那把被玷污的劍，就能建造一把新的灰燼使者。', `MaleText_loc7`='Me temo que no. El odio ha calado a fondo en la espada que tienes en tus manos. Pero no pierdas la esperanza, $c. Cuando un capítulo se acaba, da comienzo otro nuevo.$B$BEncuentra a su hijo, el hombre más devoto que jamás hayas conocido. Se rumorea que es capaz de reconstruir la Crematoria sin tan siquiera utilizar la vieja y mancillada hoja.' WHERE `ID`=12510;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 아들도 이미 죽었잖아요.', `MaleText_loc4`='但他的儿子已经死了。', `MaleText_loc5`='但他的兒子死了。', `MaleText_loc7`='Mas su hijo está muerto.', `FemaleText_loc1`='그 아들도 이미 죽었잖아요.', `FemaleText_loc4`='但他的儿子已经死了。', `FemaleText_loc5`='但他的兒子死了。', `FemaleText_loc7`='Mas su hijo está muerto.' WHERE `ID`=12511;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<고개를 젓는 종교재판관 페어뱅크스>$B$B아니오, $r! 그분의 아들 중 한 명만 죽었을 뿐이오. 한 명은 아직 살아 있지.$B$B<하늘을 가리키는 종교재판관 페어뱅크스>$B$B아웃랜드... 그곳으로 가서 그를 찾으시오.', `MaleText_loc4`='<大检察官法尔班克斯摇了摇头。>$B$B不，$r，他的一个儿子死了。但另一个还活着……$B$B<大检察官法尔班克斯抬起手指向了天空。>$B$B外域……去那里找他吧……', `MaleText_loc5`='<高階審判官法爾班克斯搖搖他的頭。>$B$B不，$r;他的兒子只有一個死了。其他還活著...$b$b<高階審判官法爾班克斯指向天空。>$B$B外域...到那裡找他...', `MaleText_loc7`='<El Gran Inquisidor Ribalimpia niega con la cabeza.>$B$BNo, $r; solo uno de sus hijos está muerto. El otro sigue con vida...$B$B<El Gran Inquisidor Ribalimpia señala al cielo.>$B$BTerrallende... lo encontrarás allí...' WHERE `ID`=12512;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='', `MaleText_loc4`='', `MaleText_loc5`='', `MaleText_loc7`='' WHERE `ID`=12513;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 고맙다는 듯이 고개를 끄덕거립니다.', `MaleText_loc4`='%s感激地点了点头。', `MaleText_loc5`='%s感激地點點頭。', `MaleText_loc7`='%s asiente atentamente.' WHERE `ID`=12514;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 매우 기뻐하는 것 같습니다.', `MaleText_loc4`='%s有些兴奋过头了。', `MaleText_loc5`='%s看起來極為開心。', `MaleText_loc7`='%s rebosa de alegría.' WHERE `ID`=12516;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 어찌할 바를 모르겠다는 표정입니다.', `MaleText_loc4`='%s困惑不已。', `MaleText_loc5`='%s看起來很困惑。', `MaleText_loc7`='El %s parece confuso.' WHERE `ID`=12517;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 어지러워합니다.', `MaleText_loc4`='%s茫然不知所措。', `MaleText_loc5`='%s看起來失去方向。', `MaleText_loc7`='El %s parece desorientado.' WHERE `ID`=12518;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 주변을 서성거립니다.', `MaleText_loc4`='%s漫无目的地闲逛。', `MaleText_loc5`='%s漫無目的地閒晃。', `MaleText_loc7`='%s deambula sin rumbo fijo.' WHERE `ID`=12519;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1은;는; 수정의 효과에 개의치 않는 듯합니다.', `MaleText_loc4`='%s似乎对疫苗水晶毫不在意。', `MaleText_loc5`='%s看起來不介意水晶的作用。', `MaleText_loc7`='A %s no parece que le importen los efectos del cristal.' WHERE `ID`=12520;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1은;는; 방금 벌어진 일이 매우 불쾌하다는 표정입니다.', `MaleText_loc4`='%s对刚才发生的事感到不快。', `MaleText_loc5`='%s不太喜歡剛剛發生的事。', `MaleText_loc7`='Al %s no le ha gustado lo que acaba de ocurrir.' WHERE `ID`=12521;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 주사를 맞고 흥분합니다.', `MaleText_loc4`='%s受到了疫苗水晶的刺激。', `MaleText_loc5`='%s被注射後變的很激動。', `MaleText_loc7`='%s se agita por la inoculación.' WHERE `ID`=12522;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저장된 세계 상태: $2285W', `MaleText_loc4`='目前世界安全状况：$2285W', `MaleText_loc5`='目前世界安全狀態:$2285W', `MaleText_loc7`='estado del mundo guardado: $2285W' WHERE `ID`=12523;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$C|1이여;여;, 블러드 엘프와 관련해서 이 사업을 연구할 시간이 좀 필요합니다. 그동안 다른 일을 처리하고 계십시오.', `MaleText_loc4`='$C，这件事可能跟血精灵有关，我需要一点时间研究下。在此期间，你或许可以做做别的事情？', `MaleText_loc5`='$C，我需要一點時間看看這個可行的血精靈生意。或許你現在有別的任務要進行?', `MaleText_loc7`='$C, tendré que dedicar algo de tiempo a investigar este posible negocio sobre los elfos de sangre. ¿Tal vez tengas algo que hacer mientras tanto?' WHERE `ID`=12524;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 고결한 빛의 정신을 따르는 길은 여러 가지라네. 이 세계의 법도를 따르든지, 아니면 다른 세계의 것을 따르든지, 선택은 $g형제:자매;의 몫일세.', `MaleText_loc4`='圣光为我们指引了许多道路，$C。你必须决定要走哪一条。', `MaleText_loc5`='條條大路通聖光，$c。你一定要決定跟隨這世界上的哪一條路，在其他世界也是。', `MaleText_loc7`='Muchos son los caminos de la Luz, $c. Debes decidir cuál seguir en este mundo o en cualquier otro.' WHERE `ID`=12525;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대가 우리 마을에서 명성을 쌓아갈수록, 저는 그대가 사용할 수 있는 물건을 더 많이 만들 수 있습니다. 요즘은 공급이 너무 부족해서 우리가 신뢰하는 이에게만 물건을 제공할 수 있거든요.', `MaleText_loc4`='$C，你的名声越来越响，因此我可以为你提供更多的货物。在物资短缺的情况下，我只能为那些获得我们信任的人服务。', `MaleText_loc5`='如果你能在我們的城鎮獲得越多名聲，我就能讓你得到越多的東西，$n。由於我們的裝備短缺所以只能提供給我們信任的人。', `MaleText_loc7`='A medida que te vayas ganando un nombre en nuestra ciudad podré ofrecerte más artículos, $n. Disponemos de pocas reservas de equipo y solo podemos permitirnos ofrecérselas a gente en quien confiemos.' WHERE `ID`=12526;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='브레디갈, 제가 어떤 물건을 구입할 수 있는지 보여주십시오.', `MaleText_loc4`='让我看看我可以买什么，弗雷迪加。', `MaleText_loc5`='讓我知道我佔有什麼樣的優勢，衛迪克。', `MaleText_loc7`='Muéstrame lo que puedo ver, Vredigar.', `FemaleText_loc1`='브레디갈, 제가 어떤 물건을 구입할 수 있는지 보여주세요.', `FemaleText_loc4`='让我看看我可以买什么，弗雷迪加。', `FemaleText_loc5`='讓我知道我佔有什麼樣的優勢，衛迪克。', `FemaleText_loc7`='Muéstrame lo que puedo ver, Vredigar.' WHERE `ID`=12527;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 파괴된 우리 땅에 피난처를 제공하고 있습니다.', `MaleText_loc4`='我尽量在这块破碎的大地上提供庇护所。', `MaleText_loc5`='我盡可能的在我們破碎的大地提供避難所。', `MaleText_loc7`='Ofrezco el refugio que puedo en nuestras tierras destruidas.', `FemaleText_loc1`='저는 파괴된 우리 땅에 피난처를 제공하고 있어요.', `FemaleText_loc4`='我尽量在这块破碎的大地上提供庇护所。', `FemaleText_loc5`='我盡可能的在我們破碎的大地提供避難所。', `FemaleText_loc7`='Ofrezco el refugio que puedo en nuestras tierras destruidas.' WHERE `ID`=12528;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='만나서 정말 반갑습니다! 이곳은 너무 섬뜩한 느낌이 들어서요. 여기 계시는 동안 포세이큰이라고 불리는 이들이 주는 다양한 기회를 놓치지 마십시오.', `MaleText_loc4`='$G兄弟:姐妹;，很高兴见到你！这地方令人毛骨悚然。去帮助那些所谓的被遗忘者吧，别错过这样的好机会。', `MaleText_loc5`='很高興看到你，$g兄弟:姐妹;!這個地方令我很不自在。當你在這裡，記得要好好利用這些所謂被遺忘者所提供的許多機會。', `MaleText_loc7`='¡Me alegro de verte, $g hermano : hermana;! Este lugar me aterroriza. Mientras estás aquí, asegúrate de aprovechar las oportunidades que estos Renegados ofrecen.' WHERE `ID`=12529;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 잘못이 아닙니다... 제 잘못이 아니라고요!$B$B제가 하라는 대로만 했으면 괜찮았을 겁니다. 하지만, 그러지 않았죠! 제 말은 조금도 들으려 하지 않았습니다.$B$B결국 그들은 모두 죽었습니다.$B$B집으로 돌아가고 싶습니다. 실버문으로 돌아가고 싶어요. 너무 지쳤습니다.', `MaleText_loc4`='这不是我的错……这不是我的错！$B$B如果他们按照我所说的去做，那么一切都会如预期那样的。但是，不。他们不听。$B$B现在他们全都死了。$B$B我只想回家，回银月城的家。我太累了。', `MaleText_loc5`='不是我的錯...那不是我的錯!!!$B$B如果他們照著我的話做一切都不會有事。但是不!他們根本不聽。$B$B現在他們都死了。$B$B我只想回家。回到銀月城的家。我累垮了。', `MaleText_loc7`='No es culpa mía... ¡¡¡NO ES CULPA MÍA!!!$B$BSi hubieran hecho lo que les dije, todo habría ido bien. ¡Pero no! No me escucharon.$B$BAhora están todos muertos.$B$BSolo quiero irme a casa. A casa, a Lunargenta. Estoy tan cansado...' WHERE `ID`=12530;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 음식이 준비됐으니 와서 가져가시오...', `MaleText_loc4`='你们的食物好了。过来拿吧……', `MaleText_loc5`='你的工作服準備好了。來拿吧...', `MaleText_loc7`='Tu bebida está lista. Ven a por ella...' WHERE `ID`=12531;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 당신이 나즈그렐 님께 또다시 불평을 했다는 얘기가 들리면 다음번에는 내가 만든 음식을 먹이겠소이다...', `MaleText_loc4`='要是我再听说你们这些差劲的家伙向纳兹格雷尔抱怨的话，那么下次我就会用你们中的一个来做菜……', `MaleText_loc5`='如果我們聽到你這彆腳貨又跑去和納茲格雷爾抱怨，下次你就會成為我們的一道菜餚...', `MaleText_loc7`='Y si vuelvo a oír que guerreros de segunda clase como ustedes se han quejado a Nazgrel, la próxima vez le serviré a uno de ustedes…', `FemaleText_loc1`='그리고 당신이 나즈그렐 님께 또다시 불평을 했다는 얘기가 들리면 다음번에는 내가 만든 음식을 먹이겠소이다...', `FemaleText_loc4`='要是我再听说你们这些差劲的家伙向纳兹格雷尔抱怨的话，那么下次我就会用你们中的一个来做菜……', `FemaleText_loc5`='如果我們聽到你這彆腳貨又跑去和納茲格雷爾抱怨，下次你就會成為我們的一道菜餚...', `FemaleText_loc7`='Y si vuelvo a oír que guerreros de segunda clase como ustedes se han quejado a Nazgrel, la próxima vez le serviré a uno de ustedes…' WHERE `ID`=12532;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$r, 이곳은 휴양지가 아니오. 쉬고 싶으면 침낭을 가져와서 그 입 좀 다물고 있으시오.$B$B그리고 지옥불 반도에서 살고 싶다는 소리는 하지 마시오. 이 험난한 자연에서 당신은 2분도 못 버틸 테니까. 그러면 작은 상자 5개에 담아서 집으로 돌려보내 주겠어.', `MaleText_loc4`='这里不是你的度假地，$r。要是你想休息，拿上你的铺盖卷，然后闭嘴滚蛋。$B$B还有，不要告诉我你想把地狱火当作你的家。你在野外都活不过两分钟。我们会把你分装在五个小盒子里运回家的。', `MaleText_loc5`='這裡不是你度假的地方，$r。如果你想休息，就帶個鋪蓋捲然後閉上你的嘴。$B$B不要告訴我你想在地獄火建立家園。你在野地裡根本生存不了兩分鐘。我們會用五個小箱子把你送回家。', `MaleText_loc7`='Aquí no estás de vacaciones, $r. Si quieres descansar, coge un saco de dormir y cierra el pico.$B$BY no me digas que quieres que el Fuego Infernal sea tu hogar. No vas a durar dos minutos fuera, en las tierras salvajes. Te mandaremos de vuelta a casa en cinco cajitas.' WHERE `ID`=12533;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사실 저는 지옥불 반도에서 살고 싶습니다.', `MaleText_loc4`='事实上，我想让地狱火半岛成为我的家。', `MaleText_loc5`='事實上，我的確想讓地獄火半島成為我的家。', `MaleText_loc7`='En realidad, no quiero hacer de la Península del Fuego Infernal mi hogar.', `FemaleText_loc1`='사실 저는 지옥불 반도에서 살고 싶어요.', `FemaleText_loc4`='事实上，我想让地狱火半岛成为我的家。', `FemaleText_loc5`='事實上，我的確想讓地獄火半島成為我的家。', `FemaleText_loc7`='En realidad, no quiero hacer de la Península del Fuego Infernal mi hogar.' WHERE `ID`=12534;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필요한 물건을 사야 하는데 당신이 파는 물건을 둘러봐도 될까요, 플로이드?', `MaleText_loc4`='我想找些特产。让我看看你的货物，弗洛伊德。', `MaleText_loc5`='我在找一些特別的商品。讓我看看你的貨物，佛洛德。', `MaleText_loc7`='Estoy buscando ciertos productos especializados. Déjame echar un vistazo a tus existencias, Floyd.', `FemaleText_loc1`='필요한 물건을 사야 하는데 당신이 파는 물건을 둘러봐도 될까요, 플로이드?', `FemaleText_loc4`='我想找些特产。让我看看你的货物，弗洛伊德。', `FemaleText_loc5`='我在找一些特別的商品。讓我看看你的貨物，佛洛德。', `FemaleText_loc7`='Estoy buscando ciertos productos especializados. Déjame echar un vistazo a tus existencias, Floyd.' WHERE `ID`=12535;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기는 탁아소가 아니란 말이다, 일꾼. 두 배로 일하라고!', `MaleText_loc4`='这里不是度假圣地，苦工。加快速度！', `MaleText_loc5`='這裡不是安親班，苦工。快跑!', `MaleText_loc7`='Esto no es una guardería, peón. ¡Paso acelerado!' WHERE `ID`=12536;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어이, 뒤통수에 내가 주먹을 날릴 때 경고를 하지 않았다는 말은 하지 마시오. 시험의 골짜기 뒤쪽은 마치 집같이 편안할 테니까 말이야.', `MaleText_loc4`='不要以为我没有警告过你，当我一拳击中你的后脑时，那感觉就像回家，就像回到试炼谷一样。', `MaleText_loc5`='不要說我沒有警告過你，我已經教訓過你了。那感覺就像回到家一樣，回到試煉谷。', `MaleText_loc7`='No digas que no te avisé cuando te metí un puñetazo en la nuca. Te sentirás como en casa, en el Valle de los Retos.' WHERE `ID`=12537;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 이곳을 지옥불이라고 부르는지 깨닫게 해주마.', `MaleText_loc4`='你会知道他们为什么把这地方叫做地狱火的，蠢货！', `MaleText_loc5`='你會明白他們為什麼稱這裡為地獄火，蠢蛋。', `MaleText_loc7`='Vas a aprender por qué llaman a este lugar Llamas Infernales, gusano.' WHERE `ID`=12538;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 냄새 나는 그림자소나무 트롤들을 완벽하게 해치울 수 있는 방법을 찾아야 해!$B$B아, 나쁜 뜻은 없네.$B$B<천진난만한 표정으로 헤벌쭉 웃으며 어깨를 으쓱하는 연금술사>', `MaleText_loc4`='我们必须设法对付那些臭气熏天的暗松巨魔！$B$B哦，我没有冒犯你的意思，$C。$B$B<药剂师带着一脸无辜的笑容耸了耸肩。>', `MaleText_loc5`='我們一定得想出個完美的辦法來對付那些臭影松食人妖。$B$B喔，沒有惡意，$c。$B$B<藥劑師無辜地笑了笑聳聳肩。>', `MaleText_loc7`='Debemos perfeccionar totalmente una forma para tratar con esos apestosos trols Sombrapino.$B$BOh, sin ánimo de ofender, $c.$B$B<El boticario sonríe inocentemente y se encoge de hombros.>' WHERE `ID`=12539;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들이 내 말만 들었어도! 당연히 포상을 받았을 텐데!', `MaleText_loc4`='如果他们听我的话，我早就得到所有我应得的赞美了！', `MaleText_loc5`='他們應該聽我的話才對。然後我就能得到我應得的讚美!', `MaleText_loc7`='Deberían haberme escuchado. ¡Así yo recibiría todos los elogios que merezco!' WHERE `ID`=12540;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 그들에게 분명 큰 소리로 외쳤어요. 후퇴하라고! 공격을 멈추고 물러난 다음 대형을 다시 갖추라고!', `MaleText_loc4`='我没有对他们吼叫吗？撤退！撤退，然后进行火力压制！', `MaleText_loc5`='我剛剛沒有對他們大喊嗎?撤退!撤退然後重新組合強大的火力!!', `MaleText_loc7`='¿No les grité? ¡Retirada! ¡¡Retiraos y reagrupaos con alto el fuego!!' WHERE `ID`=12541;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기는 실버문이 아닙니다! 여기가 어디죠? 아, 잠시 혼란스러웠어요.', `MaleText_loc4`='这不是银月城！我们在哪里？哦，我有点头昏眼花的。', `MaleText_loc5`='這裡不是銀月城!這是哪裡?喔，我剛剛恍神了一下。', `MaleText_loc7`='¡Esto no es Ciudad de Lunargenta! ¿Dónde estamos? Oh, me confundí un instante.' WHERE `ID`=12542;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='순찰자 발란나, 원정순찰대 초소로 돌아가면 그대의 행동에 대해 상세하게 보고하겠습니다! 우리 패배는 전적으로 그대의 책임이며 순찰대장님도 저와 같은 생각일 것입니다.', `MaleText_loc4`='我现在告诉你，当我们回到远行者营地，你的行动会得到全面的清算，游侠瓦兰娜！你要对我们的失败负全责，我确信上尉的想法是和我一样的。', `MaleText_loc5`='讓我告訴你，等我們回到了旅行者營地就會做你的行為總評，遊俠瓦拉娜!你要為我們的損失負責而且我相信隊長也會和我有相同的看法。', `MaleText_loc7`='¡Te lo advierto, cuando volvamos al Enclave del Errante habrá un informe completo de tus acciones, forestal Valanna! Solo tú fuiste responsable de nuestras pérdidas y estoy seguro de que el capitán lo verá de la misma forma que yo.' WHERE `ID`=12543;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='받으세요!', `MaleText_loc4`='看招！', `MaleText_loc5`='接招!', `MaleText_loc7`='¡Toma eso!' WHERE `ID`=12544;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌아가면 분명 칭찬을 받을 거예요. 피해는 약간 보았지만 전체적으로 꽤 잘한 것 같아요. 그렇지 않나요, 발란나?', `MaleText_loc4`='我相信我们在回去的时候会得到一枚奖章的。我们也许经受了一些失败，但总体来说，我觉得我们做得非常好，不是吗，瓦兰娜？', `MaleText_loc5`='我保證我們回去的時候會跟大家推薦的。我們或許有些損失，不過整體而言我想我們做的不錯，對吧，瓦拉娜?', `MaleText_loc7`='Seguro que recibiré elogios cuando regresemos. Sí que hemos sufrido varias pérdidas, pero en general creo que no ha ido mal, ¿no te parece, Valanna?' WHERE `ID`=12545;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맛있군요, 쿠키 씨... 이번에는 다른 때보다 훨씬 좋습니다, 노인장. 지금까지 이렇게 맛있는 말고기는 처음 먹어보네요.', `MaleText_loc4`='太好吃了，曲奇……你这次完全超越了你原有的水平。我从未吃到过味道这么好的马。', `MaleText_loc5`='真美味，廚師...你這次真的勝過自己了，老傢伙。我沒吃過這麼好吃的馬肉。', `MaleText_loc7`='Delicioso, Cocinitas... Esta vez realmente te has superado, viejo. Jamás había probado un caballo tan delicioso.', `FemaleText_loc1`='맛있군요, 쿠키 씨... 이번에는 다른 때보다 훨씬 좋습니다, 노인장. 지금까지 이렇게 맛있는 말고기는 처음 먹어보네요.', `FemaleText_loc4`='太好吃了，曲奇……你这次完全超越了你原有的水平。我从未吃到过味道这么好的马。', `FemaleText_loc5`='真美味，廚師...你這次真的勝過自己了，老傢伙。我沒吃過這麼好吃的馬肉。', `FemaleText_loc7`='Delicioso, Cocinitas... Esta vez realmente te has superado, viejo. Jamás había probado un caballo tan delicioso.' WHERE `ID`=12546;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계피를 조금 넣었나요, 아니면 육두구를 넣었나요? 뭐든 간에 한 가지 확실한 것은 쿠키 씨, 당신만큼 당나귀를 제대로 요리하는 자는 아무도 없다는 겁니다.', `MaleText_loc4`='我是不是尝到了肉桂？还是肉豆蔻？不管是什么，有一件事是肯定的——没有人会像你那样烹驴肉的，曲奇。', `MaleText_loc5`='我發現了肉桂的蹤跡嗎?還是肉豆蔻?不管那是什麼，確定的一點是 - 沒有人像你這樣料理驢子的，廚師。', `MaleText_loc7`='¿Detecto una pizca de canela? ¿O es nuez moscada? Sea lo que sea, hay algo seguro – nadie guisa un burro como tú, Cocinitas.', `FemaleText_loc1`='계피를 조금 넣었나요, 아니면 육두구를 넣었나요? 뭐든 간에 한 가지 확실한 것은 쿠키 씨, 당신만큼 당나귀를 제대로 요리하는 자는 아무도 없다는 겁니다.', `FemaleText_loc4`='我是不是尝到了肉桂？还是肉豆蔻？不管是什么，有一件事是肯定的——没有人会像你那样烹驴肉的，曲奇。', `FemaleText_loc5`='我發現了肉桂的蹤跡嗎?還是肉豆蔻?不管那是什麼，確定的一點是 - 沒有人像你這樣料理驢子的，廚師。', `FemaleText_loc7`='¿Detecto una pizca de canela? ¿O es nuez moscada? Sea lo que sea, hay algo seguro – nadie guisa un burro como tú, Cocinitas.' WHERE `ID`=12547;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 황천에라도 간 것 같았지요. 목욕은커녕 세수도 한 번 안 한 뚱뚱한 타우렌이 내 목구멍으로 썩은 트레샤돈 시체 맛의 음식을 밀어넣는 그런 느낌 말입니다...', `MaleText_loc4`='吃了它，我就好像死后去了虚空一样；那东西尝起来就像腐烂的内脏，被一个从未洗过手或洗过澡的牛头胖子塞进我的喉咙一样……', `MaleText_loc5`='那感覺好像我死了並進入虛空;然後有個肥胖的牛頭人將吃起來像腐爛的蛇頸龍肉的工作服塞進我喉嚨裡，用他那從來不洗的手 - 也從不沐浴...', `MaleText_loc7`='Sabe como si me hubiera muerto y estuviera en el Vacío; donde un tauren que nunca se ha lavado las manos – ni se ha bañado – me hará tragar una bazofia que sabe a trillanodonte muerto podrido...', `FemaleText_loc1`='정말 황천에라도 간 것 같았지요. 목욕은커녕 세수도 한 번 안 한 뚱뚱한 타우렌이 내 목구멍으로 썩은 트레샤돈 시체 맛의 음식을 밀어넣는 그런 느낌 말입니다...', `FemaleText_loc4`='吃了它，我就好像死后去了虚空一样；那东西尝起来就像腐烂的内脏，被一个从未洗过手或洗过澡的牛头胖子塞进我的喉咙一样……', `FemaleText_loc5`='那感覺好像我死了並進入虛空;然後有個肥胖的牛頭人將吃起來像腐爛的蛇頸龍肉的工作服塞進我喉嚨裡，用他那從來不洗的手 - 也從不沐浴...', `FemaleText_loc7`='Sabe como si me hubiera muerto y estuviera en el Vacío; donde un tauren que nunca se ha lavado las manos – ni se ha bañado – me hará tragar una bazofia que sabe a trillanodonte muerto podrido...' WHERE `ID`=12548;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 그 전통적인 방법이라는 겁니까, 쿠키 씨? 우리가 꼭 뭐 같은 맛이 나는 나무껍질을 먹어야 할 만큼 물자가 부족합니까?', `MaleText_loc4`='这也叫菜啊，曲奇？是不是因为我们的补给太少了，所以你给我们吃粪便加木屑啊？', `MaleText_loc5`='這就是我們的問題嗎，廚師?我們缺乏物資到你只能給我們吃無味的木頭屑片嗎?', `MaleText_loc7`='¿A esto hemos llegado, Cocinitas? ¿Tenemos tan pocas existencias que has recurrido a alimentarnos con astillas de madera con sabor a estiércol?', `FemaleText_loc1`='이게 그 전통적인 방법이라는 겁니까, 쿠키 씨? 우리가 꼭 뭐 같은 맛이 나는 나무껍질을 먹어야 할 만큼 물자가 부족합니까?', `FemaleText_loc4`='这也叫菜啊，曲奇？是不是因为我们的补给太少了，所以你给我们吃粪便加木屑啊？', `FemaleText_loc5`='這就是我們的問題嗎，廚師?我們缺乏物資到你只能給我們吃無味的木頭屑片嗎?', `FemaleText_loc7`='¿A esto hemos llegado, Cocinitas? ¿Tenemos tan pocas existencias que has recurrido a alimentarnos con astillas de madera con sabor a estiércol?' WHERE `ID`=12549;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위장이 음식을 토해내지 않고 버텨만 주면 되니까, 죄수들에게 주고 남은 음식이라도 주세요. 이... 이 음식을 주다니 정말 모욕적이군요.', `MaleText_loc4`='要不是我的胃在咕咕叫，我才不会碰这些给犯人吃的……食物。', `MaleText_loc5`='如果不是我的胃威脅要自己移出我的身體，把我像廢物一樣留下拿給那些囚犯，我可能就會被這個...這個食物給羞辱了。', `MaleText_loc7`='Si mi estómago no amenazara con salírseme del cuerpo y abandonarme por la basura que damos a los prisioneros, me ofendería esta... esta comida.', `FemaleText_loc1`='위장이 음식을 토해내지 않고 버텨만 주면 되니까, 죄수들에게 주고 남은 음식이라도 주세요. 이... 이 음식을 주다니 정말 모욕적이군요.', `FemaleText_loc4`='要不是我的胃在咕咕叫，我才不会碰这些给犯人吃的……食物。', `FemaleText_loc5`='如果不是我的胃威脅要自己移出我的身體，把我像廢物一樣留下拿給那些囚犯，我可能就會被這個...這個食物給羞辱了。', `FemaleText_loc7`='Si mi estómago no amenazara con salírseme del cuerpo y abandonarme por la basura que damos a los prisioneros, me ofendería esta... esta comida.' WHERE `ID`=12550;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노움도 너보다는 부지런하게 일한다! 삐삐 머리를 한 어린 여자 노움도 말이다! 빨리... 빨리 움직여라!', `MaleText_loc4`='扎着马尾巴辫的侏儒小姑娘工作起来都比你们这些苦工努力！！给我快一点！快一点！', `MaleText_loc5`='我看過比你更認真工作的地精，苦工!小地精女孩 - 長著豬的尾巴!快!快!快!', `MaleText_loc7`='¡He visto gnomos trabajar más duro que tú, patán! ¡Niñas gnomo pequeñitas con rabo de cerdo! ¡VAMOS, VAMOS, VAMOS!' WHERE `ID`=12551;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고위집행관이여, 그대가 주장하는 전면 공격에는 생각보다 엄청난 희생이 따를 것이오. 좀 더 치밀한 전략이 필요하오. 마을부터 시작해서 주변 영토도 되찾고, 적군이 데솔름까지 이르는 길목을 전부 차단하는 그런 전략 말이오.', `FemaleText_loc4`='执行官，你直接进攻的方针会让我们付出惨重的代价，对此我不能接受。我们需要一个调整后的战术，一个可以收回我们领土的战术，并且还要是一个能从村子入手切断戴索姆所有援助力量的战术。', `FemaleText_loc5`='執行者，你直接的攻擊方法會讓我們造成更多傷亡，那是我無法承受的。我們需要另一個更精準的戰略;讓我們能奪回週遭的土地，從村子開始，這樣就能切斷援軍通往死亡之域的路徑。', `FemaleText_loc7`='Ejecutor, tu propuesta de asalto directo nos costará más vidas de lo que me hace sentir cómoda. Se requiere una estrategia con más matices; una que implique que ganemos el territorio circundante, empezando por los pueblos, para aislar todos los puntos de posibles refuerzos a la Ciudad de la Muerte.' WHERE `ID`=12552;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='존경하는 귀부인, 그대는 나처럼 스컬지와 싸워본 경험이 없소. 그래서 우리 여군주께서는 내게 부인을 도와 다르칸을 물리치라 하신 거요. 그러니까 내 말을 잘 듣고 신중히 한번 생각해 보시오.', `MaleText_loc4`='女士，请恕我直言，对抗亡灵天灾，你没有我在行。因此，女王派我来协助你打败达尔坎，请照我说的做吧。', `MaleText_loc5`='恕我直言，夫人，你並沒有像我一樣攻打天譴軍團。因為如此，女士派我來幫你擊敗達克汗，你若能考量一下我要說的話就會很好。', `MaleText_loc7`='Con todo el respeto, mi señora, no ha luchado contra la Plaga, como yo. La señora me designó para ayudarla a vencer a Dar''khan por eso, y haría bien en tener en cuenta lo que tengo que decir.' WHERE `ID`=12553;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절대로 난 동의 못 해. 다르칸은 결국 궁지에 몰려 어떤 지원도 받지 못 할 거요. 데솔름으로 드나드는 길은 하나뿐이지. 당신을 배신한 그놈은 스스로 막다른 곳으로 들어갈 만큼 바보였소. 바로 그 약점 때문에 놈은 내 손에 죽을 거요!', `MaleText_loc4`='我可不这么认为。达尔坎不会得到援兵，他是在作茧自缚，因为戴索姆只有一条道进出。这个叛徒呆在那儿真是蠢到家了，我要宰了他！', `MaleText_loc5`='我強烈反對。達克汗不會得到援軍因為他會遇到瓶頸。死亡之域只有一個出入口。你們的背叛者把自己困在那裡實在很蠢，而我就是要利用那個弱點!', `MaleText_loc7`='No estoy de acuerdo en absoluto. Dar''khan no va a obtener refuerzos porque quedará atrapado en un cuello de botella. solo hay una manera de entrar o salir a la Ciudad de la Muerte. Tu traidor cometió la necedad de dejarse acorralar ahí, ¡y pienso aprovecharlo!' WHERE `ID`=12554;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아우리페러스 부인, 이건 전쟁이오. 어떤 전쟁이든 희생은 따르게 마련이지! 지구라트 두 곳만 지키면 되잖아. 우리는 저주받은 자의 탑으로 쳐들어가서 그곳의 주인을 붙잡을 거요. 그러면 쿠엘탈라스는 다시 당신 것이지.', `MaleText_loc4`='奥莉菲洛丝夫人，这是战争，哪场战争不死人的！我们必须确保鲜血通灵塔和鬼嚎通灵塔的安全。占领诅咒之塔，让敌人尝尝我们的厉害。这样你就能成功夺回奎尔萨拉斯了。', `MaleText_loc5`='這是戰爭，阿莉法娜奧絲夫人，在任何戰爭中都會有人傷亡!我們唯一需要防守的區域就是那兩座通靈塔。我們會用武力拿下詛咒神教之塔和它的主人。然後你就能重新擁有你的奎爾薩拉斯了。', `MaleText_loc7`='¡Esto es la guerra, Dama Aurífera, y en la guerra se perderán muchas vidas! Las únicas áreas que tenemos que asegurar son los dos zigurats. Nos colaremos dentro y ocuparemos la Torre de los Condenados y derrocaremos a su señor por la fuerza. Entonces tendrás tu Quel''Thalas.' WHERE `ID`=12555;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 당신의 원정순찰대가 우리를 지원하기 위해 여기 온 것이라면 받아들이겠소. 하지만, 그들은 동쪽 국경의 그림자소나무 트롤 때문에 바쁘다고 알고 있소. 기다리는 시간이 길어질수록 스컬지는 점점 강해질 것이오.', `MaleText_loc4`='如果你们的这帮远行者是来增援的，我当然欢迎。可他们丝毫不理会东部边界的暗松巨魔，总是忙着各自的闲事。要是我们一直耗下去，亡灵天灾只会变得更强。', `MaleText_loc5`='如果你的遠行者能在這裡支援我們，我會答應。但是，他們自己都在東部邊界忙著和影松食人妖作戰。我們等他們越久，天譴軍團就會變的更強大。', `MaleText_loc7`='Y si tus Errantes vinieran a apoyarnos, me parecería bien, pero en cambio lo que hacen es entretenerse con los trols Sombrapino de tu frontera oriental. Cuanto más les esperemos, más se fortalecerá la Plaga.' WHERE `ID`=12556;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='포세이큰 지원군이 도착할 때까지 얼마나 남았소? 이곳에서 우리 처지가 위태로운 상황이오. 당신의 여군주는 우리에게 더 많은 병력을 약속했소. 데솔름과 스컬지에게 전력을 집중해야 해!', `FemaleText_loc4`='遗忘者的增援还有多久才能到达？我们在这里的形势危如累卵。你的女王曾承诺给我们更多的士兵，我们必须要把注意力集中在戴索姆和天灾军团上！', `FemaleText_loc5`='被遺忘者援軍還有多久才會趕到?我們在這裡的情勢很緊張。你的女士向我們保證會派來更多士兵。我們一定要把注意力集中在死亡之域和天譴軍團!', `FemaleText_loc7`='¿Cuánto falta para que lleguen los refuerzos de los Renegados? Estamos en una posición débil. Tu Señora nos prometió más soldados. ¡Necesitamos podernos concentrar únicamente en la Ciudad de la Muerte y la Plaga!' WHERE `ID`=12557;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말싸움이 하고 싶나 보군. 그래. 지원 병력이 더 있으면 좋겠지. 하지만, 트롤을 상대로 무의미한 충돌이나 일삼고 있는 원정순찰대들을 데려오는 편이 더 빠를 텐데...', `MaleText_loc4`='我认为你正在和我争论，不过如果我们有更多增援的话，那的确是件好事。但我的意见和你相反，把远行者们从他们和巨魔的那些无意义的冲突中拉回来不是更好吗？', `MaleText_loc5`='我相信你是在幫我想理由，但沒錯如果我們增加多點援軍會很好。我想反駁你的說法，我不認為把遠行者從他們與愚蠢食人妖的衝突中調開會比較快。', `MaleText_loc7`='Creo que estás haciendo mi argumento por mí, pero sí, estaría bien que tuviéramos más refuerzos. Lo rebatiría diciendo que sería más rápido apartar a los Errantes de su absurda escaramuza con los trols.' WHERE `ID`=12558;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아우리페러스 귀부인, 우리는 지원부대요. 여군주께서 곧 병력을 더 보내실 거요. 실버문의 지도자들을 설득하여 모든 병력을 소집해 우리에게 지휘권을 넘기도록 해주시오.', `MaleText_loc4`='奥莉菲洛丝夫人，我们是增援部队。女王会及时派遣更多的增援过来。你最好说服银月城将所有的军队集合起来，并交给我们统一调遣。', `MaleText_loc5`='阿莉法娜奧絲夫人，我們是來支援的。女士最好及時多派些人。會比你說服銀月城召集所有軍隊再到這裡聽我們差遣來的好。', `MaleText_loc7`='Dama Aurífera, somos los refuerzos. Puede suceder que la Señora envíe más hombres más adelante. Será mejor que convenza a la ciudad de Lunargenta para que reúna todas sus fuerzas y las ponga a nuestra disposición aquí.' WHERE `ID`=12559;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 말이 옳소. 우리는 스컬지에게만 온 신경을 쏟아야 하지. 트롤과 마을은 무시하고 데솔름에 병력을 집중해야 해! 다르칸을 해치우면 ''우두머리''가 없어진 나머지 스컬지 군대는 급속도로 무너질 거야.', `MaleText_loc4`='你说得对，我们必须将集中精力对付亡灵天灾。别管那些巨魔和村庄了，集中兵力攻击戴索姆！达尔坎一死，那些天灾士兵就会像没头的苍蝇一样不堪一击。', `MaleText_loc5`='你是對的;我們一定要致力於對付天譴軍團。忽略食人妖和村子，把我們的注意力集中在死亡之域!擊敗達克汗後你會看到剩下的天譴軍團全都成為無頭屍體快速倒下。', `MaleText_loc7`='Tienes razón; tenemos que concentrarnos en la Plaga. ¡Ignoremos los trols y las aldeas, y centrémonos en la Ciudad de la Muerte! Ahora que Dar''khan ha sido derrotado, verás que sin su ''cabeza'', el resto del ''cuerpo'' de la Plaga caerá enseguida.' WHERE `ID`=12560;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='포세이큰 지원군? 지금 언더시티 전방에 스컬지들이 퍼져 있소. 이건 블러드 엘프들이 처리할 문제요. 우리 포세이큰은 후방 지원과 조언을 위해 여기 온 것이오.', `MaleText_loc4`='被遗忘者的援军？幽暗城与亡灵天灾的战事频发，兵力已日渐吃紧。不，血精灵目前的窘境恐怕远远比不上被遗忘者。我们是来为你们提供后备力量和建议的。', `MaleText_loc5`='被遺忘者援軍?幽暗城因為四面八方的天譴軍團而拉警報。不，這件事大部份會由血精靈來處理。我們被遺忘者是這裡的支援人手和顧問。', `MaleText_loc7`='¿Refuerzos de los Renegados? Entrañas se dispersa con la Plaga por todas partes. No, esto será un asunto que se trate en gran parte con los elfos de sangre. Nosotros, los Renegados, estamos aquí para proporcionar apoyo y consejo.' WHERE `ID`=12561;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='처음부터 내 생각이 옳았어. 데솔름은 마지막에 처리할 거요. 우리는 유령의 땅부터 지켜야 하오. 적들이 우리 측면과 후방을 노리고 있는데 다르칸과 싸우는데만 매달릴 수는 없소!', `FemaleText_loc4`='不，我是对的。戴索姆应该最后拿下，我们必须首先保卫整个幽魂之地。我不会在腹背受敌的时候派这里的部队去和达尔坎作战。', `FemaleText_loc5`='不，我開始是對的。死亡之域一定要最後處理。我們一定要先保衛整個鬼魂之地。我不會把這裡的軍隊調去對抗達克汗讓我們腹背受敵!', `FemaleText_loc7`='No, yo tenía razón, para empezar. La Ciudad de la Muerte debe ser la última. Primero debemos proteger todas las tierras fantasma. ¡No destinaré las fuerzas a una batalla contra Dar''khan con enemigos a los lados y en la retaguardia!' WHERE `ID`=12562;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뒤를 조심하라!', `MaleText_loc4`='小心你的背后，朋友！', `MaleText_loc5`='小心你後面，老兄!', `MaleText_loc7`='¡Ándate con cuidado, colega!', `FemaleText_loc1`='뒤를 조심하라!', `FemaleText_loc4`='小心你的背后，朋友！', `FemaleText_loc5`='小心你後面，老兄!', `FemaleText_loc7`='¡Ándate con cuidado,colega!' WHERE `ID`=12563;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왔던 길을 잘 확인하라!', `MaleText_loc4`='检查一下你们的脚印！', `MaleText_loc5`='確認你的行蹤!', `MaleText_loc7`='¡Cuidado por dónde andas!', `FemaleText_loc1`='왔던 길을 잘 확인하라!', `FemaleText_loc4`='检查一下你们的脚印！', `FemaleText_loc5`='確認你的行蹤!', `FemaleText_loc7`='¡Cuidado por dónde andas!' WHERE `ID`=12564;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미행당하지 않도록 조심하라!', `MaleText_loc4`='确保你没被跟踪，朋友！', `MaleText_loc5`='確定你沒被人跟蹤，老兄!', `MaleText_loc7`='¡Asegúrate de que no te siguieran!', `FemaleText_loc1`='미행당하지 않도록 조심하라!', `FemaleText_loc4`='确保你没被跟踪，朋友！', `FemaleText_loc5`='確定你沒被人跟蹤，老兄!', `FemaleText_loc7`='¡Asegúrate de que no te siguieran!' WHERE `ID`=12565;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='귀찮은 일을 달고 온 건 아니겠지?', `MaleText_loc4`='没有什么人跟着你吧？', `MaleText_loc5`='你沒牽扯其他事物吧，是嗎?', `MaleText_loc7`='¿No has arrastrado nada dentro contigo, verdad?', `FemaleText_loc1`='귀찮은 일을 달고 온 건 아니겠지?', `FemaleText_loc4`='没有什么人跟着你吧？', `FemaleText_loc5`='你沒牽扯其他事物吧，是嗎?', `FemaleText_loc7`='¿No has arrastrado nada dentro contigo, verdad?' WHERE `ID`=12566;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 한 번 말하지만 귀부인의 전략적 입장에는 절대 동의할 수 없소. 그 계획대로 하면 우리 병력은 너무 분산되오. 그러면 정작 데솔름을 공격할 병력은 얼마 남지 않을 것이오. 그런 전략은 도저히 수행할 수 없소.', `MaleText_loc4`='我再次强烈反对你在战略形势上的观点。你的计划会让我们的力量过于分散，让我们只有一小部分力量来进攻戴索姆。执行这样的战术，我不放心。', `MaleText_loc5`='我還是一樣堅決反對你對戰略情勢的看法。你的計畫會大大削弱我們的軍力。這樣一來我們就只剩下一小批軍力攻打死亡之域。我不能昧著良心去執行這種策略。', `MaleText_loc7`='De nuevo, no estoy en absoluto de acuerdo con tu punto de vista sobre la situación estratégica. Tu plan esparcirá demasiado a nuestras fuerzas. Nos dejará solo con una pequeña fuerza para atacar la Ciudad de la Muerte. No puedo ejecutar tal estrategia y quedarme con la conciencia tranquila.' WHERE `ID`=12567;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 병력을 유령의 땅 전체에 분산하면 데솔름을 공격할 때 거의 힘을 쓰지 못할 것이오. 아우리페러스 귀부인, 안 됩니다. 저는 다르칸을 죽이러 여기 왔고 그 목표를 반드시 이룰 것이오!', `MaleText_loc4`='如果我们的兵力分散在幽魂之地各处，恐怕就根本没法在戴索姆之战发挥任何作用了。不，女士，我是专程为击败达尔坎而来的！', `MaleText_loc5`='由於我們的軍隊遍布整個鬼魂之地，襲擊死亡之域時將會少有助益。不，女士，我來此的目的就是為了要殺掉達克汗!', `MaleText_loc7`='Esparcidas por las Tierras Fantasma, nuestras fuerzas serán de poca utilidad en un ataque a la Ciudad de la Muerte. ¡No, mi señora, estoy aquí para matar a Dar''khan, y eso es lo que pienso hacer!' WHERE `ID`=12568;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전에도 말했잖소. 데솔름에 병력을 집중해야만 만족스러운 성과를 얻을 수 있다고... 다른 목표들은 어떻게든 해낼 수 있소. 부인이 순찰대장 헬리오스에게 그림자소나무 트롤과 싸움을 중지하고 스컬지에만 신경을 쓰라고 말씀해 주시오.', `MaleText_loc4`='我们之前已经吃过苦头了。只有集中火力攻击戴索姆才可能取胜。绝不能将兵力分散到其他战略目标上。我建议你通知赫里奥斯中尉，让他停止跟暗松巨魔的战争，一心一意地对抗亡灵天灾。', `MaleText_loc5`='我們以前就討論過了。只有集中火力突擊死亡之域才會成功。這些其他的目標都是會讓我們分心的。我建議你通知你們的希里歐斯隊長暫停對抗影松食人妖的戰役，將重心放在天譴軍團上。', `MaleText_loc7`='Ya hemos hablado de esto. Solo podemos alcanzar el éxito con un ataque centralizado contra la Ciudad de la Muerte. Estos otros objetivos son distracciones que no nos podemos permitir. Sugiero que informe al Capitán Helios de que debe abandonar la campaña contra los trols Sombrapino y centrarse únicamente en la Plaga.' WHERE `ID`=12569;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 수석요리사가 식사를 준비할 때까지 이 문제는 잠시 접어 두는 게 어떻겠소? 이런 말해서 좀 미안한데 당신 화가 난 것 같군. 기분이 좀 나아지면 회의를 계속하도록 합시다.', `MaleText_loc4`='或许我们应该暂时把问题放一放，先让厨子为你准备一顿美餐如何？你看上去有些不悦的样子，如果你不介意我这么说的话。我们还是等你感觉好点之后再来探讨问题吧。', `MaleText_loc5`='或許我們該暫時把這件事放在一邊等到你的廚子準備好你的餐點?恕我直言你看起來有點被激怒了。我們可以等你比較冷靜後再繼續討論。', `MaleText_loc7`='Tal vez deberíamos dejar el tema por el momento, hasta que tu cocinero te haya preparado la comida. No te lo tomes a mal, pero pareces un poco indignada. Podemos seguir hablando luego, cuando estés más tranquila.' WHERE `ID`=12570;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='말씀 잘 들었소, 마브렌! 하지만 최종 결정은 내 권한이지. 당신의 지원은 고맙지만 전선에 나간 대다수는 우리 블러드 엘프요. 그릇된 판단으로 그들의 목숨을 헛되이 버릴 수는 없소!', `FemaleText_loc4`='我听到你所说的话了，玛尔伦。然而，最终的决定权在我手上。我感谢你的帮助，但是在前线浴血奋战的大部分都是血精灵。我不会让这些生命就这么轻易逝去的。', `FemaleText_loc5`='我聽到你說的話了，瑪弗倫。不過，最後的決定還是掌握在我手上。我感謝你的幫忙，但是在戰線上奮鬥的大多都是血精靈。我不會輕易地讓他們白白送命!', `FemaleText_loc7`='Te entiendo, Mavren. Sin embargo, la decisión final me corresponde a mí. Te agradezco la ayuda, pero la mayoría de vidas en riesgo son de elfos de sangre, ¡y no permitiré que esas vidas se desperdicien como si nada!' WHERE `ID`=12571;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마브렌. 말 돌리지 마시오. 난 방도를 찾아야 해! 원정순찰대는 동원할 수 없고 실버문에서는 이미 나올 만큼 나온 상태요. 그림자소나무 트롤과 줄아만을 무시할 수도 없지. 놈들이 우리 동쪽 국경에 부대를 배치해 놓았단 말이오!', `FemaleText_loc4`='玛尔伦，我不想听借口，我只想要结果！远行者们还没准备好，而银月城所能给予我们的支援也都已经给了，我不能无视那些暗松巨魔和祖阿曼的威胁……他们已经成群结队地穿越了我们东部的领土。', `FemaleText_loc5`='瑪弗倫，我不想聽藉口，我只要結果!遠行者忙不過來而我們現已收到所有要從銀月城弄到的東西。我不能無視於影松食人妖和祖阿曼...他們已在我們東部邊界準備就緒了!', `FemaleText_loc7`='¡Mavren, no quiero excusas, quiero resultados! Los Errantes no están disponibles y hemos recibido todo lo que vamos a obtener de Lunargenta por ahora. No puedo ignorar a los trols Sombrapino y a Zul''Aman... ¡están alineados a lo largo de nuestra frontera oriental!' WHERE `ID`=12572;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고위집행관, 우린 의견이 전혀 일치하지 않는군! 당신이 낸 의견을 검토하여 쿠엘탈라스를 완전히 해방하기 위해 필요한 조치들을 취하겠소. 이 회의는 조만간 계속하도록 하지.', `FemaleText_loc4`='你是否同意我的看法，悉听尊便，高级执行官。我会考虑你的忠告，然后采取我认为必要的手段解放整个奎尔萨拉斯。我们会继续就这个问题讨论下去的。', `FemaleText_loc5`='你大可以不同意我的看法，高階執行官。我會衡量你的忠告，然後我們會按步就班釋放所有奎爾薩拉斯人因為我認為有這個必要。我們下次再繼續商討。', `FemaleText_loc7`='Puedes no compartir mi opinión tanto como quieras, Sumo Ejecutor. Sopesaré tus consejos, y luego tomaré los pasos que me parezcan necesarios para liberar todo Quel''Thalas. Seguiremos con esta discusión próximamente.' WHERE `ID`=12573;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 집행관의 어투에 놀란 것 같습니다!', `FemaleText_loc4`='%s看上去对执行官的语气感到非常震惊！', `FemaleText_loc5`='%s看來對執行官的語調感到驚駭!', `FemaleText_loc7`='¡%s parece horrorizado por el tono del ejecutor!' WHERE `ID`=12574;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1은;는; 괜히 바쁜 척하느라고 애를 씁니다.', `FemaleText_loc4`='%s假装在做别的事情。', `FemaleText_loc5`='%s試著讓她自己忙些別的事。', `FemaleText_loc7`='%s intenta mantenerse ocupada con otros asuntos.' WHERE `ID`=12575;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 고위집행관 마브렌과 죽음추적자 말텐디스 쪽으로 놓인 단검을 응시합니다.', `FemaleText_loc4`='%s怒视着高级执行官玛尔伦和亡灵哨兵玛尔特迪斯的方向。', `FemaleText_loc5`='%s怒視著高階執行官瑪弗倫和亡靈哨兵瑪塔堤斯那個方向的短劍。', `FemaleText_loc7`='%s mira furioso en dirección al sumo ejecutor Marven y el mortacechador Maltendis.' WHERE `ID`=12576;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고위 집행관이 대답을 마치자 %s|1이;가; 코를 킁킁거리며 냄새를 맡습니다.', `FemaleText_loc4`='%s仰起头哼了一声，显示她对高级执行官的回答的不屑。', `FemaleText_loc5`='%s抬高她的鼻子對高階執行官的回答嗤之以鼻。', `FemaleText_loc7`='%s levanta la nariz con una mueca de desdén en respuesta al Sumo Ejecutor.' WHERE `ID`=12577;
