UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 안절부절못하며 겉옷을 만지작거립니다. 회의 중에 오가는 말투에 언짢은 것이 분명합니다.', `MaleText_loc4`='%s心不在焉地摆弄着他的护甲，显然对这场讨论提不起兴趣。', `MaleText_loc5`='%s把玩著他的護甲，明顯地對討論的語氣感到不舒服。', `MaleText_loc7`='%s juguetea con su armadura, mostrando clara incomodidad ante el tono de la discusión.' WHERE `ID`=12588;
