UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 탑 안을 빤히 쳐다보다가 입술을 꽉 깨뭅니다.', `MaleText_loc4`='%s盯着塔内，咬紧了牙关。', `MaleText_loc5`='%s往塔裡凝視然後咬緊他的下頜。', `MaleText_loc7`='%s mira al interior de la torre y aprieta los dientes.' WHERE `ID`=12593;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 캔드리스는 아직도 다르칸을 치러 가지 않을까요? 도대체 언제까지 기다려야 한답니까?', `MaleText_loc4`='为什么坎迪瑞斯还不开始攻击达尔坎？我们在等什么？', `MaleText_loc5`='為什麼坎德立斯還不對付達克汗?我們還在等什麼?', `MaleText_loc7`='¿Por qué no se levanta Kaendris contra Dar''Khan todavía? ¿Qué estamos esperando?' WHERE `ID`=12594;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이도니스, 진정하세요. 경솔한 행동은 아무런 도움이 되지 않아요! 휴식을 좀 취하고 나서 마나 수정구를 사용해 보세요. 기분이 한결 좋아질 테니까.', `FemaleText_loc4`='冷静，伊东尼斯。鲁莽的行动会让我们没有退路的！休息一会，吸取些魔力水晶。你会感觉好些的。', `FemaleText_loc5`='冷靜下來，艾度尼斯。輕率的行為對我們於事無補!休息一下，吸取一些法力水晶。你會覺得好一點。', `FemaleText_loc7`='Cálmate, Idonis. ¡Las acciones descaradas no nos llevarán a ninguna parte! Date un respiro, da golpecitos en algunos cristales de maná. Te sentirás mejor.' WHERE `ID`=12595;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이도니스, 나름대로 이유가 있겠죠. 그는 원정순찰대가 뭔가 발견했다고 믿고 있습니다.', `FemaleText_loc4`='他有他的理由，伊东尼斯。他觉得远行者找到了一些什么东西。', `FemaleText_loc5`='他有他的理由，艾度尼斯。他認為遠行者發現了什麼。', `FemaleText_loc7`='Tiene sus motivos, Idonis. Cree que los Errantes han descubierto algo.' WHERE `ID`=12596;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리는 이 일에 집중해야 합니다. 성소가 능력을 최대한 발휘하기 시작하면 실버문도 지원을 보낼 수밖에 없겠죠. 비전 성소를 작동하기에는 물자가 부족합니다.', `FemaleText_loc4`='我们必须继续专心进行我们的工作。一旦圣殿开始全力运转，银月城就不得不派人来帮忙了。运转中的奥术圣殿总是会缺少补给的。', `FemaleText_loc5`='我們一定要專注於我們的工作。一旦聖所開始以全部的生產力生產，銀月城就會被迫派兵支援。運作秘法聖所缺乏補給。', `FemaleText_loc7`='Debemos mantenernos centrados en nuestro trabajo. En cuanto el sagrario comience a producir a pleno rendimiento, Lunargenta se verá obligada a enviar ayuda. Los sagrarios Arcanos que funcionan escasean.' WHERE `ID`=12597;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 쉼터를 제공하지... 전투로 격앙된 감정을 가라앉히게, $r|1이여;여;. 내 여관을 집처럼 생각하게...', `MaleText_loc4`='放松你的脉搏吧，$r。我的旅店就是你的家……', `MaleText_loc5`='我提供舒適的環境...舒緩你的野性衝動，$r。我的旅店就是你的家...', `MaleText_loc7`='Comercio con la comodidad... Calma tu salvaje impulso, $r. Mi posada es tu hogar...' WHERE `ID`=12598;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋은 제안입니다, 플로이드. 전 이곳 지옥불 반도에 머물고자 합니다.', `MaleText_loc4`='好主意，弗洛伊德。我想把炉石绑定在地狱火半岛。', `MaleText_loc5`='一個不錯的提議，佛洛德。我希望地獄火半島可以成為我的家園。', `MaleText_loc7`='Una oferta excelente, Floyd. Deseo que la Península del Fuego Infernal sea mi hogar.', `FemaleText_loc1`='좋은 제안입니다, 플로이드. 전 이곳 지옥불 반도에 머물고자 합니다.', `FemaleText_loc4`='好主意，弗洛伊德。我想把炉石绑定在地狱火半岛。', `FemaleText_loc5`='一個不錯的提議，佛洛德。我希望地獄火半島可以成為我的家園。', `FemaleText_loc7`='Una oferta excelente, Floyd. Deseo que la Península del Fuego Infernal sea mi hogar.' WHERE `ID`=12599;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원정순찰대원 더스킹, 보고할 내용이 뭔가?', `MaleText_loc4`='远行者达斯金，你有什么事情需要报告吗？', `MaleText_loc5`='遠行者戴斯金，你有什麼事?', `MaleText_loc7`='Errante Crepúsculo, ¿de qué asunto tienes que informar?' WHERE `ID`=12601;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새로운 소식이라도 있나, 더스킹?', `MaleText_loc4`='有什么新消息吗，达斯金？', `MaleText_loc5`='有新消息嗎，戴斯金?', `MaleText_loc7`='¿Alguna novedad, Dusking?' WHERE `ID`=12602;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='편히 쉬게, 원정순찰대원 더스킹. 내게 가져온 새로운 소식이라도 있나?', `MaleText_loc4`='稍息，远行者达斯金。你有什么消息要告诉我？', `MaleText_loc5`='放輕鬆，遠行者戴斯金。你有什麼事情要告訴我?', `MaleText_loc7`='Descansa, Errante Crepúsculo. ¿Qué noticias tienes para mí?' WHERE `ID`=12603;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말해 보게, 원정순찰대원! 어떤 소식을 가져왔나?', `MaleText_loc4`='快说，远行者！你带来了什么消息？', `MaleText_loc5`='出去，遠行者!你帶來了什麼消息?', `MaleText_loc7`='Desembucha, Errante. ¿Qué noticias traes?' WHERE `ID`=12604;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='살데릴 경, 원정순찰대원 솔란나가 제브텔라와 제브노와 공격을 진행 중이라고 알려왔습니다. 그녀는 젊고 유능한 지원자들을 모집해서 그 상황을 해결할 수 있었답니다. 그리고 위층의 연금술사가 트롤 문제를 해결하기 위해 자신이 구상한 방법을 제시했습니다.', `FemaleText_loc4`='长官，远行者索兰娜告诉我，对塞布提拉和塞布努瓦的攻势正在进行中。她招募到了一个可靠的年轻人来帮助她处理各种状况。另外，楼上的药剂师提到一种药剂，他相信那也可以帮到我们解决巨魔。', `FemaleText_loc5`='長官，遠行者索安娜通知我札布泰拉和札布諾瓦的攻擊行動已在進行中。她可以徵召一名有前途的年輕候選人來幫助情勢。另外，樓上的藥劑師提到他有個辦法也可以幫助食人妖。', `FemaleText_loc7`='Señor, la Errante Solanna me informa de que los ataques a Zeb''Tela y Zeb''Nowa están en proceso. Pudo reclutar un candidato joven y prometedor para ayudar con la situación. Además, el herbolario que hay arriba ha mencionado una solución que cree que también debe ayudar con los trols.' WHERE `ID`=12605;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 안절부절못하며 순찰대장 헬리오스의 눈길을 피합니다.', `FemaleText_loc4`='%s慌乱地把目光从赫里奥斯中尉身上转开。', `FemaleText_loc5`='%s坐立不安並將視線從希里歐斯隊長身上移開。', `FemaleText_loc7`='%s se mueve nerviosamente y aparta la mirada del Capitán Helios.' WHERE `ID`=12606;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그게 전부인가, 원정순찰대원?', `MaleText_loc4`='就这些了，远行者？', `MaleText_loc5`='就這樣嗎，遠行者?', `MaleText_loc7`='¿Es eso todo, Errante?' WHERE `ID`=12607;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 고개를 숙여 발가락을 쳐다봅니다.', `FemaleText_loc4`='%s向下看着她的脚。', `FemaleText_loc5`='%s低頭注視著她的腳。', `FemaleText_loc7`='%s baja la mirada.' WHERE `ID`=12608;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아닙니다! 고위집행관이 서명한 공문이 트랜퀼리엔에서 도착했습니다. 동쪽 국경과 트롤을 지키고 있는 원정순찰대를 모두 빼랍니다. 데솔름을 공격하기 위한 발판으로 안딜리엔 영지에 병력을 배치하라는 명령입니다.', `FemaleText_loc4`='不，长官。一封从塔奎林的高级执行官那里送来的署名信。他要求我们从东部边界和巨魔那里撤回所有的远行者部队，他想让我们准备把人员部署在安迪尔林庄园，把那里作为一个对戴索姆进攻的中转站。', `FemaleText_loc5`='不，長官。一封高階執行官瑪弗倫簽署的信件從安寧地送來了。他要求我們調開所有東部邊界和食人妖那裡的遠行者。他要我們準備在安狄里安莊園部署做為突擊死亡之域的臨時基地。', `FemaleText_loc7`='No, señor. Acaba de llegar de Tranquillien una carta firmada por el Sumo Ejecutor. Solicita que apartemos todas las fuerzas Errantes y los trols de la frontera oriental. Quiere que nos preparemos para desplegar los dominios Andilien como una zona de preparación para un ataque a la Ciudad de la Muerte, señor.' WHERE `ID`=12609;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아닙니다, 순찰대장님. 트랜퀼리엔에서 또 다른 공문이 도착했습니다. 이번에도 고위집행관 마브렌 님이 서명하셨습니다. 전에 명령한 대로 그림자소나무 트롤 퇴치 작전에서 원정순찰대를 빼지 않는 이유가 뭐냐고 묻고 있습니다.', `FemaleText_loc4`='不，长官。又一封从塔奎林的信使那里送来的署名信到了。还是由高级执行官玛尔伦签署的。他想知道，为什么我们还没有执行他所下达的把远行军从暗松巨魔方面撤出来的命令，长官。', `FemaleText_loc5`='不，隊長。安寧地信差送來了另一封簽過名的信件。又是高階執行官瑪弗倫簽署的。他要知道為什麼我們還沒如他先前所下令的讓遠行者開始對抗影松食人妖的任務，長官。', `FemaleText_loc7`='No, Capitán. Ha llegado de Tranquillien otra carta firmada por mensajero. Vuelve a estar firmada por el sumo ejecutor Mavren. Quiere saber por qué nos hemos empezado a retirar a los Errantes de sus misiones contra los trols Sombrapino, como ordenó antes, señor.' WHERE `ID`=12610;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아닙니다, 순찰대장님! 트랜퀼리엔에서 또 다른 공문이 도착했습니다. 또 고위집행관 마브렌입니다. 공문에 적힌 말들이 이번에는 아주 ''화려''합니다. 데솔름을 공격하는 데 원정순찰대를 지원하라는 요구를 반복하고 있습니다. 그리고 북쪽의 영원노래 숲에 있는 원정순찰대 산장에도 전령을 보내서 병력을 요청해 보라는 제안입니다.', `FemaleText_loc4`='不，长官！又一封从塔奎林寄出的急件到了。还是高级执行官玛尔伦的，长官。这次信上的语言非常“生动”。他重申了要求我们远征军支援戴索姆方面的命令，而且建议你应该派出一个信使去北面永歌森林的远行者居所，把他们的部队也调过来。', `FemaleText_loc5`='長官，不，長官!又有另一封從安寧地來的急件。又是高階執行官瑪弗倫，隊長。這次信裡的文字非常‘多采多姿’。他重申他的要求也就是要我們引領遠行者對抗死亡之域的勢力，並建議你們該派個人到北邊永歌森林的遠行者居所，召集他們的軍隊。', `FemaleText_loc7`='¡Señor, no, señor! Ha llegado otro informe de Tranquillien. Se trata nuevamente del sumo ejecutor Mavren, capitán. Esta vez el lenguaje de la carta era muy "colorido". Reitera su petición de que formemos a los Errantes en apoyo de los esfuerzos contra la Ciudad de la Muerte y sugiere que usted debería enviar un mensajero al norte, al Retiro del Errante, en el Bosque Canción Eterna, y unirse también a sus fuerzas.' WHERE `ID`=12611;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐라고!? 한 번만 더 얘기하면 천 번째다! 그는 물론이고 그 어떤 포세이큰의 명령도 따르지 않을 것이다! 귀부인 아우리페러스께 편지를 보내도록. 그분이라면 고위집행관에게 이곳 상황을 이해시킬 것이다. 수고했다, 더스킹! 이만 가보도록.', `MaleText_loc4`='什么？！到底要我告诉他多少次！我是不会接受任何从他或者别的什么遗忘者那里下达的命令的！把这里的情况通知给奥莉菲洛丝夫人。也许她会让他知道我们在这里的意义。感谢你让我了解这些，达斯金。解散！', `MaleText_loc5`='什麼!如果我跟他講過，我就跟他講過一千次了!我不接受他的命令，或是任何被遺忘者的命令!寄封信給阿莉法娜奧絲夫人讓她知道狀況。或許她會讓他知道事情在這裡是怎麼辦的。謝謝你讓我知道，戴斯金。解散。', `MaleText_loc7`='¿Qué? ¡Si se lo he dicho una vez, se lo he dicho mil veces! ¡No acato órdenes suyas, ni de ninguno de los Renegados! Envía una carta a la Dama Aurífera poniéndola al corriente de la situación. Quizás ella lo haga saber cómo funcionan las cosas por aquí. Gracias por hacérmelo saber, Dusking. Retírate.' WHERE `ID`=12612;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 고위집행관 마브렌, 점점 짜증이 나는군! 그도 알고 있을 텐데! 도저히 동쪽 국경에서 원정순찰대를 뺄 수 없는 상황이라는 사실과 아우리페러스 귀부인도 내 의견에 전적으로 동의한다는 것을! 아우리페러스 귀부인께서 명령을 내리기 전까지 우리는 여기에서 대기한다. 이상이다! 그만 가 보도록.', `MaleText_loc4`='我对这个高级执行官玛尔伦已经开始感到厌烦了！我想他应该知道，我们是不能把东部的远行者撤出来的。他同样知道奥莉菲洛丝夫人在这件事上是完全赞同我的。除非她说让我们撤走，否则我们会坚持到底。就这样吧，远行者，解散。', `MaleText_loc5`='我對這個高階執行官瑪弗倫感到厭倦了!我們不敢讓遠行者撤退到東邊邊界而他很清楚這點!他也知道阿莉法娜奧絲夫人和我都是這麼想的。除非她說了別的意見，否則我們就是堅守崗位。就這樣了，遠行者，解散。', `MaleText_loc7`='¡Me estoy cansando del sumo ejecutor Mavren! ¡No nos atrevemos a retirar a los Errantes de la frontera oriental, y lo sabe! También sabe que la Dama Aurífera está totalmente de acuerdo conmigo en este asunto. Hasta que ella diga lo contrario, nos mantenemos. Eso es todo, Errante, retírate.' WHERE `ID`=12613;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='병력은 빼지 않는다! 편지야 원하는 만큼 보내라지. 그의 ''전략적'' 계획이 어떤 것인지 아주 잘 알고 있다. 그리고 원정순찰대의 임무에 대해 귀부인과 나의 의견이 전적으로 일치한다는 사실을 그도 잘 알 것이다. 그림자소나무 트롤을 정리하고 난 다음에야 비로소 우리 병력을 데솔름으로 돌릴 것이다. 물론 그들보다 스컬지가 더욱 위협적이지만, 지금은 트랜퀼리엔에서 그들을 잡아두어야 한다. 트롤을 무시하는 것은 자살 행위나 다름없다! 이만 물러가라, 더스킹!', `MaleText_loc4`='我不会被任何人牵着鼻子做任何事的！他可以寄所有他想寄出来的信件，我完全明白他的“战略”计划，而且他知道奥莉菲洛丝夫人和我在远行者的职责问题上的看法完全一致。一旦暗松巨魔们被解决掉，而且只有在那个时候，我们才会分散我们的注意力，到戴索姆那里去帮忙。我知道天灾是个巨大的威胁，但是塔奎林现在已经开始戒备了。忽视那些巨魔简直就是自杀！解散，达斯金。', `MaleText_loc5`='我並沒有強破任何人做任何事!他可以把他想寄的信全部寄出去。我完全了解他的‘策略性’計畫，而他知道我和夫人已對遠行者該做什麼達成共識。一旦影松食人妖被擊敗的時候，也只有那個時候，我們就會將注意力轉移至死亡之域。我知道天譴軍團是更大的威脅，但安寧地會拖延他們的行動。忽視食人妖簡直是自殺的行為!解散，戴斯金。', `MaleText_loc7`='¡No pienso retirar a nadie de nada! Puede enviar todas las cartas que quiera. Soy totalmente consciente de su plan "estratégico", y sabe que la Dama y yo estamos totalmente de acuerdo con lo que tienen que hacer los Errantes. En cuanto nos hayamos ocupado de los trols Sombrapino, y solo entonces, desviaremos nuestra atención a la Ciudad de la Muerte. Sé que los miembros de la Plaga son la mayor amenaza, pero Tranquillien va a tener que mantenerlos a raya de momento. ¡Sería un suicidio ignorar a los trols! Retírate, Dusking.' WHERE `ID`=12614;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='알겠습니다, 순찰대장님!', `FemaleText_loc4`='遵命，长官！', `FemaleText_loc5`='遵命，長官!', `FemaleText_loc7`='¡A sus órdenes, señor!' WHERE `ID`=12615;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$c|1이여;여;, 안녕하십니까! 아직 원정순찰대원 솔란나와 얘기를 나누지 않았다면 꼭 한 번 대화를 나누어 보십시오.', `FemaleText_loc4`='你好，$c。如果你还没有去和远行者索兰娜谈谈的话，就赶快去吧。', `FemaleText_loc5`='哈囉，$c。如果你還沒跟遠行者索安娜談過，那麼你實在應該快去。', `FemaleText_loc7`='Hola, $c. Si aún no lo has hecho, deberías hablar con el Errante Solanna.' WHERE `ID`=12616;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래서 우리가 도착했지. 나와 내 부대는 저 아래 뼈로 덮인 길에서 통상적인 정찰 임무를 수행했지. 우리는 먼저 정찰병을 보내서 위험한 일은 없는지 주변을 살폈소이다.', `MaleText_loc4`='那时，我和其他士兵就在荣耀之路上巡逻，这是我们日常的职责之一。我们派了侦察兵去前面察看情况，以防发生任何危险状况。', `MaleText_loc5`='然後我們 - 我和軍隊，正在骨頭路上做例行的偵察。我們派了斥候先到前面看看，以免有任何危險的東西跑出來。', `MaleText_loc7`='Así que, ahí estábamos – el batallón y yo, haciendo un reconocimiento rutinario por el camino de los huesos. Habíamos enviado al explorador delante para investigar por si aparecía cualquiera cosa peligrosa.' WHERE `ID`=12617;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니나 다를까 정찰병이 돌아와서 길 아래에 오크가 있다고 보고를 했지. 그들은 아직 우리를 발견하지 못했기 때문에 우리가 가서 안면을 터야겠다고 생각했다오.', `MaleText_loc4`='果然，侦察兵急匆匆地跑了回来，说荣耀之路的另一端有一些兽人出没。他们尚未发现我们，因此我们决定立即将这一消息通传到荣耀堡。', `MaleText_loc5`='當然，斥候跑回來，談論著路上的幾個獸人。他們還沒見過我們所以我們認為應該主動和他們熟識。', `MaleText_loc7`='Efectivamente, el explorador volvió corriendo, hablando de algunos orcos al final del camino. Aún no nos habían visto, así que pensamos en ir a conocerlos.' WHERE `ID`=12618;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 오크를 말씀하시는 겁니까, 경비대장님?', `MaleText_loc4`='什么样的兽人？', `MaleText_loc5`='什麼樣的獸人，酋長?', `MaleText_loc7`='¿Qué tipo de orcos, jefe?' WHERE `ID`=12619;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하십니까, $n.', `FemaleText_loc4`='你好，$n。', `FemaleText_loc5`='你好，$n。', `FemaleText_loc7`='Saludos, $n.' WHERE `ID`=12620;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하십니까, 저는 신입입니다.', `FemaleText_loc4`='Hi, I''m a newb.', `FemaleText_loc5`='嗨，我是個新生者。', `FemaleText_loc7`='Hola, soy nuevo.' WHERE `ID`=12621;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 바지가 흘러내린 채로 망치를 들고 그 일을 하는 걸 봤습니다.', `FemaleText_loc4`='I see you did it with your pants down and your hammer in your hand.', `FemaleText_loc5`='我看到你當時的褲子是捲下的而你的錘子在你手中。', `FemaleText_loc7`='Vi lo que hiciste con los pantalones bajados y el martillo en la mano.' WHERE `ID`=12622;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래서 어떻게 됐나요?', `MaleText_loc4`='What further information do you have?', `MaleText_loc5`='你有什麼樣的未來資訊?', `MaleText_loc7`='¿Qué otra información tienes?', `FemaleText_loc1`='그래서 어떻게 됐나요?', `FemaleText_loc4`='What further information do you have?', `FemaleText_loc5`='你有什麼樣的未來資訊?', `FemaleText_loc7`='¿Qué otra información tienes?' WHERE `ID`=12623;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신은 바로 제가 필요로 하는 흑마법사처럼 보이는군요! 사악한 고블린 족장 스날을 해치워야 합니다.', `FemaleText_loc4`='You look like just the Warlock I need! The evil goblin chieftain Snarl must be defeated.', `FemaleText_loc5`='你看起來就是我需要的術士!一定要打敗邪惡的哥布林首領斯納爾。', `FemaleText_loc7`='¡Pareces el tipo de brujo que necesito! Debemos derrotar al malvado jefe goblin Gruños.' WHERE `ID`=12624;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='붉은색의 거대한 괴물! 내가 지금껏 봤던 그 어떤 오크보다도 컸소이다. 울퉁불퉁한 근육에 여기로 비집고 나온 이빨하며...', `MaleText_loc4`='巨大的红色混蛋！比我看到过的任何兽人都要大。肌肉有这么大，獠牙一直到这儿……', `MaleText_loc5`='紅色的大混蛋!比我見過的任何獸人還要大。它的肌肉有這麼大，獠牙有這麼長...', `MaleText_loc7`='¡Enormes bobos rojos! Más grandes que cualquier orco que haya visto. Músculos enormes, colmillos enormes...' WHERE `ID`=12625;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대장님께서 말씀하시는 오크는...', `MaleText_loc4`='你指的是……', `MaleText_loc5`='你是說...', `MaleText_loc7`='Quieres decir que...' WHERE `ID`=12626;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 고개를 끄덕입니다.', `MaleText_loc4`='%s点了点头。', `MaleText_loc5`='%s點點頭。', `MaleText_loc7`='%s asiente con la cabeza.' WHERE `ID`=12627;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맞소, 타락한 오크들이지...', `MaleText_loc4`='邪兽人……', `MaleText_loc5`='魔獄獸人...', `MaleText_loc7`='Viles orcos...' WHERE `ID`=12628;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바닷가재를 보여주십시오!', `MaleText_loc4`='给我看看龙虾！', `MaleText_loc5`='把龍蝦拿來給我看看!', `MaleText_loc7`='¡Muéstrame las langostas!', `FemaleText_loc1`='바닷가재를 보여주세요!', `FemaleText_loc4`='给我看看龙虾！', `FemaleText_loc5`='把龍蝦拿來給我看看!', `FemaleText_loc7`='¡Muéstrame las langostas!' WHERE `ID`=12629;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련을 받고 싶습니다.', `MaleText_loc4`='我需要训练。', `MaleText_loc5`='我想接受訓練。', `MaleText_loc7`='Quiero entrenarme.', `FemaleText_loc1`='훈련을 받고 싶어요.', `FemaleText_loc4`='我需要训练。', `FemaleText_loc5`='我想接受訓練。', `FemaleText_loc7`='Quiero entrenarme.' WHERE `ID`=12630;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물건을 두루 살펴보고 싶습니다.', `MaleText_loc4`='让我看看你的货物。', `MaleText_loc5`='我希望看看你的商品。', `MaleText_loc7`='Me gustaría echar un vistazo a tus mercancías.', `FemaleText_loc1`='물건을 두루 살펴보고 싶어요.', `FemaleText_loc4`='让我看看你的货物。', `FemaleText_loc5`='我希望看看你的商品。', `FemaleText_loc7`='Me gustaría echar un vistazo a tus mercancías.' WHERE `ID`=12631;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='디자이너의 섬에서 살고 싶습니다.', `MaleText_loc4`='我要在这里安度晚年。', `MaleText_loc5`='我希望在設計者之島建立我的家園。', `MaleText_loc7`='Deseo hacer de la isla del diseñador mi hogar.', `FemaleText_loc1`='디자이너의 섬에서 살고 싶어요.', `FemaleText_loc4`='我要在这里安度晚年。', `FemaleText_loc5`='我希望在設計者之島建立我的家園。', `FemaleText_loc7`='Deseo hacer de la isla del diseñador mi hogar.' WHERE `ID`=12632;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 야수를 맡기고 싶습니다.', `MaleText_loc4`='我要存放宠物。', `MaleText_loc5`='我希望能穩定我的寵物。', `MaleText_loc7`='Deseo guardar a mi mascota en el establo.', `FemaleText_loc1`='제 야수를 맡기고 싶어요.', `FemaleText_loc4`='我要存放宠物。', `FemaleText_loc5`='我希望能穩定我的寵物。', `FemaleText_loc7`='Deseo guardar a mi mascota en el establo.' WHERE `ID`=12633;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='죽어라, 쓰레기 같은 흑마법사!', `FemaleText_loc4`='死吧！狗术士！', `FemaleText_loc5`='死，術士人渣!', `FemaleText_loc7`='¡Muere, $gmaldito brujo:maldita bruja;!' WHERE `ID`=12634;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만, 어떻게 그럴 수 있습니까, 경비대장님? 저주가 풀린 줄 알았는데...', `MaleText_loc4`='但是怎么会这样，头儿？诅咒不是已经被消除了吗……', `MaleText_loc5`='但是怎麼會?我以為詛咒已經解除了...', `MaleText_loc7`='Pero, ¿cómo, jefe? Pensaba que la maldición se había levantado...' WHERE `ID`=12635;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나도 모른다오, 친구. 나도 잘 모르겠어...', `MaleText_loc4`='我不知道，士兵。我——不——知道……', `MaleText_loc5`='我不知道，蠻兵。我真的不 - 知道...', `MaleText_loc7`='No lo sé, gruñido. Sencillamente - no – lo sé...' WHERE `ID`=12636;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만, 그게 끝이 아니었소. 우리가 후퇴하기 전에 그 오크 한 패거리가 우리를 발견하고 공격했지.', `MaleText_loc4`='但那还不是最糟糕的。我们还没来得及撤退，他们就发现了我们，并且发起了进攻。', `MaleText_loc5`='但那還不是最糟的。在我們撤退以前，他們一群人發現了我們並發動攻擊。', `MaleText_loc7`='Pero eso no es lo peor. Antes de que pudiéramos reagruparnos, un grupo de ellos nos descubrió y nos atacó.' WHERE `ID`=12637;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그날 내 정예병사들을 여럿 잃었다오...', `MaleText_loc4`='那天我失去了许多最棒的士兵……', `MaleText_loc5`='那天失去了幾個我最出色的士兵...', `MaleText_loc7`='Ese día perdí a algunos de mis mejores soldados...', `FemaleText_loc1`='그날 내 정예병사들을 여럿 잃었다오...', `FemaleText_loc4`='那天我失去了许多最棒的士兵……', `FemaleText_loc5`='那天失去了幾個我最出色的士兵...', `FemaleText_loc7`='Ese día perdí a algunos de mis mejores soldados...' WHERE `ID`=12638;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잔달라 방어구를 잃어버린 거라면 내가 도와줄 수 있네.', `MaleText_loc4`='如果你丢失了任何一件赞达拉护甲，我想我可以帮忙。', `MaleText_loc5`='如果你弄丟了一件贊達拉護甲，我或許可以幫你。', `MaleText_loc7`='Si has perdido una pieza de tu armadura Zandalar, quizás pueda ayudarte.' WHERE `ID`=12639;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진로크, 잔달라 구원자의 가슴보호갑을 잃어버렸습니다. 그 갑옷을 하나 구해 주실 수 있습니까?', `MaleText_loc4`='金罗克，我不小心弄丢了我的赞达拉辩护者胸甲，你能给我一件备用的吗？', `MaleText_loc5`='金羅克，恐怕我弄丟了我的贊達拉辯護者胸甲。你能給我一件新的嗎?', `MaleText_loc7`='Jin''rokh, me temo que he perdido mi peto de vindicador Zandalar. ¿Podrías conseguirme otro?', `FemaleText_loc1`='진로크, 잔달라 구원자의 가슴보호갑을 잃어버렸어요. 그 갑옷을 하나 구해 주실 수 있습니까?', `FemaleText_loc4`='金罗克，我不小心弄丢了我的赞达拉辩护者胸甲，你能给我一件备用的吗？', `FemaleText_loc5`='金羅克，恐怕我弄丟了我的贊達拉辯護者胸甲。你能給我一件新的嗎?', `FemaleText_loc7`='Jin''rokh, me temo que he perdido mi peto de vindicador Zandalar. ¿Podrías conseguirme otro?' WHERE `ID`=12640;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진로크, 구원자의 전투장비를 되찾도록 도와주실 수 있습니까?', `MaleText_loc4`='金罗克，我想我需要你帮忙重铸一件赞达拉辩护者套装。', `MaleText_loc5`='金羅克，我需要重新獲得一件辯護者戰裝。', `MaleText_loc7`='Jin''rokh, necesito que me ayudes a recuperar una pieza de Equipo de batalla del Vindicador.', `FemaleText_loc1`='진로크, 구원자의 전투장비를 되찾도록 도와주실 수 있겠어요?', `FemaleText_loc4`='金罗克，我想我需要你帮忙重铸一件赞达拉辩护者套装。', `FemaleText_loc5`='金羅克，我需要重新獲得一件辯護者戰裝。', `FemaleText_loc7`='Jin''rokh, necesito que me ayudes a recuperar una pieza de Equipo de batalla del Vindicador.' WHERE `ID`=12641;
