UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희같이 약해빠진 놈들에게 겁낼 것 같으냐? 너희는 우리 먹이가 될 것이야.', `MaleText_loc4`='好像你们这些脆弱的家伙真能对我们造成威胁似的。看我们生吞活剥了你！', `MaleText_loc5`='你們弱者對我們不會造成任何威脅。我們會毀滅你們。', `MaleText_loc7`='Como si debiluchos como ustedes representaran una amenaza para nosotros. Los devoraremos.' WHERE `ID`=12691;
