UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영원한 삶의 철퇴를 잃어버렸습니다. 새로 주실 수 있으신가요?', `MaleText_loc4`='我弄丢了我的不灭生命之锤。你能再给我一把吗？', `MaleText_loc5`='我弄丟了我的不滅生命之錘。你能給我一個替代品嗎?', `MaleText_loc7`='He perdido mi maza de vida inagotable. ¿Podrías conseguirme otra nueva?', `FemaleText_loc1`='영원한 삶의 철퇴를 잃어버렸습니다. 새로 주실 수 있으신가요?', `FemaleText_loc4`='我弄丢了我的不灭生命之锤。你能再给我一把吗？', `FemaleText_loc5`='我弄丟了我的不滅生命之錘。你能給我一個替代品嗎?', `FemaleText_loc7`='He perdido mi maza de vida inagotable. ¿Podrías conseguirme otra nueva?' WHERE `ID`=12693;
