UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밝혀진 비밀의 칼날을 잃어버렸습니다. 새로 주실 수 있으신가요?', `MaleText_loc4`='我弄丢了我的魔法秘密之刃。你能再给我一把吗？', `MaleText_loc5`='我弄丟了我的魔法秘密之刃。你能給我一個替代品嗎?', `MaleText_loc7`='He perdido mi espada de secretos oscuros. ¿Podrías conseguirme otra nueva?', `FemaleText_loc1`='밝혀진 비밀의 칼날을 잃어버렸습니다. 새로 주실 수 있으신가요?', `FemaleText_loc4`='我弄丢了我的魔法秘密之刃。你能再给我一把吗？', `FemaleText_loc5`='我弄丟了我的魔法秘密之刃。你能給我一個替代品嗎?', `FemaleText_loc7`='He perdido mi espada de secretos oscuros. ¿Podrías conseguirme otra nueva?' WHERE `ID`=12695;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영원한 정의의 칼날을 잃어버렸습니다. 새로 주실 수 있으신가요?', `MaleText_loc4`='我弄丢了我的永恒公正长剑。你能再给我一把吗？', `MaleText_loc5`='我弄丟了我的永恆公正之刃。你能給我一個替代品嗎?', `MaleText_loc7`='He perdido mi espada de justicia eterna. ¿Podrías conseguirme otra nueva?', `FemaleText_loc1`='영원한 정의의 칼날을 잃어버렸습니다. 새로 주실 수 있으신가요?', `FemaleText_loc4`='我弄丢了我的永恒公正长剑。你能再给我一把吗？', `FemaleText_loc5`='我弄丟了我的永恆公正之刃。你能給我一個替代品嗎?', `FemaleText_loc7`='He perdido mi espada de justicia eterna. ¿Podrías conseguirme otra nueva?' WHERE `ID`=12696;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무한한 지혜의 망치를 잃어버렸습니다. 새로 주실 수 있으신가요?', `MaleText_loc4`='我弄丢了我的无尽智慧之锤。你能再给我一把吗？', `MaleText_loc5`='我弄丟了我的無盡智慧裁決錘。你能給我一個替代品嗎?', `MaleText_loc7`='He perdido mi mazo de sabiduría infinita. ¿Podrías conseguirme otro nuevo?', `FemaleText_loc1`='무한한 지혜의 망치를 잃어버렸습니다. 새로 주실 수 있으신가요?', `FemaleText_loc4`='我弄丢了我的无尽智慧之锤。你能再给我一把吗？', `FemaleText_loc5`='我弄丟了我的無盡智慧裁決錘。你能給我一個替代品嗎?', `FemaleText_loc7`='He perdido mi mazo de sabiduría infinita. ¿Podrías conseguirme otro nuevo?' WHERE `ID`=12697;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형제자매들이여, 나는 약속의 땅에 다녀왔소. 그곳에서 엄청난 힘을 경험했고 더없는 행복을 느꼈소. 너무나 행복하고 황홀한 나머지 신의 꿈을 발견한 것은 아닌가 하는 생각이 들 정도였다오.', `MaleText_loc4`='兄弟姐妹们，我曾去过理想中的乐土。我感受过令人心生敬畏的强大力量。那种被赐福的感觉紧紧环绕，我竟然产生了步入神灵梦境的错觉。', `MaleText_loc5`='兄弟姐妹們，我去過樂土。我嚐過宏偉的能量。我感受過極樂 - 那極樂是那麼的令人全神貫注，我的甚至開始懷疑我是否不小心撞見了神祇的夢想。', `MaleText_loc7`='Hermanos y hermanas, he estado en la tierra prometida. He probado la energía absoluta. He sentido el éxtasis – un éxtasis tan cautivador y sobrecogedor que me quedé preguntándome si había tropezado con los sueños de los dioses.' WHERE `ID`=12698;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어두운 그림자의 단검을 잃어버렸습니다. 새로 주실 수 있으신가요?', `MaleText_loc4`='我弄丢了我的笼罩阴影匕首。你能再给我一把吗？', `MaleText_loc5`='我弄丟了我的朦朧之影匕首。你能給我一個替代品嗎?', `MaleText_loc7`='He perdido mi daga de las sombras ocultas. ¿Podrías conseguirme otra nueva?', `FemaleText_loc1`='어두운 그림자의 단검을 잃어버렸습니다. 새로 주실 수 있으신가요?', `FemaleText_loc4`='我弄丢了我的笼罩阴影匕首。你能再给我一把吗？', `FemaleText_loc5`='我弄丟了我的朦朧之影匕首。你能給我一個替代品嗎?', `FemaleText_loc7`='He perdido mi daga de las sombras ocultas. ¿Podrías conseguirme otra nueva?' WHERE `ID`=12699;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 말씀해 주세요, 말티크. 그게 무엇이죠? 어떤 느낌인가요?', `MaleText_loc4`='玛提克，快说下去。那是什么？感觉怎么样？', `MaleText_loc5`='再多說一點，馬提克。那是什麼?那是什麼感覺?', `MaleText_loc7`='Cuéntanos más, Martik. ¿Qué es? ¿Qué se siente?', `FemaleText_loc1`='더 말씀해 주세요, 말티크. 그게 무엇이죠? 어떤 느낌인가요?', `FemaleText_loc4`='玛提克，快说下去。那是什么？感觉怎么样？', `FemaleText_loc5`='再多說一點，馬提克。那是什麼?那是什麼感覺?', `FemaleText_loc7`='Cuéntanos más, Martik. ¿Qué es? ¿Qué se siente?' WHERE `ID`=12700;
