UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절대자의 크리스를 잃어버렸습니다. 새로 주실 수 있으신가요?', `MaleText_loc4`='我弄丢了我的禁断邪语短剑。你能再给我一把吗？', `MaleText_loc5`='我弄丟了我的禁斷邪語波刃劍。你能給我一個替代品嗎?', `MaleText_loc7`='He perdido mi kris de los nombres prohibidos. ¿Podrías conseguirme otro nuevo?', `FemaleText_loc1`='절대자의 크리스를 잃어버렸습니다. 새로 주실 수 있으신가요?', `FemaleText_loc4`='我弄丢了我的禁断邪语短剑。你能再给我一把吗？', `FemaleText_loc5`='我弄丟了我的禁斷邪語波刃劍。你能給我一個替代品嗎?', `FemaleText_loc7`='He perdido mi kris de los nombres prohibidos. ¿Podrías conseguirme otro nuevo?' WHERE `ID`=12702;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천국에서는 팔을 뻗어서 황천에서 가져오기만 하면 된다오.', `MaleText_loc4`='置身天堂时，你会感觉自己被来回牵扯着，在虚空间飘荡。', `MaleText_loc5`='在那片樂土，你只要伸手就可以從虛空中拿到你想要的東西。', `MaleText_loc7`='En el paraíso, simplemente alargas la mano y tomas del Vacío.' WHERE `ID`=12703;
