UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 고맙습니다! 그대가 없었다면 전 어떻게 해야 했을까요?!', `MaleText_loc4`='非常感谢！要是没有你，我真不知该如何是好！', `MaleText_loc5`='非常謝謝你!如果你不在這裡我真不知道會幹出什麼事來!', `MaleText_loc7`='¡Muchas gracias! ¡No sé que habría hecho si no hubieras estado aquí!' WHERE `ID`=12730;
