UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 춥군요! 이 세상에 온기라고는 남아 있지 않나봐요.', `MaleText_loc4`='真冷！这地方真是一点热气都没有。', `MaleText_loc5`='好冷!這個世界已經沒有溫度了。', `MaleText_loc7`='¡Qué frío! No queda calor en este mundo.', `FemaleText_loc1`='정말 춥군요! 이 세상에 온기라고는 남아 있지 않나봐요.', `FemaleText_loc4`='真冷！这地方真是一点热气都没有。', `FemaleText_loc5`='好冷!這個世界已經沒有溫度了。', `FemaleText_loc7`='¡Qué frío! No queda calor en este mundo.' WHERE `ID`=12733;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보호막이 제 구실을 못했습니다. 어떻게 그런 일이 있을 수 있나요?', `MaleText_loc4`='屏障不起作用。怎么会这样？', `MaleText_loc5`='障礙物並沒有保護我們。怎麼會這樣?', `MaleText_loc7`='La barrera no nos protegió. ¿Cómo ha podido ocurrir?', `FemaleText_loc1`='보호막이 제 구실을 못했습니다. 어떻게 그런 일이 있을 수 있나요?', `FemaleText_loc4`='屏障不起作用。怎么会这样？', `FemaleText_loc5`='障礙物並沒有保護我們。怎麼會這樣?', `FemaleText_loc7`='La barrera no nos protegió. ¿Cómo ha podido ocurrir?' WHERE `ID`=12734;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 왜 여기 남아 있죠? 어서 이 고통을 끝내야 합니다.', `MaleText_loc4`='为什么我还活着？我要终结这种痛苦。', `MaleText_loc5`='我為什麼還在這?這個痛苦一定要結束。', `MaleText_loc7`='¿Por qué me quedo? Este tormento debe finalizar.', `FemaleText_loc1`='제가 왜 여기 남아 있죠? 어서 이 고통을 끝내야 해요.', `FemaleText_loc4`='为什么我还活着？我要终结这种痛苦。', `FemaleText_loc5`='我為什麼還在這?這個痛苦一定要結束。', `FemaleText_loc7`='¿Por qué me quedo? Este tormento debe finalizar.' WHERE `ID`=12736;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 다시 온다! 준비하라!', `MaleText_loc4`='他们又来了！准备！', `MaleText_loc5`='他們又來了!準備好!', `MaleText_loc7`='¡Ya vuelven! ¡Manteneos atentos!' WHERE `ID`=12737;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 당신이 바로 편지를 발견한 분이군요. 소식을 전해 주셔서 감사합니다. 아마도 가족에 대한 소식이겠죠. 음식과 음료를 드릴 테니 마음껏 드세요.', `MaleText_loc4`='啊，就是你找到那封信的吧。感谢你带来这个……关于我的家人的消息。如果我这里的食物和饮料有什么你喜欢的，请别客气。', `MaleText_loc5`='啊，你就是找到信的那個人。謝謝你的...消息，我想應該這麼說，有關我家人的消息。歡迎你享用我提供的食物和飲料。', `MaleText_loc7`='¡Ah! Tú eres quien ha encontrado la carta. Gracias por... las noticias, supongo, de mi familia. Puedes comer y beber de todo lo que hay.', `FemaleText_loc1`='오, 당신이 바로 편지를 발견한 분이군요. 소식을 전해 주셔서 감사합니다. 아마도 가족에 대한 소식이겠죠. 음식과 음료를 드릴 테니 마음껏 드세요.', `FemaleText_loc4`='啊，就是你找到那封信的吧。感谢你带来这个……关于我的家人的消息。如果我这里的食物和饮料有什么你喜欢的，请别客气。', `FemaleText_loc5`='啊，你就是找到信的那個人。謝謝你的...消息，我想應該這麼說，有關我家人的消息。歡迎你享用我提供的食物和飲料。', `FemaleText_loc7`='¡Ah! Tú eres quien ha encontrado la carta. Gracias por... las noticias, supongo, de mi familia. Puedes comer y beber de todo lo que hay.' WHERE `ID`=12738;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오, 당신이 바로 편지를 발견한 분이군요. 소식을 전해 주셔서 감사합니다. 아마도 가족에 대한 소식이겠죠. 음식과 음료를 드릴 테니 마음껏 드세요.', `FemaleText_loc4`='啊，就是你找到那封信的吧。感谢你带来这个……关于我的家人的消息。如果我这里的食物和饮料有什么你喜欢的，请别客气。', `FemaleText_loc5`='啊，你就是找到信的那個人。謝謝你的...消息，我想應該這麼說，有關我家人的消息。歡迎你享用我提供的食物和飲料。', `FemaleText_loc7`='¡Ah! Tú eres quien ha encontrado la carta. Gracias por... las noticias, supongo, de mi familia. Puedes comer y beber de todo lo que hay.' WHERE `ID`=12739;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 한 일에 대한 대가를 원하는 것 같은데, 그런가? 내 생애를 떠올려 보라고? 흥. 내가 가진 거나 가져가고 날 혼자 내버려 두게나.', `MaleText_loc4`='我猜你在期盼些什么报酬吧，是不是？你不就是让我想起了还活着的时候么？哼，算了，从我这里随便拿件东西就赶紧走吧，让我一个人静一静。', `MaleText_loc5`='我猜你想要得到該有的報酬，對吧?提醒我我的生命?。哼。把東西拿走，然後離開。', `MaleText_loc7`='Supongo que querrás algo por lo que hiciste, ¿verdad? ¿Recordarme mi vida? Pfagh. Coge lo que tengo y déjame tranquilo.', `FemaleText_loc1`='자네가 한 일에 대한 대가를 원하는 것 같은데, 그런가? 내 생애를 떠올려 보라고? 흥. 내가 가진 거나 가져가고 날 혼자 내버려 두게나.', `FemaleText_loc4`='我猜你在期盼些什么报酬吧，是不是？你不就是让我想起了还活着的时候么？哼，算了，从我这里随便拿件东西就赶紧走吧，让我一个人静一静。', `FemaleText_loc5`='我猜你想要得到該有的報酬，對吧?提醒我我的生命?。哼。把東西拿走，然後離開。', `FemaleText_loc7`='Supongo que querrás algo por lo que hiciste, ¿verdad? ¿Recordarme mi vida? Pfagh. Coge lo que tengo y déjame tranquila.' WHERE `ID`=12740;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 다른 스컬지 무리를 해치웠다!', `MaleText_loc4`='又一批亡灵天灾被消灭了！', `MaleText_loc5`='又一批天譴軍團被摧毀了!', `MaleText_loc7`='¡Se ha destruido otra partida de miembros de la Plaga!' WHERE `ID`=12741;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해냈다! 롬매스가 빨리 지원병력을 보내야 할 텐데.', `MaleText_loc4`='真糟糕！希望罗曼斯尽快派援军过来。', `MaleText_loc5`='那都結束了!希望洛摩斯會快點派援軍前來。', `MaleText_loc7`='¡Ya está! Con un poco de suerte, Rommath enviará pronto refuerzos.' WHERE `ID`=12742;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s의 피부가 단단해집니다!', `MaleText_loc4`='%s的皮肤变得坚硬起来！', `MaleText_loc5`='%s皮膚變硬!', `MaleText_loc7`='¡La piel de %s se endurece!' WHERE `ID`=12743;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여어! 줄을 서세요, 줄을. 아웃랜드 음식은 내 입에 전혀 맞지 않는군.', `MaleText_loc4`='哎！排队好不好？我一点都吃不惯外域的东西。', `MaleText_loc5`='喂!你排隊好不好?外域的食物一點都不合我胃口。', `MaleText_loc7`='Espera en la cola, ¿de acuerdo? La comida de Terrallende no me sienta nada bien.', `FemaleText_loc1`='여어! 줄을 서세요, 줄을. 아웃랜드 음식은 내 입에 전혀 맞지 않는군요.', `FemaleText_loc4`='哎！排队好不好？我一点都吃不惯外域的东西。', `FemaleText_loc5`='喂!你排隊好不好?外域的食物一點都不合我胃口。', `FemaleText_loc7`='Espera en la cola, ¿de acuerdo? La comida de Terrallende no me sienta nada bien.' WHERE `ID`=12744;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대체 그 안에서 뭘 하는 겁니까? 제발 자비를 베풀어 빨리 좀 나와 주십시오!', `MaleText_loc4`='发生了什么事？？快一点！', `MaleText_loc5`='裡面發生了什麼事??為了聖光之愛，動作快!', `MaleText_loc7`='¿¿Qué está pasando aquí?? ¡Por amor de la LUZ, apresúrate!', `FemaleText_loc1`='대체 그 안에서 뭘 하는 겁니까? 제발 자비를 베풀어 빨리 좀 나와 주십시오!', `FemaleText_loc4`='发生了什么事？？快一点！', `FemaleText_loc5`='裡面發生了什麼事??為了聖光之愛，動作快!', `FemaleText_loc7`='¿¿Qué está pasando aquí?? ¡Por amor de la LUZ, apresúrate!' WHERE `ID`=12745;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='의무병이나 사제를 불러드릴까요? 이보세요, 벌써 한 시간이 넘었단 말입니다!', `MaleText_loc4`='要我叫医生来吗？要不我去找个牧师？亲爱的，这种情况已经持续一小时了！', `MaleText_loc5`='你要我叫醫生來嗎?還是牧師?已經過了一小時了，老兄!', `MaleText_loc7`='¿Quieres llamar a un médico? ¿Quizás a un sacerdote? ¡Ya ha pasado más de una hora!', `FemaleText_loc1`='의무병이나 사제를 불러드릴까요? 이보세요, 벌써 한 시간이 넘었단 말입니다!', `FemaleText_loc4`='要我叫医生来吗？要不我去找个牧师？亲爱的，这种情况已经持续一小时了！', `FemaleText_loc5`='你要我叫醫生來嗎?還是牧師?已經過了一小時了，老兄!', `FemaleText_loc7`='¿Quieres llamar a un médico? ¿Quizás a un sacerdote? ¡Ya ha pasado más de una hora!' WHERE `ID`=12746;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어이! 안에 있는 당신, 지금 명예의 요새의 공무 집행을 방해하고 있다는 거 알고나 있는 거요?', `MaleText_loc4`='嘿！说你呢，这可是荣耀堡的事务，别自找麻烦！', `MaleText_loc5`='喂!裏面的那位，你現在阻礙的是榮譽堡的正事!', `MaleText_loc7`='¡Oh! ¡Tú, estás levantando asuntos oficiales del Bastión del Honor!', `FemaleText_loc1`='어이! 안에 있는 당신, 지금 명예의 요새의 공무 집행을 방해하고 있다는 거 알고나 있는 거요?', `FemaleText_loc4`='嘿！说你呢，这可是荣耀堡的事务，别自找麻烦！', `FemaleText_loc5`='喂!裏面的那位，你現在阻礙的是榮譽堡的正事!', `FemaleText_loc7`='¡Oh! ¡Tú, estás levantando asuntos oficiales del Bastión del Honor!' WHERE `ID`=12747;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러니 협조 좀 부탁합니다. 지금부터 열까지 셀 텐데 10이 될 때까지 안 나오면 문을 확 열고 들어갈 겁니다!', `MaleText_loc4`='帮帮我，我开始数数，要是我数到10你还没走开，我就不客气了！', `MaleText_loc5`='幫我個忙，我現在數到十，如果我數到十，你還不離開那裡，我就要進來了!', `MaleText_loc7`='Así que ayúdame. Voy a contar a diez, y si no te has largado cuando llegue a 10, ¡voy a entrar!', `FemaleText_loc1`='그러니 협조 좀 부탁합니다. 지금부터 열까지 셀 텐데 10이 될 때까지 안 나오면 문을 확 열고 들어갈 겁니다!', `FemaleText_loc4`='帮帮我，我开始数数，要是我数到10你还没走开，我就不客气了！', `FemaleText_loc5`='幫我個忙，我現在數到十，如果我數到十，你還不離開那裡，我就要進來了!', `FemaleText_loc7`='Así que ayúdame. Voy a contar a diez, y si no te has largado cuando llegue a 10, ¡voy a entrar!' WHERE `ID`=12748;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 여관에 오신 걸 환영합니다. 저는 시드라고 합니다. 이곳에서 새로운 얼굴을 만나는 건 즐거운 일이 아닐 수 없지요. 뭘 도와드릴까요?', `MaleText_loc4`='瞧见这么多新面孔，真好。我能为你做什么？', `MaleText_loc5`='希德是名字。在這附近還能看到新面孔真好。我能為你做些什麼?', `MaleText_loc7`='Me llamo Sid. Me alegro de ver alguna cara nueva por aquí. ¿Qué puedo hacer por ti?' WHERE `ID`=12749;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시드, 물건을 보고 싶습니다.', `MaleText_loc4`='我想看看你出售的货物，希德。', `MaleText_loc5`='我想看看你的商品，希德。', `MaleText_loc7`='Me gustaría echar un vistazo a tus mercancías, Sid.', `FemaleText_loc1`='시드, 물건을 보고 싶습니다.', `FemaleText_loc4`='我想看看你出售的货物，希德。', `FemaleText_loc5`='我想看看你的商品，希德。', `FemaleText_loc7`='Me gustaría echar un vistazo a tus mercancías, Sid.' WHERE `ID`=12750;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명예의 요새를 휴식처로 삼고 싶습니다, 시드.', `MaleText_loc4`='我想把炉石绑定在荣耀堡，希德。', `MaleText_loc5`='我希望讓榮譽堡成為我的家，希德。', `MaleText_loc7`='Deseo que el Bastión del Honor sea mi hogar, Sid.', `FemaleText_loc1`='명예의 요새를 휴식처로 삼고 싶습니다, 시드.', `FemaleText_loc4`='我想把炉石绑定在荣耀堡，希德。', `FemaleText_loc5`='我希望讓榮譽堡成為我的家，希德。', `FemaleText_loc7`='Deseo que el Bastión del Honor sea mi hogar, Sid.' WHERE `ID`=12751;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 누가 있소? 의심할 필요도 없이... <통신 장애> ...통신이 가능한가? ...하늘 감시초소에서... <통신 장애>... 의 안부를 전하오.', `MaleText_loc4`='情况怎么样？毫无疑问……嗞嗞……这通讯设备行不行啊？我代表……嗞嗞……碧蓝岗哨……问好。', `MaleText_loc5`='我們這裡還有誰?不必懷疑...<干擾>...能和我們溝通的人?我從...<干擾>...藍色守望向你問好。', `MaleText_loc7`='¿Y a quién tenemos aquí? Si duda e... crzzzk... zo posible esta comunicación? Te saludo des... psshzzzk... Avanzada Azur.' WHERE `ID`=12752;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그쪽 신호를 들어보니 우리가 당신을... 우리가 추락한 큰 섬의 남동쪽 부분으로... 암멘 여울을 건너... 크쉬쉬쉬크 지지지트... 미안하오. 너무 많은...', `MaleText_loc4`='根据信号来源，我们判断你是在……飞船坠毁点的东南方。穿过晶水河……嗞嗞嗞嗞。抱歉，干扰实在太大了……', `MaleText_loc5`='從你的信號看來，我們認為...<干擾>...你的位置在我們失事的那個大島東南方的小島上。越過水晶河川可以到達...<干擾>...抱歉，有很多...<這裡受到嚴重的干擾。>', `MaleText_loc7`='A juzgar por tu señal, te ubicamos... usto al sureste de la parte más grande de la isla en la que nos estrellamos. Cruza el río Arroyocristal para lle... kshhhhk zzzt. Lo siento, hay mucha elec...' WHERE `ID`=12753;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번엔 뭡니까, 다나스 님? 제가 몹시 바쁜 걸 모르시는 건 아닐 테지요?', `MaleText_loc4`='什么事，达纳斯？没瞧见我忙得像狗一样吗？', `MaleText_loc5`='又怎麼了，達納斯?你沒看到我的工作排山倒海而來嗎?', `MaleText_loc7`='¿Y ahora qué, Danath? ¿Acaso no ves que ya estoy desbordado de trabajo?' WHERE `ID`=12754;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보자고 한 이유가 바로 그걸세, 오랜 친구여. 의논할 일이 아주 많다네.', `MaleText_loc4`='这正是我叫你老朋友的原因。我们得好好谈谈。', `MaleText_loc5`='那就是我為什麼會召見你的原因老朋友。我們有很多事要談。', `MaleText_loc7`='Precisamente por eso te he llamado, viejo amigo. Tenemos mucho de qué hablar.' WHERE `ID`=12755;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 우리가 약속의 땅에 도착하기는 했지만 할 일이 많이 있소이다. 아웃랜드를 맹목적으로 가로 지른다면 우리 백성은 쿠엘탈라스에 도착할 수 없소.$B$B안전한 길을 확보하고 자원을 지키면서 적을 피하거나 물리쳐야 하오.', `MaleText_loc4`='$n，虽然我们到过理想中的乐土，可还有很多事情等着我们去做。要是我们继续在外域徘徊不前，怎么能赶上凯尔萨斯王子？$B$B我们必须找到一条安全的路线，保护好各类资源。要是遇到敌人，打得过就打，打不过就逃。', `MaleText_loc5`='雖然我們抵達了樂土，$n，還有很多事等著要做。除非我們拼了命地穿過外域，否則我們的人民接近不了凱爾薩斯。$B$B一定要找到安全的路線，保護好資源，避開我們的敵人或殺了他們。', `MaleText_loc7`='Aunque hemos llegado a la tierra prometida, $n, aún queda mucho por hacer. Nuestra gente no llegará a Kael''thas si nos lanzamos a la desesperada a través de Terrallende.$B$BDebemos encontrar rutas seguras, asegurarnos los recursos y esquivar o destruir a nuestros enemigos.' WHERE `ID`=12756;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 거의 도착했는데 어떤 바보가 그걸 여는 겁니까?', `MaleText_loc4`='是哪个傻瓜打开了我们拼了老命要关闭的黑暗之门？', `MaleText_loc5`='哪個蠢蛋把我們要關閉的東西又打開了?', `MaleText_loc7`='¿Qué suerte de loco abre aquello que justamente nos enviaron a cerrar?' WHERE `ID`=12757;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 어둠의 문을 내 손으로 부숴버리고 싶습니다! 이건 말도 안 됩니다!', `MaleText_loc4`='我有一个好点子，可以凭一己之力摧毁黑暗之门！哈哈哈！', `MaleText_loc5`='我有個好方法可以自己把那個傳送門給分裂!這簡直是無法無天!', `MaleText_loc7`='¡Me falta poco para derribar yo mismo ese portal! ¡Esto es intolerable!' WHERE `ID`=12758;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 얼라이언스와 호드가 평화롭게 지낸다는 말도 안 되는 말을 들어보셨습니까? 들어보셨느냔 말입니다! 왜 그런 말도 안 되는 생각으로 제 피를 끓게 하는 겁니까!', `MaleText_loc4`='你听说了吗？关于那些荒谬的声明？联盟和部落倡导和平？这种言论真让人气不打一处来！', `MaleText_loc5`='你有聽說嗎?你有聽說那可笑的主張嗎?聯盟和部落擁護和平?為什麼這樣的想法會讓我的血液沸騰!', `MaleText_loc7`='¿Y has oído? ¿Has oído esas absurdas afirmaciones? ¿La Alianza y la Horda respaldando la paz? ¡Por qué solo el hecho de pensarlo me hierve la sangre!', `FemaleText_loc1`='그리고 얼라이언스와 호드가 평화롭게 지낸다는 말도 안 되는 말을 들어보셨습니까? 들어보셨느냔 말입니다! 왜 그런 말도 안 되는 생각으로 제 피를 끓게 하는 겁니까!', `FemaleText_loc4`='你听说了吗？关于那些荒谬的声明？联盟和部落倡导和平？这种言论真让人气不打一处来！', `FemaleText_loc5`='你有聽說嗎?你有聽說那可笑的主張嗎?聯盟和部落擁護和平?為什麼這樣的想法會讓我的血液沸騰!', `FemaleText_loc7`='¿Y has oído? ¿Has oído esas absurdas afirmaciones? ¿La Alianza y la Horda respaldando la paz? ¡Por qué solo el hecho de pensarlo me hierve la sangre!' WHERE `ID`=12759;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='20년 세월을 잃어버렸습니다! 20년을 말입니다! 더는 참을 수 없습니다! 절대, 절대로, 절대로 못 참습니다...', `MaleText_loc4`='20年啊！20年！我没法忍受！没法忍受……', `MaleText_loc5`='20年的失聯!20年!我不能忍受這樣!不，不，不...', `MaleText_loc7`='¡Veinte años perdidos! ¡Veinte! ¡No voy a tolerarlo! No, no, jamás...', `FemaleText_loc1`='20년 세월을 잃어버렸습니다! 20년을 말입니다! 더는 참을 수 없습니다! 절대, 절대로, 절대로 못 참습니다...', `FemaleText_loc4`='20年啊！20年！我没法忍受！没法忍受……', `FemaleText_loc5`='20年的失聯!20年!我不能忍受這樣!不，不，不...', `FemaleText_loc7`='¡Veinte años perdidos! ¡Veinte! ¡No voy a tolerarlo! No, no, jamás...' WHERE `ID`=12760;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오크를 믿는다? 아무리 듀로탄의 후손이 직접 결정한 일이라지만! 이건 미친 짓입니다!', `MaleText_loc4`='信任兽人？没门儿，哪怕他是杜隆坦的后裔！信任兽人是非常愚蠢的行为！', `MaleText_loc5`='相信一個獸人?就算是杜洛坦的後代也是一樣!這根本是瘋了!', `MaleText_loc7`='¿Confiar en un orco? ¡Aunque sea de la progenie del mismo Durotan! ¡Es una locura!' WHERE `ID`=12761;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절대로! 절대로 그들 뜻에 따를 수 없습니다! 차라리 죽겠습니다.', `MaleText_loc4`='不！我绝不遵从他们的意志！反正我也是个将死之人了。', `MaleText_loc5`='絕不!我絕對不會遵從他們的意志!我寧願去死。', `MaleText_loc7`='¡Jamás! ¡Nunca me someteré a su voluntad! Prefiero la muerte.' WHERE `ID`=12762;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 떠나겠습니다, 사령관님. 몸조심하십시오!', `MaleText_loc4`='指挥官，我告辞了。再见！', `MaleText_loc5`='我先走了，指揮官。祝你有愉快的一天!', `MaleText_loc7`='Ahora me retiro, Comandante. ¡Que tenga un buen día!' WHERE `ID`=12763;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우체통? 지금 불난 집에 부채질하는 건가! 20년 동안 세상과 떨어져 살았는데 인제 와서 우체통이라니! 허! 정말 대단하군!', `MaleText_loc4`='哎哟，这里有个邮箱？啧啧，这算不得往伤口上撒盐！20年来与世隔绝，现在我们终于有邮箱了！棒绝人寰啊！', `MaleText_loc5`='一個郵箱?那不是在傷口上灑鹽嗎!和世界脫軌了20年而現在一個郵箱!太好了!', `MaleText_loc7`='¿Un buzón de correo? ¡Esto es poner sal en la llaga! ¡Veinte años aislado del mundo y ahora aparece un buzón de correo! ¡MARAVILLOSO!' WHERE `ID`=12764;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시드! 여기 맥주, 당장!', `MaleText_loc4`='希德！上酒，快点！', `MaleText_loc5`='希德!麥芽酒，快!', `MaleText_loc7`='¡Sid! Cerveza, ¡AHORA!' WHERE `ID`=12765;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='금방 갑니다! 더 필요하신 건 없습니까? 모자 세탁이나 손톱 손질이 어떠세요?', `MaleText_loc4`='嘿，殿下！有什么事情可以为您效劳吗？帮您整理帽子或者修修指甲？', `MaleText_loc5`='馬上來，大人!你還有什麼別的事要吩咐嗎?像是洗個帽子或修個指甲?', `MaleText_loc7`='¡Ya voy, su alteza! ¿Necesitará algo más? ¿Quizás que le limpie el sombrero o le corte las uñas?' WHERE `ID`=12766;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내가 살아있는 한 우리의 계획은 알 수 없을 것이다, $r!', `FemaleText_loc4`='你别想抓活的，渣滓！', `FemaleText_loc5`='你不可能活捉我的，人渣!', `FemaleText_loc7`='¡No me cogerás viva, escoria!' WHERE `ID`=12767;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나와 함께 한 잔 하지 않겠나, 시드? 탑에 있는 내 숙소에 대신 그걸 좀 가져다 놓게! 자네 여관이 동물원이 됐군!', `MaleText_loc4`='少来了，希德！把那东西送到我在塔里的住处！你的旅店已经变成了动物园了！', `MaleText_loc5`='不准從我先開始，希德!先把它送到我哨塔的軍營去!你的旅店已經變成動物園了!', `MaleText_loc7`='¡No empieces conmigo, Sid! ¡Haz que lo manden a mis alcobas de la torre! ¡Tu posada se ha convertido en un zoo!' WHERE `ID`=12768;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='치유의 수정 확보를 위해서는 지금 아무것도 아까울 게 없습니다!', `MaleText_loc4`='我情愿用任何东西交换一块治疗水晶！', `MaleText_loc5`='現在為了治療水晶我什麼都願意給!', `MaleText_loc7`='¡Lo que daría por un cristal de sanación justo ahora!' WHERE `ID`=12769;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보급 요청 목록을 가져다주셔서 감사합니다! 제 다리도 거의 다 나았으니 이제 추락 지점으로 돌아갈 수 있습니다.', `MaleText_loc4`='谢谢你帮忙递交清单！我的腿差不多已经痊愈，这样我就可以自己走回坠毁点了。', `MaleText_loc5`='謝謝你送那張單子來，$c!我的腿幾乎復元的差不多了，很快就能自己走回失事地點。', `MaleText_loc7`='¡Gracias por entregar esa lista! Tengo la pierna casi recuperada y pronto podré volver al lugar del accidente.' WHERE `ID`=12770;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어떻게 해야 여기서 빠져나갈 수 있을까요?', `FemaleText_loc4`='我们究竟要怎样才能离开这里？', `FemaleText_loc5`='我們要怎麼離開這裡?', `FemaleText_loc7`='¿Cómo vamos a lograr salir de aquí?' WHERE `ID`=12771;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$c님... 호수, 덩굴손 그리고 올빼미야수를 돌봐주셔서 감사드려요.', `FemaleText_loc4`='感谢你照顾湖泊，鞭笞者，还有枭兽。', `FemaleText_loc5`='謝謝你救了湖泊、梟獸和鞭笞者，$c。', `FemaleText_loc7`='Gracias por cuidar del lago, los azotadores y el buhíco, $c.' WHERE `ID`=12772;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$c님, 당신은 해야 할 일을 했을 뿐이니 아무도 당신 행동에 의문을 제기하지 않을 겁니다.', `FemaleText_loc4`='没人会怀疑你的作用，$c。你做了你该做的。', `FemaleText_loc5`='沒有人會質疑你的行為，$c。你只是做了該做的事。', `FemaleText_loc7`='Nadie cuestionará tus acciones, $c. Hiciste lo que había que hacer.' WHERE `ID`=12773;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='건강하게 살아있는 걸 보니 다행이구려, $n!', `MaleText_loc4`='我很高兴看到你还健康地活着，$n！', `MaleText_loc5`='看到你還活得好好的真好，$n!', `MaleText_loc7`='¡Me alegro de verte con vida, $n!' WHERE `ID`=12774;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='치유의 수정을 보충해줘서 다시 한 번 고맙다는 말을 하고 싶군. 자네가 곳곳에 도움을 주고 있다는 말은 익히 들었네. 계속 힘써주게나!', `MaleText_loc4`='再次感谢你为我们补充了治疗水晶。我听说你在到处帮忙，加油！', `MaleText_loc5`='再次感謝你補充了我們的治療水晶。我聽說你到處在幫忙人們。保持下去!', `MaleText_loc7`='Gracias de nuevo por reponer nuestros cristales de sanación. He oído que estás ayudando por todo el lugar. ¡Sigue con el buen trabajo!' WHERE `ID`=12775;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동료에게 고마울 뿐이오.', `MaleText_loc4`='谢谢你，$n。', `MaleText_loc5`='我謝謝大家，$n。', `MaleText_loc7`='Te agradezco que me hagas compañía, $n.' WHERE `ID`=12776;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 아직 안 가시고 여기서 뭐 하시오? 추락 지점 아래에 있는 프로에니투스 님과 얘기는 나눠 본 거요?', `MaleText_loc4`='$n，你怎么还在这里？你和坠毁点那里的普罗尼图斯说过话了吗？', `MaleText_loc5`='$n，你還在這幹嘛?你去和失事地點的米奇隆談過了嗎?', `MaleText_loc7`='$n, ¿qué estás haciendo aquí todavía? ¿Ya has hablado con Proenitus en el lugar del accidente?' WHERE `ID`=12777;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미렌과 저는 어둠의 문 안팎을 통틀어 최고의 현상금 사냥꾼이지요. 잠시 기다려주시면 한 수 가르쳐드리지요.', `MaleText_loc4`='无论是在黑暗之门的那边还是这边，米伦和我都是非常优秀的猎人。到处晃晃，你也许可以学到点什么的。', `MaleText_loc5`='麥倫和我不論在黑暗之門的那一方都是最優秀的獵人。多多留意，你就會學到一些東西。', `MaleText_loc7`='Mirren y yo somos dos de los mejores cazadores de cada lado del Portal Oscuro. Quédate, puede que aprendas un par de cosas.' WHERE `ID`=12778;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 맥주가 탐나서 오신 게 아니라면 좋겠군요. 나눠줄 생각은 추호도 없을뿐더러 이게 마지막이라서요!$B$B아웃랜드로 맥주를 가져올 좋은 생각을 한 자가 우리 말고는 아무도 없는 게 내 잘못은 아니지 않아요?', `MaleText_loc4`='我希望你不是为我们的啤酒而来的。不要想了，我们是不会把啤酒分给你的！$B$B除了我们之外居然没有人会有这么好的远见，想到把啤酒带到外域来，嘿，这可不是我们的过错。', `MaleText_loc5`='我希望你不是為了麥芽酒而來的。我們沒有酒可以分享了!$B$B這不是我們的錯，沒有人有將啤酒帶到外域去的遠見，只有我們。', `MaleText_loc7`='Espero que no busques cerveza. ¡No vamos a compartirla y basta!$B$BNo es culpa nuestra que a nadie se le ocurriera traer cerveza a Terrallende excepto a nosotros.' WHERE `ID`=12779;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 폭발하며 비전 잔류물이 쏟아집니다!', `MaleText_loc4`='%s爆炸了，整个区域沐浴在奥术残渣中！', `MaleText_loc5`='%s爆開吧，讓那個地方充滿秘法殘餘!', `MaleText_loc7`='¡%s revienta, rociando la zona de residuo Arcano!' WHERE `ID`=12780;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 힘을 발산합니다!', `MaleText_loc4`='%s发怒了！', `MaleText_loc5`='%s充滿能量!', `MaleText_loc7`='¡%s se enfada enérgicamente!' WHERE `ID`=12781;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아웃랜드의 모든 지역이 이곳처럼 황량하지는 않기만 바랍니다. 영원노래 숲의 녹색 초원과 숲은 확실히 변했습니다.', `FemaleText_loc4`='希望外域不全都是像这个区域那么荒芜。这里和永歌森林的密林绿草反差真大。', `FemaleText_loc5`='希望外域並不會像這個區域一樣全為貧瘠之地。這和永歌森林的翠綠草地和森林相比簡直是天壤之別。', `FemaleText_loc7`='Por la esperanza de que no toda Terrallende sea tan inhóspita como esta región. Este es un cambio bastante grande de las verdes praderas de Canción Eterna.' WHERE `ID`=12782;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아웃랜드에는 우리가 기존의 세상에서 보았던 그 어떤 존재보다 강력하고 사악한 존재들이 잔뜩 있습니다.$B$B그들을 피해 달아나지 않고 맞서는 자는 엄청난 힘을 얻게 될 것이지만, 그 힘을 이용하고 통제하는 법을 배워야 할 것입니다.', `MaleText_loc4`='那些存在于外域的恶魔力量远比我们过去在这世界上看到过的任何东西都要强大。$B$B强大的力量应该给予那些不逃避它，而是学着去驾驭和掌握它的人。', `MaleText_loc5`='外域裡存在著比我們以前見過還強大很多的惡魔勢力。$B$B強大的力量應該給予那些不會畏懼的人，但能學著駕馭和控制它的力量。', `MaleText_loc7`='Hay en Terrallende presencias demoníacas mucho más poderosas que nada que hayamos visto en el viejo mundo.$B$BHabrá un gran poder para aquellos que no las rehúyan, sino que aprendan a aprovechar y llegar a dominar su fuerza.' WHERE `ID`=12783;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳은 내가 태어난 고향이오. 적어도 난 그렇게 알고 있지... 어릴 적 부모님은 당신의 세계와 그 화려함에 대해 얘기해 주시곤 하셨지. 그러니 내가 얼마나 이 땅을 떠나고 싶었겠소.$B$B하지만, 운명이란 잔인하기 짝이 없구려. 부모님께서는 오래전에 돌아가셨는데 바로 이 묘지에 묻히셨소. 나는 부모님과 우리 가문, 로서의 후예들의 영광을 지키고자 여기 남았소.', `MaleText_loc4`='我出生在这里，$r。这是我的世界，我所了解的一切……当我还是个小孩子的时候，我的父母经常向我讲述你们那个世界的故事，你们那个世界的荣光。我是多么渴望离开这个地方啊。$B$B唉，命运是残酷的。我的父母已经去世很久了，长眠在这个坟墓里。我留在这里，为他们的荣耀而战，也为我的家族——洛萨之子的荣耀而战。', `MaleText_loc5`='我在這裡出生的，$r。這是我的世界 - 就我所知...小時候，我的父母總是和我說你們世界的故事還有那裡的壯麗。我有多想離開這個地方啊。$B$B唉，命運是個殘酷的女人。我的父母很久前就過世了，葬在這個墓地。我仍維持著他們的榮耀和我家族的光榮 - 洛薩之子。', `MaleText_loc7`='Nací aquí, $r. Este es mi mundo – todo lo que conozco... De niño, mi madre y mi padre me obsequiaban historias de tu mundo y de su esplendor. Cómo ansiaba dejar este lugar.$B$BDesgraciadamente, el destino es un amante cruel. Mi madre y mi padre fallecieron hace tiempo y están enterrados en este mismo cementerio. Yo permanezco para defender su honor y el honor de mi familia – los hijos de Lothar.' WHERE `ID`=12784;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 저 트롤들에게 좀 더 신경을 써야 합니다. 놈들은 아무 때나 이곳에 몰려옵니다.', `MaleText_loc4`='我不觉得那些巨魔们已经被妥善“关照”了，他们可以在任何时候涌过来把我们全都踏平。', `MaleText_loc5`='我認為大家不夠重視那些食人妖。他們任何時候都可能擠進這裡。', `MaleText_loc7`='No creo que se esté prestando la atención suficiente a esos trols. Podrían presentarse en tropel aquí en cualquier momento.' WHERE `ID`=12785;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='트롤 사냥에 쓸 물건이 필요한 분? 트롤들도 만반의 준비를 다했을 것입니다.', `MaleText_loc4`='有人需要帮忙去追捕那些巨魔吗？任何巨魔都可以。', `MaleText_loc5`='有人需要物資來獵捕食人妖嗎?任何食人妖都可以。', `MaleText_loc7`='¿Hay alguien que necesite equipo para cazar a los trols? Con un trol cualquiera basta.' WHERE `ID`=12786;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 지저분하고 냄새 나는 트롤과 우리가 동맹을 맺어야 합니까? 유령이 되었을 때를 제외하고는 트롤들은 절대 선량한 족속이 아닙니다.', `MaleText_loc4`='为什么我们和这些肮脏的巨魔结盟？只有死去的巨魔才是好巨魔。', `MaleText_loc5`='為什麼我們要跟骯髒發臭的食人妖結盟?唯一的好食人妖就是死的食人妖。', `MaleText_loc7`='¿Por qué nos aliamos con los apestosos y asquerosos trols? El único trol bueno es un trol muerto.' WHERE `ID`=12787;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무엇을 도와드릴까요?', `MaleText_loc4`='我能为你效劳吗？', `MaleText_loc5`='我能幫你什麼忙?', `MaleText_loc7`='¿Qué puedo hacer por ti?', `FemaleText_loc1`='무엇을 도와드릴까요?', `FemaleText_loc4`='我能为你效劳吗？', `FemaleText_loc5`='我能幫你什麼忙?', `FemaleText_loc7`='¿Qué puedo hacer por ti?' WHERE `ID`=12788;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저리 가, 불결한 놈! 왜 모두 네 더러운 냄새를 참기만 하는지! 난 그렇게 못 해!', `MaleText_loc4`='去死吧，肮脏的东西！滚远点！', `MaleText_loc5`='快滾吧骯髒的生物!為什麼不論哪個人都能忍受你比我還骯髒。', `MaleText_loc7`='¡Fuera, criatura asquerosa! No entiendo por qué alguien iba a tolerar tu suciedad.' WHERE `ID`=12789;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물건을 좀 볼 수 있을까요?', `MaleText_loc4`='我可以看看你的货物吗？', `MaleText_loc5`='我可以看看你的商品嗎?', `MaleText_loc7`='¿Puedo ver tus mercancías?', `FemaleText_loc1`='물건을 좀 볼 수 있을까요?', `FemaleText_loc4`='我可以看看你的货物吗？', `FemaleText_loc5`='我可以看看你的商品嗎?', `FemaleText_loc7`='¿Puedo ver tus mercancías?' WHERE `ID`=12790;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아웃랜드는 마법의 힘이 새어나오는 것이 스쳐가는 바람결에도 알 수 있는 곳이라오. 느껴지오, $n? 우리 종족에게 여기보다 더 적합한 곳은 없소이다. 머지않아 신도레이는 이 새로운 땅을 우리의 고향이라고 부를 것이오!', `MaleText_loc4`='外域中弥漫着魔法的能量，到处都是。你能感觉到吗，$n？我不相信还有比这更适合我们种族的地方。很快辛多雷就会拥有一个属于自己的新世界！', `MaleText_loc5`='外域散發著魔法能量，就在那空氣中。你能感覺到嗎，$n?我想不到比這更適合我們種族的地方了。很快辛多雷就有自己的新土地了!', `MaleText_loc7`='Terrallende rezuma energía mágica, está en el mismo aire. ¿La sientes, $n? No se me ocurre un lugar más apropiado para nuestra raza. ¡Pronto los sin''dorei tendrán una nueva tierra de la que dirán que es su hogar!' WHERE `ID`=12791;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='남편이 며칠째 행방불명입니다. 저희는 성지를 순례하던 중이었는데 함께 순례를 마칠 계획이었지요.$B$B제가 너무 걱정한 나머지 마나 수정을 지나치게 자주 사용했군요.', `FemaleText_loc4`='我的丈夫失踪好几天了。我们一起到这里来朝圣，我们本应该在一起的。$B$B我太担心他了，我触摸魔力水晶的次数远远超出了必需的范围。', `FemaleText_loc5`='我的丈夫失蹤好幾天了。我們一起去朝聖，本來是要一起結束的。$B$B這樣的擔心讓我比平常更常汲取法力水晶。', `FemaleText_loc7`='Mi marido lleva días desaparecido. Nos fuimos juntos de peregrinación y se suponía que deberíamos estar de vuelta juntos también.$B$BEsta angustia me ha hecho abusar un poco de los cristales de maná.' WHERE `ID`=12792;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제대로만 길들이면 용매는 아주 유순합니다. 참 매력적이지 않나요? 잘 길들이면 아주 친근하고 좋은 친구가 되지만 야생에서는 난폭하고 위험합니다... 저는 그 녀석들이 정말 좋습니다.', `FemaleText_loc4`='龙鹰在适当饲养的情况下是非常容易被驯服的。你不觉得那是十分迷人的吗？饲养正确的话是如此的友好，而野生龙鹰又是如此的凶猛和致命……我太喜欢它们了。', `FemaleText_loc5`='如果有適當地照料，龍鷹是相當溫馴的。你不覺得這很棒嗎?如果好好撫養它們是如此的友善好相處，如果在野外生長又是如此的兇惡致命...我真是愛死它們了。', `FemaleText_loc7`='En realidad, los dracohalcones, si se crían adecuadamente, son bastante mansos. ¿No te parece fascinante? Ser tan agradables y sociables si se crían bien y tan fieros y letales en si hábitat natural... Los adoro con locura.' WHERE `ID`=12793;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난... 걱정하지... 마시오.', `MaleText_loc4`='不要……担心……我……', `MaleText_loc5`='別...擔心...我...', `MaleText_loc7`='No... te preocupes... por... mí' WHERE `ID`=12794;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다친 다리에 부목을 대자 %s|1이;가; 고통에 신음합니다.', `MaleText_loc4`='由于受伤的腿上绑着夹板，%s痛苦地咕哝着。', `MaleText_loc5`='%s當他把夾板裝到受傷的腿上時痛苦地呻吟著。', `MaleText_loc7`='%s gruñe de dolor mientras coloca un cabestrillo en su pierna herida.' WHERE `ID`=12795;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 상황이 그렇게 나쁘다고는 생각 안 해요. 조만간 전부 나아질 것이고 태양샘의 힘도 회복될 겁니다. 모두 입을 모아 말하는 나쁜 일은 없을 거예요.', `FemaleText_loc4`='我不觉得我们的处境有这么坏。我很确信一切都会很快得到纠正，太阳之井的能量也会恢复。事情不可能像大家所想的那样坏。', `FemaleText_loc5`='我不真的認為我們的情況有那麼糟。我確定一切會很快好轉，太陽之井的能量會恢復。它就是不可能像大家說的那樣糟。', `FemaleText_loc7`='La verdad es que no creo que nuestra situación sea tan mala. Estoy segura de que todo se rectificará pronto y el poder de La Fuente del Sol se restablecerá. No es posible que sea tan malo como todo el mundo pretende que es.' WHERE `ID`=12796;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선스트라이더의 블러드 엘프와 사이가 좋아졌기에 난 아웃랜드에서만 찾을 수 있는 이 피실험자와 함께 실험을 진행하려 하오. 그들은... 내 훌륭한 인격과 남자다운 외모에 감탄할 것이 분명하오이다.', `MaleText_loc4`='与逐日者合作对大家都有好处，我得到了只能在外域进行的研究课题，而他们得到了……我迷人的魅力和独特的好眼光。', `MaleText_loc5`='和逐日者交朋友各有各的好處;我用只能在外域找到的實驗品來進行研究，而他們則獲得...我迷人的個性和粗獷的帥臉蛋。', `MaleText_loc7`='Ha valido la pena hacerse amigo de los Errantes; yo puedo llevar a cabo investigaciones con sujetos que solo puedo encontrar en Terrallende y ellos... disfrutan de mi encantadora personalidad y de mi atractiva y dura apariencia.' WHERE `ID`=12797;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 병은 어디에 놓을까요?', `MaleText_loc4`='你想把这些瓶子放在哪儿？', `MaleText_loc5`='你想要這些酒瓶幹嘛?', `MaleText_loc7`='¿Dónde quieres estas botellas?', `FemaleText_loc1`='이 병은 어디에 놓을까요?', `FemaleText_loc4`='你想把这些瓶子放在哪儿？', `FemaleText_loc5`='你想要這些酒瓶幹嘛?', `FemaleText_loc7`='¿Dónde quieres estas botellas?' WHERE `ID`=12798;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 앞으로 또 다른 짐이 왔습니다, 시드 씨.', `MaleText_loc4`='你的货又来了，希德。', `MaleText_loc5`='收到給你的另一批貨，希德。', `MaleText_loc7`='Tengo otro envío para ti, Sid.', `FemaleText_loc1`='당신 앞으로 또 다른 짐이 왔습니다, 시드 씨.', `FemaleText_loc4`='你的货又来了，希德。', `FemaleText_loc5`='收到給你的另一批貨，希德。', `FemaleText_loc7`='Tengo otro envío para ti, Sid.' WHERE `ID`=12799;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='후... 이건 정말 미친 짓입니다. 아무리 병을 옮겨도 모아둔 병의 수가 절대 줄어들지 않습니다. 이건 아무리 해도 끝이 없는 작업이로군요...', `MaleText_loc4`='最疯狂的是，无论我从库存里面拿出多少瓶子，那边的数量永远不会减少。好像我陷在某个无尽的循环中无法脱身了……', `MaleText_loc5`='最瘋狂的事 - 不論我從儲備物資裡拿多少瓶酒，它們的數量仍絲毫不減。就好像我被困在一種無盡的行為迴圈裡...', `MaleText_loc7`='De lo más curioso - No importa cuántas botellas coja de las reservas, la cantidad nunca disminuye. Es como si me hubiera quedado atascado en un bucle interminable de acciones...', `FemaleText_loc1`='후... 이건 정말 미친 짓입니다. 아무리 병을 옮겨도 모아둔 병의 수가 절대 줄어들지 않습니다. 이건 아무리 해도 끝이 없는 작업이로군요...', `FemaleText_loc4`='最疯狂的是，无论我从库存里面拿出多少瓶子，那边的数量永远不会减少。好像我陷在某个无尽的循环中无法脱身了……', `FemaleText_loc5`='最瘋狂的事 - 不論我從儲備物資裡拿多少瓶酒，它們的數量仍絲毫不減。就好像我被困在一種無盡的行為迴圈裡...', `FemaleText_loc7`='De lo más curioso - No importa cuántas botellas coja de las reservas, la cantidad nunca disminuye. Es como si me hubiera quedado atascado en un bucle interminable de acciones...' WHERE `ID`=12800;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 이런! 그냥 저기 뒷방에 두십시오.', `MaleText_loc4`='祝福你，士兵！就把它们放在后面吧。', `MaleText_loc5`='祝福你的心，士兵!把它們留在心中就好。', `MaleText_loc7`='¡Bendito sea tu corazón, soldado! Mételos en la sala de atrás.' WHERE `ID`=12801;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그냥 지하실에 두십시오.', `MaleText_loc4`='放在地下室就行了。', `MaleText_loc5`='把他們留在地窖裡就好。', `MaleText_loc7`='Déjalas en la bodega.' WHERE `ID`=12802;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 고개를 끄덕입니다.', `MaleText_loc4`='%s点了点头。', `MaleText_loc5`='%s點點頭。', `MaleText_loc7`='%s asiente con la cabeza.', `FemaleText_loc1`='%s|1이;가; 고개를 끄덕입니다.', `FemaleText_loc4`='%s点了点头。', `FemaleText_loc5`='%s點點頭。', `FemaleText_loc7`='%s asiente con la cabeza.' WHERE `ID`=12803;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='썬더 블러프로 날아가고 싶습니다.', `MaleText_loc4`='我想飞往雷霆崖。', `MaleText_loc5`='我想飛往雷霆崖。', `MaleText_loc7`='Me gustaría volar a Cima del Trueno.', `FemaleText_loc1`='썬더 블러프로 날아가고 싶어요.', `FemaleText_loc4`='我想飞往雷霆崖。', `FemaleText_loc5`='我想飛往雷霆崖。', `FemaleText_loc7`='Me gustaría volar a Cima del Trueno.' WHERE `ID`=12804;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아버지가 이 황무지로 배치되셨을 때 난 아직 어린아이였소. 아버지에 대해 내가 아는 건 다른 사람들이 말해준 것뿐이오.$B$B당신의 꿈은 항상 다른가, $n? 내 꿈은 항상 똑같다오. 불타는 군단처럼 새빨간 지평선이 나를 감싸고, 알 수 없는 번호가 매겨지고, 멀리서는 전투가 벌어지지. 나는 아버지로 생각되는 한 남자의 시체 앞에 무릎을 꿇고 눈물을 흘린다오. 몸이 망가진 아버지가 숨을 헐떡거리며 뭐라고 속삭이시는데 내 모든 노력을 다해도 그분께서 뭐라고 하시는지 들을 수가 없는 그런 꿈이라오.', `MaleText_loc4`='当我父亲被派到这片废土来的时候，我还只是个婴儿。我所知道的有关他的一切都是别人告诉我的。$B$B你的梦境会改变吗，$n？我的梦境从来都不会改变，我只有一个梦：数量超乎想象的燃烧军团士兵像深红色的地平线包围着我，战争在远处打响。我跪在一个男人身前哭泣，那男人很可能就是我父亲。他大口喘着气，他的身体支离破碎，他在低声说着什么……不管怎么努力，我总是听不到他试图告诉我的事情。', `MaleText_loc5`='當我父親被派來這片荒地時我只是個嬰兒。所有我知道關於他的事都是別人告訴我的。$B$B你的夢會變嗎，$n?我的不會。我只有一個夢:一條赤紅的軍團地平線包圍著我，數量龐大無法計算，在遠處作戰。我在一個人的軀體前跪下，他大概就是我的父親，然後哭泣。當他喘著氣時，他的身體整個被壓碎，他虛弱的說著一些話。儘管我再怎麼努力;還是聽不到他要和我說的話。', `MaleText_loc7`='Era solo un bebé cuando mi padre fue destinado a este páramo. Todo lo que siempre he sabido de él es lo que otros me han contado.$B$B¿Cambian tus sueños, $n? Los míos, no. Tengo un sueño: un horizonte carmesí me envuelve mientras la Legión, en cantidad innumerable, batalla en la distancia. Me arrodillo ante el cadáver de un hombre, es de suponer que mi padre, y lloro. Mientras lucha por conseguir aire, con todo el cuerpo aplastado, susurra algo. A pesar de todos mis esfuerzos, soy incapaz de oír lo que intenta decirme.' WHERE `ID`=12805;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠이 우리 땅을 뒤덮고 있네, 젊은 친구! 무기를 들어 하늘에 떠있는 죽음의 위협에 맞서겠나?', `MaleText_loc4`='阴影已经笼罩上了我们的土地，年轻的$c。你愿意拿起武器，对抗这些从天而降的亡灵吗？', `MaleText_loc5`='黑暗掩蓋了我們的土地，年輕的$c。你會拿起武器面對這個逼近的死亡嗎?', `MaleText_loc7`='Una penumbra envuelve nuestras tierras, joven $c. ¿Tomarás las armas para enfrentarte a esta muerte veloz?' WHERE `ID`=12806;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 침공이 얼마나 계속될까요?', `MaleText_loc4`='入侵将持续多久？', `MaleText_loc5`='入侵行動會持續多久?', `MaleText_loc7`='¿Cuánto tiempo durará la invasión?', `FemaleText_loc1`='이 침공이 얼마나 계속될까요?', `FemaleText_loc4`='入侵将持续多久？', `FemaleText_loc5`='入侵行動會持續多久?', `FemaleText_loc7`='¿Cuánto tiempo durará la invasión?' WHERE `ID`=12807;
