UPDATE `locales_broadcast_text` SET `MaleText_loc1`='Holiday - Scourge Invasion, mystic - how long, Tier 1', `MaleText_loc4`='Holiday - Scourge Invasion, mystic - how long, Tier 1', `MaleText_loc5`='節日 - 天譴軍團入侵，神秘事件 - 入侵行動持續時間，第1階段', `MaleText_loc7`='Fiesta - Invasión de la Plaga, mística - duración, Nivel 1' WHERE `ID`=12809;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='Holiday - Scourge Invasion, mystic - how long, Tier 2', `MaleText_loc4`='Holiday - Scourge Invasion, mystic - how long, Tier 2', `MaleText_loc5`='節日 - 天譴軍團入侵，神秘事件 - 入侵行動持續時間，第2階段', `MaleText_loc7`='Fiesta - Invasión de la Plaga, mística - duración, Nivel 2' WHERE `ID`=12810;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니, 내가 꿈을 꾸고 있는 건가! 거기 그 어린 꼬마 아라토르? 자네인가?', `MaleText_loc4`='天啊！小阿拉托尔？是你吗？', `MaleText_loc5`='我的老天啊!「微不足道」的阿拉特?是你嗎?', `MaleText_loc7`='¡Por mi vida y mi aliento! ¿"Pequeño" Arator? ¿Eres tú?' WHERE `ID`=12811;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맞습니다, 트롤베인 사령관님. 하지만, 이제 꼬마가 아니지요. 저는 아버지를 찾으려고 왔습니다. 아버지의 행방에 대해 아시는 게 좀 있습니까? 전 알아요. 아버지는 아직 살아 계세요. 꿈속에서 그분이 살아계시는 걸 봤어요...', `MaleText_loc4`='是的，长官。但是我已经不再是那个小孩子了。我要找到我的父亲。您有任何有关他的消息吗？我知道他还活着。我在我的梦里见到过他……', `MaleText_loc5`='好，指揮官;但我不再是微不足道。我是來找我父親的。你有聽說任何他的下落嗎?我知道他還活著。我在夢中見過他...', `MaleText_loc7`='Sí, Comandante, pero ya no soy pequeño. He venido a buscar a mi padre. ¿Tienes noticias de su paradero? Sé que todavía vive. Lo he visto en mis sueños...' WHERE `ID`=12812;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 근엄하게 아라토르를 쳐다봅니다.', `MaleText_loc4`='%s冷峻地看着阿拉托尔。', `MaleText_loc5`='%s嚴肅地看著阿拉特。', `MaleText_loc7`='%s mira a Arator con tristeza.' WHERE `ID`=12813;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아라토르, 미안하지만 자네 아버님 소식에 대해서는 아는 게 없네. 지난 15년 동안 자네 아버지를 보지도 못했고 소식도 듣지 못했다네. 자네 아버님께서는 이미 오래전 사망한 것으로 생각되네. 하지만, 내가 자네 아버님을 찾으려고 온갖 노력을 다했다는 것만은 알아주게. 우리는 지옥불 반도의 경계선부터 나그란드의 폐허까지 수색했지... 하지만, 아무 성과가 없었다네. 내 목숨을 바쳐서라도 투랄리온을 다시 살릴 수 있다면, 천 번도 넘게 했을 것일세. 정말... 미안하네.', `MaleText_loc4`='恐怕没有，阿拉托尔。十五年来，我没有看到或听到任何有关你父亲的消息。我们猜测他很久以前就已经去世了。但是你要知道，我尽了全力去寻找他。我们从地狱火半岛一直找到纳格兰……但毫无结果。如果我能用自己的生命来换回图拉扬的话，我会毫不犹豫地做出这样的选择。我……很抱歉。', `MaleText_loc5`='恐怕不是這樣，阿拉特。我已經15年沒見過你父親也沒聽過他的消息。我們早就覺得他已經死了。但是你要知道:我盡了一切的努力找尋他。從地獄火到納葛蘭，我們翻遍了...一無所獲。如果我可以用自己的生命換回圖拉揚，我早就這樣做了。我...我很抱歉。', `MaleText_loc7`='Me temo que no, Arator. No he visto ni he oído acerca de tu padre en quince años. Hace mucho que hemos supuesto que está muerto. Pero has de saber esto: hice todo lo que estaba en mi mano para intentar encontrarlo. Buscamos desde los límites de Llamas Infernales al caos de Nagrand... Todo para nada. Si pudiera dar mi propia vida para traer a Turalyon de vuelta, lo haría mil veces. Lo... lo siento.' WHERE `ID`=12814;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇군요. 하지만, 전 아버지를 찾을 때까지 포기하지 않을 겁니다. 아버지는 분명히 살아 계세요. 반드시 아버지를 찾아야 합니다. 아버지를 위해 애써 주신 점은 감사하게 생각합니다, 사령관님. 아버지가 전우로서 당신을 믿은 것처럼 저를 믿어 주세요. 사령관님께 충성을 맹세합니다.', `MaleText_loc4`='只要他还没有被找到，我就会继续寻找。我知道他还活着，我知道我必须找到他。谢谢您所做的一切，长官。因为我父亲曾与您并肩作战，您也同样可以随时命令我上阵厮杀。我随时为您效劳，大人。', `MaleText_loc5`='只要還沒找到他，我就會繼續搜尋。我知道他還活著。我也知道我一定要找到他。感謝你做的一切，指揮官。就如我父親召集你，一個全副武裝的弟兄，知道你也會這樣徵召我。我願為你效勞，陛下。', `MaleText_loc7`='Mientras siga sin ser hallado, buscaré. Sé que vive. Y sé que debo encontrarlo. Te agradezco lo que has hecho, comandante. Como mi padre te llamó, un hermano de armas, has de saber que me puedes llamar. Estoy a tu servicio, mi señor.' WHERE `ID`=12815;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='병사! 이쪽으로 오라!', `MaleText_loc4`='士兵！立正！', `MaleText_loc5`='士兵!前方和中央!', `MaleText_loc7`='¡Soldado! ¡A la cabeza!' WHERE `ID`=12816;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네! 여기 대령했습니다! 임무를 알려주십시오!', `MaleText_loc4`='是，长官！', `MaleText_loc5`='長官，是的，長官!報告職責，長官!', `MaleText_loc7`='¡SEÑOR, SÍ SEÑOR! ¡A sus órdenes, señor!', `FemaleText_loc1`='네! 여기 대령했습니다! 임무를 알려주십시오!', `FemaleText_loc4`='是，长官！', `FemaleText_loc5`='長官，是的，長官!報告職責，長官!', `FemaleText_loc7`='¡SEÑOR, SÍ SEÑOR! ¡A sus órdenes, señor!' WHERE `ID`=12817;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='편히 쉬게, 병사. 자네에게 임무를 하나 주지. 네더가드로 보낸 마지막 전령이 아직 도착하지 않았네. 몇 시간 전 뼈의 길 주변에 그 전령의 물건이 흩어져 있는 걸 발견했네. 불타는 군단이나 타락한 오크의 짓이 아닐까 의심하고 있네. 어쩌면 호드일지도 모르고...', `MaleText_loc4`='稍息，下士。我有个任务要交给你。上次被派往守望堡的信使没能完成任务。几小时前，我们在荣耀之路附近发现了他破碎的尸体。我们怀疑可能是燃烧军团或是邪兽人干的，甚至可能是部落……', `MaleText_loc5`='放輕鬆，士兵。我有個任務要給你。我上一個派去守望堡的信差沒有成功。我們幾個小時前發現他的內臟已散落各處。我們懷疑可能是軍團或魔獄獸人，甚至是部落幹的...', `MaleText_loc7`='Descansa, Soldado. Tengo una misión para ti. El último mensajero que envié a Nethergarde no lo logró. Encontramos sus entrañas esparcidas por el camino de los huesos hace unas horas. Sospechamos que han sido orcos de la Legión o viles, quizás incluso la Horda...' WHERE `ID`=12818;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠습니다! 죽지 않고 편지를 배달하도록 최선을 다하겠습니다!', `MaleText_loc4`='是，长官！士兵的职责就是尽他们所能坚持到底，长官！', `MaleText_loc5`='長官，是的長官!士兵會盡最大的力氣堅持到底，長官!', `MaleText_loc7`='¡Señor, sí, señor! ¡Los soldados cuanto puedan para no morir, señor!', `FemaleText_loc1`='알겠습니다! 죽지 않고 편지를 배달하도록 최선을 다하겠습니다!', `FemaleText_loc4`='是，长官！士兵的职责就是尽他们所能坚持到底，长官！', `FemaleText_loc5`='長官，是的長官!士兵會盡最大的力氣堅持到底，長官!', `FemaleText_loc7`='¡Señor, sí, señor! ¡Los soldados cuanto puedan para no morir, señor!' WHERE `ID`=12819;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네더가드 요새에 있는 경비대 사령관 네더웨인에게 이 편지를 전해주게. 이 편지를 무사히 전달하는 자에게 상을 주라는 말도 적어 놨다네... 마구간에 가면 자네가 사용할 말이 있으니 이만 가보도록!', `MaleText_loc4`='我需要把这份情报送给守望堡的指挥官奈瑟维。如果你完成任务的话，那边会嘉奖你的。你的马正在马厩里面等着你。去吧！', `MaleText_loc5`='我需要將這個訊息送到守望堡給指揮官勒松·尼德溫。如果你辦到了就會得到表揚...你的馬在獸欄裡等著。快去!', `MaleText_loc7`='Necesito que se entregue este mensaje al comandante de vigilancia Menguabisal del castillo de Nethergarde. Hay una recomendación para ti si lo consigues... Tu caballo espera en los establos. ¡Retírate!' WHERE `ID`=12820;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앞으로!', `MaleText_loc4`='前进！', `MaleText_loc5`='向前進!', `MaleText_loc7`='¡ADELANTE!', `FemaleText_loc1`='앞으로!', `FemaleText_loc4`='前进！', `FemaleText_loc5`='向前進!', `FemaleText_loc7`='¡ADELANTE!' WHERE `ID`=12821;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선량한 이들을 보호해야 한다!', `MaleText_loc4`='保护无辜者！', `MaleText_loc5`='保護無辜者!', `MaleText_loc7`='¡Proteged a los inocentes!' WHERE `ID`=12822;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='법을 준수하라!', `MaleText_loc4`='维护法律的尊严！', `MaleText_loc5`='支持法律!', `MaleText_loc7`='¡Mantened la ley!' WHERE `ID`=12823;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대중의 신뢰에 보답하라!', `MaleText_loc4`='为人民的信赖服务！', `MaleText_loc5`='讓大眾信任!', `MaleText_loc7`='¡Sirve a la confianza pública!' WHERE `ID`=12824;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽었나 봐! 다 죽었어! 적어도 임금을 줄 필요는 없게 됐군.', `MaleText_loc4`='死了！他们全死了！至少我不用付工钱了。', `MaleText_loc5`='叫醒你一無是處的懶獸人!', `MaleText_loc7`='¡Muertos! ¡Están todos muertos! Al menos no tendré que pagarles el sueldo.' WHERE `ID`=12825;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나즈그렐 님께서 이 소식을 듣고 진노하실 때까지 기다리는 게 내 계획이다! 그 후엔 네 녀석들은 끝장이다! 알아들었나!', `MaleText_loc4`='要是让纳兹格雷尔听到这个，我就有大麻烦了！', `MaleText_loc5`='等納茲格雷爾聽說後再講!那會是我的頭顱!我的頭顱我說!', `MaleText_loc7`='¡Espera a que Nazgrel oiga esto! ¡Será mi cabeza! ¡Mi cabeza, te digo!' WHERE `ID`=12826;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 어떻게 하지? 아... 내 소중한 광산...', `MaleText_loc4`='我能做点什么？我的矿洞啊……', `MaleText_loc5`='就這樣嗎，苦工?你只要坐在那裡睡覺?', `MaleText_loc7`='¿Qué voy a hacer? Mi amada mina...' WHERE `ID`=12827;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 일꾼을 죽인 걸 후회하게 해주겠다!', `MaleText_loc4`='你会后悔杀死我的伙计的！你会后悔的！', `MaleText_loc5`='你會後悔在我值班那天睡著!後悔，我說!', `MaleText_loc7`='¡Lamentarás el día que mataste a mi tripulación! ¡Lo lamentarás, te digo!' WHERE `ID`=12828;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='Marketing - iCoke Redemption Greeting (S.H.E. giftbox)', `FemaleText_loc4`='亲爱的$n，欢迎参加可口可乐魔兽世界“要爽由自己，冰火暴风城II”夏季促销活动！幸运女神的光环再一次眷顾了你，独一无二的神奇礼物不再遥不可及，今天它们都将归属于你！如果你曾经得到过一串用来兑换奖品的神秘字符，就把它告诉我，我会给你一份惊喜的！$B$B幸运正在艾泽拉斯世界散播开来，你感受到了吗？我的勇士，一起来分享这份喜悦吧！$B愿荣誉与你同在！', `FemaleText_loc5`='歡迎來到可口可樂-魔獸世界特別活動!', `FemaleText_loc7`='Marketing - iCoke Redemption Greeting (S.H.E. giftbox)' WHERE `ID`=12829;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='Tell me about the iCoke gift box promotion.', `MaleText_loc4`='请告诉我更多关于可口可乐魔兽世界夏季促销活动的细节。', `MaleText_loc5`='告訴我關於可口可樂禮物盒特別活動的細節。', `MaleText_loc7`='Tell me about the iCoke gift box promotion.', `FemaleText_loc1`='Tell me about the iCoke gift box promotion.', `FemaleText_loc4`='请告诉我更多关于可口可乐魔兽世界夏季促销活动的细节。', `FemaleText_loc5`='告訴我關於可口可樂禮物盒特別活動的細節。', `FemaleText_loc7`='Tell me about the iCoke gift box promotion.' WHERE `ID`=12830;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='iCoke - Description (S.H.E. giftbox)', `FemaleText_loc4`='魔兽世界和可口可乐(R)共同为您带来了这次可口可乐魔兽世界“要爽由自己，冰火暴风城II”夏季促销活动。请检查魔兽世界主题的可口可乐易拉罐底部或瓶装可口可乐的瓶盖内侧，您可以找到一串13位字符。在www.iCoke.cn上输入您得到的13位字符，就有机会赢得iCoke积分，从而得到可以换取魔兽世界幸运礼品的10位电子兑换券。最后，在这里输入您得到的电子兑换券上的10位号码，神秘大奖在等待着您！', `FemaleText_loc5`='iCoke - 活動說明 (S.H.E. 禮物盒)', `FemaleText_loc7`='iCoke - Description (S.H.E. giftbox)' WHERE `ID`=12831;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈의 목에 현상금이 걸렸으니 그 버림받은 자를 사냥하러 가야 할지도 모르겠소.', `MaleText_loc4`='我也许早就该去猎杀那个肮脏的野兽，不过现在我决定提供赏金悬赏他的脑袋。', `MaleText_loc5`='既然獵捕鄙惡者的頭顱有獎金可拿，我要趕緊去打獵了。', `MaleText_loc7`='Quizás tenga que ir a cazar a esa bestia Desdichada ahora que dan una recompensa por su cabeza.' WHERE `ID`=12832;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불어라! 너희 대장은 어디에 숨었느냐?', `MaleText_loc4`='告诉我们! 你们的首领躲在哪里？', `MaleText_loc5`='告訴我們!你們的領導者躲在哪?', `MaleText_loc7`='¡Dinos dónde se esconde tu líder!' WHERE `ID`=12833;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='입을 열기 전까지는 계속 굶긴다!', `MaleText_loc4`='不开口就别想得到任何东西，你这渣滓！', `MaleText_loc5`='你不說的話是不會得到任何東西的，人渣!', `MaleText_loc7`='¡No te daremos nada hasta que hables, escoria!' WHERE `ID`=12834;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제발! 마법의 힘이 필요해... 마나 수정이든... 결정이든... 아무거나 상관없어! 너무나 고통스러워!', `MaleText_loc4`='可怜可怜我吧！我必须马上吃点东西……一块魔力水晶……一块碎片……任何东西都行！我实在无法忍受这种痛苦了！', `MaleText_loc5`='拜託!我一定要立刻吃點東西...一個法力水晶...一個裂片...任何東西都好!我不能再忍受這種痛苦了!', `MaleText_loc7`='¡Por favor! Debo alimentarme de algo pronto... Un cristal de maná... un fragmento... ¡Cualquier cosa! ¡El dolor es insoportable!' WHERE `ID`=12835;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일이 있어도 대족장님을 지켜야 한다!', `MaleText_loc4`='不惜一切代价保护酋长！', `MaleText_loc5`='不顧一切保護大酋長!', `MaleText_loc7`='¡Proteged al Jefe de Guerra a toda costa!', `FemaleText_loc1`='무슨 일이 있어도 대족장님을 지켜야 한다!', `FemaleText_loc4`='不惜一切代价保护酋长！', `FemaleText_loc5`='不顧一切保護大酋長!', `FemaleText_loc7`='¡Proteged al Jefe de Guerra a toda costa!' WHERE `ID`=12836;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자에게 죽음을!', `MaleText_loc4`='杀死那些入侵者！', `MaleText_loc5`='闖入者死!', `MaleText_loc7`='¡Muerte a los intrusos!', `FemaleText_loc1`='침입자에게 죽음을!', `FemaleText_loc4`='杀死那些入侵者！', `FemaleText_loc5`='闖入者死!', `FemaleText_loc7`='¡Muerte a los intrusos!' WHERE `ID`=12837;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해골망치를 위해!', `MaleText_loc4`='为了断背者而战！', `MaleText_loc5`='為了斷脊氏族!', `MaleText_loc7`='¡Por Rompeloma!', `FemaleText_loc1`='해골망치를 위해!', `FemaleText_loc4`='为了断背者而战！', `FemaleText_loc5`='為了斷脊氏族!', `FemaleText_loc7`='¡Por Rompeloma!' WHERE `ID`=12838;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈을 뭉개버리겠다!', `MaleText_loc4`='你们的尸骸将被吞噬！', `MaleText_loc5`='你的骨頭將被啃噬!', `MaleText_loc7`='¡Tus huesos serán devorados!', `FemaleText_loc1`='네놈을 뭉개버리겠다!', `FemaleText_loc4`='你们的尸骸将被吞噬！', `FemaleText_loc5`='你的骨頭將被啃噬!', `FemaleText_loc7`='¡Tus huesos serán devorados!' WHERE `ID`=12839;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벌레 같은 이 녀석에게 너무 잔인하다고?$B$B이번 달에만 내 부하를 둘이나 죽인 놈들이오! 우리는 버림받은 자들에게 너무 관대했소.', `MaleText_loc4`='你认为我对这些家伙太残忍了是吗？$B$B这个月他们已经杀死了我的两名手下！我们对这些家伙太仁慈了。', `MaleText_loc5`='你認為我對這個小人太殘忍了嗎?$B$B他們這個月已經殺了我手下兩個人!我們對這些鄙惡人渣太仁慈了。', `MaleText_loc7`='¿Crees que estoy siendo cruel con este gusano?$B$B¡Han matado a dos de mis hombres este mes! Somos demasiado amables con esta escoria de los desdichados.' WHERE `ID`=12840;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='공기 좋고 경치 좋은 산들바람 마을에 오신 걸 환영합니다. 실버문에서는 우리를 포기하다시피 했지만 우리는 이곳을 떠나지 않을 거예요. 우리 고향이니까요.', `FemaleText_loc4`='欢迎来到晴风村。银月城放弃了我们，但是我们拒绝离开这里。这里是我们的家。', `FemaleText_loc5`='歡迎來到晴風村。銀月城已經敗在我們手下了，但我們拒絕離開。這裡是我們的家。', `FemaleText_loc7`='$gBienvenido:Bienvenida; a la aldea Brisa Pura. Lunargenta prácticamente nos ha abandonado, pero nos negamos a marcharnos. Este es nuestro hogar.' WHERE `ID`=12842;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 죽여라!', `MaleText_loc4`='杀光他们！', `MaleText_loc5`='殺光他們!', `MaleText_loc7`='¡Mátalos a todos!' WHERE `ID`=12844;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아타말 수정 7개의 힘이로군! 생존자가 더 있다니! 자나, 당신인가? 당신을 다시 보게 되어 정말 반갑군!', `MaleText_loc4`='七块阿塔玛水晶在上！发现其他幸存者了！沙娜安，是你吗？真高兴可以再次看到你！', `MaleText_loc5`='藉著七個阿塔莫水晶的力量!其他人都在撞擊中生還了!薩那，真的是你嗎?很高興再見到你!', `MaleText_loc7`='¡Por los siete cristales de Ata''mal! ¡Otros han sobrevivido al accidente! Zhanaa, ¿eres tú? ¡Me alegro tanto de volver a verte!' WHERE `ID`=12845;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋은 소식이군요! $n, 덕분에 살았습니다!', `FemaleText_loc4`='这真是个好消息！你的努力拯救了我们，$n！', `FemaleText_loc5`='這真是個好消息!你的努力對我們有很大的幫助，$n!', `FemaleText_loc7`='¡Magníficas noticias! Tus esfuerzos nos han salvado, $n.' WHERE `ID`=12846;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제 임무는 딱 하나입니다. 서부 성소가 아무런 이상 없이 돌아가도록 하는 것이죠.$B$B제 용건부터 말할 수밖에 없는 상황을 이해해 주십시오. 보다시피 여기 상황이 걷잡을 수 없이 돌아가고 있습니다.', `FemaleText_loc4`='我的职责只有一个：确保西部圣殿运转顺畅。$B$B请原谅我的坏脾气，就像你所看到的那样，这里的状况已经超出了我的控制。', `FemaleText_loc5`='我的工作包含一個任務也只是唯一的任務:確定西部聖所正常運作。$B$B你要原諒我脾氣這麼差但是，如你所見，這裡的狀況已經有點失控了。', `FemaleText_loc7`='Mi trabajo consiste en una única tarea: asegurar que el Sagrario del Oeste no tenga problemas.$B$BTendrás que disculpar mi temperamento, pero, como puedes ver, la situación se nos ha ido un poco de las manos.' WHERE `ID`=12847;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='쌍둥이 제왕이 죽어 신전 안의 순간이동을 막고 있던 마력이 크게 약해졌습니다. 원하신다면 당신을 제왕의 은신처로 보내 드릴 수 있습니다.', `FemaleText_loc4`='双子皇帝被杀之后，神庙中能够阻止传送法阵的魔法护罩已经远远被削弱了。如果你愿意，我可以将你直接传送到双子皇帝住所那里去。', `FemaleText_loc5`='雙子帝王被殺之後，神廟裡的魔法防護阻礙傳送就大幅衰弱。如果你想的話，我可以將你傳送至帝王的巢穴。', `FemaleText_loc7`='Con la caída de los Emperadores, la protección mágica que impedía teletransportarse en el interior del templo se ha visto gravemente debilitada. Si lo deseas, puedo teletransportarte a la guarida de los Emperadores.' WHERE `ID`=12848;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쌍둥이 제왕의 은신처로 보내 주십시오.', `MaleText_loc4`='请将我传送到双子皇帝的房间去。', `MaleText_loc5`='請將我傳送至雙子帝王的巢穴。', `MaleText_loc7`='Por favor, teletranspórtame a la guarida de los Emperadores Gemelos.', `FemaleText_loc1`='쌍둥이 제왕의 은신처로 보내 주세요.', `FemaleText_loc4`='请将我传送到双子皇帝的房间去。', `FemaleText_loc5`='請將我傳送至雙子帝王的巢穴。', `FemaleText_loc7`='Por favor, teletranspórtame a la guarida de los Emperadores Gemelos.' WHERE `ID`=12849;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아우로의 죽음으로 최후의 방으로 가는 길이 열렸습니다. 원하신다면 그곳으로 보내드릴 수 있습니다.', `FemaleText_loc4`='奥罗死后，通向最后那个密室的道路已经彻底畅通了。如果你愿意的话，我可以把你传送到那边去。', `FemaleText_loc5`='奧羅被殺後通往最後房間的路就顯而易見了。如果你想的話，我可以將你傳送至那裡。', `FemaleText_loc7`='Con la caída de Ouro, el camino hacia la última cámara está despejado. Puedo enviarte allí, si lo deseas.' WHERE `ID`=12850;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최후의 방으로 보내 주십시오.', `MaleText_loc4`='请将我传送到最终密室前。', `MaleText_loc5`='請將我傳送至最後的房間。', `MaleText_loc7`='Por favor, teletranspórtame hasta la última cámara.', `FemaleText_loc1`='최후의 방으로 보내 주세요.', `FemaleText_loc4`='请将我传送到最终密室前。', `FemaleText_loc5`='請將我傳送至最後的房間。', `FemaleText_loc7`='Por favor, teletranspórtame hasta la última cámara.' WHERE `ID`=12851;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='필멸의 세계에서 과거의 삶과 욕망은 아무런 의미가 없다... 이제 주인님을 모시는 수행사제로서 무조건 충성하라! 가장 큰 영광은 주인님을 위해 죽는 것이다!', `FemaleText_loc4`='你们这群凡人，你们的意志一无是处……现在，你们都将成为主人的奴仆，并忠诚地为主人服务！世上最光荣的事莫过于为主人的事业而牺牲！', `FemaleText_loc5`='你們這群凡人，你們的意志一無是處...現在，你們都將成為主人的奴僕，並忠誠地為主人服務!世上最光榮的事莫過於為主人的事業而犧牲!', `FemaleText_loc7`='Su vida hasta ahora, sus deseos mortales no significan nada... ¡ahora son acólitos del amo y le servirán sin cuestionarlo! ¡No hay mayor gloria que morir al servicio del amo!' WHERE `ID`=12852;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='주인님께서 복수해 주실 것이다.', `FemaleText_loc4`='主人……会为我复仇雪耻的！', `FemaleText_loc5`='主人會為我復仇雪恥的!', `FemaleText_loc7`='¡¡El maestro me vengará!!' WHERE `ID`=12853;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네가 졌다!', `FemaleText_loc4`='你败了！', `FemaleText_loc5`='你失敗了!', `FemaleText_loc7`='¡Has fracasado!' WHERE `ID`=12854;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='불쌍한 것 같으니!', `FemaleText_loc4`='可怜虫！', `FemaleText_loc5`='可憐蟲!', `FemaleText_loc7`='¡Patético infeliz!' WHERE `ID`=12855;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='주인님의 이름으로 처단하라!', `FemaleText_loc4`='以主人之名，杀了他们！', `FemaleText_loc5`='以主人之名，殺了他們!', `FemaleText_loc7`='¡Mátalos en el nombre del amo!' WHERE `ID`=12856;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나에게서 도망칠 수는 없다!', `FemaleText_loc4`='休想从我面前逃掉！', `FemaleText_loc5`='休想從我面前逃掉!', `FemaleText_loc7`='¡No puedes esconderte de mí!' WHERE `ID`=12857;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 앞에 무릎을 꿇어라, 벌레들아!', `FemaleText_loc4`='跪下求饶吧，懦夫！', `FemaleText_loc5`='跪下求饒吧，懦夫!', `FemaleText_loc7`='¡Arrodíllate ante mí, sabandija!' WHERE `ID`=12858;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='두 발이 성할 때 도망쳐라!', `FemaleText_loc4`='逃啊！有本事就逃啊！', `FemaleText_loc5`='逃啊!有本事就逃啊!', `FemaleText_loc7`='¡Corre mientras puedas!' WHERE `ID`=12859;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='축제는 즐겁게 보내고 있는가?$b$b불꽃감시자가 축제를 위한 불을 관리하는 자라면 나는 과거의 축제를 관리하던 역사가라 할 수 있다네. 물론 올해의 축제도 기록하겠지. 지금까지는 모든 일이 순조롭게 진행되고 있는 듯 허이, 안 그런가?$b$b자네도 알다시피 축제 기간에 불타는 이 모든 축제의 불에는 고유한 힘이 있다네. 우린 우리의 힘을 관리하고 있는 것이야. 하지만, 분명히 적의 도시 깊숙한 곳에는 아직도 신성한 불꽃이 타오르고 있을 것일세...', `MaleText_loc4`='你还喜欢这里的节日气氛吗，$c？$b$b相对于一个负责照看火炬的火炬看守者, 我更像是一个历史学家，记录着每一次的庆典，当然，今年的庆典我也会记录下来。现在情况进展的不错，你说是不是？$b$b要知道，节庆火炬上燃烧着的圣火中，都蕴涵着强大的力量。我们现在这样监守着我们的火炬，但我相信，敌人的城市里，也有这样熊熊燃烧着的圣火……', `MaleText_loc5`='喜歡這個節慶嗎，$c?$b$b雖說火焰管理者偏向當前的火焰，但我也不只是個只熟悉節慶過去的歷史學家而已。當然，我也記錄今年的節慶活動。目前一切進展的很順利，你不覺得嗎?$b$b你知道的，$n，在節日中持續燃燒的節慶火焰中潛藏著力量。我們看顧著我們的火焰，但我確信在我們敵人的城市深處有著神聖的火焰在燃燒著...', `MaleText_loc7`='¿Estás disfrutando del festival, $c?$b$bMientras los celadores de las llamas se ocupan de las hogueras del presente, yo soy más bien un historiador y me interesan mucho los festivales anteriores. Por supuesto, estoy documentando las celebraciones de este año. De momento, todo está saliendo bien, ¿no crees?$b$b¿Sabes, $n? Hay un poder inherente a todas las hogueras del festival que se prenderán durante estas fiestas. Nosotros cuidamos las nuestras pero estoy seguro de que en las ciudades enemigas arden hogueras sagradas...', `FemaleText_loc1`='축제는 즐겁게 보내고 있는가?$b$b불꽃감시자가 축제를 위한 불을 관리하는 자라면 나는 과거의 축제를 관리하던 역사가라 할 수 있다네. 물론 올해의 축제도 기록하겠지. 지금까지는 모든 일이 순조롭게 진행되고 있는 듯 허이, 안 그런가?$b$b자네도 알다시피 축제 기간에 불타는 이 모든 축제의 불에는 고유한 힘이 있다네. 우린 우리의 힘을 관리하고 있는 것이야. 하지만, 분명히 적의 도시 깊숙한 곳에는 아직도 신성한 불꽃이 타오르고 있을 것일세...', `FemaleText_loc4`='你还喜欢这里的节日气氛吗，$c？$b$b相对于一个负责照看火炬的火炬看守者, 我更像是一个历史学家，记录着每一次的庆典，当然，今年的庆典我也会记录下来。现在情况进展的不错，你说是不是？$b$b要知道，节庆火炬上燃烧着的圣火中，都蕴涵着强大的力量。我们现在这样监守着我们的火炬，但我相信，敌人的城市里，也有这样熊熊燃烧着的圣火……', `FemaleText_loc5`='喜歡這個節慶嗎，$c?$b$b雖說火焰管理者偏向當前的火焰，但我也不只是個只熟悉節慶過去的歷史學家而已。當然，我也記錄今年的節慶活動。目前一切進展的很順利，你不覺得嗎?$b$b你知道的，$n，在節日中持續燃燒的節慶火焰中潛藏著力量。我們看顧著我們的火焰，但我確信在我們敵人的城市深處有著神聖的火焰在燃燒著...', `FemaleText_loc7`='¿Estás disfrutando del festival, $c?$b$bMientras los celadores de las llamas se ocupan de las hogueras del presente, yo soy más bien un historiador y me interesan mucho los festivales anteriores. Por supuesto, estoy documentando las celebraciones de este año. De momento, todo está saliendo bien, ¿no crees?$b$b¿Sabes, $n? Hay un poder inherente a todas las hogueras del festival que se prenderán durante estas fiestas. Nosotros cuidamos las nuestras pero estoy seguro de que en las ciudades enemigas arden hogueras sagradas...' WHERE `ID`=12860;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='놈들을 해치워라! 스컬지들이 우리 도시를 더럽히도록 놔둘 수는 없다!', `FemaleText_loc4`='消灭他们！不要让那些天灾垃圾污染我们的城市！', `FemaleText_loc5`='殺了他們!不要讓天譴軍團廢渣污染了我們的城市!', `FemaleText_loc7`='¡Matadlos! ¡No dejéis que la escoria de la Plaga profane nuestra ciudad!' WHERE `ID`=12861;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='남쪽에서 적들이 오고 있다. 무기를 꺼내라!', `FemaleText_loc4`='敌人们从南方逼近了。准备战斗！', `FemaleText_loc5`='敵人從南方逼近。準備好你的武器!', `FemaleText_loc7`='El enemigo se acerca por el sur. ¡Tened las armas listas!' WHERE `ID`=12862;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='언데드가 접근하고 있다. 공격!', `FemaleText_loc4`='亡灵在靠近，进攻！', `FemaleText_loc5`='不死族正在逼近。攻擊!', `FemaleText_loc7`='Se acercan los no-muertos. ¡Ataca!' WHERE `ID`=12863;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저기 $n, 알아낸 것 같아요!', `FemaleText_loc4`='$n，我想我已经搞明白了！', `FemaleText_loc5`='好了，$n，我想我弄懂了!', `FemaleText_loc7`='Mira, $n, ¡creo que lo he entendido!' WHERE `ID`=12983;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 누가 나의 성소를 더럽히는가? 경고하노니, 침입자는 모두 파멸을 맞으리라...', `MaleText_loc4`='谁敢侵入我的神圣领域！我警告你们：曾有许多蠢货入侵这里，他们都已经死了！', `MaleText_loc5`='誰敢侵入我的神聖領域!我警告你們:曾有許多蠢貨入侵這裏，他們都已經死了!', `MaleText_loc7`='¿Quién se atreve a profanar mi territorio? Les advierto: ¡quienes ingresen sin autorización están acabados!' WHERE `ID`=12984;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어리석은... 너희가 성공했다고 생각하나? 이제 한 발짝 더 다가왔을 뿐이다. 끝없는 심연으로!', `MaleText_loc4`='蠢货！你们以为胜券在握了吗？你们只不过是离地狱更近了一步而已。', `MaleText_loc5`='蠢貨!你們以為勝券在握了嗎?你們只不過是離地獄更近了一步而已。', `MaleText_loc7`='¡Tontos! ¿Se consideran triunfadores? ¡Sólo han dado un paso más hacia el abismo!' WHERE `ID`=12985;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 놀음도 이젠 지겹군. 와라, 너희 영혼을 망각의 저편으로 보내 주마!', `MaleText_loc4`='这场游戏已经让我觉得无聊了。继续吧，到我这里来，我会亲自毁灭你们的灵魂！', `MaleText_loc5`='這場遊戲已經讓我覺得無聊了。繼續吧，到我這裏來，我會親自毀滅你們的靈魂!', `MaleText_loc7`='Me cansé de estos juegos. ¡Avancen, y expulsaré sus almas al olvido eterno!' WHERE `ID`=12986;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 공포가 닥쳐올지 모르는군. 지금까진 아무것도 아니다. 기다리고 있노라. 낙스라마스의 얼어붙은 심장이!', `MaleText_loc4`='看来你们还不知道自己将面临怎样的恐怖？看来你们根本一无所知！纳克萨玛斯的霜寒之心正等待着你们！', `MaleText_loc5`='看來你們還不知道自己將面臨怎樣的恐怖?看來你們根本一無所知!納克薩瑪斯的霜寒之心正等待著你們!', `MaleText_loc7`='No tienen idea de los espantos que acechan. ¡No han visto nada! ¡El corazón gélido de Naxxramas los espera!' WHERE `ID`=12987;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곧, 우리는 얼라이언스와 호드를 멸망시킬 것이다. 그러면 아제로스의 나머지 세력 또한, 내 강력한 군대 앞에 무릎을 꿇겠지.', `MaleText_loc4`='联盟和部落很快就将被我们瓦解，之后，艾泽拉斯大陆也必然被天灾大军征服。', `MaleText_loc5`='我們很快就會消滅聯盟與部落。然後整個艾澤拉斯就會落入我軍的掌握之中。', `MaleText_loc7`='Pronto erradicaremos la Alianza y la Horda. Luego el resto de Azeroth sucumbirá ante el poder de mi ejército.' WHERE `ID`=12988;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자라고? 여기에? 켈투자드, 저들을 없애라! 낙스라마스가 함락돼서는 안 돼!', `MaleText_loc4`='入侵者……这里？！消灭他们，克尔苏加德！纳克萨玛斯绝不能被攻陷！', `MaleText_loc5`='入侵者...在這裡?!消滅他們，科爾蘇加德!納克薩瑪斯絕不能陷落!', `MaleText_loc7`='Invasores... ¡¿aquí?! ¡DESTRÚYELOS, Kel''Thuzad! ¡Naxxramas no debe caer!' WHERE `ID`=12989;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나의 주군이시여, 당신의 군대는 적을 쓸어버릴 준비가 되었습니다.', `MaleText_loc4`='大军几乎已经整装待发，随时可以从后方突袭敌人，陛下。', `MaleText_loc5`='陛下，您的軍隊幾乎已經準備好要進行反擊了。', `MaleText_loc7`='Sus fuerzas ya casi están en orden para contraatacar al enemigo, mi señor.' WHERE `ID`=12990;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇습니다, 주인님. 저들의 완전한 파멸이 눈앞에 다가왔습니다... 이건 뭐지?', `MaleText_loc4`='是的，主人，他们的最终末日马上即将降临了……这是什么?', `MaleText_loc5`='是的，主人。他們的終極毀滅即將到來...這是什麼?', `MaleText_loc7`='Si, amo. Se aproxima la hora de su extinción... ¿Qué es esto?' WHERE `ID`=12991;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명령을 따르겠습니다... 주인님!', `MaleText_loc4`='如您所愿，主人！', `MaleText_loc5`='如你所願，主人!', `MaleText_loc7`='¡Como ordene, amo!' WHERE `ID`=12992;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와라, 영웅이여... 리치 왕의 의지에 따라 넌 죽어야만 한다.', `MaleText_loc4`='来呀，英雄们……巫妖王命令已下，你们就都要死。', `MaleText_loc5`='來吧，英雄...依循巫妖王的意志，你將被摧毀。', `MaleText_loc7`='Venid, valientes... Por el poder del Rey Exánime, seréis destruidos.' WHERE `ID`=12993;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋다. 얼어붙은 땅의 전사들이여, 일어나라! 너희에게 싸울 것을 명하노라. 날 위해 죽고, 날 위해 죽여라! 한 놈도 살려두지 마라!', `MaleText_loc4`='很好，冰荒废土的战士们，起来吧！我命令你们为主人而战斗，杀戮，直到死亡！一个活口都不要留！', `MaleText_loc5`='非常好，凍原的戰士們，起來吧!我命令你們作戰，為你們的主人殺戮或獻身吧!不要留下活口!', `MaleText_loc7`='Muy bien. Guerreros de los páramos helados, ¡levántense! ¡Les ordeno luchar, matar y morir por su amo! ¡Que nadie sobreviva!' WHERE `ID`=12994;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자비를 구하라!', `MaleText_loc4`='祈祷我的慈悲吧！', `MaleText_loc5`='祈禱我的慈悲吧!', `MaleText_loc7`='¡Ruega por piedad!' WHERE `ID`=12995;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마지막 숨이나 쉬어라!', `MaleText_loc4`='呼出你的最后一口气！', `MaleText_loc5`='呼出你的最後一口氣!', `MaleText_loc7`='¡Exhala el último aliento!' WHERE `ID`=12996;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최후를 맞이하라!', `MaleText_loc4`='你的末日临近了！', `MaleText_loc5`='你的末日臨近了!', `MaleText_loc7`='¡El final se cierne sobre ti!' WHERE `ID`=12997;
