UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠의 문지기와 하수인, 그리고 병사들이여! 나 켈투자드가 부르니 명을 받들라!', `MaleText_loc4`='仆从们，侍卫们，隶属于黑暗与寒冷的战士们！听从克尔苏加德的召唤！', `MaleText_loc5`='僕從們，侍衛們，隸屬於黑暗與寒冷的戰士們!聽從科爾蘇加德的召喚!', `MaleText_loc7`='¡Lacayos, servidores, soldados de la fría oscuridad! ¡Obedezcan el llamado de Kel''Thuzad!' WHERE `ID`=12999;
