UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 도망쳐! 더 신선한 피가 솟구칠 테니!', `MaleText_loc4`='对，跑吧！那样伤口出血就更多了！', `MaleText_loc5`='對，跑吧!那樣傷口出血就更多了!', `MaleText_loc7`='Eso… ¡Corran! ¡Así la sangre circula más rápido!' WHERE `ID`=13003;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 손님 맞이할 시간이군.', `MaleText_loc4`='啊……欢迎来到我的大厅。', `MaleText_loc5`='啊...歡迎來到我的大廳。', `MaleText_loc7`='Ah… ¡les doy la bienvenida a mi sala!' WHERE `ID`=13004;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쉬이... 이제 다 끝이다.', `MaleText_loc4`='嘘……很快一切就都结束了。', `MaleText_loc5`='噓...很快一切就都結束了。', `MaleText_loc7`='Shhh... pronto acabará todo.' WHERE `ID`=13005;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조그만 심장 뛰는 소리가 들린다. 오, 점점 빨리... 곧 멈추게 해주마.', `MaleText_loc4`='哦，我听见不少声音啊……不过马上就都要停止了。', `MaleText_loc5`='哦，我聽見一些可愛的小心臟在跳呢，哦哦，跳得更快了...不過馬上就都要停止了。', `MaleText_loc7`='Oigo corazones latiendo. Sí... se aceleran... y pronto se detendrán.' WHERE `ID`=13006;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디로 갈까? 무얼 할까? 모두 다 부질없는 것! 고통과 죽음만이 기다릴 뿐...', `MaleText_loc4`='去哪里？做什么？太多的选择，可这一切都会在痛苦与死亡中终结。', `MaleText_loc5`='去哪裡?做什麼?太多的選擇，可這一切都會在痛苦與死亡中終結。', `MaleText_loc7`='¿Adónde ir? ¿Qué hacer? Tantas opciones que terminan en sufrimiento… y muerte de todas formas…' WHERE `ID`=13007;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어느 놈부터 먹어줄까? 참 고르기 어렵군. 다들 맛있을 것 같단 말이야...', `MaleText_loc4`='我该先吃谁呢？真是难以选择。每一个闻起来都这么鲜美……', `MaleText_loc5`='我該先吃誰呢?真是難以選擇。每一個聞起來都這麼鮮美...', `MaleText_loc7`='¿A quién me comeré primero? Qué difícil, todos huelen tan bien...' WHERE `ID`=13008;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가까이 오라, 한입 거리들아! 군침이 도는구나. 너무 오랫동안 굶주려 있었어...', `MaleText_loc4`='哦，小点心终于来了。我好久都没有吃肉和饮用鲜血了。', `MaleText_loc5`='哦，小點心終於來了。我好久都沒有吃肉和飲用鮮血了。', `MaleText_loc7`='Acérquense. Qué bocados tan sabrosos. Hace mucho tiempo que no como y no bebo sangre.' WHERE `ID`=13009;
