UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오, 젤리에크! 손님 쫓지 마! 좀 더 즐겨야 하지 않겠어?!', `FemaleText_loc4`='嘿，瑟里耶克，别把他们赶跑了。等我们玩够了再说！', `FemaleText_loc5`='嘿，札里克，別把他們趕跑了。等我們玩夠了再說!', `FemaleText_loc7`='Vamos, Zeliek, no los eches. No antes de divertirnos un rato.' WHERE `ID`=13014;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='살아남아 있길 바란다. 내 소개를 하기 전까지는...', `FemaleText_loc4`='真希望他们能撑久点儿，至少让我做完……自我介绍。', `FemaleText_loc5`='真希望他們能撐久點兒，至少讓我做完...自我介紹。', `FemaleText_loc7`='Espero que no mueran antes de que me presente... como es debido.' WHERE `ID`=13015;
