UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너의 영혼은 이제 내 것이다!', `MaleText_loc4`='你的灵魂现在属于我了！', `MaleText_loc5`='你的靈魂現在屬於我了!', `MaleText_loc7`='¡Tu alma ahora está ligada a mí!' WHERE `ID`=13017;
