UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으아아! 아직... 기뻐하긴 이르지... 승리는 잠깐일 뿐! 상상조차 할 수 없는 강력한 존재로 돌아오겠다!', `MaleText_loc4`='啊！别……高兴得……太早了！你们的胜利空洞而虚无，没有任何意义，我很快就将卷土重来！', `MaleText_loc5`='啊!別...高興得...太早了!你們的勝利空洞而虛無，沒有任何意義，我很快就將捲土重來!', `MaleText_loc7`='¡Ah! ¡No… te… alegres! Tu victoria es vana, ¡pues regresaré con poderes inconcebibles!' WHERE `ID`=13019;
