UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오랫동안 기다렸다. 이제 영혼 착취자를 만날 차례다.', `MaleText_loc4`='我已经等待很久了。现在你们将面对灵魂的收割者。', `MaleText_loc5`='我已經等待很久了。現在你們將面對靈魂的收割者。', `MaleText_loc7`='Ya he esperado suficiente. Ahora se enfrentaran al Recolector de almas.' WHERE `ID`=13028;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어리석은 것들, 스스로 죽음을 자초하다니! 감히 넘보지도 못할 힘을 무시하느냐? 그래도 가까스로 이 고딕 님의 영역까지 침범했구나. 자, 이제 출구는 하나뿐이다. 쓸쓸히 황천으로 가는 길이지.', `MaleText_loc4`='你们这些蠢货已经主动步入了陷阱。你们正在挑战一个无比强大的存在。虽然你们经历了千难万险才来到收割者的领域，来到我的面前，但是现在，活下来的唯一途径就是加入诅咒神教。', `MaleText_loc5`='你們這些蠢貨已經主動步入了陷阱。你們正在挑戰一個無比強大的存在。雖然你們經歷了千難萬險才來到收割者的領域，來到我的面前，但是現在，活下來的唯一途徑就是加入詛咒神教。', `MaleText_loc7`='Su estupidez los ha llevado hasta la muerte. Han hecho caso omiso de poderes más allá de su entendimiento descaradamente. Han intentado invadir el reino del recolector con todas sus fuerzas. Ahora solo les queda una salida... recorrer en solitario... el camino de los malditos.' WHERE `ID`=13029;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어리석은 것들, 스스로 죽음을 자초하다니!', `MaleText_loc4`='你们这些蠢货已经主动步入了陷阱。', `MaleText_loc5`='你們這些蠢貨已經主動步入了陷阱。', `MaleText_loc7`='Su estupidez los ha llevado hasta la muerte.' WHERE `ID`=13030;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 넘보지도 못할 힘을 무시하느냐?', `MaleText_loc4`='你们正在挑战一个无比强大的存在。', `MaleText_loc5`='你們正在挑戰一個無比強大的存在。', `MaleText_loc7`='Insolentemente han hecho caso omiso de poderes más allá de su entendimiento.' WHERE `ID`=13031;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래도 가까스로 이 고딕 님의 영역까지 침범했구나.', `MaleText_loc4`='虽然你们经历了千难万险才来到收割者的领域，来到我的面前。', `MaleText_loc5`='雖然你們經歷了千難萬險才來到收割者的領域，來到我的面前。', `MaleText_loc7`='Han intentar invadir el reino del recolector con todas sus fuerzas.' WHERE `ID`=13032;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 이제 출구는 하나뿐이다. 쓸쓸히 황천으로 가는 길이지.', `MaleText_loc4`='但是现在，活下来的唯一途径就是加入诅咒神教。', `MaleText_loc5`='但是現在，活下來的唯一途徑就是加入詛咒神教。', `MaleText_loc7`='Ahora solo les queda una salida... recorrer en solitario... el camino de los condenados.' WHERE `ID`=13033;
