UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 무슨 개떡같은 일이!', `MaleText_loc4`='哦……又要血流成河了！', `MaleText_loc5`='哦...又要血流成河了!', `MaleText_loc7`='¡Qué forma de derrochar sangre!' WHERE `ID`=13035;
