UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 그만 좀 지껄여라! 주둥이 닥치란 말이다!', `MaleText_loc4`='哭哭闹闹！没完没了！我都听烦了！你们要是不能闭上嘴，我来帮你们！', `MaleText_loc5`='哭哭鬧鬧!沒完沒了!我都聽煩了!你們要是不能閉上嘴，我來幫你們!', `MaleText_loc7`='¡No quiero oír más lloriqueos! ¡Cierren la boca antes de que las cierre yo!' WHERE `ID`=13039;
