UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모든 종족은 멸망할 것이다. 시간문제일 뿐이지!', `MaleText_loc4`='世间的一切种族终将灭绝，这是迟早的事情。', `MaleText_loc5`='世間的一切種族終將滅絕，這是遲早的事情。', `MaleText_loc7`='Las razas del mundo perecerán. Es solo cuestión de tiempo.' WHERE `ID`=13046;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보인다. 끝없는 고통이... 보인다. 고통과 분노가... 내게는 모든 것이 보인다.', `MaleText_loc4`='我看到了无尽的苦难。我看到了无穷的折磨。我看见了滔天的愤怒。我……看到了一切……', `MaleText_loc5`='我看到了無盡的苦難。我看到了無窮的折磨。我看見了滔天的憤懣。我...看到了一切...', `MaleText_loc7`='Veo sufrimiento sin fin. Veo tormento. Veo furia. Lo veo todo...' WHERE `ID`=13047;
