UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 힘은 미약하지만 언제든지 돕겠습니다, 잘둔.', `MaleText_loc4`='我所有的治疗之力都听从你的支配，扎尔杜。', `MaleText_loc5`='我貧乏的治療力量任你差遣，薩度恩。', `MaleText_loc7`='Mis exiguos poderes de sanación están a tu disposición, Zalduun.' WHERE `ID`=13111;
