UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런, 안 돼! 죽으면 안 돼!', `MaleText_loc4`='啊，不！这一个快不行了！', `MaleText_loc5`='喔不!我救不了這一個!', `MaleText_loc7`='¡Oh, no! ¡Estoy perdiendo a este!' WHERE `ID`=13113;
