UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c님, 즐거운 축제 보내고 계신가요? 제가 파는 상품으로 당신의 하루가 더 즐거워질 수 있답니다. 따뜻한 음료와 음식 같은 건 아무것도 아니에요!$b$b아직 해보지 않았다면, 친구를 몇 명 데리고 와서 축제 기둥 주위에서 축제를 즐겨보세요. 기운이 솟아날 거예요!', `MaleText_loc4`='庆典上过得可愉快，$c？我的东西能让你过的更加高兴一些。没什么能比热乎乎的食物和美酒更好的了！$b$b要是你还没试过，一定要叫上一两个朋友一起去彩旗那边参加庆祝，一定会让你很开心的！', `MaleText_loc5`='喜歡這個節慶嗎，$c?我的商品可以讓你的生活畫龍點睛。沒有什麼比熱騰騰的食物和飲料更好的了!$b$b如果你還沒有試過，找一兩個朋友在緞帶柱旁慶祝;一定會讓你振奮精神的!', `MaleText_loc7`='¿Estás disfrutando del festival, $c? Mis mercancías pueden contribuir a tu diversión. ¡No hay nada como una buena comida caliente y bebida!$b$bY si aún no lo has probado, tráete al menos a un amigo y baila alrededor del poste de las cintas, ¡os levantará el ánimo!', `FemaleText_loc1`='$c님, 즐거운 축제 보내고 계신가요? 제가 파는 상품으로 당신의 하루가 더 즐거워질 수 있답니다. 따뜻한 음료와 음식 같은 건 아무것도 아니에요!$b$b아직 해보지 않았다면, 친구를 몇 명 데리고 와서 축제 기둥 주위에서 축제를 즐겨보세요. 기운이 솟아날 거예요!', `FemaleText_loc4`='庆典上过得可愉快，$c？我的东西能让你过的更加高兴一些。没什么能比热乎乎的食物和美酒更好的了！$b$b要是你还没试过，一定要叫上一两个朋友一起去彩旗那边参加庆祝，一定会让你很开心的！', `FemaleText_loc5`='喜歡這個節慶嗎，$c?我的商品可以讓你的生活畫龍點睛。沒有什麼比熱騰騰的食物和飲料更好的了!$b$b如果你還沒有試過，找一兩個朋友在緞帶柱旁慶祝;一定會讓你振奮精神的!', `FemaleText_loc7`='¿Estás disfrutando del festival, $c? Mis mercancías pueden contribuir a tu diversión. ¡No hay nada como una buena comida caliente y bebida!$b$bY si aún no lo has probado, tráete al menos a un amigo y baila alrededor del poste de las cintas, ¡os levantará el ánimo!' WHERE `ID`=13119;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='축제 물품을 보여 주십시오.', `MaleText_loc4`='让我来看看你的节日大餐吧。', `MaleText_loc5`='讓我看看你的節慶大餐。', `MaleText_loc7`='Deja que eche un vistazo a tus mercancías para el festival.', `FemaleText_loc1`='축제 물품을 보여 주세요.', `FemaleText_loc4`='让我来看看你的节日大餐吧。', `FemaleText_loc5`='讓我看看你的節慶大餐。', `FemaleText_loc7`='Deja que eche un vistazo a tus mercancías para el festival.' WHERE `ID`=13120;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='느껴지는가? 불쌍한 생명체들이여! 이 땅에 드리워진 그림자는 전주곡에 불과했다. 머지않아 너희들이 소중히 여기는 모든 것이 우리 손아귀에 들어올 것이다. 너희는 리치 왕의 힘 앞에 무릎을 꿇으리라.', `MaleText_loc4`='你们能感觉到吧，可怜虫？现在的侵攻只是一个开始，很快你们所珍视的一切都将成我们的所有品！你们所有人会败倒在巫妖王面前！', `MaleText_loc5`='你感覺到了嗎，可悲的生物?籠罩這片大地的只是個前兆。你那珍貴的領地很快就會落入我們手中了!你會在巫妖王的力量前倒下!', `MaleText_loc7`='¿Pueden sentirlo, criaturas patéticas? El velo que cubre esta tierra no es más que el comienzo. ¡Muy pronto sus tierras estarán en nuestro poder! ¡Caerán ante el poder del Rey Exánime!' WHERE `ID`=13121;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절망과 두려움에 떠는 필멸의 종족들이여, 운명의 날이 다가왔다!', `MaleText_loc4`='绝望吧，凡人！你们的末日来临啦！', `MaleText_loc5`='絕望吧，人類!你們的死期到了!', `MaleText_loc7`='¡Desistan, mortales! ¡Ha llegado su hora!' WHERE `ID`=13122;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 검은 그림자를 보아라! 스컬지의 그림자가 온 세상을 뒤덮었노라. 도망칠 곳은 어디에도 없다!', `MaleText_loc4`='就让这深深地绝望提醒你：天灾军团的阴影必将笼罩一切！没有人可以逃得掉！', `MaleText_loc5`='讓這絕望提醒你:天譴軍團的黑暗勢力正全面包圍!沒有人逃得掉!', `MaleText_loc7`='Que esta penumbra os sirva para recordar que la sombra de la Plaga lo cubre todo. ¡No hay escapatoria!' WHERE `ID`=13123;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희가 전투에서 쓰러질수록 스컬지의 세력은 강해질 것이다. 너희의 운명은 오직 하나뿐! 종말을 맞을 준비를 해라!', `MaleText_loc4`='你们当中不断有人倒下，而我们的力量却在战斗中日益庞大。毁灭的结局已经不可避免。准备迎接末日吧！', `MaleText_loc5`='當你在戰爭中倒下，我們仍持續增強力量。只有一種無法避免的結果。準備等死吧!', `MaleText_loc7`='A medida que ustedes caen en la batalla, nosotros nos hacemos más fuertes. Solo hay un posible desenlace, y es inevitable. ¡Prepárense para su fin!' WHERE `ID`=13124;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전진, 나의 영웅들이여! 앞으로 나아가라! 누구도 우리 앞길을 막을 수는 없다!', `MaleText_loc4`='前进，我的仆从们！前进！扫平我们道路上的一切障碍！', `MaleText_loc5`='前進，我的奴僕們!前進!誰敢擋路就殺誰!', `MaleText_loc7`='¡Adelante, esbirros! ¡Adelante! ¡No permitáis que nadie se interponga en nuestro camino!' WHERE `ID`=13125;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 힘 앞에 벌벌 떨게 될 것이다! 도망쳐라! 승리는 산 자들의 것이 아니다!', `MaleText_loc4`='臣服在我们的力量面前吧！活人永远不可能取得胜利！', `MaleText_loc5`='在我們的力量面前畏縮!快逃!活人不會有勝利的!', `MaleText_loc7`='¡Doblegaos ante nuestro poder! ¡Huid! ¡Los vivos nunca alcanzarán la victoria!' WHERE `ID`=13126;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도대체 어떤 함정에 빠진 거지? 구원자들이여, 무기를 꺼내라!', `MaleText_loc4`='这是怎么回事？守备官，准备战斗！', `MaleText_loc5`='我們走進了什麼樣的陷阱?復仇者，準備好你們的武器!', `MaleText_loc7`='¿En qué tipo de trampa hemos caído? ¡Vindicadores, preparen sus armas!' WHERE `ID`=13127;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 빠져나갈 수 없을 거다!', `MaleText_loc4`='别想逃过此劫！', `MaleText_loc5`='你不會僥倖成功的!', `MaleText_loc7`='¡No te vas a salir con la tuya!' WHERE `ID`=13128;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디 실력을 보여봐라!', `MaleText_loc4`='菜鸟，让我看看你都有什么能耐！', `MaleText_loc5`='讓我看看你有什麼本事，菜鳥!', `MaleText_loc7`='¡Enséñame lo que sabes, $gnovato:novata;!' WHERE `ID`=13129;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 네가 할 수 있는 최선이란 말이냐?', `MaleText_loc4`='这是你的最高水平了吗？', `MaleText_loc5`='你只能做到這樣嗎?', `MaleText_loc7`='¿Eso es todo lo que sabes hacer?' WHERE `ID`=13130;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 너와 네 동료 뿐만 아니라 나의 시간도 빼앗고 있구나!', `MaleText_loc4`='你，你，还有你，根本就是在浪费同学们的时间，浪费我的时间。', `MaleText_loc5`='你不只在浪費其他學生的時間，也在浪費我的時間。', `MaleText_loc7`='Nos haces perder el tiempo a tus compañeros y a mí.' WHERE `ID`=13131;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='애처롭군...', `MaleText_loc4`='废柴……扣你五十个学分！', `MaleText_loc5`='真可悲...', `MaleText_loc7`='Patético...' WHERE `ID`=13132;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='붉은마루 산맥에 살고 계신 우리 할머님이라도 너 같은 풋내기보단 더 잘하겠군, 흥!', `MaleText_loc4`='我那个住在赤脊山的奶奶出拳都比你重，菜鸟！', `MaleText_loc5`='我住在赤脊山的老太太打假人都比你用力的多，新手!', `MaleText_loc7`='¡Mi abuelita, que vive en Crestagrana, pega más fuerte que tú!' WHERE `ID`=13133;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈은 이 훈련을 견뎌내기엔 역부족이로구나. 나약한 계집애 같은 녀석은 켈투자드 님께 필요 없다...', `MaleText_loc4`='嘿，这位学徒，你该不会是找了份错误的工作吧。克尔苏加德不需要卖花姑娘……', `MaleText_loc5`='我認為你接了份錯誤的工作，初學者。科爾蘇加德不需要任何賣花的女孩...', `MaleText_loc7`='Creo que te has equivocado de trabajo, $giniciado:iniciada;. Kel''Thuzad no precisa a blandengues como tú...' WHERE `ID`=13134;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='웃자고 한 소린가?', `MaleText_loc4`='这是在搞笑吗？', `MaleText_loc5`='這是個笑話嗎?', `MaleText_loc7`='¿Se trata de algún tipo de broma?' WHERE `ID`=13135;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마침 몸 좀 풀려던 참인데 내 상대가 되어 줄 텐가? 혼쭐나기 싫으면 꾸물거리지 말고 움직여!', `MaleText_loc4`='在我把这些假人换成你们，并且拿你们好好热身之前，你们最好拿出点像样的东西来！', `MaleText_loc5`='在我把你跟那個活動假人調換位置並且開始熱身之前開始動作!', `MaleText_loc7`='¡Haz algo antes de que sustituya el muñeco-diana por ti y empiece con mi particular sesión de calentamiento!' WHERE `ID`=13136;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='교관님, 저 수습생은 아무짝에도 쓸모가 없습니다! 실력은 별볼일없으면서 변명만 늘어놓습니다.', `MaleText_loc4`='学生我毫无价值，长官！我为这次失误而向您道歉，长官！', `MaleText_loc5`='學生無用，老師!學生為他的不足道歉!', `MaleText_loc7`='¡El alumno es despreciable, maestro! ¡El alumno se disculpa por su incompetencia!' WHERE `ID`=13137;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 교관님. 전 보잘것없는 녀석입니다!', `MaleText_loc4`='我微不足道，渺小至极，长官！', `MaleText_loc5`='我不值得，老師!', `MaleText_loc7`='¡No soy digno!' WHERE `ID`=13138;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='교관님, 앞으로 더 열심히 하겠습니다!', `MaleText_loc4`='我们会更加努力的，长官！', `MaleText_loc5`='學生會更認真學習的，老師!', `MaleText_loc7`='¡El alumno se esforzará más, maestro!' WHERE `ID`=13139;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='교관님, 저 멍청한 수습생을 혼내 주십시오.', `MaleText_loc4`='长官，学生希望您对我的愚钝做出惩罚！', `MaleText_loc5`='長官，學生要求你處罰他的無知!', `MaleText_loc7`='¡Señor, el alumno le pide que le golpee por su ignorancia!' WHERE `ID`=13140;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; $n에게 공습 신호를 보냅니다.', `MaleText_loc4`='%s将$n标记为空袭目标。', `MaleText_loc5`='%s為空襲標示$n。', `MaleText_loc7`='%s marca a $n para un ataque aéreo.' WHERE `ID`=13141;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일거리를 찾고 있다면 곡괭이를 들고 발굴 장소로 가보십시오. 저 멀리 보이는 곳에 유적이 있습니다!', `MaleText_loc4`='如果你在找活干的话，$c，拿起锄头去挖吧。你没看到那边有一大堆废墟么？', `MaleText_loc5`='如果你在找工作，$C，拿起一個工具開始挖吧。這裡所見都是廢墟!', `MaleText_loc7`='Si buscas trabajo, $c, agarra un pico y ponte a cavar. ¡Hay ruinas hasta donde alcanza la vista!' WHERE `ID`=13142;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='반갑습니다. 제 동료인 로서의 후예들과 저는 지금까지 근 20년 동안, 이 비참한 세계를 위해 애써왔습니다. 우리는 온 힘을 다해 버텨왔지만 현재 직면한 위협이 과거의 실패에서 비롯된 그림자라는 사실에 놀라움을 금할 길이 없군요.$B$B그들에게 보상할 수 있도록 도와주시겠습니까?', `FemaleText_loc4`='你好，$n。我们洛萨之子已经被困在这个破败的世界中近二十年了。我们尽自己所能生存了下来，但是令我惊讶的是，我们现在所面对的威胁只不过是我们过去失败的影子。$B$B也许你可以帮助我们来弥补这一切？', `FemaleText_loc5`='你好，$n。我親愛的洛薩之子，我困在這個悲慘的世界已經接近二十年了。我們盡力做到最好，但我們過去失敗的陰影威脅今日依舊令人感到震驚。$B$B或許你願意幫助我們改正它?', `FemaleText_loc7`='Saludos, $n. Mis compañeros de los Hijos de Lothar y yo llevamos casi veinte años atrapados en este deprimente mundo. Hemos aguantado lo mejor que hemos podido, pero es asombroso ver que los peligros a los que nos enfrentamos hoy no son más que nuestros fracasos pasados.$B$B¿Nos ayudarás tú a superarlos?' WHERE `ID`=13143;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 혹시 광산에 대한 소식을 가져온 건가? 그런가?', `MaleText_loc4`='我不指望你给我带来了矿洞的消息，有吗？', `MaleText_loc5`='我想你不會帶著礦坑的消息來，對吧?', `MaleText_loc7`='Supongo que no traes noticias de las minas, ¿verdad?' WHERE `ID`=13144;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$c|1이여;여;, 아웃랜드가 얼마나 많이 오염되는지 생각해보면 정말 놀라지 않을 수가 없지. 우리세나리온 의회는 이곳 생물들이 어떻게 살아남았는지 알아내고자 하네. 오염된 이 땅과 생물들을 연구해 보면 우리 세계의 병든 부분을 치료할 방법을 알아낼지도 모르니까 말이야.', `FemaleText_loc4`='外域被污染的范围之大非常令人震惊，$c。塞纳里奥议会希望去了解这里的生物是怎么生存下来的。了解这个破碎、扭曲的世界和它的居民，也许我们可以学习到治愈我们自己世界的方法。', `FemaleText_loc5`='外域的腐敗程度真的相當驚人，$c。塞納里奧議會想了解這土地的生物如何在這麼艱難的環境下生存。研究這塊破碎，受盡折磨的土地和它的居民，或許能教我們如何治療這生病的世界。', `FemaleText_loc7`='La corrupción de Terrallende llega a extremos increíbles, $c. El Círculo Cenarion intenta comprender cómo han podido sobrevivir esas criaturas. El estudio de esta tierra desolada y maldita puede ayudarnos a encontrar la forma de curar algunas partes de nuestro propio mundo.' WHERE `ID`=13145;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 땅에 벌어진 일을 목격하니 가슴이 아프네. 우리 세나리온 원정대는 그 피해를 파악하고 복구하기 위해 할 수 있는 일은 무엇이든 할 것이네.', `MaleText_loc4`='我很伤心地看着在这片大地上发生的一切。塞纳里奥远征队会尽全力了解和治愈那些创伤。', `MaleText_loc5`='外域的腐敗程度真的相當驚人，$c。塞納里奧遠征隊想了解這土地的生物如何在這麼艱難的環境下生存。研究這塊破碎，受盡折磨的土地和它的居民，或許能教我們如何治療這生病的世界。', `MaleText_loc7`='Es triste ver lo que le ha pasado a esta tierra. La expedición de Cenarion hará lo que pueda para comprender el daño que se ha causado y repararlo.' WHERE `ID`=13146;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='길을 잃은 것 같군, $c|1이여;여;. 당신을 다른 일꾼들과 함께 성벽 작업에 투입하는 일이 없으면 좋겠는데...', `MaleText_loc4`='$C，你似乎很迷茫。不要逼我让你跟那些苦工一起干活。', `MaleText_loc5`='你看起來若有所失，$c。不要逼我讓你和那些苦工一樣到牆上去工作。', `MaleText_loc7`='Parece que no tienes muy claro dónde estás, $c. No me hagas ponerte a trabajar en los muros con los otros peones.' WHERE `ID`=13147;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$c|1이여;여;, 만나서 반갑습니다. 정말 때맞춰 스랄마에 오셨군요. 대족장께서는 직접 오실 수가 없어서 이곳 업무를 우리에게 전적으로 위임하셨답니다.', `FemaleText_loc4`='见到你真好，$c。你来的真及时。酋长不能亲自来这里，所以全靠我们了。', `FemaleText_loc5`='你好，$c。你在這時候到達索爾瑪是最好的時機了。大酋長需要我們，因為他不能獨自在這裡。', `FemaleText_loc7`='Hola, $c. Tu llegada a Thrallmar no podría haber ocurrido en mejor momento. El Jefe de Guerra cuenta con nosotros, ya que no puede estar aquí él mismo.' WHERE `ID`=13148;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 스랄마에는 당신의 힘이 필요하오. 대족장님께는 당신의 도움이 필요하오. 임무를 수행할 준비를 해두시오.', `MaleText_loc4`='萨尔玛需要你，$c。酋长需要你。做好准备去完成你的职责吧。', `MaleText_loc5`='索爾瑪需要你，$c。大酋長需要你。準備好履行你的職責。', `MaleText_loc7`='Thrallmar te necesita, $c. El Jefe de Guerra te necesita. Debes estar a punto para cumplir con tu deber.' WHERE `ID`=13149;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 저주가 내릴 것이다, 침입자 녀석! 리치 왕께서 이끄는 군대가 널 추적하리라. 운명의 굴레를 벗어나지는 못할 것이야...', `MaleText_loc4`='不！！！诅咒你，入侵者，诅咒你！巫妖王的军团一定会杀死你的。你逃避不了必然的命运……', `MaleText_loc5`='不!!!我詛咒你們這些闖入者!巫妖王的軍隊會追擊你們。你們逃不過命運的...', `MaleText_loc7`='¡No! ¡Malditos sean, intrusos! Los ejércitos del Rey Exánime les darán caza. No evadirán su destino…' WHERE `ID`=13150;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요, $n. 저는 조니 맥위크소스라고 합니다. 저는 테스트 목적으로 사용될 특정한 기능들을 수행하도록 되어 있습니다. 저는 이번 테스트 기간 동안 다음의 2가지 사항을 도와드릴 수 있습니다.$B$B1(1) 당신을 낙스라마스와의 조화 퀘스트를 완료된 상태로 설정하여 사령관 엘리고르 돈브링어로부터 ''전쟁의 메아리'' 퀘스트를 받을 수 있도록 도와드릴 수 있습니다. 이 퀘스트를 먼저 완료하셔야만 새로운 방어구 세트 퀘스트를 받으실 수 있습니다.$B$B(2) 낙스라마스로 당신을 순간이동시켜드릴 수 있습니다.$B$B자, 그럼 무엇을 도와드릴까요?', `MaleText_loc4`='Greetings, $n. I am Johnny McWeaksauce. I am used as a tool by developers to carry out specific functions for the purpose of testing. For this test period, I am set to do two specific things:$B$B(1) Flag you as having done the Naxxramas attunement quest so that you are able to accept the next quest, "Echoes of War" from Commander Eligor Dawnbringer. You must first complete that quest to be able to access the quests for your Tier 3 armor set.$B$B(2) Teleport you to Naxxramas.$B$BWhat is it that you require?', `MaleText_loc5`='你好，$n。我是強尼·麥克威醬。我被開發者用來實行特殊的功能做為測試。在這段測試期間，我的工作有兩件事:$B$B(1) 將你標示為完成納克薩瑪斯協調任務，這樣你才能從指揮官艾利格·黎明使者那裡接下一個「戰爭的回響」任務。你必須先完成該任務才能進行第3階段甲套裝的任務。$B$B(2) 將你傳送至納克薩瑪斯。$B$B你想要哪一個?', `MaleText_loc7`='Saludos, $n. Soy Johnny MacSalsafloja. Los desarrolladores me han asignado unas funciones específicas de prueba. Durante este período de prueba, puedo realizar dos acciones específicas:$B$B(1) Marcarte de modo que quede indicado que has realizado la misión de armonización de Naxxramas y estás $glisto:lista; para aceptar la siguiente misión, "Ecos de Guerra", que el comandante Eligor Albar te asignará. Primero tendrás que completar esa misión para poder acceder a las misiones para conseguir tu armadura de Nivel 3.$B$B(2) Teletransportarte a Naxxramas.$B$B¿Qué deseas que haga por ti?' WHERE `ID`=13151;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 당황하여 고개를 젓습니다.', `MaleText_loc4`='%s沮丧地摇了摇头。', `MaleText_loc5`='%s沮喪地搖搖他的頭。', `MaleText_loc7`='%s agita la cabeza con consternación.' WHERE `ID`=13152;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선행 퀘스트를 완료 상태로 설정해주십시오.', `MaleText_loc4`='I require flagging.', `MaleText_loc5`='我需要被標示。', `MaleText_loc7`='Deseo que me marques.', `FemaleText_loc1`='선행 퀘스트를 완료 상태로 설정해주십시오.', `FemaleText_loc4`='I require flagging.', `FemaleText_loc5`='我需要被標示。', `FemaleText_loc7`='Deseo que me marques.' WHERE `ID`=13153;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='낙스라마스로 순간이동시켜 주십시오.', `MaleText_loc4`='我需要传送到纳克萨玛斯。', `MaleText_loc5`='我需要被傳送至納克薩瑪斯。', `MaleText_loc7`='Deseo que me teletransportes a Naxxramas.', `FemaleText_loc1`='낙스라마스로 순간이동시켜 주십시오.', `FemaleText_loc4`='我需要传送到纳克萨玛斯。', `FemaleText_loc5`='我需要被傳送至納克薩瑪斯。', `FemaleText_loc7`='Deseo que me teletransportes a Naxxramas.' WHERE `ID`=13154;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 한탄하며 한숨을 쉽니다.', `MaleText_loc4`='%s懊悔地叹了口气。', `MaleText_loc5`='%s後悔地嘆了口氣。', `MaleText_loc7`='%s suspira con arrepentimiento.' WHERE `ID`=13155;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요, $n. 이미 낙스라마스와의 조화 퀘스트를 완료하신 상태로 설정되어 있으십니다. 동부 역병지대 희망의 빛 예배당에 있는 사령관 엘리고르 돈브링어와 대화하셔서 ''전쟁의 메아리'' 퀘스트를 받으시기 바랍니다. 그 퀘스트를 먼저 완료하셔야만 새로운 방어구 세트 퀘스트를 받으실 수 있습니다.$B$B원하신다면 제가 당신을 낙스라마스로 순간이동시켜드릴 수도 있고 아니면 여기서 서쪽 역병숲의 차원문을 통하여 직접 낙스라마스로 가실 수도 있습니다.', `MaleText_loc4`='Greetings, $n. I see that you are already flagged as having completed the quest to gain entry to Naxxramas. Be sure to speak with Commander Eligor Dawnbringer at Light''s Hope Chapel in the Eastern Plaguelands to acquire the quest, "Echoes of War." You', `MaleText_loc5`='你好，$n。我看到你已完成進入納克薩瑪斯的任務。記得到東瘟疫之地的聖光之願禮拜堂和指揮官艾利格·黎明使者談談，取得任務「戰爭的回響」。你必須先完成那個任務才能進行第3階段護甲套裝的任務。$B$B我可以將你直接傳送至納克薩瑪斯或者你可以使用病木林裡的傳送門，就在西邊。', `MaleText_loc7`='"Saludos, $n. Veo que ya llevas la marca de haber completado la misión para poder entrar en Naxxramas. Asegúrate de hablar con el comandante Eligor Albar en la Capilla de la Esperanza de la Luz en las Tierras de la Peste del Este para obtener la misión "Ecos de Guerra". Primero tendrás que completar esa misión para poder acceder a las misiones para conseguir tu armadura de Nivel 3.$B$BYo puedo teletransportarte directamente a Naxxramas o puedes utilizar el portal situado en el Bosque de la Peste, al oeste".' WHERE `ID`=13156;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바보 같은! 우리 아버지의 존재를 부정하려는 것이냐? 죽을 준비나 해라, 필멸의 존재들이여!', `MaleText_loc4`='蠢货！你们胆敢侮辱我父亲？受死吧，凡人们！', `MaleText_loc5`='蠢蛋!你想要殺了我父親?死亡等著你，凡人!', `MaleText_loc7`='¡Estúpidos! ¿Queréis repudiar la presencia de mi padre? ¡La muerte os espera, mortales!' WHERE `ID`=13157;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 일의 배후에 나이트 엘프가 있는 건 아닐까요? 그런 의심이 드는군요. 사실 우리가 이곳 서부 성소에 더 부하를 주었기 때문에 문제가 터지는 것은 시간문제지요.', `FemaleText_loc4`='是不是暗夜精灵破坏者在捣鬼？很难说。我们施加在西部圣殿的流量如此大，发生故障只是时间问题而已。', `FemaleText_loc5`='夜精靈破壞者有可能與這無關嗎?我很懷疑。因為我們在西部聖所增加的負載，出事只是早晚的事而已。', `FemaleText_loc7`='¿Podría haber elfos de la noche saboteadores tras esto? Lo dudo. Con la carga que hemos estado poniendo en el Sagrario del Oeste solo era cuestión de tiempo que algo fuera mal.' WHERE `ID`=13158;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래 조그만 땅덩이를 되찾았구나. 그 정도로는 어림없지. 난 아직 건재하다!', `MaleText_loc4`='你们攻下了这片土地。这对我们只是个微小的挫折！我们终将成为这里的统治者！', `MaleText_loc5`='所以你征服了大地的一小塊區域。受了點小挫折!我會統治這裡的!', `MaleText_loc7`='Así que habéis conquistado una pequeña extensión de tierra. ¡Es un revés sin importancia! ¡Yo reinaré aquí de todos modos!' WHERE `ID`=13159;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필멸의 존재들이여, 할 수 있을 때 너희의 그 자그마한 승리를 즐겨라. 아제로스 대륙을 넘어선 내 마지막 승리의 함성은 그치지 않을 것이다!', `MaleText_loc4`='欢庆你们渺小的胜利吧，凡人。这根本无法阻挡我们在这片土地上的最终胜利！', `MaleText_loc5`='歡慶你們渺小的勝利吧，凡人。你是無法阻止我獲得這塊土地最終勝利的!', `MaleText_loc7`='Disfruten de su pequeña victoria mientras puedan, mortales. ¡Esto no evitará mi triunfo final sobre esta tierra!' WHERE `ID`=13160;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에 너희를 위한 승리란 없다! 너희가 되찾은 땅은 머지않아 나의 군대가 접수할 것이다!', `MaleText_loc4`='胜利不属于你们！这些你们暂时占有的土地终将完全被我们的军队所吞噬。', `MaleText_loc5`='你無法在這裡獲勝的!就算你佔領了一些土地，最後終將由我的大軍所吞沒!', `MaleText_loc7`='¡Nunca alcanzaréis la victoria! ¡Cualquier terreno que conquistéis os será arrebatado por mi ejército a su debido tiempo!' WHERE `ID`=13161;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 이 땅엔 스컬지의 그림자가 드리워져 있다. 멍청한 녀석들! 너희는 절대 이 그림자에서 벗어나지 못한다!', `MaleText_loc4`='天灾军团的阴影仍然笼罩着这片大地，蠢货！你们永远无法获得胜利！', `MaleText_loc5`='天譴軍團的陰影已經籠罩了這片大地，蠢蛋!你是無法戰勝的!', `MaleText_loc7`='¡La sombra de la Plaga todavía permanece sobre estas tierras, idiotas! ¡Jamás conseguirán reinar!' WHERE `ID`=13162;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래. 살아 있는 네놈들의 허약한 육체에도 무는 재주는 있단 말이지. 당분간 여기서 물러나마. 우리는 돌아올 것이다. 지금보다 훨씬 강해져서. 내가 돌아가면 너희의 보잘것없는 병력은 전멸을 면치 못할 것이다!', `MaleText_loc4`='看来这群貌似脆弱的活人还真有几颗锋利的牙齿。这地方就暂时归你们吧。我们会回来的，会比现在更强大，到时候你们这些弱者就不会再有机会了！', `MaleText_loc5`='看似虛弱的活人終究還剩下幾個顆鋒利的牙齒。暫時拿去這個地方，我們會以更強大的力量再次返回，而你那沒用的軍力將會覆滅!', `MaleText_loc7`='Parece que los vivos tienen agallas después de todo. Tomen este lugar, por el momento. ¡Volveremos y, cuando lo hagamos, seremos el doble de fuertes y sus tropas caerán!' WHERE `ID`=13163;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디라고 감히 내 계획을 망치려 드느냐?! 준비할 시간을 주마. 내가 다시 돌아왔을 땐 죽음과 파괴만이 있으리라!', `MaleText_loc4`='你竟敢阻挠我们的工作？！都洗干净脖子等着吧……当我们回来的时候，死亡与毁灭将终结一切！', `MaleText_loc5`='你竟敢阻撓我們在這裡的工作?!趁這個時間快作好準備...當我再次回來時，死亡和毀滅將終結一切!', `MaleText_loc7`='¿Osas interrumpir mis trabajos en la zona? Al maestro no le gustará nada. Aprovechad este tiempo para prepararos... pues cuando regresemos ¡tan solo dejaré muerte y destrucción a mi paso!' WHERE `ID`=13164;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈들이 이겼다고 생각하겠지만 리치 왕의 힘에 대항하는 자들에겐 승리란 있을 수 없다! 지금까지 보여준 건 내 힘의 전부가 아니다!', `MaleText_loc4`='你们或许以为自己获得了胜利，但是面对巫妖王，你们的抗争是毫无意义的！你们还没有见识到我真正的力量！', `MaleText_loc5`='你以為你贏了，小蟲，違抗巫妖王的力量只有死路一條!你們還沒有見到我們最終的力量!', `MaleText_loc7`='Puede que penséis que habéis ganado, gusanos, ¡pero contra la fuerza del Rey Exánime, los vivos no pueden vencer! ¡Nos volveremos a ver!' WHERE `ID`=13165;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 희미하게 빛나더니 사라집니다!', `MaleText_loc4`='%s闪着光消失了！', `MaleText_loc5`='%s閃閃發光然後消失不見!', `MaleText_loc7`='¡%s brilla y desaparece!' WHERE `ID`=13166;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘으로만 이기는 싸움은 거의 없습니다. 기교가 필요하지요. 재빠른 반사 신경과 무기에 대한 지식이 있어야만 승리할 수 있습니다.', `MaleText_loc4`='很少有较量是可以靠着纯粹的力量取胜的。巧妙的使用和认识你的武器会让你常胜不败。', `MaleText_loc5`='靠著蠻力贏了幾場比賽。那很奸詐，最後靠著你在武器上的本能反應和知識獲得勝利。', `MaleText_loc7`='Pocos ataques se ganan por pura fuerza. Al final, lo que lleva a la victoria es la astucia, los reflejos y el conocimiento de tu arma.', `FemaleText_loc1`='힘으로만 이기는 싸움은 거의 없습니다. 기교가 필요하지요. 재빠른 반사 신경과 무기에 대한 지식이 있어야만 승리할 수 있습니다.', `FemaleText_loc4`='很少有较量是可以靠着纯粹的力量取胜的。巧妙的使用和认识你的武器会让你常胜不败。', `FemaleText_loc5`='靠著蠻力贏了幾場比賽。那很奸詐，最後靠著你在武器上的本能反應和知識獲得勝利。', `FemaleText_loc7`='Pocos ataques se ganan por pura fuerza. Al final, lo que lleva a la victoria es la astucia, los reflejos y el conocimiento de tu arma.' WHERE `ID`=13167;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라레니스, 당신의 지식을 나눠주십시오.', `MaleText_loc4`='让我看看你都能教我些什么，拉雷尼斯。', `MaleText_loc5`='讓我看看你知道了什麼，拉瑞尼斯。', `MaleText_loc7`='Muéstrame lo que sabes, Larenis.', `FemaleText_loc1`='라레니스, 당신의 지식을 나눠주세요.', `FemaleText_loc4`='让我看看你都能教我些什么，拉雷尼斯。', `FemaleText_loc5`='讓我看看你知道了什麼，拉瑞尼斯。', `FemaleText_loc7`='Muéstrame lo que sabes, Larenis.' WHERE `ID`=13168;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정 잘 싸우고 있다고 자신하는 거냐? 내 군대의 수는 끝이 없도다!', `MaleText_loc4`='你们该不会以为自己做得不错吧？哈哈！我们的数量是无穷无尽的！', `MaleText_loc5`='你該不會以為自己做得很好吧?哈!我們的人數可是無窮盡的!', `MaleText_loc7`='¿Realmente pensáis que lo estáis haciendo bien? ¡Ja, ja, ja! ¡Mi ejército es ilimitado!' WHERE `ID`=13169;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투에선 잠시나마 성공했을지 모르나... 내 스컬지군에 대항하여 승리할 수 있으리라곤 꿈도 꾸지 마라!', `MaleText_loc4`='或许你们现在可以一时得势……但你们永远无法击败天灾军团！', `MaleText_loc5`='或許你輕易地在這裡戰勝了...但是你休想戰勝我的天譴軍!', `MaleText_loc7`='Habréis ganado en el campo de batalla de momento... ¡pero nunca conseguiréis derrotar a mi Plaga!' WHERE `ID`=13170;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자아, 귀여운 것. 입을 크게 벌리거라, 지르시.', `FemaleText_loc4`='把嘴张大点，基尔西。', `FemaleText_loc5`='張開嘴，澤西。', `FemaleText_loc7`='Abre completamente, Jir''ve.' WHERE `ID`=13171;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보잘것없는 진지 몇 개를 사수했구나. 애처롭도다. 그곳은 다시 내 것이 되리라!', `MaleText_loc4`='你们收复了一些微不足道的失地。可怜虫。很快我们就会再度攻占它们。', `MaleText_loc5`='你已經收復了一些微不足道的領土。真是可悲。很快地，那些都將再度屬於我的!', `MaleText_loc7`='Habéis recuperado algunos míseros territorios. Patético... ¡Pronto volverán a ser míos!' WHERE `ID`=13172;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진전하고 있다고 생각하느냐? 스컬지를 꺾을 수는 없다!', `MaleText_loc4`='你真的认为事情在朝你所推动的方向进展吗？你永远不可能击败天灾军团！', `MaleText_loc5`='你真的覺得你們戰線有所進展?你無法戰勝我的天譴軍的!', `MaleText_loc7`='¿Realmente pensáis que estáis haciendo progresos? ¡Jamás derrotaréis a mi Plaga!' WHERE `ID`=13173;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 주인님께서 조금이라도 당황하실 거라 생각했나? 우린 절대 패배하지 않는다!', `MaleText_loc4`='你以为主人会因为你的小小胜利而沮丧吗？我们永远不会在你面前倒下！', `MaleText_loc5`='你以為主人不敢接受挑戰?我們不會輸給你的!', `MaleText_loc7`='¿Creen que el maestro se amilana en vista de sus juegos? ¡Nunca caeremos ante ustedes!' WHERE `ID`=13174;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청한 녀석들! 그게 네놈들이 원하는 것이라면 계속 싸워라! 전투가 계속될수록 쓰러지는 것은 네놈들이요. 늘어나는 것은 내 언데드 군대이다!', `MaleText_loc4`='蠢货！继续战斗吧，如果那是你们最终的愿望！每一战中，你们当中都会有更多的人倒下，而我们的军团却日益庞大！', `MaleText_loc5`='你這個蠢蛋!如果那是你所希望的，就繼續進攻吧!每場戰鬥，你們死的人越多，不死的力量就更強大一些!', `MaleText_loc7`='¡Idiotas! ¡Sigan luchando, si eso es lo que quieren! ¡Con cada batalla mueren más de ustedes y las filas de mis no-muertos no hacen más que crecer!' WHERE `ID`=13175;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끊임없이 헛고생만 하는구나. 너희 병력엔 한계가 있다. 전투가 계속될수록 줄어들기만 할 뿐이지. 네놈들은 끝까지 살아남지 못한다!', `MaleText_loc4`='活人的努力总是让人惊讶。但你们的数量太有限了，而且这数量还时刻在减少。你们无法活着看到结局的！', `MaleText_loc5`='活人的努力總是令人驚訝。你的數量有限，每戰鬥一次數量就更少一些。你們無法活著看到結局的!', `MaleText_loc7`='Los esfuerzos de los vivos no dejan de asombrarnos. Tenéis un número limitado de combatientes y con cada batalla que pasa se reduce considerablemente. ¡No viviréis para ver el final!' WHERE `ID`=13176;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 감히 진정 리치 왕의 군대를 상대로 이길 수 있으리라 생각했느냐? 네놈들의 군대로는 내 군대를 파괴할 수 없다!', `MaleText_loc4`='你们真的认为自己可以与巫妖王的军团相抗衡吗？没有任何生者的军队，没有任何你可以聚集起的力量能与亡者为敌！', `MaleText_loc5`='你真的相信你有能力可以對抗巫妖王的大軍?只要是活人的軍隊，只要是你們所能獲得的力量，就不要想擊潰我的軍隊!', `MaleText_loc7`='¿Realmente pensáis que estáis que podréis vencer contra los ejércitos del Rey Exánime? ¡Ningún ejército de vivos ni ninguna otra fuerza que podáis utilizar será capaz de acabar con nosotros!' WHERE `ID`=13177;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 지겨운 저항을 지속해봐야 소용없다, 어리석은 것들! 끝내는 너희의 죽음 이외엔 아무것도 없을 것이다!', `MaleText_loc4`='这持续不断、惹人厌烦的抵抗都是徒劳的，你们这群蠢货！一切都将湮灭于虚空，惟有死亡长存！', `MaleText_loc5`='這不斷、令人厭煩的抵抗是沒有用的，你休想!除了死你別無選擇!', `MaleText_loc7`='¡Es inútil que opongáis resistencia, gusanos! ¡Encontraréis la muerte de igual modo!' WHERE `ID`=13178;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그래, 그래야 내 귀염둥이 지르시지! 우리가 널 다른 황천의 사냥개처럼 만들어 주마!', `FemaleText_loc4`='那是我的基尔西！我们会把你变成那些虚空犬中的一员！', `FemaleText_loc5`='那是我的小澤西!不過我們會把你變成虛空捕獵者!', `FemaleText_loc7`='¡Ese es mi pequeño Jir''ve! ¡Te convertiremos en uno de esos canes infernales!' WHERE `ID`=13179;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘이... 힘이... 돌아오고 있습니다!', `MaleText_loc4`='我的……力量……正在恢复！', `MaleText_loc5`='我的力量...正...恢復!', `MaleText_loc7`='¡Estoy... recuperando... las fuerzas!' WHERE `ID`=13180;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 치료법을 발견했군요! 이제 우린 적을 박살 낼 수 있는 힘을 다시 찾았습니다!', `MaleText_loc4`='你治愈了我！让我们的敌人尝尝失败的滋味吧！', `MaleText_loc5`='你找到了解藥!我們會粉碎我們的敵人!', `MaleText_loc7`='¡Has encontrado una cura! ¡Destruiremos a nuestros enemigos!' WHERE `ID`=13181;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='덕분에 건강을 회복했습니다! 당신에게 빚을 졌군요.', `MaleText_loc4`='你帮我恢复了健康！我欠你个人情，$n。', `MaleText_loc5`='你讓我的生命恢復了!我欠你一個人情，$n。', `MaleText_loc7`='¡Me has devuelto la salud! Estoy en deuda contigo, $n.' WHERE `ID`=13182;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 이해할 수 없는 내용을 중얼거립니다.', `MaleText_loc4`='%s轻声嘟囔着一些莫名奇妙的东西。', `MaleText_loc5`='%s說了一些難以理解的悄悄話。', `MaleText_loc7`='%s murmura algo ininteligible.', `FemaleText_loc1`='%s|1이;가; 이해할 수 없는 내용을 중얼거립니다.', `FemaleText_loc4`='%s轻声嘟囔着一些莫名奇妙的东西。', `FemaleText_loc5`='%s說了一些難以理解的悄悄話。', `FemaleText_loc7`='%s murmura algo ininteligible.' WHERE `ID`=13183;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 진정하십시오! 우리는 이 상황을 통제하고자 온 힘을 다하고 있습니다. 저 피눈물 오크 녀석들은 무자비한 자들입니다!', `MaleText_loc4`='大家安静一些！我们正在尽全力控制局势。那些该死的兽人是不可饶恕的！', `MaleText_loc5`='所有人安頓下來!我們已經盡全部的力量控制情況。那些該死的獸人是無情的!', `MaleText_loc7`='¡Que todo el mundo se calme! Estamos haciendo todo lo posible para controlar la situación. ¡Esos puñeteros orcos son implacables!' WHERE `ID`=13184;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성스러운 빛이 함께하시길...', `MaleText_loc4`='圣光与你同在。', `MaleText_loc5`='願聖光與你同行。', `MaleText_loc7`='Ve con la Luz.' WHERE `ID`=13185;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 흐느낍니다.', `MaleText_loc4`='%s抽泣着。', `MaleText_loc5`='%s啜泣著。', `MaleText_loc7`='%s solloza.', `FemaleText_loc1`='%s|1이;가; 흐느낍니다.', `FemaleText_loc4`='%s呜咽着。', `FemaleText_loc5`='%s啜泣著。', `FemaleText_loc7`='%s solloza.' WHERE `ID`=13186;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 화가 나서 주먹을 꽉 쥡니다.', `MaleText_loc4`='%s生气地握紧了$g他的:她的;拳头。', `MaleText_loc5`='%s憤怒地緊握$g他的:她的; 拳頭。', `MaleText_loc7`='%s aprieta los puños con rabia.', `FemaleText_loc1`='%s|1이;가; 화가 나서 주먹을 꽉 쥡니다.', `FemaleText_loc4`='%s生气地握紧了$g他的:她的;拳头。', `FemaleText_loc5`='%s憤怒地緊握$g他的:她的; 拳頭。', `FemaleText_loc7`='%s aprieta los puños con rabia.' WHERE `ID`=13187;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 집을 이렇게 그냥 내버려 둘 수 없습니다! 공격이 끊이질 않는단 말입니다!', `MaleText_loc4`='我们甚至没法离开我们的屋子！进攻似乎永远都不会停止！', `MaleText_loc5`='我甚至連我們的房子都不能離開半步!攻擊永無止境!', `MaleText_loc7`='¡Ya ni siquiera podemos salir de nuestras casas! ¡Los ataques son interminables!', `FemaleText_loc1`='우리 집을 이렇게 그냥 내버려 둘 수 없습니다! 공격이 끊이질 않는단 말입니다!', `FemaleText_loc4`='我们甚至没法离开我们的屋子！进攻似乎永远都不会停止！', `FemaleText_loc5`='我甚至連我們的房子都不能離開半步!攻擊永無止境!', `FemaleText_loc7`='¡Ya ni siquiera podemos salir de nuestras casas! ¡Los ataques son interminables!' WHERE `ID`=13188;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언덕에 있는 무덤이 들어차는 속도가 점점 더 빨라져서 우리가 무덤 파는 속도로는 따라잡기 어렵습니다.', `MaleText_loc4`='这几天山上的坟墓装满的速度比我们挖洞的速度还快。', `MaleText_loc5`='山丘上的墓地比我們挖洞的速度還快被填滿。', `MaleText_loc7`='El cementerio de la colina se llena algunos días con mayor rapidez con la que podemos cavar los hoyos.', `FemaleText_loc1`='언덕에 있는 무덤이 들어차는 속도가 점점 더 빨라져서 우리가 무덤 파는 속도로는 따라잡기 어렵습니다.', `FemaleText_loc4`='这几天山上的坟墓装满的速度比我们挖洞的速度还快。', `FemaleText_loc5`='山丘上的墓地比我們挖洞的速度還快被填滿。', `FemaleText_loc7`='El cementerio de la colina se llena algunos días con mayor rapidez con la que podemos cavar los hoyos.' WHERE `ID`=13189;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 정말 고향으로 돌아갈 수 있을까요?', `MaleText_loc4`='我们究竟还能不能回家？', `MaleText_loc5`='我們有可能回的了家嗎?', `MaleText_loc7`='¿Podremos regresar a casa alguna vez?', `FemaleText_loc1`='우리가 정말 고향으로 돌아갈 수 있을까요?', `FemaleText_loc4`='我们究竟还能不能回家？', `FemaleText_loc5`='我們有可能回的了家嗎?', `FemaleText_loc7`='¿Podremos regresar a casa alguna vez?' WHERE `ID`=13190;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 제 아들, 탈보스를 묻었습니다... 그리고 지난주에는 제 반려자를 묻었고요.', `MaleText_loc4`='我今天埋葬了我的儿子，塔沃斯……上周我埋葬了我的老伴。', `MaleText_loc5`='薩沃斯，我今天埋葬了我的兒子...上禮拜埋葬了我的配偶。', `MaleText_loc7`='Hoy he enterrado a mi hijo Thalvos... Y la semana pasada a mi esposa.', `FemaleText_loc1`='오늘 제 아들, 탈보스를 묻었습니다... 그리고 지난주에는 제 반려자를 묻었고요.', `FemaleText_loc4`='我今天埋葬了我的儿子，塔沃斯……上周我埋葬了我的老伴。', `FemaleText_loc5`='薩沃斯，我今天埋葬了我的兒子...上禮拜埋葬了我的配偶。', `FemaleText_loc7`='Hoy he enterrado a mi hijo Thalvos... Y la semana pasada a mi esposa.' WHERE `ID`=13191;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또다시 공격이 있을 거라던데... 그럼 아무도 살아남지 못합니다...', `MaleText_loc4`='他们说还会有进攻的……没有人能活下来……', `MaleText_loc5`='他們說會有另一波攻擊...沒有人會生還...', `MaleText_loc7`='Dicen que va a haber otro ataque... Nadie va a sobrevivir...', `FemaleText_loc1`='또다시 공격이 있을 거라던데... 그럼 아무도 살아남지 못합니다...', `FemaleText_loc4`='他们说还会有进攻的……没有人能活下来……', `FemaleText_loc5`='他們說會有另一波攻擊...沒有人會生還...', `FemaleText_loc7`='Dicen que va a haber otro ataque... Nadie va a sobrevivir...' WHERE `ID`=13192;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넬쥴은 결코 포기하지 않을 겁니다. 도대체 우리의 영웅은 어디에 있지요?', `MaleText_loc4`='耐奥祖永远都不会放弃。我们的英雄在哪里？', `MaleText_loc5`='耐祖奧絕不會放棄的。我們的英雄在哪?', `MaleText_loc7`='Nerzhul no se rendirá jamás. ¿Dónde están nuestros héroes?', `FemaleText_loc1`='넬쥴은 결코 포기하지 않을 겁니다. 도대체 우리의 영웅은 어디에 있지요?', `FemaleText_loc4`='耐奥祖永远都不会放弃。我们的英雄在哪里？', `FemaleText_loc5`='耐祖奧絕不會放棄的。我們的英雄在哪?', `FemaleText_loc7`='Nerzhul no se rendirá jamás. ¿Dónde están nuestros héroes?' WHERE `ID`=13193;
