UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 그대가 큰 공을 세웠다는 얘기를 들었습니다. 여기 포세이큰의 땅에서 지내는 동안은 신도레이의 영웅답게 품위 있게 행동하시리라 믿습니다!', `MaleText_loc4`='我听说了一些关于你的探险故事，$n。我知道，当你踏上遗忘者的土地时，你会举止庄重优雅，并且把自己当作一个真正的辛多雷英雄！', `MaleText_loc5`='我聽說過你的一些功績，$n。我知道當你在這被遺忘者的土地時你會帶著尊嚴行動，像個辛多雷真正的英雄。', `MaleText_loc7`='He oído hablar de tus hazañas, $n. Sé que, mientras estés en tierras de los Renegados te comportarás con dignidad y como un auténtico héroe de los sin''dorei.' WHERE `ID`=13228;
