UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러니까 그 남자가 "난 닭한테 말을 하고 있었다니까!"라고 하지 뭐예요.', `MaleText_loc4`='然后他说，“我是在跟小鸡讲话！”', `MaleText_loc5`='然後他說「我在和小雞說話!」', `MaleText_loc7`='Y entonces dice "¡Estaba hablando con el pollo!"', `FemaleText_loc1`='그러니까 그 남자가 "난 닭한테 말을 하고 있었다니까!"라고 하지 뭐예요.', `FemaleText_loc4`='然后他说，“我是在跟小鸡讲话！”', `FemaleText_loc5`='然後他說「我在和小雞說話!」', `FemaleText_loc7`='Y entonces dice "¡Estaba hablando con el pollo!"' WHERE `ID`=13235;
