UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 어떻게 해서 여기에 오게 됐는지 기억나는 분이 또 있습니까? 저뿐입니까?', `MaleText_loc4`='还有谁记得我们是怎么到这里的？难道说只有我……？', `MaleText_loc5`='有沒有任何人記得我們是怎麼到達那裡的?還是我...?', `MaleText_loc7`='¿Hay alguien más que recuerde cómo hemos venido a parar aquí? ¿Soy solo yo...?', `FemaleText_loc1`='우리가 어떻게 해서 여기에 오게 됐는지 기억나는 분이 또 있나요? 저뿐인가요?', `FemaleText_loc4`='还有谁记得我们是怎么到这里的？难道说只有我……？', `FemaleText_loc5`='有沒有任何人記得我們是怎麼到達那裡的?還是我...?', `FemaleText_loc7`='¿Hay alguien más que recuerde cómo hemos venido a parar aquí? ¿Soy solo yo...?' WHERE `ID`=13237;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 그전에는 어디에 살았더라? 분명 알았는데... 아니, 알고 있다고 생각했나...', `MaleText_loc4`='我以前住在哪里？我好像知道，至少我觉得我知道……', `MaleText_loc5`='在這之前我住在那?過去我知道的。至少我認為我做了...', `MaleText_loc7`='¿Dónde vivía yo antes? Antes lo sabía. Por lo menos, eso creo...', `FemaleText_loc1`='내가 그전에는 어디에 살았더라? 분명 알았는데... 아니, 알고 있다고 생각했나...', `FemaleText_loc4`='我以前住在哪里？我好像知道，至少我觉得我知道……', `FemaleText_loc5`='在這之前我住在那?過去我知道的。至少我認為我做了...', `FemaleText_loc7`='¿Dónde vivía yo antes? Antes lo sabía. Por lo menos, eso creo...' WHERE `ID`=13238;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 인생은 즐거워.', `MaleText_loc4`='啊,生活真美好。', `MaleText_loc5`='啊，活著真好。', `MaleText_loc7`='Ah, la vida es dulce.', `FemaleText_loc1`='아, 인생은 즐거워.', `FemaleText_loc4`='啊，生活真美好。', `FemaleText_loc5`='啊，活著真好。', `FemaleText_loc7`='Ah, la vida es dulce.' WHERE `ID`=13239;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 즐거운 건 처음입니다! 이 밤이 끝나지 않았으면 좋겠군요!', `MaleText_loc4`='我从来没有这么快乐过！我希望这个夜晚永远不要结束！', `MaleText_loc5`='我從來沒有這麼開心過!真希望今晚不要結束!', `MaleText_loc7`='¡Nunca he sido tan feliz! ¡Ojalá esta noche no se acabara jamás!', `FemaleText_loc1`='이렇게 즐거운 건 처음이에요! 이 밤이 끝나지 않았으면 좋겠어요!', `FemaleText_loc4`='我从来没有这么快乐过！我希望这个夜晚永远不要结束！', `FemaleText_loc5`='我從來沒有這麼開心過!真希望今晚不要結束!', `FemaleText_loc7`='¡Nunca he sido tan feliz! ¡Ojalá esta noche no se acabara jamás!' WHERE `ID`=13240;
