UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당장 확인해 봐야겠네요.', `MaleText_loc4`='我马上就去看看。', `MaleText_loc5`='我會立刻檢查。', `MaleText_loc7`='Lo comprobaré enseguida.' WHERE `ID`=13246;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전쟁터에서 아이들을 죽이는 자들을 봤습니다. 피의 욕망에 휩싸인 놈들이었지요. 도저히 용서할 수 없는 일이지요. 저는 왜 그런 일이 일어났는지 압니다. 그리고 그 나약한 아이들이 적어도 종교의식의 제물로 바쳐진 것은 아닙니다.', `FemaleText_loc4`='我看到有人在战争中杀害孩子们。我不能容忍这种没有人性的屠杀——但我想看看到底是怎么一回事，不过我确信他们不会用这个毫无反抗能力的俘虏来作献祭典礼的。', `FemaleText_loc5`='我看到有些人在戰役中殺害小孩。他們的嗜血 - 我不能寬恕，但我可以了解它為何會發生，不過他們當然不會為這沒有能力保護自己的俘虜舉辦儀式獻祭。', `FemaleText_loc7`='Vi a algunos matando niños. Tenían el ansia de sangre en ellos – no podría justificarlo, pero veo cómo podría haber pasado, aunque seguramente no pretenderán que este cautivo indefenso era un sacrificio ritual.' WHERE `ID`=13247;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 말이 맞길 바란다.', `MaleText_loc4`='我希望你是对的。', `MaleText_loc5`='我希望你是對的。', `MaleText_loc7`='Espero que tengas razón.' WHERE `ID`=13248;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘은 호드에게 영광스러운 날이다!', `MaleText_loc4`='今天是部落的荣耀之日！', `MaleText_loc5`='今天是部落光榮的一天!', `MaleText_loc7`='¡Hoy es un día glorioso para la Horda!' WHERE `ID`=13249;
