UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 누굽니까?', `MaleText_loc4`='谁啊？', `MaleText_loc5`='誰在那裡?', `MaleText_loc7`='¿Quién anda ahí?' WHERE `ID`=13251;
