UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비밀 암호를 입력하고 제 저글링 소환수를 받고 싶습니다.', `MaleText_loc4`='我想要输入神秘兑换码，换取我的跳虫！', `MaleText_loc5`='我想要輸入驗證碼以領取我的異化蟲寵物。', `MaleText_loc7`='Me gustaría introducir el código secreto para obtener mi Zerguezno.', `FemaleText_loc1`='비밀 암호를 입력하고 제 저글링 소환수를 받고 싶어요.', `FemaleText_loc4`='我想要输入神秘兑换码，换取我的跳虫！', `FemaleText_loc5`='我想要輸入驗證碼以領取我的異化蟲寵物。', `FemaleText_loc7`='Me gustaría introducir el código secreto para obtener mi Zerguezno.' WHERE `ID`=13253;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어이! 자네 낯이 익은데... 우리 전에 만난 적이 있지 않나?$B$B우리가 만난 적이 있다면... 자네는 분명 비밀 암호를 받았을 걸세. 그 암호를 내게 알려주면 선물을 주겠어!', `MaleText_loc4`='你好！你看起来很眼熟啊，我们以前见过么？$B$B如果我们曾见过的话，那你一定有那段神秘的数字！把你的神秘兑换码告诉我，我就给你一件礼物！', `MaleText_loc5`='嗨，$c。你好眼熟...我們以前有見過面嗎?$B$B如果我們見過面，那麼...你一定有一組驗證碼吧。告訴我你的驗證碼，我就會給你一份禮物!', `MaleText_loc7`='¡Hola! Me suena tu cara... ¿nos hemos visto antes?$B$BSi es así, seguro que alguien te ha dado un código secreto. ¡Dime tu código y te daré un regalo!', `FemaleText_loc1`='어이! 자네 낯이 익은데... 우리 전에 만난 적이 있지 않나?$B$B우리가 만난 적이 있다면... 자네는 분명 비밀 암호를 받았을 걸세. 그 암호를 내게 알려주면 선물을 주겠어!', `FemaleText_loc4`='你好！你看起来很眼熟啊，我们以前见过么？$B$B如果我们曾见过的话，那你一定有那段神秘的数字！把你的神秘兑换码告诉我，我就给你一件礼物！', `FemaleText_loc5`='嗨，$c。你好眼熟...我們以前有見過面嗎?$B$B如果我們見過面，那麼...你一定有一組驗證碼吧。告訴我你的驗證碼，我就會給你一份禮物!', `FemaleText_loc7`='¡Hola! Me suena tu cara... ¿nos hemos visto antes?$B$BSi es así, seguro que alguien te ha dado un código secreto. ¡Dime tu código y te daré un regalo!' WHERE `ID`=13254;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저기 저쪽을 보세요! 저들이 우릴 따라오고 있어요!', `FemaleText_loc4`='看！他们在跟踪我们！', `FemaleText_loc5`='在那裡!它們跟著我們!', `FemaleText_loc7`='¡Ahí! ¡Nos están siguiendo!' WHERE `ID`=13255;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 모두는 이 어둠의 문이 세워지는 과정을 보았고 장인의 솜씨와 호드의 영광을 상징하는 기념물로써 이 문이 존재하게 된 이유에 감탄해 마지 않았다.', `MaleText_loc4`='你们都目睹了这座黑暗之门建造的全过程，也都见证了那精湛的建造技术，这是一座纪念部落荣耀的丰碑。', `MaleText_loc5`='你們都看到這個傳送門的建造過程，欽佩它的工藝 ，和它如何成為部落榮耀的紀念碑。', `MaleText_loc7`='Todos habéis visto cómo se construía este portal, admirado la artesanía y cómo se erige como monumento a la gloria de la Horda.' WHERE `ID`=13256;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 내가 본 것을 그대들에게 공개하려고 한다.', `MaleText_loc4`='现在，我会给你们展现我所看到的未来。', `MaleText_loc5`='現在，我會讓你看看我所看見的景象。', `MaleText_loc7`='Ahora te revelaré las visiones que he tenido.' WHERE `ID`=13257;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 어둠의 문이라고 알려진 구조물을 가리킵니다.', `MaleText_loc4`='%s指着被称为黑暗之门的宏伟建筑。', `MaleText_loc5`='%s指向那個叫做黑暗之門的巨石結構。', `MaleText_loc7`='%s señala la estructura monolítica conocida como el Portal Oscuro.' WHERE `ID`=13258;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 먼 곳에 있는 아제로스에는 내 동맹이 있다. 그가 내게 자신의 땅을 바쳤도다. 푸르고 비옥한 그 땅에는 깨끗한 물이 풍부하고 통통하게 살찐 사냥감이 가득하노라.', `MaleText_loc4`='在很远很远的地方，在一个被称为艾泽拉斯的地方，我有一个同伴，他把自己的土地贡献给我们。那是一个绿色的、富饶的、充满着清澈的水和肥美的猎物的地方。', `MaleText_loc5`='很遠，很遠的地方，在一個叫做艾澤拉斯的土地上，我有一個盟友。他提供我們他的土地。那是個翠綠富饒，充滿純淨水源和肥壯生物可獵捕的地方。', `MaleText_loc7`='Muy, muy lejos, en una tierra llamada Azeroth, tengo un aliado. Nos ofrece su tierra. Es verde y exuberante, llena de agua pura y de criaturas rechonchas que cazar.' WHERE `ID`=13259;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무엇보다 기쁜 것은 우리가 살육의 기쁨을 계속 이어갈 수 있다는 점이다. 우리 동맹의 적이자 ''인간''이라는 종족이 자신들의 땅을 빼앗기지 않으려고 우리를 막을 것이니라.', `MaleText_loc4`='最令我兴奋的是，我们将继续谱写鲜血的荣光。一个被称为“人类”的种族，也就是我们那位伙伴的敌人，将会阻止我们夺取他们的土地。', `MaleText_loc5`='最好的是，我們會繼續讚揚流血的光榮。我們盟友的敵人，一個叫做「人類」的種族，會試著阻止我們搶走他們的土地。', `MaleText_loc7`='Lo mejor es que seguiremos exaltándonos en la gloria del derramamiento de sangre. Una raza llamado "los humanos", el enemigo de nuestro aliado, intentará evitar que tomemos sus tierras.' WHERE `ID`=13260;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 든 검에 인간들의 붉은 피가 흘러내리고 인간들은 파멸의 길을 걸어야 한다. 우리가 드레나이를 파멸로 인도했듯이 이제 인간을 파멸로 인도하리라!', `MaleText_loc4`='我们将消灭他们。他们的鲜血将在我们的剑刃上流淌。就像我们消灭了德莱尼人那样，现在我们将消灭人类！', `MaleText_loc5`='我們會摧毀他們。他們血紅的血意志恣意地淹沒我們的劍。就像我們摧毀德萊尼一樣，我們現在也要摧毀人類!', `MaleText_loc7`='Los destruiremos. Su sangre – sangre roja fluirá con libertad sobre nuestras espadas. ¡Como hemos destruido a los Draenei, destruiremos a los humanos ahora!' WHERE `ID`=13261;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 조용히 하라는 몸짓을 합니다.', `MaleText_loc4`='%s用手势让大家静下来。', `MaleText_loc5`='%s以手勢示意安靜。', `MaleText_loc7`='%s pide silencio con un ademán.' WHERE `ID`=13262;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 믿을 수 없다는 듯한 표정으로 고개를 젓습니다.', `FemaleText_loc4`='%s怀疑地摇了摇她的头。', `FemaleText_loc5`='%s不相信地搖搖她的頭。', `FemaleText_loc7`='%s niega con la cabeza con incredulidad.' WHERE `ID`=13263;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어떻게 아직도 그런 생각을 하는 겁니까? 그런 방식을 고수한다면 이 새로운 땅도 우리의 땅과 마찬가지로 고통을 겪을 것을 모르나요?', `FemaleText_loc4`='他们怎么仍然这样想？他们难道看不到，如果我们继续这样下去，这块新的土地将会遭受和我们的土地一样的痛苦？', `FemaleText_loc5`='他們怎麼還能這樣想?難道他們看不出來如果我們繼續走這條路，這塊新土地就會像我們的一樣受折磨嗎?', `FemaleText_loc7`='¿Cómo pueden seguir pensando así? ¿No ven que estas nuevas tierras sufrirán como las nuestras si seguimos por este camino?' WHERE `ID`=13264;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 동의하며 고개를 끄덕입니다.', `MaleText_loc4`='%s点了点头，表示同意。', `MaleText_loc5`='%s點點頭表示同意。', `MaleText_loc7`='%s asiente mostrando su acuerdo.' WHERE `ID`=13265;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래도 선택의 여지가 없군요. 음식과 물이 필요한 지금 우리는 이 문으로 들어가야 합니다.', `MaleText_loc4`='但是，我们没有选择。我们需要食物和水。我们必须穿越这黑暗之门。', `MaleText_loc5`='但同時我們也別無選擇。我們需要食物和水。我們一定要通過這個傳送門。', `MaleText_loc7`='Pero al mismo tiempo no tenemos elección. Necesitamos alimentos y agua. Debemos cruzar este portal.' WHERE `ID`=13266;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형제들이여, 지금 이 순간에도 우리의 동맹은 차원문 반대편을 열려고 힘쓰고 있다. 이제는 우리가 시작할 차례이니라.', `MaleText_loc4`='现在，我们的同盟正在他的世界中为了打开黑暗之门而努力。那么，我们开始吧。', `MaleText_loc5`='就連現在，我們的盟友正在他那邊努力打開傳送門。而現在，我們就要開始。', `MaleText_loc7`='Incluso ahora, nuestro aliado está trabajando para abrir el portal de su lado. Y, ahora, comenzaremos.' WHERE `ID`=13267;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 사로잡힌 드레나이에게 몸짓을 합니다.', `MaleText_loc4`='%s对着德莱尼人俘虏做了个手势。', `MaleText_loc5`='%s對德萊尼俘虜用手勢示意。', `MaleText_loc7`='%s indica con un ademán el draenei cautivo.' WHERE `ID`=13268;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피는 우리에게 이 강대한 힘을 주신 그분들에게 바치는 순수한 제물이니라. 그리고 순결한 자의 피는 더욱 순수하니 적의 피를 이용해 우리는 차원문을 열고 영광의 땅으로 들어가리라. 호드 역사의 새로운 장이 열릴지니!', `MaleText_loc4`='血是献给那些赐与我们巨大力量的神明的最完美的祭品。无辜者的血是最完美的。随着我们敌人的生命之血流淌出来，我们将打开传送门，步入一个光荣的新世界，步入部落历史上崭新的一页！', `MaleText_loc5`='鮮血對給予我們這些廣大能量的人來說是個純淨的禮物。而無辜者的鮮血更是潔淨。有了敵人的生命之液，我們將會敞開大門踏入一個光榮的新世界 - 部落歷史中新的一頁!', `MaleText_loc7`='La sangre es una ofrenda pura a aquellos que nos proporcionan estos inmensos poderes. Y la sangre de un inocente es aún más pura. Con el fluido de la vida de nuestros enemigos, abriremos el portal y entraremos en un nuevo mundo espléndido – ¡una nueva página en la historia de la Horda!' WHERE `ID`=13269;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼!!!', `MaleText_loc4`='不！！！', `MaleText_loc5`='不!!!', `MaleText_loc7`='¡¡¡NO!!!' WHERE `ID`=13270;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='굴단, 우리에게 무슨 짓을 한 것인가!', `MaleText_loc4`='古尔丹，你对我们干了些什么！', `MaleText_loc5`='古爾丹，你對我們做了什麼!', `MaleText_loc7`='Gul''dan, ¿qué nos has hecho?' WHERE `ID`=13271;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 정찰병들이다! 그들은 이미 어둠의 문으로 들어갔도다. 아마 새로운 세계에 대한 소식을 가지고 돌아올 것이다.', `MaleText_loc4`='这些是我们的斥候！他们已经穿过了黑暗之门。现在，他们带回了来自新世界的消息。', `MaleText_loc5`='這些是我們的斥候!他們早已通過黑暗之門。他們帶著新世界的消息回到你那裡。', `MaleText_loc7`='¡Estos son nuestros exploradores! Ya han atravesado el Portal Oscuro. Vuelven a ti con noticias del nuevo mundo.' WHERE `ID`=13272;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사실입니다! 모두 굴단께서 약속한 그대로입니다!', `MaleText_loc4`='是真的！都是真的！就像您承诺给我们的那样！', `MaleText_loc5`='這是真的!和你允諾我們的全都一樣!', `MaleText_loc7`='¡Es cierto! ¡Todo es como nos prometiste que sería!' WHERE `ID`=13273;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='운명의 시간이 도래했으며 새로운 시작이 우리를 기다리고 있도다! 새로운 적이 나타났음을 그대들도 느낄 수 있을 것이다. 피의 욕망이 솟구치고 있는가? 블랙핸드를 따르라! 그의 명령을 따르면 그대들은 이 새로운 세계를 지배할 수 있다! 어둠의 문 반대편의 세계는 그대들의 것이니라. 새 세상으로 나아가라!', `MaleText_loc4`='这是个命运的时刻！在另一边，一个新的开始在等待着，一群的敌人在等待着我们去消灭。你们有没有感觉到这一切？有没有感受到嗜血的复苏？跟随着黑手酋长吧！听从他的命令，你们将会统治这个新世界！在传送门的另一边，是你们的世界！夺取它！', `MaleText_loc5`='這是命運的一刻!另一方面，一個新的開始等待著。一個新的敵人讓我們屠宰。你可以感覺到，對嗎?嗜血的感覺再次興起?跟隨黑手!聽著他的命令你就會統治一個新世界，就像你的權力一樣!傳送門的另一邊是你的世界。接招吧!', `MaleText_loc7`='¡Este es el momento del destino! Por otra parte, un nuevo comienzo aguarda. Un nuevo enemigo al que masacrar. Lo sientes, ¿verdad? ¿Sientes cómo sube el ansia de sangre? ¡Sigue a Puño Negro! ¡Escucha sus órdenes y dominarás este nuevo mundo como es tu derecho! Es tu mundo al otro lado del portal. ¡Tómalo!' WHERE `ID`=13274;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드를 위하여!', `MaleText_loc4`='为了部落！', `MaleText_loc5`='為了部落!', `MaleText_loc7`='¡POR LA HORDA!', `FemaleText_loc1`='호드를 위하여!', `FemaleText_loc4`='为了部落！', `FemaleText_loc5`='為了部落!', `FemaleText_loc7`='¡POR LA HORDA!' WHERE `ID`=13275;
