UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 손님!', `MaleText_loc4`='当然，先生。', `MaleText_loc5`='當然，主人。', `MaleText_loc7`='Por supuesto, señor.' WHERE `ID`=13279;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 에너지가 흘러나가자 약해집니다.', `MaleText_loc4`='%s由于能量的流逝而开始变得虚弱。', `MaleText_loc5`='%s當它的能量流逝開始變的虛弱。', `MaleText_loc7`='%s comienza a debilitarse, a medida que su energía se va con su sangre.' WHERE `ID`=13280;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 음악은 아무리 들어도 질리지가 않네요. 그렇지 않습니까?', `MaleText_loc4`='这音乐怎么也不会过时，对吗？', `MaleText_loc5`='這音樂怎麼聽都不膩，對吧?', `MaleText_loc7`='Esta música nunca pasa de moda, ¿verdad?', `FemaleText_loc1`='이 음악은 아무리 들어도 질리지가 않네요. 그렇지 않으세요?', `FemaleText_loc4`='这音乐怎么也不会过时，对吗？', `FemaleText_loc5`='這音樂怎麼聽都不膩，對吧?', `FemaleText_loc7`='Esta música nunca pasa de moda, ¿verdad?' WHERE `ID`=13281;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 이상합니다. 제가 어떻게 여기 오게 됐는지 기억이 나질 않네요.', `MaleText_loc4`='太奇怪了，我不记得自己是怎么到这里来的了。', `MaleText_loc5`='好奇怪:我記不起來我是怎麼到達這裡的。', `MaleText_loc7`='Es tan extraño; no recuerdo cómo llegué hasta aquí.', `FemaleText_loc1`='정말 이상합니다. 제가 어떻게 여기 오게 됐는지 기억이 나질 않네요.', `FemaleText_loc4`='太奇怪了，我不记得自己是怎么到这里来的了。', `FemaleText_loc5`='好奇怪:我記不起來我是怎麼到達這裡的。', `FemaleText_loc7`='Es tan extraño; no recuerdo cómo llegué hasta aquí.' WHERE `ID`=13282;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 완료하지 못한 임무가 있는 것 같은데...', `MaleText_loc4`='我感觉似乎有什么事情还没有做完……', `MaleText_loc5`='我想我還有個任務未完成...', `MaleText_loc7`='Es como si todavía tuviera una misión pendiente...', `FemaleText_loc1`='아직 완료하지 못한 임무가 있는 것 같은데...', `FemaleText_loc4`='我感觉似乎有什么事情还没有做完……', `FemaleText_loc5`='我想我還有個任務未完成...', `FemaleText_loc7`='Es como si todavía tuviera una misión pendiente...' WHERE `ID`=13283;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 왜 여기 왔는지 모르겠습니다. 하지만, 이곳에서 최고의 시간을 보내고 있습니다!', `MaleText_loc4`='说实话我不知道自己为什么会在这里，但我觉得很开心！', `MaleText_loc5`='對於我的生活，我不知道為什麼我在這裡，但是我有最美好的時光!', `MaleText_loc7`='¡Juro por mi vida que no sé por qué estoy aquí, pero me lo estoy pasando en grande!', `FemaleText_loc1`='제가 왜 여기 왔는지 모르겠습니다. 하지만, 이곳에서 최고의 시간을 보내고 있습니다!', `FemaleText_loc4`='说实话我不知道自己为什么会在这里，但我觉得很开心！', `FemaleText_loc5`='對於我的生活，我不知道為什麼我在這裡，但是我有最美好的時光!', `FemaleText_loc7`='¡Juro por mi vida que no sé por qué estoy aquí, pero me lo estoy pasando en grande!' WHERE `ID`=13284;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 모든 게 너무 이상하게만 보입니다.', `MaleText_loc4`='这一切看上去都太奇怪了。', `MaleText_loc5`='這些似乎很怪異。', `MaleText_loc7`='Todo esto resulta muy extraño.', `FemaleText_loc1`='이 모든 게 너무 이상하게만 보입니다.', `FemaleText_loc4`='这一切看上去都太奇怪了。', `FemaleText_loc5`='這些似乎很怪異。', `FemaleText_loc7`='Todo esto resulta muy extraño.' WHERE `ID`=13286;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='딱 한 곡만 더 추겠어요. 그런 다음 정말 떠나야 합니다! 그러니까 그곳으로 돌아가야 하는데... 어딘가 하면...', `MaleText_loc4`='也许只能再跳一支舞了。我必须要走了！我必须回到……回到……', `MaleText_loc5`='或許可以再跳一首。然後我真的要離開了!我要趕快回去...去...', `MaleText_loc7`='Tal vez un baile más. ¡Luego debo irme, de veras! Tengo que volver a... a...', `FemaleText_loc1`='딱 한 곡만 더 추겠어요. 그런 다음 정말 떠나야 합니다! 그러니까 그곳으로 돌아가야 하는데... 어딘가 하면...', `FemaleText_loc4`='也许只能再跳一支舞了。我必须要走了！我必须回到……回到……', `FemaleText_loc5`='或許可以再跳一首。然後我真的要離開了!我要趕快回去...去...', `FemaleText_loc7`='Tal vez un baile más. ¡Luego debo irme, de veras! Tengo que volver a... a...' WHERE `ID`=13287;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='도와주시겠다니 정말 감사합니다. 이제 여기서 빠져나갑시다, $n.', `FemaleText_loc4`='谢谢你愿意伸出援手，现在让我们离开这里，$n！', `FemaleText_loc5`='謝謝你願意幫忙。現在，我們離開這裡吧，$n!', `FemaleText_loc7`='Gracias por prestarnos tu ayuda. ¡Y ahora, salgamos de aquí, $n!' WHERE `ID`=13289;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='휴, 잠시만 쉴 시간을 주세요. 제 체력으로는 감당하기 어려운 여정이네요.', `FemaleText_loc4`='请让我休息一会，我已经非常累了。', `FemaleText_loc5`='讓我休息一下。這旅程讓我微小的力量倍感壓力。', `FemaleText_loc7`='Permíteme que descanse un momento. Este viaje está agotando las pocas fuerzas que me quedan.' WHERE `ID`=13290;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 한 잔 더!', `MaleText_loc4`='再来一杯！', `MaleText_loc5`='再來一杯!', `MaleText_loc7`='¡Otro trago!', `FemaleText_loc1`='여기 한 잔 더!', `FemaleText_loc4`='再来一杯!', `FemaleText_loc5`='再來一杯!', `FemaleText_loc7`='¡Otro trago!' WHERE `ID`=13291;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오.. 매의 감시탑, 드디어 도착했군요! 어디 보자, 짐이 어디... 이런! 제 짐이... 짐이 없어졌어요! 아, 대체 어디에...', `FemaleText_loc4`='终于到了猎鹰岗哨！现在，我的……？天哪！我的背包找不到了！这可怎么办……', `FemaleText_loc5`='獵鷹哨站，終於!那麼，我的東西在哪...喔不!我的背包，它不見了!跑哪去了 -', `FemaleText_loc7`='¡La Avanzada del Halcón, por fin! Bueno, dónde está mi... ¡Oh, no! ¡Mi talega ha desaparecido! ¿Dónde -' WHERE `ID`=13292;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음식도 더! 포도주도 한 잔 더!', `MaleText_loc4`='多来点食物！多来点酒！', `MaleText_loc5`='更多食物!更多酒!', `MaleText_loc7`='¡Más comida! ¡Más vino!', `FemaleText_loc1`='음식도 더! 포도주도 한 잔 더!', `FemaleText_loc4`='多来点食物！多来点酒！', `FemaleText_loc5`='更多食物!更多酒!', `FemaleText_loc7`='¡Más comida! ¡Más vino!' WHERE `ID`=13293;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번에는 멀롯 술 맛을 한번 보고 싶군.', `MaleText_loc4`='我想这次我要试试葡萄酒。', `MaleText_loc5`='我相信這次我可以再多試試。', `MaleText_loc7`='Creo que esta vez probaré el merlot.', `FemaleText_loc1`='이번에는 멀롯 술 맛을 한번 보고 싶군.', `FemaleText_loc4`='我想这次我要试试葡萄酒。', `FemaleText_loc5`='我相信這次我可以再多試試。', `FemaleText_loc7`='Creo que esta vez probaré el merlot.' WHERE `ID`=13294;
