UPDATE `locales_broadcast_text` SET `MaleText_loc1`='즉시 대령하겠습니다!', `MaleText_loc4`='马上！', `MaleText_loc5`='立刻!', `MaleText_loc7`='¡Enseguida!', `FemaleText_loc1`='즉시 대령하겠습니다!', `FemaleText_loc4`='马上！', `FemaleText_loc5`='立刻!', `FemaleText_loc7`='¡Enseguida!' WHERE `ID`=13296;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='금방 대령하지요!', `MaleText_loc4`='我这就来！', `MaleText_loc5`='馬上!', `MaleText_loc7`='¡Ahora mismo!', `FemaleText_loc1`='금방 대령하지요!', `FemaleText_loc4`='我这就来！', `FemaleText_loc5`='馬上!', `FemaleText_loc7`='¡Ahora mismo!' WHERE `ID`=13297;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘은 아주 긴 밤이 될 것 같군! 여기, 술을 계속 대령하도록!', `MaleText_loc4`='继续上酒，今晚不醉不休！', `MaleText_loc5`='保持飲水來源;還要渡過一整夜呢!', `MaleText_loc7`='No dejes de ir trayendo bebida; ¡va a ser una noche muy larga!', `FemaleText_loc1`='오늘은 아주 긴 밤이 될 것 같군! 여기, 술을 계속 대령하도록!', `FemaleText_loc4`='继续上酒，今晚不醉不休！', `FemaleText_loc5`='保持飲水來源;還要渡過一整夜呢!', `FemaleText_loc7`='No dejes de ir trayendo bebida; ¡va a ser una noche muy larga!' WHERE `ID`=13298;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생사가 달렸다고 생각하고 연습하시오!', `MaleText_loc4`='好好练习，因为你的命就全靠它了！', `MaleText_loc5`='下次要表現的悠關你的性命，因為事實上就是如此!', `MaleText_loc7`='¡Practica como si te fuera la vida, porque así es!' WHERE `ID`=13299;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 볼품없는 공격은 대체 뭐지요? 돌격할 땐 과감하게 그리고 찌를 때는 단숨에, 아시겠습니까?', `MaleText_loc4`='你在拍蚊子吗？给我打起精神来！', `MaleText_loc5`='那是什麼可悲的打擊啊?振作起來，立刻!', `MaleText_loc7`='¿Qué clase de patético golpe ha sido ese? ¡Toma forma de inmediato!' WHERE `ID`=13300;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런 방어 태세는 소녀들이나 합니다! 어깨를 좀 더 다부지게 펴십시오!', `MaleText_loc4`='你的格档就像个女孩一样！用点力气！', `MaleText_loc5`='你像個小女孩一樣遲鈍!把你的肩膀放進去!', `MaleText_loc7`='¡Bloqueas como una niñita! ¡Usa el hombro!' WHERE `ID`=13301;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='똑바로 서는 게 좋겠지요? 대답하십시오!', `MaleText_loc4`='你最好改正，否则我就给你点颜色看看！', `MaleText_loc5`='你最好用心接受訓練，否則你就要對我負責!', `MaleText_loc7`='¡Más vale que pongas la espalda recta o te las verás conmigo!' WHERE `ID`=13302;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$c|1이여;여;, 어서 오십시오.', `FemaleText_loc4`='非常欢迎，$c。', `FemaleText_loc5`='我向你表示歡迎之意，$c。', `FemaleText_loc7`='Te doy la bienvenida, $c.' WHERE `ID`=13303;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여; 한가롭게 잡담이나 할 시간이 없소이다. 순례자들을 만나서 그들이 긴 여행에 대한 준비를 했는지 확인해야 하오.', `MaleText_loc4`='我没有时间来闲聊，$c。我必须照顾那些朝圣者，保证他们为漫长的旅程做好充足的准备。', `MaleText_loc5`='我沒時間閒聊，$c。我一定要照料那些朝聖者確保他們為前方漫長的旅途做好準備。', `MaleText_loc7`='No tengo tiempo para cháchara, $c. Debo ocuparme de los peregrinos y asegurarme de que están preparados para el largo viaje que hay por delante.' WHERE `ID`=13304;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='매의 감시탑에 온 것을 환영하오, $c|1이여;여;. 난 순례자들이 필요한 물품을 챙기고 긴 여행을 계속할 수 있도록 도와야 하오. 아직 순례 여행을 하고 있지 않다면 추후 여행에 필요한 정보를 드릴 수도 있소이다.', `MaleText_loc4`='欢迎来到猎鹰岗哨，$c。我留意着那些朝圣者的需求，并帮助他们继续走完漫长的旅程。如果你还没有开始朝圣，我可以给你提供一些你需要的信息。', `MaleText_loc5`='歡迎來到獵鷹哨站，$c。我會注意朝聖者的需要並在他們漫長的旅途中幫助他們。如果你還沒進行朝聖，我可以提供你會需要的資訊。', `MaleText_loc7`='$gBienvenido:Bienvenida; a la Avanzada del Halcón, $c. Yo me hago cargo de las necesidades de los peregrinos y los ayudo a continuar su largo viaje. Si todavía no has emprendido la peregrinación, puedo proporcionarte la información que necesites.' WHERE `ID`=13305;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 반갑소이다.', `MaleText_loc4`='你好，$C。', `MaleText_loc5`='你好，$c。', `MaleText_loc7`='Saludos, $c.' WHERE `ID`=13306;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예, 알겠습니다!', `MaleText_loc4`='遵命！', `MaleText_loc5`='是的，長官!', `MaleText_loc7`='¡Sí, señor!', `FemaleText_loc1`='예, 알겠습니다!', `FemaleText_loc4`='遵命！', `FemaleText_loc5`='是的，長官!', `FemaleText_loc7`='¡Sí, señor!' WHERE `ID`=13307;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='언제나 빛 속에서 당당하게 나아가십시오, $n.', `FemaleText_loc4`='愿圣光永远照耀你，$n。', `FemaleText_loc5`='永遠走在聖光中，$n。', `FemaleText_loc7`='Camina siempre en la Luz, $n.' WHERE `ID`=13308;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='원정순찰대 산장에 오신 것을 환영합니다. 우리 순찰자들은 인근 지역은 물론 아주 먼 지역까지 우리 백성을 보호하기로 맹세했습니다.', `FemaleText_loc4`='欢迎来到远行者居所。我们是一个发誓保卫人民的游侠组织。', `FemaleText_loc5`='歡迎來到遠行者居所。我們是誓死保護人民不受遠近敵人侵犯的遊俠。', `FemaleText_loc7`='$gBienvenido:Bienvenida; al Retiro del Errante. Somos forestales que hemos jurado defender a nuestra gente de los enemigos cercanos y lejanos.' WHERE `ID`=13309;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 당신 정체가 뭐지? 엘프나... 뭐... 그 비슷한 종족인가? 어쩐지 낯익은 얼굴인데... <딸꾹>', `MaleText_loc4`='嘿，有什么可以为你效劳的？你是精灵还是什么？你看上去有点眼熟。', `MaleText_loc5`='那麼，你的意思到底是什麼?你是精靈還是什麼生物?你看起來有點面熟。', `MaleText_loc7`='Di, ¿cuál esh tu acuerdo, de todash formash? ¿Eresh algún tipo de elfo o algo ashí? Me reshultas algo familiar.' WHERE `ID`=13310;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 투랄리온과 알레리아의 아들, 아라토르입니다. 맞습니다, 신부님. 저는 엘프의 핏줄을 타고났습니다. 정확히 말하자면 반은 엘프이지요.', `MaleText_loc4`='我是阿拉托尔，图拉扬和奥蕾莉亚的儿子。所以，神父，我的确是“有点”像精灵，确切地说是半精灵。', `MaleText_loc5`='我是阿拉特，圖拉揚和艾蘭里亞的兒子。所以是的，神父，我是「某種」程度上的精靈:正確地說是半個精靈。', `MaleText_loc7`='Soy Arator, hijo de Turalyon y Alleria. Así que, sí, Padre, "soy algún tipo" de elfo: mitad elfo, para ser exactos.' WHERE `ID`=13311;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s의 얼굴이 하얗게 질립니다. 그러다가 금세 침착함을 되찾은 듯 보입니다.', `MaleText_loc4`='%s的脸色变得煞白，但很快又恢复了清醒。', `MaleText_loc5`='%s的臉變的蒼白。清醒似乎來的相當快。', `MaleText_loc7`='La cara de %s empalidece. Parece recobrar la sobriedad con bastante rapidez.' WHERE `ID`=13312;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛의 이름으로! 이제 기억이 났어... 그래... 그래서 낯이 익었군. 이게 운명인가? 아마도 숙명이겠지, 아라토르? 자네 아버님과 나는 절친한 친구였지. 자네 아버지의 건강을 돌봐준 게 바로 나였네... 우리가 참가했던 전투... 그리고...', `MaleText_loc4`='以圣光的名义！难怪你看上去那么眼熟，难道这就是命中注定的吗？也许这就是命运？阿拉托尔，你的父亲和我曾经是最好的朋友，我是他的医生……啊，那些我们一起战斗过的岁月……', `MaleText_loc5`='以聖光之名!這就是你為什麼看起來這麼面熟的原因。這是命運嗎?或許是天命?阿拉特，我和你的父親曾是最好的朋友。是我讓他健健康康的...喔我們打的那些仗...還有...', `MaleText_loc7`='¡Por la Luz! Así que, por eso me resultas familiar. ¿Es esto el sino? ¿El destino, quizás? Arator, tu padre y yo fuimos los mejores amigos. Fui yo quien lo mantuvo con buena salud... Oh, las batallas que libramos... Y...' WHERE `ID`=13313;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 목소리를 가다듬습니다.', `MaleText_loc4`='%s清了清喉咙。', `MaleText_loc5`='%s清清他的喉嚨。', `MaleText_loc7`='%s se aclara la garganta.' WHERE `ID`=13314;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고... 우리가 패했던 전쟁. 정말... 미안하네, 아라토르. 내 잘못이었어...', `MaleText_loc4`='但是……我们输了那场战争。我……我很抱歉，阿拉托尔。是我的错……', `MaleText_loc5`='還有...我們輸的那場仗。我...我很抱歉，阿拉特。是我的錯...', `MaleText_loc7`='Y... perdimos la batalla. Lo... Lo siento, Arator. Fue por mi culpa...' WHERE `ID`=13315;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 흐느낍니다.', `MaleText_loc4`='%s开始哭泣。', `MaleText_loc5`='%s開始啜泣。', `MaleText_loc7`='%s comienza a sollozar.', `FemaleText_loc1`='%s|1이;가; 흐느낍니다.', `FemaleText_loc4`='%s开始哭泣。', `FemaleText_loc5`='%s開始啜泣。', `FemaleText_loc7`='%s comienza a sollozar.' WHERE `ID`=13316;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서, 시드. 내 잔을 채워 주게. 이 술로 내 아픈 기억을 지워야 하네...', `MaleText_loc4`='快点，希德。帮我倒满酒。让我忘记这一切……', `MaleText_loc5`='快，希德。裝滿我的大啤酒杯。讓回憶褪去...', `MaleText_loc7`='Rápido, Sid. Lléname la jarra. Haz que los recuerdos se desvanezcan...' WHERE `ID`=13317;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형제여... 잘 들으십시오. 저분은 여기서 아이처럼 다섯 시간은 더 울 겁니다. 그러니 당신이 정말 투랄리온 님의 아들이라면 트롤베인 님과 대화해 보시는 게 좋겠습니다. 트롤베인 님께선 요새의 꼭대기 층에 계시니 그리로 가보십시오.', `MaleText_loc4`='哦，兄弟……我跟你说，他至少还要像婴儿那样再哭上五个小时才算罢休。如果你真的是图拉扬的儿子，就去和托尔贝恩谈谈吧。他就在要塞的顶楼。', `MaleText_loc5`='喔老兄...聽著，他會在這裡像個嬰兒一樣再哭上五個小時。如果你真的是圖拉揚之子，去和托爾貝恩談談。他在堡壘裡 - 頂樓。', `MaleText_loc7`='Oh, hermano... Escucha, va a estar aquí llorando como un bebé cinco horas más. Si eres realmente el hijo de Turalyon, ve a hablar con Aterratrols. Está en el fuerte – el último de piso.' WHERE `ID`=13318;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 고개를 끄덕입니다.', `MaleText_loc4`='%s点了点头。', `MaleText_loc5`='%s點點頭。', `MaleText_loc7`='%s asiente con la cabeza.' WHERE `ID`=13319;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시드, 그분을 잘 돌봐주십시오. 그분은 제 부모님을 아는 유일한 분이십니다. 어서 진정하셔야 할 텐데...', `MaleText_loc4`='好好照顾他，希德。他可能是我和我父母之间唯一的联系。他需要清醒一点……', `MaleText_loc5`='好好照顧他，希德。他可能是尋找我父母的唯一希望。他需要清醒過來...', `MaleText_loc7`='Cuida de él, Sid. Puede que sea el único vínculo que tengo con mi padre y mi madre. Necesita que se le pase la borrachera...' WHERE `ID`=13320;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이번 순례를 맡은 게 후회되기 시작하는군요. 저는 험난한 여정을 예상했고 여행에도 익숙합니다. 그런데 아웃랜드가 이렇게나 거친 곳인지는 미처 몰랐습니다.$B$B무엇보다도 저 탈레리스가 제가 완전히 회복하기도 전에 여기서 저를 쫓아내려고 하는 것 같습니다.', `FemaleText_loc4`='我想我已经开始后悔来进行这次朝圣了。我知道路途会很艰辛，而且我也并不是一个远行的新手，但我没有准备好面对外域的困难。$B$B最主要的是，那个塔雷里斯似乎想要在我完全恢复力量之前把我赶出这里。', `FemaleText_loc5`='我想我開始後悔參加這次朝聖了。我知道路途會很崎嶇而我對旅行也不陌生，但我並沒有料想到外域艱苦的環境。$B$B更重要的是，那個達勒利斯好像想在我還沒完全恢復我的力量時把我趕出這裡。', `FemaleText_loc7`='Creo que empiezo a arrepentirme de emprender esta peregrinación. Esperaba que el camino sería duro y estoy acostumbrada a viajar, pero no estaba preparada para los rigores de Terrallende.$B$BAdemás de todo lo demás, ese Taleris parece querer alejarme de aquí antes de que haya recobrado mis fuerzas por completo.' WHERE `ID`=13321;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 안녕히 계십시오, 사령관님. 저는 여관에 머물 것이니 필요하시면 불러주세요.', `MaleText_loc4`='保重，指挥官。我会待在旅店里面，需要帮忙的话尽管找我。', `MaleText_loc5`='再會了，指揮官。我會待在旅店，如果你需要我的幫忙就來找我。', `MaleText_loc7`='Adiós, comandante. Me alojaré en la posada, por si necesita mis servicios.' WHERE `ID`=13322;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래... 이 정도면 괜찮겠군.', `MaleText_loc4`='是的……这应该可以。', `MaleText_loc5`='沒錯...這會很有用。', `MaleText_loc7`='Sí... esto servirá.' WHERE `ID`=13323;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불안정한 원천이라... 그 격렬함에 끌리는군!', `MaleText_loc4`='一种不稳定的资源……不过它在热情地召唤我！', `MaleText_loc5`='一個不穩定的泉源...但它的溫暖吸引了我。', `MaleText_loc7`='Una fuente inestable... ¡pero su calor me llama!' WHERE `ID`=13324;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일어나십시오, 갈레사.', `MaleText_loc4`='醒醒，加尔蕾萨。', `MaleText_loc5`='醒醒，高瑞莎。', `MaleText_loc7`='Despierta, Gal''ressa.' WHERE `ID`=13325;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 눈을 비벼 눈곱을 뗍니다.', `FemaleText_loc4`='%s揉了揉她的眼睛。', `FemaleText_loc5`='%s揉揉她惺忪的睡眼。', `FemaleText_loc7`='%s se frota los ojos para quitarse el sueño.' WHERE `ID`=13326;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='원하는 게 뭔가요, 탈레리스?', `FemaleText_loc4`='你有什么事吗，塔雷里斯？', `FemaleText_loc5`='你想要怎樣，達勒利斯?', `FemaleText_loc7`='¿Qué quieres, Taleris?' WHERE `ID`=13327;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갈레사, 이제 부상에서 충분히 회복하신 것 같습니다. 다시 여정을 시작할 때가 되었습니다.', `MaleText_loc4`='加尔蕾萨，你花了好些时间养伤，现在是你重新上路的时候了。', `MaleText_loc5`='你有足夠的時間讓你的傷勢復原，高瑞莎。是時候回到你走的路上了。', `MaleText_loc7`='Has tenido tiempo suficiente para recuperarte de las heridas, Gal''ressa. Ha llegado el momento de que vuelvas al camino.' WHERE `ID`=13328;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='탈레리스, 전 혼자선 갈 수 없으며 혼자서 여정을 떠나는 건 최후의 선택입니다. 다음 순례자들이 올 때까지 여기서 기다렸다가 그들과 함께 출발하겠습니다.', `FemaleText_loc4`='我不想一个人走，塔雷里斯。我会在这里等着下一批朝圣者，等他们到了之后和他们一起出发。', `FemaleText_loc5`='我不會獨自走下去的，達勒利斯，就是這樣。我要在這裡等待下一批朝聖者再和他們一起出發。', `FemaleText_loc7`='No voy a continuar sola, Taleris, es definitivo. Voy a esperar aquí al siguiente grupo de peregrinos y partiré con ellos cuando se marchen.' WHERE `ID`=13329;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럴 수는 없습니다. 당신을 돌봐줄 여유가 없으니 죄송하지만 이제 떠나주십시오.', `MaleText_loc4`='绝对不行。我们没有多余的房间给你用。你还是走吧。', `MaleText_loc5`='你不能這麼做。我們沒有房間讓你留在這裡。現在，識相的走吧。', `MaleText_loc7`='Ni hablar. Simplemente, no tenemos espacio para que te quedes aquí. Y ahora, largo, por favor.' WHERE `ID`=13330;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말 머리가 나쁘군요! 날 위협해서 보내려는 생각은 버리십시오, 탈레리스. 당장 내 눈앞에서 사라져줘요!', `FemaleText_loc4`='以太阳之井的名义，你太绝情了！你别想把我吓跑，塔雷里斯。现在从我的眼前滚开！', `FemaleText_loc5`='以太陽之井之名，你這個厚顏無恥的人!你不能恐嚇我離開的，達勒利斯。現在，消失在我的視線裡!', `FemaleText_loc7`='¡Por La Fuente del Sol, qué cabeza más dura! No me obligarás a irme, Taleris. ¡Y ahora, vete de mi vista!' WHERE `ID`=13331;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇다면, 알겠습니다. 마음대로 하십시오. 우리가 다른 순례자들을 내쫓을 때 그들이 받을 고통은 당신 책임입니다. 그 점 명심하십시오.', `MaleText_loc4`='那么好吧，随便。如果我们不得不把其他人拒之门外，你就是导致他们痛苦的根源。自己想想吧。', `MaleText_loc5`='很好，就用你的辦法。等我們把其他人趕走，你就要為他們受的苦負責。考慮看看。', `MaleText_loc7`='Muy bien, hazlo a tu manera. Cuando rechacemos a otros, tú serás responsable de su sufrimiento. Piensa en ello.' WHERE `ID`=13332;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘밤 공연의 초대장이 있으면 좋겠는데...', `MaleText_loc4`='我真希望自己有今晚演出的门票！', `MaleText_loc5`='我希望我也有今晚在歌劇大廳的表演門票。', `MaleText_loc7`='¡Ojalá tuviera entradas para el espectáculo de esta noche!', `FemaleText_loc1`='오늘밤 공연의 초대장이 있으면 좋겠는데...', `FemaleText_loc4`='我真希望自己有今晚演出的门票！', `FemaleText_loc5`='我希望我也有今晚在歌劇大廳的表演門票。', `FemaleText_loc7`='¡Ojalá tuviera entradas para el espectáculo de esta noche!' WHERE `ID`=13333;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지난밤 공연이 대단했다고 들었습니다!', `MaleText_loc4`='我听说昨晚的演出非常精彩！', `MaleText_loc5`='我聽說昨晚的表演很精采!', `MaleText_loc7`='¡He oído que la actuación de anoche fue espectacular!', `FemaleText_loc1`='지난밤 공연이 대단했다고 들었어요!', `FemaleText_loc4`='我听说昨晚的演出非常精彩！', `FemaleText_loc5`='我聽說昨晚的表演很精采!', `FemaleText_loc7`='¡He oído que la actuación de anoche fue espectacular!' WHERE `ID`=13334;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳엔 음악 소리가 없어서 대화를 나누기가 편하군요.', `MaleText_loc4`='要是没有那些嘈杂的音乐，在这里交谈会更方便些。', `MaleText_loc5`='這裡沒有音樂，講起話來輕鬆多了。', `MaleText_loc7`='Es mucho más fácil hablar aquí, sin toda esa música.', `FemaleText_loc1`='이곳엔 음악 소리가 없어서 대화를 나누기가 편하군요.', `FemaleText_loc4`='要是没有那些嘈杂的音乐，在这里交谈会更方便些。', `FemaleText_loc5`='這裡沒有音樂，講起話來輕鬆多了。', `FemaleText_loc7`='Es mucho más fácil hablar aquí, sin toda esa música.' WHERE `ID`=13335;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마치 전에 와본 것처럼 이 모든 것이 익숙하네요.', `MaleText_loc4`='这一切看上去都好眼熟，好像我以前来过这里一样。', `MaleText_loc5`='一切都如此熟悉，就像我以前曾經來過一樣。', `MaleText_loc7`='Todo esto me resulta tan familiar... como si hubiera estado aquí antes.', `FemaleText_loc1`='마치 전에 와본 것처럼 이 모든 것이 익숙하네요.', `FemaleText_loc4`='这一切看上去都好眼熟，好像我以前来过这里一样。', `FemaleText_loc5`='一切都如此熟悉，就像我以前曾經來過一樣。', `FemaleText_loc7`='Todo esto me resulta tan familiar... como si hubiera estado aquí antes.' WHERE `ID`=13336;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리도 나중에 저들 틈에 껴서 춤을 추겠지요.', `MaleText_loc4`='也许我们应该加入跳舞的人群中。', `MaleText_loc5`='或許晚點我們可以參加跳舞。', `MaleText_loc7`='Quizás más tarde deberíamos unirnos al baile.', `FemaleText_loc1`='우리도 나중에 저들 틈에 껴서 춤을 추겠지요.', `FemaleText_loc4`='也许我们应该加入跳舞的人群中。', `FemaleText_loc5`='或許晚點我們可以參加跳舞。', `FemaleText_loc7`='Quizás más tarde deberíamos unirnos al baile.' WHERE `ID`=13337;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 여기 온 이유가 분명히 있을 텐테...', `MaleText_loc4`='我十分确定自己来这里是有什么原因的……', `MaleText_loc5`='我非常確定這是我來這裡的原因...', `MaleText_loc7`='Estoy bastante seguro de que había una razón por la que vine...', `FemaleText_loc1`='내가 여기 온 이유가 분명히 있을 텐테...', `FemaleText_loc4`='我十分确定自己来这里是有什么原因的……', `FemaleText_loc5`='我非常確定這是我來這裡的原因...', `FemaleText_loc7`='Estoy bastante segura de que había una razón por la que vine...' WHERE `ID`=13338;
