UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여러분, $n 씨를 소개합니다!', `MaleText_loc4`='大家看啊，$n来了！', `MaleText_loc5`='嘿大家，是$n!', `MaleText_loc7`='¡Eh, mirad todos, es $n!', `FemaleText_loc1`='여러분, $n 씨를 소개합니다!', `FemaleText_loc4`='大家看啊，$n来了！', `FemaleText_loc5`='嘿大家，是$n!', `FemaleText_loc7`='¡Eh, mirad todos, es $n!' WHERE `ID`=13341;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이쪽 계통은 소문이 아주 빠르죠. 파티 물품을 가져다줘서 고맙습니다!', `MaleText_loc4`='消息在这圈子里传得很快。感谢你帮我们补充货源！', `MaleText_loc5`='這個議會裡消息都傳的很快。謝謝你補足了物資!', `MaleText_loc7`='Las palabras viajan rápido en este círculo. ¡Gracias por reponer los suministros!', `FemaleText_loc1`='이쪽 계통은 소문이 아주 빠르죠. 파티 물품을 가져다줘서 고마워요!', `FemaleText_loc4`='消息在这圈子里传得很快。感谢你帮我们补充货源！', `FemaleText_loc5`='這個議會裡消息都傳的很快。謝謝你補足了物資!', `FemaleText_loc7`='Las palabras viajan rápido en este círculo. ¡Gracias por reponer los suministros!' WHERE `ID`=13342;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번 파티는 정말 최고예요!', `MaleText_loc4`='这个聚会是最棒的！你不觉得吗？', `MaleText_loc5`='這個派對就是最棒的!你不覺得嗎?', `MaleText_loc7`='¡Esta fiesta es genial! ¿No te parece?', `FemaleText_loc1`='이번 파티는 정말 최고예요!', `FemaleText_loc4`='这个聚会是最棒的！你不觉得吗？', `FemaleText_loc5`='這個派對就是最棒的!你不覺得嗎?', `FemaleText_loc7`='¡Esta fiesta es genial! ¿No te parece?' WHERE `ID`=13343;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갈기발 요리를 꼭 드셔보십시오. 정말 환상적입니다!', `MaleText_loc4`='你应该尝尝魔泉美味，简直太棒了！', `MaleText_loc5`='你應該試試泉爪開胃菜，他們好吃死了!', `MaleText_loc7`='Deberías probar los aperitivos de garragil, ¡están para morirse!', `FemaleText_loc1`='갈기발 요리를 꼭 드셔보세요. 정말 환상적이거든요!', `FemaleText_loc4`='你应该尝尝魔泉美味，简直太棒了！', `FemaleText_loc5`='你應該試試泉爪開胃菜，他們好吃死了!', `FemaleText_loc7`='Deberías probar los aperitivos de garragil, ¡están para morirse!' WHERE `ID`=13344;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠... 올해 햇살 깃든 특등급 포도주는 별로 특별한 느낌이 없습니다. 그렇지 않나요, $n?', `MaleText_loc4`='我觉得今年的日光陈酿不是那么好喝。你觉得呢，$n？', `MaleText_loc5`='嗯...我認為今年的特殊美酒不怎麼特別。你同意嗎，$n?', `MaleText_loc7`='Mmm... Creo que el Toquesol especial de este año no es tan especial, después de todo. ¿No estás de acuerdo, $n?', `FemaleText_loc1`='흠... 올해 햇살 깃든 특등급 포도주는 별로 특별한 느낌이 없습니다. 그렇지 않나요, $n?', `FemaleText_loc4`='我觉得今年的日光陈酿不是那么好喝。你觉得呢，$n？', `FemaleText_loc5`='嗯...我認為今年的特殊美酒不怎麼特別。你同意嗎，$n?', `FemaleText_loc7`='Mmm... Creo que el Toquesol especial de este año no es tan especial, después de todo. ¿No estás de acuerdo, $n?' WHERE `ID`=13345;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 밤 우리 모두 국경에서 스컬지와 벌어지는 전투를 구경하러 간대요. 정말 재미있는 일이죠?!', `MaleText_loc4`='听说我们今晚都要去边界观看防御部队和天灾军团的战斗。多令人激动啊！', `MaleText_loc5`='我聽說我們今晚都要去邊界觀看和天譴軍團的戰鬥。真棒!', `MaleText_loc7`='He oído el rumor de que, esta noche, todos vamos a observar la batalla con los miembros de la Plaga en la frontera. ¡Qué deliciosamente malvado!', `FemaleText_loc1`='오늘 밤 우리 모두 국경에서 스컬지와 벌어지는 전투를 구경하러 간대요. 정말 재미있는 일이죠?!', `FemaleText_loc4`='听说我们今晚都要去边界观看防御部队和天灾军团的战斗。多令人激动啊！', `FemaleText_loc5`='我聽說我們今晚都要去邊界觀看和天譴軍團的戰鬥。真棒!', `FemaleText_loc7`='He oído el rumor de que, esta noche, todos vamos a observar la batalla con los miembros de la Plaga en la frontera. ¡Qué deliciosamente malvado!' WHERE `ID`=13346;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엘리사라 선스트라이커는 믿기지 않을 만큼 용기 있는 여인입니다. 그녀가 살데릴 경의 눈에 들 수 있을까요? 그런데 엘리사라의 옷 차림새는 유행에 한참 뒤떨어져 있더군요. 정말 안 된 일이죠.', `MaleText_loc4`='你能相信那个埃莉萨拉·射日者的勇气吗？她居然认为自己可以引起萨瑟利尔男爵的注意，还有，你看到她都穿了些什么吗？太落伍了。真令人伤心，真的。', `MaleText_loc5`='你相信那個艾麗莎·擊日者的膽量嗎?覺得她可以吸引到薩瑟里領主的目光?你有看到她穿的衣服嗎?早就過時了。真悲哀，真的。', `MaleText_loc7`='¿Te puedes creer el descaro de esa Elisara Golpesol? ¡Se cree que puede atraer la atención de Lord Saltheril! Y, ¿has visto lo que lleva puesto? Es de la temporada pasada. Es tan triste...', `FemaleText_loc1`='엘리사라 선스트라이커는 믿기지 않을 만큼 용기 있는 여인입니다. 그녀가 살데릴 경의 눈에 들 수 있을까요? 그런데 엘리사라의 옷 차림새는 유행에 한참 뒤떨어져 있더군요. 정말 안 된 일이죠.', `FemaleText_loc4`='你能相信那个埃莉萨拉·射日者的勇气吗？她居然认为自己可以引起萨瑟利尔男爵的注意，还有，你看到她都穿了些什么吗？太落伍了。真令人伤心，真的。', `FemaleText_loc5`='你相信那個艾麗莎·擊日者的膽量嗎?覺得她可以吸引到薩瑟里領主的目光?你有看到她穿的衣服嗎?早就過時了。真悲哀，真的。', `FemaleText_loc7`='¿Te puedes creer el descaro de esa Elisara Golpesol? ¡Se cree que puede atraer la atención de Lord Saltheril! Y, ¿has visto lo que lleva puesto? Es de la temporada pasada. Es tan triste...' WHERE `ID`=13347;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죄송합니다, 저는 일꾼과는 이야기를 나누지 않습니다.', `MaleText_loc4`='对不起，我不需要帮忙。', `MaleText_loc5`='抱歉，我不和幫忙的人說話。', `MaleText_loc7`='Lo siento, no hablo con el servicio.', `FemaleText_loc1`='죄송해요, 전 일꾼과는 이야기를 나누지 않아요.', `FemaleText_loc4`='对不起，我不需要帮忙。', `FemaleText_loc5`='抱歉，我不和幫忙的人說話。', `FemaleText_loc7`='Lo siento, no hablo con el servicio.' WHERE `ID`=13348;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런데 당신은 누구신지?', `MaleText_loc4`='你是……？', `MaleText_loc5`='那你是?', `MaleText_loc7`='¿Y tú eres...?', `FemaleText_loc1`='당신은 누구신가요?', `FemaleText_loc4`='你是……？', `FemaleText_loc5`='那你是?', `FemaleText_loc7`='¿Y tú eres...?' WHERE `ID`=13349;
