UPDATE `locales_broadcast_text` SET `MaleText_loc1`='응, 뭐야? 무슨 일이지?', `MaleText_loc4`='什么？发生什么事了？', `MaleText_loc5`='啊?什麼?發生了什麼事?', `MaleText_loc7`='Eh... ¿qué? ¿Qué ha ocurrido?', `FemaleText_loc1`='응, 뭐야? 무슨 일이지?', `FemaleText_loc4`='什么？发生什么事了？', `FemaleText_loc5`='啊?什麼?發生了什麼事?', `FemaleText_loc7`='Eh... ¿qué? ¿Qué ha ocurrido?' WHERE `ID`=13352;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저리 가... 난 여기서 잘래.', `MaleText_loc4`='走开……我想在这里睡觉。', `MaleText_loc5`='走開...我想在這裡睡覺。', `MaleText_loc7`='Lárgate... estoy intentando dormirrrr.', `FemaleText_loc1`='저리 가... 난 여기서 잘래.', `FemaleText_loc4`='走开……我试着在这里睡觉。', `FemaleText_loc5`='走開...我想在這裡睡覺。', `FemaleText_loc7`='Lárgate... estoy intentando dormirrrr.' WHERE `ID`=13353;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악, 속이 너무 안 좋아.', `MaleText_loc4`='我感觉不太舒服！', `MaleText_loc5`='唉，我覺得不太舒服。', `MaleText_loc7`='Argh, me encuentro un poco mal.', `FemaleText_loc1`='악, 속이 너무 안 좋아.', `FemaleText_loc4`='我感觉不太舒服！', `FemaleText_loc5`='唉，我覺得不太舒服。', `FemaleText_loc7`='Argh, me encuentro un poco mal.' WHERE `ID`=13354;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='파티에 ''탐탁지 않은 것''들을 너무 많이 들이는 것 같지 않아요? 제 친구들이 어떻게 생각할까 걱정이랍니다.', `FemaleText_loc4`='萨瑟利尔，你觉得是不是我们让太多“不受欢迎的人”来参加我们的聚会了？我有点担心朋友们会怎么想。', `FemaleText_loc5`='薩爾西，你覺得我們讓太多「不良份子」加入隊伍了嗎?我擔心我們的朋友會對這整件事怎麼想。', `FemaleText_loc7`='Salthy, ¿crees que estamos permitiendo la entrada a demasiados "indeseables"?' WHERE `ID`=13355;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오늘 밤에는 마을로 데려가 준다고 약속했잖아요! 오늘 밤도 여기에만 있을 건가요?', `FemaleText_loc4`='你答应我今晚带我进城玩的！是不是今晚我们还要待在这里？', `FemaleText_loc5`='你答應要帶我去鎮上過夜的!我們今晚又只要這樣站在這嗎?', `FemaleText_loc7`='¡Me prometiste que saldríamos por la noche en la ciudad! ¿Vamos a volver a pasarnos la noche aquí?' WHERE `ID`=13356;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 그러고 싶지 않습니다.', `MaleText_loc4`='我讨厌这么做，却不得不这么做。', `MaleText_loc5`='我恨這樣做。', `MaleText_loc7`='Odio tener que hacer esto.', `FemaleText_loc1`='정말 그러고 싶지 않습니다.', `FemaleText_loc4`='我讨厌这么做，却不得不这么做。', `FemaleText_loc5`='我恨這樣做。', `FemaleText_loc7`='Odio tener que hacer esto.' WHERE `ID`=13357;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 계속 공격해 오고 있습니다. 쓰러뜨리는 것 말고는 다른 방법이 없습니다.', `MaleText_loc4`='他们不断地进攻。我除了把他们都消灭以外别无办法。', `MaleText_loc5`='他們持續攻擊。我除了殺了他們沒有別的辦法。', `MaleText_loc7`='Siguen atacando. No hay nada más que pueda hacer, excepto sofocar el ataque.', `FemaleText_loc1`='놈들이 계속 공격해 오고 있습니다. 쓰러뜨리는 것 말고는 다른 방법이 없습니다.', `FemaleText_loc4`='他们不断地进攻。我除了把他们都消灭以外别无办法。', `FemaleText_loc5`='他們持續攻擊。我除了殺了他們沒有別的辦法。', `FemaleText_loc7`='Siguen atacando. No hay nada más que pueda hacer, excepto sofocar el ataque.' WHERE `ID`=13358;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 일이 빨리 끝났으면 좋겠군요. 변종이든 아니든 이 올빼미야수를 죽이는 일은 정말 하고 싶지 않습니다.', `MaleText_loc4`='我希望这一切可以快点结束，杀死这些枭兽——变异的或者没有变异的——让我感到恶心。', `MaleText_loc5`='我希望這一切很快結束。要殺這些梟獸，不管他們有沒有突變，都讓我很難受。', `MaleText_loc7`='Espero que esto acabe pronto. Tener que matar a esos buhícos, mutantes o no, me enferma.', `FemaleText_loc1`='이 일이 빨리 끝났으면 좋겠군요. 변종이든 아니든 이 올빼미야수를 죽이는 일은 정말 하고 싶지 않습니다.', `FemaleText_loc4`='我希望这一切可以快点结束，杀死这些枭兽——变异的或者没有变异的——让我感到恶心。', `FemaleText_loc5`='我希望這一切很快結束。要殺這些梟獸，不管他們有沒有突變，都讓我很難受。', `FemaleText_loc7`='Espero que esto acabe pronto. Tener que matar a esos buhícos, mutantes o no, me enferma.' WHERE `ID`=13359;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛이여, 이들의 영혼을 당신의 품으로!', `MaleText_loc4`='圣光把这些生物的灵魂注入你的武器中！', `MaleText_loc5`='聖光指引這些怪物的靈魂投入你的懷抱!', `MaleText_loc7`='¡Que la luz lleve a los espíritus de estas criaturas a tus brazos!', `FemaleText_loc1`='빛이여, 이들의 영혼을 당신의 품으로!', `FemaleText_loc4`='圣光把这些生物的灵魂注入你的武器中！', `FemaleText_loc5`='聖光將這些生物的精神攬入你的臂膀!', `FemaleText_loc7`='¡Que la luz lleve a los espíritus de estas criaturas a tus brazos!' WHERE `ID`=13360;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 귀부인의 귀에 대고 뭐라고 속삭입니다.', `FemaleText_loc4`='%s在奥莉菲洛丝夫人的耳边轻声说着什么。', `FemaleText_loc5`='%s在妲姆的耳邊說悄悄話。', `FemaleText_loc7`='%s susurra algo al oído a la Dama.' WHERE `ID`=13361;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 조언자에게 알았다고 고개를 끄덕입니다.', `FemaleText_loc4`='%s点着头，表示她同意顾问说的话。', `FemaleText_loc5`='%s對她的諫言者要說的話點點頭表示贊同。', `FemaleText_loc7`='%s asiente con la cabeza a lo que su consejera tiene que decir.' WHERE `ID`=13362;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='발윈이 뭐라고 속삭였는지는 몰라도 %s|1은;는; 동의하지 않습니다.', `FemaleText_loc4`='%s不同意瓦尔文悄悄跟她说的事情。', `FemaleText_loc5`='%s不同意法溫在她耳邊說的話。', `FemaleText_loc7`='%s no está de acuerdo con lo que Valwyn le ha susurrado.' WHERE `ID`=13363;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='조언자가 귓속말로 무슨 말을 했는지 모르지만 %s|1이;가; 몹시 당황합니다.', `FemaleText_loc4`='%s看上去对她的顾问所说的话感到迷惑。', `FemaleText_loc5`='%s對她的諫言者在耳邊呢喃的話顯得不知所措。', `FemaleText_loc7`='%s parece confusa por lo que le han susurrado al oído.' WHERE `ID`=13365;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 고개를 돌려 조언자 발윈을 유혹하는 듯 한쪽 눈을 깜박거립니다.', `MaleText_loc4`='%s转向顾问瓦尔文，对着她的方向挑逗地眨了眨眼。', `MaleText_loc5`='%s轉向諫言者法溫並朝她的方向猥褻地眨眨眼。', `MaleText_loc7`='%s se da la vuelta hacia la consejera Valwyn y le hace un guiño lascivo.' WHERE `ID`=13366;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 죽음추적자의 장난에 넌더리가 난 것 같습니다.', `FemaleText_loc4`='%s对亡灵哨兵露出恶心的表情。', `FemaleText_loc5`='%s對亡靈哨兵的調情看起來很厭煩。', `FemaleText_loc7`='%s mira con asco los flirteos del mortacechador.' WHERE `ID`=13367;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 미친 듯이 웃으면서 양손으로 두 가지 혼합물을 섞습니다.', `MaleText_loc4`='%s开始狂笑，然后把手中的两种液体混合起来。', `MaleText_loc5`='%s當他將兩種混合物在手裡結合後發狂地咯咯笑著。', `MaleText_loc7`='%s se ríe como un maníaco mientras combina las dos mezclas en su mano.' WHERE `ID`=13368;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제기랄! 피엉겅퀴에서 추출한 이 성분은 내 독과 잘 섞이지 않는군. 하지만, 절대 포기 안 해. 트롤들을 혼내주고 말 거야! 흠, 다른 혼합물이면 되지 않을까?', `MaleText_loc4`='该死的！这些血蓟看上去没法完美地与我的毒液混合。我不会就此停止的，那些巨魔们一定会被解决掉的！也许需要换一种混合方式？', `MaleText_loc5`='可惡!這個血薊萃取物似乎無法和我的毒藥混合在一起。但這嚇不倒我 - 我還是會對付那些食人妖的!或許嘗試不同的混合物?', `MaleText_loc7`='¡Drat! Este extracto de cardo de sangre no parece querer combinarse adecuadamente con mi veneno. No me desalentaré – ¡hay que ocuparse de esos trols! ¿Quizás una mezcla diferente?' WHERE `ID`=13369;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 군대는 무기를 사용하여 무력으로 적을 공격하지만 그런 공격이 얼마나 효과적인지는 의문이오. 기껏해야 기분전환 정도지. 적을 효과적으로 무너뜨리고 우리 앞에 무릎 꿇게 하는 것은 바로 마법의 힘이라오.', `MaleText_loc4`='当我们军队中的士兵用武器砍向敌人时，这样的进攻到底具有多大的果，这是值得怀疑的——最多也只不过是一个牵制而已。如果使用奥术魔法的话，那么我们的敌人就会轻而易举地被我们粉碎。', `MaleText_loc5`='當我們軍隊的士兵將他們的刀劍殺向我們的敵人，這樣攻擊的真正效用是值得懷疑的 - 頂多是種分散注意力的方法。只有透過秘法我們的敵人才會在我們面前崩潰並倒下。', `MaleText_loc7`='Aunque los soldados de nuestro ejército usen el acero contra nuestros enemigos, la eficacia real de tales ataques es cuestionable – una distracción, en el mejor de los casos. Es a través de lo Arcano que nuestros enemigos se desmoronarán y caerán ante nosotros.' WHERE `ID`=13370;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 잘 보고 배우시오. 훈련과 연습만으로 여러분도 이런 결과를 낼 수 있소이다.', `MaleText_loc4`='好好看着，学生们。只有通过训练和实践，才能达到这样的结果。', `MaleText_loc5`='好好看著學起來，學生們。只有透過戒律和練習你們才能達到這樣的成果。', `MaleText_loc7`='Observad y aprended, alumnos. Solo con disciplina y práctica alcanzaréis tales resultados.' WHERE `ID`=13371;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감독관이 죽었다! 넝마두건 친구들, 서두르게! 도망쳐!', `MaleText_loc4`='工头死了！兄弟们，快跑啊！', `MaleText_loc5`='監工死了!快，崔互德!跑!', `MaleText_loc7`='¡El capataz está muerto! ¡Rápido, Zarrapuchas! ¡Corred!' WHERE `ID`=13372;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달아나! 뛰어!', `MaleText_loc4`='逃啊！逃啊！', `MaleText_loc5`='逃跑!逃跑!', `MaleText_loc7`='¡Huid! ¡Huid!' WHERE `ID`=13373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기회야! 도망쳐!', `MaleText_loc4`='这是我们唯一的机会！跑吧！', `MaleText_loc5`='這是我們的機會!奔向它!', `MaleText_loc7`='¡Esta es nuestra oportunidad! ¡A correr!' WHERE `ID`=13374;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 본 것은 일반적인 화염구요.', `MaleText_loc4`='这是你所学习的标准火球术。', `MaleText_loc5`='這是你的標準火球。', `MaleText_loc7`='Esta es tu bola de Fuego estándar.' WHERE `ID`=13375;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 냉기 마법을 사용해 적의 뼈를 얼리고 행동을 느리게 할 수 있소이다.', `MaleText_loc4`='我们用冰霜来冻结他们的骨头，还可以暂停他们的移动。', `MaleText_loc5`='我們使用冰霜來冷凍他們的骨頭並讓他們動彈不得。', `MaleText_loc7`='Usamos escarcha para congelar sus huesos y detener su movimiento.' WHERE `ID`=13376;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대상이 여럿일 때는 광역 마법의 일종인 눈보라를 일으켜 적의 머리 위에 내리게 하시오.', `MaleText_loc4`='对于多个目标，往他们的头上扔暴风雪。', `MaleText_loc5`='若要對付多個目標，就讓他們的頭頂來個暴風雪吧。', `MaleText_loc7`='Para objetivos múltiples, forma una ventisca sobre sus cabezas.' WHERE `ID`=13377;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마지막은 불덩이 작렬인데 강력한 화염 마법의 일종이오. 이 마법은 강한 첫인상을 확실하게 남겨야 할 때 사용하시오.', `MaleText_loc4`='最后，我们还有变羊术。当你想要给敌人留下持久的第一印象时，用它就对了。', `MaleText_loc5`='最後，但不是最不重要的，我們有炎爆術。這是當你百分之百確定想留下一個持永的第一印象時用的。', `MaleText_loc7`='Por último, pero, sin duda, no menos importante, tenemos la piroexplosión. Esta es para cuando se quiere causar una primera impresión absoluta y completamente duradera.' WHERE `ID`=13378;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무 데도 못 간다, 벌레 같은 녀석!', `MaleText_loc4`='你们这些虫子，哪儿都别想去！', `MaleText_loc5`='你哪裡也去不了懦夫!', `MaleText_loc7`='¡No iréis a ninguna parte, gusanos!' WHERE `ID`=13379;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='즉시 돌아와라. 그렇지 않으면 주인님의 분노를 살 것이다!', `MaleText_loc4`='马上回来，否则有你们好瞧的！', `MaleText_loc5`='立刻回來否則就嚐嚐大師的憤怒!', `MaleText_loc7`='¡Vuelve de inmediato o sufre la ira del maestro!' WHERE `ID`=13380;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='즉시 돌아오지 않으면 제발 죽여달라고 애원하게 해주마!', `MaleText_loc4`='如果你们不立即回来，就准备受死吧！', `MaleText_loc5`='如果你不立刻回來，你很快就會求我賜你一死，卑鄙的人!', `MaleText_loc7`='¡Pronto suplicaréis que os mate si no volvéis enseguida, miserables!' WHERE `ID`=13381;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기요! 이리로 와서 이 우리에서 절 좀 꺼내주세요.', `FemaleText_loc4`='嘿！你能不能帮我从这笼子里逃出来？', `FemaleText_loc5`='嘿!你可以過來把我從這籠子裡弄出去嗎?', `FemaleText_loc7`='¡Eh! ¿Podrías venir y sacarme de esta jaula?' WHERE `ID`=13382;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='살려주세요!', `FemaleText_loc4`='救命啊！！！', `FemaleText_loc5`='救命!!!', `FemaleText_loc7`='¡¡¡SOCORRO!!!' WHERE `ID`=13383;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저를 여기서 구해주면 분명 보상이 따를 것입니다!', `FemaleText_loc4`='带我离开这里，我保证会奖励你的！', `FemaleText_loc5`='把我弄出去，我保證那裡面會有一個獎勵給你!', `FemaleText_loc7`='¡Sácame de aquí y te garantizo que habrá una recompensa para ti!' WHERE `ID`=13384;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='서두르세요. 저 트롤들을 모두 해치운 다음 절 여기서 꺼내주세요!', `FemaleText_loc4`='快点，杀了这些巨魔，让我离开这东西！', `FemaleText_loc5`='快，殺死全部的食人妖再把我從這東西裡放出去!', `FemaleText_loc7`='¡Rápido, mata a todos esos trols y déjame salir de esta cosa!' WHERE `ID`=13385;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='절 구해주시면 섭섭지 않게 보상해 드리겠어요!', `FemaleText_loc4`='如果你让我出去，我保证你不会后悔的！', `FemaleText_loc5`='如果你讓我出去我保證你不會後悔的!', `FemaleText_loc7`='¡Si me liberas, te prometo que no te arrepentirás!' WHERE `ID`=13386;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좀 서둘러 주세요. 트롤들이 저를 제물로 바칠 준비를 하고 있어요!', `FemaleText_loc4`='如果你不介意的话，加快点速度可以吗？我想他们已经准备把我献祭掉了！', `FemaleText_loc5`='你動作可以快一點嗎?我想他們已經準備好要犧牲我了!', `FemaleText_loc7`='¿Te importa darte prisa? ¡Creo que se están preparando para sacrificarme!' WHERE `ID`=13387;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 순례자가 도착했소이다! 빨리 물을 가져오시오. 아니면 그녀가 죽을지도 모르오!', `MaleText_loc4`='又一个朝圣者到了！快点把水拿来，否则她就要死了！', `MaleText_loc5`='另一個朝聖者來了!快點把水拿來，否則她就要死了!', `MaleText_loc7`='¡Ha llegado otra peregrina! ¡Traed agua o podríamos perderla!' WHERE `ID`=13388;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무슨 소리 못 들으셨습니까?', `FemaleText_loc4`='你听到了什么？', `FemaleText_loc5`='你有聽到什麼嗎，$n?', `FemaleText_loc7`='¿Oyes algo?' WHERE `ID`=13389;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='간신히 여기까지 왔네요. 예언자이신 레굴쿠트 님께서 경고했지만 제 부주의 때문에 결국 이런 꼴이 되었군요.$B$B저는 제스고르의 폐허를 연구하고자 이곳에 들렀다가 이동하는 도중 불타는 군단과 맞닥뜨렸답니다. 그 덕에 이제는 연구는커녕 다리에 깊은 상처만 남았군요.', `MaleText_loc4`='是我把自己弄成这般田地的。先知雷古库特曾想警告我，但是粗心最终让我变成了这样。$B$B我是来这里研究塞斯高废墟的，但是在路上与燃烧军团发生了冲突。现在，我能给你们看的就只有腿上那道化脓的伤口。', `MaleText_loc5`='我讓我自己成了一個笑柄。先知瑞卡酷試著警告我，但我的粗心最後還是讓我哉了個跟斗。$B$B我來這裡研究薩斯葛爾廢墟，但卻在路上與燃燒軍團發生衝突。現在，我所有的一切就是腿上一個討厭的傷口。', `MaleText_loc7`='Me he metido en una buena. La clarividente Regulkult intentó avisarme, pero mi descuido ha terminado por pasarme factura.$B$BBajé aquí para analizar las ruinas de Zeth''Gor, pero me impliqué con la Legión en mi camino. Ahora todo lo que he logrado es una herida profunda en la pierna.' WHERE `ID`=13390;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='젊은 $c|1이여;여;, $g형제:자매;에게 가르쳐드릴 수는 없지만 축복을 드리지요. 빛의 길로 당당하게 나아가십시오!$B$B더 무엇이 필요하겠습니까?', `MaleText_loc4`='虽然我不能训练你，年轻的$c，但我可以给你我的祝福。在圣光中大胆地前进吧！$B$B还有别的事情吗？', `MaleText_loc5`='雖然我無法提供你訓練，年輕的$c，但我可以給你我的祝福。勇敢地走進聖光裡!$B$B還有別的事嗎?', `MaleText_loc7`='Aunque no puedo ofrecerte instrucción, joven $c, puedo darte mi bendición. ¡Camina con valentía hacia la Luz!$B$B¿Hay algo más?', `FemaleText_loc1`='젊은 $c|1이여;여;, $g형제:자매;에게 가르쳐드릴 수는 없지만 축복을 드리지요. 빛의 길로 당당하게 나아가십시오!$B$B더 무엇이 필요하겠습니까?', `FemaleText_loc4`='虽然我不能训练你，年轻的$c，但我可以给你我的祝福。在圣光中大胆地前进吧！$B$B还有别的事情吗？', `FemaleText_loc5`='雖然我無法提供你訓練，年輕的$c，但我可以給你我的祝福。勇敢地走進聖光裡!$B$B還有別的事嗎?', `FemaleText_loc7`='Aunque no puedo ofrecerte instrucción, joven $c, puedo darte mi bendición. ¡Camina con valentía hacia la Luz!$B$B¿Hay algo más?' WHERE `ID`=13391;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나이트 엘프가 무슨 일을 꾸미고 있는지 알아내는 일은 무척 중요하오! 전력을 다해 그들의 목적을 알아내 주시오.', `FemaleText_loc4`='明确暗夜精灵的意图对我们来说是非常重要的，$c！请为了这个目标努力吧。', `FemaleText_loc5`='找出夜精靈在忙些什麼事對我們而言相當重要，$c! 請集中你們的精神直到找到結果。', `FemaleText_loc7`='¡Es muy importante que averigüemos qué traman los elfos de la noche, $c! Centra todos tus esfuerzos en ese objetivo.' WHERE `ID`=13392;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에서는 오래전 무시무시한 전투가 벌어졌습니다. 우리 네더가드와 은빛 여명회가 어둠의 문에서 끊임없이 밀어닥치는 악마들을 막아 냈습니다.$B$B피와 절망으로 얼룩진 진정 어두운 나날들이었지요...$B$B하지만, 아제로스의 왕국들이 가담했고 그 괴물들을 물리칠 수 있었습니다! 그런데 이제 전투는 반대편에서 벌어지고 있군요...$B$B이제 이곳은 고요하지만 저 지옥 같은 문 너머에 벌어지는 끔찍한 광경과는 너무 대조적이라서 두렵기까지 하답니다.', `MaleText_loc4`='不久之前，这个地方发生了一场可怕的战斗，我们守望堡和银色黎明在黑暗之门涌出的恶魔们无情的冲击下，几乎要全线崩溃。$B$B在那段黑暗的日子里，充满了流血和绝望……$B$B但是，艾泽拉斯各国很快就赶来支援，把那些恶魔赶了回去！战斗还在黑暗之门的另一边持续着……$B$B这座营地目前恢复了平静，但是我担心这里的宁静掩饰了黑暗之门另一边的疯狂。', `MaleText_loc5`='就在不久之前，此地才發生了一場慘烈的戰鬥。我們守望堡與銀色黎明抵抗著一波波從黑暗之門中湧出的惡魔。$B$B那些黑暗的日子，充滿的血腥與絕望...$b$b但是艾澤拉斯王國很快地加入我們，把那些怪物給逼退了!戰鬥持續在傳送門邊進行著...$b$b這個營地現在雖然很平靜，但我害怕此地的寧靜只是在掩飾著那座地獄之門後的狂暴。', `MaleText_loc7`='No hace mucho, en este sitio tuvo lugar una terrible batalla. Nosotros, Nethergarde, y El Alba Argenta mantuvimos a raya una oleada de demonios que surgieron del Portal Oscuro.$B$BAquellos eran días oscuros llenos de sangre y desesperación...$B$BPero los reinos de Azeroth se unieron a la batalla y conseguimos expulsar a los demonios. La lucha continúa del otro lado del Portal...$B$BEste campamento ahora es un lugar tranquilo; por desgracia, esa tranquilidad contrasta con los horrores que hay del otro lado.' WHERE `ID`=13393;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='트롤베인 혈족의 영웅담은 전설적이지요. 저는 한 남자를 숭배했습니다.$B$B그리고 이곳 아웃랜드에서 그가 살아있다는 것을 확인하고자...$B$B<당신 뒤쪽을 바라보는 로무스>$B$B그를 처음 만났을 때 저는 거의 기절할 뻔했지요. 엄청난 충격이 아닐 수 없었습니다. 그의 앞에 무릎을 꿇었을 때 저는 눈물을 삼켜야만 했습니다.$B$B로서의 후예들을 무사히 지킬 수만 있다면 제가 할 수 있는 것은 뭐든지 할 겁니다.', `MaleText_loc4`='托尔贝恩家族的英雄事迹就像传说一样，我非常崇拜他。$B$B当我来到外域之后……我发现他还活着。$B$B<洛姆斯凝视着你的身后。>$B$B当我第一次看到他的时候，我几乎晕倒了。那种震撼是无可抵挡的，我跪在他的面前，泪水几乎要奔涌而出。$B$B我发誓会尽我的全力来保卫洛萨之子的安全。', `MaleText_loc5`='英勇的托爾貝恩血統具有傳奇性。我崇拜他。$B$B找到他時要是活著的，就在外域...$b$b<洛摩斯注視著你經過。>$B$B當我第一次看到他時，我幾乎昏厥過去。難以阻擋的震驚力。當我跪在他面前，我必需勇敢面對。$B$B你能確信在我盡我能力完成某些事之後，洛薩之子能安全無虞。', `MaleText_loc7`='Las heroicidades de la estirpe de los Aterratrols son legendarias. Idolatro a ese hombre.$B$BY, encontrarlo vivo, en Terrallende...$B$B<Romus mira fijamente más allá de ti.>$B$BCuando lo vi por primera vez, casi me desmayé. La conmoción fue insoportable. Mientras me arrodillaba ante él, tuve que reprimir las lágrimas.$B$BPuedes apostar tu dulce trasero a que voy a hacer todo lo que esté en mi poder para asegurarme de que los Hijos de Lothar se mantienen a salvo.' WHERE `ID`=13394;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로무스가 내 아름다운 도시에 비극적인 사건이 벌어졌다는 소식을 전해 주었네. 로데론과 내가 아끼던 스트롬가드에 어떤 일이 벌어졌는지 들었을 때 내가 느낀 슬픔은 그 어떤 말로도 표현할 수가 없다네.$B$B20년 전만 해도 ''불타는 군단''에 대해 들어 본 사람은 아무도 없었지... 빌어먹을 악마들, 저주를 받아 마땅해!$B하지만, 너무 걱정하지 말게, $n. 내가 아제로스로 돌아가면 스트롬가드는 다시 한 번 심판의 성지로 우뚝 설 것이네. 내 맹세하지...', `MaleText_loc4`='洛姆斯把我的美丽城市所遭遇的悲剧告诉了我。在我听到了洛丹伦的命运……还有我所深爱的激流堡的命运之后，我找不出什么合适的语言来形容我的悲伤。$B$B二十年前，没人听说过“燃烧军团”……那些该死的恶魔！$B好好休息，$n。等到我再回到艾泽拉斯去的时候，我发誓，激流堡将再次崛起！', `MaleText_loc5`='洛摩斯通知我圍攻我美麗激流堡的噩耗。沒有任何適切的言語能訴說我聽聞羅德隆命運時的悲傷 - 以及我至愛的激流堡的命運。$B$B二十年前，根本沒有人聽過『燃燒軍團』...那些天殺該受詛咒的惡魔!$B$B盡量休息吧， $n; 要是我回到艾澤拉斯，激流堡將再次起義反戰。我發誓...', `MaleText_loc7`='Romus me ha informado de la tragedia que sufrió mi hermosa ciudad. No hay palabras que describan la pena que sentí cuando supe lo que le había ocurrido a Lordaeron y a mi amada Stromgarde.$B$BHace veinte años, nadie había oído hablar de la Legión Ardiente... ¡Malditos demonios!$BTe lo aseguro, $n; si algún día vuelvo a Azeroth, haré que Stromgarde recupere toda su antigua gloria. Lo juro...' WHERE `ID`=13395;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너희의 불순함을 반드시 정화하겠다.', `FemaleText_loc4`='你们必须得到净化。', `FemaleText_loc5`='你的不潔必須被淨化。', `FemaleText_loc7`='Su falta de pudor debe purificarse.' WHERE `ID`=13396;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이... 이런... 암흑의... 기운이! 어떻게 이런 일이?', `FemaleText_loc4`='这么……黑暗的……能量！这怎么可能？', `FemaleText_loc5`='如此...邪惡的...力量!這怎麼可能?', `FemaleText_loc7`='¡Una energía... tan... oscura! ¿Cómo es posible?' WHERE `ID`=13397;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐! 어딜 그렇게 몰래 가십니까?', `MaleText_loc4`='嘿！你想干什么，就像那样躲来躲去吗？', `MaleText_loc5`='嗨!你想要去那裡，像這樣偷偷摸摸的嗎?', `MaleText_loc7`='¡Eh! ¿Dónde crees que vas, escabulléndote de esa manera?', `FemaleText_loc1`='이봐! 어딜 그렇게 몰래 가시나요?', `FemaleText_loc4`='嘿！你想干什么，就像那样躲来躲去吗？', `FemaleText_loc5`='嗨!你想要去那裡，像這樣偷偷摸摸的嗎?', `FemaleText_loc7`='¡Eh! ¿Dónde crees que vas, escabulléndote de esa manera?' WHERE `ID`=13398;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐요, 초대장도 없이 몰래 들어가려는 겁니까?', `MaleText_loc4`='对不起，你是不是想偷偷溜进去？', `MaleText_loc5`='對不起，你想在沒有受邀的情況下試著偷溜嗎?', `MaleText_loc7`='Perdona, pero ¿estabas intentando colarte sin invitación?', `FemaleText_loc1`='이보세요, 초대장도 없이 몰래 들어가려는 거예요?', `FemaleText_loc4`='对不起，你是不是想偷偷溜进去？', `FemaleText_loc5`='對不起，你想在沒有受邀的情況下試著偷溜嗎?', `FemaleText_loc7`='Perdona, pero ¿estabas intentando colarte sin invitación?' WHERE `ID`=13399;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 너 역시 주인님을 섬겨야 할 것이다!', `MaleText_loc4`='$n，你也会为主人效力的！', `MaleText_loc5`='$n，你也將為主人服務!', `MaleText_loc7`='$n, ¡tú también servirás al Maestro!', `FemaleText_loc1`='$n, 너 역시 주인님을 섬겨야 할 것이다!', `FemaleText_loc4`='$n，你也会为主人效力的！', `FemaleText_loc5`='$n，你也將為主人服務!', `FemaleText_loc7`='$n, ¡tú también servirás al Maestro!' WHERE `ID`=13400;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님께 충성을 맹세하라. 그러면 목숨은 건질 수 있을 것이다!', `MaleText_loc4`='对主人表示你的忠诚吧，$g先生:女士;，你的生命将得到宽恕！', `MaleText_loc5`='向主人保證你的忠誠，$g先生:女士;，你的人生將得到寬恕!', `MaleText_loc7`='¡Jure lealtad al Maestro, $gseñor:señora;, y se le perdonará la vida!', `FemaleText_loc1`='주인님께 충성을 맹세하라. 그러면 목숨은 건질 수 있을 것이다!', `FemaleText_loc4`='对主人表示你的忠诚吧，$g先生:女士;，你的生命将得到宽恕！', `FemaleText_loc5`='向主人保證你的忠誠，$g先生:女士;，你的人生將得到寬恕!', `FemaleText_loc7`='¡Jure lealtad al Maestro, $gseñor:señora;, y se le perdonará la vida!' WHERE `ID`=13401;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 영사기 때문에 미치겠습니다! 영사기를 고치는 데 필요한 부품이 하나도 없거든요.', `FemaleText_loc4`='我快抓狂了！所有可以用来修理这台发射器的零件，一件都没有！', `FemaleText_loc5`='這個發射體讓我陷入困難!我缺少修復它的所有零件。', `FemaleText_loc7`='¡Este emisor me está volviendo loca! Me falta todo tipo de piezas que necesito para repararlo.' WHERE `ID`=13402;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n! 도와주셔서 감사합니다!', `FemaleText_loc4`='$n！再次感谢你的帮助。', `FemaleText_loc5`='$n! 再次應謝你的所有協助。', `FemaleText_loc7`='¡$n! ¡Gracias de nuevo por toda tu ayuda.' WHERE `ID`=13403;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아직 수리가 끝나지 않았어요. 하지만, 오래 걸리지는 않을 거예요.', `FemaleText_loc4`='不，还没完全修好。但估计不会太久了。', `FemaleText_loc5`='不，還是不要完成這部份的修復。雖然不會太久。', `FemaleText_loc7`='No, todavía no he terminado con esas reparaciones. Pero no debería faltar mucho.' WHERE `ID`=13404;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 토템의 힘을 흡수하여 대마법의 파동 형태로 변환합니다.', `MaleText_loc4`='%s吸取了图腾的能量，并将其转化为一股反魔法脉冲！', `MaleText_loc5`='%s吸取圖騰的能量並以反魔法脈衝的形式釋放出來。', `MaleText_loc7`='%s absorbe la energía del tótem y la redirige como un pulso antimagia.' WHERE `ID`=13405;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 지혜의 축복을 흡수하여 대마법의 파동으로 변환합니다.', `MaleText_loc4`='%s吸取了智慧祝福的能量，并将其转化为一股反魔法脉冲。', `MaleText_loc5`='%s吸取智慧祝福的能量並以反魔法脈衝的形式釋放出來。', `MaleText_loc7`='%s absorbe la energía de la bendición de sabiduría y la redirige como pulso antimagia.' WHERE `ID`=13406;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 이런! 여기는 어디인가요? 무슨 일이 벌어진 겁니까? 저기... 비행선의 파편이군요!', `MaleText_loc4`='天啊！我在哪里？发生了什么事？看，那是飞船的一部分！', `MaleText_loc5`='喔不!我們在那裡?發生什麼事了?你看，那是船的碎片!', `MaleText_loc7`='¡Oh, no! ¿Dónde estamos? ¿Qué ha ocurrido? ¡Mira, ahí hay parte de la nave!', `FemaleText_loc1`='아, 이런! 여기는 어디인가요? 무슨 일이 벌어진 겁니까? 저기... 비행선의 파편이군요!', `FemaleText_loc4`='天啊！我在哪里？发生了什么事？看，那是飞船的一部分！', `FemaleText_loc5`='喔不!我們在那裡?發生什麼事了?你看，那是船的碎片!', `FemaleText_loc7`='¡Oh, no! ¿Dónde estamos? ¿Qué ha ocurrido? ¡Mira, ahí hay parte de la nave!' WHERE `ID`=13407;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비행선이 추락하면서 우리는 비상 탈출 장치를 가동했습니다. 그게 제 마지막 기억이죠. 가서 도울 일이 있는지 봐야겠군요. 감사합니다!', `MaleText_loc4`='我所能记得的最后一件事是飞船在下降，而我们都进入了救生舱。我去看看有什么我可以帮忙的。谢谢你！', `MaleText_loc5`='我記得的最後一件事是我們沉船了，然後進入了分離艙。我會去看看有什麼我能幫的忙。謝謝!', `MaleText_loc7`='Lo último que recuerdo es que la nave cayó y nos metimos en las vainas. Iré a ver cómo puedo ayudar. ¡Gracias!', `FemaleText_loc1`='비행선이 추락하면서 우리는 비상 탈출 장치를 가동했습니다. 그게 제 마지막 기억이죠. 가서 도울 일이 있는지 봐야겠군요. 감사합니다!', `FemaleText_loc4`='我所能记得的最后一件事是飞船在下降，而我们都进入了救生舱。我去看看有什么我可以帮忙的。谢谢你！', `FemaleText_loc5`='我記得的最後一件事是我們沉船了，然後進入了分離艙。我會去看看有什麼我能幫的忙。謝謝!', `FemaleText_loc7`='Lo último que recuerdo es que la nave cayó y nos metimos en las vainas. Iré a ver cómo puedo ayudar. ¡Gracias!' WHERE `ID`=13408;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기가 어딥니까? 당신은 누구죠? 아, 안돼! 비행선은 어떻게 됐나요?', `MaleText_loc4`='我在哪？你是谁？天啊！飞船怎么了？', `MaleText_loc5`='我在那裡?你是誰?喔不!這艘船發生什麼事了?', `MaleText_loc7`='¿Dónde estoy? ¿Quién eres? ¡Oh, no! ¿Qué le ha ocurrido a la nave?', `FemaleText_loc1`='여기가 어딥니까? 당신은 누구죠? 아, 안돼! 비행선은 어떻게 됐나요?', `FemaleText_loc4`='我在哪？你是谁？天啊！飞船怎么了？', `FemaleText_loc5`='我在那裡?你是誰?喔不!這艘船發生什麼事了?', `FemaleText_loc7`='¿Dónde estoy? ¿Quién eres? ¡Oh, no! ¿Qué le ha ocurrido a la nave?' WHERE `ID`=13409;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으... 여기가 어딥니까? 저기 남아 있는 부분이 비행선의 전부입니까?', `MaleText_loc4`='啊……这里是哪？飞船就只剩下这点了？', `MaleText_loc5`='呃...這是什麼地方?那是船隻所遺留的地方嗎?', `MaleText_loc7`='Eh... ¿Qué lugar es este? ¿Es esto todo lo que queda de aquella nave?', `FemaleText_loc1`='으... 여기가 어딥니까? 저기 남아 있는 부분이 비행선의 전부입니까?', `FemaleText_loc4`='啊……这里是哪？飞船就只剩下这点了？', `FemaleText_loc5`='呃...這是什麼地方?那是船隻所遺留的地方嗎?', `FemaleText_loc7`='Eh... ¿Qué lugar es este? ¿Es esto todo lo que queda de aquella nave?' WHERE `ID`=13410;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으으으... 너무 아파. 좀 도와주시겠소?', `MaleText_loc4`='啊啊啊……疼死我了。你可以帮帮我吗？', `MaleText_loc5`='噢...我受傷了。你有治療水晶嗎?', `MaleText_loc7`='Ayyy... me duele. ¿Puedes ayudarme?', `FemaleText_loc1`='으으으... 너무 아파. 좀 도와주시겠소?', `FemaleText_loc4`='啊啊啊……疼死我了。你可以帮帮我吗？', `FemaleText_loc5`='噢...我受傷了。你有治療水晶嗎?', `FemaleText_loc7`='Ayyy... me duele. ¿Puedes ayudarme?' WHERE `ID`=13411;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으, 안 아픈 곳이 없군요. 좀 도와주시겠습니까?', `MaleText_loc4`='啊，我全身都好疼，你可以帮帮我吗？', `MaleText_loc5`='噢，我渾身是傷。你有治療水晶可以治療我嗎?', `MaleText_loc7`='Ay, me duele todo. ¿Me puedes ayudar?', `FemaleText_loc1`='으, 안 아픈 곳이 없군요. 좀 도와주시겠어요?', `FemaleText_loc4`='啊，我全身都好疼，你可以帮帮我吗？', `FemaleText_loc5`='噢，我渾身是傷。你有治療水晶可以治療我嗎?', `FemaleText_loc7`='Ay, me duele todo. ¿Me puedes ayudar?' WHERE `ID`=13412;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<흐느껴 울며> 저는 무덤이 싫습니다. 많은 동료가 죽었습니다. 사랑하는 루하나도...', `MaleText_loc4`='<哭泣> 我讨厌墓地。太多人死去了。还有我亲爱的鲁哈娜……', `MaleText_loc5`='<啜泣>我恨墓地。這麼多死亡。還有我的寶貝露荷娜...', `MaleText_loc7`='<Sollozando> Odio los cementerios. Hay muchos muertos. Y mi dulce Luhanaa...' WHERE `ID`=13413;
