UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 앞에 있는 묘비를 조용히 바라봅니다.', `MaleText_loc4`='%s默默地凝视着他面前的墓碑。', `MaleText_loc5`='%s沉默地凝視著在他面前的墓碑。', `MaleText_loc7`='%s mira fijamente en silencio la lápida que hay ante él.' WHERE `ID`=13415;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 갑자기 큰 소리로 엉엉 웁니다.', `MaleText_loc4`='%s悲痛地放声大哭。', `MaleText_loc5`='%s發出巨大，痛苦的啜泣聲。', `MaleText_loc7`='%s estalla en enormes y angustiosos sollozos.' WHERE `ID`=13416;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 완전히 지친 듯 고개를 숙이고 한숨을 쉽니다.', `MaleText_loc4`='%s低下了头叹了口气，非常疲倦的样子。', `MaleText_loc5`='%s低著頭嘆氣，精疲力盡。', `MaleText_loc7`='%s inclina la cabeza y suspira, visiblemente sin aliento.' WHERE `ID`=13417;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 내게서 루하나를 앗아간 겁니까? 왜?!', `MaleText_loc4`='为什么，鲁哈娜？为什么？！', `MaleText_loc5`='為什麼，露荷娜?為什麼?!', `MaleText_loc7`='¿Por qué, Luhanaa? ¡¿Por qué?!' WHERE `ID`=13418;
