UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신을 절대 잊지 못할 거요, 내 사랑.', `MaleText_loc4`='我永远都不会忘记你，我的爱人。', `MaleText_loc5`='我永遠不會忘記你，我的愛人。', `MaleText_loc7`='Nunca te olvidaré, cariño.' WHERE `ID`=13420;
