UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 너무나 보고 싶구려!', `MaleText_loc4`='我非常想念你！', `MaleText_loc5`='我非常想念你!', `MaleText_loc7`='¡Te echo tanto de menos!' WHERE `ID`=13422;
