UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 언제나 여기에, 나와 함께 있을 거요.', `MaleText_loc4`='你会一直在我身边的。', `MaleText_loc5`='你將永遠在這裡，與我一起。', `MaleText_loc7`='Siempre estarás aquí conmigo.' WHERE `ID`=13424;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='평화롭게 잠드시오, 루하나... 내 사랑.', `MaleText_loc4`='安息吧，我的爱，我的心，我的鲁哈娜。', `MaleText_loc5`='保持平靜，我親愛的，寶貝，露荷娜。', `MaleText_loc7`='Sé en paz, mi dulce, dulce Luhanaa.' WHERE `ID`=13425;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희는 이 계곡을 벗어나지 못한다!', `MaleText_loc4`='我们不会让你离开这个山谷的！', `MaleText_loc5`='我們不會讓你離開這個村子!', `MaleText_loc7`='¡No te permitiremos salir de este valle!', `FemaleText_loc1`='너희는 이 계곡을 벗어나지 못한다!', `FemaleText_loc4`='我们不会让你离开这个山谷的！', `FemaleText_loc5`='我們不會讓你離開這個村子!', `FemaleText_loc7`='¡No te permitiremos salir de este valle!' WHERE `ID`=13426;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='추락에서 살아남아 찾아온 곳이 네 무덤이 될 자리라니. 정말 불쌍하군.', `MaleText_loc4`='真可惜，你在坠毁中生还，却要死在这里。', `MaleText_loc5`='真可惜你在墜機後存活，卻要在這裡死掉。', `MaleText_loc7`='Qué lástima que sobrevivieras al accidente para morir aquí.', `FemaleText_loc1`='추락에서 살아남아 찾아온 곳이 네 무덤이 될 자리라니. 정말 불쌍하군.', `FemaleText_loc4`='真可惜，你在坠毁中生还，却要死在这里。', `FemaleText_loc5`='真可惜你在撞擊後存活，卻要在這裡死掉。', `FemaleText_loc7`='Qué lástima que sobrevivieras al accidente para morir aquí.' WHERE `ID`=13427;
