UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무도 이 계곡을 살아서 벗어나지 못한다.', `MaleText_loc4`='你们都别想活着离开这个山谷。', `MaleText_loc5`='你們都將無法活著離開這個山谷。', `MaleText_loc7`='Ninguno de ustedes saldrá de este valle con vida.', `FemaleText_loc1`='아무도 이 계곡을 살아서 벗어나지 못한다.', `FemaleText_loc4`='你们都别想活着离开这个山谷。', `FemaleText_loc5`='你們都將無法活著離開這個山谷。', `FemaleText_loc7`='Ninguno de ustedes saldrá vivo de este valle.' WHERE `ID`=13429;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 마치 무언가를 듣는 것처럼 하늘을 향해 고개를 치켜듭니다.', `MaleText_loc4`='%s抬起头，似乎在听着什么东西。', `MaleText_loc5`='%s抬起頭，就像在聆聽什麼事一樣。', `MaleText_loc7`='%s levanta la cabeza, como si oyera algo.' WHERE `ID`=13430;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하이브아쉬 근처의 땅속에서 거대한 벌레 같은 생명체가 튀어나왔습니다!', `MaleText_loc4`='一只巨大的虫形生物突然从亚什虫巢附近的土地中钻了出来！', `MaleText_loc5`='一隻像蟲一樣的巨大生物剛從亞什蟲巢附近的地表爆發出來!', `MaleText_loc7`='¡Una criatura enorme tipo gusano acaba de salir de la tierra cerca de Colmen''Ashi!' WHERE `ID`=13431;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기 하이브레갈 근처를 좀 보십시오! 저건... 미늘벌레!', `MaleText_loc4`='看那儿！雷戈虫巢那儿！那是……沙虫吗？！', `MaleText_loc5`='看哪，在那裡!在雷戈蟲巢旁!那是...沙蟲嗎?!', `MaleText_loc7`='¡Mira, allí! ¡Al lado de Colmen''Regal! Eso es... ¿un gusano de arena?' WHERE `ID`=13432;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경계를 늦추지 마십시오! 하이브조라에 거대한 벌레가 접근했다는 보고입니다!', `MaleText_loc4`='保持警惕！报告说佐拉虫巢附近有巨大的沙虫出没！', `MaleText_loc5`='留心一點!據報有巨大的蟲體接近佐拉蟲巢!', `MaleText_loc7`='¡Atención! ¡Tenemos noticias de un gusano humungoso cerca de Colmen''Zora!' WHERE `ID`=13433;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마파람 마을 근처에서 뭔가 꿈틀거리고 있습니다! 저건... 미늘벌레의 일종이군요! 모두 조심하십시오!', `MaleText_loc4`='南风村附近似乎有什么生物蠢蠢欲动！是……是沙虫！保持警惕！', `MaleText_loc5`='南風村有些騷動!是...是一隻沙蟲!小心!', `MaleText_loc7`='Algo pasa cerca de Aldea del Viento del Sur. Parece ser uno de esos gusanos de arena. ¡Mira!' WHERE `ID`=13434;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 주인님의 포도주를 쏟게 하다니!', `MaleText_loc4`='你竟然敢洒出主人的酒！', `MaleText_loc5`='你膽敢濺出主人的酒!', `MaleText_loc7`='¿Cómo te atreves a derramar el vino del maestro?', `FemaleText_loc1`='감히 주인님의 포도주를 쏟게 하다니!', `FemaleText_loc4`='你竟然敢洒出主人的酒！', `FemaleText_loc5`='你膽敢濺出主人的酒!', `FemaleText_loc7`='¿Cómo te atreves a derramar el vino del maestro?' WHERE `ID`=13435;
