UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 산을 넘어 북쪽까지 울리는 긴 소리를 내고는 따라오라는 듯 꼬리를 흔듭니다.', `MaleText_loc4`='%s发出的嚎叫在北边的山脉中回响，提醒你跟着它。', `MaleText_loc5`='%s大聲嚎叫，環繞越過山岳到達北方，並示意你跟隨。', `MaleText_loc7`='%s deja escapar un aullido que atraviesa las montañas al norte y te hace seguirlo.' WHERE `ID`=13446;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아브루의 마법이 깨졌구나! 내가 다시 자유를 찾았다!', `MaleText_loc4`='亚维鲁的魔法失效了！我又自由了！', `MaleText_loc5`='艾芙魯的魔法已經失敗了!我又再次重獲自由!', `MaleText_loc7`='¡El hechizo de Avruu se ha roto! ¡Vuelvo a ser libre!' WHERE `ID`=13447;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아브루의 마법이... 아직도 날 조종하고 있다. 너는 나와 싸워야 한다, 필멸의 존재여. 그것만이 마법을 깰 수 있는 유일한 방법이다!', `MaleText_loc4`='亚维鲁的魔法……仍然控制着我。你必须与我战斗，凡人。这是唯一可以解除那个魔法的办法！', `MaleText_loc5`='艾芙魯的魔法...仍然控制著我。你必須攻擊我，凡人。這是唯一解除魔法的辦法啊!', `MaleText_loc7`='El encanto de Avruu... todavía me controla. Debes luchar conmigo, mortal. ¡Es la única forma de romper el hechizo!' WHERE `ID`=13448;
