UPDATE `locales_broadcast_text` SET `MaleText_loc1`='항상 세계의 정령들에게 존경을 표시하는 걸 잊지 마시오.', `MaleText_loc4`='永远要对这个世界上的元素表示尊敬。', `MaleText_loc5`='記得表現出你對世界元素的敬意。', `MaleText_loc7`='Recuerda que siempre debes mostrar respeto por los elementos del mundo.', `FemaleText_loc1`='항상 세계의 정령들에게 존경을 표시하는 걸 잊지 마십시오.', `FemaleText_loc4`='永远要对这个世界上的元素表示尊敬。', `FemaleText_loc5`='記得表現出你對世界元素的敬意。', `FemaleText_loc7`='Recuerda que siempre debes mostrar respeto por los elementos del mundo.' WHERE `ID`=13452;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 세계의 정령들이 유지하고 있는 균형을 이해하기 위해 우리는 부단히 노력해야 하오.', `MaleText_loc4`='我们必须努力了解这个世界上的元素之灵所维护的平衡。', `MaleText_loc5`='我們一定要努力了解這世界元素之靈維護的平衡點。', `MaleText_loc7`='Debemos esforzarnos por comprender el equilibrio que mantienen los espíritus elementales de este mundo.', `FemaleText_loc1`='이 세계의 정령들이 유지하고 있는 균형을 이해하기 위해 우리는 부단히 노력해야 합니다.', `FemaleText_loc4`='我们必须努力了解这个世界上的元素之灵所维护的平衡。', `FemaleText_loc5`='我們一定要努力了解這世界元素之靈維護的平衡點。', `FemaleText_loc7`='Debemos esforzarnos por comprender el equilibrio que mantienen los espíritus elementales de este mundo.' WHERE `ID`=13453;
