UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이것만 기억해 주시오, $n. 당신이 이자들을 위해 최대한 많은 도움을 주시는 것이... 우리의 중요 관심사라오.', `FemaleText_loc4`='记住，$n，你尽心竭力地帮助他们便是对我们莫大的恩惠……', `FemaleText_loc5`='請記得，$n，我們希望你盡最大的可能去做為了這...這些民眾。', `FemaleText_loc7`='Recuerda, $n, que lo que más nos beneficia es que hagas todo lo posible por esta... esta gente.' WHERE `ID`=13465;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$r 님, 안녕하세요! 오늘은 기분이 좋아 보이시네요?', `FemaleText_loc4`='你好，$r！我想你过得不错吧？', `FemaleText_loc5`='你好，$r!我相信你今天會過得很好?', `FemaleText_loc7`='Saludos, $r. ¿Qué tal te va?' WHERE `ID`=13466;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고향에서 소식이라도 왔소, $c|1이여;여;?', `FemaleText_loc4`='有什么家乡来的消息吗，$c？', `FemaleText_loc5`='有任何從家鄉傳來的消息嗎，$c?', `FemaleText_loc7`='¿Tienes noticias de tu casa, $c?' WHERE `ID`=13467;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가까이 오게나, 친구여. 내 눈을 보고 놀라지 말게.$B$B난 오래전에 시력을 잃었으나 정작 중요한 것을 보는 데 눈은 필요가 없다네.', `MaleText_loc4`='靠近点，朋友。不要被我的眼睛吓到了。$B$B我可能许多年前就失明了，但我从不需要通过眼睛来看重要的东西。', `MaleText_loc5`='靠近一點，朋友。不要讓我的眼睛嚇著你。$B$B我在好幾年前就失去了我的視力，但是我從不需要眼睛去看待事物。', `MaleText_loc7`='Acércate, $gamigo:amiga;. No dejes que mis ojos te asusten.$B$BPuede que perdiera la vista hace muchos años, pero nunca la necesité para ver las cosas que importan de verdad.' WHERE `ID`=13468;
