UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그물을 잡으십시오, 젊은 $c|1이여;여;. 우리 드레나이들에겐 먹을 음식이 필요합니다!', `FemaleText_loc4`='带上一张网，年轻的$c。我们需要食物！', `FemaleText_loc5`='抓淨利，年輕的$c。我們人民需要生計啊!', `FemaleText_loc7`='Coge una red, joven $c. ¡Nuestro pueblo necesita sustento!' WHERE `ID`=13471;
