UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 다른 신도레이 $g형제:자매;를 만나다니 정말 반갑구려! 짐작하시겠지만 이 주변에서 대화를 나누는 일이란 흔하지 않소이다.', `MaleText_loc4`='很高兴看到其他的辛多雷$g兄弟:姐妹;！如你所见，这附近没有什么其他人可以说话。', `MaleText_loc5`='很高興見到另一個辛多雷$g兄弟:姐妹;! 你可以想像，在這裡沒有什麼好交談的。', `MaleText_loc7`='¡Qué alegría ver a otro sin''dorei $ghermano:hermana;! Como puedes imaginar, no hay mucha conversación por aquí.' WHERE `ID`=13475;
