UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실리시스트를 25% 확보했습니다! 모두 힘을 내십시오!', `MaleText_loc4`='水晶尘的收集进度达到25%了！继续努力！', `MaleText_loc5`='我們已擁有四分之一需要的希利塞斯了!繼續努力!', `MaleText_loc7`='¡Tenemos un cuarto de la silitista que necesitamos! ¡Hay que continuar!' WHERE `ID`=13479;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='목표치의 50%에 달하는 실리시스트를 확보했습니다! 우린 해낼 수 있습니다!', `MaleText_loc4`='水晶尘的收集进度达到50%了！我们能行的！', `MaleText_loc5`='我們已擁有一半需要的希利塞斯了!我們會成功的!', `MaleText_loc7`='Tenemos la mitad de la silitista que necesitamos. ¡Podemos lograrlo!' WHERE `ID`=13480;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='목표치의 실리시스트 확보가 얼마 남지 남았소! 얼라이언스의 승리를 위하여!', `MaleText_loc4`='水晶尘的收集工作就快完成了！继续努力，别停啊！', `MaleText_loc5`='我們已擁有大部份需要的希利塞斯了!別停下來!', `MaleText_loc7`='Casi tenemos toda la silitista que necesitamos. ¡No debemos parar!' WHERE `ID`=13481;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네를 보게 되어 영광이로군.', `MaleText_loc4`='我很荣幸认识你。', `MaleText_loc5`='做為你所熟識的人讓我備受尊重。', `MaleText_loc7`='Me honra conocerte.' WHERE `ID`=13482;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나와 얘기를 나누려고 오다니 친절하시구려. 어떤 방법으로든 부디 얼라이언스를 돕게나.', `MaleText_loc4`='很高兴能和你说话，请尽量帮助联盟吧。', `MaleText_loc5`='你能和我說這些真是太好了。請用你的任何方法幫助聯盟。', `MaleText_loc7`='Me alegro de que hables conmigo. Por favor, ayuda a la Alianza en todo lo que puedas.' WHERE `ID`=13483;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하신가. 나는 드레나이이자 모든 이의 스승인 수도자 델란이라고 하네. 그런데 자네는 누군가?', `MaleText_loc4`='你好。我是学者德尔兰，一个德莱尼人。你是谁？', `MaleText_loc5`='你好。我是隱士迪藍 - 德萊尼之一。我勉強稱得上是一位老師。你想成為什麼呢?', `MaleText_loc7`='Saludos. Soy el anacoreta Delan – uno de los draenei. Soy maestro, si se puede llamar así. Y, ¿quién puedes ser tú?' WHERE `ID`=13484;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 얼라이언스의 다른 종족에게 가르칠 것도 많지만 배워야 할 것도 많소이다. 눈, 귀 그리고 마음을 여시오.', `MaleText_loc4`='虽然我们有很多东西可以教给联盟的其他种族，但是我们同样也有很多东西要从他们那里学习。要多多使用你的眼睛、耳朵和心灵，$c。', `MaleText_loc5`='當我們教導聯盟其他種族的人，我們有很多要和他們多學習的地方。保持你的眼睛、耳朵和你的心處於學習狀態，$c。', `MaleText_loc7`='Aunque tenemos mucho que enseñar a las otras razas de la Alianza, también tenemos mucho que aprender de ellas. Mantén los ojos, las orejas y la mente abiertos, $c.' WHERE `ID`=13485;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$c|1이여;여;, 안녕하신가요?', `FemaleText_loc4`='你好啊，$c。', `FemaleText_loc5`='你好，$c。', `FemaleText_loc7`='Saludos, $c.' WHERE `ID`=13486;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$c|1이여;여;, 안녕하세요. 이 신전은 정말 아름답지 않나요? 나이트 엘프들 중에서 좋은 친구를 만나면 마음이 따뜻해진답니다.', `FemaleText_loc4`='这座城市不漂亮吗，$c？我们可以找到这么知心的暗夜精灵朋友，真让我感到温暖。', `FemaleText_loc5`='這個城市不漂亮嗎，$c?在這個夜精靈城市裡認識這麼多好朋友真令我窩心。', `FemaleText_loc7`='¿No es preciosa esta ciudad, $c? Me reconforta que hayamos encontrado tan buenos amigos en estos elfos de la noche.' WHERE `ID`=13487;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하시오, 난 여행 중인 빛의 성기사 구원자 팔란나르라고 하오. 이 잿빛 골짜기엔 나이트 엘프들을 도우러 왔소이다.', `FemaleText_loc4`='你好，我是守备官帕兰纳尔，一个信仰圣光的旅行圣骑士。我是来这里帮助暗夜精灵的。', `FemaleText_loc5`='你好，我是復仇者帕拉那爾，聖光的旅行聖騎士。我在這裡協助夜靈精。', `FemaleText_loc7`='Saludos. Soy la vindicadora Palanaar, paladín de la Luz y viajera. Estoy aquí para ayudar a los elfos de la noche.' WHERE `ID`=13488;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='버림받은 잿빛 골짜기의 땅에 성스러운 빛을 인도하는 것이 내가 진정으로 원하는 일이오.', `FemaleText_loc4`='我热切希望我们可以把圣光带到灰谷中的那些被遗忘的地方。', `FemaleText_loc5`='我們能將梣谷被遺忘的聖光帶回來是我最大的期望。', `FemaleText_loc7`='Espero con fervor que podamos llevar la Luz a aquellos lugares de Vallefresno donde se ha abandonado.' WHERE `ID`=13489;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 정도 싸움꾼한테 무기는 장신구에 불과하지!', `MaleText_loc4`='武器对我这样的战士来说无足轻重！', `MaleText_loc5`='武器對我這種技能的戰士而言只是一種方便而已!', `MaleText_loc7`='¡Las armas son solo herramientas para un guerrero con mi habilidad!' WHERE `ID`=13490;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로소스, 저를 화산 심장부로 보내 주십시오.', `MaleText_loc4`='把我传送到熔火之心去，洛索斯。', `MaleText_loc5`='將我傳送至熔火之心，洛索斯。', `MaleText_loc7`='Llévame al Núcleo de Magma, Lothos.', `FemaleText_loc1`='로소스, 저를 화산 심장부로 보내 주세요.', `FemaleText_loc4`='把我传送到熔火之心去，洛索斯。', `FemaleText_loc5`='將我傳送至熔火之心，洛索斯。', `FemaleText_loc7`='Llévame al Núcleo de Magma, Lothos.' WHERE `ID`=13491;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그따위 하찮은 마법으로는 스컬지에 상대도 되지 않는다는 걸 모르느냐!', `MaleText_loc4`='你们可笑的魔法对天灾军团来说不值一提！', `MaleText_loc5`='你們可笑的魔法對天譴軍團來說不值一提!', `MaleText_loc7`='¡Tus magias insignificantes no compiten con el poder de la Plaga!' WHERE `ID`=13492;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쓸데없는 수다나 떨면서 낭비할 시간이 없소. 사냥거리를 찾고 있다면 강가에 있는 딕티나에게 말해 보시게. 분명히 그녀에게 도움이 필요할 테니, 여기서 동쪽으로 가서 그녀를 만나보시오.', `MaleText_loc4`='我太忙了，没时间闲聊。如果你在寻找一份猎手的工作，去和河边迪泰娜聊聊吧。往东走，她应该还在那里忙呢。', `MaleText_loc5`='我太忙了沒空閒聊。如果你在尋找獵人的工作，就和河邊的狄克泰納談談 - 在東邊。她的工作一定還沒做完...', `MaleText_loc7`='Estoy demasiado ocupado como para perder el tiempo en cháchara. Si buscas trabajo como cazador, habla con Diktynna, que está en el margen del río, al este. Sin duda irá atrasada en sus tareas...' WHERE `ID`=13493;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사냥꾼으로서 훈련을 받고 싶습니다, 옥테온.', `MaleText_loc4`='我是个需要训练的猎人，艾克提恩。', `MaleText_loc5`='我是一個需要訓練的獵人，艾克緹昂。', `MaleText_loc7`='Soy un cazador en busca de instrucción, Acteon.', `FemaleText_loc1`='사냥꾼으로서 훈련을 받고 싶어요, 옥테온.', `FemaleText_loc4`='我是个需要训练的猎人，艾克提恩。', `FemaleText_loc5`='我是一個需要訓練的獵人，艾克緹昂。', `FemaleText_loc7`='Soy una cazadora en busca de instrucción, Acteon.' WHERE `ID`=13494;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아주 재미있을 거예요! 제 말이 맞죠?', `FemaleText_loc4`='看上去很有趣！亲爱的，你不觉得吗？', `FemaleText_loc5`='這會很有趣的!你不覺得嗎，親愛的?', `FemaleText_loc7`='¡Esto va a ser muy divertido! ¿No crees, $gquerido:querida;?' WHERE `ID`=13495;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엑소다르를 보게, 젊은이. 우리가 그런 재앙에서 살아남았다는 게 상상조차 어렵다네.$B$B<한숨을 쉬는 메넬라우스>$B$B예언자님의 말씀에 따르면 바로 여기가 우리의 운명이 마지막으로 펼쳐질 곳이라는군. 불타는 군단의 광기를 피해 평생을 도망쳐다녔지... 마침내 우리는 여기서 맞서기로 했네.$B$B더는 도망치지 않을 것이야... 나는 죽을 각오가 되었네.', `MaleText_loc4`='看看埃索达，年轻的$c。很难想象我们在这场大灾难中生存了下来。$B$B<梅内莱厄斯叹了口气。>$B$B先知预言我们会在这里最终了解到自己的命运。我们用了毕生的时间来逃避疯狂的燃烧军团……现在我们终于可以在这里停下来了。$B$B不再逃跑……我已经准备好光荣地战死了。', `MaleText_loc5`='盯著艾克索達，年輕的$r。真難想像我們在如此的大災難中存活了下來。$B$B<米奈奧斯嘆了口氣。>$B$B預言者表示在這裡我們的命運將最後被知道。從瘋狂地燃燒軍團逃離花了十年的時間...終於在這裡落腳。$B$B不必再逃了...我已經準備好接受死亡。', `MaleText_loc7`='Observa con atención El Exodar, joven $r. Es difícil imaginar que sobrevivimos a tal catástrofe.$B$B<Menelaous suspira.>$B$BEl profeta afirma que es aquí donde, al fin, se conocerá nuestro destino. Diez vidas pasadas huyendo de la locura de la Legión Ardiente... por fin aquí resistimos.$B$BSe acabó el huir... Estoy preparado para morir.' WHERE `ID`=13496;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='발란다르 브라이트스타에게 제 얘기를 전해주세요. 그는 뭘 해야 할지 알고 있을 거랍니다.', `FemaleText_loc4`='去和巴尔兰达·新星聊聊。他会知道该怎么做。', `FemaleText_loc5`='把字條帶給巴藍達·亮星。他會知道該怎麼做。', `FemaleText_loc7`='Envía el mensaje Balandar Estrellaclara. Él sabrá qué hacer.' WHERE `ID`=13497;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='발란다르 브라이트스타가 절 구출하라고 그대를 보냈나요?', `FemaleText_loc4`='是巴尔兰达·新星派你来救我的吗？', `FemaleText_loc5`='是巴藍達·亮星派你來救我的嗎?', `FemaleText_loc7`='¿Te envío Balandar Estrellaclara a rescatarme?' WHERE `ID`=13498;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발란다르가 당신을 구출하고 화물을 되찾아 오라고 절 보냈습니다. 그는 담쟁이 마을에서 기다리고 있습니다.', `MaleText_loc4`='巴尔兰达派我到这里来救你出去，顺便拿回他的货物。他在蕨墙村等着你。', `MaleText_loc5`='巴藍達派我來這裡把你救出來並收回他的貨物。他正在蕨牆村等你。', `MaleText_loc7`='Balandar me ha enviado para sacarte de aquí y recuperar su mercancía. Te espera en el poblado Murohelecho.', `FemaleText_loc1`='발란다르가 당신을 구출하고 화물을 되찾아 오라고 절 보냈습니다. 그는 담쟁이 마을에서 기다리고 있습니다.', `FemaleText_loc4`='巴尔兰达派我到这里来救你出去，顺便拿回他的货物。他在蕨墙村等着你。', `FemaleText_loc5`='巴藍達派我來這裡把你救出來並收回他的貨物。他正在蕨牆村等你。', `FemaleText_loc7`='Balandar me ha enviado para sacarte de aquí y recuperar su mercancía. Te espera en el poblado Murohelecho.' WHERE `ID`=13499;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='담쟁이 마을까지 혼자 갈 수 있을 거예요. 화물은 이 탑 꼭대기에 있어요. 부디 조심하세요!', `FemaleText_loc4`='我想我可以自己回蕨墙村。他们把货物放在了塔顶，多加小心！', `FemaleText_loc5`='我想我可以自己趕去蕨牆村。他們已經在哨塔頂端拿到貨物了。小心!', `FemaleText_loc7`='Creo que puedo llegar hasta Murohelecho sin ayuda. Tienen la mercancía en lo alto de la torre. ¡Ten cuidado!' WHERE `ID`=13500;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오, 정말 굉장하군요! 정말 재미있었지 않나요? 그 역겨운 잃어버린 드레나이들에게 조금씩 조금씩 저주를 걸고 있었는데 조만간 드레나이에게 시험해 볼 생각이랍니다!', `FemaleText_loc4`='太棒了！真是太有趣了，难道不是吗？我满满地诅咒了这些恶心的失落者，很快我就可以在德莱尼人身上试试了！', `FemaleText_loc5`='哦，最優秀的!那很有趣，不是嗎?慢慢地我已經詛咒了那些另人討厭的失落者。很快地我將會準備好對著德萊尼試試!', `FemaleText_loc7`='¡Ah, excelente! Fue divertido, ¿no? Poco a poco voy maldiciendo a más de esos repugnantes Perdidos. Pronto podré probar con los draenei.' WHERE `ID`=13501;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$r|1이여;여;, 영혼이 당신을 인도하길...', `FemaleText_loc4`='让灵魂指引你吧，$r。', `FemaleText_loc5`='願靈魂指引你，$r。', `FemaleText_loc7`='Que los espíritus te guíen, $r.' WHERE `ID`=13502;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마그하르에게 힘을! 여기는 무슨 일로 오셨소?', `MaleText_loc4`='氏族的力量，$c！你来这里干什么？', `MaleText_loc5`='氏族的力量，$c!是什麼事讓你來到這裡?', `MaleText_loc7`='¡Fuerza a los clanes, $c! ¿Qué te trae por aquí?' WHERE `ID`=13503;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하신가. 나는 드레나이 수도자 아분이라고 하네. 잃어버린 드레나이의 상태를 치유할 방법을 찾을 수 있다는 희망을 품고 여기서 드레노어 성역의 잃어버린 드레나이를 연구하고 있다네.', `MaleText_loc4`='你好。我是德莱尼学者阿弗恩。我在这里研究农田避难所的失落者们，希望可以找到一个治愈他们的办法。', `MaleText_loc5`='你好。我是德萊尼的隱士艾弗恩。我來這裡調查農田避難所失落者，希望能為他們的情況找到一種解藥。', `MaleText_loc7`='Saludos. Soy el anacoreta Avuun, de los draenei. Estoy aquí estudiando a Los Perdidos del Retiro Fangoso con la esperanza de poder encontrar una cura para su estado.' WHERE `ID`=13504;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 당신을 환영하오. 당분간은 말이지...', `MaleText_loc4`='欢迎你来到这里，$c。', `MaleText_loc5`='在我們之間你是受歡迎的，$c。至少現在是。', `MaleText_loc7`='Te damos la bienvenida entre nosotros, $c. Al menos por el momento.' WHERE `ID`=13505;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저주받은 잃어버린 드레나이를 도와준 점 다시 한번 고맙게 생각하네. 자네의 도움이 없었다면 내 연구를 계속 할 수 없었을 걸세.', `MaleText_loc4`='再次感谢你对被诅咒的失落者所提供的帮助。没有你的帮助，我想我是无法继续研究的。', `MaleText_loc5`='再一次感謝你協助被詛咒的失落者。沒有你的幫助，我無法繼續進行我的研究。', `MaleText_loc7`='Una vez más, gracias por tu ayuda con Los Perdidos malditos. Sin tu ayuda nunca podría haber podido continuar con mi investigación.' WHERE `ID`=13506;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='', `MaleText_loc4`='', `MaleText_loc5`='', `MaleText_loc7`='' WHERE `ID`=13507;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 상자에서 재료들을 꺼내 약병에 넣고 섞습니다.', `FemaleText_loc4`='%s从箱子里拿出材料，然后在瓶子里面把它们混了起来。', `FemaleText_loc5`='%s從木箱裡移除試劑，並在瓶子裡混合每種藥水。', `FemaleText_loc7`='%s extrae los componentes de la caja y mezcla porciones de cada uno en un frasco.' WHERE `ID`=13508;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='연구를 끝내기 위해 숱한 고난을 견뎌냈고 그대의 도움으로 마침내 해냈습니다. 밝은 미래가 우리를 기다리고 있을 거예요!', `FemaleText_loc4`='为了完成我的研究，我忍受了许多的苦难。在你的帮助下，$n，我终于成功了。我们将会获得一个美好的未来！', `FemaleText_loc5`='我為了完成我的研究已經忍受了許多困難，有你的幫助，$n，我終於做到了。為光明的未來乾杯!', `FemaleText_loc7`='He soportado muchas privaciones para finalizar mi investigación y, con tu ayuda, $n, por fin lo he hecho. ¡Por un futuro mejor!' WHERE `ID`=13509;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='머리가... 어질어질해요. 무슨 일이... 일어나는 걸까요?', `FemaleText_loc4`='我感到……头晕眼花……发生了……什么？', `FemaleText_loc5`='我感到...頭昏眼花...發生...發生什麼事了?', `FemaleText_loc7`='Me siento... algo mareada... ¿Qué... me está pasando?' WHERE `ID`=13510;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아냐, 이럴 리가 없어! 이 약은... 중독을 치유하기 위해서였지 타락의 속도를 빠르게 해서 버림받은 자 따위가 되려고 이날까지 연구한 게 아닌데!', `FemaleText_loc4`='不，这不可能！这药剂……是应该改变我对魔法的沉迷，而不是把我变成一个肮脏丑陋的失心者！不！！！', `FemaleText_loc5`='不，不可能!這個藥水...它應該是要改變我的沉溺，不是加速我在鄙惡者階級的衰退!', `FemaleText_loc7`='¡No puede ser! Este tónico... Se suponía que iba a curar mi adicción, no a acelerar mi transformación en uno de los desdichados.' WHERE `ID`=13511;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘 왔다, 친절한 영혼이여. 무슨 일로 이곳에 온 거지?', `FemaleText_loc4`='你好，$n。是什么风把你吹到这里来的？', `FemaleText_loc5`='歡迎，善良的靈魂。什麼事把你帶來我們這裡?', `FemaleText_loc7`='Bienvenido, amable espíritu. ¿Qué te ha traído hasta nosotros?' WHERE `ID`=13512;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 끝나지 않았어! 몇 가지 계략을 준비해 두었지...', `MaleText_loc4`='还没完！我还有几招没有用呢……', `MaleText_loc5`='我還沒有結束!不，我還有一些小伎倆沒施展出來呢...', `MaleText_loc7`='¡No he acabado aún! Aún tengo un par de ases bajo la manga...' WHERE `ID`=13513;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='목 좀 축이게 해달라는 이 늙은이의 청을 뿌리칠 텐가? 아... 별로 기대도 안 했어.', `MaleText_loc4`='你们应该不会不让一个可怜的老人喝点东西吧？不，不，当然不会。', `MaleText_loc5`='想必你不會拒絕給一個老人補充飲品吧?不，不，我想不會。', `MaleText_loc7`='¿Seguro que no le negarías a un viejo una bebida reconstituyente? No, no, es lo que pensé.' WHERE `ID`=13514;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 마나를 사용해 강력한 비전 마법을 시전합니다.', `MaleText_loc4`='%s开始引导魔法能量，准备施放一个强大的奥术魔法。', `MaleText_loc5`='%s開始引導他的法力進入一個強大的秘法法術。', `MaleText_loc7`='%s comienza a canalizar su maná en un poderoso hechizo Arcano.' WHERE `ID`=13515;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 정말 꿀맛이로군!', `MaleText_loc4`='啊，没有什么比畅饮一通更好的了！', `MaleText_loc5`='啊，沒有什麼比好好喝上一杯更棒的了!', `MaleText_loc7`='¡Ah, nada como una buena copa!' WHERE `ID`=13516;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 내 아들은 아주 강하지... 하지만, 내게도 힘은 있다!', `MaleText_loc4`='没错，我的儿子非常强大……但我也有自己的力量！', `MaleText_loc5`='是的，沒錯，我兒子的力量相當強大...但我有我自己的力量!', `MaleText_loc7`='Sí, sí, mi primogénito es bastante poderoso... ¡pero yo tengo mis propios poderes!' WHERE `ID`=13517;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 어릿광대 따위가 아니다! 나는 니엘라스 아란이다!', `MaleText_loc4`='我不是某个可笑的小丑，我是聂拉斯·埃兰！', `MaleText_loc5`='我可不像那些普通的小丑!我是聶拉斯·埃蘭!', `MaleText_loc7`='¡No soy un simple bufón! ¡Soy Nielas Aran!' WHERE `ID`=13518;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희에게 보여주마! 아무리 지친 개라도 송곳니는 있는 법!', `MaleText_loc4`='我要让你们知道，老狗也有几颗牙！', `MaleText_loc5`='我會讓你們看到:被打的狗也會反擊的!', `MaleText_loc7`='¡Mire: este perro apaleado aún tiene dientes!' WHERE `ID`=13519;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불타라, 지옥의 악마들아!', `MaleText_loc4`='燃烧吧，地狱的恶魔！', `MaleText_loc5`='燃燒吧，你這地獄的惡魔!', `MaleText_loc7`='¡Ardan, monstruos infernales!' WHERE `ID`=13520;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 키린 토의 최고 마법사 중 하나였다. 대충대충 해서는 절대로 날 이길 수 없을 것이다!', `MaleText_loc4`='我是肯瑞托最强大的法师之一。你们是不可能打败我的！', `MaleText_loc5`='我是祈倫托中最出色的幾個人之一。你擊敗不了我的!', `MaleText_loc7`='Me contaba entre los mejores de los Kirin Tor. ¡No me vencerás holgazaneando!' WHERE `ID`=13521;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 얼려 버리겠다!', `MaleText_loc4`='我要把你们全都冰冻！', `MaleText_loc5`='我會把你們全都凍死!', `MaleText_loc7`='¡Los congelaré a todos!' WHERE `ID`=13522;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='차가운 암흑으로 돌아가라!', `MaleText_loc4`='回到寒冷的黑暗中去吧！', `MaleText_loc5`='滾回你那冰冷的黑暗之中!', `MaleText_loc7`='¡Devuelta a la fría oscuridad con ustedes!' WHERE `ID`=13523;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아들의 비밀을 밝히려는 나의 의지는 죽음도 꺾지 못하노라!', `MaleText_loc4`='即使是死亡也无法阻止我揭开我儿子的秘密！', `MaleText_loc5`='就算死也不能阻擋我揭發我兒子的秘密!', `MaleText_loc7`='¡Ni la muerte impedirá que descubra los secretos de mi hijo!' WHERE `ID`=13525;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 악몽을 끝내고 싶구나!', `MaleText_loc4`='我要结束这场噩梦！', `MaleText_loc5`='我要結束這個夢魘!', `MaleText_loc7`='¡Quiero que se acabe esta pesadilla!' WHERE `ID`=13526;
