UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제발 그만! 내 아들... 그 아이는 미쳤어!', `MaleText_loc4`='求求你们，不要这样！我的儿子……已经疯了！', `MaleText_loc5`='拜託，別再來了!我的兒子...他已經瘋了!', `MaleText_loc7`='¡Por favor, basta! ¡Mi hijo... se ha vuelto loco!' WHERE `ID`=13529;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너흰 누구냐? 원하는 게 뭐야? 가까이 오지 마!', `MaleText_loc4`='你们是谁？你们想要什么？离我远点！', `MaleText_loc5`='你是誰?你想要什麼?離我遠一點!', `MaleText_loc7`='¿Quiénes son? ¿Qué quieren? ¡Aléjense de mí!' WHERE `ID`=13530;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그건 어디서 났지? 그 아이가 보냈나?', `MaleText_loc4`='你怎么拿到这个的？是不是他派你来的？', `MaleText_loc5`='你從哪裡弄到那個東西?是他派你來的嗎?', `MaleText_loc7`='¿De dónde sacaron eso? ¿Los ha enviado ÉL?' WHERE `ID`=13532;
