UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나의 백성이 아직 아웃랜드에 살아남아 있다니...', `MaleText_loc4`='我的同胞在外域中幸存了下来……', `MaleText_loc5`='我的人民在外域生存下來...', `MaleText_loc7`='Mi gente ha sobrevivido en Terrallende...' WHERE `ID`=13537;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오랜 세월 들키지 않고...', `MaleText_loc4`='被遗忘了许多年……', `MaleText_loc5`='被忽略了好幾年...', `MaleText_loc7`='Desapercibido durante años...' WHERE `ID`=13538;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타락하지도 않았구나!', `MaleText_loc4`='……没有被腐蚀！', `MaleText_loc5`='...未腐敗的!', `MaleText_loc7`='¡...sin corromper!' WHERE `ID`=13539;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 괜찮소, 아이트리그. 준비를 시작해야 하오. 당장 아웃랜드에 가야 한단 말이오!', `MaleText_loc4`='我没事，伊崔格。我们必须开始准备了……我需要马上赶往外域！', `MaleText_loc5`='我會沒事的，伊崔格。我們一定要開始準備了...我需要立刻前往外域!', `MaleText_loc7`='Estaré bien, Eitrigg. Debemos comenzar los preparativos... ¡Debo partir a Terrallende de inmediato!' WHERE `ID`=13540;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대 말이 맞소, 아이트리그. 시기가 좋지 않군. 헬스크림에게 갈 사절은 최고의 인재들로 구성하시오.', `MaleText_loc4`='你说得对，伊崔格。现在并不是很合适。那么我们必须派最好的使者去觐见地狱咆哮。', `MaleText_loc5`='你說的對，伊崔格。時機不利。確認我們最優秀的大使都被派到地獄吼當使者了。', `MaleText_loc7`='Tienes razón, Eitrigg. El momento es adverso. Asegúrate de que se manden a nuestros mejores embajadores como enviados a Grito Infernal.' WHERE `ID`=13541;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장님! 스랄 님... 괜찮으십니까?', `MaleText_loc4`='萨尔大人……你还好吧？', `MaleText_loc5`='索爾!我的大人...你還好嗎?', `MaleText_loc7`='¡Thrall! Mi señor... ¿está bien?' WHERE `ID`=13542;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='존경하는 대족장님. 진정하십시오. 제대로 준비하지 않으면 적들이 대족장님께서 안 계신 틈을 이용할 겁니다.', `MaleText_loc4`='请恕我直言，酋长。如果我们不准备妥当的话，我们的敌人会因为你的意外缺席而获得优势。', `MaleText_loc5`='恕我直言，大酋長。如果我們不準備妥當，敵人就會利用你意外缺席的機會。', `MaleText_loc7`='Con todos mis respetos, Jefe de Guerra. Nuestros enemigos aprovecharían tu repentina ausencia si no nos preparamos adecuadamente.' WHERE `ID`=13543;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당장 시행하겠습니다, 대족장님! 호드를 위하여!', `MaleText_loc4`='马上，大人！为了部落！', `MaleText_loc5`='立刻，長官!為了部落!', `MaleText_loc7`='¡Enseguida, señor! ¡Por la Horda!' WHERE `ID`=13544;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말 대단하군요! 그런데 골짜기에서는 어떻게 빠져나왔죠? 누군가 당신을 찾으러 수색대를 보내기 전에 돌아가는 게 좋겠군요.', `FemaleText_loc4`='啧啧，好可爱啊！你怎么敢独自出来的？也许你在其他人派出搜索队之前赶紧回去。', `FemaleText_loc5`='喔天啊!你怎麼逃出溪谷的?或許你該在某人派搜索隊來找你前回去那裡。', `FemaleText_loc7`='¿No es adorable? ¿Cómo te las arreglaste para salir del Valle? Quizás deberías volver antes de que alguien envíe un pelotón de búsqueda a por ti.' WHERE `ID`=13545;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이젠 더 부탁드릴 일이 없네요. 우리가 함께 먹은 붉은퉁돔은 절대 잊지 못할 특별한 추억이라는 사실만은 잊지 마세요...', `FemaleText_loc4`='我这里没有更多的工作可以给你了，$n。我想让你知道，那些红钳鱼真是我一辈子也忘不了的美味……', `FemaleText_loc5`='我沒有別的工作可以給你了，$n。我想讓你知道我們一起分享過的紅鯛魚是我永遠不會忘記的回憶...', `FemaleText_loc7`='No tengo más trabajo para ti, $n. Quiero que sepas que el pargo rojo que compartimos fue algo especial que nunca olvidaré...' WHERE `ID`=13546;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론 자네가 할 일이 있지! 우린 항상 솜씨 좋은 $c|1을;를; 찾고 있다네. 우리가 엑소다르로 다시 돌려보낼 드레나이들보다는 자네가 더 뛰어나길 바라네. 엑소다르를 돌아가는 드레나이는 생명이 다해 매장하려고 보내는 것이니 말이야...$B$B<소리 내어 웃는 옥테온>$B$B하하, 농담이라네! 자네 표정 정말 가관이로군. 그들은 경미한 상처를 치료하려고 엑소다르로 가는 거라네. 금방 나을 가벼운 상처지...', `MaleText_loc4`='我当然有工作要给你！我们一直在找寻$c，希望你能比那些我们送回埃索达去埋掉的德莱尼人好一点。$B$B艾克提恩大笑起来。$B$B我在开玩笑呢！你真该看看你刚才那表情。他们被送回埃索达是为了治疗些小伤，很快都会痊愈的……', `MaleText_loc5`='我當然有工作給你!我們一直都在尋找$c。希望你比那些被我們送回艾克索達...參加葬禮的德萊尼好一點。$B$B<艾克緹昂笑著。>$B$B開玩笑的!你真該看看你剛才的表情。他們被送回艾克索達治療小傷。沒有什麼無法復原的大傷...', `MaleText_loc7`='¡Por supuesto que tengo un trabajo para ti! Siempre nos viene bien $gun:una; $c. Esperemos que te vaya mejor que a los draenei que tuvimos que mandar de vuelta a El Exodar... para enterrarlos.$B$B<Acteon ríe.>$B$B¡Es broma! Si hubieras visto la cara que has puesto... Los mandamos a El Exodar para tratarlos de heridas leves. Nada de lo que no pudieran recuperarse en unos días...' WHERE `ID`=13547;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만 좀 뛰어다녀라, $n!', `MaleText_loc4`='不要跑来跑去的，$n！', `MaleText_loc5`='不要跑來跑去了，$n!', `MaleText_loc7`='¡Deja de corretear, $n!' WHERE `ID`=13548;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 종족에게 돌아가 주술사 한 명을 내게 보내라고 전하라, $c|1이여;여;.', `MaleText_loc4`='回到你的人民那里，告诉他们派个萨满祭司到我这里来。', `MaleText_loc5`='回到你的人民那裡並告訴他們派一個薩滿來我這。', `MaleText_loc7`='Vuelve con tu gente y diles que me envíen uno de sus chamanes.' WHERE `ID`=13549;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드레나이들에게 돌아가 주술사를 내게 보내라고 전하라.', `MaleText_loc4`='回到德莱尼人那里，告诉他们派个萨满祭司到我这里来。', `MaleText_loc5`='回到德萊尼那裡並告訴他們派一個薩滿來我這裡。', `MaleText_loc7`='Vuelve con los draenei y diles que me envíen a uno de sus chamanes.' WHERE `ID`=13550;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에서 네 임무는 끝났다, 주술사여. 이제 너의 동료에게 돌아가라.', `MaleText_loc4`='萨满祭司，你在这里的事情都完结了。回到你的族人那里去吧。', `MaleText_loc5`='你在這裡的工作完成了，薩滿。回到你的人民那裡吧。', `MaleText_loc7`='Tu trabajo aquí ha terminado, chamán. Vuelve con tu gente.' WHERE `ID`=13551;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주술사여, 계속할 수 있겠나? 왜 여기에 있는지 알겠는가?', `MaleText_loc4`='你有足够继续下去的理解力了吗，萨满祭司？你知道我们为什么在这里吗？', `MaleText_loc5`='你有繼續下去的體認了嗎，薩滿?你知道你為什麼會在這裡嗎?', `MaleText_loc7`='¿Tienes los conocimientos para continuar, chamán? ¿Sabes por qué estás aquí?' WHERE `ID`=13552;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그가 아버지와 같은 인물이라면 마그하르와 동맹을 맺음으로써 호드에게 새로운 시대가 도래할 것이야.', `MaleText_loc4`='如果他和他的父亲一样的话，与玛格汉结盟将会引领部落走向新时代的黎明。', `MaleText_loc5`='如果他有一點像他的父親，和瑪格哈結盟將為部落帶來一個新時代。', `MaleText_loc7`='Si se parece en algo a su padre, aliarse con los Mag''har marcará el comienzo de una nueva era para la Horda.' WHERE `ID`=13553;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하신가, $r|1이여;여;.', `MaleText_loc4`='你好，$R。', `MaleText_loc5`='你好，$r。', `MaleText_loc7`='Saludos, $r.' WHERE `ID`=13554;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='활동하기도 좋고 정령과 함께하기에도 좋은 날이로군.', `MaleText_loc4`='能生存下来，并且和元素们生活在一起，这可真好啊。', `MaleText_loc5`='能和元素一致活著真好。', `MaleText_loc7`='Es un buen día para estar vivo y fusionarse con los elementos.' WHERE `ID`=13555;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$r|1이여;여;, 내가 그대와 얘기를 나눠야만 하는가?', `MaleText_loc4`='我为什么要和你说话，$r？', `MaleText_loc5`='而我為什麼要跟你說話，$r?', `MaleText_loc7`='¿Y por qué iba a querer hablar contigo, $r?' WHERE `ID`=13556;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 있어 봤자 문제만 일으킬 뿐이다, 호드의 $g형제여:자매여;. 조용히 돌아가라.', `MaleText_loc4`='$G小伙子:姑娘;，你在这儿只会给我们添麻烦而已。走吧。', `MaleText_loc5`='你的出現只代表了麻煩，部落的$g兒子:女兒;。靜靜的走吧。', `MaleText_loc7`='Tu presencia aquí solo puede significar problemas, $ghijo:hija; de la Horda. Ve en paz.' WHERE `ID`=13557;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주위를 둘러보라, 주술사여. 대지, 바람, 물, 불, 그리고 이 모든 것과 관계를 맺고 있는 정령들의 균형이 보이는가?', `MaleText_loc4`='看看你周围，萨满祭司。你可以看到在大地、空气、水和火焰这些元素之间的平衡吗？', `MaleText_loc5`='看看你的四周，薩滿。你有看到大地，空氣，水和火焰裡的元素平衡嗎?', `MaleText_loc7`='Mira a tu alrededor, chamán. ¿Ves el equilibrio de los elementos en la tierra, el aire, el agua y el fuego que los ha tocado a todos?' WHERE `ID`=13558;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 날 소환하다니!', `MaleText_loc4`='你胆敢召唤我？！', `MaleText_loc5`='你竟敢召喚我?!', `MaleText_loc7`='¡¿Te atreves a invocarme?!' WHERE `ID`=13559;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 감히 이 나이아스 님에게 도전하는가? 약해빠진 $r 같으니, 넌 내가 장난감 삼아 데리고 놀던 어리석은 트롤들과 하등의 차이도 없구나!', `MaleText_loc4`='是谁胆敢挑战奈亚斯？渺小的$r，你只是比那些曾经被我玩弄于股掌之间的没有头脑的巨魔稍微强一些！', `MaleText_loc5`='是誰挑戰奈亞斯?微小的$r，你比以前那些跟我對決的無腦食人妖好一點，他們就像棋盤上的散沙一樣!', `MaleText_loc7`='¿Quién desafía a Naias? ¡Enclenque $r, no eres mucho mejor que esos estúpidos trols contra los que he luchado como en un tablero de juego!' WHERE `ID`=13560;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놀라지 마십시오... 제 그리핀이 온전한 상태는 아닐지 몰라도 당신을 목적지까지 안전하게 데려다 줄 겁니다. 어느 탑으로 가실 것인지 말씀해 주시겠습니까?', `MaleText_loc4`='别紧张……我的狮鹫虽然看起来死气沉沉，但是它们仍然能把你安全地送往目的地。告诉我……你想要去哪座哨塔？', `MaleText_loc5`='別驚慌...雖然我的獅鷲獸沒那麼有活力，但他們仍會忠誠地將你載往目的地。告訴我...你想去哪一個哨塔?', `MaleText_loc7`='No te asustes... mis grifos puede que no estén muy vivos que digamos, pero aun así te llevarán sin problemas a tu destino. Dime... ¿qué torre buscas?', `FemaleText_loc1`='놀라지 마십시오... 제 그리핀이 온전한 상태는 아닐지 몰라도 당신을 목적지까지 안전하게 데려다 줄 겁니다. 어느 탑으로 가실 것인지 말씀해 주시겠습니까?', `FemaleText_loc4`='别紧张……我的狮鹫虽然看起来死气沉沉，但是它们仍然能把你安全地送往目的地。告诉我……你想要去哪座哨塔？', `FemaleText_loc5`='別驚慌...雖然我的獅鷲獸沒那麼有活力，但他們仍會忠誠地將你載往目的地。告訴我...你想去哪一個哨塔?', `FemaleText_loc7`='No te asustes... mis grifos puede que no estén muy vivos que digamos, pero aun así te llevarán sin problemas a tu destino. Dime... ¿qué torre buscas?' WHERE `ID`=13561;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='북부관문 경비탑으로 가고자 합니다.', `MaleText_loc4`='带我去北地哨塔。', `MaleText_loc5`='帶我到北地哨塔。', `MaleText_loc7`='Llévame a la Torre del Paso Norte', `FemaleText_loc1`='북부관문 경비탑으로 가고자 합니다.', `FemaleText_loc4`='带我去北地哨塔。', `FemaleText_loc5`='帶我到北地哨塔。', `FemaleText_loc7`='Llévame a la Torre del Paso Norte' WHERE `ID`=13562;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동부방벽 경비탑으로 가고자 합니다.', `MaleText_loc4`='带我去东墙哨塔。', `MaleText_loc5`='帶我到東牆之塔。', `MaleText_loc7`='Llévame a la Torre de la Muralla Este.', `FemaleText_loc1`='동부방벽 경비탑으로 가고자 합니다.', `FemaleText_loc4`='带我去东墙哨塔。', `FemaleText_loc5`='帶我到東牆之塔。', `FemaleText_loc7`='Llévame a la Torre de la Muralla Este.' WHERE `ID`=13563;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='산마루 경비탑으로 가고자 합니다.', `MaleText_loc4`='带我去皇冠哨塔。', `MaleText_loc5`='帶我到皇冠哨塔。', `MaleText_loc7`='Llévame a la Torre de la Corona.', `FemaleText_loc1`='산마루 경비탑으로 가고자 합니다.', `FemaleText_loc4`='带我去皇冠哨塔。', `FemaleText_loc5`='帶我到皇冠哨塔。', `FemaleText_loc7`='Llévame a la Torre de la Corona.' WHERE `ID`=13564;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='붕대 사용법을 아직 안 배우셨다면 기본적인 붕대 제조법과 사용법을 기꺼이 알려드리겠어요. 전투에서 적절하게 붕대를 사용하느냐 그렇지 못하느냐에 따라 생사가 결정되는 경우가 간혹 있죠.', `FemaleText_loc4`='要是你还没学会怎么去使用绷带，我很高兴向你展示下基本的绷带制作和使用方法。生与死之间的区别，经常是一根绑带决定的。', `FemaleText_loc5`='如果你還沒學會怎麼使用繃帶，我很樂意教你基本的製造和使用。生與死的分別通常和正確地包紮傷口有關。', `FemaleText_loc7`='Si aún no has aprendido a usar las vendas, me encantará enseñarte los fundamentos de su creación y aplicación. La diferencia entre la vida y la muerte puede reducirse a menudo a vendar heridas adecuadamente.' WHERE `ID`=13565;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='응급치료에 대해 자세히 배우고 싶습니다, 파티마.', `MaleText_loc4`='法蒂玛，我想要学习急救技能，希望你能把你掌握的知识都传授给我。', `MaleText_loc5`='我想學習所有你要教我的急救技能，法禔瑪。', `MaleText_loc7`='Deseo aprender todo lo que tengas que enseñarme sobre los primeros auxilios, Fateema.', `FemaleText_loc1`='응급치료에 대해 자세히 배우고 싶어요, 파티마.', `FemaleText_loc4`='法蒂玛，我想要学习急救技能，希望你能把你掌握的知识都传授给我。', `FemaleText_loc5`='我想學習所有你要教我的急救技能，法禔瑪。', `FemaleText_loc7`='Deseo aprender todo lo que tengas que enseñarme sobre los primeros auxilios, Fateema.' WHERE `ID`=13566;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 복수할 것이오!', `MaleText_loc4`='我会报仇的！！', `MaleText_loc5`='我會報復的!', `MaleText_loc7`='¡TENDRÉ mi venganza!' WHERE `ID`=13567;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 매우 바쁩니다, $c|1이여;여;. 우리의 상황을 이해해 주시리라 믿습니다.', `MaleText_loc4`='我现在很忙，年轻的$c，不好意思。', `MaleText_loc5`='我現在很忙，年輕的$c。對不起。', `MaleText_loc7`='Ahora estoy muy ocupado, joven $c. Discúlpame, por favor.', `FemaleText_loc1`='지금 매우 바쁩니다, $c|1이여;여;. 우리의 상황을 이해해 주시리라 믿어요.', `FemaleText_loc4`='我现在很忙，年轻的$c，不好意思。', `FemaleText_loc5`='我現在很忙，年輕的$c。對不起。', `FemaleText_loc7`='Ahora estoy muy ocupada, joven $c. Discúlpame, por favor.' WHERE `ID`=13568;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='충분히 시간을 끌었다... 이제 게임을 끝낼 때가 됐구나!', `MaleText_loc4`='你们浪费了我太多的时间……让这场游戏结束吧！', `MaleText_loc5`='你已經浪費我很多時間了...讓這些遊戲結束吧!', `MaleText_loc7`='Ya me han hecho perder demasiado tiempo... ¡Acabemos con estos juegos!' WHERE `ID`=13569;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런, 쓸모가 없군! 분명 다른 방법이 있을 텐데...', `MaleText_loc4`='唉，没用！肯定还有其它的办法……', `MaleText_loc5`='呸，沒用!一定還有別的辦法...', `MaleText_loc7`='Bah, ¡es inútil! Tiene que haber otra forma...' WHERE `ID`=13570;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 아무 소용도 없습니다! 지지대로 떠받치지 않으면 건물이 무너지고 말 겁니다.', `MaleText_loc4`='太可怕了！如果我们不加固这根支柱的话，这座房子肯定会倒塌的。', `MaleText_loc5`='這根本一點用也沒有!如果我們不把支撐杆穩住，這棟建築物絕對會倒塌。', `MaleText_loc7`='¡Esto no va a funcionar! Sin duda los edificios se derrumbarán si no apuntalamos las vigas de apoyo.' WHERE `ID`=13571;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소용없다고 하지 않았습니까! 기초를 튼튼히 하지 않으면 건물 전체가 무너질 겁니다!', `MaleText_loc4`='这是什么玩意啊？！我们必须保护地基，否则这房子会全部倒塌的！', `MaleText_loc5`='這完全不行!我們必須把地基弄牢否則這整棟建築都會粉碎!', `MaleText_loc7`='¡Esto no servirá! Tenemos que asegurar los fundamentos o toda la estructura se desmoronará.' WHERE `ID`=13572;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 건물은 적어도 8가지 이상의 건축 규정을 위반했습니다!', `MaleText_loc4`='这个建筑至少违反了八项条例。', `MaleText_loc5`='這棟建築物起碼違反了8條法令!', `MaleText_loc7`='¡Esta construcción viola al menos ocho ordenanzas diferentes!' WHERE `ID`=13573;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='참사가 벌어져도 내겐 아무 책임이 없습니다. 아무 계획 없이 건물을 관리한 탓이니까요.', `MaleText_loc4`='我不会为这座必然倒塌的破烂建筑所造成的任何灾难负责的。', `MaleText_loc5`='隨意維修這棟建築物必然造成大災難，而我不會為此負責。', `MaleText_loc7`='No me responsabilizaré de la catástrofe que seguramente resultará del caótico mantenimiento de este edificio.' WHERE `ID`=13574;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠, 훨씬 좋아 보이는군. 안을 한번 살펴볼까...', `MaleText_loc4`='这个看上去就好多了，让我们看看里面。', `MaleText_loc5`='嗯，這樣看起來好多了。讓我們來看看裡面。', `MaleText_loc7`='Mmm, eso está mejor. Echemos un vistazo dentro.' WHERE `ID`=13575;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='킬제덴의 썩은 몸통에서 스며 나오는 더러운 기운에 뒤쪽 전체가 날아갔습니다! 어떻게 이런 곳에서 사람이 살겠습니까? 볼만큼 봤단 말입니다!', `MaleText_loc4`='亲娘唉，整个后墙都被炸开了！怎么有人会想要生活在这里？我看够了！', `MaleText_loc5`='在基爾加丹腐爛的軀體旁，整個後方都被炸開!怎麼有人能在這裡生活?我見過太多了!', `MaleText_loc7`='¡Por la nauseabunda tetilla del torso podrido de Kil''jaeden, toda la parte posterior ha sido eliminada! ¿Cómo se puede esperar que alguien viva aquí? ¡Ya he visto bastante!' WHERE `ID`=13576;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까? 저는 하늘 감시초소 건설을 감독하기 위해 엑소다르에서 파견됐습니다.', `MaleText_loc4`='你好，$c。我从埃索达被派来检查碧蓝岗哨的建筑。', `MaleText_loc5`='你好，$c。我從艾克索達被派到這裡監督藍色守望的建造工程。', `MaleText_loc7`='Saludos, $c. Me han enviado de El Exodar para supervisar la construcción de la Avanzada Azur.' WHERE `ID`=13577;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기계공학에 대해 배우고 싶습니다, 다엘로.', `MaleText_loc4`='戴罗，我想要学习工程学。', `MaleText_loc5`='我想學工程學，戴洛。', `MaleText_loc7`='Quiero aprender ingeniería, Daelo.', `FemaleText_loc1`='기계공학에 대해 배우고 싶어요, 다엘로.', `FemaleText_loc4`='戴罗，我想要学习工程学。', `FemaleText_loc5`='我想學工程學，戴洛。', `FemaleText_loc7`='Quiero aprender ingeniería, Daelo.' WHERE `ID`=13578;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물건을 두루 구경하고 싶습니다, 다엘로.', `MaleText_loc4`='戴罗，我想要看看你出售的货物。', `MaleText_loc5`='我想看看你的商品，戴洛。', `MaleText_loc7`='Deseo echarle un vistazo a tus mercancías, Daelo.', `FemaleText_loc1`='물건을 두루 구경하고 싶어요, 다엘로.', `FemaleText_loc4`='戴罗，我想要看看你出售的货物。', `FemaleText_loc5`='我想看看你的商品，戴洛。', `FemaleText_loc7`='Deseo echarle un vistazo a tus mercancías, Daelo.' WHERE `ID`=13579;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='할 일이 태산이군요! 일 좀 하게 내버려 둘 수는 없답니까?', `MaleText_loc4`='我有很多事要做！为什么他们不让我去工作？', `MaleText_loc5`='我有好多事要做!為什麼他們不能讓我做我的工作?', `MaleText_loc7`='¡Tengo mucho por hacer! ¿Por qué no me dejan trabajar?' WHERE `ID`=13580;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 고통스러운 비명을 지르며 손가락으로 주인을 가리킵니다.', `MaleText_loc4`='%s痛苦地尖叫着，并指向他的主人。', `MaleText_loc5`='%s痛苦的尖叫並指著他的主人。', `MaleText_loc7`='%s chilla de dolor y señala a su maestro.' WHERE `ID`=13582;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='변신 중에는 탈것을 탈 수 없습니다.', `MaleText_loc4`='你无法在该形态下骑乘。', `MaleText_loc5`='你不能在該形態下騎乘坐騎。', `MaleText_loc7`='No puedes montar estando transformado.', `FemaleText_loc1`='변신 중에는 탈것을 탈 수 없습니다.', `FemaleText_loc4`='你无法在该形态下骑乘。', `FemaleText_loc5`='你不能在該形態下騎乘坐騎。', `FemaleText_loc7`='No puedes montar estando transformado.' WHERE `ID`=13584;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='', `MaleText_loc4`='', `MaleText_loc5`='', `MaleText_loc7`='' WHERE `ID`=13585;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 좋은 친구, 아롱아. 넌 절대 날 떠나는 일이 없겠지. 그렇지, 얘야?', `FemaleText_loc4`='你是一位好朋友，咪咪。你永远都不会离开我，对吗？', `FemaleText_loc5`='你真是個好朋友，閃耀貓。你永遠都不會離開我吧，是嗎?', `FemaleText_loc7`='Eres tan bueno amigo, Titilín. No me dejarás nunca, ¿verdad?' WHERE `ID`=13586;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오직 너와 나뿐이로구나, 아롱아. 네 아버진 집에 돌아오지 않을 거란다.', `FemaleText_loc4`='就我和你，咪咪。爸爸不会回家的。', `FemaleText_loc5`='只有你和我，閃耀貓。爸爸不會再回家來了。', `FemaleText_loc7`='Solo estamos tú y yo, Titilín. Papá no va a venir a casa.' WHERE `ID`=13587;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='쫓아다닐 만한 재미있는 거라도 찾았니, 아롱아? 그래, 찾았구나!', `FemaleText_loc4`='你是不是找到可以追逐的玩具了，咪咪？我打赌肯定是的！', `FemaleText_loc5`='你發現什麼有趣的東西可以追逐了嗎，閃耀貓?我想你一定有!', `FemaleText_loc7`='¿Has encontrado algo con lo que divertirte por aquí? ¡Apuesto a que sí!' WHERE `ID`=13588;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋아요, 어서 가죠! 내가 완벽한 곳을 알고 있답니다!', `FemaleText_loc4`='好，我们走吧。我知道有个完美的地点！', `FemaleText_loc5`='好的，走吧。我知道有一個適合的好地方!', `FemaleText_loc7`='De acuerdo, vamos. ¡Conozco el sitio perfecto!' WHERE `ID`=13589;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아... 포도주를 맛보고 싶어 견딜 수가 없네요!', `FemaleText_loc4`='我迫不及待地想尝尝这瓶酒了！', `FemaleText_loc5`='我等不及想試試這酒了!', `FemaleText_loc7`='¡No puedo esperar a probar este vino!' WHERE `ID`=13590;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아니 이런! 나한테... 무슨 일이... 벌어지고 있는 거죠? 악! 이 고양이 좀 저리 치워줘요!', `FemaleText_loc4`='发生……了……什么事？把这只猫从我身边拿开！', `FemaleText_loc5`='我...發生了...什麼事?把這隻貓從我身上弄下來!', `FemaleText_loc7`='¿Qué... me está... ocurriendo? ¡Alejad este gato de mi vista!' WHERE `ID`=13591;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연금술사는 평범한 약초로 기적을 만들 수 있소. 치유 물약에서부터 수중 호흡이 가능한 물약까지 약초로 만들지 못하는 것은 없지.', `MaleText_loc4`='炼金师可以用普通的药草来创造奇迹，把它们转换成各种稳定的药水，比如治疗或者水下呼吸之类。', `MaleText_loc5`='鍊金師可以用普通的藥草來創造奇蹟，讓它們變成穩定的藥水，從治療到水下呼吸和其他各種效果都有。', `MaleText_loc7`='Un alquimista puede hacer milagros con hierbas ordinarias, convirtiéndolas en pociones estables cuyos efectos van desde curas a respirar bajo el agua, a todo lo que hay en medio.' WHERE `ID`=13592;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연금술사 훈련을 받고 싶습니다, 대달.', `MaleText_loc4`='我想要学习炼金术，丹达尔。', `MaleText_loc5`='我想接受訓練成為鍊金師，爹達歐。', `MaleText_loc7`='Deseo instruirme como alquimista, Daedal.', `FemaleText_loc1`='연금술사 훈련을 받고 싶어요, 대달.', `FemaleText_loc4`='我想要学习炼金术，丹达尔。', `FemaleText_loc5`='我想接受訓練成為鍊金師，爹達歐。', `FemaleText_loc7`='Deseo instruirme como alquimista, Daedal.' WHERE `ID`=13593;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물건을 좀 보여주십시오, 대달.', `MaleText_loc4`='请让我看看你的货物，丹达尔。', `MaleText_loc5`='請讓我看看你的商品，爹達歐。', `MaleText_loc7`='Permíteme echar un vistazo a tus mercancías, Daedal.', `FemaleText_loc1`='물건을 좀 보여주세요, 대달.', `FemaleText_loc4`='请让我看看你的货物，丹达尔。', `FemaleText_loc5`='請讓我看看你的商品，爹達歐。', `FemaleText_loc7`='Permíteme echar un vistazo a tus mercancías, Daedal.' WHERE `ID`=13594;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아롱이가 굶주림에 가득 찬 눈으로 비에라 선위스퍼를 쳐다봅니다.', `MaleText_loc4`='咪咪用饥饿的眼神看着薇拉·火语。', `MaleText_loc5`='閃耀貓用非常飢餓的眼神看著薇艾拉。', `MaleText_loc7`='Titilín mira a Viera Suspirosol con ojos famélicos.' WHERE `ID`=13595;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 연고를 그녀의 상처에 발라보죠.', `FemaleText_loc4`='现在把药膏涂在她的伤口上。', `FemaleText_loc5`='現在把藥膏塗到她的傷口上。', `FemaleText_loc7`='Ahora se aplica el ungüento en sus heridas.' WHERE `ID`=13596;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='흠, 연고가 별 효과 없는 것 같아요. 너무 안타까워요...', `FemaleText_loc4`='看上去这药膏没有起作用。真遗憾……', `FemaleText_loc5`='看來藥膏沒有效。真可惜...', `FemaleText_loc7`='Por lo visto, el ungüento no es efectivo. Lástima...' WHERE `ID`=13597;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠, 그녀를 치료할 방법이 아직 있을 것이오. 이쪽으로 오시오, $n. 필요한 걸 알려주겠소.', `MaleText_loc4`='可能还有个解决办法，到这边来，$n。我会向你解释我需要什么。', `MaleText_loc5`='還有一個辦法。過來，$n。我會解釋我需要什麼。', `MaleText_loc7`='Puede que aún haya solución. Ven aquí, $n. Te explicaré lo que necesito.' WHERE `ID`=13598;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거면 될 것이오...', `MaleText_loc4`='这个应该有作用……', `MaleText_loc5`='這應該會成功...', `MaleText_loc7`='Esto debería bastar...' WHERE `ID`=13599;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일어나십시오, 작은 친구. 그만 잠에서 깨십시오... 당신은 이제 안전합니다.', `MaleText_loc4`='醒来吧，小家伙。从睡眠中醒来吧……你现在安全了。', `MaleText_loc5`='醒醒啊小生物。從睡眠中醒來吧...你現在安全了。', `MaleText_loc7`='Despierta, criaturita. Despierta de tu sueño... Ahora estás a salvo.' WHERE `ID`=13600;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 낮은 소리로 신음합니다.', `FemaleText_loc4`='%s呻吟着。', `FemaleText_loc5`='%s呻吟了起來。', `FemaleText_loc7`='%s gruñe.' WHERE `ID`=13601;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 일어나 앉습니다.', `FemaleText_loc4`='%s坐了起来。', `FemaleText_loc5`='%s坐起身。', `FemaleText_loc7`='%s se incorpora.' WHERE `ID`=13602;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여... 여기가 어디지? 내... 내가 어디 있는거지?', `FemaleText_loc4`='我……我在哪里？这……这是什么地方？', `FemaleText_loc5`='我...我在哪裡?這...這是什麼地方?', `FemaleText_loc7`='¿Dó... Dónde estoy? ¿Qué... Qué es este lugar?' WHERE `ID`=13603;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='엘룬의 빛이여! 에레다르로군! 이 저주받은 악마들, 내게 무슨 짓을 한 거지? 내게는 동료가 있다. 지금까지 그랬던 것처럼 우린 끝까지 너희들과 싸우겠어! 난...', `FemaleText_loc4`='以艾露恩之光的名义！艾瑞达人！你们这群被诅咒的恶魔，你们对我做了什么？我并不是独身一人，我们会像以前那样和你们战斗到底！我……', `FemaleText_loc5`='以伊露恩之光之名!埃雷達爾!被詛咒的惡魔，你對我做了什麼?我不是一個人來的，我們會像以前一樣與你作戰!我...', `FemaleText_loc7`='¡POR LA LUZ DE ELUNE! ¡Eredar! ¿Malditos demonios, qué me han hecho? No he venido sola. ¡Lucharemos contra ustedes como ya hemos hecho! Yo...' WHERE `ID`=13604;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 다시 의식을 잃습니다.', `FemaleText_loc4`='%s昏了过去。', `FemaleText_loc5`='%s又昏迷過去。', `FemaleText_loc7`='%s vuelve a caer en coma.' WHERE `ID`=13605;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 숨을 헐떡거립니다.', `FemaleText_loc4`='%s喘了一口气。', `FemaleText_loc5`='%s喘氣。', `FemaleText_loc7`='%s ahoga un grito.' WHERE `ID`=13606;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오, 세상에...', `FemaleText_loc4`='啊……', `FemaleText_loc5`='喔天啊...', `FemaleText_loc7`='Vaya...' WHERE `ID`=13607;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='만아리... 하지만, 어떻게... 우린 에레다르가 아니에요! 그녀에게 알려야 해요! 그녀 같은 이가 있으면 반드시 찾아서 우리가 누군지 설명해 줘야만 해요...', `FemaleText_loc4`='腐蚀者……但是……我们不是艾瑞达人！她必须明白这一点！如果还有其他类似她的生物，我们必须找到他们，给他们解释……', `FemaleText_loc5`='曼那瑞...但是怎麼會...我們不是埃雷達爾!她必須知道!如果有其他人跟她一樣，我們一定要找到他們並向他們解釋...', `FemaleText_loc7`='Man''ari... Pero cómo... ¡No somos eredar! ¡Ella debe saberlo! Si hay otros como ella, debemos encontrarlos y explicar...' WHERE `ID`=13608;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 한숨을 쉽니다.', `MaleText_loc4`='%s叹了口气。', `MaleText_loc5`='%s嘆了一口氣。', `MaleText_loc7`='%s suspira.' WHERE `ID`=13609;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='비에라 선위스퍼가 아롱이에게서 도망치려고 허둥지둥 달아납니다.', `FemaleText_loc4`='薇拉·火语飞快地窜开，努力从咪咪那里逃走。', `FemaleText_loc5`='薇艾拉匆忙離開，想從閃耀貓那裡逃走。', `FemaleText_loc7`='Viera Suspirosol corre, intentando huir de Titilín.' WHERE `ID`=13610;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맹세코 성스러운 빛에 의해 그대는 이 무덤을 떠나게 될 것이오!', `MaleText_loc4`='以圣光的名义，离这座陵墓远一点！', `MaleText_loc5`='以聖光之名你將離開這座墳墓!', `MaleText_loc7`='¡Por la Luz! ¡Vete de esta tumba!' WHERE `ID`=13611;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하시오, $c|1이여;여;. 서리바람 야영지에는 무슨 일로 오셨소?', `MaleText_loc4`='你好，什么风把你吹到寒风营地来了？', `MaleText_loc5`='哈囉。什麼事讓你今天來到冰風營地?', `MaleText_loc7`='Hola. ¿Qué te trae por el Campamento del Orvallo hoy?' WHERE `ID`=13612;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 가봅시다, 친구.', `MaleText_loc4`='可以开始了吗，我的朋友？', `MaleText_loc5`='可以開始了嗎，我的朋友?', `MaleText_loc7`='¿Comenzamos, $gamigo mío:amiga mía;?' WHERE `ID`=13613;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 지역은 사악한 스컬지가 많기로 유명하니 방어 준비에 시간이 좀 걸릴지도 모르겠군. 잠시 기다릴 테니 준비하시오.', `MaleText_loc4`='这个区域到处都是天灾军团的爪牙，你最好准备一下，免得手忙脚乱。', `MaleText_loc5`='這個區域以充滿邪惡的天譴軍團為名。你可以花點時間準備你所有能做的防備。', `MaleText_loc7`='Se conoce que esta zona está llena de hediondos miembros de la Plaga. Puede que quieras tomarte unos momentos para preparar cualquier defensa que tengas a tu disposición.' WHERE `ID`=13614;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋소, 계속 갑시다.', `MaleText_loc4`='很好，我们继续前进吧。', `MaleText_loc5`='很好，我們繼續。', `MaleText_loc7`='Muy bien, sigamos.' WHERE `ID`=13615;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적의 공격이오! 조심하시오!', `MaleText_loc4`='小心！我们受到攻击了！', `MaleText_loc5`='小心!我們被攻擊了!', `MaleText_loc7`='¡Cuidado! ¡Nos atacan!' WHERE `ID`=13616;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스컬지가 우리를 공격하는 이유는 분명 빛의 수호자의 징표가 지닌 순수함 때문이오. 당하지 않으려면 조심해서 전진해야 하오!', `MaleText_loc4`='一定是光明使者的印记所散发出的纯洁气息把天灾军团吸引来了。我们必须加倍小心！', `MaleText_loc5`='一定是光明使者的印記的純淨把天譴軍團都吸引到我們這裡來了。我們一定要展開警戒否則會被制服!', `MaleText_loc7`='Debe de ser la pureza de la Marca del Iluminado la que atrae a la Plaga hacia nosotros. Hay que andar con cuidado. Puede que sean demasiados para nosotros si nos precipitamos.' WHERE `ID`=13617;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런, 다시 포위됐군! 방어하시오!', `MaleText_loc4`='又来了！小心！', `MaleText_loc5`='我們又被包圍了!做好防禦!', `MaleText_loc7`='¡Nos asedian! ¡Defendeos!' WHERE `ID`=13618;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 땅은 반드시 성스러운 빛으로 정화해야겠군! 자, 계속해서 무덤으로 갑시다. 얼마 안 남았소.', `MaleText_loc4`='这片土地真应该被圣光彻底净化！我们继续吧，陵墓就在前面。', `MaleText_loc5`='這塊土地真的需要被聖光淨化!讓我們繼續前往墓地。不遠了。', `MaleText_loc7`='¡Realmente esta tierra necesita ser limpiada por la Luz! ¡Sigamos hasta la tumba. Ya no está muy lejos.' WHERE `ID`=13619;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하신가! 오 이런, 드레나이로군!', `FemaleText_loc4`='你好！啊，老天，是个德莱尼人！', `FemaleText_loc5`='嗨!喔我的天啊，一個德萊尼!', `FemaleText_loc7`='¡Hola! ¡Oh, vaya, un draenei!' WHERE `ID`=13620;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='환영하오, 친구들!', `MaleText_loc4`='欢迎你，朋友！', `MaleText_loc5`='歡迎，朋友!', `MaleText_loc7`='¡Sed bienvenidos, amigos!' WHERE `ID`=13621;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 기억하고 여기까지 와주다니 고맙네. 그 상징이 꼭 필요한 건 아니었네만 그걸 되찾아 온 그대의 노력이 이 늙은이의 마음을 감동시키는군.', `MaleText_loc4`='感谢你专程来纪念我。你找回了这个印记——虽然它并没有什么实际的意义，但是仍然让我心里感到很温暖。', `MaleText_loc5`='謝謝你為了紀念我而來到這裡。你為了重拾象徵的努力，雖然是不必要的，但的確讓一個老人的心十分感動。', `MaleText_loc7`='Gracias por venir aquí en mi recuerdo. Sus esfuerzos por recuperar ese símbolo, aunque son innecesarios, sin duda son conmovedores para el corazón de un viejo.' WHERE `ID`=13622;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부디 일어나게, 내 친구여. 성스러운 빛의 힘을 나타내는 상징으로서 축복받은 마음을 간직하고 있으면, 오랫동안 모습을 감추었던 영웅들이 다시 한번 일어나 모든 이에게 용기를 줄 걸세.', `MaleText_loc4`='请起身吧，我的朋友。拿着这份祝福，它是圣光力量的象征，也可以时刻提醒我们，那些逝去的英雄其实一直活在我们的心中。', `MaleText_loc5`='喔，請起，我的朋友。讓這祝福成為聖光力量的象徵，以及那些早已逝去的英雄或許仍與我們同在的證明。', `MaleText_loc7`='Por favor, ponte en pie, $gamigo:amiga;. Guarda la bendición como un símbolo de la fuerza de la Luz y de cómo los héroes de antaño podrían volver a alzarse para inspirarnos a cada uno de nosotros.' WHERE `ID`=13623;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='친구여, 당신 덕분에 이번 일을 할 수 있었소. 고맙소이다. 오늘 일은 절대 잊을 수 없을 것이오! 난 잠시 여기서 우서 경께서 하신 말씀을 마음에 새기겠소. 당신은 서리바람 야영지의 대여사제 맥도널에게 돌아가시오. 그녀는 여기서 일어난 일들에 대해 매우 궁금해할 것이오.', `MaleText_loc4`='谢谢你，朋友。这一天我永远都不会忘怀！我想在这里待一会儿。请回到营地去找高阶牧师玛多妮尔，她一定对我们刚才遇到的事情很感兴趣。', `MaleText_loc5`='謝謝你讓這些成真，我的朋友。這是我永遠不會忘記的一天!我想我會留下來一會兒。請回去營地找高階牧師瑪多妮爾。我相信她會很想知道這裡發生的事。', `MaleText_loc7`='Gracias, $gamigo:amiga; por hacer esto posible. ¡Nunca olvidaré este día! Creo que me quedaré un rato. Por favor, vuelve al campamento con la suma sacerdotisa MacDowell. Sé que estará muy interesada en saber lo que ha ocurrido aquí.' WHERE `ID`=13624;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 이러는가? 생전에 내가 자네에게 무슨 잘못이라도 했는가?', `MaleText_loc4`='你为什么要这么做？我生前对你做过什么吗？', `MaleText_loc5`='你為什麼這樣做?難道我有冤枉你嗎?', `MaleText_loc7`='¿Por qué haces esto? ¿Te ofendí de algún modo en vida?' WHERE `ID`=13625;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 이제 자네가 무슨 생각인지 알겠군. 내 생전의 제자가 이런 일을 하다니... 메라 돈블레이드. 그의 마음이 그토록 사악하게 변했다니 정말 안타깝군그래.', `MaleText_loc4`='啊，我明白了。是我的学生让你来的……麦拉·黎明之刃。他的心灵竟然变得如此黑暗，这真令我伤心。', `MaleText_loc5`='啊，我在你心裡看見了它。這是我以前一個學生的工作...梅拉爾·曦刃。知道他的心變的如此黑暗真令人傷心。', `MaleText_loc7`='Ah, ahora lo veo en tu mente. Este es el trabajo de uno de mis antiguos alumnos... Mehlar Hojalba. Es triste saber que su corazón se ha vuelto tan oscuro.' WHERE `ID`=13626;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='메라에게 돌아가게. 돌아가서 내가 용서한다고 전해주게나. 그리고 그가 왜 그러는지 이해한다고도 전해 주게.', `MaleText_loc4`='回到他那里去吧。回去告诉麦拉，我原谅他，我也理解他为什么会那样想。', `MaleText_loc5`='回到他那裡。回去找梅拉爾並告訴他我原諒他，我也了解他為什麼他相信自己所做的事。', `MaleText_loc7`='Vuelve con él. Vuelve con Mehlar y dile que le perdono y que comprendo por qué cree en lo que hace.' WHERE `ID`=13627;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 안녕하시오.$B$B나는 접견 승인을 얻으려고 고위 영주의 참모분을 기다리고 있다오. 내 신분을 증명할 기회를 얻는 게 전쟁과도 같았다오.$B$B고위 영주이신 와일드해머님은 외부인을 경계 대상으로 간주한다는 얘기를 들었는데 직접 겪어보니 훨씬 심하구려. 페더비어드가 얼라이언스의 일원에게는 친절하다는 얘기를 들었소만 그를 만나면 상황이 좀 호전되었으면 하오.', `MaleText_loc4`='你好啊，$c。$B$B我正在等待鹰巢山国王的召见，要想争取这个机会还真是不容易。$B$B我听说蛮锤部族向来对外人“抱有警惕”，但显然他们不止有些警惕而已……希望在我见到羽须大人之后事情会有所改善，他似乎对联盟比较有好感。', `MaleText_loc5`='你好，$c。$B$B我在等一個大族長的顧問來信說明覲見的事。獲得機會呈現我的國書是很不容易的。$B$B我聽過蠻錘描述的「小心外來者」，但那後來被證實為不充分的陳述。希望我與羽鬚會面後事情會有所改善，聽說他與聯盟的關係密切。', `MaleText_loc7`='Buen día tengas, $c.$B$BEstoy esperando oír de uno de los consejeros de los Altos Señores feudales acerca de una audiencia. Fue una auténtica lucha solo el poder tener una oportunidad de presentar mis credenciales.$B$BHe oído describir al Martillo Salvaje como "cauteloso con los forasteros", pero se ha demostrado que eso es un eufemismo. Con algo de suerte las cosas mejorarán cuando tenga la oportunidad de reunirme con Barbapluma, quien, según me han dicho, aprueba un vínculo más estrecho con la Alianza.' WHERE `ID`=13628;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cffffff00얼라이언스가 역병숲 경비탑을 점령했습니다!|r', `MaleText_loc4`='|cffffff00联盟占领了病木林哨塔！|r', `MaleText_loc5`='|cffffff00病木林哨塔已被聯盟奪去!|r', `MaleText_loc7`='|cffffff00¡La Alianza se ha hecho con el control de la Torre del Bosque de la Peste!|r' WHERE `ID`=13629;
