UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cffffff00얼라이언스가 산마루 경비탑을 점령했습니다!|r', `MaleText_loc4`='|cffffff00联盟占领了皇冠哨塔！|r', `MaleText_loc5`='|cffffff00皇冠哨塔已被聯盟奪去!|r', `MaleText_loc7`='|cffffff00¡La Alianza se ha hecho con el control de la Torre de la Corona!|r' WHERE `ID`=13632;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cffffff00호드가 산마루 경비탑을 점령했습니다!|r', `MaleText_loc4`='|cffffff00部落占领了皇冠哨塔！|r', `MaleText_loc5`='|cffffff00皇冠哨塔已被部落奪去!|r', `MaleText_loc7`='|cffffff00¡La Horda se ha hecho con el control de la Torre de la Corona!|r' WHERE `ID`=13633;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cffffff00호드가 역병숲 경비탑을 점령했습니다!|r', `MaleText_loc4`='|cffffff00部落占领了病木林哨塔！|r', `MaleText_loc5`='|cffffff00病木林哨塔已被部落奪去!|r', `MaleText_loc7`='|cffffff00¡La Horda se ha hecho con el control de la Torre del Bosque de la Peste!|r' WHERE `ID`=13634;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cffffff00호드가 북부관문 경비탑을 점령했습니다!|r', `MaleText_loc4`='|cffffff00部落占领了北地哨塔！|r', `MaleText_loc5`='|cffffff00北地哨塔已被部落奪去!|r', `MaleText_loc7`='|cffffff00¡La Horda se ha hecho con el control de la Torre del Paso Norte!|r' WHERE `ID`=13635;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cffffff00호드가 동부방벽 경비탑을 점령했습니다!|r', `MaleText_loc4`='|cffffff00部落占领了东墙哨塔！|r', `MaleText_loc5`='|cffffff00東牆之塔已被部落奪去!|r', `MaleText_loc7`='|cffffff00¡La Horda se ha hecho con el control de la Torre de la Muralla del Este!|r' WHERE `ID`=13636;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cffff0000호드에게 영광 있으리! 이 땅은 이제 우리 것이다!|r', `MaleText_loc4`='|cffff0000部落控制了四座哨塔！|r', `MaleText_loc5`='|cffff0000所有四個哨塔現在都在部落的控制之下了!|r', `MaleText_loc7`='|cffff0000¡La Horda se ha hecho con el control de la totalidad de las torres!|r' WHERE `ID`=13637;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cff33ccff얼라이언스 만세! 이 지역은 이제 안전하다!|r', `MaleText_loc4`='|cff33ccff联盟控制了四座哨塔！|r', `MaleText_loc5`='|cff33ccff所有四個哨塔現在都在聯盟的控制之下了!|r', `MaleText_loc7`='|cff33ccff¡La Alianza se ha hecho con el control de la totalidad de las Torres!|r' WHERE `ID`=13638;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭘 원하죠?$B$B아무런 이유도 없이 낯선 사람에게 다가오는 건 무례한 행동이라고 생각하지 않나요?', `FemaleText_loc4`='你要干什么？$B$B没有理由就靠近一个陌生人，你不觉得有点粗鲁吗？', `FemaleText_loc5`='你想要什麼?$B$B毫無理由的走到陌生人身旁搭訕有點無禮，你不覺得嗎?', `FemaleText_loc7`='¿Qué quieres?$B$BNo es muy cortés dirigirse a un desconocido sin ninguna razón, ¿no crees?' WHERE `ID`=13639;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 바라는 것은 오직 그가 성스러운 빛의 정의를 깨닫고 열정을 다해 한때 아름다웠던 쿠엘탈라스를 재건하는 것뿐이라네.', `MaleText_loc4`='我只希望他能看到圣光，用他的力量来恢复曾经美丽的奎尔萨拉斯。', `MaleText_loc5`='我只希望他能看見聖光並用他的能量讓曾經美麗的奎爾薩拉斯恢復以往的面貌。', `MaleText_loc7`='Solo me queda esperar que vea la Luz y, en su lugar, centre sus energías en restaurar la antes bella Quel''Thalas.' WHERE `ID`=13640;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, 친구. ''쿠키''는 제 이름이고 요리는 제가 좋아하는 일이랍니다. 맥위크소스는 섬세한 감각을 가진 고객들을 만족시키고자 봉사하는 요리사와 상인을 배출한 유서 깊은 가문이랍니다.', `MaleText_loc4`='你好啊，朋友。我的名字叫曲奇，烹饪是我的游戏。米维克索斯是个以烹饪和贸易著称的家族。', `MaleText_loc5`='且慢，朋友。小廚是我的名字，烹飪是我的拿手絕活。麥克威醬的血統是世代流傳的廚師與商人，專門取悅感官細緻的男男女女。', `MaleText_loc7`='$gQuieto:Quieta;, $gcompañero:compañera;. El Cocinitas soy yo, y lo que me va es cocinar. Los MacSalsafloja somos una familia con una larga tradición cocinera y mercader. Sabemos como satisfacer los más delicados paladares.' WHERE `ID`=13641;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요리를 가르쳐 주십시오, 쿠키.', `MaleText_loc4`='教我怎么烹饪吧，曲奇。', `MaleText_loc5`='教我如何烹飪，廚師。', `MaleText_loc7`='Enséñame a cocinar, Cocinitas.', `FemaleText_loc1`='요리를 가르쳐 주세요, 쿠키.', `FemaleText_loc4`='教我怎么烹饪吧，曲奇。', `FemaleText_loc5`='教我如何烹飪，廚師。', `FemaleText_loc7`='Enséñame a cocinar, Cocinitas.' WHERE `ID`=13642;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물건을 보고 싶습니다, 쿠키.', `MaleText_loc4`='让我看看你的货物，曲奇。', `MaleText_loc5`='讓我看看你的商品，廚師。', `MaleText_loc7`='Déjame ver tu mercancía, Cocinitas.', `FemaleText_loc1`='물건을 보고 싶어요, 쿠키.', `FemaleText_loc4`='让我看看你的货物，曲奇。', `FemaleText_loc5`='讓我看看你的商品，廚師。', `FemaleText_loc7`='Déjame ver tu mercancía, Cocinitas.' WHERE `ID`=13643;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, 뭐 필요하신 게 있나요?', `FemaleText_loc4`='需要什么东西吗？', `FemaleText_loc5`='需要什麼嗎?', `FemaleText_loc7`='¿Necesitas algo?' WHERE `ID`=13644;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대장장이가 되고 싶습니다.', `MaleText_loc4`='我想成为一个铁匠。', `MaleText_loc5`='我想成為一名鐵匠。', `MaleText_loc7`='Quiero ser herrero.', `FemaleText_loc1`='대장장이가 되고 싶어요.', `FemaleText_loc4`='我想成为一个铁匠。', `FemaleText_loc5`='我想成為一名鐵匠。', `FemaleText_loc7`='Quiero ser herrero.' WHERE `ID`=13645;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물건을 보여주십시오, 칼리프소.', `MaleText_loc4`='让我看看你出售的货物，卡里普索。', `MaleText_loc5`='讓我看看你的商品，卡利比索。', `MaleText_loc7`='Déjame ver tu mercancía, Calypso.', `FemaleText_loc1`='물건을 보여주세요, 칼리프소.', `FemaleText_loc4`='让我看看你出售的货物，卡里普索。', `FemaleText_loc5`='讓我看看你的商品，卡利比索。', `FemaleText_loc7`='Déjame ver tu mercancía, Calypso.' WHERE `ID`=13646;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멀리에서 고대의 존재가 깨어납니다...', `MaleText_loc4`='一个远古的生物在远处被唤醒了……', `MaleText_loc5`='一個古老的生物在遠處甦醒過來...', `MaleText_loc7`='Un ser antiguo se despierta en la distancia...' WHERE `ID`=13647;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카라잔의 신비를 캐내고자 필멸의 존재들이 또 찾아왔다고?', `MaleText_loc4`='还有更多的凡人来探索卡拉赞的秘密吗？', `MaleText_loc5`='更多凡人來尋找卡拉贊的秘密了嗎?', `MaleText_loc7`='¿Han venido más mortales buscando los misterios de Karazhan?' WHERE `ID`=13648;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 멍청하군! 고통 없이 빨리 끝내주마!', `MaleText_loc4`='愚蠢的家伙！我会很快终结你们的痛苦！', `MaleText_loc5`='真是蠢蛋!我會快點結束你的痛苦!', `MaleText_loc7`='¡Necios! ¡Voy a acabar rápidamente con tu sufrimiento!' WHERE `ID`=13649;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 성스러운 빛이 함께하기를...', `MaleText_loc4`='愿圣光与你同在，$C。', `MaleText_loc5`='聖光與你同在，$c。', `MaleText_loc7`='Que la Luz te acompañe, $c.' WHERE `ID`=13650;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마침내 도와줄 이가 온 것 같군요! 오메나이에서 당신을 생존자들의 야영지로 안내해 줄 겁니다, $n.', `FemaleText_loc4`='似乎援兵终于来了！欧麦尼欢迎你来到我们的营地，$n。', `FemaleText_loc5`='看來援助終於到達!歐曼奈歡迎你來到我們的遺風營地，$n。', `FemaleText_loc7`='¡Parece que por fin ha llegado la ayuda! Los omenai te damos la bienvenida a los restos de nuestro campamento, $n.' WHERE `ID`=13651;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이칸은 넝마두건 일족에게 빛의 길을 알려주기 위해 끊임없이 노력하는 친구지. 내 생각에 넝마두건 일족은 잃어버린 드레나이와 매우 비슷한 처지야...', `MaleText_loc4`='伊坎试了又试。我想这些残冠氏族的人更像是失落者，你知道……那些失落了的……', `MaleText_loc5`='依坎試了又試。我想這些崔互德很像失落者，你知道...失落。', `MaleText_loc7`='Ikan lo intenta una y otra vez. Creo que esos Zarrapuchas son muy parecidos a Los Perdidos, ya sabes... perdidos.' WHERE `ID`=13652;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간은 좀 걸리겠지만 이 뒤틀린 드레나이들은 성스러운 빛의 길에 대해 알게 될 거요!', `MaleText_loc4`='可能会需要一段时间，但这些破碎者终将学会如何使用圣光！', `MaleText_loc5`='這會花點時間，但這些破碎者會了解聖光之道!', `MaleText_loc7`='¡Llevará su tiempo, pero estos Tábidos aprenderán los caminos de la Luz!' WHERE `ID`=13653;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오게나, $n. 나는 검은 불길을 관리하고 있는 랜드로 롱샷이라고 하네. 아마 검은 불길에 대한 얘기는 한 번도 들어보지 못했을 걸세. 우리가 일하는 방식을 생각해 보면 그리 놀랄 일은 아니지. 우리는 복잡하게 얽히는 걸 좋아하지 않거든.$B$B검은 불길은 돈으로 살 수 있는 최고의 서비스와 재미를 제공하는 일을 전문으로 한다네. 아주 찾기 어려운 물건을 찾아주는 일이나 검투사 경기나 돈이 벌리는 경기가 될 수도 있지.$B$B뭐 특별히 찾는 게 있나?', `MaleText_loc4`='你好，$n，我是兰德鲁·郎绍特，黑色烈焰的主管。这或许是你第一次听说黑色烈焰。我对此并不惊讶，因为我们向来低调。我们希望能够避免……派系争斗。$B$B黑色烈焰一贯致力于提供最好的服务和娱乐。只要你出得起价钱，不管是稀有的物品，刺激的战斗还是赚钱的游戏机会，我们都能提供。$B$B你是来找什么特殊的东西的吗？', `MaleText_loc5`='歡迎，$n。我是藍卓·長射-黑色烈焰的管理者。也許在此之前你並沒有聽過黑色烈焰這個名詞。我一點都不驚訝，因為我們一向都保持低調。我們寧願避開...派系與種族之間的鬥爭。$B$B黑色烈焰專門提供錢所能買的到最好的娛樂服務，不論是難以尋找的寶物、決鬥場的戰鬥或者一擲千金的賭局。$B$B你是來這裡找什麼獨特的東西嗎?', `MaleText_loc7`='Te doy la bienvenida, $n. Soy Landro Tirolargo, patrón de la Llama Negra. Puede que sea la primera vez que oyes hablar de mi local. No me sorprende; hacemos todo lo posible para que no se hable demasiado de nosotros. Hay que evitar meterse en líos entre las facciones.$B$BEn la Llama Negra nos especializamos en ofrecer los mejores servicios y el mejor entretenimiento que el dinero puede comprar; desde objetos difíciles de encontrar hasta peleas de gladiadores, pasando por lucrativos juegos de azar.$B$B¿Buscas algo en particular?' WHERE `ID`=13654;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 취급하십니까?', `MaleText_loc4`='你有什么促销品？', `MaleText_loc5`='有什麼可以推薦的嗎?', `MaleText_loc7`='¿Qué ofertas tienes?', `FemaleText_loc1`='뭘 취급하시나요?', `FemaleText_loc4`='你有什么促销品？', `FemaleText_loc5`='有什麼可以推薦的嗎?', `FemaleText_loc7`='¿Qué ofertas tienes?' WHERE `ID`=13655;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 신기하고 진귀한 물건 말이로군. 우린 안목 있는 여행자들을 위한 아제로스의 희귀한 물건들을 전문으로 취급하지.$B$B이렇게 나를 찾아온 걸 보니 자넨 찾는 물건이 있는 게로군. 자, $n, 어떤 물건에 관심이 있나?', `MaleText_loc4`='啊，奇珍异宝。我们收集艾泽拉斯各地的宝物，为强大的冒险者服务。$B$B既然你来找我，那么想必你已经知道自己想要什么了，$n。', `MaleText_loc5`='喔 - 古怪與稀奇。我們專精於艾澤拉斯的獨一無二的物品，專給別具眼光的冒險。$B$B自從你和我談過之後，你一定早就知道自己想要什麼了。那麼，$n，你對那樣東西有興趣?', `MaleText_loc7`='Ah, rarezas y artículos poco comunes. Estamos especializados en los objetos totalmente únicos de Azeroth para los aventureros más exigentes.$B$BSupongo que si estás hablando conmigo es porque tienes una idea de lo que estás buscando. Dime, $n, ¿qué es lo que te interesa?' WHERE `ID`=13656;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='붉은색 휘장', `MaleText_loc4`='红色徽章', `MaleText_loc5`='紅色徽章', `MaleText_loc7`='Tabardo rojo', `FemaleText_loc1`='붉은색 휘장', `FemaleText_loc4`='红色徽章', `FemaleText_loc5`='紅色徽章', `FemaleText_loc7`='Tabardo rojo' WHERE `ID`=13657;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙소, $g형제:자매;여.', `MaleText_loc4`='兄弟，谢谢你。', `MaleText_loc5`='謝謝你，兄弟。', `MaleText_loc7`='Gracias, hermano.' WHERE `ID`=13658;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내가 매의 감시탑에 가는 걸 막을 순 없어!', `FemaleText_loc4`='你休想阻止我到达猎鹰岗哨！', `FemaleText_loc5`='你阻止不了我前往獵鷹哨站!', `FemaleText_loc7`='¡No me impediréis que llegue a la Avanzada del Halcón!' WHERE `ID`=13659;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='축복을 내려주셔서 감사합니다, $n!', `MaleText_loc4`='谢谢你的祝福，$n。', `MaleText_loc5`='謝謝你的祝福，$n。', `MaleText_loc7`='Gracias por la bendición, $n.' WHERE `ID`=13660;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 아무도 절 막을 수 없습니다!', `MaleText_loc4`='现在没有任何东西可以阻止我了！', `MaleText_loc5`='現在沒有任何事能阻止我!', `MaleText_loc7`='¡Ahora nada puede detenerme!' WHERE `ID`=13661;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 그대의 축복은 언제라도 환영입니다.', `MaleText_loc4`='谢谢你的祝福，$n。', `MaleText_loc5`='永遠歡迎你的祝福，$n。', `MaleText_loc7`='Siempre agradeceré tu bendición, $n.' WHERE `ID`=13662;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='필요한 거라도 있으신가요, $c님? 제가 도와드리겠습니다.', `FemaleText_loc4`='你需要什么东西吗，$c？也许我可以帮助你。', `FemaleText_loc5`='你需要什麼嗎，$c?或許我可以幫你。', `FemaleText_loc7`='¿Necesitas algo, $c? Quizás pueda ayudarte.' WHERE `ID`=13663;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필멸의 생명체들아, 이제 내게서 도망칠 수 없다!', `MaleText_loc4`='休想逃过我的眼睛，凡人！', `MaleText_loc5`='你瞞不了我的，凡人!', `MaleText_loc7`='¡No puedes esconderte de mí, mortal!' WHERE `ID`=13664;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 기침을 하며 숨을 헐떡이기 시작합니다.', `MaleText_loc4`='%s咳嗽了一下，然后开始喘息。', `MaleText_loc5`='%s咳嗽並開始氣喘。', `MaleText_loc7`='%s tose y comienza a resollar.' WHERE `ID`=13665;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고마워요, $n. 이제 저들이 잘 지낼 것 같군요.', `FemaleText_loc4`='谢谢你，$n。他们应该没什么问题。', `FemaleText_loc5`='謝謝你，$n。看來他們會相處的很愉快。', `FemaleText_loc7`='Gracias, $n. Parece que se van a llevar de maravilla.' WHERE `ID`=13666;
