UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만! 내 친히 내려가서 너희를 짓이겨주마!', `MaleText_loc4`='够了！我要落下来把你们打得粉碎！', `MaleText_loc5`='夠了!我要親自挑戰你!', `MaleText_loc7`='¡Ya basta! Voy a aterrizar y a aplastarte yo mismo.' WHERE `ID`=13676;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하루살이 같은 놈들! 나의 힘을 똑똑히 보여주겠다!', `MaleText_loc4`='没用的虫子！让你们见识一下我的力量吧！', `MaleText_loc5`='昆蟲!給你們近距離嚐嚐我的厲害!', `MaleText_loc7`='¡Insectos! ¡Os enseñaré mi fuerza de cerca!' WHERE `ID`=13677;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음... 대단해... 정말 강력한 혼합물이로군!', `MaleText_loc4`='……一种强效的混合剂！', `MaleText_loc5`='...高效混合物!', `MaleText_loc7`='...un brebaje potente.' WHERE `ID`=13678;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만, 어디서 저자와 같은 적당한 실험 대상을 찾을 수 있겠소?', `MaleText_loc4`='但是我在哪里才能找到合适的实验品呢？', `MaleText_loc5`='但是我要去哪裡找適合的試驗物?', `MaleText_loc7`='Pero, ¿dónde podría encontrar un sujeto apropiado para la prueba?' WHERE `ID`=13682;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 이걸 마셔라, 이 푸른 괴물아! 내 말을 듣지 않으면 천천히 아주 고통스러운 죽음을 안겨주겠다!', `MaleText_loc4`='喝下这个，你这个蓝色的野蛮人！否则我保证会把你折磨致死！', `MaleText_loc5`='喝下去，你這個藍色的畜生!不服從的話我保證會讓你慢慢地痛苦地死去!', `MaleText_loc7`='¡Bébete esto, bestia azul! ¡Si me desobedeces, te prometo una muerte lenta y dolorosa!' WHERE `ID`=13683;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠... 새 실험 대상을 찾아야겠는데...', `MaleText_loc4`='唔……好像我需要一个新的测试课题。', `MaleText_loc5`='嗯...看來我需要一個新的試驗物。', `MaleText_loc7`='Mmm... parece que necesitamos una cobaya nueva.' WHERE `ID`=13684;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불쌍하구려, 포세이큰이여. 당신의 영혼에는 빛이 없소이다.', `MaleText_loc4`='我怜悯你，被遗忘者。你的灵魂暗淡无光。', `MaleText_loc5`='我可憐你，被遺忘者。你的靈魂沒有光芒。', `MaleText_loc7`='Te compadezco, Renegado. Tu alma carece de luz.' WHERE `ID`=13685;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='디부운, 당신인가요?', `FemaleText_loc4`='戴维恩，是你吗？', `FemaleText_loc5`='戴伏恩，是你嗎?', `FemaleText_loc7`='Dyvuun, ¿eres tú?' WHERE `ID`=13686;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나요, 자나. 여기 있소! 신호가 약하군.', `MaleText_loc4`='是的，沙娜安，是我！你的信号很弱。', `MaleText_loc5`='是的，薩那，是我!你的信號相當微弱。', `MaleText_loc7`='¡Sí, Zhanaa, soy yo! Tu señal es débil.' WHERE `ID`=13687;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘 안 들려요... <잡음> 아이, 참! 크게 말씀하세요!', `FemaleText_loc4`='我根本听不到你……<噪音>大声点！', `FemaleText_loc5`='我聽不太到你的聲音...<靜止>大聲點!', `FemaleText_loc7`='Apenas te oigo... <estático> ¡pertando!' WHERE `ID`=13688;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s의 속박이 약해지기 시작합니다!', `MaleText_loc4`='%s的禁锢开始变弱！', `MaleText_loc5`='%s的束縛開始變弱!', `MaleText_loc7`='¡Las cuerdas de %s empiezan a aflojarse!' WHERE `ID`=13689;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 속박에서 거의 풀려났습니다!', `MaleText_loc4`='%s快要从他的禁锢中挣脱了！', `MaleText_loc5`='%s就快要解開束縛了!', `MaleText_loc7`='¡%s casi está libre de sus cadenas!' WHERE `ID`=13690;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 완전히 풀려났습니다!', `MaleText_loc4`='%s挣脱了！', `MaleText_loc5`='%s重獲自由了!', `MaleText_loc7`='¡%s se libera!' WHERE `ID`=13691;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자나! 이런, 이걸 꼭 고쳐야겠군!', `MaleText_loc4`='沙娜安！啊，我得把这东西赶快搞定！', `MaleText_loc5`='薩那!哦,我需要修復它!', `MaleText_loc7`='¡Zhanaa! ¡Ag, tengo que arreglar esta cosa!' WHERE `ID`=13692;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙다, 주술사여. 너의 도움으로 나는 다시 태어났다. 그리고 예전보다 훨씬 더 밝게 타오를 것이다!', `MaleText_loc4`='谢谢你，萨满祭司。我已经获得了新生！', `MaleText_loc5`='謝謝你，薩滿。我重生了，將會燃燒前所未有最明亮的火焰!', `MaleText_loc7`='Gracias, chamán. ¡He vuelto a nacer y brillaré con más fuerza que nunca!' WHERE `ID`=13693;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 마지못해 말하는 것처럼 열화를 훑어봅니다.', `MaleText_loc4`='%s看着坦普，似乎想要说些什么。', `MaleText_loc5`='%s仔細查看暴躁者好像不情願說話。', `MaleText_loc7`='%s mira a Templar como si no quisiera hablar.' WHERE `ID`=13694;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 너! 언제라도 침입자가 접근할 가능성이 있으니까 이쪽 성벽을 자세히 살펴봐라!', `MaleText_loc4`='你！密切留意城墙上的一举一动，入侵者随时可能来犯！', `MaleText_loc5`='你!盯好這些堡壘，入侵者隨時都可能逼近!', `MaleText_loc7`='¡Eh, tú! ¡Vigila atentamente esas murallas, los intrusos podrían acercarse en cualquier momento!' WHERE `ID`=13695;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='유령의 땅은 군사력만 가지고는 되찾기 어려울 겁니다. 우리 마법학자들이 필요하죠.$B$B비전 마법에 대한 우리의 계략과 지식은 당할 자가 없습니다.', `MaleText_loc4`='幽暗之地仅靠军事力量是无法夺回的，$n。我们魔导师才是关键。$B$B我们的狡诈和魔法知识是无往而不利的。', `MaleText_loc5`='鬼魂之地不會被軍事武力給贏回去的，$n。那是我們博學者進來的地方。$B$B我們秘法的奸詐和知識是無與倫比的。', `MaleText_loc7`='Las Tierras Fantasma no se recuperarán con solo la fuerza militar, $n. Aquí es donde entran en juego los magistri.$B$BNuestra astucia y nuestro conocimiento de lo Arcano no tienen igual.' WHERE `ID`=13697;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이보라고, 쿠키! 오늘 저녁은 뭔가? 제발 닭고기만은... 이제 질렸으니까!', `MaleText_loc4`='嘿，曲奇！今天晚餐咱们吃了什么？不要告诉我是鸡肉！', `MaleText_loc5`='嘿，廚師!今天晚餐吃什麼?不要跟我說又是雞肉!', `MaleText_loc7`='¡Eh, Cocinitas! ¿Qué hay hoy para cenar? ¡No me digas que pollo!' WHERE `ID`=13698;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어, 함장님. 생각할 시간을 좀... 으음... 결정했습니다.', `MaleText_loc4`='呀，将军。让我考虑一下……啊……有了。', `MaleText_loc5`='啊，上將。讓我想一想...呃...就快進入焦點了。', `MaleText_loc7`='Ehhh, admirante. Déjame pensar en ello... Ehhh... Se está centrando.' WHERE `ID`=13699;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='육즙이 많은 돼지 갈비와 샌더 선장의 비밀 소스로 양념한 옆구리살을 준비하지요.', `MaleText_loc4`='我计划给大家烹制浇着美味肉汁、还有一点点杉德尔船长特制配方的鲜嫩多汁的烤猪排。', `MaleText_loc5`='它看起來是塗上特有醬汁所烤的多汁豬肋排和桑德爾船長秘密沾醬 - 沾一下。', `MaleText_loc7`='Parece que ser suculentas costillas de cerdo con su propio y delicioso jugo y la salsa secreta del capitán Sanders – para mojar.' WHERE `ID`=13700;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 후식으론 천사들의 날개에 실어 스톰윈드에서 공수해 온 신선한 치즈 케이크가 좋겠군요.', `MaleText_loc4`='而且我们有从暴风城空运过来的奶酪蛋糕作为餐后甜品。', `MaleText_loc5`='我們的甜點是起司蛋糕，經由天使的翅膀從暴風城新鮮到貨...', `MaleText_loc7`='Y, de postre, tendremos pastel de queso, traído volando bien fresco desde Ventormenta en alas de ángeles...' WHERE `ID`=13701;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오오! 정말인가?', `MaleText_loc4`='是不是啊？这么棒？', `MaleText_loc5`='哇!真的嗎?', `MaleText_loc7`='¡Vaya! ¿De veras?' WHERE `ID`=13702;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니요, 아... 닙니다...', `MaleText_loc4`='显然不是……', `MaleText_loc5`='不。不盡如此...', `MaleText_loc7`='No. No realmente...' WHERE `ID`=13703;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='송구스럽지만... 닭고기입니다...', `MaleText_loc4`='还是鸡肉……', `MaleText_loc5`='是雞肉...', `MaleText_loc7`='Ser pollo...' WHERE `ID`=13704;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 녀석이 정말 밉구나, 쿠키.', `MaleText_loc4`='我恨你，曲奇。', `MaleText_loc5`='我好恨你，廚師。', `MaleText_loc7`='Te odio, Cocinitas.' WHERE `ID`=13705;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='<여사제 킬린 일디나레가 수상한 눈으로 당신을 바라봅니다.>', `FemaleText_loc4`='<女祭司伊尔蒂娜怀疑地看着你。>', `FemaleText_loc5`='<女牧師伊丹奈爾懷疑地看著你。>', `FemaleText_loc7`='<La sacerdotisa Il''dinare te mira con recelo.>' WHERE `ID`=13706;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이방인이여, 전 나이트 엘프입니다. 그대는 우리 종족에 대해 아는 게 없겠지만 우린 그대와 그대의 선조에 대해 잘 알고 있답니다. 그대들은 스스로 에레다르라고 부르지 않을지도 모르지만, 겉모습만 보면 비슷한 점이 많습니다.$B$B제 동맹을 도와주신 점에 대해서는 감사를 드립니다. 하지만, 지금으로서는 그대들을 완전히 믿을 수가 없군요. 때가 되면 의심도 풀리고 제 걱정도 사라지겠죠.', `FemaleText_loc4`='我是个暗夜精灵，陌生人。虽然你也许对我的种族一无所知，但我们早已对你和你的祖先了如指掌。你可以不把自己称为艾瑞达人。但是，在外形上你们有很多相似点。$B$B你帮了我的朋友们，我对此非常感谢；从现在开始，你就要独自走上危机四伏的道路。也许过不了多久，你可以消除我心中的恐惧和疑虑。', `FemaleText_loc5`='我是個夜精靈，陌生人。雖然你對我的種族沒有任何了解，但我們對你和你的祖先卻相當清楚。你雖然不自稱埃雷達爾，但從外表看來，你們有很多共同點。$B$B你幫助了我的盟友，因此我很感激;但你目前的情況暫時是如履薄冰。或許時間久了，你就能解開我心中的疑慮和恐懼。', `FemaleText_loc7`='Soy una elfa de la noche, $gextranjero:extranjera;. Aunque puede que no sepas nada de mi especie, nosotros sabemos mucho de ti y de tus progenitores. Puede que no te llames eredar, pero, en apariencia, compartís muchas similitudes.$B$BHas ayudado a mis aliados, y te estoy agradecida por ello; pero, por el momento, andas por un camino incierto. Quizás con el tiempo puedas disipar las dudas y temores que albergo en el corazón.' WHERE `ID`=13707;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$r|1이여;여;, 안녕하신가요. 그대가 훌륭한 일을 한다는 걸 알고 있답니다. 엘룬의 가호가 함께하기를...', `FemaleText_loc4`='你好，$r。你高尚的行为已经得到了认可。愿艾露恩保佑你。', `FemaleText_loc5`='你好，$r。你高尚的行為是大家公認的。願伊露恩保護你。', `FemaleText_loc7`='Saludos, $r. Tus nobles acciones han sido reconocidas. Que Elune te proteja.' WHERE `ID`=13708;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서부터는 조심하시오, 이방인 친구.', `MaleText_loc4`='小心一点，陌生人。', `MaleText_loc5`='在這裡要小心你的腳步，陌生人。', `MaleText_loc7`='Ándate con cuidado, forastero.' WHERE `ID`=13709;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금까지 당신은 우리에게 큰 도움이 되었소. 이 야영지의 다른 이들도 좀 도와주는 건 어떻겠소?$B$B그리고 그 고블린들은 내가 알아서 처리할 테니 신경 쓰지 마시오.', `MaleText_loc4`='迄今为止，你帮了我们不少忙，$n。营地附近还有其他人需要你的帮助呢。$B$B别担心那些地精，我会妥善安排好一切的。', `MaleText_loc5`='到現在為止你幫了很大的忙，$n。你對營地的其他人也會很有助益。$B$B不要擔心那些哥布林，我處理好所有的事了。', `MaleText_loc7`='Has sido de gran ayuda hasta ahora, $n. Harías bien en ayudar a los demás en el campamento.$B$BY no te preocupes por esos goblins, me estoy haciendo cargo de todo.' WHERE `ID`=13710;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아다만트 님, 이 서판을 좀 보시고 룬 문자를 해독해 주시겠어요?', `FemaleText_loc4`='阿达曼特，你能看下这块石板，顺便试着翻译一下上面的符文吗？', `FemaleText_loc5`='阿達曼，可以請你看一下這塊石板並試譯它的符文嗎?', `FemaleText_loc7`='Adamant, ¿podrías echarle un vistazo a esta tablilla para intentar descifrar las runas?' WHERE `ID`=13711;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 물론입니다! 아름다우신 여사제님, 당신을 위해서라면 무엇이든지 합지요!', `MaleText_loc4`='当然！没问题，亲爱的！', `MaleText_loc5`='當然!為了你什麼都可以，親愛的!', `MaleText_loc7`='¡Por supuesto! ¡Cualquier cosa por ti, cariño!' WHERE `ID`=13712;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자. 어디 서판을 좀 볼까요?', `MaleText_loc4`='嗯，让我看看那块石板。', `MaleText_loc5`='好吧，讓我看看那塊石板。', `MaleText_loc7`='De acuerdo, déjame echarle un vistazo a esa tablilla.' WHERE `ID`=13713;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 드워프어로 중얼거리며 천천히 서판을 읽습니다.', `MaleText_loc4`='%s慢慢地读着石板，用他们的母语读着那些文字。', `MaleText_loc5`='%s慢慢地讀著石板，用他們的母語無聲的讀著文字。', `MaleText_loc7`='%s lee la tablilla lentamente, moviendo los labios como si dijera las palabras en su idioma nativo.' WHERE `ID`=13714;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나가 장군! 오, 이런...', `MaleText_loc4`='天哪……纳迦督军！', `MaleText_loc5`='納迦督軍!喔天啊...', `MaleText_loc7`='¡Señor de la Guerra naga! Vaya...' WHERE `ID`=13715;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아름다우신 여사제님, 제가 말씀드릴 내용이 심기를 불편하게 해드릴지도 모르겠군요. 이 서판은 나가의 통신 수단입니다. 나가의 지도자인 장군 스리스티즈가 부하들에게 섬의 나머지 지역을 무력으로 점령하라고 명령한 내용이 담겨 있습니다.', `MaleText_loc4`='嗯，你不会喜欢这个消息的，小姑娘。这块石板是纳迦的交流工具。他们的首领督军斯雷提兹命令他的纳迦们用武力来抢夺这块岛屿。', `MaleText_loc5`='嗯，我接下來要說的話不太中聽，小姑娘。這個石板是納迦用來溝通的東西。他們的領導者，督軍司瑞史提斯，已命令他的納迦用武力佔領這座島剩下的區域。', `MaleText_loc7`='Bueno, no te va a gustar lo que tengo que decirte, joven señorita. Esta tablilla es un comunicado naga. Su líder, el señor de la guerra Sriss''tiz, ha ordenado a sus nagas que tomen el resto de la isla por la fuerza.' WHERE `ID`=13716;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 나즈자타에서 나가 증원군이 온 것 같군요!', `MaleText_loc4`='看上去他得到了纳沙塔的增援！', `MaleText_loc5`='而且看來他有援軍從納沙塔爾趕來!', `MaleText_loc7`='¡Y parece que ha conseguido que vengan refuerzos de Nazjatar!' WHERE `ID`=13717;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭔가 손을 써야 합니다!', `MaleText_loc4`='我们必须得干点什么了！', `MaleText_loc5`='我們一定要想想辦法!', `MaleText_loc7`='¡Tenemos que hacer algo con esto!' WHERE `ID`=13718;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고맙습니다, 아다만트씨. 이 일에 딱 맞는 사람을 알고 있어요.', `FemaleText_loc4`='谢谢你，阿达曼特。我想我知道谁最适合这项工作。', `FemaleText_loc5`='謝謝你，阿達曼。我想我知道一個適合的人選。', `FemaleText_loc7`='Gracias, Adamant. Creo que conozco a la persona adecuada para el trabajo.' WHERE `ID`=13719;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다시 만나서 반갑군요. 상황도 좀 안정된 것 같고 이제 우리가 과거에 잃어버렸던 아주 귀중한 보물에 대해 얘기를 좀 하려고 합니다만...', `FemaleText_loc4`='很高兴能再次见到你，$n。也许当事情都解决了之后，我可以告诉你有关那些我们丢失的无价之宝的事情……', `FemaleText_loc5`='再見到你真好，$n。或許等一切安頓下來後，我可以和你談談我們失去的無價之寶...', `FemaleText_loc7`='Me alegro de verte, $n. Puede que cuando se calmen las cosas te hable del preciado tesoro que hemos perdido...' WHERE `ID`=13720;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 얼라이언스가 내 요새 안에 이렇게나 깊숙하게 쳐들어왔단 말인가? 명예의 요새의 포로들을 데려오고 사형 집행인을 불러라! 이곳을 침범한 대가는 목숨으로 치러야 할 것이다!', `MaleText_loc4`='联盟竟敢深入我的堡垒？把荣耀堡的战俘带出来，让刽子手们待命！他们会为这次入侵付出生命的代价！', `MaleText_loc5`='聯盟竟敢如此深入我的堡壘?把榮譽堡的犯人帶出來再把劊子手叫來!他們要用生命為他們的入侵付出代價!', `MaleText_loc7`='¿Osa la Alianza entrar en mi fortaleza? ¡Sacad a los prisioneros del Bastión del Honor y llamad al verdugo! ¡Pagarán esta intromisión con su vida!' WHERE `ID`=13721;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스랄의 가짜 호드들이 감히 내 요새 안에 이렇게나 깊숙하게 쳐들어왔단 말인가? 스랄마의 포로들을 데려오고 사형 집행인을 불러라! 이곳을 침범한 대가는 목숨으로 치러야 할 것이다!', `MaleText_loc4`='萨尔的那个冒牌部落胆敢深入我的堡垒？把萨尔玛的战俘带出来，让刽子手们待命！他们会为这次入侵付出生命的代价！', `MaleText_loc5`='索爾的假部落竟敢如此深入我的堡壘?把索爾瑪的犯人帶出來再把劊子手叫來!他們要用生命為他們的入侵付出代價!', `MaleText_loc7`='¿La falsa Horda de Thrall se atreve a acercarse tanto a mi fortaleza? ¡Sacad a los prisioneros de Thrallmar y llamad al verdugo! ¡Pagarán esta afrenta con sus vidas!' WHERE `ID`=13722;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사형 집행인이 도착했다! 포로들을 대령하라!', `MaleText_loc4`='刽子手们已经就位了！把俘虏们准备好！', `MaleText_loc5`='劊子手到了!犯人們準備好了!', `MaleText_loc7`='¡El verdugo ha llegado! ¡Preparad a los prisioneros!' WHERE `ID`=13723;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당장 포로 녀석 하나를 처형해라! 드워프를 먼저 처형해라... 저 녀석은 자기 자랑이 너무 심하단 말이다.', `MaleText_loc4`='马上处决一个战俘！先杀了那个矮人……他的废话太多了。', `MaleText_loc5`='立刻處死其中一名囚犯!先殺死那個矮人...他廢話太多了。', `MaleText_loc7`='¡Ejecutad a los prisioneros enseguida! Mata al enano primero... Habla demasiado por su propio bien.' WHERE `ID`=13724;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 포로 녀석 하나를 처형해라! 타우렌을 먼저 처형하고... 녀석의 머리털을 전리품으로 보관해라.', `MaleText_loc4`='开始审问他们吧！先把那个牛头人带过来。', `MaleText_loc5`='立刻處死其中一名囚犯!先殺死那個牛頭人...把他的頭留著當戰利品。', `MaleText_loc7`='¡Ejecutad a uno de los prisioneros de inmediato! Matad primero al tauren... guardad su cabeza como trofeo.' WHERE `ID`=13725;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='포로들 가운데 고위 장교가 한 명 있는 것 같구나... 재미있군. 그 얼라이언스 계집을 처형해라!', `MaleText_loc4`='看上去有个指挥官在我们的俘虏中间……太棒了。马上砍了那个联盟小妞！', `MaleText_loc5`='看來我們的俘虜之中也有階段制度...真有意思。處死這個聯盟少女!', `MaleText_loc7`='Parece que tenemos a un oficial de mando entre nuestros cautivos... qué divertido. ¡Ejecutad a la mujerzuela de la Alianza!' WHERE `ID`=13726;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='포로들 가운데 고위 장교가 있는 것 같구나... 재미있군. 그 하룻강아지 같은 녀석을 당장 처형해라!', `MaleText_loc4`='看上去有个指挥官在我们的俘虏中间……太棒了。马上砍了这条绿皮狗！', `MaleText_loc5`='看來我們的俘虜之中也有階段制度...真有意思。立刻處死這個綠皮膚的傢伙!', `MaleText_loc7`='Parece que tenemos a un oficial de mando entre nuestros cautivos... qué divertido. ¡Ejecutad a este perro de piel verde de inmediato!' WHERE `ID`=13727;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마지막 포로를 처형해라. 이제 침입자들은 자신들의 행동이 얼마나 어리석었는지 다시 생각해 보겠지!', `MaleText_loc4`='杀了最后的那个战俘。我们的入侵者现在也许会重新考虑他们那愚蠢的行动了！', `MaleText_loc5`='殺死最後一個囚犯。或許我們的入侵者現在會重新考慮他們愚蠢的行動!', `MaleText_loc7`='Matad al último prisionero. ¡Tal vez ahora nuestros intrusos reconsideren sus estúpidas acciones!' WHERE `ID`=13728;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 보고 있는 겁니까?', `MaleText_loc4`='你在看什么？', `MaleText_loc5`='你在看什麼?', `MaleText_loc7`='¿Qué miras?' WHERE `ID`=13729;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 위대한 도시, 아이언포지의 드워프인 아다만트 아이언하트라고 하네. 내 제복을 보면 알겠지만 난 아이언포지 정예 경비병의 일원이었네. 그렇지, 나는 마그니 폐하의 오른팔이었다네! 뭐, 적어도 퇴역하기 전까지는 그랬지. 지금은 고고학을 연구하고 있네. 사실은 취미지만... 고고학이 세상을 보는 훌륭한 방법이라는 걸 깨달았지!', `MaleText_loc4`='我是来自铁炉堡的阿达曼特·铁心。我想你可能已经从我的制服上面猜出来了，我曾是铁炉堡精英守卫中的一员。是的，我曾经是麦格尼的左膀右臂！至少在我退休前。现在我开始涉足考古学，确切地说，这是我的爱好，而且我发现这真是个了解世界的好办法！', `MaleText_loc5`='我是偉大之城鐵爐堡的阿達曼·鐵心。你們看我的制服應該猜到我曾是鐵爐堡精英守衛之一。是的，我是麥格尼的副手!至少在我退休之前都是。現在我都在研究考古學。這是個嗜好;加上我認為這是個見識世界的好方法!', `MaleText_loc7`='Soy Adamant Coracero, de la gran ciudad de Forjaz. Como probablemente puedas suponer viendo mi uniforme, una vez formé parte de la guardia de élite de Forjaz. ¡Sí, fui la mano derecha de Magni! Al menos, hasta que me retiré. Ahora me intereso por la arqueología. En realidad es una afición; además, ¡pensé que sería una gran forma de ver mundo!' WHERE `ID`=13730;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 덤벼, 추악한 오우거의 자식아!', `MaleText_loc4`='来吧，你这个食人魔养的！', `MaleText_loc5`='來吧，你這個骯髒巨魔之子!', `MaleText_loc7`='¡Adelante, hijo de ogro sarnoso!' WHERE `ID`=13731;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무슨 짓이든 해봐라, 이 악마의 자식들!', `FemaleText_loc4`='放马过来吧，杂种！', `FemaleText_loc5`='盡你最少的努力就好了，惡魔重生!', `FemaleText_loc7`='¡Haz lo peor que puedas, engendro demoníaco!' WHERE `ID`=13732;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 끝내자... 너무 오래 기다렸군.', `MaleText_loc4`='快点……我已经等得够久了。', `MaleText_loc5`='快點解決它...我已經等了夠久了。', `MaleText_loc7`='Acabemos con esto... ya he esperado suficiente.' WHERE `ID`=13733;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카르가스, 더러운 녀석! 진짜 호드가 널 가만두지 않을 것이다!', `MaleText_loc4`='我唾弃你，卡加斯。真正的部落会消灭你的！', `MaleText_loc5`='我唾棄你，卡加斯。真正的部落會把你毀滅!', `MaleText_loc7`='Te escupo, Kargath. ¡La auténtica Horda te aplastará!' WHERE `ID`=13734;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='운명을 막을 수는 없을 거다, 타락한 오크들아. 지옥불 성채는 곧 함락될 것이다.', `MaleText_loc4`='这都是命中注定的，邪兽人。地狱火堡垒不久就将毁灭。', `MaleText_loc5`='你無法阻止不可避免的事，魔獄獸人。地獄火堡壘很快就會陷落。', `MaleText_loc7`='No puedes detener lo inevitable, orco vil. La ciudadela del Fuego Infernal caerá pronto.' WHERE `ID`=13735;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 봐라, 이 쓰레기 같은 녀석아! 이게 진정한 오크의 모습이다!', `MaleText_loc4`='看看我，你们这帮渣滓！这才是真正的兽人该有的样子！', `MaleText_loc5`='看著我，人渣!這才是真正的獸人!', `MaleText_loc7`='¡Mírame, escoria! ¡Este es el aspecto de un orco de verdad!' WHERE `ID`=13736;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<흐느끼는 카우렌>', `MaleText_loc4`='<库雷呜咽着。>', `MaleText_loc5`='<科倫啜泣。>', `MaleText_loc7`='<Cowlen solloza.>' WHERE `ID`=13737;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 뭘 어쨌다고 신께서는 제게 이런 시련을 주시는 거죠? 제가 아끼던 모든 것이 사라졌습니다. 숲의 짐승들이 우리 가족을 빼앗아 갔고, 집은 무너지고 배도 가라앉았습니다.$B$B전 이 망가진 섬에서 오도 가도 못하는 끝장난 인생입니다.$B$B아마도 당신은 제게 죽음을 선물하러 오셨겠지요? 반항하지 않을 테니 빨리 끝냅시다. 비참한 이 목숨을 가져가십시오. 저는 겁쟁이라서 도저히 자살은 못 하겠습니다. 손 떨리는 것 좀 보시라고요... 정말 못 하겠습니다.', `MaleText_loc4`='我干了些什么？为什么神明要如此残忍地惩罚我？我所爱的一切都没有了——不是死了就是被毁灭了。我的家人被森林里的怪物掳走，我的家被夷为平地，我的船沉了。$B$B这个已经崩溃的人在这座破碎的岛屿上束手无策。$B$B也许你来这里是要完成你那肮脏的工作？那么就快点，我不会抵抗的。拿走我的生命吧，陌生人；我自己下不了手，我的手在颤抖……', `MaleText_loc5`='我做了什麼讓神祇們用這樣殘暴的行為抨擊我?失去了所有我珍愛的一切 - 不是死亡就是毀滅。森林裡的野獸帶走我身邊的家人。我的家園被夷平。我的船沉了。$B$B我是個一無所有的人，擱淺在一座破碎的島上。$B$B或許你是來這裡完成任務的?快點了結吧，我不會抵抗的。取我的性命吧，陌生人;我太懦弱不敢自己了斷。我的雙手顫抖...那把劍不會正中要害。', `MaleText_loc7`='¿Qué puedo haber hecho para dar a los dioses motivos para arremeter contra mí con tal ferocidad? Todo lo que quería ha desaparecido – muerto o ha sido destruido. Mi familia, arrebatada por las bestias del bosque. Mi hogar, arrasado. Mi nave, hundida.$B$BSoy un hombre roto, perdido en una isla rota.$B$B¿Quizás estás aquí para terminar el trabajo? Hazlo rápido, no opondré resistencia. Toma mi vida, $gextranjero:extranjera;; soy demasiado cobarde como para hacerlo yo mismo. Mi mano tiembla... el filo no será certero.' WHERE `ID`=13738;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나이트 엘프여, 당신을 해치려고 온 게 아닙니다. 그리고 이건 신이 내린 시련이 아닙니다...', `MaleText_loc4`='我不会杀你的，暗夜精灵。神明也不会这么做的……', `MaleText_loc5`='我不是來殺你的，夜精靈。而且神祇也沒有這個意思...', `MaleText_loc7`='No he venido a matarte, elfo de la noche. Y los dioses no han hecho esto...', `FemaleText_loc1`='나이트 엘프여, 당신을 해치려고 온 게 아닙니다. 그리고 이건 신이 내린 시련이 아닙니다...', `FemaleText_loc4`='我不会杀你的，暗夜精灵。神明也不会这么做的……', `FemaleText_loc5`='我不是來殺你的，夜精靈。而且神祇也沒有這個意思...', `FemaleText_loc7`='No he venido a matarte, elfo de la noche. Y los dioses no han hecho esto...' WHERE `ID`=13739;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신이 아니라면 그럼 누굽니까? 어떻게요? 누가 이런 일을 저지른 겁니까?', `MaleText_loc4`='如果不是神，那会是谁？什么样的力量会把这里变成这样？', `MaleText_loc5`='如果不是神祇，那會是誰?是什麼造成了這樣的衝突?', `MaleText_loc7`='Si no los dioses, ¿quién? ¿Cómo? ¿Qué podría causar tal disputa?' WHERE `ID`=13740;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번 일에 대한 책임이 우리 종족에게 어느 정도는 있다고 생각합니다. 우린 불타는 군단에게 패하여 고향에서 쫓겨난 난민입니다. 이번 비극은 최근에 우리가 피난을 가던 중 발생한 것입니다. 우리 배가 난파되었고 이 잔해는 그 배에서 나온 겁니다.', `MaleText_loc4`='恐怕我的同胞应该对这次破坏负一些责任。燃烧军团逼我们逃出了家园，成为了难民。这个惨剧是由我们导致的。我们的飞船坠毁了——这块碎片是飞船的一部分。', `MaleText_loc5`='我擔心我的人民要為這次的毀滅負責。我們是難民，燃燒軍團迫使我們離開家園。這個悲劇是我們最近一次疏散的結果。我們的飛船失事了 - 這個殘骸是那艘飛船的一部分。', `MaleText_loc7`='Me temo que mi pueblo es, de algún modo, responsable de esta destrucción. Somos refugiados, desplazados de nuestro hogar por la Legión Ardiente. Esta tragedia es el resultado de nuestra última evacuación. Nuestra nave tuvo un accidente – estos escombros son parte de aquella nave.', `FemaleText_loc1`='우리 종족에게 이번 일에 대한 책임이 어느 정도는 있다고 생각해요. 우린 불타는 군단에게 패하여 고향에서 쫓겨난 난민이에요. 이번 비극은 최근에 우리가 피난을 가던 중 발생한 것이에요. 우리 배가 난파되었고 이 잔해는 그 배에서 나온 거예요.', `FemaleText_loc4`='恐怕我的同胞应该对这次破坏负一些责任。燃烧军团逼我们逃出了家园，成为了难民。这个惨剧是由我们导致的。我们的飞船坠毁了——这块碎片是飞船的一部分。', `FemaleText_loc5`='我擔心我的人民要為這次的毀滅負責。我們是難民，燃燒軍團迫使我們離開家園。這個悲劇是我們最近一次疏散的結果。我們的飛船失事了 - 這個殘骸是那艘飛船的一部分。', `FemaleText_loc7`='Me temo que mi pueblo es, de algún modo, responsable de esta destrucción. Somos refugiados, desplazados de nuestro hogar por la Legión Ardiente. Esta tragedia es el resultado de nuestra última evacuación. Nuestra nave tuvo un accidente – estos escombros son parte de aquella nave.' WHERE `ID`=13741;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불타는 군단? 악마들이요? 당신들도 그자들에게 당한 건가요? 우리 종족도 불타는 군단한테 당했습니다. 그 어둠의 지배자들에게 저주를 받았지요.$B$B<눈물을 훔치는 카우렌>$B$B그런 이유로 저는 아주 오래전에 가족과 함께 이곳으로 왔습니다.', `MaleText_loc4`='燃烧军团？恶魔？他们在猎杀你？我的人民也在被燃烧军团猎杀，被他们的黑暗主人作为诅咒的目标。$B$B<库雷擦去了泪水。>$B$B那就是我几年前把家搬到这里来的原因。', `MaleText_loc5`='軍團?惡魔?他們追捕你?我的人民也被燃燒軍團追捕:黑暗大師將他們視為毀滅的目標。$B$B<科倫擦去眼淚。>$B$B這是我和家人多年前搬遷至此的原因。', `MaleText_loc7`='¿Legión? ¿Demonios? ¿Te dan caza? Mi pueblo también ha sido perseguido por la Legión: blanco de sus maestros oscuros para la condenación.$B$B<Cowlen se seca las lágrimas.>$B$BEsa es la razón por la que trasladé a mi familia aquí hace tantos años.' WHERE `ID`=13742;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 공통점이 많군요, 나이트 엘프님. 우리가 만난 게 어쩌면 운명일지도 모른다는 생각이 드네요. 카우렌, 제가 당신을 돕겠습니다. 나와 같은 자들이 돕게 해주십시오. 우리가 잘못된 것을 바로잡을 것이라고 맹세합니다.', `MaleText_loc4`='看来我们有很多共同点，暗夜精灵。我对你的不幸爱莫能助，但也许是命运让我们聚到了一起。让我帮助你吧，库雷。让我的人民帮助你吧。我发誓我们会矫正自己犯下的错误。', `MaleText_loc5`='我們有很多共同點，夜精靈。我不由自主的覺得或許是命運把我們連結在一起。讓我來幫你，科倫。讓我的人民來幫忙。我們會讓一切恢復正常。我發誓。', `MaleText_loc7`='Tenemos mucho en común, elfo de la noche. No puedo evitar sentir que quizás fue el destino lo que nos unió. Déjame ayudarte, Cowlen. Deja que mi pueblo ayude. Solucionaremos los problemas. Eso te lo juro.', `FemaleText_loc1`='우린 공통점이 많군요, 나이트 엘프님. 우리가 만난 게 어쩌면 운명일지도 모른다는 생각이 드네요. 카우렌, 제가 당신을 돕겠습니다. 나와 같은 자들이 돕게 해주십시오. 우리가 잘못된 것을 바로잡을 것이라고 맹세합니다.', `FemaleText_loc4`='看来我们有很多共同点，暗夜精灵。我对你的不幸爱莫能助，但也许是命运让我们聚到了一起。让我帮助你吧，库雷。让我的人民帮助你吧。我发誓我们会矫正自己犯下的错误。', `FemaleText_loc5`='我們有很多共同點，夜精靈。我不由自主的覺得或許是命運把我們連結在一起。讓我來幫你，科倫。讓我的人民來幫忙。我們會讓一切恢復正常。我發誓。', `FemaleText_loc7`='Tenemos mucho en común, elfo de la noche. No puedo evitar sentir que quizás fue el destino lo que nos unió. Déjame ayudarte, Cowlen. Deja que mi pueblo ayude. Solucionaremos los problemas. Eso te lo juro.' WHERE `ID`=13743;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 집은 이쪽으로 숲을 지나면 나와요. 어서 가봐요.', `FemaleText_loc4`='这边走，我们的房子在那里，穿过灌木丛就到。', `FemaleText_loc5`='我們家在這邊，通過灌木叢。', `FemaleText_loc7`='Nuestra casa está por aquí, a través del matorral.' WHERE `ID`=13744;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기가 우리 집이에요... 이런, 불쌍한 우리 가족. 모든 것이 파괴됐군요.', `FemaleText_loc4`='我可怜的家，所有的东西都被摧毁了。', `FemaleText_loc5`='我可憐的家庭。一切都被摧毀了。', `FemaleText_loc7`='Mi pobre familia. Lo han destruido todo.' WHERE `ID`=13745;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='앗, 아버지! 아버지! 살아계셨군요!', `FemaleText_loc4`='爸爸！爸爸！你还活着！', `FemaleText_loc5`='爸爸!爸爸!你還活著!', `FemaleText_loc7`='¡Padre! ¡Padre! ¡Estás vivo!' WHERE `ID`=13746;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 아버지를 껴안습니다.', `FemaleText_loc4`='%s拥抱着她的父亲。', `FemaleText_loc5`='%s擁抱她的父親。', `FemaleText_loc7`='%s abraza a su padre.' WHERE `ID`=13747;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아버지, 여기 이분이 절 여기까지 안전하게 데려다 주셨어요.', `FemaleText_loc4`='你应该感谢$n安全地把我带回来，爸爸。', `FemaleText_loc5`='你要謝謝$n把我安全送回這裡，爸爸。', `FemaleText_loc7`='Puedes dar las gracias a $n por devolverme aquí sin incidentes, padre.' WHERE `ID`=13748;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='딸아!', `MaleText_loc4`='女儿！', `MaleText_loc5`='女兒!', `MaleText_loc7`='¡Hija!' WHERE `ID`=13749;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 안녕하신지요. 나이트 엘프가 이곳으로 우리 드레나이를 불러 협조하기 전까지 이숲은 모든 이에게 잊혀진 곳이었습니다.$B$B칼도레이는 이 땅과 인연이 깊기에, 나이트 엘프가 우리 드레나이에게 숲의 노래를 소생시키는 데 협력해 달라고 부탁한 것은 영광스러운 일이 아닐 수 없습니다.', `MaleText_loc4`='你好，$c。在暗夜精灵邀请我们德莱尼人加入他们之前，这片林地几乎已经被遗忘了。$B$B卡多雷人完全控制了这片土地，他们邀请我们加入重建林歌神殿的任务，对此我们德莱尼人深感荣耀。', `MaleText_loc5`='你好，$c。在夜精靈邀請德萊尼加入他們之前，這片林地是被遺忘的。$B$B卡多雷和這片土地關係密切，而我們德萊尼很榮幸他們要我們一起接下重新振作林歌神殿的任務。', `MaleText_loc7`='Saludos, $c. Antes de que los elfos de la noche invitaran a los draenei a unirse a ellos aquí, este claro estaba casi olvidado.$B$BLos kaldorei tienen un profundo vínculo con estas tierras, y nosotros, los draenei, nos sentimos honrados de compartir la tarea de revitalizar Canción del Bosque.' WHERE `ID`=13750;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런 곳에서 새로운 분을 만나니 무척 반갑군요. 지금 우리는 적의 수가 너무 많아 간신히 버티고만 있습니다.$B$B우리를 없애려고 혈안이 된 적들에게 완전히 둘러싸였습니다. 북쪽으로는 사티로스, 동쪽으로는 전쟁노래 벌목기지의 오크, 그리고 악령불 언덕의 악마들까지...$B$B우리는 죽는 한이 있더라도 이곳을 되찾고 말 것입니다. 그런데 지금은 우리가 죽을 확률이 더 큰 것 같군요!', `FemaleText_loc4`='很高兴可以在这里看到新面孔。我们的哨站很小，但却有着大量的敌人。我们被那些企图消灭我们的家伙包围着：北面的萨特，东面伐木营地的兽人，还有那些冥火岭的恶魔。$B$B虽然几乎是身处死地，但即使我们全部牺牲，我们也要夺回这个地方！', `FemaleText_loc5`='很高興在這裡看到新面孔。我們的前哨很小而我們的敵人卻很多。我們被那些想摧毀我們的人給包圍:西邊的薩特，南方戰歌伐木營地的獸人和冥火嶺的惡魔。$B$B我們感激德萊尼答應加入我們保衛林歌神殿不受這些人的威脅。', `FemaleText_loc7`='Me alegro de ver una cara nueva por aquí. Apenas resistimos y nuestros enemigos, muy numerosos.$B$BEstamos rodeados por seres que quieren eliminarnos: sátiros al norte, orcos del aserradero Grito de Guerra al este y demonios del Cerro Lumbrevil.$B$BRecuperamos este lugar aunque sea lo último que hagamos. ¡Parece que puede que lo sea!' WHERE `ID`=13757;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 숨을 깊게 들이마십니다.', `MaleText_loc4`='%s深深地吸了一口气', `MaleText_loc5`='%s深呼吸', `MaleText_loc7`='%s respira profundamente' WHERE `ID`=13758;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳 숲의 노래에서 다른 이들의 목소리를 다시 듣게 되어 기쁘군요. 제가 후손들이 타락하기 전 이 땅을 처음 발견했던 칼도레이의 마지막 종족이 되는 것은 아닐까 하고 걱정했었습니다.', `MaleText_loc4`='能在林歌神殿听到其他的人的声音，这可真是太好了，我都开始觉得自己可能是留在这里的最后一个卡多雷了。', `MaleText_loc5`='再次在林歌神殿這裡聽到其他人的聲音真好。我開始覺得好像我會是這片土地衰退腐敗前最後一個注視它們的卡多雷人。', `MaleText_loc7`='Me alegra volver a oír las voces de otros aquí, en Canción del Bosque. Me había empezado a sentir como si fuera el último de los kaldorei que fuera a poner la vista en estas tierras antes de su descenso a la corrupción.' WHERE `ID`=13759;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='capture point Contested1', `MaleText_loc4`='capture point Contested1', `MaleText_loc5`='奪旗點爭奪中1', `MaleText_loc7`='punto de captura en litigio1' WHERE `ID`=13760;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='capture point Contested2', `MaleText_loc4`='capture point Contested2', `MaleText_loc5`='奪旗點爭奪中2', `MaleText_loc7`='punto de captura en litigio2' WHERE `ID`=13761;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='capture point Win1', `MaleText_loc4`='capture point Win1', `MaleText_loc5`='奪旗點勝1', `MaleText_loc7`='punto de captura ganado1' WHERE `ID`=13762;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='capture point Win2', `MaleText_loc4`='capture point Win2', `MaleText_loc5`='奪旗點勝2', `MaleText_loc7`='punto de captura ganado2' WHERE `ID`=13763;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='capture point Progress1', `MaleText_loc4`='capture point Progress1', `MaleText_loc5`='奪旗點進度1', `MaleText_loc7`='punto de captura en progreso1' WHERE `ID`=13764;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='capture point Progress2', `MaleText_loc4`='capture point Progress2', `MaleText_loc5`='奪旗點進度2', `MaleText_loc7`='punto de captura en progreso2' WHERE `ID`=13765;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주변에서 악의 기운이 느껴지십니까? 아르거스의 이름으로 반드시 정화해야 합니다!$B$B악마들은 우리 고향이었던 아르거스를 파괴했습니다. 그러니 우리의 새로운 고향인 아제로스에 발조차 못들이게 할 것입니다!', `MaleText_loc4`='你能感觉到弥漫在我们周围的邪恶气息吗，$c？以阿古斯之手的名义，它必须被消灭掉！$B$B那些恶魔摧毁了我们曾经的家园阿古斯。我绝不会容忍他们蹂躏我们新的家园——艾泽拉斯！', `MaleText_loc5`='你可以感覺到附近邪惡的氣息嗎，$c?聖光之手啊，它必須被淨化!$B$B惡魔毀了我們的家園，阿古斯。我絕對不允許它們出現在我們新的家園，艾澤拉斯!', `MaleText_loc7`='¿Sientes el mal alrededor nuestro, $c? ¡Por la Mano, debe ser purificado!$B$BLos demonios destruyeron nuestro mundo natal, Argus. ¡No toleraré su presencia en nuestro nuevo hogar, Azeroth!' WHERE `ID`=13766;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악마들을 모두 처리했으니 이곳에 새로운 고향을 건설할 수 있겠구려.', `MaleText_loc4`='现在那些恶魔已经被解决了，我们可以在这里建立一座新的基地了。', `MaleText_loc5`='既然惡魔的問題已被解決，我們就可以繼續在這裡建立新基地了。', `MaleText_loc7`='Ahora que nos hemos ocupado de los demonios, podemos continuar con el establecimiento de una nueva base aquí.' WHERE `ID`=13767;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 손수건을 먹어치우더니 화가 난 듯 씩씩거립니다!', `MaleText_loc4`='%s吞吃着布帛，并生气地发出咝咝的声音。', `MaleText_loc5`='%s狼吞虎嚥地吃光織品並憤怒地發出嘶嘶聲!', `MaleText_loc7`='¡%s devora la tela y sisea con enfado!' WHERE `ID`=13768;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 남쪽에서 피어 오른 사악한 기운을 처리했으나 여전히 그 곳에서 위험이 느껴지는구려.', `MaleText_loc4`='虽然你已经给南方的恶魔势力造成了沉重的打击，但我还是觉得那个地方有些问题。', `MaleText_loc5`='雖然你給南方的邪惡惡魔一次很大的教訓，但我仍感應到那個區域有麻煩。', `MaleText_loc7`='Aunque has asestado un duro golpe al mal demoníaco del sur, sigo sintiendo problemas en esa región.' WHERE `ID`=13769;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='도와주세요!', `FemaleText_loc4`='帮帮我！', `FemaleText_loc5`='救救我!$n在攻擊!', `FemaleText_loc7`='¡Socorro!' WHERE `ID`=13770;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신과 당신 부족이 우리의 동맹으로서 함께하겠다고 하시니 우리도 이 섬에 계속 남아 재건하기로 결정했습니다. 엘룬의 가호가 있기를, 영웅이여.$B$B슬픔은 왔다가 사라지지만 우리는 살아남을 겁니다.', `MaleText_loc4`='有你和你的朋友作为同盟，我们决定留在这座岛上进行重建工作。艾露恩保佑你，英雄。$B$B虽然悲伤仍然萦绕在我心中，但我相信我们可以生存下来。', `MaleText_loc5`='有你和你的人民做盟友，我們決定留在這座島上重建家園。伊露恩祝福你，英雄。$B$B雖然悲傷依舊來來去去，我想我們會活下來的。', `MaleText_loc7`='Contigo y con tu gente como aliados, hemos decidido quedarnos en esta isla y reconstruir. Que Elune te bendiga, héroe.$B$BAunque la tristeza va y viene, creo que sobreviviremos.' WHERE `ID`=13771;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정 $r|1이;가; 맞는 건가? 여기서 자네를 보니 힘이 나는군! 우리는 최대한 많은 도움이 필요하네.', `MaleText_loc4`='你是一个$R，对吧？在这儿遇见你真是令人振奋！我们欢迎任何能够寻求到的援助。', `MaleText_loc5`='你是一個$r，對嗎?在這裡見到你讓我很振奮!我們可以利用所有能獲得的幫助。', `MaleText_loc7`='Eres $gun:una; $r, ¿verdad? ¡Me anima verte aquí! Nos irá bien toda la ayuda que podamos recibir.' WHERE `ID`=13772;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자다!', `MaleText_loc4`='入侵者！', `MaleText_loc5`='入侵者!', `MaleText_loc7`='¡$gIntruso:Intrusa;!', `FemaleText_loc1`='침입자다!', `FemaleText_loc4`='入侵者！', `FemaleText_loc5`='入侵者!', `FemaleText_loc7`='¡$gIntruso:Intrusa;!' WHERE `ID`=13773;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기선 아무도 네놈을 환영하지 않는다!', `MaleText_loc4`='这里不欢迎你！', `MaleText_loc5`='這裡不歡迎你!', `MaleText_loc7`='¡No eres $gbienvenido:bienvenida; aquí!', `FemaleText_loc1`='여기선 아무도 네놈을 환영하지 않아!', `FemaleText_loc4`='这里不欢迎你！', `FemaleText_loc5`='這裡不歡迎你!', `FemaleText_loc7`='¡No eres $gbienvenido:bienvenida; aquí!' WHERE `ID`=13774;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 나가 깃발을 집어듭니다.', `MaleText_loc4`='%s拾起纳迦的旗帜。', `MaleText_loc5`='%s拾起納迦旗。', `MaleText_loc7`='%s coge la bandera naga.' WHERE `ID`=13775;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일이라도 있습니까, 불똥 님? 모이라고 하신 이유가 뭡니까?', `MaleText_loc4`='这到底是怎么回事，斯巴克？你为什么要召集这次会面？', `MaleText_loc5`='是什麼大事，火花?你為何發起這次會面?', `MaleText_loc7`='¿Cuál es la gran idea, Chispik? ¿Por qué convocas esta reunión?' WHERE `ID`=13776;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 짓인가? 너 때문에 내 정체가 거의 드러날 뻔했잖아, 멍청한 녀석! 내가 분명 나침반하고 항해 지도를 안전한 곳에 두라고 하지 않았나. 바보도 쉽게 찾을 수 있는 뻥 뚫린 곳 말고!', `MaleText_loc4`='怎么回事？你几乎破坏了我的伪装，白痴！我告诉你把罗盘和航海地图放在一个安全的地方，而不是放在一个给任何傻瓜都可以发现的地方。', `MaleText_loc5`='是什麼大事?你差點毀了我的掩護，白痴!我跟你說過要把指南針和航海地圖放到安全一點的地方 - 不是任何蠢蛋都會發現的大庭廣眾之下。', `MaleText_loc7`='¿Cuál es la gran idea? ¡Casi fastidias mi tapadera, idiota! Te dije que pusieras la brújula y los mapas de navegación en un lugar seguro – no fuera, en campo abierto, para que cualquier estúpido los descubra.' WHERE `ID`=13777;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님께서는 엑소다르의 소재에 관한 정보를 지키려고 엄청난 노력을 하셨다. 너 때문에 내부 첩자가 발각될 뻔했을 뿐만 아니라 우리 계획도 전부 엉망이 될 뻔했다는 걸 아나?', `MaleText_loc4`='主人不遗余力地探查有关埃索达所在之处的信息。你可能会破坏整个行动，包括我们在埃索达安插的间谍！', `MaleText_loc5`='主人已經努力掩飾艾克索達的下落。你可能會毀了整個運作，包括我們在裡面的間諜掩護。', `MaleText_loc7`='El maestro ha hecho todo lo posible para obtener información sobre el paradero de El Exodar. Podrías haber fastidiado toda la operación, incluyendo la tapadera de nuestro espía, que ocupa un puesto de confianza.' WHERE `ID`=13778;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정하십시오, 불똥 님! 모든 것이 제 통제 하에 있습니다. 우리는 그들 몰래 엑소다르에서 채굴을 할 것이고 불똥님과 저는 아주 큰 부자가 될 겁니다.', `MaleText_loc4`='放松一点，斯巴克！一切都在我的控制下。我们会慢慢挖光埃索达的水晶……让我和你都变得非常非常富裕。', `MaleText_loc5`='放輕鬆，火花!一切都在我的掌控中。我們將會在艾克索達下方開始探採 - 讓我們兩人都變得非常、非常富有。', `MaleText_loc7`='¡Relájate, Chispik! Lo tengo todo bajo control. Les quitaremos El Exodar de debajo de sus mismos pies – haciéndonos muy, muy ricos tú y yo en el proceso.' WHERE `ID`=13779;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정하라고? 캘타스 님께서 그분께 실망을 안겨준 자들에게 어떻게 하시는지 알고나 하는 소린가, 기즐? 영원한 고통과 괴로움에 몸부림치는 거다... 이번 일을 망치면 알아서 해, 멍청한 고블린 녀석.', `MaleText_loc4`='放松点？你知道凯尔萨斯会对那些让他失望的家伙做些什么吗，吉兹尔？无尽的痛苦……不要把这事情搞砸了，白痴！', `MaleText_loc5`='放輕鬆?你知道凱爾薩斯怎麼對付那些辜負他的人嗎，吉索?永遠的痛苦與折磨...別搞砸了，笨蛋。', `MaleText_loc7`='¿Relajarme? ¿Sabes lo que hace Kael''thas con los que le fallan, Geezle? Sufrimiento y dolor eternos... ¡Así que ten cuidado, estúpido!' WHERE `ID`=13780;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 핏빛안개 척후병들이 우리 정보원의 위치를 파악했다. 그 멍청이 벨렌은 곧 무방비 상태가 될 것이다. 우리가 습격하기에 충분한 시간이지! 이제, 네놈을 없애 버리기 전에 눈앞에서 사라져라...', `MaleText_loc4`='我们的秘血岛斥候已经定位到了我们的联系人。那个笨蛋维伦很快就会处于毫无防备的状态，让我们有充足的时间发动进攻！现在，在我把你蒸发掉之前离开我的视线……', `MaleText_loc5`='我們的血謎斥候已和我們聯絡上。那個笨蛋，費倫，很快就會門戶洞開毫無防禦 - 足以讓我們一舉拿下!現在趁我還沒把你蒸發前快離開我的視線...', `MaleText_loc7`='Nuestros exploradores de Bruma de Sangre han encontrado a nuestro contacto. El estúpido, Velen, pronto se dejará abierto e indefenso – ¡el tiempo suficiente para que ataquemos! Ahora sal de mi vista antes de que te evapore...' WHERE `ID`=13781;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 알겠습니다. 다시는 이런 일이 없도록 하겠습니다...', `MaleText_loc4`='遵命，长官。不会再出错了……', `MaleText_loc5`='是的，長官。不會再有下次了...', `MaleText_loc7`='Sí, señor. No volverá a pasar...' WHERE `ID`=13782;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈이었나, 불똥! 네가 어떻게? 넌 멕카토크의 신임을 받지 않았나!', `MaleText_loc4`='原来是你，斯巴克！你怎么会这样？你曾是梅卡托克的大使！', `MaleText_loc5`='原來就是你，火花!你怎麼可以這樣?你是梅卡托克信任的使節!', `MaleText_loc7`='¡Así que eras tú, Chispik! ¿Cómo has podido? ¡Eras un enviado de confianza de Mekkatorque!' WHERE `ID`=13783;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$c|1이여;여;, 처치할 악마들이 우글거린다네. 정의를 위해 싸울 정도의 기개는 있겠지?', `FemaleText_loc4`='有很多恶魔要去消灭，$c。你有没有勇往直前的气概？', `FemaleText_loc5`='要撲殺惡魔，$c。你有那個膽量去做該做的事嗎?', `FemaleText_loc7`='Hay demonios que matar, $c. ¿Tienes agallas para hacer lo que hay que hacer?' WHERE `ID`=13784;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 소리 내어 웃습니다.', `MaleText_loc4`='%s笑了。', `MaleText_loc5`='%s大笑。', `MaleText_loc7`='%s ríe.' WHERE `ID`=13785;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너와 네 종족은 내게 아무런 의미도 없다, 멍청아. 내게는 주인님의 의지만이 중요할 뿐이다. 이... 이 드레나이들을 끝까지 추적해서 없앨 것이다... 이 세계의 모든 것을 파괴할 것이다. 넌 이제 끝이다.', `MaleText_loc4`='你和你的同类对我来说毫无意义，蠢货。主人的意愿是最重要的。这些……这些德莱尼人都会被猎杀——就像这世界上的所有东西一样。你们会被消灭的。', `MaleText_loc5`='你和你的族人對我而言毫無意義，蠢蛋。大師的心願才是最重要的。這些...這些德萊尼會被追捕並殘殺 - 這世界上的所有生物都是。等著瞧吧。', `MaleText_loc7`='Tu calaña y tú no significáis nada para mí, $gestúpido:estúpida;. La voluntad del maestro es lo único que importa. Esos... esos draenei serán perseguidos, atrapados y asesinados – como todas las cosas de este mundo. Desistirás.' WHERE `ID`=13786;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하찮은 너희 문명사회에서 조용한 시민인 척하다가, 부름만 받으면 이렇게 헌신적으로 불타는 군단을 섬길 이들이 있다는 게 놀랍지 않나?', `MaleText_loc4`='在你们这种毫无意义的文明中，竟然出现了那么多为燃烧军团全心全意效力却又隐藏得毫无破绽的人，你们不觉得可怕吗？', `MaleText_loc5`='那些對燃燒軍團如此奉獻服從的人在你無意義的文明世界裡做一名堅定的市民直到他們被徵召，這樣的事是不是嚇壞你了呢?', `MaleText_loc7`='¿Te asusta saber que hay quienes son capaces de servir a la Legión con tal fervor y devoción que esperan la llamada actuando como ciudadanos ejemplares y sin descubrirse?' WHERE `ID`=13787;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이것으로 끝이란 말인가?', `MaleText_loc4`='结束了吗？', `MaleText_loc5`='結束了嗎?', `MaleText_loc7`='¿Es este el fin?', `FemaleText_loc1`='이것으로 끝이란 말인가?', `FemaleText_loc4`='结束了吗？', `FemaleText_loc5`='結束了嗎?', `FemaleText_loc7`='¿Es este el fin?' WHERE `ID`=13789;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앞으로 어떻게 될 것인지...', `MaleText_loc4`='这一切都会——', `MaleText_loc5`='什麼會變成-', `MaleText_loc7`='¿Qué será de --', `FemaleText_loc1`='앞으로 어떻게 될 것인지...', `FemaleText_loc4`='这一切都会——', `FemaleText_loc5`='什麼會變成-', `FemaleText_loc7`='¿Qué será de --' WHERE `ID`=13790;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두려움에 떨면서 살든가 캘타스 님의 뜻에 따라 죽어라... 결국 죽기는 마찬가지가 아닌가?', `MaleText_loc4`='在恐惧中生存，遵从凯尔萨斯的意志死去……都是一样的。', `MaleText_loc5`='活在恐懼中，死於凱爾薩斯的意願...都是一樣的意思。', `MaleText_loc7`='Vivir con miedo, morir por voluntad de Kael''thas... Es lo mismo.' WHERE `ID`=13791;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제독님, 나무 변장 도구가 더 필요합니다.', `MaleText_loc4`='上将，我还要一套树伪装工具包。', `MaleText_loc5`='上將，我需要另一組偽裝樹木工具。', `MaleText_loc7`='Almirante, necesito otro disfraz completo de árbol.', `FemaleText_loc1`='제독님, 나무 변장 도구가 더 필요해요.', `FemaleText_loc4`='上将，我还要一套树伪装工具包。', `FemaleText_loc5`='上將，我需要另一組偽裝樹木工具。', `FemaleText_loc7`='Almirante, necesito otro disfraz completo de árbol.' WHERE `ID`=13792;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 평생을 쏟은 작품에 무슨 짓을 한 거냐?! 죽어라!!!', `MaleText_loc4`='你都对我的毕生的工作做了什么？！去死吧！！！', `MaleText_loc5`='你對我畢生的傑作做了什麼?!去死吧!!!', `MaleText_loc7`='¡¿Qué has hecho con el trabajo de mi vida?! ¡¡¡MUERE!!!' WHERE `ID`=13793;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='파수대는 경계 태세를 갖춰라! 잠깐, 저쪽에서 무슨 소리가 난 것 같은데...', `FemaleText_loc4`='哨兵们，警戒起来！我听到了什么声音……', `FemaleText_loc5`='偵察兵進入戒備!我聽到那裡有動靜...', `FemaleText_loc7`='¡Centinelas, alerta! He oído algo por allí...' WHERE `ID`=13794;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭔가 보인 것 같은데?', `FemaleText_loc4`='那是什么？', `FemaleText_loc5`='那是什麼?', `FemaleText_loc7`='¿Qué ha sido eso?' WHERE `ID`=13795;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 눈을 속이고 접근할 수는 없다!', `FemaleText_loc4`='别想那样鬼鬼祟祟地靠近我，$c！', `FemaleText_loc5`='別以為我沒發現你，$c!', `FemaleText_loc7`='¡A mí no me la juegas, $c!' WHERE `ID`=13796;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그 악마들을 많이 처치했으니 불타는 군단도 우리 벌목기지를 공격하는 것을 다시 생각하게 될 걸세. 하지만, 아직도 사악한 악마가 꿈틀대는 것이 느껴지는군.', `FemaleText_loc4`='由于损失了大批恶魔，燃烧军团若是想要再次进攻我们的伐木场，必定会再三考虑的。无论怎样，我仍然感觉到恶魔的力量在活跃着。', `FemaleText_loc5`='只要殺死足夠的惡魔，燃燒軍團就會考慮是否要再次攻擊我們的伐木場。不過，我仍然感受到惡魔的禍害不斷騷動著。', `FemaleText_loc7`='Con una buena parte de sus demonios asesinados, la Legión se lo pensará dos veces antes de volver a atacar nuestro aserradero. Sin embargo, aún siento cómo despierta un mal demoníaco.' WHERE `ID`=13797;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너, 거기 꼼짝 마라!', `MaleText_loc4`='你，站住！', `MaleText_loc5`='你，守住!', `MaleText_loc7`='¡Tú, aguanta ahí!', `FemaleText_loc1`='너, 거기 꼼짝 마라!', `FemaleText_loc4`='你，站住！', `FemaleText_loc5`='你，守住!', `FemaleText_loc7`='¡Tú, aguanta ahí!' WHERE `ID`=13798;
