UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리를 찾아오다니 정말 영광일세, $n.', `FemaleText_loc4`='我们对你的出席感到很荣幸，$n。', `FemaleText_loc5`='你的出現讓我們感到光榮，$n。', `FemaleText_loc7`='Nos honras con tu presencia, $n.' WHERE `ID`=13803;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해가 떴으니 또 마구간을 청소해야겠군.', `MaleText_loc4`='又是一天，又一个马厩需要清理。', `MaleText_loc5`='新的一天，又有新的獸欄要打掃。', `MaleText_loc7`='Un nuevo día y un nuevo montón de estiércol para mí.', `FemaleText_loc1`='해가 떴으니 또 마구간을 청소해야겠군.', `FemaleText_loc4`='又是一天，又一个马厩需要清理。', `FemaleText_loc5`='新的一天，又有新的獸欄要打掃。', `FemaleText_loc7`='Un nuevo día y un nuevo montón de estiércol para mí.' WHERE `ID`=13804;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 일도 점점 지겨워지네.', `MaleText_loc4`='我厌烦这种单调的生活了。', `MaleText_loc5`='我受夠了這些例行公事。', `MaleText_loc7`='Me estoy cansando de esta rutina.', `FemaleText_loc1`='이 일도 점점 지겨워지네.', `FemaleText_loc4`='我厌烦这种单调的生活了。', `FemaleText_loc5`='我受夠了這些例行公事。', `FemaleText_loc7`='Me estoy cansando de esta rutina.' WHERE `ID`=13805;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<한숨> 평생하고도 아주 오랫동안 이 일만 한 거 같아...', `MaleText_loc4`='<叹气>看上去我要在这里待到永远了……', `MaleText_loc5`='<唉>好像我已身處其中一輩子了...', `MaleText_loc7`='<suspira> Parece como si llevara desde siempre con esto...', `FemaleText_loc1`='<한숨> 평생하고도 아주 오랫동안 이 일만 한 거 같아...', `FemaleText_loc4`='<叹气>看上去我要在这里待到永远了……', `FemaleText_loc5`='<唉>好像我已身處其中一輩子了...', `FemaleText_loc7`='<suspira> Parece como si llevara desde siempre con esto...' WHERE `ID`=13806;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='결국 우리 사이에 악마 하나가 있었군... 우리가 예상하지 못했던 곳에서 말이야.', `MaleText_loc4`='竟然有个恶魔潜伏在我们中间……真是想不到。', `MaleText_loc5`='畢竟我們之中有個惡魔...只是我們沒想過他會出現在這裡。', `MaleText_loc7`='Después de todo, había un demonio entre nosotros. Solo que no donde esperábamos.' WHERE `ID`=13807;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위대한 영웅에게 모두 환호를!', `MaleText_loc4`='为我们尊贵的英雄欢呼吧！', `MaleText_loc5`='大家為崇高的英雄喝采!', `MaleText_loc7`='¡Saludad todos al exaltado héroe!' WHERE `ID`=13808;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 여행에 대한 일화는 앞으로 오랫동안 사람들의 입에 오르내릴 것이오!', `MaleText_loc4`='你的故事将被传颂！', `MaleText_loc5`='你的旅行故事會流傳好多年!', `MaleText_loc7`='¡La historia de tu viaje se contará en muchos años venideros!' WHERE `ID`=13809;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 손자들에게 들려 줄 얘깃거리가 생겼군... 왕국의 배신자는 우리 가운데 있었소!', `MaleText_loc4`='我终于有个故事可以讲给孙儿们听了……一个叛徒曾与我们生活在一起！', `MaleText_loc5`='我終於有個故事可以告訴我的子孫...有個賣國賊住在我們之中!', `MaleText_loc7`='Por fin tengo una historia que contarle a mis nietos... ¡Un traidor del reino vivió entre nosotros!' WHERE `ID`=13810;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사실 난 저 노움 녀석이 단 한 번도 마음에 들지 않았단 말이지...', `MaleText_loc4`='说实话，我从来就没喜欢过那个侏儒……', `MaleText_loc5`='說實話，我從來都不喜歡那個地精...', `MaleText_loc7`='A decir verdad, nunca me gustó ese gnomo...' WHERE `ID`=13811;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 시련에서 살아남다니 우리는 운이 좋은 편이오. 당신이 없었다면 이 섬의 모든 이들이 살해됐을지도 모른다오!', `MaleText_loc4`='我们能够在这样的考验中生存下来，真是太幸运了。如果不是你，在岛上的每个人可能早已经被杀死了。', `MaleText_loc5`='我們很幸運能從這次的磨難中存活下來。如果不是你，島上所有的人可能都被殺了!', `MaleText_loc7`='Tenemos suerte de haber sobrevivido a ese calvario. ¡De no ser por ti, todas las personas de esta isla podrían haber muerto!' WHERE `ID`=13812;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼마나 많은 배신자 녀석들이 우리 사이에 숨어 있을지 의심스럽군. 저 노움 녀석을 알아온 지 수년이 넘었지만 녀석이 배신자일 거라는 상상은 전혀 못했소이다.', `MaleText_loc4`='我怀疑还有多少这样的叛徒混在我们中间。我认识斯巴克很多年了，却从未想到过他会是个叛徒。', `MaleText_loc5`='不知道他們還有多少人藏在我們之中。我認識火花好幾年了 - 從沒想過他竟是個叛徒。', `MaleText_loc7`='Me pregunto cuántos más de ellos viven entre nosotros. Hacía años que conocía a Chispik – nunca me habría imaginado que era un traidor.' WHERE `ID`=13813;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='위대한 영웅에게 모두 환호를!', `FemaleText_loc4`='为我们尊贵的英雄欢呼吧！', `FemaleText_loc5`='大家為崇高的英雄喝采!', `FemaleText_loc7`='¡Saludad todos al héroe exaltado!' WHERE `ID`=13814;
