UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='드디어 손자들에게 들려 줄 얘깃거리가 생겼군... 왕국의 배신자는 우리 가운데 있었소!', `FemaleText_loc4`='我终于有个故事可以讲给孙儿们听了……一个叛徒曾与我们生活在一起！', `FemaleText_loc5`='我終於有個故事可以告訴我的子孫...有個賣國賊住在我們之中!', `FemaleText_loc7`='Por fin tengo una historia que contarle a mis nietos... ¡Un traidor del reino estaba viviendo entre nosotros!' WHERE `ID`=13816;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사실 난 저 노움 녀석이 단 한 번도 마음에 들지 않았단 말이지...', `FemaleText_loc4`='说实话，我从来就没喜欢过那个侏儒……', `FemaleText_loc5`='說實話，我從來都不喜歡那個地精...', `FemaleText_loc7`='A decir verdad, nunca me gustó ese gnomo...' WHERE `ID`=13817;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런 시련에서 살아남다니 우리는 운이 좋은 편이오. 당신이 없었다면 이 섬의 모든 사람들이 살해됐을지도 모른다오!', `FemaleText_loc4`='我们能够在这样的考验中生存下来，真是太幸运了。如果不是你，在岛上的每个人可能早已经被杀死了。', `FemaleText_loc5`='我們很幸運能從這次的磨難中存活下來。如果不是你，島上所有的人可能都被殺了!', `FemaleText_loc7`='Tenemos suerte de haber sobrevivido a ese calvario. ¡De no ser por ti, todas las personas de esta isla podrían haber muerto!' WHERE `ID`=13818;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='얼마나 많은 배신자 녀석들이 우리 사이에 숨어 있을지 의심스럽군. 저 노움 녀석을 알아온 지 수년이 넘었지만 녀석이 배신자일 거라는 상상은 전혀 못했소이다.', `FemaleText_loc4`='我怀疑还有多少这样的叛徒混在我们中间。我认识斯巴克很多年了，却从未想到过他会是个叛徒。', `FemaleText_loc5`='不知道他們還有多少人藏在我們之中。我認識火花好幾年了 - 從沒想過他竟是個叛徒。', `FemaleText_loc7`='Me pregunto cuántos quedarán entre nosotros. Conocía a Chispik desde hacía muchos años. Nunca habría imaginado que era un traidor.' WHERE `ID`=13819;
