UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어제 대무도회장에 가서 이번에 새로 온 주방장님이 춤을 추시는 걸 봤는데... 정말 멋지더군요.', `FemaleText_loc4`='所以我说，“没问题，但是你得多掏点。”', `FemaleText_loc5`='所以我說，「沒錯，但那會讓你花費多餘的力氣」。', `FemaleText_loc7`='Así que dije, "Sí, pero eso te costará más."' WHERE `ID`=13883;
