UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[펄볼그] 적이 저지른 이 야만스러운 짓의 증인이 돼라, $n. 그들이 우리의 젊은이들을... 힘없는 자들을... 여기에 이 뾰족가지 일족의 우리에 가둬놨다. 그들을 구하라, 예언의 현신이여!', `MaleText_loc4`='[熊怪语] 瞧瞧敌人犯下的残忍罪行吧。刺臂熊怪掳走了我们的幼子……他们还只是毫无反抗力的孩子，却被关押起来。英雄，请你搭救他们吧！', `MaleText_loc5`='[熊怪語]證明我們敵人的野蠻行為，$n。他們偷竊了我們的幼者...我們的弱者...他們被囚禁在這裡，落入鬚肢的手裡。釋放他們，允諾者!', `MaleText_loc7`='[Fúrbolg] Doy fe de los actos salvajes de nuestros adversarios, $n. Roban a nuestros jóvenes... nuestros débiles... Encarcelados aquí, están a merced de los ardides de Brazolanudo. ¡Libéralos, $gPrometido:Prometida;!' WHERE `ID`=13950;
