UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 거둘 유일한 성과는 바로 자신의 파멸밖에 없습니다!', `MaleText_loc4`='你们唯一的结局就是陷入永恒的诅咒！', `MaleText_loc5`='你只會成功的毀掉你們自己!', `MaleText_loc7`='¡Conseguirán condenarse a ustedes mismos!' WHERE `ID`=13972;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 두 다리가 성할 때 돌아가십시오.', `MaleText_loc4`='回头吧，在你还能回头的时候……', `MaleText_loc5`='趁你還來的及的時候回頭。', `MaleText_loc7`='Vuélvete mientras puedas.' WHERE `ID`=13973;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 우리의 창살을 갉아 댑니다.', `MaleText_loc4`='%s咬着笼子的栅栏。', `MaleText_loc5`='%s啃咬籠子的欄杆。', `MaleText_loc7`='%s roe las barras de su jaula.' WHERE `ID`=13974;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 우리를 들이받습니다.', `MaleText_loc4`='%s咬着笼子，发出咔咔的声音。', `MaleText_loc5`='%s在它的籠子裡窘迫不安。', `MaleText_loc7`='%s hace vibrar su jaula.' WHERE `ID`=13975;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 도움을 요청합니다.', `MaleText_loc4`='%s叫喊着寻求帮助。', `MaleText_loc5`='%s呼叫支援。', `MaleText_loc7`='%s pide ayuda.' WHERE `ID`=13976;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 자신을 잡아 온 자들을 향해 으르렁거립니다.', `MaleText_loc4`='%s对着它的捕捉者咆哮。', `MaleText_loc5`='%s對俘虜他的人咆哮。', `MaleText_loc7`='%s ruge a sus captores.' WHERE `ID`=13977;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[펄볼그어] 너울소나무 펄볼그는 당신의 용감한 행동을 잊지 못할 것입니다!', `MaleText_loc4`='[熊怪语] 止松熊怪不会忘记你的勇敢！', `MaleText_loc5`='[熊怪語]靜松熊怪不會那麼快忘記你的英勇行為!', `MaleText_loc7`='[Fúrbolg] ¡Los fúrbolgs de Semprepino tardarán en olvidar tu valentía!' WHERE `ID`=13978;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[펄볼그어] 감사합니다. 너울소나무 요새에 남아 있는 이들이 당신을 영웅으로 환영할 겁니다!', `MaleText_loc4`='[熊怪语] 止松要塞像欢迎英雄般欢迎你！', `MaleText_loc5`='[熊怪語]那些留在靜松要塞的人會像英雄一樣歡迎你!', `MaleText_loc7`='[Fúrbolg] ¡Aquellos que permanezcan en el Bastión Semprepino te darán la bienvenida como a un héroe!' WHERE `ID`=13979;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[펄볼그어] 오, 예언이 사실이로군요! 구해주셔서 감사합니다.', `MaleText_loc4`='[熊怪语] 预言是真的！', `MaleText_loc5`='[熊怪語]預言是真的!', `MaleText_loc7`='[Fúrbolg] ¡La profecía es cierta!' WHERE `ID`=13980;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수많은 시련을 겪어왔겠지. 안타깝군. 결국엔 모두 헛수고니까! 너희는 그분께 무릎을 꿇으리라.', `MaleText_loc4`='你们赢得了许多挑战……可惜到头来还是白费劲！很快你们的同胞就要向我的主人低头了！', `MaleText_loc5`='你面對過許多挑戰者...但那些全都是徒勞的!很快你的人民都將臣服於我的主人!', `MaleText_loc7`='Se han enfrentado a muchos desafíos... ¡Una pena que haya sido en vano! ¡Pronto su gente se arrodillará ante MI señor!' WHERE `ID`=13981;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실패했군... 평화는 불가능하구나.', `MaleText_loc4`='我失败了……和平是不可能出现的。', `MaleText_loc5`='我失敗了...和平無望了。', `MaleText_loc7`='He fracasado... la paz es imposible.' WHERE `ID`=13982;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성스러운 빛의 이름 안에서... 아니, 대체 무슨 일이지...?', `MaleText_loc4`='怎么……？', `MaleText_loc5`='聖光之名是什麼...?', `MaleText_loc7`='¿Qué en nombre de la Luz...?' WHERE `ID`=13983;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타락한 오크들!', `MaleText_loc4`='邪兽人！', `MaleText_loc5`='魔獄獸人!', `MaleText_loc7`='¡Orcos viles!' WHERE `ID`=13984;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살육이 끊이질 않고 있구나... 성스러운 빛이여, 제가 할 수 있는 일이 없겠습니까?', `MaleText_loc4`='流血的循环看不到尽头……我什么都做不了吗？', `MaleText_loc5`='殺人的循環永無止境...沒有解決的辦法嗎?', `MaleText_loc7`='El ciclo de derramamiento de sangre es interminable... ¿No hay nada que pueda hacer?' WHERE `ID`=13985;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌아오지 마라, 드레나이 녀석. 다음번에는 무장을 했건 안 했건 목숨을 부지할 수 없을 것이다!', `MaleText_loc4`='不要回来，德莱尼渣滓。下次我们不会留下你的小命，不管你是不是拿着武器！', `MaleText_loc5`='不要回來，德萊尼人渣。下次我們不會饒你，不管你手上有沒有武器!', `MaleText_loc7`='No vuelvas, escoria draenei. ¡La próxima vez no te perdonaremos la vida, con armas o sin ellas!' WHERE `ID`=13986;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='', `MaleText_loc4`='', `MaleText_loc5`='', `MaleText_loc7`='' WHERE `ID`=13987;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='숨통을 끊어주마!', `MaleText_loc4`='去死吧！', `MaleText_loc5`='你可以死了!', `MaleText_loc7`='¡Puedes morir!' WHERE `ID`=13988;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 알겠습니다! 진정한 호드에 도움이 되도록 노력하겠습니다!', `MaleText_loc4`='遵命！我不会辜负邪部落的！', `MaleText_loc5`='是的長官!我不會讓魔獄部落失望的!', `MaleText_loc7`='¡Sí, señor! ¡No fallaré a la Horda vil!' WHERE `ID`=13989;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 돌격 신호를 보냅니다.', `MaleText_loc4`='%s发出了冲锋的信号。', `MaleText_loc5`='%s示意衝鋒。', `MaleText_loc7`='%s indica un ataque.' WHERE `ID`=13990;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 짓을 한 겁니까, 마쿠루? 이건 우리 방식이 아닙니다!', `MaleText_loc4`='你都干了些什么，玛库鲁？这不是我们的方式！', `MaleText_loc5`='你做了什麼，瑪酷魯?!這些不是我們的方法!', `MaleText_loc7`='¡¿Qué has hecho, Makuru?! ¡Estas no son nuestras formas!' WHERE `ID`=13991;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 마음은 이해합니다, 마쿠루. 세다이는 제 형제였습니다. 하지만, 그의 이상에 어긋나는 일로 그의 명예를 더럽혀서는 안 됩니다.', `MaleText_loc4`='我知道你的感受，玛库鲁。瑟丹毕竟是我的兄弟。然而我们不能通过反对他的理想来纪念他。', `MaleText_loc5`='我能夠了解你的感受，瑪酷魯。希戴畢竟是我的兄弟。我們不能反對他的理想而使他蒙羞。', `MaleText_loc7`='Comprendo cómo te sientes, Makuru. Sedai era mi hermano, después de todo. Pero no podemos deshonrar su memoria yendo contra sus mismos ideales.' WHERE `ID`=13992;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 당신을 도우러 왔으니 두려워하지 마십시오. 살아 생전 우리 고향이었던 곳을 지켜주어 정말 고맙게 생각합니다. 그 보답으로 당신이 역병지대로 최대한 빨리 돌아갈 수 있도록 돕겠습니다. 제 동료가 앞으로의 일정에 대해 설명해 드릴 겁니다. 이 도시에서 마력이 가장 충만한 곳으로 가면 그를 만나게 될 겁니다.', `MaleText_loc4`='别害怕；我们是来帮你的。在我们的家园保卫战中，你曾经慷慨地伸出援手；你想要迅速返回东瘟疫之地是吧，这点我们可以做到的。我的同伴会向你解释要怎么做；去城内的魔法区域找他吧。', `MaleText_loc5`='別怕;我們是來幫你的。我們很感謝你在我們先前的家園給予的保護，做為感謝的方式，如果你需要，我們可以讓你快速回到瘟疫之地。我的同伴會解釋進一步的程序;你可以在城市中秘法能量最強的地方找到他。', `MaleText_loc7`='No tengas miedo. Estamos aquí para ayudarte. Te agradecemos tus esfuerzos por defendernos en nuestro antiguo hogar, y como agradecimiento hemos venido a ayudarte a regresar rápidamente a las Tierras de la Peste cuando lo necesites. Mi compatriota te puede explicar más sobre el proceso. Lo encontrarás en esta ciudad, en donde las energías Arcanas tienen su máxima potencia.', `FemaleText_loc1`='우린 당신을 도우러 왔으니 두려워하지 마세요. 살아 생전 우리 고향이었던 곳을 지켜주어 정말 고맙게 생각한답니다. 그 보답으로 당신이 역병지대로 최대한 빨리 돌아갈 수 있도록 돕겠습니다. 제 동료가 앞으로의 일정에 대해 설명해 드릴 겁니다. 이 도시에서 마력이 가장 충만한 곳으로 가면 그를 만나게 될 거예요.', `FemaleText_loc4`='别害怕；我们是来帮你的。在我们的家园保卫战中，你曾经慷慨地伸出援手；你想要迅速返回东瘟疫之地是吧，这点我们可以做到的。我的同伴会向你解释要怎么做；去城内的魔法区域找他吧。', `FemaleText_loc5`='別怕;我們是來幫你的。我們很感謝你在我們先前的家園給予的保護，做為感謝的方式，如果你需要，我們可以讓你快速回到瘟疫之地。我的同伴會解釋進一步的程序;你可以在城市中秘法能量最強的地方找到他。', `FemaleText_loc7`='No tengas miedo. Estamos aquí para ayudarte. Te agradecemos tus esfuerzos por defendernos en nuestro antiguo hogar, y como agradecimiento hemos venido a ayudarte a regresar rápidamente a las Tierras de la Peste cuando lo necesites. Mi compatriota te puede explicar más sobre el proceso. Lo encontrarás en esta ciudad, en donde las energías Arcanas tienen su máxima potencia.' WHERE `ID`=13993;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 정말 죄송하지만 우리 마법으로는 아직 그 도시의 불타는 잔해 속에 도사린 공포를 겪어보지 못한 영혼을 스트라솔름으로 데려다드릴 수 없습니다.', `MaleText_loc4`='抱歉，$C，斯坦索姆燃烧的废墟中弥漫着难以言说的恐怖气氛，而你尚未经历过这一切，我们没法将你传送到斯坦索姆去。', `MaleText_loc5`='我真的很抱歉，$c，因為你的靈魂從未體驗過斯坦索姆燃燒殘骸裡等待的恐懼，我們的魔法不能將你帶到那個城市。', `MaleText_loc7`='Realmente lo siento, $c, pero como tu espíritu nunca ha sufrido los horrores que acontecen en Stratholme, nuestra magia no te puede llevar a la ciudad.', `FemaleText_loc1`='$c|1이여;여;, 정말 죄송하지만 우리 마법으로는 아직 그 도시의 불타는 잔해 속에 도사린 공포를 겪어보지 못한 영혼을 스트라솔름으로 데려다드릴 수 없습니다.', `FemaleText_loc4`='抱歉，$C，斯坦索姆燃烧的废墟中弥漫着难以言说的恐怖气氛，而你尚未经历过这一切，我们没法将你传送到斯坦索姆去。', `FemaleText_loc5`='我真的很抱歉，$c，因為你的靈魂從未體驗過斯坦索姆燃燒殘骸裡等待的恐懼，我們的魔法不能將你帶到那個城市。', `FemaleText_loc7`='Realmente lo siento, $c, pero como tu espíritu nunca ha sufrido los horrores que acontecen en Stratholme, nuestra magia no te puede llevar a la ciudad.' WHERE `ID`=13994;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 눈을 보니 스트라솔름의 비극을 이미 경험해 보신 것 같군요. 그곳에 비참하게 갇혀 있는 딱한 영혼들을 없앨 작정이라면 원안으로 들어가십시오. 불타는 도시의 문으로 바로 이동하게 될 겁니다.', `MaleText_loc4`='我从你的眼神儿中看得出来，你对斯坦索姆的悲剧事件并不陌生。如果你想要解救那些被困在斯坦索姆中的可怜亡魂，就站到这法阵中来。它会直接将你传送到那座燃烧的城市入口处的。', `MaleText_loc5`='從你的眼睛裡我看的出來你對斯坦索姆的災難並不陌生。如果你想結束那些受困的可憐靈魂不幸命運，就踏進圈圈裡。它會直接將你帶到燃燒的城市入口。', `MaleText_loc7`='En tus ojos veo que no eres ajeno a la tragedia de Stratholme. Si deseas acabar con la miserable existencia de las almas en pena de allí, colócate en medio del círculo. Te llevará directamente a las puedras de la ciudad ardiente.', `FemaleText_loc1`='당신의 눈을 보니 스트라솔름의 비극을 이미 경험해 보신 것 같군요. 그곳에 갇혀 비참하게 존재하고 있는 딱한 영혼들을 없앨 작정이라면 원 안으로 들어가세요. 불타는 도시의 문으로 바로 이동하게 될 거예요.', `FemaleText_loc4`='我从你的眼神儿中看得出来，你对斯坦索姆的悲剧事件并不陌生。如果你想要解救那些被困在斯坦索姆中的可怜亡魂，就站到这法阵中来。它会直接将你传送到那座燃烧的城市入口处的。', `FemaleText_loc5`='從你的眼睛裡我看的出來你對斯坦索姆的災難並不陌生。如果你想結束那些受困的可憐靈魂不幸命運，就踏進圈圈裡。它會直接將你帶到燃燒的城市入口。', `FemaleText_loc7`='En tus ojos veo que no eres ajeno a la tragedia de Stratholme. Si deseas acabar con la miserable existencia de las almas en pena de allí, colócate en medio del círculo. Te llevará directamente a las puedras de la ciudad ardiente.' WHERE `ID`=13995;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오베다이, 오크들은 우리를 싫어하오! 그들은 우리 동족을 수없이 살해했소! 그들은 죽음보다 더한 고통을 받아야 마땅하단 말이오.', `MaleText_loc4`='这些兽人恨我们，欧巴迪！他们杀了我们这么多的同伴，死亡是他们应得的。', `MaleText_loc5`='獸人憎恨我們，歐拜德!他們以前殺了很多我們的人!他們罪該萬死。', `MaleText_loc7`='¡Los orcos nos odian, Obadei! ¡Han matado a muchos de nosotros antes! Merecen la muerte y algo peor.' WHERE `ID`=13996;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 이럴 수는... 세다이! 오크 녀석들 대가를 치르게 해주마!', `MaleText_loc4`='不！不……瑟丹！兽人们必须付出代价！', `MaleText_loc5`='不!不要...希戴!獸人會付出代價的!', `MaleText_loc7`='¡No! No... ¡Sedai! ¡Los orcos deben pagar!' WHERE `ID`=13997;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[펄볼그어] 이 예언을 눈여겨 보십시오!', `MaleText_loc4`='[熊怪语] 看吧，预言！', `MaleText_loc5`='[熊怪語]看著預言!', `MaleText_loc7`='[Fúrbolg] ¡He aquí la profecía!' WHERE `ID`=13998;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='냄새가 나지 않나? 어쩐 일인지 신선한 살덩이들이 우리 요새를 침입했구나. 침입자를 조심하라.', `MaleText_loc4`='你闻到了吗？好像有新鲜的肉进入了我们的堡垒。警惕那些入侵者。', `MaleText_loc5`='你有聞到嗎?新兵不知怎麼破壞了我們的堡壘。小心所有的入侵者!', `MaleText_loc7`='¿Hueles eso? Carne fresca ha penetrado de algún modo en nuestra ciudadela. Mantente vigilante ante cualquier intruso.' WHERE `ID`=13999;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투견을 풀어놓을 때까지 침입자들을 막아라!', `MaleText_loc4`='入侵者！给我顶住！等我放狗出来！', `MaleText_loc5`='入侵者!在我釋放戰犬前先拖延他們!', `MaleText_loc7`='¡Intrusos! ¡Mantenlos alejados hasta que pueda liberar a los canes de guerra!' WHERE `ID`=14000;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도망가기엔 너무 늦었다. 이제 내 전투견의 분노를 맛보아라!', `MaleText_loc4`='已经晚了，让我的狗撕碎你们吧！', `MaleText_loc5`='你太遲了，現在感受我的戰爭獵犬的憤怒吧!', `MaleText_loc7`='¡Demasiado tarde, ahora siente la ira de mis canes de guerra!' WHERE `ID`=14001;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<인간 보병이 바짝 긴장한 듯 결의에 찬 표정으로 서 있습니다.>', `MaleText_loc4`='<步兵笔直地站着，全身的肌肉都紧绷着。>', `MaleText_loc5`='西洋棋:人類步卒', `MaleText_loc7`='<El lacayo está de pie con aire decidido y músculos tensos.>' WHERE `ID`=14002;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성스러운 빛 얘기는 그만 집어치우십시오. 우리는 늪으로 가야 합니다! 그곳이 우리가 있어야 할 곳입니다!', `MaleText_loc4`='停止你这圣光如何如何的废话吧。我们要去沼泽！我们属于那里！', `MaleText_loc5`='停止這些聖光狗屁。沼澤是我們要去的地方!我們屬於那裡!', `MaleText_loc7`='Deja ya esa tontería de la Luz. ¡Donde tenemos que ir es al pantano! ¡Ese es nuestro sitio!' WHERE `ID`=14003;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런! 마음대로 하시오. 우린 떠날 것이오!', `MaleText_loc4`='哈！可笑，我们要走了！', `MaleText_loc5`='呸!隨便你們。我們要走了!', `MaleText_loc7`='¡Bah! Haced lo que queráis. ¡Nos vamos!' WHERE `ID`=14004;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저... 저는 성스러운 빛에 대해 듣고 싶습니다. 제 생각에... 제 기억으로는...', `MaleText_loc4`='我……我想听到关于圣光的事。我想……我记得……', `MaleText_loc5`='我...我想聽聽聖光的事。我想...我記得...', `MaleText_loc7`='Qui... quiero oír acerca de la Luz. Creo... recordar...' WHERE `ID`=14005;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 오셨습니다, 형제여! 당신은 악마들로부터 벗어났습니다! 벨렌 님의 가르침을 받아들이십시오. 성스러운 빛을 받아들이십시오!', `MaleText_loc4`='欢迎你们，我的同胞！你们摆脱了恶魔的控制。张开双臂拥抱维伦的教导吧！信奉圣光的指引吧！', `MaleText_loc5`='歡迎，我的同胞!你們已從惡魔那裡被解放了。擁抱費倫的教導吧!擁抱聖光!', `MaleText_loc7`='¡Bienvenidos, hermanos! Habéis sido liberados de los demonios. ¡Abrazad las enseñanzas de Velen! ¡Abrazad la luz!' WHERE `ID`=14006;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 세계에 사는 자들의 도움을 받아 불타는 군단과 맞서려면, 그들과 평화롭게 살아가는 방법 또한 배워야 하네.$B$B아제로스를 여행하는 동안 항상 이 점을 기억하시기 바라네. 성스러운 빛이 $g형제:자매;를 바른 길로 인도하길...', `MaleText_loc4`='我们试着取得这个世界的人民的认同和帮助来抵抗燃烧军团，因此我们必须同样学会和他们和平相处。$B$B当你游历整个艾泽拉斯的时候，请铭记这一点。让圣光指引你吧。', `MaleText_loc5`='當我們試著獲得這世界對抗燃燒軍團的人支援時，我們一定也要學著和他們和平共處。$B$B當你在整個艾澤拉斯旅行時請記住這點。願聖光引導你。', `MaleText_loc7`='Mientras buscamos la ayuda de los pueblos de este mundo contra la Legión Ardiente, debemos aprender a vivir en paz con ellos.$B$BNo olvides esto mientras viajes por Azeroth. Que la Luz te guíe.' WHERE `ID`=14007;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='인간 보병 조종', `MaleText_loc4`='控制人类步兵', `MaleText_loc5`='控制人類步卒', `MaleText_loc7`='Controlar lacayo humano', `FemaleText_loc1`='인간 보병 조종', `FemaleText_loc4`='控制人类步兵', `FemaleText_loc5`='控制人類步卒', `FemaleText_loc7`='Controlar lacayo humano' WHERE `ID`=14008;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[펄볼그어] 영혼이 우리에게 환영을 보여주고 있습니다!', `MaleText_loc4`='[熊怪语] 灵魂赐予我们预见之力！', `MaleText_loc5`='[熊怪語]靈魂給我們洞察力!', `MaleText_loc7`='[Fúrbolg] ¡Los espíritus nos otorgan visión!' WHERE `ID`=14009;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엑소다르로 날아갈 준비가 됐습니다.', `MaleText_loc4`='我准备好飞去埃索达了。', `MaleText_loc5`='我準備好飛往艾克索達了。', `MaleText_loc7`='Estoy preparado para que me lleven volando a El Exodar.', `FemaleText_loc1`='엑소다르로 날아갈 준비가 됐어요.', `FemaleText_loc4`='我准备好飞去埃索达了。', `FemaleText_loc5`='我準備好飛往艾克索達了。', `FemaleText_loc7`='Estoy preparada para que me lleven volando a El Exodar.' WHERE `ID`=14010;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기는 무슨 일로 왔나, 작은 $r 친구?', `MaleText_loc4`='是什么风把你吹到这里来的，渺小的$r？', `MaleText_loc5`='什麼事讓你千里迢迢的來到這裡，小$r?', `MaleText_loc7`='¿Qué te trae hasta aquí, $gpequeño:pequeña; $r?' WHERE `ID`=14011;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비됐나, $n?', `MaleText_loc4`='$n，你准备好了吗？', `MaleText_loc5`='準備好了嗎，$n?', `MaleText_loc7`='¿Estás $glisto:lista;, $n?' WHERE `ID`=14012;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$c|1이여;여;, 반갑습니다. 여기까지 찾아오는 손님은 거의 없는데 뭘 도와 드릴까요?', `FemaleText_loc4`='你好，$c。很少有客人会到我这里来。有什么我可以帮忙的吗？', `FemaleText_loc5`='你好，$c。我這裡的訪客好少。我該怎麼做才能改善?', `FemaleText_loc7`='Saludos, $c. Recibo tan pocos visitantes aquí. ¿A qué debo el placer?' WHERE `ID`=14013;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='수술루스가 그대를 기다리고 있습니다, $n.', `FemaleText_loc4`='苏苏鲁斯正在等着你呢，$n。', `FemaleText_loc5`='蘇瑟拉斯在等你，$n。', `FemaleText_loc7`='Susurrus te espera, $n.' WHERE `ID`=14014;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헤엄을 쳐서 내 영역까지 오다니 용감하구나, 땅을 걷는 자여.', `MaleText_loc4`='你勇敢地游到了我的领域，陆行者。', `MaleText_loc5`='你得要有十足的勇氣才敢踏入我的領域來，陸地人。', `MaleText_loc7`='Has tenido el valor de nadar hasta mi reino, caminante.' WHERE `ID`=14015;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그대를 기다리고 있었습니다. 잘 오셨습니다.', `FemaleText_loc4`='我一直都期待着你的到来。', `FemaleText_loc5`='我一直在等你。', `FemaleText_loc7`='Te estaba esperando.' WHERE `ID`=14016;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대장기술을 배우고 싶습니다.', `MaleText_loc4`='我想要学习更多关于锻造的知识。', `MaleText_loc5`='我想多學點關於鍛造的事。', `MaleText_loc7`='Deseo aprender más sobre la herrería.', `FemaleText_loc1`='대장기술을 배우고 싶어요.', `FemaleText_loc4`='我想要学习更多关于锻造的知识。', `FemaleText_loc5`='我想多學點關於鍛造的事。', `FemaleText_loc7`='Deseo aprender más sobre la herrería.' WHERE `ID`=14017;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 사막에서는 몸조심해야 합니다.', `MaleText_loc4`='在沙漠里要多加小心，$c。', `MaleText_loc5`='在沙漠裡要小心，$c。', `MaleText_loc7`='Ten cuidado en el desierto, $c.' WHERE `ID`=14018;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발을 끌며 걷는 소리가 동굴 전체에 울려 퍼집니다.', `MaleText_loc4`='脚步声的回音在洞内回荡。', `MaleText_loc5`='腳步聲在洞穴裡迴盪著。', `MaleText_loc7`='El sonido de pies arrastrando resuena por toda la cueva.' WHERE `ID`=14019;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일로 왔나요, $T신입생:신입생;? 엄마를 찾으러 왔나요? 저런, 안됐군요. 스랄마의 장교 클럽에 가서 찾아보는 게 좋을 겁니다.', `MaleText_loc4`='你想找回你的妈妈？太糟了。也许你应该去萨尔玛的军官俱乐部把她找回来？', `MaleText_loc5`='怎麼啦，$T小子:女孩;?你想找媽咪?嗯很抱歉。或許你該前往索爾瑪官員的俱樂部去把她找回來?', `MaleText_loc7`='¿Qué es ese $Tchiquillo:chiquilla;? ¿Quieres a tu mami? Bueno, una lástima. ¿Quizás deberías hacer una visita al club de oficiales de Thrallmar para recuperarla?' WHERE `ID`=14020;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 지금 어디에 있는지 아십니까? 여기는 아웃랜드의 명예의 요새입니다! 이 전쟁터의 한복판을 좋아하든지 아니면 떠나세요!', `MaleText_loc4`='你知道这是哪儿吗？这是荣耀堡，甜心！爱上它，或者滚出去！', `MaleText_loc5`='你知道你在哪裡嗎?這是榮譽堡，寶貝!不喜歡就滾!', `MaleText_loc7`='¿Sabes dónde estás? ¡Esto es el Bastión del Honor, cariño! ¡Ámalo o lárgate!' WHERE `ID`=14021;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수정에서 떨어져라! 그만 얼쩡대고 이제 죽어라!', `MaleText_loc4`='离水晶远点！死吧！', `MaleText_loc5`='你離水晶遠一點!去死吧!', `MaleText_loc7`='¡Aléjate de los cristales! ¡Muere, ahora!' WHERE `ID`=14022;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야외로 나들이 나온 게 아닙니다! 당신은 지금 아웃랜드에 있는 거예요! 열심히 임무를 수행하시든가 아니면 다시 어둠의 문 저편으로 넘어가시란 말입니다.', `MaleText_loc4`='这不是野营，蠢货！你在外域！要么打起精神来，要么从黑暗之门滚回去。', `MaleText_loc5`='這不是考察旅行，蛆蟲!你現在在外域!表現好一點不然就滾回傳送門去。', `MaleText_loc7`='¡No estamos de excursión, gusano! ¡Estás en Terrallende! ¡Adáptate o te devolveré a través del portal de una patada!' WHERE `ID`=14023;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신에게 상황을 설명할 시간도 없고 그러고 싶지도 않습니다! 긴히 중요하게 하실 말이 있어서 오신 겁니까, 아니면 한잔 얻어 마시려고 들른 건가요?', `MaleText_loc4`='我既没有时间，也没有兴趣来和你解释什么，混账！现在你还有什么要说的吗？或者你来这里只不过是要我和你一起去喝杯酒，公主？', `MaleText_loc5`='我既沒時間，也沒意願解釋這些給你聽，討厭鬼!現在你有重要的事要說嗎，還是你只是要約我去喝一杯啊，公主?', `MaleText_loc7`='¡No tengo tiempo ni ganas de explicarte nada, idiota! Bueno, ¿tienes algo importante que decirme o solo estás aquí para invitarme a tomar una copa, princesa?' WHERE `ID`=14024;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대체 문제가 뭐죠?!', `MaleText_loc4`='你什么毛病？', `MaleText_loc5`='你最主要的故障問題是什麼?!', `MaleText_loc7`='¡¿Cuál es tu fallo principal?!' WHERE `ID`=14025;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 여기저기 주변을 돌아다니는 걸 봤습니다. 혹시 할 일이 없어서 그러는 거라면 무기고에 장비나 갖다놓으실래요?', `MaleText_loc4`='我看你在这里跳来跳去，为什么不帮大家一个忙，把你的装备全部脱了扔在军械库里面？', `MaleText_loc5`='我看過你在附近走來走去。你為何不幫我們一個忙，減少軍械庫裡的裝備?', `MaleText_loc7`='Te he visto andar por ahí. ¿Por qué no nos haces un favor a todos y dejas tu equipamiento en la armería?' WHERE `ID`=14026;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쿠르드란의 이름으로 당신을 어둠의 문으로 통과시켜 준 게 누굽니까?', `MaleText_loc4`='以库德兰的名义，是谁让你穿越黑暗之门的？', `MaleText_loc5`='是誰自稱庫德蘭讓你通過黑暗之門?', `MaleText_loc7`='¿Quién, en nombre de Kurdran, te ha dejado pasar por el Portal Oscuro?' WHERE `ID`=14027;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런, 이런, 이런. 이게 누구죠? $T민간인:민간인;|1이;가; 아닌가요? 여어, 귀하신 몸이 납시셨군. 그러나 이곳에선 특별 대접 같은 건 없으니 꿈도 꾸지 마세요!', `MaleText_loc4`='哎哟，这是什么？一个平民？？太令人感动了！你休想得到我的特殊待遇！', `MaleText_loc5`='瞧瞧，這是哪位啊?一個$T平民:平民;?很珍貴吧?我不會給你特殊待遇的!', `MaleText_loc7`='Bueno, bueno, bueno, ¿qué tenemos aquí? ¿$tUn:Una; civil? ¿No es precioso? ¡No vas a obtener un tratamiento especial por mi parte!' WHERE `ID`=14028;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 포효합니다!', `MaleText_loc4`='%s咆哮着。', `MaleText_loc5`='%s吼叫!', `MaleText_loc7`='¡%s ruge!' WHERE `ID`=14029;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 문자들은 어떤 사건을 말해 주는군. 앞부분의 그림은 우리가 하늘 감시초소에서 만난 생물과 매우 흡사하군요...', `FemaleText_loc4`='这些象形文字叙述着一个故事。这个位于开端的图形，看上去就像那个我们在碧蓝岗哨遭遇的生物……', `FemaleText_loc5`='嗯...這些象形文字似乎在訴說一個故事。這個形體一開始，看起來很眼熟 - 幾乎就像我們同胞在藍色守望遇到的一種生物...', `FemaleText_loc7`='Las pictografías cuentan una historia. Esta figura del principio se parece a una de las criaturas que encontraron nuestros compañeros de la Avanzada Azur...' WHERE `ID`=14030;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아냐, 이럴 리가 없는데... 그 생물은 스스로 불타는 군단의 종이 되었다고 하는군요! 그리고 그 생물이 사티로스로 모습을 바꾸어 불타는 군단의 축복을 받았다고 합니다!', `FemaleText_loc4`='不，这不可能……上面说这个生物自愿变成了燃烧军团的奴仆。他变身成为萨特，接受了燃烧军团的“祝福”。', `FemaleText_loc5`='不，不可能...如果我沒看錯的話，它說這個生物自願成為燃燒軍團的奴隸!它顯示他正轉變為一個薩特並接受我們最大的敵人的「庇護」!', `FemaleText_loc7`='No puede ser... Dice que esta criatura se unió a la Legión voluntariamente. Se transformó en un sátiro y recibió la ""bendición"" de la Legión.' WHERE `ID`=14031;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 사티로스들을 쓰러뜨려야 합니다, $n! 이제 불타는 군단이 이 땅에 나타나 고통을 주는 일은 없어야 합니다!', `FemaleText_loc4`='我们必须消灭这些萨特，$n。我们不能让燃烧军团出现在这片土地上。', `FemaleText_loc5`='我們一定要對抗這些薩特，$n。我們一定要擊敗他們。我們不能容忍燃燒軍團出現在這些土地上!', `FemaleText_loc7`='Debemos vencer a estos sátiros, $n. No soportaremos la presencia de la Legión en estas tierras.' WHERE `ID`=14032;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 목소리를 낮추게나!', `MaleText_loc4`='压低你的嗓门，$C！', `MaleText_loc5`='小聲點，$c!', `MaleText_loc7`='¡No alces la voz, $c!' WHERE `ID`=14033;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='할 말이 있으면 어서 말해보게!', `MaleText_loc4`='如果你有什么话要说，就快点！', `MaleText_loc5`='如果你有話要說，就說吧!', `MaleText_loc7`='¡Si tienes algo que decir, dilo!' WHERE `ID`=14034;
