UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[펄볼그어] 현재 올빼미야수를 상대로 공격을 진행 중입니다. 다른 공격이 이어지지 않게 기다려야 합니다!', `MaleText_loc4`='[熊怪语] 目前我们正在进攻，必须稍等一会才能发动下一波进攻！', `MaleText_loc5`='[熊怪語]目前有一波襲擊在進行。我們一定要等待再發動另一次攻擊!', `MaleText_loc7`='[Fúrbolg] Actualmente hay un ataque en progreso. ¡Debemos esperar antes de desencadenar otro!' WHERE `ID`=14037;
