UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대여사제와 대화해 보셨소? 그분께서 당신의 관점에서 본 성지 순례에 대해 무척 듣고 싶어하신다오.', `MaleText_loc4`='你和高阶女牧师谈过话了吗？她非常渴望听到你去朝圣的故事。', `MaleText_loc5`='你和高階牧師談過了嗎?她很渴望聽聽你口中說出的朝聖故事。', `MaleText_loc7`='¿Has hablado ya con la suma sacerdotisa? Está ansiosa por oír la historia de la peregrinación desde tu perspectiva.' WHERE `ID`=14039;
