UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신사 숙녀 여러분, 오늘 저녁 공연에 오신 것을 환영합니다!', `MaleText_loc4`='女士们，先生们，晚上好！欢迎观看今晚的演出！', `MaleText_loc5`='晚安女士們先生們，歡迎來到今晚的表演現場!', `MaleText_loc7`='¡Bienvenidos, señoras y señores, a la sesión de esta tarde!' WHERE `ID`=14057;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='옥테온, 달새김 사슴을 사냥하기에 가장 좋은 곳은 어디입니까?', `MaleText_loc4`='艾克提恩，哪里是狩猎月痕雄鹿的最佳区域？', `MaleText_loc5`='艾克緹昂，哪裡是獵捕牧月成鹿最好的地方?', `MaleText_loc7`='Acteon, ¿cuál es el mejor sitio para cazar venados lunares?', `FemaleText_loc1`='옥테온, 달새김 사슴을 사냥하기에 가장 좋은 곳은 어디인가요?', `FemaleText_loc4`='艾克提恩，哪里是狩猎月痕雄鹿的最佳区域？', `FemaleText_loc5`='艾克緹昂，哪裡是獵捕牧月成鹿最好的地方?', `FemaleText_loc7`='Acteon, ¿cuál es el mejor sitio para cazar venados lunares?' WHERE `ID`=14058;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하늘 감시초소의 남쪽과 동쪽에 가면 풀을 뜯고 있는 달새김 사슴을 볼 수 있을 걸세.', `MaleText_loc4`='你可以在碧蓝岗哨的南面和东面找到月痕雄鹿。', `MaleText_loc5`='你可以在藍色守望東方和南方找到放牧中的牧月成鹿。', `MaleText_loc7`='Los venados lunares se pueden encontrar pastando al sur y al este de la Avanzada Azur.' WHERE `ID`=14059;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='옥테온, 달새김 순록을 사냥하기에 가장 좋은 곳은 어디입니까?', `MaleText_loc4`='艾克提恩，哪里是狩猎月痕巨鹿的最佳区域？', `MaleText_loc5`='艾克緹昂，哪裡是獵捕牧月雄鹿最好的地方?', `MaleText_loc7`='Acteon, ¿cuál es el mejor sitio para cazar ciervos lunares?', `FemaleText_loc1`='옥테온, 달새김 순록을 사냥하기에 가장 좋은 곳은 어디인가요?', `FemaleText_loc4`='艾克提恩，哪里是狩猎月痕巨鹿的最佳区域？', `FemaleText_loc5`='艾克緹昂，哪裡是獵捕牧月雄鹿最好的地方?', `FemaleText_loc7`='Acteon, ¿cuál es el mejor sitio para cazar ciervos lunares?' WHERE `ID`=14060;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하늘 감시초소의 북쪽으로 가면 달새김 순록을 볼 수 있을 걸세.$B$B즐거운 사냥 되게나!', `MaleText_loc4`='就在碧蓝岗哨的北面，你在那里很容易找到月痕巨鹿。$B$B狩猎愉快，$n！', `MaleText_loc5`='藍色守望北邊是你可以找到最多牧月雄鹿的地方。$B$B打獵愉快，$n!', `MaleText_loc7`='Justo al norte de la Avanzada Azur es donde tendrás mejor suerte para encontrar ciervos lunares.$B$B¡Buena caza, $n!' WHERE `ID`=14061;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디로 가야 병든 새끼 흑호를 찾을 수 있습니까, 총독님?', `MaleText_loc4`='我在哪里能找到更多感染的夜行豹幼崽，主教？', `MaleText_loc5`='我可以在哪裡找到更多被感染的小型夜間潛獵者，主教?', `MaleText_loc7`='¿Dónde puedo encontrar más cachorros de acechador nocturno infectados, exarca?', `FemaleText_loc1`='어디로 가야 병든 새끼 흑호를 찾을 수 있나요, 총독님?', `FemaleText_loc4`='我在哪里能找到更多感染的夜行豹幼崽，主教？', `FemaleText_loc5`='我可以在哪裡找到更多被感染的小型夜間潛獵者，主教?', `FemaleText_loc7`='¿Dónde puedo encontrar más cachorros de acechador nocturno infectados, exarca?' WHERE `ID`=14062;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='병든 새끼 흑호는 북쪽에서 오는 것 같으니, 나라면 북쪽에서 사냥을 시작하겠네.', `MaleText_loc4`='感染的夜行豹幼崽似乎是从北面来的，我建议你会从那边开始狩猎。', `MaleText_loc5`='那些被感染的小型夜間潛獵者好像是從北邊來的。如果我是你，我會從那裡開始獵捕。', `MaleText_loc7`='Los cachorros de acechadores nocturnos infectados parecen venir del norte. Si yo fuera tú, ahí es donde empezaría mi caza.' WHERE `ID`=14063;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 고통에 울부짖습니다!', `MaleText_loc4`='%s痛苦地咆哮着！', `MaleText_loc5`='%s痛苦地吼叫!', `MaleText_loc7`='¡%s ruge de dolor!' WHERE `ID`=14064;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='막투르, 당신과 함께 여기 머물 수 있도록 허락해 줘서 고맙습니다. 장담하는데 우린 서로에게 배울 게 많을 겁니다. 그리고 난 동쪽의 잃어버린 드레나이에 대해 최대한 많은 정보를 얻고자 합니다.', `MaleText_loc4`='玛格图尔，感谢你允许我留在这里。我相信我们彼此还有很多东西可以互相学习，而且我很希望能对东边的那些失落者有更多的认识。', `MaleText_loc5`='瑪格圖爾，謝謝你讓我和你一起留在這裡。我相信我們一定可以向彼此學習許多事物。我迫不及待想知道東邊的失落者所有的事情。', `MaleText_loc7`='Magtoor, gracias por permitir que me quede contigo. Estoy seguro de que hay mucho que podemos aprender el uno del otro. Y estoy ansioso por saber todo lo que pueda sobre Los Perdidos del este.' WHERE `ID`=14065;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위대하신 트제라크시여, 제브락스의 권위를 빌려 당신을 소환하려 합니다!', `MaleText_loc4`='伟大的瑟拉克，我们以塞弗拉克斯的名义将您召唤！', `MaleText_loc5`='偉大的泰斯拉克，以澤伏瑞斯之名，我們要將你召喚出來!', `MaleText_loc7`='¡Gran Tzerak, en nombre de Zevrax, te invocamos!' WHERE `ID`=14066;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불타는 군단의 적을 몰아내 주시고 우리에게 대항하는 이들에게 파멸의 비를 내려 주시옵소서!', `MaleText_loc4`='消灭燃烧军团的敌人，毁灭那些和我们作对的蠢货！', `MaleText_loc5`='挫敗燃燒軍團的敵人，大量的毀滅那些對抗我們的人!', `MaleText_loc7`='¡Destierra a los enemigos de la Legión Ardiente, que diluvie la destrucción sobre aquellos que opongan resistencia!' WHERE `ID`=14067;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론입니다, 친구여. 얼마든지 우리와 지내도 좋습니다.', `MaleText_loc4`='当然，我的朋友。我们非常欢迎你。', `MaleText_loc5`='當然，我的朋友。我們歡迎你留下來和我們一起，多久都可以。', `MaleText_loc7`='Por supuesto, $gamigo:amiga;. Puedes alojarte con nosotros todo el tiempo que quieras.' WHERE `ID`=14068;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오랫동안 당신이 재림하시길 기다렸습니다! 저희에게 불타는 군단의 적들을 파멸하기 위한 명을 내려주십시오!', `MaleText_loc4`='长久以来我们期盼着您的回归！引领我们去消灭那些燃烧军团的宿敌吧！', `MaleText_loc5`='我們一直以來都渴望著你的歸來!領導我們摧毀軍團最強大的敵人!', `MaleText_loc7`='¡Hemos ansiado mucho tu retorno! ¡Ordénanos en la destrucción de los mayores enemigos de la Legión!' WHERE `ID`=14069;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 어리석고 약해빠진 놈들! 나는 그 누구의 도움도 필요하지 않다!', `MaleText_loc4`='蠢货！懦夫！瑟拉克不再需要你们的帮助了！', `MaleText_loc5`='笨蛋!懦弱!泰斯拉克不需要你的協助!', `MaleText_loc7`='¡Estúpidos! ¡Enclenques! ¡Tzerak no necesita de su ayuda!' WHERE `ID`=14070;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런, 거기서 완전히 망쳤군요. 연습이라고 생각합시다. 자, 다시 한번 가 볼까요?', `MaleText_loc4`='哇，你完全炸毁了那里。让我们把这当作一次热身吧。你准备好再去一次了吗？', `MaleText_loc5`='哇，你真的太厲害了。我們就把這當做是排練吧，好嗎?準備好再次出征了嗎?', `MaleText_loc7`='Vaya, has fracasado estrepitosamente. Pensemos que ha sido un ensayo, ¿de acuerdo? ¿Preparado para salir de nuevo?' WHERE `ID`=14071;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 고개를 뒤로 젖히더니 소리 내어 웃습니다.', `MaleText_loc4`='%s仰头大笑。', `MaleText_loc5`='%s轉過頭來笑著。', `MaleText_loc7`='%s echa la cabeza hacia atrás y se ríe.' WHERE `ID`=14072;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='들어가는 장면 3', `MaleText_loc4`='Entering Phase 3 <PH>', `MaleText_loc5`='進入階段3<PH>', `MaleText_loc7`='Entrando en la Fase 3 <PH>' WHERE `ID`=14073;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='늑대가 나타났어요.', `MaleText_loc4`='这只狼快要死了。', `MaleText_loc5`='那隻狼要陣亡了。', `MaleText_loc7`='El lobo está bajando.', `FemaleText_loc1`='늑대가 나타났어요.', `FemaleText_loc4`='这只狼快要死了。', `FemaleText_loc5`='那隻狼要陣亡了。', `FemaleText_loc7`='El lobo está bajando.' WHERE `ID`=14074;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 호드와 거래를 하는 것입니까? 그들의 야비한 방법은 상대할 가치도 없단 말입니다.', `MaleText_loc4`='你为什么要跟部落来往？他们的居心叵测。', `MaleText_loc5`='你為什麼要和部落來往?他們的等級和你差太多了。', `MaleText_loc7`='¿Por qué traficas con la Horda? Sus viles formas no son dignas de ti.' WHERE `ID`=14075;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아하! 하나 찾았다!', `MaleText_loc4`='啊哈！找到一个！', `MaleText_loc5`='啊哈!找到一個了!', `MaleText_loc7`='¡Ajá! ¡Encontré a uno!' WHERE `ID`=14076;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 찾았군!', `MaleText_loc4`='又一个！', `MaleText_loc5`='又一個!', `MaleText_loc7`='¡$gOtro:Otra;!' WHERE `ID`=14077;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 이건 꽤 크군!', `MaleText_loc4`='啧啧，这个真不小！', `MaleText_loc5`='喔那是很大一個!', `MaleText_loc7`='¡Oh, es $guno de los:una de las; grandes!' WHERE `ID`=14078;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 정말 이 안에서 바다의 소리를 들을 수 있는지 궁금하군요.', `MaleText_loc4`='你真的能在这些东西中听到海洋的声音么？', `MaleText_loc5`='不知道你是不是真的可以從這些東西裡聽到大海的聲音。', `MaleText_loc7`='Me pregunto si es verdad que se oye el océano en estas cosas.' WHERE `ID`=14079;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거 참... 바다는 싫지만 해변은 좋으니 아이러니한 일이야.', `MaleText_loc4`='真讽刺，我讨厌海洋，但我喜欢海滩。', `MaleText_loc5`='真諷刺，我痛恨大海但我很愛沙灘。', `MaleText_loc7`='Es irónico, odio el océano, pero me encanta la playa.' WHERE `ID`=14080;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 선택의 여지가 없습니다. 우리가 호드의 명예를 높이지 못하면 그들은 분명 우리를 근처 스토나드에 처박을 테니까요! 당신과 당신의 친구들조차도 그들을 못 막을 것 같아 걱정이 됩니다.', `MaleText_loc4`='我们没有选择。如果我们坚持不住，他们就会把我们在斯通纳德门口彻底打垮。恐怕即便是你和你的朋友，也无法阻止他们。', `MaleText_loc5`='我們別無選擇。如果我們不能為部落帶來榮耀，那他們一定會從附近的斯通納德消滅我們!我擔心就連你和你的朋友都無法阻止他們。', `MaleText_loc7`='No tenemos elección. ¡Si no honramos la presencia de la Horda, seguramente nos aplastarán desde la cercana Rocal! Me temo que ni siquiera tú y tus amigos podríais pararlos.' WHERE `ID`=14081;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇습니다, 주인님. 모든 것이 계획대로 진행되고 있습니다.', `MaleText_loc4`='是的，主人。一切都在按照计划进行。', `MaleText_loc5`='是的主人，一切都照計畫進行。', `MaleText_loc7`='Sí, maestro, todo va según lo planeado.' WHERE `ID`=14082;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 껍질을 자신의 가방에 넣습니다.', `MaleText_loc4`='%s把贝壳放在了他的背包里。', `MaleText_loc5`='%s把貝殼放進他的背包裡。', `MaleText_loc7`='%s mete el proyectil en su talega.' WHERE `ID`=14083;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 눈높이까지 껍질을 들어올립니다.', `MaleText_loc4`='%s把贝壳举起来放在耳边。', `MaleText_loc5`='%s把貝殼拿到他的耳朵旁。', `MaleText_loc7`='%s se lleva el caparazón a la oreja.' WHERE `ID`=14084;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='케르사이 더스크싱어가 실종된 우리 형제와 자매들에게 저지르고 있는 사악한 짓거리를 끝낼 방법을 찾아야 합니다!', `MaleText_loc4`='我一定要想办法让邪恶的瑟尔希·暗歌无法再对我们的失落者兄弟姐妹们下毒手！', `MaleText_loc5`='我一定要想個辦法殺掉瑟賽·幽詠這個惡魔，就是他傷害了我們逝去的兄弟姐妹!', `MaleText_loc7`='¡Debo encontrar una forma de poner fin al mal que Cersei Canto Nocturno está cometiendo contra nuestros hermanos y hermanas perdidos!' WHERE `ID`=14085;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 껍질을 조사합니다.', `MaleText_loc4`='%s仔细检查着贝壳。', `MaleText_loc5`='%s檢視貝殼。', `MaleText_loc7`='%s examina el proyectil.' WHERE `ID`=14086;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하십시오, 아분. 저와 거래를 하는 스토나드의 상인이 말하길 그녀가 어떤 끔찍한 질병을 완성하려고 부단히 노력하고 있다고 합니다. 그들은 그 질병이 드레나이를 상대로 대단한 성과를 거둘 거라고 했습니다!', `MaleText_loc4`='小心一点，阿弗恩。有一个跟我们做过生意的斯通纳德商人说，瑟尔希喃喃自语着一些有关“她正在努力完善的疾病”的话。他们说那是为了对付德莱尼人而研究出来的东西！', `MaleText_loc5`='小心，艾弗恩。我在斯通納德交易的一個商人聽說她在大力讚揚一些她試著完成的可怕疾病。他們說是用來對付德萊尼的!', `MaleText_loc7`='Ten cuidado, Avuun. Uno de los mercaderes con los que comercio en Rocal la ha oído delirar acerca de una horrible enfermedad que está intentando perfeccionar. ¡Dicen que es para usarla contra los draenei!' WHERE `ID`=14087;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수도자님, 우리를 찾아주셔서 영광입니다만 이곳에서 진정 당신이 할 수 있는 게 무엇인지 궁금하군요.', `MaleText_loc4`='你在这里，我们很荣幸，但是我想知道的是，你究竟认为自己可以获得什么样的成果？', `MaleText_loc5`='隱士，我們很榮幸你來這裡，但我很好奇你真的認為你能完成什麼?', `MaleText_loc7`='Anacoreta, nos honra que estés aquí, pero tengo curiosidad con respecto a lo que crees poder conseguir.' WHERE `ID`=14088;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='막투르, 나는 잃어버린 드레나이를 위기에서 구할 방법이 있다고 믿습니다. 그들을 연구하면 그들을 파괴하고 있는 사악한 힘을 치료할 방법을 찾을 겁니다. 또한 그 과정에서 뒤틀린 드레나이들이 입은 피해도 복구할 수 있을 것이라 믿습니다.', `MaleText_loc4`='玛格图尔，我相信我们有办法从灭亡的边缘挽救这些失落者。通过研究，我将会发现净化他们所受的邪恶污染的办法。而且，你们破碎者也必然可以通过这种方法完全康复。', `MaleText_loc5`='瑪格圖爾，我有信心一定有辦法可以將失落者帶回來的。藉由細察他們，我會找到一個方法來消除毀滅他們的邪惡能量。這樣做的話，我也能徹底改變破碎者的傷害。', `MaleText_loc7`='Magtoor, confío en que hay una forma de traer a Los Perdidos de vuelta del abismo. Al estudiarlos, encontraré una forma de curar las energías viles que los han consumido. Y, al hacerlo, también podré revertir el daño a los Tábidos.' WHERE `ID`=14089;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 널 베겠다!', `MaleText_loc4`='去死吧！', `MaleText_loc5`='現在，我要砍斷你!', `MaleText_loc7`='¡Y ahora, te rajo!' WHERE `ID`=14090;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽어!', `MaleText_loc4`='死吧！！', `MaleText_loc5`='死吧!', `MaleText_loc7`='¡MUERE!' WHERE `ID`=14091;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어허, 이 친구가... 바쁜 거 안 보이나요?', `MaleText_loc4`='你看不到我很忙么？', `MaleText_loc5`='你沒看到我在忙嗎?', `MaleText_loc7`='¿No ves que estoy ocupado?' WHERE `ID`=14092;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다 끝났습니다, 불똥. 제독께서 당신이 얼라이언스를 배신했다는 사실을 알고 계십니다. 이제 내게 협조해서 알고 있는 사실을 모두 털어놓겠습니까, 아니면 한바탕 싸움을 벌여보겠습니까?', `MaleText_loc4`='结束了，斯巴克。上将已经知道是你背叛了联盟。现在你是要与我合作，告诉我你知道的一切，还是和要与我为敌？', `MaleText_loc5`='結束了，火花。上將知道是你背叛了聯盟。現在你不是要和我合作，就是要告訴我你所知道的一切，否則我們就要來硬的了。', `MaleText_loc7`='Se ha terminado, Chispik. El almirante sabe que fuiste tú quien traicionó a la Alianza. Ahora vas a colaborar conmigo y a decirme todo lo que sabes o vas a recibir algunos golpes.', `FemaleText_loc1`='다 끝났습니다, 불똥. 제독께서 당신이 얼라이언스를 배신했다는 사실을 알고 계십니다. 이제 내게 협조해서 알고 있는 사실을 모두 털어놓겠습니까, 아니면 한바탕 싸움을 벌여보겠습니까?', `FemaleText_loc4`='结束了，斯巴克。上将已经知道是你背叛了联盟。现在你是要与我合作，告诉我你知道的一切，还是和要与我为敌？', `FemaleText_loc5`='結束了，火花。上將知道是你背叛了聯盟。現在你不是要和我合作，就是要告訴我你所知道的一切，否則我們就要來硬的了。', `FemaleText_loc7`='Se ha terminado, Chispik. El almirante sabe que fuiste tú quien traicionó a la Alianza. Ahora vas a colaborar conmigo y a decirme todo lo que sabes o vas a recibir algunos golpes.' WHERE `ID`=14093;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하하하! 그 바보는 내 계획을 절대 알아내지 못할 걸! 알아낸다고 해도 드레나이 녀석을 구하기에는 너무 늦어!', `FemaleText_loc4`='哈哈哈！那个白痴永远也不会知道我的计划！就算他知道了，对德莱尼人来说也太晚了！', `FemaleText_loc5`='哈哈哈!那個笨蛋永遠不會知道我要做什麼!否則，如果他知道的話，對德萊尼來說已經太晚了!', `FemaleText_loc7`='¡Jajaja! ¡Ese idiota nunca descubrirá qué estoy tramando! O, si lo hace, ¡será demasiado tarde para los draenei!' WHERE `ID`=14094;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오크들, 바보가 따로 없군! 손만 뻗으면 차지할 수 있는 강력한 힘이 가까이에 있는데 다른 녀석이 그 힘을 강탈해 가는 것을 손 놓고 구경만 하고 있으니!', `FemaleText_loc4`='这些兽人都是蠢货！强大的力量唾手可得，但他们却视而不见，让别人占尽了先机！', `FemaleText_loc5`='<她嘴裡咕噥著。>這些獸人是笨蛋!附近有這麼多力量等著被佔領，而他們所做的卻是坐視他人來掠奪這些財產!', `FemaleText_loc7`='¡Esos orcos son estúpidos! ¡Tanto poder cerca esperando a que lo tomen, y todo lo que hacen es estar sentados mano sobre mano y observar mientras otros saquean las riquezas!' WHERE `ID`=14095;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 마지막 처리를 하고 나면 결과가 어떻게 나올지 궁금해 죽겠군!', `FemaleText_loc4`='我简直等不及要看这最后一批的实验结果了！', `FemaleText_loc5`='我等不及要看最新一批的結果了!', `FemaleText_loc7`='¡No puedo esperar a ver los resultados de esta última partida!' WHERE `ID`=14096;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아분이 감히 나와 맞서겠다고?! 가만두지 않겠다! 내가 드레나이를 처리하면 그들은 차라리 잃어버린 드레나이이길 바랄 것이다!', `FemaleText_loc4`='阿弗恩敢跟我对着干？我要让他死无葬身之地！当我解决了德莱尼人之后，他们会后悔自己当年没有变成失落者！', `FemaleText_loc5`='艾弗恩竟敢和我作對?!我會粉碎他的!等我解決了德萊尼，他們就會希望他們是失落者!', `FemaleText_loc7`='¡¿Avuun osa oponerse a mí?! ¡Lo aplastaré! ¡Cuando acabe con los draenei, desearán ser Los Perdidos!' WHERE `ID`=14097;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오, 손톱 손질이랑 엉덩이 때리기는 이제 좀 그만둘래? 널 봐주는 사람은 아무도 없단 말이야!', `FemaleText_loc4`='你能不能先别修自己的指甲？就一小会儿行不行啊？说真的，没人关心你的指甲！', `FemaleText_loc5`='喔，你可以不要再看你的指甲並打你自己一下嗎，一下就好?真的，沒人會在意的!', `FemaleText_loc7`='¡Oh, ¿puedes dejar de mirarte las uñas y darte palmadas por un momento? ¡De verdad, a nadie le importa!' WHERE `ID`=14098;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='배고프지 않아? 출출한데... 툴타쉬의 보존용 햄으로 만든 스테이크가 또 생각나서 견딜 수가 없네. 육즙 가득한 그 구운 고기를 한입만 먹었으면!', `FemaleText_loc4`='你饿了吗？我饿了。我一想起索尔塔什的烤火腿就忍不住了。啊！要是再来一些味美多汁的烤鹌鹑……', `FemaleText_loc5`='你餓嗎?我餓了。我無法再忍受索爾塔什的燻肉了。要是我們能弄到一些多汁的烤鵪鶉就好了!', `FemaleText_loc7`='¿Tienes hambre? Yo tengo hambre. No puedo soportar pensar en bistec de jamón curado de Thultash. ¡Si pudiéramos conseguir algo de esa suculenta codorniz asada!' WHERE `ID`=14099;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='신선한 공기 좀 마셔야겠어. 이 늪에 숨겨둔 물건이 있어서 그런 건 절대 아니야! 잠시 밖에 다녀올게. 내가 다녀올 동안 넌 제발 옷 좀 제대로 챙겨 입으라고.', `FemaleText_loc4`='我需要一些新鲜空气，不是这沼泽地里的空气。我要出去走走，当我外出的时候，你记得打扫一下房间，明白吗？', `FemaleText_loc5`='我需要一些新鮮空氣，這沼澤裡卻一點也沒有!我要出去晃晃。我出去的時候好好整理一下，好嗎?', `FemaleText_loc7`='¡Necesito algo de aire puro, pero en este pantano no hay ni una pizca! Voy fuera un rato. Ordena un poco mientras estoy fuera, ¿de acuerdo?' WHERE `ID`=14101;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내가 가는 곳마다 따라다닐 거야? <한숨을 쉬는 케르사이>', `FemaleText_loc4`='你非要走到哪里都跟着我吗？<叹气>', `FemaleText_loc5`='你一定要一直跟著我嗎?<嘆氣>', `FemaleText_loc7`='¿Me tienes que seguir a todas partes? <suspira>' WHERE `ID`=14102;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저기 아래 저 여자 좀 보게! 대체 자신이 뭐라고 생각하는 걸까?', `FemaleText_loc4`='看！她以为自己是谁啊？', `FemaleText_loc5`='來這下面看看她!她以為她是誰啊!', `FemaleText_loc7`='¡Mírala, allí abajo! ¿Quién se cree que es?' WHERE `ID`=14103;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠, 분명 그녀는 자신이 스토나드의 새로운 주인이라고 믿고 있어. 그녀의 서큐버스를 도와 난장판을 정리해 주겠다고 제안하는 게 어때?', `MaleText_loc4`='嗯，显然她以为自己是斯通纳德的新主人了。也许我们应该去帮她的魅魔打扫房间？', `MaleText_loc5`='嗯，毫無疑問的她以為自己是斯通納德的新主宰。或許我們應該幫助她解決她的困境?', `MaleText_loc7`='Sin duda cree ser la nueva amante de Rocal. ¿Quizás deberíamos ofrecernos a ayudar a sus súcubos a ordenar sus líos?' WHERE `ID`=14104;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 여자의 방식은 비겁해. 그녀를 보면 포세이큰 연금술사가 생각난다고.', `MaleText_loc4`='她的手段真卑鄙，让我想起了那些被遗忘者的药剂师。', `MaleText_loc5`='她的方法太軟弱了。她讓我想起被遺忘者藥劑師。', `MaleText_loc7`='Sus métodos son cobardes. Me recuerda a los boticarios Renegados.' WHERE `ID`=14105;
