UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요, 털이 없는 이방인을 만나게 되다니... 전 용감한 굴프라고 합니다!', `MaleText_loc4`='古尔弗是我的名字，陌生人。勇敢的古尔弗！', `MaleText_loc5`='克夫是我的名字，陌生人。勇者克夫!', `MaleText_loc7`='Mi nombre es Gurf, $gextranjero:extranjera;. ¡Gurf el Valiente!' WHERE `ID`=14156;
