UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하신가, 나는 너울소나무 일족의 늙은 사냥꾼인 무르도라고 하네.', `MaleText_loc4`='我是莫多，止松要塞的猎人长者。', `MaleText_loc5`='我是墨爾多，靜松的長者獵人。', `MaleText_loc7`='Soy Moordo, cazador anciano de Semprepino.' WHERE `ID`=14158;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가죽세공사가 되고 싶습니다, 무르도. 저에게 가죽세공 기술을 가르쳐 주십시오.', `MaleText_loc4`='莫多，我希望成为一名制皮师。请让我接受训练。', `MaleText_loc5`='我想成為一個製皮師，墨爾多。請訓練我。', `MaleText_loc7`='Deseo convertirme en peletero, Moordo. Por favor, instrúyeme.', `FemaleText_loc1`='가죽세공사가 되고 싶어요, 무르도. 저에게 가죽세공 기술을 가르쳐 주십시오.', `FemaleText_loc4`='莫多，我希望成为一名制皮师。请让我接受训练。', `FemaleText_loc5`='我想成為一個製皮師，墨爾多。請訓練我。', `FemaleText_loc7`='Deseo convertirme en peletera, Moordo. Por favor, instrúyeme.' WHERE `ID`=14159;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 예언의 영웅께서 제 가게에 들려주시다니 영광이네요! 뭘 도와드리면 될까요?', `MaleText_loc4`='欢迎来到我的商店！', `MaleText_loc5`='歡迎來到我的店鋪!', `MaleText_loc7`='¡$gBienvenido:Bienvenida; a mi tienda!' WHERE `ID`=14160;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, 파르카트? 물건을 사러 왔습니다.', `MaleText_loc4`='你好，帕卡特。我想购买点东西。', `MaleText_loc5`='哈囉，帕卡特。我想買點東西。', `MaleText_loc7`='Hola, Parkat. Deseo comprar algo.', `FemaleText_loc1`='안녕하세요, 파르카트? 물건을 사러 왔어요.', `FemaleText_loc4`='你好，帕卡特。我想购买点东西。', `FemaleText_loc5`='哈囉，帕卡特。我想買點東西。', `FemaleText_loc7`='Hola, Parkat. Deseo comprar algo.' WHERE `ID`=14161;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 예언의 현신께서 도착하셨군요. 너울소나무 요새에 오신 것을 환영합니다.', `MaleText_loc4`='啊，英雄来了。欢迎来到止松要塞。', `MaleText_loc5`='啊，允諾者已來到。歡迎來到靜松要塞。', `MaleText_loc7`='Ah, $gel Prometido:la Prometida; ha llegado. $gBienvenido:Bienvenida; al Bastión Semprepino.' WHERE `ID`=14162;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까? 저는 너울소나무 일족의 차기 대족장인 젊은 너울소나무라고 합니다.', `MaleText_loc4`='你好，$c。我是止松酋长，止松要塞的继承人。', `MaleText_loc5`='好消息，$c。我是靜松年少者，靜松王座的繼承人。', `MaleText_loc7`='Buenas nuevas, $c. Soy Semprepino el Menor, heredero al trono de Semprepino.' WHERE `ID`=14163;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나의 백성을 지켜주고 너울소나무 일족을 번영의 시대로 인도할 자는 바로 당신이오!', `MaleText_loc4`='你就是那个会保护我的人民，并指引止松要塞进入一个新时代的英雄！', `MaleText_loc5`='你要保衛我的人民並為靜松開創一個新的繁榮時代!', `MaleText_loc7`='¿Eres tú quien defenderá a mi gente y anunciará una nueva era de prosperidad para Semprepino?' WHERE `ID`=14164;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 알아볼 수 있을 만큼 병든 새끼 흑호를 많이 없애 주세요... 그리 어렵지는 않을 겁니다.', `MaleText_loc4`='尽可能多地清理掉感染的夜行豹……应该很简单。', `MaleText_loc5`='殺死越多被感染的夜間潛獵者越好...這很簡單。', `MaleText_loc7`='Matar tantos acechadores nocturnos infectados como pueda encontrar... Debería ser fácil.', `FemaleText_loc1`='제가 알아볼 수 있을 만큼 병든 새끼 흑호를 많이 없애 주세요... 그리 어렵지는 않을 거예요.', `FemaleText_loc4`='尽可能多地清理掉感染的夜行豹……应该很简单。', `FemaleText_loc5`='殺死越多被感染的夜間潛獵者越好...這很簡單。', `FemaleText_loc7`='Matar tantos acechadores nocturnos infectados como pueda encontrar... Debería ser fácil.' WHERE `ID`=14165;
