UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와주십시오! 이 생명체는 너무 거칠어 혼자 다루기는 어려울 거 같습니다.', `MaleText_loc4`='帮帮我！我觉得这东西对我来说可能比较棘手。', `MaleText_loc5`='救命!我想我無法獨自對付這個生物。', `MaleText_loc7`='¡Socorro! Creo que esta criatura puede que sea demasiado duro para que me encargue de él yo sola.', `FemaleText_loc1`='도와주십시오! 이 생명체는 너무 거칠어 혼자 다루기는 어려울 거 같습니다.', `FemaleText_loc4`='帮帮我！我觉得这东西对我来说可能比较棘手。', `FemaleText_loc5`='救命!我想我無法獨自對付這個生物。', `FemaleText_loc7`='¡Socorro! Creo que esta criatura puede que sea demasiado duro para que me encargue de él yo sola.' WHERE `ID`=14167;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누구 없습니까? 도와주세요! 이 생물이 절 죽이려고 합니다!', `MaleText_loc4`='有谁能听到我的话吗？我需要帮助！我快要被干掉了！', `MaleText_loc5`='有人在嗎?我需要幫忙!這個生物要殺了我!', `MaleText_loc7`='¿Me oye alguien? ¡Necesito ayuda! ¡Esta criatura va a matarme!', `FemaleText_loc1`='누구 없습니까? 도와주세요! 이 생물이 절 죽이려고 합니다!', `FemaleText_loc4`='有谁能听到我的话吗？我需要帮助！我快要被干掉了！', `FemaleText_loc5`='有人在嗎?我需要幫忙!這個生物要殺了我!', `FemaleText_loc7`='¿Me oye alguien? ¡Necesito ayuda! ¡Esta criatura va a matarme!' WHERE `ID`=14168;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더는 막기가 어렵습니다! 총독님께 저는 최선을 다했다고 전해 주십시오.', `MaleText_loc4`='我坚持不下去了！告诉主教说我尽力了。', `MaleText_loc5`='我撐不下去了!告訴我的主教我已經盡力了。', `MaleText_loc7`='¡No puedo resistirlo más! Dile al exarca que lo hice lo mejor que pude.', `FemaleText_loc1`='더는 막기가 어려워요! 총독님께 저는 최선을 다했다고 전해 주세요.', `FemaleText_loc4`='我坚持不下去了！告诉主教说我尽力了。', `FemaleText_loc5`='我撐不下去了!告訴我的主教我已經盡力了。', `FemaleText_loc7`='¡No puedo resistirlo más! Dile al exarca que lo hice lo mejor que pude.' WHERE `ID`=14169;
