UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 마을에 있는 작은 보라색 생물의 정체가 뭔지 궁금합니다... 정말 아름답거든요.', `MaleText_loc4`='我在想村子里那个紫色的生物是什么……看上去真漂亮。', `MaleText_loc5`='不知道村子裡那個紫色的小生物是什麼...它還真是漂亮。', `MaleText_loc7`='Me pregunto qué es esa criaturita púrpura de la aldea... sin duda es preciosa.', `FemaleText_loc1`='이 마을에 있는 작은 보라색 생물의 정체가 뭔지 궁금합니다... 정말 아름답거든요.', `FemaleText_loc4`='我在想村子里那个紫色的生物是什么……看上去真漂亮。', `FemaleText_loc5`='不知道村子裡那個紫色的小生物是什麼...它還真是漂亮。', `FemaleText_loc7`='Me pregunto qué es esa criaturita púrpura de la aldea... sin duda es preciosa.' WHERE `ID`=14179;
