UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너의 죽음은 왕께 바치는 좋은 선물이 될 것이다!', `MaleText_loc4`='我要将你的生命作为献给大王的祭品！', `MaleText_loc5`='你的死就是獻給國王最適合的禮物!', `MaleText_loc7`='¡Tu muerte será un tributo adecuado para el rey!', `FemaleText_loc1`='너의 죽음은 왕께 바치는 좋은 선물이 될 것이다!', `FemaleText_loc4`='我要将你的生命作为献给大王的祭品！', `FemaleText_loc5`='你的死將會是痛苦的。', `FemaleText_loc7`='¡Tu muerte será un tributo adecuado para el rey!' WHERE `ID`=14182;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실버문 만세! 선스트라이더 만세!', `MaleText_loc4`='为了银月城！为了逐日者！', `MaleText_loc5`='為了銀月城!為了逐日者!', `MaleText_loc7`='¡Por Lunargenta! ¡Por Caminante del Sol!', `FemaleText_loc1`='실버문 만세! 선스트라이더 만세!', `FemaleText_loc4`='为了银月城！为了逐日者！', `FemaleText_loc5`='為了銀月城!為了逐日者!', `FemaleText_loc7`='¡Por Lunargenta! ¡Por Caminante del Sol!' WHERE `ID`=14183;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금은 편자를 고치는 중이라 좀 바쁩니다만... 나중에 다시 오시겠습니까?', `MaleText_loc4`='我恐怕现在正忙着修理这些马蹄铁。你不介意另挑一个时间再过来吧？', `MaleText_loc5`='我現在忙著處理馬蹄鐵的事。你可以改天再來嗎?', `MaleText_loc7`='Me temo que en este momento estoy bastante ocupado clavando herraduras. ¿Te importaría volver en otro momento?' WHERE `ID`=14184;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 한때 메디브 님을 모셨습니다... 적어도 저는 그렇게 생각한답니다. 저는 보랏빛 눈의 감시자들을 도와 주인님을 감시했습니다.$B$B하지만, 지금 제가 할 수 있는 일은... 하루종일 편자를 만드는 것뿐이랍니다.', `MaleText_loc4`='我曾经为麦迪文效劳过……或者可以说是假装效劳过。我帮助紫罗兰之眼监视着我的主人。$B$B不过现在我所做的只是制造马蹄铁。一个又一个。', `MaleText_loc5`='我曾經為麥迪文效命...或是說假裝為他效命。我希望紫羅蘭之眼可以盯緊主人。$B$B但是現在我所想的只有...製作馬蹄鐵。不斷地做。', `MaleText_loc7`='Una vez serví a Medivh... o fingí hacerlo. Ayudé a El Ojo Violeta a vigilar muy de cerca al maestro.$B$BPero ahora, todo en lo que pienso es en... hacer herraduras. Una y otra vez.' WHERE `ID`=14185;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈의 머리 크기를 좀 봐라! 현상금을 두 배는 받아야겠구나!', `MaleText_loc4`='哈哈！我可以拿双份的赏金啦！', `MaleText_loc5`='看看你的頭有多大!這應該可以讓我賣出兩倍賞金的錢!', `MaleText_loc7`='¡Mira el tamaño de tu cabeza! ¡Eso debería darme el doble de recompensa!', `FemaleText_loc1`='네놈의 머리 크기를 좀 봐라! 현상금을 두 배는 받아야겠구나!', `FemaleText_loc4`='哈哈！我可以拿双份的赏金啦！', `FemaleText_loc5`='看看你的頭有多大!這應該可以讓我賣出兩倍賞金的錢!', `FemaleText_loc7`='¡Mira el tamaño de tu cabeza! ¡Eso debería darme el doble de recompensa!' WHERE `ID`=14186;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 보랏빛 눈의 감시자에 대해 알고 있군요? 나중에 시간을 내보겠습니다.$B$B지금은 일을 해야 해서요.', `MaleText_loc4`='你对紫罗兰之眼有所了解？或许我待会有时间的话会跟你聊聊。$B$B现在我得继续做事。', `MaleText_loc5`='那你知道紫羅蘭之眼嗎?或許我等下才有空跟你說話。$B$B我要回去工作了。', `MaleText_loc7`='Entonces, ¿has oído hablar de El Ojo Violeta? A lo mejor luego tendré tiempo para ti.$B$BTengo que volver al trabajo.' WHERE `ID`=14187;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코렌, 저는 대장장이입니다. 당신의 물건이 보고 싶어요.', `MaleText_loc4`='我想要学习你的铁匠技术，库雷恩。', `MaleText_loc5`='我需要你的鐵匠技能，卡爾侖。', `MaleText_loc7`='Necesito tu habilidad de herrero, Koren.', `FemaleText_loc1`='코렌, 저는 대장장이입니다. 당신의 물건이 보고 싶어요.', `FemaleText_loc4`='我想要学习你的铁匠技术，库雷恩。', `FemaleText_loc5`='我需要你的鐵匠技能，卡爾侖。', `FemaleText_loc7`='Necesito tu habilidad de herrero, Koren.' WHERE `ID`=14188;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='<죽음의 풀을 씹고 있는 듯한 에랄란>$b$b사랑의 묘약을 만들 작정이라면 잘못 찾아오셨습니다. 실명, 신경 마비, 그리고 숨통 끊기가 제 전문이니까요.', `FemaleText_loc4`='<艾拉兰看上去正在研究着某种毒草。>$B$B如果你在找人帮你制作爱情药水，那么你来错地方了。我的知识全都是关于配制致盲、致残甚至致命的毒药……你也有希望成为我这样的行家。', `FemaleText_loc5`='<依蘭兒看起來正在咀嚼一些喪命草。>$b$b如果你想製造愛情藥水，那你來錯地方了。致盲，殘廢，和殺戮才是我的本事，也希望你有興趣。', `FemaleText_loc7`='<Eralan parece estar mascando muerteflor.>$b$bSi quieres hacer una poción de amor, estás en el sitio equivocado. Cegar, lisiar y matar es mi negocio, y espero que también el tuyo.' WHERE `ID`=14189;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 그대에게서 힘을 향한 욕망이 느껴집니다.', `MaleText_loc4`='我能感觉到你对力量的渴望，$c。', `MaleText_loc5`='我可以感覺到你對力量的渴望，$c。', `MaleText_loc7`='Puedo sentir tu deseo de poder, $c.', `FemaleText_loc1`='$c|1이여;여;, 그대에게서 힘을 향한 욕망이 느껴집니다.', `FemaleText_loc4`='我能感觉到你对力量的渴望，$c。', `FemaleText_loc5`='我可以感覺到你對力量的渴望，$c。', `FemaleText_loc7`='Puedo sentir tu deseo de poder, $c.' WHERE `ID`=14190;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대의 신념으로 저를 승리로 인도하소서.', `MaleText_loc4`='你的信念指引我走向胜利。', `MaleText_loc5`='你的信念引導我走向勝利。', `MaleText_loc7`='Tu fe me guía hasta la victoria.' WHERE `ID`=14191;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성스러운 빛은 우리에게 승리를 위한 힘과 마력을 허락합니다.', `MaleText_loc4`='圣光给了我们通往胜利和力量之路的魔法。', `MaleText_loc5`='聖光給我們力量和魔法來獲得勝利!', `MaleText_loc7`='La Luz nos da la fuerza y la magia para triunfar.', `FemaleText_loc1`='성스러운 빛은 우리에게 승리를 위한 힘과 마력을 허락하지요.', `FemaleText_loc4`='圣光给了我们通往胜利和力量之路的魔法。', `FemaleText_loc5`='聖光給我們力量和魔法來獲得勝利!', `FemaleText_loc7`='La Luz nos da la fuerza y la magia para triunfar.' WHERE `ID`=14192;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로크 나라쉬! 외부인들을 물리칠 준비를 해라! 전사들이여, 집결하라!', `MaleText_loc4`='Lok-Narash！准备干掉这些入侵者！战士们，集合！', `MaleText_loc5`='部落衝鋒!準備擊垮外來者!戰士，集合!', `MaleText_loc7`='¡Lok-Narash! ¡Preparaos a acabar con los forasteros! ¡Guerreros, uníos!' WHERE `ID`=14193;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들을 몰아내자! 한 놈도 살려두지 마라!', `MaleText_loc4`='把他们干掉！不要留下一个活口！', `MaleText_loc5`='把他們趕走!一個活口都不留!', `MaleText_loc7`='¡Expulsadlos! ¡No tomaremos a ninguno vivo!' WHERE `ID`=14194;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 두 진영이 있으며 모두 피로 물들여 마땅한 녀석들이다. 오늘은 누가 먼저 죽음을 맛보겠느냐?', `MaleText_loc4`='两个敌对阵营，他们都应被浸没在血泊中。谁会在今天品尝死亡的味道呢？', `MaleText_loc5`='兩個敵方陣營。都該溺死在血泊中。今天誰會嘗到死亡的味道?', `MaleText_loc7`='Dos facciones enemigas. Ambas merecen ahogarse en sangre. ¿Quién probará la muerte el día de hoy?' WHERE `ID`=14195;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌격! 진정한 호드를 위하여! 승리를 위해!', `MaleText_loc4`='冲啊！为了邪部落！为了胜利！', `MaleText_loc5`='我們策騎奔馳!為了魔獄部落!為了勝利!', `MaleText_loc7`='¡Cabalgamos! ¡Por la Horda vil! ¡Por la victoria!' WHERE `ID`=14196;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정한 호드를 위하여!', `MaleText_loc4`='为了邪部落！！！', `MaleText_loc5`='為了魔獄部落!', `MaleText_loc7`='¡POR LA HORDA VIL!' WHERE `ID`=14197;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='록타르! 승리를 위해!', `MaleText_loc4`='Lok-Tar！为了胜利！', `MaleText_loc5`='為了部落!為了勝利!', `MaleText_loc7`='¡Lok-Tar! ¡Por la victoria!' WHERE `ID`=14199;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공격대원들은 대열에 합류하라! 코르팡 님께서 신호를 내리면 일제히 돌격해서 저 겁쟁이들을 쓰러트린다! 앞으로!', `MaleText_loc4`='骑兵们！列队！跟着库尔冯的信号冲锋，碾碎这些胆怯的家伙！前进！', `MaleText_loc5`='劫掠者，加入隊伍!遵照柯爾樊的指示向前衝鋒並粉碎這些懦弱的蹩腳貨!衝啊!', `MaleText_loc7`='¡Asaltantes, uníos a filas! ¡Cuando Korfang dé la señal, cargad adelante y arrasad a estos perros cobardes! ¡Adelante!' WHERE `ID`=14200;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스는 수십 년 동안 우리에게 맞서왔습니다! 그들은 심지어 지금도 우리 땅에 탑을 세워 우리를 조롱하고 있습니다!', `MaleText_loc4`='联盟和我们作对已经几十年了！现在，他们
甚至在我们的领土上建起了哨塔！', `MaleText_loc5`='聯盟已和我們為敵數十年矣!就連現在他們也用建立在我們土地上的哨塔來嘲笑我們!', `MaleText_loc7`='¡La Alianza se ha opuesto a nosotros durante décadas! ¡Incluso ahora 
 se burlan de nosotros con las torres que han construido en nuestra tierra!' WHERE `ID`=14201;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스랄이 이끄는 배신자들이 진정한 힘의 길을 포기했습니다! 그 건방지고 어리석은 자들은 죽어 마땅합니다!', `MaleText_loc4`='萨尔的叛徒们抛弃了通往真正力量的唯一道路！他们应该因为傲慢和愚蠢而付出生命的代价！', `MaleText_loc5`='索爾的叛徒已背棄了通往真正力量的道路!他們會因為無禮和愚蠢而亡!', `MaleText_loc7`='¡Los traidores de Thrall han abandonado el camino hacia el verdadero poder! ¡Deberían morir por su insolencia y su estupidez!' WHERE `ID`=14202;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보고 드리러 왔습니다, 코르팡 님!', `MaleText_loc4`='听我的命令，库尔冯！', `MaleText_loc5`='聽我的話，柯爾樊!', `MaleText_loc7`='¡Escucha mis palabras, Korfang!' WHERE `ID`=14203;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇다면 그 탑을 놈들의 무덤으로 만들어 주자! 탑을 파괴해라!', `MaleText_loc4`='那就让这些哨塔变成他们的坟墓吧！干掉他们！', `MaleText_loc5`='讓那些哨塔成為他們的墳墓!摧毀他們!', `MaleText_loc7`='¡Entonces, que esas torres sean sus tumbas! ¡A por ellos!' WHERE `ID`=14204;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탑을 파괴한다! 우리의 힘을 맛보고 나면 놈들은 멍청한 스랄을 저주할 것이다! 탑으로 이동하라!', `MaleText_loc4`='很好！一旦他们见识到了我们的厉害，就会咒骂萨尔的愚蠢了！向哨塔方向出发！', `MaleText_loc5`='就這樣吧!他們嘗到我們的力量之後就會詛咒索爾!前往哨塔!', `MaleText_loc7`='¡Que así sea! Maldecirán a Thrall en cuanto hayan probado nuestra fuerza. ¡A las torres!' WHERE `ID`=14205;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타락한 호드가 이동한다!', `MaleText_loc4`='邪部落正在行动！', `MaleText_loc5`='魔獄部落正在行動!', `MaleText_loc7`='¡La Horda vil está en marcha!' WHERE `ID`=14206;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타락한 호드 정찰병이다! 저 녀석이 뭘 보고 있는 거지?', `MaleText_loc4`='一个邪部落斥候！他在找什么？', `MaleText_loc5`='一個魔獄部落斥候!他要找什麼?', `MaleText_loc7`='¡Un explorador de la Horda vil! ¿Qué está buscando?' WHERE `ID`=14207;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적의 공격이다! 위치를 사수하라!', `MaleText_loc4`='我们受到了进攻！坚守你们的阵地！', `MaleText_loc5`='我們遭受攻擊!各就各位!', `MaleText_loc7`='¡Nos atacan! ¡Tomad posiciones!' WHERE `ID`=14208;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 스랄마를 공격한다!', `MaleText_loc4`='他们在袭击萨尔玛！', `MaleText_loc5`='他們在襲擊索爾瑪!', `MaleText_loc7`='¡Están asaltando Thrallmar!' WHERE `ID`=14209;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 죽여라!', `MaleText_loc4`='杀光他们！', `MaleText_loc5`='殺光他們!', `MaleText_loc7`='¡Matadlos a todos!' WHERE `ID`=14210;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희의 소중한 땅의 마법은 어디로 갔느냐?', `MaleText_loc4`='你那强大的大地魔法在哪里？', `MaleText_loc5`='你珍貴的大地魔法在哪?', `MaleText_loc7`='¿Dónde está tu preciosa magia de la tierra ahora?' WHERE `ID`=14211;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잡아 먹기 좋으라고 그런거지!', `MaleText_loc4`='可以一口把你吃掉呀！', `MaleText_loc5`='我想把你吃掉!', `MaleText_loc7`='¡Para poseerte mejor!' WHERE `ID`=14212;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도망쳐라, 꼬마야! 달아나라...', `MaleText_loc4`='快跑呀，小姑娘，快跑呀！', `MaleText_loc5`='快逃啊小女孩，快逃!', `MaleText_loc7`='¡Huye, pequeña! ¡Corre!' WHERE `ID`=14213;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 도착하자 큰 소리를 냅니다.', `MaleText_loc4`='%s怒吼着表示赞同。', `MaleText_loc5`='%s大聲吼出它的贊同。', `MaleText_loc7`='%s brama su aprobación.' WHERE `ID`=14214;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='길드 사무소에 오신 것을 환영합니다. 무엇을 도와드릴까요?', `FemaleText_loc4`='欢迎来到公会注册处。有什么我可以为您效劳的吗？', `FemaleText_loc5`='歡迎來到公會註冊員這裡。我能幫你什麼忙嗎?', `FemaleText_loc7`='Bienvenido a la Registradora de Hermandades. ¿En qué puedo ayudarte?' WHERE `ID`=14215;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='반갑네, 젊은이...', `FemaleText_loc4`='你好，我的孩子。', `FemaleText_loc5`='哈囉，我的孩子。', `FemaleText_loc7`='Hola, mi $gniño:niña;.' WHERE `ID`=14216;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우와, 할머니는 귀가 정말 크시군요.', `MaleText_loc4`='喔，奶奶，你的耳朵怎么这么尖？', `MaleText_loc5`='喔，外婆，你的耳朵真大。', `MaleText_loc7`='Oh, abuela, qué orejas tan grandes tienes.', `FemaleText_loc1`='우와, 할머니는 귀가 정말 크시네요.', `FemaleText_loc4`='喔，奶奶，你的耳朵怎么这么尖？', `FemaleText_loc5`='喔，外婆，你的耳朵真大。', `FemaleText_loc7`='Oh, abuela, qué orejas tan grandes tienes.' WHERE `ID`=14217;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그건 네 귀여운 목소리를 더 잘 듣기 위해서란다.', `FemaleText_loc4`='可以更好地听你说话啊，孩子。', `FemaleText_loc5`='這樣才能更清楚的聽到你說話，我的孩子。', `FemaleText_loc7`='Son para oírte mejor, cariño.' WHERE `ID`=14218;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우와, 할머니는 눈이 정말 크시군요.', `MaleText_loc4`='喔，奶奶，你的眼睛怎么这么大？', `MaleText_loc5`='喔，外婆，你的眼睛真大。', `MaleText_loc7`='Oh, abuelita, qué ojos más grandes tienes.', `FemaleText_loc1`='우와, 할머니는 눈이 정말 크시네요.', `FemaleText_loc4`='喔，奶奶，你的眼睛怎么这么大？', `FemaleText_loc5`='喔，外婆，你的眼睛真大。', `FemaleText_loc7`='Oh, abuelita, qué ojos más grandes tienes.' WHERE `ID`=14219;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그건 귀여운 네 얼굴을 더 잘 보기 위해서지.', `FemaleText_loc4`='可以把你看得更清楚啊，孩子。', `FemaleText_loc5`='這樣才能更清楚的看見你，我的孩子。', `FemaleText_loc7`='Lo mejor para verte, mi $gniño:niña;.' WHERE `ID`=14220;
