UPDATE `locales_broadcast_text` SET `MaleText_loc1`='덤벼라, 침입자여.', `MaleText_loc4`='入侵者来了……', `MaleText_loc5`='來吧入侵者，來挑戰布洛克強大的憤怒!', `MaleText_loc7`='Venid, intrusos...' WHERE `ID`=14259;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오시게. 나는 핏빛 감시초소의 수장 애드미티우스라고 하네.', `MaleText_loc4`='我是埃德门图斯，秘血岗哨的首领。', `MaleText_loc5`='我是阿德密特斯，血色守望的領導者。', `MaleText_loc7`='Soy Admetius, líder de la Avanzada de Sangre.' WHERE `ID`=14260;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스랄마에 잘 왔소, $n! 우리 일을 계속해서 도와준다면 우리 보급품을 더욱 많이 이용할 권한을 주지.', `MaleText_loc4`='欢迎来到萨尔玛，$n。随着你在萨尔玛的声望不断提升，我可以让你使用我们的更多物资。', `MaleText_loc5`='歡迎來到索爾瑪，$n!你持續幫助我們的事業，我就會讓你使用更多我們的物資。', `MaleText_loc7`='¡$gBienvenido:Bienvenida; a Thrallmar, $n! Como sigues ayudándonos en nuestra causa, te otorgaré más acceso a nuestros suministros.' WHERE `ID`=14261;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모라에... 당신이오?', `MaleText_loc4`='莫莱……是你吗？', `MaleText_loc5`='莫瑞伊...是你嗎?', `MaleText_loc7`='Morae... ¿Eres tú?' WHERE `ID`=14262;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 당신은 내 아내가 아니로군. 하지만, 그녀와 만난 적이 있군. 그녀를 만나거든 내가 추락에서는 살아남았으나 이곳 침투요원들에게 죽임을 당했다고 전해 주시오.', `MaleText_loc4`='不……你不是莫莱，但我感觉到你遇到过她。当你看见她的时候，告诉她我在坠毁中幸存了下来，但是没想到会被那些血精灵杀死……', `MaleText_loc5`='不...你不是莫瑞伊，但我感應到你們見過面。當你看見她，告訴她我在失事中活了下來，只是被滲透者給殺了。', `MaleText_loc7`='No... No eres Morae, pero siento que os conocéis. Cuando la veas, dile que sobreviví al accidente para caer en manos de los infiltradores.' WHERE `ID`=14263;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 아내에게... 내가 죽기 전까지 그녀만을 생각했다고 전해 주시오...', `MaleText_loc4`='让她知道……我一直在想着她……', `MaleText_loc5`='讓她知道...我最後的思緒想著她...', `MaleText_loc7`='Hazle saber... que mi último pensamiento fue para ella...' WHERE `ID`=14264;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 도움을 요청합니다.', `MaleText_loc4`='%s呼喊着寻求帮助。', `MaleText_loc5`='%s需要協助。', `MaleText_loc7`='%s pide ayuda.' WHERE `ID`=14265;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대의 동물 친구를 돌봐줄 일손이 필요합니까?', `MaleText_loc4`='需要我来照顾你的动物伙伴吗？', `MaleText_loc5`='需要幫忙照顧你的動物夥伴嗎?', `MaleText_loc7`='¿Me necesitas para cuidar de tus compañeros animales?' WHERE `ID`=14266;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 야수를 맡기고 싶습니다.', `MaleText_loc4`='我想要寄放我的宠物。', `MaleText_loc5`='我想要使用獸欄。', `MaleText_loc7`='Deseo usar el establo.', `FemaleText_loc1`='제 야수를 맡기고 싶어요.', `FemaleText_loc4`='我想要寄放我的宠物。', `FemaleText_loc5`='我想要使用獸欄。', `FemaleText_loc7`='Deseo usar el establo.' WHERE `ID`=14267;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아르거스의 대리인에서 이 맥아리가 우리 도시에서 가장 열성적인 일원이었지.$B$B귀중한 광물로 도로를 깔고, 칠흑 같은 어둠 속에서도 강물이 빛났다고 한다면 믿겠소?$B$B아, 그 시절이 다시 왔으면 좋겠군... 얼마나 오래되었을까? 천 년? 만 년?', `MaleText_loc4`='在阿古斯，玛凯雷是我们最庄严最神圣的城市。$B$B如果我告诉你，那里的人行道都是用贵重的矿石铺设的，那里的河流甚至在完全黑暗的地方都能闪闪发光，你能相信吗？$B$B我向往那些日子……多久了？一千年？还是一万年？', `MaleText_loc5`='在阿古斯，麥克艾瑞是我們最神聖的城市。$B$B如果我告訴你走道兩旁都排列著珍貴的礦物你會相信嗎?河裡即使是全黑的也閃著光芒?$B$B我渴望那些日子...已經過了多久了?一千年?一萬年?', `MaleText_loc7`='En Argus, Mac''Aree era nuestra ciudad más sagrada.$B$B¿Me creerías si te dijera que las calles estaban empedradas con joyas? ¿Que los ríos brillaban incluso en las noches más oscuras?$B$BEcho de menos aquellos días... ¿Cuánto tiempo ha pasado? ¿Mil años? ¿Diez mil?' WHERE `ID`=14268;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='버섯이 잔뜩 난 곳을 찾았으면 좋겠는데... 지금까지 살면서 그런 곳은 한 번도 보지 못했다오!', `MaleText_loc4`='如果我可以再次回到蘑菇丛就好了。我这辈子都没有看到过这么多成熟的蘑菇。', `MaleText_loc5`='要是我可以回到蘑菇灌木叢就好了。我這一生從沒見過這樣成熟的蘑菇叢!', `MaleText_loc7`='Si pudiera volver al matorral de champiñones... ¡Nunca había visto setas tan grandes!' WHERE `ID`=14269;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분부대로 하겠습니다.', `MaleText_loc4`='遵命，大人。', `MaleText_loc5`='我會完成，女士。', `MaleText_loc7`='Así se hará, mi señora.' WHERE `ID`=14270;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신에게 새로운 임무를 주겠소.', `MaleText_loc4`='你有新的命令，废物。', `MaleText_loc5`='你有新命令了，蛆蟲。', `MaleText_loc7`='Tenéis nuevas órdenes, gusanos.' WHERE `ID`=14271;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈이 상관할 일이 아니다.', `MaleText_loc4`='这和你没关系，废物。', `MaleText_loc5`='不用你擔心，蛆蟲。', `MaleText_loc7`='No es de tu incumbencia, gusano.' WHERE `ID`=14272;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저리 비켜!', `MaleText_loc4`='别挡着我的道儿！', `MaleText_loc5`='不要擋我的路!', `MaleText_loc7`='¡Fuera de mi camino!' WHERE `ID`=14273;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 태양매 정찰대의 통신을 방해하느냐?', `MaleText_loc4`='你胆敢插手炎鹰部队的事务？', `MaleText_loc5`='你竟敢妨礙太陽之鷹的官方交流?', `MaleText_loc7`='¿Te atreves a dificultar las comunicaciones oficiales de un Halcón del Sol?', `FemaleText_loc1`='감히 태양매 정찰대의 통신을 방해하느냐?', `FemaleText_loc4`='你胆敢插手炎鹰部队的事务？', `FemaleText_loc5`='你竟敢妨礙太陽之鷹的官方交流?', `FemaleText_loc7`='¿Te atreves a dificultar las comunicaciones oficiales de un Halcón del Sol?' WHERE `ID`=14274;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말에 손대지 마라, 불결한 녀석!', `MaleText_loc4`='不要碰我的马，肮脏的家伙！', `MaleText_loc5`='不要碰那匹馬，垃圾!', `MaleText_loc7`='¡No toques el caballo, mugre!' WHERE `ID`=14275;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님, 왕께서 내리신 새로운 소식은 없습니까?', `MaleText_loc4`='陛下，国王那里有什么新消息吗？', `MaleText_loc5`='塞爾，有國王的消息嗎?', `MaleText_loc7`='Señor, ¿alguna noticia del rey?', `FemaleText_loc1`='주인님, 왕께서 내리신 새로운 소식은 없나요?', `FemaleText_loc4`='陛下，国王那里有什么新消息吗？', `FemaleText_loc5`='塞爾，有國王的消息嗎?', `FemaleText_loc7`='Señor, ¿alguna noticia del rey?' WHERE `ID`=14276;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시로나스 님께서 움직이고 있습니다, 주인님. 그녀가 시작한 것입니까?', `MaleText_loc4`='希隆娜丝有消息了吗，主人？她处境不妙了？', `MaleText_loc5`='賽羅娜斯在鼓動嗎，主人?她有苦幹實幹嗎?', `MaleText_loc7`='¿Se mueve Sironas, maestro? ¿Lucha?', `FemaleText_loc1`='시로나스 님께서 움직이고 있습니다, 주인님. 그녀가 시작한 것입니까?', `FemaleText_loc4`='希隆娜丝有消息了吗，主人？她处境不妙了？', `FemaleText_loc5`='賽羅娜斯在鼓動嗎，主人?她有苦幹實幹嗎?', `FemaleText_loc7`='¿Se mueve Sironas, maestro? ¿Lucha?' WHERE `ID`=14277;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선스트라이더의 이름으로 놈들을 모조리 처치하겠습니다!', `MaleText_loc4`='我要以逐日者的名义把他们都干掉！', `MaleText_loc5`='我會以逐日者之名毀滅他們!', `MaleText_loc7`='¡Los golpearé a todos en nombre del Caminante del Sol!', `FemaleText_loc1`='선스트라이더의 이름으로 놈들을 모조리 처치하겠습니다!', `FemaleText_loc4`='我要以逐日者的名义把他们都干掉！', `FemaleText_loc5`='我會以逐日者之名毀滅他們!', `FemaleText_loc7`='¡Los golpearé a todos en nombre del Caminante del Sol!' WHERE `ID`=14278;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더러운 드레나이는 이 땅에서 살 수 없습니다...', `MaleText_loc4`='肮脏的德莱尼人不会在这个世界上活太久了……', `MaleText_loc5`='德萊尼垃圾不會留在這世界上...', `MaleText_loc7`='La mugre draenei no durará en este mundo...', `FemaleText_loc1`='더러운 드레나이는 이 땅에서 살 수 없습니다...', `FemaleText_loc4`='肮脏的德莱尼人不会在这个世界上活太久了……', `FemaleText_loc5`='德萊尼垃圾不會留在這世界上...', `FemaleText_loc7`='La mugre draenei no durará en este mundo...' WHERE `ID`=14279;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그게 무슨 뜻이지?', `MaleText_loc4`='这个词是什么意思……？', `MaleText_loc5`='高特爾是什麼意思?', `MaleText_loc7`='¿Qué significa Gotcher?', `FemaleText_loc1`='그게 무슨 뜻이지?', `FemaleText_loc4`='这个词是什么意思……？', `FemaleText_loc5`='高特爾是什麼意思?', `FemaleText_loc7`='¿Qué significa gotcher?' WHERE `ID`=14280;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 어디 보세나...', `MaleText_loc4`='现在，让我们看看……', `MaleText_loc5`='現在，來看看...', `MaleText_loc7`='Bueno, vamos a ver...' WHERE `ID`=14281;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 일지를 번역하면서 일지를 쓴 사람보다 ''앤드류 클레멘타인''이라는 자가 술에 취해 세운 공적에 대해 더 많이 알게 되었군그래.', `MaleText_loc4`='在翻译的过程中，我相信我对这个醉鬼所写的东西的了解，远远多于对日记本身的了解。', `MaleText_loc5`='在翻譯它的過程中，我覺得我了解這位「安德魯·克萊曼汀」喝醉酒的輝煌成就比日記的作者還多。', `MaleText_loc7`='En el proceso de traducir esto, creo que he aprendido más sobre las hazañas de borrachera de un tal Andrew Clementina que sobre el diario del autor.' WHERE `ID`=14282;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만, 중요한 건 아닐세. 클레멘타인 씨의... 음, 공헌에 대한 얘기가 있긴 하지만 이건 놀카이라는 자의 일지인 것 같네. 그리고 뒷부분에 기록된 내용은 잔인한 전쟁에 대한 묘사일세.', `MaleText_loc4`='但是，没关系。这个克莱门蒂先生的……呃，著作，是无伤大雅的，这本日记似乎属于一个名叫诺尔凯的人。整个日记描述了一场残忍的战争。', `MaleText_loc5`='不過，沒關係。儘管，克萊曼汀先生的...呃，「投稿」，看起來像是一個叫諾凱的人的日記。它的結尾描述一個殘忍的戰鬥。', `MaleText_loc7`='Bueno, no importa. A pesar de la... eeeh... "contribución" del señor Clementina, este parece ser el diario de un hombre llamado Nolkai. Los pasajes que se encuentran hacia el final describen una batalla brutal.' WHERE `ID`=14283;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제세라, 고린뿔물버섯이 있는 곳을 알려주시겠습니까?', `MaleText_loc4`='耶塞拉，你能告诉我去哪里找水生臭角菇吗？', `MaleText_loc5`='潔希拉，你可以告訴我去哪裡找水生惡菌菇嗎?', `MaleText_loc7`='Jessera, ¿podrías indicarme dónde está el cuernohediondo acuático?', `FemaleText_loc1`='제세라, 고린뿔물버섯이 있는 곳을 알려주시겠어요?', `FemaleText_loc4`='耶塞拉，你能告诉我去哪里找水生臭角菇吗？', `FemaleText_loc5`='潔希拉，你可以告訴我去哪裡找水生惡菌菇嗎?', `FemaleText_loc7`='Jessera, ¿podrías indicarme dónde está el cuernohediondo acuático?' WHERE `ID`=14284;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 구절을 한번 보게나...', `MaleText_loc4`='注意一下这条小路……', `MaleText_loc5`='看看這條通路...', `MaleText_loc7`='Echa un vistazo a este pasaje...' WHERE `ID`=14285;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 섬을 가르는 물속에서 찾아보시오. 하지만, 고린뿔작살광포어는 강물 속에 서식한다는 사실을 명심하고 숨을 크게 들이마시는 게 좋을 거요.', `MaleText_loc4`='搜索一下将小岛一分为二的河流，但是要多加小心，水里有很多臭角刺鱼。', `MaleText_loc5`='看看那條分裂這座島的水流，但是要小心:河水是臭角前鋒的家。', `MaleText_loc7`='Busca en las aguas que dividen esta isla, pero ten cuidado: el asediador cuernohediondo habita en ellas.' WHERE `ID`=14286;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제세라, 파멸의 버섯이 있는 곳을 알려주시겠습니까?', `MaleText_loc4`='耶塞拉，你能告诉我去哪里找致命孢子簇吗？', `MaleText_loc5`='潔希拉，你可以告訴我去哪裡找有害的孢子群嗎?', `MaleText_loc7`='Jessera, ¿podrías dirigirme hacia la poliespora ruinosa?', `FemaleText_loc1`='제세라, 파멸의 버섯이 있는 곳을 알려주시겠어요?', `FemaleText_loc4`='耶塞拉，你能告诉我去哪里找致命孢子簇吗？', `FemaleText_loc5`='潔希拉，你可以告訴我去哪裡找有害的孢子群嗎?', `FemaleText_loc7`='Jessera, ¿podrías dirigirme hacia la poliespora ruinosa?' WHERE `ID`=14287;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 핏빛 감시초소에 온 것을 환영하네. 나는 여행을 하면서 만난 여러 사람으로부터 다양한 도구와 유물, 지식을 얻었다네.$B$B내 지식이 필요하다면 구하게나... 원하는 것을 얻을 것일세.', `MaleText_loc4`='欢迎来到秘血岗哨，$c。在我的旅途中，我收集到了各种文明的工具、文物和知识。$B$B如果你需要这些知识，只管来问我就是了。', `MaleText_loc5`='歡迎來到血色守望，$c。在我旅行的途中，累積了許多的工具，手工藝品，和所有我遇過的人所擁有的知識。$B$B如果你發現有你需要的知識，那就跟我說吧。', `MaleText_loc7`='$gBienvenido:Bienvenida; a la Avanzada de Sangre, $c. En mis viajes, he acumulado una gran variedad de herramientas, artefactos y conocimiento de las diversas gentes con las que me he encontrado.$B$BSi ves que necesitas estos conocimientos, solo tienes que decirlo.' WHERE `ID`=14288;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이름에서 추측할 수 있는 것처럼 파멸의 버섯은 폐허 근처에서 찾을 수 있소. 로레스아란에 해답이 있소이다.$B$B사실 이 버섯의 이름에 진짜로 그런 의미가 있는 것은 아니고, 그저 괜찮은 이름을 붙이려고 고민을 좀 했을 뿐이라오.', `MaleText_loc4`='顾名思义，你可以在洛雷萨兰废墟周围找到这东西。$B$B确切地说，这名字其实是我起的……很棒吧。', `MaleText_loc5`='就像它的名字一樣，你可以在廢墟旁找到它。羅薩倫握有答案。$B$B其實，它的名字並不真正意指那樣 - 我只是想藉替真菌命名來耍點小聰明。', `MaleText_loc7`='Como el nombre sugiere, se puede encontrar cerca de unas ruinas. Loreth''Aran tiene la respuesta.$B$BDe hecho, la verdad es que el nombre no sugiere eso – solo intentaba hacerme el listo al nombrar los hongos.' WHERE `ID`=14289;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제세라, 지옥방울버섯이 있는 곳을 알려주시겠습니까?', `MaleText_loc4`='耶塞拉，你能告诉我去哪里找邪锥蘑菇吗？', `MaleText_loc5`='潔希拉，你可以告訴我去哪裡找魔錐果真菌嗎?', `MaleText_loc7`='Jessera, ¿podrías dirigirme hacia el hongo de bellota vil?', `FemaleText_loc1`='제세라, 지옥방울버섯이 있는 곳을 알려주시겠어요?', `FemaleText_loc4`='耶塞拉，你能告诉我去哪里找邪锥蘑菇吗？', `FemaleText_loc5`='潔希拉，你可以告訴我去哪裡找魔錐果真菌嗎?', `FemaleText_loc7`='Jessera, ¿podrías dirigirme hacia el hongo de bellota vil?' WHERE `ID`=14290;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지옥방울이라는 이름은 사악한 마법 오염에서 따온 것이오. 서쪽에 있는 나지비안 사티로스 야영지에서 지옥방울버섯을 찾아보시오.', `MaleText_loc4`='邪锥这个名字起源于堕落的邪恶魔法。去纳兹维安萨特营地寻找邪锥蘑菇吧，就在西边。', `MaleText_loc5`='魔錐果的名字起源為邪惡魔法的墮落。去納茲維恩的薩特營地 - 在西邊尋找魔錐果真菌。', `MaleText_loc7`='La bellota vil debe su nombre a la corrupción de la magia vil. Busca el hongo de bellota vil en el campamento de sátiros de Nazzivian: al oeste.' WHERE `ID`=14291;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제세라, 피버섯이 있는 곳을 알려주시겠습니까?', `MaleText_loc4`='耶塞拉，你能告诉我去哪里找血蘑菇吗？', `MaleText_loc5`='潔希拉，你可以告訴我去哪裡找血色蘑菇嗎?', `MaleText_loc7`='Jessera, ¿podrías dirigirme hacia los champiñones sanguinos?', `FemaleText_loc1`='제세라, 피버섯이 있는 곳을 알려주시겠어요?', `FemaleText_loc4`='耶塞拉，你能告诉我去哪里找血蘑菇吗？', `FemaleText_loc5`='潔希拉，你可以告訴我去哪裡找血色蘑菇嗎?', `FemaleText_loc7`='Jessera, ¿podrías dirigirme hacia los champiñones sanguinos?' WHERE `ID`=14292;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피버섯은 다른 버섯보다 훨씬 평범하여 핏빛안개 섬 주변의 숲 속의 거의 모든 지역에서 찾아볼 수 있소. 목숨을 소중하게 생각한다면 핏빛안개 섬을 가르는 길의 남쪽을 계속 찾아보시오.', `MaleText_loc4`='血蘑菇和其它蘑菇比起来就普通多了，几乎可以在秘血岛周围森林中的任何地方找到。如果你不想丢了小命，就到秘血岛上的大道南边找找。', `MaleText_loc5`='血色蘑菇比其他菌類更普遍而且幾乎可以在血謎島的樹林各處找到。如果你想活久一點就到那條區分血謎島的路南方尋找。', `MaleText_loc7`='Los champiñones sanguinos son más comunes que las otras variedades de hongos y generalmente se pueden encontrar en cualquier parte de los bosques que rodean Bruma de Sangre. Busca hacia el sur del camino que divide Bruma de Sangre, si aprecias tu vida.' WHERE `ID`=14293;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법사여, 이... 무슨 짓을 한 것인가? 어떻게 이럴 수가! 내 몸속에서... 불이 타오르다니!', `MaleText_loc4`='你做了些什么，巫师？这不可能！我……我的身体燃烧起来了！', `MaleText_loc5`='你做了什麼，巫師?這是不可能的!我在燃燒...從體內!', `MaleText_loc7`='¿Qué has hecho, mago? ¡No puede ser! Me quemo... ¡desde dentro!' WHERE `ID`=14294;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용이여, 나를 화나게 하는군. 난 아랫마을 주민들처럼 쉽게 겁먹지는 않을 걸세.', `MaleText_loc4`='你吸引了我的注意力，龙。跟下面那些村民不一样，我可不容易被吓倒。', `MaleText_loc5`='你已經引起了我的注意，飛龍。你會發現我不像下面的村民那樣容易害怕。', `MaleText_loc7`='Tienes mi atención, dragón. Verás que no me asusto tan fácilmente como los aldeanos de abajo.' WHERE `ID`=14295;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='메디브여, 비전에 대한 그대의 연구는 도를 넘어섰도다. 그대의 연구가 그대가 이해할 수 있는 범위를 넘어선 강력한 존재들의 관심을 끌었더군. 그대는 지금 즉시 카라잔을 떠나야 한다!', `MaleText_loc4`='麦迪文，你沉迷于研究奥术能量，已经偏离了正道。你已经引起了某种远远超越你所能理解的力量的关注。你必须立即离开卡拉赞！', `MaleText_loc5`='你對秘法的涉獵已經太超過了，麥迪文。你已經引起了你所不能理解的力量注意。你一定要立刻離開卡拉贊!', `MaleText_loc7`='Tus incursiones en lo Arcano han ido demasiado lejos, Medivh. Has atraído la atención de fuerzas que no podrías comprender. ¡Debes abandonar Karazhan de inmediato!' WHERE `ID`=14296;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 내 집에서 나에게 도전하다니 아무리 용이라지만 오만함이 하늘을 찌르는구나!', `MaleText_loc4`='你胆敢在我的地盘挑战我？虽然你是一条龙，但是你的自大仍然让我震惊！', `MaleText_loc5`='你竟敢在我的地盤挑戰我?你的傲慢真是令人驚奇，就連對一隻龍而言也是一樣!', `MaleText_loc7`='¿Osas desafiarme en mi propia morada? ¡Tu arrogancia es asombrosa, hasta para un dragón!' WHERE `ID`=14297;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠의 힘이 그대를 이용하려고 기다리고 있도다, 메디브여! 이곳에 계속 머무를수록 끔찍한 일을 겪게 될 것이다. 시간이 얼마 없으니 서둘러야 한다!', `MaleText_loc4`='一股黑暗的力量正在利用你，麦迪文！如果你执意留下，可怕的日子就会很快到来。你必须赶快，我们的时间不多了！', `MaleText_loc5`='一股黑暗力量想利用你，麥迪文!如果你留下，悲慘的日子就會持續下去。你一定要快，我們沒有太多時間!', `MaleText_loc7`='¡Un poder oscuro intenta utilizarte, Medivh! Si te quedas, vendrán días temibles. ¡Debes apresurarte, no tenemos mucho tiempo!' WHERE `ID`=14298;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 무슨 말을 하는지 모르겠군, 용이여... 하지만, 나는 이런 무례한 행동에 겁을 먹지는 않을 것이야. 때가 되면 그때 카라잔을 떠날 것일세!', `MaleText_loc4`='我不知道你在说什么，龙……但是我不会被你这傲慢的表象吓倒。我想什么时候离开卡拉赞，就什么时候离开卡拉赞！', `MaleText_loc5`='我不清楚你在說什麼，飛龍...但我不會被這樣無禮的表現所威脅。只有在我覺得適合的時候，我才會離開卡拉贊。', `MaleText_loc7`='No sé de qué estás hablando, dragón..., pero no me acobardará esta demostración de insolencia. ¡Me iré de Karazhan cuando me plazca!' WHERE `ID`=14299;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선택의 여지를 주지 않는구나, 메디브. 충고를 들으려 하지 않는다면 힘으로 막는 수밖에 없도다!', `MaleText_loc4`='你让我别无选择。如果你不愿意讲道理的话，我就要使用武力了！', `MaleText_loc5`='你讓我別無選擇。你如果不能聽進道理，我就要用武力來阻止你了!', `MaleText_loc7`='No me dejas alternativa. ¡Te detendré por la fuerza si no atiendes a razones!' WHERE `ID`=14300;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$g형제:자매;가 핏빛안개 섬에 있는 동안 배워야 하는 한 가지가 있다면 그건 바로 경계심을 가지는 일일세. 이 섬은 먼저 부주의한 자들의 목숨을 앗아간 후, 경계가 철저한 전사들을 노리기 시작하지.$B$B어딜 가든 적은 $g형제:자매;의 목숨을 빼앗을 기회를 엿보고 있을 걸세.', `MaleText_loc4`='如果你在秘血岛的时候只学到一样东西，$c，我希望那是“警惕”。最初，这座岛屿看起来很安全，然而危险逐渐浮现，甚至是最谨慎的战士都会随时陷入危险。$B$B无论在哪里，总有敌人想要取走你的性命。', `MaleText_loc5`='如果你在血謎島的時間裡只學會一件事，$c，我希望那是警惕。這座島會先奪去不警惕的生命，再開始削弱最謹慎的戰士。$B$B你所到之處，都有一個敵人準備好要奪走你的性命。', `MaleText_loc7`='Si aprendes una cosa durante el tiempo que pases en Bruma de Sangre, $c, espero que sea la vigilancia. Esta isla se lleva primero a los imprudentes y, después, empieza a desgastar incluso al más precavido de los guerreros.$B$BMires donde mires, se erige un enemigo dispuesto a arrancarte la vida.' WHERE `ID`=14301;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='추락 사건 이후 지금까지 벌어진 모든 일은 단지 시작에 불과합니다. 엑소다르를 탄 것이 마치 전생의 일처럼 느껴지는군요.$B$B지금 제 현실은 돌연변이 생물들 그리고 수많은 블러드 엘프 첩자들과 함께 이 섬에 갇혀 있다는 것입니다. 조만간 저도 그들과 별반 다를 바 없는 처지가 될 테지요...', `FemaleText_loc4`='自从坠毁之后，我看什么东西都是模糊一片。仿佛登上埃索达已经是很久很久以前的事情了。$B$B现在，我的世界中充满了变异的生物和无尽的血精灵。很快，也许我就不会记得任何别的东西了……', `FemaleText_loc5`='自從失事後發生的所有事已逐漸明朗。我好像已經上來艾克索達一輩子那麼久。$B$B現在，我的真實生活就侷限在這座島上，伴隨著突變的生物和無盡的海上血精靈密探。很快的，一切就變的好像我從沒見過什麼不同的事物一樣...', `FemaleText_loc7`='Todo lo que ha pasado desde el accidente es poco más que una imagen borrosa. Parece que haya pasado toda una vida desde que estaba a bordo de El Exodar.$B$BAhora, mi realidad se ve restringida a esta isla, con sus criaturas mutantes y su interminable mar de agentes elfos. Pronto será como si nunca hubiera conocido nada diferente...' WHERE `ID`=14302;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 이들은 이 땅을 보고 죽음, 오염, 불행만을 떠올리지. 물론 불행한 일들이 만연한 것이 사실이나, 그런 견해 때문에 우리의 주변 환경이 주는 무한한 기회들마저 무시되고 있소이다.$B$B나는 마냥 뒷짐만 지고 서서 이런 기회가 사라지는 것을 보고만 있지는 않겠소. 당신이 도와준다면 여기 핏빛 감시초소에 있는 다른 이들에게 주변 환경과 생물들을 이용하는 방법을 보여줄 수 있소이다. 당신의 힘을 빌려주겠소?', `MaleText_loc4`='在其他人看来，这个地方只有死亡、堕落和灾难。说实话，这里确实充满了这些东西。但是那些观点忽视了这个全新的环境赐予我们的机会。$B$B我不会呆呆地站在这里，忽视那些宝贵的机会，$c。在你的帮助下，我们可以向秘血岗哨的其他人展示如何利用环境，以及生活在这种环境中的生物。', `MaleText_loc5`='其他人看著這片風景而他們只看到了死亡，腐敗，和厄運。沒有任何東西短缺，的確，但眼前的景象讓人忽略了我們環境所帶來的機會。$B$B我不會坐視不管讓這些機會被白白忽略，$c。有了你的幫助，我們可以讓血色守望這裡的其他人看看如何利用環境和其中的生物。', `MaleText_loc7`='Algunos ven en este paisaje solo muerte, corrupción y adversidad. Es cierto que no falta nada de eso, pero esa visión no tiene en cuenta las oportunidades que ofrece nuestro entorno.$B$BYo no voy a quedarme de brazos cruzados viendo cómo no se aprovechan esas oportunidades, $c. Con tu ayuda, podremos enseñar a los demás en Avanzada de Sangre a aprovechar el entorno y sus criaturas.' WHERE `ID`=14303;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, $c|1이여;여;?$B$B저기 저쪽에 있는 케셀은 교활한 노인네입니다. 그를 상대할 때는 정말 조심해야 합니다.$B$B그가 제게 ''엘레크 관리직''을 제안했는데 저는 바보처럼 그게 그저 먹이나 주고 훈련 좀 시키는 그런 일인 줄 알았죠. 그가 제게 삽을 건네준 순간, 그렇게 간단한 일이 아니라는 걸 알았습니다...', `MaleText_loc4`='你好，$c。$B$B凯希尔就在那边，他是个非常聪明的家伙，跟他打交道要非常小心才行。$B$B他给我提供了一个“照顾雷象”的工作，愚蠢的我认为这只是一个简单的喂养或者训练之类的工作。当他交给我一把铁铲的时候，我才知道那是干什么的……', `MaleText_loc5`='哈囉，$c。$B$B長者凱索在那裡，他是個聰明的人。如果我是你，我會非常小心的和他交易。$B$B他提供我照料伊萊克的工作叫我當一個蠢蛋，我以為是供我吃，訓練，等等之類的。後來當他遞給我鐵鍬時一切就很明顯了...', `MaleText_loc7`='Hola, $c.$B$BAhí está el viejo Kessel. Es muy listo. Yo tendría cuidado si hiciera tratos con él.$B$BMe ofreció trabajo "cuidando elekks" y yo, tonto de mí, pensé que se trataba de darles de comer y cosas así. Las cosas me quedaron más claras cuando me dejó esta pala...' WHERE `ID`=14304;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 지금 당장 부활해야 합니다.', `MaleText_loc4`='我应该现在就复活。', `MaleText_loc5`='我現在要復活。', `MaleText_loc7`='Ahora debería descansar.', `FemaleText_loc1`='나는 지금 당장 부활해야 해요.', `FemaleText_loc4`='我应该现在就复活。', `FemaleText_loc5`='我現在要復活。', `FemaleText_loc7`='Ahora debería descansar.' WHERE `ID`=14305;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투 준비! 죄수가 달아나고 있다!', `MaleText_loc4`='拿起武器！囚犯们逃走了！', `MaleText_loc5`='準備作戰!囚犯逃跑!', `MaleText_loc7`='¡A las armas! ¡El prisionero escapa!', `FemaleText_loc1`='전투 준비! 죄수가 달아나고 있다!', `FemaleText_loc4`='拿起武器！囚犯们逃走了！', `FemaleText_loc5`='準備作戰!囚犯逃跑!', `FemaleText_loc7`='¡A las armas! ¡El prisionero escapa!' WHERE `ID`=14306;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 강력한 마법을 걸어 자신의 정수를 마력으로 바꿉니다.', `MaleText_loc4`='%s开始释放一个强大的法术，把他自己的精华融入到了魔法中。', `MaleText_loc5`='%s開始施展一個強大能量法術，將他的本體交織在魔法裡。', `MaleText_loc7`='%s comienza a lanzar un hechizo de gran poder, entregando su propia esencia a la magia.' WHERE `ID`=14308;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자들이 방어선을 뚫었다!', `MaleText_loc4`='入侵者已经攻破了防线！', `MaleText_loc5`='入侵者已經突破了防禦線!', `MaleText_loc7`='¡Unos invasores han traspasado las defensas!' WHERE `ID`=14309;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='궁수들, 대열을 갖춰라! 지시를 내리겠다!', `MaleText_loc4`='弓箭手！就位！看我的标记……', `MaleText_loc5`='弓箭手們，隊型排列!聽我口令...', `MaleText_loc7`='¡Arqueros, formen filas! ¡A mi señal!' WHERE `ID`=14310;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비!', `MaleText_loc4`='预备……', `MaleText_loc5`='準備!', `MaleText_loc7`='¡Listos!' WHERE `ID`=14311;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알려줘서 고맙소, $n! 어서 대비를 해야겠군!', `MaleText_loc4`='$n，谢谢你的提醒！我们这就着手准备！', `MaleText_loc5`='謝謝你的警告，$n!我們會做好準備!', `MaleText_loc7`='¡Gracias por la advertencia, $n! ¡Nos prepararemos!' WHERE `ID`=14312;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예언의 현신이여, 소식을 전해줘서 고맙소이다. 너울소나무 일족은 블러드 엘프 공격에 대비하여 만반의 준비를 할 것이오.', `MaleText_loc4`='英雄，感谢你的警告。止松要塞会准备好的。', `MaleText_loc5`='允諾者，我們感謝你的警告。靜松部族會做好準備。', `MaleText_loc7`='$gPrometido:Prometida;, te agradecemos la advertencia. La tribu Semprepino estará preparada.' WHERE `ID`=14313;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 알려줘서 고맙소. 방어할 준비를 하겠소이다.', `MaleText_loc4`='感谢你的提醒，$n。我们会做好防御准备的。', `MaleText_loc5`='謝謝你的警告，$n。我們會做好防禦。', `MaleText_loc7`='Gracias por el aviso, $n. Prepararemos nuestras defensas.' WHERE `ID`=14314;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다시 안으로 들어갈게요. 다른 일이 생기면 저에게 알려주십시오.', `FemaleText_loc4`='我回里面去了。要是有什么其它事情，告诉我一声。', `FemaleText_loc5`='我要進去裡面。有任何事都要讓我知道。', `FemaleText_loc7`='Vuelvo dentro. Hazme saber si surge cualquiera otra cosa.' WHERE `ID`=14315;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 화를 돋우지 말았어야 했다. 이제 그만 가야한다... 내 힘을 회복해야 해...', `MaleText_loc4`='他不应该惹恼我。我必须……恢复我的力量……', `MaleText_loc5`='他不該激怒我。我一定要走...快恢復我的力量...', `MaleText_loc7`='No debería haberme hecho enfadar. Debo irme... recuperar mis fuerzas...' WHERE `ID`=14316;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 엘레크 군주이자 아르거스의 대리인의 신도인 케셀이라고 하오. 당신은 아르거스의 대리인의 신입 신도인가?', `MaleText_loc4`='我是凯希尔，雷象之王，阿古斯之手的成员。你是新来的吗？', `MaleText_loc5`='我是凱索，伊萊克的統治者，阿古斯之手的追隨者。你是新成員嗎?', `MaleText_loc7`='Soy Kessel, señor de los elekk, discípulo de la Mano de Argus. ¿Eres el nuevo recluta?' WHERE `ID`=14317;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오랜 시간을 연구했지만... 아무런 성과도 없군요! 그들이 옳았나 봐요. 우리가 더불어 사는 방법을 배워야 하나 봅니다.', `FemaleText_loc4`='这么多年来的研究……结果却是一场空！也许他们是对的，也许这是我们必须与之斗争一生的东西。', `FemaleText_loc5`='那麼多年來的研究...而且沒有報酬!或許他們是對的，或許我們就是要學著和這樣的事物一起生活。', `FemaleText_loc7`='Todos estos años de investigación... ¡y para nada! Quizás tenían razón, quizás esto sea algo con lo que debemos aprender a vivir.' WHERE `ID`=14318;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s |1이;가; 한 손으로 코를 쥔 채 대변을 퍼서 양동이에 담습니다.', `MaleText_loc4`='%s捏住鼻子，把挖出的粪便放在他的篮子里面。', `MaleText_loc5`='%s捏住他的鼻子，舀出糞肥並放入他的水桶裡。', `MaleText_loc7`='Tapándose la nariz, %s recoge el estiércol y lo mete en su cubo.' WHERE `ID`=14319;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최선을 다하겠습니다만 확답은 못 드리겠군요. 이 무기는 완전히 부서져서 말입니다.', `MaleText_loc4`='我会尽我所能，但是我不保证什么。这把武器已经完全粉碎了。', `MaleText_loc5`='我會盡力。不過，不能保證。這個武器已經完全粉碎了。', `MaleText_loc7`='Haré lo que pueda. Pero no prometo nada. Esta arma está totalmente destrozada.' WHERE `ID`=14320;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='금속을 건졌으니 이 무기를 검이나 단검으로 재련할 수 있을 겁니다.', `MaleText_loc4`='所谓废物利用，就是说我应该可以把这些金属重新铸造成一把剑或者匕首。', `MaleText_loc5`='這金屬是可以利用的。我可以重新將它鑄造成劍或匕首。', `MaleText_loc7`='El metal se pudo salvar. Podría ser capaz de volver a forjar el arma con una espada o una daga.' WHERE `ID`=14321;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뾰족가지 펄볼그의 분노를 받아라!', `MaleText_loc4`='面对刺臂部族的愤怒吧！', `MaleText_loc5`='見識鬚肢的憤怒吧!', `MaleText_loc7`='¡Enfréntate a la ira de Brazolanudo!' WHERE `ID`=14322;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구해 주셔서 정말 감사합니다, $n! 우리 아버지께서 기뻐하실 거예요!', `MaleText_loc4`='谢谢你救了我，$n！我父亲会很高兴的！', `MaleText_loc5`='謝謝你救了我，$n!我父親會很高興的!', `MaleText_loc7`='Gracias por salvarme, $n. ¡Mi padre se pondrá muy contento!' WHERE `ID`=14323;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하시오. 나는 핏빛 감시초소의 원정대장인 아켈루스라고 하오.', `MaleText_loc4`='我是阿彻鲁斯，秘血岗哨远征军首席指挥官。', `MaleText_loc5`='我是阿奇拉斯，血色守望的主要遠征人員。', `MaleText_loc7`='Soy Achelus, oficial en jefe de la expedición de Avanzada de Sangre.' WHERE `ID`=14324;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 하늘안개 섬으로 오고 가는 우편 업무를 담당하고 있습니다. 전갈을 보내려면 아마 가장 먼저 제 손을 거치게 될 겁니다.', `MaleText_loc4`='我是往来于这里和秘蓝岛之间的邮差，$c。如果你有什么消息需要递送，很可能是要交给我来办的。', `MaleText_loc5`='我遞送和藍謎島往來的郵件，$c。如果你需要遞送訊息，它非常有可能會先由我這裡發送。', `MaleText_loc7`='Reparto el correo a y desde Bruma Azur, $c. Si necesitas que se entregue un mensaje, es más que probable que se envíe primero a través de mí.' WHERE `ID`=14325;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아르거스의 대리인의 일원이 된다는 의미는... 성스러운 빛의 대리자가 된다는 뜻이오. 어떠한 의심도 없이 봉사해야 하며 어떠한 의심도 없이 기꺼이 죽음을 맞이해야 하오.', `MaleText_loc4`='成为一个阿古斯之手的意义是什么……我们是圣光的代言人。我们全心全意的服务，就算让我们去死，我们也勇往直前。', `MaleText_loc5`='成為阿古斯之手的意義...我們是聖光的密探。我們毫無疑問的效命。沒有懷疑的死去。', `MaleText_loc7`='Lo que significa ser de la Mano de Argus... Somos agentes de la Luz. Servimos sin preguntas. Morimos sin preguntas.' WHERE `ID`=14326;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들이 절 찾아보라고 당신을 보냈습니까? 그래도 제 부하들 없이는 돌아가지 않겠습니다.', `MaleText_loc4`='是他们派你来找我的吗？我不会丢下伙伴独自回去的。', `MaleText_loc5`='是他們派你來找我的嗎?我不會丟下我的人回去的。', `MaleText_loc7`='¿Te han enviado a buscarme? Yo no vuelvo sin mis hombres.' WHERE `ID`=14327;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신들은 우편물을 확인도 안 합니까?', `MaleText_loc4`='你们从来都不看信箱的吗？', `MaleText_loc5`='你們從來都不收信的嗎?', `MaleText_loc7`='¿Es que nunca miráis el correo?' WHERE `ID`=14328;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 저 혼자서 이 모든 편지를 배달하라는 겁니까?', `MaleText_loc4`='我要怎么样才能把这么多邮件都送出去？', `MaleText_loc5`='我要怎麼遞送所有這些訊息?', `MaleText_loc7`='¿Cómo se supone que voy a entregar todos estos mensajes?' WHERE `ID`=14329;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배치를 다시 받고 싶은 심정이로군요. 이 일은 정말 너무 힘들단 말입니다...', `MaleText_loc4`='我要换个工作。这个工作快要让我崩溃了……', `MaleText_loc5`='我需要重新分配。這份工作快把我逼到極限了...', `MaleText_loc7`='Necesito que me reasignen. Este trabajo me está llevando cada vez más al límite...' WHERE `ID`=14330;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조만간 수정 둠해머를 얻으면 전 이 마을을 등지고 곧장 오크에게 달려갈 겁니다. 그들은 그제야 후회하겠죠...', `MaleText_loc4`='总有一天，我会突然拔出水晶战锤把这地方砸个稀巴烂……看他们还催不催我！', `MaleText_loc5`='這些天裡我要破壞結晶末日錘並成為這鎮上絕對的獸人。然後他們就會很後悔...', `MaleText_loc7`='Un día de estos voy a llevarme el martillo maldito cristalino y a volverme un orco en esta ciudad. Entonces lo lamentarán...' WHERE `ID`=14331;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그는 자기가 굉장히 중요한 자라고 생각하지요. 언제나 저를 찬밥 취급하고 말입니다... 그에게 보여주고야 말 겁니다. 모두에게 보여줄 거라고요!', `MaleText_loc4`='他以为自己多么重要，总是把我呼来喝去的……我要给他点颜色看看……我要让他们所有人都尝尝我的厉害！', `MaleText_loc5`='他以為他是多麼的重要。總是愛使喚我...我會讓他見識一下。讓他們全部的人見識一下!', `MaleText_loc7`='Se cree tan importante. Siempre dándome órdenes... Yo le enseñaré. ¡Les enseñaré a todos!' WHERE `ID`=14332;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐 헤르메시우스, 나한테 온 편지 있나?', `MaleText_loc4`='嘿，赫米修斯，有什么新邮件给我吗？', `MaleText_loc5`='嘿赫米瑟斯，我有新信嗎?', `MaleText_loc7`='Eh, Hermesius, ¿tengo correo?' WHERE `ID`=14333;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헤르메시우스, 엑소다르에서 보낸 내 짐은 아직 안 왔나? 일주일도 넘었는데 말이야.', `MaleText_loc4`='赫米修斯，有从埃索达寄给我的包裹吗？已经一个多星期了。', `MaleText_loc5`='赫米瑟斯，我從艾克索達來的包裹到了沒?已經超過一個禮拜了。', `MaleText_loc7`='Hermesius, ¿ha llegado ya mi paquete de El Exodar? Ya ha pasado más de una semana.' WHERE `ID`=14334;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헤르메시우스, 빨리 와보게! 얼라이언스 원정대의 인간 사령관에게 급하게 보낼 게 있다네.', `MaleText_loc4`='赫米修斯，快点过来！我有个非常紧急的邮件，必须交给联盟远征军的人类上将。', `MaleText_loc5`='赫米瑟斯快來!我有一封緊急信件一定要送到聯盟遠征隊的人類上將手上。', `MaleText_loc7`='¡Hermeisius, ven rápido! Tengo una entrega urgente para el almirante humano de la expedición de la Alianza.' WHERE `ID`=14335;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우편물 배달하는 데 무슨 문제라도 있는 건가? 우편물이 제때 도착하지 않으면 어떻게 일을 하겠어?', `MaleText_loc4`='你的运送服务到底怎么回事？邮件从不及时送达，让我们怎么去履行职责？', `MaleText_loc5`='你的快遞服務發生了什麼問題?如果郵件永遠都無法準時抵達，我們要如何運作?', `MaleText_loc7`='¿Qué está pasando en tu servicio de entregas? ¿Cómo quieres que trabajemos sin nunca nos llega el correo a tiempo?' WHERE `ID`=14336;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 일이 그렇게 쉬워 보이면 이 무거운 가방을 들고 직접 배달해 보시지 그러십니까!', `MaleText_loc4`='如果你觉得这很简单，带上你的包去试试！', `MaleText_loc5`='如果你覺得這很簡單的話，抓起背包幹活去吧!', `MaleText_loc7`='¡SI CREES QUE ES TAN FÁCIL, AGARRA UNA BOLSA Y PONTE A TRABAJAR!' WHERE `ID`=14337;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럴 게 아니라면 그만 사라져 주십시오! 조만간 당신들이 괴롭히던 과거의 헤르메시우스는 없을 겁니다. 그것만큼은 약속하지요...', `MaleText_loc4`='要不然就离我远点！总有一天，老赫米修斯发飙了，不会再被你们支来支去。我是认真的……', `MaleText_loc5`='否則的話，不要再來煩我!這些天你將不能再使喚老赫米瑟斯了。這點我可以保證...', `MaleText_loc7`='¡De otra forma, bájate de mi espalda! Un día de estos no tendrás al viejo Hermesius para darle órdenes. Eso te lo prometo...' WHERE `ID`=14338;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='헤르메시우스씨, 저한테 온 편지가 있나요?', `FemaleText_loc4`='嘿，赫米修斯，有我的新邮件吗？', `FemaleText_loc5`='嘿赫米瑟斯，我有新信嗎?', `FemaleText_loc7`='Eh, Hermesius, ¿tengo algo de correo nuevo?' WHERE `ID`=14339;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='헤르메시우스씨, 엑소다르에서 보낸 제 짐은 아직 안 왔나요? 일주일도 넘었는데...', `FemaleText_loc4`='赫米修斯，有从埃索达寄给我的包裹吗？已经一个多星期了。', `FemaleText_loc5`='赫米瑟斯，我從艾克索達來的包裹到了沒?已經超過一個禮拜了。', `FemaleText_loc7`='Hermesius, ¿no ha llegado aún mi paquete de El Exodar? Ha pasado más de una semana.' WHERE `ID`=14340;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='헤르메시우스씨, 어서 이리 와보세요! 얼라이언스 원정대의 인간 사령관에게 급하게 보낼 물건이 있답니다.', `FemaleText_loc4`='赫米修斯，快点过来！我有一封非常紧急的邮件必须交给联盟远征军的人类上将。', `FemaleText_loc5`='赫米瑟斯快來!我有一封緊急信件一定要送到聯盟遠征隊的人類上將手上。', `FemaleText_loc7`='¡Hermesius, ven raudo! Tengo una entrega urgente que se debe llevar al almirante humano de la expedición de la Alianza.' WHERE `ID`=14341;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우편물 배달에 무슨 문제라도 있는 건가요? 우편물이 제때 도착하지 않으면 어떻게 일을 하겠어요?', `FemaleText_loc4`='你的运送服务到底怎么回事？邮件从不及时送达，让我们怎么去履行职责？', `FemaleText_loc5`='你的快遞服務發生了什麼問題?如果郵件永遠都無法準時抵達，我們要如何運作?', `FemaleText_loc7`='¿Qué sucede en tu servicio de entrega? ¿Cómo se supone que vamos a funcionar si nuestro correo nunca llega a tiempo?' WHERE `ID`=14342;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='분명 당신은 드레나이 세계에서 가장 게으른 우편집배원으로 알려졌을 거예요.', `FemaleText_loc4`='你肯定是德莱尼人中最懒的信使了！', `FemaleText_loc5`='你一定是德萊尼史上最懶的信差。', `FemaleText_loc7`='¡Debes de ser el mensajero más perezoso que hayan conocido los draenei!' WHERE `ID`=14343;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분명 당신은 드레나이 세계에 가장 게으른 우편집배원으로 알려졌을 거요.', `MaleText_loc4`='你一定是德莱尼一族最懒惰的信使。', `MaleText_loc5`='你一定是德萊尼史上最懶的信差。', `MaleText_loc7`='Debes de ser el mensajero más perezoso que hayan conocido los draenei.' WHERE `ID`=14344;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 아르거스의 대리인을 공격하다니!', `MaleText_loc4`='你胆敢攻击阿古斯之手的成员？！', `MaleText_loc5`='你竟敢襲擊阿古斯之手密探?', `MaleText_loc7`='¿Te atreves a golpear a un agente de la Mano?' WHERE `ID`=14345;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 풀려났다! 자유다!', `MaleText_loc4`='自由了！我们自由了！', `MaleText_loc5`='我們自由了!我們自由了!', `MaleText_loc7`='¡Somos libres! ¡Somos libres!', `FemaleText_loc1`='드디어 풀려났다! 자유다!', `FemaleText_loc4`='自由了！我们自由了！', `FemaleText_loc5`='我們自由了!我們自由了!', `FemaleText_loc7`='¡Somos libres! ¡Somos libres!' WHERE `ID`=14346;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야호! 고맙습니다!', `MaleText_loc4`='哇！谢谢你了！', `MaleText_loc5`='哇喔!謝啦!', `MaleText_loc7`='¡Guau! ¡Gracias!', `FemaleText_loc1`='야호! 고마워요!', `FemaleText_loc4`='哇！谢谢你了！', `FemaleText_loc5`='哇喔!謝啦!', `FemaleText_loc7`='¡Guau! ¡Gracias!' WHERE `ID`=14347;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벨렌 님의 보살핌 덕분에 제가 구출되었군요! 감사합니다!', `MaleText_loc4`='以维伦的名义，我得救了！', `MaleText_loc5`='以費倫的額徽之名，我被拯救了!', `MaleText_loc7`='¡Por el sello de la frente de Velen, estoy salvado!', `FemaleText_loc1`='벨렌 님의 보살핌 덕분에 제가 구출되었군요! 감사합니다!', `FemaleText_loc4`='以维伦的名义，我得救了！', `FemaleText_loc5`='以費倫的額徽之名，我被拯救了!', `FemaleText_loc7`='¡Por el sello de la frente de Velen, estoy salvada!' WHERE `ID`=14348;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 알고 있었어요. 코르넬리우스는 우릴 남겨두고 가지 않는다는 사실을!', `MaleText_loc4`='我知道考内留斯不会丢下我们的！', `MaleText_loc5`='我就知道卡尼勒斯不會丟下我們的!', `MaleText_loc7`='¡Sabía que Cornelius no nos dejaría atrás!', `FemaleText_loc1`='전 알고 있었어요. 코르넬리우스는 우릴 남겨두고 가지 않는다는 사실을!', `FemaleText_loc4`='我知道考内留斯不会丢下我们的！', `FemaleText_loc5`='我就知道卡尼勒斯不會丟下我們的!', `FemaleText_loc7`='¡Sabía que Cornelius no nos dejaría atrás!' WHERE `ID`=14349;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='널 처치하고 주인님을 기쁘게 해드려야겠다.', `MaleText_loc4`='主人得知你的死讯一定会非常满意。', `MaleText_loc5`='你的死會讓我們的主人很滿意。', `MaleText_loc7`='Tu muerte satisfará a nuestro maestro.', `FemaleText_loc1`='널 처치하고 주인님을 기쁘게 해드려야겠다.', `FemaleText_loc4`='主人得知你的死讯一定会非常满意。', `FemaleText_loc5`='你的死會讓我們的主人很滿意。', `FemaleText_loc7`='Tu muerte satisfará a nuestro maestro.' WHERE `ID`=14350;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇다, 나는 ''뒤틀린 드레나이''이지. 내가 뒤틀린 드레나이라고 해서 너에게 피해가 되는 일이라도 있나? 우린 사회 일부에서 우리를 향해 던지는 멸시의 시선을 견뎌야 한다. 이 세계의 정령을 더욱 잘 이해하고 원활하게 교감하는 것이 가장 중요한 일이지.', `MaleText_loc4`='对，我是一个破碎者。我相信这并不会让你觉得不安吧。破碎者或者德莱尼人，我们必须忍受可能遭受的嘲笑。和这个世界上的元素们更好地理解和沟通，这才是最要紧的事。', `MaleText_loc5`='是的，我是「破碎者」的一員。我相信這不會讓你困擾吧?破碎者或德萊尼，我們一定要容忍社會對我們的奚落和嘲笑。和這世界的元素有更好的了解和溝通才是最重要的事。', `MaleText_loc7`='Sí, soy de los Tábidos. Espero que no te moleste. Tábido o draenei, siempre hay quien te margina desde dentro de la sociedad. Lo único que importa es conocerse mejor y comunicarse con los que forman este mundo.', `FemaleText_loc1`='그렇다, 나는 ''뒤틀린 드레나이''이지. 내가 뒤틀린 드레나이라고 해서 너에게 피해가 되는 일이라도 있나? 우린 사회 일부에서 우리를 향해 던지는 멸시의 시선을 견뎌야 한다. 이 세계의 정령을 더욱 잘 이해하고 원활하게 교감하는 것이 가장 중요한 일이지.', `FemaleText_loc4`='对，我是一个破碎者。我相信这并不会让你觉得不安吧。破碎者或者德莱尼人，我们必须忍受可能遭受的嘲笑。和这个世界上的元素们更好地理解和沟通，这才是最要紧的事。', `FemaleText_loc5`='是的，我是「破碎者」的一員。我相信這不會讓你困擾吧?破碎者或德萊尼，我們一定要容忍社會對我們的奚落和嘲笑。和這世界的元素有更好的了解和溝通才是最重要的事。', `FemaleText_loc7`='Sí, soy de los Tábidos. Espero que no te moleste. Tábido o draenei, siempre hay quien te margina desde dentro de la sociedad. Lo único que importa es conocerse mejor y comunicarse con los que forman este mundo.' WHERE `ID`=14351;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='편히 앉아 쉬십시오.', `MaleText_loc4`='请坐下，不要拘束。', `MaleText_loc5`='請，當自己家一樣坐下。', `MaleText_loc7`='Siéntate y ponte $gcómodo:cómoda;.', `FemaleText_loc1`='편히 앉아 쉬세요.', `FemaleText_loc4`='请坐下，不要拘束。', `FemaleText_loc5`='請，當自己家一樣坐下。', `FemaleText_loc7`='Siéntate y ponte $gcómodo:cómoda;.' WHERE `ID`=14352;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 그래, 도망자들의 피는 내게 힘을 주지! 핏빛안개 섬이여, 조심해라!', `MaleText_loc4`='啊……流放者之血赐予了我力量！秘血岛，我来了！', `MaleText_loc5`='啊...是的，放逐者的血給了我力量!小心，血謎!', `MaleText_loc7`='Ahhh... ¡Sí, la sangre de los exiliados me llena de fuerza! ¡Cuidado, Bruma de Sangre!' WHERE `ID`=14353;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='캘타스의 추종자들이여, 적을 무찌르자! 놈들에게 에레둔을 피해 달아날 곳은 없다는 것을 보여주자!', `MaleText_loc4`='过来，凯尔萨斯的追随者们，消灭我们的敌人！让他们知道没有人可以从我们手中逃走！', `MaleText_loc5`='來吧，凱爾薩斯的追隨者，讓我們摧毀我們的敵人吧!讓他們知道他們逃不出艾瑞達的手掌心!', `MaleText_loc7`='Vamos, seguidores de Kael, ¡destruyamos a nuestros enemigos! ¡Demostrémosles que no se puede huir de los Eredun!' WHERE `ID`=14354;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번 공격이 너무 오랫동안 지체되고 있다. 드레나이와 녀석들의 불쌍한 도시를 파괴해 버리자!', `MaleText_loc4`='总攻的时刻到了，让我们摧毁德莱尼人和他们那可怜的城市！', `MaleText_loc5`='圍攻已經靜止太久了，讓我們摧毀德萊尼和他們可悲的城市吧!', `MaleText_loc7`='Este asedio ha estado latente durante demasiado tiempo, ¡destruyamos a los draenei y su lamentable ciudad!' WHERE `ID`=14355;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제, 모두 죽인다!', `MaleText_loc4`='现在，杀光他们！', `MaleText_loc5`='現在，殺光他們!', `MaleText_loc7`='¡Ahora, matadlos a todos!' WHERE `ID`=14356;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 안녕하십니까? 믿음직한 히포그리프를 찾고 계신가요?', `MaleText_loc4`='早上好，$c。你需要可靠的角鹰兽吗？', `MaleText_loc5`='你好，$c。你需要一隻可靠的角鷹獸嗎?', `MaleText_loc7`='Buen día, $c. ¿Necesitas un hipogrifo fiable?' WHERE `ID`=14357;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='히포그리프를 타고 여행을 하고 싶습니다.', `MaleText_loc4`='我想骑着角鹰兽旅行。', `MaleText_loc5`='我想坐角鷹獸旅行。', `MaleText_loc7`='Deseo viajar en hipogrifo.', `FemaleText_loc1`='히포그리프를 타고 여행을 하고 싶어요.', `FemaleText_loc4`='我想骑着角鹰兽旅行。', `FemaleText_loc5`='我想坐角鷹獸旅行。', `FemaleText_loc7`='Deseo viajar en hipogrifo.' WHERE `ID`=14358;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엑소다르로 가려는 참이라면 당신에게 딱 알맞은 히포그리프가 있습니다!', `MaleText_loc4`='如果你需要去埃索达，就乘坐我的角鹰兽吧！', `MaleText_loc5`='如果你想前往艾克索達，我這裡有角鷹獸可載你前往!', `MaleText_loc7`='¡Si tienes que viajar a El Exodar, tengo el hipogrifo perfecto para ti!' WHERE `ID`=14359;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='히포그리프를 타고 여행을 하고 싶습니다.', `MaleText_loc4`='我想要乘坐角鹰兽。', `MaleText_loc5`='我想坐角鷹獸旅行。', `MaleText_loc7`='Deseo viajar en hipogrifo.', `FemaleText_loc1`='히포그리프를 타고 여행을 하고 싶어요.', `FemaleText_loc4`='我想要乘坐角鹰兽。', `FemaleText_loc5`='我想坐角鷹獸旅行。', `FemaleText_loc7`='Deseo viajar en hipogrifo.' WHERE `ID`=14360;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 녹슬기 시작합니다!', `MaleText_loc4`='%s开始生锈了！', `MaleText_loc5`='%s開始生鏽!', `MaleText_loc7`='¡%s comienza a oxidarse!' WHERE `ID`=14361;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쉿! 조용히 하세요. 전 여기 숨어서 멀록을 관찰하고 있단 말입니다.$B$B이 커다란 거북이 껍데기 속에 숨어 지내는 건 모두 연구를 위한 것이지요. 멀록이 여기에 있는 저를 발견하면 제 존재에 반응할 것이고 그럼 자료를 완성할 수 없거든요!$B$B탐험가 연맹에 가입한 최초의 노움으로서 저는 지금까지 어떤 드워프도 올라가지 못했던 자리까지 오를 겁니다!', `MaleText_loc4`='嘘！安静点，我正在监视那些鱼人。$B$B住在这个大龟壳里是我对科学的献身精神的体现。毕竟，要是让那些鱼人看到我在这里，它们肯定会做出一些反应，这样数据就乱套了！$B$B作为探险者协会的第一名侏儒会员，我大胆地来到了矮人从未涉足的地方！', `MaleText_loc5`='噓!安靜;我正在觀察魚人。$B$B住在一個超大型的烏龜殼裡是我願意為科學所做的犧牲。畢竟，如果魚人看到我在這裡，他們的反應就會因為我的存在而改變，那樣會降低我資料的真實度!$B$B身為探險者協會的第一名地精成員，我大膽地進入沒有矮人敢去的地方!', `MaleText_loc7`='¡Shh! Silencio absoluto; estoy observando a los múrlocs.$B$BVivir en un caparazón de tortuga gigante es un sacrificio que estoy dispuesto a hacer por la ciencia. Después de todo, si los múrlocs me ven aquí, ¡reaccionarán ante mi presencia y contaminarán mis datos!$B$B¡Como el primer gnómico de la Liga de Expedicionarios, voy con valentía a lugares a los que ningún enano ha ido antes!' WHERE `ID`=14362;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 내가 간다, 총독!', `MaleText_loc4`='来吧，主教！', `MaleText_loc5`='我現在為你而來，主教!', `MaleText_loc7`='¡Ahora vengo a por ti, exarca!' WHERE `ID`=14363;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이곳의 영혼들은 그대의 종족의 싸움에 주의를 기울이고 있습니다, $r|1이여;여;. 아마 그대가 살아서 이 경비탑을 지키는 데 성공한다면, 내 그대를 도울 수 있을 겁니다.', `FemaleText_loc4`='似乎此地的鬼魂们并不欢迎你，$r。如果你能攻下这座哨塔，我可以考虑帮助你。', `FemaleText_loc5`='這個地方的靈魂對你的族人很不友善，$r。如果你能贏得這座哨塔，我或許能夠幫你。', `FemaleText_loc7`='Los espíritus de este lugar están en contra de los de tu clase, $r. Quizás si logras conquistar la torre con la espada yo pueda ayudarte.' WHERE `ID`=14364;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공격을 막아보십시오, 풋내기 양반! 혈기사가 될 자격이 있는지 한번 봅시다!', `MaleText_loc4`='多加小心，年轻人！让我们看看你是不是个够格的血骑士。', `MaleText_loc5`='做好防禦，年輕人!我們會看看你是不是一個做血騎士的料。', `MaleText_loc7`='¡Defiéndete, jovenzuelo! Veremos si ya hay un Caballero de sangre en ti.' WHERE `ID`=14365;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 감히 우리 여왕님의 조각상을 더럽히느냐?', `MaleText_loc4`='是谁胆敢亵渎女王的雕像？', `MaleText_loc5`='誰敢褻瀆我們心愛的雕像?', `MaleText_loc7`='¿Quién se atreve a profanar la tumba de nuestra amada?' WHERE `ID`=14366;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이것은... 실버문? 으, 머리야... 다음번에 블러드밸러가 지원자를 모집하면 다른 방식을 제안해야겠습니다. 선행을 베푸는 혈기사의 모범을 보여주는 역할 말이죠!', `MaleText_loc4`='这是……银月城？我的头……下次布拉德瓦罗要找志愿者的话，我会给他介绍别人的。真正的血骑士的楷模！', `MaleText_loc5`='這是...銀月城?我的頭...下次血色英勇需要志願者，我會將他指向別的方向。血騎士德行的模範，的確!', `MaleText_loc7`='¿Es esto... Lunargenta? Mi cabeza... La próxima vez que Sangrevalor necesite un voluntario, le mandaré con otro. ¡Menudo dechado de virtudes de Caballero de sangre!' WHERE `ID`=14367;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 오해하지 마십시오. 부활시켜 주신 일은 정말 감사하게 생각합니다. 하지만, 이 특수 임무는 이번이 마지막이에요. 아, 포도주 한 잔이면 이 끔찍한 두통이 사라질 텐데...', `MaleText_loc4`='不要误解我，$n。我非常感激你救了我，不过我想这是我最后一次执行这个任务了。也许一两杯酒可以帮我减轻头痛。', `MaleText_loc5`='別誤會我，$n。我非常感謝你將我復活，但我想這是我最後一次從事這樣特定的職務。或許一兩杯酒會對頭痛有點幫助。', `MaleText_loc7`='No te equivoques, $n. Personalmente, aprecio mucho la resurrección, pero creo que será la última vez que haga esto. Puede que un vaso o dos de vino alivien el dolor de cabeza.' WHERE `ID`=14368;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제정신이오? 주위를 둘러보시오, 필멸의 존재여. 그대가 갈라진 대지 위에 서 있는 게 보이지 않으시오? 우리 종족이 겪었던 고통을 경험하고 싶지 않다면 그냥 이곳을 떠나시오...', `MaleText_loc4`='你疯了吗？看看你的周围，凡人。你没看到你正站在崩裂的大地上吗？离开这个地方，免得遭受我和我们的人民所遭受的痛苦……', `MaleText_loc5`='你瘋了嗎?看看你的四周，凡人。你沒看到你站在分裂的大地上嗎?離開這個地方，以免你遭受和我與人民一樣的苦...', `MaleText_loc7`='¿Has perdido el juicio? Mira a tu alrededor, mortal. ¿No ves que pisas tierras divididas? Abandona este lugar, para no sufrir como mi pueblo y yo lo hemos hecho...' WHERE `ID`=14369;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무엇 때문에 괴로워하는 겁니까?', `MaleText_loc4`='为什么你要受苦？', `MaleText_loc5`='你為何受苦?', `MaleText_loc7`='¿Por qué sufres?', `FemaleText_loc1`='무엇 때문에 괴로워하는 거예요?', `FemaleText_loc4`='为什么你要受苦？', `FemaleText_loc5`='你為何受苦?', `FemaleText_loc7`='¿Por qué sufres?' WHERE `ID`=14370;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대는 제정신이 아닌데다가 눈까지 멀었구려...$B$B나는 오래전에 어떤 땅에 도착하여 그곳을 지키는 데 실패했소. 그래서 한 문명이 사라졌고 그 기억을 죽어서도 지니고 있는 비참한 유령이라오.$B$B천 년 전에는 그대처럼 살과 뼈로 이루어진 존재였다오. 나는 이 땅의 왕자이자 용기수로서 꿈의 여왕 이세라의 축복을 받은 자요.', `MaleText_loc4`='你是瞎了还是疯了？$B$B我是个鬼魂，一个早已不存在的远古文明的遗留者，永远滞留在这片我没能保护好的土地上。$B$B在一万年之前，我和你一样是个血肉之躯。我曾经是这块土地的王子，也是一个被梦境之龙伊瑟拉赐福的龙骑士。', `MaleText_loc5`='你是個瘋了還是瞎了?$B$B我是個鬼魂 - 一個殘忍的提醒者，提醒著很久不存在的文明 - 繫住一塊我無法保護的土地。$B$B很久以前 - 一萬年前 - 我是有血有肉的人，就像你一樣。我是這塊土地的王子也是個龍騎士，受翡翠夢境的伊瑟拉所庇護。', `MaleText_loc7`='¿Estás $gciego:ciega; además de $gloco:loca;?$B$BSoy un fantasma - un cruel recuerdo de una civilización que hace mucho que dejó de existir – anclado a una tierra que no supe proteger.$B$BAntaño – hace diez mil años – era de carne y hueso, como tú. Era Príncipe de esta tierra y jinete de dragones, bendecido por Ysera del Sueño.' WHERE `ID`=14371;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이세라는 누구이며 당신은 어떻게 해서 축복을 받았습니까?', `MaleText_loc4`='伊瑟拉是什么？你又是怎么得到她的赐福的？', `MaleText_loc5`='伊瑟拉是什麼，你又如何被庇護?', `MaleText_loc7`='¿Qué es Ysera y cómo fuiste bendecido?', `FemaleText_loc1`='이세라는 누구이며 당신은 어떻게 해서 축복을 받았나요?', `FemaleText_loc4`='伊瑟拉是什么？你又是怎么得到她的赐福的？', `FemaleText_loc5`='伊瑟拉是什麼，你又如何被庇護?', `FemaleText_loc7`='¿Qué es Ysera y cómo fuiste bendecido?' WHERE `ID`=14372;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이세라 님에 대해 들어 보지 못했소? 자연의 수호신이나 꿈의 위상으로도 불리는 그분 말이오. 이세라 님께선 모든 녹색용의 보호자와 같은 존재요! 그렇소이다, 내 왕국에 녹색용군단을 선물한 것도 바로 이세라 님이셨지. 우리는 고귀한 존재들과 어깨를 나란히 했으며, 적과 싸울 때 녹색용들은 우리가 자신들의 등에 올라타도록 허락했소. 수 세기 동안 모든 것이 순조로왔지... 그 일이 있기 전까지는...', `MaleText_loc4`='你从没有听说过伊瑟拉？大自然的守护者？翡翠梦境的守护？她是所有绿龙的女王！是的，伊瑟拉亲自将她的血脉赐予了我的王国。我们和那些高贵的生物并肩战斗，他们允许我们骑在他们身上，在战争中击溃一切敌人。就这样愉快地过了几个世纪……直到……', `MaleText_loc5`='你沒聽過伊瑟拉?大自然的守護者?夢境之龍?她是所有綠龍軍團的母親!是的，是伊瑟拉親自將她的後裔贈送給我的王國。我們和這些高貴的生物肩並肩作戰，他們也允許我們騎著他們進入戰場對抗我們的敵人。一切都相當地美好，持續了許多個世紀...直到...', `MaleText_loc7`='¿No has oído hablar de Ysera? ¿La Guardiana de la Naturaleza? ¿El Aspecto de los sueños? ¡Es la matrona de los dragones Verdes! Sí, fue Ysera misma la que bendijo a mi pueblo con su camada. Tratábamos a esas nobles criaturas como hermanos y nos permitían montar a sus lomos para combatir al enemigo. Todo fue bien durante muchos siglos, hasta...' WHERE `ID`=14373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일이 있었습니까?', `MaleText_loc4`='直到什么时候？', `MaleText_loc5`='直到什麼?', `MaleText_loc7`='¿Hasta qué?', `FemaleText_loc1`='무슨 일이 있었나요?', `FemaleText_loc4`='直到什么时候？', `FemaleText_loc5`='直到什麼?', `FemaleText_loc7`='¿Hasta qué?' WHERE `ID`=14374;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='데스윙 혈족... 이세라 님의 선행이 검은용군단의 지도자인 데스윙의 분노를 샀소. 검은용들은 밤을 틈타 우리를 공격했지! 첫 번째 공격에서 많은 이들이 죽었지만 녹색용군단이 우리를 보호하기 위해 나섰소.$B$B<섬 주변을 가리키는 왕자 토레스>$B$B한때 거대한 녹색용이었던 그들은 지금 뼈만 남아 있다오. 아무도 살아남지 못했지.', `MaleText_loc4`='死亡之翼的子孙们……伊瑟拉的仁爱激起了死亡之翼——黑龙军团的首领的怨恨。他们在我们睡觉时发起了攻击！许多人死在第一次攻势中，但绿龙勇敢地前来保护我们。$B$B<托雷斯王子指了指岛屿的周围。>$B$B那些骸骨就是绿龙们的残骸。黑龙没有给他们留下任何活口。', `MaleText_loc5`='死亡之翼的後代...伊瑟拉的仁慈喚起了死亡之翼的憤怒 - 黑龍軍團的庇護者。他們在我們沉睡中襲擊我們!許多人在一開始的攻擊中就死了，但綠龍軍團便來保護我們。$B$B<托瑞斯王子指著這座島。>$B$B那些曾經偉大的龍群只剩下這些白骨。沒有一個倖免。', `MaleText_loc7`='La camada de Alamuerte. La bondad de Ysera despertó la ira de Alamuerte, patrón de los Vuelos Negros. ¡Nos atacaron mientras dormíamos! Murieron muchos en el primer ataque, pero los verdes nos defendieron.$B$B<El príncipe Toreth señala alrededor de la isla.>$B$BLos huesos es lo único que queda de aquellos grandes dragones. No sobrevivió ninguno.' WHERE `ID`=14375;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다들 죽었다면 왜 당신은 계속 여기에 있습니까?', `MaleText_loc4`='为什么你还在这里？', `MaleText_loc5`='那你為什麼還在這裡?', `MaleText_loc7`='Entonces, ¿por qué estás todavía aquí?', `FemaleText_loc1`='다들 죽었다면 왜 당신은 계속 여기에 있나요?', `FemaleText_loc4`='为什么你还在这里？', `FemaleText_loc5`='那你為什麼還在這裡?', `FemaleText_loc7`='Entonces, ¿por qué estás todavía aquí?' WHERE `ID`=14376;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 그들의 손에 마지막으로 희생되었소이다. 내 육신에서 영혼이 빠져나가는 게 느껴졌을 때 나는 피의 맹세를 했소.$B$B<고개를 흔드는 왕자 토레스>$B$B이 세계를 위해 내 모든 피를 바치겠다는 맹세와 함께 나와 이 대지 사이에 계약이 맺어졌지. 오직 나만이 우리 종족의 역사를 보존하고 있는 것이오.$B$B로레스아란의 용기수에 대한 이야기가 시간이 흘러도 잊혀지지 않는다는 사실을 확인하기 전에는 잠들 수가 없다오.', `MaleText_loc4`='我是最后一个牺牲的。当我的灵魂离开我那凡人的躯体时，我发了一个血誓。$B$B<托雷斯王子摇了摇头。>$B$B一个在我和这片土地之间建立的誓言：我的血属于这个世界。我变成了一个孤独地守候者，讲述着我的人民的故事。$B$B我不能休息，直到我确信洛雷萨兰龙骑士的故事不会随着时间的流逝而被遗忘。', `MaleText_loc5`='我是最後一個死的人。當我感覺我的靈魂離開了我的凡人軀殼，我便發下血誓。$B$B<托瑞斯王子搖搖他的頭。>$B$B我和這塊土地簽下一個契約:我的鮮血為這世界潑灑。我成了唯一守護我人民歷史的人。$B$B在我確信羅薩倫龍騎士的故事尚未消失在時間的洪流之前我不會休息的。', `MaleText_loc7`='Fui el último en morir. Mientras siento como mi espíritu deja mi receptáculo mortal, hice un juramento de sangre.$B$B<El príncipe Toreth niega con la cabeza.>$B$BSe llevó a cabo un pacto entre esta tierra y yo: mi sangre por este mundo. Me convertí en el único guardián de la historia de mi gente.$B$BNo puedo descansar hasta que sepa con seguridad que la historia de los jinetes de dragones de Loreth''Aran no se ha perdido en el laberinto del tiempo.' WHERE `ID`=14377;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='학생들은 양떼와 어느 정도 비슷하지. 잘 지도하고 충분한 관심을 쏟으면 유용하고 만족스러운 존재가 된다네.$B$B하지만, 잠시만 내버려두어도 절벽에서 떨어지거나 얕은 강물에 빠져 죽고 말지.', `MaleText_loc4`='学生们有点像绵羊。当你教导和关心他们时，他们是有用的，甚至可能是讨人喜欢的。$B$B但是只要你离开他们一分钟，他们就会从悬崖上摔下去，或者淹死在河里。', `MaleText_loc5`='學生就像綿羊。當你引導並密切注意他們，他們就會變的很有用甚至很可愛。$B$B你離開他們一下，他們就從懸崖上跌下或溺死在很淺的河裡。', `MaleText_loc7`='Los alumnos son un poco como ovejas. Son útiles y hasta agradables cuando los orientas y les prestas mucha atención.$B$BLos dejas solos un minuto y acaban cayéndose por un precipicio o ahogándose en un río poco profundo.' WHERE `ID`=14378;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 게시판에는 위험한 임무를 완료한 대가로 받는 보상에 대해 다양한 공지 사항이 적혀있습니다. 특별히 눈에 띄는 내용은 없습니다. 나중에 다시 확인하는 것이 좋겠습니다.', `MaleText_loc4`='这个公告牌上张贴着多种公告和执行危险任务的奖励。现在没什么可以吸引你的东西，也许你应该过段时间再回来看看。', `MaleText_loc5`='這個告示牌張貼了不同的通知和懸賞佈告給完成危險調查任務的人。沒什麼特別吸引你的注意;或許你該過陣子再來看。', `MaleText_loc7`='Este letrero contiene varios anuncios y avisos de recompensas por llevar a cabo tareas peligrosas de sondeo. Nada te llama la atención especialmente; quizás deberías volver a mirarlo más adelante.' WHERE `ID`=14379;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 이마를 닦으며 한숨을 쉽니다.', `MaleText_loc4`='%s擦了擦眉毛，叹了口气。', `MaleText_loc5`='擦了擦他的額頭，%s嘆了一口氣。', `MaleText_loc7`='Secándose la frente, %s suspira.', `FemaleText_loc1`='%s|1이;가; 이마를 닦으며 한숨을 쉽니다.', `FemaleText_loc4`='%s擦了擦眉毛，叹了口气。', `FemaleText_loc5`='擦了擦他的額頭，%s嘆了一口氣。', `FemaleText_loc7`='Secándose la frente, %s suspira.' WHERE `ID`=14380;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 툴룬에게 고개를 돌리더니 거만하게 코웃음을 칩니다.', `MaleText_loc4`='%s把头转向图伦，轻蔑地冷笑着。', `MaleText_loc5`='轉身對付塔奴藍，%s輕蔑地冷笑。', `MaleText_loc7`='Girándose para mirar a Tuluun, %s sonríe con desdén.', `FemaleText_loc1`='%s|1이;가; 툴룬에게 고개를 돌리더니 거만하게 코웃음을 칩니다.', `FemaleText_loc4`='%s把头转向图伦，轻蔑地冷笑着。', `FemaleText_loc5`='轉身對付塔奴藍，%s輕蔑地冷笑。', `FemaleText_loc7`='Girándose para mirar a Tuluun, %s sonríe con desdén.' WHERE `ID`=14381;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기에 당신 같은 부류는 필요 없습니다.', `MaleText_loc4`='在这里，我们不需要你的仁慈。', `MaleText_loc5`='我們這裡不需要你的種族。', `MaleText_loc7`='No necesitamos a gente de tu calaña aquí.', `FemaleText_loc1`='여기에 당신 같은 부류는 필요 없어요.', `FemaleText_loc4`='在这里，我们不需要你的仁慈。', `FemaleText_loc5`='我們這裡不需要你的種族。', `FemaleText_loc7`='No necesitamos a gente de tu calaña aquí.' WHERE `ID`=14382;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이단을 퍼트리는 저런 자와 함께 일을 할 수 있을 거라고 생각하십니까?', `MaleText_loc4`='我怎么能在那东西传播他的异端邪说时安心工作？', `MaleText_loc5`='那東西到處傳播它的異教我要怎麼把工作完成?', `MaleText_loc7`='¿Cómo quieren que haga mi trabajo con esa cosa propagando la herejía?', `FemaleText_loc1`='이단을 퍼트리는 저런 자와 함께 일을 할 수 있을 거라고 생각하세요?', `FemaleText_loc4`='我怎么能在那东西传播他的异端邪说时安心工作？', `FemaleText_loc5`='那東西到處傳播它的異教我要怎麼把工作完成?', `FemaleText_loc7`='¿Cómo quieren que haga mi trabajo con esa cosa propagando la herejía?' WHERE `ID`=14383;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 다시 일을 시작하려고 등을 돌리면서 지겹다는 듯이 한숨을 쉽니다.', `MaleText_loc4`='%s厌烦地叹了口气，转身回去工作了。', `MaleText_loc5`='%s厭煩地嘆了一口氣回到他的工作上。', `MaleText_loc7`='El %s suspira con disgusto mientras vuelve a su trabajo.', `FemaleText_loc1`='%s|1이;가; 다시 일을 시작하려고 등을 돌리면서 지겹다는 듯이 한숨을 쉽니다.', `FemaleText_loc4`='%s厌烦地叹了口气，转身回去工作了。', `FemaleText_loc5`='%s厭煩地嘆了一口氣回到他的工作上。', `FemaleText_loc7`='El %s suspira con disgusto mientras vuelve a su trabajo.' WHERE `ID`=14384;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하신가요, 스톰윈드의 시민이여. 내게 하실 말씀이 없으시면 가던 길을 가 주셨으면 합니다만...', `MaleText_loc4`='朋友，向你致意。如果你没什么要帮忙的就径直往前走吧。', `MaleText_loc5`='你好，居民。如果你沒什麼事要問我，那就請你走吧。', `MaleText_loc7`='Saludos, $gciudadano:ciudadana;. Te ruego que sigas tu camino si es que no tienes nada que preguntarme.' WHERE `ID`=14385;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='윈저 치안대장님께서 당신을 기다리고 계셨습니다, $n. 안타깝게도, 그분께서는 가벼운 병을 앓고 계시지만 곧 자리로 복귀하실 겁니다.', `MaleText_loc4`='温德索尔元帅一直都盼着你呢，$n。不幸的是，眼下他身染微恙，不过应该很快就能康复。', `MaleText_loc5`='溫德索爾元帥一直在等你，$n。不幸的是，他現在不太舒服。不過應該很快就會恢復了。', `MaleText_loc7`='El mariscal Windsor te ha estado esperando, $n. Desafortunadamente, ahora mismo está indispuesto. Seguro que pronto podrá atenderte.' WHERE `ID`=14386;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해냈군요! 대단합니다! 윈저 치안대장님께서 당신이 오시기를 고대하셨지요. 지금 그분께 연락을 취해 드릴까요?', `MaleText_loc4`='你做到了！太了不起了！温德索尔元帅一直都盼着你呢。你要我现在就通知他吗？', `MaleText_loc5`='你辦到了!太傑出了!溫德索爾元帥一直在等你。要不要我現在去通知他?', `MaleText_loc7`='¡Lo has conseguido! ¡Excelente! El mariscal Windsor te ha estado esperando. ¿Deseas que lo llame?' WHERE `ID`=14387;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='치안대장 윈저 님께 준비가 됐다고 전해 주십시오.', `MaleText_loc4`='请转告温德索尔元帅我已准备就绪。', `MaleText_loc5`='讓溫德索爾元帥知道我準備好了。', `MaleText_loc7`='Haz saber al mariscal Windsor que ya estoy listo.', `FemaleText_loc1`='치안대장 윈저 님께 준비가 됐다고 전해 주세요.', `FemaleText_loc4`='请转告温德索尔元帅我已准备就绪。', `FemaleText_loc5`='讓溫德索爾元帥知道我準備好了。', `FemaleText_loc7`='Haz saber al mariscal Windsor que ya estoy lista.' WHERE `ID`=14388;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신호를 보냈으니 윈저 님께서 금방 도착하실 겁니다.', `MaleText_loc4`='我已经通知了温德索尔元帅。他应该很快就能赶到这儿。', `MaleText_loc5`='信號已發出。他應該很快就會到了。', `MaleText_loc7`='Ya he enviado la señal. Seguro que llegará pronto.' WHERE `ID`=14389;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오십시오, 영웅이여. 당신의 공적에 대한 이야기가 세대에 걸쳐 전해질 것이라 믿습니다. 아마 언젠가, 당신의 동상이 저 스톰윈드의 영웅들 사이에 세워질 날이 있겠군요.', `MaleText_loc4`='勇士，向你致敬。你所立下的丰功伟绩将代代传颂。或许有一天，你的雕像会矗立在暴风城的英雄谷。', `MaleText_loc5`='嗨，勇士。你的事蹟將會被世代傳誦。或許有一天，你的雕像會矗立在暴風城的英雄之間。', `MaleText_loc7`='Saludos, Campeón. Los relatos de tus hazañas se harán eternos. Quizás algún día se erija una estatua en tu honor entre los héroes de Ventormenta.' WHERE `ID`=14390;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가... 가까이 오지 마십시오! 또다시 제가 병에 걸리면 그때는 얘기할 수가 없습니다.$B$B다시 그런 일이 생기면 큰일이니까 절 그냥 내버려 두십시오.', `MaleText_loc4`='离我远点，$r！很难说我什么时候会再次发病。$B$B离我远点，免得出事！', `MaleText_loc5`='離我遠一點，$r!當病痛再次對我纏身就不要再和我接近了。$B$B在它再發生之前不要再來找我。', `MaleText_loc7`='¡Aléjate de mí, $r! No se sabe cuándo me volverá a tomar la enfermedad.$B$BDéjame solo antes de que vuelva a suceder.' WHERE `ID`=14391;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 말을 잘 들으시오, 인간이여. 당신의 몸 상태에 대해서는 아무 관심도 없소. 다만 내가 필요한 물건을 당신이 지니고 있을 뿐이오. 핏빛철로 주괴가 어디에 있는지 말해주시오.', `MaleText_loc4`='听着，人类。我不关心你们的约定，但是你们有我要的东西。告诉我在哪里可以找到血铸铁锭。', `MaleText_loc5`='聽我說，人類。我不在乎你的困境，但你有我要的東西。告訴我要去哪裡找到血鑄錠。', `MaleText_loc7`='Escúchame, humano. No me importa nada tu difícil situación, pero tienes algo que necesito. Dime dónde encontrar los lingotes forjados con sangre.', `FemaleText_loc1`='내 말을 잘 들으세요, 인간이여. 당신의 몸 상태에 대해서는 아무 관심도 없습니다. 다만 내가 필요한 물건을 당신이 지니고 있을 뿐입니다. 핏빛철로 주괴가 어디에 있는지 말해주세요.', `FemaleText_loc4`='听着，人类。我不关心你们的约定，但是你们有我要的东西。告诉我在哪里可以找到血铸铁锭。', `FemaleText_loc5`='聽我說，人類。我不在乎你的困境，但你有我要的東西。告訴我要去哪裡找到血鑄錠。', `FemaleText_loc7`='Escúchame, humano. No me importa nada tu difícil situación, pero tienes algo que necesito. Dime dónde encontrar los lingotes forjados con sangre.' WHERE `ID`=14392;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='광석에 대한 얘기는 어디서 들었습니까? 남작도 모르는 일인데...$B$B자, 이 저주받은 물건을 가져가십시오. 그 물건 때문에 나쁜 일만 생겼습니다. 그 물건은 안마당 바로 밖에 있는 마구간에 숨겨 놨습니다.$B$B<랜던의 목구멍에서 낮은 노성이 들리기 시작합니다.>', `MaleText_loc4`='你怎么知道这些矿石的？甚至连男爵都不知道……$B$B拿走那被诅咒的东西，它们除了厄运，什么都没有带给我。我把它们藏在院子里的马厩旁边。$B$B<兰登的喉咙里发出了一声低吼。>', `MaleText_loc5`='你怎麼知道礦石的事?就連男爵都不知道...$b$b帶著被詛咒的東西。反正它們也只帶給了我不幸。我把它們藏在庭院後的獸欄裡。$B$B<藍登的喉嚨後發出了一聲低沉的嗥叫。>', `MaleText_loc7`='¿Cómo supiste lo del mineral? Ni siquiera el Barón lo sabía...$B$BLlévate lo que quieras. De todas formas, a mí solo me han traído desgracias. Están escondidos en los establos, cerca del patio.$B$B<De la garganta de Laden empieza a salir un gruñido grave.>' WHERE `ID`=14393;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='', `MaleText_loc4`='', `MaleText_loc5`='', `MaleText_loc7`='' WHERE `ID`=14394;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 분노에 차서 고함을 지릅니다.', `MaleText_loc4`='%s愤怒地吼叫着。', `MaleText_loc5`='%s憤怒的吼叫。', `MaleText_loc7`='%s aúlla de rabia.' WHERE `ID`=14395;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내가 듣고자 하는 얘기를 모두 털어놓게 될 거다, 이 쓰레기 같은 $r!', `FemaleText_loc4`='你会告诉任何我想知道的事情，你这渣滓。', `FemaleText_loc5`='你要告訴我所有我想知道的事，人渣。', `FemaleText_loc7`='Me dirás todo lo que quiero saber, escoria.' WHERE `ID`=14396;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 동족들은 어디에 있지? 어서 말해, 이 악당 녀석!', `FemaleText_loc4`='我们的人都在哪里，混蛋？回答我！', `FemaleText_loc5`='我們的人在哪，壞蛋?我要知道答案!', `FemaleText_loc7`='¿Dónde están nuestros hombres, canalla? ¡Quiero respuestas!' WHERE `ID`=14397;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='배가 고프거나 갈증이 나지 않나? 내가 묻는 말에 대답만 하면 먹을 것과 마실 것을 줄 수도 있다.', `FemaleText_loc4`='你饿吗？渴吗？我可以帮你准备吃的和喝的——你所需要做的就是告诉我一些我想知道的情报。', `FemaleText_loc5`='你不餓嗎?渴嗎?我可以安排食物和飲料 - 你要做的就是告訴我想知道的一切。', `FemaleText_loc7`='¿No tienes hambre? ¿O sed? Puedo proporcionarte comida y bebida; lo único que tienes que hacer es decirme lo que quiero saber.' WHERE `ID`=14398;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='흠... 여기 두 블러드 엘프 녀석들이 계속해서 입을 열지 않으면 내 입에서 거친 말이 나가겠군.', `FemaleText_loc4`='如果这两个家伙不马上开口说话，我就要违背我所说的话了。', `FemaleText_loc5`='如果這兩個人不快點開始說話，我講話就不會太好聽了。', `FemaleText_loc7`='Si estos dos no empiezan a hablar pronto, voy a pasarme a palabras violentas.' WHERE `ID`=14399;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파란 피부의 잡종이 감히 내게 말을 거는 것이냐? 네 녀석에게 알려줄 바에 차라리 죽음을 택하겠다.', `MaleText_loc4`='你胆敢和我说话，蓝皮肤的杂种。我宁可现在就去死，也不会告诉你任何事情的。', `MaleText_loc5`='你竟敢和我說話，藍皮膚的雜種狗?我寧願快點死也不會告訴你任何事情。', `MaleText_loc7`='¿Te atreves a dirigirte a mí, estúpido piel azul? Preferiría morir antes que decirte nada.', `FemaleText_loc1`='파란 피부의 잡종이 감히 내게 말을 거는 것이냐? 네 녀석에게 알려줄 바에 차라리 죽음을 택하겠다.', `FemaleText_loc4`='你胆敢和我说话，蓝皮肤的杂种。我宁可现在就去死，也不会告诉你任何事情的。', `FemaleText_loc5`='你竟敢和我說話，藍皮膚的雜種狗?我寧願快點死也不會告訴你任何事情。', `FemaleText_loc7`='¿Te atreves a dirigirte a mí, estúpido piel azul? Preferiría morir antes que decirte nada.' WHERE `ID`=14400;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 심문관 엘리시아에게 침을 뱉습니다.', `MaleText_loc4`='%s对着审讯者埃莉西亚吐口水。', `MaleText_loc5`='%s對審問者伊萊希雅吐口水。', `MaleText_loc7`='%s escupe a la Interrogadora Elysia.', `FemaleText_loc1`='%s|1이;가; 심문관 엘리시아에게 침을 뱉습니다.', `FemaleText_loc4`='%s对着审讯者埃莉西亚吐口水。', `FemaleText_loc5`='%s對審問者伊萊希雅吐口水。', `FemaleText_loc7`='%s escupe a la Interrogadora Elysia.' WHERE `ID`=14401;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 소리 내어 웃습니다.', `MaleText_loc4`='%s笑了。', `MaleText_loc5`='%s大笑。', `MaleText_loc7`='%s ríe.', `FemaleText_loc1`='%s|1이;가; 소리 내어 웃습니다.', `FemaleText_loc4`='%s笑了。', `FemaleText_loc5`='%s大笑。', `FemaleText_loc7`='%s ríe.' WHERE `ID`=14402;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 너희의 푸른색 피를 즐겨 마신단다, 드레나이 녀석아. 네 녀석에게 상처를 입히고 흘러나오는 그 파란색 피를 감상하는 것만큼 즐거운 일도 없지.', `MaleText_loc4`='我们会很高兴啜饮你那蓝色血液的，德莱尼人。没有什么比看着你们的血涌出来更快乐的事情了。', `MaleText_loc5`='我們快樂地喝著你的藍色血液，德萊尼。沒有什麼比看著你的血從傷口流出還要愉快的了。', `MaleText_loc7`='Bebemos felizmente en tu sangre azul, draenei. Nada nos da más placer que herirte para ver fluir la sangre.', `FemaleText_loc1`='우리는 너희의 푸른색 피를 즐겨 마신단다, 드레나이 녀석아. 네 녀석에게 상처를 입히고 흘러나오는 그 파란색 피를 감상하는 것만큼 즐거운 일도 없지.', `FemaleText_loc4`='我们会很高兴啜饮你那蓝色血液的，德莱尼人。没有什么比看着你们的血涌出来更快乐的事情了。', `FemaleText_loc5`='我們快樂地喝著你的藍色血液，德萊尼。沒有什麼比看著你的血從傷口流出還要愉快的了。', `FemaleText_loc7`='Bebemos felizmente en tu sangre azul, draenei. Nada nos da más placer que herirte para ver fluir la sangre.' WHERE `ID`=14403;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 일을 시작해라!', `MaleText_loc4`='给我回去工作！', `MaleText_loc5`='快回去工作吧你!', `MaleText_loc7`='¡Tú, vuelve al trabajo!' WHERE `ID`=14404;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일어나라! 이제 일하러 가란 말이다!', `MaleText_loc4`='醒醒！给我起来！回去工作！', `MaleText_loc5`='醒來!快起來回去工作!', `MaleText_loc7`='¡Despierta! ¡Ahora levanta y vuelve al trabajo!' WHERE `ID`=14405;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 오만하고 멍청한 놈! 감히 젤레마르의 피를 훔치려고 했나? 그 대가를 치르게 해주마!', `MaleText_loc4`='蠢货！你想窃取塞雷玛尔之血吗？你会为此付出代价的！', `MaleText_loc5`='無恥的蠢貨!你想偷賽勒瑪爾的鮮血?你先好好祈禱吧!', `MaleText_loc7`='¡Estúpido insolente! ¿Pensaste en robar la sangre de Zelemar? ¡Pagarás con la tuya!' WHERE `ID`=14406;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시체를 조사한 당신은 실패로 끝난 데솔름 공격 작전을 지휘했던 혈기사 돈스타가 틀림없다는 결론을 내립니다.', `MaleText_loc4`='检查了尸体之后，你断定这就是伊斯塔·晨星，进攻戴索姆却惨遭失败的血骑士。', `MaleText_loc5`='檢查屍體你推論這一定是血騎士晨星，死亡之域失敗突擊的領導者。', `MaleText_loc7`='Examinando el cadáver, concluyes que este tiene que ser el Caballero de sangre Estrella del Alba, el líder del asalto frustrado a la Ciudad de la Muerte.' WHERE `ID`=14407;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시체를 뒤져 휘장을 찾습니다.', `MaleText_loc4`='在尸体上寻找一枚徽章。', `MaleText_loc5`='搜索屍體尋找徽記。', `MaleText_loc7`='Busca una insignia en el cadáver.', `FemaleText_loc1`='시체를 뒤져 휘장을 찾습니다.', `FemaleText_loc4`='在尸体上寻找一枚徽章。', `FemaleText_loc5`='搜索屍體尋找徽記。', `FemaleText_loc7`='Busca una insignia en el cadáver.' WHERE `ID`=14408;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='길드를 창설하도록 도와드리겠습니다.', `MaleText_loc4`='我可以帮助你建立公会。', `MaleText_loc5`='我可以幫你建立一個公會。', `MaleText_loc7`='Te puedo ayudar a fundar una hermandad.' WHERE `ID`=14409;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시체의 옷과 장비를 뒤져서 전투와 오염된 환경에 손상되지 않은 휘장을 찾아냅니다.', `MaleText_loc4`='翻遍血骑士的尸体之后，你找到了那枚徽章。它并没有因为战争和周围的环境而受到任何损伤。', `MaleText_loc5`='尋找屍體的衣服和裝備讓你發現了需要的徽記，未受戰役和惡劣環境的損壞。', `MaleText_loc7`='Un registro en la ropa y el equipamiento del cadáver muestra la insignia que necesitas, en perfecto estado tras la batalla y el entorno infecto.' WHERE `ID`=14410;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='엘룬의 축복이 있기를. 뭘 도와드릴까요?', `FemaleText_loc4`='艾露恩祝福着你，有什么我能为你效劳的吗？', `FemaleText_loc5`='伊露恩的仁慈降臨到你身上。我能幫你什麼?', `FemaleText_loc7`='Que Elune te bendiga. ¿En qué puedo servirte?' WHERE `ID`=14411;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서둘러라! 시간을 지체할수록 너에게 가해지는 고통만 커진다는 것을 모르나!', `MaleText_loc4`='快一点！你拖得越久，我给你的痛苦就会越多！', `MaleText_loc5`='快點!你動作越慢，我就會讓你越痛!', `MaleText_loc7`='¡Date prisa de una vez! ¡Cuanto más tardes, más te vas a arrepentir!' WHERE `ID`=14412;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐야?! 가정교육도 못 받았나?', `MaleText_loc4`='这是啥？！你爸妈没有教你学点什么东西吗？', `MaleText_loc5`='這是什麼?!你爸媽都沒教你一點東西嗎?!', `MaleText_loc7`='¡¿Qué es esto?! ¡¿No te enseñaron nada papá y mamá?!' WHERE `ID`=14413;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 끔찍하다... 너희처럼 게으른 일꾼을 매질하느라 내 팔이 떨어질 지경이야!', `MaleText_loc4`='这太糟糕了……抽这些懒骨头把我的胳膊都抽酸了！', `MaleText_loc5`='這真是糟糕...我打你們這些懶惰的苦工打的手都痠了!', `MaleText_loc7`='Esto es terrible... ¡Se me cansan los brazos de tanto daros palizas, patanes perezosos!' WHERE `ID`=14414;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 멀었다! 이렇게 빨리 지치다니!', `MaleText_loc4`='不要松懈！不要松懈！', `MaleText_loc5`='太快了!你太快就懈怠了!', `MaleText_loc7`='¡Demasiado pronto! ¡Aflojas demasiado pronto!' WHERE `ID`=14415;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠습니다, 감독님! 분부대로 따르겠습니다.', `MaleText_loc4`='遵命，主人，听从您的任何吩咐。', `MaleText_loc5`='是的主人，任你差遣。', `MaleText_loc7`='Sí, maestro, cualquier cosa que digas.' WHERE `ID`=14416;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$c|1이여;여;, 어서 오십시오. 우리를 찾아오기로 하신 건 정말 잘하신 겁니다.', `FemaleText_loc4`='谢谢你，$c。你能来拜访我们实在是太好了。', `FemaleText_loc5`='你好，$c。你決定來拜訪我們是對的。', `FemaleText_loc7`='Saludos, $c. Me alegro de que te hayas decidido a visitarnos.' WHERE `ID`=14417;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 우리 셋 중 나를 위해 명예롭게 봉사했소, $n. 이제 내 교육은 여기까지오. 그동안 수고가 많았소이다. 쿠로스가 준비를 마치면 당신을 부를 것이니 기다리시오.', `MaleText_loc4`='你对三人执政团的效劳是一种荣耀，$n。多保重。当库卢斯准备好了的时候，他会召唤你的。', `MaleText_loc5`='你以榮譽為三人之一效命，$n。我們的時間已到盡頭。庫羅斯準備好後會告訴你。', `MaleText_loc7`='Has servido a uno de los tres con honor, $n. Nuestro tiempo se acaba. Kuros te llamará cuando esté preparado.' WHERE `ID`=14418;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 의약품 상자를 발견했습니다.', `MaleText_loc4`='一个%s看到了医用补给品。', `MaleText_loc5`='一個%s發現了醫療補給。', `MaleText_loc7`='%s ve suministros médicos.', `FemaleText_loc1`='%s|1이;가; 의약품 상자를 발견했습니다.', `FemaleText_loc4`='一个%s看到了医用补给品。', `FemaleText_loc5`='一個%s發現了醫療補給。', `FemaleText_loc7`='%s ve suministros médicos.' WHERE `ID`=14419;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 의약품 상자를 집어듭니다.', `MaleText_loc4`='%s拾起了医用补给品。', `MaleText_loc5`='%s撿起醫療補給。', `MaleText_loc7`='%s recoge material médico.', `FemaleText_loc1`='%s|1이;가; 의약품 상자를 집어듭니다.', `FemaleText_loc4`='%s拾起了医用补给品。', `FemaleText_loc5`='%s撿起醫療補給。', `FemaleText_loc7`='%s recoge material médico.' WHERE `ID`=14420;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 졌습니다. <PH>', `MaleText_loc4`='Sorry, you lose! <PH>', `MaleText_loc5`='抱歉，你輸了!<PH>', `MaleText_loc7`='¡Lo siento, has perdido! <PH>', `FemaleText_loc1`='당신은 졌습니다. <PH>', `FemaleText_loc4`='Sorry, you lose! <PH>', `FemaleText_loc5`='抱歉，你輸了!<PH>', `FemaleText_loc7`='¡Lo siento, has perdido! <PH>' WHERE `ID`=14421;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='만나서 반갑네, $c|1이여;여;. 나는 대리인의 삼두연합행정부의 두 번째인 쿠로스라고 하네.', `MaleText_loc4`='你好，$c。我是库卢斯，阿古斯之手三人执政团的成员。', `MaleText_loc5`='你好，$c。我是庫羅斯，三頭政治的第二人。', `MaleText_loc7`='Saludos, $c. Soy Kuros, segundo del Triunvirato de la Mano.' WHERE `ID`=14422;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 그들이 그를 무자비하게 때리는 광경을 목격했다. 그들의 무자비한 부대장은 마치 그 잔인함이 정상인 것 마냥 행동했다. 야만적인 폭력을 통해 나는 나 자신이 망가지고 있는 걸 느낄 수 있었다.$B$B구원자 사루안이 그들의 주먹에 얻어맞는 것을 보았을 때 나는 울기 시작했다. 공포 때문이 아니었다... 나는 너무나 슬퍼서 울었다. 삼두연합행정부의 한 드레나이가 그런 식으로 대접을 받다니 슬프지 않을 수 없었다. 나를 속박하고 있는 이 족쇄를 풀 수만 있다면... 그럴 수만 있다면...', `MaleText_loc4`='我眼睁睁地看着他们无情地鞭打着他，这对于那位残忍的军官来说似乎早已是稀松平常的事情。残酷的鞭笞让我几乎崩溃。$B$B当我看到守备官撒鲁安被他们鞭笞时，我开始哭泣。不是因为恐惧……而是因为看到一位执政官被如此折磨而感到悲伤。要是我能逃出去，要是……', `MaleText_loc5`='我看著他們無情的鞭打他。他們殘酷的副官一舉一動就好像殘暴是正常的事一樣。經過野蠻的鞭打之後，我可以感覺我已經崩潰了。$B$B看著復仇者薩魯安忍受他們的毆打，我開始哭泣。並不是因為害怕...而是因為悲傷。看到三頭政治的德萊尼被這樣對待。要是我能打破我的束縛就好了。要是可以的話...', `MaleText_loc7`='Observé mientras lo golpeaban sin compasión. Su despiadado teniente actuaba como si tal crueldad fuera un acto de normalidad. A través de la salvaje paliza, me sentía como si yo mismo me quebrara.$B$BMientras observaba cómo el vindicador Saruan recibía sus golpes, comencé a sollozar. No por miedo... Lloré de tristeza. Ver a un draenei del Triunvirato tratado de tal forma. Si yo pudiera haberme liberado de mis ataduras. Si yo pudiera...' WHERE `ID`=14428;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<다음 장으로 넘깁니다.>', `MaleText_loc4`='<翻到下一页。>', `MaleText_loc5`='<翻開下一頁。>', `MaleText_loc7`='<Pasa a la página siguiente.>', `FemaleText_loc1`='< 다음 장으로 넘깁니다.>', `FemaleText_loc4`='<翻到下一页。>', `FemaleText_loc5`='<翻開下一頁。>', `FemaleText_loc7`='<Pasa a la página siguiente.>' WHERE `ID`=14429;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영원처럼 느껴진 시간이 지났을 때 그 구원자는 의식을 잃었다. 아무리 그라 해도 견디기 어려운 고문이었다. 다른 이들이 마티스라고 부르던 잔인한 자가 병균이 득실거리는 물을 너덜너덜해진 사루안의 몸에 뿌려 깨우려고 했지만 사루안은 깨어나지 않았다.', `MaleText_loc4`='过了很长一段时间，守备官失去了知觉。他已遭受太多的严刑拷打。那个残忍的家伙——他的名字似乎是叫玛提斯——竟然往守备官那早已伤痕累累的身体上泼洒腐水。但撒鲁安并没有清醒过来。', `MaleText_loc5`='在看起來像實體的東西出現後，復仇者就失去意識了。這實在太折磨了，即使是對他而言也一樣。殘忍的 - 馬帝斯，據悉他是被這樣稱呼的 - 還將傳染的水潑灑在薩魯安毀壞的身上想叫醒他。但薩魯安並沒有醒來。', `MaleText_loc7`='Tras lo que pareció ser una eternidad, el vindicador perdió la conciencia. La tortura era demasiado, incluso para él. El cruel – Matis, como descubrí que le llamaban – intentó despertar a Saruan salpicando su devastado cuerpo con agua con contagio. Pero Saruan no despertó.' WHERE `ID`=14430;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 비명을 지르고 싶었지만 단지 헐떡거리는 낮은 소리만이 내 입술 밖으로 새어 나왔을 뿐이다. 나의 이런 반항적인 행동은 즉시 폭력으로 다스려졌다. 바닥에 쓰러져 있을 때 나는 사루안의 시체 앞을 걸어다니는 마티스의 모습을 볼 수 있었다. 그는 분명 걱정이 있어 보였다. 그는 만약 사루안이 구타 때문에 죽은 것이면 시로나스인지 시로나인지 하는 자가 자기를 뼈만 남도록 벌을 줄 거라고 했다.', `MaleText_loc4`='我想大声尖叫，却只能发出微微的声音。因为刚才的反抗行动，我很快就被打倒在地。当我躺在地上时，看到玛提斯在撒鲁安的尸体旁来回走动，显得非常焦虑。他曾说过如果撒鲁安死于他的折磨，那个希隆娜丝会活活要了他的命。', `MaleText_loc5`='我想尖叫可是只有一聲低喘迸出我嘴邊。我很快就被這次的反叛行動給打敗。當我躺在地上，我可以看見馬帝斯在薩魯安的屍體前跺步。他看起來很擔心。他聲稱如果薩魯安被打死的話，賽羅娜斯、賽羅娜或類似這樣的實體會把他的肉體從骨頭上剝下。', `MaleText_loc7`='Quería gritar, pero solo escapó de mis labios un grito ahogado. Me golpearon de inmediatamente por tal acto de rebeldía. Mientras yacía en el suelo, pude ver a Matis paseándose delante del cuerpo de Saruan. Parecía visiblemente preocupado. Afirmó que a Sironas, Sirona o alguna entidad tal haría que se le arrancara la carne de los huesos si Saruan había perecido debido a la paliza.' WHERE `ID`=14431;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 시로나스라고 하는 자는 사루안에 대한 계획을 세웠다... $B$B<여기에서 갑자기 중단된 기록은 일지를 가로지른 한 획으로 끝납니다. 이 드레나이는 기록을 하던 중 사망했습니다.>', `MaleText_loc4`='希隆娜丝计划把撒鲁安……$B$B<由于作者死去，故事突然中断了。接下去的记录是一片空白。>', `MaleText_loc5`='賽羅娜斯實體對薩魯安有個計畫...$b$b<書寫突然中斷，一條長長的線畫過頁面。這個德萊尼在製造實體時死去。>', `MaleText_loc7`='Que la entidad Sironas tenía planes para Saruan... $B$B< La escritura se detiene repentinamente y una larga línea se desplaza hasta salirse de la página. Aquel draenei murió mientras escribía.>' WHERE `ID`=14432;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잊지 마세요, $n! 새벽길을 벗어나지 않고도 내곽 엘프 관문에 닿을 수 있습니다!', `FemaleText_loc4`='记住，$n！沿着黎明之路就可以走到精灵之门！', `FemaleText_loc5`='記住，$n!沿著黎明小路走你就會到達內精靈之門!', `FemaleText_loc7`='Recuerda, $n. No salgas de la calle del Alba y llegarás a la Puerta Elfa Interior.' WHERE `ID`=14433;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여관 주인이 있는 쪽을 향해 꽥꽥 울더니 선스트라이더 섬으로 돌아갑니다.', `MaleText_loc4`='朝着旅店老板的方向大叫，然后向着逐日岛的方向回去了。', `MaleText_loc5`='朝旅店老闆的方向粗聲大叫，聲音直傳到逐日者之島。', `MaleText_loc7`='Sale en dirección del tabernero y pasa de vuelta por la Isla de Caminante del Sol.' WHERE `ID`=14434;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 안녕하십니까? 대장기술을 배우고 싶다면 제대로 찾아오셨습니다.', `MaleText_loc4`='你好，$c。如果你想学习铁匠技术的话，我想你来对了地方。', `MaleText_loc5`='你好，$c。如果你想學習鐵匠的藝術，那麼你來對地方了。', `MaleText_loc7`='Buenos días, $c. Si deseas aprender el arte del herrero, has venido al lugar idóneo.' WHERE `ID`=14435;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대장장이 훈련을 받고 싶습니다.', `MaleText_loc4`='我想学习锻造技术。', `MaleText_loc5`='我想接受訓練成為一個鐵匠。', `MaleText_loc7`='Necesito instrucción de herrero.', `FemaleText_loc1`='대장장이 훈련을 받고 싶어요.', `FemaleText_loc4`='我想学习锻造技术。', `FemaleText_loc5`='我想接受訓練成為一個鐵匠。', `FemaleText_loc7`='Necesito instrucción de herrero.' WHERE `ID`=14436;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 우리 짝지는 그대를 해치지는 않을 테니 신경 쓰지 않으셔도 됩니다. 저 녀석은 그냥 여기저기 긁는 것을 좋아할 뿐이랍니다.$B$B우리 짝지는 단지 덩치 크고 사랑스러운 고양이일 뿐이죠.$B$B그렇지 않니, 짝지야? 물론이고말고. 너는 내 귀여운 고양이잖니. 너는 이 엄마의 사랑스러운 아기란다!', `FemaleText_loc4`='哦，不用担心巴迪。他不会伤害你的，他不过是喜欢这样抓来抓去而已。$B$B他只是一只又大又可爱的猫而已。$B$B不是吗，巴迪？可爱的小东西，我的小宝贝！', `FemaleText_loc5`='喔，別管巴弟。他不會傷害你的，他只是有時候喜歡抓來抓去。$B$B他只是隻可愛的大貓咪。$B$B對不對呀巴弟?對，沒錯，你最可愛了，小傢伙。你是媽咪的小寶貝，你就是這樣!', `FemaleText_loc7`='Oh, no hagas caso de Buddy. No te hará daño, solo le gusta arañar de vez en cuando.$B$BEs solo un gatito grande y adorable.$B$B¿No es así, Buddy? Sí, bonito, cosita. ¡El pequeñín de tu mami, eso es lo que eres!' WHERE `ID`=14437;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 모루 위에다 재료를 배열합니다.', `MaleText_loc4`='%s将材料放在铁砧上。', `MaleText_loc5`='%s將材料安置在鐵砧上。', `MaleText_loc7`='%s dispone los materiales sobre el yunque.' WHERE `ID`=14438;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='베마린이 무슨 일을 하고 있는지 알고 분노하여 얼굴이 온통 일그러진 %s|1이;가; 뒤를 돌아서 떠납니다.', `MaleText_loc4`='当他知道波玛尔正在干什么的时候，%s的脸开始扭曲。他转身走开了。', `MaleText_loc5`='當%s知道貝瑪倫在做些什麼時他的臉嫌惡地扭曲。他轉過身走開。', `MaleText_loc7`='La cara de %s se retuerce de repulsión cuando se da cuenta de lo que Bemarrin está haciendo. Se gira y se marcha.' WHERE `ID`=14439;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저런 자들에게는 신경 쓸 필요 없습니다. $n, 그대가 속한 혈기사단의 희생도 저들에겐 아무런 의미가 없습니다. 그대들이 자신들을 지키기 위해 어떤 대가를 치러야 하는지 저들은 결코 이해하지 못할 것입니다.', `MaleText_loc4`='不用在意他们，$n。你所属的组织所做出的牺牲对他们来说不值一提，他们永远也不会懂得你为了保卫他们付出了什么样的代价。', `MaleText_loc5`='不要管他們那種人，$n。你的軍隊做出的犧牲浪費在他們身上。他們永遠不會了解你在對抗他們防禦時所使用的力量花了你多少心血。', `MaleText_loc7`='No prestes atención a su calaña, $n. Los sacrificios realizados por tu orden están perdidos en ellos. Nunca comprenderán el precio que pagáis por el poder que ejercéis en su defensa.' WHERE `ID`=14440;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 여기 있습니다. 다 됐습니다.', `MaleText_loc4`='好了，$n。已经完成了。', `MaleText_loc5`='好了，$n。完成了。', `MaleText_loc7`='Toma, $n. Está hecho.' WHERE `ID`=14441;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 세나리온 드루이드는 자연의 균형을 지키는 수호자들이오. 핵심은 균형을 유지하는 것이지. 우리 드루이드는 어떤 일을 부탁받아도 결정적인 행동을 취할 때까지 오래 지체하지 않소. 다른 이들의 말은 듣지 마시오. 특히 우리 중에 여기저기 기웃거리기만 하는 자들의 말은 절대로!', `MaleText_loc4`='我们塞纳里奥的德鲁伊们是大自然平衡的保护者，我们的职责就是保持平衡。当我们被召唤的时候，就不应该在采取决定性的行动前等待太久。不要听信别人的理论，尤其是我们当中的那些只负责观察的人！', `MaleText_loc5`='我們塞納里奧的德魯伊是自然平衡的保衛者。重點是平衡。當我們被徵召時一定要儘速採取果斷的行動。不要讓任何人左右你，尤其是我們之中那些只想靜觀其變的人。', `MaleText_loc7`='Nosotros, los druidas de Cenarius, protegemos el equilibrio de la naturaleza. Lo más importante es el equilibrio. En momentos de necesidad, no deberíamos tardar mucho en tomar acciones decisivas. Que nadie te haga creer lo contrario, ¡sobre todo aquellos de entre nosotros que solo quieren observar!' WHERE `ID`=14442;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물러서십시오, $n! 불꽃이 엄청나게 튈 겁니다.', `MaleText_loc4`='站后面点，$n。会有很多火花溅射出来的。', `MaleText_loc5`='退後，$n。馬上就有很多火花要產生了。', `MaleText_loc7`='Retrocede, $n. Van a saltar muchas chispas.' WHERE `ID`=14443;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 의식을 잃습니다.', `MaleText_loc4`='%s失去了知觉。', `MaleText_loc5`='%s變的不省人事。', `MaleText_loc7`='%s cae inconsciente.' WHERE `ID`=14444;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쿠로스 님께 돌아가십시오. 나는 마티스를 핏빛 감시초소로 데려가겠습니다.', `MaleText_loc4`='回库卢斯那里去吧。我会把他带到秘血岗哨的。', `MaleText_loc5`='回到庫羅斯那裡。我會把他帶回血色守望。', `MaleText_loc7`='Vuelve con Kuros. Lo llevaré a la Avanzada de Sangre.', `FemaleText_loc1`='쿠로스 님께 돌아가십시오. 나는 마티스를 핏빛 감시초소로 데려가겠습니다.', `FemaleText_loc4`='回库卢斯那里去吧。我会把他带到秘血岗哨的。', `FemaleText_loc5`='回到庫羅斯那裡。我會把他帶回血色守望。', `FemaleText_loc7`='Vuelve con Kuros. Lo llevaré a la Avanzada de Sangre.' WHERE `ID`=14445;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 잡았구나, $n!', `MaleText_loc4`='抓住你了，$n！', `MaleText_loc5`='我們抓到你了，$n!', `MaleText_loc7`='¡Ahora te tenemos, $n!', `FemaleText_loc1`='드디어 잡았구나, $n!', `FemaleText_loc4`='抓住你了，$n！', `FemaleText_loc5`='我們抓到你了，$n!', `FemaleText_loc7`='¡Ahora te tenemos, $n!' WHERE `ID`=14446;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 죽이기 전에는 데려갈 수 없을 것이다!', `MaleText_loc4`='别想活捉我！', `MaleText_loc5`='你永遠也不會活捉我!', `MaleText_loc7`='¡Nunca me cogeréis vivo!' WHERE `ID`=14447;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽을 때까지 싸우리라!', `MaleText_loc4`='战斗到最后一刻！', `MaleText_loc5`='敬死亡!', `MaleText_loc7`='¡A la muerte!' WHERE `ID`=14448;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 찾은 걸 후회하게 해 주마, 어리석은 놈.', `MaleText_loc4`='你会后悔的，可怜虫。', `MaleText_loc5`='你會後悔的，蛆蟲。', `MaleText_loc7`='Te arrepentirás de esto, gusano.' WHERE `ID`=14449;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, $n. 퀘스트 완료 9711 -- 학살자 마티스 -- 아래 있는 옵션 단추를 클릭하십시오.$B$B제가 마법을 시전하려고 해도 아무 일도 일어나지 않는다는 것을 알아 두십시오.', `MaleText_loc4`='Hi, $n. Click the option below to complete quest 9711 -- Matis the Cruel.$B$BNote that nothing happens even though I am attempting to cast a spell.', `MaleText_loc5`='嗨，$n。點擊下列的選項來完成任務9711 - 殘忍的馬帝斯。$B$B請注意雖然我正嘗試施展一個法術但並沒有任何事發生。', `MaleText_loc7`='Hola, $n. Haz clic en la opción de debajo para completar la misión 9711 -- Matis el Cruel.$B$BFíjate en que no sucede nada aunque intente lanzar un hechizo.' WHERE `ID`=14450;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 저를 완성시켜야 합니다.', `MaleText_loc4`='You complete me.', `MaleText_loc5`='你讓我變的完整。', `MaleText_loc7`='Me completas.', `FemaleText_loc1`='당신이 저를 완성시켜야 합니다.', `FemaleText_loc4`='You complete me.', `FemaleText_loc5`='你讓我變的完整。', `FemaleText_loc7`='Me completas.' WHERE `ID`=14451;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정확하게 일치하는 내재된 대상을 사용하지만 효과는 다른 죽음의 손길과 같은 마법을 저에게 시전해 주십시오.', `MaleText_loc4`='Cast another spell on me that uses the exact same implicit target but has a different effect -- like death touch.', `MaleText_loc5`='對我施展另一個法術，對同樣的目標作用但為不同的效果 - 就像死亡之觸。', `MaleText_loc7`='Lánzame otro hechizo que utilice exactamente el mismo objetivo implícito, pero tenga un efecto diferente – como el toque de la muerte.', `FemaleText_loc1`='저에게 정확하게 일치하는 내재된 대상을 사용하지만 효과는 다른 죽음의 손길과 같은 마법을 저에게 시전해 주세요.', `FemaleText_loc4`='Cast another spell on me that uses the exact same implicit target but has a different effect -- like death touch.', `FemaleText_loc5`='對我施展另一個法術，對同樣的目標作用但為不同的效果 - 就像死亡之觸。', `FemaleText_loc7`='Lánzame otro hechizo que utilice exactamente el mismo objetivo implícito, pero tenga un efecto diferente – como el toque de la muerte.' WHERE `ID`=14452;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부름을 받고 대령했습니다. 분부만 내리십시오.', `MaleText_loc4`='听候您的吩咐，大人。', `MaleText_loc5`='任您差遣，我的主人。', `MaleText_loc7`='Estoy a tu servicio, mi señor.', `FemaleText_loc1`='부름을 받고 대령했습니다. 분부만 내리십시오.', `FemaleText_loc4`='听候您的吩咐，大人。', `FemaleText_loc5`='任您差遣，我的主人。', `FemaleText_loc7`='Estoy a tu servicio, mi señor.' WHERE `ID`=14453;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='추적자들은 모두 나가서 범죄자인 학살자 마티스를 찾도록 한다. 내가 아르거스의 손의 믿을 만한 요원에게 신호용 권총을 주었다. 추적자 중 누구라도 그 신호를 보면 그 요원이 마티스를 찾았으며 지원이 필요하다는 뜻으로 알도록 하라. 그리고 추적자들은 마티스를 산 채로 데려와야 한다는 것을 잊지 말도록.', `MaleText_loc4`='我希望你们全部去搜查那个罪犯，残忍的玛提斯。我将一把信号枪交给了一位可靠的阿古斯之手特派员。当你们看到闪光信号的时候，就意味着玛提斯被发现了。记住，必须把玛提斯给我活着带回来。', `MaleText_loc5`='我要你們所有的追蹤者都出去搜索犯人，殘忍的馬帝斯。我已給我信賴的阿古斯之手密探信號槍了。當你或你的追蹤者之一看到信號，就表示一個密探已經找到馬帝斯和需要的協助了。記住，追蹤者，要把馬帝斯活捉回來。', `MaleText_loc7`='Quiero a todos los rastreadores fuera buscando a ese criminal, Matis el Cruel. He entregado pistolas de señales a agentes de confianza de la Mano. Si alguno ve la señal, significará que han encontrado a Matis y que necesitan ayuda. Y recuerda, rastreador, necesito a Matis vivo.' WHERE `ID`=14454;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분부대로 하겠습니다.', `MaleText_loc4`='遵命，大人。', `MaleText_loc5`='我的王，事情將會完成。', `MaleText_loc7`='Se hará, mi señor.', `FemaleText_loc1`='분부대로 하겠습니다.', `FemaleText_loc4`='遵命，大人。', `FemaleText_loc5`='我的王，事情將會完成。', `FemaleText_loc7`='Se hará, mi señor.' WHERE `ID`=14455;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 형제들을 부릅니다.', `MaleText_loc4`='%s呼唤他们的同伴。', `MaleText_loc5`='%s召喚他們的同胞。', `MaleText_loc7`='%s llama a sus hermanos.', `FemaleText_loc1`='%s|1이;가; 형제들을 부릅니다.', `FemaleText_loc4`='%s呼唤他们的同伴。', `FemaleText_loc5`='%s召喚他們的同胞。', `FemaleText_loc7`='%s llama a sus hermanos.' WHERE `ID`=14456;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형제자매들이여! 오늘 밤 우리는 사냥을 한다! 오늘은 마티스라고 하는 블러드 엘프를 심판하는 날이다! 가장 먼저 그를 발견하는 자는 일주일간 엑소다르를 타고 휴가를 즐기게 될 것이다!', `MaleText_loc4`='兄弟姐妹们，今晚我们要搜索一个名叫玛提斯的血精灵，把他带来接受审判！第一个找到他的人可以得到在埃索达的一星期休假！', `MaleText_loc5`='兄弟姐妹們今晚我們要展開獵捕行動!一定要讓那個叫馬帝斯的血精靈知道什麼是正義!第一個找到他的人就能獲得本週的艾克索達渡假權!', `MaleText_loc7`='¡Hermanos y hermanas, esta noche salimos de caza! ¡Hay que ajusticiar a un elfo de sangre llamado Matis! ¡El primero que lo encuentre disfrutará de una semana de vacaciones a bordo de El Exodar!', `FemaleText_loc1`='형제자매들이여! 오늘 밤 우리는 사냥을 한다! 오늘은 마티스라고 하는 블러드 엘프를 심판하는 날이다! 가장 먼저 그를 발견하는 자는 일주일간 엑소다르를 타고 휴가를 즐기게 될 것이다!', `FemaleText_loc4`='兄弟姐妹们，今晚我们要搜索一个名叫玛提斯的血精灵，把他带来接受审判！第一个找到他的人可以得到在埃索达的一星期休假！', `FemaleText_loc5`='兄弟姐妹們今晚我們要展開獵捕行動!一定要讓那個叫馬帝斯的血精靈知道什麼是正義!第一個找到他的人就能獲得本週的艾克索達渡假權!', `FemaleText_loc7`='¡Hermanos y hermanas, esta noche salimos de caza! ¡Hay que ajusticiar a un elfo de sangre llamado Matis! ¡El primero que lo encuentre disfrutará de una semana de vacaciones a bordo de El Exodar!' WHERE `ID`=14457;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앞으로! 핏빛안개 섬의 야생이 기다리고 있다!', `MaleText_loc4`='出发！秘血岛的冒险之旅在等待着我们！', `MaleText_loc5`='在前面!血謎荒地在等著我們!', `MaleText_loc7`='¡Adelante! ¡Las tierras salvajes de Bruma de Sangre aguardan!', `FemaleText_loc1`='앞으로! 핏빛안개 섬의 야생이 기다리고 있다!', `FemaleText_loc4`='出发！秘血岛的冒险之旅在等待着我们！', `FemaleText_loc5`='在前面!血謎荒地在等著我們!', `FemaleText_loc7`='¡Adelante! ¡Las tierras salvajes de Bruma de Sangre aguardan!' WHERE `ID`=14458;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시험을 시작하겠다! 블러드래스여, 공격하라!', `MaleText_loc4`='开始试炼吧！布拉维·血怒，给我上！', `MaleText_loc5`='試煉開始!血怒，攻擊!', `MaleText_loc7`='¡Que comience la prueba! ¡Furiasangre, ataca!' WHERE `ID`=14459;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용사 라이트렌드여, 나를 자랑스럽게 해다오!', `MaleText_loc4`='勇士莱伦德·光痕，让我为你而骄傲吧！', `MaleText_loc5`='勇士萊特蘭德，別讓我失望!', `MaleText_loc7`='¡Campeón Rasgaluz, haz que me sienta orgulloso!' WHERE `ID`=14460;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스랄이 달아났다! 멀리 가지 못하게 막아라!', `MaleText_loc4`='萨尔逃跑了！不要让他跑掉！', `MaleText_loc5`='索爾逃跑了!別讓他逃掉!', `MaleText_loc7`='¡Thrall ha huido! ¡No le dejéis escapar!', `FemaleText_loc1`='스랄이 달아났다! 멀리 가지 못하게 막아라!', `FemaleText_loc4`='萨尔逃跑了！不要让他跑掉！', `FemaleText_loc5`='索爾逃跑了!別讓他逃掉!', `FemaleText_loc7`='¡Thrall ha huido! ¡No le dejéis escapar!' WHERE `ID`=14461;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스위프트블레이드, 벼락출세를 노리는 이 친구에게 진짜 혈기사가 싸우는 모습을 보여줘!', `MaleText_loc4`='玛尔娅·迅刃，让这个家伙看看真正的血骑士是怎么战斗的！', `MaleText_loc5`='讓這個傲慢自負的人知道真正的血騎士是怎麼戰鬥的，迅刃!', `MaleText_loc7`='¡Enséñale a $geste presuntuoso:esta presuntuosa; cómo lucha un Caballero de sangre de verdad, Hojágil!' WHERE `ID`=14462;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n에게 고통의 의미를 알려줘라, 선스트라이커!', `MaleText_loc4`='斯塔克·射日者，给$n点痛苦尝尝！', `MaleText_loc5`='讓$n知道什麼是痛苦，擊日者!', `MaleText_loc7`='¡Enseña a $n lo que significa el dolor, Golpesol!' WHERE `ID`=14463;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘했네, $n! 두 번째 시험을 통과했어!', `MaleText_loc4`='干得好，$n！你通过了第二个试炼！', `MaleText_loc5`='做的好，$n!你通過了第二個試煉!', `MaleText_loc7`='¡Bien hecho, $n! Has superado la segunda prueba!' WHERE `ID`=14464;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈이 저기 있다. 놈을 막아라!', `MaleText_loc4`='他就在那里，拦住他！', `MaleText_loc5`='他在那裡，抓住他!', `MaleText_loc7`='¡Ahí está, detenedlo!', `FemaleText_loc1`='놈이 저기 있다. 놈을 막아라!', `FemaleText_loc4`='他就在那里，拦住他！', `FemaleText_loc5`='他在那裡，抓住他!', `FemaleText_loc7`='¡Ahí está, detenedlo!' WHERE `ID`=14465;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈이 달아나지 못하게 막아라!', `MaleText_loc4`='不要让他跑了！', `MaleText_loc5`='別讓他跑了!', `MaleText_loc7`='¡No le dejéis escapar!', `FemaleText_loc1`='놈이 달아나지 못하게 막아라!', `FemaleText_loc4`='不要让他跑了！', `FemaleText_loc5`='別讓他跑了!', `FemaleText_loc7`='¡No le dejéis escapar!' WHERE `ID`=14466;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대는 누구지? 나를 귀찮게 하지 마시오.', `MaleText_loc4`='你是谁？离我远点。', `MaleText_loc5`='你是誰?不要來煩我。', `MaleText_loc7`='¿Quién eres? Déjame en paz.' WHERE `ID`=14467;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳을 나갈 준비가 됐습니다. 스랄, 가시지요.', `MaleText_loc4`='我们准备好带你离开这里了，萨尔。出发吧！', `MaleText_loc5`='我們已經準備好要救你出來了，索爾。來吧!', `MaleText_loc7`='Estamos listos para sacarte de aquí, Thrall. ¡Vamos!', `FemaleText_loc1`='이곳을 나갈 준비가 됐습니다. 스랄, 가시지요.', `FemaleText_loc4`='我们准备好带你离开这里了，萨尔。出发吧！', `FemaleText_loc5`='我們已經準備好要救你出來了，索爾。來吧!', `FemaleText_loc7`='Estamos listos para sacarte de aquí, Thrall. ¡Vamos!' WHERE `ID`=14468;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 소중한 지도자가 너희를 저버렸다! 이제 그의 손에 너희의 피를 묻혀주리라! 공격!', `MaleText_loc4`='你效忠的首领令你失望了！让他的双手沾满你的鲜血！进攻！', `MaleText_loc5`='你摯愛的領導者已經辜負你了!讓你的鮮血沾滿他的手吧!攻擊!', `MaleText_loc7`='¡Tu querido líder te ha fallado! ¡Deja que tu sangre esté en sus manos! ¡Atacad!' WHERE `ID`=14470;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='승리가 눈앞에 있다! 록타르 오가르!', `MaleText_loc4`='离胜利只有一步之遥了！Lok-Tar Ogar！', `MaleText_loc5`='勝利就只差一步了!不勝即亡!', `MaleText_loc7`='¡La victoria está a un tiro de piedra! ¡Lok-Tar Ogar!' WHERE `ID`=14471;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주요 수조의 상태는 어떻습니까?', `MaleText_loc4`='主储水箱的状态怎么样了？', `MaleText_loc5`='主要儲水池現在狀況如何?', `MaleText_loc7`='¿Cuál es el estado de nuestro tanque principal?' WHERE `ID`=14472;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저건 수조 안에서 뭘 하는 겁니까?', `MaleText_loc4`='什么东西在储水箱里？', `MaleText_loc5`='儲水池裡那是什麼東西?', `MaleText_loc7`='¿Qué hace esa cosa dentro del tanque?' WHERE `ID`=14473;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요청한 방류 신청에 대해 멘누께서 무슨 말씀이 없으셨습니까?', `MaleText_loc4`='门努对我们要求的援助有任何答复吗？', `MaleText_loc5`='有曼紐傳來關於我們需要救濟物品的消息嗎?', `MaleText_loc7`='¿Algún mensaje de Mennu sobre la ayuda que solicitamos?' WHERE `ID`=14475;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희는 누수를 막기 위해 가능한 모든 조치를 취하고 있습니다!', `MaleText_loc4`='长官，我们正在尽一切可能找出泄漏的位置！', `MaleText_loc5`='長官，我們已經盡一切力量來對付裂縫!', `MaleText_loc7`='¡Señor, estamos haciendo todo lo posible para solucionar el escape!' WHERE `ID`=14477;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여전히 새고 있습니다.', `MaleText_loc4`='仍然在泄漏，长官。', `MaleText_loc5`='還在漏水，長官。', `MaleText_loc7`='Sigue goteando, señor.', `FemaleText_loc1`='여전히 새고 있습니다.', `FemaleText_loc4`='仍然在泄漏，长官。', `FemaleText_loc5`='還在漏水，長官。', `FemaleText_loc7`='Sigue goteando, señor.' WHERE `ID`=14478;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물을 멈추기 위해 가능한 모든 조치를 취하고 있습니다.', `MaleText_loc4`='我们在尽一切办法把水停住。', `MaleText_loc5`='我們正在盡一切努力阻擋漏水。', `MaleText_loc7`='Estamos haciendo todo lo que podemos para detener el agua.', `FemaleText_loc1`='물을 멈추기 위해 가능한 모든 조치를 취하고 있습니다.', `FemaleText_loc4`='我们在尽一切办法把水停住。', `FemaleText_loc5`='我們正在盡一切努力阻擋漏水。', `FemaleText_loc7`='Estamos haciendo todo lo que podemos para detener el agua.' WHERE `ID`=14479;
