UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멘누 님과 연락을 취하는 데 문제가 있었습니다!', `MaleText_loc4`='我们和门努之间的联络出了问题，长官！', `MaleText_loc5`='曼紐有麻煩了，長官!', `MaleText_loc7`='¡Ha habido problemas para ponernos en contacto con Mennu, señor!', `FemaleText_loc1`='멘누 님과 연락을 취하는 데 문제가 있었습니다!', `FemaleText_loc4`='我们和门努之间的联络出了问题，长官！', `FemaleText_loc5`='曼紐有麻煩了，長官!', `FemaleText_loc7`='¡Ha habido problemas para ponernos en contacto con Mennu, señor!' WHERE `ID`=14485;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강제 노역소에 보낸 우리 전령이 아직 돌아오지 않았습니다.', `MaleText_loc4`='我们派去奴隶围栏的那个信使再也没有回来过，长官。', `MaleText_loc5`='我們前往奴隸監獄的信差從未回來過，長官。', `MaleText_loc7`='Nuestro mensajero al Recinto de los Esclavos nunca regresó, señor.', `FemaleText_loc1`='강제 노역소에 보낸 우리 전령이 아직 돌아오지 않았습니다.', `FemaleText_loc4`='我们派去奴隶围栏的那个信使再也没有回来过，长官。', `FemaleText_loc5`='我們前往奴隸監獄的信差從未回來過，長官。', `FemaleText_loc7`='Nuestro mensajero al Recinto de los Esclavos nunca regresó, señor.' WHERE `ID`=14486;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서둘러라! 일리단 님은 실수를 너그러운 아량으로 넘기시는 분이 아니란 말이다!', `MaleText_loc4`='好吧，赶快！伊利丹大人没有耐心容忍错误！', `MaleText_loc5`='嗯，快點!伊利丹王沒有耐心容忍錯誤!', `MaleText_loc7`='¡Bueno, date prisa! ¡Lord Illidan no tiene paciencia para los errores!' WHERE `ID`=14488;
