UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그가 애완용 고블린과 노는 시간을 줄이고 훈련에 더 많은 시간을 투자했더라면 이걸 충분히 고칠 수 있었을 것이다!', `MaleText_loc4`='如果他在他的地精宠物身上少花点时间，在训练上多花点时间的话，我们应该就能修复这东西了！', `MaleText_loc5`='或許如果他花少一點時間和他的寵物哥布林玩耍，多一點時間訓練，我們就會有足夠的能力修理這東西了!', `MaleText_loc7`='¡Quizás si hubiera pasado menos tiempo jugando con su mascota goblin y más tiempo instruyéndose, tendríamos el poder suficiente para arreglar esta cosa!' WHERE `ID`=14491;
