UPDATE `locales_broadcast_text` SET `MaleText_loc1`='프우르 인제 간다, $n. 방주 가지고 돌아온다.', `MaleText_loc4`='弗沃尔去，$n。去拿箱子，回来。', `MaleText_loc5`='費斯伍爾現在走了，$n。拿到方舟，再回來。', `MaleText_loc7`='Fhwoor ir ahora, $n. Conseguir arca, volver.' WHERE `ID`=14639;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나가 처치 준비 시간이다.', `MaleText_loc4`='休息一会……准备好。', `MaleText_loc5`='抓住時機...做好準備。', `MaleText_loc7`='Tomar momento... prepararse.' WHERE `ID`=14640;
