UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 쉬슬리스의 방주를 가볍게 들어올립니다.', `MaleText_loc4`='%s轻松地举起了萨斯里斯圣柜。', `MaleText_loc5`='%s毫不費力的將斯利斯方舟舉起。', `MaleText_loc7`='%s alza el arca de Ssslith con facilidad.' WHERE `ID`=14642;
