UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 쉬슬리스의 방주를 땅에 내려놓습니다.', `MaleText_loc4`='%s把萨斯里斯圣柜放在地上。', `MaleText_loc5`='%s將斯利斯方舟放在地上。', `MaleText_loc7`='%s deja el arca de Ssslith en el suelo.' WHERE `ID`=14645;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='프우르 잘했다!', `MaleText_loc4`='弗沃尔干得好！', `MaleText_loc5`='費斯伍爾做的好!', `MaleText_loc7`='¡Fhwoor hacer bien!' WHERE `ID`=14646;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벡터 코일을 파괴할 때가 되었소!', `MaleText_loc4`='摧毁矢量感应器的时机到了！', `MaleText_loc5`='是時候來摧毀旋繞導航器了!', `MaleText_loc7`='¡Ha llegado el momento de destruir la Espiral Vectorial!' WHERE `ID`=14647;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 임무를 맡았으니 이제 앞으로 나아갈 길만이 있을 뿐이오. 바짝 따라오면서 내 뒤를 부탁하오.', `MaleText_loc4`='现在已经没有退路了，$n。靠近我，小心背后。', `MaleText_loc5`='現在沒有辦法回頭了，$n。跟好隊伍，幫我把風。', `MaleText_loc7`='Ahora no nos podemos volver, $n. Quédate cerca y vigila mi retaguardia.' WHERE `ID`=14648;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기로군! 벡터 코일에서 거대한 붉은색 수정이 튀어나온 부분이 보이오? 저곳이 바로 첫 번째 폭탄을 설치할 위치요.', `MaleText_loc4`='就是这个！你看到矢量感应器上突起的红色水晶了吗？那就是放置第一组炸药的地方。', `MaleText_loc5`='在那裡!你有看到那個巨大的紅色水晶從旋繞導航器探出頭來嗎?我要在那裡放置第一批爆裂物。', `MaleText_loc7`='¡Ahí está! ¿Ves dónde sobresale el cristal rojo grande de la Espiral Vectorial? Ahí es donde necesito colocar el primer grupo de explosivos.' WHERE `ID`=14649;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엄호해 주시오!', `MaleText_loc4`='掩护我！', `MaleText_loc5`='掩護我!', `MaleText_loc7`='¡Cúbreme!' WHERE `ID`=14650;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼마 안 걸릴 테니 폭탄을 설치하는 동안 녀석들이 접근하지 못하게 막아주시오.', `MaleText_loc4`='不需要太久的，$n。不要让他们接近我。', `MaleText_loc5`='不會再久了，$n。我工作的時候叫他們別來煩我。', `MaleText_loc7`='No falta mucho más tiempo, $n. Solo haz que no se me acerquen mientras trabajo.' WHERE `ID`=14651;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다 됐소! 어서 몸을 숨기시오!', `MaleText_loc4`='搞定了！快找掩护！', `MaleText_loc5`='行動!快，找掩護!', `MaleText_loc7`='¡Esto servirá! ¡Rápido, a cubierto!' WHERE `ID`=14652;
