UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 일로 너무 흥분하지 마시오, 영웅 친구. 지금까지의 일은 쉬운 부분이었소. 앞으로 험난한 과정이 기다리고 있으니 어서 갑시다!', `MaleText_loc4`='不要过于兴奋，英雄，这只是最简单的部分。真正的挑战正在等着我们呢！走吧。', `MaleText_loc5`='別太興奮，英雄，那是較簡單的部份。挑戰還在前頭!走吧。', `MaleText_loc7`='No te emociones demasiado, héroe, esa era la parte fácil. ¡El reto está por venir! Vamos.' WHERE `ID`=14656;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저건 대체 뭐지?!?!', `MaleText_loc4`='那是什么东西？！', `MaleText_loc5`='那是什麼東西在虛空之中?!?!', `MaleText_loc7`='¡¿¡¿Qué es eso, en nombre del Vacío?!?!' WHERE `ID`=14657;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠... 단단히 준비하도록 하시오, $n.', `MaleText_loc4`='做好准备，$n。', `MaleText_loc5`='做好一切的準備，$n。', `MaleText_loc7`='Prepárate para cualquier cosa, $n.' WHERE `ID`=14658;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 이런 빛의 가호가 있으라! 시로나스가 벡터 코일에서 직접 힘을 흡수하고 있소이다!', `MaleText_loc4`='圣光在上！她正在吸取矢量感应器的能量！', `MaleText_loc5`='讚美聖光!她正在抽取旋繞導航器的能量!', `MaleText_loc7`='¡Luz bendita! ¡Está succionando energía de la Espiral Vectorial!' WHERE `ID`=14659;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엄호해 주시오. 빨리 끝내야 하오. 내가 이쪽 측면의 수정을 날려버리면 시로나스에게 힘을 주는 광선을 방해하여 그녀가 깨어날 것이오! 그녀가 우리를 보면 엄청난 화를 내뿜을 거란 생각이 드는군...', `MaleText_loc4`='掩护我，我们必须再快点。一旦我炸开了这边，就会破坏能量光束，她一定会冲出来的！我想她不会很高兴见到我们的。', `MaleText_loc5`='掩護我，我們動作要快。一旦我擊破這邊的防禦，就會中斷能量光束，她就會爆衝出來!我很懷疑她會高興看到我們。', `MaleText_loc7`='Cúbreme. Hay que darse prisa. ¡Cuando destruya el soporte de este lado, habrá una perturbación en los rayos de energía y saldrá! Dudo mucho que se alegre de vernos.' WHERE `ID`=14660;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거의 다 됐소! 조금만 시간을 더...', `MaleText_loc4`='快完成了！只要再多一点时间……', `MaleText_loc5`='我就快成功了!只要再多一點時間...', `MaleText_loc7`='¡Ya casi lo tenemos! Un poco más de tiempo...' WHERE `ID`=14661;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 다 됐소. 몸을 숨기고 목숨을 지킬 준비를 하시오, $n!', `MaleText_loc4`='快找掩护！准备为你的性命而战吧，$n！', `MaleText_loc5`='找掩護，準備殊死一戰吧，$n!', `MaleText_loc7`='¡Ponte a cubierto y prepárate para la lucha de tu vida, $n!' WHERE `ID`=14662;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 빛의 어머니이신 오로스여... 저희를 지켜주소서!', `MaleText_loc4`='沃洛斯在上！天啊！', `MaleText_loc5`='我的媽啊!', `MaleText_loc7`='¡Santa madre de O''ros!' WHERE `ID`=14663;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시로나스가 죽었다! 드... 드디어 모든 게 끝났다는 것이 믿을 수가 없군! 해냈단 말이오! 당신이 블러드 엘프 녀석들과 시로나스를 해치웠소!', `MaleText_loc4`='我……我简直不敢相信。你成功了！你消灭了血精灵和他们的首领！', `MaleText_loc5`='我...我不敢相信它結束了。你做到了!你摧毀了血精靈和他們的領導者!', `MaleText_loc7`='No... no me puedo creer que se haya acabado. ¡Lo has hecho! ¡Has destruido a los elfos de sangre y a su líder!' WHERE `ID`=14664;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='핏빛 감시초소로 돌아가시오. 거기서 다시 봅시다...', `MaleText_loc4`='回秘血岗哨吧。我会在那里和你碰面……', `MaleText_loc5`='回去血色守望。我會在那裡和你會面...', `MaleText_loc7`='Vuelve a la Avanzada de Sangre. Te veré allí...' WHERE `ID`=14665;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='버릇없는 녀석들, 너희 신에게 기도나 올려라. 너희는 곧 네놈들의 신을 만나게 될 테니까!', `FemaleText_loc4`='狂妄的孩子们，在你们快要见到你们的神明之前向他祈祷吧！', `FemaleText_loc5`='任性的孩子，向神祇禱告吧，因為你就快要去見祂了!', `FemaleText_loc7`='¡Niños malcriados, rezen a sus dioses, pues están a punto de reunirse con ellos!' WHERE `ID`=14666;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 이곳에서 인내심을 갖고 명령을 기다리고 있습니다.', `FemaleText_loc4`='我在耐心等候命令，$c。', `FemaleText_loc5`='我正耐心地等待命令，$c。', `FemaleText_loc7`='Aguardo órdenes pacientemente, $c.' WHERE `ID`=14667;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐요! 여기 이쪽입니다! 네, 여기 이쪽... 이 우리 안에 있습니다!!!', `MaleText_loc4`='嘿！过来！对，过来……我在这个笼子里面！！！', `MaleText_loc5`='嘿!看這裡!對，這裡...我在籠子裡!!!', `MaleText_loc7`='¡Eh! ¡Por aquí! Sí, por aquí... ¡¡¡Estoy en esta jaula!!!' WHERE `ID`=14668;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말한 대로 건방진 참견이 사라지니 쿠아그미란이 가까이 왔군요!$B$B약속드린 대로 그와 싸우는 데 도움이 되는 신비의 은혜로 그대를 강하게 해드리지요.', `MaleText_loc4`='现在终于安全了，就像我刚才所说的那样，夸格米拉就在附近！$B$B我说到做到，现在我可以给你施加一个强化魔法，应该可以在你和他的战斗中帮到你。', `MaleText_loc5`='粗野的干擾已結束，如我所說，奎克米瑞已經接近了!$B$B依先前允諾的，我可以用一個魔法恩賜增強你的力量，幫助你與他對抗。', `MaleText_loc7`='Ahora que la grosera interrupción ha terminado, como iba diciendo, ¡Quagmirran está cerca!$B$BSegún lo prometido, puedo fortalecerte con un favor mágico que debería ayudarte en tu lucha contra él.' WHERE `ID`=14669;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='식물학자님, 그 은혜로 절 강하게 해주십시오.', `MaleText_loc4`='博学者，请给我施加这个魔法吧。', `MaleText_loc5`='自然療者，請給予我你的恩賜。', `MaleText_loc7`='Naturalista, concédeme tu favor.', `FemaleText_loc1`='식물학자님, 그 은혜로 절 강하게 해주십시오.', `FemaleText_loc4`='博学者，请给我施加这个魔法吧。', `FemaleText_loc5`='自然療者，請給予我你的恩賜。', `FemaleText_loc7`='Naturalista, concédeme tu favor.' WHERE `ID`=14670;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[서투른 공용어] 축제를 벌일 시간입니다.', `MaleText_loc4`='[不流畅的通用语] 该庆祝了。', `MaleText_loc5`='[操著不流利的普通語]是時候慶祝我們做的事了。', `MaleText_loc7`='[En lengua común con dificultad] Es hora de celebrar que lo hacemos.' WHERE `ID`=14671;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예언의 현신이여, 우리와 쿠르즈의 예언을 기억하시오? 지금 이 순간은 이미 결정된 운명이었소. 당신은 이 세계에서 맡은 일을 모두 완수했소.$B$B<당신에게 고개를 숙이는 대족장 너울소나무>$B$B나의 백성들은 언제나 드레나이를 환영할 것이오.', `MaleText_loc4`='英雄，你还记得我们吗？你还记得库尔兹的预言吗？这是个命中注定的时刻。你完成了你与生俱来的使命。$B$B<止松老酋长在你面前鞠躬。>$B$B德莱尼人会永远受到我的人民的欢迎。', `MaleText_loc5`='允諾者，你記得我們嗎?你還記得克茲的預言嗎?這一刻是早就註定的了。你已做了這個世界要你做的。$B$B<大酋長靜松在你面前鞠躬。>$B$B德萊尼將會永遠受我的人民愛戴。', `MaleText_loc7`='$gPrometido:Prometida;, ¿nos recuerdas? ¿Recuerdas la profecía de Kurz? Este momento ya estaba dispuesto. Has hecho aquello para que lo viniste a este mundo.$B$B<El gran jefe Semprepino se inclina ante ti.>$B$BLos Draenei siempre serán bienvenidos entre mi gente.' WHERE `ID`=14672;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[서투른 공용어] 너울소나무 일족 영웅에게 감사하오. 고맙소이다!', `MaleText_loc4`='[不流畅的通用语] 止松要塞感谢英雄。非常感谢！', `MaleText_loc5`='[操著不流利的普通語]靜松感謝英雄。非常感謝!', `MaleText_loc7`='[En lengua común con dificultad] Semprepino gracias a héroe. ¡Mucho gracias!' WHERE `ID`=14673;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영광스러운 승리로구나!', `MaleText_loc4`='一个光荣的胜利！', `MaleText_loc5`='一個光榮的勝利!', `MaleText_loc7`='¡Una victoria gloriosa!' WHERE `ID`=14674;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='먼 길을 왔구려, $n. 정말 먼길이로군... 하지만, 나는 당신이 위대한 영웅이 될 운명이라는 것을 알고 있었소. 우리 모두 말이지. 정말 대단하구려, $n!$B$B그리고 우리 안에 있던 노움 문제를 해결해 준 점 다시 한 번 고맙게 생각하오...', `MaleText_loc4`='$n，这一路累得够呛吧。可算是长途跋涉啊……但是我相信，你注定要经历这许多不寻常的故事。我们都相信。向你致敬，$n！$B$B再次感谢你帮我们解决了这件麻烦事……', `MaleText_loc5`='你走了很長一段路，$n。真的是很辛苦...但我知道你注定要成就偉大的事業。我們都知道。全體向$n敬禮!$B$B再次謝謝你解決了我們的地精問題...', `MaleText_loc7`='Has recorrido un largo camino, $n. Muy largo, sí... Pero sabía que tu destino te reservaba grandes cosas. Todos lo sabíamos. ¡Saludad todos a $n!$B$BY gracias por ocuparte de nuestro problema gnomo...' WHERE `ID`=14675;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 당신의 승리를 축하하고 우리의 새로운 동맹들을 환영하려고 여기 왔소!', `MaleText_loc4`='我们在这里庆祝你的胜利，并欢迎我们新的同盟！', `MaleText_loc5`='我們來這裡慶祝你的勝利並歡迎我們新發現的盟友!', `MaleText_loc7`='¡Estamos aquí para celebrar tu victoria y para dar la bienvenida a nuestros recién hallados aliados!' WHERE `ID`=14676;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 제 목숨을 구해 준 분에게 고맙다는 말을 전하고자 여기 왔답니다.', `FemaleText_loc4`='我来这里是为了感谢那位拯救我性命的英雄。', `FemaleText_loc5`='我是來謝謝那個救過我一命的人。', `FemaleText_loc7`='Estoy aquí para dar las gracias a quien me salvó la vida.' WHERE `ID`=14677;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='절 기억하지 못하실지도 모르겠지만 그대가 제 목숨을 구해 주셨습니다. 저는 얼마 전에야 비로소 혼자 걸을 수 있을 만큼 건강이 회복되었지요.$B$B절 구해 주신 데 대한 감사의 인사와 제가 했던 말에 대한 사과를 드리고 싶었습니다... 고맙습니다, $n. 언제나 엘룬께서 그대를 굽어살피시길...', `FemaleText_loc4`='你可能不记得我了，但是你救了我的命。我最近才刚刚恢复健康，可以自己下地行走了。$B$B我想感谢你为我做的一切，并为我所说过的话道歉……谢谢你，$n。希望艾露恩永远保佑你。', `FemaleText_loc5`='你或許不記得我，但你救了我一命。我最近才康復到可以自己走路。$B$B我想謝謝你為我做的一切並為我說過的話道歉...謝謝你，$n。願伊露恩永遠守護著你。', `FemaleText_loc7`='Probablemente no me recuerdes, pero me salvaste la vida. Hace poco tiempo que me he recuperado lo suficiente como para poder andar sin ayuda.$B$BQuería darte las gracias por lo que hiciste por mí y pedirte disculpas por lo que pude decir... Gracias, $n. Que Elune te proteja.' WHERE `ID`=14678;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 당신을 끌어안습니다.', `FemaleText_loc4`='%s拥抱了你。', `FemaleText_loc5`='%s擁抱你。', `FemaleText_loc7`='%s te abraza.' WHERE `ID`=14679;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 우리의 영웅을 지원하고자 여기 왔네!', `MaleText_loc4`='我们是来为英雄喝彩的！', `MaleText_loc5`='我們是來這裡幫助我們的英雄的!', `MaleText_loc7`='¡Estamos aquí para apoyar a nuestro héroe!' WHERE `ID`=14680;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절대로 이걸 놓치지 말았어야 했는데 말일세, $n.$B$B<당신을 끌어안는 총독 메넬라우스>$B$B우리는 자네가 자랑스럽다네.', `MaleText_loc4`='我这辈子都不会忘记的，$n。$B$B<大主教梅内莱厄斯拥抱了你。>$B$B我们为你感到骄傲。', `MaleText_loc5`='為了世界我不會錯過的，$n。$B$B<主教米奈奧斯擁抱你。>$B$B我們以你為傲。', `MaleText_loc7`='No me lo habría perdido por nada del mundo, $n.$B$B<El exarca Menelaous te abraza.>$B$BEstamos orgullosos de ti.' WHERE `ID`=14681;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 드레나이 용사를 지원하려고 왔소이다!', `MaleText_loc4`='我是来支持德莱尼勇士的！', `MaleText_loc5`='我是來支援德萊尼勇士的!', `MaleText_loc7`='¡He venido a apoyar al campeón draenei!' WHERE `ID`=14682;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 만나서 반갑소이다, $n. 내 친구와 함께 왔소. 그녀가 정말 당신을 만나고 싶어해서 말이오.$B$B<소리 내어 웃는 케셀>', `MaleText_loc4`='很高兴再次见到你，$n。我带了个朋友过来，她非常想见到你。$B$B<凯希尔大笑起来。>', `MaleText_loc5`='再次見到你真好，$n。我帶了一個朋友和我一起。她真的很想見你。$B$B<凱索笑著。>', `MaleText_loc7`='Me alegro de volver a verte, $n. He traído a una amiga conmigo. Ella tenía muchas ganas de verte.$B$B<Kessel se ríe.>' WHERE `ID`=14683;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘은 드레나이에게 영광스러운 날이오! 당신이 한 모든 일에 감사하오, $n.', `MaleText_loc4`='这是德莱尼人的荣耀之日！谢谢你为我们所做的一切，$n。', `MaleText_loc5`='這是德萊尼榮耀的一天!謝謝你所做的一切，$n。', `MaleText_loc7`='¡Este es un día glorioso para los draenei! Gracias por todo lo que has hecho, $n.' WHERE `ID`=14684;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 드레나이 백성들의 영웅을 축하하기 위해 먼 길을 왔습니다.', `MaleText_loc4`='我们远道而来，是为了感谢德莱尼人的英雄。', `MaleText_loc5`='我們走了一大段路來慶祝德萊尼人民的英雄。', `MaleText_loc7`='Hemos viajado hasta aquí para celebrar al héroe del pueblo draenei.' WHERE `ID`=14685;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신을 만나기 위해서라면 대해라도 건넜을 겁니다. 우리는 당신이 우리를 위해 한 일을 잊지 않을 겁니다.', `MaleText_loc4`='我特地穿越无尽之海来看你，朋友。我们永远都不会忘记你为我们所做的一切。', `MaleText_loc5`='我會越過無盡之海來看你。我們永遠不會忘記你為我們做的事。', `MaleText_loc7`='Habría cruzado el Mare Mágnum para verte, $gamigo:amiga;. Nunca olvidaremos lo que hiciste por nosotros.' WHERE `ID`=14686;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 절 위해 한 일에 대해 다시 한 번 감사를 드리고 싶었습니다. 당신은 저에게 숲의 짐승들로부터 고향을 되찾을 수 있는 용기를 주셨습니다. 그 과정에서 저는 마그윈을 찾았습니다!', `MaleText_loc4`='我想再次感谢你为我做的一切。你给了我驱赶森林中的野兽、夺回了我的家园的勇气。而且，我还找到了麦戈薇！', `MaleText_loc5`='我想再次感謝你為我所做的一切。你給了我勇氣從森林裡的野獸手裡奪回我的家園。同時，我還找到了麥格文!', `MaleText_loc7`='Quería agradecerte lo que hiciste por mí. Me diste fuerzas para recuperar mi hogar de las bestias del bosque. ¡Y al hacerlo, encontré a Magwin!' WHERE `ID`=14687;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 딸을 구해 주신 그 은혜는 평생을 다해도 갚지 못할 겁니다, $n. 정말 감사합니다.', `MaleText_loc4`='你救了我女儿的性命，$n，你的恩情我永世不忘。谢谢你，$n。', `MaleText_loc5`='你救了我的女兒，$n，因為這樣，我永遠都欠你一份人情，$n。非常感謝你。', `MaleText_loc7`='Salvaste a mi hija, $n, y por eso estoy en deuda eterna contigo, $n. Muchas gracias.' WHERE `ID`=14688;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드레나이 용사가 우리와 함께하고 있도다. 이것은 하늘안개 섬과 핏빛안개 섬의 구원자를 축하하기 위한 것이니라!', `MaleText_loc4`='德莱尼人的勇士和我们在一起。为秘蓝岛和秘血岛的救世主欢呼吧！', `MaleText_loc5`='德萊尼的勇士就走在我們之中。這是個藍謎島和血謎島救星的慶祝活動!', `MaleText_loc7`='El campeón draenei camina entre nosotros. ¡Es una celebración para el salvador de Bruma Azur y Bruma de Sangre!' WHERE `ID`=14689;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 모든 것이 $g형제:자매;를 위한 것일세, $n. $g형제:자매;는 위대한 일을 해냈네. $g형제:자매;는 이 모든 종족들과 수천 명이 넘는 목숨을 구했네.$B$B$g형제:자매;는 이 세계가 겪고 있던 반목과 비극을 극복했으며 그 과정에서 $g형제:자매;와 함께 우리 모두의 위상을 드높였네.$B$B$g형제:자매;는 정말 많은 일을 해냈다네. 많은 이들이 열 번의 삶을 통해 할 수 있는 것보다도 많은 일을 이겨냈지. 하지만, $g형제:자매;의 삶은 이제부터 시작일세. $g형제:자매; 같은 영웅이 천 명만 있다면 정말 평화로울 텐데...$B$B하지만, 잘 듣게나, $n. $g형제:자매;의 운명은 아웃랜드에 있네. 내 예시 속에서 $g형제:자매;의 모습을 보았다네. 이것은 아직 말하지 않은 예언일세.$B$B우리 종족들을 찾아주게나, $n. 그들을 찾아서 고향으로 데려오게...', `MaleText_loc4`='这一切都是你的成就，$n。你成功地拯救了成千上万的人。$B$B你已经超越了这个世界上的冲突和灾难，让我们与你一起升华。$B$B你的功绩，许多人十辈子也无法达到，而你的旅程才刚刚开始。如果我们有几千个像你这样的英雄就好了。$B$B但是，$n，你的命运在外域等待着你。我从幻像中看到了一个不甚明了的预言。$B$B找到我们的人民，$n。找到他们，带他们回家……', `MaleText_loc5`='這全都是給你的，$n。你做到了。你救了所有這些人們和幾千幾萬的生命。$B$B你在這世界的衝突和悲劇之上興起，將我們和你一起提升。$B$B你做了這麼多 - 比許多人十輩子可以做的還要多 - 但你的生命才剛開始。真希望我們有幾千個像你一樣的英雄。$B$B但聽好了，$n。你的命運在外域。我在幻境中看過一個未透露的預言。$B$B找到我們的人民，$n。找到他們並把他們帶回家...', `MaleText_loc7`='Todo esto es por ti, $n. Tú lo lograste. Salvaste a toda esta gente y a miles más.$B$BHas hecho mucho; más de lo que muchos no habrían hecho en diez vidas. Pero acabas de empezar. Si hubiera mil héroes como tú...$B$BPero escucha bien, $n. Tu destino está en Terrallende. Lo he visto en mis visiones; una profecía por desvelar.$B$BEncuentra a nuestra gente, $n. Encuéntralos y tráelos a casa...' WHERE `ID`=14690;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 하늘안개 섬과 핏빛안개 섬의 구원자인 $n|1을;를; 맞이하라. 그대는 아르거스의 대리인의 영웅이자 드레나이의 용사요!', `MaleText_loc4`='为秘蓝岛和秘血岛的救世主$n欢呼吧，阿古斯之手的英雄，德莱尼人的勇士！', `MaleText_loc5`='讚美$n，藍謎島和血謎島的救星。阿古斯之手的英雄，德萊尼人民的勇士!', `MaleText_loc7`='Aclamen todos a $n, $gsalvador:salvadora; de Bruma Azur y Bruma de Sangre. ¡$gHéroe:Heroína; de la Mano de Argus, $gcampeón:campeona; de los draenei!' WHERE `ID`=14691;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드를 둘러싼 높은 성벽이 당당한 위용을 자랑하는 모습을 보니 내 마음이 참으로 흡족하군.$b$b지금 스트라솔름으로 가볼 작정이라면 내 도움을 받을 생각은 꿈에도 하지 말게나. 그 불타오르는 도시 근처의 탑들은 아직 전쟁의 소용돌이에 휩싸여 있고 내 하찮은 능력은 자네에게 별 도움이 되지 않으니까 말이야. 자네 진영이 거기서 성공을 거두면, 날 다시 찾아오게.', `MaleText_loc4`='看着雄伟的暴风城城墙高耸、壁垒森严、固若金汤，真是令人倍感欣慰。$B$B你想去斯坦索姆？恐怕眼下我没法帮你。在那座燃烧的城市附近，哨塔争夺战仍在继续；而且我的力量太过薄弱，真是爱莫能助啊。如果你能成功夺得哨塔，再来找我吧。', `MaleText_loc5`='這正是我所希望見到的暴風城壯碩、聳立的城牆。$b$b如果你正期待前往斯坦索姆，恐怕我現在無法幫你。燃燒城市附近的哨塔仍在爭奪中，而我的力量太過微弱以至於無法協助你。等你在那裡獲得勝利後再回來找我。', `MaleText_loc7`='Me alegra ver una Ventormenta fuerte y pujante.$b$bSi lo que quieres es ir a Stratholme, me temo que ahora mismo no te puedo ayudar. Las torres en las cercanías de la ciudad ardiente todavía están en disputa, y por ello no tengo poder suficiente para ayudarte. Regresa a mí una vez hayas conseguido conquistarlas.' WHERE `ID`=14692;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 자네 진영이 승리했다는 사실이 느껴지는군! 이제 자네가 스트라솔름까지 안전하게 순간이동할 때가 되었군. 단, 자네가 내 동료를 먼저 만나봤다면 말이지. 원형 안으로 들어와서 조용히 기다리게...', `MaleText_loc4`='啊，我能感受到——你获胜啦！如果你已经拜访过我在斯坦索姆的同伴，我想现在我能将你安全传送到那儿了。来，走到法阵中来，耐心等待……', `MaleText_loc5`='啊，我可以感覺到 - 你成功了!如果你已先拜訪了我那裡的同事，我相信現在可以安全地將你傳送至斯坦索姆了。踏進那個圓圈裡耐心等候...', `MaleText_loc7`='Ah, puedo sentirlo... ¡Hoy es tu día! Creo que te puedo transportar a Stratholme, siempre que le hayas hecho una visita allí a mi compañero. Simplemente párate en medio del círculo y espera...' WHERE `ID`=14693;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런! 겁쟁이 바보들아! 감히 나와 맞설 생각이라면 내가 있는 곳으로 와라!', `MaleText_loc4`='呸！胆小鬼，蠢货！如果你们够胆的话，就回到我的平台上来跟我较量！', `MaleText_loc5`='呸!懦夫和蠢蛋!如果你有膽挑戰我就回到我的平臺去!', `MaleText_loc7`='¡Bah! ¡Cobardes y estúpidos! ¡Vuelve a mi plataforma si osas enfrentarte a mí!' WHERE `ID`=14694;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리는 경계를 늦출 여유가 없습니다. 이 세계는 불타는 군단의 첩자들과 동맹들로 가득한 곳입니다. 조금이라도 이상한 것을 발견하면 주저하지 말고 제게 보여주십시오.', `FemaleText_loc4`='我们不能让我们的卫兵倒下，$C。这个世界布满了燃烧军团的爪牙和同盟，如果你发现了任何奇怪的东西，就立即告诉我。', `FemaleText_loc5`='我們不能讓我們的守衛倒下，$c。這個世界充滿了燃燒軍團的密探和盟友。如果你遇到任何奇怪的事，立刻向我報備。', `FemaleText_loc7`='No podemos permitirnos bajar la guardia, $c. Este mundo está plagado de agentes y aliados de la Legión Ardiente. Si tropiezas con algo extraño, no dudes en mostrármelo.' WHERE `ID`=14695;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이시엘은 아웃랜드로 진출하는 과정에서 적의 저항이 있을 거라 예상했습니다. 그래서 우리 감시자들이 함께 원정에 참여한 것이지요.$B$B우리는 나가가 그 정도의 힘과 숫자로 우리에게 맞서리라고는 예상도 못했습니다.', `MaleText_loc4`='伊谢尔预计那些与她为敌的家伙也会入侵外域，这便是我们驻守此地的原因。$B$B我们可不愿看到敌人以超过那些纳迦军队的规模大举来犯。', `MaleText_loc5`='伊斯歐認為一些敵方對手會對外域展開突擊。這就是為什麼我們看守者也來到這裡的原因。$B$B我們從未想過我們的對手會以納迦呈現過的力量或數量出現。', `MaleText_loc7`='Ysiel esperaba algo de resistencia enemiga a su incursión en Terrallende. Por eso se nos trajo a los celadores.$B$BNunca esperamos que nuestra resistencia viniera con la fuerza o los números que los nagas han mostrado.' WHERE `ID`=14696;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그대가 누군지는 모르겠으나 진심으로 환영합니다. $C|1이여;여;, 아키몬드와 그의 스컬지가 언제 침략할지 모르는 급박한 상황입니다. 우리와 함께 이 악마를 막아내는 데 그대의 힘을 빌려주지 않겠습니까?', `FemaleText_loc4`='我不知道你是谁，但是我欢迎你的到来。阿克蒙德和他的天灾军团随时都有可能向我们进攻，$C。你会和我们一起面对这些恶魔吗？', `FemaleText_loc5`='我不知道你是誰，但歡迎你的到來。阿克蒙德和他的天譴軍隊隨時都有可能發動攻擊，$C。你會和我們站在同一陣線對抗這個惡魔嗎?', `FemaleText_loc7`='No tengo ni idea de quién eres, pero tu presencia aquí es de lo más bienvenida. Archimonde y su ejército de la Plaga podría atacar en cualquier momento, $c. ¿Estarás con nosotros para luchar contra este mal?' WHERE `ID`=14697;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 동료와 저는 프라우드무어 님, 당신과 함께하겠습니다.', `MaleText_loc4`='我和我的伙伴们将与您并肩作战，普罗德摩尔女士。', `MaleText_loc5`='我和我的同伴都與你同在，普勞德摩爾女士。', `MaleText_loc7`='Mis compañeros y yo estamos contigo, Lady Valiente.', `FemaleText_loc1`='제 동료와 저는 프라우드무어 님, 당신과 함께하겠습니다.', `FemaleText_loc4`='我和我的伙伴们将与您并肩作战，普罗德摩尔女士。', `FemaleText_loc5`='我和我的同伴都與你同在，普勞德摩爾女士。', `FemaleText_loc7`='Mis compañeros y yo estamos contigo, Lady Valiente.' WHERE `ID`=14698;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$r|1이여;여;, 고맙습니다. 이제 대비를 하시기 바랍니다. 아키몬드가 다가오고 있습니다. 우리는 이 피할 수 없는 상황을 최선을 다해 막아내야 합니다.', `FemaleText_loc4`='谢谢你，$c。好好准备一下。阿克蒙德正在行军，我们必须尽可能在这里坚守得更久一些。', `FemaleText_loc5`='謝謝你，$R。現在做好準備。阿克蒙德就在邊界，我們一定要盡量拖延不可避免的一切。', `FemaleText_loc7`='Gracias, $r. Ahora, preparaos. Archimonde está en marcha y debemos retrasar lo inevitable todo lo que podamos.' WHERE `ID`=14699;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아제로스에 도움을 청하는 일이 썩 내키지는 않지만 우리에게는 선택의 여지가 없어요.', `FemaleText_loc4`='我不喜欢那个向艾泽拉斯求援的想法，但我们现在没有别的选择。', `FemaleText_loc5`='我不喜歡這個向艾澤拉斯求援的主意，但我別無選擇。', `FemaleText_loc7`='No me gusta la idea de pedir ayuda a Azeroth, pero no tenemos elección.' WHERE `ID`=14700;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n, 저는 우리 원정대의 문제로 세나리온 의회에 부담을 주는 일이 없도록 하자고 스스로 다짐했어요. 하지만, 우리 군사력은 너무 미약해요. 우리는 학자들과 초보 모험가들로 이루어진 집단일 뿐이에요.', `FemaleText_loc4`='我告诉自己不要用远征队的问题去麻烦塞纳里奥议会，$n。然而，我们的军事力量太渺小了。这主要是因为，我们大部分都是学者和探险者。', `FemaleText_loc5`='我告訴自己不能讓我們遠征隊的問題加重塞納里奧議會的負擔，$n。但是，我們的軍事力量很微小。最重要的是，我們都是學者和探險家。', `FemaleText_loc7`='Me prometí a mí misma que no haría cargar al Círculo Cenarion con los problemas de la expedición, $n. Pero nuestra fuerza militar es insignificante. Somos estudiantes y exploradores ante todo.' WHERE `ID`=14701;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하지만, 이 문제는 정말 심각하군요. 나가를 막지 못한다면 우리 원정대는 말할 것도 없고... 세나리온 의회의 대드루이드들에게 이 소식을 전해야 해요.', `FemaleText_loc4`='这件事情实在太重大了。如果远征队不能遏制纳迦的嚣张气焰，那我们的存在又有何意义？必须把这个消息传达给议会的大德鲁伊们。', `FemaleText_loc5`='但是，這太大了。如果納迦沒有被阻止下來，我們的遠征根本一點用也沒有。一定要將消息傳回去給議會的大德魯伊。', `FemaleText_loc7`='Esto es demasiado. Si no detenemos a los nagas, nuestra expedición será lo de menos. Hay que avisar a los archidruidas del Círculo.' WHERE `ID`=14702;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[PH] British가 온다! 길을 정리해라!', `MaleText_loc4`='[PH] The British are coming! Clear the roads!', `MaleText_loc5`='[PH]英國人來了!清理路面!', `MaleText_loc7`='[PH] ¡Vienen los británicos! ¡Despejad los caminos!', `FemaleText_loc1`='[PH] British가 온다! 길을 정리해라!', `FemaleText_loc4`='[PH] The British are coming! Clear the roads!', `FemaleText_loc5`='[PH]英國人來了!清理路面!', `FemaleText_loc7`='[PH] ¡Vienen los británicos! ¡Despejad los caminos!' WHERE `ID`=14703;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='최대한 저들의 공격을 버터 내야 합니다! 계속 싸워주십시오!', `FemaleText_loc4`='我们必须继续守住这里，越久越好！战斗到底！', `FemaleText_loc5`='我們一定要盡力繼續撐下去!繼續奮鬥!', `FemaleText_loc7`='¡Debemos seguir resistiendo todo lo que podamos! ¡Seguid luchando!' WHERE `ID`=14704;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 고통스러워 울부짖습니다.', `MaleText_loc4`='%s痛苦地咆哮着。', `MaleText_loc5`='%s痛苦地怒吼。', `MaleText_loc7`='%s ruge de dolor.', `FemaleText_loc1`='%s|1이;가; 고통스러워 울부짖습니다.', `FemaleText_loc4`='%s痛苦地咆哮着。', `FemaleText_loc5`='%s痛苦地怒吼。', `FemaleText_loc7`='%s ruge de dolor.' WHERE `ID`=14705;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그대가 그늘늪 호수에서 설명한 구조물과 똑같이 생겼군요. 그러니까 이것이 장가르 습지대의 모든 호수에서 나가가 물을 퍼올리고 있다는 뜻일까요?', `FemaleText_loc4`='这与你所描述的暗泽湖中的建筑完全一样。是不是意味着纳迦们在抽取赞加沼泽的所有湖泊里面的水？', `FemaleText_loc5`='那就像你描述在昂布拉凡湖的建築一樣。這表示納迦正在抽取贊格沼澤所有湖泊的水嗎?', `FemaleText_loc7`='Es igual que la estructura que describiste del lago Umbropantano. ¿Significa eso que los nagas están bombeando el agua de todos los lagos de la Marisma de Zangar?' WHERE `ID`=14706;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분부대로 따르겠습니다, 주인님!', `MaleText_loc4`='遵命，主人！', `MaleText_loc5`='聽你差遣，主人!', `MaleText_loc7`='¡A sus órdenes, maestro!', `FemaleText_loc1`='분부대로 따르겠습니다, 주인님!', `FemaleText_loc4`='遵命，主人！', `FemaleText_loc5`='聽你差遣，主人!', `FemaleText_loc7`='¡A sus órdenes, maestro!' WHERE `ID`=14707;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 알겠습니다!', `MaleText_loc4`='如你所愿！', `MaleText_loc5`='如你所願!', `MaleText_loc7`='¡Como desees!', `FemaleText_loc1`='잘 알겠습니다!', `FemaleText_loc4`='如你所愿！', `FemaleText_loc5`='如你所願!', `FemaleText_loc7`='¡Como desees!' WHERE `ID`=14708;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='태양매 정찰대 만세!', `MaleText_loc4`='为了炎鹰部队！', `MaleText_loc5`='為了太陽之鷹!', `MaleText_loc7`='¡Por los Halcones del Sol!', `FemaleText_loc1`='태양매 정찰대 만세!', `FemaleText_loc4`='为了炎鹰部队！', `FemaleText_loc5`='為了太陽之鷹!', `FemaleText_loc7`='¡Por los Halcones del Sol!' WHERE `ID`=14709;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들을 해치우자!', `MaleText_loc4`='消灭他们！', `MaleText_loc5`='讓我們殺光他們!', `MaleText_loc7`='¡Déjanos matarlos!', `FemaleText_loc1`='놈들을 해치우자!', `FemaleText_loc4`='消灭他们！', `FemaleText_loc5`='讓我們殺光他們!', `FemaleText_loc7`='¡Déjanos matarlos!' WHERE `ID`=14710;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='캘타스 만세!', `MaleText_loc4`='为了凯尔萨斯！', `MaleText_loc5`='為了凱爾薩斯!', `MaleText_loc7`='¡Por Kael!', `FemaleText_loc1`='캘타스 만세!', `FemaleText_loc4`='为了凯尔萨斯！', `FemaleText_loc5`='為了凱爾薩斯!', `FemaleText_loc7`='¡Por Kael!' WHERE `ID`=14711;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나가들이 그들의 호수에서조차 물을 퍼내고 있어요! 대체 저들의 목적이 무엇일까요?', `FemaleText_loc4`='纳迦们甚至在抽干他们自己湖里的水。他们到底有什么企图？', `FemaleText_loc5`='納迦甚至還將他們湖裡的水都抽出來!他們究竟有什麼樣的企圖?', `FemaleText_loc7`='¡Los nagas están sacando el agua de su propio lago! ¿Con qué fin pueden estar haciéndolo?' WHERE `ID`=14712;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저기 보세요! 모든 파이프가 저 구조물과 연결된 것 같군요. 놈들이 그동안 훔친 물의 양이 저 정도밖에 안 될 리가 없습니다. 나머지 물을 어디에 저장해 둔 걸까요?', `FemaleText_loc4`='看！那些管道似乎都连接着那座建筑，但是那里面不可能存放所有他们偷来的水。他们究竟把水储存在哪里呢？', `FemaleText_loc5`='那裡!那些導管全都連接到那棟建築。那根本不可能足夠儲藏他們偷的水。他們把水都放在哪裡?', `FemaleText_loc7`='¡Ahí! Parece que todos esos tubos están conectados a esa estructura. Es imposible que contenga toda el agua que han sacado. ¿Dónde la almacenarán?' WHERE `ID`=14713;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 죽음의 늪에서 어떤 일이 일어났는지 알겠군요. 한때 그곳에는 분명 호수가 있었을 겁니다. 나가를 막지 못하면 조만간 습지대의 전 지역이 저 꼴이 될 겁니다!', `FemaleText_loc4`='我们看到的一切都说明了在死亡泥潭曾经发生过什么，那里曾经是一片湖泊。如果我们不阻止纳迦的行动，整个沼泽很快就会变成那个样子！', `FemaleText_loc5`='我們所見解釋了死亡污泥發生的事。這裡曾有一口湖。如果我們不阻止納迦，所有的沼澤很快就會變的和這個一樣!', `FemaleText_loc7`='Lo que vimos explica lo que ocurrió en el Lodo Muerto. Antes aquí había un lago. ¡Si no detenemos a los nagas, todas las ciénagas se quedarán así!' WHERE `ID`=14714;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 형편없는 수비로군. 이게 너의 한계인가?', `MaleText_loc4`='多脆弱的防守啊。你们就这点本事？', `MaleText_loc5`='真是個可鄙的防禦。你們只有這點本事嗎?', `MaleText_loc7`='Qué defensa más pobre. ¿Es esto lo mejor que sabes hacer?' WHERE `ID`=14715;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='머릿수로 날 막아 보겠다는 수작인가? 놈들을 해치워라!', `MaleText_loc4`='还有多少条挡路狗？杀了他们，炎鹰部队！', `MaleText_loc5`='更多人擋我的路?殺了他們，太陽之鷹!', `MaleText_loc7`='¿Otra vez en mi camino? ¡Matadlos, Halcones del Sol!' WHERE `ID`=14716;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 형편없는 수비로는 날 막지 못한다.', `MaleText_loc4`='我不会被如此脆弱的防守阻止的。', `MaleText_loc5`='我不會被這樣可鄙的防禦給阻擋的。', `MaleText_loc7`='No me detendrá una defensa tan lamentable.' WHERE `ID`=14717;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 핏빛 감시초소의 파수대를 맡고 있는 지휘관입니다. 제가 도울 일이라도 있습니까?', `FemaleText_loc4`='我是秘血岗哨的防务首领，有什么我可以帮你的吗？', `FemaleText_loc5`='我是血色守望防禦的領導者。我能幫你什麼忙嗎?', `FemaleText_loc7`='Soy la líder de la defensa de la Avanzada de Sangre. ¿En qué puedo ayudarte?' WHERE `ID`=14718;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[서투른 공용어] 너울소나무 일족 각오가 되어 있소! 정말 고맙소!', `MaleText_loc4`='[不流畅的通用语] 止松要塞准备好了！非常感谢！', `MaleText_loc5`='[操著不流利的普通語]靜松做好準備!非常感激!', `MaleText_loc7`='[En el Ágora] ¡Semprepino, prepárate! ¡Muchas gracias!' WHERE `ID`=14719;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하십니까. 핏빛안개 섬의 전쟁에 대해 알아보려고 오셨습니까?', `FemaleText_loc4`='你好，你是不是到这里来了解秘血岛事态的？', `FemaleText_loc5`='哈囉，你是來這裡了解血謎的衝突嗎?', `FemaleText_loc7`='Hola, ¿estás aquí para aprender acerca del conflicto en Bruma de Sangre?' WHERE `ID`=14720;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 도울 일이라도 있습니까?', `FemaleText_loc4`='有什么我可以帮你的吗？', `FemaleText_loc5`='我能幫你嗎?', `FemaleText_loc7`='¿Puedo ayudarte?' WHERE `ID`=14721;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리는 추호의 의심도 없이 빛을 위해 봉사합니다. 우리의 목적에 대해 좀 더 알고 싶지 않습니까?', `FemaleText_loc4`='我们无条件地为圣光效劳，也许你可能会对我们的目的感到好奇？', `FemaleText_loc5`='我們毫無異議地為聖光效命。或許你對我們的目的還是有一點好奇?', `FemaleText_loc7`='Servimos a la luz incondicionalmente. ¿Quizás tengas algo más de curiosidad sobre nuestro fin?' WHERE `ID`=14722;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파수대에 대해 말씀해 주십시오.', `MaleText_loc4`='告诉我关于防御者的事情吧。', `MaleText_loc5`='告訴我關於防衛者的事。', `MaleText_loc7`='Háblame de los Defensores.', `FemaleText_loc1`='파수대에 대해 말씀해 주십시오.', `FemaleText_loc4`='告诉我关于防御者的事情吧。', `FemaleText_loc5`='告訴我關於防衛者的事。', `FemaleText_loc7`='Háblame de los Defensores.' WHERE `ID`=14723;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='길은 안전한가요? 나갈 수 있을 때 어서 가요, $n 님.', `FemaleText_loc4`='前面安全吗？让我们离开这里吧，$n。', `FemaleText_loc5`='路途清空了嗎?等我們可以的時候就逃出這裡，$n。', `FemaleText_loc7`='¿Está despejado el camino? Salgamos mientras podamos, $n.' WHERE `ID`=14724;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='음... 빠져나가는 게 쉽지 않을 것 같군요. 자, 빠져나갈 준비를 하세요!', `FemaleText_loc4`='看起来没那么容易逃脱。做好准备！', `FemaleText_loc5`='看來我們沒辦法那麼輕易逃走。做好準備!', `FemaleText_loc7`='Parece que no escaparemos tan fácilmente. ¡Preparaos!' WHERE `ID`=14725;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기는 안전하지 못하니 계속 움직여야 해요!', `FemaleText_loc4`='继续前进吧，这里并不安全！', `FemaleText_loc5`='繼續前進。我們在這裡不安全!', `FemaleText_loc7`='Prosigamos. ¡Aquí no estamos seguros!' WHERE `ID`=14726;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='조심하세요, $n! 전방에 적이 나타났어요!', `FemaleText_loc4`='小心，$n！敌人就在前面！', `FemaleText_loc5`='小心，$n!前方有敵人!', `FemaleText_loc7`='¡Cuidado, $n! ¡Enemigos al frente!' WHERE `ID`=14727;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='야영지에 거의 도착했군요! 어서 가요.', `FemaleText_loc4`='我们快到庇护所了！加油。', `FemaleText_loc5`='我們就快到避難所了!走吧。', `FemaleText_loc7`='¡Casi hemos llegado al refugio! Vamos.' WHERE `ID`=14728;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오, 그리운 제 드루이드 동료가 보이는군요. 고맙습니다, $n 님. 이시엘이 틀림없이 당신에게 보답할 겁니다!', `FemaleText_loc4`='我已经可以看到我的德鲁伊同伴了。感谢你，$n。我相信伊谢尔会奖励你的。', `FemaleText_loc5`='從這裡我可以看到我的德魯伊同伴們。謝謝你，$n。我相信伊斯歐會獎勵你的行為!', `FemaleText_loc7`='Desde aquí veo a mis compañeros druidas. Gracias, $n. ¡Estoy segura de que Ysiel te recompensará por tus acciones!' WHERE `ID`=14729;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쿠엘탈라스의 수호자이자, 캘타스 왕자의 충실한 종, 그리고 성스러운 빛의 진정한 주인인 혈기사의 본부에 오신 것을 진심으로 환영하오.', `MaleText_loc4`='欢迎来到血骑士的总部，我们是奎尔萨拉斯的防御者，银月城的忠实仆从，圣光的真正主人。', `MaleText_loc5`='歡迎來到奎爾薩拉斯的防衛者，血騎士的總部，我們是銀月忠誠的僕人，也是聖光真正的主人。', `MaleText_loc7`='$gBienvenido:Bienvenida; al puesto de mando de los Caballeros de sangre, defensores de Quel''Thalas, fieles siervos de Lunargenta y verdaderos maestros de la Luz.' WHERE `ID`=14730;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리한테서 벗어날 수 없다, 드루이드!', `MaleText_loc4`='德鲁伊，你别想从我们手中逃走！', `MaleText_loc5`='你逃不出我們手掌心的，德魯伊!', `MaleText_loc7`='¡No huirás de nosotros, druida!' WHERE `ID`=14731;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇지. 저 녀석들의 피가 더 많이 흐르게 하라! 그러면 나는 이곳에 강림할 수 있다!', `MaleText_loc4`='是的……让他们的血再多溅出一点！这样我就更接近了！', `MaleText_loc5`='很好..潑灑更多他們的鮮血!這讓我和這個地方更靠近!', `MaleText_loc7`='Sí..., ¡derrama más sangre suya! ¡Me acerca a ese lugar!' WHERE `ID`=14732;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더! 놈들의 피를 더 많이 쏟아라! 거의 다 됐다!', `MaleText_loc4`='再多点！再多点血！我已经很近了！', `MaleText_loc5`='再來!潑灑更多他們的鮮血!我就快成功了!', `MaleText_loc7`='¡Más! ¡Derrama más sangre! ¡Estoy cerca!' WHERE `ID`=14733;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래! 좀 더! 조만간 나는 자유의 몸이 될 것이다!', `MaleText_loc4`='对！再多点！我马上就可以获得解脱了！', `MaleText_loc5`='很好!再來!我很快就會被釋放了!', `MaleText_loc7`='¡Sí! ¡Más! ¡Pronto seré liberado!' WHERE `ID`=14734;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번에는 너로 인해 실패했지만 우리는 다시 돌아올 것이다...', `MaleText_loc4`='你暂时阻碍了我们，但是我们会回来的……', `MaleText_loc5`='你現在阻撓了我們，但我們還會再回來的...', `MaleText_loc7`='Por ahora has frustrado nuestros planes, pero volveremos...' WHERE `ID`=14735;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오십시오, $n!', `MaleText_loc4`='欢迎回来，$n！', `MaleText_loc5`='歡迎回來，$n!', `MaleText_loc7`='¡$gBienvenido:Bienvenida; de nuevo, $n!', `FemaleText_loc1`='어서 오십시오, $n!', `FemaleText_loc4`='欢迎回来，$n！', `FemaleText_loc5`='歡迎回來，$n!', `FemaleText_loc7`='¡$gBienvenido:Bienvenida; de nuevo, $n!' WHERE `ID`=14736;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희를 찾아주시다니 정말 영광입니다, $n.', `MaleText_loc4`='能和你在一起，我们感到很荣幸，$n。', `MaleText_loc5`='你的出現讓我們感到很榮幸，$n。', `MaleText_loc7`='Nos honras con tu presencia, $n.', `FemaleText_loc1`='저희를 찾아주시다니 정말 영광입니다, $n.', `FemaleText_loc4`='能和你在一起，我们感到很荣幸，$n。', `FemaleText_loc5`='你的出現讓我們感到很榮幸，$n。', `FemaleText_loc7`='Nos honras con tu presencia, $n.' WHERE `ID`=14737;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자연은 자연의 비밀을 배우려는 이들에게 친절을 베푼다, $c|1이여;여;.', `MaleText_loc4`='大自然喜欢那些希望去了解它的秘密的人，$n。', `MaleText_loc5`='大自然會幫助那些願意了解它的奧妙的人，$n。', `MaleText_loc7`='La naturaleza favorece a aquellos que están dispuestos a conocer sus secretos, $n.' WHERE `ID`=14738;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제게 당신의 표식을 주십시오, 지혜로운 고대인이시여.', `MaleText_loc4`='赐予我你的印记吧，睿智的古树。', `MaleText_loc5`='請授予我你的印記，睿智的長者。', `MaleText_loc7`='Otórgame tu marca, sabio ancestro.', `FemaleText_loc1`='제게 당신의 표식을 주십시오, 지혜로운 고대인이시여.', `FemaleText_loc4`='赐予我你的印记吧，睿智的古树。', `FemaleText_loc5`='請授予我你的印記，睿智的長者。', `FemaleText_loc7`='Otórgame tu marca, sabio ancestro.' WHERE `ID`=14739;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$r|1이여;여;, 자연은 강력한 힘이 있다. 그리하여 자연을 정복하려 하는 자는 결코 성공할 수 없는 것이니라.', `MaleText_loc4`='自然是一种强大的力量，$r。那些尝试征服它的人从来没有成功过。', `MaleText_loc5`='自然是一種強大的力量，$r。那些想制服大自然的人從未永久成功過。', `MaleText_loc7`='La naturaleza es una fuerza poderosa, $r. Aquellos que intentan dominarla nunca lo consiguen de modo permanente.' WHERE `ID`=14740;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제게 당신의 표식을 주십시오, 강인한 고대인이시여.', `MaleText_loc4`='赐予我你的印记吧，强大的古树。', `MaleText_loc5`='請授予我你的印記，萬能的長者。', `MaleText_loc7`='Otórgame tu marca, poderoso ancestro.', `FemaleText_loc1`='제게 당신의 표식을 주십시오, 강인한 고대인이시여.', `FemaleText_loc4`='赐予我你的印记吧，强大的古树。', `FemaleText_loc5`='請授予我你的印記，萬能的長者。', `FemaleText_loc7`='Otórgame tu marca, poderoso ancestro.' WHERE `ID`=14741;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대장님! 만아리의 흉물이 서쪽에 소환되었다는 보고가 들어왔습니다. 당장 파수대를 배치해서 핏빛 감시초소로 진입하는 길을 차단하겠습니다.', `FemaleText_loc4`='长官！我们收到报告说，一个艾瑞达堕落者在西面被召唤了出来。我会派遣防御部队在通往秘血岗哨的路上拦截他。', `FemaleText_loc5`='長官!我們獲報表示西方有曼那瑞·憎惡的形體被召喚出來。我已部署防衛者截擊通往血色守望的路徑。', `FemaleText_loc7`='¡Señor! Nos informan de que están invocando abominaciones Man''ari al oeste. Estoy desplegando a los defensores en el camino hacia la Avanzada de Sangre.' WHERE `ID`=14742;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성스러운 빛이 당신을 보호하기를. 이제 출발하십시오!', `MaleText_loc4`='愿圣光保佑你。去吧！', `MaleText_loc5`='願聖光保護你。現在，走吧!', `MaleText_loc7`='Que la Luz te proteja. ¡Vete!' WHERE `ID`=14743;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주위에 있는 모든 대상에게 상급 약화 마법을 시전하십시오.', `MaleText_loc4`='请为附近所有的目标施放高级的减效法术。', `MaleText_loc5`='請對附近所有目標施展高優先權的減益法術。', `MaleText_loc7`='Lanza un hechizo de PERJUICIO de alta prioridad sobre todos los objetivos cercanos.', `FemaleText_loc1`='주위에 있는 모든 대상에게 상급 약화 마법을 시전하십시오.', `FemaleText_loc4`='请为附近所有的目标施放高级的减效法术。', `FemaleText_loc5`='請對附近所有目標施展高優先權的減益法術。', `FemaleText_loc7`='Lanza un hechizo de PERJUICIO de alta prioridad sobre todos los objetivos cercanos.' WHERE `ID`=14744;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주위에 있는 모든 대상에게 상급 강화 마법을 시전하십시오.', `MaleText_loc4`='请为附近所有的目标施放高级的增益法术。', `MaleText_loc5`='請對附近所有目標施展高優先權的增益法術。', `MaleText_loc7`='Lanza un hechizo de VENTAJA de alta prioridad sobre todos los objetivos cercanos.', `FemaleText_loc1`='주위에 있는 모든 대상에게 상급 강화 마법을 시전하십시오.', `FemaleText_loc4`='请为附近所有的目标施放高级的增益法术。', `FemaleText_loc5`='請對附近所有目標施展高優先權的增益法術。', `FemaleText_loc7`='Lanza un hechizo de VENTAJA de alta prioridad sobre todos los objetivos cercanos.' WHERE `ID`=14745;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='북부관문 경비탑에 지원이 필요하다! 다시 한번 진군하여 우리 군주님을 기쁘게 해드리자!', `MaleText_loc4`='北地哨塔需要我们的支援！冲啊！', `MaleText_loc5`='北地哨塔需要我們的協助!讓我們再一次衝鋒陷陣，展現傲氣和忠誠!', `MaleText_loc7`='La Torre del Paso Norte necesita tu asistencia. Debemos controlarla y ser el orgullo de nuestra estirpe.' WHERE `ID`=14746;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알론서스 교회를 지키는 데 성공한 %s의 영혼이 안식으로 돌아갑니다.', `MaleText_loc4`='成功地守卫了阿隆索斯礼拜堂之后，%s的灵魂恢复了它的宁静。', `MaleText_loc5`='成功防禦了阿隆索斯教堂後，%s的靈魂恢復平靜。', `MaleText_loc7`='Tras haber defendido con éxito la Capilla de Alonsus, el espíritu de %s vuelve a su descanso.', `FemaleText_loc1`='알론서스 교회를 지키는 데 성공한 %s의 영혼이 안식으로 돌아갑니다.', `FemaleText_loc4`='成功地守卫了阿隆索斯礼拜堂之后，%s的灵魂恢复了它的宁静。', `FemaleText_loc5`='成功防禦了阿隆索斯教堂後，%s的靈魂恢復平靜。', `FemaleText_loc7`='Tras haber defendido con éxito la Capilla de Alonsus, el espíritu de %s vuelve a su descanso.' WHERE `ID`=14747;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와투순처럼 조용한 물이 형태를 갖춥니다.', `MaleText_loc4`='瓦图苏的现身使水流恢复了平静。', `MaleText_loc5`='水面隨著瓦吐森成形而平靜下來。', `MaleText_loc7`='Las aguas se calman cuando Watoosun se materializa.' WHERE `ID`=14748;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고대의 정령이여, 당신은 대지 고리회의 영광입니다. 무슨 문제로 그렇게 괴로워하십니까?', `MaleText_loc4`='远古的灵魂，大地之环为你感到骄傲。你有什么麻烦吗？', `MaleText_loc5`='古老的靈魂，你尊敬陶土議會。什麼事讓你如此煩心?', `MaleText_loc7`='Espíritu anciano, honras al Anillo de la Tierra. ¿Qué te preocupa tanto?' WHERE `ID`=14749;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대의 형제들이 내 아이들을 해치려 하고 있다. 스스로 바람갈대 일족이라고 부르는 이들이 이 땅을 파괴하고 있다. 이곳이 늪지대로 변해서는 아니된다...', `MaleText_loc4`='你的同胞想要伤害我的孩子。那些自称风茅什么的家伙把大地弄得乌烟瘴气，我们绝不能让这里成为沼泽地……', `MaleText_loc5`='你的同胞想傷害我的孩子。那些自稱為風蘆的人破壞了這塊土地。這裡再也不會成為一塊濕地...', `MaleText_loc7`='Parece que tus hermanos hacen daño a mis hijos. Aquellos que se hacen llamar Junco Alabeado trastornan la tierra. Esto no se convertirá en un pantano...' WHERE `ID`=14750;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 힘을 모으겠습니다. 정령들에 대한 모독 행위가 계속되도록 내버려두지 않겠습니다.', `MaleText_loc4`='我们的力量将被聚集。我们不会允许亵渎再继续下去。', `MaleText_loc5`='我們的力量會被集中。我們不會讓褻瀆行為持續下去。', `MaleText_loc7`='Concentraremos nuestro poder. No permitiré que continúe esta profanación.' WHERE `ID`=14751;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음을 맞이할 시간이 왔다, 보로스!', `MaleText_loc4`='波鲁斯，你的死期到了！', `MaleText_loc5`='你的死期已到，波羅斯!', `MaleText_loc7`='¡Se acerca tu muerte, Boros!' WHERE `ID`=14752;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 예전의 애송이가 아니다, 만아리! 정의의 이름으로 당신의 고통을 끝내 주마!', `MaleText_loc4`='我们不是以前那些年轻而弱小的人了，艾瑞达堕落者！以圣光的名义，我们会终结你的痛苦！', `MaleText_loc5`='我們已不是從前的年輕人了，曼那瑞!以聖光之名，我們要結束你的苦難!', `MaleText_loc7`='¡Ya no somos los jovenzuelos de antaño, Man''ari! ¡Por la luz que acabaremos con tu sufrimiento!' WHERE `ID`=14753;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정의의 이름으로! 녀석들이 도대체 당신에게 무슨 짓을 한 것이지?', `MaleText_loc4`='以圣光的名义！他们对你做了什么？', `MaleText_loc5`='以聖光之名!他們對你做了什麼?', `MaleText_loc7`='¡Por la luz! ¿Qué te han hecho?' WHERE `ID`=14754;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 고통은 끝입니다!', `MaleText_loc4`='让我们做个了结吧！', `MaleText_loc5`='我們現在就將它結束!', `MaleText_loc7`='¡Acabamos con esto ahora!' WHERE `ID`=14755;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 사악한 표정으로 히죽거립니다.', `MaleText_loc4`='%s坏笑着。', `MaleText_loc5`='%s不懷好意地露齒而笑。', `MaleText_loc7`='%s sonríe maliciosamente.' WHERE `ID`=14756;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하십니까, $n 님.', `FemaleText_loc4`='你好，$n。', `FemaleText_loc5`='你好，$n。', `FemaleText_loc7`='Saludos, $n.' WHERE `ID`=14757;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정령들의 상태가 불안정합니다. 정령들의 분노에 잠식당하지 않으려면 나그란드에 있는 동안 주변을 조심하십시오.', `MaleText_loc4`='这些灵魂在躁动，$r。在纳格兰游历的时候留心你的周围，以免你被他们的愤怒吞噬。', `MaleText_loc5`='靈魂很不安，$r。在納葛蘭要小心你的四周，免得被他們的憤怒給吞噬了。', `MaleText_loc7`='Los espíritus están agitados, $r. Debes estar vigilante de tus alrededores mientras estés en Nagrand, no sea que su furia te consuma.' WHERE `ID`=14758;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대지 고리회는 정령들의 힘과 위엄을 지키고자 노력하고 있습니다.', `MaleText_loc4`='大地之环会设法维护元素们的权威和力量。', `MaleText_loc5`='陶土議會想要保存元素的力量和莊嚴。', `MaleText_loc7`='El Anillo de la Tierra intenta conservar la fuerza y majestuosidad de los elementos.' WHERE `ID`=14759;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정령들이 그렇게 불안해해서야 제 동족이 어떻게 마음 놓고 싸우겠습니까? 정령들의 도움이 없으면 이 세계가 존재할 수 없다는 사실을 그들은 모르는가 봅니다.', `FemaleText_loc4`='在元素们陷入混乱的时刻，我们的人民怎么能战斗？难道他们不知道这个世界完全无法脱离元素的支持而存在？', `FemaleText_loc5`='元素這樣混亂要我的人民怎麼作戰?他們難道看不出來沒有元素的支持這世界無法生存嗎。', `FemaleText_loc7`='¿Cómo puede mi pueblo luchar cuando los elementos están en una confusión tal? No ven, que, sin el apoyo de los elementos, el mundo simplemente no puede ser.' WHERE `ID`=14760;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 대지 고리회의 운트라그라고 하오. 정령의 옥좌에서 지내는 동안 정령들을 자극하지 마시오.', `MaleText_loc4`='我是大地之环的温塔格。当你在元素王座逗留时，请尽量不要去打扰元素们。', `MaleText_loc5`='我是陶土議會的安崔哥。在元素王座的時候試著不要激怒元素。', `MaleText_loc7`='Soy Untrag del Anillo de la Tierra. Intenta no ofender a los elementos mientras permanezcas en el Trono de los Elementos.' WHERE `ID`=14761;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈이 접근한다! 방어 준비!', `MaleText_loc4`='有东西靠近了！准备作战！', `MaleText_loc5`='怪物來了!做好武裝!', `MaleText_loc7`='¡La criatura ssse acerca! ¡Alarma!' WHERE `ID`=14762;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 죄송합니다. 순간 그대를 근성이 있는 다른 이들과 착각했습니다. 가던 길이나 가십시오. 훈련받지 않은 자는 우리의 비밀을 알 수 없습니다.', `MaleText_loc4`='抱歉，$c。我把你错认成个有骨气的人。滚开，我们的秘密不是那些没经过训练的家伙有资格知道的。', `MaleText_loc5`='我道歉，$c。我以為你是個有骨氣的人。你走吧;我們的秘密不告訴不牢靠的人。', `MaleText_loc7`='Lo lamento, $c. Te confundí con alguien con agallas. Vete; nuestros secretos no son para oídos inexpertos.', `FemaleText_loc1`='$c|1이여;여;, 죄송합니다. 순간 그대를 근성이 있는 다른 이들과 착각했습니다. 가던 길이나 가십시오. 훈련받지 않은 자는 우리의 비밀을 알 수 없습니다.', `FemaleText_loc4`='抱歉，$c。我把你错认成个有骨气的人。滚开，我们的秘密不是那些没经过训练的家伙有资格知道的。', `FemaleText_loc5`='我道歉，$c。我以為你是個有骨氣的人。你走吧;我們的秘密不告訴不牢靠的人。', `FemaleText_loc7`='Lo lamento, $c. Te confundí con alguien con agallas. Vete; nuestros secretos no son para oídos inexpertos.' WHERE `ID`=14763;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 손으로 죽여주마!', `MaleText_loc4`='准备毁灭在我手上吧！', `MaleText_loc5`='準備在我手中死去吧!', `MaleText_loc7`='¡Prepárate para morir entre misss manosss!' WHERE `ID`=14764;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 지금은 설교할 시간이 없습니다. 다른 곳에 가서 훈련을 받으십시오.', `MaleText_loc4`='我现在没有时间来说教，$c。到别的地方去寻找你的知识吧。', `MaleText_loc5`='我現在沒空說教，$c。去別的地方尋找你的知識。', `MaleText_loc7`='No tengo tiempo para sermones ahora, $c. Busca tus conocimientos en otra parte.', `FemaleText_loc1`='$c|1이여;여;, 지금은 설교할 시간이 없군요. 다른 곳에 가서 훈련을 받으세요.', `FemaleText_loc4`='我现在没有时间来说教，$c。到别的地方去寻找你的知识吧。', `FemaleText_loc5`='我現在沒空說教，$c。去別的地方尋找你的知識。', `FemaleText_loc7`='No tengo tiempo para sermones ahora, $c. Busca tus conocimientos en otra parte.' WHERE `ID`=14765;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 잘못 찾아오신 것 같군요.', `MaleText_loc4`='看来你走错方向了，$c。', `MaleText_loc5`='看來你做了錯誤的選擇，$c。', `MaleText_loc7`='Parece que te equivocaste, $c.', `FemaleText_loc1`='$c|1이여;여;, 잘못 찾아오신 것 같군요.', `FemaleText_loc4`='看来你走错方向了，$c。', `FemaleText_loc5`='看來你做了錯誤的選擇，$c。', `FemaleText_loc7`='Parece que te equivocaste, $c.' WHERE `ID`=14766;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, $n 님. 여기까지 오면서 미행을 당하지는 않으셨겠죠?', `MaleText_loc4`='你好，$n。我希望你不是被跟踪到这里的？', `MaleText_loc5`='你好，$n。你沒被人跟來吧，我能信任你嗎?', `MaleText_loc7`='Saludos, $n. Confío en que no te hayan seguido hasta aquí.', `FemaleText_loc1`='안녕하십니까, $n 님. 여기까지 오면서 미행을 당하지는 않으셨겠죠?', `FemaleText_loc4`='你好，$n。我希望你不是被跟踪到这里的？', `FemaleText_loc5`='你好，$n。你沒被人跟來吧，我能信任你嗎?', `FemaleText_loc7`='Saludos, $n. Confío en que no te hayan seguido hasta aquí.' WHERE `ID`=14767;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대 같은 $c|1과는;와는; 할 말이 없습니다. 마음이 맞는 이들을 다시 한번 찾아보십시오.', `MaleText_loc4`='我们没什么可谈的，$c。也许你应该去找和你志趣相投的人。', `MaleText_loc5`='我們沒什麼好談的，$c。或許你該去找別人，和你比較志趣相投的人。', `MaleText_loc7`='No tenemos mucho de qué hablar, $c. Quizás deberías buscar a otros individuos de ideas más similares.', `FemaleText_loc1`='그대 같은 $c|1과는;와는; 할 말이 없습니다. 마음이 맞는 이들을 다시 한번 찾아보십시오.', `FemaleText_loc4`='我们没什么可谈的，$c。也许你应该去找和你志趣相投的人。', `FemaleText_loc5`='我們沒什麼好談的，$c。或許你該去找別人，和你比較志趣相投的人。', `FemaleText_loc7`='No tenemos mucho de qué hablar, $c. Quizás deberías buscar a otros individuos de ideas más similares.' WHERE `ID`=14768;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 근처에서 제정신이 박힌 이를 만난다는 것은 참 반가운 일입니다. 무엇을 도와드릴까요?', `MaleText_loc4`='我很高兴看到有个心智健全的$r在这里。有什么我可以帮你的吗？', `MaleText_loc5`='看到這裡有人神智清楚真好。有什麼我能幫忙的嗎?', `MaleText_loc7`='Es un placer ver a alguien cuerdo por aquí. ¿En qué puedo ayudarte?', `FemaleText_loc1`='이 근처에서 제정신이 박힌 이를 만난다는 것은 참 반가운 일입니다. 무엇을 도와드릴까요?', `FemaleText_loc4`='我很高兴看到有个心智健全的$r在这里。有什么我可以帮你的吗？', `FemaleText_loc5`='看到這裡有人神智清楚真好。有什麼我能幫忙的嗎?', `FemaleText_loc7`='Es un placer ver a alguien cuerdo por aquí. ¿En qué puedo ayudarte?' WHERE `ID`=14769;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 저와 같은 순찰대 소속이로군요. 무슨 일이십니까?', `MaleText_loc4`='啊，一个猎人伙伴。你需要什么？', `MaleText_loc5`='啊，一個遊俠夥伴。你需要什麼?', `MaleText_loc7`='Ah, compañero forestal. ¿Qué necesitas?', `FemaleText_loc1`='아, 저와 같은 순찰대 소속이로군요. 무슨 일이십니까?', `FemaleText_loc4`='啊，一个猎人伙伴。你需要什么？', `FemaleText_loc5`='啊，一個遊俠夥伴。你需要什麼?', `FemaleText_loc7`='Ah, compañero forestal. ¿Qué necesitas?' WHERE `ID`=14770;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 그대는 복잡한 비전 마법을 이해할 능력이 부족합니다. 어서 가던 길이나 가십시오.', `MaleText_loc4`='很明显你缺乏控制复杂的奥术能量所必需的能力，$c。闪开点。', `MaleText_loc5`='你明顯地缺乏能力掌握秘法繁複難懂的細節，$c。你走吧。', `MaleText_loc7`='Evidentemente careces de la capacidad para comprender las complejidades de lo Arcano, $c. Largo.', `FemaleText_loc1`='$c|1이여;여;, 그대는 복잡한 비전 마법을 이해할 능력이 부족하군요. 어서 가던 길이나 가세요.', `FemaleText_loc4`='很明显你缺乏控制复杂的奥术能量所必需的能力，$c。闪开点。', `FemaleText_loc5`='你明顯地缺乏能力掌握秘法繁複難懂的細節，$c。你走吧。', `FemaleText_loc7`='Evidentemente careces de la capacidad para comprender las complejidades de lo Arcano, $c. Largo.' WHERE `ID`=14771;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대의 연구에 어떤 도움을 드릴까요?', `MaleText_loc4`='有什么我可以帮你的吗？', `MaleText_loc5`='我能為你的研究提供什麼協助?', `MaleText_loc7`='¿Qué ayuda te puedo brindar en tus estudios?', `FemaleText_loc1`='그대의 연구에 어떤 도움을 드릴까요?', `FemaleText_loc4`='有什么我可以帮你的吗？', `FemaleText_loc5`='我能為你的研究提供什麼協助?', `FemaleText_loc7`='¿Qué ayuda te puedo brindar en tus estudios?' WHERE `ID`=14772;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 가는 길은 강철 같은 의지와 확고한 믿음을 가진 자만이 통과할 수 있소. $c|1이여;여;, 그대에게는 둘 중 어느 것도 보이지 않소.', `MaleText_loc4`='我们只接受那些拥有钢铁般坚定的意志、怀着永不动摇的决心的同伴。似乎这两样优点你都不具备，$C。', `MaleText_loc5`='我們的道路是給那些有鋼鐵意志和堅定決心的人走的。你看起來並不擁有這些特質，$c。', `MaleText_loc7`='El nuestro es un camino para aquellos con voluntad férrea y determinación firme. No pareces poseer ninguno de estos rasgos, $c.', `FemaleText_loc1`='우리가 가는 길은 강철 같은 의지와 확고한 믿음을 가진 자만이 통과할 수 있습니다. $c|1이여;여;, 그대에게는 둘 중 어느 것도 보이지 않네요.', `FemaleText_loc4`='我们只接受那些拥有钢铁般坚定的意志、怀着永不动摇的决心的同伴。似乎这两样优点你都不具备，$C。', `FemaleText_loc5`='我們的道路是給那些有鋼鐵意志和堅定決心的人走的。你看起來並不擁有這些特質，$c。', `FemaleText_loc7`='El nuestro es un camino para aquellos con voluntad férrea y determinación firme. No pareces poseer ninguno de estos rasgos, $c.' WHERE `ID`=14773;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가르침을 더 구하고자 하시오, $n?', `MaleText_loc4`='你是来寻求进一步的指导的吗，$n？', `MaleText_loc5`='你想獲得更多的指示嗎，$n?', `MaleText_loc7`='¿Buscas más instrucción, $n?', `FemaleText_loc1`='가르침을 더 구하고자 하시나요, $n 님?', `FemaleText_loc4`='你是来寻求进一步的指导的吗，$n？', `FemaleText_loc5`='你想獲得更多的指示嗎，$n?', `FemaleText_loc7`='¿Buscas más instrucción, $n?' WHERE `ID`=14774;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 땅은 추락 사건으로 인해 황폐화되었습니다. 그대는 우리 드루이드의 철학을 따르지 않을 수도 있기에 그대의 치료 과정에 도움이 되는 모든 방법을 사용해 달라고 부탁 드리는 바입니다.', `MaleText_loc4`='这片土地被坠毁搞得一团糟。虽然你也许并不认同我们的哲学，$c，但是我期盼你尽量帮助别人。', `MaleText_loc5`='這塊土地已遭墜毀摧殘。雖然你不懂我們的人生觀，$c，我還是鼓勵你盡所能的協助治療程序。', `MaleText_loc7`='Esta tierra ha sido arrasada por el accidente. Aunque no compartas nuestra filosofía, $c, te ruego que hagas todo lo que puedas para curarla.', `FemaleText_loc1`='이 땅은 추락 사건으로 인해 황폐화되었습니다. 그대는 우리 드루이드의 철학을 따르지 않을 수도 있기에 그대의 치료 과정에 도움이 되는 모든 방법을 사용해 달라고 부탁 드리는 바입니다.', `FemaleText_loc4`='这片土地被坠毁搞得一团糟。虽然你也许并不认同我们的哲学，$c，但是我期盼你尽量帮助别人。', `FemaleText_loc5`='這塊土地已遭墜毀摧殘。雖然你不懂我們的人生觀，$c，我還是鼓勵你盡所能的協助治療程序。', `FemaleText_loc7`='Esta tierra ha sido arrasada por el accidente. Aunque no compartas nuestra filosofía, $c, te ruego que hagas todo lo que puedas para curarla.' WHERE `ID`=14775;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오십시오, 동지여. 오늘은 무엇을 도와드릴까요?', `MaleText_loc4`='你好，我的$g兄弟:姐妹;。今天你需要怎样的指引呢？', `MaleText_loc5`='你好，我的$g兄弟:姐妹;。我能給你什麼指引?', `MaleText_loc7`='Saludos, $ghermano:hermana;. ¿En qué puedo guiarte hoy?', `FemaleText_loc1`='어서 오십시오, 동지여. 오늘은 무엇을 도와드릴까요?', `FemaleText_loc4`='你好，我的$g兄弟:姐妹;。今天你需要怎样的指引呢？', `FemaleText_loc5`='你好，我的$g兄弟:姐妹;。我能給你什麼指引?', `FemaleText_loc7`='Saludos, $ghermano:hermana;. ¿En qué puedo guiarte hoy?' WHERE `ID`=14776;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='바람이 그대를 인도하기를, $n.', `FemaleText_loc4`='愿风指引你，$n。', `FemaleText_loc5`='願風引導你，$n。', `FemaleText_loc7`='Que los vientos te guíen, $n.' WHERE `ID`=14777;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불타라! 불타라! 불타올라라!', `MaleText_loc4`='烧吧！烧吧！烧吧！', `MaleText_loc5`='燒吧!燒吧!燒吧!', `MaleText_loc7`='¡Arde! ¡Arde! ¡Arde!' WHERE `ID`=14778;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 책은 아웃랜드의 다양한 식물 종에 대한 정보를 담고 있습니다. 대부분은 장가르 습지대의 토착 식물입니다.$B$B도표와 그림은 당신이 이해하기에 다소 어렵습니다. 아마도 책의 저자가 당신에게 조언을 줄 수 있을 것입니다.', `MaleText_loc4`='这本书包含了外域的植物种类的信息，其中大部分被详细介绍的植物产自赞加沼泽。$B$B书中的文字和图表可能有点超越你的理解能力，也许作者可以给你一些指点。', `MaleText_loc5`='這本書包含了外域植物種類的資料。大部份詳述的植物都是贊格沼澤土生土長的。$B$B書裡的圖表對你而言有點難以理解。或許作者可以給你一些指示。', `MaleText_loc7`='Este libro contiene información sobre las especies de plantas de Terrallende. La mayoría de las plantas descritas son originarias de la marisma de Zangar.$B$BLas tablas y los gráficos son algo complejos para que los comprendas. Quizás el autor pueda darte algunos consejos.' WHERE `ID`=14779;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 책은 아웃랜드의 다양한 식물 종에 대한 정보를 담고 있습니다. 대부분은 장가르 습지대의 토착 식물입니다.$B$B당신은 책 속의 도표와 그림을 이용하여 이제 다양한 식물 종을 구분할 수 있다는 자신감을 느낍니다.', `MaleText_loc4`='这本书包含了外域的植物种类的信息，其中大部分被详细介绍的植物产自赞加沼泽。$B$B你自信可以凭借书中的文字和图表来识别各种植物。', `MaleText_loc5`='這本書包含了外域植物種類的資料。大部份詳述的植物都是贊格沼澤土生土長的。$B$B你有自信你可以使用書裡的圖表來辨識不同的植物種類。', `MaleText_loc7`='Este libro contiene información sobre las especies de plantas de Terrallende. La mayoría de las plantas son originarias de la marisma de Zangar.$B$BTienes la seguridad de que podrás usar los gráficos y las tablas del libro para identificar varias especies de plantas.' WHERE `ID`=14780;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 언제나 사물을 구분하고 체계화하는 것을 좋아한답니다. 아마도 어머니를 닮아서 그런 것 같아요.', `FemaleText_loc4`='我一直喜欢有条理的事情。我想这是我母亲的遗传。', `FemaleText_loc5`='我一直都很喜歡將事物分類組織。我想是遺傳了我母親。', `FemaleText_loc7`='Siempre me ha gustado ordenar y organizar cosas. Supongo que he salido a mi madre.' WHERE `ID`=14781;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='행복은 필수적인 것입니다, 시민이여!', `MaleText_loc4`='快乐源于秩序，公民。', `MaleText_loc5`='履行義務方能享受快樂，居民。', `MaleText_loc7`='La felicidad es obligatoria, habitante.' WHERE `ID`=14782;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실버문의 법을 준수하십시오. 그렇지 않을 경우 그에 상응하는 처벌을 받게 될 것입니다.', `MaleText_loc4`='遵守银月城的法律。违法者将被消灭。', `MaleText_loc5`='遵守銀月城的法律。不照做的話就會導致結束。', `MaleText_loc7`='Obedece las leyes de Lunargenta. El no hacerlo resultará en finalización.' WHERE `ID`=14783;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강인함을 잃지 마십시오. 캘타스 님께서 - 문제 발생 - 로르테마르 님께서 그대를 힘과 영광의 세계로 인도할 겁니다!', `MaleText_loc4`='要坚强起来。凯尔萨斯——错误——洛瑟玛会指引你们走向力量和光明！', `MaleText_loc5`='堅強下去。凱爾薩斯將會 - 不對 - 洛索瑪將會帶領你們走向力量和榮耀!', `MaleText_loc7`='No desfallezcas. ¡Kael''thas, perdón, Lor''themar te conducirá hasta el poder y la gloria!' WHERE `ID`=14784;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도시의 평온함을 깨지 마십시오. 평화를 유지해야 합니다.', `MaleText_loc4`='不要破坏城市的宁静。必须维护和平。', `MaleText_loc5`='不要打擾城裡的安寧。一定要維持和平。', `MaleText_loc7`='No perturbes la serenidad de la ciudad. Se debe defender la paz.' WHERE `ID`=14785;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음... 당신네 $r 종족을 어떻게 생각해야 할지 아직은 잘 모르겠어요. 당신 종족 중 일부는 거칠고 스포어링을 보이는 대로 죽일지도 모르니까요.$B$B하지만, 당신은 선량하신 분 같네요... 겉모습은 약간 웃기게 생기기는 했지만요, 아캉캉.', `MaleText_loc4`='我不知道该怎么看待你们这些$r。你们中的一些人可能会粗暴地杀害所有他所看到的孢子人。$B$B你看起来还算友好……尽管有点可笑。我希望如此。', `MaleText_loc5`='我還不知道該對你的種族作何感想，$r。你們有些人真的很暴力，一見到孢子人就殺。$B$B你看起來很友善...還長的挺有喜感的。', `MaleText_loc7`='Todavía no sé qué pensar de tu calaña, $r. Algunos de ustedes pueden ser violentos y matar esporinos en cuanto los ven.$B$BPareces agradable... aunque quizás con un aspecto algo extraño, supongo.' WHERE `ID`=14786;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성벽 안에서는 질서를 지키십시오.', `MaleText_loc4`='维护银月城的秩序。', `MaleText_loc5`='維持這些城牆裡的秩序。', `MaleText_loc7`='Mantén el orden entre estas cuatro paredes.' WHERE `ID`=14787;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에헴헴, 스포어가르에 오신 걸 환영하오, $r|1이여;여;. 이 근처에서 당신 종족을 보는 일은 그리 흔한 일이 아니지. 하지만, 당신은 자신의 가치를 우리에게 증명해 보였으니 우리의 친구요. 이곳에서 편히 쉬시오.', `MaleText_loc4`='欢迎你来到孢子村，$r。通常在这附近看不到很多你的同类，但是你向我们证明了自己的价值。请不要拘束。', `MaleText_loc5`='歡迎你來斯博格爾，$r。我們這裡通常見不到什麼你們的族人，但你已向我們證明了你的價值。請隨意。', `MaleText_loc7`='Te doy la bienvenida a Esporaggar, $r. No solemos recibir la visita de gente como tú por aquí, pero tú nos has ayudado. Esta es tu casa.' WHERE `ID`=14788;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수렁군주가 포자 주머니를 먹어 치우고 있어요! 저들을 막아야만 해요!', `MaleText_loc4`='沼泽领主正在吞食孢子囊！必须阻止它们！', `MaleText_loc5`='泥沼領主們正在吞噬孢子囊!一定要阻止他們!', `MaleText_loc7`='¡Los señores de la marisma están devorando las bolsas de esporas! ¡Hay que detenerlos!' WHERE `ID`=14789;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 고마워요. 우리 후손들은 이제 무사할 거예요. 스포어가르에 가서 우리 동족을 만나보세요. 당신이 한 위대한 일에 대해 모두 알고 있을 테니까요.', `MaleText_loc4`='$n，你保护了我们年轻的族人。前往孢子村，跟我的同胞们碰面吧。你的美名早就在他们中流传开来了。', `MaleText_loc5`='多虧了你我們的青年們才能安全，$n。前往斯博格爾見見我的人民。他們都聽過你偉大的事蹟了。', `MaleText_loc7`='Gracias a ti, nuestros jóvenes estarán a salvo, $n. Ve a Esporaggar y visita a mi gente. Todos han oído hablar muy bien de ti.' WHERE `ID`=14790;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혈기사여, 우리 목숨은 그대의 것입니다.', `MaleText_loc4`='我们听从你的调遣，血骑士。', `MaleText_loc5`='我們的生命是你的，血騎士。', `MaleText_loc7`='Nuestras vidas son tuyas, Caballero de sangre.', `FemaleText_loc1`='혈기사여, 우리 목숨은 그대의 것입니다.', `FemaleText_loc4`='我们听从你的调遣，血骑士。', `FemaleText_loc5`='我們的生命是你的，血騎士。', `FemaleText_loc7`='Nuestras vidas son tuyas, Caballero de sangre.' WHERE `ID`=14791;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대의 힘이 우리를 강하게 만듭니다.', `MaleText_loc4`='你的力量使我们变得更加强大。', `MaleText_loc5`='你的力量讓我們都更強大。', `MaleText_loc7`='Tu poder nos fortalece a todos.', `FemaleText_loc1`='그대의 힘이 우리를 강하게 만듭니다.', `FemaleText_loc4`='你的力量使我们变得更加强大。', `FemaleText_loc5`='你的力量讓我們都更強大。', `FemaleText_loc7`='Tu poder nos fortalece a todos.' WHERE `ID`=14792;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신성한 빛조차 우리 백성의 꿋꿋한 의지를 꺾을 수는 없습니다.', `MaleText_loc4`='即使是圣光也无法与我们不屈的意志相提并论。', `MaleText_loc5`='就連聖光都比不上我們人民不服輸的意志。', `MaleText_loc7`='Incluso la Luz no es rival para la voluntad indomable de nuestro pueblo.', `FemaleText_loc1`='신성한 빛조차 우리 백성의 꿋꿋한 의지를 꺾을 수는 없습니다.', `FemaleText_loc4`='即使是圣光也无法与我们不屈的意志相提并论。', `FemaleText_loc5`='就連聖光都比不上我們人民不服輸的意志。', `FemaleText_loc7`='Incluso la Luz no es rival para la voluntad indomable de nuestro pueblo.' WHERE `ID`=14793;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='핏빛 감시초소의 파수대는 모든 위협으로부터 이 전초기지의 안전을 수호하고 있습니다.', `FemaleText_loc4`='秘血岗哨的防御者抵御着任何针对这座哨所的威胁。', `FemaleText_loc5`='血色守望的防衛者會保護這個前哨站不受任何威脅傷害。', `FemaleText_loc7`='Los defensores de Avanzada de Sangre protegerán este campamento de cualquier peligro.' WHERE `ID`=14794;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='파수대는 태양매 정찰대의 위협으로부터 핏빛 감시초소를 지키고자 여기 있는 것입니다.', `FemaleText_loc4`='防御者们在这里抵御着来自炎鹰部队的威胁。', `FemaleText_loc5`='防衛者已來到這裡保護血色守望不受太陽之鷹的威脅。', `FemaleText_loc7`='Los defensores están aquí para proteger la Avanzada de Sangre de la amenaza de Halcón del Sol.' WHERE `ID`=14795;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='최근에 우리는 강력한 힘을 가진 생물이 벡터 코일 근처에 소환되었다는 얘기를 들었습니다. 그러나 두려워하지 마십시오. 마을을 위협하는 존재가 있다면 우리는 목숨을 바쳐 마을을 지켜야 합니다.', `FemaleText_loc4`='我们最近听说有一个拥有巨大力量的生物在矢量感应器附近被召唤了出来。我们不畏惧任何威胁，我们会用自己的生命来捍卫这里！', `FemaleText_loc5`='我們最近聽說一隻具有龐大力量的生物在旋繞導航器被召喚出來。我們無所畏懼，有任何東西威脅城鎮的話我們會以性命保護它不受傷害。', `FemaleText_loc7`='Hace poco, hemos oído que están invocando una criatura de inmenso poder cerca de la Espiral Vectorial. No temas, si la ciudad corriese peligro, entregaríamos nuestras vidas para salvarla.' WHERE `ID`=14796;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 등골이 다 오싹하군.', `MaleText_loc4`='啊……我的背上感到一股凉意。', `MaleText_loc5`='啊...一股寒氣爬上了我的脊椎。', `MaleText_loc7`='Aaah... Tengo escalofríos.', `FemaleText_loc1`='아... 등골이 다 오싹하군.', `FemaleText_loc4`='啊……我的背上感到一股凉意。', `FemaleText_loc5`='啊...一股寒氣爬上了我的脊椎。', `FemaleText_loc7`='Aaah... Tengo escalofríos.' WHERE `ID`=14797;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 세계에 남아 있는 신성함이란 도대체 어디 있나요?', `MaleText_loc4`='这个世界已经没有圣洁可言了吗？', `MaleText_loc5`='這世上沒有聖潔的事物了嗎?', `MaleText_loc7`='¿Es que no queda nada sagrado en este mundo?', `FemaleText_loc1`='이 세계에 남아 있는 신성함이란 도대체 어디 있나요?', `FemaleText_loc4`='这个世界已经没有圣洁可言了吗？', `FemaleText_loc5`='這世上沒有聖潔的事物了嗎?', `FemaleText_loc7`='¿Es que no queda nada sagrado en este mundo?' WHERE `ID`=14798;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바라건대 저들도 빛을 보게 될 겁니다.', `MaleText_loc4`='他们会看到圣光的，希望如此。', `MaleText_loc5`='我希望，他們都會見到聖光。', `MaleText_loc7`='Verán la luz. O eso espero.', `FemaleText_loc1`='바라건대 저들도 빛을 보게 될 거예요.', `FemaleText_loc4`='他们会看到圣光的，希望如此。', `FemaleText_loc5`='我希望，他們都會見到聖光。', `FemaleText_loc7`='Verán la luz. O eso espero.' WHERE `ID`=14799;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='므우루가 없으니 아마 저 오만한 혈기사들도 정신이 좀 들 겁니다.', `MaleText_loc4`='穆鲁被夺走了，想必那些傲慢的血骑士会稍微清醒一点。', `MaleText_loc5`='隨著莫魯的離開，也許那些自大的血騎士將會體會到現實。', `MaleText_loc7`='Ahora que M''uru ya no está, quizá esos arrogantes Caballeros de sangre entren en razón.', `FemaleText_loc1`='므우루가 없으니 아마 저 오만한 혈기사들도 정신이 좀 들 겁니다.', `FemaleText_loc4`='穆鲁被夺走了，想必那些傲慢的血骑士会稍微清醒一点。', `FemaleText_loc5`='隨著莫魯的離開，也許那些自大的血騎士將會體會到現實。', `FemaleText_loc7`='Ahora que M''uru ya no está, quizá esos arrogantes Caballeros de sangre entren en razón.' WHERE `ID`=14800;
