UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<고르다우그의 동작이 멈추자 대지가 요란한 소리를 냅니다.>$B$B말하게나.', `MaleText_loc4`='<大地的隆隆声因为戈达乌暂停移动而停了下来。>$B$B说。', `MaleText_loc5`='<大地隨著葛爾道格的動作停下發出隆隆聲。>$B$B說吧。', `MaleText_loc7`='<La tierra retumba cuando los movimientos de Gordawg se detienen.>$B$BHabla.' WHERE `ID`=14802;
