UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 거만한 웃음을 지으며 순찰자들의 작은 훈련장을 둘러봅니다.', `MaleText_loc4`='%s俯视着那窄小的游侠练习场，作出一副谦逊的笑容。', `MaleText_loc5`='%s審視著小小的遊俠練習場地臉上揚起高傲的奸笑。', `MaleText_loc7`='%s inspecciona el pequeño terreno de prácticas de los forestales con una sonrisa condescendiente.', `FemaleText_loc1`='%s|1이;가; 거만한 웃음을 지으며 순찰자들의 작은 훈련장을 둘러봅니다.', `FemaleText_loc4`='%s俯视着那窄小的游侠练习场，作出一副谦逊的笑容。', `FemaleText_loc5`='%s審視著小小的遊俠練習場地臉上揚起高傲的奸笑。', `FemaleText_loc7`='%s inspecciona el pequeño terreno de prácticas de los forestales con una sonrisa condescendiente.' WHERE `ID`=14810;
