UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 웃기는 놈들이죠. 저기 바깥에 있는 놈들이 우리를 향해 턱을 치켜드는 모습을 본 적 있습니까?', `MaleText_loc4`='我们的邻居真可笑。你看到他们是怎么蔑视我们的吗？', `MaleText_loc5`='我們的鄰居真的很有趣。你有看過他們對我們嗤之以鼻的樣子嗎?', `MaleText_loc7`='Nuestros vecinos son ridículos. ¿Has visto como nos miran?', `FemaleText_loc1`='정말 웃기는 놈들이죠. 저기 바깥에 있는 놈들이 우리를 향해 턱을 치켜드는 모습을 본 적 있나요?', `FemaleText_loc4`='我们的邻居真可笑。你看到他们是怎么蔑视我们的吗？', `FemaleText_loc5`='我們的鄰居真的很有趣。你有看過他們對我們嗤之以鼻的樣子嗎?', `FemaleText_loc7`='Nuestros vecinos son ridículos. ¿Has visto como nos miran?' WHERE `ID`=14815;
