UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우두머리 성난파도다, 조심하십시오!', `MaleText_loc4`='工头泰德瓦斯，小心！', `MaleText_loc5`='監督者泰洛斯，小心啊!', `MaleText_loc7`='¡Sobrestante Iramarea, cuidado!' WHERE `ID`=14817;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='순찰자들은 자신들을 과대평가하고 있는 것이 분명합니다.', `MaleText_loc4`='这些游侠都是些眼高过天的家伙。', `MaleText_loc5`='那些遊俠一定對自己有很高的評價。', `MaleText_loc7`='Los forestales se lo tienen muy creído.', `FemaleText_loc1`='순찰자들은 자신들을 과대평가하고 있는 것이 분명해요.', `FemaleText_loc4`='这些游侠都是些眼高过天的家伙。', `FemaleText_loc5`='那些遊俠一定對自己有很高的評價。', `FemaleText_loc7`='Los forestales se lo tienen muy creído.' WHERE `ID`=14818;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 바깥에 있는 더러운 활쟁이들의 건방진 태도에 정말 신물이 납니다.', `MaleText_loc4`='外面那些拿弓的家伙十分傲慢，这让我很不爽。', `MaleText_loc5`='我很快就對外面那些骯髒的弓箭手驕傲的態度感到厭煩了。', `MaleText_loc7`='Me estoy cansando rápidamente de la actitud altiva que obtengo de esos sucios lanzaflechas de fuera.', `FemaleText_loc1`='저 바깥에 있는 더러운 활쟁이들의 건방진 태도에 정말 신물이 나네요.', `FemaleText_loc4`='外面那些拿弓的家伙十分傲慢，这让我很不爽。', `FemaleText_loc5`='我很快就對外面那些骯髒的弓箭手驕傲的態度感到厭煩了。', `FemaleText_loc7`='Me estoy cansando rápidamente de la actitud altiva que obtengo de esos sucios lanzaflechas de fuera.' WHERE `ID`=14819;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도대체 어디서 저런 자신감이 나올까요?', `MaleText_loc4`='他们觉得他们是谁？', `MaleText_loc5`='他們以為他們是誰?', `MaleText_loc7`='¿Quiénes se creen que son?', `FemaleText_loc1`='도대체 어디서 저런 자신감이 나올까요?', `FemaleText_loc4`='他们觉得他们是谁？', `FemaleText_loc5`='他們以為他們是誰?', `FemaleText_loc7`='¿Quiénes se creen que son?' WHERE `ID`=14820;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 말씀인지 알겠습니다... 저들은 우리가 듣지 못할 것이라고 생각하고 우리에 대해 쑥덕거리죠. 언젠가는 그 대가를 치를 것입니다.', `MaleText_loc4`='我知道你的意思……他们自以为他们的私语我们不知道。他们会自食其果的。', `MaleText_loc5`='我懂你的意思...他們以為我們聽不到他們在偷偷討論我們。他們會得到教訓的。', `MaleText_loc7`='Entiendo lo que quieres decir... Hablan de nosotros cuando creen que no los oímos. Nos las pagarán.', `FemaleText_loc1`='무슨 말씀인지 알겠습니다... 저들은 우리가 듣지 못할 것이라고 생각하고 우리에 대해 숙덕거리죠. 언젠가는 그 대가를 치를 것입니다.', `FemaleText_loc4`='我知道你的意思……他们自以为他们的私语我们不知道。他们会自食其果的。', `FemaleText_loc5`='我懂你的意思...他們以為我們聽不到他們在偷偷討論我們。他們會得到教訓的。', `FemaleText_loc7`='Entiendo lo que quieres decir... Hablan de nosotros cuando creen que no los oímos. Nos las pagarán.' WHERE `ID`=14821;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='질투심, 이것이 바로 저들이 느끼는 감정의 전부입니다. 저들은 진정한 힘에 헌신할 것을 두려워하죠.', `MaleText_loc4`='嫉妒，他们嫉妒了。他们害怕为真正的力量献身。', `MaleText_loc5`='嫉妒，他們就是這樣。他們害怕將自己奉獻給真正的力量。', `MaleText_loc7`='Envidia. Eso es lo único que sienten. Tienen miedo de entregarse al verdadero poder.', `FemaleText_loc1`='질투심, 그게 바로 그들이 느끼는 감정입니다. 그들은 진정한 힘에 자신을 바치는 것을 두려워합니다.', `FemaleText_loc4`='嫉妒，他们嫉妒了。他们害怕为真正的力量献身。', `FemaleText_loc5`='嫉妒，他們就是這樣。他們害怕將自己奉獻給真正的力量。', `FemaleText_loc7`='Envidia. Eso es lo único que sienten. Tienen miedo de entregarse al verdadero poder.' WHERE `ID`=14822;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들은 자신들이 이해하지 못하는 것을 덮어놓고 두려워합니다.', `MaleText_loc4`='他们对那些他们无法理解的东西感到畏惧。', `MaleText_loc5`='他們只是害怕無法了解的事物。', `MaleText_loc7`='Simplemente temen lo que no entienden.', `FemaleText_loc1`='저들은 자신들이 이해하지 못하는 것을 덮어놓고 두려워하죠.', `FemaleText_loc4`='他们对那些他们无法理解的东西感到畏惧。', `FemaleText_loc5`='他們只是害怕無法了解的事物。', `FemaleText_loc7`='Simplemente temen lo que no entienden.' WHERE `ID`=14823;
