UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 사라졌어요. 이렇게 되다니 믿을 수가 없군요. 우리가 이런 식으로 배신당할 줄 누가 생각이나 했겠어요?', `MaleText_loc4`='没了。我不敢相信它已经没了。谁能料到我们居然遭受了这么残酷的背叛？', `MaleText_loc5`='全消失了。我不敢相信這全消失了。誰相信我們會遭到這樣的背叛?', `MaleText_loc7`='Ha desaparecido. No me lo puedo creer. ¿Quién habría imaginado que nos iban a traicionar de esta manera?', `FemaleText_loc1`='모두 사라졌어요. 이렇게 되다니 믿을 수가 없군요. 우리가 이런 식으로 배신당할 줄 누가 생각이나 했겠어요?', `FemaleText_loc4`='没了。我不敢相信它已经没了。谁能料到我们居然遭受了这么残酷的背叛？', `FemaleText_loc5`='全消失了。我不敢相信這全消失了。誰相信我們會遭到這樣的背叛?', `FemaleText_loc7`='Ha desaparecido. No me lo puedo creer. ¿Quién habría imaginado que nos iban a traicionar de esta manera?' WHERE `ID`=14833;
