UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여군주 바쉬 님의 이름으로 그 건방진 녀석을 처단하라!', `MaleText_loc4`='以瓦丝琪之名，打败他！', `MaleText_loc5`='以瓦許女士之名將他擊敗!', `MaleText_loc7`='¡Véncelo en nombre de Lady Vashj!' WHERE `ID`=14836;
