UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여군주 리아드린 님께서 방법을 찾으셔야 합니다. 그러셔야 하고 말고요.', `MaleText_loc4`='女伯爵莉亚德琳有义务为我们找到新的出路。她必须这么做。', `MaleText_loc5`='莉雅德倫女士肩負起尋找出路的責任。她一定要成功。', `MaleText_loc7`='Lady Liadrin debe encontrar una solución. Es imperativo.', `FemaleText_loc1`='여군주 리아드린 님께서 방법을 찾으셔야 합니다. 그러셔야 하고 말고요.', `FemaleText_loc4`='女伯爵莉亚德琳有义务为我们找到新的出路。她必须这么做。', `FemaleText_loc5`='莉雅德倫女士肩負起尋找出路的責任。她一定要成功。', `FemaleText_loc7`='Lady Liadrin debe encontrar una solución. Es imperativo.' WHERE `ID`=14838;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그... 제가 잘못 들은 게 아니지요? 그 인물이 바로 태양왕이었다는 거 말입니다.', `MaleText_loc4`='这……这都是真的吗？这真的是太阳之王干的吗？', `MaleText_loc5`='這...這是真的嗎?我聽到了什麼?那是太陽之王本人?', `MaleText_loc7`='¿Es… verdad lo que he oído? ¿Que era el Rey del Sol en persona?', `FemaleText_loc1`='그... 제가 들은 게 사실인가요? 그 인물이 바로 태양왕이었다는 거 말입니다.', `FemaleText_loc4`='这……这都是真的吗？这真的是太阳之王干的吗？', `FemaleText_loc5`='這...這是真的嗎?我聽到了什麼?那是太陽之王本人?', `FemaleText_loc7`='¿Es… verdad lo que he oído? ¿Que era el Rey del Sol en persona?' WHERE `ID`=14839;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 혈기사단은 이 실패를 딛고 견뎌낼 겁니다. 다른 선택이 없으니... 다른 원천을 찾아내야 합니다.', `MaleText_loc4`='无论怎样，血骑士必须坚持到底。我们没有选择……我们必须找到新的能量源。', `MaleText_loc5`='當然，血騎士會撐過這一次的損失。我們沒有別的選擇...我們必須要找到別的來源。', `MaleText_loc7`='A pesar de esta pérdida, los Caballeros de sangre seguirán existiendo. No tenemos otra opción… debemos encontrar otra fuente.', `FemaleText_loc1`='우리 혈기사단은 이 실패를 딛고 견뎌낼 겁니다. 다른 선택이 없으니... 다른 원천을 찾아내야 합니다.', `FemaleText_loc4`='无论怎样，血骑士必须坚持到底。我们没有选择……我们必须找到新的能量源。', `FemaleText_loc5`='當然，血騎士會撐過這一次的損失。我們沒有別的選擇...我們必須要找到別的來源。', `FemaleText_loc7`='A pesar de esta pérdida, los Caballeros de sangre seguirán existiendo. No tenemos otra opción… debemos encontrar otra fuente.' WHERE `ID`=14840;
