UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cffffff00얼라이언스가 무너진 언덕을 점령했습니다!|r', `MaleText_loc4`='|cffffff00联盟占领了碎石岭！|r', `MaleText_loc5`='|cffffff00破碎之丘已被聯盟佔領!|r', `MaleText_loc7`='|cffffff00¡Cerro Tábido ha sido tomado por la Alianza!|r' WHERE `ID`=14845;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cffffff00호드가 무너진 언덕을 점령했습니다!|r', `MaleText_loc4`='|cffffff00部落占领了碎石岭！|r', `MaleText_loc5`='|cffffff00破碎之丘已被部落佔領!|r', `MaleText_loc7`='|cffffff00¡Cerro Tábido ha sido tomado por la Horda!|r' WHERE `ID`=14846;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어리석은 녀석, 너는 결코 방주를 훔치는 데 성공하지 못할 것이다!', `FemaleText_loc4`='蠢货，你休想偷走箱子！', `FemaleText_loc5`='蠢蛋，你不會成功偷到方舟的!', `FemaleText_loc7`='¡Essstúpidosss, no conssseguiréisss robar el arca!' WHERE `ID`=14847;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아버지께서는 더 큰 사냥감을 찾아 좀 더 특별한 곳으로 갔네. 허나 우린 아직 이곳에서 사냥하고 있으니 걱정하지 말게!', `MaleText_loc4`='我父亲去了更光怪陆离的地方寻找更大的猎物。不用担心，我们还会在这里继续打猎！', `MaleText_loc5`='我父親在更奇特的地方尋找更大的獵物。不過別擔心，我們仍在這裡打獵!', `MaleText_loc7`='Mi padre ha partido hacia lugares más exóticos en busca de mayores presas. Pero no te preocupes, ¡todavía hay mucho que cazar aquí!' WHERE `ID`=14848;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 경계를 늦추지 마시오. 언제 어떤 짐승이 주변의 다른 먹이 대신 당신 뒤를 몰래 추적할지 모른다오.', `MaleText_loc4`='保持警惕，$c。当野兽潜行靠近你的时候，你永远不会察觉得到。', `MaleText_loc5`='眼睛睜大一點，$c。你永遠不知道是你在追蹤野獸還是牠們在追蹤你。', `MaleText_loc7`='Mantén los ojos bien abiertos, $c. Nunca se sabe cuándo hay alguna bestia acechándote, y no al revés.' WHERE `ID`=14849;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헤멧 네싱워리 씨, 여기 아웃랜드에서 뭘 하고 있습니까?', `MaleText_loc4`='赫米特·奈辛瓦里，你在外域干什么？', `MaleText_loc5`='赫米特·奈辛瓦里，你在外域這裡做什麼?', `MaleText_loc7`='Hemet Nesingwary, ¿qué estás haciendo en Terrallende?', `FemaleText_loc1`='헤멧 네싱워리 씨, 여기 아웃랜드에서 뭘 하고 있나요?', `FemaleText_loc4`='赫米特·奈辛瓦里，你在外域干什么？', `FemaleText_loc5`='赫米特·奈辛瓦里，你在外域這裡做什麼?', `FemaleText_loc7`='Hemet Nesingwary, ¿qué estás haciendo en Terrallende?' WHERE `ID`=14850;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여어, 반갑구려. 난 유능한 내 아들에게 가시덤불 골짜기의 원정대를 맡겼소. 당신이 아제로스 전 지역에서 가장 신나는 놀이를 찾아다닐 때 당신은 무언가 그 이상의 것을 원하게 될 거요.$B$B그리고 당신도 여기 야수들이 얼마나 큰지 봤지 않소?$B$B나는 당신이 여기서 처음 보았을 가장 위험한 사냥감을 사냥하고 있었소. 내 말은 뿔엄니를 잡아서 그 심장을 전리품으로 가져갈 생각이라는 거요!', `MaleText_loc4`='听着，$g小子:小姑娘;。我把远征队交给了我可靠的儿子，赫米特·奈辛瓦里二世。当你杀过全艾泽拉斯最凶猛的野兽之后，你就会开始渴望更多。$B$B你看到这里野兽的个头了吗？！$B$B我在这里猎杀着你所见过的最危险的猎物。我打算亲自抓住塔丝克，把她的徽记带回去做战利品。', `MaleText_loc5`='聽著$g小子:小姑娘;。我將狩獵遠征隊交給了我能幹的兒子。當你獵遍了全艾澤拉斯最棒的獵物，你自然會渴望更大的挑戰。$B$B你有看到這裡的野獸的大小嗎?!$B$B我要在這裡獵捕你所見過最危險的獵物。而且我一定要獵到長牙，將她的心臟帶回去做為戰利品!', `MaleText_loc7`='Escucha, $gamigo:amiga;. He dejado la expedición en las competentes manos de mi hijo Júnior. Cuando ya has cazado las mejores presas de Azeroth, empiezas a pensar en algo más grande.$B$B¿Y has visto las bestias que hay aquí?$B$B¡He venido a abatir la presa más peligrosa que hayas imaginado jamás! ¡Quiero cazar a Eburnia y llevarme su corazón como trofeo!' WHERE `ID`=14851;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n! 당신의 사냥 실력 역시 매우 뛰어난 걸 기억하고 있소이다. 가시덤불 골짜기에서 사냥을 시작한 당신은 처음에는 약간 불안했지만 늙은 뱅갈라시까지 잡고 최고의 사냥꾼이 됐지.$B$B하지만, 내 말을 잘 들으시오. 여기 아웃랜드의 사냥감은 차원이 다른 녀석들이라오. 내 몸에 녀석들이 얼마나 강력한지를 보여주는 상처도 있다오!', `MaleText_loc4`='$n！我对你的狩猎能力印象深刻，你在荆棘谷的开始并不是那么如意，但你坚持到了最后，并且当你捕获了虎王邦加拉什后，你已经成为了最好的猎人之一。$B$B不过听好了，$g小伙子:小姑娘;，外域这里的猎物真的很难对付，我的伤疤可以证明这一点。', `MaleText_loc5`='$n!我對你的打獵本領印象深刻。你在荊棘谷的開始或許不太穩當，但你堅持到底，捕獲老邦加拉西成為最出色的人之一。$B$B但聽好了，$g小夥子:小姑娘;，外域的獵物是真的很難對付。我還有疤可以證明這點!', `MaleText_loc7`='¡$n! Recuerdo tus proezas de caza. Puede que no empezaras demasiado bien en Tuercespina, pero has seguido a tu ritmo y ahora eres uno de los mejores tras abatir al viejo Bangalash.$B$BPero escucha, $gamigo:amiga;, las presas de Terrallende ahora son lo máximo. ¡Mira mis cicatrices!' WHERE `ID`=14852;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 쉭쉭 소리를 내며 공격할 준비를 합니다.', `MaleText_loc4`='%s响亮地发出咝咝的声音，准备攻击。', `MaleText_loc5`='%s大聲地發出噓聲並準備攻擊。', `MaleText_loc7`='%s sisea con fuerza y se prepara para atacar.' WHERE `ID`=14853;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='켈레마르 대사여... 우리를 위해 자네 종족은 어떤 일을 해줄 수 있나?', `FemaleText_loc4`='提醒我，大使……你的人民会为我们做出什么样的贡献？', `FemaleText_loc5`='提醒我，大使...你的人民究竟會對我們的努力做出什麼樣的貢獻?', `FemaleText_loc7`='Recuérdame, embajador... ¿en qué contribuiría tu pueblo exactamente a nuestros esfuerzos?' WHERE `ID`=14854;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그곳으로 데려다 주세요.', `MaleText_loc4`='Take me to the place<PH>', `MaleText_loc5`='帶我到那去<PH>', `MaleText_loc7`='Llévame al lugar <PH>' WHERE `ID`=14855;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='따라오라고!', `MaleText_loc4`='跟着我！', `MaleText_loc5`='跟著我!', `MaleText_loc7`='¡Sígueme!', `FemaleText_loc1`='따라오라고!', `FemaleText_loc4`='跟着我！', `FemaleText_loc5`='跟著我!', `FemaleText_loc7`='¡Sígueme!' WHERE `ID`=14856;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 종족은 강합니다. 우리는 그대들이 늘 필요로 했던 비전 마법에 대한 통찰력을 나눠줄 수 있습니다. 물론 공격할 의사는 전혀 없고요.', `MaleText_loc4`='我们的人民非常强大。我们给你们带来了你们前所未知的、不可思议的魔法——啊，当然我不是在冒犯你们。', `MaleText_loc5`='我們的人民很強壯。我們為你帶來了秘法魔法的專精，這是你們先前所缺少的 - 啊，無冒犯之意，真的。', `MaleText_loc7`='Nuestro pueblo es fuerte. Te traemos un dominio de la magia Arcana de la que antes carecías – ah, sin ánimo de ofender, por supuesto.' WHERE `ID`=14857;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 관계는 분명 그대들에게 이익이 될 것입니다. 우리는 엄청난 힘을 사용할 수 있습니다. 우리가 도와주면 여러분은 적을 물리칠 수 있습니다.', `MaleText_loc4`='我肯定你们会看到与我们搞好关系的益处。我们所掌握的力量是无穷的。有了我们的帮助，你们的敌人将很快被消灭。', `MaleText_loc5`='你的確看到我們關係中的有利條件。我們所掌控的力量十分龐大。有我們的幫助，你的敵人絕對會被殲滅。', `MaleText_loc7`='Sin duda ves las ventajas de nuestra relación. Los poderes que inspiramos son inmensos. Con nuestra ayuda, tus enemigos serían diezmados.' WHERE `ID`=14858;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='과거에 우리의 충성심이 조금 어긋나 있었다는 사실은 인정합니다. 하지만, 의심은 잠시 접어두십시오. 여러분의 지도자를 위해 우리의 강대한 힘을 바치겠다고 약속합니다.', `MaleText_loc4`='我明白在很久以前我们曾有些分歧，但是请把你们的顾虑放在一边。我们强大的力量已经完全可以听凭你们的首领来调遣了。', `MaleText_loc5`='我知道我們在過去有些不怎麼忠誠的行為，但先將你的疑慮放在一邊。我們已將龐大的力量完全許諾給你的領導者了。', `MaleText_loc7`='Me doy cuenta de que en el pasado teníamos lealtades algo diferentes, pero deja tus recelos a un lado. Nuestro considerable poder se ha comprometido a tus líderes de buena fe.' WHERE `ID`=14859;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='조만간 자네 종족이 얼마나 헌신적인지 알 수 있겠군.', `FemaleText_loc4`='我想我们会在适当的时候看到你们的贡献。', `FemaleText_loc5`='我想我們會在適當的時候看到你的貢獻。', `FemaleText_loc7`='Supongo que veremos la medida de tu dedicación a su debido tiempo.' WHERE `ID`=14860;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 트롤의 목표를 생각하면 자네 종족은 별로 쓸모가 없을 것 같은데?', `MaleText_loc4`='你不觉得你们对巨魔的贡献还不够吗？', `MaleText_loc5`='你認為你跟隨食人妖的腳步讓你不那麼出色了嗎?', `MaleText_loc7`='¿Crees que podrías contribuir mirando a este trol con menos furia?' WHERE `ID`=14861;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='타타이?!', `FemaleText_loc4`='塔泰！', `FemaleText_loc5`='塔泰!', `FemaleText_loc7`='¡Tatai!' WHERE `ID`=14862;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 체념한 듯 한숨을 쉬더니 입을 다뭅니다.', `MaleText_loc4`='%s顺从地叹了口气，沉默了下来。', `MaleText_loc5`='%s屈從地嘆了口氣開始變的沉默。', `MaleText_loc7`='%s suspira con resignación y se queda en silencio.' WHERE `ID`=14863;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리가 맺은 협정은 정말 유익하다고 볼 수 있지.', `FemaleText_loc4`='真正互利的同盟。', `FemaleText_loc5`='的確是個有助的聯盟。', `FemaleText_loc7`='Ciertamente, una alianza ventajosa.' WHERE `ID`=14864;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 감히 심연 깊은 곳에 잠들어 있는 구로크 님을 깨우는 것이냐!', `MaleText_loc4`='是谁胆敢召唤古罗克？', `MaleText_loc5`='誰膽敢召喚彼方的古羅克?', `MaleText_loc7`='¿QUIÉN OSA LLAMAR A GUROK DEL INFRAMUNDO?' WHERE `ID`=14865;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='델라 룬토템이 이마를 찡그리지만 침묵을 지킵니다.', `FemaleText_loc4`='德拉·符文图腾皱了下眉毛，但她还是继续保持沉默。', `FemaleText_loc5`='戴拉·符騰皺起眉頭，但她保持沉默。', `FemaleText_loc7`='Dela Tótem de Runa frunce el ceño, pero permanece en silencio.' WHERE `ID`=14866;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이방인이여, 서둘러 여군주 제이나 프라우드무어를 만나 보게. 그녀는 소규모의 얼라이언스 군대를 이끌고 용감하게 불타는 군단의 초반 공격을 막아내고, 아키몬드의 접근을 지연시키고 있네.', `MaleText_loc4`='陌生人，赶快到吉安娜·普罗德摩尔那里去。她的一小股联盟部队正在勇敢地抵挡着燃烧军团的攻势，延缓着阿克蒙德的到来。', `MaleText_loc5`='陌生人，趕快行動聯絡珍娜·普勞德摩爾女士。她人數不多的聯盟部隊正勇敢地試著減弱燃燒軍團的初步攻擊並延遲阿克蒙德的接近。', `MaleText_loc7`='$gForastero:Forastera; date prisa y ponte en contacto con Lady Jaina Valiente. Con su pequeño ejército de la Alianza pretende frenar el asalto de la Legión Ardiente y retrasar la llegada de Archimonde.' WHERE `ID`=14867;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그건 그렇고 자네 종족이 호드에 어떤 도움을 줄 수 있나?', `MaleText_loc4`='总之，你们能给部落做出什么贡献？', `MaleText_loc5`='你到底給予部落什麼樣的幫助?', `MaleText_loc7`='¿Qué ayuda proporcionarás a la Horda, de todas formas?' WHERE `ID`=14868;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여군주 프라우드무어의 군대는 아키몬드와 그의 불타는 군단을 막으려고 피를 흘렸다. 그리고 이제 우리가 아키몬드의 악마군에 맞서야 한다. 그대는 나와 함께 적의 맹공격에 맞설 각오가 되었는가?', `MaleText_loc4`='普罗德摩尔女士的部队为了拖延阿克蒙德和他的燃烧军团，已经经历了一场恶战。现在这个严酷的任务摆在了我们的面前。你准备好面对他们的冲击了吗？', `MaleText_loc5`='普勞德摩爾女士的軍隊已奮力阻擋了阿克蒙德和他的燃燒軍團，而現在這個艱困的任務落到我們頭上。你準備好和我一起抵擋突擊了嗎?', `MaleText_loc7`='Las fuerzas de Lady Valiente han sufrido para ralentizar el avance de Archimonde y de la Legión Ardiente; ahora nos toca tomar el relevo. ¿Estás $glisto:lista; para luchar a mi lado?' WHERE `ID`=14869;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='켈레마르 대사... 블러드 엘프들이 우리를 돕겠다는 정확한 이유가 뭐죠?', `FemaleText_loc4`='告诉我们，克雷玛尔大使……血精灵们到底准备怎么样来帮助我们？', `FemaleText_loc5`='告訴我們，凱勒瑪爾大使...血精靈究竟打算怎樣幫助我們?', `FemaleText_loc7`='Díganos, embajador Kelemar... ¿cómo piensan ayudarnos los elfos de sangre exactamente?' WHERE `ID`=14870;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새의 영혼이여, 우리 신전에 와주었구려. 환영하오.', `MaleText_loc4`='我谦卑地欢迎你来到我们的神殿，灵魂。', `MaleText_loc5`='我謙遜地歡迎你來我們的神廟，靈魂。', `MaleText_loc7`='Te doy la bienvenida a nuestro templo, espíritu.' WHERE `ID`=14871;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑소, 장로여. 그대의 백성이 지닌 드레나이와 그 동맹들에 대한 적대감에 종지부를 찍을 시간이 되었소.', `MaleText_loc4`='您好，长者。是时候让您的人民结束对德莱尼人和他们的同盟的敌意了。', `MaleText_loc5`='你好，長者。是時候讓你的人民終止他們對德萊尼及其盟友的敵意了。', `MaleText_loc7`='Saludos, anciano. Es hora de que tu pueblo cese las hostilidades contra los draenei y sus aliados.', `FemaleText_loc1`='반갑소, 장로여. 그대의 백성이 지닌 드레나이와 그 동맹들에 대한 적대감에 종지부를 찍을 시간이 되었소.', `FemaleText_loc4`='您好，长者。是时候让您的人民结束对德莱尼人和他们的同盟的敌意了。', `FemaleText_loc5`='你好，長者。是時候讓你的人民終止他們對德萊尼及其盟友的敵意了。', `FemaleText_loc7`='Saludos, anciano. Es hora de que tu pueblo cese las hostilidades contra los draenei y sus aliados.' WHERE `ID`=14872;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 고통받고 있을 때 등을 돌린 드레나이와 교섭을 하라는 말입니까? 나는 그리 생각지 않습니다.$B$B진정한 새의 영혼이라면 그런 말을 할 수 없다! 정체를 밝혀라, 이 사기꾼. 누가 보내서 왔느냐?', `MaleText_loc4`='和那些在我们受苦的时候抛弃我们的德莱尼人协商？我不这么想。$B$B真正的灵魂是不会说出这种话的！露出你的真面目吧，骗子。是谁派你来的？', `MaleText_loc5`='和德萊尼那些在我們受苦的時候背叛我們的人協商?我不這麼想。$B$B一個真正的靈魂不會這樣對談!顯露出你的真面目吧，騙子。', `MaleText_loc7`='¿Tratar con los draenei, la gente que nos dio la espalda cuando sufríamos? No lo creo.$B$B¡Un espíritu recto no habla así! Muéstrate, impostor. ¿Quién te envía?' WHERE `ID`=14873;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장로, 당신을 속일 생각은 없었소. 텔레도르의 드레나이들은 당신이 익숙한 방식으로 당신에게 접근할 생각이었을 뿐이오.', `MaleText_loc4`='我不是想欺骗您，长者。泰雷多尔的德莱尼人想用一种您熟悉的方式来接近您。', `MaleText_loc5`='我無意欺騙你，長者。泰倫多爾的德萊尼想以你熟悉的方式來接近你。', `MaleText_loc7`='No pretendía engañarte, anciano. Los draenei de Telredor solo querían acercarse a ti de un modo que te resultara familiar.', `FemaleText_loc1`='장로, 당신을 속일 생각은 없었소. 텔레도르의 드레나이들은 당신이 익숙한 방식으로 당신에게 접근할 생각이었을 뿐이오.', `FemaleText_loc4`='我不是想欺骗您，长者。泰雷多尔的德莱尼人想用一种您熟悉的方式来接近您。', `FemaleText_loc5`='我無意欺騙你，長者。泰倫多爾的德萊尼想以你熟悉的方式來接近你。', `FemaleText_loc7`='No pretendía engañarte, anciano. Los draenei de Telredor solo pretendían acercarse a ti de un modo que te resultara familiar.' WHERE `ID`=14874;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신과 함께하겠습니다, 대족장님.', `MaleText_loc4`='我与你并肩作战，萨尔。', `MaleText_loc5`='我與你同在，索爾。', `MaleText_loc7`='Estoy contigo, Thrall.', `FemaleText_loc1`='당신과 함께하겠어요, 대족장님.', `FemaleText_loc4`='我与你并肩作战，萨尔。', `FemaleText_loc5`='我與你同在，索爾。', `FemaleText_loc7`='Estoy contigo, Thrall.' WHERE `ID`=14875;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러니까, 이런 속임수로 우리를 기만하려고 한 자들을 믿어야 한다는 말이오? 드레나이들이 우리에 대해 깊게 생각해 본 적이 거의 없기에 이딴 속임수에 의지해서 우리 관심을 끌려는 게 아닌가?$B$B우리에게 속죄하고자 도움의 손길을 보내려는 그들의 마음은 잘 알겠지만, 내 백성들은 그런 도움을 원하지 않을 것이오. 우리는 혼자 힘으로 충분히 일어설 수 있으며 자랑스럽고 독립된 종족으로서 우리의 운명을 추구할 것이오. 그대의 동맹에 돌아가서 이대로 전하시오.', `MaleText_loc4`='这么看来，我们要不要信任那些使用这种诡计来欺骗我们的家伙呢？是不是德莱尼人对我们的感受毫不在意，以至于认为他们必须凭借欺骗来取得我们的注意？$B$B我们知道，他们想要“救赎”我们，但是我的人民不需要他们的救赎。我们会靠自己的能力生存下去，并自豪地、独立地向着我们的命运前进。把我的话带给你的同盟吧。', `MaleText_loc5`='所以我們要信任那些用欺騙來侮辱我們的人嗎?德萊尼那麼輕視我們所以他們必須使用奸計來引起我們的注意嗎?$B$B我們知道他們想「救贖」我們，但我的人民根本不想要他們的救贖。我們可以自己站起來而且我們追求的是驕傲，獨立的命運。把這個訊息帶給你的盟友。', `MaleText_loc7`='Así que debemos confiar en quienes nos insultan de esta manera. ¿Qué imagen tienen los draenei de nosotros como para usar trucos que llamen nuestra atención?$B$BSabemos que están deseando "redimirnos", pero mi pueblo no necesita redención alguna. Somos capaces de arreglárnoslas solos y perseguiremos nuestro destino como un pueblo independiente y orgulloso. Transmite este mensaje a tus aliados.' WHERE `ID`=14876;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇다면, 불타는 군단이 마음껏 까불도록 놔둬 볼까!', `MaleText_loc4`='那么让燃烧军团尽管使出他们的手段吧！', `MaleText_loc5`='然後讓軍團痛苦至極!', `MaleText_loc7`='¡Entonces, que la Legión haga lo peor!' WHERE `ID`=14877;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불타는 군단이 우리를 강력하게 압박하고 있지만 우리 방어선은 견고하네. 우리 호드가 세계수에 접근하려는 아키몬드를 막고 있는 매 순간 우리는 승리에 조금씩 가까워지고 있는 것이라네.', `MaleText_loc4`='燃烧军团紧紧逼迫着我们，但是我们顶住他们潮水般的进攻。阿克蒙德接近世界之树的时间越晚，我们离胜利就越近一步。', `MaleText_loc5`='燃燒軍團緊逼我們，但我們的防禦還撐的住。我們每讓阿克蒙德遠離世界之樹一步就讓我們離勝利更近一步。', `MaleText_loc7`='La Legión Ardiente nos presiona, pero nuestra defensa resiste. Cada momento que mantenemos a Archimonde lejos del Árbol del Mundo nos lleva más cerca de la victoria.' WHERE `ID`=14878;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대로 전하겠으니 몸조심하시오, 장로여.', `MaleText_loc4`='我会告诉他们的。保重，长者。', `MaleText_loc5`='我會告訴他們。再會了，長者。', `MaleText_loc7`='Se lo diré. Adiós, anciano.', `FemaleText_loc1`='그대로 전하겠으니 몸조심하세요, 장로님.', `FemaleText_loc4`='我会告诉他们的。保重，长者。', `FemaleText_loc5`='我會告訴他們。再會了，長者。', `FemaleText_loc7`='Se lo diré. Adiós, anciano.' WHERE `ID`=14879;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋소. 가서 그들을 이해시키시오.$B$B이제 내 신전에서 조용히 떠나 주시면 고맙겠구려.', `MaleText_loc4`='好，一定要让他们理解。$B$B现在，如果你能离开我的神殿，我会非常感激的。', `MaleText_loc5`='很好。確定他們了解。$B$B現在，如果你能安靜的離開我的神廟我會非常感激。', `MaleText_loc7`='Bien. Asegúrate de que lo comprenden.$B$BAhora te agradecería que dejaras mi templo en paz.' WHERE `ID`=14880;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에서 제 일은 끝났습니다.', `MaleText_loc4`='我在这里的工作已经完成了。', `MaleText_loc5`='我在這裡的責任已盡。', `MaleText_loc7`='Mi trabajo aquí ha terminado.' WHERE `ID`=14881;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳은 정말 거대하군. 이렇게 큰 공간이 필요한 이유가 뭔가?', `MaleText_loc4`='这地方真大。你们要这么大的地盘干啥？', `MaleText_loc5`='這個地方很大。你為什麼需要這麼大的空間?', `MaleText_loc7`='Este lugar mu grande. ¿Pa'' qué necesitas todo este espasio?' WHERE `ID`=14882;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳은 한때 번성했던 실버문의 일부에 불과합니다. 아서스가 우리 땅을 침략한 이후 도시의 대부분이 흔적도 없이 파괴됐습니다.', `MaleText_loc4`='这里只不过是曾经的银月城的一小部分。城市的大部分都在阿尔萨斯横扫我们土地的时候被破坏了。', `MaleText_loc5`='這只是銀月城一部分的過去而已。大部分的城市都在阿薩斯橫掃我們的土地之後消失了。', `MaleText_loc7`='Esto es simplemente parte de lo que Lunargenta fue antaño. Gran parte de la ciudad se perdió después de que Arthas destruyera nuestras tierras.' WHERE `ID`=14883;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 전쟁 중에 많은 동족을 잃었습니다... 그래서 이 도시에서도 예전만큼 활기찬 모습을 찾아볼 수 없죠. 하지만 우리는 견뎌낼 것입니다.', `MaleText_loc4`='我们在战争中失去了很多同胞……所以，这座城市也许已经不像以前那样充满了活力。不管怎样，我们都会忍耐。', `MaleText_loc5`='我們在戰爭中損失了很多族人...所以是的，這城市或許不像它以前那樣充滿活力。不過，我們會忍耐。', `MaleText_loc7`='Perdimos a muchos de los nuestros en la guerra... Sí, la ciudad no está tan animada como antes. Pero resistiremos.' WHERE `ID`=14884;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대사가 원하는 만큼 블러드 엘프 종족이 강해진다면 충분히 도시를 재건할 수 있을 걸세.', `FemaleText_loc4`='如果你的人民像你所宣称的那样强大，我深信你们会再次迈入辉煌的。', `FemaleText_loc5`='如果你的人民和你的意圖一樣強壯，我相信你會再次找回你的進展。', `FemaleText_loc7`='Si tu gente es tan fuerte como dices, estoy segura de que todo volverá a su cauce.' WHERE `ID`=14885;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 의견을 묻는다면 이건 엄청난 낭비라고 대답하고 싶군.', `MaleText_loc4`='如果你想知道我的意见，这是个大浪费。', `MaleText_loc5`='這是個很大的浪費，如果你問我。', `MaleText_loc7`='E''to ser gran despilfarro, socio.' WHERE `ID`=14886;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='타타이, 아무도 안 물어봤네.', `FemaleText_loc4`='没人在问你，塔泰。', `FemaleText_loc5`='嗯，沒人問你，塔泰。', `FemaleText_loc7`='Nadie te había preguntado, Tatai.' WHERE `ID`=14887;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 조그만 소리로 뭐라고 투덜거립니다.', `MaleText_loc4`='%s低声发着牢骚。', `MaleText_loc5`='%s嘴裡咕噥著。', `MaleText_loc7`='%s farfulla entre dientes.' WHERE `ID`=14888;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='블러드 엘프만이 스컬지의 희생자는 아니라네. 우리 여군주 실바나스께서 자네 종족의 처지에 공감하고 계시네.', `FemaleText_loc4`='你们不是亡灵天灾唯一的受害者。我们的希尔瓦娜斯女王很同情你们的遭遇。', `FemaleText_loc5`='你不是天譴軍團下唯一的受害者。我們的希瓦娜斯女士同情你的困境。', `FemaleText_loc7`='No son las únicas víctimas de la Plaga. Nuestra señora Sylvanas conoce su dolor.' WHERE `ID`=14889;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='애도의 뜻을 표합니다. 과거 몇 년 동안은 우리 모두에게 힘든 시간이었지요.', `FemaleText_loc4`='我很遗憾。过去的几年对我们来说很艰难。', `FemaleText_loc5`='我的慰問。我們過去這些年過的都很苦。', `FemaleText_loc7`='Lo siento. Estos últimos años han sido muy duros para todos.' WHERE `ID`=14890;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 도시는 매우... 넓군요. 하지만, 뭔가 부족한 것 같아요. 콕 집어서 말할 수는 없지만...', `FemaleText_loc4`='这座城市非常……奢华。但是它看上去似乎缺少些什么，我不能确切地指出到底缺什么……', `FemaleText_loc5`='這個城市非常的...昂貴，但它看起來少了什麼。我不能觸碰任何東西...', `FemaleText_loc7`='La ciudad es muy... extensa, pero parece que le falta algo. No sé exactamente qué...' WHERE `ID`=14891;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그대의 종족은 많은 노력을 기울인 것 같군요. 솔직히 경망스럽긴 하지만... 아, 제 말에 마음 상해 마세요. 하지만, 사실 낭비 아닌가요?', `FemaleText_loc4`='似乎大量的能量被用在了……琐碎的东西上……我希望你能宽恕我的用词。这样是不是，呃，太浪费了？', `FemaleText_loc5`='看來你的能量有一大部分是用來做...我希望你能原諒我說的話...無聊的東西。不是嗎，呃，浪費?', `FemaleText_loc7`='Parece que gran parte de tu poder se usa para... y espero que me perdones la expresión... frivolidades. ¿No es eso... bueno, un desperdicio?' WHERE `ID`=14892;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳은 여러분의 환경과는 조금 다를 것입니다. 우리가 가진 힘을 보여주는 것일 뿐, 그 이상도 이하도 아닙니다. 우리도 우리가 가진 자원을 염두에 두고 있습니다.', `MaleText_loc4`='这肯定和你们所习惯的环境有些区别。它只不过是我们所拥有的力量的一个展示而已，我们是很在意资源的。', `MaleText_loc5`='這一定和你習慣的環境有某種程度的不同。這是我們握有的力量明顯的證明，如此而已。', `MaleText_loc7`='Esto debe de ser bastante diferente a tu entorno habitual, ¿verdad? Es una demostración del poder que poseemos, nada más. Cuidamos de nuestros recursos.' WHERE `ID`=14893;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 생각해 보십시오. 오직 아름다운 환경을 조성하기 위해서 마법을 사용할 여유가 있다면 우리에게는 마음껏 사용할 수 있는 엄청난 힘의 원천이 있습니다.', `MaleText_loc4`='仔细想想，我的朋友们。如果我们能在这些简单的美观设施上花费我们的魔法，那么很明显，我们有着无穷无尽的能量以供驱使。', `MaleText_loc5`='仔細地想想看，我的朋友。如果我們可以將魔法消耗在裝飾用的附魔上，很明顯地我們擁有極大的力量。', `MaleText_loc7`='Pensadlo bien, amigos. Si podemos permitirnos gastar nuestra magia por razones simplemente estéticas, está claro que disponemos de una gran reserva.' WHERE `ID`=14894;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='환경이란 아름다움의 척도일 뿐만 아니라 사기를 올리는 역할도 합니다. 마음대로 다룰 수 있는 엄청난 힘이 우리에게 있다는 사실을 백성에게 보여주죠. 그것만으로도... 우리는 거의 모든 일을 해낼 수 있습니다.', `MaleText_loc4`='这不只是简单的美化措施，同样也可以振奋士气。它向我们的人民证明了我们拥有着多么巨大的力量，凭借这种力量……我们可以去做任何事。', `MaleText_loc5`='這不只是個裝飾的方法，也是提高士氣的手段。它向我們的人民說明我們手上握有大量的力量，因此...我們幾乎可以做任何事。', `MaleText_loc7`='No es solo una medida de embellecimiento, sino también una inyección de moral. Demuestra a nuestro pueblo que tenemos mucho poder en las yemas de los dedos, y con él... podemos hacerlo prácticamente todo.' WHERE `ID`=14895;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='깊은 생각에 잠긴 %s|1이;가; 집게손가락으로 뺨을 두드립니다.', `FemaleText_loc4`='%s用手指轻拍着她的下巴，陷入了沉思。', `FemaleText_loc5`='%s用一隻手指輕敲她的下巴，陷入沉思。', `FemaleText_loc7`='%s posa un dedo sobre la mejilla, perdida en sus pensamientos.' WHERE `ID`=14896;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 내가 여기 책임자였다면 제일 먼저 저 짓거리를 멈췄을걸. 내 말 잊지 말라고.', `MaleText_loc4`='哎！如果我可以掌管这个地方，我要做的第一件事情就是停止这些花哨的东西。你记住我的话。', `MaleText_loc5`='呸!如果讓我來掌管這個地方，我要做的第一件事就是阻止那一切。記住我的話。', `MaleText_loc7`='¡Bah! Si alguna vez estoy al mando de este lugar, lo primero que haré será parar todo eso. Escucha bien lo que te digo.' WHERE `ID`=14897;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제발 그만둬요, 타타이! 우리는 여기 손님으로 온 거예요.', `FemaleText_loc4`='塔泰，不要这样。我们是客人。', `FemaleText_loc5`='塔泰，拜託。我們是這裡的客人。', `FemaleText_loc7`='Tatai, por favor. Somos invitados.' WHERE `ID`=14898;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 그러니까... 우리 모두에게 다행스럽게도 트롤은 아름다운 우리 도시 내에서 당분간 그 어떤 권력도 잡지 못할 것 같습니다.', `MaleText_loc4`='是啊，其实……对我们来说很幸运，巨魔无论何时都不会在我们美丽的城市里占据重要的位置。', `MaleText_loc5`='是的，呃...我們都很幸運，食人妖還不會那麼快接下我們城裡的權力職位。', `MaleText_loc7`='Sí, bueno... Afortunadamente para todos, los trols no ocuparán ningún puesto de poder en esta ciudad en bastante tiempo.' WHERE `ID`=14899;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 생각에는 적당한 것 같군. 힘을 사용하는 것을 두려워하지 않는다는 사실을 적과 동맹 모두에게 보여주니까.', `FemaleText_loc4`='我可以理解你们的良苦用心。你们让所有人，不管是敌人还是同盟，都知道你们不再害怕使用你们的力量了。', `FemaleText_loc5`='一筆可理解的支出，在我看來。讓所有人，不管是敵人或盟友，讓他們知道你不怕使用你的力量。', `FemaleText_loc7`='En mi opinión, es un gasto razonable. Muestra a todo el mundo, enemigos y aliados por igual, que no tienes miedo de usar tu poder.' WHERE `ID`=14900;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 비전 수정점을 치기 시작합니다.', `MaleText_loc4`='%s开始施放一个占卜法术。', `MaleText_loc5`='%s開始進行一個秘法占卜。', `MaleText_loc7`='%s comienza a realizar una visión Arcana.' WHERE `ID`=14901;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 빌어먹을 수정구 같으니라고! 아무것도 나타나지 않잖아!', `MaleText_loc4`='该死的占卜水晶！我什么都看不到。', `MaleText_loc5`='可惡!我在這裡得不到任何東西。', `MaleText_loc7`='¡Maldito cristal de visión! No consigo nada por aquí.' WHERE `ID`=14902;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘 모르겠어요. 저에겐 그냥 낭비로만 보이네요.', `FemaleText_loc4`='也许吧。但它始终看上去很浪费。', `FemaleText_loc5`='我不知道。這看起來還是很浪費。', `FemaleText_loc7`='No sé. A mí me parece un despilfarro.' WHERE `ID`=14903;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이것들은 어떻게 스스로 떠다니지?', `MaleText_loc4`='为啥这些东西都能自己漂浮在空中？', `MaleText_loc5`='為什麼這些東西都會自己漂浮移動?', `MaleText_loc7`='¿Po'' qué flotan y giran todos esos chismes?' WHERE `ID`=14904;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='켈레마르 대사, 그대가 선택한 장식이 참 흥미롭군. 말해 보게. 비전 마법을 이용해 하필 왜 저렇게 시시한 치장을 했지?', `FemaleText_loc4`='你们选择的装饰真是引人入胜，克雷玛尔。告诉我，为什么要搞这些没用的东西？', `FemaleText_loc5`='你的裝潢品味很有趣，凱勒瑪爾。告訴我 - 為何選擇秘法裝飾品?', `FemaleText_loc7`='Tu selección del decorado me intriga, Kelemar. Dime, ¿por qué toda esa parafernalia arcana?' WHERE `ID`=14905;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아직은 로르테마르 테론을 만날 수 없는 모양인데?', `FemaleText_loc4`='洛瑟玛·塞隆有空接见我们了吗？', `FemaleText_loc5`='我想洛索瑪·塞隆還沒空見我們一面吧?', `FemaleText_loc7`='Supongo que Lor''themar Theron no puede recibirme todavía, ¿verdad?' WHERE `ID`=14906;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='섭정께서는 매우 바쁜 분입니다. 여러분께서 이해해주시기 바랍니다.', `MaleText_loc4`='摄政王是个非常忙碌的人。我相信你能懂得这一点。', `MaleText_loc5`='攝政王是個非常忙碌的人。我相信你能理解。', `MaleText_loc7`='El Señor regente es una persona muy ocupada. Estoy seguro de que lo entiendes.' WHERE `ID`=14907;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 그분은 여러분을 만날 시간이 없지만 너무 걱정하지 마십시오. 바쁜 일정을 쪼개서라도 여러분과 만날 방안을 찾아내실 테니까요.', `MaleText_loc4`='他现在还不能和你会面，但不用担心。我确信他会找到合适的机会，在他繁忙的日程中与你们会面。', `MaleText_loc5`='他還不能見你們，但你們不用為此煩心。我相信他會在百忙中抽空和你們見面的。', `MaleText_loc7`='Todavía no puede veros, pero no os preocupéis por ello. Estoy seguro de que encontrará una forma de meteros en su apretada agenda.' WHERE `ID`=14908;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일이 잘 풀렸습니다. 어떤 공격도 없을 것이며 언제까지나 우리는 여러분을 환대할 것입니다. 트롤까지도 말입니다.', `MaleText_loc4`='在适当的时候肯定可以，不用着急。不管怎样，我们都是非常好客的，甚至对巨魔都一样。', `MaleText_loc5`='在正常的程序中。沒有匆忙，畢竟 - 我們的敵意會無限地向你延伸。就算食人妖也一樣。', `MaleText_loc7`='En su debido momento. No hay prisas. Todos podéis disfrutar de nuestra hospitalidad indefinidamente. Hasta los trols.' WHERE `ID`=14909;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='켈레마르, 당분간은 그 답변을 믿고 기다리겠네. 하지만, 내 인내심도 한계가 있는 법이네.', `FemaleText_loc4`='我们暂时接受你的解释，克雷玛尔。不过我们的耐心是有限的。', `FemaleText_loc5`='我暫時接受那個答案，凱勒瑪爾，但我的耐心並不是永無止境。', `FemaleText_loc7`='Aceptaré esa respuesta por ahora, Kelemar, pero mi paciencia tiene límites.' WHERE `ID`=14910;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 생각한 그대로군. 또 연기될 줄 알았어.', `MaleText_loc4`='就像我所想的那样。又拖延了。', `MaleText_loc5`='跟我想的一樣。更多的延遲。', `MaleText_loc7`='Justo lo que pensaba. Más retrasos.' WHERE `ID`=14911;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 되먹지 못한 트롤 같으니라고. 그렇게 주둥이를 아무렇게나 놀린다면 내 기꺼이 그 입을 막아주마.', `FemaleText_loc4`='巨魔，如果你的舌头不能使用礼貌的措辞，我会很高兴帮你去掉它的。', `FemaleText_loc5`='食人妖，如果你不能記住文明的說話方式，我很樂意為你將它移除。', `FemaleText_loc7`='Troll, si no eres capaz de que esa lengua hable de forma civilizada, estaré encantada de arrancártela.' WHERE `ID`=14912;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가... 가까이 오지 마.', `MaleText_loc4`='离我远点。', `MaleText_loc5`='離我遠一點。', `MaleText_loc7`='T''escondes de mí.' WHERE `ID`=14913;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 의기양양한 미소를 짓습니다.', `FemaleText_loc4`='%s耀武扬威地笑着。', `FemaleText_loc5`='%s得意洋洋地奸笑。', `FemaleText_loc7`='%s sonríe con satisfacción.' WHERE `ID`=14914;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='점점 지겨워지는군.', `FemaleText_loc4`='我开始有点无聊了。', `FemaleText_loc5`='這開始變的令人厭倦。', `FemaleText_loc7`='Esto empieza a aburrirme.' WHERE `ID`=14915;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='켈레마르 대사, 그렇게 하죠. 기다리겠어요.', `FemaleText_loc4`='没关系，大使。我们可以等。', `FemaleText_loc5`='您說的是，大使。我們可以等。', `FemaleText_loc7`='Como digas, embajador. Podemos esperar.' WHERE `ID`=14916;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='분명 섭정과 만나기로 했었던 것 같은데... 지금 섭정이 자리에 있는 건지 없는 건지 의문이 들기 시작하는군.', `FemaleText_loc4`='我想我们应该去和摄政王谈谈了，现在我甚至开始怀疑他是否真的存在了。', `FemaleText_loc5`='我以為我們要和攝政王談話。我開始懷疑他究竟是否存在這裡。', `FemaleText_loc7`='Pensaba que íbamos a hablar con el Señor regente. Empiezo a dudar de su existencia.' WHERE `ID`=14917;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이곳에는 우아한 아름다움이 있지만... 모든 나무와 식물들이 매우... 부자연스럽군요.', `FemaleText_loc4`='这个地方的景致真是美不胜收……但是这些树和植物，仍然显得如此……不自然。', `FemaleText_loc5`='這個地方有著一種永恆的美...但是所有的樹和植物，還是很...不自然。', `FemaleText_loc7`='Este lugar tiene cierta belleza etérea..., pero la vegetación me sigue pareciendo muy... antinatural.' WHERE `ID`=14918;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미치겠군. 이 엘프들이 마치 내가 뭘 훔치기라도 한 것처럼 쳐다보잖아.', `MaleText_loc4`='我有点感到厌烦了，你们这些血精灵们，不要像我偷了什么东西那样对待我。', `MaleText_loc5`='我開始感到厭倦了。這些精靈，他們把我當小偷一樣對待。', `MaleText_loc7`='Me e''toy cansando de eto. ¡Elfos me tratan como un ladrón!' WHERE `ID`=14919;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오레보르 피난처에 온 것을 환영하오, 친구여. 여기서는 아무것도 두려워할 필요가 없소. 우리는 뒤틀린 드레나이지만 당신의 적이 아니오.$B$B나는 쿠레나이의 이쿠티라고 하오. 쿠레나이는 드레나이 형제들과 그들의 새로운 동맹 간의 관계를 다시 수립하고자 하는 뒤틀린 드레나이의 단체요.', `MaleText_loc4`='朋友，欢迎来到奥雷柏尔营地。在这里你没有什么可以感到恐惧的。我们是破碎者，但并不是你的敌人。$B$B我是库雷尼的伊库提，我们是一群期望和德莱尼兄弟以及他们新结识的同盟们重建联系的破碎者。', `MaleText_loc5`='歡迎來到奧雷伯爾港，朋友。在這裡沒有什麼好怕的。我們是破碎者，但我們不是你的敵人。$B$B我是卡爾奈的伊庫堤，我們是一群想和德萊尼兄弟及他們新找到的盟友重新建立關係的破碎者。', `MaleText_loc7`='$gBienvenido:Bienvenida; al Puerto Orebor, $gamigo:amiga;. Aquí no tienes nada que temer. Somos Tábidos, pero no somos enemigos.$B$BYo soy Ikuti de los Kurenai, un grupo de Tábidos que desean recuperar las relaciones con los hermanos draenei y sus nuevos aliados.' WHERE `ID`=14920;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='막투는 $r인 당신이 누군지는 모르겠지만 만나서 반갑습니다. 갑옷을 구입하거나 수리하시려거든 이 막투를 찾아주십시오.', `MaleText_loc4`='玛克图不认识你，$r。但是他很高兴和你相识。如果你需要购买或修理，就找玛克图。', `MaleText_loc5`='瑪克吐沒有認出你來，$r，但他很高興見到你。如果你需要購買或修理護甲，別找別人，要找瑪克吐。', `MaleText_loc7`='Maktu no te reconoce, $r, pero está encantado de verte. Si necesitas comprar o reparar armadura, ven a ver a Maktu.' WHERE `ID`=14921;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='트롤이여, 모두 그대의 선조 때문이 아닐까요? 녹색 피부를 가진 그대의 종족과 수십 년 동안 싸운 결과 우리의 마음은 아직도 싸늘하답니다.', `MaleText_loc4`='我恐怕是你们祖先的原因，巨魔。和你们那些绿皮肤的伙伴战斗了几十年之后，他们难免不厌恶你们。', `MaleText_loc5`='我怕你的祖先就是原因，食人妖。幾十年來和你的綠皮膚同胞作戰已讓他們的心臟更強壯，更不怕你的族人。', `MaleText_loc7`='Me temo que la causa son tus ancestros, troll. Tras decenios luchando contra tus soldados pieles verdes, es normal que los corazones todavía conserven algo de aversión.' WHERE `ID`=14922;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='막투, 물건을 보여주십시오.', `MaleText_loc4`='给我看看你的货物，玛克图。', `MaleText_loc5`='讓我看看你的商品，瑪克吐。', `MaleText_loc7`='Enséñame tu mercancía, Maktu.', `FemaleText_loc1`='막투, 물건을 보여주세요.', `FemaleText_loc4`='给我看看你的货物，玛克图。', `FemaleText_loc5`='讓我看看你的商品，瑪克吐。', `FemaleText_loc7`='Enséñame tu mercancía, Maktu.' WHERE `ID`=14923;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 신전에 대한 기억이 짙은 안개처럼 내 마음을 덮고 있지만 기억을 되짚어 조리 있는 이야기를 만들지는 못하겠습니다. 이곳이 다시 내게 무언가의 의미가 되었습니다. 기억을 되찾을 때까지는 내 일부가 없는 것 같은 느낌이 들 겁니다.$B$B아마 드레나이가 잃어버린 제 기억을 되찾도록 도와줄 수 있지 않을까요?', `MaleText_loc4`='这座神殿留给我的记忆好像一层浓重的雾，至今我都不能把它组织成一个连贯的故事。这个地方应该曾经对我意味着什么……除非我能恢复那部分记忆，否则我会觉得我的记忆缺少了什么。$B$B也许德莱尼人可以帮助我恢复失去的记忆。', `MaleText_loc5`='這座神廟的回憶像一層厚厚的霧氣覆蓋了我的心靈，但我不能把它們拼湊成一個有條理的故事。這個地方曾對我而言有著某種意義。除非我可以重拾記憶，否則我會覺得一部分的自己不見了。$B$B或許德萊尼可以幫我想起我所遺忘的事情。', `MaleText_loc7`='Los recuerdos de este templo me envuelven la mente como una bruma espesa, pero no consigo formar una historia coherente con ellos. Este lugar significó algo para mí antaño. Hasta que pueda recuperar ese recuerdo, me sentiré como si faltara parte de mí.$B$BQuizás los draenei puedan ayudarme a recuperar lo que he perdido.' WHERE `ID`=14924;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물건을 좀 살펴보고 싶군요.', `MaleText_loc4`='我想要看看你出售的货物。', `MaleText_loc5`='我想看看你的貨物。', `MaleText_loc7`='Me gustaría echar un vistazo a tus mercancías.', `FemaleText_loc1`='물건을 좀 살펴보고 싶군요.', `FemaleText_loc4`='我想要看看你出售的货物。', `FemaleText_loc5`='我想看看你的貨物。', `FemaleText_loc7`='Me gustaría echar un vistazo a tus mercancías.' WHERE `ID`=14925;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼굴을 드십시오. 시간이 지나면 우리 백성도 그대를 적이 아닌 동맹으로 인식할 것입니다.', `MaleText_loc4`='不要灰心。也许随着时间的推移，我们的人民会把你们作为同盟那样看待，而不是敌人。', `MaleText_loc5`='把你的下巴抬高。或許隨著時間過去，我們的人民會視你為盟友，而不是你現在看起來的敵人。', `MaleText_loc7`='No te aflijas. Puede que con el tiempo nuestra gente te vea como el aliado que eres y no como el enemigo que pareces.' WHERE `ID`=14926;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='타타이, 자네는 저 표정에 익숙해져야 해. 자네가 사절단에 선발된 이유를 기억하나?', `FemaleText_loc4`='塔泰，你应该早就习惯了。你还记得你被派来做这份工作的原因吗？', `FemaleText_loc5`='你應該對那些眼神習慣了，塔泰。你還記得當初被徵集來做這份工作的理由嗎?', `FemaleText_loc7`='Deberías estar acostumbrado a este aspecto, Tatai. ¿Recuerdas la razón por la que estás haciendo este trabajo?' WHERE `ID`=14927;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만하게...', `MaleText_loc4`='闭嘴……', `MaleText_loc5`='不准開始...', `MaleText_loc7`='No empieces...' WHERE `ID`=14928;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자네는 감시당해서 불쾌하겠지만, 나름대로 나도 자네 뒤치다꺼리가 달갑지만은 않아. 이것만은 알아 두게... 상황이 훨씬 나빠질 수도 있었다고.', `FemaleText_loc4`='当你的保姆要比看着你更让我不爽。给我记住……要不是我的话，事情可能更糟糕。', `FemaleText_loc5`='當你的保姆並不會比監視你讓我高興。記住...這並不是最糟的情形。', `FemaleText_loc7`='No estoy más contenta de ser tu canguro de lo que tú lo estás de ser observado. Solo recuerda... podría haber sido peor.' WHERE `ID`=14929;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='독 재료와 물품을 구경하고 싶습니다.', `MaleText_loc4`='让我看看你出售的材料和毒药。', `MaleText_loc5`='讓我看看你的試劑和毒藥補給。', `MaleText_loc7`='Déjame ver tus componentes y tus venenos.', `FemaleText_loc1`='독 재료와 물품을 구경하고 싶어요.', `FemaleText_loc4`='让我看看你出售的材料和毒药。', `FemaleText_loc5`='讓我看看你的試劑和毒藥補給。', `FemaleText_loc7`='Déjame ver tus componentes y tus venenos.' WHERE `ID`=14930;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저를 ''팀''이라고 부르는 이들도 있지만 제 친구들에게 저는 ''전문가''로 통한답니다.', `MaleText_loc4`='有些人叫我“提姆”，但是对我的朋友来说，我是“专家”。', `MaleText_loc5`='有些人可以叫我「提姆」，但對我朋友而言，我是「專家」。', `MaleText_loc7`='Algunos me llaman "Tim", pero para mis amigos soy "el especialista".' WHERE `ID`=14931;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전문가라고요? 어떤 분야의 전문가 말입니까?', `MaleText_loc4`='专家，嗯？那么你是哪一方面的专家？', `MaleText_loc5`='專家，是嗎?不過，你是哪種類型的專家?', `MaleText_loc7`='Un especialista, ¿verdad? ¿Qué clase de especialista eres?', `FemaleText_loc1`='전문가라고요? 어떤 분야의 전문가 말인가요?', `FemaleText_loc4`='专家，嗯？那么你是哪一方面的专家？', `FemaleText_loc5`='專家，是嗎?不過，你是哪種類型的專家?', `FemaleText_loc7`='Un especialista, ¿verdad? ¿Qué clase de especialista eres?' WHERE `ID`=14932;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런 걸 물어보시다니 제가 전문가라는 호칭을 사용할 만한 사람으로 보이지 않나 보군요. 흠...', `MaleText_loc4`='坦率地说，你还不够和我熟络到可以使用那个昵称。', `MaleText_loc5`='如果你要問，你根本不了解我，不足以使用那個稱號。', `MaleText_loc7`='Si lo preguntas, es que no hay confianza suficiente como para que uses ese apelativo.' WHERE `ID`=14933;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, $c|1이여;여;. 당신의 사냥 실력을 한계까지 시험해 보고 싶습니까? 멀리서 찾을 필요 없습니다.$B$B헤멧 네싱워리가 이 세계의 생존자들이 알고 있는 그 어떤 탐험대보다도 훌륭한 조직을 구성했습니다. 용기가 있다면 우리 탐험대에 들어오십시오.', `MaleText_loc4`='你好，$c。你想突破你的狩猎能力的极限吗？不用到处寻找了。$B$B赫米特·奈辛瓦里集合了这个世界上最好的探险队员。如果你够胆，就加入我们的队伍吧。', `MaleText_loc5`='你好，$c。你想將你的獵人本領發展到極限嗎?就是這裡了。$B$B赫米特·奈辛瓦里召集了這世界上有史以來最厲害的遠征隊。如果你敢的話就加入我們的狩獵旅行隊。', `MaleText_loc7`='Saludos, $c. ¿Quieres cazar al límite? No busques más.$B$BHemet Nesingwary ha reunido a la mejor expedición jamás vista sobre los restos de este mundo. Ven con nosotros de safari si te atreves.' WHERE `ID`=14934;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 주변에 폐허가 있다고 해서 달라란이 멸망했다고는 생각하지 마십시오. 달라란은 그 어느 때보다도 강력합니다.', `MaleText_loc4`='不要被我们周围的废墟所蒙蔽，$c。达拉然仍然像以前那样强大。', `MaleText_loc5`='別被我們身邊這些廢墟搞糊塗了，$c。達拉然一如往常的強大。', `MaleText_loc7`='No dejes que las ruinas que nos rodean te engañen, $c. Dalaran es tan poderosa como siempre.' WHERE `ID`=14935;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카라잔은 단순한 건물이 아니오. 아제로스를 관통하는 지맥을 추적한 거라면 지맥이 바로 저리로 집중되는 것을 알 수 있소.$B$B<탑 아래의 눈에 보이지 않는 지점을 가리키는 알투루스>$B$B멋지지 않소?', `MaleText_loc4`='卡拉赞不仅仅是一座建筑物，$n。如果你追踪那些穿越艾泽拉斯的魔网能量线，就会发现它们全部都聚集在这里。$B$B<奥图鲁斯指了指高塔下方的一个看不见的位置。>$B$B非常迷人吧，不是吗？', `MaleText_loc5`='卡拉贊不只是個建築物，$n。如果你追溯橫跨艾澤拉斯的能量界線，你會發現它們都會合在那裡。$B$B<艾特羅斯指向哨塔下隱密的一點。>$B$B很棒，對吧?', `MaleText_loc7`='Karazhan es más que un simple edificio, $n. Si trazaras las líneas-ley que atraviesan Azeroth, verías que todas convergen justo ahí.$B$B<Alturus señala un punto invisible bajo la torre.>$B$BFascinante, ¿verdad?' WHERE `ID`=14936;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대마법사 알바리욱스는 한때 흥미로운 이론을 연구한 논문을 썼다오. 그는 다른 세계에도 카라잔과 똑같은 곳이 있으며 같은 공간을 공유하고 있다고 주장했지.$B$B정말 안타깝게도 얼마 후 그는 정신병자가 됐다오.', `MaleText_loc4`='大法师奥瓦鲁克斯曾经写过一篇论文，探讨一个非常迷人的理论。他提出在另外一个世界有个原样复制的卡拉赞，而且两个卡拉赞之间由于某种未知原因共享着相同的空间。$B$B他不久以后就疯了。多遗憾啊。', `MaleText_loc5`='大法師艾發瑞克斯曾寫過一篇探索迷人理論的論文。他提到除了我們的世界之外，在另一個空間裏也有個一模一樣的卡拉贊，而它們兩個恰巧位於同一個地點。$B$B他後來就瘋了。真的很可惜。', `MaleText_loc7`='El archimago Alvareux escribió hace tiempo un tratado en el que desarrollaba una teoría fascinante. Proponía la existencia de una copia exacta de Karazhan en un mundo diferente al nuestro, pero que, de algún modo, compartía nuestro propio espacio.$B$BSe volvió loco poco después. Una lástima.' WHERE `ID`=14937;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기에는 악명 높은 범죄자들과 사악한 생물들에게 현상금이 걸려 있다는 게시물이 붙어 있습니다. 이 현상금을 노리기에는 지금 당장은 너무 위험한 것 같습니다. 나중에 다시 확인하는 게 좋겠습니다.', `MaleText_loc4`='那些声名狼藉的罪犯与凶兽的悬赏被张贴在这里。对现在的你来说，这些悬赏实在太危险了，当你变强后再回来看看吧。', `MaleText_loc5`='獎勵捕獲惡名昭彰的罪犯和邪惡的動物的懸賞就貼在這裡。現在就去追求這份賞金對你而言還太危險了，等你獲得了力量之後再來看這塊佈告。', `MaleText_loc7`='Aquí se publican las recompensas ofrecidas por animales malignos y criminales peligrosos. Para ti, la recompensa publicada aquí es demasiado peligrosa, pero vuelve a comprobar el tablón cuando seas más fuerte.' WHERE `ID`=14938;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나루는 우리의 상상을 초월할 정도로 현명하다오. 난 수년 동안 달라란의 도서관에서 배운 것보다 지난 5개월 동안 아달에게 더 많은 것을 배웠소.', `MaleText_loc4`='纳鲁的智慧远远超出我们的理解。在过去的五个月里，我从阿达尔那里学到的东西，远比我这么多年在达拉然图书馆里学到的还多。', `MaleText_loc5`='那魯比我們想像的還要聰明。過去五個月我從阿達歐那裡學到比我在達拉然圖書館那些年更多事情。', `MaleText_loc7`='Los naaru poseen una sabiduría que no podemos comprender. He aprendido más cosas de A''dal en los últimos cinco meses que en todos los años que pasé en las bibliotecas de Dalaran.' WHERE `ID`=14939;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='현상 수배: 죽음의 발톱이라는 단어 위에 두꺼운 붉은색 사선이 그려져 있습니다. 똑같은 붉은색 잉크로 "$n|1이라는;라는; 영웅이 무시무시한 야수를 해치우고 현상금을 차지했습니다."라는 문구와 함께 다른 내용이 적혀 있습니다.', `MaleText_loc4`='通缉令上画着一条粗大的红色横线：死爪。“这笔赏金已经被英勇的$n领走了，他战胜了那个可怕的野兽。”以相同的红墨水书写的声明叙述了更多的细节。', `MaleText_loc5`='一條粗粗的紅色斜線被畫過佈告懸賞:死亡之爪。「此賞金由英勇的$n獲得，他征服了可怕的野獸」，還有更多內容以相同的紅色墨水寫著。', `MaleText_loc7`='Una gruesa línea roja ha sido trazada atravesando las palabras SE BUSCA: Garraletal. "Esta recompensa ha sido exigida por $n, de cualidades heroicas, que ha derrotado a la temible bestia," proclama más escritura en la misma tinta roja.' WHERE `ID`=14940;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 현상 수배 푯말에는 다양한 공고와 보상에 대한 통지가 담겨 있습니다.', `MaleText_loc4`='这块公告牌贴着各种通知与奖赏单。', `MaleText_loc5`='這塊告示牌上有著各種佈告和懸賞告示。', `MaleText_loc7`='Este panel contiene varios anuncios y noticias sobre recompensas.' WHERE `ID`=14941;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='행운을 빌어요, 즐거운 시간 되세요!', `MaleText_loc4`='GLHF! <PH>', `MaleText_loc5`='GLHF! <PH>', `MaleText_loc7`='¡GLHF! <PH>' WHERE `ID`=14942;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 해보겠습니다!', `MaleText_loc4`='让我飞吧！', `MaleText_loc5`='讓我飛!', `MaleText_loc7`='¡Déjame volar!', `FemaleText_loc1`='제가 해보겠습니다!', `FemaleText_loc4`='让我飞吧！', `FemaleText_loc5`='讓我飛!', `FemaleText_loc7`='¡Déjame volar!' WHERE `ID`=14943;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='완벽한 장소로군! 설치를 시작해야겠어...', `MaleText_loc4`='这个位置太棒了！我们开始准备吧……', `MaleText_loc5`='這個地點真是完美!讓我準備一下...', `MaleText_loc7`='¡Este sitio es perfecto! Déjame montar...' WHERE `ID`=14944;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자브라진에 온 것을 환영하네. 난 이 기지의 감독관이자 장가르 습지대에 주둔하고 있는 검은창 군대의 사령관인 어둠사냥꾼 덴자이라고 하네.', `MaleText_loc4`='欢迎来到萨布拉金，$c。 我是暗影猎手德恩加，这个前哨站的督军和暗矛部族在赞加沼泽的司令官。', `MaleText_loc5`='歡迎來到薩布拉金，$c。我是暗影獵人丹傑，這座前哨站的監督者，也是贊格沼澤的暗矛軍隊指揮官。', `MaleText_loc7`='$gBienvenido:Bienvenida; a Zabra''jin, $c. Soy el cazador de las Sombras Denjai, supervisor de esta Avanzada y comandante de las fuerzas de Lanza Negra destacadas en la Marisma de Zangar.' WHERE `ID`=14945;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 내 아기 멀록들을 데려가는 게 어떻겠나?! 나에게는 매처럼 날카로운 눈과... 뭐더라... 그러니까, 청력이 뛰어난 어떤 동물과 같은 귀가 있네!', `MaleText_loc4`='别妄想把我的鱼人宝宝从我身边夺走！我有鹰的眼睛和像……像……有着强大力量的什么东西的耳朵！', `MaleText_loc5`='現在你別想試圖逃跑小魚人!我有著像老鷹一樣的眼睛，像...像...像某種有強大能量動物的耳朵!', `MaleText_loc7`='¡Ni se os ocurra pensar en intentar huir de mí, bebés múrloc! ¡Tengo ojos de halcón y orejas de... orejas de... de algo con orejas muy poderosas!' WHERE `ID`=14946;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='토르가쉬는 새의 내장을 들여다 보거나 선조의 뼈를 던져서 미래를 점칠 수 있다고 믿고 있습니다. 사실 우리가 할 일은 조용히 정령들에게 물어보는 것뿐인데 말이죠. 하지만, 그에게는 이런 말은 하지 마십시오. 그는 고집이 무척 세답니다.', `FemaleText_loc4`='托尔加什相信他可以通过鸟的肠子或者通过摇骨头预测未来。但实际上，你所要做的就是询问那些灵魂。不过别告诉他这些，$n。他是个很固执的家伙。', `FemaleText_loc5`='巫醫托卡斯相信他可以在鳥的內臟裡或擲祖先的指關節骨來預測未來。真的，你所要做的就是詢問靈魂。但不要告訴他，$n。他很固執。', `FemaleText_loc7`='Tor''gash cree que puede ver el futuro en las entrañas de los pájaros o lanzando los huesos de caña de sus ancestros. En realidad todo lo que hace falta es preguntar a los espíritus. Pero no intentes contarle esto, $n. Es muy terco.' WHERE `ID`=14947;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전투 보상 로봇, 얼라이언스', `FemaleText_loc4`='TugofWar Buffbot, 联盟', `FemaleText_loc5`='競賽祝福者，聯盟', `FemaleText_loc7`='TugofWar Buffbot, Alianza' WHERE `ID`=14948;
