UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투 보상 로봇, 제게 보상을 주십시오.', `MaleText_loc4`='TugofWar Buffbot,给我个奖励。', `MaleText_loc5`='競賽祝福者，請給我獎賞。', `MaleText_loc7`='TugofWar Buffbot, dame una recompensa', `FemaleText_loc1`='전투 보상 로봇, 제게 보상을 주십시오.', `FemaleText_loc4`='TugofWar Buffbot, 给我个奖励', `FemaleText_loc5`='競賽祝福者，請給我獎賞。', `FemaleText_loc7`='TugofWar Buffbot, dame una recompensa' WHERE `ID`=14950;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전투 보상 로봇, 호드 승리자', `FemaleText_loc4`='TugofWar Buffbot, 部落胜者', `FemaleText_loc5`='競賽祝福者，部落優勝者', `FemaleText_loc7`='TugofWar Buffbot, ganador de la Horda' WHERE `ID`=14951;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전투 보상 로봇, 호드 인사', `FemaleText_loc4`='TugofWar Buffbot, 部落问候', `FemaleText_loc5`='競賽祝福者，部落你好', `FemaleText_loc7`='TugofWar Buffbot, saludo de la Horda' WHERE `ID`=14952;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더는 탈 자리가 없습니다! 곧 운행이 다시 시작될 겁니다...', `MaleText_loc4`='There are no more available rides! There should be one available very soon... <PH>', `MaleText_loc5`='沒有可用的交通工具了!應該很快就會有一個了...<PH>', `MaleText_loc7`='¡No hay más paseos disponibles! Muy pronto debería haber uno disponible... <PH>' WHERE `ID`=14953;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 자신이 매우 유능한 사냥꾼이라는 것을 증명했소. 하지만, 당신의 꿈에 나타나는 야수 하나가 아직 남았지 않소? 바로 뿔엄니 말이오!', `MaleText_loc4`='你已经证明了自己是个合格的猎人，$n。但是还有一种猎物令你寝食难安……那就是塔丝克！', `MaleText_loc5`='你已證明自己是個非常稱職的王牌獵人，$n。但仍有一隻野獸還縈繞在你夢中...長牙!', `MaleText_loc7`='Has demostrado ser $gun cazador:una cazadora; muy capaz, $n. Pero todavía hay una bestia que se aparece en tus sueños... ¡Eburnia!' WHERE `ID`=14954;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 바취로, 반타르, 굶주린 검은갈고리, 심지어 강력한 뿔엄니까지 모두 무릎 꿇게 한 장본인이오! 당신은 내가 알고 있는 최고의 사냥꾼이오!', `MaleText_loc4`='你猎获了巴克洛尔、班塔尔和裂肠者，甚至连强大的塔丝克也不是你的对手！你是我所认识的最优秀的猎手！', `MaleText_loc5`='你已捕獲他們全部了:巴奇洛爾，班薩爾，卡特瑞普，還有強大的長牙!你真的是我所認識最厲害的王牌獵人!', `MaleText_loc7`='Los has metido a todos en el saco: Bach''lor, Banthar, Arrancatripas, y ¡hasta la poderosa Eburnia! ¡Realmente eres $gel mejor cazador:la mejor cazadora; que conozco!' WHERE `ID`=14955;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그때 저는 가시투성이 풀숲에서 탈부크 사슴과 육탄전을 벌이며 뒹굴었는데, 믿을 것은 오직 날카로운 단검 한 자루와...<쿨럭>... 사냥꾼의 예리한 판단력뿐이었습니다.$B$B그때 갑자기 하늘에서 다가온 사나운 바람올빼미 수컷 한 쌍이 저를 낚아챘습니다! 하지만 녀석들의 비겁한 공격은...<쿨럭>... 성공하지 못했습니다.$B$B그 녀석들의 부리를 전리품으로 챙기는 동안 저는 찰과상을 입고 세균에 감염되었지요. 지독한 병균이라 고통에 시달렸지만 저는 하루나 이틀 안에 나을 거라 확신했습니다.', `MaleText_loc4`='我曾和一头塔布羊在荆棘丛里面厮打、肉搏，我那把锋利的匕首……<咳嗽>……和猎人的智慧拯救了我。$B$B突然，一对凶猛的雄性狩猎风鹏从天空中落到我的面前！它们卑鄙的攻击……<咳嗽>……一点作用都没有起。$B$B不久以后，我就把它们的喙拿来当战利品了。我的伤口在这次搏斗中感染了，有点烦人的是，我现在很痛，但我相信会在一两天内痊愈的。', `MaleText_loc5`='我就在一塊多刺的矮樹叢裡打滾，和一隻塔巴克雄鹿正面交鋒，只有我銳利的小刀...<咳嗽>...和敏捷獵人的智力能救我。$B$B突然間一對兇猛的風翼貓頭鷹獵人從天而降朝我彈過來!他們懦弱的攻擊...<咳嗽>...完全幫不了他們自己。$B$B雖然我拿到他們的鳥喙做為戰利品，但我也在戰鬥過程中被刮傷感染。有點令人不快，我也承受了很大的痛苦，但我相信一兩天就會好了。', `MaleText_loc7`='Y ahí estaba, cara a cara con un venado talbuk y armado solo con mi cuchillo... <tose>... y mi inteligencia de cazador curtido que me salvaría el pellejo.$B$BDe repente, ¡veo que un par de vientorrocs cazadores se lanzan sobre mí desde el cielo! Su ataque a traición... <tose> no me ayudó demasiado tampoco.$B$BMe quedé con sus picos de trofeo, pero también tengo una cicatriz infectada de recuerdo. Es muy fea y me duele mucho, pero estoy seguro de que curará en un día o dos.' WHERE `ID`=14956;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='처음에 나무보다 큰 버섯을 봤을 때는 이곳을 꼭 집으로 삼아야 하나 싶었지. 하지만, 조금만 지나면 당신도 그냥 넘기게 될 거요.', `MaleText_loc4`='那是第一次我看到比树还高的蘑菇，我不是确定是否可以把这个地方当做家。过了一会儿你才转移了视线。', `MaleText_loc5`='我第一次看到蘑菇長的比樹還要高，我不知道我是否可以稱這個地方為家。過了一陣子之後你就不再注意了。', `MaleText_loc7`='La primera vez que vi setas más altas que árboles, no tenía tanta seguridad en que pudiera llamar a este lugar hogar. Después de un tiempo, sencillamente dejas de darte cuenta.' WHERE `ID`=14957;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='직업용품을 구입하고 싶습니다.', `MaleText_loc4`='我想要购买商业技能所需的工具。', `MaleText_loc5`='我想購買交易技能的補給品。', `MaleText_loc7`='Deseo comprar material de oficio.', `FemaleText_loc1`='직업용품을 구입하고 싶어요.', `FemaleText_loc4`='我想要购买商业技能所需的工具。', `FemaleText_loc5`='我想購買交易技能的補給品。', `FemaleText_loc7`='Deseo comprar material de oficio.' WHERE `ID`=14958;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='장가르 습지대에서 지내는 동안 시간을 내서 낚시 가는 걸 잊지 마십시오. 언제 다시 물을 보게 될지 알 수 없습니다.', `FemaleText_loc4`='不要忘记当你在赞加沼泽的时候花点时间钓鱼。你从不知道什么时候你会再次看到水。', `FemaleText_loc5`='在贊格沼澤別忘了花點時間去釣魚。你永遠不知道什麼時候還會看到水源。', `FemaleText_loc7`='No olvides tomarte tu tiempo para pescar algo mientras estés en la Marisma de Zangar. Nunca sabes cuándo volverás a estar cerca del agua.' WHERE `ID`=14959;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='낚시용품을 구입하고 싶습니다.', `MaleText_loc4`='我想要购买渔具。', `MaleText_loc5`='我想向你買釣魚補給。', `MaleText_loc7`='Deseo comprar material de pesca.', `FemaleText_loc1`='낚시용품을 구입하고 싶어요.', `FemaleText_loc4`='我想要购买渔具。', `FemaleText_loc5`='我想向你買釣魚補給。', `FemaleText_loc7`='Deseo comprar material de pesca.' WHERE `ID`=14960;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='낚시 기술에 대한 조언을 부탁합니다.', `MaleText_loc4`='指点一下我的钓鱼技术吧。', `MaleText_loc5`='給我的釣魚技巧一些指點。', `MaleText_loc7`='Dame alguna sugerencia para mejorar mi técnica de pesca.', `FemaleText_loc1`='낚시 기술에 대한 조언을 부탁해요.', `FemaleText_loc4`='指点一下我的钓鱼技术吧。', `FemaleText_loc5`='給我的釣魚技巧一些指點。', `FemaleText_loc7`='Dame alguna sugerencia para mejorar mi técnica de pesca.' WHERE `ID`=14961;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한때 텔레도르는 드레나이 사제들과 순례자들의 피난처였소. 그곳에 살던 사제들을 찾아오는 이들은 거의 없었지.$B$B오크들이 드레나이의 정착지를 공격하자 난민들이 대규모로 도착하기 시작했소. 수도자인 아후른과 다른 이들이 텔레도르를 신전에서 안전한 피난처로 바꿔놓았다오. 나를 포함한 많은 드레나이들이 살아남을 수 있었던 것도 그의 노력 덕분이오.', `MaleText_loc4`='泰雷多尔对德莱尼人牧师和朝圣者来说曾经是个隐密的据点。很少会有人拜访这些隐居的牧师。$B$B当兽人开始攻击德莱尼人的时候，难民的数量多到无法想象。学者安霍尔和其他人把泰雷多尔从一座神殿转变成了一处避风港。很多德莱尼人，包括我自己，都很感谢他为拯救我们的生命所做出的一切。', `MaleText_loc5`='泰倫多爾曾是德萊尼牧師和朝聖者的隱蔽休息處。牧師居民顯少接見訪客。$B$B當獸人開始攻擊德萊尼居民們，難民開始大批到來。隱士阿浩恩和其他人將泰倫多爾從神殿轉變為一個安全的避風港。許多德萊尼，包括我自己，都欠他一個人情。', `MaleText_loc7`='Telredor era un refugio para sacerdotes draenei y peregrinos. Los sacerdotes residentes casi no reciben visitas.$B$BCuando los orcos lanzaron sus primeros ataques a los asentamientos draenei, los refugiados empezaron a llegar en masa. El anacoreta Ahuurn y los demás transformaron Telredor en un refugio seguro. Muchos draenei, yo incluido, debemos nuestras vidas a sus esfuerzos.' WHERE `ID`=14962;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='놀라운 광경이군. 좀 더 젊었을 때 못 본 게 아쉬워.', `FemaleText_loc4`='如此不可思议的奇观。我真后悔没有在年轻的时候看到它。', `FemaleText_loc5`='真是令人讚嘆的景象啊。真後悔我年輕時沒看到。', `FemaleText_loc7`='Qué vistas tan maravillosas. Lamento no haber podido verlas cuando era más joven.' WHERE `ID`=14963;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기까지 찾아와 주셔서 감사합니다. 실버문이 여러분 마음에 드셨으면 좋겠습니다.', `MaleText_loc4`='感谢你来到这里。我希望你在银月城过得开心。', `MaleText_loc5`='謝謝你到此造訪。希望你會找到喜歡的銀月城。', `MaleText_loc7`='Gracias por haber venido hasta aquí. Espero que te guste Lunargenta.' WHERE `ID`=14964;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 아름다운 도시가 지닌 신비를 느껴보십시오.', `MaleText_loc4`='看吧，我们美丽的城市。', `MaleText_loc5`='看看我們美麗城市的奇景。', `MaleText_loc7`='Contempla las maravillas de nuestra hermosa ciudad.' WHERE `ID`=14965;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='텔레도르 꼭대기에서 보는 경치는 정말 멋지지 않나요?', `FemaleText_loc4`='在泰雷多尔顶部观景真是华丽啊，难道不是吗？', `FemaleText_loc5`='泰倫多爾頂端的風景很壯觀，對吧?', `FemaleText_loc7`='Las vistas desde la cima de Telredor son magníficas, ¿verdad?' WHERE `ID`=14966;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물건을 사고 싶습니다.', `MaleText_loc4`='我想从你这儿买点东西。', `MaleText_loc5`='我想和你買東西。', `MaleText_loc7`='Me gustaría comprarte algo.', `FemaleText_loc1`='물건을 사고 싶어요.', `FemaleText_loc4`='我想从你这儿买点东西。', `FemaleText_loc5`='我想和你買東西。', `FemaleText_loc7`='Me gustaría comprarte algo.' WHERE `ID`=14967;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='텔레도르에 오신 것을 환영합니다. 필요한 게 있으면 주저 말고 말씀하십시오.', `MaleText_loc4`='欢迎来到泰雷多尔，$c。如果你有任何事情需要帮忙，尽管来找我。', `MaleText_loc5`='歡迎來到泰倫多爾，$c。如果你需要任何東西，請隨時來跟我要。', `MaleText_loc7`='$gBienvenido:Bienvenida; a Telredor, $c. Si necesitas algo, no dudes en preguntar.' WHERE `ID`=14968;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기는 너무 밝군. 내 취향은 아니야.', `MaleText_loc4`='这个地方对我来说太亮了。', `MaleText_loc5`='這地方對我而言太過生氣蓬勃。', `MaleText_loc7`='Este lugar tener demasiada luz para mi gusto.' WHERE `ID`=14969;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='머무는 동안 조심하십시오. 일부 꽉 막힌 이들이 이미 오래전에 해체된 낡은 동맹에 연연할지도 모릅니다...', `MaleText_loc4`='你在这里逗留期间可要加倍小心。一些顽固的家伙可能仍然会对我们以前的盟友心存幻想……', `MaleText_loc5`='停留的時候請提高警覺。某些思想保守的人可能在舊聯盟解散後還是忠誠於他們...', `MaleText_loc7`='Ten cuidado durante tu estancia. Algunos individuos de mente estrecha siguen creyendo en viejas alianzas ya rotas...' WHERE `ID`=14970;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물건을 사고 싶습니다.', `MaleText_loc4`='我想从你这儿买点东西。', `MaleText_loc5`='我想和你買東西。', `MaleText_loc7`='Deseo comprarte algo.', `FemaleText_loc1`='물건을 사고 싶어요.', `FemaleText_loc4`='我想从你这儿买点东西。', `FemaleText_loc5`='我想和你買東西。', `FemaleText_loc7`='Deseo comprarte algo.' WHERE `ID`=14971;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 장소에서 이렇게 여러 종류의 버섯을 보기는 처음입니다. 시간만 충분하다면 이 버섯들의 사용법을 모두 알아낼 겁니다.', `MaleText_loc4`='我从没有在同一个地方看到过这么多的蘑菇。给我足够的时间，我保证可以找到它们的所有用处。', `MaleText_loc5`='我從沒見過一個地方有那麼多不同種類的蘑菇。如果有足夠的時間，我相信我可以找出它們所有的用途。', `MaleText_loc7`='Nunca había visto tantos tipos diferentes de setas en un mismo sitio. Si me dieran el tiempo suficiente, estoy seguro de que podría encontrar un uso para cada una.' WHERE `ID`=14972;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='텔레도르는 과거 수 세기 동안 변한 것보다 지난 20년간 더 많은 변화를 겪었소. 그동안 이 세계가 급변하였기 때문에 난 아무런 불평도 할 수 없었소.$B$B성스러운 빛이 은둔 사제였던 내가 만나 볼 수 없었던 친구와 동료를 인도해 주었소. 여기서 지내는 동안 과거에 대해 최대한 많이 배우시오. $g형제:자매;의 여행이 $g형제:자매;를 어디로 인도하는지 이해하는 데 도움이 될 것이오.', `MaleText_loc4`='泰雷多尔在过去的二十年里所见证的变化，远比过去的几个世纪还要多得多。我不是在抱怨，$n。世界在那段时间里改变了很多。$B$B圣光给我带来了许多朋友和同伴，如果我还是一个闭门冥思的牧师，就根本不会有这种机会。好好利用你在这里的时间来学习一切知识吧，这可以帮助你了解你的旅程和你的目标。', `MaleText_loc5`='泰倫多爾過去20年來經歷的改變比先前幾個世紀還要來的多。我不能抱怨，$n，因為世界那些時候改變更多。$B$B聖光為我帶來了身為隱居牧師不會有的朋友和同伴。在這裡學習過去帶給你的經驗。它會幫助你了解你的旅程將帶你去哪裡。', `MaleText_loc7`='Telredor ha cambiado más en los últimos veinte años que en los siglos pasados. Yo no me quejo, $n; no es la primera vez que cambia el mundo.$B$BLa Luz me ha traído amigos y compañeros que no habría conocido como monje de clausura. Aprende lo que puedas del pasado mientras estás aquí.' WHERE `ID`=14973;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 거짓말쟁이 같으니! 죽기 직전까지 흠씬 두들겨 패주마!', `MaleText_loc4`='狡猾的家伙！我会让你生不如死！', `MaleText_loc5`='奸詐的傢伙!我會把你打到死!', `MaleText_loc7`='¡Cría traidora! ¡Te voy a golpear hasta que solo te quede un hilo de tu triste vida!' WHERE `ID`=14974;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카르다쉬의 토템을 어디다 숨겼는지 말해라. 그러면 더는 고문하지 않겠다.', `MaleText_loc4`='告诉我卡达什图腾藏在哪里，不然就继续吃我的拳头吧！', `MaleText_loc5`='告訴我卡達許圖騰藏在哪裡我們就不再打你。', `MaleText_loc7`='Dime dónde está el tótem de Kar''dash y no habrá más golpes.' WHERE `ID`=14975;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠사냥꾼인 덴자이가 이 기지를 건설할 건축가와 병사들과 함께 절 여기로 파견했소. 우리는 가까스로 건설을 마쳤는데 그는 벌써 보고서를 요청하고 있소!$B$B물건이 필요하다면 약간은 제공할 수 있지만 아직도 첫 번째 보급품이 도착하기만을 기다리는 상황이오.', `MaleText_loc4`='暗影猎手德恩加派我、建筑工和一些战士到这里来建立这座哨所。我们刚刚完工，他就已经要求汇报了！$B$B如果你需要补给，我可以给你提供一些东西，但是我们仍然在等待第一批物资。', `MaleText_loc5`='暗影獵人丹傑派我和一支由建築商和戰士組成的小分遣隊來這裡建立這座前哨。我們才剛建好而他就已經開始向我們要報告了!$B$B如果你需要補給，我可以提供一些東西，但我們仍在等待第一批貨物。', `MaleText_loc7`='El cazador de las Sombras Denjai me ha enviado con un pequeño contingente de albañiles y guerreros para establecerse en esta Avanzada. ¡Apenas hemos terminado de construirla y ya nos pide informes!$B$BSi necesitas material, puedo ofrecerte algunas cosas, pero aún esperamos nuestro primer envío.' WHERE `ID`=14976;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 고문 도중에 죽는다면 우리는 나가서 또 다른 너의 동족을 잡아올 것이야. 너희 중 한 명 정도는 분명 고통을 못 견디고 우리에게 필요한 정보를 주겠지.', `MaleText_loc4`='如果你在拷问中丧命，我们会出去再绑架一个你的同类。迟早你们之间有一个会因为受不了酷刑而招供的！', `MaleText_loc5`='你再次因折磨而死，我們會出去再抓一個你的族人。你們之中一人註定要在痛苦下屈服並給予我們需要的資訊。', `MaleText_loc7`='En cuanto mueras debido a la tortura, saldremos a secuestrar a otro de tu especie. Uno de ustedes tiene que venirse abajo por el dolor y darnos la información que necesitamos.' WHERE `ID`=14977;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카르다쉬의 토템을 손에 넣으면 우리는 너희 도시를 파괴하고 우리의 도시를 재건할 것이다.', `MaleText_loc4`='一旦卡达什图腾落入我们手中，我们就会把你们的城市夷为平地，以我们自己的方式重建它。', `MaleText_loc5`='卡達許圖騰再一次成為我們的了，我們會夷平你們的城市然後重建我們的家園。', `MaleText_loc7`='Cuando el tótem de Kar''dash sea nuestro, arrasaremos sus ciudades y las reconstruiremos como las nuestras.', `FemaleText_loc1`='카르다쉬의 토템을 손에 넣으면 우리는 너희 도시를 파괴하고 우리의 도시를 재건할 것이다.', `FemaleText_loc4`='一旦卡达什图腾落入我们手中，我们就会把你们的城市夷为平地，以我们自己的方式重建它。', `FemaleText_loc5`='卡達許圖騰再一次成為我們的了，我們會夷平你們的城市然後重建我們的家園。', `FemaleText_loc7`='Cuando el tótem de Kar''dash sea nuestro, arrasaremos sus ciudades y las reconstruiremos como las nuestras.' WHERE `ID`=14978;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물건을 사고 싶습니다.', `MaleText_loc4`='我想从你这儿买点东西。', `MaleText_loc5`='我想和你買東西。', `MaleText_loc7`='Deseo comprarte algo.', `FemaleText_loc1`='물건을 사고 싶어요.', `FemaleText_loc4`='我想从你这儿买点东西。', `FemaleText_loc5`='我想和你買東西。', `FemaleText_loc7`='Deseo comprarte algo.' WHERE `ID`=14979;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='의술사 토르가쉬를 만나면 그가 만들어준 물약과 부적이 아무 효과도 없더라고 전해 주시오! 그가 말한 그대로 했지만 마가샤는 여전히 주라이한테만 관심을 보이고 있소.$B$B그 엉터리 의술사가 하는 거짓말은 절대 믿지 마시오!', `MaleText_loc4`='如果你有机会遇到巫医托尔加什，告诉他，他的药和符咒不起作用！我完全按照他告诉我的去做，但是玛加沙仍然只把注意力放在祖莱身上。$B$B不敢相信巫医告诉我的事情竟然是假的。', `MaleText_loc5`='如果你看到巫醫托卡斯就告訴他，他的混合物和符咒根本沒用!我完全照著他的話做，但瑪卡莎眼裡還是只有祖瑞伊。$B$B不要相信那個假巫醫告訴你的任何話!', `MaleText_loc7`='¡Si te encuentras con el médico brujo Tor''gash dile que sus brebajes y sus talismanes no funcionan! Hice exactamente lo que me dijo y Magasha sigue coladita por Zurai.$B$B¡No te creas nada de lo que dice ese falso médico brujo!' WHERE `ID`=14980;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='레아비즈는 코도처럼 예민하지! 웃기는 건 그가 자신이 그렇게 뻔뻔하지 않다고 믿는다는 사실이오. 주위에 보는 눈이 없다고 생각될 때 그가 나를 보는 눈길을 알고 있소.$B$B정말 소름이 끼치지. 어둠사냥꾼 덴자이가 우리를 함께 보내지 않았으면 좋겠소. 늪쥐 감시초소를 건설하는 일은 그와 떨어질 완벽한 기회였소.', `FemaleText_loc4`='里维伊的脸皮就像科多兽那样厚！可笑的是，他并不觉得他的骚扰行为是这么的明显。我看到他直勾勾地盯着我，还自以为没人发现他。$B$B他让我觉得毛骨悚然，我真的希望暗影猎手德恩加没有派他和我们在一起。建造沼泽鼠岗哨原本是一个摆脱他的好机会。', `FemaleText_loc5`='瑞伏基擁有所有科多獸俱備的敏銳!有趣的是牠不認為自己很引人注目。我看過牠盯著我看的眼神，以為沒有人在看牠的樣子。$B$B牠讓我汗毛直豎，我多希望暗影獵人丹傑沒把牠送來和我們一起。設立斯溫派特崗哨時是個甩開牠的好時機。', `FemaleText_loc7`='¡Reavij es tan sutil como un kodo! Pero lo peor es que no se da cuenta de que se nota. Veo la forma en que me mira cuando cree que nadie lo ve.$B$BMe asusta. Desearía que el cazador de las Sombras Denjai no lo hubiera mandado con nosotros. Nos podríamos haber deshecho de él cuando montamos la Avanzada Rata del Pantano.' WHERE `ID`=14981;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, $c|1이여;여;. 저는 소위 말하는 뒤틀린 드레나이입니다. 우리 뒤틀린 드레나이들은 잃어버린 드레나이만큼 사악하지는 않지만, 그들과 마찬가지로 사악한 기운의 영향을 받아 원래 드레나이의 모습에서 변이된 모습을 하고 있답니다.', `MaleText_loc4`='你好，$c。我是被他们叫做破碎者的家伙。就像失落者那样，只不过还没像他们那么糟糕。邪能的摧残让我们从原来德莱尼人的形态转变到现在的这个样子。', `MaleText_loc5`='哈囉，$c。我就是人們口中的破碎者。和失落者一樣，雖然我們不像他們那麼壞，但我們還是對邪惡能量十分頭痛，就是它把我們從原本的德萊尼形態轉變過來的。', `MaleText_loc7`='Hola, $c. Soy lo que llaman uno de los Tábidos. Como les pasó a Los Perdidos, nosotros también sufrimos la influencia de las energías viles que corrompieron nuestro aspecto draenei original.' WHERE `ID`=14982;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가라다르는 아수라장입니다, 이방인이여. 대모께서 병에 걸린 이후 가로쉬는 심한 우울증에 빠졌습니다. 아버지를 닮은 것 같지는 않아요.$B$B<한숨을 쉬는 쿠르쿠쉬>', `MaleText_loc4`='加拉达尔现在很混乱，陌生人。自从祖母生了病，加尔鲁什变得非常沮丧。他真是一点都不像他的父亲。$B$B<古库斯叹了口气。>', `MaleText_loc5`='卡拉達爾處於一團混亂中，陌生人。自從主母生病後，卡爾洛斯就得變的意氣消沉。他已經變的不像他爸爸的兒子了。$B$B<可庫許嘆氣。>', `MaleText_loc7`='Garadar es un caos, $gextranjero:extranjera;. Desde que la Abuela enfermó, Garrosh ha caído en una profunda depresión. Desde luego no es el niño de su padre.$B$B<Kurkush suspira.>' WHERE `ID`=14983;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 힘을 내라!', `MaleText_loc4`='卖力一点！', `MaleText_loc5`='回去幹活!', `MaleText_loc7`='¡Esforzaos al máximo!' WHERE `ID`=14984;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 빨리 베라!', `MaleText_loc4`='快点砍！', `MaleText_loc5`='砍快一點!', `MaleText_loc7`='¡Cortad más aprisa!' WHERE `ID`=14985;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꾸물거리면 우두머리 그록아크께서 널 처단하실 것이다!', `MaleText_loc4`='快点，否则格罗阿克会要了你的命！', `MaleText_loc5`='動作快點否則葛洛卡老大會讓你人頭落地!', `MaleText_loc7`='¡Más rápido, o el jefe Grog''ak te cortará la cabeza!' WHERE `ID`=14986;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 직접 가서 시범을 보여줘야 되겠나?', `MaleText_loc4`='是不是需要让我过来教你该怎么做？', `MaleText_loc5`='我需要過來這裡教你如何做嗎?', `MaleText_loc7`='¿Tengo que ir allí y enseñarte cómo se hace?' WHERE `ID`=14987;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꼭 번개 화살을 날려줘야만 일을 더 빨리 하겠나?', `MaleText_loc4`='也许一发闪电箭可以让你有动力工作得更卖力一些？', `MaleText_loc5`='或許一支閃電箭會刺激你加快工作速度?', `MaleText_loc7`='¿Quizás un rayo te incentivará para trabajar más rápido?' WHERE `ID`=14988;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나무를 다 베기 전까지 휴식은 없다!', `MaleText_loc4`='在全部砍下之前，别想休息！', `MaleText_loc5`='在拿下所有人之前不要闖入!', `MaleText_loc7`='¡No hay pausas hasta que esté todo cortado!' WHERE `ID`=14989;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마침내 끝났도다! 동지들의 죽음을 애도하라! 이루지 못한 꿈을 그리며 슬피 울어라! 하크 민 코레이!', `MaleText_loc4`='终于结束了！一切都终结了！为你们的世界默哀吧！Hach min corai！', `MaleText_loc5`='我終於辦到了!為所有你知道的往生者，和所有即將往生的人哀悼吧!', `MaleText_loc7`='¡Al fin ha llegado! Lloren y lamenten la destrucción de todo aquello que han conocido y todo lo que hubiera podido ser! ¡Hach min corai!' WHERE `ID`=14990;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안돼! 이럴 수는 없어! 안돼!', `MaleText_loc4`='不，这不可能！不！！！', `MaleText_loc5`='不，不可能!不!!!!!', `MaleText_loc7`='¡No, no puede ser! ¡Nooo!' WHERE `ID`=14991;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이것들아, 다시 일을 시작해라!', `MaleText_loc4`='狗东西，回去工作！', `MaleText_loc5`='回去工作，無賴!', `MaleText_loc7`='¡Vuelve al trabajo, perro!' WHERE `ID`=14992;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 암흑갈기 일족과 피비늘 일족의 나가 지도자들에게 현상금이 걸려 있음을 알리는 벽보가 붙어 있습니다. 그 둘은 극히 위험한 놈들이므로 나중에 다시 확인하는 것이 좋을 것 같습니다.', `MaleText_loc4`='暗潮纳迦氏族和血鳞纳迦氏族首领的悬赏布告被列在这里。听说他们两个都非常危险，也许你应该以后再去看看。', `MaleText_loc5`='暗羽和血鱗部族的納迦領導者懸賞公告公佈在此。他們聽起來都相當可怕，或許你該等下再來看看。', `MaleText_loc7`='Hay una nota sobre una recompensa por los jefes nagas de Cresta Oscura y Escamas de Sangre. Parecen los dos muy peligrosos. Será mejor que vuelvas más tarde.' WHERE `ID`=14993;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='암흑갈기 일족과 피비늘 일족의 나가 지도자들에게 현상금이 걸려 있음을 알리는 벽보가 붙어 있습니다.', `MaleText_loc4`='暗潮纳迦氏族和血鳞纳迦氏族首领的悬赏布告被列在这里。', `MaleText_loc5`='暗羽和血鱗部族的納迦領導者懸賞公告公佈在此。', `MaleText_loc7`='Los anuncios de recompensas por los líderes nagas de las tribus de Cresta Oscura y Escamas de Sangre están enumerados aquí.' WHERE `ID`=14994;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들은 죽었습니다. 모두...$B$B수렁피 일족이 우리를 쓸고 갈 때 알 수 없는 뭔가 저를 붙잡았습니다. 당신은 너무 분노한 나머지 몸 전체가 타오를 것 같은 기분을 느낀 적이 있습니까? 생명을 시들게 하는 열기, 혈관 속의 피를 모조리 태울 것 같은 열기를? 바로 그때 제 기분이었죠.$B$B<잠시 두 눈이 붉게 빛나는 사울팽>$B$B저는 최후의 생존자였습니다. 30마리가 절 둘러쌌죠... 수렁피 일족 말입니다... 그 이후의 일은 기억나지 않습니다. 저는 정신을 잃었고 얼마 후 깨어났습니다.', `MaleText_loc4`='他们死了。他们全都死了……$B$B暗血氏族突袭了我们，一些我不能理解的事情充斥着我的大脑。告诉我，你有没有感到过就像你的整个生命都在燃烧那样的愤怒？一种足以让生命枯萎的愤怒，一种足以烧尽你的血液的愤怒……那就是我所感觉到的。$B$B<萨鲁法尔的眼中闪过了血红色的光芒。>$B$B我是最后一个幸存者。他们三十个人个包围了我……暗血……之后的一切我都不记得了。我昏了过去，很久才醒过来。', `MaleText_loc5`='他們死了。全部的人...$b$b當黑暗之血拿下我們，就有某種我無法理解的東西控制了我。告訴我，你曾感受過極大的憤怒，讓你整個人像在燃燒一樣嗎?一種讓生命都枯萎的高溫?一種焚化你血管的熱度?那就是我感受到的。$B$B<薩魯法爾的雙眼短暫地閃了一陣紅光。>$B$B我是最後一個活下來的人。他們30個人圍繞著我...黑暗之血...我只記得這個畫面。後來我眼前一黑，過了不知道多久才醒來。', `MaleText_loc7`='Han muerto. Todos...$B$BLos Sangreoscura pasaron a través de nosotros y algo que no puedo comprender me poseyó. Dime, ¿alguna vez has experimentado una rabia tan grande que sientes que arde todo tu ser? ¿Un ardor que marchita a los vivos? ¿Un fuego que quema la sangre de tus venas? Eso es lo que yo sentí.$B$B<Los ojos de Colmillosauro brillan con una luz roja durante un segundo.>$B$BYo fui el único que sobrevivió. Me rodearon treinta... Sangreoscura... No recuerdo nada más. Perdí el conocimiento y me desperté al poco tiempo.' WHERE `ID`=14995;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='암흑의 시기가 모습을 드러내고 있습니다, 이방인이여...', `MaleText_loc4`='黑暗就在前面，隐约可见，陌生人……', `MaleText_loc5`='黑暗時期隱約出現在前方，陌生人...', `MaleText_loc7`='Se avecinan tiempos oscuros, $gextranjero:extranjera;...' WHERE `ID`=14996;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정령들이 극도로 흥분했습니다. 이 사태의 원인을 찾아야 합니다.', `MaleText_loc4`='灵魂们非常容易激动。我们必须找到这场骚动的原因。', `MaleText_loc5`='靈魂都受到極大的煽動。我們一定要找出這次動亂的原因。', `MaleText_loc7`='Los espíritus están muy agitados. Debemos encontrar la causa de tal alteración.' WHERE `ID`=14997;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 빛나는 돌 위에 수렁피 우상을 놓고 정령을 소환합니다.', `MaleText_loc4`='%s把暗血神像放在闪电石的顶部以召唤灵魂。', `MaleText_loc5`='%s將黑暗之血塑像放在聖光之石頂端並召喚亡靈。', `MaleText_loc7`='%s coloca los ídolos Sangreoscura en lo alto de la piedra Relámpago e invoca a los espíritus.' WHERE `ID`=14998;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하시오!', `MaleText_loc4`='小心！', `MaleText_loc5`='小心!', `MaleText_loc7`='¡Cuidado!' WHERE `ID`=14999;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='녀석들이 더 많이 오고 있소! 조심하시오!', `MaleText_loc4`='又过来了一些！小心！', `MaleText_loc5`='他們有更多人追來了!小心!', `MaleText_loc7`='¡Vienen más de ellos! ¡Cuidados!' WHERE `ID`=15000;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들이 추적자들을 더 많이 보낼 경우를 대비해서 여기서 헤어지는 게 좋겠소. 우리 중 한 명은 가로쉬에게로 돌아가야 할 테니 말이오. 몸조심하시오, 이방인이여.', `MaleText_loc4`='最好我们现在就分开，以免他们派更多人来追击我们。希望我们之间有人可以成功回到加尔鲁什那里。保重，陌生人。', `MaleText_loc5`='我們最好現在分開，以免他們派更多人來追我們。希望我們之中有人能安全回到卡爾洛斯那裡。再會了，陌生人。', `MaleText_loc7`='Lo mejor es que nos separemos ahora, por si envían más a por nosotros. Con un poco de suerte, uno de nosotros conseguirá volver a Garrosh. Adiós, $gextranjero:extranjera;.' WHERE `ID`=15001;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들의 탈출을 막아라! 강한 녀석을 먼저 해치워야 한다!', `MaleText_loc4`='不要让他们跑了！先杀掉那个强壮的家伙！', `MaleText_loc5`='別讓他們逃跑!把最強壯的那個先殺了!', `MaleText_loc7`='¡No les dejéis escapar! ¡Matad primero al fuerte!' WHERE `ID`=15002;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디로 빠져나가려고 하느냐? 놈들을 모두 죽여라!', `MaleText_loc4`='想跑？没门！消灭他们！', `MaleText_loc5`='你以為你要去哪?殺光他們!', `MaleText_loc7`='¿Dónde creéis que vais? ¡Matadlos a todos!' WHERE `ID`=15003;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정령들이여, 제게 치유의 힘을 주십시오!', `MaleText_loc4`='灵魂赐予我治愈的力量！', `MaleText_loc5`='靈魂給我力量痊癒!', `MaleText_loc7`='¡Los espíritus me dan la fuerza para curar!' WHERE `ID`=15004;
