UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대지의 토템이여, 저들의 발을 묶어주십시오!', `MaleText_loc4`='大地图腾，阻止他们的前进！', `MaleText_loc5`='大地圖騰，終止他們前進!', `MaleText_loc7`='¡Tótem de la tierra, detén su avance!' WHERE `ID`=15008;
