UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='으악! 그 수정들은 제대로 작동할 거라고 했단 말이야!', `FemaleText_loc4`='唉唷。他们告诉我这些水晶可以完美运转！这帮奸商！', `FemaleText_loc5`='啊。他們跟我說那些水晶會正常運作!', `FemaleText_loc7`='Argh. ¡Me dijeron que estos cristales funcionarían correctamente!' WHERE `ID`=15013;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='물러서라, 섭정이 지나가시는 길이다! 장난 아니라고!', `FemaleText_loc4`='不要挡着摄政王的路！我说真的！', `FemaleText_loc5`='你最好不要擋住攝政王的路!我是認真的!', `FemaleText_loc7`='¡Apártate del camino del Señor regente! ¡Lo digo en serio!' WHERE `ID`=15014;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잡히면 네 부품에서 마력을 추출할 거야. 그러니까 도와줘...', `FemaleText_loc4`='要是我抓住你，我会把你的零件都给分解掉，所以你最好……', `FemaleText_loc5`='等我抓到你，我就會將你的零件都分解，所以救救我...', `FemaleText_loc7`='Cuando te pille, voy a desencantar tus piezas, te lo aseguro...' WHERE `ID`=15015;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 지니고 있는 이 모든 것들은 우리가 필사적으로 싸운 결과라네... 오크에게서 텔라아르를 되찾았으나 오우거들은 결코 쉽지 않은 상대였네.', `MaleText_loc4`='我们所拥有的一切都是浴血奋战换来的……我们从兽人手中夺回了塔拉，随后却面临食人魔的挑衅，这帮家伙就不那么容易对付了。', `MaleText_loc5`='我們所有的一切，我們已拼命地奮鬥...要先從獸人再從巨魔手中奪回泰拉不是件簡單的事。', `MaleText_loc7`='Todo lo que tenemos, lo hemos conseguido luchando con dientes y tentáculos. Retomar Telaar de los orcos, y después de los ogros, no fue tarea fácil.' WHERE `ID`=15016;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cffffff00경비병들을 모두 처치했습니다!|r', `MaleText_loc4`='|cffffff00所有的卫兵都被击败了！|r', `MaleText_loc5`='|cffffff00所有的守衛都已被擊敗!|r', `MaleText_loc7`='|cffffff00¡Han derrotado a todos los guardias!|r' WHERE `ID`=15017;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cffffff00얼라이언스가 할라아를 차지했습니다!|r', `MaleText_loc4`='|cffffff00联盟占领了哈兰！|r', `MaleText_loc5`='|cffffff00聯盟已經控制了哈剌!|r', `MaleText_loc7`='|cffffff00¡La Alianza ha tomado el control de Halaa!|r' WHERE `ID`=15018;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cffffff00호드가 할라아를 차지했습니다!|r', `MaleText_loc4`='|cffffff00部落占领了哈兰！|r', `MaleText_loc5`='|cffffff00部落已經控制了哈剌!|r', `MaleText_loc7`='|cffffff00¡La Horda ha tomado el control de Halaa!|r' WHERE `ID`=15019;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cffffff00할라아가 무방비 상태가 되었습니다!|r', `MaleText_loc4`='|cffffff00哈兰的防御力量被消灭了！|r', `MaleText_loc5`='|cffffff00哈剌毫無防禦!|r', `MaleText_loc7`='|cffffff00¡Halaa está indefensa!|r' WHERE `ID`=15020;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음, 예상치 못한 손님들이군. 준비를 해야겠어...', `MaleText_loc4`='啊，不速之客。我得准备一下……', `MaleText_loc5`='嗯，突然上門的訪客。一定要做好準備...', `MaleText_loc7`='Mm, visita inesperada. Hay que hacer los preparativos...' WHERE `ID`=15021;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 정말 미련했구나.', `MaleText_loc4`='我真是太笨拙了。', `MaleText_loc5`='我真是笨拙的可以。', `MaleText_loc7`='¡Qué torpeza de mi parte!' WHERE `ID`=15022;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헤멧은 제가 아는 가장 위대한 사냥꾼입니다. 우리는 몇 달 전 아제로스 뒤편에 있는 여명의 설원 언덕에서 우연히 만났지요. 우리는 라크쉬리라고 하는 거대한 호랑이를 같이 추적하고 있었지요.$B$B우리는 그 사냥감을 놓고 서로 싸우는 대신 내기를 했습니다. 내기인즉슨, 눈호랑이 가죽을 구하는 자의 요구를 들어주는 것이었습니다. 정말 부끄러운 일이지만 이게 바로 제가 피츠라는 별명을 얻게 된 계기입니다.', `MaleText_loc4`='赫米特是我所认识的最棒的猎人。很久以前，我们在艾泽拉斯的冬泉谷的山上偶遇。他和我正在追踪着一个相同的目标：那只名叫拉克西里的豹子。$B$B与其为了一个猎物打得头破血流，还不如下个赌注决定胜负：谁能得到霜刃豹的毛皮，就可以要求对方做些什么。那真是我一辈子的耻辱，我这“好儿子”的绰号就是这么来的。$B$B我看上去像一个“好儿子”吗？', `MaleText_loc5`='赫米特是我所知道最出色的獵人。我們幾個月前偶然在艾澤拉斯的冬泉谷大廳巧遇過。我們在追蹤同一個獵物:一隻叫拉克西里的巨豹。$B$B我們沒為了獵物打起來，而是對牠做了個賭注;誰收集到霜刃豹的皮革就可以要求對方某事。讓我永遠羞愧的是，這就是我如何得到我的綽號，費茲。$B$B我看起來像費茲嗎?', `MaleText_loc7`='Hemet es el mejor cazador que conozco. Nos topamos en las colinas de Cuna del Invierno, en Azeroth, hace muchas lunas. Él y yo acechábamos a la misma presa: el gran felino conocido como Rak''shiri.$B$BEn lugar de pelearnos por nuestra presa, hicimos una apuesta; quien consiguiera la piel del sable de hielo, podría exigirle algo al otro. Para mi vergüenza eterna, fui el que perdió.$B$B¿Tengo cara de haber ganado?' WHERE `ID`=15023;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너의 새 이름을 사예나로 정했어.', `MaleText_loc4`='你的新名字叫萨耶娜。', `MaleText_loc5`='你的新名字是莎耶娜。', `MaleText_loc7`='Tu nuevo nombre es Sayena.' WHERE `ID`=15024;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='꼬마야, 내 이름은 님리다야.', `FemaleText_loc4`='我叫尼姆瑞达，小子。', `FemaleText_loc5`='我的名字是尼瑞達，孩子。', `FemaleText_loc7`='Mi nombre es Nimrida, chico.' WHERE `ID`=15025;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제부터 사예나라니까.', `MaleText_loc4`='是萨耶娜。', `MaleText_loc5`='是莎耶娜。', `MaleText_loc7`='Es Sayena.' WHERE `ID`=15026;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='난 님리다야.', `FemaleText_loc4`='尼姆瑞达。', `FemaleText_loc5`='尼瑞達。', `FemaleText_loc7`='Nimrida.' WHERE `ID`=15027;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 너의 주인이야... 그러니까 너는 내 말을 따라야 하잖아!', `MaleText_loc4`='我是你的主人……你应该照我说的去做！', `MaleText_loc5`='我是你的主人...你要照我的話做!', `MaleText_loc7`='Soy tu maestro... ¡se supone que tienes que hacer lo que digo!' WHERE `ID`=15028;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='애송이 흑마법사, 네가 나를 소환했을지는 몰라도 내 이름을 애완동물 같은 이름으로 고칠 권리는 없다고.', `FemaleText_loc4`='可能是你召唤了我，小术士，但是这并不代表你可以像对待宠物那样给我起名字。', `FemaleText_loc5`='你是召喚了我，我的小術士，但這不表示你可以幫我重新取個跟小孩寵物一樣的名字。', `FemaleText_loc7`='Puede que me hayas convocado, pequeño brujo, pero eso no te da permiso a cambiarme el nombre como a la mascota de un niño.' WHERE `ID`=15029;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제발... 부탁이야.', `MaleText_loc4`='拜托……', `MaleText_loc5`='拜託...好嗎?', `MaleText_loc7`='Vamos... ¿por favor?' WHERE `ID`=15030;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내가 애원하는 목소리를 좋아한다는 사실을 알고 있군... 하지만, 절대 안 돼.', `FemaleText_loc4`='你知道，我喜欢看着你乞求我……但是不行。', `FemaleText_loc5`='我真喜歡你求我的時候...但是，不。', `FemaleText_loc7`='Sabes que me encanta cuando suplicas... pero no.' WHERE `ID`=15031;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 고개를 떨구고 한숨을 쉽니다.', `MaleText_loc4`='%s垂下头，轻声叹了口气。', `MaleText_loc5`='%s感到羞愧並嘆氣。', `MaleText_loc7`='%s agacha la cabeza y suspira.' WHERE `ID`=15032;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강아지처럼 졸졸 따라다니지 말고 다른 데서 기다리라고 했잖아...', `MaleText_loc4`='我告诉过你在其它地方等我，不要像只小狗一样跟着我……', `MaleText_loc5`='我叫你到別的地方等我，不是像隻小狗一樣跟著我...', `MaleText_loc7`='Te dije que me esperases en otro sitio, no que me siguieras como un perrito...' WHERE `ID`=15033;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강력한 사냥꾼이 돌아오셨군요. 자, 마지막 사냥감을 추적한 얘기를 들려주시겠습니까?', `MaleText_loc4`='强大的猎人$n回来了。给我讲讲你最新的狩猎故事吧。', `MaleText_loc5`='偉大的獵人，$n回來了。告訴我你最近追蹤獵物的故事。', `MaleText_loc7`='El poderoso cazador, $n, vuelve. Cuéntame la historia de cómo acechaste a tu última presa.' WHERE `ID`=15034;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='체. 누가 보면 나랑 있는 걸 부끄럽게 생각하는 줄 알겠다, 주인님아.', `FemaleText_loc4`='哼。有人可能会觉得你和我在一起的时候显得很害羞，主人。', `FemaleText_loc5`='去。有人可能覺得你不想被人看到和我一起，大師。', `FemaleText_loc7`='Vaya. Cualquiera diría que te avergüenza que te vean conmigo, maestro.' WHERE `ID`=15035;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 아냐... 그러니까... 우리 둘 다 너무 매력적으로 생겼잖아.', `MaleText_loc4`='不，不……其实……呃……我们走在街上的回头率比较高。', `MaleText_loc5`='不，不...只是...嗯...我們長的很美。', `MaleText_loc7`='No, no... es solo que... bueno... estamos atrayendo miradas.' WHERE `ID`=15036;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그래서 그게 무슨 문제지? 여자는 가끔 남들 앞에서 뽐내는 걸 즐긴다고.', `FemaleText_loc4`='难道这有什么问题吗？那个女人在不停地回头看我。', `FemaleText_loc5`='那有什麼不對嗎?一個喜歡自己樣貌多變的女人。', `FemaleText_loc7`='¿Y qué hay de malo en eso? A una mujer le gusta volver cabezas de vez en cuando.' WHERE `ID`=15037;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부탁인데 다시 들어가면 안 될까?', `MaleText_loc4`='拜托你回屋里去吧……？', `MaleText_loc5`='拜託你進去裡面好嗎?', `MaleText_loc7`='Haz el favor de volver dentro.' WHERE `ID`=15038;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 케야노미르를 보고 미간을 찡그리더니 아니꼬운 웃음을 짓습니다.', `FemaleText_loc4`='%s弯起眉毛看着克亚诺米尔，露出了迷人的微笑。', `FemaleText_loc5`='%s對奇亞諾麥拱起了眉毛，嘴上揚起了一絲歪斜的奸笑。', `FemaleText_loc7`='%s levanta una ceja hacia Keyanomir, con una sonrisa irónica asomándole a los labios.' WHERE `ID`=15039;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='"부탁?" 주인님아, 너는 배울 게 아주 많아...', `FemaleText_loc4`='“拜托？”你还有很多东西要学呢……主人。', `FemaleText_loc5`='「拜託」?你有太多事要學了...大師。', `FemaleText_loc7`='"¿Por favor?" Tienes tanto que aprender... maestro.' WHERE `ID`=15040;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지옥무쇠의 맛이 어떠냐?', `MaleText_loc4`='喜欢魔铁的味道吗？', `MaleText_loc5`='喜歡邪惡鋼鐵的味道嗎?', `MaleText_loc7`='¿Disfrutas del sabor del hierro vil?' WHERE `ID`=15041;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽어라!', `MaleText_loc4`='死吧！', `MaleText_loc5`='死吧!', `MaleText_loc7`='¡Muere!' WHERE `ID`=15042;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무도 우리를 이길 수는 없다!', `MaleText_loc4`='没有人能打败邪部落！', `MaleText_loc5`='沒有人能擊敗魔獄部落!', `MaleText_loc7`='¡Nadie vencerá a la Horda vil!' WHERE `ID`=15043;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 습격이군! 방어하십시오!', `MaleText_loc4`='有埋伏！小心！', `MaleText_loc5`='有埋伏!準備迎戰!', `MaleText_loc7`='¡Es una emboscada! ¡Defendeos!' WHERE `ID`=15044;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 상처는 좋아지고 있습니다만 저는 누워 있는 게 더 좋아서요.', `MaleText_loc4`='嗯，嗯，我感觉好点了，但我其实有点喜欢这里……', `MaleText_loc5`='對，對，我感覺好多了，但我還滿喜歡這裡的。', `MaleText_loc7`='Sí, sí, me siento mejor, pero la verdad es que me gusta estar aquí abajo.' WHERE `ID`=15045;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 많은 적이 나타나기 전에 어서 떠나야 합니다.', `MaleText_loc4`='我们必须赶紧离开，免得碰到更多人。', `MaleText_loc5`='我們一定要在他們通知更多人前離開。', `MaleText_loc7`='Debemos irnos antes de que alerten a más.' WHERE `ID`=15046;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='포위됐습니다. 길을 열어야 합니다!', `MaleText_loc4`='我们被包围了！', `MaleText_loc5`='我們被包圍了!', `MaleText_loc7`='¡Estamos rodeados!' WHERE `ID`=15047;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 위에 텔라아르로 가는 길이 있습니다. 수렁피 일족 녀석들이 추가 병력을 보내서 우리를 추적할 게 뻔하니 갈림길이 나오면 찢어져서 가기로 합시다. 우리 중 한 명은 텔라아르로 돌아가야만 합니다.', `MaleText_loc4`='前面就是去塔拉的路。我们在前面的岔道分开，他们肯定会派更多人来追击我们的。希望我们当中有人能活着回到塔拉。', `MaleText_loc5`='前方就是通往泰拉的路。我們會在到達岔路時分道揚鑣，因為他們一定會派更多黑暗之血來追捕我們。希望我們之中有人能活著回到泰拉。', `MaleText_loc7`='Hacia arriba se encuentra el camino a Telaar. Nos separaremos cuando lleguemos a la bifurcación, ya que seguramente enviarán a más Sangreoscuras tras nosotros. Con un poco de suerte uno de nosotros conseguirá llegar a Telaar vivo.' WHERE `ID`=15048;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='몸조심하십시오, 이방인이여. 내 동족들이 당신의 영웅적인 헌신을 잊지 않을 겁니다. 이제 서둘러 텔라아르로 가서 아레크론을 만나십시오!', `MaleText_loc4`='保重，陌生人。你的英雄事迹会被我们的人民永远铭记。现在，快去塔拉吧！', `MaleText_loc5`='再會了，陌生人。我的人民會記住你的英雄事蹟。現在，快去泰拉吧!', `MaleText_loc7`='Adiós, $gforaestero:forastera;. Tus hazañas serán recordadas por mi pueblo. ¡Ahora corre a Telaar!' WHERE `ID`=15049;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='요런 앙큼한, 너희 모두에게 재앙이 따르리라!', `FemaleText_loc4`='我为你们感到可悲，小家伙们！', `FemaleText_loc5`='為你們每一個人感到不幸，我的小美人們!', `FemaleText_loc7`='¡Ay de todos y cada uno de ustedes, queridos míos!' WHERE `ID`=15050;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='따끔한 교훈이 됐겠지?', `FemaleText_loc4`='搞定你了，对不对？', `FemaleText_loc5`='把你修好了，對嗎?', `FemaleText_loc7`='¿Esto alivia, verdad?' WHERE `ID`=15051;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너희가 어떻게? 정녕 잔인하고 비정한 세상이로다...', `FemaleText_loc4`='怎么可能？啊，这真是个残酷的世界……', `FemaleText_loc5`='你怎麼能這樣?真是個殘酷，殘酷的世界...', `FemaleText_loc7`='¿Cómo es posible? Oh, que mundo cruel...' WHERE `ID`=15052;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저... 마법사님... 수정을 잘 흔들어 보셨습니까? 지맥에 가려서 보이지 않을 수도 있잖아요?', `MaleText_loc4`='先——先生……您有没有试过充分摇动那颗水晶？很可能是魔网能量线遮蔽了水晶。', `MaleText_loc5`='先-先生...你試過猛力地搖那個水晶嗎?能量界線可能讓它的讀取變的混亂。', `MaleText_loc7`='Se... Señor..., ¿has probado dándole un buen meneo al cristal? Es posible que las líneas nublen la lectura.' WHERE `ID`=15053;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수정의 머리가 아니라 자네의 머리를 한 번 흔들어 줘야겠군! 지맥이 자네의 머리를 어지럽히고 있는 거 아닌가? 수정을 흔들어도 소용없네, 다리우스. 우리에게 필요한 것은 미네랄이 풍부하게 함유된 물 저장소라네. 희미한 비전 신호도 모두 황과 석회에 축적될 것일세.', `MaleText_loc4`='我应该给你的脑袋来一次充分的振动！我感觉魔网能量线遮住了你的脑子。不，达里乌斯，我们需要的是大量富含矿物质的水源。即使是非常微弱的奥术信号也会在硫磺和石灰中累积下来。', `MaleText_loc5`='我必須給你當頭棒喝!我感覺能量界線已讓你的腦袋變的混濁。不，達瑞亞斯。我們需要的是大量儲存的礦物重水。即使微弱的秘法訊號都會累積在硫磺和石灰裡。', `MaleText_loc7`='¡Lo que voy a hacer va a ser darle un buen meneo a tu cabeza! A mí me parece que lo que las líneas nublan es tu mente. No, Darius, lo que necesitamos es un gran depósito de agua mineral pesada. Las señales Arcanas débiles se acumulan en la cal y el azufre.' WHERE `ID`=15054;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='박물관에는 초대받은 손님만 입장하실 수 있습니다.', `MaleText_loc4`='展览厅只对访客开放。', `MaleText_loc5`='展示廳是賓客專屬的。', `MaleText_loc7`='La colección es solo para los invitados.' WHERE `ID`=15055;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죄... 죄송합니다, 대마법사님.', `MaleText_loc4`='对——对不起，先生。', `MaleText_loc5`='對-對不起，先生。', `MaleText_loc7`='Lo si... Lo siento, señor.' WHERE `ID`=15056;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='관리인, 작동을 중단합니다...', `MaleText_loc4`='馆长无法继续运……作……', `MaleText_loc5`='館長無法運-作-了。', `MaleText_loc7`='Curator ya no está opera-ti-vo.' WHERE `ID`=15057;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어린 아이에게 너무 가혹하게 굴지 마십시오, 알투루스. 그 아이는 세드릭이 직접 당신에게 맡긴 아이라는 걸 잊지 마세요.', `FemaleText_loc4`='不要对孩子这么刻薄，奥图鲁斯。记住是塞德瑞克亲自把他指派给你的。', `FemaleText_loc5`='不要對那個孩子這麼兇，艾特羅斯。記住是賽卓克親自指派他給你的。', `FemaleText_loc7`='No seas tan brusco con el niño, Alturus. Recuerda que Cedric te lo asignó personalmente.' WHERE `ID`=15058;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='현재 요청하신 내용은 처리가 불가능합니다.', `MaleText_loc4`='你的请求未能得到批准。', `MaleText_loc5`='無法處理你的要求。', `MaleText_loc7`='No se puede procesar tu petición.' WHERE `ID`=15059;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='규칙 위반으로 경보가 발동됐습니다.', `MaleText_loc4`='不合作将导致攻击行动。', `MaleText_loc5`='不順從就會招致攻擊性的行動。', `MaleText_loc7`='Será castigado quien no cumpla las normas.' WHERE `ID`=15060;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기다리는 것도 지겹군. 날 위해 춤이나 춰라, 멍청아.', `MaleText_loc4`='我等得有点累了。给我跳个舞，白痴。', `MaleText_loc5`='我受夠了等待。為我跳舞吧，蠢貨。', `MaleText_loc7`='Me estoy cansando de esperar. Baila para mí, imbécil.' WHERE `ID`=15061;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너 말고, 이런 멍청한! 다른 녀석 말이다.', `MaleText_loc4`='不是你，蠢货！我说的是另一个白痴。', `MaleText_loc5`='不是你，白痴!是另一個蠢貨。', `MaleText_loc7`='¡Tú no, idiota! El otro imbécil.', `FemaleText_loc1`='너 말고, 이런 멍청한! 다른 녀석 말이다.', `FemaleText_loc4`='不是你，蠢货！我说的是另一个白痴。', `FemaleText_loc5`='不是你，白痴!是另一個蠢貨。', `FemaleText_loc7`='¡Tú no, idiota! El otro imbécil.' WHERE `ID`=15062;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런, 죄송합니다.', `MaleText_loc4`='啊。格隆度很抱歉。', `MaleText_loc5`='啊。非常抱歉。', `MaleText_loc7`='Uy. Grondo sentir.' WHERE `ID`=15063;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='운코르 님의 말 못 들었나? 춤 춰라!', `MaleText_loc4`='你听到安克尔的话吗，聋子？给我跳舞！', `MaleText_loc5`='你聽到昂庫爾的聲音，笨蛋?跳舞!', `MaleText_loc7`='¿Oyes a Unkor, tonto? ¡Baila!' WHERE `ID`=15064;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알았다, 알았어. 지금 춤 춘다.', `MaleText_loc4`='好，好。我现在跳。', `MaleText_loc5`='好，好。我現在跳舞。', `MaleText_loc7`='Vale, vale. Ahora yo bailar.' WHERE `ID`=15065;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='티토! 우리를 보호해줘, 응? 그래 줄 수 있지, 티토?', `FemaleText_loc4`='托托，你不会让这些家伙伤害我们的，对吧？', `FemaleText_loc5`='不要讓他們傷害我們多多!喔，你不會吧，是嗎?', `FemaleText_loc7`='¡No permitas que nos hagan daño, Tito! No lo harás, ¿verdad?' WHERE `ID`=15066;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='티토야, 우린 집으로 갈 방법을 찾아야 해! 늙은 마법사가 우릴 도와줄 수 있을 거야! 허수아비, 사자, 양철통아... 우리? 오... 맙소사, 손님들이 온 것 같아!', `FemaleText_loc4`='啊，托托，我们必须找到回家的路！那位老巫师是我们唯一的希望了！稻草人、狮子，还有铁皮人，你们能不能——呀，有人来了！', `FemaleText_loc5`='喔多多，我們一定要找到回家的路!那個老巫師是我們唯一的希望!稻草人、獅子、機器人，你會 - 等等哦...天呀，快看，我們有訪客!', `FemaleText_loc7`='¡Oh, Tito, solo tenemos que buscar la manera de volver a casa! ¡El viejo hechicero puede ser nuestra única esperanza! Espantapájaros, Rugido, Cabezalata, van a... oh... espera... ¡Oh, caramba, miren tenemos visita!' WHERE `ID`=15067;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 마침내... 마침내 집으로 갈 수 있게 됐어!', `FemaleText_loc4`='啊，我终于……终于可以回家啦！', `FemaleText_loc5`='喔終於，我終於可以回家了!', `FemaleText_loc7`='¡Oh, al fin puedo irme a casa!' WHERE `ID`=15068;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='티토! 오, 티토! 안 돼!', `FemaleText_loc4`='托托！不！你们杀了托托！', `FemaleText_loc5`='多多!喔多多，不!', `FemaleText_loc7`='¡Tito! ¡Oh, Tito, no!' WHERE `ID`=15069;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신들은 대체 누구시기에 절 이리도 괴롭히나요?', `FemaleText_loc4`='你是个什么魔鬼，这样煎熬着我？', `FemaleText_loc5`='你是什麼樣的惡魔，讓我這樣的痛苦?', `FemaleText_loc7`='¿Quién diablo ser es que me atormenta de esta forma?' WHERE `ID`=15070;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이별은 달콤한 슬픔이죠.', `FemaleText_loc4`='离别是这样甜蜜的凄清。', `FemaleText_loc5`='分離是這樣甜蜜的悲傷。', `FemaleText_loc7`='El partir es un dolor tan dulce.' WHERE `ID`=15071;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='로밀로, 제가 가요! 오... 당신께 축배를!', `FemaleText_loc4`='罗密欧，我来了！我为你干了这一杯！', `FemaleText_loc5`='羅慕歐，我來了!喔...讓我敬你!', `FemaleText_loc7`='¡Romulo, ya voy! ¡Oh... bebo esto en tu honor!' WHERE `ID`=15072;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정다운 밤이시여. 어서 와서 나의 로밀로를 돌려주소서!', `FemaleText_loc4`='来吧，可爱的黑颜的夜，把我的罗密欧给我！', `FemaleText_loc5`='來吧，溫和的夜晚;把我的羅慕歐還給我!', `FemaleText_loc7`='Adelante, gentil noche, ¡devuélveme a mi Romulo!' WHERE `ID`=15073;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오, 반가운 단검이여! 내 가슴은 너의 칼집이니, 그 안에 들어가 이 몸을 죽게 하오!', `FemaleText_loc4`='啊，好刀子！这就是你的鞘子；你刺了进去，让我死了吧!', `FemaleText_loc5`='喔快樂的匕首!這是你的護套;別生鏽了，讓我死吧!', `FemaleText_loc7`='¡Oh, maravillosa daga! ¡Aquí está tu vaina, oxídate dentro y permíteme morir!' WHERE `ID`=15074;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기어코 나를 화나게 하는구나? 그렇다면 받아라, 애송이!', `MaleText_loc4`='你要激怒我吗？那就来吧!', `MaleText_loc5`='你想挑釁我嗎?下一個就輪到你了，小子!', `MaleText_loc7`='¿Me provocan? ¡Aquí tienen!' WHERE `ID`=15075;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야말로 나를 위로하는 커다란 즐거움이지!', `MaleText_loc4`='现在我又重新得到了多大的安慰！', `MaleText_loc5`='我的心情能夠?此而恢復，真好!', `MaleText_loc7`='¡Cómo revive esto mi consuelo!' WHERE `ID`=15076;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='추악한 욕망과 죽음의 모태여, 그대들의 썩어빠진 입을 벌려주마!', `MaleText_loc4`='无情的泥土，我要擘开你的馋吻!', `MaleText_loc5`='你這個可恨的貪心鬼，你找死;我要撕開你的嘴!', `MaleText_loc7`='Buche detestable, matriz de muerte; ¡te ordeno que abras tus putrefactas mandíbulas!' WHERE `ID`=15077;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대들은 나를 쓰러뜨린 그 일격을 자랑스러워하며... 미소짓는구나.', `MaleText_loc4`='你杀了我……却洋洋得意。', `MaleText_loc5`='你大笑...在殺掉我...的最後一擊後。', `MaleText_loc7`='Sonríen... al ver el golpe que… acaba conmigo.' WHERE `ID`=15078;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너희의 행동은 그냥 넘길 수가 없다.', `FemaleText_loc4`='你们的行为是不可饶恕的。', `FemaleText_loc5`='你的行為不能被容忍。', `FemaleText_loc7`='No se tolerará su comportamiento.' WHERE `ID`=15079;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그 부정한 생각을 떨쳐버려라.', `FemaleText_loc4`='抛弃一切堕落的杂念。', `FemaleText_loc5`='逐出你墮落的思想。', `FemaleText_loc7`='Expulsen sus pensamientos impuros.' WHERE `ID`=15080;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너희 손에 내가 죽는구나. 이러고도 양심에 거리끼지 않겠느냐?', `FemaleText_loc4`='死亡来临了。你们自问无愧于良知吗？', `FemaleText_loc5`='死亡降臨。你的善惡觀念清楚了嗎?', `FemaleText_loc7`='La muerte se avecina. ¿Tendrán la conciencia limpia?' WHERE `ID`=15081;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아 아 아...', `FemaleText_loc4`='啊哈哈哈……', `FemaleText_loc5`='啊啊啊......', `FemaleText_loc7`='Mmh mmh mh...' WHERE `ID`=15082;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='불순한 생각은 천박한 행동으로 이어지는 법!', `FemaleText_loc4`='不纯的思想会导致亵渎的行为。', `FemaleText_loc5`='不純潔的思想就會導致褻瀆的行為。', `FemaleText_loc7`='Los pensamientos impuros propician acciones profanas.' WHERE `ID`=15083;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이것이 최선의 방법이다.', `FemaleText_loc4`='这样就没问题了。', `FemaleText_loc5`='這是為了追求完美。', `FemaleText_loc7`='Se ha hecho lo necesario.' WHERE `ID`=15084;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간... 언제나 시간이 부족해.', `MaleText_loc4`='时间……时间总是不够。', `MaleText_loc5`='時間...時間永遠不夠。', `MaleText_loc7`='Tiempo... siempre falta tiempo.' WHERE `ID`=15085;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흥분해서 그만 실수를 했네요...', `MaleText_loc4`='啊，真惨。', `MaleText_loc5`='喔，我剛剛離開並且製造了一些混亂...', `MaleText_loc7`='Oh, que desastre hice…' WHERE `ID`=15086;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무역연합은 수개월 동안 이 작업을 계획해 왔다! 우리는 세계에서 가장 큰 다이아몬드라고 알려진 오슈군을 캐려고 했다.$B$B하지만, 채굴을 시작하려고 했을 때 연합왕자 하라매드께서 작업을 중단하라는 명령을 내렸다. 황천의 폭풍에서 정치적인 문제가 해결될 때까지 기다리라는 것이었다. 그래서 당분간 밀수한 보석을 모아서 파는 일을 하고 있는데 이것이 점점 수익을 갉아먹지 뭔가...', `MaleText_loc4`='星界财团已经策划这个行动好几个月了！我们要挖掘宇宙中最大的钻石——沃舒古。$B$B就在我们要开始动手的时候，节点亲王哈拉迈德送来口信说，我们需要暂缓一下，直到解决一个虚空风暴地区的政治问题。我只能把我们的行动改变为在空闲时间走私宝石，但是这似乎在慢慢消耗我们的利润。', `MaleText_loc5`='聯合團已經籌備這個計畫好幾個月了!我們想挖掘歐夏剛，這是一種被譽為宇宙中最大的鑽石。$B$B在我們要開始進行計畫的數分鐘前，奈薩斯王子哈拉瑪德傳話來命令我們在虛空風暴的一場政治衝突解決之前暫時按兵不動。我已經將我們的計畫轉變成目前暫時營運一個囤積走私寶石的貨倉，但這樣只會慢慢的吞噬我們的利潤。', `MaleText_loc7`='El Consorcio lleva meses planeando esta operación. Queríamos encontrar el Oshu''gun, el diamante más grande del universo.$B$BUnos minutos antes de que empezáramos, nos llegó un mensaje del príncipe-nexo Haramad pidiéndonos que esperemos hasta que se resolviera una cuestión política en Tormenta Abisal. He transformado la operación en un mercado negro de gemas mientras esperamos, pero nuestros beneficios se reducen cada minuto.' WHERE `ID`=15087;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런, 저 사슴들이 우리를 별로 반기지 않는 것 같군!', `MaleText_loc4`='啊……那些塔布羊看上去对我们不是很友好！', `MaleText_loc5`='喔喔，那些雄鹿看起來對我們不太高興。', `MaleText_loc7`='Parece que a esos venados no les caemos muy bien.' WHERE `ID`=15088;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하시오, 피츠. 놈들이 우리를 향해 곧장 달려오고 있소!', `MaleText_loc4`='小心，好儿子，它们冲过来了！', `MaleText_loc5`='小心，費茲，他們是針對我們而來的!', `MaleText_loc7`='¡Cuidado, Fitz, vienen a por nosotros!' WHERE `ID`=15089;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일입니까?!', `MaleText_loc4`='发生什么事了？！', `MaleText_loc5`='發生什麼事?!', `MaleText_loc7`='¡¿Qué pasa?!' WHERE `ID`=15090;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 미소를 짓더니 라이플을 집어넣습니다.', `MaleText_loc4`='%s笑了笑，摆弄着他的步枪。', `MaleText_loc5`='%s微笑著把他的步槍放回槍袋。', `MaleText_loc7`='%s sonríe y guarda su rifle.' WHERE `ID`=15091;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='게제는 여기 일을 처리하러 왔다. 난 그가 일을 하는 동안 아무도 그를 방해하지 못하게 하기 위해 여기 왔다.', `MaleText_loc4`='杰赫要在这里专心完成一项工作。而我负责保证在他工作时没人可以打扰他。', `MaleText_loc5`='吉札是來把工作做好的。我來確認這時候沒有人打擾他。', `MaleText_loc7`='Gezhe está aquí para hacer un trabajo. Yo estoy aquí para asegurarme de que nadie lo moleste mientras trabaja.' WHERE `ID`=15092;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음... 여러분?', `MaleText_loc4`='兄弟们？', `MaleText_loc5`='呃...大伙們?', `MaleText_loc7`='Mm... ¿chicos?' WHERE `ID`=15093;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헤멧? 피츠? 거기... 있는 겁니까?', `MaleText_loc4`='赫米特？好儿子？', `MaleText_loc5`='赫米特?費茲?', `MaleText_loc7`='¿Hemet? ¿Fitz?' WHERE `ID`=15094;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 다행이군요. 걱정하던 참입니다.', `MaleText_loc4`='那就好，我都有点开始担心了。', `MaleText_loc5`='喔很好，我正開始擔心。', `MaleText_loc7`='Ah, bien, estaba empezando a preocuparme.' WHERE `ID`=15095;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이방인이여, 우리가 누군지 아십니까? 우리는 마그하르입니다. 당신들은 우리를 갈색 오크라고 부른다는 얘기를 들었습니다. 우리 마그하르는 생존자들입니다. 망한 왕국의 생존자, 붉은 천연두의 생존자, 파괴된 세계의 생존자...$B$B저는 킬로그의 아들 요린입니다. 피눈물 부족의 대족장인 데드아이 가문의 마지막 혈통입니다.', `MaleText_loc4`='你知道我们是谁吗，陌生人？我们是玛格汉，棕色的兽人，我听到你们的同类都是这么叫我们的。玛格汉是幸存者：一个消失了的王朝的幸存者，红色天灾的幸存者，这个破碎世界的幸存者……$B$B我叫约林，基尔罗格之子。死眼家族最后的血统，血环氏族的酋长。', `MaleText_loc5`='你知道我們是誰嗎，陌生人?我們是瑪格哈 - 咖啡色獸人，我聽過你們族人這樣稱呼我們。瑪格哈是生還者:一個墮落朝代的生還者;紅色帕斯的生還者;一個粉碎世界的生還者...$b$b我是喬林，基爾羅格之子;亡眼的最後一個後裔:血之谷氏族的酋長。', `MaleText_loc7`='¿Sabes quiénes somos, $gextranjero:extranjera;? Somos Mag''har – orcos marrones, según he oído que tu especie nos llama. Los Mag''har son supervivientes: supervivientes de una dinastía caída; supervivientes de la enfermedad roja; supervivientes de un mundo destrozado...$B$BSoy Jorin, hijo de Kilrogg; el último del linaje de Mortojo: Jefe de Guerra del clan de Foso Sangrante.' WHERE `ID`=15096;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='항복! 제발 죽이지 마십시오!', `MaleText_loc4`='我投降！不要杀我！', `MaleText_loc5`='我放棄!拜託別殺我!', `MaleText_loc7`='¡Me rindo! ¡Por favor, no me mates!' WHERE `ID`=15097;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제... 도망이다!', `MaleText_loc4`='我跑！', `MaleText_loc5`='而現在，我跑!', `MaleText_loc7`='Y, ahora, ¡corro!' WHERE `ID`=15098;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='헤멧이 지상에서 사냥을 할 때 보조 날개를 관통시키지만 않았어도 우리는 추락하지 않았을 걸세!$B$B하지만, 금방 고쳐 놓을 테니 너무 걱정하지 말게.', `FemaleText_loc4`='若是赫米特知道如何在射击猎物时避免打中机翼的话，我们就不会坠毁。$B$B不用担心，我会很快把它修好的。', `FemaleText_loc5`='如果赫米特在嘗試獵捕地面的獵物時可以避開穿過副翼的射擊，我們就不會墜毀了。$B$B不過別擔心，我會很快就把她修好的。', `FemaleText_loc7`='¡No nos habríamos estrellado si Hemet aprendiera a no dispararle a los alerones cuando intenta darle a las presas del suelo!$B$BPero no pasa nada, los arreglaré bastante rápido.' WHERE `ID`=15099;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘레, 그대가 아껴둔 재료가 분명 있을 겁니다. 제가 능숙하다는 것을 아시잖아요?! 어떤 것이든, 모두!', `MaleText_loc4`='我知道你肯定有什么东西可以施舍给我，萨尔雷。随便什么东西，任何东西都行！', `MaleText_loc5`='你當然有東西可以給我，賽爾。你知道我很在行的。一定有點東西，任何東西!', `MaleText_loc7`='Sin duda tienes algo de lo que puedes prescindir, Zalle. Sabes que soy bueno para ello. ¡Algo, cualquier cosa!' WHERE `ID`=15100;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='카일란, 그대 같은 사람에게 줄 물건은 없습니다. 마지막으로 경고하는데, 가게에서 나가주십시오.', `FemaleText_loc4`='我没有任何东西给像你这样的家伙，塞伊兰。像上次那样，滚出这个店。', `FemaleText_loc5`='我這裡沒有你想要的東西，凱歐蘭。我再說最後一次，滾出這間店。', `FemaleText_loc7`='No tengo nada para los que son como tú, Cailan. Por última vez te pido que salgas de esta tienda.' WHERE `ID`=15101;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='반갑네요, 해럴드. 제게 당신 물건이 있어요!', `FemaleText_loc4`='嘿，哈罗德。我拿到你的皮革了！', `FemaleText_loc5`='嗨，哈洛德。我拿到你的皮革了!', `FemaleText_loc7`='Hola, Harold. ¡Tengo tus pieles!' WHERE `ID`=15102;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와주십시오! 제발 도와주세요!', `MaleText_loc4`='救救我！请救救我！', `MaleText_loc5`='救救我!拜託救救我!', `MaleText_loc7`='¡Ayuda! ¡Ayuda, por favor!' WHERE `ID`=15103;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='꺅! 누가 좀 도와줘요!', `FemaleText_loc4`='啊！有人来救救我吗！', `FemaleText_loc5`='喂!來人救救我!', `FemaleText_loc7`='¡Ah! ¡Que alguien me ayude!' WHERE `ID`=15104;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 이런 곳에 절 남겨둘 수 있단 말입니까?', `MaleText_loc4`='你怎么能就这么把我留在这里？', `MaleText_loc5`='你怎麼可以就這樣把我留在那裡?', `MaleText_loc7`='¿Cómo me puedes dejar aquí?' WHERE `ID`=15106;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 계신 분! 이 망할 놈의 우리 안에서 나가도록 도와주십시오!', `MaleText_loc4`='嘿，你！帮帮忙，帮我从这肮脏的囚笼中脱身！', `MaleText_loc5`='嘿!幫我找找離開這破爛籠子的路!', `MaleText_loc7`='¡Eh, tú! ¡Ayúdame a salir de esta maldita jaula!' WHERE `ID`=15107;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언제쯤이면 이 고통이 끝날까?', `MaleText_loc4`='何时才能结束这种痛苦啊？', `MaleText_loc5`='痛苦何時會停止?', `MaleText_loc7`='¿Cesará alguna vez el dolor?' WHERE `ID`=15108;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 크리스틴의 물건을 뒤지더니 그녀의 가죽 꾸러미를 집습니다.', `MaleText_loc4`='%s洗劫了克里斯登的物品，还拿走了她的一捆皮革。', `MaleText_loc5`='%s洗劫了克莉斯坦的東西，拿走了她大批的皮革。', `MaleText_loc7`='%s revuelve las cosas de Kristen y agarra su fardo de pieles.' WHERE `ID`=15109;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 가죽이 있습니다, 해럴드. 이제 보상을 주십시오!', `MaleText_loc4`='这是我的皮革，哈罗德。现在给我奖励吧。', `MaleText_loc5`='我的皮革在這，哈洛德。給我獎勵吧!', `MaleText_loc7`='Aquí están mis pieles, Harold. ¡Ahora dame la recompensa!' WHERE `ID`=15110;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꼬마 녀석, 이건 내가 가져가겠다.', `MaleText_loc4`='我会收下这些皮革的，小东西。', `MaleText_loc5`='我要那些皮革，小傢伙。', `MaleText_loc7`='Me llevaré esas pieles, pequeña.' WHERE `ID`=15111;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 물론입니다, 갱클리. 다만...<쿨럭>... 거기서 잠시만 기다리십시오. <쿨럭> 이보게들?', `MaleText_loc4`='呃……当然，甘克雷。只不过……<咳嗽>……在这里等着。<咳嗽>兄弟们？', `MaleText_loc5`='呃...那當然，甘克利。先...<咳嗽>...在那等一下。<咳嗽>大夥們?', `MaleText_loc7`='Oh... seguro, Abusón. Solo...<tose>... espera aquí. <Tose> ¿Chicos?' WHERE `ID`=15112;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사악한 갱클리 로튼피스트가 벌을 받아서 정말 기뻐요! 해럴드에게 줄 가죽이 필요하시다면 제게 많이 있답니다.', `FemaleText_loc4`='我很高兴那个邪恶的甘克雷·骨拳没能得逞！如果你想带点毛皮给哈罗德的话，我有很多。', `FemaleText_loc5`='我很高興甘克利·腐蝕之拳得到他應有的報應了!如果你想給哈洛德一些皮革，我這裡有很多。', `FemaleText_loc7`='¡Me alegro mucho de que Abusón Puñoinfecto recibiera su merecido! Tengo muchas pieles por si quieres darle alguna a Harold.' WHERE `ID`=15113;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잡았다! 네가 술래야!', `MaleText_loc4`='抓住你了！就是你！', `MaleText_loc5`='別跑!就是你!', `MaleText_loc7`='¡Te pillé! ¡La llevas!', `FemaleText_loc1`='잡았다! 네가 술래야!', `FemaleText_loc4`='抓住你了！就是你！', `FemaleText_loc5`='別跑!就是你!', `FemaleText_loc7`='¡Te pillé! ¡La llevas!' WHERE `ID`=15114;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들을 해치워라!', `MaleText_loc4`='杀了他们！', `MaleText_loc5`='你竟敢玷污我的房子!你不值得我浪費時間殺你...殺了他們我的戰士!', `MaleText_loc7`='¡Matadlos!' WHERE `ID`=15115;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저리 비켜!', `MaleText_loc4`='不要挡路！', `MaleText_loc5`='不要擋路!', `MaleText_loc7`='¡Apártate de mi camino!', `FemaleText_loc1`='저리 비켜!', `FemaleText_loc4`='不要挡路！', `FemaleText_loc5`='不要擋路!', `FemaleText_loc7`='¡Apártate de mi camino!' WHERE `ID`=15116;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오리다, 꽥꽥!', `MaleText_loc4`='蹲下！', `MaleText_loc5`='低頭!', `MaleText_loc7`='¡Agáchate!', `FemaleText_loc1`='오리다, 꽥꽥!', `FemaleText_loc4`='蹲下！', `FemaleText_loc5`='低頭!', `FemaleText_loc7`='¡Agáchate!' WHERE `ID`=15117;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오우거?! 네가 바로 오우거구나! 하하!', `MaleText_loc4`='食人魔！你是食人魔！哈哈！', `MaleText_loc5`='巨魔!你是巨魔!哈哈!', `MaleText_loc7`='¡OGRO! ¡Tú eres el ogro! ¡Ja, ja!', `FemaleText_loc1`='오우거?! 네가 바로 오우거구나! 하하!', `FemaleText_loc4`='食人魔！你是食人魔！哈哈！', `FemaleText_loc5`='巨魔!你是巨魔!哈哈!', `FemaleText_loc7`='¡OGRO! ¡Tú eres el ogro! ¡Ja, ja!' WHERE `ID`=15118;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호수에 가까이 가지 마세요! 유령이 나온대요!', `MaleText_loc4`='不要靠近那片湖泊！那里有鬼魂出没！', `MaleText_loc5`='不要靠近湖邊!那裡有鬼!', `MaleText_loc7`='¡No te acerques demasiado al lago! ¡Está encantado!', `FemaleText_loc1`='호수에 가까이 가지 마세요! 유령이 나온대요!', `FemaleText_loc4`='不要靠近那片湖泊！那里有鬼魂出没！', `FemaleText_loc5`='不要靠近湖邊!那裡有鬼!', `FemaleText_loc7`='¡No te acerques demasiado al lago! ¡Está encantado!' WHERE `ID`=15119;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='인제 그만 달리면 안 될까?', `MaleText_loc4`='我们可以停下来了吗？', `MaleText_loc5`='我們可以不要再跑了嗎?', `MaleText_loc7`='¿Podemos parar de correr?', `FemaleText_loc1`='인제 그만 달리면 안 될까?', `FemaleText_loc4`='我们可以停下来了吗？', `FemaleText_loc5`='我們可以不要再跑了嗎?', `FemaleText_loc7`='¿Podemos parar de correr?' WHERE `ID`=15120;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힝, 엄마를 잃어버렸어요.', `MaleText_loc4`='我想妈妈了。', `MaleText_loc5`='我想念我媽咪。', `MaleText_loc7`='Echo de menos a mi mami.', `FemaleText_loc1`='힝, 엄마를 잃어버렸어요.', `FemaleText_loc4`='我想妈妈了。', `FemaleText_loc5`='我想念我媽咪。', `FemaleText_loc7`='Echo de menos a mi mami.' WHERE `ID`=15121;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다리 아파, 그만 놀래!', `MaleText_loc4`='我不想再玩了！', `MaleText_loc5`='我不想再玩了!', `MaleText_loc7`='¡No quiero jugar más!', `FemaleText_loc1`='다리 아파, 그만 놀래!', `FemaleText_loc4`='我不想再玩了！', `FemaleText_loc5`='我不想再玩了!', `FemaleText_loc7`='¡No quiero jugar más!' WHERE `ID`=15122;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='패배를 인정할 수 없다! 나는 에레다르의 공작이다! 나... 나는...', `MaleText_loc4`='我拒绝承认失败！我是艾瑞达的王子！我……是……', `MaleText_loc5`='我拒絕承認失敗!我是埃雷達爾的王子!我...我是...', `MaleText_loc7`='¡Me niego a asumir la derrota! ¡Soy el príncipe de los Eredar! Soy…' WHERE `ID`=15123;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론 이길 거란 생각은 하지 않았겠지.', `MaleText_loc4`='你显然没有奢望自己可以获胜。', `MaleText_loc5`='你當然不覺得你會贏。', `MaleText_loc7`='No habrás pensado que podías vencer' WHERE `ID`=15124;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 탐욕과 우둔함이 너희를 파멸로 이끌었노라.', `MaleText_loc4`='你的贪婪和愚蠢注定了你的结局。', `MaleText_loc5`='你的貪婪，你的愚蠢將你帶往毀滅。', `MaleText_loc7`='Tu codicia y estupidez te han llevado a este final.' WHERE `ID`=15125;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희는 노리개일 뿐이다. 기분 전환거리도 안 되는...', `MaleText_loc4`='你不过是个无聊的玩具，甚至不能让我提起战斗的兴趣。', `MaleText_loc5`='你不過是個玩物。就連提供娛樂都還嫌不夠。', `MaleText_loc7`='No eres más que un juguete y ni siquiera sirves para entretenerme.' WHERE `ID`=15126;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기까지 오다니 정신이 나간 놈들이 분명하구나. 소원이라면 파멸시켜 주마!', `MaleText_loc4`='疯狂将你们带到我的面前，而我将以死亡终结你们！', `MaleText_loc5`='瘋狂把你帶到我的面前。我會成為你失敗的原因!', `MaleText_loc7`='La locura los ha traído ante mi. ¡Seré su fin!' WHERE `ID`=15127;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 근접 폭발 폭탄을 작동시킵니다!', `MaleText_loc4`='%s开始放置炸弹！', `MaleText_loc5`='%s開始裝備自走炸彈!', `MaleText_loc7`='¡%s comienza a armar la bomba de proximidad!' WHERE `ID`=15129;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 감히... 이게 무슨 짓이냐? 너희가 모든 것을 망쳐놓았다!', `MaleText_loc4`='谁竟敢打断……什么？你们都干了些什么？你们毁掉了一切！', `MaleText_loc5`='誰敢來干擾—這是什麼;你做了什麼?全都被你搞砸了!', `MaleText_loc7`='¿Quién osa interrumpir? – ¿Qué es esto? ¿Qué han hecho? ¡Hecharán todo a perder!' WHERE `ID`=15130;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 한숨 자라.', `MaleText_loc4`='去睡一小会吧。', `MaleText_loc5`='準備進入長眠吧。', `MaleText_loc7`='Adelante, haz 40 guiños.' WHERE `ID`=15131;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가까이... 더 가까이... 활활 타오르리라!', `MaleText_loc4`='靠近点！再近点……燃烧吧！', `MaleText_loc5`='靠近一點!再靠近一點...然後燃燒吧!', `MaleText_loc7`='Mas cerca... acérquense... ¡y ardan!' WHERE `ID`=15132;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꼭 이럴 필요는 없었잖아!', `MaleText_loc4`='你们为什么要这么做！', `MaleText_loc5`='你不用這麼做!', `MaleText_loc7`='¡No tenía que llegar a esto!' WHERE `ID`=15133;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 독구름을 일으킵니다!', `MaleText_loc4`='%s喷出一片毒云！', `MaleText_loc5`='%s召喚了一朵毒雲!', `MaleText_loc7`='¡%s engendra una nube de veneno!' WHERE `ID`=15134;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날... 빗자루로만은 만들지 말아줘.', `MaleText_loc4`='别让他们把我……做成草垫。', `MaleText_loc5`='不要讓他們把我...當床墊。', `MaleText_loc7`='No permitas que... hagan un colchón conmigo.' WHERE `ID`=15135;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나도 분명 쓸모가 있다고!', `MaleText_loc4`='看来我并不是一个失败品！', `MaleText_loc5`='原來我也不是個失敗者嘛!', `MaleText_loc7`='¡Supongo que al fin y al cabo no soy un fracaso!' WHERE `ID`=15136;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 목숨은 당신 것입니다, 위대한 분이시여...', `MaleText_loc4`='我的生命属于您，主人……', `MaleText_loc5`='我的生命歸屬於你，喔強者...', `MaleText_loc7`='Mi vida te pertenece, oh alteza…' WHERE `ID`=15137;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사악한 갱클리 로튼피스트가 벌을 받아서 정말 기뻐요!', `FemaleText_loc4`='我很高兴那个邪恶的甘克雷·骨拳没能得逞！', `FemaleText_loc5`='我很高興甘克利·腐蝕之拳得到他應有的報應了!', `FemaleText_loc7`='¡Me alegra TANTO que ese malvado Abusón Puñoinfecto tuviera su merecido!' WHERE `ID`=15138;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대모님이시여, 이 물을 드십시오.', `FemaleText_loc4`='盖亚安祖母，请喝点水吧。', `FemaleText_loc5`='主母，請喝下這些水。', `FemaleText_loc7`='Abuela, por favor, bebe esta agua.' WHERE `ID`=15139;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이봐요! 제가 전에 가죽 꾸러미를 드리지 않았나요?$B$B어쨌든 저는 그 사악한 갱클리 로튼피스트의 무자비한 손아귀에서 벗어나게 돼서 정말 기쁘답니다!', `FemaleText_loc4`='嘿！我是不是以前给过你一捆皮革？$B$B不管怎样，能从那个坏蛋甘克雷·骨拳手下逃生，我很高兴。', `FemaleText_loc5`='嘿!我不是給了你一堆皮革嗎?$B$B不管怎麼樣，我很高興你把我從邪惡的甘克利·腐蝕之拳殘酷的控制之下救出來!', `FemaleText_loc7`='¡Eh! ¿No te había entregado un fajo de pieles antes?$B$BDe cualquier modo, me alegro de estar a salvo de las garras del perverso Abusón Puñoinfecto.' WHERE `ID`=15140;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 때맞춰 와줬군. 막 의식을 시작하려던 참이었다!', `MaleText_loc4`='啊，你们来的正是时候。仪式就要开始了！', `MaleText_loc5`='啊，你來的正好。儀式正要開始!', `MaleText_loc7`='Ah, justo a tiempo. ¡Los rituales van a empezar!' WHERE `ID`=15141;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대모님이시여, 제가 해야 할 일이 있습니까?', `FemaleText_loc4`='盖亚安祖母，有什么我可以效劳的吗？', `FemaleText_loc5`='主母，我可以幫上什麼忙嗎?', `FemaleText_loc7`='Abuela, ¿hay algo que pueda hacer?' WHERE `ID`=15142;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대모님이시여, 가로쉬의 불타오르던 열정이 사그라졌습니다. 이제 당신이 없으면 저희는 길 잃은 양에 불과합니다.', `FemaleText_loc4`='盖亚安祖母，加尔鲁什已经失去了信心。如果没有了您，我们就一无所有了。', `FemaleText_loc5`='主母，卡爾洛斯失去了他的心。我們沒有你就會迷失方向。', `FemaleText_loc7`='Abuela, Garrosh ha perdido el corazón. Sin ti, estamos perdidos.' WHERE `ID`=15143;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='최선을 다해 아이들을 돌보겠습니다, 대모님이시여.', `FemaleText_loc4`='我会尽我所能照顾孩子们的，盖亚安祖母。', `FemaleText_loc5`='我會盡最大的力量來照顧孩子們，主母。', `FemaleText_loc7`='Me ocuparé de los pequeños lo mejor que pueda, Abuela.' WHERE `ID`=15144;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희의 피로 내 마법진을 칠하리라!', `MaleText_loc4`='你的血让我的法阵更强大！', `MaleText_loc5`='我會將你的鮮血灑在我的法陣裡!', `MaleText_loc7`='¡Ungiré mi círculo con tu sangre!' WHERE `ID`=15145;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위대한 분께서 기뻐하실 것이다.', `MaleText_loc4`='主人会非常高兴的。', `MaleText_loc5`='強者會很高興的。', `MaleText_loc7`='Su alteza estará complacida.' WHERE `ID`=15146;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위대한 분이시여, 부디 이 보잘것없는 제물을 받아주십시오...', `MaleText_loc4`='主人，请接受这谦卑的祭品……', `MaleText_loc5`='請收下這個粗糙的禮物吧，喔強者...', `MaleText_loc7`='Por favor, acepta esta humilde ofrenda, oh alteza...' WHERE `ID`=15147;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='충성심의 증거로 이 제물을 바칩니다.', `MaleText_loc4`='让这份祭品见证我的忠诚。', `MaleText_loc5`='讓這個犧牲做為我忠誠的明證吧!', `MaleText_loc7`='Que este sacrificio sirva de testimonio de mi lealtad.' WHERE `ID`=15148;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대모께서는 우리 모두를 기르셨지요. 당신이 만난 모든 마그하리의 삶에는 대모의 손길이 닿아있어요. 아주 특별한 방법으로 말이죠. 대모께서 돌아가신다면 우리는 그분을 정말 많이 그리워할 거예요.', `FemaleText_loc4`='盖亚安祖母让我们获得了升华。所有你遇到的玛格汉族人的生活都与盖亚安祖母有着某些特殊的联系。当她去世的时候，我们会非常怀念她的。', `FemaleText_loc5`='主母將我們撫養長大。你看到的任何瑪格哈利都因為主母而有他們生命動容的一面在。當她去世後我們會非常想念她的。', `FemaleText_loc7`='La Abuela nos crió a todos. Todos los Mag''hari que ves han sentido la influencia y el cariño de la Abuela de una forma u otra. La echaremos mucho de menos cuando ya no esté.' WHERE `ID`=15149;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나오너라, 어둠의 피조물들이여! 내 부름에 응답하라!', `MaleText_loc4`='来吧，黑暗中的潜伏者！听从我的召唤！', `MaleText_loc5`='來吧，黑暗中的生物!重新振作聽從我的指令!', `MaleText_loc7`='¡A mí, habitantes de la oscuridad! ¡Reúnanse a mi llamada!' WHERE `ID`=15150;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 귀여운 아이들아... 먹이가 아주 많구나!', `MaleText_loc4`='快来吧，我的宠物们。来吃个够吧！', `MaleText_loc5`='集合，我的寵物...食物夠大家分的!', `MaleText_loc7`='Vengan, mascotas mías, ¡hay para todas!' WHERE `ID`=15151;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대모께서 말씀하시길 제 이름은 한 위대한 오크족 영웅의 이름을 딴 것이라고 하셨습니다.', `FemaleText_loc4`='盖亚安祖母曾跟我说，我的名字来自一位伟大的兽人英雄。', `FemaleText_loc5`='主母跟我說我是依一個偉大的獸人英雄命名的。', `FemaleText_loc7`='La Abuela dice que me llamo como un gran héroe orco.' WHERE `ID`=15152;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음... 맛있구나.', `MaleText_loc4`='啊……美味极了。', `MaleText_loc5`='嗯...好吃。', `MaleText_loc7`='Mmmm... que delicia.' WHERE `ID`=15153;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 낡은 양철통 신세로구나!', `MaleText_loc4`='又变成一堆废铜烂铁了。', `MaleText_loc5`='繼續當個老鐵鏽。', `MaleText_loc7`='Otra vez a hacer de cubo oxidado.' WHERE `ID`=15155;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 솜씨가 아직 녹슬지 않았네.', `MaleText_loc4`='看来我还没有锈成一团废铁。', `MaleText_loc5`='看起來我還沒有銹得很嚴重嘛。', `MaleText_loc7`='Supongo que no estoy tan oxidado al fin y al cabo.' WHERE `ID`=15156;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 자리를 옮기더니 가시에 긁혀 고통으로 신음합니다.', `MaleText_loc4`='由于被荆棘划伤，%s发出了痛苦的呻吟。', `MaleText_loc5`='變形中，%s因為被刺刮傷的痛苦而呻吟著。', `MaleText_loc7`='Moviéndose, %s se queja del dolor del arañazo de la espina.' WHERE `ID`=15157;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 고통에 울부짖습니다.', `MaleText_loc4`='%s痛苦地呻吟着。', `MaleText_loc5`='%s痛苦地呻吟。', `MaleText_loc7`='%s gruñe de dolor.' WHERE `ID`=15158;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 동료를 바라보더니 아픈 듯이 투덜거립니다.', `MaleText_loc4`='%s看了看他的朋友们，然后痛苦地嘟哝着。', `MaleText_loc5`='%s看著他的朋友然後痛苦地咕噥著。', `MaleText_loc7`='%s mira a sus amigos y gruñe terriblemente.' WHERE `ID`=15159;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 자신의 코 고는 소리에 잠이 깹니다.', `MaleText_loc4`='%s的鼾声把自己惊醒了。', `MaleText_loc5`='%s把他從鼾聲中叫醒。', `MaleText_loc7`='%s se despierta roncando.' WHERE `ID`=15160;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 긁힌 상처 주위의 부드러운 부위를 만지더니 주춤합니다.', `MaleText_loc4`='%s触摸到了自己伤口附近柔软的肌体，疼得颤抖了一下。', `MaleText_loc5`='%s觸摸他抓痕的脆弱處，開始感到退縮。', `MaleText_loc7`='%s hace una mueca de dolor cuando toca la zona sensible de alrededor de su arañazo.' WHERE `ID`=15161;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 휘파람으로 노래를 부르다가 갑자기 멈추더니 신음합니다.', `MaleText_loc4`='%s开始吹口哨，但突然停住，呻吟了起来。', `MaleText_loc5`='%s開始哼起一首小調，然後突然停下並開始嗚咽。', `MaleText_loc7`='%s comienza a silbar una melodía, pero se detiene bruscamente y gime.' WHERE `ID`=15162;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 시대가 왔다!', `MaleText_loc4`='我们翘首企盼的日子终于来了！', `MaleText_loc5`='我們的時代來臨了!', `MaleText_loc7`='¡Ha llegado nuestra hora!' WHERE `ID`=15163;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 마법사는 몰락할 것이다!', `MaleText_loc4`='麦迪文会被打倒的！', `MaleText_loc5`='巫師將會倒下!', `MaleText_loc7`='¡El zahorí caerá!' WHERE `ID`=15164;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='집행자들이여! 모두 죽여라!', `MaleText_loc4`='进攻！杀光他们！', `MaleText_loc5`='執行者!殺光他們!', `MaleText_loc7`='¡Gorilas! ¡Matadlos a todos!' WHERE `ID`=15165;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 결코 멈추지 않는다!', `MaleText_loc4`='我们是不会被阻止的！', `MaleText_loc5`='沒有人阻擋的了我們!', `MaleText_loc7`='¡No nos detendrán!' WHERE `ID`=15166;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 많은 무한의 용군단이 내 자리를 대신할 것이다.', `MaleText_loc4`='更多人会顶上我的位置。', `MaleText_loc5`='會有更多人來替補我的位置。', `MaleText_loc7`='Habrá más que ocupen mi lugar.' WHERE `ID`=15167;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희의 노력은... 쓸데없는 짓이니라.', `MaleText_loc4`='你所做的努力……都是徒劳。', `MaleText_loc5`='你的努力...都是白費力氣。', `MaleText_loc7`='Sus esfuerzos... son en vano.' WHERE `ID`=15168;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희는 그를 구하지 못할 것이다!', `MaleText_loc4`='别想挽救他！', `MaleText_loc5`='你救不了他的!', `MaleText_loc7`='¡No lo salvarás!' WHERE `ID`=15169;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 시간의 길은 우리가 관리한다!', `MaleText_loc4`='我们控制了时间之流！', `MaleText_loc5`='我們現在控制時間之道了!', `MaleText_loc7`='¡Nosotros controlamos los portales del tiempo ahora!' WHERE `ID`=15170;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='최후의 수호자를 해치워라!', `FemaleText_loc4`='最后的守护者，去死吧！', `FemaleText_loc5`='讓最後的守護者死吧!', `FemaleText_loc7`='¡Muerte al último guardián!' WHERE `ID`=15171;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리를 막지 못할지니!', `FemaleText_loc4`='你别想挡我们的路！', `FemaleText_loc5`='你阻礙不了我們的!', `FemaleText_loc7`='¡No te interpondrás en nuestro camino!' WHERE `ID`=15172;
