UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 합리적인 $r|1으로;로; 보인다! 우리는 서로 도움이 될 수 있을 것이다.', `MaleText_loc4`='你似乎是个通情达理的$R。或许我们能互相帮助。', `MaleText_loc5`='你看起來是個講理的$r。或許我們可以互相幫助。', `MaleText_loc7`='Pareces $gun:una; $r razonable. Quizás podamos ayudarnos mutuamente.' WHERE `ID`=15197;
