UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈이 한 짓에 대한 대가를 치르게 해주마!', `MaleText_loc4`='我会让你为此付出代价的！', `MaleText_loc5`='我會讓你為此付出代價的!', `MaleText_loc7`='¡Te haré pagar por ello!' WHERE `ID`=15199;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여러분, 제발 부탁입니다. 아주 하찮은 재료나 싸구려 물건도 좋으니 적선해 주십시오. 이 불쌍한 영혼을 도와주세요!', `MaleText_loc4`='女士们，请帮帮我吧。我很绝望。你们可以随便施舍点东西……最微不足道的魔法材料，最便宜的物品，帮帮一个需要帮助的可怜人吧！', `MaleText_loc5`='女士們，拜託。我走頭無路了。你們一定可以施捨什麼...一點點試劑也好，你們最便宜的貨物也好。救救需要的靈魂吧!', `MaleText_loc7`='Damas, por favor. Estoy desesperado. Desde luego pueden prescindir de algo... el componente más pequeño, sus mercancías más baratas. ¡Ayuden a un alma necesitada!' WHERE `ID`=15200;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장군 칼리스레쉬께서 네놈의 무례한 짓에 대해서 알게 되실 것이다!', `MaleText_loc4`='督军卡利瑟里斯会很高兴看到你们这些傲慢的家伙被干掉的！', `MaleText_loc5`='督軍卡利斯瑞會知道這樣傲慢無禮的行為的!', `MaleText_loc7`='¡El señor de la guerra Kalithresh sabrá de esta insolencia!' WHERE `ID`=15201;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시는 우리를 거역하지 못하게 해주겠다!', `MaleText_loc4`='别想再插手我们的事情！', `MaleText_loc5`='我會讓你知道不要再妨礙我們了!', `MaleText_loc7`='¡Te enseñaré a no cruzarte en nuestro camino de nuevo!' WHERE `ID`=15202;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 입술을 바르르 떨더니 쓸쓸히 상점에서 물러납니다.', `MaleText_loc4`='%s的嘴唇颤抖着，失落地拖着腿走出了商店。', `MaleText_loc5`='%s的嘴唇顫抖，他拖著腳步無望地走出店外。', `MaleText_loc7`='A %s le tiemblan los labios y sale de la tienda arrastrando los pies desolado.' WHERE `ID`=15203;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='카일란, 거지에게 줄 물건은 없네요.', `FemaleText_loc4`='没有施舍，塞伊兰。', `FemaleText_loc5`='不施捨，凱歐蘭。', `FemaleText_loc7`='Nada de limosnas, Cailan.' WHERE `ID`=15204;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내가 그대의 중독 현상이 계속되게 한 것은 아니잖아요. 그건 절대 내 잘못이 아닙니다. 나가주세요.', `FemaleText_loc4`='我不会让你这么沉迷下去的。这又不是我的过错。滚出去！', `FemaleText_loc5`='我不打算讓你的魔法癮永久存在。那不是我的錯。出去。', `FemaleText_loc7`='No voy a alimentar tu adicción. Yo no soy la responsable. Fuera.' WHERE `ID`=15205;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강해지시오. 캘타스는 우릴 배반했고 우리가 아는 건 항상 변하고 있소. 하지만 낙담해서는 안 되오. 우린 항상 그래왔던 것처럼 이겨낼 거요. 아서스가 우리 땅을 휩쓸었을 때도 우리 영혼을 파괴하진 못했지 않소. 그리고 캘타스도 그러지 못할 거요. 번영하는 우리의 미래로 나아갈 수 있도록 모두에게 교훈이 되게 하시오.', `MaleText_loc4`='坚强一些。凯尔萨斯背叛了我们，我们的希冀变成了泡影，但是不要失去信心。我们会坚持到底，就像以前一样。阿尔萨斯的铁蹄没有摧毁我们的精神，凯尔萨斯也绝不可能让我们毁灭。就让这变故成为我们永远铭记的一课吧。', `MaleText_loc5`='堅強點。凱爾薩斯已經背叛我們了，我們所知了解的事物正在變化，不過不要失去信心。我們將會如同我們一直以來所做的，忍耐。當阿薩斯橫掃過我們的大陸時都沒能擊垮我們的精神，而凱爾薩斯也一樣。就讓這成為我們前進繁榮的未來所該學到的一課吧。', `MaleText_loc7`='Sean fuertes. Kael''thas nos ha traicionado y lo que sabemos es incierto, pero no se desmoralicen. Aguantaremos como lo hemos hecho siempre. Arthas no consiguió destrozar nuestro ánimo cuando barrio nuestra tierra y tampoco lo conseguirá Kael''thas. Aprendamos algo de esto mientras avanzamos hacia un futuro próspero.' WHERE `ID`=15206;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 멋진 도시에서 어디를 가고자 하시오?', `MaleText_loc4`='你想到我们美丽的城市哪个区域逛逛？', `MaleText_loc5`='你想去我們城市的哪裡呢?', `MaleText_loc7`='¿A qué lugar de nuestra bella ciudad deseas ir?', `FemaleText_loc1`='우리의 멋진 도시에서 어디를 가고자 하십니까?', `FemaleText_loc4`='你想到我们美丽的城市哪个区域逛逛？', `FemaleText_loc5`='你想去我們城市的哪裡呢?', `FemaleText_loc7`='¿A qué lugar de nuestra bella ciudad deseas ir?' WHERE `ID`=15207;
