UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실버문에는 두 개의 경매장이 있소. 어느 경매장에 가고 싶으시오?', `MaleText_loc4`='我们的银月城有两座拍卖行，你喜欢哪个？', `MaleText_loc5`='我們銀月城裡有兩間拍賣場。你比較偏好哪一個?', `MaleText_loc7`='Hay dos casas de subastas en Lunargenta. ¿Cuál prefieres?', `FemaleText_loc1`='실버문에는 두 개의 경매장이 있습니다. 어느 경매장에 가고 싶으신가요?', `FemaleText_loc4`='我们的银月城有两座拍卖行，你喜欢哪个？', `FemaleText_loc5`='我們銀月城裡有兩間拍賣場。你比較偏好哪一個?', `FemaleText_loc7`='Hay dos casas de subastas en Lunargenta. ¿Cuál prefieres?' WHERE `ID`=15209;
