UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서쪽 경매장은 시장 중앙에 있소. 장로의 거리 바로 서쪽이니 그리로 가 보시오.', `MaleText_loc4`='西面的那座拍卖行可以在花园街市中间找到，就在长者步道往西一点。', `MaleText_loc5`='西邊拍賣場就在商店街中段，長者步道西邊。', `MaleText_loc7`='La casa de subastas del oeste está en el medio del Bazar, al oeste del Camino de los Ancestros.', `FemaleText_loc1`='서쪽 경매장은 시장 중앙에 있습니다. 장로의 거리 바로 서쪽이니 그리로 가 보십시오.', `FemaleText_loc4`='西面的那座拍卖行可以在花园街市中间找到，就在长者步道往西一点。', `FemaleText_loc5`='西邊拍賣場就在商店街中段，長者步道西邊。', `FemaleText_loc7`='La casa de subastas del oeste está en el medio del Bazar, al oeste del Camino de los Ancestros.' WHERE `ID`=15211;
