UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왕궁 교역소 경매장은 이 도시의 동부에 있소이다. 혈기사들과 순찰대들이 훈련하는 지역의 바로 남쪽이오.', `MaleText_loc4`='皇家贸易区的拍卖行可以在城市的东部找到，就在血骑士和猎人的训练区域往南一点。', `MaleText_loc5`='皇家交易所拍賣場就在城東邊，血騎士和遊俠訓練區的南方。', `MaleText_loc7`='La casa de subastas del Intercambio Real está en la zona este de la ciudad, al sur del área de entrenamiento de Caballeros de sangre y forestales.', `FemaleText_loc1`='왕궁 교역소 경매장은 이 도시의 동부에 있습니다. 혈기사들과 순찰대들이 훈련하는 지역의 바로 남쪽이지요.', `FemaleText_loc4`='皇家贸易区的拍卖行可以在城市的东部找到，就在血骑士和猎人的训练区域往南一点。', `FemaleText_loc5`='皇家交易所拍賣場就在城東邊，血騎士和遊俠訓練區的南方。', `FemaleText_loc7`='La casa de subastas del Intercambio Real está en la zona este de la ciudad, al sur del área de entrenamiento de Caballeros de sangre y forestales.' WHERE `ID`=15213;
