UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실버문에는 두 개의 은행이 있는데 어떤 은행을 찾으시오?', `MaleText_loc4`='这儿有两座银行，你想去哪一座？', `MaleText_loc5`='你想參觀我們兩間銀行的哪一間呢?', `MaleText_loc7`='¿Cuál de nuestros dos bancos te gustaría visitar?', `FemaleText_loc1`='실버문에는 두 개의 은행이 있는데 어떤 은행을 찾으십니까?', `FemaleText_loc4`='这儿有两座银行，你想去哪一座？', `FemaleText_loc5`='你想參觀我們兩間銀行的哪一間呢?', `FemaleText_loc7`='¿Cuál de nuestros dos bancos te gustaría visitar?' WHERE `ID`=15215;
