UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실버문 은행은 시장 안의 남동쪽 가장자리로 가서 찾으면 되오.', `MaleText_loc4`='银月城银行就在花园街市。去东南角找找吧。', `MaleText_loc5`='你可以在商店街找到西邊的銀行。去東南方的角落找找。', `MaleText_loc7`='El Banco de Lunargenta se puede encontrar dentro del Bazar. Búscalo en la esquina sureste.', `FemaleText_loc1`='실버문 은행은 시장 안의 남동쪽 가장자리로 가서 찾으면 됩니다.', `FemaleText_loc4`='银月城银行就在花园街市。去东南角找找吧。', `FemaleText_loc5`='你可以在商店街裡找到西邊的銀行。去東南方的角落找找。', `FemaleText_loc7`='El Banco de Lunargenta se puede encontrar dentro del Bazar. Búscalo en la esquina sureste.' WHERE `ID`=15217;
