UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도시 동부에 있는 은행을 찾는다면 왕궁 교역소를 찾으면 되오. 은행은 그 안에서 북쪽 성벽을 따라가면 있소이다.', `MaleText_loc4`='如果你想要在城市的东部找一家银行的话，就在皇家贸易区的北墙那里。', `MaleText_loc5`='如果你在找城市東邊的銀行，就去皇家交易所拍賣場找吧。它就在北邊的牆那裡。', `MaleText_loc7`='Si buscas un banco en la parte este de la ciudad, no busques más lejos, ve al Intercambio Real. Está en el muro norte.', `FemaleText_loc1`='도시 동부에 있는 은행을 찾는다면 왕궁 교역소를 찾으면 됩니다. 은행은 그 안에서 북쪽 성벽을 따라가면 있습니다.', `FemaleText_loc4`='如果你想要在城市的东部找一家银行的话，就在皇家贸易区的北墙那里。', `FemaleText_loc5`='如果你在找城市東邊的銀行，就去皇家交易所拍賣場找吧。它就在北邊的牆那裡。', `FemaleText_loc7`='Si buscas un banco en la parte este de la ciudad, no busques más lejos, ve al Intercambio Real. Está en el muro norte.' WHERE `ID`=15219;
