UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밖으로 나가서 수호자의 관문 서쪽으로 가면 창공의 조련사 글로밍과 그녀의 용매들을 만날 수 있소.', `MaleText_loc4`='葛拉米和她的龙鹰就在城外的牧羊人之门西面。', `MaleText_loc5`='女飛行師薄暮和她的龍鷹就在外頭西邊的牧羊人之門。', `MaleText_loc7`='La maestra del cielo Anochecer y sus dracohalcones están fuera y hacia el oeste de la Puerta del Pastor.', `FemaleText_loc1`='밖으로 나가서 수호자의 관문 서쪽으로 가면 창공의 조련사 글로밍과 그녀의 용매들을 만날 수 있소.', `FemaleText_loc4`='葛拉米和她的龙鹰就在城外的牧羊人之门西面。', `FemaleText_loc5`='女飛行師薄暮和她的龍鷹就在外頭西邊的牧羊人之門。', `FemaleText_loc7`='La maestra del cielo Anochecer y sus dracohalcones están fuera y hacia el oeste de la Puerta del Pastor.' WHERE `ID`=15221;
