UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실버문의 길드 사무관은 탄드린으로 그녀의 사무소는 장로의 거리를 따라가면 있는데 마법학자의 관문에서 가까우니 그리로 가 보시오.', `MaleText_loc4`='坦德莉恩是银月城的公会注册员。她的住处就在长者步街上，魔导师之门附近。', `MaleText_loc5`='泰德林是銀月城的公會註冊員。她就住在長者步道上，離博學者之門很近。', `MaleText_loc7`='Tandrine es la Maestra de la hermandad de Lunargenta. Se encuentra en el Camino de los Ancestros, cerca de la Puerta Magister.', `FemaleText_loc1`='실버문의 길드 사무관은 탄드린으로 그녀의 사무소는 장로의 거리를 따라가면 있는데 마법학자의 관문에서 가까우니 그리로 가 보십시오.', `FemaleText_loc4`='坦德莉恩是银月城的公会注册员。她的住处就在长者步街上，魔导师之门附近。', `FemaleText_loc5`='泰德林是銀月城的公會註冊員。她就住在長者步道上，離博學者之門很近。', `FemaleText_loc7`='Tandrine es la Maestra de la hermandad de Lunargenta. Se encuentra en el Camino de los Ancestros, cerca de la Puerta Magister.' WHERE `ID`=15223;
