UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벨란드라라는 재능 있는 여성이 운영하는 실버문 여관은 왕궁 교역소 안에 있소. 저명한 양조업자가 종종 그곳에 들린다는 소문도 있었소이다.', `MaleText_loc4`='银月城旅店座落在皇家贸易区，由一个叫维兰德拉的女人经营着。我听说那个有名的调酒师有时也会出现在那里。', `MaleText_loc5`='銀月城旅店就在皇家交易所拍賣場裡，由一個聰明的女性，費蘭卓經營。我聽說有名的植物大師有時候也會在那裡出現。', `MaleText_loc7`='La Posada de la Ciudad de Lunargenta, ubicada en el Intercambio Real, está regentada por una mujer de talento llamada Velandra. Me han dicho que también se puede encontrar allí, a veces, al renombrado maestro vinícola.', `FemaleText_loc1`='벨란드라라는 재능 있는 여성이 운영하는 실버문 여관은 왕궁 교역소 안에 있습니다. 저명한 양조업자가 종종 그곳에 들린다는 소문도 들었습니다.', `FemaleText_loc4`='银月城旅店座落在皇家贸易区，由一个叫维兰德拉的女人经营着。我听说那个有名的调酒师有时也会出现在那里。', `FemaleText_loc5`='銀月城旅店就在皇家交易所拍賣場裡，由一個聰明的女性，費蘭卓經營。我聽說有名的植物大師有時候也會在那裡出現。', `FemaleText_loc7`='La Posada de la Ciudad de Lunargenta, ubicada en el Intercambio Real, está regentada por una mujer de talento llamada Velandra. Me han dicho que también se puede encontrar allí, a veces, al renombrado maestro vinícola.' WHERE `ID`=15225;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우체통', `MaleText_loc4`='邮箱', `MaleText_loc5`='郵箱', `MaleText_loc7`='Buzón', `FemaleText_loc1`='우체통', `FemaleText_loc4`='邮箱', `FemaleText_loc5`='郵箱', `FemaleText_loc7`='Buzón' WHERE `ID`=15226;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 실버문에는 우체통이 수없이 많소. 그중 왕궁 교역소 은행에서 관리하는 우체통이 그대의 목적에 딱 맞을 것이오.', `MaleText_loc4`='在我们美丽的城市里有许多邮箱。靠近皇家贸易区银行的那个对你来说应该非常方便。', `MaleText_loc5`='我們城裡有大量的郵箱。皇家交易所銀行旁的那個應該符合你的需求。', `MaleText_loc7`='Tenemos una gran abundancia de buzones de correo en nuestra hermosa ciudad. El que se encuentra junto al Banco Real de Cambio debería ajustarse a tus necesidades.', `FemaleText_loc1`='우리 도시에는 우체통이 수없이 많죠. 그중 왕궁 교역소 은행에서 관리하는 우체통이 그대의 목적에 딱 맞을 것입니다.', `FemaleText_loc4`='在我们美丽的城市里有许多邮箱。靠近皇家贸易区银行的那个对你来说应该非常方便。', `FemaleText_loc5`='我們城裡有大量的郵箱。皇家交易所銀行旁的那個應該符合你的需求。', `FemaleText_loc7`='Tenemos una gran abundancia de buzones de correo en nuestra hermosa ciudad. El que se encuentra junto al Banco Real de Cambio debería ajustarse a tus necesidades.' WHERE `ID`=15227;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야수 관리인', `MaleText_loc4`='兽栏管理员', `MaleText_loc5`='獸欄管理員', `MaleText_loc7`='Maestro de establos', `FemaleText_loc1`='야수 관리인', `FemaleText_loc4`='兽栏管理员', `FemaleText_loc5`='獸欄管理員', `FemaleText_loc7`='Maestro de establos' WHERE `ID`=15228;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 도시 안에서 야수를 돌보는 샬렌은 그 주인들이 밖에서 일을 보러 간 사이 야수들이 날뛰지 못하도록 돌봐주고 있소. 그녀는 원정순찰대 광장 안의 순찰자의 전당 바로 바깥에 있으니 그리로 가 보시오.', `MaleText_loc4`='沙尔蕾恩在城市里面照顾动物，避免它们在主人离开的时候因为无所事事而发狂。她就在远行者广场的游侠大厅外面。', `MaleText_loc5`='賽玲在城裡照料動物，當他們的主人不顧性命作戰時她會保護他們。她就在遠行者廣場的遊俠大廳外面。', `MaleText_loc7`='Shalenn se ocupa de los animales en la ciudad y evita que se pongan nerviosos cuando sus dueños están de paseo. Está en la Plaza del Errante, cerca de la sala de los forestales.', `FemaleText_loc1`='이 도시 안에서 야수를 돌보는 샬렌은 그 주인들이 밖에서 일을 보러 간 사이 야수들이 날뛰지 못하도록 돌봐주지요. 그녀는 원정순찰대 광장 안의 순찰자의 전당 바로 바깥에 있으니 그리로 가 보십시오.', `FemaleText_loc4`='沙尔蕾恩在城市里面照顾动物，避免它们在主人离开的时候因为无所事事而发狂。她就在远行者广场的游侠大厅外面。', `FemaleText_loc5`='賽玲在城裡照料動物，當他們的主人不顧性命作戰時她會保護他們。她就在遠行者廣場的遊俠大廳外面。', `FemaleText_loc7`='Shalenn se ocupa de los animales en la ciudad y evita que se pongan nerviosos cuando sus dueños están de paseo. Está en la Plaza del Errante, cerca de la sala de los forestales.' WHERE `ID`=15229;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무기 전문가', `MaleText_loc4`='武器大师', `MaleText_loc5`='武器大師', `MaleText_loc7`='Maestro de armas', `FemaleText_loc1`='무기 전문가', `FemaleText_loc4`='武器大师', `FemaleText_loc5`='武器大師', `FemaleText_loc7`='Maestro de armas' WHERE `ID`=15230;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원정순찰대 광장의 혈기사들이 친절하게도 실버문의 무기 전문가 일레다에게 자신들의 전당을 사용하도록 허락했소이다. 그녀가 요구하는 훈련 비용이 결코 적지는 않지만 그대도 그녀의 전문 지식에 감탄할 것이오.', `MaleText_loc4`='远行者广场的血骑士慷慨地允许银月城的武器大师伊蕾达使用他们的大厅。虽然她的训练费用并不便宜，但是你会非常欣赏她的专业素养。', `MaleText_loc5`='遠行者廣場的血騎士好心地讓了他們大廳一個空間給伊利達，銀月城的武器大師。雖然她的訓練不便宜，但她的專業知識會讓你激賞的。', `MaleText_loc7`='Los Caballeros de sangre de la Plaza del Errante ceden generosamente espacio en su sala para Ileda, la maestra de armas de Lunargenta. Su entrenamiento no es barato, pero apreciarás su experiencia.', `FemaleText_loc1`='원정순찰대 광장의 혈기사들이 친절하게도 실버문의 무기 전문가 일레다에게 자신들의 전당을 사용하도록 허락했답니다. 그녀가 요구하는 훈련 비용이 결코 적지는 않지만 그대도 그녀의 전문 지식에 감탄할 것입니다.', `FemaleText_loc4`='远行者广场的血骑士慷慨地允许银月城的武器大师伊蕾达使用他们的大厅。虽然她的训练费用并不便宜，但是你会非常欣赏她的专业素养。', `FemaleText_loc5`='遠行者廣場的血騎士好心地讓了他們大廳一個空間給伊利達，銀月城的武器大師。雖然她的訓練不便宜，但她的專業知識會讓你激賞的。', `FemaleText_loc7`='Los Caballeros de sangre de la Plaza del Errante ceden generosamente espacio en su sala para Ileda, la maestra de armas de Lunargenta. Su entrenamiento no es barato, pero apreciarás su experiencia.' WHERE `ID`=15231;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투모병관', `MaleText_loc4`='战场军官', `MaleText_loc5`='戰場軍官', `MaleText_loc7`='Maestros de batalla', `FemaleText_loc1`='전투모병관', `FemaleText_loc4`='战场军官', `FemaleText_loc5`='戰場軍官', `FemaleText_loc7`='Maestros de batalla' WHERE `ID`=15232;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투모병관들은 원정순찰대 광장의 혈기사 자치령에 있는 전당 깊숙한 곳에서 휴식을 취하고 있소. 예의가 좀 없기는 하지만... 어쨌든 그들은 굉장한 혜택을 제공한다오.', `MaleText_loc4`='战场军官们在远行者广场的血骑士大厅深处。虽然他们有点……粗鲁，但还是有些优点的。', `MaleText_loc5`='三個戰場軍官悠閒的在遠行者廣場裡休息，就在血騎士營地的大廳裡。雖然他們有些...粗野，但他們也有其可取之處。', `MaleText_loc7`='Los maestros de batalla descansan detrás de los muros del enclave de los Caballeros de sangre, en la Plaza del Errante. Aunque suelen ser... un poco bruscos, también tienen sus bondades.', `FemaleText_loc1`='전투모병관들은 원정순찰대 광장의 혈기사 자치령에 있는 전당 깊숙한 곳에서 휴식을 취하고 있습니다. 예의가 좀 없기는 하지만... 어쨌든 그들은 굉장한 혜택을 제공하지요.', `FemaleText_loc4`='战场军官们在远行者广场的血骑士大厅深处。虽然他们有点……粗鲁，但还是有些优点的。', `FemaleText_loc5`='三個戰場軍官悠閒的在遠行者廣場裡休息，就在血騎士營地的大廳裡。雖然他們有些...粗野，但他們也有其可取之處。', `FemaleText_loc7`='Los maestros de batalla descansan detrás de los muros del enclave de los Caballeros de sangre, en la Plaza del Errante. Aunque suelen ser... un poco bruscos, también tienen sus bondades.' WHERE `ID`=15233;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='직업 상급자', `MaleText_loc4`='职业训练师', `MaleText_loc5`='職業訓練師', `MaleText_loc7`='Instructor de clase', `FemaleText_loc1`='직업 상급자', `FemaleText_loc4`='职业训练师', `FemaleText_loc5`='職業訓練師', `FemaleText_loc7`='Instructor de clase' WHERE `ID`=15234;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디로 가고자 하시오?', `MaleText_loc4`='你希望选择哪条发展之路？', `MaleText_loc5`='你想追尋什麼道路?', `MaleText_loc7`='¿Qué camino quieres seguir?', `FemaleText_loc1`='어디로 가고자 하시오?', `FemaleText_loc4`='你希望选择哪条发展之路？', `FemaleText_loc5`='你想追尋什麼道路?', `FemaleText_loc7`='¿Qué camino quieres seguir?' WHERE `ID`=15235;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드루이드', `MaleText_loc4`='德鲁伊', `MaleText_loc5`='德魯伊', `MaleText_loc7`='Druida', `FemaleText_loc1`='드루이드', `FemaleText_loc4`='德鲁伊', `FemaleText_loc5`='德魯伊', `FemaleText_loc7`='Druida' WHERE `ID`=15236;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드루이드? 우리 종족은 드루이드의 길을 걷지 않지만... 그대는 참 운이 좋군. 내가 보기에 여성임이 틀림없는 한 타우렌이 장로의 거리 북쪽 끝에 아담한 처소를 짓고 살고 있는데 그녀의 이름은 하레네 플레인워커라오.', `MaleText_loc4`='德鲁伊之路？我们的人不会选择这个……但是你很幸运。一个女性牛头人——至少，我相信那是个女性——在长者步道的北面尽头建了个住处。她叫哈雷尼·平原行者。', `MaleText_loc5`='德魯伊的一員?我們的人民不走那條路的...但你很幸運。一個牛頭人女性 - 至少我認為她是個女性 - 已在長者步道的北方盡頭建立了一個有模有樣的居住地。她的名字叫海若妮·大地行者。', `MaleText_loc7`='¿Un druida? Nuestra gente no sigue ese camino..., pero estás de suerte. Una tauren, creo que se trata de una hembra, se ha instalado en una modesta casa al norte del Camino de los Ancestros. Se llama Harene Correllanos.', `FemaleText_loc1`='드루이드요? 우리 종족은 드루이드의 길을 걷지 않지만... 그대는 참 운이 좋군요. 제가 보기에 여성임이 틀림없는 한 타우렌이 장로의 거리 북쪽 끝에 아담한 처소를 짓고 살고 있는데 그녀의 이름은 하레네 플레인워커라고 하더군요.', `FemaleText_loc4`='德鲁伊之路？我们的人不会选择这个……但是你很幸运。一个女性牛头人——至少，我相信那是个女性——在长者步道的北面尽头建了个住处。她叫哈雷尼·平原行者。', `FemaleText_loc5`='德魯伊的一員?我們的人民不走那條路的...但你很幸運。一個牛頭人女性 - 至少我認為她是個女性 - 已在長者步道的北方盡頭建立了一個有模有樣的居住地。她的名字叫海若妮·大地行者。', `FemaleText_loc7`='¿Un druida? Nuestra gente no sigue ese camino..., pero estás de suerte. Una tauren, creo que se trata de una hembra, se ha instalado en una modesta casa al norte del Camino de los Ancestros. Se llama Harene Correllanos.' WHERE `ID`=15237;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사냥꾼', `MaleText_loc4`='猎人', `MaleText_loc5`='獵人', `MaleText_loc7`='Cazador', `FemaleText_loc1`='사냥꾼', `FemaleText_loc4`='猎人', `FemaleText_loc5`='獵人', `FemaleText_loc7`='Cazador' WHERE `ID`=15238;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하필이면... 흠, 그대가 진정 시대에 뒤 떨어지는 그 사냥꾼들과 대화를 하면서 시간을 낭비하고 싶다면 원정순찰대 광장을 찾아가 보시오. 잔디네가 그대를 돌봐줄 것이오.', `MaleText_loc4`='哦，你在找……他们。好啊，如果你真的想浪费你的时间来和那些迟钝的家伙谈话，可以在远行者广场里面找到这些游侠。桑迪恩会接待你的。', `MaleText_loc5`='喔。你在找他們...的一員啊。嗯，如果你真的想浪費時間和那些畏縮的人講話，你可以在遠行者廣場找到那些遊俠。席丹會照顧你。', `MaleText_loc7`='Ah, buscas a uno... de esos. Bueno, si de veras quieres perder tu tiempo hablando con un raro de esos, encontrarás a los forestales en la Plaza del Errante. Zandine podrá atenderte.', `FemaleText_loc1`='하필이면... 흠, 그대가 진정 시대에 뒤 떨어지는 그 사냥꾼들과 대화를 하면서 시간을 낭비하고 싶다면 원정순찰대 광장을 찾아가 보십시오. 잔디네가 그대를 돌봐줄 겁니다.', `FemaleText_loc4`='哦，你在找……他们。好啊，如果你真的想浪费你的时间来和那些迟钝的家伙谈话，可以在远行者广场里面找到这些游侠。桑迪恩会接待你的。', `FemaleText_loc5`='喔。你在找他們...的一員啊。嗯，如果你真的想浪費時間和那些畏縮的人講話，你可以在遠行者廣場找到那些遊俠。席丹會照顧你。', `FemaleText_loc7`='Ah, buscas a uno... de esos. Bueno, si de veras quieres perder tu tiempo hablando con un raro de esos, encontrarás a los forestales en la Plaza del Errante. Zandine podrá atenderte.' WHERE `ID`=15239;
