UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비전 마법의 대가를 찾고 있소? 성난태양 첨탑으로 가면 쿠이타스와 다른 마법학자들을 만날 수 있소이다.', `MaleText_loc4`='啊，你在找传授神秘魔法的导师吗？你可以在日怒之塔找到奎恩萨斯和其他的魔导师。', `MaleText_loc5`='啊，在尋找秘法大師嗎?你可以在日怒尖塔裡找到奎薩斯和其他博學者。', `MaleText_loc7`='Ah, ¿buscas a los maestros de lo Arcano? Puedes encontrar a Quithas y a los otros magistri en la Aguja Furia del Sol.', `FemaleText_loc1`='비전 마법의 대가를 찾고 있군요? 성난태양 첨탑으로 가면 쿠이타스와 다른 마법학자들을 만날 수 있습니다.', `FemaleText_loc4`='啊，你在找传授神秘魔法的导师吗？你可以在日怒之塔找到奎恩萨斯和其他的魔导师。', `FemaleText_loc5`='啊，在尋找秘法大師嗎?你可以在日怒尖塔裡找到奎薩斯和其他博學者。', `FemaleText_loc7`='Ah, ¿buscas a los maestros de lo Arcano? Puedes encontrar a Quithas y a los otros magistri en la Aguja Furia del Sol.' WHERE `ID`=15245;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혈기사들의 지도자인 여군주 리아드린이 원정순찰대 광장의 한 자치령에서 혈기사단을 지도하고 있소. 훈련을 원한다면 그곳에 있는 부사령관 바치와 대화해 보시오. 그대도 자신의 목숨이 귀중한 줄 알고 있다면 그곳에 있는 동안 예절 바르게 행동하도록 하시오.', `MaleText_loc4`='女伯爵莉亚德琳，血骑士的领袖，把她的血骑士总部设在远行者广场的边上。如果你需要什么指导的话，可以去和勇士巴卡希谈谈。倘若你想要保住自己的脑袋，记得在那里说话时放礼貌点。', `MaleText_loc5`='血騎士的女王，莉雅德倫女士把她的血騎士都配置在遠行者廣場的一個營地裡。假如你想尋找進一步的指導，你必須跟那邊的貝戚勇士談話。如果你想活命的話到那裡就要抱著恭敬的態度。', `MaleText_loc7`='Lady Liadrin, matriarca de los Caballeros de sangre, tiene el puesto de mando en la Plaza del Errante. Tendrás que hablar con el Campeón Bachi si quieres recibir instrucción. Habla siempre con respeto si aprecias tu cabeza.', `FemaleText_loc1`='혈기사들의 지도자인 여군주 리아드린이 원정순찰대 광장의 한 자치령에서 혈기사단을 지도하고 있습니다. 훈련을 원한다면 그곳에 있는 부사령관 바치와 대화해 보십시오. 그대도 자신의 목숨이 귀중한 줄 알고 계신다면 그곳에 있는 동안 예절 바르게 행동하십시오.', `FemaleText_loc4`='女伯爵莉亚德琳，血骑士的领袖，把她的血骑士总部设在远行者广场的边上。如果你需要什么指导的话，可以去和勇士巴卡希谈谈。倘若你想要保住自己的脑袋，记得在那里说话时放礼貌点。', `FemaleText_loc5`='血騎士的女王，莉雅德倫女士把她的血騎士都配置在遠行者廣場的一個營地裡。假如你想尋找進一步的指導，你必須跟那邊的貝戚勇士談話。如果你想活命的話到那裡就要抱著恭敬的態度。', `FemaleText_loc7`='Lady Liadrin, matriarca de los Caballeros de sangre, tiene el puesto de mando en la Plaza del Errante. Tendrás que hablar con el Campeón Bachi si quieres recibir instrucción. Habla siempre con respeto si aprecias tu cabeza.' WHERE `ID`=15246;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성난태양 첨탑으로 가면 우리 도시의 사제들을 만날 수 있으니 벨레스트라를 찾아보시오.', `MaleText_loc4`='我们这座美丽城市中的牧师在日怒之塔内。去那里找贝蕾丝特拉女士吧。', `MaleText_loc5`='你可以在日怒尖塔找到這個美麗城市的牧師。去找拜拉斯卓女士吧。', `MaleText_loc7`='Los sacerdotes de nuestra bella ciudad se pueden encontrar en la Aguja Furia del Sol. Busca a la dama Belestra.', `FemaleText_loc1`='성난태양 첨탑으로 가면 우리 도시의 사제들을 만날 수 있으니 벨레스트라를 찾아보십시오.', `FemaleText_loc4`='我们这座美丽城市中的牧师在日怒之塔内。去那里找贝蕾丝特拉女士吧。', `FemaleText_loc5`='你可以在日怒尖塔找到這個美麗城市的牧師。去找拜拉斯卓女士吧。', `FemaleText_loc7`='Los sacerdotes de nuestra bella ciudad se pueden encontrar en la Aguja Furia del Sol. Busca a la dama Belestra.' WHERE `ID`=15247;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보통 우리보다 훨씬 날렵한 이들은 찾기 어렵지. 하지만, 죽음의 골목으로 깊숙이 들어가면 젤라니스와 그의 동료를 만날 수 있을 것이오.', `MaleText_loc4`='有时候很难找到那些敏捷的家伙，不过你很可能在谋杀小径的深处偶遇潜行者瑟兰尼斯和他的伙计们。', `MaleText_loc5`='我們動作越敏捷就會越難被發現，你應該會在奧格的地盤深處遇到盜賊賽藍尼斯和他的同伴。', `MaleText_loc7`='Los más ágiles de entre nosotros pueden ser difíciles de ver a veces, pero, no obstante, probablemente te encontrarás con el pícaro Zelanis y con su cohorte en las profundidades del Frontal de la Muerte.', `FemaleText_loc1`='보통 우리보다 훨씬 날렵한 이들은 찾기 어렵죠. 하지만, 죽음의 골목으로 깊숙이 들어가면 젤라니스와 그의 동료를 만날 수 있을 겁니다.', `FemaleText_loc4`='有时候很难找到那些敏捷的家伙，不过你很可能在谋杀小径的深处偶遇潜行者瑟兰尼斯和他的伙计们。', `FemaleText_loc5`='我們動作越敏捷就會越難被發現，你應該會在奧格的地盤深處遇到盜賊賽藍尼斯和他的同伴。', `FemaleText_loc7`='Los más ágiles de entre nosotros pueden ser difíciles de ver a veces, pero, no obstante, probablemente te encontrarás con el pícaro Zelanis y con su cohorte en las profundidades del Frontal de la Muerte.' WHERE `ID`=15248;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악마를 소환하는 일은 위험하지만 그로써 얻는 힘은 무궁무진하지. 이 도시에는 알람마라고 하는 흑마술의 전문가가 있는데 죽음의 골목에서 다른 흑마법사들을 돌보고 있소이다.', `MaleText_loc4`='召唤恶魔是一种很危险的行为，但是那又可以让你掌握巨大的力量。奥拉玛是我们的常驻专家，在谋杀小径指导着术士们。', `MaleText_loc5`='召喚惡魔是件危險的事，但它產生的力量會非常龐大。我們的常駐專家是阿拉瑪，他負責看管奧格的地盤裡的術士。', `MaleText_loc7`='La invocación de demonios es una práctica peligrosa, pero puede proporcionar un poder enorme. Nuestro experto particular es Alamma; se ocupa de los brujos desde el Frontal de la Muerte.', `FemaleText_loc1`='악마를 소환하는 일은 위험하지만 그로써 얻는 힘은 무궁무진합니다. 이 도시에는 알람마라고 하는 흑마술의 전문가가 있는데 죽음의 골목에서 다른 흑마법사들을 돌보고 있답니다.', `FemaleText_loc4`='召唤恶魔是一种很危险的行为，但是那又可以让你掌握巨大的力量。奥拉玛是我们的常驻专家，在谋杀小径指导着术士们。', `FemaleText_loc5`='召喚惡魔是件危險的事，但它產生的力量會非常龐大。我們的常駐專家是阿拉瑪，他負責看管奧格的地盤裡的術士。', `FemaleText_loc7`='La invocación de demonios es una práctica peligrosa, pero puede proporcionar un poder enorme. Nuestro experto particular es Alamma; se ocupa de los brujos desde el Frontal de la Muerte.' WHERE `ID`=15249;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기술 전문가', `MaleText_loc4`='专业训练师', `MaleText_loc5`='專業技能訓練師', `MaleText_loc7`='Instructor de profesión', `FemaleText_loc1`='기술 전문가', `FemaleText_loc4`='专业训练师', `FemaleText_loc5`='專業技能訓練師', `FemaleText_loc7`='Instructor de profesión' WHERE `ID`=15250;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 기술을 배우고 싶으시오?', `MaleText_loc4`='你要学习何种专业技能？', `MaleText_loc5`='你想學什麼專業技能?', `MaleText_loc7`='¿Qué profesión quieres aprender?', `FemaleText_loc1`='어떤 기술을 배우고 싶으세요?', `FemaleText_loc4`='你要学习何种专业技能？', `FemaleText_loc5`='你想學什麼專業技能?', `FemaleText_loc7`='¿Qué profesión quieres aprender?' WHERE `ID`=15251;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연금술', `MaleText_loc4`='炼金术', `MaleText_loc5`='鍊金術', `MaleText_loc7`='Alquimia', `FemaleText_loc1`='연금술', `FemaleText_loc4`='炼金术', `FemaleText_loc5`='鍊金術', `FemaleText_loc7`='Alquimia' WHERE `ID`=15252;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연금술사들은 태양 궁정에 있소이다. 캠베론을 찾아가면 그대가 물약 제조술에 대해 알고 싶은 모든 내용을 가르쳐줄 것이오.', `MaleText_loc4`='炼金师们都在逐日王庭，你可以去找卡博隆，他会很热情地教你一大堆关于制造药水的知识。', `MaleText_loc5`='鍊金師在陽光庭院裡;你會找到坎伯朗，他會很樂意教你任何關於釀造藥水的事。', `MaleText_loc7`='Los alquimistas están situados en la Corte del Sol; encontrarás a Camberon ansioso por enseñarte cualquier cosa que quieras saber sobre el arte de elaborar pociones.', `FemaleText_loc1`='연금술사들은 태양 궁정에 있습니다. 캠베론을 찾아가면 그대가 물약 제조술에 대해 알고 싶은 모든 내용을 가르쳐줄 것입니다.', `FemaleText_loc4`='炼金师们都在逐日王庭，你可以去找卡博隆，他会很热情地教你一大堆关于制造药水的知识。', `FemaleText_loc5`='鍊金師在陽光庭院裡;你會找到坎伯朗，他會很樂意教你任何關於釀造藥水的事。', `FemaleText_loc7`='Los alquimistas están situados en la Corte del Sol; encontrarás a Camberon ansioso por enseñarte cualquier cosa que quieras saber sobre el arte de elaborar pociones.' WHERE `ID`=15254;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대장기술', `MaleText_loc4`='锻造', `MaleText_loc5`='鍛造', `MaleText_loc7`='Herrería', `FemaleText_loc1`='대장기술', `FemaleText_loc4`='锻造', `FemaleText_loc5`='鍛造', `FemaleText_loc7`='Herrería' WHERE `ID`=15255;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원정순찰대 광장에서 베마린이 대장기술을 가르치고 있소이다. 좀 힘들고 고된... 일이긴 하지만 나름의 매력이 있겠지.', `MaleText_loc4`='波玛尔在远行者广场传授铁匠的技术。虽然这是个……脏活，但我想它还是有一些优点的。', `MaleText_loc5`='貝瑪倫在遠行者廣場教授鍛造的手藝。雖然它是個有點...髒的差事，但我想它還是有它的價值。', `MaleText_loc7`='Bemarrin instruye en el oficio de la herrería en la Plaza del Errante. Aunque es un oficio algo... sucio, supongo que tiene sus ventajas.', `FemaleText_loc1`='원정순찰대 광장에서 베마린이 대장기술을 가르치고 있습니다. 좀 힘들고 고된... 일이긴 하지만 나름의 매력이 있겠죠.', `FemaleText_loc4`='波玛尔在远行者广场传授铁匠的技术。虽然这是个……脏活，但我想它还是有一些优点的。', `FemaleText_loc5`='貝瑪倫在遠行者廣場教授鍛造的手藝。雖然它是個有點...髒的差事，但我想它還是有它的價值。', `FemaleText_loc7`='Bemarrin instruye en el oficio de la herrería en la Plaza del Errante. Aunque es un oficio algo... sucio, supongo que tiene sus ventajas.' WHERE `ID`=15256;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법부여', `MaleText_loc4`='附魔', `MaleText_loc5`='附魔', `MaleText_loc7`='Encantamiento', `FemaleText_loc1`='마법부여', `FemaleText_loc4`='附魔', `FemaleText_loc5`='附魔', `FemaleText_loc7`='Encantamiento' WHERE `ID`=15257;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='현재 마법부여사 세다나가 수습생을 받고 있다 하니 태양 궁정에 있는 한 방안에서 그녀를 찾아보시오.', `MaleText_loc4`='我相信附魔师瑟丹娜正在招收学生。你可以在逐日王庭的某个亭子里面找到她。', `MaleText_loc5`='我想附魔師希丹娜目前正在招生。你可以在陽光庭院裡的一個凹室裡找到她。', `MaleText_loc7`='Creo que Sedana la encantadora está reclutando aprendices en estos momentos. La encontrarás en las habitaciones de la Corte del Sol.', `FemaleText_loc1`='현재 마법부여사 세다나가 수습생을 받고 있다 하니 태양 궁정에 있는 한 방안에서 그녀를 찾아보십시오.', `FemaleText_loc4`='我相信附魔师瑟丹娜正在招收学生。你可以在逐日王庭的某个亭子里面找到她。', `FemaleText_loc5`='我想附魔師希丹娜目前正在招生。你可以在陽光庭院裡的一個凹室裡找到她。', `FemaleText_loc7`='Creo que Sedana la encantadora está reclutando aprendices en estos momentos. La encontrarás en las habitaciones de la Corte del Sol.' WHERE `ID`=15258;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기계공학', `MaleText_loc4`='工程学', `MaleText_loc5`='工程學', `MaleText_loc7`='Ingeniería', `FemaleText_loc1`='기계공학', `FemaleText_loc4`='工程学', `FemaleText_loc5`='工程學', `FemaleText_loc7`='Ingeniería' WHERE `ID`=15259;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='특이한 선택이군... 하지만, 내가 판단한 일은 아니겠지. 단웨가 바로 그대가 찾는 인물일 것이오. 그녀의 연구실은 태양 궁정 근처에 있는데 원정순찰대 광장으로 가는 길목에 있소이다.', `MaleText_loc4`='一个奇怪的选择……但是我想这并不是我该评判的。你应该去找丹文，她的工程台就在逐日王庭附近，通往远行者广场的那条路上。', `MaleText_loc5`='奇怪的選擇...但我想我不是該批判的那個人。丹威是你該去找的人;她的工程學小攤在去遠行者廣場的路上，陽光庭院附近。', `MaleText_loc7`='Una elección extraña... pero no soy quién para juzgar, supongo. Danwe es a quien buscas; su puesto de ingeniería está cerca de la Corte del Sol, de camino a la Plaza del Errante.', `FemaleText_loc1`='특이한 선택이군요... 하지만, 제가 판단한 일은 아니겠지요. 단웨가 바로 그대가 찾는 인물일 것입니다. 그녀의 연구실은 태양 궁정 근처에 있는데 원정순찰대 광장으로 가는 길목에 있습니다.', `FemaleText_loc4`='一个奇怪的选择……但是我想这并不是我该评判的。你应该去找丹文，她的工程台就在逐日王庭附近，通往远行者广场的那条路上。', `FemaleText_loc5`='奇怪的選擇...但我想我不是該批判的那個人。丹威是你該去找的人;她的工程學小攤在去遠行者廣場的路上，陽光庭院附近。', `FemaleText_loc7`='Una elección extraña... pero no soy quién para juzgar, supongo. Danwe es a quien buscas; su puesto de ingeniería está cerca de la Corte del Sol, de camino a la Plaza del Errante.' WHERE `ID`=15260;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='응급치료', `MaleText_loc4`='急救', `MaleText_loc5`='急救', `MaleText_loc7`='Primeros auxilios', `FemaleText_loc1`='응급치료', `FemaleText_loc4`='急救', `FemaleText_loc5`='急救', `FemaleText_loc7`='Primeros auxilios' WHERE `ID`=15261;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알레스투스는 상처를 치료하는... 복잡한 기술의 대가지. 응급치료를 배우는 것을 목표로 하고 있다면 장로의 거리에서 그를 찾아보시오. 왕궁 교역소의 입구 근처라오.', `MaleText_loc4`='埃雷图斯是个……处理各种伤口的大师。如果学习急救是你的目标，就去长者步道找他吧，他就在皇家贸易区的入口附近。', `MaleText_loc5`='艾瑞斯塔是個擅長用...較混亂的方式治療傷口的專家。如果學習急救是你的目的，就去皇家交易所入口附近的長者步道找他吧。', `MaleText_loc7`='Alestus es maestro en... vendar heridas de cualquier manera. Si lo que quieres es aprender primeros auxilios, búscalo en el Camino de los Ancestros, cerca de la entrada al Intercambio Real.', `FemaleText_loc1`='알레스투스는 상처를 치료하는... 복잡한 기술의 대가입니다. 응급치료를 배우는 것을 목표로 하고 있다면 장로의 거리에서 그를 찾아보십시오. 왕궁 교역소의 입구 근처입니다.', `FemaleText_loc4`='埃雷图斯是个……处理各种伤口的大师。如果学习急救是你的目标，就去长者步道找他吧，他就在皇家贸易区的入口附近。', `FemaleText_loc5`='艾瑞斯塔是個擅長用...較混亂的方式治療傷口的專家。如果學習急救是你的目的，就去皇家交易所入口附近的長者步道找他吧。', `FemaleText_loc7`='Alestus es maestro en... vendar heridas de cualquier manera. Si lo que quieres es aprender primeros auxilios, búscalo en el Camino de los Ancestros, cerca de la entrada al Intercambio Real.' WHERE `ID`=15262;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='낚시', `MaleText_loc4`='钓鱼', `MaleText_loc5`='釣魚', `MaleText_loc7`='Pesca', `FemaleText_loc1`='낚시', `FemaleText_loc4`='钓鱼', `FemaleText_loc5`='釣魚', `FemaleText_loc7`='Pesca' WHERE `ID`=15263;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물고기가 많이 낚이기로 유명한 쿠엘탈라스의 물이 그대의 눈길을 사로잡은 모양이군? 낚시 경험이 풍부한 드라덴을 장로의 거리에서 찾을 수 있소이다. 왕궁 교역소 근처로 가시오.', `MaleText_loc4`='奎尔萨拉斯的水里有着大量的鱼，你从来都没发现过吗？德拉森对钓鱼很有经验，你可以在长者步道靠近皇家贸易区的地方找到他。', `MaleText_loc5`='奎爾薩拉斯的水裡充滿了魚群;我想你也注意到了吧?崔森在釣魚手藝上相當有技巧，你可以在皇家交易所拍賣場旁的長者步道找到他。', `MaleText_loc7`='Las aguas de Quel''Thalas rebosan de peces; te han llamado la atención, ¿verdad? Drathen tiene bastante experiencia en los trucos del oficio de la pesca, y se le puede encontrar en el Camino de los Ancestros, cerca del Intercambio Real.', `FemaleText_loc1`='물고기가 많이 낚이기로 유명한 쿠엘탈라스의 물이 그대의 눈길을 사로잡은 모양이군요? 낚시 경험이 풍부한 드라덴을 장로의 거리에서 찾을 수 있습니다. 왕궁 교역소 근처로 가십시오.', `FemaleText_loc4`='奎尔萨拉斯的水里有着大量的鱼，你从来都没发现过吗？德拉森对钓鱼很有经验，你可以在长者步道靠近皇家贸易区的地方找到他。', `FemaleText_loc5`='奎爾薩拉斯的水裡充滿了魚群;我想你也注意到了吧?崔森在釣魚手藝上相當有技巧，你可以在皇家交易所拍賣場旁的長者步道找到他。', `FemaleText_loc7`='Las aguas de Quel''Thalas rebosan de peces; te han llamado la atención, ¿verdad? Drathen tiene bastante experiencia en los trucos del oficio de la pesca, y se le puede encontrar en el Camino de los Ancestros, cerca del Intercambio Real.' WHERE `ID`=15264;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='약초채집', `MaleText_loc4`='草药学', `MaleText_loc5`='草藥學', `MaleText_loc7`='Herboristería', `FemaleText_loc1`='약초채집', `FemaleText_loc4`='草药学', `FemaleText_loc5`='草藥學', `FemaleText_loc7`='Herboristería' WHERE `ID`=15265;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='식물학자 나세라는 약초를 찾아내는 날카로운 눈의 소유자이지. 그대 같은 자라면 그녀가 지혜를 나눠줄 수도 있을 것 같군. 태양 궁정의 한 방에서 연금술사와 함께 있는 그녀를 찾아가시오.', `MaleText_loc4`='植物学家娜萨兰有着一副寻找药草的敏锐眼睛，我想她可能会把她的智慧传授给像你这样的家伙吧。你可以在逐日王庭那里的亭子中找到她和炼金师们。', `MaleText_loc5`='植物學家納德娜有雙銳利的雙眼可以尋找草藥，我想她應該會將她的智慧與你這種人分享。你可以在陽光庭院的凹室裡找到她和鍊金師們在一起。', `MaleText_loc7`='La botánica Nathera tiene una gran habilidad para encontrar hierbas y me imagino que puede transmitir sus conocimientos a alguien como tú. La encontrarás en una de las habitaciones de la Corte del Sol.', `FemaleText_loc1`='식물학자 나세라는 약초를 찾아내는 날카로운 눈의 소유자지요. 그대 같은 분이라면 그녀가 지혜를 나눠줄 수도 있을 것 같네요. 태양 궁정의 한 방에서 연금술사와 함께 있는 그녀를 찾아가십시오.', `FemaleText_loc4`='植物学家娜萨兰有着一副寻找药草的敏锐眼睛，我想她可能会把她的智慧传授给像你这样的家伙吧。你可以在逐日王庭那里的亭子中找到她和炼金师们。', `FemaleText_loc5`='植物學家納德娜有雙銳利的雙眼可以尋找草藥，我想她應該會將她的智慧與你這種人分享。你可以在陽光庭院的凹室裡找到她和鍊金師們在一起。', `FemaleText_loc7`='La botánica Nathera tiene una gran habilidad para encontrar hierbas y me imagino que puede transmitir sus conocimientos a alguien como tú. La encontrarás en una de las habitaciones de la Corte del Sol.' WHERE `ID`=15266;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보석세공', `MaleText_loc4`='珠宝加工', `MaleText_loc5`='珠寶設計', `MaleText_loc7`='Joyería', `FemaleText_loc1`='보석세공', `FemaleText_loc4`='珠宝加工', `FemaleText_loc5`='珠寶設計', `FemaleText_loc7`='Joyería' WHERE `ID`=15267;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보석세공을 배우고 싶다면 왕궁 교역소의 남쪽 끝에 있는 칼린다의 상점으로 가시오.', `MaleText_loc4`='如果你要找珠宝匠，就去皇家贸易区的南部寻找卡琳达的商店。', `MaleText_loc5`='如果你在尋找珠寶設計師，你可以在皇家交易所拍賣場的南方盡頭找到卡琳達的小店。', `MaleText_loc7`='Si lo que buscas es una joyería, encontrarás la tienda de Kalinda al extremo sur del Intercambio Real.', `FemaleText_loc1`='보석세공을 배우고 싶다면 왕궁 교역소의 남쪽 끝에 있는 칼린다의 상점으로 가십시오.', `FemaleText_loc4`='如果你要找珠宝匠，就去皇家贸易区的南部寻找卡琳达的商店。', `FemaleText_loc5`='如果你在尋找珠寶設計師，你可以在皇家交易所拍賣場的南方盡頭找到卡琳達的小店。', `FemaleText_loc7`='Si lo que buscas es una joyería, encontrarás la tienda de Kalinda al extremo sur del Intercambio Real.' WHERE `ID`=15268;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가죽세공', `MaleText_loc4`='制皮', `MaleText_loc5`='製皮', `MaleText_loc7`='Peletería', `FemaleText_loc1`='가죽세공', `FemaleText_loc4`='制皮', `FemaleText_loc5`='製皮', `FemaleText_loc7`='Peletería' WHERE `ID`=15269;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장로의 거리 남동쪽 끝으로 가면 리날리스가 차려놓은 멋진 가죽세공 작업대가 보일 것이오. 약간의 훈련비만 내면 그녀가 그대를 훈련시켜 줄 것이오...', `MaleText_loc4`='沿着长者步道走到东南方的尽头，莱纳里斯在那里开了一家制皮点。她会教你的，只要你肯付钱。', `MaleText_loc5`='在長者步道東南方盡頭，萊娜利斯設了一個很棒的製皮攤。她會訓練你...只要一點點代價。', `MaleText_loc7`='En el extremo suroriental del Camino de los Ancestros, Lynalis tiene un buen puesto de peletería. Si pagas, te adiestrará.', `FemaleText_loc1`='장로의 거리 남동쪽 끝으로 가면 리날리스가 차려놓은 멋진 가죽세공 작업대가 보일 것입니다. 약간의 훈련비만 내면 그녀가 그대를 훈련시켜 줄 겁니다...', `FemaleText_loc4`='沿着长者步道走到东南方的尽头，莱纳里斯在那里开了一家制皮点。她会教你的，只要你肯付钱。', `FemaleText_loc5`='在長者步道東南方盡頭，萊娜利斯設了一個很棒的製皮攤。她會訓練你...只要一點點代價。', `FemaleText_loc7`='En el extremo suroriental del Camino de los Ancestros, Lynalis tiene un buen puesto de peletería. Si pagas, te adiestrará.' WHERE `ID`=15270;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='채광', `MaleText_loc4`='采矿', `MaleText_loc5`='採礦', `MaleText_loc7`='Minería', `FemaleText_loc1`='채광', `FemaleText_loc4`='采矿', `FemaleText_loc5`='採礦', `FemaleText_loc7`='Minería' WHERE `ID`=15271;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='먼지를 뒤집어쓰고 땅을 파는 정신 나간 일이 즐겁다면 원정순찰대 광장에 있는 벨릴에게 가 보시오. 그대를 보면 벨릴도 자기만 정신이 이상한 게 아니라는 사실에 기뻐할 것이오.', `MaleText_loc4`='如果在泥土里面挖掘对你来说是一种有趣的娱乐，就去远行者广场找比利尔分享你的疯狂吧。我相信他会很高兴看到他不是唯一的疯子。', `MaleText_loc5`='如果挖土是一種讓你享受的消遣，那就去遠行者廣場找貝利爾分享你瘋狂的興趣吧。我相信他會很高興看到不只他一個人有病的。', `MaleText_loc7`='Si cavar en la suciedad es la clase de pasatiempo que encuentras entretenido, ve a compartir tu locura con Belil en la Plaza del Errante. Seguro que estaría contento al saber que no es la única persona que ha perdido el juicio.', `FemaleText_loc1`='먼지를 뒤집어쓰고 땅을 파는 정신 나간 일이 즐겁다면 원정순찰대 광장에 있는 벨릴에게 가세요. 그대를 보면 벨릴도 자기만 정신이 이상한 게 아니라는 사실에 기뻐할 겁니다.', `FemaleText_loc4`='如果在泥土里面挖掘对你来说是一种有趣的娱乐，就去远行者广场找比利尔分享你的疯狂吧。我相信他会很高兴看到他不是唯一的疯子。', `FemaleText_loc5`='如果挖土是一種讓你享受的消遣，那就去遠行者廣場找貝利爾分享你瘋狂的興趣吧。我相信他會很高興看到不只他一個人有病的。', `FemaleText_loc7`='Si cavar en la suciedad es la clase de pasatiempo que encuentras entretenido, ve a compartir tu locura con Belil en la Plaza del Errante. Seguro que estaría contento al saber que no es la única persona que ha perdido el juicio.' WHERE `ID`=15272;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무두질', `MaleText_loc4`='剥皮', `MaleText_loc5`='剝皮', `MaleText_loc7`='Desuello', `FemaleText_loc1`='무두질', `FemaleText_loc4`='剥皮', `FemaleText_loc5`='剝皮', `FemaleText_loc7`='Desuello' WHERE `ID`=15273;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='틴은 매우 뛰어난 무두장이지. 그녀가 무두질한 스라소니 가죽은 여태까지 제가 본 것 중 최고였소이다. 그녀에게 무두질을 배우고 싶다면 장로의 거리 남동쪽 끝으로 가시오.', `MaleText_loc4`='提恩是个很有天赋的剥皮师，她所生产的山猫皮是我见过的最好的东西。如果你想从她那里学到点本事，可以在长者步道的东南尽头找到她。', `MaleText_loc5`='帝恩是個相當有天份的剝皮師;她製作的山貓毛皮是我見過最好的。如果你想向她學習，你可以在長者步道東南方的盡頭找到她。', `MaleText_loc7`='Tyn es la desolladora de talento; fabrica el mejor cuero de lince que haya visto. Si deseas aprender de ella, la encontrarás en el extremo sureste del Camino de los Ancestros.', `FemaleText_loc1`='틴은 매우 뛰어난 무두장이입니다. 그녀가 무두질한 스라소니 가죽은 여태까지 제가 본 것 중 최고였습니다. 그녀에게 무두질을 배우고 싶다면 장로의 거리 남동쪽 끝으로 가십시오.', `FemaleText_loc4`='提恩是个很有天赋的剥皮师，她所生产的山猫皮是我见过的最好的东西。如果你想从她那里学到点本事，可以在长者步道的东南尽头找到她。', `FemaleText_loc5`='帝恩是個相當有天份的剝皮師;她製作的山貓毛皮是我見過最好的。如果你想向她學習，你可以在長者步道東南方的盡頭找到她。', `FemaleText_loc7`='Tyn es la desolladora de talento; fabrica el mejor cuero de lince que haya visto. Si deseas aprender de ella, la encontrarás en el extremo sureste del Camino de los Ancestros.' WHERE `ID`=15274;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='재봉술', `MaleText_loc4`='裁缝', `MaleText_loc5`='裁縫', `MaleText_loc7`='Sastrería', `FemaleText_loc1`='재봉술', `FemaleText_loc4`='裁缝', `FemaleText_loc5`='裁縫', `FemaleText_loc7`='Sastrería' WHERE `ID`=15275;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 도시의 재봉사들은 항상 섬세한 기술을 가르칠 만한 호기심 왕성한 제자들을 찾고 있소. 재봉용품 상점을 찾기가 처음에는 좀 어려울지도 모르겠군. 시장의 경매장에서 바로 북쪽에 있는 건물 아래층에 가 보시오.', `MaleText_loc4`='裁缝基伦一直在寻找好奇的学生来传授他那精巧的手艺。他的店有点不好找，就在花园街市的拍卖行的北面。你可以在那座建筑的底层找到他。', `MaleText_loc5`='裁縫奇蘭一直都在尋找更有好奇心的學生來傳授他微妙的手藝。他的店第一次會有點難找，但它就在商店街拍賣場的北邊。你會在建築物的較低層找到他。', `MaleText_loc7`='El sastre Keelen siempre está dispuesto a recibir nuevos estudiantes para transmitir su delicado saber. Su tienda es un poco difícil de encontrar al principio: se encuentra justo al norte de la casa de subastas del Bazar. Él está en el piso más bajo del edificio.', `FemaleText_loc1`='이 도시의 재봉사들은 항상 섬세한 기술을 가르칠 만한 호기심 왕성한 제자들을 찾고 있습니다. 재봉용품 상점을 찾기가 처음에는 좀 어려울지도 모르겠군요. 시장의 경매장에서 바로 북쪽에 있는 건물 아래층에 가 보십시오.', `FemaleText_loc4`='裁缝基伦一直在寻找好奇的学生来传授他那精巧的手艺。他的店有点不好找，就在花园街市的拍卖行的北面。你可以在那座建筑的底层找到他。', `FemaleText_loc5`='裁縫奇蘭一直都在尋找更有好奇心的學生來傳授他微妙的手藝。他的店第一次會有點難找，但它就在商店街拍賣場的北邊。你會在建築物的較低層找到他。', `FemaleText_loc7`='El sastre Keelen siempre está dispuesto a recibir nuevos estudiantes para transmitir su delicado saber. Su tienda es un poco difícil de encontrar al principio: se encuentra justo al norte de la casa de subastas del Bazar. Él está en el piso más bajo del edificio.' WHERE `ID`=15276;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시험 중. 이게 제대로 작동하는 겁니까????', `MaleText_loc4`='测试。这东西正常工作吗？', `MaleText_loc5`='TESTING. IS THIS THING WORKING????', `MaleText_loc7`='PROBANDO. ¿¿¿¿FUNCIONA ESTA COSA????', `FemaleText_loc1`='시험 중. 이게 제대로 작동하는 겁니까????', `FemaleText_loc4`='测试。这东西正常工作吗？', `FemaleText_loc5`='TESTING. IS THIS THING WORKING????', `FemaleText_loc7`='PROBANDO. ¿¿¿¿FUNCIONA ESTA COSA????' WHERE `ID`=15277;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나그란드에서는 사냥감이 오우거 사냥한다!', `MaleText_loc4`='在纳格兰，食物竟敢追杀食人魔！', `MaleText_loc5`='在納葛蘭獵食巨魔!', `MaleText_loc7`='¡En Nagrand, la comida cazar a ogro!' WHERE `ID`=15278;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소금과 후추로 간을 하면 더 좋은 맛이 나겠군.', `MaleText_loc4`='再加点盐和胡椒你就更美味了。', `MaleText_loc5`='加一點鹽和胡椒你應該吃起來會很美味。', `MaleText_loc7`='Tendrás buen sabor, quizás con un poco de sal y pimienta.' WHERE `ID`=15279;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 이목을 끄는 문서를 떨어뜨립니다.', `MaleText_loc4`='%s掉落了一份重要的文件。', `MaleText_loc5`='%s掉了一份顯眼的文件。', `MaleText_loc7`='%s deja caer un documento llamativo.' WHERE `ID`=15280;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='룸프한테 말 건 이유 뭐야? 룸프 배고프다. 그게 전부다.', `MaleText_loc4`='为什么你对拉普这么粗暴？拉普只是饿了。', `MaleText_loc5`='你為什麼要對浪普這麼壞?浪普只是肚子餓而已。', `MaleText_loc7`='¿Por qué ser cruel con Zoquete? Zoquete hambriento, eso es todo.' WHERE `ID`=15281;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알았다, 알았어! 룸프 항복이다!', `MaleText_loc4`='好吧，好吧！拉普投降！', `MaleText_loc5`='好好好!浪普放棄!', `MaleText_loc7`='¡De acuerdo, de acuerdo! ¡Zoquete rendirse!' WHERE `ID`=15282;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 질문에 대답해, 이 오우거야!', `MaleText_loc4`='我需要答案，食人魔！', `MaleText_loc5`='我要答案，巨魔!', `MaleText_loc7`='¡Necesito respuestas, ogro!', `FemaleText_loc1`='내 질문에 대답해, 이 오우거야!', `FemaleText_loc4`='我需要答案，食人魔！', `FemaleText_loc5`='我要答案，巨魔!', `FemaleText_loc7`='¡Necesito respuestas, ogro!' WHERE `ID`=15283;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알았다! 룸프 네가 원하는 거 모두 분다!', `MaleText_loc4`='好好好！拉普什么都说！', `MaleText_loc5`='好吧!浪普告訴你所有你想知道的事!', `MaleText_loc7`='¡De acuerdo! Zoquete decirte todo lo que quieras!' WHERE `ID`=15284;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌주먹 일족이 이렇게 멀리까지 온 이유가 뭐지? 알다시피 여기는 쿠레나이의 영역이지 않나?', `MaleText_loc4`='为什么石拳氏族出现在这么远的地方？你要知道这是库雷尼的领地。', `MaleText_loc5`='為什麼石拳跑到那麼遠的地方去?你知道這是卡爾奈的領土。', `MaleText_loc7`='¿Por qué llegan los Puño de Roca hasta aquí? Sabes que este es territorio Kurenai.', `FemaleText_loc1`='돌주먹 일족이 이렇게 멀리까지 온 이유가 뭐지? 알다시피 여기는 쿠레나이의 영역이지 않나?', `FemaleText_loc4`='为什么石拳氏族出现在这么远的地方？你要知道这是库雷尼的领地。', `FemaleText_loc5`='為什麼石拳跑到那麼遠的地方去?你知道這是卡爾奈的領土。', `FemaleText_loc7`='¿Por qué llegan los Puño de Roca hasta aquí? Sabes que este es territorio Kurenai.' WHERE `ID`=15285;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌주먹 일족 배고프다! 먹을 것 필요하다! 전쟁망치 일족이 돌주먹 일족 산에서 북쪽으로 내쫓았다. 지금 많은 돌주먹 일족 굶주린다.', `MaleText_loc4`='石拳氏族好饿！要吃东西！战槌氏族把石拳氏族赶到了北面。石拳需要更多食物。', `MaleText_loc5`='石拳餓了!需要食物!戰槌巨魔部族把石拳踢出土堆到北邊去了。現在有更多的石拳要餵養。', `MaleText_loc7`='¡Puño de Roca hambriento! ¡Necesitar comida! Tribu de ogros Mazo de Guerra echar Puño de Roca del montículo al norte. Muchos más Puños de Roca que alimentar ahora.' WHERE `ID`=15286;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래서 원하는 건 뭐든지 먹을 수 있다고 생각했어? 네가 먹으려고 하는 건 텔라아르의 뒤틀린 드레나이들이라고.', `MaleText_loc4`='你以为你可以想吃什么就吃什么吗？你肯定是想去吃塔拉的破碎者。', `MaleText_loc5`='你以為你可以吃任何想吃的東西嗎?很明顯地你想吃泰拉的破碎者。', `MaleText_loc7`='¿Y crees que puedes comer todo lo que quieras? Obviamente intentas comerte a los Tábidos de Telaar.', `FemaleText_loc1`='그래서 원하는 건 뭐든지 먹을 수 있다고 생각했어? 네가 먹으려고 하는 건 텔라아르의 뒤틀린 드레나이들이라고.', `FemaleText_loc4`='你以为你可以想吃什么就吃什么吗？你肯定是想去吃塔拉的破碎者。', `FemaleText_loc5`='你以為你可以吃任何想吃的東西嗎?很明顯地你想吃泰拉的破碎者。', `FemaleText_loc7`='¿Y crees que puedes comer todo lo que quieras? Obviamente intentas comerte a los Tábidos de Telaar.' WHERE `ID`=15287;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇지 않다. 조금만 뜯어먹으려고 했다. 전부 먹지 않는다. 맞다, 그 작은 거라면 모두 먹었을지도 모른다.$B$B그들 정말 맛있다!', `MaleText_loc4`='不是。我只不过想慢慢咀嚼而已。我并不是所有的东西都吃的。呃，也许我会吃那些小东西。$B$B他们味道真好！', `MaleText_loc5`='不是那樣。我只是喜歡一點一點地吃。我不會吃全部。好吧，或許我吃那個小的。$B$B他們很美味!', `MaleText_loc7`='No cierto. Mí solo querer mordisquear. Yo no comer todo. Bueno, quizás comer los pequeños.$B$B¡Son deliciosos!' WHERE `ID`=15288;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들에게 피해를 주는 건 전쟁을 의미해, 룸프! 전쟁 말이야!', `MaleText_loc4`='这意味着战争，拉普！我说的是战争！', `MaleText_loc5`='這代表戰爭，浪普!我說戰爭!', `MaleText_loc7`='¡Esto significa la guerra, Zoquete! ¡La guerra, te digo!', `FemaleText_loc1`='그들에게 피해를 주는 건 전쟁을 의미해, 룸프! 전쟁 말이야!', `FemaleText_loc4`='这意味着战争，拉普！我说的是战争！', `FemaleText_loc5`='這代表戰爭，浪普!我說戰爭!', `FemaleText_loc7`='¡Esto significa la guerra, Zoquete! ¡La guerra, te digo!' WHERE `ID`=15289;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<어깨를 으쓱하는 룸프>$B$B너 그거 전쟁 돌주먹 일족에게 가져와라. 우리 그거 찌개에 넣는다.', `MaleText_loc4`='<拉普耸了耸肩。>$B$B你把战争给石拳氏族带来，我们炖它吃。', `MaleText_loc5`='<浪普聳了聳肩。>$B$B你為石拳帶來戰爭。我們將它放進鍋裡煮。', `MaleText_loc7`='<Zoquete se encoge de hombros.>$B$BUstedes llevan guerra a los Puño de Roca. Nosotros los ponemos en guiso.' WHERE `ID`=15290;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 꺼내 주세요!', `MaleText_loc4`='把我弄出这里，$r！', `MaleText_loc5`='讓我離開這裡，$r!', `MaleText_loc7`='¡Sácame de aquí, $r!' WHERE `ID`=15291;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 얼간이, 먹을 것 좀 줄까!?', `MaleText_loc4`='嘿，胖子，给我弄点吃的怎么样！？', `MaleText_loc5`='嘿傻瓜，要不要來點食物!?', `MaleText_loc7`='¿¡Eh, cabezón, qué tal algo de comida!?' WHERE `ID`=15292;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 뚱보, 그렇게 뚱뚱한 몸으로 화장실은 어떻게 가지!?', `MaleText_loc4`='嘿，胖子，你这么胖怎么去厕所的！？', `MaleText_loc5`='嘿胖子，你那麼胖怎麼走的進那間浴室啊!?', `MaleText_loc7`='Eh, gordinflas, ¿¡cómo vas al baño con toda esa grasa!?' WHERE `ID`=15293;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='차라리 날 잡아먹으란 말이야! 너희처럼 지독한 냄새를 풍기는 놈들 옆에서 우리에 갇혀 있기는 정말 싫단 말이다, 이 뚱보 녀석들!', `MaleText_loc4`='吃掉我吧！我无法忍受被锁在你们这些臭胖子旁边！', `MaleText_loc5`='快把我吃了吧!我不能再忍受被關在這個籠子裡，和你們這些臭氣沖天的胖粗人在一起了。', `MaleText_loc7`='¡Cómanme de una vez! No soporto estar aquí enjaulado con ustedes merodeando a mi alrededor, gusanos apestosos.' WHERE `ID`=15294;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아빠가 보고 싶어, 흑!', `MaleText_loc4`='我想我的爸爸！', `MaleText_loc5`='我要爸爸!', `MaleText_loc7`='¡Quiero a mi papi!' WHERE `ID`=15295;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 여기서 나가기만 하면 너희는 다 죽었어!', `MaleText_loc4`='要是我能从这里出来的话，你们这些白痴会有麻烦的！', `MaleText_loc5`='等我離開這裡你這傻瓜就慘了!', `MaleText_loc7`='¡Ustedes, cabezones, estarán en peligro si alguna vez salgo de aquí!' WHERE `ID`=15296;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙습니다! 아빠가 당신에게 크게 보상할 거예요! 그럼 안녕히!', `MaleText_loc4`='谢谢，$R！我的父亲一定会好好奖励你的！再见！', `MaleText_loc5`='謝謝，$r!我相信我爸爸會好好獎勵你的!再見!', `MaleText_loc7`='¡Gracias, $r! ¡Estoy seguro de que mi padre te recompensará con generosidad! ¡Adiós!' WHERE `ID`=15297;
