UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 녀석 더는 먹고 싶지 않다.', `MaleText_loc4`='我甚至都不想吃他。', `MaleText_loc5`='我甚至根本不想吃他了。', `MaleText_loc7`='Mi ya no querer comerlo.' WHERE `ID`=15299;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 식욕 잃었다. 코르키 바보다.', `MaleText_loc4`='我没有食欲，考尔奇是傻瓜。', `MaleText_loc5`='我沒有食慾。柯爾奇是小人。', `MaleText_loc7`='Mi perder apetito. Corki es caca.' WHERE `ID`=15300;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 이제 못 참아!', `MaleText_loc4`='我不能接受！不能！', `MaleText_loc5`='我再也不想忍受了!', `MaleText_loc7`='¡Mi no poder soportar más!' WHERE `ID`=15301;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='새로운 식물 종에 대해 배우는 것은 우리 원정대에게 매우 중요한 일입니다. 의학용이나 식용이 아니라 해도 마찬가지이지요.$B$B식물은 다른 형태의 생명이 살아가는 데 필요한 초석이 됩니다. 식물을 이해하면 자연을 전체적으로 이해할 수가 있지요.', `FemaleText_loc4`='了解这些新植物的分类对我们远征队来说非常重要。这不只是为了医用或者食用。$B$B植物是很多其它生命存活的基础，了解它们可以让我们更好地了解整个大自然。', `FemaleText_loc5`='學習新植物種類對我們的遠征隊來說是極為重要的。不只是為了醫療或食用方面的考量。$B$B植物提供了許多其他生命形態存在的基本要素。了解它們讓我們更能了解整個大自然。', `FemaleText_loc7`='Aprender todo lo que se pueda sobre nuevas especies de plantas es muy importante para nuestra expedición. No solo de las comestibles o las medicinales.$B$BLas plantas son la base de otras muchas formas de vida. Comprenderlas mejor significa comprender mejor todo el sistema natural.' WHERE `ID`=15302;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='', `MaleText_loc4`='', `MaleText_loc5`='', `MaleText_loc7`='' WHERE `ID`=15303;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='축하해. 여기 오니까 폐허에 있을 때보다 냄새가 더 지독해졌군.', `MaleText_loc4`='祝贺你，这里比废墟那里闻起来更糟。', `MaleText_loc5`='恭喜。這裡的味道聞起來比廢墟還糟。', `MaleText_loc7`='Enhorabuena. Huele peor aquí que en las ruinas.' WHERE `ID`=15304;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐 뚱보, 너희는 왜 변으로 가득한 구덩이에서 살기를 고집하는 거지?', `MaleText_loc4`='嘿，胖子，是什么理由让你可以坚持住在这么一个满墙都是粪便的地方？', `MaleText_loc5`='嘿胖子，你究竟為什麼堅持要住在牆上一個充滿污穢的洞裡呢?', `MaleText_loc7`='Eh, gordinflas, ¿hay alguna razón por la que insistes en vivir en un agujero lleno de excremento en la pared?' WHERE `ID`=15305;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='먹을 것 좀 주면 안 될까??? 이건 말도 안 돼!', `MaleText_loc4`='请给我点食物吧？不要太过分！', `MaleText_loc5`='我可以要一些食物嗎，拜託???這太不道德了!', `MaleText_loc7`='¿¿¿Puedo comer algo, por favor??? ¡Esto es escandaloso!' WHERE `ID`=15306;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 발 냄새나 변을 가득 채운 치즈와 생선 조각. 이보다 더 지독한 냄새가 있을까?', `MaleText_loc4`='我不知道是什么闻起来更糟糕一些，是你的脚呢，还是一堆充满奶酪和鱼肉的粪便？', `MaleText_loc5`='我不知道哪一個聞起來比較糟:你的腳還是塞滿污穢的起司和魚片。', `MaleText_loc7`='No se qué huele peor, si tus pies o un filete de pescado y queso relleno de excremento.' WHERE `ID`=15307;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두 번 다시 잡히지 않을 거예요! 약속해요! 그럼 또 안녕히!', `MaleText_loc4`='这是我最后一次被抓住！我保证！再见！', `MaleText_loc5`='這是我最後一次被抓到!我保證!再見!', `MaleText_loc7`='¡Esta es la última vez que me pillan! ¡Lo prometo! ¡Adiós!' WHERE `ID`=15308;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='소중한 시간을 벌었어요. 이제 돌아가야 해요.', `FemaleText_loc4`='我们赢得了宝贵的时间。现在必须撤退。', `FemaleText_loc5`='我們已經贏得了寶貴的時間，現在我們必須撤退。', `FemaleText_loc7`='Hemos ganado tiempo valioso, ahora retrocedamos.' WHERE `ID`=15309;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 광역 순간이동 마법을 시전합니다.', `FemaleText_loc4`='%s开始施放一个群体传送法术。', `FemaleText_loc5`='%s開始引導一個強大的傳送法術。', `FemaleText_loc7`='%s comienza a canalizar un hechizo de teletransporte enorme.' WHERE `ID`=15310;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스랄이시여, 가실 시간이 되었습니다!', `MaleText_loc4`='萨尔大人，该出发了！', `MaleText_loc5`='索爾大人，該出發了!', `MaleText_loc7`='¡Lord Thrall, es hora de irse!' WHERE `ID`=15311;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 할 일은 여기까지다. 잘했다 제군들! 이제부터는 다른 용사들에게 맡기겠다.', `MaleText_loc4`='我们完成了自己的使命，现在就看其他人了。', `MaleText_loc5`='我們已經盡了我們的責任，圓滿達成。剩下來就交給其他人了。', `MaleText_loc7`='Hemos cumplido con nuestra parte. Ahora depende de los otros.' WHERE `ID`=15312;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 여군주 제이나 프라우드무어를 향해 고개를 끄덕입니다.', `MaleText_loc4`='%s对着吉安娜·普罗德摩尔点了点头。', `MaleText_loc5`='%s對珍娜·普勞德摩爾女士點點頭。', `MaleText_loc7`='%s saluda con la cabeza a Lady Jaina Valiente.' WHERE `ID`=15313;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 이리도 무엄하게 칼날의 란트레서의 길을 막는 것이냐? 얼굴을 아는 것만으로도 죽을 수 있다는 사실을 모르느냐?', `MaleText_loc4`='是谁这么大胆地站在兰特瑞索·火刃面前？你不知道自己死到临头了吗，$g小子:小姑娘;？', `MaleText_loc5`='是誰這麼大膽站在『劍刃』蘭崔索面前?你想找死嗎，$g男孩:女孩;?', `MaleText_loc7`='¿Quién es tan valiente como para presentarse ante Lantresor del Filo? ¿Acaso no reconoces la muerte cuando la tienes delante?' WHERE `ID`=15314;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 당신의 친구들인 오우거들을 수없이 죽였습니다, 란트레서. 두려움 따윈 모릅니다.', `MaleText_loc4`='我杀了你们这么多食人魔，兰特瑞索。我什么都不怕。', `MaleText_loc5`='我殺了你很多巨魔，蘭崔索。我什麼都不怕。', `MaleText_loc7`='He matado a muchos de tus ogros, Lantresor. No tengo miedo.', `FemaleText_loc1`='나는 당신의 친구들인 오우거들을 수없이 죽였어요, 란트레서. 두려움 따윈 모릅니다.', `FemaleText_loc4`='我杀了你们这么多食人魔，兰特瑞索。我什么都不怕。', `FemaleText_loc5`='我殺了你很多巨魔，蘭崔索。我什麼都不怕。', `FemaleText_loc7`='He matado a muchos de tus ogros, Lantresor. No tengo miedo.' WHERE `ID`=15315;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='참 바보로군. 내가 누군지 모르는가?', `MaleText_loc4`='那么你就是个蠢货。你不知道我是谁吗？', `MaleText_loc5`='那你就是個笨蛋。你不知道我是誰嗎?', `MaleText_loc7`='Entonces eres $gun insensato:una insensata;. ¿Sabes lo que soy?' WHERE `ID`=15316;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 꼭 알아야 합니까? 내 눈에는 당신은 단지 오크일 뿐입니다.', `MaleText_loc4`='我应该知道吗？你看上去就像个兽人。', `MaleText_loc5`='我會知道嗎?我覺得你看起來像獸人。', `MaleText_loc7`='¿Debería saberlo? A mí me pareces un orco.', `FemaleText_loc1`='내가 꼭 알아야 하나요? 내 눈에는 당신은 단지 오크일 뿐입니다.', `FemaleText_loc4`='我应该知道吗？你看上去就像个兽人。', `FemaleText_loc5`='我會知道嗎?我覺得你看起來像獸人。', `FemaleText_loc7`='¿Debería saberlo? A mí me pareces un orco.' WHERE `ID`=15317;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오크라...$B$B<비웃는 란트레서>$B$B나는 반오크 혈통의 검귀다.', `MaleText_loc4`='一个兽人……$B$B<兰特瑞索露出轻蔑的表情。>$B$B我是个拥有一半兽人血统的剑圣。', `MaleText_loc5`='一個獸人...$b$b<蘭崔索嘲笑著。>$B$B我是個半獸人後代的大劍師。', `MaleText_loc7`='Un orco...$B$B<Lantresor se burla.>$B$BSoy un maestro del acero de origen medio orco.' WHERE `ID`=15318;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 나머지 반쪽은 뭡니까?', `MaleText_loc4`='那么另一半是什么？', `MaleText_loc5`='那另一半呢?', `MaleText_loc7`='¿Y la otra mitad?', `FemaleText_loc1`='그럼 나머지 반쪽은 뭐죠?', `FemaleText_loc4`='那么另一半是什么？', `FemaleText_loc5`='那另一半呢?', `FemaleText_loc7`='¿Y la otra mitad?' WHERE `ID`=15319;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드레나이다... 그런 이유로 나는 이도 저도 아니지. 오크도 아니고 드레나이도 아니란 말이다. 나와 같은 종족은 극히 드물다. 수십 년 전 대부분 살해되었지... 나는 강인한 의지 덕분에 지금까지 살아 있는 것이다.', `MaleText_loc4`='德莱尼人……因为这个，我既不是兽人又不是德莱尼人。我的血统是非常稀有的，同族们大部分在十年前都已经被杀了……我凭借我的意志活了下来。', `MaleText_loc5`='德萊尼...因為如此，我兩者都不是。不是獸人，也不是德萊尼。我的種族是罕見的一種。大部份的人都在幾十年前被殺了...我會活下來全靠我的意志力。', `MaleText_loc7`='Draenei... Por esa razón, no soy ninguno de los dos. Ni orco, ni draenei. Formo parte de una raza poco común. La mayoría hemos sido asesinados hace décadas... Sobrevivo gracias a mi fuerza de voluntad.' WHERE `ID`=15320;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇군요. 당신 종족에 대한 얘기는 들었지만 반오크를 직접 만날 줄은 꿈에도 생각 못했습니다.', `MaleText_loc4`='我听说过你的族群，但是我从没想到真的会遇到一个。', `MaleText_loc5`='我聽過你的種族，但沒想過我會遇到一個混血兒。', `MaleText_loc7`='He oído hablar de tu raza, pero nunca pensé que conocería un media sangre.', `FemaleText_loc1`='그렇군요. 당신 종족에 대한 얘기는 들었지만 반오크를 직접 만날 줄은 꿈에도 생각 못했습니다.', `FemaleText_loc4`='我听说过你的族群，但是我从没想到真的会遇到一个。', `FemaleText_loc5`='我聽過你的種族，但沒想過我會遇到一個混血兒。', `FemaleText_loc7`='He oído hablar de tu raza, pero nunca pensé que conocería un media sangre.' WHERE `ID`=15321;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말을 가려서 해라, $r|1이여;여;. 나는 자네가 전설 속에서나 들은 일을 직접 봐 왔고 지금까지 수많은 자의 목숨을 거두었다. 내가 모신 두 명의 호드 대족장의 명령에 따라서... 그리고 지금 나는 돌주먹 일족의 지배자다.', `MaleText_loc4`='闭嘴，$R。我所经历过的一切，你只有在传说中才听说过。我无情地杀死过男人、女人，甚至是孩子。我为两任部落酋长效力过……而现在，我统治着石拳氏族。', `MaleText_loc5`='閉上你的嘴，$r。我這一生看過的事物你都只有在傳說中聽過而已。我殺過男人，女人，和小孩，眼都不眨一下。在兩個部落酋長旗下待過...現在，我統治著石拳。', `MaleText_loc7`='Muérdete la lengua, $r. Yo he visto cosas de las que tú solo has oído hablar en leyendas. He matado a hombres, mujeres y niños sin remordimientos. He servido a las órdenes de dos Jefes de Guerra de la Horda. Y ahora, dirijo a los Puño de Roca.' WHERE `ID`=15322;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사과 드립니다. 당신을 화나게 할 생각은 없었습니다. 저는 제 동족을 대표해서 여기 왔습니다.', `MaleText_loc4`='对不起。我并不是有意冒犯。我来这里是为了我的人民的利益。', `MaleText_loc5`='很抱歉。我無意冒犯。我是代表我的人民來到這裡。', `MaleText_loc7`='Lo siento. No quería ofender. Estoy aquí en representación de mi pueblo.', `FemaleText_loc1`='사과 드립니다. 당신을 화나게 할 생각은 없었습니다. 저는 제 동족을 대표해서 여기 왔습니다.', `FemaleText_loc4`='对不起。我并不是有意冒犯。我来这里是为了我的人民的利益。', `FemaleText_loc5`='很抱歉。我無意冒犯。我是代表我的人民來到這裡。', `FemaleText_loc7`='Lo siento. No quería ofender. Estoy aquí en representación de mi pueblo.' WHERE `ID`=15323;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원하는 것이 무엇이지, $r의 대표여?', `MaleText_loc4`='那么你的人民想从兰特瑞索这里得到什么，$r？', `MaleText_loc5`='那你的人民要蘭崔索怎麼做，$r?', `MaleText_loc7`='Y, ¿qué quiere tu pueblo de Lantresor, $r?' WHERE `ID`=15324;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 동족이 원하는 것은 당신이 돌주먹 오우거들을 물리고 우리 영역에 대한 공격을 중단하는 것입니다. 그러면 우리도 군대를 철수할 것입니다.', `MaleText_loc4`='我的人民需要你撤回你的石拳食人魔，并停止所有针对我们领土的进攻。作为回报，我们同样会撤回我们的部队。', `MaleText_loc5`='我的人民要求你撤退你的石拳巨魔並停止所有對我們領土的攻擊行動。然後，我們才會撤退我們的軍隊。', `MaleText_loc7`='Mi gente quiere que retires a tus ogros Puño de Roca y que cesen los ataques a sus tierras. A cambio, nosotros también retiraremos a nuestras fuerzas.', `FemaleText_loc1`='제 동족이 원하는 것은 당신이 돌주먹 오우거들을 물리고 우리 영역에 대한 공격을 중단하는 것입니다. 그러면 우리도 군대를 철수할 것입니다.', `FemaleText_loc4`='我的人民需要你撤回你的石拳食人魔，并停止所有针对我们领土的进攻。作为回报，我们同样会撤回我们的部队。', `FemaleText_loc5`='我的人民要求你撤退你的石拳巨魔並停止所有對我們領土的攻擊行動。然後，我們才會撤退我們的軍隊。', `FemaleText_loc7`='Mi gente quiere que retires a tus ogros Puño de Roca y que cesen los ataques a sus tierras. A cambio, nosotros también retiraremos a nuestras fuerzas.' WHERE `ID`=15325;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<크게 소리 내어 웃는 란트레서>$B$B네가 지금 어디에 있는지 알고나 하는 소리냐? 이곳은 오우거의 땅이다. 오크와 드레나이가 있기 전부터 오우거들이 있었다. 그래, 너희의 요구를 들어주지 못하겠다면, 너희가 질 게 뻔한 전쟁을 시작하겠다는 뜻이냐? 돌주먹 일족은 너희를 부술 것이다. 돌주먹 일족이 너희를 없애버리지 못한다고 해도 전쟁망치 일족이 그렇게 할 것이야...$B$B너희 지도자도 이미 알고 있을 텐데...', `MaleText_loc4`='<兰特瑞索大笑起来。>$B$B你知道你在哪里吗，蠢货？这里是食人魔的领地。在兽人之前，甚至在德莱尼人之前，食人魔就已经存在了。现在，你想要打一场你必定失败的战争？石拳氏族会消灭你们，如果石拳没有消灭你们，战槌氏族一样会……$B$B我相信你们的领袖很明白这一点……', `MaleText_loc5`='<蘭崔索痛快地大笑。>$B$B你知道你現在在哪嗎，笨蛋?這是巨魔的地盤。在獸人之前，在德萊尼之前，還有巨魔。而你卻想發動一場必然會輸的戰爭?石拳會粉碎你的。如果石拳沒有毀滅你們，戰槌也會...$b$b我想你的領導者早就知道這點了...', `MaleText_loc7`='<Lantresor ríe ruidosamente.>$B$B¿Sabes dónde te has metido, $gestúpido:estúpida;? Este es territorio de los ogros. Antes de los orcos y antes de los draenei estaban los ogros. Y sabiendo eso, quieres empezar una guerra que perderás con toda seguridad... Puño de Roca te aplastará. Y si Puño de Roca no te aplasta, entonces será Mazo de Guerra.$B$BPero creo que tus líderes ya lo saben...' WHERE `ID`=15326;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇다면 우리는 끝까지 당신과 싸울 것입니다, 란트레서. 당신이 우리 마을을 약탈하고 동족을 죽이는 걸 그냥 보고만 있지는 않을 거니까요.', `MaleText_loc4`='那么，我们会和你战斗到底，兰特瑞索。我们不会就这么眼睁睁看着你掠夺我们的村庄，杀害我们的人民。', `MaleText_loc5`='那麼，我們會與你對抗到底，蘭崔索。我們不會呆站一旁任你掠奪我們的城鎮殺害我們的人民。', `MaleText_loc7`='Lucharemos contra ti hasta el final. No nos quedaremos de brazos cruzados mientras saqueas nuestras ciudades y matas a nuestra gente.', `FemaleText_loc1`='그렇다면 우리는 끝까지 당신과 싸울 것입니다, 란트레서. 당신이 우리 마을을 약탈하고 동족을 죽이는 걸 그냥 보고만 있지는 않을 거니까요.', `FemaleText_loc4`='那么，我们会和你战斗到底，兰特瑞索。我们不会就这么眼睁睁看着你掠夺我们的村庄，杀害我们的人民。', `FemaleText_loc5`='那麼，我們會與你對抗到底，蘭崔索。我們不會呆站一旁任你掠奪我們的城鎮殺害我們的人民。', `FemaleText_loc7`='Lucharemos contra ti hasta el final. No nos quedaremos de brazos cruzados mientras saqueas nuestras ciudades y matas a nuestra gente.' WHERE `ID`=15327;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<당신의 속마음을 꿰뚫어 보려는 듯이 쳐다보는 란트레서>$B$B어쩌면 다른 방법이 있을지도 모르지... 내가 말하는 그대로 행한다면 네 종족의 지도자가 요구하는 바를 들어주마.$B$B우리에게 도움을 준다면 서로에게 큰 도움이 될 수도 있을 것이다.', `MaleText_loc4`='<兰特瑞索怒视着你。>$B$B也许有另外一个办法……如果你完成了我要你做的事情，我可以答应你的领袖的要求。$B$B有了你的帮助，也许我们都可以得到完美的结果。', `MaleText_loc5`='<蘭崔索像是正看穿你一樣地注視著你。>$B$B或許還有別的辦法...我會同意你的領導者的要求，只要你照著我的話去做。$B$B有了你的幫助，我們或許可以幫對方一個大忙。', `MaleText_loc7`='<Lantresor te mira como si viese a través de ti.>$B$BPuede que haya otra solución... Aceptaré lo que pide tu líder, pero solo si haces exactamente lo que diga.$B$BEste trato podría beneficiarnos mucho a los dos.' WHERE `ID`=15328;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 할 일이 무엇입니까?', `MaleText_loc4`='我要做些什么呢？', `MaleText_loc5`='我要怎麼做?', `MaleText_loc7`='¿Qué debo hacer?', `FemaleText_loc1`='제가 할 일이 무엇인가요?', `FemaleText_loc4`='我要做些什么呢？', `FemaleText_loc5`='我要怎麼做?', `FemaleText_loc7`='¿Qué debo hacer?' WHERE `ID`=15329;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 할 일은 킬소로우 요새의 오크들이 그들의 기지를 전쟁망치 오우거들이 공격했다고 믿게 한 후, 전쟁망치 오우거들은 킬소로우의 오크들이 그들의 기지를 공격했다고 믿게 하는 작전을 수행하는 것일세.$B$B이 작전이 성공하면 우리 문제가 모두 해결될 것이다.$B$B돌주먹 일족은 영토를 되찾을 수 있고 너희 종족은 돌주먹 일족, 전쟁망치 일족, 어둠의 의회의 공격으로부터 자유롭게 될 것이네.', `MaleText_loc4`='你得捏造出一堆故事，让基尔索罗堡垒的兽人相信战槌食人魔袭击了他们的营地；你还得再编另一堆故事，让战槌食人魔相信基尔索罗兽人正在攻击他们的营地。$B$B这样困扰我们的两大难题就都解决了。$B$B石拳氏族会夺回他们的领地，而你的族人再也不会受到石拳、战槌和暗影议会的攻击。', `MaleText_loc5`='你要發動一系列活動讓吉爾索洛堡壘的吉爾索洛相信戰槌巨魔攻擊了他們的基地，再策劃另一系列活動讓戰槌巨魔相信吉爾索洛正要攻擊他們的基地。$B$B這樣做你就解決了我們的兩個麻煩。$B$B石拳將奪回他們的領土而你的人民將不再遭受石拳，戰槌，和吉爾索洛的攻擊。', `MaleText_loc7`='Participarás en una serie de acontecimientos que harán que los orcos Mata''penas de la Fortaleza Mata''penas piensen que los ogros de Mazo de Guerra han atacado su base. Después, tendrá lugar otra serie de acontecimientos que harán que los ogros de Mazo de Guerra piensen que los orcos de Mata''penas están atacando su base.$B$BSi lo haces, resolverás nuestros problemas y los tuyos.$B$BPuño de Roca recuperará su territorio y Mazo de Guerra, el Consejo de la Sombra y Puño de Roca dejarán de atacar a tu gente.' WHERE `ID`=15330;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비정상적으로 크게 성장한 벌레라고 해도 저를 장가르 습지대에서 쫓아낼 수는 없어요! 탐험가 연맹이 어떤 조직인지 녀석들에게 제대로 보여주겠어요...', `MaleText_loc4`='没有什么畸形的虫子可以把我赶出赞加沼泽！我会让它们知道探险者协会不是好惹的……', `MaleText_loc5`='沒有任何橫行的臭蟲可以把我逐出贊格沼澤!我會讓他們見識探險者協會的厲害...', `MaleText_loc7`='¡Ningún bicho superdesarrollado me echará de la marisma de Zangar! Yo les enseñaré de que está hecha la Liga de Expedicionarios...' WHERE `ID`=15331;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='곧 모두 다 끝장날 것이다!', `FemaleText_loc4`='很快就会结束了！', `FemaleText_loc5`='一切很快就會結束了!', `FemaleText_loc7`='¡Pronto acabará todo!' WHERE `ID`=15332;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전리품이 하나 더 생겼군!', `MaleText_loc4`='又一个战利品！', `MaleText_loc5`='我又新增一項戰利品了!', `MaleText_loc7`='¡Otro trofeo para mi colección!' WHERE `ID`=15333;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 잘했다, 천둥아!', `MaleText_loc4`='干得好，午夜！', `MaleText_loc5`='做的好，午夜!', `MaleText_loc7`='¡Bien hecho, Medianoche!' WHERE `ID`=15334;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전시물에는 손대지 마십시오.', `MaleText_loc4`='不许触摸展品。', `MaleText_loc5`='不要觸碰展覽品。', `MaleText_loc7`='No toques la exposición.' WHERE `ID`=15335;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 초대받지 못하셨습니다.', `MaleText_loc4`='你不是访客。', `MaleText_loc5`='你不是客人。', `MaleText_loc7`='No eres un invitado.' WHERE `ID`=15336;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='관람 규칙을 엄격히 준수해 주십시오.', `MaleText_loc4`='画廊的规定必须严格遵守。', `MaleText_loc5`='畫廊規定將嚴格執行。', `MaleText_loc7`='Las normas de la galería se cumplirán sin excepción.' WHERE `ID`=15337;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 이곳의 안전을 책임지고 있습니다.', `MaleText_loc4`='馆长已经为保护画廊准备就绪。', `MaleText_loc5`='這個館長是負責保衛畫廊的。', `MaleText_loc7`='Este Curator está equipado para proteger la galería.' WHERE `ID`=15338;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디까지 했죠? 아, 맞아...', `MaleText_loc4`='我说到哪里了？哦，对了……', `MaleText_loc5`='喔， 現在我在哪啊?喔，對了...', `MaleText_loc7`='Bueno, ¿en qué estaba? Ah, sí...' WHERE `ID`=15339;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절 부르셨습니까?', `MaleText_loc4`='你叫我吗？', `MaleText_loc5`='你找我嗎?', `MaleText_loc7`='¿Me llamaban?' WHERE `ID`=15340;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바보 같으니! 시간은 너의 몸을 태우는 불길이 되리라!', `MaleText_loc4`='愚蠢的家伙！时间就是吞噬你躯体的烈焰！', `MaleText_loc5`='頭腦簡單的笨蛋!你在燃燒的是時間的火焰!', `MaleText_loc7`='¡Tontos! El tiempo es el fuego en el que arderán!' WHERE `ID`=15341;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어찌 감히 이렇게 압도적인 힘에 맞서기를 꿈꾸느냐?', `MaleText_loc4`='你如何抵挡这无坚不摧的力量？', `MaleText_loc5`='你怎能期望抵抗這樣勢不可當的力量?', `MaleText_loc7`='¿Cómo pueden esperar enfrentese a semejante poder?' WHERE `ID`=15342;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모든 차원과 실체가 나를 향해 열려 있노라!', `MaleText_loc4`='所有的世界都向我敞开大门！', `MaleText_loc5`='所有的實體，所有的空間對我來說都是開放的!', `MaleText_loc7`='¡Todas las realidades, todas las dimensiones están abiertas a mí!' WHERE `ID`=15343;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 말체자르 님은 혼자가 아니시다. 너희는 나의 군대와 맞서야 한다!', `MaleText_loc4`='你面对的不仅仅是玛克扎尔，还有我所号令的军团！', `MaleText_loc5`='你挑戰的不只是莫克札，而是我所率領的整個軍隊!', `MaleText_loc7`='¡No solo se enfrentan a Malchezaar, sino a todas las legiones bajo mi mando!' WHERE `ID`=15344;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마침내 악몽이 끝났다...', `MaleText_loc4`='终于……噩梦结束了……', `MaleText_loc5`='惡夢終於結束了...', `MaleText_loc7`='Al fin acaba la pesadilla...' WHERE `ID`=15345;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우워어! 나 어둠의 의회의 마술사다! 나 전쟁망치 일족 영... 영역 때문에 왔다... 전쟁망치 일족 땅 문제로 왔다!', `MaleText_loc4`='喔！我是暗影议会的人！我来攻打战槌氏族！', `MaleText_loc5`='吼!我是暗影議會的巫師!我是為了戰槌的領..領...我是為了戰槌的土地來的!', `MaleText_loc7`='¡Aaah! ¡Yo ser mágico del Consejo de la Sombra! Yo venir por territorri... Tetirro... ¡Yo venir por tierras de Mazo de Guerra!' WHERE `ID`=15346;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠의 의회에서 너네 전쟁망치 일족 만나러 왔다! 우리 너네한테 화났다!', `MaleText_loc4`='暗影议会要灭了战槌氏族！我们很生气！后果很严重！', `MaleText_loc5`='暗影議會是衝著你來的，戰槌!我們對你非常憤怒!', `MaleText_loc7`='¡El Consejo de la Sombra venir por ti, Mazo de Guerra! ¡Nosotros está enfadados contigo!' WHERE `ID`=15347;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 전쟁망치 오우거 죽였다! 나는 어둠의 의회랑 친구다! 와서 잡아 봐!', `MaleText_loc4`='我又杀了一个战槌食人魔！我是暗影议会的！来杀我啊！', `MaleText_loc5`='我殺死了另一個戰槌巨魔!我是暗影議會!來抓我啊!', `MaleText_loc7`='¡Morí otro ogro Mazo de Guerra! ¡Yo soy Consejo de la Sombra! ¡Venir a por mí!' WHERE `ID`=15348;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='닥쳐라, 멍청이! 왜 시끄럽게 떠드나?', `MaleText_loc4`='闭嘴，傻瓜！你在叫什么？', `MaleText_loc5`='閉嘴，蠢貨!你吼什麼吼?', `MaleText_loc7`='¡Cállate, idiota! ¿Por qué gritas?' WHERE `ID`=15349;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들 믿게 하려고 했다... 그 사실 진짜로 만들려고 했다. 이제 그들 어둠의 의회 애들이 한 짓이라고 확신한다!', `MaleText_loc4`='我想让他们相信……我想让这看上去更真实。他们现在肯定相信是暗影议会了！', `MaleText_loc5`='我想讓它成真...我想讓它成為事實。他們現在一定認為它是暗影議會了!', `MaleText_loc7`='Mi querer fingir... Mi querer hacerlo real. ¡Ahora ellos creer seguro que Consejo de las Sombras!' WHERE `ID`=15350;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너 좋은 머리 가졌다. 녀석들 더 몰려오기 전에 언능 이거 끝내자.', `MaleText_loc4`='你真聪明。让我们在情况变糟之前把这事情搞定。', `MaleText_loc5`='你真聰明。趁沒有更多前我們現在就這麼做。', `MaleText_loc7`='Eres tan listo. Hagámoslo ahora antes de que vengan más.' WHERE `ID`=15351;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='녀석들 모두 왔다! 전쟁망치 일족 단단히 화났다! 만세!', `MaleText_loc4`='杀啊！战槌食人魔看上去很生气了！哈哈！', `MaleText_loc5`='全部就這樣了!戰槌會發狂的!萬歲!', `MaleText_loc7`='¡Esos son los míos! ¡Esos Mazo de Guerra están mu locos! ¡Hurra!' WHERE `ID`=15352;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='똑같은 고통을 겪진 않겠다.', `MaleText_loc4`='我不会再次受辱的！', `MaleText_loc5`='我不會再被折磨了!', `MaleText_loc7`='¡No sufriré más torturas!' WHERE `ID`=15353;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 좋은 소리 같다. 그 오크들 죽었다는 소리로 들린다.', `MaleText_loc4`='你这个声音真好听。像兽人临死前的惨叫。', `MaleText_loc5`='你學的聲音很好。聽起來就像獸人死亡的聲音。', `MaleText_loc7`='Lo haces sonar bastante bien. Suena como si el orco muriera.' WHERE `ID`=15354;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽은 오크 소리 최고다!', `MaleText_loc4`='我学兽人临死前的惨叫声最像了！', `MaleText_loc5`='我學的死亡獸人聲音才是最像的!', `MaleText_loc7`='¡Mi grito de orco muerto es el amo!' WHERE `ID`=15355;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너의 죽은 오크 소리 괜찮다. 하지만 내 건 더 좋다.', `MaleText_loc4`='你学兽人临死前的惨叫声还不错。可我叫的比你更好听。', `MaleText_loc5`='你的死亡獸人聲音還好。我的比較像。', `MaleText_loc7`='Tu grito de orco muerto está bien. El mío es el amo.' WHERE `ID`=15356;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분명 좋을 거다.', `MaleText_loc4`='确实不错。', `MaleText_loc5`='那當然很好。', `MaleText_loc7`='Tranqui, está bien.' WHERE `ID`=15357;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마지막에 나 죽은 오크 이빨 가는 소리 들었다... 부드득... 죽은 오크 싸우는 소리 들었다.', `MaleText_loc4`='上个月，我当上了兽人惨叫声模仿冠军。', `MaleText_loc5`='上個月，我贏了死亡獸人聲音模仿錦...錦表(標)...我贏了死亡獸人聲音模仿比賽。', `MaleText_loc7`='El mes pasao, yo gané la compipi..., la compite... Gané el concurso del grito de orco muerto.' WHERE `ID`=15358;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 밤, 보이는 것을 그대로 믿지 마십시오... 이제 여러분의 눈앞에 믿지 못할 광경이 펼쳐집니다.', `MaleText_loc4`='今晚，一切都变得虚虚实实，真伪难辨；今晚，你们的眼睛将欺骗你们的心灵！', `MaleText_loc5`='今晚，事情不是它們看來的那樣...因為今晚你可能無法相信自己的眼睛!', `MaleText_loc7`='¡Esta noche las cosas no son lo que parecen... no se confíen de lo que ven sus ojos!' WHERE `ID`=15359;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 조용히 손녀를 기다리는 할머니가 계십니다... 백발이 성성한 이 숙녀분을 두려워할 이는 아무도 없겠죠!', `MaleText_loc4`='比如说，这位老奶奶正在等待她的孙女……显然，头发斑白的慈祥老奶奶没有什么威胁！', `MaleText_loc5`='就拿這個安靜的年長女性來說，她在等待孫女的到來...當然這個和藹、灰髮的老女士沒有什麼好怕的!', `MaleText_loc7`='Por ejemplo esta ancianita que espera la visita de su nieta... ¡Seguro que no hay nada que temer de esta dulce anciana de pelo canoso!' WHERE `ID`=15360;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만, 제가 여러분의 눈을 속이고 있다면?! 저 아래 뭐가 있는지 직접 확인하십시오! 이제... 연극을 시작하겠습니다!', `MaleText_loc4`='但是我不能说得太多！你们必须自己看清隐藏在伪装下面的真相！现在——演出开始！', `MaleText_loc5`='但不要叫我告訴你結果!你得自己看看這些表象之下隱藏了什麼!而現在...好戲就要上場!', `MaleText_loc7`='¡Pero no dejen que los confunda! ¡Vean con sus propios ojos lo que hay detrás de las apariencias! Y, ahora... ¡que continúe el espectáculo!' WHERE `ID`=15361;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 밤, 충직한 동료의 도움을 받아 고향으로 돌아가기 위해서 필사적으로 노력하는 길 잃은 한 소녀를 통해 인간의 영혼은 그 깊이가 얼마나 되는지 알아보겠습니다!', `MaleText_loc4`='今晚，我们将见证人类灵魂深处的信念。一位迷失的小女孩，在忠诚的伙伴们的帮助下寻找回家的路！', `MaleText_loc5`='今晚我們要探索人類靈魂的深度，和一個迷失又寂寞的女孩一起 - 在她忠心的同伴幫助下 - 竭盡所能地尋找她回家的路!', `MaleText_loc7`='¡Esta noche nos sumergimos en las profundidades del alma humana mientras nos encontramos con una niña perdida y sola que intenta desesperadamente, con la ayuda de sus fieles compañeros, encontrar el camino a su casa!' WHERE `ID`=15362;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불행히도, 심술궂고 사악한 쭈그렁할멈이 이 소녀의 뒤를 쫓고 있습니다!', `MaleText_loc4`='但是……一个邪恶的老巫婆正在追赶着她！', `MaleText_loc5`='但是她被一個...邪惡、壞心的老太婆追趕著!', `MaleText_loc7`='¡Sin embargo... la persigue una vieja bruja maligna!' WHERE `ID`=15363;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='과연 소녀는 살아서 집에 돌아갈 수 있을까요? 그 답은 오직 시간만이 알려줄 것입니다. 이제... 연극을 시작하겠습니다!', `MaleText_loc4`='她能逃脱魔掌吗？她能平安回家吗？只有时间才能回答这些问题。现在——演出开始！', `MaleText_loc5`='她會活下來嗎?她會戰勝嗎?時間會證明一切。而現在...好戲就要上場!', `MaleText_loc7`='¿Será capaz de salvarse? ¿Vencerá? Solo el tiempo lo dirá. ¡Y ahora... que continúe el espectáculo!' WHERE `ID`=15364;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 밤... 금지된 사랑의 이야기를 파헤쳐 보겠습니다!', `MaleText_loc4`='今晚，我们将看到一段受到百般阻挠的爱情！', `MaleText_loc5`='今晚...我們要探索一個禁忌之愛的故事。', `MaleText_loc7`='¡Esta noche... vamos a explorar un relato de amor prohibido!' WHERE `ID`=15365;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기억해 두십시오. 두고 보면 아시겠지만 모든 사랑 얘기가 행복하게 끝나는 것은 아닙니다. 때로는 장미 가시처럼 아픈 것이 사랑이지요!', `MaleText_loc4`='但是，大家知道，并非所有的爱情故事都有完满的结局。有些时候，爱情就像荆棘一样危险！', `MaleText_loc5`='小心點，因為不是所有的愛情故事都有幸福的結局，你會慢慢懂的。有時候，愛情就像刺那樣令人心痛!', `MaleText_loc7`='¡Pero cuidado, no todos los cuentos de amor tienen un final feliz, como puede darse el caso! ¡A veces, el amor pincha como una espina!' WHERE `ID`=15366;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래도 제게서 사랑을 뺏어가지는 마세요. 운명이 연인들을 갈라놓을 때 어떤 비극이 기다리고 있을까요?! 이제... 연극을 시작하겠습니다!', `MaleText_loc4`='耳闻为虚眼见为实，当两个彼此相爱的人在今晚见面时，又将会上演什么样的悲剧？大家拭目以待吧！现在——演出开始！', `MaleText_loc5`='但不要問我;你要自己體驗星光交織下的喜鵲橋前方有著什麼樣的悲劇!而現在...好戲就要上場!', `MaleText_loc7`='Pero comprueben por ustedes mismos la tragedia que aguarda cuando los caminos de dos amantes se cruzan! ¡Y ahora... que continúe el espectáculo!' WHERE `ID`=15367;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='텍스트가 잘 표시되는지 확인하기 위한 보스용 이모트 시험용입니다.', `MaleText_loc4`='[PH] This is a test boss emote to see how the text is displayed.', `MaleText_loc5`='[PH] This is a test boss emote to see how the text is displayed.', `MaleText_loc7`='[PH] Esto es un emotexto de prueba de jefe para ver cómo se muestra el texto.' WHERE `ID`=15368;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모든 게시물은 교도관 불로크를 만나 허가를 받아야만 붙일 수 있습니다.$B$B만일 무단으로 게시물을 붙이다 적발되면 벌을 받게 됩니다.$B$B게시물을 붙이는 것은 무료입니다.', `MaleText_loc4`='想要张贴悬赏令的人必须事先与监护者布罗克交谈。$B$B未经批准擅自张贴将被起诉。张贴悬赏令不需支付金币。', `MaleText_loc5`='登記者在發佈任何任務之前要先和守望者波洛克談談。$B$B我們會起訴未經同意的發佈者。$B$B不要發佈帳單。', `MaleText_loc7`='Los inscritos tendrán que hablar con el celador Tororroc antes de publicar cualquier tarea.$B$BLos que publiquen anuncios no aprobados serán perseguidos.$B$BNo publiquéis facturas.' WHERE `ID`=15369;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모든 게시물은 교도관 모입프 질을 만나 허가를 받아야만 붙일 수 있습니다.$B$B만일 무단으로 게시물을 붙이다 적발되면 벌을 받게 됩니다.$B$B또한, 이곳에 청구서를 붙이지 마십시오.', `MaleText_loc4`='想要张贴悬赏令的人必须事先与监护者莫布吉尔交谈。$B$B未经批准擅自张贴将被起诉。张贴悬赏令不需支付金币。', `MaleText_loc5`='登記者在發佈任何任務之前要先和守望者莫布夫·吉爾談談。$B$B我們將會起訴那些未經同意的發佈行為。$B$B不張貼清單。', `MaleText_loc7`='Se exige que los participantes hablen con el celador Moi''bff Jill antes de anunciar ninguna tarea.$B$BAquellos a los que se halle haciendo anuncios sin aprobar serán procesados.$B$BNo colguéis facturas.' WHERE `ID`=15370;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='망할 오우거들. 전부 지옥에나 떨어져라. 이 야만족으로부터 우리를 구해줄 자는 없소!? 이번이 벌써 50번째 납치 사건이오.', `MaleText_loc4`='那些该死的食人魔。他们应该被推到虚空里。有人能从这些野人手里拯救我们吗？这已经是最近第五次绑架了！', `MaleText_loc5`='那些可惡的巨魔。詛咒他們進入虛空。沒有人要把我們從這些野蠻人手中救出來嗎!這是這麼多日子以來第五次綁架了。', `MaleText_loc7`='Malditos ogros. Al Vacío con ellos. ¡¿Es que nadie nos librará de esos salvajes?! ¡Van a un secuestro por día!' WHERE `ID`=15371;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그게 우리가 줄 수 있는 최대한의 보상이오. 누군가 이 일을 맡아주면 좋을 텐데...', `MaleText_loc4`='那已经是我们所能提供的最好的奖励了。希望有人会接受那个任务。', `MaleText_loc5`='那是我們所能提供的最好的獎勵。希望有人會接受這個任務。', `MaleText_loc7`='Esa es la mejor recompensa que van a poder ofrecer. Esperemos que alguien acepte esta misión.' WHERE `ID`=15372;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새로운 게시물이 올라갑니다! 모험가여, 영웅들이여, 게시판 주위로 모이십시오!', `MaleText_loc4`='新的公告贴好了！冒险家和英雄们，聚集到公告板前吧！', `MaleText_loc5`='新消息公佈!冒險者和英雄們，聚集到佈告欄前來吧!', `MaleText_loc7`='¡Hay nuevos anuncios! ¡Aventureros y héroes, reuníos alrededor del tablón de anuncios!' WHERE `ID`=15373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 텔라아르의 평화와 안전을 지키는 데 필요한 도움을 얻을 수 있겠군!', `MaleText_loc4`='这样塔拉就应该能得到它所需要的援助了！', `MaleText_loc5`='那應該會找到泰拉需要的幫助!', `MaleText_loc7`='¡Eso le debería dar a Telaar la ayuda que necesita!' WHERE `ID`=15374;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일거리를 찾고 있다면 현상 수배 전단을 확인해 보시오.', `MaleText_loc4`='$r，如果你在找活干的话，去看下公告板吧。', `MaleText_loc5`='如果你在找工作的話就看看佈告欄，$r。', `MaleText_loc7`='Si buscas trabajo, mira el tablón de anuncios, $r.' WHERE `ID`=15375;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 제 모자를 잘 다루시는군요, $n. 그 어느 곳을 가도 제 모자보다 좋은 모자는 찾지 못할 겁니다.', `MaleText_loc4`='$n，好好保护我的帽子。世上再也找不出比这顶帽子更好的了。', `MaleText_loc5`='你現在將我的帽子保存得很好，$n。你在這個世界或任何地方都找不到比這更好的一頂了。', `MaleText_loc7`='Trata bien mi sombrero, $n. No encontrarás uno mejor en este mundo. Ni en el otro.' WHERE `ID`=15376;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여러분! 세계수에 있는 아키몬드에게 가서 그를 막으십시오, 우리는 이곳에서 언데드들을 막아야 합니다!', `FemaleText_loc4`='[PH] Players! Go Stop Archimonde at the tree, we will hold the Undead off here!', `FemaleText_loc5`='[PH]玩家!快去樹那裡阻止阿克蒙德，我們會守住這裡的不死族!', `FemaleText_loc7`='[PH] ¡Jugadores! ¡Id a detener a Archimonde al árbol, nosotros mantendremos a los no-muertos alejados!' WHERE `ID`=15377;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 누가 사냥꾼의 애마를 건드리느냐?', `MaleText_loc4`='是谁胆敢攻击我的坐骑？', `MaleText_loc5`='誰敢攻擊獵人的駿馬?', `MaleText_loc7`='¿Quién osa atacar al corcel del Cazador?' WHERE `ID`=15378;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한번 혼쭐이 나야 정신을 차릴 놈들이로구나!', `MaleText_loc4`='也许你应该找个更加厉害的对手过招！', `MaleText_loc5`='或許你寧願對抗更為可怕的敵手來測試自己的實力?!', `MaleText_loc7`='¿Quizá prefieran probarse con un oponente más imponente?' WHERE `ID`=15379;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽은 이들을 전혀 존중하지 않는 오우거들에게 교훈을 가르쳐 주어야 합니다.', `MaleText_loc4`='他们一点也不尊重死者，$r。我们必须狠狠教训一下这些食人魔了。', `MaleText_loc5`='他們對亡者沒有尊敬，$r。一定要給巨魔一點教訓。', `MaleText_loc7`='No tienen respeto por los muertos, $r. Hay que dar una lección a los ogros.' WHERE `ID`=15380;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생존자들을 찾아야 합니다. 누군가 아직 살아 있다면 적어도 구하려는 시도는 해 봐야 하지 않겠습니까?', `MaleText_loc4`='我们必须搜寻幸存者。如果仍然有人活着，我们至少得试试救他们回来……', `MaleText_loc5`='我們一定要尋找生還者。如果有任何人還活著，我們一定要至少試著把他們救回來...', `MaleText_loc7`='Debemos buscar supervivientes. Si hay alguien que todavía viva, al menos debemos intentar traerlo de vuelta...' WHERE `ID`=15381;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와주십시오! 도와주십시오! 저들이 절 잡아먹으려고 합니다!', `MaleText_loc4`='救命！救命！他们要吃了我！', `MaleText_loc5`='救命!救命!他們要吃了我!', `MaleText_loc7`='¡Socorro! ¡Auxilio! ¡Van a comerme!', `FemaleText_loc1`='도와주십시오! 도와주십시오! 저들이 절 잡아먹으려고 합니다!', `FemaleText_loc4`='救命！救命！他们要吃了我！', `FemaleText_loc5`='救命!救命!他們要吃了我!', `FemaleText_loc7`='¡Socorro! ¡Auxilio! ¡Van a comerme!' WHERE `ID`=15382;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 난 끝장이구나!', `MaleText_loc4`='我完蛋了！', `MaleText_loc5`='我完蛋了!', `MaleText_loc7`='¡Es mi ruina!', `FemaleText_loc1`='이제 난 끝장이구나!', `FemaleText_loc4`='我完蛋了！', `FemaleText_loc5`='我完蛋了!', `FemaleText_loc7`='¡Es mi ruina!' WHERE `ID`=15383;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언젠가 영웅이 나타나 오크에게 예전의 영광을 안겨줄 겁니다.', `MaleText_loc4`='总有一天，一个英雄将会挺身而出，让兽人重获昔日的荣耀。', `MaleText_loc5`='有一天，一名英雄將崛起，帶領獸人重拾往日的榮耀。', `MaleText_loc7`='Un día, un héroe se alzará y elevará a los orcos a su gloria de antaño.', `FemaleText_loc1`='언젠가 영웅이 나타나 오크에게 예전의 영광을 안겨줄 거예요.', `FemaleText_loc4`='总有一天，一个英雄将会挺身而出，让兽人重获昔日的荣耀。', `FemaleText_loc5`='有一天，一名英雄將崛起，帶領獸人重拾往日的榮耀。', `FemaleText_loc7`='Un día, un héroe se alzará y elevará a los orcos a su gloria de antaño.' WHERE `ID`=15384;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오우거들에게 열쇠가 있습니다! 오우거들을 해치우고 절 여기서 꺼내주십시오!', `MaleText_loc4`='食人魔拿着钥匙！干掉他们，把我弄出这里！', `MaleText_loc5`='鑰匙在巨魔手上!殺了巨魔把我救出去!', `MaleText_loc7`='¡Los ogros tienen las llaves! ¡Mata a los ogros y sácame de aquí!', `FemaleText_loc1`='오우거들에게 열쇠가 있어요! 오우거들을 해치우고 절 여기서 꺼내주세요!', `FemaleText_loc4`='食人魔拿着钥匙！干掉他们，把我弄出这里！', `FemaleText_loc5`='鑰匙在巨魔手上!殺了巨魔把我救出去!', `FemaleText_loc7`='¡Los ogros tienen las llaves! ¡Mata a los ogros y sácame de aquí!' WHERE `ID`=15385;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 아이들이 고아가 될 겁니다!', `MaleText_loc4`='我的孩子们会变成孤儿的！', `MaleText_loc5`='我的孩子會變成孤兒!', `MaleText_loc7`='¡Convertirán a mis hijos en huérfanos!', `FemaleText_loc1`='제 아이들이 고아가 될 겁니다!', `FemaleText_loc4`='我的孩子们会变成孤儿的！', `FemaleText_loc5`='我的孩子會變成孤兒!', `FemaleText_loc7`='¡Convertirán a mis hijos en huérfanos!' WHERE `ID`=15386;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙습니다! 당신이 마그하르를 도와준 일을 절대 잊지 않겠습니다.', `MaleText_loc4`='谢谢你，$R！你为玛格汉所做的一切，我们都将铭记在心。', `MaleText_loc5`='謝謝你，$r!你對瑪格哈的貢獻不會被遺忘的。', `MaleText_loc7`='¡Gracias, $r! Tus servicios a los Mag''har no se olvidarán.', `FemaleText_loc1`='고맙습니다! 당신이 마그하르를 도와준 일을 절대 잊지 않겠어요.', `FemaleText_loc4`='谢谢你，$R！你为玛格汉所做的一切，我们都将铭记在心。', `FemaleText_loc5`='謝謝你，$r!你對瑪格哈的貢獻不會被遺忘的。', `FemaleText_loc7`='¡Gracias, $r! Tus servicios a los Mag''har no se olvidarán.' WHERE `ID`=15387;
