UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 고맙습니다, 영웅이여!', `MaleText_loc4`='太感谢你了，英雄！', `MaleText_loc5`='非常感激，英雄!', `MaleText_loc7`='¡Muchas gracias, héroe!', `FemaleText_loc1`='정말 고맙습니다, 영웅이여!', `FemaleText_loc4`='太感谢你了，英雄！', `FemaleText_loc5`='非常感激，英雄!', `FemaleText_loc7`='¡Muchas gracias, héroe!' WHERE `ID`=15389;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정령들이 당신을 보살피길!', `MaleText_loc4`='灵魂与你同在，$r！', `MaleText_loc5`='靈魂守護著你，$r!', `MaleText_loc7`='¡Que los espíritus te cuiden, $r!', `FemaleText_loc1`='정령들이 당신을 보살피길!', `FemaleText_loc4`='灵魂与你同在，$r！', `FemaleText_loc5`='靈魂守護著你，$r!', `FemaleText_loc7`='¡Que los espíritus te cuiden, $r!' WHERE `ID`=15390;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 가십시오. 여기서 벗어나야 합니다! 목숨을 지키십시오!', `MaleText_loc4`='继续，快离开这里！保护好你自己！', `MaleText_loc5`='走吧，離開這裡!拯救你自己!', `MaleText_loc7`='¡Venga, sal de aquí! ¡Sálvate!' WHERE `ID`=15391;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘하셨습니다, 모험가여. 격노한 윈터칠이 죽었으니 적들은 잠시 동안 진군을 멈출 수밖에 없습니다. 이 짧은 시간을 현명하게 사용하도록 하세요. 조만간 아키몬드가 훨씬 더 강력한 군대를 보낼 테니 상처를 치료하고 방어 태세를 점검해야 합니다. 내 빈약한 예비 군대가 전투가 다시 재개되면 그대를 지원할 것입니다.', `FemaleText_loc4`='干得好，冒险者。雷基·冬寒的死让我们获得了一个短暂的喘息机会。好好利用这段珍贵的时间吧。治疗一下你的伤口，做好准备，很快阿克蒙德就会向我们派出更强大的部队。我的部队会在战斗再次开始时增援你的。', `FemaleText_loc5`='做的好，冒險者。瑞齊·凜冬的死暫停了敵人的進展，讓我們全都可以喘一口氣。聰明地使用這短暫的時間。治好傷者，準備好你們的防禦，阿克蒙德很快就會派更可怕的軍隊來對付我們。', `FemaleText_loc7`='Bien hecho, $gaventurero:aventurera;. La muerte de Ira Fríoinvierno exánime nos ha dado una breve pausa en el avance del enemigo. Utiliza sabiamente este breve tiempo. Cuida de tus heridos y prepara tus defensas, ya que, pronto, Archimonde nos enviará tropas más letales aún. Mi exigua fuerza de unidades de reserva te reforzará cuando se vuelva a emprender la batalla.' WHERE `ID`=15392;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아키몬드가 어떤 군대를 보내던 우리는 준비가 되어 있습니다, 프라우드무어 님.', `MaleText_loc4`='我们已经准备好对付阿克蒙德的任何爪牙了，普罗德摩尔女士。', `MaleText_loc5`='不管阿克蒙德要派誰來對付我們，我們都已經準備好了，普勞德摩爾女士。', `MaleText_loc7`='Estamos listos para cualquier cosa que Archimonde nos mande, lady Valiente.', `FemaleText_loc1`='아키몬드가 어떤 군대를 보내던 우리는 준비가 되어 있습니다, 프라우드무어 님.', `FemaleText_loc4`='我们已经准备好对付阿克蒙德的任何爪牙了，普罗德摩尔女士。', `FemaleText_loc5`='不管阿克蒙德要派誰來對付我們，我們都已經準備好了，普勞德摩爾女士。', `FemaleText_loc7`='Estamos listos para cualquier cosa que Archimonde nos mande, lady Valiente.' WHERE `ID`=15393;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그렇다면 아키몬드가 설쳐 대는 모습을 지켜보도록 할까요?', `FemaleText_loc4`='那么就让阿克蒙德再吃一场败仗吧！', `FemaleText_loc5`='然後讓阿克蒙德做他的壞事。', `FemaleText_loc7`='Entonces, que Archimonde haga lo peor que sepa.' WHERE `ID`=15394;
