UPDATE `locales_broadcast_text` SET `MaleText_loc1`='관심이 있으시다면 당신에게 채광을 가르쳐 드리도록 하겠습니다.', `MaleText_loc4`='我可以教你采矿。你感兴趣吗？', `MaleText_loc5`='我可以教你採礦。有興趣嗎?', `MaleText_loc7`='Puedo adiestrarte en minería. ¿Te interesa?', `FemaleText_loc1`='관심이 있으시다면 당신에게 채광을 가르쳐 드리도록 하지요.', `FemaleText_loc4`='我可以教你采矿。你感兴趣吗？', `FemaleText_loc5`='我可以教你採礦。有興趣嗎?', `FemaleText_loc7`='Puedo adiestrarte en minería. ¿Te interesa?' WHERE `ID`=15411;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 머리에 치료제를 발라주십시오. 가시로 만든 제 왕관이 마음에 드십니까?', `MaleText_loc4`='在我的头上涂些治疗药膏。你喜欢我的荆棘王冠吗？', `MaleText_loc5`='把治療藥膏塗在我頭上。你喜歡我的刺棘皇冠嗎?', `MaleText_loc7`='Unce mi frente con un bálsamo de sanación. ¿Te gusta mi corona de espinas?' WHERE `ID`=15412;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='관심이 있으시다면 약초채집의 방법에 대해서 가르쳐 드리도록 하겠습니다.', `MaleText_loc4`='我可以教你草药学。你感兴趣吗？', `MaleText_loc5`='我可以教你草藥學。有興趣嗎?', `MaleText_loc7`='Te puedo instruir en la herboristería. ¿Te interesa?', `FemaleText_loc1`='관심이 있으시다면 약초채집의 방법에 대해서 가르쳐 드리도록 하지요.', `FemaleText_loc4`='我可以教你草药学。你感兴趣吗？', `FemaleText_loc5`='我可以教你草藥學。有興趣嗎?', `FemaleText_loc7`='Te puedo instruir en la herboristería. ¿Te interesa?' WHERE `ID`=15413;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연금술의 신비한 매력을 배우고 싶으십니까?', `MaleText_loc4`='我可以教你炼金术。你感兴趣吗？', `MaleText_loc5`='我可以教你鍊金術。有興趣嗎?', `MaleText_loc7`='Puedo instruirte en alquimia. ¿Te interesa?', `FemaleText_loc1`='연금술의 신비한 매력을 배우고 싶으신가요?', `FemaleText_loc4`='我可以教你炼金术。你感兴趣吗？', `FemaleText_loc5`='我可以教你鍊金術。有興趣嗎?', `FemaleText_loc7`='Puedo instruirte en alquimia. ¿Te interesa?' WHERE `ID`=15414;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='놀랍군요! 아네테론이 그대에게 패한 덕분에 아키몬드의 계획이 지연되었고, 우리는 승리에 그만큼 가까워졌습니다. 하지만 저와 제 병사들은 몹시 지친 상태라 철수해야 합니다. 그대의 힘이 약해지지 않았다면 동쪽에 있는 스랄의 야영지로 가세요. 그곳에서 우린 또다시 항쟁을 벌일 것입니다. 부디 무사하시길.', `FemaleText_loc4`='太棒了！你打败了安纳塞隆，延缓了阿克蒙德的计划，让我们离胜利更近了一步。但是，我的部队不能留在这里。他们都已经非常疲倦，现在是撤退的时候了。如果你还能支撑下去的话，就到东面去，找到萨尔的营地吧。那是我们的另外一个据点。保重。', `FemaleText_loc5`='太驚人了!你擊敗安納塞隆的事實讓阿克蒙德的目的受到延誤，也讓我們離勝利更近一步。不過，我的軍隊不能待在這裡。我和我的軍隊都筋疲力竭，現在是時候好好休息了。如果你的力量還夠，就前往東邊的索爾的營地。我們會在那裡再做停留。祝你好運。', `FemaleText_loc7`='¡Es asombroso! La derrota de Anatheron ha retrasado a Archimonde en sus planes y nos ha acercado a la victoria. Pero mis fuerzas no pueden permanecer aquí. Mis soldados y yo estamos muy cansados y debemos retirarnos. Si todavía te quedan fuerzas, ve al campamento de Thrall, al este. Allí opondremos resistencia de nuevo. Suerte.' WHERE `ID`=15415;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠습니다. 우리가 다시 만날 때까지, 안녕하시길...', `MaleText_loc4`='再会，普罗德摩尔女士。', `MaleText_loc5`='下次再見，普勞德摩爾女士。', `MaleText_loc7`='Hasta que nos volvamos a encontrar, Lady Valiente.', `FemaleText_loc1`='알겠습니다. 우리가 다시 만날 때까지, 안녕하시길...', `FemaleText_loc4`='再会，普罗德摩尔女士。', `FemaleText_loc5`='下次再見，普勞德摩爾女士。', `FemaleText_loc7`='Hasta que nos volvamos a encontrar, Lady Valiente.' WHERE `ID`=15416;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 옷을 가져갈 수 없다! 죽어라!', `MaleText_loc4`='别想抢走我的衣服！死吧！', `MaleText_loc5`='你拿不到我的衣服的!死吧!', `MaleText_loc7`='¡No te llevarás mi ropa! ¡Muere!' WHERE `ID`=15418;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말한 대로 될 거다!', `MaleText_loc4`='按我说的做！', `MaleText_loc5`='它奉命行事!', `MaleText_loc7`='¡HACE LO QUE SE LE DICE!' WHERE `ID`=15419;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='찌개 속에나 들어가라!', `MaleText_loc4`='到锅里去！', `MaleText_loc5`='進到燉肉裡去!', `MaleText_loc7`='¡MÉTETE EN EL ESTOFADO!' WHERE `ID`=15420;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뱃속에 넣으면 좋겠군!', `MaleText_loc4`='你的味道应该不错！', `MaleText_loc5`='我要把你吃掉!', `MaleText_loc7`='¡TÚ BUENO EN BARRIGA!' WHERE `ID`=15421;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그 보급품 상자들을 되찾아야 합니다!', `FemaleText_loc4`='我们必须把那些补给箱给弄回来！', `FemaleText_loc5`='我們一定要追回那些補給木箱!', `FemaleText_loc7`='¡Hay que recuperar esas cajas de suministros!' WHERE `ID`=15422;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 먹을 오크들이 잔뜩 널려 있는데도 왜 날 잡아먹으려는 거야?', `MaleText_loc4`='你有这么多兽人可以吃，为什么还要吃我？', `MaleText_loc5`='你有這麼多獸人可以吃為什麼還想吃我?', `MaleText_loc7`='¿Por qué quieres comerme cuando tienes a todos esos orcos para comer?' WHERE `ID`=15423;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고마워요, $n 님! 제 목숨을 구해 주신 게 이걸로 몇 번째죠? 3번이던가요? 제 책에 우리 얘기를 쓰면 정말 재미있겠네요!', `MaleText_loc4`='谢谢你，$n！你救了我多少次了？三次？我已经把你当亲人看待了！', `MaleText_loc5`='謝謝，$n!你救過我多少次了?三次?這讓我的血液得以傳承!', `MaleText_loc7`='¡Gracias, $n! ¿Cuántas veces me has salvado la vida ya? ¿Tres? ¡Puedes considerarte mi $ghermano:hermana;!' WHERE `ID`=15424;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세나리온 수풀에 들어갈 때는 조심하시오. 주변을 해로운 기운이 배회하고 있소. 그 기운의 잔류물이 드루이드 친구들을 죽인 것이 틀림없소.', `MaleText_loc4`='进入这片树林的时候小心点，$c。这地方被一个邪恶的光环笼罩着，肯定是那些杀害我的德鲁伊同胞的家伙留下的。', `MaleText_loc5`='進入灌木叢要小心點，$c。有個具傷害力的光環徘徊在那個地方。那一定是以前摧毀曾在這裡的德魯伊的生物殘渣。', `MaleText_loc7`='Ten cuidado al ir al matorral, $c. Hay un aura perjudicial en ese sitio. Debe de ser el residuo de lo que fuera que destruyera a mis compañeros druidas.' WHERE `ID`=15425;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 아빠가 전쟁망치 일족에게 몸값을 내면 네 녀석을 잡아먹지 않을지도 모르지.', `MaleText_loc4`='要是你爸爸给我们送来赎金，我们就不吃你。', `MaleText_loc5`='你爸爸對戰槌貢獻良多，或許我們不會吃你。', `MaleText_loc7`='Tu papá pagar a Mazo de Guerra y quizás nosotros no comerte.' WHERE `ID`=15426;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하! 농담을 믿다니... 어쨌거나 우리는 널 잡아먹을 거다!', `MaleText_loc4`='哈哈！开个玩笑。我们肯定会吃掉你的！', `MaleText_loc5`='哈哈!開玩笑的。我們當然會把你吃掉!', `MaleText_loc7`='¡Ja, ja! Era broma. Te comemos fijo.' WHERE `ID`=15427;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 숲은 꼭 유령이 나올 것 같습니다. 얼라이언스보다도 나쁜 기운이 가득하니 조심하십시오.', `MaleText_loc4`='这片森林是个怪异的地方，这里的坏魂能要比联盟还多，所以你自己得小心点。', `MaleText_loc5`='這個森林是個令人毛骨悚然的地方。到處都是比聯盟更多的邪惡護符，所以你要小心自身安全。', `MaleText_loc7`='Este bosque ser un lugar espeluznante. Está lleno de más mal Juju que la Alianza, así que ten cuidado.' WHERE `ID`=15428;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 숲 속에서 위험한 존재는 호드뿐만이 아닙니다. 겉으로 드러난 평온한 모습에 속지 마십시오.', `FemaleText_loc4`='部落不是这片森林里潜伏着的唯一危险。不要让它宁静的表象迷惑了你。', `FemaleText_loc5`='部落不是森林中唯一的危險。不要被它看似寧靜的樣子騙了。', `FemaleText_loc7`='La Horda no es el único peligro de este bosque. No te dejes engañar por su aparente tranquilidad.' WHERE `ID`=15429;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쿵! 저기 끓고 있는 뼈를 봐라!', `MaleText_loc4`='哈哈！听那烤软骨的滋滋声！', `MaleText_loc5`='天啊!看那個軟骨被煮的滋滋作響!', `MaleText_loc7`='¡AH! ¡Mira cómo cruje el cartílago!' WHERE `ID`=15430;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 이건 최고의 뒤틀린 드레나이 스튜를 만드는 조리법이다!', `MaleText_loc4`='这是做破碎者杂烩的最棒的配方！', `MaleText_loc5`='然後這就是最棒的破碎者海鮮雜燴濃湯!', `MaleText_loc7`='Esta e'' la reseta pa'' la mejor sopa de pescao.' WHERE `ID`=15431;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우선 양념이 필요하지.', `MaleText_loc4`='首先你需要一点香料。', `MaleText_loc5`='首先你需要香料。', `MaleText_loc7`='Primero necesitas las especias.' WHERE `ID`=15432;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가마솥에 소금을 넣고...', `MaleText_loc4`='把盐放进锅里……', `MaleText_loc5`='鹽放到鍋子裡...', `MaleText_loc7`='La sal va a la olla...' WHERE `ID`=15433;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그다음 후추를 뿌리는 거지...', `MaleText_loc4`='把胡椒扔进锅里……', `MaleText_loc5`='然後你放一點胡椒到鍋子裡...', `MaleText_loc7`='Después, mete la pimienta en la olla...' WHERE `ID`=15434;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 한 단계 높여서 비밀 재... 재... 재 뭐더라... 비밀 양념을 뿌리는 거지!', `MaleText_loc4`='现在我们把主菜弄开一道小口，放那些……那些……特别的调料！', `MaleText_loc5`='現在我們要放入一點秘密的...呃...呃...秘密醬料!', `MaleText_loc7`='Ahora lo animamos una pizca con el ingra... ingor... inrag... ¡con la salsa secreta!' WHERE `ID`=15435;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 마지막으로 코르키를 넣으면 돼!', `MaleText_loc4`='最后，我们把考尔奇放进去！', `MaleText_loc5`='而最後，我們賭了柯爾奇!', `MaleText_loc7`='Y, por último, ¡lo ponemos en el Corki!' WHERE `ID`=15436;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$r|1이여;여;, 자네는 분명 강하네만 이곳의 모든 도전자들을 이기고 전쟁망치 용사가 되기 위한 조건을 갖추고 있나?', `MaleText_loc4`='$R，你确实很强壮，但是你配得上战槌勇士的称号吗？', `MaleText_loc5`='你當然很強壯，$r，但是你有成為戰槌勇士的本事嗎?', `MaleText_loc7`='Eres muy fuerte, $r, pero ¿crees que tienes lo que hay que tener para ser un campeón de Mazo de Guerra?' WHERE `ID`=15437;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='망치발굽이 돌격할 준비를 합니다.', `MaleText_loc4`='断蹄准备冲锋。', `MaleText_loc5`='斷趾準備發動攻擊。', `MaleText_loc7`='Dedorroto se prepara para atacar.' WHERE `ID`=15438;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='첫 번째 대전이 시작됩니다! $n|1과;와; 사나운 갈래발굽인 망치발굽의 대결입니다, 여러분!', `MaleText_loc4`='战斗即将开始！$n对凶猛的裂蹄牛——断蹄！', `MaleText_loc5`='打鬥就要開始了!$n對兇猛的裂蹄，斷趾!', `MaleText_loc7`='¡La batalla está a punto de comenzar! ¡$n contra el feroz uñagrieta, Dedorroto!' WHERE `ID`=15439;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='길을 비켜라. 우리가 대결 중인 게 안 보이나!', `MaleText_loc4`='不要挡我的路，$r。你没看到我们正在战斗吗！', `MaleText_loc5`='別擋我的路，$r。沒看到我們正在打鬥嗎!', `MaleText_loc7`='Aparta de mi camino, $r. ¡No ves que estamos en medio de una batalla!' WHERE `ID`=15440;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피의 투기장으로 들어가게, $n. 곧 대전이 시작될 걸세!', `MaleText_loc4`='进入鲜血竞技场吧，$n。战斗就要开始了！', `MaleText_loc5`='進入血色競技場，$n。搏鬥賽要開始了!', `MaleText_loc7`='Entra en El Círculo de Sangre, $n. ¡La lucha está a punto de comenzar!' WHERE `ID`=15441;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 망치발굽을 쓰러뜨렸습니다!', `MaleText_loc4`='$n打败了断蹄！', `MaleText_loc5`='$n擊敗了斷趾!', `MaleText_loc7`='¡$n ha vencido a Dedorroto!' WHERE `ID`=15442;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 패배했습니다!', `MaleText_loc4`='$n被打败了！', `MaleText_loc5`='$n被擊敗!', `MaleText_loc7`='¡$n saborea la derrota!' WHERE `ID`=15443;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대단하군! 그 카즈로갈이 죽으면서 내지른 비명에 불타는 군단의 수뇌부가 겁먹은 게 분명하네. 이제 그대의 군대가 지닌 힘에 대해 저들도 알게 되었으니 불타는 군단이 어떻게 도발해 올지 기대해 보세.', `MaleText_loc4`='太棒了！卡兹洛加死亡时发出的嚎叫应该会让燃烧军团感到畏惧。他们现在认识到了你们所拥有的力量，那么准备好接受燃烧军团的更强烈的打击吧。', `MaleText_loc5`='太傑出了!死亡守衛領主的死亡哀嚎會讓恐懼穿透燃燒軍團的核心。他們現在知道你的軍隊擁有的力量，所以你要對燃燒軍團做好最壞的打算。', `MaleText_loc7`='¡Es extraordinario! El grito de muerte de Kaz''rogal debería llevar el miedo hasta el mismo corazón de la Legión Ardiente. Ahora conocen la fuerza que poseen tus tropas, así que puedes esperar lo peor que pueda ofrecer la Legión.' WHERE `ID`=15444;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두려워할 것은 아무것도 없습니다.', `MaleText_loc4`='我们无所畏惧。', `MaleText_loc5`='我們無所畏懼。', `MaleText_loc7`='No tenemos nada que temer.', `FemaleText_loc1`='두려워할 것은 아무것도 없어요.', `FemaleText_loc4`='我们无所畏惧。', `FemaleText_loc5`='我們無所畏懼。', `FemaleText_loc7`='No tenemos nada que temer.' WHERE `ID`=15445;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정령의 힘이 그대와 함께하기를.', `MaleText_loc4`='灵魂与你同在。', `MaleText_loc5`='願靈魂與你同在。', `MaleText_loc7`='Que los espíritus estén contigo.' WHERE `ID`=15446;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='종소리가 요란하게 울리는 것을 보니 방어 수호물이 침입자들을 감지하고 보초들에게 경고하는 것 같습니다.', `MaleText_loc4`='防御结界发现了入侵者，响起了刺耳的警报声。', `MaleText_loc5`='當防禦監督偵測到入侵者就會響起一陣響亮的排鐘聲，警告哨兵。', `MaleText_loc7`='Cuando los guardas de defensa detectan intrusos, hacen sonar una campana que alerta a los vigías.' WHERE `ID`=15447;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대단하군! 아즈갈로 같은 지옥의 군주를 처치한다는 것은 절대 쉬운 일이 아니네. 시간이 있다면 $g형제:자매;와 그 동료의 모험담을 들을 텐데 아키몬드는 그 정도의 여유조차 허락하지 않는군그래. 이미 정찰병들로부터 불타는 군단이 우리 야영지 밖에 엄청난 규모의 군사들을 집결시키고 있으며, 아키몬드가 세계수에 매우 근접했다는 보고를 받았네. 우리는 여군주 프라우드무어의 도움을 받아 철수 중이니 $g형제:자매;는 지금 즉시 세계수에 가도록 하게. 우리 세계의 운명은 아직 결정되지 않았다네.', `MaleText_loc4`='太精彩了！杀死一个像阿兹加洛这样的深渊领主并不是件小事，我的朋友。如果我们有更多的时间，我会很乐意倾听你和你同伴的故事。但是阿克蒙德不会给我们休息的机会，不管怎样，我的斥候报告说，燃烧军团正在我们营地外聚集更强大的力量，而且阿克蒙德离世界之树已经非常近了。我们正在普罗德摩尔女士的帮助下撤退。你应该立即向世界之树进发。我们世界的命运仍然未定。', `MaleText_loc5`='太傑出了!殺死一個像亞茲加洛的深淵領主不是件簡單的事，我的朋友。如果我們有多一點時間，我很樂意聽聽你和同伴的故事。不過，阿克蒙德不會給我們那點時間。我的斥候回報，軍團已在我們營地外聚集了一支巨大的軍隊，而阿克蒙德已經很接近世界之樹了。我們正在珍娜·普勞德摩爾的支援下疏散中。你應該立即前往世界之樹。我們世界的命運仍是未知數。', `MaleText_loc7`='¡Excelente! Matar a un Señor del foso como Azgalor es una hazaña digna de mención. Si tuviera más tiempo, me gustaría que me contarais cómo lo hicisteis. Pero Archimonde no nos concederá ni un minuto. Mis exploradores me han informado de que la Legión está formando un ejército enorme a las afueras de nuestro campamento y de que Archimonde está muy cerca del Árbol del Mundo. Nosotros estamos evacuando con la ayuda de Lady Valiente. Debéis dirigiros hacia el Árbol del Mundo ahora mismo. El destino de nuestro mundo aún es incierto.' WHERE `ID`=15448;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='몸 조심하십시오, 스랄 님.', `MaleText_loc4`='再会，萨尔。', `MaleText_loc5`='下次再見，索爾。', `MaleText_loc7`='Hasta que nos volvamos a encontrar, Thrall.', `FemaleText_loc1`='몸 조심하세요, 스랄 님.', `FemaleText_loc4`='再会，萨尔。', `FemaleText_loc5`='下次再見，索爾。', `FemaleText_loc7`='Hasta que nos volvamos a encontrar, Thrall.' WHERE `ID`=15449;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더러운 벌레 같은 녀석. 복종하지 않으면 죽음뿐이다!', `MaleText_loc4`='肮脏的寄生虫。投降或者等死吧！', `MaleText_loc5`='骯髒的害蟲。屈服或找死!', `MaleText_loc7`='Sucia alimaña. ¡Ríndete o muere!' WHERE `ID`=15450;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너도 마찬가지냐, 나방 녀석아? 우리는 좋은 친구였지. 네가 그리울 거다.', `MaleText_loc4`='你也一样，巨蛾？我们曾经是这么好的朋友。我会想念你的。', `MaleText_loc5`='你也是，翼鳥?我們從前是那麼好的朋友。我會想念你的。', `MaleText_loc7`='¿Tú también, aleteador? Solíamos ser tan buenos amigos... Te echaré de menos.' WHERE `ID`=15451;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런, 실수를. 가끔 달빛 섬광을 통제할 수 없을 때가 있어서 말이지...', `MaleText_loc4`='糟糕，我的错。有时候我无法控制我的月火。', `MaleText_loc5`='喔，是我不好。有時候我不能控制我的月火術。', `MaleText_loc7`='Uy, culpa mía. A veces no puedo controlar mi Fuego lunar.' WHERE `ID`=15452;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 누구이기에 날 훑어보고 평가하는 겁니까?!', `MaleText_loc4`='是谁胆敢直视着我，对我评头论足？', `MaleText_loc5`='你是誰膽敢盯著我看還提出意見?', `MaleText_loc7`='¡¿Quién eres tú para mirarme fijamente y juzgarme?!' WHERE `ID`=15453;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 아는 사이던가요? 세나리온 원정대에 가입하고 싶다면 어서 오십시오.', `MaleText_loc4`='我认识你吗？如果你对加入塞纳里奥远征队感兴趣的话，就靠近点。', `MaleText_loc5`='我認識你嗎?如果你對加入塞納里奧遠征隊有興趣的話就向前一步吧。', `MaleText_loc7`='¿Te conozco? Si quieres unirte a la expedición Cenarion, pasa.' WHERE `ID`=15454;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 누구와 대화하고 있는지 주의하십시오. 주위에 테로나방이 엿들으니까요.', `MaleText_loc4`='说话要小心，蛾子们有耳朵。', `MaleText_loc5`='小心你是在跟誰說話。泰洛飛蛾會聽見的。', `MaleText_loc7`='Ten cuidado de con quién hablas. Las teropolillas tienen orejas.' WHERE `ID`=15455;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저녁 만찬에 초대된 손님이 모두 예의 바른 것은 아니죠. 자신의 몸가짐에나 신경 쓰십시오!', `MaleText_loc4`='不是所有的客人都是那么和蔼的。注意礼貌。', `MaleText_loc5`='不是所有的晚宴賓客都很優雅。注意你的舉止!', `MaleText_loc7`='No todos los invitados a cenar son corteses. ¡Cuida tus modales!' WHERE `ID`=15456;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저것들은 모든 걸 알고 있으며 항상 엿듣고 있단 말입니다!', `MaleText_loc4`='它知道一切，它看到一切！', `MaleText_loc5`='它無所不知，無所不見!', `MaleText_loc7`='¡Todo lo sabe y todo lo ve!' WHERE `ID`=15457;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빗속에서 기다릴 필요 없습니다. 들어오십시오... 우리와 함께하셔도 됩니다.', `MaleText_loc4`='不需要在雨中等待。进来吧……我们欢迎你。', `MaleText_loc5`='不要再外面的雨中等待。進來...歡迎你進來和我們一起。', `MaleText_loc7`='No hace falta que esperes fuera con esa lluvia. Entra. Tu visita es grata.' WHERE `ID`=15458;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흉포한 테로나방들과 저는 여기 있어도 괜찮습니다. 아, 예. 고맙습니다.', `MaleText_loc4`='巨蛾和我在这里很和谐，谢谢你。', `MaleText_loc5`='我和兇惡的泰洛飛蛾在這裡相安無事，謝謝你。', `MaleText_loc7`='Las teropolillas sañosas y yo estamos muy bien aquí tranquilos, gracias.' WHERE `ID`=15459;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='푸른 형제들이 최고의 위치에 올랐다!', `MaleText_loc4`='蓝色兄弟最高！', `MaleText_loc5`='憂鬱兄弟至上!', `MaleText_loc7`='¡El reinado supremo de los hermanos azules!' WHERE `ID`=15460;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 여러분! 전투가 시작될 것입니다! 자비를 모르는 수렁피 쌍둥이들과 $n의 대결입니다!', `MaleText_loc4`='战斗马上开始！无情的暗血双子对阵$n！', `MaleText_loc5`='打鬥就要開始了!殘酷的黑暗之血雙子對$n!', `MaleText_loc7`='¡La batalla está a punto de comenzar! ¡Los despiadados gemelos Sangreoscura contra $n!' WHERE `ID`=15461;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='믿을 수가 없군요! $n|1이;가; 수렁피 쌍둥이를 이겼습니다!', `MaleText_loc4`='难以置信！$n击败了暗血兄弟！', `MaleText_loc5`='不可思議!$n擊敗了黑暗之血雙子!', `MaleText_loc7`='¡Increíble! ¡$n ha derrotado a los gemelos Sangreoscura!' WHERE `ID`=15462;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꼬마 새, 이리 와라! 한 번 놀자!', `MaleText_loc4`='出来，小家伙们！穆格高克要跟你们玩！', `MaleText_loc5`='出來啊，小鳥!穆格苟克想和你玩玩!', `MaleText_loc7`='¡Salid, pajaritos! ¡Mug''gok querer jugar!' WHERE `ID`=15463;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 기분 망치지 마라, 새대가리!', `MaleText_loc4`='穆格高克一点都不疼，鸟人！', `MaleText_loc5`='不要傷了穆格苟克的心，鳥人!', `MaleText_loc7`='¡No herir sentimientos Mug''gok, hombres pájaro!' WHERE `ID`=15464;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아! 새들 늘 그런 식이지! 무그고크 새 친구 생겼다!', `MaleText_loc4`='很好！鸟人们走开！穆格高克找到了一个新朋友！', `MaleText_loc5`='很好!鳥人就是那樣!穆格苟克有新朋友了!', `MaleText_loc7`='¡Perfecto! ¡Los pájaros estar por allí! ¡Mug''gok encontrar nuevos amigos!' WHERE `ID`=15465;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일어나라, 나의 형제들이여. 일어나 싸워라!', `MaleText_loc4`='复活吧，我死去的兄弟们！准备战斗！', `MaleText_loc5`='各就各位!準備戰鬥!', `MaleText_loc7`='¡Levántense, hermanos caídos! ¡Tomen forma y luchen!' WHERE `ID`=15466;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여러분, 칼날 산맥에서 들려오는 환호 소리가 파괴의 군주 로크다르를 불러 왔습니다! $n|1이;가; 목숨을 걸고 싸우는 이번 대전을 눈을 크게 뜨고 지켜보십시오.', `MaleText_loc4`='为从刀锋山来的裂石之王洛卡达尔欢呼吧！$n正在为$g他的:她的;生命而战！', `MaleText_loc5`='來自劍刃山脈的『碎裂領主』洛克達!$n加入了$g他的:她的;生命搏鬥。', `MaleText_loc7`='¡De la montaña de Filospada, llega el Señor Hendido, Rokdar! $n luchará en la batalla de su vida.' WHERE `ID`=15467;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로크다르 $n 부숴버린다!', `MaleText_loc4`='洛卡达尔要揍扁弱小的$n！', `MaleText_loc5`='洛克達要粉碎渺小的$n!', `MaleText_loc7`='¡ROKDAR DESTROZAR ENCLENQUE $n!' WHERE `ID`=15468;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 대전에서 또 승리를 거뒀습니다!', `MaleText_loc4`='$n又一次胜利了！', `MaleText_loc5`='$n再一次獲勝!', `MaleText_loc7`='¡$n sale $gvictorioso:victoriosa; una vez más!' WHERE `ID`=15469;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로크다르 정말 멍청했다! 모고르가 저것보단 훨씬 잘 싸울 수 있었는데!', `MaleText_loc4`='真没劲！穆戈尔更厉害！', `MaleText_loc5`='搞什麼!莫古可以打一場比這更好的仗!', `MaleText_loc7`='¡Eso ha sido una basura! ¡Mogor podría luchar mucho mejor!' WHERE `ID`=15470;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 뒤틀린 드레나이의 시체 한 구가 있습니다. 이상하게도 돌연변이 나방이 죽음의 원인으로 보이지는 않습니다.$B$B이 드레나이는 죽음의 순간 필사적으로 한쪽 손을 내민 것처럼 보이며 그 바로 옆에는 이상한 물체가 보입니다. 이것이 그의 죽음과 어떤 관련이 있지 않을까요?', `MaleText_loc4`='一个破碎者的尸体躺在这里。神秘的是，他死亡的原因并不是由于那变异的蛾子。$B$B也许是因为他手上的奇怪物品？', `MaleText_loc5`='一個破碎者的屍體躺在那裡。很神秘的是，死亡的原因不像是因為那些突變的飛蛾。$B$B也許還有某種神秘的東西造成這件事情?', `MaleText_loc7`='Aquí yace el cadáver de un Tábido. Curiosamente, la causa de muerte no parece ser una polilla mutante.$B$BQuizás tenga algo que ver con el extraño objeto que se encuentra al lado de su mano extendida.' WHERE `ID`=15471;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가까이... 이리 가까이 오너라... 이 공포의 군주께서 어떤 힘이 있는지 맛보게 해주마!', `MaleText_loc4`='靠近点……再靠近点……看看虚空给我们带来了什么！', `MaleText_loc5`='靠近一點...再近一點...看看虛無的厲害!', `MaleText_loc7`='Más cerca... Acércate más... ¡Mira lo que trae el vacío!' WHERE `ID`=15472;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 알 수 없는 곳에서 온 공허의 군주인 스크라가스가 나타났습니다! 과연 $n|1이;가; 저 보이드의 맹공격에서 살아남을 수 있을까요?', `MaleText_loc4`='来自未知世界的强者，瑟克拉加斯！$n能否在虚空能量的冲击下幸存呢？', `MaleText_loc5`='未知的聲音:史卡拉克斯!$n可能從虛無能量的猛攻下生還嗎?', `MaleText_loc7`='De origen desconocido, ¡este es Skra''gath! ¿Sobrevivirá $n al ataque de las energías de la nada?' WHERE `ID`=15473;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번 대전 모고르 전혀 감탄 안 했다! 스크라가스는 공기와 어둠의 존재다! 흐느적대는 오크 어린애 같았다!', `MaleText_loc4`='穆戈尔没有印象！瑟克拉加斯是由空气和暗影组成的！像被压扁的兽人一样软！', `MaleText_loc5`='莫古不以為意!史卡拉克斯是空氣和幻像做的!就像黏糊糊的獸人一樣軟!', `MaleText_loc7`='¡Mogor no impresionado! ¡Skra''gath se hizo de aire y sombras! ¡Blando como los enclenques orquitos!' WHERE `ID`=15474;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 모두가 기다리던 순간이 왔습니다! 전쟁망치 용사가 수주일 만에 처음으로 피의 투기장에서 그의 실력을 뽐낼 것입니다! $n|1이;가; 전쟁망치 용사가 싸웠던 다른 상대들처럼 쉽게 무릎을 꿇게 될까요? 숨죽이고 지켜보도록 하지요...', `MaleText_loc4`='这是我们最为期待的时刻！战槌勇士要开始他本周在鲜血竞技场的第一场表演了！$n会不会像这位勇士的其他对手那样被轻松打败呢？我们拭目以待……', `MaleText_loc5`='這是我們一直在等待的時刻!戰槌勇士就要在血色競技場展開他幾週內的第一次演出了!$n會像其他挑戰勇士的人一樣輕易地倒下嗎?我們等著瞧吧...', `MaleText_loc7`='¡Este es el momento que todos esperábamos! El campeón de Mazo de Guerra vuelve a El Círculo de Sangre después de semanas. ¿Será capaz $n de derrotarlo tan fácilmente como a los demás? Ahora lo veremos...' WHERE `ID`=15475;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 도전자의 몸뚱어리를 서서히 분해해 놓겠다... 한 조각씩!', `MaleText_loc4`='我要把这个挑战者撕成碎片！', `MaleText_loc5`='我會把這個挑戰者一塊一塊的撕裂...一塊一塊!', `MaleText_loc7`='Pedazo a pedazo, destrozaré a este aspirante... ¡PEDAZO A PEDAZO!' WHERE `ID`=15476;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 뭐지? 불가능하다! 너 지금 모고르와 싸우는 거다! 널 부숴 버리겠다!', `MaleText_loc4`='什么！？不可能！！你要和穆戈尔战斗了！穆戈尔杀啊！！！', `MaleText_loc5`='什麼!?不可能!!你和莫古現在打一架!莫古殺你!', `MaleText_loc7`='¿¡QUÉ!? ¡¡ESO NO POSIBLE ES!! ¡Tú luchar contra Mogor ahora! ¡Mogor destrozar!' WHERE `ID`=15477;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 진정한 영웅의 솜씨 맛 봐라! 도망갈 기회를 준다. 널 파괴... 박살... 널 죽이기 전에 도망가는 게 좋을 거다!', `MaleText_loc4`='现在你将面对真正的冠军！我会给你一个逃跑的机会，小家伙。在穆戈尔把你杀死之前逃跑吧！', `MaleText_loc5`='現在你面對真正的勇士!我給你機會逃跑小傢伙。趁莫古開始毀滅之前逃跑...趁莫古開始殺人之前快逃吧!', `MaleText_loc7`='¡Ahora te enfrentas a un verdadero campeón! Te doy oportunidad de escapar, pequeñín. Corre antes de que Mogor... Antes de que... ¡Antes de que Mogor MATAR!' WHERE `ID`=15478;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더는 도망칠 기회 없다! 오우거의 빚 갚을 시간이다!', `MaleText_loc4`='没有机会了！现在你要付出代价了！', `MaleText_loc5`='沒有機會了!現在你要付錢給那個巨魔!', `MaleText_loc7`='¡No más oportunidades! ¡Ahora pagas al ogro!' WHERE `ID`=15479;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모고르가 자네에게 도전했네. 자네는 그 도전을 받아들여야만 해! 싸울 준비가 되면 투기장으로 들어가게.', `MaleText_loc4`='穆戈尔向你挑战。你必须同意！进入竞技场，准备战斗吧。', `MaleText_loc5`='莫古向你挑戰。你必須接受!如果你準備好打鬥就進入競技場。', `MaleText_loc7`='Mogor te ha retado. ¡Debes aceptar! Entra en el círculo cuando estés $glisto:lista; para luchar.' WHERE `ID`=15480;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오!!! 피의 투기장의 역사상 처음으로 모고르가 대전 상대 지목권을 사용했습니다! 전쟁으로 파괴된 이 땅에서 $n|1이;가; 전쟁망치 일족의 영웅 모고르와 처절한 전투를 벌이게 됩니다!', `MaleText_loc4`='有史以来，穆戈尔第一次在鲜血竞技场作战！在这个回合，$n将会面对穆戈尔，战槌英雄！', `MaleText_loc5`='血色競技場有史以來第一次，莫古要展開他的拳擊之戰!在這塊受戰爭蹂躪的土地上，$n將挑戰戰槌的英雄，莫古!', `MaleText_loc7`='¡Por vez primera en la historia de El Círculo de Sangre, Mogor ha decidido ejercer su derecho a la batalla! ¡En este suelo destrozado por la tierra, $n se enfrentará a Mogor, héroe de Mazo de Guerra!' WHERE `ID`=15481;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 전쟁망치 일족의 영웅 모고르를 물리치고야 말았군요! $n에게 박수를 보내 주십시오!', `MaleText_loc4`='$n打败了战槌英雄穆戈尔！大家为$n欢呼吧！', `MaleText_loc5`='$n擊敗了戰槌的英雄，莫古!眾人為$n歡呼!', `MaleText_loc7`='¡$n ha derrotado al héroe de Mazo de Guerra, Mogor! ¡Gloria a $n!' WHERE `ID`=15482;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으아악! 더는 친절한 오우거 없다! 너 감히 날 아프게 했다!!', `MaleText_loc4`='我发怒了！你把穆戈尔打疼了！！', `MaleText_loc5`='不要再有好巨魔了!你傷了莫古!', `MaleText_loc7`='¡Ya no ogro bueno! ¡Tú daño a Mogor!' WHERE `ID`=15483;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 오크 해골을 담은 자루처럼 쓰러졌습니다!', `MaleText_loc4`='$n瘫软地倒下了！', `MaleText_loc5`='$n像一袋獸人頭顱一樣倒了下來!', `MaleText_loc7`='¡$n se ha desplomado como un saco de huesos!' WHERE `ID`=15484;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n에게 남은 것은 바닥의 붉은 핏자국뿐입니다!', `MaleText_loc4`='$n留下来的只不过是地上的一大块红色污点！', `MaleText_loc5`='$n所剩的就是地上的一塊紅色污跡!', `MaleText_loc7`='¡Todo lo que queda de $n es esa mancha roja del suelo!' WHERE `ID`=15485;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오시게, 용사여! 검투사를 정식 직업으로 삼고 싶은 생각은 없나? 우리가 힘을 합치면 돈방석에 올라앉을 수 있단 말이지.', `MaleText_loc4`='你好啊，勇士！你想过作一个全职的角斗士吗？你和我搭档肯定可以赚很多钱。', `MaleText_loc5`='嗨，勇士!你想過做個全職的神鬼戰士嗎?你和我可以大撈一筆。', `MaleText_loc7`='¡Saludos, $gcampeón:campeona;! ¿Nunca te has planteado trabajar de gladiador a tiempo completo?' WHERE `ID`=15486;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 무슨 뜻인가요?!', `MaleText_loc4`='这是什么意思？', `MaleText_loc5`='這是什麼意思?!', `MaleText_loc7`='¡¿Qué significa esto?!' WHERE `ID`=15487;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 아주 아주... 아주 바빠요! 무슨 일인가요?', `MaleText_loc4`='很忙……很忙！什么？', `MaleText_loc5`='非常忙...非常忙!什麼?', `MaleText_loc7`='Muy ocupado... ¡Muy ocupado! ¿Qué?' WHERE `ID`=15488;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엠푸르, 제가 묻는 말에 대답하십시오! 그렇지 않으면...', `MaleText_loc4`='埃博尔，你是想马上把我要知道的东西告诉我，还是吃点苦头？', `MaleText_loc5`='安普爾，你要告訴我所有想知道的一切，否則後果自負!', `MaleText_loc7`='¡Empoor, me vas a contar lo que quiero saber, o si no...!', `FemaleText_loc1`='엠푸르, 제가 묻는 말에 대답하십시오! 그렇지 않으면...', `FemaleText_loc4`='埃博尔，你是想马上把我要知道的东西告诉我，还是吃点苦头？', `FemaleText_loc5`='安普爾，你要告訴我所有想知道的一切，否則後果自負!', `FemaleText_loc7`='¡Empoor, me vas a contar lo que quiero saber, o si no...!' WHERE `ID`=15489;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어흑흑... 그렇다고 날 죽을 정도로 두들겨 패다니... 원하는 게 뭡니까?', `MaleText_loc4`='现在我被打得就差一口气了，你想要什么？', `MaleText_loc5`='既然我已被打的性命垂危，你想怎麼樣呢?', `MaleText_loc7`='¿Ahora que me han pegado en todas partes, qué quieres?' WHERE `ID`=15490;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 이제 갑니다!', `MaleText_loc4`='我现在就离开！', `MaleText_loc5`='我要離開了!', `MaleText_loc7`='¡Ahora me marcho!' WHERE `ID`=15491;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 마지막으로 할 일이 있다면 그것은 이 학살의 진상을 철저히 파헤치는 것이오!', `MaleText_loc4`='我们无论如何都要彻底调查这次惨案！', `MaleText_loc5`='如果這場大屠殺是我們最不可能做的事，我們會追根究底!', `MaleText_loc7`='¡Averiguaremos lo que ha causado esta masacre aunque sea lo último que hagamos!' WHERE `ID`=15492;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cffffff00호드가 할라아를 차지했습니다!|r', `MaleText_loc4`='|cffffff00部落正在夺取哈兰的控制权！|r', `MaleText_loc5`='|cffffff00部落獲得哈剌的控制權!|r', `MaleText_loc7`='|cffffff00¡La Horda va a conseguir controlar Halaa!|r' WHERE `ID`=15493;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cffffff00얼라이언스가 할라아를 차지했습니다!|r', `MaleText_loc4`='|cffffff00联盟正在夺取哈兰的控制权！|r', `MaleText_loc5`='|cffffff00聯盟獲得哈剌的控制權!|r', `MaleText_loc7`='|cffffff00¡La Alianza va a conseguir controlar Halaa!|r' WHERE `ID`=15494;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙습니다, $n! 이 정신 나간 새들로부터 벗어날 수 있다는 희망을 포기하려고 했었습니다!', `MaleText_loc4`='$n，谢谢你！我原本以为我死定了！', `MaleText_loc5`='謝謝你，$n!我已經放棄從這些瘋狂的鳥腦裡被拯救的任何希望了!', `MaleText_loc7`='Gracias, $n. Ya había perdido la esperanza de que me rescataran de esos cabeza de chorlito.' WHERE `ID`=15495;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 당신에게 큰 빚을 졌습니다. 이제 이 커다란 둥지에서 죽는구나 싶었는데!', `MaleText_loc4`='我欠你一条命，$n。我都开始想自己可能会在这个超大的鸟巢中死掉了！', `MaleText_loc5`='我欠你一份人情，$n。我開始覺得我會死在這生長過度的安樂窩!', `MaleText_loc7`='Estoy en deuda contigo, $n. Ya estaba pensando que iba a morir en ese nido gigante.' WHERE `ID`=15496;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='불타는 군단과의 싸움을 도와주신다면 정말 고맙겠습니다. 여군주 제이나 프라우드무어가 전방에서 그대와 같은 용사들의 도움을 기다리고 있습니다.', `FemaleText_loc4`='非常感谢你来支援我们对抗燃烧军团的战斗。吉安娜·普罗德摩尔女士正需要你的帮助。', `FemaleText_loc5`='我們非常感激你幫助我們對抗燃燒軍團。珍娜·普勞德摩爾女士在前線可能需要你的幫助。', `FemaleText_loc7`='Tu ayuda en la lucha contra la Legión Ardiente sería de lo más apreciada. Lady Jaina Valiente podría utilizar tu ayuda en las primeras líneas.' WHERE `ID`=15497;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그대가 불타는 군단과의 전투를 계속해서 도와주셨으면 합니다. 여기서 서쪽에 있는 스랄의 야영지로 가서 그를 도와주십시오.', `FemaleText_loc4`='非常感谢你继续帮助我们对抗燃烧军团。在这里的西面就是萨尔的营地，他可能会需要你们。', `FemaleText_loc5`='我們感謝你持續幫助對抗燃燒軍團。西邊的索爾營地可能會需要你的幫助。', `FemaleText_loc7`='Tu continua ayuda contra la Legión Ardiente seguiría siendo apreciada. Thrall podría seguir utilizando tu ayuda en su campamento, al oeste de aquí.' WHERE `ID`=15498;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$C|1이여;여;, 우리가 두려워하던 시간이 머지 않았습니다. 아키몬드가 놀드랏실에 도착해서 세계수의 힘을 흡수하려고 하고 있습니다. 말퓨리온에게 그의 계획을 진행할 수 있는 시간을 벌어줘야 합니다. 따라서 우리는 상상하기 힘든 일을 해야만 하는 것입니다. 나와 내 군대가 불타는 군단이 산꼭대기에 올라가지 못하게 막고 있는 동안 그대는 아키몬드를 직접 공격하십시오.', `FemaleText_loc4`='噩梦般的时刻就在眼前了，$c。阿克蒙德成功地靠近了诺达希尔，并开始吸取世界之树的能量。玛法里奥需要更多时间来准备他的计划，我们必须尽全力完成这几乎不可能的任务。在我的部队抵抗潮水般的燃烧军团部队时，你必须直接进攻阿克蒙德。', `FemaleText_loc5`='我們一直以來害怕的時刻即將到來，$C。阿克蒙德已經到達諾達希爾，而且開始吞食世界之樹的能量。瑪法里恩需要更多時間來實行他的計畫，所以我們一定要做到不可能的事。在我的軍隊拖延燃燒軍團逼近山頂時，你一定要直接攻擊阿克蒙德。', `FemaleText_loc7`='Se acerca el momento que tanto temíamos, $c. Archimonde ha conseguido llegar hasta Nordrassil y está empezando a devorar las energías del Árbol del Mundo. Malfurion necesita más tiempo para que su plan funcione, así que tendremos que hacer lo impensable: hay que atacar a Archimonde directamente, mientras mis tropas se encargan del grueso de la Legión Ardiente que se acerca a la cima.' WHERE `ID`=15499;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절 구하러 오셨습니까? 어서 이 족쇄를 풀어 주십시오!', `MaleText_loc4`='你是过来救我的吗？快点，救我出去！', `MaleText_loc5`='你是來救我的嗎?快，幫我解開這些鎖鍊!', `MaleText_loc7`='¿Has venido a rescatarme? ¡Rápido, quítame estas cadenas!' WHERE `ID`=15500;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='족쇄를 풀어드릴 테니 잠시만 기다리십시오.', `MaleText_loc4`='我马上就会把你救出来。', `MaleText_loc5`='我很快就會幫你解開它們了。', `MaleText_loc7`='Te sacaré de ahí en un momento.', `FemaleText_loc1`='족쇄를 풀어드릴 테니 잠시만 기다리세요.', `FemaleText_loc4`='我马上就会把你救出来。', `FemaleText_loc5`='我很快就會幫你解開它們了。', `FemaleText_loc7`='Te sacaré de ahí en un momento.' WHERE `ID`=15501;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 괴물 같은 새들이 돌아오기 전에 어서 이 족쇄를 풀어주십시오!', `MaleText_loc4`='快点，在那帮鸟人回来之前把我从这些锁链中解救出来！', `MaleText_loc5`='快點在那些鳥人回來前幫我把這些鎖鍊解開!', `MaleText_loc7`='¡Corre! ¡Sácame de estas cadenas antes de que vuelvan los hombres pájaro!' WHERE `ID`=15502;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='족쇄를 풀어 드릴 테니 잠시만 기다리십시오.', `MaleText_loc4`='我马上就会把你救出来。', `MaleText_loc5`='我很快就會幫你解開那些鎖鍊。', `MaleText_loc7`='Te sacaré de ahí en un momento.', `FemaleText_loc1`='족쇄를 풀어 드릴 테니 잠시만 기다리십시오.', `FemaleText_loc4`='我马上就会把你救出来。', `FemaleText_loc5`='我很快就會幫你解開那些鎖鍊。', `FemaleText_loc7`='Te sacaré de ahí en un momento.' WHERE `ID`=15503;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 빨리! 더 빨리 움직여, 이 쓸모없는 녀석들!', `MaleText_loc4`='快点！再快点！你这没用的家伙！', `MaleText_loc5`='快一點!叫你無用的小廢物快一點!', `MaleText_loc7`='¡Más rápido! ¡Más rápido, enanos inútiles!' WHERE `ID`=15504;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불타는 군단의 영광을 위해!', `MaleText_loc4`='为了军团的荣耀而战！', `MaleText_loc5`='為了軍團的榮耀!', `MaleText_loc7`='¡POR LA GLORIA DE LA LEGIÓN!' WHERE `ID`=15505;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 살점을 발라내 주겠다!', `MaleText_loc4`='恶魔会把你们碎尸万断！', `MaleText_loc5`='戴摩斯會從你的骨頭上把你的肉給剝下來!', `MaleText_loc7`='¡Demos arrancará la carne de sus huesos!' WHERE `ID`=15506;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 용광로는 새로운 시대를 열 것이다! 내가 바로 용광로의 주인이다!', `MaleText_loc4`='这座铸魔基地将会铸造出一个新的纪元！迪摩斯是不可战胜的！', `MaleText_loc5`='這個煉冶場會引進全新的世代!是戴摩斯在掌控它!', `MaleText_loc7`='¡En esta forja se dará forma a una nueva era! ¡Demos lo ordena!' WHERE `ID`=15507;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 용광로는 새로운 시대를 열 것이다! 내가 바로 용광로의 주인이다!', `MaleText_loc4`='这座铸魔基地将会铸造出一个新的纪元！迪摩斯是不可战胜的！', `MaleText_loc5`='這個煉冶場會引進全新的世代!是戴摩斯在掌控它!', `MaleText_loc7`='¡En esta forja se dará forma a una nueva era! ¡Demos lo ordena!' WHERE `ID`=15508;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간의 선술집에 오신 것을 환영합니다!', `MaleText_loc4`='欢迎来到时光旅店！', `MaleText_loc5`='歡迎來到時光之穴!', `MaleText_loc7`='¡$gBienvenido:Bienvenida; a las Tabernas del Tiempo!' WHERE `ID`=15509;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피곤함에 지친 당신의 발에게 쉴 시간을 주십시오. 이 세계의 모든 시간이 이곳에 머물고 있습니다...', `MaleText_loc4`='放松你疲惫的双腿，我们拥有整个世界的时间……', `MaleText_loc5`='讓你疲憊的雙腳休息一下，我們有的是時間...', `MaleText_loc7`='Deja que reposen tus pies cansados. Tenemos todo el tiempo del mundo...' WHERE `ID`=15510;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐, 마실 거라도 드릴까요? 다른 어느 곳과도 비교할 수 없을 만큼 오랫동안 숙성된 술이 있습니다!', `MaleText_loc4`='我可以请你喝一杯吗？我保证这是真正的陈年老酒！', `MaleText_loc5`='要來一杯嗎?我保證沒有什麼比這更陳更香的!', `MaleText_loc7`='¿Puedo ofrecerte algo de beber? ¡Te prometo que será de un muy buen año!' WHERE `ID`=15511;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='축하합니다! 오늘 우리는 위대한 승리를 쟁취했습니다.', `FemaleText_loc4`='祝贺你！今天你赢得了一场伟大的胜利。', `FemaleText_loc5`='恭喜!今天我們贏得了一場偉大的勝利。', `FemaleText_loc7`='¡Enhorabuena! Hoy se ha logrado una gran victoria.' WHERE `ID`=15512;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세상의 끝 선술집에서 파는 것들은 견줄 수도 없을 만큼 훌륭한 물건이 있답니다. 전 제가 파는 물건에 관심을 보이는 손님들이 어떤 유형이고, 또 어떤 분야에 특히 마음이 끌려 하는지 발견해냈죠.$B$B제가 주로 취급하는 물건은 멀리 광활한 세계에서 입수한 진귀한 기술용품입니다. 때때로 아주 희귀한 물건을 한두 가지쯤 내놓기도 하지요.$B$B그런데 어떤 물건을 찾으시는지요?', `MaleText_loc4`='天涯旅店没有什么我想要的。不过，这里却能吸引许多对我在售卖的商品十分感兴趣的客户。$B$B我专门研究稀奇的工程学物品，已经获得了很大的成就。有时候，我这里可能还会有一两件奇货出售。$B$B怎么样，有什么你感兴趣的吗？', `MaleText_loc5`='世界的盡頭小酒館不提供我族人任何物品。不過，我發現它會吸引對我賣的東西有興趣的顧客。$B$B我專賣從世界各地取得的特殊工程學物品。有時候我還有一兩個稀有的物品可供購買。$B$B你對我的物品有什麼興趣嗎?', `MaleText_loc7`='La Taberna del Fin del Mundo no tiene nada que ofrecer a los de mi especie. Sin embargo, creo que atrae el tipo de clientela interesada en lo que tengo en venta.$B$BMe especializo en productos de ingeniería exóticos adquiridos en lugares lejanos. De vez en cuando hasta tengo un par de cosas raras en venta.$B$B¿Qué podría interesarte?' WHERE `ID`=15514;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='투렘에서 상자를 찾아내는 일에 운이 따라주던가요?', `MaleText_loc4`='找到图雷姆的那只箱子了吗？', `MaleText_loc5`='在杜瑞追蹤盒子的進展如何?', `MaleText_loc7`='¿Tuviste suerte en tu búsqueda de esa caja en Tuurem?' WHERE `ID`=15515;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서쪽을 바라보면 뭐가 보이는가, 필멸의 존재여?', `MaleText_loc4`='当你往西边看的时候，你看到了什么，凡人？', `MaleText_loc5`='當你望向西邊，你看見了什麼，凡人?', `MaleText_loc7`='¿Qué ves cuando miras al oeste, mortal?' WHERE `ID`=15516;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뒤틀린 강철이 보이고 갈라진 대지의 냄새가 납니다.', `MaleText_loc4`='我看到了扭曲的钢铁，碎裂的大地。', `MaleText_loc5`='我看見扭曲的鋼鐵、嗅到了分裂的大地。', `MaleText_loc7`='Veo acero retorcido y huelo a tierra herida.', `FemaleText_loc1`='뒤틀린 강철이 보이고 갈라진 대지의 냄새가 납니다.', `FemaleText_loc4`='我看到了扭曲的钢铁，碎裂的大地。', `FemaleText_loc5`='我看見扭曲的鋼鐵、嗅到了分裂的大地。', `FemaleText_loc7`='Veo acero retorcido y huelo a tierra herida.' WHERE `ID`=15517;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그게 뭘 말하는지 아는가? 바로 침략의 조짐이라네.$B$B그렇지, 주인님께서 차원문을 봉인하신 건 현명하신 판단이었어. 하지만 그 때문에... 이걸 어떻게 표현하면 좋나? 주인님께서는 초점을 잃으셨지. 그렇네... 주의력 말이야.$B$B그로 인해서 불타는 군단이 기회를 잡은 것이지. 이제 그들이 모습을 드러내고 나날이 숫자가 불어나고 있네.', `MaleText_loc4`='你知道我看到了什么？一个入侵的先兆。$B$B虽然主人非常睿智地封印了传送门，但他失去了他的……我该怎么来表达这个？他的专注。是的……专注。$B$B因此，军团抓住了这个机会。他们现在渗透了进来，数量在一天天地膨胀。', `MaleText_loc5`='你知道我看見什麼嗎?一個入侵的前兆。$B$B是，大師將傳送門密封起來是很聰明，但他也自此失去他的...我該怎麼說?大師失去了他的焦點。是的...焦點。$B$B因為如此，軍團抓住了機會。他們開始滲透，逐日壯大他們的數量。', `MaleText_loc7`='¿Sabes lo que veo yo? Un preludio de la invasión.$B$BSí, el maestro hizo bien en sellar los portales, pero luego se le fue un poco... ¿Cómo podría decirlo...? Digamos que perdió la concentración. Eso. La concentración.$B$BLa Legión supo bien aprovechar esa ventaja. Ahora han conseguido infiltrarse, y cada día que pasa hay más.' WHERE `ID`=15518;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불타는 군단이라고요?', `MaleText_loc4`='军团？', `MaleText_loc5`='軍團?', `MaleText_loc7`='¿Legión?', `FemaleText_loc1`='불타는 군단이라고요?', `FemaleText_loc4`='军团？', `FemaleText_loc5`='軍團?', `FemaleText_loc7`='¿Legión?' WHERE `ID`=15519;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불타는 군단. 잔인한 악마들. 나는 그대 얼굴 앞에 들이민 손이 보이는 만큼 그들의 모습이 확실하게 보인다네. 그러니까 그들을 정확하게 볼 수 있었다는 말이지.$B$B불타는 군단이 돌아오면서 새로운 음모가 시작되었네. 정상적인 환경이라면 난 먼 곳에서도 악마의 존재를 느낄 수가 있지.$B$B<얼굴을 찡그리는 알트루이스>', `MaleText_loc4`='燃烧军团。恶魔。我可以清晰地看到他们，就像你能清晰地看到自己的双手那样。以前，我总是能一眼看清他们。$B$B随着燃烧军团的回归，他们正在进行着新的诡计。在通常的情况下，我可以感觉到千里之外的恶魔。$B$B<奥图里斯的面孔扭曲了一下。>', `MaleText_loc5`='燃燒軍團。惡魔。我能清楚的看見他們就像你可以看見你自己的雙手一樣。只不過，我是過去可以清楚的看見他們。$B$B軍團帶著新的陰謀詭計回來。在正常的情況下，我可以感應到幾千步以外的惡魔。$B$B<奧翠司做了個厭惡的鬼臉。>', `MaleText_loc7`='La Legión Ardiente. Demonios. Los veo tan claramente como tú te verías la mano delante de la cara. Bueno, los veía claramente.$B$BLa vuelta de la Legión, ha traído nuevos estratagemas. En circunstancias normales, puedo sentir la presencia de un demonio a miles de leguas.$B$B<Altruis tuerce el gesto.>' WHERE `ID`=15520;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 지금은 어떻습니까?', `MaleText_loc4`='现在呢？', `MaleText_loc5`='那現在呢?', `MaleText_loc7`='¿Y ahora?', `FemaleText_loc1`='그럼 지금은 어떠세요?', `FemaleText_loc4`='现在呢？', `FemaleText_loc5`='那現在呢?', `FemaleText_loc7`='¿Y ahora?' WHERE `ID`=15521;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들이 나를 피하고 있어 방어선 너머가 보이지 않는다네. 그들은 위치가 탐지되는 걸 막으려고 수호물을 설치했지.$B$B<서쪽을 가리키는 알트루이스>$B$B그들은 어떤 것도 두려워하지 않는 우리를 무서워하지. 그런 힘을 얻기 위해 치르는 대가는 엄청난 것이야... 많은 것을 희생해야 한다네.', `MaleText_loc4`='他们躲避着我。我的视野不能穿越他们的防线。他们部署了结界来避免我的窥探。$B$B<奥图里斯指了指西边。>$B$B他们畏惧我们，因为他们知道我们无所畏惧。换取这种力量需要付出巨大的代价，惨痛的牺牲。', `MaleText_loc5`='他們難倒我了。我不能越過他們的防禦。他們已經配置了監督來阻止偵測。$B$B<奧翠司往西邊指。>$B$B他們知道我們無所畏懼所以他們很怕我們。這樣的力量付出的代價是很大的，犧牲無數。', `MaleText_loc7`='Me evitan. No puedo ver a través de sus defensas. Han colocado guardas para dificultar la detección.$B$B<Altruis señala al oeste.>$B$BNos temen porque saben que no tememos nada. El coste de un poder así es grande; los sacrificios, muchos.' WHERE `ID`=15522;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 지금은 어떻게 그들을 봅니까?', `MaleText_loc4`='你现在要怎么才能看到他们？', `MaleText_loc5`='你現在要拿他們怎麼辦?', `MaleText_loc7`='¿Cómo los ves ahora?', `FemaleText_loc1`='그럼 지금은 어떻게 그들을 보세요?', `FemaleText_loc4`='你现在要怎么才能看到他们？', `FemaleText_loc5`='你現在要拿他們怎麼辦?', `FemaleText_loc7`='¿Cómo los ves ahora?' WHERE `ID`=15523;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<고개를 돌리며 미소를 짓는 알트루이스>$B$B보지 못한다네.$B$B<비룡 네스란다무스를 가리키는 알트루이스>$B$B저 괴철로 기지에서 저들이 만들고 있는 물건이 완성되기 전에 막아야 하네.', `MaleText_loc4`='<奥图里斯转向你笑了笑。>$B$B我不行。$B$B<奥图里斯指了指他的坐骑，奈瑟兰达姆斯。>$B$B我们必须在这些铸魔营地有能力完成它们正在建造的东西之前阻止他们。', `MaleText_loc5`='<奧翠司轉頭面向你並微笑。>$B$B我不這麼認為。$B$B<奧翠司指著他的駿馬，尼斯蘭德瑪斯。>$B$B不管他們正在建造什麼東西，我們一定要在這些煉冶場完成之前阻止他們。', `MaleText_loc7`='<Altruis se vuelve hacia ti y sonríe.>$B$BYo no.$B$B<Altruis señala a su corcel, Nethrandamus.>$B$BDebemos detenerlos antes de que esos campamentos Forja terminen lo que quiera que hayan empezado a construir.' WHERE `ID`=15524;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='괴철로 기지요?', `MaleText_loc4`='铸魔营地？', `MaleText_loc5`='煉冶場?', `MaleText_loc7`='¿Campamentos forja?', `FemaleText_loc1`='괴철로 기지요?', `FemaleText_loc4`='铸魔营地？', `FemaleText_loc5`='煉冶場?', `FemaleText_loc7`='¿Campamentos forja?' WHERE `ID`=15525;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 나그란드의 아름다운 주변 경관을 망치는 구조물을 부르는 이름이지. 불타는 군단은 그 이동식 괴철로 기지에서 대량 파괴 무기를 만들려고 모아그와 간아그를 고용했지. 그들이 이곳 나그란드에 그걸 지어서 뭘 하든 신경 쓰지 않도록 하세!$B$B그대는 내 눈이 될 것이며 그대의 무기에는 내 분노가 담길 것일세.', `MaleText_loc4`='那是他们的这些邪恶的建筑物的名称。燃烧军团雇用了莫尔葛恶魔和甘尔葛恶魔，在这些营地中建造具备大规模杀伤能力的武器。有了结界的存在，我就不能发现他们正在纳格兰建造些什么！$B$B你将是我的眼睛。你的武器将是我的愤怒。', `MaleText_loc5`='那就是這些把風景弄的亂七八糟的結構。軍團雇用了莫阿格和甘納格在這些活動煉冶場建造大規模毀滅性武器。我們不用知道他們到底想在納葛蘭這裡建造些什麼!$B$B你們就是我的眼睛。你們的武器就是我的狂怒。', `MaleText_loc7`='Así es como se llaman esas estructuras que ensucian el paisaje. La Legión ha empleado a los Mo''arg y Gan''arg para construir armas de destrucción masiva en esos campamentos Forja móviles. ¡Que no descubramos lo que intentan construir aquí en Nagrand!$B$BTú serás mis ojos. Tus armas serán mi furia.' WHERE `ID`=15526;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 젠장, 또 당신입니까! 갈길이나 가세요!', `MaleText_loc4`='啊，怎么又是你！滚开！', `MaleText_loc5`='喔不，怎麼又是你!走開!', `MaleText_loc7`='¡Oh, no, tú otra vez no! ¡Vete!' WHERE `ID`=15527;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이것은 불꽃날개 거점의 소유다. 그 더러운 손을 가까이 대지 마라!', `MaleText_loc4`='这是属于火翼岗哨的！你休想碰它！', `MaleText_loc5`='那是火翼崗哨的財產。離它遠一點!', `MaleText_loc7`='Eso es la propiedad Alto Ala de Fuego. ¡Aléjate de ahí!', `FemaleText_loc1`='이것은 불꽃날개 거점의 소유다. 그 더러운 손을 가까이 대지 마라!', `FemaleText_loc4`='这是属于火翼岗哨的！你休想碰它！', `FemaleText_loc5`='那是火翼崗哨的財產。離它遠一點!', `FemaleText_loc7`='Eso es la propiedad Alto Ala de Fuego. ¡Aléjate de ahí!' WHERE `ID`=15528;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='몹시 화가 난 %s|1이;가; 엄청난 힘으로 식물학자 바이트를 강타합니다.', `MaleText_loc4`='%s很明显被惹怒了，用尽全力击打博学者拜特。', `MaleText_loc5`='%s真的很惱怒，用致命的力量擊打自然學家拜特。', `MaleText_loc7`='Muy molesto, %s propina un golpe fortísimo al naturalista Mordisco.' WHERE `ID`=15529;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 된거죠? 오, 그대가 벌써 놈을 처치했군요! 이제 시체를 연구할 수 있겠습니다.', `MaleText_loc4`='怎么回事？你把他给杀了！好吧，我想我可以研究一下尸体。', `MaleText_loc5`='這是什麼?你已經殺了他!喔好吧，我想我可以研究屍體了。', `MaleText_loc7`='¿Qué es esto? ¡Ya lo has matado! Bueno, supongo que puedo examinar el cadáver.' WHERE `ID`=15530;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 가엾은 식물학자 바이트의 시체가 있습니다. 지식에 대한 그의 열정은 오직 죽음만이 멈출 수 있었습니다.', `MaleText_loc4`='这里躺着可怜的博学者拜特的遗体。他对知识的热情给他带来的只有死亡的结局。', `MaleText_loc5`='這裡躺著可憐的自然學家拜特的破碎形體。他對知識的狂熱只能和他死狀的慘烈相匹配。', `MaleText_loc7`='Aquí yace el cuerpo roto del pobre naturalista Mordisco. La ferocidad de su sed de conocimientos fue solo superada por su brutal muerte.' WHERE `ID`=15531;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 조사한 모든 정보를 내가 총정리해봤네.$B$B주요 괴철로 기지는 두 곳이 있네. 바로 이곳에서 서쪽에 있는 증오의 괴철로 기지와 남서쪽에 있는 경악의 괴철로 기지일세. 각 괴철로 기지에는 군단 순간이동기 하나, 용광로 하나 그리고 마법을 방어하는 여러 개의 탑이 있네. 또한, 지옥 대포를 조작하는 격노수호병이 괴철로 기지를 지키고 있지. 마지막으로 각 괴철로 기지를 지옥의 군주가 감독하고 있어.$B$B뭐, 이 정도쯤이야 자네에게 전혀 문제도 되지 않겠지만...$B$B<소리 내어 웃는 알트루이스>', `MaleText_loc4`='这是我从你的调查中得到的情报。$B$B那里有着两座主要的铸魔营地——仇恨和畏惧。铸魔营地：仇恨在我们的西边，而西南边是铸魔营地：畏惧。每座营地中都有一个军团传送点，一座熔炉，还有几座法术结界塔。每座营地都配备了由愤怒卫士控制的邪能火炮。最后，每座营地都还有一个深渊领主监督着。$B$B就这样，这应该一点也问题没有……$B$B<奥图里斯大笑起来。>', `MaleText_loc5`='這是我從你收集的調查資訊中獲得的結果。$B$B有兩個主要的煉冶場:西邊的煉冶場:仇恨和西南方的煉冶場:恐懼。每個煉冶場有一個軍團傳送器，一個熔爐，和幾個法術防護哨塔。此外，還有憤怒守衛操縱惡魔火砲來守衛煉冶場。最後，每個煉冶場都有一個深淵領主監督者。$B$B好吧，這樣應該一點問題都沒有了...$b$b<奧翠司笑著。>', `MaleText_loc7`='Esto es lo que he sacado de la información que conseguiste con la inspección.$B$BHay dos campamentos Forja principales: Campamento Forja: Odio, al oeste de aquí y Campamento Forja: Miedo, al suroeste. Cada campamento tiene un teletransportador de la Legión, una forja y varias torres de amparo de hechizos. Además los campamentos están custodiados por guardias de cólera que manejan cañones viles. Para terminar, cada campamento tiene un señor del foso como sobrestante.$B$BEsto no debería suponer ningún problema...$B$B< Altruis ríe.>' WHERE `ID`=15532;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 생각엔 다른 자들이 오슈군으로 들어갈까 말까 고민하는 동안 돈을 좀 벌 수 있을 거 같소.$B$B시간이 곧 돈이지!', `MaleText_loc4`='我想我应该趁别人还在讨论是否可以进入沃舒古的时候自己先想办法赚些钱。$B$B时间就是利润！', `MaleText_loc5`='我想我可以在其他人還在苦惱是否要進入歐夏剛時另外賺點收入。$B$B時間就是利潤!', `MaleText_loc7`='Creo que sacaré algún dinerillo extra mientras los demás deciden si es buena idea ir a Oshu''gun.$B$B¡El tiempo es oro!' WHERE `ID`=15534;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='봉화가 켜졌으니 이제 공격할 때이다! 이 전투 깃발을 가지고 가서 호드의 무덤에 꽂아라!', `MaleText_loc4`='灯塔点亮了，是时候发动进攻了！拿上一面部落军旗，把它插在墓地中吧！', `MaleText_loc5`='烽火已點燃，現在是攻擊的時刻了!拿起一面戰旗，並且替部落將它插在墓地上!', `MaleText_loc7`='Las balizas están encendidas. ¡Es el momento de atacar! ¡Toma uno de estos confalones y plántalo en el cementerio! ¡Por la Horda!' WHERE `ID`=15535;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 쌍둥이 첨탑 폐허가 안전하지 않다! 2개의 봉화가 켜지고 이 지역의 안전이 확보되면 전투 깃발을 전달하라. 그곳으로 가서 그 봉화를 접수하라!', `MaleText_loc4`='双塔废墟还没有被占领！我的命令是当这两座灯塔都被点亮、并且整个区域都被占领的时候发放军旗。到那里去控制灯塔吧！', `MaleText_loc5`='雙塔廢墟還沒落入我方的控制之中!我的命令是點燃兩座烽火臺，並且在該區域處於我方控制之下時發送戰旗。去將那兩座烽火臺奪下!', `MaleText_loc7`='¡Las Ruinas de las Agujas Gemelas no son seguras todavía! Las órdenes son entregar confalones solo cuando las dos balizas estén encendidas y la zona sea segura. ¡Toma el control de las balizas, vamos!' WHERE `ID`=15536;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제게 전투 깃발을 주십시오. 쌍둥이 첨탑 폐허를 우리 손에 넣겠습니다.', `MaleText_loc4`='给我军旗。我会控制双塔废墟的。', `MaleText_loc5`='給我一面戰旗。我會去佔領雙塔廢墟。', `MaleText_loc7`='Dame un confalón de batalla. Tomaré el control de las Ruinas de las Agujas Gemelas.', `FemaleText_loc1`='제게 전투 깃발을 주십시오. 쌍둥이 첨탑 폐허를 우리 손에 넣겠습니다.', `FemaleText_loc4`='给我军旗。我会控制双塔废墟的。', `FemaleText_loc5`='給我一面戰旗。我會去佔領雙塔廢墟。', `FemaleText_loc7`='Dame un confalón de batalla. Tomaré el control de las Ruinas de las Agujas Gemelas.' WHERE `ID`=15537;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='봉화가 켜졌으니 이제 공격할 때이다! 이 전투 깃발을 가지고 가서 얼라이언스의 무덤에 꽂아라!', `MaleText_loc4`='灯塔点亮了，是时候发动进攻了！拿上一面联盟军旗，把它插在墓地中吧！', `MaleText_loc5`='烽火已點燃，現在是攻擊的時刻了!拿起一面戰旗，並且替聯盟將它插在墓地上!', `MaleText_loc7`='Las balizas están encendidas, ¡es el momento de atacar! ¡Toma uno de esos estandartes y plántalo en el cementerio por la Alianza!' WHERE `ID`=15538;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제게 전투 깃발을 주십시오. 쌍둥이 첨탑 폐허를 우리 손에 넣겠습니다.', `MaleText_loc4`='给我一面军旗，我去占领双塔废墟。', `MaleText_loc5`='給我一面戰旗。我會去佔領雙塔廢墟。', `MaleText_loc7`='Dame un confalón de batalla. Tomaré el control de las Ruinas de las Agujas Gemelas.', `FemaleText_loc1`='제게 전투 깃발을 주십시오. 쌍둥이 첨탑 폐허를 우리 손에 넣겠습니다.', `FemaleText_loc4`='给我一面军旗，我去占领双塔废墟。', `FemaleText_loc5`='給我一面戰旗。我會去佔領雙塔廢墟。', `FemaleText_loc7`='Dame un confalón de batalla. Tomaré el control de las Ruinas de las Agujas Gemelas.' WHERE `ID`=15539;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 쌍둥이 첨탑 폐허는 안전하지 않습니다! 2개의 봉화가 켜지고 그 지역의 안전이 확보되면 전투 깃발을 꽂으십시오. 자, 그곳으로 가서 어서 봉화를 접수하십시오!', `MaleText_loc4`='双塔废墟还没有被占领！我的命令是当这两座灯塔都被点亮、并且整个区域都被占领的时候发放军旗。到那里去控制灯塔吧！', `MaleText_loc5`='雙塔廢墟還沒落入我方的控制之中!我的命令是點燃兩座烽火臺，並且在該區域處於我方控制之下時發送戰旗。去將那兩座烽火臺奪下!', `MaleText_loc7`='¡Las Ruinas de las Agujas Gemelas no son seguras todavía! Las órdenes son entregar confalones solo cuando las dos balizas estén encendidas y la zona sea segura. ¡Toma el control de las balizas, vamos!' WHERE `ID`=15540;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cffffff00얼라이언스가 서쪽 봉화를 차지했습니다!|r', `MaleText_loc4`='|cffffff00联盟夺取了西部灯塔的控制权！|r', `MaleText_loc5`='|cffffff00聯盟已奪去西部哨塔控制權!|r', `MaleText_loc7`='|cffffff00¡La Alianza ha tomado el control de la Baliza del Oeste!|r' WHERE `ID`=15541;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어느 녀석이 내 집에 들어와서 나를 위협하는 것이냐!', `MaleText_loc4`='你闯进我的家门来威胁我？我可不认为你能如愿。', `MaleText_loc5`='你進到我的房子裡來威脅我?我可不這麼認為!', `MaleText_loc7`='¿Vienes a mi propia casa a amenazarme? ¡Ahora verás!' WHERE `ID`=15542;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cffffff00호드가 서쪽 봉화를 차지했습니다!|r', `MaleText_loc4`='|cffffff00部落夺取了西部灯塔的控制权！|r', `MaleText_loc5`='|cffffff00部落已奪去西部哨塔控制權!|r', `MaleText_loc7`='|cffffff00¡La Horda ha tomado el control de la Baliza del Oeste!|r' WHERE `ID`=15543;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<당신을 향해 으르렁대더니 거품이 이는 맥주를 마시러 돌아가는 살살라빔>', `MaleText_loc4`='<萨萨拉比姆对着你咆哮，然后回头去喝他那起泡的饮料。>', `MaleText_loc5`='<沙薩拉畢恩對你咆哮，再回去喝他充滿泡沫的飲料。>', `MaleText_loc7`='<Sal''salabim te gruñe y se aleja para ingerir su brebaje espumoso.>' WHERE `ID`=15544;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cffffff00호드가 동쪽 봉화를 차지했습니다!|r', `MaleText_loc4`='|cffffff00部落夺取了东部灯塔的控制权！|r', `MaleText_loc5`='|cffffff00部落已奪去東部哨塔控制權!|r', `MaleText_loc7`='|cffffff00¡La Horda ha tomado el control de la Baliza del Este!|r' WHERE `ID`=15545;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cffffff00얼라이언스가 동쪽 봉화를 차지했습니다!|r', `MaleText_loc4`='|cffffff00联盟夺取了东部灯塔的控制权！|r', `MaleText_loc5`='|cffffff00聯盟已奪去東部哨塔控制權!|r', `MaleText_loc7`='|cffffff00¡La Alianza ha tomado el control de la Baliza del Este!|r' WHERE `ID`=15546;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[악마어]카 칼릭스!', `MaleText_loc4`='[恶魔语] Ka kalix！', `MaleText_loc5`='[惡魔]卡卡立克斯!', `MaleText_loc7`='[Demoníaco] ¡Ka kalix!' WHERE `ID`=15551;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알트루이스가 보내서 왔습니다. 당신이 절 도와줄 수 있다고 했습니다.', `MaleText_loc4`='奥图里斯派我过来的。他说你能帮我。', `MaleText_loc5`='奧翠司叫我來的。他說你可以幫我。', `MaleText_loc7`='Me envía Altruis. Ha dicho que puedes ayudarme.', `FemaleText_loc1`='알트루이스가 보내서 왔습니다. 당신이 절 도와줄 수 있다고 했습니다.', `FemaleText_loc4`='奥图里斯派我过来的。他说你能帮我。', `FemaleText_loc5`='奧翠司叫我來的。他說你可以幫我。', `FemaleText_loc7`='Me envía Altruis. Ha dicho que puedes ayudarme.' WHERE `ID`=15552;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='트리로스, 당신의 마음 어딘가에 진실이 있다는 거 알고 있습니다. 저에게 말씀해 주십시오.', `MaleText_loc4`='忒洛斯，我知道你了解真相。告诉我吧。', `MaleText_loc5`='崔洛斯，我知道真相就在你心裡的某處。告訴我吧。', `MaleText_loc7`='Treelos, sé que la verdad está en algún lugar de tu interior. Dime de qué se trata.', `FemaleText_loc1`='트리로스, 당신의 마음 어딘가에 진실이 있다는 거 알고 있습니다. 저에게 말씀해 주십시오.', `FemaleText_loc4`='忒洛斯，我知道你了解真相。告诉我吧。', `FemaleText_loc5`='崔洛斯，我知道真相就在你心裡的某處。告訴我吧。', `FemaleText_loc7`='Treelos, sé que la verdad está en algún lugar de tu interior. Dime de qué se trata.' WHERE `ID`=15553;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<기묘한 표정으로 당신을 쳐다보더니 고민하면서 잠시 머뭇거리는 교도관 트리로스.>$B$B장가르 습지대... 진실에 너무 가까이 접근했습니다.$B$B<다시 정신이 나간 교도관 트리로스>$B$B아직도 그가 지켜보고 있는 겁니까!?', `MaleText_loc4`='<监护者忒洛斯滑稽地看着你，停了停，看起来似乎很难控制自己。>$B$B赞加沼泽……真相太近了。$B$B<他的脸再次变得疯狂起来。>$B$B他还在监视着吗！？', `MaleText_loc5`='<守望者崔洛斯打趣的看著你然後停了一下，明顯地在掙扎>$B$B贊格沼澤...太接近真相了。$B$B<他的臉再次變得瘋狂。>$B$B他還在看嗎?', `MaleText_loc7`='<El Celador Treelos te mira de forma extraña y hace una pequeña pausa; está afectado.>$B$BLa Marisma de Zangar... demasiado cerca de la verdad.$B$B<Su rostro adopta un gesto de locura de nuevo.>$B$B¡¿Sigue observando?!' WHERE `ID`=15554;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얘기해 주십시오! 장가르 습지대가 어쨌다는 겁니까?', `MaleText_loc4`='嘿！清醒一点，哥们！赞加沼泽怎么了？', `MaleText_loc5`='振作點老兄!贊格沼澤怎麼樣?', `MaleText_loc7`='¡Mantenlo unido, hombre! ¿Qué pasa con la marisma de Zangar?', `FemaleText_loc1`='얘기해 주세요! 장가르 습지대가 어쨌다는 거죠?', `FemaleText_loc4`='嘿！清醒一点，哥们！赞加沼泽怎么了？', `FemaleText_loc5`='振作點老兄!贊格沼澤怎麼樣?', `FemaleText_loc7`='¡Mantenlo unido, hombre! ¿Qué pasa con la marisma de Zangar?' WHERE `ID`=15555;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 말입니까? 장가르 습지대라니요? 제가 뭐하러 그곳에 가겠습니까?$B$B<생각에 잠긴 트리로스>$B$B오, 그렇군요, 장가르 습지대... 그곳에 있던... 우리 드루이드들은 수위가 낮아지는 원인을 거의 알아냈습니다. 그것이 모든 것을 파괴하고 있습니다!$B$B<광기가 돌아오는 교도관 트리로스의 눈>$B$B우리 모두를 죽인 겁니다! 그 밝은 빛이! 쾅!!', `MaleText_loc4`='那是什么？赞加沼泽？为什么我要去那里？$B$B<忒洛斯似乎正在陷入沉思。>$b$B是的，赞加沼泽……我们……德鲁伊们快要发现为什么水平面正在下降。它正毁灭着一切！$B$B<癫狂又在监护者的眼中出现。>$B$B毁灭我们吧！明亮的圣光！轰！！', `MaleText_loc5`='那是什麼?贊格沼澤?我為什麼會想去那裡?$B$B<崔洛斯看起來在沉思。>$B$B好，贊格沼澤...我們...那裡的德魯伊很快就會知道為什麼水平面一直在降低了。它在摧毀一切!$B$B<你可以在守望者的眼裡看見瘋狂錯亂的恐懼。>$B$B摧毀我們全部的人!刺眼的光芒!爆炸!', `MaleText_loc7`='¿Qué? ¿La Marisma de Zangar? ¿Para qué quieres ir ahí?$B$B<Treelos se queda pensativo.>$B$BSí, la Marisma de Zangar... Nosotros..., los druidas, estamos averiguando por qué el nivel del agua ha bajado tanto. ¡Está perdiéndose todo!$B$B<Ves un brillo de locura en la mirada del celador.>$B$B¡Todos destruidos! ¡Luz brillante! ¡BUM!' WHERE `ID`=15556;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이러고 있을 시간이 없습니다! 교도관, 무슨 일이 있었던 겁니까?', `MaleText_loc4`='我没有时间跟你玩！监护者，到底发生了什么事？！', `MaleText_loc5`='我沒時間了!典獄官，發生什麼事了?!', `MaleText_loc7`='¡No tengo tiempo para esto! ¡¿Qué ha ocurrido, celador?!', `FemaleText_loc1`='이러고 있을 시간이 없어요! 교도관, 무슨 일이 있었던 거죠?', `FemaleText_loc4`='我没有时间跟你玩！监护者，到底发生了什么事？！', `FemaleText_loc5`='我沒時間了!典獄官，發生什麼事了?!', `FemaleText_loc7`='¡No tengo tiempo para esto! ¡¿Qué ha ocurrido, celador?!' WHERE `ID`=15557;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불꽃날개 블러드 엘프들이... 어떤 이유로 우리를 막으려 합니다.$B$B<빈틈을 보이지 않기 위해 잠시 동안 눈에 띄게 노력하는 교도관 트리로스>$B$B그들은... 한 뒤틀린 드레나이를... 사절로 보냈습니다... 하지만 그는 폭탄을 지니고 있었습니다!$B$B죽었죠... 그들 모두 죽었단 말입니다! 그들은 힘을 다해 달아나려고 노력했습니다! 운이 좋았던 이조차 알지 못했습니다.$B$B제가 그 폭발 속에 있어야 했습니다. 그것은 공포였... 또다시 우리를 지켜보고 있단 말입니다!$B$B<낙담한 모습으로 마치 당신이 그 자리에 없는 것처럼 당신을 응시하는 트리로스>', `MaleText_loc4`='火翼的血精灵们……不知道为什么，他们想阻止我们。$B$B<监护者忒洛斯努力地想镇静下来。>$B$B他们……他们派了一个破碎者作为……作为大使……但是他有炸弹！$B$B他们都死了，他们都死了！他们想逃跑！有些幸运的家伙甚至都不知道。$B$B我肯定是在爆炸的边缘。那实在太糟了……又开始监视我们了！$B$B<忒洛斯变得很沮丧，直钩钩地看着前方，好像把你当成了空气。>', `MaleText_loc5`='血精靈...不知道為什麼他們就是想阻止我們。$B$B<守望者崔洛斯明顯地努力讓他的頭腦多保持清醒幾秒。>$B$B他們...他們派了一個破碎者當...當間諜...但他帶了一顆炸彈!$B$B他們死了，他們全都死了!他們試著逃跑!根本不知道有沒有倖存者。$B$B我一定是在爆炸的邊緣。那實在太可...它又在盯著我們看了!$B$B<崔洛斯變的很沮喪並直視你後方好像你不在那裡一樣。>', `MaleText_loc7`='Los elfos de sangre de Ala de Fuego quieren detenernos por alguna razón...$B$B<El Celador Treelos se esfuerza visiblemente por contenerse.>$B$BEnviaron.. Enviaron a un Tábido de mensajero... Un Tábido, sí... ¡Pero tenía una bomba!$B$B¡Murieron! ¡Murieron todos! ¡Intentaron escaparse! Los que tuvieron suerte, ni siquiera se dieron cuenta.$B$BYo estaba fuera del alcance de la explosión. Fue horri... ¡NOS ESTÁ OBSERVANDO OTRA VEZ!$B$B<Treelos enmudece y mira a través de ti como si no estuvieras.>' WHERE `ID`=15558;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 원하나!?', `MaleText_loc4`='你要干什么？', `MaleText_loc5`='你想怎樣?', `MaleText_loc7`='¿¡QUÉ QUIEREN USTEDES!?' WHERE `ID`=15559;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살살라빔에게 진 빚을 받으러 왔습니다. 빚을 갚지 않으면 당신을 다치게 할 수밖에 없습니다.', `MaleText_loc4`='我是萨萨拉比姆派来收债的。还钱，否则我就不客气了。', `MaleText_loc5`='沙薩拉畢恩派我來討回你欠的債。快付錢否則我就要對你不利了。', `MaleText_loc7`='Me envía Sal''salabim para cobrar una deuda que tienes con él. Págame o tendré que hacerte daño.', `FemaleText_loc1`='살살라빔에게 진 빚을 받으러 왔습니다. 빚을 갚지 않으면 당신을 다치게 할 수밖에 없어요.', `FemaleText_loc4`='我是萨萨拉比姆派来收债的。还钱，否则我就不客气了。', `FemaleText_loc5`='沙薩拉畢恩派我來討回你欠的債。快付錢否則我就要對你不利了。', `FemaleText_loc7`='Me envía Sal''salabim para cobrar una deuda que tienes con él. Págame o tendré que hacerte daño.' WHERE `ID`=15560;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='프쉬쉬쉬쉬쉬?', `MaleText_loc4`='呼嘶呼呼？？', `MaleText_loc5`='噓～～～～?', `MaleText_loc7`='¿Fshhhhhhsssfhhhhh?' WHERE `ID`=15561;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<이상한 딸각거리는 소리와 닭 울음소리를 내는 플룬>', `MaleText_loc4`='<弗鲁恩发出一连串奇怪的唧唧咯咯的声音。>', `MaleText_loc5`='<服倫做了一連串奇怪的卡嗒和咯咯聲。>', `MaleText_loc7`='<Floon hace una serie de ruidos y chasquidos extraños.>' WHERE `ID`=15562;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말입니까? 그는 이미 절 죽였습니다! 그가 뭘 더 바란다는 거죠?', `MaleText_loc4`='你开玩笑吧？他已经把我杀了！他还想要什么？', `MaleText_loc5`='你是認真的嗎?他已經殺過我了!他還能怎麼樣?', `MaleText_loc7`='¿Hablas en serio? ¡Ya me ha matado! ¿Qué más podría querer?' WHERE `ID`=15563;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그는 자기 "돈"을 원합니다. 돈을 갚지 못하면 다시 한 번... 죽어야 합니다...', `MaleText_loc4`='他想要“金币”。再说一次……要么付钱要么纳命来……', `MaleText_loc5`='他要他的「金子」。不付錢就死...再一次...', `MaleText_loc7`='Quiere sus "oros". Paga o muere... otra vez.', `FemaleText_loc1`='그는 자기 "돈"을 원합니다. 돈을 갚지 못하면 다시 한 번... 죽어야 합니다...', `FemaleText_loc4`='他想要“金币”。再说一次……要么付钱要么纳命来……', `FemaleText_loc5`='他要他的「金子」。不付錢就死...再一次...', `FemaleText_loc7`='Quiere sus "oros". Paga o muere... otra vez.' WHERE `ID`=15564;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='플루우우우우우운! 쿠쉬쿠쉬 아무것도 못 받았다! 죽어라!', `MaleText_loc4`='库什库什不会还钱的！死吧！', `MaleText_loc5`='可惡!庫庫許不付錢!死吧!', `MaleText_loc7`='¡F''woooroonn! ¡Coosh''coosh pagar nada! ¡Morir!' WHERE `ID`=15565;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 세 번째 방법을 선택하겠습니다. 죽어라!', `MaleText_loc4`='我选择第三项：杀了你！', `MaleText_loc5`='我選第三個選項:殺了你!', `MaleText_loc7`='Elijo la tercera opción: ¡MATARTE!' WHERE `ID`=15566;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라리크 너한테 교훈 가르쳐 준다!', `MaleText_loc4`='拉里克要教训你！', `MaleText_loc5`='拉利克現在要給你點顏色瞧瞧!', `MaleText_loc7`='¡Raliq darte lección ahora!' WHERE `ID`=15567;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 이곳에서 무슨 일이 일어났는지 알아낼 수 있도록 도와줘서 다시 한 번 고맙다는 말을 하고 싶소, $n.', `MaleText_loc4`='$n，再次感谢你帮我找出了树林里这件惨剧的真相。', `MaleText_loc5`='再次謝謝你，$n，幫助我揭發灌木叢這裡發生的事。', `MaleText_loc7`='Gracias de nuevo, $n, por ayudarme a descubrir lo que pasó en el matorral.' WHERE `ID`=15568;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가져가라. 어차피 쓸모없는 놈이니까!', `MaleText_loc4`='你可以随便处理他，我已经不需要他了！', `MaleText_loc5`='你可以殺了那個人，我再也不需要他了!', `MaleText_loc7`='¡Te lo puedes quedar, ya no me sirve!' WHERE `ID`=15569;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자인가? 어서 저 녀석을 해치우는 것이 최선이다!', `MaleText_loc4`='入侵者？去吧，干掉他，帮我省点力气！', `MaleText_loc5`='侵入者?去吧，殺了那個人，省了我的力氣!', `MaleText_loc7`='¿Intrusos? Vamos, mata a este; me ahorrarás el esfuerzo.' WHERE `ID`=15570;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그놈을 원한다고? 좋다, 가져가라!', `MaleText_loc4`='你想杀了他？随便你！', `MaleText_loc5`='你也想殺那個人?很好，殺吧!', `MaleText_loc7`='¿Lo quieres? ¡Muy bien, tómalo!' WHERE `ID`=15572;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='약골을 상대하는데 시간을 낭비하지 말라고.', `MaleText_loc4`='别在他身上浪费时间了，他是个没用的东西。', `MaleText_loc5`='別浪費太多時間在那個人身上，他太弱了!', `MaleText_loc7`='¡No pierdas el tiempo con ese! Es débil.' WHERE `ID`=15573;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 녀석을 치면 엄마를 부를지도 모르니까 조심해라! 하하하!', `MaleText_loc4`='小心！你打那家伙的时候，他可能会叫他的妈妈。哈哈哈！', `MaleText_loc5`='小心!那個人可能會因為你打他而向他媽媽告狀。哈哈哈!', `MaleText_loc7`='¡Cuidado! Puede que ese llame a su mami cuando le pegues. ¡Jajaja!' WHERE `ID`=15574;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 마구 내려쳐라! 그놈은 오우거만큼 머리가 단단하지.', `MaleText_loc4`='对！不要留情！', `MaleText_loc5`='對，狠狠打扁那個人，他的頭顱和巨魔一樣厚實!', `MaleText_loc7`='¡Sí, dale sin piedad! Tiene el cráneo tan grueso como el de un ogro.' WHERE `ID`=15575;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저놈의 피부는 붉은색일지 몰라도 그 내장은 노란색이다!', `MaleText_loc4`='那家伙的毛皮可能是红色的，但是他的肚子是黄色的！', `MaleText_loc5`='那個人的皮膚雖然是紅色的，但他的肚子是黃色的!', `MaleText_loc7`='¡La piel de ese puede que sea roja, pero su barriga es amarilla!' WHERE `ID`=15576;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 다른 녀석을 원하는 것이냐? 그래, 어서 처치해라! 얼굴보다는 바닥에 흐르는 녀석의 피가 더 보기 좋을 것이니까...', `MaleText_loc4`='你还想要？去吧！这家伙的血流在地板上比淌在脸上好看多了。', `MaleText_loc5`='你想要另外一個?去吧!他的血流在地上會比流在他臉上好看些。', `MaleText_loc7`='¿Quieres otro? ¡Adelante! Su sangre queda mejor derramada en el suelo que en su cara.' WHERE `ID`=15577;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 그래. 새 아침의 첫 살상이로구나. 계속해라!', `MaleText_loc4`='啊，不错，早晨的第一次击杀。继续！', `MaleText_loc5`='啊太好了，今早的第一個手下敗將。繼續!', `MaleText_loc7`='Aaah, sí... La primera muerte de la mañana. Continúa.' WHERE `ID`=15578;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구차한 목숨이 또 하나 갔구나. 계속 해봐라!', `MaleText_loc4`='有个废柴挂了，继续，干掉下一个！', `MaleText_loc5`='又一個可憐人陣亡了，繼續，繼續殺呀!', `MaleText_loc7`='Un desgraciado menos. ¡Adelante, ve por otro!' WHERE `ID`=15579;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 녀석은 금세 죽어 버리는군! 녀석의 형제라면 좀 더 버틸 수 있겠지!', `MaleText_loc4`='那家伙死得太快了！也许他的兄弟可以撑得更久一些！', `MaleText_loc5`='那個死的真快!或許他的兄弟不只是會打仗而已!', `MaleText_loc7`='¡Qué rápido murió ese! Puede que sus hermanos den un poco más de guerra.' WHERE `ID`=15580;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갈색 오크 녀석들조차도 그보다 오래 버티건만. 쓰레기 같은 녀석... 다음!', `MaleText_loc4`='兽人就是皮糙肉厚死得慢。多浪费啊……下一个！', `MaleText_loc5`='就連咖啡色皮膚的獸人都要那麼久才死。真是浪費時間...下一個!', `MaleText_loc7`='Hasta los orcos de piel marrón tardan más en morir. Qué desperdicio... ¡el siguiente!' WHERE `ID`=15581;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어쨌거나 처리하려던 놈이었다!', `MaleText_loc4`='就算你不动手，我也会杀了他！', `MaleText_loc5`='反正我馬上就要把他殺了!', `MaleText_loc7`='¡Me iba encargar de él de todas formas!' WHERE `ID`=15582;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='녀석의 죽음은 처음 녀석보다 훨씬 끔찍하군!', `MaleText_loc4`='他的死要比第一个悲惨得多！', `MaleText_loc5`='他死的比第一個人還要悽慘!', `MaleText_loc7`='¡Su muerte ha sido incluso más triste que la del primero!' WHERE `ID`=15583;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 시간 낭비가 따로 없군. 다음!', `MaleText_loc4`='啊，多么浪费啊。下一个！', `MaleText_loc5`='可憐啊!至少他的血在我的地板上挺好看的!', `MaleText_loc7`='Ah, que desperdicio... ¡Siguiente!' WHERE `ID`=15584;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='녀석은 자신의 검은늑대가 죽었을 때 눈물을 흘렸다만 지금 녀석을 위해 울어줄 사람은 아무도 없다!', `MaleText_loc4`='他为他的座狼的死而哭泣。好吧，现在没人为他哭泣了！', `MaleText_loc5`='他的座狼死去時他哭的很傷心。嗯，現在卻沒有人為他哭泣!', `MaleText_loc7`='Lloró cuando murió su huargo. ¡Nadie llorará por él ahora!' WHERE `ID`=15585;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노예들을 처리하는 데 시간이 오래 걸렸구나!', `MaleText_loc4`='你这么久才解决掉他们！', `MaleText_loc5`='時間夠你去把他們毀滅掉了!', `MaleText_loc7`='¡Te ha llevado bastante tiempo rematarlos!' WHERE `ID`=15586;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 그 비천한 쓰레기들을 훈련하는 일에서 벗어났으니 너와 함께 즐거운 시간을 보내야겠구나!', `MaleText_loc4`='现在我有空来教训那些可怜虫了，让我来和你玩玩！', `MaleText_loc5`='既然我不用再訓練那些可悲的傢伙，我就跟你好好玩玩吧!', `MaleText_loc7`='¡Ahora que ya no tengo que entrenar a esos miserables insectos, podré divertirme contigo!' WHERE `ID`=15587;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바닥을 피로 물들이니 얼마나 보기 좋으냐.', `MaleText_loc4`='用血来装饰我的地板多好啊。', `MaleText_loc5`='你真是好人竟用鮮血來裝飾我的地板。', `MaleText_loc7`='Qué bonito por tu parte, decorar mi suelo con sangre.' WHERE `ID`=15588;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성가신 일을 대신 해줘서 고맙군. 이제 나도 재미 좀 볼까!', `MaleText_loc4`='谢谢你们帮我省去不少麻烦。现在，该我来找找乐子了！', `MaleText_loc5`='謝謝你幫助我渡過難關。現在該是換我表現的時候了!', `MaleText_loc7`='¡Gracias por ahorrarme las molestias! Es mi turno de divertirme un poco.' WHERE `ID`=15589;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cffffff00호드가 쌍둥이 첨탑 폐허의 통제권을 차지했습니다!|r', `MaleText_loc4`='|cffffff00部落夺取了双塔废墟的控制权！|r', `MaleText_loc5`='|cffffff00部落已奪去雙塔廢墟控制權!|r', `MaleText_loc7`='|cffffff00¡La Horda ha tomado el control de las Ruinas de las Agujas Gemelas!|r' WHERE `ID`=15590;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cffffff00얼라이언스가 쌍둥이 첨탑 폐허를 차지했습니다!|r', `MaleText_loc4`='|cffffff00联盟夺取了双塔废墟的控制权！|r', `MaleText_loc5`='|cffffff00聯盟已奪去雙塔廢墟控制權!|r', `MaleText_loc7`='|cffffff00¡La Alianza ha tomado el control de las ruinas de las Agujas Gemelas!|r' WHERE `ID`=15591;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자? 네가 그 멍청이들의 생각을 뜯어고쳐 놓아라!', `MaleText_loc4`='懦夫？也许你该把那个白痴给我打得聪明点！', `MaleText_loc5`='門外漢?或許你可以給那個笨蛋一點顏色瞧瞧!', `MaleText_loc7`='¿Extranjeros? Métele un poco de inteligencia a golpes en la cabeza.' WHERE `ID`=15593;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한꺼번에 덤벼보시겠다? 정말 재미있겠군!', `MaleText_loc4`='你想要我们一起上？很好！', `MaleText_loc5`='喔?你想一次對付我們所有人?這一定會很有趣...', `MaleText_loc7`='¿Quieres luchar contra todos nosotros a la vez? ¡Mas ser divertido!' WHERE `ID`=15594;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제대로 덤벼라! 진짜 싸움이 뭔지 보여줘!', `MaleText_loc4`='来吧，让我看看你们真正的实力！', `MaleText_loc5`='來吧，打一場真正的戰鬥!', `MaleText_loc7`='¡Vamos! ¡Ofrézcanme una lucha de verdad!' WHERE `ID`=15595;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 무서워...', `MaleText_loc4`='我感到胆战心惊……', `MaleText_loc5`='我很畏縮...', `MaleText_loc7`='Me siento juguetón...' WHERE `ID`=15596;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 아직 떠날 준비가 안 됐는데...', `MaleText_loc4`='啊……我还没准备好离开……', `MaleText_loc5`='呃...我真的還沒準備好離開...', `MaleText_loc7`='Ah... Todavía me queda cuerda...' WHERE `ID`=15597;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 정말 아름다웠어... 내가 시인이었다면 얼마나 좋을까...', `MaleText_loc4`='我看到的东西……是如此漂亮……如果我是个诗人……', `MaleText_loc5`='我看到的東西...是那樣美麗...好像我是詩人一樣...', `MaleText_loc7`='Las cosas que he visto... Qué hermosas... Si fuera poeta...' WHERE `ID`=15598;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='머릿속은 맑고 깨끗하지만 구름도 끼어 있네... 은빛 구름들이...투명하리만큼 뽀얀 선을 만들고...', `MaleText_loc4`='我的脑子既清醒又混乱……有时候像水晶那样明了……有时候又像云彩那样模糊……', `MaleText_loc5`='我的頭又清醒又昏沉...水晶內層...銀色雲朵...', `MaleText_loc7`='Mi cabeza está despejada y dormida al mismo tiempo... Lienzos de cristal... nubes de plata...' WHERE `ID`=15599;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제 일은 이 가엾은 영혼들을 돌보는 것입니다. 도와주실 분이라면 알도르 사제회든 점술가 길드든 상관없이 환영합니다.$B$B일손이 너무 부족해서 붕대 감을 줄만 안다면 오우거라 해도 돌려보내지 못할 판이랍니다. 이 도시의 정치 문제야 제 알 바 아니죠.', `FemaleText_loc4`='我的工作是照顾那些可怜的灵魂。我愿意接受任何帮忙，无论他们是奥尔多还是占星者。$B$B我们太缺人手了，如果食人魔知道怎么扎绷带，我甚至愿意让他们帮忙。这座城市里的政治派系对我来说是个不小的麻烦。', `FemaleText_loc5`='我的工作是照顧可些可憐的靈魂。我接受任何樂於幫助的人，不管他們是奧多爾或占卜者。$B$B我們人手很不足，如果有巨魔知道怎麼使用止血帶我也不會拒絕他的。我不太在意這個城市的政治傾向。', `FemaleText_loc7`='Mi trabajo consiste en ocuparme de estas pobres almas. Acepto la ayuda de cualquier corazón bondadoso, ya sea Aldor o Arúspice.$B$BNecesitamos a tanta gente que no le diría que no ni a un ogro si supiera cómo hacer un torniquete. La política de la ciudad me importa bien poco.' WHERE `ID`=15600;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='믿어지세요? 이 에테리얼에게는 바실리스크 눈이 하나도 없네요!$B$B그리고 그의 지도자는 뻔뻔스럽게도 스스로 ''밀수왕''이라고 부르고 있습니다!', `FemaleText_loc4`='你能相信吗？这个虚灵身上竟然没有一只蜥蜴眼！$B$B然而他们的首领竟然还有胆子自称为“走私大亨！”', `FemaleText_loc5`='你相信嗎?這個以太族身上竟然連一個蜥蝪眼也沒有!$B$B他的領導者竟然還有臉自稱為「走私者王子」!', `FemaleText_loc7`='No puedo creerlo. ¡Este etéreo no tiene ni un solo ojo de basilisco!$B$B¡Y su líder tiene la desfachatez de llamarse ''el Príncipe Contrabandista''!' WHERE `ID`=15601;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고양이가 빗자루를 뚫어져라 쳐다봅니다.', `MaleText_loc4`='猫专注地盯着扫帚。', `MaleText_loc5`='那隻貓專注地看著掃帚。', `MaleText_loc7`='El gato mira la escoba atentamente.' WHERE `ID`=15602;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 그러고 있니, 베시. 오늘은 네가 산책할 차례잖아?', `MaleText_loc4`='贝希，你在叫什么？该出去走走了，对吧？', `MaleText_loc5`='哈囉，貝絲。今天換你去散步了，對嗎?', `MaleText_loc7`='Ah, hola, Bessy. Hoy te toca pasear, ¿verdad?' WHERE `ID`=15603;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가엾은 베시, 이렇게 더운 날에 마구간에 갇혀 있는 신세라니... 자, 내가 널 위해 간식을 가져왔단다!', `MaleText_loc4`='可怜的贝希，大热天的被关在畜棚里。让我给你找点吃的！', `MaleText_loc5`='可憐的貝絲，這麼熱的天氣還要被關在這個穀倉裡。讓我幫你拿個點心來!', `MaleText_loc7`='Pobre Bessy, confinada en este establo en un día tan caluroso. ¡Déjame darte un tentempié!' WHERE `ID`=15604;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 베시가 오늘은 배가 고프구나. 가서 사과를 좀 가져오마.', `MaleText_loc4`='贝希今天很饿呢，不是吗？我来喂你一个苹果吧。', `MaleText_loc5`='貝絲今天很餓，是嗎?讓我來幫你拿顆蘋果。', `MaleText_loc7`='Hoy Bessy es una chica hambrienta, ¿verdad? Déjame ir a buscar una manzana para ti.' WHERE `ID`=15605;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어여, 안녕한가, 벤자민! 베시에게 사과를 좀 가져다줘도 되겠나?', `MaleText_loc4`='你好，本杰明！我拿个苹果给贝希吃，你不介意吧？', `MaleText_loc5`='你好，班傑明!你介意我拿一顆蘋果給貝絲嗎?', `MaleText_loc7`='¡Buenos días, Benjamin! ¿Te importa que me lleve una manzana para Bessy?' WHERE `ID`=15606;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이보게, 벤자민! 우리 늙은 베시에게 간식으로 사과를 갖다줘도 되겠지?', `MaleText_loc4`='你好，本杰明！我拿个苹果给老贝希吃，你不介意吧？', `MaleText_loc5`='喂，班傑明!你介意我給老貝絲一顆蘋果當點心嗎?', `MaleText_loc7`='¡Hola, Benjamin! ¿Te importa si cojo una manzana para la vieja Bessy?' WHERE `ID`=15608;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이보게, 벤자민. 내 오랜 친구여, 베시에게 사과 하나만 줄 수 있겠나?', `MaleText_loc4`='嗨，老朋友本杰明，我拿个苹果给贝希吃，你不介意吧？', `MaleText_loc5`='班傑明，我的老友，你今天可以給貝絲一顆蘋果吃嗎?', `MaleText_loc7`='Benjamin, viejo amigo, ¿crees que podrías darme una manzana para Bessy hoy?' WHERE `ID`=15609;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 나무에서 사과를 하나 땁니다.', `MaleText_loc4`='%s从树上摘了个苹果。', `MaleText_loc5`='%s從樹上摘了一顆蘋果下來。', `MaleText_loc7`='%s coge una manzana del árbol.' WHERE `ID`=15610;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙네, 벤자민!', `MaleText_loc4`='谢谢你，本杰明！', `MaleText_loc5`='謝了，班傑明!', `MaleText_loc7`='¡Gracias, Benjamin!' WHERE `ID`=15611;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사무엘, 저 낡은 마차는 아직도 고장이 자주 나나 보군?', `MaleText_loc4`='萨缪尔，那辆破旧的马车依然令你焦头烂额吗？', `MaleText_loc5`='山繆，那輛老貨車還會故障嗎?', `MaleText_loc7`='Samuel, ¿ese viejo carro sigue estropeado?' WHERE `ID`=15612;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 마차가 또 고장 났나, 사무엘?', `MaleText_loc4`='萨缪尔，你又在为那辆破旧的马车烦恼了是吧？', `MaleText_loc5`='那輛貨車又壞了，山繆?', `MaleText_loc7`='¿Se te ha vuelto a estropear ese carro, Samuel?' WHERE `ID`=15613;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 오래된 마차로군. 사무엘, 저 마차 고장 난 게 분명해.', `MaleText_loc4`='这马车太破旧了，贝希。它没少给你添麻烦吧？', `MaleText_loc5`='這麼老的一輛貨車，難怪它會拖垮你，山繆。', `MaleText_loc7`='Es un carro tan viejo que no me extraña que se te haya vuelto a estropear, Samuel.' WHERE `ID`=15614;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음... 안됐군. 일손이 필요하다면 나중에 들르도록 하지.', `MaleText_loc4`='我对你的遭遇深表同情。如果你需要帮忙的话，我待会就过来。', `MaleText_loc5`='嗯，我很遺憾聽到這個消息。如果你需要幫忙我等下會再來的。', `MaleText_loc7`='Vaya. Una pena. Me pasaré luego por si necesitas una mano.' WHERE `ID`=15615;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='베시가 이 작은 사과를 맛있게 먹을 거야.', `MaleText_loc4`='嗯，贝希会喜欢这份零食的。', `MaleText_loc5`='嗯，貝絲會很喜歡這個小點心的。', `MaleText_loc7`='Bueno, Bessy disfrutará de este pequeño aperitivo.' WHERE `ID`=15616;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 먹어라 베시야. 내가 준비를 끝내는 동안 넌 이 사과를 먹으렴.', `MaleText_loc4`='嗨，贝希，在我做准备工作的时候，你可以尝尝这只苹果。', `MaleText_loc5`='來，貝絲，在我幫你準備的時候好好享用這顆蘋果吧。', `MaleText_loc7`='Toma, Bessy, disfruta de esta manzana mientras te preparo.' WHERE `ID`=15617;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 베시에게 탐스러운 빨간 사과를 먹입니다.', `MaleText_loc4`='%s喂贝希吃大红苹果。', `MaleText_loc5`='%s餵貝絲吃一顆鮮亮的紅蘋果。', `MaleText_loc7`='%s le da a Bessy la manzana roja.' WHERE `ID`=15618;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 이봐, 블랑쉬. 사과 하나 가지고 부러워할 거 없어. 넌 조만간 멋진 모험을 떠나게 될 테니까 말이야.', `MaleText_loc4`='听着，布兰契。别嫉妒，很快你就要独自探险了。', `MaleText_loc5`='好了，布蘭契。別吃醋了，你很快就會體驗一個大冒險了。', `MaleText_loc7`='Venga, venga, Blanchy, no te pongas celoso. Muy pronto vivirás una gran aventura tú solo.' WHERE `ID`=15619;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='워워! 진정해, 블랑쉬. 오늘은 너에게 줄 사과가 없단다. 내일 우리가 널 남녘해안으로 데려갈 텐데 너는 배를 타고 바다를 건널 거야.', `MaleText_loc4`='布兰契，不行，今天你不能吃苹果。明天我会送你去南海镇，在那儿乘船横跨海洋。', `MaleText_loc5`='咳，好了，布蘭契，你今天不能再吃蘋果了。明天我們會帶你去南海鎮，你會在那裡坐船跨越大海。', `MaleText_loc7`='Vaya, cálmate, Blanchy, no puedes comerte ninguna manzana hoy. Mañana te llevaremos a Costasur, donde zarparás en un barco a través de los mares.' WHERE `ID`=15620;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 블랑쉬. 너무 걱정하지 마. 서부 몰락지대에 있는 내 형제가 널 잘 돌봐줄 거란다. 네가 마음껏 뛰어놀 수 있을 만큼 넓은 아름다운 농장을 가지고 있다는 말을 들었단다.', `MaleText_loc4`='啊，布兰契，别担心。我兄弟就住在西部荒野，他会好好照顾你的。我听说他拥有一座漂亮的大农场，你可以随意在农场里闲逛。', `MaleText_loc5`='喔，布蘭契，別擔心，我在西部荒野的哥哥會好好照顧你的。我聽說他有一個漂亮的農場，那裡有足夠的空間讓你漫步。', `MaleText_loc7`='Oooh, Blanchy, no te preocupes, mi hermano de los Páramos de Poniente te cuidará muy bien. Tiene una granja muy bonita con un montón de espacio para que pasees.' WHERE `ID`=15621;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='망아지 블랑쉬가 질투심에 발을 구릅니다.', `MaleText_loc4`='小马布兰契心怀嫉妒地跺着脚。', `MaleText_loc5`='小馬布蘭契嫉妒地跺著她的腳。', `MaleText_loc7`='La joven Blanchy pisotea celosa.' WHERE `ID`=15622;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알았어, 베시야. 잠깐 산책을 하도록 하자. 가자, 가자!', `MaleText_loc4`='很好，贝希，我们出去散散步吧。来，来！', `MaleText_loc5`='好了貝絲，讓我帶你散個步吧。駕，駕!', `MaleText_loc7`='Está bien, Bessy, nos vamos de paseo. ¡Ven! ¡Ven!' WHERE `ID`=15623;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='착하지, 우리 베시!', `MaleText_loc4`='很好，贝希！', `MaleText_loc5`='乖孩子，貝絲!', `MaleText_loc7`='¡Buena chica, Bessy!' WHERE `ID`=15624;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일은 잘됐나, 사무엘?', `MaleText_loc4`='有什么收获吗，萨缪尔？', `MaleText_loc5`='運氣如何，山繆?', `MaleText_loc7`='¿Ha habido suerte, Samuel?' WHERE `ID`=15625;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='베시가 행복한 듯한 소리를 냅니다.', `MaleText_loc4`='贝希欢快地嘶叫起来。', `MaleText_loc5`='貝絲開心地嘶叫。', `MaleText_loc7`='Bessy relincha de alegría.' WHERE `ID`=15626;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론이네. 어서 하나 가져가게나. 사과라면 모두가 먹을 만큼 많이 있으니 말이야!', `MaleText_loc4`='当然，去拿一个吧，有很多呢！', `MaleText_loc5`='沒問題，去拿吧，還有很多!', `MaleText_loc7`='Claro, adelante, toma una, ¡hay de sobra para todos!' WHERE `ID`=15627;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 일을 하면서 혼자 투덜거립니다.', `MaleText_loc4`='%s一边工作一边发着牢骚。', `MaleText_loc5`='%s一邊工作一邊自顧自的抱怨著。', `MaleText_loc7`='%s habla para sí mismo mientras trabaja.' WHERE `ID`=15628;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇네, 여전히 고장이야. 하지만 어쩌겠나... 마차를 새로 살 형편이 아닌 것을...', `MaleText_loc4`='啊，修不好。我哪儿有钱买辆新的。', `MaleText_loc5`='是，它仍是壞的。沒錢買新的。', `MaleText_loc7`='Vaya, todavía está roto. Pero no puedo permitirme comprar uno nuevo.' WHERE `ID`=15629;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여전히 고장이라네. 전혀 나아진 점이 없어.', `MaleText_loc4`='啊，修不好。真是倒霉透顶。', `MaleText_loc5`='不，它仍是壞的。一點運氣也沒有，我想。', `MaleText_loc7`='Nada, sigue roto. Nada de suerte, supongo.' WHERE `ID`=15630;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 흥분해서 고개를 흔듭니다.', `FemaleText_loc4`='%s摇了摇头，对那些骚乱感到不胜其烦。', `FemaleText_loc5`='%s非常激動的搖著頭。', `FemaleText_loc7`='%s agita su cabeza ante semejante conmoción.' WHERE `ID`=15631;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 엄마를 지켜줄거야!', `MaleText_loc4`='我会保证你的安全，妈妈！', `MaleText_loc5`='我會保護你的安全，媽媽!', `MaleText_loc7`='¡Yo te mantendré a salvo, mamá!' WHERE `ID`=15632;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엄마, 아빠는 언제 와?', `MaleText_loc4`='爸爸什么时候回来，妈妈？', `MaleText_loc5`='媽，爸爸什麼時候會回來?', `MaleText_loc7`='¿Cuándo vuelve papá, mamá?' WHERE `ID`=15633;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='세스, 너무 멀리 가지 마라. 엄마는 네 목소리가 들리지 않으면 불안해.', `FemaleText_loc4`='不要走太远了，塞瑟。你知道妈妈不喜欢你走得太远。', `FemaleText_loc5`='別走太遠塞斯。你知道媽媽不喜歡聽不見你的聲音。', `FemaleText_loc7`='No te alejes demasiado, Seth. Sabes que a mamá no le gusta dejar de oírte.' WHERE `ID`=15634;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='응, 갈게! 엄마!', `MaleText_loc4`='过来了，妈妈！', `MaleText_loc5`='我來了，媽媽!', `MaleText_loc7`='¡Vengo, mamá!' WHERE `ID`=15635;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='앞이... 앞이 보여요...', `FemaleText_loc4`='我……我能看到了……', `FemaleText_loc5`='我...我看見了...', `FemaleText_loc7`='Puedo... Puedo ver...' WHERE `ID`=15636;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다시는 아들의 얼굴을 못 볼 것이라 생각했습니다. 이리 오너라, 세스! 네 예쁜 얼굴 좀 보자꾸나!', `FemaleText_loc4`='我还以为再也看不到我儿子的脸了。过来，塞瑟！让妈妈好好看看你！', `FemaleText_loc5`='我以為我再也見不到我的兒子了。過來這裡，塞斯!讓媽媽好好看看你!', `FemaleText_loc7`='Pensé que no volvería a ver la cara de mi hijo. ¡Ven, Seth! Deja que te vea mamá.' WHERE `ID`=15637;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='울지 마, 엄마! 나 여기 있잖아. 내 얼굴 보여?', `MaleText_loc4`='不要哭，妈妈。我就在这里，看！', `MaleText_loc5`='別哭媽咪。我就在這裡，看到了嗎?', `MaleText_loc7`='No llores, mamá. Estoy aquí, ¿ves?' WHERE `ID`=15638;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이걸 마셔요, 잘리아. 생각만큼 강력하지는 않지만 도움이 될 것입니다.', `FemaleText_loc4`='喝下这个，萨恩莉亚。那不像我希望的那样有效，但也许会有点帮助。', `FemaleText_loc5`='喝掉這個，札麗亞。它不像我預期的那樣有效，但或許會有點幫助。', `FemaleText_loc7`='Bebe esto, Zahlia. No es tan potente como esperaba, pero puede que sirva.' WHERE `ID`=15639;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 잘못된 길로 가고 있소, $n. 내 엘레크는 적의 영역으로 들어가지 않을 것이오.', `MaleText_loc4`='你走错方向了，$n。我的雷象是不会进入敌方领土的。', `MaleText_loc5`='你走錯地方了，$n。我的伊萊克絕不會走進敵方的領土。', `MaleText_loc7`='Ese no es el camino correcto, $n. Mi elekk no querrá pasar por territorio hostil.' WHERE `ID`=15640;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='반갑습니다. 우리는 성스러운 빛의 사제들이자 샤타르를 섬기는 알도르 사제회입니다.$B$B원한다면 언제든지 우리와 함께 지내실 수 있습니다.', `FemaleText_loc4`='你好，$n。我们是奥尔多，圣光的牧师和沙塔尔的仆人。$B$B我们随时欢迎你来这里。', `FemaleText_loc5`='歡迎，$n。我們是奧多爾，聖光的祭司和薩塔的僕人。$B$B歡迎你留下來和我們一起，要多久都可以。', `FemaleText_loc7`='$gBienvenido:Bienvenida;, $n. Somos los Aldor, sacerdotes de la luz y siervos de Sha''tar.$B$BPuedes quedarte con nosotros todo el tiempo que quieras.' WHERE `ID`=15641;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샤타르가 누구죠?', `MaleText_loc4`='谁是沙塔尔？', `MaleText_loc5`='誰是薩塔?', `MaleText_loc7`='¿Quiénes son los Sha''tar?', `FemaleText_loc1`='샤타르가 누구죠?', `FemaleText_loc4`='谁是沙塔尔？', `FemaleText_loc5`='誰是薩塔?', `FemaleText_loc7`='¿Quiénes son los Sha''tar?' WHERE `ID`=15642;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='''빛에서 태어난 자들''이 샤타르에 가까운 뜻일 것입니다. 일리단의 부하들을 물리치고 샤트라스를 되찾은 나루에게 우리가 붙인 이름이죠.', `FemaleText_loc4`='“生于圣光”应该是最接近沙塔尔这个词原意的翻译。那是我们给从伊利丹的爪牙手中夺取并重建沙塔斯城的纳鲁所起的名字。', `FemaleText_loc5`='「生於聖光」會是薩塔最貼切的寫照。那是我們給予那些從伊利丹密探手中奪回撒塔斯城的那魯的名稱。', `FemaleText_loc7`='''Sha''tar significa Nacidos de la luz''. Es el nombre que dimos a los naaru que recuperaron Shattrath de los ejércitos de Illidan.' WHERE `ID`=15643;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샤트라스는 드레나이의 도시가 아닙니까? 왜 이곳에 다른 이들을 받아들인 거죠?', `MaleText_loc4`='沙塔斯城不是一个德莱尼人的城市吗？为什么允许其他人生活在这里？', `MaleText_loc5`='撒塔斯不是德萊尼的城市嗎?為什麼你們會容許其他人在這裡?', `MaleText_loc7`='¿Shattrath no es una ciudad draenei? ¿Por qué permitís que entren otros aquí?', `FemaleText_loc1`='샤트라스는 드레나이의 도시가 아닙니까? 왜 이곳에 다른 이들을 받아들인 거죠?', `FemaleText_loc4`='沙塔斯城不是一个德莱尼人的城市吗？为什么允许其他人生活在这里？', `FemaleText_loc5`='撒塔斯不是德萊尼的城市嗎?為什麼你們會容許其他人在這裡?', `FemaleText_loc7`='¿Shattrath no es una ciudad draenei? ¿Por qué permitís que entren otros aquí?' WHERE `ID`=15644;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='샤트라스는 불타는 군단과 일리단을 상대로 전쟁을 벌이는 무대 이상의 역할을 합니다. 샤트라스는 우리를 위협하는 폭력에서 벗어나려는 이들에게 성소와 같은 역할을 합니다.$B$B피난민들을 돌려보낸다면 우리는 위선자가 되는 것입니다.$B$B당신의 질문이 점술가 길드에 대한 것이라면 이렇게 대답하죠. 저는 약속을 이행할 것을 강력하게 요구하는 점술가 길드와 그 지도자를 인정하지 않으나 나루의 지혜에 대해서는 의심하지 않습니다.$B$B지금은 어려운 시기입니다. $n, 우리는 동맹이 필요합니다.', `FemaleText_loc4`='沙塔斯城不仅仅是个为了对抗燃烧军团和伊利丹而设立的运输中转站，还是给那些企图寻找庇护的人们的避难所。$B$B如果我们赶走那些难民的话，我们就是伪君子了。$B$B如果你想问的是占星者，那么我要说，虽然我不喜欢他们，也不喜欢他们首领那救赎愿景的疯狂想法，但是这并不能让我怀疑纳鲁的智慧。$B$B这是一个艰难的时刻，$n。我们需要团结一切可以团结的力量。', `FemaleText_loc5`='撒塔斯不只是個和燃燒軍團與伊利丹作戰的舞台而已。它也是那些想逃離周遭暴力的人的聖域。$B$B如果我們把難民趕走那會使我們成為偽君子。$B$B如果你的問題是那些占卜者，那麼我告訴你，雖然我也不喜歡他們或他們領導者為救贖幻像做出的野蠻要求，但那魯的智慧是不容我們懷疑的。$B$B現在是艱難的時刻，$n。我們需要所有的盟友。', `FemaleText_loc7`='Shattrath es algo más que un cuartel general para la guerra que libramos contra Illidan y la Legión Ardiente. Es un santuario para los que quieren refugiarse de la violencia que nos rodea.$B$BSi no aceptáramos a los refugiados, seríamos unos hipócritas.$B$BSi preguntas por los Arúspices, te diré que, aunque no me gusten ellos ni su líder, no tenemos la autoridad para cuestionar la sabiduría de los naaru.$B$BSon tiempos difíciles, $n. Necesitamos a todos los aliados que podamos encontrar.' WHERE `ID`=15645;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리도 왕년에는 악마 놈들과 싸웠었지! 진짜 악마 말이야!', `MaleText_loc4`='想当年，我们和恶魔战斗！真正的恶魔！', `MaleText_loc5`='在我的年代裡，我們對抗惡魔!真正的惡魔!', `MaleText_loc7`='¡En mis tiempos, luchábamos contra demonios! ¡De los de verdad!' WHERE `ID`=15646;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 낚시하기에 좋은 날씨로군!', `MaleText_loc4`='真是个钓鱼的好日子！', `MaleText_loc5`='真是個釣魚的好天氣!', `MaleText_loc7`='¡Un tiempo perfecto para pescar!' WHERE `ID`=15647;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이보다 더 좋은 날씨는 없을 거유!', `MaleText_loc4`='没有比这更好的天气了！', `MaleText_loc5`='今天真是太完美了!', `MaleText_loc7`='¡No podía imaginarme un día mejor!' WHERE `ID`=15648;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='낚시하기에 좋은 최고의 저녁이로군!', `MaleText_loc4`='没什么比一个适合钓鱼的晚上更让我开心的了！', `MaleText_loc5`='沒什麼比在美好的夜晚釣魚更棒的了!', `MaleText_loc7`='¡Nada mejor que una buena tarde de pesca!' WHERE `ID`=15649;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 날씨가 화창하군요! 따뜻한 기온과 시원한 연못이라니...', `MaleText_loc4`='确实！没什么比温暖的空气和凉爽的池塘更好了……', `MaleText_loc5`='的確!沒什麼像溫暖的空氣和涼爽的池塘這麼好的了...', `MaleText_loc7`='¡Cierto! No hay nada como una brisa cálida y un estanque fresco...' WHERE `ID`=15650;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벌레들보다 물고기가 많이 걸려야 할 텐데...', `MaleText_loc4`='我只是希望那些鱼不要只把鱼饵吃光却不上钩……', `MaleText_loc5`='我只希望魚兒不只是咬走蟲餌而已...', `MaleText_loc7`='Solo espero que piquen más los peces que los mosquitos...' WHERE `ID`=15651;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇군요. 오늘 같은 날씨가 계속된다면 좋을 텐데...', `MaleText_loc4`='是啊，如果每天都像今天那样……', `MaleText_loc5`='好，只要每天都像今天一樣...', `MaleText_loc7`='Sí, ojalá todos los días fueran como hoy...' WHERE `ID`=15652;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자 자, 조용히 합시다. 당신이 떠드는 소리가 물고기들을 쫓아내면 어쩌려고 그러시오?', `MaleText_loc4`='小声点，你的废话会把鱼吓走的！', `MaleText_loc5`='安靜，你的狂吠聲會嚇跑魚群的!', `MaleText_loc7`='¡Guarden silencio, su cháchara asustará a los peces!' WHERE `ID`=15653;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어허! 진정한 낚시꾼은 아무리 비가 많이 와도 낚싯대를 드리우는 법이라오!', `MaleText_loc4`='啊，真正的渔夫会出现在瓢泼的大雨中！', `MaleText_loc5`='呸，真正的漁夫都可以承受最殘酷的風雨!', `MaleText_loc7`='Bah, los buenos pescadores lo aguantan todo.' WHERE `ID`=15654;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐라고 했습니까?', `MaleText_loc4`='你刚才说什么？', `MaleText_loc5`='你說什麼?', `MaleText_loc7`='¿Qué has dicho?' WHERE `ID`=15655;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 우리가 큰곰 숯검댕이를 보게 될 거라 생각하슈?', `MaleText_loc4`='你觉得我们今天能见到老黑炭吗？', `MaleText_loc5`='你想我們今天會看到奧爾蘇迪嗎?', `MaleText_loc7`='¿Crees que veremos al viejo Tiznado hoy?' WHERE `ID`=15656;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번에는 틀림없이 대어를 건질 거유...', `MaleText_loc4`='我打赌我这次会抓到一条大鱼……', `MaleText_loc5`='我跟你打賭我這次會釣到一隻大魚...', `MaleText_loc7`='Esta vez estoy seguro de que pescaré algo gordo...' WHERE `ID`=15657;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또다시 레기의 장화를 낚으면 안 되는데...', `MaleText_loc4`='我不想再钓起臭皮靴了……', `MaleText_loc5`='最好不要再讓我釣到瑞基的靴子了...', `MaleText_loc7`='Espero no sacar otro par de botas de Reggy...' WHERE `ID`=15658;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어쩌면요...', `MaleText_loc4`='也许……', `MaleText_loc5`='或許吧...', `MaleText_loc7`='Quizás...' WHERE `ID`=15659;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무 놈이나 좀 걸려라...', `MaleText_loc4`='任何事情都可能发生……', `MaleText_loc5`='任何事都有可能發生...', `MaleText_loc7`='Puede pasar cualquier cosa...' WHERE `ID`=15660;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하, 목표를 너무 높게 잡지 마세요...', `MaleText_loc4`='哈哈哈，不要抱有太大的希望……', `MaleText_loc5`='哈哈，別期望太高...', `MaleText_loc7`='Ja, ja, ja. No deberías tener tantas esperanzas.' WHERE `ID`=15661;
