UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디 미끼 남는 분 계세요?', `MaleText_loc4`='你们有多余的鱼饵吗？', `MaleText_loc5`='你們有多的魚餌嗎?', `MaleText_loc7`='¿Tenéis un cebo de sobra?' WHERE `ID`=15663;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전에 우리가 저 아래 엘윈 숲에서 붉은색 지느러미가 달린 멀록을 잡은 일 기억하세요?', `MaleText_loc4`='还记得那个时候我们在艾尔文森林抓红鳞鱼人的事吗？', `MaleText_loc5`='記得我們上次在艾爾文森林抓到一隻紅鰭的魚人嗎?', `MaleText_loc7`='¿Te acuerdas de cuando pescamos aquel múrloc rojo en Elwynn?' WHERE `ID`=15664;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신이여, 감사합니다. 베르사가 여기 없는 게 얼마나 다행인지...', `MaleText_loc4`='感谢圣光，波尔塔不在这里……', `MaleText_loc5`='感謝聖光貝紗不在這裡...', `MaleText_loc7`='Gracias a la Luz que Bertha no está aquí...' WHERE `ID`=15665;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='화창한 날씨에 잔소리할 집사람도 없고 얼마나 평화로운지 모르겠군...', `MaleText_loc4`='在这样温暖的日子里没有老婆在耳边大吵大闹，这真是太好了……', `MaleText_loc5`='沒有什麼是比一個溫暖的日子加上沒有老女人對你大吼來的好...', `MaleText_loc7`='No hay nada como un día caluroso sin la mujer pegando voces...' WHERE `ID`=15666;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조용한 게 정말 좋습니다그려... 집과는 다르게 말이유!', `MaleText_loc4`='没有什么比安安静静地更好了，家里太吵了！', `MaleText_loc5`='沒有什麼是比平靜那樣安寧來的好...不像在家裡!', `MaleText_loc7`='No hay nada como la paz y el silencio... ¡No como en casa!' WHERE `ID`=15667;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 말이 그 말입니다! 사라가 집안일로 불평하는 소리에 잠시도 편할 때가 없으니 원!', `MaleText_loc4`='说得好啊！萨拉无时无刻不在抱怨家务活！', `MaleText_loc5`='我聽到了!薩拉永遠都在抱怨那些雜務，我的耳根子永遠不得安寧!', `MaleText_loc7`='¡Ya te digo! ¡No puedo descansar ni un momento sin que Sarah se queje de las tareas domésticas!' WHERE `ID`=15668;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맞아요. 소리를 질러서 우리 사나이들과 물고기의 평화를 방해하는 아이들도 없지요...', `MaleText_loc4`='啊，你这喋喋不休的小家伙！没看见我正在享受钓鱼的乐趣吗？别打扰我……', `MaleText_loc5`='是，一個安靜的年輕人打亂了一個男人和他的魚群的平靜...', `MaleText_loc7`='Sí, y tampoco hay ningún crío llorón que se entrometa entre un hombre y su pesca...' WHERE `ID`=15669;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 말이 맞지만 적어도 당신을 기다리는 따뜻한 저녁상이 있지 않습니까...', `MaleText_loc4`='换句话说，至少你回家就可以吃到一顿美味佳肴……', `MaleText_loc5`='是這樣說沒錯，不過至少還有熱騰騰的晚餐等著你...', `MaleText_loc7`='Eso lo decís ahora, pero al menos tenéis un plato caliente esperándoos...' WHERE `ID`=15670;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 정도면 괜찮은 편이죠. 당신 부인은 어떤 치즈 상인과 함께 스톰윈드로 달아날 뻔했잖아요!', `MaleText_loc4`='可能更糟，你的妻子可能会和什么奶酪商人私奔去暴风城！', `MaleText_loc5`='可能更糟，你的妻子可能會和某個起司商人私奔到暴風城去!', `MaleText_loc7`='Podría ser peor. Tu mujer podría fugarse a Ventormenta con un mercader de queso.' WHERE `ID`=15671;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런 얘기는 좀 크게 하지 말라고요!', `MaleText_loc4`='最好不要说得那么大声！', `MaleText_loc5`='最好別太大聲的說!', `MaleText_loc7`='¡No lo digas demasiado alto!' WHERE `ID`=15672;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='형제자매들이여, 잘 들으시오. 우리 종족의 생존에 대해서 논해 봅시다. 지난번 재앙에서는 가까스로 살아남았을지 몰라도 다음엔 우리 모두 멸망할까 두렵습니다.', `FemaleText_loc4`='我的兄弟姐妹们，听我说。我们必须开始关注自身的生存了。虽然我们在一场灾难中勉强幸存了下来，但是我担心下一场灾难会把我们彻底摧毁。', `FemaleText_loc5`='各位手足同胞們，請聽我說。我們必須談談種族延續的議題。我們已經勉強的倖存於上一次的大災難，但是我怕下一次就會全軍覆沒。', `FemaleText_loc7`='Hermanos y hermanas, escuchadme. Tenemos que hablar de la supervivencia de nuestro pueblo. Hemos sobrevivido a una catástrofe, pero me temo que la siguiente acabará por destruirnos.' WHERE `ID`=15673;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='상황이 어떻게 돌아가고 있는지 모르겠소? 눈을 크게 뜨시오. 보려고 하면 보일 거요. 대체 이 새 동맹은 뭐지? 우리가 오랜 동맹을 배신한 이유가 고작 공공의 적과 친해지기 위해서란 말이오?', `FemaleText_loc4`='你们看不到眼前正在发生些什么事情吗？睁开你们的眼睛，一切都明明白白展现在你们眼前。我们的新同盟是什么？为什么我们背叛了过去的盟友，却要与所有生命的大敌亲密相处？', `FemaleText_loc5`='你看不見發生什麼嗎?張開你的眼睛。它赤裸裸地讓所有人注意到。這個新聯盟是什麼?為什麼我們背叛老盟友，只為將所有活著的變成敵人?', `FemaleText_loc7`='¿No ves lo que está ocurriendo? Abre los ojos. Está pasando delante de nuestras narices. ¿Por qué hemos traicionado a nuestros antiguos aliados solo para unirnos a enemigos de los vivos?' WHERE `ID`=15674;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니, 당신이 틀렸습니다! 배신을 당한 것은 우리 쪽이라고요!', `MaleText_loc4`='不，你错了！我们才是遭到背叛的人！', `MaleText_loc5`='不，你錯了!我們是受到背叛的人!', `MaleText_loc7`='¡No, te equivocas! ¡Nosotros fuimos los traicionados!' WHERE `ID`=15675;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드워프들이 우리의 동맹이었던 적이 있던가?', `MaleText_loc4`='什么时候连矮人都变成了我们的朋友？', `MaleText_loc5`='沒有魔法我們要怎麼活?', `MaleText_loc7`='¿Desde cuando son los enanos nuestros amigos?' WHERE `ID`=15676;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='암흑의 시기에 인간들은 우리를 버렸잖아! 인간 종족의 왕자는 몸소 우리 땅을 습격했고...', `FemaleText_loc4`='人类在我们最黑暗的时刻抛弃了我们！他们的王子亲自领导了对我们领土的袭击。', `FemaleText_loc5`='人類在我們最黑暗的時刻拋棄了我們!他們的王子親自領導攻擊我們的土地。', `FemaleText_loc7`='¡Los humanos nos abandonaron en nuestro peor momento! ¡Su propio Príncipe lideró el ataque a nuestras tierras!' WHERE `ID`=15677;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바보 같으니! 왕자의 부하들은 현재 우리가 동맹을 맺은 바로 그 포세이큰이었고 이제 그 왕자가 우릴 배반했소!', `MaleText_loc4`='你这个蠢货！王子的爪牙就是那些被遗忘者，就是我们现在的同盟！而且他现在已经背叛了我们！', `MaleText_loc5`='你這個笨蛋!王子的手下就是現在與我們結盟的被遺忘者，而現在他已經背叛我們了!', `MaleText_loc7`='¡Necio! ¡Los secuaces del Príncipe son los mismos Renegados con los que ahora estamos aliados y ahora él nos ha traicionado!' WHERE `ID`=15678;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실버문의 순찰대 사령관은 동맹으로서 의리를 지킬 것입니다!', `MaleText_loc4`='她曾经是银月城的游侠将军，现在也会是我们忠诚的盟友！', `MaleText_loc5`='銀月城的遊俠將軍將會是忠誠的盟友!', `MaleText_loc7`='¡El General Forestal de Lunargenta será un aliado leal!' WHERE `ID`=15679;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그녀를 진정 친구로서 여기는 거요? 정말 바보 같군. 현재 어둠의 여왕은 예전의 그 실바나스가 아니오.', `FemaleText_loc4`='你把她当作朋友？你真是个蠢货。这个“黑暗女王”不是希尔瓦娜斯。', `FemaleText_loc5`='你稱她做朋友?你是一個傻瓜。這位「黑暗女王」不是希瓦娜斯。', `FemaleText_loc7`='¿La consideras una amiga? Idiota. Esa ""Dama Oscura"" no es Sylvanas.' WHERE `ID`=15680;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 이제 우리가 뭘 알아낼 수 있는지 확인해 봅시다...', `MaleText_loc4`='现在，让我们看看可以发现些什么……', `MaleText_loc5`='來看看我們能發現什麼...', `MaleText_loc7`='A ver qué averiguamos...' WHERE `ID`=15681;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭔가... 보입니다만 매우 희미하군요.', `MaleText_loc4`='我看到……一些东西，但是非常弱。', `MaleText_loc5`='我看見...一個東西。不過它非常模糊就是了。', `MaleText_loc7`='Veo... algo. Está muy débil.' WHERE `ID`=15682;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='데이롬이 살아 있군요! 아라코아가 그의 앞을 왔다갔다하면서 같은 질문을 반복해서 하는 모습이 보입니다. 또 한 명이 있는데, 오크로군요...', `MaleText_loc4`='迪鲁姆还活着！我看到一个鸦人在他的面前来回走动，反复地问着他相同的问题。还有另一个人，一个兽人……', `MaleText_loc5`='迪羅姆還活著!我可以想像一個阿拉卡人在他面前來回踱步，一次又一次的問著他同樣的問題。還有另外一個人也活著，一個獸人...', `MaleText_loc7`='¡Deirom está vivo! Puedo hacer que un arakkoa se pasee delante de él haciéndole una y otra vez las misma preguntas. Hay otro..., un orco.' WHERE `ID`=15683;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들이 데이롬을 세 마을 중 한 곳에 가두어 놓은 것이 분명합니다. 장막의... 장막의 샬라스입니다! 탠더에게 즉시 이 사실을 알려야 합니다! 어서 가서 그에게 알리십시오.', `MaleText_loc4`='他们把他抓到了一颗树上，沙……沙拉斯鸦巢！山德必须马上知道这个！快去告诉他吧。', `MaleText_loc5`='他們把他抓進其中一個樹居裡了。迷霧...迷霧撒拉斯!薩德爾一定要立刻知道這件事!快去和他談談。', `MaleText_loc7`='Lo tienen en uno de sus asentamientos de árboles. Velo... ¡Velo Shalas! ¡Thander debe ser informado inmediatamente! Ve a hablar con él.' WHERE `ID`=15684;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 알레리아 성채에 오신 것을 환영합니다.', `MaleText_loc4`='欢迎来到奥蕾莉亚要塞，$c。', `MaleText_loc5`='歡迎來到艾蘭里堡壘，$c。', `MaleText_loc7`='$gBienvenido:Bienvenida; al Bastión Allerian, $c.' WHERE `ID`=15685;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 이제 우리가 뭘 알아낼 수 있는지 확인해 봅시다...', `MaleText_loc4`='现在，让我们看看可以发现些什么……', `MaleText_loc5`='來看看我們能發現什麼...', `MaleText_loc7`='A ver qué averiguamos...' WHERE `ID`=15686;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 두가르가 살아 있습니다! 아라코아가 그의 앞을 왔다갔다하면서 같은 질문을 계속해서 반복하는 모습이 보입니다. 또 한 명이 있는데, 인간이로군요...', `MaleText_loc4`='杜加尔还活着！我看到一个鸦人在他的面前来回走动，反复地问着他相同的问题。还有另一个人，一个人类……', `MaleText_loc5`='杜葛爾還活著!我可以想像一個阿拉卡人在他面前來回踱步，一次又一次的問著他同樣的問題。還有另外一個人也活著，一個人類...', `MaleText_loc7`='¡Dugar vive! Puedo hacer que un arakkoa se pasee delante de él haciéndole una y otra vez las misma preguntas. Hay otro..., un humano.' WHERE `ID`=15687;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그는 수풀이 우거진 마을에 갇혀 있습니다. 장막의... 장막의 샬라스입니다! 로카그에게 즉시 이 사실을 알려야 합니다! 어서 가서 보고하십시오.', `MaleText_loc4`='他们把他抓到了一颗树上，沙……沙拉斯鸦巢！罗卡格必须马上知道这个！快去告诉他吧。', `MaleText_loc5`='他們把他抓進其中一個樹居裡了。迷霧...迷霧撒拉斯!瑞克格一定要立刻知道這件事!快去和他談談。', `MaleText_loc7`='Lo tienen en uno de sus asentamientos de árboles. Velo... ¡Velo Shalas! ¡Rokag debe ser informado inmediatamente! Ve a hablar con él.' WHERE `ID`=15688;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하십시오. 이 숲에는 알 수 없는 위험이 잔뜩 숨어 있고 곳곳이 적으로 가득합니다.', `MaleText_loc4`='机警点，$c。这片森林中充满隐藏的危险和潜在的敌人。', `MaleText_loc5`='小心點，$c。森林裡充滿了隱藏的危險和潛在的敵人。', `MaleText_loc7`='Cuidado, $c. El bosque está lleno de peligros ocultos y de enemigos.' WHERE `ID`=15689;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='남녘해안은 평화로운 마을입니다... 언젠가 이곳에서 살고 싶답니다.', `MaleText_loc4`='南海镇是个多么宁静的城镇啊……我真希望有一天可以定居在这里。', `MaleText_loc5`='南海鎮真是個平靜的城鎮...有一天我真想住到這裡來。', `MaleText_loc7`='Costasur es una ciudad muy pacífica... Me gustaría vivir en ella algún día.' WHERE `ID`=15690;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수렁군주가 공격하고 있어요! 저흴 도와주세요!', `MaleText_loc4`='沼泽领主正在进攻我们！救救我们！', `MaleText_loc5`='泥沼領主正在攻擊我們!救救我們!', `MaleText_loc7`='¡Nos atacan los señores de la marisma! ¡Ayuda!' WHERE `ID`=15691;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 좀 도와주세요! 우리 아이들이 위험해요!', `MaleText_loc4`='谁来帮帮忙啊？我们的幼体危在旦夕！', `MaleText_loc5`='來人啊!我們的孩子有危險了!', `MaleText_loc7`='¡Ayuda! ¡Los jóvenes están en peligro!' WHERE `ID`=15692;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비하십시오! 전투가 곧 시작됩니다!', `MaleText_loc4`='准备好！就要开始了！', `MaleText_loc5`='做好準備!要開始打架了!', `MaleText_loc7`='¡Preparaos! ¡La pelea está a punto de empezar!', `FemaleText_loc1`='준비하십시오! 전투가 곧 시작됩니다!', `FemaleText_loc4`='准备好！就要开始了！', `FemaleText_loc5`='做好準備!要開始打架了!', `FemaleText_loc7`='¡Preparaos! ¡La pelea está a punto de empezar!' WHERE `ID`=15693;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 대단한 싸움이었습니다!', `MaleText_loc4`='哇，多棒的一场战斗啊！', `MaleText_loc5`='哇，打的真精采!', `MaleText_loc7`='¡Vaya, menuda pelea!', `FemaleText_loc1`='오, 대단한 싸움이었어요!', `FemaleText_loc4`='哇，多棒的一场战斗啊！', `FemaleText_loc5`='哇，打的真精采!', `FemaleText_loc7`='¡Vaya, menuda pelea!' WHERE `ID`=15694;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 어서 녀석을 날려버리라고!', `MaleText_loc4`='干掉他！', `MaleText_loc5`='把他的頭取下來!', `MaleText_loc7`='¡Acabad con su cabeza!', `FemaleText_loc1`='자, 어서 녀석을 날려버리라고!', `FemaleText_loc4`='干掉他！', `FemaleText_loc5`='把他的頭取下來!', `FemaleText_loc7`='¡Acabad con su cabeza!' WHERE `ID`=15695;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멋진 전투를 보여달라고!', `MaleText_loc4`='我要血！', `MaleText_loc5`='我渴望鮮血!', `MaleText_loc7`='¡Quiero sangre!', `FemaleText_loc1`='멋진 전투를 보여주세요!', `FemaleText_loc4`='我要血！', `FemaleText_loc5`='我渴望鮮血!', `FemaleText_loc7`='¡Quiero sangre!' WHERE `ID`=15696;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 그거야! 좀 더!', `MaleText_loc4`='对，对！再多些！', `MaleText_loc5`='對，對!我要更多!', `MaleText_loc7`='¡Sí, sí! ¡Quiero más!', `FemaleText_loc1`='그래, 그거예요! 좀 더!', `FemaleText_loc4`='对，对！再多些！', `FemaleText_loc5`='對，對!我要更多!', `FemaleText_loc7`='¡Sí, sí! ¡Quiero más!' WHERE `ID`=15697;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끝내버려! 천천히! 서서히 죽어가는 모습을 보고 싶군!', `MaleText_loc4`='解决他，但不要太快！我想看着他慢慢死去！', `MaleText_loc5`='了結它，但是別太快!我想看場緩慢的死亡!', `MaleText_loc7`='¡Acábalo, pero no demasiado rápido! ¡Quiero ver una muerte lenta!', `FemaleText_loc1`='끝내버려요! 천천히! 서서히 죽어가는 모습을 보고 싶군요!', `FemaleText_loc4`='解决他，但不要太快！我想看着他慢慢死去！', `FemaleText_loc5`='了結它，但是別太快!我想看場緩慢的死亡!', `FemaleText_loc7`='¡Acábalo, pero no demasiado rápido! ¡Quiero ver una muerte lenta!' WHERE `ID`=15698;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 꿈이 있습니다... 말들이 활기차게 뛰놀고, 아이들이 더 강하게 크고 시간 자체가 흘러가지 않는 그런 날이 오는 꿈이요.', `MaleText_loc4`='[PH] I have a dream... a dream of a day when horses run faster, men grow stronger and time itself stands still.', `MaleText_loc5`='我有個夢想...一個製作舒服鞋子的夢想，它們是世界無敵的!', `MaleText_loc7`='[PH] Tengo un sueño... un sueño del día en que los caballos corran más rápidos, los hombres crezcan más fuertes y el tiempo mismo se pare.' WHERE `ID`=15699;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='직스 치안대장님의 마음을 움직일 부드러운 가죽이 충분하다면...', `MaleText_loc4`='[PH] If only there was a leather soft enough to appeal to Marshal Zyx.', `MaleText_loc5`='我知道如何製作有史以來最舒適的鞋子...前提是要有夠軟的皮革來製作它們!', `MaleText_loc7`='[PH] Si hubiera un cuero lo suficientemente suave como para atraer al mariscal Zyx.' WHERE `ID`=15700;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모든 게 기억나는구나...', `MaleText_loc4`='我记得所有事情……', `MaleText_loc5`='我記得所有的事...', `MaleText_loc7`='Lo recuerdo todo...', `FemaleText_loc1`='모든 게 기억나는구나...', `FemaleText_loc4`='我记得所有事情……', `FemaleText_loc5`='我記得所有的事...', `FemaleText_loc7`='Lo recuerdo todo...' WHERE `ID`=15701;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거 소름끼치는군요.$B$B전 이곳에서 우리 자신의 불편에는 아무런 관심이 없습니다만 해골 무덤에 만연한 죽음의 공포를 완화하기 위해서 뭔가 해야만 합니다!', `MaleText_loc4`='这太糟了。$B$B我并不计较我们在这里有多不舒服，但我们必须做点什么，为那些白骨荒野的亡者减轻痛苦。', `MaleText_loc5`='這真是太糟了。$B$B我不是為了我們的不安著想，但是我們必須做一些事情以減輕白骨荒野死者的傷痛!', `MaleText_loc7`='Esto es sencillamente horrible.$B$BNo me importan nada nuestras propias incomodidades aquí, ¡pero debemos hacer algo para aliviar el dolor de los muertos de El Vertedero de Huesos!' WHERE `ID`=15702;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게 무슨 일이 벌어지고 있는 것이냐?', `MaleText_loc4`='我怎么了？', `MaleText_loc5`='我怎麼了?', `MaleText_loc7`='¿Qué me está pasando?', `FemaleText_loc1`='내게 무슨 일이 벌어지고 있는 것이냐?', `FemaleText_loc4`='我怎么了？', `FemaleText_loc5`='我怎麼了?', `FemaleText_loc7`='¿Qué me está pasando?' WHERE `ID`=15703;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼들이 부르고 있다... 난 지쳤구나.', `MaleText_loc4`='灵魂的召唤……我被吞噬了。', `MaleText_loc5`='靈魂召喚...我被吞噬了。', `MaleText_loc7`='Los espíritus me llaman... Estoy consumido.', `FemaleText_loc1`='영혼들이 부르고 있다... 난 지쳤구나.', `FemaleText_loc4`='灵魂的召唤……我被吞噬了。', `FemaleText_loc5`='靈魂召喚...我被吞噬了。', `FemaleText_loc7`='Los espíritus me llaman... Estoy consumida.' WHERE `ID`=15704;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무나 고통스럽구나.', `MaleText_loc4`='这痛苦简直无法忍受。', `MaleText_loc5`='這痛苦令人無法忍受。', `MaleText_loc7`='El dolor es insoportable.', `FemaleText_loc1`='너무나 고통스럽구나.', `FemaleText_loc4`='这痛苦简直无法忍受。', `FemaleText_loc5`='這痛苦令人無法忍受。', `FemaleText_loc7`='El dolor es insoportable.' WHERE `ID`=15705;
