UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽어가고 있어... 죽어가고 있구나... 죽어가...', `MaleText_loc4`='它快死了。它快死了。它快死了。', `MaleText_loc5`='它正逐漸死去。它正逐漸死去。它正逐漸死去。', `MaleText_loc7`='Está muriendo. Está muriendo. Está muriendo.', `FemaleText_loc1`='죽어가고 있어... 죽어가고 있구나... 죽어가...', `FemaleText_loc4`='它快死了。它快死了。它快死了。', `FemaleText_loc5`='它正逐漸死去。它正逐漸死去。它正逐漸死去。', `FemaleText_loc7`='Está muriendo. Está muriendo. Está muriendo.' WHERE `ID`=15707;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='알도르 사제회를 돕기 위해 오셨습니까?', `FemaleText_loc4`='你是来这里帮助奥尔多的吗？', `FemaleText_loc5`='你是來這幫助奧多爾的嗎?', `FemaleText_loc7`='¿Estás aquí para ayudar a los Aldor?' WHERE `ID`=15708;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳이 함락된다면 우리는 어떻게 되는 것이냐?', `MaleText_loc4`='我们会怎么样？', `MaleText_loc5`='當它陣亡時我們會變成什麼樣子?', `MaleText_loc7`='¿Qué será de nosotros cuando caiga?', `FemaleText_loc1`='이곳이 함락된다면 우리는 어떻게 되는 것이냐?', `FemaleText_loc4`='我们会怎么样？', `FemaleText_loc5`='當它陣亡時我們會變成什麼樣子?', `FemaleText_loc7`='¿Qué será de nosotros cuando caiga?' WHERE `ID`=15709;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='통제가 안 된다... 나를 끌어당기고 있어... 보이드가 성장하고 있다...', `MaleText_loc4`='我控制不了……它在拉我进去……虚空在扩大……', `MaleText_loc5`='無法控制...它把我吸進去...虛無不斷壯大...', `MaleText_loc7`='No puedo controlarlo... Me empuja... El vacío crece...', `FemaleText_loc1`='통제가 안 된다... 나를 끌어당기고 있어... 보이드가 성장하고 있다...', `FemaleText_loc4`='我控制不了……它在拉我进去……虚空在扩大……', `FemaleText_loc5`='無法控制...它把我吸進去...虛無不斷壯大...', `FemaleText_loc7`='No puedo controlarlo... Me empuja... El vacío crece...' WHERE `ID`=15710;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n, 이 문제를 해결하기 위해 아낌없이 지원해주신 도움과 희생에 정말 감사드립니다.', `FemaleText_loc4`='我很感激你的援助和为此所做出的牺牲，$n。', `FemaleText_loc5`='你對這件事的幫助和犧牲讓我十分感激，$n。', `FemaleText_loc7`='Agradezco tu entrega en este asunto, $n.' WHERE `ID`=15711;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 선조의 영혼에게 안식을 찾아주셨으니 이 은혜는 평생을 다해도 갚지 못할 것입니다.', `FemaleText_loc4`='是你让我们祖先的灵魂安息，我会永远感激你。', `FemaleText_loc5`='你讓我的祖先靈魂得到安息，我永遠都欠你一個人情。', `FemaleText_loc7`='Estaré siempre en deuda contigo por haber devuelto los espíritus de mis ancestros a su descanso.' WHERE `ID`=15712;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리티라, 사후 세계의 추출물을 하나 더 얻을 수 있습니까?', `MaleText_loc4`='学者，我还需要一份灵魂精萃。', `MaleText_loc5`='隱士，我需要另一個來世的提煉物。', `MaleText_loc7`='Anacoreta, necesito otro extracto del más allá.', `FemaleText_loc1`='리티라, 사후 세계의 추출물을 하나 더 얻을 수 있을까요?', `FemaleText_loc4`='学者，我还需要一份灵魂精萃。', `FemaleText_loc5`='隱士，我需要另一個來世的提煉物。', `FemaleText_loc7`='Anacoreta, necesito otro extracto del más allá.' WHERE `ID`=15713;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='환영회 같은 걸 기대한다면 실망할 것이오, $c|1이여;여;. 이곳에서는 전통에 얽매이지 않으며 중요한 것은 현재오이다.', `MaleText_loc4`='如果你在期盼正式的欢迎，那么你会失望的，$c。我们在这里并不拘泥于传统。怎么行就怎么做。', `MaleText_loc5`='如果你期待會有什麼正式歡迎款待之類的話，你恐怕要失望了，$c。在這裡我們傳統不算什麼，有什麼工作就好好做。', `MaleText_loc7`='Si esperas algo parecido a una bienvenida oficial, siento decepcionarte, $c; aquí no seguimos demasiado las tradiciones. No nos gustan los artificios.' WHERE `ID`=15714;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 현상 수배 전단에 붙은 다양한 양피지 중 하나가 특별히 눈에 띕니다. 해골 무덤에 있는 해골채찍 독수리를 처치하라는 내용입니다.', `MaleText_loc4`='钉满了羊皮纸的悬赏榜上有一张纸很显眼。上面写的是：希望有人能够去白骨荒野清理白骨秃鹫。', `MaleText_loc5`='懸賞告示上釘著幾張羊皮紙，一張新的告示引人注目的釘在這個告示牌上。宣布一則在白骨荒野殺死鞭骨者的消息。', `MaleText_loc7`='Una nota destaca de los demás pedazos de pergamino que están clavados en este cartel de "Se busca". Un llamamiento para matar a los Atizahuesos de El Vertedero de Huesos.' WHERE `ID`=15715;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 현상 수배지는 갖가지 위험 활동에 대한 보상과 공고로 가득 차 있습니다. 그러나 아직은 특별히 참여하고 싶다는 생각이 들지 않으니 아무래도 다음에 다시 확인해야 할 것 같습니다.', `MaleText_loc4`='这张悬赏单明细分得很清楚，各种冒险所能获得的奖励也列在了上面。然而，你还没找到适合你的悬赏内容。$B$B也许你应该稍后再来看看。', `MaleText_loc5`='這張懸賞告示掛在分類公告區，對各種危險的活動進行懸賞。不過，你好像還沒有看到有什麼特別之處吧。$B$B或許你應該晚點再去確認一次?', `MaleText_loc7`='En el cartel de Se busca hay muchas noticias y anuncios de recompensas, pero no ves ninguno que se ajuste a tu nivel y capacidades.$B$BSerá mejor que vuelvas más tarde.' WHERE `ID`=15716;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아니요, 괜찮습니다. 이런 경험이 많으니까요...$B$B<재미있어 하면서도 짜증나는 듯한 표정을 짓는 타엘라>$B$B저는 하이 엘프이지, 블러드 엘프가 아니랍니다. 그러니 당신 마법을 빨아들이진 않을 테니 걱정하지 마세요.', `FemaleText_loc4`='不，没关系。我经常遇到这种事情。$B$B<泰拉看上去有些高兴又有些恼火。>$B$B我是个**高等**精灵，不是个血精灵。所以不要担心，我不会把你的所有法力吸个精光的。', `FemaleText_loc5`='不，別生氣，我知道的。$B$B<泰蘭看起來又喜又怒>$B$B我是高等精靈，不是血精靈。別擔心，我不會把你的魔法吸光的。', `FemaleText_loc7`='No, que no te sepa mal. Me pasa mucho.$B$B<Taela parece entre divertida y molesta.>$B$BSoy una ALTA elfa, no una elfa de sangre. No te preocupes, no voy a chuparte toda la magia.' WHERE `ID`=15717;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 해골채찍 독수리를 증오하네!$B$B내가 한쪽 눈을 잃지 않았고 가끔 정신을 잃지만 않아도 매일 가서 놈들을 쏘아 죽였을 것이네!', `MaleText_loc4`='白骨秃鹫，我恨他们！$B$B要不是我失去了眼睛，要不是我那时灵时不灵的法术，我早就出去把他们全部轰成渣了！', `MaleText_loc5`='鞭骨者，我恨死他們了!$B$B要不是因為我沒看到，而且還中了暈眩法術，我會在同一時間把他們全都射下!', `MaleText_loc7`='Atizahuesos... ¡Los detesto a todos!$B$BSi no hubiera perdido mi ojo ni me salieran a veces esos hechizos tan débiles, estaría ahí fuera cargándomelos a todos.' WHERE `ID`=15718;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 기절합니다.', `MaleText_loc4`='%s晕倒了。', `MaleText_loc5`='%s 昏倒了。', `MaleText_loc7`='%s se desmaya.' WHERE `ID`=15719;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 성벽 위에서 일하는 알도르 사제회의 모습을 쭉 지켜봤어요. 그들은 도시 전체를 재건할 거예요.$B$B늙은 현장감독 오슬로가 호숫골에 있는 집을 재건했을 때보다 훨씬 더 빠른 속도로 작업하고 있어요. 그는 늘 연장을 호수에 빠뜨리거나 놀에게 보급품을 빼앗기곤 했죠.$B$B알도르 사제회에 그를 도와줄 일손을 좀 보내달라고 부탁해야겠어요. 알도르 사제회에서 그 다리를 수리했다면 순식간에 끝났을 거예요.', `MaleText_loc4`='我看到奥尔多正在修缮那些城墙。你知道，他们想要重建整座城市。$B$B他们比老工头奥斯洛在湖畔镇干得快多了，他不是把工具遗失在河里，就是被豺狼人拿走他的补给。$B$B我应该要求奥尔多去帮助他，这样他们就会很快修好那座断桥了。', `MaleText_loc5`='我看到奧多爾在城牆上工作，你知道?，他們要重建整個城市。$B$B他們工作的速度比老工頭奧斯洛回到湖畔鎮還快。他一直讓他的工具遺失在湖裡，要不然豺狼人會拿走他的補給品。$B$B我應該詢問奧多爾需不需要幫忙，因為他們還得盡速把橋修好。', `MaleText_loc7`='He estado observando cómo trabajan los Aldor en las murallas. Van a reconstruir toda la ciudad, ¿sabes?$B$BTrabajan mucho más de prisa que el viejo supervisor Olento en mi Villa del Lago natal. Constantemente perdía las herramientas en el lago, o los gnolls le robaban los suministros.$B$BDebería pedir a los Aldor que le envíen algo de ayuda. Ellos repararían el puente en menos que canta un gallo.' WHERE `ID`=15720;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$c|1이여;여;, 저 밖에는 광대한 숲이 있소. 주술사들은 영혼들과 놀고, 전사들은 칼이나 갖고 놀게 하시오. 난 테로카르 숲에서 한몫 단단히 잡을 거요.', `FemaleText_loc4`='那里有着大片的森林，$c。让萨满和灵魂们玩耍，让战士们耍他们的剑。泰罗卡森林是个要让我赚大钱的地方。', `FemaleText_loc5`='這裡有廣大的森林，$c。就讓薩滿和靈魂一起玩，也讓戰士把玩他們的劍吧。我將在泰洛卡這個地方創造我的命運財富。', `FemaleText_loc7`='Hay un gran bosque ahí fuera, $c. Deja que el chamán juegue con los espíritus y el guerrero con las espadas. En Terokkar haré fortuna.' WHERE `ID`=15721;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말루카즈는 이 숲의 역사적 중요성에 대해 끊임없이 떠들어 대더군. 하지만 난 당면한 문제가 해결될 때까지는 역사 따위를 생각할 정도로 사치를 부릴 여유가 없소.$B$B그가 이곳에서 하는 일이 중요하지 않다는 건 아니지만 누군가는 요새의 방어와 보급에 대해 걱정해야 한다는 거라오.', `MaleText_loc4`='玛鲁卡兹喋喋不休地讲述着这片森林的辉煌历史，但是在我们解决掉现在的问题前，我不会再奢靡无度了。$B$B我不是说他在这里的工作不重要，但是必须有人要去检查一下要塞的防御和后勤工作。', `MaleText_loc5`='瑪魯卡茲不斷喋喋不休地講著這個森林的歷史有多重要，但我現在沒有興趣聽這個歷史，除非我們當前的問題解決了。$B$B我不是說他在這裡的工作不重要，但要有個人去看管防禦工事並掌管後勤流程。', `MaleText_loc7`='Malukaz no para de hablar de la importancia histórica de este bosque, pero yo no puedo permitirme el lujo de preocuparme por la historia hasta que no se arregle el presente.$B$BNo digo que su trabajo aquí no sea importante, pero alguien tiene que preocuparse de que funcionen las defensas y la logística del fuerte.' WHERE `ID`=15722;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나그란드를 지나서 숲에 도착하기 전까지 우리의 전통문화가 많이 사라지지 않았을까 걱정했습니다. 제 걱정이 기우였다는 것을 알게 되어 얼마나 다행인지 모릅니다.$B$B숲은 아직 그대로네요!', `MaleText_loc4`='直到我游遍了纳格兰并进入这片森林之前，我都在担心我们失去了太多的文化传承。看来我多虑了。$B$B这里的风貌依然保持完好！', `MaleText_loc5`='從納葛蘭旅行直到來到這個森林，我很害怕我們的原始文化會消逝，但我很高興我錯了。$B$B這裡還是一如既往!', `MaleText_loc7`='Hasta que viajé por Nagrand y llegué al bosque, pensaba que una gran parte de nuestra cultura original se había perdido. Me alegra comprobar que estaba equivocado.$B$B¡Todavía queda mucho por hacer aquí!' WHERE `ID`=15723;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어둠의 문이 열리면서 우리 종족의 운명에 대한 소식을 들었어요. 어떤 면에서는 추방당한 덕분에 종족과 함께 몰락하는 것을 피한 셈이죠. 하지만, 원정순찰대가 캘타스와 한 패가 된 모습을 볼 때면...$B$B한때는 나의 형제였던 자들이 그런 일을 할 수 있으리라고는 정말이지 꿈에도 생각하지 못했어요.$B$B제가 꿈꾸던 귀향은 결코 없을 거예요. 이 숲이 저의 마지막 안식처입니다.', `FemaleText_loc4`='我的同胞的命运随着黑暗之门的打开进入了新的篇章。在某种程度上来说，我的流放使我免于堕落。但是看到远行者把他们的命运都交给了凯尔萨斯……$B$B我不敢相信我以前的朋友可以做出这样的事情。$B$B我那回家的梦看来永远都不可能实现了，这片森林是我唯一的家。', `FemaleText_loc5`='開啟黑暗之門為我的人民的命運帶來了新的消息，我的流亡保護了我沒有和他們一同毀滅，但是看見那些遠行者卻把他們丟給凱爾薩斯...$b$b我從未想像過我從前的兄弟們會碰到這種事。$B$B我夢想中的歸國永遠不再能實現，這個森林是我唯一的家鄉，我卻得離開。', `FemaleText_loc7`='La apertura del Portal Oscuro, trajo noticias de la suerte que corrió mi pueblo. En cierto modo, mi exilio evitó que compartiese su caída, pero ver a los Errantes darlo todo por Kael''thas...$B$BNunca imaginé que los que fueron mis hermanos podrían hacer algo así.$B$BLa vuelta a casa con la que tanto soñé nunca tendrá lugar. Este bosque es el único hogar que me queda.' WHERE `ID`=15724;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이곳에 처음 도착했을 때 마을의 이름을 딴 자를 만날 수 있으리라 기대했었죠.$B$B<주위를 흘끗 둘러보는 로스엘레스>$B$B대부분의 젊은 하이 엘프들은 첫 번째 수습생이 될 나이가 될 무렵이면 원정순찰자가 되고 싶다는 생각은 하지 않게 된답니다. 그런 다음에는 마법학자가 되고 싶어하는 단계에 올라가게 되지요.$B$B그런데 솔직히 말해서 저는 원정순찰자가 되고 싶은 단계를 아직 넘어서지 못한 것 같아요. 재봉사가 꿈인 하이 엘프는 없지만 어머니가 종종 말씀하셨듯이 원정순찰자가 벌거벗고 돌아다니도록 할 수는 없잖아요?', `FemaleText_loc4`='当我最初来到这里时，我曾希望能和这个小镇所用名字的主人会面。$B$B<洛瑟蕾丝扫视着周围。>$B$B当年幼的高等精灵成长到学徒的年龄时，他们的脑袋里想的便不再是“我要成为一名远行者”，而是“我要当一名魔导师”。$B$B没有人会梦想成为一个女裁缝，但就像我母亲常常说的那样，我们不能让远行者就这么不穿衣服走来走去。', `FemaleText_loc5`='當我第一次來到這裡，我希望能遇見和城同名的人。$B$B<羅斯勒斯環視一周>$B$B大部分年輕高等的精靈屬於「我想要成為遠行者」的階段，這時候的他們是符合他們的年紀的見習期。接下來，會變成「我想要成為博學者」的階段。$B$B老實說，我不認為我不再適合遠行者的階段。沒有人夢想長大之後，要成為一個女裁縫師，但就像我媽曾說過的話，我不能像遠行者一樣光溜溜的到處跑。', `FemaleText_loc7`='Cuado llegué aquí, esperaba estar a la altura de la reputación de la ciudad.$B$B<Ros''eleth mira a su alrededor.>$B$BLa mayoría de los jóvenes superan la fase de "quiero ser un Errante" en cuanto cumplen la edad para empezar a aprender. Entonces pasan a la fase "yo quiero ser magister".$B$BNadie quiere ser costurera, pero los Errantes no pueden pasearse por ahí desnudos; ya lo decía mi madre.' WHERE `ID`=15725;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이곳에 처음 도착했을 때 마을의 이름을 딴 자를 만날 수 있으리라 기대했었죠.$B$B<주위를 흘끗 둘러보는 로스엘레스>$B$B대부분의 젊은 하이 엘프들은 첫 번째 수습생이 될 나이가 될 무렵이면 "원정순찰자가 되고 싶어요."라는 생각은 하지 않게 된답니다. 그런 다음에는 "마법학자가 되고 싶어요."라는 단계에 올라가게 되지요.$B$B그런데 솔직히 말해서 저는 원정순찰자가 되고 싶은 단계를 아직 넘어서지 못한 것 같아요. 재봉사가 꿈인 하이 엘프는 없지만 어머니가 종종 말씀하셨듯이 원정순찰자가 벌거벗고 돌아다니도록 할 수는 없잖아요?', `FemaleText_loc4`='当我最初来到这里时，我曾希望能和这个小镇所用名字的主人会面。$B$B<洛瑟蕾丝扫视着周围。>$B$B当年幼的高等精灵成长到学徒的年龄时，他们的脑袋里想的便不再是“我要成为一名远行者”，而是“我要当一名魔导师”。$B$B说实话，我不觉得我曾经幻想过成为远行者。没有人会梦想成为一名女裁缝，但就像我母亲常常说的那样，我们不能让远行者就这么不穿衣服走来走去。', `FemaleText_loc5`='當我第一次來到這裡，我希望能遇見和城同名的人。$B$B<羅斯勒斯環視一周>$B$B大部分年輕高等的精靈屬於「我想要成為遠行者」的階段，這時候的他們會被當作新手。接下來，會變成「我想要成為博學者」的階段。$B$B老實說，我不認為我不再適合遠行者的階段。沒有人夢想長大之後，要成為一個女裁縫師，但就像我媽曾說過的話，我不能像遠行者一樣光溜溜的到處跑。', `FemaleText_loc7`='Cuado llegué aquí, esperaba estar a la altura de la reputación de la ciudad.$B$B<Ros''eleth mira a su alrededor.>$B$BLa mayoría de los jóvenes superan la fase de "quiero ser un Errante" en cuanto alguien los acepta como aprendices. Entonces pasan a la fase "yo quiero ser magister".$B$BPara serte sincera, yo todavía estoy superando lo de "quiero ser Errante". Nadie quiere ser costurera de mayor, pero alguien tiene que hacer lo que se ponen los Errantes para no andar desnudos. Eso es lo que solía decirme mi madre.' WHERE `ID`=15726;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로스엘레스는 정말 멋진 여자랍니다. 제가 의복이나 모자를 찾으러 갈 때마다 로스엘레스가 윙크하는 걸 봤지요? 주변 상황이 좀 정리되면 그녀와 함께 숲 속을 산책하며 데이트를 할 생각입니다.$B$B이럴 때는 정말이지 스톰윈드의 멋진 선술집들이 그립답니다.', `MaleText_loc4`='你有没有看到每当我拿起一件衣服或者帽子的时候，洛瑟蕾丝总是对我眨眼睛？当这附近的事情安定下来后，我一定会带她去森林里散散步。$B$B有时候，我还是挺想念暴风城的那些豪华旅店的。', `MaleText_loc5`='每當我穿了件衣服或帽子，你曾看過羅斯勒斯裝做沒看見我嗎?這裏所有的事情都安頓下來，我要帶她去森林散步。$B$B就這麼一次，我錯過暴風城所有精緻的小酒館。', `MaleText_loc7`='¿Has visto cómo me guiña el ojo Ros''eleth cada vez que voy a recoger ropa o algún sombrero? Cuando las cosas se calmen por aquí, me la voy a llevar de paseo al bosque.$B$BAhora sí que echo de menos todas esas tabernas de Ventormenta.' WHERE `ID`=15727;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<쉿 소리를 내며 저지하는 카이드>$B$B조용! 오크와 얼라이언스를 끌어들이고 싶은 거야, 이 둔하고 한심한 녀석 같으니!$B$B그래, 그렇게 고개만 끄덕이라고. 얘기가 끝나면 자네는 곧장 여길 뜨고 여기서 나를 본 사실은 잊어버려.', `MaleText_loc4`='<凯德对你发出嘘声。>$B$B你这个蠢货！小声点，否则你会把那些兽人和联盟全引到我们这里来！$B$B对，就那样，点点头就行了，在我们完成谈话后，走远点，把我们的见面忘了吧。', `MaleText_loc5`='<凱德對你發出噓聲>$B$B安靜點，要不然你能擊敗獸人和聯盟嗎，你這個笨手笨腳的蠢蛋!$B$B這就對了，點頭就好了，當我們談話結束，你就離開這裡然後忘記你在這裡找到了我。', `MaleText_loc7`='<Kaide te hace callar.>$B$B¡Silencio, o atraerás a los orcos y a la Alianza hacia nosotros, torpe patán!$B$BExacto, asiente con la cabeza, y cuando acabemos de hablar te irás y olvidarás que me viste aquí.' WHERE `ID`=15728;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 함께 일할 수도 있겠지만, 더욱 신중해져야 할 것이네. 다시 한번 강조하지만 말과 행동을 주의하도록 하게.$B$B장담하건대, 이곳에는 우리만 있는 게 아니니 말이야.', `MaleText_loc4`='我们也许可以一起工作，但那只是为了增加判断力。再说一次，注意你的言行。$B$B我敢保证，周围还有别的人。', `MaleText_loc5`='我們可能會在一起工作，但是要小心謹慎，我再一次提醒你要注意你的言行舉止。$B$B我可以保證在這裡我們是最不親近的。', `MaleText_loc7`='Puede que estemos juntos en esto, pero eso solo hace que sea más necesaria la discreción. Te lo repito: ten cuidado con lo que dices y con lo que haces.$B$BTe garantizo que no somos los únicos aquí fuera.' WHERE `ID`=15729;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 다소 불안한 듯 주위를 둘러봅니다.', `MaleText_loc4`='%s扫视了一下周围，稍微有些紧张。', `MaleText_loc5`='%s有點緊張的向四處看了一下。', `MaleText_loc7`='%s mira a su alrededor con nerviosismo.' WHERE `ID`=15730;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요, 로스엘레스. 내, 으음, 내, 내... ''모자''는 다 완성되었나요?', `MaleText_loc4`='你好啊，洛瑟蕾丝。我的那个，那个……我的“头盔”完成了吗？', `MaleText_loc5`='你好啊，羅斯勒斯。我的...嗯...嗚...唔...我的頭盔完成了嗎?', `MaleText_loc7`='Hola, Ros''eleth. ¿Está mi..., eh..., mis artículos para la cabeza preparados?' WHERE `ID`=15731;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어머, 그럼요, 베르텔름, 모자는 다 만들었어요. 특별히 최고로 크고, 풍성하고, 근사한 깃털을 사용했답니다. 새로 만들 바지 치수를 재는 동안에 당신은...', `FemaleText_loc4`='什么？啊，当然，波尔泰姆，你的帽子做好了。我用了大量蓬松的、我所能找到的最华丽的羽毛制成了它。如果你愿意的话，我还可以为你量一量尺寸，做一双新的长筒袜——', `FemaleText_loc5`='為什麼，是的，伯特泰歐，我完成你的帽子了。我用了大量且又軟又好的羽毛。或許你想要我幫你做一雙新襪子，當你—', `FemaleText_loc7`='Pues sí, Bertelm, he acabado tu sombrero. He usado la pluma más grande, airosa y magnífica que encontré. Tal vez quieras que te tome medidas para confeccionarte unos pantalones nuevos mientras estés...' WHERE `ID`=15732;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s의 얼굴이 붉어집니다.', `MaleText_loc4`='%s的脸开始变红了。', `MaleText_loc5`='%s開始變紅。', `MaleText_loc7`='%s comienza a ponerse rojo.' WHERE `ID`=15733;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어, 아뇨... 아닙니다. 그럴 필요 없습니다. 나, 나중에 병사를 보내서, 투, 아니 모자를 가지고 오라고 하겠습니다. 정말 어서 가봐야 해서요...', `MaleText_loc4`='哦，不……不，不必了。我会，嗯，派一个士兵来拿，呃，头盔。我现在必须走了……', `MaleText_loc5`='喔，不...不，不需要了。我待會兒...嗚...派士兵去收集...嗚...頭盔。我現在一定得過去...', `MaleText_loc7`='Eh, no... No, no hace falta. Mandaré a un, eh..., a un soldado a recoger las..., eh..., los artículos para la cabeza más tarde. Ahora me tengo que ir...' WHERE `ID`=15734;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가엾은 베르텔름...', `FemaleText_loc4`='可怜的波尔泰姆……', `FemaleText_loc5`='可憐的伯特泰歐...', `FemaleText_loc7`='Pobre Bertelm...' WHERE `ID`=15735;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오, 저 가엾은 베르텔름...', `FemaleText_loc4`='可怜的波尔泰姆……', `FemaleText_loc5`='可憐的伯特泰歐...', `FemaleText_loc7`='Pobre Bertelm...' WHERE `ID`=15736;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐야! 이봐, 어서 물을 가져와라! 요새 전체로 번지기 전에 불을 꺼야 한다! 빨리, 젠장!', `MaleText_loc4`='你们！赶快去打水！在火势蔓延起来之前扑灭它！快一点，你们这些该死的东西！', `MaleText_loc5`='你!快去拿水來!在火勢擴大之前快撲滅它!快呀，該死的!', `MaleText_loc7`='Ustedes, ¡Busquen agua, rápido! ¡Apaguen las llamas antes de que se extiendan al resto del castillo! ¡Rápido, maldición!' WHERE `ID`=15737;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진실한 믿음은 곧 피에 있습니다. 우리 종족 외에는 누구도 믿을 수 없어요!', `MaleText_loc4`='流血是真实的。我们只能相信自己！', `MaleText_loc5`='血統才是真理，我們只能相信自己人!', `MaleText_loc7`='La sangre es fuerte. ¡No podemos confiar en nadie excepto en los nuestros!' WHERE `ID`=15738;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='투기장 전투 시작 15초 전입니다!', `MaleText_loc4`='竞技场战斗将在十五秒后开始！', `MaleText_loc5`='15秒後競技場戰鬥開始!', `MaleText_loc7`='¡Quince segundos para que comience la batalla de arena!' WHERE `ID`=15739;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='투기장 전투 시작 1분 전입니다!', `MaleText_loc4`='竞技场战斗将在一分钟后开始！', `MaleText_loc5`='1分鐘後競技場戰鬥開始!', `MaleText_loc7`='¡Un minuto hasta que dé comienzo la batalla en arena!' WHERE `ID`=15740;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='투기장 전투 시작 30초 전입니다!', `MaleText_loc4`='竞技场战斗将在三十秒后开始！', `MaleText_loc5`='30秒後競技場戰鬥開始!', `MaleText_loc7`='¡Treinta segundos hasta que comience la batalla de arena!' WHERE `ID`=15741;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='투기장 전투가 시작되었습니다!', `MaleText_loc4`='竞技场战斗开始了！', `MaleText_loc5`='競技場戰鬥開始了!', `MaleText_loc7`='¡La batalla de arena ha comenzado!' WHERE `ID`=15742;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='방금 피라고 하셨소? 과연 자기 좋을 때만 친구인 척하는 오크들이 우리를 도와줄까?', `FemaleText_loc4`='血？还有这些兽人，这些见风使舵的家伙？他们会帮我们吗？', `FemaleText_loc5`='血統?他們是獸人，這些獸人是我們最好的朋友?他們會協助我們?', `FemaleText_loc7`='¿Sangre? ¿Y esos orcos, esos que solo son amigos en los buenos tiempos? ¿Nos ayudarán?' WHERE `ID`=15743;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 우리의 땅에 지독한 병이 돌고 있소. 날로 심각해지고 있지! 마력에 대한 욕구가 클수록 우리는 약해질 테고 결국 몰락하고 말 거요. 과거에 그랬던 것처럼!', `MaleText_loc4`='死亡之痕横穿过我们的土地！它每天都在生长。就像以前那样，我们对魔法的需要使得我们脆弱，同样也把我们带向毁灭。', `MaleText_loc5`='我們的土地遭受荒疫肆虐，而且日趨惡劣!我們越需要魔法就越使得我們衰弱，並為我們帶來毀滅，就像之前所發生的一樣!', `MaleText_loc7`='¡El añublo recorre nuestra tierra! Crece día a día. Nuestra sed de magia nos debilita y nos llevará a la destrucción, tal y como ha ocurrido antes.' WHERE `ID`=15744;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만, 우리가 마력 없이 어떻게 살아갑니까?', `MaleText_loc4`='没有魔法，我们要怎么生存？', `MaleText_loc5`='沒有了魔法我們要如何過活?', `MaleText_loc7`='¿Cómo vamos a vivir sin magia?' WHERE `ID`=15745;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='경이로운 이 도시를 한번 보십시오! 이것이 바로 마법의 힘입니다.', `FemaleText_loc4`='看看这座神奇的城市！这就是魔法本身。', `FemaleText_loc5`='看看這奇幻的城市!這是魔法!', `FemaleText_loc7`='¡Admira qué maravillas! Esto es magia.' WHERE `ID`=15747;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만, 대가를 치르지 않았소?! 우리는 모두 장님이 되었소. 모두 눈이 멀어 버렸단 말이오!', `MaleText_loc4`='但是那代价呢？你完全被蒙蔽了。我们都完全被蒙蔽了。', `MaleText_loc5`='但是代價是什麼?你們全都瞎了!我們全都瞎了!', `MaleText_loc7`='¿Pero a qué precio? Están ciegos. Los han cegado. Nos han cegado a todos.' WHERE `ID`=15748;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 배신자라는 말입니까?', `MaleText_loc4`='你称我们是叛徒吗？', `MaleText_loc5`='你叫我們叛國賊?', `MaleText_loc7`='¿Nos estás llamando traidores?' WHERE `ID`=15749;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마법학자들이야말로 배신자들이오! 우리가 이렇게 된 것도 다 그들 때문이지.', `FemaleText_loc4`='魔导师们是叛徒！他们已经注定了我们的毁灭。', `FemaleText_loc5`='博學者都是叛國賊!他們批准了我們的判決。', `FemaleText_loc7`='¡Los magistri son los traidores! Han sellado nuestro destino.' WHERE `ID`=15750;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런 허튼소리 그만 늘어놓고 숲으로 돌아가시오!', `MaleText_loc4`='一派胡言。回到你的森林里去！', `MaleText_loc5`='空談的廢話，回你的森林去吧!', `MaleText_loc7`='Charla idealista sin sentido. ¡Vuelve a tu bosque!' WHERE `ID`=15751;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신 같은 자들 때문에 우리는 미개한 종족처럼 살아야 하잖아!', `FemaleText_loc4`='你会让我们像野蛮人那样生活的！', `FemaleText_loc5`='你就像個野蠻人一樣擁有我們的生命!', `FemaleText_loc7`='¡Quieres que vivamos como salvajes!' WHERE `ID`=15752;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절대 그런 것은 아니오! 내 양심을 걸고 말하겠소. 우리 일족의 무절제는 우리 자신과, 그동안 힘들게 쌓아올린 모든 것을 파괴할 거요.', `MaleText_loc4`='不，不是野蛮人！这是道德。我们毫无节制的行为会最终摧毁我们，进而摧毁我们所努力构建的一切。', `MaleText_loc5`='不，不是野蠻!而是良心!我們子民的暴行會摧毀我們，並破壞我們努力所建造的東西。', `MaleText_loc7`='No, salvajes no. ¡Seres conscientes! Los excesos de nuestro pueblo nos destruirán a nosotros y lo que tanto nos costó construir.' WHERE `ID`=15753;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리는 살아남고자 투쟁하지 않았소. 그것이 결국 철저한 파괴를 불러오고 만 것이지.', `FemaleText_loc4`='我们竭尽全力挣扎奋斗，为的是求得生存的机会，而不是给自己带来真正的毁灭。', `FemaleText_loc5`='我們不用為了生存而努力掙扎，這只會引起真正的毀滅。', `FemaleText_loc7`='No hemos luchado tanto por sobrevivir solo para traer la destrucción verdadera.' WHERE `ID`=15754;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일입니까? 바쁜 게 안 보입니까? 어둠의 의회에서는 시간당 수당이나 주면서 저를 고용한 것이 아닙니다!', `MaleText_loc4`='嗯，你想要什么？你没看到我正忙着吗？暗影议会可不会按小时给我付工钱。', `MaleText_loc5`='是啊，你想要什麼?你看不出來我正在忙嗎?暗影議會讓我一刻不得閒!', `MaleText_loc7`='Sí, ¿qué quieres? ¿No ves que estoy ocupado? ¡El Consejo de la Sombra no me paga por hora de trabajo!', `FemaleText_loc1`='무슨 일입니까? 바쁜 게 안 보입니까? 어둠의 의회에서는 시간당 수당이나 주면서 저를 고용한 것이 아닙니다!', `FemaleText_loc4`='嗯，你想要什么？你没看到我正忙着吗？暗影议会可不会按小时给我付工钱。', `FemaleText_loc5`='是啊，你想要什麼?你看不出來我正在忙嗎?暗影議會讓我一刻不得閒!', `FemaleText_loc7`='Sí, ¿qué quieres? ¿No ves que estoy ocupada? ¡El Consejo de la Sombra no me paga por hora de trabajo!' WHERE `ID`=15755;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 파멸의 갈림길에 서 있소. 이 성급한 행동에 대해 다시 생각해 봐야 하오.', `MaleText_loc4`='我们站在毁灭的边缘。我们必须重新考虑这轻率的行动计划。', `MaleText_loc5`='我們站在毀滅的邊緣，我們必須要重新考慮這個草率行動所帶來的影響。', `MaleText_loc7`='Estamos al borde de la destrucción. Debemos meditar bien sobre la dirección que hemos tomado.' WHERE `ID`=15756;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 이곳을 다 수리하고 있습니까?', `MaleText_loc4`='为什么你要把这些全都修理了？', `MaleText_loc5`='為什麼你要修理這個地方?', `MaleText_loc7`='¿Por qué estás arreglando todo esto?', `FemaleText_loc1`='왜 이곳을 다 수리하고 있나요?', `FemaleText_loc4`='为什么你要把这些全都修理了？', `FemaleText_loc5`='為什麼你要修理這個地方?', `FemaleText_loc7`='¿Por qué estás arreglando todo esto?' WHERE `ID`=15757;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 하는 것처럼 보입니까? 우리가 이주할 땅을 손보는 중입니다. 전부 다 제 손으로 직접 말이죠!$B$B이 숲 속에 작전 기지를 만들어 놓으면 샤트라스, 알레리아, 돌망치, 세나리온의 드루이드들이 무슨 계획을 꾸미고 있는지 한결 쉽게 알아낼 수 있겠죠. 아킨둔의 기지에서는 몹시 불편할 거예요.$B$B그런데 우리가 아는 사이였나요?', `MaleText_loc4`='我看上去像在干什么？我正在尽我的全力修理这个地方，这样我们就可以搬进来常驻了！$B$B随着基地在森林中运作起来，我们就更容易监视沙塔斯城、奥蕾莉亚岗哨、裂石堡，以及塞纳里奥的德鲁伊们。我们在奥金顿的基地中可不方便做这个。$B$B等一下，我认识你吗？', `MaleText_loc5`='我看起來像是在做什麼?我在整修這個地方 - 而且還全靠我自己一個人 - 這樣我們才能搬進來!$B$B有了運作基地在這裡的森林，要知道撒塔斯、艾蘭里、碎石和塞納里奧的德魯伊在幹嘛就容易的多了。我們在奧齊頓的基地就很不方便。$B$B等一下，我認識你嗎?', `MaleText_loc7`='¿Qué parece que estoy haciendo? Estoy arreglando las cosas para que podamos instalarnos. Y yo solo, además.$B$BCon una base de operaciones en el bosque será más fácil seguir la pista a lo que traman los druidas de Shattrath, Allerian, Rompepedras y Cenarion. Nuestra base en Auchindoun es demasiado poco práctica para eso.$B$BEspera un momento, ¿te conozco?', `FemaleText_loc1`='뭘 하는 것처럼 보입니까? 우리가 이주할 땅을 손보는 중입니다. 전부 다 제 손으로 직접 말이죠!$B$B이 숲 속에 작전 기지를 만들어 놓으면 샤트라스, 알레리아, 돌망치, 세나리온의 드루이드들이 무슨 계획을 꾸미고 있는지 한결 쉽게 알아낼 수 있겠죠. 아킨둔의 기지에서는 몹시 불편할 거예요.$B$B그런데 우리가 아는 사이였나요?', `FemaleText_loc4`='我看上去像在干什么？我正在尽我的全力修理这个地方，这样我们就可以搬进来常驻了！$B$B随着基地在森林中运作起来，我们就更容易监视沙塔斯城、奥蕾莉亚岗哨、裂石堡，以及塞纳里奥的德鲁伊们。我们在奥金顿的基地中可不方便做这个。$B$B等一下，我认识你吗？', `FemaleText_loc5`='我看起來像是在做什麼?我在整修這個地方 - 而且還全靠我自己一個人 - 這樣我們才能搬進來!$B$B有了運作基地在這裡的森林，要知道撒塔斯、艾蘭里、碎石和塞納里奧的德魯伊在幹嘛就容易的多了。我們在奧齊頓的基地就很不方便。$B$B等一下，我認識你嗎?', `FemaleText_loc7`='¿Qué parece que estoy haciendo? Estoy arreglando las cosas para que podamos instalarnos. Y yo sola, además.$B$BCon una base de operaciones en el bosque será más fácil seguir la pista a lo que traman los druidas de Shattrath, Allerian, Rompepedras y Cenarion. Nuestra base en Auchindoun es demasiado poco práctica para eso.$B$BEspera un momento, ¿te conozco?' WHERE `ID`=15758;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 하고 있는 일이 뭐라고 생각하세요? 저는 우리가 이주할 수 있도록 이곳을 수리하고 있어요. 오로지 혼자 힘으로 말입니다!$B$B그런데 우리가 아는 사이였나요?', `MaleText_loc4`='我看上去像在干什么？我正在尽我的全力修理这个地方，这样我们就可以搬进来常驻了！$B$B等一下，我认识你吗？', `MaleText_loc5`='我看起來像是在做什麼?我只是在整修這個我要住的地方，這樣我們才能搬到這裡!$B$B我認識你嗎?', `MaleText_loc7`='¿Qué crees que estoy haciendo? ¡Estoy arreglándolo –yo solo, por cierto– para poder mudarnos!$B$B¿Te conozco de algo?', `FemaleText_loc1`='제가 하고 있는 일이 뭐라고 생각하세요? 저는 우리가 이주할 수 있도록 이곳을 수리하고 있어요. 오로지 혼자 힘으로 말입니다!$B$B그런데 우리가 아는 사이였나요?', `FemaleText_loc4`='我看上去像在干什么？我正在尽我的全力修理这个地方，这样我们就可以搬进来常驻了！$B$B等一下，我认识你吗？', `FemaleText_loc5`='我看起來像是在做什麼?我只是在整修這個我要住的地方，這樣我們才能搬到這裡!$B$B我認識你嗎?', `FemaleText_loc7`='¿Qué crees que estoy haciendo? ¡Estoy arreglándolo –yo sola, por cierto– para poder mudarnos!$B$B¿Te conozco de algo?' WHERE `ID`=15759;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 아는 사이던가요? 이봐요, 난 휘말리고 싶은 생각 없습니다. 그저 이곳을 좀 수리하고 있을 뿐이니까요.', `MaleText_loc4`='我认识你吗？听着，我不想找麻烦。我只是在修理东西。', `MaleText_loc5`='我認識你嗎?聽著，我不想惹任何麻煩，我只是在這裡修東西而已。', `MaleText_loc7`='¿Te conozco? Mira, no quiero problemas. Yo solo arreglo cosas por aquí.', `FemaleText_loc1`='우리가 아는 사이던가요? 이봐요, 난 휘말리고 싶은 생각 없습니다. 그저 이곳을 좀 수리하고 있을 뿐이니까요.', `FemaleText_loc4`='我认识你吗？听着，我不想找麻烦。我只是在修理东西。', `FemaleText_loc5`='我認識你嗎?聽著，我不想惹任何麻煩，我只是在這裡修東西而已。', `FemaleText_loc7`='¿Te conozco? Mira, no quiero problemas. Yo solo arreglo cosas por aquí.' WHERE `ID`=15760;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐라고요? 당신은 누굽니까?$B$B<손을 들어 막는 수습생>$B$B저기, 다시 수련을 계속할 테니까 못 본 걸로 해 주시겠습니까?', `MaleText_loc4`='什么？你是谁？$B$B<新兵举起了双手。>$B$B看，不如这样，我继续回去练习，而你就当没看到过我？', `MaleText_loc5`='什麼?你是誰?$B$B<新加入的人拉起他的手。>$B$B聽著，要不我回去繼續我的訓練然後你當作沒看見我?', `MaleText_loc7`='¿Qué? ¿Quién eres?$B$B<La iniciada levanta las manos.>$B$BMira, ¿qué te parece si yo vuelvo con mi instrucción y tú haces como si no me hubieras visto?', `FemaleText_loc1`='뭐라고요? 당신은 누구죠?$B$B<손을 들어 막는 수습생>$B$B저기, 다시 수련을 계속할 테니까 못 본 걸로 해 주시겠어요?', `FemaleText_loc4`='什么？你是谁？$B$B<新兵举起了双手。>$B$B看，不如这样，我继续回去练习，而你就当没看到过我？', `FemaleText_loc5`='什麼?你是誰?$B$B<新加入的人拉起他的手。>$B$B聽著，要不我回去繼續我的訓練然後你當作沒看見我?', `FemaleText_loc7`='¿Qué? ¿Quién eres?$B$B<La iniciada levanta las manos.>$B$BMira, ¿qué te parece si yo vuelvo con mi instrucción y tú haces como si no me hubieras visto?' WHERE `ID`=15761;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐라고요? 빌어먹을, 처음부터 전부 다시 시작해야 하잖아!', `MaleText_loc4`='嗯？该死的，现在我不得不重新开始了！', `MaleText_loc5`='嗯?去你的，現在我得從頭來過!', `MaleText_loc7`='¿Sí? Rayos. Ahora voy a tener que empezar desde el principio.', `FemaleText_loc1`='뭐라고요? 빌어먹을, 처음부터 전부 다시 시작해야 하잖아!', `FemaleText_loc4`='嗯？该死的，现在我不得不重新开始了！', `FemaleText_loc5`='嗯?去你的，現在我得從頭來過!', `FemaleText_loc7`='¿Sí? Rayos. Ahora voy a tener que empezar desde el principio.' WHERE `ID`=15762;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 뭘 하고 있습니까?', `MaleText_loc4`='你在干什么？', `MaleText_loc5`='你在這裡幹做什麼?', `MaleText_loc7`='¿Qué estás haciendo aquí?', `FemaleText_loc1`='여기서 뭘 하고 있나요?', `FemaleText_loc4`='你在干什么？', `FemaleText_loc5`='你在這裡幹做什麼?', `FemaleText_loc7`='¿Qué estás haciendo aquí?' WHERE `ID`=15763;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수련 중이지요! 곧 다른 소환사들과 합류하여 아킨둔의 어둠의 미궁에서 명성을 날릴 만큼 실력이 향상될 것입니다.$B$B정말 큰 놈을 소환할 기회가 생기면 좋겠어요! 울림만큼 큰 녀석이든가 그렇지 않으면 전 녀석의 통제권을 잃게 될 거예요!', `MaleText_loc4`='加紧练习！很快我就会有足够的能力跟其他召唤者一起进入奥金顿的暗影迷宫了。$b$b我希望能得到召唤一些大东西的机会！也许是和摩摩尔一样大的家伙，但是我不会失去对他的控制！', `MaleText_loc5`='練習!不用多久我就可以加入其他召喚師並且輪到我去奧齊頓的暗影迷宮。$B$B我希望我有機會可以召喚更大的東西!或許像莫爾墨那麼大，雖然我不會對他失去掌控!', `MaleText_loc7`='¡Entrenando! Pronto seré lo suficientemente bueno como para unirme a los otros invocadores y entrar en el Laberinto de las Sombras de Auchindoun.$B$B¡Espero poder invocar algo grande! ¡Quizás algo tan grande como Murmur, aunque no perdería el control sobre él!', `FemaleText_loc1`='수련 중이지요! 곧 다른 소환사들과 합류하여 아킨둔의 어둠의 미궁에서 명성을 날릴 만큼 실력이 향상될 것입니다.$B$B정말 큰 놈을 소환할 기회가 생기면 좋겠어요! 울림만큼 큰 녀석이든가 그렇지 않으면 전 녀석의 통제권을 잃게 될 거예요!', `FemaleText_loc4`='加紧练习！很快我就会有足够的能力跟其他召唤者一起进入奥金顿的暗影迷宫了。$b$b我希望能得到召唤一些大东西的机会！也许是和摩摩尔一样大的家伙，但是我不会失去对他的控制！', `FemaleText_loc5`='練習!不用多久我就可以加入其他召喚師並且輪到我去奧齊頓的暗影迷宮。$B$B我希望我有機會可以召喚更大的東西!或許像莫爾墨那麼大，雖然我不會對他失去掌控!', `FemaleText_loc7`='¡Entrenando! Pronto seré lo suficientemente buena como para unirme a los otros invocadores y entrar en el Laberinto de las Sombras de Auchindoun.$B$B¡Espero poder invocar algo grande! ¡Quizás algo tan grande como Murmur, aunque no perdería el control sobre él!' WHERE `ID`=15764;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 우리 편이 아니로군! 경비병!$B$B오, 제발 해치지 마세요! 얼굴만은 제발!!! 얼굴은 안된다고요!!!', `MaleText_loc4`='你不是我们的同伴！卫兵！$B$B哦，请别伤害我！别打脸！别打脸！', `MaleText_loc5`='你不是我們的人!守衛快來啊!$B$B喔!拜託!別傷害我!別打我的臉!別打我的臉!', `MaleText_loc7`='¡No eres uno de los nuestros! ¡Guardias!$B$B¡No me hagas daño, por favor! ¡En la cara no! ¡En la cara no!', `FemaleText_loc1`='당신은 우리 편이 아니로군! 경비병!$B$B오, 제발 해치지 마세요! 얼굴만은 제발!!! 얼굴은 안돼요!!!', `FemaleText_loc4`='你不是我们的同伴！卫兵！$B$B哦，请别伤害我！别打脸！别打脸！', `FemaleText_loc5`='你不是我們的人!守衛快來啊!$B$B喔!拜託!別傷害我!別打我的臉!別打我的臉!', `FemaleText_loc7`='¡No eres uno de los nuestros! ¡Guardias!$B$B¡No me hagas daño, por favor! ¡En la cara no! ¡En la cara no!' WHERE `ID`=15765;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도대체 원하는 게 뭐요? 우리 훌륭한 지도자와 중요한 문제를 의논하느라 바쁜 것이 보이지 않소?$B$B썩 물러가지 않으면 흠씬 두들겨 맞을 줄 아시오!', `MaleText_loc4`='你觉得我能为你做些什么吗？没看到我正在讨论关于我们杰出领袖的重要事情吗？$B$B有话快说！', `MaleText_loc5`='你覺得我到底能為你做什麼?你難道不能看出我正忙著和我們偉大的領袖談論重大的議題嗎?$B$B兔崽仔，快說你有什麼事，要不我就扁你一頓!', `MaleText_loc7`='¿Y qué es exactamente lo que puedo hacer por ti? ¿No te das cuenta de que estoy muy ocupado discutiendo cuestiones importantes con nuestro ilustre líder?$B$BDate prisa en hablar o haré que te den una paliza, gusano.', `FemaleText_loc1`='도대체 원하는 게 뭐요? 우리 훌륭한 지도자와 중요한 문제를 의논하느라 바쁜 것이 보이지 않소?$B$B썩 물러가지 않으면 흠씬 두들겨 맞을 줄 아시오!', `FemaleText_loc4`='你觉得我能为你做些什么吗？没看到我正在讨论关于我们杰出领袖的重要事情吗？$B$B有话快说！', `FemaleText_loc5`='你覺得我到底能為你做什麼?你難道不能看出我正忙著和我們偉大的領袖談論重大的議題嗎?$B$B兔崽仔，快說你有什麼事，要不我就扁你一頓!', `FemaleText_loc7`='¿Y qué es exactamente lo que puedo hacer por ti? ¿No te das cuenta de que estoy muy ocupada discutiendo cuestiones importantes con nuestro ilustre líder?$B$BDate prisa en hablar o haré que te den una paliza, gusano.' WHERE `ID`=15766;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조언자여, 새로운 소식이 있습니까?', `MaleText_loc4`='顾问，有什么新消息吗？', `MaleText_loc5`='顧問，有沒有最新的消息?', `MaleText_loc7`='Consejero, ¿qué noticias tienes?', `FemaleText_loc1`='조언자여, 새로운 소식이 있나요?', `FemaleText_loc4`='顾问，有什么新消息吗？', `FemaleText_loc5`='顧問，有沒有最新的消息?', `FemaleText_loc7`='Consejero, ¿qué noticias tienes?' WHERE `ID`=15767;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 우리 지도자께 계획이 어떻게 진행되고 있는지 보고하던 참이었소. 몇 주만 더 있으면 이 장소가 제 모습을 되찾게 될 거요.$B$B하지만 오크들로 마을의 일꾼을 채우려면 어둠의 의회가 필요할 것이오. 그렇게 하면 조상의 유산을 물려받는 데다가 은밀하게 일을 할 수도 있지.$B$B잠깐만... 우리가 아는 사이요? 당신의 이름이 뭐요?', `MaleText_loc4`='好吧，我正在给我们的首领进行汇报。应该只需要再多几周，我们就可以让这地方处于良好的运行状态。$B$B不过，我们可能想让暗影议会只派遣兽人来这里，那样的话，我们就能宣称这村子是我们的属地，便于进行秘密工作了。$B$B等一下，我认识你吗？你叫什么名字？', `MaleText_loc5`='好吧，我只是要給我們領袖進度報告，現在所有的事情都在進行中也包括了計畫，不出幾個禮拜，這個地方就能成型了。$B$B然而，我們希望暗影議會派一個人和獸人一起來到村莊。這樣我們就可以完成祖先的要求並且暗中進行這件事。$B$B等等，我認識你嗎?你叫什麼名字?', `MaleText_loc7`='Bueno, yo solo estaba informando a nuestro líder sobre los avances y sobre cómo todo sale según lo previsto. Solo tardaremos unas semanas más en tenerlo todo arreglado.$B$BPuede que nos convenga que el Consejo de la Sombra contrate a orcos para el pueblo. Así alegaremos derecho ancestral y podremos trabajar ocultos.$B$BUn momento. ¿Te conozco? ¿Cómo te llamas?', `FemaleText_loc1`='음, 나는 여기 우리의 지도자에게 계획의 진행 상황을 보고 드리던 참입니다. 몇 주만 더 있으면 이 장소가 제 모습을 되찾게 될 것입니다.$B$B하지만 오크들로 마을의 일꾼을 채우려면 어둠의 의회가 필요할 겁니다. 그렇게 하면 조상의 유산을 물려받는 데다가 은밀하게 일을 할 수도 있지요.$B$B잠깐만요. 우리가 아는 사이던가요? 당신의 이름이 뭡니까?', `FemaleText_loc4`='好吧，我正在给我们的首领进行汇报。应该只需要再多几周，我们就可以让这地方处于良好的运行状态。$B$B不过，我们可能想让暗影议会只派遣兽人来这里，那样的话，我们就能宣称这村子是我们的属地，便于进行秘密工作了。$B$B等一下，我认识你吗？你叫什么名字？', `FemaleText_loc5`='好吧，我只是要給我們領袖進度報告，現在所有的事情都在進行中也包括了計畫，不出幾個禮拜，這個地方就能成型了。$B$B然而，我們希望暗影議會派一個人和獸人一起來到村莊。這樣我們就可以完成祖先的要求並且暗中進行這件事。$B$B等等，我認識你嗎?你叫什麼名字?', `FemaleText_loc7`='Bueno, yo solo estaba informando a nuestro líder sobre los avances y sobre como todo sale según lo previsto. Solo tardaremos unas semanas más en tenerlo todo arreglado.$B$BPuede que nos convenga que el Consejo de la Sombra contrate a orcos para el pueblo. Así alegaremos derecho ancestral y podremos trabajar en la sombra.$B$BUn momento. ¿Te conozco? ¿Cómo te llamas?' WHERE `ID`=15768;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='젊은이, 어서 오게.', `FemaleText_loc4`='你好，年轻的$r。', `FemaleText_loc5`='你好，年輕的$r。', `FemaleText_loc7`='Hola, joven $r.' WHERE `ID`=15769;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대모님, 안녕하십니까. 가로쉬에게 저를 보자고 하셨다는 얘기를 듣고 찾아뵈었습니다.', `MaleText_loc4`='你好，盖亚安祖母。加尔鲁什告诉我您想和我谈谈。', `MaleText_loc5`='主母，你好。 卡爾洛斯說你想和我談談。', `MaleText_loc7`='Hola, Abuela. Garrosh me dijo que querías hablar conmigo.', `FemaleText_loc1`='대모님, 안녕하십니까. 가로쉬에게 저를 보자고 하셨다는 얘기를 듣고 찾아뵈었습니다.', `FemaleText_loc4`='你好，盖亚安祖母。加尔鲁什告诉我您想和我谈谈。', `FemaleText_loc5`='主母，你好。 卡爾洛斯說你想和我談談。', `FemaleText_loc7`='Hola, Abuela. Garrosh me dijo que querías hablar conmigo.' WHERE `ID`=15770;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어서 오게나, 젊은이. 난 마그하르의 대모, 게야라고 한다네.$B$B<기침을 크게 하는 대모 게야>$B$B젊은이가 여기 온 걸 보니 어둠의 문이 열렸나 보군. 이곳의 오크들은 어둠의 문의 일화를 기억하기에는 너무 어리거나 너무 병들어 있다네.$B$B<주변의 오크들을 가리키는 대모 게야>$B$B저들은 거의 다 고아이거나 곧 고아가 될 게지. 그렇네, 블랙핸드는 다른 방법을 쓸 수가 없었을 것이야. 병든 자와 건강한 자를 분리하는 것 말고는 말이지. 오직 강한 자만이 살아남을 거야... 지금은 그렇게들 말하고 있다네.', `FemaleText_loc4`='你好，亲爱的。我是盖亚安，玛格汉的女族长。$B$B<盖亚安祖母咳嗽了一下。>$B$B你在这里，那及说明黑暗之门已经重新开启了。在这里的大部分兽人都太年轻或是太虚弱，以至于不能记起黑暗之门。$B$B<盖亚安祖母指了指她周围的兽人。>$B$B他们大部分是孤儿，或很快就会变成孤儿了。是的，这就是黑手酋长的做法，让体弱者远离健康者，只有强壮的兽人可以生存……', `FemaleText_loc5`='你好，親愛的。我是吉雅，瑪格哈的女守護者。$B$B<主母吉雅咳了幾聲。>$B$B如果你待在這裡，大門會一直敞開著，所以你會很安全。大部分的獸人都太年輕、太虛弱而記不得黑暗之門。$B$B<主母吉雅指向圍繞著她的獸人。>$B$B他們大多是孤兒或是快成為孤兒，唉!黑手會用盡所有的辦法。要健健康康的，唯有強壯才能生存...所以他們才這麼說。', `FemaleText_loc7`='Hola, $gquerido:querida;. Soy Geyah, matrona de los Mag''har.$B$B<La Abuela Geyah tose.>$B$BSi estás aquí, deduzco que es porque el portal se ha abierto. La mayoría de los orcos son demasiado jóvenes o están demasiado cansados como para acordarse del Portal Oscuro.$B$B<La Abuela Geyah señala a los orcos de su alrededor.>$B$BMuchos de ellos eran huérfanos o estaban a punto de convertirse en huérfanos. Sí, Puño Negro no querría que fuese de otra forma. Aparta al sano del enfermo. Solo sobrevivirán los fuertes... Eso dicen.' WHERE `ID`=15771;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대모님, 이곳 오크들을 모두 키우신 겁니까?', `MaleText_loc4`='祖母，这里的兽人都是您抚养长大的吗？', `MaleText_loc5`='主母，妳養育了這裡全部的獸人?', `MaleText_loc7`='¿Tú criaste a todos estos orcos, Abuela?', `FemaleText_loc1`='대모님, 이곳 오크들을 모두 키우신 건가요?', `FemaleText_loc4`='祖母，这里的兽人都是您抚养长大的吗？', `FemaleText_loc5`='主母，妳養育了這裡全部的獸人?', `FemaleText_loc7`='¿Tú criaste a todos estos orcos, Abuela?' WHERE `ID`=15772;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저들은 이곳에서 자랐다네. 우리는 그들을 안전하게 보호하고 건강을 되찾아주기 위해 최선을 다해 간호했지. 죽은 오크도 많지만, 그보다 많은 어린이들이 강하게 성장했다네. 가로쉬처럼...$B$B<한숨짓는 대모 게야>$B$B알다시피 그는 마음에 크게 상처를 받았네. 가로쉬는 내가 자신을 잡아주는 존재라고 말하지. 내가 없었다면 그의 아버지를 데려갔고 우리 종족에게 저주를 내린 피에 대한 굶주림이 자기를 집어삼킬 것이라고 말이야.', `FemaleText_loc4`='他们在这里长大，我们让他们远离伤害。我尽可能地照顾他们的健康。很多都夭折了，但是更多的孩子茁壮成长了起来。就像加尔鲁什那样……$B$B<盖亚安祖母叹了口气。>$B$B你知道，他失去了他的信心。他告诉我，我是他的一切。如果失去了我，吞噬了他的父亲、诅咒了我们的人民的嗜血狂热会彻底占据他。', `FemaleText_loc5`='他們得在這裡成長，我們讓他們安全無憂。我們盡全力讓他們恢復健康。有許多虛弱的人反而更加的成長茁壯，像卡爾洛斯就是...$b$b<主母吉雅嘆了口氣。>$B$B你知道他失去了他的心。他說我是他的平衡。如果沒有了我，他血液中的貪婪會毀滅他的父親，最後還會傷害我們的人民。', `FemaleText_loc7`='Han crecido aquí. Los protegemos del peligro. Los hemos curado y alimentado lo mejor que hemos podido. Muchos murieron, pero muchos, muchos otros han crecido sanos y fuertes. Como Garrosh...$B$B<La Abuela Geyah suspira.>$B$BPerdió su corazón, ¿sabes? Me dice que soy su equilibrio. Que sin mí, la sed de sangre que consumió a su padre hará con él lo mismo.' WHERE `ID`=15773;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 말을 믿으십니까?', `MaleText_loc4`='您相信吗？', `MaleText_loc5`='你相信這個嗎?', `MaleText_loc7`='¿Eso crees?', `FemaleText_loc1`='그 말을 믿으세요?', `FemaleText_loc4`='您相信吗？', `FemaleText_loc5`='你相信這個嗎?', `FemaleText_loc7`='¿Te lo crees?' WHERE `ID`=15774;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='<웃음 짓는 대모 게야>$B$B물론 아니라네, 젊은이. 하지만, 믿음을 가져야 할 쪽은 내가 아니야...$B$B가로쉬는 강하고 현명하여 마그하르를 이끌 수 있다네. 모든 정령도 그를 인정하고 말이야. 지금 가로쉬가 자기 자신을 믿으면 돼. 그는 두려움이 너무 많아... 자기 자신을 풀어주면 분노가 자신뿐만 아니라 주변의 모든 것을 집어삼켜 버릴까 봐 두려워하고 있다네.', `FemaleText_loc4`='<盖亚安祖母虚弱地笑了笑。>$B$B当然不，亲爱的。但是这并不是我相不相信的问题……$B$B加尔鲁什有能力来领导玛格汉。他是个强壮又聪明的领袖，万灵都很支持他。他只是需要自信。他的心中充满了恐惧……他的恐惧太深了，如果不能善加引导，他的愤怒会毁灭他自己和他周围所有的人。', `FemaleText_loc5`='<祖母吉雅虛弱的笑著。>$B$B當然不是，親愛的。但這不是我相不相信的問題...$b$b卡爾洛斯可以領導瑪格哈，他強壯且睿智，所有的靈魂都認同他。只是他需要相信他自己。他太害怕了...他的恐懼如此之深，若他可以放自己一馬，他的怒氣會讓他全神貫注，所有的東西也就垂手可得了。', `FemaleText_loc7`='<Abuela Geyah ríe débilmente>$B$BClaro que no, $gquerido:querida;. Pero yo no soy quien debe creer...$B$BGarrosh puede liderar a los Mag''har. Es fuerte y sabio. Tiene el apoyo de los espíritus. Solo necesita creer en sí mismo. Tiene mucho miedo... Su miedo es tan profundo que si se deja llevar, la rabia lo consumirá a él y a cuantos lo rodeen.' WHERE `ID`=15775;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 하면 좋을까요? 수많은 시도를 해봤습니다. 나그란드의 주민들을 돕기 위해 최선을 다했고요. 하지만, 가로쉬에게 다가가려 할 때마다 그는 저를 물리치더군요.', `MaleText_loc4`='那怎么办？我已经试过很多办法了。我尽全力来帮助纳格兰的人民，但是每次我想接近加尔鲁什，他总是避开我。', `MaleText_loc5`='還有什麼可以做?我試著去做許多不同的事，我盡全力去幫助納葛蘭的人民，每次我接近卡爾洛斯，他就打發我走。', `MaleText_loc7`='¿Qué se puede hacer? He intentado muchas cosas. He hecho todo lo posible por ayudar a las gentes de Nagrand. Cada vez que me he acercado a Garrosh, me ha echado.', `FemaleText_loc1`='어떻게 하면 좋을까요? 수많은 시도를 해봤어요. 나그란드의 주민들을 돕기 위해 최선을 다했고요. 하지만, 가로쉬에게 다가가려 할 때마다 그는 저를 물리치더군요.', `FemaleText_loc4`='那怎么办？我已经试过很多办法了。我尽全力来帮助纳格兰的人民，但是每次我想接近加尔鲁什，他总是避开我。', `FemaleText_loc5`='還有什麼可以做?我試著去做許多不同的事，我盡全力去幫助納葛蘭的人民，每次我接近卡爾洛斯，他就打發我走。', `FemaleText_loc7`='¿Qué se puede hacer? He intentado muchas cosas. He hecho todo lo posible por ayudar a las gentes de Nagrand. Cada vez que me he acercado a Garrosh, me ha echado.' WHERE `ID`=15776;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그 방법을 알면 얼마나 좋겠나? 그는 자네의 말에도 나의 말에도 귀를 기울이려 하지 않을 거라네. 사실, 그게 내가 아직 여기 머무는 까닭이지. 그래서 대모 카슈르와 이곳을 떠나지 않았다네. 그는 다시 마음을 다잡아야 해. 올바른 지도자가 없이 우리 종족은 이 겨울을 무사히 넘기지 못할 것일세.', `FemaleText_loc4`='我希望我能知道该怎么做，亲爱的。他不会听你的，同样他也不会听我的。事实上，这就是我还在这里的原因，这就是我还没有和卡舒尔宗母一起离开的原因。他必须找回他的自信。如果没有合适的领导，我们的人民根本活不过这个冬天。', `FemaleText_loc5`='我希望我知道，親愛的。他既不會聽你也不會聽我的，老實說這就是為什麼我還在這裡，為什麼我還不能和族母卡修爾一起離開。他必須找到他的心，沒有了領導者我們的子民活不過這個冬天的。', `FemaleText_loc7`='Me gustaría saberlo, $gquerido:querida;. No te escuchará. Igual que no me escucha a mí. En realidad, él es la razón por la que sigo aquí. Por eso no me fui con madre Kashur. Debe encontrar su corazón. Nuestro pueblo no sobrevivirá al invierno sin un líder.' WHERE `ID`=15777;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='떠난다고요? 어떻게 그럴 수가 있습니까?', `MaleText_loc4`='离开？您怎么能选择离开呢？', `MaleText_loc5`='離開?你怎麼可以選擇離開?', `MaleText_loc7`='¿Ido? ¿Cómo puedes decidir irte?', `FemaleText_loc1`='떠난다고요? 어떻게 그럴 수가 있죠?', `FemaleText_loc4`='离开？您怎么能选择离开呢？', `FemaleText_loc5`='離開?你怎麼可以選擇離開?', `FemaleText_loc7`='¿Ido? ¿Cómo puedes decidir irte?' WHERE `ID`=15778;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='<조용히 웃음 짓는 대모 게야>$B$B난 늙었다네. 갈 때가 됐지. 내가 죽으면 내 영혼은 영혼의 세계로 갈 걸세. 그곳에서 우리 선조와 함께 머무르면서 우리 종족을 보살필 것이야.$B$B가라드가 살아 있었을 때 대모 카슈르의 의무는 내가 지금 맡고 있는 일과 똑같았네.', `FemaleText_loc4`='<盖亚安祖母笑了笑。>$B$B我老了，我的时日已经不多了。当我去世以后，我的灵魂会前往灵魂的国度。我会在那里与我的祖先们团聚。那就是我们关注着仍然活着的人民的地方。$B$B当加拉达还活着的时候，卡舒尔宗母的职责就和我现在的一样。', `FemaleText_loc5`='<主母吉雅微笑著。>$B$B我老了，時間該到了，當我走了之後，我的靈魂會移往靈界，在那裡我會和我的祖先站在一起，看著我們的子民。$B$B只要卡拉達爾還活著，族母卡修爾的義務就同我現在的義務一樣了。', `FemaleText_loc7`='<Abuela Geyah sonríe.>$B$BSoy vieja. Pronto llegará mi hora. Cuando ya no esté, mi espíritu pasará al reino de los espíritus. Allí me encontraré con mis ancestros. Desde allí protegeré a nuestro pueblo.$B$BCuando Garad vivía, el deber de madre Kashur era el que tengo yo hoy.' WHERE `ID`=15779;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 의무라는 것이 뭡니까?', `MaleText_loc4`='这个职责是什么？', `MaleText_loc5`='這個義務是什麼?', `MaleText_loc7`='¿Cuál es tu función?', `FemaleText_loc1`='그 의무라는 것이 뭐죠?', `FemaleText_loc4`='这个职责是什么？', `FemaleText_loc5`='這個義務是什麼?', `FemaleText_loc7`='¿Cuál es tu función?' WHERE `ID`=15780;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대모의 의무는 귀를 기울이는 것이라네. 바람과 물과 불, 그리고 대지의 소리에 귀를 기울이는 것이지. 온기를 지키기 위해 지푸라기를 모으는 짐승들처럼 부족을 위해 정보를 모으는 것이야. 나는 영혼들과 대화를 하지... 꿈속에서 대모 카슈르는 예전에 그녀와 대화하던 영혼들처럼 내게 말을 건다네... 내가 죽으면 나도 이런 식으로 드라키아와 켈레스틴에게 이야기를 들려줄 걸세.$B$B<빙그레 웃는 대모 게야>', `FemaleText_loc4`='部族母亲的职责就是倾听。倾听风、水、火和大地。从它们那里收集对氏族有用的信息，就像氏族中的其他人收集皮毛以供大家御寒一样。与我交流的正是灵魂……在我的梦里，卡舒尔宗母就像灵魂和她谈话那样对我谈话……当我去世之后，我会以相同的方式和德拉吉亚和塞雷斯蒂谈话。$B$B<盖亚安祖母微笑着。>', `FemaleText_loc5`='身為一位氏族之母的責任就是聆聽。傾聽風、水、火、大地的聲音。替她的氏族收集資訊，就像其他人收集毛皮以供保暖。那些靈魂和我親密地交談...在我的夢裡，族母卡修爾和我談話，正猶如那些靈魂和她談話一樣...當我走了之後，我將會用這種方式與崔克雅和瑟萊斯丁交談。$B$B< 主母吉雅微笑著。>', `FemaleText_loc7`='El deber de una madre del clan es escuchar. Escuchar el viento, el agua, el fuego y la tierra. Conseguir información para el clan del mismo modo que otros consiguen pieles para calentarnos en invierno. Yo me comunico con los espíritus... En mis sueños, madre Kashur me habla. Cuando deje este mundo, hablaré con Drakia y Celestine de este mismo modo.$B$B<La Abuela Geyah sonríe.>' WHERE `ID`=15781;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 도와드릴 일은 없습니까, 대모님?', `MaleText_loc4`='我能为你做点什么吗, 盖亚安祖母？', `MaleText_loc5`='有沒有什麼事是我可以幫忙的呢，主母?', `MaleText_loc7`='¿Puedo hacer algo por ti, Abuela?', `FemaleText_loc1`='제가 도와드릴 일은 없나요, 대모님?', `FemaleText_loc4`='我能为你做点什么吗, 盖亚安祖母？', `FemaleText_loc5`='有沒有什麼事是我可以幫忙的呢，主母?', `FemaleText_loc7`='¿Puedo hacer algo por ti, Abuela?' WHERE `ID`=15782;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에서 시간은 귀중하니 절대 낭비하지 마십시오.', `MaleText_loc4`='时间是宝贵的，不要浪费它。', `MaleText_loc5`='時間很珍貴，千萬別浪費!', `MaleText_loc7`='El tiempo es precioso, nunca lo malgastes.' WHERE `ID`=15783;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='화염 폭탄 자루를 주십시오.', `MaleText_loc4`='我需要燃烧弹包。', `MaleText_loc5`='我需要一箱燃燒彈。', `MaleText_loc7`='Necesito un paquete de bombas incendiarias.', `FemaleText_loc1`='화염 폭탄 자루를 주세요.', `FemaleText_loc4`='我需要燃烧弹包。', `FemaleText_loc5`='我需要一箱燃燒彈。', `FemaleText_loc7`='Necesito un paquete de bombas incendiarias.' WHERE `ID`=15784;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 폭탄 자루를 받으십시오, $n. 자칫 잘못 사용하면 심각한 파괴를 가져올 수 있으니 조심해서 다루도록 하십시오.', `MaleText_loc4`='要多少有多少，$n。小心使用，如果使用不当的话，这些东西是相当麻烦的。', `MaleText_loc5`='這裡有許多燃燒裝置，$n。要小心一點，要是使用不當，它們會在一個時間內造成重大傷害。', `MaleText_loc7`='Aquí hay más artefactos incendiarios, $n. Ten cuidado con ellos. Si no los usas adecuadamente, pueden provocar una catástrofe.' WHERE `ID`=15785;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 너! 여기는 네가 있을 곳이 아니다!', `MaleText_loc4`='你！你不属于这里！', `MaleText_loc5`='你!你不屬於這裡!', `MaleText_loc7`='¡Tú! ¡Este no es tu lugar!' WHERE `ID`=15786;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 수상쩍은 집단이 무슨 일을 꾸미는지 무슨 수를 써서라도 알아내고야 말겠소!', `MaleText_loc4`='我要查出那些家伙的真正计划！', `MaleText_loc5`='無論如何，我要弄清楚這個謎樣的團體到底是怎麼回事!', `MaleText_loc7`='¡Voy a averiguar lo que ese siniestro grupo está haciendo el Poblado Grangol''var!' WHERE `ID`=15787;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='윅스, 한 번 더 변장하게 해 주십시오.', `MaleText_loc4`='列兵维克斯，我还需要一个伪装。', `MaleText_loc5`='士兵維克斯，我需要其他的偽裝。', `MaleText_loc7`='Soldado Semanas, necesito otro disfraz.', `FemaleText_loc1`='윅스, 한 번 더 변장하게 해 주세요.', `FemaleText_loc4`='列兵维克斯，我还需要一个伪装。', `FemaleText_loc5`='士兵維克斯，我需要其他的偽裝。', `FemaleText_loc7`='Soldado Semanas, necesito otro disfraz.' WHERE `ID`=15788;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 그란골바르 마을의 어둠의 의회에 관한 비밀을 파해쳐줘서 고맙소.', `MaleText_loc4`='$n，谢谢你解决了格兰戈瓦村的暗影议会成员。', `MaleText_loc5`='$n，謝謝你對付了在葛蘭戈瓦村神秘的暗影議會。', `MaleText_loc7`='Gracias por ocuparte del misterio del Consejo de la Sombra en el Poblado Grangol''var, $n.' WHERE `ID`=15789;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다시 한번, 고맙습니다, $n. 당신의 도움이 없었다면 우리는 절대 그란골바르 마을의 어둠의 의회를 상대할 수 없었을 겁니다.', `FemaleText_loc4`='再次感谢，$n。没有你的帮助，我们不可能解决格兰戈瓦村的暗影议会成员。', `FemaleText_loc5`='我要再一次的感謝你，$n。沒有你的協助我們絕對沒辦法對付在葛蘭戈瓦村的暗影議會。', `FemaleText_loc7`='Te doy las gracias de nuevo, $n. Sin tu ayuda, no podríamos haber vencido al Consejo de la Sombra aquí en el pueblo de Grangol''var.' WHERE `ID`=15790;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리는 그 어둠의 집단이 그란골바르 마을에서 무엇을 하고 있는지 알아내야 합니다!', `FemaleText_loc4`='我们要找出那些家伙在格兰戈瓦村干些什么！', `FemaleText_loc5`='我們需要找出葛蘭戈瓦村謎樣的團體到底要做什麼!', `FemaleText_loc7`='¡Hay que averiguar lo que ese siniestro grupo está haciendo en el Poblado Grangol''var!' WHERE `ID`=15791;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정찰병 네프티스, 한 번 더 변장시켜 주세요.', `MaleText_loc4`='斥候奈弗蒂丝，我还需要一个伪装。', `MaleText_loc5`='斥候奈夫提斯，我需要其他的偽裝。', `MaleText_loc7`='Exploradora Neftis, necesito otro disfraz.', `FemaleText_loc1`='정찰병 네프티스, 한 번 더 변장시켜 주세요.', `FemaleText_loc4`='斥候奈弗蒂丝，我还需要一个伪装。', `FemaleText_loc5`='斥候奈夫提斯，我需要其他的偽裝。', `FemaleText_loc7`='Exploradora Neftis, necesito otro disfraz.' WHERE `ID`=15792;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 누구도 우리를 불시에 기습하지 못하도록 살펴야 하는 의무가 있네, $g형제:자매;여.$B$B즉, 사태가 발생하기 전에 미리 행동에 나서야 한다는 것이지!', `MaleText_loc4`='我们在这里有一项任务，$g小子:姑娘;，要保证这个任务万无一失。$B$B我们必须先发制人！', `MaleText_loc5`='對於這裡我們有應盡的義務，$g男孩:女孩;好好留意，別讓任何人對我們進行突襲。$B$B也就是說我們要主動行動!', `MaleText_loc7`='Tenemos una misión que cumplir, $gamigo:amiga;: no dejarnos sorprender por nadie.$B$B¡Y eso significa que hay que actuar antes que ellos!' WHERE `ID`=15793;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이곳으로 배정되다니 내가 뭔가 실수를 한 것이 틀림없어요.', `FemaleText_loc4`='我肯定在某个地方做错了什么，才被分配到这里来。', `FemaleText_loc5`='我一定做錯了什麼才會被分派到這裡。', `FemaleText_loc7`='He tenido que hacer algo mal en algún sitio para que me destinaran aquí.' WHERE `ID`=15794;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소식 들으셨어요? 어둠의 미궁에 있는 울림의 통제권을 잃어버렸다던데...', `MaleText_loc4`='你有没有听说他们在暗影迷宫里完全失去了对摩摩尔的控制？！', `MaleText_loc5`='你聽說他們已經失去對暗影迷宮莫爾墨的控制了嗎?', `MaleText_loc7`='¡¿Has oído que han perdido el control total de Murmullo en el Laberinto de las Sombras?!', `FemaleText_loc1`='소식 들으셨어요? 어둠의 미궁에 있는 울림의 통제권을 잃어버렸다던데...', `FemaleText_loc4`='你有没有听说他们在暗影迷宫里完全失去了对摩摩尔的控制？！', `FemaleText_loc5`='你聽說他們已經失去對暗影迷宮莫爾墨的控制了嗎?', `FemaleText_loc7`='¡¿Has oído que han perdido el control total de Murmullo en el Laberinto de las Sombras?!' WHERE `ID`=15795;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일은 고된데 보수는 시원치가 않네요. 하지만, 폐허가 된 이 마을은 아킨둔 안으로 잠행하는 자들을 확실히 막아내지요.', `MaleText_loc4`='他们没有付足够的工钱给我们。但是在这座荒废的村庄总比在奥金顿里躲躲藏藏好多了。', `MaleText_loc5`='他們對我們付出的還不夠。但這個被摧毀的村莊絕對讓奧齊頓深受打擊。', `MaleText_loc7`='No nos pagan lo suficiente por hacer esto. Pero este pueblo ruinoso sin duda es mejor que merodear dentro de Auchindoun.', `FemaleText_loc1`='일은 고된데 보수는 시원치가 않네요. 하지만, 폐허가 된 이 마을은 아킨둔 안으로 잠행하는 자들을 확실히 막아내지요.', `FemaleText_loc4`='他们没有付足够的工钱给我们。但是在这座荒废的村庄总比在奥金顿里躲躲藏藏好多了。', `FemaleText_loc5`='他們對我們付出的還不夠。但這個被摧毀的村莊絕對讓奧齊頓深受打擊。', `FemaleText_loc7`='No nos pagan lo suficiente por hacer esto. Pero este pueblo ruinoso sin duda es mejor que merodear dentro de Auchindoun.' WHERE `ID`=15796;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 그들이 내 학비를 대 주겠다고 했기 때문에 참여하게 되었습니다. 삼촌 말로는 내가 다음 학기에 들어갈 수 있다는군요!', `MaleText_loc4`='我加入他们，因为他们说可以付给我足够的钱让我去学院。我叔叔说我下个学期就可以去了！', `MaleText_loc5`='我會參加是因為他們說他們會讓我進入學院。我叔叔說下一季我也可以來!', `MaleText_loc7`='Me enrolé porque dijeron que me pagarían la academia. ¡Mi tío dice que podré ir la próxima temporada!', `FemaleText_loc1`='나는 그들이 내 학비를 대 주겠다고 했기 때문에 참여하게 되었습니다. 삼촌 말로는 내가 다음 학기에 들어갈 수 있다는군요!', `FemaleText_loc4`='我加入他们，因为他们说可以付给我足够的钱让我去学院。我叔叔说我下个学期就可以去了！', `FemaleText_loc5`='我會參加是因為他們說他們會讓我進入學院。我叔叔說下一季我也可以來!', `FemaleText_loc7`='Me enrolé porque dijeron que me pagarían la academia. ¡Mi tío dice que podré ir la próxima temporada!' WHERE `ID`=15797;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어이, 당신은 새로 온 친구가 틀림없군요! 만나서 반갑습니다!$B$B아킨둔의 어둠의 미궁에서 울림의 통제권을 회복에 대해서 들려온 소식 없나요?', `MaleText_loc4`='你好，你肯定是新来的吧！很高兴认识你！$B$B有没有从奥金顿暗影迷宫传来有关我们是否重新控制了摩摩尔的消息？', `MaleText_loc5`='嘿!你一定是那個新成員吧!很高興認識你!$B$B奧齊頓的暗影迷宮是否有傳來消息表示我們奪回莫爾墨的控制權了?', `MaleText_loc7`='¡Eh, hola! Tú debes de ser $gel nuevo:la nueva; recluta. Encantado de conocerte.$B$B¿Algún mensaje del Laberinto de las Sombras de Auchindoun sobre si ya hemos recuperado el control de Murmullo?', `FemaleText_loc1`='어이, 당신은 새로 온 친구가 틀림없군요! 만나서 반갑습니다!$B$B아킨둔의 어둠의 미궁에서 울림의 통제권을 회복에 대해서 들려온 소식 없나요?', `FemaleText_loc4`='你好，你肯定是新来的吧！很高兴认识你！$B$B有没有从奥金顿暗影迷宫传来有关我们是否重新控制了摩摩尔的消息？', `FemaleText_loc5`='嘿!你一定是那個新成員吧!很高興認識你!$B$B奧齊頓的暗影迷宮是否有傳來消息表示我們奪回莫爾墨的控制權了?', `FemaleText_loc7`='¡Eh, hola! Tú debes de ser $gel nuevo:la nueva; recluta. Encantado de conocerte.$B$B¿Algún mensaje del Laberinto de las Sombras de Auchindoun sobre si ya hemos recuperado el control de Murmullo?' WHERE `ID`=15798;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나중에 한잔 하러 샤트라스에 갈 예정인데 혹시 관심 있으시면 같이 갑시다.', `MaleText_loc4`='我们一群人准备稍后去沙塔斯城喝酒，你有兴趣吗？', `MaleText_loc5`='如果你有興趣的話，我們幾個等一下要去撒塔斯城喝點東西。', `MaleText_loc7`='Si te interesa, algunos iremos a tomar algo a Shattrath después.', `FemaleText_loc1`='나중에 한잔 하러 샤트라스에 갈 예정인데 혹시 관심 있으시면 같이 가요.', `FemaleText_loc4`='我们一群人准备稍后去沙塔斯城喝酒，你有兴趣吗？', `FemaleText_loc5`='如果你有興趣的話，我們幾個等一下要去撒塔斯城喝點東西。', `FemaleText_loc7`='Si te interesa, algunos iremos a tomar algo a Shattrath después.' WHERE `ID`=15799;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가죽 공놀이 경기에 참여할 생각이 있습니까? 우린 월요일에서 수요일까지 거의 매주 경기한답니다.$B$B이번 교대 시간이 끝나면 시합을 할 예정인데 우리와 함께 땀을 흘려도 좋습니다.', `MaleText_loc4`='有兴趣加入我们的皮球联赛吗？大部分情况下，我们在周一至周三比赛。$B$B我们很欢迎你在这次轮班以后加入我们。', `MaleText_loc5`='你有興趣參加我們的皮球隊?我們大部分是從星期一練習到星期三。$B$B等這回合之後歡迎你加入，我們要丟球了!', `MaleText_loc7`='¿Te apetece participar con nosotros en la liga de la pelota de cuero? Jugamos de lunes a miércoles casi siempre.$B$BVente si quieres después de este turno. Iremos a dar unas patadas.', `FemaleText_loc1`='가죽 공놀이 경기에 참여할 생각이 있나요? 우린 월요일에서 수요일까지 거의 매주 경기한답니다.$B$B이번 교대 시간이 끝나면 시합을 할 예정인데 우리와 함께 땀을 흘려도 좋아요.', `FemaleText_loc4`='有兴趣加入我们的皮球联赛吗？大部分情况下，我们在周一至周三比赛。$B$B我们很欢迎你在这次轮班以后加入我们。', `FemaleText_loc5`='你有興趣參加我們的皮球隊?我們大部分是從星期一練習到星期三。$B$B等這回合之後歡迎你加入，我們要丟球了!', `FemaleText_loc7`='¿Te apetece participar con nosotros en la liga de la pelota de cuero? Jugamos de lunes a miércoles casi siempre.$B$BVente si quieres después de este turno. Iremos a dar unas patadas.' WHERE `ID`=15800;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳이 어둠의 의회의 작전 기지가 되었으면 좋겠어요. 이상하게 들리실 테지만 어둠의 미궁이 그립네요.', `MaleText_loc4`='我希望这个地方可以成为暗影议会的前哨基地。我知道这听上去很奇怪，但是我真的有点想念暗影迷宫了。', `MaleText_loc5`='我希望這個地方能成為暗影議會運作的前哨站。我知道這聽起來很怪，但是我還真有點想念暗影迷宮。', `MaleText_loc7`='Espero que este lugar sirva como base de la vanguardia de las operaciones del Consejo de la Sombra. Sé que suena raro, pero echo de menos el Laberinto de las Sombras.', `FemaleText_loc1`='이곳이 어둠의 의회의 작전 기지가 되었으면 좋겠어요. 이상하게 들리실 테지만 어둠의 미궁이 그립네요.', `FemaleText_loc4`='我希望这个地方可以成为暗影议会的前哨基地。我知道这听上去很奇怪，但是我真的有点想念暗影迷宫了。', `FemaleText_loc5`='我希望這個地方能成為暗影議會運作的前哨站。我知道這聽起來很怪，但是我還真有點想念暗影迷宮。', `FemaleText_loc7`='Espero que este lugar sirva como base de la vanguardia de las operaciones del Consejo de la Sombra. Sé que suena raro, pero echo de menos el Laberinto de las Sombras.' WHERE `ID`=15801;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<당신의 귀 가까이 입을 댑니다.>$B$B우리끼리 비밀 얘기지만 조만간 야간 교대 시간에 그냥 ''제대''해 버릴 생각입니다. 무슨 말인지 알지요?', `MaleText_loc4`='<他斜靠了过来。>$B$B就我和你，我想也许哪天晚上我们可以一起出去，你知道我的意思。', `MaleText_loc5`='<他靠近了一點。>$B$B這裡就只有你和我，我在想要不要鼓起勇氣在某個夜裡離開這裡。你懂嗎?', `MaleText_loc7`='<Se acerca un poco.>$B$BEntre tú y yo. Estoy pensando en escaquearme una noche de estas, ¿me entiendes?', `FemaleText_loc1`='<당신의 귀 가까이 입을 댑니다.>$B$B우리끼리 비밀 얘기지만 조만간 야간 교대 시간에 그냥 ''제대''해 버릴 생각입니다. 무슨 말인지 알지요?', `FemaleText_loc4`='<她斜靠了过来。>$B$B就我和你，我想也许哪天晚上我们可以一起出去，你知道我的意思。', `FemaleText_loc5`='<她靠近了一點。>$B$B這裡就只有你和我，我在想要不要鼓起勇氣在某個夜裡離開這裡。你懂嗎?', `FemaleText_loc7`='<Se acerca un poco.>$B$BEntre tú y yo. Estoy pensando en escaquearme una noche de estas, ¿me entiendes?' WHERE `ID`=15802;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 뭔데 여기 와서 나한테 이래라저래라 하는 거지? 이 마을에서 어둠의 의회의 지도자요. 내 눈앞에서 썩 꺼지라고!$B$B다시 내 눈에 띄는 날에는 세상 끝날 줄 아시오. 알아들었소?$B$B아마도 아킨둔의 어둠의 미궁에 묻히거나 울림에게 희생당하고 싶은 건가?', `MaleText_loc4`='你以为你是谁，竟敢走进来打扰我？我是这座村子中的暗影议会首领。滚出我的视野！$B$B如果再让我看到你，你就玩完了，懂吗？$B$B你是喜欢被埋葬在奥金顿的迷宫里，还是去给摩摩尔当祭品呢？', `MaleText_loc5`='你以為你是誰可以跑進這裡跟我大小聲?我是這村子暗影議會的領導人。滾出我的視線!$B$B如果再讓我看到你，我會讓你看不到明天的太陽。懂了嗎?$B$B或許你想被葬在奧齊頓的迷宮裡，或是獻祭給莫爾墨?', `MaleText_loc7`='¿Quién te crees para aparecer por aquí y hablarme sin más? Soy el líder del Consejo de la Sombra en este pueblo. ¡Fuera de mi vista!$B$BSi te vuelvo a ver, seré la última persona que veas, ¿entendido?$B$BQuizás te gustaría que te enterraran en el laberinto de Auchindoun, o te sacrificaran a Murmur.' WHERE `ID`=15803;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 이럴 수가 있지? 터놓고 얘기하자는 건데!', `MaleText_loc4`='你怎么能这么做？亏我这么信任你！', `MaleText_loc5`='你怎麼可以這麼做?我是這麼信任你!', `MaleText_loc7`='¿Cómo puedes hacerme esto? ¡Confiaba en ti!', `FemaleText_loc1`='어떻게 이럴 수가 있지? 터놓고 얘기하자는 건데!', `FemaleText_loc4`='你怎么能这么做？亏我这么信任你！', `FemaleText_loc5`='你怎麼可以這麼做?我是這麼信任你!', `FemaleText_loc7`='¿Cómo puedes hacerme esto? ¡Confiaba en ti!' WHERE `ID`=15804;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가죽 공놀이 경기에서 빠진 게 분명하군!', `MaleText_loc4`='你被皮球队开除了！', `MaleText_loc5`='你得離開皮球隊!', `MaleText_loc7`='¡Estás fuera del equipo de la pelota de cuero!', `FemaleText_loc1`='가죽 공놀이 경기에서 빠진 게 분명하군!', `FemaleText_loc4`='你被皮球队开除了！', `FemaleText_loc5`='你得離開皮球隊!', `FemaleText_loc7`='¡Estás fuera del equipo de la pelota de cuero!' WHERE `ID`=15805;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나중에 우리와 한잔 하는 건 잊어버리라고!', `MaleText_loc4`='不用再想那些酒啦！', `MaleText_loc5`='你可以晚點再忘記那些飲料!', `MaleText_loc7`='¡Olvídate de tomar algo después!', `FemaleText_loc1`='나중에 우리와 한잔 하는 건 잊어버리시오!', `FemaleText_loc4`='不用再想那些酒啦！', `FemaleText_loc5`='你可以晚點再忘記那些飲料!', `FemaleText_loc7`='¡Olvídate de tomar algo después!' WHERE `ID`=15806;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신고식이라고? 장례식은 어때?!', `MaleText_loc4`='特别的午餐？一个特别的死亡怎么样？', `MaleText_loc5`='特別午餐?要不來個特別的死亡餐點?', `MaleText_loc7`='¿Comida especial? ¡Mejor una muerte especial!', `FemaleText_loc1`='신고식이라고? 장례식은 어때?!', `FemaleText_loc4`='特别的午餐？一个特别的死亡怎么样？', `FemaleText_loc5`='特別午餐?要不來個特別的死亡餐點?', `FemaleText_loc7`='¿Comida especial? ¡Mejor una muerte especial!' WHERE `ID`=15807;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음, 그래... 잡아라!', `MaleText_loc4`='嗯，是的……拿下他们！', `MaleText_loc5`='嗯，是呀...搞定他們!', `MaleText_loc7`='Mmm..., eso. ¡A por ellos!', `FemaleText_loc1`='음, 그래... 잡아라!', `FemaleText_loc4`='嗯，是的……拿下他们！', `FemaleText_loc5`='嗯，是呀...搞定他們!', `FemaleText_loc7`='Mmm..., eso. ¡A por ellos!' WHERE `ID`=15808;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='단짝 친구가 될 수 있을 거라 생각했는데!', `MaleText_loc4`='我想我们会变成最好的朋友！', `MaleText_loc5`='我想我們可以成為最好的朋友!', `MaleText_loc7`='¡Pensé que íbamos a llevarnos bien!', `FemaleText_loc1`='단짝 친구가 될 수 있을 거라 생각했는데!', `FemaleText_loc4`='我想我们会变成最好的朋友！', `FemaleText_loc5`='我想我們可以成為最好的朋友!', `FemaleText_loc7`='¡Pensé que íbamos a llevarnos bien!' WHERE `ID`=15809;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐야? 새로 온 녀석이잖아?!', `MaleText_loc4`='什么？这家伙是新来的吗？', `MaleText_loc5`='什麼?那傢伙不是新來的?', `MaleText_loc7`='¿Qué? ¿No es ese $gel nuevo:la nueva;?', `FemaleText_loc1`='뭐야? 새로 온 녀석이잖아?!', `FemaleText_loc4`='什么？这家伙是新来的吗？', `FemaleText_loc5`='什麼?那傢伙不是新來的?', `FemaleText_loc7`='¿Qué? ¿No es ese $gel nuevo:la nueva;?' WHERE `ID`=15810;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='젠장, 당신이 그럭저럭 마음에 들었는데...', `MaleText_loc4`='该死，我有些喜欢你了。', `MaleText_loc5`='可惡，我有點喜歡你了。', `MaleText_loc7`='Rayos. Si hasta me caías bien.', `FemaleText_loc1`='젠장, 당신이 그럭저럭 마음에 들었는데...', `FemaleText_loc4`='该死，我有些喜欢你了。', `FemaleText_loc5`='可惡，我有點喜歡你了。', `FemaleText_loc7`='Rayos. Si hasta me caías bien.' WHERE `ID`=15811;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='베르텔름이 최근 작품 제작을 위해 가죽을 모으고 있다는 소문을 들었어요. 당신에게는 망토를 만들 거라고 말했겠지요?$B$B망토는 무슨... 사실은 그가 자신의 늑대 가죽 모자띠를 비밀에 부치려고 둘러대는 말에 불과하답니다. 그는 단지 그 늑대 가죽 모자띠를 전투에서 더럽히자고 가죽을 수집하기 위해 그 많은 노력을 하려는 거라니까요!', `FemaleText_loc4`='我听说波尔泰姆为了他的最新发明收集了很多毛皮。他对你说是件披风，对吗？$B$B其实那些毛皮是用来作帽子的。他不可能他把用尽全力收集的毛皮做成一件在战斗中很快就会弄脏的东西！', `FemaleText_loc5`='我聽伯特泰歐正在為他最新的創作收集軟毛。他告訴你這是用來做披風的，是吧?$B$B不是，那他就是用來掩飾要做成狼毛帽帶的秘密。他不會無緣無故放下所有的工作，只為了收集沾滿泥土的軟毛吧!', `FemaleText_loc7`='He oído de que Bertelem ha estado comprando pieles para su última creación. Te dijo que sería una capa, ¿verdad?$B$BPues no es una capa. Es lo que dice para guardar el secreto de su banda de piel de lobo para sombreros. ¡No se habría esforzado tanto en conseguir esas pieles para que luego se manchasen en la batalla!' WHERE `ID`=15812;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛의 전당에서 상급 연금술사들을 찾을 수 있을 겁니다. 정의의 길을 가시기를...', `MaleText_loc4`='炼金术训练师就在圣光穹顶。愿圣光与你同在。', `MaleText_loc5`='你會在聖光地窖找到鍊金術訓練師。願聖光與你同行。', `MaleText_loc7`='Encontrarás a nuestro instructor alquimista en El Arca de las Luces. Ve con la Luz.', `FemaleText_loc1`='빛의 전당에서 상급 연금술사들을 찾을 수 있을 겁니다. 정의의 길을 가시기를...', `FemaleText_loc4`='炼金术训练师就在圣光穹顶。愿圣光与你同在。', `FemaleText_loc5`='你會在聖光地窖找到鍊金術訓練師。願聖光與你同行。', `FemaleText_loc7`='Encontrarás a nuestro instructor alquimista en El Arca de las Luces. Ve con la Luz.' WHERE `ID`=15813;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비록 부의 획득이 더는 우리 삶의 목표는 아니나 우리는 세상을 움직이는 것은 돈이라는 사실을 잘 알고 있습니다. 나루의 보좌로 가면 경매장에 가실 수 있습니다.', `MaleText_loc4`='尽管获取财富已经不是我们生活的动力了，但我们仍懂得有钱能使鬼推磨的道理。你可以在纳鲁之座找到我们的拍卖行。', `MaleText_loc5`='雖然獲得財富不再是我們生活的動力，但我們知道有錢能使鬼推磨的道理。你可以在那魯之座找到我們的拍賣場。', `MaleText_loc7`='Aunque la acumulación de riqueza ya no es el objetivo principal de nuestras vidas, somos conscientes de que el dinero es lo que hace que se mueva el mundo. Encontrarás nuestra casa de subastas en el Trono de los Naaru.', `FemaleText_loc1`='비록 부의 획득이 더는 우리 삶의 목표는 아니나 우리는 세상을 움직이는 것은 돈이라는 사실을 잘 알고 있습니다. 나루의 보좌로 가면 경매장에 가실 수 있습니다.', `FemaleText_loc4`='尽管获取财富已经不是我们生活的动力了，但我们仍懂得有钱能使鬼推磨的道理。你可以在纳鲁之座找到我们的拍卖行。', `FemaleText_loc5`='雖然獲得財富不再是我們生活的動力，但我們知道有錢能使鬼推磨的道理。你可以在那魯之座找到我們的拍賣場。', `FemaleText_loc7`='Aunque la acumulación de riqueza ya no es el objetivo principal de nuestras vidas, somos conscientes de que el dinero es lo que hace que se mueva el mundo. Encontrarás nuestra casa de subastas en el Trono de los Naaru.' WHERE `ID`=15814;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엑소다르의 중심지에 가면 은행이 있습니다. 성스러운 빛이 함께하시길...', `MaleText_loc4`='银行就在埃索达的中心地带。愿圣光与你同在。', `MaleText_loc5`='你會在艾克索達的中央找到銀行。願聖光與你同行。', `MaleText_loc7`='El banco se encuentra en la cabina central de El Exodar. Ve con la Luz.', `FemaleText_loc1`='엑소다르의 중심지에 가면 은행이 있습니다. 성스러운 빛이 함께하시길...', `FemaleText_loc4`='银行就在埃索达的中心地带。愿圣光与你同在。', `FemaleText_loc5`='你會在艾克索達的中央找到銀行。願聖光與你同行。', `FemaleText_loc7`='El banco se encuentra en la cabina central de El Exodar. Ve con la Luz.' WHERE `ID`=15815;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 히포그리프 조련사는 스테파노스입니다. 그는 엑소다르의 중심지에 있습니다. 당신의 여행에 성스러운 빛이 함께하기를.', `MaleText_loc4`='斯泰法努斯是我们的角鹰兽管理员。他就在埃索达的中央。愿圣光庇护你。', `MaleText_loc5`='史丹樊那斯是我們的角鷹獸管理員。他就在艾克索達的中央地帶。願聖光在旅途中與你同在。', `MaleText_loc7`='Stephanos es nuestro maestro de grifos. Vive en la cabina central de El Exodar. Que la Luz te acompañe en tus viajes.', `FemaleText_loc1`='우리 히포그리프 조련사는 스테파노스입니다. 그는 엑소다르의 중심지에 있습니다. 당신의 여행에 성스러운 빛이 함께하기를.', `FemaleText_loc4`='斯泰法努斯是我们的角鹰兽管理员。他就在埃索达的中央。愿圣光庇护你。', `FemaleText_loc5`='史丹樊那斯是我們的角鷹獸管理員。他就在艾克索達的中央地帶。願聖光在旅途中與你同在。', `FemaleText_loc7`='Stephanos es nuestro maestro de grifos. Vive en la cabina central de El Exodar. Que la Luz te acompañe en tus viajes.' WHERE `ID`=15816;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛의 전당에 가면 우리의 투기장 사무관을 찾을 수 있을 겁니다. 그리고 간병인 브릴과 함께 지내는 "미글릭 블롯스트롬"이라는 고블린이 있는데, 자신을 세계 투기장 결투 대회 대표라고 주장한다고 하더군요.', `MaleText_loc4`='你可以在圣光穹顶找到我们的战场军官。在布雷尔旁还有个叫米格里克·布罗斯托的家伙，他自称是这个世界上的竞技场巡回赛的官方代表。', `MaleText_loc5`='你可以在聖光地窖找到我們的戰場軍官。那裡有一個叫「米格萊克·布拉特斯托姆」和要求代表這個世界環形競技場的照顧者布利尤在一塊兒。', `MaleText_loc7`='Nuestros maestros de batalla están en el Arca de las Luces. También encontrarás a ''Miglik Borrón'' junto al cuidador Breel; dice ser el representante del círculo de lucha de este mundo.', `FemaleText_loc1`='빛의 전당에 가면 우리의 투기장 사무관을 찾을 수 있을 겁니다. 그리고 간병인 브릴과 함께 지내는 "미글릭 블롯스트롬"이라는 고블린이 있는데, 자신을 세계 투기장 결투 대회 대표라고 주장한다고 하더군요.', `FemaleText_loc4`='你可以在圣光穹顶找到我们的战场军官。在布雷尔旁还有个叫米格里克·布罗斯托的家伙，他自称是这个世界上的竞技场巡回赛的官方代表。', `FemaleText_loc5`='你可以在聖光地窖找到我們的戰場軍官。那裡有一個叫「米格萊克·布拉特斯托姆」和要求代表這個世界環形競技場的照顧者布利尤在一塊兒。', `FemaleText_loc7`='Nuestros maestros de batalla están en el Arca de las Luces. También encontrarás a ""Miglik Borrón"" junto al cuidador Breel; dice ser el representante del círculo de lucha de este mundo.' WHERE `ID`=15817;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미알은 엑소다르의 수석 대장장이랍니다. 그녀는 교역 지구의 아래층에 있으니 그리로 가 보십시오. 성스러운 빛이 함께하기를.', `MaleText_loc4`='米阿尔是我们埃索达的首席铁匠，你可以在贸易阶梯的底层找到她。愿圣光与你同行。', `MaleText_loc5`='米歐是我們艾克索達的首席鐵匠，你可以在貿易區較低的一層中找到她，願聖光與你同行。', `MaleText_loc7`='Miall es nuestra herrera en jefe en El Exodar. La encontrarás en la parte baja de la Grada de los Mercaderes.', `FemaleText_loc1`='미알은 엑소다르의 수석 대장장이랍니다. 그녀는 교역 지구의 아래층에 있으니 그리로 가 보십시오. 성스러운 빛이 함께하기를.', `FemaleText_loc4`='米阿尔是我们埃索达的首席铁匠，你可以在贸易阶梯的底层找到她。愿圣光与你同行。', `FemaleText_loc5`='米歐是我們艾克索達的首席鐵匠，你可以在貿易區較低的一層中找到她，願聖光與你同行。', `FemaleText_loc7`='Miall es nuestra herrera en jefe en El Exodar. La encontrarás en la parte baja de la Grada de los Mercaderes.' WHERE `ID`=15818;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 직업 상급자를 찾으십니까?', `MaleText_loc4`='你在寻找什么训练师？', `MaleText_loc5`='你在尋找什麼樣的訓練師?', `MaleText_loc7`='¿Qué instructor buscas?', `FemaleText_loc1`='어떤 직업 상급자를 찾으십니까?', `FemaleText_loc4`='你在寻找什么训练师？', `FemaleText_loc5`='你在尋找什麼樣的訓練師?', `FemaleText_loc7`='¿Qué instructor buscas?' WHERE `ID`=15819;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드루이드? 오... 샬란니우스, 샬란니우스를 찾으시는군요. 엑소다르 외곽, 발라르의 나루 근처에서 이 나이트 엘프를 찾을 수 있을 겁니다.', `MaleText_loc4`='德鲁伊？啊……沙兰尤斯，你在找沙兰尤斯吧。你可以在埃索达的外面找到这个暗夜精灵，就在瓦拉尔港口附近。', `MaleText_loc5`='德魯伊?啊...薩娜妮斯...你在找薩娜妮斯。你可以在艾克索達外面找到那個夜精靈，靠近瓦拉船台那裡。', `MaleText_loc7`='¿Druida? Ah... Shalannius. Buscas a Shalannius. Encontrarás a ese elfo de la noche fuera de El Exodar, al lado del atracadero de Valaar.', `FemaleText_loc1`='드루이드? 오... 샬란니우스, 샬란니우스를 찾으시는군요. 엑소다르 외곽, 발라르의 나루 근처에서 이 나이트 엘프를 찾을 수 있을 겁니다.', `FemaleText_loc4`='德鲁伊？啊……沙兰尤斯，你在找沙兰尤斯吧。你可以在埃索达的外面找到这个暗夜精灵，就在瓦拉尔港口附近。', `FemaleText_loc5`='德魯伊?啊...薩娜妮斯...你在找薩娜妮斯。你可以在艾克索達外面找到那個夜精靈，靠近瓦拉船台那裡。', `FemaleText_loc7`='¿Druida? Ah... Shalannius. Buscas a Shalannius. Encontrarás a ese elfo de la noche fuera de El Exodar, al lado del atracadero de Valaar.' WHERE `ID`=15820;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 마법부여사들은 수정 전당에 보석세공사들 맞은 편에 있습니다. 성스러운 빛이 함께하기를.', `MaleText_loc4`='我们的附魔师们就在水晶大厅，珠宝匠的对面。圣光与你同在。', `MaleText_loc5`='我們的附魔師位於水晶大廳的珠寶工藝師的對面，願聖光與你同在。', `MaleText_loc7`='Nuestros encantadores están en la Sala de Cristal, enfrente de los joyeros. Qué la luz de acompañe.', `FemaleText_loc1`='우리의 마법부여사들은 수정 전당에 보석세공사들 맞은 편에 있습니다. 성스러운 빛이 함께하기를.', `FemaleText_loc4`='我们的附魔师们就在水晶大厅，珠宝匠的对面。圣光与你同在。', `FemaleText_loc5`='我們的附魔師位於水晶大廳的珠寶工藝師的對面，願聖光與你同在。', `FemaleText_loc7`='Nuestros encantadores están en la Sala de Cristal, enfrente de los joyeros. Qué la luz de acompañe.' WHERE `ID`=15821;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 위대한 엑소다르의 재건을 기꺼이 돕겠다고요? 엑소다르가 다시 원래 기능을 되찾으려면 몇 년은 걸릴 거라고 들었습니다. 당신에게는 두 시간을 드리지요. 농담입니다. 우리 기술자들은 교역 지구의 아래층에 있으니 그리로 가 보십시오. 성스러운 빛이 함께하기를.', `MaleText_loc4`='这么看来，你想帮我们修理埃索达吗？我听说让埃索达再度恢复所有功能需要几年的时间，但你只有两个小时。开个玩笑。我们的工程师们就在贸易阶梯的底层，愿圣光与你同行。', `MaleText_loc5`='所以你願意幫助我們恢復偉大的艾克索達囉? 我聽說要讓艾克索達再次充滿生機需要花上幾年的時間。但是你只有兩個小時喔。開玩笑的啦，我們的工程師位於貿易區較低的一層，願聖光與你同行。', `MaleText_loc7`='¿Así que quieres ayudarnos a reparar el gran Exodar? He oído que pasarán años antes de que El Exodar vuelva a estar operativo. Tienes dos horas. Es broma. Nuestros ingenieros están en las partes bajas de la Grada de los Mercaderes. Ve con la Luz.', `FemaleText_loc1`='그래, 위대한 엑소다르의 재건을 기꺼이 돕겠다고요? 엑소다르가 다시 원래 기능을 되찾으려면 몇 년은 걸릴 거라고 들었습니다. 당신에게는 두 시간을 드리지요. 농담입니다. 우리 기술자들은 교역 지구의 아래층에 있으니 그리로 가 보십시오. 성스러운 빛이 함께하기를.', `FemaleText_loc4`='这么看来，你想帮我们修理埃索达吗？我听说让埃索达再度恢复所有功能需要几年的时间，但你只有两个小时。开个玩笑。我们的工程师们就在贸易阶梯的底层，愿圣光与你同行。', `FemaleText_loc5`='所以你願意幫助我們恢復偉大的艾克索達囉? 我聽說要讓艾克索達再次充滿生機需要花上幾年的時間。但是你只有兩個小時喔。開玩笑的啦，我們的工程師位於貿易區較低的一層，願聖光與你同行。', `FemaleText_loc7`='¿Así que quieres ayudarnos a reparar el gran Exodar? He oído que pasarán años antes de que El Exodar vuelva a estar operativo. Tienes dos horas. Es broma. Nuestros ingenieros están en las partes bajas de la Grada de los Mercaderes. Ve con la Luz.' WHERE `ID`=15822;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛의 이름으로! 타인의 안녕에 관심을 가지는 자가 있다는 것은 축복 받은 일이지요. 이렇게 어려운 시기에는 받을 수 있는 도움은 모두 받아야 합니다. 수정 전당의 수정 동굴 근처에 있는 누스가 당신에게 응급치료법을 가르쳐 줄 수 있을 겁니다. 성스러운 빛이 함께하기를.', `MaleText_loc4`='以圣光之名！有人愿意关心其他人的安宁真是一种幸福。在这种时候，我们就是应该互帮互助帮助。努丝可以教你急救技能，她就在水晶大厅的水晶洞附近。圣光与你同在！', `MaleText_loc5`='聖光保佑你!這個祝福是給予那些關心其他人的人。每一次都像我們需要得到所有的幫助。衲斯在這方面可以給予你急救的訓練。她在水晶大廳的水晶洞穴附近。願聖光與你同在!', `MaleText_loc7`='¡Por la Luz! Es una bendición encontrar a alguien que se preocupe por el bienestar de los demás. En un momento como este, necesitamos todas las manos posibles. Nus te puede adiestrar en primeros auxilios. Está cerca de la cueva de cristales de la Sala de Cristal.', `FemaleText_loc1`='빛의 이름으로! 타인의 안녕에 관심을 가지는 자가 있다는 것은 축복 받은 일이지요. 이렇게 어려운 시기에는 받을 수 있는 도움은 모두 받아야 합니다. 수정 전당의 수정 동굴 근처에 있는 누스가 당신에게 응급치료법을 가르쳐 줄 수 있을 겁니다. 성스러운 빛이 함께하기를.', `FemaleText_loc4`='以圣光之名！有人愿意关心其他人的安宁真是一种幸福。在这种时候，我们就是应该互帮互助帮助。努丝可以教你急救技能，她就在水晶大厅的水晶洞附近。圣光与你同在！', `FemaleText_loc5`='聖光保佑你!這個祝福是給予那些關心其他人的人。每一次都像我們需要得到所有的幫助。衲斯在這方面可以給予你急救的訓練。她在水晶大廳的水晶洞穴附近。願聖光與你同在!', `FemaleText_loc7`='¡Por la Luz! Es una bendición encontrar a alguien que se preocupe por el bienestar de los demás. En un momento como este, necesitamos todas las manos posibles. Nus te puede adiestrar en primeros auxilios. Está cerca de la cueva de cristales de la Sala de Cristal.' WHERE `ID`=15823;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만!', `MaleText_loc4`='住手！', `MaleText_loc5`='住手!', `MaleText_loc7`='¡Para!', `FemaleText_loc1`='그만!', `FemaleText_loc4`='住手！', `FemaleText_loc5`='住手!', `FemaleText_loc7`='¡Para!' WHERE `ID`=15824;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제발 그만 좀...', `MaleText_loc4`='你能不能先别——', `MaleText_loc5`='你能不能住手--', `MaleText_loc7`='Para de una...', `FemaleText_loc1`='제발 그만 좀...', `FemaleText_loc4`='你能不能先别——', `FemaleText_loc5`='你能不能住手--', `FemaleText_loc7`='Para de una...' WHERE `ID`=15825;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수정 전당의 축복받은 빛의 샘 근처에서 전문 낚시꾼 에레트를 찾을 수 있을 겁니다.', `MaleText_loc4`='你可以在水晶大厅靠近圣泉的地方找到钓鱼训练师伊雷特。', `MaleText_loc5`='你可以在靠近聖光之水的水晶大廳找到釣魚訓練師伊瑞德 。', `MaleText_loc7`='Encontrarás a Erett el instructor de pesca en la Sala de Cristal, cerca de las aguas bendecidas por la Luz.', `FemaleText_loc1`='수정 전당의 축복받은 빛의 샘 근처에서 전문 낚시꾼 에레트를 찾을 수 있을 겁니다.', `FemaleText_loc4`='你可以在水晶大厅靠近圣泉的地方找到钓鱼训练师伊雷特。', `FemaleText_loc5`='你可以在靠近聖光之水的水晶大廳找到釣魚訓練師伊瑞德 。', `FemaleText_loc7`='Encontrarás a Erett el instructor de pesca en la Sala de Cristal, cerca de las aguas bendecidas por la Luz.' WHERE `ID`=15826;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탁자 위의 책과 두루마리 더미를 뒤지던 %s|1이;가; 한 가지에 흥미를 갖고 조사하기 시작합니다.', `MaleText_loc4`='在翻遍桌上的卷轴和书籍以后，%s开始对其中的一本表现出了特别的兴趣。', `MaleText_loc5`='翻著成堆的書籍和桌上的卷軸，%s很感興趣的開始檢視某樣東西。', `MaleText_loc7`='Tras echar un vistazo rápido a los libros y los pergaminos que hay encima de la mesa, %s examina uno con especial interés.' WHERE `ID`=15827;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='교역 지구 입구 근처에 길드 사무관인 푸남이 있을 겁니다.', `MaleText_loc4`='公会注册员就在贸易阶梯的入口附近。', `MaleText_loc5`='你可以在貿易區入口找到范安姆，他是一位公會註冊員。', `MaleText_loc7`='Funaam, el maestro de la hermandad, está cerca de la entrada de la Grada de los Mercaderes.', `FemaleText_loc1`='교역 지구 입구 근처에 길드 사무관인 푸남이 있을 겁니다.', `FemaleText_loc4`='公会注册员就在贸易阶梯的入口附近。', `FemaleText_loc5`='你可以在貿易區入口找到范安姆，他是一位公會註冊員。', `FemaleText_loc7`='Funaam, el maestro de la hermandad, está cerca de la entrada de la Grada de los Mercaderes.' WHERE `ID`=15828;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐라고? 이게 뭔가?!', `MaleText_loc4`='什么？这是什么？！', `MaleText_loc5`='什麼?這是什麼?!', `MaleText_loc7`='¿Qué? ¡¿Qué es esto?!' WHERE `ID`=15829;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 도저히 상상도 할 수 없는 일이야!', `MaleText_loc4`='简直是遥不可及！', `MaleText_loc5`='這簡直無法想像!', `MaleText_loc7`='¡Es inimaginable!' WHERE `ID`=15830;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무래도 내가 술 마시는 날을 잘못 택한 것 같군.', `MaleText_loc4`='看来今天不宜戒酒。', `MaleText_loc5`='看來我挑錯日子戒酒了。', `MaleText_loc7`='Me parece que he elegido un mal día para dejar de beber.' WHERE `ID`=15831;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 이걸 놓칠 수가 있나?!', `MaleText_loc4`='怎么可能错过这个？！', `MaleText_loc5`='這怎麼會失敗呢?!', `MaleText_loc7`='¡¿Cómo se ha podido perder algo así?!' WHERE `ID`=15832;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대장님, 사소한 문제가 생겼습니다.', `MaleText_loc4`='长官，我们有个小问题。', `MaleText_loc5`='上尉大人，我們有個小問題。', `MaleText_loc7`='Capitán, hay un problemilla.' WHERE `ID`=15833;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정하고 어서 계속해보게.', `MaleText_loc4`='稍息，中尉。继续。', `MaleText_loc5`='稍息，中尉，繼續吧。', `MaleText_loc7`='Adelante, teniente, dime.' WHERE `ID`=15834;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번에는 뭔가, 그래블?', `MaleText_loc4`='现在怎么样了，加维？', `MaleText_loc5`='現在怎麼樣了，葛拉伏?', `MaleText_loc7`='¿Qué ocurre, Gravel?' WHERE `ID`=15835;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 뭐가 잘못될 수가 있다는 건가?', `MaleText_loc4`='还有什么可能出错？', `MaleText_loc5`='究竟是什麼地方弄錯呢?', `MaleText_loc7`='¿Qué más puede salir mal?' WHERE `ID`=15836;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말해 보게, 부관. 무슨 문제가 있나?', `MaleText_loc4`='什么事，中尉？报告吧。', `MaleText_loc5`='什麼事，中尉!說吧。', `MaleText_loc7`='¿Sí, teniente? Informa.' WHERE `ID`=15837;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠습니다, 대장님! 누군가가 저에게 세나리온 수풀의 드루이드들이 몰살당했다고 전하려고 했던 것 같습니다!', `MaleText_loc4`='就像你说的那样，长官。看来有人没能及时通知我，塞纳里奥树林的德鲁伊们全都被消灭了！', `MaleText_loc5`='如同你所說的，長官。那個逃跑的人告訴我在塞納里奧灌木林的德魯伊已經死了!', `MaleText_loc7`='Como quieras, señor. Parece que alguien olvidó decirme que los druidas del Matorral Cenarion han sido eliminados.' WHERE `ID`=15838;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 다시 공격당했다는 나쁜 소식입니다. 적들은 물러갔지만 전방 감시탑에 불이 났습니다.', `MaleText_loc4`='坏消息。我们又遭到了袭击。他们跑了，但是前面的哨塔着火了。', `MaleText_loc5`='壞消息，我們又被攻擊了。他們雖然離開了，但是前線哨塔失火了。', `MaleText_loc7`='Malas noticias. Nos han dado de nuevo. No están, pero la torre vigía del frente está en llamas.' WHERE `ID`=15839;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 상인들 중에 한 명이 실종되었습니다!', `MaleText_loc4`='我们的一个商人失踪了！', `MaleText_loc5`='我們其中的一位商人不見了!', `MaleText_loc7`='¡Falta uno de nuestros mercaderes!' WHERE `ID`=15840;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛의 전당 뒤쪽 성벽에서 우리의 약초채집가인 켐모르한을 찾을 수 있을 겁니다.', `MaleText_loc4`='草药学训练师塞摩尔汉就在圣光穹顶的后墙对面。', `MaleText_loc5`='你可以在那魯之座的後牆對面，找到我們的草藥師希莫爾汗。', `MaleText_loc7`='Nuestro herborista, Cemmorhan, está cerca del muro trasero de El Arca de las Luces.', `FemaleText_loc1`='빛의 전당 뒤쪽 성벽에서 우리의 약초채집가인 켐모르한을 찾을 수 있을 겁니다.', `FemaleText_loc4`='草药学训练师塞摩尔汉就在圣光穹顶的后墙对面。', `FemaleText_loc5`='你可以在那魯之座的後牆對面，找到我們的草藥師希莫爾汗。', `FemaleText_loc7`='Nuestro herborista, Cemmorhan, está cerca del muro trasero de El Arca de las Luces.' WHERE `ID`=15841;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명예의 요새에서 최근에 도착한 자들 말인데요, 그들은 용병들입니다! 녀석들이 문제를 일으키고 있습니다. 제가 녀석들을 좀 상대해야 하지 않을까요?', `MaleText_loc4`='最近从荣耀堡来的那些人——他们是雇佣兵！他们正在挑起是非，也许我应该和他们谈谈？', `MaleText_loc5`='那些最近從榮譽堡抵達的隊伍-他們是傭兵!他們開始引起一些麻煩，或許我該和他們談談?', `MaleText_loc7`='¡Los que llegaron hace poco del Bastión del Honor son mercenarios! Están empezando a causar problemas. ¿Crees que debería hablar con ellos?' WHERE `ID`=15842;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 정찰병이 보고하기를 어느 어둠의 집단이 그란골바르 마을의 폐허로 들어왔다고 합니다. 앗, 이 보고는 일주일 이상 지난 것이로군요.', `MaleText_loc4`='我们的一个斥候报告说，有一支秘密组织已经进入了格兰戈瓦村的废墟。糟糕，这报告是一周前的。', `MaleText_loc5`='我們其中一位的斥候報告暗影軍團已經行軍至葛蘭戈瓦村的廢墟裡，糟了!這是一個禮拜之前的報告。', `MaleText_loc7`='Uno de nuestros exploradores informa de que un grupo misterioso se ha desplazado hasta las ruinas del Poblado Grangol''var. Vaya... Este informe tiene más de una semana.' WHERE `ID`=15843;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세나리온 드루이드가 불꽃날개 거점을 점령했다는 소식을 외부에 있는 우리 정찰병이 전해왔습니다.', `MaleText_loc4`='我们得到情报说，有个塞纳里奥的德鲁伊在火翼岗哨被俘虏了。', `MaleText_loc5`='我們從逃跑的斥候那裡拿到報告，報告上指出塞納里奧其中有一個德魯伊被囚禁在火翼崗哨。', `MaleText_loc7`='Tenemos informes de un explorador de campo según los cuales un druida de Cenarion ha sido hecho cautivos en el Alto Ala de Fuego.' WHERE `ID`=15844;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사냥꾼을 찾는다고요? 교역 지구 2층의 사냥꾼의 성소에서 그들을 찾을 수 있을 겁니다.', `MaleText_loc4`='你在寻找猎人？他们就在贸易阶梯第二层的猎手圣殿中。', `MaleText_loc5`='你要找獵人?你可以在貿易區第二層的獵人聖所那邊找到他們。', `MaleText_loc7`='¿Buscas cazadores? Los encontrarás en el segundo nivel de la Grada de los Mercaderes, en el Sagrario de los cazadores.', `FemaleText_loc1`='사냥꾼을 찾는다고요? 교역 지구 2층의 사냥꾼의 성소에서 그들을 찾을 수 있을 겁니다.', `FemaleText_loc4`='你在寻找猎人？他们就在贸易阶梯第二层的猎手圣殿中。', `FemaleText_loc5`='你要找獵人?你可以在貿易區第二層的獵人聖所那邊找到他們。', `FemaleText_loc7`='¿Buscas cazadores? Los encontrarás en el segundo nivel de la Grada de los Mercaderes, en el Sagrario de los cazadores.' WHERE `ID`=15845;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='간병소는 엑소다르의 주 출입구 근처, 중앙 빛의 전당 위에 있습니다.', `MaleText_loc4`='我们的医护中心位于圣光穹顶中心的上方，靠近埃索达的主入口。', `MaleText_loc5`='我們的照顧者中心位於聖光地窖中心的上方，靠近艾克索達主要入口的地方。', `MaleText_loc7`='Nuestro Centro de Cuidadores está encima del Arca de las Luces central, cerca de la entrada principal a El Exodar.', `FemaleText_loc1`='간병소는 엑소다르의 주 출입구 근처, 중앙 빛의 전당 위에 있습니다.', `FemaleText_loc4`='我们的医护中心位于圣光穹顶中心的上方，靠近埃索达的主入口。', `FemaleText_loc5`='我們的照顧者中心位於聖光地窖中心的上方，靠近艾克索達主要入口的地方。', `FemaleText_loc7`='Nuestro Centro de Cuidadores está encima del Arca de las Luces central, cerca de la entrada principal a El Exodar.' WHERE `ID`=15846;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 가르쳐드릴 기술을 익힐 수 있을 만큼 충분히 기술을 연마했습니까?', `MaleText_loc4`='你的技巧已经达到学习新东西的标准了吗？', `MaleText_loc5`='你有把我教授給你的技巧好好地磨練一番嗎?', `MaleText_loc7`='¿Tienes el nivel suficiente para aprender lo que te puedo enseñar?', `FemaleText_loc1`='제가 가르쳐드릴 기술을 익힐 수 있을 만큼 충분히 기술을 연마했나요?', `FemaleText_loc4`='你的技巧已经达到学习新东西的标准了吗？', `FemaleText_loc5`='你有把我教授給你的技巧好好地磨練一番嗎?', `FemaleText_loc7`='¿Tienes el nivel suficiente para aprender lo que te puedo enseñar?' WHERE `ID`=15847;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파리는 보석세공에 관심이 있는 자들에게 보석세공의 정교함을 알려준답니다. 저기 동굴 근처의 수정 전당에 가면 그를 만날 수 있을 겁니다.', `MaleText_loc4`='法里在训练那些对珠宝加工感兴趣的人。你可以在水晶大厅靠近巨洞的方位找到她。', `MaleText_loc5`='法芮訓練那些對珠寶工藝有興趣的人。你可以在靠近洞穴的水晶大廳那裡找到他。', `MaleText_loc7`='Farii adiestra a los que quieren aprender joyería. Está en la Sala de Cristal, cerca de esa caverna.', `FemaleText_loc1`='파리는 보석세공에 관심이 있는 자들에게 보석세공의 정교함을 알려준답니다. 저기 동굴 근처의 수정 전당에 가면 그를 만날 수 있을 겁니다.', `FemaleText_loc4`='法里在训练那些对珠宝加工感兴趣的人。你可以在水晶大厅靠近巨洞的方位找到她。', `FemaleText_loc5`='法芮訓練那些對珠寶工藝有興趣的人。你可以在靠近洞穴的水晶大廳那裡找到他。', `FemaleText_loc7`='Farii adiestra a los que quieren aprender joyería. Está en la Sala de Cristal, cerca de esa caverna.' WHERE `ID`=15848;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그것 참 걱정스러운 소식이군. 부관, 당장 가서 이 문제를 처리하도록!', `MaleText_loc4`='真是个麻烦的消息。看看是不是能够立刻解决！', `MaleText_loc5`='這實在是個麻煩的消息，立刻調查這件事!', `MaleText_loc7`='Esas noticias son preocupantes, sí. ¡Ocúpate de esto se solucione lo antes posible!' WHERE `ID`=15849;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이러고 있을 시간이 없네, 부관. 어서 가서 이번 일에 손을 써 보도록 하게.', `MaleText_loc4`='我没有时间，中尉。你去把它搞定。', `MaleText_loc5`='中尉，我沒有時間處理這件事，請確保你可以掌控大局。', `MaleText_loc7`='No tengo tiempo para esto, teniente. Hazlo tú mismo.' WHERE `ID`=15850;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 어떤 식으로든 그 문제에 도움이 되려면 사람들이 더 필요할 것이네. 그 일을 도와줄 정찰병들을 불러들이도록 하게나.', `MaleText_loc4`='如果我们要去帮忙的话，就必须有更多的人手。叫一些斥候过来一起帮忙吧。', `MaleText_loc5`='如果我們需要幫助的話，我們會需要更多的人手，請求更多的斥候來幫忙吧。', `MaleText_loc7`='Vamos a necesitar a más gente si queremos ocuparnos de esto. Llama a algunos de los exploradores para que colaboren.' WHERE `ID`=15851;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래블해머 부관, 그 문제를 가장 중요한 사안으로 처리하도록 하게. 누구든 도움이 될만한 자들에게 알리도록.', `MaleText_loc4`='中尉，我希望你能把这个设置为最高优先级。通告任何你觉得可以施以援手的人。', `MaleText_loc5`='中尉，我要你做好優先工作。通知任何你覺得需要幫助的人。', `MaleText_loc7`='Teniente, quiero que esta sea tu prioridad número uno. Avisa a todos los que creas que pueden ayudar.' WHERE `ID`=15852;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예, 예, 대장님. 즉시 시행하겠습니다!', `MaleText_loc4`='遵命，长官。马上去办！', `MaleText_loc5`='是的...是的，長官，馬上去!', `MaleText_loc7`='¡Sí, señor! ¡Ahora mismo!' WHERE `ID`=15853;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='교역 지구에서 엑소다르의 가죽세공사를 찾을 수 있을 겁니다. 성스러운 빛이 당신을 인도하길.', `MaleText_loc4`='埃索达的制皮训练师在贸易阶梯。愿圣光保佑你。', `MaleText_loc5`='你可以在貿易區找到艾克索達的製皮師，願聖光保佑你。', `MaleText_loc7`='Los peleteros de El Exodar están en la Grada de los Mercaderes. Que la Luz te bendiga.', `FemaleText_loc1`='교역 지구에서 엑소다르의 가죽세공사를 찾을 수 있을 겁니다. 성스러운 빛이 당신을 인도하길.', `FemaleText_loc4`='埃索达的制皮训练师在贸易阶梯。愿圣光保佑你。', `FemaleText_loc5`='你可以在貿易區找到艾克索達的製皮師，願聖光保佑你。', `FemaleText_loc7`='Los peleteros de El Exodar están en la Grada de los Mercaderes. Que la Luz te bendiga.' WHERE `ID`=15854;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛의 전당에서 우리 마법사들을 찾을 수 있습니다. 성스러운 빛이 함께하시길...', `MaleText_loc4`='法师训练师就在圣光穹顶。愿圣光与你同在。', `MaleText_loc5`='你可以在聖光地窖找到我們的法師，願聖光與你同行。', `MaleText_loc7`='Nuestros magos están en el Arca de las Luces. Ve con la Luz.', `FemaleText_loc1`='빛의 전당에서 우리 마법사들을 찾을 수 있습니다. 성스러운 빛이 함께하시길...', `FemaleText_loc4`='法师训练师就在圣光穹顶。愿圣光与你同在。', `FemaleText_loc5`='你可以在聖光地窖找到我們的法師，願聖光與你同行。', `FemaleText_loc7`='Nuestros magos están en el Arca de las Luces. Ve con la Luz.' WHERE `ID`=15855;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나루의 축복이 있기를. 무엇을 찾으십니까?', `MaleText_loc4`='纳鲁的祝福。我能帮你什么忙吗？', `MaleText_loc5`='願聖光保佑那魯，你要我幫你找什麼嗎?', `MaleText_loc7`='Recibe la bendición de los naaru. ¿En qué puedo ayudarte?', `FemaleText_loc1`='나루의 축복이 있기를. 무엇을 찾으시나요?', `FemaleText_loc4`='纳鲁的祝福。我能帮你什么忙吗？', `FemaleText_loc5`='願聖光保佑那魯，你要我幫你找什麼嗎?', `FemaleText_loc7`='Recibe la bendición de los naaru. ¿En qué puedo ayudarte?' WHERE `ID`=15856;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='교역 지구 뒤쪽으로 가면 우리 전문 광부들을 찾을 수 있습니다.', `MaleText_loc4`='采矿训练师就在贸易阶梯后面。', `MaleText_loc5`='你可以在快到貿易區的後方找到採礦訓練師。', `MaleText_loc7`='Encontrarás a nuestros instructores de minería en la parte trasera de la Grada de los Mercaderes.', `FemaleText_loc1`='교역 지구 뒤쪽으로 가면 우리 전문 광부들을 찾을 수 있습니다.', `FemaleText_loc4`='采矿训练师就在贸易阶梯后面。', `FemaleText_loc5`='你可以在快到貿易區的後方找到採礦訓練師。', `FemaleText_loc7`='Encontrarás a nuestros instructores de minería en la parte trasera de la Grada de los Mercaderes.' WHERE `ID`=15857;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엑소다르의 상급 성기사들은 나루의 보좌에 있는 빛나는 빛의 예배당에 있으니 그리로 가보시기 바랍니다.', `MaleText_loc4`='你可以在纳鲁之座内的圣光礼拜堂找到埃索达的圣骑士训练师。', `MaleText_loc5`='可以在那魯之座的聖光教堂那裡找到艾克索達的聖騎士訓練師。', `MaleText_loc7`='Los instructores de paladines de El Exodar están en la luminosa Capilla de la Luz, en el Trono de los Naaru.', `FemaleText_loc1`='엑소다르의 상급 성기사들은 나루의 보좌에 있는 빛나는 빛의 예배당에 있으니 그리로 가보시기 바랍니다.', `FemaleText_loc4`='你可以在纳鲁之座内的圣光礼拜堂找到埃索达的圣骑士训练师。', `FemaleText_loc5`='可以在那魯之座的聖光教堂那裡找到艾克索達的聖騎士訓練師。', `FemaleText_loc7`='Los instructores de paladines de El Exodar están en la luminosa Capilla de la Luz, en el Trono de los Naaru.' WHERE `ID`=15858;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 상급 사제들은 빛의 전당에서 나루의 보좌로 나가는 길목에 있는 빛의 의회 회의실 안에 있습니다. 성스러운 빛이 함께하기를.', `MaleText_loc4`='我们的牧师训练师就在靠近纳鲁之座入口的圣光教团房间里。愿圣光伴随你。', `MaleText_loc5`='你可以在聖光會議廳找到我們的牧師訓練師，就在那魯之座的入口，願聖光保佑你。', `MaleText_loc7`='Nuestro instructor de sacerdotes está en la sala de la Orden de la Luz, a la entrada del Trono de los Naaru. Que la luz te acompañe.', `FemaleText_loc1`='우리 상급 사제들은 빛의 전당에서 나루의 보좌로 나가는 길목에 있는 빛의 의회 회의실 안에 있습니다. 성스러운 빛이 함께하기를.', `FemaleText_loc4`='我们的牧师训练师就在靠近纳鲁之座入口的圣光教团房间里。愿圣光伴随你。', `FemaleText_loc5`='你可以在聖光會議廳找到我們的牧師訓練師，就在那魯之座的入口，願聖光保佑你。', `FemaleText_loc7`='Nuestro instructor de sacerdotes está en la sala de la Orden de la Luz, a la entrada del Trono de los Naaru. Que la luz te acompañe.' WHERE `ID`=15859;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 기술 전문가를 찾으십니까?', `MaleText_loc4`='你要找哪位专业技能训练师？', `MaleText_loc5`='你想找哪種專業技能訓練師?', `MaleText_loc7`='¿Qué tipo de instructor de profesión estás buscando?', `FemaleText_loc1`='어떤 기술 전문가를 찾으십니까?', `FemaleText_loc4`='你要找哪位专业技能训练师？', `FemaleText_loc5`='你想找哪種專業技能訓練師?', `FemaleText_loc7`='¿Qué tipo de instructor de profesión estás buscando?' WHERE `ID`=15860;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수정 전당에 가면 상급 주술사들이 많이 있을 겁니다. 그곳에서 선견자 노분도 님을 찾아가 뒤틀린 드레나이들에게 약간의 동정 어린 눈길을 보내 주십시오. 성스러운 빛이 함께하기를.', `MaleText_loc4`='水晶大厅中有数名萨满祭司训练师。或者你可以找预言者努波顿谈谈，对这位破碎者表示一下你的怜悯之情。愿圣光与你同在。', `MaleText_loc5`='你可以在水晶大廳找到薩滿訓練師。或許你該拜訪那裡的先知諾柏多，並且在破碎者面前表現一副可憐兮兮的樣子。願聖光保佑你。', `MaleText_loc7`='Hay varios instructores de chamanes en la Sala de Cristal. Puede que quieras ver al clarividente Nobundo. Muéstrate $gcompasivo:compasiva; con los Tábidos. Que la Luz te acompañe.', `FemaleText_loc1`='수정 전당에 가면 상급 주술사들이 많이 있을 겁니다. 그곳에서 선견자 노분도 님을 찾아가 뒤틀린 드레나이들에게 약간의 동정 어린 눈길을 보내 주십시오. 성스러운 빛이 함께하기를.', `FemaleText_loc4`='水晶大厅中有数名萨满祭司训练师。或者你可以找预言者努波顿谈谈，对这位破碎者表示一下你的怜悯之情。愿圣光与你同在。', `FemaleText_loc5`='你可以在水晶大廳找到薩滿訓練師。或許你該拜訪那裡的先知諾柏多，並且在破碎者面前表現一副可憐兮兮的樣子。願聖光保佑你。', `FemaleText_loc7`='Hay varios instructores de chamanes en la Sala de Cristal. Puede que quieras ver al clarividente Nobundo. Muéstrate $gcompasivo:compasiva; con los Tábidos. Que la Luz te acompañe.' WHERE `ID`=15861;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='교역 지구에 가면 가죽세공사들과 함께 엑소다르의 상급 무두장이들이 있을 겁니다. 성스러운 빛이 당신을 인도하길.', `MaleText_loc4`='埃索达的剥皮训练师跟制皮训练师都在贸易阶梯。愿圣光保佑你。', `MaleText_loc5`='你可以在貿易區那裡找到艾克索達剝皮訓練師和製皮師在一起。願聖光保佑你。', `MaleText_loc7`='Los instructores de desuello de El Exodar están en la Grada de los Mercaderes, junto a los peleteros. Que la Luz te bendiga.', `FemaleText_loc1`='교역 지구에 가면 가죽세공사들과 함께 엑소다르의 상급 무두장이들이 있을 겁니다. 성스러운 빛이 당신을 인도하길.', `FemaleText_loc4`='埃索达的剥皮训练师跟制皮训练师都在贸易阶梯。愿圣光保佑你。', `FemaleText_loc5`='你可以在貿易區那裡找到艾克索達剝皮訓練師和製皮師在一起。願聖光保佑你。', `FemaleText_loc7`='Los instructores de desuello de El Exodar están en la Grada de los Mercaderes, junto a los peleteros. Que la Luz te bendiga.' WHERE `ID`=15862;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='간병소 바깥에서 야수 관리인 아르세이드를 만날 수 있을 겁니다. 그는 엑소다르의 주 출입구 근처, 중심지의 위층에 있습니다.', `MaleText_loc4`='你可以在医护中心找到我们的兽栏管理员阿尔泰德，他就站在中间轮轴的上一层，靠近埃索达主出口那里。', `MaleText_loc5`='你可以在照顧者中心找到我們的獸欄管理員，阿斯艾德。他位於中心的較高處，靠近艾克索達主要入口的位置。', `MaleText_loc7`='Puedes encontrar a Arthaid, nuestro maestro de establos, fuera del Centro de Cuidadores. Se encuentra en la planta superior de la cabina central, cerca de la entrada principal a El Exodar.', `FemaleText_loc1`='간병소 바깥에서 야수 관리인 아르세이드를 만날 수 있을 겁니다. 그는 엑소다르의 주 출입구 근처, 중심지의 위층에 있습니다.', `FemaleText_loc4`='你可以在医护中心找到我们的兽栏管理员阿尔泰德，他就站在中间轮轴的上一层，靠近埃索达主出口那里。', `FemaleText_loc5`='你可以在照顧者中心找到我們的獸欄管理員，阿斯艾德。他位於中心的較高處，靠近艾克索達主要入口的位置。', `FemaleText_loc7`='Puedes encontrar a Arthaid, nuestro maestro de establos, fuera del Centro de Cuidadores. Se encuentra en la planta superior de la cabina central, cerca de la entrada principal a El Exodar.' WHERE `ID`=15863;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오래전에는 우리는 하나로 된 낙하복을 입었지요. 우리의 혁신적인 재봉사들 덕분에 더는 그렇게 비실용적인 의복을 입지 않아도 되게 되었답니다. 교역 지구에 가면 이 의복의 선구자들을 만날 수 있을 겁니다.', `MaleText_loc4`='以前，我们曾穿过连体衣。感谢灵感不断的裁缝们，我们终于可以脱下那些不实用的制服了。你可以在贸易阶梯找到这些引领时尚的设计师。', `MaleText_loc5`='多年前，我們穿著一件式的連身衣。我們很感謝我們裁縫師的創新，讓我們終於不用再穿著不合時宜的衣服了。你可以在貿易區那裡找到那些時尚專家。', `MaleText_loc7`='Hace mucho tiempo, llevábamos monos de una sola pieza. Gracias a nuestros modernos sastres, ya no tenemos que vestir algo tan poco práctico. Puedes encontrar a esos diseñadores de vanguardia en la Grada de los Mercaderes.', `FemaleText_loc1`='오래전에는 우리는 하나로 된 낙하복을 입었지요. 우리의 혁신적인 재봉사들 덕분에 더는 그렇게 비실용적인 의복을 입지 않아도 되게 되었답니다. 교역 지구에 가면 이 의복의 선구자들을 만날 수 있을 겁니다.', `FemaleText_loc4`='以前，我们曾穿过连体衣。感谢灵感不断的裁缝们，我们终于可以脱下那些不实用的制服了。你可以在贸易阶梯找到这些引领时尚的设计师。', `FemaleText_loc5`='多年前，我們穿著一件式的連身衣。我們很感謝我們裁縫師的創新，讓我們終於不用再穿著不合時宜的衣服了。你可以在貿易區那裡找到那些時尚專家。', `FemaleText_loc7`='Hace mucho tiempo, llevábamos monos de una sola pieza. Gracias a nuestros modernos sastres, ya no tenemos que vestir algo tan poco práctico. Puedes encontrar a esos diseñadores de vanguardia en la Grada de los Mercaderes.' WHERE `ID`=15864;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 전단의 정보에는 당신이 아직 당면한 임무를 수행할 자격이 되지 않는다는 것이 나타나 있습니다.$B$B다음에 다시 확인해 보는 것이 좋겠습니다.', `MaleText_loc4`='根据这块通缉令公告板上面的信息显示，你还没有达到现有任务的要求。$B$B你应该晚点再来看看。', `MaleText_loc5`='懸賞告示上的訊息指出你還未具有資該參加這項任務。$B$B不過，你之後還是應該再確認一遍。', `MaleText_loc7`='La información en este cartel de Se busca indica que todavía no eres capaz de llevar a cabo lo que pide.$B$BVuelve a intentarlo más tarde.' WHERE `ID`=15865;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='재미있는 내용의 공고입니다. 이 지역 나방의 씨를 말리라는 요청입니다. 황제테로나방이라는 이름의 나방이라고 합니다.', `MaleText_loc4`='有意思。这张通缉令要求消灭本地的蛾子，一些“华丽的巨蛾”之类的东西。', `MaleText_loc5`='真有趣，懸賞告示上寫著撲殺本地的飛蛾，而且還是皇家泰洛飛蛾。', `MaleText_loc7`='Interesante. El cartel de Se busca pide que se extermine la población local de polillas. Algo sobre teropolillas reales.' WHERE `ID`=15866;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위대한 전사가 되고 싶으십니까? 전쟁은 전사를 위대하게 만들어주지 않지요. 그래도 교역 지구의 나머지 부분이 내려다보이는 전사의 정원에 가면 위대한 상급 전사들을 만날 수 있을 겁니다.', `MaleText_loc4`='想成为一名伟大的战士吗？战争不会让你变得伟大。尽管如此，你可以在战士平台找到我们伟大的战士训练师，战士平台就在贸易阶梯的上方。', `MaleText_loc5`='想尋找成為偉大戰士的方法?戰鬥無法讓人偉大。不過你可以在戰士區找到我們偉大的戰士訓練師，往上看就可以看到貿易區的休息之地。', `MaleText_loc7`='¿Quieres ser un gran guerrero? La guerra no te hace grande. Aun así, encontrarás nuestros instructores de guerreros en el Bancal del Guerrero, por encima del resto de la Grada de los Mercaderes.', `FemaleText_loc1`='위대한 전사가 되고 싶으십니까? 전쟁은 전사를 위대하게 만들어주지 않지요. 그래도 교역 지구의 나머지 부분이 내려다보이는 전사의 정원에 가면 위대한 상급 전사들을 만날 수 있을 겁니다.', `FemaleText_loc4`='想成为一名伟大的战士吗？战争不会让你变得伟大。尽管如此，你可以在战士平台找到我们伟大的战士训练师，战士平台就在贸易阶梯的上方。', `FemaleText_loc5`='想尋找成為偉大戰士的方法?戰鬥無法讓人偉大。不過你可以在戰士區找到我們偉大的戰士訓練師，往上看就可以看到貿易區的休息之地。', `FemaleText_loc7`='¿Quieres ser un gran guerrero? La guerra no te hace grande. Aun así, encontrarás nuestros instructores de guerreros en el Bancal del Guerrero, por encima del resto de la Grada de los Mercaderes.' WHERE `ID`=15867;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왕궁 교역소 은행에 오신 것을 환영합니다. 손님, 무엇을 도와드릴까요?', `MaleText_loc4`='欢迎来到皇家贸易区，$g先生:女士;。有什么我可以帮你的吗？', `MaleText_loc5`='歡迎來到皇家交易所銀行，$g先生:女士;。您需要什麼服務呢?', `MaleText_loc7`='$gBienvenido:Bienvenida; a al Banco Real de Cambio. ¿Qué deseas?', `FemaleText_loc1`='왕궁 교역소 은행에 오신 것을 환영합니다. 손님, 무엇을 도와드릴까요?', `FemaleText_loc4`='欢迎来到皇家贸易区，$g先生:女士;。有什么我可以帮你的吗？', `FemaleText_loc5`='歡迎來到皇家交易所銀行，$g先生:女士;。您需要什麼服務呢?', `FemaleText_loc7`='$gBienvenido:Bienvenida; a al Banco Real de Cambio. ¿Qué deseas?' WHERE `ID`=15868;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실버문 은행을 선택해 주셔서 감사합니다. 오늘은 뭘 도와드릴까요?', `MaleText_loc4`='感谢你选择了银月城银行。今天我能为你做些什么？', `MaleText_loc5`='謝謝您選擇了銀月城銀行，今天我能為您做些什麼呢?', `MaleText_loc7`='Gracias por escoger el Banco de Lunargenta. ¿En qué puedo ayudarte?', `FemaleText_loc1`='실버문 은행을 선택해 주셔서 감사합니다. 오늘은 뭘 도와드릴까요?', `FemaleText_loc4`='感谢你选择了银月城银行。今天我能为你做些什么？', `FemaleText_loc5`='謝謝您選擇了銀月城銀行，今天我能為您做些什麼呢?', `FemaleText_loc7`='Gracias por escoger el Banco de Lunargenta. ¿En qué puedo ayudarte?' WHERE `ID`=15869;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무기 기술을 향상시키고 싶으신가요? 우리의 무기 전문가들은 교역 지구의 최상층인 전사의 정원에 있습니다.', `MaleText_loc4`='想要学习更多武器技能吗？武器大师就在贸易阶梯最高层的战士阶梯。', `MaleText_loc5`='你想要改善你的武器技能?我們的武器大師在戰士區中貿易區的最高一層。', `MaleText_loc7`='¿Quieres mejorar tu habilidad con las armas? El maestro de armas está en nivel más elevado de la Grada de los Mercaderes, en el Bancal del Guerrero.', `FemaleText_loc1`='무기 기술을 향상시키고 싶으신가요? 우리의 무기 전문가들은 교역 지구의 최상층인 전사의 정원에 있습니다.', `FemaleText_loc4`='想要学习更多武器技能吗？武器大师就在贸易阶梯最高层的战士阶梯。', `FemaleText_loc5`='你想要改善你的武器技能?我們的武器大師在戰士區中貿易區的最高一層。', `FemaleText_loc7`='¿Quieres mejorar tu habilidad con las armas? El maestro de armas está en nivel más elevado de la Grada de los Mercaderes, en el Bancal del Guerrero.' WHERE `ID`=15870;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오십시오, $t시민:시민;이여, 무슨 중요한 일이 있었기에 저를 찾아오신 겁니까?', `MaleText_loc4`='你好，公民。你有什么重要的消息想让我知道吗？', `MaleText_loc5`='是的，$t居民:居民;，你有什麼重要的事非要引起我的注意?', `MaleText_loc7`='Sí, $tciudadano:ciudadana;, ¿qué asunto importante puede precisar mi atención?' WHERE `ID`=15871;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요? 저희 왕궁 교역소 은행에서 오늘은 무엇을 도와드리면 될까요?', `MaleText_loc4`='你好，今天有什么可以帮你的吗？', `MaleText_loc5`='您好。我們皇家外匯銀行今天能提供你協助嗎?', `MaleText_loc7`='Saludos. ¿En qué puede ayudarte el Banco del Intercambio Real?', `FemaleText_loc1`='안녕하세요? 저희 왕궁 교역소 은행에서 오늘은 무엇을 도와드리면 될까요?', `FemaleText_loc4`='你好，今天有什么可以帮你的吗？', `FemaleText_loc5`='您好。我們皇家外匯銀行今天能提供你協助嗎?', `FemaleText_loc7`='Saludos. ¿En qué puede ayudarte el Banco del Intercambio Real?' WHERE `ID`=15872;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실버문 은행에 오신 것을 환영합니다. 손님, 보관함을 보고 싶으세요?', `MaleText_loc4`='欢迎来到银月城银行，$g先生:女士;。你想使用存储服务吗？', `MaleText_loc5`='歡迎來到銀月城銀行，$g先生:女士;。你想要進入保管箱嗎?', `MaleText_loc7`='$gBienvenido:Bienvenida; al Banco de Lunargenta. ¿Quieres acceder a tu cuenta?', `FemaleText_loc1`='실버문 은행에 오신 것을 환영합니다. 손님, 보관함을 보고 싶으세요?', `FemaleText_loc4`='欢迎来到银月城银行，$g先生:女士;。你想使用存储服务吗？', `FemaleText_loc5`='歡迎來到銀月城銀行，$g先生:女士;。你想要進入保管箱嗎?', `FemaleText_loc7`='$gBienvenido:Bienvenida; al Banco de Lunargenta. ¿Quieres acceder a tu cuenta?' WHERE `ID`=15873;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엑소다르의 금고실은 넓고 안전하답니다. 이곳에 손님의 물건을 맡기시면 걱정이 없으실 것입니다.', `MaleText_loc4`='埃索达的地下储藏室规模庞大，守卫森严。你的物品放在这里一定很安全。', `MaleText_loc5`='艾克索達的地窖非常的寬大且保護完善，在這裡你的東西不會受到任何損傷。', `MaleText_loc7`='Las cámaras de El Exodar son grandes y están bien protegidas. Tus bienes está a salvo en ellas.', `FemaleText_loc1`='엑소다르의 금고실은 넓고 안전하답니다. 이곳에 손님의 물건을 맡기시면 걱정이 없으실 것입니다.', `FemaleText_loc4`='埃索达的地下储藏室规模庞大，守卫森严。你的物品放在这里一定很安全。', `FemaleText_loc5`='艾克索達的地窖非常的寬大且保護完善，在這裡你的東西不會受到任何損傷。', `FemaleText_loc7`='Las cámaras de El Exodar son grandes y están bien protegidas. Tus bienes está a salvo en ellas.' WHERE `ID`=15874;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 엑소다르의 개인 보관소의 접근 관리를 맡고 있습니다. 물건을 맡기러 오셨습니까 아니면 찾으러 오셨습니까?', `MaleText_loc4`='我们控制着埃索达的储存设施。你有什么东西需要存取吗？', `MaleText_loc5`='我們掌控了艾克索達保管箱的通道，有沒有你想要保存或拿走的物品呢?', `MaleText_loc7`='Controlamos el acceso a las instalaciones de almacenamiento de El Exodar. ¿Quieres sacar o meter algo?', `FemaleText_loc1`='우리는 엑소다르의 개인 보관소의 접근 관리를 맡고 있습니다. 물건을 맡기러 오셨습니까 아니면 찾으러 오셨습니까?', `FemaleText_loc4`='我们控制着埃索达的储存设施。你有什么东西需要存取吗？', `FemaleText_loc5`='我們掌控了艾克索達保管箱的通道，有沒有你想要保存或拿走的物品呢?', `FemaleText_loc7`='Controlamos el acceso a las instalaciones de almacenamiento de El Exodar. ¿Quieres sacar o meter algo?' WHERE `ID`=15875;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기요! 제가 여기서 나가도록 도와주실 수 있으세요?', `FemaleText_loc4`='嘿！你觉得你能帮我离开这吗？', `FemaleText_loc5`='嗨!你認為你能夠幫助我離開這裡嗎?', `FemaleText_loc7`='Hola. ¿Puedes ayudarme a salir de aquí?' WHERE `ID`=15876;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그래요! 그대는 호드고, 전 얼라이언스 편이죠. 하지만, 이번 한 번만 그 점을 제쳐두면 안 될까요? 여기서 나갈 수 있도록 간절히 도움을 청합니다.', `FemaleText_loc4`='嘿！我知道你是部落的人，而我是联盟这一边的，但你觉得这次我们是否可以把这些抛到脑后呢？我真的需要有人帮我离开这里。', `FemaleText_loc5`='嗨!我知道你是部落的人，而我卻是聯盟的人，但是這一次你不覺得我們應該不計前嫌嗎?我真的需要協助離開這裡。', `FemaleText_loc7`='¡Hola! Sé que estás con la Horda y que yo soy de la Alianza, pero ¿no crees que podríamos olvidar eso por un momento? Me gustaría que alguien me ayudase a salir de aquí.' WHERE `ID`=15877;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기요! 저 좀 도와주세요.', `FemaleText_loc4`='嘿？帮个忙行不行？', `FemaleText_loc5`='哈囉?救命啊?', `FemaleText_loc7`='¿Hola? ¿Alguien me ayuda?' WHERE `ID`=15878;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='<콜록>... <콜록>... 여기 곤경에 빠진 여자가 있어요!', `FemaleText_loc4`='<咳嗽><咳嗽>这里有个痛苦的年轻姑娘！', `FemaleText_loc5`='<咳嗽> <咳嗽> 窮困的少女在這裡!', `FemaleText_loc7`='Ejem, ejem... ¡Hay una doncella en peligro aquí!' WHERE `ID`=15879;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='괜찮으시다면 저를 여기서 구해주실 수 있으신가요?', `FemaleText_loc4`='要是有机会的话，你觉得你能让我离开这里吗？', `FemaleText_loc5`='當你得到機會的時候，你想你能讓我離開這裡嗎?', `FemaleText_loc7`='Si tienes un momento, ¿crees que podrías sacarme de aquí?' WHERE `ID`=15880;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저를 여기 두고 가지 마세요! 절 두고 가시면 나중에 찾아갈 거예요...', `FemaleText_loc4`='不要把我留在这里！要是你这么绝情，我做鬼也不会放过你……', `FemaleText_loc5`='別想從這裡離開我!無論你怎麼逃，我都會找到你的...', `FemaleText_loc7`='¡No me dejes aquí! Si me dejas, te encontraré...' WHERE `ID`=15881;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋아요, 어서 여기서 나가요!', `FemaleText_loc4`='好吧，让我们离开这里。', `FemaleText_loc5`='好了，我們快離開這裡吧!', `FemaleText_loc7`='¡Está bien! ¡Salgamos de aquí!' WHERE `ID`=15882;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='준비되셨나요? 잠시 시간을 드리지요.', `FemaleText_loc4`='你确信你准备好了？再等一会儿。', `FemaleText_loc5`='你確定你準備好了?還是等一下吧。', `FemaleText_loc7`='¿Seguro que estás $glisto:lista;? Piénsatelo bien.' WHERE `ID`=15883;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋아요, 어서가죠!', `FemaleText_loc4`='好吧，我们出发吧！', `FemaleText_loc5`='好吧，我們就這麼做吧!', `FemaleText_loc7`='¡Vamos allá!' WHERE `ID`=15884;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오, 이런, 나쁜 엘프들!', `FemaleText_loc4`='啊呀，坏精灵！', `FemaleText_loc5`='嗚喔!壞精靈!', `FemaleText_loc7`='Oh, no. Elfos malos.' WHERE `ID`=15885;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 자들은 도통 포기라는 걸 모르는군요!', `FemaleText_loc4`='这些家伙都是一根筋吗？', `FemaleText_loc5`='難到那些傢伙不會放棄嗎?', `FemaleText_loc7`='¿Estos tíos nunca se rinden?' WHERE `ID`=15886;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋아요, 여기부터는 혼자 갈 수 있을 것 같군요. 저를 그 무서운 곳에서 빼내줘서 정말 고마워요!', `FemaleText_loc4`='好吧，我想我可以自己逃出这里了。很感谢你的帮助！', `FemaleText_loc5`='好吧，我可以自己想辦法從這裡離開。真的很謝謝你幫我把從那裡放出來!', `FemaleText_loc7`='Vale, creo que ya me las puedo arreglar yo sola. Gracias por sacarme de aquí.' WHERE `ID`=15887;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하이 엘프 첩자가 달아나고 있다. 잡아라!', `MaleText_loc4`='高等精灵间谍逃跑了。抓住她！', `MaleText_loc5`='那個高等精靈間諜逃跑了!抓住她!', `MaleText_loc7`='¡La espía elfa noble se escapa! ¡Atrapadla!', `FemaleText_loc1`='하이 엘프 첩자가 달아나고 있다. 잡아라!', `FemaleText_loc4`='高等精灵间谍逃跑了。抓住她！', `FemaleText_loc5`='那個高等精靈間諜逃跑了!抓住她!', `FemaleText_loc7`='¡La espía elfo noble se escapa! ¡Atrapadla!' WHERE `ID`=15888;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기에 현상금과 일자리에 대한 공고가 붙어 있습니다.', `MaleText_loc4`='这里发布着各类悬赏和工作机会的布告。', `MaleText_loc5`='獎金公告和工作職缺都刊登在這裡。', `MaleText_loc7`='Aquí hay anuncios de recompensas y trabajos.' WHERE `ID`=15889;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='첩자가 탈출하게 해서는 안 된다!', `MaleText_loc4`='不要让间谍逃跑！', `MaleText_loc5`='不要讓間諜逃走了!', `MaleText_loc7`='¡No dejéis que escape el espía!', `FemaleText_loc1`='첩자가 탈출하게 해서는 안 된다!', `FemaleText_loc4`='不要让间谍逃跑！', `FemaleText_loc5`='不要讓間諜逃走了!', `FemaleText_loc7`='¡No dejéis que escape el espía!' WHERE `ID`=15890;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 무슨 일이지? 경비병!', `MaleText_loc4`='这是什么意思？卫兵！', `MaleText_loc5`='這是什麼意思?守衛!', `MaleText_loc7`='¿Qué significa esto? ¡Guardas!' WHERE `ID`=15891;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 친구에겐 이 정도면 충분할 것이오.', `MaleText_loc4`='这可真够他受的。', `MaleText_loc5`='失去他就已經夠了。', `MaleText_loc7`='Eso es suficiente para él.' WHERE `ID`=15892;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새로운 계획에 따라야 한다면 무기와 갑옷을 갖추는 게 좋겠소이다.', `MaleText_loc4`='在我们出发之前，我最好装备一些武器和护甲。', `MaleText_loc5`='只要我們執行新的計畫，我也會拿起武器穿起護甲。', `MaleText_loc7`='Mientras sigamos con el nuevo plan, puede que sea mejor que coja un arma y alguna armadura.' WHERE `ID`=15893;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갑시다.', `MaleText_loc4`='走吧。', `MaleText_loc5`='我們走吧!', `MaleText_loc7`='Vamos.' WHERE `ID`=15894;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자여, 그대는 망각의 절벽 위에 위태롭게 매달려 있구나! 불타는 군단이 도래함과 동시에 너의 종말도 올 것이다.', `MaleText_loc4`='入侵者，你们在遗忘的深渊边缘摇摆！燃烧军团就是你们的末日！', `MaleText_loc5`='入侵者，你現在岌岌可危了!等燃燒軍團到來你也就跟著完蛋了。', `MaleText_loc7`='¡Invasores, estan al borde de la extinción! ¡La Legión Ardiente llega, y, con ella, su fin!' WHERE `ID`=15895;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자가 죄수를 데리고 달아난다! 놈들을 처치하라!!!', `MaleText_loc4`='入侵者和囚犯在一起！杀死他们！！', `MaleText_loc5`='侵入者和囚犯在一起!殺了他們!', `MaleText_loc7`='¡Intrusosss con el prisionero! ¡Mátalos!' WHERE `ID`=15896;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐라고요? 그대가 벌써 놈을 처치했군요!$B$B쿠아그미란을 연구하고, 가능하면 놈과 맞붙을 생각이었는데... 하지만, 이제 그 시체를 연구할 수 있게 됐어요.$B$B<한숨>$B$B제발 이 우리에서 꺼내주세요. 놈의 시체를 조사한 다음 여기서 나가야겠습니다.', `MaleText_loc4`='什么？你已经把他给杀了！$B$B我以前一直希望能研究夸格米拉，或许还能和他互动一下。但是现在我所能做的就只有研究他的尸体。$B$B<叹气>$B$B请让我离开这只笼子。我会看他一眼，然后自己离开这里。', `MaleText_loc5`='什麼?你已經殺了他!$B$B我本來想好好研究奎克米瑞，甚至和他有所互動。但是現在我能研究的就只有他的屍體了。$b$b<唉>$B$B放我離開這個監牢吧，等我看過他之後我會自己離開這裡的。', `MaleText_loc7`='¿Qué? ¡Ya lo has matado!$B$BYo que quería estudiar a Quagmirran e incluso comunicarme con él... Ahora todo lo que podré estudiar será su cadáver.$B$B<Suspiro.>$B$BPor favor, sácame de esta jaula. Echaré un vistazo a lo que queda de él y me iré de este lugar.' WHERE `ID`=15897;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 전단에 있는 심술궂은 오크의 소름끼치는 면상이 눈을 부릅뜨고 있습니다. 이자의 의복으로 보아 흑마법사인 것이 분명합니다.', `MaleText_loc4`='那个猥琐的兽人从海报里凝视着你。他的服饰看上去很明显是一个术士。', `MaleText_loc5`='輕瞥這張海報，獸人那陰森可怕的表情正回瞪著你，他的穿著很明顯是位術士。', `MaleText_loc7`='El espantoso rostro de un orco malicioso te devuelve la mirada desde este cartel. Su ropa es, obviamente, de la índole de la de los brujos.' WHERE `ID`=15898;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일이오?', `MaleText_loc4`='嗯？什么？', `MaleText_loc5`='什麼?那是什麼?', `MaleText_loc7`='¿Sí? ¿Qué quieres?' WHERE `ID`=15899;
