UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드르렁... 전부 다 거짓말... 우린 다 끝장이야... 쩝쩝...', `MaleText_loc4`='呼噜噜……都是谎言……这是我们注定的命运……呼噜噜……', `MaleText_loc5`='Zzz...我們...命中注定， 失敗...zzz...', `MaleText_loc7`='Zzz... Todo mentiras... Zzz... Estamos condenados... Zzz... Todos...', `FemaleText_loc1`='드르렁... 전부 다 거짓말... 우린 다 끝장이야... 쩝쩝...', `FemaleText_loc4`='呼噜噜……都是谎言……这是我们注定的命运……呼噜噜……', `FemaleText_loc5`='Zzz...我們...命中注定， 失敗...zzz...', `FemaleText_loc7`='Zzz... Todo mentiras... Zzz... Estamos condenados... Zzz... Todos...' WHERE `ID`=15902;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제길... 난 너무... 예뻐. 움냐.', `MaleText_loc4`='呼噜噜……我真是……貌美如花……呼噜噜……', `MaleText_loc5`='Zzz...我是如此...美麗...zzz...', `MaleText_loc7`='Zzz... Soy tan... guapo... zzz...', `FemaleText_loc1`='제길... 난 너무... 예뻐. 움냐.', `FemaleText_loc4`='呼噜噜……我真是……貌美如花……呼噜噜……', `FemaleText_loc5`='Zzz...我是如此...美麗...zzz...', `FemaleText_loc7`='Zzz... Soy tan... guapa... zzz...' WHERE `ID`=15903;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구경이라도 났소? 가던 길이나 계속 가시오.', `MaleText_loc4`='这里没有什么可以看的。往前走。', `MaleText_loc5`='在這裡看不到什麼，走吧。', `MaleText_loc7`='No hay nada que ver aquí. Circula.', `FemaleText_loc1`='구경이라도 났소? 가던 길이나 계속 가시오.', `FemaleText_loc4`='这里没有什么可以看的。往前走。', `FemaleText_loc5`='在這裡看不到什麼，走吧。', `FemaleText_loc7`='No hay nada que ver aquí. Circula.' WHERE `ID`=15904;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대가 상관할 일이 아니오. 갈 길이나 가시오.', `MaleText_loc4`='这和你没关系。继续走。', `MaleText_loc5`='這不關你的事，你走吧。', `MaleText_loc7`='Esto no te concierne. Sigue tu camino.', `FemaleText_loc1`='그대가 상관할 일이 아니오. 갈 길이나 가시오.', `FemaleText_loc4`='这和你没关系。继续走。', `FemaleText_loc5`='這不關你的事，你走吧。', `FemaleText_loc7`='Esto no te concierne. Sigue tu camino.' WHERE `ID`=15905;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들을 해치워라!', `MaleText_loc4`='杀死他们！', `MaleText_loc5`='殺了他們!', `MaleText_loc7`='¡Mátalosssss!' WHERE `ID`=15906;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희는 모두 고통에 몸부림치리라!', `MaleText_loc4`='承担这痛苦吧！', `MaleText_loc5`='你們將全被處決!', `MaleText_loc7`='¡Vais a sssufrir!' WHERE `ID`=15907;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='추적자가 오고 있소.', `MaleText_loc4`='有骑兵来了。', `MaleText_loc5`='一個騎士過來了。', `MaleText_loc7`='Se aproxima un jinete.' WHERE `ID`=15908;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스랄! 네가 탈출할 수 있다고 생각하나? 너와 네 동료들은 블랙무어와 대면해야 할 것이다. 내가 충분히 재미를 본 다음에 말이지.', `MaleText_loc4`='萨尔！你不会真的以为可以逃脱吧？你和你的伙伴们很快就要去接受布莱克摩尔的审讯……不过我得先跟你玩玩。', `MaleText_loc5`='索爾!你該不會以為你真的能夠逃走吧?在我玩過癮之後，你和你的盟友得向布拉克摩爾回覆了...', `MaleText_loc7`='¡Thrall! No creias que ibas a escapar, ¿verdad? Tú y tus aliados responderan ante Lodonegro... después de que me entretengo un rato.' WHERE `ID`=15909;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙소, 친구들. 그대들에게 나의 자유를 빚졌군. 그런데 타레사는 어디 있소? 산 속으로 떠나기 전에 마지막으로 그녀에게 감사의 인사를 전하고 싶은데...', `MaleText_loc4`='谢谢你们，朋友。我非常感激你们。塔蕾莎在哪里？我非常希望能在动身离开之前再见她一次，并再次感谢她。', `MaleText_loc5`='謝謝你朋友，我很感激你讓我自由了。塔蕾莎在哪裡?在我離開前往山裡之前，我想見她最後一次並向她道謝。', `MaleText_loc7`='Gracias, amigos; os debo mi libertad. ¿Dónde está Taretha? Tenía la esperanza de volver a verla y darle las gracias antes de partir hacia las montañas.' WHERE `ID`=15910;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스랄, 타레사 님은 당신을 만날 수 없습니다.', `MaleText_loc4`='塔蕾莎不能见你，萨尔。', `MaleText_loc5`='索爾，塔蕾莎不能見你。', `MaleText_loc7`='Taretha no puede verte, Thrall.', `FemaleText_loc1`='스랄, 타레사 님은 당신을 만날 수 없습니다.', `FemaleText_loc4`='塔蕾莎不能见你，萨尔。', `FemaleText_loc5`='索爾，塔蕾莎不能見你。', `FemaleText_loc7`='Taretha no puede verte, Thrall.' WHERE `ID`=15911;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그게 무슨 말이오? 타레사가 위험에 처하기라도 한 것이오?', `MaleText_loc4`='你是什么意思？是不是塔蕾莎有危险？', `MaleText_loc5`='你是什麼意思?你是說塔蕾莎有危險了嗎?', `MaleText_loc7`='¿Qué quieres decir? ¿Taretha está en peligro?' WHERE `ID`=15912;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상황이 좀 복잡합니다, 스랄. 블랙무어의 부하들이 더 나타나기 전에 이제 산으로 출발하시는 것이 좋겠습니다. 우리가 타레사를 꼭 구하겠습니다.', `MaleText_loc4`='现在的处境非常复杂，萨尔。对你来说，最好在更多布莱克摩尔的人出现前离开这里。我们会保证塔蕾莎的安全。', `MaleText_loc5`='索爾，情況更加複雜了。在布拉克摩爾的人出現之前，你現在最好就是前往山裡。我們會確保塔蕾莎的安全。', `MaleText_loc7`='La situación es bastante compleja, Thrall. Por ahora lo mejor será que te dirijas a las montañas antes de que aparezcan los hombres de Lodonegro. Me aseguraré de que Taretha no corra peligro.', `FemaleText_loc1`='상황이 좀 복잡합니다, 스랄. 블랙무어의 부하들이 더 나타나기 전에 이제 산으로 출발하시는 것이 좋겠습니다. 우리가 타레사를 꼭 구하겠습니다.', `FemaleText_loc4`='现在的处境非常复杂，萨尔。对你来说，最好在更多布莱克摩尔的人出现前离开这里。我们会保证塔蕾莎的安全。', `FemaleText_loc5`='索爾，情況更加複雜了。在布拉克摩爾的人出現之前，你現在最好就是前往山裡。我們會確保塔蕾莎的安全。', `FemaleText_loc7`='La situación es bastante compleja, Thrall. Por ahora lo mejor será que te dirijas a las montañas antes de que aparezcan los hombres de Lodonegro. Me aseguraré de que Taretha no corra peligro.' WHERE `ID`=15913;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇게는 할 수 없소. 위험에 처한 타레사를 남겨두고 나 혼자 산으로 달아날 수는 없는 일이오. 나는 겁쟁이가 아니오. 자, 그녀는 어디 있소?', `MaleText_loc4`='我不会这么做的。我不会把塔蕾莎留在危险中，而我却自己跑开。我不是个懦夫。现在告诉我，她在哪里？', `MaleText_loc5`='我不會做出這種事情的，我無法在塔蕾莎危險之際還離開她，逃跑到山裡，我不是膽小鬼。現在她在哪裡?', `MaleText_loc7`='No lo haré. No puedo dejar a Taretha en peligro mientras huyo hacia las montañas. No soy un cobarde. ¿Dónde está?' WHERE `ID`=15914;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타렌 제분소에 있습니다.', `MaleText_loc4`='塔伦米尔。', `MaleText_loc5`='塔倫米爾。', `MaleText_loc7`='Molino Tarren.', `FemaleText_loc1`='타렌 제분소에 있습니다.', `FemaleText_loc4`='塔伦米尔。', `FemaleText_loc5`='塔倫米爾。', `FemaleText_loc7`='Molino Tarren.' WHERE `ID`=15915;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋소. 타렌 제분소는 여기서 서쪽에 있소. 시간이 많지 않소.', `MaleText_loc4`='很好。塔伦米尔就在西面。既然时间紧迫……', `MaleText_loc5`='非常好，塔倫米爾就在此處的西邊，既然時間非常重要...', `MaleText_loc7`='Muy bien. El Molino Tarren se encuentra al oeste. El tiempo es fundamental...' WHERE `ID`=15916;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리가 한목소리로 말한다면 그 누구도 우릴 무시할 수 없을 거요!', `FemaleText_loc4`='如果我们作为一个整体来抗争，就不可能被忽视了！', `FemaleText_loc5`='如果我們和一個人說話，就不該被忽略!', `FemaleText_loc7`='¡Si nos ponemos todos de acuerdo, nadie podrá ignorarnos!' WHERE `ID`=15917;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리에게 여러분의 힘을 실어주시오! 지금이야말로 우리 종족을 구원하기 위해 행동에 나설 때요!', `MaleText_loc4`='让所有人听到你们的声音！现在是时候团结起来拯救我们的人民了。', `MaleText_loc5`='請借助我們你們的聲音!時候到了，我們是該發動解救我們的人民了。', `MaleText_loc7`='¡Unamos nuestras voces! Ha llegado el momento de salvar a nuestro pueblo.' WHERE `ID`=15918;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로르테마르는 우리 말을 경청해야 할 거요! 우리는 절대 조용히 있지 않을 테니까!', `MaleText_loc4`='洛瑟玛必须听到我们的呼声！我们不能再沉默下去了！', `MaleText_loc5`='洛索瑪一定要聽聽我們的意見!我們不會再沉默下去!', `MaleText_loc7`='¡Lor''themar debe oírnos! ¡Nadie nos hará callar!' WHERE `ID`=15919;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마법학자들이 우리를 다시 영광으로 인도할 거요.', `FemaleText_loc4`='魔导师们会指引我们重获荣耀。', `FemaleText_loc5`='博學者會指引我們返回光榮。', `FemaleText_loc7`='Los magistri nos guiarán de nuevo a la gloria.' WHERE `ID`=15920;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 새로운 동맹이 우리를 예전의 영광으로 인도할 거요. 이 동맹은 진실할 것이고, 우리는 또다시 배신당하지 않을 거요!', `MaleText_loc4`='我们的新盟友会帮助我们回归昔日的荣光。这一次，我们不会再被背叛了！', `MaleText_loc5`='我們的新同盟將會帶領我們回到過有的光榮，這個約定是真的，我們不會再次被背叛的!', `MaleText_loc7`='Nuestros nuevos aliados nos devolverán nuestra antigua gloria. Estos vínculos serán verdaderos. ¡Nadie volverá a traicionarnos!' WHERE `ID`=15921;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 문제에 대해서 생각해보겠소. 도움이 필요하면 부르시오.', `MaleText_loc4`='应该没问题了。如果你还需要我的话，召唤我。', `MaleText_loc5`='那應該要注意一下。如果你還需要我的服務就召喚我吧。', `MaleText_loc7`='Con esto debería bastar. Vuelve a llamarme si necesitas mi ayuda.' WHERE `ID`=15922;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마력이 우리의 도시를 위대하게 만들었다는 사실을 모르시겠소?', `MaleText_loc4`='你们没有看到魔法是怎样把我们的城市变得如此美好吗？', `MaleText_loc5`='你難道看不出來魔法讓我們的城市如此美好?', `MaleText_loc7`='¿No ves cómo la magia ha hecho de nuestra ciudad una maravilla?' WHERE `ID`=15923;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로르테마르는 실버문을 재건하여 우리가 진정 자랑스러워할 만한 도시로 만들었소.', `MaleText_loc4`='洛瑟玛重建的银月城真是我们的骄傲。', `MaleText_loc5`='洛索瑪將銀月城重建成一座我們真該引以為傲的城市。', `MaleText_loc7`='Lor''themar ha transformado Lunargenta en algo de lo que sí podemos estar orgullosos.' WHERE `ID`=15924;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 우리의 삶이 예전보다 개선되지 않았다고 말할 자가 있소? 우리의 생활이 윤택해졌다는 사실을 부인할 자가 있느냐는 말이오.', `MaleText_loc4`='你怎么可以说我们的生活没有变得更美好？你怎么可以否定我们的生活变得更美好了？', `MaleText_loc5`='你怎麼可以說我們的生活不如以往?你怎麼可以否定我們生活的進步?', `MaleText_loc7`='¿Cómo puedes pensar que nuestras vidas no están mejor ahora? No puedes negar que hemos avanzado mucho.' WHERE `ID`=15925;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='현명한 마법학자들은 우리를 번영의 미래로 인도할 계획을 세울 거요.', `MaleText_loc4`='英明的魔导师将会指引我们走向繁荣的未来。', `MaleText_loc5`='睿智的博學者將會規劃出我們未來的繁盛方向。', `MaleText_loc7`='Los magistri son sabios y elaborarán un plan próspero para nuestro futuro.' WHERE `ID`=15926;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='얼라이언스 놈들의 배신을 백 배, 천 배로 갚아줄 거요. 절대 잊어서도 용서해서도 안 돼!', `FemaleText_loc4`='我们会让联盟千倍偿还他们的背叛。我们永远也不会原谅和忘记这种耻辱。', `FemaleText_loc5`='那些背叛我們的聯盟會付出成千成倍的代價，我們永遠不會放棄也絕對不會忘記。', `FemaleText_loc7`='Haremos que la Alianza pague por su traición y su abandono. No perdonaremos ni olvidaremos nunca.' WHERE `ID`=15927;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마력에 반대하는 자들은 진보의 적이요.', `FemaleText_loc4`='那些公开反对魔法的家伙都是潜在的敌人。', `FemaleText_loc5`='那些說出要抵抗法力的人都是敵人。', `FemaleText_loc7`='Los que critican la magia son enemigos del progreso.' WHERE `ID`=15928;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자연은 마력과 평화롭게 공존하지. 양쪽 모두를 가진다면 우리 미래에 한계란 없소.', `FemaleText_loc4`='自然和魔法和平相处。有了这两者，我们前途似锦。', `FemaleText_loc5`='我們自然的生活在和平與魔法之中。相輔相成之下，我們的未來不受拘束。', `FemaleText_loc7`='La naturaleza vive en paz con la magia. Con ambas cosas, nuestro futuro no tiene límite.' WHERE `ID`=15929;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우린 얼라이언스의 배신을 갚아줘야 해! 절대 잊어서도, 용서해서도 안 될 것이오!', `FemaleText_loc4`='我们会报复联盟！我们永远也不会忘记，永远也不会原谅他们！', `FemaleText_loc5`='我們會報復聯盟的背叛!我們永不忘記也絕不放棄!', `FemaleText_loc7`='¡Le devolveremos la traición a la Alianza! Nunca olvidaremos, ¡y nunca perdonaremos!' WHERE `ID`=15930;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물건을 두루 살펴보고 싶습니다.', `MaleText_loc4`='我想要看看你出售的货物。', `MaleText_loc5`='我希望能看看你的物品。', `MaleText_loc7`='Me gustaría ver tus mercancías.', `FemaleText_loc1`='물건을 두루 살펴보고 싶습니다.', `FemaleText_loc4`='我想要看看你出售的货物。', `FemaleText_loc5`='我希望能看看你的物品。', `FemaleText_loc7`='Me gustaría ver tus mercancías.' WHERE `ID`=15931;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나를 여기서 만났다고 너무 놀란 표정 짓지 마시오, $r|1이여;여;. 계시자 쿠르즈가 드레나이와 내 종족의 동맹이 온다고 예언했다오.', `MaleText_loc4`='不要用惊讶的眼光看着我，$r。德莱尼人的到来和与我们的结盟都已经被启示者库尔兹言中了。', `MaleText_loc5`='看到我在這裡也別這麼驚訝，$r。『啟示者』克茲預言德萊尼和他們的聯盟以及我的子民們即將到來。', `MaleText_loc7`='No te sorprendas tanto por verme aquí, $r. Kurz el Revelador predijo la llegada de los draenei y su alianza con mi pueblo.' WHERE `ID`=15932;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<펄볼그 언어로 인사하자 미소 짓는 너울소나무 대사 프라사부>$B$B당신이 예언에서 말하던 그 사람이 틀림없군. 만나게 되어 크나 큰 영광이오.$B$B나는 대족장이신 너울소나무 님의 핏빛 감시초소의 대리인인 너울소나무 대사 프라사부라고 하오이다.', `MaleText_loc4`='<你用熊怪语问候大使弗拉萨布，他笑了笑。>$B$B你一定是预言中被提到的那个人了，见到你很荣幸。$B$B我是弗拉萨布大使，止松老酋长派驻秘血岗哨的代表。', `MaleText_loc5`='<當你是用熊怪語和大使法薩布打招呼時，他笑了。>$B$B你一定是預言中那個會說這個語言的人，很榮幸能遇見你。$B$B我是大使法薩布，大酋長靜松在血色守望的代表。', `MaleText_loc7`='<Cuando saludas al embajador Frasaboo en el idioma fúrbolg, sonríe.>$B$BTú debes de ser de quien habla la profecía. Es un gran honor conocerte.$B$BSoy el embajador Frasaboo, representante del gran jefe Semprepino en Avanzada de Sangre.' WHERE `ID`=15933;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 만나서 반갑소이다, $n. 대족장이신 너울소나무 님께서는 뾰족가지 펄볼그로부터 따님을 구해주신 것에 대해 깊이 감사하고 계시오이다.', `MaleText_loc4`='很高兴再次见到你，$n。你从刺臂部族手里救了止松老酋长的女儿，他衷心地感谢你。', `MaleText_loc5`='很高興再見到你，$n。大酋長靜松對於你從鬚肢的爪牙之下解救他的女兒，至上深深的感激。', `MaleText_loc7`='Me alegro de verte de nuevo, $n. Tienes la gratitud del gran jefe Semprepino por rescatar a su hija de las garras de Brazolanudo.' WHERE `ID`=15934;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탐험가 연맹의 회원으로 오랜 세월을 보내면서 나는 아제로스 전역을 여행했지요. 그러나 핏빛안개 섬과 같은 건 본 적이 없습니다.', `MaleText_loc4`='我加入探险者协会这么多年来，已经踏遍了整个艾泽拉斯，但我从没见过秘血岛那样的地方。', `MaleText_loc5`='在我當探險者協會成員的那幾年裡，我踏遍了艾澤拉斯，但我從未看過有關血謎島的事物。', `MaleText_loc7`='Durante mis años como miembro de la Liga de Expedicionarios, he viajado por todo Azeroth, pero nunca he visto nada como Bruma de Sangre.' WHERE `ID`=15935;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='채광에 대해 가르쳐 주십시오.', `MaleText_loc4`='教我如何采矿。', `MaleText_loc5`='請訓練我採礦技巧。', `MaleText_loc7`='Entréname en el oficio de la minería.', `FemaleText_loc1`='채광에 대해 가르쳐 주십시오.', `FemaleText_loc4`='教我如何采矿。', `FemaleText_loc5`='請訓練我採礦技巧。', `FemaleText_loc7`='Entréname en el oficio de la minería.' WHERE `ID`=15936;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제발 아무 말씀도 말아 주세요. 더 이상 이들과 문제를 일으키고 싶지 않습니다.', `MaleText_loc4`='请不要对我说任何事，我不想再介入他们的麻烦之中。', `MaleText_loc5`='拜託，別再跟我說什麼了。我不想和他們再惹更多的麻煩了。', `MaleText_loc7`='Por favor, no me digas nada. No quiero tener más problemas con ellos.', `FemaleText_loc1`='제발 아무 말씀도 말아 주세요. 더 이상 이들과 문제를 일으키고 싶지 않습니다.', `FemaleText_loc4`='请不要对我说任何事，我不想再介入他们的麻烦之中。', `FemaleText_loc5`='拜託，別再跟我說什麼了。我不想和他們再惹更多的麻煩了。', `FemaleText_loc7`='Por favor, no me digas nada. No quiero tener más problemas con ellos.' WHERE `ID`=15937;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리는 방금 여기 도착해서 너무나 많은 친구와 동지들을 묻었습니다. 슬프지 않을 수가 없네요.', `FemaleText_loc4`='我们刚刚抵达这里，却已经有许多战友和朋友在途中丧生了。', `FemaleText_loc5`='我們才剛到這裡就得埋葬我們眾多的朋友與夥伴。', `FemaleText_loc7`='Acabamos de llegar aquí y ya hemos enterrado a demasiados amigos.' WHERE `ID`=15938;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용건이 뭡니까, $r|1이여;여;?', `MaleText_loc4`='你想要什么，$r？', `MaleText_loc5`='你想要什麼東西呢， $r?', `MaleText_loc7`='¿Qué quieres, $r?' WHERE `ID`=15939;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물건을 구경하고 싶습니다, 오토남부시.', `MaleText_loc4`='奥图纳布斯，我想要看看你出售的货物。', `MaleText_loc5`='我希望可以看看你的商品，歐多納布希。', `MaleText_loc7`='Me gustaría echar un vistazo a tu mercancía, Otonambusi.', `FemaleText_loc1`='물건을 구경하고 싶습니다, 오토남부시.', `FemaleText_loc4`='奥图纳布斯，我想要看看你出售的货物。', `FemaleText_loc5`='我希望可以看看你的商品，歐多納布希。', `FemaleText_loc7`='Me gustaría echar un vistazo a tu mercancía, Otonambusi.' WHERE `ID`=15940;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런... 당신, 생선을 먹지 않는다면 어떻게 푸딩을 얻을 수 있겠습니까?', `MaleText_loc4`='不吃鱼，你怎么能吃布丁呢?', `MaleText_loc5`='如果你不吃魚的話又怎麼能吃布丁呢?', `MaleText_loc7`='¿Cómo vas a tomar postre si no te comes el pescado?' WHERE `ID`=15941;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생선을 먹지 않는다면 푸딩을 얻을 수 없습니다!', `MaleText_loc4`='如果你不把鱼吃了，就别想吃布丁！', `MaleText_loc5`='如果你不吃魚的話，就不可以吃布丁!', `MaleText_loc7`='Si no te comes el pescado, no tendrás postre.' WHERE `ID`=15942;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련을 원합니다, 아에솜.', `MaleText_loc4`='我想接受训练，伊索姆。', `MaleText_loc5`='我希望接受訓練，艾伊森。', `MaleText_loc7`='Me gustaría recibir instrucción, Aesom.', `FemaleText_loc1`='훈련을 원합니다, 아에솜.', `FemaleText_loc4`='我想接受训练，伊索姆。', `FemaleText_loc5`='我希望接受訓練，艾伊森。', `FemaleText_loc7`='Me gustaría recibir instrucción, Aesom.' WHERE `ID`=15943;
