UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타레사! 이 사악한 마력은 대체 뭐요?', `MaleText_loc4`='塔蕾莎！这是什么邪恶的魔法？', `MaleText_loc5`='塔蕾莎!這可恨的法術是什麼?', `MaleText_loc7`='¡Taretha! ¿Qué clase de magia repugnante es esta?' WHERE `ID`=15978;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='스랄, 빠져나오셨군요!', `FemaleText_loc4`='萨尔，你逃出来了！', `FemaleText_loc5`='索爾，快逃!', `FemaleText_loc7`='¡Thrall, has escapado!' WHERE `ID`=15979;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나, 이 근방에서 가장 위대한 마법사 위크소스의 페오레스가 일개 여행자인 그대를 언더시티로 순간이동 해드리겠소.$B$B이 개혁의 시기에 나의 위대함을 느껴보시오. 그 이름도 웅장한 눈보라사가 과거에 그 누구도 본 적도, 들은 적도, 느낀 적도 없는 순간이동 장치를 준비한 것이오.$B$B그렇소, 아주 웅장한 장치요. 그 대단한 장치는 시간과 공간의 구조 자체를 이동하여 이 세계에 머무는 모든 생명체들을 새로운 번영의 시대로 데려갈 거요.', `MaleText_loc4`='我，匹欧雷斯，附近最伟大的法师，会传送你，一个苦工，去幽暗城。$B$B你应该注意到的是，我的伟大只有在这改革时期才会被感觉到，我这个皇家工程师所建造的一个以前从未有人看到过、听到过、甚至想到过的传送设施。$B$B没错，太伟大了。这项发明是如此的重要，甚至会令空间和时间的构造自行切换，推动这个世界的人民进入一个繁荣的新时代……', `MaleText_loc5`='在下我，帕歐瑞什·伊丹比，傳說中最偉大的法師，我會把你這個苦工傳送至幽暗城去。$B$B當皇家暴雪家族準備好前所未聞的傳送紋章，從這個革新時期中，你可以感受到我的偉大是多麼顯赫。$B$B喔，沒錯，這是很偉大的。事實上在這種物換星移的情況下，推動這個世界的居民進入繁盛新世紀...', `MaleText_loc7`='Yo, Peoreth Il''danube, el mago más grande en diez metros a la redonda, te teletransportaré a ti, simple plebeyo, a la ciudad de Entrañas.$B$BQuiero recordar que mi presencia solo os iluminará durante este periodo de cambios, ya que la real Casa de Ventisca está preparando un sistema de teletransporte como nunca se ha visto bajo las estrellas.$B$BSí, señor; dará gloria verlo. Tanta gloria que el mismo tejido del tiempo y el espacio cambiará, desplazando a los más afortunados habitantes de este mundo hacia una nueva era de prosperidad...' WHERE `ID`=15980;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그냥 저를 언더시티로 순간이동시켜 주십시오.', `MaleText_loc4`='闭嘴，把我传送到幽暗城。', `MaleText_loc5`='給我閉嘴，把我傳送至幽暗城就對了!', `MaleText_loc7`='Cierra el pico y teletranspórtame a Entrañas.', `FemaleText_loc1`='그냥 저를 언더시티로 순간이동시켜 주세요.', `FemaleText_loc4`='闭嘴，把我传送到幽暗城。', `FemaleText_loc5`='給我閉嘴，把我傳送至幽暗城就對了!', `FemaleText_loc7`='Cierra el pico y teletranspórtame a Entrañas.' WHERE `ID`=15981;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 종족의 풍요로운 문화를 마음껏 느껴보시오! 딱 한 번이라도 화려한 삶을 누려보시오. 그런 후에는 신의 손길을 받은 것을 고마워하며 기쁨 속에 최후를 맞을 수 있을 거요!$B$B블러드 엘프라면 남자, 여자, 애, 어른 할 것 없이 모두 못마땅해하지. 그대에게 날아올 경멸의 침을 무시하고 마음껏 먹고 들이켜시오!$B$B야만인이여, 그대와 함께 실버문으로!', `MaleText_loc4`='享受血精灵富庶的生活吧！领略世间最奢华的装饰，哪怕一次也好。或许你走到生命尽头之时，还能回忆起今天这个被神灵眷顾的幸运日！$B$B饮下这杯酒吧，化解所有对血精灵的指责。饮下它吧！$B$B野蛮人，为了银月城干杯！', `MaleText_loc5`='我的子民沉浸在富饒裡!如果只有一次，好好享受富裕的生活吧。或許之後你就在這樣的結局中死去，蒙主寵召啊!$B$B要你喝下這個唾液是為了從反對派的血精靈那裡，確保飛行的方向。男人、女人和小孩，喝乾它!喝．乾．它!$B$B你這野蠻人，我就和你一起到銀月城吧!', `MaleText_loc7`='¡Sumérgete en la opulencia de mi pueblo! Prueba, por una vez, las delicias de la vida. ¡Puede que entonces mueras a gusto, sabiendo que fuiste tocado por la mano de un dios!$B$BQue bebas los salivazos que recibas de elfos de sangre; niños, mujeres y hombres, todos por igual. ¡Bebe! ¡Bebe!$B$B¡A Lunargenta, bárbaro!' WHERE `ID`=15982;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그냥 저를 실버문으로 순간이동시켜 주십시오.', `MaleText_loc4`='嗯，把我传送到银月城吧。', `MaleText_loc5`='嗯，把我傳送至銀月城吧。', `MaleText_loc7`='Mm, tú solo teletranspórtame a Lunargenta.', `FemaleText_loc1`='그냥 저를 실버문으로 순간이동시켜 주세요.', `FemaleText_loc4`='嗯，把我传送到银月城吧。', `FemaleText_loc5`='嗯，把我傳送至銀月城吧。', `FemaleText_loc7`='Mm, tú solo teletranspórtame a Lunargenta.' WHERE `ID`=15983;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미안하오, 젊은이... 순간이동 주문을 사용하려면 최소한 이만큼은 자라야 하오.$B$B<오른손으로 자기 무릎 근처의 높이를 가리키는 페오레스>$B$B더 자라거든 다시 오시오.', `MaleText_loc4`='啊，很抱歉，年轻的主人。你必须至少有这点高度才能使用传送法术。$B$B<匹欧雷斯用他的右手在他膝盖附近做了一个高度的近似值。>$B$B等你长大了再回来吧。', `MaleText_loc5`='哎，年輕人真對不起呀。你是最後一個利用傳送法術的人吧。$B$B<帕歐瑞什高舉他的右手，然後停在及膝的高度。>$B$B當你長大後，就回來吧。', `MaleText_loc7`='Ah, mis disculpas, joven $gmaestro:maestra;. Tienes que ser así de $galto:alta; para poder usar un hechizo de teletransporte.$B$B<Peoreth señala con su mano derecha la altura de su rodilla.>$B$BVuelve cuando hayas crecido.' WHERE `ID`=15984;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미안하오, 젊은이... 순간이동 주문을 사용하려면 최소한 이만큼은 자라야 하오.$B$B<오른손으로 자기 무릎 근처의 높이를 가리키는 말트라케>$B$B더 자라거든 다시 오시오.', `MaleText_loc4`='啊，很抱歉，年轻的主人。你必须至少有这点高度才能使用传送法术。$B$B<玛尔塔克用他的右手在他膝盖附近做了一个高度的近似值。>$B$B等你长大了再回来吧。', `MaleText_loc5`='哎，年輕人真對不起呀。你是最後一個利用傳送法術的人吧。$B$B<瑪特拉克高舉他的右手，然後停在及膝的高度。>$B$B當你長大後，就回來吧。', `MaleText_loc7`='Ah, mis disculpas, joven $gmaestro:maestra;. Tienes que ser así de $galto:alta; para poder usar un hechizo de teletransporte.$B$B<Maltrake señala con su mano derecha la altura de su rodilla.>$B$BVuelve cuando hayas crecido.' WHERE `ID`=15985;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런, 저자를 막아라!', `MaleText_loc4`='他在这里，阻止他！', `MaleText_loc5`='他在這裡，阻止他!', `MaleText_loc7`='¡Está aquí! ¡Hay que detenerle!', `FemaleText_loc1`='이런, 저자를 막아라!', `FemaleText_loc4`='他在这里，阻止他！', `FemaleText_loc5`='他在這裡，阻止他!', `FemaleText_loc7`='¡Está aquí! ¡Hay que detenerle!' WHERE `ID`=15986;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='스랄의 탈출을 도와주셔서 감사합니다, 여러분. 이제 저도 좀 도와주실 수 있을까요? 오늘 아침에 일어나보니 이 마법 감옥에 갇혀 있는 것을 알게 되었습니다. 한 이상한 마법사가 한동안 여기 갇혀 있어야 할 거라고만 말했답니다.', `FemaleText_loc4`='感谢你们帮助萨尔逃脱，朋友们。现在我只希望你们同样能帮我。我早上醒来时，发现自己被囚禁在这个魔法监牢中。一个奇怪的巫师告诉我，我必须在这里待一段时间。', `FemaleText_loc5`='我的朋友們，謝謝你們幫助索爾逃脫。現在我只希望你也可以幫助我。今天早晨我醒來的時候，發現自己被關在這個有法力的監牢裡。一個奇怪的巫師告訴我說，我暫時得待在這裡。', `FemaleText_loc7`='Gracias por ayudar a Thrall a escapar, amigos. Ahora, espero que también podáis ayudarme a mí. Me desperté esta mañana atrapada en esta prisión mágica. Un extraño zahorí me dijo que me quedaría un tiempo aquí.' WHERE `ID`=15987;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신은 누구시죠? 그 마법사와 한패인가요?', `FemaleText_loc4`='Who are you? Are you with the wizard? [PH]', `FemaleText_loc5`='你是誰?你和巫師在一起嗎?[PH]', `FemaleText_loc7`='¿Quién eres tú? ¿Estás con el zahorí? [PH]' WHERE `ID`=15988;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='', `MaleText_loc4`='', `MaleText_loc5`='', `MaleText_loc7`='' WHERE `ID`=15989;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 당신을 구하러 왔습니다, 타레사.', `MaleText_loc4`='我们是来这里救你的，塔蕾莎。', `MaleText_loc5`='我們來營救妳了，塔蕾莎!', `MaleText_loc7`='Hemos venido a rescatarte, Taretha.', `FemaleText_loc1`='우린 당신을 구하러 왔습니다, 타레사.', `FemaleText_loc4`='我们是来这里救你的，塔蕾莎。', `FemaleText_loc5`='我們來營救妳了，塔蕾莎!', `FemaleText_loc7`='Hemos venido a rescatarte, Taretha.' WHERE `ID`=15990;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아니오, 지금은 별로 중요한 일이 없네요. 당신은 가셔서 스랄이 탈출하는 걸 도와주세요. 제가 감옥에 불을 질러 소란을 피우려고 했는데 이 마법 감옥에 붙잡혀 있는 신세라 어쩔 수 없이 제 대신 이번 일을 해 주셔야겠습니다.', `FemaleText_loc4`='No, I''m not important right now. You have to go help Thrall escape. I was going to set a fire as a diversion, but with me in this magical prison you''ll have to do it instead. [PH]', `FemaleText_loc5`='不，我現在不是最重要的。你必須幫助索爾脫逃。我會放火來分散注意力，不過我被關在這個有法力的監牢裡，所以你得代替我才行。[PH]', `FemaleText_loc7`='No, yo no soy importante ahora mismo. Tienes que ir a ayudar a Thrall a escapar. Iba a encender un fuego para crear una distracción pero, conmigo en esta prisión mágica, van a tener que hacerlo ustedes. [PH]' WHERE `ID`=15991;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이상한 마법사라고요?', `MaleText_loc4`='奇怪的巫师？', `MaleText_loc5`='奇怪的巫師?', `MaleText_loc7`='¿Un zahorí extraño?', `FemaleText_loc1`='이상한 마법사라고요?', `FemaleText_loc4`='奇怪的巫师？', `FemaleText_loc5`='奇怪的巫師?', `FemaleText_loc7`='¿Un zahorí extraño?' WHERE `ID`=15992;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네, 맞아요. 그 남자는 달라란의 마법사가 아니었어요. 그의 옷은 상당히 이국적이고 억양도 생소했답니다. 그가 중얼거리던 말이라고는 시간이 어쩌고저쩌고하는 것뿐이었어요. 그 마법사를 찾아서 절 풀어 주라고 설득해 주세요.', `FemaleText_loc4`='是的，朋友们。这个人不是达拉然的巫师。他的衣服看上去是外来的，还有他的口音我也不是很熟悉。他不停地说着什么时间这个、时间那个之类的话。你得找到那个巫师，让他来释放我。', `FemaleText_loc5`='是的，朋友們。這個人不是達拉然的巫師。他的衣服看起來有點陌生，而他的口音聽起來也不太熟悉。他總是含糊的說著這個時間、那個時間的。你要找到這個巫師並說服他釋放我。', `FemaleText_loc7`='Sí, amigos. Ese hombre no era un zahorí de Dalaran. Sus ropas y acento no me resultaban familiares. Todo lo que decía es el tiempo esto, el tiempo lo otro... Tendréis que encontrar al zahorí y convencerle para que me suelte.' WHERE `ID`=15993;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타레사, 우리가 꺼내 드리겠으니 걱정하지 마십시오. 그 마법사는 아주 먼 곳으로 사라진 것 같습니다.', `MaleText_loc4`='我们会把你救出去的，塔蕾莎。不要担心。我怀疑那个巫师很可能在就在附近徘徊。', `MaleText_loc5`='我們會救妳出來的，塔蕾莎。別擔心，我猜巫師離這裡還遠得很呢。', `MaleText_loc7`='Te sacaremos de ahí, Taretha. No te preocupes. No creo que el zahorí se haya ido muy lejos.', `FemaleText_loc1`='타레사, 우리가 꺼내 드리겠으니 걱정하지 마십시오. 그 마법사는 아주 먼 곳으로 사라진 것 같군요.', `FemaleText_loc4`='我们会把你救出去的，塔蕾莎。不要担心。我怀疑那个巫师很可能在就在附近徘徊。', `FemaleText_loc5`='我們會救妳出來的，塔蕾莎。別擔心，我猜巫師離這裡還遠得很呢。', `FemaleText_loc7`='Te sacaremos de ahí, Taretha. No te preocupes. No creo que el zahorí se haya ido muy lejos.' WHERE `ID`=15994;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타레사가 살아 있다니 정말 기쁘네. 이제 그녀를 마법 속박에서 풀어 줄 방법을 찾아야 하네.', `MaleText_loc4`='我很高兴塔蕾莎还活着，现在我们必须找到一个方法把她从魔法禁锢中解救出来。', `MaleText_loc5`='我很高興塔蕾莎還活著。我們現在得想個法子，從充滿魔力的束縛中解救她。', `MaleText_loc7`='Me alegro de que Taretha siga viva. Debemos encontrar la forma de liberarla de sus ataduras mágicas.' WHERE `ID`=15995;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 고난의 거리를 대표하여 아킨둔에서 어둠의 의회 일당을 뿌리 뽑아야 한다는 제안을 하려고 왔습니다. 그러니까, 우리의 희망찬 미래를 위해서라도 해골 무덤보다 더한 재앙이 일어날 가능성을 미리 방지하자는 거지요!$B$B우리 백성은 이미 많은 고통을 겪었습니다. 저는 그 고통을 멈추고자 여기 왔습니다!', `FemaleText_loc4`='作为贫民窟的代表，我要在此提出我们的建议，那就是：必须扫清在奥金顿横行的暗影议会成员。这关系到我们是否能在未来阻止他们再次创造一个新的白骨荒野，制造一次更大的灾难！$B$B我们的人民已经承受了太多的痛苦。我在这里盼望着那些痛苦立刻停止！', `FemaleText_loc5`='身為陰鬱城的代表，在這裡我要提出我們的困擾，奧齊頓必須解決暗影議會的侵擾。也就是說比起白骨荒野的世界，我們對於未來要有希望，並儘可能地擊退大洪水!$B$B我們的子民已經承受太多的苦難了，我希望能看見這場災難停止。', `FemaleText_loc7`='Como representante del Bajo Arrabal, estoy aquí para exponer nuestro caso, por el que Auchindoun debe ser evacuada de su infestación del Consejo de la Sombra. Esto es, ¡si queremos albergar esperanzas de tener un futuro y evitar la posibilidad de un cataclismo mayor que la creación de El Vertedero de Huesos!$B$BTodas nuestras gentes han sufrido ya demasiado. ¡Estoy aquí para encargarme de que ese sufrimiento se detenga!' WHERE `ID`=15996;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파멸의 수호병', `MaleText_loc4`='末日守卫', `MaleText_loc5`='末日守衛', `MaleText_loc7`='Guardia apocalíptico', `FemaleText_loc1`='파멸의 수호병', `FemaleText_loc4`='末日守卫', `FemaleText_loc5`='末日守衛', `FemaleText_loc7`='Guardia apocalíptico' WHERE `ID`=15997;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='격노수호병', `MaleText_loc4`='愤怒卫士', `MaleText_loc5`='憤怒守衛', `MaleText_loc7`='Guardia de cólera', `FemaleText_loc1`='격노수호병', `FemaleText_loc4`='愤怒卫士', `FemaleText_loc5`='憤怒守衛', `FemaleText_loc7`='Guardia de cólera' WHERE `ID`=15998;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서큐버스', `MaleText_loc4`='魅魔', `MaleText_loc5`='魅魔', `MaleText_loc7`='Súcubo', `FemaleText_loc1`='서큐버스', `FemaleText_loc4`='魅魔', `FemaleText_loc5`='魅魔', `FemaleText_loc7`='Súcubo' WHERE `ID`=15999;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쉬바라', `MaleText_loc4`='破坏魔', `MaleText_loc5`='希瓦拉', `MaleText_loc7`='Shivarra', `FemaleText_loc1`='쉬바라', `FemaleText_loc4`='破坏魔', `FemaleText_loc5`='希瓦拉', `FemaleText_loc7`='Shivarra' WHERE `ID`=16000;
