UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지옥수호병', `MaleText_loc4`='恶魔卫士', `MaleText_loc5`='惡魔守衛', `MaleText_loc7`='Guardia vil', `FemaleText_loc1`='지옥수호병', `FemaleText_loc4`='恶魔卫士', `FemaleText_loc5`='惡魔守衛', `FemaleText_loc7`='Guardia vil' WHERE `ID`=16006;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌아가라, 필멸의 존재여... 네가 할 만한 싸움이 아니다.', `MaleText_loc4`='回去吧，凡人……这不是你的战争。', `MaleText_loc5`='凡人啊...回去吧...這不是你們的戰爭。', `MaleText_loc7`='Da la vuelta, mortal... Esta no es tu guerra.' WHERE `ID`=16007;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너는 그들을 막을 수 없다...', `MaleText_loc4`='你没法阻止他们……', `MaleText_loc5`='你無法阻止他們...', `MaleText_loc7`='No puedes detenerles...' WHERE `ID`=16008;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 영원한... 존재다.', `MaleText_loc4`='我们是无穷的……永恒的。', `MaleText_loc5`='我們是無盡的...永恆。', `MaleText_loc7`='Somos infinitos... eternos.' WHERE `ID`=16009;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들은 통제력이 부족하다... 오슈군이 그들을 부른다...', `MaleText_loc4`='他们无法控制自己……沃舒古在召唤他们……', `MaleText_loc5`='他們不受控制...歐夏剛在呼喚他們...', `MaleText_loc7`='No tienen control... Oshu''gun les llama...' WHERE `ID`=16010;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그건 봉화다. 잊혀진 시대의 유산이지.', `MaleText_loc4`='这是一座灯塔。一个被忘却的时代留下的遗迹。', `MaleText_loc5`='這是信號燈，是遺忘時代裡的遺物。', `MaleText_loc7`='Es una baliza. Un recuerdo de una época olvidada.' WHERE `ID`=16011;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='편히 앉으십시오. 장가르 습지대의 난폭한 적들은 수많은 생명을 앗아갈 수도 있습니다.', `MaleText_loc4`='坐一会吧，朋友。赞加沼泽所遭受的破坏真让人身心疲惫。', `MaleText_loc5`='請坐，$g兄弟:姐妹;。 贊格沼澤的災害會帶走許許多多的$g男人:女人;。', `MaleText_loc7`='Siéntate, $ghermano:hermana;. Los devastadores de la Marisma de Zangar pueden acabar con cualquier $ghombre:mujer;.' WHERE `ID`=16012;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에서 쉬고 싶다면 말씀만 하십시오!', `MaleText_loc4`='如果你想要在这里休息，跟我说就行了！', `MaleText_loc5`='如果你想在這裡休息，你只需要問一下就好了!', `MaleText_loc7`='¡Si quieres descansar aquí, solo tienes que preguntar!' WHERE `ID`=16013;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크아아아!', `MaleText_loc4`='啊啊啊啊啊！', `MaleText_loc5`='嗄嗄嗄!', `MaleText_loc7`='¡Graaaa!' WHERE `ID`=16014;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연고를 만들 수 있도록 도와주셔서 감사합니다, $n. 통증이 좀 없어지면 이 다리로 어디까지 갈 수 있나 확인해 봐야겠습니다.', `MaleText_loc4`='感谢你帮我制造药膏，$n。如果它真能缓解痛苦，我会去看看我能让这条腿走多远。', `MaleText_loc5`='謝謝你幫忙製作藥膏，$n。只要有機會可以減輕疼痛，不管多遠我都可以靠這條腿找尋找它。', `MaleText_loc7`='Gracias por tu ayuda con el bálsamo, $n. Cuando me haya calmado el dolor, probaré lo lejos que consigo llegar con la pierna así...' WHERE `ID`=16015;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스랄! 밖으로 나와서 네 운명을 받아들여라!', `MaleText_loc4`='萨尔！出来面对你的命运吧！', `MaleText_loc5`='索爾!出來受死吧!', `MaleText_loc7`='¡Thrall! ¡Sal y enfréntate a tu destino!' WHERE `ID`=16016;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐였지?', `MaleText_loc4`='那是什么东西？', `MaleText_loc5`='誰，那是什麼東西?', `MaleText_loc7`='¿Qué o quién era eso?' WHERE `ID`=16017;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스랄, 밖으로 나와서 네 운명을 맞이해라.', `MaleText_loc4`='萨尔！出来面对你的命运吧！', `MaleText_loc5`='索爾，出來面對你的命運吧! [PH]', `MaleText_loc7`='¡Sal fuera y enfréntate a tu destino! [PH]' WHERE `ID`=16018;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타레사의 목숨이 위태롭다. 너희는 그녀를 살리고 싶겠지... 분명히 그녀를 구출하고 싶을 거야.', `MaleText_loc4`='塔蕾莎性命堪忧，你一定非常关心她，你一定想要救她……', `MaleText_loc5`='塔蕾莎的生命危在旦夕。想必你很關心她。想必你很想救她...', `MaleText_loc7`='La vida de Taretha pende de un hilo. Seguro que te importa. Seguro que quieres salvarla...' WHERE `ID`=16019;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼!', `MaleText_loc4`='不！', `MaleText_loc5`='不!', `MaleText_loc7`='¡No!' WHERE `ID`=16020;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 거기 있구나. 일을 조용히 처리하고 싶었는데 어쩔 수 없이 정면대결을 해야겠군. 스랄, 네 미래는 여기서 끝이다. 그러니까 너와 네 성가신 친구들은 모두 죽어줘야겠다!', `MaleText_loc4`='啊，你来了。我原本希望以比较隐秘的方式解决问题，但是现在看来正面冲突是在所难免的了。你的命运之路在此终结，萨尔。你和你那些爱管闲事的朋友全都得死！', `MaleText_loc5`='噢，原來你在這。我原本想更巧妙地完成這件事，但是我想直接的衝突是無法避免的。索爾，你已經沒有未來了。因此...你跟你那些令人討厭的朋友必須死在這裡!', `MaleText_loc7`='Ah, ahí estás. Esperaba llevar a cabo esto con un poco de sutileza, pero supongo que la confrontación directa era inevitable. Tu futuro, Thrall, no debe llegar a materializarse. Así que... ¡tú y tus problemáticos amigos tienen que morir!' WHERE `ID`=16021;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가라다르에 온 것을 환영하네, 이방인이여. 쉴 곳을 찾고 있나?', `FemaleText_loc4`='欢迎来到加拉达尔，陌生人。你在找一处可以休息的地方吗？', `FemaleText_loc5`='歡迎來到卡拉達爾，陌生人。你找好休憩的地方了嗎?', `FemaleText_loc7`='$GBienvenido:bienvenida; a Garadar, $gforastero:forastera;. ¿Buscas un lugar donde descansar?' WHERE `ID`=16022;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 네 존재 자체를 지워주마!', `MaleText_loc4`='够了。我要把你们全部消灭！', `MaleText_loc5`='夠了。我將讓你從這個世界上消失!', `MaleText_loc7`='Ya basta. ¡Borraré tu existencia!' WHERE `ID`=16023;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 또 한 명의 주술사가 지혜를 구하고 있군요. 영혼들의 말이 분명하게 들리지 않나요? 운명을 점쳐 드릴까요?', `MaleText_loc4`='啊……另一位寻求启迪的萨满祭司，我说得对吗？灵魂们说得不够清楚吗？你要我帮你指明命运之路的方向吗？', `MaleText_loc5`='啊... 又一個在尋找啟發的薩滿嗎，或許吧?是不是精靈講得不清楚?你希望藉由我的幫助以看見什麼在你未來嗎?', `MaleText_loc7`='Ah... ¿Otro chamán que busca la iluminación? ¿Acaso los espíritus no hablan claro? ¿Quieres que te ayude a ver lo que te espera en tu camino?' WHERE `ID`=16024;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 지혜를 찾아 이곳에 오는 주술사들을 안내하는 스칼테쉬라고 합니다... 하지만 다른 길을 걷는 자들에게도 한두 가지 정도는 보여줄 수 있습니다. 알아보고 싶으신가요?', `MaleText_loc4`='我是斯卡泰斯，在这里引领萨满祭司寻求启迪……但即使信念不同者也可以在这里得到指引。你想看看吗？', `MaleText_loc5`='我是史卡帝斯，在這指導尋找啟發的薩滿...但是甚至那些走向不同道路的那些人也可以獲知一，兩件事情。你希望看見嗎?', `MaleText_loc7`='Soy Skaltesh, guía de los chamanes que buscan la iluminación... pero incluso aquellos que siguen diferentes caminos, pueden aprender un par de cosas. ¿Deseas ver?' WHERE `ID`=16025;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알려주십시오, 스칼테쉬.', `MaleText_loc4`='我想，先知。', `MaleText_loc5`='指引我，先知。', `MaleText_loc7`='Muéstramelo, vidente.', `FemaleText_loc1`='알려주십시오, 스칼테쉬.', `FemaleText_loc4`='我想，先知。', `FemaleText_loc5`='指引我，先知。', `FemaleText_loc7`='Muéstramelo, vidente.' WHERE `ID`=16026;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 병에 든 약을 마시면 잠시 동안 보이지 않게 깔린 안개가 사라질 것입니다. 영혼들이 함께하기를.', `MaleText_loc4`='喝下这瓶东西，迷雾就会消失一段时间。和灵魂们一起去吧，我的朋友。', `MaleText_loc5`='喝了這個藥水瓶的藥水，迷霧就會被散開一段時間。與精靈同去，我的朋友。', `MaleText_loc7`='Bebe de este vial y la niebla se disipará durante un rato. Ve con los espíritus, $gamigo:amiga;.' WHERE `ID`=16027;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 도시에서 가장 뛰어난 요리사인 실란을 만나려면 나그네의 쉼터 위층으로 가보십시오. 그녀의 조수에게서 요리 재료를 구입할 수도 있습니다.', `MaleText_loc4`='塞莱恩是城里最好的厨师之一，你可以在旅者的梦乡旅店的楼上找到她。你同样可以从她的助手那儿买到烹调用品。', `MaleText_loc5`='賽藍恩，城市裡最好的廚師之一，可以在旅人休憩小酒館的樓上發現他。你也能從她的助手那裡購買烹飪用具。', `MaleText_loc7`='En la Taberna del Descanso del Caminante puedes encontrar a Sylann, uno de los mejores cocineros de la ciudad. Allí también puedes comprarle avituallamientos de cocina a su asistente.', `FemaleText_loc1`='이 도시에서 가장 뛰어난 요리사인 실란을 만나려면 나그네의 쉼터 위층으로 가보십시오. 그녀의 조수에게서 요리 재료를 구입할 수도 있습니다.', `FemaleText_loc4`='塞莱恩是城里最好的厨师之一，你可以在旅者的梦乡旅店的楼上找到她。你同样可以从她的助手那儿买到烹调用品。', `FemaleText_loc5`='賽藍恩，城市裡最好的廚師之一，可以在旅人休憩小酒館的樓上發現他。你也能從她的助手那裡購買烹飪用具。', `FemaleText_loc7`='En la Taberna del Descanso del Caminante puedes encontrar a Sylann, uno de los mejores cocineros de la ciudad. Allí también puedes comprarle avituallamientos de cocina a su asistente.' WHERE `ID`=16028;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요리', `MaleText_loc4`='烹饪', `MaleText_loc5`='烹飪', `MaleText_loc7`='Cocina', `FemaleText_loc1`='요리', `FemaleText_loc4`='烹饪', `FemaleText_loc5`='烹飪', `FemaleText_loc7`='Cocina' WHERE `ID`=16029;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겨울 할아버지는 겨울맞이 축제 기간 동안 아이언포지의 나무 아래에 모든 사람들을 위한 선물을 놓아두십니다!', `MaleText_loc4`='冬幕节期间，冬天爷爷在铁炉堡的树下给每个人都留下了玩具。', `MaleText_loc5`='冬天爺爺在冬幕節日的盛宴期間，會在鐵爐堡的樹下為每個人留下玩具!', `MaleText_loc7`='¡El Gran Padre Invierno deja juguetes para todos bajo el árbol de Forjaz durante el festín del Festival de Invierno!', `FemaleText_loc1`='겨울 할아버지는 겨울맞이 축제 기간 동안 아이언포지의 나무 아래에 모든 사람들을 위한 선물을 놓아두십니다!', `FemaleText_loc4`='在冬幕节期间，冬天爷爷在铁炉堡的树下给每个人都留下了玩具。', `FemaleText_loc5`='冬天爺爺在冬幕節日的盛宴期間，會在鐵爐堡的樹下為每個人留下玩具!', `FemaleText_loc7`='¡El Gran Padre Invierno deja juguetes para todos bajo el árbol de Forjaz durante el festín del Festival de Invierno!' WHERE `ID`=16031;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지하철을 타고 아이언포지로 가서 겨울 할아버지를 만나야 합니다.', `MaleText_loc4`='我应该坐地铁去铁炉堡看看冬天爷爷。', `MaleText_loc5`='我應該搭乘電車到鐵爐堡，並且拜訪冬天爺爺。', `MaleText_loc7`='Debería coger el tren a Forjaz y hacerle una visita al Gran Padre Invierno.', `FemaleText_loc1`='지하철을 타고 아이언포지로 가서 겨울 할아버지를 만나야 해요.', `FemaleText_loc4`='我应该坐地铁去铁炉堡看看冬天爷爷。', `FemaleText_loc5`='我應該搭乘電車到鐵爐堡，並且拜訪冬天爺爺。', `FemaleText_loc7`='Debería coger el tren a Forjaz y hacerle una visita al Gran Padre Invierno.' WHERE `ID`=16032;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='블러드 엘프들이 수년 만에 처음으로 그들의 숲에서 활동을 시작했다고 합니다. 하지만 그게 호드에 들어오기 위한 것일까요? 그럴 리가 없습니다. 그렇지 않습니까?', `MaleText_loc4`='他们说精灵们这么多年来是第一次从森林里走了出来。而且是去加入部落？那不是真的，对吗？', `MaleText_loc5`='他們說那些精靈們是數年來第一次離開他們的森林。但是去加入部落?它不能是真的，對吧?', `MaleText_loc7`='Dicen que los elfos han salido de sus bosque por primera vez en muchos años. Pero de ahí a unirse a la Horda... No puede ser cierto,¿no?', `FemaleText_loc1`='엘프들이 수년 만에 처음으로 그들의 숲에서 활동을 시작했다고 합니다. 하지만 그게 호드에 들어오기 위한 것일까요? 그럴 리가 없습니다. 그렇지 않습니까?', `FemaleText_loc4`='他们说精灵们这么多年来是第一次从森林里走了出来。而且是去加入部落？那不是真的，对吗？', `FemaleText_loc5`='他們說那些精靈們是數年來第一次離開他們的森林。但是去加入部落?它不能是真的，對吧?', `FemaleText_loc7`='Dicen que los elfos han salido de sus bosque por primera vez en muchos años. Pero de ahí a unirse a la Horda... No puede ser cierto,¿no?' WHERE `ID`=16033;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='Human Gossip NPC - Periodic Talk (Expansion Prologue) 01', `MaleText_loc4`='Human Gossip NPC - Periodic Talk (Expansion Prologue) 01', `MaleText_loc5`='Human Gossip NPC - Periodic Talk (Expansion Prologue) 01', `MaleText_loc7`='PNJ humano cotilla - Charla periódica (prólogo de la expansión) 01', `FemaleText_loc1`='Human Gossip NPC - Periodic Talk (Expansion Prologue) 01', `FemaleText_loc4`='Human Gossip NPC - Periodic Talk (Expansion Prologue) 01', `FemaleText_loc5`='Human Gossip NPC - Periodic Talk (Expansion Prologue) 01', `FemaleText_loc7`='PNJ humano cotilla - Charla periódica (prólogo de la expansión) 01' WHERE `ID`=16034;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 바쁘게 일하는 게 안 보입니까?', `MaleText_loc4`='你没看到我现在很忙吗？', `MaleText_loc5`='你沒看到我在這裡忙嗎?', `MaleText_loc7`='¿No ves que estoy ocupado?', `FemaleText_loc1`='지금 바쁘게 일하는 게 안 보이세요?', `FemaleText_loc4`='你没看到我现在很忙吗？', `FemaleText_loc5`='你沒看到我在這裡忙嗎?', `FemaleText_loc7`='¿No ves que estoy ocupado?' WHERE `ID`=16035;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네? 무얼 원하시죠?', `MaleText_loc4`='嗯？你要做什么？', `MaleText_loc5`='嗯?你找我有什麼事?', `MaleText_loc7`='¿Sí? ¿Qué quieres?', `FemaleText_loc1`='네? 무얼 원하시죠?', `FemaleText_loc4`='嗯？你要做什么？', `FemaleText_loc5`='嗯?你找我有什麼事?', `FemaleText_loc7`='¿Sí? ¿Qué quieres?' WHERE `ID`=16036;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일입니까?', `MaleText_loc4`='对了，你是……？', `MaleText_loc5`='你是?', `MaleText_loc7`='¿Y tú eres...?', `FemaleText_loc1`='무슨 일이죠?', `FemaleText_loc4`='对了，你是……？', `FemaleText_loc5`='你是?', `FemaleText_loc7`='¿Y tú eres...?' WHERE `ID`=16037;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 숲은 점점 더 위험해지고 있는데 제 누이 실란나는 아무것도 모르고 있습니다. 하지만 어찌 됐든 이 마차에 짐을 다 실으면 도시 성벽 안으로 들어갈 겁니다.$b$b가방이 필요 이상으로 많은 것 같으니 필요하시다면 제 가방을 사용하셔도 좋습니다.', `MaleText_loc4`='我天真烂漫的妹妹西尔兰娜对这林子里面的危险一无所知。但是不管怎么样，等我把货物装好了，我们就搬到城里去。$B$B我这里的包太多了，你不如拿几个去用吧。', `MaleText_loc5`='我的姐妹希麗安娜天真的不知這些樹林之增長中的危險。但是喜歡與否，當這些運貨馬車裝載完畢時我們將移往城牆內。$B$B看起來我這裡的袋子比我需要的還多。或許你能利用他們。', `MaleText_loc7`='Mi hermana Silanna es muy ingenua, no entiende el peligro creciente que habita en estos bosques. Pero de todas formas, en cuanto cargue el carro, nos vamos a la ciudad. $b$bParece ser que tengo más bolsas de las que necesito. Quizás a ti te vengan bien.' WHERE `ID`=16039;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$r|1이여;여;, 얘기나 하고 있을 시간이 없다네. 자네가 이 광산의 문제를 도와줄 생각이 없다면 말이야.', `MaleText_loc4`='我没有时间闲扯，$r。确切地说，除非你愿意帮我解决矿井里的麻烦。', `MaleText_loc5`='沒有太多時間交談，$r。除非你願意幫助我解決礦場的麻煩。', `MaleText_loc7`='No tengo mucho tiempo para hablar, $r. A menos que quieras ayudarme con un problemilla que tengo.' WHERE `ID`=16040;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠시 이곳에 멈춰서 눈을 감아 보십시오. 바람의 흐름이 느껴지십니까?', `MaleText_loc4`='在这里停一会，我的孩子们，闭上眼睛。你们可以感觉到空气的流动吗？', `MaleText_loc5`='在這裡停一下，我的孩子，並且閉上你的眼睛。你能感覺到氣流嗎?', `MaleText_loc7`='Niños, deteneos un momento y cerrad los ojos. ¿Podéis sentir las corrientes de aire?' WHERE `ID`=16041;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='광산의 문제를 도와줘서 얼마나 고마운지 모르겠네. 이제 광부들이 일터로 다시 돌아가도록 설득하는 일만 남았군그래.', `MaleText_loc4`='我不知道该怎么感谢你对我的帮助了。现在，唯一的问题就是说服那些矿工回来工作。', `MaleText_loc5`='你對礦山的幫助無法言謝。現在，只剩下說服這些礦工回去工作這事了。', `MaleText_loc7`='Te agradezco muchísimo tu ayuda con las minas. Ahora, solo hay que convencer a los mineros para que vuelvan al trabajo.' WHERE `ID`=16042;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두 명의 학생이 눈을 감고 고개를 숙입니다.', `MaleText_loc4`='这两位学生闭上了双眼，又低下了头。', `MaleText_loc5`='兩個學生閉上他們的眼睛並且低著頭。', `MaleText_loc7`='Los dos estudiantes cierran los ojos e inclinan la cabeza.', `FemaleText_loc1`='두 명의 학생이 눈을 감고 고개를 숙입니다.', `FemaleText_loc4`='这两位学生闭上了双眼，又低下了头。', `FemaleText_loc5`='兩個學生閉上他們的眼睛並且低著頭。', `FemaleText_loc7`='Los dos estudiantes cierran los ojos e inclinan la cabeza.' WHERE `ID`=16043;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희들의 세계는 파멸할 것이다, 어리석은 존재여! 너희들의 종말이 얼마 남지 않았다!', `MaleText_loc4`='凡人，受死吧！你的末日到了！', `MaleText_loc5`='你的世界將死去，凡人!你的毀滅現在即將到來!', `MaleText_loc7`='¡Su mundo está acabado, mortales! ¡Pronto llegará su fin!' WHERE `ID`=16044;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고개를 숙여라, 하찮은 벌레들이여! 너희들의 연약한 영웅 따위는 아무것도 아니다! 너희들의 구원자를 자처하는 녀석들은 우리의 첫 번째 제물이 될 것이다!', `MaleText_loc4`='逃吧，蠕虫们！你们软弱的英雄不值一提！你们的救星将会成为我们的开胃菜！', `MaleText_loc5`='畏縮吧，小蟲們!你們虛弱的英雄們沒有什麼!你的救星們將是我們的第一個享受!', `MaleText_loc7`='¡Tiemblen, gusanos! ¡Sus insignificantes héroes no serán más que un aperitivo para nosotros!' WHERE `ID`=16045;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아제로스는 너무 오랫동안 우리 그림자 아래 그 몸을 숨겨 왔느니! 이제 불타는 군단의 힘을 보여 주마. 절망을 맛보거라!', `MaleText_loc4`='艾泽拉斯已经在我们的阴影下畏缩得太久了！现在，感受燃烧的远征给你们带来的绝望吧！', `MaleText_loc5`='艾澤拉斯已經在我們的影子下畏縮太長的時間了!現在，感受燃燒軍團和絕望的力量吧!', `MaleText_loc7`='Azeroth lleva mucho tiempo sometido a nuestras sombras. ¡Temblad ante el poder de la Cruzada Ardiente! ¡Abandonad toda esperanza!' WHERE `ID`=16046;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 운명은 여기서 끝이다, 아제로스여! 내가 위상의 결정을 찾아내면 우리의 힘을 당해 내지 못할 것이다!', `MaleText_loc4`='艾泽拉斯的命运早已注定。我会找到那些碎片，我们的力量将无人可挡！', `MaleText_loc5`='你的命運已經決定了，艾澤拉斯!我將找到時間的裂片，然後你將在我們的力量之下倒下!', `MaleText_loc7`='¡Tu destino está escrito, Azeroth! ¡Encontraré los fragmentos de los Aspectos y entonces no podréis resistir ante nuestro poder!' WHERE `ID`=16047;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 이곳은 고통의 맛을 보게 해 줄 가치도 없구나!', `MaleText_loc4`='哈哈！这里还不值得我亲自出马！', `MaleText_loc5`='哈!這個地方還不值得我打擊!', `MaleText_loc7`='¡Ja! ¡Este lugar ni siquiera es digno de ser arrasado!' WHERE `ID`=16048;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='풀어 주셔서 감사합니다, $n! 저는 샤트라스에 있는 오빠에게 가겠습니다!', `MaleText_loc4`='谢谢你解救了我，$n！我马上就回沙塔斯城去！', `MaleText_loc5`='謝謝你釋放我，$n!我將要前往撒塔斯!', `MaleText_loc7`='¡Gracias por liberarme, $n! ¡Me voy a Shattrath!' WHERE `ID`=16049;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 선생님.', `MaleText_loc4`='是的，老师。', `MaleText_loc5`='好的，老師。', `MaleText_loc7`='Sí, maestro.' WHERE `ID`=16050;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<한숨을 쉬는 이스파르>$B$B나무 위에 지은 건축물 중에는 살기에 적합하지 않은 곳도 있습니다만, 세데크 전당 전체로 볼 때는 상당히 발전한 모습입니다.$B$B예전 샤트라스에 있었던 것처럼 편안하게 스케티스에 있는 내 진짜 집에 내 여동생과 함께 돌아가지 못합니다. 내 여동생은 우리의 오랜 형제들이 죄인을 관리하는 세데크 전당에 아직도 묶여 있어서 말입니다.', `MaleText_loc4`='<伊斯法尔叹了口气。>$B$B几间树屋还算不上是家，但是这已经比塞泰克大厅好多了。$B$B就算和在沙塔斯城一样舒适，我也不会丢下我的妹妹一个人回到老家斯克提斯去。她被我们的长兄抓走了，被困在塞泰克大厅里。', `MaleText_loc5`='<伊斯法嘆氣。>$B$B一堆樹上小屋不算是一個家，但卻是比塞司克大廳有過之而無不及。$B$B如同在撒塔斯般的舒服，我不能在沒有我的妹妹的情況下回去我真實的家司凱堤斯。她仍然被困在塞司克大廳裡，被我們的哥哥作為囚犯。', `MaleText_loc7`='<Isfar suspira.>$B$BUn par de casas en los árboles no hacen un hogar, pero ha sido una gran mejora en las Salas Sethekk.$B$BAunque en Shattrath estaba perfectamente bien, no soy capaz de regresar a mi verdadero hogar en Skettis sin mi hermana. Está atrapada en las Salas Sethekk. La tiene prisionera nuestro hermano mayor.' WHERE `ID`=16051;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$r|1이여;여;, 제발 여기서 나가게 해 주세요! 이 철창을 열면 분명히 제 오라버니의 관심을 끌 겁니다. 그러면 흑마술사 시스 오라버니를 처치해 주세요.', `MaleText_loc4`='$r，请带我逃走吧！打开笼子就会引起我哥哥的注意。杀掉黑暗编织者塞斯！', `MaleText_loc5`='拜託，$r，救我出去!打開籠子的鎖肯定將引起我的兄弟的注意。殺死暗織者希斯!', `MaleText_loc7`='¡Por favor, $r, sácame de aquí! Abrir la jaula atraerá la atención de mi hermano. ¡Mata a Tejeoscuro Syth!' WHERE `ID`=16052;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금이 기회입니다! 절 이 우리에서 꺼내주십시오!', `MaleText_loc4`='我们的机会来了！让我出去！', `MaleText_loc5`='現在是我們的機會!把我從這只籠中放出!', `MaleText_loc7`='¡Ahora es nuestra oportunidad! ¡Sácame de aquí!' WHERE `ID`=16053;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나오게 해드릴 테니 잠시만 기다리십시오.', `MaleText_loc4`='我马上带你离开这里。', `MaleText_loc5`='我很快就會幫你脫離那裡了。', `MaleText_loc7`='Te sacaré de ahí en un segundo.', `FemaleText_loc1`='나오게 해드릴 테니 잠시만 기다리세요.', `FemaleText_loc4`='我马上带你离开这里。', `FemaleText_loc5`='我很快就會幫你脫離那裡了。', `FemaleText_loc7`='Te sacaré de ahí en un segundo.' WHERE `ID`=16054;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바람의 정령은 이곳 지하에도 있습니다. 그들은 흙으로 둘러싸여 있는 갑갑한 곳을 싫어합니다... 어디로든 갈 수 있는 그들의 특별한 자유가 제한되기 때문이지요.', `MaleText_loc4`='你可以在地下或是这里找到空气之灵。它们讨厌被大地环抱和挤压，它们宝贵的自由在这里受到了局限。', `MaleText_loc5`='空氣精靈甚至在這裡，地底，也可能被發現。他們不喜歡被包圍著，被大地限制著...他們寶貴的自由在這裡是有限的。', `MaleText_loc7`='Los espíritus del aire también pueden encontrarse aquí, bajo tierra. No les gusta estar rodeados, constreñidos por la tierra... Su preciada libertad está limitada aquí abajo.' WHERE `ID`=16055;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘하셨어요! 하지만, 붙잡히지 않으려면 서둘러야 합니다!', `MaleText_loc4`='干得好！快一点，我们不想被抓住！', `MaleText_loc5`='做得好!不過，趕快，我們可不想被抓住!', `MaleText_loc7`='¡Bien hecho! Rápido, no queremos que nos atrapen.' WHERE `ID`=16056;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바람의 정령들은 변덕스럽고 산만하지만... 자신의 말을 들을 수 있는 자들과는 비밀을 공유할 겁니다.', `MaleText_loc4`='它们反复无常，而且很容易受到干扰……但是它们会向倾听者分享心中的秘密。', `MaleText_loc5`='他們非常古怪，這些精靈們，和容易被干擾...但是他們會與那些知道如何聆聽的人分享他們的秘密。', `MaleText_loc7`='Estos espíritus son muy combativos y se distraen fácilmente... pero comparten sus secretos con aquellos que saben escuchar.' WHERE `ID`=16057;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='버림받은 엘프들을 처리하는 데 문제가 있으신가요? 저에게 당신에게 필요한 것이 있답니다.', `MaleText_loc4`='和那些失心者打交道遇到什么麻烦了吗？我这里有你想要的东西。', `MaleText_loc5`='對付鄙惡者有困難嗎?我正好有你所需要的東西。', `MaleText_loc7`='¿Problemas con los desdichados? Tengo justo lo que necesitas.', `FemaleText_loc1`='버림받은 엘프들을 처리하는 데 문제가 있으신가요? 저에게 당신에게 필요한 것이 있답니다.', `FemaleText_loc4`='和那些失心者打交道遇到什么麻烦了吗？我这里有你想要的东西。', `FemaleText_loc5`='對付鄙惡者有困難嗎?我正好有你所需要的東西。', `FemaleText_loc7`='¿Problemas con los desdichados? Tengo justo lo que necesitas.' WHERE `ID`=16058;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디서 났는지는 묻지 마세요...', `MaleText_loc4`='不要问它从哪里来……它的故乡在……', `MaleText_loc5`='別我問是從哪裡弄來的...', `MaleText_loc7`='Pero no me preguntes dónde lo he conseguido...', `FemaleText_loc1`='어디서 났는지는 묻지 마세요...', `FemaleText_loc4`='不要问它从哪里来……它的故乡在……', `FemaleText_loc5`='別我問是從哪裡弄來的...', `FemaleText_loc7`='Pero no me preguntes dónde lo he conseguido...' WHERE `ID`=16059;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='집중한 채 안절부절 못하는 학생을 보고 %s|1이;가; 미소를 짓습니다.', `MaleText_loc4`='%s看着他的学生坐立不安，微微笑了笑。', `MaleText_loc5`='%s對他自己微笑，當他看著學生在專注中坐立不安。', `MaleText_loc7`='%s sonríe mientras observa a los estudiantes concentrados y nerviosos.', `FemaleText_loc1`='집중한 채 안절부절 못하는 학생을 보고 %s|1이;가; 미소를 짓습니다.', `FemaleText_loc4`='%s看着他的学生坐立不安，微微笑了笑。', `FemaleText_loc5`='%s對他自己微笑，當他看著學生在專注中坐立不安。', `FemaleText_loc7`='%s sonríe mientras observa a los estudiantes concentrados y nerviosos.' WHERE `ID`=16060;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이리 오십시오. 바람의 정령 말고도 공부할 것이 많습니다.', `MaleText_loc4`='过来。比起风中的秘密，我们还有更多的东西需要学习。', `MaleText_loc5`='來。除了風的秘密以外，還有更多需要學習的。', `MaleText_loc7`='Vamos. Hay más cosas que estudiar aparte de los secretos del viento.' WHERE `ID`=16061;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='킬소로우의 성벽이 너의 피로 물들게 될 것이다!', `FemaleText_loc4`='你的鲜血将会涂满基尔索罗的围墙！', `FemaleText_loc5`='你的血將塗滿吉爾索洛的牆!', `FemaleText_loc7`='¡Su sangre cubrirá los muros de Mata’penas!' WHERE `ID`=16062;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시험의 투기장은 한때 매우 영광스럽고 명예로운 곳이었네. 하지만 그때 스팀휘들 무역회사가 도착했지. 황금과 오크의 도끼보다 날카로운 깃펜을 가득 실은 마차와 함께...', `MaleText_loc4`='试炼竞技场曾经是个满是荣耀的地方。不过，热砂港集团的出现，带来了成车的黄金和比兽人的斧子更硬的羽毛笔……', `MaleText_loc5`='試煉競技場曾經是偉大光榮和榮譽的地方。後來，熱砂企業的哥布林們來了，帶著許多裝滿黃金的馬車和比任何獸人斧還鋒利的鵝毛筆...', `MaleText_loc7`='El Círculo de los Retos era antaño un lugar de honor y gloria. Pero entonces llegó el Cártel Bonvapor con sus carros llenos de oro y sus plumas más afiladas que hachas de orco...' WHERE `ID`=16063;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세데크는 자신이 모든 아라코아 주인의 가장 진실하고 충성스러운 추종자들이라고 믿습니다. $r|1이여;여;, 그들의 주인에 대해서는 깃털이 달린 자들만을 위한 비밀이니 더는 묻지 마십시오.$B$B세데크는 아킨둔의 파괴를 우리의 주인이 이 행성에 도착한 것으로 해석했었지요. 그들은 우리의 가장 위대한 영웅 테로크의 유산을 가지고 폐허를 향해 떠났습니다.$B$B지금도 신전의 폐허에서 주인을 찾고 있습니다. 하지만 나는 그들이 거짓말을 하고 있다는 걸 알게 되었고 더는 그들의 일원이 아닙니다.', `MaleText_loc4`='塞泰克一族认为他们是所有鸦人中最忠诚于主人的信徒。不要多问关于主人的事，$R，只有鸦人才有资格了解他的神秘传说。$B$B塞泰克认为奥金顿的毁灭是主人到来的信号。他们带着我们最伟大的英雄泰罗克的圣物去了废墟。$B$B他们仍然在神殿的废墟中寻找主人，但是我看穿了他们的谎言。我不再和他们同流合污了。', `MaleText_loc5`='塞司克相信他們自己是所有阿拉卡主人最真和最忠誠的崇拜者。不要詢問關於主人的事情，$R，因為他的神秘只給予那些有羽毛的人的。$B$B塞司克解釋奧齊頓的崩潰是因為我們主人到達這顆行星上。他們準備出發去廢墟，帶著我們最偉大之英雄泰洛克的遺物。$B$B他們仍然在神廟的廢墟中尋找主人，但是我看穿了他們的謊話。我不再是他們其中的一個。', `MaleText_loc7`='Los Sethekk se creen los verdaderos y más fieles seguidores del maestro de todos los arakkoa. No me preguntes por el maestro, $r, porque sus misterios son solo para los alados.$B$BLos Sethekk interpretaron la destrucción de Auchindoun como la llegada de nuestro maestro a este planeta. Partieron hacia las ruinas llevándose las reliquias de nuestro gran héroe, Terokk.$B$BSiguen buscando al maestro en las ruinas del templo, pero he conseguido ver la verdad que se esconde tras sus mentiras. Ya no soy uno de ellos.' WHERE `ID`=16064;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 마지막으로 전당에 있었을 때 갈퀴대왕 이키스가 권력의 상징인 테로크의 깃창을 가져갔습니다.$B$B내 형제 흑마술사 시스는 우리의 의식이 진행되는 동안 테로크의 가면을 쓰고 있었습니다.$B$B테로크의 전설의 경우에는 정확하게 어디에 있는지 알아낼 방법은 없지만 보통 둥근 지붕의 대전당 안에 있는 룬 마법진 중 한 곳에 보관했습니다.', `MaleText_loc4`='当我还大厅中徘徊的时候，利爪之王艾吉斯随身携带着泰罗克的羽毛，把它作为他权力的象征。$B$B我的兄弟——黑暗编织者塞斯在我们的仪式上戴着泰罗克的面具。$B$B至于泰罗克的传说，我们不可能确切地知道它在哪里，但是他们通常把它放在大厅的某个符文法阵中间。', `MaleText_loc5`='當我在大廳時，鷹王伊奇斯帶著泰洛克羽毛，作為他權力的標誌。$B$B我的兄弟，暗織者希斯，在我們的儀式期間戴著泰洛克面罩。$B$B至於泰洛克的傳說，沒有辦法確切知道它在那裡，但是他們通常將它放在他們巨大拱頂大廳內的符文法陣中心。', `MaleText_loc7`='La última vez que estuve en las Salas, el Rey Garra Ikiss llevaba la pluma de Terokk con él, como símbolo de autoridad.$B$BMi hermano, Tejeoscuro Syth, llevó la máscara de Terokk durante nuestros rituales.$B$BY, con respecto a la saga de Terokk, no hay forma de saber exactamente dónde está, pero generalmente la tienen en el centro de uno de sus círculos de runas en las grandes salas selladas.' WHERE `ID`=16065;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='''갈퀴대왕'' 이키스는 내 형제 흑마술사 시스와 함께 세데크의 지도자 중 한 명입니다.$B$B스케티스에서 아킨둔의 폐허로 세데크의 대이동을 이끈 것이 바로 그들입니다. 이키스는 초창기에는 뛰어난 지도자였지만 점점 타락하여 미치광이가 되었습니다.$B$B현재 그는 자기가 테로크의 환생이라며 떠벌리고 다닙니다! 그는 아라코아들이 자기를 지도자로 인정하고 복종하기를 진심으로 바라고 있습니다. 그가 얼마나 거만한지 상상이 되십니까?', `MaleText_loc4`='利爪之王艾吉斯和我兄弟黑暗编织者塞斯一样，都是塞泰克的领导者之一。$B$B是他们带领塞泰克一族从斯克提斯来到了奥金顿废墟。最初，艾吉斯是一个有着超凡魅力的领袖，但是他陷入了疯狂。$B$B现在，他公然宣称他就是再生的泰罗克！他想让所有鸦人向他屈服，接受他的统治。你能相信他居然如此傲慢吗？', `MaleText_loc5`='『鷹王』伊奇斯與我的兄弟暗織者希斯都是塞司克的領導人。$B$B他們領導塞司克的人民，從司凱堤斯遷徙到奧齊頓的廢墟。最初，伊奇斯是一位有號召力的領導人，但是他已經幾近瘋狂。$B$B現在，他公開宣佈他是泰洛克再世!他真的期望阿拉卡人對他卑躬屈膝以作為他們的統治者。你能相信他的傲慢嗎?', `MaleText_loc7`='El Rey ''Garra Ikiss'' es uno de los líderes de los Sethekk, junto con mi hermano, Tejeoscuro Syth.$B$BFueron ellos quienes guiaron el éxodo de los Sethekk desde Skettis hasta las Ruinas de Auchindoun. Al principio, Ikiss era un líder carismático, pero la locura se ha apoderado de él.$B$B¡Ahora se proclama a sí mismo como la reencarnación de Terokk! Realmente espera que los arakkoa se arrodillen ante él como su verdadero gobernante. ¿Te puedes creer su arrogancia?' WHERE `ID`=16066;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갈퀴대왕 이키스란 자가 누구입니까?', `MaleText_loc4`='谁是利爪之王艾吉斯？', `MaleText_loc5`='誰是鷹王伊奇斯?', `MaleText_loc7`='¿Quién es el Rey Garra Ikiss?', `FemaleText_loc1`='갈퀴대왕 이키스란 자가 누구인가요?', `FemaleText_loc4`='谁是利爪之王艾吉斯？', `FemaleText_loc5`='誰是鷹王伊奇斯?', `FemaleText_loc7`='¿Quién es el Rey Garra Ikiss?' WHERE `ID`=16067;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세데크란 자가 누구입니까?', `MaleText_loc4`='谁是塞泰克？', `MaleText_loc5`='誰是塞司克?', `MaleText_loc7`='¿Quiénes son los Sethekk?', `FemaleText_loc1`='세데크란 자가 누구인가요?', `FemaleText_loc4`='谁是塞泰克？', `FemaleText_loc5`='誰是塞司克?', `FemaleText_loc7`='¿Quiénes son los Sethekk?' WHERE `ID`=16068;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='테로크의 유산은 어디에 있습니까?', `MaleText_loc4`='我在哪里可以找到泰罗克的圣物？', `MaleText_loc5`='我要去那找泰洛克的遺物?', `MaleText_loc7`='¿Dónde puedo encontrar las reliquias de Terokk?', `FemaleText_loc1`='테로크의 유산은 어디에 있나요?', `FemaleText_loc4`='我在哪里可以找到泰罗克的圣物？', `FemaleText_loc5`='我要去那找泰洛克的遺物?', `FemaleText_loc7`='¿Dónde puedo encontrar las reliquias de Terokk?' WHERE `ID`=16069;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 계속 언급하고 있는 테로크란 자는 누구입니까?', `MaleText_loc4`='谁是这个你一直提起的泰罗克？', `MaleText_loc5`='你一直提到的泰洛克是誰呀?', `MaleText_loc7`='¿Quién es ese Terokk del que tanto hablas?', `FemaleText_loc1`='당신이 계속 언급하고 있는 테로크란 자는 누구인가요?', `FemaleText_loc4`='谁是这个你一直提起的泰罗克？', `FemaleText_loc5`='你一直提到的泰洛克是誰呀?', `FemaleText_loc7`='¿Quién es ese Terokk del que tanto hablas?' WHERE `ID`=16070;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그는 아라코아에게 알려진 자들 중에 가장 위대한 영웅이십니다.$B$B고대 시절엔 그가 자신의 발톱으로 스케티스를 건설했다고 전해집니다. 그는 우리의 가장 위대한 용사이자 수호자입니다. 하지만 우리가 루크마르를 존경하지 않자 우리를 떠났습니다.$B$B그래서 우리는 엄청난 힘과 우주에서의 지위를 약속한 새로운 주인을 숭배했지요.$B$B일부에서는 테로크와 루크마르가 같은 인물이라고 말하기도 합니다. 우리가 그에게 등을 돌리자 그는 모습을 감추었습니다.', `MaleText_loc4`='他是鸦人有史以来最伟大的英雄。$B$B据说在远古时代，他用自己的爪子建造了斯克提斯。他是我们最伟大的勇士和守护者，但当我们开始放弃对鲁克玛的崇拜时，他离开了我们。$B$B我们开始崇拜一个承诺给我们无尽力量的新主人。$B$B有人说泰罗卡和鲁克玛是同一个人，所以他在我们背弃他的时候离开了我们。', `MaleText_loc5`='他曾經是阿拉卡最偉大的英雄。$B$B傳說在古代，他用他自己的爪子建造司凱堤斯城。他是我們最偉大的勇士和防衛者，但是當我們捨棄了對魯克馬爾的尊敬感時，他離開了我們。$B$B我們來信奉一位新的主人，一個將宇宙裡未知的力量和地位許諾給我們的人。$B$B有些人說泰洛克和魯克馬爾是同一個人，並且當我們對他遠離時，他從我們這裡消失了。', `MaleText_loc7`='Es el héroe más glorioso entre los arakkoa.$B$BDicen que, en la antigüedad, construyó Skettis con sus propias garras. Era nuestro mayor campeón y defensor, pero nos dejó cuando dejamos de venerar a Rukhmar.$B$BEmpezamos a adorar a un nuevo maestro, uno que nos prometió increíble poder y estatus en el cosmos.$B$BAlgunos dicen que Terokk y Rukhmar son uno y que nos abandonó cuando nosotros le abandonamos a él.' WHERE `ID`=16071;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오게, 어서 와. 얼마 전에 멋지고 적절한 이름으로 바뀐 스팀휘들 경기장에 온 것을 환영하네!', `MaleText_loc4`='欢迎，欢迎来到最近刚刚改名的热砂竞技场！', `MaleText_loc5`='歡迎，歡迎，歡迎來到最近重新正名的熱砂競技場!', `MaleText_loc7`='¡Bienvenidos, bienvenidos al reciente y apropiadamente renombrado Estadio Bonvapor!' WHERE `ID`=16072;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에서 따뜻한 기운이 느껴집니까?', `MaleText_loc4`='你能感受到这里的温暖吗，我的孩子们？', `MaleText_loc5`='你在這能感覺溫暖嗎，我的孩子?', `MaleText_loc7`='¿Podéis sentir el calor, niños?' WHERE `ID`=16073;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='학생들은 천천히 고개를 끄덕이며 선생님을 바라봅니다.', `MaleText_loc4`='学生们缓慢地点了点头，全神贯注地看着他们的老师。', `MaleText_loc5`='那些學生緩慢地點頭，並全神貫注在他們的教師身上。', `MaleText_loc7`='Los estudiantes asienten lentamente con los ojos fijados en su maestro.', `FemaleText_loc1`='학생들은 천천히 고개를 끄덕이며 선생님을 바라봅니다.', `FemaleText_loc4`='学生们缓慢地点了点头，全神贯注地看着他们的老师。', `FemaleText_loc5`='那些學生緩慢地點頭，並全神貫注在他們的教師身上。', `FemaleText_loc7`='Los estudiantes asienten lentamente con los ojos fijados en su maestro.' WHERE `ID`=16074;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 말하는 따뜻한 기운에 집중하십시오...', `MaleText_loc4`='注意我所提到的温暖一词……', `MaleText_loc5`='當我講話時，將注意力集中在那溫度...', `MaleText_loc7`='Concéntrate en el calor mientras hablo...' WHERE `ID`=16075;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불의 힘은 변화합니다. 불의 힘은 매우 강력하지만 끊임없이 변해서... 예측할 수가 없지요.', `MaleText_loc4`='火是多变的。它的力量相当大，但是它永远在变……不可预知。', `MaleText_loc5`='火的力量在於變化。它的力量是相當強的，但是不斷變換...無法預知。', `MaleText_loc7`='La fuerza del fuego está en el cambio. La fuerza es importante, pero siempre cambia... Es impredecible.' WHERE `ID`=16076;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이것은 정령 자신들에게도 해당되는 것입니다. 그들은 화를 잘 냅니다. 그들의 급한 성미에 넘어가지 않고 듣는 방법을 배우는 것이 중요하답니다.', `MaleText_loc4`='关于自然之灵，它们是很容易被激怒的。你们要学会在不惹怒它们的情况下去聆听，这一点非常重要。', `MaleText_loc5`='這延伸到精靈他們本身。他們通常很容易就會憤怒;學習如何在不受到他們脾氣的影響之下聆聽他們的聲音是很重要的。', `MaleText_loc7`='Esto se extiende a los espíritus. A menudo se enfadan rápidamente. Es importante aprender a escuchar sin ser víctima de su temperamento.' WHERE `ID`=16077;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 정도면 충분합니다. 이리 오십시오.', `MaleText_loc4`='先说到这里吧，来。', `MaleText_loc5`='現在這樣就夠了。來吧。', `MaleText_loc7`='Ya basta por ahora. Vamos.' WHERE `ID`=16078;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳의 물은 평화롭지 않습니까? 천장에서 떨어지는 물방울 소리를 들어 보면 물의 정령의 진정한 목소리를 들을 수 있답니다...', `MaleText_loc4`='这里的水很平静，是不是？倾听水滴从屋檐落下的声音，那就是它们真正的语言。', `MaleText_loc5`='這裡的水是平靜的，不是嗎?聆聽水流從天花板上的滴淌能幫助你找到它真實的聲音...', `MaleText_loc7`='El agua aquí está tranquila, ¿verdad? Escuchar cómo caen las gotas del techo puede ayudarte a encontrar su voz verdadera...' WHERE `ID`=16079;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물의 정령들이 아마도 가장 솔직할 것입니다. 그들은 마음이 넓고 이해심이 깊지요. 정말로 정령들의 목소리가 들리지 않는다면 물의 소리부터 들어 보십시오.', `MaleText_loc4`='水流之灵是最坦率的。它们非常慷慨，并且善解人意。事实上，如果你听不到它们的声音，那么你就应该开始学习与水沟通。', `MaleText_loc5`='水靈或許是最直言不諱的。他們慷慨並且善解人意。的確，如果你無法聽到聲音的話，那你應該從水開始。', `MaleText_loc7`='Los espíritus del agua son, quizás, los más francos. Son generosos y comprensivos. Si se tienen problemas para escuchar las voces, se debe comenzar con el agua.' WHERE `ID`=16080;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제자들이여, 눈을 감고 이 전당 안에서 들리는 물소리에 귀를 기울여 보십시오.', `MaleText_loc4`='闭上你的眼睛，孩子们。聆听大厅内的潺潺水声。', `MaleText_loc5`='閉上你的眼睛，我的孩子，並且聽聽在這些大廳裡的水。', `MaleText_loc7`='Cerrad los ojos, niños, y escuchad el agua que habita en estas paredes.' WHERE `ID`=16081;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='드디어 자유로군요! 모두 고마워요!', `FemaleText_loc4`='我自由了！感谢你们！', `FemaleText_loc5`='我自由了!謝謝你們!', `FemaleText_loc7`='¡Soy libre! Gracias a todos.' WHERE `ID`=16082;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무사해서 다행이오, 타레사. 그대의 친구들이 없었다면 이번 일은 불가능했을 것이오. 모두 이들 덕분이오.', `MaleText_loc4`='我很高兴你安全了，塔蕾莎。要是没有你的朋友们的帮助，这一切是不可能发生的。', `MaleText_loc5`='我很高興你安全了，塔蕾莎。如果沒有妳的朋友，這一切的一切都不可能發生。他們讓所有的事實現了。', `MaleText_loc7`='Me alegro de que estés bien, Taretha. Nada de esto habría sido posible sin tus amigos. Han hecho que esto pasara.' WHERE `ID`=16083;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐라고? 그럼 이들은 대체 누구란 말이오?', `MaleText_loc4`='那么这些人是谁？', `MaleText_loc5`='這些人是誰?', `MaleText_loc7`='¿Quiénes son estos?' WHERE `ID`=16084;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='스랄, 저는 이분들을 뵌 적이 없어요.', `FemaleText_loc4`='萨尔，我以前从没有遇到过这些人。', `FemaleText_loc5`='索爾，我這一生從未見過這些人。', `FemaleText_loc7`='Thrall, no les había visto jamás.' WHERE `ID`=16085;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스랄 님과 타레사 님, 저에게 잠시만 시간을 내어 주시면 두 분에게 모든 걸 설명 드리겠습니다.', `MaleText_loc4`='如果你们给我一点时间的话，我想我可以向你们俩解释一切。', `MaleText_loc5`='如果你們給我一點時間，我相信，我能對你們兩解釋一切。', `MaleText_loc7`='Creo que puedo explicároslo todo si me dais un segundo.' WHERE `ID`=16086;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 저들에게 건 마법은 그들의 머릿속에서 우리에 대한 기억과 조금 전까지 있었던 일에 대한 기억을 지워버릴 것입니다. 그들은 우리가 시간을 거슬러 오지 않았던 현실만 기억하게 될 겁니다. 수고하셨습니다. 이제 스랄은 자신의 운명을 찾기 위해 모험을 떠날 것입니다... 그리고 타레사는...', `MaleText_loc4`='这个法术应该可以清除他们对我们和刚才所发生的事情的记忆。他们现在所要记住的是没有被干涉过的历史。干得好，萨尔会继续旅行以找寻他的命运，至于塔蕾莎……', `MaleText_loc5`='那法術應該已抹滅他們對我們和剛剛發生的事的記憶。他們現在只會記得的只會是看起來沒有被短暫干擾的現實。做得好。 索爾將繼續尋找他的命運，而塔蕾莎...', `MaleText_loc7`='El hechizo debería borrar su memoria de nosotros y de lo ocurrido. Todo lo que pueden recordar ahora es la realidad que sería sin el intento de interferencia temporal. Bien hecho. Thrall viajará para encontrar su destino, y a Taretha...' WHERE `ID`=16087;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='유감스럽지만 그녀도 운명을 피할 수는 없습니다.', `MaleText_loc4`='很遗憾，她的命运是不可避免的。', `MaleText_loc5`='她令人遺憾的命運是不可避免的。', `MaleText_loc7`='Su destino es, lamentablemente, inevitable.' WHERE `ID`=16088;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타레사, 잘 있으시오. 당신의 호의는 결코 잊지 않겠소.', `MaleText_loc4`='再见，塔蕾莎。我永远不会忘记你的善良。', `MaleText_loc5`='再見了，塔蕾莎。我永遠不會忘記你的恩情。', `MaleText_loc7`='Adiós, Taretha. Jamás olvidaré tu bondad.' WHERE `ID`=16089;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그들은 당신을 괴물이라고 부르지요. 하지만 괴물은 당신이 아니라 바로 그들이랍니다. 잘 가세요, 스랄 님.', `FemaleText_loc4`='他们称你为怪物，但他们才是真正的怪物，你不是。保重，萨尔。', `FemaleText_loc5`='他們稱呼你為一個怪物。但是他們才是怪物，並非你。再會了，索爾。', `FemaleText_loc7`='Te llaman monstruo. Pero ellos son los monstruos, no tú. Adiós, Thrall.' WHERE `ID`=16090;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 버림받은 엘프들에게 어떤 조치든 취해야 합니다...', `MaleText_loc4`='必须对这些失心者采取行动了……', `MaleText_loc5`='這些鄙惡者的事情一定處理...', `MaleText_loc7`='Hay que hacer algo con los desdichados...', `FemaleText_loc1`='저 버림받은 엘프들에게 어떤 조치든 취해야 합니다...', `FemaleText_loc4`='必须对这些失心者采取行动了……', `FemaleText_loc5`='這些鄙惡者的事情一定處理...', `FemaleText_loc7`='Hay que hacer algo con los desdichados...' WHERE `ID`=16091;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='버림받은 엘프들의 문제가 해결되면 우리는 더 많은 자원을 전쟁 준비에 투입할 수 있습니다.', `MaleText_loc4`='等他们被解决了，我们就可以为战争提供更多的资源。', `MaleText_loc5`='一旦他們被處理掉，我們就能把更多的資源獻給戰爭所需。', `MaleText_loc7`='En cuanto nos hayamos ocupado de ellos, podremos seguir trabajando por la campaña.', `FemaleText_loc1`='버림받은 엘프들의 문제가 해결되면 우리는 더 많은 자원을 전쟁 준비에 투입할 수 있습니다.', `FemaleText_loc4`='等他们被解决了，我们就可以为战争提供更多的资源。', `FemaleText_loc5`='一旦他們被處理掉，我們就能把更多的資源獻給戰爭所需。', `FemaleText_loc7`='En cuanto nos hayamos ocupado de ellos, podremos seguir trabajando por la campaña.' WHERE `ID`=16092;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='치즈와 함께 먹을 포도주가 있다면 얼마나 좋을까...', `MaleText_loc4`='如果有酒就着奶酪吃该有多好啊……', `MaleText_loc5`='如果我有一些酒與我的乳酪相配...', `MaleText_loc7`='Si tuviese algo de vino para acompañar al queso...', `FemaleText_loc1`='치즈와 함께 먹을 포도주가 있다면 얼마나 좋을까...', `FemaleText_loc4`='如果有酒就着奶酪吃该有多好啊……', `FemaleText_loc5`='如果我有一些酒與我的乳酪相配...', `FemaleText_loc7`='Si tuviese algo de vino para acompañar al queso...' WHERE `ID`=16093;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으, 정말 따분하기 짝이 없는 장사네요!', `MaleText_loc4`='啊……多么可怕的工作啊！', `MaleText_loc5`='哦...真是令人討厭的工作!', `MaleText_loc7`='¡Ooh, qué trabajo más espantoso!', `FemaleText_loc1`='으, 정말 따분하기 짝이 없는 장사네요!', `FemaleText_loc4`='啊……多么可怕的工作啊！', `FemaleText_loc5`='哦...真是令人討厭的工作!', `FemaleText_loc7`='¡Ooh, qué trabajo más espantoso!' WHERE `ID`=16094;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하루종일 끔찍한 발 냄새에 시달리는군.', `MaleText_loc4`='整天，都沉浸在脚臭味中……', `MaleText_loc5`='整天，被臭腳的惡臭所包圍。', `MaleText_loc7`='Todo el día rodeado de hedor de pies.', `FemaleText_loc1`='하루종일 끔찍한 발 냄새에 시달리는군.', `FemaleText_loc4`='整天，都沉浸在脚臭味中……', `FemaleText_loc5`='整天，被臭腳的惡臭所包圍。', `FemaleText_loc7`='Todo el día rodeada de hedor de pies.' WHERE `ID`=16095;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 이 지루한 시간이 훨씬 달콤하게 흘러갈 텐데...', `MaleText_loc4`='我们一起渡过的时光是如此的甜蜜。', `MaleText_loc5`='時間將會更加甜美地度過。', `MaleText_loc7`='Las horas pasarían mucho más rápidamente.', `FemaleText_loc1`='그럼 이 지루한 시간이 훨씬 달콤하게 흘러갈 텐데...', `FemaleText_loc4`='我们一起渡过的时光是如此的甜蜜。', `FemaleText_loc5`='時間將會更加甜美地度過。', `FemaleText_loc7`='Las horas pasarían mucho más rápidamente.' WHERE `ID`=16096;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 어머니는 다른 일을 선택할 수 없었을까?', `MaleText_loc4`='为什么母亲不能选择别的工作呢？', `MaleText_loc5`='母親為什麼不能選擇其它事情去奉獻她自己呢?', `MaleText_loc7`='¿Por qué madre no habrá elegido otra cosa a la que dedicarse?', `FemaleText_loc1`='왜 어머니는 다른 일을 선택할 수 없었을까?', `FemaleText_loc4`='为什么母亲不能选择别的工作呢？', `FemaleText_loc5`='母親為什麼不能選擇其它事情去奉獻她自己呢?', `FemaleText_loc7`='¿Por qué madre no habrá elegido otra cosa a la que dedicarse?' WHERE `ID`=16097;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='케이크, 패스트리, 거기에 빵까지... 치즈만 빼고 다 있군!', `MaleText_loc4`='蛋糕，馅饼，甚至是面包——除了奶酪什么都行！', `MaleText_loc5`='蛋糕，糕餅，甚至麵包 - 除了乳酪之外!', `MaleText_loc7`='Tartas, repostería, incluso pan... ¡Cualquier cosa menos queso!', `FemaleText_loc1`='케이크, 패스트리, 거기에 빵까지... 치즈만 빼고 다 있군!', `FemaleText_loc4`='蛋糕，馅饼，甚至是面包——除了奶酪什么都行！', `FemaleText_loc5`='蛋糕，糕餅，甚至麵包 - 除了乳酪之外!', `FemaleText_loc7`='Tartas, repostería, incluso pan... ¡Cualquier cosa menos queso!' WHERE `ID`=16098;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='젠장! 마차에 뭔가 싣고 나면 얼마 지나지 않아 다시 나타나다니!', `MaleText_loc4`='啊！每次我把什么东西装到马车里，它都会很快重新出现在这里！', `MaleText_loc5`='哎!每當我把東西放上馬車，昔日的景象歷歷在目!', `MaleText_loc7`='¡Bah! ¡Cada vez que cargo algo en el vagón, vuelve a aparecer en un instante!', `FemaleText_loc1`='젠장! 마차에 뭔가 싣고 나면 얼마 지나지 않아 다시 나타나다니!', `FemaleText_loc4`='啊！每次我把什么东西装到马车里，它都会很快重新出现在这里！', `FemaleText_loc5`='哎!每當我把東西放上馬車，昔日的景象歷歷在目!', `FemaleText_loc7`='¡Bah! ¡Cada vez que cargo algo en el vagón, vuelve a aparecer en un instante!' WHERE `ID`=16099;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누이가 그 주문 책자를 주기 전에 잘 알아봤어야 하는 건데...', `MaleText_loc4`='我根本不应该把那本法术书送给西尔兰娜。', `MaleText_loc5`='我應該比任何人都要清楚不該將咒語之書給希麗安娜 。', `MaleText_loc7`='No debería haberle dado a Silanna ese tomo de conjuros.', `FemaleText_loc1`='누이가 그 주문 책자를 주기 전에 잘 알아봤어야 하는 건데...', `FemaleText_loc4`='我根本不应该把那本法术书送给西尔兰娜。', `FemaleText_loc5`='我應該比任何人都要清楚不該將咒語之書給希麗安娜 。', `FemaleText_loc7`='No debería haberle dado a Silanna ese tomo de conjuros.' WHERE `ID`=16100;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='근육만 있고 뇌가 없는 자들, 그게 바로 일꾼들이지! 저들에게 동기를 유발한다면 일을 매우 잘하게 될 게야. 내 말이 무슨 뜻인지 이해했다면 그들을 발로 ''차야'' 할 것이네.', `MaleText_loc4`='苦工就是那样力大无脑！他们还是很听话的，不过必须在开始前被“踢几下”才行，我想你应该能明白我的意思。', `MaleText_loc5`='都是肌肉沒有大腦，那樣等於是苦工!當你能激勵他們的時候，他們是偉大的，但他們必須被「踢」動，你知道我的意思吧。', `MaleText_loc7`='¡Mucho brazo y poco seso! Así son los peones. Trabajan bien cuando eres capaz de motivarlos, pero de vez en cuando necesitan un poco más de "motivación", ¿entiendes?' WHERE `ID`=16101;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청한 짓이야...', `MaleText_loc4`='这些肮脏的勾当。', `MaleText_loc5`='這些愚蠢的行為。', `MaleText_loc7`='Malas acciones.', `FemaleText_loc1`='멍청한 짓이야...', `FemaleText_loc4`='这些肮脏的勾当。', `FemaleText_loc5`='這些愚蠢的行為。', `FemaleText_loc7`='Malas acciones.' WHERE `ID`=16102;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='운 좋게도 몇 병을 건질 수 있었으니 다행스럽군.', `MaleText_loc4`='太幸运了，我成功打捞到了几瓶。', `MaleText_loc5`='幸運地，我搶救了幾個瓶子。', `MaleText_loc7`='Afortunadamente, he conseguido recuperar algunas botellas.', `FemaleText_loc1`='운 좋게도 몇 병을 건질 수 있었으니 다행스럽군.', `FemaleText_loc4`='太幸运了，我成功打捞到了几瓶。', `FemaleText_loc5`='幸運地，我搶救了幾個瓶子。', `FemaleText_loc7`='Afortunadamente, he conseguido recuperar algunas botellas.' WHERE `ID`=16103;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두 학생은 눈을 감고 소리를 듣기 위해 노력합니다.', `MaleText_loc4`='每个学生都闭上了眼睛，竖着耳朵听着声音。', `MaleText_loc5`='兩個學生閉上他們的眼睛，盡全力聆聽那聲音。', `MaleText_loc7`='Ambos estudiantes cierran los ojos y se esfuerzan por oír las voces.', `FemaleText_loc1`='두 학생은 눈을 감고 소리를 듣기 위해 노력합니다.', `FemaleText_loc4`='每个学生都闭上了眼睛，竖着耳朵听着声音。', `FemaleText_loc5`='兩個學生閉上他們的眼睛，盡全力聆聽那聲音。', `FemaleText_loc7`='Ambos estudiantes cierran los ojos y se esfuerzan por oír las voces.' WHERE `ID`=16104;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='딸꾹... 정말 비... 비 뭐더라... 비 뭐였는데... 에, 정말 끔찍한 재앙이야!', `MaleText_loc4`='嗝……真……真……呃……真是场灾难啊！', `MaleText_loc5`='嗝...什麼樣的折磨...不幸...嗯苦難...錯了，簡直是災難!', `MaleText_loc7`='Hip... Qué calima... Calama... Eh... Qué calami... Eh..., qué desastre.', `FemaleText_loc1`='딸꾹... 정말 비... 비 뭐더라... 비 뭐였는데... 에, 정말 끔찍한 재앙이야!', `FemaleText_loc4`='嗝……真……真……呃……真是场灾难啊！', `FemaleText_loc5`='嗝...什麼樣的折磨...不幸...嗯苦難...錯了，簡直是災難!', `FemaleText_loc7`='Hip... Qué calima... Calama... Eh... Qué calami... Eh..., qué desastre.' WHERE `ID`=16105;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='건장한 블러드 엘프 한 명이 취하기엔 충분하군.', `MaleText_loc4`='这足够逼得一个人去喝闷酒了。', `MaleText_loc5`='已足夠迫使一個人喝酒了。', `MaleText_loc7`='Esto es suficiente para empujar a cualquier hombre a la bebida.', `FemaleText_loc1`='건장한 블러드 엘프 한 명이 취하기엔 충분하군.', `FemaleText_loc4`='这足够逼得一个人去喝闷酒了。', `FemaleText_loc5`='已足夠迫使一個人喝酒了。', `FemaleText_loc7`='Esto es suficiente para empujar a cualquiera a la bebida.' WHERE `ID`=16106;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 고개를 끄덕이더니 헛기침을 합니다.', `MaleText_loc4`='%s点了点头，清了清喉咙。', `MaleText_loc5`='%s對他自己點點頭，並且清嗓子。', `MaleText_loc7`='%s asiente para sí y se aclara la garganta.', `FemaleText_loc1`='%s|1이;가; 고개를 끄덕이더니 헛기침을 합니다.', `FemaleText_loc4`='%s点了点头，清了清喉咙。', `FemaleText_loc5`='%s對他自己點點頭，並且清嗓子。', `FemaleText_loc7`='%s asiente para sí y se aclara la garganta.' WHERE `ID`=16107;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일어나십시오, 제자들이여... 오늘은 여기까지만 하겠습니다.', `MaleText_loc4`='站起来，我的孩子们……先到这里吧。', `MaleText_loc5`='我的孩子，站住...現在夠了。', `MaleText_loc7`='Parad, hijos míos. Por hoy basta.' WHERE `ID`=16108;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$c님, 맘에 드시는 게 있으신가요?', `FemaleText_loc4`='有印象吗，$c？', `FemaleText_loc5`='就像你看見的任何事情一樣嗎，$c?', `FemaleText_loc7`='¿Te gusta algo de lo que ves, $c?' WHERE `ID`=16109;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대지의 정령에 대해서는 언제 말씀해 주시는 겁니까?', `MaleText_loc4`='那大地之灵呢？', `MaleText_loc5`='大地之靈怎麼樣?', `MaleText_loc7`='¿Qué pasa con los espíritus de la tierra?', `FemaleText_loc1`='대지의 정령에 대해서는 언제 말씀해 주시는 겁니까?', `FemaleText_loc4`='那大地之灵呢？', `FemaleText_loc5`='大地之靈怎麼樣?', `FemaleText_loc7`='¿Qué pasa con los espíritus de la tierra?' WHERE `ID`=16110;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 부드럽게 미소를 짓습니다.', `MaleText_loc4`='%s吃吃地笑着。', `MaleText_loc5`='%s輕輕地輕聲笑著。', `MaleText_loc7`='%s se ríe suavemente.', `FemaleText_loc1`='%s|1이;가; 부드럽게 미소를 짓습니다.', `FemaleText_loc4`='%s吃吃地笑着。', `FemaleText_loc5`='%s輕輕地輕聲笑著。', `FemaleText_loc7`='%s se ríe suavemente.' WHERE `ID`=16111;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대지의 정령은 이 방에 가득합니다. 우리가 있는 곳이 어디인지 한 번 생각해 보세요.', `MaleText_loc4`='大地之灵在这里出现得非常频繁，我的孩子。毕竟我们是在地下，对吗？', `MaleText_loc5`='這間房間中存在著非常多的大地之靈，我的孩子。終究，我們在地下，我們不是嗎?', `MaleText_loc7`='Los espíritus de la tierra están muy presentes en esta sala. No en vano estamos bajo tierra, ¿verdad?' WHERE `ID`=16112;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대지의 정령들은 인내심이 강합니다. 주술사는 대지의 정령을 통해 삶의 고난을 극복하는 법을 배웁니다.', `MaleText_loc4`='大地之灵很坚强。因为这样，萨满祭司学会了在面对艰难时保持坚忍。', `MaleText_loc5`='他們是禁慾主義者，大地的精靈們。透過他們薩滿學會忍受生活的艱難。', `MaleText_loc7`='Los espíritus de la tierra son estoicos. Con ellos, los chamanes aprenden a sobrellevar las dificultades de la vida.' WHERE `ID`=16113;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돈만 내면 당신이 원하는 것을 주겠소.', `MaleText_loc4`='只要你有钱，我就能弄到你要的东西。', `MaleText_loc5`='如果你有錢，我就有你需要的。', `MaleText_loc7`='Si tienes dinero, tengo lo que necesitas.' WHERE `ID`=16114;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대지의 정령들은 우리가 이 세계에 처음 왔을 때도 이곳에 있었으며 우리가 죽은 후에도 오랫동안 남아 있을 것입니다.', `MaleText_loc4`='这些石头在我们第一次进入这个世界的时候就存在了，并且在我们离开的时候，它们也不会离开。', `MaleText_loc5`='當我們第一次進入這個世界時，岩石就在這裡，並且在我們消逝很久以後，他們仍將持續。', `MaleText_loc7`='Las rocas estaban aquí la primera vez que vinimos a este mundo y permanecerán aquí cuando nos hayamos ido.' WHERE `ID`=16115;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='한번 둘러보시고 관심 가는 물건이 있는지 확인해 보세요.', `FemaleText_loc4`='请随便看看，如果你对什么感兴趣，就告诉我。', `FemaleText_loc5`='四處看看，並且通知我如果這裡有任何東西讓你感到興趣。', `FemaleText_loc7`='Echa un vistazo y avísame si te interesa algo.' WHERE `ID`=16116;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일어나십시오... 토론할 것이 더 있습니다.', `MaleText_loc4`='站起来吧……还有很多事情要谈。', `MaleText_loc5`='站住...還有更多要討論的。', `MaleText_loc7`='Todavía tenemos cosas que hablar.' WHERE `ID`=16118;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cffffff00호드가 해골 무덤을 차지했습니다!|r', `MaleText_loc4`='|cffffff00部落夺取了白骨荒野的控制权！|r', `MaleText_loc5`='|cffffff00部落已經控制住白骨荒野!|r', `MaleText_loc7`='|cffffff00La Horda ha tomado el control de El Vertedero de Huesos.|r' WHERE `ID`=16119;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cffffff00얼라이언스가 해골 무덤을 차지했습니다!|r', `MaleText_loc4`='|cffffff00联盟夺取了白骨荒野的控制权！|r', `MaleText_loc5`='|cffffff00聯盟已經控制住白骨荒野!|r', `MaleText_loc7`='|cffffff00La Alianza ha tomado el control de El Vertedero de Huesos.|r' WHERE `ID`=16120;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='시간을 갖고 천천히 무기를 둘러보십시오. 필요하시면 무기와 갑옷도 손봐 드리지요.', `FemaleText_loc4`='请自便，看看这把武器。如果你想修理你的武器和装备，我们这里也提供周到的服务。', `FemaleText_loc5`='不用著急，看看這些武器。如果你需要修理武器和盔甲，我也提供這樣的服務。', `FemaleText_loc7`='Tómate tu tiempo, mira bien las armas. También reparo armaduras, si necesitas ese servicio.' WHERE `ID`=16121;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게 자네가 마법을 시전하는데 필요한 물건이 있다네. 어디 둘러보겠나?', `MaleText_loc4`='我有你所需要的施法材料。', `MaleText_loc5`='我這裡只有你施法所需要的東西。', `MaleText_loc7`='Tengo justo lo que necesitas para lanzar tu hechizo.' WHERE `ID`=16122;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 알고 있는 사실을 다시 한번 말해 주십시오!', `MaleText_loc4`='把你知道的再跟我讲一遍！', `MaleText_loc5`='再次告訴我，你所知道的事!', `MaleText_loc7`='Vuelve a contarme lo que sabes.', `FemaleText_loc1`='당신이 알고 있는 사실을 다시 한번 말해 주십시오!', `FemaleText_loc4`='把你知道的再跟我讲一遍！', `FemaleText_loc5`='再次告訴我，你所知道的事!', `FemaleText_loc7`='Vuelve a contarme lo que sabes.' WHERE `ID`=16123;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나그란드의 평화를 되찾으려면 날카로운 검과 강한 갑옷이 필요할 겁니다. 당신이 정의를 실천할 수 있도록 장비를 손봐 드릴까요?', `MaleText_loc4`='只有锋利的武器和坚固的护甲可以让纳格兰回归原有的宁静。让我修理你的装备吧，这样你才能去惩奸除恶。', `MaleText_loc5`='將需要鋒利的刀劍以及強化的盔甲來把平靜帶回納葛蘭。需要我來修理你的裝備，以便你能維護正義嗎?', `MaleText_loc7`='Lo que se necesita para devolverle la tranquilidad a Nagrand es una espada afilada y una armadura reforzada. ¿Quieres que repare tu equipamiento para que puedas impartir justicia?' WHERE `ID`=16124;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물건을 살펴보고 싶습니다.', `MaleText_loc4`='我想要看看你出售的货物。', `MaleText_loc5`='我想要看看你出售的東西。', `MaleText_loc7`='Me gustaría echar un vistazo a tus mercancías.', `FemaleText_loc1`='물건을 살펴보고 싶습니다.', `FemaleText_loc4`='我想要看看你出售的货物。', `FemaleText_loc5`='我想要看看你出售的東西。', `FemaleText_loc7`='Me gustaría echar un vistazo a tus mercancías.' WHERE `ID`=16125;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시약과 독을 찾고 계십니까? 그렇다면 제대로 오셨습니다!', `MaleText_loc4`='你在找毒药和施法材料的供应商吗？如果是的话，那么你来对地方了！', `MaleText_loc5`='你正在尋找藥劑還是毒藥嗎?如果是這樣的話，你已經來到對地方了!', `MaleText_loc7`='¿Estás buscando algún componente o suministros de veneno? ¡Pues has venido al lugar apropiado!' WHERE `ID`=16126;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물건을 살펴보고 싶습니다.', `MaleText_loc4`='我想要看看你出售的货物。', `MaleText_loc5`='我想要看看你出售的東西。', `MaleText_loc7`='Me gustaría echar un vistazo a tus mercancías.', `FemaleText_loc1`='물건을 살펴보고 싶습니다.', `FemaleText_loc4`='我想要看看你出售的货物。', `FemaleText_loc5`='我想要看看你出售的東西。', `FemaleText_loc7`='Me gustaría echar un vistazo a tus mercancías.' WHERE `ID`=16127;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 장인에게 필요한 물건을 팔고 있습니다. 기본적인 물건은 구비하고 있으나 고급 물품은 없답니다.', `MaleText_loc4`='我出售工匠们需要的物品。不过只是些基础物品，没什么特别的。', `MaleText_loc5`='我賣工藝師需要的物品。基本和不花俏所需的物品。', `MaleText_loc7`='Vendo lo que los artesanos necesitan. Solo objetos básicos, nada especial.' WHERE `ID`=16128;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 물건을 팔고 있습니까?', `MaleText_loc4`='你都卖些什么？', `MaleText_loc5`='你有什麼東西要賣嗎?', `MaleText_loc7`='¿Qué ofertas tienes?', `FemaleText_loc1`='어떤 물건을 팔고 있나요?', `FemaleText_loc4`='你都卖些什么？', `FemaleText_loc5`='你有什麼東西要賣嗎?', `FemaleText_loc7`='¿Qué ofertas tienes?' WHERE `ID`=16129;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='야수를 맡기러 오셨습니까?', `FemaleText_loc4`='你需要寄放你的宠物吗？', `FemaleText_loc5`='你需要寄放你的寵物嗎?', `FemaleText_loc7`='¿Necesitas alojar a tu mascota?' WHERE `ID`=16130;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 야수를 맡기고 싶어요.', `MaleText_loc4`='我想要寄放我的宠物。', `MaleText_loc5`='我想寄放我的寵物。', `MaleText_loc7`='Deseo guardar a mi mascota en el establo.', `FemaleText_loc1`='제 야수를 맡기고 싶어요.', `FemaleText_loc4`='我想要寄放我的宠物。', `FemaleText_loc5`='我想寄放我的寵物。', `FemaleText_loc7`='Deseo guardar a mi mascota en el establo.' WHERE `ID`=16131;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='길을 잃으신 겁니까? 마을 상인 대부분은 마을의 중심부 근처에 있습니다.', `FemaleText_loc4`='你迷路了吗？这里大部分的商人都居住在城镇中心。', `FemaleText_loc5`='你迷路了嗎?大多數的鎮上小販都在市中心附近。', `FemaleText_loc7`='¿Sabes dónde estás? La mayoría de los mercaderes están cerca del centro de la ciudad.' WHERE `ID`=16132;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 온갖 종류의 물건을 모두 취급하지만 보통은 희귀한 물건만을 팔고 있답니다.', `FemaleText_loc4`='我有很多零碎的小东西。', `FemaleText_loc5`='我販賣零星物品，不過大部分都是奇怪的東西。', `FemaleText_loc7`='Lo traigo fino y lo traigo gordo. Bueno, casi todo gordo, más bien.' WHERE `ID`=16133;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 물건을 팔고 있습니까?', `MaleText_loc4`='你都卖些什么？', `MaleText_loc5`='你有什麼東西要賣嗎?', `MaleText_loc7`='¿Qué tienes a la venta?', `FemaleText_loc1`='어떤 물건을 팔고 있습니까?', `FemaleText_loc4`='你都卖些什么？', `FemaleText_loc5`='你有什麼東西要賣嗎?', `FemaleText_loc7`='¿Qué tienes a la venta?' WHERE `ID`=16134;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 물건을 팔고 있습니까?', `MaleText_loc4`='你都卖些什么？', `MaleText_loc5`='你有什麼東西要賣嗎?', `MaleText_loc7`='¿Qué tienes a la venta?', `FemaleText_loc1`='어떤 물건을 팔고 있습니까?', `FemaleText_loc4`='你都卖些什么？', `FemaleText_loc5`='你有什麼東西要賣嗎?', `FemaleText_loc7`='¿Qué tienes a la venta?' WHERE `ID`=16135;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미치고 환장하겠군. 저 망할 알이 손에 닿지 않다니!', `MaleText_loc4`='我快要疯了。我碰不到那些该死的蛋！', `MaleText_loc5`='我快要發瘋了。我不能拿到那些可惡的蛋!', `MaleText_loc7`='¡Me estoy volviendo loco! ¡No consigo alcanzar esos malditos huevos!' WHERE `ID`=16136;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 맛있어 보이는데...', `MaleText_loc4`='它们看上去太美味了……', `MaleText_loc5`='這看起來真是美味...', `MaleText_loc7`='Y parecen tan deliciosos...' WHERE `ID`=16137;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 빌어먹을 기계가 작동하게 만들 수만 있다면!', `MaleText_loc4`='要是我能让这台该死的机器工作起来就好了！', `MaleText_loc5`='要是我能使這台殘破的機器運轉該多好!', `MaleText_loc7`='¡Si pudiera hacer que esta maldita máquina funcionara!' WHERE `ID`=16138;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 달콤하고, 맛있고, 반점이 있는 알아, 넌 내 거야...', `MaleText_loc4`='啊，美味的鸟蛋啊……你们都将是我的……', `MaleText_loc5`='噢甜美，美味，有斑紋的蛋 - 你將是我的...', `MaleText_loc7`='Oh, preciosos, deliciosos huevos moteados... ¡Seréis míos!' WHERE `ID`=16139;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='수년 동안 명예의 요새는 지옥불 반도의 두려운 존재들과 맞서 왔습니다. 이제 차원문이 다시 열리고 아제로스에서 지원군이 도착할 테니 이 지긋지긋한 교착 상태에 종지부를 찍을 수 있을 겁니다.', `FemaleText_loc4`='很多年来，荣耀堡都在独自抵抗着地狱火半岛的敌人。现在，既然黑暗之门已经重新开启，援助者们像潮水一样从艾泽拉斯涌入，也许这个血腥的僵局将会被打破。', `FemaleText_loc5`='多年來，榮譽堡一直對抗著地獄火半島的恐怖。現在，既然傳送門的入口已經重新開啟，且援助從艾澤拉斯來到，或許這個流血的僵持將會結束。', `FemaleText_loc7`='Durante años, Bastión del Honor resistió ante los horrores de la Península del Fuego Infernal. Ahora que el portal está de nuevo abierto y que llega ayuda continua de Azeroth, puede que acabemos de una vez con este sangriento enfrentamiento.' WHERE `ID`=16140;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지옥불 반도에 있는 우리의 적군 중에 지옥불 성채의 오크도 끼어 있다는 것은 유감스러운 일이 아닐 수 없네.$B$B하지만... 그 누가 오크보다도 우리 호드를 더 만만한 상대라고 생각하겠나?', `FemaleText_loc4`='我们在地狱火半岛的敌人非常多，遗憾的是，地狱火堡垒的兽人便是其中之一。$B$B但是……没有谁比这些兽人更适合用来历练部落的新兵了。', `FemaleText_loc5`='令人遺憾的是，我們在地獄火半島上那麼多的敵人中，地獄火堡壘的獸人們站在他們中間。$B$B但是...誰能比獸人們更適於挑戰並消耗部落...?', `FemaleText_loc7`='Es lamentable que, entre nuestros muchos enemigos en la Península del Fuego Infernal, se encuentren los orcos de la Ciudadela del Fuego Infernal.$B$BPero... ¿quién mejor para desafiar a la Horda que... los orcos?' WHERE `ID`=16141;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 이곳의 병참장교입니다. 필요한 물건이라도 있으십니까?', `FemaleText_loc4`='我是这里的军需官，你需要什么补给吗？', `FemaleText_loc5`='我是這裡的軍需官，你需要幫忙嗎?', `FemaleText_loc7`='¡Yo soy la intendente aquí! ¿Necesitabas provisiones?' WHERE `ID`=16142;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 만나서 반갑네, $n! 몇 가지만 손을 보면 방방이의 궤도가 완벽해질 걸세!', `MaleText_loc4`='很高兴再次见到你，$n！只要再调整下跳跃的轨道就完美了！', `MaleText_loc5`='真高興再次見到你，$n!只需一些更多的調整，而跳躍軌道將會是完美的!', `MaleText_loc7`='¡Me alegro de verte de nuevo, $n! ¡Unos pocos ajustes a la trayectoria del salto y será perfecto!' WHERE `ID`=16143;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와자트, 제가 바보 같은 짓을 해서 열쇠를 잃어버렸습니다. 열쇠를 새로 얻을 수 있을까요?', `MaleText_loc4`='瓦萨特，我做了些愚蠢的事情，把钥匙给弄丢了。你能再给我一把吗？', `MaleText_loc5`='瓦薩特，我做了件愚蠢的事情，並且因此遺失了我的鑰匙。可以麻煩你在給我一根鑰匙嗎?', `MaleText_loc7`='Oye, Wazat, he hecho algo estúpido y he perdido mi llave como resultado de esa estupidez. ¿Podrías conseguirme otra?', `FemaleText_loc1`='와자트, 제가 바보 같은 짓을 해서 열쇠를 잃어버렸습니다. 열쇠를 새로 얻을 수 있을까요?', `FemaleText_loc4`='瓦萨特，我做了些愚蠢的事情，把钥匙给弄丢了。你能再给我一把吗？', `FemaleText_loc5`='瓦薩特，我做了件愚蠢的事情，並且因此遺失了我的鑰匙。可以麻煩你在給我一根鑰匙嗎?', `FemaleText_loc7`='Oye, Wazat, he hecho algo estúpido y he perdido mi llave como resultado de esa estupidez. ¿Podrías conseguirme otra?' WHERE `ID`=16144;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐, 자네 부탁이라면, $n!', `MaleText_loc4`='没问题，$n！', `MaleText_loc5`='為了你什麼都可以，$n!', `MaleText_loc7`='¡Lo que sea por ti, $n!' WHERE `ID`=16145;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='징표를 교환하고 싶습니다.', `MaleText_loc4`='我要兑换徽记！', `MaleText_loc5`='我要兌換印記!', `MaleText_loc7`='¡Tengo marcas para canjear!', `FemaleText_loc1`='징표를 교환하고 싶습니다.', `FemaleText_loc4`='我要兑换徽记！', `FemaleText_loc5`='我要兌換印記!', `FemaleText_loc7`='¡Tengo marcas para canjear!' WHERE `ID`=16146;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐요, $n. 이쪽으로 오세요.', `MaleText_loc4`='喂，$n，到这里来。', `MaleText_loc5`='嘿， $n，來吧。', `MaleText_loc7`='Psst, $n, ven aquí.' WHERE `ID`=16147;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 이쪽으로 오시오.', `MaleText_loc4`='$n，过来。', `MaleText_loc5`='$n，來吧。', `MaleText_loc7`='$n, ven aquí.' WHERE `ID`=16148;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 끔찍한 소리를 내지릅니다.', `MaleText_loc4`='%s发出一声可怕的尖叫。', `MaleText_loc5`='%s放聲驚嚇尖叫。', `MaleText_loc7`='%s deja escapar un chillido terrorífico.' WHERE `ID`=16149;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 깨지면서 흘러나온 노른자로 둥지가 가득 찹니다.', `MaleText_loc4`='%s破裂开来，蛋黄流满了鸟巢。', `MaleText_loc5`='%s啪地一聲破裂，整個巢充滿蛋黃。', `MaleText_loc7`='%s se rompe y se abre, llenando el nido de yema.' WHERE `ID`=16150;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드루이드들의 주최로 달숲에서 달의 축제가 열리고 있습니다. 먼 곳에 계시는 분들을 위해 스톰윈드 바로 바깥에서 이동 서비스를 제공하고 있습니다.', `MaleText_loc4`='德鲁伊们在月光林地举行春节庆典。如果你觉得路途太遥远了，他们在暴风城外提供传送服务。', `MaleText_loc5`='德魯伊們舉行的新年節慶慶祝活動正在月光林地進行。如果旅行到那裡對你來說太遠了，他們正在暴風城外提供月井的運輸服務。', `MaleText_loc7`='El Festival Lunar de los druidas tiene lugar en Claro de la Luna. Si te queda demasiado lejos, puedes usar el transporte que ofrecen a las puertas de Ventormenta.', `FemaleText_loc1`='드루이드들의 주최로 달숲에서 달의 축제가 열리고 있습니다. 먼 곳에 계시는 분들을 위해 스톰윈드 바로 바깥에서 이동 서비스를 제공하고 있습니다.', `FemaleText_loc4`='德鲁伊们在月光林地举行春节庆典。如果你觉得路途太遥远了，他们在暴风城外提供传送服务。', `FemaleText_loc5`='德魯伊們舉行的新年節慶慶祝活動正在月光林地進行。如果旅行到那裡對你來說太遠了，他們正在暴風城外提供月井的運輸服務。', `FemaleText_loc7`='El Festival Lunar de los druidas tiene lugar en Claro de la Luna. Si te queda demasiado lejos, puedes usar el transporte que ofrecen a las puertas de Ventormenta.' WHERE `ID`=16151;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달의 축제는 우리 드워프들에게 특별한 시간이지요. 축제 기간 동안 선대의 장로들에게 찾아가서 존경을 표시한답니다.', `MaleText_loc4`='春节对我们来说是个特别的日子。我们寻找古代的长者，对他们表示敬意。', `MaleText_loc5`='新年節慶對我們來說是特別的時刻。我們在尋找我們長輩，陶土議會，並且向他們表示敬意。', `MaleText_loc7`='El Festival Lunar es una época especial para nosotros. Buscamos a nuestros ancestros, los terráneos, y los honramos.', `FemaleText_loc1`='달의 축제는 우리 드워프들에게 특별한 시간이지요. 축제 기간 동안 선대의 장로들에게 찾아가서 존경을 표시한답니다.', `FemaleText_loc4`='春节对我们来说是个特别的日子。我们寻找古代的长者，对他们表示敬意。', `FemaleText_loc5`='新年節慶對我們來說是特別的時刻。我們在尋找我們長輩，陶土議會，並且向他們表示敬意。', `FemaleText_loc7`='El Festival Lunar es una época especial para nosotros. Buscamos a nuestros ancestros, los terráneos, y los honramos.' WHERE `ID`=16153;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='Dwarf Gossip NPC - Periodic Talk (Expansion Prologue) 01', `MaleText_loc4`='Dwarf Gossip NPC - Periodic Talk (Expansion Prologue) 01', `MaleText_loc5`='Dwarf Gossip NPC - Periodic Talk (Expansion Prologue) 01', `MaleText_loc7`='PNJ enano cotilla - Charla periódica (prólogo de la expansión) 01', `FemaleText_loc1`='Dwarf Gossip NPC - Periodic Talk (Expansion Prologue) 01', `FemaleText_loc4`='Dwarf Gossip NPC - Periodic Talk (Expansion Prologue) 01', `FemaleText_loc5`='Dwarf Gossip NPC - Periodic Talk (Expansion Prologue) 01', `FemaleText_loc7`='PNJ enano cotilla - Charla periódica (prólogo de la expansión) 01' WHERE `ID`=16154;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이언포지는 겨울맞이 축제가 열리는 기간에 가장 멋지답니다.', `MaleText_loc4`='铁炉堡很少看上去像冬幕节期间那样富丽堂皇。', `MaleText_loc5`='鐵爐堡很少看起來像在冬幕節的盛宴期間一樣的壯觀。', `MaleText_loc7`='Forjaz, raramente está tan espléndido como durante el festín del Festival de Invierno.', `FemaleText_loc1`='아이언포지는 겨울맞이 축제가 열리는 기간에 가장 멋져요.', `FemaleText_loc4`='铁炉堡很少看上去像冬幕节期间那样富丽堂皇。', `FemaleText_loc5`='鐵爐堡很少看起來像在冬幕節的盛宴期間一樣的壯觀。', `FemaleText_loc7`='Forjaz, raramente está tan espléndido como durante el festín del Festival de Invierno.' WHERE `ID`=16155;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달의 축제는 우리 나이트 엘프들에게 특별한 의미가 있지요. 우리는 전 세계에 있는 장로들을 찾아가서 그분들의 지혜를 배웁니다.', `MaleText_loc4`='春节对暗夜精灵来说有着特殊的意义。我们在全世界寻找长者的智慧。', `MaleText_loc5`='新年節慶對夜精靈們有特別的意義。我們在全世界尋找我們長輩的智慧。', `MaleText_loc7`='El Festival Lunar tiene un significado especial para los elfos de la noche. Buscamos la sabiduría de nuestros ancestros por todo el mundo.', `FemaleText_loc1`='달의 축제는 우리 나이트 엘프들에게 특별한 의미가 있지요. 우리는 전 세계에 있는 장로들을 찾아가서 그분들의 지혜를 배웁니다.', `FemaleText_loc4`='春节对暗夜精灵来说有着特殊的意义。我们在全世界寻找长者的智慧。', `FemaleText_loc5`='新年節慶對夜精靈們有特別的意義。我們在全世界尋找我們長輩的智慧。', `FemaleText_loc7`='El Festival Lunar tiene un significado especial para los elfos de la noche. Buscamos la sabiduría de nuestros ancestros por todo el mundo.' WHERE `ID`=16156;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='Night Elf Gossip NPC - Periodic Talk (Expansion Prologue) 01', `MaleText_loc4`='Night Elf Gossip NPC - Periodic Talk (Expansion Prologue) 01', `MaleText_loc5`='Night Elf Gossip NPC - Periodic Talk (Expansion Prologue) 01', `MaleText_loc7`='PNJ elfo de la noche cotilla - Charla periódica (prólogo de la expansión) 01', `FemaleText_loc1`='Night Elf Gossip NPC - Periodic Talk (Expansion Prologue) 01', `FemaleText_loc4`='Night Elf Gossip NPC - Periodic Talk (Expansion Prologue) 01', `FemaleText_loc5`='Night Elf Gossip NPC - Periodic Talk (Expansion Prologue) 01', `FemaleText_loc7`='PNJ elfo de la noche cotilla - Charla periódica (prólogo de la expansión) 01' WHERE `ID`=16157;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겨우살이 나무 밑에 서 있으면 모두 저에게 키스를 하려는 것 같다니까요.', `MaleText_loc4`='感觉好像每个人都想在槲寄生下吻我。', `MaleText_loc5`='感覺上好像每個人都想要在槲寄生下吻我。', `MaleText_loc7`='Parece ser que todos quieren besarme bajo el muérdago.', `FemaleText_loc1`='겨우살이 나무 밑에 서 있으면 모두 저에게 키스를 하려는 것 같아요.', `FemaleText_loc4`='感觉好像每个人都想在槲寄生下吻我。', `FemaleText_loc5`='感覺上好像每個人都想要在槲寄生下吻我。', `FemaleText_loc7`='Parece ser que todos quieren besarme bajo el muérdago.' WHERE `ID`=16158;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 알기로 이번에 얼라이언스 연합 친구들은 겨울맞이 축제를 아이언포지에서 연다고 하더군요.', `MaleText_loc4`='据我所知，联盟的人民在铁炉堡庆祝这个冬幕节。', `MaleText_loc5`='據我所知，聯盟的人民在鐵爐堡慶祝這次的冬幕節。', `MaleText_loc7`='Tengo entendido que las gentes de la ALianza celebran este Festival de Invierno en Forjaz.', `FemaleText_loc1`='제가 알기로 이번에 얼라이언스 사람들은 겨울맞이 축제를 아이언포지에서 연다고 하더군요.', `FemaleText_loc4`='据我所知，联盟的人民在铁炉堡庆祝这个冬幕节。', `FemaleText_loc5`='據我所知，聯盟的人民在鐵爐堡慶祝這次的冬幕節。', `FemaleText_loc7`='Tengo entendido que las gentes de la ALianza celebran este Festival de Invierno en Forjaz.' WHERE `ID`=16161;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠의 문이 다시 한번 열리는 날 우리는 고향 드레노어로 돌아갈 수 있을 것이오.', `MaleText_loc4`='如果黑暗之门再次打开，我们就可以回到家乡德拉诺了。', `MaleText_loc5`='如果黑暗之門再次打開，我們就能回到在德拉諾的家。', `MaleText_loc7`='Si El Portal Oscuro vuelve a abrirse, podríamos volver a casa, a Draenor.', `FemaleText_loc1`='어둠의 문이 다시 한번 열리는 날 우리는 고향 드레노어로 돌아갈 수 있습니다.', `FemaleText_loc4`='如果黑暗之门再次打开，我们就可以回到家乡德拉诺了。', `FemaleText_loc5`='如果黑暗之門再次打開，我們就能回到在德拉諾的家。', `FemaleText_loc7`='Si El Portal Oscuro vuelve a abrirse, podríamos volver a casa, a Draenor.' WHERE `ID`=16163;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 겨울맞이 축제의 전통을 제대로 알지는 못하지만 그 전통을 받아들였소.', `MaleText_loc4`='尽管我们并不完全理解冬幕节的传统，但是……入乡随俗。', `MaleText_loc5`='雖然我們不是真正地了解冬幕節的傳統，但是我們已經喜歡上它們了。', `MaleText_loc7`='Aunque no entendemos muy bien las tradiciones del Festival de Invierno, las hemos adoptado.', `FemaleText_loc1`='우리는 겨울맞이 축제의 전통을 제대로 알지는 못하지만 그 전통을 받아들였습니다.', `FemaleText_loc4`='尽管我们并不完全理解冬幕节的传统，但是……入乡随俗。', `FemaleText_loc5`='雖然我們不是真正地了解冬幕節的傳統，但是我們已經喜歡上它們了。', `FemaleText_loc7`='Aunque no entendemos muy bien las tradiciones del Festival de Invierno, las hemos adaptado.' WHERE `ID`=16164;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='Night Elf Gossip NPC - Periodic Talk (Expansion Prologue) 01', `MaleText_loc4`='Undead Gossip NPC - Periodic Talk (Lunar Festival) 01', `MaleText_loc5`='Undead Gossip NPC - Periodic Talk (Lunar Festival) 01', `MaleText_loc7`='PNJ no-muerto cotilla - Charla periódica (Festtival Lunarn) 01', `FemaleText_loc1`='Undead Gossip NPC - Periodic Talk (Lunar Festival) 01', `FemaleText_loc4`='Undead Gossip NPC - Periodic Talk (Lunar Festival) 01', `FemaleText_loc5`='Undead Gossip NPC - Periodic Talk (Lunar Festival) 01', `FemaleText_loc7`='PNJ no-muerto cotilla - Charla periódica (Festtival Lunarn) 01' WHERE `ID`=16165;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='Undead Gossip NPC - Periodic Talk (Expansion Prologue) 01', `MaleText_loc4`='Undead Gossip NPC - Periodic Talk (Expansion Prologue) 01', `MaleText_loc5`='Undead Gossip NPC - Periodic Talk (Expansion Prologue) 01', `MaleText_loc7`='PNJ no-muerto cotilla - Charla periódica (prólogo de la expansión) 01', `FemaleText_loc1`='Undead Gossip NPC - Periodic Talk (Expansion Prologue) 01', `FemaleText_loc4`='Undead Gossip NPC - Periodic Talk (Expansion Prologue) 01', `FemaleText_loc5`='Undead Gossip NPC - Periodic Talk (Expansion Prologue) 01', `FemaleText_loc7`='PNJ no-muerto cotilla - Charla periódica (prólogo de la expansión) 01' WHERE `ID`=16166;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겨울맞이 축제가 예전 같지 않지만 일단 놀러가 보면 여전히 느껴지는 뭔가 있지.', `MaleText_loc4`='现在的冬幕节已经跟以前不一样了，但是我仍然很有节日的感觉。', `MaleText_loc5`='冬幕節日現在不同了，但是裝裝樣子仍然使我感覺到一些東西。', `MaleText_loc7`='El Festival de Invierno ya no es lo mismo, pero encargarme de los preparativos sigue haciéndome sentir algo.', `FemaleText_loc1`='겨울맞이 축제가 예전 같지 않지만 일단 놀러가 보면 여전히 느껴지는 뭔가 있지요.', `FemaleText_loc4`='现在的冬幕节已经跟以前不一样了，但是我仍然很有节日的感觉。', `FemaleText_loc5`='冬幕節日現在不同了，但是裝裝樣子仍然使我感覺到一些東西。', `FemaleText_loc7`='El Festival de Invierno ya no es lo mismo, pero encargarme de los preparativos sigue haciéndome sentir algo.' WHERE `ID`=16167;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달의 축제는 전 세계에 걸쳐 존재하는 선조에게 지혜를 구하는 우리 타우렌에게 특별한 의미가 있소이다.', `MaleText_loc4`='春节对牛头人来说有着特殊的意义。我们在全世界寻找长者的智慧。', `MaleText_loc5`='新年節慶對牛頭人有特別的意義。我們在全世界尋找我們長輩的智慧。', `MaleText_loc7`='El Festival Lunar tiene un significado especial para los tauren. Buscamos la sabiduría de nuestros ancestros por todo el mundo.', `FemaleText_loc1`='달의 축제는 전 세계에 걸쳐 존재하는 선조에게 지혜를 구하는 우리 타우렌에게 특별한 의미가 있답니다.', `FemaleText_loc4`='春节对牛头人来说有着特殊的意义。我们在全世界寻找长者的智慧。', `FemaleText_loc5`='新年節慶對牛頭人有特別的意義。我們在全世界尋找我們長輩的智慧。', `FemaleText_loc7`='El Festival Lunar tiene un significado especial para los tauren. Buscamos la sabiduría de nuestros ancestros por todo el mundo.' WHERE `ID`=16168;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='Tauren Gossip NPC - Periodic Talk (Expansion Prologue) 01', `MaleText_loc4`='Tauren Gossip NPC - Periodic Talk (Expansion Prologue) 01', `MaleText_loc5`='Tauren Gossip NPC - Periodic Talk (Expansion Prologue) 01', `MaleText_loc7`='PNJ tauren cotilla - Charla periódica (prólogo de la expansión) 01', `FemaleText_loc1`='Tauren Gossip NPC - Periodic Talk (Expansion Prologue) 01', `FemaleText_loc4`='Tauren Gossip NPC - Periodic Talk (Expansion Prologue) 01', `FemaleText_loc5`='Tauren Gossip NPC - Periodic Talk (Expansion Prologue) 01', `FemaleText_loc7`='PNJ tauren cotilla - Charla periódica (prólogo de la expansión) 01' WHERE `ID`=16169;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오그리마에서 와이번을 한 번만 타면 겨울 할아버지를 만날 수 있소이다.', `MaleText_loc4`='冬天爷爷就在奥格瑞玛，乘坐双足飞龙很快就能抵达那里。', `MaleText_loc5`='冬天爺爺只差雙足翼龍的運送就能到達奧格瑪。', `MaleText_loc7`='El Gran Padre Invierno está a un viaje en dracoleón de Orgrimmar.', `FemaleText_loc1`='오그리마에서 와이번을 한 번만 타면 겨울 할아버지를 만날 수 있습니다.', `FemaleText_loc4`='冬天爷爷就在奥格瑞玛，乘坐双足飞龙很快就能抵达那里。', `FemaleText_loc5`='冬天爺爺只差雙足翼龍的運送就能到達奧格瑪。', `FemaleText_loc7`='El Gran Padre Invierno está a un viaje en dracoleón de Orgrimmar.' WHERE `ID`=16170;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달의 축제는 칼도레이에게 무엇보다 중요한 의미를 지닙니다. 드루이드의 위대한 축제는 분명 굉장한 행사랍니다.', `MaleText_loc4`='对卡多雷而言，春节是最重要的节日。德鲁伊举办的庆典总是非常热闹。', `MaleText_loc5`='新年節慶對卡多雷越來越重要。德魯伊們的大慶典肯定正達到高峰。', `MaleText_loc7`='El Festival Lunar era muy importante para los kaldorei. El gran festival de los druidas debe de estar a tope en estos momentos.', `FemaleText_loc1`='달의 축제는 칼도레이에게 무엇보다 중요한 의미를 지닙니다. 드루이드의 위대한 축제는 분명 굉장한 행사예요.', `FemaleText_loc4`='对卡多雷而言，春节是最重要的节日。德鲁伊举办的庆典总是非常热闹。', `FemaleText_loc5`='新年節慶對卡多雷越來越重要。德魯伊們的大慶典肯定正達到高峰。', `FemaleText_loc7`='El Festival Lunar era muy importante para los kaldorei. El gran festival de los druidas debe de estar a tope en estos momentos.' WHERE `ID`=16171;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겨울맞이 축제는 언제나 인간의 전유물이었지요. 고블린이나 오크가 축제에 참가하는 모습은 다소 낯선 광경이랍니다.', `MaleText_loc4`='冬幕节一直以来都是个人类的节日。看着地精和兽人开始掺合进来，感觉相当诡异。', `MaleText_loc5`='冬幕節一直是人類的活動。看見哥布林和獸人參加活動還真有點奇怪。', `MaleText_loc7`='El Festival de Invierno siempre ha sido algo de los humanos. Es extraño ver cómo lo han adoptado los goblins y los orcos.', `FemaleText_loc1`='겨울맞이 축제는 언제나 인간의 전유물이었지요. 고블린이나 오크가 축제에 참가하는 모습은 다소 낯선 광경이랍니다.', `FemaleText_loc4`='冬幕节一直以来都是个人类的节日。看着地精和兽人开始掺合进来，感觉相当诡异。', `FemaleText_loc5`='冬幕節一直是人類的活動。看見哥布林和獸人參加活動還真有點奇怪。', `FemaleText_loc7`='El Festival de Invierno siempre ha sido algo de los humanos. Es extraño ver cómo lo han adoptado los goblins y los orcos.' WHERE `ID`=16173;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이언포지의 마법 지구로 가서 그곳의 나이트 엘프 드루이드들과 대화해 보십시오. 당신이 달의 축제에 참가할 수 있도록 달숲으로 순간이동시켜 줄 것입니다.', `MaleText_loc4`='去铁炉堡的秘法区和那里的暗夜精灵德鲁伊谈谈吧，他们可以把你传送到月光林地去参加春节庆典。', `MaleText_loc5`='去鐵爐堡的秘法區並且與那裡的夜精靈德魯伊們談話。他們能將你送到月光林地參加新年節慶慶祝活動。', `MaleText_loc7`='Ve a la Sala Mística de Forjaz y habla con los druidas elfos de la noche de allí. Te podrán transportar a Claro de la Luna para celebrar con ellos el Festival Lunar.', `FemaleText_loc1`='아이언포지의 마법 지구로 가서 그곳의 나이트 엘프 드루이드들과 대화해 보세요. 당신이 달의 축제에 참가할 수 있도록 달숲으로 순간이동시켜 줄 겁니다.', `FemaleText_loc4`='去铁炉堡的秘法区和那里的暗夜精灵德鲁伊谈谈吧，他们可以把你传送到月光林地去参加春节庆典。', `FemaleText_loc5`='去鐵爐堡的秘法區並且與那裡的夜精靈德魯伊們談話。他們能將你送到月光林地參加新年節慶慶祝活動。', `FemaleText_loc7`='Ve a la Sala Mística de Forjaz y habla con los druidas elfos de la noche de allí. Te podrán transportar a Claro de la Luna para celebrar con ellos el Festival Lunar.' WHERE `ID`=16174;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 오랜 친구인 엘프들이 호드와 동맹을 맺었다는 소문을 들었습니다. 전 늘 그들을 믿는 일은 어리석은 짓이라고 말해 왔는데도 말입니다. 거참...', `MaleText_loc4`='我听到传言说，我们的老朋友——精灵们，和部落结盟了。我一直在说，信任他们是非常愚蠢的。', `MaleText_loc5`='我已經聽到我們的老朋友，那些精靈們，已經與部落聯盟的謠言。我總是說我們對他們的信任是愚蠢的。', `MaleText_loc7`='He oído rumores de que nuestros antiguos amigos, los elfos, se han aliado con la Horda. Siempre se dijo que deberíamos haber confiado en ellos.', `FemaleText_loc1`='우리의 오랜 친구인 엘프들이 호드와 동맹을 맺었다는 소문을 들었습니다. 전 늘 그들을 믿는 일은 어리석은 짓이라고 말해 왔는데도 말입니다. 거참...', `FemaleText_loc4`='我听到传言说，我们的老朋友——精灵们，和部落结盟了。我一直在说，信任他们是非常愚蠢的。', `FemaleText_loc5`='我已經聽到我們的老朋友，那些精靈們，已經與部落聯盟的謠言。我總是說我們對他們的信任是愚蠢的。', `FemaleText_loc7`='He oído rumores de que nuestros antiguos amigos, los elfos, se han aliado con la Horda. Siempre se dijo que deberíamos haber confiado en ellos.' WHERE `ID`=16175;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이언포지 은행 앞에 가면 근처에 있는 나무 아래서 선물을 나눠 주시는 겨울 할아버지를 만날 수 있습니다.', `MaleText_loc4`='冬天爷爷就在铁炉堡银行门口。他身旁的树下堆满了礼物。', `MaleText_loc5`='冬天爺爺可以在鐵爐堡銀行的前面找到。靠近他的樹是分發禮物的地方。', `MaleText_loc7`='Puedes encontrar al Gran Padre Invierno justo delante de la ribera de Forjaz. El árbol que está junto a él es donde se entregan los regalos.', `FemaleText_loc1`='아이언포지 은행 앞에 가면 근처에 있는 나무 아래서 선물을 나눠 주시는 겨울 할아버지를 만날 수 있어요.', `FemaleText_loc4`='冬天爷爷就在铁炉堡银行门口。他身旁的树下堆满了礼物。', `FemaleText_loc5`='冬天爺爺可以在鐵爐堡銀行的前面找到。靠近他的樹是分發禮物的地方。', `FemaleText_loc7`='Puedes encontrar al Gran Padre Invierno justo delante de la ribera de Forjaz. El árbol que está junto a él es donde se entregan los regalos.' WHERE `ID`=16176;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스 연합에 들어온 신생 종족들은 겨울맞이 축제에서 소란을 피우곤 하지요. 아이언포지 은행은 이번 축제의 중심지랍니다.', `MaleText_loc4`='瞧瞧那些没见过世面的家伙，过个冬幕节就激动成这样。铁炉堡的银行是节日庆典的中心。', `MaleText_loc5`='青少年者的比賽引起冬幕節的大混亂。鐵爐堡的銀行是慶典的中心。', `MaleText_loc7`='Las razas más jóvenes se emocionan mucho con el Festival de Invierno. La ribera de Forjaz es el centro de las celebraciones.', `FemaleText_loc1`='얼라이언스 연합에 들어온 신생 종족들은 겨울맞이 축제에서 소란을 피우곤 하지요. 아이언포지 은행은 이번 축제의 중심지랍니다.', `FemaleText_loc4`='瞧瞧那些没见过世面的家伙，过个冬幕节就激动成这样。铁炉堡的银行是节日庆典的中心。', `FemaleText_loc5`='青少年者的比賽引起冬幕節的大混亂。鐵爐堡的銀行是慶典的中心。', `FemaleText_loc7`='Las razas más jóvenes se emocionan mucho con el Festival de Invierno. La ribera de Forjaz es el centro de las celebraciones.' WHERE `ID`=16179;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 형제 블러드 엘프들이 방식을 바꿀 수만 있다면 좋으련만... 그들은 다시 한번 불타는 군단을 불러들이게 될 거라는 걸 잊지 마십시오.', `MaleText_loc4`='如果我们的兄弟——那些血精灵能迷途知返就好了。他们会把燃烧军团再次带到我们面前的，你记住我的话。', `MaleText_loc5`='如果我們的兄弟，血精靈們，能改變他們的模式。他們將再次為我們帶來燃燒軍團，記住我說的。', `MaleText_loc7`='Si tan solo nuestros hermanos, los elfos de la sangre, cambiasen de forma de ser... Van a conseguir que la Legión vuelva a caer sobre nosotros, ya lo verás.', `FemaleText_loc1`='우리의 형제 블러드 엘프들이 방식을 바꿀 수만 있다면 좋으련만... 그들은 다시 한번 불타는 군단을 불러들이게 될 거라는 걸 잊지 마십시오.', `FemaleText_loc4`='如果我们的兄弟——那些血精灵能迷途知返就好了。他们会把燃烧军团再次带到我们面前的，你记住我的话。', `FemaleText_loc5`='如果我們的兄弟，血精靈們，能改變他們的模式。他們將再次為我們帶來燃燒軍團，記住我說的。', `FemaleText_loc7`='Si tan solo nuestros hermanos, los elfos de la sangre, cambiasen de forma de ser... Van a conseguir que la Legión vuelva a caer sobre nosotros, ya lo verás.' WHERE `ID`=16180;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='현재 달숲에서 달의 축제가 한창 열리고 있습니다. 직접 찾아갈 수도 있고 세나리온 자치령의 드루이드들을 만나시면 순간이동하는 데 도움을 받으실 수 있습니다.', `MaleText_loc4`='春节庆典在月光林地进行。你可以自己艰苦跋涉，或者使用塞纳里奥区的德鲁伊们提供的传送服务到那里去。', `MaleText_loc5`='新年節慶的慶祝活動正在月光林地達到高峰。你可以選擇艱辛的長途旅行，或者是利用塞納里奧區的德魯伊們所提供的運輸服務。', `MaleText_loc7`='La celebración del Festival Lunar está en pleno apogeo en el Claro de la Luna. Puedes ir caminando, pero los druidas del Enclave Cenarion están ofreciendo transporte.', `FemaleText_loc1`='현재 달숲에서 달의 축제가 한창 열리고 있습니다. 직접 찾아갈 수도 있고 세나리온 자치령의 드루이드들을 만나시면 순간이동하는 데 도움을 받으실 수 있습니다.', `FemaleText_loc4`='春节庆典在月光林地进行。你可以自己艰苦跋涉，或者使用塞纳里奥区的德鲁伊们提供的传送服务到那里去。', `FemaleText_loc5`='新年節慶的慶祝活動正在月光林地達到高峰。你可以選擇艱辛的長途旅行，或者是利用塞納里奧區的德魯伊們所提供的運輸服務。', `FemaleText_loc7`='La celebración del Festival Lunar está en pleno apogeo en el Claro de la Luna. Puedes ir caminando, pero los druidas del Enclave Cenarion están ofreciendo transporte.' WHERE `ID`=16181;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수없이 많은 곳을 돌아다녀 봤지만 겨울맞이 축제처럼 흥겨운 축제는 본 적이 없습니다. 드워프들의 위대한 도시 아이언포지로 가서 직접 확인해 보십시오.', `MaleText_loc4`='我到过无数个世界，但是我从没有看到过像冬幕节宴会那样的令人愉快的庆典。你应该去铁炉堡亲眼看看。', `MaleText_loc5`='我遊歷過無數個世界，但是我從未見過像冬幕節這樣令人愉快的慶祝活動。你應該前往鐵爐堡，矮人們的偉大城市，親眼看看這場盛會。', `MaleText_loc7`='He viajado por muchísimos mundos, pero nunca había visto nada tan entrañable como las celebraciones del festín del Festival de Invierno. Deberías ir a Forjaz, la gran ciudad de los enanos, y verlo con tus propios ojos.', `FemaleText_loc1`='수없이 많은 곳을 돌아다녀 봤지만 겨울맞이 축제처럼 흥겨운 축제는 본 적이 없습니다. 드워프들의 위대한 도시 아이언포지로 가서 직접 확인해 보십시오.', `FemaleText_loc4`='我到过无数个世界，但是我从没有看到过像冬幕节宴会那样的令人愉快的庆典。你应该去铁炉堡亲眼看看。', `FemaleText_loc5`='我遊歷過無數個世界，但是我從未見過像冬幕節這樣令人愉快的慶祝活動。你應該前往鐵爐堡，矮人們的偉大城市，親眼看看這場盛會。', `FemaleText_loc7`='He viajado por muchísimos mundos, pero nunca había visto nada tan entrañable como las celebraciones del festín del Festival de Invierno. Deberías ir a Forjaz, la gran ciudad de los enanos, y verlo con tus propios ojos.' WHERE `ID`=16183;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 새로운 세계가 우리를 유혹하는군요. 불타는 군단의 침략을 막아낸 세계라니... 정말 대단합니다.', `MaleText_loc4`='这个新世界使我们着迷。一个世界能让燃烧军团精疲力竭……真是令人惊异。', `MaleText_loc5`='這個新世界使我們著迷。一個將軍團擊退甚至停頓的世界...驚人。', `MaleText_loc7`='Este nuevo mundo nos fascina. Un mundo que ha luchado contra la Legión y la ha neutralizado... impresionante.', `FemaleText_loc1`='이 새로운 세계가 우리를 유혹하는군요. 불타는 군단의 침략을 막아낸 세계라니... 정말 대단합니다.', `FemaleText_loc4`='这个新世界使我们着迷。一个世界能让燃烧军团精疲力竭……真是令人惊异。', `FemaleText_loc5`='這個新世界使我們著迷。一個將軍團擊退甚至停頓的世界...驚人。', `FemaleText_loc7`='Este nuevo mundo nos fascina. Un mundo que ha luchado contra la Legión y ha conseguido quedarse en un impasse... impresionante.' WHERE `ID`=16184;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아제로스의 드루이드들이 달숲에서 멋진 축제를 열고 있습니다. 도시 내에서 축제 구경꾼을 찾아보시면 당신을 달숲으로 순간이동시켜줄 것입니다.', `MaleText_loc4`='艾泽拉斯的德鲁伊们正在月光林地举办一场大型庆典。如果你在城市里找到春节狂欢者，他们可以把你传送到月光林地。', `MaleText_loc5`='艾澤拉斯的德魯伊在月光林地舉行一個盛大的慶祝活動。如果你在城市裡找到新年狂歡者，他們可傳送你到那裡。', `MaleText_loc7`='Los druidas de Azeroth están celebrando una gran fiesta en el Claro de la Luna. Si encuentras a los juerguistas del Festival Lunar en la ciudad, podrán llevarte allí.', `FemaleText_loc1`='아제로스의 드루이드들이 달숲에서 멋진 축제를 열고 있습니다. 도시 내에서 축제 구경꾼을 찾아보시면 당신을 달숲으로 순간이동시켜줄 것입니다.', `FemaleText_loc4`='艾泽拉斯的德鲁伊们正在月光林地举办一场大型庆典。如果你在城市里找到春节狂欢者，他们可以把你传送到月光林地。', `FemaleText_loc5`='艾澤拉斯的德魯伊在月光林地舉行一個盛大的慶祝活動。如果你在城市裡找到新年狂歡者，他們可傳送你到那裡。', `FemaleText_loc7`='Los druidas de Azeroth están celebrando una gran fiesta en el Claro de la Luna. Si encuentras a los juerguistas del Festival Lunar en la ciudad, podrán llevarte allí.' WHERE `ID`=16185;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정한 겨울맞이 축제를 즐기고 싶다면 오그리마로 가십시오.', `MaleText_loc4`='如果你想真正体验一下冬幕节，就应该去奥格瑞玛看看。', `MaleText_loc5`='如果你希望體驗真正的冬幕節宴會，你應該去奧格瑪。', `MaleText_loc7`='Si quieres experimentar realmente el festín del Festival de Invierno, deberías ir a Orgrimmar.', `FemaleText_loc1`='진정한 겨울맞이 축제를 즐기고 싶다면 오그리마로 가세요.', `FemaleText_loc4`='如果你想真正体验一下冬幕节，就应该去奥格瑞玛看看。', `FemaleText_loc5`='如果你希望體驗真正的冬幕節宴會，你應該去奧格瑪。', `FemaleText_loc7`='Si quieres experimentar realmente el festín del Festival de Invierno, deberías ir a Orgrimmar.' WHERE `ID`=16187;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스가 새로운 동맹을 찾았다고 하는군요. 그러나 우리를 잃은 손해를 만회하려면 굉장히 힘들 겁니다.', `MaleText_loc4`='他们说联盟找到了新的同盟，没有我们的帮助，他们肯定更加难以重振旗鼓。', `MaleText_loc5`='他們說聯盟已經找到新盟友。他們要從失去我們中恢復將會是困難重重的。', `MaleText_loc7`='Dicen que la Alianza ha encontrado nuevos aliados. Se sentirán presionados a recuperarse por habernos perdido.', `FemaleText_loc1`='얼라이언스가 새로운 동맹을 찾았다고 하는군요. 그러나 우리를 잃은 손해를 만회하려면 굉장히 힘들 겁니다.', `FemaleText_loc4`='他们说联盟找到了新的同盟，没有我们的帮助，他们肯定更加难以重振旗鼓。', `FemaleText_loc5`='他們說聯盟已經找到新盟友。他們要從失去我們中恢復將會是困難重重的。', `FemaleText_loc7`='Dicen que la Alianza ha encontrado nuevos aliados. Se sentirán presionados a recuperarse por habernos perdido.' WHERE `ID`=16188;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='축제에 참가하고자 한다면 실버문에서 축제 구경꾼을 찾아보십시오. 그들이 당신을 달숲으로 순간이동시켜 줄 겁니다.', `MaleText_loc4`='如果你在银月城找到春节狂欢者，他们可以把你传送到月光林地去参加庆典。', `MaleText_loc5`='如果你在銀月城找到新年狂歡者們，他們能送你到月光林地參與慶祝活動。', `MaleText_loc7`='Si encuentras a juerguistas del Festival Lunar en Lunargenta, podrán transportarte a Claro de la Luna para que participes en la fiesta.', `FemaleText_loc1`='축제에 참가하고자 한다면 실버문에서 축제 구경꾼을 찾아보세요. 그들이 당신을 달숲으로 순간이동시켜 줄 테니까요.', `FemaleText_loc4`='如果你在银月城找到春节狂欢者，他们可以把你传送到月光林地去参加庆典。', `FemaleText_loc5`='如果你在銀月城找到新年狂歡者們，他們能送你到月光林地參與慶祝活動。', `FemaleText_loc7`='Si encuentras a juerguistas del Festival Lunar en Lunargenta, podrán transportarte a Claro de la Luna para que participes en la fiesta.' WHERE `ID`=16189;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘의 골짜기의 가운데로 가면 나무 아래에서 겨울 할아버지를 찾을 수 있을 거요.', `MaleText_loc4`='你可以在力量谷中心找到冬天爷爷。他就在圣诞树下。', `MaleText_loc5`='你可以在力量谷的中心找到冬天爺爺。找那棵樹就對了。', `MaleText_loc7`='Encontrarás al Gran Padre Invierno en el centro del Valle de la Fuerza. Busca el árbol.', `FemaleText_loc1`='힘의 골짜기의 가운데로 가면 나무 아래에서 겨울 할아버지를 찾을 수 있을 거요.', `FemaleText_loc4`='你可以在力量谷中心找到冬天爷爷。他就在圣诞树下。', `FemaleText_loc5`='你可以在力量谷的中心找到冬天爺爺。找那棵樹就對了。', `FemaleText_loc7`='Encontrarás al Gran Padre Invierno en el centro del Valle de la Fuerza. Busca el árbol.' WHERE `ID`=16191;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='북쪽에서 발생한 거대한 폭발에 대해 들어 보셨습니까?', `MaleText_loc4`='你听说北面的大爆炸了吗？', `MaleText_loc5`='你聽說過在北方的大爆炸了嗎?', `MaleText_loc7`='¿Has oído hablar de la gran explosión que tuvo lugar en el norte?', `FemaleText_loc1`='북쪽에서 발생한 거대한 폭발에 대해 들어 보셨습니까?', `FemaleText_loc4`='你听说北面的大爆炸了吗？', `FemaleText_loc5`='你聽說過在北方的大爆炸了嗎?', `FemaleText_loc7`='¿Has oído hablar de la gran explosión que tuvo lugar en el norte?' WHERE `ID`=16192;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달숲에서 달의 축제 중 가장 큰 행사가 진행되고 있소이다. 게다가 먼 곳에 있는 친구들을 위해 지혜의 골짜기에서 드루이드들이 달숲으로 순간이동시켜 주는 서비스를 제공하고 있지.', `MaleText_loc4`='最热闹的春节庆典正在月光林地进行。如果你觉得到那里去实在太远，可以去智慧谷找德鲁伊们把你传送过去。', `MaleText_loc5`='新年節慶最大的慶祝活動正在月光林地進行。如果覺得旅行到那裡太遠，德魯伊們提供從智慧谷出發的運輸服務。', `MaleText_loc7`='La mayor celebración del Festival Lunar tiene lugar en el Claro de la Luna. Si te parece que está demasiado lejos, los druidas están transportando gente desde el Valle de la Sabiduría.', `FemaleText_loc1`='달숲에서 달의 축제 중 가장 큰 행사가 진행되고 있습니다. 게다가 먼 곳에 있는 친구들을 위해 지혜의 골짜기에서 드루이드들이 달숲으로 순간이동시켜 주는 서비스를 제공하고 있지요.', `FemaleText_loc4`='最热闹的春节庆典正在月光林地进行。如果你觉得到那里去实在太远，可以去智慧谷找德鲁伊们把你传送过去。', `FemaleText_loc5`='新年節慶最大的慶祝活動正在月光林地進行。如果覺得旅行到那裡太遠，德魯伊們提供從智慧谷出發的運輸服務。', `FemaleText_loc7`='La mayor celebración del Festival Lunar tiene lugar en el Claro de la Luna. Si te parece que está demasiado lejos, los druidas están transportando gente desde el Valle de la Sabiduría.' WHERE `ID`=16193;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여전히 습관적으로 행하고는 있지만 이제 겨울맞이 축제는 아무런 의미도 없소이다. 오그리마에서는 진짜 축하 행사가 벌어지고 있소.', `MaleText_loc4`='我们也开始庆祝冬幕节了，但这里的宴会感觉有点空旷。奥格瑞玛那边才是真正的庆典。', `MaleText_loc5`='我們仍然舉行應景的活動，但是今年的冬幕節宴會已經冷清了許多。在奧格瑪，他們有真正的慶祝活動。', `MaleText_loc7`='Todavía estamos celebrándolo, pero parece que la fiesta del festín del Festival de Invierno ya se ha terminado. En Orgrimmar es donde tienen la verdadera celebración.', `FemaleText_loc1`='여전히 습관적으로 행하고는 있지만 이제 겨울맞이 축제는 아무런 의미도 없습니다. 오그리마에서는 진짜 축하 행사가 벌어지고 있습니다.', `FemaleText_loc4`='我们也开始庆祝冬幕节了，但这里的宴会感觉有点空旷。奥格瑞玛那边才是真正的庆典。', `FemaleText_loc5`='我們仍然舉行應景的活動，但是今年的冬幕節宴會已經冷清了許多。在奧格瑪，他們有真正的慶祝活動。', `FemaleText_loc7`='Todavía estamos celebrándolo, pero parece que la fiesta del festín del Festival de Invierno ya se ha terminado. En Orgrimmar es donde tienen la verdadera celebración.' WHERE `ID`=16195;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새로운 동맹이 우리와 합류하기 위해 이곳으로 온다는 얘기를 들었습니다. 엘프들과 함께 싸우는 겁니다... 마치 예전처럼 말이죠.', `MaleText_loc4`='我听说我们的新同盟会来和我们一起庆祝。和精灵们并肩作战……就像以前那样。', `MaleText_loc5`='我聽說我們的新盟友將在這裡與我們會合。與精靈們並肩戰鬥...正如往日一樣。', `MaleText_loc7`='He oído que nuestros nuevos aliados se unirán a nosotros aquí. Lucharemos junto a los elfos... Como en los viejos tiempos.', `FemaleText_loc1`='새로운 동맹이 우리와 합류하기 위해 이곳으로 온다는 얘기를 들었습니다. 엘프들과 함께 싸우는 겁니다... 마치 예전처럼 말이죠.', `FemaleText_loc4`='我听说我们的新同盟会来和我们一起庆祝。和精灵们并肩作战……就像以前那样。', `FemaleText_loc5`='我聽說我們的新盟友將在這裡與我們會合。與精靈們並肩戰鬥...正如往日一樣。', `FemaleText_loc7`='He oído que nuestros nuevos aliados se unirán a nosotros aquí. Lucharemos junto a los elfos... Como en los viejos tiempos.' WHERE `ID`=16196;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='많은 우리 포세이큰들은 한때 가슴에 태양을 품었지만 이제는 달이 그 자리를 차지하고 있네. 하지만, 당신이 축제를 즐기고 싶다면 칼림도어의 달숲으로 가시게. 언더시티 왕실로 가면 드루이드들이 달숲으로 보내줄 것일세.', `MaleText_loc4`='对遗忘者来说，月亮已经取代了太阳在我们心中的地位。如果你想要参加节日庆典的话，就去卡利姆多的月光林地吧。幽暗城王座厅的德鲁伊可以将你传送到那里。', `MaleText_loc5`='對大多數的被遺忘者而言，月亮現在我們心中佔有一席之地，那個太陽曾經存在的地方。不過，如果你選擇參加慶祝活動，去卡林多的月光林地。在幽暗城上的王座廳裡的德魯伊們將可以傳送你到那裡。', `MaleText_loc7`='Para muchos Renegados, la luna representa lo que en algún momento representó el sol. Pero si quieres unirte a las celebraciones, ve a Claro de la Luna, en Kalimdor. En la sala del trono, encima de Entrañas, hay druidas que te pueden transportar hasta allí.', `FemaleText_loc1`='많은 우리 포세이큰들은 한때 가슴에 태양을 품었지만 이제는 달이 그 자리를 차지하고 있지요. 하지만, 당신이 축제를 즐기고 싶다면 칼림도어의 달숲으로 가세요. 언더시티 왕실로 가면 드루이드들이 달숲으로 보내줄 테니까요.', `FemaleText_loc4`='对遗忘者来说，月亮已经取代了太阳在我们心中的地位。如果你想要参加节日庆典的话，就去卡利姆多的月光林地吧。幽暗城王座厅的德鲁伊可以将你传送到那里。', `FemaleText_loc5`='對大多數的被遺忘者而言，月亮現在我們心中佔有一席之地，那個太陽曾經存在的地方。不過，如果你選擇參加慶祝活動，去卡林多的月光林地。在幽暗城上的王座廳裡的德魯伊們將可以傳送你到那裡。', `FemaleText_loc7`='Para muchos Renegados, la luna representa lo que en algún momento representó el sol. Pero si quieres unirte a las celebraciones, ve a Claro de la Luna, en Kalimdor. En la sala del trono, encima de Entrañas, hay druidas que te pueden transportar hasta allí.' WHERE `ID`=16197;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겨울맞이 축제는 추운 계절에 따뜻함을 느끼게 해주는 원천인데 그 중심지가 바로 오그리마입니다.', `MaleText_loc4`='在寒冷的季节中，冬幕节的庆典是个非常温暖的去处，它的中心就在奥格瑞玛。', `MaleText_loc5`='在如此寒冷的季節裡，冬幕節的慶祝宴會溫暖了大家的心，而慶祝的主要地點位在奧格瑪。', `MaleText_loc7`='La celebración del festín del Festival de Invierno es fuente de regocijo en los largos meses fríos. Su corazón está en Orgrimmar.', `FemaleText_loc1`='겨울맞이 축제는 추운 계절에 따뜻함을 느끼게 해주는 원천인데 그 중심지가 바로 오그리마입니다.', `FemaleText_loc4`='在寒冷的季节中，冬幕节的庆典是个非常温暖的去处，它的中心就在奥格瑞玛。', `FemaleText_loc5`='在如此寒冷的季節裡，冬幕節的慶祝宴會溫暖了大家的心，而慶祝的主要地點位在奧格瑪。', `FemaleText_loc7`='La celebración del festín del Festival de Invierno es fuente de regocijo en los largos meses fríos. Su corazón está en Orgrimmar.' WHERE `ID`=16199;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바다 건너에서 온 이 엘프들을 어떻게 해야 할지 모르겠네. 이 대륙에 있는 타우렌과 엘프들은 매일같이 전쟁을 치르고 있으니 말이야.', `MaleText_loc4`='我不知道这些精灵为什么要远涉重洋。这片土地上的牛头人和精灵们永远在打仗。', `MaleText_loc5`='我不知道什麼原因讓這些小精靈越過海洋。這個大陸的牛頭人和精靈們總是在打仗。', `MaleText_loc7`='No sé qué pensar de esos elfos del otro lado del mar. Los tauren y los elfos de este continente siempre han estado en guerra.', `FemaleText_loc1`='바다 건너에서 온 이 엘프들을 어떻게 해야 할지 모르겠군요. 이 대륙에 있는 타우렌과 엘프들은 매일같이 전쟁을 치르고 있으니 말입니다.', `FemaleText_loc4`='我不知道这些精灵为什么要远涉重洋。这片土地上的牛头人和精灵们永远在打仗。', `FemaleText_loc5`='我不知道什麼原因讓這些小精靈越過海洋。這個大陸的牛頭人和精靈們總是在打仗。', `FemaleText_loc7`='No sé qué pensar de esos elfos del otro lado del mar. Los tauren y los elfos de este continente siempre han estado en guerra.' WHERE `ID`=16200;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달숲에서 달의 축제 중 가장 큰 의식이 진행되고 있소. 달숲으로 가려거든 썬더 블러프의 장로의 봉우리로 가면 드루이드들이 순간이동시켜 줄 것이오.', `MaleText_loc4`='最隆重的春节庆典正在月光林地进行。德鲁伊们可以把你从雷霆崖的长者高地传送到那里。', `MaleText_loc5`='新年節慶最大的慶祝活動在月光林地進行。在雷霆崖長者高地那裡的德魯伊們將可以傳送你過去。', `MaleText_loc7`='La mayor celebración del Festival Lunar tiene lugar en el Claro de la Luna. Los druidas te llevarán allí desde el Alto de los Ancestros de la Cima del Trueno.', `FemaleText_loc1`='달숲에서 달의 축제 중 가장 큰 의식이 진행되고 있소. 달숲으로 가려거든 썬더 블러프의 장로의 봉우리로 가면 드루이드들이 순간이동시켜 줄 겁니다.', `FemaleText_loc4`='最隆重的春节庆典正在月光林地进行。德鲁伊们可以把你从雷霆崖的长者高地传送到那里。', `FemaleText_loc5`='新年節慶最大的慶祝活動在月光林地進行。在雷霆崖長者高地那裡的德魯伊們將可以傳送你過去。', `FemaleText_loc7`='La mayor celebración del Festival Lunar tiene lugar en el Claro de la Luna. Los druidas te llevarán allí desde el Alto de los Ancestros de la Cima del Trueno.' WHERE `ID`=16201;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$r, 이쪽으로 오십시오. 여기 최고의 품질을 자랑하는 검들을 한번 보십시오. 당신도 아마 제 물건을 사고 싶어 못 배길 걸요. 이렇게 훌륭한 솜씨와 정성이 깃든 무기는 어디에서도 쉽게 찾아볼 수 없지요.', `MaleText_loc4`='来这儿瞧瞧吧。这些武器都很上等呢，不是吗？你肯定想要购买吧。$r，别的地方可找不到锻造工艺如此精湛的武器。', `MaleText_loc5`='你 - 過來這裡。這些刀劍難道不是質地優良的嗎?當然你會希望從我這裡購買。你在別處找不到像這樣的手藝，並且這樣做工精細的武器，$r。', `MaleText_loc7`='Tú... ven aquí. ¿No te parece que estas espadas son de gran calidad? Seguro que quieres comprarme alguna. No encontrarás armas forjadas con tanta artesanía ni dedicación en ningún otro lugar, $r.' WHERE `ID`=16202;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$r|1이여;여;, 뭘 멀뚱멀뚱 보고 계십니까?', `MaleText_loc4`='你在看什么，$r？', `MaleText_loc5`='你在注視什麼，$r?', `MaleText_loc7`='¿Qué miras, $r?' WHERE `ID`=16203;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 당황스럽지만 어떤 이는 제가 겨울 할아버지의 보조인 줄 알았다지 뭡니까!', `MaleText_loc4`='多尴尬啊！有人把我错认成了冬天爷爷的助手。', `MaleText_loc5`='多尷尬!有人把我誤認為是冬天爺爺的幫手之一。', `MaleText_loc7`='¡Qué embarazoso! Me han confundido con uno de los ayudantes del Gran Padre Invierno.', `FemaleText_loc1`='정말 당황스럽지만 어떤 이는 제가 겨울 할아버지의 보조인 줄 알았다지 뭐예요!', `FemaleText_loc4`='多尴尬啊！有人把我错认成了冬天爷爷的助手。', `FemaleText_loc5`='多尷尬!有人把我誤認為是冬天爺爺的幫手之一。', `FemaleText_loc7`='¡Qué embarazoso! Me han confundido con una de las ayudantes del Gran Padre Invierno.' WHERE `ID`=16204;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='Gnome Gossip NPC - Periodic Talk (Expansion Prologue) 01', `MaleText_loc4`='Gnome Gossip NPC - Periodic Talk (Expansion Prologue) 01', `MaleText_loc5`='Gnome Gossip NPC - Periodic Talk (Expansion Prologue) 01', `MaleText_loc7`='PNJ gnomo cotilla - Charla periódica (prólogo de la expansión) 01', `FemaleText_loc1`='Gnome Gossip NPC - Periodic Talk (Expansion Prologue) 01', `FemaleText_loc4`='Gnome Gossip NPC - Periodic Talk (Expansion Prologue) 01', `FemaleText_loc5`='Gnome Gossip NPC - Periodic Talk (Expansion Prologue) 01', `FemaleText_loc7`='PNJ gnomo cotilla - Charla periódica (prólogo de la expansión) 01' WHERE `ID`=16205;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해마다 불꽃놀이 하기 가장 좋은 때는 달의 축제랍니다!', `MaleText_loc4`='春节是一年中看烟火的最好时节！', `MaleText_loc5`='新年節慶的煙火大會是一年中最好的時刻!', `MaleText_loc7`='¡El Festival Lunar es el mejor momento del año para los fuegos artificiales!', `FemaleText_loc1`='해마다 불꽃놀이 하기 가장 좋은 때는 달의 축제랍니다!', `FemaleText_loc4`='春节是一年中看烟火的最好时节！', `FemaleText_loc5`='新年節慶的煙火大會是一年中最好的時刻!', `FemaleText_loc7`='¡El Festival Lunar es el mejor momento del año para los fuegos artificiales!' WHERE `ID`=16206;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 오그리마는 진정한 겨울맞이 축제의 중심지가 되었소.', `MaleText_loc4`='奥格瑞玛完全变成了冬幕节的中心。', `MaleText_loc5`='奧格瑪已經真地成為冬幕節的重要地點。', `MaleText_loc7`='Orgrimmar es el corazón del Festival de Invierno.', `FemaleText_loc1`='이제 오그리마는 진정한 겨울맞이 축제의 중심지가 되었어요.', `FemaleText_loc4`='奥格瑞玛完全变成了冬幕节的中心。', `FemaleText_loc5`='奧格瑪已經真地成為冬幕節的重要地點。', `FemaleText_loc7`='Orgrimmar es el corazón del Festival de Invierno.' WHERE `ID`=16209;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='Troll Gossip NPC - Periodic Talk (Expansion Prologue) 01', `MaleText_loc4`='Troll Gossip NPC - Periodic Talk (Expansion Prologue) 01', `MaleText_loc5`='Troll Gossip NPC - Periodic Talk (Expansion Prologue) 01', `MaleText_loc7`='PNJ trol cotilla - Charla periódica (prólogo de la expansión) 01', `FemaleText_loc1`='Troll Gossip NPC - Periodic Talk (Expansion Prologue) 01', `FemaleText_loc4`='Troll Gossip NPC - Periodic Talk (Expansion Prologue) 01', `FemaleText_loc5`='Troll Gossip NPC - Periodic Talk (Expansion Prologue) 01', `FemaleText_loc7`='PNJ trol cotilla - Charla periódica (prólogo de la expansión) 01' WHERE `ID`=16210;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 달숲으로 가서 드루이드의 위대한 달의 축제를 봐야 하오.', `MaleText_loc4`='我们应该去月光林地，看看德鲁伊们举办的春节庆典。', `MaleText_loc5`='我們應該去月光林地看看德魯伊們的新年節慶。', `MaleText_loc7`='Deberíamos ir al Claro de la Luna para ver el gran festival de la luna de los druidas.', `FemaleText_loc1`='우린 달숲으로 가서 드루이드의 위대한 달의 축제를 봐야 해요.', `FemaleText_loc4`='我们应该去月光林地，看看德鲁伊们举办的春节庆典。', `FemaleText_loc5`='我們應該去月光林地看看德魯伊們的新年節慶。', `FemaleText_loc7`='Deberíamos ir al Claro de la Luna para ver el gran festival de la luna de los druidas.' WHERE `ID`=16211;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이언포지 은행 앞에 가면 근처에 있는 나무 아래서 선물을 나누어 주시는 겨울 할아버지를 찾을 수 있습니다.', `MaleText_loc4`='冬天爷爷就在铁炉堡银行门口。他身旁的树下堆满了礼物。', `MaleText_loc5`='冬天爺爺可以在鐵爐堡銀行的前面被發現。靠近他的樹是分發禮物的地方。', `MaleText_loc7`='Puedes encontrar al Gran Padre Invierno justo delante de la ribera de Forjaz. El árbol que está junto a él es donde se entregan los regalos.', `FemaleText_loc1`='아이언포지 은행 앞에 가면 근처에 있는 나무 아래서 선물을 나누어 주시는 겨울 할아버지를 찾을 수 있답니다.', `FemaleText_loc4`='冬天爷爷就在铁炉堡银行门口。他身旁的树下堆满了礼物。', `FemaleText_loc5`='冬天爺爺可以在鐵爐堡銀行的前面被發現。靠近他的樹是分發禮物的地方。', `FemaleText_loc7`='Puedes encontrar al Gran Padre Invierno justo delante de la ribera de Forjaz. El árbol que está junto a él es donde se entregan los regalos.' WHERE `ID`=16212;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소문 들었어요? 칼림도어의 북쪽 땅에서 거대한 폭발이 일어나서 드디어 엘프들도 쿠엘탈라스에서 활동을 시작했다고 하더라고요.', `MaleText_loc4`='你听说那个传言了吗？在卡利姆多大陆的北方发生了巨大的爆炸，而奎尔萨拉斯的精灵们终于又活跃起来了！', `MaleText_loc5`='你聽到謠言了嗎?在卡林多北方的土地發生過一次的大爆炸，那些精靈們最後在奎爾薩拉斯落腳!', `MaleText_loc7`='¿Te has enterado? ¡Ha habido una gran explosión en las tierras del norte de Kalimdor y los elfos se están rebelando en Quel''Thalas!', `FemaleText_loc1`='소문 들으셨나요? 칼림도어의 북쪽 땅에서 거대한 폭발이 일어나서 드디어 엘프들도 쿠엘탈라스에서 활동을 시작했다고 하더라고요.', `FemaleText_loc4`='你听说那个传言了吗？在卡利姆多大陆的北方发生了巨大的爆炸，而奎尔萨拉斯的精灵们终于又活跃起来了！', `FemaleText_loc5`='你聽到謠言了嗎?在卡林多北方的土地發生過一次的大爆炸，那些精靈們最後在奎爾薩拉斯落腳!', `FemaleText_loc7`='¿Te has enterado? ¡Ha habido una gran explosión en las tierras del norte de Kalimdor y los elfos se están rebelando en Quel''Thalas!' WHERE `ID`=16213;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이언포지의 마법 지구로 가서 그곳의 나이트 엘프 드루이드들과 대화해 보십시오. 당신이 달의 축제에 참가할 수 있도록 달숲으로 순간이동해 줄 겁니다.', `MaleText_loc4`='去铁炉堡的秘法区和暗夜精灵的德鲁伊谈谈。他们会把你传送到月光林地去参加春节庆典。', `MaleText_loc5`='去鐵爐堡的秘法區並且與那裡的夜精靈德魯伊們講話。他們能送你到月光林地參加新年節慶慶祝活動。', `MaleText_loc7`='Ve a la Sala Mística de Forjaz y habla con los druidas elfos de la noche de allí. Te podrán transportar a Claro de la Luna para celebrar con ellos el Festival Lunar.', `FemaleText_loc1`='아이언포지의 마법 지구로 가서 그곳의 나이트 엘프 드루이드들과 대화해 보세요. 당신이 달의 축제에 참가할 수 있도록 달숲으로 순간이동해 줄 테니까요.', `FemaleText_loc4`='去铁炉堡的秘法区和暗夜精灵的德鲁伊谈谈。他们会把你传送到月光林地去参加春节庆典。', `FemaleText_loc5`='去鐵爐堡的秘法區並且與那裡的夜精靈德魯伊們講話。他們能送你到月光林地參加新年節慶慶祝活動。', `FemaleText_loc7`='Ve a la Sala Mística de Forjaz y habla con los druidas elfos de la noche de allí. Te podrán transportar a Claro de la Luna para celebrar con ellos el Festival Lunar.' WHERE `ID`=16214;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘의 골짜기 가운데로 가면 나무 밑에 있는 겨울 할아버지를 만날 수 있소.', `MaleText_loc4`='你可以在力量谷中心找到冬天爷爷。他就在圣诞树下。', `MaleText_loc5`='你可以在力量谷的中心找到冬天爺爺。找那棵樹就對了。', `MaleText_loc7`='Encontrarás al Gran Padre Invierno en el centro del Valle de la Fuerza. Busca el árbol.', `FemaleText_loc1`='힘의 골짜기 가운데로 가면 나무 밑에 있는 겨울 할아버지를 만날 수 있소.', `FemaleText_loc4`='你可以在力量谷中心找到冬天爷爷。他就在圣诞树下。', `FemaleText_loc5`='你可以在力量谷的中心找到冬天爺爺。找那棵樹就對了。', `FemaleText_loc7`='Encontrarás al Gran Padre Invierno en el centro del Valle de la Fuerza. Busca el árbol.' WHERE `ID`=16215;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='북쪽에 사는 파란색 피부의 종족에 대한 소문이요? 아마도 또 다른 트롤일 겁니다.', `MaleText_loc4`='据说北方又出现了一些蓝皮肤的家伙？也许只是更多的巨魔而已。', `MaleText_loc5`='謠傳藍色皮膚的人在北邊?或許只是食人妖而已。', `MaleText_loc7`='¿Los rumores dicen que hay pieles azules en el norte? Puede que sean más trols.', `FemaleText_loc1`='북쪽에 사는 파란색 피부의 종족에 대한 소문이요? 아마도 또 다른 트롤일 겁니다.', `FemaleText_loc4`='据说北方又出现了一些蓝皮肤的家伙？也许只是更多的巨魔而已。', `FemaleText_loc5`='謠傳藍色皮膚的人在北邊?或許只是食人妖而已。', `FemaleText_loc7`='¿Los rumores dicen que hay pieles azules en el norte? Puede que sean más trols.' WHERE `ID`=16216;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달숲에서 달의 축제 행사 중 가장 멋진 순서가 진행되고 있소이다. 그렇다고 그곳까지 걸어갈 필요는 없소. 지혜의 골짜기에서 드루이드들이 순간이동 서비스를 제공하고 있으니 말이오.', `MaleText_loc4`='最精彩的春节庆典正在月光林地举行。当然你不用跋山涉水走去那里，智慧谷的德鲁伊们可以直接传送你过去。', `MaleText_loc5`='最驚人的新年節慶派對在月光林地舉行。不過，不要用走的，在智慧谷的德魯伊們可以傳送你到那裡。', `MaleText_loc7`='La mejor fiesta del Festival Lunar se celebra en Claro de la Luna. No vayas hasta allí andando; los druidas del Valle de la Sabiduría te pueden llevar.', `FemaleText_loc1`='달숲에서 달의 축제 행사 중 가장 멋진 순서가 진행되고 있답니다. 그렇다고 그곳까지 걸어갈 필요는 없어요. 지혜의 골짜기에서 드루이드들이 순간이동 서비스를 제공하고 있으니 말이죠.', `FemaleText_loc4`='最精彩的春节庆典正在月光林地举行。当然你不用跋山涉水走去那里，智慧谷的德鲁伊们可以直接传送你过去。', `FemaleText_loc5`='最驚人的新年節慶派對在月光林地舉行。不過，不要用走的，在智慧谷的德魯伊們可以傳送你到那裡。', `FemaleText_loc7`='La mejor fiesta del Festival Lunar se celebra en Claro de la Luna. No vayas hasta allí andando; los druidas del Valle de la Sabiduría te pueden llevar.' WHERE `ID`=16217;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 야생이 숨 쉬고 있는 나그란드의 평야는 지금까지 제가 경험한 최고의 사냥터를 선사하고 있습니다.', `MaleText_loc4`='纳格兰的原始大草原是我所见过的最好的狩猎地点。', `MaleText_loc5`='納葛蘭的原始平原是我所經歷過提供最多和最好的狩獵區。', `MaleText_loc7`='Las agrestes praderas de Nagrand son el mejor lugar para ir a cazar.' WHERE `ID`=16218;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생선 좋아하세요? 저는 생선을 취급하고 있습니다. 신선한 물고기 맛을 즐기신다면 와서 맛이라도 한번 보고 가세요.', `MaleText_loc4`='你喜欢鱼吗，$r？我这里有鱼，最新鲜的鱼，过来看看我的货物吧。', `MaleText_loc5`='你喜歡魚嗎，$r?我這裡有魚。如果你喜歡新鮮的魚，最新鮮的，過來並且看看我的物品。', `MaleText_loc7`='¿Te gusta el pescado, $r? Tengo pescado. Si te gusta el pescado fresco, fresquísimo, ven a ver lo que tengo.' WHERE `ID`=16219;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저에게는 당신을 도울 방법이 없습니다. 어둠의 문 남쪽에 있는 얼라이언스의 그리핀 조련사를 찾아가 보십시오.', `MaleText_loc4`='我没法帮你，请跟黑暗之门南面的狮鹫管理员交谈。', `MaleText_loc5`='我不能幫助你，請與黑暗之門南邊的獅鷲獸管理員談談吧。', `MaleText_loc7`='No puedo ayudarte. Habla con el maestro de grifos del lado sur del Portal Oscuro.', `FemaleText_loc1`='저에게는 당신을 도울 방법이 없습니다. 어둠의 문 남쪽에 있는 얼라이언스의 그리핀 조련사를 찾아가 보십시오.', `FemaleText_loc4`='我没法帮你，请跟黑暗之门南面的狮鹫管理员交谈。', `FemaleText_loc5`='我不能幫助你，請與黑暗之門南邊的獅鷲獸管理員談談吧。', `FemaleText_loc7`='No puedo ayudarte. Habla don el maestro de grifos del lado sur del Portal Oscuro.' WHERE `ID`=16220;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저에게는 당신을 도울 방법이 없습니다. 어둠의 문 북쪽에 있는 호드의 와이번 조련사를 찾아가 보십시오.', `MaleText_loc4`='我没法帮你，请跟黑暗之门北面的双足飞龙管理员交谈。', `MaleText_loc5`='我不能幫助你，請與黑暗之門北邊的雙足飛龍管理員談談吧。', `MaleText_loc7`='No puedo ayudarte, habla con el maestro de jinetes del viento en la parte norte de El Portal Oscuro.', `FemaleText_loc1`='저에게는 당신을 도울 방법이 없습니다. 어둠의 문 북쪽에 있는 호드의 와이번 조련사를 찾아가 보십시오.', `FemaleText_loc4`='我没法帮你，请跟黑暗之门北面的双足飞龙管理员交谈。', `FemaleText_loc5`='我不能幫助你，請與黑暗之門北邊的雙足飛龍管理員談談吧。', `FemaleText_loc7`='No puedo ayudarte, habla con el maestro de jinetes del viento en la parte norte de El Portal Oscuro.' WHERE `ID`=16222;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절대로 이 뒤틀린 드레나이들의 눈을 똑바로 바라보지 마십시오. 제 생각에 그들은 마음만 먹으면 당신의 영혼을 흡수할 수도 있을 거 같거든요!', `MaleText_loc4`='永远不要直视破碎者的眼睛。我认为，如果他们愿意的话，他们可以把你的灵魂从眼中抽出来！', `MaleText_loc5`='絕不能直接注視這些破碎者的眼睛。我認為他們能把你的靈魂直接吸出來，如果他們想要的話!', `MaleText_loc7`='Nunca mires a esos Tábidos directamente a los ojos. ¡Creo que te pueden succionar el alma si quieren!' WHERE `ID`=16223;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 앞에서 비켜라, 꼬마야! 내가 훈련 중인 게 안 보이느냐? 그래, 너는 다음 대의 전쟁망치 용사가 될 수 있을 것이다.$B$B맞다, 나는 오래된 웃는 해골 폐허의 북쪽에 있는 피의 투기장에 참가할 준비가 거의 끝났다. 하지만 꿈도 꾸지 말거라, 꼬마야. 너는 아직 너무 약하다. 투기장 진행자인 굴그토크는 네가 그곳에서 싸우는 것은 고사하고 훔쳐보는 것도 허락하지 않을 것이다.$B$B이제 녀석이 널 때려눕히기 전에 때려눕혀라.', `MaleText_loc4`='从我面前走开，孩子！你没有看到我在训练吗？没错，我会成为下一个战槌勇士的。$B$B是的，我差不多准备好去古老的鲜血竞技场参加挑战了。但是你想都不要想，孩子。你实在太弱了。竞技场的报幕员古尔戈索克甚至都不会让你偷看正在进行的战斗。$B$B闪远点。', `MaleText_loc5`='離開我的視線，孩子!你看不見我正在訓練嗎?就是我，我將是下一名戰槌勇士。$B$B呀，我就快要準備就緒然後就能前往舊獰笑骷髏廢墟的北面的血色競技場了。但是想都不要想，孩子。你太弱了。葛爾薩克，競技場廣播員，甚至不會讓你偷看一下競技場，更不用說在它裡面的戰鬥。$B$B現在，在它擊敗你之前，先擊敗它。', `MaleText_loc7`='¡Quítate de en medio, $gniñato:niñata;! ¿No ves que estoy entrenando? Es cierto; el tuyo será el siguiente campeón de Mazo de Guerra.$B$BSí, estoy listo para El Círculo de Sangre de las viejas Ruinas Riecráneos. Ni lo intentes, $gniñato:niñata;. Eres demasiado débil. Gurgthock, el comentarista del círculo no te dejará ni acercarte al foso. Y no digamos luchar.$B$BY ahora, golpea antes de que te golpee.' WHERE `ID`=16224;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너 자신을 보거라. 너는 덩치가 크지도 않고 강하지도 않다... 네가 피의 투기장의 결투에 참가해서 전쟁망치 용사와 맞설 수 있을 만큼 강하다고 생각하느냐?$B$B<소리 내어 웃는 투기장 투사>$B$B별로 그럴 것 같지는 않지만 네가 얼마나 강한지 시험해 보고 싶다면 위치를 알려 주마. 북쪽을 향해 한참을 가다 보면 나그란드와 장가르 습지대를 구분하는 산맥 반대편에 피의 투기장이 있다. 굴그토크가 오래된 웃는 해골 폐허에서 경기를 주관하고 있으며 상품도 지급한다. 상품 얘기가 나왔으니 말인데 올해는 엄청난 상품이 준비되어 있다는 말을 들었다!', `MaleText_loc4`='好吧，看看你自己。你觉得自己够强壮吗？或是你觉得你已经强壮到足以挑战鲜血竞技场的战槌勇士了？$B$B<斗士大笑起来。>$B$B不大可能，但你如果非常想验证一下你的力量，就朝北方一直走，在分割纳格兰和赞加沼泽的山脚之下，你可以找到鲜血竞技场。旧嘲颅废墟的古尔戈索克掌管着那里，他同样也掌管着奖赏。说到奖赏，我听说这个赛季的奖品非常棒！', `MaleText_loc5`='好，看看你。你不是高大和強壯的...或許你認為你強壯到足以走進血色競技場，並且面對戰槌勇士嗎?$B$B<競技場鬥士笑了。>$B$B不是很可能，不過如果你想要試試你力量，血色競技場的位置是遠北方，面對著分隔納葛蘭和贊格沼澤的山脈。葛爾薩克在舊獰笑骷髏廢墟經營表演，而他負責發放獎品。談到獎品，我聽到這季的獎品令人難以置信!', `MaleText_loc7`='Vaya, vaya. Qué grande y fuerte eres... ¿Crees que eres lo suficientemente fuerte como para entrar en El Círculo de Sangre y enfrentarte al campeón Mazo de Guerra?$B$B<El luchador del foso se ríe.>$B$BNo lo creo, pero si alguna vez quieres poner a prueba tu fuerza, El Círculo de Sangre está en el norte, justo en las montañas que dividen Nagrand y la Marisma de Zangar. Gurgthock es quien se encarga del espectáculo en las viejas Ruinas Riecráneos y también es quien entrega los premios. Y, hablando de premios, ¡he oído que los de esta temporada son increíbles!' WHERE `ID`=16225;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오오! 저 근육 좀 봐!', `MaleText_loc4`='哇！看看他的肌肉！', `MaleText_loc5`='哇!看看他的肌肉!', `MaleText_loc7`='¡Vaya! ¡Mira qué músculos!', `FemaleText_loc1`='오오! 저 근육 좀 봐요!', `FemaleText_loc4`='哇！看看他的肌肉！', `FemaleText_loc5`='哇!看看他的肌肉!', `FemaleText_loc7`='¡Vaya! ¡Mira qué músculos!' WHERE `ID`=16226;
