UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 훈련된 강인한 신체의 소유자잖아!', `MaleText_loc4`='他真是训练有素！', `MaleText_loc5`='他被訓練的非常好!', `MaleText_loc7`='¡Está tan bien disciplinado!', `FemaleText_loc1`='잘 훈련된 강인한 신체의 소유자잖아!', `FemaleText_loc4`='他真是训练有素！', `FemaleText_loc5`='他被訓練的非常好!', `FemaleText_loc7`='¡Está tan bien disciplinado!' WHERE `ID`=16237;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 저런 능력을 발휘한다지?', `MaleText_loc4`='他是怎么做到的？', `MaleText_loc5`='他怎麼做到的?', `MaleText_loc7`='¿Cómo lo hace?', `FemaleText_loc1`='어떻게 저런 능력을 발휘한다지요?', `FemaleText_loc4`='他是怎么做到的？', `FemaleText_loc5`='他怎麼做到的?', `FemaleText_loc7`='¿Cómo lo hace?' WHERE `ID`=16238;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나그란드에서 뭘 하는 거지, 쓰레기 같은 녀석? 대답해라!', `MaleText_loc4`='你来纳格兰干什么，混蛋？回答我！', `MaleText_loc5`='你在納葛蘭做什麼，骯髒的東西?回答我!', `MaleText_loc7`='¿Qué estás haciendo en Nagrand, escoria? ¡Responde!' WHERE `ID`=16239;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 찾고 있나, 혈기사 친구? 대답하지 않으면 내 잔인함을 탓하게 될 것이다.', `MaleText_loc4`='你的目的是什么，血骑士？快说，否则你可要受皮肉之苦了。', `MaleText_loc5`='你的目地是什麼，血騎士?講出來，否則這些野獸將會處罰你。', `MaleText_loc7`='¿Qué quieres, Caballero de sangre? Habla, o los toscos te castigarán.' WHERE `ID`=16240;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 칸을 향해 눈썹을 치켜 올립니다.', `MaleText_loc4`='%s对克安挑了挑眉毛。', `MaleText_loc5`='%s對卡恩深感驚訝。', `MaleText_loc7`='%s levanta una ceja a Khan.', `FemaleText_loc1`='%s|1이;가; 칸을 향해 눈썹을 치켜 올립니다.', `FemaleText_loc4`='%s对克安挑了挑眉毛。', `FemaleText_loc5`='%s對卡恩深感驚訝。', `FemaleText_loc7`='%s levanta una ceja a Khan.' WHERE `ID`=16241;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 마치 혈기사에게 가까이 접근하기라도 한 듯 무릎을 꿇습니다.', `MaleText_loc4`='%s跪了下来，好像要靠近血骑士。', `MaleText_loc5`='%s跪下來為了更接近血騎士。', `MaleText_loc7`='%s se arrodilla como para acercarse al Caballero de sangre.' WHERE `ID`=16242;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놀랐나? 무슨 생각을 했지? 저 드레나이가 포로들을 안 때리던가?', `MaleText_loc4`='很吃惊吗？你以为怎样？德莱尼人不会对他们的囚犯用刑？', `MaleText_loc5`='驚訝嗎?你認為怎樣?德萊尼不拷打他們的囚犯嗎?', `MaleText_loc7`='¿Te sorprende? ¡¿Que pensabas qué?! ¿Que los draenei no maltratan a sus prisioneros?' WHERE `ID`=16243;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 생각이 맞다. 우리는 포로들을 때리지 않는다. 하지만 뒤틀린 드레나이는 폭력을 아무렇지도 않게 생각하지. 너도 알겠지만 그들은 잔인하다...', `MaleText_loc4`='你说对了，我们不会殴打囚犯。但破碎者们可不管这一套。你看，毕竟他们是野蛮人……', `MaleText_loc5`='你是對的。我們不拷打我們的囚犯。破碎者，另一方面，對暴力可是一點問題都沒有。你知道，畢究...他們是野蠻人...', `MaleText_loc7`='Pues tienes razón. No maltratamos a nuestros prisioneros. Los Tábidos, al contrario, no tienen problemas con la violencia. Verás, después de todo son unos brutos...' WHERE `ID`=16244;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이놈이 입을 열 때까지 두들겨라...', `MaleText_loc4`='揍到这个混蛋开口为止……', `MaleText_loc5`='拷打這骯髒東西，直到它說出來為止...', `MaleText_loc7`='Golpea a esta escoria hasta que hable...' WHERE `ID`=16245;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 고개를 끄덕입니다.', `MaleText_loc4`='%s点了点头。', `MaleText_loc5`='%s點點頭。', `MaleText_loc7`='%s asiente con la cabeza.' WHERE `ID`=16246;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='심문관이 여기 나그란드에서 이 블러드 엘프들이 무슨 짓을 하고 있는지 알아내기 위해 노력하고 있습니다. 제가 들은 바로 그들은 서쪽의 다이아몬드 광산 오슈군에서 수정 가루를 찾고 있다고 합니다.$B$B보나 마나 교활한 계획이나 사악한 물건을 만드는 데 이용하려는 걸 겁니다...$B$B우리 일을 돕고 이 블러드 엘프들을 막고 싶다면 현재 싸움이 벌어지는 북서쪽의 할라아로 가십시오. 블러드 엘프들과 아르거스의 대리인의 병사들이 전투를 벌이고 있습니다! 싸움에 뛰어들어 정의가 무엇인지 보여 주십시오!', `MaleText_loc4`='审问者想搞清楚这些血精灵在纳格兰干什么。我听说他们是为了西边的钻石山——沃舒古的水晶粉末残渣而来。$B$B毫无疑问，他们想把这些残渣用于某些阴险的计划或是掺进什么调和物里面……$B$B如果你想帮我们查明真相，阻止那些血精灵的话，你必须知道，血精灵们和阿古斯之手的士兵们正在西北部的哈兰发生冲突。加入战斗，让他们看看什么才是正确的！', `MaleText_loc5`='審問者試圖查明這些血精靈正在納葛蘭這裡做些什麼。從我聽到的，他們在追蹤來自歐夏剛，西方的鑽石山，的水晶粉末殘渣。無疑地要用在一些陰險的計畫或者混合物裡的...$b$b假如你願意幫助我們並且阻止這些血精靈的話，衝突現在正在哈剌的西北方發生。血精靈們和阿古斯之手的士兵正在戰鬥!加入他們並且讓他們知道我們的厲害!', `MaleText_loc7`='El interrogador está intentando averiguar lo que han venido a hacer estos elfos de sangre a Nagrand. Por lo que he oído, buscan polvo de cristal de Oshu''gun, la montaña diamante del oeste.$B$BSeguro que es para algún plan retorcido o para algún brebaje...$B$BSi quieres ayudarnos a detener a esos elfos de sangre, ve hacia el noroeste, a Halaa. ¡Los soldados de la Mano de Argus se están enfrentando a los elfos de sangre! ¡Vete y demuéstrales lo que vales!', `FemaleText_loc1`='심문관이 여기 나그란드에서 이 블러드 엘프들이 무슨 짓을 하고 있는지 알아내기 위해 노력하고 있습니다. 제가 들은 바로 그들은 서쪽의 다이아몬드 광산 오슈군에서 수정 가루를 찾고 있다고 합니다.$B$B보나 마나 교활한 계획이나 사악한 물건을 만드는 데 이용하려는 걸 겁니다...$B$B우리 일을 돕고 이 블러드 엘프들을 막고 싶다면 현재 싸움이 벌어지는 북서쪽의 할라아로 가십시오. 블러드 엘프들과 아르거스의 대리인의 병사들이 전투를 벌이고 있습니다! 싸움에 뛰어들어 정의가 무엇인지 보여 주십시오!', `FemaleText_loc4`='审问者想搞清楚这些血精灵在纳格兰干什么。我听说他们是为了西边的钻石山——沃舒古的水晶粉末残渣而来。$B$B毫无疑问，他们想把这些残渣用于某些阴险的计划或是掺进什么调和物里面……$B$B如果你想帮我们查明真相，阻止那些血精灵的话，你必须知道，血精灵们和阿古斯之手的士兵们正在西北部的哈兰发生冲突。加入战斗，让他们看看什么才是正确的！', `FemaleText_loc5`='審問者試圖查明這些血精靈正在納葛蘭這裡做些什麼。從我聽到的，他們在追蹤來自歐夏剛，西方的鑽石山，的水晶粉末殘渣。無疑地要用在一些陰險的計畫或者混合物裡的...$b$b假如你願意幫助我們並且阻止這些血精靈的話，衝突現在正在哈剌的西北方發生。血精靈們和阿古斯之手的士兵正在戰鬥!加入他們並且讓他們知道我們的厲害!', `FemaleText_loc7`='El interrogador está intentando averiguar lo que han venido a hacer estos elfos de sangre a Nagrand. Por lo que he oído, buscan polvo de cristal de Oshu''gun, la montaña diamante del oeste.$B$BSeguro que es para algún plan retorcido o para algún brebaje...$B$BSi quieres ayudarnos a detener a esos elfos de la sangre, ve hacia el noroeste, a Halaa. ¡Los soldados de la Mano de Argus se están enfrentando a los elfos de sangre! ¡Vete y demuéstrales lo que vales!' WHERE `ID`=16247;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드레나이가 돌아왔네! 드레나이들이 서쪽 길을 순찰하던 나의 정예 늑대기병 두 명을 공격했네만 여지없이 우리가 그 전투에서 승리했지.$B$B무슨 일이 벌어지고 있는지는 잘 모르겠지만 내 정찰병들의 말에 따르면 할라아 전역에 블러드 엘프들과 드레나이가 있다고 하네. 내가 블러드 엘프들을 좋아하는 것은 아니지만 드레나이를 싫어하는 것은 확실하지. 할라아에서 드레나이나 녀석들의 동맹을 발견하면 날 위해 녀석들을 해치워 주게.$B$B할라아는 서쪽에 있네... 자네가 지금 당장 가고 싶어할까 봐 말해 주는 걸세.', `MaleText_loc4`='德莱尼人又来了！他们偷袭了我们两名正在西边道路上巡逻的狼骑兵。不用说，我们赢了。$B$B现在我不确定发生了什么，但据我的斥候说，哈兰到处都是血精灵和德莱尼人。我不喜欢血精灵，至于德莱尼人，我恨死他们了。如果你在哈兰看到德莱尼人或是任何他们的盟友，就帮我狠狠教训他们。$B$B如果你现在就要去……哈兰就在西面。', `MaleText_loc5`='德萊尼回來了!當他們正在外巡邏西方的道路時，這個小組偷襲我最好的兩名狼騎士。不用多說，我們在那次衝突中勝利了。$B$B現在我不能確定到底發生了什麼事，但我的斥候告訴我，血精靈和德萊尼遍及整個哈剌。我不是血精靈愛好者，但德萊尼卻是我所厭惡的。如果你在哈剌看見德萊尼或者他們的盟友，一定要為我把他們狠狠的教訓一頓。$B$B哈剌的位置是這裡的西方...如果你現在要去的話。', `MaleText_loc7`='¡Los draenei han vuelto! Ese grupo se enfrentó a una patrulla formada por dos de mis mejores caballeros lobo. Por supuesto, salimos victoriosos de esa escaramuza.$B$BNo sé muy bien lo que está pasando, pero según mis patrullas, todo Halaa está lleno de draenei y elfos de sangre. No me gustan mucho los elfos de sangre, pero si hay algo que de verdad odio, son los draenei. Si ves a algún draenei o a alguno de sus aliados en Halaa, asegúrate de patearles el culo de mi parte.$B$BHalaa está al oeste. Por si querías ir ahora, digo.', `FemaleText_loc1`='드레나이가 돌아왔네! 드레나이들이 서쪽 길을 순찰하던 나의 정예 늑대기병 두 명을 공격했네만 여지없이 우리가 그 전투에서 승리했지.$B$B무슨 일이 벌어지고 있는지는 잘 모르겠지만 내 정찰병들의 말에 따르면 할라아 전역에 블러드 엘프들과 드레나이가 있다고 하네. 내가 블러드 엘프들을 좋아하는 것은 아니지만 드레나이를 싫어하는 것은 확실하지. 할라아에서 드레나이나 녀석들의 동맹을 발견하면 날 위해 녀석들을 해치워 주게.$B$B할라아는 서쪽에 있네... 자네가 지금 당장 가고 싶어할까 봐 말해 주는 걸세.', `FemaleText_loc4`='德莱尼人又来了！他们偷袭了我们两名正在西边道路上巡逻的狼骑兵。不用说，我们赢了。$B$B现在我不确定发生了什么，但据我的斥候说，哈兰到处都是血精灵和德莱尼人。我不喜欢血精灵，至于德莱尼人，我恨死他们了。如果你在哈兰看到德莱尼人或是任何他们的盟友，就帮我狠狠教训他们。$B$B如果你现在就要去……哈兰就在西面。', `FemaleText_loc5`='德萊尼回來了!當他們正在外巡邏西方的道路時，這個小組偷襲我最好的兩名狼騎士。不用多說，我們在那次衝突中勝利了。$B$B現在我不能確定到底發生了什麼事，但我的斥候告訴我，血精靈和德萊尼遍及整個哈剌。我不是血精靈愛好者，但德萊尼卻是我所厭惡的。如果你在哈剌看見德萊尼或者他們的盟友，一定要為我把他們狠狠的教訓一頓。$B$B哈剌的位置是這裡的西方...如果你現在要去的話。', `FemaleText_loc7`='¡Los draenei han vuelto! Este grupo se enfrentó a una patrulla con dos de mis mejores caballeros lobo. Por supuesto, salieron victoriosos de esa escaramuza.$B$BNo sé muy bien lo que está pasando, pero según mis patrullas, todo Halaa está lleno de draenei y elfos de sangre. No me gustan mucho los elfos de sangre, pero si hay algo que de verdad odio, son los draenei. Si ves a draenei o a alguno de sus aliados en Halaa, asegúrate de patearles el culo de mi parte.$B$BHalaa está al oeste. Por si querías ir ahora, digo.' WHERE `ID`=16248;
