UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저자들이 달아나기 전에 해치워라!', `MaleText_loc4`='别让他们跑了！杀了他们！', `MaleText_loc5`='在他們逃離之前，殺死他們!', `MaleText_loc7`='¡Matadles antes de que se escapen!', `FemaleText_loc1`='저자들이 달아나기 전에 해치워라!', `FemaleText_loc4`='别让他们跑了！杀了他们！', `FemaleText_loc5`='在他們逃離之前，殺死他們!', `FemaleText_loc7`='¡Matadles antes de que se escapen!' WHERE `ID`=16250;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 너무 많은 걸 알고 있군! 절대 살려둘 수 없다!', `MaleText_loc4`='你知道得太多了！', `MaleText_loc5`='你知道的太多!', `MaleText_loc7`='¡Sabes demasiado!', `FemaleText_loc1`='넌 너무 많은 걸 알고 있군! 절대 살려둘 수 없다!', `FemaleText_loc4`='你知道得太多了！', `FemaleText_loc5`='你知道的太多!', `FemaleText_loc7`='¡Sabes demasiado!' WHERE `ID`=16251;
