UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cffffff00얼라이언스 척후병이 전투 깃발을 나눠 주고 있습니다.|r', `MaleText_loc4`='|cffffff00联盟战地斥候正在发放军旗。|r', `MaleText_loc5`='|cffffff00聯盟戰場斥候現在開始發送戰旗。|r', `MaleText_loc7`='|cffffff00El Explorador de campo de la Alianza está entregando estandartes de batalla.|r' WHERE `ID`=16287;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cffffff00호드 척후병이 전투 깃발을 나눠 주고 있습니다.|r', `MaleText_loc4`='|cffffff00部落战地斥候正在发放军旗。|r', `MaleText_loc5`='|cffffff00部落戰場斥候現在開始發送戰旗。|r', `MaleText_loc7`='|cffffff00El Explorador de campo de la Horda está entregando estandartes de batalla.|r' WHERE `ID`=16288;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 이미 쌍둥이 첨탑 폐허를 손에 넣었다! 거기 멍하니 있지 말고, 가서 폐허를 방어하라!', `MaleText_loc4`='我们已经占领了双塔废墟！快去参与防守！', `MaleText_loc5`='我們已經控制了雙塔廢墟!快前往保衛它!', `MaleText_loc7`='¡Ya tenemos el control de las Ruinas de las Agujas Gemelas! Salid ahí afuera y defended lo que es nuestro.' WHERE `ID`=16289;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 이미 쌍둥이 첨탑 폐허를 손에 넣었다! 거기 멍하니 있지 말고, 가서 폐허를 방어하라!', `MaleText_loc4`='我们已经占领了双塔废墟！快去参与防守！', `MaleText_loc5`='我們已經控制了雙塔廢墟!快前往保衛它!', `MaleText_loc7`='¡Ya tenemos el control de las Ruinas de las Agujas Gemelas! Salid ahí afuera y defended lo que es nuestro.' WHERE `ID`=16290;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 오래된 드레나이의 게시판은 쿠레나이가 다시 깨끗하게 닦아서 공지 사항과 현상금을 게시하는 데 사용하고 있습니다.', `MaleText_loc4`='这块陈旧的德莱尼公告板被库雷尼重新打磨过了，现在用来张贴公告和悬赏名单。', `MaleText_loc5`='這塊舊的德萊尼板子已經被卡爾奈翻修，並且現在被用來公佈通告和賞金。', `MaleText_loc7`='Este viejo tablón draenei ha sido modificado por los Kurenai y ahora se usa para publicar anuncios y recompensas.' WHERE `ID`=16291;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='병사들이여! 정렬하라!', `MaleText_loc4`='士兵们！集合！', `MaleText_loc5`='士兵們!集合!', `MaleText_loc7`='¡Tropas! ¡A formar!' WHERE `ID`=16292;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠사냥꾼 덴자이는 이 게시판을 사용하여 중요한 공지 사항이나 자브라진의 적에게 걸린 새로운 현상금을 게시하고 있습니다.', `MaleText_loc4`='暗影猎手德恩加用这块公告板来张贴重要的公告和萨布拉金的新悬赏名单。', `MaleText_loc5`='暗影獵人丹傑在這塊板子上公佈關於薩布拉金仇敵賞金的相關重要通告和消息。', `MaleText_loc7`='El cazador de las Sombras Denjai usa este tablón para publicar anuncios importantes y noticias de recompensas sobre enemigos de Zabra''jin.' WHERE `ID`=16293;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영광스럽게도 존경하는 대수도자이신 알모넨 님의 말씀을 듣게 되었다. 모두 무릎을 꿇도록.', `MaleText_loc4`='我们很荣幸能聆听到尊敬的资深学者奥蒙纳的教诲。请坐下。', `MaleText_loc5`='我們很高興能夠聽到敬畏的大隱士艾蒙南的聲音。下跪。', `MaleText_loc7`='Nos honra recibir noticias de nuestro venerado gran anacoreta Almonen. Arrodillaos.' WHERE `ID`=16294;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='병사들이여! 이만 해산!', `MaleText_loc4`='士兵们！散开！', `MaleText_loc5`='士兵們!散開!', `MaleText_loc7`='¡Tropas! ¡Romped filas!' WHERE `ID`=16295;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='과일 상인! 아직도 네 마차가 우리 영업을 방해하고 있다! 앞으로 한 시간을 줄 테니 우리 구역에서 마차를 빼라. 우리 인내심을 시험하지 마라!', `MaleText_loc4`='水果商人！你的小车仍然挡着我们的路。我再给你一个小时，把它从我们的地盘挪开。不要再考验我们的耐心！', `MaleText_loc5`='水果小販!!!你的車仍然檔到我們的路!我們再給你一個小時將它從我們的地區移開。不要再測試我們的耐性!', `MaleText_loc7`='¡¡¡VENDEDOR DE FRUTA!!! ¡Tu carro sigue en nuestro camino! Te damos una hora más para sacarlo de nuestra zona. ¡No sigas poniendo a prueba nuestra paciencia!', `FemaleText_loc1`='과일 상인! 아직도 네 마차가 우리 영업을 방해하고 있다! 앞으로 한 시간을 줄 테니 우리 구역에서 마차를 빼라. 우리 인내심을 시험하지 마라!', `FemaleText_loc4`='水果商人！你的小车仍然挡着我们的路。我再给你一个小时，把它从我们的地盘挪开。不要再考验我们的耐心！', `FemaleText_loc5`='水果小販!!!你的車仍然檔到我們的路!我們再給你一個小時將它從我們的地區移開。不要再測試我們的耐性!', `FemaleText_loc7`='¡¡¡VENDEDOR DE FRUTA!!! ¡Tu carro sigue en nuestro camino! Te damos una hora más para sacarlo de nuestra zona. ¡No sigas poniendo a prueba nuestra paciencia!' WHERE `ID`=16296;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 과일 상인은 목숨이 아깝지도 않다는 말인가? 시간이 얼마 남지 않았다, 과일 상인!', `MaleText_loc4`='这个水果商人不要命了吗？你快没时间了！水果商人！！', `MaleText_loc5`='這個水果小販不珍惜他的生命嗎?你沒有時間了，水果小販!!', `MaleText_loc7`='¿Acaso este vendedor de fruta no valora su vida? ¡¡TE ESTÁS QUEDANDO SIN TIEMPO, VENDEDOR DE FRUTA!!', `FemaleText_loc1`='이 과일 상인은 목숨이 아깝지도 않다는 말인가? 시간이 얼마 남지 않았다, 과일 상인!', `FemaleText_loc4`='这个水果商人不要命了吗？你快没时间了！水果商人！！', `FemaleText_loc5`='這個水果小販不珍惜他的生命嗎?你沒有時間了，水果小販!!', `FemaleText_loc7`='¿Acaso este vendedor de fruta no valora su vida? ¡¡TE ESTÁS QUEDANDO SIN TIEMPO, VENDEDOR DE FRUTA!!' WHERE `ID`=16297;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하! 방금 사과 하나를 으깨버렸다, 과일 상인! 이걸로 끝날 거라는 생각은 하지 마라!', `MaleText_loc4`='哈！我碾碎了一个苹果，水果商人！这不会是最后一个！！', `MaleText_loc5`='哈!我壓碎一個蘋果，水果小販!這將不是最後一個!!', `MaleText_loc7`='¡JA! ¡HE APLASTADO UNA MANZANA, VENDEDOR DE FRUTA! ¡¡Y NO SERÁ LA ÚLTIMA!!', `FemaleText_loc1`='하하! 방금 사과 하나를 으깨버렸다, 과일 상인! 이걸로 끝날 거라는 생각은 하지 마라!', `FemaleText_loc4`='哈！我碾碎了一个苹果，水果商人！这不会是最后一个！！', `FemaleText_loc5`='哈!我壓碎一個蘋果，水果小販!這將不是最後一個!!', `FemaleText_loc7`='¡JA! ¡HE APLASTADO UNA MANZANA, VENDEDOR DE FRUTA! ¡¡Y NO SERÁ LA ÚLTIMA!!' WHERE `ID`=16298;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 형제와 자매들이여, 그대들의 훈련 모습을 지켜봤습니다.', `MaleText_loc4`='你们的苦练我都看在眼里，年轻的兄弟姐妹们。', `MaleText_loc5`='我一直在觀察你們的訓練，我年輕的兄弟姐妹。', `MaleText_loc7`='He estado observando su entrenamiento, mis jóvenes hermanos y hermanas.' WHERE `ID`=16299;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 평생 이렇게 훈련이 잘된 군대는 본 적이 없어요.', `MaleText_loc4`='像你们这样训练有素的部队，我还是第一次看见。', `MaleText_loc5`='從我出生至今還沒見過如此訓練有素的部隊。', `MaleText_loc7`='No he visto a un grupo de soldados mejor entrenados en toda mi vida.' WHERE `ID`=16300;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 전장에서 적과 맞설 시간이 왔습니다. 제가 말하는 이 순간에도 우리의 형제와 자매들이 쿠엘다나스 섬에 있는 킬제덴의 군대가 몰려오지 못하도록 맞서 싸우고 있습니다.', `MaleText_loc4`='现在是让你上战场面对我们敌人的时刻了。正如我所说的那样，我们的兄弟姐妹们正在奎尔丹纳斯岛上为抵挡基尔加丹而战斗着。', `MaleText_loc5`='在戰場上面對我們敵人的時刻現在已經到來。就像我對我的同胞們說的，在奎爾達納斯之島上擊退基爾加丹吧。', `MaleText_loc7`='Ha llegado la hora de que os enfrentéis a nuestro enemigo en el campo de batalla. Mientras estoy aquí hablando, nuestros hermanos y hermanas luchan para eliminar a los ejércitos de Kil''jaeden de esta Isla de Quel''Danas.' WHERE `ID`=16301;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼 속의 어둠이 그 어느 때보다도 가깝게 너희를 끌어당기고 있다...', `MaleText_loc4`='你灵魂中的黑暗会使你越陷越深……', `MaleText_loc5`='在你靈魂裡的黑暗面將你拉得很近...', `MaleText_loc7`='La oscuridad que yace en sus almas los acerca aún más...' WHERE `ID`=16302;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여러분 모두 잘 알고 있듯이 우리 종족이 걸어온 길은 그리 순탄하지만은 않았습니다. 블러드 엘프와 드레나이가 보여주지 않았습니까?', `MaleText_loc4`='就像你们都熟知的那样，我们人民所走的道路并不是一帆风顺。血精灵和德莱尼人都同样经历了试炼。', `MaleText_loc5`='正如你所知，我們族人的道路絕不是會讓人羨慕之路。血精靈和德萊尼都一樣受到考驗。', `MaleText_loc7`='Como todos sabéis, el camino de nuestro pueblo no ha sido envidiable. Tanto los elfos de sangre como los draenei han sido puestos a prueba.' WHERE `ID`=16303;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 기억하는 역사는 투쟁과 반목의 연속이었습니다.', `MaleText_loc4`='在我们的记忆中，冲突和斗争一直如影随形。', `MaleText_loc5`='從我們有記憶以來，爭鬥和衝突就是我們的忠實同伴。', `MaleText_loc7`='El conflicto y la desolación han sido nuestros únicos compañeros en la vida, hasta donde alcanza nuestra memoria.' WHERE `ID`=16305;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해가 수없이 바뀌고 수많은 세계를 거치는 동안 우리는 성스러운 빛을 포용하고 어둠의 시대가 끝나길 간절히 원했지요. 우리의 점술가 길드 동지들도 그런 포부를 지녔답니다.', `MaleText_loc4`='无数的时光，无尽的探寻，德莱尼人一直渴望与圣光更紧密地相拥，并将那黑暗终结。我们的占星者兄弟们也同样有着如此的雄心壮志。', `MaleText_loc5`='無數年以來，和穿過無數的世界，德萊尼學到要更努力地擁抱聖光和毀滅黑暗。這也是我們占卜者兄弟所抱持的野望。', `MaleText_loc7`='Durante innumerables años y en incontables mundos, los draenei hemos anhelado abrazar mejor la Luz y poner fin a la oscuridad. Es lo mismo que codician nuestros hermanos Arúspices.' WHERE `ID`=16306;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 장담하건대, 분명히 사과가 이것보다는 더 많았다고... 그록!', `FemaleText_loc4`='我要是发誓说我有更多苹果就好了。葛罗克！', `FemaleText_loc5`='我發誓我的蘋果數量應該更多才對。葛羅克!', `FemaleText_loc7`='Juraría que tenía más manzanas. ¡Grok!' WHERE `ID`=16307;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고귀한 나의 형제와 자매들이여, 마침내 우리의 시대가 왔습니다!', `MaleText_loc4`='时机终于来临了，我高贵的兄弟姐妹们，命运就在我们手中！', `MaleText_loc5`='最後我高貴的兄弟姐妹們，我們的時代即將到來!', `MaleText_loc7`='Y ahora, por fin, hermanos y hermanas, ha llegado la hora.' WHERE `ID`=16308;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좀 전에 그대들은 신병으로서 무릎을 꿇었습니다...', `MaleText_loc4`='不久前，你们还是新兵……', `MaleText_loc5`='片刻之前，你像新兵般的跪著...', `MaleText_loc7`='Hace unos segundos os habéis arrodillado como reclutas draenei…' WHERE `ID`=16309;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나의 축복으로 이제 그대들은 성스러운 빛의 자식으로 거듭났습니다!', `MaleText_loc4`='现在，在我的祝福下，你们将成为真正的圣光之子！', `MaleText_loc5`='現在，帶著我的祝福，你是個真正的聖光子民了!', `MaleText_loc7`='Ahora, con mi bendición, ¡os levantaréis como verdaderos Hijos de la Luz!' WHERE `ID`=16310;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형제들이여, 전진하십시오. 성스러운 빛이 어둠을 몰아내기를! 그 책략가는 정의의 심판을 받을 겁니다!', `MaleText_loc4`='前进吧，我的兄弟，愿你们的圣光划破沿途的一切黑暗！欺诈者必将灭亡！', `MaleText_loc5`='向前，我的兄弟。願你的光明可以刺穿那些黑暗!欺詐者必須被繩之以法!', `MaleText_loc7`='Adelante, hermanos, que su Luz atraviese la oscuridad cada vez que se encuentre con ella…' WHERE `ID`=16311;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='응? 방금 누가 뭐라고 했지?', `FemaleText_loc4`='嗯？有人说了什么吗？', `FemaleText_loc5`='啊?有人在說話嗎?', `FemaleText_loc7`='¿Eh? ¿Alguien ha dicho algo?' WHERE `ID`=16312;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='과일이라고? 누가 과일을 사고 싶다고?', `FemaleText_loc4`='水果？有人说他们想要水果吗？', `FemaleText_loc5`='水果?有人說他們想要水果嗎?', `FemaleText_loc7`='¿Fruta? ¿Alguien ha dicho que quiere fruta?' WHERE `ID`=16313;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저 불쌍한 오크가 계속 뭐라고 떠드는 거지? 누가 무슨 일인지 물어봐주는 게 좋지 않을까...', `FemaleText_loc4`='那些可怜的兽人在叫喊什么？谁去看看怎么回事？', `FemaleText_loc5`='那個可憐的獸人在叫喊些什麼?有人該去看看發生了什麼事。', `FemaleText_loc7`='¿Qué grita ese pobre orco? Alguien debería ir a ver qué está pasando.' WHERE `ID`=16314;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='누가 날 불렀나?', `FemaleText_loc4`='有人叫我吗？', `FemaleText_loc5`='有人找我嗎?', `FemaleText_loc7`='¿Alguien me está llamando?' WHERE `ID`=16315;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 저항할 수 없는 유혹이겠지. 그렇지 않나? 좀 더 빠르고 강해지고 싶겠지? 여기 이 아뮬렛을 하나 걸기만 하면 분명 그렇게 될 거야. 어서 이 신비한 물건을 하나 장만하게! 아주 싸게 줄 테니까!', `MaleText_loc4`='啊，你不能拒绝，你能吗？你不能。你能吗？讨论一下嘛。你想变得更快、更高、更强吗？我卖的每一个护身符都绝对有效！过来买一个这样神奇的小玩意吧！半价！', `MaleText_loc5`='啊，你禁不住吧，你可以嗎?想要更好，更強大，更快嗎?這些護符中的每一個都保證可做到我所說的。走向前並且買一個這些奇蹟般的小玩意!以兩倍便宜的價格買到喔!', `MaleText_loc7`='Ahh, ¿no has podido resistirte, eh? ¿Quieres ser mejor, más fuerte y más $grápido:rápida;? Pues eso es lo que hacen cada uno de estos amuletos. ¡Pasa y compra una de estas pequeñas maravillas! ¡No encontrarás nada más barato!' WHERE `ID`=16316;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일단... 물건 좀 보죠.', `MaleText_loc4`='我会……看一看的。', `MaleText_loc5`='我會...看一看。', `MaleText_loc7`='Eh... echaré un vistazo.', `FemaleText_loc1`='일단... 물건 좀 보죠.', `FemaleText_loc4`='我会……看一看的。', `FemaleText_loc5`='我會......看一看。', `FemaleText_loc7`='Eh... echaré un vistazo.' WHERE `ID`=16317;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, $r! 자네에게 딱 맞는 물건이 있어. 정말 용한 수호 부적을 본 적 있나? 우는 애를 잡아 간다는 호랑이처럼 아주 무서운 놈이라고. 자네도 모르게 신기한 재주를 부릴 거야. 자네에게는 꼭 필요한 부적이지. 그리고 내가 판매하는 모든 수호 부적의 품질은 절대 보장한다고!', `MaleText_loc4`='嘿！嘿，$r！我有个东西简直是给你量身定做的！你看到过提克巴朗吗？偷你东西的可怕生物。你所需要的就是我的防盗符咒，保证可以吓走所有的提克巴朗！', `MaleText_loc5`='喂!喂，$r!我剛好有一些東西要給你。你看過提巴蘭嗎?令人感到恐懼的生物，他們大概會偷光你的東西。你需要的是我的提巴蘭護符。保證可避開全部的提巴蘭們!', `MaleText_loc7`='¡Eh! ¡Eh, $r! Tengo justo lo que necesitas. ¿Alguna vez has visto un tikbalang? Son unos bichos muy raros. Les gusta mucho robar. Lo que necesitas es uno de mis protectores contra tikbalangs. ¡Eficacia probada contra tikbalangs!' WHERE `ID`=16318;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 좀 보라고, $c! 보여줄 물건이 있네. 자네에게 꼭 필요한 물건이야. 그게 뭐냐고? 바로 비누야. 어린이용 끈 달린 비누지! 기분을 상하게 할 생각은 없어. 솔직히 자네는 아직 덜 여물지 않았나. 내가 하는 말 알아듣겠지?', `MaleText_loc4`='看这里，$c！我这里有样东西给你，你绝对需要。是块肥皂，是的……而且系在一根绳子上！我没有要冒犯的意思，$G先生:甜心;，但是我相信你知道我在说什么？', `MaleText_loc5`='看這裡，$c!我這有一些東西。正好是你需要的。它是肥皂，是的...並且它綁在一根繩子上!我並無惡意，$G朋友:親愛的;，但你看起來不太年輕，知道我在說什麼嗎?', `MaleText_loc7`='¡Mira eso, $c! Tengo algo pa ti. Justo lo que necesitas. Sí, es jabón... ¡y atado a una cuerda! No te ofendas, $Gtío:cielo;, pero tu perfume no es nada agradable... ya me entiendes.' WHERE `ID`=16319;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상사병에 걸린 것 같군. 도대체 얼마나 특별한 사랑이기에 그토록 침울해졌나? 전혀 걱정할 필요 없네. 내가 파는 이 목걸이를 사서 걸고 나가면 그 누구라도 자네를 사랑할 거야!', `MaleText_loc4`='你看上去很忧愁。是不是某些特殊的人让你如此低落，嗯？不用担心，不用担心。从我这里买一枚勋章吧，他们永远都不会再成为你的问题了，$g伙计:小姐;！', `MaleText_loc5`='你看起來像是患了相思病。某位特殊的人使你感到沮喪，是嗎?不用擔心，不用擔心。從我這裡買個大勳章，當你看見他們時，戴上它，讓他們對你著迷，$G朋友:甜心;!', `MaleText_loc7`='Parece que tienes mal de amores. Esa media naranja tuya te da dolores de cabeza, ¿eh? No preocuparse. Yo te doy este medallón; ¡tú te lo pones cuando estés cerca de quien tú ya sabes y $gtodas:todos; se volverán $gloquitas:loquitos; por ti, $gmorenazo:reina mora;!' WHERE `ID`=16320;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바깥은 참 위험하지... 자네에게 가장 필요한 것이 뭘까? 바로 안전이지. 죽음을 피할 수 있도록 내가 도와주겠어! 이 기적적인 불멸의 광석 목걸이를 목에 걸면 설령 영혼의 세계에 가게 됐더라도 다시 돌아올 수 있다고! 마치 소풍이라도 가듯 자네 시체를 찾아가서 생생한 몸으로 부활하는 거지!', `MaleText_loc4`='到处都有危险，不是吗？知道你需要什么吗？保护。我可以帮你挑战死亡！把这块非凡的石头戴在脖子上，看，如果你可以在灵魂世界找到自己，那么你就能复活！只不过需要一个跑向尸体的过程，然后你就重生了，一个崭新的你！', `MaleText_loc5`='到那邊很危險，不是嗎?知道你需要什麼嗎?保護。我能幫助你對抗死亡本身!在你的脖子上穿戴這魔法護身符，看，然後你將能夠回來，假如你發現你身處幽靈世界!只要快步跑向你的屍體，就能重獲新生!', `MaleText_loc7`='¿Un poco revuelto ahí fuera, eh? ¿Sabes lo que necesitas? Protección. ¡Puedo ayudarte a desafiar a la mismísima muerte! Ponte este fetiche en el cuello, ya verás, ¡y después podrás volver si te encuentras en el mundo de los espíritus! Una pequeña excursión a tu cuerpo, ¡y ya tás, $gfresco:fresca; como una lechuga!' WHERE `ID`=16321;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놀라운 아뮬렛을 구경해보게! 정말 희귀한 작품일세! 오랜 세월에 걸쳐 검증을 받은 그립타 가문의 진정한 솜씨 앞에서는 최신 세공 기술도 어린애 장난에 불과하지! 마법 부적을 저렴한 가격에 구입해서 능력을 향상시킬 절호의 기회라고!', `MaleText_loc4`='多棒的护身符啊！难以置信的古董！那些新来的珠宝工匠们从未尝试过的、格里伏塔的神秘物品！买下这些魔法护身符，提升你的能力吧！很便宜的！', `MaleText_loc5`='驚人的護符!難以置信的古董!新式的珠寶設計師將沒有東西可以試驗，老格利夫塔真正的神秘方法!透過廉價的這些魔法護符改善你自己吧!', `MaleText_loc7`='¡Amuletos impresionantes! ¡Increíblemente curiosos! ¡Los joyeros modernos no saben na de los verdaderos métodos místicos del viejo Griftah! ¡Puedes ser mejor gracias a estos talismanes mágicos! ¡Y a un precio más que módico!' WHERE `ID`=16322;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오게, $r... 던전에 들어가서 위험을 자초하고 싶지는 않겠지? 지저분한 임무, 그리고 또 뭐가 있지? 아무짝에도 쓸모없는 싸구려 장신구? 맙소사, 자네에겐 내 아뮬렛이 필요해. 효과는 내가 장담하네!', `MaleText_loc4`='过来，$r。你不想让你自己在地下城里受到伤害吧，对吗？努力工作，为了什么？一些毫无价值的饰品？不，你所需要的就是一个我制作的护身符。保证有用！', `MaleText_loc5`='過來這裡，$r。你不會想要把你自己置於身陷地城的風險中的，你想嗎?污穢地工作，為什麼?一些沒有價值的小飾物嗎?算了吧，你需要的是我的一個護符。保證有效!', `MaleText_loc7`='Ven pa’cá, $r. ¿No querrás arriesgarte en una mazmorra, verdad? Un trabajo mu sucio, ¿y pa qué? ¿Para una chuchería que no vale pa na? Nooo, lo que necesitas es uno de mis amuletos. ¡Funcionan, te lo garantizo!' WHERE `ID`=16323;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피곤해 보이는군. 자네에게 딱 맞는 물건이 있네. 내가 파는 아뮬렛을 걸면 적들을 휙휙 뛰어넘고 강에서는 물 만난 고기처럼 헤엄칠 수 있다고. 그리고 자네가 먹는 음식에 힘을 불어넣어 순식간에 상처를 아물게 하지!', `MaleText_loc4`='你看上去很疲惫，$c。我有东西给你。这些护身符，它们可以帮你跳跃障碍物和游过河流，就像那是你与生俱来的能力一样。它们让你吃的食物充满能量，让你的伤口在眨眼间就能愈合！', `MaleText_loc5`='你看起來很疲倦，$c。我準備了一些東西給你。這些護符，他們能幫助你越過障礙，並讓你如生於河中般的游泳過河。他們使你吃的食物充滿能量，讓你的傷口在你看見前就癒合!', `MaleText_loc7`='Parece que necesitas descansar, $c. Te voy a dar una cosita. Estos amuletos pueden ayudarte a esquivar obstáculos y a nadar por los ríos como si hubieras nacido para ello. ¡Energizan la comida que comes y hacen que tus heridas se cierren en un instante!' WHERE `ID`=16324;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙습니다! 고맙습니다! 이렇게 환영해 주시다니 정말 감사합니다.', `MaleText_loc4`='谢谢！谢谢！谢谢你如此热烈地欢迎我。', `MaleText_loc5`='謝謝!謝謝!謝謝你們熱情的歡迎。', `MaleText_loc7`='¡Gracias! ¡Gracias! Gracias por una bienvenida tan cálida.' WHERE `ID`=16325;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우와! 이 모든 박수가 절 위한 것입니까? 와주신 모든 분께 감사합니다!', `MaleText_loc4`='哇！这些掌声都是献给我的？感谢你们的到来！', `MaleText_loc5`='哇!所有的掌聲都是給我的嗎?謝謝你們!', `MaleText_loc7`='¡Guau! ¿Todos esos aplausos son para mí? ¡Gracias por venir!' WHERE `ID`=16326;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저를 보러 와주신 모든 분께 감사합니다! 여러분은 오늘 저와 함께 좋은 시간을 보낼 것입니다.', `MaleText_loc4`='谢谢你到这儿来看我！希望你已经准备好享受这个时刻了，我早就迫不及待了。', `MaleText_loc5`='感謝你過來看我!我希望你已準備好渡過美好時光，因為我已準備好。', `MaleText_loc7`='¡Gracias por venir a verme! Espero que estéis preparados para pasároslo bien, porque yo sí que lo estoy.' WHERE `ID`=16327;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘이 제 첫무대이니... 예쁘게 봐주시기 바랍니다.', `MaleText_loc4`='嘿，朋友们，够了够了……那是我第一次。', `MaleText_loc5`='嘿各位，對我不要太嚴格...這是我的第一次。', `MaleText_loc7`='Venga, chicos. No me tratéis así. Es mi primera vez.' WHERE `ID`=16328;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 웃을 준비되셨습니까?!', `MaleText_loc4`='你准备好开怀大笑了吗？', `MaleText_loc5`='你準備好大笑了嗎!', `MaleText_loc7`='¿Listos para soltar carcajadas?' WHERE `ID`=16329;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼간이들...', `MaleText_loc4`='蠢货。', `MaleText_loc5`='蠢蛋。', `MaleText_loc7`='¡Idiotas!' WHERE `ID`=16330;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여러분, 귀여운 꼬마 오크들이 모두 똑같이 생겼다는 사실을 알고 계세요?', `MaleText_loc4`='你有没有注意到那些可爱的兽人孩子看上去全都长得一个样？', `MaleText_loc5`='你有發現過所有可愛的獸人孩子都長的一樣嗎?', `MaleText_loc7`='¿Alguna vez os habéis fijado en cuánto se parecen todos esos niñitos orcos tan monos?' WHERE `ID`=16331;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 노움이 한 타우렌에게 자기가 화산 심장부에 가본 적이 있다고 했답니다.', `MaleText_loc4`='这个侏儒告诉牛头人说，他去过熔火之心。', `MaleText_loc5`='所以這個地精告訴一個牛頭人他去過熔火之心。', `MaleText_loc7`='Un gnomo va y le dice a un tauren que ha estado en el Núcleo de Magma.' WHERE `ID`=16332;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='재미난 수수께끼 하나 내볼까요... 왜 수박에는 물이 많을까요?', `MaleText_loc4`='我有个好问题，为什么西瓜里面有水？', `MaleText_loc5`='我想到個不錯的，為什麼西瓜裡會有水?', `MaleText_loc7`='¡Ah, uno muy bueno! ¿Por qué las sandías tienen un día santo?' WHERE `ID`=16333;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='귀여운 외모를 점점 잃는 것은 참 유감스러운 일이죠. 불모의 땅에는 "옥상에서 떨어진 메주보다 아름다운 것도 없다."라는 격언이라도 있나봐요.', `MaleText_loc4`='他们长大之后就不可爱了，真是糟糕。贫瘠之地的成人礼上大概会执行“爬上大树再狠狠地摔下来”这样的仪式。', `MaleText_loc5`='真可惜，他們不一會兒就變得不那麼可愛了。在貧瘠之地裡一定有一些成年禮叫做，「爬上醜陋的樹並且掉下來。」', `MaleText_loc7`='Es una pena que no sigan siendo monos. Tiene que haber algún tipo de prueba de madurez en Los Baldíos que sea, "Súbete al árbol feo y cáete."' WHERE `ID`=16334;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러자 타우렌이 "그때 넌 소떼 한가운데 빠진 거였어."라고 했답니다.', `MaleText_loc4`='牛头人说，“真是吹牛。”', `MaleText_loc5`='牛頭人說，「還真是多牛啊」。', `MaleText_loc7`='Y el tauren dice, "No te lo crees ni tú."' WHERE `ID`=16335;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 희망이 샘솟는 봄에 씨를 뿌리기 때문이랍니다!', `MaleText_loc4`='因为它们是在春天种植的！', `MaleText_loc5`='因為它們是在春天播種的!', `MaleText_loc7`='¡Porque cuando no te las comes tú día no es nada santo!' WHERE `ID`=16336;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흉내 내기 시간이 돌아왔습니다! 자, 제목은 ''멍청한 타우렌''입니다.', `MaleText_loc4`='演出时间！我把这叫做“愚蠢的牛头人”！', `MaleText_loc5`='模仿時間到了!我稱這個為「愚蠢的牛頭人」。', `MaleText_loc7`='¡¡Hora de las imitaciones!! A esto lo llamo yo, "El tauren idiota."' WHERE `ID`=16337;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='희극 배우가 헛기침을 하며 목을 가다듬습니다.', `MaleText_loc4`='喜剧演员清了清喉咙。', `MaleText_loc5`='喜劇演員清了清他的喉嚨。', `MaleText_loc7`='El cómico se aclara la garganta.' WHERE `ID`=16338;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여성들과 도대체 어떤 관계가 있을까요? 그러니까 그들은 항상...', `MaleText_loc4`='怎么和女人打交道？我的意思是她们就像是……', `MaleText_loc5`='女人有什麼了不起?我是說她們總是...', `MaleText_loc7`='¿Y qué pasa con las mujeres? No sé, es que siempre son como...' WHERE `ID`=16339;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 노움들은 더 상태가 안 좋아요! 그들이 항상 하는 말이...', `MaleText_loc4`='侏儒们更糟！他们一直在说一些……', `MaleText_loc5`='然後地精更壞了!他們總是說一些...', `MaleText_loc7`='¡Y los gnomos son todavía peores! Siempre están diciendo cosas como...' WHERE `ID`=16340;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙습니다! 담당 웨이터에게 팁 주는 것 잊지 마세요! 모두 좋은 밤 되세요.', `MaleText_loc4`='谢谢！别忘记给服务生小费！晚安。', `MaleText_loc5`='謝謝你!別忘了給你的服務生一點小費!晚安各位。', `MaleText_loc7`='¡Gracias! ¡No olvides la propina! Buenas noches, chicos.' WHERE `ID`=16341;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벌써 끝났느냐고요? 여러분은 오늘 정말 좋은 관객이셨습니다. 조심해서 돌아가시고 좋은 밤 되십시오.', `MaleText_loc4`='已经结束了？真不错。路上小心，晚安。', `MaleText_loc5`='它已經結束了嗎?你們表現的很好，各位。路上小心和晚安。', `MaleText_loc7`='¿Ya se ha terminado? Habéis sido un gran público. Volved a casa con cuidado y que tengáis buena noche.' WHERE `ID`=16343;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여러분은 정말 훌륭한 관객입니다! 좋은 밤 되십시오!', `MaleText_loc4`='你们都是最棒的观众！祝你们晚上愉快！', `MaleText_loc5`='你們一直是很棒的觀眾!祝你們有個美好的夜晚!', `MaleText_loc7`='¡Me ha encantado teneros como público! ¡Buenas noches!' WHERE `ID`=16344;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 감사합니다! 계속 박수를 쳐주세요. 아까부터 이 안에 파리 한 마리가 보였는데 여러분 중 한 분이 잡아주시면 좋겠네요! 좋은 밤 되십시오!', `MaleText_loc4`='感谢大家！继续鼓掌，那里有只苍蝇，你们中一定要有人把它拍下来！晚安！', `MaleText_loc5`='謝謝大家!並且一直鼓掌，在這裡有一隻蒼蠅，你們其中一個就快要打到它了!晚安!', `MaleText_loc7`='¡Gracias a todo el mundo! Y seguid aplaudiendo, hay un moscón por ahí y el que lo aplaste tiene premio. ¡Buenas noches!' WHERE `ID`=16345;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대열을 갖추고 저 바보들을 몰아내라!', `MaleText_loc4`='准备战斗，干掉这些蠢货！', `MaleText_loc5`='列隊把這些蠢貨碾碎!', `MaleText_loc7`='¡En fila y aplastaran a esos tontos!' WHERE `ID`=16346;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부대는 정렬하라! 저놈들을 빨리 쓸어내자!', `MaleText_loc4`='列阵！速战速决！', `MaleText_loc5`='列隊!快點把他們解決!', `MaleText_loc7`='¡Formados! ¡Acabemos con ellos rápido!' WHERE `ID`=16347;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 웃음 제조기들은 이만 물러날 시간이네요. 모두 즐거운 밤 되십시오!', `MaleText_loc4`='好吧，是时间取下这些可笑的肌肉了。大家晚安！', `MaleText_loc5`='嗯，是時候將這些喜劇的肌肉拿到別處了。祝你們有一個好夜晚!', `MaleText_loc7`='En fin, ha llegado la hora de que estos músculos tan graciosos se vayan a otra parte. ¡Muy buenas noches!' WHERE `ID`=16348;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투 준비! 오래 끌 싸움은 아니다...', `MaleText_loc4`='准备好！很快就结束了……', `MaleText_loc5`='準備!這應該不會花太多時間...', `MaleText_loc7`='¡Prepárense! No tardaremos mucho…' WHERE `ID`=16349;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가차없이 공격하라! 대열을 갖춰라!', `MaleText_loc4`='不要给他们任何机会！准备战斗！', `MaleText_loc5`='不要對它們手下留情!列隊!', `MaleText_loc7`='¡Sin cuartel! ¡Formados!' WHERE `ID`=16350;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마지막 흉내 내기입니다. 좀 어렵긴 하지만 누군지 알아맞혀 보세요...', `MaleText_loc4`='最后一个模仿。有点难度，但是你们能猜出是谁吗……', `MaleText_loc5`='最後一個模仿。滿難的，但看你能不能猜到他是誰...', `MaleText_loc7`='Una última imitación. Es complicado, pero a ver si podéis adivinar quién es...' WHERE `ID`=16351;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로크 나라쉬! 방어 태세!', `MaleText_loc4`='Lok-Narash！防御阵型！', `MaleText_loc5`='部落衝鋒!防禦姿態!', `MaleText_loc7`='¡Lok-Narash! ¡Posición defensiva!' WHERE `ID`=16352;
