UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엘레크가 여러분 댁 울타리에 앉았다면?', `MaleText_loc4`='当雷象坐在你家围栏上的时候，你该怎么办？', `MaleText_loc5`='伊萊克坐在你的柵欄時大概會是幾點鐘?', `MaleText_loc7`='¿Qué hora es cuando un elekk se sienta en tu verja?' WHERE `ID`=16368;
