UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아내와 저는 23년 동안 행복했습니다...', `MaleText_loc4`='我和我的妻子一起快乐地生活了二十三年……', `MaleText_loc5`='我和我太太幸福了23年...', `MaleText_loc7`='Mi esposa y yo hemos sido felices durante 23 años...' WHERE `ID`=16370;
