UPDATE `locales_broadcast_text` SET `MaleText_loc1`='망가진 부메랑을 뭐라고 부르게요?', `MaleText_loc4`='你把坏的回旋标叫做什么？', `MaleText_loc5`='你怎麼叫一個壞掉的迴旋鏢?', `MaleText_loc7`='¿Qué es un bumerán roto?' WHERE `ID`=16372;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그냥 막대기죠!', `MaleText_loc4`='一根棍子！', `MaleText_loc5`='一根棍子!', `MaleText_loc7`='¡Un palo!' WHERE `ID`=16373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 블러드 엘프 여성을 좋아합니다. 특히 그들이 이런 말을 할 때는 정말 최고죠...', `MaleText_loc4`='我爱血精灵女人。特别是当她们说这些话题的时候……', `MaleText_loc5`='我愛血精靈女人。尤其是當他們說這種東西的時候...', `MaleText_loc7`='Me encantan las elfas de la sangre. Especialmente cuando dicen esas cosas...' WHERE `ID`=16374;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노움이 소원을 들어준다는 얘기를 들었습니다...', `MaleText_loc4`='我听说侏儒们可以实现愿望……', `MaleText_loc5`='我聽說地精能授予願望...', `MaleText_loc7`='He oído que los gnomos pueden conceder deseos...' WHERE `ID`=16375;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 소원은 그들이 없어져 버렸으면 좋겠다는 거예요!', `MaleText_loc4`='我的愿望就是让他们走远点！', `MaleText_loc5`='我真希望他們可以走開!', `MaleText_loc7`='¡Pues deseo que desaparezcan!' WHERE `ID`=16376;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠시 후 페리 가트너가 벌이는 희극을 맘껏 즐겨주십시오!', `MaleText_loc4`='很快就可以看到派瑞·加奈尔的喜剧表演了！', `MaleText_loc5`='來看看派瑞·卡特勒的諧劇風格，還有幾分鐘就開始!', `MaleText_loc7`='¡Disfruta de las actuaciones de Perry Gatner en unos instantes!', `FemaleText_loc1`='잠시 후 페리 가트너가 벌이는 희극을 맘껏 즐겨주십시오!', `FemaleText_loc4`='很快就可以看到派瑞·加奈尔的喜剧表演了！', `FemaleText_loc5`='來看看派瑞·卡特勒的諧劇風格，還有幾分鐘就開始!', `FemaleText_loc7`='¡Disfruta de las actuaciones de Perry Gatner en unos instantes!' WHERE `ID`=16377;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 어떤 타우렌이라도 이 용도에만은 안성맞춤이더군요...', `MaleText_loc4`='我遇到过的牛头人都非常美……', `MaleText_loc5`='我從沒遇過不討人喜歡的牛頭人...', `MaleText_loc7`='Nunca conocí a un tauren que no me gustara...' WHERE `ID`=16378;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='추수절 선물용 소갈비 모둠 말이죠!', `MaleText_loc4`='味！', `MaleText_loc5`='大吃一頓!!', `MaleText_loc7`='¡¡Para cenar!!' WHERE `ID`=16379;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배꼽이 빠져라 웃고 싶은 분은 세상의 끝 선술집으로 오십시오!', `MaleText_loc4`='要是你想要大笑一场，就去天涯旅店吧！', `MaleText_loc5`='如果你們準備好大笑一場，就前往世界的盡頭小酒館!', `MaleText_loc7`='Si quieres divertirte, vete a la taberna del Fin del Mundo.', `FemaleText_loc1`='배꼽이 빠져라 웃고 싶은 분은 세상의 끝 선술집으로 오십시오!', `FemaleText_loc4`='要是你想要大笑一场，就去天涯旅店吧！', `FemaleText_loc5`='如果你們準備好大笑一場，就前往世界的盡頭小酒館!', `FemaleText_loc7`='Si estás $glisto:lista; para divertirte, vete a la taberna del Fin del Mundo.' WHERE `ID`=16380;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공연이 끝났으니 절 붉은십자군 수도원으로 데려다 주실 분 없습니까?', `MaleText_loc4`='现在表演结束了，有人可以带我去刷血色修道院吗？', `MaleText_loc5`='既然演出結束了，有人能帶我去一趟血色修道院嗎?', `MaleText_loc7`='Ahora que el espectáculo ha terminado, ¿puede alguien ayudarme a recorrer el Monasterio Escarlata?' WHERE `ID`=16381;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여러분! 제 농담이 지연되는 시간에 보상은 절대 없습니다.', `MaleText_loc4`='大家好！离下个笑话还有多久？', `MaleText_loc5`='大家!這笑話要笑多久?', `MaleText_loc7`='¡Eh, todos! ¿Cuánto falta para que empiecen los chistes?' WHERE `ID`=16382;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 밤, 이 자리를 찾아주신 모든 여러분께 감사드립니다. 샤트라스 최고의 희극 배우 페리 가트너를 박수로 맞아주시기 바랍니다!', `MaleText_loc4`='感谢大家光临。现在请鼓掌欢迎沙塔斯城最棒的——派瑞·加奈尔！', `MaleText_loc5`='感謝你們今晚的出席。現在讓我們熱烈鼓掌歡迎撒塔斯最好的，派瑞·卡特勒!', `MaleText_loc7`='Gracias a todos por venir. Y ahora, un gran aplauso de bienvenida para el mejor de Shattrath, ¡Perry Gatner!' WHERE `ID`=16383;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='페리 가트너! 정말 대단한 배우죠! 이곳은 밤새도록 문을 여니까 편히 앉아서 즐기시기 바랍니다!', `MaleText_loc4`='派瑞·加奈尔！多棒的表演！酒馆是通宵营业的，所以请待在这尽情享受吧！', `MaleText_loc5`='派瑞·卡特勒!演的好!酒店整夜開著，因此，請留在那裡好好的享受!', `MaleText_loc7`='¡Perry Gatner! ¡Qué espectáculo! ¡La cantina estará abierta toda la noche, así que pasad y disfrutad!' WHERE `ID`=16384;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 여러분께는 그리 우호적인 평판을 얻지 못했군요.', `MaleText_loc4`='显然我和你的人民是敌对的。', `MaleText_loc5`='明顯地我在你們族人中的聲望是有敵意的。', `MaleText_loc7`='Parece que mi reputación con tu gente es mala.' WHERE `ID`=16385;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강화 마법 좀 걸어주실래요? 죽을 맛이로군요.', `MaleText_loc4`='能给我个增益魔法吗？我快死在这里了。', `MaleText_loc5`='可以給我個增益祝福嗎? 我快要不行了。', `MaleText_loc7`='¿Alguien me da un conjuro? Me estoy muriendo aquí arriba.' WHERE `ID`=16386;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜들 이러세요! 이 농담은 영웅급이라고요!', `MaleText_loc4`='哈哈哈！这些笑话真是太棒了！', `MaleText_loc5`='拜託!這些笑話都是老梗了!', `MaleText_loc7`='¡Venga! ¡Esos chistes son épicos!' WHERE `ID`=16387;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이럴 줄 알았으면 웃음 보너스 효과가 붙은 장화라도 신고 오는 건데...', `MaleText_loc4`='要是我知道会这样，我就该穿上我的[大笑长靴]。', `MaleText_loc5`='如果我知道會變成這樣，我寧願把我的搞笑大鞋穿來。', `MaleText_loc7`='Si hubiera sabido que esto iba a ser así, me habría puesto mis súper botas de la risa.' WHERE `ID`=16388;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠! 여기 계신 분들은 좀처럼 웃지를 않으시는군요.', `MaleText_loc4`='哇！这里的笑声好像从来没停过，是吗？', `MaleText_loc5`='哇!這裡不常聽到笑聲，對吧?', `MaleText_loc7`='¡Vaya! No os echáis muchas risas por aquí, ¿verdad?' WHERE `ID`=16389;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='솔직하게 말하겠다. 우리는 그곳을 공격할 것이다! 그럼 제군들 중에 그 임무를 맡을 용감한 오크는 과연 누구인가?', `MaleText_loc4`='我不想对你们说谎，士兵们。我们被打得屁滚尿流！有没有像兽人那样带种的，站出来去做点什么？', `MaleText_loc5`='我不想騙你，士兵。我們正遭到痛宰!現在你們之中的哪一個能夠拿出獸人般的勇氣來對此採取行動?', `MaleText_loc7`='Nos los voy a mentir, soldados. ¡Nos están pateando el culo! ¿Acaso ninguno de ustedes es lo suficientemente orco como para hacer algo al respecto?' WHERE `ID`=16390;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장님께서 아라지우스의 목에 상금을 걸었다! 지금부터 아무짝에도 쓸모없는 그 쓰레기 같은 악마는 척살 대상 1호이다.', `MaleText_loc4`='酋长正在悬赏捉拿阿拉修斯！从现在起，那些毫无用处的废物恶魔变成了首要的敌人。', `MaleText_loc5`='大酋長已經懸賞捉拿阿拉薩爾斯!現在，那個毫無用處的惡魔是頭號敵人。', `MaleText_loc7`='El Jefe de Guerra ha puesto precio a la cabeza de Arazzius. Ahora mismo, ese demonio de pacotilla se empeña en ningunear a su principal enemigo.' WHERE `ID`=16391;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇다, 우리는 몇 가지 어려움에 처해 있다. 어떤 어려움인지는 확실히 인지하고 있다. 그러나 문제는 그 어려움을 어떻게 해결하느냐 하는 것이다.', `MaleText_loc4`='是的，我们有麻烦了。我想那是显而易见的。但问题是，我们要怎么办？', `MaleText_loc5`='是，我們有問題。我想那是一清二楚的。問題是，我們要對它做些什麼?', `MaleText_loc7`='Sí, tenemos problemas. Creo que eso está más que claro. La pregunta es, ¿qué vamos a hacer?' WHERE `ID`=16392;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도대체 얼마나 많은 보병이 시체가 되어 고향으로 돌아가야만 불타는 군단의 살인 부대로 뛰어드는 것이 자살 행위라는 것을 알겠는가? 그리고 마치 내 말을 이해한다는 듯이 그 큰 머리 좀 끄덕이지 말라!', `MaleText_loc4`='都长长脑子吧，在你们认识到一头冲进燃烧军团的小队是自杀行为之前，我还要送多少具尸体回你们的家？还有，不要在我面前用力晃你们的大脑袋，好像你们明白我在说什么似的。', `MaleText_loc5`='在你們長大腦並意識到頭一個跑進軍團屠殺團是自殺行為之前，我還需要把多少個像你們這樣的蠻兵以屍袋送回給你們的媽媽和爸爸?不要點點你的大頭顱好像知道我在說些什麼!', `MaleText_loc7`='¿Cuántos brutos tengo que devolver a sus padres metidos en sacos antes de que os crezca cerebro y os deis cuenta de que atacar de frente a un pelotón asesino de la Legión es un suicidio? ¡Y no agitéis esas cabezotas como si supierais de lo que hablo!' WHERE `ID`=16393;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 생활에 익숙해져야 한다, 보병들이여. 우리는 비참한 삶을 이어가기 위해 이곳에 왔다. 새로운 고향 지옥불 반도에 온 것을 환영하는 바이다.', `MaleText_loc4`='习惯就好，姑娘们。像我一样关心这些悲惨的幸存者吧。欢迎来到地狱火半岛，你的新家。', `MaleText_loc5`='習慣它吧，女孩們。據我所知，我們將在這個地方渡過我們的下半生。歡迎到地獄火半島，你的新家。', `MaleText_loc7`='Acostumbrense, chicas. Nos quedaremos aquí el resto de nuestras miserables vidas. Bienvenidas a la Península del Fuego Infernal, su nuevo hogar.' WHERE `ID`=16394;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='온다! 놈들이 이곳을 통과하게 해서는 안 된다! 화염 마법의 힘을 집중하라! 지금, 바로 지금이다!', `MaleText_loc4`='来了！一个都别放过！集中火力！放！', `MaleText_loc5`='敵人來了!不要讓他們穿過!集中火力!現在，現在，現在!', `MaleText_loc7`='¡¡VIENEN!! ¡No les permitáis pasar! ¡Fuego! ¡VAMOS, VAMOS, VAMOS!' WHERE `ID`=16395;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파멸의 군주의 권위에 고개를 숙여라! 너희가 이길 승산은 전혀 없다!', `MaleText_loc4`='屈服于末日领主的力量吧！你们没有任何机会！', `MaleText_loc5`='向毀滅領主的力量鞠躬!你沒有僥倖的機會!', `MaleText_loc7`='¡Inclínate ante el poder del Señor Apocalíptico! ¡Estás $gacabado:acabada;!' WHERE `ID`=16396;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알줄은 우리 주인님의 이름으로 이 땅을 지배할 것이다!', `MaleText_loc4`='以我们主人之名，阿苏勒将占有这块大陆！', `MaleText_loc5`='阿爾蘇勒將以我們主人的名義擁有這塊土地!', `MaleText_loc7`='¡Esta tierra será de Arzule en nombre de nuestro maestro!' WHERE `ID`=16397;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전쟁인도자시여, 제 기도를 들어주소서! 우리의 적들에게 벌을 내려 주십시오!', `MaleText_loc4`='听我号令，战争使者！击倒我们的敌人！', `MaleText_loc5`='先驅者聽到我的呼叫!擊垮我們的敵人!', `MaleText_loc7`='¡¡Belisarios, oíd mi llamada!! ¡Atacad a nuestros enemigos!' WHERE `ID`=16398;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='날 여기서 꺼내줄 방법을 찾아야 해, 어서!', `FemaleText_loc4`='找条路带我离开这里，$c。', `FemaleText_loc5`='想辦法把我帶離這裡，$c。', `FemaleText_loc7`='¡Encuentra la forma de sacarme de aquí, $c!' WHERE `ID`=16399;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 날 여기서 꺼낼 방법을 찾아보시오!', `MaleText_loc4`='找条路带我离开这里，$c。', `MaleText_loc5`='想辦法把我帶離這裡，$c!', `MaleText_loc7`='¡Encuentra la forma de sacarme de aquí, $c!' WHERE `ID`=16400;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련이 완료됐습니다. 곧 다음 신병을 모집할 예정입니다.', `MaleText_loc4`='训练完成了，长官。我们的下一批新兵很快就会准备好的。', `MaleText_loc5`='訓練完成，長官。我們的下一批新兵不久將到。', `MaleText_loc7`='El entrenamiento ha finalizado, señor. Pronto recibiremos nuestro lote de nuevos reclutas.' WHERE `ID`=16401;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 포효합니다!', `MaleText_loc4`='%s咆哮着。', `MaleText_loc5`='%s吼叫!', `MaleText_loc7`='¡%s ruge!' WHERE `ID`=16402;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다. 하지만, 칭찬을 받기 전에 먼저 손님으로 오신 사절 모르딘의 도움을 받았다는 사실부터 밝혀야겠군요.', `MaleText_loc4`='谢谢。摩尔丁特使给予了我莫大的帮助，您的褒扬我真是受之有愧。', `MaleText_loc5`='感謝你，長官，但我不能在沒有感謝我們的客人 - 大使莫爾丁之下接受你的讚揚。', `MaleText_loc7`='Gracias, señor, pero no puedo aceptar sus alabanzas sin antes reconocer la ayuda de nuestro invitado, el Emisario Mordin.' WHERE `ID`=16403;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그가 제안한 군대 훈련 방법은 정말 탁월했습니다.', `MaleText_loc4`='他所提出的方法一直对组建军队很有效果。', `MaleText_loc5`='他建議的技巧在整備軍隊過程中非常有效。', `MaleText_loc7`='Las técnicas que ha sugerido han resultado ser eficaces para entrenar a los soldados.' WHERE `ID`=16404;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말씀 중에 죄송합니다만, 토르보스 경! 다음 부대를 준비해야 합니다.', `MaleText_loc4`='对不起，托沃斯男爵。我必须集合下一批士兵，以便您的检阅。', `MaleText_loc5`='如果你允許的話，托沃斯領主。我必須為你的檢閱準備下一支部隊。', `MaleText_loc7`='Con su venia, Lord Torvos. Debo preparar los siguientes soldados para su revista.' WHERE `ID`=16405;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선구자여, 잘하고 있군.', `MaleText_loc4`='干得好，先驱者。', `MaleText_loc5`='你做的很好，先驅者。', `MaleText_loc7`='Estás haciendo un buen trabajo, presagista.' WHERE `ID`=16406;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대가 가르친 신병들이 전투에서 가장 뛰어나다고 전방에서 소식이 왔네.', `MaleText_loc4`='从前线传来的消息，你的新兵在战场上的表现是最出色的。', `MaleText_loc5`='來自前線的消息是你的新兵在戰鬥中的表現勝過全部其它人。', `MaleText_loc7`='Se dice en las primeras líneas que tus reclutas son mucho mejores que los demás.' WHERE `ID`=16407;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런 말씀 마십시오, 친구여...', `MaleText_loc4`='正好相反，我的朋友。', `MaleText_loc5`='正好相反，我的朋友。', `MaleText_loc7`='Al contrario, amigo.' WHERE `ID`=16408;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대가 제공한 적에 관한 정보와 전략을 통해 우리는 전투에서 엄청난 효과를 봤습니다.', `MaleText_loc4`='正是你在研究敌人和他们战术时的睿智，让我们在战场上取得了巨大的优势。', `MaleText_loc5`='具有你提供之敵人的情報和他們的戰術，我們已經實地獲得優勢。', `MaleText_loc7`='Con la información que nos has proporcionado sobre el enemigo y sus tácticas, tendremos una gran ventaja en el campo.' WHERE `ID`=16409;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여전히 치열한 전투가 벌어지고 희생이 크지만 그대는 정말 큰 도움이 되었습니다.', `MaleText_loc4`='战斗是惨烈和代价沉重的，但是你的援助却无法用价值来衡量。', `MaleText_loc5`='戰鬥依然殘酷而昂貴，但是你的幫助已經證明是無價的。', `MaleText_loc7`='La batalla sigue siendo terrible, pero tu ayuda ha sido vital.' WHERE `ID`=16410;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 이만 가보게.', `MaleText_loc4`='解散。', `MaleText_loc5`='解散。', `MaleText_loc7`='Despedido.' WHERE `ID`=16411;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 돕게 되어 영광이죠. 이렇게 험한 시기에 더 큰 도움을 드리지 못해 오히려 죄송스럽게 생각합니다.', `MaleText_loc4`='您是如此信任我，尊敬的长官。很遗憾，在这危险的时刻，我们却不能提供更多帮助。', `MaleText_loc5`='你太抬舉我了，先生。我很遺憾我們在這樣危急的時代無法給予更多的幫助。', `MaleText_loc7`='Me da demasiado crédito, buen señor. Siento no poder ayudarle más en estos tiempos tan difíciles.' WHERE `ID`=16412;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고마운 말씀입니다. 아제로스에 있는 우리 사령관들에게 당신이 고마워한다는 소식을 전하겠습니다.', `MaleText_loc4`='这是个好消息。我会把你的感激转达给我们在艾泽拉斯的司令官。', `MaleText_loc5`='這的確是個好消息。回到艾澤拉斯之後，我將傳達你的感激之情給我們的指揮官。', `MaleText_loc7`='Me alegra oír esa noticia. Transmitiré tu agradecimiento a los comandantes en Azeroth.' WHERE `ID`=16413;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='알레리아 성채에 오신 것을 환영합니다. 이 여관에서 지친 몸을 쉬시겠습니까, 아니면 식사를 하시겠습니까?', `FemaleText_loc4`='客官，您是打尖儿，还是住店？', `FemaleText_loc5`='歡迎。你要在這裡休息，還是來一頓餐點呢?', `FemaleText_loc7`='$gBienvenido:Bienvenida;. ¿Descansarás aquí? ¿Te apetece comer algo?' WHERE `ID`=16414;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대들이 해 낸 일을 보라! 불타는 군단의 가장 강력한 기계조차도 호드의 상대가 되지 못하고 있다!', `MaleText_loc4`='士兵们，干得好！就算是燃烧军团最可怕的机甲都不是部落的对手！', `MaleText_loc5`='看看你所完成的，士兵!即使軍團最可怕的機器也敵不過部落!', `MaleText_loc7`='¡Mirad lo que habéis conseguido, soldados! ¡Incluso las más temibles máquinas de la Legión no son rival para la Horda!' WHERE `ID`=16416;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들의 지옥절단기를 우리가 어떻게 했는지 부여 주도록 하자!', `MaleText_loc4`='让他们看看，我们解决了他们的魔能机甲！', `MaleText_loc5`='讓他們看看我們對他們的惡魔劫奪者做了什麼!', `MaleText_loc7`='¡Que vean lo que hemos hecho con su atracador vil!' WHERE `ID`=16417;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 후손들에게 더 나은 미래를 선사하기 위해 전쟁을 하고 있다! 그러기 위해 우리는 불타는 군단을 물리칠 것이다!', `MaleText_loc4`='我们作战，是为了后代可以看到更美好的明天！为了他们，让我们消灭燃烧军团！', `MaleText_loc5`='我們戰爭是為了讓我們的小孩還能活著看見更好的明天!並且為他們，我們必須摧毀燃燒軍團!', `MaleText_loc7`='Luchamos para que nuestros pequeños puedan tener un futuro mejor. ¡Y por ellos, destruiremos a la Legión Ardiente!' WHERE `ID`=16418;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 보내 봐라, 악마들아! 여기 이놈처럼 모조리 없애 주마!', `MaleText_loc4`='再来啊，恶魔们！我们会像这样消灭它们！', `MaleText_loc5`='再來啊，惡魔!我們會摧毀他們就像我們摧毀這個一樣!', `MaleText_loc7`='¡Enviad más, demonios! ¡Las destruiremos como esta!' WHERE `ID`=16419;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장님 만세! 호드를 위하여!', `MaleText_loc4`='为了酋长！为了部落！', `MaleText_loc5`='為了大酋長!為了部落!', `MaleText_loc7`='¡Por el Jefe de Guerra! ¡Por la Horda!' WHERE `ID`=16420;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좀 더 빨리 움직여라, 이 하찮은 것들! 주인님께서 찾고 계신 아타말 수정을 찾지 못하면 그분의 분노를 사게 될 것이다.', `MaleText_loc4`='再快点，蠢货！如果我们找不到主人想要的阿塔玛水晶，他不会高兴的。', `MaleText_loc5`='快一點，殘渣!如果我們不找到主人追求的阿塔莫水晶，他將很不高興。', `MaleText_loc7`='¡Más rápido, escoria! El maestro se enfadará si no encontramos el cristal de Ata''mal que buscamos.' WHERE `ID`=16421;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겨울 할아버지는 겨울맞이 축제 기간 동안 아이언포지의 나무 아래 있는 모든 사람들에게 선물을 주신답니다. 올해는 어떤 선물일까 궁금해서 못 참겠어요!', `MaleText_loc4`='冬天爷爷会把给每个人的礼物放在铁炉堡的树下。我已经等不及要去拿我的了。', `MaleText_loc5`='冬天爺爺將在鐵爐堡的樹下為每個人留下禮物。我等不及要得到我的!', `MaleText_loc7`='El Gran Padre Invierno dejará regalos para todos bajo el árbol, en Forjaz. ¡Me muero por ver el mío!', `FemaleText_loc1`='겨울 할아버지는 겨울맞이 축제 기간 동안 아이언포지의 나무 아래 있는 모든 사람들에게 선물을 주신답니다. 올해는 어떤 선물일까 궁금해서 못 참겠어요!', `FemaleText_loc4`='冬天爷爷会把给每个人的礼物放在铁炉堡的树下。我已经等不及要去拿我的了。', `FemaleText_loc5`='冬天爺爺將在鐵爐堡的樹下為每個人留下禮物。我等不及要得到我的!', `FemaleText_loc7`='El Gran Padre Invierno dejará regalos para todos bajo el árbol, en Forjaz. ¡Me muero por ver el mío!' WHERE `ID`=16422;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겨울맞이 축제가 끝나기 전에 겨울 할아버지를 만날 기회가 있으면 좋겠군요.', `MaleText_loc4`='我希望能有机会在冬幕节结束之前和冬天爷爷聊聊天。', `MaleText_loc5`='我希望在冬幕節結束之前，我有機會拜訪冬天爺爺。', `MaleText_loc7`='Espero tener la oportunidad de ver al Gran Padre Invierno antes de que termine el Festival de Invierno.', `FemaleText_loc1`='겨울맞이 축제가 끝나기 전에 겨울 할아버지를 만날 기회가 있으면 좋겠어요.', `FemaleText_loc4`='我希望能有机会在冬幕节结束之前和冬天爷爷聊聊天。', `FemaleText_loc5`='我希望在冬幕節結束之前，我有機會拜訪冬天爺爺。', `FemaleText_loc7`='Espero tener la oportunidad de ver al Gran Padre Invierno antes de que termine el Festival de Invierno.' WHERE `ID`=16423;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 빨리 파라, 쓰레기들아! 나로 하여금 고통의 진짜 의미를 가르치게 하지 마라!', `MaleText_loc4`='挖快点，可怜虫！不要逼我对你下狠手！', `MaleText_loc5`='壞蛋們，挖快一點!不要逼我讓你們看到真正的痛苦!', `MaleText_loc7`='¡Cava más rápido, basura! ¡No me obligues a mostrarte el verdadero significado del dolor!' WHERE `ID`=16424;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멈추지 마라! 요령을 피우다 걸리면 끔찍한 고통을 보여 주마!', `MaleText_loc4`='不要停下来！如果你敢有哪怕一秒钟放下锄头的念头，我保证会让你明白什么叫死去活来！', `MaleText_loc5`='不要停止!如果你放下那工具，我將保證你會死一千次!', `MaleText_loc7`='¡No pares! ¡Te prometo un millar de muertes si vuelves a pensar en dejar ese pico!' WHERE `ID`=16425;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 뭐가 터진건가?', `MaleText_loc4`='那是什么东西？！', `MaleText_loc5`='那是什麼?', `MaleText_loc7`='¿Qué ha sido eso?' WHERE `ID`=16426;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무너진 하늘 마루의 하늘에서 떨어진 거대한 수정을 둘러싼 신비를 밝혀내야 합니다.', `FemaleText_loc4`='那些从天上滑落到坠星山的巨型水晶，隐藏着我们必须解读的迷团。', `FemaleText_loc5`='我們必須找出從墜天山脈天空上掉下來的巨大水晶背後所隱藏的秘密。', `FemaleText_loc7`='Hay que descubrir lo que se esconde tras el misterio del cristal gigante que cayó de los cielos en Cresta Cielo Estrellado.' WHERE `ID`=16427;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='때로는 직면한 문제에 굴하지 않고 정면으로 부딪치는 것이 가장 좋을 때가 있지요.', `MaleText_loc4`='有时候，直接了当地提问是最好的。', `MaleText_loc5`='有時候直接逼近問題是最好的方法。', `MaleText_loc7`='Algunas veces, un enfoque más directo es la solución.' WHERE `ID`=16428;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님, 실패했습니다...', `MaleText_loc4`='主人，我失败了……', `MaleText_loc5`='主人，我失敗了...', `MaleText_loc7`='Maestro, he fracasado...' WHERE `ID`=16429;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불타는 군단에게 사로잡히면 그들에게 "자르 일 로마스 다 티데스비"라고 하십시오. 자기들의 신을 모독했다는 이유로 그 자리에서 당신을 죽일 겁니다. 그러면 적어도 끔찍한 고문을 받는 일은 면할 수 있겠지요...', `MaleText_loc4`='如果你被燃烧军团俘虏了，对他们说“Xar il romath da tidesbi”，他们就会马上杀了你，因为你侮辱了他们的神。否则你就会受到无尽的折磨或者更糟的……', `MaleText_loc5`='如果你被軍團抓到，告訴他們「(惡魔語)沙爾·伊歐·羅馬斯·達·泰斯比。」他們將因為你侮辱他們的神而立刻殺死你，讓你免於遭受慘忍的拷問或更慘的事...', `MaleText_loc7`='Si te captura la Legión, diles ''Xar il romath da tidesbi.'' Te matarán enseguida por haber insultado a su dios y te librarás de una tortura horrible o de algo peor...' WHERE `ID`=16430;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 전방사령관 토아크 님으로부터 받은 폭격 임무를 수행 중입니다. 파괴의 장갑 와이번이 필요합니다!', `MaleText_loc4`='我正在为前线指挥官托尔克执行轰炸任务。我需要一头武装飞龙！', `MaleText_loc5`='我在執行一項前線指揮官吐阿奇所賦予的轟炸任務。我需要一個雙足翼龍毀滅者!', `MaleText_loc7`='Estoy en una misión de bombardeo para el comandante de vanguardia To''arch. ¡Necesito un destructor dracoleón!', `FemaleText_loc1`='저는 전방사령관 토아크 님으로부터 받은 폭격 임무를 수행 중입니다. 파괴의 장갑 와이번이 필요합니다!', `FemaleText_loc4`='我正在为前线指挥官托尔克执行轰炸任务。我需要一头武装飞龙！', `FemaleText_loc5`='我在執行一項前線指揮官吐阿奇所賦予的轟炸任務。我需要一個雙足翼龍毀滅者!', `FemaleText_loc7`='Estoy en una misión de bombardeo para el comandante de vanguardia To''arch. ¡Necesito un destructor dracoleón!' WHERE `ID`=16431;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='건방진 놈들. 네 놈들은 잠시 시간을 늦췄을 뿐 결코 너희의 운명을 피할 수는 없다. 하나가 쓰러지면 열이 새로 일어날 것이니... 그것이 나 카자크의 뜻이니라...', `MaleText_loc4`='可笑的凡人，你们只是延迟了不可避免的命运。一个恶魔倒下去，十个恶魔会站起来。这就是卡扎克的意志……', `MaleText_loc5`='無知的幼蟲們，你只是延遲了不可避免的事。殺死1個，10個就會出現。這些是卡札克的意願...', `MaleText_loc7`='Insolentes crías... Solo retrasáis lo inevitable. Donde cae uno, saldrán diez más. Tal es la voluntad de Kazzak...' WHERE `ID`=16432;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='재미를 볼 시간이다!', `MaleText_loc4`='有好玩的啦！', `MaleText_loc5`='玩樂的時間到了!', `MaleText_loc7`='¡Hora de divertirse!' WHERE `ID`=16433;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투 준비! 거대괴수의 공격이다!', `MaleText_loc4`='准备战斗！巨人进攻了！', `MaleText_loc5`='拿武器!巨像進攻了!', `MaleText_loc7`='¡Coged las armas! ¡Los colosos atacan!', `FemaleText_loc1`='전투 준비! 거대괴수의 공격이다!', `FemaleText_loc4`='准备战斗！巨人进攻了！', `FemaleText_loc5`='拿武器!巨像進攻了!', `FemaleText_loc7`='¡Coged las armas! ¡Los colosos atacan!' WHERE `ID`=16434;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='집행자들이여, 동쪽 입구를 방어하십시오!', `MaleText_loc4`='卫兵，守住东面的入口！', `MaleText_loc5`='守衛，防守東邊入口!', `MaleText_loc7`='¡Celadores, defended la entrada este!' WHERE `ID`=16435;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상황 종료! 거대괴수의 공격을 막아낸 것 같습니다.', `MaleText_loc4`='都解决了。看上去巨人的进攻被击退了。', `MaleText_loc5`='了解。看起來這波巨像的攻擊被逐退了。', `MaleText_loc7`='BIen. Parece que el ataque de los colosos ha sido detenido.' WHERE `ID`=16436;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어리석은 것들! 파괴자 앞에 무릎을 꿇고 공포에 몸을 떨어라!', `MaleText_loc4`='颤抖吧，凡人们！颤抖并在你们的毁灭者面前卑躬屈膝吧！', `MaleText_loc5`='顫抖吧，凡人!顫抖並跪在你的摧毀者面前!', `MaleText_loc7`='¡Tiemblen, mortales! ¡Tiemblen y arrodíllense ante su destructor!' WHERE `ID`=16437;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 주인님의 일을 방해하다니! 그 대가를 치르게 될 것이다, 이 어리석은 녀석!', `MaleText_loc4`='你胆敢妨碍主人的计划？你会付出代价的，愚蠢的凡人！', `MaleText_loc5`='你竟敢干擾主人的努力?你會付出代價的，愚蠢的凡人!', `MaleText_loc7`='¿Te atreves a entrometerte en los asuntos del amo? ¡Pagarás por ello, mortal!' WHERE `ID`=16438;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자들을 해치워라, 더러운 넝마두건 녀석들아! 내 말을 거역한다면 끝없는 고통을 선물해 주마!', `MaleText_loc4`='消灭这些入侵者，肮脏的残冠氏族！如果你们不服从我的命令，我会让你们尝到无尽的痛苦！', `MaleText_loc5`='殺死這些入侵者，污穢的崔互德們!如果你不服從我，我將把永無止境的痛苦許諾給你!', `MaleText_loc7`='¡Matad a los intrusos, asquerosos Zarrapuchas! ¡Os juro que lo lamentaréis eternamente si no me obedecéis!' WHERE `ID`=16439;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 가라, 이 쓸모없는 것들아! 저 바보들에게 우리 주인님이 얼마나 위대한 분인지 보여 주거라!', `MaleText_loc4`='去吧，你们这些可怜虫！让那些蠢货们知道藐视主人的下场！', `MaleText_loc5`='去，你這個小壞蛋!讓這些傻瓜知道我們的主人不是可以愚弄的!', `MaleText_loc7`='¡Venga, desgraciados! ¡Enséñenles a esos estúpidos que nuestro amo no se anda con tonterías!' WHERE `ID`=16440;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도망갈 생각은 꿈에도 하지 마라, 이 뒤틀린 드레나이 쓰레기들아! 침입자들을 해치우지 않으면 지옥보다도 고통스러운 운명을 안겨주겠다!', `MaleText_loc4`='不要妄想逃跑，可怜的破碎者！不消灭这些入侵者，我就让你们生不如死！', `MaleText_loc5`='休想逃跑，破碎者的壞蛋們!如果你們不殺死這些入侵者，我將許諾你一個比死更壞的命運!', `MaleText_loc7`='¡Que ni se os ocurra huir, miserables Tábidos! ¡Os prometo un destino peor que la muerte si no acabáis con estos intrusos!' WHERE `ID`=16441;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='풀어 주셔서 고맙소, $n. 이제 여길 빠져 나갑시다!', `MaleText_loc4`='感谢你解救了我，$n。现在让我们离开这里！', `MaleText_loc5`='謝謝你釋放了我，$n。現在我們快離開這!', `MaleText_loc7`='Gracias por liberarme, $n. ¡Ahora salgamos de aquí!' WHERE `ID`=16442;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='바로 그거야! 이제 여기서 빠져나가야 해!', `FemaleText_loc4`='就要到了！让我们逃离这里！', `FemaleText_loc5`='這還差不多!我們離開這!', `FemaleText_loc7`='¡Eso es! ¡Salgamos de aquí!' WHERE `ID`=16443;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='굴뚝나무 목장조합이 오그리마와 아이언포지에 가게를 열었습니다. 올해 축제에는 그들이 어떤 것을 만들어낼지 궁금하군요.', `MaleText_loc4`='烟林牧场在奥格瑞玛和铁炉堡开了商店。不知道他们今年在构想些什么？', `MaleText_loc5`='燻木牧場已經在奧格瑪和鐵爐堡開業。不知道他們今年會想出什麼怪玩意呢?', `MaleText_loc7`='Pastos de Bosquehumeante ha abierto establecimientos en Orgrimmar y Forjaz. ¿Qué prepararán este año?', `FemaleText_loc1`='굴뚝나무 목장조합이 오그리마와 아이언포지에 가게를 열었습니다. 올해 축제에는 그들이 어떤 것을 만들어낼지 궁금하네요.', `FemaleText_loc4`='烟林牧场在奥格瑞玛和铁炉堡开了商店。不知道他们今年在构想些什么？', `FemaleText_loc5`='燻木牧場已經在奧格瑪和鐵爐堡開業。不知道他們今年會想出什麼怪玩意呢?', `FemaleText_loc7`='Pastos de Bosquehumeante ha abierto establecimientos en Orgrimmar y Forjaz. ¿Qué prepararán este año?' WHERE `ID`=16444;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='금발 머리, 녹색 피부, 뿔 달린 머리, 파란색 피부. 이 모든 것들이 우리 고블린의 뛰어난 기술을 팔아먹을 수 있는 새로운 시장이 열린 것을 뜻하는 거 아니겠습니까? 심지어 불타는 군단과의 전쟁도 우리에겐 더욱 높은 수익 창출의 기회를 뜻합니다.', `MaleText_loc4`='金发，绿皮肤，带角的脑袋，蓝皮肤——所有这些家伙都给我们伟大的地精工程学带来了新的市场！即使是与燃烧军团的第二次战争展望都会提高我们的销量！', `MaleText_loc5`='金黃色的頭髮，綠色的皮，角頭，藍色的皮 - 對我們完美的哥布林工程學來說這些代表著新的市場!即使與軍團間的另一次戰爭，對我們而言也只是代表更多的銷售!', `MaleText_loc7`='Pelo rubio, piel verde, cabeza con cuerno, piel azul... todo lo que esto significa para nosotros son nuevos mercados para nuestra excelente ingeniería goblin. Incluso la posibilidad de otra guerra contra la Legión significa más ventas para nosotros.', `FemaleText_loc1`='금발 머리, 녹색 피부, 뿔 달린 머리, 파란색 피부. 이 모든 것들이 우리 고블린의 뛰어난 기술을 팔아먹을 수 있는 새로운 시장이 열린 것을 뜻하는 거 아니겠습니까? 심지어 불타는 군단과의 전쟁도 우리에겐 더욱 높은 수익 창출의 기회를 뜻합니다.', `FemaleText_loc4`='金发，绿皮肤，带角的脑袋，蓝皮肤——所有这些家伙都给我们伟大的地精工程学带来了新的市场！即使是与燃烧军团的第二次战争展望都会提高我们的销量！', `FemaleText_loc5`='金黃色的頭髮，綠色的皮，角頭，藍色的皮 - 對我們完美的哥布林工程學來說這些代表著新的市場!即使與軍團間的另一次戰爭，對我們而言也只是代表更多的銷售!', `FemaleText_loc7`='Pelo rubio, piel verde, cabeza con cuerno, piel azul... todo lo que esto significa para nosotros son nuevos mercados para nuestra excelente ingeniería goblin. Incluso la posibilidad de otra guerra contra la Legión significa más ventas para nosotros.' WHERE `ID`=16445;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='병사들이여! 이만 해산!', `MaleText_loc4`='士兵们！散开！', `MaleText_loc5`='士兵們!散開!', `MaleText_loc7`='¡Soldados! ¡Retirada!' WHERE `ID`=16446;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드루이드들이 달숲에서 멋진 달의 축제를 열고 있지요. 먼 곳에 계신 분들을 위해 드루이드들이 대도시에서 순간이동하는 데 도움을 받을 수 있는 거 아시나요?', `MaleText_loc4`='德鲁伊们在月光林地举行春节庆典。要是那里对你来说太远了，他们正在各大城市提供着传送服务。', `MaleText_loc5`='德魯伊們正在月光林地舉行一個新年節慶的大慶典。如果那用走的太遠，他們可接駁來自大城市的人。', `MaleText_loc7`='Los druidas están disfrutando de una gran celebración del Festival Lunar en el Claro de la Luna. Si te parece demasiado tiempo para ir andando, están teletransportando a gente desde las grandes ciudades.', `FemaleText_loc1`='드루이드들이 달숲에서 멋진 달의 축제를 열고 있지요. 먼 곳에 계신 분들을 위해 드루이드들이 대도시에서 순간이동하는 데 도움을 받을 수 있는 거 아시나요?', `FemaleText_loc4`='德鲁伊们在月光林地举行春节庆典。要是那里对你来说太远了，他们正在各大城市提供着传送服务。', `FemaleText_loc5`='德魯伊們正在月光林地舉行一個新年節慶的大慶典。如果那用走的太遠，他們可接駁來自大城市的人。', `FemaleText_loc7`='Los druidas están disfrutando de una gran celebración del Festival Lunar en el Claro de la Luna. Si te parece demasiado tiempo para ir andando, están teletransportando a gente desde las grandes ciudades.' WHERE `ID`=16447;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두, 잘 듣도록!', `MaleText_loc4`='听好了！', `MaleText_loc5`='聽好了大夥!', `MaleText_loc7`='¡Escuchad, hombres!' WHERE `ID`=16448;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 훈련은 끝났다. 모두 임무를 맡게 될 것이다. 성스러운 빛이 그대들을 인도하길...', `MaleText_loc4`='你的训练已经结束。我给你们都分派了任务，愿圣光指引你。', `MaleText_loc5`='你的訓練完成了。你們每一個人都有各自的任務。願聖光引導你。', `MaleText_loc7`='La instrucción ha terminado. Todos sabéis lo que tenéis asignado. Que la Luz os guíe.' WHERE `ID`=16449;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 가젯잔의 수익을 보호하고자 여기 운고로 분화구로 왔어요. 당신이 상관할 바는 아니죠.', `MaleText_loc4`='我们在这里保护着加基森在安戈洛的利益，而且那和你毫无关系。', `MaleText_loc5`='我們是來保護加基森在安戈洛的利益，這不關你的事。', `MaleText_loc7`='Estamos aquí para proteger los intereses de Gadgetzan en Un''Goro y eso no te incumbe.' WHERE `ID`=16450;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지옥불 반도는 철저하게 파괴되었습니다. 그곳의 주민들에게는 무자비하고 용서받지 못할 일이지요. 여정을 떠나기 전에 장비의 정비를 마치고 물자를 챙기는 걸 잊지 마십시오.', `FemaleText_loc4`='地狱火半岛是一个满目疮痍的区域——对那里的居民们来说，那是多么的残酷和艰难。确保在冒险前修理并囤积好补给品吧。', `FemaleText_loc5`='地獄火半島是一個粉碎的王國 - 對它的居民殘酷而無情。在冒險以前一定要修理好裝備並且貯存補給品。', `FemaleText_loc7`='La Península del Fuego Infernal es un reino devastado y despiadado con sus habitantes. Repara y haz acopio de víveres y material necesario antes de salir de expedición.' WHERE `ID`=16451;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 물건을 팔고 있습니까?', `MaleText_loc4`='你都卖些什么？', `MaleText_loc5`='你有什麼東西要賣嗎?', `MaleText_loc7`='¿Qué tienes a la venta?', `FemaleText_loc1`='어떤 물건을 팔고 있나요?', `FemaleText_loc4`='你都卖些什么？', `FemaleText_loc5`='你有什麼東西要賣嗎?', `FemaleText_loc7`='¿Qué tienes a la venta?' WHERE `ID`=16452;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그곳에 관심을 쏟기도 전에 얼마나 많은 병사들이 죽어 나가야 하는 겁니까?', `MaleText_loc4`='在我们开始严肃对待之前，还有多少士兵要死在这里？', `MaleText_loc5`='還需要死多少士兵，我們才會開始注意外面?', `MaleText_loc7`='¿Cuántos soldados más deben morir antes de que empecemos a prestar atención a lo que está pasando?' WHERE `ID`=16453;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악마들이 정정당당하게 싸울 것이라 생각하시오? 그 짐승들은 오크보다도 야만적이고 언데드보다도 교활하오. 일반적인 전쟁을 기준으로 불타는 군단과 맞서려는 생각은 버리시오.', `MaleText_loc4`='你们觉得这些恶魔会跟我们公平地交战吗？它们比兽人更野蛮，比亡灵更狡猾。千万不要试图以普通的战争标准来评判燃烧军团。', `MaleText_loc5`='你認為惡魔們將公正比賽嗎?這些野獸比獸人們更野蠻，且比不死身更狡猾。千萬不要試圖以正常的標準戰爭方式來與軍團抗衡。', `MaleText_loc7`='¿Crees que los demonios van a jugar limpio? Esas bestias son más salvajes que los orcos y más astutos que los no-muertos. Ni intentes enfrentarte a la Legión pensando en los estándares normales de la guerra.' WHERE `ID`=16454;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신에게 오늘 시체가 된 병사 10명을 고향으로 돌려보냈다는 말을 하는 게 아니었는데...', `MaleText_loc4`='我很遗憾地告诉你们，今天我们又送了十个士兵回家——装在裹尸袋里。', `MaleText_loc5`='我很遺憾地通知你們我們今天送了另外10名士兵回家 - 在屍袋裡。', `MaleText_loc7`='Siento informarte de que hoy enviamos a otros diez soldados a casa... en bolsas de cadáveres.' WHERE `ID`=16455;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번 전쟁에서 어떻게든 이기겠지 하는 생각은 버리십시오. 이번 전쟁이 단지 전쟁일 뿐이라는 착각도 버리는 게 좋을 겁니다. 이 파괴된 땅의 모든 것을 위해 싸우고, 할퀴고, 걷어차지 않으면 모든 것을 잃게 될 테니까요.', `MaleText_loc4`='这场战争——不要错误地认为它是除了战争以外的什么东西——是不会自动获胜的。如果我们不尽全力来为这块破碎世界的每一寸土地战斗，我们就会失去一切。', `MaleText_loc5`='是的，別天真地以為這不是一場戰爭，而戰爭是不會自然而然就獲得勝利的。如果我們不使盡所有手段，爭取這片破碎之地上的每一塊小領土，我們就會全面戰敗了', `MaleText_loc7`='Esta guerra, y no vayas a creer que no es una guerra, no va a ganarse sola. Si no luchamos, mordemos, arañamos y pateamos por cada centímetro de tierra de este mundo destrozado, lo perderemos todo.', `FemaleText_loc1`='이번 전쟁에서 어떻게든 이기겠지 하는 생각은 버리십시오. 이번 전쟁이 단지 전쟁일 뿐이라는 착각도 버리는 게 좋을 겁니다. 이 파괴된 땅의 모든 것을 위해 싸우고, 할퀴고, 걷어차지 않으면 모든 것을 잃게 될 테니까요.', `FemaleText_loc4`='这场战争——不要错误地认为它是除了战争以外的什么东西——是不会自动获胜的。如果我们不尽全力来为这块破碎世界的每一寸土地战斗，我们就会失去一切。', `FemaleText_loc5`='是的，別天真地以為這不是一場戰爭，而戰爭是不會自然而然就獲得勝利的。如果我們不使盡所有手段，爭取這片破碎之地上的每一塊小領土，我們就會全面戰敗了', `FemaleText_loc7`='Esta guerra, y no vayas a creer que no es una guerra, no va a ganarse sola. Si no luchamos, mordemos, arañamos y pateamos por cada centímetro de tierra de este mundo destrozado, lo perderemos todo.' WHERE `ID`=16456;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='목소리를 낮추고 눈을 크게 뜨십시오, $n. 우리는 적에게 포위되었습니다.', `MaleText_loc4`='小点声，睁开你的眼睛看看，$n。我们被这里的敌人包围了。', `MaleText_loc5`='降低你的音量，並張大你的雙眼，$n。我們的外面到處都是敵人。', `MaleText_loc7`='Habla bajo y mantén los ojos abiertos, $n. Estamos rodeados de enemigos.' WHERE `ID`=16457;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대가 첫 번째로 해야 할 일은 던홀드 요새의 포로수용소 안에 있는 통에 화염 폭탄을 설치하는 것입니다. 폭탄 5개가 폭발하고 적의 주의가 흐트러지면 던홀드의 지하 감옥에 있는 스랄을 찾아서 풀어 주십시오. 이후로 그를 따라다니면서, 절대 그가 죽지 않게 보호해 주셔야 합니다!$B$B준비가 되면 브레이즌이 그대를 던홀드까지 데려다 줄 겁니다.', `MaleText_loc4`='潜入敦霍尔德城堡的收容所，在圆桶中放置燃烧弹。点燃五枚燃烧弹，一旦声东击西之计成功，就去敦霍尔德城堡的地下室找到萨尔，并保护他逃走，你必须确保萨尔的生命安全！$B$B如果你准备好了，就跟布拉森谈谈，飞往敦霍尔德城堡吧。', `MaleText_loc5`='你必須在敦霍爾德城堡拘留室裡的桶子旁使用燃燒炸彈包裹。一旦5顆炸彈已經被點燃且轉向已經被設定，找到位於敦霍爾德地下監獄的索爾並且釋放他。跟著他並且確保他的安全!$B$B當你準備好時，布瑞茲恩將載你飛到敦霍爾德。', `MaleText_loc7`='Tienes que usar las bombas incendiarias en los barriles que están dentro de los pabellones de internamiento del Castillo de Durnholde. Cuando cinco bombas hayan explotado y se haya creado una distracción, encuentra a Thrall en la prisión del sótano de Durnholde y libérale. Síguele y asegúrate de que siga con vida.$B$BInsolente te llevará volando hasta Durnholde cuando quieras.' WHERE `ID`=16458;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비가 되었는가? 내가 던홀드로 바로 데려다 주겠다.', `MaleText_loc4`='如果你愿意的话，我可以直接带你去敦霍尔德。', `MaleText_loc5`='我可以立刻帶你去敦霍爾德，如果你想要的話。', `MaleText_loc7`='Te llevaré a Durnholde directamente si es lo que quieres.' WHERE `ID`=16459;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대를 던홀드로 데려다 주기 전에 에로지온에게 화염 폭탄 자루를 받으라. 시간을 낭비하기 싫은 건 결국 그대도 마찬가질 테니...', `MaleText_loc4`='在我带你飞往敦霍尔德之前，你要先从伊洛希恩那儿搞一包燃烧弹。不要浪费时间。', `MaleText_loc5`='在我載你飛到敦霍爾德之前，你應該從伊洛森那獲取燃燒炸彈包裹。畢竟，你不會想要浪費你的時間吧。', `MaleText_loc7`='Erozion te dará un paquete de bombas incendiarias antes de que partas para Durnholde. No tienes tiempo que perder.' WHERE `ID`=16460;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='던홀드 요새로 갈 준비가 끝났습니다.', `MaleText_loc4`='我准备好去敦霍尔德城堡了。', `MaleText_loc5`='我準備好前往敦霍爾德城堡了。', `MaleText_loc7`='Estoy listo para ir al Castillo de Durnholde.', `FemaleText_loc1`='던홀드 요새로 갈 준비가 끝났습니다.', `FemaleText_loc4`='我准备好去敦霍尔德城堡了。', `FemaleText_loc5`='我準備好前往敦霍爾德城堡了。', `FemaleText_loc7`='Estoy lista para ir al Castillo de Durnholde.' WHERE `ID`=16461;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끔찍해... 아주 끔찍해!$B$B황천의 폭풍의 52번 구역에서 오고 있었는데 아무런 이유없이 녀석들이 우릴 격추했지 뭔가! 테로카르 숲으로 빨리 가려는 욕심에 그 지름길로 가는 게 아니었는데!', `MaleText_loc4`='可怕……太可怕了！$B$B我们从虚空风暴的52区起飞，航行途中正想着心事，但他们却把我们射了下来！我知道我们不应该利用那条捷径去泰罗卡森林的！', `MaleText_loc5`='可怕...就只有可怕!$B$B我們只是從虛空風暴的52區離開回來而已，而他們擊落我們!我知道我們不該利用那個捷徑去泰洛卡森林!', `MaleText_loc7`='Horrible... Es horrible.$B$BNo nos metíamos con nadie y al volver del área 52 a la altura de Tormenta Abisal, ¡nos dispararon! ¡Ya sabía yo que no conviene tomar atajos para llegar al Bosque de Terokkar!' WHERE `ID`=16462;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='굴뚝나무 목장조합의 고블린들은 이맘때가 되면 언제나 멋진 물건들을 판답니다.', `MaleText_loc4`='每年的这个时候，烟林牧场的地精们总是会出售一些非常棒的糖果。', `MaleText_loc5`='每年這個時候燻木牧場的哥布林總會賣一些令人驚奇的小東西。', `MaleText_loc7`='Los goblins de Pastos de Bosquehumeante siempre tienen unas golosinas magníficas en esta época del año.', `FemaleText_loc1`='굴뚝나무 목장조합의 고블린들은 이맘때가 되면 언제나 멋진 물건들을 팔지요.', `FemaleText_loc4`='每年的这个时候，烟林牧场的地精们总是会出售一些非常棒的糖果。', `FemaleText_loc5`='每年這個時候燻木牧場的哥布林總會賣一些令人驚奇的小東西。', `FemaleText_loc7`='Los goblins de Pastos de Bosquehumeante siempre tienen unas golosinas magníficas en esta época del año.' WHERE `ID`=16463;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겨울 할아버지는 겨울맞이 축제 기간 동안 오그리마의 나무 아래 있는 모든 사람들에게 선물을 주신답니다. 올해에는 어떤 선물을 주실지 궁금하군요.', `MaleText_loc4`='冬天爷爷会把每个人的礼物放在奥格瑞玛的树下，我在想今年他会给我什么。', `MaleText_loc5`='冬天爺爺將在奧格瑪的樹下為每個人留下禮物。我想知道他今年將帶給我什麼。', `MaleText_loc7`='El Gran Padre Invierno dejará regalos para todos bajo el árbol de Orgrimmar. ¿Qué me traerá este año?', `FemaleText_loc1`='겨울 할아버지는 겨울맞이 축제 기간 동안 오그리마의 나무 아래 있는 모든 사람들에게 선물을 주신답니다. 올해에는 어떤 선물을 주실지 궁금하군요.', `FemaleText_loc4`='冬天爷爷会把每个人的礼物放在奥格瑞玛的树下，我在想今年他会给我什么。', `FemaleText_loc5`='冬天爺爺將在奧格瑪的樹下為每個人留下禮物。我想知道他今年將帶給我什麼。', `FemaleText_loc7`='El Gran Padre Invierno dejará regalos para todos bajo el árbol de Orgrimmar. ¿Qué me traerá este año?' WHERE `ID`=16464;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전설에 따르면 거대한 괴수 오멘이 달숲에 있는 엘룬아라 호수에 잠들어 있으며 일 년에 딱 한 번 나타난다고 하더군요. 하지만 단지 전설일 뿐이겠죠 뭐.', `MaleText_loc4`='传说月光林地的月神湖水下沉睡着一头年兽，一年只出水一次。不过那只是个传说而已。', `MaleText_loc5`='傳說年獸沉睡在月光林地的月神湖水裡，一年只出現一次。但是那只是一個傳說。', `MaleText_loc7`='La leyenda dice que la gran bestia Augurio duerme en las aguas del Lago Elune''ara en Claro de la Luna y solo aparece una vez al año. Pero solo es una leyenda.', `FemaleText_loc1`='전설에 따르면 거대한 괴수 오멘이 달숲에 있는 엘룬아라 호수에 잠들어 있으며 일 년에 딱 한 번 나타난다고 하더군요. 하지만 단지 전설일 뿐이겠죠 뭐.', `FemaleText_loc4`='传说月光林地的月神湖水下沉睡着一头年兽，一年只出水一次。不过那只是个传说而已。', `FemaleText_loc5`='傳說年獸沉睡在月光林地的月神湖水裡，一年只出現一次。但是那只是一個傳說。', `FemaleText_loc7`='La leyenda dice que la gran bestia Augurio duerme en las aguas del Lago Elune''ara en Claro de la Luna y solo aparece una vez al año. Pero solo es una leyenda.' WHERE `ID`=16465;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 달의 축제 기간 동안 장로들을 찾아가서 그분들의 지혜를 배워야 합니다.', `MaleText_loc4`='在春节期间，我们应该花时间来寻找我们的长者，思考他们的智慧。', `MaleText_loc5`='在新年慶典期間，我們應該花時間尋找我們的長輩並且聽取他們的智慧。', `MaleText_loc7`='Durante el Festival Lunar, deberíamos tomarnos algo de tiempo para buscar a nuestros ancianos y ser testigos de su sabiduría.', `FemaleText_loc1`='우리는 달의 축제 기간 동안 장로들을 찾아가서 그분들의 지혜를 배워야 합니다.', `FemaleText_loc4`='在春节期间，我们应该花时间来寻找我们的长者，思考他们的智慧。', `FemaleText_loc5`='在新年慶典期間，我們應該花時間尋找我們的長輩並且聽取他們的智慧。', `FemaleText_loc7`='Durante el Festival Lunar, deberíamos tomarnos algo de tiempo para buscar a nuestros ancianos y ser testigos de su sabiduría.' WHERE `ID`=16466;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불꽃놀이를 구경해 보신 적 있으신가요? 요즘이 1년 중에 폭죽을 구입하기 가장 좋은 때랍니다.', `MaleText_loc4`='你看到烟火了吗？这是一年中购买烟火的最好时刻。', `MaleText_loc5`='你有看過煙火嗎?現在可是一年之中購買它們的最佳時機。', `MaleText_loc7`='¿Has visto los fuegos artificiales? Este es el mejor momento del año para comprarlos.', `FemaleText_loc1`='불꽃놀이를 구경해 보신 적 있으신가요? 요즘이 1년 중에 폭죽을 구입하기 가장 좋은 때랍니다.', `FemaleText_loc4`='你看到烟火了吗？这是一年中购买烟火的最好时刻。', `FemaleText_loc5`='你有看過煙火嗎?現在可是一年之中購買它們的最佳時機。', `FemaleText_loc7`='¿Has visto los fuegos artificiales? Este es el mejor momento del año para comprarlos.' WHERE `ID`=16467;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밤의 안식처에 있는 드루이드들이 달숲에서 달의 축제를 위해 멋진 축하 파티를 열고 있습니다.', `MaleText_loc4`='永夜港的德鲁伊们正在月光林地举办一个隆重的春节庆祝活动。', `MaleText_loc5`='永夜港的德魯伊們正為新年慶典在月光林地舉行一個盛大的慶祝活動。', `MaleText_loc7`='Los druidas de Amparo de la Noche organizan una gran fiesta en Claro de la Luna para el Festival Lunar.', `FemaleText_loc1`='밤의 안식처에 있는 드루이드들이 달숲에서 달의 축제를 위해 멋진 축하 파티를 열고 있답니다.', `FemaleText_loc4`='永夜港的德鲁伊们正在月光林地举办一个隆重的春节庆祝活动。', `FemaleText_loc5`='永夜港的德魯伊們正為新年慶典在月光林地舉行一個盛大的慶祝活動。', `FemaleText_loc7`='Los druidas de Amparo de la Noche organizan una gran fiesta en Claro de la Luna para el Festival Lunar.' WHERE `ID`=16468;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용서하십시오... 전 선택의 여지가 없습니다.', `MaleText_loc4`='原谅我……我别无选择。', `MaleText_loc5`='原諒我...我別無選擇。', `MaleText_loc7`='Perdóname... No tengo elección.' WHERE `ID`=16469;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 말대로 하겠습니다, 악마여. 적어도 지금은...', `MaleText_loc4`='我会按你吩咐的去做，恶魔。至少现在是。', `MaleText_loc5`='我會照你的話做，惡魔。至少目前會。', `MaleText_loc7`='Haré lo que me pides, demonio. Al menos por ahora.' WHERE `ID`=16470;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저를 이 불행의 구렁텅이에서 좀 꺼내 주십시오!', `MaleText_loc4`='结束我的痛苦吧！', `MaleText_loc5`='助我脫離苦海吧!', `MaleText_loc7`='¡Libérame de este sufrimiento!' WHERE `ID`=16471;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 뒤틀린 드레나이 녀석들을 가루로 만들어 버려라, 일리다리! 이 버림받은 땅에 쓸만한 물건이 있다면 우리가 찾아낼 것이다!', `MaleText_loc4`='让这些可怜的破碎者累到吐血吧，伊利达雷！要是这个被遗弃的地方有任何值钱的东西，我们会找到它的！', `MaleText_loc5`='叫那些破碎者蠢蛋們用生命來幹活，伊利達瑞!如果這個遺棄的地方有任何有價值的東西，我們將找到它!', `MaleText_loc7`='¡Acaba con estos malditos gusanos Tábidos, Illidari! ¡Si hay algo de valor en este lugar, lo encontraremos!' WHERE `ID`=16472;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원정대 거점은 얼라이언스에서 군단 전초지와 가장 가까운 연락 지점입니다. 이곳의 북쪽에는 온통 악마들뿐이니 동료와 함께 여행하도록 하십시오.', `MaleText_loc4`='远征军岗哨是联盟最接近燃烧军团前线的联络点。这里的北面除了恶魔还是恶魔。找个朋友搭伴旅行吧。', `MaleText_loc5`='遠征隊哨塔是聯盟與軍團前線最近的接觸點。這裡北部除了惡魔之外別無他物，惡魔和更多的惡魔。建議最好與一個同伴一起旅行。', `MaleText_loc7`='Punta de Expedición es la vanguardia de la Alianza en el frente de la Legión. Al norte de aquí no hay más que demonios, demonios y más demonios. No viajes $gsolo:sola;.' WHERE `ID`=16473;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 뒤틀린 드레나이 놈을 잘 감시해라! 탈출한 녀석들이 너무 많다!', `MaleText_loc4`='看紧这些破碎者人渣！已经有很多从我们这里逃走了！', `MaleText_loc5`='盯好這個破碎者人渣!太多人從我們這裡逃跑了!', `MaleText_loc7`='¡Vigilad bien a estos malditos Tábidos! Ya se han escapado demasiadas veces.' WHERE `ID`=16474;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님께서 원하시는 걸 찾게 될 것이다! 실패는 용납할 수 없다!', `MaleText_loc4`='我们必须找到主人想要的东西！只许成功，不许失败！', `MaleText_loc5`='我們會找到主人在找的東西!失敗不是我們的選擇!', `MaleText_loc7`='¡Encontraremos lo que busca el maestro! ¡El fracaso no es una opción!' WHERE `ID`=16475;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이놈들이 잠시도 쉬지 못하게 하라! 이곳에 아타말 수정이 있다면 반드시 찾을 것이다!', `MaleText_loc4`='不要让这些可怜虫有一点点喘息的时间！如果这里真的有一颗阿塔玛水晶的话，那么我们会找到它的！', `MaleText_loc5`='不要給這些可惡的人片刻的休息時間!如果這裡有一顆阿塔莫水晶，那麼我們將找到它!', `MaleText_loc7`='¡No les deis ni un momento de descanso! ¡Si hay algún cristal de Ata''mal aquí, lo encontraremos!' WHERE `ID`=16476;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 두 명령서는 이번 파견에 대해 급하게 갈겨 쓴 내용이 있습니다.', `MaleText_loc4`='这封信件上潦草地书写着两道指令。', `MaleText_loc5`='兩組命令看起來像是被急速潦草地書寫在這公文上。', `MaleText_loc7`='Aquí se han escrito dos partes con órdenes rápidas.' WHERE `ID`=16477;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠의 문이 다시 열렸습니다! 도대체 어떤 일이 벌어질까요?', `MaleText_loc4`='黑暗之门再度开启了！这预示着什么？', `MaleText_loc5`='黑暗之門再次開啟!這意味著什麼?', `MaleText_loc7`='¡El Portal Oscuro vuelve a abrirse! ¿Qué presagia?', `FemaleText_loc1`='어둠의 문이 다시 열렸습니다! 도대체 어떤 일이 벌어질까요?', `FemaleText_loc4`='黑暗之门再度开启了！这预示着什么？', `FemaleText_loc5`='黑暗之門再次開啟!這意味著什麼?', `FemaleText_loc7`='¡El Portal Oscuro vuelve a abrirse! ¿Qué presagia?' WHERE `ID`=16478;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불타는 군단이 돌아왔습니다! 어떻게 그들을 막아야 할까요?', `MaleText_loc4`='燃烧军团回来了！我们该如何来阻止他们？', `MaleText_loc5`='燃燒軍團回來了!我們要怎麼去阻止他們?', `MaleText_loc7`='¡La Legión Ardiente ha vuelto! ¿Qué podemos hacer para detenerles?', `FemaleText_loc1`='불타는 군단이 돌아왔습니다! 어떻게 그들을 막아야 할까요?', `FemaleText_loc4`='燃烧军团回来了！我们该如何来阻止他们？', `FemaleText_loc5`='燃燒軍團回來了!我們要怎麼去阻止他們?', `FemaleText_loc7`='¡La Legión Ardiente ha vuelto! ¿Qué podemos hacer para detenerles?' WHERE `ID`=16479;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 고대 드레나이 수정과 유물에 대해 알고 있기 때문에 일리다리 악마들은 내가 이곳에서 떠나지 못하게 하고 있소.$B$B녀석들은 우리 종족들을 노예로 부려서 강력한 수정을 찾는 데 동원하고 있소이다... 이곳에는 십중팔구 수정이 없을 것 같은데 말이오.', `MaleText_loc4`='因为我了解古代德莱尼水晶和遗迹，所以伊利达雷的恶魔们把我囚禁在这里。$B$B他们奴役了我的很多族人，并且利用我们寻找一块能量巨大的水晶……一块可能根本不在这里的水晶。', `MaleText_loc5`='因為我對古老德萊尼水晶和遺物的知識，伊利丹的惡魔將我囚禁在這裡。$B$B他們已經奴役我們大多數人，並且利用我們尋找一顆強而有力的水晶...一顆甚至很可能根本不在這裡的水晶。', `MaleText_loc7`='Los demonios Illidari me tienen aquí por mis conocimientos sobre antiguos cristales y reliquias draenei.$B$BHan esclavizado a muchos de los míos y nos usan para buscar un cristal muy poderoso... Uno que probablemente no esté aquí.' WHERE `ID`=16481;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드레나이... 너무 많아서 믿기 어려울 정도로군요. 하지만 그들이 성스러운 빛을 따른다면 그렇게까지 나빠지지는 않을 겁니다.', `MaleText_loc4`='德莱尼人……根本不可相信。不过如果他们是圣光的追随者，应该也坏不到哪儿去。', `MaleText_loc5`='德萊尼...這幾乎難以置信。但是如果他們跟隨聖光，他們不可能那麼壞。', `MaleText_loc7`='Los draenei... es casi demasiado para creérselo. Pero si son seguidores de la Luz, no pueden ser tan malos.', `FemaleText_loc1`='드레나이... 너무 많아서 믿기 어려울 정도로군요. 하지만 그들이 성스러운 빛을 따른다면 그렇게까지 나빠지지는 않을 겁니다.', `FemaleText_loc4`='德莱尼人……根本不可相信。不过如果他们是圣光的追随者，应该也坏不到哪儿去。', `FemaleText_loc5`='德萊尼...這幾乎難以置信。但是如果他們跟隨聖光，他們不可能那麼壞。', `FemaleText_loc7`='Los draenei... es casi demasiado para creérselo. Pero si son seguidores de la Luz, no pueden ser tan malos.' WHERE `ID`=16482;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엘프들이 어떻게 우리를 배신할 수가 있습니까? 우리가 최고의 동료는 아니었다고 해도 호드와 동맹을 맺다니요?', `MaleText_loc4`='精灵们怎么能背叛我们？我们虽不是最好的朋友，但是加入部落……搞笑吧？', `MaleText_loc5`='精靈怎麼會背叛我們?我們從不是最好的朋友，但也不至於加入部落吧?', `MaleText_loc7`='¿Cómo han podido los elfos traicionarnos? Vale, nunca hemos sido los mejores amigos del mundo... ¿pero unirse a la Horda?', `FemaleText_loc1`='엘프들이 어떻게 우리를 배신할 수가 있죠? 우리가 최고의 동료는 아니었다고 해도 호드와 동맹을 맺다니요?', `FemaleText_loc4`='精灵们怎么能背叛我们？我们虽不是最好的朋友，但是加入部落……搞笑吧？', `FemaleText_loc5`='精靈怎麼會背叛我們?我們從不是最好的朋友，但也不至於加入部落吧?', `FemaleText_loc7`='¿Cómo han podido los elfos traicionarnos? Vale, nunca hemos sido los mejores amigos del mundo... ¿pero unirse a la Horda?' WHERE `ID`=16483;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠의 문이 건재하다고요? 좋은 소식은 아니로군요.', `MaleText_loc4`='黑暗之门活跃起来了？这不是个好消息。', `MaleText_loc5`='黑暗之門重生了?情況不妙。', `MaleText_loc7`='¿El Portal Oscuro vuelve a la vida? Esto no tiene buena pinta...', `FemaleText_loc1`='어둠의 문이 건재하다고요? 좋은 소식은 아니로군요.', `FemaleText_loc4`='黑暗之门活跃起来了？这不是个好消息。', `FemaleText_loc5`='黑暗之門重生了?情況不妙。', `FemaleText_loc7`='¿El Portal Oscuro vuelve a la vida? Esto no tiene buena pinta...' WHERE `ID`=16484;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇다면 탈출하는 게 어떻습니까?', `MaleText_loc4`='你为什么不逃呢？', `MaleText_loc5`='你為什麼不逃跑?', `MaleText_loc7`='¿Por qué no escapas?', `FemaleText_loc1`='그렇다면 탈출하는 게 어떤가요?', `FemaleText_loc4`='你为什么不逃呢？', `FemaleText_loc5`='你為什麼不逃跑?', `FemaleText_loc7`='¿Por qué no escapas?' WHERE `ID`=16485;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왕립 연금술 학회의 일원들이 리치 왕의 역병을 치료할 방법을 조사하고 있습니다.', `MaleText_loc4`='炼金师协会研究出了治愈巫妖王天灾的方法。', `MaleText_loc5`='藥劑師學會著手研究尋求出巫妖王瘟疫的解藥。', `MaleText_loc7`='La Sociedad de Boticarios busca una cura contra la plaga del Rey Exánime.', `FemaleText_loc1`='왕립 연금술 학회의 일원들이 리치 왕의 역병을 치료할 방법을 조사하고 있습니다.', `FemaleText_loc4`='炼金师协会研究出了治愈巫妖王瘟疫的方法。', `FemaleText_loc5`='藥劑師學會著手研究尋求出巫妖王瘟疫的解藥。', `FemaleText_loc7`='La Sociedad de Boticarios busca una cura contra la plaga del Rey Exánime.' WHERE `ID`=16486;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭣 때문에 말이오? 일리단의 악마들이 날 붙잡아서 노예로 삼지 않으면 장가르 습지대의 나가들이 그렇게 할 텐데 무슨 소용이 있겠소.$B$B뒤틀린 드레나이 일족들이 일리단과 그의 동맹들에게 가담해봤자 대부분이 다 노예가 될 뿐이오. 내 동족들에게는 아무런 희망도 없소이다.', `MaleText_loc4`='为什么？就算伊利丹的恶魔不再抓住我、奴役我，那么赞加沼泽的纳迦也会这么做的。$B$B加入伊利丹和他的恶魔大军无非是为破碎者氏族套上新的枷锁罢了。我们的人民没有任何希望。', `MaleText_loc5`='為什麼?如果伊利丹的惡魔沒有再次抓到我並奴役我，贊格沼澤的納迦也會。$B$B加入伊利丹和他所屬聯盟的人原來只是一些破碎者部族裡的奴役。我的人民沒有希望了。', `MaleText_loc7`='¿Para qué? Si los demonios de Illidan no me capturan y me vuelven a esclavizar, entonces serán los nagas de la Marisma de Zangar quienes lo hagan.$B$BUnirse a Illidan y a sus aliados significa esclavitud para las tribus de Tábidos. A mi pueblo no le queda esperanza.' WHERE `ID`=16487;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕이 공세를 취하는 상황이니 호드에서도 같은 방법으로 응해줘야 합니다! 노스렌드로 갑시다!', `MaleText_loc4`='巫妖王展开了攻势，部落必须做出有力的回应！远征诺森德！', `MaleText_loc5`='只要巫妖王不停止進攻腳步，部落便需要對他迎頭痛擊!殺到北裂境!', `MaleText_loc7`='¡Con el Rey Exánime a la ofensiva, la Horda debe responder de la misma forma! ¡A Rasganorte!', `FemaleText_loc1`='리치 왕이 공세를 취하는 상황이니 호드에서도 같은 방법으로 응해줘야 합니다! 노스렌드로 갑시다!', `FemaleText_loc4`='巫妖王展开了攻势，部落必须做出有力的回应！远征诺森德！', `FemaleText_loc5`='只要巫妖王不停止進攻腳步，部落便需要對他迎頭痛擊!殺到北裂境!', `FemaleText_loc7`='¡Con el Rey Exánime a la ofensiva, la Horda debe responder de la misma forma! ¡A Rasganorte!' WHERE `ID`=16488;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛의 수호자시여, 또 다른 특수 부대가 도착한 것 같습니다.', `MaleText_loc4`='长官，看来我们的另一批特殊单位已经到位了。', `MaleText_loc5`='長官，看來我們的另一批特派人員已到達。', `MaleText_loc7`='Señor, parece ser que ha llegado otra de nuestras unidades especiales.' WHERE `ID`=16489;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훌륭하군. 우리는 나그란드를 정화하는 데 총력을 기울여야 한다는 뜻을 전하십시오!', `MaleText_loc4`='太好了。我们必须把精力集中在清理纳格兰这件事情上！', `MaleText_loc5`='非常好。我們一定要集中火力淨化納葛蘭!', `MaleText_loc7`='Excelente. Debemos centrar nuestros esfuerzos en la limpieza de Nagrand.' WHERE `ID`=16490;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠습니다!', `MaleText_loc4`='明白了，大人。', `MaleText_loc5`='了解，長官。', `MaleText_loc7`='Entendido, señor.' WHERE `ID`=16491;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 들어라, 제군들!', `MaleText_loc4`='听好了，士兵们！', `MaleText_loc5`='聽好了，士兵們!', `MaleText_loc7`='¡Escuchad, soldados!' WHERE `ID`=16492;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제군들은 훈련 과정에서 뛰어난 태도와 능력을 보여주었기 때문에 이 자리에 서게 된 것이다.', `MaleText_loc4`='我叫你来是因为你在训练中显示出了过人的才智与能力。', `MaleText_loc5`='你在這裡是因為你在整個訓練期間顯現出特別的天資和能力。', `MaleText_loc7`='Estáis aquí porque habéis demostrado una gran aptitud y mucha habilidad durante el entrenamiento.' WHERE `ID`=16493;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 제군들은 위험한 임무를 맡아서 적진으로 파견될 것이다.', `MaleText_loc4`='你现在要直接前往敌方领地执行一个危险的任务。', `MaleText_loc5`='你現在將為一項背叛的任務被直接派遣進入敵方陣營。', `MaleText_loc7`='Ahora vais a ser enviados directamente a territorio enemigo en una misión complicada.' WHERE `ID`=16494;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서쪽 땅 나그란드에서 들끓는 분노의 괴철로가 최근 우리의 안전을 크게 위협하고 있다.', `MaleText_loc4`='纳格兰，西边的那块大陆，敌人在那里的铸魔营地威胁着我们的安全，使纳格兰最近变得有点混乱。', `MaleText_loc5`='納葛蘭，位於西方的土地，最近已經到處布滿著威脅我們安全的敵人熔爐營地。', `MaleText_loc7`='Nagrand, la tierra del oeste, está infestada de campamentos Forja enemigos que suponen una amenaza para nuestra seguridad.' WHERE `ID`=16495;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일리단에게 공격을 집중한 상태에서 이 땅을 정화하는 일은 바로 제군들의 몫이다.', `MaleText_loc4`='由于我们大部分的力量都聚集在伊利丹身上，清理这片土地的任务就交给你了。', `MaleText_loc5`='由於我們的部隊大部分專注於對付伊利丹，淨化這些土地的任務就落在你身上了。', `MaleText_loc7`='Con el grueso de nuestras tropas concentradas en Illidan, la tarea de limpiar estas tierras cae sobre ustedes.' WHERE `ID`=16496;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앞으로 일주일 후에 제군들의 성과에 대한 자세한 보고서를 가지고 돌아오도록.', `MaleText_loc4`='你应该在一周之内带回一份详细的行动报告。', `MaleText_loc5`='你要在一週內帶著詳細的行動報告回來。', `MaleText_loc7`='Tienes que volver en una semana con un informe detallado sobre tus actividades.' WHERE `ID`=16497;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성스러운 빛이 제군들과 함께하기를... 이만 해산!', `MaleText_loc4`='愿圣光与你同在……解散！', `MaleText_loc5`='願聖光與你同在...我先告退了!', `MaleText_loc7`='Que la Luz esté con ustedes. ¡Retírense!' WHERE `ID`=16498;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스랄이 무시무시한 고함 소리로 말을 놀라게 합니다!', `MaleText_loc4`='萨尔的怒吼使马匹都为之战栗！', `MaleText_loc5`='索爾兇猛的吼叫聲嚇著了馬兒。', `MaleText_loc7`='¡Thrall asusta al caballo con un fuerte grito!' WHERE `ID`=16499;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='굴뚝나무 목장조합에서 새로 내놓은 물건이 보고 싶어 못 참겠습니다.', `MaleText_loc4`='我迫不及待地想看看烟林牧场的新货物。', `MaleText_loc5`='我等不及要看燻木牧場最新的商品。', `MaleText_loc7`='Tengo muchas ganas de ver las nuevas mercancías de Pastos de Bosquehumeante.', `FemaleText_loc1`='굴뚝나무 목장조합에서 새로 내놓은 물건이 보고 싶어 못 참겠어요.', `FemaleText_loc4`='我迫不及待地想看看烟林牧场的新货物。', `FemaleText_loc5`='我等不及要看燻木牧場最新的商品。', `FemaleText_loc7`='Tengo muchas ganas de ver las nuevas mercancías de Pastos de Bosquehumeante.' WHERE `ID`=16500;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 겨울맞이 윈터볼트. 다음은 어떤 걸 생각해 볼까요?', `MaleText_loc4`='啊，冬幕欢乐制造器。下一次我们该想点什么？', `MaleText_loc5`='啊，冬幕歡樂製造器。我們下一個會想到什麼?', `MaleText_loc7`='Ah, el Maravoltio Invernal. ¿Qué será lo siguiente?', `FemaleText_loc1`='아, 겨울맞이 윈터볼트. 다음은 어떤 걸 생각해 볼까요?', `FemaleText_loc4`='啊，冬幕欢乐制造器。下一次我们该想点什么？', `FemaleText_loc5`='啊，冬幕歡樂製造器。我們下一個會想到什麼?', `FemaleText_loc7`='Ah, el Maravoltio Invernal. ¿Qué será lo siguiente?' WHERE `ID`=16501;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엘프든 드레나이든 우리 기술자들에게는 돈으로밖에 안 보일 겁니다.', `MaleText_loc4`='精灵们或德莱尼人，对我们的工程师来说，不过是又多了两条财路。', `MaleText_loc5`='精靈或德萊尼，對我們的工程師而言都是更多的錢。', `MaleText_loc7`='Elfos o draenei; eso solo significa más dinero para nuestros ingenieros.', `FemaleText_loc1`='엘프든 드레나이든 우리 기술자들에게는 돈으로밖에 안 보일 겁니다.', `FemaleText_loc4`='精灵们或德莱尼人，对我们的工程师来说，不过是又多了两条财路。', `FemaleText_loc5`='精靈或德萊尼，對我們的工程師而言都是更多的錢。', `FemaleText_loc7`='Elfos o draenei; eso solo significa más dinero para nuestros ingenieros.' WHERE `ID`=16502;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 멋진 겨울 모자들은 어디서 가져오는 겁니까?', `MaleText_loc4`='那些漂亮的圣诞帽是哪里来的？', `MaleText_loc5`='那些超棒的冬帽是從哪裡來的?', `MaleText_loc7`='¿De dónde vienen todos esos magníficos sombreros de invierno?', `FemaleText_loc1`='이 멋진 겨울 모자들은 어디서 가져오는 거죠?', `FemaleText_loc4`='那些漂亮的圣诞帽是哪里来的？', `FemaleText_loc5`='那些超棒的冬帽是從哪裡來的?', `FemaleText_loc7`='¿De dónde vienen todos esos magníficos sombreros de invierno?' WHERE `ID`=16503;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시는 지름길로 가지 않을 것이네. 내 맹세하지! 지옥불 반도의 하늘이 그렇게 위험할 줄이야 누가 알았겠나?', `MaleText_loc4`='我发誓，我再也不会走捷径了！我怎么知道地狱火半岛的上空那么危险？', `MaleText_loc5`='我絕不會再抄捷徑了，我發誓!我怎麼會知道在地獄火半島上方的天空是那麼的危險?', `MaleText_loc7`='¡Juro que jamás volveré a ir por un atajo! ¿Cómo se supone que iba a saber que los cielos sobre la Península del Fuego Infernal eran tan peligrosos?' WHERE `ID`=16504;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죄송하지만 급하게 해결해야 할 문제가 있어서 가보겠습니다.', `MaleText_loc4`='对不起，长官，我有紧急事件需要禀报。', `MaleText_loc5`='遵命，長官，我有要緊的事情要去做。', `MaleText_loc7`='Con su venia, señor; tengo asuntos urgentes que atender.' WHERE `ID`=16505;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수도자 닌두멘, 청이 하나 있습니다.', `MaleText_loc4`='学者尼度门，我有一事相求。', `MaleText_loc5`='隱士奈杜曼，我對你有一個請求。', `MaleText_loc7`='Anacoreta Nindumen, tengo que pedirte algo.' WHERE `ID`=16506;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방금 또 다른 신병 부대를 나그란드로 보냈습니다. 그들을 위해 기도해 주시겠습니까?', `MaleText_loc4`='我们刚派了另一队新手队伍进驻了纳格兰。你能为他们祈祷平安吗？', `MaleText_loc5`='我們剛剛把另一個無經驗的小隊送到納葛蘭。你可以為他們禱告嗎?', `MaleText_loc7`='Acabamos de enviar un escuadrón de novatos a Nagrand. ¿Podrías orar por ellos?' WHERE `ID`=16507;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋다, 선구자여! 가보도록!', `MaleText_loc4`='当然，先驱者。解散。', `MaleText_loc5`='當然，先驅者。退下吧。', `MaleText_loc7`='Por supuesto, presagista. Puedes marcharte.' WHERE `ID`=16508;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스포어링들은 왜 다리 밑에서 살까?', `MaleText_loc4`='我想知道为什么孢子人住在桥下面？', `MaleText_loc5`='不知道為什麼孢子人都住在橋下?', `MaleText_loc7`='Me pregunto por qué los esporines viven bajo el puente.', `FemaleText_loc1`='스포어링들은 왜 다리 밑에서 살까?', `FemaleText_loc4`='我想知道为什么孢子人住在桥下面？', `FemaleText_loc5`='不知道為什麼孢子人都住在橋下?', `FemaleText_loc7`='Me pregunto por qué los esporines viven bajo el puente.' WHERE `ID`=16509;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스포어링은 색깔이 참 예뻐.', `MaleText_loc4`='孢子人有着漂亮的颜色。', `MaleText_loc5`='孢子人都有漂亮的顏色。', `MaleText_loc7`='Los esporines tienen colores muy bonitos.', `FemaleText_loc1`='스포어링은 색깔이 참 예뻐.', `FemaleText_loc4`='孢子人有着漂亮的颜色。', `FemaleText_loc5`='孢子人都有漂亮的顏色。', `FemaleText_loc7`='Los esporines tienen colores muy bonitos.' WHERE `ID`=16510;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='운동을 열심히 하지 않으면 스포어링처럼 될 수도 있다고 엄마가 그러셨어.', `MaleText_loc4`='我妈妈说要是我不好好锻炼的话，最后我会变得像个孢子人一样。', `MaleText_loc5`='我媽媽說如果我不做足夠的運動，我就會變的跟孢子人一樣。', `MaleText_loc7`='Mi mamá me dijo que si no hago el suficiente ejercicio, acabaré pareciéndome a un esporito.', `FemaleText_loc1`='운동을 열심히 하지 않으면 스포어링처럼 될 수도 있다고 엄마가 그러셨어.', `FemaleText_loc4`='我妈妈说要是我不好好锻炼的话，最后我会变得像个孢子人一样。', `FemaleText_loc5`='我媽媽說如果我不做足夠的運動，我就會變的跟孢子人一樣。', `FemaleText_loc7`='Mi mamá me dijo que si no hago el suficiente ejercicio, acabaré pareciéndome a un esporito.' WHERE `ID`=16511;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엄마는 자정이 넘어서 스포어링에게 먹이를 주면 안 된다고 하셨어.', `MaleText_loc4`='妈妈说不要在午夜之后喂孢子人。', `MaleText_loc5`='媽媽說午夜以後就不要再餵孢子人了。', `MaleText_loc7`='Mamá dice que no hay que darles de comer después de medianoche.', `FemaleText_loc1`='엄마는 자정이 넘어서 스포어링에게 먹이를 주면 안 된다고 하셨어.', `FemaleText_loc4`='妈妈说不要在午夜之后喂孢子人。', `FemaleText_loc5`='媽媽說午夜以後就不要再餵孢子人了。', `FemaleText_loc7`='Mamá dice que no hay que darles de comer después de medianoche.' WHERE `ID`=16512;
