UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 밀드레드 간호사님이 정말 좋아. 우리 아빠가 다쳤을 때 고쳐주셨거든.', `MaleText_loc4`='米尔蕾护士真是个好人，她在我爸爸受伤的时候照顾了他。', `MaleText_loc5`='米歐瑞德護士真的很好，她在我爸爸受傷的時候照顧他。', `MaleText_loc7`='La enfermera Mildred es muy simpática. Cuidó de mi papá cuando estaba herido.', `FemaleText_loc1`='난 밀드레드 간호사님이 정말 좋아. 우리 아빠가 다쳤을 때 고쳐주셨거든.', `FemaleText_loc4`='米尔蕾护士真是个好人，我爸爸受伤的时候是她护理的。', `FemaleText_loc5`='米歐瑞德護士真的很好，她在我爸爸受傷的時候照顧他。', `FemaleText_loc7`='La enfermera Mildred es muy simpática. Cuidó de mi papá cuando estaba herido.' WHERE `ID`=16514;
