UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겨울맞이 축제가 열리고 있는 곳을 알려 주십시오.', `MaleText_loc4`='告诉我冬幕节庆典在哪里举行。', `MaleText_loc5`='帶我去冬幕節慶典的地點。', `MaleText_loc7`='Enséñame dónde se celebra el Festival de Invierno.', `FemaleText_loc1`='겨울맞이 축제가 열리고 있는 곳을 알려 주십시오.', `FemaleText_loc4`='告诉我冬幕节庆典在哪里举行。', `FemaleText_loc5`='帶我去冬幕節慶典的地點。', `FemaleText_loc7`='Enséñame dónde se celebra el Festival de Invierno.' WHERE `ID`=16543;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리될 것입니다.', `MaleText_loc4`='愿我们的愿望能够实现。', `MaleText_loc5`='但願如此。', `MaleText_loc7`='Que así sea.', `FemaleText_loc1`='그리될 거예요.', `FemaleText_loc4`='愿我们的愿望能够实现。', `FemaleText_loc5`='但願如此。', `FemaleText_loc7`='Que así sea.' WHERE `ID`=16544;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사령관들이여, 함께 칼을 든 형제자매들이여, 수천 명의 병사를 보내기보다 내가 몸소 그대들과 함께 싸우겠다. 우리는 전장의 호랑이들이다! 저 악마들과 어둠의 문 너머 무엇이 기다리고 있는지 그대들도 알 것이다. 영생이 우리 것이다!', `MaleText_loc4`='军官们……生死与共的兄弟姐妹们。比起指挥千军万马，我宁可与你们并肩血战。我们是一群狮子！你们知道在黑暗之门和这些恶魔背后有什么在等待着我们吗？是永恒！是不朽！', `MaleText_loc5`='元帥...持劍比肩的同袍。與任何數千的軍隊相比，我寧願與你們並肩戰鬥。我們是獅群!你知道在這些惡魔和在黑暗之門之後是什麼在等待著我們嗎?就是永垂不朽!去吧!', `MaleText_loc7`='Mariscales... Hermanos y hermanas de la espada. Prefiero luchar a su lado que junto con un ejército de mil. ¡Somos leones! Saben lo que nos espera detrás de esos demonios y del Portal Oscuro. ¡La inmortalidad! ¡Tomenla!' WHERE `ID`=16545;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 의무를 다한 후 아제로스의 인간들이 천 년 동안 살아남는다면, 그때야 비로소 우리의 시간이 헛되지 않았다고 말할 수 있을 것이다.', `MaleText_loc4`='让我们振作起来，完成我们的使命。如果艾泽拉斯的人类可以延续千年，那么千年后的人们谈起今天的时候会说，“这是人类最辉煌而骄傲的时刻。”', `MaleText_loc5`='讓我們因此讓我們撐起我們的職責，因此支持我們自己，以致於如果艾澤拉斯的人類持續了一千年，人們仍然會說，這是他們最精采的時候。', `MaleText_loc7`='Dejad que nos entreguemos a nuestro deber y conseguir que, aunque los Humanos de Azeroth duren mil años, los hombres sigan diciendo ''esta fue su época dorada''.' WHERE `ID`=16546;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 오래된 불화와 결속을 뒤로하고 왕국과 백성들이 한데 모일 시간이다. 절대 이길 수 없을 것 같은 전쟁이 다가왔고 저 높은 곳에서 피난처를 찾아야 한다. 그렇지 않으면 우린 어둠의 홍수에 모두 휩쓸릴 것이다.', `MaleText_loc4`='是时候让我们，每一个王国，每一个人，摒弃我们长久以来的不合并团结一心了。一场希望渺茫的战争就在我们面前，而我们必须寻求更高的庇护，否则就会被黑暗的洪水吞没。', `MaleText_loc5`='現在是我們把王國和個人們在長期以來的世仇放在一邊並且結合的時候了。 一個贏不了的戰爭向我們襲捲而來，而我們必須在更高的地上尋找避難處，以免我們被這大批黑暗捲走。', `MaleText_loc7`='Ya es hora de que, como reinos y como individuos, apartemos nuestras viejas rencillas y nos unamos. Una guerra imposible de ganar se cierne sobre nosotros y debemos refugiarnos en terreno elevado o dejar que nos arrastre la marea de oscuridad.' WHERE `ID`=16547;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싸우면 죽고 도망치면 살 것이 자명하지만 그런 삶을 얼마나 오래 지탱하길 바라는가? 우리 눈앞에 악마들이 있다. 이 자리에 없는 이들, 몇 주전 마을에서 죽어간 이들을 생각하라. 그들이 우리 세계를 침략한 이 공포를 막기 위해 얼마나 이 자리에 있기를 바라는가?', `MaleText_loc4`='没错，战斗，也许你会阵亡。逃跑，或许你可以活下来，但你能活多久呢？恶魔就在我们面前！那些畏缩不前的懦夫，过不了几周就会在自己的村庄中死去。他们是否愿意用那些惶惶不安的逃难岁月换取一次守护黑暗之门的机会，换取一次阻止那些企图入侵艾泽拉斯世界的恶魔大军的机会？', `MaleText_loc5`='是的。作戰，你可能會死。逃跑，你可能會活著，但多久?魔鬼們是不會放過我們的!而那些不在這裡的，將從現在起數週內在他們的村莊死去，他們願意用從今日起的全部日子去交換一個來這裡，並且阻止這些恐怖侵入我們的世界的機會嗎?', `MaleText_loc7`='Sí. Lucha y morirás. Corre y vivirás. Pero ¿por cuánto tiempo? ¡Se acercan los demonios! Y los que no están aquí, que morirán en sus pueblos en cuestión de semanas, se arrepentirán de no haber estado junto a nosotros en este día para detener a los horrores que invaden nuestro mundo.' WHERE `ID`=16548;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 싸워야 한다. 절대 도망쳐서는 안 된다.', `MaleText_loc4`='所有人都要奋战到底，永不退缩。', `MaleText_loc5`='所有人都要續奮戰。一個都不准放棄。', `MaleText_loc7`='Todo el mundo lucha. Nadie abandona.' WHERE `ID`=16549;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영토를 사수하라! 얼라이언스의 아들 딸들이여, 호드의 형제자매들이여! 그대들의 눈동자에서 내 가슴을 서늘하게 한 것과 같은 공포를 보았다. 우리의 용기가 사그라져서 친구들을 배반하고 우정을 깨뜨릴 날도 있을지 모른다. 하지만, 그날이 오늘은 아니다!', `MaleText_loc4`='坚守你们的阵地！坚守你们的阵地！联盟的子民们！部落的子民们！我的兄弟姐妹们！在你们的眼中，我看到了同样存在于我心中的恐惧。也许某一天我们的勇气会消逝，也许我们会遗弃自己的朋友，也许我们的友谊会荡然无存……但决不是今天。', `MaleText_loc5`='堅守陣地!堅守陣地!聯盟的子孫! 部落的子孫!我的兄弟姐妹!我在你們眼睛裡看見在我心中相同的恐懼。我們勇氣失敗的一天或許會到來，就在我們遺棄我們的朋友並且毀壞我們的友誼時...但是絕對不是今天。', `MaleText_loc7`='¡Aguanten! ¡Aguanten! ¡Hijos de la Alianza! ¡Y de Horda! ¡Hermanos y hermanas! Veo en sus ojos el mismo miedo que alguna vez se apoderó de mi corazón. Puede que llegue el día en el que nuestra valentía nos abandone; un día en el que maldigamos a nuestros amigos y no respetemos nuestra palabra..., pero no será hoy.' WHERE `ID`=16550;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘, 우리는 싸운다! 이 소중한 땅에서 버틸 수 있을 만큼 버틴다! 그대들을 믿는다, 아제로스의 영웅들이여!', `MaleText_loc4`='今天，我们战斗到底！以这片美丽的土地上所有你们所爱的人的名义，我命令你们坚守阵地，艾泽拉斯的英雄们！', `MaleText_loc5`='今天我們戰鬥!!為了你們在這些土地上所珍視的全部，我命令你們站起來，艾澤拉斯的英雄們!', `MaleText_loc7`='¡¡Hoy lucharemos!! ¡Por todo lo que amáis en estas nobles tierras, os pido que luchéis, héroes de Azeroth!' WHERE `ID`=16551;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형제자매들이여, 우리의 수는 적지만 오늘 나와 함께 피를 나누자! 그렇게 지독하지는 않으리라. 최근 적들의 상황은 악화되었다.', `MaleText_loc4`='勇士们，我的兄弟姐妹们，我们并肩作战，流血牺牲，你们是我最亲密的战友。就让战火洗练出你们崇高的价值，赢得后世的美名吧。', `MaleText_loc5`='我們人數很少，我們對人數很少感到愉快，我們是團結的兄弟姐妹。那些今天與我一同灑流血的，將是我的家族;不管他們多麼的卑微，今天將使他們變的高貴。', `MaleText_loc7`='Por nosotros, esos pocos afortunados, hermanas y hermanos. Por los que hoy han derramado su sangre conmigo, por los míos. Que este día nos haga mejores.' WHERE `ID`=16552;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 이 자리에 있지 않은 아제로스의 모험가들은 여기 오지 않은 것을 수치스럽게 여겨야 한다. 그들은 이 불운한 나날에 우리와 함께 싸운 이야기를 하는 영웅들 앞에서 비겁한 자신을 발견할 것이다.', `MaleText_loc4`='那些畏缩在艾泽拉斯世界各个角落中的懦夫们，当有人谈起这个黑暗的日子时，他们必定会为自己的胆怯感到羞愧。', `MaleText_loc5`='而那些現在在艾澤拉斯的人，可惡的希望他們的存在不被察覺，所以當任何人提起與我們並肩作戰直到這個黑暗之日時，他們總是會默默不語。', `MaleText_loc7`='Y los que en Azeroth estén hoy en la cama, se maldecirán por no haber estado aquí. Tendrán que callarse cuando alguno de los que estuvo aquí diga que luchó con nosotros en este amargo día.' WHERE `ID`=16553;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빨리 해라! 투석기들을 공격에 써먹을 수 있도록 정비해야 한다!', `MaleText_loc4`='动作快点！我们需要这些投石器来发动进攻！', `MaleText_loc5`='動作快一點!我們需要這些投石車來發動攻擊!', `MaleText_loc7`='¡Trabaja más rápido! ¡Las catapultas tienen que estar listas para atacar!', `FemaleText_loc1`='빨리 해라! 투석기들을 공격에 써먹을 수 있도록 정비해야 한다!', `FemaleText_loc4`='动作快点！我们需要这些投石器来发动进攻！', `FemaleText_loc5`='動作快一點!我們需要這些投石車來發動攻擊!', `FemaleText_loc7`='¡Trabaja más rápido! ¡Las catapultas tienen que estar listas para atacar!' WHERE `ID`=16554;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='망가진 투석기에서 쓸만한 부품을 꺼내라!', `MaleText_loc4`='从坏掉的投石器上回收一切你们需要的东西！', `MaleText_loc5`='從破碎的投石機裡拿取你所需要的!', `MaleText_loc7`='¡Recupera lo que necesites de las catapultas rotas!', `FemaleText_loc1`='망가진 투석기에서 쓸만한 부품을 꺼내라!', `FemaleText_loc4`='从坏掉的投石器上回收一切你们需要的东西！', `FemaleText_loc5`='從破碎的投石機裡拿取你所需要的!', `FemaleText_loc7`='¡Recupera lo que necesites de las catapultas rotas!' WHERE `ID`=16555;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음에 일을 망치는 놈은 밤새 저주받은 지역을 순찰할 줄 알아라!', `MaleText_loc4`='你们这些苦工谁要是再犯错，就给我在这被诅咒的边界巡夜！', `MaleText_loc5`='下一個把事情搞砸的苦工，將花一個晚上巡邏被詛咒的周邊陣地!', `MaleText_loc7`='El próximo peón que la vuelva a liar pasará la noche patrullando el maldito perímetro.', `FemaleText_loc1`='다음에 일을 망치는 놈은 밤새 저주받은 지역을 순찰할 줄 알아라!', `FemaleText_loc4`='你们这些苦工谁要是再犯错，就给我在这被诅咒的边界巡夜！', `FemaleText_loc5`='下一個把事情搞砸的苦工，將花一個晚上巡邏被詛咒的周邊陣地!', `FemaleText_loc7`='El próximo peón que la vuelva a liar pasará la noche patrullando el maldito perímetro.' WHERE `ID`=16556;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='게으름 피우다 걸리는 일꾼은 투석기에 매달아서 검은 사원으로 날려버리겠다!', `MaleText_loc4`='要是给我看到谁偷懒，我就把他们绑在投石器上，丢到黑暗神殿去！', `MaleText_loc5`='假如讓我看見這裡有任何偷懶的苦工，我將把他們裝進投石機裡，並且把他們射到黑暗神廟去!', `MaleText_loc7`='¡Si veo a algún peón holgazaneando, lo cargaré en una catapulta y lo lanzaré al Templo Oscuro!', `FemaleText_loc1`='게으름 피우다 걸리는 일꾼은 투석기에 매달아서 검은 사원으로 날려버리겠다!', `FemaleText_loc4`='要是给我看到谁偷懒，我就把他们绑在投石器上，丢到黑暗神殿去！', `FemaleText_loc5`='假如讓我看見這裡有任何偷懶的苦工，我將把他們裝進投石機裡，並且把他們射到黑暗神廟去!', `FemaleText_loc7`='¡Si veo a algún peón holgazaneando, lo cargaré en una catapulta y lo lanzaré al Templo Oscuro!' WHERE `ID`=16557;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='속도를 늦추지 마라!', `MaleText_loc4`='快一点！', `MaleText_loc5`='保持這個速度!', `MaleText_loc7`='¡Con buen ritmo!', `FemaleText_loc1`='속도를 늦추지 마라!', `FemaleText_loc4`='快一点！', `FemaleText_loc5`='保持這個速度!', `FemaleText_loc7`='¡Con buen ritmo!' WHERE `ID`=16558;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 저쪽에 묘지가 있으니 쉬고 싶은 일꾼들은 언제든지 말만 해라.', `MaleText_loc4`='无论什么时候，你们这些苦工要是想休息的话，那边的坟地等着你们呢。', `MaleText_loc5`='什麼時候你們這些苦工想要休息一下，墳場就在那裡。', `MaleText_loc7`='Peones, si alguno de ustedes quiere descansar, el cementerio está justo ahí.', `FemaleText_loc1`='바로 저쪽에 묘지가 있으니 쉬고 싶은 일꾼들은 언제든지 말만 해라.', `FemaleText_loc4`='无论什么时候，你们这些苦工要是想休息的话，那边的坟地等着你们呢。', `FemaleText_loc5`='什麼時候你們這些苦工想要休息一下，墳場就在那裡。', `FemaleText_loc7`='Peones, si alguno de ustedes quiere descansar, el cementerio está justo ahí.' WHERE `ID`=16559;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수호자시여, 점술가 언덕에서 녀석들의 동태를 점친 보고서를 가져왔습니다.', `MaleText_loc4`='长官，我是从占星者之台来递交报告的。', `MaleText_loc5`='長官，我是來傳送占卜者階梯的報告。', `MaleText_loc7`='Señor, he venido a entregar mi informe de la Grada del Arúspice.' WHERE `ID`=16560;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들의 동태를 파악하는 일은 불가능합니다.', `MaleText_loc4`='长官，我们不可能从他们的行动中得到什么情报。', `MaleText_loc5`='長官，對於他們的行為根本無法做出任何判斷。', `MaleText_loc7`='Señor, es imposible sacar conclusiones de sus acciones.' WHERE `ID`=16561;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자신들도 뭘 해야 하는지 전혀 모르는 듯, 그들의 움직임은 혼란 그 자체입니다.', `MaleText_loc4`='他们的行动真的很混乱，好像他们自己都不知道要干什么。', `MaleText_loc5`='他們的移動徹底混亂，好像他們自己也不知道他們在幹什麼。', `MaleText_loc7`='Sus movimientos son completamente aleatorios; es como si ellos mismos no supieran lo que están haciendo.' WHERE `ID`=16562;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죄송합니다. 보고할 내용이 더 많으면 좋을 텐데...', `MaleText_loc4`='对不起，长官。我本应能带回来更多的情报。', `MaleText_loc5`='是我不好，長官。我的報告資料不足。', `MaleText_loc7`='Mis disculpas, señor. Ojalá tuviera más información.' WHERE `ID`=16563;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분부대로 따르겠습니다.', `MaleText_loc4`='遵命，长官！', `MaleText_loc5`='聽你差遣，長官。', `MaleText_loc7`='Como ordenes, señor.' WHERE `ID`=16564;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보고하도록...', `MaleText_loc4`='嗯，出去吧，新兵……', `MaleText_loc5`='嗯，拿出來，見習生...', `MaleText_loc7`='Adelante, neófito...' WHERE `ID`=16565;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예상했던 그대로입니다. 적들도 우리가 지켜보고 있다는 사실을 알고 있습니다.', `MaleText_loc4`='和我猜想的完全一样，士兵。他们知道我们在监视。', `MaleText_loc5`='這是與我期望的完全一樣，士兵。他們知道我們仔細在看他們。', `MaleText_loc7`='Es exactamente lo que esperaba, soldado. Saben que los estamos observando.' WHERE `ID`=16566;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리에게 혼란을 주기 위해 의미 없는 행동으로 진짜 의도를 감추고 있는 것입니다.', `MaleText_loc4`='他们用无意义的移动来扰乱我们的注意力，从而掩盖他们的意图。', `MaleText_loc5`='他們用無意義的行為來混淆他們的真正意圖。', `MaleText_loc7`='Enmascaran sus intenciones con movimientos sin sentido para confundirnos.' WHERE `ID`=16567;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간이 지나면 놈들의 속임수가 빤히 눈에 보일 겁니다.', `MaleText_loc4`='总有一天，你可以学会看穿他们的诡计。', `MaleText_loc5`='慢慢的，你將會學到如何看透他們的騙術。', `MaleText_loc7`='Con el tiempo, puede que aprendas a identificar sus engaños.' WHERE `ID`=16568;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그전까지는 당신이 기지에 있는 것만으로도 적들은 긴장의 끈을 놓지 않을 겁니다.', `MaleText_loc4`='在那之前，你要继续假装在监视他们，这会让他们以为自己的计谋得逞了。', `MaleText_loc5`='直到那時，你出現在你的崗哨將使他們保持警覺。', `MaleText_loc7`='Hasta entonces, tu presencia en el puesto los mantendrá alerta.' WHERE `ID`=16569;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 세게! 더 빨리! 더 강하게!', `MaleText_loc4`='更猛！更快！更强！', `MaleText_loc5`='辛苦點!快一點!堅強點!', `MaleText_loc7`='¡Más duro! ¡Más rápido! ¡Más fuerte!' WHERE `ID`=16570;
