UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적의 공격이다! 몸을 숨기시오!', `MaleText_loc4`='我们受到攻击了！快找掩护！', `MaleText_loc5`='我們正遭受攻擊!快找掩護!', `MaleText_loc7`='¡NOS ATACAN! ¡PONEOS A CUBIERTO!' WHERE `ID`=16575;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부숴라, 보병들아! 이 물건을 다시 스톰윈드로 운반할 것이다!', `MaleText_loc4`='拆下它，士兵们！我们要把这东西运回暴风城！', `MaleText_loc5`='士兵，拆毀它!我們要將這東西運回暴風城!', `MaleText_loc7`='¡Destrozadlo, soldados! ¡Devolveremos esta cosa a Ventormenta!' WHERE `ID`=16576;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 이 고철 덩어리를 녹여서 주괴로 무기를 만들 것이다! 지옥절단기를 얼라이언스 식으로 대접하면 불타는 군단이 어떤 반응을 보일지 지켜보도록 하자!', `MaleText_loc4`='我们会融化这个大家伙，用铁锭制造武器！让燃烧军团尝尝由他们的魔能机甲打造的武器的厉害！', `MaleText_loc5`='我們將要融化這塊廢品，並且用鑄鐵製造武器!讓我們看看燃燒軍團有多喜歡嚐嚐惡魔劫奪者配上聯盟風格的味道!', `MaleText_loc7`='Vamos a fundir este trozo de basura y a hacer armas con los lingotes. Veamos si a la Legión le gusta probar un atracador vil al estilo Alianza.' WHERE `ID`=16577;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘했다, 보병! 더러운 호드 짐승들이 우리 앞에 모습을 드러내는 꼴을 그냥 두지 않으려던 참이었다!', `MaleText_loc4`='干得好，士兵们！部落狗们怎能让我们低头！', `MaleText_loc5`='做得好，士兵!我們不會讓部落的骯髒動物使我們難堪!', `MaleText_loc7`='¡Bien hecho, soldados! ¡No íbamos a dejar que esos sucios animales de la Horda nos chulearan!' WHERE `ID`=16578;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 번만 더 이 큰 깡통을 던지기만 해 봐라! 얼라이언스가 어떤 존재인지 보여주고 말 테다!', `MaleText_loc4`='让他们再给我们扔过来这么一个畸形的铁罐头吧！我们要让他们看看联盟的厉害！', `MaleText_loc5`='讓他們在對我們丟一次那些奇怪體型的罐頭!我們會讓他們知道甚麼叫做聯盟!', `MaleText_loc7`='¡Dejad que nos manden otra de sus latas gigantes! ¡Les enseñaremos de qué está hecha la Alianza!' WHERE `ID`=16579;
