UPDATE `locales_broadcast_text` SET `MaleText_loc1`='희극 배우가 인간 여성 흉내를 냅니다.', `MaleText_loc4`='喜剧演员扮成了一个女性人类。', `MaleText_loc5`='喜劇演員扮演一位人類女人。', `MaleText_loc7`='El comediante imita a una humana.' WHERE `ID`=16583;
