UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헝가르펜이 고통스러워 울부짖습니다.', `MaleText_loc4`='霍加尔芬痛苦地咆哮着。', `MaleText_loc5`='飢餓之牙痛苦地大吼。', `MaleText_loc7`='Panthambre ruge de dolor.', `FemaleText_loc1`='헝가르펜이 고통스러워 울부짖습니다.', `FemaleText_loc4`='霍加尔芬痛苦地咆哮着。', `FemaleText_loc5`='飢餓之牙痛苦地大吼。', `FemaleText_loc7`='Panthambre ruge de dolor.' WHERE `ID`=16594;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<나루에게 다가가자 부드러운 빛이 당신의 온몸을 감쌉니다. 나루는 아무 말도 없지만 당신의 마음속에서는 천천히 음악이 울려 퍼지고 안전함이 느껴집니다. 샤트라스에서 당신을 환영하고 있음을 알 수 있습니다.>', `MaleText_loc4`='<当你接近纳鲁的时候，一道柔和的光线充盈了你的全身。和缓的乐声在你的心房回荡，尽管纳鲁一语未发，但一种安全感却油然而生。欢迎你来到沙塔斯城。>', `MaleText_loc5`='<當你接近那些那魯時，慰藉的亮光充滿你。緩慢的音樂鐘琴聲在你的心裡回盪，雖然一言不發，你感覺到安全的保證。歡迎你來到在撒塔斯城。 >', `MaleText_loc7`='<Una suave luz te llena según te vas acercando al naaru. El lento repicar de campanas resuena en tu mente y, aunque nadie dice ni la más mínima palabra, sientes una gran seguridad. $GBienvenido:Bienvenida; a la Ciudad de Shattrath.>' WHERE `ID`=16595;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 이제 모두 라이플을 조준하라...', `MaleText_loc4`='好吧，让我们瞄准……', `MaleText_loc5`='現在，讓我們將那些步槍瞄準在...', `MaleText_loc7`='Muy bien, ahora vamos a ver esos rifles...' WHERE `ID`=16596;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='편대에 볼일이 없으면 그만 가던 길이나 가시오.', `MaleText_loc4`='如果你没有要紧事的话，就给我走开。', `MaleText_loc5`='向前走，除非對艦隊有任何意見。', `MaleText_loc7`='Sigue tu camino; a menos que tengas algo que ver con la flota.' WHERE `ID`=16597;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소형 폭탄과 융단 폭격에 대해 말씀해 주십시오.', `MaleText_loc4`='给我讲讲轻型炸弹和地毯式轰炸吧。', `MaleText_loc5`='告訴我關於輕炸彈和地毯式轟炸的事。', `MaleText_loc7`='Háblame de las bombas ligeras y de sembrar de bombas.', `FemaleText_loc1`='소형 폭탄과 융단 폭격에 대해 말씀해 주십시오.', `FemaleText_loc4`='给我讲讲轻型炸弹和地毯式轰炸吧。', `FemaleText_loc5`='告訴我關於輕炸彈和地毯式轟炸的事。', `FemaleText_loc7`='Háblame de las bombas ligeras y del bombardeo con alfombra.' WHERE `ID`=16598;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='융단 폭격이란 한 지역에 엄청난 수의 폭탄을 투하하는 것으로, 해당 지역을 폭탄으로 뒤덮어 버리는 방법입니다.$B$B폭격기로 여러 개의 소형 폭탄을 투하한 다음 대형 폭탄으로 남은 생물들을 제거하는 방법을 주로 사용합니다.', `MaleText_loc4`='地毯式轰炸是指在一个地区空投大量的炸弹，就像用炸弹在那个区域铺上一层地毯那样。$B$B投弹者一般在一个区域投放多枚轻型?弹，然后用重磅炸弹来清扫剩余的目标。', `MaleText_loc5`='地毯式轟炸是指在一個地區上投下非常多的炸彈，基本上是以炸彈在該地區鋪地毯。$B$B轟炸機通常會先在目標地區上投幾顆輕炸彈，然後在使用重型炸彈將任何仍然可能站著的東西清理掉。', `MaleText_loc7`='El bombardeo de saturación significa soltar un elevado número de bombas en una zona, esencialmente, soltar una lluvia de bombas sobre una zona.$B$BA menudo los bombarderos utilizan varias bombas ligeras en una región y, a continuación, bombas pesadas para acabar con cualquier cosa que siga en pie.' WHERE `ID`=16599;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='융단 폭격은 제 전문입니다. 준비됐습니다!', `MaleText_loc4`='让我去执行地毯式轰炸吧，我已经做好起飞准备了！', `MaleText_loc5`='地毯式轟炸是為我而發明的。我已準備好可以隨時起飛!', `MaleText_loc7`='Lo mío son los bombardeos intensivos. ¡Estoy listo para volar!', `FemaleText_loc1`='융단 폭격은 제 전문입니다. 준비됐습니다!', `FemaleText_loc4`='让我去执行地毯式轰炸吧，我已经做好起飞准备了！', `FemaleText_loc5`='地毯式轟炸是為我而發明的。我已準備好可以隨時起飛!', `FemaleText_loc7`='Los bombardeos con alfombras es lo mío. ¡Estoy lista para volar!' WHERE `ID`=16600;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 것도 말씀해 주십시오.', `MaleText_loc4`='告诉我一些别的事情。', `MaleText_loc5`='告訴我關於其他的事情。', `MaleText_loc7`='Háblame de otra cosa.', `FemaleText_loc1`='다른 것도 말씀해 주십시오.', `FemaleText_loc4`='告诉我一些别的事情。', `FemaleText_loc5`='告訴我關於其他的事情。', `FemaleText_loc7`='Háblame de otra cosa.' WHERE `ID`=16601;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대형 폭탄에 대해 말씀해 주십시오.', `MaleText_loc4`='告诉我关于重磅炸弹的事。', `MaleText_loc5`='告訴我關於重型炸彈的事。', `MaleText_loc7`='Háblame de bombas pesadas.', `FemaleText_loc1`='대형 폭탄에 대해 말씀해 주십시오.', `FemaleText_loc4`='告诉我关于重磅炸弹的事。', `FemaleText_loc5`='告訴我關於重型炸彈的事。', `FemaleText_loc7`='Háblame de bombas pesadas.' WHERE `ID`=16602;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반드시, 꼭 지금 죽여야겠다면 대형 폭탄을 사용하십시오. 대형 폭탄은 폭발 반경이 엄청나게 넓고 훨씬 강력한 피해를 줍니다. 하지만 소형 폭탄에 비해 실을 수 있는 양이 매우 적고, 한번 사용하면 다시 사용할 때까지 오래 기다려야 한다는 단점이 있습니다.', `MaleText_loc4`='当你确定必须消灭某个目标时，重磅炸弹是你的首选。重磅炸弹的爆炸范围更大，能造成的伤害更高。缺点就是你只能带很少的重磅炸弹——要比轻型炸弹少得多，而且每次使用的间隔时间很长。', `MaleText_loc5`='當你絕對、堅決地現在必須殺戮，那麼重型炸彈就是首要的選擇。重型炸彈有更大的影響半徑並且可以造成更多損害。缺點是與輕炸彈相比，你能攜帶的重型炸彈少的多，且在使用之間必須等待較長時間。', `MaleText_loc7`='Cuando sepas total y absolutamente que tienes que matar, utiliza la bomba pesada. Las bombas pesadas tienen un radio mucho mayor y causan mucho más daño. Lo malo es que puedes llevar menos bombas pesadas que ligeras y tienes que esperar más tiempo antes de lanzar la siguiente.' WHERE `ID`=16603;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대형 폭탄이라면 제가 전문입니다. 저를 보내 주십시오!', `MaleText_loc4`='我是使用重磅炸弹的高手。出发吧！', `MaleText_loc5`='我是重型炸彈專家。送我上去!', `MaleText_loc7`='¡Soy el amo de las bombas pesadas! ¡Súbeme!', `FemaleText_loc1`='대형 폭탄이라면 제가 전문입니다. 저를 보내 주십시오!', `FemaleText_loc4`='我是使用重磅炸弹的高手。出发吧！', `FemaleText_loc5`='我是重型炸彈專家。送我上去!', `FemaleText_loc7`='¡Soy la ama de las bombas pesadas! ¡Súbeme!' WHERE `ID`=16604;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으, 이런...', `MaleText_loc4`='哎呀……', `MaleText_loc5`='呃，哎呀...', `MaleText_loc7`='Aaah... Ay.' WHERE `ID`=16605;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분명히 저는 라이플을 제대로 겨냥했는데...', `MaleText_loc4`='……至少我的枪瞄得很准。', `MaleText_loc5`='...至少我們知道我的步槍是正確地瞄準。', `MaleText_loc7`='Al menos ahora sabemos que mi rifle está bien calibrado.' WHERE `ID`=16606;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='병사여...', `MaleText_loc4`='士兵……', `MaleText_loc5`='士兵...', `MaleText_loc7`='Soldado...' WHERE `ID`=16607;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련 시에는 공포탄만 지급된다는 사실을 알고 있지 않나?! 엄살피우지 마라!', `MaleText_loc4`='你一定知道那些射手对钻探一无所知，对吗？', `MaleText_loc5`='你真的知道神射手的射擊練習是使用空包彈，是嗎?', `MaleText_loc7`='Sabías que los tiradores tienen cartuchos de fogueo para los entrenamientos, ¿no?' WHERE `ID`=16608;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이들은 무기 훈련을 할 준비가 전혀 안 되어 있군.', `MaleText_loc4`='很明显，这组还没准备好武器练习。', `MaleText_loc5`='明顯地，這一組尚無法進行武器演習。', `MaleText_loc7`='Está claro que este grupo no está listo para los ejercicios con armas.' WHERE `ID`=16609;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='행군 훈련을 시작할 테니 전원 집합! 이번에는 부상자 없이 행군을 무사히 마칠 수 있을지 보겠다...', `MaleText_loc4`='集合！行军训练！让我们看看是否可以做到零伤亡……', `MaleText_loc5`='集合來進行踏步練習!看看是否我們能夠在沒有任何傷亡的情況下行走...', `MaleText_loc7`='¡Hora de practicar la marcha! Veamos si podemos conseguir caminar sin sufrir bajas...' WHERE `ID`=16610;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한푼만 줍쇼.', `MaleText_loc4`='施舍个铜币吧，$G先生:女士;？', `MaleText_loc5`='賞點錢好嗎，$G先生:女士;?', `MaleText_loc7`='¿Tiene una moneda de cobre, $gseñor:señora;?', `FemaleText_loc1`='한푼만 줍쇼.', `FemaleText_loc4`='施舍个铜币吧，$G先生:女士;？', `FemaleText_loc5`='賞點錢好嗎，$G先生:女士;?', `FemaleText_loc7`='¿Tiene una moneda de cobre, $gseñor:señora;?' WHERE `ID`=16611;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여보시오. 적선 좀 하시려오? 먹여 살릴 자식이 다섯이나 있소이다...', `MaleText_loc4`='嘿，$G先生:女士;，可怜可怜我吧，我还有五个孩子等着吃饭呢！', `MaleText_loc5`='嘿，$G先生:女士;?有錢給我嗎?我有五個孩子要養!', `MaleText_loc7`='¡Eh, $gamigo:amiga;! ¿Tienes algo de dinero? Tengo que alimentar a mis hijos.', `FemaleText_loc1`='여보시오. 적선 좀 하시려오? 먹여 살릴 자식이 다섯이나 있소이다...', `FemaleText_loc4`='嘿，$G先生:女士;，可怜可怜我吧，我还有五个孩子等着吃饭呢！', `FemaleText_loc5`='嘿，$G先生:女士;?有錢給我嗎?我有五個孩子要養!', `FemaleText_loc7`='¡Eh, $gamigo:amiga;! ¿Tienes algo de dinero? Tengo que alimentar a mis hijos.' WHERE `ID`=16612;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제발 우리를 지나치지 마세요...', `MaleText_loc4`='请不要视而不见……', `MaleText_loc5`='請不要忽略我們...', `MaleText_loc7`='Por favor, ten piedad...', `FemaleText_loc1`='제발 우리를 지나치지 마세요...', `FemaleText_loc4`='请不要视而不见……', `FemaleText_loc5`='請不要忽略我們...', `FemaleText_loc7`='Por favor, ten piedad...' WHERE `ID`=16613;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한푼만 적선해줍쇼.', `MaleText_loc4`='请施舍一点铜币吧？', `MaleText_loc5`='有多餘的銅板嗎?', `MaleText_loc7`='¿Alguna pieza de cobre suelta?', `FemaleText_loc1`='한푼만 적선해줍쇼.', `FemaleText_loc4`='请施舍一点铜币吧？', `FemaleText_loc5`='有多餘的銅板嗎?', `FemaleText_loc7`='¿Alguna pieza de cobre suelta?' WHERE `ID`=16614;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저를 심연의 절벽으로 보내 주십시오!', `MaleText_loc4`='送我去地狱岩床！', `MaleText_loc5`='送我到深淵沙洲!', `MaleText_loc7`='¡Mándame a La Plataforma Abisal!', `FemaleText_loc1`='저를 심연의 절벽으로 보내 주십시오!', `FemaleText_loc4`='送我去地狱岩床！', `FemaleText_loc5`='送我到深淵沙洲!', `FemaleText_loc7`='¡Mándame a La Plataforma Abisal!' WHERE `ID`=16615;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사냥꾼들은 이쪽으로! 아제로스에서 싸우다 죽는 것이 무엇을 의미하는지 저 악마들에게 보여주자!', `MaleText_loc4`='猎人们，到我这里来！让我们给这些恶魔们看看，和艾泽拉斯作对是什么下场！', `MaleText_loc5`='獵人，出列!讓我們顯示給這些惡魔看，他所對抗的是什麼，並且讓他們在艾澤拉斯中死去!', `MaleText_loc7`='¡Venid, cazadores! ¡Enseñémosles a estos demonios lo que significa luchar y morir en Azeroth!' WHERE `ID`=16616;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정령들이 우리를 향해 전투의 노래를 부르고 있도다!', `MaleText_loc4`='灵魂们在为我们歌唱！他们在高唱着战斗之歌！', `MaleText_loc5`='精靈們在替我們歌頌!他們唱著戰鬥的歌!', `MaleText_loc7`='¡Lo espíritus cantan para nosotros! ¡Cantan la canción de la batalla!' WHERE `ID`=16617;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형제자매들이여, 쳐부숴라! 오늘 우리의 사냥감은 바로 악마들이다!', `MaleText_loc4`='战斗到底，兄弟姐妹们！今天我们狩猎恶魔！', `MaleText_loc5`='準確地攻擊，兄弟和姐妹們!今天我們的獵物是惡魔們!', `MaleText_loc7`='¡Suerte, hermanos y hermanas! ¡Hoy, nuestra presa son los demonios!' WHERE `ID`=16618;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은빛 여명회의 수호자들이여, 우리와 함께 가자!', `MaleText_loc4`='银色黎明的卫士们！我们和你们并肩作战！', `MaleText_loc5`='銀色黎明的防衛者!我們和你們是同一陣線的!', `MaleText_loc7`='¡Defensores de El Alba Argenta! ¡Estamos con ustedes!' WHERE `ID`=16619;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 한번 말하노니 오늘 우리는 저 불타는 군단에게 누구도 우리 세계를 차지할 수 없다는 사실을 똑똑히 보여줄 것이다.', `MaleText_loc4`='我们会让燃烧军团再次看到，他们休想抢走我们的世界！', `MaleText_loc5`='我們會再一次讓燃燒軍團知道他們奪不走我們的世界!', `MaleText_loc7`='¡Una vez más, demostraremos a esa Legión Ardiente que nuestro mundo no se dejará tomar!' WHERE `ID`=16620;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 악마들은 쓰러질 것이다. 아제로스를 위하여!', `MaleText_loc4`='这些恶魔必将被击败！为了艾泽拉斯而战！', `MaleText_loc5`='這些惡魔會失敗的!為了艾澤拉斯!', `MaleText_loc7`='¡Esos monstruos caerán! ¡Por Azeroth!' WHERE `ID`=16621;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 운명이 오늘 이 시간까지가 전부라고 생각한다면 누구도 쉽게 우리를 꺾을 수 없으리라! 엄호를 부탁한다. 이 악마들은 갈대처럼 꺾이리라!', `MaleText_loc4`='即使我们的命运注定要在今天完结，我们也不能就这么轻易地死去！跟我冲啊！让这些恶魔像割麦子一样倒下！', `MaleText_loc5`='如果今天的死亡是我們的命運，我們也不會如此輕易的死去!記住我的話，這些惡魔將像小麥般的倒下!', `MaleText_loc7`='Si es nuestro destino morir hoy, ¡no nos rendiremos hasta el fin! Oid, ¡esos demonios caerán como el trigo en la siega!' WHERE `ID`=16622;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싸워라! 선조가 우리의 용맹과 힘을 지켜보고 계신다! 오늘 우리 세계를 위하여 저들을 끝까지 추격한다!', `MaleText_loc4`='战斗，战斗！让我们的先祖看看我们所拥有的勇气和力量！今天我们为了先祖的荣耀而战，为了我们的世界而战！', `MaleText_loc5`='繼續戰鬥，並且讓我們的祖先看見我們所擁有的英勇和力量!今天我們的獵殺是為他們，和為我們的世界!', `MaleText_loc7`='¡Luchad y que nuestros ancestros sean testigos de nuestra fuerza y valentía! ¡Hoy, nuestra caza es para ellos y para el mundo!' WHERE `ID`=16623;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비록 그대들의 힘이 다하고 상처에서 피가 나오고 맨땅에 넘어져서 살점이 떨어져 나가도 우리 세계의 정령들을 위해 싸워야 한다! 어떤 악의 세력도 우리를 막을 수 없다.', `MaleText_loc4`='尽管你们的肌肉疲惫不堪，你们的鲜血浸透了这片土地，但是你们是在为了这个世界而战。任何邪恶的力量都挡不住我们！', `MaleText_loc5`='雖然你精力殆盡且血液從傷口流到這浸透的地面，你為你世界的精神而戰鬥。沒有邪惡的力量能反抗我們!', `MaleText_loc7`='Aunque se cansen sus músculos y su sangre se derrame por heridas y cortes, luchen por el espíritu de su mundo. ¡Ninguna fuerza del mal podrá con nosotros!' WHERE `ID`=16624;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아제로스의 병사들이여, 그대들은 이제부터 불타는 성전에 맞서 전투를 벌이게 될 것이오. 빛을 사랑하는 모든 이들의 바람과 희망이 그대들과 함께할 것이오. 우리의 용맹한 동맹과 전우들과 함께 악마들을 물리치고 이 땅을 지켜낼 것이오. 그리하여 많은 세상을 집어삼킬 파괴적인 횡포에 종지부를 찍을 것이오.', `MaleText_loc4`='艾泽拉斯的士兵们，你们正在与邪恶的燃烧军团对抗。所有信仰圣光的人民的希冀和祈祷与你们同在。在我们勇敢的同盟和战友们的帮助下，你们会坚守每一寸土地，击退恶魔的冲击。你们将阻止这些肆虐了很多世界的暴徒！', `MaleText_loc5`='艾澤拉斯的士兵們，你們現在與卑鄙的燃燒軍團戰鬥。以及所有熱愛光明之人的希望和祈禱與你們一同前進。在我們勇敢的盟友和戰友的陪伴下，你將堅守陣地並且抵禦這惡魔的攻擊。你將阻擋狂掃那麼多世界的破壞暴行。', `MaleText_loc7`='Soldados de Azeroth, se enfrentán a la infame Cruzada Ardiente. Junto a ustedes, caminan las esperanzas y las oraciones de nuestro amado pueblo. Junto con nuestros amigos y compañeros de armas, aguantarán y detendrán esta invasión demoniaca. Acabarán con la destrucción y la tiranía que han asolado tantos mundos.' WHERE `ID`=16625;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 기세등등하게 이 냉혹한 임무를 치러야 하며 우리의 목적이 실패로 하지 않도록 해야 하오. 그대들의 동족과 지난 시간 적이었던 자들을 돕고자 한다니 환영이오. 우리의 단결된 힘으로 함께 나아가 오늘이 승리의 날이 되도록 싸우시오!', `MaleText_loc4`='我们要以极大的热情面对这项严酷的任务，也要保证我们不会失败。欢迎一切来帮助你们的伙伴们和你曾经的敌人，让我们齐心协力，胜利是我们的！', `MaleText_loc5`='我們必須以高昂的情緒接起這項嚴峻的任務，並且確信我們的理想將不會遭受失敗。歡迎你們諸兄弟的幫助，以及你們曾經激昂的仇敵 - 讓我們與我們聯合的力量一起全部前進，並且在今天獲得勝利!', `MaleText_loc7`='Cumpliremos con nuestro deber con la moral alta y seguros de que nuestra causa seguirá siempre viva. ¡Aprovechen la ayuda de sus hermanos y de sus antiguos enemigos y avancemos todos juntos, con nuestra fuerzas unidas, hacia la victoria!' WHERE `ID`=16626;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 악마들은 우리를 파멸의 구렁텅이에 빠뜨리고자 하나 필시 우리가 이길 수 없는 상대라 여길 것이오. 저들 자신을 파멸로 몰고 가는 건 우리요. 우리 연합이 카자크와 그의 군대를 처치할 것이오. 그리하려면 그들이 세상을 멸망시키려는 야욕에 못지않게 우리는 몸과 마음을 불사르려는 각오를 다져야 하오.', `MaleText_loc4`='恶魔们应该知道，我们就是他们的末日。虽然他们希望毁灭我们，但最终被毁灭的将是他们。卡扎克和他们的爪牙们将会被我们打败。但是为了这个目标，我们必须以自己的血肉之躯来阻止他们。', `MaleText_loc5`='惡魔們，無疑地我們是他們的復仇者且，雖然他們希望我們的毀滅，但是是我們將引起他們的滅亡。這聯盟將削弱並且戰勝卡札克和他的力量。如過這樣做，我們必須對他們拋出我們的身體和心臟，因為他們至少尋找這個世界的忘卻。', `MaleText_loc7`='Los demonios deberían estar seguros de que somos su peor enemigo y, aunque quieren destruirnos, nosotros seremos su ruina. Esta coalición debilitará y derrotará a Kazzak y sus fuerzas. Para ello, es necesario entregarse en cuerpo y alma a nuestra misión. ¡Ellos solo persiguen la destrucción de este mundo!' WHERE `ID`=16627;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아제로스의 시민들의 힘, 지혜와 끝없는 인내심이 저 너머 세계의 생명체들에게 큰 감명을 주고 있소이다. 피와 공포로 가득 찬 이 날, 난 그대들의 세계가 바로 영웅들로 가득 찬 세계라는 것을 깨닫게 되었소!', `MaleText_loc4`='艾泽拉斯人民的力量、智慧和坚韧孕育了那些超越你的想象的勇士。在这充满血腥和恐惧的岁月里，我预见到你们的世界将涌现无数的英雄！', `MaleText_loc5`='力量，智慧，無止境的艾澤拉斯族人耐力鼓舞那些在你指望以外的人。在今天，充滿血和恐懼的日子，我看見你們的是這世界的英雄!', `MaleText_loc7`='La fuerza, la sabiduría y la resistencia de los pueblos de Azeroth inspira a más de los que te imaginas. ¡En este día, de sangre y terror, veo que el tuyo es un mundo de héroes!' WHERE `ID`=16628;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영겁이 지난 후에 다시 온 저 악마들과 우리의 오랜 적들이 다시 그들의 추잡한 얼굴을 드러내고 있소. 공포는 저들의 치명적인 무기이니 두려움에 몸을 떨어서는 안 되오.', `MaleText_loc4`='恶魔，我们自古以来的敌人，再次露出他们凶残的面貌。但是不要颤栗，因为恐惧是他们的武器，是他们最致命的武器。', `MaleText_loc5`='來自萬古過往的惡魔，我們的老仇敵，再一次顯現他們野獸般的臉孔。但是不要畏縮，因為恐懼是他們眾多武器之一。而且是最致命的武器。', `MaleText_loc7`='Los demonios, nuestros enemigos desde hace eones, muestran de nuevo su monstruoso rostro. Pero no temas; el miedo es una de sus muchas armas. Y una de las más eficaces.' WHERE `ID`=16629;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 새로운 형제와 자매들이여, 힘을 내시오! 우리의 세상을 위하여 저 악마들을 처치하시오. 이곳을 지키시오. 그대들의 친구와 동맹이 그대들과 함께 칼을 높이 들 것이오!', `MaleText_loc4`='力量！我的兄弟姐妹们！把这些馋涎你们这个世界的恶魔赶回去！守住这里，你们的朋友和同盟会来与你们并肩而战！', `MaleText_loc5`='力量!我的新兄弟和姐妹!為了你的世界擊退這些魔鬼。守住這裡，你的朋友和盟友將會到來，並與你一起揮舞他們的劍!', `MaleText_loc7`='¡Fuerza! ¡Mis nuevos hermanos y hermanas! Machaquen a esos demonios por el bien de su mundo. ¡Aguanten y sus amigos y aliados vendrán a ayudarlos con sus espadas!' WHERE `ID`=16630;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋소! 힘을 내시오! 그대들의 친구에게 도움을 주고 우리의 단결된 힘으로 저 악마들을 물리칠 것이니! 굳게 희망을 가지고 무기를 부여잡으시오. 성스러운 빛이 이 어둠을 뚫고 새로운 생명이 움트는 새벽으로 가리라는 믿음을 잃지 마시오!', `MaleText_loc4`='是的！守住！与你的军团并肩作战吧，只要我们同心协力，就能战胜这些恶魔！绝不放弃希望，握紧你的武器战斗吧！相信圣光能穿透这黑暗，明日拂晓的曙光将照耀我们的世界！', `MaleText_loc5`='是!站穩你的腳!幫助你的隊友，只要我們將我們的力量團結在一起我們就能將戰勝這些惡魔!強烈地堅持希望並緊緊握住你的武器，並且相信，聖光將刺穿黑暗並且閃耀於明天的黎明!', `MaleText_loc7`='¡Sí! ¡Para en seco! ¡Ayuda a tus soldados y juntas, nuestras fuerzas combinadas acabarán con esos demonios! ¡Agarren sus esperanzas y sus armas! ¡Pronto la Luz romperá esta oscuridad y brillará hasta que rompa el alba del futuro!' WHERE `ID`=16631;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싸우시오! 온 힘을 다해! 그리고 오늘 저들의 피가 영웅들의 피에 섞여 흐르리라 믿으시오. 최후에도 그대들의 영혼은 내 동족과 이 세상에 승리를 가져왔다는 걸 깨달을 것이니. 우리가 싸우는 저 불타는 군단이 절망에 빠진 우리를 보며 즐거워할 것이니 절망에 굴복해서는 안 되오, 친구여.', `MaleText_loc4`='战斗！战斗！今天我们所流淌的血与英雄的鲜血交融！即使死去，我们的灵魂也会得知你们拯救家园和这个世界的消息。不要向绝望屈服，朋友们，绝望只会令恶魔感到欣喜！', `MaleText_loc5`='繼續戰鬥!繼續戰鬥!要知道，今天流的血是與英雄的血混在一起的。即使死，我們的靈魂也將知道救了你的家族和你的世界的勝利。不要屈服於絕望，朋友，因為我們所面對的惡魔將肯定樂於享受它。', `MaleText_loc7`='¡Luchen! ¡Luchen! Y sepan que la sangre derramada hoy, se mezclará con la sangre de héroes. Incluso en la muerte, nuestros espíritus conocerán la victoria de salvar su raza y su mundo. No desesperen, amigos; eso es lo que los demonios contra los que nos enfrentamos quieren.' WHERE `ID`=16632;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지난 순간 모두 우리가 왜 왔는지의 이유를 다시 증명하는 아제로스의 시민들을 보았소. 내가 그대들과 함께 싸우는 건 근엄함 자긍심이며, 내가 오늘 죽어도 난 친구들과 함께하기 기쁘다오.', `MaleText_loc4`='每一分，每一秒，我都看到艾泽拉斯的人民证明了我们来此的理由。我很骄傲能与你们并肩而战，如果我会在今天死去，那我也要与我的朋友一起战死！', `MaleText_loc5`='隨著每一個流逝的片刻，我看見艾澤拉斯的族人再次證明了我們來的原因。我與你一起作戰是由於莊嚴的驕傲，如果我今天一定要死了，那我將死在朋友之中。', `MaleText_loc7`='Cada instante que pasa, el pueblo de Azeroth me recuerda las razones por las que vinimos. Lucharé junto a ustedes con orgullo. Si muero hoy, moriré entre amigos.' WHERE `ID`=16633;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당당하고 아주 멋진 모습을 보여주었다!', `MaleText_loc4`='你们是走台步还是军事操练啊？', `MaleText_loc5`='那可是非常花俏的跨步，女士們!', `MaleText_loc7`='¡Eso si que son señoritas como a mí me gustan!' WHERE `ID`=16634;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 다시 한번 사격 연습을 해볼까...', `MaleText_loc4`='现在让我们再射一次试试……', `MaleText_loc5`='現在我們再來試試射擊...', `MaleText_loc7`='Venga, vamos a intentarlo otra vez...' WHERE `ID`=16635;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대형을 갖추고 조준!', `MaleText_loc4`='列队，瞄准！', `MaleText_loc5`='進入隊型和拿起那些槍然後瞄準!', `MaleText_loc7`='¡A formar! ¡Y quiero esas armas calibradas!' WHERE `ID`=16636;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제부터 조심하도록. 더 이상 실수해서는 안...', `MaleText_loc4`='小心点，我们不能再犯任何错——', `MaleText_loc5`='小心點，我們現在不希望在有任何錯誤-', `MaleText_loc7`='Con cuidado, no quiero ni un solo error m...' WHERE `ID`=16637;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='재미있는 장난이었다...', `MaleText_loc4`='哦，真可爱……', `MaleText_loc5`='喔，好可愛...', `MaleText_loc7`='Oh, qué lindo...' WHERE `ID`=16638;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 한번만 더 그런 모습이 보이면 하루 종일 행군을 하겠다!', `MaleText_loc4`='要是再让我看到这种事情，我们就行军一整天！', `MaleText_loc5`='如果我再讓我看到那個，我們將會跨步一整天!', `MaleText_loc7`='¡Como vuelva a ver algo así, nos pasaremos el día andando en formación!' WHERE `ID`=16639;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 이제 제군들의 위풍당당한 걸음걸이를 보도록 하지... 행군을 시작하라!', `MaleText_loc4`='其实，我们还想再看看那种奇特的步伐……动起来！', `MaleText_loc5`='實際上，讓我們再多看一些花俏的步伐...走吧!', `MaleText_loc7`='De hecho... ¡Vamos a ver cómo os movéis, sí! ¡Vamos!' WHERE `ID`=16640;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇게 힘찬 모습을 다시 보다니 매우 흡족하군.', `MaleText_loc4`='啧啧，步法真优雅，模特们。', `MaleText_loc5`='再一次，那些是非常好的支撐物，女士們。', `MaleText_loc7`='Lo repito, unas señoritas deliciosas.' WHERE `ID`=16641;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='총 쏘는 법이 배우기 어렵다면 다른 일을 알아보는 게 좋을 거다.', `MaleText_loc4`='要是我们教不会你射击，你至少可以到后面的小酒馆去打工。', `MaleText_loc5`='如果我們不能教你射擊，你將有一項在小酒店裡的職業去依靠。', `MaleText_loc7`='Si no podemos enseñaros a disparar, al menos podréis hacer carrera en la cantina.' WHERE `ID`=16642;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 뭔가? 잘못된 대형으로 전환하지 않았나?!', `MaleText_loc4`='这是什么？你们的方位全都搞错了。', `MaleText_loc5`='這是什麼?你已經移成一個錯誤的隊形!', `MaleText_loc7`='¿Qué hacéis? ¡Estáis formando mal!' WHERE `ID`=16643;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 나간다면 공격을 미처 해보기도 전에 엉터리 대형만 만들다가 끝날 것이다.', `MaleText_loc4`='你们在进攻前只能使用交错阵——', `MaleText_loc5`='你只能在攻擊前使用錯開的隊形-', `MaleText_loc7`='Se supone que la formación escalonada viene justo antes del ata...' WHERE `ID`=16644;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만 좀 해! 지금 이곳은 전쟁 중이다!', `MaleText_loc4`='这里够乱了！我们还要不要去打仗了？', `MaleText_loc5`='鬧夠了!這裡要打仗了!', `MaleText_loc7`='¡Basta de perder el tiempo! ¡Ahí hay una guerra!' WHERE `ID`=16645;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 점점 강해집니다.', `MaleText_loc4`='%s变得更强大了。', `MaleText_loc5`='%s開始變的強壯。', `MaleText_loc7`='%s comienza a hacerse más fuerte.' WHERE `ID`=16646;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s의 표면에서 거품이 일어납니다.', `MaleText_loc4`='%s的表面开始冒泡。', `MaleText_loc5`='%s的表面開始冒泡。', `MaleText_loc7`='La superficie de %s comienza a bullir.' WHERE `ID`=16647;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘은 정말 멋진 관객들만 모이셨군요. 저기 드워프 여성께서는 면도도 하셨네요.', `MaleText_loc4`='这群人看上去不错。连女矮人都刮了胡子。', `MaleText_loc5`='多麼好看的人群。矮人的婦女甚至會刮鬍鬚。', `MaleText_loc7`='Qué buen aspecto tiene esta gente. Las enanas incluso se han afeitado.' WHERE `ID`=16648;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방금 아이언포지에서 날아왔죠. 그놈 날개가 엄청 뻐근할 겁니다!', `MaleText_loc4`='我刚从铁炉堡飞过来，小子！我坐骑的翅膀都快累断了！', `MaleText_loc5`='我剛剛從鐵爐堡飛過來和，男孩!，我坐騎的翅膀已經疲倦了!', `MaleText_loc7`='Acabo de llegar de Forjaz volando. ¡Señor! Mi montura tiene las alas cansadísimas.' WHERE `ID`=16649;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일로 왔는지 알고 있다. 그 일에 영원히 마침표를 찍어주지!', `MaleText_loc4`='我知道你们要干什么，而我将永远打消你们的念头！', `MaleText_loc5`='我知道你想要做些什麼，而我想要結束它，永遠!', `MaleText_loc7`='Sé lo que planean y voy a ponerle fin, ¡definitivamente!' WHERE `ID`=16650;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지난주에 황금골에 갔다 왔습니다. 여러분은 거기 가본 적 있으세요?', `MaleText_loc4`='我上周在闪金镇。你去过那里吗？', `MaleText_loc5`='上個禮拜我在閃金鎮。你有去那裡嗎?', `MaleText_loc7`='La semana pasada estuve en Villadorada. ¿Has estado allí alguna vez?' WHERE `ID`=16651;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조그마한 마을에서 한 꼬마에게 지도를 그려달라고 부탁했습니다. 그랬더니 데피아즈단 현상 수배 전단 뒷면에 지도를 그리지 뭡니까...', `MaleText_loc4`='那镇子真小，我让一个小孩给我画张地图。结果他画在了迪菲亚通缉令的背面……', `MaleText_loc5`='那個鎮是如此的小，以至於當我要求一個孩子幫我畫一張地圖時，他把它畫在一張迪菲亞通緝犯海報的背面...', `MaleText_loc7`='Ese pueblo es tan pequeño que le pedí a un niño que me dibujara el mapa. Lo dibujó en la parte trasera de un cartel de Se busca de los Defias...' WHERE `ID`=16652;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그것도 아주 정확한 비율로요!', `MaleText_loc4`='还是一比一的！', `MaleText_loc5`='按比例!!', `MaleText_loc7`='¡¡A escala!!' WHERE `ID`=16653;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 옆에 스카이리는 정말 아릅답지 않나? 우리 사령관님의 믿음직한 그리핀이지. 쿠르드란께서는 성채에서 접견 중이시지. 쿠르드란께서 바쁘실 때는 내가 스카이리를 돌보고 있지. 스카이리는 강하면서 거친 정말 멋진 생물이야. 스카이리는 쿠르드란 님을 위해서라면 제 목숨이라도 바칠 걸세. 이렇게 충성심이 강한 녀석은 처음 본단 말이야.

스카이리를 돌보는 것은 명예로운 일이라네. 암, 그렇고말고.', `MaleText_loc4`='她真漂亮，不是吗？斯卡雷……她是我们的指挥官库德兰忠实的狮鹫。库德兰常常在蛮锤要塞中处理事务，他公务繁忙时我就负责照料斯卡雷。她的羽毛真美，作战时却尽显出勇猛的一面。她愿意为了库德兰而死，真的。你肯定没有见过比她更忠诚的宝贝儿。

照料她真是我的荣幸啊。', `MaleText_loc5`='她是個美人，不是嗎?史蓋瑞...我們指揮官的忠實獅鷲。庫德蘭他自己，他在堡壘裡有他的觀眾。當他忙碌的時候，我會照顧我們這裡的史蓋瑞。華麗的動物，她是;生來強大而兇猛。她會為庫德蘭而死。一個你們從未見過的忠實靈魂。

照顧他是一種榮譽，是的。', `MaleText_loc7`='Es una preciosidad, ¿a que sí? Cielo''ree, el fiel grifo de nuestro comandante. Kurdran ha desaparecido, ¿sabes? No está muerto, no; eso no lo sabremos hasta que encontremos el cuerpo. Y todavía entonces, habrá quienes no lo crean. Mientras tanto, Cielo''ree está con nosotros, esperando a que vuelva.' WHERE `ID`=16654;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황금골의 여관은 멋진 호숫가 전망을 자랑한다고 선전하더군요...', `MaleText_loc4`='闪金镇旅店为他们的湖畔景观房做广告……', `MaleText_loc5`='閃金鎮的旅店以湖光景色為廣告...', `MaleText_loc7`='La posada de Villadorada se anuncia con sus vistas del lago...' WHERE `ID`=16655;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런데 창문 너머로 멀록이 수영하는 모습만 보이더군요.', `MaleText_loc4`='结果我看到有个鱼人在我的窗边游泳。', `MaleText_loc5`='我看到一個魚人從我的窗戶旁游過去。', `MaleText_loc7`='Vi a un múrloc pasar nadando por mi ventana.' WHERE `ID`=16656;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='등불의 심지를 갈려면 코볼트가 몇 명이나 있어야 할까요?', `MaleText_loc4`='多少狗头人换一根蜡烛？', `MaleText_loc5`='換一根燈籠燈芯需要多少狗頭人?', `MaleText_loc7`='¿Cuántos kóbolds hacen falta para cambiar la mecha de un farol?' WHERE `ID`=16657;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만, 양초는 절대 못 가져가겠죠!', `MaleText_loc4`='不许抢走我的蜡烛！', `MaleText_loc5`='你不可以帶蠟燭!', `MaleText_loc7`='¡Tú no llevarte vela!' WHERE `ID`=16658;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피를 볼 시간이군!', `MaleText_loc4`='流血吧！', `MaleText_loc5`='殺戮的時間到了!', `MaleText_loc7`='¡Hora de sangrar!' WHERE `ID`=16659;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도망가라! 이 겁쟁이들아!', `MaleText_loc4`='跑吧，你们这些懦夫！', `MaleText_loc5`='跑，你這可惡的懦夫!', `MaleText_loc7`='¡Huyan, malditos cobardes!' WHERE `ID`=16660;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여러분께 주정뱅이 라리크를 소개합니다. 그의 어머니는 너무 뚱뚱해서 칼날 산맥으로 날아갈 때 요금을 두 배는 더 내야 한답니다!', `MaleText_loc4`='嘿，那是醉鬼拉里克……他的妈妈太胖了，当她飞去刀锋山的时候，他们按磅数收她的费用！', `MaleText_loc5`='喂，是『酒鬼』拉利克...他的媽媽是如此肥胖，以致於當她飛往劍刃山脈時，他們是向她以磅計費!', `MaleText_loc7`='Eh, es Raliq el Borracho... Su madre es tan, tan gorda, que cuando vuela a Filospada le cobran por kilos.' WHERE `ID`=16661;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쓸데없는 간섭은 그만둬라.', `MaleText_loc4`='看你还怎么多管闲事！', `MaleText_loc5`='別再亂管閒事!', `MaleText_loc7`='¡Esta es la ultima vez que entrometes!' WHERE `ID`=16662;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 이상 방해하지 마라!', `MaleText_loc4`='你别想插手这件事！', `MaleText_loc5`='你無法干擾了!', `MaleText_loc7`='¡No interferirás!' WHERE `ID`=16663;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스랄을... 풀어줘서는... 안 돼.', `MaleText_loc4`='不能……让萨尔……逃走。', `MaleText_loc5`='索爾...一定不能...自由。', `MaleText_loc7`='Thrall... no debe ser... libre.' WHERE `ID`=16664;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 누가 있는지 보십시오. 우리 친구, 주정뱅이 라리크입니다. 그의 어머니는 너무 뚱뚱해서 용 아가리에도 못 들어가지요.', `MaleText_loc4`='看这是谁啊，醉鬼拉里克……他的妈妈太胖了，连龙都不要吃她……', `MaleText_loc5`='看看誰在這裡，是『酒鬼』拉利克...他的媽媽是如此肥胖，以致於連龍都不想吃她...', `MaleText_loc7`='Mira quién está aquí. Es Raliq el Borracho... Su madre está tan gorda que no se la comen ni los dragones.' WHERE `ID`=16665;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들 모자는 남은 음식을 보관할 데가 없어서 모조리 뱃속에다 넣지요!', `MaleText_loc4`='因为他们不知道该把剩下的肉放在哪里！', `MaleText_loc5`='他們不知道該把剩餘物儲存在哪!', `MaleText_loc7`='¡No saben dónde almacenar las sobras!' WHERE `ID`=16666;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하하! 주정뱅이 라리크를 좀 보세요... 그의 어머니는 너무 뚱뚱해서 오우거 신문의 표지를 장식한다고 해도 몸이 다 나오지도 못할 거예요...', `MaleText_loc4`='嘿！嘿！嘿！这不是醉鬼拉里克吗……他妈妈太胖了，她不仅上了《今日食人魔》的封面……', `MaleText_loc5`='喂!喂!喂!這不是『酒鬼』拉利克嗎...他的媽媽是如此肥胖，以致於她今天不僅僅上了《今日巨魔》的封面...', `MaleText_loc7`='¡Eh! ¡Eh! ¡Eh! Es Raliq el Borracho... Su madre está tan gorda que no cabía en la cubierta de OgroInterviú...' WHERE `ID`=16667;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아마 뒷면 표지까지 다 쓴다고 해도 모자랄 겁니다!', `MaleText_loc4`='还上了封底！', `MaleText_loc5`='她還做了封底!', `MaleText_loc7`='¡También hizo la cubierta posterior!' WHERE `ID`=16668;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한때 노움은 친절하고 예의 바른 종족이었죠...', `MaleText_loc4`='侏儒们曾经是非常值得尊敬的种族……', `MaleText_loc5`='地精以前是個很好，很尊重人的種族...', `MaleText_loc7`='Los gnomos solían ser amables y respetuosos...' WHERE `ID`=16669;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='며칠 전 어떤 친구가 실성이라도 한 듯, 거리를 걸어가면서 "당신도 한번 노움을 알면 다시는 고향으로 돌아오지 못한다!"라고 외치는 걸 봤어요.', `MaleText_loc4`='有一天我看到有人沿着大街边走边叫，“一旦你变成侏儒，你就只能租房子住了！”', `MaleText_loc5`='前些日子我看見有一個人走下街道大叫，「一旦你去地精那裡，你就回不了家」!', `MaleText_loc7`='El otro día oí a alguien por la calle decir:''¡Quisiera se gnomo, pero no sé cómo!''' WHERE `ID`=16670;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여러분도 고블린을 믿지 않으시지요...', `MaleText_loc4`='通常你不能相信地精……', `MaleText_loc5`='從以前以來你就不能相信哥布林...', `MaleText_loc7`='Antes no te podías fiar de un goblin...' WHERE `ID`=16671;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 뭐라고 반박하겠습니까? 고블린과 거래를 트기 전에는 지갑에 쇠 자물쇠부터 다는 게 상책인데요.', `MaleText_loc4`='我在开玩笑吗？如果你和地精们做生意，你最好给钱包装上个铁套子。', `MaleText_loc5`='我在跟誰開玩笑?如果你與哥布林進行交易，你最好在你的零錢包上鍍層鐵。', `MaleText_loc7`='A quién quiero engañar... Si haces tratos con goblins, será mejor que tengas coraza de hierro en tu monedero.' WHERE `ID`=16672;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 노예다! 그것이 너의 영원한 운명이다!', `MaleText_loc4`='你是个奴隶！你永远都是个奴隶！', `MaleText_loc5`='你是一個奴隸!永遠都不會改變!', `MaleText_loc7`='¡Esclavo! ¡Es lo que siempre serás!' WHERE `ID`=16673;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='블랙무어가 대체 너에게 무얼 기대하는지 모르겠군. 돈으로 살 수 있는 한낱 노예 따위에 불과한데 말이야.', `MaleText_loc4`='我不知道布莱克摩尔为什么看中你，在我看来你只不过是个愚蠢的兽人！', `MaleText_loc5`='我不知道布拉克摩爾在你身上看見什麼。據我的看法你只是另一個愚昧野蠻的人!', `MaleText_loc7`='No sé lo que Lodonegro ve en ti. ¡Por mi dinero no eres más que otro salvaje ignorante!' WHERE `ID`=16674;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스랄은 절대 자유의 몸이 될 수 없어!', `MaleText_loc4`='萨尔不可能逃脱！', `MaleText_loc5`='索爾永遠都不會自由!', `MaleText_loc7`='¡Thrall nunca serás libre!' WHERE `ID`=16675;
