UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한번 다시 생각해 보자고요. 저만 못생겼나요? 아니면 호드가 다 그런가요?', `MaleText_loc4`='只有我这么觉得吗？部落简直是我们可以找到的最难看的敌人？', `MaleText_loc5`='只有我發覺，還是部落的人員是我們可發現的敵人裡面最醜陋的?', `MaleText_loc7`='¿Soy solo yo, o la Horda está a punto de luchar contra el enemigo más feo que podíamos haber encontrado?' WHERE `ID`=16678;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여러분께서 자리를 뜨지 않은 것만 봐도 블러드 엘프들이 얼마나 매력적인지 알 수 있죠. 그 말의 요지가 바로 그거였습니다. 전달하는 과정에서 약간 오해가 있었을 뿐이죠.', `MaleText_loc4`='你们不要感到失落，我的意思是血精灵是多么迷人啊。都是翻译的错。', `MaleText_loc5`='為了不讓你們感到被遺忘，我所說的全部只是血精靈有多麼吸引人。可能在翻譯過程中失去某些意思。', `MaleText_loc7`='Chicos, para que no os sintáis marginados, lo que he dicho es que los elfos de sangre son muy atractivos. Se pierde algo de sentido con la traducción.' WHERE `ID`=16679;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니 도대체 상황이 얼마나 절박하기에 가축을 동료로 받아들인답니까?', `MaleText_loc4`='只能招募你的家畜作为同盟是多么令人失望啊！', `MaleText_loc5`='你必須為盟友補充你的家畜有多情急?', `MaleText_loc7`='¡Qué desesperado tienes que sentirte por encontrar aliados para reclutar a tu ganado!' WHERE `ID`=16680;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저도 개를 한 마리 기르고 있지만 검을 주지는 않아요.', `MaleText_loc4`='我有一条狗，但我不会把剑给它。', `MaleText_loc5`='我有一隻狗，但我沒給他一把劍。', `MaleText_loc7`='Tengo un perro, pero no voy a darle una espada.' WHERE `ID`=16681;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러니까 블러드 엘프들은 자신들이 한 발자국만 앞으로 나가면 이 세계를 지배하게 될 거로 생각한다는 거군요...', `MaleText_loc4`='那些血精灵认为他们离控制这个世界只有一步之遥……', `MaleText_loc5`='所以血精靈認為他們只差一步就能摧毀世界...', `MaleText_loc7`='Así que los elfos de sangre creen que están a punto de dominar el mundo...' WHERE `ID`=16682;
