UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나즈자타의 심연을 위해!', `MaleText_loc4`='以纳沙塔的名义！', `MaleText_loc5`='以納沙塔爾深淵之名!', `MaleText_loc7`='¡Por las profundidades de Nazjatar!', `FemaleText_loc1`='나즈자타의 심연을 위해!', `FemaleText_loc4`='以纳沙塔的名义！', `FemaleText_loc5`='以納沙塔爾深淵之名!', `FemaleText_loc7`='¡Por las profundidades de Nazjatar!' WHERE `ID`=16711;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 피는 맹독과 같다!', `MaleText_loc4`='我的血剧毒无比！', `MaleText_loc5`='我的血就像毒液一樣!', `MaleText_loc7`='¡Mi sangre es tósigo!', `FemaleText_loc1`='내 피는 맹독과 같다!', `FemaleText_loc4`='我的血剧毒无比！', `FemaleText_loc5`='我的血就像毒液一樣!', `FemaleText_loc7`='¡Mi sangre es tósigo!' WHERE `ID`=16712;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으... 아파... 제 동료는 어디 있습니까? 다시 싸움터로 돌아가야 합니다...', `MaleText_loc4`='啊……好疼……我的朋友们在哪里？我要回去战斗……', `MaleText_loc5`='啊...好痛...我的朋友在哪裡?我必須回去作戰...', `MaleText_loc7`='Ay... Duele... ¿Dónde están mis amigos? Tengo que volver a la batalla...', `FemaleText_loc1`='으... 아파... 제 동료는 어디 있습니까? 다시 싸움터로 돌아가야 합니다...', `FemaleText_loc4`='啊……好疼……我的朋友们在哪里？我要回去战斗……', `FemaleText_loc5`='啊...好痛...我的朋友在哪裡?我必須回去作戰...', `FemaleText_loc7`='Ay... Duele... ¿Dónde están mis amigos? Tengo que volver a la batalla...' WHERE `ID`=16713;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 지금 어디로 가고 있다고 생각하는 것이오? 당신은 심각한 부상을 입었소이다. 어서 천막으로 돌아가서 간호사에게 치료를 받으시오!', `MaleText_loc4`='你觉得你该去哪里，士兵？看看你受的这些致命伤。现在回到你的帐篷里去，让护士为你治疗！', `MaleText_loc5`='你認為你要到那裡去，士兵?那些是你已經到那裡的致命傷口。現在，回到那座帳篷並讓護士治療你!', `MaleText_loc7`='¿Adónde crees que vas, soldado? Tienes unas heridas muy graves. Vuelve a la tienda y deja que la enfermera te cure.', `FemaleText_loc1`='당신이 지금 어디로 가고 있다고 생각하는 것이오? 당신은 심각한 부상을 입었소이다. 어서 천막으로 돌아가서 간호사에게 치료를 받으시오!', `FemaleText_loc4`='你觉得你该去哪里，士兵？看看你受的这些致命伤。现在回到你的帐篷里去，让护士为你治疗！', `FemaleText_loc5`='你認為你要到那裡去，士兵?那些是你已經到那裡的致命傷口。現在，回到那座帳篷並讓護士治療你!', `FemaleText_loc7`='¿Adónde crees que vas, soldado? Tienes unas heridas muy graves. Vuelve a la tienda y deja que la enfermera te cure.' WHERE `ID`=16714;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대장님! 제가 아제로스를 위해 싸우러 가지 않을 거라면 뭐 하러 이 군대에 들어온 겁니까? 저는 전투에 참여하려고 입대한 것이니 그 일을 하고 싶습니다.', `MaleText_loc4`='长官！要是我不去为艾泽拉斯而战，那么为什么我要加入这支军队呢？我应征就是为了能为军队效力，我要坚持到底！', `MaleText_loc5`='先生!如果我不出去並且為艾澤拉斯而戰鬥，那麼我為什麼會在這軍隊裡?我是應徵入伍的，而且我打算貫徹始終。', `MaleText_loc7`='¡Señor! Si no salimos ahí fuera y luchamos por Azeroth, ¿entonces qué pinto yo en este ejército? Me enlisté para hacer un trabajo, y pretendo hacerlo.', `FemaleText_loc1`='대장님! 제가 아제로스를 위해 싸우러 가지 않을 거라면 뭐 하러 이 군대에 들어온 겁니까? 저는 전투에 참여하려고 입대한 것이니 그 일을 하고 싶습니다.', `FemaleText_loc4`='长官！要是我不去为艾泽拉斯而战，那么为什么我要加入这支军队呢？我应征就是为了能为军队效力，我要坚持到底！', `FemaleText_loc5`='先生!如果我不離開那邊並且為艾澤拉斯戰鬥，那麼我為什麼在這支軍隊?我應徵一個工作，而我打算貫徹它。', `FemaleText_loc7`='¡Señor! Si no salimos ahí fuera y luchamos por Azeroth, ¿entonces qué pinto yo en este ejército? Me enlisté para hacer un trabajo, y pretendo hacerlo.' WHERE `ID`=16715;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='테로크의 이름으로!', `MaleText_loc4`='以泰罗克之名！', `MaleText_loc5`='以泰洛克之名!', `MaleText_loc7`='¡En el nombre de Terokk!', `FemaleText_loc1`='테로크의 이름으로!', `FemaleText_loc4`='以泰罗克之名！', `FemaleText_loc5`='以泰洛克之名!', `FemaleText_loc7`='¡En el nombre de Terokk!' WHERE `ID`=16716;
