UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 소용돌이로 인해 우린 뭘 깨달은 것이냐!', `MaleText_loc4`='瞧瞧虚空之风给我们带来了什么？', `MaleText_loc5`='靈風給我們帶來了什麼?', `MaleText_loc7`='¿Qué nos han traído los vientos abisales?' WHERE `ID`=16721;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이방인이여, 고향에 돌아가기엔 너무 멀리 왔구나!', `MaleText_loc4`='你走了很远，陌生人。', `MaleText_loc5`='你離家很遠，陌生人。', `MaleText_loc7`='Estás lejos de tu casa, $gextranjero:extranjera;.' WHERE `ID`=16722;
