UPDATE `locales_broadcast_text` SET `MaleText_loc1`='속삭이는 소리가 들리면 죽을 줄 알아라...', `MaleText_loc4`='如果你听到那低吟，你就离死不远了……', `MaleText_loc5`='如果讓我聽到悄悄話，你就等死吧...', `MaleText_loc7`='Si oyes el susurro, es que estás muriendo...' WHERE `ID`=16724;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연설 잘 들었습니다, 알모넨 님. 동지들에게 큰 도움이 될 겁니다.', `MaleText_loc4`='感谢你的演讲，奥蒙纳。他们会铭记在心的。', `MaleText_loc5`='謝謝你和那些人說話，艾蒙南。他們會更能面對。', `MaleText_loc7`='Gracias por hablar con los hombres, Almonen. Serán mejores gracias a lo que les has dicho.' WHERE `ID`=16725;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영광입니다, 알모넨 대수도자님.', `MaleText_loc4`='这是我的荣幸，资深学者。', `MaleText_loc5`='這是我的榮幸，大隱士艾蒙南。', `MaleText_loc7`='Será un honor, gran anacoreta.' WHERE `ID`=16726;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부사령관님, 일꾼들이 오그리마에서 온 물자를 정리하고 정비하기 위해 밤낮으로 열심히 일하고 있습니다. 아직 할 일이 많이 남아 있지만 예정보다 한 시간 일찍 진행되고 있습니다.', `MaleText_loc4`='中将，苦工们日以继夜地整理从奥格瑞玛运来的补给品。还有很多没有完成，不过我们已经赶超原计划一小时了。', `MaleText_loc5`='中將。苦工們日夜工作去組織和準備從奧格瑪那裡來的補給品。雖然仍然有非常多的事要做，但是我們的進度已提前一個小時。', `MaleText_loc7`='Teniente general. Los peones están trabajando día y noche para organizar los suministros de Orgrimmar. Todavía queda mucho por hacer, pero vamos una hora por delante del plan.' WHERE `ID`=16727;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훌륭하군. 계속 분발해 주게, 보급장교. 이만 가 보게.', `MaleText_loc4`='太棒了。继续保持，供给官。解散。', `MaleText_loc5`='非常好。繼續保持，物資商人。退下吧。', `MaleText_loc7`='Excelente. Continúa así, gran avituallador. Puedes marcharte.' WHERE `ID`=16728;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 마법을 사용하면 스랄이 죽기 전으로 시간을 되돌릴 수 있답니다. 하지만 제가 시간을 조절하는 데는 한계가 있다는 걸 알아 두십시오.', `MaleText_loc4`='我的魔法力量可以让时间回到萨尔死亡之前，但是小心点，我控制时间的力量是有限的。', `MaleText_loc5`='我的魔法力量能將時間回轉到索爾死亡之前，但是小心。我操控時間的能力有限。', `MaleText_loc7`='Mi poder mágico puede volver el tiempo atrás, hasta antes de la muerte de Thrall, pero ten cuidado. Mi poder para manipular el tiempo es limitado.' WHERE `ID`=16729;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러니 제 앞에서 비켜 주십시오. 불타는 군단을 황천으로 돌려보낼 시간입니다!!', `MaleText_loc4`='给我走开，该是把燃烧军团送回虚空去的时候了！！', `MaleText_loc5`='現在不要擋我的路，是時候把燃燒軍團送回虛空了!!', `MaleText_loc7`='Ahora vete de mi vista. ¡Es hora de devolver la Legión Ardiente a la nada!', `FemaleText_loc1`='그러니 제 앞에서 비켜 주십시오. 불타는 군단을 황천으로 돌려보낼 시간입니다!!', `FemaleText_loc4`='给我走开，该是把燃烧军团送回虚空去的时候了！！', `FemaleText_loc5`='現在不要擋我的路，是時候把燃燒軍團送回虛空了!!', `FemaleText_loc7`='Ahora vete de mi vista. ¡Es hora de devolver la Legión Ardiente de vuelta a la nada!' WHERE `ID`=16730;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 시간의 흐름을 다시 한 번만 되돌릴 수가 있습니다. 또다시 스랄이 죽게 된다면 모든 게 끝장이니 명심하십시오.', `MaleText_loc4`='我再次将时间逆转了。如果你不能阻止萨尔的死，那么一切就全完了。', `MaleText_loc5`='我已經再一次將時間的流動延後。如果你不能阻止索爾的死亡，那全部都失敗了。', `MaleText_loc7`='He invertido el flujo del tiempo una vez más. Si no salvas a Thrall esta vez, todo estará perdido.' WHERE `ID`=16731;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동지들이여... 실망시켜서 미안합니다...', `MaleText_loc4`='朋友们……我辜负了你们……', `MaleText_loc5`='朋友...我讓你失望了...', `MaleText_loc7`='Amigos... Os he fallado...', `FemaleText_loc1`='동지들이여... 실망시켜서 미안합니다...', `FemaleText_loc4`='朋友们……我辜负了你们……', `FemaleText_loc5`='朋友...我讓你失望了...', `FemaleText_loc7`='Amigos... Os he fallado...' WHERE `ID`=16732;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동지여, 감사할 필요 없네. 그대의 병사들 앞에서 연설한다는 사실이 오히려 영광일세.', `MaleText_loc4`='不必言谢，我的朋友。我想我可以随意与你手下的新兵交谈吧。', `MaleText_loc5`='你的感謝是不必要的，我的朋友。我認為那是一種對你的新兵講話的特權。', `MaleText_loc7`='No es necesario que me des las gracias. Considero que es un privilegio hablar con tus reclutas.' WHERE `ID`=16733;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 이곳을 찾는 이들에게 아달이 일깨워준 진실을 전하겠네.', `MaleText_loc4`='阿达尔所展露的真理让我豁然开朗，今天我要将这真理传授给我的门徒。', `MaleText_loc5`='阿達歐已經將我的心靈打開去認知我今天是去告知我們的保護人。', `MaleText_loc7`='A''dal ha abierto mi mente a verdades que compartiré hoy con nuestros parroquianos.' WHERE `ID`=16734;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 이곳 빛의 정원에 모인 여러분을 환영합니다.', `MaleText_loc4`='朋友，我很荣幸来迎接你今日驾临神殿。', `MaleText_loc5`='朋友，今天能歡迎你來到神廟是我至高的榮幸。', `MaleText_loc7`='Amigos, me complace inmensamente daros la bienvenida al templo.' WHERE `ID`=16735;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 감동적일 데가... 진정한 전사의 기개로다... 이 군대에는 자네 같은 병사들이 더 많아야 해. 이제 가서 저들을 끝장내 버리시오!', `MaleText_loc4`='这就是士兵的精神……我真希望军队里有更多的士兵像你这样。现在拿上你的武器，送他们去地狱吧！！', `MaleText_loc5`='嗤之以鼻地說...就是要那種氣概，士兵.. 我只希望軍隊裡有更多的士兵像你一樣。現在到戰場上並且懲罰他們!!', `MaleText_loc7`='Sniff... Ese es el espíritu, soldado... Ojalá tuviese más soldados como tú en este ejército. ¡¡Ahora sal ahí fuera y enséñales lo que es el infierno!!', `FemaleText_loc1`='이렇게 감동적일 데가... 진정한 전사의 기개로다... 이 군대에는 자네 같은 병사들이 더 많아야 해. 이제 가서 저들을 끝장내 버리시오!', `FemaleText_loc4`='这就是士兵的精神……我真希望军队里有更多的士兵像你这样。现在拿上你的武器，送他们去地狱吧！！', `FemaleText_loc5`='嗤之以鼻地說...就是要那種氣概，士兵.. 我只希望軍隊裡有更多的士兵像你一樣。現在到戰場上並且懲罰他們!!', `FemaleText_loc7`='Sniff... Ese es el espíritu, soldado... Ojalá tuviese más soldados como tú en este ejército. ¡¡Ahora sal ahí fuera y enséñales lo que es el infierno!!' WHERE `ID`=16736;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아아안 돼!!', `MaleText_loc4`='不！！', `MaleText_loc5`='不!!', `MaleText_loc7`='¡Noooooooooooo!', `FemaleText_loc1`='아아아안 돼!!', `FemaleText_loc4`='不！！', `FemaleText_loc5`='不!!', `FemaleText_loc7`='¡Noooooooooooo!' WHERE `ID`=16737;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니오... 우리가 당신을 실망시켰소... 바로 우리가 말이오...', `MaleText_loc4`='不，我的朋友……我们辜负了你……我们辜负了你。', `MaleText_loc5`='不我的朋友...我們讓你失望了...我們讓你失望了。', `MaleText_loc7`='No, amigo mío... Nosotros te hemos fallado. Te hemos fallado.', `FemaleText_loc1`='아니오... 우리가 당신을 실망시켰소... 바로 우리가 말이오...', `FemaleText_loc4`='不，我的朋友……我们辜负了你……我们辜负了你。', `FemaleText_loc5`='不我的朋友...我們讓你失望了...我們讓你失望了。', `FemaleText_loc7`='No, amigo mío... Nosotros te hemos fallado. Te hemos fallado.' WHERE `ID`=16738;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시는 이런 일이 없을 것이오!! 앞으로 부상당한 병사가 전방으로 돌아가겠다고 하면 절대 용납하지 않겠소이다. 이제부터요.', `MaleText_loc4`='休想！！下次要是再有受伤的士兵想回到前线，我会坚决反对的。就从现在开始！', `MaleText_loc5`='決不要再犯!!下一次傷兵們想要返回前線，我一定會果斷行動。這一次我是認真的。', `MaleText_loc7`='¡¡NUNCA MÁS!! La próxima vez que un soldado herido quiera volver a las primeras líneas, me voy a negar. Y esta vez lo digo en serio.', `FemaleText_loc1`='다시는 이런 일이 없을 것이오!! 앞으로 부상당한 병사가 전방으로 돌아가겠다고 하면 절대 용납하지 않겠소이다. 이제부터요.', `FemaleText_loc4`='休想！！下次要是再有受伤的士兵想回到前线，我会坚决反对的。就从现在开始！', `FemaleText_loc5`='決不要再犯!!下一次傷兵們想要返回前線，我一定會果斷行動。這一次我是認真的。', `FemaleText_loc7`='¡¡NUNCA MÁS!! La próxima vez que un soldado herido quiera volver a las primeras líneas, me voy a negar. Y esta vez lo digo en serio.' WHERE `ID`=16739;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아달은 성스러운 빛의 충실한 종인 저에게 수많은 계시를 내려주었습니다.', `MaleText_loc4`='对于我这个圣光的卑微仆从，阿达尔从来不会隐瞒任何知识。', `MaleText_loc5`='阿達歐非常慷慨地對我披露事實，一位聖光的謙卑僕人。', `MaleText_loc7`='A''dal ha sido generoso en sus revelaciones conmigo, un simple siervo de la Luz.' WHERE `ID`=16740;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신성한 부름에 따라 진실을 알고자 하는 모든 이에게 그 실체를 말씀드리겠습니다.', `MaleText_loc4`='我的神圣使命要求我必须将这些真理分享给所有应该知晓它的人们。', `MaleText_loc5`='根據我神聖的召喚，我必須分享這些顯示的事實給所有願意聆聽的人。', `MaleText_loc7`='Según mi invocación divina, debo compartir estas verdades reveladas con todo aquel que quiera escucharlas.' WHERE `ID`=16741;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 모두의 마음속에는 성스러운 빛이 존재합니다...', `MaleText_loc4`='这让我得知，我们每个人的心中都有圣光……', `MaleText_loc5`='我很清楚的瞭解到在我們每個人裡面，都有聖光存在...', `MaleText_loc7`='Sé que, dentro de cada uno de ustedes, reside la Luz...' WHERE `ID`=16742;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자연의 모든 생명체가 조건 없이 가질 수 있는 선물이지요.', `MaleText_loc4`='……这是一份礼物，一份赐予所有自然生灵的礼物。', `MaleText_loc5`='...這是一個禮物，慷慨地給予所有自然出生的生命...', `MaleText_loc7`='Es un regalo. Un regalo que se entrega a todos los seres en el nacimiento.' WHERE `ID`=16743;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 필사적으로 방어합니다.', `MaleText_loc4`='%s绝望地保护着自己。', `MaleText_loc5`='%s絕望地保衛他自己。', `MaleText_loc7`='%s se defiende desesperadamente.' WHERE `ID`=16744;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원한다면 그대도 남아서 연설을 들어도 좋네.', `MaleText_loc4`='欢迎你继续负责。', `MaleText_loc5`='歡迎你繼續出席。', `MaleText_loc7`='Te rogamos que tengas un poco de paciencia.' WHERE `ID`=16745;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 근처에서 죽은 지 얼마 안 된 시체의 냄새를 맡습니다.', `MaleText_loc4`='%s闻了闻附近的一具新鲜尸体。', `MaleText_loc5`='%s聞到附近有一具新鮮的屍體。', `MaleText_loc7`='%s huele un cadáver reciente cercano.' WHERE `ID`=16746;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아! 정말 죄송합니다. 정말 당황스럽군요! 몰랐습니다... 아... 잠깐 누워서 좀 쉬십시오.', `MaleText_loc4`='哦！真对不起！太尴尬了！我没注意……啊……请躺下，多休息会吧。', `MaleText_loc5`='噢!非常抱歉。真是非常尷尬!我沒發覺到...啊...請躺下，多休息一下。', `MaleText_loc7`='¡Oh! Lo siento mucho. ¡Qué vergüenza! No me di cuenta de que... ah... por favor, túmbate, descánsate.' WHERE `ID`=16747;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 오리온 부사령관님. 이번 작전의 사상자 수는 만족할 만한 수준이었음을 보고드리러 왔습니다. 사실 부상자들은 상당히... 그러니까... 활기가 넘칩니다.', `MaleText_loc4`='啊，沃雷恩中将。我是来为这次行动作报告的，伤亡人数目前在我们可以接受的范围之内。事实上，伤者还很……精神着呢。', `MaleText_loc5`='啊，歐萊恩中將。我是來報告這次行動的傷亡等級完全是在可接受的範圍之內。實際上，傷員們還蠻... 啊...生氣勃勃。', `MaleText_loc7`='Ah, teniente general Orion. He venido a informar que las bajas están dentro de los niveles aceptables para esta operación. De hecho, los heridos están bastante... bien.' WHERE `ID`=16748;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 이런! 부사령관님, 정말 끔찍합니다! 이런 일은 난생처음입니다. 저는 다시 일을 하러 돌아가겠습니다.', `MaleText_loc4`='天哪，中将，太可怕了！我保证再也不会了。我现在就交出管理权。', `MaleText_loc5`='天哪，中將，這是多麼的恐怖!我一定不會如此。現在，我必須回到我的崗位。', `MaleText_loc7`='Cielo santo, general, ¡qué horror! Nunca me atrevería a algo semejante. Volveré a mis tareas.' WHERE `ID`=16749;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 반가운 소식이군. 그들에게 돌아가게, 사제여. 하지만 이것만은 기억하게. 그 누구도 잡아먹지 말게나.', `MaleText_loc4`='这是个好消息。回到他们身边吧，牧师。但是记住：谁都不许吃。', `MaleText_loc5`='這是好消息。回去找他們，牧師。但要注意:不要吃任何人。', `MaleText_loc7`='Buenas noticias. Vuelve con ellos, sacerdote. Pero escucha bien: NO te comas a nadie.' WHERE `ID`=16750;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아으으! 뭐 하는 거야? 난 아직 살아있다고, 이 나쁜 녀석아!', `MaleText_loc4`='啊！你在干什么？！我还活着呢，该死的！', `MaleText_loc5`='啊!你在做什麼?我還活著，可惡!', `MaleText_loc7`='¡Aaaay! ¡¿Qué haces?! ¡Todavía estoy vivo, idiota!' WHERE `ID`=16751;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성스러운 빛은 느낌으로 나타납니다. 처음에는 미약해서 쉽게 지나칠 수도 있지만 마침내는 진실을 보여주고 옳은 일을 하도록 인도하죠.', `MaleText_loc4`='刚开始的时候，圣光以某种微妙的感觉昭示着它的教义。人们很容易忽视这种感觉，但是圣光依然指引着他们探索真理，并促使他们常行善事。', `MaleText_loc5`='它將自己顯露為感覺，起初很小並且容易被忽視，那確認真實並且微妙地刺激一個人去做好事。', `MaleText_loc7`='Se manifiesta como un sentimiento, primero pequeño y fácil de ignorar, que confirma verdades y te empuja a hacer el bien.' WHERE `ID`=16752;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='순수한 친절, 자비로운 행동, 도움이 필요한 이들을 도와주는 일... 이 모든 게 성스러운 빛의 열매입니다.', `MaleText_loc4`='真诚、仁慈、宽恕、奉献。这些都是圣光结出的硕果。', `MaleText_loc5`='單純的仁慈，慈善的行為，服務那些有需要的。這些全部是聖光的果實。', `MaleText_loc7`='La simple bondad, los actos caritativos y la ayuda a los necesitados. Tales son los frutos de la Luz.' WHERE `ID`=16753;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성스러운 빛은 자신의 조언에 귀를 기울이는 자에게 눈에 보이는 혹은 보이지 않는 축복으로 보답합니다.', `MaleText_loc4`='圣光祝福那些接受感召的人们，这种赐福可能是有形的，也可能是无形的。', `MaleText_loc5`='那些注意到它以祝福所激勵的那些人將受到它的獎勵，不管是看見的和是未看見的。', `MaleText_loc7`='Recompensa a quienes siguen sus enseñanzas con bendiciones, tanto visibles como invisibles.' WHERE `ID`=16754;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러면 희망과 신념에 대한 믿음이 강해지면서 점점 더 강한 빛을 받아들일 수 있습니다.', `MaleText_loc4`='随着个人信念的逐渐强化，他对圣光之力的驾驭就会愈发纯熟。', `MaleText_loc5`='個人儲藏的希望和信仰被強化，以及偉大聖光的容量被提升了。', `MaleText_loc7`='Las reservas personales de esperanza y fe se ven fortalecidas y la capacidad de albergar la Luz en cada uno, aumenta.' WHERE `ID`=16755;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성스러운 빛의 가르침을 따르다 보면 그 목소리와 힘에 점점 민감해지는 자신을 느낄 수 있을 겁니다.', `MaleText_loc4`='经过时间的历练，越是服从圣光指引的人，就越能触及到圣光的声息，越能驾驭圣光的力量。', `MaleText_loc5`='隨著時間的演進，透過服從聖光的指導，一個人變的對它的聲音和能力感到更加敏感。', `MaleText_loc7`='Con el transcurso del tiempo, mediante la obediencia a la orientación de la Luz, te vuelves más sensible a su voz y a su poder.' WHERE `ID`=16756;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성스러운 빛을 충실히 섬기는 이들의 치유 능력과 축복의 힘은 정말 대단하지요.', `MaleText_loc4`='圣光最忠实的追随者们拥有无上的治愈与祝福之力。', `MaleText_loc5`='偉大是聖光的治療和祝福能力最勤勉的跟隨者。', `MaleText_loc7`='Glorioso es el poder de curación y bendición de los seguidores más fervientes de la Luz.' WHERE `ID`=16757;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘을 내시오! 밖에 있는 우리 동료가 이 장비들을 필요로 하고 있소!', `MaleText_loc4`='加油！小伙子们就在外面，我们要把这些补给物准备好！', `MaleText_loc5`='拜託!我們的兄弟們都在那邊，和他們迫切的需要這些補給品!', `MaleText_loc7`='¡Venga! Nuestros chicos están ahí fuera y necesitan esos suministros ya.', `FemaleText_loc1`='힘을 내시오! 밖에 있는 우리 동료가 이 장비들을 필요로 하고 있소!', `FemaleText_loc4`='加油！小伙子们就在外面，我们要把这些补给物准备好！', `FemaleText_loc5`='拜託!我們的兄弟們都在那邊，和他們迫切的需要這些補給品!', `FemaleText_loc7`='¡Venga! Nuestros chicos están ahí fuera y necesitan esos suministros ya.' WHERE `ID`=16758;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='속도를 늦추지 마시오! 이 물건들을 옮기고 무기를 수리해야 하오!', `MaleText_loc4`='继续干，小伙子们！我们要把这些补给品运走，还要把武器都修好！', `MaleText_loc5`='跟上速度，男孩們!我們需要移動這些補給品，及修復武器!', `MaleText_loc7`='¡Seguid así, chicos! ¡Hay que mover esta mercancía y reparar las armas!', `FemaleText_loc1`='속도를 늦추지 마시오! 이 물건들을 옮기고 무기를 수리해야 하오!', `FemaleText_loc4`='继续干，小伙子们！我们要把这些补给品运走，还要把武器都修好！', `FemaleText_loc5`='跟上速度，男孩們!我們需要移動這些補給品，及修復武器!', `FemaleText_loc7`='¡Seguid así, chicos! ¡Hay que mover esta mercancía y reparar las armas!' WHERE `ID`=16759;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='작업에 박차를 가하시오! 이 투석기가 저절로 고쳐지는 줄 아시오!', `MaleText_loc4`='加快速度！这些投石器可不会自己把自己给修好的！', `MaleText_loc5`='速度再快一點!這些弩砲可不會自行修好的!', `MaleText_loc7`='¡Cojamos ritmo! Esas balistas no se van a arreglar solas.', `FemaleText_loc1`='작업에 박차를 가하시오! 이 투석기가 저절로 고쳐지는 줄 아시오!', `FemaleText_loc4`='加快速度！这些投石器可不会自己把自己给修好的！', `FemaleText_loc5`='速度再快一點!這些弩砲可不會自行修好的!', `FemaleText_loc7`='¡Cojamos ritmo! Esas balistas no se van a arreglar solas.' WHERE `ID`=16760;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런데 슬프게도 성스러운 빛을 무시하고 죽을 운명 속에서 헤매는 이들이 있습니다.', `MaleText_loc4`='悲哀的是，那些徘徊的死者蔑视圣光。', `MaleText_loc5`='真悲哀，那些藐視聖光的人都步向死亡的墓地。', `MaleText_loc7`='Desgraciadamente, los hay que recorren la vida de espaldas a la Luz.' WHERE `ID`=16761;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성스러운 빛이 자취를 감추면 오직 어둠만이 남습니다.', `MaleText_loc4`='圣光抛弃了那些执迷不悟的愚者，留给他们的是无尽的黑暗。', `MaleText_loc5`='聖光從這些退離，直到只剩黑暗。', `MaleText_loc7`='Y entonces, la Luz se retirará, hasta que solo permanezca la oscuridad.' WHERE `ID`=16762;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛이 없는 곳에서는 절망과 혐오, 그리고 분노만이 창궐하는 법이지요.', `MaleText_loc4`='在没有圣光的地方，绝望、厌恶和愤怒横行。', `MaleText_loc5`='那裡沒有光明、絕望、厭惡和盛行的繁榮。', `MaleText_loc7`='Donde no hay luz, aparecen la desesperación, el odio y la ira.' WHERE `ID`=16763;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 어둠의 세력이 우리를 파멸하려고 성난 이를 드러내는 위험한 시대에 태어났습니다.', `MaleText_loc4`='我们出生在一个危险的时代，黑暗的力量誓要让我们走向毁灭。', `MaleText_loc5`='我們出生於危險的年代，在那裡黑暗的力量為我們帶來了毀滅。', `MaleText_loc7`='Hemos nacido en una época peligrosa, donde las fuerzas de la oscuridad están dispuestas a destruirnos.' WHERE `ID`=16764;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 성스러운 빛과 조화를 이뤄야 할 때입니다.', `MaleText_loc4`='是在圣光之下寻找自我的时候了。', `MaleText_loc5`='這些都是發現你自己與聖光同步的時機。', `MaleText_loc7`='En estos tiempos es cuando más cerca de la Luz hay que mantenerse.' WHERE `ID`=16765;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 말을 잘 기억하여 마음속의 성스러운 빛으로 진실을 직접 확인하십시오.', `MaleText_loc4`='聆听我的话语，感受存在于你们体内的圣光吧。', `MaleText_loc5`='聽我的禱言，並讓你體內的聖光確認它們的真偽。', `MaleText_loc7`='Escucha mis palabras y deja que la Luz de tu interior te diga que son ciertas.' WHERE `ID`=16766;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성스러운 빛이여, 제게 힘을 주소서!', `MaleText_loc4`='圣光，赐予我力量吧。', `MaleText_loc5`='聖光，給我力量。', `MaleText_loc7`='¡Luz, dame tu fuerza!', `FemaleText_loc1`='성스러운 빛이여, 제게 힘을 주소서!', `FemaleText_loc4`='圣光，赐予我力量吧。', `FemaleText_loc5`='聖光，給我力量。', `FemaleText_loc7`='Luz, dame fuerza.' WHERE `ID`=16767;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성스러운 빛이여, 우리의 타락한 형제자매들을 맡기려 하나이다. 부드러운 사랑으로 그들을 감싸 주시옵고, 모든 악으로부터 그들을 구원하여 영원한 안식을 안겨 주소서.', `MaleText_loc4`='我们恭敬地将堕落的兄弟姐妹们托付给圣光。此生，用你的款款爱意拥抱他们，保护他们远离邪恶的侵袭，让他们永远地安息吧。', `MaleText_loc5`='我們謙卑地委託我們墮落的兄弟和姐妹給聖光。在此生中你以你親切的愛擁抱他們;從每個邪惡中解救他們並且令他們進入永恆的長眠。', `MaleText_loc7`='Entregamos humildemente a nuestros hermanos y hermanas caídos a la Luz. En esta vida les diste tu dulce amor; líbralos ahora de todo el mal y deja que gocen del descanso eterno.', `FemaleText_loc1`='성스러운 빛이여, 우리의 타락한 형제자매들을 맡기려 하나이다. 부드러운 사랑으로 그들을 감싸 주시옵고, 모든 악으로부터 그들을 구원하여 영원한 안식을 안겨 주소서.', `FemaleText_loc4`='我们恭敬地将堕落的兄弟姐妹们托付给圣光。此生，用你的款款爱意拥抱他们，保护他们远离邪恶的侵袭，让他们永远地安息吧。', `FemaleText_loc5`='我們謙卑地委託我們墮落的兄弟和姐妹給聖光。在此生中你以你親切的愛擁抱他們;從每個邪惡中解救他們並且令他們進入永恆的長眠。', `FemaleText_loc7`='Entregamos humildemente a nuestros hermanos y hermanas caídos a la Luz. En esta vida les diste tu dulce amor; líbralos ahora de todo el mal y deja que gocen del descanso eterno.' WHERE `ID`=16768;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성스러운 빛이여, 타락한 이들을 거짓에서 진실로, 어둠에서 빛으로, 죽음에서 영생으로 이끌어 주소서.', `MaleText_loc4`='圣光，指引那些堕落者从虚伪走向真实，从黑暗走向光明，从死亡走向永生。', `MaleText_loc5`='聖光，引領墮落的人們從不真實到真實，從黑暗到光明，和從死亡到不朽。', `MaleText_loc7`='Luz, guía a los caídos de la falsedad a la verdad, de la oscuridad hacia la Luz y de la muerte a la vida infinita.', `FemaleText_loc1`='성스러운 빛이여, 타락한 이들을 거짓에서 진실로, 어둠에서 빛으로, 죽음에서 영생으로 이끌어 주소서.', `FemaleText_loc4`='圣光，指引那些堕落者从虚伪走向真实，从黑暗走向光明，从死亡走向永生。', `FemaleText_loc5`='聖光，引領墮落的人們從不真實到真實，從黑暗到光明，和從死亡到不朽。', `FemaleText_loc7`='Luz, guía a los caídos de la falsedad a la verdad, de la oscuridad hacia la luz y de la muerte a la vida infinita.' WHERE `ID`=16769;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성스러운 빛이 영원히 그대와 함께하기를.', `MaleText_loc4`='愿圣光与你同在。', `MaleText_loc5`='聖光永遠與你同在。', `MaleText_loc7`='Que la luz esté contigo ahora y siempre.', `FemaleText_loc1`='성스러운 빛이 영원히 그대와 함께하기를.', `FemaleText_loc4`='愿圣光与你同在。', `FemaleText_loc5`='聖光永遠與你同在。', `FemaleText_loc7`='Que la luz esté contigo ahora y siempre.' WHERE `ID`=16770;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미친 듯 깔깔거리는 %s의 눈이 붉은색으로 빛납니다!', `MaleText_loc4`='%s开始发狂了，他的眼睛变得通红！', `MaleText_loc5`='當%s開始瘋狂地咯咯笑時他的雙眼發著紅光!', `MaleText_loc7`='¡Los ojos de %s emiten un brillo rojo y comienza a reírse como un loco!' WHERE `ID`=16771;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사제가 무릎을 꿇고 조용히 기도합니다.', `MaleText_loc4`='牧师跪下来，默默地祈祷着。', `MaleText_loc5`='牧師在寧靜的祈禱中跪下。', `MaleText_loc7`='El sacerdote se arrodilla y reza en silencio.', `FemaleText_loc1`='사제가 무릎을 꿇고 조용히 기도합니다.', `FemaleText_loc4`='牧师跪下来，默默地祈祷着。', `FemaleText_loc5`='牧師在寧靜的祈禱中跪下。', `FemaleText_loc7`='El sacerdote se arrodilla y reza en silencio.' WHERE `ID`=16772;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이미 충분히 귀찮게 하지 않았나? 꼭 잠까지 깨워야겠나?', `MaleText_loc4`='你折腾得还不够吗？你非要把我从沉睡中惊醒吗？', `MaleText_loc5`='你所造成的傷害還不夠嗎?你一定要來擾亂我的睡眠嗎?', `MaleText_loc7`='¿No has hecho ya daño suficiente? ¿Tienes también que despertarme de mi letargo?' WHERE `ID`=16773;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 폭력으로 무슨 이득을 얻을 수 있나? 지난 일은 지난 일일 뿐이야. 난 우리 동족을 실망시켰네.', `MaleText_loc4`='暴力就能解决一切吗？该做的事，我都做完了。我辜负了我的族人。', `MaleText_loc5`='暴力到底能帶來甚麼利益?事情已經發生了。我失敗了。', `MaleText_loc7`='¿De qué sirve esta violencia? Lo hecho, hecho está. He fallado a mi pueblo.' WHERE `ID`=16774;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대 안의 빛을 받아들이십시오, 동지들이여! 어둠을 멀리하십시오...', `MaleText_loc4`='拥抱你体内的圣光吧，我的朋友们！将所有的黑暗拒之门外……', `MaleText_loc5`='擁抱在你內心的聖光，我的朋友!摒棄所有黑暗...', `MaleText_loc7`='¡Ábranse a la Luz de su interior, amigos! Saquen de ustedes toda la oscuridad...' WHERE `ID`=16775;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 믿음으로 이 시련을 견뎌내야 합니다. 그러면 언젠가 승리를 거둘 겁니다.', `MaleText_loc4`='我们必须忍耐这些痛苦的时期，总有一天我们会找到属于自己的胜利。', `MaleText_loc5`='我們必須忠實地忍受這些試驗的時代，有一天我們將會發現我們自己勝利了。', `MaleText_loc7`='Hay que sufrir estas pruebas con la esperanza de que algún día saldremos victoriosos.' WHERE `ID`=16776;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 할 일은 성스러운 빛이 통치하는 평화의 시대가 도래했음을 알리는 것입니다.', `MaleText_loc4`='它引领我们走向一个由圣光统治的和平时代。', `MaleText_loc5`='迎接一個和平時代的責任落在我們身上，在那裡聖光將統治一切。', `MaleText_loc7`='De nosotros depende que empiece una era de paz en la que la Luz reine.' WHERE `ID`=16777;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나루의 이름으로 그리될 겁니다.', `MaleText_loc4`='以纳鲁的名义，愿我们的愿望能够实现。', `MaleText_loc5`='以那魯之名，但願如此。', `MaleText_loc7`='Por los naaru, que así sea.' WHERE `ID`=16778;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대수도자여, 그대의 말씀대로 될 겁니다.', `MaleText_loc4`='但愿就像你说的那样，大人。', `MaleText_loc5`='願一切能如你所說，大隱士艾蒙南。', `MaleText_loc7`='Que así sea, gran anacoreta.' WHERE `ID`=16779;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛의 길에 이르기를...', `MaleText_loc4`='愿我们的愿望能够实现。', `MaleText_loc5`='但願如此。', `MaleText_loc7`='Que así sea.', `FemaleText_loc1`='빛의 길에 이르기를...', `FemaleText_loc4`='愿我们的愿望能够实现。', `FemaleText_loc5`='但願如此。', `FemaleText_loc7`='Que así sea.' WHERE `ID`=16780;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s에게 발각되었습니다!', `MaleText_loc4`='你被%s发现了！', `MaleText_loc5`='你被%s發現了!', `MaleText_loc7`='¡%s te ha detectado!' WHERE `ID`=16781;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 죽은 동료의 영혼을 결속하려고 합니다.', `MaleText_loc4`='%s试着去抓住阵亡战友的灵魂。', `MaleText_loc5`='%s嘗試保存他死去同伴的靈魂。', `MaleText_loc7`='%s intenta vincular el espíritu de su camarada caído.' WHERE `ID`=16782;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시키는 대로 해, 어서 날아!', `MaleText_loc4`='照我说的做，飞吧！', `MaleText_loc5`='照我的話做，飛!', `MaleText_loc7`='Haz lo que te digo. ¡Vuela!', `FemaleText_loc1`='시키는 대로 해, 어서 날아!', `FemaleText_loc4`='照我说的做，飞吧！', `FemaleText_loc5`='照我的話做，飛!', `FemaleText_loc7`='Haz lo que te digo. ¡Vuela!' WHERE `ID`=16783;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일이 있어도 신록의 정원을 지켜야 합니다!', `MaleText_loc4`='不惜一切代价保卫生态船！', `MaleText_loc5`='不惜代價保護波塔尼卡!', `MaleText_loc7`='¡Protege el Invernáculo cueste lo que cueste!' WHERE `ID`=16784;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자들을 모조리 처단해야 합니다!', `MaleText_loc4`='任何入侵者都必须被消灭！', `MaleText_loc5`='消滅所有的入侵者!', `MaleText_loc7`='¡Los intrusos deben ser eliminados!' WHERE `ID`=16785;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='캘타스 님이 우릴 구원하실 겁니다!', `MaleText_loc4`='凯尔萨斯会拯救我们。', `MaleText_loc5`='凱爾薩斯會拯救我們。', `MaleText_loc7`='Kael''Thas nos salvará.' WHERE `ID`=16786;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='때가 왔다, 굴단! 너의 흑마법사들에게 좀 더 노력하라고 해라! 지금부터 어둠의 문이 열리고 너의 호드는 이 썩어빠진 불신의 세상으로 풀려날 것이다!', `MaleText_loc4`='时机成熟了！古尔丹，命令你的术士们加倍努力！用不了多久，传送门就会打开，你的部落将在这个富饶而毫无防备的世界中所向披靡！', `MaleText_loc5`='時候到了!古爾丹，命令你的術士們加倍努力!很快的，傳送門將會打開，而你的部落將會被放在這個一攻即破，沒有戒心的世界中!', `MaleText_loc7`='¡Ha llegado la hora! ¡Gul''dan, ordena a tus brujos redoblar esfuerzos! ¡En unos instantes, el portal se abrirá y tu Horda marchará sobre este mundo maduro y confiado!' WHERE `ID`=16787;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명예롭게 죽고 안식을 찾도록 하라.', `MaleText_loc4`='你会光荣地死去的。', `MaleText_loc5`='你會和光榮的死者一起安息。', `MaleText_loc7`='Descansarás con los muertos honorables.', `FemaleText_loc1`='명예롭게 죽고 안식을 찾도록 하라.', `FemaleText_loc4`='你会光荣地死去的。', `FemaleText_loc5`='你會和光榮的死者一起安息。', `FemaleText_loc7`='Descansarás con los muertos.' WHERE `ID`=16788;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭔가? 용사들이여... 날 도우러 왔나? 어둠의 존재가 느껴진다. 이 신성한 의식에는 분명 그의 축복이 담겨 있다.', `MaleText_loc4`='你们是……来帮助我的？我感觉到了黑暗之王的力量。看来这个伟大的时刻已经得到了他的赐福。', `MaleText_loc5`='這是什麼?勇士們...來支援我?我感覺到黑暗者插手這件事了。這次神聖的事件真的受到了他的祝福。', `MaleText_loc7`='¿Qué es esto? Campeones... ¿que vienen en mi ayuda? Siento la mano del Oscuro tras esto. Verdaderamente este sagrado suceso porta su bendición.' WHERE `ID`=16789;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 이런 나약한 무리에게 당하다니!', `MaleText_loc4`='不！我诅咒这具脆弱的躯体！', `MaleText_loc5`='這個該死的軀體既虛弱又平凡!', `MaleText_loc7`='¡No! ¡Malditos sean estos débiles mortales!' WHERE `ID`=16790;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너는 죽음을 선택했다.', `MaleText_loc4`='你选择了死亡。', `MaleText_loc5`='你選擇了死亡。', `MaleText_loc7`='Has escogido la muerte.', `FemaleText_loc1`='너는 죽음을 선택했다.', `FemaleText_loc4`='你选择了死亡。', `FemaleText_loc5`='你選擇了死亡。', `FemaleText_loc7`='Has escogido la muerte.' WHERE `ID`=16791;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용사들이여! 나의 보호막이 약해진다!', `MaleText_loc4`='勇士们！我的护盾正在减弱！', `MaleText_loc5`='勇士們!我的護盾變弱了!', `MaleText_loc7`='¡Campeones! ¡Mi escudo se debilita!' WHERE `ID`=16792;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳을 침입한 대가를 치르리라.', `MaleText_loc4`='你会为此付出代价的。', `MaleText_loc5`='你會為這次侵犯付出代價。', `MaleText_loc7`='Pagarás por esta transgresión.', `FemaleText_loc1`='이곳을 침입한 대가를 치르리라.', `FemaleText_loc4`='你会为此付出代价的。', `FemaleText_loc5`='你會為這次侵犯付出代價。', `FemaleText_loc7`='Pagarás por esta transgresión.' WHERE `ID`=16793;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나의 힘을 어둠의 문에 집중해야 돼! 보호막을 지탱할 시간이 없다!', `MaleText_loc4`='我的能量必须集中在传送门上！我没有时间来增强护盾了！', `MaleText_loc5`='我的力量必須被集中於傳送門!我沒有時間維持護盾!', `MaleText_loc7`='¡Tengo que concentrar mis poderes en el portal! ¡No hay tiempo para retener el escudo!' WHERE `ID`=16794;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보호막이 거의 없어졌다! 위험하다. 모든 일이 수포로 돌아갈지도 몰라!', `MaleText_loc4`='护盾快要消失了！我的一切努力随时都有可能付之东流！', `MaleText_loc5`='護盾差不多要消失了!我所有的努力將暴露在危險之中!', `MaleText_loc7`='¡Casi ha desparecido el escudo! ¡Peligra todo mi trabajo!' WHERE `ID`=16795;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용사들이여, 도와줘서 고맙다. 이제 굴단의 호드는 굶주린 메뚜기떼처럼 이 세상을 휩쓸 것이다. 내가 계획한 모든 것들이 마침내 실현될 것이다.', `MaleText_loc4`='感谢你们的帮助，勇士们。古尔丹的部落将会像蝗虫一样席卷这个世界，我精心准备的计划也总算没有白费。', `MaleText_loc5`='我感激你的幫助，勇士們。現在，古爾丹的部落將像一群蝗蟲一樣掃過這個世界，我所有的設計以及仔細實行的計畫最後都將逐漸被理解。', `MaleText_loc7`='Les agradezco su ayuda, campeones. Ahora la Horda de Gul''dan se extenderá por este mundo como una plaga de langostas, y todos mis diseños y mis meticulosos planes verán sus frutos.' WHERE `ID`=16796;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쉿! 영혼들이 자고 있다!', `MaleText_loc4`='嘘！灵魂们正在长眠！', `MaleText_loc5`='噓!亡靈在睡覺!', `MaleText_loc7`='¡Sssh! Los espíritus duermen.', `FemaleText_loc1`='쉿! 영혼들이 자고 있다!', `FemaleText_loc4`='嘘！灵魂们正在长眠！', `FemaleText_loc5`='噓!亡靈在睡覺!', `FemaleText_loc7`='¡Sssh! Los espíritus duermen.' WHERE `ID`=16797;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모든 것이 파멸할 것이다!', `MaleText_loc4`='毁灭降临了！', `MaleText_loc5`='毀滅會找到我們所有人!', `MaleText_loc7`='¡La ruina nos llega a todos!', `FemaleText_loc1`='모든 것이 파멸할 것이다!', `FemaleText_loc4`='毁灭降临了！', `FemaleText_loc5`='毀滅會找到我們所有人!', `FemaleText_loc7`='¡La ruina nos llega a todos!' WHERE `ID`=16798;
