UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 고집을 피우는 게냐? 어차피 다 헛된 일... 아직 늦지 않았어! 살 수 있을 때 도망쳐라!', `MaleText_loc4`='你们为什么还要坚持下去？难道你们不明白这样做是毫无意义的吗？还不算太晚！你们仍然可以全身而退……', `MaleText_loc5`='你還在堅持什麼?你當然能看見它全然無用。現在還不算太遲!你仍然可以活著離開...', `MaleText_loc7`='¿Por qué insisten? Seguramente ven la inutilidad de todo. Aún pueden marcharse con vida...' WHERE `ID`=16821;
