UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 쳇바퀴처럼 돌아가는 세상을 영원히 부서뜨릴 때가 왔다! 우린 모래시계의 노예가 아니야! 경고한다. 이 위대한 뜻을 거부하는 자, 첫 번째 희생양이 되리라!', `MaleText_loc4`='是时候毁灭这个秩序的世界了！让我们永远不再受到时间沙漏的制约！我警告你们：不愿迎接这一伟大时刻的蠢货，都将变成它的牺牲品！', `MaleText_loc5`='是時候永遠打破這個以時間規律運作的宇宙了!讓我們不再被沙漏所奴役!我警告你:那些無法完全接受這條更為偉大道路的人，將成為路上的犧牲者!', `MaleText_loc7`='¡Ha llegado la hora de destruir este universo de cuerda para siempre! ¡Dejaremos de ser esclavos del reloj de arena! ¡Les advierto: aquellos que no sigan este gran camino serán arrollados por él!' WHERE `ID`=16827;
