UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도대체 무슨 짓이냐? 난... 아악...', `MaleText_loc4`='这是什么骗局？我……啊……', `MaleText_loc5`='這是什麼奸計?我...啊...', `MaleText_loc7`='¿Qué clase de truco es esto? Yo... AAARRR...', `FemaleText_loc1`='도대체 무슨 짓이냐? 난... 아악...', `FemaleText_loc4`='这是什么骗局？我……啊……', `FemaleText_loc5`='這是什麼奸計?我...啊...', `FemaleText_loc7`='¿Qué clase de truco es esto? Yo... AAARRR...' WHERE `ID`=16840;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선조님의 보살핌이 있기를, 친절한 이여...', `MaleText_loc4`='先祖们保佑着你，善良的人……', `MaleText_loc5`='祖先守護著你，好心人...', `MaleText_loc7`='Que los ancestros te protejan...', `FemaleText_loc1`='선조님의 보살핌이 있기를, 친절한 이여...', `FemaleText_loc4`='先祖们保佑着你，善良的人……', `FemaleText_loc5`='祖先守護著你，好心人...', `FemaleText_loc7`='Que los ancestros te protejan...' WHERE `ID`=16841;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더는 못 봐주겠군. 내가 제군들이라면 당장 신전으로 달려가서 제발 총 좀 똑바로 쏘게 해달라고 기도라도 올릴 것이다!', `MaleText_loc4`='我看不下去了。如果我是你的话，我就会去神殿祈祷自己能打得更准一点！', `MaleText_loc5`='我已經看夠了。如果我是你，我將到聖壂並且祈禱當你可以在實戰中射的直一點!', `MaleText_loc7`='Ya he visto bastante. Si yo estuviera en tu lugar, me iría al templo a rezar para poder aprender a disparar de verdad.' WHERE `ID`=16842;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 근처의 칼날발톱에게로 달아나려 합니다.', `MaleText_loc4`='%s试图逃向附近的掠食者。', `MaleText_loc5`='%s嘗試逃到附近的劫毀者那裡。', `MaleText_loc7`='%s intenta huir a un devastador cercano.', `FemaleText_loc1`='%s|1이;가; 근처의 칼날발톱에게로 달아나려 합니다.', `FemaleText_loc4`='%s试图逃向附近的掠食者。', `FemaleText_loc5`='%s嘗試逃到附近的劫毀者那裡。', `FemaleText_loc7`='%s intenta huir a un devastador cercano.' WHERE `ID`=16843;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가로쉬가 자네에게 뭐라고 하던가, $n?', `FemaleText_loc4`='加尔鲁什跟你说了些什么，$n？', `FemaleText_loc5`='卡爾洛斯跟你說了什麼，$n?', `FemaleText_loc7`='¿Qué te dijo Garrosh, $n?' WHERE `ID`=16844;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대모님, 이제는 가로쉬를 구제할 방법이 없습니다. 마그하르를 돕는 제 모습을 지켜본 가로쉬가 자신이 지도자로서 자질이 한참은 부족하다고 판단한 것 같습니다.', `MaleText_loc4`='盖亚安祖母，加尔鲁什已经不可救药了。为了玛格汗的未来着想，我认为他已经不适合继续领导氏族了。', `MaleText_loc5`='卡爾洛斯是無可救藥的，主母。我懼怕在幫助瑪格哈的過程同時，我已經使卡爾洛斯認為他不適合成為領導人。', `MaleText_loc7`='Garrosh no puede ser perdonado, Abuela. Me temo que al ayudar a los Mag''har he convencido a Garrosh de que no puede ser el líder.', `FemaleText_loc1`='대모님, 이제는 가로쉬를 구제할 방법이 없어요. 마그하르를 돕는 제 모습을 지켜본 가로쉬가 자신이 지도자로서 자질이 한참은 부족하다고 판단한 것 같아요.', `FemaleText_loc4`='盖亚安祖母，加尔鲁什已经不可救药了。为了玛格汗的未来着想，我认为他已经不适合继续领导氏族了。', `FemaleText_loc5`='卡爾洛斯是無可救藥的，主母。我懼怕在幫助瑪格哈的過程同時，我已經使卡爾洛斯認為他不適合成為領導人。', `FemaleText_loc7`='Garrosh no puede ser perdonado, Abuela. Me temo que al ayudar a los Mag''har he convencido a Garrosh de que no puede ser el líder.' WHERE `ID`=16845;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그럴 리가... 그가 그렇게 쉽게 포기하다니... 가로쉬가 자네에게 대족장의 자리를 부탁한 이유가 뭔가?', `FemaleText_loc4`='不可能。他不能就这么放弃。为什么他会要求你取代他酋长的位置？', `FemaleText_loc5`='不可能。他實在不能就這樣放棄。他為什麼要求你取代他的位置成為新的大酋長?', `FemaleText_loc7`='No puede ser. No puede rendirse sin más. ¿Por qué te ha pedido que ocuparas su puesto de Jefe de Guerra?' WHERE `ID`=16846;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대모님, 그가 말하길 마그하르 전체가 저를 아끼고 존경하며 신뢰하고 있다고 합니다. 제가 대족장이 된다면 그는 대모님이 돌아가신 후에 자신도 편히 죽음을 맞이할 수 있을 거라고 했습니다.', `MaleText_loc4`='祖母，他告诉我整个玛格汉氏族都爱我，尊敬我，信任我。他对我说他会把酋长的位置让给我，那样当您去世后他就可以毫无挂念地死去，让他的血统彻底消失。', `MaleText_loc5`='主母，他告訴我全部瑪格哈的愛、榮譽、並且相信我。當他是大酋長時，他曾向我說過當你通過時，他將無牽掛地死去，將他的血脈從這世上從此移除。', `MaleText_loc7`='Abuela, me dice que todos los Mag''har me quieren, me honran y confían en mí. Dice que, conmigo como Jefe de Guerra, él quedará liberado cuando tú no estés, eliminando su línea de sangre de la existencia.', `FemaleText_loc1`='대모님, 그가 말하길 마그하르 전체가 저를 아끼고 존경하며 신뢰하고 있다고 합니다. 제가 대족장이 된다면 그는 대모님이 돌아가신 후에 자신도 편히 죽음을 맞이할 수 있을 거라고 했습니다.', `FemaleText_loc4`='祖母，他告诉我整个玛格汉氏族都爱我，尊敬我，信任我。他对我说他会把酋长的位置让给我，那样当您去世后他就可以毫无挂念地死去，让他的血统彻底消失。', `FemaleText_loc5`='主母，他告訴我全部瑪格哈的愛、榮譽、並且相信我。當他是大酋長時，他曾向我說過當你通過時，他將無牽掛地死去，將他的血脈從這世上從此移除。', `FemaleText_loc7`='Abuela, me dice que todos los Mag''har me quieren, me honran y confían en mí. Dice que, conmigo como Jefe de Guerra, él quedará liberado cuando tú no estés, eliminando su línea de sangre de la existencia.' WHERE `ID`=16847;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='<당신의 대답에 고개를 끄덕이는 대모 게야>$B$B나는 더 이상 싸울 힘이 없네. 나의 시대는 오래전에 끝났어. 다시 한번 자네에게 고맙다는 말을 하고 싶네. 가로쉬에게는 별 감흥을 주지 못한 것 같네만 자네의 업적은 우리 백성의 용기를 북돋아 주었네. 이제 우리 일족은 단결하여 우리의 권리를 위해 싸울 각오가 되었네.', `FemaleText_loc4`='<盖亚安祖母点了点头，接受了你的回答。>$B$B我不能再和灵魂战斗了，$n。我的时日已经不多了。我必须再次感谢你所做的一切，虽然你也许无法改变加尔鲁什，但我的很多人民已经由于你的努力而重新树立了信心。他们现在非常希望能为我们氏族的生存而战。', `FemaleText_loc5`='<主母吉雅點了點頭，接受你的回答。>$B$B我不能再與那些精靈戰鬥了，$n。我的時代老早以前就過去了。再一次，我必須為你所做的一切感謝你。當卡爾洛斯也許無法被移動，我的大多數族人已經被你的成就所感動。他們現在願意成為一個聯合的部落來為我們的權利而戰鬥。', `FemaleText_loc7`='<La Abuela Geyah asiente, aceptando tu respuesta.>$B$BYa no puedo seguir luchando con los espíritus, $n. Ha llegado mi hora. De nuevo, debo darte las gracias por todo lo que has hecho. Si bien es posible que a Garrosh no se le pueda conmover, muchos de los míos se han sentido exaltados por tus logros. Ahora están dispuestos a luchar por nuestros derechos como un clan unido.' WHERE `ID`=16848;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 최선을 다해서 노력했을 뿐입니다, 대모님. 따뜻한 말씀 감사합니다.', `MaleText_loc4`='我做了所有我能做的事情，祖母。感谢您的赞美之词。', `MaleText_loc5`='我已做了所有我能做的，主母。感謝你仁慈的話語。', `MaleText_loc7`='He hecho todo lo que he podido, Abuela. Te doy las gracias por tus amables palabras.', `FemaleText_loc1`='전 최선을 다해서 노력했을 뿐인 걸요, 대모님. 따뜻한 말씀 감사해요.', `FemaleText_loc4`='我做了所有我能做的事情，祖母。感谢您的赞美之词。', `FemaleText_loc5`='我已做了所有我能做的，主母。感謝你仁慈的話語。', `FemaleText_loc7`='He hecho todo lo que he podido, Abuela. Te doy las gracias por tus amables palabras.' WHERE `ID`=16849;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='<당신을 향해 미소를 짓는 대모 게야>$B$B자네를 보니 내 아들이 생각나는군, $n!$B$B아들은 어떤 고난에도 꿈쩍하지 않는 태산과도 같았지. 우리 일족의 힘과 명예의 상징이었다네.$B$B<눈물을 글썽거리는 게야>$B$B그 아이는 우리를 구하기 위해서 자신을 희생했네. 후손들이 피의 저주가 없는 세상에서 살아가게 해주려고... 사악한 굴단과 그의 검은 호드만 아니었다면...$B$B<깊은 생각에 빠져 먼 곳을 바라보는 게야>$B$B듀로탄, 네가 살아 있다면 얼마나 좋을까. 우리 백성에게는 네가 정말 절실하게 필요하구나...', `FemaleText_loc4`='<盖亚安祖母对你笑了笑。>$B$B你让我想起了我的儿子，$n。$B$B他曾是一座雄伟的山脉，一个代表着力量和荣誉的支柱。$B$B<盖亚安的眼睛里闪烁着泪花。>$B$B他为了我们的生存牺牲了自己，为了让兽人后代们可以出生在一个没有血之诅咒……没有古尔丹和他的黑暗部落的世界。$B$B<盖亚安凝视着远方，发着呆。>$B$B杜隆坦……我多么希望你能在这里啊，你的人民需要你……', `FemaleText_loc5`='<主母吉雅對著你微笑。>$B$B你使我想起我的兒子，$n。$B$B他是一座不可移動的山︰一個社會的棟樑和榮譽。$B$B<吉雅的眼睛涌出眼淚。>$B$B他犧牲自己，好讓我們能倖存下來。以便在他之後的數代獸人，可以出生於一個沒有血詛咒的世界...沒有古爾丹和他的黑暗部落...$b$b<吉雅凝視遠方，呆呆地默想的。>$B$B噢 杜洛坦，我真希望你能在這裡。你的族人如此地需要你...', `FemaleText_loc7`='<La abuela Geyah te sonríe.>$B$BMe recuerdas a mi hijo, $n.$B$BÉl era una montaña inamovible: un pilar de fuerza y honor.$B$B<Los ojos de Geyah se llenan de lágrimas.>$B$BSe sacrificó para que pudiéramos sobrevivir. Para que generaciones de orcos tras él pudieran nacer en un mundo sin la maldición de la sangre... Sin Gul''dan y su Horda oscura...$B$B<Geyah mira fijamente a la distancia, perdida en sus pensamientos.>$B$BOh, Durotan, cómo deseo que pudieras estar aquí. Tu pueblo te necesita desesperadamente...' WHERE `ID`=16850;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대모님이 바로 듀로탄 님의 어머니란 말씀입니까?', `MaleText_loc4`='盖亚安祖母，您是杜隆坦的母亲？', `MaleText_loc5`='主母，你是杜洛坦的母親嗎?', `MaleText_loc7`='Abuela, ¿eres la madre de Durotan?', `FemaleText_loc1`='대모님이 바로 듀로탄 님의 어머니세요?', `FemaleText_loc4`='盖亚安祖母，您是杜隆坦的母亲？', `FemaleText_loc5`='主母，你是杜洛坦的母親嗎?', `FemaleText_loc7`='Abuela, ¿eres la madre de Durotan?' WHERE `ID`=16851;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='<고개를 끄덕이는 대모 게야>$B$B내 아들을 알고 있나?', `FemaleText_loc4`='<盖亚安祖母点了点头。>$B$B你认识我儿子？', `FemaleText_loc5`='<主母吉雅點點頭。>$B$B你認識我兒子嗎?', `FemaleText_loc7`='<La Abuela Geyah asiente con la cabeza.>$B$B¿Conociste a mi hijo?' WHERE `ID`=16852;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대모님, 안타깝게도 그런 영광스러운 기회는 제게 돌아오지 않았습니다. 듀로탄 님은 오래전에 세상을 뜨셨지만 그분의 영웅담은 제가 사는 곳의 모든 이들이 잘 알고 있습니다. 아제로스의 오크들은 대모님의 아드님 이름을 딴 듀로타라는 곳에서 살고 있고요. 그리고... <잠시 호흡을 가다듬고 대모에게 말할 내용을 정리합니다.>', `MaleText_loc4`='盖亚安祖母，我没有这个荣幸。杜隆坦在我出生前就去世了，但是他的英雄事迹传遍了我的世界。艾泽拉斯的兽人国家就以你儿子而命名，叫做杜隆塔尔，而且……<你停下来吸了一口气，考虑着你将要告诉盖亚安祖母的事情。>', `MaleText_loc5`='主母，我從未有此榮幸。杜洛坦早在我之前已死，但是他的英雄事跡在我的世界上為人所熟知。艾澤拉斯的獸人們居住在一個稱為杜洛塔的地方，以你的兒子之名所命。並且... <你花費片刻呼吸，並且徹底考慮你將要告訴主母的事。>', `MaleText_loc7`='Abuela, nunca he tenido el honor. Durotan murió antes de que yo naciera, pero sus heroicos actos son conocidos por todos en mi mundo. Los orcos de Azeroth residen en un lugar llamado Durotar, nombrado así en honor a tu hijo. Y... <Haces una pausa para respirar y pensar bien lo que estás a punto de decirle a la Abuela.>', `FemaleText_loc1`='대모님, 안타깝게도 그런 영광스러운 기회는 제게 돌아오지 않았습니다. 듀로탄 님은 오래전에 세상을 뜨셨지만 그분의 영웅담은 제가 사는 곳의 모든 이들이 잘 알고 있습니다. 아제로스의 오크들은 대모님의 아드님 이름을 딴 듀로타라는 곳에서 살고 있고요. 그리고... <잠시 호흡을 가다듬고 대모에게 말할 내용을 정리합니다.>', `FemaleText_loc4`='盖亚安祖母，我没有这个荣幸。杜隆坦在我出生前就去世了，但是他的英雄事迹传遍了我的世界。艾泽拉斯的兽人国家就以你儿子而命名，叫做杜隆塔尔，而且……<你停下来吸了一口气，考虑着你将要告诉盖亚安祖母的事情。>', `FemaleText_loc5`='主母，我從未有此榮幸。杜洛坦早在我之前已死，但是他的英雄事跡在我的世界上為人所熟知。艾澤拉斯的獸人們居住在一個稱為杜洛塔的地方，以你的兒子之名所命。並且... <你花費片刻呼吸，並且徹底考慮你將要告訴主母的事。>', `FemaleText_loc7`='Abuela, nunca he tenido el honor. Durotan murió antes de que yo naciera, pero sus heroicos actos son conocidos por todos en mi mundo. Los orcos de Azeroth residen en un lugar llamado Durotar, nombrado así en honor a tu hijo. Y... <Haces una pausa para respirar y pensar bien lo que estás a punto de decirle a la Abuela.>' WHERE `ID`=16853;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='<대모 게야의 보라색 눈동자가 당신을 응시합니다.>$B$B그래...', `FemaleText_loc4`='<盖亚安祖母的那双紫罗兰色的眼睛盯着你。>$B$B而且……？', `FemaleText_loc5`='<主母吉雅紫色的眼睛緊盯著你的雙眼。>$B$B是的...', `FemaleText_loc7`='<Los ojos violetas de la Abuela Geyah se fijan en los tuyos.>$B$BSí...' WHERE `ID`=16854;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대모님, 우리 대족장님을 아세요? 제가 온 세계에서 우리 종족을 이끌고 계신 분 말입니다. 그분이 바로... 듀로탄 님의 아들입니다. 그러니까, 대모님의 손자죠.', `MaleText_loc4`='我们那个世界的酋长，我的同胞的领袖。他……他是杜隆坦的儿子。他是你的孙子。', `MaleText_loc5`='它是我的大酋長，主母。我族人的領導人。來自我的世界。他...他是杜洛坦的兒子。他是你的孫子。', `MaleText_loc7`='Es mi Jefe de Guerra, abuela. El líder de mi pueblo. De mi mundo. Es... Es el hijo de Durotan. Es tu nieto.', `FemaleText_loc1`='대모님, 우리 대족장님을 아세요? 제가 온 세계에서 우리 종족을 이끌고 계신 분 말입니다. 그분이 바로... 듀로탄 님의 아들입니다. 그러니까, 대모님의 손자죠.', `FemaleText_loc4`='我们那个世界的酋长，我的同胞的领袖。他……他是杜隆坦的儿子。他是你的孙子。', `FemaleText_loc5`='它是我的大酋長，主母。我族人的領導人。來自我的世界。他...他是杜洛坦的兒子。他是你的孫子。', `FemaleText_loc7`='Es mi Jefe de Guerra, abuela. El líder de mi pueblo. De mi mundo. Es... Es el hijo de Durotan. Es tu nieto.' WHERE `ID`=16855;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='<대모 게야의 얼굴을 타고 흘러내리는 눈물>$B$B듀로탄... 우리 듀로탄이 살아남아... 아들을 낳았단 말이지? 드라카가 떠나기 전에 말했던 그 아이란 말인가? 그들은 이런 세상에서 어떻게 아이를 기르냐며 걱정했지. 그 문 반대편의 세상이 그들의 유일한 희망이었네. 듀로탄에게는 말하지 못했지만 정령들에게 그들을 보살펴 달라고, 아이를 지키고 그들에게 힘이 되어달라고 간절히 부탁했네.$B$B손자를... 꼭 만나고 싶네. 꼭 만나야 해. 부탁하네. 시간이 얼마 남지 않았네. 손자에게 전해 주게. 내가 죽기 전에...', `FemaleText_loc4`='<盖亚安祖母泪如泉涌。>$B$B我……我……杜隆坦还有个孩子？德拉卡那孩子在他们离开前告诉我……他们最害怕的就是……让一个孩子在这样的世界中长大。那座门的对面曾是他们唯一的希望。我不敢告诉杜隆坦，但是暗地里，我祈求灵魂保佑他们——保佑他们的孩子，并赐予他们力量。$B$B我……我一定要看看我的孙子。我一定要看到他。请帮我这个忙，我太虚弱了。你必须在我离开这个世界前告诉他……', `FemaleText_loc5`='<淚水從主母吉雅的臉上落下。>$B$B我...我...杜洛坦倖存下來而有一個孩子嗎?這個孩子崔坎在他們離開之前告訴我...那是他們最大的恐懼...在這個世界培養一個孩子。在那扇門的另一邊是他們唯一的希望。我不敢告訴杜洛坦，但是秘密地，我懇求精靈庇祐他們 - 保護他們的孩子並且給他們力量。$B$B我...我必須看看我的孫子。我必須看看他。拜託，我太虛弱了。你必須告訴他。在我離開這個世界之前...', `FemaleText_loc7`='<Las lágrimas surcan la cara de la Abuela Geyah.>$B$BYo... Yo... ¿Durotan sobrevivió para tener un hijo? El niño sobre el que Draka me habló antes de irse... Era su mayor miedo... Criar un niño en este mundo. Al otro lado de esa puerta yacía su única esperanza. No me atreví a decírselo a Durotan pero, en secreto, supliqué a los espíritus que les protegiesen... que protegiesen a su hijo y les diesen fuerza.$B$BDebo... debo ver a mi nieto. Debo verle. Por favor, estoy demasiado débil. ¡Debes decírselo! Antes de que se acabe mi tiempo en este mundo...' WHERE `ID`=16856;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대모님, 지금 즉시 아제로스로 돌아가겠습니다.', `MaleText_loc4`='我会马上回到艾泽拉斯的，祖母。', `MaleText_loc5`='我會立刻回到艾澤拉斯，主母。', `MaleText_loc7`='Volveré a Azeroth ahora mismo, Abuela.', `FemaleText_loc1`='대모님, 지금 즉시 아제로스로 돌아가겠습니다.', `FemaleText_loc4`='我会马上回到艾泽拉斯的，祖母。', `FemaleText_loc5`='我會立刻回到艾澤拉斯，主母。', `FemaleText_loc7`='Volveré a Azeroth ahora mismo, Abuela.' WHERE `ID`=16857;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어리석은 녀석! 너는 네가 이해할 수 없는 세계를 돌아다니는 어린 아이일 뿐이다. 더 이상 입을 놀리지 마라!', `MaleText_loc4`='笨蛋！你这个不知道天高地厚的家伙。闭嘴！', `MaleText_loc5`='蠢蛋!你是一個在你無法理解的世界裡玩的孩子。不要再講話了，$n!', `MaleText_loc7`='¡Idiota! Eres como un niño jugando en un mundo que se escapa a tu comprensión. ¡No hables más!' WHERE `ID`=16858;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 무기는 나에게 아무런 위협이 되지 못한다는 걸 모르느냐! 불쌍한 녀석!', `MaleText_loc4`='刀剑无用，$n！投降吧！', `MaleText_loc5`='你的武器對我沒有用，$n! 發發慈悲吧!', `MaleText_loc7`='¡Tus armas no sirven de nada contra mí! ¡Claudica!' WHERE `ID`=16859;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 기술에 자신이 있나? 놀라운 해답이 나올 것이니 잘 생각해 봐라.', `MaleText_loc4`='你对你的技术有信心吗？想清楚，也许答案会让你吃惊。', `MaleText_loc5`='你對你的技能有信心?仔細想想，$n。答案可能會讓你吃驚。', `MaleText_loc7`='¿Confías en tu habilidad? Piénsalo bien. La respuesta puede sorprenderte.' WHERE `ID`=16860;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리의 지도자를 실망시켜서는 안 된다! 캘타스 님이 우리를 구원할 것이다!', `FemaleText_loc4`='我们不能让领袖失望！凯尔萨斯会拯救我们！', `FemaleText_loc5`='我們不能讓領導者失望!凱爾薩斯會救贖我們!', `FemaleText_loc7`='¡No podemos fallar a nuestro líder! ¡Kael''Thas nos redimirá!' WHERE `ID`=16861;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이... 얼마나 수치스러운 일인가!', `MaleText_loc4`='真……丢人。', `MaleText_loc5`='真是...遺憾。', `MaleText_loc7`='Qué vergüenza...' WHERE `ID`=16862;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하인들을 괴롭히는 게 훨씬 더 재밌을 것 같군.', `MaleText_loc4`='跟苦工打交道都比这有趣！', `MaleText_loc5`='我覺得折磨苦工比較有趣!', `MaleText_loc7`='¡Lo pasaba mejor torturando a los peones!' WHERE `ID`=16863;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벌써부터 지겨워지는군.', `MaleText_loc4`='我已经有些厌倦了！', `MaleText_loc5`='我已經很無聊了!', `MaleText_loc7`='¡Ya estoy aburrido!' WHERE `ID`=16864;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 졌다!', `MaleText_loc4`='你败了。', `MaleText_loc5`='你輸了。', `MaleText_loc7`='Perdiste.' WHERE `ID`=16865;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='순순히 죽어라!', `MaleText_loc4`='啊，死吧！', `MaleText_loc5`='喔，受死吧!', `MaleText_loc7`='¡Vamos, muérete ya!' WHERE `ID`=16866;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='''황천의 폭풍''은 예전에는 이렇지 않았답니다.$B$B지금도 파괴되고 있는 이 땅을 파랄론의 초원이라고 이라고 부르던 시절이 있었지요. 하지만 악마에게 점령당한 후 아름다운 시절은 거의 사라지고 없답니다.', `MaleText_loc4`='“虚空风暴”并非一直是现在这个样子。$B$B以前这块破碎的大陆叫做法兰伦平原，但是现在剩下来的只是很少一部分……', `MaleText_loc5`='''虛空風暴''不是永遠如你現在所看見的一樣。$B$B曾幾何時這塊被踐踏的土地被稱為法拉隆平原。那些原有的面目現在卻已面目全非。', `MaleText_loc7`='''La Tormenta Abisal'' no ha sido siempre como lo que ves ahora.$B$BHubo un tiempo cuando esta tierra destrozada se conocía con el nombre de las Llanuras de Farahlon. Muy poco de lo que quedaba de esos días ha sobrevivido al mal que se ha instalado aquí.' WHERE `ID`=16867;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='공격을 멈추시오! 이건 변장일 뿐이오. 난 샤트라스 외부의 고난의 거리 연합 밑에서 일하는 비밀요원이요.$B$B당신의 도움이 필요하오!', `FemaleText_loc4`='$C，不要打了，这只是个伪装！我是沙塔斯城贫民窟的间谍。$B$B我希望你是来这里帮我的！', `FemaleText_loc5`='$C，停止你的攻擊，這只是一個偽裝!我在撒塔斯城外為陰鬱城聯盟工作的一個間諜。$B$B我希望你在這裡能幫助我!', `FemaleText_loc7`='¡$C, no ataques! Es solo un disfraz. Soy una espía que trabaja para la coalición del Bajo Arrabal fuera de la Ciudad de Shattrath.$B$B¡Espero que estés aquí para ayudar!' WHERE `ID`=16868;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대마법사 바르고스 님께서는 제게 자신의 지팡이를 맡기면서 블러드 엘프의 공격을 피해 보랏빛 탑에서 달아나라고 하셨습니다. 저는 그분께서 말씀하신 대로 알클론의 오래된 드레나이 정착지에 피신하려고 했었지요.$B$B하지만 그것도 잠시뿐이었습니다. 저는 불타는 군단의 선발대와 마주쳤답니다. 악마들에게 지팡이를 뺏겼지만 가까스로 도망쳐 목숨을 건질 수 있었지요.$B$B주인님은 아직 이 사실을 모르고 계시지만 저는 아직도 수치심에서 벗어나지 못하고 있습니다.', `MaleText_loc4`='在血精灵攻打紫罗兰之塔时，大法师瓦格斯让我逃出了那里，并把他的法杖托付给了我。我按照他的指示前往阿尔科隆，希望能在那处古老的德莱尼人的殖民地避难。$B$B然而，那里情况反而更糟，我来到了燃烧军团力量的风口浪尖。恶魔们把法杖夺走了，不过幸运的是，我留住了性命。$B$B尽管老师还不知道我的失败，但这仍然让我觉得非常羞愧。', `MaleText_loc5`='大法師瓦戈斯在告知我如何從血精靈對紫羅蘭之塔的攻擊中逃離後將他的法杖委託於我。我按他所告訴我的去做，希望能在阿克隆的舊德萊尼殖民地裡避難。$B$B沒有暫緩。我已經一直走進燃燒軍團部隊的前方。惡魔從我那兒搶走法杖，但是我都幸運的逃離。$B$B雖然我的主人對我的失敗一無所知，但它仍然使我羞愧。', `MaleText_loc7`='El archimago Vargoth me confió su bastón cuando me apresuró a huir del ataque de los elfos de sangre a la Torre Violeta. Hice lo que me pidió, esperando poder refugiarme en el viejo asentamiento draenei de Arklon.$B$BPero no fue así. Había dado de pleno con una fuerza de la Legión Ardiente. Los demonios me robaron el bastón, aunque conseguí escapar con vida.$B$BAunque mi maestro nada sabe de mi fracaso, sigue siendo un motivo de gran vergüenza para mí.' WHERE `ID`=16869;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='실례입니다만 아달이 우리를 여기에 파견한 목적은 캘타스의 행동을 조사하는 것이지 전면 공격을 하려는 것이 아닙니다.', `FemaleText_loc4`='恕我直言，阿达尔派我来这里是为了调查凯尔萨斯的行动，而不是发动一次全力进攻。', `FemaleText_loc5`='我們固然尊重你方意見，阿達歐派我們來這裡調查凱爾薩斯的活動，而不是要發起一次大規模攻擊。', `FemaleText_loc7`='Con todo el respeto, A''dal nos envió aquí para investigar las actividades de Kael, no para organizar un ataque a gran escala.' WHERE `ID`=16870;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 불안정합니다!', `MaleText_loc4`='%s变得不稳定了！', `MaleText_loc5`='%s不太穩定!', `MaleText_loc7`='¡%s está inestable!', `FemaleText_loc1`='%s|1이;가; 불안정합니다!', `FemaleText_loc4`='%s变得不稳定了！', `FemaleText_loc5`='%s不太穩定!', `FemaleText_loc7`='¡%s está inestable!' WHERE `ID`=16871;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이보시오, 고귀하신 드레나이 친구. 우리끼리 폭풍우 요새에 쳐들어가자는 소리가 아니오. 하지만 기회가 오면 바로 차지해야 하는 것이 아니오?', `MaleText_loc4`='你瞧，甜心。我们没有人想要直接进攻风暴要塞，但要是机会就在眼前，为何不去拿下呢？', `MaleText_loc5`='甜心，看。沒有人在談論關於我們自己猛攻風暴要塞的事，但是當我們看到機會時，我們就必須行動。', `MaleText_loc7`='Mira, cariño. Nadie está diciendo que ataquemos El Castillo de la Tempestad solos, pero cuando veamos una oportunidad, tenemos que aprovecharnos.' WHERE `ID`=16872;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='입 다물지 못하겠소, 파렴치한 같으니! 빛의 여사제님께 무례한 말투를 삼가도록 하시오!', `MaleText_loc4`='闭嘴，你这混蛋！不要用那种语调和圣光的女祭司说话！', `MaleText_loc5`='無賴，保持沉默!不要膽敢對一名聖光的女牧師使用那種語調!', `MaleText_loc7`='¡Cuidado con lo que dices! ¡No te atrevas a usar ese tono con una sacerdotisa de la Luz!' WHERE `ID`=16873;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='흥, 여긴 바보들 천지군요!', `FemaleText_loc4`='我身边这些家伙都是白痴！', `FemaleText_loc5`='我被白痴包圍著!', `FemaleText_loc7`='¡Estoy rodeada de estúpidos!' WHERE `ID`=16874;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 탈라시안어에 능통하다는 걸 알면 라린나님께서 즐거우시겠군요. 지금하신 답례 말씀에 담긴 호의는 잊지 않겠습니다.', `FemaleText_loc4`='魔导师会很高兴知道我对萨拉斯语很熟悉的。别摆出一副谦恭的模样，我不吃你这套。', `FemaleText_loc5`='博學者將會很高興知道我的薩拉斯語很流利。你的好意我心領了。', `FemaleText_loc7`='La magistrix se alegrará de ver que hablo bien thalassiano. Me halaga tu cortesía.' WHERE `ID`=16875;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다시 본론으로 돌아가서... 우리는 마나괴철로에 주의를 기울여 대처해야 합니다. 적들이 어떻게 그리고 왜 그것을 사용하는지 알아내야 하는 것입니다.', `FemaleText_loc4`='话过三句必跑题……我们应当把注意力放在这些法力熔炉上。我们需要知道敌人正在用它们做什么，以及为什么要这么做。', `FemaleText_loc5`='回到正題...我們應該把注意力集中於這些法力熔爐。我們需要知道敵人利用它們來做甚麼和為什麼。', `FemaleText_loc7`='Y, volviendo al tema... deberíamos centrar nuestra atención en esas Forjas de Maná. Tenemos que descubrir lo que va a hacer el enemigo y por qué.' WHERE `ID`=16876;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 환자가 있습니다!', `MaleText_loc4`='这里需要治疗！', `MaleText_loc5`='這裡需要治療!', `MaleText_loc7`='¡Necesitamos curación por aquí!', `FemaleText_loc1`='여기 환자가 있습니다!', `FemaleText_loc4`='这里需要治疗！', `FemaleText_loc5`='這裡需要治療!', `FemaleText_loc7`='¡Necesitamos curación por aquí!' WHERE `ID`=16877;
