UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리가 분명히 알려 줬을 텐데요! 우리 대부분이 캘타스의 신임을 받던 추종자들이라는 사실을 잊은 겁니까?', `FemaleText_loc4`='我们是非常开诚布公的！你忘了我们中的许多人都曾经是凯尔萨斯最信任的手下吗？', `FemaleText_loc5`='我們已經告訴你們所需要知道的全部!你忘記我們之中有許多人過去曾是凱爾薩斯所深信的跟隨者嗎?', `FemaleText_loc7`='¡Ya te hemos dicho todo lo que hay que saber! ¿Olvidas que muchos de nosotros solíamos ser seguidores de Kael''thas?' WHERE `ID`=16883;
