UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신도 이것만은 인정해야 하오. 당신이 변절자들로부터 얻은 정보는 오래된 것이고 확실하지도 않소이다. 우리는 치밀하게 계산된 전술을 바탕으로 마나괴철로를 공격하여 최대한 많은 정보를 캐내야 하오.', `MaleText_loc4`='连你都必须承认你从背叛者那得来的信息是过时的，而且是不可靠的。我们应该有计划地进攻这些法力熔炉，并尽可能收集一切情报。', `MaleText_loc5`='連你都必須承認來自背叛者的訊息過時且不可靠。讓我們對這些法力熔爐進行精密的攻擊並蒐集任何我們所能獲得的資訊。', `MaleText_loc7`='Incluso tú tienes que admitir que tu información sobre los desertores no está actualizada y es poco fidedigna. Hagamos ataques calculados a esas Forjas de Maná y reunamos toda la información que podamos.' WHERE `ID`=16890;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 저 친구에게서 뭔가 있어 보이는 작전이 나오는군!', `MaleText_loc4`='老大终于发话了！', `MaleText_loc5`='大傢伙終於開始行動了!', `MaleText_loc7`='¡Por fin el chico grande habla de acción!' WHERE `ID`=16891;
