UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소용돌이가 몰아치는 걸 보십시오. 이리 와서 앉아 편히 쉬십시오. 이곳에서 휴식의 대가는 당신이 쉽게 제공할 수 있는 겸손함 뿐이랍니다.', `MaleText_loc4`='好吧，看看虚空之风把谁吹来了。进来，坐下，休息一会。很便宜，你完全付得起。', `MaleText_loc5`='很好。看看虛空之風掃了什麼進來。進來，坐下，好好的休息一下。費用是適當的;你肯定能支付得起。', `MaleText_loc7`='Vaya. Mira qué han traído los vientos de la nada. Entra, siéntate y descansa. no cobramos mucho; seguro que puedes permitírtelo.', `FemaleText_loc1`='소용돌이가 몰아치는 걸 보십시오. 이리 와서 앉아 편히 쉬십시오. 이곳에서 휴식의 대가는 당신이 쉽게 제공할 수 있는 겸손함 뿐이랍니다.', `FemaleText_loc4`='好吧，看看虚空之风把谁吹来了。进来，坐下，休息一会。很便宜，你完全付得起。', `FemaleText_loc5`='很好。看看虛空之風掃了什麼進來。進來，坐下，好好的休息一下。費用是適當的;你肯定能支付得起。', `FemaleText_loc7`='Vaya. Mira qué han traído los vientos de la nada. Entra, siéntate y descansa. no cobramos mucho; seguro que puedes permitírtelo.' WHERE `ID`=16894;
