UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다... 네 잘못이야!', `MaleText_loc4`='都是……你的错！', `MaleText_loc5`='這一切...都是你的錯!', `MaleText_loc7`='Todo esto es... ¡por tu culpa!' WHERE `ID`=16924;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가... 정말... 미워.', `MaleText_loc4`='我……恨……你。', `MaleText_loc5`='我...恨...你。', `MaleText_loc7`='Te... o... dio.' WHERE `ID`=16925;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='휴! 내 행운의 모자가 여기 있었네. 사방을 뒤져도 없더니만.', `MaleText_loc4`='哟！那是我的幸运帽。我一直在到处找它。', `MaleText_loc5`='呼!我的幸運帽在這。我到處在找它。', `MaleText_loc7`='¡Uf! Aquí está mi sombrero de la suerte. Lo había buscado por todas partes.' WHERE `ID`=16926;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='망토 없이 외출할 수는 없지. 이 안에 망토가 있으면 좋겠어...', `MaleText_loc4`='我不能不穿披风出去。我希望它在这里……', `MaleText_loc5`='我不可能不穿我的披風就出門。我希望它在這裡...', `MaleText_loc7`='No puedo seguir sin mi capa. Espero que esté aquí...' WHERE `ID`=16927;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<용기가 있다면 계속 읽어보십시오...>', `MaleText_loc4`='<继续读，如果你敢的话……>', `MaleText_loc5`='<如果你敢，就繼續讀...>', `MaleText_loc7`='<Sigue leyendo, si te atreves...>', `FemaleText_loc1`='<용기가 있다면 계속 읽어보십시오...>', `FemaleText_loc4`='<继续读，如果你敢的话……>', `FemaleText_loc5`='<如果你敢，就繼續讀...>', `FemaleText_loc7`='<Sigue leyendo, si te atreves...>' WHERE `ID`=16928;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 있었군! 마지막에 확인할 때만 해도 분명 여기 없었는데...', `MaleText_loc4`='在这里！我发誓我上次没有把它放在这里……', `MaleText_loc5`='在這裡!我發誓我上次看的時候它不在這裡...', `MaleText_loc7`='¡Aquí está! Juraría que no estaba aquí la última vez que miré.' WHERE `ID`=16929;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혼돈을 위해 존재하는 그것의 아주 작은 속삭임은 온 세상에 파멸을 불러왔습니다!$B$B그럼에도 아무것도 개의치 않는 이 존재를 숭배하려는 자들이 있었으며, 이 존재를 자기 마음대로 조종하려는 미치광이들마저 나타났습니다.', `MaleText_loc4`='摩摩尔只为混乱而生，它最轻微的低语就意味着诸界的毁灭！$B$B尽管如此，这个冥顽的生物却不乏崇拜者。更荒诞的是，竟然有愚蠢的狂徒企图控制它！', `MaleText_loc5`='只為混亂存在，它輕微的低語意味著全世界的毀滅!$B$B但是，仍有人會去崇拜這無腦的生物。甚至有更加瘋狂的人想要控制它。', `MaleText_loc7`='Existía solo para el caos. ¡Su más leve susurro significaba la destrucción de mundos enteros!$B$BY, aun así, había quienes intentaban adorar a este ser sin conciencia. Había quienes estaban más locos y se atrevían a pensar en controlarlo.' WHERE `ID`=16930;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검을 두고 나가다니 제정신이 아닌가 봅니다. 그런데 제가 검이 여기 있는 것을 봤다면 그냥 놔두고 갔을 리는 없는데...', `MaleText_loc4`='我不知道我在想什么，竟然没拿剑就出去了。如果我看到它在这里，我就会带上它了……', `MaleText_loc5`='我不知道我在想什麼，沒帶我的劍就出去了。如果我有看到它在這裡就會帶著它了...', `MaleText_loc7`='No sé en qué estaba pensando. Mira que salir sin mi espada... Me la habría puesto si la hubiera visto aquí...' WHERE `ID`=16931;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 침대에서 재미있는 얘기를 읽어야 잠이 옵니다. 이제 편히 잠들 수 있겠네요.', `FemaleText_loc4`='没有一个好的睡前故事，我就睡不着。现在我肯定可以睡个好觉了。', `FemaleText_loc5`='沒有一個好聽的床邊故事我沒辦法睡。現在我可以好好休息了。', `FemaleText_loc7`='No puedo dormir si no me cuentan un buen cuento. Ahora, seguro que duermo bien.' WHERE `ID`=16932;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아제로스의 선량한 시민들이여, 싸우시오. 그리고 용기를 내시오! 당신의 동족이 이 지옥의 문을 돌격하여 용감하게 전투를 마치도록 저 불타는 군단에게 몸을 던질 것이오. 성스러운 빛이 당신을 지키기를!', `MaleText_loc4`='战斗吧，艾泽拉斯的勇士们，勇敢地战斗吧！你们的同胞会冲入这座地狱般的传送门，并很快像你们一样勇敢地对抗这些恶魔。圣光保佑你们！', `MaleText_loc5`='艾澤拉斯的善良居民，繼續戰鬥。並且有信心!你的手足們很快就會到來，並且也會如同你一般的與惡魔們英勇作戰。願聖光保佑你!', `MaleText_loc7`='Luchen juntos, pueblos de Azeroth. ¡Y no pierdan esperanza! Sus hermanos acuden corriendo a este portal demoniaco y pronto se enfrentarán a los demonios con tanto valor como ustedes. ¡Que la Luz los proteja!', `FemaleText_loc1`='아제로스의 선량한 시민들이여, 싸우시오. 그리고 용기를 내시오! 당신의 동족이 이 지옥의 문을 돌격하여 용감하게 전투를 마치도록 저 불타는 군단에게 몸을 던질 것이오. 성스러운 빛이 당신을 지키기를!', `FemaleText_loc4`='战斗吧，艾泽拉斯的勇士们，勇敢地战斗吧！你们的同胞会冲入这座地狱般的传送门，并很快像你们一样勇敢地对抗这些恶魔。圣光保佑你们！', `FemaleText_loc5`='艾澤拉斯的善良居民，繼續戰鬥。並且有信心!你的手足們很快就會到來，並且也會如同你一般的與惡魔們英勇作戰。願聖光保佑你!', `FemaleText_loc7`='Luchen juntos, pueblos de Azeroth. ¡Y no pierdan esperanza! Sus hermanos acuden corriendo a este portal demoniaco y pronto se enfrentarán a los demonios con tanto valor como ustedes. ¡Que la Luz los proteja!' WHERE `ID`=16933;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은빛 여명회여! 우리가 지원하러 간다! 형제자매들이여, 싸움을 멈추지 마라! 이 고독한 싸움은 오래가지 않을 것이다!', `MaleText_loc4`='银色黎明！我们需要召集更多的援手！继续战斗，兄弟姐妹们！你们不是孤军奋战！', `MaleText_loc5`='銀色黎明!我們去聚集更多的幫助!繼續戰鬥，兄弟和姐妹。很快的你將不會是獨自作戰!', `MaleText_loc7`='¡El Alba Argenta! ¡Vamos a por ayuda! Luchad, hermanos y hermanas. ¡Y sabed que no lucharéis solos!' WHERE `ID`=16934;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형제들이여, 전우들이여! 이곳에 호드의 힘이 필요하다! 용맹스러운 사냥꾼들이여, 정신을 무장하라! 어둠의 문에서 기어나온 악마들에게 무릎을 꿇을 수는 없다!', `MaleText_loc4`='我的兄弟们，我的战友们！我必须去寻找部落的帮助，指引他们来到这里增援！勇敢的猎人们，顽强地战斗下去！不要被那些从黑暗之门涌出的恶魔击败！', `MaleText_loc5`='我的手足們，戰友們!我必須去尋找部落的力量並且把他們引導到這裡!勇敢的獵人，保持你強烈的精神!不要畏懼入口大量出來的惡魔!', `MaleText_loc7`='¡Hermanos de guerra! Voy a buscar a las fuerzas de la Horda para que acudan aquí. ¡No perdáis el espíritu de la lucha, valientes cazadores! ¡No caigáis ante los monstruos que escupe el portal!' WHERE `ID`=16935;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 책의 낡은 페이지들은 마법의 힘으로 필멸의 존재들이 감당조차 할 수 없는 참혹한 부분은 넘기고 안전한 내용이 있는 페이지로 당신을 안내합니다.$B$B어떻게 보면 옳고 또 어떻게 보면 아주 그릇된 느낌을 주는 페이지가 열립니다.', `MaleText_loc4`='散发着霉味的书页似乎着魔一般翻动起来，你注意到法典中某个特殊的章节，上面的文字渗透出凡人难以察觉的恐怖气息。$B$B书页停止翻动，仿佛在指引你阅读摊开在你面前的这一页。你浏览着其中的内容，却发现它记载的是一段禁断的历史。', `MaleText_loc5`='發黴的法典書頁神奇地自動翻頁，將你的注意力引領到凡人的眼睛根本不該看到的恐怖章節。$B$B書本翻到了不知為何使人感覺是「正確」，但其實卻是錯得離譜的一頁。', `MaleText_loc7`='Las mohosas páginas del códice parecen girar por arte de magia y centran tu atención en un capítulo concreto sobre horrores pasados que ningún ojo mortal debería percibir.$B$BEl libro se abre en una página que, de alguna forma, parece ser la ''correcta'', aunque al mismo tiempo la equivocada.' WHERE `ID`=16936;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘 있는 자들조차 그 존재의 말이 두려워 벌벌 떨었습니다.$B$B그럼에도 자기 멋대로 종교를 만들어 신봉하던 위선자들과 허풍선이들은 자신들의 ''신''을 통제하기 위해 발버둥을 쳤습니다. 이 어리석은 자들에게 아무 관심도 없고 어떠한 배려도 없었던 울림은 하품 한번으로 그들을 영원히 소멸시켰습니다.$B$B그러나 그중 한 명이 살아남아 이 세상에 울림을 소환하는 방법을 알아냈습니다.', `MaleText_loc4`='瞧，所谓的强者战栗着跪拜在它面前，惟恐摩摩尔催动音波，令他们粉身碎骨。$B$B那些狂妄的家伙则假借崇拜之名组成了宗教组织，暗地里策划着如何控制他们的“神”，却不知道他们的野心注定会落空。摩摩尔对它的崇拜者毫不在意，不经意间打了个哈欠，他们就灰飞烟灭了。$B$B只有一人得以幸存，虽然这场浩劫令他神志有些错乱，但他却偶然发现了将摩摩尔召唤到这个世界的方法。', `MaleText_loc5`='看啊，勇者在它的跟前顫抖，害怕它會對其出聲。$B$B但是這些騙子，這些崇拜不存在之偽教的假信徒，依舊罔顧現實，企圖要控制他們的「神」。然而，莫爾墨只是毫不在乎地 - 或可能甚至根本沒注意到他們 - 打了個呵欠，他們就這樣灰飛湮滅了。$B$B但不知怎麼的，有個人倖存了下來，而且他的瘋狂同時也找到了使莫爾墨進入這世界的途徑。', `MaleText_loc7`='Y cómo los poderosos caían temblando a sus pies, temerosos de que pudiera dirigir sus palabras hacia ellos.$B$BY, aun así, esos charlatanes, esos falsos adoradores de una religión no existente, pretendían negarse a lo inevitable, en un vano intento de controlar a su ''dios''. Indiferente y, probablemente sin darse cuenta de su presencia, Murmullo bostezó, y ellos cayeron en la inconsciencia.$B$BPero, de alguna forma, uno de ellos consiguió sobrevivir y, en su locura, encontró la forma de traer a Murmullo al mundo.' WHERE `ID`=16937;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 그 누구에게도 비교할 수 없는 마법과 어둠의 지식을 갖춘 그 생존자는 이 세상에 알려지지 않은 존재들의 영혼을 사냥하여 자신의 소환술을 강화했습니다.$B$B그러나 그와 공모자들이 울림을 소환하기 위해 개발한 영혼의 장치는 모든 문명을 집어삼키고 말았습니다.', `MaleText_loc4`='这位侥幸逃生的凡人在黑暗法术上的造诣无人能及。他设计出某种灵魂装置，利用它们捕获灵魂来强化召唤仪式。$B$B这位魔法师和他的同谋们为了将摩摩尔召唤到这个世界，不惜灭绝了数个氏族文明，夺取了他们的灵魂来推进仪式的进程。', `MaleText_loc5`='有一個對於秘法和黑暗的知識的狂熱是無人所能超過的凡人，他想出一種方法透過捕捉和使用未知的靈魂來強化他的召喚。$B$B整個文明世界因為他的靈魂設備成為儀式的燃料而陷入絕盡，透過他和他的陰謀者們莫爾墨將被召喚到他們的世界。', `MaleText_loc7`='Un mortal con un increíble conocimiento arcano y oscuro que nadie podía superar; desarrolló un método para aumentar su invocación mediante la captura y utilización de almas.$B$BCivilizaciones enteras fueron exterminadas mediante este dispositivo de almas para alimentar el ritual mediante el que él y sus conspiradores traerían a Murmullo a su mundo.' WHERE `ID`=16938;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 결국 그들은 울림을 소환하는 데 성공했습니다.$B$B그들은 수많은 영혼을 희생시켜 강화한 속박과 침묵 마법을 사용했지만 울림을 마음대로 부리기는커녕 조금도 통제할 수 없었습니다.$B$B그들은 여러 가지 전략을 세웠지만 모두 실패했습니다. 그 과정에서 소환 의식의 힘이 약해졌고 결국 삽시간에 울림에게 걸린 봉인이 풀렸습니다.$B$B울림에게는 그 짧은 순간이면 충분했습니다.', `MaleText_loc4`='他们果真召唤出了摩摩尔。$B$B魔法师企图利用强大的法术来抑制摩摩尔之音，并不断地夺取灵魂来维系法术的有效性。尽管如此，他们依然无法控制这个野蛮的生物，无法令它屈从于他们的意志。$B$B他们想出了各种方法想要制服摩摩尔，却无一例外地失败了。在试验这些方法的过程中，他们弱化了仪式的效果，意外地使摩摩尔看到了一丝自由的曙光。$B$B而这一丝曙光对摩摩尔来说已经足够了。', `MaleText_loc5`='而他們將莫爾墨召喚前來。$B$B使用強大的封鎖魔法和沉默魔法，並定期的餵食他們靈魂。然而他們仍然無法控制那野獸，不能使它屈服於他們的意愿。$B$B這些凡人開始想出不同的策略，而他們全部都一個接一個的失敗。也因為不斷的嘗試，儀式的力量因此減弱，意外的使莫爾墨獲得輕微的一點點自由。$B$B而那就是它所需要的全部。', `MaleText_loc7`='Y sí, invocaron a Murmullo.$B$BSe utilizaron poderosas magias para contenerle y silenciarle, gracias al constante goteo de almas de las que se alimentaban. Y, ni aun así, fueron capaces de controlar a la bestia, ni de someterla a su voluntad.$B$BEstos mortales comenzaron a pensar en diferentes estrategias que, una tras una, fracasaron. Y, al hacerlo, debilitaron los rituales, dando a Murmullo, sin querer, un atisbo de libertad.$B$BEra todo lo que necesitaba.' WHERE `ID`=16939;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세상을 파괴한 그 대재앙 이후 남은 것은 이 책뿐입니다. 무한한 힘을 가진 우주의 존재를 지배하려던 어리석은 자들...$B$B이 책을 얻은 당신도 그들과 같은 전례를 반복할 것입니까?$B$B이 부정한 책에 조심스럽게 언급된 울림 또는 또 다른 강력한 존재를 소환할 방법이라도 고안해 냈습니까?$B$B두고보면 알겠지요.', `MaleText_loc4`='在以后的那场大灾难中，只有这本法典得以保存下来。那些高傲而愚蠢的凡人妄图控制拥有无上力量的宇宙生物。$B$B而你呢？法典的拥有者，你会做出同样的蠢事吗？$B$B你是否已经想好了召唤摩摩尔的安全之策？这本邪恶的禁断之书还记载着其它神秘的宇宙生物，或许你对它们更感兴趣？$B$B我们等着瞧吧。', `MaleText_loc5`='只有這本書在經歷毀滅他們世界的災變之後仍然倖存。那些想要控制一個具有未知力量的宇宙生命的驕傲和愚蠢的人。$B$B身為法典的持有人，你會作出同樣的事嗎?$B$B你有想出一個萬全的方法來召喚莫爾墨，以及任何在這邪惡的書頁內所隱藏的秘密嗎?$B$B我們拭目以待。', `MaleText_loc7`='Solo este libro sobrevivió a la catástrofe que destruyó el mundo en el que se encontraba. Aquellos hombres orgullosos e inconscientes pensaron que controlaban a un ser cósmico de poder inimaginable.$B$B¿Acaso tú, dueño del códice, eres como ellos?$B$B¿Has tramado algún plan para invocar a Murmullo o a alguna otra entidad de las mencionadas en esas páginas impías?$B$BYa lo veremos.' WHERE `ID`=16940;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여어, 안녕하신가! 새로운 친구를 만나게 되어 반갑군. 이곳에 오는 친구들이 그리 많지 않아서 말이야. 게다가 여기 기술자 친구들은 그리 화술이 뛰어난 친구들이 못 되거든.$B$B52번 구역으로 가는 거 같은데, 맞나?', `MaleText_loc4`='嗨！很高兴可以看到新面孔——我平时没有太多的客人，而且那些技术员也不是那么健谈。$B$B我打赌你是要去52区，我说得没错吧？', `MaleText_loc5`='嘿你!看見一張新面孔真好 - 這裡不常出現參觀者，而那些技師也不是很好的談話對象。$B$B我打賭你是要去52區的路上。對吧?', `MaleText_loc7`='¡Eh! Me alegro de ver caras nuevas. No tengo muchas visitas y los técnicos no son muy habladores.$B$BApuesto a que te diriges al Área 52, ¿verdad?' WHERE `ID`=16941;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고위 식물학자님?', `MaleText_loc4`='高级植物学家？', `MaleText_loc5`='大植物學家?', `MaleText_loc7`='¿Gran botánico?', `FemaleText_loc1`='고위 식물학자님?', `FemaleText_loc4`='高级植物学家？', `FemaleText_loc5`='大植物學家?', `FemaleText_loc7`='¿Gran botánico?' WHERE `ID`=16942;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 한숨을 쉽니다.', `MaleText_loc4`='%s叹了口气。', `MaleText_loc5`='%s嘆了一口氣。', `MaleText_loc7`='%s suspira.', `FemaleText_loc1`='%s|1이;가; 한숨을 쉽니다.', `FemaleText_loc4`='%s叹了口气。', `FemaleText_loc5`='%s嘆了一口氣。', `FemaleText_loc7`='%s suspira.' WHERE `ID`=16944;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='중얼중얼... 화염초 꽃잎... 중얼중얼...', `MaleText_loc4`='嗯……火红色的花瓣……嗯……', `MaleText_loc5`='...咕噥...火焰花瓣...咕噥...', `MaleText_loc7`='Cuchicheos... pétalos de fuego... Cuchicheos...' WHERE `ID`=16945;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='중얼중얼...', `MaleText_loc4`='……咕哝咕哝……', `MaleText_loc5`='...咕噥咕噥...', `MaleText_loc7`='Mmm... Mmm...' WHERE `ID`=16946;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가시 덩굴... 중얼중얼... 아냐!', `MaleText_loc4`='……这上面好多刺……呃……哎唷！', `MaleText_loc5`='...多刺的藤蔓...咕噥...喔!', `MaleText_loc7`='... vides con espinas... murmura... ¡Auuu!' WHERE `ID`=16947;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조합만 제대로 하면...', `MaleText_loc4`='……正确地混合之后，也许……', `MaleText_loc5`='...如果有正確的混合物，或許...', `MaleText_loc7`='... quizás... con la mezcla correcta...' WHERE `ID`=16948;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 뭐야? 그럴 리가 없는데! 누가 이 다리를 세웠지? 아, 우리가 했지.', `MaleText_loc4`='这是什么？这是什么乱七八糟的！到底是谁造了这座桥？哦，我们造的。', `MaleText_loc5`='這是什麼?那不會是正確的!不論如何誰建造了這座橋?噢，是我們做的。', `MaleText_loc7`='¿Qué es eso? ¡No puede ser cierto! ¿Quién construyó este puente? Ah, nosotros.' WHERE `ID`=16949;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 안 돼! 또다시 측정을 해야 한단 말인가?', `MaleText_loc4`='哦，不！这东西需要另一个刻度吗？', `MaleText_loc5`='噢不!這個東西需要在一次的校正嗎?', `MaleText_loc7`='¡Oh, no! ¿Acaso esto necesita OTRA recalibración?' WHERE `ID`=16950;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에테리얼에게 중고 장비를 구입하는 것도 이번이 마지막이다!', `MaleText_loc4`='这是我最后一次从虚灵那里买二手装备！', `MaleText_loc5`='這是最後一次我向以太族買二手設備了!', `MaleText_loc7`='¡Es la última vez que compro material de segunda mano de un etéreo!' WHERE `ID`=16951;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='길 건너에 있는 블러드 엘프들이 내가 첩자라고 오해하지 말아야 할 텐데!', `MaleText_loc4`='希望那些过路的血精灵没有查觉到我正在侦察他们！', `MaleText_loc5`='我希望那些穿過的血精靈們不會認為我正在偵察他們!', `MaleText_loc7`='Espero que esos elfos de sangre no crean que les estoy espiando.' WHERE `ID`=16952;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 맞는다면 시간이 얼마 없잖아! 젠장.', `MaleText_loc4`='如果这是对的，我们没有太多时间了！哦，好吧。', `MaleText_loc5`='如果這是對的，我們時間不多了!喔好吧。', `MaleText_loc7`='Si esto es cierto, no falta mucho. Vaya.' WHERE `ID`=16953;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='행성들이 배열을 갖췄군! 두 번째 달이 그... 그 별자리를 뭐라고 부르더라?', `MaleText_loc4`='行星排成了一列！第二个月亮就在那个……什么位置来着？', `MaleText_loc5`='行星被調整好了!第2個月亮是在房子的...現在那所房子再次叫什麼?', `MaleText_loc7`='¡Los planetas están alineados! La segunda luna está en la casa de... ¿Qué casa era esta?' WHERE `ID`=16954;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 연구 결과를 팔아서 황천 로켓의 좌석을 구입하는 게 현명하겠지. 어서 여길 떠나야 할 것 같은 기분이 드는군!', `MaleText_loc4`='要是我够聪明的话，我早就把这项研究卖了换张火箭飞船的座票。我感觉我们很快就要离开这里了。', `MaleText_loc5`='如果我聰明的話，我會將我的研究賣掉來換取火箭船上的一個位子。我感覺到我們很快的就應該要離開這裡!', `MaleText_loc7`='Si fuera un chico listo, vendería esta investigación a cambio de un asiento en el cohete. Me da la impresión de que vamos a tener que largarnos de aquí muy pronto.' WHERE `ID`=16955;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='믿기 힘든 일이로군! 모든 별들이 아웃랜드를 중심으로 공전하지 않는다는 사실을 발견한 것 같군. 아냐, 그럴 리가 없는데!', `MaleText_loc4`='不可能！我发现所有东西都不围绕外域运转！不，这不可能！', `MaleText_loc5`='難以相信!我想我剛剛發現所有東西沒有圍繞外域軌道運行。不，那怎麼可能!', `MaleText_loc7`='¡Increíble! Creo que acabo de descubrir que no todo orbita alrededor de Terrallende. No... ¡No puede ser!' WHERE `ID`=16956;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 "항공 우주 공학 전문위원단"의 단장을 맡고 있는 퓨즐라지라네. 줄여서 B.O.O.M. 이라 부르지.$B$B시스템은 모두 정상적으로 작동하고 있나?! X-52 황천 로켓은 아직 많은 연구가 필요한 것 같군!$B$B자자, 친구들... 발사 완료까진 할 일이 태산이라네!', `MaleText_loc4`='爆裂推进式多缸火箭航天局——简称为爆缸航天局——的指挥官弗斯拉格随时为你效劳。$B$B所有的系统都运行正常吗？！看上去X-52虚空火箭仍有很多准备工作要做！$B$B加油……我们的时间不多了！', `MaleText_loc5`='火箭主管夫斯拉吉，B.O.O.M.指揮官 - 軌道操控和機械的首腦 - 任你差遣。$B$B所有系統正常嗎?!X-52虛空火箭看起來像仍然需要許多工作!$B$B來吧工人們...火箭倒數的時間從來不在!', `MaleText_loc7`='Jefe de cohetes Fuselaje, comandante de B.U.M.: Baqueteados Ultraorbitales Mecanizados, a tu servicio.$B$B¿Están todos los sistemas en marcha? Parece que el cohete abisal X-52 todavía necesita mucho trabajo.$B$BVamos, chicos... ¡Estamos a menos CERO segundos!' WHERE `ID`=16957;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='알레리아 성채에 오신 것을 환영합니다, $n.', `FemaleText_loc4`='欢迎来到奥蕾莉亚要塞，$n。', `FemaleText_loc5`='歡迎來到艾蘭里堡壘，$n。', `FemaleText_loc7`='$GBienvenido:bienvenida; al Bastión Allerian, $n.' WHERE `ID`=16958;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='로봇을 다루는 건 아주 섬세한 작업이랍니다, 아시겠어요? 괜스레 서둘렀다간 뭐라도 망가뜨리기 십상이죠.$B$B예를 들면 퓨즐라지의 머리라던가!$B$B제 로봇들이 궁금하시다고요? 저는 언제나 Mk를 연구한답니다. Mk. I 호와 Mk. II 호는 전기 두뇌 콘덴서가 망가져서 미치광이처럼 되기 직전에 약 0.5초간 감각을 느꼈지요!$B$B그래서 III 호와 IV 호는 건너뛰고 바로 Mk. V 호에 착수했죠. Mk. V 호는 제 자존심이자 즐거움이라고요!', `FemaleText_loc4`='这是一个细活，你知道吗？做这项工作你不能操之过急，也不能判断错误。$B$B就像弗斯拉格的脑袋一样！$B$B你可能对我的机器人感到疑惑？我一直在研究麦克斯米林I型和麦克斯米林II型的脑容爆炸前所获得的智能！$B$B我决定忽略III型和IV型，直接去研究我为之骄傲和快乐的麦克斯米林V型。', `FemaleText_loc5`='對外來說這可是精緻的成品，你知道嗎?它實在不能趕，否則可能有些東西會被弄壞。$B$B像是夫斯拉吉的頭!$B$B你可能會對我的機器人好奇?我總是在馬克斯一號身上工作，和馬克斯二號在他的大腦電容器爆炸之前的一瞬間獲得知覺然後他就瘋了!$B$B我決定跳過三號和四號，並且直接到馬克斯五號 - 我的驕傲和快樂!', `FemaleText_loc7`='Se trata de un trabajo muy delicado, ¿sabes? No puedo estar sometida a presión, o algo acabará rompiéndose.$B$B¡Como la cabeza de Fuselaje!$B$B¿Te estás preguntando sobre mis robots? Siempre estoy trabajando en el nº I. El nº. II y yo conseguimos la capacidad de sentir durante un milisegundo antes de que su condensador cerebral explotase y se volviese loco.$B$BDecidí saltarme el III y IV, y me fui derecha al nº. V. ¡Mi ojito derecho!' WHERE `ID`=16959;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물건 가격을 매길 때 실수하지 않도록 조심하십시오. 저번에 보석 값을 너무 많이 쳐준 게 있어서 이번 달에 또 그랬다간 게제한테 말하기가 쉽지 않거든요.', `MaleText_loc4`='设法把错误评估控制到最小。我不希望杰赫知道我们这个月又为一批宝石运输多掏了钱。', `MaleText_loc5`='試著將估價錯誤控制到最低限度。我討厭告訴吉札我們這個月在另一筆寶石裝運費用上超支了。', `MaleText_loc7`='Procura no cometer errores en la tasación. No me gustaría tener que decirle a Gezhe que hemos pagado de más por otro cargamento de gemas este mes.' WHERE `ID`=16960;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오라, 형제들이여! 찬란한 나의 능력에 흠뻑 취하라!', `MaleText_loc4`='欢迎你们，我的兄弟们！让我力量的荣光照耀你们！', `MaleText_loc5`='歡迎我的兄弟!在我能量的榮耀中享受吧!', `MaleText_loc7`='¡Bienvenidos hermanos! ¡Deleitaros en la gloria de mi poder!' WHERE `ID`=16961;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 폐허에 가면 조심해야 합니다. 키린 토의 영혼들은 당신을 친구라고 여기지 않을 테니 말입니다.$B$B관리자와 나의 영혼만이 이곳과 깊은 연을 맺어 사후에도 정체성을 유지할 수 있는 것이랍니다.', `MaleText_loc4`='在废墟里面记得小心点，$c。肯瑞托之魂不会把你当作朋友的。$B$B只有我和管理员能与肯瑞瓦鬼魂沟通，即便他们已是魂灵，也会将我们视为朋友。', `MaleText_loc5`='在廢墟裡要小心，$c。你在那裡發現的祈倫托幽靈將不會認得你是一位朋友。$B$B管理者和我是這地方唯一能夠維持我們原本面貌的幽靈。', `MaleText_loc7`='Ten cuidado en las ruinas, $c. Los espíritus del Kirin Tor que encontrarás, no te reconocerán como $gamigo:amiga;.$B$BEl custodio y yo somos los únicos cuyos espíritus mantenían un vínculo tan fuerte con este lugar como para conservar nuestra identidad en la muerte.' WHERE `ID`=16962;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='키린바르 마을은 20년 동안 수많은 오크의 공격을 견뎌냈지만 결국 캘타스의 군대에게 무너졌소이다. 자칭 키린 토의 일원이라던 자가 한 명만 빼고 우리 모두를 살해한 것이오.$B$B캘타스는 살아남은 대마법사 바르고스를 보랏빛 탑에 가두고 키린 토 일원은 아무도 접근할 수 없도록 마법을 걸었소이다.', `MaleText_loc4`='肯瑞瓦在兽人的无数次冲击下生存了20多年，但是它并没有抵挡住凯尔萨斯的进攻。有一个叛徒，一个曾自称为肯瑞托一员的家伙，我们中除了大法师瓦格斯之外的人都被他杀害了。$B$B大法师瓦格斯从那次劫难中幸存了下来，因此凯尔萨斯把他囚禁在紫罗兰之塔内，用一种任何肯瑞托成员都无法通过的魔法屏障封印了紫罗兰之塔。', `MaleText_loc5`='肯瑞瓦在歷經20多年和無數的獸人突擊之後依舊毅立不搖，但它卻抵抗不了凱爾薩斯的部隊。一個曾稱自己為祈倫托成員的人卻謀殺了我們所有人，只留下一個人。$B$B大法師瓦戈斯在攻擊後倖存，所以凱爾薩斯把他囚禁在紫羅蘭之塔內，並用魔法結界來用阻止任何祈倫托成員的進入。', `MaleText_loc7`='Kirin''Var sobrevivió a 20 largos años de incontables asaltos orcos, pero no pudo sobrevivir a las fuerzas de Kael''thas. Un hombre que se hacía llamar miembro del Kirin Tor nos asesinó a todos, menos a uno.$B$BEl archimago Vargoth sobrevivió al ataque, así que Kael''thas le encarceló en la Torre Violeta y protegió la Torre con una magia que prohibía el paso a cualquier miembro del Kirin Tor.' WHERE `ID`=16963;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋았어, Mk. I 호, 이제 됐어. 이제 스위치를 켜볼까...', `FemaleText_loc4`='好吧，麦克斯米林I型，快要开始了。我们打开你的这个开关……', `FemaleText_loc5`='好的，馬克斯一號，這樣應該差不多了。讓我開啟你這裡的開關...', `FemaleText_loc7`='Muy bien, nº. I, con eso servirá. Vamos a toquetear un poco tus botones...' WHERE `ID`=16964;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안 돼! 언제쯤이면 제대로 작동할 거니?!', `FemaleText_loc4`='天哪！我什么时候才能让你运转起来？', `FemaleText_loc5`='喔不!我哪一天才能讓你開始工作?!', `FemaleText_loc7`='¡Oh, no! ¿¿Alguna vez conseguiré que funciones??' WHERE `ID`=16965;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대의 집이라고 생각하고 앉아서 편히 쉬십시오.', `MaleText_loc4`='请坐吧，不要拘束。', `MaleText_loc5`='請坐，請隨意。', `MaleText_loc7`='Siéntate y ponte $gcómodo:cómoda;.', `FemaleText_loc1`='그대의 집이라고 생각하고 앉아서 편히 쉬십시오.', `FemaleText_loc4`='请坐吧，不要拘束。', `FemaleText_loc5`='請坐，請隨意。', `FemaleText_loc7`='Siéntate y ponte $gcómodo:cómoda;.' WHERE `ID`=16966;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여행에 지친 $c님, 여관에 오신 걸 환영합니다. 뭘 도와드릴까요?', `MaleText_loc4`='欢迎来到我的旅店，疲劳的旅者。有什么我可以帮你的吗？', `MaleText_loc5`='歡迎來到我的旅店，疲累的旅人。我能為你做點什麼嗎?', `MaleText_loc7`='Te doy la bienvenida a mi taberna, $gfatigado viajero:fatigada viajera;. ¿En qué puedo ayudarte?', `FemaleText_loc1`='여행에 지친 $c님, 여관에 오신 걸 환영합니다. 뭘 도와드릴까요?', `FemaleText_loc4`='欢迎来到我的旅店，疲劳的旅者。有什么我可以帮你的吗？', `FemaleText_loc5`='歡迎來到我的旅店，疲累的旅人。我能為你做點什麼嗎?', `FemaleText_loc7`='Te doy la bienvenida a mi taberna, $gfatigado viajero:fatigada viajera;. ¿En qué puedo ayudarte?' WHERE `ID`=16967;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 쓰러지기 시작합니다!', `MaleText_loc4`='%s开始瓦解！', `MaleText_loc5`='%s開始崩潰!', `MaleText_loc7`='¡%s comienza a venirse abajo!' WHERE `ID`=16968;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이보시오, 이 지명수배 전단 읽어 봤소?', `MaleText_loc4`='嘿，你看见通缉令上的悬赏了吗？', `MaleText_loc5`='嘿，你看過這張懸賞告示上的賞金了嗎?', `MaleText_loc7`='Eh, ¿has leído lo del botín en este cartel de Se Busca?', `FemaleText_loc1`='이보세요, 이 지명수배 전단 읽어 보았나요?', `FemaleText_loc4`='嘿，你看见通缉令上的悬赏了吗？', `FemaleText_loc5`='嘿，你看過這張懸賞告示上的賞金了嗎?', `FemaleText_loc7`='Eh, ¿has leído lo del botín en este cartel de Se Busca?' WHERE `ID`=16969;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 전단을 보면 소위 모험가라고 하는 자들에게 어떤 녀석들을 처치하고 돌아오면 현상금을 보상으로 지급하겠다고 되어 있소이다. 이게 우리가 하는 일 아니오? 같은 일을 하는데 내가 받는 보수가 너무 적은 거 아니냔 말이오!', `MaleText_loc4`='这个通缉令上写的是，他们会聘请那些所谓的冒险家来猎杀某些东西。我们不就是干这个的吗？我可不觉得我赚得够多了！', `MaleText_loc5`='這張懸賞告示上說他們提供黃金給那些所謂的冒險者來去去殺死某些東西。那不就是我們最拿手的嗎?我認為我的薪水實在太少了!', `MaleText_loc7`='Este cartel de Se Busca dice que están ofreciendo oro a esos supuestos aventureros por matar cosas. ¿No es eso lo que hacemos nosotros? ¡No creo que me estén pagando lo suficiente!', `FemaleText_loc1`='이 전단을 보면 소위 모험가라고 하는 자들에게 어떤 녀석들을 처치하고 돌아오면 현상금을 보상으로 지급하겠다고 되어 있어요. 이게 우리가 하는 일 아니가요? 같은 일을 하는데 내가 받는 보수가 너무 적은 거 아니냔 말입니다!', `FemaleText_loc4`='这个通缉令上写的是，他们会聘请那些所谓的冒险家来猎杀某些东西。我们不就是干这个的吗？我可不觉得我赚得够多了！', `FemaleText_loc5`='這張懸賞告示上說他們提供黃金給那些所謂的冒險者來去去殺死某些東西。那不就是我們最拿手的嗎?我認為我的薪水實在太少了!', `FemaleText_loc7`='Este cartel de Se Busca dice que están ofreciendo oro a esos supuestos aventureros por matar cosas. ¿No es eso lo que hacemos nosotros? ¡No creo que me estén pagando lo suficiente!' WHERE `ID`=16970;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 수배 전단을 보면 해골채찍 독수리의 목에 현상금이 걸려 있소. 내가 그 일을 하는 건 어떻겠소?', `MaleText_loc4`='这个通缉令在悬赏白骨秃鹫。你觉得我应该揭榜吗？', `MaleText_loc5`='這張懸賞告示上對鞭骨者有一筆賞金。你認為我應該做嗎?', `MaleText_loc7`='Este cartel de Se Busca ofrece una recompensa por los Atizahuesos. ¿No crees que yo podría hacerlo?', `FemaleText_loc1`='이 수배 전단을 보면 해골채찍 독수리의 목에 현상금이 걸려 있어요. 내가 그 일을 하는 건 어떻겠어요?', `FemaleText_loc4`='这个通缉令在悬赏白骨秃鹫。你觉得我应该揭榜吗？', `FemaleText_loc5`='這張懸賞告示上對鞭骨者有一筆賞金。你認為我應該做嗎?', `FemaleText_loc7`='Este cartel de Se Busca ofrece una recompensa por los Atizahuesos. ¿No crees que yo podría hacerlo?' WHERE `ID`=16971;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해골 무덤이라니! 현상금이 아무리 두둑해도 해골 무덤에는 절대 갈 수 없소!', `MaleText_loc4`='白骨荒野！哪怕你给我再多报酬，我也不想去那个鬼地方！', `MaleText_loc5`='白骨荒野!我不管報酬是什麼，我絕對不會進去白骨荒野!', `MaleText_loc7`='¡El Vertedero de Huesos! No quiero saber lo que me dan de recompensa. ¡Yo no voy al Vertedero de Huesos!', `FemaleText_loc1`='해골 무덤이라뇨! 현상금이 아무리 두둑해도 해골 무덤에는 절대 갈 수 없습니다!', `FemaleText_loc4`='白骨荒野！哪怕你给我再多报酬，我也不想去那个鬼地方！', `FemaleText_loc5`='白骨荒野!我不管報酬是什麼，我絕對不會進去白骨荒野!', `FemaleText_loc7`='¡El Vertedero de Huesos! No quiero saber lo que me dan de recompensa. ¡Yo no voy al Vertedero de Huesos!' WHERE `ID`=16972;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 황천에서 하인을 소환합니다!', `MaleText_loc4`='%s从虚空中召唤出他的仆人！', `MaleText_loc5`='%s從虛空召喚他的僕人!', `MaleText_loc7`='¡%s invoca a sus sirvientes de la nada!' WHERE `ID`=16973;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='근무가 끝나면 현상금 사냥 한번 해볼 생각 없소?', `MaleText_loc4`='不如下班后去瞧瞧那份悬赏令？奖励不菲呀。', `MaleText_loc5`='你想要在輪班結束之後，去抓拿這張懸賞告示上的所懸賞的通緝犯嗎?', `MaleText_loc7`='¿Quieres ir a por la recompensa de este cartel de Se Busca cuando acabemos el turno?', `FemaleText_loc1`='근무가 끝나면 현상금 사냥 한번 해볼 생각 없나요?', `FemaleText_loc4`='不如下班后去瞧瞧那份悬赏令？奖励不菲呀。', `FemaleText_loc5`='你想要在輪班結束之後，去抓拿這張懸賞告示上的所懸賞的通緝犯嗎?', `FemaleText_loc7`='¿Quieres ir a por la recompensa de este cartel de Se Busca cuando acabemos el turno?' WHERE `ID`=16974;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='글쎄... 뭐, 하고 싶은 대로 하시오.', `MaleText_loc4`='不知道，我也不关心。', `MaleText_loc5`='幫迷失者找到方向', `MaleText_loc7`='Ni lo sé ni me importa.', `FemaleText_loc1`='글쎄... 뭐, 하고 싶은 대로 하세요.', `FemaleText_loc4`='不知道，我也不关心。', `FemaleText_loc5`='幫迷失者找到方向', `FemaleText_loc7`='Ni lo sé ni me importa.' WHERE `ID`=16975;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 오늘 하루종일 떠들던 현상 수배 전단이 저거요?', `MaleText_loc4`='你除了整天念叨那些悬赏令，还有点别的事情可做么？', `MaleText_loc5`='你今天要講的就只有那張懸賞告示的事嗎?', `MaleText_loc7`='¿Te vas a pasar todo el día hablando de ese cartel de Se Busca?', `FemaleText_loc1`='당신이 오늘 하루종일 떠들던 현상 수배 전단이 저건가요?', `FemaleText_loc4`='你除了整天念叨那些悬赏令，还有点别的事情可做么？', `FemaleText_loc5`='你今天要講的就只有那張懸賞告示的事嗎?', `FemaleText_loc7`='¿Te vas a pasar todo el día hablando de ese cartel de Se Busca?' WHERE `ID`=16976;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='근무가 끝나면 바로 현상금 사냥을 시작할 생각이오.', `MaleText_loc4`='下班后我就去看看那份悬赏令。', `MaleText_loc5`='這次輪班後我就要去深入調查那份賞金。', `MaleText_loc7`='Voy a ir a por esa recompensa cuando acabe el turno.', `FemaleText_loc1`='근무가 끝나면 바로 현상금 사냥을 시작할 생각입니다.', `FemaleText_loc4`='下班后我就去看看那份悬赏令。', `FemaleText_loc5`='這次輪班後我就要去深入調查那份賞金。', `FemaleText_loc7`='Voy a ir a por esa recompensa cuando acabe el turno.' WHERE `ID`=16977;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해골 무덤의 해골채찍 독수리들은 가볍게 볼 상대들이 아니오. 녀석들에게 무서운 질병이 있다는 소리도 들었소이다!', `MaleText_loc4`='白骨秃鹫可不是好对付的。我听说它们都携带着污秽！', `MaleText_loc5`='白骨荒野的鞭骨者可不是開玩笑的。我聽說他們會傳播疾病!', `MaleText_loc7`='Los Atizahuesos no son un enemigo cualquiera. ¡He oído que te pueden contagiar enfermedades!', `FemaleText_loc1`='해골 무덤의 해골채찍 독수리들은 가볍게 볼 상대들이 아닙니다. 녀석들에게 무서운 질병이 있다는 소리도 들었답니다!', `FemaleText_loc4`='白骨秃鹫可不是好对付的。我听说它们都携带着污秽！', `FemaleText_loc5`='白骨荒野的鞭骨者可不是開玩笑的。我聽說他們會傳播疾病!', `FemaleText_loc7`='Los Atizahuesos no son un enemigo cualquiera. ¡He oído que te pueden contagiar enfermedades!' WHERE `ID`=16978;
