UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발포하라고. 밧줄을 잘라.', `MaleText_loc4`='我说，我们发射吧。割断绳子。', `MaleText_loc5`='我說我們向它開火。切斷繩索。', `MaleText_loc7`='Adelante. Corta la cuerda.', `FemaleText_loc1`='발포하라고. 밧줄을 잘라.', `FemaleText_loc4`='我说，我们发射吧。割断绳子。', `FemaleText_loc5`='我說我們向它開火。切斷繩索。', `FemaleText_loc7`='Adelante. Corta la cuerda.' WHERE `ID`=16981;
