UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 잘라. 칼이 있는 건 너잖아.', `MaleText_loc4`='你割绳子。你有小刀。', `MaleText_loc5`='切斷繩索。你有小刀。', `MaleText_loc7`='Tú has cortado la cuerda. Así que tendrás el cuchillo.', `FemaleText_loc1`='네가 잘라. 칼이 있는 건 너잖아.', `FemaleText_loc4`='你割绳子。你有小刀。', `FemaleText_loc5`='切斷繩索。你有小刀。', `FemaleText_loc7`='Tú has cortado la cuerda. Así que tendrás el cuchillo.' WHERE `ID`=16983;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='현상 수배 전단의 내용을 읽어줘.$B$B나도 돕고 싶네!', `MaleText_loc4`='把悬赏令的内容念给葛雷克听？$B$B葛雷克想要帮忙！', `MaleText_loc5`='你幫葛利克讀懸賞告示?$B$B葛利克想幫忙!', `MaleText_loc7`='¿Lees el cartel de Se busca para Grek?$B$B¡Grek quiere ayudar!' WHERE `ID`=16984;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 이 현상 수배 전단 좀 읽어줘! 그렉은 글을 읽을 줄 몰라.', `MaleText_loc4`='谁过来给葛雷克读下这张通缉令。葛雷克不识字！', `MaleText_loc5`='快來人幫葛利克看一下這張懸賞告示。葛利克不識字!', `MaleText_loc7`='¡Qué alguien lea este cartel de Se busca para Grek! Grek no sabe leer.' WHERE `ID`=16985;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 생각에는 여기서 명예의 요새를 맞힐 수 있을 거 같은데...', `MaleText_loc4`='我认为我们可以从这儿攻击荣耀堡。', `MaleText_loc5`='你知道，我想我們可以從這裡擊中榮譽堡。', `MaleText_loc7`='¿Sabes? Creo que podemos llegar al Bastión del Honor desde aquí.', `FemaleText_loc1`='내 생각에는 여기서 명예의 요새를 맞힐 수 있을 거 같은데...', `FemaleText_loc4`='我认为我们可以从这儿攻击荣耀堡。', `FemaleText_loc5`='你知道，我想我們可以從這裡擊中榮譽堡。', `FemaleText_loc7`='¿Sabes? Creo que podemos llegar al Bastión del Honor desde aquí.' WHERE `ID`=16986;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아! 하가쉬가 실수로 넘어지면서 발포된 거라고 말하면 되겠군!', `MaleText_loc4`='啊！我们可以告诉他，是哈加什绊倒了它，然后意外地发射了！', `MaleText_loc5`='啊!我們能告訴他，哈卡斯意外的跌了進去並且將它點燃!', `MaleText_loc7`='¡Ah! Podemos decirle que Hagash tropezó y lo disparó sin querer.', `FemaleText_loc1`='아! 하가쉬가 실수로 넘어지면서 발포된 거라고 말하면 되겠군!', `FemaleText_loc4`='啊！我们可以告诉他，是哈加什绊倒了它，然后意外地发射了！', `FemaleText_loc5`='啊!我們能告訴他，哈卡斯意外的跌了進去並且將它點燃!', `FemaleText_loc7`='¡Ah! Podemos decirle que Hagash tropezó y lo disparó sin querer.' WHERE `ID`=16987;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크라콜크 사령관님께서 아시면 우리를 산채로 잡아먹을 거야. 그러지 말라고.', `MaleText_loc4`='要是让克拉库克将军发现了，他会生吞我们的，不行。', `MaleText_loc5`='如果克洛克爾克將軍知道了，他會把我們生吞活剝。別這麼做。', `MaleText_loc7`='Si el general Krakork se entera, nos comerá vivos. No.', `FemaleText_loc1`='크라콜크 사령관님께서 아시면 우리를 산채로 잡아먹을 거야. 그러지 말라고.', `FemaleText_loc4`='要是让克拉库克将军发现了，他会生吞我们的，不行。', `FemaleText_loc5`='如果克洛克爾克將軍知道了，他會把我們生吞活剝。別這麼做。', `FemaleText_loc7`='Si el general Krakork se entera, nos comerá vivos. No.' WHERE `ID`=16988;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 한숨을 쉽니다.', `MaleText_loc4`='%s叹了口气。', `MaleText_loc5`='%s嘆了一口氣。', `MaleText_loc7`='%s suspira.', `FemaleText_loc1`='%s|1이;가; 한숨을 쉽니다.', `FemaleText_loc4`='%s叹了口气。', `FemaleText_loc5`='%s嘆了一口氣。', `FemaleText_loc7`='%s suspira.' WHERE `ID`=16989;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 장님이지 귀머거리는 아니야. 나한테 덮어씌울 생각은 꿈에도 하지 말라고.', `MaleText_loc4`='我是瞎了，你这个蠢猪，但不是聋了。想都不要想。', `MaleText_loc5`='我是瞎了，你這個愚蠢的豬崽，但我沒聾。你想都別想。', `MaleText_loc7`='Estoy ciego, idiota, no sordo. Ni se te ocurra.' WHERE `ID`=16990;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 이 바위로 명예의 요새를 맞힐 수 있다는 데 10실버 건다!', `MaleText_loc4`='我赌十个银币，我能把这块石头扔到荣耀堡！', `MaleText_loc5`='賭十銀我可以用這顆巨礫擊中榮譽堡!', `MaleText_loc7`='¡Diez de plata a que llego con esta piedra hasta Bastión del Honor!', `FemaleText_loc1`='내가 이 바위로 명예의 요새를 맞힐 수 있다는 데 10실버 건다!', `FemaleText_loc4`='我赌十个银币，我能把这块石头扔到荣耀堡！', `FemaleText_loc5`='賭十銀我可以用這顆巨礫擊中榮譽堡!', `FemaleText_loc7`='¡Diez de plata a que llego con esta piedra hasta Bastión del Honor!' WHERE `ID`=16991;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디 한 번 해봐. 그럼 네 녀석을 돈과 함께 발사해서 저 벽에다 처박아 줄 테다.', `MaleText_loc4`='试试看，然后我会把你和你的十个银币一起丢过那道墙。', `MaleText_loc5`='你要是敢的話，我就會把你和你的十銀發射到那面牆後面去。', `MaleText_loc7`='Inténtalo y os dispararé a ti y a tus diez monedas de plata.', `FemaleText_loc1`='어디 한 번 해봐. 그럼 네 녀석을 돈과 함께 발사해서 저 벽에다 처박아 줄 테다.', `FemaleText_loc4`='试试看，然后我会把你和你的十个银币一起丢过那道墙。', `FemaleText_loc5`='你要是敢的話，我就會把你和你的十銀發射到那面牆後面去。', `FemaleText_loc7`='Inténtalo y os dispararé a ti y a tus diez monedas de plata.' WHERE `ID`=16992;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 나가십시오. 놈들이 너무 많으니 어서 달아나야 합니다!', `MaleText_loc4`='离开这里，它们的数量实在太多了！各自逃命吧！', `MaleText_loc5`='離開這裡，他們為數太多了!趁還來的及快逃!', `MaleText_loc7`='¡Vámonos, son demasiados! ¡Escapad mientras podéis!', `FemaleText_loc1`='여기서 나가십시오. 놈들이 너무 많으니 어서 달아나야 합니다!', `FemaleText_loc4`='离开这里，它们的数量实在太多了！各自逃命吧！', `FemaleText_loc5`='離開這裡，他們為數太多了!趁還來的及快逃!', `FemaleText_loc7`='¡Vámonos, son demasiados! ¡Escapad mientras podéis!' WHERE `ID`=16993;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와줘요! 누가 좀 도와주세요!', `MaleText_loc4`='救命！谁来帮帮我们！', `MaleText_loc5`='救命!誰能救救我們!', `MaleText_loc7`='¡Ayuda! ¡Que alguien nos ayude!', `FemaleText_loc1`='도와줘요! 누가 좀 도와주세요!', `FemaleText_loc4`='救命！谁来帮帮我们！', `FemaleText_loc5`='救命!誰能救救我們!', `FemaleText_loc7`='¡Ayuda! ¡Que alguien nos ayude!' WHERE `ID`=16994;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요. 무슨 일로 찾아오셨죠?$B$B이곳은 부모를 잃고 아무도 돌봐 줄 사람이 없는 불쌍한 아웃랜드의 고아들을 위한 보육원입니다.$B$B여기까지 발걸음을 하신 걸 보면, 혹시 입양을 고려하고 계신가요?', `FemaleText_loc4`='你好，是什么风把你吹到这儿来的？$B$B这里的孤儿院专门收留那些在外域失去双亲、无人照看的孩子。$B$B也许你是来考虑领养的吧？', `FemaleText_loc5`='哈囉，什麼把你帶到這裡來?$B$B這裡是收容外域那些失去父母以及無人看顧的孩童的孤兒院。$B$B或許你到這裡來是想要認養?', `FemaleText_loc7`='Hola. ¿Qué te trae aquí?$b$bEsto es un orfanato para los niños de Terrallende que han perdido a sus padres y no tienen a nadie que cuide de ellos.$b$b¿Acaso quieres que te adopten?' WHERE `ID`=16995;
