UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 강한 모험가들을 여러 번 만나게 되는군요. 황천의 폭풍은 위험한 곳이니 가장 효과가 뛰어난 마법이 필요할 겁니다. 저는 최고급 재료만을 팔고 있으며 일반 제품과 아제로스에서 들여온 물건들 등 모두 있답니다. 와서 한번 구경해 보시면 절대 실망하지 않을 겁니다!', `MaleText_loc4`='啊，又一个强大的旅行者。虚空很危险，你会需要最强力的法术来任你支配。我这里有各种上好的材料，普通的和珍稀的都有。来吧，买点吧，你不会遗憾的！', `MaleText_loc5`='啊，另一名強而有力的旅人。虛空可是很危險的;你將會需要任何你所能夠攜帶的有效法術。我提供最好的、普通的和奇特的藥劑。來買吧 - 你不會後悔的!', `MaleText_loc7`='Ah, $gotro viajero:otra viajera;. El Vacío Abisal puede ser peligroso. Te recomiendo que tengas los hechizos más potentes. Tengo los mejores componentes, tanto comunes como exóticos. ¡Cómprame algo, no te arrepentirás!' WHERE `ID`=17001;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에는 강한 괴물들이 많습니다, 여행자님. 살아남으려면 충분한 탄약이 필요할 겁니다. 제 가게에는 좋은 화살, 총알, 그리고 투척용 무기들이 잔뜩 구비되어 있으니 손님께선 운이 좋으시군요. 주위 환경을 고려한다면 이 가격도 싼 편이랍니다.', `MaleText_loc4`='这个地方的生物非常强壮，旅行者。如果你想活下去的话，应该带好充足的弹药。你很幸运——我这里有大量的箭矢、子弹和投掷武器。如果你考虑一下周围的环境，我的价格还是非常合理的。', `MaleText_loc5`='這個地方的動物是強壯的，旅行者。如果你希望存活，你將需要充裕的彈藥。你很幸運 - 我有貨量充足的箭、子彈和投射武器。價格合理，以這種環境來說。', `MaleText_loc7`='Las criaturas de este lugar son peligrosas, caminante. Necesitarás mucha munición si quieres sobrevivir. Estás de suerte. Tengo de todo: flechas, balas y armas arrojadizas. El precio es razonable... considerando las circunstancias.' WHERE `ID`=17002;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='조심하고 무사히 돌아와야 해!', `FemaleText_loc4`='小心点，一定要活着回来啊！', `FemaleText_loc5`='在那裡要小心，毫髮無傷的回來!', `FemaleText_loc7`='Ten cuidado y vuelve de una pieza.' WHERE `ID`=17003;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혹시 거래를 하려고 하십니까? 그렇다면 더 멀리 갈 필요 없습니다. 저는 정직한 장사꾼입니다. 제가 가진 물건 들은 매우 구하기 힘들었습니다. 뭐, 그렇지만 어디서 났는지는 상관없지 않겠습니까? 당신에게 필요한 건 뭐든지 있으니 둘러보십시오.', `MaleText_loc4`='一个商人，也许吧？你要补给的话只需要找我就好。我的价格十分合理，朋友。要知道，这些物品是很难搞到的，你就不要关心来源了好不好？总之，你会在这里找到你想要的。', `MaleText_loc5`='或許，一名小商人嗎?你需要的看來不會比我供應的多。我的價格十分合理，朋友。這些物品獲得不易，但它們的來源有什麼關係，呃?你將擁有你需要的。', `MaleText_loc7`='¿Eres mercader? Pues ya no busques más, yo tengo los suministros que necesitas. Mis precios son bastante justos, $gamigo:amiga;. No fue nada fácil conseguir estos objetos, pero eso no nos importa, ¿eh? Tendrás lo que necesitas.' WHERE `ID`=17004;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저자는 누굽니까? 왠지 낯익은 얼굴인데...', `MaleText_loc4`='他是谁？他看上去很面熟。', `MaleText_loc5`='他是誰?他看起來好面熟。', `MaleText_loc7`='¿Quién es? Su cara me es familiar.', `FemaleText_loc1`='저자는 누구죠? 왠지 낯익은 얼굴인데...', `FemaleText_loc4`='他是谁？他看上去很面熟。', `FemaleText_loc5`='他是誰?他看起來好面熟。', `FemaleText_loc7`='¿Quién es? Su cara me es familiar.' WHERE `ID`=17005;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소문이 사실입니까? 저자가 정말 대모님의 피를 이어받은 분입니까?', `MaleText_loc4`='传言是真的？他真的有盖亚安祖母的血统吗？', `MaleText_loc5`='傳言是真的嗎?他真的有主母的血統?', `MaleText_loc7`='¿Son ciertos los rumores? ¿Realmente es de la línea de sangre de la Abuela?', `FemaleText_loc1`='소문이 사실인가요? 저자가 정말 대모님의 피를 이어받은 분이라고요?', `FemaleText_loc4`='传言是真的？他真的有盖亚安祖母的血统吗？', `FemaleText_loc5`='傳言是真的嗎?他真的有主母的血統?', `FemaleText_loc7`='¿Son ciertos los rumores? ¿Realmente es de la línea de sangre de la Abuela?' WHERE `ID`=17006;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그게 사실입니까? 정말로 듀로탄 님의 아들이란 말입니까?', `MaleText_loc4`='真的是杜隆坦的儿子？', `MaleText_loc5`='這可能是真的嗎?杜洛坦之子?', `MaleText_loc7`='¿Podría ser posible? ¿El hijo de Durotan?', `FemaleText_loc1`='그게 사실인가요? 정말로 듀로탄 님의 아들이란 말인가요?', `FemaleText_loc4`='真的是杜隆坦的儿子？', `FemaleText_loc5`='這可能是真的嗎?杜洛坦之子?', `FemaleText_loc7`='¿Podría ser posible? ¿El hijo de Durotan?' WHERE `ID`=17007;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리를 이끌어 주려고 오신 걸까요?', `MaleText_loc4`='他是来领导我们的吗？', `MaleText_loc5`='他是來領導我們的嗎?', `MaleText_loc7`='¿Ha venido a guiarnos?', `FemaleText_loc1`='우리를 이끌어 주려고 오신 걸까요?', `FemaleText_loc4`='他是来领导我们的吗？', `FemaleText_loc5`='他是來領導我們的嗎?', `FemaleText_loc7`='¿Ha venido a guiarnos?' WHERE `ID`=17008;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저렇게 강한 기운을 풍기는 오크는 처음 봅니다. 우리처럼... 평범한 오크가 아닌 것 같군요.', `MaleText_loc4`='我从未在一个兽人身上感到如此强大的力量。他是……凡人吗……', `MaleText_loc5`='我從未感覺過這樣的力量從一個獸人身上散發出來。他是...凡人嗎...', `MaleText_loc7`='Nunca había conocido a un orco que irradiase tanta fuerza. ¿Es... mortal...?', `FemaleText_loc1`='저렇게 강한 기운을 풍기는 오크는 처음 봅니다. 우리처럼... 평범한 오크가 아닌 것 같군요.', `FemaleText_loc4`='我从未在一个兽人身上感到如此强大的力量。他是……凡人吗……', `FemaleText_loc5`='我從未感覺過這樣的力量從一個獸人身上散發出來。他是...凡人嗎...', `FemaleText_loc7`='Nunca había conocido a un orco que irradiase tanta fuerza. ¿Es... mortal...?' WHERE `ID`=17009;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저자가 둠해머를 갖고 있습니다!', `MaleText_loc4`='他拿着毁灭战锤！', `MaleText_loc5`='他帶著末日錘!', `MaleText_loc7`='¡Lleva el Martillo Maldito!', `FemaleText_loc1`='저자가 둠해머를 갖고 있어요!', `FemaleText_loc4`='他拿着毁灭战锤！', `FemaleText_loc5`='他帶著末日錘!', `FemaleText_loc7`='¡Lleva el Martillo Maldito!' WHERE `ID`=17010;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='처음으로 안도감이 느껴지는군요. 저는 당신을 모르지만 당신이 원한다면 목숨이라도 바치고 싶습니다.', `MaleText_loc4`='我有生以来第一次感到如此安全。我并不认识你，陌生人，但是我知道，如果你要我放弃我的生命，我会毫不犹豫地为你这么做。', `MaleText_loc5`='這是第一次，我感到安全。雖然我不認識你，陌生人，但是我知道只要你要求，我將為你放棄我的生活。', `MaleText_loc7`='Por primera vez, me siento a salvo. No sé tú, $gforastero:forastera;, pero sé que te entregaría mi vida si me la pidieras.', `FemaleText_loc1`='처음으로 안도감이 느껴지는군요. 저는 당신을 모르지만 당신이 원한다면 목숨이라도 바치고 싶습니다.', `FemaleText_loc4`='我有生以来第一次感到如此安全。我并不认识你，陌生人，但是我知道，如果你要我放弃我的生命，我会毫不犹豫地为你这么做。', `FemaleText_loc5`='這是第一次，我感到安全。雖然我不認識你，陌生人，但是我知道只要你要求，我將為你放棄我的生活。', `FemaleText_loc7`='Por primera vez, me siento a salvo. No sé tú, $gforastero:forastera;, pero sé que te entregaría mi vida si me la pidieras.' WHERE `ID`=17011;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='듀로탄 님의 아들... 가라드 님과 게야 님의 손자시여... 고개를 숙여 대족장님에게 인사를 드리십시오...', `MaleText_loc4`='杜隆坦之子……加拉达和盖亚安的孙子……向我们的酋长鞠躬吧……', `MaleText_loc5`='杜洛坦之子...卡拉達和吉雅的孫子...向我們之中的大酋長鞠躬...', `MaleText_loc7`='Hijo de Durotan... Nieto de Garad y Geyah... Inclinaos; entre nosotros hay un Jefe de Guerra.', `FemaleText_loc1`='듀로탄 님의 아들... 가라드 님과 게야 님의 손자시여... 고개를 숙여 대족장님에게 인사를 드리십시오...', `FemaleText_loc4`='杜隆坦之子……加拉达和盖亚安的孙子……向我们的酋长鞠躬吧……', `FemaleText_loc5`='杜洛坦之子...卡拉達和吉雅的孫子...向我們之中的大酋長鞠躬...', `FemaleText_loc7`='Hijo de Durotan... Nieto de Garad y Geyah... Inclinaos; entre nosotros hay un Jefe de Guerra.' WHERE `ID`=17012;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='만나 뵙게 되어 영광입니다, 듀로탄의 아들이시여. 당신은 고귀하신 분이십니다...', `MaleText_loc4`='我是微不足道的，杜隆坦之子。我们都是微不足道的……', `MaleText_loc5`='我不值，杜洛坦之子。我們全都不值...', `MaleText_loc7`='No soy digno, hijo de Durotan. Nadie es digno...', `FemaleText_loc1`='만나 뵙게 되어 영광입니다, 듀로탄의 아들이시여. 당신은 고귀하신 분이십니다...', `FemaleText_loc4`='我是微不足道的，杜隆坦之子。我们都是微不足道的……', `FemaleText_loc5`='我不值，杜洛坦之子。我們全都不值...', `FemaleText_loc7`='No soy digna, hijo de Durotan. Nadie es digno...' WHERE `ID`=17013;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='돌아왔구나! 기계는 모두 모았니?', `FemaleText_loc4`='你回来了！你帮我拿到所有的机器了吗？', `FemaleText_loc5`='你回來了!你弄到所有的機器了嗎?', `FemaleText_loc7`='¡Has vuelto! ¿Has conseguido todas las máquinas?' WHERE `ID`=17014;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당당함을 잃지 마시오, 형제자매들이여!', `MaleText_loc4`='骄傲地站起来吧，我的$g兄弟:姐妹;！', `MaleText_loc5`='驕傲的站出來，$g兄弟:姐妹;!', `MaleText_loc7`='¡Levanta la cabeza, $ghermano:hermana;!' WHERE `ID`=17015;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대를 만나게 되어 영광이오.', `MaleText_loc4`='你让我感到很荣幸，我的$g兄弟:姐妹;。', `MaleText_loc5`='你為我帶來榮耀，$g兄弟:姐妹;。', `MaleText_loc7`='Es un honor, $ghermano:hermana;.' WHERE `ID`=17016;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나야 말로 그대들에게 감사해야지.', `MaleText_loc4`='我才是微不足道的。', `MaleText_loc5`='我才是不值得的人。', `MaleText_loc7`='Soy yo quien no es digno.' WHERE `ID`=17017;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대들 앞에서 난 그저 잃어 버린 기억을 찾으려는 소년일 뿐이라오.', `MaleText_loc4`='站在你面前的只是一个想要找回失落记忆的孩子。', `MaleText_loc5`='我只是站在你面前尋找丟失回憶的小男孩。', `MaleText_loc7`='Me presento ante ti como un niño que busca recuerdos perdidos.' WHERE `ID`=17018;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='히포그리프 조련사', `MaleText_loc4`='角鹰兽管理员', `MaleText_loc5`='角鷹獸管理員', `MaleText_loc7`='Maestro de hipogrifos', `FemaleText_loc1`='히포그리프 조련사', `FemaleText_loc4`='角鹰兽管理员', `FemaleText_loc5`='角鷹獸管理員', `FemaleText_loc7`='Maestro de hipogrifos' WHERE `ID`=17019;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠... 중력장 왜곡이 안정화된 듯합니다. 우리가 해냈습니다!', `MaleText_loc4`='恩……引力扭曲指数看上去稳定了。我们成功了！', `MaleText_loc5`='噢...在比重計上的變形讀值好像有穩定化了。我們做到了!', `MaleText_loc7`='Mmm... Parece que se han estabilizado las perturbaciones gravimétricas. ¡Lo hemos conseguido!' WHERE `ID`=17020;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미량의 시간 입자가 감지되고 있습니다. 흠... 시간영역을 반전시키면 역 위상 유도 인자를 사용하여 입자를 제거할 수 있을지도 모릅니다. 물론 시간영역부터 만들어야겠지만...', `MaleText_loc4`='我正在对时间粒子进行痕量分析。嗯，如果我们使用反向相位引导装置，同时反转空间转移发生器，或许就能歼灭这些时间粒子。当然，首先我们需要建造一台空间转移发生器。', `MaleText_loc5`='我正在紀錄科尼遁粒子的數量。噢，如果在反轉我們自己的科尼球體時使用反相誘發器，我們也許能消除粒子。當然，那表示我們需要建造科尼球體...', `MaleText_loc7`='Estoy encontrando restos de partículas de cronitón. Mmm. Si usamos un inductor de fase cambiado mientras invertimos nuestra cronosfera, podremos eliminar las partículas. Pero claro, eso significa que hay que construir una cronosfera...' WHERE `ID`=17021;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흥미롭군요... 차광 사인 곡선법으로 볼 때 황천 입자 방사량이 상승하고 있는 듯합니다. 그에 비해 에너곤 입자들은 세제곱으로 증가했습니다...', `MaleText_loc4`='有意思……看来灵流粒子的喷发增量符合葛波正弦函数曲线。而超能粒子则呈三次幂增长……', `MaleText_loc5`='有趣...看來負面能量放射正持續以三角曲線比率增加。然而能量微粒卻是方塊狀的...', `MaleText_loc7`='Interesante... parece que las emisiones abisatronales están aumentando utilizando la escala de la curva gobo-sin. Aun así, las partículas energitronales están elevadas al cubo...' WHERE `ID`=17022;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황천의 양자 요동 현상으로 인해 제 장치가 정확한 자료를 얻기 힘듭니다.', `MaleText_loc4`='我的雷达设备由于量子虚空波动的干扰而不能获取准确的信息。', `MaleText_loc5`='我的機件得不到所有量子虛空波動的正確讀數。', `MaleText_loc7`='Mi invento no puede efectuar un registro preciso con todas esas fluctuaciones cuánticas de vacío.' WHERE `ID`=17023;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠... 우리가 사용하는 동기화 가속기가 이 지역의 중력장 왜곡 현상에 별 영향을 주지 못한 것 같습니다.', `MaleText_loc4`='嗯……似乎我们使用的同步加速单元对这片区域的引力扭曲或是真空状态都没有产生显著的影响。', `MaleText_loc5`='嗯...看來我們一直在使用的那個同步器組件，對這個區段的重量扭曲沒有值得注意的作用。', `MaleText_loc7`='Mmm... Parece que la unidad sincotronal que hemos estado utilizando no ha tenido ningún efecto evidente en las distorsiones gravimétricas o gravitatrónicas de este sector.' WHERE `ID`=17024;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주위를 둘러보거라. 이곳이 드레노어다!', `MaleText_loc4`='看看你们的周围，年轻人。这里是德拉诺！', `MaleText_loc5`='看看你的四周，年輕人。這是德拉諾!', `MaleText_loc7`='Miren a su alrededor, jóvenes. ¡Esto es Draenor!' WHERE `ID`=17025;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놀랍군. 세상이 파괴됐음에도 불구하고 이렇게 멀쩡하다니...', `MaleText_loc4`='太棒了。这里为什么居然没有被毁灭呢？', `MaleText_loc5`='太驚人了。它怎麼還能維持在這個狀態，完全未受世界毀滅的影響?', `MaleText_loc7`='Es asombroso. ¿Cómo ha podido permanecer en este estado sin que le afecte la destrucción del mundo?' WHERE `ID`=17026;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오슈군은 아직 건재할까... 암흑의 시대가 오기 전에 겪었던 이야기들... 수많은 놀라운 기억들...', `MaleText_loc4`='我怀疑沃舒古是不是还存在……我还记得许多黑暗之前的事情……太多美好的回忆了……', `MaleText_loc5`='我納悶，歐夏剛還在嗎...喔在黑暗之前我可以說的故事...那麼多奇妙的回憶...', `MaleText_loc7`='Me pregunto si Oshu''gun sigue en pie... ¡Oh, la de historias que podría contarte sobre la época de antes de la oscuridad! Tantos fantásticos recuerdos...' WHERE `ID`=17027;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 여기서 소년의 티를 막 벗기 시작한 듀로탄께서 탈부크를 처음으로 잡았지. 아, 봄 축제가 열리면 그분은 우리에게 그 이야기를 해 주시곤 하셨는데...', `MaleText_loc4`='我记得就是在这块土地上，年轻的杜隆坦猎杀了他的第一只塔布羊。啊，我仍然记得他在春季节庆时反复地对我们讲这个故事。', `MaleText_loc5`='我相信是在這片土地上一個年輕，剛進入青春期的杜洛坦，殺死了他的第一隻雄鹿。啊，我還記得他在春季慶典為我們重述那個故事。', `MaleText_loc7`='Creo que fue en esta misma tierra donde un joven Durotan, que casi no había llegado a la adolescencia, mató a su primer talbuk. Todavía puedo recordarle contándonos esa historia en el festival de primavera.' WHERE `ID`=17028;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 밟고 있는 이 땅에서 우리의 위대한 영웅들이 사냥을 하셨지.', `MaleText_loc4`='就在我们脚下的这块土地上，我们最伟大的英雄曾在这里狩猎。', `MaleText_loc5`='在這塊我們現在碰觸，我們最偉大的英雄曾經狩獵的土地上。', `MaleText_loc7`='Y, en este mismo suelo donde ahora estamos, nuestros más grandes héroes cazaban.' WHERE `ID`=17029;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알다시피 그들은 절친한 친구였소. 듀로탄 님과 오그림 님께서 테로카르 숲에 들어갔다가 오우거에게 잡힐 뻔한 적도 있었지. 드레나이가 그들을 구해 주지 않았다면 잡혔겠지... 옛일을 회상하니 마음이 울적하군. 우리는 드레나이에게 정말 심한 짓을 했어...', `MaleText_loc4`='你知道，杜隆坦和奥格瑞姆曾是最好的朋友，他们曾经结伴去泰罗卡森林冒险，在那里差点被一只食人魔杀死。要不是德莱尼人救了他们……回首往事总让我伤感，我们都对那些德莱尼人干了什么……', `MaleText_loc5`='你知道，他們是最好的朋友。杜洛坦和奧格林曾經進入泰洛卡森林，他們差點在那裡被一個巨魔給殺掉。要不是有個德萊尼救了他們...回憶這些過去真讓我傷心。我們竟對德萊尼做出這樣恐怖的事...', `MaleText_loc7`='Eran buenos amigos. Durotan y Orgrim se aventuraron en el Bosque de Terokkar y casi los mata un ogro. Si no hubiera sido por el draenei que los salvó... Me entristece recordar aquellos tiempos. Les hicimos cosas terribles a los draenei...' WHERE `ID`=17030;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오래된 기억들이 깨어나는구나. 고귀한 바람의 정령들이 밀어주기라도 하는 듯 내게 달려오는구나...', `MaleText_loc4`='往日的回忆不断浮现。它们在我脑海中急速掠过，仿佛是高贵的空气之魂在催促着它们。', `MaleText_loc5`='舊時的回憶襲捲。他們衝向我，好像被空氣中高尚的靈魂激勵一樣...', `MaleText_loc7`='Los viejos recuerdos vuelven a la luz. Vienen rápidamente a mí como empujados por los nobles espíritus del viento...' WHERE `ID`=17031;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 죽어도 여한이 없도다. 마침내 고향에 돌아왔으니 내 영혼은 이 육체의 껍데기를 벗을 수 있게 되었노라.', `MaleText_loc4`='我已经做好赴死的准备了。魂归故土，我终于可以挣脱这具凡人的躯壳。', `MaleText_loc5`='我準備好赴死了。終於回到家鄉，我的靈魂可以從這個凡人的軀殼中自由了。', `MaleText_loc7`='Estoy listo para morir. Por fin en casa, mi espíritu puede liberarse de su caparazón mortal.' WHERE `ID`=17032;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황천에서 비정상적인 수치가 탐지되었습니다.', `MaleText_loc4`='我们从虚空流中捕获了一些奇怪的信息。', `MaleText_loc5`='我們從虛空緞帶取得了一些奇怪的讀數。', `MaleText_loc7`='Hemos recibido extrañas lecturas de los galones abisales.' WHERE `ID`=17033;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='중력장 왜곡에 대한 사전 보고서가 준비되었습니다.', `MaleText_loc4`='我得到了一份关于重力破坏的初步报告。', `MaleText_loc5`='我有一份關於重量瓦解的初步報告。', `MaleText_loc7`='Tengo un informe preliminar sobre las perturbaciones gravimétricas.' WHERE `ID`=17034;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황천으로부터 또 다른 수치가 탐지되었습니다.', `MaleText_loc4`='我有另一条从虚空传来的讯息。', `MaleText_loc5`='我從虛空接受到另一個讀數。', `MaleText_loc7`='Recibo más datos de la nada.' WHERE `ID`=17035;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 사차원 기록기가 황천에서 이상한 조짐을 탐지했습니다.', `MaleText_loc4`='我的四分记录器从虚空中检测到了一些反常的讯息。', `MaleText_loc5`='我的四倍通訊器從虛空異象中偵測到一些異常的讀數。', `MaleText_loc7`='Mi receptor cuántico ha detectado unas lecturas anómalas de las anomalías abisales.' WHERE `ID`=17036;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무래도 장치가 고장인 것 같습니다. 정말로 이상한 수치가 나옵니다.', `MaleText_loc4`='我想我的雷达设备搞不好是坏掉了，它平时可以收集很多特殊的信息。', `MaleText_loc5`='我想我的機件壞了，它顯示了一些奇怪的讀數。', `MaleText_loc7`='Creo que mi aparato se ha roto, aunque consiguió recibir unas extrañas lecturas.' WHERE `ID`=17037;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 수치를 좀 보십시오. 지금까지와는 전혀 다릅니다.', `MaleText_loc4`='你应该看看这些读数，跟我们曾经见过的大不相同。', `MaleText_loc5`='你應該看看這些讀數，它們不像我們之前看過的任何數據。', `MaleText_loc7`='Deberías echar un vistazo a estas lecturas, nunca había visto algo parecido.' WHERE `ID`=17038;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 늑대 가죽으로 만든 예복을 입습니다.', `MaleText_loc4`='%s披上了他的狼皮外套。', `MaleText_loc5`='%s穿上他的狼皮法衣。', `MaleText_loc7`='%s se pone sus prendas de piel de lobo.' WHERE `ID`=17039;
