UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가지고 있는 물건을 보고 싶습니다.', `MaleText_loc4`='让我们看看你有些什么。', `MaleText_loc5`='讓我們看看你有什麼發現。', `MaleText_loc7`='Veamos qué tienes.' WHERE `ID`=17041;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 보고 있는 중이니 잠깐만 기다리라고.', `MaleText_loc4`='给我点时间来检查这些东西。', `MaleText_loc5`='給我一點時間仔細檢查這些發現。', `MaleText_loc7`='Déjame un momento para estudiar estos hallazgos.' WHERE `ID`=17042;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 직접 판단하도록 하지.', `MaleText_loc4`='我会做出裁决的。', `MaleText_loc5`='我會來審判。', `MaleText_loc7`='Yo juzgaré eso.' WHERE `ID`=17043;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='숲에 있는 늑대의 영혼들이여, 내 말이 들립니까?!', `MaleText_loc4`='森林的狼魂，听从我的命令吧！', `MaleText_loc5`='森林的狼靈，聽我說!', `MaleText_loc7`='¡Espíritu lobo del bosque, escúchame!' WHERE `ID`=17044;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이리 줘보라고. 뭘 알아냈는지 좀 볼까!', `MaleText_loc4`='把它交出来，让我们看看你拿到了什么！', `MaleText_loc5`='嗯把它拿過來讓我們看看你發現了什麼!', `MaleText_loc7`='Dámelo y veamos lo que tienes.' WHERE `ID`=17045;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오래전 그대들은 우리 동료였습니다. 우리는 악마에게 몸을 바쳤고 그대들을 잊었습니다.', `MaleText_loc4`='曾几何时，你是我的族人的挚友。我们将自己献与了恶魔，你也在我们的记忆中被抹去。', `MaleText_loc5`='很久前，你是我們族人的同伴。我們致力於對付邪惡而遺忘了你。', `MaleText_loc7`='Mucho tiempo atrás, eras $gcompañero:compañera; de los míos. Pero nos pasamos al lado del mal y te olvidamos.' WHERE `ID`=17046;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 우리가 돌아왔습니다! 그대들에게 영광을 돌려주려고 돌아왔단 말입니다. 다시 한번 모습을 드러내 주십시오.', `MaleText_loc4`='但是我们回来了，灵魂！我们再次向你致敬。请再次显身，赐我们以恩泽。', `MaleText_loc5`='但我們回來了，偉大之魂!我們再次回來敬頌你。請再次現身認同我們吧。', `MaleText_loc7`='¡Pero hemos vuelto, espíritu! Hemos vuelto para honrarte de nuevo. Glorifícanos otra vez con tu presencia.' WHERE `ID`=17047;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='즐겨 마시는 술이 뭔가? 의자에 편히 앉게나.$B$B나는 B.O.O.M. 밑에서 일하는 선임 바텐더 부츠라고 하네!$B$B진정 효과가 좋고 강한 술 한잔을 원한다면 이 부츠가 만들어 줄 수 있지.', `MaleText_loc4`='你的乐趣是什么？拉出一把椅子喝上一杯吗？$B$B我是布兹，爆缸航天局的首席调酒师和超级招待员！$B$B如果你要找乐子，就来找布兹！', `MaleText_loc5`='你平時都做何消遣呢?拉張椅子坐下喝一杯吧。$B$B我是布茲，B.O.O.M.的首席調酒師和超級酒保!$B$B只要是夠嗆夠辣的酒，老布茲都可以幫你特調。', `MaleText_loc7`='¿Qué quieres? Siéntate y escoge uno.$B$BSoy Botas, mixólogo jefe de B.U.M. y barman extraordinario.$B$BSi lo que necesitas es un toque mágico, el viejo Botas te lo dará.' WHERE `ID`=17048;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 맙소사...', `MaleText_loc4`='啊……', `MaleText_loc5`='喔天啊...', `MaleText_loc7`='Cielos...' WHERE `ID`=17049;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멋지군!', `MaleText_loc4`='真迷人。', `MaleText_loc5`='太棒了。', `MaleText_loc7`='Fascinante.' WHERE `ID`=17050;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 말루카즈의 부름에 응답하여 포효합니다.', `MaleText_loc4`='%s用嚎叫回应玛鲁卡兹的召唤。', `MaleText_loc5`='%s怒吼著回應瑪魯卡茲的呼叫。', `MaleText_loc7`='%s aúlla en respuesta a la llamada de Malukaz.' WHERE `ID`=17051;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대단하군!', `MaleText_loc4`='真是难以置信！', `MaleText_loc5`='不可思議!', `MaleText_loc7`='¡Increíble!' WHERE `ID`=17052;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대단하군... 정말 대단해.', `MaleText_loc4`='令人难忘……太令人难忘了。', `MaleText_loc5`='真令人佩服...非常佩服。', `MaleText_loc7`='Impresionante... Muy impresionante.' WHERE `ID`=17053;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부츠, 부드럽게 넘어가는 술은 없습니까?', `MaleText_loc4`='布兹，酒单给我。', `MaleText_loc5`='布茲，你那裡有什麼好酒嗎?', `MaleText_loc7`='¿Botas, qué tienes por ahí que entre bien?', `FemaleText_loc1`='부츠, 부드럽게 넘어가는 술은 없나요?', `FemaleText_loc4`='布兹，酒单给我。', `FemaleText_loc5`='布茲，你那裡有什麼好酒嗎?', `FemaleText_loc7`='¿Botas? ¿Qué tienes por ahí que entre bien?' WHERE `ID`=17054;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정령이여, 우리의 결속이 또다시 깨어지는 일이 없기를...', `MaleText_loc4`='愿你与我们的结合永不再分开，灵魂。', `MaleText_loc5`='願我們與你的連結永遠不會再被切斷，亡靈。', `MaleText_loc7`='Que nuestro vínculo no vuelva a romperse nunca, espíritu.' WHERE `ID`=17055;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대단한 가즈로 님!', `MaleText_loc4`='伟大的加兹鲁维！', `MaleText_loc5`='偉大的加茲魯維!', `MaleText_loc7`='¡Gran Gazlowe!' WHERE `ID`=17056;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 수치를 보완하려면 정보가 더 필요하다고. 그곳으로 돌아가서 정보를 더 모아오도록!', `MaleText_loc4`='我们需要收集更多的数据来证实这些信息。回去收集数据吧。', `MaleText_loc5`='我們需要收集更多資料來證實這些讀數。回來這裡收集那些資料。', `MaleText_loc7`='Necesitaremos recopilar más datos para mejorar la lectura. Vuelve ahí y recoge información.' WHERE `ID`=17057;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 이 정보를 확인해야 해. 우리 시설을 더 망가뜨리고 싶지 않다면 말이야.', `MaleText_loc4`='我们需要确认这些数据，我们可不想把设备弄得乱七八糟。', `MaleText_loc5`='我們需要確認這個資料，我們不想弄壞更多設備了。', `MaleText_loc7`='Hay que confirmar estos datos. No podemos arriesgarnos a destrozar ninguna parte más de nuestras instalaciones.' WHERE `ID`=17058;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 수치에 의하면 겁낼 게 없군. 적어도 당분간은 말이야. 단, 확실히 하려면 정보가 더 필요해.', `MaleText_loc4`='依据这些信息，我们没有什么可害怕的。至少目前是没有，我们还需要更多的数据来确认。', `MaleText_loc5`='根據這些數據，我們沒什麼好怕的。至少短時間內沒問題。我們需要更多資料來做確認。', `MaleText_loc7`='Según esta lecturas, no tenemos nada que temer. Al menos nada en el futuro más próximo. Necesitaremos más datos para estar seguros.' WHERE `ID`=17059;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 정보는 파란 책 프로젝트에 아주 유용하겠군. 에, 그러니까 내 새로운 머리모양에나 어울리겠다는 뭐 그런 뜻이지. 정보, 정보가 더 필요해!', `MaleText_loc4`='这份数据对蓝书计划十分有用。呃，我的意思是这会对我的新造型很有帮助。去看看你能不能收集到更多的数据。', `MaleText_loc5`='這個資料會對藍色整型百科相當有用，我是說，這對我的新造型會很有幫助。看看你能否收集到更多資料。', `MaleText_loc7`='Estos datos serán muy útiles para el cuaderno de notas del proyecto. Eh..., quiero decir estará muy bien para mi nuevo aspecto. Mira a ver si puedes encontrar más datos.' WHERE `ID`=17060;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠... 이 황천의 방사능은 매우 치명적일지도 몰라. 하지만, 무시하다가는 더 큰일이 벌어질 수도 있다고. 확실히 하려면 수치가 더 필요해...', `MaleText_loc4`='唔……这种虚空辐射被证明是十分致命的。如果我们忽视了它，那就会更加致命。我需要更多信息来确定这一点。', `MaleText_loc5`='嗯...這個虛空輻射可能會相當致命。但如果忽略它就可能更致命。我需要更多讀數來確認這點。', `MaleText_loc7`='Mmm... esta radiación abisal podría ser bastante letal. Pero también podría ser una falsa alarma. Necesitaré más lecturas para confirmarlo.' WHERE `ID`=17061;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야호! 자, 시작해 볼까!', `MaleText_loc4`='喔哦！开始了！', `MaleText_loc5`='哇喔!開始囉!', `MaleText_loc7`='¡Uaaah! ¡Allá vamos!' WHERE `ID`=17062;
