UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 괜찮아, 괜찮다고! 아 이런, 로켓 연료 장치의 설계도를 그리러 돌아가야겠군!', `MaleText_loc4`='我没事。我没事。啊好吧，继续回去设计那个火箭燃料！', `MaleText_loc5`='我沒事，我沒事!啊嗯，回到那個火箭燃料的計畫階段!', `MaleText_loc7`='¡Estoy bien, estoy bien! Bueno, tendré que revisar mis diseños de la ignición.' WHERE `ID`=17064;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 해냈습니다! 스랄 님도 자랑스러워하실 겁니다.', `MaleText_loc4`='我们成功了！萨尔会为我们骄傲的。', `MaleText_loc5`='我們辦到了!索爾會很驕傲的。', `MaleText_loc7`='¡Lo hemos conseguido! Thrall estaría orgulloso.' WHERE `ID`=17066;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런! 누가 소방관 좀 불러 주십시오! 의무병!!! 여기 의사 없습니까?', `MaleText_loc4`='呀！谁叫下火警！医生！！医生呢？', `MaleText_loc5`='哎呀!快呼叫消防署長!軍醫!!!這裡有醫生嗎?', `MaleText_loc7`='¡Huy! ¡Que alguien llame a los bomberos! ¡Médico! ¿Hay algún médico por aquí!' WHERE `ID`=17067;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렉, 라코리아가 새로 만든 기름을 무기에 사용해 보시겠습니까?', `MaleText_loc4`='葛雷克，你想试试这些拉克妮亚做的新武器油吗？', `MaleText_loc5`='葛利克，你要不要試試瑞蔻莉雅製造的新武器油呢?', `MaleText_loc7`='Grek, ¿quieres probar este nuevo aceite para armas que ha hecho Rakoria?', `FemaleText_loc1`='그렉, 라코리아가 새로 만든 기름을 무기에 사용해 보시겠습니까?', `FemaleText_loc4`='葛雷克，你想试试这些拉克妮亚做的新武器油吗？', `FemaleText_loc5`='葛利克，你要不要試試瑞蔻莉雅製造的新武器油呢?', `FemaleText_loc7`='Grek, ¿quieres probar este nuevo aceite para armas que ha hecho Rakoria?' WHERE `ID`=17068;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러지!', `MaleText_loc4`='葛雷克试试！', `MaleText_loc5`='葛利克試試!', `MaleText_loc7`='¡Grek probar!' WHERE `ID`=17069;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 기름은 나한테 아무짝에도 소용이 없군! 이 그렉이 로브나 뒤집어쓰고 다니는 약골로 보이나?', `MaleText_loc4`='这油对葛雷克没什么用处！你觉得葛雷克看起来像什么？穿着长袍的弱者？', `MaleText_loc5`='這個油對葛利克沒好處!你覺得葛利克看起來像什麼，一個穿著長袍的弱者?', `MaleText_loc7`='¡Este aceite no vale para Grek! ¿Qué crees que es Grek? ¿Un debilucho con túnica?' WHERE `ID`=17070;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 의사입니다! 무슨 문제가 있나요?', `MaleText_loc4`='我是医生！发生什么事情了？', `MaleText_loc5`='我是醫生!有什麼問題嗎?', `MaleText_loc7`='¡Soy médico! ¿Cuál es el problema?' WHERE `ID`=17071;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오! 저 안에 들어가서 고블린을 구할 수 있도록 누가 불 좀 꺼주세요!', `MaleText_loc4`='哦！得有人去灭了那些火，不然我没法进去救那个地精！', `MaleText_loc5`='喔!有人要去把那些火焰撲滅我才能進去救那個哥布林!', `MaleText_loc7`='¡Oh! Alguien tiene que apagar esos fuegos para que yo pueda entrar y salvar a ese goblin.' WHERE `ID`=17072;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이게 마나 오일일줄은 상상도 못했소! 수요가 엄청날 것이오. 물론 그렉은 빼고 말이야!', `FemaleText_loc4`='我从未想过这个竟然是法力之油！肯定会热卖的，葛雷克！', `FemaleText_loc5`='我從沒想過它竟然會是法力油!一定會有許多人想要的，當然除了葛利克!', `FemaleText_loc7`='¡Nunca pensé que sería aceite de maná! ¡Vamos a tener mucha demanda de eso, menos Grek, por supuesto!' WHERE `ID`=17073;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아요... 이제 들어가겠습니다!', `MaleText_loc4`='好吧……让我进去！', `MaleText_loc5`='對...讓我進去!', `MaleText_loc7`='Bien... ¡Déjame entrar!' WHERE `ID`=17074;
