UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빌어먹을, 부츠! 난 의사지 사제가 아니란 말이야! 비키라고!', `MaleText_loc4`='该死的，布兹，我是个医生，不是个牧师！让开！！', `MaleText_loc5`='可惡，布茲，我是博士不是牧師!離開!!!', `MaleText_loc7`='¡Maldición, Botas! Soy un doctor, no un sacerdote. ¡¡¡Fuera!!!' WHERE `ID`=17078;
