UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헬스크림! 축복받은 선조들! 그는 그롬 님을 그대로 닮았더군요, 지혜로운 드렉타르시여.', `MaleText_loc4`='地狱咆哮！天啊！德雷克塔尔，他简直就是格罗姆再世。', `MaleText_loc5`='地獄吼!神聖的祖先!他是葛羅反射的映象，德雷克塔爾。', `MaleText_loc7`='¡Grito Infernal! ¡Benditos ancestros! Es la viva imagen de Grom, Drek''Thar.' WHERE `ID`=17080;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천만에요!', `MaleText_loc4`='很荣幸！', `MaleText_loc5`='我的榮幸!', `MaleText_loc7`='¡Un placer!' WHERE `ID`=17081;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙습니다...', `MaleText_loc4`='谢谢……', `MaleText_loc5`='謝謝...', `MaleText_loc7`='Gracias...' WHERE `ID`=17082;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가젯잔 타임즈의 특파원이신가요? 절 따라오신다면 제 실험 기구들을 보여 드리도록 하지요...$B$B<자브라시스가 기다리던 그 기자가 아니라고 말하자...>$B$B이런, 아니라고요? 그렇다면 당신에게 필요한 물건을 찾아보세요. 시간 끌지 마시고요. 저는 기다리는 사람이 있습니다.', `FemaleText_loc4`='你是加基森时报的记者吗？如果你跟着我，我会让你看看我的试验设备……$B$B<你告诉她你不是她所期盼的记者。>$B$B哦，你不是？那么好吧，如果你需要施法材料，就自己挑吧。我在等人呢。', `FemaleText_loc5`='你是加基森報的記者嗎?如果你剛剛跟蹤我，我會讓你見識我的實驗儀器...$b$b<你告訴魔導師你不是她說的記者。>$B$B喔，你不是?那好，如果你需要試劑，就快點找你要的東西不要逗留。我在等人。', `FemaleText_loc7`='¿Eres el corresponsal de la Voz de Gadgetzan? Si me sigues, te enseñaré mi nuevo invento...$B$B<Le dices a la maga que no eres el corresponsal que esperaba.> Está bien. Si necesitas componentes, búscalos. Rapidito. Estoy esperando a alguien.' WHERE `ID`=17083;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 불렀나요?', `MaleText_loc4`='谁在叫我？', `MaleText_loc5`='有人來拜訪嗎?', `MaleText_loc7`='¿Me ha llamado alguien?' WHERE `ID`=17084;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물건을 살펴보고 싶습니다.', `MaleText_loc4`='我想要看看你出售的货物。', `MaleText_loc5`='我想看看你的商品。', `MaleText_loc7`='Me gustaría echar un vistazo a tus mercancías.', `FemaleText_loc1`='물건을 살펴보고 싶습니다.', `FemaleText_loc4`='我想要看看你出售的货物。', `FemaleText_loc5`='我想看看你的商品。', `FemaleText_loc7`='Me gustaría echar un vistazo a tus mercancías.' WHERE `ID`=17085;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 자신이 도착했음을 울음소리로 표현합니다.', `MaleText_loc4`='%s表示赞同。', `MaleText_loc5`='%s表達它的贊同。', `MaleText_loc7`='%s expresa su aprobación.' WHERE `ID`=17086;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='건방지고 멍청한 녀석! 너는 캘타스 왕자님을 섬기는 자들에게 상대가 될 수 없다!', `MaleText_loc4`='蠢货！你们不是凯尔萨斯王子的忠实仆从的对手！', `MaleText_loc5`='傲慢的蠢蛋!你根本不是凱爾薩斯王子僕人的對手!', `MaleText_loc7`='¡Idiota impertinente! ¡No eres rival para los súbditos del príncipe Kael''thas!' WHERE `ID`=17087;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방사선?!$B$B아니, 자넨 그 일에 신경 쓸 거 없다고! 젠장, 요즘은 다들 그렇게 믿고 있더군.$B$B그건 그렇고 여기 공정에 대해 어떻게 생각하나? 그럼, 최신식이지! 믿어도 좋아.', `MaleText_loc4`='辐射？！$B$B不，你不用担心那些。天哪，这几天大家都这么认为。$B$B那么你对我们在这里的计划有什么看法？技术的巅峰，宝贝！你最好相信它。', `MaleText_loc5`='輻射!$B$B不，你不用擔心那個!去，現在人們相信的東西。$B$B那麼，你覺得我們在這裡的運作怎麼樣?藝術之都，寶貝!你最好相信。', `MaleText_loc7`='¡¿Radiaciones?!$B$BNo, eso no tiene que preocuparte. Rayos, hay que ver las cosas que se cree la gente hoy en día.$B$BEntonces, ¿qué te parecen nuestras operaciones ahí abajo? ¡Es una obra de arte! Ver para creer.' WHERE `ID`=17088;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='남은 게 좀 있습니다.', `MaleText_loc4`='我还有点剩下的。', `MaleText_loc5`='我有一些殘餘物。', `MaleText_loc7`='Me queda algo.', `FemaleText_loc1`='남은 게 좀 있습니다.', `FemaleText_loc4`='我还有点剩下的。', `FemaleText_loc5`='我有一些殘餘物。', `FemaleText_loc7`='Me queda algo.' WHERE `ID`=17089;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조잡한 폭발물을 잃어버렸습니다. 남은 게 좀 있습니까?', `MaleText_loc4`='我遗失了我的劣质炸弹。你还有多余的吗？', `MaleText_loc5`='我弄丟了粗糙的爆裂物。你還有剩下的嗎?', `MaleText_loc7`='He perdido mis explosivos rudimentarios. ¿Te queda alguno a ti?', `FemaleText_loc1`='조잡한 폭발물을 잃어버렸습니다. 남은 게 좀 있나요?', `FemaleText_loc4`='我遗失了我的劣质炸弹。你还有多余的吗？', `FemaleText_loc5`='我弄丟了粗糙的爆裂物。你還有剩下的嗎?', `FemaleText_loc7`='He perdido mis explosivos rudimentarios. ¿Te queda alguno a ti?' WHERE `ID`=17090;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 고개를 끄덕입니다.', `MaleText_loc4`='%s点了点头。', `MaleText_loc5`='%s點點頭。', `MaleText_loc7`='%s asiente con la cabeza.' WHERE `ID`=17091;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 기억들이 물밀처럼 밀려오는군요, 스랄 님.', `MaleText_loc4`='萨尔，久远的记忆涌上了我的心头……', `MaleText_loc5`='回憶快速倒帶，索爾。', `MaleText_loc7`='Los recuerdos fluyen, Thrall.' WHERE `ID`=17092;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 수년 동안 우리가 실버문에서 옳은 일을 하고 있다고 확신했소. 우리는 아웃랜드에 도착해서 다시 캘타스와 합류하기 위해 열심히 일했지.$B$B우리를 위해 캘타스가 뭘 준비해 놓았었는지 알았더라면 난 매날개 광장에 머물러 있었을 것이오.', `MaleText_loc4`='多年来我一直深信我们在银月城所做的事情是对的——为能到达外域而努力，那么我们就可以和凯尔萨斯重新会合。$B$B当我知道凯尔萨斯为我们准备了什么之后，我愿意还是待在鹰翼广场。', `MaleText_loc5`='幾年來我都深信我們在銀月城做的是對的 - 努力到達外域我們就能和凱爾重聚。$B$B要是我知道凱爾薩斯為我們準備著什麼，我就會留在獵鷹之翼廣場了。', `MaleText_loc7`='Durante años estuve convencido de que hacíamos lo correcto en Lunargenta al intentar alcanzar Terrallende para reunirnos con Kael.$B$BSi hubiera sabido lo que nos deparaba Kael''thas, no me habría movido de la Plaza Alalcón.' WHERE `ID`=17093;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='게시판에 눈길을 끄는 두 개의 전단이 붙었는데 하나는 휠러 아저씨가, 다른 하나는 로켓발사단장 퓨즐라지가 올린 것입니다.$B$B휠러 아저씨는 기계 부품을 구하는 전단을 올렸습니다. 로켓발사단장은 거대한 산악거인의 목에 현상금을 걸었습니다!$B$B두 전단의 자세한 내용은 깨알같이 작은 고블린 글씨로 적혀 있어서 알아보기 매우 어렵습니다.', `MaleText_loc4`='两张醒目的悬赏单被钉在公告板上，一张是维勒老爹的悬赏，另一张是火箭主管弗斯拉格的。$B$B老爹的看上去是一个机械零件的悬赏，而火箭主管悬赏巨大的山脉巨人。$B$B两个悬赏令都是用晦涩难懂、歪歪扭扭的地精小篆书写的。', `MaleText_loc5`='有兩張重要的海報釘在這裡的板子上;一張是威勒老爹的，一張是火箭主管夫斯拉吉的。$B$B威勒老爹的看起來是一張機械零件的懸賞海報。火箭主管夫斯拉吉的則是和一個巨大的巨人頭顱有關的賞金告示!$B$B這兩則消息的細節都用非常小的哥布林筆跡寫著，當然，相當難以辨認。', `MaleText_loc7`='Hay dos notas enormes en el tablón; una es de Papá Ruedas y, la otra, del jefe de cohetes Fuselaje.$B$BLa de Papá parece ser un anuncio en el que solicita la pieza de una máquina. ¡La del jefe de cohetes guarda relación con una recompensa por la cabeza de un enorme gigante montés!$B$BLos detalles de ambas están escritos con caligrafía goblin muy pequeña, que, por supuesto, es prácticamente ilegible.' WHERE `ID`=17094;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에 여러 개의 전단이 붙어 있는 것이 눈에 띕니다.$B$B하지만, 자세히 보니 당신이 직접 이 일을 맡기에는 무리가 있는 것 같습니다. 나중에 다시 확인하는 게 좋겠습니다!', `MaleText_loc4`='在这里的公告板上钉着几张醒目的悬赏单。$B$B然而，难懂的条文很明显地告诉你，你还没有准备好。你应该以后再来看看！', `MaleText_loc5`='有幾張重要的海報釘在這個板子上。$B$B然而，小號字體指出你尚未準備好執行手邊這幾個任務。你絕對要過陣子再回來看看!', `MaleText_loc7`='Hay varias notas destacadas en el tablón.$B$BSin embargo, la letra pequeña indica que no estás $gpreparado:preparada; para ninguna de las tareas. ¡Definitivamente deberías volver más tarde!' WHERE `ID`=17095;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좀 더 일찍 오지 못해서 미안하오, 헬스크림의 아들이여. 그대의 아버님에 대해서 들려줄 말이 무척 많지만 우선은 어디로 가야 대모님을 찾아뵐 수 있는지부터 말해 주겠소?', `MaleText_loc4`='我很抱歉我没能及时赶来，年轻的地狱咆哮。我有很多关于你父亲的事情要告诉你，但首先，你必须告诉我可以在哪里找到祖母。', `MaleText_loc5`='我很抱歉我沒有早點來，年輕的地獄吼。我有好多你父親的事要告訴你，但你必須先告訴我可以在哪裡找到主母。', `MaleText_loc7`='Siento no haber podido venir antes, joven Grito Infernal. Tengo mucho que contarte sobre tu padre, pero primero, debes decirme dónde puedo encontrar a la Abuela.' WHERE `ID`=17096;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디냐! 결정이 어디 있느냔 말이다! 우리가 못 보게 숨겨놓을 수 없을 것이야!', `MaleText_loc4`='哪儿？碎片在哪儿！你别想把它们藏起来！', `MaleText_loc5`='哪裡?裂片在哪裡!你不能把它們藏起來!', `MaleText_loc7`='¿Dónde? ¿Dónde están los fragmentos? ¡Los encontraremos!' WHERE `ID`=17097;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 마그하르를 찾아 주다니 더 없는 영광이오, 듀로탄의 아들이여. 대모님께서는 피난민 병동에서 기다리고 계시다오.', `MaleText_loc4`='我们对你的光临感到很荣幸，杜隆坦之子。祖母在她的病房等着你。', `MaleText_loc5`='你的出現讓我們備感榮幸，杜洛坦之子。主母在收容所等著你。', `MaleText_loc7`='Nos sentimos honrados por tu presencia, hijo de Durotan. La Abuela te espera en el hospicio.' WHERE `ID`=17098;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 피난민 병동을 가리킵니다.', `MaleText_loc4`='%s指向对面的病房。', `MaleText_loc5`='%s指向收容所。', `MaleText_loc7`='%s señala al hospicio.' WHERE `ID`=17099;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙소이다, 가로쉬. 대모님을 뵙고 난 후에 그대와 의논할 일이 아주 많소이다.', `MaleText_loc4`='感谢你，加尔鲁什。在我拜访祖母之后，我会找你好好谈谈的。', `MaleText_loc5`='謝謝你，卡爾洛斯。等我拜訪過主母回來後我們還有很多事要談論。', `MaleText_loc7`='Gracias, Garrosh. Tenemos mucho de qué hablar cuando vuelva de ver a la Abuela.' WHERE `ID`=17100;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너를 기다리고 있었단다, 듀로탄의 아들아. 좀 더 가까이 오겠느냐? 이제는 예전처럼 눈이 잘 보이지 않아서 말이다.', `FemaleText_loc4`='我等你好久了，孩子。靠近一点，我的眼睛已经不像以前那么好使了。', `FemaleText_loc5`='我一直在等你，年輕人。靠近點 - 我的眼睛已經不像以前那樣銳利了。', `FemaleText_loc7`='Estaba esperándote, joven. Acércate. Mis ojos ya no son lo que eran.' WHERE `ID`=17101;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대모님이시여...', `MaleText_loc4`='祖母……', `MaleText_loc5`='主母...', `MaleText_loc7`='Abuela...' WHERE `ID`=17102;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가까이 오너라, 손자여. 네 대모 옆에 와서 앉거라.', `FemaleText_loc4`='靠近点，孙子。坐在你祖母的身边。', `FemaleText_loc5`='靠近點，孫子。坐到你的主母旁邊。', `FemaleText_loc7`='Acércate, nieto mío. Siéntate al lado de tu Abuela.' WHERE `ID`=17103;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='드렉타르, 자네는 언제나 우리 백성들을 위해 충성을 바쳤지. 자네에게 정령들의 가호가 있기를 바라네, 오랜 친구여. 이곳 역시 자네의 고향이니 마음 편히 지내도록 하게.', `FemaleText_loc4`='德雷克塔尔是我们的忠诚伙伴，灵魂保佑你，老朋友。这里也是你的家，请随意点。', `FemaleText_loc5`='德雷克塔爾，永遠對我們的族人忠誠。亡靈庇佑你，老友。這也是你的家，請隨意。', `FemaleText_loc7`='Drek''Thar, siempre fiel a nuestro pueblo. Que los espíritus te bendigas, viejo amigo. Haz como en tu casa. Eres $gbienvenido:bienvenida;.' WHERE `ID`=17104;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 화염의 힘을 흡수합니다.', `MaleText_loc4`='%s吸收了本次攻击的火焰能量。', `MaleText_loc5`='%s吸收了攻擊的火焰能量。', `MaleText_loc7`='%s absorbe la energía de fuego del ataque.' WHERE `ID`=17105;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 냉기의 힘을 흡수합니다.', `MaleText_loc4`='%s吸收了本次攻击的冰霜能量。', `MaleText_loc5`='%s吸收了攻擊的冰霜能量。', `MaleText_loc7`='%s absorbe la energía de escarcha del ataque.' WHERE `ID`=17106;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 자연의 힘을 흡수합니다.', `MaleText_loc4`='%s吸收了本次攻击的自然能量。', `MaleText_loc5`='%s吸收了攻擊的自然能量。', `MaleText_loc7`='%s absorbe la energía de naturaleza del ataque.' WHERE `ID`=17107;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 어둠의 힘을 흡수합니다.', `MaleText_loc4`='%s吸收了本次攻击的暗影能量。', `MaleText_loc5`='%s吸收了攻擊的暗影能量。', `MaleText_loc7`='%s absorbe la energía de las Sombras del ataque.' WHERE `ID`=17108;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 비전의 힘을 흡수합니다.', `MaleText_loc4`='%s吸收了本次攻击的奥术能量。', `MaleText_loc5`='%s吸收了攻擊的秘法能量。', `MaleText_loc7`='%s absorbe la energía arcana del ataque.' WHERE `ID`=17109;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 성스러운 힘을 흡수합니다.', `MaleText_loc4`='%s吸收了本次攻击的神圣能量。', `MaleText_loc5`='%s吸收了攻擊的神聖能量。', `MaleText_loc7`='%s absorbe la energía sagrada del ataque.' WHERE `ID`=17110;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스랄 님, 혼자 가시는 게 좋겠습니다. 이 늙은이가 선견자들에게 한두 가지 조언을 해 줄 수 있을 것 같군요.', `MaleText_loc4`='萨尔，你应该单独过去。也许这位老萨满祭司可以教给那些先知一点东西。', `MaleText_loc5`='索爾，你應該獨自前往。或許這個老薩滿可以教那些先知一點東西。', `MaleText_loc7`='Thrall, deberías ir solo. Quizás este viejo chamán pueda enseñar un par de cosas a esos clarividentes.' WHERE `ID`=17111;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 늙은이는 번개의 후예들과 함께 머물 것이니 도움이 필요하시면 언제든지 오십시오.', `MaleText_loc4`='如果你需要我伸出援手的话，我随时愿意为闪电之子效劳。', `MaleText_loc5`='如果你需要我的幫忙我會和閃電之子在一起。', `MaleText_loc7`='Estaré con los Hijos del Rayo si necesitas mis servicios.' WHERE `ID`=17112;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런가요, 대모님...', `MaleText_loc4`='祖母……我是不是……', `MaleText_loc5`='主母...我...', `MaleText_loc7`='Abuela... Estoy...' WHERE `ID`=17113;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='휠러 아저씨가 여행자들을 속여 브나르 마나괴철로로 보내려고 하다니... 믿을 수가 없군!', `MaleText_loc4`='我不敢相信，维勒老爹觉得他可以把进入法力熔炉：布纳尔内的所有人骗出来！', `MaleText_loc5`='我不敢相信威勒老爹認為他能誘騙任何人進入法力熔爐巴納爾!', `MaleText_loc7`='No puedo creer que Papá Ruedas piense de verdad que va a engañar alguien para que vaya a la Forja de Maná de B''naar.', `FemaleText_loc1`='휠러 아저씨가 여행자들을 속여 브나르 마나괴철로로 보내려고 하다니... 믿을 수가 없군!', `FemaleText_loc4`='我不敢相信，维勒老爹觉得他可以把进入法力熔炉：布纳尔内的所有人骗出来！', `FemaleText_loc5`='我不敢相信威勒老爹認為他能誘騙任何人進入法力熔爐巴納爾!', `FemaleText_loc7`='No puedo creer que Papá Ruedas piense de verdad que va a engañar alguien para que vaya a la Forja de Maná de B''naar.' WHERE `ID`=17114;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번 근무 시간이 끝나면 다른 요원들을 불러 모아 그곳으로 가봐야 하려나?', `MaleText_loc4`='也许我应该召集其他人，在这次变动后向那里出发？', `MaleText_loc5`='或許我該在這次輪班之後召集一些其他的密探前往那裡?', `MaleText_loc7`='¿Quizás debería reunir a otros agentes y dirigirme allí después de este turno?', `FemaleText_loc1`='이번 근무 시간이 끝나면 다른 요원들을 불러 모아 그곳으로 가봐야 하려나?', `FemaleText_loc4`='也许我应该召集其他人，在这次变动后向那里出发？', `FemaleText_loc5`='或許我該在這次輪班之後召集一些其他的密探前往那裡?', `FemaleText_loc7`='¿Quizás debería reunir a otros agentes y dirigirme allí después de este turno?' WHERE `ID`=17115;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠, 비전 파멸자는 정말 강하지. 휠러 아저씨는 자신이 뭘 요구하고 있는지 알기는 하는 건가?', `MaleText_loc4`='唔，奥术歼灭者非常厉害，我怀疑维勒老爹是否知道他在悬赏什么？', `MaleText_loc5`='嗯，秘法殲滅者還滿堅固的。我懷疑威勒老爹知不知道他要的是什麼?', `MaleText_loc7`='Mmm. Los aniquiladores Arcanos son bastante duros. Me pregunto si Papá Ruedas sabe lo que está pidiendo.', `FemaleText_loc1`='흠, 비전 파멸자는 정말 강하지. 휠러 아저씨는 자신이 뭘 요구하고 있는지 알기는 하는 건가?', `FemaleText_loc4`='唔，奥术歼灭者非常厉害，我怀疑维勒老爹是否知道他在悬赏什么？', `FemaleText_loc5`='嗯，秘法殲滅者還滿堅固的。我懷疑威勒老爹知不知道他要的是什麼?', `FemaleText_loc7`='Mmm. Los aniquiladores Arcanos son bastante duros. Me pregunto si Papá Ruedas sabe lo que está pidiendo.' WHERE `ID`=17116;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서보의 결함 때문에 X-52 황천 로켓 건설이 지연되어서는 안 된다고!', `MaleText_loc4`='我们不能让一个失败的系统延缓X-52虚空火箭的建造！', `MaleText_loc5`='我們不能讓一個壞掉的伺服電動機拖垮了X-52虛空火箭的建造進度!', `MaleText_loc7`='¡No podemos permitir que un servo defectuoso retrase la construcción del cohete abisal X-52!', `FemaleText_loc1`='서보의 결함 때문에 X-52 황천 로켓 건설이 지연되어서는 안 된다고!', `FemaleText_loc4`='我们不能让一个失败的系统延缓X-52虚空火箭的建造！', `FemaleText_loc5`='我們不能讓一個壞掉的伺服電動機拖垮了X-52虛空火箭的建造進度!', `FemaleText_loc7`='¡No podemos permitir que un servo defectuoso retrase la construcción del cohete infernal X-52!' WHERE `ID`=17117;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여러분! 이쪽으로 오셔서 이 현상 수배 전단을 한번 봐주십시오! 정말 믿을 수 없을 겁니다!', `MaleText_loc4`='嗨！到这来看看这张通缉令，你不会相信你的眼睛！', `MaleText_loc5`='嘿!過來這裡看看這個懸賞告示。你會不敢相信!', `MaleText_loc7`='¡Eh! ¡Ven aquí y mira este cartel de Se busca! ¡No te lo vas a creer!', `FemaleText_loc1`='여러분! 이쪽으로 오셔서 이 현상 수배 전단을 한번 봐주십시오! 정말 믿을 수 없을 겁니다!', `FemaleText_loc4`='嗨！到这来看看这张通缉令，你不会相信你的眼睛！', `FemaleText_loc5`='嘿!過來這裡看看這個懸賞告示。你會不敢相信!', `FemaleText_loc7`='¡Eh! ¡Ven aquí y mira este cartel de Se busca! ¡No te lo vas a creer!' WHERE `ID`=17118;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기계 부품을 넘치도록 가진 이웃이 주위에 널려 있어서 정말 다행스러워.', `MaleText_loc4`='好消息是，我们周围都是有着多余机械部件的邻居。', `MaleText_loc5`='好消息是我們被鄰居和過量的機械零件所包圍。', `MaleText_loc7`='Es una suerte que estemos rodeados de vecinos con excedentes de piezas de repuesto.', `FemaleText_loc1`='기계 부품을 넘치도록 가진 이웃이 주위에 널려 있어서 정말 다행스러워.', `FemaleText_loc4`='好消息是，我们周围都是有着多余机械部件的邻居。', `FemaleText_loc5`='好消息是我們被鄰居和過量的機械零件所包圍。', `FemaleText_loc7`='Es una suerte que estemos rodeados de vecinos con excedentes de piezas de repuesto.' WHERE `ID`=17119;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그래, 맞구나. 네 당당한 걸음걸이는 아비를 닮았구나. 네 아비도 너처럼 어깨가 참으로 넓었지. 오, 그 강렬한 눈은 네 어미를 닮았구나.', `FemaleText_loc4`='是的，你的一举一动就像我的儿子那样。你有着他那宽厚的肩膀——啊，还有你母亲那犀利的目光。', `FemaleText_loc5`='沒錯，你的動作就像我的兒子一樣。你有他寬闊的肩膀 - 啊，還有你母親銳利的眼神。', `FemaleText_loc7`='Sí, te mueves como mi hijo. Tienes sus anchos hombros... ahh, y los fieros ojos de tu madre.' WHERE `ID`=17120;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그들이...', `FemaleText_loc4`='他们还……', `FemaleText_loc5`='他們...', `FemaleText_loc7`='Son...' WHERE `ID`=17121;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 부모님께선... 살아남지 못하셨습니다, 대모님. 두 분께선 제가 태어난 직후 돌아가셨지요. 저는 부모님에 대해 아는 게 전혀 없습니다. 저는 노예로 자랐고 지금까지 저는 스랄이라는 이름으로 살아 왔습니다.', `MaleText_loc4`='他们……没有，祖母。他们在我出生后不久就被杀害了。我从来都没有见过他们。我是作为一个奴隶长大的。我这个名字的意思，就是“奴隶”。', `MaleText_loc5`='他們...沒有，主母。他們在我出生後沒多久就被殺了。我從未見過他們。我被當做奴隸養大的。直到今天，我一直被叫做索爾。', `MaleText_loc7`='Ellos... no... Abuela. Murieron poco después de que yo naciese. Nunca les conocí. Crecí como un esclavo. Hasta este día, me he llamado Thrall.' WHERE `ID`=17122;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너는 듀로탄의 아들이 틀림없구나... 내 손자야. 드라카가 네 아비와 함께 이 세계를 떠나기 전에 아이가 있다는 말을 했었지. 하지만 난 그 둘이 살아남을 거라는 생각은 꿈에도 하지 못했단다...', `FemaleText_loc4`='不用怀疑，你是杜隆坦的后代……我的孙子。德拉卡在和你父亲离开我们的世界前告诉我她有了孩子，但是我从没有想到他们可以生存下来……', `FemaleText_loc5`='毫無疑問 - 你是杜洛坦的繼承人...我的孫子。崔卡告訴我她和你父親離開人世前有個孩子，但我作夢也沒想到他們還活著...', `FemaleText_loc7`='No hay duda... eres el heredero de Durotan... mi nieto. Draka me dijo que estaba embarazada antes de que ella y tu padre dejasen este mundo, pero nunca me atreví a soñar con que hubiesen sobrevivido...' WHERE `ID`=17123;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그분들께선 명예로운 죽음을 맞이하셨습니다, 대모님.', `MaleText_loc4`='他们的死充满荣耀，祖母。', `MaleText_loc5`='他們死的很光榮，主母。', `MaleText_loc7`='Murieron con honor, Abuela.' WHERE `ID`=17124;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 아버지나 어머니에 대해 아는 게 전혀 없습니다. 오그림이 제 부모님과 부모님이 드레노어로 여행을 갔던 일에 대해 많은 얘기를 해 줬습니다. 그는 저에게 가장 훌륭한 스승이자 가장 친한 친구였습니다, 대모님. 그는 영웅에게 어울리는 죽음을 맞이했습니다... 그들은 모두 영웅으로서 전사했으며 그들을 위한 명예의 노래가 남아 있습니다.', `MaleText_loc4`='我一点也不熟悉我的父亲或者母亲。奥格瑞姆跟我说过很多关于他们的故事和他们在德拉诺的冒险经历。他是我最好的老师和最亲密的朋友，祖母。他像个英雄般地死去了……他们都像英雄般地死去了，荣耀的战歌为他们奏响。', `MaleText_loc5`='我從不知道我的父親或母親是誰。奧格林和我說過許多他們的故事還有在德拉諾的冒險。他是我最棒的導師和最好的朋友，主母。他是個英雄...他們全都是英雄，為向他們致敬，一首榮耀之歌永遠流傳著。', `MaleText_loc7`='Nunca conocí a mi padre ni a mi madre. Orgrim me contó muchas historias sobre ellos y sus aventuras en Draenor. Fue mi mejor maestro y mi más querido amigo, Abuela. Murió como el héroe que fue... Todos murieron como héroes y, por todos ellos, permanece un canto de honor.' WHERE `ID`=17125;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네 이름이 스랄이라고? 네가 노예로 지낸 건 다 과거일 뿐이다, 손자야! 하지만 더는 아니란다! 듀로탄을 마지막으로 만났을 때 듀로탄은 아직 태어나지 않은 아이의 이름을 알려줬었지... 듀로탄이... 정말 자랑스러워했는데...', `FemaleText_loc4`='萨尔？你只是过去是一个奴隶，孙子！你再也不会是奴隶了！当我最后一次看到杜隆坦的时候，他把还没出生的儿子的名字都想好了……他是……那么的自豪……', `FemaleText_loc5`='索爾?你只是過去的一個奴隸而已，孫子!但是不會再發生了!我上次見到他的時候，杜洛坦告訴我他要為他尚未出生的兒子取什麼名字...他是...那麼的驕傲...', `FemaleText_loc7`='¿Thrall? ¡Has sido un esclavo del pasado, querido nieto! ¡Pero ya no lo serás jamás! Cuando le vi por última vez, Durotan me dijo el nombre que le pondría a su hijo... Estaba tan... orgulloso...' WHERE `ID`=17126;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대모님께서도 들어보셨을 겁니다.', `MaleText_loc4`='但是您肯定听说了，祖母。', `MaleText_loc5`='但你肯定聽過，主母。', `MaleText_loc7`='Seguro que ya lo sabes, Abuela.' WHERE `ID`=17127;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 가장 위대한 영웅은 세상을 떠나셨습니다. 우리 모두를 구한 것이 바로 그롬 님이셨지요... 그가 만노로스를 쓰러뜨리고 피의 저주를 영원히 끝냈을 때 저는 그분의 옆을 지켰습니다.', `MaleText_loc4`='我们最伟大的英雄去世了。那就是拯救我们全族的格罗姆……我和他并肩而战，最后他打倒了玛诺洛斯，永远地终结了我们的诅咒。', `MaleText_loc5`='他是我們最偉大的英雄。是葛羅解放了我們所有人...當他擊敗瑪諾洛斯並永遠終止詛咒時我就在他身邊。', `MaleText_loc7`='Murió siendo nuestro héroe más grande. Fue Grom quien nos liberó a todos... Yo estaba a su lado cuando venció a Mannoroth y puso fin a la maldición.' WHERE `ID`=17128;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='축복받은 영혼이여! 20년 동안 우리는 모두 맨 처음 저주받은 피의 잔을 들이키고 우리 종족을 파멸로 이끈 것이 바로 그롬이라고 알고 있었는데... 그의 아들인 가로쉬 역시 그렇게만 알고 있었고...', `FemaleText_loc4`='天哪！二十年以来，我们只知道是格罗姆第一个喝下诅咒之杯内的东西，把诅咒带给了我们的人民……那是他儿子加尔鲁什唯一知道的事实。', `FemaleText_loc5`='神聖的亡靈!二十年來，我們只知道葛羅是第一個用那個被詛咒的酒杯飲酒並把毀滅帶給我們族人的人...這是他的兒子，卡爾洛斯所知道的唯一真相。', `FemaleText_loc7`='¡Benditos espíritus! Durante veinte años todo lo que supimos fue que Grom fue el primero en beber del cáliz maldito y llevar la condenación a nuestro pueblo... Es la única verdad que su hijo, Garrosh, ha conocido.' WHERE `ID`=17129;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벌목기 녀석들?! 벌목기들이 더는 벌목을 하지 않으려고 하지. 어제도 그랬다니까!$B$B로켓을 완성하려면, X-52를 발사하려면 더 뛰어난 기술이 필요하다네!', `MaleText_loc4`='收割机？！它们不管用了，实在太落伍了。$B$B如果我们要制造火箭——如果我们要让X-52离开地面——我们就需要更尖端的技术！', `MaleText_loc5`='伐木機?!它們不會再切割了。它們已經過時了!$B$B如果我們要建造火箭 - 如果我們要讓X-52升空 - 我們就需要更好的技術!', `MaleText_loc7`='¡¿Trituradoras?! Ya no sirven. ¡Están muy pasadas de moda!$B$BSi vamos a construir cohetes... si vamos a hacer que el X-52 despegue... ¡necesitamos la mejor tecnología!' WHERE `ID`=17130;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='손자야, 네가... 네가 가로쉬에게 그의 아버지가 네게 했던 말을 전해주지 않겠니?', `FemaleText_loc4`='孙子，你会……你会把你所告诉我的关于他父亲的一切都告诉加尔鲁什吗？', `FemaleText_loc5`='孫子，你可以...你可以告訴卡爾洛斯你和我說的關於他父親的事嗎?', `FemaleText_loc7`='Nieto... ¿Puedes decirle a Garrosh lo que me contaste sobre su padre?' WHERE `ID`=17131;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가로쉬에게 알려 주란 말이십니까? 대모님, 가로쉬의 아버지는 우리 모두를 피의 저주에서 벗어나게 하려고 목숨을 잃었습니다. 저는 아무 말도 하지 않을 겁니다. 대신 헬스크림 님의 의지를 의심하는 모든 이들과 가로쉬에게 그롬 헬스크림이라는 영웅이 모든 오크들을 위해 어떻게 생을 마감했는지 보여 주겠습니다!', `MaleText_loc4`='告诉他？祖母，他父亲的死让我们都从血之诅咒中解脱了。我什么都不会告诉他。我会让他亲眼看看！让他和那些置疑格罗姆决心的家伙看看，格罗姆为整个兽人氏族做过些什么！', `MaleText_loc5`='告訴他?主母，那孩子的父親死去我們才能不受血咒威脅而生活。我不會告訴他的。我會讓他知道!讓他和所有懷疑地獄吼決心的人知道葛羅·地獄吼為所有獸人做的一切!', `MaleText_loc7`='¿Decírselo? Abuela, el padre del chico murió para que todos nosotros pudiéramos vivir sin el peso de la maldición de la sangre. No le diré nada. ¡Se lo enseñaré! Se lo enseñaré a él y a cualquiera que dude de lo que Grom Grito Infernal hizo exactamente por todos los orcos.' WHERE `ID`=17132;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠시 자리를 비우겠습니다, 대모님. 이 손자 곧 돌아오도록 하겠습니다.', `MaleText_loc4`='请原谅，祖母。我很快就回来。', `MaleText_loc5`='請原諒我，主母。我很快就會回來。', `MaleText_loc7`='Perdóname, Abuela. Volveré pronto.' WHERE `ID`=17133;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헬스크림의 아들 가로쉬여, 그대의 아버지는 우리의 가장 위대한 영웅으로 살다 가셨소. 그대의 아버지가 어떤 희생으로 우리를 악마의 손아귀에서 풀어 주었는지, 그대에게 보여 주는 영광을 허락해 주시오.', `MaleText_loc4`='加尔鲁什，地狱咆哮之子，你的父亲是我们最伟大的英雄。请允许我为你展示一下，你父亲为了让我们免受恶魔的控制而做出的牺牲。', `MaleText_loc5`='卡爾洛斯，地獄吼之子，你父親生前死後都是我們最偉大的英雄。請容許我讓你看看你父親所做的犧牲，這樣我們才能免於惡魔的掌控而生存。', `MaleText_loc7`='Garrosh, hijo de Grito Infernal, tu padre vivió y murió siendo nuestro más glorioso héroe. Hónrame permitiéndome mostrarte lo que tu padre sacrificó para que todos pudiéramos vivir libres del demonio.' WHERE `ID`=17134;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋습니다, 듀로탄의 아들 스랄이여.', `MaleText_loc4`='如你所愿，萨尔，杜隆坦之子。', `MaleText_loc5`='如你所願，索爾，杜洛坦之子。', `MaleText_loc7`='Como quieras, Thrall, hijo de Durotan.' WHERE `ID`=17135;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정령들이여, 내게 힘을 주소서! 이 오랜 상처로부터 내 영혼을 가져가 모든 이들이 볼 수 있도록 해주소서! 헬스크림의 아들이 자신의 아버지에 대해 알 수 있게 해주소서! 온 백성에게 누가 자신들을 구원해 줬는지 알게 해주소서!', `MaleText_loc4`='灵魂们，赐予我力量吧！从我的灵魂中抽出那些旧日的伤痛，让所有人都看看！让这个孩子了解他的父亲！让这些人认识他们的救世主！', `MaleText_loc5`='亡靈給我力量!從我的靈魂中拿走這些舊創傷，並讓世人都看見它們!讓這個孩子認識他的父親!讓這些人認識他們的救星!', `MaleText_loc7`='¡Espíritus, dadme fuerzas! ¡Llevaos estas viejas heridas de mi alma y haced que todos las vean! ¡Que esta criatura conozca a su padre! ¡Que este pueblo conozca a su salvador!' WHERE `ID`=17136;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 비웃습니다.', `MaleText_loc4`='%s笑了。', `MaleText_loc5`='%s大笑。', `MaleText_loc7`='%s ríe.' WHERE `ID`=17137;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예상대로군. 네가 올 줄 알았다. 위대하신 헬스크림도 함께 오셨군.', `MaleText_loc4`='在我意料之中。我知道你会来这里，而且我看到你把强大的地狱咆哮也带来了。', `MaleText_loc5`='如我所料。我就知道你會來。我還看見你帶了強大的地獄吼過來。', `MaleText_loc7`='Qué previsible. Sabía que vendrías. Veo que traes contigo al gran Grito Infernal.' WHERE `ID`=17138;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그놈의 피는 내 것이다. 태생부터 천한 네 종족이 그렇듯...', `MaleText_loc4`='他的血是我的，你们整个卑贱的种族都是我的！', `MaleText_loc5`='他的血是我的，你們整個卑賤的種族都是我的!', `MaleText_loc7`='Su sangre es mía; igual que toda tu impura raza.' WHERE `ID`=17139;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 반항하며 울부짖습니다.', `MaleText_loc4`='%s挑衅地咆哮着。', `MaleText_loc5`='%s反抗的怒吼。', `MaleText_loc7`='%s ruge desconfiado.' WHERE `ID`=17140;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노력은 가상하다만 아무 소용없다.', `MaleText_loc4`='勇敢的尝试，但是毫无意义。', `MaleText_loc5`='勇敢的嘗試，但是毫無意義。', `MaleText_loc7`='Un esfuerzo digno, pero inútil.' WHERE `ID`=17141;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스랄은 네가 구원받을 수 있다고 믿더군. 하지만, 그는 네 영혼 속에서 무엇이 불타고 있는지 알 수 없지. 가슴 속은 너도 알다시피 우린 똑같아...', `MaleText_loc4`='这个孩子相信他能够挽救你，但他不知道是什么在你的灵魂中燃烧。你心里很清楚，你我都是一样的。', `MaleText_loc5`='這個孩子相信他能夠挽救你，但他不知道是什麼在你的靈魂中燃燒。你心裡很清楚，你我都是一樣的。', `MaleText_loc7`='El chico pensaba que podías redimirte, pero no sabía lo que ardía en tu alma; porque en el fondo, sabes que somos iguales.' WHERE `ID`=17142;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 블러드 엘프의 통제에서 벗어납니다!', `MaleText_loc4`='%s逃脱了血精灵的控制！', `MaleText_loc5`='%s掙脫了血精靈的控制!', `MaleText_loc7`='%s se libera del control del elfo de sangre.' WHERE `ID`=17143;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안돼!', `MaleText_loc4`='不！不！', `MaleText_loc5`='不!', `MaleText_loc7`='¡Nooo!' WHERE `ID`=17144;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='식사가 준비됐다! 남김없이 먹어라. 긴 하루가 될 것이다.', `MaleText_loc4`='汤做好了！快点吃。我们还有很长的路要赶。', `MaleText_loc5`='湯來了，弟兄們!快吃。我們還有很多事要做。', `MaleText_loc7`='¡Ha llegado la sopa, muchachos! Comed. Nos espera un día largo.' WHERE `ID`=17145;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자 그럼, 이 기술이 어떤 원리로 작동하는지 알아볼까!', `MaleText_loc4`='好吧，让我们看看这技术的诀窍！', `MaleText_loc5`='好了，讓我們來看看這個技術厲害在哪裡!', `MaleText_loc7`='Muy bien, ¡veamos cómo es realmente!' WHERE `ID`=17146;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 뭘 알아야 하는지 긴 진공관 분석기가 알려줘야 한단 말이야.', `MaleText_loc4`='长管零件分析器应该会告诉我需要知道些什么。', `MaleText_loc5`='長管機件分析器應該會告訴我要知道的東西。', `MaleText_loc7`='El analizador de espectro de tubo largo debería decirme lo que necesito saber.' WHERE `ID`=17147;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정렬하라! 훈련 시간이다!', `MaleText_loc4`='集合！开工了！', `MaleText_loc5`='弟兄們，列隊!該開始操練了!', `MaleText_loc7`='¡Todos dentro! ¡Es hora de perforar!' WHERE `ID`=17148;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악, 부서졌군! 전력을 너무 강하게 설정한 걸까? 게다가 거의 휠러 자동차를 부셔놨군! 이크, 저 영감에게 말하지 말라고!', `MaleText_loc4`='啊，碎了！难道是我把能量值设置得太高了？它差点就击中了维勒动力机！呀，不要告诉他！', `MaleText_loc5`='哎，崩潰!我想我把能量設定的太高了?它差一點就要擊中偉勒汽車!哎呀，別告訴他 !', `MaleText_loc7`='¡Vaya, desintegrado! Quizás tenía la potencia demasiado alta... ¡Y casi me cargo el móvil Ruedas!' WHERE `ID`=17149;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스랄... 피의 안개가 걷혔네.', `MaleText_loc4`='萨尔……血液的诅咒已经消失。', `MaleText_loc5`='索爾...血液的魔性已經消散了。', `MaleText_loc7`='Thrall... La bruma de sangre ha desaparecido.' WHERE `ID`=17150;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피의 저주가 사라지자 그롬의 눈이 흐려집니다.', `MaleText_loc4`='由于血之诅咒被消除，格罗姆的眼睛变得暗淡了。', `MaleText_loc5`='當血的詛咒升起，葛羅的眼神變的暗淡。', `MaleText_loc7`='Los ojos de Grom se aclaran y la maldición desaparece.' WHERE `ID`=17151;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='몸 안에서 흐르던 악마의 불꽃은 모두 꺼져버렸네... 이제야 내 자신의 속박을 풀었다네.', `MaleText_loc4`='恶魔的火焰不再灼烧着我的躯体。我……解放了自己。', `MaleText_loc5`='惡魔的火焰不再灼燒我的軀體。我...解放了自己。', `MaleText_loc7`='El fuego del demonio ya no corre por mis venas. Me he... liberado.' WHERE `ID`=17152;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니오. 당신은 우리 모두의 속박을 풀어주었소.', `MaleText_loc4`='不，老朋友。你解放了我们所有人。', `MaleText_loc5`='不，老朋友。你解放了我們所有人...', `MaleText_loc7`='No, viejo amigo. Nos has liberado a todos.' WHERE `ID`=17153;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법사님, 당신의 이름을 속삭이는 소리를 들었습니다. 당신은 누구이십니까?', `MaleText_loc4`='我只在一些低声的私语中听说过你的名字，法师。你是谁？', `MaleText_loc5`='我只有在私語中聽過別人提起你的名字，法師。你是誰?', `MaleText_loc7`='Siempre he oído tu nombre entre susurros, mago. ¿Quién eres?', `FemaleText_loc1`='마법사님, 당신의 이름을 속삭이는 소리를 들었습니다. 당신은 누구이십니까?', `FemaleText_loc4`='我只在一些低声的私语中听说过你的名字，法师。你是谁？', `FemaleText_loc5`='我只有在私語中聽過別人提起你的名字，法師。你是誰?', `FemaleText_loc7`='Siempre he oído tu nombre entre susurros, mago. ¿Quién eres?' WHERE `ID`=17154;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 돌아가신 수호자 메디브 님의 제자였던 카드가라고 하오. 당신도 그분의 이름을 들어본 적은 있을 거요.$B$B메디브 님이 악마 살게라스의 지배를 받고 있으며 이 세계와 아제로스를 연결하는 어둠의 문을 열었다는 사실을 밝혀낸 것이 바로 나요. 정말 존경했지만 그분의 고통받는 영혼을 구원하려면 스승님을 죽일 수밖에 없었소.', `MaleText_loc4`='我是卡德加，堕落的守护者麦迪文曾经的学徒。我相信你以前肯定听说过这个名字。$B$B是我发现麦迪文被邪恶的萨格拉斯支配，然后他就开启了这个世界和艾泽拉斯之间的黑暗之门。尽管我尊重我的主人，但我被迫消灭了他，让他痛苦的灵魂得到了解脱。', `MaleText_loc5`='我是卡德加，死去的守護者，麥迪文的舊時學徒。我相信你一定聽過他的名字。$B$B是我發現麥迪文被邪惡者，薩格拉斯支配著 - 他還開啟了這個世界和艾澤拉斯間的黑暗之門。雖然我尊敬我的大師，我還是被迫殺了他，讓他受折磨的靈魂安息。', `MaleText_loc7`='Soy Khadgar, antiguo aprendiz del guardián caído, Medivh. Seguro que has oído su nombre antes.$B$BYo fui quien descubrió que Medivh había estado poseído por el Maligno, Sargeras, y que había abierto El Portal Oscuro entre este mundo y Azeroth. Si bien honraba a mi maestro, me vi obligado a matarle y desterrar su alma torturada.' WHERE `ID`=17155;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇군요.', `MaleText_loc4`='我明白了。', `MaleText_loc5`='我懂了。', `MaleText_loc7`='Ya veo.', `FemaleText_loc1`='그렇군요.', `FemaleText_loc4`='我明白了。', `FemaleText_loc5`='我懂了。', `FemaleText_loc7`='Ya veo.' WHERE `ID`=17156;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 아제로스에서 호드를 몰아낼 당시 나는 안두인 로서 경과 함께 싸웠소. 나는 메디브께서 남긴 유산의 계승자로서 거칠 것이 없었소.$B$B마침내 이 끔찍한 세계를 정벌하고 사악한 오크들에게 종말을 고하라는 명령이 내려왔을 때 나는 동료인 투랄리온, 알레리아, 다나스, 쿠르드란과 함께 전진했소.', `MaleText_loc4`='我和安度因·洛萨爵士并肩战斗，把部落从我们艾泽拉斯驱逐了出去。作为麦迪文遗产的继承人，我只能这么做。$B$B当联盟最终决定远征这个阴森的世界，永久终止兽人的邪恶时，我和我的朋友图拉扬、奥蕾莉亚、达纳斯和库德兰挺身而出。', `MaleText_loc5`='我在安杜因·洛薩身邊作戰，把部落從我們艾澤拉斯的土地上趕走。身為麥迪文的遺產繼承人，我不能鬆懈。$B$B當戰爭終於入侵這個可怕的世界 - 並且永遠結束獸人的罪惡 - 我和我的朋友圖拉揚、艾蘭里亞、達納斯和庫德蘭向前跨了一步。', `MaleText_loc7`='Yo luché junto a Lord Anduin Lothar cuando conseguimos expulsar a la Horda de nuestras tierras, en Azeroth. Como heredero del legado de Medivh, no podía hacer otra cosa.$B$BCuando finalmente llegó el momento de invadir este sombrío mundo, y acabar con el mal de los orcos para siempre, di un paso al frente junto a mis amigos Turalyon, Alleria, Danath y Kurdran.' WHERE `ID`=17157;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동료와 나는 인간 종족 중에 가장 위대하고 헌신적인 분을 기리는 의미로 우리 스스로 로서의 후예들이라 칭했소. 우리는 넬쥴을 꺾고 그 광기를 잠재우려고 사력을 다했소.$B$B이 세계가 운이 다해 붕괴했을 때 우리가 사랑하는 아제로스에 피해가 가는 일이 없도록 어둠의 문을 파괴했소.', `MaleText_loc4`='我和我的伙伴们称自己为洛萨之子，以此来对我们所认识的最无私和最伟大的人表示尊敬。我们用尽全力击败耐奥祖，结束了他的疯狂。$B$B当这个被诅咒的世界在我们身边崩塌时，我们破坏了黑暗之门，以阻止更多的伤害降临到我们所深爱着的艾泽拉斯。', `MaleText_loc5`='我和我的同伴自稱洛薩之子 - 向我們所認識最偉大，最無私的人致敬。我們盡了全部的力量擊敗耐祖奧並結束他的瘋狂。$B$B當這個注定失敗的世界在我們身邊崩塌，我們粉碎了黑暗之門以阻止更多傷害降臨在我們摯愛的艾澤拉斯。', `MaleText_loc7`='Mis camaradas y yo nos hicimos llamar los Hijos de Lothar, en honor al hombre más bondadoso y desinteresado que jamás conocimos. Hicimos todo lo que pudimos por derrotar a Ner''zhul y poner fin a la locura.$B$BCuando este mundo condenado se derrumbó a nuestro alrededor, destruimos El Portal Oscuro para evitar que algún otro mal pudiese caer sobre nuestro amado Azeroth.' WHERE `ID`=17158;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 파괴된 황무지에 갇힌 우리는 살아남고자 최선의 노력을 다했소. 그렇게 세월이 흐르던 중 우리는 뒤틀린 황천에서 새로운 악마가 다가오고 있다는 것을 감지했소. 사악한 오크들보다도 더욱 끔찍하고 이 아웃랜드를 점령하려는 야심을 품은 그들이 바로... 불타는 군단이었소.', `MaleText_loc4`='我们被困在了这个破碎的世界，并努力生存了下来。随着时间的流逝，我们感觉到一股新的邪恶力量正在从扭曲虚空靠近我们，包围我们。那就是比黑暗的兽人更邪恶、想要占据外域的燃烧军团。', `MaleText_loc5`='我們被困在這塊破碎的荒野，盡了全力生存下來。時間過去，我們感應到一個新的禍害正從扭曲虛空中包圍我們。比黑暗獸人更邪惡 - 是燃燒軍團想掌控這個...外域。', `MaleText_loc7`='Atrapados en ese erial, hicimos lo que pudimos por sobrevivir. Con el tiempo, sentimos que una nueva maldad nos rodeaba desde El Vacío Abisal. Peor que los orcos malignos... Era la Legión Ardiente que pretendía tomar... Terrallende.' WHERE `ID`=17159;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동료가 심연을 넘어 침입해온 악마들을 막는 동안 나는 마법을 사용하여 끝없는 어둠 너머에 도착했소. 그곳에서 나는 절대적인 성스러움과 순수함을 간직한 존재, 바로 거대한 빛 자체를 느꼈소.$B$B내가 발견한 것은 아달과 그의 나루였소. 그것은 한마디로... 기적이었소.', `MaleText_loc4`='当我的同伴在坚定不移地对抗逐渐逼近的黑暗时，我使用魔法进入了遥远的宇宙。在那里，我感受到了一种具有无穷圣光之力的生物……$B$B那就是阿达尔和他的纳鲁。那只能说是个……奇迹。', `MaleText_loc5`='當我的同伴守住黑暗入侵的戰線時，我利用我的魔法進入渾沌黑暗。在那裡，我感應到廣大聖光的生命 - 具有深不可測的純淨。$B$B我發現的是阿達歐和他的那魯。這簡直就是...奇蹟。', `MaleText_loc7`='Mientras que mis camaradas aguantaban en el límite de la creciente oscuridad, utilicé mi magia para llegar a la Gran Oscuridad del Más Allá. Allí, pude sentir seres con una gran Luz y de insondable pureza.$B$BY encontré a A''dal y a sus naaru. Fue como... un milagro.' WHERE `ID`=17160;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<싱긋 웃는 카드가>$B$B나는 아달과 그의 동족을 설득하여 이곳으로 돌아왔소. 이 우주에서 불타는 군단을 몰아낼 수 있는 것은 그들뿐이라고 믿고 있소. 하지만, 먼저 그들의 힘이 우리 가슴속에 자리잡아야 하오. 당신도 곧 알게 되겠지만...$B$B악에 맞서 싸우려면 우리 스스로 그들의 영원한 빛을 밝히는 봉화가 되어야 하오.', `MaleText_loc4`='<卡德加笑了笑。>$B$B我劝说阿达尔和他们的伙伴们和我一起回到这里。我相信只有他们的力量可以将燃烧军团赶出这个宇宙。但是,毫无疑问，就像你很快就会认识到的那样——他们的力量首先必须在我们的心中扎根。$B$B为了和黑暗进行斗争，我们必须成为他们永恒圣光的灯塔。', `MaleText_loc5`='<卡德加自己露齒而笑>$B$B我說服阿達歐和他的同胞回來這裡找我。我相信只有他們的力量才能把軍團趕出這個宇宙。但你也絕對會發現 - 他們的力量必須先住在我們的心裡。$B$B要對抗黑暗，我們一定要成為他們永恆聖光的燈塔。', `MaleText_loc7`='<Khadgar sonríe para sí mismo >$B$BConvencí a A''dal y a sus hermanos para que volviesen aquí conmigo. Creo que solo su poder puede expulsar a la Legión de este universo. Pero, como descubrirás, para ello es necesario que su poder viva en nuestros corazones.$B$BPara luchar contra la oscuridad, debemos convertirnos en faros de su eterna Luz.' WHERE `ID`=17161;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배신에는 잔인한 보복이 따르게 마련이오. 샤트라스는 일리단과 캘타스로부터 무자비한 공격을 받고 있소.$B$B블러드 엘프, 나가와 뒤틀린 드레나이로 구성된 연합군이 물 밀듯 이 도시로 밀려들어 올 거요. 오직 샤타르의 힘으로 막아내는 수밖에 없소.$B$B나루에게 한 가지 분명한 사실이 있소. 불타는 군단을 추적하려면 먼저 일리단을 격파해야 한다는 거지.', `MaleText_loc4`='疯狂的复仇很快就来临了。沙塔斯城遭受着伊利丹和凯尔萨斯的无情攻击。$B$B血精灵、纳迦和破碎者的军队涌入城市，沙塔尔的力量顽强抵抗着他们。$B$B纳鲁非常明白，如果他们想要追击燃烧军团，就必须首先打败伊利丹。', `MaleText_loc5`='因為背叛產生的激烈報復緊追在後。撒塔斯城遭受伊利丹和凱爾薩斯無情的攻擊。$B$B血精靈，納迦，和破碎者的軍隊會湧入城市;只有薩塔的力量能驅逐他們。$B$B那魯清楚了一件事。如果他們要追捕軍團，就要先擊敗伊利丹。', `MaleText_loc7`='A continuación llegaron feroces represalias contra los desertores. La Ciudad de Shattrath sufrió un implacable ataque de Illidan y Kael''thas.$B$BEjércitos de elfos de sangre, nagas y Tábidos asaltaban constantemente la ciudad, solo para ser repelidos por el poder de los Sha''tar.$B$BY entonces, los naaru lo comprendieron. Si querían ir a por la Legión, primero tendrían que derrotar a Illidan.' WHERE `ID`=17162;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 털썩 주저앉습니다.', `MaleText_loc4`='%s的感情崩溃了。', `MaleText_loc5`='%s崩潰。', `MaleText_loc7`='%s se derrumba.' WHERE `ID`=17163;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 평생 내가 저주받은 피를 이어받았다고 생각해 왔소. 나는 아버지의 처절한 실패의 그늘 속에서 살고 있다고 생각했던 것이오.', `MaleText_loc4`='一直以来，我都觉得我的血统是受到诅咒的。我生活在我父亲巨大的失败阴影之下。', `MaleText_loc5`='我認為我一生的血統都被詛咒了。我一直活在我父親最大的失敗的陰影之下。', `MaleText_loc7`='Durante toda mi vida, he pensado siempre que mi linaje estaba maldito. He vivido a la sombra del mayor fracaso de mi padre.' WHERE `ID`=17164;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보다시피 샤트라스는 건재하오. 한편, ''지리''라고 하는 나루가 일리단의 본거지 바로 앞에 있는 어둠달 골짜기를 성공리에 습격했소.$B$B그곳에서 그는 알도르 사제회와 점술가 길드의 지원을 받아 일리단의 군대와 계속해서 전투를 벌이고 있소.$B$B그렇다고 해서 그 두 진영이 서로에 대한 오랜 적개심을 잊은 것은 아니지. 사실, 바로 그런 해묵은 감정 때문에 그들은 나루를 돕고자 떠나는 영광스러운 임무를 맡으려고 경쟁을 벌인다오. 매일 이 도시의 아달이 그 결정을 내리고 있소.', `MaleText_loc4`='沙塔斯城没有沦陷，就像你看到的那样。相反，那个叫做克希利的纳鲁发动了一次向影月谷——伊利丹的门阶的袭击。$B$B在那里，在奥尔多和占星者的帮助下，他持续向伊利丹的军队发动猛攻。$B$B他们争先恐后地想要为纳鲁效力，想要在纳鲁那里获得更多的荣耀。可是睿智的阿达尔却能让这两个派系维系着微妙的平衡。每一天，双方的军队都聚集在这里，等待着由阿达尔决定派遣谁到影月谷去参战。', `MaleText_loc5`='如你所見，撒塔斯沒有陷落。相反的，叫希瑞的那魯領導了一次對影月谷成功的入侵 - 那是伊利丹的大門口。$B$B有奧多爾和占卜者的協助，他持續對伊利丹發動戰爭。$B$B不過，這兩個陣營仍未化解他們的舊仇。為了被派去協助那魯的殊榮而競爭，他們的敵意依舊很深。每一天，阿達歐都會在撒塔斯這裡做出決定。', `MaleText_loc7`='Como puedes ver, Shattrath siguió en pie. Los naaru conocidos como Xi''ri prepararon una incursión con éxito al Valle Sombraluna, justo al lado de donde estaban las tropas de Illidan.$B$BAllí siguen en plena guerra con los ejércitos de Illidan con la ayuda de los Aldor y los Arúspices.$B$BSin embargo, las dos facciones todavía no han abandonado su vieja enemistad. Tal es la animosidad entre ellos que compiten por el honor de ser los enviados a ayudar a los naaru. Cada día, esa decisión la toma A''dal, justo aquí, en Shattrath.' WHERE `ID`=17165;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 아버님을 싫어했던 것은 그분께서 행하신 일 때문이오. 아버님께서 내게 넘겨주셨던 무거운 짐 때문이었던 것이지. 허나 지금은...', `MaleText_loc4`='我恨他的所作所为。我恨他，因为他把负担都留给了我。但是现在……', `MaleText_loc5`='他做的事讓我痛恨他。他留給我的重擔讓我痛恨他。但現在...', `MaleText_loc7`='Lo he odiado por lo que hizo. Lo he odiado por el peso su legado. Pero ahora...' WHERE `ID`=17166;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='듀로탄의 아들이여, 당신은 내가 알지 못했던 절대적인 신뢰가 어떤 것인지를 보여 주었소. 당신과 당신의 동맹은 어떠한 값어치로도 매길 수 없는 구원이라는 선물을 내게 주었소이다. 마그하르의 구세주 스랄이여, 당신은 그 누구도 내게 주지 못했던 명예를 가르쳐 주었소...', `MaleText_loc4`='你让我看到了我可能永远都不会知道的真相。你和你的朋友们给我带来了无价的礼物：救赎。萨尔，玛格汉的救世主，你让我感到了前所未有的荣耀……', `MaleText_loc5`='你讓我知道了永遠也不會知道的真相。你和你的盟友賜予了我一個無價的東西:救贖。索爾，瑪格哈的救星，你為我帶來的榮耀是無人能敵的...', `MaleText_loc7`='Me has enseñado verdades que jamás habría descubierto. Tú y tus aliados me habéis regalado algo que no tiene precio: la redención. Thrall, redentor de los Mag''har, me honras como nadie lo ha hecho...' WHERE `ID`=17167;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘, 내 가슴을 짓누르던 커다란 짐을 벗어 던졌소. 내 가슴은 자부심으로 충만하다오. 그리고 내 평생 처음으로 내가 누군지 떳떳하게 말할 수 있게 되었소이다. 마침내 가슴 속의 분노를 떨쳐버리게 되었단 말이오.', `MaleText_loc4`='在今天，我心中的重担终于可以放下了。我的内心充满着自豪。我有生以来第一次可以骄傲地说出我的名字，终于可以释放我心中的愤怒！', `MaleText_loc5`='在今天，我胸口的一個重擔被舉起了。我的心高漲著驕傲。第一次，我可以驕傲地說出我是誰。我終於可以宣洩心中的狂怒。', `MaleText_loc7`='En este día, mi pecho se siente liberado de un gran peso. Mi corazón se llena de orgullo. Y, por primera vez, puedo proclamar a los cuatro vientos quien soy. Ya puedo desatar la furia de mi corazón.' WHERE `ID`=17168;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 마그하르의 대족장 그롬의 아들 가로쉬 헬스크림이다! 아버지 헬스크림의 전투 함성이 그대들에게 용기와 힘을 줄 것이니! 내 자유의 함성이 그대들을 충만케 할 것이오!', `MaleText_loc4`='我是加尔鲁什·地狱咆哮，格罗姆之子，玛格汉的酋长！让地狱咆哮的战斗怒吼给予你们勇气和力量吧！', `MaleText_loc5`='我是卡爾洛斯·地獄吼，葛羅之子，他是瑪格哈的酋長!讓地獄吼的戰鬥召喚給你勇氣和力量!因我的號召而高昂。', `MaleText_loc7`='Soy Garrosh Grito Infernal, hijo de Grom, jefe de los Mag’har. ¡Que el grito de guerra de Grito Infernal os dé coraje y fuerza! ¡Que mi grito de guerra os eleve el espíritu!' WHERE `ID`=17169;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샤트라스가 승리했다는 소식이 빠르게 퍼지고 있소. 과거의 전쟁과 새로 벌어진 전쟁의 피난민들이 도시로 몰려들고 있소.$B$B현재 도시 남쪽의 3분의 1을 피난민들이 메우고 있소. 일리단을 피해서 도망친 이들을 그냥 돌려보낼 수는 없지. 그러니까 개중에 성격이 아주 괴팍한 이들을 마주칠 수도 있을 거요. 하지만, 대부분 모든 희망을 잃었다가 이제 다시 새로운 삶을 살게 된 평범한 이들이지.', `MaleText_loc4`='沙塔斯城胜利的消息很快就传开了。难民们开始重新涌入城市，现在整个贫民窟三分之一的地方都被他们占据了。没有任何一个躲避伊利丹的人会被驱逐，所以你可能会在那里遇到一两个令人讨厌的家伙。但是他们大部分都只是普通人，一些曾经绝望，但如今生命得以延续的人。', `MaleText_loc5`='撒塔斯城勝利的消息散播的很快。所有先前戰爭和新起戰爭的難民都湧入了城市。$B$B整個下部三分之一的城市都被他們佔據了。所有尋求逃過伊利丹的人都不會被驅逐，所以你或許會遇到一兩個討厭的人。但大部分來說，他們只是曾經失去所有希望，現在又被賜予了新生命的普通人而已。', `MaleText_loc7`='Las noticias de las victorias de la Ciudad de Shattrath se expandieron rápidamente. Refugiados de antiguas guerras y de la que acababa de comenzar empezaron a llegar a la ciudad.$B$BAhora, todo el tercio inferior de la ciudad está habitada por ellos. Se acepta a todo el que busque una tregua de Illidan, así que podrías encontrarte con un par de personajes indeseables allí... Pero, en la mayor parte, son solo gente normal que han perdido toda esperanza y ahora han recibido una nueva vida.' WHERE `ID`=17170;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙소, 듀로탄의 아들이여.', `MaleText_loc4`='谢谢你，杜隆坦之子。', `MaleText_loc5`='謝謝你，杜洛坦之子。', `MaleText_loc7`='Gracias, hijo de Durotan.' WHERE `ID`=17171;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 가로쉬의 어깨에 손을 얹습니다.', `MaleText_loc4`='%s把手放在加尔鲁什的肩上。', `MaleText_loc5`='%s將一隻手放在卡爾洛斯的肩膀上。', `MaleText_loc7`='%s pone una mano sobre el hombro de Garrosh.' WHERE `ID`=17172;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게 고마워할 필요 없소, 가로쉬. 그대의 아버지는 내게 친형제와도 같은 존재, 그대와 마그하르를 위한 일이라면 무엇이라도 할 것이오. 이제 나는 대모님께 돌아가야 하겠소이다.', `MaleText_loc4`='你没必要感谢我，加尔鲁什。你的父亲和我是兄弟。我会为你和玛格汉氏族做任何事。现在，我得回祖母身边去了。', `MaleText_loc5`='不用謝我，卡爾洛斯。你的父親就像我的兄弟一樣。我會為你和瑪格哈做任何事。我現在一定要回去找主母。', `MaleText_loc7`='No me lo agradezcas, Garrosh. Tu padre era como un hermano para mí. Haría lo que fuera por ti y los Mag''har. Debo volver con la Abuela.' WHERE `ID`=17173;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 그들을 위해, 혹은 그들이 꿈꾸는 이상을 위해 싸우는 것이오.$B$B이 성벽을 벗어나면 그들은 목숨을 잃을 거요. 그들도 알고 우리고 알고 있듯이... 이 세계는 캘타스, 일리단, 그리고 불타는 군단의 위협을 받고 있소.$B$B이 성벽 안에서 당신은 이 세계를 위해 기꺼이 싸우려는 친구들을 만날 것이오.', `MaleText_loc4`='我们是为了他们而战斗，更确切地说，说为了他们所憧憬的生活而战斗。$B$B在这城墙之外的人们已经丧失了和平生活的权利。世界就像他们知道的那样……就像我们所有人知道的那样，被凯尔萨斯、伊利丹和燃烧军团所威胁着。$B$B而在这城墙之内，你会找到一些同样希望来为此而战的朋友。', `MaleText_loc5`='我們是為了他們，或為了他們所代表的東西才奮戰。$B$B在這些牆後，這些人們的生命是被沒收的。他們所知道的世界...如我們所知道的，被凱爾薩斯，伊利丹，和燃燒軍團所威脅著。$B$B在這些牆內你會發現很少人願意為那個世界而戰。', `MaleText_loc7`='Es por ellos, o mejor dicho, por lo que representan, por lo que debemos luchar.$B$BFuera de estos muros, las vidas de esa gente no valen nada. El mundo como lo conocen... como todos lo conocemos, está amenazado por Kael''thas, Illidan y la Legión Ardiente.$B$BEn estos muros encontrarás a los únicos que quedan dispuestos a luchar por ese mundo.' WHERE `ID`=17174;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대모님, 제가 돌아왔습니다. 가로쉬는 이제 마음을 다잡고 명예로움으로 가득 찼습니다.', `MaleText_loc4`='我回来了，祖母。加尔鲁什找回了他的信心和斗志。', `MaleText_loc5`='我回來了，主母。卡爾洛斯找到了他的心和他的憤怒。', `MaleText_loc7`='He vuelto, Abuela. Garrosh ha encontrado su corazón y su furia.' WHERE `ID`=17175;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠... 냉기, 불, 비전 방어는 7번 조합보다 빠르게 반응하는 데 비해 자연 방어는 지속 효과로 남아 있다니...', `MaleText_loc4`='唔……冰霜、火焰和奥术的防御反应比第7批要快，但自然防御仍然很被动。', `MaleText_loc5`='嗯...冰霜，火焰，和秘法防禦的回應都比第7批快，但自然防禦則保持被動。', `MaleText_loc7`='Mmm... las defensas de escarcha, de fuego y Arcanas responden más rápidamente que el lote 7, pero las defensas de naturaleza permanecen pasivas.', `FemaleText_loc1`='흠... 냉기, 불, 비전 방어는 7번 조합보다 빠르게 반응하는 데 비해 자연 방어는 지속 효과로 남아 있다니...', `FemaleText_loc4`='唔……冰霜、火焰和奥术的防御反应比第7批要快，但自然防御仍然很被动。', `FemaleText_loc5`='嗯...冰霜，火焰，和秘法防禦的回應都比第7批快，但自然防禦則保持被動。', `FemaleText_loc7`='Mmm... las defensas de escarcha, de fuego y Arcanas responden más rápidamente que el lote 7, pero las defensas de naturaleza permanecen pasivas.' WHERE `ID`=17178;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 아침에 맡는 황천의 냄새가 좋군.', `MaleText_loc4`='我爱早晨虚空的味道。', `MaleText_loc5`='我愛虛空早上的氣味。', `MaleText_loc7`='Me encanta el olor de la nada por la mañana.', `FemaleText_loc1`='아, 아침에 맡는 황천의 냄새가 좋군.', `FemaleText_loc4`='我爱早晨虚空的味道。', `FemaleText_loc5`='我愛虛空早上的氣味。', `FemaleText_loc7`='Me encanta el olor del Vacío por la mañana.' WHERE `ID`=17179;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='냄새가 마치...', `MaleText_loc4`='闻上去就像……', `MaleText_loc5`='這聞起來好像...', `MaleText_loc7`='Huele a...', `FemaleText_loc1`='냄새가 마치...', `FemaleText_loc4`='闻上去就像……', `FemaleText_loc5`='這聞起來好像...', `FemaleText_loc7`='Huele a...' WHERE `ID`=17180;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='...승리의 냄새 같구나.', `MaleText_loc4`='……胜利。', `MaleText_loc5`='...勝利。', `MaleText_loc7`='...victoria.', `FemaleText_loc1`='...승리의 냄새 같구나.', `FemaleText_loc4`='……胜利。', `FemaleText_loc5`='...勝利。', `FemaleText_loc7`='...victoria.' WHERE `ID`=17181;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 종류의 물건을 보면 한때 이 휠러의 오래된 창고의 절반을 차지하던 제드 동력 장치가 생각난단 말이야.', `MaleText_loc4`='这东西让我想起Z型能量节点阀，有次我摆弄那个玩意儿的时候差点没把维勒老爹的旧车库炸掉一半。', `MaleText_loc5`='這東西有點提醒了我曾經把半個威勒老爹的舊車庫都毀掉的Z字能量核。', `MaleText_loc7`='Este tipo de cosa me recuerda a un nódulo de potencia Zed con el que una vez destruí la mitad de mi viejo garaje.' WHERE `ID`=17182;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용건이 뭔가, $r|1이여;여;?', `MaleText_loc4`='你想要点什么，$r？', `MaleText_loc5`='你想要什麼，$r?', `MaleText_loc7`='¿Qué deseas, $r?' WHERE `ID`=17183;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='인사드립니다, 게제 님! 하라사미드 구역에서 17건의 주문이 추가로 들어왔습니다. 예측하신 대로 벨다라이트 시장이 붕괴됐습니다.', `MaleText_loc4`='杰赫，您好！另外十七份定单被送到了哈拉撒米德。就像您所预见的那样，维达宝石市场崩盘了。', `MaleText_loc5`='嗨，吉札!哈拉薩米區又有十七份訂單了。重綠礦石的市場已全部崩潰了，正如你所預期。', `MaleText_loc7`='¡Saludos, Gezhe! Se han enviado diecisiete pedidos más al sector Hara''samid. Los mercados de la veladrita pesada se han venido abajo, tal y como predijiste.' WHERE `ID`=17184;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 물러가도록 하겠습니다.', `MaleText_loc4`='遵命，长官。', `MaleText_loc5`='尊命，長官。', `MaleText_loc7`='Con tu venia, señor.' WHERE `ID`=17185;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헤라지 수출이 증가 추세입니다. 이미 세관원을 매수해 놨으니 며칠 안으로 밀수품이 도착할 겁니다.', `MaleText_loc4`='长官，哈莱兹的出口前景看涨。我们已经适当贿赂了税务官员，走私品这几天就会到了。', `MaleText_loc5`='海拉茲出口物價正在上升，長官。我們已收買了適宜的課稅官員，走私品這幾天就會開始到貨了。', `MaleText_loc7`='Las exportaciones de Heraazi están subiendo. Ya hemos untado a los oficiales de aduanas que hacía falta y el contrabando empezará a llegar en cuestión de días.' WHERE `ID`=17186;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 연합왕자에게서 아무 소식이 없습니다. 황천의 폭풍에 있는 우리 고객들의 분쟁에 대한 소문이 돌고 있습니다. 우리 소다라미 후원자들이 자본 회수에 대한 얘기를 꺼내고 있습니다. 그런 일이 발생하지 않도록 설득하기 위해 최고의 협상단을 보냈습니다.', `MaleText_loc4`='目前没有从节点王子那边传来的命令。一个与我们的客户在虚空风暴发生纠纷的传言正在传播。索达亚米的支持者提出要脱离我们，我们已经派遣了最好的交涉者去劝阻他们，长官。', `MaleText_loc5`='目前沒有奈薩斯王子傳來的消息。我們和虛空風暴客戶爭執的傳言已甚囂塵上。我們的蘇達拉米贊助者說要迫使放棄。我們已派了最厲害的磋商者去勸阻他們，長官。', `MaleText_loc7`='Todavía no sabemos nada del Príncipe-nexo. Han comenzado a circular rumores sobre una disputa con nuestros clientes en la Tormenta Abisal. Nuestros benefactores Sodaraami hablan de una desinversión. Hemos enviado a nuestros mejores negociadores para disuadirlos, señor.' WHERE `ID`=17187;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자로디 구역 시장이 다시 열렸습니다. 모든 종류의 사파이어 가격이 상승했으며 은 가격은 하락했습니다. 금 가격은 상승했고 다이아몬드 가격은 그대로입니다.$B$B아, 그리고 형제 분께서 지난주에 빌려간 홀로큐브를 돌려달라고 하셨습니다.', `MaleText_loc4`='夏罗迪地区的市场已经重新开放了，长官。各种蓝宝石价格上涨，银价下跌，金价上涨，钻石走势平稳。$B$B哦，还有，您的兄弟要您归还上周借走的全息盒。', `MaleText_loc5`='薩羅帝區市場已重新開張，長官。所有的藍寶石價格上漲。銀價下跌。金價上漲。鑽石維持穩定。$B$B喔，還有你的兄弟要你帶回上禮拜借的投射機。', `MaleText_loc7`='Los mercados del sector Xarodi se han vuelto a abrir, señor. Los zafiros de todas las clases están subiendo. La plata baja. El oro sube. Los diamantes se mantienen.$B$BAh, y tu hermano dice que le devuelvas los holocubos que te llevaste la semana pasada.' WHERE `ID`=17188;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황천의 폭풍에서 온 소식입니다. 고객이 혈석 대금 지불을 거부했으니 모든 혈석 수입을 중단하라고 합니다.$B$B연합왕자가 그에 대한 보상으로 우리 물건을 최고가로 구입하겠답니다.', `MaleText_loc4`='从虚空风暴传来的命令，长官。停止进口血宝石，客户拒绝付款。$B$B节点亲王会以全额买下我们的库存作为补偿。', `MaleText_loc5`='虛空風暴來的消息，長官。停止所有的血寶石進口;顧客已棄絕付款。$B$B奈薩斯王子會用原價買下我們所有的存貨做為補償。', `MaleText_loc7`='Un mensaje de Tormenta Abisal: Detened las importaciones de gemas de sangre: el cliente ha congelado los pagos.$B$BEl Príncipe-nexo nos comprará los excedentes a su precio original como compensación.' WHERE `ID`=17189;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예상한 대로군. 아주 좋아. 이만 가 보도록.', `MaleText_loc4`='正如我预期的那样。非常好，解散。', `MaleText_loc5`='正如我所預期。非常好，退下吧。', `MaleText_loc7`='Lo que pensaba. Está bien. Puedes irte.' WHERE `ID`=17190;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놀랄 만한 내용은 하나도 없군. 제대로 된 소식을 가지고 오도록. 알겠나?', `MaleText_loc4`='没什么异常。有新消息的时候再来吧。', `MaleText_loc5`='沒什麼特別的事。帶些真正的消息回來好嗎?', `MaleText_loc7`='No me sorprende nada. Vuelve con alguna noticia de verdad, ¿de acuerdo?' WHERE `ID`=17191;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해고되고 싶지 않으면 내가 수익을 낼 수 있도록 해야 할 거야. 그러려면 이번 주에 내부 정보가 필요하니 사람을 잘 골라서 매수하도록 해. 어서 가라고!', `MaleText_loc4`='贿赂你必须贿赂的人，但是，如果我这周还想继续获得利润，你们这一大票人还想找活干的话，就给我弄点内部信息来。滚吧！', `MaleText_loc5`='收買你必須收買的人，但我本週需要一些內幕消息才能賺一大筆錢並讓你的份也有著落。下去吧!', `MaleText_loc7`='Soborna a quien tengas que sobornar, pero esta semana necesito alguna información de dentro si quiero sacar algún beneficio y manteneros contratados. ¡Y ahora largo!' WHERE `ID`=17192;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐, 그런 건 아니고요.', `MaleText_loc4`='不完全是这样。', `MaleText_loc5`='那可不一定。', `MaleText_loc7`='En realidad, no.' WHERE `ID`=17193;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저걸 시험하러 안으로 들어가는 일만 아니면 괜찮지만... 그렇다면 전 싫습니다.', `MaleText_loc4`='如果不派我去测试它的话就行……否则，不。', `MaleText_loc5`='如果我不是那個被派去測試它的人...其他人，也不會。', `MaleText_loc7`='Solo si no soy yo quien lo pruebe... Si no, no.' WHERE `ID`=17194;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그게 무슨 뜻입니까? 준비라니요? 그게 준비할 수 있는 일인가요?', `MaleText_loc4`='到底是什么意思？准备好了？还能准备好吗？', `MaleText_loc5`='那到底是什麼意思?準備好了?有可能準備好嗎?', `MaleText_loc7`='¿Qué significa esto? ¿Listo? ¿Acabará esto algún día?' WHERE `ID`=17195;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두목님, 제가 가진 전부를 그녀에게 줄 생각입니다. 그녀가 이 많은 걸 다 가져가지는 못하겠지만요!', `MaleText_loc4`='我把我手里的都给了她，队长。我觉得她拿不下了！', `MaleText_loc5`='我給了她我所有的一切，隊長。我不認為她可以拿走更多這些東西!', `MaleText_loc7`='Le estoy dando todo lo que tengo, capitán. ¡No creo que pueda aguantar mucho más!' WHERE `ID`=17196;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두목님, 이 장치를 더 빨리 두들기는 건 불가능합니다! 제 붕대가 벌써 헐거워지기 시작했어요!', `MaleText_loc4`='我不能敲得更快了，队长！我的裹布已经开始散落了！', `MaleText_loc5`='我沒辦法更快地敲擊這個儀器了，隊長!我的精神已經開始渙散!', `MaleText_loc7`='¡No puedo golpear este dispositivo más rápido, capitán! ¡Mi envoltura está comenzando a deshacerse!' WHERE `ID`=17197;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만 좀 물어보시겠습니까?', `MaleText_loc4`='你能不问那个问题了吗？', `MaleText_loc5`='你可以不要再問了嗎?', `MaleText_loc7`='¿Puedes parar de preguntar eso?' WHERE `ID`=17198;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='5분마다 우리를 들볶는 대신 망치를 들고 직접 이 구조물을 두들기는 게 어떻겠습니까?', `MaleText_loc4`='你为什么不拿起锤子去敲那些房子呢？不要每五分钟就来烦我一次！', `MaleText_loc5`='你為何不拿起錘子開始敲擊這些建築物而不是每5分鐘就問我們做完了沒?', `MaleText_loc7`='¿Por qué no coges un martillo y empiezas a golpear esas estructuras en vez de preguntarnos cada cinco minutos?' WHERE `ID`=17199;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두목님의 끝없는 불평은 이미 들을 만큼 들었습니다. 두목의 역할이 뭐라고 생각하십니까? 그러니까, 정신이 사납다고요!', `MaleText_loc4`='我受够了，不要再抱怨了，队长。你这算什么队长？你的勇气呢？', `MaleText_loc5`='我受夠了你不斷的發牢騷，隊長。你這樣還算什麼隊長?我是說，拿出一點膽量來!', `MaleText_loc7`='Ya he tenido bastante de tanto lloriqueo incesante, capitán. ¿Y de qué eres capitán tú? ¡Lo que hay que ver!' WHERE `ID`=17200;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 망할 문을 안전히 통과할 수 있게 하려면 아직 멀었나?', `MaleText_loc4`='这个该死的东西现在可以安全通过了吗？', `MaleText_loc5`='現在可以安全通過那個鬼東西了嗎?', `MaleText_loc7`='¿Ya es seguro pasar por ese maldito chisme?' WHERE `ID`=17201;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 안 끝났나? 뭐가 이렇게 오래 걸리나?', `MaleText_loc4`='完成了吗？是什么该死的东西需要这么长时间？', `MaleText_loc5`='完成了嗎?到底在幹嘛搞那麼久?', `MaleText_loc7`='¿Ya está? ¿Por qué está tardando tanto?' WHERE `ID`=17202;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 대신 고블린을 고용할 수도 있어. 그러길 바라는 거냐?', `MaleText_loc4`='你知道，我们随时可以用地精替换你。你难道希望这样？', `MaleText_loc5`='你知道，我們可以輕易地用哥布林來取代你。這是你想要的嗎???', `MaleText_loc7`='¿Sabes una cosa? ¡Podríamos sustituirte por goblins! ¡¿Es eso lo que quieres?!' WHERE `ID`=17203;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 멍청이들은 학교에서 대체 뭘 배웠는지 정말 형편없군! 저놈들이 뭘 하고 있는지 누구 아는 사람 있나?', `MaleText_loc4`='我不敢相信你这个蠢货竟然为了这个去学校！谁知道他们在干什么吗？', `MaleText_loc5`='我不敢相信你們這些蠢貨為了這個去學校!這裡有人知道他們在幹嘛嗎?', `MaleText_loc7`='¡Imbéciles! No me puedo creer que hayáis estudiado para esto. ¿Alguien de aquí sabe lo que está haciendo?' WHERE `ID`=17204;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 바보 같은 일에 대한 보수치고는 너무 짜단 말이야.', `MaleText_loc4`='给我的报酬太少了。', `MaleText_loc5`='我沒有因為這樣的胡鬧得到足夠的報酬。', `MaleText_loc7`='No me pagan lo suficiente para esta tontería.' WHERE `ID`=17205;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='까짓것 한번 해보죠!', `MaleText_loc4`='什么都没有！', `MaleText_loc5`='什麼都沒發生!', `MaleText_loc7`='¡A ver qué pasa!' WHERE `ID`=17206;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최소한 이력서에 쓸 건 하나 더 늘겠군.', `MaleText_loc4`='这会留下个记号……', `MaleText_loc5`='這會名留青史...', `MaleText_loc7`='Esto dejará marca...' WHERE `ID`=17207;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성공한다면 보수가 오르겠지.', `MaleText_loc4`='如果我成功了，我希望能提薪。', `MaleText_loc5`='如果我能順利通過，我希望可以加個薪。', `MaleText_loc7`='Si lo consigo, espero que me den un aumento.' WHERE `ID`=17208;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해냈어! 내가 해냈어!', `MaleText_loc4`='我成功了！我成功了！', `MaleText_loc5`='我成功了!我成功了!', `MaleText_loc7`='¡Lo conseguí! ¡Lo conseguí!' WHERE `ID`=17209;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 안전해 보이는군. 안으로 들어가라, 기술자!', `MaleText_loc4`='好吧，看上去安全了。进去吧，工程师！', `MaleText_loc5`='好吧，看起來安全了。進去吧，工程師!', `MaleText_loc7`='Está bien, parece seguro. ¡Entra ahí, ingeniero!' WHERE `ID`=17210;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 몸을 더듬으며 어디 잘못된 곳은 없는지 확인합니다.', `MaleText_loc4`='%s用手上下摸索着，确保东西都带齐了。', `MaleText_loc5`='%s用手摸摸他的身體確認一切都完好無缺。', `MaleText_loc7`='%s se toca con sus manos para comprobar que todo está en su sitio.' WHERE `ID`=17211;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 어깨를 으쓱합니다.', `MaleText_loc4`='%s耸了耸肩。', `MaleText_loc5`='%s聳了聳肩。', `MaleText_loc7`='%s se encoge de hombros.' WHERE `ID`=17212;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 불만스럽다는 듯 고개를 젓습니다.', `MaleText_loc4`='%s不以为然地摇了摇头。', `MaleText_loc5`='%s不贊同地搖搖他的頭。', `MaleText_loc7`='%s desaprueba con la cabeza.' WHERE `ID`=17213;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음, 처음부터 다시 해봐야겠어.', `MaleText_loc4`='好吧，重新制定计划吧。', `MaleText_loc5`='喔好吧，回到計畫階段。', `MaleText_loc7`='Vaya. Otra vez a revisar el diseño.' WHERE `ID`=17214;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어쨌든 별로 마음에 안 드는 놈이었다. 말만 많고 ''하는 일''은 별로 없었지.', `MaleText_loc4`='无论如何，我不太喜欢他。他总是说得多，做得太少。', `MaleText_loc5`='反正我也不喜歡他 。說的很多，「做」的卻不夠。', `MaleText_loc7`='No me gustaba mucho, de todas formas. Hablaba mucho y hacía poco.' WHERE `ID`=17215;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='젠장, 놈들의 보안 장치를 어떻게 뚫지?', `MaleText_loc4`='该死，我们应该怎样穿过他们的安全措施？', `MaleText_loc5`='可惡。我們要怎樣才能破解他們的安全措施?', `MaleText_loc7`='Maldición. ¿Cómo vamos a conseguir pasar sus medidas de seguridad?' WHERE `ID`=17216;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘하는 짓들이다, 이 무능한 놈들아! 기술자 한 명이 또 증발했잖아!', `MaleText_loc4`='干得好，你这个蠢货！我们的又一个工程师被蒸发了！', `MaleText_loc5`='幹得好你這無能的智障!我們又一個工程師被蒸發了!', `MaleText_loc7`='¡Que os vaya bien, estúpidos incompetentes! ¡Otro ingeniero vaporizado!' WHERE `ID`=17217;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙게도 이 안에 들어가려고 안달 난 멍청이들이 줄을 섰단 말이야.', `MaleText_loc4`='好在总有一帮愚蠢的家伙挤破头似的往这里涌。', `MaleText_loc5`='感謝，還有許多想來這裡的笨蛋。', `MaleText_loc7`='Afortunadamente, hay un buen caudal de idiotas que han picado para venir aquí.' WHERE `ID`=17218;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='''전문가''란 무엇일까요? 비전문가가 뭐냐고 묻는 게 더 좋겠군요. 그러니까 저는 안 배운 게 없습니다! 사실 당신이 만난 누구보다도 모든 분야에 능통한 이 세상에서 가장 똑똑한 에테리얼입니다. 제 말이 거짓이라면 돈을 돌려드리죠.$B$B죄송합니다. 장사꾼처럼 말했군요...', `MaleText_loc4`='“杂学家”是什么？你应该问“杂学家”不是什么。这意味着是我研究世间万物！事实上我精通任何东西，我保证我是你所遇到过的最聪明的虚灵——否则我就把你的钱还你。$B$B对不起。那是我心灵中的商人本质在说话……', `MaleText_loc5`='什麼是『學家』?正確一點的問題應該是什麼不是『學家』。意思是我研究所有的事物!事實上，我精通『所有事物』，我保證是你們見過最有智慧的以太人 - 也是你們用錢聘請到最有智慧的以太族。$B$B抱歉。那是我身體裡的商人在說話...', `MaleText_loc7`='¿Qué es un "todólogo?" Mejor sería preguntar qué no es un "todólogo." ¡Significa que lo estudio todo! De hecho, soy tan experto en "todo" que te aseguro que soy el etéreo más inteligente que jamás hayas visto, ¡te apuesto lo que quieras!$B$BPerdona. Está hablando el comerciante en mí...' WHERE `ID`=17219;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 교활하지도 음흉하지도 않습니다. 그런 발언은 상당히 불쾌합니다.$B$B등에 막대기를 꽂아 버리기 전에 제 앞에서 사라지십시오.', `MaleText_loc4`='我既不瘦也不黑。实话实说，这两个词都是对我的侮辱。$B$B现在，在我把法杖插到你后背上之前赶紧给我消失。', `MaleText_loc5`='我既不狡猾也不可疑。事實上，我覺得這兩個形容詞都很汙辱我。$B$B現在，在我對你抄傢伙前離開我的視線。', `MaleText_loc7`='No soy flaco ni oscuro. De hecho, ambas referencias me parecen insultantes.$B$BY ahora, sal de mi vista antes de que te clave el bastón en el culo.' WHERE `ID`=17220;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 당신은 무역연합의 동료로군요. 물건을 좀 보시겠습니까?', `MaleText_loc4`='啊，我注意到你是星界财团的朋友。也许你有兴趣买点东西？', `MaleText_loc5`='啊，我看出你是聯合團的朋友。或許你會有興趣買點東西?', `MaleText_loc7`='Ah. Veo que eres amigo del Consorcio. ¿Te interesaría hacer una compra?' WHERE `ID`=17221;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물건을 보여주십시오, 말라깽이!', `MaleText_loc4`='让我看看你都卖什么东西，“瘦子”。', `MaleText_loc5`='給我看看你賣的商品，『瘦子』。', `MaleText_loc7`='Enséñame lo que tienes a la venta, "Flaco."', `FemaleText_loc1`='물건을 보여주세요, 말라깽이!', `FemaleText_loc4`='让我看看你都卖什么东西，“瘦子”。', `FemaleText_loc5`='給我看看你賣的商品，『瘦子』。', `FemaleText_loc7`='Enséñame lo que tienes a la venta, "Flaco."' WHERE `ID`=17222;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샤파르는 영리한 놈일세. 놈은 다른 에테리얼 무리가 들어오지 못하게 일종의 수호물을 사용해서 입구를 만들었지. 우리는 놈의 방어선을 뚫고 안으로 들어가서 우리 물건을 찾아오려고 노력 중일세. 최고의 에테리얼들이 쉬지 않고 작업 중이니 이제 금방 열릴 거야. 분명 그런 예감이 들어...', `MaleText_loc4`='沙法尔真是个聪明的混蛋。他在入口装上了一些防护装置来阻止其他虚灵进入。我们正在想办法击溃他的防线，以便进去拿回属于我们的东西。我已经让最好的虚灵们在这里日以继夜地工作了。很快就可以打开它了。我的预感越来越强烈了……', `MaleText_loc5`='薩法爾很聰明，他用某種結界壟斷了入口防止其他以太族團隊進入。我們正設法突破他的防禦，這樣我們就能進入那裡奪回我們的東西。我找了以太族精英日以繼夜地努力著。我們現在隨時都可能將它打開。我可以感覺得到...', `MaleText_loc7`='Ese Shaffar es un tipo muy listo. Ha colocado en la entrada algún tipo de protección para evitar que entren otros etéreos. Estamos trabajando para romper sus defensas y poder entrar ahí para coger lo que es nuestro. Tengo a los mejores etéreos trabajando en esto día y noche. Lo conseguiremos en cualquier momento. Lo noto...' WHERE `ID`=17223;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샤파르의 에테리얼이 마나 무덤으로 들어가는 입구에 무슨 짓을 해놨든 별로 중요하지 않다. 무역연합이 안전히 들어가 우리 물건을 가져올 수 있도록 수호물을 제거할 때까지 너는 작업을 계속해야 해!', `MaleText_loc4`='我不管沙法尔的虚灵在法力陵墓的入口放了什么东西。你要一直工作，直到那些防护被除掉，那样星界财团就能安全地拿回属于自己的东西！', `MaleText_loc5`='我才不管薩法爾的以太族在法力墓地入口放置了什麼。在那些結界被移除，聯合團可以安全地搬進來並拿走屬於我們的東西前，你都要持續工作。', `MaleText_loc7`='No me importa en absoluto lo que los etéreos de Zafra hayan colocado en la entrada de las Tumbas de Maná. Trabajaréis hasta que la protección ya no esté y el Consorcio pueda entrar sin peligro para coger lo que nos pertenece.' WHERE `ID`=17224;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"안 돼요." 혹은 "못 합니다." 따위의 말이나 듣자고 너희 같은 기술자에게 엄청난 보수를 주는 줄 아나? 방어벽을 제거하라. 아니면 X-17에 연료 넣는 일이나 시키겠다.', `MaleText_loc4`='我给你们这些工程师付了这么高的工资可不是为了听到你说“不”或者“不能”。把那个屏障弄倒，否则我就把你丢去X-17的能量改造线工作。', `MaleText_loc5`='我不是付你們倆高額的金錢來聽「不」或「無法」這些字眼的。趕快想辦法把那個屏障解除，否則你們就會被貶去X-17上處理能量矯正線。', `MaleText_loc7`='No os estoy pagando cantidades desorbitadas de oro para oíros decir "no" o "imposible". Derribad esa barrera si no queréis que os mande a la línea energética de X-17.' WHERE `ID`=17225;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='참을 만큼 참았다, 몰팔리우스. 한 번만 더 일을 망치면 저 차원문으로 들어가서 카프티즈의 실험 재료가 될 줄로 알아라.', `MaleText_loc4`='我靠近边缘了，莫法鲁斯。接下来就该你跑过传送门了，为卡弗提兹的测试作实验吧。', `MaleText_loc5`='我正在失敗的邊緣，莫法利厄司。再搞砸一次，你就會是那個為了卡夫提茲的測試而通過傳送門的人。', `MaleText_loc7`='Ya no puedo más, Morphalius. Otra metedura de pata y serás tú quien corra al portal para las pruebas de Kaftiz.' WHERE `ID`=17226;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정해라, 제군들!', `MaleText_loc4`='放松点。', `MaleText_loc5`='放鬆，兄弟。', `MaleText_loc7`='Tranquilos, muchachos.' WHERE `ID`=17227;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 우선 자신의 몸이 무사한지부터 확인합니다.', `MaleText_loc4`='%s检查了一下，确保他的身体是完整的。', `MaleText_loc5`='%s仔細檢查以確定他的屍體完整無缺。', `MaleText_loc7`='%s comprueba que su cuerpo está intacto.' WHERE `ID`=17228;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 해내셨군요! 잘하셨습니다. 잠시 실례하죠. 남아 있는 우리 기술자들을 안으로 데려와야겠습니다.', `MaleText_loc4`='你成功了！干得好，$R。失陪一下，我得进去瞧瞧别的伙计们。', `MaleText_loc5`='你辦到了!幹得好，$r。不好意思，我現在要去接應裡面剩下的人手。', `MaleText_loc7`='¡Lo has conseguido! Bien hecho, $r. Ahora, si me perdonas, tengo que meter dentro al resto de nuestro equipo.' WHERE `ID`=17229;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 제어장치를 능숙하게 조작합니다.', `MaleText_loc4`='%s熟练地操作着控制面板。', `MaleText_loc5`='%s熟練地操作著控制面板。', `MaleText_loc7`='%s manipula expertamente el panel de control.' WHERE `ID`=17230;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간이 얼마 없다! 운반할 수 있는 건 아무거나 챙겨서 곧장 폭풍 첨탑으로 순간이동하도록! 서둘러!', `MaleText_loc4`='不要浪费时间！能拿的就都给我拿上，然后直接传送到风暴尖塔！冲啊！', `MaleText_loc5`='不要浪費任何時間!把所有沒固定的東西都拿到地上並直接傳送至風暴之尖!快快快!', `MaleText_loc7`='¡No hay tiempo que perder! ¡Agarra todo lo que puedas y teletranspórtate a la Flecha de la Tormenta! ¡Vamos, vamos!' WHERE `ID`=17231;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제어장치가 이동하더니 축을 중심으로 회전합니다.', `MaleText_loc4`='控制面板在轴承上转动着。', `MaleText_loc5`='控制面板的軸線移動旋轉。', `MaleText_loc7`='El panel de control cambia y gira sobre sí mismo.' WHERE `ID`=17232;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<아무 단추나 하나 누릅니다.>', `MaleText_loc4`='<随便按下某个按钮。>', `MaleText_loc5`='<按了一個隨機鈕。>', `MaleText_loc7`='<Pulsa un botón cualquiera.>', `FemaleText_loc1`='<아무 단추나 하나 누릅니다.>', `FemaleText_loc4`='<随便按下某个按钮。>', `FemaleText_loc5`='<按了一個隨機鈕。>', `FemaleText_loc7`='<Pulsa cualquier botón.>' WHERE `ID`=17233;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='', `MaleText_loc4`='', `MaleText_loc5`='', `MaleText_loc7`='' WHERE `ID`=17234;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘은 시장이 참 분주한 것 같습니다.', `MaleText_loc4`='今天的市场看上去的确很忙碌。', `MaleText_loc5`='市場今天看起來真的很忙碌。', `MaleText_loc7`='El mercado parece muy ajetreado hoy.' WHERE `ID`=17235;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주변을 뛰어다니는 정신 나간 꼬마들 좀 보십시오. 세상일에는 조금도 신경을 쓰지 않나 봐요.', `MaleText_loc4`='看那些四处奔跑的孩子们，他们是多么天真烂漫。', `MaleText_loc5`='看那些瘋狂的孩子跑來跑去。完全不擔心世上的任何事。', `MaleText_loc7`='Mira a esos niños traviesos corriendo por todas partes. Nada en este mundo les preocupa.' WHERE `ID`=17236;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저건 대체 어떤 생물이랍니까? 보라색 고블린처럼 보이는데...', `MaleText_loc4`='这家伙是什么？看上去像个紫色的地精。', `MaleText_loc5`='那是什麼生物?看起來像是紫色的哥布林。', `MaleText_loc7`='¿Qué suerte de criatura es esa? Parece un goblin morado.' WHERE `ID`=17237;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아달을 사사로운 속세의 문제로 괴롭히지 마시오. 이 존재의 의지 덕분에 적들이 우리 도시로 쳐들어오지 못하는 것이오.', `MaleText_loc4`='不要用太多问题来麻烦阿达尔，$r。这个生物的意志是让我们的城市远离伤害的关键。', `MaleText_loc5`='別用世俗的問題來煩擾阿達歐，$r。這個生命的意志是所有不讓我們敵人摧毀這城市的力量。', `MaleText_loc7`='No molestes a A''dal con preguntas triviales, $r. La voluntad de este ser es lo único que evita que nuestros enemigos aplasten la ciudad.' WHERE `ID`=17238;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이방인이여, 저를 따라오십시오. 오래 걸리지는 않을 겁니다.', `MaleText_loc4`='跟我来，陌生人。这不会耽误你太长时间的。', `MaleText_loc5`='跟我來，陌生人。這不會花太久的時間。', `MaleText_loc7`='Sígueme, extranjer$go:a;. No tardaremos mucho.' WHERE `ID`=17239;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샤트라스는 한때 이 세계에 살던 드레나이의 수도였습니다. 샤트라스는 ''빛이 거하는 곳''이라는 뜻이죠.', `MaleText_loc4`='沙塔斯城曾经是德莱尼人在这个世界的首都。它的意思是“圣光的居所”。', `MaleText_loc5`='撒塔斯曾是這世界的德萊尼首都。它的名字的意思是「聖光住所」。', `MaleText_loc7`='Shattrath fue antiguamente la capital draenei de este mundo. Su nombre significa "morada de la Luz."' WHERE `ID`=17240;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아! 훌륭해! 멋진 광경이였다... 날 위해 일하라고 했다면 거절했겠지. 그렇지 않는가? 아니야, 쓸데없이 내 일꾼들을 학살하는 행위는 네 이력에 부정적인 영향을 미칠지도 모른다.', `MaleText_loc4`='好啊！好啊！表现得真好……我不能劝你为我工作，我能吗？不，我想我手下的那些屠夫会影响到你的签约。', `MaleText_loc5`='太棒了!太棒了!精采的演出...我不能說服你替我工作，對吧?不，我想我不必要的屠夫員工會對你的工作申請有負面的影響。', `MaleText_loc7`='¡Bravo! ¡Bravo! Un gran espectáculo. No podría convencerte de que trabajaras para mí, ¿verdad? Ya. Supongo que mis matanzas indiscriminadas de empleados han favorecido la caída de mi reputación como empresario.' WHERE `ID`=17241;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='''빛에서 태어난 자''라고도 불리는 샤타르는 불타는 군단의 악마들과 싸우기 위해 아웃랜드로 온 나루입니다.', `MaleText_loc4`='沙塔尔，或者说“生于圣光”，这个词是指来到外域和燃烧军团的恶魔们作战的纳鲁。', `MaleText_loc5`='薩塔，或「聖光之子」是來到外域與燃燒軍團惡魔對抗的那魯。', `MaleText_loc7`='"Los Sha''tar, o los "nacidos de la Luz" son los naaru que vinieron a Terrallende para luchar contra los demonios de la Legión Ardiente.' WHERE `ID`=17242;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샤힌, 좋은 계획이었다. 이 한 가지 사실만 아니었다면 그걸 갖고 도망칠 수도 있었겠지...', `MaleText_loc4`='沙赫恩，你的计划是不错。要不是出了点差池，你应该能侥幸成功的……', `MaleText_loc5`='你的計畫很完美，薩希恩。要不是因為這一個問題你早已逃脫了...', `MaleText_loc7`='Tu plan era bueno, Sha''heen, y te habría salido bien si no hubiera sido por una cosa...' WHERE `ID`=17243;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 에테리얼의 욕망을 과소평가하지 마라!', `MaleText_loc4`='永远不要低估其他虚灵的贪婪！', `MaleText_loc5`='永遠不要低估其他以太族的貪婪!', `MaleText_loc7`='¡Nunca subestimes la avaricia de otro etéreo!' WHERE `ID`=17244;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 얼마 후 샤트라스는 또다시 공격을 받았습니다. 이번에는 일리단의 군대였지요. 일리단의 동맹인 캘타스 선스트라이더가 수많은 블러드 엘프들을 보내 샤트라스를 파괴했습니다.', `MaleText_loc4`='然而好景不长，这座城市再次遭受了攻击。这次，发动进攻的是伊利丹的军队。伊利丹的同盟凯尔萨斯·逐日者派出了一大群血精灵来毁灭这座城市。', `MaleText_loc5`='不過，在城市再次遭受攻擊前沒有太多時間了。這一次，是伊利丹軍隊的攻擊。伊利丹的盟友，凱爾薩斯·逐日者派出一大批血精靈來損毀城市。', `MaleText_loc7`='Sin embargo, no pasó mucho tiempo hasta que volvieron a atacar la ciudad. Esta vez, el ataque era de los ejércitos de Illidan. El aliado de Illidan, Kael''thas Caminante del Sol, había enviado a un gran número de elfos de sangre para destruir la ciudad.' WHERE `ID`=17245;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리 오래 걸리지는 않을 겁니다. 제가 이 황천 수집 장치를 털 동안 뒤를 지켜주십시오.', `MaleText_loc4`='这不会花太长时间的。在我清空这些虚空收集器的时候保护我。', `MaleText_loc5`='這不會花太久的時間。在我清空這些虛空收集者的時候幫我把風就好了。', `MaleText_loc7`='No debería tardar demasiado. Cúbreme la espalda mientras descargo estos recolectores de vacío.' WHERE `ID`=17246;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갑자기 블러드 엘프들이 도시의 수호자들 앞에 무기를 내려놓은 겁니다. 그리고 그들의 지도자인 블러드 엘프 장로 보렌살이 빛의 정원에 뛰어들어 아달과 대화를 요구했습니다.', `MaleText_loc4`='血精灵们在城市守卫面前放下了武器。他们的首领，一个被称为沃雷塔尔的血精灵长者，冲进了圣光广场，要求和阿达尔对话。', `MaleText_loc5`='血精靈將他們的武器放在城市防衛者面前;他們的領導者，一個叫沃藍索的血精靈長者衝進聖光露臺並要求與阿達歐對談。', `MaleText_loc7`='Los elfos de sangre tiraron sus armas delante de los defensores de la ciudad; su líder, un elfo de sangre llamado Voren''thal, irrumpió en el Bancal de la Luz y exigió hablar con A''dal.' WHERE `ID`=17247;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋습니다! 그럼 움직여 볼까요?', `MaleText_loc4`='太棒了！我们继续吧？', `MaleText_loc5`='太棒了!讓我們繼續前進，好嗎?', `MaleText_loc7`='¡Estupendo! Sigamos, ¿de acuerdo?' WHERE `ID`=17248;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에너지 수위가 이 정도인 것을 보면 분명히 샤파르는 떼돈을 벌어들이겠군요!', `MaleText_loc4`='啧啧，看这能量等级，沙法尔准备大开杀戒了！', `MaleText_loc5`='看著這些能量水平，薩法爾開始大開殺戒!', `MaleText_loc7`='¡Teniendo en cuenta estos niveles de energía, Shaffar estaba preparado para provocar una matanza!' WHERE `ID`=17249;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보렌살과 그 부하들의 변절은 그때까지 캘타스의 군대가 입었던 어떤 피해보다도 큰 손실이었습니다. 더구나 이들은 평범한 블러드 엘프들이 아니었죠. 캘타스를 따르던 최고의 학자들과 마법학자들 중 상당수가 보렌살의 영향을 받아 마음이 흔들렸습니다.', `MaleText_loc4`='沃雷塔尔和他的追随者们的变节是凯尔萨斯有史以来所遭受到的最严重的损失。他们不是一群普通的血精灵，凯尔萨斯手下很多最睿智、最强大的学者和魔导师也被沃雷塔尔的影响力动摇了。', `MaleText_loc5`='沃藍索和他的追隨者的背叛是凱爾薩斯軍隊遭受的最大損失。他們不是普通的血精靈。許多凱爾最優秀和聰明的學者及博學者都被沃藍索的影響給動搖。', `MaleText_loc7`='La deserción de Voren''thal y sus seguidores resultó ser una gran pérdida para las tropas de Kael. Y no se trataba de elfos de sangre cualquiera. Muchos de los más brillantes escolares y magistri de Kael, habían caído bajo la influencia de Voren''thal.' WHERE `ID`=17250;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러고도 남을 겁니다...', `MaleText_loc4`='这就应该能行了……', `MaleText_loc5`='那應該可以...', `MaleText_loc7`='Esto debería bastar...' WHERE `ID`=17251;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠, 다음 황천 수집 장치는 어디에 있을까요?', `MaleText_loc4`='唔，下一个收集器在哪里？', `MaleText_loc5`='嗯，下一個收集器在哪?', `MaleText_loc7`='Mmm. ¿Dónde está el siguiente contenedor?' WHERE `ID`=17252;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알도르 사제회는 성스러운 빛을 섬기며 용서와 구원의 가치를 소중하게 생각하지요. 하지만, 아무리 그들이라도 블러드 엘프들이 캘타스의 명령을 받던 시절에 저질렀던 잘못을 쉽게 잊을 수 없었습니다.', `MaleText_loc4`='奥尔多是圣光的追随者，宽恕和救赎是他们的信条。然而，他们却很难忘记血精灵在凯尔萨斯命令之下的所作所为。', `MaleText_loc5`='奧多爾是聖光的追隨者，原諒和救贖是他們所了解的價值。但是，他們卻很難忘記血精靈在凱爾的指揮下所做的一切。', `MaleText_loc7`='Los Aldor son seguidores de la Luz; comprenden el perdón y la redención. Sin embargo, les costó olvidar los actos de los elfos de sangre bajo el mando de Kael.' WHERE `ID`=17253;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 저기 있군. 따라오십시오.', `MaleText_loc4`='啊，就是那里。跟我来，肉人。', `MaleText_loc5`='啊，在那裡。跟我來，寄生蟲。', `MaleText_loc7`='Ah, ahí está. Sígueme, ser de carne.' WHERE `ID`=17254;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황천 수집 장치들이 이렇게나 많이 있다니... 제가 일을 하는 동안 안전하게 지켜주십시오.', `MaleText_loc4`='再有几个收集器就完工了，请在我工作的时候保护我。', `MaleText_loc5`='不可能有太多的收集者。在我工作時確保我的安全就對了。', `MaleText_loc7`='No pueden quedar muchos contenedores. Tú protégeme mientras yo trabajo.' WHERE `ID`=17255;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니 이건 또 뭡니까? 이 지역은 이제 안전하다고 말하지 않았었나요? 이번이 벌써 세 번째 공격이던가요? 여기서 빠져나가면 그만큼 당신 보상에서 공제하겠습니다. 자, 거기 그냥 그렇게 서 있지 말고 저 황천 수집 장치에 접근할 수 있도록 길을 터주십시오.', `MaleText_loc4`='你是吃干饭的吗？你刚才还说这个地方是安全的，结果现在这已经是第三次攻击了。如果我们能活着离开这里，我肯定要扣除你的奖励。不要傻站在那里，把他们都消灭掉，让我有机会接近那个收集器！', `MaleText_loc5`='現在是什麼情形?你不是說這裡已經安全了嗎?現在這是第三次的攻擊?如果我們能安全離開這裡，我絕對會扣除你的獎勵。不要只會站在那裡，摧毀他們我才能接近那個收集者。', `MaleText_loc7`='¿Qué tenemos aquí? ¿Creí que habías dicho que esta zona era segura? ¿Es el tercer ataque? Si pudiéramos salir de aquí, te aseguro que restaría esto de la recompensa. Y no te quedes ahí, acaba con ellos para que pueda llegar hasta el colector.' WHERE `ID`=17256;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샤트라스를 향한 공격이 계속되었지만 보시다시피 도시는 함락되지 않았습니다. 한편, ''지리''라는 나루가 일리단의 본거지 바로 앞에 있는 어둠달 골짜기를 성공리에 습격했습니다.', `MaleText_loc4`='对沙塔斯城的进攻持续着，但是城市并没有沦陷，就像你看到的那样。相反，那个名叫克希利的纳鲁领导了一次成功的反击，一直打到了伊利丹的家门口——影月谷。', `MaleText_loc5`='對撒塔斯的攻擊持續進行，但城市並未崩塌，如你所見。相反的，稱為希瑞的那魯領導了一次對影月谷成功的入侵 - 那是伊利丹的大門。', `MaleText_loc7`='Los ataques contra Shattrath continuaron, pero, como puedes ver, la ciudad no cayó. Al contrario. El naaru llamado Xi''ri dirigió con éxito una incursión en el Valle Sombraluna; muy cerca de la guarida de Illidan.' WHERE `ID`=17257;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='출구에 거의 도착했군요. 30초 정도 쉬었다가 여기서 빠져나갑시다.', `MaleText_loc4`='我们离出口很近了。我会让你休息三十秒，然后我们离开这里。', `MaleText_loc5`='我們離出口很近。我讓你們休息大約三十秒，然後我們就要離開這裡。', `MaleText_loc7`='Estamos cerca de la salida. Te dejaré descansar unos treinta segundos, pero después nos vamos.' WHERE `ID`=17258;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비됐습니까?', `MaleText_loc4`='你准备好了吗？', `MaleText_loc5`='你準備好起身了嗎?', `MaleText_loc7`='¿Estás $glisto:lista; para salir?' WHERE `ID`=17260;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='휴식은 여기까지... 갑시다!', `MaleText_loc4`='好吧，休息结束。出发！', `MaleText_loc5`='好了休息時間已結束。我們走!', `MaleText_loc7`='Bien. Se acabó la pausa. ¡Vamos!' WHERE `ID`=17261;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카드가 님을 다시 찾아가십시오. 샤타르를 섬기려면 알도르 사제회 또는 점술가 길드 중 한 편과 동맹을 맺어야 한다는 사실을 기억하십시오. 참고로, 둘 중 한 편과 뜻을 함께하기로 결정하면 다른 편은 적이 될 겁니다.', `MaleText_loc4`='卡德加应该准备好再次见你了。记住，如果你准备为沙塔尔效力，你很可能不得不与奥尔多或是占星者结盟。同样，对任何一方示好都会引起另外一方的敌意。', `MaleText_loc5`='卡德加應該已準備好再見你一次了。只是要記得效忠於薩塔你就差不多是和奧多爾或占卜者結盟了。想獲得一個陣營的好感就會造成另一方的仇恨。', `MaleText_loc7`='Khadgar debería estar listo para volver a verte. Pero recuerda que, para servir a los Sha''tar, tendrás que aliarte con los Aldor o los Arúspices. Y conseguir el favor de un grupo hará que disminuya tu nivel de reputación con los otros.' WHERE `ID`=17262;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 그래요? 대체 그게 뭔데요?', `MaleText_loc4`='真的吗？那会是什么？', `MaleText_loc5`='喔真的嗎?那會是什麼呢?', `MaleText_loc7`='¿Ah, sí? ¿Y qué puede ser?' WHERE `ID`=17263;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그의 말이 옳습니다. 그런데 그 멋진 문구는 앞으로 제가 써야겠군요... 이제 그는 쓰지 못하게 됐으니까요!', `MaleText_loc4`='他是对的，你知道。我不得不亲自拿起那把标记射线枪……看上去他不会再使用它了！', `MaleText_loc5`='他是對的，你知道。我必須把那當做我自己的口頭禪...反正他也不會再用它了!', `MaleText_loc7`='Tenía razón, ¿sabes? Tendré que quedarme yo con ese título... ¡De todas formas, ya no sirve para nada!' WHERE `ID`=17264;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다. 그리고 행운을 빕니다!', `MaleText_loc4`='谢谢，祝你好运！', `MaleText_loc5`='感謝並祝你好運!', `MaleText_loc7`='¡Gracias y buena suerte!' WHERE `ID`=17265;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 손님께 샤트라스를 구경시켜 드려라. 고난의 거리에 가면 소매치기를 조심하고.', `MaleText_loc4`='带我们的客人去沙塔斯城里走走吧？路过贫民窟的时候小心你的钱包。', `MaleText_loc5`='帶我們的客人去參觀一下撒塔斯，好嗎?小心陰鬱城裡的扒手。', `MaleText_loc7`='Enséñale a nuestr$go:a; invitad$go:a; la Ciudad de Shattrath, ¿de acuerdo? Ten cuidado con los ladrones del Bajo Arrabal.' WHERE `ID`=17266;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불타는 군단 때문에 오크들이 드레나이에게 등을 돌렸을 때 이곳에서 가장 격렬한 전투가 벌어졌습니다. 드레나이는 끝까지 싸웠지만 결국 도시는 함락되었죠.', `MaleText_loc4`='当燃烧军团诱使兽人和德莱尼人反目成仇时，激烈的战斗就在这里爆发了。尽管德莱尼人浴血奋战，但最后，城市还是沦陷了。', `MaleText_loc5`='當燃燒軍團讓獸人和德萊尼反目成仇，最慘烈的戰役就在這裡發生了。德萊尼拼命地作戰，但最後城市還是瓦解了。', `MaleText_loc7`='Cuando la Legión Ardiente puso a los orcos contra los draenei, la batalla más fiera tuvo lugar aquí. Los draenei lucharon con todas sus fuerzas pero, al final, la ciudad cayó.' WHERE `ID`=17268;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폐허가 된 도시에는 어둠만이 남아 있었습니다... 하지만, 샤타르가 도착하자 얘기가 달라졌죠.', `MaleText_loc4`='整座城市只剩下废墟和黑暗……直到沙塔尔来临。', `MaleText_loc5`='這城市只剩下廢墟和黑暗...直到薩塔到來。', `MaleText_loc7`='La ciudad quedó derruida y en la oscuridad... hasta que llegaron los Sha''tar.' WHERE `ID`=17269;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고난의 거리로 갑시다. 한 가지 미리 알려드리자면 샤트라스는 아웃랜드에 남아 있는 몇 안 되는 안전한 피난처이기 때문에 과거에 벌어진 전쟁이나 현재 진행 중인 전쟁을 피해 많은 난민이 몰려들고 있습니다.', `MaleText_loc4`='我们去贫民窟走走吧。我要提醒你，作为外域唯一的避风港，沙塔斯城吸引了成群的难民，无论是现在的战争所致，还是以往的战争所致。', `MaleText_loc5`='讓我們進入陰鬱城。我會警告你撒塔斯是外域唯一安全的避難所之一，它吸引了所有戰爭中的難民，現在的和以前的。', `MaleText_loc7`='Adentrémonos en el Bajo Arrabal. Te advierto de que, al ser uno de los pocos lugares seguros de Terrallende, Shattrath ha atraído cientos de refugiados de muchas guerras, presentes y pasadas.' WHERE `ID`=17270;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들이 폐허의 도시 샤트라스로 이끌려 왔을 때 살아남은 소수의 드레나이 사제들은 바로 이곳의 부서진 신전에서 의식을 거행하고 있었습니다.', `MaleText_loc4`='他们慕名来到沙塔斯城的废墟，一小群德莱尼传教士利用那里的一座废弃神庙传授着他们的教义。', `MaleText_loc5`='他們被吸引到撒塔斯城，一小群遺留下來的德萊尼教士在這個地方的一座廢棄神廟裡進行它的祭儀。', `MaleText_loc7`='Fueron atraídos hasta las Ruinas de la Ciudad de Shattrath, donde un pequeño grupo de sacerdotes draenei llevaba a cabo sus ritos dentro de uno de los templos en ruinas, justo aquí.' WHERE `ID`=17271;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알도르라는 이름의 그 사제들은 나루가 돌아왔으며 재건 사업이 곧 시작된다는 소식을 듣고 금세 기운을 회복했습니다. 부서진 사원은 현재 부상당한 난민들을 위한 진료소로 사용되고 있습니다.', `MaleText_loc4`='被称为奥尔多的那些传教士们，因为纳鲁回归和重建即将开始的传言而迅速恢复了生命力。废弃的神庙如今变成了治疗伤者的医务室。', `MaleText_loc5`='當傳言聲稱那魯已回來而重建很快就會開始時，奧多爾的教士們快速地重拾了它的力量。被毀的神廟現在是受傷難民的醫務室。', `MaleText_loc7`='Los sacerdotes, conocidos como los Aldor, rápidamente recuperaron su fuerza según se fueron enterando de que los naaru habían regresado. Y la reconstrucción comenzó pronto. El templo en ruinas ahora se utiliza como enfermería para los refugiados heridos.' WHERE `ID`=17272;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='블러드 엘프 군대가 바로 이 다리를 건널 때 알도르 사제회의 총독과 구원자들이 빛의 정원을 방어하고자 진을 쳤습니다. 그런데 그때 전혀 예상치 못한 일이 벌어졌습니다.', `MaleText_loc4`='当时一大群血精灵跨过了这座桥，奥尔多的主教和守备官们筑起了人墙，保卫圣光广场。就在这时，意想不到的事情发生了。', `MaleText_loc5`='當血精靈軍團越過這座橋時，奧多爾的主教和復仇者排列成隊防衛聖光露臺。但卻發生了始料未及的事。', `MaleText_loc7`='Mientras el regimiento de elfos de sangre cruzaba este mismo puente, los exarcas y vindicadores de los Aldor se alineaban para defender el Bancal de la Luz. Pero ocurrió algo imprevisto.' WHERE `ID`=17274;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나루가 나타나자 보렌살은 무릎을 꿇고 이렇게 말했습니다. "나루여, 환영 속에서 당신을 보았습니다. 당신은 우리 종족이 살아남을 수 있는 유일한 희망입니다. 저와 부하들은 당신을 따르고자 이곳에 왔습니다."', `MaleText_loc4`='当纳鲁走近他时，沃雷塔尔跪在他的面前，说道：“我在我的梦境里看到过您，纳鲁。您是我的族群唯一的生存希望。我和我的部下愿意为您效劳。”', `MaleText_loc5`='當那魯接近他時，沃藍索跪在他面前說出了這些話:「我在幻象中見過你，那魯。我們種族存活的希望就在你的手中。我和我的同伴是來效忠於你的」。', `MaleText_loc7`='Cuando el naaru se le acercó, Voren''thal se arrodilló ante él y pronunció estas palabras: ''Te he visto en mis sueños, naaru. La esperanza de supervivencia de mi raza está puesta en ti. Los que me siguen y yo estamos aquí para servirte.''' WHERE `ID`=17275;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나루는 캘타스를 배신한 이들을 받아들였습니다. 점술가 길드라고 불리게 된 그들은 지금 저 위 언덕에서 살고 있죠. 그곳은 점술가 길드에 속한 자들만이 마음 편히 드나들 수 있습니다.', `MaleText_loc4`='纳鲁接受了这些叛节的血精灵，他们被称为占星者。他们住在上面的平台，只有他们的追随者才被允许踏足那里。', `MaleText_loc5`='那魯接受叛離者，也就是占卜者;他們的住處就在平臺上方。只有被占卜者所接納的人才能到那裡去。', `MaleText_loc7`='Los naaru aceptaron a los desertores, que pasarían a llamarse los Arúspices; viven en esa plataforma de arriba. Solo aquellos que tengan el grado de iniciados con los Arúspices pueden entrar aquí.' WHERE `ID`=17276;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사실 알도르의 많은 사제들이 나루를 섬기겠다고 맹세한 그 마법학자들에게 살해되었었지요. 사제회의 일원들은 한때 적이었던 자들과 같은 도시에 산다는 게 별로 달갑지 않았던 것입니다.', `MaleText_loc4`='许多传教士曾经被那些如今发誓效忠纳鲁的魔导师们杀死。他们对于和旧日的敌人同住在一座城市里面感到非常不悦。', `MaleText_loc5`='許多教士都被現在發誓效忠那魯的博學者給殺害。他們不樂於和以前的敵人分享這個城市。', `MaleText_loc7`='Muchos sacerdotes murieron a manos de los magistri que ahora han jurado servir al naaru. No querían compartir la ciudad con sus antiguos enemigos.' WHERE `ID`=17277;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 위에 알도르의 가장 신성한 신전과 주거지들이 있습니다. 그 곳은 매우 신성한 장소로 사제회에 속한 자들만이 환영을 받는 곳이지요.', `MaleText_loc4`='奥尔多最神圣的庙宇和它周围的小建筑坐落在上面的广场上。作为一个神圣的场所，只有他们的追随者才被允许进入那里。', `MaleText_loc5`='奧多爾最神聖的神廟和它的環境住所都坐落於平臺之上。做為一個神聖的地點，只有被接納的人可以進入其中。', `MaleText_loc7`='El templo más sagrado de los Aldor y sus alrededores están en el bancal de arriba. Como lugar sagrado, solo pueden entrar los iniciados.' WHERE `ID`=17278;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그곳에서 그는 알도르 사제회와 점술가 길드의 지원을 받아 일리단의 군대와 계속해서 전투를 벌이고 있습니다. 그렇다고 해서 그 두 진영이 서로에 대한 오랜 적개심을 잊은 것은 아니죠.', `MaleText_loc4`='在奥尔多和占星者的协助下，他不断对伊利丹的军队发动着攻势。然而这两股势力并没有冰释前嫌。', `MaleText_loc5`='有奧多爾和占卜者的協助，他持續對伊利丹發動戰爭。不過，這兩個陣營仍未化解他們的舊仇。', `MaleText_loc7`='Allí continúa la guerra contra Illidan con la asistencia de Aldor y los Arúspices. Las dos facciones siguen alimentando sus viejos odios.' WHERE `ID`=17279;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사실, 바로 그런 해묵은 감정 때문에 그들은 나루를 돕고자 떠나는 영광스러운 임무를 맡으려고 경쟁을 벌입니다. 매일 이 도시의 아달이 그 결정을 내리죠. 군대는 어둠달 골짜기로 출정하기 전에 아달의 축복을 받으려고 이곳에서 집결합니다.', `MaleText_loc4`='他们争先恐后地想要为纳鲁效劳，想要在纳鲁那里获得更多的荣耀。可是睿智的阿达尔却能让这两个氏族维系着微妙的平衡。每一天，双方的军队都聚集在这里，等待由阿达尔选择要派遣谁前往影月谷参战。', `MaleText_loc5`='為了被派去協助那魯的殊榮而競爭，他們的敵意很深。每一天，阿達歐都會在這裡做下那個決定。軍隊聚集在這裡接受阿達歐的祝福再前往影月谷。', `MaleText_loc7`='Es tal su rivalidad que compiten hasta por el honor de asistir a los naaru aquí. Cada día, A''dal toma una decisión en este lugar. Los ejércitos se reúnen aquí para recibir la bendición de A''dal antes de salir para Sombraluna.' WHERE `ID`=17280;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이방인이여, 행운을 빌겠습니다. 그리고 샤트라스에 오신 것을 환영합니다.', `MaleText_loc4`='祝你好运，陌生人，欢迎来到沙塔斯城。', `MaleText_loc5`='祝好運，陌生人，歡迎來到撒塔斯城。', `MaleText_loc7`='Suerte, $gextranjero:extranjera; y $gbienvenido:bienvenida; a Shattrath.' WHERE `ID`=17281;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='샤트라스에 처음 오신 분이군요! 나중에 꼭 한번 들러주십시오. 환자들을 돌볼 일손이 늘 부족합니다.', `FemaleText_loc4`='一个新来的家伙！记得等一会过来看看，我们总是希望能有更多人帮这些伤者一把。', `FemaleText_loc5`='一個撒塔斯的新來者!記得以後要來拜訪。我們永遠都需要人手幫忙傷者。', `FemaleText_loc7`='¡$GUn forastero:una forastera; en Shattrath! Pásate más tarde por aquí. Siempre nos viene bien una mano con los heridos.' WHERE `ID`=17282;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카드가께서 친히 하인을 시켜 도시를 안내해 주신다고? 좋은 인상을 심어주셨나 보군요, $n.', `MaleText_loc4`='卡德加亲自带你参观？你肯定给他留下了一个好印象，$n。', `MaleText_loc5`='卡德加本人帶你參觀環境?你一定是給他了很好的印象，$n。', `MaleText_loc7`='¿Khadgar en persona te está enseñando el lugar? Has debido de impresionarlo, $n.' WHERE `ID`=17283;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언행을 조심하십시오. 저 친구가 카드가의 하인 곁에 붙어 있는 모습을 자주 봤습니다.', `MaleText_loc4`='注意你的言辞，卡德加的宠物正陪着这个人呢。', `MaleText_loc5`='小心你說的話，卡德加的寵物會聽到。', `MaleText_loc7`='Ten cuidado con lo que dices, se lo está enseñando todo la mascota de Khadgar.' WHERE `ID`=17284;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지금 농담하시는 건가요? 저는 점술가 길드의 일원이란 말입니다. 저는 언제나 말을 가려서 합니다. 그런데 이 도시에는 동지보다 적이 더 많은 것 같군요.', `FemaleText_loc4`='你在开玩笑吗？我是个占星者，我一直很注意我的言辞。看上去这个城市中的敌人比朋友多得多。', `FemaleText_loc5`='你在開玩笑嗎?我是一個占卜者，我向來都謹慎發言。看來這城市的敵人比盟友還多。', `FemaleText_loc7`='¿Estás de broma? Soy Arúspice. Siempre tengo cuidado con lo que digo. Por lo visto hay más enemigos que aliados en esta ciudad.' WHERE `ID`=17285;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성스러운 빛이 함께하기를, $n. 샤트라스에 오신 것을 환영합니다.', `MaleText_loc4`='愿圣光与你同在，$n。欢迎你来到沙塔斯。', `MaleText_loc5`='願聖光與你同在，$n。歡迎來到撒塔斯。', `MaleText_loc7`='Que la Luz esté contigo, $n. Y $gbienvenido:bienvenida; a Shattrath.', `FemaleText_loc1`='성스러운 빛이 함께하기를, $n. 샤트라스에 오신 것을 환영합니다.', `FemaleText_loc4`='愿圣光与你同在，$n。欢迎你来到沙塔斯。', `FemaleText_loc5`='願聖光與你同在，$n。歡迎來到撒塔斯。', `FemaleText_loc7`='Que la Luz esté contigo, $n. Y $gbienvenido:bienvenida; a Shattrath.' WHERE `ID`=17286;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 친구를 가려서 사귀는 편입니다, $n. 당신은 우리의 친구가 될 자격이 있다고 생각하시나요?', `MaleText_loc4`='我们选择朋友是有标准的，$n。你觉得你达到条件了吗？', `MaleText_loc5`='我們對於要和誰做朋友還滿挑剔的，$n。你覺得你有那個本事嗎?', `MaleText_loc7`='Somos muy quisquillosos a la hora de hacer amigos, $n. ¿Crees que tienes lo que se necesita?', `FemaleText_loc1`='우리는 친구를 가려서 사귀는 편입니다, $n. 당신은 우리의 친구가 될 자격이 있다고 생각하십니까?', `FemaleText_loc4`='我们选择朋友是有标准的，$n。你觉得你达到条件了吗？', `FemaleText_loc5`='我們對於要和誰做朋友還滿挑剔的，$n。你覺得你有那個本事嗎?', `FemaleText_loc7`='Somos muy quisquillosos a la hora de hacer amigos, $n. ¿Crees que tienes lo que se necesita?' WHERE `ID`=17287;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<주위 환경과 동화되면서 머리 부분이 희미해지는 대마법사 바르고스의 환영>$B$B파랄론의 초원을 본 적이 있다면 이곳이 같은 장소라는 걸 믿지 못할 것이오. 몇 달 전만 해도 이 땅은 서부 몰락지대와는 전혀 다른 모습이었소이다.$B$B지금은 모든 게 사라졌지. 대체 어떻게, 왜 그런 것일까?', `MaleText_loc4`='<影像的头部在环视周围时变得模糊起来。>$B$B如果你曾看到过法兰伦平原，你就不会相信眼下这个地方居然曾经是那种样子。仅仅几个月以前，这些原野看上去并不比西部荒野更糟糕。$B$B但是现在一切都不同了，这是怎么回事？到底为什么？', `MaleText_loc5`='<當影像開始顯現環境時，它的前端變的模糊不清。>$B$B如果你見過法拉隆平原，你不會相信這是同一個地方。幾個月前，這些地方在西部荒野不會看起來如此不恰當。$B$B現在一切都沒了，但是怎麼會這樣，又是為什麼?', `MaleText_loc7`='<La cabeza de la imagen se vuelve borrosa mientras se funde con lo que la rodea.>$B$BSi hubieras visto las Llanuras de Farahlon, no te creerías que es este mismo lugar. Hace solo unos meses, estos campos no habrían desentonado en los Páramos de Poniente.$B$BYa no queda nada. ¿Cómo ha sido? ¿Y por qué?' WHERE `ID`=17288;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생각했던 것보다 대지의 상태가 훨씬 좋지 않군. 계속해서 이런 식으로 손상된다면 파랄론, 그러니까 황천의 폭풍은 머지않아 우주의 먼지가 될 것이오.$B$B언제쯤 이런 일이 멈추게 될까? ''멈추기는 할까?''라고 묻는 게 더 낫겠구려.', `MaleText_loc4`='这个地方比我想像的差多了。如果破坏以这个速度继续下去，法兰伦——呃，虚空风暴很快就会变成宇宙的尘埃。$B$B我在想，它要被破坏到何种程度才会停止？或许我应该问，“它会停止吗？”', `MaleText_loc5`='這土地現在的情況比我想像的還要糟。如果傷害一直以這樣的速度持續下去，法拉隆 - 呃，虛空風暴很快就只是宇宙的碎石了。$B$B我納悶它會在哪裡停下?或許更好的問法是，''它會停下''嗎?', `MaleText_loc7`='La tierra está en peor estado de lo que me había imaginado. Si se sigue dañando a este ritmo, Farahlon, eh..., Tormenta Abisal no será más que un erial cósmico.$B$B¿Cuándo parará? Puede que la pregunta correcta sea ¿parará algún día?' WHERE `ID`=17289;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<겉모습이 아닌 마음속을 꿰뚫어보려는 듯한 대마법사 바르고스의 환영>$B$B마치 이 지역이 마력의 바다라도 된 것처럼 이곳에서 비전 마력의 흐름이 밀려왔다가 밀려나가고 있소이다. 첫 번째 대재앙 때에도 이 정도로 큰 피해는 없었는데 말이오.', `MaleText_loc4`='<大法师的影像似乎并没有看着你，而是注视着你的身后。>$B$B奥术能量的洪流使这个区域好像在被不可思议的力量拍打一样，这是日积月累的结果，而不是某一次灾难的产物。', `MaleText_loc5`='<大法師的影像似乎是看透你，而不是看著你。>$B$B這裡的秘法能量漲退和流動就好像淹沒在魔法能量海裡。就連第一次的大洪水也未造成這樣的損害。', `MaleText_loc7`='<La imagen del archimago parece atravesarte con la mirada en lugar de mirarte.>$B$BGalones y corrientes de energía arcana emanan y flotan como si la zona estuviera hundida en un mar de poder mágico. Ni siquiera el primer cataclismo causó tanto daño.' WHERE `ID`=17290;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 키린 토에 이런 고통을 준 캘타스에게 복수할 것이오! 그는 한때 우리의 형제였지만 더는 아니오.$B$B응분의 대가가 있을 것이오.$B$B<성공할 것이라는 기대는 그다지 많이 하지 않지만 단호한 표정으로 고개를 끄덕이는 대마법사 바르고스>$B$B캘타스는 단순한 도적 마법사가 아니오이다. 내가 만약 이 탑에서 벗어난다면 라반드위르와 나는 캘타스와 맞서 싸우는 자들을 도울 것이오.', `MaleText_loc4`='我要向凯尔萨斯复仇，为他对肯瑞托所做的暴行复仇！他曾经与我兄弟相称，但如今我们不再是兄弟了。$B$B我会找他算帐的。$B$B<大法师面沉似水地点了点头。>$B$B凯尔萨斯不仅仅是个无赖的法师。一旦我自由了，拉文德维尔和我会帮助任何与他为敌的人。', `MaleText_loc5`='我會為凱爾薩斯對祈倫托的惡行復仇!他曾是我們的兄弟之一，但現在再也不是了。$B$B他會有報應的。$B$B<大法師嚴肅地點點頭，並不喜歡這個可能性。>$B$B凱爾薩斯不只是個盜賊法師。一旦我從哨塔中自由了，羅樊德威和我就會協助任何想對抗他的人。', `MaleText_loc7`='¡Me vengaré de Kael''thas por esta traición al Kirin Tor! Una vez caminó entre nosotros como un hermano, pero ya no somos hermanos.$B$BLlegará la hora de la verdad.$B$B<El archimago asiente, sin que le entusiasme el panorama.>$B$BKael''thas es mucho más que un simple pícaro mago. Cuando esté liberado de esta torre, Ravandwyr y yo ayudaremos a quien quiera que se oponga a él.' WHERE `ID`=17291;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 뒤에 있는 보주는 한때 아제로스에서 일어나는 사건을 볼 수 있는 능력이 있었소이다.$B$B캘타스의 저주를 받아 모든 능력을 상실하긴 했지만 갇혀 지낸 긴 세월 동안 많은 마법사가 보주의 영상에서 위안을 찾았소이다.$B$B잊고 싶지 않다고 부르짖는 마법사가 있는가 하면 잊고 싶어 하는 마법사도 있었지.', `MaleText_loc4`='我身后的宝珠曾经可以用来窥视艾泽拉斯正在发生的事。$B$B凯尔萨斯的诅咒改变了一切，当然，在这么多年的隔离中，很多法师通过它的影像得到了慰籍。$B$B风吹不散长恨，花染不透乡仇。', `MaleText_loc5`='我身後的寶珠曾可以瞥見艾澤拉斯正在發生的事。$B$B當然，凱爾薩斯的詛咒改變了那一切，但在我們被隔離的幾年裡，許多法師都在它的影像中找到慰藉。$B$B有些人占卜是為了記憶;有人則是為了忘記。', `MaleText_loc7`='Hubo un tiempo cuando el orbe que ves detrás de mí era capaz de ver lo que sucedía en Azeroth.$B$BLa maldición de Kael''thas cambió todo eso, por supuesto, pero durante nuestros años de aislamiento, muchos de los magos encontraron alivio en sus imágenes.$B$BAlgunos las miraban para recordar, otros para olvidar.' WHERE `ID`=17292;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 죽이러 온 것이라면 번호표를 받아서 순서를 기다리게나.', `MaleText_loc4`='如果你是来杀我的，请先去取个号，然后去排队。', `MaleText_loc5`='如果你是被派來殺我的，請拿個號碼牌到旁邊等待。', `MaleText_loc7`='Si te han enviado a matarme, coge un número y espera tu turno.' WHERE `ID`=17293;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<억지 웃음으로 맞이하는 대마법사 바르고스>$B$B이 저주받은 보랏빛 탑에는 방이 많이 있소이다. 아무 때나 이리 오면 날 찾을 수 있을 것이오.', `MaleText_loc4`='<大法师瓦格斯发出扭曲的笑容，对你示好。>$B$B被诅咒的紫罗兰之塔映着明月。$B$B风吹过云影似梦。', `MaleText_loc5`='<大法師瓦戈斯給了你一個諷刺的微笑。>$B$B被詛咒的紫羅蘭之塔還有很多房間。$B$B任何時候，你都可以在這裡找到我。', `MaleText_loc7`='<El archimago Vargoth te sonríe irónicamente.>$B$BHay mucho sitio en la Torre Violeta.$B$BAquí me encontrarás en cualquier momento del año.' WHERE `ID`=17294;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그날 밤, 캘타스가 이 마을을 파괴했는데 나는 아무 도움도 되지 못했소. 그는 마법으로 날 탑에 가두어놓고 동료가 죽는 모습을 강제로 지켜보게 하여 더욱 고통스러웠지.$B$B지금도 저 멀리서 그들의 목소리가 들린다오. 자정이 되면 나를 깨우는 그 목소리가...', `MaleText_loc4`='在凯尔萨斯夷平村庄的那个晚上，我根本帮不上任何忙。他的魔法早已把我封印在塔中，我的随从们被折磨至死，他逼迫我亲眼目睹这一幕惨剧。$B$B昨夜的梦就在眼前，是谁把我留在这里空悲切。', `MaleText_loc5`='凱爾薩斯夷平村子的那個夜裡，我無能為力。他的魔法已把我封在哨塔裡，逼迫我目睹同伴的死來加重對我的折磨。$B$B而他們的聲音現在仍從遠方傳來，在夜裡把我喚醒。', `MaleText_loc7`='La noche en que Kael''thas arrasó el pueblo, yo no pude hacer nada para ayudar. Su magia ya me había encerrado en la torre, exacerbando mi tormento al obligarme a ver las muertes de los míos.$B$BY todavía, sus voces me llaman en la distancia, despertándome en mitad de la noche.' WHERE `ID`=17295;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자세를 낮춰! 내가 여기 있는 걸 놈들에게 들키기 싫단 말이다.$B$B우, 이거 정말 화나는데! 저 에테리얼들은 도대체 무슨 권리로 그런 생각을 하는 거야?$B$B이건 내 거라고!', `MaleText_loc4`='低调！我不想让他们看到我在这里。$B$B哦，这真让我火冒三丈！这些虚灵觉得他们自己是谁？$B$B这是我的地盘！', `MaleText_loc5`='小聲點!我不想讓他們看到我在這裡。$B$B喔，這真的讓我怒火中燒!這些以太族以為他們是誰啊?$B$B這是我的土地!', `MaleText_loc7`='¡Habla bajo! No quiero que me vean aquí.$B$B¡Ooh, esto me pone furioso! ¿Pero quién se creen que son esos etéreos?$B$B¡Ahora me toca a mí!' WHERE `ID`=17296;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='혼자 슬퍼하도록 제발 절 내버려 두세요.', `FemaleText_loc4`='请让我一个人独自伤心流泪。', `FemaleText_loc5`='請讓我自己靜一靜。', `FemaleText_loc7`='Por favor, déjame sola con mi tristeza.' WHERE `ID`=17297;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 돌아오신 것을 환영합니다.', `MaleText_loc4`='欢迎回来，$n。', `MaleText_loc5`='歡迎回來，$n。', `MaleText_loc7`='$gBienvenido:Bienvenida; de nuevo, $n.', `FemaleText_loc1`='$n, 돌아오신 것을 환영합니다.', `FemaleText_loc4`='欢迎回来，$n。', `FemaleText_loc5`='歡迎回來，$n。', `FemaleText_loc7`='$gBienvenido:Bienvenida; de nuevo, $n.' WHERE `ID`=17298;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 당신이라면 점술가 언덕에는 들어가지 않겠습니다. 그곳에선 아무도 당신을 환영하지 않아요.', `MaleText_loc4`='如果我是你的话，我就不会冒险进入占星者广场，$n。你在那里不受欢迎。', `MaleText_loc5`='如果我是你，我不會冒險進入占卜者平臺，$n。你在這裡不受歡迎。', `MaleText_loc7`='Si fuera tú, yo no entraría en el Bancal del Arúspice, $n. No creo que te den una cálida bienvenida.', `FemaleText_loc1`='제가 당신이라면 점술가 언덕에는 들어가지 않겠습니다. 그곳에선 아무도 당신을 환영하지 않아요.', `FemaleText_loc4`='如果我是你的话，我就不会冒险进入占星者广场，$n。你在那里不受欢迎。', `FemaleText_loc5`='如果我是你，我不會冒險進入占卜者平臺，$n。你在這裡不受歡迎。', `FemaleText_loc7`='Si fuera tú, yo no entraría en el Bancal del Arúspice, $n. No creo que te den una cálida bienvenida.' WHERE `ID`=17299;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아버지, 계속할 수 있도록 제게 힘을 주세요.', `FemaleText_loc4`='父亲，给我继续下去的力量吧。', `FemaleText_loc5`='父親，給我力量撐下去。', `FemaleText_loc7`='Padre, dame fuerza para seguir adelante.' WHERE `ID`=17300;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='계시를 내려 주십시오... 어떤 거라도...', `FemaleText_loc4`='给我一个启示……任何东西……', `FemaleText_loc5`='給我一點暗示...任何一點都好。', `FemaleText_loc7`='Dame una señal... algo...' WHERE `ID`=17301;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='부탁입니다, 아버지. 저는 아버지처럼 강하지 못합니다. 저 혼자서는 이 일을 할 수 없습니다. 제발 도와주십시오...', `FemaleText_loc4`='父亲，求你了。我没有你的力量。我一个人做不到。请帮帮我……', `FemaleText_loc5`='拜託，父親，我沒有你的力量。我無法自己辦到。請幫我...', `FemaleText_loc7`='Por favor, padre, yo no tengo tu fuerza. No puedo hacerlo sola. Por favor, ayúdame...' WHERE `ID`=17302;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 키득거리며 웃습니다.', `MaleText_loc4`='%s咯咯地笑。', `MaleText_loc5`='%s傻笑。', `MaleText_loc7`='%s suelta una risita.' WHERE `ID`=17303;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 고개를 끄덕입니다.', `MaleText_loc4`='%s点了点头。', `MaleText_loc5`='%s點點頭。', `MaleText_loc7`='%s asiente con la cabeza.' WHERE `ID`=17304;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 미소를 짓습니다.', `MaleText_loc4`='%s微笑着。', `MaleText_loc5`='%s微笑。', `MaleText_loc7`='%s sonríe.' WHERE `ID`=17305;
