UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 클라리사의 옷자락을 끌어당깁니다.', `MaleText_loc4`='%s拽着克拉里萨的长袍。', `MaleText_loc5`='%s用力拉克萊瑞莎的長袍。', `MaleText_loc7`='%s tira del vestido de Clarissa.' WHERE `ID`=17311;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엄마, 할아버지가 모두 다 잘 될 거라고 하셨어요.', `MaleText_loc4`='妈妈，爷爷说一切都会好起来的。', `MaleText_loc5`='媽咪，爺爺說一切都會沒事的。', `MaleText_loc7`='Mamá, el Abuelo dice que todo va a salir bien.' WHERE `ID`=17312;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='울지 마세요, 엄마. 할아버지가 걱정하지 말라고 하셨어요.', `MaleText_loc4`='不要哭，妈妈。爷爷说没什么可以担心的。', `MaleText_loc5`='別哭，媽咪。爺爺說不用擔心。', `MaleText_loc7`='No llores, mamá. El Abuelo dice que no hay por qué preocuparse.' WHERE `ID`=17313;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엄마, 할아버지가 우리를 지켜보시면서 지켜주신다고 하셨다니까요.', `MaleText_loc4`='妈妈，爷爷告诉我他会保证我们没事的。', `MaleText_loc5`='媽咪，爺爺告訴我他會守護我們確保我們沒事。', `MaleText_loc7`='Mamá, el Abuelo me dijo que nos protegería y se aseguraría de que estuviéramos bien.' WHERE `ID`=17314;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 눈물을 훔칩니다.', `FemaleText_loc4`='%s拭去了眼泪。', `FemaleText_loc5`='%s擦去眼淚。', `FemaleText_loc7`='%s seca las lágrimas.' WHERE `ID`=17315;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아가야, 할아버지는 돌아가셨단다. 하지만 괜찮을 거란다.', `FemaleText_loc4`='哦，宝贝，爷爷去世了。一切都会好起来的。', `FemaleText_loc5`='喔甜心，爺爺過世了。沒事的。', `FemaleText_loc7`='Cariño, el abuelito ya no está. Tranquilo, cielo.' WHERE `ID`=17316;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='괜찮을 거란다, 아가야.', `FemaleText_loc4`='我知道一切都会好起来的，宝贝。', `FemaleText_loc5`='我知道會沒事的，寶貝。', `FemaleText_loc7`='Sé que todo irá bien, cariño.' WHERE `ID`=17317;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='언젠가 우리 모두 함께하게 될 거란다, 아가야.', `FemaleText_loc4`='最终我们会团聚的，甜心。', `FemaleText_loc5`='最後，我們全都會在一起的，甜心。', `FemaleText_loc7`='Al final, todos estaremos juntos, cielo.' WHERE `ID`=17318;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='엄마가 널 지켜줄게, 아가야.', `FemaleText_loc4`='妈妈要确保你没事，宝贝。', `FemaleText_loc5`='媽咪會讓你平安無事的，寶貝。', `FemaleText_loc7`='Mami se va a asegurar de que estés bien, cariño.' WHERE `ID`=17319;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아무도 널 해치지 못하게 엄마가 지켜줄게, 아가야.', `FemaleText_loc4`='妈妈不会让任何人伤害你的，甜心。', `FemaleText_loc5`='媽咪不會讓任何人傷害你的，小心肝。', `FemaleText_loc7`='Mami no dejará que nadie te haga daño, cielo.' WHERE `ID`=17320;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좀 조용히 하라고! 이 망할 영혼들 같으니!', `MaleText_loc4`='安静！该死的灵魂！', `MaleText_loc5`='安靜!可惡，亡靈!', `MaleText_loc7`='¡Silencio! ¡Malditos seáis, espíritus!' WHERE `ID`=17321;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들이 날 이 수도원에서 내쫓으시겠다?', `MaleText_loc4`='他们会把我逐出修道院吗？', `MaleText_loc5`='把我從小修道院裡趕出去，他們會這麼做嗎?', `MaleText_loc7`='Me descartan de las prioridades, ¿verdad?' WHERE `ID`=17322;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들에게 보여주마... 모두에게 보여줄 것이다!', `MaleText_loc4`='我要让他们知道我的厉害！', `MaleText_loc5`='我會讓他們知道...我會讓他們所有人知道!', `MaleText_loc7`='Yo les enseñaré... ¡Les enseñaré a todos!' WHERE `ID`=17323;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니, 영혼들이여... 나는 그들이 모두 영원히 안에 갇힐까 봐 두렵다! 이제 날 내버려둬...', `MaleText_loc4`='不，灵魂，我恐怕他们都被永远困在里面了！现在，离我远点……', `MaleText_loc5`='不，亡靈，我擔心他們全都被困在裡面 - 永永遠遠!現在我要離開...', `MaleText_loc7`='No, espíritu, me temo que están todos atrapados dentro – ¡PARA SIEMPRE! Ahora déjame...' WHERE `ID`=17324;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계약을 어겼다? 내가 계약을 어겼다고? 그 멍청한 총독과 놈의 화신은 어떻고?', `MaleText_loc4`='我破坏了合约？我破坏了合约？？？那愚蠢的主教和他的化身是怎么回事？', `MaleText_loc5`='我破壞了盟約?我破壞了盟約?那個愚蠢的主教和他的化身又怎麼說?', `MaleText_loc7`='¿Que rompí un pacto? ¿QUE YO ROMPÍ UN PACTO? ¿Y qué hay de ese estúpido exarca y su avatar?' WHERE `ID`=17325;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽은 자는 말이 없는 법. 인제 그만 입을 다물어라!', `MaleText_loc4`='死人是不会说话的。现在闭上你的嘴！', `MaleText_loc5`='亡者不應說話。安靜!', `MaleText_loc7`='Se supone que los muertos no hablan. ¡Ahora, silencio!' WHERE `ID`=17326;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜? 이유가 뭐냐! 왜 내가 그런 "짐"을 짊어져야 하느냔 말이다!', `MaleText_loc4`='为什么？为什么！为什么我被“赐予”了这么个负担？', `MaleText_loc5`='為什麼?為什麼!我為何被「賦予」這樣的重擔?', `MaleText_loc7`='¿Por qué? ¡POR QUÉ! ¿Por qué me "regalaron" tal carga?' WHERE `ID`=17327;
