UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 당신이라면 여기서 물러나겠소. 당신은 아직 인정을 받지 못했군.', `MaleText_loc4`='如果我是你的话，我是不会再进一步的，$n。你没有进入上面的许可。', `MaleText_loc5`='如果我是你，我不會再往前進了，$n。你不被允許。', `MaleText_loc7`='Yo no seguiría más allá si fuese tú, $n. No estás autorizado a subir.', `FemaleText_loc1`='제가 당신이라면 여기서 물러나겠소. 당신은 아직 인정을 받지 못했군.', `FemaleText_loc4`='如果我是你的话，我是不会再进一步的，$n。你没有进入上面的许可。', `FemaleText_loc5`='如果我是你，我不會再往前進了，$n。你不被允許。', `FemaleText_loc7`='Yo no seguiría más allá si fuese tú, $n. No estás autorizado a subir.' WHERE `ID`=17332;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 신성한 땅에 접근하지 않는 게 신상에 좋을 거요, $n...', `MaleText_loc4`='你最好还是离我们的圣地远点，$n。', `MaleText_loc5`='離我們的神聖之地遠一點對你比較好，$n。', `MaleText_loc7`='Te sería beneficioso que te alejaras de nuestras tierras sagradas, $n.', `FemaleText_loc1`='우리의 신성한 땅에 접근하지 않는 게 신상에 좋을 거요, $n...', `FemaleText_loc4`='你最好还是离我们的圣地远点，$n。', `FemaleText_loc5`='離我們的神聖之地遠一點對你比較好，$n。', `FemaleText_loc7`='Te sería beneficioso que te alejaras de nuestras tierras sagradas, $n.' WHERE `ID`=17333;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에 들어오려면 먼저 당신의 가치를 증명해 보여야 하오, $n...', `MaleText_loc4`='$n，想要受欢迎，就得证明自己的实力。', `MaleText_loc5`='你必須向我們證明自己才能受到歡迎，$n。', `MaleText_loc7`='Tendrás que demostrar tu valía ante nosotros para ser $gbienvenido:bienvenida; aquí, $n.', `FemaleText_loc1`='이곳에 들어오려면 먼저 당신의 가치를 증명해 보여야 하오, $n...', `FemaleText_loc4`='$n，想要受欢迎，就得证明自己的实力。', `FemaleText_loc5`='你必須向我們證明自己才能受到歡迎，$n。', `FemaleText_loc7`='Tendrás que demostrar tu valía ante nosotros para ser $gbienvenido:bienvenida; aquí, $n.' WHERE `ID`=17334;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이보라고, 잠시만, $n. 여기 위에 구석이라고. 서둘러!', `MaleText_loc4`='喂，嘿，$n。上面，到这里来。快点！', `MaleText_loc5`='喂，嘿，$n。在平臺這裡。快!', `MaleText_loc7`='Psst, eh, $n. Súbete a la plataforma. ¡Rápido!' WHERE `ID`=17335;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇게 쉽게 당할 내가 아니다! 이 감옥의 벽이 흔들리고... 무너지리라!', `MaleText_loc4`='我是不会轻易倒下的！让这座牢狱的墙壁颤抖并崩塌吧！', `MaleText_loc5`='我不會這麼輕易就被擊敗!讓這座監獄的牆壁震顫...然後崩塌!', `MaleText_loc7`='¡No me iré tan fácilmente! ¡Que tiemblen los muros de esta prisión... y se derrumben!' WHERE `ID`=17336;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다 똑같은 놈들이야! 힘없는 새끼양, 쥐 같은 놈들!', `MaleText_loc4`='小羊羔！小旅鼠！它们都在！', `MaleText_loc5`='羔羊和旅鼠!全部都是!', `MaleText_loc7`='¡Corderos! ¡Lemmings! ¡Todos ellos!' WHERE `ID`=17337;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s의 상태가 불안정하게 변하더니 붕괴됩니다!', `MaleText_loc4`='%s变得不稳定起来，并开始瓦解！', `MaleText_loc5`='%s變的不穩定並開始瓦解!', `MaleText_loc7`='¡%s se vuelve inestable y comienza a desintegrarse!', `FemaleText_loc1`='%s의 상태가 불안정하게 변하더니 붕괴됩니다!', `FemaleText_loc4`='%s变得不稳定起来，并开始瓦解！', `FemaleText_loc5`='%s變的不穩定並開始瓦解!', `FemaleText_loc7`='¡%s se vuelve inestable y comienza a desintegrarse!' WHERE `ID`=17338;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비열하고 성가신 벌레들! 날 풀어다오. 최소한 자비로운 죽음을 선사할 테니!', `MaleText_loc4`='可悲的虫子！放了我，也许我可以让你们死得痛快点！', `MaleText_loc5`='無恥又多管閒事的蟲子!釋放我，或許我會讓你死的好看一點!', `MaleText_loc7`='¡Miserables, insectos entrometidos! ¡Libérenme y quizás les conceda una muerte clemente!' WHERE `ID`=17339;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 조그만 거머리들아, 내 피를 빨다가 사레나 들려라!', `MaleText_loc4`='寄生虫！吸血鬼！痛饮我的血液吧！', `MaleText_loc5`='害蟲!寄生蟲!敢拿我的血就讓你好看!', `MaleText_loc7`='¡Alimañas! ¡Sanguijuelas! ¡Tomen mi sangre y ahóguense en ella!' WHERE `ID`=17340;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일리단은 돼먹지 않은 멍청이에 불과하다. 그를 무너뜨리고 아웃랜드를 다시 손에 넣으리라!', `MaleText_loc4`='伊利丹是个傲慢的蠢货！我要毁灭他，重新统治外域！', `MaleText_loc5`='伊利丹是個自大的蠢蛋!我會毀滅他並重新奪回外域!', `MaleText_loc7`='¡Illidan es un tonto arrogante! ¡Lo aplastaré y recuperaré Terrallende!' WHERE `ID`=17341;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어리석은 기생충들아, 내 피는 나의 것이다!', `MaleText_loc4`='滚开，你们这些寄生虫！我的血是我自己的！', `MaleText_loc5`='走開，你這無腦的寄生蟲!我的血是我自己的!', `MaleText_loc7`='¡Fuera, estúpidos parásitos! ¡Mi sangre me pertenece!' WHERE `ID`=17342;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 보잘것없는 마법으로 얼마나 버틸 성싶으냐?', `MaleText_loc4`='你们以为自己那点可笑的魔法能把我困住多久？', `MaleText_loc5`='你覺得你可悲的法術還能箝制我多久?', `MaleText_loc7`='¿Cuánto creen que podrán retenerme con su patética brujería?' WHERE `ID`=17343;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나의 피로 너희는 파멸을 맞으리라!', `MaleText_loc4`='我的血就是你们的末日！', `MaleText_loc5`='我的血液會是你生命的終點!', `MaleText_loc7`='¡Mi sangre acabará con ustedes!' WHERE `ID`=17344;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로켓발사단장인 퓨즐라지가 X-52 황천 로켓을 건설하고자 지원자를 모집하고 있을 때 난 보안 부서에 이력서를 냈지.$B$B유감스럽게도 남은 자리는 선임기술자밖에 없었다네. 그나마 여기 자이롤이 있어서 어깨너머로 배울 기회가 있었지.', `MaleText_loc4`='当火箭主管弗斯拉格寻求志愿者来帮助他建造X-52虚空火箭的时候，我向安全工程部门投递了简历。$B$B不幸的是，唯一剩下的职位只有主工程师了。对我来说幸运的是，有塞希罗在这里盯着我不要犯错。', `MaleText_loc5`='當火箭主管夫斯拉吉在尋求志願者幫忙建造X-52虛空火箭時，我就向安全部門呈送了我的履歷。$B$B不幸的是，唯一剩下的職缺是首席工程師。不過我很幸運，有辛洛歐在這幫我檢查肩膀。', `MaleText_loc7`='Cuando el jefe de cohetes Fuselaje pedía voluntarios para ayudar a construir el cohete abisal X-52, entregué mi currículum para el departamento de seguridad.$B$BPor desgracia, el único puesto que quedaba era el de jefe de ingenieros. Para mi suerte, tengo aquí a Xyrol.' WHERE `ID`=17345;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가... 풀려났도다!', `MaleText_loc4`='我……自由了！', `MaleText_loc5`='我...被...釋放了!', `MaleText_loc7`='¡He... sido... liberado!' WHERE `ID`=17346;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불타는 군단이 너희 모두를 파멸시키리라!', `MaleText_loc4`='军团会吞噬你们！', `MaleText_loc5`='軍團會把你們全都毀滅!', `MaleText_loc7`='¡La Legión los consumirá a todos!' WHERE `ID`=17347;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼, 다시 그럴 수는 없다!', `MaleText_loc4`='不！不！！', `MaleText_loc5`='別再來了!別再來了...', `MaleText_loc7`='¡No... otra vez, no!' WHERE `ID`=17348;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 약하다고 생각했나? 자, 이제 누가 더 약한지 똑똑히 알았겠지!', `MaleText_loc4`='你们以为我很虚弱？看看现在谁更虚弱？', `MaleText_loc5`='你不是覺得我很弱嗎?很軟嗎?現在誰才是弱者?', `MaleText_loc7`='¿Pensabas que era débil? ¿Blando? ¿Quién es el débil ahora?' WHERE `ID`=17349;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으악, 도와줘! 마나 망령이다! 동족들의 복수를 하고 정수를 되찾으러 왔구나!', `MaleText_loc4`='救命！法力怨魂！它是来为它的同伴报仇的，而且还要偷走它们的精华！', `MaleText_loc5`='救命!法力怨靈!它來為它的同胞報仇並偷回它們的精華!', `MaleText_loc7`='¡Ayuda! ¡Un ánima de maná! ¡Ha venido a vengar a los suyos y a recuperar sus esencias!' WHERE `ID`=17350;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오십시오, 고난의 거리의 자유인들의 친구여. 하지만 오래 머무실 수는 없습니다.$B$B내부에서 싸움이 벌어지고 있습니다. 우리는 당신의 도움이 필요합니다!', `MaleText_loc4`='欢迎你，贫民窟自由民的朋友，但是不要在这里逗留太久。$B$B战斗的声音从里面传出，我的同胞需要你的帮助！', `MaleText_loc5`='歡迎，陰鬱城自由人民的朋友，但是不要逗留太久。$B$B裡面有戰鬥的聲響傳出。我的同伴需要你的協助!', `MaleText_loc7`='$gBienvenido:Bienvenida;, $gamigo:amiga; del Bajo Arrabal, pero no te demores.$B$BDel interior llegan sonidos de batalla. ¡Mis compatriotas estarán encantados de recibir tu ayuda!' WHERE `ID`=17351;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 고난의 거리에 친구가 된다면 당신과 거래를 하겠습니다.', `MaleText_loc4`='如果你成为了贫民窟的朋友，也许我们可以做点生意？', `MaleText_loc5`='如果你成為陰鬱城的朋友，或許我們可以做點生意?', `MaleText_loc7`='Si trabas amistad con el Bajo Arrabal, puede que hagamos negocios.' WHERE `ID`=17352;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='버르장머리를 고쳐주마, 요 쥐방울만한 놈!', `MaleText_loc4`='该好好给你上上家教课了，小$g子:姑娘;！', `MaleText_loc5`='是時候教你一點規矩了，小$g男孩:女孩;!', `MaleText_loc7`='¡Es hora de que aprendas una lección de modales, $gpequeño:pequeña;!' WHERE `ID`=17353;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='셋 셀 때까지 썩 꺼지지 않으면 험한 꼴을 보게 될 것이다.', `MaleText_loc4`='在我数到“3”之前，滚出这里，否则小心我放狗咬你。', `MaleText_loc5`='現在我要數到''3''，你最好趁我放狗咬人之前快點離開。', `MaleText_loc7`='Ahora voy a contar hasta tres para que te largues de aquí antes de que te eche encima a los perros.' WHERE `ID`=17354;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하나...', `MaleText_loc4`='1……', `MaleText_loc5`='1...', `MaleText_loc7`='1...' WHERE `ID`=17355;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='둘...', `MaleText_loc4`='2……', `MaleText_loc5`='2...', `MaleText_loc7`='2...' WHERE `ID`=17356;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도로 엄마 뱃속으로 들여보내 주마!', `MaleText_loc4`='是时候去见你的造物主了！', `MaleText_loc5`='是時候見你的造物者了!', `MaleText_loc7`='¡Es hora de ver a donde van los que se portan mal!' WHERE `ID`=17357;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 손마디를 우두둑 꺾습니다.', `MaleText_loc4`='%s捏了捏了他的手指关节。', `MaleText_loc5`='%s把他的關節弄的喀喀作響。', `MaleText_loc7`='%s chasca sus nudillos.' WHERE `ID`=17358;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 에테리얼 기술은 정말 놀랍지 않나요?!$B$B그들이 절 이곳에 머물도록 허락해 줘서 정말 기쁘답니다. 열심히 배울 겁니다... 그러다 보면 기술의 일부를 내 것으로 만들 수 있을지도 모르니까요!', `FemaleText_loc4`='你能相信虚灵的科技吗？！$B$B我当然愿意和他们待在这里。我会学到很多……也许还能给我自己弄一点！', `FemaleText_loc5`='你相信這個以太族技術嗎?!$B$B我當然很高興他們讓我一起留在這裡。我將會學到很多...或許還可以幫自己偷走一些!', `FemaleText_loc7`='¿No te parece increíble esta tecnología etérea?$B$BYo me conformo con que me dejen acercarme hasta aquí. Voy a aprender mucho... ¡Puede que consiga alguno de estos para mí!' WHERE `ID`=17359;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 너무 하네! 처음에는 마나 망령이 오더니 이번에는 추적자의 복수인가?! 이놈들아, 너희 정수는 절대 못 찾을 걸!', `MaleText_loc4`='哦，拜托！先是法力怨魂，现在又是追迹者？！不，你休想拿回你的魔精！', `MaleText_loc5`='喔，拜託!一開始是法力怨靈現在又是潛獵者的復仇?!不，你別想要回你的魔精!', `MaleText_loc7`='¡Venga! Primero la ánima de maná y ahora la venganza de este acechador. ¡No, hoy no vas a recuperar tu mojo!' WHERE `ID`=17360;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 좋소! 항복하겠소! 해치지만 마시오!', `MaleText_loc4`='好吧，我们投降！不要伤害我们！', `MaleText_loc5`='好吧，我們放棄!別傷害我們!', `MaleText_loc7`='¡Está bien, nos rendimos! ¡No nos hagas daño!' WHERE `ID`=17361;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='믿을 수 없어! 또 공격할 사람 있나?', `MaleText_loc4`='难以置信！还有其他人想攻击？', `MaleText_loc5`='不可思議!還有人想要攻擊的嗎?', `MaleText_loc7`='¡Increíble! ¿Alguien más quiere atacar?' WHERE `ID`=17362;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 의식을 잃습니다.', `MaleText_loc4`='%s失去了知觉。', `MaleText_loc5`='%s不省人事。', `MaleText_loc7`='%s pierde el conocimiento.' WHERE `ID`=17363;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꼬마야, 집어쳐라. 난 다른 바쁜 일이 있어서...', `MaleText_loc4`='跑吧，孩子。我还有事情要做……', `MaleText_loc5`='滾開，小鬼。我還有正事要做...', `MaleText_loc7`='¡Dale caña, $gchico:chica;! Tengo asuntos que atender...' WHERE `ID`=17364;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신한테 어떤 책이 있다고 에제키엘이 그러던데...', `MaleText_loc4`='伊瑟基尔说你可能有那本书……', `MaleText_loc5`='伊斯奇歐說你會有某本書...', `MaleText_loc7`='Ezekiel dijo que tú podrías tener cierto libro...', `FemaleText_loc1`='당신한테 어떤 책이 있다고 에제키엘이 그러던데...', `FemaleText_loc4`='伊瑟基尔说你可能有那本书……', `FemaleText_loc5`='伊斯奇歐說你會有某本書...', `FemaleText_loc7`='Ezekiel dijo que tú podrías tener cierto libro...' WHERE `ID`=17365;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자들이 공장 방어선을 돌파했다! 즉시 비상 방어 체제를 가동해라!', `MaleText_loc4`='入侵者已经突入了工厂！马上启动紧急防御协议！', `MaleText_loc5`='入侵者已破壞工廠!立刻開始緊急防禦措施!', `MaleText_loc7`='¡Intrusos han entrado en la fábrica! ¡Activad el protocolo de defensa de emergencia inmediatamente!', `FemaleText_loc1`='침입자들이 공장 방어선을 돌파했다! 즉시 비상 방어 체제를 가동해라!', `FemaleText_loc4`='入侵者已经突入了工厂！马上启动紧急防御协议！', `FemaleText_loc5`='入侵者已破壞工廠!立刻開始緊急防禦措施!', `FemaleText_loc7`='¡Intrusos han entrado en la fábrica! ¡Activad el protocolo de defensa de emergencia inmediatamente!' WHERE `ID`=17366;
