UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강한 힘과 영리한 머리를 가지고 있으며 날개가 달린 이 돌연변이들은 그 잔인함으로 전 우주에 악명을 떨치고 있습니다.', `MaleText_loc4`='这些长着翅膀的畸形怪物强大而又谨慎，他们的残忍在整个宇宙中都臭名昭著。', `MaleText_loc5`='強大又謹慎，這些多翼的失常者因為他們的殘忍而宇宙聞名。', `MaleText_loc7`='Potentes y prudentes, estas aberraciones con alas son conocidas en todo el cosmos por su brutalidad.', `FemaleText_loc1`='강한 힘과 영리한 머리를 가지고 있으며 날개가 달린 이 돌연변이들은 그 잔인함으로 전 우주에 악명을 떨치고 있습니다.', `FemaleText_loc4`='这些长着翅膀的畸形怪物强大而又谨慎，他们的残忍在整个宇宙中都臭名昭著。', `FemaleText_loc5`='強大又謹慎，這些多翼的失常者因為他們的殘忍而宇宙聞名。', `FemaleText_loc7`='Potentes y prudentes, estas aberraciones con alas son conocidas en todo el cosmos por su brutalidad.' WHERE `ID`=17370;
