UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사악하고 잔인한 격노수호병은 불타는 군단의 에레다르 고위직을 보호합니다.', `MaleText_loc4`='狡猾而纪律严明的愤怒卫士一直在保护着燃烧军团的艾瑞达主人们。', `MaleText_loc5`='憤怒守衛既狡猾又精準，他們通常保護軍團的埃雷達爾大師。', `MaleText_loc7`='Astuta y precisa, la guardia de cólera a menudo protege a los maestros eredar de la Legión.', `FemaleText_loc1`='사악하고 잔인한 격노수호병은 불타는 군단의 에레다르 고위직을 보호합니다.', `FemaleText_loc4`='狡猾而纪律严明的愤怒卫士一直在保护着燃烧军团的艾瑞达主人们。', `FemaleText_loc5`='憤怒守衛既狡猾又精準，他們通常保護軍團的埃雷達爾大師。', `FemaleText_loc7`='Astuta y precisa, la guardia de cólera a menudo protege a los maestros eredar de la Legión.' WHERE `ID`=17398;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잔인한 세이야드는 불타는 군단의 성전이 지닌 교활한 면을 보여 주는 좋은 증거입니다.', `MaleText_loc4`='残暴的萨亚德魅魔代表着燃烧军团的狡猾一面。', `MaleText_loc5`='殘忍的薩亞德妖女是軍團的恐怖主義遠征較微妙面的例子。', `MaleText_loc7`='Las crueles tentadoras sayaadi representan el lado más refinado de la cruzada de destrucción de la Legión.', `FemaleText_loc1`='잔인한 세이야드는 불타는 군단의 성전이 지닌 교활한 면을 보여 주는 좋은 증거입니다.', `FemaleText_loc4`='残暴的萨亚德魅魔代表着燃烧军团的狡猾一面。', `FemaleText_loc5`='殘忍的薩亞德妖女是軍團的恐怖主義遠征較微妙面的例子。', `FemaleText_loc7`='Las crueles tentadoras sayaadi representan el lado más refinado de la cruzada de destrucción de la Legión.' WHERE `ID`=17399;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='매우 카리스마적이자 살게라스에게 충실한 이 여사제들은 오직 살게라스의 죽음의 환영의 힘을 전파하기 위해서 살아갑니다.', `MaleText_loc4`='这些女祭司非常虔诚，并拥有非凡的魅力，她们生存的意义就是传播萨格拉斯的意志。', `MaleText_loc5`='這些女祭司既虔誠又極有魅力，她們為了宣揚薩格拉斯可怕幻象的力量而生存。', `MaleText_loc7`='Devotas y extremadamente carismáticas, estas sacerdotisas viven solo para evangelizar el poder de la visión de terror de Sargeras.', `FemaleText_loc1`='매우 카리스마적이자 살게라스에게 충실한 이 여사제들은 오직 살게라스의 죽음의 환영의 힘을 전파하기 위해서 살아갑니다.', `FemaleText_loc4`='这些女祭司非常虔诚，并拥有非凡的魅力，她们生存的意义就是传播萨格拉斯的意志。', `FemaleText_loc5`='這些女祭司既虔誠又極有魅力，她們為了宣揚薩格拉斯可怕幻象的力量而生存。', `FemaleText_loc7`='Devotas y extremadamente carismáticas, estas sacerdotisas viven solo para evangelizar el poder de la visión de terror de Sargeras.' WHERE `ID`=17400;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나스레짐은 불멸의 존재의 에너지를 먹고 사는 무자비한 악마입니다.', `MaleText_loc4`='纳斯雷兹姆是通过吞噬普通生物以获得力量的残忍的恶魔。', `MaleText_loc5`='納斯雷茲姆是殘酷的惡棍，以凡人生物的能量維生。', `MaleText_loc7`='Los Nathrezim son monstruos sin piedad que se alimentan de las energías de las criaturas mortales.', `FemaleText_loc1`='나스레짐은 불멸의 존재의 에너지를 먹고 사는 무자비한 악마입니다.', `FemaleText_loc4`='纳斯雷兹姆是通过吞噬普通生物以获得力量的残忍的恶魔。', `FemaleText_loc5`='納斯雷茲姆是殘酷的惡棍，以凡人生物的能量維生。', `FemaleText_loc7`='Los Nathrezim son monstruos sin piedad que se alimentan de las energías de las criaturas mortales.' WHERE `ID`=17401;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='교활하며 강력한 에레다르의 흑마법사들은 한때 우리의 소중한 동지였습니다.', `MaleText_loc4`='狡猾而强大的艾瑞达术士曾经是我们这个种族的贵族。', `MaleText_loc5`='狡猾，強大的埃雷達爾術士曾是我們高尚的親屬。', `MaleText_loc7`='Los astutos y poderosos brujos eredar fueron antaño nuestros nobles parientes.', `FemaleText_loc1`='교활하며 강력한 에레다르의 흑마법사들은 한때 우리의 소중한 동지였습니다.', `FemaleText_loc4`='狡猾而强大的艾瑞达术士曾经是我们这个种族的贵族。', `FemaleText_loc5`='狡猾，強大的埃雷達爾術士曾是我們高尚的親屬。', `FemaleText_loc7`='Los astutos y poderosos brujos eredar fueron antaño nuestros nobles parientes.' WHERE `ID`=17402;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 거대한 파괴자들은 불타는 군단의 사령관을 맡고 있습니다.', `MaleText_loc4`='这些庞大的毁灭者是燃烧军团的军事指挥官。', `MaleText_loc5`='這些巨像摧毀者是軍團的軍事指揮官。', `MaleText_loc7`='Estos destructores colosales sirven como comandantes militares de la Legión.', `FemaleText_loc1`='이 거대한 파괴자들은 불타는 군단의 사령관을 맡고 있습니다.', `FemaleText_loc4`='这些庞大的毁灭者是燃烧军团的军事指挥官。', `FemaleText_loc5`='這些巨像摧毀者是軍團的軍事指揮官。', `FemaleText_loc7`='Estos destructores colosales sirven como comandantes militares de la Legión.' WHERE `ID`=17403;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 왜소한 모아그들은 매우 영리하며 좀 더 큰 동족의 조수로 고용되기도 합니다.', `MaleText_loc4`='这些矮小的莫尔葛是非常聪明的物种，并且经常被当作他们大个子同胞的帮手使用。', `MaleText_loc5`='這些發育不良的莫阿格非常聰明，通常被他們體型較大的同胞雇用為幫手。', `MaleText_loc7`='Estos mo''arg atrofiados son muy listos y a menudo se les emplea como ayudantes de sus hermanos mayores.', `FemaleText_loc1`='이 왜소한 모아그들은 매우 영리하며 좀 더 큰 동족의 조수로 고용되기도 합니다.', `FemaleText_loc4`='这些矮小的莫尔葛是非常聪明的物种，并且经常被当作他们大个子同胞的帮手使用。', `FemaleText_loc5`='這些發育不良的莫阿格非常聰明，通常被他們體型較大的同胞雇用為幫手。', `FemaleText_loc7`='Estos mo''arg atrofiados son muy listos y a menudo se les emplea como ayudantes de sus hermanos mayores.' WHERE `ID`=17404;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야만적인 방법으로 보이겠지만 끔찍한 공포야말로 최고의 기술자이자 대장장이입니다.', `MaleText_loc4`='尽管他们看上去很野蛮，但这些用铁缝合起来的可怕生物其实是非常聪明的工程师和铸造匠。', `MaleText_loc5`='他們雖然看起來很粗野，但這些鐵打的恐怖人物是非常出色的工程師和鍛造鐵匠。', `MaleText_loc7`='Aunque puedan parecer brutos, estos pequeños monstruos de hierro son ingenieros y forjadores extremadamente brillantes.', `FemaleText_loc1`='야만적인 방법으로 보이겠지만 끔찍한 공포야말로 최고의 기술자이자 대장장이입니다.', `FemaleText_loc4`='尽管他们看上去很野蛮，但这些用铁缝合起来的可怕生物其实是非常聪明的工程师和铸造匠。', `FemaleText_loc5`='他們雖然看起來很粗野，但這些鐵打的恐怖人物是非常出色的工程師和鍛造鐵匠。', `FemaleText_loc7`='Aunque puedan parecer brutos, estos pequeños monstruos de hierro son ingenieros y forjadores extremadamente brillantes.' WHERE `ID`=17405;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모아그 종족 출신으로 불타는 군단에게 징병되었으며 이 전사들은 불타는 군단의 고위 계층의 사병입니다.', `MaleText_loc4`='他们是从莫尔葛种族中征募而来的战士，作为燃烧军团普通的士兵服役。', `MaleText_loc5`='這些戰士被莫阿格種族徵召，以軍團的軍隊和文件兵的身分效命。', `MaleText_loc7`='Reclutados de la raza mo''arg, estos guerreros sirven como soldados rasos de la Legión.', `FemaleText_loc1`='모아그 종족 출신으로 불타는 군단에게 징병되었으며 이 전사들은 불타는 군단의 고위 계층의 사병입니다.', `FemaleText_loc4`='他们是从莫尔葛种族中征募而来的战士，作为燃烧军团普通的士兵服役。', `FemaleText_loc5`='這些戰士被莫阿格種族徵召，以軍團的軍隊和文件兵的身分效命。', `FemaleText_loc7`='Reclutados de la raza mo''arg, estos guerreros sirven como soldados rasos de la Legión.' WHERE `ID`=17406;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 여기 오다니 신의 은총이로군. 마침 저녁 시간이 다 되었는데!', `MaleText_loc4`='感谢你的仁慈，晚饭时间快到了！', `MaleText_loc5`='謝天謝地你來到這裡，就快到晚餐時間了!', `MaleText_loc7`='¡Por fin llegas! Ya es casi la hora de cenar.' WHERE `ID`=17407;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하하! 우리가 간다, 난쟁이 고블린들아!', `MaleText_loc4`='哈哈哈！我们来了，小地精们！', `MaleText_loc5`='哈哈哈!我們是為你們而來的，小哥布林!', `MaleText_loc7`='¡Ja, ja, ja! ¡Vamos por ustedes, goblinitos!' WHERE `ID`=17408;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='휴... 정말 죽는 줄만 알았습니다.', `MaleText_loc4`='我以为我死定了。', `MaleText_loc5`='我還以為我鐵定沒救了。', `MaleText_loc7`='Pensé que estaba acabado.' WHERE `ID`=17409;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타락한 오크들에게 잡아먹히는 것과 노예상인인 라젤크라즈 밑에서 일하는 것 중 어느 게 더 불행하기 짝이 없는 인생인지 모르겠지만... 어쨌든 고맙습니다!', `MaleText_loc4`='我不知道是被邪兽人吃掉更糟呢，还是为拉泽克拉兹工作更糟？不管怎么样，还是谢谢你！', `MaleText_loc5`='我不知道哪一個比較糟，被魔獄獸人吃掉，還是為奴隸主人瑞絲坎茲工作!喔呃，還是謝謝你!', `MaleText_loc7`='No sé qué es peor, si que te coman orcos viles o trabajar para ese maestro de esclavos Razelcraz. Bueno, ¡gracias de todos modos!' WHERE `ID`=17410;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가지고 있는 물건을 보고 싶습니다.', `MaleText_loc4`='让我们看看你有些什么。', `MaleText_loc5`='讓我們看看你有什麼。', `MaleText_loc7`='Veamos qué tienes.', `FemaleText_loc1`='가지고 있는 물건을 보고 싶습니다.', `FemaleText_loc4`='让我们看看你有些什么。', `FemaleText_loc5`='讓我們看看你有什麼。', `FemaleText_loc7`='Veamos qué tienes.' WHERE `ID`=17411;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아킨둔의 영혼이 축복하는 자들은 유령의 조각이라는 형태로 이루어진 강력한 영혼을 사로잡을 수 있는 능력이 있다고 하오. 나는 여행을 하던 도중, 이 유령의 조각을 본 적이 있으나 아직 그들의 비밀을 밝혀내지 못했소이다.

내가 알아챌 수 있었던 유일한 사실은 그들이 아킨둔의 깊숙한 곳에서 왔다는 것이오. 유령의 조각을 보면 내게 넘겨주시오. 보상은 충분히 드리겠소...', `MaleText_loc4`='据说，那些被奥金顿之魂保佑的人们拥有一种强大的能力，可以捕获以幽魂碎片形态出现的强大灵魂。在我的旅途中，我不经意间得到了几个幽魂碎片，但我至今还没解开它们的秘密。

唯一我能洞悉的就是，它们似乎来自奥金顿的深处。如果你有机会得到这些幽魂碎片，我保证我会用让你觉得很有价值的东西来交换……', `MaleText_loc5`='據說那些受奧齊頓靈魂庇護的人具有一種能力，可以捕捉鬼靈裂片形式的強大靈魂。我在旅途中遇過一些這樣的鬼靈裂片，但仍未解開它們的秘密。

我唯一能分辨的事就是它們似乎是來自奧齊頓深處。如果你剛好碰到任何這種鬼靈裂片並將它們交給我，我確信我可以讓你心甘情願地拿來交換...', `MaleText_loc7`='Se dice que aquellos bendecidos por los espíritus de Auchindoun poseen la habilidad de capturar almas poderosas en forma de fragmentos de espíritus. Me he cruzado con algunos de estos fragmentos de espíritus en mis viajes, pero todavía debo desvelar sus secretos. 

Lo único que he podido percibir es que parecen originarse en las profundidades de la misma Auchindoun. Si por casualidad te cruzas con alguno de estos fragmentos de espíritus, estoy seguro de que te valdría la pena permitirme que te los quite de las manos...' WHERE `ID`=17412;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='짐 다 챙겼습니다. 준비 끝났습니다.', `MaleText_loc4`='我已经整装待发。', `MaleText_loc5`='我所有的背包都打包好了，我要走了。', `MaleText_loc7`='Ya he hecho todas mis maletas, estoy preparado para marcharme.' WHERE `ID`=17413;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='워워, 아직 로켓 준비가 덜 끝났습니다. 퓨즈가 완전히 타 버리거나 저 위에 당신 혼자 남는 일이 없도록 퓨즈 길이를 조절해야 해서 말이죠.', `MaleText_loc4`='飞船还没准备好。我们仍然需要调整保险丝的长度，以确保它不会烧坏而把你一个人留在那里。', `MaleText_loc5`='船還沒準備好。我們還需要校準引信長度以確保它不會燃燒殆盡把你獨自留在那裡。', `MaleText_loc7`='La nave aún no está lista. Aún tenemos que calibrar la longitud del fusible para asegurarnos de que no se quema y te deja por ahí tirado.' WHERE `ID`=17414;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불타는 군단이 아제로스의 전 지역을 공격하고 있습니다. 그들을 막을 영웅들의 힘이 필요합니다!', `MaleText_loc4`='燃烧军团正在攻击整个艾泽拉斯。我们需要英雄将他们击退。', `MaleText_loc5`='燃燒軍團的軍隊在攻擊整個艾澤拉斯。我們需要英雄來擊退他們!', `MaleText_loc7`='Los ejércitos de la Legión Ardiente están atacando por todo Azeroth. ¡Necesitamos héroes para expulsarlos!', `FemaleText_loc1`='불타는 군단이 아제로스의 전 지역을 공격하고 있습니다. 그들을 막을 영웅들의 힘이 필요합니다!', `FemaleText_loc4`='燃烧军团正在攻击整个艾泽拉斯。我们需要英雄将他们击退。', `FemaleText_loc5`='燃燒軍團的軍隊在攻擊整個艾澤拉斯。我們需要英雄來擊退他們!', `FemaleText_loc7`='Los ejércitos de la Legión Ardiente están atacando a todo Azeroth. ¡Necesitamos héroes para expulsarlos!' WHERE `ID`=17415;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 하려는 일은 뭡니까? 이 과학 어쩌구, 난 이해가 안 됩니다... 보라고요. 일주일에 닷새를 근무하는 게 내 일이란 말입니다.', `MaleText_loc4`='你说什么？我不太明白这些复杂的理论……瞧，这只是我一周五天的日常工作而已。', `MaleText_loc5`='你要做什麼?所有這些科學，我不懂...看，這就是我的工作，一週五天。', `MaleText_loc7`='¿Tenéis que hacer qué? Toda esa ciencia, no entiendo nada... Mira, esto es solo mi trabajo, cinco días a la semana.' WHERE `ID`=17416;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분명 로켓을 발사할 때까지는 긴 시간이 걸릴 겁니다. 가족들이 있는 집으로 우선 돌아가는 게 좋지 않겠습니까?', `MaleText_loc4`='事实上，距离发射还需要很长、很长时间。也许你应该调头回家去。', `MaleText_loc5`='實質上，在我們準備好發動前會是一段很長，很長的時間。或許你該回去家鄉找你的家人。', `MaleText_loc7`='Básicamente, va a pasar mucho, mucho tiempo antes de que estemos listos para despegar. Quizás deberías volver a casa, con tu familia.' WHERE `ID`=17417;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해골망치 초소로 가고자 합니다!', `MaleText_loc4`='借我一只双足飞龙。我要去断背岗哨！', `MaleText_loc5`='借我一隻雙足飛龍。我要去斷脊山脊!', `MaleText_loc7`='Déjame un jinete del viento. ¡Me voy a la Avanzada Rompeloma!', `FemaleText_loc1`='해골망치 초소로 가고자 합니다!', `FemaleText_loc4`='借我一只双足飞龙。我要去断背岗哨！', `FemaleText_loc5`='借我一隻雙足飛龍。我要去斷脊山脊!', `FemaleText_loc7`='Déjame un jinete del viento. ¡Me voy a la Avanzada Rompeloma!' WHERE `ID`=17418;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런... 못합니다. 난 가족들이 생각하는 그런 집에 있는 고블린이 아니란 말입니다. 게다가 난 가족들을 이리로 데려오지도 않았다고요.', `MaleText_loc4`='我不能，我不是他们所想的那种宅男。而且，我并没有把他们带到这里来。', `MaleText_loc5`='我不能。我不是那種他們認為的居家男人。何況，不是我把他們帶到這裡來的。', `MaleText_loc7`='No puedo. No soy el hombre que creen que soy en casa. Además, no los he traído.' WHERE `ID`=17419;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이리로 불러보는 건 어떻습니까? 가족은 당신에게 힘이 되어 줄 텐데요.', `MaleText_loc4`='为什么不？家庭可以给你力量。', `MaleText_loc5`='為何不?家庭會給你力量。', `MaleText_loc7`='¿Por qué no? Una familia puede darte fuerza.' WHERE `ID`=17420;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 참, 여기는 아이를 키울만한 곳이 아니라고요. 날씨도 춥고 아이들을 길러 줄 고블린도 없단 말입니다.', `MaleText_loc4`='这不是个适合你的孩子成长的地方。这里很冷，而且在这里没人能养育他们。', `MaleText_loc5`='這不是個適合撫養你孩子的地方。這裡很冷，而且又沒有人會撫養他們。', `MaleText_loc7`='Este no es el mejor lugar para criar a tus hijos. Hace frío, y podría no haber nadie para criarlos.' WHERE `ID`=17421;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이들을 기를 수가 없었단 말입니까?', `MaleText_loc4`='你不能养育他们吗？', `MaleText_loc5`='你不能撫養他們嗎?', `MaleText_loc7`='¿No podrías criarlos tú?' WHERE `ID`=17422;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 아니요, 아니요... 난 로켓 조종사란 말입니다.', `MaleText_loc4`='哦，不，不，不……我是飞行员。', `MaleText_loc5`='喔不，不，不...我是個火箭人。', `MaleText_loc7`='Oh, no, no, no... Soy un hombre de cohete.' WHERE `ID`=17423;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='글쎄요, 이미 말한 대로 발사 준비를 끝내려면 시간이 좀 걸릴 것 같습니다. 다시 알려드리지요.', `MaleText_loc4`='好吧，就像我说的那样。在飞船准备好飞行前，我们还需要一段时间。我会让你知道最新进展的。', `MaleText_loc5`='嗯，就像我說的;我們還要一陣子才能讓這艘船可以飛行。我們會隨時通知你的。', `MaleText_loc7`='Bueno, es como te he dicho; va a pasar algún tiempo antes de que tengamos esta nave lista para volar. Te mantendremos informado.' WHERE `ID`=17424;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수정으로 지어진 이 구조물은 마력으로 가득합니다. 눈앞에 이상한 문양의 환영이 나타나더니 빠른 속도로 연속해서 두루마리 모양이 됩니다.', `MaleText_loc4`='这座水晶建筑由于能量的流动不时地发出蜂鸣声。奇怪的符号在你面前闪烁，并快速地滚动着。', `MaleText_loc5`='這個水晶基底的建構發出能量的嗡嗡聲。奇怪的雕紋投射在你面前並快速地像卷軸般展開。', `MaleText_loc7`='Este constructo de cristal zumba con energía. Ante ti, se proyectan extraños glifos que se desplazan arriba y abajo con rapidez.' WHERE `ID`=17425;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달의 축제의 만월 동안 우리는 엘룬의 빛을 찬양합니다.', `MaleText_loc4`='当春节满月的时候，我们为月神之光而庆祝。', `MaleText_loc5`='在滿月的新年慶典中，我們慶祝伊露恩之光。', `MaleText_loc7`='Durante la luna llena del Festival Lunar Festival, celebramos la Luz de Elune.', `FemaleText_loc1`='달의 축제의 만월 동안 우리는 엘룬의 빛을 찬양합니다.', `FemaleText_loc4`='当春节满月的时候，我们为月神之光而庆祝。', `FemaleText_loc5`='在滿月的新年慶典中，我們慶祝伊露恩之光。', `FemaleText_loc7`='Durante la luna llena del Festival Lunar Festival, celebramos la Luz de Elune.' WHERE `ID`=17426;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바쁘다, 바빠! 할 일은 많고 시간은 없구나!$B$B불꽃 스패너를 어디에 뒀더라? 금방 쓰고 어디다 놨지... 이 근처 어딘데... 분명 좀 전에 손가락을 데었었는데!', `MaleText_loc4`='忙啊，太忙了！事情太多，时间太少！$B$B我把那个合金扳手放哪了？我知道就在这里的某个地方……我刚才还被那东西烫了手指！', `MaleText_loc5`='忙啊忙!好多事要做，時間卻好少!$B$B我把那個火扳手放到哪去了?我知道它就在這附近...我剛剛才被它燙到手指的!', `MaleText_loc7`='¡Ocupado, ocupado! ¡Tanto por hacer, tan poco tiempo!$B$BBueno, ¿dónde he puesto esa pirollave? Sé que está por aquí... ¡me he quemado los dedos con ella hace solo un momento!' WHERE `ID`=17427;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 세상의 모든 자들이 이 멋진 달의 축제를 계속 진행하는 게 전혀 놀랄 일이 아니로군요. 축제에 참여하기 위해 달숲에 꼭 가야겠습니다.', `MaleText_loc4`='这个世界的人民举行隆重的月亮庆典一点也不奇怪。我非常想去月光林地参加那个庆典。', `MaleText_loc5`='這片土地的人會舉辦盛大的新年慶典並不令人驚訝。我很願意去月光林地參加。', `MaleText_loc7`='No me sorprende que la gente de estas tierras celebren un Festival Lunar. Me gustaría mucho ir a Claro de la Luna para asistir.', `FemaleText_loc1`='이 세상의 모든 자들이 이 멋진 달의 축제를 계속 진행하는 게 전혀 놀랄 일이 아니로군요. 축제에 참여하기 위해 달숲에 꼭 가야겠어요.', `FemaleText_loc4`='这个世界的人民举行隆重的月亮庆典一点也不奇怪。我非常想去月光林地参加那个庆典。', `FemaleText_loc5`='這片土地的人會舉辦盛大的新年慶典並不令人驚訝。我很願意去月光林地參加。', `FemaleText_loc7`='No me sorprende que la gente de estas tierras celebren un Festival Lunar. Me gustaría mucho ir a Claro de la Luna para asistir.' WHERE `ID`=17428;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들에게 작업 속도를 높이라고 해라!', `MaleText_loc4`='让他们再干快点！', `MaleText_loc5`='叫他們工作快一點!', `MaleText_loc7`='¡Haz que trabajen más rápido!' WHERE `ID`=17429;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭풍 첨탑이 우리를 덮치기 전에 이 지옥절단기 기술 모두를 가지고 여기서 나가야 한다!', `MaleText_loc4`='我们必须在风暴尖塔的人教训我们之前拿到所有的魔能机甲技术，然后离开这里。', `MaleText_loc5`='我們一定要在風暴之尖倒向我們之前把所有這些惡魔劫奪者技術弄走!', `MaleText_loc7`='¡Hay que conseguir esa tecnología de atracador vil antes de que se nos eche encima Flecha de la Tormenta!' WHERE `ID`=17430;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='녀석들에게 가서 서두르라고 해라!', `MaleText_loc4`='去告诉他们快一点！', `MaleText_loc5`='去告訴他們快一點!', `MaleText_loc7`='¡Diles que se den prisa!' WHERE `ID`=17431;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='작업 속도가 너무 느리다! 가서 녀석들을 닦달해라!', `MaleText_loc4`='这项工作进展得太慢了。去催催他们！', `MaleText_loc5`='這次運作進行的太慢了。去刺激他們一下!', `MaleText_loc7`='Esta operación avanza con demasiada lentitud. ¡Ve a motivarlos!' WHERE `ID`=17432;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 지옥절단기 기술을 모두 챙겨서 아웃랜드의 다음 변환기까지 실어 나를 준비를 마쳐야 한다!', `MaleText_loc4`='我想把所有的魔能机甲技术整理好，准备在下次外域转向之前运出。', `MaleText_loc5`='我要帶走所有這些惡魔劫奪者技術並準備好在下一次的外域翻轉前運出!', `MaleText_loc7`='¡Quiero toda esa tecnología de atracador vil embalada y lista para la entrega en el próximo viaje a Terrallende!' WHERE `ID`=17433;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기, 너! 가서 녀석들이 일을 제대로 하고 있나 확인해 봐!', `MaleText_loc4`='你！去监督那些家伙的工作！', `MaleText_loc5`='嘿!去看看他們是不是都在工作!', `MaleText_loc7`='¡Tú! ¡Ve a asegurarte de que están haciendo su trabajo!' WHERE `ID`=17434;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인 의식을 가지고 일을 해야 할 거 아냐. 내가 모든 걸 직접 해야 하나? 가서 작업 속도 좀 올리라고 해!', `MaleText_loc4`='没有什么比得上经营自己的公司了。但是我必须事必躬亲吗？告诉他们加快速度！', `MaleText_loc5`='沒什麼像經營你自己的事業一樣棒的了。但我要自己做全部的事嗎?叫他們動作快一點!', `MaleText_loc7`='No hay nada como dirigir tu propia empresa. Pero, ¿tengo que hacerlo todo yo? ¡Diles que se den prisa!' WHERE `ID`=17435;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 배신자 케이지를 잡으면 내가 직접 심문하겠다! 가서 녀석을 찾아봐라!', `MaleText_loc4`='要是我们抓到那个叛徒卡尔伊，我会亲自把他拆开！去找他！', `MaleText_loc5`='如果我們能抓到那個背叛者凱澤，我要親自解決他!去找他!', `MaleText_loc7`='¡Si pillamos a ese traidor, Khay''ji, voy a encargarme de él personalmente! ¡Ve a buscarlo!' WHERE `ID`=17436;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 변장이 통할까?', `MaleText_loc4`='你觉得我们能制作一个看过得去的伪装吗？', `MaleText_loc5`='你覺得我們可以脫下可通行的偽裝嗎?', `MaleText_loc7`='¿Crees que podremos conseguir un disfraz pasable?' WHERE `ID`=17437;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 정도로 될지 모르겠군. 우리가 속이려는 것은 트로그가 아니니까.', `MaleText_loc4`='不知道这是不是足够好了，我们要愚弄的人并不是傻瓜。', `MaleText_loc5`='我不確定這是否會夠好。這些不是我們想愚弄的穴居怪。', `MaleText_loc7`='No sé si esto bastará. No estamos intentando engañar a troggs.' WHERE `ID`=17438;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='음... 어깨 부분이 잘못된 거 같군요. 그래도 비슷해 보이네요.', `FemaleText_loc4`='我觉得你把肩部弄错了，不过看上去已经很不错了。', `FemaleText_loc5`='我想你把肩膀的部分弄錯了。仔細看。', `FemaleText_loc7`='Creo que no tienes bien las hombreras. Eso parece, vamos.' WHERE `ID`=17439;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법에 대해 약간만 알고 있으면 이런 일을 할 때 편리하지. 환상이 모두를 완벽하게 속일 수 있는 것은 아니지만, 보통 일 처리하는 데 별문제는 없소.', `MaleText_loc4`='干这行，懂点魔法迟早有用。影像不能欺骗所有人，但是它们通常可以让你事半功倍。', `MaleText_loc5`='了解一點魔法在這行業還挺受用的。幻影不能永遠愚弄所有人，但它們通常可以讓事情進展的不錯。', `MaleText_loc7`='Viene bien saber un poco de magia para ese tipo de trabajos. Las ilusiones no pueden confundir a todo el mundo, pero casi siempre funcionan bastante bien.' WHERE `ID`=17440;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1을;를; 위해 만세 삼창을 합시다. 불타는 군단으로부터 우리 52번 구역을 구해준 고마운 친구요!', `MaleText_loc4`='为$n欢呼吧！$G他:她;从燃烧军团的手里拯救了我们的城镇！', `MaleText_loc5`='為$n歡呼三聲!$G他:她;從燃燒軍團的手中救回了城鎮!', `MaleText_loc7`='¡Tres hurras por $n! ¡Ha salvado la ciudad de la Legión Ardiente!' WHERE `ID`=17441;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='만세!', `MaleText_loc4`='万岁！', `MaleText_loc5`='萬歲!', `MaleText_loc7`='¡Hurra!' WHERE `ID`=17442;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일로 오셨나요? 그대는 지금 수송관에서 작업을 하고 있어야 할 시간 아닌가요?$B$B폭풍우 요새로 보내는 에너지의 양을 두 배로 늘렸기 때문에 빈둥거릴 여유가 전혀 없단 말입니다. 이곳에서 또다시 울트리스와 같은 일이 벌어져서는 안 됩니다.', `MaleText_loc4`='你在这里干什么？你不是应该在能量管道上工作吗？$B$B我们正在向风暴要塞传送两倍以上的能量，任何人都不能偷懒！我们不想看到这里变成另一个乌提斯。', `MaleText_loc5`='你在這裡幹嘛?你不是應該在能量管線上工作嗎?$B$B我們的能量比輸入風暴要塞的還要多兩倍以上，不能有人再遊手好閒了。我們不希望這裡再出現另一個奧崔斯。', `MaleText_loc7`='¿Qué haces aquí? ¿No deberías estar trabajando en la tubería de energía?$B$BHemos aumentado a más del doble la cantidad de energía que enviamos a El Castillo de la Tempestad y no podemos permitirnos que nadie gandulee. No queremos que suceda otro Ultris aquí.' WHERE `ID`=17443;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='울트리스요?', `MaleText_loc4`='乌提斯？', `MaleText_loc5`='奧崔斯?', `MaleText_loc7`='¿Ultris?', `FemaleText_loc1`='울트리스요?', `FemaleText_loc4`='乌提斯？', `FemaleText_loc5`='奧崔斯?', `FemaleText_loc7`='¿Ultris?' WHERE `ID`=17444;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당연히 울트리스 마나괴철로 말이지요! 당신, 어디 멀리 여행이라도 다녀왔나요?$B$B마나괴철로에 과부하가 걸려 엄청난 폭발이 일어났습니다. 그 일로 현실 세계에 균열이 생겼고 그곳을 통해 공허에서 온 생명체들이 쏟아져 나오고 있습니다. 북동쪽으로 가면 아무 데서나 그놈들을 볼 수 있습니다.', `MaleText_loc4`='当然是法力熔炉：乌提斯！你以为是哪里？$B$B那个法力熔炉由于超过负荷而造成了大爆炸。事实上，它已经被完全摧毁了，而现在虚空生物正川流不息地在那里涌现，就在东北方向，到处都是。', `MaleText_loc5`='法力熔爐奧崔斯，當然!你去哪了?$B$B法力熔爐已負荷過多並造成了巨大的爆炸。它在現實中留下了一個破洞而現在虛無生物都從裡面傾巢而出。你可以在東北方看到他們散佈各地。', `MaleText_loc7`='¡La forja de maná Ultris, por supuesto! ¿Dónde has estado?$B$BLa forja de maná se sobrecargó y creó una gran explosión. Dejó un desgarrón en la realidad y ahora las criaturas del vacío han estado entrando por ahí. Se las puede ver por todas partes hacia el noreste.' WHERE `ID`=17445;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 사자의 책을 읽습니다.', `MaleText_loc4`='%s从死亡之书内读着什么。', `MaleText_loc5`='%s閱讀亡者之書。', `MaleText_loc7`='%s lee del libro de los muertos.' WHERE `ID`=17446;
