UPDATE `locales_broadcast_text` SET `MaleText_loc1`='팻 네이글! 월드 디자인 팀입니다! 코리 스톡튼, 폴 C., 짐 채드윅, 스태츠, 에드 헤인스, 모리스, 고처, 제시!, 사라 B., 빅토르 C., 데이브 A.! 배경을 담당하고 있는 미술 팀입니다!', `MaleText_loc4`='Pat Nagle! World design team! Cory Stockton, Paul C., Jim Chadwick, Staats, Ed Hanes, Morris, Gotcher, Jesse!, Sarah B., Victor C., Dave A.! All of our amazing exterior artists!', `MaleText_loc5`='Pat Nagle! World design team! Cory Stockton, Paul C., Jim Chadwick, Staats, Ed Hanes, Morris, Gotcher, Jesse!, Sarah B., Victor C., Dave A.! All of our amazing exterior artists!', `MaleText_loc7`='¡Pat Nagle! ¡Equipo de diseño mundial! ¡Cory Stockton, Paul C., Jim Chadwick, Staats, Ed Hanes, Morris, Gotcher, Jesse! ¡Sarah B., Victor C., Dave A.! ¡Todos nuestros increíbles artistas exteriores!' WHERE `ID`=17450;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스콧 머서! 제프, 와이어트, 조, 트래비스, 크리스, 스티븐! 브레이지!', `MaleText_loc4`='Scott Mercer! Geoff, Wyatt, Joe, Travis, Kris, Steven! Brazie!', `MaleText_loc5`='Scott Mercer! Geoff, Wyatt, Joe, Travis, Kris, Steven! Brazie!', `MaleText_loc7`='¡Scott Mercer! ¡Geoff, Wyatt, Joe, Travis, Kris, Steven! ¡Brazie!' WHERE `ID`=17451;
