UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 사신이다! 너희의 마을을 파괴해 주마!', `MaleText_loc4`='我就是死神！！你们的城镇就要毁灭了！！！', `MaleText_loc5`='我就是死亡!讓你們的城鎮準備毀滅吧!', `MaleText_loc7`='¡SOY LA MUERTE! ¡QUE SU PUEBLO SE PREPARE PARA SER ELIMINADO!' WHERE `ID`=17455;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 저게 뭐지? 어서... 고철절단기 X6000으로 우릴 지켜줘!', `MaleText_loc4`='天哪！那是什么？快点，派再造机甲X6000型来保护我们！！！', `MaleText_loc5`='喔不!那是什麼?快，讓廢料劫奪者X6000保護我們!', `MaleText_loc7`='¡Oh, no! ¿Qué es eso? ¡¡¡Rápido, ponte al mando del atracador desguazador X6000!!!' WHERE `ID`=17456;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우트락 너 죽이겠다!', `MaleText_loc4`='乌尔特拉克要杀了你！', `MaleText_loc5`='烏崔克要殺了你!', `MaleText_loc7`='¡Urtrak mata a ti!' WHERE `ID`=17457;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='복수는 우리 것이다! 형제들이여, 공격하라!', `MaleText_loc4`='复仇属于我们！兄弟们，进攻！', `MaleText_loc5`='我們要復仇!兄弟們，攻擊!', `MaleText_loc7`='¡La venganza es nuestra! ¡Atacad hermanos!', `FemaleText_loc1`='복수는 우리 것이다! 형제들이여, 공격하라!', `FemaleText_loc4`='复仇属于我们！兄弟们，进攻！', `FemaleText_loc5`='我們要復仇!兄弟們，攻擊!', `FemaleText_loc7`='¡La venganza es nuestra! ¡Atacad hermanos!' WHERE `ID`=17458;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 백 년 전에 해야 했었던 일을 할 차례로군.', `MaleText_loc4`='开始做我几百年前就应该完成的事吧！', `MaleText_loc5`='現在要來做我一百年前就該做的事。', `MaleText_loc7`='Y ahora, a hacer lo que debería haber hecho hace cientos de años.' WHERE `ID`=17459;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두 번 다시 그럴 순 없다...', `MaleText_loc4`='不……', `MaleText_loc5`='永遠沒有下一次...', `MaleText_loc7`='Nunca más...' WHERE `ID`=17460;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정렬! 침입자들에게 혹독한 대가를 치르게 해줘라!', `MaleText_loc4`='让入侵者付出代价！', `MaleText_loc5`='列隊讓入侵者們付出代價!', `MaleText_loc7`='¡Formen filas y que paguen los intrusos!' WHERE `ID`=17461;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 대가를 치르더라도 저들을 막아야 한다!', `MaleText_loc4`='不惜一切代价，顶住！', `MaleText_loc5`='無論如何都要將它們擊退!', `MaleText_loc7`='¡Deténganlos a toda costa!' WHERE `ID`=17462;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 계시면 안전할 것입니다. 듀로 마나괴철로가 공격을 받은 이후 우리는 이곳의 보안을 강화했습니다.', `MaleText_loc4`='你在这儿应该很安全。法力熔炉：杜隆遭到攻击后我们便在此地增设了防御力量。', `MaleText_loc5`='你在這裡應該感覺安全了;法力熔爐杜羅遭受攻擊後我們已在附近增加了保全措施。', `MaleText_loc7`='Aquí no deberías tener miedo, hemos mejorado la seguridad de estas instalaciones después de los ataques a Forja de Maná Duro.' WHERE `ID`=17463;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 듀로 마나괴철로를 공격했습니까?', `MaleText_loc4`='谁攻击了法力熔炉：杜隆？', `MaleText_loc5`='誰攻擊了法力熔爐杜羅?', `MaleText_loc7`='¿Quién atacó Forja de Maná Duro?', `FemaleText_loc1`='누가 듀로 마나괴철로를 공격했습니까?', `FemaleText_loc4`='谁攻击了法力熔炉：杜隆？', `FemaleText_loc5`='誰攻擊了法力熔爐杜羅?', `FemaleText_loc7`='¿Quién atacó Forja de Maná Duro?' WHERE `ID`=17464;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='듀로 마나괴철로는 폭풍우 요새에서 가장 가까운 시설이기 때문에 물량의 대부분을 처리합니다.$B$B아시다시피 마나괴철로에 과부하가 걸리면 수송관에서 마나가 새기 마련이지요. 예기치 않은 사실이지만 그곳에서 발산된 기운에 마나 생명체들이 이끌리고 있습니다. 마나가 유출된 곳곳에서 마나 생명체들이 떼를 지어 튀어나오고 듀로 마나괴철로는 치명적인 타격을 받고 있습니다.$B$B하지만, 아직 폭발하지는 않았습니다.', `MaleText_loc4`='法力熔炉：杜隆是离风暴要塞最近的设备，因此它处理着大部分的负载。$B$B你应该知道，这些法力熔炉的负载会引起管道泄露。散发出的能量吸引着讨厌的法力生物，我们在多个泄漏点遭受到法力生物的袭击，此刻法力熔炉：杜隆所遭受的攻击最为猛烈。', `MaleText_loc5`='法力熔爐杜羅是離風暴要塞最近的設備，所以它承載大部份的負荷。$B$B你該知道，這些法力熔爐如果超載會讓管線造成漏洞。放射能量吸引了有害的法力生物。我們在許多漏洞地點都有生物侵擾的問題;法力熔爐杜羅目前最受打擊。', `MaleText_loc7`='Forja de Maná Duro son las instalaciones más cercanas a El Castillo de la Tempestad, así que se ocupa de la mayor parte de la carga.$B$BComo deberías saber, si estas forjas de maná se sobrecargan se producen derrames en los conductos y a veces no solo se derrama maná. Hemos tenido plagas de criaturas de maná en muchos puntos en que ha habido derrames; la Forja de Maná Duro fue la peor parada, hace un tiempo.$B$BPor lo menos no explotó como la Forja de Maná Ultris.' WHERE `ID`=17465;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하하! 네 약해 빠진 로켓은 파괴되었다! 나중에 다시 돌아와서 마을의 나머지 부분을 끝장내 주마!', `MaleText_loc4`='哈哈哈！你们可笑的火箭被毁灭了！我一会儿就回来解决你们这弱小的城镇！', `MaleText_loc5`='哈哈哈!你無用的火箭被摧毀了!我會再回來毀滅你的微小城鎮!', `MaleText_loc7`='¡JA, JA, JA! ¡TU LAMENTABLE COHETE HA SIDO DESTRUIDO! ¡PRONTO VOLVERÉ A POR EL RESTO DE TU MISERABLE PUEBLO!' WHERE `ID`=17466;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로서의 후예들에 대해 말씀해 주십시오.', `MaleText_loc4`='向我讲述洛萨之子的事吧。', `MaleText_loc5`='告訴我洛薩之子的事。', `MaleText_loc7`='Háblame de los Hijos de Lothar.', `FemaleText_loc1`='로서의 후예들에 대해 말씀해 주십시오.', `FemaleText_loc4`='向我讲述洛萨之子的事吧。', `FemaleText_loc5`='告訴我洛薩之子的事。', `FemaleText_loc7`='Háblame de los Hijos de Lothar.' WHERE `ID`=17467;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지옥절단기를 만들어서 날 막으려던 네 눈물겨운 시도는 실패로 끝났다! 이젠 52번 구역의 차례다!', `MaleText_loc4`='你想利用魔能机甲阻止我的企图失败了！现在，向52区前进！', `MaleText_loc5`='你想創造惡魔劫奪者來阻止我的可悲企圖已經失敗了!現在，進入52區!', `MaleText_loc7`='¡TU TRISTE INTENTO DE CREAR UN ATRACADOR VIL PARA DETENERME HA FRACASADO! AHORA, A LA ZONA 52.' WHERE `ID`=17468;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 기술을 사용해서 작업을 하는 건 정말 골치 아픈 일입니다. 모든 것이 이상한 방식으로 건설되었습니다.', `FemaleText_loc4`='采用这种技术进行工作让我非常头痛。所有东西都构造在一种怪异的方式上。', `FemaleText_loc5`='運用這個技術還真是令人頭痛。所有的東西都是用這樣不同的方法建造的。', `FemaleText_loc7`='Trabajar con esta tecnología me da dolores de cabeza. Todo esto está construido de forma rarísima.' WHERE `ID`=17469;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수년 전 내 부하들과 나는 마법사 카드가와 성기사 투랄리온을 따라 이 세계로 왔다네. 우리의 유일한 목적은 오크들과 그들의 사악한 일족을 멸종시키는 것이었지. 하지만 마지막 전투의 순간에 뭔가가 단단히 잘못되었다네.$B$B결국 이 어둠의 세계는 산산이 찢기고 내 동료는 공허 속으로 사라졌지.', `MaleText_loc4`='很多年以前，我和我的部下追随着卡德加和图拉扬来到这个世界。我们唯一的目标是消灭兽人和他们卑鄙的同类。然而在战争的最后时刻，有些事情变得十分糟糕。$B$B最终，这个黑暗的世界变得支离破碎——而我亲爱的朋友们则消失在虚空中。', `MaleText_loc5`='許多年前，我和我的人追隨巫師卡德加和聖騎士圖拉揚來到這個世界。我們唯一的目的就是徹底消滅獸人和他們邪惡的同類。但是在我們戰役的最後幾個小時發生了嚴重的錯誤。$B$B最後，這個黑暗世界分崩離析 - 我親愛的朋友都消失在虛無中。', `MaleText_loc7`='Hace muchos años, mis hombres y yo seguimos al mago Khadgar y al paladín Turalyon hasta este mundo. Nuestro objetivo era aniquilar a toda la horrible raza orca. Pero algo salió mal en el último momento.$B$BAl final, el mundo oscuro estalló en pedazos y mis amigos se perdieron en el vacío.' WHERE `ID`=17470;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 얘기해 주십시오.', `MaleText_loc4`='<更多>', `MaleText_loc5`='<更多>', `MaleText_loc7`='<más>', `FemaleText_loc1`='더 얘기해 주세요.', `FemaleText_loc4`='<更多>', `FemaleText_loc5`='<更多>', `FemaleText_loc7`='<más>' WHERE `ID`=17471;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 이후 우리 로서의 후예들은 이곳에 남아 싸우다 죽어 갔으며... 오늘 같은 날이 오게 해 달라고 기도했다네. 차원문이 열리고 우리 형제들이 우리를 고향으로 데려다 줄 그런 날을 말이지.$B$B정말 뛸 듯이 기쁘네만 아직 임무가 끝나지 않았다네. 이 세계를 떠나서 휴식을 취하기 전에 해야 할 일이 많네.', `MaleText_loc4`='我们，洛萨之子，从那时起就在这里坚持着，战斗……死亡……祈祷像今天这样的日子能早点到来，一个黑暗之门能够再次打开、我们的兄弟可以接我们回家的日子。$B$B虽然我们很高兴，但是职责仍然在召唤着我们。在我们离开这里享受安宁之前，仍然有很多事情要做。', `MaleText_loc5`='我們，洛薩之子，一直以來都待在這裡 - 作戰...死去...祈禱著今天會來到 - 傳送門打開，我們的兄弟送我們回家的一天。$B$B我們雖然歡欣鼓舞，但職責仍要堅守。在我們離開這世界獲得安息以前還有很多事要做。', `MaleText_loc7`='Nosotros, los hijos de Lothar, hemos permanecido aquí desde entonces - luchando... muriendo... rogando que llegara un día como el de hoy – un día en el que el Portal se abriera y nuestros hermanos vinieran a llevarnos a casa.$B$BPor más rebosantes de alegría que estemos, el deber sigue llamando. Hay mucho que hacer antes de poder marcharnos de este mundo y descansar.' WHERE `ID`=17472;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 안 돼! X-52 황천 로켓이 공격을 받고 있잖아! 경비병! 경비병!', `MaleText_loc4`='哦，天哪！X-52虚空火箭被攻击了！卫兵！卫兵！', `MaleText_loc5`='喔不!X-52虛空火箭正遭受攻擊!守衛!守衛!', `MaleText_loc7`='¡Oh, no! ¡Están atacando al cohete abisal X-52! ¡Guardias! ¡Guardias!' WHERE `ID`=17474;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 기술은 어디서 온 것입니까?', `MaleText_loc4`='这项技术是从哪儿来的？', `MaleText_loc5`='這種技術是從哪來的?', `MaleText_loc7`='¿De dónde ha salido esta tecnología?', `FemaleText_loc1`='이 기술은 어디서 온 것인가요?', `FemaleText_loc4`='这项技术是从哪儿来的？', `FemaleText_loc5`='這種技術是從哪來的?', `FemaleText_loc7`='¿De dónde ha salido esta tecnología?' WHERE `ID`=17475;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그들이 당신에게 초임자가 할 일에 대해 알려주지 않던가요? 이 마나괴철로는 폭풍우 요새의 부품으로 건설되었으며 황천으로부터 에너지를 흡수하도록 설계되었습니다.$B$B나루는 이 기술을 사용해서 여행하는 동안 그들의 비행선을 강화했지요. 이 기술이 지상에서 사용하기에 안전하지 않다고 주장하던 이들도 있었지만 그런 이들은 그 즉시 입막음을 당했습니다.', `FemaleText_loc4`='他们没有教你们这些新来的家伙任何东西吗？这些法力熔炉是作为风暴要塞的一部分而建造的，用来吸取虚空中的能量。$B$B纳鲁用这个技术在旅途中给他们的飞船供给动力。有人说那技术在陆地上使用可能不安全，然而他们很快就沉默了。', `FemaleText_loc5`='他們沒教你們新兵任何事嗎?這些法力熔爐是由風暴要塞的部分建造而成，用來吸取虛空的能量。$B$B那魯用這種技術來增強他們的飛船航行。有些人說這種技術在陸上使用可能不太安全。現在他們啞口無言了。', `FemaleText_loc7`='¿No os enseñan nada a los nuevos reclutas? Estas forjas de maná se construyeron a partir de partes de El Castillo de la Tempestad pensadas para succionar energía del vacío.$B$BLos naaru usaron esta tecnología para impulsar su nave durante sus viajes. Algunos dijeron que la tecnología puede que no sea segura para su uso en tierra. Se les hizo callar de inmediato.' WHERE `ID`=17476;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 다른 병사가 명예의 요새로 오고 있습니다... 쿠르드란의 수염을 걸고 말하는데 도움을 받을 수 있을 겁니다!', `MaleText_loc4`='又一个前往荣耀堡的士兵……以库德兰的胡须之名，他们正需要你的帮助！', `MaleText_loc5`='又一個士兵往$g他:她;去榮譽堡的路上了...以庫德蘭的鬍鬚為名，他們需要幫助!', `MaleText_loc7`='Otro soldado de camino al Bastión del Honor... ¡por la barba de Kurdran, podrán hacer uso de la ayuda!', `FemaleText_loc1`='또 다른 병사가 명예의 요새로 오고 있어요... 쿠르드란의 수염을 걸고 말하는데 도움을 받을 수 있을 거예요!', `FemaleText_loc4`='又一个前往荣耀堡的士兵……以库德兰的胡须之名，他们正需要你的帮助！', `FemaleText_loc5`='又一個士兵往$g他:她;去榮譽堡的路上了...以庫德蘭的鬍鬚為名，他們需要幫助!', `FemaleText_loc7`='Otro soldado de camino al Bastión del Honor... ¡por la barba de Kurdran, podrán hacer uso de la ayuda!' WHERE `ID`=17477;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명예의 요새로 가고자 합니다!', `MaleText_loc4`='送我到荣耀堡去！', `MaleText_loc5`='送我到榮譽堡!', `MaleText_loc7`='¡Envíame a Bastión del Honor!', `FemaleText_loc1`='명예의 요새로 가고자 합니다!', `FemaleText_loc4`='送我到荣耀堡去！', `FemaleText_loc5`='送我到榮譽堡!', `FemaleText_loc7`='¡Envíame a Bastión del Honor!' WHERE `ID`=17478;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악! 내 아름다운 X-52 황천 로켓이! 고장 난 로켓을 수리하려면 4배의 노력이 필요할 거야!', `MaleText_loc4`='啊！我漂亮的X-52虚空火箭。我们必须加倍努力才能修好它！', `MaleText_loc5`='哇!我美麗的X-52虛空火箭。我們要用四倍的努力來修補這個損壞!', `MaleText_loc7`='¡Ah! Mi precioso cohete abisal X-52. ¡Habrá que cuadruplicar esfuerzos para reparar estos daños!' WHERE `ID`=17479;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아시디시피 갑옷 제작은 제 열정입니다. 살아 있을 때나 죽었을 때나 갑옷 제작은 제가 가장 좋아하는 일이지요. 부디 저를 살아 있는 드레나이라고 생각해 주십시오. 제가 다시 한 번 느낌이라는 게 뭔지 알 수 있도록 해주십시오... 당신의 물건을 수리할 수 있는 영광을 제게 주십시오.', `MaleText_loc4`='那是我的爱好，你知道。无论生死，铸造装甲都是我的最爱。请把我当作一个还活着的德莱尼人吧，陌生人。让我再次体会那种感觉吧……请让我修理你的物品。', `MaleText_loc5`='是我的熱情，你知道。不管生與死，護甲鍛造是我的愛好。請把我當做一個還活著的德萊尼對待，陌生人。讓我再次知道那是什麼感覺...讓我有那個榮幸為你修理物品。', `MaleText_loc7`='Es mi pasión, sabes. En la vida y en la muerte, la artesanía de armas es lo que amo. Por favor, trátame como si fuera un draenei vivo, $gextranjero:extranjera;. Deja que vuelva a saber lo que es sentir... Permíteme el honor de reparar tus objetos.' WHERE `ID`=17480;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 물건을 수리해 주십시오.', `MaleText_loc4`='请修理一下我的物品吧。', `MaleText_loc5`='請修理我的物品。', `MaleText_loc7`='Repara mis objetos.', `FemaleText_loc1`='제 물건을 수리해 주십시오.', `FemaleText_loc4`='请修理一下我的物品吧。', `FemaleText_loc5`='請修理我的物品。', `FemaleText_loc7`='Repara mis objetos.' WHERE `ID`=17481;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무역연합은 작시스 배신자들에게 반드시 복수할 겁니다!', `MaleText_loc4`='星界财团会对那些萨克希斯背叛者进行复仇的！', `MaleText_loc5`='聯合團會對薩希斯背叛者復仇的!', `MaleText_loc7`='¡El Consorcio se vengará de los traidores Zaxxis!' WHERE `ID`=17482;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 우리 일을 돕기 위해 새로 온 용사인가? $n, 무슨 일로 왔는지 말해 보게나.', `MaleText_loc4`='啊，一个来帮助我们的新勇士？你说呢，$n？', `MaleText_loc5`='啊，一個來幫助我們理想的新勇士?你好嗎，$n?', `MaleText_loc7`='Ah, un nuevo campeón para nuestra causa. ¿Qué dices, $n?' WHERE `ID`=17483;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 로서의 후예들은 여기 지옥불 반도에서 20년 동안을 싸워 왔네. 우리는 이곳의 토착 오크들과 불타는 성전의 끔찍한 악마들에게 사방으로 포위되었네. 우리의 가슴은 여전히 힘차게 고동치고 있지만 수년간의 전쟁을 치르면서 그 수가 많이 줄었지.$B$B자네와 아제로스에서 온 영웅들이 등장한 것은 정말 반가운 일이라네!', `MaleText_loc4`='$n，洛萨之子曾经在这里，在地狱火半岛，战斗了整整二十年。我们被这里的兽人和燃烧军团的恶魔们困扰着，虽然我们心中仍充满激情，但年复一年的战斗让我们的人手越来越少。$B$B你，从艾泽拉斯赶来的新一代的英雄，我们欢迎你的到来！', `MaleText_loc5`='$n，洛薩之子曾在此作戰，就在地獄火半島上，長達二十年的時間。我們被當地的獸人和燃燒軍團的地獄惡魔四面包圍，雖然我們的心仍強烈地跳動，連年作戰卻已削減了我們的數量。$B$B你，和艾澤拉斯湧入的新世代英雄們，真的是我們所樂見的!', `MaleText_loc7`='$n, los hijos de Lothar han luchado aquí, en la península del Fuego Infernal, durante dos décadas. Nos vemos acosados por todos lados por orcos indígenas y demonios infernales de la Cruzada Ardiente y, aunque nuestros corazones siguen latiendo con fuerza, años de guerra han reducido nuestros números.$B$B¡Tú, y el influjo de la nueva generación de héroes de Azeroth, sois, sin lugar a dudas, una visión bien acogida!' WHERE `ID`=17484;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='삐!', `MaleText_loc4`='吡！', `MaleText_loc5`='嗶!', `MaleText_loc7`='¡Bip!' WHERE `ID`=17485;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기, 당신! 사탕 좀 드릴까?', `MaleText_loc4`='嘿，说你呢。想要些糖吗？', `MaleText_loc5`='嘿，你好。想要一些糖果嗎?', `MaleText_loc7`='Eh, tú. ¿Quieres golosinas?' WHERE `ID`=17486;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 가난한 예술가를 위해 온정의 손길을 베푸실 분?', `MaleText_loc4`='施舍施舍我这个饿得要死的艺术家吧？', `MaleText_loc5`='施捨一點零錢給快餓死的藝術家好嗎?', `MaleText_loc7`='¿Te sobran algunas monedas para un artista hambriento?' WHERE `ID`=17487;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요! 잠깐... 누구 없습니까?', `MaleText_loc4`='啥？！等等……有人吗？', `MaleText_loc5`='如何啊孩子!慢著...有人在嗎?', `MaleText_loc7`='¡Qué pasa, hijo! Espera... ¿hay alguien ahí?' WHERE `ID`=17488;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지옥불 성채에 있는 오크에 대해 말씀해 주십시오.', `MaleText_loc4`='告诉我一些关于地狱火兽人的事吧。', `MaleText_loc5`='告訴我地獄火獸人的事。', `MaleText_loc7`='Háblame de los orcos del Fuego Infernal.', `FemaleText_loc1`='지옥불 성채에 있는 오크에 대해 말씀해 주십시오.', `FemaleText_loc4`='告诉我一些关于地狱火兽人的事吧。', `FemaleText_loc5`='告訴我地獄火獸人的事。', `FemaleText_loc7`='Háblame de los orcos del Fuego Infernal.' WHERE `ID`=17489;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오크들... 나는 한 평생을 오크들과 싸웠네.$B$B20년 전 우리는 호드를 제압하고 지옥불 성채의 성벽을 무너뜨렸네. 우리는 비열한 녹색 괴물들을 위기로 몰아넣었지! 그 일이 있은 후 우리는 몇 번의 사소한 충돌을 제외하고는 오크들로부터 별다른 위협을 받지 않았다네.$B$B현재까지는 말이야...', `MaleText_loc4`='兽人。看来我一辈子都要和他们作战了。$B$B二十年以前，我们击败了部落，推倒了地狱火堡垒的城墙。我们把那些卑鄙的绿怪物逼了毁灭的边缘！在那以后，除了少数冲突以外，那些堕落的兽人们再也没有对我们构成任何威胁。$B$B直到现在。', `MaleText_loc5`='獸人。我的一生似乎都在與他們作戰。$B$B二十年前我們粉碎了部落，拆毀了他們地獄火堡壘的城牆。我們把邪惡的綠皮膚趕到最邊緣!在那之後，除了一些小衝突，破碎的獸人再也沒有對我們造成威脅了。$B$B一直到了現在。', `MaleText_loc7`='Orcos. Creo que me he pasado la vida luchando contra ellos.$B$BHace veinte años, dividimos a la Horda y destruimos los muros de su Ciudadela del Fuego Infernal. ¡Dimos una buena lección a esos pieles verdes! Después de eso, a parte de alguna que otra escaramuza, los orcos ya no eran una amenaza.$B$BHasta ahora.' WHERE `ID`=17490;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 도전할 자가 남아 있느냐?', `MaleText_loc4`='还！有！谁！', `MaleText_loc5`='沒有人留下來測試我嗎?', `MaleText_loc7`='¿Ya no hay nadie que quiera probarme?' WHERE `ID`=17491;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희의 종말이 다가오고 있다.', `MaleText_loc4`='你们时日不多了！', `MaleText_loc5`='你的時間不多了!', `MaleText_loc7`='¡Se les acaba el tiempo!' WHERE `ID`=17492;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미개한 종족아! 나는 높으신 분의 부름을 받는 몸이시다.', `MaleText_loc4`='你们不值一提！我只听从主人的召唤……', `MaleText_loc5`='你什麼都不是!我效命於更高層次的人...', `MaleText_loc7`='¡No son nada! Respondo a una llamada superior…' WHERE `ID`=17493;
