UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠에서 깬 제로미가 천천히 일어납니다.', `MaleText_loc4`='耶罗米醒了过来，慢慢地伸了伸脚。', `MaleText_loc5`='傑洛米醒來並慢慢站起來。', `MaleText_loc7`='Jero''me despierta y se levanta lentamente.' WHERE `ID`=17513;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명예의 요새에 온 것을 환영하네, $n. 만나서 반갑군.', `MaleText_loc4`='欢迎来到荣耀堡，$n。你能来真是太好了。', `MaleText_loc5`='歡迎來到榮譽堡，$n。有你真好。', `MaleText_loc7`='$gBienvenido:Bienvenida; al Bastión del Honor, $n. Nos alegramos de tenerte aquí.' WHERE `ID`=17514;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠의 존재가 저를 붙잡고 있습니다, 주인님. 죽은 저를 찾아오시다니 주인님은 정말 자비로운 분이십니다. 저를 용서하십시오...', `MaleText_loc4`='黑暗控制了我，主人。死亡对我是最仁慈的惩罚。原谅我……', `MaleText_loc5`='黑暗者控制了我，主人。你奪取我的性命是慈悲的。原諒我...', `MaleText_loc7`='Los oscuros me han capturado, maestro. Has sido clemente al buscar mi muerte. Perdóname...' WHERE `ID`=17515;
