UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대부님? 대부님이세요?', `FemaleText_loc4`='父亲？是你吗？', `FemaleText_loc5`='父親?父親那是你嗎?', `FemaleText_loc7`='¿Padre? ¿Eres tú, padre?' WHERE `ID`=17518;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='괜찮을 것이다, 얘야. 더는 슬퍼 말거라...', `MaleText_loc4`='没事的，亲爱的。不要再伤心了……', `MaleText_loc5`='一切都會沒事的，寶貝。別再苦惱了...', `MaleText_loc7`='Todo irá bien, $gquerido:querida;. No te aflijas más...' WHERE `ID`=17519;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 고개를 끄덕입니다.', `MaleText_loc4`='%s点了点头。', `MaleText_loc5`='%s點點頭。', `MaleText_loc7`='%s asiente con la cabeza.' WHERE `ID`=17520;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='약 20년 전 얼라이언스는 오크들을 완전히 뿌리 뽑을 생각으로 이 세계에 첫 번째 원정대를 보냈소. 정말... 끔찍한 싸움이었지. 수많은 영혼이 아제로스의 안전을 위해 용감하게 싸우다 사라져 갔소이다.$B$B하지만 일부 영혼들은... 영원한 전쟁 속에 갇혀 있다오.', `MaleText_loc4`='大概二十年以前，联盟展开了对这个世界的第一次远征，希望可以永久根除兽人的威胁。那是一场……可怕的战争。很多勇敢的灵魂为保证艾泽拉斯的安全牺牲了。$B$B有些灵魂仍然……滞留在这无尽的战斗中。', `MaleText_loc5`='大約二十年前，聯盟發動了第一次的世界遠征，希望能永遠根除獸人。那是一場...可怕的鬥爭。許多勇敢的靈魂為了保衛艾澤拉斯的安全而喪命。$B$B然而有些靈魂仍然...被鎖在永恆的戰鬥中。', `MaleText_loc7`='Hace unos veinte años, la Alianza envió la primera Expedición a este mundo con la esperanza de erradicar a los orcos para siempre. Fue un... conflicto terrible. Muchas almas valientes perecieron para asegurar la seguridad de Azeroth.$B$BPero algunas almas permanecen... en combate eterno.' WHERE `ID`=17521;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='약 20년 전 얼라이언스는 오크들을 완전히 뿌리 뽑을 생각으로 이 세계에 첫 번째 원정대를 보냈소. 정말... 끔찍한 싸움이었지. 수많은 영혼이 아제로스의 안전을 위해 용감하게 싸우다 사라져 갔소이다.$B$B그런 영혼들에게 안식을 가져다줘서 정말 고맙소이다, $n.', `MaleText_loc4`='大概二十年以前，联盟展开了对这个世界的第一次远征，希望可以永久根除兽人的威胁。那是一场……可怕的战争。很多勇敢的灵魂为保证艾泽拉斯的安全牺牲了。$B$B谢谢你让那些灵魂安息，$n。', `MaleText_loc5`='大約二十年前，聯盟發動了第一次的世界遠征，希望能永遠根除獸人。那是一場...可怕的鬥爭。許多勇敢的靈魂為了保衛艾澤拉斯的安全而喪命。$B$B謝謝你，$n，希望那些靈魂能獲得安息。', `MaleText_loc7`='Hace unos veinte años, la Alianza lanzó la primera expedición a este mundo con la intención de eliminar a los orcos para siempre. Fue... una batalla terrible. Murieron muchos valientes para defender a Azeroth. $B$BGracias, $n, por contribuir al descanso de sus almas.' WHERE `ID`=17522;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명예의 요새를 지키는 이들은 여기 이 끔찍한 땅에 모두의 피와 청춘을 바쳤습니다... 하지만 여전히 드높은 기개를 잃지 않았습니다!$B$B이제 당신과 당신 동료가 도와준다면 우리가 전세의 흐름을 바꿀 수 있을 겁니다. 당신은 우리에게 언젠가 고향으로 돌아갈 수 있다는 희망을 주셨습니다.', `MaleText_loc4`='荣耀堡的人们在这块恶魔横行的土地上浴血奋战，献出了他们的青春……而如今他们仍然激情不退！$B$B现在你和从艾泽拉斯来的军团可以帮助我们扭转局面。是你给了我们重返家乡的希望。', `MaleText_loc5`='榮譽堡的男男女女揮灑了這麼多熱血，失去了他們在這可怕土地上的青春...但他們仍然堅守高昂的精神!$B$B現在，你和你從艾澤拉斯來的同伴可以幫助我們扭轉情勢。你讓我們對有一天能回到家鄉有了希望。', `MaleText_loc7`='Los hombres y mujeres de Bastión del Honor han derramado mucha sangre y han perdido a sus hijos en esta horrible tierra... ¡Y a pesar de eso, siguen luchando con la moral alta!$B$BAhora, tú y tus seguidores de Azeroth podéis ayudar a que cambien las tornas. Gracias a ti ha vuelto la esperanza de regresar a nuestras tierras.' WHERE `ID`=17523;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 도와줘서 정말 고맙소. 언젠가 나는 이 탑과 캘타스의 저주받은 마법에서 풀려 나게 될 겁니다!', `MaleText_loc4`='我不知道该怎么感谢你才好了，$n。终于，我终于可以摆脱凯尔萨斯那该死的魔法，重获自由了！', `MaleText_loc5`='我無法表達對你的感謝，$n。終於，我可以從這座哨塔和凱爾的該死魔法中自由了!', `MaleText_loc7`='No puedo agradecerte tu ayuda lo suficiente, $n. ¡Al fin seré libre de esta torre y de la detestable magia de Kael!' WHERE `ID`=17524;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 고향에 대해 말씀해 주십시오.', `MaleText_loc4`='给我讲讲你的家乡。', `MaleText_loc5`='告訴我你的家鄉。', `MaleText_loc7`='Háblame de tu planeta natal.', `FemaleText_loc1`='당신의 고향에 대해 말씀해 주십시오.', `FemaleText_loc4`='给我讲讲你的家乡。', `FemaleText_loc5`='告訴我你的家鄉。', `FemaleText_loc7`='Háblame de tu planeta natal.' WHERE `ID`=17525;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 어떻게 의식이 실패할 수가 있지?', `MaleText_loc4`='不！仪式怎么会失败的？', `MaleText_loc5`='不!儀式怎麼會失敗?', `MaleText_loc7`='¡No! ¿Cómo ha podido fallar el ritual?' WHERE `ID`=17526;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달숲에서는 달의 축제가 한창입니다. 드루이드 사절단이 언더시티의 왕실에서 축제에 참가하고자 하는 자들을 달숲으로 보내 주신답니다.', `MaleText_loc4`='春节盛典正在月光林地举行。你可以在幽暗城的谒见厅找到一群德鲁伊，他们会把你传送到庆典现场。', `MaleText_loc5`='新年慶典正在月光林地如火如荼的進行中。你可以在幽暗城的王座廳裡找到一群德魯伊代表團，傳送人們到那裡。', `MaleText_loc7`='El Festival Lunar está en plena marcha en Claro de la Luna. Se puede encontrar una delegación de druidas en la sala del trono de Entrañas, que transporta a gente allí.', `FemaleText_loc1`='달숲에서는 달의 축제가 한창입니다. 드루이드 사절단이 언더시티의 왕실에서 축제에 참가하고자 하는 자들을 달숲으로 보내 주신답니다.', `FemaleText_loc4`='春节盛典正在月光林地举行。你可以在幽暗城的谒见厅找到一群德鲁伊，他们会把你传送到庆典现场。', `FemaleText_loc5`='新年慶典正在月光林地如火如荼的進行中。你可以在幽暗城的王座廳裡找到一群德魯伊代表團，傳送人們到那裡。', `FemaleText_loc7`='El Festival Lunar está en plena marcha en Claro de la Luna. Se puede encontrar una delegación de druidas en la sala del trono de Entrañas, que transporta a gente allí.' WHERE `ID`=17527;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달의 축제가 벌어지는 중심지가 달숲인 것 같군요. 달숲에 걸어가고 싶지 않다면 다르나서스에 세나리온 자치령에 드루이드들이 당신을 순간이동해 줄 수 있으니 그리로 가 보는 게 어떻겠습니까?', `MaleText_loc4`='春节庆祝的中心地在月光林地。要是你不想走过去的话，达纳苏斯塞纳里奥区的德鲁伊可以把你传送到那里。', `MaleText_loc5`='看來新年慶典的中心在月光林地。如果你不想走路的話，達納蘇斯，塞納里奧區的德魯伊可以將你傳送過去。', `MaleText_loc7`='Por lo visto, el corazón del Festival Lunar está en Claro de la Luna. Los druidas de Enclave Cenarion en Darnassus te pueden transportar hasta allí si no quieres caminar.', `FemaleText_loc1`='달의 축제가 벌어지는 중심지가 달숲인 것 같군요. 달숲에 걸어가고 싶지 않다면 다르나서스에 세나리온 자치령에 드루이드들이 당신을 순간이동해 줄 수 있으니 그리로 가 보는 게 어떻겠어요?', `FemaleText_loc4`='春节庆祝的中心地在月光林地。要是你不想走过去的话，达纳苏斯塞纳里奥区的德鲁伊可以把你传送到那里。', `FemaleText_loc5`='看來新年慶典的中心在月光林地。如果你不想走路的話，達納蘇斯，塞納里奧區的德魯伊可以將你傳送過去。', `FemaleText_loc7`='Por lo visto, el corazón del Festival Lunar está en Claro de la Luna. Los druidas de Enclave Cenarion en Darnassus te pueden transportar hasta allí si no quieres caminar.' WHERE `ID`=17528;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여성 블러드 엘프 사령관의 가물거리는 환영이 나타납니다. 주변 풍경으로 보아 그녀는 폭풍우 요새 안에 있는 것이 분명합니다.', `FemaleText_loc4`='一个忽隐忽显的女性血精灵指挥官影像出现了。从周围的布置来看，她肯定在风暴要塞里。', `FemaleText_loc5`='一個女性血精靈指揮官閃爍的影像出現。從環境看來，你可以辨認出她一定是在風暴要塞裡面。', `FemaleText_loc7`='Aparece una imagen parpadeante de una elfa de sangre comandante. Por los alrededores, deduces que debe de estar dentro de El Castillo de la Tempestad.' WHERE `ID`=17529;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그 블러드 엘프는 마법학자처럼 보이지는 않지만 탑의 저주를 풀 수 있는 물건을 지니고 있는 것 같습니다.', `FemaleText_loc4`='那个血精灵看上去并不像一个魔导师，但是她很可能掌握着一些关于这座塔里诅咒的关键。', `FemaleText_loc5`='血精靈不像是博學者，但或許她握有某個東西是哨塔詛咒的關鍵。', `FemaleText_loc7`='La elfa de sangre no parece ser un magister, pero quizás tenga algo que sea la clave de la maldición de la torre.' WHERE `ID`=17530;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네더가드의 감시자들이 차원문의 동요를 눈치를 채기 전까지 시간이 별로 없었고 이젠 불타는 군단이 우리의 세상에 들어와 우레와 같은 소리를 질러댔습니다!$B$B아제로스 왕국의 지원군들이 전투에 속속 참여하곤 있으나, 은빛 여명회인 우리가 처음으로 네더가드의 요청으로 이곳에 규합했습니다.$B$B우리의 임무는 얼라이언스와 호드 연합이 도착하여 도움을 줄 때까지 저 사악한 적들을 궁지에 몰아넣는 것입니다.', `MaleText_loc4`='当守望堡的卫兵发现黑暗之门出现骚动时，只剩下不多的时间了……恶魔咆哮着涌入我们的世界！$B$B尽管艾泽拉斯的援军还在路上，我们银色黎明会第一个响应守望堡的征召。$B$B我们的任务是：守住这里，直到联盟和部落的援军抵达……', `MaleText_loc5`='在守望堡的看守者感應到傳送門裡的干擾前還有一點時間...惡魔已肆虐我們的世界!$B$B雖然艾澤拉斯王國的援軍已在趕來的路上，我們銀色黎明仍是守望堡號召後第一批到達的人。$B$B我們的任務:把這些怪物擋在海灣直到聯盟和部落的援助到來...', `MaleText_loc7`='Desde que los vigilantes de Nethergarde sintieron una perturbación en el portal hasta que entraron los primeros demonios, pasó muy poco tiempo$B$BAunque los refuerzos de los reinos de Azeroth ya están de camino, nosotros, El Alba Argenta, fuimos los primeros en acudir a la llamada de Nethergarde.$B$BNuestra misión era mantener a raya a esos monstruos hasta la llegada de la Alianza y la horda...' WHERE `ID`=17531;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 근처에 있는 노예에게 자신을 돕도록 명령합니다!', `MaleText_loc4`='%s呼唤附近的奴隶来帮助他！', `MaleText_loc5`='%s呼叫附近的奴隸來幫助他!', `MaleText_loc7`='¡%s llama a un esclavo cercano para que lo ayude!' WHERE `ID`=17532;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 대단하군! 이 서보는 제 몫을 단단히 할 걸세!', `MaleText_loc4`='太棒了！这个机械臂应该会管用！', `MaleText_loc5`='太棒了!這個伺服電動機可以完成那個戲法!', `MaleText_loc7`='¡Bien! ¡Este servo debería servir!' WHERE `ID`=17533;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거면 될 것 같아. 부품을 가져다줘서 정말 고맙네!', `MaleText_loc4`='太好了。再次感谢你帮我们弄到了零件！', `MaleText_loc5`='這很適合。再次謝謝你幫我們弄來這個零件!', `MaleText_loc7`='Esto servirá. ¡Gracias de nuevo por conseguirme esta parte!' WHERE `ID`=17534;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여전히 저주가 남아 있군. 다른 방법을 찾아야 할 것 같소이다.', `MaleText_loc4`='诅咒还是原封不动。我们得寻找另一种办法。', `MaleText_loc5`='詛咒仍然完好無損。我們要想另一個辦法。', `MaleText_loc7`='La maldición permanece intacta. Tendremos que buscar otra forma.' WHERE `ID`=17535;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오, 이런! 이곳에 무슨 일이 벌어진 겁니까?', `FemaleText_loc4`='哦，亲爱的！这里发生了什么？', `FemaleText_loc5`='喔天啊!這裡發生了什麼事?', `FemaleText_loc7`='¡Vaya! ¿Qué ha sucedido aquí?' WHERE `ID`=17536;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내부에 있는 우리 요원 5명과 함께 시간의 길이 흐트러졌습니다.', `FemaleText_loc4`='时间流崩溃时，我们有五个特派员被困在里面。', `FemaleText_loc5`='時間之道崩塌的時候，還有五個我們的密探在裡頭。', `FemaleText_loc7`='El portal del tiempo se vino abajo con cinco de nuestros agentes en su interior.' WHERE `ID`=17537;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='칼도레이 용기는 어떻게 됐습니까?', `FemaleText_loc4`='卡多雷的船呢？', `FemaleText_loc5`='那卡多雷飛船怎麼樣了?', `FemaleText_loc7`='¿Y la nave kaldorei?' WHERE `ID`=17538;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='칼도레이 용기는 시간의 길이 붕괴되고 얼마 후 파괴되었습니다. 우리는 칼도레이 용기를 조사할 것입니다.', `FemaleText_loc4`='它在崩溃以后很快就撞毁了。我们正在检查它。', `FemaleText_loc5`='在崩塌後不久它就闖入了。我們現在正在檢驗它。', `FemaleText_loc7`='Se estrelló aquí poco después del derrumbamiento. Lo estamos examinando ahora.' WHERE `ID`=17539;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 고개를 끄덕입니다.', `FemaleText_loc4`='%s点了点头。', `FemaleText_loc5`='%s點點頭。', `FemaleText_loc7`='%s asiente con la cabeza.' WHERE `ID`=17540;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='멋지군요! 그게 뭐죠, 안도르무?', `FemaleText_loc4`='太迷人了。这是什么，安多尔姆？', `FemaleText_loc5`='太棒了。那是什麼，安杜姆?', `FemaleText_loc7`='Fascinante. ¿Qué es, Andormu?' WHERE `ID`=17541;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭔가 매우 성가실 것 같은 녀석들이 있습니다. 그자들이 시간의 길을 건너는 모습이 보이고 있군요.', `MaleText_loc4`='一些非常非常烦人的事情。它们越来越频繁地穿越时间流了。', `MaleText_loc5`='某個非常，非常令人困擾的東西。我們開始透過時間之道對他們有更多的了解。', `MaleText_loc7`='Algo muy, muy inquietante. Estamos empezando a ver más de estos por los portales del tiempo.' WHERE `ID`=17542;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='흠, 그들이 시간의 길을 조작하고 있는 건가요?', `FemaleText_loc4`='唔，他们正在破坏时间流吗？', `FemaleText_loc5`='嗯，他們在篡改時間之道嗎?', `FemaleText_loc7`='Mmm. ¿Están enredando con los portales del tiempo?' WHERE `ID`=17543;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노자리, 난 과거를 조작하여 자신의 위치를 향상시키려는 탐욕스러운 마법사에 대해 말하고 있는 것이 아니랍니다.', `MaleText_loc4`='诺萨莉，我不是在谈论某个想要通过微调过去来提升他现世地位的贪婪巫师。', `MaleText_loc5`='諾札瑞，我不是在說一個藉著對過去做些小更動來提升他在生命中的地位的貪婪巫師。', `MaleText_loc7`='Nozari, no estoy hablando de un zahorí avaricioso que intente mejorar su posición en la vida haciendo un pequeño ajuste en el pasado.' WHERE `ID`=17544;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 존재들은 자기들끼리 스톰윈드 복권의 당첨 번호도 알려주지 않는답니다.', `MaleText_loc4`='亲爱的，这些家伙并不是想给他们自己搞到暴风城彩票的幸运数字这么简单。', `MaleText_loc5`='這些生物不知道暴風城樂透彩的中獎號碼，親愛的。', `MaleText_loc7`='Esos seres se están dando a sí mismos los números ganadores de la lotería de Ventormenta, $gquerido:querida;.' WHERE `ID`=17545;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 당신이 그 일에 대해 말하는 게 싫어요. 전 모든 방면에서 당신과 동등합니다. 다음번에 세속의 소용돌이에 갇히면 도움을 요청해야 한다는 걸 명심하세요.', `FemaleText_loc4`='我很讨厌你用那种态度和我说话。我和你在任何方面都是平等，兄弟。记住下次当你困在时间漩涡里的时候，不要哭着求我。', `FemaleText_loc5`='我痛恨你用那種態度跟我說話。我和你在各方面都是相等的，兄弟。記住下次你被困在時間旋渦裡的時候，不要哭著求我救你。', `FemaleText_loc7`='Odio que me hables así. Soy tu igual en todos los sentidos, hermano. Recuérdalo la próxima vez que estés atrapado en medio de un vórtice temporal, pidiendo ayuda a gritos.' WHERE `ID`=17546;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용서하십시오, 노자리. 최근에 좀 예민해서 말입니다. 이 생물들은 시간의 길을 변형시키려고 하고 있습니다.', `MaleText_loc4`='对不起，诺萨莉，我最近有点急躁。这些生物正企图改变时间流。', `MaleText_loc5`='是我不好，諾札瑞。我最近有點煩躁。這些生物正嘗試改變時間之道。', `MaleText_loc7`='Perdón, Nozari. Últimamente estoy un poco nervioso. Estas criaturas quieren modificar los portales del tiempo.' WHERE `ID`=17547;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 이 일이 마지막으로 일어난 때를 기억하고 있지 않습니까? 주인님께서 관련되어 있지 않기를 바랍시다.', `MaleText_loc4`='你还记得上次发生同样的事吗？希望主人不需要被卷入此事。', `MaleText_loc5`='你還記得這最後一次發生的時候吧?讓我們祈禱主人不需要捲入其中。', `MaleText_loc7`='Recuerdas la última vez que eso sucedió, ¿verdad? Esperemos que no haga falta implicar al maestro.' WHERE `ID`=17548;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='해 볼까요?', `FemaleText_loc4`='我们应该这样希望吗？', `FemaleText_loc5`='我們要開始了嗎?', `FemaleText_loc7`='¿Debemos hacerlo?' WHERE `ID`=17549;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절대 안 됩니다. 우리 자신을 위험에 빠뜨릴 수는 없습니다. 주인님께서 사라지시면 흐름을 유지시킬 수 있는 것은 우리밖에 없습니다. 이제 다른 자들의 도움을 받을 때가 됐습니다. 아제로스의 영웅들과 모험가들 말입니다...', `MaleText_loc4`='当然不。我们不能把自己卷入危险中去。主人不在的情况下，我们都要确保时间流完整无缺。艾泽拉斯的英雄们和冒险者们估计马上就要来了……', `MaleText_loc5`='當然不。我們絕不能讓自己身處險境。主人不在，我們是這裡唯一能讓流動完整的人。其他人隨時都會到。艾澤拉斯的英雄和冒險者...', `MaleText_loc7`='Por supuesto que no. No debemos arriesgarnos. Mientras no esté aquí el maestro, somos los únicos que podemos mantener intacta la corriente. Los demás llegarán de un momento a otro. Héroes y aventureros de Azeroth...' WHERE `ID`=17550;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 고개를 끄덕입니다.', `FemaleText_loc4`='%s点了点头。', `FemaleText_loc5`='%s點點頭。', `FemaleText_loc7`='%s asiente.' WHERE `ID`=17551;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수년간, 독자적으로 설립된 감시대는 네더가드에서 어둠의 문을 지켜보았습니다. 오랫동안 굳게 닫혀 있던 통로를 통해 사악한 기운이 흘러나오는 것을 처음 발견한 것도 우리였지요.$B$B우리는 전 세계에 경고했고 영웅들이 이에 응답했습니다.$B$B이제 은빛 여명회는 이 방어선을 지키고 있습니다. 그리고 호드와 얼라이언스 사령관들이 우리를 돕기 위해 이곳으로 진군해 오고 있습니다!', `MaleText_loc4`='很多年来，守望堡一直看守着黑暗之门，时刻保持着警惕，是我首先感觉到了魔能从这个常年关闭的门里泄漏出来。$B$B我们发出了一个世界范围的警告，然后收到了答复……$B$B现在，银色黎明把守着这里，同样，部落和联盟很快也会赶来帮助我们！', `MaleText_loc5`='守望堡，幾年來都屹立注視著黑暗之門。它非常的機警，我們是第一批感應到虛空能量從那長長的封閉入口外漏的人。$B$B我們喚起了全球的警戒，而世界也給予我們回應...$b$b現在，當部落和聯盟的王國與氏族，率領了他們的軍隊趕來協助我們，銀色黎明則堅守著這條陣線!', `MaleText_loc7`='Nethergarde, ha vigilado durante años el Portal Oscuro. Nunca hemos bajado la guardia; fuimos los primeros en detectar las energías viles que se filtraban por las puertas cerradas.$B$BDimos la voz de alarma y todo el mundo respondió...$B$BAhora, El Alba Argenta protege esta línea mientras los reinos y los clanes de la Horda y la Alianza reúnen sus fuerzas para ayudarnos.' WHERE `ID`=17552;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 무역연합의 대리인으로서 언제나 우리 사업의 추이에 대해 깊은 관심이 있소이다.$B$B블러드 엘프들이 협력 관계를 성실하게 수행하지 않아 정말 유감이오.', `MaleText_loc4`='作为星界财团的代表，我一直留意生意伙伴与我们的关系。$B$B不幸的是，血精灵并没有给他们的伙伴以足够的尊重。', `MaleText_loc5`='身為聯合團的代表，我一直都很注意我在我們生意買賣中的互動分派。$B$B不幸的是血精靈不會以這樣的尊敬來對待他們的夥伴。', `MaleText_loc7`='Como representante del Consorcio, siempre tengo en cuenta la influencia que mis acciones ejercen sobre nuestros negocios.$B$BEs una pena que los elfos de sangre no tengan la delicadeza de hacer lo mismo.' WHERE `ID`=17553;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 제 동생은 무역연합에서 떠오르는 샛별입니다. 물론 동생은 아주 겸손해서 아니라고 하지만요.', `MaleText_loc4`='我身边的弟弟是星界财团的后起之秀。当然，他太谦虚了，甚至要拒绝这种光荣。', `MaleText_loc5`='我弟弟在這裡是聯合團中的新興之星。當然，他太謙虛所以不會承認的。', `MaleText_loc7`='Mi hermano menor es la nueva promesa del Consorcio. Por supuesto, es demasiado modesto para reconocerlo.' WHERE `ID`=17554;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 ''동생''이라는 말만 했다고요? 우리가 쌍둥이라는 사실을 빼놓았군요. 고작 몇 분 먼저 태어났을 뿐이면서...$B$B''떠오르는 샛별''이라는 말은 믿지 마십시오. 저는 절대 형보다 뛰어난 상인이 될 수 없으니까요.', `MaleText_loc4`='当他称我为“弟弟”的时候，他忘记提起我们是双胞胎了。他只不过比我早出生那么几分钟而已。$B$B不要让什么“后起之秀”蒙敝你。我永远无法成为他那样的商人。', `MaleText_loc5`='當他說''弟弟''的時候，他忘記說我們是雙胞胎。他真的只有大我幾分鐘而已。$B$B不要被他那一點''小聰明''給騙了。我永遠不可能成為像他一樣重要的商人。', `MaleText_loc7`='Cuando dice "hermano menor", olvida mencionar que somos gemelos. En realidad solo es mayor por un par de minutos.$B$BNo dejéis que su historia de la "nueva promesa" os engañe. Nunca seré un mercader de la misma magnitud que él.' WHERE `ID`=17555;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 견본을 조사합니다.', `FemaleText_loc4`='%s在检查样品。', `FemaleText_loc5`='%s檢驗樣品。', `FemaleText_loc7`='%s examina el ejemplar.' WHERE `ID`=17556;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 견본의 실체가 사라지고 있습니다. 뭔가 혹은 누군가가 시간의 길을 변형하고 있습니다.', `FemaleText_loc4`='这个样本正在逐渐消失。有什么东西或者什么人正在改变着时间流。', `FemaleText_loc5`='樣品正在逐漸消失。有東西或人正在改變時間之道。', `FemaleText_loc7`='Este ejemplar se está desvaneciendo. Algo o alguien está alterando el portal del tiempo.' WHERE `ID`=17557;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='읽을 수가 없군요... 뭔가가 방해하고 있습니다...', `FemaleText_loc4`='我不能得到读数……有东西在妨碍我……', `FemaleText_loc5`='我看不到讀數...有東西在干擾...', `FemaleText_loc7`='No consigo una lectura... Algo está interfiriendo...' WHERE `ID`=17558;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='시간의 중재자들이 인지하고 있나요?', `FemaleText_loc4`='流沙之鳞已经知道了吗？', `FemaleText_loc5`='流沙之鱗知道了嗎?', `FemaleText_loc7`='¿Se ha puesto al corriente a la Escama de Arenas?' WHERE `ID`=17559;
