UPDATE `locales_broadcast_text` SET `MaleText_loc1`='치즈라고요? 아마도... 오래 숙성된 치즈겠죠?', `MaleText_loc4`='奶酪，嗯？那会不会是一块……陈年的奶酪了？', `MaleText_loc5`='起司，是嗎?或許是...陳年的起司?', `MaleText_loc7`='¿Queso, eh? ¿Es quizás... queso añejo?', `FemaleText_loc1`='치즈라고요? 아마도... 오래 숙성된 치즈겠죠?', `FemaleText_loc4`='奶酪，嗯？那会不会是一块……陈年的奶酪了？', `FemaleText_loc5`='起司，是嗎?或許是...陳年的起司?', `FemaleText_loc7`='¿Queso, eh? ¿Es quizás... queso añejo?' WHERE `ID`=17566;
