UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 내가 기억할 수 있는 그 순간부터 여기 갇혀 있었네.$B$B전생에 난 대장장이였지. 자네가 가진 물건을 고쳐줄 수도 있을 거야.', `MaleText_loc4`='嗯，从我能记事开始，我就在这里了。$B$B在我以前的生活中，我是个铁匠。也许我可以帮你修点什么？', `MaleText_loc5`='是的，我已經被困在這裡不知道有多久了。$B$B在我的前世裡，我是個護甲師。或許我能幫你修理東西?', `MaleText_loc7`='Sí, he estado atrapado aquí desde que puedo recordar.$B$BEn mi vida anterior, era armero. ¿Quizás pueda repararte algo?' WHERE `ID`=17579;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러면 수리를 좀 부탁합니다.', `MaleText_loc4`='我需要修理。', `MaleText_loc5`='我需要修理。', `MaleText_loc7`='Necesito reparar.', `FemaleText_loc1`='그러면 수리 좀 부탁할게요.', `FemaleText_loc4`='我需要修理。', `FemaleText_loc5`='我需要修理。', `FemaleText_loc7`='Necesito reparar.' WHERE `ID`=17580;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마침내 말벗이 나타났군! 제가 시 한 수 읊어드릴까요?', `MaleText_loc4`='终于有人和我说话了！想听几首我作的诗吗？', `MaleText_loc5`='終於，有人來和我說話了!想聽聽我的一些押韻詩嗎?', `MaleText_loc7`='¡Al fin, alguien ha bajado a hablar conmigo! ¿Quieres oír alguno de mis poemas?' WHERE `ID`=17581;
