UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발걸음도 가볍게, 길을 걸어가면서! 나무를 보네, 나뭇잎이 떨어지네!', `MaleText_loc4`='沿街！行走！绿叶纵有千片哟，也要化为泥土。', `MaleText_loc5`='走上街去!看著我的腳!看著葉子，從樹上飄落!', `MaleText_loc7`='¡Bajando la calle! ¡Mirando el valle! ¡Observando las hojas caer en la calle!' WHERE `ID`=17584;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 도시는 언제쯤 완성될까요? 다 끝났다고 생각될 때마다 하루만 더 일하라는 지시를 받지요...', `MaleText_loc4`='什么时候这个城市会完工？三年之后又三年，三年之后又三年……', `MaleText_loc5`='這座城市什麼時候才會完工?每次我覺得完成時，他們就會告訴我還要再工作一天...', `MaleText_loc7`='¿Cuándo se acabará esta ciudad? Cada vez que creo que he terminado, me dicen que hay un día más de trabajo...' WHERE `ID`=17585;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 도시에서 영원히 일을 할 것 같은 느낌이 듭니다!', `MaleText_loc4`='我感觉我要在这里当一辈子工人了！', `MaleText_loc5`='我覺得我好像在這個城市工作了一輩子一樣!', `MaleText_loc7`='¡Me siento como si trabajara en esta ciudad desde siempre!' WHERE `ID`=17586;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 멋진 도시가 완성되는 꿈을 종종 꾸곤 합니다. 이 일이 제 꿈까지 악몽으로 만들었어요!', `MaleText_loc4`='有时候我曾梦想这座宏伟的城市竣工后的模样。唉，但是这些工作把我的梦变成了噩梦！', `MaleText_loc5`='有時候我夢想著這個驚人的城市變的完整。唉，所有這些工作已讓我的夢想變成夢魘!', `MaleText_loc7`='A veces sueño que esta increíble ciudad está completa. ¡Desgraciadamente, todo este trabajo ha convertido mis sueños en pesadillas!' WHERE `ID`=17587;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 앞으로 몇 주만 더 고생하면 됩니다. 제가 들은 바로는 그렇습니다만...', `MaleText_loc4`='我们只需要再干几个星期就行了。至少他们是这么说的……', `MaleText_loc5`='我們只需要為這艱難局面再努力幾個禮拜就好了。至少他們是這樣告訴我們的...', `MaleText_loc7`='Solo tenemos que trabajar con esta intensidad unas cuantas semanas más. Al menos eso es lo que nos dicen...' WHERE `ID`=17588;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 에테리얼 순간이동 장치는 밝은 색깔의 단추와 스위치로 덮여 있습니다. 하지만, 위장이 되어 있는 것 같습니다.', `MaleText_loc4`='这个虚灵传送台上有好几个刷着亮漆的按钮和开关，但看上去已经废弃了。', `MaleText_loc5`='這個以太傳送器上充滿了明亮顏色的按鈕和開關，但看起來已經不復使用了。', `MaleText_loc7`='Esta plataforma de teletransporte etérea está cubierta de botones e interruptores de colores vivos, pero parece haber caído en desuso.' WHERE `ID`=17590;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='없는 게 없습니다! 큰놈, 작은놈, 원하는 건 뭐든지 이 하진이 책임지고 구해드리겠습니다.$B$B울트리스 마나괴철로로 가시는 여행자 여러분, 목숨이 아깝다면 짐을 단단히 꾸려가십시오. 물건을 살 수 있는 곳은 여기가 마지막입니다.', `MaleText_loc4`='瞧一瞧看一看啊，我的朋友！无论大小，无论你需要什么，哈斯辛这里应有尽有。$B$B如果你珍惜你的生命，没有补给就不要靠近法力熔炉：乌提斯。哈斯辛是你最后的机会。', `MaleText_loc5`='什麼都賣，我的朋友!大或小，你要什麼，海辛就給你什麼。$B$B如果你愛惜你的生命，就一定要補足物資再前往法力熔爐奧崔斯。海辛是你最後的機會。', `MaleText_loc7`='¡Todo en venta, $gamigo:amiga;! Grande y pequeño, sea lo que sea lo que necesitas, Hazzin te lo proporcionará.$B$BSi valoras tu vida, no te acerques a la forja de maná Ultris sin reabastecerte. Hazzin es la última oportunidad que tienes.' WHERE `ID`=17591;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하진, 물건을 보여주십시오.', `MaleText_loc4`='商人哈斯辛，你在卖些什么？', `MaleText_loc5`='商人海辛，你有什麼東西要賣?', `MaleText_loc7`='Tratante Hazzin, ¿qué me ofreces?', `FemaleText_loc1`='하진, 물건을 보여주세요.', `FemaleText_loc4`='商人哈斯辛，你在卖些什么？', `FemaleText_loc5`='商人海辛，你有什麼東西要賣?', `FemaleText_loc7`='Tratante Hazzin, ¿qué me ofreces?' WHERE `ID`=17592;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 검은늑대들을 부릅니다.', `MaleText_loc4`='%s召唤出他的座狼。', `MaleText_loc5`='%s召喚他的座狼。', `MaleText_loc7`='%s llama a sus huargos.' WHERE `ID`=17593;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 우리가 연합왕자 하라매드가 노리는 물건을 되찾을 수 있다고 자신합니다.', `MaleText_loc4`='我们会找到节点亲王哈拉迈德想要的东西，对此我很有信心。', `MaleText_loc5`='我有十足的把握我們會找到奈薩斯王子哈拉瑪德想要的東西。', `MaleText_loc7`='Confío en que recuperaremos lo que desea el príncipe-nexo Haramad.' WHERE `ID`=17594;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 깜짝 놀라면서 일어납니다.', `MaleText_loc4`='%s醒了过来，一脸震惊。', `MaleText_loc5`='%s醒來，受到驚嚇。', `MaleText_loc7`='%s se despierta con miedo.' WHERE `ID`=17595;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그게... 모두 꿈이었다니? 하늘안개 섬, 핏빛안개 섬, 장가르 습지대, 어둠달 골짜기... 그리고 줄아만까지도... 제인! 어디 있니?!', `MaleText_loc4`='这……这是梦吗？秘蓝岛，秘血岛，赞加沼泽，影月……甚至是祖阿曼……杰恩！杰恩你在哪里！', `MaleText_loc5`='這...這一切全是夢嗎?藍謎島，血謎島，贊格沼澤，影月谷...就連祖阿曼...珍恩!珍恩你在哪裡!', `MaleText_loc7`='¿Fue... fue todo un sueño? Bruma Azur, Bruma de Sangre, la marisma de Zangar, Sombraluna... hasta Zul''Aman... ¡Jane! ¿Jane, dónde estás?' WHERE `ID`=17596;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 멋지군요. 모든 게 한낱 꿈이었습니다...', `MaleText_loc4`='啊，太好了。那一切只是场梦……', `MaleText_loc5`='啊，太好了。這一切全是夢...', `MaleText_loc7`='Ah, menos mal. Era solo un sueño.' WHERE `ID`=17597;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저 여기 있잖아요, 아빠. 오늘 하루 종일 주무셨어요. 굉장히 피곤하셨나 봐요!', `FemaleText_loc4`='我在这里，爸爸。你睡了一整天了。你一定是太累了！', `FemaleText_loc5`='我就在這裡，爸爸。你已經睡了一整天了。你一定很累!', `FemaleText_loc7`='Aquí estoy, papito. Llevas durmiendo todo el día. ¡Debías de estar muy cansado!' WHERE `ID`=17598;
