UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이방인들이여, 당신들에게 너무나도 많은 빚을 졌소.', `MaleText_loc4`='我欠你们的情，陌生人。', `MaleText_loc5`='我真的欠你們一份人情，陌生人。', `MaleText_loc7`='Estoy en deuda con ustedes forasteros.' WHERE `ID`=17607;
