UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좀 더 조용한 곳에서 토론을 진행합시다. 절 따라오십시오, $n...', `MaleText_loc4`='让我们找个更隐秘点的地方继续我们的谈话……跟我走，$n。', `MaleText_loc5`='讓我們到一個比較...私密的地方談話。跟我來，$n。', `MaleText_loc7`='Sigamos con esta charla en un... lugar más discreto. Sígueme, $n.' WHERE `ID`=17615;
