UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 별명이 칼주먹인데는 다 이유가 있다. 너희도 곧 알게 될 것이다.', `MaleText_loc4`='我这“刃拳”的名号可不是白来的！', `MaleText_loc5`='我被叫做刃拳是有原因的。你馬上就會知道了。', `MaleText_loc7`='Les enseñaré por qué me llaman Garrafilada.' WHERE `ID`=17617;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 정말로 네놈과 다시 거래를 할 것이라 생각하지는 않았겠지? 손해를 줄이는 것이 수익을 남기는 최선의 방법일 때도 있는 법이다!', `MaleText_loc4`='你真以为我会再和你做生意？有时候弥补损失最好的办法就是知道什么会造成损失。', `MaleText_loc5`='你不是真的以為我會再和你做生意吧?有時候，要回收利潤的方法就是知道何時該切斷你的盈虧。', `MaleText_loc7`='No pensaste en serio que volvería a hacer negocios contigo, ¿verdad? A veces, la mejor forma de volver a tener rentabilidad es saber cuándo recortar tus pérdidas.' WHERE `ID`=17618;
