UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1을;를; 죽여라!', `MaleText_loc4`='杀了$n！', `MaleText_loc5`='殺了$n!', `MaleText_loc7`='¡Mata a $n!', `FemaleText_loc1`='$n|1을;를; 죽여라!', `FemaleText_loc4`='杀了$n！', `FemaleText_loc5`='殺了$n!', `FemaleText_loc7`='¡Mata a $n!' WHERE `ID`=17624;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런 황천의 용은 처음 봤습니다. 선조의 기질을 그대로 물려받은 것처럼 보이지만 전혀 다른 존재가 되었으니까요.', `FemaleText_loc4`='我从来没见过像虚空龙那样的生物。他们似乎继承了祖先的性格，但他们已经变得完全不同了。', `FemaleText_loc5`='我沒看過像這些虛空龍族的東西。他們似乎繼承了他們父親的性情，但又變成某種完全不同的生物。', `FemaleText_loc7`='Nunca había visto nada igual a esos dracos abisales. Parece que han heredado el temperamento de su señor, pero, al mismo tiempo, son algo totalmente diferente.' WHERE `ID`=17625;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 땅은 신선한 피에 물들어 아직도 뜨겁다네. 아, 악마들이 어둠의 문을 부수고 아제로스의 영웅들과 싸웠을 때 내가 이곳에 있어 내 눈으로 볼 수 있었다면! 그 얼마나 장엄한 전투였더란 말인가!$B$B이제, 전투는 반대편에서 더 사납게 몰아친다네!', `MaleText_loc4`='这里的大地依然留有鲜血的余温。啊，恶魔飞奔着穿过黑暗之门，与艾泽拉斯的英雄们杀得昏天暗地，我真想亲眼看看这一幕。那会是多么宏大的一场战斗啊！$B$B但是现在，更多更猛烈的战斗正在另一端进行着！', `MaleText_loc5`='這裡的地上還因為剛灑下的鮮血而溫熱著。啊，我願意親眼見證惡魔扯破那個傳送門和艾澤拉斯的英雄們起衝突!多棒的一場戰役啊!$B$B但是現在，更激烈的打鬥就在另一邊進行著!', `MaleText_loc7`='El suelo de este lugar todavía está caliente de sangre recién derramada. ¡Ah, habría dado mi propio ojo para estar aquí cuando los demonios entraron por ese portal y se enfrentaron a los héroes de Azeroth! ¡Menuda batalla!$B$B¡Pero ahora, al otro lado hay una batalla aún más feroz!' WHERE `ID`=17626;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 나간다는 것은 겁도 없이 아라 마나괴철로 근처에 간다는 뜻이겠군요.$B$B죽기 전에 먼저 사거나 팔 물건은 없습니까?', `MaleText_loc4`='如果你是沿着这条路出去的话，那你肯定够胆去法力熔炉：艾拉附近冒险了。$B$B在你出发前买点东西吧？', `MaleText_loc5`='如果你大老遠跑來這裡，那麼你一定敢冒險到法力熔爐艾拉附近。$B$B在你前往之前想不想買賣點什麼呢?', `MaleText_loc7`='Si has venido hasta aquí, debe de ser porque osas aventurarte cerca de la forja de maná Ara.$B$B¿Quieres comprar o vender antes de seguir hasta allí?' WHERE `ID`=17627;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 물건을 팔고 있습니까, 툴루만?', `MaleText_loc4`='你都卖些什么，图鲁曼？', `MaleText_loc5`='你要賣什麼，吐魯曼?', `MaleText_loc7`='¿Qué vendes, Tuluman?', `FemaleText_loc1`='무슨 물건을 팔고 있습니까, 툴루만?', `FemaleText_loc4`='你都卖些什么，图鲁曼？', `FemaleText_loc5`='你要賣什麼，吐魯曼?', `FemaleText_loc7`='¿Qué vendes, Tuluman?' WHERE `ID`=17628;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 이 세계의 생명체를 세 가지로 분류합니다. 경쟁자, 고객, 그리고 일꾼... 경쟁자는 무자비하게 제거하고, 고객의 욕구를 만족시키고, 일꾼들은 엄격히 감독해야죠.$B$B개인적으로 계약을 맺고 일하는 자들은 믿을 게 못됩니다. 일꾼들보다 많은 보수에 고객처럼 대접받기를 원하더군요. 그런 자들은 절대 믿지 마십시오.', `MaleText_loc4`='在这个世界上只有3种人：竞争者，顾客和雇员。竞争者会被无情地碾碎，顾客需要被满足，而雇员则应该被严格地管理。$B$B不受约束的承包者是一个神话。他们希望得到比雇员更多的回报，但是要像顾客一样对待他们。永远都不要相信自称是承包者的人。', `MaleText_loc5`='這世界上只有3種人:競爭者，消費者，和受雇者。競爭者會被殘忍地粉碎，消費者沉迷於欲望，而受雇者則被嚴格地監督。$B$B獨立的承包人是個神話。他們想獲得比受雇者更好的待遇，但又想被當成消費者對待。永遠不要相信以那個頭銜自稱的人。', `MaleText_loc7`='Solo hay tres tipos de personas en este mundo: competidores, clientes y empleados. Los competidores se deben aplastar implacablemente, a los clientes se les debe satisfacer, y a los empleados, supervisar estrictamente.$B$BLos contratistas independientes son un mito. Quieren que se les pague mejor que a los empleados, pero que se les trate como a clientes. Nunca confíes en nadie que use ese título para sí.' WHERE `ID`=17629;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직... 끝난 건 아니다.', `MaleText_loc4`='你们……等着瞧。', `MaleText_loc5`='它...還沒結束。', `MaleText_loc7`='¡No se ha acabado!' WHERE `ID`=17630;
