UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아코르 쉬 카이! 내 강아지들아, 배불리 먹어라.', `MaleText_loc4`='Achor she-ki！吞噬他们的躯体！', `MaleText_loc5`='我召喚你!盡情吃吧，我的寵物!吃你的食物!', `MaleText_loc7`='¡Achor she-ki! ¡Disfruta, mascota mía! ¡Come hasta hartarte!' WHERE `ID`=17637;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바람의 무역상 마리드와 접촉을 시도합니다.', `MaleText_loc4`='尝试联系星界商人玛里德。', `MaleText_loc5`='嘗試聯繫風之貿易者瑪利德。', `MaleText_loc7`='Intenta ponerte en contacto con el comerciante de viento Marid.', `FemaleText_loc1`='바람의 무역상 마리드와 접촉을 시도합니다.', `FemaleText_loc4`='尝试联系星界商人玛里德。', `FemaleText_loc5`='嘗試聯繫風之貿易者瑪利德。', `FemaleText_loc7`='Intenta ponerte en contacto con el comerciante de viento Marid.' WHERE `ID`=17638;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 테로카르 숲을 한참 동안 바라봅니다.', `MaleText_loc4`='%s远眺泰罗卡森林。', `MaleText_loc5`='%s盯著泰洛卡森林看了好一陣子。', `MaleText_loc7`='%s mira largamente el bosque de Terokkar.' WHERE `ID`=17639;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 자네는 우리의 명예를 어느 정도 되찾아 주었네. 정말 큰일을 했군그래. 적이 쳐들어와서 곤란한 상황에 빠지면 다시 우리를 찾아 주게나.', `MaleText_loc4`='$n，你帮了我们很大的忙，挽回了我们的荣誉。当我们的敌人逼近时，再来找我们吧。', `MaleText_loc5`='$n，你為我們付出了很大的努力，為我們修復榮耀。等我們的敵人逼近，在你遇到難關時再來找我們。', `MaleText_loc7`='$n, nos has proporcionado un gran servicio, devolviéndonos algo de nuestro honor. Vuelve a buscarnos en tu momento más oscuro, cuando nuestros enemigos estén cerca.' WHERE `ID`=17640;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기는 성스러운 곳이다.', `MaleText_loc4`='这里是圣地！', `MaleText_loc5`='這裡是神聖之地!', `MaleText_loc7`='¡Esto es suelo sagrado!', `FemaleText_loc1`='여기는 성스러운 곳이다.', `FemaleText_loc4`='这里是圣地！', `FemaleText_loc5`='這裡是神聖之地!', `FemaleText_loc7`='¡Esto es suelo sagrado!' WHERE `ID`=17641;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 이곳에 오다니!', `MaleText_loc4`='你们竟敢闯入这里？！', `MaleText_loc5`='你竟敢來這裡?', `MaleText_loc7`='¡¿Cómo osan venir aquí?!', `FemaleText_loc1`='감히 이곳에 오다니!', `FemaleText_loc4`='你们竟敢闯入这里？！', `FemaleText_loc5`='你竟敢來這裡?', `FemaleText_loc7`='¡¿Cómo osan venir aquí?!' WHERE `ID`=17642;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='외부인은 출입 금지다!', `MaleText_loc4`='不许进来！', `MaleText_loc5`='擅闖禁地者死!', `MaleText_loc7`='¡No se permiten intrusos aquí!', `FemaleText_loc1`='외부인은 출입 금지다!', `FemaleText_loc4`='不许进来！', `FemaleText_loc5`='擅闖禁地者死!', `FemaleText_loc7`='¡No se permiten intrusos aquí!' WHERE `ID`=17643;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희의 마음을 어지럽히리라.', `MaleText_loc4`='你的心智将被蒙蔽！', `MaleText_loc5`='讓你的心被蒙蔽。', `MaleText_loc7`='Que se nuble su mente.' WHERE `ID`=17644;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 영혼의 어둠을 응시하라.', `MaleText_loc4`='直视你灵魂深处的黑暗吧。', `MaleText_loc5`='看透你靈魂的黑暗面。', `MaleText_loc7`='Miren fijamente la oscuridad de su alma.' WHERE `ID`=17645;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기가 내가 속한 곳이다.', `MaleText_loc4`='这里……是我的归宿。', `MaleText_loc5`='這是...屬於我的地方。', `MaleText_loc7`='Este es... mi lugar.' WHERE `ID`=17646;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너의 생명을 내놓아야 할 것이다.', `MaleText_loc4`='你会付出生命的代价！', `MaleText_loc5`='你會用你的生命付出代價!', `MaleText_loc7`='¡Lo pagarán con sus vidas!' WHERE `ID`=17647;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 물러설 곳은 없다.', `MaleText_loc4`='你无路可逃了！', `MaleText_loc5`='現在無法回頭了!', `MaleText_loc7`='¡Ya no hay vuelta atrás!' WHERE `ID`=17648;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='참회의 기도나 올려라.', `MaleText_loc4`='忏悔吧！', `MaleText_loc5`='懺悔吧你!', `MaleText_loc7`='¡Cumplan su penitencia!' WHERE `ID`=17649;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기가 너의 무덤이 될 것이다!', `MaleText_loc4`='这里就是你的坟墓！', `MaleText_loc5`='這些牆將會是你的葬身之地!', `MaleText_loc7`='¡Estos muros serán su tumba!' WHERE `ID`=17650;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 넌 이곳을 떠돌게 될 것이다. 영원히!', `MaleText_loc4`='永远留在这里吧。', `MaleText_loc5`='現在你會留在這裡了...永遠的。', `MaleText_loc7`='Ahora se quedarán... toda la eternidad.' WHERE `ID`=17651;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 대량 치유를 시전합니다!', `MaleText_loc4`='%s开始施放强大的治疗法术！', `MaleText_loc5`='%s開始大量的治療!', `MaleText_loc7`='¡%s comienza una curación masiva!' WHERE `ID`=17652;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 건방지고 거만한 놈이 있나! 내 집에서 날 이길 생각을 하다니!', `MaleText_loc4`='多傲慢啊！多自大啊！你觉得你可以在我的门口打败我吗？', `MaleText_loc5`='真是無恥!真是自大!要我相信你會在我的門階前擊敗我!', `MaleText_loc7`='¡Qué insolencia! ¡Qué arrogancia! ¡Creer que podrías derrotarme en mi propio umbral!' WHERE `ID`=17653;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 재미없군.', `MaleText_loc4`='这练习让我觉得厌烦。', `MaleText_loc5`='這個練習很無聊。', `MaleText_loc7`='Este ejercicio me aburre.' WHERE `ID`=17654;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 시험해 보고 싶나? 그렇지만 네게는 그럴 능력이 없다.', `MaleText_loc4`='想要考验我？你还不够资格。', `MaleText_loc5`='你們要考驗我嗎?你根本無法勝任這個任務。', `MaleText_loc7`='¿Quién quiere ponerme a prueba? No creo que tú des la talla.' WHERE `ID`=17655;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하십니까, $c|1이여;여;. 시간의 동굴을 안내해 드리도록 하겠습니다. 저를 따라와 주시겠습니까?', `FemaleText_loc4`='你好，$n。我会带你游览时光之穴。请跟紧我。', `FemaleText_loc5`='你好，$n。我會指引你通過洞穴。請嘗試並努力。', `FemaleText_loc7`='Saludos, $n. Te guiaré por la caverna. Procura seguir mi ritmo y no perderte.' WHERE `ID`=17656;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='시간의 동굴이 필멸의 존재에게 항상 열려 있는지 아닌지는 우리도 모릅니다. 사실 영생을 누리는 시간의 지배자께서 자신의 판단에 따라 우리의 시간의 길을 변화시키시기에 뭐라 말할 수가 없군요. 당신이 지금 보고 있는 것은 내일이 되면 존재하지 않을지도 모른답니다. 당신이 어제로 되돌아가 정신을 차리게 되어 이곳에 대한 기억이 전혀 남아 있지 않을 수도 있습니다.', `FemaleText_loc4`='我们不知道时光之穴是否一直都允许凡人进入。确切的说，我们不可能知道这一点，因为时光之王在永远地运动着，用他认为恰当的方式来改变我们的时间流。也许你现在所看到的东西，明天就不存在了。你也可能会在昨天醒来，然后对这个地方没有丝毫的印象。', `FemaleText_loc5`='我們不知道凡人是否永遠都可以進入時光之穴。真的，我們很難知道永恆之王是否無休止的運作，隨他意思改變我們的時間之道。你現在所看到的一切明天很可能就不復存在了。你可能在昨天醒來然後對這個地方沒有任何記憶。', `FemaleText_loc7`='No sabemos si las Cavernas del Tiempo siempre han sido accesibles a los mortales. Sinceramente, es imposible de decir, ya que el Atemporal está en perpetuo movimiento, cambiando nuestros portales del tiempo como cree conveniente. Lo que ves ahora puede no existir mañana. Puedes despertarte mañana y no tener recuerdo de este lugar.' WHERE `ID`=17657;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이상한 일이라는 거 저도 압니다... 필멸의 존재들은 대부분 이곳에서 본 것을 이해하지 못한답니다. 그들의 지각 능력으로는 여기서 보게 되는 것을 완전히 받아들일 수 없으니까요.', `FemaleText_loc4`='这很奇怪，我知道……大部分凡人无法真正理解他们在这里看到的东西，他们所看到往往无法和他们的理解联系起来。', `FemaleText_loc5`='這很奇怪，我知道...大部分的凡人不能真正理解他們在這裡看到的一切，因為通常他們所見的與他們在真實世界的認知是迥異的。', `FemaleText_loc7`='Es extraño, lo sé... La mayoría de los mortales no pueden llegar a comprender lo que ven aquí, ya que, a menudo, lo que ven no está anclado en su propia percepción de la realidad.' WHERE `ID`=17658;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='시간의 관리인으로서 우리는 노즈도르무님의 영역을 감시하고 돌보는 일을 맡고 있습니다. 현재 주인님께서는 자리에 안 계십니다. 다시 말해 시간을 바꾸려고 시도하는 자들이 여럿 있다는 뜻이지요. 주인님께서는 필멸의 존재들 사이에 벌어지는 일에는 절대 관여하지 않으시지만 다른 이들에 의해 시간이 변경되면 시간을 바로잡으신답니다. 주인님께서는 이 문제에 대해서는 매우 보수적이랍니다.', `FemaleText_loc4`='作为时间的管理者，我们看管和照顾着诺兹多姆的领地。主人目前不在这里，这就意味着他正在尝试着剧烈地改变时间进程。主人向来不理会凡人的闲事，除了纠正其他人对时间的改变。他是非常反对这种行为的。', `FemaleText_loc5`='身為時間的守衛，我們看管並照料諾茲多姆的領土。主人現在不在，這表示正有人企圖戲劇性地改變時間。主人從不干預凡人的事務而是改正他人對時間做的改變。他在這件事上是很保守的。', `FemaleText_loc7`='Como guardianes del tiempo, vigilamos y cuidamos el reino de Nozdormu. El maestro está ausente por el momento, lo que significa que se está intentando alterar el tiempo drásticamente. El maestro nunca se entromete en los asuntos de los mortales, sino que corrige las alteraciones hechas al tiempo por otros. En este aspecto, es reaccionario.' WHERE `ID`=17659;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='일반적인 시간 관리는 시간의 수호자들만 있으면 충분합니다. 대부분의 평범한 사건은 우리 힘으로 처리할 수가 있지요. 제 말은 사소한 문제를 뜻하는 거랍니다. 예를 들어 도적 같은 마법사가 현재의 지위나 부의 추구를 위해 과거의 무언가를 바꾸는 행위 같은 것 말이지요.', `FemaleText_loc4`='对于普通的时间维护工作，时光守护者的力量是足够的。我们可以处理大部分普通的干扰。举个小例子来说，比如某些无赖法师们试图改变过去的一些东西来提升他们现在的身份和财富之类的事情，不在话下。', `FemaleText_loc5`='就普通的時間維護來說，時光守望者已經是很稱職的監督了。我們可以解決大部分普通的混亂。我是說些小事，像是某些法師惡棍改變過去的某些事來提升他們現在的地位或財富。', `FemaleText_loc7`='Para un mantenimiento normal del tiempo, los Vigilantes del Tiempo son custodios suficientes. Podemos ocuparnos de las alteraciones más ordinarias. Hablo de cosas pequeñas, como magos pícaros que cambian algo del pasado para elevar su estatus o su riqueza en el presente.' WHERE `ID`=17660;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리는 앞에 보이는 굴을 시간의 길이라고 부른답니다. 시간의 길의 수는 무한하지요. 주인님께서는 현재 당신의 현실에서 존재하고 있는 시간의 길을 ''문제가 있는 지역''이라고 간주하셨습니다. 이런 지역은 주제는 전혀 다를지 몰라도 그 원인은 언제나 하나랍니다. 다시 말해 동일한 세속적 혼란으로 인해 존재하게 되었다는 뜻입니다. 시간의 길 안을 여행할 땐 이 사실을 명심하십시오...', `FemaleText_loc4`='你看到的这些隧道被称为时间流。它们的数量是无穷的。当前在你们的现实中存在的那个就是主人所认为的“麻烦点”。这些麻烦点也许有着完全不同的内容，但是它们通常都有着相同的原因。它们的存在是同样的时间干扰所产生的结果，当你进入其中的一个麻烦点去冒险时，要牢记这一点……', `FemaleText_loc5`='你看到的這些隧道叫時間之道。它們的數量是無限的。那些現在存在於你的真實生活中的就是主人眼裡的『麻煩之地』。這些麻煩之地的主題可能會完全不同，但它們永遠都是同一個原因導致。那就是，它們的存在是同樣的時間干擾的產物。記得如果你進入了一個隧道...', `FemaleText_loc7`='"Estos túneles que ves son portales del tiempo. Son infinitos. Los que hay en tu plano de la realidad son los que el maestro llama "fuentes de problemas". Esas fuentes de problemas pueden mostrar aspectos totalmente diferentes, pero tienen una causa común. Su existencia es el fruto de una única perturbación temporal. Recuérdalo siempre que entres en alguno..."' WHERE `ID`=17661;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='현재 시간의 길은 가장 안정적인 것에서 가장 위험한 것의 순서로 분류되어 있습니다. 시간의 길이 위험도에 따라 분류되었다는 사실을 꼭 기억하시기 바랍니다. 시간의 길 중 한 곳이 붕괴되면 당신의 세계가 종말을 맞이하게 되니까요. 우리는 이곳에 오는 영웅과 모험가들이 어떤 시간의 길이 자신의 능력에 맞는지 쉽게 인지할 수 있도록 하기 위해 그런 방식으로 시간의 길을 분류한답니다.', `FemaleText_loc4`='时间流目前是按照“小灾难”至“大灾难”的顺序排列着的。注意它们全部都是“灾难”，这意味着任何一个时间流的毁灭都会终结你们的世界，没有区别。我们把它们这样分类，只是为了让那些被派到这里来的英雄们和冒险者们知道自己的能力适合处理哪个时间流中的事务。', `FemaleText_loc5`='時間之道現在從最不悲慘到最悲慘的順序排列。請注意它們全都分類為悲慘，代表任何一個時間之道崩塌的話都會毀滅你的世界。我們只這樣分類它們，如此一來被派到這裡的英雄和冒險者才知道哪一條時間之道最適合他們的能力。', `FemaleText_loc7`='Actualmente, los portales del tiempo se ordenan de menos catastrófico a más catastrófico. Ten en cuenta que todos se clasifican como catastróficos, lo que significa que, el hecho de que uno solo de esos portales del tiempo se derrumbara, significaría que tu mundo terminaría. Solo los clasificamos así para que los héroes y aventureros que envían aquí sepan qué portal del tiempo se adecua mejor a sus habilidades.' WHERE `ID`=17662;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 시간의 길은 정말 난장판입니다! 현재 우리 요원을 안에 투입해서 질서를 회복하려고 하는 중이랍니다. 얼마 되진 않지만 제가 가진 정보에 따르면 스랄의 자유가 위기에 처해 있습니다. 무한의 용군단이라는 사악한 단체가 스랄의 탈출을 막으려 하고 있습니다. 외부의 도움이 없으면 모든 게 허사가 되고 말 것입니다.', `FemaleText_loc4`='这个时间流目前正处于极度的混乱中！我们派了一些人在里面努力恢复秩序。我所能告诉你的一点信息就是，萨尔的自由正在危难中。一个被称为永恒之龙的邪恶组织正在尝试阻止他的逃脱。我担心如果没有来自外界的帮助，一切都将无可挽回。', `FemaleText_loc5`='這條時間之道已經陷入一片混亂!我們有密探現在正在裡面嘗試讓它恢復秩序。就我微少的資訊指出索爾的自由有危險了。一個叫做恆龍軍團的有害組織正試著阻止他逃跑。我擔心沒有外界的協助，我們會失去一切。', `FemaleText_loc7`='¡Este portal del tiempo está patas arriba! Ahora mismo tenemos a agentes en su interior que intentan devolverle el orden. La poca información que tenemos indica que la libertad de Thrall está en peligro. Una organización malévola conocida como el Vuelo Infinito está intentando evitar su huida. Me temo que, sin ayuda externa, todo estará perdido.' WHERE `ID`=17663;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리는 이 시간의 길에 대해 아는 것이 거의 없습니다. 사트가 파견되어 현재 저 시간의 길 내에 있지요. 그의 통신문을 통해 얻은 정보를 보면 무한의 용군단이 또다시 시간을 변형하려 하고 있다고 합니다. 어둠의 문을 연 것이 파괴를 목적으로 한 것일까요? 그렇지 않기를 기도합시다...', `FemaleText_loc4`='关于这个时间流，我们只得到了很少的一点情报。萨艾特已经被派遣进去了。从和他的通信中，我们获知的情报是永恒之龙再次尝试改变时间。很可能他们的目标是破坏黑暗之门的开启？希望不是这样……', `FemaleText_loc5`='我們對這條時間之道所知有限，因此派遣塞特前往調查。從他傳回的消息中指出，恆龍軍團要再次嘗試改變時間。黑暗之門的開啟事件成為他們破壞的目標了嗎?希望不是如此...', `FemaleText_loc7`='Tenemos muy poca información sobre este portal del tiempo. Sa''at ha sido enviado y, actualmente, está dentro. Los datos que hemos reunido de su correspondencia son que el Vuelo Infinito está intentando, una vez más, alterar el tiempo. ¿Podría ser que el objetivo sea sabotear la apertura del Portal Oscuro? Esperemos que no...' WHERE `ID`=17664;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리는 이 시간의 길이 하이잘 산으로 연결된다는 것 말고는 아는 게 없습니다. 무한의 용군단은 우리가 개입하지 못하도록 막기까지 했었지요. 우리가 알고 있는 것은 거의 아무것도 없습니다, 필멸의 존재여. 소리도르미가 시간의 길의 방어선을 돌파하기 위해 노력은 하고 있지만 아직 별다른 성과가 없었습니다. 방어선을 뚫고 가서 문제를 해결할 이는 당신밖에 없습니다.', `FemaleText_loc4`='这个时间流通向海加尔山，我们只知道这些。永恒之龙不顾一切地阻止我们的介入，因此我们对其它的事情丝毫没有头绪，凡人。索莉多米正在尝试着突破时间流的防守，但是迄今都没有成功。你或许是我们突破和解决这个冲突的唯一希望。', `FemaleText_loc5`='我們只知道這條時間之道通往海加爾山。恆龍軍團已盡了所有的力氣來阻止我們介入。我們不知道接下來會怎樣，凡人。索芮朵蜜目前正試圖衝破時間之道的防禦，但到目前為止都沒成功。你是我們突破並解決衝突唯一的希望。', `FemaleText_loc7`='Todo lo que sabemos de este portal del tiempo es que conduce al monte Hyjal. El Vuelo Infinito ha hecho todo lo posible para evitar nuestra implicación. No sabemos prácticamente nada, mortal. Actualmente, Soridormi está intentando atravesar las defensas del portal del tiempo, pero, hasta ahora, no ha tenido éxito. Puede que seas nuestra única esperanza de abrirnos paso y resolver el conflicto.' WHERE `ID`=17665;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리가 함께한 시간은 이제 끝났습니다, $n. 행운이 있다면 그 행운이 당신과 함께하기를 빌겠습니다.', `FemaleText_loc4`='我们的时间正处在危险的边缘，$n。如果运气这种东西确实存在的话，我祝你好运。', `FemaleText_loc5`='我們的時間就要結束了，$n。我祝你好運，如果真有好運存在的話。', `FemaleText_loc7`='Ha llegado el momento, $n. Te desearía suerte, pero sé que la suerte no existe.' WHERE `ID`=17666;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이곳의 진실은 단 두 가지입니다. 첫째, 시간은 무질서하며 끊임없이 흐르고 매우 순응적이다. 둘째, 인지하는 것이 현실은 아니다.', `FemaleText_loc4`='在这里只有两条真理：首先，时间是混乱的，永远在不停地变化，并且可以完全改变。第二，感觉并不代表真实。', `FemaleText_loc5`='這裡只有找到兩個真相:第一，時間是混亂的，永遠在變遷，完全的延展，第二，感覺並不支配事實。', `FemaleText_loc7`='Aquí solo se pueden encontrar dos verdades: primero, que el tiempo es caótico, siempre en flujo, y completamente maleable y, segundo, que la percepción no dicta la realidad.' WHERE `ID`=17667;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자, 다시 저를 따라오십시오.', `FemaleText_loc4`='请跟着我。', `FemaleText_loc5`='請跟著我。', `FemaleText_loc7`='Sígueme, por favor.' WHERE `ID`=17668;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 시간의 길은 현재 붕괴하여 재생성되었습니다. 그 결과는 옛날의 스트라솔름이었지요. 안에서 도대체 무슨 일이 일어나고 있었을까요?', `FemaleText_loc4`='这个时间流在塌缩后实现了重组，回归于往昔的斯坦索姆。什么样的事件正在其中上演呢？', `FemaleText_loc5`='這條時間之道現在正在崩塌與重組。終點將是往昔的斯坦索姆。那裡又可能會發生什麼事呢?', `FemaleText_loc7`='Este portal del tiempo se ha derrumbando y vuelto a formar. El resultado fue un Stratholme pretérito. ¿Qué puede estar pasando en su interior?' WHERE `ID`=17669;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희들은 죽어 마땅하다.', `MaleText_loc4`='罪有应得！', `MaleText_loc5`='這是你應得的!', `MaleText_loc7`='¡Te lo mereces!' WHERE `ID`=17670;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='친구들도 곧 네 뒤를 따르리라.', `MaleText_loc4`='你的朋友很快就会去找你了！', `MaleText_loc5`='你的朋友很快就會加入你的行列!', `MaleText_loc7`='¡Tus amigos pronto se reunirán contigo!' WHERE `ID`=17671;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요행이 있기만 빌어야 할 거다.', `MaleText_loc4`='祝你们……好运。你们会需要好运气的。', `MaleText_loc5`='祝你...好運。你會需要好運的。', `MaleText_loc7`='Buena suerte... La necesitarán.' WHERE `ID`=17672;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그를 풀어줘서는 안 돼!', `MaleText_loc4`='你们不能让他挣脱！', `MaleText_loc5`='千萬別讓他跑了!', `MaleText_loc7`='¡No deben liberarlo!' WHERE `ID`=17673;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무것도 모르는 것들이!', `MaleText_loc4`='无知的蠢货！', `MaleText_loc5`='無知的傢伙!', `MaleText_loc7`='¡Granujas ignorantes!' WHERE `ID`=17674;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바보들아, 그가 우리를 모두 죽일 것이다.', `MaleText_loc4`='你们这些蠢货！他会把我们全都杀掉！', `MaleText_loc5`='你這個蠢蛋!他會把我們全都殺了!', `MaleText_loc7`='¡Tontos! ¡Nos matará a todos!' WHERE `ID`=17675;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쿨루타스, 당장 수정을 도로 내놓아라!', `MaleText_loc4`='库鲁萨斯，你会马上把水晶还给我的！', `MaleText_loc5`='卡露薩斯，你要立刻把水晶帶來給我!', `MaleText_loc7`='¡Culuthas, me devolverás el cristal de inmediato!' WHERE `ID`=17676;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아타말 수정을 다루는 방법도 모르지 않나? 넌 수정에게 지배당할 것이다!', `MaleText_loc4`='你根本不知道怎么控制阿塔玛水晶。它会毁灭你的。', `MaleText_loc5`='你不知道如何控制阿塔莫水晶。它會毀了你!', `MaleText_loc7`='No tienes ni idea de cómo controlar el cristal de Ata''mal. ¡Te consumirá!' WHERE `ID`=17677;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수정을 돌려줘. 안 그러면 소멸을 면치 못하리라!', `MaleText_loc4`='把水晶还给我，否则就面对死亡吧！', `MaleText_loc5`='把水晶還給我不然就等死吧!', `MaleText_loc7`='¡Devuélveme el cristal o enfréntate a la aniquilación!' WHERE `ID`=17678;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나의 실험을 방해하지 마라!', `MaleText_loc4`='我的工作不能中断！', `MaleText_loc5`='我的工作不能被打斷!', `MaleText_loc7`='¡No tienen que interrumpir mi trabajo!' WHERE `ID`=17679;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희는 좋은 재료가 되겠어...', `MaleText_loc4`='也许我可以好好利用你……', `MaleText_loc5`='也許我可以用你來做點什麼...', `MaleText_loc7`='Quizá me sirvan para algo…' WHERE `ID`=17680;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='증오... 분노... 난 이런 것들을 다루는데 익숙하지.', `MaleText_loc4`='愤怒……仇恨……我可以利用的工具。', `MaleText_loc5`='憤怒...仇恨...這些是我可以使用的工具。', `MaleText_loc7`='Ira... odio... Esas son mis herramientas.' WHERE `ID`=17681;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 그리로 가서 널 죽이는 수고를 하게 하지 마라!', `MaleText_loc4`='不要逼我亲手杀了你！', `MaleText_loc5`='不要逼我過來殺你!', `MaleText_loc7`='¡No me hagas ir hasta allí y destruirte!' WHERE `ID`=17682;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희를 어떻게 변형할 수 있을지 한번 보자!', `MaleText_loc4`='我们来看看你能被改造成什么样子！', `MaleText_loc5`='看看我可以把你變成怎麼樣!', `MaleText_loc7`='¡Veamos qué puedo hacer contigo!' WHERE `ID`=17683;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저항해봤자 소용없다.', `MaleText_loc4`='抵抗是没有意义的。', `MaleText_loc5`='抵抗是沒有意義的。', `MaleText_loc7`='Es inútil resistirse.' WHERE `ID`=17684;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게서 떨어져!', `MaleText_loc4`='离我……远点！', `MaleText_loc5`='離...我遠一點!', `MaleText_loc7`='¡No se me acerquen!' WHERE `ID`=17685;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 나의 악마들을 죽이다니!', `MaleText_loc4`='你怎么敢杀了我的恶魔！', `MaleText_loc5`='你好大的膽子竟敢摧毀我的惡魔!', `MaleText_loc7`='¿Cómo te atreves a destruir mis demonios?' WHERE `ID`=17686;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대체 저것들은 뭐냐? 네가 부하로 소환한 것이냐? 주제를 알아야지!', `MaleText_loc4`='你召唤了什么东西来协助你？你以为你是谁？！', `MaleText_loc5`='你召喚了什麼東西來伺候你?!你以為你是誰!', `MaleText_loc7`='¡¿Qué son estas cosas que has invocado para servirte?! ¡Pero quién crees que eres!' WHERE `ID`=17687;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쿨루타스, 당장 수정을 가져와!', `MaleText_loc4`='库鲁萨斯，现在把水晶给我！', `MaleText_loc5`='卡露薩斯，現在就把水晶送來給我!', `MaleText_loc7`='¡Culuthas, devuélveme el cristal ahora!' WHERE `ID`=17688;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐지? 방금 무슨 소리 못 들었나? 쿨루타스, 근처에 무역연합의 졸개들이 있다. 당장 수정을 가져와!', `MaleText_loc4`='那是什么？你听到什么了吗？库鲁萨斯，那是附近星界财团的奴隶发出来的声音。马上把水晶给我拿过来！', `MaleText_loc5`='那是什麼?你聽到了嗎?卡露薩斯，附近有聯合團的僕人。立刻把水晶給我帶來!', `MaleText_loc7`='¿Qué es eso? ¿Has oído algo? Culuthas, hay sirvientes del Consorcio cerca. ¡Tráeme el cristal inmediatamente!' WHERE `ID`=17689;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쿨루타스, 어디로 사라진 거냐?!', `MaleText_loc4`='库鲁萨斯，你去哪儿了？！', `MaleText_loc5`='卡露薩斯你到哪裡去了?!', `MaleText_loc7`='¡¿Culuthas, dónde has ido?!' WHERE `ID`=17690;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 피해 숨지는 못한다, 쿨루타스! 네놈이 어디에 있든지 찾아내고 말겠다!', `MaleText_loc4`='休想逃过我的眼睛，库鲁萨斯。无论你逃到哪儿，我都不会放过你！', `MaleText_loc5`='你躲不過我的，卡露薩斯!不管你跑到哪我都會抓到你!', `MaleText_loc7`='¡No puedes esconderte de mí, Culuthas! ¡Te daré caza, no importa dónde vayas!' WHERE `ID`=17691;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='널 느낄 수 있다, ''모험가'' 친구... 심지어 이 마법의 환영을 통해서도 네가 느껴진다. 쿨루타스가 모습을 드러냈을 때 아타말 수정을 되찾을 수 있을 거로 생각하겠지. 하지만, 네놈의 착각이다!', `MaleText_loc4`='“冒险者”，即使是通过这魔法影像，我都可以感觉到你。你觉得你可以在库鲁萨斯现身的时候重新拿回阿塔玛水晶，但是你错了！', `MaleText_loc5`='我可以感應到你，「冒險者」，就算透過這個魔法影像也一樣。你以為你可以在卡露薩斯現身時取得阿塔莫水晶，但你搞錯了!', `MaleText_loc7`='Puedo sentirte, "$gaventurero:aventurera;", incluso a través de esta imagen mágica. Crees que recuperarás el cristal de Ata''mal cuando Culuthas se muestre, ¡pero estás $gequivocado:equivocada;!' WHERE `ID`=17692;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모습을 드러내라, 쿨루타스. 수정만 가져오면 모든 걸 용서하겠다.', `MaleText_loc4`='现身吧，库鲁萨斯。只要你给我水晶，也许我会当这一切没有发生过。', `MaleText_loc5`='現身啊，卡露薩斯。只要你把水晶帶來給我一切都可以原諒。', `MaleText_loc7`='Muéstrate, Culuthas. Todo estará olvidado si me traes el cristal.' WHERE `ID`=17693;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수정을 사용해서 숨었나? 네 능력으로는 그 수정의 힘을 완전히 감출 수 없다는 걸 알아둬라!', `MaleText_loc4`='你在用水晶隐藏自己吗？是不是？你应该知道这种力量不可能被掩盖！', `MaleText_loc5`='你用水晶來躲藏嗎?是這樣嗎?你應該知道你不可能掩蓋這樣的力量!', `MaleText_loc7`='¿Estás usando el cristal para esconderte? ¿Es eso? ¡Deberías saber que no puedes ocultar un poder así de ningún modo!' WHERE `ID`=17694;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 어디로 사라졌는지 몰라도 네놈과 수정을 찾아내고야 말겠다, 쿨루타스!', `MaleText_loc4`='我不知道你到底去哪了。但我可以保证，无论你在哪里，我都会找到你和那颗水晶，库鲁萨斯！', `MaleText_loc5`='我不知道你去了哪裡。但我保證不論你去了哪，我都會找到你和水晶，卡露薩斯!', `MaleText_loc7`='¡No sé dónde te has metido, pero puedo asegurarte que, estés donde estés, te encontraré a ti y al cristal, Culuthas!' WHERE `ID`=17695;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='심연이 너희를 집어삼키리라!', `FemaleText_loc4`='深渊将会吞噬你们！', `FemaleText_loc5`='死亡會毀滅你!', `FemaleText_loc7`='¡Las profundidades los consumirán!' WHERE `ID`=17696;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='땅개미들아, 너희 운명을 받아들여라!', `FemaleText_loc4`='迎接你们的末日吧，地面上的蠢货！', `FemaleText_loc5`='你的死期到了，地表的生物!', `FemaleText_loc7`='¡Van a morir, moradores de la superficie!' WHERE `ID`=17697;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너희 피가 강을 이루리라!', `FemaleText_loc4`='你们会淹死在鲜血中！', `FemaleText_loc5`='你會溺死在血水中!', `FemaleText_loc7`='¡Se ahogarán en sangre!' WHERE `ID`=17698;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쿨루타스, 내 손에 잡히면 영원한 고통 속에 몸부림치도록 해주겠다!', `MaleText_loc4`='库鲁萨斯，只要我找到你，我保证你会忍受无尽的痛苦！', `MaleText_loc5`='卡露薩斯，等我找到你，我絕對會讓你永遠受苦!', `MaleText_loc7`='¡Culuthas, cuando te encuentre, me aseguraré de que sufras por toda la eternidad!' WHERE `ID`=17699;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너희를 저승의 심연으로 데려가리라!', `FemaleText_loc4`='下地狱吧！', `FemaleText_loc5`='被遺忘的深淵等著你!', `FemaleText_loc7`='¡A las profundidades del olvido contigo!' WHERE `ID`=17701;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여군주와 주인님을 위하여!', `FemaleText_loc4`='为了女王和主人！', `FemaleText_loc5`='為了我的夫人和主人!', `FemaleText_loc7`='¡Por mi ama y señora!' WHERE `ID`=17702;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소크레타르, 내가 네놈에게 수정을 내줄 것 같나?!', `MaleText_loc4`='我不会把它给你的，索克雷萨！', `MaleText_loc5`='我不會把它給你的，索奎薩爾!', `MaleText_loc7`='¡No te lo daré, Socrethar!' WHERE `ID`=17703;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 여군주님이 오시면 너흰 끝장이다!', `FemaleText_loc4`='我们的女王……会消灭你们的。', `FemaleText_loc5`='我們的女監護者將會...把你終結。', `FemaleText_loc7`='Nuestra matrona los... acabará.' WHERE `ID`=17704;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무리 지껄여 봐라. 그런다고 내가 이런 힘을 포기할 것 같으냐!', `MaleText_loc4`='说什么我也不会放弃这种力量！', `MaleText_loc5`='你說的任何話都不會說服我放棄這樣的力量!', `MaleText_loc7`='¡Nada que digas me convencerá de abandonar tal poder!' WHERE `ID`=17705;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수정만 있으면 이 몸이 바로 신이시다!', `MaleText_loc4`='水晶在手，天下我有！！！', `MaleText_loc5`='有了水晶，我就是神了!', `MaleText_loc7`='¡CON EL CRISTAL, SOY UN DIOS!' WHERE `ID`=17706;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실컷 떠들어라. 아무리 그래도 아타말 수정은 넘겨줄 수 없다.', `MaleText_loc4`='就算你一直说到脸色发青，我也不会把阿塔玛水晶交给你的。', `MaleText_loc5`='你可以一直講話直到你的臉孔變青為止，我不會把阿塔莫水晶送給你的。', `MaleText_loc7`='Puedes hablar todo lo que quieras; no te pienso entregar mi cristal de Ata''mal.' WHERE `ID`=17707;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소크레타르, 내 생각은 좀 다른데... 수정의 힘을 얻으면 넌 나를 섬기게 되리라. 단, 널 살려준다는 조건에서 말이다.', `MaleText_loc4`='我不这么觉得，索克雷萨。有了水晶的力量，你会很快就会成为我的仆人——如果我允许你活着的话。', `MaleText_loc5`='我不這麼認為，索奎薩爾。有了水晶的力量，你很快就會效命於我了。如果我讓你活下來的話。', `MaleText_loc7`='No lo creo, Socrethar. Con el poder del cristal, pronto me servirás. Si te permito vivir, claro.' WHERE `ID`=17708;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 수정을 탐냈던 놈들을 모두 단숨에 해치웠지. 훗날 내가 널 찾아가는 날, 너도 간단히 처리해 주마.', `MaleText_loc4`='他们都想把它据为己有，但是我轻而易举地把他们干掉了，很快你也将是这个下场。', `MaleText_loc5`='他們全都想獨佔它，但我已將他們輕鬆地殺掉，就像我等下去拜訪你時會輕鬆地把你殺了一樣。', `MaleText_loc7`='Todos lo querían para sí, pero yo los maté con tanta facilidad como te mataré a ti dentro de un momento.' WHERE `ID`=17709;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼.', `MaleText_loc4`='不。', `MaleText_loc5`='不。', `MaleText_loc7`='No.' WHERE `ID`=17710;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경계를 늦추지 마라!', `MaleText_loc4`='保持警惕！', `MaleText_loc5`='保持警覺!', `MaleText_loc7`='¡Mantente alerta!', `FemaleText_loc1`='경계를 늦추지 마라!', `FemaleText_loc4`='保持警惕！', `FemaleText_loc5`='保持警覺!', `FemaleText_loc7`='¡Mantente alerta!' WHERE `ID`=17711;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마음껏 지껄여라. 수정은 내가 갖고 있겠다. 조만간 모든 아웃랜드가 내 발밑에 무릎을 꿇으리라!', `MaleText_loc4`='乞求你想要的一切吧，但水晶是我的。整个外域很快就会被我踏在脚下！', `MaleText_loc5`='很抱歉，我要自己留著水晶。整個外域很快將被踩在我腳下!', `MaleText_loc7`='Suplica todo lo que quieras, pero me quedo con el cristal para mí. ¡Toda Terrallende caerá pronto bajo mi paso!' WHERE `ID`=17712;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자를 조심하라.', `MaleText_loc4`='注意入侵者。', `MaleText_loc5`='小心入侵者。', `MaleText_loc7`='Cuidado con los intrusos.', `FemaleText_loc1`='침입자를 조심하라.', `FemaleText_loc4`='注意入侵者。', `FemaleText_loc5`='小心入侵者。', `FemaleText_loc7`='Cuidado con los intrusos.' WHERE `ID`=17713;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 근처에 물이 있었으면 참 좋을 것 같지 않나?', `MaleText_loc4`='你不希望这附近有水吗？', `MaleText_loc5`='你不希望附近有點水嗎?', `MaleText_loc7`='¿No te gustaría que hubiera agua por aquí?', `FemaleText_loc1`='이 근처에 물이 있었으면 참 좋을 것 같지 않나?', `FemaleText_loc4`='你不希望这附近有水吗？', `FemaleText_loc5`='你不希望附近有點水嗎?', `FemaleText_loc7`='¿No te gustaría que hubiera agua por aquí?' WHERE `ID`=17714;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님을 실망시킬 수는 없다.', `MaleText_loc4`='我们不能辜负主人。', `MaleText_loc5`='我們絕不能讓主人失望。', `MaleText_loc7`='No debemos fallarle al maestro.', `FemaleText_loc1`='주인님을 실망시킬 수는 없다.', `FemaleText_loc4`='我们不能辜负主人。', `FemaleText_loc5`='我們絕不能讓主人失望。', `FemaleText_loc7`='No debemos fallarle al maestro.' WHERE `ID`=17715;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고통의 세계를 보여주마!', `MaleText_loc4`='你们有苦头吃了！', `MaleText_loc5`='你到了一個痛苦的世界!', `MaleText_loc7`='¡Han entrado en la dimensión del dolor!' WHERE `ID`=17716;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='금속의 뜨거운 맛을 봐라, 더러운 놈들!', `MaleText_loc4`='等死吧，草包们！', `MaleText_loc5`='吃熱金屬吧，卑鄙小人!', `MaleText_loc7`='¡Traga metal caliente, canalla!' WHERE `ID`=17717;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 그쪽으로 가마!', `MaleText_loc4`='我要出手了！', `MaleText_loc5`='我會過來的!', `MaleText_loc7`='¡Ahora voy!' WHERE `ID`=17718;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정한 고통이 뭔지 알려주겠다!', `MaleText_loc4`='我要给你们一些苦头吃！', `MaleText_loc5`='我會為你帶來痛苦!', `MaleText_loc7`='¡Traigo mucho dolor!' WHERE `ID`=17719;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='애송이, 제대로 대접받으니 어때!', `MaleText_loc4`='你玩完了，蠢货！', `MaleText_loc5`='你死了，笨蛋!', `MaleText_loc7`='¡Despachado, rufián!' WHERE `ID`=17720;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 널 차지했다!', `MaleText_loc4`='我比你强！', `MaleText_loc5`='你不是我的對手!', `MaleText_loc7`='¡Te he machacado!' WHERE `ID`=17721;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 죽었다, 식은 죽 먹기로군.', `MaleText_loc4`='去死吧，白痴！', `MaleText_loc5`='享受你的死亡吧，弱者!', `MaleText_loc7`='¡Muérete a gusto, pastelito!' WHERE `ID`=17722;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엄마...', `MaleText_loc4`='妈呀。', `MaleText_loc5`='媽啊。', `MaleText_loc7`='Mamá.' WHERE `ID`=17723;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 경비병들을 꺾었다고 아주 기고만장을 하는구나. 우리 계획에 타협이란 없다!', `MaleText_loc4`='打败了我的卫兵，就以为自己已经足够强大了吗？我们的工作成果是不容你们损害的！', `MaleText_loc5`='只是因為打敗了我的守衛你們就自認為有價值嗎?我們在這裡的工作是不會停止的!', `MaleText_loc7`='¿Consideran que son dignos solo porque son mejores que mis guardias? ¡No se comprometerá nuestro trabajo aquí!' WHERE `ID`=17724;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 끝나지 않았다.', `MaleText_loc4`='还没完呢……', `MaleText_loc5`='這離結束還差的遠...', `MaleText_loc7`='¡Esto no se ha acabado todavía!' WHERE `ID`=17725;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곧 너희들의 시체가 산을 이룰 것이다.', `MaleText_loc4`='你们小命不保了！', `MaleText_loc5`='你會人頭落地!', `MaleText_loc7`='¡Rodarán sus cabezas!' WHERE `ID`=17726;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 종족은 정말 싫어!', `MaleText_loc4`='我藐视你们这些低等生物！', `MaleText_loc5`='我瞧不起你們族人!', `MaleText_loc7`='¡Desprecio a todos los de su clase!' WHERE `ID`=17727;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바안탈소 도레이!', `MaleText_loc4`='Ba''anthalso-dorei！', `MaleText_loc5`='讓大地居住者死!', `MaleText_loc7`='¡Ba''anthalso-dorei!' WHERE `ID`=17728;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무리 발버둥쳐도 소용없다!', `MaleText_loc4`='没用的东西！', `MaleText_loc5`='蠕動，地面的污物!', `MaleText_loc7`='¡Retuércete, inmundicia de la superficie!' WHERE `ID`=17729;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='군주님을 위하여!', `MaleText_loc4`='为了……瓦丝琪女王！', `MaleText_loc5`='為了她閣下...為了...瓦許!', `MaleText_loc7`='¡Por Su excelencia... por... Vashj!' WHERE `ID`=17730;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나도... 부하들이 있다!', `MaleText_loc4`='我有自己的—呱嘎—宠物！', `MaleText_loc5`='我有寵物 - 喀-嘎! - 我自己的!', `MaleText_loc7`='¡Tengo mascotas ah-ogh, propias!' WHERE `ID`=17733;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠, 움직일 시간이군!', `MaleText_loc4`='嗯……该我行动了！', `MaleText_loc5`='嗯...是時候行動了!', `MaleText_loc7`='¡Mmm... ahora, me toca a mí!' WHERE `ID`=17734;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='귀여운 것들, 그래...', `MaleText_loc4`='不错的宠物，哈哈……呱呱嘎！', `MaleText_loc5`='好寵物，是的...呀啊-啊-啊喀!', `MaleText_loc7`='¡Bonitas mascotas, si... raa-a-ak!' WHERE `ID`=17735;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꼬마들이 무기도 들었네. 그리... 훌륭하진 않군.', `MaleText_loc4`='不错的宠物，但是有武器就—嘎嘎—不太好了！', `MaleText_loc5`='好的寵物都有武器。沒有這麼 - 呀-喀 - 好。', `MaleText_loc7`='Las mascotas bonitas tienen armas. No son tan ra-ak-bonitas.' WHERE `ID`=17736;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 삶이란 덧없는 것이지...', `MaleText_loc4`='对，生命是短暂的，嘎嘎呱！', `MaleText_loc5`='是的，短暫的生命，呀喀-啊-喀喀!', `MaleText_loc7`='¡Sí, efímera es la vida, raa-a-aak!' WHERE `ID`=17737;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음, 자유롭게 해주마!', `MaleText_loc4`='嗯……你自由了。呱！', `MaleText_loc5`='嗯...自由吧。嘎!', `MaleText_loc7`='Mmm... sé libre. ¡Aak!' WHERE `ID`=17738;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음... 생명이 없으면 고통도 없지.', `MaleText_loc4`='啊……没有了生命，没有了痛苦。嘎！', `MaleText_loc5`='嗯...不要再有生命。不要再有痛苦。啊-呀喀!', `MaleText_loc7`='Mmm... se acabó la vida, se acabó el dolor. ¡A-ak!' WHERE `ID`=17739;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하라, 필멸의 존재여. 이 전당의 뒤에는 그대의 세계에서 들어 보지 못한 위험한 것들이 존재하고 있느니... 조심해서 전진하라.', `MaleText_loc4`='小心，凡人。穿过这座大厅之后，你将面对在你的世界里从未听说过的危险。小心点……', `MaleText_loc5`='小心，凡人，這間大廳後面有著你的世界從未聽過的危險。小心地走...', `MaleText_loc7`='Cuidado, mortal. tras esta sala hay peligros desconocidos en tu mundo. Camina con cuidado...' WHERE `ID`=17740;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 만나서 반갑다, $n. 내가 그대를 주인님의 둥지에 데려다 주길 원하나?', `MaleText_loc4`='很高兴再次见到你，$n。想让我带你去主人的巢穴吗？', `MaleText_loc5`='很高興再見到你，$n。你要我帶你去主人的巢穴嗎?', `MaleText_loc7`='Me alegro de verte de nuevo, $n. ¿Quieres que te lleve a la guarida del maestro?' WHERE `ID`=17741;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저를 데려다 주십시오.', `MaleText_loc4`='请带我去主人的巢穴。', `MaleText_loc5`='請帶我去主人的巢穴。', `MaleText_loc7`='Llévame a la guarida del maestro.', `FemaleText_loc1`='저를 데려다 주세요.', `FemaleText_loc4`='请带我去主人的巢穴。', `FemaleText_loc5`='請帶我去主人的巢穴。', `FemaleText_loc7`='Llévame a la guarida del maestro.' WHERE `ID`=17742;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아라시 분지가 파멸단의 공격을 받고 있습니다. $n, 저희를 도와주시겠습니까?', `MaleText_loc4`='阿拉希盆地被污染者侵占了。你会帮我们作战吗，$n？', `MaleText_loc5`='阿拉希盆地已被污染者侵擾。你能幫我們嗎，$n?', `MaleText_loc7`='La Cuenca de Arathi está ocupada por Los Rapiñadores. ¿Puedes ayudarnos, $n?' WHERE `ID`=17743;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 먼 곳에서 알도르의 친구를 만나다니 정말 반갑습니다. 이 엘프들이 건방지게 떠들어 대는 소리를 참는 것도 곧 한계에 도달할 것 같군요.', `MaleText_loc4`='很高兴能在这个偏远的地方看到奥尔多的朋友。我恐怕自己无法再忍受这些精灵傲慢的话语了。', `MaleText_loc5`='在這些偏遠地區能見到奧多爾的朋友真好。我擔心我不能再忍受這些精靈厚顏無恥的嘮叨了。', `MaleText_loc7`='Me alegro de ver a un amigo de Aldor por estos recónditos rincones. Me temo que no soportaré mucha más cháchara de esos elfos insolentes.' WHERE `ID`=17744;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n, 아라시 분지로 들어가! 처치해! 손에 처음 피를 묻혀보는 것처럼 전투의 의지를 불태우도록!', `FemaleText_loc4`='去吧，$n，去阿拉希盆地勇敢地战斗吧！', `FemaleText_loc5`='去吧，$n，進入阿拉希盆地!殺，殺，就像你從未殺過一樣!', `FemaleText_loc7`='¡$n, ve a la Cuenca de Arathi! ¡Mata! ¡Mata como nunca habías matado antes!' WHERE `ID`=17745;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네를 위해 전쟁노래 협곡으로 들어가는 문을 열겠네. 비열한 얼라이언스와 맞서 싸우겠나?', `MaleText_loc4`='战歌峡谷的入口就在你的前面。你会和这些肮脏的联盟战斗到底吗？', `MaleText_loc5`='戰歌峽谷的入口就在你面前。你會對抗那裡卑鄙的聯盟嗎?', `MaleText_loc7`='Tienes ante ti la entrada a la Garganta Grito de Guerra. ¿Te enfrentarás a la odiosa Alianza allí?' WHERE `ID`=17746;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='만나서 반갑습니다. 이 순간에도 호드는 전쟁노래 협곡을 공격하고 있습니다. 얼라이언스를 도와 싸우시겠습니까?', `FemaleText_loc4`='你好啊，$c。即使是现在，部落还在进攻战歌峡谷。你会和联盟并肩而战吗？', `FemaleText_loc5`='你好，$c。就連到了現在，部落仍在攻擊戰歌峽谷。你會和聯盟一起奮戰嗎?', `FemaleText_loc7`='Saludos, $c. Incluso ahora, la Horda ataca la garganta Grito de Guerra. ¿Lucharás junto a la Alianza allí?' WHERE `ID`=17747;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 뭘 우물쭈물하고 있나?! 알터랙 계곡에서 자네를 부르고 있네. 어서 서둘러!', `MaleText_loc4`='你在这里干什么？！去奥特兰克山谷吧，那里需要你！', `MaleText_loc5`='你在這裡做什麼?!快到奧特蘭克山谷去，那裡需要你!', `MaleText_loc7`='¡¿Qué haces aquí?! ¡Muévete al Valle de Alterac, donde se te necesita!' WHERE `ID`=17748;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='빌어먹을! 지금쯤 알터랙 계곡에서 신나게 싸우고 있어야 하는데 여기서 안내나 해야 하다니... 자네! 얼라이언스와 싸우러 왔나?', `FemaleText_loc4`='野猪粪！为什么当我自己可以上阵杀敌的时候，却让我站在这里指引别人去奥特兰克山谷？你！你去跟联盟打过仗了吗？', `FemaleText_loc5`='野豬糞!為什麼我就一定要留在這裡引導其他人去奧特蘭克山谷，而不是自己去作戰?你!你是來對抗聯盟的嗎?', `FemaleText_loc7`='¡EXCREMENTO DE JABALÍ! ¿Por qué tengo que quedarme aquí sirviendo de guía para el Valle de Alterac pudiendo estar luchando? ¡Tú! ¿Has venido a luchar contra la Alianza?' WHERE `ID`=17749;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='숲은 변화의 씨앗과 함께 노래한다. 그렇지만 고통에 빠져 울기도 한다.$B$B우리의 새로운 동료인 드레나이도 그대와 같이 우리를 도우려고 이곳으로 왔다. 형제와 자매의 나무들이 종말을 맞고, 잿빛 골짜기가 사라지기 전에 이 파괴적인 행위는 종식되어야 한다.', `MaleText_loc4`='森林在为变革的种子而歌唱，但也还在因为痛苦而哭号。$B$B德莱尼人是我们的新朋友，他们像你一样在帮助我们。我们必须阻止那些兽人继续摧毁我的树木兄弟和姐妹。否则，灰谷将不复存在。', `MaleText_loc5`='森林和改變的種子一同歌唱著，但它也因痛苦而悲鳴。$B$B就像你一樣，我們的新朋友德萊尼來到這幫助我們。我們必須阻止我的樹木兄弟和姐妹們遭到殺害，在一切都毀滅和梣谷消失之前。', `MaleText_loc7`='El bosque canta con las semillas del cambio. Pero también grita de dolor.$B$BNuestros nuevos amigos, los draenei, están aquí para ayudarnos, al igual que tú. Debemos acabar con la destrucción de mis hermanos y hermanas árboles antes de que todo esté perdido y Vallefresno deje de existir.' WHERE `ID`=17750;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타이리와 조라드에게 접촉을 시도합니다.', `MaleText_loc4`='尝试联系泰莉和乔拉德。', `MaleText_loc5`='試圖聯繫泰利和喬洛德。', `MaleText_loc7`='Intenta ponerte en contacto con Tyri y Jorad.', `FemaleText_loc1`='타이리와 조라드에게 접촉을 시도합니다.', `FemaleText_loc4`='尝试联系泰莉和乔拉德。', `FemaleText_loc5`='試圖聯繫泰利和喬洛德。', `FemaleText_loc7`='Intenta ponerte en contacto con Tyri y Jorad.' WHERE `ID`=17751;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그 교활한 에테리얼을 만날 필요가 전혀 없습니다. 이리 오십시오. 의논할 일이 아주 많습니다.', `FemaleText_loc4`='不需要再和那个两面三刀的虚灵联系了。过来，我们有很多事情要讨论。', `FemaleText_loc5`='沒必要聯絡那個為所欲為的以太族。來，我們還有很多事要談。', `FemaleText_loc7`='No hay razón para entrar en contacto con ese conspirador etéreo. Ven, tenemos mucho de qué hablar.' WHERE `ID`=17752;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='던홀드로 날아갈 준비가 끝나면 내게 말하라. 그곳까지 태워 주겠다.', `MaleText_loc4`='当你准备好飞往敦霍尔德的时候，跟我说一声。我会带你去那里的。', `MaleText_loc5`='等你準備好飛往敦霍爾德，讓我知道我就會載你去。', `MaleText_loc7`='Cuando estés $glisto:lista; para volar a Durnholde, házmelo saber y te llevaré.' WHERE `ID`=17753;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황천의 비룡에 대해 더 많은 정보를 가지고 왔습니다. 당신의 사업을 도와서 수익을 늘려보고 싶습니다. 그 골칫거리 엘프와 그녀의 인간 친구는 제가 처리하겠습니다.', `MaleText_loc4`='星界商人玛里德，我带来了更多有关虚空幼龙的情报。我打算跟你搭档作生意，如果你愿意多付一点的话，我还可以帮你关照那个麻烦的精灵和她的人类朋友。', `MaleText_loc5`='風之貿易者瑪利德，我帶回了更多虛空龍的消息。我準備好當你的生意夥伴了，為了額外的一筆錢，我會解決那個麻煩的精靈和她的人類朋友。', `MaleText_loc7`='Comerciante de viento Marid, he vuelto con más información sobre los dracos abisales. Estoy preparado para ser tu socio comercial y, por una cantidad adicional, me ocuparé de esa elfa molesta y de su amigo humano.', `FemaleText_loc1`='황천의 비룡에 대해 더 많은 정보를 가지고 왔어요. 당신의 사업을 도와서 수익을 늘려보고 싶네요. 그 골칫거리 엘프와 그녀의 인간 친구는 제가 처리하죠.', `FemaleText_loc4`='星界商人玛里德，我带来了更多有关虚空幼龙的情报。我打算跟你搭档作生意，如果你愿意多付一点的话，我还可以帮你关照那个麻烦的精灵和她的人类朋友。', `FemaleText_loc5`='風之貿易者瑪利德，我帶回了更多虛空龍的消息。我準備好當你的生意夥伴了，為了額外的一筆錢，我會解決那個麻煩的精靈和她的人類朋友。', `FemaleText_loc7`='Comerciante de viento Marid, he vuelto con más información sobre los dracos abisales. Estoy preparada para ser tu socia comercial y, por una cantidad adicional, me ocuparé de esa elfa molesta y de su amigo humano.' WHERE `ID`=17754;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살려 주십시오! 아렐리온의 비밀에 대해 알려드리겠습니다.', `MaleText_loc4`='请饶我一命！我会告诉你埃雷利恩的秘密。', `MaleText_loc5`='饒我一命!我會告訴你阿利恩的秘密。', `MaleText_loc7`='¡Perdóname la vida! Te contaré el secreto de Arelion.' WHERE `ID`=17755;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용건이 뭡니까? 저는 잡담이나 할 만큼 한가하지 않습니다.', `MaleText_loc4`='你要什么？我不是个喜欢闲聊的人。', `MaleText_loc5`='你想幹嘛?我沒空閒話家常。', `MaleText_loc7`='¿Qué es lo que quieres? No me van las charlas.' WHERE `ID`=17756;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법학자 카린다가 당신에게 아렐리온의 비밀에 대해 물어보라며 절 보냈습니다. 그가 누구랑 사귀었죠?', `MaleText_loc4`='魔导师卡尔琳达让我来问你关于埃雷利恩的秘密。他是不是在外面跟别人幽会？', `MaleText_loc5`='博學者卡莉達派我來問你阿利恩的秘密。誰見過他嗎?', `MaleText_loc7`='La magistrix Carinda me ha enviado para preguntarte sobre el secreto de Arelion. ¿A quién estaba viendo?', `FemaleText_loc1`='마법학자 카린다가 당신에게 아렐리온의 비밀에 대해 물어보라며 절 보냈습니다. 그가 누구랑 사귀었죠?', `FemaleText_loc4`='魔导师卡尔琳达让我来问你关于埃雷利恩的秘密。他是不是在外面跟别人幽会？', `FemaleText_loc5`='博學者卡莉達派我來問你阿利恩的秘密。誰見過他嗎?', `FemaleText_loc7`='La magistrix Carinda me ha enviado para preguntarte sobre el secreto de Arelion. ¿A quién estaba viendo?' WHERE `ID`=17757;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 친구를 그리 쉽게 배신할 줄 알았느냐. 착각하지 마라! 내게 맞서보아라, 이 불한당 같은 녀석!', `MaleText_loc4`='如果你觉得我会这么轻易背叛我的朋友，那你就大错特错了！来吧，你这个无赖！', `MaleText_loc5`='如果你以為我會那麼輕易地背叛我的朋友，那就請你再想想吧!挑戰我，你這壞蛋!', `MaleText_loc7`='¡Si crees que traicionaré a mi $gamigo:amiga; tan fácilmente, piénsatelo dos veces! ¡Mírame, canalla!' WHERE `ID`=17758;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지금은 뇌물을 먹이는 중이라 좀 바쁩니다. 나중에 다시 오십시오.', `FemaleText_loc4`='我现在正忙着讨论一个贿赂计划。你不如晚点过来吧？', `FemaleText_loc5`='我現在有點忙著協商賄賂。你等下再回來找我。', `FemaleText_loc7`='Ahora mismo estoy un poco ocupada negociando un soborno. Quizás quieras volver más tarde.' WHERE `ID`=17759;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 당신을 코루 마나괴철로로 데려다 드리겠습니다. 준비됐습니까? 적진 바로 뒤에 떨어뜨려 놓을 테니 필요한 물건이 있으면 빼놓지 말고 가져가십시오.', `FemaleText_loc4`='我已经安排送你去法力熔炉：库鲁恩的事宜了。你准备好了吗，$n？你会降落在敌人的防守线后方，所以请确保你带了所有必需的东西。', `FemaleText_loc5`='我已經安排好讓你到法力熔爐寇魯的班次了。你準備好了嗎，$n?你會在敵方戰線後方被放下來，所以確定你帶了所有需要的東西去。', `FemaleText_loc7`='He organizado tu vuelo a la forja de maná Coruu. ¿Estás $gpreparado:preparada;, $n? Te dejarán detrás de las filas enemigas, así que asegúrate de llevar todo lo que necesitas.' WHERE `ID`=17760;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='완벽하게 준비됐습니다.', `MaleText_loc4`='我完全准备好了。', `MaleText_loc5`='我從沒像現在這樣十足的準備妥當。', `MaleText_loc7`='Estoy más preparado que nunca.', `FemaleText_loc1`='완벽하게 준비됐어요.', `FemaleText_loc4`='我完全准备好了。', `FemaleText_loc5`='我從沒像現在這樣十足的準備妥當。', `FemaleText_loc7`='Estoy más preparada que nunca.' WHERE `ID`=17761;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이키스는 까악... 까악.. 죽지 않아.', `MaleText_loc4`='艾吉斯不会……呱嘎……不会死…', `MaleText_loc5`='伊奇斯不會 - 啊，啊 - 死...', `MaleText_loc7`='Ikiss no -rak, rak-morirá...' WHERE `ID`=17762;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽어라! 장신구에 손대지 마!', `MaleText_loc4`='死吧！嘎！别想动我的宝贝！', `MaleText_loc5`='你去死吧 - 嘎!離飾品遠一點!', `MaleText_loc7`='¡Muere-ka! ¡No toques los abalatorios!' WHERE `ID`=17763;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으으으음...', `MaleText_loc4`='嗯……', `MaleText_loc5`='嗯...', `MaleText_loc7`='Mmm...' WHERE `ID`=17764;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음, 감히 나에게 도전하는 거냐?!', `MaleText_loc4`='嗯，你们想跟艾吉斯开战？呱嘎！', `MaleText_loc5`='嗯，你對伊奇斯宣戰?哎呀!', `MaleText_loc7`='Mmmm, ¿declaran la guerra a Ikiss? ¡Aa-ak!' WHERE `ID`=17765;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 악마들을 통과시키지 마십시오! 내 뒤에는 부상자들이 있습니다!', `MaleText_loc4`='不要让那些恶魔冲过来！我们的伤员在后面！', `MaleText_loc5`='別讓那些惡魔通過!我們的傷者就在我身後!', `MaleText_loc7`='¡No dejéis que esos malignos se abran paso! ¡Nuestros heridos están detrás de mí!', `FemaleText_loc1`='저 악마들을 통과시키지 마십시오! 내 뒤에는 부상자들이 있습니다!', `FemaleText_loc4`='不要让那些恶魔冲过来！我们的伤员在后面！', `FemaleText_loc5`='別讓那些惡魔通過!我們的傷者就在我身後!', `FemaleText_loc7`='¡No dejéis que esos malignos se abran paso! ¡Nuestros heridos están detrás de mí!' WHERE `ID`=17766;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이키스가 할퀴어 줄까? 찢어 줄까?!', `MaleText_loc4`='艾吉斯杀了你们，呱嘎嘎！杀了你们！', `MaleText_loc5`='伊奇斯會砍你的肉，小可愛 - 呀喀-啊-呀喀 - 刮你的皮，太棒了!', `MaleText_loc7`='Ikiss los corta, preciosos-ak-a-ak-, los rebana, ¡sí!' WHERE `ID`=17767;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너흰 절대 도망 못 간다!', `MaleText_loc4`='咕呱——嘎！休想逃走！', `MaleText_loc5`='逃不了的 - 喀 - 你!', `MaleText_loc7`='¡No hay escapatoria para aogh-para ustedes!' WHERE `ID`=17768;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장신구. 그래, 어여쁜 장신구! 힘, 위대한 힘... 장신구의 힘!', `MaleText_loc4`='呱嘎！宝贝，对，强大的宝贝！力量，无穷的力量。呱嘎嘎！宝贝中的力量！嘎嘎！', `MaleText_loc5`='呀啊!飾品，太好了。漂亮的飾品!啊!力量，強大的力量。呀喀!飾品的力量!呀喀!', `MaleText_loc7`='¡Ra-ak! Abalorios, sí. ¡Abalorios preciosos! ¡Ak! Poder, gran poder. ¡Ra-kaw! ¡Poder de los abalorios! ¡Ak-co!' WHERE `ID`=17769;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 영혼을 먹어주마.', `MaleText_loc4`='我要……吞噬你的灵魂。', `MaleText_loc5`='我會以你的靈魂...為食物。', `MaleText_loc7`='Me nutriré de... sus almas.' WHERE `ID`=17771;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생명력이 느껴진다.', `MaleText_loc4`='这里……充满了活力。', `MaleText_loc5`='真是...生意盎然。', `MaleText_loc7`='Tanta... vida.' WHERE `ID`=17772;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저항하지 마라..', `MaleText_loc4`='不要……抵抗。', `MaleText_loc5`='不要...抵抗。', `MaleText_loc7`='No... se resistan.' WHERE `ID`=17773;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래... 나의 힘은 막강하다...', `MaleText_loc4`='我……更强大了。', `MaleText_loc5`='是的...我被...賦予力量。', `MaleText_loc7`='Sí... tengo... el poder.' WHERE `ID`=17774;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더... 더 많이 필요하다..', `MaleText_loc4`='更多……还要更多。', `MaleText_loc5`='更多...我一定還要更多。', `MaleText_loc7`='Más... quiero más.' WHERE `ID`=17775;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 공허로 돌아가는구나.', `MaleText_loc4`='再次……回到虚空。', `MaleText_loc5`='再一次，到達虛無。', `MaleText_loc7`='Al Vacío... otra vez.' WHERE `ID`=17776;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='작별 인사를 할 시간이군. 잘 있으시오.', `MaleText_loc4`='我必须……说再见了。', `MaleText_loc5`='我一定要和你說...再會了。', `MaleText_loc7`='Debo... despedirme.' WHERE `ID`=17777;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 가시오.', `MaleText_loc4`='恕不远送。', `MaleText_loc5`='而現在我們和同伴分離。', `MaleText_loc7`='Ahora nos decimos adiós.' WHERE `ID`=17778;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 즐거운 시간이었소.', `MaleText_loc4`='这场战斗……很有趣。', `MaleText_loc5`='一切真是...很有意思。', `MaleText_loc7`='Ha sido... divertido.' WHERE `ID`=17779;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 정식으로 소개도 안 한 것 같은데?', `MaleText_loc4`='我们还没有互相作自我介绍呢。', `MaleText_loc5`='我們還沒被正式地引見。', `MaleText_loc7`='No nos han presentado debidamente.' WHERE `ID`=17780;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멋진 전투로군, 아주 재미있어.', `MaleText_loc4`='一场史诗般的战斗，多么激动人心啊！', `MaleText_loc5`='一場史詩聖戰，多刺激啊!', `MaleText_loc7`='Una batalla épica, ¡qué emocionante!' WHERE `ID`=17781;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='즐거운 모험을 기다리고 있었소.', `MaleText_loc4`='我多么渴望能有一次真正的冒险！', `MaleText_loc5`='我一直期待一次很棒的冒險!', `MaleText_loc7`='¡Anhelaba una aventura de verdad!' WHERE `ID`=17782;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신들에게 보여줄 아주 멋진 선물이 있지.', `MaleText_loc4`='我有一些很棒的东西要展示给你们……', `MaleText_loc5`='我有一個很棒的東西要給你看。', `MaleText_loc7`='Les voy a enseñar cosas fascinantes.' WHERE `ID`=17783;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 무슨 일이야? 하, 손님이 찾아오실 줄은 몰랐는데 사과 말씀드리겠소. 보시다시피 우린 지금 무척 바쁘다오. 하지만, 손님 접대는 꼭 친히 이 몸께서 해드리겠소.', `MaleText_loc4`='这是怎么回事？请原谅，但是我没有料到会有人来拜访。正如你们看到的，我们现在有别的事情要忙。不过没关系，作为一个热情的主人，我会用自己的方式招待你们……', `MaleText_loc5`='這是什麼?你一定要原諒我，因為我沒料到會有客人來。如你所見，我們現在有點忙。但是沒關係。由於我是個殷勤的主人，我會...親自招待你的。', `MaleText_loc7`='¿Qué significa esto? Me tienen que disculpar pero no esperaba compañía. Como pueden ver, estamos algo preocupados ahora mismo. Pero no importa. Puesto que soy un gentil anfitrión los atenderé... personalmente.' WHERE `ID`=17784;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; $n|1을;를; 보더니 점점 커집니다!', `MaleText_loc4`='%s看着$n，开始变大！', `MaleText_loc5`='%s看到$n體型便不斷變大!', `MaleText_loc7`='¡%s crece al ver a $n!' WHERE `ID`=17785;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s의 힘이 점점 약해집니다.', `MaleText_loc4`='%s的力量消失了。', `MaleText_loc5`='%s的力量逐漸消褪。', `MaleText_loc7`='La fuerza de %s se desvanece.' WHERE `ID`=17786;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하라매드 님, 사실 당신이 신경 쓸 일이 많습니다. 그 아타말 수정을 저의 주인이신 캘타스 왕자님께 드리는 것도 그중 하나가 되겠지요.', `MaleText_loc4`='事实上，节点亲王哈拉迈德，你有很多东西需要考虑。比如说把阿塔玛水晶交给我的主人，凯尔萨斯王子。', `MaleText_loc5`='的確，奈薩斯王子哈拉瑪德，你是有很多事要考慮。像是把阿塔莫水晶交給我的主人，凱爾薩斯王子。', `MaleText_loc7`='Efectivamente, príncipe-nexo Haramad, tenéis mucho en qué pensar. Como en devolver ese cristal de Ata''mal a mi maestro, el príncipe Kael''thas.' WHERE `ID`=17787;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아타말 수정의 힘을 사용해 네놈을 박살 내주마!', `MaleText_loc4`='我会用阿塔玛水晶的力量来毁灭你！', `MaleText_loc5`='我會用阿塔莫水晶的力量來粉碎你!', `MaleText_loc7`='¡Usaré el poder del cristal de Ata''mal para aplastarte!' WHERE `ID`=17788;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아타말 수정은 절대 뺏어가지 못한다!', `MaleText_loc4`='别想抢走我的阿塔玛水晶！', `MaleText_loc5`='你永遠不會從我這裡拿走阿塔莫水晶!', `MaleText_loc7`='¡No me arrebatarás el cristal de Ata''mal!' WHERE `ID`=17790;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아타말 수정은 나의 것이다!', `MaleText_loc4`='阿塔玛水晶是我的！', `MaleText_loc5`='阿塔莫水晶是我的!', `MaleText_loc7`='¡El cristal de Ata''mal es mío!' WHERE `ID`=17791;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니, 내 생각은 좀 다르네. 이제야 사심이 사라졌군. 자네의 주인과 내 사이의 거래는 이제 끝일세. 자네의 주인에게 돌아가서 내가 아타말 수정을 나루에게 돌려주기로 결정했다고 전하게.', `MaleText_loc4`='不，我不觉得。刚才我所目睹的无私行为净化了我的心灵。我和你的主人之间的交易已经结束了。你可以回去告诉他，我已经准备把阿塔玛水晶交给纳鲁了。', `MaleText_loc5`='不，我不這麼認為。我剛目睹的無私已讓我的腦袋清醒。我和你主人的恩怨就到此結束。你可以回去讓他知道我已決定將阿塔莫水晶交給那魯了。', `MaleText_loc7`='No, no lo creo. El altruismo del que acabo de ser testigo me ha aclarado la mente. Mis tratos con tu maestro han terminado. Puedes volver y hacerle saber que he decidido entregar el cristal de Ata''mal a los naaru.' WHERE `ID`=17793;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐라고요? 말도 안 됩니다! 이 일에 대한 대가를 치르게 될 겁니다, 하라매드. 당신뿐만 아니라 여기 있는 당신 부하들 모두!', `MaleText_loc4`='什么！！这太可恶了！你和你的朋友会为此付出代价的，哈拉迈德！', `MaleText_loc5`='什麼!這真是無法無天!你會為此付出代價哈拉瑪德!你和你在這裡的助理一起!', `MaleText_loc7`='¡¿Qué?! ¡Esto es intolerable! ¡Pagarás por esto, Haramad! ¡Tú y tu insolente asistente!' WHERE `ID`=17794;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭풍 첨탑에 온 것을 환영하네, $c|1이여;여;.$B$B이 장치를 이용해 환영의 모습으로 대화할 수밖에 없는 상황을 이해하도록. 날 노리는 적이 한둘이 아니라서 어쩔 수 없이 내린 조치이니 말일세.$B$B단, 이곳만큼은 자네에게 절대 안전을 보장하네.', `MaleText_loc4`='欢迎来到风暴尖塔，$c。$B$B请不要因为我以影像的形式出现而感到厌恶。我的很多敌人都想让我死，所以这只是个防范措施。$B$B我保证你在这里会很安全的。', `MaleText_loc5`='歡迎來到風暴之尖，$c。$B$B請別被我透過這個影像儀器顯現的實體給嚇到了。有很多仇家想看到我死，所以這只是一個預防措施。$B$B我向你保證你在這裡很安全。', `MaleText_loc7`='$gBienvenido:Bienvenida; a la Flecha de la Tormenta, $c.$B$BQue no te disuada que esté presente a través de este dispositivo de imágenes. Tengo muchos enemigos a los que les gustaría verme muerto, así que es solo por precaución.$B$BTe aseguro que estás perfectamente $gseguro:segura; aquí.' WHERE `ID`=17795;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경비병! 기다려. 내가 금방 그리로 가겠다!', `MaleText_loc4`='卫兵们！守住，我马上就到了！', `MaleText_loc5`='守衛!等等，我馬上就過去!', `MaleText_loc7`='¡Guardias! ¡Espera, voy enseguida!' WHERE `ID`=17796;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 무역연합에서 캘타스 왕자와 진행하던 사업은 완전히 끝났네. 여기서 잠시만 기다리면 금방 돌아오겠네. 그리고 자네가 해야 할 일이 있네.', `MaleText_loc4`='这肯定会中断我们和凯尔萨斯之间的一切交易关系。请待在这里，我会很快回来，有些事情想让你去做。', `MaleText_loc5`='那必定會結束我們和凱爾薩斯的生意關係。請留在這裡。我很快就會回來，有件事我想請你去做。', `MaleText_loc7`='Esto ha terminado con nuestras relaciones comerciales con Kael''thas. Por favor, quédate aquí. Volveré pronto. Quiero que hagas algo por mí.' WHERE `ID`=17797;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제대로 돌아가게 해 주마, 이 쓰레기 같은 녀석.', `MaleText_loc4`='我会让你也开始工作的，你这个废物。', `MaleText_loc5`='總有一天我會讓你去幹活，你這個廢物。', `MaleText_loc7`='Te haré trabajar, cubo de basura.' WHERE `ID`=17798;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구입하려는 하시는 물건이 있거나 팔려고 하시는 물건이 있습니까?$B$B우리가 하는 일이 바로 그런 것이지요.$B$B자, 뭘 도와 드릴까요?', `MaleText_loc4`='你想买什么东西吗？还是想卖什么东西？$B$B这就是我们出现在这里的原因，我的朋友。$B$B请告诉我你的想法吧。', `MaleText_loc5`='你想買什麼東西嗎?還是你想賣什麼東西?$B$B這是為什麼我們會在這裡的原因，我的朋友。$B$B請告訴我你的意願。', `MaleText_loc7`='¿Hay algo que desees comprar? ¿Hay algo que desees vender?$B$BPor eso estamos aquí, $gamigo:amiga;.$B$BPor favor, dime qué deseas.' WHERE `ID`=17799;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='듀나르, 물건을 살펴보고 싶습니다.', `MaleText_loc4`='商人杜纳尔，我想看看你的货物。', `MaleText_loc5`='商人杜那爾，我想看看你的商品。', `MaleText_loc7`='Me gustaría echar un vistazo a tus mercancías.', `FemaleText_loc1`='듀나르, 물건을 살펴보고 싶습니다.', `FemaleText_loc4`='商人杜纳尔，我想看看你的货物。', `FemaleText_loc5`='商人杜那爾，我想看看你的商品。', `FemaleText_loc7`='Me gustaría echar un vistazo a tus mercancías.' WHERE `ID`=17800;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게 좀 이러지 말아달란 말이다!', `MaleText_loc4`='闭嘴！', `MaleText_loc5`='你別拿我開刀!', `MaleText_loc7`='¡No empieces conmigo!' WHERE `ID`=17801;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐라고?! 내가 못할 거라고? 똑똑히 봐 둬라. 내가 한번 일을 맡았다 하면 말이야...', `MaleText_loc4`='什么？！你不觉得我能成功吗？只要我拿到了我的零件……我会证明给你看的。', `MaleText_loc5`='什麼?!你認為我辦不到?我會證明給你看...不過是等我拿到我的零件以後。', `MaleText_loc7`='¡¿Qué?! ¿No crees que pueda hacerlo? Ya te enseñaré... en cuanto tenga mis partes, claro.' WHERE `ID`=17802;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 정말 재미있군그래. 그렇지 않나?', `MaleText_loc4`='哈哈，这真是太有趣了，不是吗？', `MaleText_loc5`='是啊，那真是有趣不是嗎?', `MaleText_loc7`='Ah, sí, es muy divertido, ¿verdad?' WHERE `ID`=17803;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='움직였다고! 맹세해. 분명 움직이는 걸 봤어!', `MaleText_loc4`='它动了！我发誓，我看到它动了！', `MaleText_loc5`='它動了!我發誓，我看到它動了!', `MaleText_loc7`='¡Se ha movido! ¡Lo juro, lo he visto moverse!' WHERE `ID`=17804;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아야! 이렇게 하는 게 아니군.', `MaleText_loc4`='哎唷！不对。', `MaleText_loc5`='喔!那是不對的。', `MaleText_loc7`='¡Ay! Eso no está bien.' WHERE `ID`=17805;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 최근에 아제로스에서 도착했다는 말인가? 수련을 단단히 한 모양이군. $c|1이여;여;, 이 땅에는 이전에 호드가 마주친 것들과는 다른 위험이 가득하다네. 나는 우리의 대족장이신 스랄 님의 오른팔인 나즈그렐이라고 하네. 대족장님께서는 내게 이 용감한 원정대를 지키라는 영광스러운 임무를 맡기셨지. 나는 어떤 일이 있어도 임무를 완수할 것이네!', `MaleText_loc4`='你是刚从艾泽拉斯世界到这边来的吧？你最好武装好自己，$c。这里的危险和部落之前所面对的大不一样。我是纳兹格雷尔——伟大的酋长萨尔的左右手。我很荣幸他让我负责保证这支勇敢的远征队的安全，以所有的灵魂之名，我会出色地完成任务！', `MaleText_loc5`='所以你是最近從艾澤拉斯來到這裡的?你最好讓自己下定決心，$c - 這土地上有著部落從未挑戰過的危險事物。我是納茲格雷爾 - 我們偉大酋長，索爾的得力助手。他賦予我護衛這次勇敢遠征的任務，所以 - 我以一切擔保 - 我會做到!', `MaleText_loc7`='Así que acabas de llegar de Azeroth, ¿eh? Será mejor que te armes de valor, $c – en esta tierra hay peligros como ninguno al que se haya enfrentado antes la Horda. Soy Nazgrel – la mano derecha de nuestro poderoso Jefe de Guerra, Thrall. Me honró con la tarea de salvaguardar a su valiente expedición y – por todos los espíritus – ¡lo haré!' WHERE `ID`=17806;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스랄마로 보내 주십시오!', `MaleText_loc4`='送我去萨尔玛！', `MaleText_loc5`='送我去索爾瑪!', `MaleText_loc7`='¡Mándame a Thrallmar!', `FemaleText_loc1`='스랄마로 보내 주세요!', `FemaleText_loc4`='送我去萨尔玛！', `FemaleText_loc5`='送我去索爾瑪!', `FemaleText_loc7`='¡Mándame a Thrallmar!' WHERE `ID`=17807;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='트롬카, $g형제:자매;여! 아웃랜드에 온 것을 환영하네. 호드는 이 척박한 땅에서 힘을 가진 자라면 누구라도 환영하네. 약속 하나 하지. 자네가 원하는 게 영광스러운 전투라면 이곳에서 얼마든지 경험할 수 있을 것일세.', `MaleText_loc4`='你好啊，我的$g兄弟:姐妹;！欢迎来到外域。部落需要聚集这块破碎的世界中一切可以聚集的力量。我保证，如果你是为荣耀之战而来，你必定会在这里得到满足。', `MaleText_loc5`='(獸人語)你好，$g兄弟:姐妹;!歡迎來到外域。部落需要這殘破世界裡所有能召集到的力量。我向你保證，如果你尋找的是光榮的戰役，你可以在這裡找到。', `MaleText_loc7`='¡Throm''ka, $ghermano:hermana;! $gBienvenido:Bienvenida; a Terrallende. La Horda necesita toda la fuerza que pueda reunir en este mundo destrozado. Te prometo que, si es una batalla gloriosa lo que andas buscando, aquí tendrás hasta hartarte.' WHERE `ID`=17808;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 서두르게. 이곳에서 전쟁이 벌어질 걸세. 혹여 자네 아직도 모르고 있었나?', `MaleText_loc4`='动作快点，$c。战斗已经在这里打响了，难道你还没注意到？', `MaleText_loc5`='動作快，$c - 我們在這裡有場仗要打，你沒注意到嗎?', `MaleText_loc7`='Hazlo rápido, $c – tenemos una guerra que librar aquí, ¿o no te habías dado cuenta?' WHERE `ID`=17809;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절대로 그들의 전투 기술을 얕잡아 봐서는 안 됩니다.', `MaleText_loc4`='永远都不要低估他们的战斗能力。', `MaleText_loc5`='永遠不能低估他們的戰鬥技巧。', `MaleText_loc7`='Su habilidad en la batalla nunca se debe subestimar.', `FemaleText_loc1`='절대로 그들의 전투 기술을 얕잡아 봐서는 안 됩니다.', `FemaleText_loc4`='永远都不要低估他们的战斗能力。', `FemaleText_loc5`='永遠不能低估他們的戰鬥技巧。', `FemaleText_loc7`='Su habilidad en la batalla nunca se debe subestimar.' WHERE `ID`=17810;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들은 고통을 주는 것을 즐깁니다. 그들의 끔찍한 고문 수법은 악몽과도 같습니다.', `MaleText_loc4`='她们的乐趣就是给别人造成痛苦，她们致人于死地的审问方式是非常可怕的。', `MaleText_loc5`='他們沉迷於製造痛苦 - 而他們殘忍的訊問就是可怕的夢魘。', `MaleText_loc7`='Se recrean provocando miedo y dolor. Sus sangrientos interrogatorios son la cualidad de las pesadillas.', `FemaleText_loc1`='그들은 고통을 주는 것을 즐깁니다. 그들의 끔찍한 고문 수법은 악몽과도 같습니다.', `FemaleText_loc4`='她们的乐趣就是给别人造成痛苦，她们致人于死地的审问方式是非常可怕的。', `FemaleText_loc5`='他們沉迷於製造痛苦 - 而他們殘忍的訊問就是可怕的夢魘。', `FemaleText_loc7`='Se recrean provocando miedo y dolor. Sus sangrientos interrogatorios son la cualidad de las pesadillas.' WHERE `ID`=17811;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들은 불타는 성전의 휘몰아치는 힘입니다.', `MaleText_loc4`='这些恶魔是燃烧军团远征中的驱动力量。', `MaleText_loc5`='他們是燃燒十字軍的操作中心。', `MaleText_loc7`='Son el corazón de la Cruzada Ardiente.', `FemaleText_loc1`='그들은 불타는 성전의 휘몰아치는 힘입니다.', `FemaleText_loc4`='这些恶魔是燃烧军团远征中的驱动力量。', `FemaleText_loc5`='他們是燃燒十字軍的操作中心。', `FemaleText_loc7`='Son el corazón de la Cruzada Ardiente.' WHERE `ID`=17812;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들은 공포와 속임수를 사용합니다. 전 세계가 그들의 어둠의 세력 앞에 무릎을 꿇자 형제와 다투는 일도 종종 생기고 있습니다.', `MaleText_loc4`='他们利用恐怖和诡计让兄弟之间互相残杀，以他们的黑暗力量毁灭诸界。', `MaleText_loc5`='他們利用恐怖行動和藉口 - 常讓兄弟反目，整個世界因他們黑暗的力量而崩塌。', `MaleText_loc7`='Utilizan el terror y el subterfugio – a menudo poniendo a hermanos en contra mientras el mundo entero cae ante su oscura influencia.', `FemaleText_loc1`='그들은 공포와 속임수를 사용합니다. 전 세계가 그들의 어둠의 세력 앞에 무릎을 꿇자 형제와 다투는 일도 종종 생기고 있습니다.', `FemaleText_loc4`='他们利用恐怖和诡计让兄弟之间互相残杀，以他们的黑暗力量毁灭诸界。', `FemaleText_loc5`='他們利用恐怖行動和藉口 - 常讓兄弟反目，整個世界因他們黑暗的力量而崩塌。', `FemaleText_loc7`='Utilizan el terror y el subterfugio – a menudo poniendo a hermanos en contra mientras el mundo entero cae ante su oscura influencia.' WHERE `ID`=17813;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만! 더 멀리 가지 마시오, 필멸의 존재여. 무한의 용군단에 맞서기에는 아직 준비가 부족하오. 이리 오시오. 내가 돕겠소이다.', `MaleText_loc4`='停下！不要再往前走了，凡人。你还没有做好面对永恒之龙的准备。过来，让我帮帮你。', `MaleText_loc5`='停!別再走了，凡人。你尚未準備好挑戰恆龍軍團。來吧，讓我幫你。', `MaleText_loc7`='¡Detente! No avances más, mortal. Estás mal $gpreparado:preparada; para enfrentarte a las fuerzas del Vuelo Infinito. Vamos, déjame ayudarte.' WHERE `ID`=17814;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='본성이 사악한 그들은 자신들이 급조한 기술을 사용하는 것을 좋아합니다.', `MaleText_loc4`='由于与生俱来的玩世不恭，他们喜欢使用自己那不成熟的科技手段。', `MaleText_loc5`='他們天性邪惡，喜歡利用他們自己倉促創造魔像的技術。', `MaleText_loc7`='Traviesos por naturaleza, les encanta emplear sus propias tecnologías, construidas apresuradamente.', `FemaleText_loc1`='본성이 사악한 그들은 자신들의 급조한 기술을 사용하는 것을 좋아합니다.', `FemaleText_loc4`='由于与生俱来的玩世不恭，他们喜欢使用自己那不成熟的科技手段。', `FemaleText_loc5`='他們天性邪惡，喜歡利用他們自己倉促創造魔像的技術。', `FemaleText_loc7`='Traviesos por naturaleza, les encanta emplear sus propias tecnologías, construidas apresuradamente.' WHERE `ID`=17815;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 작은 소리로 중얼거리더니 다시 일을 하러 갑니다.', `MaleText_loc4`='%s嘀咕着回去工作了。', `MaleText_loc5`='%s在嘴裡咕噥著，回到工作崗位上。', `MaleText_loc7`='Farfullando para sí, %s vuelve al trabajo.' WHERE `ID`=17816;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들의 검은색 강철 구조물은 천 개의 세계에 걸쳐 죽음의 바람을 불러 왔습니다.', `MaleText_loc4`='他们所制造的黑色机械在无数世界中播种了死亡。', `MaleText_loc5`='他們的黑鐵傀儡將死亡散播到大千世界。', `MaleText_loc7`='Sus ensamblajes de hierro bruno han sembrado la muerte a través de mil mundos.', `FemaleText_loc1`='그들의 검은색 강철 구조물은 천 개의 세계에 걸쳐 죽음의 바람을 불러 왔습니다.', `FemaleText_loc4`='他们所制造的黑色机械在无数世界中播种了死亡。', `FemaleText_loc5`='他們的黑鐵傀儡將死亡散播到大千世界。', `FemaleText_loc7`='Sus ensamblajes de hierro bruno han sembrado la muerte a través de mil mundos.' WHERE `ID`=17817;
