UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사트, 시간의 봉화를 잃어버렸는데 새로 하나 주시겠습니까?', `MaleText_loc4`='萨艾特，我遗失了我的时空道标，请再给我一个！', `MaleText_loc5`='塞特，我弄丟了時間信號燈需要另一個!', `MaleText_loc7`='¡Sa''at, he perdido la cronobengala y necesito otra!', `FemaleText_loc1`='사트, 시간의 봉화를 잃어버렸는데 새로 하나 주시겠어요?', `FemaleText_loc4`='萨艾特，我遗失了我的时空道标，请再给我一个！', `FemaleText_loc5`='塞特，我弄丟了時間信號燈需要另一個!', `FemaleText_loc7`='¡Sa''at, he perdido la cronobengala y necesito otra!' WHERE `ID`=17879;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 돌아온 것을 환영하오, 영웅이여. 다시 한 번 수호자를 지키기 위해 돌아온 것이오? 시간의 봉화를 가져가는 걸 잊지 마시오!', `MaleText_loc4`='啊，欢迎回来，英雄。你是再次回来保护麦迪文的吗？不要忘记带上一个时空道标！', `MaleText_loc5`='啊，歡迎回來，英雄。你再次回來保護守衛者嗎?別忘記帶一個時間信號燈在身上!', `MaleText_loc7`='Ah, bienvenido de nuevo, héroe. ¿Has vuelto para volver a proteger al Guardián? ¡No olvides llevarte una cronobengala contigo!' WHERE `ID`=17880;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간의 봉화가 필요합니다, 사트.', `MaleText_loc4`='我需要一个时空道标，萨艾特。', `MaleText_loc5`='我需要一個時間信號燈，塞特。', `MaleText_loc7`='Necesito una cronobengala, Sa''at.', `FemaleText_loc1`='시간의 봉화가 필요합니다, 사트.', `FemaleText_loc4`='我需要一个时空道标，萨艾特。', `FemaleText_loc5`='我需要一個時間信號燈，塞特。', `FemaleText_loc7`='Necesito una cronobengala, Sa''at.' WHERE `ID`=17881;
