UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경고! %s 긴급 차단 시스템이 가동되었습니다. 1분 후에 차단이 실시됩니다.', `MaleText_loc4`='警告！%s紧急停机准备开始。将在一分钟后停机。', `MaleText_loc5`='警告!%s緊急關閉程序已開始。關閉將在一分鐘後完成。', `MaleText_loc7`='¡Aviso! El proceso de cierre de emergencia de %s ha comenzado. El cierre se completará en un minuto.' WHERE `ID`=17883;
