UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그 멍청한 엘프가 돌아왔을 때만 날 소환하라고 했다! 이게 무슨 짓이지? 어쨌거나 넌 나를 오래 붙잡고 있지 못한다.', `FemaleText_loc4`='我告诉过你，那个愚蠢的精灵回来时再召唤我！这是怎么回事？不管怎样，你都不会占用我太多时间了……', `FemaleText_loc5`='我跟你說過只有在那個愚蠢的精靈回來時才能召喚我!這是怎麼回事?無所謂，反正你也不能扣留我多久了。', `FemaleText_loc7`='¡Te dije que me invocaras solo si volvía ese estúpido elfo! ¿Qué es esto? No importa, no me retendrás por mucho tiempo.' WHERE `ID`=17887;
