UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난... 죽어 마땅하다...', `MaleText_loc4`='我……罪有应得……', `MaleText_loc5`='這是我...應得的...', `MaleText_loc7`='Me... lo merezco...' WHERE `ID`=17894;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에서 우리가 할 일에 대해 좀 더 자세히 알려주십시오, 나즈그렐.', `MaleText_loc4`='纳兹格雷尔，向我多介绍一些这里的任务。', `MaleText_loc5`='跟我多說些我們在這裡的任務，納茲格雷爾。', `MaleText_loc7`='Cuéntame más sobre nuestra misión aquí, Nazgrel.', `FemaleText_loc1`='이곳에서 우리가 할 일에 대해 좀 더 자세히 알려주십시오, 나즈그렐.', `FemaleText_loc4`='纳兹格雷尔，向我多介绍一些这里的任务。', `FemaleText_loc5`='跟我多說些我們在這裡的任務，納茲格雷爾。', `FemaleText_loc7`='Cuéntame más sobre nuestra misión aquí, Nazgrel.' WHERE `ID`=17895;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장님께서는 어둠의 문이 다시 열렸다는 소식을 듣자마자 조언자들을 불러모아 이 용감한 원정대를 조직하셨다네. 몇몇 의원들이 의문을 표하기도 했지만 스랄께서는 우리 종족의 역사를 밝힐 수 있다는 희망을 버리지 않으셨네. 스랄께서는 파괴된 이 세계 어딘가에 오크족에 대한 진실이 숨겨져 있을 거라 믿고 계시네.$B$B나 역시 가장 암울하던 시기에는... 오크족에 대한 진실이 밝혀지지 않으면 어쩌나 걱정을 했었다네.', `MaleText_loc4`='当我们的酋长听说黑暗之门被重新打开之后，他马上召集了他的顾问来计划这次远征。尽管少数几个顾问还抱有怀疑态度，但萨尔坚信我们能开拓新的视野，并将其写入我们的历史。他相信在这个充满灾难的世界的某处隐藏着兽人真正的传说。$B$B我必须要承认，在我内心最黑暗的时候，我曾为那传说不能昭告世人而感到恐慌。', `MaleText_loc5`='一旦我們的大酋長知道黑暗之門被重新開啟，他就會立即召集他的顧問來計畫這個大膽的遠征。雖然有些顧問有所懷疑，但索爾堅信我們可能會對族人的歷史有新的洞悉。他相信這世界的殘骸中某處，就藏著獸人真正的故事。$B$B我必須承認在我最壞的打算中...我擔心那個故事最好不要被人知道。', `MaleText_loc7`='Cuando nuestro Jefe de Guerra oyó que el Portal Oscuro se había vuelto a abrir, reunió de inmediato a sus consejeros para planear esta osada expedición. Aunque varios de sus concejales tienen sus dudas, Thrall mantiene la esperanza de que podríamos descubrir cosas nuevas sobre la historia de nuestro pueblo. Cree que, en algún lugar en medio de las ruinas de este mundo, se encuentra escondida la auténtica historia del pueblo orco.$B$BDebo admitir que en mis momentos más oscuros... temo que la historia debería permanecer sin contar.' WHERE `ID`=17896;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<계속 듣기>', `MaleText_loc4`='<继续听下去。>', `MaleText_loc5`='<繼續聆聽>', `MaleText_loc7`='<Seguir escuchando>', `FemaleText_loc1`='<계속 듣기>', `FemaleText_loc4`='<继续听下去。>', `FemaleText_loc5`='<繼續聆聽>', `FemaleText_loc7`='<Escucha>' WHERE `ID`=17897;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드는 많은 위험을 무릅쓰고 아웃랜드로 건너왔네. 자원, 인력, 심지어 우리 땅의 전략적 방어선조차 위태로운 상황이네. 이런 악조건에도 불구하고 스랄께서는 이 황량한 땅의 약속을 믿고 계시다네. 요즘 스랄 님의 눈에서 이상한 광채가 보이네. 마치 우리 눈에는 보이지 않는 어떤 놀라운 사실을 발견하기라도 하신 듯 말일세.$B$B하지만 그분은 여전히 대족장이며 내 형제라네. 나는 지옥 끝까지라도 그분을 따를 것이네.', `MaleText_loc4`='部落对外域的探索太过冒险了——资源、人力，甚至是我们对本土的防御都已经很危险了。但是，萨尔相信可以在这个满目疮痍的世界中找到部落的命运归宿。这几天我们从他的眼里看到了奇怪的光芒——好像他感觉到了什么激动人心的新发现，但是我们对此一无所知。$B$B不管怎样，他是我的酋长和结拜兄弟。我愿意追随他，直到深渊之门。', `MaleText_loc5`='部落冒了很多險才進入外域 - 資源，人力 - 就連我們土地的策略防禦都很危急。撇開這一切，索爾相信這荒蕪土地仍有前途。這些日子他眼裡有一種奇怪的光芒 - 好像他感覺到什麼我們不懂的天啟。$B$B不過，他仍是我的大酋長和我的兄弟。我會跟隨他通過深淵的大門。', `MaleText_loc7`='La Horda ha arriesgado mucho para aventurarse en Terrallende - recursos, mano de obra – incluso la defensa táctica de nuestras tierras está en juego. A pesar de todo, Thrall cree en la promesa de esta tierra devastada. Hay una luz extraña en sus ojos estos días – como si sintiera alguna revelación conmovedora que los demás no sentimos.$B$BCon todo, es mi Jefe de Guerra y mi hermano de sangre. Lo seguiría a través de las mismas puertas del abismo.' WHERE `ID`=17898;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='트롬카, $c|1이여;여;. 풋내기로군. 기운이 넘치는 걸 보니, 이 땅의 공포를 맛보지 못한 모양이지?$B$B<땅에 침을 뱉는 하사관 쉐터스컬>$B$B곧 모든 게 변할 걸세.', `MaleText_loc4`='你好啊，$c。你肯定是新来的，你看上去冒冒失失的，好像对这块恐怖的土地一无所知。$B$B<斯古尔·碎颅者中士对着地上吐了口口水。>$B$B早晚你会改变的。', `MaleText_loc5`='(獸人語)你好，$c。你一定是新人。你看起來充滿朝氣，尚未被這片土地的恐怖之處所蹂躪。$B$B<碎顱中士朝塵土裡吐了口口水。>$B$B那將會改變的。', `MaleText_loc7`='Throm''ka, $c. Debes de ser $gnuevo:nueva;. Pareces joven y no tienes aspecto de haber vivido los horrores de estas tierras.$B$B<El sargento Trizacráneo escupe en el suelo>$B$BEso va a cambiar.' WHERE `ID`=17899;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='긴급 차단이 완료되었습니다.', `MaleText_loc4`='紧急停机已完成。', `MaleText_loc5`='緊急停工完成。', `MaleText_loc7`='Apagado de emergencia completado.' WHERE `ID`=17900;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 원정대는 차원문을 안전하게 지나서 스랄마라 불리는 새로운 기지를 건설했네. 보다시피 불타는 군단은 우리의 방어선을 뚫고 우리를 우리 형제들로부터 격리시키려 하고 있네. 악마들은 분명 어둠의 문을 다시 차지하고 아제로스로부터 오는 지원군을 차단하려는 것일 게야.', `MaleText_loc4`='我们的远征军已经安全地穿越了黑暗之门，建立起了一座名为萨尔玛的新基地。就像你看到的那样，燃烧军团切断了我们和兄弟们之间的联系。很明显，那些恶魔希望能重新夺回黑暗之门，阻止我们从艾泽拉斯得到更多的增援。', `MaleText_loc5`='我們的遠征隊安全地通過了傳送門並建立了一個叫索爾瑪的新基地。但如你所見，燃燒軍團進入，切斷了我們和兄弟的連繫。明顯地，那些惡魔想奪回黑暗之門，阻止我們從艾澤拉斯召集援軍。', `MaleText_loc7`='Nuestra expedición logró cruzar el Portal sin incidentes y estableció una nueva base llamada Thrallmar. Pero, como puedes ver, la Legión Ardiente se instaló y nos aisló de nuestros hermanos. Claramente, los demonios esperan retomar el Portal Oscuro y evitar que reunamos refuerzos de Azeroth.' WHERE `ID`=17901;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 군대는 얼라이언스의 도움을 받아 여기에 진을 칠 것이니 자네가 스랄마에 계시는 사령관 크라콜크 님께 내 보고서를 전달해 주게. 그분의 도움을 받으면 이 악마들이 맨 처음 나온 심연으로 쫓아낼 수 있을 것이네! 우리 뒤쪽의 단상에 서 있는 블라가 프레이페더와 얘기해 보게. 자네가 좀 더 빨리 스랄마로 갈 수 있도록 도와줄 걸세.', `MaleText_loc4`='有了联盟的帮助，我的部队会守住这条阵线，但是我需要你帮我送一份报告给萨尔玛的克拉库克将军。有了他的帮助，我们就能把这些恶魔送回到他们的深渊去！去和我们身后平台上的维拉加·乱羽聊聊吧，她会给你一些必要的指引。', `MaleText_loc5`='有聯盟的幫助，我的軍隊就能守住這裡的戰線，但我需要你幫我把報告送給索爾瑪的克洛克爾克將軍。有他的幫忙，我們就能把這些惡魔趕回他們出生的深淵!和法拉格·伏瑞菲德談談，她就在我們後面的平臺上站著。她很快就會讓你上路的。', `MaleText_loc7`='Con la ayuda de la Alianza, mis tropas seguirán defendiendo sin ceder, pero necesito que le entregues mi informe al general Krakork de Thrallmar. ¡Con su ayuda, podremos devolver a esos demonios al abismo que los engendró! Habla to Vlagga Plumacalma, que está sobre la plataforma que se encuentra detrás de nosotros. Ella te pondrá en marcha.' WHERE `ID`=17902;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 많이...', `MaleText_loc4`='更多', `MaleText_loc5`='更多', `MaleText_loc7`='más', `FemaleText_loc1`='더 많이...', `FemaleText_loc4`='更多', `FemaleText_loc5`='更多', `FemaleText_loc7`='más' WHERE `ID`=17903;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조금만 도와주면 태릭스가 성공할 수 있을 거라 믿습니다.', `MaleText_loc4`='有了援助，我相信塔蕾克丝就快要有所突破了。', `MaleText_loc5`='有人幫忙的話，我相信泰瑞茲很快就能突破了。', `MaleText_loc7`='Creo que, con algo de ayuda, Taerix puede estar cerca de un avance.' WHERE `ID`=17904;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드에 있는 형제들이 말하길 군대에는 절대 가지 말라고 그랬지... 그 말을 듣지 않길 잘한 것 같소!', `MaleText_loc4`='暴风城的兄弟们告诉我不要参军……我很高兴当初没有听他们的！', `MaleText_loc5`='我的兄弟在暴風城告訴我不要加入軍隊...我很高興，我沒有聽他的話!', `MaleText_loc7`='Mis hermanos de Ventormenta me dijeron que no me uniera al ejército... ¡me alegro de no haberlos escuchado!' WHERE `ID`=17905;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='징검다리 거점은 저 같은 와일드해머 드워프를 위한 멋진 곳이지요. 공중에서 이렇게 오랜 시간을 있어본 적이 없어서 말입니다!', `MaleText_loc4`='破碎岗哨很适合蛮锤矮人，我从来没在空中逗留过这么久！', `MaleText_loc5`='對蠻錘矮人而言，破碎崗哨是個很棒的地方。我沒有多少時間可以在天空中飛翔了!', `MaleText_loc7`='El Puesto Devastación es un gran lugar para un enano Martillo Salvaje. ¡Nunca he pasado tanto tiempo en el aire!', `FemaleText_loc1`='징검다리 거점은 저 같은 와일드해머 드워프를 위한 멋진 곳이지요. 공중에서 이렇게 오랜 시간을 있어본 적이 없어서 말입니다!', `FemaleText_loc4`='破碎岗哨很适合蛮锤矮人，我从来没在空中逗留过这么久！', `FemaleText_loc5`='對蠻錘矮人而言，破碎崗哨是個很棒的地方。我沒有多少時間可以在天空中飛翔了!', `FemaleText_loc7`='El Puesto Devastación es un gran lugar para un enano Martillo Salvaje. ¡Nunca he pasado tanto tiempo en el aire!' WHERE `ID`=17906;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='매타조는 고귀한 생물입니다. 언제나 성심을 다해 다뤄야 합니다. 화난 매타조보다 위험한 것도 없으니 말입니다.', `FemaleText_loc4`='陆行鸟是种高贵的生物。你要好好对待你的陆行鸟，没有什么比一只愤怒的陆行鸟更危险了。', `FemaleText_loc5`='陸行鷹是高貴的生物。記得永遠都要對你的陸行鷹很好;很少比憤怒的陸行鷹更危險的了。', `FemaleText_loc7`='Los halcones zancudos son criaturas nobles. Trata bien al tuyo; hay pocas cosas más peligrosas que un halcón zancudo enfadado.' WHERE `ID`=17907;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리가 도와주면 식물학자 태릭스가 우리 문제의 해결 방법을 찾을 수 있을 거라 확신합니다.', `FemaleText_loc4`='我确信有了我们的帮助，植物学家塔蕾克丝必定可以帮我们找到解决问题的办法。', `FemaleText_loc5`='我相信，有我們的幫忙，植物學家泰瑞茲就可以找到解決我們問題的方法。', `FemaleText_loc7`='Estoy segura de que, con tu ayuda, la botánica Taerix podrá hallar soluciones a nuestros problemas.' WHERE `ID`=17908;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 짐승들 중 한 마리를 구입하고 싶습니다.', `MaleText_loc4`='我想要购买一只小动物。', `MaleText_loc5`='我想購買這些生物中的一個。', `MaleText_loc7`='Quiero comprar una de esas criaturas.', `FemaleText_loc1`='이 짐승들 중 한 마리를 구입하고 싶어요.', `FemaleText_loc4`='我想要购买一只小动物。', `FemaleText_loc5`='我想購買這些生物中的一個。', `FemaleText_loc7`='Quiero comprar una de esas criaturas.' WHERE `ID`=17909;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조준!', `MaleText_loc4`='瞄准！', `MaleText_loc5`='瞄準!', `MaleText_loc7`='¡Apunten!' WHERE `ID`=17910;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발사!', `MaleText_loc4`='放！', `MaleText_loc5`='射擊!', `MaleText_loc7`='¡Fuego!' WHERE `ID`=17911;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='중화제를 호수에 섞자 수정에 오염된 물이 깨끗해지는 것 같습니다.', `MaleText_loc4`='随着中和剂与湖水混合起来，被水晶映射的湖面开始变得清澈了。', `MaleText_loc5`='當中和劑混和在湖水裡，被水晶輻射的水看起來變的清澈了。', `MaleText_loc7`='Al mezclar el agente neutralizador con las aguas del lago, parece que recuperan su color.' WHERE `ID`=17912;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일이 있어도 메카나르를 지켜야 한다!', `MaleText_loc4`='不惜一切代价保卫能源舰！', `MaleText_loc5`='不惜任何代價保護麥克納爾!', `MaleText_loc7`='¡Proteged el Mechanar a toda costa!' WHERE `ID`=17913;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 물론 훔친 물건은 하나도 없습니다. 하지만 누가 묻거든 당신은 저한테 물건을 산 적이 없다고 하시면 됩니다!', `MaleText_loc4`='当然我的货物都安然无恙。若是有人问起来，你可不要说是从我这里弄来的！', `MaleText_loc5`='我的貨品當然沒有一個是偷出來的。但如果有人問起，別說你是跟我買的!', `MaleText_loc7`='Por supuesto, ninguno de mis artículos es robado. Pero, si alguien te pregunta, ¡no los has obtenido de mí!' WHERE `ID`=17914;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최신 설계도, 도안, 설명서 등이 모두 이곳에 있습니다. 따라하기 아주 쉽게 설명되어 있어서 직접 제작도 가능하답니다!', `MaleText_loc4`='你可以在这里获得最新的蓝图、设计图和结构图。这些说明很好理解，只要按照说明书一步一步做就可以了。', `MaleText_loc5`='最新的藍圖，圖樣和結構圖都在這裡。這些操作說明簡單到它們幾乎自己就可以製作出來!', `MaleText_loc7`='Las últimas copias de planos, patrones y esquemas están disponibles justo aquí. ¡Estas instrucciones son tan fáciles de seguir que prácticamente se construyen solos!' WHERE `ID`=17915;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밀수품 중 최상품은 바로 여기에 모여 있습니다, $n. 누이 좋고 매부 좋은 일이죠! 고블린의 세금과 나루의 금지령을 피할 수 있는 물건들입니다. 저희 무역연합은 당신이 필요한 모든 물건을 언제나 공급해 드리고 있습니다!', `MaleText_loc4`='最上乘的走私货就在这里，$n。我的货物都是居家旅行杀人灭口的好东西。避开了地精的税收和纳鲁的禁令——星界财团会满足你方方面面的购物需求！', `MaleText_loc5`='最棒的走私品精選就在這裡，$n。男女老少都適合!躲過哥布林的課稅和那魯的禁令 - 聯合團在這裡滿足你所有的購物需求!', `MaleText_loc7`='La mejor selección de artículos de contrabando está disponible justo aquí, $n. ¡Genial para toda la familia! Evita los impuestos de los goblins y las prohibiciones naaru – ¡el Consorcio está aquí para cubrir todas tus necesidades de compra!' WHERE `ID`=17916;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쉿! 당신이 관심을 가질만한 물건이 있습니다, $n. 나그란드의 짐노새가 떨어뜨린 물건이랍니다!', `MaleText_loc4`='喂！我这里的东西你肯定会感兴趣的，$n。它在纳格兰弄翻了一头骡子。', `MaleText_loc5`='嘿!我有個東西你可能會有興趣，$n。從納葛蘭的運貨馱騾身上掉下來的!', `MaleText_loc7`='¡Pssst! Tengo algo que podría interesarte, $n. ¡Se cayó de una mula de carga en Nagrand!' WHERE `ID`=17917;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='와, 여기서 태양샘이 보일 것 같아요!', `FemaleText_loc4`='我想我可以在这里看到太阳之井！', `FemaleText_loc5`='我想我從這裡可以看見太陽之井!', `FemaleText_loc7`='¡Me parece que desde aquí se ve La Fuente del Sol!' WHERE `ID`=17918;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말 이 조개껍데기 속에서 파도 소리가 들릴까?', `FemaleText_loc4`='你真的能从这些海螺里面听到大海的声音吗？', `FemaleText_loc5`='你真的可以從這些貝殼裡聽到海洋的聲音嗎?', `FemaleText_loc7`='¿De verdad se oye el mar dentro de estas caracolas?' WHERE `ID`=17919;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='와! 이것 좀 봐! 빛나는 조개껍데기잖아!', `FemaleText_loc4`='喔！看，这个好亮啊！', `FemaleText_loc5`='喔!看，這個是閃亮的!', `FemaleText_loc7`='¡Oooh! ¡Mira cómo brilla!' WHERE `ID`=17920;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제인이 보면 좋아할 거야!', `FemaleText_loc4`='杰恩会喜欢这个的！', `FemaleText_loc5`='珍恩會很愛這個的!', `FemaleText_loc7`='¡A Jane le va encantar esta!' WHERE `ID`=17921;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 조개껍데기를 주워듭니다.', `FemaleText_loc4`='%s捡起一只海螺。', `FemaleText_loc5`='%s撿起一個海貝殼。', `FemaleText_loc7`='%s coge una concha marina.' WHERE `ID`=17922;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 조개껍데기를 귀에 가져다 댑니다.', `FemaleText_loc4`='%s把海螺放到她的耳边。', `FemaleText_loc5`='%s把一個海貝殼拿到她耳朵旁。', `FemaleText_loc7`='%s se acerca la caracola al oído.' WHERE `ID`=17923;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 조개껍데기에서 흙을 털어냅니다.', `FemaleText_loc4`='%s掸落了海螺上的泥沙。', `FemaleText_loc5`='%s把殼上的泥土甩掉。', `FemaleText_loc7`='%s sacude la suciedad de la concha.' WHERE `ID`=17924;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너를 철창에서 꺼내 줄 시간이 된 것 같구나.', `MaleText_loc4`='看上去该把你从笼子里放出来了。', `MaleText_loc5`='看來是時候把你從籠子裡放出來了。', `MaleText_loc7`='Me parece que es el momento de dejarte salir de esta jaula.' WHERE `ID`=17925;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 눈물을 닦아냅니다.', `FemaleText_loc4`='%s擦去了眼泪。', `FemaleText_loc5`='%s擦去眼淚。', `FemaleText_loc7`='%s se seca una lágrima.' WHERE `ID`=17926;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고엘. 너는 서리늑대 부족의 족장인 듀로탄의 아들 고엘이란다. 손자야, 이제 너는 내가 살아가는 가장 큰 즐거움이로구나.', `FemaleText_loc4`='古伊尔。你是古伊尔，杜隆坦之子——真正的霜狼氏族的酋长。今天，我的孙儿——你是我心中最大的欢乐。', `FemaleText_loc5`='高爾。你是高爾，杜洛坦之子 - 霜狼的合法酋長。今天，孫子 - 你是我心中最大的喜悅。', `FemaleText_loc7`='Go''el. Eres Go''el, hijo de Durotan, jefe legítimo de los Lobo Gélido. Este día, nieto, eres la gran alegría de mi corazón.' WHERE `ID`=17927;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='평생, 이 순간을 꿈꿔 왔습니다, 대모님. 지금까지 제가 부모님에 대해 들은 것이라고는 부모님과 일행들이 드레노어에서 겪은 일화에 대해 오그림님께 들은 것이 전부였답니다. 그분께선 저에게 가장 훌륭한 스승이자 가장 친한 친구셨지요. 그분은 영웅에게 어울리는 최후를 맞이하셨습니다... 그분들은 모두 영웅으로서 전사하셨으며 그들을 위한 명예의 노래가 남아 있답니다.', `MaleText_loc4`='我一直梦到这个场景，祖母。奥格瑞姆跟我说过很多关于他们的故事和他们在德拉诺的冒险经历。他是我最好的老师和最亲密的朋友，祖母。他像个英雄般地死去了……他们都像英雄般地死去了，荣耀的战歌为他们奏响。', `MaleText_loc5`='我畢生都夢想著這一刻，主母。一直到現在，我所擁有的就只有關於我父母和他們在德拉諾冒險的故事。他是我最好的良師益友。他是個陣亡的英雄...他們全都英勇的死去 - 而他們所有人，都留下了一首光榮的詩歌。', `MaleText_loc7`='He soñado con este momento toda mi vida, abuela. Hasta ahora, todo lo que he tenido eran las historias de Orgrim sobre mis padres y sus aventuras en Draenor. Fue mi mejor maestro y mi amigo más querido. Murió como un héroe... Todos murieron como héroes – y, para todos ellos, permanece una canción de honor.' WHERE `ID`=17928;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='손자야, 네가 둠해머를 지니고 있구나. 우리의 위대한 영웅들이 모두 쓰러진 것이냐?', `FemaleText_loc4`='我看到你拿着毁灭之锤。我们伟大的英雄们都倒下了吗，孙子？', `FemaleText_loc5`='我看見你拿著末日錘。我們所有最棒的英雄都陣亡了嗎，孫子?', `FemaleText_loc7`='Veo que tienes el Martillo Maldito. ¿Han caído todos nuestros grandes héroes, nieto?' WHERE `ID`=17929;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그롬마쉬 헬스크림은 어떻게 됐느냐?', `FemaleText_loc4`='格罗玛什怎么了？地狱咆哮怎么了？', `FemaleText_loc5`='葛羅瑪許怎麼樣?地獄吼怎麼樣?', `FemaleText_loc7`='¿Qué hay de Grommash? ¿Qué hay de Grito Infernal?' WHERE `ID`=17930;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='긴급 차단을 막아야 한다! 캘타스 님께서 이 일을 알게 되시면 우릴 가만두지 않으실 것이다!', `MaleText_loc4`='中断紧急停机！凯尔萨斯大人若是知道了，我们必定人头不保！', `MaleText_loc5`='阻止緊急停工!凱爾知道了會讓我們人頭落地的!', `MaleText_loc7`='¡Detened el cierre de emergencia! ¡Kael nos cortará la cabeza si se entera de esto!', `FemaleText_loc1`='긴급 차단을 막아야 한다! 캘타스 님께서 이 일을 알게 되시면 우릴 가만두지 않으실 것이다!', `FemaleText_loc4`='中断紧急停机！凯尔萨斯大人若是知道了，我们必定人头不保！', `FemaleText_loc5`='阻止緊急停工!凱爾知道了會讓我們人頭落地的!', `FemaleText_loc7`='¡Detened el cierre de emergencia! ¡Kael nos cortará la cabeza si se entera de esto!' WHERE `ID`=17931;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나루의 긴급 차단 시스템이 가동되면 마나괴철로를 영원히 쓸 수 없게 된다. 그러니 반드시 취소해야 한다!', `MaleText_loc4`='纳鲁的紧急停机程序会让法力熔炉永久停止运转的！必须阻止它！', `MaleText_loc5`='那魯的緊急停工會讓法力熔爐永遠癱瘓!一定要阻止它!', `MaleText_loc7`='¡El apagado de emergencia de los naaru inhabilitará la forja de maná permanentemente! ¡Hay que evitarlo!', `FemaleText_loc1`='나루의 긴급 차단 시스템이 가동되면 마나괴철로를 영원히 쓸 수 없게 된다. 그러니 반드시 취소해야 한다!', `FemaleText_loc4`='纳鲁的紧急停机程序会让法力熔炉永久停止运转的！必须阻止它！', `FemaleText_loc5`='那魯的緊急停工會讓法力熔爐永遠癱瘓!一定要阻止它!', `FemaleText_loc7`='¡El apagado de emergencia de los naaru inhabilitará la forja de maná permanentemente! ¡Hay que evitarlo!' WHERE `ID`=17932;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아웃랜드로 가시는 길인가요? 그렇다면 52번 구역에 있는 빅스톤 핀치휘슬에게 가 보십시오. 그는 스팀휘들 결투 대회의 공식 투기장 사무관으로서, 투기장 점수가 높은 이들에게 온갖 종류의 좋은 물건을 팔고 있다더군요.', `FemaleText_loc4`='去外域？记得拜访一下虚空风暴52区的维克斯顿。他是热砂搏击会的官方竞技场商人，他那里有许多不可思议的物品，专门卖给那些有着足够竞技场点数的家伙。', `FemaleText_loc5`='前往外域?去虛空風暴的52區拜訪維斯頓·急嘯。身為熱砂戰鬥同盟的官方競技場商人，他販賣各種不可思議的物品給有足夠競技場點數的人。', `FemaleText_loc7`='¿Te diriges a Terrallende? Visita a Vixton Silbapellizco en el Área 52 de Tormenta Abisal. Como vendedor oficial de la arena del circuito de lucha de Bonvapor, tiene todo tipo de artículos increíbles para aquellos que dispongan de suficientes puntos de Arena.' WHERE `ID`=17933;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 이제 중화제를 뿌려 주면...', `MaleText_loc4`='现在，把中和剂放上去……', `MaleText_loc5`='現在，把中和劑放上去...', `MaleText_loc7`='Ahora, para ponerle el agente neutralizador...' WHERE `ID`=17934;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='징검다리 거점으로 보내 주십시오!', `MaleText_loc4`='送我去破碎岗哨！', `MaleText_loc5`='送我去破碎崗哨!', `MaleText_loc7`='¡Envíame a Puesto Devastación!', `FemaleText_loc1`='징검다리 거점으로 보내 주세요!', `FemaleText_loc4`='送我去破碎岗哨！', `FemaleText_loc5`='送我去破碎崗哨!', `FemaleText_loc7`='¡Envíame a Puesto Devastación!' WHERE `ID`=17935;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명예 거점으로 보내 주십시오!', `MaleText_loc4`='送我到荣耀岗哨去！', `MaleText_loc5`='送我去榮譽崗哨!', `MaleText_loc7`='¡Enviadme al Alto del Honor!', `FemaleText_loc1`='명예 거점으로 보내 주십시오!', `FemaleText_loc4`='送我到荣耀岗哨去！', `FemaleText_loc5`='送我去榮譽崗哨!', `FemaleText_loc7`='¡Enviadme al Alto del Honor!' WHERE `ID`=17936;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='징검다리 거점으로 보내 주십시오!', `MaleText_loc4`='送我去破碎岗哨！', `MaleText_loc5`='送我去破碎崗哨!', `MaleText_loc7`='¡Envíame a Puesto Devastación!', `FemaleText_loc1`='징검다리 거점으로 보내 주세요!', `FemaleText_loc4`='送我去破碎岗哨！', `FemaleText_loc5`='送我去破碎崗哨!', `FemaleText_loc7`='¡Envíame a Puesto Devastación!' WHERE `ID`=17937;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='테돈, 이제 변이된 생물에게 중화제를 시험해 보십시오.', `FemaleText_loc4`='泰顿，你去在那些变异生物身上试用一下中和剂如何？', `FemaleText_loc5`='泰德昂，試著將中和劑用在突變的生物身上。', `FemaleText_loc7`='Tedon, adelántate y prueba el agente neutralizador en la criatura mutante.' WHERE `ID`=17938;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성공이야!', `MaleText_loc4`='成功了！', `MaleText_loc5`='成功!', `MaleText_loc7`='¡Éxito!' WHERE `ID`=17939;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 좋습니다. 전진하기 전에 준비할 시간을 좀 갖도록 하십시오.', `MaleText_loc4`='非常好。在我们出发之前，休整一下。', `MaleText_loc5`='非常好。在我們出發之前，花費片刻準備好自己。', `MaleText_loc7`='Muy bien. Antes de que nos dirijamos allá abajo, tómate un momento para prepararte.' WHERE `ID`=17940;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋습니다, 활기차게 전진하도록 합시다.', `MaleText_loc4`='我们加快步伐吧。', `MaleText_loc5`='加快速度前進。', `MaleText_loc7`='Vayamos con paso ligero.' WHERE `ID`=17941;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기 저 앞에 있는 첫 번째 수정탑에서 시작하도록 합시다. 저들이 내게 접근하지 못하게 해야 한다는 걸 명심하십시오.', `MaleText_loc4`='我们从第一座能量塔开始，往正前方走。记住，别让他们靠近我。', `MaleText_loc5`='我們將從第一座能量鐵塔開始，在正前方。記住，盡量讓他們遠離我。', `MaleText_loc7`='Empezaremos por esa torre de alta tensión de ahí. Recuerda; mantenlos alejados de mí.' WHERE `ID`=17942;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 수정탑은 끝났으니 다음 수정탑으로 갑시다.', `MaleText_loc4`='这座塔已经搞定了。下一个。', `MaleText_loc5`='我處理完這座鐵塔了。到下一個。', `MaleText_loc7`='He acabado con esta torre. Pasemos a la siguiente.' WHERE `ID`=17943;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋습니다, 수정탑 두 개를 해체했습니다. 이번에는 가열 기관입니다.', `MaleText_loc4`='很好，二号塔也解决了。现在去热能导管那里。', `MaleText_loc5`='好的，第二座鐵塔倒下。現在處理熱歧管。', `MaleText_loc7`='Muy bien. Torre número dos, rematada. Ahora, el colector de calor.' WHERE `ID`=17944;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 정도면 됐습니다. 이제 공간이동 관문이 폭발할 겁니다!', `MaleText_loc4`='这样应该就可以了。传送器随时可能爆炸！', `MaleText_loc5`='這樣應該就可以了。傳送器現在應該隨時都會爆炸!', `MaleText_loc7`='Creo que ya está. ¡El teletransportador debería explotar en cualquier momento!' WHERE `ID`=17945;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아요, 여기서 나갑시다!', `MaleText_loc4`='好吧，我们离开这里！', `MaleText_loc5`='好吧，我們離開這裡!', `MaleText_loc7`='Vale, ¡larguémonos de aquí!' WHERE `ID`=17946;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저를 도와 남쪽에 있는 불타는 군단 야영지의 공간이동 관문을 습격할 생각은 없습니까?', `MaleText_loc4`='想帮我去拆除南边那些燃烧军团营地里的迁跃门吗？', `MaleText_loc5`='想幫助我拿下南邊燃燒軍團營地裡的那個星移門嗎?', `MaleText_loc7`='¿Te apetece ayudarme a destruir el portal de distorsión del campamento que la Legión Ardiente tiene hacia el sur?' WHERE `ID`=17947;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 호흡이 잘 맞는 것 같군요, $n. 당신이 없었다면 그 공간이동 관문을 날려 버리지 못했을 겁니다!', `MaleText_loc4`='我们合作得很好，$n。如果没有你的话，我是不可能拆掉那些迁跃门的！', `MaleText_loc5`='我們合作愉快，$n。如果沒有你我不可能將那個星移門拿下!', `MaleText_loc7`='Trabajamos bien juntos, $n. No podría haber derribado ese portal de distorsión si ti.' WHERE `ID`=17948;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙습니다, $n! 당신이 없었다면 해내지 못했을 겁니다. 가루즈에게 소식을 전하도록 하십시오.', `MaleText_loc4`='$n，谢谢你！没有你的帮助，我是不可能成功的。你会跟加鲁斯说明这一切吗？', `MaleText_loc5`='謝謝你，$n!如果沒有你我根本無法完成它。你會讓加魯知道嗎?', `MaleText_loc7`='¡Gracias, $n! No podría haberlo hecho sin ti. ¿Se lo harás saber a Gahruj?' WHERE `ID`=17949;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들이 접근하지 못하게 막아 주십시오!', `MaleText_loc4`='别让他们靠近我！', `MaleText_loc5`='離我遠一點!', `MaleText_loc7`='¡Aléjalos de mí!' WHERE `ID`=17950;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저분들은 며칠 전 샤트라스에서 도착했는데 그 이후로 줄곧 논쟁을 하고 있지 뭡니까.$B$B당신이 저분들 때문에 발길을 돌리지 않아 정말 다행이랍니다. 저분들이 저러는 통에 손님이 떨어져 나가는 게 아닐까 걱정하던 참이었거든요.', `FemaleText_loc4`='这些家伙几天前就来到沙塔斯城了，而他们的争论到现在还没有停止。$B$B我很高兴你没有因此离开，我还在想他们会不会把潜在的顾客给吓走呢。', `FemaleText_loc5`='這些人幾天前從撒塔斯抵達，從那時候開始他們就沒停止過爭吵。$B$B我很高興他們沒有把你嚇跑，因為我開始認為他們在嚇跑我的顧客。', `FemaleText_loc7`='Esta gente llegó de Shattrath hace algunas noches y no han parado de discutir desde entonces.$B$BMe alegro de ver que no te han asustado. Estaba empezando a temer que ahuyentaran a mis clientes.' WHERE `ID`=17951;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='샤트라스에 있는 자들이 어서 빨리 싸움을 끝냈으면 좋겠네요. 점점 신경이 쓰여서 말이죠.$B$B무엇을 도와 드릴까요?', `FemaleText_loc4`='我希望这些沙塔斯城的家伙们快点停止争吵，我脑袋都被吵大了。$B$B有什么我能帮你的吗？', `FemaleText_loc5`='我希望這些撒塔斯人快點停止戰鬥。他們開始讓我感到心煩。$B$B有什麼我能幫忙的嗎?', `FemaleText_loc7`='Espero que esa gente de Shattrath deje de luchar pronto. Están empezando a ponerme los nervios de punta.$B$B¿En qué puedo ayudarte?' WHERE `ID`=17952;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좀 더 열심히 해라, 이 녀석들!', `MaleText_loc4`='努力工作，你们这些败狗！', `MaleText_loc5`='努力工作，蠢蛋!', `MaleText_loc7`='¡Trabajad más, perros!' WHERE `ID`=17953;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 빨리 해라. 그렇지 않으면 따끔한 맛을 보여 주겠다!', `MaleText_loc4`='再快点，否则就尝尝利爪的厉害！', `MaleText_loc5`='快一點，否則就讓你嚐嚐利爪的滋味!', `MaleText_loc7`='¡Más rápido, o probarás la Zarpa!' WHERE `ID`=17954;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='군주 파멸의 발톱. 그래, 내가 듣기 좋아하는 말이지!', `MaleText_loc4`='“厄运之爪大人”，哈哈，听起来不错！', `MaleText_loc5`='杜姆克勞領主。很好，我喜歡這個頭銜!', `MaleText_loc7`='Lord Zarpaletal. ¡Sí, me gusta como suena!' WHERE `ID`=17955;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 주인이 누구더냐?!', `MaleText_loc4`='谁是你的主人？！', `MaleText_loc5`='誰是你的主人?!', `MaleText_loc7`='¡¿Quién es tu maestro?!' WHERE `ID`=17956;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빨리, 더 빨리! 지옥절단기 부품을 모으란 말이다!', `MaleText_loc4`='快点，再快点！把这些魔能机甲部件收集起来！', `MaleText_loc5`='動作快，動作快!將那些惡魔劫奪者零件收集好!', `MaleText_loc7`='¡Más rápido, más rápido! ¡Reunid esas partes del atracador vil!' WHERE `ID`=17957;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 벌목기 톱날검과 함께 사라졌어야 한다고 생각하느냐?', `MaleText_loc4`='你觉得我应该用圆锯吗？', `MaleText_loc5`='你認為我原本應該和巴斯撒一起去?', `MaleText_loc7`='¿Crees que debería haber ido con la sierra circular?' WHERE `ID`=17958;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지옥절단기 부품을 모아라. 우리는 고블린들을 놀라게 할 것이다!', `MaleText_loc4`='把这些魔能机甲部件收集起来。我们会让地精们大吃一惊的！', `MaleText_loc5`='收集那些惡魔劫奪者零件。我們將要給哥布林們一個驚奇!', `MaleText_loc7`='Consigue esas piezas de atracador vil. ¡Vamos a preparar una sorpresa para los goblins!' WHERE `ID`=17959;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 힘들군. 휴가를 좀 얻어야겠어. 거기, 너! 그 안에 등을 집어넣어!', `MaleText_loc4`='这真是个复杂的工作，我想要休假……你，说你呢！赶紧干活！', `MaleText_loc5`='這真是艱苦的工作。我覺得我需要一個假期。你，繼續做你的事!', `MaleText_loc7`='Esto es trabajo duro. Creo que necesito unas vacaciones. ¡Eh, tú, vamos, quiero ver cómo te rompes la espalda!' WHERE `ID`=17960;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 아직 폭풍의 눈에서 싸울 수 있을 만큼 강하지 못합니다. 좀 더 경험을 쌓은 후에 다시 오십시오.', `MaleText_loc4`='你还太年轻，不足以在风暴之眼里战斗。多积累些经验再来吧。', `MaleText_loc5`='你的等級還不足以參加暴風之眼的戰鬥。等你獲得更多經驗的時候再回來。', `MaleText_loc7`='Todavía no eres lo bastante fuerte como para luchar en el Ojo de la Tormenta. Vuelve cuando hayas ganado más experiencia.', `FemaleText_loc1`='당신은 아직 폭풍의 눈에서 싸울 수 있을 만큼 강하지 못합니다. 좀 더 경험을 쌓은 후에 다시 오십시오.', `FemaleText_loc4`='你还太年轻，不足以在风暴之眼里战斗。多积累些经验再来吧。', `FemaleText_loc5`='你的等級還不足以參加暴風之眼的戰鬥。等你獲得更多經驗的時候再回來。', `FemaleText_loc7`='Todavía no eres lo bastante fuerte como para luchar en el Ojo de la Tormenta. Vuelve cuando hayas ganado más experiencia.' WHERE `ID`=17961;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드레나이 군대와 동맹인 얼라이언스가 아웃랜드의 폭풍의 눈에서 호드와 전투를 벌이고 있습니다. 폭풍의 눈에서의 전투를 얼라이언스에게 유리한 방향으로 이끌 수 있도록 도움을 주시겠습니까?', `MaleText_loc4`='德莱尼部队和联盟友军正与部落在外域的风暴之眼交战。你会加入他们，为我们扭转战局吗？', `MaleText_loc5`='在外域的暴風之眼，德萊尼部隊和他們的聯盟與部落開始了戰爭。你願意加入他們來扭轉戰爭的情勢嗎?', `MaleText_loc7`='Las fuerzas draenei y sus aliados de la Alianza se enfrentan a la Horda en el Ojo de la Tormenta, en Terrallende. ¿Quieres unirte a ellos para que la balanza se incline a nuestro favor?', `FemaleText_loc1`='드레나이 군대와 동맹인 얼라이언스가 아웃랜드의 폭풍의 눈에서 호드와 전투를 벌이고 있습니다. 폭풍의 눈에서의 전투를 얼라이언스에게 유리한 방향으로 이끌 수 있도록 도움을 주시겠습니까?', `FemaleText_loc4`='德莱尼部队和联盟友军正与部落在外域的风暴之眼交战。你会加入他们，为我们扭转战局吗？', `FemaleText_loc5`='在外域的暴風之眼，德萊尼部隊和他們的聯盟與部落開始了戰爭。你願意加入他們來扭轉戰爭的情勢嗎?', `FemaleText_loc7`='Las fuerzas draenei y sus aliados de la Alianza se enfrentan a la Horda en el Ojo de la Tormenta, en Terrallende. ¿Quieres unirte a ellos para que la balanza se incline a nuestro favor?' WHERE `ID`=17962;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 호드 연합에서는 드레나이와 참견하기 좋아하는 얼라이언스가 아웃랜드의 마나 저장고를 모두 차지하게 둘 수는 없네. 블러드 엘프들의 폭풍의 눈 공격 작전에 동참하겠나?', `MaleText_loc4`='部落不会允许德莱尼人和那些爱管闲事的联盟来控制外域的魔法晶格。你会加入血精灵的部队并前往风暴之眼作战吗？', `MaleText_loc5`='部落不允許德萊尼和他們愛管閒事的聯盟控制在外域裡全部的法力電池。你願意加入血精靈的行列與他們一起對暴風之眼的發出攻擊嗎?', `MaleText_loc7`='La Horda no debe permitir que los draenei y su entrometida Alianza controlen las células de maná de Terrallende. ¿Quieres acompañar a los elfos de sangre en su ataque al Ojo de la Tormenta?', `FemaleText_loc1`='우리 호드 연합에서는 드레나이와 참견하기 좋아하는 얼라이언스가 아웃랜드의 마나 저장고를 모두 차지하게 둘 수는 없습니다. 블러드 엘프들의 폭풍의 눈 공격 작전에 동참하시겠습니까?', `FemaleText_loc4`='部落不会允许德莱尼人和那些爱管闲事的联盟来控制外域的魔法晶格。你会加入血精灵的部队并前往风暴之眼作战吗？', `FemaleText_loc5`='部落不允許德萊尼和他們愛管閒事的聯盟控制在外域裡全部的法力電池。你願意加入血精靈的行列與他們一起對暴風之眼的發出攻擊嗎?', `FemaleText_loc7`='La Horda no debe permitir que los draenei y su entrometida Alianza controlen las células de maná de Terrallende. ¿Quieres acompañar a los elfos de sangre en su ataque al Ojo de la Tormenta?' WHERE `ID`=17963;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='편대사령관 브락크를 찾아가 보십시오, $n. 당신에게 파괴의 장갑 와이번 한 마리를 내줄 것입니다. 그럼, 행운을 빕니다!', `MaleText_loc4`='去和空军指挥官布拉克谈谈，$n。他会给你配备一只武装飞龙。对了，祝你好运！', `MaleText_loc5`='與空軍指揮布拉克談話，$n。他將會提供一隻裝甲雙足翼龍毀滅者給你。並且，祝你好運!', `MaleText_loc7`='Habla con el comandante del aire Brack, $n. Te proporcionará uno de nuestros destructores dracoleones acorazados. ¡Y buena suerte!' WHERE `ID`=17964;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이보시오, $c! 비행 임무 때문에 오셨소?', `MaleText_loc4`='你好，$c！你是要汇报飞行任务的进展吗？', `MaleText_loc5`='你好，$c!你要回報一項飛行任務嗎?', `MaleText_loc7`='¡Hola, $c! ¿Vienes por la misión de vuelo?' WHERE `ID`=17965;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='할...', `MaleText_loc4`='哈尔……', `MaleText_loc5`='哈爾...', `MaleText_loc7`='Hal...' WHERE `ID`=17966;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일이오, 내트?', `MaleText_loc4`='什么事，纳特？', `MaleText_loc5`='是嗎，納特?', `MaleText_loc7`='¿Sí, Nat?' WHERE `ID`=17967;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어젯밤 또 그 꿈을 꿨습니다...', `MaleText_loc4`='昨晚我又做了那个梦……', `MaleText_loc5`='昨晚又再次的夢到那個夢...', `MaleText_loc7`='Tuve ese sueño la noche pasada...' WHERE `ID`=17968;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 꿈 말이오?', `MaleText_loc4`='哪一个？', `MaleText_loc5`='哪一個?', `MaleText_loc7`='¿Qué sueño?' WHERE `ID`=17969;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 꿈 말입니다... 아주 황당한 꿈. 기억 안 나십니까?', `MaleText_loc4`='那个梦……那个疯狂的梦。记得吗？', `MaleText_loc5`='那個夢...很瘋狂的那個。記得嗎?', `MaleText_loc7`='Ese sueño... El loco. ¿Te acuerdas?' WHERE `ID`=17970;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타렌 제분소가 언데드 군대에 의해 파괴되고 남녘해안과 영원히 원수지간이 되는 꿈 말입니다.', `MaleText_loc4`='塔伦米尔被某种疯狂的亡灵力量毁灭了，而且永远地变成了南海镇的敌人。', `MaleText_loc5`='塔倫米爾被某些瘋狂的不死軍團所摧毀並且永遠的成為南海鎮的敵人。', `MaleText_loc7`='El molino Tarren Mill es destruido por alguna extraña tropa de no-muertos y se convierte por siempre jamás en un enemigo de Costasur.' WHERE `ID`=17971;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상상이 됩니까, 할? 그런 일은 없겠지요?', `MaleText_loc4`='你能想象这件事吗，哈尔？你能吗？', `MaleText_loc5`='你能想像這樣的一件事情嗎，哈爾? 你能嗎?', `MaleText_loc7`='¿Te imaginas algo así, Hal? ¿Te lo imaginas?' WHERE `ID`=17972;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 왜 제가 던홀드에 있는 꿈과 블랙무어가 노예로 부리던 오크가 탈출하는 꿈 말입니다.', `MaleText_loc4`='我还梦到敦霍尔德，布莱克摩尔那个的兽人奴隶逃跑了……', `MaleText_loc5`='我在敦霍爾德那裡的那次，那個布拉克摩爾的私人奴隸逃跑...', `MaleText_loc7`='El sueño ese en el que estoy en Durnholde y ese orco..., ese Lodonegro me tiene como su esclavo personal...' WHERE `ID`=17973;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='결국 그는 감옥을 통째로 부수고 포로가 된 오크들을 모두 구출한 뒤 오크들의 왕이 되었답니다... 대족장인가 뭐라고 부르는 것 같았습니다.', `MaleText_loc4`='他最终摧毁了整个城堡，救出了所有被我们关在营地的兽人。他成为了兽人的国王……酋长之类的什么东西。', `MaleText_loc5`='他最後毀滅整個堡壘，釋放關在營地的所有獸人，並且成為獸人的國王...大酋長還是甚麼的。', `MaleText_loc7`='Acaba destruyendo todo el castillo, liberando todos los orcos que mantenemos en los campamentos, y ascendiendo al poder como rey de los orcos... Jefe de Guerra o algo.' WHERE `ID`=17974;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황당한 꿈이지요?', `MaleText_loc4`='太疯狂了，不是吗？', `MaleText_loc5`='很瘋狂，不是嗎?', `MaleText_loc7`='Qué locura, ¿no?' WHERE `ID`=17975;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러니까 내가 어떤 거대하고 오래된 나무가 있는 산에 있었습니다. 주위에는 엘프들이 여기저기 뛰어다니고 있었고요...', `MaleText_loc4`='然后我梦到一座长着大树的山，一群精灵们到处跑来跑去……', `MaleText_loc5`='我在某個山上跟一些老樹們一起。到處都是精靈跑來跑去...', `MaleText_loc7`='Así que estoy en alguna montaña con algún árbol. Una pandilla de elfos corretea...' WHERE `ID`=17976;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런데 갑자기 키가 100미터 정도 되는 악마가 나타나 그 거대한 나무를 오르기 시작하는 겁니다.', `MaleText_loc4`='不知道从哪里冒出来的一个300尺高的恶魔或者什么东西走了过来，开始爬树……', `MaleText_loc5`='不知從哪兒來，大約300英尺高的惡魔或是某種東西走了過來並且開始爬樹...', `MaleText_loc7`='De repente, un demonio de 90 metros de alto, sale de la nada y empieza a escalar el árbol...' WHERE `ID`=17977;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더욱 희한한 것은 그 거대한 악마가 둥둥 떠다니는 자그마한 빛 같은 것들에 죽임을 당하는 것이었습니다. 아, 그리고 저는 여자 엘프였습니다. 네... 황당했지요...', `MaleText_loc4`='听起来很疯狂吧？更疯狂的还在后面呢。那个巨大的恶魔被一群飘在空中的小光球给炸死了……哦，我在梦中是一个女精灵……对……', `MaleText_loc5`='而如果那不夠瘋狂，哪個大惡魔被一群漂浮的發光物給殺死...噢，我在那裡也是一個女精靈...是的...', `MaleText_loc7`='Y, por si no fuera bastante locura, a ese demonio grande le dan muerte una pandilla de cositas de luz flotantes... Oh, en ese yo era una elfa... Sí...' WHERE `ID`=17978;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번 꿈에서 나는 세상에서 제일가는 어부였답니다. 그리고 칼림도어라고 불리는 곳으로 갔지요...', `MaleText_loc4`='在这个梦里，我是这个世界中的钓鱼大师。我搬到了一个名叫卡利姆多的地方……', `MaleText_loc5`='在這個夢裡，我是釣魚世界的主人。我搬到一處稱為卡林多的地方...', `MaleText_loc7`='En ese sueño, era el mejor pescador del mundo. Me había mudado a un sitio llamado Kalimdor...' WHERE `ID`=17979;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 전 세계에서 사람들이 찾아와 제게 고기 잡는 법을 배워 갔답니다.', `MaleText_loc4`='从世界各地来的人们走到我面前对我表示敬意……在我这里学习钓鱼。', `MaleText_loc5`='並且世界各地的人們來到我這裡對我表示尊敬...並且學習如何釣魚。', `MaleText_loc7`='Y gente de todo el mundo viene a rendirme homenaje... y a aprender a pescar.' WHERE `ID`=17980;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 낚시의 신이나 마찬가지였습니다...', `MaleText_loc4`='我就像什么钓鱼之神那样……', `MaleText_loc5`='我看起來像某種釣魚之神...', `MaleText_loc7`='Soy como una especie de dios de la pesca...' WHERE `ID`=17981;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='믿을 수가 없지만 말입니다...혹시 폴로르와 티굴이라는 두 건달 녀석들을 알고 있습니까?', `MaleText_loc4`='我根本不能相信这个……你知道那两个大嘴巴的恶棍，弗洛尔和提古勒吗？', `MaleText_loc5`='真的令人難以置信...你知道那兩個大聲裝腔作勢的暴徒，佛爾洛和提古勒嗎?', `MaleText_loc7`='No me puedo creer este... ¿Conoces a esos dos rufianes mal hablados, Foror y Tigule?' WHERE `ID`=17982;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번 꿈에선 그자들이 아이스크림이라고 불리는 뭔가를 발명했는데 딸기 맛이 났습니다... 간단히 말해서 그자들이 아이스크림으로 엄청난 부자가 됐지 뭡니까!', `MaleText_loc4`='在那个梦里，他们不知通过什么手段，发明了一种叫做冰淇淋的东西，还用草莓来调味……好吧，长话短说，他们最后变得十分富裕！', `MaleText_loc5`='在哪夢裡，他們最終發明了一種叫做冰淇淋的東西並用草莓來當做配料...噢，長話短說，他們最後突然致富了!', `MaleText_loc7`='Y en el sueño, acabaron inventando algo que llamaban helado. Y le daba sabor con fresas... Total, que se hicieron ricos con eso.' WHERE `ID`=17983;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 웃긴 것은 그들이 아이스크림 장사를 그만두고 모험가가 된다는 겁니다... 전 세계를 여행하다 결국은 어떤 차원문에 들어가게 되곤... 전 그 뒤에 식은땀을 흘리며 깨어났답니다...', `MaleText_loc4`='还不够疯狂么？我还梦到他们退出冰淇淋生意，变成了冒险家……他们周游了全世界，随后消失在什么传送门里。我随即就醒了，出了一身冷汗……', `MaleText_loc5`='如果那不夠瘋狂，他們決定停止冰淇淋生意並且成為冒險者...他們到處旅行最後在某個傳送門中消失。在那之後我就在冷汗中醒來...', `MaleText_loc7`='Por si no fuera locura suficiente, deciden dejar el negocio de los helados y convertirse en aventureros... Viajan por todas partes y, finalmente, desaparecen en algún portal. Después de ese me desperté con sudores fríos...' WHERE `ID`=17984;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 오싹한 꿈이었습니다... 그러니까 왕의 아들인 아서스가... 우서 경과 함께 악을 무찌르러 가는데... *이마의 땀을 닦는 내트*', `MaleText_loc4`='还有一个非常可怕的梦……国王的儿子，阿尔萨斯……他和乌瑟尔一起对抗邪恶……*纳特擦了擦他的额头*', `MaleText_loc5`='這個真的非常恐怖...國王的兒子，阿薩斯...當他與烏瑟一同與邪惡戰鬥...*納特將它的眉毛輕輕拍乾*', `MaleText_loc7`='Este es realmente triste... El hijo del rey, Arthas... Bueno, sale a batallar contra el mal, junto con Uther... *Nat se seca la frente*' WHERE `ID`=17985;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가엾게도 아서스 왕자는 악마에게 마음을 빼앗겨 악마가 되고 맙니다...', `MaleText_loc4`='不幸的是，阿尔萨斯被邪恶吞噬了，最终变成了邪恶本身……', `MaleText_loc5`='但是可悲的是，阿薩斯最後被邪惡給迷惑並且變得邪惡...', `MaleText_loc7`='Pero, trágicamente, Arthas es consumido por el mal y se transforma en mal...' WHERE `ID`=17986;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그는 착한 척하며 기회를 잡아 왕인 아버지에게 다가간 후 칼을 뽑아 즉시 왕을 살해했답니다.', `MaleText_loc4`='他假装好意地回到了国王身边，拔出佩剑，跑向国王，对着国王就这么……你知道……咔嚓一声。', `MaleText_loc5`='嗯，他回到國王身邊假裝一切都很好，然後拔出他的劍，並抵住國王，刺進...你知道的...當場殺死他。', `MaleText_loc7`='Bueno, pues vuelve a ver al rey, como si no pasara nada, con cara de bueno, y de repente, saca la espada y... Bueno, ya sabes, lo mata de un tajo.' WHERE `ID`=17987;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런 일은 절대로 일어나지 않을 것이오, 내트. 낚시나 합시다.', `MaleText_loc4`='这些永远都不会发生的，纳特。', `MaleText_loc5`='它永遠不會發生，奈特。', `MaleText_loc7`='Nunca ocurrirá, Nat.' WHERE `ID`=17988;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 자다가 봉창을 두드리는... 말도 안 되오!', `MaleText_loc4`='这不可能！', `MaleText_loc5`='不可能!', `MaleText_loc7`='¡Imposible!' WHERE `ID`=17989;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내트, 가끔 당신이 걱정된다오.', `MaleText_loc4`='我有些担心你了，纳特。', `MaleText_loc5`='我有時候真的替你擔心，奈特。', `MaleText_loc7`='A veces me preocupas, Nat.' WHERE `ID`=17990;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그냥 개 꿈일 뿐이겠지...', `MaleText_loc4`='不可能。', `MaleText_loc5`='不行。', `MaleText_loc7`='Ni hablar.' WHERE `ID`=17991;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내트, 그런 터무니없는 소리를 처음 듣는 건 아니지만 이건 좀 너무하는군.', `MaleText_loc4`='纳特，这是我听过的最可笑的梦了。', `MaleText_loc5`='納特，一直到今天我曾經聽到一個或者兩個彌天大謊，但是跟你所說的真的無法相比。', `MaleText_loc7`='Nat, he oído cosas grandes en mis tiempos, pero esta se lleva la palma.' WHERE `ID`=17992;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대체 무슨 말도 안 되는 소리오, 내트?', `MaleText_loc4`='你那根笛子里装着什么，纳特？', `MaleText_loc5`='你在那根管子藏了甚麼，納特?', `MaleText_loc7`='¿Qué tienes en esa pipa, Nat?' WHERE `ID`=17993;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='*고개를 젓는 할* 오, 내트, 내트...', `MaleText_loc4`='*哈尔摇着头*纳特，纳特，纳特……', `MaleText_loc5`='*哈爾搖了搖他的頭* 納特，納特，納特...', `MaleText_loc7`='*Hal niega con la cabeza * Nat, Nat, Nat...' WHERE `ID`=17994;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만하고 고기나 잡으시오, 내트.', `MaleText_loc4`='闭上嘴去钓鱼吧，纳特。', `MaleText_loc5`='閉嘴和抓你的魚，納特。', `MaleText_loc7`='Calla y pesca, Nat.' WHERE `ID`=17995;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 이곳도 싫고 여기 사람들도 싫습니다! 이거 해라! 저거 해라! 그래, 이제 내가 농부란 말이지요? 그럼 수확도 해야겠군요? 언젠가 이곳이 공동묘지가 되어서 시끄러운 자들이 죄다 묻혀 버렸으면 좋겠군요!', `MaleText_loc4`='我讨厌这个地方和这里的每个人！斯密瑟斯做这个！斯密瑟斯做那个！哦，这么说我是个农民了？所以我就得去收割东西了？我希望有一天这整个地方变成一座大坟场，所有那些聒噪的家伙都会被埋在这里！', `MaleText_loc5`='我憎惡這個地方和在這裡的每個人!密瑟斯做這!密瑟斯做那!噢，所以我現在是一個農夫，呃?我必須要收成東西，呃?我希望有一天這整個地方會變成一個大墳場，而全部的大嘴巴都被埋在這可惡的地方!', `MaleText_loc7`='¡Odio este lugar y todo el mundo que hay en él! ¡Herrera, haz esto! ¡Herrera, haz lo otro! Oh, así que ahora soy un granjero, ¿eh? Así que voy a tener que cosechar cosas, ¿eh? ¡Espero que un día todo este lugar se convierta en un gran cementerio y todos los bocazas estén enterrados justo aquí, maldita sea!' WHERE `ID`=17996;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 채소를 모읍니다.', `MaleText_loc4`='%s收集了一些蔬菜。', `MaleText_loc5`='%s收集一些蔬菜。', `MaleText_loc7`='%s recoge alguna verdura.' WHERE `ID`=17997;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 땅을 팝니다.', `MaleText_loc4`='%s在泥土里挖掘。', `MaleText_loc5`='%s鑽進灰塵裡。', `MaleText_loc7`='%s cava en el barro.' WHERE `ID`=17998;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 돌멩이를 치웁니다.', `MaleText_loc4`='%s移动了一块石头。', `MaleText_loc5`='%s移動一塊岩石。', `MaleText_loc7`='%s mueve una roca.' WHERE `ID`=17999;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='광산에서 인생을 낭비하려고 실버문에서 여기까지 온 것이 아니란 말이야!', `MaleText_loc4`='我从银月城来这里，不是为了把我的生命浪费在一个矿洞中！', `MaleText_loc5`='我不是從銀月城千辛萬苦來到這地方然後辛勞苦幹地在礦坑裡過我的一生!', `MaleText_loc7`='¡No he venido desde la ciudad de Lunargenta para pasarme la vida trabajando en una mina!' WHERE `ID`=18000;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그냥 떠나야 해. 우리가 고작 이따위 일이나 하러 아웃랜드까지 온 거란 말인가?', `MaleText_loc4`='我们应该离开。这是我们来外域的原因吗？', `MaleText_loc5`='我們應該離開這。這就是我們來到外域的原因嗎?', `MaleText_loc7`='Deberíamos marcharnos. ¿Para esto vinimos a Terrallende?' WHERE `ID`=18001;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 속았어. 이곳은 그들이 말한 천국과는 딴판이라고!', `MaleText_loc4`='我们被愚弄了。这根本不是他们所承诺的乐土！', `MaleText_loc5`='我們被欺騙了。這根本就不是被許諾的土地!', `MaleText_loc7`='Nos han timado. ¡Sin duda, esto no es la tierra prometida!' WHERE `ID`=18002;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 고귀한 블러드 엘프요. 이따위 육체노동은 하지 않는단 말이오.', `MaleText_loc4`='我是个血精灵。我不干体力活。', `MaleText_loc5`='我是一個血精靈。我不做體力勞動。', `MaleText_loc7`='Soy un elfo de sangre. No hago trabajos físicos.' WHERE `ID`=18003;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='캘타스가 우리한테 거짓말을 한 거요. 아웃랜드는 낙원이 아니오.', `MaleText_loc4`='凯尔萨斯对我们撒了谎，外域并不是天堂。', `MaleText_loc5`='凱爾薩斯騙了我們。外域不是天堂。', `MaleText_loc7`='Kael''thas nos mintió. Terrallende no es un paraíso.' WHERE `ID`=18004;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 한때 실버문에서 잘 나가는 마법학자였소. 그런데 이제 밑바닥으로 떨어져 노예나 다름없는 처지가 되어 버리다니!', `MaleText_loc4`='我曾经是银月城中的伟大的魔导师。现在我却成了比奴隶好那么一点点的工头！', `MaleText_loc5`='我曾經是銀月城一個偉大的博學者。現在我是一個被降級，在工頭之後奴隸之上的人!', `MaleText_loc7`='Antaño era un gran magister en la ciudad de Lunargenta. ¡Ahora me han degradado y soy un antiguo supervisor, poco más que un esclavo!' WHERE `ID`=18005;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나한테 이런 천한 일을 시키다니 말도 안 돼!', `MaleText_loc4`='他们没有权力把我降职来做这些下等事！', `MaleText_loc5`='他們沒有權利把我降級來做這些枯燥的任務!', `MaleText_loc7`='¡No tienen derecho a rebajarme a este tipo de tarea!' WHERE `ID`=18006;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 연장을 버리고 우리 모두 떠나야 해. 이런 일이나 하려고 아웃랜드에 온 게 아니잖아.', `MaleText_loc4`='过来。让我们放下这些拙劣的器械，然后远离这一切。这不是我们来外域的理由。', `MaleText_loc5`='來，讓我們放下這些粗糙的儀器並且離開這裡所有的一切。這不是我們來外域的原因。', `MaleText_loc7`='Ven. Dejemos estos instrumentos primitivos y alejémonos de todo esto. No es por lo que vinimos a Terrallende.' WHERE `ID`=18007;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장가르 습지대에 가본 적이 있으면 다니엘스라는 친구를 만나봤을 걸세. 거 왜 있잖나... 이상한 보호모를 쓰고 "전문가"에게만 대답하는 친구 말일세.$B$B아, 물론 내가 그에게 모든 것을 가르쳤지.$B$B그 친구의 휘황찬란한 옷에 현혹되지 말게. 마음속으로 아직 난 도적이지. 다니엘스와 나는 많은 시간을 함께 일했지만 그 시절은 내가 은퇴하기 전이지. 내가 알기로 그 친구는 주위 사람들을 못 배기게 하면서 아직도 활동하고 있다네.', `MaleText_loc4`='如果你去过赞加沼泽，你可能遇到过一个叫做丹尼斯的朋友，你记得——那个带着个奇怪的帽子，只会在你叫他“专家”的时候回应的家伙吗？$B$B当然，是我教会了他一切。$B$B不要被我华丽的服饰所迷惑。其实在我的内心里，我仍然是个盗贼。丹尼斯和我曾经在战壕里相处过很长时间，但那是在我退休前的事情了。据我所知，他仍在那里，让敌人体验地狱般的痛苦。', `MaleText_loc5`='如果你曾到過贊格沼澤，你可能遇到一個名叫丹尼爾的人。你知道的 -- 戴一頂奇怪的盔帽，只會回答「專家」的人。$B$B當然，他知道的一切都是我教的。$B$B不要讓這身華麗的衣服欺騙了你。我內心裡仍然是一名盜賊。丹尼爾和我一同在戰壕中度過許多時光，但是在我退休之前。據我所知，他仍然在外頭，教訓敵人。', `MaleText_loc7`='Si has estado en la marisma de Zangar, puede que te hayas encontrado con un tipo llamado Daniels. Ya sabes – lleva un casco extraño, solo responde al nombre de "el Especialista."$B$BPor supuesto, le enseñé todo lo que sabe.$B$BNo te dejes engañar por la ropa elegante. En el fondo sigo siendo un pícaro. Daniels y yo pasamos mucho tiempo juntos en las trincheras, pero eso fue antes de que yo me retirara. Por lo que sé, sigue ahí fuera, desatando el infierno.' WHERE `ID`=18008;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠시 휴식을 취할 시간이로군...', `MaleText_loc4`='该让老斯密瑟斯休息一会了……', `MaleText_loc5`='是時候讓年邁的鐵匠們休息一下...', `MaleText_loc7`='Es hora de que el viejo Herrera se tome un descanso...' WHERE `ID`=18009;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='매일 우리가 하는 일은 이 광산에서 막노동을 하는 것이 전부요. 블러드 엘프 남자는 이런 육체노동이 체질에 맞지 않는데 말이야.', `MaleText_loc4`='日复一日，我们所做的就是在这座矿井里面做苦力。男性血精灵不是为体力劳动而生的！', `MaleText_loc5`='日復一日，我們只能在這礦坑做苦力。血精靈男性並不是做苦工的料。', `MaleText_loc7`='Día tras día, lo único que hacemos es matarnos trabajando en esta mina. El elfo de sangre no fue hecho para tales tareas manuales.' WHERE `ID`=18010;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 하품을 합니다.', `MaleText_loc4`='%s打了个哈欠。', `MaleText_loc5`='%s打呵欠。', `MaleText_loc7`='%s bosteza.' WHERE `ID`=18011;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠, 다시 맷돌질을 해야겠군.', `MaleText_loc4`='嘿，回来干活。', `MaleText_loc5`='欸，回去做事。', `MaleText_loc7`='Vuelve al tajo.' WHERE `ID`=18012;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잠깐! 성에 침입자들이 있다!', `FemaleText_loc4`='停下！有入侵者在城堡里！', `FemaleText_loc5`='等一下!入侵者在城堡裡!', `FemaleText_loc7`='¡Quieto! ¡Hay intrusos en el castillo!' WHERE `ID`=18013;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='빛의 궁전에 침입해서 우리 비밀을 가지고 달아날 수 있을 거라 생각했니! 비샤스, 이 죄인을 당장 심문하세요!', `FemaleText_loc4`='这样看来，你觉得你可以逃出这座圣光的宫殿，带着我们的秘密逃走吗？韦沙斯，立即审问这个罪犯！', `FemaleText_loc5`='你以為你可以闖入這座聖光的宮殿，並且帶著我們的秘密而逃走嗎!韋沙斯，立刻審問這個罪犯!', `FemaleText_loc7`='¡Así que pensabas que podrías irrumpir en este palacio de la Luz y huir con nuestros secretos! ¡Vishas, interroga a este criminal de inmediato!' WHERE `ID`=18014;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론입니다, 화이트메인양!', `MaleText_loc4`='我很荣幸，夫人！', `MaleText_loc5`='這是我的榮幸，我的女士!', `MaleText_loc7`='¡Por supuesto, mi señora!' WHERE `ID`=18015;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 녀석, 전부 말해라! 순순히 실토하지 않으면 네 녀석의 다리를 늘려 주마!', `MaleText_loc4`='告诉我……告诉我所有的事情！不然我就亲手把你的秘密挖出来！', `MaleText_loc5`='將一切告訴我，你這個賤骨頭!你若是嘴硬，我就將你的肉體活活撕成八塊!', `MaleText_loc7`='¡Cuéntamelo todo, escoria! ¡Dímelo o te arrancaré los secretos de la carne!' WHERE `ID`=18016;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='화이트메인양, 이자가 전혀 입을 열지 않습니다. 뭔가 비밀이 있는 게 분명합니다! 못된 비밀 말입니다!', `MaleText_loc4`='它不说话，夫人。我知道它保守着秘密！邪恶的秘密！', `MaleText_loc5`='它死也不肯說，我的女士。我知道它確實掌握著一些秘密!重要的秘密!', `MaleText_loc7`='No habla, señora. ¡Sé que guarda secretos! ¡Secretos oscuros!' WHERE `ID`=18017;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 힘을 아껴야만 해요... 지금 이 상황엔 내 차원 마법이 필요하게 될지 누구도 장담할 수 없으니까요!', `MaleText_loc4`='我必须保存能量……很难说什么时候会用到我的传送魔法！', `MaleText_loc5`='我必須保存我的魔力...不知道什麼時候會用到我的傳送魔法!', `MaleText_loc7`='Debo conservar mi energía... ¡no se sabe cuándo se necesitará mi magia del portal!' WHERE `ID`=18018;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나의 용사여, 이 괴물을 처치하세요!', `FemaleText_loc4`='我的勇士，消灭这个怪物！', `FemaleText_loc5`='我的勇士，殺死這個怪物!', `FemaleText_loc7`='¡Campeón, destruye a ese monstruo!' WHERE `ID`=18019;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='화이트메인의 이름으로 저 이단자는 정화될 것입니다!', `MaleText_loc4`='这些异教徒们必将受到净化，女士！', `MaleText_loc5`='這些異教徒的罪惡將被淨化，我的女士!', `MaleText_loc7`='¡El infiel será purificado, señora!' WHERE `ID`=18020;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헉헉! 치명적인 상처를 입었습니다! 당신을 실망시키다니...', `MaleText_loc4`='啊！它对我进行了致命的一击！我要死了……', `MaleText_loc5`='噢不!它已經擊出了決定性的一擊!我讓你失望了...', `MaleText_loc7`='¡ARGH! ¡Ha asestado un golpe mortal! Te he fallado...' WHERE `ID`=18021;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 치명상을 입은 듯 비틀거립니다.', `MaleText_loc4`='%s蹒跚着，好像他受了重伤似的。', `MaleText_loc5`='%s蹣跚而行好像受到了致命的傷害。', `MaleText_loc7`='%s se tambalea como si estuviera herido de muerte.' WHERE `ID`=18022;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='모그레인이 쓰러지다니! 이 원수는 꼭 갚을 것이다! 일어나라, 나의 용사여! 일어나라!', `FemaleText_loc4`='莫格莱尼倒下了？你们要为此付出代价！复活吧，我的勇士！复活吧！', `FemaleText_loc5`='莫格萊尼已經倒下!你將為你的背叛付出代價!起來吧，我的勇士!起來吧!', `FemaleText_loc7`='¡Mograine ha caído! ¡Pagarás por esta traición! ¡Levántate, mi campeón! ¡Levántate!' WHERE `ID`=18023;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 르노에게 치유 주문을 시전하는 척합니다.', `FemaleText_loc4`='%s假装对着雷诺施放了一个治疗法术。', `FemaleText_loc5`='%s假裝對雷諾施展治療法術。', `FemaleText_loc7`='%s finge lanzar un hechizo de sanación sobre Renault.' WHERE `ID`=18024;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='은빛 여명회에서 이곳에서의 처절한 싸움에서 이겨내길 진정 바람 하오. 악마 군단에 내 로브를 버리는 건 아주 싫을 테니까 말이오.', `FemaleText_loc4`='我的确希望这些……银色黎明可以管理这里的日常事务。我讨厌那些恶魔杂碎们弄脏我的长袍！', `FemaleText_loc5`='我真的希望這些...銀色黎明的部隊管理一下這裡。我討厭為了懲治那些惡魔的烏合之眾而弄髒我的袍子!', `FemaleText_loc7`='También espero que esos..., los de El Alba Argenta, se ocupen de lo que pasa aquí. No me gustaría manchar mi túnica con esa basura de demonios.' WHERE `ID`=18025;
