UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음, 그래서... 저에게 이것 저것 가르쳐 주실 수...', `MaleText_loc4`='那么你真的可以教我这个……这个……', `MaleText_loc5`='所以你能教我這...這...', `MaleText_loc7`='Así que puedes enseñarme este... este...' WHERE `ID`=18041;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강령술. 강령술이라고 하오. 그리고 당신에게 내 힘에 담긴 그 기술을 가르쳐 줄 수 있소이다.', `MaleText_loc4`='通灵术。它叫通灵术。没错，我把它和我的力量结合在了一起。', `MaleText_loc5`='死靈法術。它被稱為死靈法術。而且沒錯，我擁有死靈的力量以賜予你這份厚禮。', `MaleText_loc7`='Nigromancia. Se llama nigromancia. Y sí, está en mi poder bendecirte con sus milagros.' WHERE `ID`=18042;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 키린 토에서는요? 그들은 강령술에 대해 뭐라고 하던가요?', `MaleText_loc4`='肯瑞托呢？他们对通灵术有什么看法？', `MaleText_loc5`='那麼祈倫托呢?他們對死靈法術有什麼看法呢?', `MaleText_loc7`='¿Y el Kirin Tor? ¿Qué opinan ellos de la nigromancia?' WHERE `ID`=18043;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헬쿨라, 당신은 키린 토의 일원도 아니고 강령술사도 아니니 당신이 걱정할 일이 아니오.', `MaleText_loc4`='这和你无关，赫尔库拉，你既不是肯瑞托的一员也不是一个通灵师。', `MaleText_loc5`='那不關你的事，赫爾庫拉，因為你既不屬於祈倫托也不是一名死靈法師。', `MaleText_loc7`='Eso no te concierne, Helcular, ya que no eres ni el Kirin Tor ni un nigromante.' WHERE `ID`=18044;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최선을 다하도록!', `MaleText_loc4`='原地就位！', `MaleText_loc5`='稍息!', `MaleText_loc7`='¡Espera mis órdenes!', `FemaleText_loc1`='최선을 다하도록!', `FemaleText_loc4`='原地就位！', `FemaleText_loc5`='稍息!', `FemaleText_loc7`='¡Espera mis órdenes!' WHERE `ID`=18045;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방심하지 마라.', `MaleText_loc4`='保持警惕。', `MaleText_loc5`='立正站好。', `MaleText_loc7`='Mantente alerta.', `FemaleText_loc1`='방심하지 마라.', `FemaleText_loc4`='保持警惕。', `FemaleText_loc5`='立正站好。', `FemaleText_loc7`='Mantente alerta.' WHERE `ID`=18046;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 좋아.', `MaleText_loc4`='非常好。', `MaleText_loc5`='非常好。', `MaleText_loc7`='Muy bien.', `FemaleText_loc1`='아주 좋아.', `FemaleText_loc4`='非常好。', `FemaleText_loc5`='非常好。', `FemaleText_loc7`='Muy bien.' WHERE `ID`=18047;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘했다.', `MaleText_loc4`='干得非常好。', `MaleText_loc5`='幹得好。', `MaleText_loc7`='Excelente.', `FemaleText_loc1`='잘했다.', `FemaleText_loc4`='干得非常好。', `FemaleText_loc5`='幹得好。', `FemaleText_loc7`='Excelente.' WHERE `ID`=18048;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 잘해 주고 있으니 기쁘군.', `MaleText_loc4`='我为你的言行感到自豪。', `MaleText_loc5`='你的事蹟讓我感到驕傲。', `MaleText_loc7`='Estoy orgulloso de ti.', `FemaleText_loc1`='좋아, 잘해 주고 있으니 기쁘군.', `FemaleText_loc4`='我为你的言行感到自豪。', `FemaleText_loc5`='你的事蹟讓我感到驕傲。', `FemaleText_loc7`='Estoy orgulloso de ti.' WHERE `ID`=18049;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='솔직히 말해 키린 토가 어떻게 생각하든 난 전혀 관심이 없소! 그들은 구시대적인 방식만을 고집하는 바보들이라오.', `MaleText_loc4`='但是老实说，我对肯瑞托的想法一点也不感兴趣！他们是群蠢货，一群沉迷在他们古老腐朽的习惯中的蠢货。', `MaleText_loc5`='但是老實說，我一點都不在乎祈倫托怎麼想!他們是呆子，只會用他們食古不化的腦子在辦事。', `MaleText_loc7`='Pero, para ser totalmente sincero, ¡no me importa en absoluto lo que piense el Kirin Tor! Son unos estúpidos, inflexibles en sus modos arcaicos.' WHERE `ID`=18050;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='켈투자드 님, 절 가르쳐 주십시오. 당신이 알고 있는 모든 것을..', `MaleText_loc4`='那么，克尔苏加德，教我吧，把你知道的东西都教给我……', `MaleText_loc5`='那麼你就教教我，科爾蘇加德。教我你所知道的一切...', `MaleText_loc7`='Entonces enséñame, Kel''Thuzad. Enséñame todo lo que sepas...' WHERE `ID`=18051;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='때가 되면, 헬쿨라... 모든 것은 때가 되면 이루어질 것이오...', `MaleText_loc4`='时机恰当的时候，赫尔库拉……等到时机恰当的时候……', `MaleText_loc5`='適當的時機，赫爾庫拉...適當的時機...', `MaleText_loc7`='A su debido tiempo, Helcular... Todo a su debido tiempo...' WHERE `ID`=18052;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 좌우를 살핍니다.', `MaleText_loc4`='%s左右环顾着。', `MaleText_loc5`='%s看了一下左邊，然後看看右邊。', `MaleText_loc7`='%s mira a la izquierda y a la derecha.' WHERE `ID`=18053;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헬쿨라, 그대에게 맛보기로 약간만 보여 주도록 하겠소...', `MaleText_loc4`='过来，赫尔库拉，让我给你展示一下……', `MaleText_loc5`='來，赫爾庫拉，讓我給你一點甜頭嚐嚐...', `MaleText_loc7`='Ven, Helcular, déjame darte una pequeña muestra...' WHERE `ID`=18054;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 알아들을 수 없는 말을 중얼거립니다.', `MaleText_loc4`='%s念出一些令人无法理解的语言。', `MaleText_loc5`='%s說了一些難以理解的話。', `MaleText_loc7`='%s farfulla algo incomprensible.' WHERE `ID`=18055;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헬쿨라, 이제 알겠소? 지금도 내 힘이 의심스럽소? 난 생명을 마음대로 부린다오!', `MaleText_loc4`='现在你看到了吗，赫尔库拉？你还会怀疑我的力量吗？我控制着生命！', `MaleText_loc5`='你看見了嗎，赫爾庫拉?你還懷疑我的力量嗎?我可以控制生命!', `MaleText_loc7`='¿Lo ves ahora, Helcular? ¿Dudas del poder? ¡Controlo la vida!' WHERE `ID`=18056;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 죽음도...', `MaleText_loc4`='还有死亡……', `MaleText_loc5`='而死亡...', `MaleText_loc7`='Y la muerte...' WHERE `ID`=18057;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 소소한 마법을 손보고 있지만 말이오...', `MaleText_loc4`='我仍然在解决一些无足轻重的细节……', `MaleText_loc5`='我還在矯正一些小細節...', `MaleText_loc7`='Sigo resolviendo algunos detalles sin importancia...' WHERE `ID`=18058;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 가루즈에게 우리가 성공했다는 소식을 전해 주십시오.', `MaleText_loc4`='$n，答应我你会把我们胜利的消息告诉加鲁斯。', `MaleText_loc5`='$n，請確實的將我們的成功轉告加魯。', `MaleText_loc7`='$n, comunica a Gahruj nuestro éxito.' WHERE `ID`=18059;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수천 명의 사람들이 하늘 위에서 우리를 바라보던 그 꿈...', `MaleText_loc4`='那是个成千上万的人们都从天上看着我们的地方……', `MaleText_loc5`='就是那數千個人從天空中俯視著我們的地方...', `MaleText_loc7`='Donde nos observan miles de personas desde el cielo...' WHERE `ID`=18060;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 그들의 꼭두각시 인형처럼 춤추고, 울고, 싸우고, 어리석은 말을 하면서 그들을 즐겁게 했지요.', `MaleText_loc4`='我们就像他们的傀儡——我们不管做什么都是为了让他们开心。', `MaleText_loc5`='我們就像他們的傀儡一樣 - 我們跳舞、哭泣、戰鬥並且說傻話供他們娛樂。', `MaleText_loc7`='Somos como sus marionetas – bailamos, lloramos, luchamos y decimos cosas estúpidas para que se diviertan.' WHERE `ID`=18061;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가끔 깨어 있을 때도 그들이 우리를 바라보고 있다고 생각합니다. 아마 지금 이순간도 지켜보고 있겠지요...', `MaleText_loc4`='有时候，甚至在我清醒的时候，我都觉得他们正监视着我们。也许他们现在正监视着我们……', `MaleText_loc5`='有時，即使當我醒著的時候，我也認為他們正看著我們。或許他們現在正看著我們...', `MaleText_loc7`='A veces, hasta cuando estoy despierto, creo que nos están observando. Quizás lo estén haciendo ahora mismo...' WHERE `ID`=18062;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 가지고 온 게 9개나 더 있어서 다행이군. 이건 나중에 끝내야겠어.', `MaleText_loc4`='你给我们带来了另外九个真是件好事。我想我一会就会完成这个的。', `MaleText_loc5`='幸好你又幫我們多帶了9個來。我想我稍後就可以完成了。', `MaleText_loc7`='Me alegro de que nos trajeras nueve más. Creo que dejaré esto para más tarde.' WHERE `ID`=18063;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만, 에드! 내 배를 보지 않겠소? *딸꾹*', `MaleText_loc4`='等等，艾德华！让我给你看看我的船！*嗝*', `MaleText_loc5`='嘿，等一下!讓你們看一下我的船!*打嗝*', `MaleText_loc7`='¡Para, Ed! ¡Deja que te enseñe mi nave! Hips.' WHERE `ID`=18064;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋소! 앞장서시오, 샌더스!', `MaleText_loc4`='带路吧，杉德尔！', `MaleText_loc5`='帶路吧，桑德斯!', `MaleText_loc7`='¡Tú delante, Sanders!' WHERE `ID`=18065;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐 하는 거요, 샌더스?', `MaleText_loc4`='你在干什么，杉德尔？', `MaleText_loc5`='你在做什麼，桑德斯?', `MaleText_loc7`='¿Qué haces, Sanders?' WHERE `ID`=18066;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리를 미행하는 사람은 없는지 확인하려는 것뿐이오. *딸꾹*', `MaleText_loc4`='我只是在确保没人跟踪我们！*嗝*', `MaleText_loc5`='我只不過是在確定我們沒被跟蹤!*打嗝*', `MaleText_loc7`='¡Solo mirificaba que no nos siguieran nadie! Hips.' WHERE `ID`=18067;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음... 괜찮군, 갑시다.', `MaleText_loc4`='很安全……', `MaleText_loc5`='很清楚的...', `MaleText_loc7`='P''alante.' WHERE `ID`=18068;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기 있구려! 아름답지 않소이까?', `MaleText_loc4`='就是她！很漂亮吧？', `MaleText_loc5`='就是她!她夠美嗎?', `MaleText_loc7`='¡Eso ser ella! ¿No es una belleza?' WHERE `ID`=18069;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇군, 정말 아름답소이다. 근데 내 범선 바로 옆에 정박해 놓았군! *딸꾹*', `MaleText_loc4`='是的，她真漂亮。而且你还把她停在了我的护卫舰旁边！*嗝*', `MaleText_loc5`='嗯，她的確是個美人。而你把她泊在我的護衛艦旁邊!*打嗝*', `MaleText_loc7`='Sí, sí que es una belleza. ¡Y la has aparcado al lado de mi fragata! *hic*' WHERE `ID`=18070;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 저 괴물 녀석이 당신 배요? 아... 정말 크군!', `MaleText_loc4`='那个怪物是你的，艾德华？啊……她真大啊！', `MaleText_loc5`='那個怪物是你們家的嗎，喂?呃...她很大隻!', `MaleText_loc7`='¿Es tuyo ese monstruo, Ed? Arrr... ¡Es grande!' WHERE `ID`=18071;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하! 저 녀석이 내 범선이라오... 저 녀석을 타고 온 세상을 항해할 것이오. 저 바다 건너!', `MaleText_loc4`='是的！她是我的……我准备用她穿越大海，穿越整个世界！', `MaleText_loc5`='耶!她全部都是屬於我的...我要駕駛她航行全世界。穿過這片海洋!', `MaleText_loc7`='¡Eh! Es todo mío... Navegaré alrededor del mundo con él. ¡Por todos los mares!' WHERE `ID`=18072;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 에드! 정말 항해에 적합한 배요!', `MaleText_loc4`='啊，艾德华！她看上去的确很适合航海啊！', `MaleText_loc5`='阿，喔!她很明確地適於航海!', `MaleText_loc7`='¡Ar, Ed! ¡Sí señor! ¡Por todos los bares!... Quícir, por todos los mares...' WHERE `ID`=18073;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런데... 샌더스, 저 상자 안에는 뭐가 들어 있소?', `MaleText_loc4`='杉德尔，那个箱子里面是什么？', `MaleText_loc5`='桑德斯，你那個箱子裡裝著什麼東西?', `MaleText_loc7`='Sanders, ¿qué guardas en ese cofre?' WHERE `ID`=18074;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에드, 비밀 지킬 수 있소? 아, 죽은 사람은 말을 못하지!', `MaleText_loc4`='你能保密吗，艾德华？啊，死人是不会说话的！', `MaleText_loc5`='呃，你們能保守秘密嗎?阿，死人才不會告密!', `MaleText_loc7`='¿Puedes guardar un secreto, Ed? ¡Arr, los muertos no cuentan historias!' WHERE `ID`=18075;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 고개를 끄덕입니다.', `MaleText_loc4`='%s点了点头。', `MaleText_loc5`='%s點點頭。', `MaleText_loc7`='%s asiente con la cabeza.' WHERE `ID`=18076;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 보물이라오, 에드. 평생 모은 것이지! 아... 해적의 왕에게 어울리는 하얀 셔츠와!', `MaleText_loc4`='那是我的宝贝，艾德华。我毕生的心血！啊……一件适合海盗之王穿的白色衬衣！', `MaleText_loc5`='這是我的財寶，呃。我的畢生成就!阿...一件適合海賊王穿著的白色襯衫!', `MaleText_loc7`='Es mi tesoro, Ed. ¡El trabajo de mi vida! Arrr... Una camisa blanca adecuada para que la lleve un rey de piratas!' WHERE `ID`=18077;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='허리에 두르는 빨간색 장식띠. 자랑스러운 장식띠이지...', `MaleText_loc4`='一块你可以系在头上或腰上的红色饰带。那饰带是舰队的荣耀……', `MaleText_loc5`='一條能套在你們頭上或者馬褲上的紅飾帶。代表著艦隊的榮譽，飾帶的意義...', `MaleText_loc7`='Una faja roja que te puedes poner en la cabeza o en los calzones. Esa faja es el orgullo de la flota...' WHERE `ID`=18078;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마지막으로 아주 커다란 전리품 자루라오! 사과를 8개나 채울 수 있을 정도로 크지! 8개란 말이오, 에드! 믿어지오?', `MaleText_loc4`='还有，一个巨大的包！足够装下八个苹果的包！八个啊，艾德华！你能相信吗！？', `MaleText_loc5`='最後但肯定不是唯一的，一個巨大的袋子!大得足以裝入8顆蘋果!8顆耶!你們能相信它有多好嗎!?', `MaleText_loc7`='Y, por último, pero, sin duda, no menos importante, ¡la bolsa enorme! ¡Lo suficientemente grande como para meter ocho manzanas enteras! ¡Ocho, Ed! ¡¿Puedes creerlo!?' WHERE `ID`=18079;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 숨을 헐떡거립니다.', `MaleText_loc4`='%s剧烈地喘息起来。', `MaleText_loc5`='%s喘息著。', `MaleText_loc7`='%s suspira.' WHERE `ID`=18080;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악! 조용히 합시다, 에드! 악당들이 근처에 있소이다! 저자들을 귀가 밝아서 방금 당신이 낸 소리도 다 들을 수가 있단 말이오!', `MaleText_loc4`='当然！小声点，艾德华！那些无赖汉就在附近！他们的耳朵正听着刚从你嘴里溜出去的那些话！', `MaleText_loc5`='阿!小聲點，呃!這是那群飯桶唯一有用的地方!他們的飯桶耳朵專門聽像是剛從你的嘴唇蹦出來的喘氣聲!', `MaleText_loc7`='¡Aaar! ¡Callarse, Ed! Hay moros en la costa. Ya sabes. Orejas puestas en todo. Incluso en los suspiros que se te escapan.' WHERE `ID`=18081;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미안하오, 샌더스. 이렇게 대단한 물건을 본 적이 없어서 말이오. 깜짝 놀랐소이다.', `MaleText_loc4`='对不起，杉德尔。我只是从未看到过这样的好东西。这让我太吃惊了。', `MaleText_loc5`='很抱歉，桑德斯。我只是從未見過這麼豐碩的收穫，使我大吃一驚。', `MaleText_loc7`='Lo siento, Sanders. Nunca he visto tal recompensa. Me ha cogido por sorpresa.' WHERE `ID`=18082;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='괜찮소, 에드. 상자는 단단히 잠겨 있으니 걱정하지 마시오. 아무도 이 샌더스의 보물에 손대지 못하오! 자, 가서 한잔 더 합시다. 술기운이 떨어지는군.', `MaleText_loc4`='没事的，艾德华。我的战利品都好好地锁在那只箱子里面。永远没有人能得到杉德尔船长的财宝了！让我再去喝一杯。我的情绪有点开始消沉了。', `MaleText_loc5`='沒問題的，呃。我的財寶都在那個箱子內鎖得好好的。世界上沒有一個傻瓜可以擁有桑德斯船長的財寶!讓我們再去喝一杯。我有點無精打采。', `MaleText_loc7`='Está bien, Ed. Mi botín está bien guardado en aquel cofre. ¡Ningún estúpido tendrá jamás el tesoro del capitán Sanders! Vayamos a por otra bebida. El humor está por los suelos.' WHERE `ID`=18083;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='목소리를 낮춰주시기 바라오, 여러분! 이 여관에 낯선 자들이 있소이다...', `MaleText_loc4`='小声点。周围有陌生人……', `MaleText_loc5`='小聲點。附近有許多陌生人...', `MaleText_loc7`='Bajad la voz. Hay extraños rondando...' WHERE `ID`=18084;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형제자매 여러분, 오늘 여러분을 이렇게 청한 것은 로데론의 운명에 대해 논하기 위함이오.', `MaleText_loc4`='兄弟姐妹们，今天我把你们召集到这里，是为了讨论洛丹伦的命运。', `MaleText_loc5`='各位手足同胞，我今天召集你們到這裡來討論羅德隆的命運。', `MaleText_loc7`='Hermanos y hermanas, os he convocado para hablar del destino de Lordaeron.' WHERE `ID`=18085;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 작은 소리로 속삭입니다.', `MaleText_loc4`='%s放低了他的声音。', `MaleText_loc5`='%s降低他的聲音低聲耳語。', `MaleText_loc7`='%s baja la voz hasta convertirse en un susurro.' WHERE `ID`=18086;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 소식을 접했습니다만... 믿고 싶지 않은 일이오.', `MaleText_loc4`='我听说发生了一些事情……一些不应该发生的事情。', `MaleText_loc5`='我聽到一些事情...不應該是這樣的事情。', `MaleText_loc7`='Oigo cosas... Cosas que no deberían ser.' WHERE `ID`=18087;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽은 자들의 부활... 얼어붙은 북쪽 땅에서 온 언데드. 로데론의 도시들이 통째로 사라지는... 그런... 믿을 수가 없지만...', `MaleText_loc4`='死者复生……亡灵，在诺森德那片冰冷的大陆。整个城市突然消失得无影无踪。我……', `MaleText_loc5`='死者復甦...成為不死之身，從北方的結凍大地而來。整座都城市失蹤了。我...', `MaleText_loc7`='Los muertos se levantan... No-muertos, de las tierras heladas del norte. Han desaparecido ciudades enteras. Yo...' WHERE `ID`=18088;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 노스렌드도 파괴되었다고 하오.', `MaleText_loc4`='我听说诺森德已经沦陷了……', `MaleText_loc5`='我聽說北裂境已經失落了...', `MaleText_loc7`='He oído que Rasganorte se ha perdido...' WHERE `ID`=18089;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놀라움과 탄성이 여관을 가득 채웁니다.', `MaleText_loc4`='惊讶的声音传遍了整个房间。', `MaleText_loc5`='喘氣聲可在整個房間聽到。', `MaleText_loc7`='Se oyen suspiros por toda la sala.' WHERE `ID`=18090;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 대비를 해야 하오. 전에 언데드와 마주한 적이 있소만 그들은 감정이나 동정심이라곤 전혀 없는 무자비한 살인 기계요.', `MaleText_loc4`='我们必须随时准备好。我曾经面对过这些亡灵。他们是残忍的杀人机器，毫无同情和怜悯。', `MaleText_loc5`='我們必須準備妥當。我以前曾面對過不死怪物。他們是殘酷的殺人機器，缺乏任何情感或者同情心。', `MaleText_loc7`='Hay que estar preparados. Me he enfrentado a no-muertos. Son máquinas de matar despiadadas, sin emociones ni compasión.' WHERE `ID`=18091;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 고개를 끄덕입니다.', `MaleText_loc4`='%s点了点头。', `MaleText_loc5`='%s點點頭。', `MaleText_loc7`='%s asiente con la cabeza.' WHERE `ID`=18092;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동감하오, 나도 그들과 맞서 싸워봤소이다. 그런 공격에 맞서기에 우리는 아직 준비가 덜 됐소이다.', `MaleText_loc4`='是的，我也和他们交手过。我们的王国还没有准备好抵挡这种进攻。', `MaleText_loc5`='嗯，我也與他們戰鬥過。以一個國家應有的防禦工事來講，我們根本還沒有準備好應付如此難纏的敵人。', `MaleText_loc7`='Sí, también he luchado contra ellos. Como reino, estamos mal preparados para resistir tal ataque.' WHERE `ID`=18093;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 생각은 어떻습니까, 모그레인 경?', `MaleText_loc4`='你有什么建议吗，莫格莱尼？', `MaleText_loc5`='你有什麼好提議呢，莫格萊尼?', `MaleText_loc7`='¿Qué propones, Mograine?' WHERE `ID`=18094;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계획말이오? 물론 언데드의 침략에 준비를 하여야 하오이다. 사랑하는 가족과 친구들을 위해 언데드의 공격 가능성에 대비해야 하는 것이오.', `MaleText_loc4`='建议？我建议我们现在就准备起来。为亡灵可能对我们的爱人、家人和朋友展开的屠杀准备起来。', `MaleText_loc5`='提議嗎?我提議我們做好準備。讓我們摯愛的親人，家庭和朋友準備好經歷一場不死怪物大屠殺的可能性。', `MaleText_loc7`='¿Proponer? Propongo que nos preparemos. Que preparemos a nuestros seres queridos, familia y amigos para la posibilidad de un holocausto de los no-muertos.' WHERE `ID`=18095;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 내게 이게 있소이다...', `MaleText_loc4`='就是这个……', `MaleText_loc5`='還有這個...', `MaleText_loc7`='Y está esto...' WHERE `ID`=18096;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 상자를 엽니다.', `MaleText_loc4`='%s打开了箱子。', `MaleText_loc5`='%s打開箱子的鎖。', `MaleText_loc7`='%s abre el cofre con llave.' WHERE `ID`=18097;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런! 그게 뭡니까?', `FemaleText_loc4`='以圣光的名义！这是什么？', `FemaleText_loc5`='以聖光之名!那是什麼?', `FemaleText_loc7`='¡Por la Luz! ¿Qué es eso?' WHERE `ID`=18098;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='10년간 이 물건이 내 손에 있었소이다. 검은바위 첨탑 때부터 ...', `MaleText_loc4`='我得到这个东西已经有十年了。自从黑石塔……', `MaleText_loc5`='我已經持有這樣東西10年了。自從黑石塔...', `MaleText_loc7`='He tenido este objeto en mi poder diez años. Desde la cumbre de Roca Negra...' WHERE `ID`=18099;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오크족 부관이던 흑마법사의 시체에서 이 물건을 얻었소이다. 이 물건은 오크들의 고향에서 온 것이오.', `MaleText_loc4`='我把它从一个兽人军官……一个黑暗的施法者的遗体上拿了下来……这是从他们的家乡带来的。', `MaleText_loc5`='我從一個獸人中尉的屍體上扯下它 - 一個黑暗的法器...來自他們的祖國。', `MaleText_loc7`='Lo arranqué de los restos de un teniente orco – un taumaturgo oscuro... Es de su mundo.' WHERE `ID`=18100;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 가까이 접근하지 마시오. 딱 한 번이었지만... 전에 그 물건에 손을 올린 적이 있소이다. 지금도 그때 생각이 생생하구려.', `MaleText_loc4`='不要太靠近了。我曾经把手放在上面……就那么一次。那天的记忆至今仍然在我脑海里浮现。', `MaleText_loc5`='不要靠得太近。我曾經染指過它...僅僅一次，從此不敢重蹈覆轍。我仍然忘不了那天的記憶。', `MaleText_loc7`='No te acerques demasiado. Una vez le puse la mano encima... Solo una vez y nunca más. Los recuerdos de aquel día aún perduran.' WHERE `ID`=18101;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 건틀릿을 벗고 상처가 난 팔을 모두에게 보여 줍니다.', `MaleText_loc4`='%s从他的右臂上脱下了手套，在大家面前露出了他那扭曲的手。', `MaleText_loc5`='%s自他的右臂脫下護手鎧甲並且讓每個人看他嚴重受創的手。', `MaleText_loc7`='%s se quita el guantelete de su brazo derecho y muestra a todo el mundo su mano destrozada.' WHERE `ID`=18102;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 물건은 살아있는 어둠의 형상이라고 생각하오... 현신이자 또한 공허요.', `MaleText_loc4`='我猜想这个东西是暗影的实体化身……黑暗的表象。它是一块虚空的领域。', `MaleText_loc5`='我推測這樣東西是暗影...黑暗的化身...它是一種邪惡的象徵。它不屬於這個世界。', `MaleText_loc7`='Supongo que este objeto es la encarnación viviente de las Sombras... la oscuridad... Es una manifestación. Es un vacío.' WHERE `ID`=18103;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 사악한 유물이 어떻게 언데드와 관련이 있다는 것인지 이해가 되지 않네, 모그레인. 우리가 저 물건을 파괴해야 해!', `MaleText_loc4`='我不知道这个邪恶的东西会跟亡灵有什么关系。我们必须摧毁它！', `MaleText_loc5`='我看不出這個邪惡的法器對不死怪的重要性。我們必須破壞它!', `MaleText_loc7`='No veo cómo puede este artefacto maligno ser relevante para los no-muertos. ¡Debemos destruirlo!' WHERE `ID`=18104;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사절 탈룬은 우리의 새로운 동지들에게 이 세계의 정령에 대해 가르치라고 절 여기로 데려왔지요... 하지만 아무도 제 말을 듣지 않는군요.', `MaleText_loc4`='塔卢恩大使把我一起带过来，希望我可以向我们的新伙伴们传授关于这个世界上的元素的知识……但没人愿意听。', `MaleText_loc5`='大使塔魯恩要我同行是希望我能教導我們的新盟友關於這個世界的元素...但是沒有人願意聽。', `MaleText_loc7`='El emisario Taluun me trajo consigo esperando que pudiera enseñar a nuestros nuevos aliados cosas sobre los elementos de este mundo... pero nadie escucha.', `FemaleText_loc1`='사절 탈룬은 우리의 새로운 동지들에게 이 세계의 정령에 대해 가르치라고 절 여기로 데려왔지요... 하지만 아무도 제 말을 듣지 않는군요.', `FemaleText_loc4`='塔卢恩大使把我一起带过来，希望我可以向我们的新伙伴们传授关于这个世界上的元素的知识……但没人愿意听。', `FemaleText_loc5`='大使塔魯恩要我同行是希望我能教導我們的新盟友關於這個世界的元素...但是沒有人願意聽。', `FemaleText_loc7`='El emisario Taluun me trajo consigo esperando que pudiera enseñar a nuestros nuevos aliados cosas sobre los elementos de este mundo... pero nadie escucha.' WHERE `ID`=18105;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 고개를 젓습니다.', `MaleText_loc4`='%s摇了摇头。', `MaleText_loc5`='%s搖了搖頭。', `MaleText_loc7`='%s niega con la cabeza.' WHERE `ID`=18106;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아닐세, 내 오랜 친구여. 관련이 아주 많다네.', `MaleText_loc4`='不，老朋友，这很有关系。', `MaleText_loc5`='不，老朋友，它的關係重大。', `MaleText_loc7`='No, $gviejo amigo:vieja amiga;, es muy relevante.' WHERE `ID`=18107;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 형제자매들이여, 한가지 묻겠소. 악이 없다면 선이 존재할 수 있소? 어둠이 없는데 빛의 존재 이유가 뭐란 말이오?', `MaleText_loc4`='让我来问你们一个问题，兄弟姐妹们：善可以离开恶而存在吗？光明可以离开黑暗而存在吗？', `MaleText_loc5`='各位手足同胞們，讓我問你們︰少了邪惡，善良能單獨存在嗎?少了黑暗，還能有光明嗎?', `MaleText_loc7`='Dejadme haceros esta pregunta, hermanos y hermanas: ¿puede existir el bien sin el mal? ¿Puede haber luz sin oscuridad?' WHERE `ID`=18108;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악이 있어야 선도 존재할 수 있다면, 이 유물이 존재함으로써 정반대의 성질을 가진 물건도 존재할 수 있지 않겠소?', `MaleText_loc4`='如果答案是否定的，那么这很可能就是它存在的原因，这个东西的另一个极端是否也必然存在呢？', `MaleText_loc5`='而如果那個答案是否定的，那麼有可能是因為這個邪惡法器的存在，所以才有善良勢力的存在嗎?', `MaleText_loc7`='Y, si la respuesta es no, ¿puede ser posible que, porque este artefacto existe, su contrario también debe existir?' WHERE `ID`=18109;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성스러운 빛의 현신이 언데드에게 얼마나 큰 타격을 미칠지 상상이 되오?', `MaleText_loc4`='你们能否想象圣光的实体会对亡灵造成什么样的破坏？', `MaleText_loc5`='你能想像聖光的力量可以對不死怪物的肉身造成什麼樣的傷害嗎?', `MaleText_loc7`='¿Podéis imaginar lo que la manifestación material de la Luz podrías hacer contra los no-muertos?' WHERE `ID`=18110;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사절 탈룬은 우리의 새로운 동지들에게 이 세계의 정령에 대해 가르치라고 절 여기로 데려왔지요. 하지만 이들은 제 말을 들으려 하지 않는군요. 당신은 어떻습니까?', `MaleText_loc4`='塔卢恩大使把我一起带过来，希望我可以向我们的新伙伴们传授关于这个世界上的元素的知识……但迄今为止他们都拒绝听这些，也许你愿意听听？', `MaleText_loc5`='大使塔魯恩要我同行是希望我能教導我們的新盟友關於這個世界的元素。目前沒有人願意聽，但也許你有興趣聽嗎?', `MaleText_loc7`='El emisario Taluun me trajo consigo esperando que enseñara a nuestros nuevos aliados cosas acerca de los elementos de este mundo. Hasta ahora, se niegan a escuchar, pero, ¿quizás tú lo harías?', `FemaleText_loc1`='사절 탈룬은 우리의 새로운 동지들에게 이 세계의 정령에 대해 가르치라고 절 여기로 데려왔지요. 하지만 이들은 제 말을 들으려 하지 않는군요. 당신은 어떻습니까?', `FemaleText_loc4`='塔卢恩大使把我一起带过来，希望我可以向我们的新伙伴们传授关于这个世界上的元素的知识……但迄今为止他们都拒绝听这些，也许你愿意听听？', `FemaleText_loc5`='大使塔魯恩要我同行是希望我能教導我們的新盟友關於這個世界的元素。目前沒有人願意聽，但也許你有興趣聽嗎?', `FemaleText_loc7`='El emisario Taluun me trajo consigo esperando que enseñara a nuestros nuevos aliados cosas acerca de los elementos de este mundo. Hasta ahora, se niegan a escuchar, pero, ¿quizás tú lo harías?' WHERE `ID`=18111;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말도 안 되네, 모그레인! 반드시 파괴해야 하네!', `MaleText_loc4`='一派胡言，莫格莱尼！这东西必须被摧毁掉！', `MaleText_loc5`='胡說八道，莫格萊尼!它必須被銷毀!', `MaleText_loc7`='¡Tonterías, Mograine! ¡Debe ser destruido!' WHERE `ID`=18112;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='충격으로 인해 사람들이 말을 잃었습니다.', `MaleText_loc4`='众人震惊了片刻，随即是一片沉默。', `MaleText_loc5`='人們先是感到震驚然後接著沉默。', `MaleText_loc7`='Una conmoción, y después, silencio, sorprende a la multitud.' WHERE `ID`=18113;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실례하겠습니다, $c|1이여;여;. 전 아무리 지루해도 사절이신 선소로우님을 보살펴 드려야 합니다.', `MaleText_loc4`='离我远点，$c。我必须要和他们一样，傻乎乎地保护银月大使欧诺·炎伤。', `MaleText_loc5`='讓我靜一靜，$c。我必須致力於我對憂日大使的職責，雖然這些工作是非常單調乏味的。', `MaleText_loc7`='Déjame, $c. Debo atender mis obligaciones con el embajador Penasol, por más aburridos que sean.', `FemaleText_loc1`='실례하겠습니다, $c|1이여;여;. 전 아무리 지루해도 사절이신 선소로우님을 보살펴 드려야 합니다.', `FemaleText_loc4`='离我远点，$c。我必须要和他们一样，傻乎乎地保护银月大使欧诺·炎伤。', `FemaleText_loc5`='讓我靜一靜，$c。我必須致力於我對憂日大使的職責，雖然這些工作是非常單調乏味的。', `FemaleText_loc7`='Déjame, $c. Debo atender mis obligaciones con el embajador Penasol, por más aburridos que sean.' WHERE `ID`=18114;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='샤타르에서는 어둠달 골짜기와 일리단의 일에 집중하고 있지만 우리 알도르 사제회에서는 캘타스 선스트라이더의 위협을 무시할 수 없습니다.', `FemaleText_loc4`='当沙塔尔继续把他们的注意力放在影月谷和伊利丹身上时，我们同样不能无视凯尔萨斯·逐日者带来的威胁。', `FemaleText_loc5`='儘管薩塔的焦點依然著重在影月谷和伊利丹，我們仍然不能忽視凱爾薩斯·逐日者帶來的威脅。', `FemaleText_loc7`='Aunque la atención de los Sha''tar permanezca en el valle Sombraluna e Illidan, no podemos ignorar la amenaza que Kael''thas el Caminante del Sol supone.' WHERE `ID`=18115;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선소로우님을 지키는 일이 점점 지겹군요, $n 님. 저와 잠시 대련을 하시겠습니까? 우리 둘 중 하나는 뭔가 배울 수 있을 겁니다.', `MaleText_loc4`='我对保护银月大使欧诺·炎伤感到有点厌烦了，$n。你有空和我聊聊吗？或许我们能彼此学到些什么？', `MaleText_loc5`='我對保護憂日大使感到厭煩，$n。介意跟我談談嗎?或許我們之中有人可以學到一些事情。', `MaleText_loc7`='Me aburro de proteger al embajador Penasol, $n. ¿Quieres practicar un poco de lucha? Quizás uno de los dos aprenda algo.', `FemaleText_loc1`='선소로우님을 지키는 일이 점점 지겹군요, $n 님. 저와 잠시 대련을 하시겠습니까? 우리 둘 중 하나는 뭔가 배울 수 있을 겁니다.', `FemaleText_loc4`='我对保护银月大使欧诺·炎伤感到有点厌烦了，$n。你有空和我聊聊吗？或许我们能彼此学到些什么？', `FemaleText_loc5`='我對保護憂日大使感到厭煩，$n。介意跟我談談嗎?或許我們之中有人可以學到一些事情。', `FemaleText_loc7`='Me aburro de proteger al embajador Penasol, $n. ¿Quieres practicar un poco de lucha? Quizás uno de los dos aprenda algo.' WHERE `ID`=18116;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악마의 물체가 빛을 삼켜 버렸습니다!', `MaleText_loc4`='它吞噬了圣光！', `MaleText_loc5`='它充滿聖光的力量!', `MaleText_loc7`='¡Ha consumido la Luz!' WHERE `ID`=18117;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 말도 안 되는 일이!', `MaleText_loc4`='这不可能！', `MaleText_loc5`='不可能!', `MaleText_loc7`='¡Imposible!' WHERE `ID`=18118;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<긴급 차단 시스템 가동>', `MaleText_loc4`='<启动紧急停机。>', `MaleText_loc5`='<啟動緊急關閉程序。>', `MaleText_loc7`='<Lanzar apagado de emergencia.>', `FemaleText_loc1`='<긴급 차단 시스템 가동>', `FemaleText_loc4`='<启动紧急停机。>', `FemaleText_loc5`='<啟動緊急關閉程序。>', `FemaleText_loc7`='<Lanzar apagado de emergencia.>' WHERE `ID`=18119;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제어장치에 다가가자 당신이 지니고 있는 장치 접근 수정이 부드럽게 진동하더니 빛과 함께 공명하기 시작합니다.$B$B수많은 정보의 물결이 머릿속으로 흘러들어오고 갑자기 마나괴철로의 에너지 생산 수치, 안정성, 다른 수송관으로의 출력 등을 알게 됩니다. 지금 당신 눈앞에 있는 제어장치가 명령을 기다리고 있습니다.', `MaleText_loc4`='当你靠近控制器时，你带着的那块控制水晶开始慢慢地发出蜂鸣，光芒在水晶上面跳动。$B$B突然在你的脑海里浮现出了法力熔炉的各种能量生产标准，它的稳定性和它到不同管道的输出量。控制器正等待着你的命令。', `MaleText_loc5`='當你接近控制台時，你身上的控制水晶發出輕柔的嗡嗡聲以及一陣陣光源的脈動。$B$B一陣訊息突然湧入你的腦海，突然之間你明瞭了法力熔爐的能量生產水準，它的產量穩定以及它透過不同的輸送管運送能源。控制台等待你的命令。', `MaleText_loc7`='A medida que te acercas a la consola, el cristal de acceso que tienes contigo comienza a zumbar suavemente y a emitir una luz parpadeante.$B$BUn torrente de información fluye hasta tu mente y, de repente, eres consciente de los niveles de producción de energía de la forja de maná, de su estabilidad y de su producción a diferentes tuberías. La consola aguarda tu orden.' WHERE `ID`=18120;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저게 점점... 밝아지고 있는 겁니까? 빛깔이... 변하고 있군요.', `MaleText_loc4`='它……它在变亮？它的颜色……正在改变。', `MaleText_loc5`='它...它變輕了嗎?它的顏色...它正在改變。', `MaleText_loc7`='¿Se está atenuando? Su color... está cambiando.' WHERE `ID`=18121;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 빛이여! 저럴 수가 있소? 이런 일이 일어나다니!', `MaleText_loc4`='以圣光的名义！真的是这样吗？这就是我们所需要的东西吗？', `MaleText_loc5`='以聖光之名!可能嗎?這有可能嗎?', `MaleText_loc7`='¡Por la Luz! ¿Será posible? ¿Será esto?' WHERE `ID`=18122;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알아내야 하오. 반드시 확인해야 돼...', `MaleText_loc4`='我必须知道……我会知道的……', `MaleText_loc5`='我一定要知道...我會知道的...', `MaleText_loc7`='Debo saber... y lo sabré...' WHERE `ID`=18123;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 빛의 수정을 향해 손을 내밉니다.', `MaleText_loc4`='%s伸出手去触摸光明水晶。', `MaleText_loc5`='%s伸出手去觸碰發光的水晶。', `MaleText_loc7`='%s saca el brazo para tocar el cristal de luz.' WHERE `ID`=18124;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건... 이건... 정말 아름답구려. 수정을 만졌을 때의 느낌이란... 성스러운 빛이 내 몸을 흐르고 나와 소통하였소이다... 나의 영혼이 치유된 것이오.', `MaleText_loc4`='太……太……太漂亮了。当我碰到它的时候，我感觉到……圣光在我体内流过，我觉得它……它治愈了我的灵魂。', `MaleText_loc5`='我...它...它是如此的美麗。當我接觸它時，我感覺到...一道溫暖的光源在它和我的身體之間循環...它治癒了我的心靈。', `MaleText_loc7`='Es... Es... Es hermoso. Lo que sentí mientras lo tocaba... La Luz fluía a través de mí y yo fluía en ella... Ha sanado mi alma.' WHERE `ID`=18125;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모그레인, 자네 손을 보게나! 자네 손의 상처가 사라졌군!', `MaleText_loc4`='你的手！伤口愈合了！', `MaleText_loc5`='你的手!痊癒了!', `MaleText_loc7`='¡Tu mano! ¡Se ha curado!' WHERE `ID`=18126;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 수정을 상자 안에 다시 넣습니다.', `MaleText_loc4`='%s把水晶放回了箱子。', `MaleText_loc5`='%s把水晶放回箱子裡。', `MaleText_loc7`='%s vuelve a poner el cristal en el cofre.' WHERE `ID`=18127;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앞으로 오늘 일에 대해 다시는 언급하지 말도록 하는 게 좋겠소. 적이 많소이다. 우리가 이런 유물을 가지고 있다는 것을 적들이 알면 아니 되오.', `MaleText_loc4`='让我们再也不要提起今天这件事情。我们有太多的敌人。他们不需要知道我们手中有这么一件宝贝。', `MaleText_loc5`='永遠都不要再提起今天。我們的敵人很多。不必讓他們知道我們擁有這種法器。', `MaleText_loc7`='No volvamos a hablar de este día. Nuestros enemigos son muchos. No tienen por qué saber que tenemos tales artefactos en nuestro poder.' WHERE `ID`=18128;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 상상한 적이 있소이다... 이 축복 받은 수정을 이용해 우리가 무기를 만드는 걸 말이오. 그 무기 속에는 우리 각자의 조그만 힘들이 살아 숨 쉴 것이오... 언데드와 싸울 때 그 무기를 사용하면 언데드가 쓰러질 것이며 싸움이 끝나면 파멸만이 남게 될 것이니...', `MaleText_loc4`='我看到了……我从这块神圣的水晶中看到了……我们会铸造一件武器。这件武器中包含着我们每个人的力量……当它面对亡灵时，它会释放出这种力量，毁灭它们。这把武器所到之处，留下的只有灰烬……', `MaleText_loc5`='我見過它的用途...我們將把這顆祝福的水晶鍛造成一種武器。這把武器將集結並保存我們每個人的一部分力量...當它被用來對付不死怪物時，它將打倒他們。並且在它的力量面前，一切都將化成灰燼...', `MaleText_loc7`='Lo he visto... De este cristal bendito forjaremos un arma. Este arma tendrá en su interior un pedazo de cada uno de nosotros... Y, cuando se use contra no-muertos, los desterrará. Y, a su paso, solo dejará cenizas...' WHERE `ID`=18129;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파멸의 인도자...', `MaleText_loc4`='灰烬使者……', `MaleText_loc5`='灰燼使者...', `MaleText_loc7`='La Crematoria...', `FemaleText_loc1`='파멸의 인도자...', `FemaleText_loc4`='灰烬使者……', `FemaleText_loc5`='灰燼使者...', `FemaleText_loc7`='La Crematoria...' WHERE `ID`=18130;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당장 멈춰라!', `MaleText_loc4`='马上停下来！', `MaleText_loc5`='立刻住手!', `MaleText_loc7`='¡Para inmediatamente!', `FemaleText_loc1`='당장 멈춰라!', `FemaleText_loc4`='马上停下来！', `FemaleText_loc5`='立刻住手!', `FemaleText_loc7`='¡Para inmediatamente!' WHERE `ID`=18131;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 고물을 고치면 도적들한테 습격받을 걱정 없이 장사를 다닐 수 있을 거야!', `MaleText_loc4`='当我让这块大垃圾工作起来之后，我就再也不用害怕那些强盗啦！', `MaleText_loc5`='當我得到這一大塊廢物上路的時候，我就可以安心的走在路上而不用懼怕匪徒的襲擊!', `MaleText_loc7`='¡Cuando consiga que este trozo de basura funcione, podré ir por los caminos sin temor a que los bandidos me asalten!' WHERE `ID`=18132;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조금만 더 하면 준비가 될 거야...', `MaleText_loc4`='再转上几圈就准备好了……', `MaleText_loc5`='再揮動幾次而它就準備好了...', `MaleText_loc7`='Un poco más y ya está...' WHERE `ID`=18133;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 물건들을 다른 고블린한테 팔아도 되겠지? 나는 부자가 될 거야! 부자가 된다고!', `MaleText_loc4`='也许我应该把这些东西卖给其他地精？我会变得很有钱！非常有钱！', `MaleText_loc5`='或許我能把這些東西賣給其他的哥布林?我將變成有錢人!我說有錢人!', `MaleText_loc7`='¿Quizás pueda vender estas cosas a otros goblins? ¡Seré rico! ¡Sí, rico!' WHERE `ID`=18134;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 직실이라는 이름이 지역 상표가 되는 것이지! 내가 시장을 독점하는 거야!', `MaleText_loc4`='没错，吉克希尔会变成一个家喻户晓的名字！我会垄断市场！', `MaleText_loc5`='是的，吉克希爾將是一個家喻戶曉的名字!我將壟斷市場!', `MaleText_loc7`='¡Sí, Zixil será un nombre que se pronunciará en todos los hogares! ¡Me haré con el mercado!' WHERE `ID`=18135;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어허, 내 망토에서 손을 치우시오! 물론 이 망토를 갖고 싶어하는 당신 마음은 이해하오. 모두가 내 망토를 갖고 싶어하지. 양심도 없고 사회에서 지위도 낮지만 난 이 망토들을 팔아서 부자가 될 것이오. 이곳에서 아이언포지까지의 모든 이들이 이 바르톨로 진세티의 이름을 듣게 될 것이란 말이오. 모두들 진세티표 상품들을 몹시도 탐낼 것이오!', `MaleText_loc4`='别动那张斗篷！没错，没错，我知道你也想要一件。每个人都想要一件我的斗篷。相信我，你这个卑微的家伙，总有一天我会靠出售我的斗篷赚到大钱。从铁炉堡到这里的每个人都会知道巴图罗·吉塞提的名字。吉塞提商标会成为令所有人垂涎欲滴的东西！', `MaleText_loc5`='別碰那件披風!是的，是的，我知道你也想要一件。所有人都想要我的披風。相信我，目前我只是個道德和社會地位低落的人，但是有一天我將靠賣我的披風而賺大錢。從這裡到鐵爐堡的所有人都將知道巴圖羅·吉塞提的名字。吉塞提標籤將成為炙手可熱的商品!', `MaleText_loc7`='¡No toques la capa! Sí, sí, ya sé que quieres una. Todo el mundo quiere una capa mía. Créeme, persona de clase baja y moral distendida, algún día me haré rico gracias a la venta de mis capas. Y todos, desde aquí hasta Forjaz, habrán oído hablar de Bartolo Ginsetti. ¡La marca Ginsetti será codiciada por todos!' WHERE `ID`=18136;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기, 잠시만! 그렇소, 당신. 잠시 이쪽으로 오시오. 할 말이 있소이다... 꼭 얘기해야 하는 게 있소. 나의 위대함이 묻혀버리면 안 되니까 말이오!', `MaleText_loc4`='嘿！叫你呢，你这个没礼貌的$G小伙子:小姑娘;。快过来，我得告诉你一些事情……让我跟你讲讲关于我的伟大事迹，不然人们都快将我的丰功伟绩忘得一干二净了！', `MaleText_loc5`='喂!是的，就是你，小農民。快過來，我必須告訴你某些事情...我必須把我的偉大之處告訴你，以免這樣的事情失傳了!', `MaleText_loc7`='¡Eh, tú! Sí, tú, $gcampesino:campesina;. Ven deprisa, debo decirte algo... ¡Debo hablarte de mi grandeza, no sea que tales cosas se pierdan en el vacío!' WHERE `ID`=18137;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우우우, 헙! 이 근육이 살아나는 내 옷을 좀 보시오. 멋진 망토와 어우러져 내 매력이 묻어나고 있지 않소?', `MaleText_loc4`='喔喔，耶！看看我鼓起的肌肉，感受我身体的温暖吧。', `MaleText_loc5`='噢，耶!看我高低起伏的肌肉組織。沐浴在我健壯體格的光輝裡。', `MaleText_loc7`='¡Aaaah! ¡Eh! Admira mi esculpido físico. Este cuerpo mío pasma a todos con sus armoniosas formas.' WHERE `ID`=18138;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진실을 말해 주십시오! 누가 배신을 할 것인지 말해 주십시오!', `MaleText_loc4`='我们要知道真相！让我们看看谁会背叛我们！', `MaleText_loc5`='告訴我們真相!告訴我們誰會成為背叛者!', `MaleText_loc7`='¡La verdad! ¡Dinos quién nos traicionará!' WHERE `ID`=18139;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 미친 짓입니다! 볼만큼 봤습니다! 그만!', `MaleText_loc4`='太疯狂了！我受够了！受够了！', `MaleText_loc5`='簡直是瘋了!我受夠了!夠了!', `MaleText_loc7`='¡Esto es una locura! ¡Ya basta! ¡BASTA!' WHERE `ID`=18140;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두들 들으세요!', `MaleText_loc4`='都给我听好了！！！', `MaleText_loc5`='大家注意聽好!', `MaleText_loc7`='¡ESCUCHADME TODOS!' WHERE `ID`=18141;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘난 모그레인 양반, 당신도 마찬가지입니다! 그 입 다무십시오!', `MaleText_loc4`='我也在和你说话，莫格莱尼先生！闭上你的嘴！', `MaleText_loc5`='我也在跟你講話，迷戀馬褲的莫格萊尼先生!閉上你的狗嘴!', `MaleText_loc7`='¡Hablo contigo, señor calzones elegantes Mograine! ¡CIERRA EL PICO!' WHERE `ID`=18142;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자자, 이 여관에 있는 모든 사람들, 소리를 낮추지 않으면 이 주방장 예센이 식칼을 들고 달려나올 겁니다! 내 말 알아들었소?!!!', `MaleText_loc4`='现在，这个酒吧里的人都给我闭嘴，否则杰森就要拔出他的铁钩和切肉刀，把你们剁成肉泥！都听明白了吗？！！', `MaleText_loc5`='現在，在這間酒吧的每個人都把音量放到最低，否則傑森將要拿出他的桿麵棍還有菜刀，並把你們全部剁成碎肉拿去餵獸人吃!每個人都聽清楚了嗎?!!!', `MaleText_loc7`='¡AHORA, todo el mundo en este bar va a mantener el ruido bajo mínimos o el viejo Jessen va a sacar la cuchilla y va a hacer el orco con todos ustedes! ¡¡¡¿LO HA ENTENDIDO TODO EL MUNDO?!!!' WHERE `ID`=18143;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아아아아!!!!! 제발 그만하십시오!', `MaleText_loc4`='啊啊啊啊啊啊啊！闭嘴！', `MaleText_loc5`='啊啊啊啊啊!!!閉嘴!', `MaleText_loc7`='¡AAAAAAAAAAAAAAAAAH! ¡SILENCIO!' WHERE `ID`=18144;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님을 실망시켜서는 안 된다.', `MaleText_loc4`='我们不能让主人失望。', `MaleText_loc5`='我們絕不能讓主人失望。', `MaleText_loc7`='No debemos fallarle al maestro.', `FemaleText_loc1`='주인님을 실망시켜서는 안 된다.', `FemaleText_loc4`='我们不能让主人失望。', `FemaleText_loc5`='我們絕不能讓主人失望。', `FemaleText_loc7`='No debemos fallarle al maestro.' WHERE `ID`=18145;
