UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 알겠습니다!', `MaleText_loc4`='遵命！', `MaleText_loc5`='是的，長官!', `MaleText_loc7`='¡Sí, señor!', `FemaleText_loc1`='네, 알겠습니다!', `FemaleText_loc4`='遵命！', `FemaleText_loc5`='是的，長官!', `FemaleText_loc7`='¡Sí, señor!' WHERE `ID`=18147;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은화 한 닢만 주시구려...', `MaleText_loc4`='施舍个银币吧，朋友？', `MaleText_loc5`='施捨一個銀幣嗎，朋友?', `MaleText_loc7`='¿Tienes un poco de plata para mí, $gamigo:amiga;?' WHERE `ID`=18148;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동전 한 개만 적선해 줍쇼. 돈은 곧 쓸모가 없을 거요... 종말이 머지않았다고...', `MaleText_loc4`='有多余的铜币吗？反正你很快就不再需要它了。世界末日快要来了……', `MaleText_loc5`='施捨一個銅錢嗎?不久之後你也用不到它。世界末日越來越近了...', `MaleText_loc7`='¿Un poco de cobre? No lo vas a necesitar. Se acerca el fin del mundo...' WHERE `ID`=18149;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음식 좀 나눠 주시구려...', `MaleText_loc4`='有吃的吗？', `MaleText_loc5`='你有多餘的食物嗎?', `MaleText_loc7`='¿Tienes algo de comida?' WHERE `ID`=18150;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제발, 배고픈 자식이 셋입니다! 음, 제가 세 명이라고 했나요? 열 명 배고픈 자식들이 아빠를 기다리고 있습니다!', `MaleText_loc4`='帮帮忙吧，$g先生:女士;,我有三个孩子等着吃饭呢！我说的是三个？不对，我有个十个饥饿的孩子等着吃饭呢！', `MaleText_loc5`='拜託你，$g先生:夫人;，我有3個飢餓的孩子要養!我說3個了嗎?是10個飢餓的孩子!', `MaleText_loc7`='Por favor, $gseñor:señora;, tengo tres niños pequeños... ¿Dije tres? ¡Tengo diez hijos hambrientos!' WHERE `ID`=18151;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐! 술을 드릴 테니 동전 한 닢만 적선해 줍쇼...', `MaleText_loc4`='嘿……给我点钱喝酒吧？', `MaleText_loc5`='喂...施捨一個銅錢讓我買酒嗎?', `MaleText_loc7`='Pssst... ¿Me das una piececita de cobre para el grog?' WHERE `ID`=18152;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음식을 받고 일을 하겠습니다... 일자리라도 좀...', `MaleText_loc4`='我愿意为食物而工作……', `MaleText_loc5`='我願意為了食物而工作...', `MaleText_loc7`='Trabajo por comida...' WHERE `ID`=18153;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구두를 닦아 드릴 테니 동전 한 닢만 줍쇼!', `MaleText_loc4`='让我擦亮你的鞋吧！只要一个铜币！', `MaleText_loc5`='讓我擦亮你的鞋!只要一個銅錢!', `MaleText_loc7`='¡Permíteme abrillantarte los zapatos! ¡Solo una pieza de cobre por el servicio!' WHERE `ID`=18154;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경고! $n|1이;가; %s 긴급 차단 시스템을 가동하였습니다. 2분 후에 차단이 완료됩니다.', `MaleText_loc4`='警告！%s的紧急停机程序已经启动。停机将在两分钟内完成。', `MaleText_loc5`='警告!%s緊急關閉程序已由$n啟動。將在二分鐘後完全關閉。', `MaleText_loc7`='¡Atención! $n ha iniciado el proceso de apagado de emergencia de %s. El apagado concluirá en dos minutos.' WHERE `ID`=18155;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='긴급 차단까지 1분 남았습니다.', `MaleText_loc4`='将在一分钟后完成紧急停机。', `MaleText_loc5`='緊急關閉程序將在一分鐘內完成。', `MaleText_loc7`='El apagado de emergencia concluirá en un minuto.' WHERE `ID`=18156;
