UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='술이 더 필요하십니까?', `FemaleText_loc4`='还要酒？', `FemaleText_loc5`='更多的烈酒嗎?', `FemaleText_loc7`='¿Más grog?' WHERE `ID`=18159;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='존, 이것 좀 보십시오. 이거 정말 멋진데요!', `MaleText_loc4`='乔纳森，看看。多壮观啊！', `MaleText_loc5`='喬，看看它。真是金碧輝煌!', `MaleText_loc7`='Mira, Jon. ¡Es glorioso!' WHERE `ID`=18160;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 그렇군요. 타렌 제분소와 남녘해안의 친선을 상징하는데 두 마을의 중간에 이 탑을 세우는 것보다 더 좋은 방법이 어디 있겠습니까! 훌륭합니다!', `MaleText_loc4`='确实。证明塔伦米尔和南海镇之间的友谊和兄弟关系的最佳方式，就是在两个镇子中间树立这座哨塔。多棒的点子啊！', `MaleText_loc5`='的確。還有什麼比在塔倫米爾和南海鎮這兩個鎮的中間建立起這座塔更能象徵彼此之間的友誼與手足關係。太棒了!', `MaleText_loc7`='Cierto. Qué mejor manera de reflejar los lazos de amistad y hermandad entre Molino Tarren y Costasur que una torre que marque el punto intermedio entre las dos ciudades. ¡Es brillante!' WHERE `ID`=18161;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 마나괴철로를 멈출 수는 없을 것이다, 쓰레기같은 것!', `MaleText_loc4`='卑贱的家伙，别想关闭我的法力熔炉！', `MaleText_loc5`='你無法關閉我的法力熔爐，敗類!', `MaleText_loc7`='¡No cerrarás mi forja de maná, escoria!' WHERE `ID`=18162;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 초록색 가스가 담긴 병을 깨뜨립니다.', `MaleText_loc4`='%s压碎了一只装满绿色气体的小瓶子。', `MaleText_loc5`='%s壓碎一瓶綠色氣體藥水瓶。', `MaleText_loc7`='%s rompe un vial de gas verde.' WHERE `ID`=18163;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛의 감시자의 임무는 두 가지입니다. 첫째로, 모든 힘을 다하여 사제회를 지키는 것... 두 번째는 곳곳에 숨어 있는 성스러운 빛의 적을 추적해 제거하는 것입니다.', `MaleText_loc4`='圣光护卫者的工作是双重的。保护传教士的安全是他们的首要任务，而消灭圣光的敌人是次要的。', `MaleText_loc5`='艾德伊恩的工作分成兩部份。首先最重要的是保護教士。再來是找出聖光的敵人並且消滅他們。', `MaleText_loc7`='El Celador de la Luz tiene una tarea doble. Proteger a la hermandad a cualquier precio en primer lugar. Y en segundo lugar, destruir a los enemigos de la Luz dondequiera que estén.' WHERE `ID`=18164;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아르도니스, 듀로 마나괴철로로 지원 병력을 보내라. 이것은 부탁이 아니라 명령이다.', `MaleText_loc4`='阿尔杜尼斯，我们要你派增援去法力熔炉：杜隆。这不是请求，而是命令。', `MaleText_loc5`='我們需要你派增援部隊給法力熔爐杜羅，艾登尼斯。這不是一個請求，這是命令。', `MaleText_loc7`='Necesitamos que envíes refuerzos a Forja de Maná Duro, Ardonis. No te lo pido por favor, es una orden.' WHERE `ID`=18165;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='설마 농담이겠죠?! 이 마나괴철로를 운영하기에도 인원이 턱없이 부족하단 말입니다!', `MaleText_loc4`='你不会是认真的吧！我们的人手已经严重不足，都快要不能维持法力熔炉的正常运作了！', `MaleText_loc5`='你不是認真的吧!我們的人手嚴重不足，並且只能勉強維持這個法力熔爐運作!', `MaleText_loc7`='¡No puedes hablar en serio! ¡Tenemos una seria falta de personal y apenas podemos hacer que esta forja de maná funcione!' WHERE `ID`=18166;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명령대로 해라. 듀로 마나괴철로가 마나 생명체의 공격을 받고 있으며 도저히 수습할 수 없는 상황이다. 명령 불복종은 용납하지 않는다!', `MaleText_loc4`='照我的吩咐做。法力熔炉：杜隆受到魔法生物的严重袭击，局势已然失控了。如果你们不按指示随意胡来，将受到最严厉的惩罚！', `MaleText_loc5`='你將照命令去做。法力熔爐杜羅已經受到法力魔物的沉重攻勢，情勢失去控制。違反軍令是不被允許的!', `MaleText_loc7`='Harás lo que se te ordene. La forja de maná Duro ha sufrido fuertes ataques por parte de criaturas de maná y la situación está fuera de control. ¡No se tolerará un incumplimiento!' WHERE `ID`=18167;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 진정 이 땅은 초토화 직전의 위기에 놓여있습니다. 2차 대전쟁이 끝나고 아직 사람들이 살아 있다는 게 놀라울 따름입니다.', `MaleText_loc4`='以穆拉丁的胡须之名，$c，这个地方已经濒临毁灭了。我无法想象居然有人可以在第二次战争结束后一直活到现在。', `MaleText_loc5`='以穆拉丁的鬍子起誓，$c。這塊土地瀕臨毀滅。我不能想像任何人從第二次戰爭結束後能在這裡倖存。', `MaleText_loc7`='Por la barba de Muradin, $c. Esta tierra está al borde de la aniquilación. No me puedo imaginar que alguien sobreviviera aquí desde el final de la segunda guerra.', `FemaleText_loc1`='$c|1이여;여;, 진정 이 땅은 초토화 직전의 위기에 놓여있습니다. 2차 대전쟁이 끝나고 아직 사람들이 살아 있다는 게 놀라울 따름입니다.', `FemaleText_loc4`='以穆拉丁的胡须之名，$c，这个地方已经濒临毁灭了。我无法想象居然有人可以在第二次战争结束后一直活到现在。', `FemaleText_loc5`='以穆拉丁的鬍子起誓，$c。這塊土地瀕臨毀滅。我不能想像任何人從第二次戰爭結束後能在這裡倖存。', `FemaleText_loc7`='Por la barba de Muradin, $c. Esta tierra está al borde de la aniquilación. No me puedo imaginar que alguien sobreviviera aquí desde el final de la segunda guerra.' WHERE `ID`=18168;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영역 트리거가 작동합니다.', `MaleText_loc4`='Area trigger works.', `MaleText_loc5`='範圍效果成功了。', `MaleText_loc7`='El activador de área funciona.' WHERE `ID`=18169;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 이것 좀 보라고! 피망치 특별주! 으음...', `MaleText_loc4`='哦，看！血槌啤酒！唔……', `MaleText_loc5`='喔，你看!血槌釀酒!嗯...', `MaleText_loc7`='¡Ohh, mira! ¡Cerveza Machacasangre! Mmmm...' WHERE `ID`=18170;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피망치 특별주? 내가 제일로 좋아하는 거잖아!', `MaleText_loc4`='血槌啤酒？我的最爱！', `MaleText_loc5`='血槌釀酒?我的最愛!', `MaleText_loc7`='¿Cerveza Machacasangre? ¡Mi preferida!' WHERE `ID`=18171;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음... 목 말라!', `MaleText_loc4`='嗯。渴死我了！', `MaleText_loc5`='嗯。我口渴!', `MaleText_loc7`='Mmm. ¡Tengo sed!' WHERE `ID`=18172;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 뭐지?', `MaleText_loc4`='这是什么？', `MaleText_loc5`='這是什麼?', `MaleText_loc7`='¿Qué es esto?' WHERE `ID`=18173;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미처 끝내지 못한 일을 도와줄 자를 구하고 있습니다.$B$B당신이라면 할 수 있을 것 같군요.', `MaleText_loc4`='我在找人来帮我完成那个拖了很久的任务。$B$B你似乎很适合。', `MaleText_loc5`='我正尋找某人幫助我做一項已經過期很久的任務。$B$B你看起來有這能力。', `MaleText_loc7`='Busco alguien que me ayude con una tarea que debería haberse acabado hace tiempo.$B$BPareces capaz.' WHERE `ID`=18174;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 파랄론 폐허에서 일을 처리해 준 덕분에 이제 한숨 놓았습니다. 이제 발굴단을 구성해서 폐허로 가려고 합니다.$B$B고맙습니다, $n.', `MaleText_loc4`='你在法兰伦废墟的努力让我回到了日程上。我正在召集我的队伍，准备向那里出发了。$B$B谢谢你，$n。', `MaleText_loc5`='你為我在法拉隆廢墟所做的工作已讓我趕上進度。我現在正集合我的部隊前往那邊去。$B$B感謝你，$n。', `MaleText_loc7`='Gracias a lo que hiciste por mí en las Ruinas de Farahlon ya no voy retrasado en mi plan de trabajo. Estoy reuniendo a mi equipo para salir.$B$BGracias, $n.' WHERE `ID`=18175;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불타는 군단의 악마들이 곳곳에 깔렸소이다... 우리가 이번 일을 해결해야 하오!', `MaleText_loc4`='到处都是燃烧军团……把它们全都干掉！', `MaleText_loc5`='到處都是燃燒軍團的成員...他們必須解決掉!', `MaleText_loc7`='La Legión está por todas partes... ¡hay que ocuparse de ellos!' WHERE `ID`=18176;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 덕분에 계획했던 대로 파랄론 폐허에서 작업을 시작할 수 있게 되었소이다.', `MaleText_loc4`='谢谢你，我们在法兰伦废墟的计划又可以顺利进行了。', `MaleText_loc5`='感謝你，我們才能繼續我們的法拉隆廢墟計畫。', `MaleText_loc7`='Gracias a ti, podremos seguir con nuestros planes en las Ruinas de Farahlon.' WHERE `ID`=18177;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='육체의 소유자여, 에테리얼에 대해서 뭘 알고 있소?$B$B서로 다른 종족 간의 전쟁임에도 불구하고 당신은 우리를 모두 같은 시각으로 바라보는군.$B$B이제 소개를 할 시간이 된 것 같군. 나는 자유연합의 사령관 야미르라고 하오. 또한 이 지역에 있는 공허의 생물과 에테리움을 처리할 수 있는 유일한 희망이기도 하지.', `MaleText_loc4`='你对虚灵了解多少，肉乎乎的家伙？$B$B毫无疑问，你肯定觉得我们全都一样，但却忘记了不同阵营之间的冲突和竞争。$B$B该是自我介绍的时候了，我是维序派的司令官阿米尔——如果你想要解决在这个区域横行霸道的虚空生物和复仇军，我是你唯一的希望。', `MaleText_loc5`='關於以太族你知道些什麼呢?$B$B你無疑地以相同的標準看我們全部，忘記了在不同派系之間的衝突和爭鬥。$B$B也該是介紹我自己的時候了。我是護國者的指揮官阿密爾 - 也是你在這地區內解決虛無生物和以太皇族充斥的唯一希望。', `MaleText_loc7`='¿Qué sabes de los etéreos, ser de carne?$B$BSin duda nos ves iguales a todos, e ignoras los conflictos y luchas entre las diferentes facciones.$B$BQuizás sea el momento para presentaciones. Soy el comandante Ameer del Protectorado – también tu única esperanza de resolver la infestación de criaturas del vacío y El Etereum en esta zona.' WHERE `ID`=18178;
