UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무우우우우우!', `MaleText_loc4`='哞！', `MaleText_loc5`='哞!', `MaleText_loc7`='¡Muuuuuu!' WHERE `ID`=18180;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='베시, 집에 돌아왔구나. 신이여, 감사합니다!', `MaleText_loc4`='贝希，你回来了。感谢圣光！', `MaleText_loc5`='貝絲，你在家。感謝聖光!', `MaleText_loc7`='Bessy, estás en casa. ¡Gracias a la Luz!' WHERE `ID`=18181;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런...', `MaleText_loc4`='噢，不……', `MaleText_loc5`='喔哦...', `MaleText_loc7`='Vaya...' WHERE `ID`=18182;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에테리움은 누구입니까?', `MaleText_loc4`='什么是复仇军？', `MaleText_loc5`='以太皇族是什麼?', `MaleText_loc7`='¿Qué es El Etereum?', `FemaleText_loc1`='에테리움은 누구인가요?', `FemaleText_loc4`='什么是复仇军？', `FemaleText_loc5`='以太皇族是什麼?', `FemaleText_loc7`='¿Qué es El Etereum?' WHERE `ID`=18183;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에테리움은 내 고향인 크아레쉬의 지배자들이었지. 비극적이게도 우린 공허의 군주 디멘시우스가 공허의 군대를 끌고 와 모든 것을 파괴하기 전에 대피를 해야만 했소. 이런 이유로 에테리움은 복수를 맹세했지. 그 후로 그들은 디멘시우스를 추적하였소...$B$B그러나 우리 자유연합은 디멘시우스 때문에 뭉치게 된 것은 아니오. 우리는 에테리움을 막기 위해 조직되었소.', `MaleText_loc4`='复仇军曾经是我们的家乡卡雷什的统治阶级。悲惨的是，在虚空领主迪门修斯释放他的虚空大军，吞噬一切阻挡他的生物前，我们被迫从卡雷什逃了出来。为此，复仇军发誓要报仇。从那时起，他们一直都在追踪迪门修斯……$B$B然而，维序派成立的初衷并不是为了对抗迪门修斯，而是复仇军。', `MaleText_loc5`='以太皇族是在我凱瑞西家鄉的統治階級。可悲的是，虛無領主迪曼修斯在世界上釋出他的虛無軍團，並且計畫完全毀滅所有阻礙他的人，在事情發生之前，我們只好被迫撤出凱瑞西。對這種行為，以太皇族發誓要復仇。他們從那以後一直跟蹤迪曼修斯...$b$b然而，護國者並不是一個反對迪曼修斯的團體。我們反對的是以太皇族。', `MaleText_loc7`='El Etereum era la clase gobernante de etéreos en mi mundo de K''aresh. Trágicamente, nos vimos obligados a evacuar K''aresh poco antes de que el señor del vacío, Dimensius, liberara sus ejércitos del vacío sobre el mundo y diezmara por completo todo lo que se hallaba a su paso. Por aquel acto, El Etereum juró venganza. Lleva siguiéndole la pista a Dimensius desde entonces...$B$BEl Protectorado, sin embargo, no fue una reacción a Dimensius. Fuimos una reacción a El Etereum.' WHERE `ID`=18184;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 얘긴지 이해가 가지 않습니다, 야미르.', `MaleText_loc4`='我不明白。你是什么意思，阿米尔？', `MaleText_loc5`='我不了解。 你是什麼意思，阿密爾?', `MaleText_loc7`='No comprendo. ¿Qué quieres decir, Ameer?', `FemaleText_loc1`='무슨 얘긴지 이해가 가지 않아요, 야미르.', `FemaleText_loc4`='我不明白。你是什么意思，阿米尔？', `FemaleText_loc5`='我不了解。 你是什麼意思，阿密爾?', `FemaleText_loc7`='No comprendo. ¿Qué quieres decir, Ameer?' WHERE `ID`=18185;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에테리움은 점점 어둡고 교활하게 변해 갔소. 그들은 오직 복수만을 생각하고 자신의 길을 막거나 자신과 함께 뜻을 같이하지 않는 자들을 적으로 간주했소. 많은 이들은 에테리움이 점점 미쳐 가는 것을 보고 떠나 버렸지. 에테리움의 몇몇 연합왕자들은 에테리움을 떠나 다른 조직을 만들고 다른 뜻을 품었소. 무역연합이 그 한 예이자 우리 자유연합도 마찬가지라오...', `MaleText_loc4`='复仇军在黑暗扭曲中成长。复仇变成了他们唯一的依靠，任何阻碍他们或者不愿意加入他们的人都会被他们认为是敌人。很多人因为看到复仇军陷入了疯狂而离开了他们。复仇军议会的几个节点亲王也离开复仇军，创立了其它一些有着不同目标的团体和阵营。星界财团就是其中之一，而维序派是另一个……', `MaleText_loc5`='以太皇族已經變得行為墮落...價值觀扭曲。報仇已經成為他們的唯一的寄託，而任何阻礙或者不加入他們行為的人都被當作敵人。很多人看見以太皇族陷入瘋狂並且離開。一些以太皇族議會的奈薩斯王子脫離以太皇族，以不同的目標成立其他團體和派別。聯合團就是因此而生的一個例子。護國者則是另一個...', `MaleText_loc7`='El Etereum se ha vuelto oscuro... retorcido. La venganza se ha convertido en su único recurso y, cualquiera que se interponga en su camino o no se una a su causa se considera enemigo. Muchos vieron que El Etereum caía en picado hacia la locura y se marcharon. Varios de los príncipes-nexo del consejo Etereum los abandonaron para formar otros grupos y facciones con diferentes objetivos. El Consorcio es un ejemplo de un grupo disidente. El Protectorado es otro...' WHERE `ID`=18186;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래서 어떻게 하려고 하는 겁니까?', `MaleText_loc4`='那么你们的目标是……？', `MaleText_loc5`='那麼你的目的是什麼?', `MaleText_loc7`='Entonces, ¿cuál es su propósito?', `FemaleText_loc1`='그래서 어떻게 하려고 하는 거죠?', `FemaleText_loc4`='那么你们的目标是……？', `FemaleText_loc5`='那麼你的目的是什麼?', `FemaleText_loc7`='Entonces, ¿cuál es su propósito?' WHERE `ID`=18187;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 디멘시우스만큼이나 에테리움도 우리에겐 위험한 존재라고 생각하오. 둘 다 멈추어야 하지...', `MaleText_loc4`='我们感觉到复仇军就像迪门修斯一样对我们存在造成了威胁。两者都必须被终结……', `MaleText_loc5`='我們認為到以太皇族對我們的生存造成的威脅和迪曼修斯一樣大。兩者都必須被制止...', `MaleText_loc7`='Pensamos que El Etereum es una amenaza tan grande para nuestra existencia como Dimensius. Ambos deben ser detenidos...' WHERE `ID`=18188;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 잘 알겠습니다. 제가 도울 일이라도 있습니까? 에테리움과 공허의 생물들은 우리에게도 위험한 존재입니다.', `MaleText_loc4`='我想我现在明白了。有什么我可以帮你的吗？复仇军和虚空生物同样也是我们的威胁。', `MaleText_loc5`='我認為我現在了解了。我能幫上任何忙嗎?以太皇族和虛無生物同時也是對我們生存的一個威脅。', `MaleText_loc7`='Creo que ahora lo comprendo. ¿Puedo ayudar en algo? El Etereum y las criaturas del vacío también son una amenaza para nuestra supervivencia.', `FemaleText_loc1`='이제 잘 알겠군요. 제가 도울 일이라도 있나요? 에테리움과 공허의 생물들은 우리에게도 위험한 존재입니다.', `FemaleText_loc4`='我想我现在明白了。有什么我可以帮你的吗？复仇军和虚空生物同样也是我们的威胁。', `FemaleText_loc5`='我認為我現在了解了。我能幫上任何忙嗎?以太皇族和虛無生物同時也是對我們生存的一個威脅。', `FemaleText_loc7`='Creo que ahora lo comprendo. ¿Puedo ayudar en algo? El Etereum y las criaturas del vacío también son una amenaza para nuestra supervivencia.' WHERE `ID`=18189;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적군이 감지되었소. 전송 종료!', `MaleText_loc4`='发现敌人。通话中断。', `MaleText_loc5`='敵方接近。通話結束。', `MaleText_loc7`='Hostiles detectados. Finalizando transmisión.' WHERE `ID`=18190;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자유연합 전송 완료.', `MaleText_loc4`='维序派传输完成。', `MaleText_loc5`='護國者傳送完成。', `MaleText_loc7`='Transmisión del Protectorado completa.' WHERE `ID`=18191;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어이, 난 스팀휘들 결투 대회의 공식 투기장 사무관 빅스톤 핀치휘슬이라고 하네. 관심이 있다면 군침이 돌만한 상품들을 보여주겠어.', `MaleText_loc4`='哟。我是维克斯顿，热砂港搏击会的官方竞技场商人。如果你有足够的声望，我就有让你流口水的物品。', `MaleText_loc5`='嗨。我是維斯頓·急嘯，熱砂戰鬥同盟的正式競技場商人。如果你聲望足夠，我有使你看到流口水的稀世珍寶。', `MaleText_loc7`='Hola. Soy Vixton Silbapellizco, vendedor oficial de la Arena para el circuito de lucha de Bonvapor. Si tienes al representante, tengo los artículos que te harán la boca agua.' WHERE `ID`=18192;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='2분 후 전투가 시작됩니다!', `MaleText_loc4`='战斗将在2分钟后开始！', `MaleText_loc5`='戰鬥在2分鐘內開始!', `MaleText_loc7`='¡La batalla comienza en dos minutos!' WHERE `ID`=18193;
