UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으... 기분이 안 좋아.', `MaleText_loc4`='呃……我感觉不是很好。', `MaleText_loc5`='呃...我感覺不太舒服。', `MaleText_loc7`='Ugh... Mi no sentir bien.' WHERE `ID`=18197;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 전방사령관 킹스톤을 도와 폭파 임무를 수행하는 중입니다. 임무를 지원해 줄 파괴의 장갑 그리핀이 필요합니다!', `MaleText_loc4`='我正在执行前线指挥官金斯顿下达的轰炸任务。我需要一头武装狮鹫！', `MaleText_loc5`='我正為前線指揮官金斯頓進行一項轟炸任務。我需要一隻獅鷲獸毀滅者!', `MaleText_loc7`='Estoy en una misión de bombardeo para el comandante de vanguardia Kingston. ¡Necesito un destructor grifo!', `FemaleText_loc1`='저는 전방사령관 킹스톤을 도와 폭파 임무를 수행하는 중입니다. 임무를 지원해 줄 파괴의 장갑 그리핀이 필요합니다!', `FemaleText_loc4`='我正在执行前线指挥官金斯顿下达的轰炸任务。我需要一头武装狮鹫！', `FemaleText_loc5`='我正為前線指揮官金斯頓進行一項轟炸任務。我需要一隻獅鷲獸毀滅者!', `FemaleText_loc7`='Estoy en una misión de bombardeo para el comandante de vanguardia Kingston. ¡Necesito un destructor grifo!' WHERE `ID`=18198;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='속이 메스껍다면 페슬과 얘기해 보십시오. 그에게 멀미에 좋은 게 있을 겁니다.', `MaleText_loc4`='如果你感到不舒服，去找匹斯特。他可能有晕船药。', `MaleText_loc5`='如果你想吐的話，與派斯托談話。他也許有暈機藥。', `MaleText_loc7`='Si estás $gmareado:mareada;, habla con Pestle. Puede que tenga algo para los mareos.' WHERE `ID`=18199;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='심연의 절벽으로 보내 주십시오!', `MaleText_loc4`='送我去地狱岩床！', `MaleText_loc5`='送我到深淵沙洲!', `MaleText_loc7`='¡Enviadme a la Plataforma Abisal!', `FemaleText_loc1`='심연의 절벽으로 보내 주십시오!', `FemaleText_loc4`='送我去地狱岩床！', `FemaleText_loc5`='送我到深淵沙洲!', `FemaleText_loc7`='¡Enviadme a la Plataforma Abisal!' WHERE `ID`=18200;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 이놈의 세금 때문에 못 살겠습니다. 테레나스 국왕은 이런 재건축이 경제 부흥에 도움이 된다고 생각하는 걸까요? 정말 어디가 잘못돼도 한참 잘못 됐나 봐요.', `MaleText_loc4`='这些该死的税收快要压得我喘不过气了。如果泰瑞纳斯国王认为征收重税能促进经济发展，他必将丧失民心。', `MaleText_loc5`='這些可惡的稅令我腰酸背痛。假如泰瑞納斯國王認為這些重建可以促進經濟發展，他一定是瘋了。', `MaleText_loc7`='Estos malditos impuestos me están destrozando. El rey Terenas debe de estar desvariando, si cree que toda esta reconstrucción impulsará la economía.', `FemaleText_loc1`='정말 이놈의 세금 때문에 못 살겠습니다. 테레나스 국왕은 이런 재건축이 경제 부흥에 도움이 된다고 생각하는 걸까요? 정말 어디가 잘못돼도 한참 잘못 됐나 봐요.', `FemaleText_loc4`='这些该死的税收快要压得我喘不过气了。如果泰瑞纳斯国王认为征收重税能促进经济发展，他必将丧失民心。', `FemaleText_loc5`='這些可惡的稅令我腰酸背痛。假如泰瑞納斯國王認為這些重建可以促進經濟發展，他一定是瘋了。', `FemaleText_loc7`='Estos malditos impuestos me están destrozando. El rey Terenas debe de estar desvariando, si cree que toda esta reconstrucción impulsará la economía.' WHERE `ID`=18201;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전쟁 후 국왕은 다른 사람이 되어 버렸습니다. 마치 하루아침에 늙어 버린 노인네처럼 말입니다. 그래도 그의 아들은 언젠가 훌륭한 왕이 될 겁니다.', `MaleText_loc4`='自从战争以后，他就变得不一样了。好像他变老了，而且是一夜之间变老了。不过他的儿子总有一天会变成一位杰出的国王。', `MaleText_loc5`='自從那場戰爭開始，他改變了。他看起來像是在一夜之間衰老成一位老人一樣。可是，他的兒子 - 有一天將當一位好國王。', `MaleText_loc7`='No ha sido el mismo desde la Guerra. Parece como si hubiera envejecido y se hubiera convertido en un anciano de la noche a la mañana. Pero ese hijo suyo – será un rey excelente algún día.', `FemaleText_loc1`='전쟁 후 국왕은 다른 사람이 되어 버렸어요. 마치 하루아침에 늙어 버린 노인네처럼 말이죠. 그래도 그의 아들은 언젠가 훌륭한 왕이 될 거예요.', `FemaleText_loc4`='自从战争以后，他就变得不一样了。好像他变老了，而且是一夜之间变老了。不过他的儿子总有一天会变成一位杰出的国王。', `FemaleText_loc5`='自從那場戰爭開始，他改變了。他看起來像是在一夜之間衰老成一位老人一樣。可是，他的兒子 - 有一天將當一位好國王。', `FemaleText_loc7`='No ha sido el mismo desde la Guerra. Parece como si hubiera envejecido y se hubiera convertido en un anciano de la noche a la mañana. Pero ese hijo suyo – será un rey excelente algún día.' WHERE `ID`=18202;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아서스 왕자 말인가요? 듣자하니 프라우드무어의 딸 꽁무니만 쫓아다니는데 열을 올린다고 하더군요. 나라 일보다는 자기 일만 생각하는 거 아니겠어요?', `MaleText_loc4`='阿尔萨斯王子？我跟你说，我听说他把几乎所有的时间都用来追求普罗德摩尔的女儿了。比花在国事上的多得多。', `MaleText_loc5`='阿薩斯王子嗎?請坐。據我所知，他花費全部的時間追求普勞德摩爾的女兒。那個戀愛中的男孩關心他的戀情更甚國事，我告訴你。', `MaleText_loc7`='¿El príncipe Arthas? Por favor. Se pasa todo el tiempo detrás de la hija de Valiente, por lo que he oído. El chico tiene más en su cabeza que los asuntos de estado, te lo digo yo.', `FemaleText_loc1`='아서스 왕자 말인가요? 말도 마세요. 프라우드무어의 딸 꽁무니만 쫓아다니는데 열을 올린다고 하더군요. 나라 일보다는 자기 일만 생각하는 거 아니겠어요?', `FemaleText_loc4`='阿尔萨斯王子？我跟你说，我听说他把几乎所有的时间都用来追求普罗德摩尔的女儿了。比花在国事上的多得多。', `FemaleText_loc5`='阿薩斯王子嗎?請坐。據我所知，他花費全部的時間追求普勞德摩爾的女兒。那個戀愛中的男孩關心他的戀情更甚國事，我告訴你。', `FemaleText_loc7`='¿El príncipe Arthas? Por favor. Se pasa todo el tiempo detrás de la hija de Valiente, por lo que he oído. El chico tiene más en su cabeza que los asuntos de estado, te lo digo yo.' WHERE `ID`=18203;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정확히는 모르겠군요. 왕자가 성기사 훈련을 받고 있다고 듣긴 했습니다. 테레나스 국왕은 은빛 성기사단에서 왕자를 교육시킬 것이라고 믿고 있지요. 아서스 왕자를 제대로 교육시킬 인물이 있다면 바로 우서 경일 겁니다.', `MaleText_loc4`='我不是很确定。我听说他正在接受圣骑士训练，泰瑞纳斯希望白银之手可以教会他一些纪律。如果这世上有人可以改变阿尔萨斯，那只有老乌瑟尔了。', `MaleText_loc5`='我不能十分確定。我曾經聽說他被訓練成為一名聖騎士。泰瑞納斯希望白銀之手能教他一些紀律。如果有人能教阿薩斯正直，那將是老烏瑟。', `MaleText_loc7`='No estoy tan seguro. He oído que se le ha instruido como paladín. Terenas espera que la Mano de Plata pueda enseñarle algo de disciplina. Si alguien puede enderezar a Arthas, ese es el viejo Uther.', `FemaleText_loc1`='정확히는 모르겠군요. 왕자가 성기사 훈련을 받고 있다고 듣긴 했습니다. 테레나스 국왕은 은빛 성기사단에서 왕자를 교육시킬 것이라고 믿고 있지요. 아서스 왕자를 제대로 교육시킬 인물이 있다면 바로 우서 경일 겁니다.', `FemaleText_loc4`='我不是很确定。我听说他正在接受圣骑士训练，泰瑞纳斯希望白银之手可以教会他一些纪律。如果这世上有人可以改变阿尔萨斯，那只有老乌瑟尔了。', `FemaleText_loc5`='我不能十分確定。我曾經聽說他被訓練成為一名聖騎士。泰瑞納斯希望白銀之手能教他一些紀律。如果有人能教阿薩斯正直，那將是老烏瑟。', `FemaleText_loc7`='No estoy tan segura. He oído que se le ha instruido como paladín. Terenas espera que la Mano de Plata pueda enseñarle algo de disciplina. Si alguien puede enderezar a Arthas, ese es el viejo Uther.' WHERE `ID`=18204;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맞습니다. 우서 경이 우리 민중의 진정한 영웅이라는 건 사실이니까요.', `MaleText_loc4`='对，没错。乌瑟尔，他才是人民的真正英雄。', `MaleText_loc5`='沒錯，那是真的。烏瑟 - 現在人們擁有一名真正的英雄了。', `MaleText_loc7`='Sí, eso es cierto. Uther – ese sí que es un auténtico héroe para el pueblo.', `FemaleText_loc1`='맞아요, 우서 경이 우리 민중의 진정한 영웅이라는 건 사실이니까요.', `FemaleText_loc4`='对，没错。乌瑟尔，他才是人民的真正英雄。', `FemaleText_loc5`='沒錯，那是真的。烏瑟 - 現在人們擁有一名真正的英雄了。', `FemaleText_loc7`='Sí, eso es cierto. Uther – ese sí que es un auténtico héroe para el pueblo.' WHERE `ID`=18205;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='블랙무어 부관의 새로운 검투사에 관해 들어봤소? 어떤 이들은 무적이라고 말하더군.', `MaleText_loc4`='那么你有没有听说布莱克摩尔的那个新角斗士？有人说他是不败的。', `MaleText_loc5`='那麼你有聽說過布拉克摩爾中尉的新鬥士嗎?有些人說他是無法打敗的。', `MaleText_loc7`='Bueno, ¿has oído hablar acerca del nuevo gladiador del teniente Lodonegro? Hay quien dice que es invencible.', `FemaleText_loc1`='블랙무어 부관의 새로운 검투사에 관해 들어봤소? 어떤 이들은 무적이라고 말하더군.', `FemaleText_loc4`='那么你有没有听说布莱克摩尔的那个新角斗士？有人说他是不败的。', `FemaleText_loc5`='那麼你有聽說過布拉克摩爾中尉的新鬥士嗎?有些人說他是無法打敗的。', `FemaleText_loc7`='Bueno, ¿has oído hablar acerca del nuevo gladiador del teniente Lodonegro? Hay quien dice que es invencible.' WHERE `ID`=18206;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 그 덩치 큰 오크가 싸우는 것을 본 적이 있습니다. 그자 때문에 일주일 분의 봉급을 날렸지 뭡니까. 다시 그런 실수를 저지르지 않을 겁니다!', `MaleText_loc4`='是的，我看他打过。他是个兽人——就像其他兽人一样壮。我一周的工钱就输在那场上面。我不会再犯那样的错误了！', `MaleText_loc5`='嗯，我看見他們在戰鬥。他是一個獸人 - 塊頭就像他們生來一樣大。賭那個獸人會贏害我損失一星期的薪水。將不會再犯那種錯誤!', `MaleText_loc7`='Sí, lo he visto luchar. Es un orco – grande como son ellos. Perdí el sueldo de una semana apostando contra él. ¡No volveré a cometer esa equivocación!', `FemaleText_loc1`='네, 그 덩치 큰 오크가 싸우는 것을 본 적이 있어요. 그 오크 덕분에 일주일 분의 봉급을 날렸지 뭐예요. 다시 그런 실수를 저지르지 않을 거예요!', `FemaleText_loc4`='是的，我看他打过。他是个兽人——就像其他兽人一样壮。我一周的工钱就输在那场上面。我不会再犯那样的错误了！', `FemaleText_loc5`='嗯，我看見他們在戰鬥。他是一個獸人 - 塊頭就像他們生來一樣大。賭那個獸人會贏害我損失一星期的薪水。將不會再犯那種錯誤!', `FemaleText_loc7`='Sí, lo he visto luchar. Es un orco – grande como son ellos. Perdí el sueldo de una semana apostando contra él. ¡No volveré a cometer esa equivocación!' WHERE `ID`=18207;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이기든 지든 그런 오크를 애완용으로 두다니 좀 무모한 것 아닐까요? 오크는 믿을 수 없습니다. 오크들은 짐승이라고요.', `MaleText_loc4`='但不管输或赢，他留着那么个宠物兽人肯定是疯了。那些家伙不能信任，他们只是些动物而已。', `MaleText_loc5`='不管贏或輸，中尉一定是發瘋了才會去保留一頭像那樣的獸人寵物。那些東西不能被信任。他們是野蠻的動物。', `MaleText_loc7`='Gane o pierda, el teniente debe de estar loco para tener como mascota un orco como ese. No se puede confiar en ellos. Son animales, eso es lo que son.', `FemaleText_loc1`='이기든 지든 그런 오크를 애완용으로 두다니 좀 무모한 것 아닐까요? 오크는 믿을 수 없습니다. 오크들은 짐승이잖아요.', `FemaleText_loc4`='但不管输或赢，他留着那么个宠物兽人肯定是疯了。那些家伙不能信任，他们只是些动物而已。', `FemaleText_loc5`='不管贏或輸，中尉一定是發瘋了才會去保留一頭像那樣的獸人寵物。那些東西不能被信任。他們是野蠻的動物。', `FemaleText_loc7`='Gane o pierda, el teniente debe de estar loco para tener como mascota un orco como ese. No se puede confiar en ellos. Son animales, eso es lo que son.' WHERE `ID`=18208;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼요, 맞아요. 만약 탈출이라도 한다면 당장에 날려 버려야 해요!', `MaleText_loc4`='没错，没错。要是那个怪物逃跑了的话……圣光在上。', `MaleText_loc5`='真的。真的。如果那個怪物可以掙脫的話，願聖光保佑他!', `MaleText_loc7`='Cierto, cierto. ¡Que la Luz lo ayude si alguna vez se libera ese monstruo!', `FemaleText_loc1`='그럼요, 맞아요. 만약 탈출이라도 한다면 당장에 날려 버려야 해요!', `FemaleText_loc4`='没错，没错。要是那个怪物逃跑了的话……圣光在上。', `FemaleText_loc5`='真的。真的。如果那個怪物可以掙脫的話，願聖光保佑他!', `FemaleText_loc7`='Cierto, cierto. ¡Que la Luz lo ayude si alguna vez se libera ese monstruo!' WHERE `ID`=18209;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='20년 동안 우린 이 지옥 같은 곳에서 헤매고 있었습니다. 제가 할 수 있는 일은 저 부서진 문으로 비명을 지르며 달려가지 않는 게 고작이었단 말입니다. 친구들과 가족들이 보고 싶습니다! 내가 무사하다는 것을 알리고 싶다고요!', `MaleText_loc4`='我困在这个地狱一样的地方已经有二十年了。我所能做的就是冲着那道该死的大门尖叫，我想再看看我所爱的人！我想让他们知道我还活着！', `MaleText_loc5`='我們已經困在這個該死的洞內無依無靠20年了。我能做的就是不要邊跑邊叫的穿過那被詛咒的傳送門。我想要再次看見我的親人!我想要他們知道我仍然活著。', `MaleText_loc7`='Llevamos veinte años perdidos en este agujero infernal. Poco puedo hacer para no correr gritando por ese maldito Portal. ¡Quiero volver a ver a mis seres queridos! Quiero que sepan que sigo vivo.' WHERE `ID`=18210;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동감입니다. 하지만 아직 해야 할 일이 남아 있습니다. 악마들이 우리의 고향인 아제로스로 가는 길을 알아낸다면 모두 헛수고입니다. 서로에게 힘이 되어 주면서 견디어 낼 수밖에 없습니다. 다나스 님을 믿으세요. 그분께서 우리를 실망시키신 적이 있습니까?', `MaleText_loc4`='我和你的感觉一样，但是我们在这里仍然有不可推卸的职责。如果恶魔们找到了返回艾泽拉斯的路，那我们的一切努力就都白费了。我们只要在这里再坚持一段时间，相信达纳斯——他从未让我们失望过。', `MaleText_loc5`='我有同感。但是這裡仍然有一個工作要完成。假如這禍害找到回艾澤拉斯的路 - 回到我們的家鄉，所有的努力都是白費的。我們必須再堅持一會兒。相信達納斯 - 他以前從未使我們失望。', `MaleText_loc7`='Siento lo mismo. Pero todavía hay un trabajo por hacer ahí fuera. Todo habrá sido en balde si ese malvado encuentra el camino de vuelta a Azeroth – de vuelta a nuestros hogares. Solo tenemos que resistir un poco más. Confía en Danath – nunca nos ha defraudado.' WHERE `ID`=18211;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 걱정하는 건 그분이 아닙니다. 여기 경험 없는 풋내기들이 걱정되는 것입니다. 괴상한 보라색 엘프들은 아직 실력을 발휘해 본 적이 없으니까요.', `MaleText_loc4`='我担心的不是他。这些新来的——和那些跟他们一起来的紫色的精灵才是我所担心的。他们甚至还没能证明自己跟我们是一路的。', `MaleText_loc5`='他不是我所擔心的。我擔心的是周遭的這些新手 - 以及那些他們帶來令人毛骨悚然的紫色精靈。他們甚至還沒證明他們的能力呢。', `MaleText_loc7`='No es él el que me preocupa. Son esos novatos que hay por aquí – y esos asquerosos elfos púrpura que han traído consigo. Ni siquiera se han probado a sí mismos aún.' WHERE `ID`=18212;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런... 늙은 아저씨 같은 말을 하시는군요.', `MaleText_loc4`='拜托，你听上去就像个脾气暴躁的老人。', `MaleText_loc5`='拜託 - 你聽起來像是一個脾氣暴躁的老人。', `MaleText_loc7`='Vamos – hablas como un viejo gruñón.' WHERE `ID`=18213;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 늙을 만큼 늙었단 말입니다!', `MaleText_loc4`='我还真就是个脾气暴躁的老人！', `MaleText_loc5`='我是一個脾氣暴躁的老人!', `MaleText_loc7`='¡Soy un viejo gruñón!' WHERE `ID`=18214;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무하하하하! 가라 나의 예쁜 아이들아! 로켓발사단장과 그의 황천 로켓을 파괴하라! 52번 구역을 초토화해라! 위대하신 붐 박사 앞에서 무릎을 꿇어라! 무릎을 꿇란 말이다!!!', `MaleText_loc4`='哇哈哈哈哈！去吧，我的手下们……消灭火箭主管和他的虚空火箭！征服52区！跪下吧！在砰砰博士面前屈服吧！！', `MaleText_loc5`='哇哈哈哈!去吧我的寶貝們...摧毀火箭主管和他的虛空火箭!消滅52區!跪下吧!在布姆博士面前跪下吧!!!', `MaleText_loc7`='¡Muajajajajaja! Id, esbirros... ¡destruid al jefe de cohetes y su cohete abisal! ¡Aniquilad el Área 52! ¡Arrodillaos! ¡¡¡Arrodillaos ante el doctor Bum!!!' WHERE `ID`=18215;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<아무 소리로 들리지 않는데 가끔 깜짝 놀라서 뒤돌아보는 수습생 안드레단>$B$B안녕하십니까, $n! 실례합니다만 저는 지금 농부 네이든의 일을 하고 있는 중입니다. 그가 마을회관에서 돌아오기 전에 여기 있는 모든 말들에게 발굽을 달아야 해서요. 제가 도울 일이라도 있습니까?', `MaleText_loc4`='<学徒时不时显露出心不在焉的样子，他似乎在辨听着你无法听见的声响。>$B$B今天天气不错，挺风和日丽的……$n。请原谅我这副心烦意乱的模样，但是我正在为纳丁干活。我要在他从城镇大厅回来之前，替所有的马匹都钉上马蹄铁。我能帮你什么忙吗？', `MaleText_loc5`='<學徒偶爾轉頭看看四周，顯然是對那些你聽不見的聲音所做的反應。>$B$B祝你有美好的一天，$n。如果我看起來好像心不在焉的話請原諒我，因為我正在沉浸在農夫那丁所交代的工作當中。當他從市政廳返回時，我想要把他所有的馬都裝好馬蹄鐵。我能幫上你什麼忙嗎?', `MaleText_loc7`='<El aprendiz mira de vez en cuando por encima del hombro, aparentemente reaccionando ante sonidos que tú no puedes oír.>$B$BBuenos días, $n. Discúlpame si parezco distraído, pero me encuentro en medio de un trabajo para el granjero Natin. Quiero poner herraduras a todos sus caballos para cuando vuelva del concejo. ¿En qué puedo ayudarte?' WHERE `ID`=18216;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물건을 살펴보고 싶습니다.', `MaleText_loc4`='我想要看看你出售的货物。', `MaleText_loc5`='我希望能看看你的商品。', `MaleText_loc7`='Me gustaría echar un vistazo a tus mercancías.', `FemaleText_loc1`='물건을 살펴보고 싶습니다.', `FemaleText_loc4`='我想要看看你出售的货物。', `FemaleText_loc5`='我希望能看看你的商品。', `FemaleText_loc7`='Me gustaría echar un vistazo a tus mercancías.' WHERE `ID`=18217;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='붐 박사의 로봇들이 공격하고 있다고! 저들을 저지해야 해!', `MaleText_loc4`='砰砰博士的机器人开始进攻了！阻止他们！', `MaleText_loc5`='布姆博士的機器人正在攻擊我們!阻止他們!', `MaleText_loc7`='¡Los robots del doctor Bum están atacando! ¡Detenedlos!' WHERE `ID`=18218;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런! 정말 놀라웠어! 시간이 갈수록 나와 황천 로켓이 점점 위험해지는군! 누군가 붐 박사를 좀 처리해 줘야겠군!', `MaleText_loc4`='呀。他们接近了！他们离我和虚空火箭越来越近了！谁去解决掉砰砰博士啊！', `MaleText_loc5`='哎呀。真危險!他們越來越逼近我跟虛空火箭了!有人必須去對付布姆博士!', `MaleText_loc7`='Ay. ¡Eso ha estado cerca! ¡Y cada vez se acercan más a mí y al cohete abisal! ¡Alguien tiene que ocuparse del doctor Bum!' WHERE `ID`=18219;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 꺾었을진 몰라도 이 전쟁은... 어림없다!', `MaleText_loc4`='你虽然赢得了这次战役，但无法赢得整个战争。', `MaleText_loc5`='你已經贏了這次的戰役，但不是...這場...戰爭。', `MaleText_loc7`='Habéis ganado esta batalla, pero no la guerra.' WHERE `ID`=18220;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불타는 군단의 마지막 정복 작전이 시작됐다! 다시 한번, 이 세계를 우리 손 안에 거머쥐리라! 아무도 살려두지 않겠다!', `MaleText_loc4`='燃烧军团的最终战役开始了！这个世界再一次任凭我们宰割。不要留任何活口!', `MaleText_loc5`='燃燒軍團最後的征戰已經開始了!世界的掌控權再次落入我們手中。無人可以倖免!', `MaleText_loc7`='¡La conquista final de la Legión está en marcha! ¡De nuevo la subyugación de este mundo está a nuestro alcance. ¡Que mueran todos!' WHERE `ID`=18221;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부서지고 썩어가리라!', `MaleText_loc4`='崩溃吧！腐烂吧！', `MaleText_loc5`='崩裂粉碎吧!', `MaleText_loc7`='¡Caigan y púdranse!' WHERE `ID`=18222;
