UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음의... 한기에 굴복하라.', `MaleText_loc4`='在死亡的严寒面前屈服吧。', `MaleText_loc5`='屈服於冰冷絕望的...死亡吧。', `MaleText_loc7`='Ríndanse ante el frío helado... de la muerte.' WHERE `ID`=18224;
