UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멸망에 처한 세계의 수호자들이여, 구차한 목숨이라도 건지려면 어서 달아나라!', `MaleText_loc4`='你们在保卫一个注定要毁灭的世界！逃走吧，那样也许你们还能多活几天！', `MaleText_loc5`='你們要守護的世界躲不了毀滅的命運!逃離這兒，也許可以延長你們那可悲的生命!', `MaleText_loc7`='¡Son los defensores de un mundo condenado! ¡Huyan y quizá prolonguen sus patéticas vidas!' WHERE `ID`=18230;
