UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하늘에서 불 비가 내릴지어다!', `MaleText_loc4`='火焰之雨从天而降！', `MaleText_loc5`='讓火從天而降吧!', `MaleText_loc7`='¡Que llueva fuego!' WHERE `ID`=18235;
