UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천천히 죽여줄 시간이 없어 아쉽구나!', `MaleText_loc4`='真可惜，没时间继续跟你打交道了。', `MaleText_loc5`='真可惜，沒有時間把你慢慢折磨到死!', `MaleText_loc7`='¡Qué pena, no hay tiempo para una muerte lenta!' WHERE `ID`=18239;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살려달라고 울부짖어 봐라! 너의 부질없는 목숨을 거두리라!', `MaleText_loc4`='哭喊着求饶吧！你们毫无意义的生命就要结束了！', `MaleText_loc5`='哭著乞求憐憫吧!不久之後你們將喪失無意義的生命!', `MaleText_loc7`='¡Imploren clemencia! ¡Pronto perderán sus insignificantes vidas!' WHERE `ID`=18240;
