UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈은 상대가 안 된다!', `MaleText_loc4`='你毫无价值！', `MaleText_loc5`='你算什麼東西!', `MaleText_loc7`='¡No son nada!' WHERE `ID`=18244;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한심하고 성가신 것!', `MaleText_loc4`='可怜虫！', `MaleText_loc5`='可悲的傢伙!', `MaleText_loc7`='¡Fastidio miserable!' WHERE `ID`=18245;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 요원 야식스와 함께 자유연합 사령관으로부터 울트리스에 있는 공허의 괴물들을 소탕하라는 명령을 받아서 빈틈없는 공격을 개시할 예정이었습니다. 우리의 최종 목표는 그 지역에서 모든 생명을 집어삼키는 공허의 군주 아르코누스를 처치하고 자유연합 경비초소로 돌아오는 것이었죠.$B$B하지만, 유감스럽게도 우리는 약간 늦게 도착했습니다. 전 살덩이괴물들과 전면전을 벌이던 중 야식스와 떨어지고 말았습니다. 지금 그는 안에 갇혀 적군에게 둘러싸여서 있습니다.', `MaleText_loc4`='我和代理人亚希克斯接到了维序派司令部的最高级别任务指派，要去根除乌提斯的虚空生物，这是一次战略进攻。我们返回维序派哨站之前的最后一个任务是消灭那个被肉人们养得越来越胖的虚空领主阿克努斯。$B$B不幸的是，我们晚到了一会儿。亚希克斯和我在与血肉兽的交火中走散了，现在他被敌人困在里面。', `MaleText_loc5`='護國者指揮官授權密探亞希克斯和我一項優先處理的重要任務，消滅奧崔斯的所有虛無生物。這本來應該是是戰術上的突襲戰。在返回護國者哨站之前的最後一次突襲，我們的目標是一個名叫阿肯納斯的虛無領主，他的身軀因為吸取當地的生命體而茁壯強大。$B$B可惜，我們到達的太晚。亞希克斯和我在與噬屍獸的激烈交戰中被分開了。現在他被困在裡面，被阻擋在敵軍後方。', `MaleText_loc7`='Al agente Ya-six y a mí nos asignaron una misión de prioridad alta desde el mando del Protectorado: erradicar toda señal de infestación de criaturas del vacío de Ultris. Tenían que ser ataques tácticos. Nuestro último ataque antes de volver a la Atalaya del Protectorado tenía que caer sobre un señor del vacío llamado Arconus, que había estado engordando gracias a los seres de carne de la zona.$B$BPor desgracia, llegamos un poco tarde. Ya-six y yo nos separamos en el tiroteo con las bestias de carne. Ahora está atrapado dentro, inmovilizado tras líneas enemigas.' WHERE `ID`=18246;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='희망 따위는 버려라! 오래전 시작한 계획을 마무리하고자 불타는 군단이 돌아왔다. 이번엔 절대 피할 수 없다!', `MaleText_loc4`='放弃所有希望吧！燃烧军团要完成这许多年前就注定的使命。这一次，一切都无可挽回了!', `MaleText_loc5`='放棄希望吧!燃燒軍團已經捲土重來，誓言要完成多年前開始的毀滅計畫。這次，沒有人能活著離開!', `MaleText_loc7`='¡Abandonen toda esperanza! ¡La Legión ha vuelto para acabar lo que se empezó hace tantos años. ¡Esta vez, no habrá escapatoria!' WHERE `ID`=18247;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈들의 시대는... 끝났다.', `MaleText_loc4`='你们的日子……就要到头。', `MaleText_loc5`='你的死期就要...到了。', `MaleText_loc7`='Su tiempo casi se ha... agotado.' WHERE `ID`=18248;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아락세스, 응답하라... 들리나, 아락세스? 아무것도 안 보인다. 차원의 폭풍이 시야를 가리고 있다.', `MaleText_loc4`='阿拉克塞，呼叫……你在吗？阿拉克塞？可见度为零。扭曲风暴阻挡了我们的视线。', `MaleText_loc5`='阿雷克斯，進來...阿雷克斯你在嗎?我的能見度是零。扭曲風暴阻礙了我們的感官。', `MaleText_loc7`='Araxes, entra... ¿Estás ahí, Araxes? La visibilidad es nula. Las tormentas de distorsión nos bloquean.' WHERE `ID`=18249;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아. 상황을 보고하라.', `MaleText_loc4`='收到。状况报告，士兵。', `MaleText_loc5`='收到。狀態回報，士兵。', `MaleText_loc7`='Copio. Informe de estado, soldado.' WHERE `ID`=18250;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽어라! 미천한 벌레 같은 것들!', `MaleText_loc4`='受苦吧，你这卑劣的虫子！', `MaleText_loc5`='受苦吧，你這隻卑劣的臭蟲!', `MaleText_loc7`='¡Sufran, despreciables insectos!' WHERE `ID`=18251;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이것은 시작에 불과하다!', `MaleText_loc4`='这只是……一点小小的教训。', `MaleText_loc5`='試試我的厲害，還有更精采的在後頭。', `MaleText_loc7`='Solo es el principio... de lo que les espera.' WHERE `ID`=18252;
