UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무도 널 구해주지 못해.', `MaleText_loc4`='没有人可以挽救你。', `MaleText_loc5`='沒有人救的了你。', `MaleText_loc7`='Nadie va a salvarte.' WHERE `ID`=18254;
