UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 망할 기계야, 작동을 하란 말이야. *휴대용 응답장치를 주먹으로 두들기는 요원 아락세스*', `MaleText_loc4`='我希望这个该死的东西能管用。*阿拉克塞重重地敲打了一下便携式传送器。*', `MaleText_loc5`='我希望這可惡的東西恢復運作。*阿雷克斯敲打可攜式傳送器。*', `MaleText_loc7`='Espero que este maldito trasto funcione. *Araxes da golpecitos al transpondedor portátil.*' WHERE `ID`=18256;
