UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사령관님, 표시를 찾았습니다. 야식스와 갈라졌습니다. 지원을 요청합니다.', `MaleText_loc4`='我们已经确定了标记的位置，长官。亚希克斯和我走散了。我们需要增援。', `MaleText_loc5`='我們已經找到目標，指揮官。亞希克斯和我已經被分開了。請求支援。', `MaleText_loc7`='Hemos localizado la marca, comandante. Ya-six y yo nos hemos separado. Solicitando apoyo.' WHERE `ID`=18268;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알았다, 아락세스. 지원을 보내겠다. 현 위치에서 대기하라. 반복한다. 현 위치에서 대기하라.', `MaleText_loc4`='收到，阿拉克塞。增援正在赶来。守住你的位置。我重复一遍，守住你的位置。', `MaleText_loc5`='收到，阿雷克斯。援軍已經出發了。守住你的崗位。我重複，守住你的崗位。', `MaleText_loc7`='Copia eso, Araxes. El apoyo está en camino. Mantén tu posición. Repito, mantén tu posición.' WHERE `ID`=18269;
