UPDATE `locales_broadcast_text` SET `MaleText_loc1`='징검다리 거점에 오신 것을 환영합니다, $n! 많은 경험을 하시길 바랍니다!', `MaleText_loc4`='欢迎来到破碎岗哨，$n！我希望你能活下来！', `MaleText_loc5`='歡迎來到破碎崗哨，$n!希望你在這場經歷之後倖存!', `MaleText_loc7`='¡$gBienvenido:Bienvenida; al Puesto Devastación, $n! ¡Espero que sobrevivas a esta experiencia!' WHERE `ID`=18272;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성스러운 빛이 당신을 인도할 수 없다면 제가 당신을 돕겠습니다. 뭘 도와 드릴까요?', `MaleText_loc4`='如果圣光不能指引你，我的朋友，也许我可以给你点帮助。你需要什么？', `MaleText_loc5`='如果聖光不能指引你的道路，我的朋友，或許我可以幫上忙。你需要什麼?', `MaleText_loc7`='Si la Luz no puede guiarte, $gamigo:amiga;, quizás yo pueda ayudarte. ¿Qué necesitas?', `FemaleText_loc1`='성스러운 빛이 당신을 인도할 수 없다면 제가 당신을 돕겠습니다. 뭘 도와 드릴까요?', `FemaleText_loc4`='如果圣光不能指引你，我的朋友，也许我可以给你点帮助。你需要什么？', `FemaleText_loc5`='如果聖光不能指引你的道路，我的朋友，或許我可以幫上忙。你需要什麼?', `FemaleText_loc7`='Si la Luz no puede guiarte, $gamigo:amiga;, quizás yo pueda ayudarte. ¿Qué necesitas?' WHERE `ID`=18273;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 섬은 참 이상한 곳입니다. 그렇지 않습니까? 제가 도와 드릴 일이라도 있습니까?', `MaleText_loc4`='这座岛真奇怪，不是吗？有什么我能帮你的吗？', `MaleText_loc5`='這個島好奇怪，不是嗎?我能為你效勞嗎?', `MaleText_loc7`='Esta isla puede ser extraña, ¿verdad? ¿Hay algo que pueda hacer por ti?', `FemaleText_loc1`='이 섬은 참 이상한 곳입니다. 그렇지 않습니까? 제가 도울 일이라도 있나요?', `FemaleText_loc4`='这座岛真奇怪，不是吗？有什么我能帮你的吗？', `FemaleText_loc5`='這個島好奇怪，不是嗎?我能為你效勞嗎?', `FemaleText_loc7`='Esta isla puede ser extraña, ¿verdad? ¿Hay algo que pueda hacer por ti?' WHERE `ID`=18274;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물건을 보관할 곳을 찾으신다고요? 그렇다면 엑소다르에서 안전한 은행으로 가셔서 은행원에게 도움을 받으시기 바랍니다.', `MaleText_loc4`='在找仓库？你是想去埃索达的保险箱那里吧，那么……银行职员们会很高兴帮助你的。', `MaleText_loc5`='尋找存放物品的場所嗎?你可以向艾克索達的保險庫前進，然後...那些銀行家將非常樂於幫助你。', `MaleText_loc7`='¿Buscas almacenamiento? Entonces querrás dirigirte a la seguridad de El Exodar... los banqueros estarán muy contentos de ayudarte.', `FemaleText_loc1`='물건을 보관할 곳을 찾으신다고요? 그렇다면 엑소다르에서 안전한 은행으로 가셔서 은행원에게 도움을 받으시기 바랍니다.', `FemaleText_loc4`='在找仓库？你是想去埃索达的保险箱那里吧，那么……银行职员们会很高兴帮助你的。', `FemaleText_loc5`='尋找存放物品的場所嗎?你可以向艾克索達的保險庫前進，然後...那些銀行家將非常樂於幫助你。', `FemaleText_loc7`='¿Buscas almacenamiento? Entonces querrás dirigirte a la seguridad de El Exodar... los banqueros estarán muy contentos de ayudarte.' WHERE `ID`=18275;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말 이상한 도시 아닌가요?', `FemaleText_loc4`='奇特的城市，不是吗？', `FemaleText_loc5`='古怪的城市，對嗎?', `FemaleText_loc7`='Una vista maravillosa, ¿verdad?' WHERE `ID`=18276;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='말을 많이 하지 마세요. 아시겠어요?', `FemaleText_loc4`='不喜欢说话？', `FemaleText_loc5`='你的話不多，對嗎?', `FemaleText_loc7`='No hablas mucho, ¿eh?' WHERE `ID`=18277;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가끔은 고향이 그리울 때가 있죠. 어쩌면 고향을 위해 싸우는 것이 그리운 것인지도 모른답니다.', `FemaleText_loc4`='有时候，我会想家。也许我只是想念为它而战的日子。', `FemaleText_loc5`='有的時候，我想念我的家。也許我只是想念為它而戰的感覺。', `FemaleText_loc7`='A veces echo de menos mi hogar. O quizás simplemente echo de menos luchar por él.' WHERE `ID`=18278;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오랫동안 제 형제들을 만나지 못했어요. 그들이 그립군요.', `FemaleText_loc4`='很久没有看到我的兄弟了。', `FemaleText_loc5`='我有一段很長的時間沒見過我的兄弟。', `FemaleText_loc7`='Hace siglos que no veo a mis hermanos.' WHERE `ID`=18279;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음...', `MaleText_loc4`='嗯。', `MaleText_loc5`='嗯。', `MaleText_loc7`='Mmm.' WHERE `ID`=18280;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아락세스! 지원이 필요합니다! 광산에 갇혔습니다. 제가 있는 위치가 정확히 어딘지는 모르겠지만 여기까지 오면서 땅에 자유연합 추적장치를 떨어뜨려 놓았습니다.', `MaleText_loc4`='阿拉克塞！快来帮忙！我被困在矿洞里了。我……我不确定我到底在哪里，但我在来的路上放了追踪器。', `MaleText_loc5`='阿雷克斯!送來救援隊!我被困在礦坑裡。我...我不能確定我的確實位置，但是我沉著把追蹤器丟在我後面的地上。', `MaleText_loc7`='¡Araxes! ¡Envía ayuda! Estoy inmovilizado en las minas. No... no estoy seguro de dónde estoy exactamente, pero he tenido la sangre fría de dejar caer trazadores en el suelo que hay detrás de mí.' WHERE `ID`=18281;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자유연합 추적장치를 다시 따라나갈 수가 없습니다. 가는 길에 살덩이괴물이 너무 많아요. 구조대를 보내 주십시오... 추적장치를 따라오면 됩니다... 이상!', `MaleText_loc4`='我不能跟着追踪器走出去，沿途的血肉兽太多了。派人……跟着追踪器进来吧……亚希克斯，完毕。', `MaleText_loc5`='我不能跟隨追蹤器離開這裡，沿途太多噬屍獸了。派人去...跟隨那些追蹤器...把亞希克斯救出來。', `MaleText_loc7`='No puedo seguir los trazadores para salir, hay demasiadas bestias de carne por el camino. Envía a alguien dentro... Seguid los trazadores... Ya-six, corto.' WHERE `ID`=18282;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐요! 거기, 당신! 이쪽입니다!', `MaleText_loc4`='嘿！说你呢！$R！过来！', `MaleText_loc5`='喂!喂你!$R!在這裡!', `MaleText_loc7`='¡Eh! ¡Eh, tú! ¡$R! ¡Por aquí!' WHERE `ID`=18283;
