UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cffffff00얼라이언스가 영혼의 탑을 차지했습니다!|r', `MaleText_loc4`='|cffffff00联盟夺取了一座灵魂塔的控制权！|r', `MaleText_loc5`='|cffffff00聯盟已經控制住一座靈魂尖塔!|r', `MaleText_loc7`='|cffffff00¡La Alianza ha tomado el control de una torre Espíritu!|r' WHERE `ID`=18285;
