UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저한테 생각이 있습니다. 이 조각을 땅에 두고 어떤 일이 벌어지나 확인해 봅시다.', `FemaleText_loc4`='我有个主意。让我们把这块碎片种到地上，看看会发生什么。', `FemaleText_loc5`='我有一個想法。讓我們把這塊裂片種在地上並且看看會發生什麼事情。', `FemaleText_loc7`='Tengo una idea. Plantemos este fragmento en el suelo y veamos qué sucede.' WHERE `ID`=18289;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='황천의 폭풍의 52번 구역에 있는 빅스톤 핀치휘슬에게 가보십시오. 그는 스팀휘들 결투 대회의 공식 투기장 사무관으로서, 투기장 점수가 높은 이들에게 온갖 종류의 좋은 물건을 팔고 있습니다.', `FemaleText_loc4`='别忘记去拜访虚空风暴52区的维克斯顿。作为热砂港搏击会的官方竞技场商人，他出售各种不可思议的物品给那些有着足够竞技场点数的家伙。', `FemaleText_loc5`='一定要拜訪在虛空風暴52區的維斯頓·急嘯。身為熱砂戰鬥同盟的正式競技場商人，他有各式各樣難以置信的物品，出售給那些有足夠競技場點數的人。', `FemaleText_loc7`='Asegúrate de visitar a Vixton Silbapellizco en el Área 52 de Tormenta Abisal. Como vendedor oficial de la arena del circuito de lucha de Bonvapor, tiene todo tipo de artículos increíbles para aquellos que dispongan de suficientes puntos de Arena.' WHERE `ID`=18290;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그 수정 조각에서 발산되는 악의 기운이 거대괴수 중 하나를 끌어들이고 있습니다. 당장 그걸 내려놓으십시오!', `FemaleText_loc4`='水晶碎片中散发出的邪恶光芒引来了一只巨人，快点消灭它！', `FemaleText_loc5`='從水晶裂片散發出來的邪惡氣息已經引誘來了一個巨像。快解決它!', `FemaleText_loc7`='El mal que emana del fragmento de cristal ha atraído a uno de los colosos. ¡Abátelo, rápido!' WHERE `ID`=18291;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='히포그리프 조련사', `MaleText_loc4`='角鹰兽管理员', `MaleText_loc5`='角鷹獸管理員', `MaleText_loc7`='Maestro de hipogrifos', `FemaleText_loc1`='히포그리프 조련사', `FemaleText_loc4`='角鹰兽管理员', `FemaleText_loc5`='角鷹獸管理員', `FemaleText_loc7`='Maestro de hipogrifos' WHERE `ID`=18292;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기 위에 언덕으로 오세요, $n 님.', `FemaleText_loc4`='到山上来，$n。', `FemaleText_loc5`='在小山丘這裡，$n。', `FemaleText_loc7`='Aquí arriba, en la colina, $n.' WHERE `ID`=18293;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n, 그대가 해줄 일이 있습니다.', `FemaleText_loc4`='$n，我这里有些事情需要你去做。', `FemaleText_loc5`='$n，我需要你去做一些事情。', `FemaleText_loc7`='$n, hay algo que necesito que hagas.' WHERE `ID`=18294;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엑소다르 근처에 가면 히포그리프가 있습니다. 핏빛 감시초소로 날아가고 싶다면 그곳으로 가도록 하십시오.', `MaleText_loc4`='角鹰兽们栖息在埃索达入口处。如果你想飞去秘血岗哨的话，你应该去那里看看。', `MaleText_loc5`='角鷹獸在艾克索達附近被照顧得很好。如果你希望飛往血色守望，你真該前往艾克索達一趟。', `MaleText_loc7`='Los hipogrifos están bien cuidados cerca del mismo Exodar. Deberías viajar hasta allí si deseas volar hasta la Avanzada de Sangre.', `FemaleText_loc1`='엑소다르 근처에 가면 히포그리프가 있습니다. 핏빛 감시초소로 날아가고 싶다면 그곳으로 가도록 하십시오.', `FemaleText_loc4`='角鹰兽们栖息在埃索达入口处。如果你想飞去秘血岗哨的话，你应该去那里看看。', `FemaleText_loc5`='角鷹獸在艾克索達附近被照顧得很好。如果你希望飛往血色守望，你真該前往艾克索達一趟。', `FemaleText_loc7`='Los hipogrifos están bien cuidados cerca del mismo Exodar. Deberías viajar hasta allí si deseas volar hasta la Avanzada de Sangre.' WHERE `ID`=18295;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한때 풍부한 물량을 자랑했던 엑소다르의 직물 공급량이 위험 수준으로 떨어졌습니다. 옷감을 기부해 주신다면 이곳에서 드레나이에 대한 당신의 명성이 높아질 것입니다.', `MaleText_loc4`='埃索达的布料储备快要消耗殆尽了，如果你以捐献布料的方式帮助我们，无疑可以提升你和在德莱尼人中的声望。', `MaleText_loc5`='艾克索達過去大量供應的紡織品產量已經縮減到異常的低。假如你願意捐贈布料幫助我們，你與德萊尼的聲望將會提高。', `MaleText_loc7`='El suministro de tejidos de El Exodar, antaño tan vasto, ha disminuido peligrosamente. Tu reputación con los draenei aumentaría si nos ayudaras donando tela.' WHERE `ID`=18296;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='푸남은 우리의 길드 등록 사무관을 만나시려면 엑소다르로 가십시오. 길을 따라가면 금방 엑소다르에 다다를 것입니다.', `MaleText_loc4`='弗纳姆是我们的公会注册员，他的办公室就设立在埃索达里面。沿着路走，你很快就可以找到他。', `MaleText_loc5`='范安姆是我們的公會註冊員。他的辦公室已經設立在艾克索達。請沿著道路走;你將立即找到它。', `MaleText_loc7`='Funaam es nuestro registrador del gremio. Su oficina se ha establecido dentro de El Exodar. Sigue el camino; la encontrarás enseguida.', `FemaleText_loc1`='푸남은 우리의 길드 등록 사무관을 만나시려면 엑소다르로 가십시오. 길을 따라가면 금방 엑소다르에 다다를 것입니다.', `FemaleText_loc4`='弗纳姆是我们的公会注册员，他的办公室就设立在埃索达里面。沿着路走，你很快就可以找到他。', `FemaleText_loc5`='范安姆是我們的公會註冊員。他的辦公室已經設立在艾克索達。請沿著道路走;你將立即找到它。', `FemaleText_loc7`='Funaam es nuestro registrador del gremio. Su oficina se ha establecido dentro de El Exodar. Sigue el camino; la encontrarás enseguida.' WHERE `ID`=18297;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여관은 하늘 감시초소의 북쪽에 있습니다. 그곳의 간병인인 첼란이 당신을 잘 돌봐 줄 겁니다.', `MaleText_loc4`='我们那简陋的旅馆坐落在碧蓝岗哨的北面，谢尔兰会照顾好你的。', `MaleText_loc5`='我們簡陋的旅館館位於藍色守望北邊;查倫將好好的照顧你。', `MaleText_loc7`='Nuestra humilde posada está situada al norte de la Avanzada Azur; Chellan cuidará bien de ti.', `FemaleText_loc1`='여관은 하늘 감시초소의 북쪽에 있습니다. 그곳의 간병인인 첼란이 당신을 잘 돌봐 줄 겁니다.', `FemaleText_loc4`='我们那简陋的旅馆坐落在碧蓝岗哨的北面，谢尔兰会照顾好你的。', `FemaleText_loc5`='我們簡陋的旅館館位於藍色守望北邊;查倫將好好的照顧你。', `FemaleText_loc7`='Nuestra humilde posada está situada al norte de la Avanzada Azur; Chellan cuidará bien de ti.' WHERE `ID`=18298;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보십시오! 아름다운 혼돈의 기운이 응집하고 있습니다.', `MaleText_loc4`='看那些壮观的混乱能量之流！', `MaleText_loc5`='看那群可觀的混亂能量聚合體!', `MaleText_loc7`='¡Mira esa bonita agrupación de energías caóticas!' WHERE `ID`=18299;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하늘 감시초소의 여관 밖에 서 있는 에스비나가 당신의 야수를 잘 돌봐 줄 것입니다.', `MaleText_loc4`='伊斯比纳会很高兴帮助你照料动物同伴的。她在碧蓝岗哨的旅馆外面等着你。', `MaleText_loc5`='艾斯濱娜很高興可以照顧你的動物同伴，我的朋友。她在藍色守望的旅館外邊等待。', `MaleText_loc7`='Esbina estará contenta de cuidar de tu compañero animal, $gamigo:amiga;. Te espera fuera de la posada, dentro de la Avanzada Azur.', `FemaleText_loc1`='하늘 감시초소의 여관 밖에 서 있는 에스비나가 당신의 야수를 잘 돌봐 줄 것입니다.', `FemaleText_loc4`='伊斯比纳会很高兴帮助你照料动物同伴的。她在碧蓝岗哨的旅馆外面等着你。', `FemaleText_loc5`='艾斯濱娜很高興可以照顧你的動物同伴，我的朋友。她在藍色守望的旅館外邊等待。', `FemaleText_loc7`='Esbina estará contenta de cuidar de tu compañero animal, $gamigo:amiga;. Te espera fuera de la posada, dentro de la Avanzada Azur.' WHERE `ID`=18300;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐! 너로 말미암아 창피한 일이 벌어진다면 난 에테리움을 수치스럽게 한 벌로 죽임을 당할 것이다.', `MaleText_loc4`='停下！你这样会让我变红，然后就会有人把我错当成复仇军并把把我干掉！', `MaleText_loc5`='噢，住手!你會讓我變成紅色，然後別人會把我誤認為以太皇族並且殺死我。', `MaleText_loc7`='¡Oh, para! Vas a hacer que me ponga rojo y, entonces, alguien me va a tomar por un miembro de El Etereum y me matará.' WHERE `ID`=18301;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 훈련을 받으러 오셨군요? 하늘 감시초소에는 여러 상급자들이 있답니다. 어떤 직업의 상급자를 찾으십니까?', `MaleText_loc4`='啊，你是想要训练吗？有几个导师在碧蓝岗哨那里……你想学什么？', `MaleText_loc5`='喔，尋找訓練師，是嗎?藍色守望有幾位訓練師...你追求的是什麼樣的訓練?', `MaleText_loc7`='Ah, buscas instrucción, ¿verdad? Hay varios instructores que acampan en la Avanzada Azur... ¿a quién buscas?', `FemaleText_loc1`='아, 훈련을 받으러 오셨군요? 하늘 감시초소에는 여러 상급자들이 있답니다. 어떤 직업의 상급자를 찾으시나요?', `FemaleText_loc4`='啊，你是想要训练吗？有几个导师在碧蓝岗哨那里……你想学什么？', `FemaleText_loc5`='喔，尋找訓練師，是嗎?藍色守望有幾位訓練師...你追求的是什麼樣的訓練?', `FemaleText_loc7`='Ah, buscas instrucción, ¿verdad? Hay varios instructores que acampan en la Avanzada Azur... ¿a quién buscas?' WHERE `ID`=18302;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 그들은 살게라스의 꼬임에 넘어가 지금은 우리의 가장 강력한 적이 되었습니다.', `MaleText_loc4`='然而他们受到了萨格拉斯的邪恶诱惑——现在他们变成了我们最强大的敌人。', `MaleText_loc5`='然而他們受到薩格拉斯邪惡的誘惑 - 現在他們已經成為我們最可怕的敵人。', `MaleText_loc7`='Pero cayeron en la atracción del mal de Sargeras – y ahora se han convertido en nuestros enemigos más acérrimos.', `FemaleText_loc1`='하지만 그들은 살게라스의 꼬임에 넘어가 지금은 우리의 가장 강력한 적이 되었습니다.', `FemaleText_loc4`='然而他们受到了萨格拉斯的邪恶诱惑——现在他们变成了我们最强大的敌人。', `FemaleText_loc5`='然而他們受到薩格拉斯邪惡的誘惑 - 現在他們已經成為我們最可怕的敵人。', `FemaleText_loc7`='Pero cayeron en la atracción del mal de Sargeras – y ahora se han convertido en nuestros enemigos más acérrimos.' WHERE `ID`=18303;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이쪽이 아니군요. 아르코누스는 광산의 반대편 끝에 있습니다. 설마 겁이 나서 그러는 건 아니겠지요? 저는 겁쟁이는 따라가지 않습니다.', `MaleText_loc4`='不是这条路。阿克努斯在矿洞的另一段。你不是想逃跑吧，伙计？我是不会跟着一个懦夫的。', `MaleText_loc5`='這是錯誤的方向。阿肯納斯在礦坑的另一端。你不是想逃跑吧，是嗎，膽小鬼?我不會跟隨一個懦夫的。', `MaleText_loc7`='Ese es el camino equivocado. Arconus está al otro extremo de la mina. ¿No te estarás acobardando, verdad, ser de carne? No seguiré a un cobarde.' WHERE `ID`=18304;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들은 강한 만큼이나 잔인합니다. 또한 존재하는 모든 것을 파괴하려 합니다.', `MaleText_loc4`='他们非常强大而残酷，以毁灭一切为乐。', `MaleText_loc5`='他們是殘忍而強大的 - 並且熱愛毀滅世上的一切。', `MaleText_loc7`='Son tan crueles como poderosos – y se deleitan con la destrucción de todo lo que existe.', `FemaleText_loc1`='그들은 강한 만큼이나 잔인합니다. 또한 존재하는 모든 것을 파괴하려 합니다.', `FemaleText_loc4`='他们非常强大而残酷，以毁灭一切为乐。', `FemaleText_loc5`='他們是殘忍而強大的 - 並且熱愛毀滅世上的一切。', `FemaleText_loc7`='Son tan crueles como poderosos – y se deleitan con la destrucción de todo lo que existe.' WHERE `ID`=18305;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드루이드라고요? 이곳에는 상급 드루이드가 없습니다만... 엑소다르 근처에 가면 당신의 설명과 일치하는 이가 있다는 말을 들은 것 같습니다. 샬란니우스라는 이름의 나이트 엘프입니다.', `MaleText_loc4`='德鲁伊？这里没人学习那种知识……但是我听说埃索达附近有些人很符合你的描述。好像是叫沙兰尤斯？', `MaleText_loc5`='德魯伊?這裡沒有人選擇追求德魯伊之路...但是我想我聽說在艾克索達附近有人符合你的描述。我想是薩娜妮斯嗎?', `MaleText_loc7`='¿Druida? Nadie aquí sigue ese camino... pero creo haber oído de alguien que coincide con esa descripción cerca de El Exodar. Shalannius, creo.', `FemaleText_loc1`='드루이드라고요? 이곳에는 상급 드루이드가 없습니다만... 엑소다르 근처에 가면 당신의 설명과 일치하는 이가 있다는 말을 들은 것 같습니다. 샬란니우스라는 이름의 나이트 엘프입니다.', `FemaleText_loc4`='德鲁伊？这里没人学习那种知识……但是我听说埃索达附近有些人很符合你的描述。好像是叫沙兰尤斯？', `FemaleText_loc5`='德魯伊?這裡沒有人選擇追求德魯伊之路...但是我想我聽說在艾克索達附近有人符合你的描述。我想是薩娜妮斯嗎?', `FemaleText_loc7`='¿Druida? Nadie aquí sigue ese camino... pero creo haber oído de alguien que coincide con esa descripción cerca de El Exodar. Shalannius, creo.' WHERE `ID`=18306;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실버문에 옷감을 기부하시겠다고요?$B$B매타조를 타려고 하시는군요. 잘됐군요... 누이 좋고 매부 좋은 일이죠. 이 도시를 위해 옷감을 좀 가져다주십시오. 제가 그대의 평판이 올라가도록 힘쓰겠습니다.', `MaleText_loc4`='什么？你想给银月城捐献布料吗？$B$B你只是想要只陆行鸟吧，不是吗？好吧，好吧……为这座城市捐献布料，我来负责让你声名远播。', `MaleText_loc5`='什麼?你希望捐贈布料給銀月城嗎?$B$B你只是為了陸行鷹而這麼做，不是嗎?非常好，非常好...為這城市而做的善行，我將保證提升你的聲望。', `MaleText_loc7`='¿Qué? ¿Quieres donar ropa a Lunargenta?$B$B¿Vas detrás de un jinete de halcón, verdad? Muy bien, muy bien... haz este favor a la ciudad, y me aseguraré de que tu reputación mejore.' WHERE `ID`=18307;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들은 두려움을 모르고 주인의 의지를 위해 맹목적으로 충성합니다.', `MaleText_loc4`='他们坚定而无畏地服从他们主人的任何命令。', `MaleText_loc5`='他們毫無畏懼而且堅定的效忠於主人威嚴的命令。', `MaleText_loc7`='Son intrépida y firmemente leales a la voluntad de su maestro, que para ellos es como un dios.', `FemaleText_loc1`='그들은 두려움을 모르고 주인의 의지를 위해 맹목적으로 충성합니다.', `FemaleText_loc4`='他们坚定而无畏地服从他们主人的任何命令。', `FemaleText_loc5`='他們毫無畏懼而且堅定的效忠於主人威嚴的命令。', `FemaleText_loc7`='Son intrépida y firmemente leales a la voluntad de su maestro, que para ellos es como un dios.' WHERE `ID`=18308;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='옥테온은 우리의 전문 추적자이자 좋은 친구입니다. 그가 입고 있는 가죽을 보면 그의 사냥 실력을 알 수 있지요. 그의 야영장은 하늘 감시초소의 남동쪽에 있으니 그리로 가 보십시오.', `MaleText_loc4`='艾克提恩是常驻这里的追踪者。而且他还干得很不错——他穿着的皮甲就是他技术的象征。他的营地就在碧蓝岗哨的东南方。', `MaleText_loc5`='艾克緹昂是我們的獵人代表，同時也是一名精通狩獵的獵人 - 他身上所穿的皮革就是他高超技術的證明。他的營地在藍色守望的東南邊。', `MaleText_loc7`='Acteon es nuestro rastreador residente, y es de los buenos, además – las pieles que viste son prueba de su destreza. Su campamento está al sureste de la Avanzada Azur.', `FemaleText_loc1`='옥테온은 우리의 전문 추적자이자 좋은 친구입니다. 그가 입고 있는 가죽을 보면 그의 사냥 실력을 알 수 있지요. 그의 야영장은 하늘 감시초소의 남동쪽에 있으니 그리로 가 보십시오.', `FemaleText_loc4`='艾克提恩是常驻这里的追踪者。而且他还干得很不错——他穿着的皮甲就是他技术的象征。他的营地就在碧蓝岗哨的东南方。', `FemaleText_loc5`='艾克緹昂是我們的獵人代表，同時也是一名精通狩獵的獵人 - 他身上所穿的皮革就是他高超技術的證明。他的營地在藍色守望的東南邊。', `FemaleText_loc7`='Acteon es nuestro rastreador residente, y es de los buenos, además – las pieles que viste son prueba de su destreza. Su campamento está al sureste de la Avanzada Azur.' WHERE `ID`=18309;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='느껴져요. 아르코누스가 가까이 있군요. 북서쪽 길로 가십시오. 위로 가서 모퉁이를 돌면 아르코누스가 있을 겁니다. 전투 준비를 하십시오!', `MaleText_loc4`='阿克努斯就在附近。我能感觉到他的气息。穿过西北面的那条小道。他应该就在那角落附近。准备战斗！', `MaleText_loc5`='阿肯納斯就在附近。我能感覺到他。在西北方的通道。順著通道上坡，他應該就在角落的附近。準備戰鬥!', `MaleText_loc7`='Arconus está cerca. Puedo sentirlo. Toma el paso noroeste. Debería estar justo allí. ¡Prepárate para luchar!' WHERE `ID`=18310;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파멸의 수호병은 자신들이 모시는 지옥의 군주에게 절대적으로 충성하며 세계를 파괴하는 것을 즐깁니다.', `MaleText_loc4`='末日守卫完全效忠于他们的主人深渊领主，享受着破坏世界的乐趣。', `MaleText_loc5`='末日守衛完全獻身於他們的主人深淵領主並且熱愛毀滅世上的一切事物。', `MaleText_loc7`='Los Guardias apocalípticos son totalmente fieles a sus señores del foso y se deleitan con la destrucción de los mundos.', `FemaleText_loc1`='파멸의 수호병은 자신들이 모시는 지옥의 군주에게 절대적으로 충성하며 세계를 파괴하는 것을 즐깁니다.', `FemaleText_loc4`='末日守卫完全效忠于他们的主人深渊领主，享受着破坏世界的乐趣。', `FemaleText_loc5`='末日守衛完全獻身於他們的主人深淵領主並且熱愛毀滅世上的一切事物。', `FemaleText_loc7`='Los Guardias apocalípticos son totalmente fieles a sus señores del foso y se deleitan con la destrucción de los mundos.' WHERE `ID`=18311;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저를 등지고 서십시오! 정확한 공격이 필요합니다!', `MaleText_loc4`='让它背对着我！我需要干净利落的一击！', `MaleText_loc5`='讓它背對我!我需要乾淨俐落的一擊!', `MaleText_loc7`='¡Gírale la espalda hacia mí! ¡Necesito un disparo limpio!' WHERE `ID`=18312;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간 낭비 같습니다. 공격은 언제 시작하죠?', `MaleText_loc4`='这是在浪费我的时间。快行动啊！', `MaleText_loc5`='這是在浪費我的時間。要從那裡開始?', `MaleText_loc7`='Esto es una pérdida de mi tiempo. ¿Dónde está la acción?' WHERE `ID`=18313;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 부상당했다는 말을 깜박했나요?', `MaleText_loc4`='我有没有跟你说我受伤了？', `MaleText_loc5`='我忘記提及我受傷了嗎?', `MaleText_loc7`='¿Olvidé mencionar que estoy herido?' WHERE `ID`=18314;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='솜씨가 나쁘지는 않군요. 풋내기치고...', `MaleText_loc4`='对于一个血肉之躯来说……已经射得不错了。', `MaleText_loc5`='射的不錯。對一個菜鳥來說...', `MaleText_loc7`='No ha sido un mal disparo. Para un ser de carne...' WHERE `ID`=18315;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 살덩이괴물이 싫어...', `MaleText_loc4`='我讨厌血肉兽……', `MaleText_loc5`='我討厭噬屍獸...', `MaleText_loc7`='Odio las bestias de carne...' WHERE `ID`=18316;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비전 마법을 배우고 싶다면 하늘 감시초소의 동쪽에서 루아다와 함께 제자들을 가르치고 있는 세미드를 찾아가도록 하십시오.', `MaleText_loc4`='如果想要掌握奥术魔法，你只需要去找塞米德就可以了。他就在碧蓝岗哨的东边，和鲁安达在一起。', `MaleText_loc5`='想精通秘法的話，找希蜜德就對了。他在藍色守望東邊提供秘法的訓練，在羅達的旁邊。', `MaleText_loc7`='Para el dominio de lo Arcano, no necesitas buscar más lejos que Semid. Instruye en el extremo oriental de la Avanzada Azur, junto con Ruada.', `FemaleText_loc1`='비전 마법을 배우고 싶다면 하늘 감시초소의 동쪽에서 루아다와 함께 제자들을 가르치고 있는 세미드를 찾아가도록 하십시오.', `FemaleText_loc4`='如果想要掌握奥术魔法，你只需要去找塞米德就可以了。他就在碧蓝岗哨的东边，和鲁安达在一起。', `FemaleText_loc5`='想精通秘法的話，找希蜜德就對了。他在藍色守望東邊提供秘法的訓練，在羅達的旁邊。', `FemaleText_loc7`='Para el dominio de lo Arcano, no necesitas buscar más lejos que Semid. Instruye en el extremo oriental de la Avanzada Azur, junto con Ruada.' WHERE `ID`=18317;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 환영은 정말 약하네요. 저 야만스러운 족속이 제 귀중한 환영에 손도 대지 못하게 하십시오.', `MaleText_loc4`='我的这个影像异常地微弱。不要让这些野蛮的家伙碰到我宝贵的影像。', `MaleText_loc5`='我的化身非常的脆弱。不要讓這些野獸的髒手碰到我寶貴的化身。', `MaleText_loc7`='Este reflejo de mí es excepcionalmente débil. No dejes que esos brutos pongan un dedo en mi preciosa imagen.' WHERE `ID`=18318;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='툴라스는 고귀한 여성으로서 성스러운 빛의 강력한 수호자랍니다. 그녀는 여관에서 드레나이들을 가르치고 있으니 그리로 가 보십시오.', `MaleText_loc4`='图拉丝是一位高贵的女士，也是坚定的圣光卫士。她在旅店内传授着她的课程。', `MaleText_loc5`='對人和善的朵拉斯是一名高尚的婦女，和一名英勇的聖光防衛者。她在旅館裡提供訓練。', `MaleText_loc7`='La buena Tullas es una mujer noble y una defensora incondicional de la Luz. Sus lecciones se instruyen en la misma posada.', `FemaleText_loc1`='툴라스는 고귀한 여성으로서 성스러운 빛의 강력한 수호자랍니다. 그녀는 여관에서 드레나이들을 가르치고 있으니 그리로 가 보십시오.', `FemaleText_loc4`='图拉丝是一位高贵的女士，也是坚定的圣光卫士。她在旅店内传授着她的课程。', `FemaleText_loc5`='對人和善的朵拉斯是一名高尚的婦女，和一名英勇的聖光防衛者。她在旅館裡提供訓練。', `FemaleText_loc7`='La buena Tullas es una mujer noble y una defensora incondicional de la Luz. Sus lecciones se instruyen en la misma posada.' WHERE `ID`=18319;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='작지만 편리한 첼란의 여관에 가면 사제인 구반을 만날 수 있습니다.', `MaleText_loc4`='你可以在谢尔兰的那座很小但很实用的旅店里找到牧师古安。', `MaleText_loc5`='在查倫小而服務良好的小酒館裡，你能找到牧師古樊。', `MaleText_loc7`='En la pequeña, pero buena posada de Chellan, puedes encontrar al sacerdote Guvan.', `FemaleText_loc1`='작지만 편리한 첼란의 여관에 가면 사제인 구반을 만날 수 있습니다.', `FemaleText_loc4`='你可以在谢尔兰的那座很小但很实用的旅店里找到牧师古安。', `FemaleText_loc5`='在查倫小而服務良好的小酒館裡，你能找到牧師古樊。', `FemaleText_loc7`='En la pequeña, pero buena posada de Chellan, puedes encontrar al sacerdote Guvan.' WHERE `ID`=18320;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주술사', `MaleText_loc4`='萨满祭司', `MaleText_loc5`='薩滿', `MaleText_loc7`='Chamán', `FemaleText_loc1`='주술사', `FemaleText_loc4`='萨满祭司', `FemaleText_loc5`='薩滿', `FemaleText_loc7`='Chamán' WHERE `ID`=18321;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신도 주술사입니까? 흠, 어떤 길을 선택할지는 모르겠지만 그 선택은 당신이 하는 것이겠죠... 상급 주술사인 툴룬은 하늘 감시초소의 북서쪽 외딴 곳에 작은 야영지에 있습니다.', `MaleText_loc4`='你是个萨满祭司？嗯，你可以自行决定未来要走的道路……哪条道路都行。图伦就在碧蓝岗哨西北方某处僻静的小营地里。', `MaleText_loc5`='你也是薩滿的一員嗎?嗯。我認為你可以自由地選擇你自己的道路...無論那條道路可能是什麼。塔奴藍在藍色守望的西北有一個孤立的小營地。', `MaleText_loc7`='¿Eres uno de los chamanes? Mm. Supongo que eres libre de escoger tu propio camino... sea cual sea. Tuluun tiene un pequeño campamento aislado al noroeste de la Avanzada Azur.', `FemaleText_loc1`='당신도 주술사입니까? 흠, 어떤 길을 선택할지는 모르겠지만 그 선택은 당신이 하는 것이겠죠... 상급 주술사인 툴룬은 하늘 감시초소의 북서쪽 외딴 곳에 작은 야영지에 있습니다.', `FemaleText_loc4`='你是个萨满祭司？嗯，你可以自行决定未来要走的道路……哪条道路都行。图伦就在碧蓝岗哨西北方某处僻静的小营地里。', `FemaleText_loc5`='你也是薩滿的一員嗎?嗯。我認為你可以自由地選擇你自己的道路...無論那條道路可能是什麼。塔奴藍在藍色守望的西北有一個孤立的小營地。', `FemaleText_loc7`='¿Eres uno de los chamanes? Mm. Supongo que eres libre de escoger tu propio camino... sea cual sea. Tuluun tiene un pequeño campamento aislado al noroeste de la Avanzada Azur.' WHERE `ID`=18322;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='루아다는 하늘 감시초소의 동쪽에서 초년병 전사들을 가르치고 있습니다. 전투에서 도움이 되는 실용적인 기술을 배우고 싶다면 그녀에게 배우는 게 좋을 겁니다.', `MaleText_loc4`='鲁安达在碧蓝岗哨的东部训练年轻的战士们。如果你想要提高作战技术的话，找她就对了。', `MaleText_loc5`='羅達在藍色守望東部訓練年輕的戰士。如果實戰技藝方面的訓練是你所追尋的，她將對你有幫助。', `MaleText_loc7`='Ruada instruye a jóvenes combatientes en la parte oriental de la Avanzada Azur. Si lo que buscas es instrucción en el arte práctico de la guerra, ella te ayudará.', `FemaleText_loc1`='루아다는 하늘 감시초소의 동쪽에서 초년병 전사들을 가르치고 있습니다. 전투에서 도움이 되는 실용적인 기술을 배우고 싶다면 그녀에게 배우는 게 좋을 겁니다.', `FemaleText_loc4`='鲁安达在碧蓝岗哨的东部训练年轻的战士们。如果你想要提高作战技术的话，找她就对了。', `FemaleText_loc5`='羅達在藍色守望東部訓練年輕的戰士。如果實戰技藝方面的訓練是你所追尋的，她將對你有幫助。', `FemaleText_loc7`='Ruada instruye a jóvenes combatientes en la parte oriental de la Avanzada Azur. Si lo que buscas es instrucción en el arte práctico de la guerra, ella te ayudará.' WHERE `ID`=18323;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하늘안개 섬 전역에 걸쳐 뛰어난 상급 기술자들이 많이 있답니다. 어떤 전문가를 찾으십니까?', `MaleText_loc4`='有几个熟练的工匠分散在秘蓝岛周围。你在找哪一个？', `MaleText_loc5`='許多訓練師散佈在藍謎島周圍。你在尋找哪一個?', `MaleText_loc7`='Hay varios mercaderes diestros esparcidos por Bruma Azur. ¿A quién buscas?', `FemaleText_loc1`='하늘안개 섬 전역에 걸쳐 뛰어난 상급 기술자들이 많이 있답니다. 어떤 전문가를 찾으십니까?', `FemaleText_loc4`='有几个熟练的工匠分散在秘蓝岛周围。你在找哪一个？', `FemaleText_loc5`='許多訓練師散佈在藍謎島周圍。你在尋找哪一個?', `FemaleText_loc7`='Hay varios mercaderes diestros esparcidos por Bruma Azur. ¿A quién buscas?' WHERE `ID`=18324;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 죽은 척하기를 그만두고 앞으로 돌격합니다!', `MaleText_loc4`='%s停止装死，向前冲锋！', `MaleText_loc5`='%s停止裝死並且向前衝鋒!', `MaleText_loc7`='¡%s deja de fingir la muerte y carga!' WHERE `ID`=18325;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연금술이라면 물약 제조 기술을 잘 알고 있는 대달이 적격이지요. 그는 하늘 감시초소의 서쪽에 있는 파티마 옆에서 일하고 있습니다.', `MaleText_loc4`='丹达尔对配制药水的技术非常在行。他就在碧蓝岗哨的西部，和法蒂玛一起工作。', `MaleText_loc5`='爹達歐精通於藥劑的製作。他在藍色守望西方的法禔瑪附近工作。', `MaleText_loc7`='Daedal conoce el arte de elaborar pociones. Trabaja estrechamente con Fateema en el extremo oriental de la Avanzada Azur.', `FemaleText_loc1`='연금술이라면 물약 제조 기술을 잘 알고 있는 대달이 적격이지요. 그는 하늘 감시초소의 서쪽에 있는 파티마 옆에서 일하고 있습니다.', `FemaleText_loc4`='丹达尔对配制药水的技术非常在行。他就在碧蓝岗哨的西部，和法蒂玛一起工作。', `FemaleText_loc5`='爹達歐精通於藥劑的製作。他在藍色守望西方的法禔瑪附近工作。', `FemaleText_loc7`='Daedal conoce el arte de elaborar pociones. Trabaja estrechamente con Fateema en el extremo oriental de la Avanzada Azur.' WHERE `ID`=18326;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하늘 감시초소에는 대장간이 없습니다만 남쪽 해안에 있는 그 이상한 야영지에서 젊은 대장장이들이 오는 것을 목격한 적이 몇 번 있습니다. 그곳으로 가 보시는 게 좋을 것 같군요.', `MaleText_loc4`='在碧蓝岗哨这里，我们没有设立铁匠铺。不过，我曾看到几个年轻的铁匠从南海岸的临时营地那里过来，也许你应该去那里看看。', `MaleText_loc5`='藍色守望沒有鐵匠。不過，我看過一些年輕的鐵匠來自南岸上那古怪的營地。或許你應該進行調查。', `MaleText_loc7`='No tenemos herrería establecida en la Avanzada Azur. Sin embargo, he visto a varios herreros jóvenes venir de aquel campamento extraño en la costa sur. Quizás deberías investigar.', `FemaleText_loc1`='하늘 감시초소에는 대장간이 없지만 남쪽 해안에 있는 그 이상한 야영지에서 젊은 대장장이들이 오는 것을 목격한 적이 몇 번 있습니다. 그곳으로 가 보시는 게 좋을 것 같군요.', `FemaleText_loc4`='在碧蓝岗哨这里，我们没有设立铁匠铺。不过，我曾看到几个年轻的铁匠从南海岸的临时营地那里过来，也许你应该去那里看看。', `FemaleText_loc5`='藍色守望沒有鐵匠。不過，我看過一些年輕的鐵匠來自南岸上那古怪的營地。或許你應該進行調查。', `FemaleText_loc7`='No tenemos herrería establecida en la Avanzada Azur. Sin embargo, he visto a varios herreros jóvenes venir de aquel campamento extraño en la costa sur. Quizás deberías investigar.' WHERE `ID`=18327;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 감시초소엔 요리사가 없습니다. 그런데 이상한 것은... 남풍에 좋은 냄새가 실려온다는 거랍니다. 냄새가 나는 방향으로 가 보는 게 어떻습니까?', `MaleText_loc4`='我们没有多余的食物可以分享了，但是有点奇怪……从南方吹来的风中夹杂着诱人的香味。不如去那边看看？', `MaleText_loc5`='我們沒有多餘的廚師，但是很奇怪...南風吹來一些令人流口水的味道。跟隨你的鼻子走，好嗎?', `MaleText_loc7`='No teníamos cocineros de sobras, pero es un poco raro... hay algunos aromas deliciosos en el viento del sur. Sigue tu nariz, ¿eh?', `FemaleText_loc1`='이 감시초소엔 요리사가 없습니다. 그런데 이상한 것은... 남풍에 좋은 냄새가 실려온다는 거랍니다. 냄새가 나는 방향으로 가 보는 게 어떻습니까?', `FemaleText_loc4`='我们没有多余的食物可以分享了，但是有点奇怪……从南方吹来的风中夹杂着诱人的香味。不如去那边看看？', `FemaleText_loc5`='我們沒有多餘的廚師，但是很奇怪...南風吹來一些令人流口水的味道。跟隨你的鼻子走，好嗎?', `FemaleText_loc7`='No teníamos cocineros de sobras, pero es un poco raro... hay algunos aromas deliciosos en el viento del sur. Sigue tu nariz, ¿eh?' WHERE `ID`=18328;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나호그와 같은 우리 마법부여사들은 엑소다르에서 열심히 연구를 하며 바쁜 시간을 보내고 있으니, 그녀를 만나면 당신에게 더 깊은 마법 부여의 세계를 보여줄 것입니다.', `MaleText_loc4`='我们的附魔师们在埃索达研究各种课题，纳霍加可以教你一些初步的知识。', `MaleText_loc5`='我們的附魔師在艾克索達度過他們的日子，進行許多附魔工程。奈歐格將開始訓練你。', `MaleText_loc7`='Nuestros encantadores se pasan el día en El Exodar, trabajando en varios proyectos. Nahogg iniciará tu instrucción.', `FemaleText_loc1`='나호그와 같은 우리 마법부여사들은 엑소다르에서 열심히 연구를 하며 바쁜 시간을 보내고 있으니, 그녀를 만나면 당신에게 더 깊은 마법 부여의 세계를 보여줄 겁니다.', `FemaleText_loc4`='我们的附魔师们在埃索达研究各种课题，纳霍加可以教你一些初步的知识。', `FemaleText_loc5`='我們的附魔師在艾克索達度過他們的日子，進行許多附魔工程。奈歐格將開始訓練你。', `FemaleText_loc7`='Nuestros encantadores se pasan el día en El Exodar, trabajando en varios proyectos. Nahogg iniciará tu instrucción.' WHERE `ID`=18329;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳의 기술병인 다엘로라면 당신에게 기계공학의 기초를 가르쳐 줄 수 있을 겁니다. 아마 당신이 우리 기술자가 고장 난 통신 장비를 고치는 일을 도와줄 수 있겠군요!', `MaleText_loc4`='这里的技师，戴罗，可以教你些基础的工程学知识。也许你可以帮助我们的技术员修理那个坏掉的通信设备！', `MaleText_loc5`='本地的巧匠戴洛能教你工程學的基礎。或許你能幫助我們的技師修理那個故障的通訊設備!', `MaleText_loc7`='El artificiero local, Daelo, puede enseñarte las bases de la ingeniería. ¡Quizás podrías ayudar a nuestro técnico a reparar el dispositivo de comunicaciones que funciona mal!', `FemaleText_loc1`='이곳의 기술병인 다엘로라면 당신에게 기계공학의 기초를 가르쳐 줄 수 있을 겁니다. 아마 당신이 우리 기술자가 고장 난 통신 장비를 고치는 일을 도와줄 수 있겠군요!', `FemaleText_loc4`='这里的技师，戴罗，可以教你些基础的工程学知识。也许你可以帮助我们的技术员修理那个坏掉的通信设备！', `FemaleText_loc5`='本地的巧匠戴洛能教你工程學的基礎。或許你能幫助我們的技師修理那個故障的通訊設備!', `FemaleText_loc7`='El artificiero local, Daelo, puede enseñarte las bases de la ingeniería. ¡Quizás podrías ayudar a nuestro técnico a reparar el dispositivo de comunicaciones que funciona mal!' WHERE `ID`=18330;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파티마는 우리 수도자로서 추락 사고로 다친 이들을 돌보는 데 큰 역할을 하고 있답니다. 그녀는 하늘 감시초소의 서쪽에서 일을 하고 있으니 그리로 가면 만날 수 있을 겁니다.', `MaleText_loc4`='法蒂玛是我们的学者，她在照顾坠毁事故受害者的过程中起到了无法估量的作用。她就在岗哨的西边。', `MaleText_loc5`='法禔瑪是我們的隱士，並且在照料傷者的領域裡面是無價的。她在藍色守望的西邊實行她的醫術。', `MaleText_loc7`='Fateema es nuestra anacoreta, y ha sido inestimable para cuidar a las víctimas del accidente. Practica su oficio en el extremo occidental de la Avanzada.', `FemaleText_loc1`='파티마는 우리 수도자로서 추락 사고로 다친 이들을 돌보는 데 큰 역할을 하고 있답니다. 그녀는 하늘 감시초소의 서쪽에서 일을 하고 있으니 그리로 가면 만날 수 있을 겁니다.', `FemaleText_loc4`='法蒂玛是我们的学者，她在照顾坠毁事故受害者的过程中起到了无法估量的作用。她就在岗哨的西边。', `FemaleText_loc5`='法禔瑪是我們的隱士，並且在照料傷者的領域裡面是無價的。她在藍色守望的西邊實行她的醫術。', `FemaleText_loc7`='Fateema es nuestra anacoreta, y ha sido inestimable para cuidar a las víctimas del accidente. Practica su oficio en el extremo occidental de la Avanzada.' WHERE `ID`=18331;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야심만만한 낚시꾼이라... 뭐, 딕티나는 암멘 여울의 해안에 살고 있는데 그물과 막대기로 고기를 잡아 우리 모두에게 생선을 공급하고 있답니다. 그녀에게 가면 도울 일이 있을 겁니다.', `MaleText_loc4`='一个热心的钓鱼者……好吧，迪泰娜就住在埃门海滩的岸边，用她的网和鱼竿让我们有源源不断的鱼可吃。我相信她需要一些帮助。', `MaleText_loc5`='一個有抱負的釣魚者...嗯，狄克泰納住在安曼淺灘的岸上，用她的網和釣魚竿持續提供我們所需。我肯定她能幫助你。', `MaleText_loc7`='$gUn:Una; aspirante a pescador... bueno, Diktynna vive en la costa del Vado Ammen, y usa su red y su palo para mantenernos abastecidos a todos. Estoy seguro de que tu ayuda le iría bien.', `FemaleText_loc1`='야심만만한 낚시꾼이라... 뭐, 딕티나는 암멘 여울의 해안에 살고 있는데 그물과 막대기로 고기를 잡아 우리 모두에게 생선을 공급하고 있답니다. 그녀에게 가면 도울 일이 있을 겁니다.', `FemaleText_loc4`='一个热心的钓鱼者……好吧，迪泰娜就住在埃门海滩的岸边，用她的网和鱼竿让我们有源源不断的鱼可吃。我相信她需要一些帮助。', `FemaleText_loc5`='一個有抱負的釣魚者...嗯，狄克泰納住在安曼淺灘的岸上，用她的網和釣魚竿持續提供我們所需。我肯定她能幫助你。', `FemaleText_loc7`='$gUn:Una; aspirante a pescador... bueno, Diktynna vive en la costa del vado Ammen, y usa su red y su palo para mantenernos abastecidos a todos. Estoy segura de que tu ayuda le iría bien.' WHERE `ID`=18332;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헤우르는 우리가 이곳에 도착한 이후로 줄곧 이 지역의 식물을 연구해 왔으니 그라면 당신에게 약초채집의 길을 가르칠 수 있을 겁니다. 하늘 감시초소의 서쪽 끝에 가면 대달과 함께 일하고 있는 헤우르를 찾을 수 있을 겁니다.', `MaleText_loc4`='自从我们降落以后，赫罗就研究起了这里的植物，他会指导你的。你可以在碧蓝岗哨的西部边缘发现他正在和丹达尔一起工作。', `MaleText_loc5`='赫爾從我們的到達起已經著手於研究本地植物。他能指引你的道路。你能發現他在藍色守望西部邊緣上與爹達歐一起工作。', `MaleText_loc7`='Heur ha estudiado la flora local desde nuestro aterrizaje. Podrá guiarte. Puedes encontrarle trabajando con Daedal en el margen occidental de la Avanzada Azur.', `FemaleText_loc1`='헤우르는 우리가 이곳에 도착한 이후로 줄곧 이 지역의 식물을 연구해 왔으니 그라면 당신에게 약초채집의 길을 가르칠 수 있을 겁니다. 하늘 감시초소의 서쪽 끝에 가면 대달과 함께 일하고 있는 헤우르를 찾을 수 있을 겁니다.', `FemaleText_loc4`='自从我们降落以后，赫罗就研究起了这里的植物，他会指导你的。你可以在碧蓝岗哨的西部边缘发现他正在和丹达尔一起工作。', `FemaleText_loc5`='赫爾從我們的到達起已經著手於研究本地植物。他能指引你的道路。你能發現他在藍色守望西部邊緣上與爹達歐一起工作。', `FemaleText_loc7`='Heur ha estudiado la flora local desde nuestro aterrizaje. Podrá guiarte. Puedes encontrarle trabajando con Daedal en el margen occidental de la Avanzada Azur.' WHERE `ID`=18333;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 새로운 동맹 너울소나무 펄볼그는 우리가 어떤 가죽을 사용하는지에 관심을 보이더군요. 저는 북쪽에 살고 있는 그들에게 가죽세공을 배울 작정이랍니다.', `MaleText_loc4`='我们的新朋友——止松要塞的熊怪们对我们找到的皮革表现出了很强烈的兴趣。他们就住在北面，不如去他们那里问问看。', `MaleText_loc5`='我們的新盟友靜松熊怪，已經談及對我們找到的皮革感興趣。他們住在北方;你可以從他們身上學習知識。', `MaleText_loc7`='Nuestros nuevos aliados, los fúrbolgs de Semprepino, han mostrado su interés en llevarse todas las pieles que encontremos. Viven al norte; yo acudiría a ellos en busca de conocimiento.', `FemaleText_loc1`='우리의 새로운 동맹 너울소나무 펄볼그는 우리가 어떤 가죽을 사용하는지에 관심을 보이더군요. 저는 북쪽에 살고 있는 그들에게 가죽세공을 배울 작정이랍니다.', `FemaleText_loc4`='我们的新朋友——止松要塞的熊怪们对我们找到的皮革表现出了很强烈的兴趣。他们就住在北面，不如去他们那里问问看。', `FemaleText_loc5`='我們的新盟友靜松熊怪，已經談及對我們找到的皮革感興趣。他們住在北方;你可以從他們身上學習知識。', `FemaleText_loc7`='Nuestros nuevos aliados, los fúrbolgs de Semprepino, han mostrado su interés en llevarse todas las pieles que encontremos. Viven al norte; yo acudiría a ellos en busca de conocimiento.' WHERE `ID`=18334;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 찾는 전문가는 바로 둘비로군요. 그녀는 하늘 감시초소의 가운데에서 다른 자들을 훈련하고 있으니 그리로 가 보시기 바랍니다.', `MaleText_loc4`='去找杜尔维。她在岗哨的中间传授着勘测矿藏的技能。', `MaleText_loc5`='杜維是你想找的人。她在藍色守望中間訓練採礦者。', `MaleText_loc7`='Dulvi es la mujer que quieres. Instruye a nuevas posibilidades en medio de la Avanzada.', `FemaleText_loc1`='당신이 찾는 전문가는 바로 둘비로군요. 그녀는 하늘 감시초소의 가운데에서 다른 자들을 훈련하고 있으니 그리로 가 보시기 바랍니다.', `FemaleText_loc4`='去找杜尔维。她在岗哨的中间传授着勘测矿藏的技能。', `FemaleText_loc5`='杜維是你想找的人。她在藍色守望中間訓練採礦者。', `FemaleText_loc7`='Dulvi es la mujer que quieres. Instruye a los nuevos en medio de la Avanzada.' WHERE `ID`=18335;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너울소나무 요새로 가십시오. 그곳의 펄볼그들은 매우 많은 도움을 주었으며 당신이 원하는 기술의 전문가들이랍니다.', `MaleText_loc4`='去止松要塞看看，我的朋友。那里的熊怪非常乐于帮助我们，也许你可以在那里找到你所需要的知识。', `MaleText_loc5`='前往靜松要塞吧，我的朋友。那裡的熊怪提供非常大的幫助，並且他們可能正好有你需要的專門技能。', `MaleText_loc7`='Viaja al Bastión Semprepino, $gamigo:amiga;. Los fúrbolgs que hay allí han sido muy útiles, y puede que tengan justo la pericia que necesitas.', `FemaleText_loc1`='너울소나무 요새로 가십시오. 그곳의 펄볼그들은 매우 많은 도움을 주었으며 당신이 원하는 기술의 전문가들이랍니다.', `FemaleText_loc4`='去止松要塞看看，我的朋友。那里的熊怪非常乐于帮助我们，也许你可以在那里找到你所需要的知识。', `FemaleText_loc5`='前往靜松要塞吧，我的朋友。那裡的熊怪提供非常大的幫助，並且他們可能正好有你需要的專門技能。', `FemaleText_loc7`='Viaja al Bastión Semprepino, $gamigo:amiga;. Los fúrbolgs que hay allí han sido muy útiles, y puede que tengan justo la pericia que necesitas.' WHERE `ID`=18336;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하늘 감시초소에는 재봉사가 없습니다만 해변에 있는 야영지에 가 보시는 것도 괜찮을 겁니다. 바다 건너에서 온 상인들이 많은 것 같았으니 말입니다.', `MaleText_loc4`='碧蓝岗哨这边没有裁缝。不过你可以去海滩旁的营地问问，他们似乎带来了一些裁缝。', `MaleText_loc5`='藍色守望這裡沒有裁縫師。但是，你可以去海灘上的營地找找看 - 他們有許多從海外來經商的訓練師。', `MaleText_loc7`='No tenemos sastres en la Avanzada Azur. Pero quizás quieras probar en el campamento de la playa – parecen tener varios mercaderes del otro lado del mar.', `FemaleText_loc1`='하늘 감시초소에는 재봉사가 없습니다만 해변에 있는 야영지에 가 보시는 것도 괜찮을 겁니다. 바다 건너에서 온 상인들이 많은 것 같았으니 말입니다.', `FemaleText_loc4`='碧蓝岗哨这边没有裁缝。不过你可以去海滩旁的营地问问，他们似乎带来了一些裁缝。', `FemaleText_loc5`='藍色守望這裡沒有裁縫師。但是，你可以去海灘上的營地找找看 - 他們有許多從海外來經商的訓練師。', `FemaleText_loc7`='No tenemos sastres en la Avanzada Azur. Pero quizás quieras probar en el campamento de la playa – parecen tener varios mercaderes del otro lado del mar.' WHERE `ID`=18337;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보석세공', `MaleText_loc4`='珠宝加工', `MaleText_loc5`='珠寶設計', `MaleText_loc7`='Joyería', `FemaleText_loc1`='보석세공', `FemaleText_loc4`='珠宝加工', `FemaleText_loc5`='珠寶設計', `FemaleText_loc7`='Joyería' WHERE `ID`=18338;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보석세공인을 찾으신다고요? 우리 보석세공인들은 엑소다르에서 그들이 발견한 재료를 가지고 멋진 세공을 하고 있습니다. 엑소다르로 가서 파리와 대화해 보십시오.', `MaleText_loc4`='在找宝石工匠吗？埃索达的珠宝匠们用双手雕琢出精美的工艺品，到那边找法里谈谈吧。', `MaleText_loc5`='找一位珠寶工匠嗎?我們的珠寶設計師在艾克索達，使用他們發現的天然寶石加工成華麗炫目的珠寶。在你抵達之後可以與法芮談談。', `MaleText_loc7`='¿Buscas un lapidario? Nuestros joyeros están en El Exodar, utilizando los materiales que han descubierto para hacer maravillas. Habla con Farii cuando llegues.', `FemaleText_loc1`='보석세공인을 찾으신다고요? 우리 보석세공인들은 엑소다르에서 그들이 발견한 재료를 가지고 멋진 세공을 하고 있습니다. 그곳에 도착하면 파리와 대화해 보십시오.', `FemaleText_loc4`='在找宝石工匠吗？埃索达的珠宝匠们用双手雕琢出精美的工艺品，到那边找法里谈谈吧。', `FemaleText_loc5`='找一位珠寶工匠嗎?我們的珠寶設計師在艾克索達，使用他們發現的天然寶石加工成華麗炫目的珠寶。在你抵達之後可以與法芮談談。', `FemaleText_loc7`='¿Buscas un lapidario? Nuestros joyeros están en El Exodar, utilizando los materiales que han descubierto para hacer maravillas. Habla con Farii cuando llegues.' WHERE `ID`=18339;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 원하신다고요?! 영웅의 계곡에 그 이상한 드레나이 중 한 명이 있다는 말을 들었습니다. 그녀라면 알고 있을지도 모르지만 저는 아는 게 없습니다.', `MaleText_loc4`='你要什么？！我听说英雄谷里有一个古怪的德莱尼女人。或许她知道。', `MaleText_loc5`='你想要什麼?!我聽到某些事情關於英雄谷裡其中一隻古怪的德萊尼生物。或許她知道;我不清楚。', `MaleText_loc7`='¡¿Que quieres qué?! He oído cosas sobre uno de esos extraños draenei en el Valle de los Héroes. Puede que ella sepa algo; yo no sé nada.', `FemaleText_loc1`='뭘 원하신다고요?! 영웅의 계곡에 그 이상한 드레나이 중 한 명이 있다는 말을 들었습니다. 그녀라면 알고 있을지도 모르지만 저는 아는 게 없답니다.', `FemaleText_loc4`='你要什么？！我听说英雄谷里有一个古怪的德莱尼女人。或许她知道。', `FemaleText_loc5`='你想要什麼?!我聽到某些事情關於英雄谷裡其中一隻古怪的德萊尼生物。或許她知道;我不清楚。', `FemaleText_loc7`='¡¿Que quieres qué?! He oído cosas sobre uno de esos extraños draenei en el Valle de los Héroes. Puede que ella sepa algo; yo no sé nada.' WHERE `ID`=18340;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='약해 빠진 놈! 덤벼봐라!', `MaleText_loc4`='你这个弱者！来吧！', `MaleText_loc5`='你太弱了!來吧!', `MaleText_loc7`='¡Eres débil! ¡VAMOS!' WHERE `ID`=18341;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공포가 뭔지 가르쳐 주마!', `MaleText_loc4`='现在你该知道什么是恐惧了！', `MaleText_loc5`='現在你將認識什麼是恐懼!', `MaleText_loc7`='¡Ahora conocerás el temor!' WHERE `ID`=18342;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살라다르 만세! 연합왕 만세!', `MaleText_loc4`='为了萨哈达尔！为了节点亲王！', `MaleText_loc5`='為薩哈達爾而戰!為奈薩斯王而戰!', `MaleText_loc7`='¡Por Salhadaar! ¡Por el rey-nexo!' WHERE `ID`=18343;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='순수한 힘을 느껴보아라!', `MaleText_loc4`='尝尝纯净的能量吧！', `MaleText_loc5`='嚐嚐看純淨能量的威力吧!', `MaleText_loc7`='¡Prueba energía pura!' WHERE `ID`=18344;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 전투 실력은 나에 비하면 한참 멀었구나!', `MaleText_loc4`='你的战力怎能与我相比！', `MaleText_loc5`='你的戰鬥本領與我的相比不算什麼!', `MaleText_loc7`='¡Tu destreza en la batalla no es nada comparada con la mía!' WHERE `ID`=18345;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 죽음은 감히 에테리움 영역에 발을 들여놓으려는 자들에게 좋은 본보기가 될 것이다!', `MaleText_loc4`='你的死将给那些妄想踏足复仇军领地的人以警示！', `MaleText_loc5`='你的死亡訊息將是所有敢踏足以太皇族領土之人的警惕!', `MaleText_loc7`='¡Tu muerte servirá como mensaje para todo aquel que ose pisar territorio de El Etereum!' WHERE `ID`=18346;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불쌍하군. 기껏 그 정도란 말인가?', `MaleText_loc4`='真可怜。你就这点能耐？', `MaleText_loc5`='可悲。你盡力也只能做到這種程度嗎?', `MaleText_loc7`='Patético. ¿Es eso lo mejor que puedes hacer?' WHERE `ID`=18347;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도망칠 수 있을 때 도망쳐라!', `MaleText_loc4`='在你还能逃跑的时候，赶快逃吧！', `MaleText_loc5`='趁你還能跑的時候趕快逃跑吧!', `MaleText_loc7`='¡Huye mientras puedas!' WHERE `ID`=18348;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 뒤틀린 드레나이 벌레 녀석이 지팡이를 줬군. 그렇지? 자기가 바로 동족을 팔아먹은 장본인이라는 말도 하던가? 어찌 됐든 네놈들은 대가를 치러야 한다!', `MaleText_loc4`='是那个破碎者渣滓给你这根法杖的吧？他有没有告诉你，他就是那个出卖自己同胞的家伙？无所谓，你们两个都会为此付出代价的！', `MaleText_loc5`='那個破碎者的可憐蟲給你那把杖，是嗎?他也告訴你他就是出賣他的部族的背叛者嗎?沒有關係，你們都將為此付出代價!', `MaleText_loc7`='Ese gusano Tábido te dio el bastón, ¿verdad? ¿También te dijo que es el que vendió su tribu a mi maestro? ¡No importa, ambos pagaréis por eso!' WHERE `ID`=18349;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='', `MaleText_loc4`='', `MaleText_loc5`='', `MaleText_loc7`='' WHERE `ID`=18350;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 뒤틀린 드레나이 녀석이 그 지팡이를 줬구나! 네게 순수하게 접근하던가!? 내가 모시는 분께 자기 일족을 팔아먹은 배신자가 본인이라는 말도 하던가?', `MaleText_loc4`='那个破碎者渣滓！他把什么都告诉你了吗？！他有没有告诉你，他就是那个把自己的部族出卖给我的主人的家伙？', `MaleText_loc5`='那個破碎者的可憐蟲!他對你招供了嗎!?他告訴你他是將他的部族出賣給我的主人的背叛者嗎?', `MaleText_loc7`='¡Ese gusano Tábido! ¿¡Ha confesado!? ¿Te ha dicho que es el que vendió su tribu a mi maestro?' WHERE `ID`=18351;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물의 정령이 우리를 떠났으니 우리 일족은 끝이구나.', `MaleText_loc4`='水流之灵遗弃了我们，族群必将毁灭。', `MaleText_loc5`='水靈已經離開我們。我們的部族厄運臨頭了。', `MaleText_loc7`='El espíritu de agua nos ha dejado. Nuestra tribu está condenada.' WHERE `ID`=18352;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자유롭게 가십시오, 장로님. 장로님의 일족에게로 다시 정령을 데리고 오십시오.', `MaleText_loc4`='去吧，长者。为你的部族带回那些元素之灵。', `MaleText_loc5`='自由地走吧，長者。把精靈們帶回你的部族。', `MaleText_loc7`='Camina libre, anciano. Trae los espíritus de vuelta a tu tribu.', `FemaleText_loc1`='자유롭게 가십시오, 장로님. 장로님의 일족에게로 다시 정령을 데리고 오십시오.', `FemaleText_loc4`='去吧，长者。为你的部族带回那些元素之灵。', `FemaleText_loc5`='自由地走吧，長者。把精靈們帶回你的部族。', `FemaleText_loc7`='Camina libre, anciano. Trae los espíritus de vuelta a tu tribu.' WHERE `ID`=18353;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바람이 더는 우리 일족에게 말을 하지 않는구려, $n. 우리 일족은 정령을 데리고 올 장로를 잃고 길을 헤매고 있소이다.', `MaleText_loc4`='风不再与我们的部族交流了，$n。如果没有长者将元素之灵召回来，我们将万劫不复。', `MaleText_loc5`='風已經不再跟我們的族人耳語了，$n。我的族人迷失了，我們需要長老將精靈們帶回部族。', `MaleText_loc7`='Los vientos ya no hablan con nuestra tribu, $n. Mi pueblo está perdido sin ancianos que les traigan los espíritus.' WHERE `ID`=18354;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 묶고 있는 이 사슬 때문에 우리 종족에게 불의 정령을 데리고 갈 수가 없소이다, $n. 불이 없는 영혼은 자신을 지배하고 있는 자에게 반항할 수가 없소.', `MaleText_loc4`='$n，我被这些镣铐束缚着，不能为我的部族带回火焰之灵。失去火焰之灵的灵魂如同傀儡，无法反抗他们的主人。', `MaleText_loc5`='這些綁住我的鎖鍊阻止我把火焰之靈帶到我的族人那裡，$n。一個缺少火的靈魂是不能反抗主人的靈魂。', `MaleText_loc7`='Estas cadenas que me atan me impiden llevar el espíritu del fuego a mi pueblo, $n. Las almas sin fuego son almas que no se pueden rebelar contra sus maestros.' WHERE `ID`=18355;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 자유로구나! 우리 일족이 그들의 주인과 싸울 용기를 얻을 수 있도록 불의 정령에게 돌아와 달라고 부탁하겠소이다! 고맙소.', `MaleText_loc4`='我自由了！我会请求火焰之灵回到族人身边去，这样我们或许就能鼓起勇气反抗主人了！谢谢你，$R。', `MaleText_loc5`='我自由啦!我將要求火的精靈返回我們部族，使我的族人有勇氣反抗他們的主人!感謝你，$r。', `MaleText_loc7`='¡Soy libre! Le pediré al espíritu del fuego que vuelva a nosotros, para que mi pueblo tenga el valor de luchar contra sus maestros. Gracias, $r.' WHERE `ID`=18356;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 자유다! 물의 정령이 우리 일족에게 돌아올 것이오. 그러면 우리는 이 험난한 땅에서 살아남을 수 있는 지혜를 얻을 수 있소이다. 당신에게 빚을 졌구려, $n.', `MaleText_loc4`='我自由了！水流之灵将回到族人身边去。在它的指引下，我们终将在这片荒芜的土地上生存下去。我欠你一个人情，$n。', `MaleText_loc5`='我自由了!水靈會回到我的族人那裡。它將為我們帶來在這塊嚴酷的土地裡生存所需要的智慧。我欠你人情，$n。', `MaleText_loc7`='¡Soy libre! El espíritu de agua vuelve a mi pueblo. Nos traerá la sabiduría que necesitamos para sobrevivir en esta dura tierra. Estoy en deuda contigo, $n.' WHERE `ID`=18357;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 날 구해 줬구려! 다시 한 번 바람이 우리 일족에게 말을 하고 힘을 주고 있소이다. 정말 고맙소.', `MaleText_loc4`='你给了我自由！风之灵又一次愿意与族人们交流并赐予我们力量了。谢谢你，陌生人。', `MaleText_loc5`='你已經釋放了我!風再一次的對我的族人耳語，並且賦予我們風的力量。感謝你，陌生人。', `MaleText_loc7`='¡Me has liberado! Los vientos vuelven a hablar con mi pueblo y nos otorgan su fuerza. Te lo agradezco, $gextranjero:extranjera;.' WHERE `ID`=18358;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 깃발을 차지했습니다!', `MaleText_loc4`='$n夺走了旗帜！', `MaleText_loc5`='$n已經奪走了旗幟!', `MaleText_loc7`='¡$n ha tomado la bandera!' WHERE `ID`=18359;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드워프 지구를 방문한 와일드해머 주술사들이 몇 명 있다고 들었으니, 그곳에서 운을 시험해 보시는 게 좋겠습니다.$B$B영웅의 계곡에서 빈둥거리던 드레나이 선견자도 그들을 만나러 갔답니다.', `MaleText_loc4`='我听说有两名蛮锤萨满进入了矮人区。你也许可以去那里试试你的运气。$B$B一直待在英雄谷的那位德莱尼先知也去找他们了。', `MaleText_loc5`='我聽說有兩個蠻錘的薩滿到了矮人區，所以你可以到那碰碰運氣。$B$B曾經待在英雄谷的德萊尼先知也已經去見他們了。', `MaleText_loc7`='He oído que hay un par de chamanes Martillo Salvaje de visita por el Distrito de los Enanos, así que puedes probar allí.$b$bLa clarividente draenei que solía andar por el Valle de los Héroes también ha ido a conocerlos.', `FemaleText_loc1`='드워프 지구를 방문한 와일드해머 주술사들이 몇 명 있다고 들었으니, 그곳에서 운을 시험해 보시는 게 좋겠습니다.$B$B영웅의 계곡에서 빈둥거리던 드레나이 선견자도 그들을 만나러 갔답니다.', `FemaleText_loc4`='我听说有两名蛮锤萨满进入了矮人区。你也许可以去那里试试你的运气。$B$B一直待在英雄谷的那位德莱尼先知也去找他们了。', `FemaleText_loc5`='我聽說有兩個蠻錘的薩滿到了矮人區，所以你可以到那碰碰運氣。$B$B曾經待在英雄谷的德萊尼先知也已經去見他們了。', `FemaleText_loc7`='He oído que hay un par de chamanes Martillo Salvaje de visita por el Distrito de los Enanos, así que puedes probar allí.$b$bLa clarividente draenei que solía andar por el Valle de los Héroes también ha ido a conocerlos.' WHERE `ID`=18360;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='깃발이 떨어졌습니다!', `MaleText_loc4`='旗帜被扔掉了！', `MaleText_loc5`='旗幟已經掉落!', `MaleText_loc7`='¡Ha caído la bandera!' WHERE `ID`=18361;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성기사', `MaleText_loc4`='圣骑士', `MaleText_loc5`='聖騎士', `MaleText_loc7`='Paladín', `FemaleText_loc1`='성기사', `FemaleText_loc4`='圣骑士', `FemaleText_loc5`='聖騎士', `FemaleText_loc7`='Paladín' WHERE `ID`=18362;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 성기사 아니다. 여자 엘프 하나 왕실에 있다. 그 엘프 성기사다. 그리 가서 배워라.', `MaleText_loc4`='我们不喜欢圣骑士。女精灵来到城市，在皇家区。她是圣骑士，和她说话，学习圣骑士的东西。', `MaleText_loc5`='我們不像聖騎士。精靈女士來到城市，待在皇家區。她的聖騎士。你說，學習聖騎士東西。', `MaleText_loc7`='Nosotros no gusta paladín. Elfa viene a ciudad. Barrio Real. Tú habla ella y aprender cosas de paladín.', `FemaleText_loc1`='우리 성기사 아니다. 여자 엘프 하나 왕실에 있다. 그 엘프 성기사다. 그리 가서 배워라.', `FemaleText_loc4`='我们不喜欢圣骑士。女精灵来到城市，在皇家区。她是圣骑士，和她说话，学习圣骑士的东西。', `FemaleText_loc5`='我們不像聖騎士。精靈女士來到城市，待在皇家區。她的聖騎士。你說，學習聖騎士東西。', `FemaleText_loc7`='Nosotros no gusta paladín. Elfa viene a ciudad. Barrio Real. Tú habla ella y aprender cosas de paladín.' WHERE `ID`=18363;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='깃발이 다시 제자리로 돌아갔습니다.', `MaleText_loc4`='旗帜被重新放置了。', `MaleText_loc5`='旗幟已重置。', `MaleText_loc7`='La bandera se ha restablecido.' WHERE `ID`=18364;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성기사라고? 자네 연금술사의 혼합물 같은 걸 마신 건가? 뭐, 엘프 사절단이 언더시티에 계시는 어둠의 여왕님을 알현하고 있다고 하더군. 그들 중 한 명이 성기사가 어디 있는지 알고 있을 거다.', `MaleText_loc4`='圣骑士？你是不是吃错药了还是怎么？我听到有传言说一个精灵代表团正在幽暗城拜访黑暗女王。也许他们之中有人会知道。', `MaleText_loc5`='聖騎士?你有沒有參與藥劑師會議或者其他相關的呢?我聽說某支精靈分隊前往拜訪幽暗城的黑暗女王。也許他們之中有人會知情。', `MaleText_loc7`='¿Paladín? ¿Has estado tomando pociones raras del boticario o algo así? He oído rumores de que un destacamento elfo ha visitado a la Dama Oscura en Entrañas. Puede que alguno de ellos sepa algo.', `FemaleText_loc1`='성기사라고? 자네 연금술사의 혼합물 같은 걸 마신 건가? 뭐, 엘프 사절단이 언더시티에 계시는 어둠의 여왕님을 알현하고 있다고 하더군. 그들 중 한 명이 성기사가 어디 있는지 알고 있을 거다.', `FemaleText_loc4`='圣骑士？你是不是吃错药了还是怎么？我听到有传言说一个精灵代表团正在幽暗城拜访黑暗女王。也许他们之中有人会知道。', `FemaleText_loc5`='聖騎士?你有沒有參與藥劑師會議或者其他相關的呢?我聽說某支精靈分隊前往拜訪幽暗城的黑暗女王。也許他們之中有人會知情。', `FemaleText_loc7`='¿Paladín? ¿Has estado tomando pociones raras del boticario o algo así? He oído rumores de que un destacamento elfo ha visitado a la Dama Oscura en Entrañas. Puede que alguno de ellos sepa algo.' WHERE `ID`=18365;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 들고 있던 무기를 버리고 장창을 꺼냅니다!', `MaleText_loc4`='%s扔掉了他的武器，拿起了一把长柄武器！', `MaleText_loc5`='%s丟掉他的武器並且伸手去拿長柄武器!', `MaleText_loc7`='¡%s deja sus armas y coge un arma de asta!' WHERE `ID`=18366;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겁쟁이 녀석! 넌 결코 날 어둠 속으로 끌고 갈 수 없을 것이다!', `MaleText_loc4`='懦夫！你们休想把我拉进阴影中！', `MaleText_loc5`='懦夫!你們絕不可能將我推入黑暗的深淵!', `MaleText_loc7`='¡Cobardes! ¡Nunca me arrastraréis a las sombras!' WHERE `ID`=18367;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 기진맥진합니다.', `MaleText_loc4`='%s已经精疲力尽了。', `MaleText_loc5`='%s精疲力盡了。', `MaleText_loc7`='%s está cansado.' WHERE `ID`=18368;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 지금 무슨 짓을 하고 있다고 생각하느냐? 감히 주인님의 실험을 방해하려는 것이냐?', `MaleText_loc4`='那么你觉得你正在干什么？你胆敢妨碍主人的实验？', `MaleText_loc5`='你認為你在做什麼?你敢干擾我主人的實驗?', `MaleText_loc7`='¿Qué crees que estás haciendo? ¿Osas interferir en el experimento de mi maestro?' WHERE `ID`=18369;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 여기서 한 일이 마음에 드나? 우리는 하늘에서 이 수정을 아웃랜드 전역에 뿌릴 것이다.', `MaleText_loc4`='你喜欢我们的成果吗？也许我们应该把这种水晶撒满整个外域。', `MaleText_loc5`='你喜歡我們在這裡的傑作嗎?或許我們會在整個外域的天空中降下這些水晶。', `MaleText_loc7`='¿Te gusta lo que hemos hecho aquí? Quizás dejemos caer estos cristales del cielo por toda Terrallende.' WHERE `ID`=18370;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 세계를 치유하고 거대괴수를 불러내서 미치게 하는 힘을 막으려는 네 행동이 점점 지겨워지는군. 거대괴수의 왕 골리아손이여, 캘타스 왕자와 내가 명하노니 이리 와서 수정을 보호해라!', `MaleText_loc4`='我渐渐对你尝试治愈这个大地、遏制能量召唤的行为感到厌烦了。葛利安索恩，巨人之王，凯尔萨斯王子和我命令你来保卫这块水晶！', `MaleText_loc5`='我對你企圖治癒土地、平息召喚和激怒巨像之能量的舉動已經失去了耐性。巨像之王哥利亞森，凱爾薩斯王子還有我命令你們保護水晶!', `MaleText_loc7`='Me he cansado de tus intentos por sanar la tierra y sofocar las energías que invocan y vuelven locos a los colosos. ¡Goliathon, rey de los colosos, el príncipe Kael''thas y yo te pedimos que vengas a defender el cristal!' WHERE `ID`=18371;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조만간 다시 만나게 될 것이다.', `MaleText_loc4`='我们很快就会再见面的。', `MaleText_loc5`='我們很快就會再見面。', `MaleText_loc7`='Nos volveremos a ver pronto.' WHERE `ID`=18372;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그대의 도움이 정말 큰 힘이 되었습니다.$B$B세나리온 원정대는 앞으로 일리단이 절대 하늘에서 오염된 수정을 떨어뜨리지 못하도록 온 힘을 다해 저지할 것입니다.', `FemaleText_loc4`='你的帮助是无价的，我的朋友。$B$B我敢保证塞纳里奥远征队会倾尽全力来抵抗伊利丹从天空中丢下来的任何污染水晶。', `FemaleText_loc5`='你的幫助是無價的，我的朋友。$B$B我能向你保證，塞納里奧遠征隊將用一切的力量反擊任何未來被伊利丹從天空降下的污染水晶。', `FemaleText_loc7`='Tu ayuda ha sido inestimable, $gamigo:amiga;.$B$BTe aseguro que la expedición Cenarion hará lo que pueda para luchar contra cualquier cristal máculo que caiga de los cielos enviado por Illidan.' WHERE `ID`=18373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='덤벼라!', `MaleText_loc4`='打我啊！', `MaleText_loc5`='攻擊我啊!', `MaleText_loc7`='¡PÉGAME!' WHERE `ID`=18374;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스가 깃발을 차지했습니다!', `MaleText_loc4`='联盟夺得了旗帜！', `MaleText_loc5`='聯盟已奪得旗幟!', `MaleText_loc7`='¡La Alianza ha capturado la bandera!' WHERE `ID`=18375;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얘들아! 내게로 와라!', `MaleText_loc4`='孩子们，来帮助我！', `MaleText_loc5`='孩子們，到我這兒來!', `MaleText_loc7`='¡Pequeños, vengan a mí!', `FemaleText_loc1`='얘들아! 내게로 와라!', `FemaleText_loc4`='孩子们，来帮助我！', `FemaleText_loc5`='孩子們，到我這兒來!', `FemaleText_loc7`='¡Pequeños, vengan a mí!' WHERE `ID`=18376;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하! 네 의식은 실패했다, 어리석은 것들!', `MaleText_loc4`='哈哈！你的典礼失败了，傻瓜！', `MaleText_loc5`='哈!你的儀式已經失敗了，傻瓜!', `MaleText_loc7`='¡Ja! ¡Tu ritual también ha fracasado!' WHERE `ID`=18377;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검투사를 데리고 와라!', `MaleText_loc4`='把角斗士带出来！', `MaleText_loc5`='帶鬥士出來!', `MaleText_loc7`='¡Sacad al gladiador!' WHERE `ID`=18378;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 살덩이마귀에게 걸겠어. 아주 무시무시하게 생겼잖아!', `MaleText_loc4`='我赌血肉魔赢。那个家伙很可怕！', `MaleText_loc5`='我的錢在食屍惡魔身上。那種怪物太恐怖了!', `MaleText_loc7`='Apuesto por el maligno de carne. ¡Esa criatura es terrorífica!' WHERE `ID`=18379;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자유연합 포로가 우리 검투사를 이길 가능성은 전혀 없어!', `MaleText_loc4`='维序派的囚犯不可能??我们的角斗士！', `MaleText_loc5`='護國者囚犯要戰勝我們的鬥士是不可能的!', `MaleText_loc7`='¡De ningún modo un prisionero del Protectorado va a derrotar a nuestro gladiador!' WHERE `ID`=18380;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황천의 바실리스크는 쉽지 않은 상대이지만 우리 검투사가 승리할 것이다!', `MaleText_loc4`='虚空蜥蜴会是个挑战，但是角斗士会渡过难关的！', `MaleText_loc5`='虛空蜥蜴將是一項挑戰，但是鬥士將克服困難!', `MaleText_loc7`='¡El abilisco será un desafío, pero el gladiador lo superará!' WHERE `ID`=18381;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생명이 없는 저 녀석을 어떻게 해치울 건가?', `MaleText_loc4`='越宅越厉害……', `MaleText_loc5`='你如何戰勝沒有生命的那些東西?', `MaleText_loc7`='¿Cómo vences a aquello que no tiene vida?' WHERE `ID`=18382;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사로잡힌 후부터 바위갈퀴가 불안정한 에너지를 흡수하고 있다는 말을 들었다고.', `MaleText_loc4`='我听说那些剥石者在被捕获后注射了不稳定的能量。', `MaleText_loc5`='我聽說岩石鐮奪怪自從捕獲後一直吸取不穩定的能量。', `MaleText_loc7`='He oído que el despellejador de roca ha estado succionando energía inestable desde que lo capturaron.' WHERE `ID`=18383;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드가 깃발을 차지했습니다!', `MaleText_loc4`='部落夺得了旗帜！', `MaleText_loc5`='部落已奪得旗幟!', `MaleText_loc7`='¡La Horda ha capturado la bandera!' WHERE `ID`=18384;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성스러운 빛이여! 제게 이 구원자를 살릴 힘을 주소서!', `MaleText_loc4`='圣光！不要辜负我！', `MaleText_loc5`='聖光!不要使我失望!', `MaleText_loc7`='¡Luz! ¡No me falles!' WHERE `ID`=18385;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구원자여, 제 앞에서 죽으면 안 됩니다!', `MaleText_loc4`='不要死在我面前，守备官！', `MaleText_loc5`='復仇者，不要在我眼前死掉!', `MaleText_loc7`='¡No me falles, vindicador!' WHERE `ID`=18386;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리에게는... 캘타스와 불타는 군단만이 필요해!', `MaleText_loc4`='凯尔萨斯和燃烧军团……来得正好！', `MaleText_loc5`='凱爾薩斯和燃燒軍團...正是我們需要的!', `MaleText_loc7`='Kael''thas y la Legión... ¡justo lo que necesitábamos!' WHERE `ID`=18387;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 절 구했군요! 야미르에게 당신의 고귀한 행동에 대해 말하겠습니다.', `MaleText_loc4`='你救了我的命！我会把你的功绩汇报给阿米尔的。', `MaleText_loc5`='你救了我，凡人!阿密爾會聽到你的高尚行為。', `MaleText_loc7`='¡Me has salvado, ser de carne! Ameer sabrá de este noble acto.' WHERE `ID`=18388;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='길 잃은 형제여, 우리는 당신을 도우려고 왔습니다. 당신의 목숨을 거두기 전에 회개할 기회를 주는 것이 관례입니다. 나루의 명령에 따라 당신에게 회개할 기회를 드리겠습니다.', `MaleText_loc4`='我们到这里来是为了消灭你，迷失的兄弟。按照传统，我们会在消灭你之前给你个忏悔的机会。按照纳鲁的律法，我们给你这个机会。', `MaleText_loc5`='我們為你而來，迷失的同胞。按照慣例在行刑之前都會提供一個的懺悔機會。依照那魯的法律命令，我們提供你這個機會。', `MaleText_loc7`='Estamos aquí por ti, hermano perdido. Es costumbre ofrecerte una oportunidad de arrepentirte antes de destruirte. Te ofrecemos esta oportunidad, como exige la ley de los naaru.' WHERE `ID`=18389;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 웃기지도 않는군. 날 죽이려고 왔다는 강력한 알도르 군대가 고작 이 정도란 말이냐?', `MaleText_loc4`='真是可笑。这就是前来消灭我的“强大的奥尔多军队”吗？', `MaleText_loc5`='不要逗我笑了。這就是要來擊敗我的強大奧多爾軍隊嗎?', `MaleText_loc7`='No me hagas reír. ¿Es este el poderoso ejército de los Aldor que ha venido a derrotarme?' WHERE `ID`=18390;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소크레타르, 우리의 수가 적을지는 모르지만 신념만큼은 굳건하다. 너는 절대 이해하지 못하겠지. 관례는 지켰으니 최후를 맞이할 준비나 해라.', `MaleText_loc4`='我们也许势单力薄，索克雷萨，但是我们有着强大的信念。有些东西你是永远都不会懂的。现在机会已经给过你了，准备迎接你的末日吧！', `MaleText_loc5`='我們也許人不多，索奎薩爾，但是我們的信念非常堅定。有些事你永遠都不會瞭解的。既然客套話已經說完了，準備去死吧。', `MaleText_loc7`='Puede que seamos pocos, Socrethar, pero nuestra fe es fuerte. Algo que nunca comprenderás. Ahora que se ha observado la costumbre, prepárate para tu fin.' WHERE `ID`=18391;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 상대해 주지. 그런데 시작하기 전에 먼저 너희가 만나볼 친구가 있다.', `MaleText_loc4`='好吧，让我们结束这一切吧。不管怎样，在我们开始之前，我想让你见一个人。', `MaleText_loc5`='是的，讓我們解決這件事。不過在我們開始之前，我想帶你見一個人。', `MaleText_loc7`='Sí, zanjemos esto. Sin embargo, antes de comenzar, hay alguien a quien me gustaría que conocierais.' WHERE `ID`=18392;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게... 네가 어떻게?!', `MaleText_loc4`='怎么……你怎么能？！', `MaleText_loc5`='你...你怎麼能?!', `MaleText_loc7`='¡¿Cómo... cómo has podido?!' WHERE `ID`=18393;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원수들이 우리 도시에 들어온 이후 내 가슴속은 증오로 가득 찼지. 보렌살이라는 자를 알았는데 그는 후에 현자라고 불리더군. 바로 놈의 손에 내 형제가 죽었는데 말이야.', `MaleText_loc4`='自从我们的死敌被允许进入我们的城市后，我的心中充满着仇恨。那个沃雷塔尔被称为先知以前，我就认识他了。正是他亲手杀死了我的兄弟。', `MaleText_loc5`='自從我們不共戴天的仇敵被容許進入我們的城市，我的心已經充滿了仇恨。我認得一個叫做沃藍索的占卜者，人們稱他為先知。我的兄弟就是被他親手殺死的。', `MaleText_loc7`='Mi corazón está lleno de odio desde que se permitió entrar en nuestra ciudad a nuestros enemigos acérrimos. Conocía al que llamaban Voren''thal, antes de ser conocido como vidente. Fue su mano la que asesinó a mi hermano.' WHERE `ID`=18394;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 그 증오를 일리단과 불타는 군단에게 돌렸지만 그들은 우리를 배신하지 않았어. 우리는 나루의 선택을 받았었지! 우리는 그들을 위해 살았고 그들을 위해 목숨도 바쳤어!', `MaleText_loc4`='我把那仇恨转移到了伊利达雷和燃烧军团身上……但是他们并不是那些背叛我们的家伙。纳鲁选择了我们！我们为了他们战斗到死！', `MaleText_loc5`='我將憎恨轉向伊利丹和燃燒軍團...但他們不是背叛我們的人。我們是那魯認定的人!我們因他們而活，為他們而死!', `MaleText_loc7`='Dirigí ese odio hacia los Illidari y la Legión Ardiente... pero no fueron ellos los que nos traicionaron. ¡Éramos los escogidos por los naaru! ¡Vivimos y morimos por ellos!' WHERE `ID`=18395;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마음속의 증오의 힘이 하나로 뭉치자 모든 것이 명확해졌다. 샤트라스와 함께 나루를 파괴해야 해.', `MaleText_loc4`='当我心中的仇恨开始凝聚之后，整件事情就开始变得清晰起来。沙塔斯城必须和纳鲁一起被毁灭。', `MaleText_loc5`='一旦我心中的恨意凝結成仇恨，我看清了一切。撒塔斯必須被毀滅，裡頭的那魯也是一樣。', `MaleText_loc7`='Cuando el odio de mi corazón se centró, lo tuve todo claro. Había que destruir Shattrath y, con ella, a los naaru.' WHERE `ID`=18396;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소크레타르가 네 정신을 흐리게 하고 있어, 카일란! 네가 그런 말을 할 리가 없는데! 열심히 훈련하던 네 어린 시절 모습을 난 기억한다. 그때 네 의지가 훨씬 강했어!', `MaleText_loc4`='索克雷萨蒙蔽了你的心灵，凯兰恩！这些话不是你的本意！我还记得你孩提时我训练你的情景。你的意志向来那么坚强！', `MaleText_loc5`='索奎薩爾矇蔽了你的心智，凱嵐!這不是你的本意!當你還年幼時，我記得訓練過你。你那時的意志還比較堅定!', `MaleText_loc7`='¡Socrethar te nubla la mente, Kaylaan! ¡No sientes esas palabras! Recuerdo instruirte cuando solo eras un jovenzuelo. ¡Tu voluntad ya era fuerte entonces!' WHERE `ID`=18397;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 틀렸다, 아드옌! 지금보다 정신이 맑았던 적은 없어.', `MaleText_loc4`='你错了，阿德因。我的想法从来没有这么清晰过。', `MaleText_loc5`='你錯了，艾德伊恩。我的心從未如此的堅定過。', `MaleText_loc7`='Te equivocas, Adyen. Mi mente nunca ha estado tan despejada.' WHERE `ID`=18398;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스승님...', `MaleText_loc4`='老师……', `MaleText_loc5`='老師...', `MaleText_loc7`='Profesora...' WHERE `ID`=18399;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='소크레타르, 성스러운 빛은 잃어버린 아들이 돌아오기를 바라고 있다.', `FemaleText_loc4`='圣光想让它迷失的孩子回来，索克雷萨。', `FemaleText_loc5`='聖光要討回迷失的子民，索奎薩爾。', `FemaleText_loc7`='La Luz quiere recuperar a su hijo perdido, Socrethar.' WHERE `ID`=18400;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그 대신 나를 데려가라. 카일란을 네 사악한 손아귀에서 풀어준다면 넌 알도르 대여사제인 나, 이샤나를 포로로 얻으리라.', `FemaleText_loc4`='我愿以我自己作为交换。如果你把凯兰恩从你的黑暗枷锁中释放的话，你会得到奥尔多的高阶女祭司伊沙娜作为你的囚犯。', `FemaleText_loc5`='我願將自己作為人質交換。如果你將凱嵐從你的黑暗禁制釋放出來的話，你將擁有伊莎納，奧多爾的高階女祭司作為你的囚犯。', `FemaleText_loc7`='Me ofrezco a cambio. Tendrás a Ishanah, suma sacerdotisa de los Aldor, como prisionera, si liberas a Kaylaan de tu oscuro alcance.' WHERE `ID`=18401;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='늙고 어리석은 마녀 같으니... 너희 둘 다 차지할 수 있는데 내가 그럴 이유가 있나?', `MaleText_loc4`='你这个愚蠢的老巫婆……你们两个都是我的囊中之物，我为什么还要跟你做交易？', `MaleText_loc5`='你這愚蠢的老巫婆...當我能夠同時抓住你們兩個時，為什麼我還要那麼做呢?', `MaleText_loc7`='Vieja arpía estúpida... ¿Por qué iba a hacerlo cuando os puedo tener a ambos?' WHERE `ID`=18402;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='', `MaleText_loc4`='', `MaleText_loc5`='', `MaleText_loc7`='' WHERE `ID`=18403;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 내가 무슨 짓을 저지른 거지?', `MaleText_loc4`='不！我都做了些什么？', `MaleText_loc5`='不!我做了什麼?', `MaleText_loc7`='¡No! ¿Qué es lo que he hecho?' WHERE `ID`=18404;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성스러운 빛이여, 제게 힘을 주소서!', `MaleText_loc4`='圣光赐予我力量！', `MaleText_loc5`='聖光賦予我力量!', `MaleText_loc7`='¡Que la Luz me dé fuerza!' WHERE `ID`=18405;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제발! 이제 지겹구나. 내 손으로 너희를 모두 죽여야겠다.', `MaleText_loc4`='哦，天哪！这太令人作呕了，看来我不得不亲自把你们全部解决掉。', `MaleText_loc5`='噢，拜託!真令人噁心;看來我必須要親手殺死你們全部。', `MaleText_loc7`='¡Oh, por favor! Esto es asqueroso. Voy a tener que mataros a todos yo mismo.' WHERE `ID`=18406;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 개들을 처리해라, 카일란! 이제 너도 불타는 군단에서 한 자리 마련해야 하지 않겠느냐!', `MaleText_loc4`='干掉这些狗东西，凯兰恩！提升你在燃烧军团的地位吧！', `MaleText_loc5`='殺死這些狗，凱嵐!證明你對燃燒軍團的忠心!', `MaleText_loc7`='¡Mata a esos perros, Kaylaan! ¡Gánate tu puesto en la Legión Ardiente!' WHERE `ID`=18407;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 기다리는 거냐? 놈들을 끝장내. 네 증오를 불태워라!', `MaleText_loc4`='你在等什么？解决他们，年轻人。燃烧你的仇恨吧！', `MaleText_loc5`='你還在等什麼?結束他們，年輕人。燃燒你的憎恨吧!', `MaleText_loc7`='¿A qué esperas? Acaba con ellos, joven. ¡Deja que tu odio arda!' WHERE `ID`=18408;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 주인님...', `MaleText_loc4`='是……主人。', `MaleText_loc5`='是的...主人。', `MaleText_loc7`='Sí... maestro.' WHERE `ID`=18409;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 실패하지 않을 것입니다.', `MaleText_loc4`='我们不会失败的。', `MaleText_loc5`='我們絕對不會失敗。', `MaleText_loc7`='No fallaremos.', `FemaleText_loc1`='우리는 실패하지 않을 것입니다.', `FemaleText_loc4`='我们不会失败的。', `FemaleText_loc5`='我們絕對不會失敗。', `FemaleText_loc7`='No fallaremos.' WHERE `ID`=18410;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기가 어디입니까?', `MaleText_loc4`='这是什么地方？', `MaleText_loc5`='這是什麼地方?', `MaleText_loc7`='¿Qué es este lugar?', `FemaleText_loc1`='여기가 어디인가요?', `FemaleText_loc4`='这是什么地方？', `FemaleText_loc5`='這是什麼地方?', `FemaleText_loc7`='¿Qué es este lugar?' WHERE `ID`=18411;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='메디브는 어디에 있습니까?', `MaleText_loc4`='麦迪文在哪里？', `MaleText_loc5`='麥迪文在哪?', `MaleText_loc7`='¿Dónde está Medivh?', `FemaleText_loc1`='메디브는 어디에 있나요?', `FemaleText_loc4`='麦迪文在哪里？', `FemaleText_loc5`='麥迪文在哪?', `FemaleText_loc7`='¿Dónde está Medivh?' WHERE `ID`=18412;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탑에 어떻게 들어갈 수 있습니까?', `MaleText_loc4`='我该朝哪个方向走？', `MaleText_loc5`='你是如何操縱這個塔?', `MaleText_loc7`='¿Cómo me oriento por la torre?', `FemaleText_loc1`='탑에 어떻게 들어갈 수 있나요?', `FemaleText_loc4`='我该朝哪个方向走？', `FemaleText_loc5`='你是如何操縱這個塔?', `FemaleText_loc7`='¿Cómo me oriento por la torre?' WHERE `ID`=18413;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳은 카라잔의 탑으로 저의 주인이신 메디브 님의 거처입니다. 한낱 문지기에 불과한 제가 설명할 수 있는 것은 여기까지입니다.', `MaleText_loc4`='这里是卡拉赞之塔，我的主人麦迪文的住所。身为一个卑微的看门人，我没有其它的东西可以向你解释。', `MaleText_loc5`='這是卡拉贊高塔，同時也是我的主人，麥迪文的住宅。作為一名謙卑的看門人，主人的事情我從不敢過問。', `MaleText_loc7`='Esta es la torre de Karazhan y la residencia de mi maestro, Medivh. Como humilde portero, no te puedo explicar mucho más.' WHERE `ID`=18414;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='메디브와 관련된 모든 질문은 집사인 모로스 님께 물어보십시오. 저는 주인님께서 하시는 일에 대해 아는 게 거의 없습니다. 몇몇 귀족들이 연회장에서 모로스 님을 알현하고 있으니 궁금한 점이 있으면 가서 물어보십시오.', `MaleText_loc4`='所有关于麦迪文的事都应该直接去问这里的管家莫罗斯，我几乎完全不知道主人在干些什么。如果你想知道更多的事情的话，我想现在正有一些贵族在宴会厅里和莫罗斯会面。', `MaleText_loc5`='關於麥迪文的所有問題應該去問哨塔服務員，摩洛。小的對主人的事情所知有限。如果你希望更進一步詢問的話，我相信有幾名貴族目前正在宴會大廳與摩洛交談。', `MaleText_loc7`='Todas las preguntas sobre Medivh deberían dirigirse a Moroes, el administrador de la torre. Yo mismo sé muy poco sobre los asuntos del maestro. Creo que ahora mismo varios nobles intentan tener una audiencia con Moroes en la sala de banquetes, si deseas saber más.' WHERE `ID`=18415;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 현관문을 통해 손님께서는 세 방향 중 한 곳으로 탑에 들어갈 수 있습니다. 제 뒤쪽에 있는 계단을 따라가면 대무도회장이 나오는데 현재 손님들을 접대하고 있습니다. 아마 마구간이 있다는 걸 냄새로 아실 수 있을 것이며, 하인 숙소로 들어가는 입구는 이곳 현관문 옆에 있습니다.', `MaleText_loc4`='从门房这里，你可以向三个方向行进。我身后的楼梯通往会客间，客人们正在那里玩乐。我相信你已经闻到附近的马厩的味道，还有仆役宿舍的入口就在门房的大门旁边。', `MaleText_loc5`='從警衛站這裡，你可以選擇從3個方向之一前往。在我後面的樓梯通向華麗的跳舞大廳，那裡目前正在招待客人。我相信你也聞到了附近的獸欄，而通往佣人區的入口緊接著警衛站的大門。', `MaleText_loc7`='Desde aquí, la torre de entrada, puedes ir en tres direcciones. Las escaleras que hay tras de mí conducen al gran salón de baile, donde ahora mismo los invitados se entretienen. Estoy seguro de que hueles el establo, que está cerca, y la entrada a las Alcobas de los Sirvientes queda al lado de la puerta de la torre de entrada.' WHERE `ID`=18416;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천둥이가 누굽니까?', `MaleText_loc4`='谁是午夜？', `MaleText_loc5`='誰是午夜?', `MaleText_loc7`='¿Quién es Medianoche?', `FemaleText_loc1`='천둥이가 누군가요?', `FemaleText_loc4`='谁是午夜？', `FemaleText_loc5`='誰是午夜?', `FemaleText_loc7`='¿Quién es Medianoche?' WHERE `ID`=18417;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천둥이는 사냥꾼 어튜멘의 전용 말입니다. 제가 본 말 중에 가장 빠르고, 강하며, 교활합니다. 심지어 말 주인은 그보다 훨씬 성미가 고약하답니다! 모두 천둥이의 발굽에 차이거나 어튜멘에게 얻어맞지 않기 위해 그들과 거리를 둔답니다.', `MaleText_loc4`='午夜是猎手阿图门的私人坐骑。我从未见过一匹比它更快、更强壮或者更英勇的马了。而且它的骑士更是喜怒无常！每个人都和它保持一定距离，以免被午夜踢到头，或被阿图门揍一顿。', `MaleText_loc5`='午夜是獵人阿圖曼的個人坐騎。我從未看過一隻比它更迅速，更強壯，或者脾氣更暴躁的馬。而且騎乘她的主人更加的喜怒無常!所有人都與她盡量保持距離，免得頭上無端多了個午夜的蹄印，或者是被阿圖曼一陣毒打。', `MaleText_loc7`='Medianoche es la montura personal de Attumen el Montero. Nunca he visto una yegua más veloz, fuerte o malintencionada. ¡Y su jinete es aún más temperamental! Todo el mundo guarda sus distancias con ella, por miedo a una coz de Medianoche o un golpe de Attumen.' WHERE `ID`=18418;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='망할 거미들, 끊임없이 소리를 질러 대는 박쥐들, 그리고 그 저주받은 악마의 짐승들은 모두 하인 숙소에 살고 있어. 더는 안심하고 주변을 돌아다닐 수가 없단 말이지. 특히 큰 녀석들이 나오는 날에는 더욱 위험하오.', `MaleText_loc4`='该死的蜘蛛、不断尖叫的蝙蝠、还有那些被诅咒的恶魔野兽，它们占据了仆役宿舍。那里已经很不安全了，尤其是当那些大家伙们从黑暗中跳出来的时候。', `MaleText_loc5`='佣人區住著該死的蜘蛛、總是在尖嘯的蝙蝠和那些被詛咒的惡魔般的野獸。在該區走動已不再安全，特別是有大隻的怪物從潛藏處撲向你的時候。', `MaleText_loc7`='Las malditas arañas, los murciélagos, que chillan sin parar y esas malditas bestias demoníacas han tomado residencia en las Alcobas de los Sirvientes. Ya no es seguro pasearse, especialmente cuando los grandes salen de su escondite.' WHERE `ID`=18419;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 도와달라는 말입니까?', `MaleText_loc4`='帮你什么？', `MaleText_loc5`='幫助你應付什麼情況?', `MaleText_loc7`='¿Ayudarte con qué situación?', `FemaleText_loc1`='뭘 도와달라는 말입니까?', `FemaleText_loc4`='帮你什么？', `FemaleText_loc5`='幫助你應付什麼情況?', `FemaleText_loc7`='¿Ayudarte con qué situación?' WHERE `ID`=18420;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='큰 녀석들이라고요?', `MaleText_loc4`='大家伙？', `MaleText_loc5`='大隻的怪嗎?', `MaleText_loc7`='¿Los grandes?', `FemaleText_loc1`='큰 녀석들이라고요?', `FemaleText_loc4`='大家伙？', `FemaleText_loc5`='大隻的怪嗎?', `FemaleText_loc7`='¿Los grandes?' WHERE `ID`=18421;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇소, 그 녀석들을 직접 본 적은 없지만 가끔 멀리서 녀석들의 소리가 들리오. 안으로 들어가게 된다면 녀석들을 조심하시오.', `MaleText_loc4`='是的，我从未亲自见过它们，但有时候我可以从远处听到它们的声音。如果你想进去冒险的话，对它们要保持充分的警惕。', `MaleText_loc5`='對了，我從未親眼看過他們，但是有時候我會在遠方聽見他們的聲音。如果你在裡面冒險，睜大眼睛注意它們。', `MaleText_loc7`='Ah, sí, personalmente nunca los he visto, pero a veces los oigo de lejos. Ten cautela si te aventuras a entrar.' WHERE `ID`=18422;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신과 잡담할 시간이 없습니다. 사람들을 훈련시키고 탑을 감시해야 합니다.', `MaleText_loc4`='我没有时间来闲聊了。我有很多人需要训练，还有一座塔需要看管。', `MaleText_loc5`='我沒有時間陪你閒聊。我還要訓練一堆人，以及守護一座哨塔。', `MaleText_loc7`='No tengo tiempo para cháchara. Tengo hombres y mujeres a los que instruir y una torre que vigilar.' WHERE `ID`=18423;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, 여러분! 로데론 최고 악단의 공연을 감상하십시오. 주인님과 주인님의 손님들을 위해 공연을 하게 된 것을 대단한 영광으로 생각합니다. 자, 곧 공연이 시작된다고 하니 관람석에 자리를 잡아 주시기 바랍니다.', `MaleText_loc4`='你好！看这完美的乐器，真荣幸可以为主人和他的客人们演出。去观众那里找个座位，我听说表演很快就要开始了。', `MaleText_loc5`='你好!瞧這把羅德隆最好的樂器之一。能夠為主人和他的貴賓演奏是無上的光榮。在觀眾席找個位置坐，我聽說表演不久將開始。', `MaleText_loc7`='¡Saludos! Contempla uno de los instrumentos musicales más bellos de toda Lordaeron. Es un verdadero honor actuar para el maestro y todos sus invitados. Toma asiento entre el público, creo que la actuación va a dar comienzo pronto.' WHERE `ID`=18424;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훌륭합니다! 정말 대단하군요!! 진정 멋진 공연이었습니다! 혹시 소속된 공연단이 있으신가요?', `MaleText_loc4`='太棒了！不知名的艺人居然可以表演出这么精彩的一场演出。你有代理人了吗？', `MaleText_loc5`='真是太壯觀了!令人驚嘆!這麼棒的表演竟然來自一個不知名的表演者!你有經紀人嗎?', `MaleText_loc7`='¡Espléndido! ¡Maravilloso! ¡Una actuación tan excelente de $gun relativo desconocido:una relativa desconocida;! ¿Tienes agente, por casualidad?' WHERE `ID`=18425;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 연회는 무의미하오. 저 바보 귀족들은 결코 메디브를 만나지 못할 것이오. 그들은 진정 모르고 있는 걸까? 여기서 시간을 낭비하느니 가족들과 함께 어둠골에 있을 걸 그랬소이다.', `MaleText_loc4`='这个聚会毫无意义。那些愚蠢的贵族们永远都不可能看到麦迪文，他们不明白吗？我应该待在夜色镇，和我的家人在一起，而不是在这里浪费时间。', `MaleText_loc5`='這個派對是毫無意義的。那些愚蠢的貴族絕不會看到麥迪文的。他們看不出來嗎?我本應該與我的家人待在夜色鎮，而不是在這裡浪費我的時間。', `MaleText_loc7`='Esta fiesta no tiene sentido. Esos estúpidos nobles nunca llegarán a ver a Medivh. ¿Es que no lo ven? Debería haberme quedado en Villa Oscura con mi familia en lugar de perder el tiempo aquí.' WHERE `ID`=18426;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 근처... 어디인데... 확실합니다. 이 도서관 어딘가에 제가 찾는 정보가 있습니다...', `MaleText_loc4`='我知道……在这里……某个地方。在这图书馆的某个地方有我要找的知识……', `MaleText_loc5`='就在這裡...的某個地方...我知道的。在這座圖書館的某處有我正在尋找的知識...', `MaleText_loc7`='Está por aquí... en algún lugar... lo sé. En algún lugar de esta biblioteca está el conocimiento que estoy buscando...' WHERE `ID`=18427;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 탑은 완전히 미쳐서 돌아가고 있습니다. 여기는 도서관이 아니라 책으로 쌓은 거대한 건초더미입니다. 아마 바늘이나 찾을 수 있을는지 모르겠네요! 그건 그렇고, 제가 뭘 하고 있었죠?', `FemaleText_loc4`='这座塔完全陷入了疯狂。这不是个图书馆，只是个巨大的书堆，而我不觉得这里有我要找的东西！既然这样，我以前都在干什么？', `FemaleText_loc5`='這座塔簡直是完全建給瘋子住的地方。這不是一座圖書館，這是一座巨大的舊書攤，而我看這裡的書多到連針都插不進去!對了，我來這邊是要做什麼?', `FemaleText_loc7`='Esta torre es una auténtica locura. Esto no es una biblioteca, es un enorme pajar, ¡y ni siquiera creo que exista la aguja! Bueno, ¿qué estaba haciendo?' WHERE `ID`=18428;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 때문에 매우 중요한 일이 방해 받고 있으니 당장 떠나 주십시오. 이런, 어디까지 했지? 다시 처음부터 해야 하는 건가?', `MaleText_loc4`='你的出现打扰了这项重要的工作，请马上离开。我刚才进展到哪里了？', `MaleText_loc5`='你在這裡會影響我做一項重要的工作。請立刻離開。對了，我又做到哪了?', `MaleText_loc7`='Tu presencia aquí interfiere con un trabajo muy importante. Por favor, márchate de inmediato. ¿Por dónde iba?' WHERE `ID`=18429;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 새로운 고객을 만나기엔 정말 묘한 곳이로군요!', `MaleText_loc4`='啊，在这么个奇怪的地方居然也有潜在的顾客！', `MaleText_loc5`='啊，想不到在這麼奇怪的地方可以找到潛在的客戶!', `MaleText_loc7`='¡Ah, qué lugar tan extraño para buscar posibles clientes!' WHERE `ID`=18430;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 어떤 물건을 팝니까?', `MaleText_loc4`='你都卖些什么？', `MaleText_loc5`='你賣的是什麼貨物呢?', `MaleText_loc7`='¿Qué podrías estar vendiendo?', `FemaleText_loc1`='당신은 어떤 물건을 파나요?', `FemaleText_loc4`='你都卖些什么？', `FemaleText_loc5`='你賣的是什麼貨物呢?', `FemaleText_loc7`='¿Qué podrías estar vendiendo?' WHERE `ID`=18431;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 끝냅시다... 제가 장치를 운반하는 동안 절 엄호해 주십시오.', `MaleText_loc4`='我们开始吧……掩护我，我会运送包裹的。', `MaleText_loc5`='讓我們這樣做...請繼續掩護我，而我將達成目標。', `MaleText_loc7`='Hagamos esto... Tú cúbreme y yo entregaré el paquete.' WHERE `ID`=18432;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맙소사! 여길 좀 보십시오! 살라다르가 뭘 계획하고 있는지 상상이 되는군요. 어서 계속 갑시다.', `MaleText_loc4`='以卡雷什的第二个太阳之名，看这个地方！我只能认为萨哈达尔正在计划着什么。加油，我们继续。', `MaleText_loc5`='以凱瑞西第二個太陽之名，看這個地方!我只能猜想薩哈達爾的計畫。跟我來，讓我們繼續走。', `MaleText_loc7`='¡Por el segundo sol de K''aresh, mira este lugar! Puedo imaginar lo que trama Salaadin. Vamos, sigamos.' WHERE `ID`=18433;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 많은 공허의 폐기물과 물기를 보니 독성 수액괴물이 그리 멀지 않은 곳에 있는 것 같군요.', `MaleText_loc4`='这么多的虚空垃圾和漂浮物，不远的地方一定有什么可怕的东西。', `MaleText_loc5`='隨著這麼多的無用廢物以及臨陣脫逃者，有毒的虛無恐泥應該離我們不遠。', `MaleText_loc7`='Con tantos residuos y desechos de vacío, no puede estar lejos un horror de vacío tóxico.' WHERE `ID`=18434;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기 좀 보십시오! 살라다르의 수송관이로군요! 그자가 공허의 힘을 잘 관리하고 있군...', `MaleText_loc4`='看那边！萨哈达尔的管道！他一直吃得很不错嘛……', `MaleText_loc5`='看那裡，凡人!薩哈達爾的導管!他的補給良好...', `MaleText_loc7`='¡Mira allí, ser de carne! ¡Los conductos de Salaadin! Se mantiene bien alimentado...' WHERE `ID`=18435;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋습니다, 제가 이 장치를 설치하는 동안 절 엄호해 주십시오. 그리 오래 걸리지 않을 겁니다.', `MaleText_loc4`='好吧，在我放置这干扰器的时候好好保护我。这不会花费太长时间的。', `MaleText_loc5`='好吧，當我設置這個干擾器時保護我。應該不需要很長的時間。', `MaleText_loc7`='De acuerdo, protégeme mientras coloco este disruptor. No debería llevarme mucho tiempo.' WHERE `ID`=18436;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끝났습니다! 어서, 뒤로! 물러나십시오!', `MaleText_loc4`='完成了！后退！后退！', `MaleText_loc5`='完成!撤退!撤退!', `MaleText_loc7`='¡Hecho! ¡Cúbreme! ¡Cúbreme!' WHERE `ID`=18437;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들이 저한테 접근하지 못하게 해주십시오!', `MaleText_loc4`='让这些东西离我远点！', `MaleText_loc5`='別讓這些東西碰我!', `MaleText_loc7`='¡Aleja esas cosas de mí!' WHERE `ID`=18438;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공격받고 있습니다! 반복합니다, 공격받고 있습니다!', `MaleText_loc4`='我受到攻击！重复一遍，我受到攻击！', `MaleText_loc5`='我被攻擊了!我重複，我被攻擊了!', `MaleText_loc7`='¡Me están atacando! ¡Repito, me están atacando!' WHERE `ID`=18439;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새로운 일거리를 찾아야겠군요.', `MaleText_loc4`='我需要找到一条新的工作线路。', `MaleText_loc5`='我需要找到一條新的導管。', `MaleText_loc7`='Tengo que buscar un nuevo tipo de trabajo.' WHERE `ID`=18440;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수송관을 보호해라! 침입자들을 막아라!', `MaleText_loc4`='保护好那些管道！阻止入侵者！', `MaleText_loc5`='保護導管!制止那些入侵者!', `MaleText_loc7`='¡Proteged el conducto! ¡Detened a los intrusos!' WHERE `ID`=18441;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 제가 할 일은 끝난 것 같군요. 송수신기로 돌아가서 야미르의 홀로그램 영상에게 보고하도록 하십시오.', `MaleText_loc4`='我在这里的工作大约已经完成了。去发射器那里向阿米尔的影像报告吧。', `MaleText_loc5`='看起來我在這裡的工作已完成了。到傳送器跟阿密爾的完全影像回報。', `MaleText_loc7`='Parece que mi trabajo aquí ha terminado. Informa a la holo-imagen de Ameer en el transpondedor.' WHERE `ID`=18442;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='참견쟁이들아, 지옥에 떨어질 준비나 해라. 너희는 방금 신을 풀어준 것이다!', `MaleText_loc4`='准备粉身碎骨吧，爱管闲事的家伙。你们释放了一个神！', `MaleText_loc5`='準備消失在歷史之中吧，愛管閒事的人。你已經釋放了一個神!', `MaleText_loc7`='Preparaos para caer en la inconsciencia, entrometidos. ¡Habéis liberado a un dios!' WHERE `ID`=18443;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엘른악 샤크타!', `MaleText_loc4`='Elen-ak shaktha！', `MaleText_loc5`='(惡魔語)再來一次!', `MaleText_loc7`='¡Elen-ak shaktha!' WHERE `ID`=18444;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 해골들아 일어나 날 위해 전진하라!', `MaleText_loc4`='复活吧，我的士兵们！给我进攻！', `MaleText_loc5`='出來吧，我的士兵，在我的命令下前進!', `MaleText_loc7`='¡Alzaos, soldados, y desfilad para mí!' WHERE `ID`=18445;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희는 결국... 실패할 것이다.', `MaleText_loc4`='你终将面临……失败。', `MaleText_loc5`='你將會...一敗塗地。', `MaleText_loc7`='Al final... fracasarás.' WHERE `ID`=18446;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으... 내 생명력을... 주인님께.', `MaleText_loc4`='我的生命……属于主人。', `MaleText_loc5`='我的生命...奉獻給主人。', `MaleText_loc7`='Mi vida... por el maestro.' WHERE `ID`=18447;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님을 모실 수 있어서... 영광이었습니다.', `MaleText_loc4`='我很荣幸……为主人服务。', `MaleText_loc5`='服侍主人...我的榮幸。', `MaleText_loc7`='Un placer... servir al maestro.' WHERE `ID`=18448;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이로써 주인님의 적이 하나 줄었다!', `MaleText_loc4`='主人的敌人又少了一个！', `MaleText_loc5`='少了一個主人的敵人!', `MaleText_loc7`='¡Un enemigo del maestro menos!' WHERE `ID`=18449;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고양이 앞에 놓인 쥐새끼 꼴이로군!', `MaleText_loc4`='一群待宰的羔羊！', `MaleText_loc5`='待宰的羔羊!', `MaleText_loc7`='¡Corderos para la carnicería!' WHERE `ID`=18450;
