UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대마법사 바르고스의 지팡이를 잃어버렸습니다. 새로 하나 주실 수 있습니까?', `MaleText_loc4`='我把大法师瓦格斯的法杖弄丢了。你能重新给我一根吗？', `MaleText_loc5`='我已經遺失大法師瓦戈斯之杖。你能找回它嗎?', `MaleText_loc7`='He perdido el bastón del archimago Vargoth. ¿Puedes sustituirlo?', `FemaleText_loc1`='대마법사 바르고스의 지팡이를 잃어버렸습니다. 새로 하나 주실 수 있나요?', `FemaleText_loc4`='我把大法师瓦格斯的法杖弄丢了。你能重新给我一根吗？', `FemaleText_loc5`='我已經遺失大法師瓦戈斯之杖。你能找回它嗎?', `FemaleText_loc7`='He perdido el bastón del archimago Vargoth. ¿Puedes sustituirlo?' WHERE `ID`=18546;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사실을 감추고 왜곡하려는 이들이 있는 반면에 현자들은 진실을 밝혀낸다오.$B$B$n, 이 도서관의 목적은 현자를 배출하는 것이오.', `MaleText_loc4`='有些人寻求着谎言，而先知则带来了圣光的真理。$B$B这座图书馆存在的意义，就是让每个人都成为自己命运的先知。', `MaleText_loc5`='有些人的天性喜愛編織謊言與歪曲事實。另一方面，先知將真相攤在陽光之下。$B$B這座圖書館的宗旨，$n，就是使每一個人都能成為一名先知。', `MaleText_loc7`='Están aquellos que intentan mentir y tergiversar la realidad. Los videntes, por otra parte, llevan la verdad a la luz.$B$BEl fin de esta biblioteca, $n, es convertir a todo el mundo en profeta.' WHERE `ID`=18547;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에테리얼 중에서 어떤 이들은 살 그리고 살로 이루어진 존재들을 다루곤 하는데 그런 에테리얼들을 살덩이괴물 조련사라고 합니다.', `MaleText_loc4`='在虚灵中，一部分会员负责处理血肉兽。他们被称为驯兽者。', `MaleText_loc5`='在以太族中，某些成員特別喜歡處理肉塊和生物的血肉之軀。那些人被稱為血肉處理者。', `MaleText_loc7`='Entre los etéreos, hay quienes tratan con carne y con seres de carne; son conocidos como los tratantes de carne.' WHERE `ID`=18548;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 멋진 땅에서 무엇을 찾고 있소?', `MaleText_loc4`='你来这片美丽的土地寻找什么？', `MaleText_loc5`='你在我們美好的大地尋找什麼嗎?', `MaleText_loc7`='¿Buscas algo en nuestras bellas tierras?', `FemaleText_loc1`='우리의 멋진 땅에서 무엇을 찾고 있습니까?', `FemaleText_loc4`='你来这片美丽的土地寻找什么？', `FemaleText_loc5`='你在我們美好的大地尋找什麼嗎?', `FemaleText_loc7`='¿Buscas algo en nuestras bellas tierras?' WHERE `ID`=18549;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='창공의 조련사 글로밍은 실버문 근처의 마법학자의 관문 밖에서 용매를 돌보고 있소.', `MaleText_loc4`='葛拉米就站在银月城的魔导师之门外，她管理着龙鹰。', `MaleText_loc5`='女飛行師薄暮站在博學者之門的外邊靠近銀月城，照顧龍鷹。', `MaleText_loc7`='La maestra del cielo Anochecer está fuera de la Puerta Magister cerca de Lunargenta. Se ocupa de los dracohalcones.', `FemaleText_loc1`='창공의 조련사 글로밍은 실버문 근처의 마법학자의 관문 밖에서 용매를 돌보고 있습니다.', `FemaleText_loc4`='葛拉米就站在银月城的魔导师之门外，她管理着龙鹰。', `FemaleText_loc5`='女飛行師薄暮站在博學者之門的外邊靠近銀月城，照顧龍鷹。', `FemaleText_loc7`='La maestra del cielo Anochecer está fuera de la Puerta Magister cerca de Lunargenta. Se ocupa de los dracohalcones.' WHERE `ID`=18550;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='길드를 창설하려면 실버문 안에서 알아보는 게 좋을 거요.', `MaleText_loc4`='如果你想注册一个公会，我建议你去银月城里面打听打听。', `MaleText_loc5`='如果你想登記建立公會，我將建議你去銀月城內詢問。', `MaleText_loc7`='Si quieres registrar una hermandad, te sugiero que busques en Lunargenta.', `FemaleText_loc1`='길드를 창설하려면 실버문 안에서 알아보는 게 좋을 거요.', `FemaleText_loc4`='如果你想注册一个公会，我建议你去银月城里面打听打听。', `FemaleText_loc5`='如果你想登記建立公會，我將建議你去銀月城內詢問。', `FemaleText_loc7`='Si quieres registrar una hermandad, te sugiero que busques en Lunargenta.' WHERE `ID`=18551;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='매날개 광장의 남동쪽 모퉁이로 가면 델라니엘이 운영하는 좋은 여관이 있소. 따뜻한 음식과 숙성된 포도주, 그리고 포근한 침대... 이 정도면 충분하지 않겠소?', `MaleText_loc4`='德兰妮尔经营着她那个设在鹰翼广场东南角的旅店。美酒佳肴，还有柔软的床……夫复何求？', `MaleText_loc5`='德拉尼歐在獵鷹之翼廣場的東南角落妥善的經營她的旅館。美味的食物，香醇的美酒，柔軟的床...你還能找到更好的旅館嗎?', `MaleText_loc7`='La posada de Delaniel está en la esquina suroriental de la Plaza Alalcón. Buen vino, buena comida, camas limpias... ¿Qué más se puede pedir?', `FemaleText_loc1`='매날개 광장의 남동쪽 모퉁이로 가면 델라니엘이 운영하는 좋은 여관이 있소. 따뜻한 음식과 숙성된 포도주, 그리고 포근한 침대... 이 정도면 충분하지 않겠소?', `FemaleText_loc4`='德兰妮尔经营着她那个设在鹰翼广场东南角的旅店。美酒佳肴，还有柔软的床……夫复何求？', `FemaleText_loc5`='德拉尼歐在獵鷹之翼廣場的東南角落妥善的經營她的旅館。美味的食物，香醇的美酒，柔軟的床...你還能找到更好的旅館嗎?', `FemaleText_loc7`='La posada de Delaniel está en la esquina suroriental de la Plaza Alalcón. Buen vino, buena comida, camas limpias... ¿Qué más se puede pedir?' WHERE `ID`=18552;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 순찰자들은 자신들의 고된 짐을 스스로 풀어낼 능력이 없는 것 같더군. 야수를 맡길 곳을 찾고 있다면 매날개 광장의 여관 밖에 있는 아나토스가 도와드릴 것이오.', `MaleText_loc4`='有些猎人们似乎无法看管好他们自己的野兽。如果你必须找个地方把野兽暂时圈养起来，阿娜索丝可以帮忙。她就在鹰翼广场的旅馆外面工作。', `MaleText_loc5`='有些遊俠似乎無法應付心中野獸般的慾望操控著他們的意志。如果你只是想在城鎮內制止這種事情，安納斯會接手的。她在獵鷹之翼廣場的旅館外頭等著工作上門。', `MaleText_loc7`='Algunos forestales son incapaces de cuidar de su material. Lo mejor es dejarlo en algún sitio en la ciudad. Anathos se ocupa de esas cosas. Vive y trabaja en la Plaza Alalcón, al lado de la posada.', `FemaleText_loc1`='어떤 순찰자들은 자신들의 고된 짐을 스스로 풀어낼 능력이 없는 것 같더군. 야수를 맡길 곳을 찾고 있다면 매날개 광장의 여관 밖에 있는 아나토스가 도와드릴 겁니다.', `FemaleText_loc4`='有些猎人们似乎无法看管好他们自己的野兽。如果你必须找个地方把野兽暂时圈养起来，阿娜索丝可以帮忙。她就在鹰翼广场的旅馆外面工作。', `FemaleText_loc5`='有些遊俠似乎無法應付心中野獸般的慾望操控著他們的意志。如果你只是想在城鎮內制止這種事情，安納斯會接手的。她在獵鷹之翼廣場的旅館外頭等著工作上門。', `FemaleText_loc7`='Algunos forestales son incapaces de cuidar de su material. Lo mejor es dejarlo en algún sitio en la ciudad. Anathos se ocupa de esas cosas. Vive y trabaja en la Plaza Alalcón, al lado de la posada.' WHERE `ID`=18553;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드루이드의 길을 걷는 한 타우렌 여성이 실버문에 야영지를 차렸으니 그리로 가보시오. 지금도 그곳에서 분명히 풀을 뜯고 있을 거요.', `MaleText_loc4`='有个自称是德鲁伊的母牛在银月城内建立了一处小营地。她现在肯定正在啃我们的植物。', `MaleText_loc5`='聲稱是德魯伊的一名牛頭人女士已經在銀月谷內建立營地。當我們在講話時，無疑地她正在我們的農作物上放牧。', `MaleText_loc7`='Se ha instalado en Lunargenta una vaca que dice ser druida. Lo más probable es que en estos momentos esté paciendo en nuestros jardines.', `FemaleText_loc1`='드루이드의 길을 걷는 한 타우렌 여성이 실버문에 야영지를 차렸으니 그리로 가보시오. 지금도 그곳에서 분명히 풀을 뜯고 있을 거요.', `FemaleText_loc4`='有个自称是德鲁伊的母牛在银月城内建立了一处小营地。她现在肯定正在啃我们的植物。', `FemaleText_loc5`='聲稱是德魯伊的一名牛頭人女士已經在銀月谷內建立營地。當我們在講話時，無疑地她正在我們的農作物上放牧。', `FemaleText_loc7`='Se ha instalado en Lunargenta una vaca que dice ser druida. Lo más probable es que en estos momentos esté paciendo en nuestros jardines.' WHERE `ID`=18554;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사냥을 배우려는 순찰자들은 매날개 광장의 북동쪽 건물에 머물고 있는 사냥꾼 한노비아에게 교육을 받고 있으니 그리로 가보시오.', `MaleText_loc4`='猎人们都在听汉诺维亚的课，他是一个站在鹰翼广场东北方建筑里的远行者。', `MaleText_loc5`='那些遊俠接受汗諾雅的指導，汗諾雅是一位待在獵鷹之翼廣場東北大樓的遠行者。', `MaleText_loc7`='Hannovia se ocupa de adiestrar a los forestales. Se encuentra en el edificio nororiental de la Plaza Alalcón.', `FemaleText_loc1`='사냥을 배우려는 순찰자들은 매날개 광장의 북동쪽 건물에 머물고 있는 사냥꾼 한노비아에게 교육을 받고 있으니 그리로 가보시오.', `FemaleText_loc4`='猎人们都在听汉诺维亚的课，他是一个站在鹰翼广场东北方建筑里的远行者。', `FemaleText_loc5`='那些遊俠接受汗諾雅的指導，汗諾雅是一位待在獵鷹之翼廣場東北大樓的遠行者。', `FemaleText_loc7`='Hannovia se ocupa de adiestrar a los forestales. Se encuentra en el edificio nororiental de la Plaza Alalcón.' WHERE `ID`=18555;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갈리델이 매날개 광장에서 비전 마법을 가르치고 있소. 여관 2층으로 가면 그녀를 찾을 수 있습니다.', `MaleText_loc4`='加琳黛尔在鹰翼广场内传授奥术魔法之道，你可以在旅店二楼找到她。', `MaleText_loc5`='卡綠笛在獵鷹之翼廣場裡教導魔法的奧秘;你可以在旅館的二樓找到她。', `MaleText_loc7`='Garridel enseña las artes Arcanas en la Plaza Alalcón. Se encuentra en la segunda planta de la posada.', `FemaleText_loc1`='갈리델이 매날개 광장에서 비전 마법을 가르치고 있소. 여관 2층으로 가면 그녀를 찾을 수 있습니다.', `FemaleText_loc4`='加琳黛尔在鹰翼广场内传授奥术魔法之道，你可以在旅店二楼找到她。', `FemaleText_loc5`='卡綠笛在獵鷹之翼廣場裡教導魔法的奧秘;你可以在旅館的二樓找到她。', `FemaleText_loc7`='Garridel enseña las artes Arcanas en la Plaza Alalcón. Se encuentra en la segunda planta de la posada.' WHERE `ID`=18556;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고작 이 정도냐, 살라다르?', `MaleText_loc4`='这就是你的全部能耐了，萨哈达尔？', `MaleText_loc5`='這是你使盡吃奶的力氣才能造成的投擲傷害嗎，薩哈達爾??', `MaleText_loc7`='¿Esto es lo mejor que tienes para mí, Salhadaar?' WHERE `ID`=18557;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고통의 시간이 왔다!', `MaleText_loc4`='是时候让你尝尝痛苦的滋味了！', `MaleText_loc5`='痛苦的時間到了!', `MaleText_loc7`='¡Hora de sufrir!' WHERE `ID`=18558;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불쌍한 싸움꾼이 또 하나 있군...', `MaleText_loc4`='又一个令人同情的竞争者……', `MaleText_loc5`='另一個可憐的爭奪者...', `MaleText_loc7`='Otro rival lamentable...' WHERE `ID`=18559;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밖으로 내보내!', `MaleText_loc4`='发射！', `MaleText_loc5`='送它出去!', `MaleText_loc7`='¡Enviadlo fuera!' WHERE `ID`=18560;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자유연합을 위해! 죽어라, 이 더러운 에테리움!', `MaleText_loc4`='为了维序派而战！去死吧！肮脏的复仇军！', `MaleText_loc5`='為了護國者!去死吧，污穢的以太皇族!', `MaleText_loc7`='¡Por el Protectorado! ¡Muere, basura de El Etereum!' WHERE `ID`=18561;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙습니다, 친구여. 여기서 나갈 수 있게 도와주시겠습니까?', `MaleText_loc4`='谢谢你，朋友。你能帮我离开这里吗？', `MaleText_loc5`='朋友，感謝。你可以幫助我離開這裡嗎?', `MaleText_loc7`='Gracias, $gamigo:amiga;. ¿Me ayudarás a salir de aquí?' WHERE `ID`=18562;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='광장의 북동쪽 건물에서 혈기사 노엘렌느가 젊은 훈련병들을 기다리고 있으니 어서 가보십시오.', `MaleText_loc4`='血骑士诺尔蕾妮正在广场东北方的建筑里面等着年轻的新兵们。', `MaleText_loc5`='血騎士諾伊蘭妮在廣場東北大樓裡等待年輕的學員。', `MaleText_loc7`='La Caballero de sangre Noellene te espera en el edificio nororiental de la plaza.', `FemaleText_loc1`='광장의 북동쪽 건물에서 혈기사 노엘렌느가 젊은 훈련병들을 기다리고 있으니 어서 가보십시오.', `FemaleText_loc4`='血骑士诺尔蕾妮正在广场东北方的建筑里面等着年轻的新兵们。', `FemaleText_loc5`='血騎士諾伊蘭妮在廣場東北大樓裡等待年輕的學員。', `FemaleText_loc7`='La Caballero de sangre Noellene te espera en el edificio nororiental de la plaza.' WHERE `ID`=18563;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사제의 지식을 원한다면 포나리스를 찾아가십시오. 델라니엘의 여관 2층에서 다른 이들과 사제로서 소임을 다하고 있습니다.', `MaleText_loc4`='如果你在寻求牧师的知识，那么珀纳瑞斯就是你要找的人。他在德兰妮尔的旅店二楼。', `MaleText_loc5`='如果你追尋神職人員的知識，保娜莉絲是你的理想人選。他在德拉尼歐的旅館二樓與其他人共事。', `MaleText_loc7`='Si buscas la sabiduría de un sacerdote, habla con Ponaris. Está con los demás en la segunda planta de la posada de Delaniel.', `FemaleText_loc1`='사제의 지식을 원한다면 포나리스를 찾아가십시오. 델라니엘의 여관 2층에서 다른 이들과 사제로서 소임을 다하고 있습니다.', `FemaleText_loc4`='如果你在寻求牧师的知识，那么珀纳瑞斯就是你要找的人。他在德兰妮尔的旅店二楼。', `FemaleText_loc5`='如果你追尋神職人員的知識，保娜莉絲是你的理想人選。他在德拉尼歐的旅館二樓與其他人共事。', `FemaleText_loc7`='Si buscas la sabiduría de un sacerdote, habla con Ponaris. Está con los demás en la segunda planta de la posada de Delaniel.' WHERE `ID`=18564;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='매날개 광장의 북동쪽에 건물이 하나 있는데... 안에 탄나리아라고 소멸 솜씨가 기차게 뛰어난 여성 도적이 있습니다.', `MaleText_loc4`='在鹰翼广场的东北部有一座建筑……你可以在里面找到塔娜莉亚，一个很擅长躲藏的女人。', `MaleText_loc5`='在獵鷹之翼廣場的東北有一座建築物...在裡面，你可能會找到塔娜莉雅，一名擅長於隱匿蹤跡的女士。', `MaleText_loc7`='Hay un edificio al noreste de la Plaza Alalcón. En él, es muy probable que encuentres a Tannaria. Su especialidad es permanecer oculta.', `FemaleText_loc1`='매날개 광장의 북동쪽에 건물이 하나 있는데... 안에 탄나리아라고 소멸 솜씨가 기차게 뛰어난 여성 도적이 있습니다.', `FemaleText_loc4`='在鹰翼广场的东北部有一座建筑……你可以在里面找到塔娜莉亚，一个很擅长躲藏的女人。', `FemaleText_loc5`='在獵鷹之翼廣場的東北有一座建築物...在裡面，你可能會找到塔娜莉雅，一名擅長於隱匿蹤跡的女士。', `FemaleText_loc7`='Hay un edificio al noreste de la Plaza Alalcón. En él, es muy probable que encuentres a Tannaria. Su especialidad es permanecer oculta.' WHERE `ID`=18565;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자유연합 경비초소가 그리 멀지 않습니다, $n. 이쪽입니다!', `MaleText_loc4`='我们离维序派哨站不远了，$n。这边走！', `MaleText_loc5`='我們不可以離護國者哨站太遠，$n。朝這個方向!', `MaleText_loc7`='No estamos demasiado lejos de la Avanzada del Protectorado, $n. ¡Por aquí!' WHERE `ID`=18566;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사령관님! 이 친구가 절 구했습니다!', `MaleText_loc4`='长官！这个肉乎乎的人救了我！', `MaleText_loc5`='指揮官!這個人救了我!', `MaleText_loc7`='¡Comandante! ¡Este ser de carne me ha rescatado!' WHERE `ID`=18567;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 사령관 야미르에게 경례합니다.', `MaleText_loc4`='%s向指挥官阿米尔敬礼。', `MaleText_loc5`='%s向指揮官阿密爾敬禮。', `MaleText_loc7`='%s saluda al comandante Ameer.' WHERE `ID`=18568;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='매날개 광장의 여관 2층에 켈레오누스라는 악마 소환 전문가가 있습니다.', `MaleText_loc4`='塞罗努斯是召唤恶魔的专家。他居住在鹰翼广场旅店，就在二楼。', `MaleText_loc5`='塞隆娜絲是我們的本地居民，專精於召喚惡魔。他住在獵鷹之翼廣場的旅館二樓。', `MaleText_loc7`='Celoenus es nuestro experto residente en invocación de demonios. Está en la posada de la Plaza Alalcón, en la segunda planta.', `FemaleText_loc1`='매날개 광장의 여관 2층에 켈레오누스라는 악마 소환 전문가가 있습니다.', `FemaleText_loc4`='塞罗努斯是召唤恶魔的专家。他居住在鹰翼广场旅店，就在二楼。', `FemaleText_loc5`='塞隆娜絲是我們的本地居民，專精於召喚惡魔。他住在獵鷹之翼廣場的旅館二樓。', `FemaleText_loc7`='Celoenus es nuestro experto residente en invocación de demonios. Está en la posada de la Plaza Alalcón, en la segunda planta.' WHERE `ID`=18569;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연금술사를 하나 아는데 이름이 아마 셰이나스렌일 겁니다. 마지막으로 봤을 때는 살데릴의 안식처로 가고 있었는데 보나 마나 그 우스꽝스러운 파티에 갔겠죠.', `MaleText_loc4`='我认识一位本地的炼金师。森纳瑟林，应该是这个名字。当我最后一次看到他的时候，他正在前往萨瑟利尔庄园，毫无疑问，他是去参加一场可笑的聚会。', `MaleText_loc5`='我知道一名本地的鍊金師。雪納倫，我相信這是他的名字。上次我見到他的時候，他正前往薩瑟里的避風港，一定是去參加一個他那可笑的聚會。', `MaleText_loc7`='Conozco a un alquimista local. Creo que se llama Sheynathren. La última vez que lo vi, se dirigía al Refugio de Saltheril. Seguramente para unirse a esas ridículas fiestas.', `FemaleText_loc1`='연금술사를 하나 아는데 이름이 아마 셰이나스렌일 겁니다. 마지막으로 봤을 때는 살데릴의 안식처로 가고 있었는데 보나 마나 그 우스꽝스러운 파티에 갔겠죠.', `FemaleText_loc4`='我认识一位本地的炼金师。森纳瑟林，应该是这个名字。当我最后一次看到他的时候，他正在前往萨瑟利尔庄园，毫无疑问，他是去参加一场可笑的聚会。', `FemaleText_loc5`='我知道一名本地的鍊金師。雪納倫，我相信這是他的名字。上次我見到他的時候，他正前往薩瑟里的避風港，一定是去參加一個他那可笑的聚會。', `FemaleText_loc7`='Conozco a un alquimista local. Creo que se llama Sheynathren. La última vez que lo vi, se dirigía al Refugio de Saltheril. Seguramente para unirse a uno de esos ridículos grupos.' WHERE `ID`=18570;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='순찰대가 영원노래 숲 동쪽에 있는 야영지에 아라텔이라는 대장장이 한 명을 데리고 있지요. 그대를 도울 수 있을 겁니다.', `MaleText_loc4`='远行者们在他们永歌森林东部的居所留下了一位铁匠。阿拉瑟尔也许能帮到你。', `MaleText_loc5`='遠行者在永歌森林的東部的居所雇用了一名鐵匠。艾瑞塞爾能幫助你。', `MaleText_loc7`='Los Errantes tienen un herrero en su retiro al este de Canción Eterna. Arathel podrá ayudarte.', `FemaleText_loc1`='순찰대가 영원노래 숲 동쪽에 있는 야영지에 아라텔이라는 대장장이 한 명을 데리고 있지요. 그대를 도울 수 있을 겁니다.', `FemaleText_loc4`='远行者们在他们永歌森林东部的居所留下了一位铁匠。阿拉瑟尔也许能帮到你。', `FemaleText_loc5`='遠行者在永歌森林的東部的居所雇用了一名鐵匠。艾瑞塞爾能幫助你。', `FemaleText_loc7`='Los Errantes tienen un herrero en su retiro al este de Canción Eterna. Arathel podrá ayudarte.' WHERE `ID`=18571;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='델라니엘이 쿼렐레스트라라는 훌륭한 요리사를 데리고 있습니다. 그녀에게 요리를 배우는 게 좋을 겁니다. 매날개 광장 여관에 가면 찾을 수 있습니다.', `MaleText_loc4`='德兰妮尔一直提供着一种被称为奎尔雷斯塔什么的美食。如果你想从她那里学手艺的话，应该去鹰翼广场旅店找她。', `MaleText_loc5`='德拉尼歐聘請了一位名叫奎芮絲的美味廚師。你可以跟她學到最棒的烹調技術。當然，你可以在獵鷹之翼廣場旅店找到她。', `MaleText_loc7`='Delaniel ha contratado a una cocinera excelente. Se llama Quarelestra. Seguro que puedes aprender mucho de ella. Está en la posada de la Plaza de Alalcón, claro.', `FemaleText_loc1`='델라니엘이 쿼렐레스트라라는 훌륭한 요리사를 데리고 있습니다. 그녀에게 요리를 배우는 게 좋을 겁니다. 매날개 광장 여관에 가면 찾을 수 있습니다.', `FemaleText_loc4`='德兰妮尔一直提供着一种被称为奎尔雷斯塔什么的美食。如果你想从她那里学手艺的话，应该去鹰翼广场旅店找她。', `FemaleText_loc5`='德拉尼歐聘請了一位名叫奎芮絲的美味廚師。你可以跟她學到最棒的烹調技術。當然，你可以在獵鷹之翼廣場旅店找到她。', `FemaleText_loc7`='Delaniel ha contratado a una cocinera excelente. Se llama Quarelestra. Seguro que puedes aprender mucho de ella. Está en la posada de la Plaza de Alalcón, claro.' WHERE `ID`=18572;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법부여사 에레다니아를 찾는다면 멀리 갈 필요 없이 살데릴이 축하 파티를 여는 장소로 가십시오. 며칠 전에 초대장을 받았다고 자랑했으니까 분명 그곳으로 갔을 겁니다.', `MaleText_loc4`='如果你在找艾雷达妮娅的话，就应该去萨瑟利尔的庆典那里。她几天前收到了邀请。', `MaleText_loc5`='假如你在尋找附魔師艾瑞丹妮雅，別超過薩瑟里的小慶典。她數天前收到邀請。', `MaleText_loc7`='Si buscas a Eredania la encantadora, ve a la pequeña fiesta de Saltheril. Recibió su invitación hace unos días.', `FemaleText_loc1`='마법부여사 에레다니아를 찾는다면 멀리 갈 필요 없이 살데릴이 축하 파티를 여는 장소로 가십시오. 며칠 전에 초대장을 받았다고 자랑했으니까 분명 그곳으로 갔을 겁니다.', `FemaleText_loc4`='如果你在找艾雷达妮娅的话，就应该去萨瑟利尔的庆典那里。她几天前收到了邀请。', `FemaleText_loc5`='假如你在尋找附魔師艾瑞丹妮雅，別超過薩瑟里的小慶典。她數天前收到邀請。', `FemaleText_loc7`='Si buscas a Eredania la encantadora, ve a la pequeña fiesta de Saltheril. Recibió su invitación hace unos días.' WHERE `ID`=18573;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그처럼 위험하고 예측 불가능한 기술을 우리 숲에서 사용하면 불행한 결과를 가져올 겁니다. 실버문의 성벽은 돌풍을 견뎌낼 만큼 튼튼하니까 실버문 안으로 들어가서 알아보십시오.', `MaleText_loc4`='这么危险和不可预知的专业技能是不能在我们的森林里修习的。你可以去银月城，不管怎样，城墙还是足够承受住爆炸的。', `MaleText_loc5`='如此危險和無法預期的訓練在我們的原始樹林中實行的結果可能會帶來大災難。但是，你或許可以在銀月城試試看;它的城牆堅固得足以禁得起爆炸。', `MaleText_loc7`='Una profesión tan impredecible y peligrosa no puede desempeñarse en nuestros tranquilos bosques sin consecuencias desastrosas. Inténtalo en Lunargenta. Sus muros son lo suficientemente resistentes como para aguantar los impactos.', `FemaleText_loc1`='그처럼 위험하고 예측 불가능한 기술을 우리 숲에서 사용하면 불행한 결과를 가져올 겁니다. 실버문의 성벽은 돌풍을 견뎌낼 만큼 튼튼하니까 실버문 안으로 들어가서 알아보십시오.', `FemaleText_loc4`='这么危险和不可预知的专业技能是不能在我们的森林里修习的。你可以去银月城，不管怎样，城墙还是足够承受住爆炸的。', `FemaleText_loc5`='如此危險和無法預期的訓練在我們的原始樹林中實行的結果可能會帶來大災難。但是，你或許可以在銀月城試試看;它的城牆堅固得足以禁得起爆炸。', `FemaleText_loc7`='Una profesión tan impredecible y peligrosa no puede desempeñarse en nuestros tranquilos bosques sin consecuencias desastrosas. Inténtalo en Lunargenta. Sus muros son lo suficientemente resistentes como para aguantar los impactos.' WHERE `ID`=18574;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지극히 평범하고 세속적인 방법으로 상처를 치료하는 것을 좋아하는 이들을 위해 카나리아가 매날개 광장 여관에서 깨끗한 진료소를 운영하고 있으니 그리로 가보십시오.', `MaleText_loc4`='为了那些更喜欢用普通方法来治疗伤口的人，鹰翼广场旅店里的卡娜莉亚设立了一处整洁的急救站。', `MaleText_loc5`='對想要善用一般修復身軀方法的人，卡娜莉雅在獵鷹之翼廣場旅店內的一個小攤位維持生計。', `MaleText_loc7`='Para los que prefieran métodos más caseros de curar las heridas, Kanaria tiene un puesto en el interior de la posada de la Plaza Alalcón.', `FemaleText_loc1`='지극히 평범하고 세속적인 방법으로 상처를 치료하는 것을 좋아하는 이들을 위해 카나리아가 매날개 광장 여관에서 깨끗한 진료소를 운영하고 있으니 그리로 가보십시오.', `FemaleText_loc4`='为了那些更喜欢用普通方法来治疗伤口的人，鹰翼广场旅店里的卡娜莉亚设立了一处整洁的急救站。', `FemaleText_loc5`='對想要善用一般修復身軀方法的人，卡娜莉雅在獵鷹之翼廣場旅店內的一個小攤位維持生計。', `FemaleText_loc7`='Para los que prefieran métodos más caseros de curar las heridas, Kanaria tiene un puesto en el interior de la posada de la Plaza Alalcón.' WHERE `ID`=18575;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자극적이고, 축축하고, 푸드덕거리는 못생긴 물고기와 시간을 보내는 게 그대가 찾는 즐거움이라면... 이 도시에 낚시꾼 한 명이 있긴 합니다.', `MaleText_loc4`='如果你想以腥味、潮湿和乏味来打发这种好日子的话，我们伟大的城市里有个渔夫……', `MaleText_loc5`='在我們偉大的城市裡有一個漁夫...如果與刺激，潮濕的海水搏鬥是你最喜歡的生活方式。', `MaleText_loc7`='Hay un pescador en nuestra gran ciudad. Está bien si te gusta pasar la tarde con repugnantes cosas resbaladizas y húmedas.', `FemaleText_loc1`='자극적이고, 축축하고, 푸드덕거리는 못생긴 물고기와 시간을 보내는 게 그대가 찾는 즐거움이라면... 이 도시에 낚시꾼 한 명이 있긴 합니다.', `FemaleText_loc4`='如果你想以腥味、潮湿和乏味来打发这种好日子的话，我们伟大的城市里有个渔夫……', `FemaleText_loc5`='在我們偉大的城市裡有一個漁夫...如果與刺激，潮濕的海水搏鬥是你最喜歡的生活方式。', `FemaleText_loc7`='Hay un pescador en nuestra gran ciudad. Está bien si te gusta pasar la tarde con repugnantes cosas resbaladizas y húmedas.' WHERE `ID`=18576;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='식물학자 티니아렐보다 파티용 꽃을 잘 가꾸는 사람이 있을까요? 분명 살데릴에게 포도주를 대접받고 있을 테니 그리로 가보십시오.', `MaleText_loc4`='谁能比植物学家塔尼安雷尔更擅长布置晚会的鲜花布景？我相信萨瑟利尔男爵会用酒来报答他的。', `MaleText_loc5`='誰能比植物學家泰尼阿瑞歐更會照顧滿屋子的花?如果有這種人我想薩瑟里會請他喝酒。', `MaleText_loc7`='¿Quién mejor que el gran botánico Tyniarrel para los arreglos florales de una fiesta? Estoy seguro de que Saltheril se lo paga en vino.', `FemaleText_loc1`='식물학자 티니아렐보다 파티용 꽃을 잘 가꾸는 사람이 있을까요? 분명 살데릴에게 포도주를 대접받고 있을 테니 그리로 가보십시오.', `FemaleText_loc4`='谁能比植物学家塔尼安雷尔更擅长布置晚会的鲜花布景？我相信萨瑟利尔男爵会用酒来报答他的。', `FemaleText_loc5`='誰能比植物學家泰尼阿瑞歐更會照顧滿屋子的花?如果有這種人我想薩瑟里會請他喝酒。', `FemaleText_loc7`='¿Quién mejor que el gran botánico Tyniarrel para los arreglos florales de una fiesta? Estoy segura de que Saltheril se lo paga en vino.' WHERE `ID`=18577;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='...그들이 우리에게 가지 말라고 했지만... 우리는 갔습니다... 가지 말라고 했지만... 갔습니다...', `MaleText_loc4`='……他们告诉我们不要去……但我们还是去了……他们告诉我们不要去……但是我们还是去了……', `MaleText_loc5`='...他們叫我們不要去...但是最後我們還是去了...他們叫我們不要去...但是最後我們還是去了...', `MaleText_loc7`='Nos dijeron que no fuésemos..., pero fuimos de todas formas... Nos dijeron que no fuésemos..., pero fuimos de todas formas...', `FemaleText_loc1`='...그들이 우리에게 가지 말라고 했지만... 우리는 갔습니다... 가지 말라고 했지만... 갔습니다...', `FemaleText_loc4`='……他们告诉我们不要去……但我们还是去了……他们告诉我们不要去……但是我们还是去了……', `FemaleText_loc5`='...他們叫我們不要去...但是最後我們還是去了......他們叫我們不要去...但是最後我們還是去了...', `FemaleText_loc7`='Nos dijeron que no fuésemos..., pero fuimos de todas formas... Nos dijeron que no fuésemos..., pero fuimos de todas formas...' WHERE `ID`=18578;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야미르 님은 저 에테리움들이 무슨 일을 꾸미고 있나 걱정하실지도 모르지만 난 바로 디멘시우스라는 진정한 위험에 맞서는 일에 집중하고 있소.', `MaleText_loc4`='阿米尔可能在担心复仇军有所动作，但是我仍然把注意力集中在迪门修斯那里，它才是真正的危险。', `MaleText_loc5`='阿密爾可能擔心以太皇族帶來的威脅，但是我正專注在這裡的真正危險︰迪曼修斯。', `MaleText_loc7`='Ameer debe de estar preocupado por las actividades de El Etereum, pero yo debo concentrarme en la verdadera amenaza: Dimensius.' WHERE `ID`=18579;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='매날개 광장에 있는 델라니엘의 여관에 가면 우리의 전문 보석세공인인 알레이니아를 찾을 수 있습니다. 그녀가 수습생을 구하는 것 같았으니 그리로 가보시지요.', `MaleText_loc4`='珠宝加工训练师奥雷妮亚就居住在鹰翼广场那间德兰妮尔开设的旅店里。她或许正需要一名学徒。', `MaleText_loc5`='我們的居民珠寶設計師，阿蕾妮雅，可在獵鷹之翼廣場的德拉尼歐旅店裡找到。她可能正在尋找一個學徒。', `MaleText_loc7`='Nuestra joyera residente, Aleinia, está en el establecimiento de Delaniel en la Plaza Alalcón. Puede que busque aprendiz.', `FemaleText_loc1`='매날개 광장에 있는 델라니엘의 여관에 가면 우리의 전문 보석세공인인 알레이니아를 찾을 수 있습니다. 그녀가 수습생을 구하는 것 같았으니 그리로 가보시지요.', `FemaleText_loc4`='珠宝加工训练师奥雷妮亚就居住在鹰翼广场那间德兰妮尔开设的旅店里。她或许正需要一名学徒。', `FemaleText_loc5`='我們的居民珠寶設計師，阿蕾妮雅，可在獵鷹之翼廣場的德拉尼歐旅店裡找到。她可能正在尋找一個學徒。', `FemaleText_loc7`='Nuestra joyera residente, Aleinia, está en el establecimiento de Delaniel en la Plaza Alalcón. Puede que busque aprendiz.' WHERE `ID`=18580;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영원노래 숲에서 사시인이 완벽한 스라소니 가죽을 찾고 있으니 찾아가 보십시오. 마법학자의 관문 남서쪽에 마스레인과 함께 있습니다.', `MaleText_loc4`='萨瑟林在永歌森林找到的山猫皮很适合他的作品。你应该和他谈谈——他就站在魔导师之门西南的玛斯雷恩旁边。', `MaleText_loc5`='莎希恩發現藏在永歌森林的山貓對他的創作很有幫助。你可以去跟他交談 - 他跟瑪斯莉安正好站在博學者之門的西南方。', `MaleText_loc7`='Sathein cree que los pellejos de lince son perfectos para sus creaciones. Deberías hablar con él. Está con Mathreyn al suroeste de la Puerta Magister.', `FemaleText_loc1`='영원노래 숲에서 사시인이 완벽한 스라소니 가죽을 찾고 있으니 찾아가 보십시오. 마법학자의 관문 남서쪽에 마스레인과 함께 있습니다.', `FemaleText_loc4`='萨瑟林在永歌森林找到的山猫皮很适合他的作品。你应该和他谈谈——他就站在魔导师之门西南的玛斯雷恩旁边。', `FemaleText_loc5`='莎希恩發現藏在永歌森林的山貓對他的創作很有幫助。你可以去跟他交談 - 他跟瑪斯莉安正好站在博學者之門的西南方。', `FemaleText_loc7`='Sathein cree que los pellejos de lince son perfectos para sus creaciones. Deberías hablar con él. Está con Mathreyn al suroeste de la Puerta Magister.' WHERE `ID`=18581;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실버문으로 가면 광부들을 찾을 수 있습니다. 보나 마나 그 냄새 나는 용광로에서 광물을 녹이고 있을 겁니다.', `MaleText_loc4`='你可以在银月城内找到矿工，毫无疑问他们在熔炉附近。', `MaleText_loc5`='那些礦工可在銀月城找到，接近熔爐的地方，享受礦產帶給他們的利潤。', `MaleText_loc7`='Hay mineros en Lunargenta. Con toda seguridad, estarán cerca de las apestosas forjas en las que funden lo que encuentran.', `FemaleText_loc1`='실버문으로 가면 광부들을 찾을 수 있습니다. 보나 마나 그 냄새 나는 용광로에서 광물을 녹이고 있을 겁니다.', `FemaleText_loc4`='你可以在银月城内找到矿工，毫无疑问他们在熔炉附近。', `FemaleText_loc5`='那些礦工可在銀月城找到，接近熔爐的地方，享受礦產帶給他們的利潤。', `FemaleText_loc7`='Hay mineros en Lunargenta. Con toda seguridad, estarán cerca de las apestosas forjas en las que funden lo que encuentran.' WHERE `ID`=18582;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마스레인은 야만적인 무두질에 능숙하지요. 진정 그런 일을 원한다면 그가 어디에 있는지 말씀드리겠어요. 마법학자의 관문 남서쪽에서 사시인에게 가죽을 공급하고 있으니 그리로 가보십시오.', `MaleText_loc4`='如果你真能习惯的话，玛斯雷恩对野蛮的剥皮工作很在行。他在为萨瑟林提供皮料，你可以在魔导师之门的东南找到他们俩。', `MaleText_loc5`='瑪斯莉安擅長於剝皮的野蠻工作，如果那真的是你所追尋的。他供應莎希恩皮革;你可以在博學者之門的西南方找到他們倆。', `MaleText_loc7`='Mathreyn es competente en la técnica bárbara del desuello, si es lo que te interesa. Es el proveedor de Sathein. Los encontrarás a ambos al suroeste de la Puerta Magister.', `FemaleText_loc1`='마스레인은 야만적인 무두질에 능숙하지요. 진정 그런 일을 원한다면 그가 어디에 있는지 말씀드리겠어요. 마법학자의 관문 남서쪽에서 사시인에게 가죽을 공급하고 있으니 그리로 가보십시오.', `FemaleText_loc4`='如果你真能习惯的话，玛斯雷恩对野蛮的剥皮工作很在行。他在为萨瑟林提供皮料，你可以在魔导师之门的东南找到他们俩。', `FemaleText_loc5`='瑪斯莉安擅長於剝皮的野蠻工作，如果那真的是你所追尋的。他供應莎希恩皮革;你可以在博學者之門的西南方找到他們倆。', `FemaleText_loc7`='Mathreyn es competente en la técnica bárbara del desuello, si es lo que te interesa. Es el proveedor de Sathein. Los encontrarás a ambos al suroeste de la Puerta Magister.' WHERE `ID`=18583;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최근에 살데릴의 안식처에 훌륭한 재봉사가 한 명 왔습니다. 바늘과 실을 다루는 그녀의 솜씨는 최고이니 그녀를 찾아가 보십시오.', `MaleText_loc4`='最优秀的女裁缝最近去萨瑟利尔庄园了，她的针线技艺在那里更受赏识。', `MaleText_loc5`='好的女裁縫師最近以來都在薩瑟里的避風港忙碌;她使用針線的高超本領在那裡肯定被賞識。', `MaleText_loc7`='La buena costurera está muy ocupada últimamente en el Refugio de Saltheril. Su habilidad con la aguja y el hilo es muy apreciada allí.', `FemaleText_loc1`='최근에 살데릴의 안식처에 훌륭한 재봉사가 한 명 왔습니다. 바늘과 실을 다루는 그녀의 솜씨는 최고이니 그녀를 찾아가 보십시오.', `FemaleText_loc4`='最优秀的女裁缝最近去萨瑟利尔庄园了，她的针线技艺在那里更受赏识。', `FemaleText_loc5`='好的女裁縫師最近以來都在薩瑟里的避風港忙碌;她使用針線的高超本領在那裡肯定被賞識。', `FemaleText_loc7`='La buena costurera está muy ocupada últimamente en el Refugio de Saltheril. Su habilidad con la aguja y el hilo es muy apreciada allí.' WHERE `ID`=18584;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 원하는지 말씀해 보시오.', `MaleText_loc4`='你在找什么？说出来。', `MaleText_loc5`='你追尋什麼?大聲說。', `MaleText_loc7`='¿Qué buscas? Habla.', `FemaleText_loc1`='뭘 원하는지 말씀해 보시오.', `FemaleText_loc4`='你在找什么？说出来。', `FemaleText_loc5`='你追尋什麼?大聲說。', `FemaleText_loc7`='¿Qué buscas? Habla.' WHERE `ID`=18585;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 엘레크를 팔고 있습니까?', `MaleText_loc4`='哪种雷象是可以出售的？', `MaleText_loc5`='有哪些伊萊克是要賣的?', `MaleText_loc7`='¿Qué elekks están a la venta?', `FemaleText_loc1`='어떤 엘레크를 팔고 있습니까?', `FemaleText_loc4`='哪种雷象是可以出售的？', `FemaleText_loc5`='有哪些伊萊克是要賣的?', `FemaleText_loc7`='¿Qué elekks están a la venta?' WHERE `ID`=18586;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 멋진 전투를 벌였으나 산산조각이 납니다.', `MaleText_loc4`='在一场恶斗之后，%s化作了碎片。', `MaleText_loc5`='%s在戰鬥中用盡了力量，碎裂一地。', `MaleText_loc7`='El %s ha luchado por última vez y cae en pedazos.' WHERE `ID`=18587;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 시대, 다른 곳에서 태어났다면 나는 아마 애송이 취급을 받았을 겁니다. 하지만 이곳에서는 나루의 영광을 위해 목숨을 바칠 각오가 된 숙련된 전투병이지요.$B$B우리 중 수십 명이 아라 마나괴철로 안으로 들어갔습니다. 그리고 다른 이들은 모두 불타는 군단에게 당했지요.', `MaleText_loc4`='如果在其它的时间和地点，我肯定只会被当作一个新人。在这里，我已经是个有经验的老兵了，随时都准备好为纳鲁的荣耀而战。$B$B我们有十个人进入法力熔炉：艾拉，其他的人都死在了燃烧军团手下。', `MaleText_loc5`='在不同的時間和地點我可能只是一個沒經驗的小兵。但現在我是一位經驗豐富的戰士，為了那魯的榮譽而活，為了那魯的榮譽而死。$B$B我們之中的十位進入法力熔爐艾拉。其他人致力於對付燃燒軍團。', `MaleText_loc7`='En otro tiempo y en otro lugar habría sido considerado como un cachorro. Y aquí estoy ahora; un luchador con experiencia y listo para morir por la gloria de los naaru.$B$BDiez de entre nosotros llegaron a Forja de Maná Ara. Los demás cayeron ante la Legión.' WHERE `ID`=18588;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 변화하기 시작합니다...', `MaleText_loc4`='%s开始变形……', `MaleText_loc5`='%s開始變形...', `MaleText_loc7`='%s comienza su metamorfosis.' WHERE `ID`=18589;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 이제 소크레타르에게 맞설 시간이 왔습니다. 준비되셨나요?', `MaleText_loc4`='是时候面对索克雷萨了，$n。你准备好了吗？', `MaleText_loc5`='該是面對索奎薩爾的時候了，$n。準備好了嗎?', `MaleText_loc7`='Llegó el momento de enfrentarse a Socrethar, $n. ¿Estás $glisto:lista;?' WHERE `ID`=18590;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비됐습니다, 아드옌!', `MaleText_loc4`='我准备好了，阿德因。', `MaleText_loc5`='我準備好了，艾德伊恩。', `MaleText_loc7`='Estoy listo, Adyen.', `FemaleText_loc1`='준비됐어요, 아드옌!', `FemaleText_loc4`='我准备好了，阿德因。', `FemaleText_loc5`='我準備好了，艾德伊恩。', `FemaleText_loc7`='Estoy lista, Adyen.' WHERE `ID`=18591;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='점술가 길드에서 보내서 오셨소? 당신은 전혀 점술가처럼 보이지 않는데...', `MaleText_loc4`='是占星者派你来联系我的吗？你看上去一点也不像个占星者。', `MaleText_loc5`='占卜者派你與我聯繫嗎?你看起來根本不像占卜者。', `MaleText_loc7`='¿Te enviaron los Arúspices? Tú no pareces un Arúspice.' WHERE `ID`=18592;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='한가하게 잡담이나 하면서 낭비할 시간은 없으니 어서 말하도록. 포세이큰이 무시 못할 세력으로 성장하긴 했지만 주어진 날까지 할 일이 아주 많다. 이 거대한 도시는 그냥 돌아가는 게 아니란 말이다.$b$b원하는 게 무엇인가?', `FemaleText_loc4`='快点说，我没有时间浪费在闲聊上。被遗忘者已经变成了一股不可低估的力量，但是我们仍然有很多事需要去做。这座城市可不会自己运转起来。$B$B你想要什么？', `FemaleText_loc5`='有話快說;我沒有時間閒聊。被遺忘者已經發展成要被對付的一股力量，但是在剩下的一天中仍然有非常多要做的事。城市不會自行運作。$b$b你想要什麼?', `FemaleText_loc7`='Habla rápido. No tengo tiempo que perder en charlas. Los Renegados son ya una fuerza considerable, pero todavía hay demasiadas cosas por hacer. Esta ciudad no se gestiona sola.$B$B¿Qué quieres?' WHERE `ID`=18593;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='희망이 없구나... 내가 할 수 있는 일은 전부 다했건만...', `MaleText_loc4`='没有希望了……我尽了我的全力。', `MaleText_loc5`='沒希望了...我已經盡力。', `MaleText_loc7`='No hay esperanza... He hecho lo que he podido.' WHERE `ID`=18594;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실패했어. 성스러운 빛이 날 저버렸군.', `MaleText_loc4`='我失败了。圣光抛弃了我。', `MaleText_loc5`='我已經失敗了。聖光已經拋棄了我。', `MaleText_loc7`='He fracasado. La Luz me ha abandonado.' WHERE `ID`=18595;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 스팀휘들 결투 대회에서 싸울 자격이 없네. 귀찮게 하지 말라고.', `MaleText_loc4`='你还未达到在热砂港搏击会中出场的条件，$c。不要浪费我的时间。', `MaleText_loc5`='你還不夠資格在熱砂戰鬥同盟中戰鬥，$c。不要浪費我的時間。', `MaleText_loc7`='No tienes lo que hace falta para luchar en el Círculo de Lucha Bonvapor, $c. Deja de hacerme perder el tiempo.', `FemaleText_loc1`='자네는 스팀휘들 결투 대회에서 싸울 자격이 없네. 귀찮게 하지 말라고.', `FemaleText_loc4`='你还未达到在热砂港搏击会中出场的条件，$c。不要浪费我的时间。', `FemaleText_loc5`='你還不夠資格在熱砂戰鬥同盟中戰鬥，$c。不要浪費我的時間。', `FemaleText_loc7`='No tienes lo que hace falta para luchar en el Círculo de Lucha Bonvapor, $c. Deja de hacerme perder el tiempo.' WHERE `ID`=18596;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아! 자네는 스팀휘들 결투 대회가 열리는 투기장에서 싸울 준비가 된 것 같군그래.', `MaleText_loc4`='好吧，$c。你觉得你符合参加热砂港搏击会的竞技场参与条件了吗？', `MaleText_loc5`='好吧，$c。你認為你的實力足夠參加熱砂戰鬥同盟競技場的戰鬥嗎?', `MaleText_loc7`='Está bien, $c. ¿Crees que tienes lo que hay que tener para entrar en las arenas del Círculo de Lucha Bonvapor?', `FemaleText_loc1`='좋아! 자네는 스팀휘들 결투 대회가 열리는 투기장에서 싸울 준비가 된 것 같군그래.', `FemaleText_loc4`='好吧，$c。你觉得你符合参加热砂港搏击会的竞技场参与条件了吗？', `FemaleText_loc5`='好吧，$c。你認為你的實力足夠參加熱砂戰鬥同盟競技場的戰鬥嗎?', `FemaleText_loc7`='Está bien, $c. ¿Crees que tienes lo que hay que tener para entrar en las arenas del Círculo de Lucha Bonvapor?' WHERE `ID`=18597;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='투기장 결투에 참여하고 싶습니다.', `MaleText_loc4`='我想要在竞技场一展身手。', `MaleText_loc5`='我想在競技場戰鬥。', `MaleText_loc7`='Quiero luchar en la arena.', `FemaleText_loc1`='투기장 결투에 참여하고 싶습니다.', `FemaleText_loc4`='我想要在竞技场一展身手。', `FemaleText_loc5`='我想在競技場戰鬥。', `FemaleText_loc7`='Quiero luchar en la arena.' WHERE `ID`=18598;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='희미한 메아리가 들립니다...', `MaleText_loc4`='你听到了微弱的回声……', `MaleText_loc5`='你聽到微弱的回音...', `MaleText_loc7`='Oyes un eco débil...' WHERE `ID`=18599;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='금속으로 돌을 가는 시끄러운 소리가 들립니다...', `MaleText_loc4`='你听到了金属摩擦石头的噪音……', `MaleText_loc5`='你聽到金屬磨在石頭上的響亮隆隆聲...', `MaleText_loc7`='Oyes un ruido estridente de metal rozando contra piedra...' WHERE `ID`=18600;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나가의 물 보일러가 작동하고 아래서는 죽어가는 광포어의 소리가 들립니다.', `MaleText_loc4`='纳迦的开水锅炉被激活了，随后从下面传来撕心裂肺的叫声。', `MaleText_loc5`='納迦的滾水鍋爐啟動，而下方傳來死前痛苦狂吼的聲音。', `MaleText_loc7`='El hervidor de agua naga se activa y puedes oír los gemidos de peces furia muriendo.' WHERE `ID`=18601;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='괘씸한 놈, 그 행동은 파멸을 앞당길 뿐이다! 때가 되면 모두 멸망할지니!', `MaleText_loc4`='你这样做，无非是让不可避免的末日来得更快而已。那时，这一切都将被吞噬！', `MaleText_loc5`='你只是在加速不可避免的滅亡。到時，所有事物都將被毀滅!', `MaleText_loc7`='Solo aceleras lo inevitable. Al final, ¡todo será devorado!' WHERE `ID`=18602;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투의 전당에 있는 전투 상황실 근처에 가면 투기장 사무관을 찾을 수 있을 겁니다.', `MaleText_loc4`='你可以在武器大厅的战略沙图周围找到战场军官们。', `MaleText_loc5`='你將在武器大廳裡的戰議桌周遭找到戰場軍官。', `MaleText_loc7`='Los maestros de batalla están cerca de la mesa de guerra de la Sala de Armas.', `FemaleText_loc1`='전투의 전당에 있는 전투 상황실 근처에 가면 투기장 사무관을 찾을 수 있을 겁니다.', `FemaleText_loc4`='你可以在武器大厅的战略沙图周围找到战场军官们。', `FemaleText_loc5`='你將在武器大廳裡的戰議桌周遭找到戰場軍官。', `FemaleText_loc7`='Los maestros de batalla están cerca de la mesa de guerra de la Sala de Armas.' WHERE `ID`=18603;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전사의 정원에 가면 모여 있는 전투모병관들을 찾을 수 있을 겁니다.', `FemaleText_loc4`='战场军官都聚集在战士区。', `FemaleText_loc5`='你可以在戰士區找到戰場軍官。', `FemaleText_loc7`='Los maestros de batalla están reunidos en el Bancal del Guerrero.' WHERE `ID`=18604;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드 왕궁의 전략 회의실에 가면 전투모병관을 찾을 수 있을 겁니다.', `MaleText_loc4`='你可以在暴风要塞找到战场军官。', `MaleText_loc5`='你可以在暴風要塞的戰爭室找到戰場軍官。', `MaleText_loc7`='Los maestros de batalla están en la sala de guerra del Castillo de Ventormenta.', `FemaleText_loc1`='스톰윈드 왕궁의 전략 회의실에 가면 전투모병관을 찾을 수 있을 겁니다.', `FemaleText_loc4`='你可以在暴风要塞找到战场军官。', `FemaleText_loc5`='你可以在暴風要塞的戰爭室找到戰場軍官。', `FemaleText_loc7`='Los maestros de batalla están en la sala de guerra del Castillo de Ventormenta.' WHERE `ID`=18605;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 약해진 것 같습니다.', `MaleText_loc4`='%s看上去变弱了。', `MaleText_loc5`='%s好像衰弱了。', `MaleText_loc7`='%s parece debilitado.' WHERE `ID`=18606;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수렵의 봉우리로 가면 투기장 사무관을 찾을 수 있을 겁니다.', `MaleText_loc4`='去猎人高地吧，你可以在那里找到战场军官。', `MaleText_loc5`='去獵人高地。你將在那裡找到戰場軍官。', `MaleText_loc7`='Ve al alto de los cazadores. Allí encontrarás a los maestros de batalla.', `FemaleText_loc1`='수렵의 봉우리로 가면 투기장 사무관을 찾을 수 있을 겁니다.', `FemaleText_loc4`='去猎人高地吧，你可以在那里找到战场军官。', `FemaleText_loc5`='去獵人高地。你將在那裡找到戰場軍官。', `FemaleText_loc7`='Ve al alto de los cazadores. Allí encontrarás a los maestros de batalla.' WHERE `ID`=18607;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명예의 골짜기에 있는 용사의 전당에 가면 투기장 사무관들을 찾을 수 있을 걸세.', `MaleText_loc4`='战场军官就在荣誉谷的勇士大厅里。', `MaleText_loc5`='你將在榮譽谷的勇者大廳裡面找到戰場軍官。', `MaleText_loc7`='Encontrarás a los maestros de batalla en el Bastión de los Valientes en el Valle del Honor.', `FemaleText_loc1`='명예의 골짜기에 있는 용사의 전당에 가면 투기장 사무관들을 찾을 수 있을 걸세.', `FemaleText_loc4`='战场军官就在荣誉谷的勇士大厅里。', `FemaleText_loc5`='你將在榮譽谷的勇者大廳裡面找到戰場軍官。', `FemaleText_loc7`='Encontrarás a los maestros de batalla en el Bastión de los Valientes en el Valle del Honor.' WHERE `ID`=18608;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왕실로 가라. 그들 왕실 주위 마법진에 있다.', `MaleText_loc4`='你可以去皇家区。他们都在那里，在房间里面站成一个圆圈。', `MaleText_loc5`='前往皇家區。他們全部在那裡，在房間裡圍成一圈。', `MaleText_loc7`='Ve al Barrio Real. Todos allí. En círculo en la sala.', `FemaleText_loc1`='왕실로 가라. 그들 왕실 주위 마법진에 있다.', `FemaleText_loc4`='你可以去皇家区。他们都在那里，在房间里面站成一个圆圈。', `FemaleText_loc5`='前往皇家區。他們全部在那裡，在房間裡圍成一圈。', `FemaleText_loc7`='Ve al Barrio Real. Todos allí. En círculo en la sala.' WHERE `ID`=18609;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='투기장 사무관', `MaleText_loc4`='竞技场管理员', `MaleText_loc5`='競技場戰場軍官', `MaleText_loc7`='Maestro de batalla de arena', `FemaleText_loc1`='투기장 사무관', `FemaleText_loc4`='竞技场管理员', `FemaleText_loc5`='競技場戰場軍官', `FemaleText_loc7`='Maestro de batalla de arena' WHERE `ID`=18610;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나루의 보좌에 있는 간병소에 가면 그를 찾을 수 있을 겁니다. 성스러운 빛이 함께하기를.', `MaleText_loc4`='你可以在纳鲁之座的医护中心找到他。愿圣光与你同在。', `MaleText_loc5`='你將在那魯之座的照顧者中心找到他。願聖光與你同在。', `MaleText_loc7`='Lo encontrarás en el centro de cuidadores, en el Trono de los Naaru. Que la Luz sea contigo.', `FemaleText_loc1`='나루의 보좌에 있는 간병소에 가면 그를 찾을 수 있을 겁니다. 성스러운 빛이 함께하기를.', `FemaleText_loc4`='你可以在纳鲁之座的医护中心找到他。愿圣光与你同在。', `FemaleText_loc5`='你將在那魯之座的照顧者中心找到他。願聖光與你同在。', `FemaleText_loc7`='Lo encontrarás en el centro de cuidadores, en el Trono de los Naaru. Que la Luz sea contigo.' WHERE `ID`=18611;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='머핀 있습니다!', `MaleText_loc4`='来看看我的松饼吧！', `MaleText_loc5`='噢耶，我得到鬆餅了!', `MaleText_loc7`='¡Sí, tengo bollos!' WHERE `ID`=18612;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='머핀 구경 좀 할 수 있을까요?!', `MaleText_loc4`='好吧，松饼人，给我看看你的松饼！', `MaleText_loc5`='好的，鬆餅人，讓我看看你的鬆餅!', `MaleText_loc7`='Está bien, bollero, ¡enséñame tus bollos!', `FemaleText_loc1`='머핀 구경 좀 할 수 있나요?!', `FemaleText_loc4`='好吧，松饼人，给我看看你的松饼！', `FemaleText_loc5`='好的，鬆餅人，讓我看看你的鬆餅!', `FemaleText_loc7`='Está bien, bollero, ¡enséñame tus bollos!' WHERE `ID`=18613;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방금 구운 머핀 있습니다! 이리 와서 머핀 하나 사세요!', `MaleText_loc4`='新鲜的松饼！到这里来拿新鲜的松饼吧！', `MaleText_loc5`='新鮮的鬆餅!來在這裡得到你新鮮的鬆餅!', `MaleText_loc7`='¡Bollos frescos! ¡Tengo bollos frescos!' WHERE `ID`=18614;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여러분, 안녕? 오늘도 행복한 하루 되길 바라요. 이리 와서 달콤한 머핀 맛 좀 보세요!', `MaleText_loc4`='你好。我希望你能渡过一个童话般的日子。来买我的松饼吧！', `MaleText_loc5`='你好嗎?希望你今天過的很棒。來買一個我的鬆餅!', `MaleText_loc7`='¿Qué tal? Espero que tengas un día excelente. ¡Cómprame algún bollo!' WHERE `ID`=18615;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방금 나온 따끈따끈한 머핀이 왔어요. 이리 오세요!', `MaleText_loc4`='我有松饼。到我这里来！', `MaleText_loc5`='我這兒有鬆餅。快過來!', `MaleText_loc7`='Tengo bollos deliciosos. ¡Ven a por uno!' WHERE `ID`=18616;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 네. 저는 머핀 장수랍니다. 제가 왜 머핀 장수냐고요? 그야 머핀을 파니까 머핀 장수죠!', `MaleText_loc4`='没错，我是松饼人。你知道为什么吗？因为我卖松饼啊！', `MaleText_loc5`='耶，耶，我是鬆餅人。你知道為什麼嗎?因為我賣鬆餅，那就是為什麼!', `MaleText_loc7`='Sí, sí, yo soy el bollero. ¿Y sabes por qué? ¡Porque vendo bollos! ¡Por eso!' WHERE `ID`=18617;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 무엇과도 비교할 수 없는 최고의 머핀이 왔어요!', `MaleText_loc4`='没有什么食品能和我这些华丽的松饼相比！', `MaleText_loc5`='我的鬆餅是最棒的!', `MaleText_loc7`='¡No hay nada como mis bollos recién hechos!' WHERE `ID`=18618;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갓 구워내 뜨끈한 머핀이 왔어요. 샤트라스 어디에서도 이 가격에 이런 머핀은 못 구합니다.', `MaleText_loc4`='趁热赶紧买吧，沙塔斯城里面绝对找不到比我这里价格更公道的松饼了！', `MaleText_loc5`='趕快趁熱、趁新鮮吃下去。在撒塔斯，你找不到價格這麼好的鬆餅。', `MaleText_loc7`='Llévatelos mientras están calientes. No encontrarás bollos a mejor precio en todo Shattrath.' WHERE `ID`=18619;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 어떤 것과도 비교할 수 없는 최고의 머핀이 왔어요.', `MaleText_loc4`='喝一口啤酒，吃一口我的松饼，真是人生的一大享受啊。', `MaleText_loc5`='沒有什麼比用一杯滿滿的啤酒把我可口的鬆餅沖下肚裡還要好。', `MaleText_loc7`='Lo que mejor va con mis deliciosos bollos es una buena jarra llena.' WHERE `ID`=18620;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 정말 최고의 머핀이 왔어요! 이리 와서 신선한 머핀 사세요!', `MaleText_loc4`='哈哈，多么美味啊。卖松饼啦！来这里买新鲜的松饼吧！', `MaleText_loc5`='耶，正中紅心。賣鬆餅!快過來買你剛出爐的鬆餅喔!', `MaleText_loc7`='¡Sí, eso es! ¡Vendo bollos! ¡Bollos recién hechos aquí!' WHERE `ID`=18621;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='불타는 군단에서는 네놈들이 더 빨리 일하기를 원한다! 더 빨리 움직이란 말이다, 이 벌레들아!', `FemaleText_loc4`='燃烧军团命令你们工作得快点！再快点，虫子！', `FemaleText_loc5`='燃燒軍團要你更迅速地工作!快一點，懶蟲!', `FemaleText_loc7`='¡La Legión necesita que trabajéis más rápido! ¡Más rápido gusanos!' WHERE `ID`=18622;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='조만간 불타는 군단의 모든 병력이 도착할 것이다.', `FemaleText_loc4`='燃烧军团即将驾临。', `FemaleText_loc5`='燃燒軍團的主力部隊不久將到達。', `FemaleText_loc7`='Pronto la Legión Ardiente revelará toda su fuerza.' WHERE `ID`=18623;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='멈추지 마라! 영광의 시간이 머지않았다!', `FemaleText_loc4`='不要停！我们的荣光就要来临了！', `FemaleText_loc5`='不要停!我們的光榮時刻正靠近中!', `FemaleText_loc7`='¡No paréis! ¡Pronto llegará el momento de la gloria!' WHERE `ID`=18624;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='실패한다면 영원히 고통 속에서 헤매게 될 것이다!', `FemaleText_loc4`='失败者会尝尽人间的痛苦！', `FemaleText_loc5`='如果你失敗了，你將永久受苦!', `FemaleText_loc7`='¡Sufrirás eternamente si fracasas!' WHERE `ID`=18625;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 알겠습니다!', `MaleText_loc4`='就像你说的那样！', `MaleText_loc5`='遵命!', `MaleText_loc7`='¡Como quieras!' WHERE `ID`=18626;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기, 여행자님! 이리 오셔서 따끈따끈한 머핀 좀 맛보세요!', `MaleText_loc4`='嗨！过来尝尝我的热松饼！', `MaleText_loc5`='喂你!過來這裡，嚐嚐我的熱鬆餅!', `MaleText_loc7`='¡Eh, tú! Ven aquí' WHERE `ID`=18627;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 불타는 군단에게 봉사하기 위해 존재합니다!', `MaleText_loc4`='我生来就是为大家效劳的！', `MaleText_loc5`='我生而為您服務!', `MaleText_loc7`='Vivo para servir.' WHERE `ID`=18628;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분부하신 대로 합지요.', `MaleText_loc4`='生命不息，交谈不息。', `MaleText_loc5`='總是愛說教。', `MaleText_loc7`='Siempre con el discurso.' WHERE `ID`=18629;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지옥절단기를 더 만들게 당장 부품을 가져와!', `MaleText_loc4`='去把另一个魔能机甲的部件找来给我，快去！', `MaleText_loc5`='給我另一個惡魔劫奪者的零件，現在!', `MaleText_loc7`='¡Necesito las piezas de otro atracador vil ahora!' WHERE `ID`=18630;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지옥절단기를 다시 만들 부품은 충분하다. 더 강하고, 더 빠르고, 더 좋은 지옥절단기 말이다!', `MaleText_loc4`='重铸所需的部件已经足够了，我们的目标是：更高、更快、更强！', `MaleText_loc5`='有足夠的零件重新製造它。更強大，更快，更好!', `MaleText_loc7`='Hay piezas suficientes para reconstruirlo. ¡Será más fuerte, más rápido y mejor!' WHERE `ID`=18631;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='껍데기는 상관없으니 내부 부품을 가져와!', `MaleText_loc4`='我不要外壳，我要内部的零件！', `MaleText_loc5`='我不管你如何破壞它的外殼，我只要內部的零件!', `MaleText_loc7`='No me interesa la carcasa. ¡Necesito las piezas internas!' WHERE `ID`=18632;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 자유연합의 공격대장 세이드라고 합니다. 옆에 서 있는 병사들은 저의 복수자들입니다. 우리는 공허의 수송관을 파괴한 육체의 소유자의 명령을 기다리고 있습니다. 그의 명령에 따라 우리는 디멘시우스의 둥지로 진군하여 최종 공격 명령을 기다릴 것입니다!$B$B이 시간이 오기까지 아주 오랜 시간이 흘렀습니다만... 곧 공허의 군주는 우리의 단합된 힘에 맞서야 할 것입니다!', `MaleText_loc4`='你好，我是维序派的萨义德上尉，我身旁的这些士兵是我的复仇者部队。我们等待着摧毁虚空管道的那个肉人的命令。用那个肉人的话来说，我们要赶到迪门修斯的巢穴外，等待最后进攻的命令！$B$B等了这么多年……虚空领主很快就会面对我们的夹击了！', `MaleText_loc5`='凡人，我是護國者的瑟翼德上尉，我身邊的這些士兵就是我的復仇者。我們等待來自破壞虛無導管之凡人的命令。依該名凡人的命令，我們將前進到迪曼修斯的窩穴，並且等待最後的命令做出最後一擊!$B$B已經等太久了...虛無領主將很快面對我們結合的力量!', `MaleText_loc7`='Ser de carne, soy el capitán Saeed del protectorado y estos soldados que están a mi lado son mis vengadores. Esperamos órdenes del ser de carne que destruyó el conducto del vacío. Cuando él lo ordene, nos adentraremos en la guarida de Dimensius y esperaremos para el ataque final.$B$BHa pasado demasiado tiempo... ¡El señor del vacío probará nuestras fuerzas combinadas!' WHERE `ID`=18633;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세이드는 현재 교전 중이거나 교전 명령을 기다리는 중입니다. 동쪽으로 가서 세이드가 당신을 도울 준비가 되었는지 확인해 보십시오. 만약 그가 없다면 또 다른 전투가 진행 중인 겁니다. 그렇다면, 그가 올 때까지 기다렸다가 디멘시우스를 공격하는 것이 좋을 겁니다.', `MaleText_loc4`='萨义德现在要么已经开战了，要么正在等待开战的命令。你可以直接去我的东面，看看萨义德是不是已经准备好了。如果他不在，那么他肯定正在进行另一场战斗。我建议你在进攻迪门修斯前等他回来。', `MaleText_loc5`='瑟翼德目前在進攻或者等待命令發動攻擊。你可以直接到我的正東方，並且看看瑟翼德是否準備好。如果他不在，那麼他是在進行其他的攻擊。在攻擊迪曼修斯之前，我建議你等他回來。', `MaleText_loc7`='Saeed ha salido o está esperando órdenes para salir. Puedes comprobarlo tú directamente: si está disponible, estará al este; si no está, probablemente esté luchando en alguna batalla. Te recomiendo que esperes a que vuelva antes de enfrentarte a Dimensius.' WHERE `ID`=18634;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새 위상 분열기가 필요합니다, 학자님.', `MaleText_loc4`='我需要一个新的相位扰流器，教授。', `MaleText_loc5`='我需要一個新的相位干擾器，教授。', `MaleText_loc7`='Necesito un nuevo perturbador de fase, profesor.', `FemaleText_loc1`='새 위상 분열기가 필요합니다, 학자님.', `FemaleText_loc4`='我需要一个新的相位扰流器，教授。', `FemaleText_loc5`='我需要一個新的相位干擾器，教授。', `FemaleText_loc7`='Necesito un nuevo perturbador de fase, profesor.' WHERE `ID`=18635;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황천의 비룡이 알았다는 듯 당신을 바라봅니다.', `MaleText_loc4`='虚空幼龙赞许地看着你。', `MaleText_loc5`='虛空龍認同地看著你。', `MaleText_loc7`='El draco abisal te dirige una mirada de aprobación.' WHERE `ID`=18636;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비됐으니 날 태워다 주렴!', `MaleText_loc4`='我准备起飞了！带我飞翔吧，龙！', `MaleText_loc5`='我已經準備好要起飛了!載我上去，幼龍!', `MaleText_loc7`='¡Todo listo para volar! ¡Llévame, dragón!', `FemaleText_loc1`='준비됐으니 날 태워다 주렴!', `FemaleText_loc4`='我准备起飞了！带我飞翔吧，龙！', `FemaleText_loc5`='我已經準備好要起飛了!載我上去，幼龍!', `FemaleText_loc7`='¡Todo listo para volar! ¡Llévame, dragón!' WHERE `ID`=18637;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황천의 비룡이 당신을 태우려고 하지 않습니다. 학자 다비리에게 위상 분열기를 얻어야 합니다. 위상 분열기가 없으면 황천의 비룡을 탈 수 없습니다.', `MaleText_loc4`='虚空幼龙拒绝让你骑上它。你要从达比雷教授那里拿到相位扰流器，否则它是不会载你起飞的。', `MaleText_loc5`='虛空龍拒絕讓你騎它。確定一下你從戴比瑞教授那裡得到一個相位干擾器。否則它將不會載你。', `MaleText_loc7`='El draco abisal se niega a llevarte. Consigue un perturbador de fase del profesor Dabiri. No te dejará montar sin uno.' WHERE `ID`=18638;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 바로 그 육체의 소유자입니다, 세이드 대장. 진군합시다!', `MaleText_loc4`='我就是那个“肉人”，萨义德。我们出发吧！', `MaleText_loc5`='我是那個凡人，瑟翼德。走吧!', `MaleText_loc7`='Yo soy ese ser de carne, Saeed. ¡Vamos!', `FemaleText_loc1`='제가 바로 그 육체의 소유자입니다, 세이드 대장. 진군합시다!', `FemaleText_loc4`='我就是那个“肉人”，萨义德。我们出发吧！', `FemaleText_loc5`='我是那個凡人，瑟翼德。走吧!', `FemaleText_loc7`='Yo soy ese ser de carne, Saeed. ¡Vamos!' WHERE `ID`=18639;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최종 공격 준비가 되었습니다, $n 님. 당신의 명령을 따르겠습니다! 공격 명령을 내리시면 부하들과 제가 디멘시우스를 처단하겠습니다!', `MaleText_loc4`='没问题，$n。我们会听你的命令冲锋陷阵！只要你一句话，我和我的手下就会发动进攻！', `MaleText_loc5`='就看這一擊了，$n。我們聽命於你!只要一個命令，我們將衝向敵人!', `MaleText_loc7`='Ya está, $n. ¡Atacamos cuando tú digas! ¡Da la orden y mis hombres y yo cargaremos!' WHERE `ID`=18640;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋습니다. 역사적인 날을 만들어 봅시다!', `MaleText_loc4`='我准备好了。让我们创造历史吧！', `MaleText_loc5`='我準備好了。讓我們創造歷史吧!', `MaleText_loc7`='Estoy listo. ¡Hagamos historia!', `FemaleText_loc1`='좋아요. 역사적인 날을 만들어 봅시다!', `FemaleText_loc4`='我准备好了。让我们创造历史吧！', `FemaleText_loc5`='我準備好了。讓我們創造歷史吧!', `FemaleText_loc7`='Estoy lista. ¡Hagamos historia!' WHERE `ID`=18641;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 제군들. 우리가 기다리던 육체의 소유자께서 오셨다! 진군하라!', `MaleText_loc4`='你们听到那肉人说的话了吗！开始行动！', `MaleText_loc5`='你們聽到命令了!出動!', `MaleText_loc7`='¡Ya habéis oído al ser de carne! ¡VAMOS!' WHERE `ID`=18642;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비되면 말씀하십시오, $n 님. 당신의 명령에 총공격을 개시하겠습니다.', `MaleText_loc4`='准备好了就告诉我，$n。我们听你号令，随时可以发动攻击。', `MaleText_loc5`='告訴我什麼時候你將準備好，$n。我們將依你的命令攻擊。', `MaleText_loc7`='Avísame cuando estés $glisto:lista;, $n. Atacaremos a tu orden.' WHERE `ID`=18643;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금이 아니면 영영 기회가 없다, 제군들! 총공격을 개시한다! 크아레쉬를 위해! 자유연합을 위해!', `MaleText_loc4`='机会难得，士兵们！让我们行动吧！为了卡雷什！为了维序派！', `MaleText_loc5`='士兵們，不成功便成仁!上吧!為凱瑞西而戰!為護國者而戰!', `MaleText_loc7`='¡Ahora o nunca, soldados! ¡Adelante! ¡Por K''aresh! ¡Por el Protectorado!' WHERE `ID`=18644;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 네놈을 처단할 때가 되었구나, 디멘시우스!', `MaleText_loc4`='你的末日终于来临了，迪门修斯！', `MaleText_loc5`='毀滅你的時刻終於到了，迪曼修斯!', `MaleText_loc7`='¡Ha llegado la hora de tu destrucción, Dimensius!' WHERE `ID`=18645;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 비웃습니다.', `MaleText_loc4`='%s笑了。', `MaleText_loc5`='%s大笑。', `MaleText_loc7`='%s ríe.' WHERE `ID`=18646;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간이란 필멸의 존재에게나 의미가 있는 것이지, 벌레 같은 놈. 나 디멘시우스는 영원한 존재이니라!', `MaleText_loc4`='时间只能约束凡人，蠢货。迪门修斯是无敌的！', `MaleText_loc5`='時間只對凡人，昆蟲有意義。迪曼修斯擁有無限的時間!', `MaleText_loc7`='¿La hora? ¡El tiempo solo tiene significado para los mortales, insectos! ¡Dimensius es infinito!' WHERE `ID`=18647;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세이드의 도움이 필요합니다, 학자님! 그는 어디에 있습니까?', `MaleText_loc4`='我需要萨义德的帮助，教授！他在哪里？', `MaleText_loc5`='我需要瑟翼德的幫助，教授!他在那裡?', `MaleText_loc7`='¡Necesito la ayuda de Saeed, profesor! ¿Dónde está?', `FemaleText_loc1`='세이드의 도움이 필요합니다, 학자님! 그는 어디에 있나요?', `FemaleText_loc4`='我需要萨义德的帮助，教授！他在哪里？', `FemaleText_loc5`='我需要瑟翼德的幫助，教授!他在那裡?', `FemaleText_loc7`='¡Necesito la ayuda de Saeed, profesor! ¿Dónde está?' WHERE `ID`=18648;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 이겼습니다! 드디어 디멘시우스가 죽었습니다! 돌아가서 학자님께 보고하십시오, 영웅이여.', `MaleText_loc4`='我们胜利了！迪门修斯已经不复存在了！回去向教授报告吧，英雄。', `MaleText_loc5`='我們勝利了!迪曼修斯已不存在!回報教授吧，英雄。', `MaleText_loc7`='¡Hemos vencido! ¡Dimensuis ya no existe! Vuelve a hablar con el profesor, héroe.' WHERE `ID`=18649;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여행자여, 중앙 생태지구에 온 것을 환영합니다. 숄리라는 고블린을 상대할 때는 아주 조심해야 합니다. 지금까지 ''친구''라는 단어를 마침표 대신 사용하는 자는 그자밖에 없었던 것 같습니다.', `MaleText_loc4`='欢迎来到中央生态圆顶，旅行者。我提醒你，和那个地精舒利做生意时要多留意。喜欢把“朋友”这个词作为标点符号的家伙一般都不可信。', `MaleText_loc5`='歡迎來到秘境領地，旅遊者。我要警告你謹慎處理那個哥布林，休利。我相信我之前從沒聽過任何人使用這個字「哥們」作為標點符號。', `MaleText_loc7`='Te doy la bienvenida al Ecodomo de la Tierra Media, $gviajero:viajera;. Tengo que pedirte que tengas cuidado al tratar con ese goblin, Shauly. Es la única persona que conozca que usa la palabra "colega" como signo de puntuación.' WHERE `ID`=18650;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 수리를 시작해 봅시다.', `MaleText_loc4`='现在开始修理吧。', `MaleText_loc5`='現在開始修理。', `MaleText_loc7`='Ahora, a empezar con las reparaciones.' WHERE `ID`=18651;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='작동하는군요! 가바르 님께서 이 소식을 들으면 기뻐하실 겁니다.', `MaleText_loc4`='成功了！贾巴尔会很高兴听到这个消息的。', `MaleText_loc5`='成功了!加巴聽到這個消息一定會很高興。', `MaleText_loc7`='¡Funciona! Ghabar estará encantado de saberlo.' WHERE `ID`=18652;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='드디어 우리가 여기 온 목적을 달성했군요. 우리가 $n|1을;를; 고용해서 잭슨, 당신의 어려움을 해결해 주기를 바랐답니다.', `FemaleText_loc4`='我们最终完成了来到这里的目的。我只是希望我们能马上雇用$n，然后把你从囚禁中解救出来，贾森。', `FemaleText_loc5`='我們最後終於取得我們來這裡要拿的東西了。我只希望我們立刻雇用$n並且挽救你的難堪，傑克森。', `FemaleText_loc7`='Al fin conseguimos lo que vinimos a buscar. Solo lamento no haber contratado a $n directamente. Te habrías ahorrado las molestias, Jaxon.' WHERE `ID`=18653;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그게 무슨 뜻인가요?', `MaleText_loc4`='那应该是什么意思？', `MaleText_loc5`='那是什麼意思?', `MaleText_loc7`='¿Qué quieres decir?' WHERE `ID`=18654;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 마침내 이곳을 떠나서 그 구역에서 작업을 시작할...', `MaleText_loc4`='嗯，至少我们可以离开这个地方，开始在圆顶工作了——', `MaleText_loc5`='好，至少我們能離開這個地方，並且開始對秘境著手工作，就在5 --', `MaleText_loc7`='Al menos podemos irnos de aquí y empezar a trabajar en el domo del área...' WHERE `ID`=18655;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잭슨! 우리 임무를 밝히려는 거예요? 그럼 절 좀 도와서 내가 작업 중인 이 옷에서 바늘을 꺼내주시죠...', `FemaleText_loc4`='贾森！你是不是试着想撕破我们的掩护？那么就帮帮我吧，我要把这件外套上的针拿走……', `FemaleText_loc5`='傑克森!你想暴露我們的真實身分嗎?來呀，讓我把我正在修補的短衫的針頭拔出來...', `FemaleText_loc7`='¡Jaxon! ¿Quieres descubrirnos o qué? Ayúdame, anda. Cogeré la aguja de esta blusa en la que estoy trabajando...' WHERE `ID`=18656;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='윽, 아니... 바늘은 안 돼요! 바늘만 빼면 아무거나 괜찮아요!', `MaleText_loc4`='不，别动针！除了针以外什么东西都可以！', `MaleText_loc5`='不，不要針頭!除了針以外的東西都可以!', `MaleText_loc7`='¡No, la aguja no! ¡Lo que sea, pero la aguja no!' WHERE `ID`=18657;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 당신의 서투른 솜씨를 보고 깔깔대며 웃습니다.', `MaleText_loc4`='%s嘲笑你的笨拙。', `MaleText_loc5`='%s嘲笑你的笨拙。', `MaleText_loc7`='%s se ríe de tu torpeza.' WHERE `ID`=18658;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알레리아 성채가 사방으로 적에게 포위되었으니 우리가 적들을 공격해야 합니다.', `MaleText_loc4`='奥蕾莉亚要塞被敌人重重包围，我们应该与他们一起战斗。', `MaleText_loc5`='由於艾蘭里堡壘四周都被敵人包圍了，是時候讓我們去與他們戰鬥了。', `MaleText_loc7`='El Bastión Allerian está rodeado de enemigos por todas partes. Es hora de plantarles cara.' WHERE `ID`=18659;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이곳에서 일을 할 작정을 했다면 그만큼 자네 자신의 능력에 대해 자신감이 있어야 하네. 저기 그림자추적자는 하는 일이 거의 없거든.', `FemaleText_loc4`='如果你想从这里出去的话，就得自己努力，那边的巡影者什么忙都帮不上。', `FemaleText_loc5`='你想不想來這裡，讓你自己成為有用的人，因為在那裡的巡影者做得不夠多。', `FemaleText_loc7`='Si vas a venir aquí fuera, haz algo útil, porque el acechasombras de ahí no está haciendo mucho.' WHERE `ID`=18661;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정확한 각도와 속도가 중요하지.', `MaleText_loc4`='精确的角度和速度……', `MaleText_loc5`='只要有準確的角度和速度...', `MaleText_loc7`='Con la velocidad y el ángulo preciso...' WHERE `ID`=18662;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하이잘 산 전투는 이 시간의 길에서 가장 굳건히 방어가 된 역사적인 사건 중 하나지요. 만약 어떤 침입자가 시간을 변경한다면 그 여파는 모든 역사를 뒤흔들어 하이잘 산 전투 이후에 벌어진 모든 사건들에 영향을 줄 겁니다.$B$B위상의 절친한 친구로서 저는 다른 청동용들에 비해 시간의 흐름과의 조화도가 훨씬 높답니다. 최근에 하이잘 산 전투를 둘러싼 사건들로부터 작은 시간의 파문을 느꼈습니다. 누군가 혹은 무언가가 이 시간대를 바꾸려 하고 있습니다. 반드시 그들을 막아야 합니다.', `FemaleText_loc4`='海加尔山战役是这条时间流里防备最严密的事件之一。一旦入侵者改变了它的结果，历史上所有的后续事件都会受到波及。$B$B做为守护者的配偶，我比其他青铜龙更熟悉时间流的动向。最近，我感觉海加尔山战役周围的时间突然出现了微妙的波动。一定有谁正在企图改变这条时间流，我们必须阻止他们。', `FemaleText_loc5`='海加爾山戰役是時間線中保護得最好的事件之一。如果一名入侵者改變它的結果，影響將會波及歷史上所有後續的關鍵發展。$B$B身為時間最好的夥伴，我比其他青銅龍更協調於時間流。我最近感覺到從圍繞海加爾山戰役的事件裡散發出片刻的時間漣漪。有人或者某些東西正試圖改變這條時間線，他們必須被制止。', `FemaleText_loc7`='La Batalla del Monte Hyjal es uno de los acontecimientos más protegidos de esta línea temporal. Si algún intruso modificara su resultado, se reflejaría en todos los momentos de la historia dependientes.$B$BComo mano derecha del Aspecto, soy más sensible al flujo del tiempo que otros dragones de bronce. He sentido una perturbación en el tiempo de los acontecimientos de la Batalla del Monte Hyjal. Alguien o algo está intentando cambiar esa línea temporal y hay que impedirlo.' WHERE `ID`=18663;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대지치유사여, 고맙습니다.', `MaleText_loc4`='谢谢你，大地治愈者。', `MaleText_loc5`='謝謝你，大地治癒者。', `MaleText_loc7`='Gracias, ensalmador de la tierra.' WHERE `ID`=18664;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고맙습니다, 친절한 영혼이여... 당신이 갈퀴흉터 저수지의 수중 감옥에서 절 구해주셨군요. 하지만, 아직 많은 이들이 근처 감옥에 갇혀 있답니다. 절 도와 그들도 구출해 주실래요?', `FemaleText_loc4`='感谢你，仁慈的灵魂。你从库斯卡的水牢中解救了我，但是还有很多人被关在附近。你会帮我解救他们吗？', `FemaleText_loc5`='謝謝你，善良的人。你將我救出考斯卡的水牢，但是在附近還有更多囚犯。你願意幫助我釋放他們嗎?', `FemaleText_loc7`='Gracias, amable $gamigo:amiga;. Me has liberado de esta prisión de agua de Cicatriz Espiral, pero todavía quedan muchos otros prisioneros en los alrededores. ¿Me ayudarás a liberarlos también?' WHERE `ID`=18665;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐만요. 엑소다르의 친구라는 사실을 증명해 보이기 전까지는 좋은 엘레크를 구입할 수 없답니다. 신용을 충분히 얻은 다음에 돌아오세요.', `MaleText_loc4`='等一下。在你证明自己是埃索达的朋友之前，你不能购买我们的雷象。等我们足够信任你了之后再来吧。', `MaleText_loc5`='等一下。我不能將優良的伊萊克賣給未經艾克索達所認同的人。等你得到我們的信任後再來吧。', `MaleText_loc7`='No tan rápido. No puedes adquirir un ejemplar de elekk como este sin probar antes que eres amigo de El Exodar. Vuelve cuando sepamos que podemos confiar en ti.', `FemaleText_loc1`='잠깐만요. 엑소다르의 친구라는 사실을 증명해 보이기 전까지는 좋은 엘레크를 구입할 수 없답니다. 신용을 충분히 얻은 다음에 돌아오세요.', `FemaleText_loc4`='等一下。在你证明自己是埃索达的朋友之前，你不能购买我们的雷象。等我们足够信任你了之后再来吧。', `FemaleText_loc5`='等一下。我不能將優良的伊萊克賣給未經艾克索達所認同的人。等你得到我們的信任後再來吧。', `FemaleText_loc7`='No tan rápido. No puedes adquirir un ejemplar de elekk como este sin probar antes que eres amigo de El Exodar. Vuelve cuando sepamos que podemos confiar en ti.' WHERE `ID`=18666;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 원하는 거요? 말해보시오. 우리 종족에 대한 당신의 헌신과 우정을 증명할 때까지는 내 엘레크를 내놓을 수 없소.', `MaleText_loc4`='你想要什么？说出来，在你可以证明你的贡献和与你和我们的友谊之前，我不准备雷象卖给你。', `MaleText_loc5`='你有什麼目的?大聲說。我不會把我的任何伊萊克托付給你，直到你證明你對我們族人的奉獻和友誼。', `MaleText_loc7`='¿Qué buscas? Habla. No voy a venderte un elekk hasta que demuestres amistad y dedicación a mi pueblo.', `FemaleText_loc1`='뭘 원하는 거요? 말해보시오. 우리 종족에 대한 당신의 헌신과 우정을 증명할 때까지는 내 엘레크를 내놓을 수 없소.', `FemaleText_loc4`='你想要什么？说出来，在你可以证明你的贡献和与你和我们的友谊之前，我不准备雷象卖给你。', `FemaleText_loc5`='你有什麼目的?大聲說。我不會把我的任何伊萊克托付給你，直到你證明你對我們族人的奉獻和友誼。', `FemaleText_loc7`='¿Qué buscas? Habla. No voy a venderte un elekk hasta que demuestres amistad y dedicación a mi pueblo.' WHERE `ID`=18667;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정령들이 받는 고통이 느껴집니다, $n. 이쪽입니다. 빨리 오십시오!', `FemaleText_loc4`='是痛苦的灵魂，我察觉到了。$n。他们在这里，快点过来！', `FemaleText_loc5`='我感覺到受折磨的靈魂，$n。他們在這方向。快點過來!', `FemaleText_loc7`='Siento los espíritus torturados, $n. Están por aquí. ¡Ven, rápido!' WHERE `ID`=18668;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n, 절 보호해 주세요. 놈들의 사악한 마법을 뚫고 나가야 합니다!', `FemaleText_loc4`='保护我，$n。我必须冲破他们邪恶的魔法！', `FemaleText_loc5`='庇護我，$n。我必須突破他們令人厭惡的魔法!', `FemaleText_loc7`='Protégeme, $n. ¡Tengo que atravesar su magia vil!' WHERE `ID`=18669;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 출구를 찾아야 합니다.', `FemaleText_loc4`='现在我们必须找到出口。', `FemaleText_loc5`='現在我們必須找到出口。', `FemaleText_loc7`='Ahora debemos encontrar la salida.' WHERE `ID`=18670;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n, 조금만 가면 돼요. 출구는 바로 저 위에 있으니까요.', `FemaleText_loc4`='应该不会太远了，$n。出口就在前面。', `FemaleText_loc5`='應該快到了，$n。出口就在前面。', `FemaleText_loc7`='No debería estar muy lejos, $n. La salida está por aquí.' WHERE `ID`=18671;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고맙습니다, $n. 굴단의 손아귀 근처의 저주의 제단에 있는 제 형제들에게 돌아가서 윌다는 안전하다고 전해 주십시오. 대지모신께서 굽어보시길...', `FemaleText_loc4`='谢谢你，$n。请回去转告我的兄弟，告诉他们维尔达安全了，他们在古尔丹之手附近的诅咒祭坛那里。愿大地之母保佑你……', `FemaleText_loc5`='謝謝你，$n。請返回位於古爾丹火山附近的詛咒祭壇，並且告訴他們，威爾達安全了。願大地之母保佑你...', `FemaleText_loc7`='Gracias, $n. Vuelve con los míos al Altar de Condenación, cerca de la Mano de Gul''dan y diles que Wilda está a salvo. Que la Madre Tierra esté contigo...' WHERE `ID`=18672;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나가는 자연을 존중할 줄 모릅니다. 놈들은 이기적인 목적으로 자연을 파괴하고 오염시킵니다. 마치 정령들을 괴롭히는 재미로 사는 것 같아요.', `FemaleText_loc4`='纳迦不尊重大自然。他们为了满足自己的私欲让大自然扭曲和堕落，他们的行为激怒了元素之灵。', `FemaleText_loc5`='納迦不尊重大自然。他們扭曲和腐化大自然以滿足他們的需要。他們的生活使精靈們焦慮。', `FemaleText_loc7`='Los nagas no respetan la naturaleza. Retuercen y corrompen lo que sea con tal de satisfacer sus necesidades. Viven para irritar a los espíritus.' WHERE `ID`=18673;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나가가 물의 정령들을 괴롭히고 있어요. 놈들은 혼돈과 파괴를 불러옵니다!', `FemaleText_loc4`='纳迦折磨着水之魂。他们引起了混乱和毁灭！', `FemaleText_loc5`='納迦折磨水靈。他們引起混亂和毀滅!', `FemaleText_loc7`='Los nagas torturan a los espíritus del agua. ¡Invocan solo caos y destrucción!' WHERE `ID`=18674;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아제로스와 드레노어에 있는 거대한 수로의 무질서한 본성은 물의 정령들이 받은 고통이 직접적으로 나타난 결과입니다.', `FemaleText_loc4`='被折磨的水之魂在艾泽拉斯世界和德拉诺世界的水道中躁动……', `FemaleText_loc5`='艾澤拉斯和德拉諾上巨大水道的騷動，是由痛苦的水靈所引起的。', `FemaleText_loc7`='La naturaleza turbulenta de las grandes vías de agua de Azeroth y Draenor son una consecuencia de la irritación de los espíritus del agua.' WHERE `ID`=18675;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='5...', `MaleText_loc4`='5……', `MaleText_loc5`='5...', `MaleText_loc7`='5...' WHERE `ID`=18676;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='4...', `MaleText_loc4`='4……', `MaleText_loc5`='4...', `MaleText_loc7`='4...' WHERE `ID`=18677;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='3...', `MaleText_loc4`='3……', `MaleText_loc5`='3...', `MaleText_loc7`='3...' WHERE `ID`=18678;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='2...', `MaleText_loc4`='2……', `MaleText_loc5`='2...', `MaleText_loc7`='2...' WHERE `ID`=18680;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='1...', `MaleText_loc4`='1……', `MaleText_loc5`='1...', `MaleText_loc7`='1...' WHERE `ID`=18681;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하루종일 거기에서 무릎을 꿇고 있을 건가?', `FemaleText_loc4`='你准备就这么整天跪在那里吗？', `FemaleText_loc5`='你打算跪一整天嗎?', `FemaleText_loc7`='¿Te vas a quedar de rodillas aquí todo el día?' WHERE `ID`=18682;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋아, 그냥 날 무시하게나. 무시하든 말든 신경도 안 쓰니까!', `FemaleText_loc4`='好吧，无视我。我不介意！', `FemaleText_loc5`='好，不理我。我不在乎!', `FemaleText_loc7`='Muy bien, pasa de mí. ¡Me da igual!' WHERE `ID`=18683;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여군주 바쉬는 이 극악무도한 짓거리에 대해 해명해야 해요. 정의의 이름으로 그녀를 심판해야 합니다!', `FemaleText_loc4`='瓦丝琪女王必须为这些暴行负责。她必将得到制裁！', `FemaleText_loc5`='瓦許女士必須對這些暴行負責。她必須被審判!', `FemaleText_loc7`='Lady Vashj deberá responder por esas atrocidades. ¡Hay que llevarla ante la justicia!' WHERE `ID`=18684;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='갈퀴흉터 저수지의 나가들은 유난히 포로들에게 잔인하답니다. 제가 그 수중 감옥 안에서 살아남은 것은 기적입니다. 모두 대지모신께서 돌봐주신 덕분이지요.', `FemaleText_loc4`='库斯卡的纳迦对他们的战俘异常凶残。我能在水牢里活这么长时间真是个奇迹。感谢大地之母。', `FemaleText_loc5`='考斯卡的納迦對他們的囚犯異常殘忍。我在那座水牢裡存活那麼久實在是一個奇蹟。感謝大地之母。', `FemaleText_loc7`='Los nagas de Cicatriz Espiral son muy crueles con sus prisioneros. Es un milagro que sobrevivieras en esa prisión de agua tanto como yo. Demos gracias a la Madre Tierra.' WHERE `ID`=18685;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 한숨을 쉬더니 모닥불로 돌아갑니다.', `MaleText_loc4`='%s叹着气，回到了营火旁。', `MaleText_loc5`='在嘆氣聲中，%s回到營火旁邊。', `MaleText_loc7`='%s vuelve a la hoguera suspirando.' WHERE `ID`=18686;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='조심하세요!', `FemaleText_loc4`='小心！', `FemaleText_loc5`='小心!', `FemaleText_loc7`='¡Cuidado!' WHERE `ID`=18687;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나가의 공격입니다! 방어하십시오!', `FemaleText_loc4`='纳迦进攻了！准备战斗！', `FemaleText_loc5`='納迦攻擊者!保護自己!', `FemaleText_loc7`='¡Ofensiva naga! ¡A cubierto!' WHERE `ID`=18688;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘은 너무도 조용하군요, 텔로리아. 블러드 엘프들이 뭔가 안 좋은 일을 꾸미고 있습니다. 난 느낄 수 있습니다.', `MaleText_loc4`='今天太宁静了，塞洛莉娅。我能感觉到，这些血精灵们肯定有什么邪恶的计划。', `MaleText_loc5`='今天太安靜了，瑟蘿莉雅。血精靈不懷好意。我能感覺到。', `MaleText_loc7`='Todo está demasiado tranquilo hoy, Theloria. Los elfos de sangre están tramando algo. Lo noto.' WHERE `ID`=18689;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='텔로리아가 대답이 없자 %s|1이;가; 투덜거립니다.', `MaleText_loc4`='%s对她的沉默表示不满。', `MaleText_loc5`='%s無聲地咕噥了一下。', `MaleText_loc7`='%s gruñe.' WHERE `ID`=18690;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘은 너무도 조용하군요, 텔로리아. 블러드 엘프들이 뭔가 안 좋은 일을 꾸미고 있습니다. 느낄 수 있단 말입니다.', `MaleText_loc4`='今天太宁静了，塞洛莉娅。我能感觉到，这些血精灵们肯定有什么邪恶的计划。', `MaleText_loc5`='今晚太安靜了，瑟蘿莉雅。血精靈們不懷好意。我能夠感覺到。', `MaleText_loc7`='Todo está demasiado tranquilo esta noche, Theloria. Los elfos de sangre están tramando algo. Lo noto.' WHERE `ID`=18691;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 죽여라!', `MaleText_loc4`='杀光他们！', `MaleText_loc5`='殺光他們全部!', `MaleText_loc7`='¡Mátalos a todos!' WHERE `ID`=18692;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갈퀴흉터 저수지에서 절대 도망칠 수 없다...', `MaleText_loc4`='别想从库斯卡手中逃掉……', `MaleText_loc5`='你永遠逃不出考斯斯斯卡卡卡的...', `MaleText_loc7`='No podrás escapar de Cicatriz Essspiral...' WHERE `ID`=18693;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대지를 산산이 갈라버리십시오, 굴단! 연결 고리를 제거하십시오!', `MaleText_loc4`='撕裂这片土地吧，古尔丹！切断我们与它之间的联系！', `MaleText_loc5`='撕裂土地，古爾丹!切斷聯繫!', `MaleText_loc7`='¡Parte la tierra, Gul''dan! ¡Corta el vínculo!', `FemaleText_loc1`='대지를 산산이 갈라버리십시오, 굴단! 연결 고리를 제거하십시오!', `FemaleText_loc4`='撕裂这片土地吧，古尔丹！切断我们与它之间的联系！', `FemaleText_loc5`='撕裂土地，古爾丹!切斷聯繫!', `FemaleText_loc7`='¡Parte la tierra, Gul''dan! ¡Corta el vínculo!' WHERE `ID`=18694;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잊지 마십시오! 그들은 우리를 버렸습니다!', `MaleText_loc4`='不要忘记！是它们抛弃了我们！', `MaleText_loc5`='他們遺棄了我們!別忘記!', `MaleText_loc7`='¡Nos han abandonado! ¡No olvides!', `FemaleText_loc1`='잊지 마십시오! 그들은 우리를 버렸어요!', `FemaleText_loc4`='不要忘记！是它们抛弃了我们！', `FemaleText_loc5`='他們遺棄了我們!別忘記!', `FemaleText_loc7`='¡Nos han abandonado! ¡No olvides!' WHERE `ID`=18695;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='순순히 말을 듣지 않겠다면 억지로라도 이 땅에서 끌어낼 거요!', `MaleText_loc4`='如果它们拒绝给予，我们就强夺！', `MaleText_loc5`='如果它拒絕交出，我們就從這片大地當中奪走!', `MaleText_loc7`='¡Tomaremos por la fuerza lo que la tierra nos niegue!', `FemaleText_loc1`='순순히 말을 듣지 않겠다면 억지로라도 이 땅에서 끌어낼 겁니다!', `FemaleText_loc4`='如果它们拒绝给予，我们就强夺！', `FemaleText_loc5`='如果它拒絕交出，我們就從這片大地當中奪走!', `FemaleText_loc7`='¡Tomaremos por la fuerza lo que la tierra nos niegue!' WHERE `ID`=18696;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이러지 마시오, 굴단! 정령들이 결코 우리를 용서하지 않을 것이오!', `MaleText_loc4`='不要这么做，古尔丹！元素们永远都不会原谅我们的！', `MaleText_loc5`='別這樣做，古爾丹!元素們絕不會原諒我們的!', `MaleText_loc7`='¡No lo hagas, Gul''dan! ¡Los elementos no nos perdonarán nunca!', `FemaleText_loc1`='이러지 마십시오, 굴단! 정령들이 결코 우리를 용서하지 않을 것이오!', `FemaleText_loc4`='不要这么做，古尔丹！元素们永远都不会原谅我们的！', `FemaleText_loc5`='別這樣做，古爾丹!元素們絕不會原諒我們的!', `FemaleText_loc7`='¡No lo hagas, Gul''dan! ¡Los elementos no nos perdonarán nunca!' WHERE `ID`=18697;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만! 그만 멈추십시오!', `MaleText_loc4`='住手！你必须马上住手！', `MaleText_loc5`='停!你一定要停下來!', `MaleText_loc7`='¡Para! ¡Detente de una vez!', `FemaleText_loc1`='그만! 그만 멈추세요!', `FemaleText_loc4`='住手！你必须马上住手！', `FemaleText_loc5`='停!你一定要停下來!', `FemaleText_loc7`='¡Para! ¡Detente de una vez!' WHERE `ID`=18698;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 자손들을 생각하세요, 굴단! 당신의 행동은 우리 모두를 파멸로 이끌 겁니다!', `MaleText_loc4`='想想我们的后代，古尔丹！你会毁灭我们的！', `MaleText_loc5`='想想我們的孩子，古爾丹!你會毀了我們全部!', `MaleText_loc7`='¡Piensa en nuestra descendencia, Gul''dan! ¡Nos vas a destruir a todos!', `FemaleText_loc1`='우리 아이들을 생각하세요, 굴단! 당신의 행동은 우리 모두를 파멸로 이끌 거예요!', `FemaleText_loc4`='想想我们的后代，古尔丹！你会毁灭我们的！', `FemaleText_loc5`='想想我們的孩子，古爾丹!你會毀了我們全部!', `FemaleText_loc7`='¡Piensa en nuestra descendencia, Gul''dan! ¡Nos vas a destruir a todos!' WHERE `ID`=18699;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 우리 모두를 파멸의 구렁텅이에 빠뜨렸소. 우리 모두 패배했단 말이오.', `MaleText_loc4`='你诅咒了我们……我们完蛋了。', `MaleText_loc5`='你已經毀了我們所有人...我們輸了。', `MaleText_loc7`='Nos has condenado a todos... Estamos perdidos.', `FemaleText_loc1`='당신은 우리 모두를 파멸의 구렁텅이에 빠뜨렸어요. 우리 모두 패배했단 말입니다.', `FemaleText_loc4`='你诅咒了我们……我们完蛋了。', `FemaleText_loc5`='你已經毀了我們所有人...我們輸了。', `FemaleText_loc7`='Nos has condenado a todos... Estamos perdidos.' WHERE `ID`=18700;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조용히 해! 파멸의 날이 머지않았다!', `MaleText_loc4`='安静！大地的崩溃很快就要来临了！', `MaleText_loc5`='肅靜!毀滅很快就到了!', `MaleText_loc7`='¡Silencio! ¡Ahora llega la destrucción!' WHERE `ID`=18701;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거부할 수 없는 힘을 갖고 계신 어둠의 주인님을 맞이하라!', `MaleText_loc4`='亲眼看看黑暗主宰那势不可挡的力量吧！', `MaleText_loc5`='證明我們黑暗主人無法否認的力量!', `MaleText_loc7`='¡Contempla el innegable poder de nuestro oscuro amo!' WHERE `ID`=18702;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그분께서 선사하는 능력으로 나는 이 땅을 파괴한 후 재건할 것이니라!', `MaleText_loc4`='有了他所赐予的力量，我会夷平这片土地，并重新铸造它！', `MaleText_loc5`='有了他的禮物，我應該可以夷平並改良這片土地。', `MaleText_loc7`='¡Con este don, arrasaré la tierra para recrearla!' WHERE `ID`=18703;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보아라! 우리 앞의 땅이 갈라진다! 에너지의 흐름을 주시해라! 적에게 힘을 주는 원천이니...', `MaleText_loc4`='看！大地在我们面前破碎了！看那些流动的能量！它会让我们的军队更加强大……', `MaleText_loc5`='瞧!看我們面前地上的那條裂縫!注意能量的流動!這可以養活我們的軍隊...', `MaleText_loc7`='¡Mira! ¡Mira cómo se abre el suelo ante nosotros! ¡Mira cómo fluye la energía! Alimentará a nuestro ejército...' WHERE `ID`=18704;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 결코 힘을 잃지 않는다! 난 우리의 미래를 지켜왔다! 너희는 나와 함께 영광을 누리리라!', `MaleText_loc4`='我们再也不会缺乏足够的力量了！我拯救了我们的未来！享受我的荣耀吧！', `MaleText_loc5`='我們絕不會失去力量!我已經保護了我們的未來!沐浴在我的光榮裡吧!', `MaleText_loc7`='¡Nunca nos faltará poder! He asegurado nuestro futuro. ¡Someteos a mi gloria!' WHERE `ID`=18705;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 모든 게... 끝났다...', `MaleText_loc4`='结……束……了……', `MaleText_loc5`='這...個...完成了...', `MaleText_loc7`='Ya... está... hecho...' WHERE `ID`=18706;
