UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 이날이 오기만을 손꼽아 기다려 왔습니다!', `MaleText_loc4`='我们等这个日子已经很久了！', `MaleText_loc5`='我們等待這一天的來臨已經等待很久了。', `MaleText_loc7`='¡Llevábamos esperando mucho tiempo a que llegara este día!' WHERE `ID`=18711;
