UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 공손한 어조로 작게 중얼거립니다.', `FemaleText_loc4`='%s低声念诵着虔诚的祷文。', `FemaleText_loc5`='%s以恭敬的語調輕輕低聲地耳語著。', `FemaleText_loc7`='%s susurra con suavidad en un tono reverente.' WHERE `ID`=18715;
