UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노동력을 보충할 시간이군.', `MaleText_loc4`='是叫人帮忙的时候了。', `MaleText_loc5`='是該增加人力的時候了。', `MaleText_loc7`='Hora de reforzar mi mano de obra.' WHERE `ID`=18717;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='생명의 숲에서 우리 일이 무사히 진행되어야 합니다. 우리의 생존은 숲의 안녕과 성장에 달렸습니다.', `FemaleText_loc4`='我们在活木林的工作不能受到打扰。活木林持续与健康的成长决定了我们的命运。', `FemaleText_loc5`='我們在生命之林裡的工作瀕臨斷絕。我們的生命決定於它延續的健康和成長。', `FemaleText_loc7`='Nuestro trabajo en la Arboleda Viviente no debe ponerse en peligro. Nuestras propias vidas dependen de su crecimiento y su salud.' WHERE `ID`=18718;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 현상 수배 전단에 붙은 정보를 검토합니다.', `MaleText_loc4`='%s仔细地读着通缉令。', `MaleText_loc5`='%s檢查懸賞告示上的訊息。', `MaleText_loc7`='%s se une a Rina en su meditación silenciosa.' WHERE `ID`=18719;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 리나 문스프링을 도와주지 않았다면 그녀를 찾아가 보시오.', `MaleText_loc4`='去问问莉娜·月泉有什么需要你帮助的事情吧。', `MaleText_loc5`='假如你還沒拿到，請確認你對琳娜·月泉提供了協助。', `MaleText_loc7`='Si todavía no lo has hecho, asegúrate de ofrecer tu ayuda a Rina Lunabril.' WHERE `ID`=18720;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 들은 얘기가 정확하다면 그대가 이미 실바나르를 위해 좋은 일을 했더군.$B$B계속 힘써 주면 이곳의 우리 진지를 지켜낼 수 있소.', `MaleText_loc4`='如果我听说的事情都属实的话，你已经为希尔瓦纳做了很多事。$B$B继续下去，也许我们能在这里安家了。', `MaleText_loc5`='如果我聽到的沒錯，你已經為希爾瓦納完成了令人滿意的工作。$B$B保持下去，或許我們能夠把家留在這裡。', `MaleText_loc7`='Si he entendido bien, ya estás haciendo un buen trabajo para Sylvanaar.$B$BSigue así y es posible que podamos conservar nuestro hogar aquí.' WHERE `ID`=18721;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='복수의 시간이 다가왔다.', `MaleText_loc4`='复仇的日子即将到来了。', `MaleText_loc5`='報仇的時間接近了。', `MaleText_loc7`='Se acerca la hora de la venganza.' WHERE `ID`=18722;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너는 우리의 명령을 따르게 될 것이다, 필멸의 존재여.', `MaleText_loc4`='照我的吩咐办事，凡人。', `MaleText_loc5`='你將執行我們的命令，凡人。', `MaleText_loc7`='Harás lo que se te ordene, mortal.' WHERE `ID`=18723;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조만간 모든 것이 끝날 것이다...', `MaleText_loc4`='一切都会很快结束的……', `MaleText_loc5`='很快的全部都會結束...', `MaleText_loc7`='Todo acabará muy pronto...' WHERE `ID`=18724;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진짜 싸움을 시작해 볼까...', `MaleText_loc4`='我喜欢自己动手……', `MaleText_loc5`='我比較喜歡自己動手做...', `MaleText_loc7`='Manos a la obra...' WHERE `ID`=18725;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 종류의 새끼 용매를 팔고 있는지 보고 싶습니다.', `MaleText_loc4`='让我看看你这里有什么小东西卖。', `MaleText_loc5`='讓我看看你有哪些幼獸出售。', `MaleText_loc7`='Déjame ver la prole que tienes a la venta.', `FemaleText_loc1`='어떤 종류의 새끼 용매를 팔고 있는지 보고 싶습니다.', `FemaleText_loc4`='让我看看你这里有什么小东西卖。', `FemaleText_loc5`='讓讓我看看你有哪些幼獸出售。', `FemaleText_loc7`='Déjame ver la prole que tienes a la venta.' WHERE `ID`=18726;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여행자여, 가서 편히 쉬게. 따뜻한 우리 모닥불을 자네 것처럼 생각하게나.', `MaleText_loc4`='去休息吧，流浪者。让我们同享这炉火。', `MaleText_loc5`='漫遊者，去休息吧。我們的火堆就是你的。', `MaleText_loc7`='Descansa, vagabundo. Nuestros fuegos son tuyos.', `FemaleText_loc1`='여행자여, 가서 편히 쉬게. 따뜻한 우리 모닥불을 자네 것처럼 생각하게나.', `FemaleText_loc4`='去休息吧，流浪者。让我们同享这炉火。', `FemaleText_loc5`='漫遊者，去休息吧。我們的火堆就是你的。', `FemaleText_loc7`='Descansa, vagabundo. Nuestros fuegos son tuyos.' WHERE `ID`=18727;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사정거리 안에 들어왔소! 지금 위상 분열기를 투하하시오!', `MaleText_loc4`='距离正好！快投下相位扰流器！！！', `MaleText_loc5`='你被瞄準了!馬上把相位干擾器丟掉!!!', `MaleText_loc7`='¡Ya estás cerca! ¡¡Tira el perturbador de fase ahora!!', `FemaleText_loc1`='사정거리 안에 들어왔소! 지금 위상 분열기를 투하하시오!', `FemaleText_loc4`='距离正好！快投下相位扰流器！！！', `FemaleText_loc5`='你被瞄準了!馬上把相位干擾器丟掉!!!', `FemaleText_loc7`='¡Ya estás cerca! ¡¡Tira el perturbador de fase ahora!!' WHERE `ID`=18728;
