UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 세계를 떠나면서 그의 명령을 수행할 망령을 소환합니다.', `MaleText_loc4`='%s离开了这个世界，召唤出影子来执行他的命令。', `MaleText_loc5`='%s離開這個世界，並傳喚幽靈去執行他的命令。', `MaleText_loc7`='%s se va del mundo e invoca a sus siervos sombra.' WHERE `ID`=18730;
