UPDATE `locales_broadcast_text` SET `MaleText_loc1`='승리가 아니면 죽음뿐!', `MaleText_loc4`='胜利或者死亡！', `MaleText_loc5`='不勝即亡!', `MaleText_loc7`='¡Victoria o muerte!' WHERE `ID`=18732;
