UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 괴철로를 향해 돌진합니다.', `MaleText_loc4`='%s冲向熔炉。', `MaleText_loc5`='%s衝向鍛爐。', `MaleText_loc7`='%s se va corriendo hacia la forja.' WHERE `ID`=18735;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳이 바로 굴단이 오크와 정령 사이의 연결 고리를 제거한 장소라오. 힘에 대한 그의 끝없는 갈증은 드레나이의 전멸로도 채울 수가 없었지. 굴단은 드레노어도 멸망시켰는데, 대지를 파괴해 그 힘을 모조리 흡수하여 전쟁에 사용했소.$B$B이제 남은 것이라고는 그의 광기밖에 없소.$B$B$r|1이여;여;, 제단을 보시오. 대지에서 분노한 넋들이 끝없이 출몰하고 있소이다...', `MaleText_loc4`='就是在这里，古尔丹切断了兽人们和元素之灵间的联系。将德莱尼人全部消灭已经不能满足他对无尽力量的渴望。为了他的战争，他要把德拉诺也夷为平地，吸取它的所有能量。$B$B现在这里所留下的一切都只是他那疯狂过后的痕迹。$B$B看那祭坛，$r——这块大地将永远死气沉沉……', `MaleText_loc5`='古爾丹就是在這裡切斷獸人和元素之靈間的聯繫。他對力量的那種無法抑制的渴望無法由徹底消滅德萊尼來得到滿足。他還得毀掉德拉諾，夷平土地並且汲取它所有的能量供給他的戰爭使用。$B$B現在所剩下的都是他瘋狂行徑的殘餘。$B$B看看這個祭壇，$r - 這片大地永遠被困著...', `MaleText_loc7`='Aquí fue donde Gul''dan cortó el vínculo entre los orcos y los espíritus elementales. Su insaciable sed de poder no se conformaba con la aniquilación de los draenei. Tenía que destruir Draenor; arrasar la tierra y absorber su energía para usarla en la guerra.$B$BAhora todo lo que queda son jirones de su locura.$B$BMira el altar, $r. Esta tierra quedará marcada para siempre...' WHERE `ID`=18736;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카라보르의 진혼곡이 하늘 끝까지 울려 퍼집니다.', `MaleText_loc4`='卡拉波的挽歌向天空发出嚎叫。', `MaleText_loc5`='卡拉伯爾的輓歌喊向天堂。', `MaleText_loc7`='El Réquiem de Karabor sube hacia el cielo.' WHERE `ID`=18737;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카라보르의 진혼곡이 정령들에게 반사됩니다.', `MaleText_loc4`='卡拉波的挽歌变回了元素生物。', `MaleText_loc5`='卡拉伯爾的輓歌回歸元素。', `MaleText_loc7`='El canto fúnebre de Karabor vuelve a los elementos.' WHERE `ID`=18738;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 파열의 회오리를 시전합니다!', `MaleText_loc4`='%s开始施放冲击新星！', `MaleText_loc5`='%s開始施展衝擊新星!', `MaleText_loc7`='¡%s comienza a lanzar una Nova explosiva!' WHERE `ID`=18739;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 말씀해 주십시오.', `MaleText_loc4`='请继续。', `MaleText_loc5`='請繼續。', `MaleText_loc7`='Adelante.', `FemaleText_loc1`='계속 말씀해 주십시오.', `FemaleText_loc4`='请继续。', `FemaleText_loc5`='請繼續。', `FemaleText_loc7`='Adelante.' WHERE `ID`=18740;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 우리 선조의 유서깊은 주술 전통을 자랑스럽게 생각하오. 오늘 우리가 이 자리에 있기까지 선조의 희생이 따랐다는 사실을 결코 잊어서는 안 되오.$B$B그리고 이제 후손의 미래를 위해 우리가 희생할 차례요.$B$B그런데 무슨 이유로 날 찾아온 거요?', `MaleText_loc4`='我为祖先们秉承着历史悠久的萨满教统而感到荣幸。我们必须铭记他们所做出的牺牲。$B$B对我们来说，作为回报，我们必须为后代的将来做出必要的牺牲。$B$B是什么把你带到我这里来的，$c？', `MaleText_loc5`='我在古老崇敬的薩滿傳統裡尊敬我的祖先。我們絕不能忘記他們的犧牲造就今日我們能夠在這裡生存。$B$B同樣的，我們也得做出必要的犧牲讓我們的子孫能有個未來。$B$B什麼將你帶到我這裡，$c?', `MaleText_loc7`='Honro a mis ancestros en la tradición chamanística. Nunca hay que olvidar los sacrificios que hicieron para que pudiéramos estar aquí.$B$BNosotros, a cambio, debemos hacer los sacrificios necesarios para que nuestros descendientes tengan un futuro.$B$B¿Qué te trae a mí, $c?' WHERE `ID`=18741;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 후에 무슨 일을 하셨습니까?', `MaleText_loc4`='那么你做了些什么？', `MaleText_loc5`='那你到底做了什麼?', `MaleText_loc7`='¿Qué hiciste después?', `FemaleText_loc1`='그 후에 무슨 일을 하셨나요?', `FemaleText_loc4`='那么你做了些什么？', `FemaleText_loc5`='那你到底做了什麼?', `FemaleText_loc7`='¿Qué hiciste después?' WHERE `ID`=18742;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 후에 무슨 일이 벌어졌습니까?', `MaleText_loc4`='后来呢？', `MaleText_loc5`='接下來發生了什麼事?', `MaleText_loc7`='¿Qué pasó después?', `FemaleText_loc1`='그 후에 무슨 일이 벌어졌죠?', `FemaleText_loc4`='后来呢？', `FemaleText_loc5`='接下來發生了什麼事?', `FemaleText_loc7`='¿Qué pasó después?' WHERE `ID`=18743;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇군요.', `MaleText_loc4`='我知道了。', `MaleText_loc5`='我知道。', `MaleText_loc7`='Entiendo.', `FemaleText_loc1`='그렇군요.', `FemaleText_loc4`='我知道了。', `FemaleText_loc5`='我知道。', `FemaleText_loc7`='Entiendo.' WHERE `ID`=18744;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='묻고 싶은 게 또 있습니다.', `MaleText_loc4`='我还想问你一些其它的问题。', `MaleText_loc5`='我還有其他事情想要問你。', `MaleText_loc7`='Hay otra cosa que quiero preguntarte.', `FemaleText_loc1`='묻고 싶은 게 또 있습니다.', `FemaleText_loc4`='我还想问你一些其它的问题。', `FemaleText_loc5`='我還有其他事情想要問你。', `FemaleText_loc7`='Hay otra cosa que quiero preguntarte.' WHERE `ID`=18745;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='근처 오우거들로부터 천둥군주 요새를 빼앗은 지 얼마 되지 않았소.$B$B요새 방어를 도우려고 왔소? 고르드렉이 일손을 구하고 있으니 가보시오.', `MaleText_loc4`='不久以前，我们从周围的食人魔那里夺回了雷神要塞的控制权。$B$B你是来这里帮我们防守的吗？我知道高德雷克正在寻求帮助。', `MaleText_loc5`='不久之前我們必須從附近的巨魔手中將雷霆王村的控制權奪過來。$B$B你是來這裡幫助我們維持我們的防禦嗎?我知道葛德雷克正在尋求協助。', `MaleText_loc7`='No ha pasado tanto tiempo desde que tomamos el Bastión Señor del Trueno de manos de los ogros.$B$B¿Estás aquí para ayudarnos a defenderlo? Sé que Gor''drek busca ayuda.' WHERE `ID`=18746;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 배낭에 손을 넣더니 사악한 표정을 짓습니다.', `MaleText_loc4`='%s把手伸进背包时，双眼射出邪恶的光芒。', `MaleText_loc5`='當%s將手伸進他的背包時，他的眼睛裡露出了邪惡的神情。', `MaleText_loc7`='%s tiene una mirada maligna mientras busca en su mochila.' WHERE `ID`=18747;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 그의 아버지를 부르는 듯 울음소리를 냅니다.', `MaleText_loc4`='%s大声呼唤着它的父亲。', `MaleText_loc5`='%s大聲呼叫它的父親。', `MaleText_loc7`='%s llama a su padre.', `FemaleText_loc1`='%s|1이;가; 그의 아버지를 부르는 듯 울음소리를 냅니다.', `FemaleText_loc4`='%s大声呼唤着它的父亲。', `FemaleText_loc5`='%s大聲呼叫它的父親。', `FemaleText_loc7`='%s llama a su padre.' WHERE `ID`=18748;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정령들이 공격할지도 모르니 물러서시오, $n.', `MaleText_loc4`='靠后，$n。灵魂可能会伤害到你。', `MaleText_loc5`='退後，$n。鬼魂們也許會發動猛烈攻擊。', `MaleText_loc7`='Atrás, $n. Los espíritus pueden atacar.' WHERE `ID`=18749;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리를 왜 사로잡았지?', `MaleText_loc4`='为什么你要捕获我们？', `MaleText_loc5`='為什麼你捕捉了我們?', `MaleText_loc7`='¿Por qué nos has capturado?' WHERE `ID`=18750;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 해서 얻으려는 게 뭔가?', `MaleText_loc4`='你希望从中得到些什么？', `MaleText_loc5`='這次你希望學點什麼?', `MaleText_loc7`='¿Qué esperas obtener de esto?' WHERE `ID`=18751;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 절을 합니다.', `MaleText_loc4`='%s鞠了一躬。', `MaleText_loc5`='%s 鞠躬。', `MaleText_loc7`='%s se inclina.' WHERE `ID`=18752;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정령이여, 우리는 그대들을 돕고 싶소. 그대들의 지혜를 구합니다.', `MaleText_loc4`='我们希望能帮助你，灵魂。我们寻求你的智慧。', `MaleText_loc5`='我們想要幫助你，鬼魂。我們需要你的智慧。', `MaleText_loc7`='Queremos ayudarte, espíritu. Buscamos tu sabiduría.' WHERE `ID`=18753;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지혜라고 했나? 사이루크의 억제할 수 없는 분노를 부른 것은 자네 종족이었잖아.', `MaleText_loc4`='智慧？是你的同族导致了森卢肯那无比的愤怒。', `MaleText_loc5`='智慧?就是你的人引起賽洛庫無法容忍的憤怒。', `MaleText_loc7`='¿Sabiduría? Tu pueblo fue el que provocó la terrible ira de Cyrukh.' WHERE `ID`=18754;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 왜 너희를 도와야 하지? 이 세계는 폐허가 되었어. 멸망했단 말이지.', `MaleText_loc4`='为什么我们要帮助你们？这个世界已经被毁灭了，被破坏了。', `MaleText_loc5`='我們為什麼要幫助你?這個世界被毀了。破壞了。', `MaleText_loc7`='¿Por qué deberíamos ayudarte? El mundo está arrasado. Destruido.' WHERE `ID`=18755;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 고개를 끄덕입니다.', `MaleText_loc4`='%s点了点头。', `MaleText_loc5`='%s點點頭。', `MaleText_loc7`='%s asiente con la cabeza.' WHERE `ID`=18756;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대들의 말이 맞소, 정령이여... 그대들에게 그런 짓을 한 것은 나의 동족이었소. 우리가 그 잘못을 바로잡게 해주시오.', `MaleText_loc4`='你是对的，灵魂。是我的同胞对你们做了这些错事，但是请让我们纠正这一切。', `MaleText_loc5`='你是對的，鬼魂。就是我們的人對你做了這種事。請允許我們將它導正。', `MaleText_loc7`='Tienes razón, espíritu. Mi pueblo os hizo esto. Déjanos enmendar nuestros errores.' WHERE `ID`=18757;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제발 이것만은 알려주시오. 대체 사이루크가 뭐요?', `MaleText_loc4`='请告诉我们：森卢肯是谁，或者说，是什么？', `MaleText_loc5`='請告訴我們︰賽洛庫是人還是東西?', `MaleText_loc7`='Solo dinos esto: ¿qué o quién es Cyrukh?' WHERE `ID`=18758;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바보 같은! 불의 군주 사이루크 말일세! 연결 고리가 끊어졌을 때 사이루크가 깨어났지. 사이루크의 눈물이 흘러내려 이 땅을 용암으로 채운 걸세.', `MaleText_loc4`='蠢货！火焰之王森卢肯！当联系被切断的时候，森卢肯醒了，是森卢肯的泪水注满了这片遍是熔岩的大地。', `MaleText_loc5`='傻瓜!火焰之王賽洛庫!當聯繫被切斷，賽洛庫醒了過來。充滿這片陸地的熔岩就是賽洛庫的眼淚。', `MaleText_loc7`='¡Insensato! ¡Cyrukh, el señor de Fuego! Cuando se rompió el vínculo, Cyrukh despertó. Son las lágrimas de Cyrukh las que llenan este mundo de roca fundida.' WHERE `ID`=18759;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불... 불의 군주라고 하셨소? 정령들의 군주가 깨어났다는 말이오? 그렇군... 굴단 당신은 정말 바보였소!', `MaleText_loc4`='火……火焰之王？那不是一位元素之王吗？难怪……古尔丹，你这个该死的蠢货！', `MaleText_loc5`='火...火焰之王?發現一個元素之王了嗎?當然...古爾丹你是一個討人厭的傻瓜!', `MaleText_loc7`='El... ¿El Señor del Fuego? ¿Despertó a un señor elemental? Claro... ¡Maldito Gul''dan!' WHERE `ID`=18760;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 그는 제정신이 아닐세. 세계가 파괴되는 동안 미쳐버렸지. 우리 정령들이 쉴 수가 없어.', `MaleText_loc4`='他现在已经疯了，在破碎中失去了理智。元素们将永无安宁。', `MaleText_loc5`='他現在瘋了。在碎裂時發了狂。元素無法得到休息。', `MaleText_loc7`='Ahora ha perdido la razón. Se volvió loco durante la rotura. No hay descanso para los elementos.' WHERE `ID`=18761;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분명 방법이 있을 거요.', `MaleText_loc4`='肯定有办法解决的。', `MaleText_loc5`='一定有方法。', `MaleText_loc7`='Tiene que haber una forma.' WHERE `ID`=18762;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 방법이 있어. 바로 사이루크를 해치우는 걸세. 정령의 군주를 해치워야 해.', `MaleText_loc4`='是的，有一个方法：消灭森卢肯。消灭这位元素之王。', `MaleText_loc5`='是的，一個方法。殺掉賽洛庫。殺掉一個元素之王。', `MaleText_loc7`='Sí, una forma. Destruir a Cyrukh. Destruir a un señor elemental.' WHERE `ID`=18763;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정령이여, 나와 동료를 믿어주시오. 그리고 불의 군주를 소환할 방법을 알려주시오. 우리 동맹이 놈을 쓰러뜨릴 거요.', `MaleText_loc4`='不要怀疑我和我的朋友，灵魂。请告诉我们怎样才能召唤炎魔之王。我的朋友们会消灭他的。', `MaleText_loc5`='不要懷疑我的夥伴和我，鬼魂。告訴我們如何召喚火焰之王。我的盟友將會殺掉他。', `MaleText_loc7`='No dudes de mis camaradas ni de mí, espíritu. Dinos cómo invocar al señor elemental. Mis aliados y yo lo destruiremos.' WHERE `ID`=18764;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주문을 외워야 하네...', `MaleText_loc4`='你倒是说句话啊……', `MaleText_loc5`='你必須要傳達這些訊息...', `MaleText_loc7`='Debéis pronunciar las palabras...' WHERE `ID`=18765;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 맞아! 그 주문... 파멸의 주문... 자네의 스승이었던 어둠의 존재가 사용했던 그 주문!', `MaleText_loc4`='是的……是的……咒语。诅咒的咒语。你那黑暗的主人所诵读的咒语。', `MaleText_loc5`='是...是...這些文字。詛咒的文字。黑暗者所提的那些文字。你的主人。', `MaleText_loc7`='Sí... Sí..., las palabras. Las palabras de la maldición. Las palabras pronunciadas por el oscuro, tu maestro.' WHERE `ID`=18766;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래... 굴단...', `MaleText_loc4`='是的……古尔丹……', `MaleText_loc5`='是的...古爾丹...', `MaleText_loc7`='Sí... Gul''dan...' WHERE `ID`=18767;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 반드시 그 주문을 찾아낼 거요. 그리고 놈을 소환해 해치우겠소.', `MaleText_loc4`='我们会找到这些咒语。我们会召唤你的主人，并把他消灭掉。', `MaleText_loc5`='我們會找到這些文字。我們將會召喚你的主人，而且我們會毀掉他。', `MaleText_loc7`='Encontraremos esas palabras. Invocaremos a tu maestro y lo destruiremos.' WHERE `ID`=18768;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대화... 대화가 필요하오... 필멸의 생명체여, 이제 우리를 풀어주시오.', `MaleText_loc4`='交谈，更多的交谈……现在放了我们，凡人。', `MaleText_loc5`='談判。更多的談判...現在釋放我們，凡人。', `MaleText_loc7`='Hablas. Solo hablas... Ahora libéranos, mortal.' WHERE `ID`=18769;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나루의 보좌에는 두 개의 우체통이 있는데, 하나는 은행 근처에, 다른 하나는 경매장 밖에 있습니다.', `MaleText_loc4`='在纳鲁之座有两个邮箱：一个在银行的附近，另一个在拍卖行的外面。', `MaleText_loc5`='在那魯之座有兩個郵箱︰一個緊鄰銀行，而另一個在拍賣場外面。', `MaleText_loc7`='Hay dos buzones de correo en el Trono de los Naaru: uno al lado del banco y otro en el exterior de la casa de subastas.', `FemaleText_loc1`='나루의 보좌에는 두 개의 우체통이 있는데, 하나는 은행 근처에, 다른 하나는 경매장 밖에 있습니다.', `FemaleText_loc4`='在纳鲁之座有两个邮箱：一个在银行的附近，另一个在拍卖行的外面。', `FemaleText_loc5`='在那魯之座有兩個郵箱︰一個緊鄰銀行，而另一個在拍賣場外面。', `FemaleText_loc7`='Hay dos buzones de correo en el Trono de los Naaru: uno al lado del banco y otro en el exterior de la casa de subastas.' WHERE `ID`=18770;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전쟁을 어떻게 생각하시오? 우리가 여기 있는 이유를 명심하시기 바라오... 그러면 싸우고 죽는 일이 좀 더 쉽게 느껴질 것이오.', `MaleText_loc4`='你觉得战争怎么样，$n？想想我们为什么来这儿吧……这会让你更容易接受无尽的战斗和死亡。', `MaleText_loc5`='你覺得戰爭怎麼樣，$n?只要記得我們為什麼在這裡...那就是戰鬥，以及死亡的原因，會容易得多。', `MaleText_loc7`='¿Qué te parece la guerra, $n? Tú recuerda por qué estamos aquí... Eso hace que luchar y morir sea mucho más fácil.' WHERE `ID`=18771;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳 상황을 볼 때 원정대 거점은 군대가 주둔하기 어려운 지역이지만 명예의 요새 방어를 위해 중요한 곳이오. 이곳에서 얻는 정보와 우리 병사들이 불타는 군단과 제스고르의 오크들을 상대로 벌이는 교전은 얼라이언스가 지옥불 반도로 출정을 하기 위해 매우 중요한 것이지.', `MaleText_loc4`='远征军岗哨是个条件艰苦的地方，但是那里对荣耀堡的防御非常关键。在这里收集的情报，还有士兵们与燃烧军团和塞斯高兽人之间的战斗，都是联盟在地狱火半岛的战役中的关键。', `MaleText_loc5`='遠征隊哨塔是一個可以駐紮的堅固之地，但當務之急是保護榮譽堡。這裡資訊的收集，以及我們的士兵對抗軍團和薩斯葛爾獸人所做的戰鬥，對聯盟的地獄火戰役來說是無價的。', `MaleText_loc7`='Punta de Expedición es uno de los peores lugares donde te pueden destinar, pero es vital para la defensa de Bastión del Honor. La información que conseguimos aquí y los combates que libran nuestros soldados contra la Legión y los orcos de Zeth''Gor son muy útiles para la campaña de Fuego Infernal de la Alianza.' WHERE `ID`=18772;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벌써 이곳의 일을 돕고 있다는 얘기는 들었소.$B$B잘하셨소. 우리 일을 도와달라고 당신을 설득해야 하나 걱정하던 참이었는데 말이오.', `MaleText_loc4`='我听说你已经在这里发挥作用了。$B$B太好了。我还担心我们得去劝你帮忙呢。', `MaleText_loc5`='我聽說你已經開始在這附近盡一份力了。$B$B很好。我擔心我們得要〝說服〞你來幫忙。', `MaleText_loc7`='He oído que has decidido echar una mano por aquí.$B$BBien. Tenía miedo de que fuera necesario ''convencerte'' para que nos ayudaras.' WHERE `ID`=18773;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1로부터;으로부터; 음침하고 오싹한 목소리가 울려 퍼집니다...', `MaleText_loc4`='%s发出一种低沉、让人毛骨悚然的声音。', `MaleText_loc5`='一股來自%s的深沉、令人寒顫的聲音回響四周...', `MaleText_loc7`='Una voz tenebrosa y profunda surge de %s...' WHERE `ID`=18774;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n! 감히 내 장난감을 가지고 놀다니!', `MaleText_loc4`='你胆敢把我的玩具视若儿戏，$n！', `MaleText_loc5`='你竟敢玩弄我的玩物，$n!', `MaleText_loc7`='¡¿Cómo te atreves a toquetear mis juguetes, $n?!' WHERE `ID`=18775;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 성채의 오크들이 네놈의 피를 마시고 살을 뜯어 먹을 것이다!', `MaleText_loc4`='我堡垒中的兽人将吃你的肉，喝你的血！', `MaleText_loc5`='我堡壘裡的獸人將會喝你的血並且狼吞虎嚥的把你吃光!', `MaleText_loc7`='¡Los orcos de mi ciudadela te devorarán y beberán tu sangre!' WHERE `ID`=18776;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하하하!', `MaleText_loc4`='哈哈哈哈！', `MaleText_loc5`='哈哈哈哈哈!', `MaleText_loc7`='¡Ja, ja, ja, ja, ja!' WHERE `ID`=18777;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 잃어버린 주문을 되찾을 시간이오!', `MaleText_loc4`='现在去找回遗失的咒语吧！', `MaleText_loc5`='現在馬上去取回這些遺失的文字!', `MaleText_loc7`='Ahora, a recuperar las palabras perdidas.' WHERE `ID`=18778;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두 개의 기둥 역할을 하는 뼈 사이에 팽팽하게 펼쳐진 가죽은 서쪽에 있는 얼라이언스의 실바나르와 생명의 숲의 주요 수호자를 대비하라는 신호입니다.', `MaleText_loc4`='在骨架之间紧绷着的毛皮上写着的信息主要是召集军队以对抗西面的联盟希尔瓦纳与活木林的驻军。', `MaleText_loc5`='拉緊在骨頭之間延展的皮是一個號召對抗聯盟的希爾瓦納主要防衛者和西方的生命之林的信號。', `MaleText_loc7`='La piel tensada entre los huesos es una llamada a la lucha contra los defensores de la Alianza de Sylvanaar y la Arboleda Viviente al oeste.' WHERE `ID`=18779;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='반가워요. 저는 아지미라고 해요! 과일과 식수를 팔려고 자주 외출하지요. 혹시 배가 고프거나 목이 마르지는 않으세요?', `FemaleText_loc4`='你好啊，我是阿兹米！我经常在这里出售新鲜的水果和水。你饿了吗，或是有点渴？', `FemaleText_loc5`='真高興見到你，我是阿茲米!我經常到這裡販賣新鮮的水果和水。你會餓嗎，還是覺得口渴?', `FemaleText_loc7`='¡Saludos, soy Azimi! Suelo dar una vuelta por aquí fuera para vender a los guerreros fruta fresca y agua. ¿Tienes hambre? ¿Y sed?' WHERE `ID`=18780;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 현상 수배 전단을 읽습니다.', `MaleText_loc4`='%s开始阅读布告牌。', `MaleText_loc5`='%s開始閱讀懸賞告示。', `MaleText_loc7`='%s lee el cartel de Se busca.' WHERE `ID`=18781;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='투덜거리던 %s|1이;가; 현상 수배 전단에서 돌아서더니 모닥불 옆의 따뜻한 자리로 돌아갑니다.', `MaleText_loc4`='%s嘟囔着从悬赏牌前走开，回到了温暖的篝火旁。', `MaleText_loc5`='咕噥著，%s轉身離開那些懸賞告示，返回他位於火旁的溫暖位置。', `MaleText_loc7`='Con un gruñido, %s se aleja del cartel de Se busca y vuelve a su sitio cerca del fuego.' WHERE `ID`=18782;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='체, 내가 쓸데없는 잡담이나 하고 있을 만큼 한가해 보이나?$B$B응?$B$B용건이 있으면 빨리 말하게. 오우거들을 해치워야 한단 말이야!', `MaleText_loc4`='呸！你看我有时间闲聊吗？$B$B有吗？$B$B快点去做你的工作。这里还有很多食人魔要杀呢！', `MaleText_loc5`='嗯!我看起來像是有時間無所事事閒扯的人嗎?$B$B我是嗎?$B$B快去做你的正事。去殺掉那裏的巨魔!', `MaleText_loc7`='¡Bah! ¿Te parece que tengo tiempo para cháchara?$B$B¿Te lo parece?$B$BDate prisa en explicarme lo que quieres. ¡Hay ogros que matar!' WHERE `ID`=18783;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 펼쳐진 가죽에 적혀 있는 내용은 아직 당신이 감당할 수 없는 임무를 요구합니다.$B$B나중에 다시 확인하는 것이 좋겠습니다.', `MaleText_loc4`='铺开的毛皮上写着一些悬赏工作的内容，而你现在恐怕还不够资格。$B$B你应该稍后再来看看。', `MaleText_loc5`='這裡這片延展的皮上所著述的那些話語需要某種你不認為你有十足把握的東西。$B$B你應該晚點查一下之前的紀錄。', `MaleText_loc7`='Las palabras pintadas en la piel tensada te proponen una misión para la que crees que no estás $gpreparado:preparada; todavía.$B$BVuelve más tarde.' WHERE `ID`=18784;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하십니까. 안퀴라즈 전쟁 준비 때문에 오신 것이겠지요? 현재 많은 도움이 필요한 상황입니다.$B$B이번 준비는 곧 안퀴라즈의 실리시드와 그 주인들을 상대로 벌일 전쟁에 대비하고자 호드와 얼라이언스가 협동해서 펼치는 작전입니다. 우리는 오그리마의 정기의 골짜기에서 전쟁 물자가 될만한 물건들을 모으고 있는데, 그대가 좀 도와주셨으면 합니다.$B$B사령관님을 뵙고 이번 일에 당신이 어떤 도움이 될 수 있을지 얘기를 들어보시는 게 어떻겠습니까?', `FemaleText_loc4`='嗨，$C。我想你是为安其拉之战而来的吧。我们急需帮助。$B$B部落和联盟必须携手对抗安其拉异种虫类大军和它们的主人。在奥格瑞玛的精神谷，我们正在收集原料以赶制战争物资，收集工作需要你的帮助。$B$B你可以跟我们的指挥官谈谈吗？', `FemaleText_loc5`='歡迎，$c。我相信你到這裡來查詢有關於安其拉戰爭努力的成果。我們會需要很多幫助。$B$B戰爭努力的成果是部落與聯盟之間聯合的成就，以準備對抗即將到來的一場與異種以及他們主人的戰爭。在奧格瑪的精神谷，我們收集許許多多貨物去製造戰爭裝備，而這些收集的任務就是我們需要你幫助的事。$B$B我能說服你去與我們的指揮官談談關於需要幫忙的事嗎?', `FemaleText_loc7`='Hola, $c. Supongo que estás aquí para preguntar por el esfuerzo de guerra de Ahn''Qiraj. Vamos a necesitar mucha ayuda.$B$BEl esfuerzo de guerra es un sacrificio común de la Horda y la Alianza para la lucha contra los silítidos y sus amos de Ahn''Qiraj. En el Valle de los Espíritus de Orgrimmar estamos recolectando todo lo que podemos para crear armamento; para esas tareas de recolección es para lo que necesitamos tu ayuda.$B$B¿Querrías hablar con el comandante sobre esto?' WHERE `ID`=18785;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='반갑습니다. 안퀴라즈 전쟁 준비 때문에 오셨기를 바랍니다. 현재 많은 도움이 필요한 상황입니다.$B$B이번 준비는 곧 안퀴라즈의 실리시드와 그 주인들을 상대로 벌일 전쟁에 대비하고자 호드와 얼라이언스가 협동해서 펼치는 작전입니다. 아이언포지의 군사 지구에서 전쟁 물자가 될 만한 물건을 모으고 있는데, 당신이 좀 도와주셨으면 좋겠습니다.$B$B사령관님을 뵙고 이번 일에 당신이 어떤 도움이 될 수 있을지 얘기를 들어보시는 게 어떻겠습니까?', `FemaleText_loc4`='很高兴见到你，$C。我想你是为安其拉一战而来的吧。我们急需帮助。$B$B部落和联盟必须携手对抗安其拉异种虫类大军和它们的主人。在铁炉堡的军事区，我们正在收集原料以赶制战争物资，收集工作需要你的帮助。$B$B你可以跟我们的指挥官谈谈吗？', `FemaleText_loc5`='很高興見到你，$c。我希望你在這裡調查關於安其拉戰爭的努力成果。我們會需要很多幫助。$B$B戰爭的努力成果是聯盟與部落間一次團結的成就，以準備對抗即將到來的一場與異種及他們在安其拉的主人的戰爭。在鐵爐堡軍事區，我們收集各式各樣貨物來製造我們的戰爭裝備，而我們需要你幫忙的就是這些收集任務。$B$B我能說服你去與我們的指揮官談談關於要進行的事嗎?', `FemaleText_loc7`='Hola, $c. Espero que estés aquí para preguntar por el esfuerzo de guerra de Ahn''Qiraj. Vamos a necesitar mucha ayuda.$B$BEl esfuerzo de guerra es un sacrificio común de la Alianza y la Horda para la lucha contra los silítidos y sus amos de Ahn''Qiraj. En la Sala Militar de Forjaz estamos recolectando todo lo que podemos para crear armamento; para esas tareas de recolección es para lo que necesitamos tu ayuda.$B$B¿Querrías hablar con el comandante sobre esto?' WHERE `ID`=18786;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 당신 같은 영웅이라면 알터랙 계곡 전투보다 더 중요한 전투에서 능력을 발휘하는 것이 좋겠소.', `MaleText_loc4`='像你这样伟大的英雄不应该把才能埋没在奥特兰克山谷里，$n。', `MaleText_loc5`='像你這種水準的英雄不應該在奧特蘭克山谷浪費他們的才華，$n。', `MaleText_loc7`='Los héroes de tu calibre no deberían malgastar su talento en el Valle de Alterac, $n.', `FemaleText_loc1`='$n, 당신 같은 영웅이라면 알터랙 계곡 전투보다 더 중요한 전투에서 능력을 발휘하는 것이 좋겠소.', `FemaleText_loc4`='像你这样伟大的英雄不应该把才能埋没在奥特兰克山谷里，$n。', `FemaleText_loc5`='像你這種水準的英雄不應該在奧特蘭克山谷浪費他們的才華，$n。', `FemaleText_loc7`='Los héroes de tu calibre no deberían malgastar su talento en el Valle de Alterac, $n.' WHERE `ID`=18787;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대와 같은 $r|1이;가; 실바나르의 번영을 위해 헌신하는 모습을 보니 기쁘군. 우리는 이곳에서 아주 짧은 시간 많은 일을 했소. 하지만, 우리를 포위한 군대가 우리의 삶을 위협하고 있소.$B$B어떻소? $c|1이여;여;, 우리를 도와주겠소?', `MaleText_loc4`='很高兴看到一个像你这样的$r。你为希尔瓦纳的安宁做出了贡献，我们在这里时间虽然短，但是却做了很多。不过，周围的敌对势力仍然威胁着我们的生命。$B$B我想听听你要说什么。说出你的想法，$c。', `MaleText_loc5`='很高興看見一位$r，例如你本人一樣，為了希爾瓦納的安寧有所奉獻。我們在非常短的時間內做了很多事，但是圍繞我們的力量卻威脅著我們的生活模式。$B$B我會傾聽你說得話。說出你的想法吧，$c。', `MaleText_loc7`='Me alegro de ver a $gun:una; $r como tú ayudando para que Sylvanaar sea un lugar mejor. Hemos hecho mucho en muy poco tiempo, pero las fuerzas que nos rodean amenazan nuestra forma de vida.$B$BMe gustaría escuchar lo que tienes que decir. Habla, $c.' WHERE `ID`=18788;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='탄약이나 그 밖의 물건을 찾고 있으신가요? 베이베이를 위해 모아둔 식량도 좀 있는데 혹시 필요하지 않으신가요?', `FemaleText_loc4`='你在寻找弹药或其他供给吗？我这里有些为贝贝收集的多余的食物，你应该也有需要的。', `FemaleText_loc5`='你正在尋找彈藥或是其他補給品?我也有些為貝貝收集的額外食物，就在這裡，你應該會需要一點吧。', `FemaleText_loc7`='¿Buscas munición? ¿Otros materiales? También tengo comida para Beibei si la necesitas.' WHERE `ID`=18789;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 점점 커집니다!', `MaleText_loc4`='%s的体形变大了！', `MaleText_loc5`='%s變大了!', `MaleText_loc7`='¡%s crece!' WHERE `ID`=18790;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='세나리온 야영지에 오신 것을 환영합니다, $n. 그대가 필요로 하는 물자를 돈을 받고 제공하라는 명령을 받았으니 둘러보도록 하십시오.', `FemaleText_loc4`='欢迎来到塞纳里奥庇护所，$n。我向你出售基本的供给品，你应该会需要它们的。', `FemaleText_loc5`='歡迎到塞納里奧避難所，$n。我接到指示要提供基本的補給品供你購買，你應該會有需要。', `FemaleText_loc7`='$gBienvenido:Bienvenida; al Refugio Cenarion, $n. Tengo órdenes de ofrecerte material básico si lo necesitas.' WHERE `ID`=18791;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악! 내 몸에 불이 붙었어!!!', `MaleText_loc4`='我着火了！！', `MaleText_loc5`='我著火了!!', `MaleText_loc7`='¡¡ME QUEMO!!', `FemaleText_loc1`='악! 내 몸에 불이 붙었어!!!', `FemaleText_loc4`='我着火了！！', `FemaleText_loc5`='我著火了!!', `FemaleText_loc7`='¡¡ME QUEMO!!' WHERE `ID`=18792;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 또 내 몸에 불이 붙었어!!!', `MaleText_loc4`='我又着火了！！', `MaleText_loc5`='我又著火了!!', `MaleText_loc7`='¡¡ME QUEMO!! ¡¡OTRA VEZ!!', `FemaleText_loc1`='이런 또 내 몸에 불이 붙었어!!!', `FemaleText_loc4`='我又着火了！！', `FemaleText_loc5`='我又著火了!!', `FemaleText_loc7`='¡¡ME QUEMO!! ¡¡OTRA VEZ!!' WHERE `ID`=18793;
