UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아침이 되면 좀 아프겠지...', `MaleText_loc4`='早上的时候会很痛的。', `MaleText_loc5`='到了早上這個應該會很痛。', `MaleText_loc7`='Esto te dolerá mañana por la mañana.', `FemaleText_loc1`='아침이 되면 좀 아프겠지...', `FemaleText_loc4`='早上的时候会很痛的。', `FemaleText_loc5`='到了早上這個應該會很痛。', `FemaleText_loc7`='Esto te dolerá mañana por la mañana.' WHERE `ID`=18797;
