UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 시키는 대로 한다. 그만 때려.', `MaleText_loc4`='我会听鸟人的吩咐。不要再啄我了。', `MaleText_loc5`='無論我做了什麼怪異的需求。 請停止傷害。', `MaleText_loc7`='Haré lo que quieras, pajarito. ¡Solo para de hacerme daño!' WHERE `ID`=18855;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<이 호랑이는 무장을 하고 안장을 얹은 것으로 봐서 전투용입니다. 이렇게 설명하지 않아도 우스꽝스러운 품새로 봐서 충분히 아실 수 있겠죠?>', `MaleText_loc4`='<它是一头巨大的、全副武装的、带着鞍具的攻击型猛兽，若是它开口说话的话，就显得更傻了。>', `MaleText_loc5`='<它是一隻巨大，身穿護甲，披上鞍具的攻擊貓。就算他不會說話不也是夠蠢了嗎? >', `MaleText_loc7`='<Es un gato gigante con armadura, riendas y silla de montar. ¿No te parece ya lo suficientemente gracioso? ¿También quieres que hable?>' WHERE `ID`=18856;
