UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니, 아직은 안 돼! 내가 준비되기 전에는 멈추면 안 돼! 계속해!', `MaleText_loc4`='休想！我没让你们休息之前，就继续练习练习再练习！继续！', `MaleText_loc5`='噢不，你不行!當我準備好讓你停止練習時，你才能停止練習! 繼續!', `MaleText_loc7`='¡Ah, no! Pararás de entrenar cuando yo te diga que puede parar de entrenar. ¡SIGUE!' WHERE `ID`=18859;
