UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 신경 쓰지 말게. 그거라면 이 고통을 없애줄 거야.', `MaleText_loc4`='请不要介意，也许这样能驱除头痛。', `MaleText_loc5`='請別在意要是我做了什麼事。 也許這可以擺脫這次的頭痛。', `MaleText_loc7`='No me importa. Puede que se me quite el dolor de cabeza.' WHERE `ID`=18863;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$c|1이여;여;, 미안하지만 오직 마법사만이 차원문 마법을 배울 수 있답니다.', `FemaleText_loc4`='只有法师可以学习传送魔法，$c。', `FemaleText_loc5`='只有法師才能學習傳送門的法術，$c。', `FemaleText_loc7`='Solo un mago puede aprender la magia de los portales, $c.' WHERE `ID`=18864;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신은 마법사로군요... 차원문 마법을 배우고 싶습니까?', `FemaleText_loc4`='法师……你想学习传送魔法，是吗？', `FemaleText_loc5`='一個法師...你想要學習傳送門的法術，是嗎?', `FemaleText_loc7`='Un mago... ¿Quieres aprender la magia de los portales?' WHERE `ID`=18865;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 호박은 정말 먹음직스러워요! 내가 한입 베어 문다고 눈치챌 자는 없을 거예요...', `MaleText_loc4`='This pumpkin sure looks succulent! Nobody will notice if I take a small bite... [PH]', `MaleText_loc5`='這個南瓜看起來肯定香甜多汁!沒人會注意到要是我咬了一小口... [PH]', `MaleText_loc7`='¡Esta calabaza tiene un aspecto suculento! Nadie se dará cuenta si le doy un mordisquito... [PH]' WHERE `ID`=18866;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='언더시티의 왕립 연금술 학회는 이곳 아웃랜드의 오크 동맹들을 돕고자 하네. 우리 호드 연합의 결속을 강화하고 새로운 종족이나 혼합물 같은 연구 대상을 찾을 기회이지.$B$B예를 들면... 독 같은 거 말일세.', `FemaleText_loc4`='幽暗城的皇家药剂师协会渴望去外域帮助我们的兽人盟友。这是个加强我们之间联系的好机会，而且我们还能借此机会找到新的标本和混合物。$B$B混合物……例如毒药。', `FemaleText_loc5`='幽暗城的皇家藥劑師學會積極要援助我們在外域的獸人盟友。這是一個強化我們的團結性以及發現可以進行研究的新種類及混合物的機會。$B$B混合物...比如說毒藥。', `FemaleText_loc7`='La Sociedad Real de Boticarios de Entrañas está dispuesta a ayudar a nuestros aliados orcos aquí, en Terrallende. Es una oportunidad de estrechar nuestros lazos y de encontrar nuevos especímenes y compuestos para nuestros estudios.$B$BCompuestos como... venenos.' WHERE `ID`=18867;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 내 호박을 훔쳐간 거야?! 이 악당, 도망 못 간다!', `MaleText_loc4`='Who''s stealing my pumpkins?! You won''t get away with this, you rascal! [PH]', `MaleText_loc5`='誰正在偷我的南瓜?!你不會跑不掉的，你這個無賴! [PH]', `MaleText_loc7`='¡¿Quién me roba las calabazas?! ¡No te saldrás con la tuya, granuja! [PH]' WHERE `ID`=18868;
