UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; $n에게 버섯 포자를 뿌립니다.', `MaleText_loc4`='%s向$n扔了块蘑菇孢子。', `MaleText_loc5`='%s對$n投擲一個蘑菇孢子。', `MaleText_loc7`='%s tira una espora de champiñón a $n.' WHERE `ID`=18913;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌려서 말하자면 원래는 백사장 야영지에 들를 계획이 없었습니다. 물건이 배달되기만을 기다리는 손님들이 있는데 이렇게 지체돼서야 제때 갈 수 있을지 의문이로군요.', `MaleText_loc4`='说得好听点，白沙岗哨是一个意外的耽搁。我的客户们还指望着我来运送货物，不过我有些怀疑，再有这样的耽搁的话，我是否可以及时完成任务。', `MaleText_loc5`='白沙崗哨對我來說就像是個意外的一站，溫和的放下它。我的客戶正指望我運送達我的貨品，我開始懷疑我是否可以在所有的耽擱下把東西即時送達。', `MaleText_loc7`='El Campamento del Tramo Blanco es una parada que no estaba en mis planes, por decirlo suavemente. Mis clientes esperan que haga las entregas a tiempo y estoy empezando a pensar que va a ser imposible con todas estas paradas imprevistas.' WHERE `ID`=18914;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제발 좀 열지 마세요! 제발!$B$B제가 원하는 장소에 오우거들이 제대로 가둬 놓았다니까요.', `FemaleText_loc4`='嘿，不要打开那些笼子，好吗？$B$B我就想让食人魔把我放在这个笼子里。', `FemaleText_loc5`='喂，不要打開籠子!好嗎?$B$B那些巨魔將我放在我要他們放的地方了。', `FemaleText_loc7`='¡Eh, no abras las jaulas!$B$BEstos ogros me tienen justo donde quiero.' WHERE `ID`=18915;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지옥불 반도의 먼지와 열이 상당히 자극적이라고 들었지... 잘은 모르겠지만 난 아직 살아 있고 존경하는 내 동맹들을 믿을 걸세.', `MaleText_loc4`='有人告诉我，地狱火半岛的尘土和炎热是非常恼人的……我不知道是不是那样，但是我会相信我那些值得敬重的、而且仍然活着的盟友。', `MaleText_loc5`='我聽說地獄火半島的灰塵和熱度十分令人煩燥...我不知道，不過我會相信我那受人尊敬，還活著著的生命，盟友。', `MaleText_loc7`='Tengo entendido que el polvo y el calor de la Península del Fuego Infernal son muy irritantes... No estoy seguro, pero confiaré en mis queridos y todavía vivos aliados.' WHERE `ID`=18916;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원소 가죽세공을 취소하고 싶습니다!', `MaleText_loc4`='我想要遗忘元素制皮专精！', `MaleText_loc5`='我想要遺忘元素製皮!', `MaleText_loc7`='¡Deseo olvidar lo aprendido sobre la peletería elemental!', `FemaleText_loc1`='원소 가죽세공을 취소하고 싶습니다!', `FemaleText_loc4`='我想要遗忘元素制皮专精！', `FemaleText_loc5`='我想要遺忘元素製皮!', `FemaleText_loc7`='¡Deseo olvidar lo aprendido sobre la peletería elemental!' WHERE `ID`=18917;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하십니까, $C|1이여;여;. 도와주셔서 감사합니다만 이 문은 열지 말아 주십시오.', `FemaleText_loc4`='嗨，谢谢帮忙。但是请别打开笼子。', `FemaleText_loc5`='嗨。謝謝幫助。但是請不要打開籠子。', `FemaleText_loc7`='Hola. Gracias por tu ayuda, pero no abras la jaula, por favor.' WHERE `ID`=18918;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네, 멍청한 오우거들이 자물쇠를 잠그는 걸 잊어버렸지요. 하지만, 바로 제가 원하는 바이니 열지만 말아 주십시오.', `FemaleText_loc4`='是的，食人魔太愚蠢了，他们忘记锁我的笼子了。但是那正是我想要的，请不要再打开它了。', `FemaleText_loc5`='是的，巨魔就是這麼的笨到他們忘記幫我的籠子上鎖。但是那正好就是我為何喜歡它的原因，因此請不要再打開它。', `FemaleText_loc7`='Sí, los ogros son tan estúpidos que olvidaron cerrar mi jaula, pero a mí me conviene que esté así; por favor, no la vuelvas a abrir.' WHERE `ID`=18919;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제발, 열지 마세요. 오우거들 중에 눈치채는 녀석이 있을지도 모른단 말입니다!', `FemaleText_loc4`='不，不要打开笼子。他们会注意到的！', `FemaleText_loc5`='不。不要打開籠子。他們其中的一個可能會注意到!', `FemaleText_loc7`='No. No abras la jaula. ¡Puede que se den cuenta!' WHERE `ID`=18920;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제발 우리 문을 열지 말아 주세요. 고맙습니다.', `FemaleText_loc4`='请把笼门关上。谢谢。', `FemaleText_loc5`='請不要打開籠子的門。感謝。', `FemaleText_loc7`='Por favor, deja la puerta de la jaula cerrada. Gracias.' WHERE `ID`=18921;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='거기 잠시만요, 여기 입구 근처 위쪽입니다. 네, 여기 우리 안이에요. 어서 이리 좀 와주십시오!', `FemaleText_loc4`='喂，$r，到入口这里来。我在笼子里。快点！', `FemaleText_loc5`='喂!噓!$r，上來入口附近。我就在籠子裡。快點!', `FemaleText_loc7`='Pssst, $r, aquí, cerca de la entrada. Estoy en la jaula. ¡Date prisa!' WHERE `ID`=18922;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원소 가죽세공을 취소하는 것은 그리 간단한 일이 아니랍니다. 원소 가죽세공을 취소하면 원소 가죽세공의 제조법 또한 모두 사라집니다!', `MaleText_loc4`='遗忘元素制皮可不是说着玩的。如果你选择放弃它，你同样会忘记所有需要元素制皮专精的图样！', `MaleText_loc5`='遺忘元素製皮不是件容易的事。如果你選擇遺忘它，你也會忘記所有需要元素製皮的方法!', `MaleText_loc7`='Olvidar la peletería elemental no es algo que deba tomarse a la ligera. Si lo haces, olvidarás también todas las recetas que requieran peletería elemental.', `FemaleText_loc1`='원소 가죽세공을 취소하는 것은 그리 간단한 일이 아니랍니다. 원소 가죽세공을 취소하면 원소 가죽세공의 제조법 또한 모두 사라집니다!', `FemaleText_loc4`='遗忘元素制皮可不是说着玩的。如果你选择放弃它，你同样会忘记所有需要元素制皮专精的图样！', `FemaleText_loc5`='遺忘元素製皮不是件容易的事。如果你選擇遺忘它，你也會忘記所有需要元素製皮的方法!', `FemaleText_loc7`='Olvidar la peletería elemental no es algo que deba tomarse a la ligera. Si lo haces, olvidarás también todas las recetas que requieran peletería elemental.' WHERE `ID`=18923;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 종족에게 약간 우호적 이상의 평판을 얻기 전까지는 매타조를 구입할 수 없습니다.', `FemaleText_loc4`='除非你在我们族人中的声望达到友好以上的程度，否则不能购买陆行鸟。', `FemaleText_loc5`='你在這裡將無法購買陸行鷹直到你證明自己對我們族人最少達到友好的境界。', `FemaleText_loc7`='No podrás comprar ningún halcón zancudo hasta que mi pueblo no te considere, al menos, amistoso.' WHERE `ID`=18924;
