UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 오크들은 아웃랜드에 자신들의 영토를 갖고 싶어합니다! 그들이 제게 얼마나 충성했는지를 듣고 나면 질투심에 절 죽이고 싶을지도 몰라요!', `MaleText_loc4`='这些兽人肯定非常渴望在外域扩张势力！如果我告诉你他们给了我多少银币，你一定会嫉妒地掐死我！', `MaleText_loc5`='這些獸人一定真的很渴望獲取外域的支配權!如果我告訴你他們為了我的忠誠付出了多少，你會因妒忌而殺了我!', `MaleText_loc7`='¡Estos orcos deben de tener muchas ganas de hacer suyas estas tierras de Terrallende! Si te dijera cuánto pagan por mi lealtad, me matarías de la envidia.' WHERE `ID`=18926;
