UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말로 가죽세공 기술과 그에 관련된 제조법을 모두 취소하시겠습니까?', `MaleText_loc4`='你真的想遗忘你的制皮专业并失去所有相关的图样吗？', `MaleText_loc5`='你真的想要忘掉你的製皮專業，並且失去所有相關訣竅嗎?', `MaleText_loc7`='¿De verdad quieres olvidar tu especialización en peletería y perder todas las recetas asociadas?', `FemaleText_loc1`='정말로 가죽세공 기술과 그에 관련된 제조법을 모두 취소하시겠습니까?', `FemaleText_loc4`='你真的想遗忘你的制皮专业并失去所有相关的图样吗？', `FemaleText_loc5`='你真的想要忘掉你的製皮專業，並且失去所有相關訣竅嗎?', `FemaleText_loc7`='¿De verdad quieres olvidar tu especialización en peletería y perder todas las recetas asociadas?' WHERE `ID`=18928;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 자신의 힘을 끌어내려고 필사적으로 노력합니다!', `MaleText_loc4`='%s开始在绝望中释放他的力量！', `MaleText_loc5`='%s開始不顧一切釋放他的力量!', `MaleText_loc7`='%s comienza a liberar su poder, desesperado.' WHERE `ID`=18929;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돈만 내면 매타조 타는 법을 가르쳐 주도록 하겠소.', `MaleText_loc4`='如果你有金币，我就能教你怎么骑陆行鸟。', `MaleText_loc5`='如果你有黃金，我就能教導你如何騎乘陸行鷹。', `MaleText_loc7`='Si tienes dinero suficiente, puedo enseñarte a montar un halcón zancudo.' WHERE `ID`=18930;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='매타조 타는 법을 배우려면 블러드 엘프에게 약간 우호적 평판을 얻어야 합니다.', `MaleText_loc4`='你必须在血精灵一族中达到友好声望，我才能教你骑术，$C。', `MaleText_loc5`='在我教你騎術之前，你必須與血精靈達到友好的聲望才行，$c。', `MaleText_loc7`='Es necesario que los elfos de sangre te consideren $gamistoso:amistosa; para que pueda enseñarte una habilidad de equitación, $c.' WHERE `ID`=18931;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='매타조 타는 법을 배우려면 블러드 엘프에게 확고한 동맹 평판을 얻어야 합니다.', `MaleText_loc4`='你必须在血精灵一族中达到崇拜声望，我才能教你骑术，$C。', `MaleText_loc5`='在我教你騎術之前，你必須與血精靈達到崇拜的聲望才行，$c。', `MaleText_loc7`='Es necesario que los elfos de sangre te consideren $gun exaltado:una exaltada; para que pueda enseñarte una habilidad de equitación, $c.' WHERE `ID`=18932;
