UPDATE `locales_broadcast_text` SET `MaleText_loc1`='망치 제작 기술을 취소하고 싶습니다!', `MaleText_loc4`='我想要遗忘铸锤专精！', `MaleText_loc5`='我想要遺忘錘類鍛造!', `MaleText_loc7`='¡Deseo olvidar lo aprendido sobre la forja de martillos!', `FemaleText_loc1`='망치 제작 기술을 취소하고 싶습니다!', `FemaleText_loc4`='我想要遗忘铸锤专精！', `FemaleText_loc5`='我想要遺忘錘類鍛造!', `FemaleText_loc7`='¡Deseo olvidar lo aprendido sobre la forja de martillos!' WHERE `ID`=18990;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='망치 제작 기술을 취소하는 것은 그리 간단한 일이 아니랍니다. 망치 제작 기술을 취소하면 망치 제작 기술에 관련된 모든 제조법이 사라집니다!', `MaleText_loc4`='遗忘铸锤技能可不是说着玩的。如果你选择放弃它，你同样会忘记所有需要铸锤技能的图样！', `MaleText_loc5`='遺忘你的錘類鍛造技能不是件容易的事。如果你選擇遺忘，你將會失去所有製作錘類鍛造需要的方法!', `MaleText_loc7`='Olvidar la forja de martillos no es algo que deba tomarse a la ligera. Si lo haces, olvidarás también todas las recetas que requieran forja de martillos.', `FemaleText_loc1`='망치 제작 기술을 취소하는 것은 그리 간단한 일이 아니랍니다. 망치 제작 기술을 취소하면 망치 제작 기술에 관련된 모든 제조법이 사라집니다!', `FemaleText_loc4`='遗忘铸锤技能可不是说着玩的。如果你选择放弃它，你同样会忘记所有需要铸锤技能的图样！', `FemaleText_loc5`='遺忘你的錘類鍛造技能不是件容易的事。如果你選擇遺忘，你將會失去所有製作錘類鍛造需要的方法!', `FemaleText_loc7`='Olvidar la forja de martillos no es algo que deba tomarse a la ligera. Si lo haces, olvidarás también todas las recetas que requieran forja de martillos.' WHERE `ID`=18991;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 광분하여 공격합니다.', `MaleText_loc4`='%s带着绝望的愤怒开始攻击。', `MaleText_loc5`='%s暴怒發狂的進攻。', `MaleText_loc7`='%s golpea con una furia desesperada.' WHERE `ID`=18992;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난... 나는 죽었는데... 끔찍한 고통에 시달리다가... 암흑이 나를 집어삼켰는데... 혹시 내가 보이나?', `MaleText_loc4`='我……我已经死了……我承受了这么多痛苦……被卷入了黑暗……你能看到我吗，$r？', `MaleText_loc5`='我...我已經死了...那麼的痛苦...被吞沒在黑暗裡...你看得見我嗎，$r?', `MaleText_loc7`='He... He muerto... Tanto dolor... en la oscuridad... ¿Puedes verme, $r?' WHERE `ID`=18993;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모든 게 잘 돌아가고 있다! 조만간 그 배신자의 뼈를 밟아 부술 날이 올 것이다!', `MaleText_loc4`='事情进行得很顺利！不久之后这些背叛者的尸骨就将被我们狠狠地踩在脚下。', `MaleText_loc5`='事情進行得很好!很快的我們腳下就會踩著背叛者的骨頭了!', `MaleText_loc7`='¡Las cosas marchan bien! ¡Pronto machacaremos los huesos del Traidor bajo nuestros pies!' WHERE `ID`=18994;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음 지옥불정령 부대를 내보낼 준비를 하라!', `MaleText_loc4`='准备发射下一波地狱火！', `MaleText_loc5`='準備發動下一波的煉獄火!', `MaleText_loc7`='¡Preparad la próxima oleada de infernales!' WHERE `ID`=18995;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불타는 군단의 영광으로 하늘이 무너질 것이다!', `MaleText_loc4`='天空会随着燃烧军团的荣耀而坍塌！', `MaleText_loc5`='天空將與軍團的榮耀一起下降!', `MaleText_loc7`='¡El cielo caerá bajo la gloria de la Legión!' WHERE `ID`=18996;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음 공격에 대비해야 한다! 그 배신자는 죽음을 맞이하게 될 것이다!', `MaleText_loc4`='我们必须准备好下一次进攻！！背叛者必将被消灭！', `MaleText_loc5`='我們一定要為下一場攻擊作準備!背叛者將會被毀滅!', `MaleText_loc7`='¡Preparémonos para el siguiente ataque! ¡El Traidor será destruido!' WHERE `ID`=18997;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 근처의 암컷을 돕기 위해 뛰어갑니다!', `MaleText_loc4`='%s冲过去帮助附近的一头母羊。', `MaleText_loc5`='%s急忙去幫助一隻附近的雌鹿!', `MaleText_loc7`='%s corre en ayuda de un cervatillo cercano.' WHERE `ID`=18998;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 불타는 군단은 모든 것을 정복할 것이다! 적들은 화염에 휩싸인 채 우리의 위대한 힘 아래 굴복할 것이다!', `MaleText_loc4`='我们会征服一切，因为我们是燃烧军团！我们的敌人会在火焰中被融毁，被我们的力量所碾碎！', `MaleText_loc5`='我們將征服一切，因為我們是燃燒軍團!我們的敵人會在火焰裡燃燒殆盡，並且在我們的力量下粉身碎骨!', `MaleText_loc7`='¡Lo conquistaremos todo, pues somos la Legión Ardiente! ¡Nuestros enemigos serán consumidos por las llamas y aplastados bajo nuestro poder!' WHERE `ID`=18999;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무도 불타는 군단의 길을 막지 못한다! 이 세계는 우리 것이다!', `MaleText_loc4`='没人可以和燃烧军团抗衡！这个世界是我们的！', `MaleText_loc5`='沒有人能夠對抗燃燒軍團!這個世界是我們的!', `MaleText_loc7`='¡Nadie puede enfrentarse a la Legión Ardiente! ¡Este mundo es nuestro!' WHERE `ID`=19001;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 존재는 아무런 의미가 없다! 불타는 군단의 압도적인 승리만이 중요할 뿐이다!', `MaleText_loc4`='你们的努力全是徒劳的！只有燃烧军团全面的胜利才有意义！', `MaleText_loc5`='你毫無意義!對於軍團來說只有絕對的勝利!', `MaleText_loc7`='¡No tienes sentido! ¡Lo único que importa es la victoria absoluta de la Legión!' WHERE `ID`=19002;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최고의 조언가를 상대로 잘도 버텨냈군. 허나 그 누구도 붉은 망치의 힘에는 대항할 수 없지. 보아라, 군주 생귀나르를!', `MaleText_loc4`='你们击败了我最强大的顾问……但是没有人能战胜鲜血之锤。出来吧，萨古纳尔男爵！', `MaleText_loc5`='你已經努力的打敗了我的幾位最忠誠的諫言者...但是沒有人可以抵抗血錘的力量。等著看桑古納爾領主的力量吧!', `MaleText_loc7`='Han sobrevivido a algunos de mis mejores consejeros... pero nadie puede resistir el poder del Martillo de Sangre. ¡He aquí Lord Sanguinar!' WHERE `ID`=19003;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카퍼니안, 놈들이 여기 온 것을 후회하게 해 줘라.', `MaleText_loc4`='卡波妮娅会很快解决你们的。', `MaleText_loc5`='卡普尼恩將保證你們不會在這裡停留太久。', `MaleText_loc7`='Capernian se encargará de que su visita sea breve.' WHERE `ID`=19004;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 그 정도 실력이면 수석기술자 텔로니쿠스를 상대해 볼만하겠어.', `MaleText_loc4`='干得不错。看来你们有能力挑战我的首席技师，塔隆尼库斯。', `MaleText_loc5`='做得好，你已經證明你的實力足以挑戰我的工程大師泰隆尼卡斯。', `MaleText_loc7`='Bien hecho. Parecen dignos de probar sus habilidades con mi amo ingeniero Telonicus.' WHERE `ID`=19005;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='암흑의 인도자 탈라드레드를 상대로 얼마나 버틸지 볼까?', `MaleText_loc4`='让我们来看看你们如何面对亵渎者萨拉德雷！', `MaleText_loc5`='了不起。讓我們看看你們這些大膽的狂徒如何反抗扭曲預言家薩拉瑞德的力量!', `MaleText_loc7`='¡Veamos si tienes tanto coraje frente al Ensombrecedor, Thaladred!' WHERE `ID`=19006;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무기 제작 기술을 취소하고 싶습니다!', `MaleText_loc4`='我想要遗忘武器锻造专精！', `MaleText_loc5`='我想要遺忘武器鍛造!', `MaleText_loc7`='¡Deseo olvidar lo aprendido sobre la forja de armas!', `FemaleText_loc1`='무기 제작 기술을 취소하고 싶습니다!', `FemaleText_loc4`='我想要遗忘武器锻造专精！', `FemaleText_loc5`='我想要遺忘武器鍛造!', `FemaleText_loc7`='¡Deseo olvidar lo aprendido sobre la forja de armas!' WHERE `ID`=19007;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무기 제작 기술을 취소하는 것은 그리 간단한 일이 아니랍니다. 무기 제작 기술을 취소하면 무기 제작 기술에 관련된 모든 제조법이 사라집니다!', `MaleText_loc4`='遗忘你的武器铸造技能并不是什么轻松的事。如果你选择放弃，你会忘记所有武器专精相关的图样！', `MaleText_loc5`='遺忘你的武器鍛造技能不是件隨便的事。如果你選擇放棄，你將會失去所有製作武器鍛造需要的方法!', `MaleText_loc7`='Olvidar la habilidad de forja de armas no es algo que se haga a la ligera. ¡Si decides abandonarla, olvidarás todas las fórmulas que necesitan de la forja de armas para crear!', `FemaleText_loc1`='무기 제작 기술을 취소하는 것은 그리 간단한 일이 아니랍니다. 무기 제작 기술을 취소하면 무기 제작 기술에 관련된 모든 제조법이 사라집니다!', `FemaleText_loc4`='遗忘你的武器铸造技能并不是什么轻松的事。如果你选择放弃，你会忘记所有武器专精相关的图样！', `FemaleText_loc5`='遺忘你的武器鍛造技能不是件隨便的事。如果你選擇放棄，你將會失去所有製作武器鍛造需要的方法!', `FemaleText_loc7`='Olvidar la habilidad de forja de armas no es algo que se haga a la ligera. ¡Si decides abandonarla, olvidarás todas las fórmulas que necesitan de la forja de armas para crear!' WHERE `ID`=19008;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 도움을 받으려면 먼저 당신의 무기류 제작 기술을 취소해야 합니다. 여명의 설원의 눈망루 마을에 가서 도움을 받으십시오!', `MaleText_loc4`='你必须首先遗忘你所学的武器锻造专精，我才能帮助你。前往冬泉谷的永望镇寻求帮助吧！', `MaleText_loc5`='在我能幫助你之前，你必須先去遺忘你的武器類型專業。到冬泉谷的永望鎮去尋求協助!', `MaleText_loc7`='Debes olvidar tu especialidad en un tipo de arma antes de que pueda ayudarte. ¡Ve a Vista Eterna, en Cuna del Invierno, y busca ayuda allí!', `FemaleText_loc1`='제 도움을 받으려면 먼저 당신의 무기류 제작 기술을 취소해야 합니다. 여명의 설원의 눈망루 마을에 가서 도움을 받으십시오!', `FemaleText_loc4`='你必须首先遗忘你所学的武器锻造专精，我才能帮助你。前往冬泉谷的永望镇寻求帮助吧！', `FemaleText_loc5`='在我能幫助你之前，你必須先去遺忘你的武器類型專業。到冬泉谷的永望鎮去尋求協助!', `FemaleText_loc7`='Debes olvidar tu especialidad en un tipo de arma antes de que pueda ayudarte. ¡Ve a Vista Eterna, en Cuna del Invierno, y busca ayuda allí!' WHERE `ID`=19009;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방어구 제작 기술을 취소하고 싶습니다!', `MaleText_loc4`='我想要遗忘护甲锻造专精！', `MaleText_loc5`='我想要遺忘護甲鍛造!', `MaleText_loc7`='¡Deseo olvidar lo aprendido sobre la forja de armaduras!', `FemaleText_loc1`='방어구 제작 기술을 취소하고 싶습니다!', `FemaleText_loc4`='我想要遗忘护甲锻造专精！', `FemaleText_loc5`='我想要遺忘護甲鍛造!', `FemaleText_loc7`='¡Deseo olvidar lo aprendido sobre la forja de armaduras!' WHERE `ID`=19010;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방어구 제작 기술을 취소하는 것은 그리 간단한 일이 아니랍니다. 방어구 제작 기술을 취소하면 방어구 제작 기술에 관련된 모든 제조법이 사라집니다!', `MaleText_loc4`='遗忘铸甲技能可不是说着玩的。如果你选择放弃它，你同样会忘记所有需要铸甲技能的图样！', `MaleText_loc5`='遺忘你的護甲鍛造技能不是件隨便的事。如果你選擇放棄，你將會失去所有製作護甲鍛造需要的所有方法!', `MaleText_loc7`='Olvidar la habilidad de forja de armaduras no es algo que se haga a la ligera. ¡Si decides abandonarla, olvidarás todas las fórmulas que necesitan de la forja de armaduras para crear!', `FemaleText_loc1`='방어구 제작 기술을 취소하는 것은 그리 간단한 일이 아니랍니다. 방어구 제작 기술을 취소하면 방어구 제작 기술에 관련된 모든 제조법이 사라집니다!', `FemaleText_loc4`='遗忘铸甲技能可不是说着玩的。如果你选择放弃它，你同样会忘记所有需要铸甲技能的图样！', `FemaleText_loc5`='遺忘你的護甲鍛造技能不是件隨便的事。如果你選擇放棄，你將會失去所有製作護甲鍛造需要的所有方法!', `FemaleText_loc7`='Olvidar la habilidad de forja de armaduras no es algo que se haga a la ligera. ¡Si decides abandonarla, olvidarás todas las fórmulas que necesitan de la forja de armaduras para crear!' WHERE `ID`=19011;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기! 놈을 해치우세요! 파멸의 암호를 되찾아야 해요!', `MaleText_loc4`='那儿！消灭他！必须抢到密码！', `MaleText_loc5`='在那!殺了他!一定要拿回密碼!', `MaleText_loc7`='¡Ahí! ¡Destruidle! ¡Hay que recuperar la clave!' WHERE `ID`=19012;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어리석은 놈들! 절대 파멸의 암호를 차지할 수 없다!', `MaleText_loc4`='蠢货！你永远都别想得到密码！', `MaleText_loc5`='沒禮貌的傻瓜!你絕不會擁有密碼的!', `MaleText_loc7`='¡Semejante insolencia! ¡Nunca tendrás la Clave!' WHERE `ID`=19013;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 파멸의 암호는 우리 것이다!', `MaleText_loc4`='诅咒密码现在属于我们了！', `MaleText_loc5`='毀滅密碼現在屬於我們了!', `MaleText_loc7`='¡Ahora la Clave de Condenación nos pertenece!' WHERE `ID`=19014;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈들은 파멸하리라!', `MaleText_loc4`='你们会被毁灭的！', `MaleText_loc5`='你將會被摧毀!', `MaleText_loc7`='¡Seréis destruidos!' WHERE `ID`=19015;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희가 침략했다는 소식이 주인님 귀에 들어가면 네놈들은 영원히 쫓기는 신세가 되겠지!', `MaleText_loc4`='主人会知道这次可笑的入侵，你将永世被追杀！', `MaleText_loc5`='主人會知道這次入侵。你將永遠被追殺!', `MaleText_loc7`='El maestro sabrá de esta incursión. ¡Te darán caza toda la eternidad!' WHERE `ID`=19016;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알토르, 또 다른 정령사냥꾼의 도움이 필요합니다.', `MaleText_loc4`='我需要另一位灵魂猎手的帮助，阿托尔。', `MaleText_loc5`='我需要另一個幽魂獵手的幫助，阿爾托。', `MaleText_loc7`='Necesito la ayuda de otro espíritu cazador, Ar''tor.', `FemaleText_loc1`='알토르, 또 다른 정령사냥꾼의 도움이 필요해요.', `FemaleText_loc4`='我需要另一位灵魂猎手的帮助，阿托尔。', `FemaleText_loc5`='我需要另一個幽魂獵手的幫助，阿爾托。', `FemaleText_loc7`='Necesito la ayuda de otro espíritu cazador, Ar''tor.' WHERE `ID`=19017;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 알겠네. 바로 정령사냥꾼을 준비해 주지.', `MaleText_loc4`='如你所愿，$n。灵魂猎人已经准备好了。', `MaleText_loc5`='如你所期望的，$n。幽魂獵手準備好了。', `MaleText_loc7`='Como desees, $n. El espíritu cazador está preparado.' WHERE `ID`=19018;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나의 전성기는 전선에서 지나갔고, 야수를 조련하는 데 수많은 세월을 보냈소. 고향에 돌아오니 기분이 좋군. 어떻게 변했든지 이곳은 내 고향이니까.', `MaleText_loc4`='我在战壕中渡过了很久，还花了很多年来训练小狗们。回家的感觉真好。无论它变成了什么样子，那始终是我的家。', `MaleText_loc5`='我已經在戰壕裡度過我的時間，並且花費很多年訓練這些自負的傻小子。回家的感覺真好。不管它變成怎樣，都是我的家。', `MaleText_loc7`='He pasado mi tiempo en las trincheras y muchos años entrenando a los cachorros. Me alegro de estar en casa. No importa en lo que se haya convertido, este es mi hogar.' WHERE `ID`=19019;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인을 위해서라면 죽음까지 막아설 줄 아는 이 용감한 야수들을 돌보는 것은 영광스러운 일이라오.', `MaleText_loc4`='照看这些让我的部族免受死亡威胁的无畏野兽是一种荣誉。', `MaleText_loc5`='照料這些擋在我的族人和死亡之間的勇敢野獸是一種榮譽。', `MaleText_loc7`='Ocuparme de esas bestias intrépidas, que se interponen entre mis compañeros de clan y la muerte, es un honor.' WHERE `ID`=19020;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='게드라, 제 야수를 맡아주십시오.', `MaleText_loc4`='我想要寄放我的宠物，盖德拉。', `MaleText_loc5`='我想要寄放我的寵物，傑德洛。', `MaleText_loc7`='Deseo guardar a mi mascota en el establo, Gedrah.', `FemaleText_loc1`='게드라, 제 야수를 맡아주세요.', `FemaleText_loc4`='我想要寄放我的宠物，盖德拉。', `FemaleText_loc5`='我想要寄放我的寵物，傑德洛。', `FemaleText_loc7`='Deseo guardar a mi mascota en el establo, Gedrah.' WHERE `ID`=19021;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고맙네, $n. 이제 실험을 해볼까...', `FemaleText_loc4`='谢谢你，$n。现在，去完成测试吧……', `FemaleText_loc5`='謝謝你，$n。現在，進行測試...', `FemaleText_loc7`='Gracias, $n. Ahora, a realizar la prueba...' WHERE `ID`=19022;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 그래...', `FemaleText_loc4`='啊，我明白了……', `FemaleText_loc5`='啊，我明白了...', `FemaleText_loc7`='Ah, ya veo...' WHERE `ID`=19023;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안타깝군.', `FemaleText_loc4`='是的，这真不幸。', `FemaleText_loc5`='沒錯，真是不幸。', `FemaleText_loc7`='Sí, es inoportuno.' WHERE `ID`=19024;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n, 이 피는 악마의 힘에 오염된 해골이빨 부족의 것임을 다시 한번 확인했네. 하지만, 지금 내가 가진 장비로는 더 자세한 조사가 불가능할 것 같군...', `FemaleText_loc4`='$n，我已经确认了这感染恶魔力量的鲜血是噬骨氏族的兽人们留下的。我担心不管用什么方式，我现有的设备都不能更进一步钻研这个秘密了……', `FemaleText_loc5`='$n，我已經確認這個血液是來自獸人的噬骨者氏族，受到惡魔力量的腐化。不過，我害怕的是我目前的設備沒辦法再深入研究這個秘密...', `FemaleText_loc7`='$n, he confirmado que esta sangre pertenece al clan de orcos Mascahuesos, contaminados de poder demoníaco. Sin embargo, me temo que mi equipamiento actual no puede profundizar más en este misterio...' WHERE `ID`=19025;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳은 신성한 땅입니다! 여기에선 아무도 당신과 같은 자를 환영하지 않습니다.', `MaleText_loc4`='这里是圣地！滚开！', `MaleText_loc5`='這些是神聖的土地!這裡不歡迎你。', `MaleText_loc7`='¡Esta es tierra sagrada! No eres $gbienvenido:bienvenida;.' WHERE `ID`=19026;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='점술가 길드의 친구는 이곳에 들어올 수 없습니다!', `MaleText_loc4`='占星者的朋友不允许到这儿来！', `MaleText_loc5`='這裡不歡迎占卜者的朋友!', `MaleText_loc7`='¡Los amigos de los Arúspices no pueden estar aquí!' WHERE `ID`=19027;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳을 떠나 당신만의 시간을 갖고 당신의 행동을 반성해 보도록 하십시오.', `MaleText_loc4`='快点离开这里，反省一下你的行动。', `MaleText_loc5`='省下你這裡的時間去反省你的行為。', `MaleText_loc7`='Tómate tu tiempo lejos de aquí para reflexionar sobre tus acciones.' WHERE `ID`=19028;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오우거들이 나를 목까지 묻고는 잊어버렸네.$B$B그래, 우습기도 하겠지. 마음껏 비웃게나. 머리만 남은 유령이 여기 있으니까.$B$B물론 도와준다면 보상을 줄 수도 있어.$B$B그치만 됐어. 계속 웃기나 하라고.', `MaleText_loc4`='那些食人魔，他们把我埋起来，然后忘记回来了。$B$B嗯，朋友，有趣吧，笑吧。$B$B当然，要是你想帮我出来，我是不会让你吃亏的。$B$B如果你不想帮忙，就继续笑吧。', `MaleText_loc5`='這些巨魔，他們把我埋到只剩我的脖子，然後就忘記回來了。$B$B是啊，老兄，真有趣。笑出來吧。沒有身體的鬼魂頭在這裡。$B$B當然，如果你想要幫我出來，我也許值得你花點時間。$B$B但是不准，一直笑。', `MaleText_loc7`='Los ogros, me entierran hasta el cuello aquí y después se olvidan de volver.$B$BSí, muy gracioso. Ríete. Hay una cabeza de fantasma aquí.$B$BDe acuerdo, si quieres ayudarme, quizás puedas servirme.$B$BPero no, sigue riéndote.' WHERE `ID`=19029;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새들이 부리는 마법은 먹히지 않아. 난 이제 자유다!', `MaleText_loc4`='鸦人的法术失效了。我自由了！', `MaleText_loc5`='奇怪法術沒用。我好好的!', `MaleText_loc7`='El hechizo de pájaro no funciona. ¡Mi ser libre!' WHERE `ID`=19030;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 알을 낳습니다.', `MaleText_loc4`='%s产下一枚卵。', `MaleText_loc5`='%s下了一顆蛋。', `MaleText_loc7`='%s pone un huevo.' WHERE `ID`=19031;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청한 오우거들에게 한 수 가르쳐 줘야겠군.', `MaleText_loc4`='愚蠢的食人魔。你们都应该好好上一课。', `MaleText_loc5`='愚蠢的巨魔。你們全都需要受到教訓。', `MaleText_loc7`='Ogro estúpido. Necesitáis que os enseñen una lección.' WHERE `ID`=19032;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자유를 원한다면 자유를 찾고자 노력해야 한다.', `MaleText_loc4`='如果你所追寻的是自由，那么你终将得到它。', `MaleText_loc5`='如果你尋求的是自由，那麼你找到的就是自由。', `MaleText_loc7`='Si lo que buscas es libertad, libertad es lo que encontrarás.' WHERE `ID`=19033;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 오우거들은 쓰레기다. 말하자면 이제 쓰레기를 버릴 시간이란 뜻이지.', `MaleText_loc4`='食人魔就像一次性的用品，用过就可以丢弃。现在，是清理垃圾的时候了。', `MaleText_loc5`='你們這些巨魔是可丟棄的。意思就是說，是清理垃圾的時候了。', `MaleText_loc7`='Sois desechables, ogros. Dicho esto, es hora de sacar la basura.' WHERE `ID`=19034;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오우거라면 이제 지긋지긋해. 오우거들을 하나도 남김없이 모조리 없애야 한다.', `MaleText_loc4`='我厌烦这些食人魔。我们应该消灭他们，全部。', `MaleText_loc5`='我厭倦了這些巨魔。我們應該除掉他們，全部。', `MaleText_loc7`='Me cansan esos ogros. Deberíamos exterminarlos a todos.' WHERE `ID`=19035;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 중에 같은 꼴이 되고 싶은 녀석이 또 있나?', `MaleText_loc4`='有其他的食人魔想加入你朋友的行列吗？', `MaleText_loc5`='你有任何其他的巨魔想要加入你的朋友嗎?', `MaleText_loc7`='¿Alguno de ustedes, ogros, quiere unirse a $gnuestro amigo:nuestra amiga;?' WHERE `ID`=19036;
