UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 조용히 한숨을 쉬며 운명을 기다립니다.', `MaleText_loc4`='%s轻轻叹了口气，等待着无可避免的结局。', `MaleText_loc5`='靜靜地嘆氣，%s等待著不可避免的事。', `MaleText_loc7`='Suspirando sin hacer ruido, el %s aguarda lo inevitable.', `FemaleText_loc1`='%s|1이;가; 조용히 한숨을 쉬며 운명을 기다립니다.', `FemaleText_loc4`='%s轻轻叹了口气，等待着无可避免的结局。', `FemaleText_loc5`='靜靜地嘆氣，%s等待著不可避免的事。', `FemaleText_loc7`='Suspirando sin hacer ruido, el %s aguarda lo inevitable.' WHERE `ID`=19049;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 임박한 자신의 운명을 직시합니다.', `MaleText_loc4`='%s转过身面对即将到来的厄运。', `MaleText_loc5`='%s轉而面對逼近他的死亡。', `MaleText_loc7`='El %s se gira para enfrentarse a su inminente destino.', `FemaleText_loc1`='%s|1이;가; 임박한 자신의 운명을 직시합니다.', `FemaleText_loc4`='%s转过身面对即将到来的厄运。', `FemaleText_loc5`='%s轉而面對逼近他的死亡。', `FemaleText_loc7`='El %s se gira para enfrentarse a su inminente destino.' WHERE `ID`=19050;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간이 없다는 것을 안 %s|1은;는; 뛰려고도 하지 않습니다.', `MaleText_loc4`='%s知道已经来不及了，他甚至没有尝试跑开。', `MaleText_loc5`='知道時間不夠，%s甚至連跑都不跑。', `MaleText_loc7`='Sabiendo que no hay tiempo suficiente, el %s ni siquiera intenta correr.', `FemaleText_loc1`='시간이 없다는 것을 안 %s|1은;는; 뛰려고도 하지 않습니다.', `FemaleText_loc4`='%s知道已经来不及了，他甚至没有尝试跑开。', `FemaleText_loc5`='知道時間不夠，%s甚至連跑都不跑。', `FemaleText_loc7`='Sabiendo que no hay tiempo suficiente, el %s ni siquiera intenta correr.' WHERE `ID`=19051;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<고개를 젓는 누아인 스톰윙>$B$B한쪽에는 불타는 군단, 그 반대편에는 일리단의 졸개들이 있으니 이 성채를 지키려면 모든 수단을 총동원해야 합니다. 우리는 반드시 해낼 겁니다! 진정한 와일드해머라면 고향을 내어주느니 차라리 죽음을 택할 테니까요.', `MaleText_loc4`='<努埃恩摇了摇头。>$B$B燃烧军团和伊利丹的随从使我们腹背受敌，我们要做好牺牲一切的准备来防御要塞，绝对不能失败！真的蛮锤矮人宁死也不会抛弃自己的家园。', `MaleText_loc5`='<奴艾恩·雷翼搖頭。>$B$B一邊是軍團而另一邊是伊利丹的爪牙，我們要盡一切能夠取得的事物來防衛堡壘，而且我們一定會受住它!每一個忠誠的蠻錘寧願死也不會交出我們的家園。', `MaleText_loc7`='<Nuainn Alatormenta niega con la cabeza.>$B$BCon la Legión a un lado y los esbirros de Illidan al otro, vamos a necesitar todo lo posible para defender el bastión, ¡y lo haremos! Todo auténtico Martillo Salvaje preferiría morir a renunciar a nuestra tierra.' WHERE `ID`=19052;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보다시피 내 무기고에는 굉장한 무기가 아주 많지.', `MaleText_loc4`='你们看，我的个人收藏中有许多武器……', `MaleText_loc5`='你們看，我的個人收藏中有許多武器...', `MaleText_loc7`='Como pueden ver, dispongo de un amplio arsenal...' WHERE `ID`=19053;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='똑바로 서라, 그런트! 너는 이제 코르크론 파수병의 명령을 따라야 한다.', `MaleText_loc4`='立正，士兵！现在你要听从库卡隆卫士的指挥。', `MaleText_loc5`='站直，蠻兵!你現在受控於柯爾克隆守衛。', `MaleText_loc7`='¡Ponte $gderecho:derecha;, $gbruto:bruta;! Ahora estás bajo las órdenes de la Guardia de Kor''kron.' WHERE `ID`=19054;
