UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주목! 이제 내가 하는 대로 해라.', `MaleText_loc4`='注意！现在我做什么，你们就做什么。', `MaleText_loc5`='注意!現在跟我這樣做。', `MaleText_loc7`='¡Atención! Ahora haced lo que yo haga.', `FemaleText_loc1`='주목! 이제 내가 하는 대로 해라.', `FemaleText_loc4`='注意！现在我做什么，你们就做什么。', `FemaleText_loc5`='注意!現在跟我這樣做。', `FemaleText_loc7`='¡Atención! Ahora haced lo que yo haga.' WHERE `ID`=19058;
