UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈들을 과소평가했나 보군. 모두를 한꺼번에 상대하라는 건 불공평한 처사지만, 나의 백성도 공평한 대접을 받은 적 없기는 매한가지. 받은 대로 돌려주겠다.', `MaleText_loc4`='也许我确实低估了你们。虽然让你们同时面对我的四位顾问显得有些不公平，但是我的人民从来都没有得到过公平的待遇。我只是在以牙还牙。', `MaleText_loc5`='也許我低估了你。要你一次對付四位諫言者也許對你來說是不太公平，但是...我的人民從未得到公平的對待。我只是以牙還牙而已。', `MaleText_loc7`='Quizás los subestimé. Sería injusto que los haga enfrentar a los cuatro consejeros al mismo tiempo, pero... nunca se ha tratado con justicia a mi gente. Así que les devuelvo el favor.' WHERE `ID`=19060;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하하! 거의 시간이 됐습니다! 언제가 마지막 날이 될지 두려워하지 않아도 됩니다...', `FemaleText_loc4`='哈哈！是时候了！再也不用每天提心吊胆了！', `FemaleText_loc5`='哈!是時候了!不用再懼怕每一天都是我們的最後一天了...', `FemaleText_loc7`='¡Ja! ¡Ya era hora! Ya no hay que temer más que cada día será el último...' WHERE `ID`=19061;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='모두 다 한 잔씩 받으세요. 타도크가 돌린다면 말이죠...', `FemaleText_loc4`='要是萨度克愿意的话……我想每个人都应该得到一杯的。', `FemaleText_loc5`='我認為每個人都應該要有一杯酒。要是薩杜克請客的話...', `FemaleText_loc7`='Creo que todo el mundo se merece una bebida. Si Thadok está compartiendo...' WHERE `ID`=19062;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='책을 읽다보니 갈증이 나는군요. 한 잔 할까요?', `FemaleText_loc4`='学会阅读是很有必要的一件事。一块面包？', `FemaleText_loc5`='學習閱讀是一個會口乾舌燥的事。來一杯，要嗎?', `FemaleText_loc7`='Aprender a leer es un asunto que da sed. Un brindis, ¿eh?' WHERE `ID`=19063;
