UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오래전 내 피가 차갑게 굳어버리지 않았다면 지금 엄청나게 끓어올랐을 거야...', `MaleText_loc4`='要不是我的血早已凝固了，它现在就会因愤怒而沸腾……', `MaleText_loc5`='要是我的血沒在很久以前就凝結了，那它現在就會因為憤怒而沸騰...', `MaleText_loc7`='Si la sangre no se me hubiera coagulado hace tiempo, estaría hirviendo de rabia ahora mismo...' WHERE `ID`=19069;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 땅은 지금도 과거의 상처를 안고 있네. 과연 그 상처가 치료될까 의문이군...', `MaleText_loc4`='这片土地仍然挂着旧日的伤痕，我在想它们是否能够痊愈。', `MaleText_loc5`='這塊土地仍然承受著過去的傷痕。我懷疑他們是否將夠治癒。', `MaleText_loc7`='Esta tierra todavía porta las cicatrices del pasado. Me pregunto si alguna vez sanarán.' WHERE `ID`=19070;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물속에서 숨을 쉴 수 있도록 마법을 걸어주시겠습니까?', `MaleText_loc4`='你能对我施放让我可以在水下呼吸和移动的魔法吗？', `MaleText_loc5`='你能施法幫助我在水中呼吸及行動嗎?', `MaleText_loc7`='¿Puedes lanzar el hechizo para ayudarme a respirar y moverme bajo el agua?', `FemaleText_loc1`='물속에서 숨을 쉴 수 있도록 마법을 걸어주시겠어요?', `FemaleText_loc4`='你能对我施放让我可以在水下呼吸和移动的魔法吗？', `FemaleText_loc5`='你能施法幫助我在水中呼吸及行動嗎?', `FemaleText_loc7`='¿Puedes lanzar el hechizo para ayudarme a respirar y moverme bajo el agua?' WHERE `ID`=19071;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 멀리 떨어졌군요... 연결이... 끊어졌습니다...', `MaleText_loc4`='我太远了……连接……中断了……', `MaleText_loc5`='我太遠了...連線...中斷...', `MaleText_loc7`='Estoy demasiado lejos... El vínculo... se ha perdido...' WHERE `ID`=19072;
