UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='기쁜 소식입니다! $n|1이;가; 목숨을 위협하던 악마들로부터 우리를 구했습니다!', `FemaleText_loc4`='欢呼吧，我的朋友们！$n从威胁我们生命的暗影手中拯救了我们！', `FemaleText_loc5`='我的朋友，慶祝吧!$n已經將我們從威脅我們生命的陰影中拯救出來了!', `FemaleText_loc7`='¡Alegraos, amigos! ¡$n nos ha salvado de la sombra inminente que amenazaba nuestras vidas!' WHERE `ID`=19075;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 우리가 안전하다고요? 그게 정말입니까?! 야호!', `MaleText_loc4`='我们得救了？我们真的得救了？！呀哈！', `MaleText_loc5`='我們安全了?我們真的安全了?!啊呼!', `MaleText_loc7`='¿Estamos salvados? ¡¿Estamos salvados de verdad?! ¡YUJU!' WHERE `ID`=19076;
