UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 정말 운이 좋군요. 이럴 때 포도주가 빠질 순 없죠.', `MaleText_loc4`='多幸运啊。我觉得这时候应该喝点小酒。', `MaleText_loc5`='真幸運。我相信這需要一點酒。', `MaleText_loc7`='Qué afortunado. Opino que esto pide algo de vino.' WHERE `ID`=19079;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 우리가 구출된 것을 기념하는 고급 포도주입니다!', `MaleText_loc4`='为我们的得救干一杯！', `MaleText_loc5`='一瓶好的葡萄酒慶祝我們的拯救!', `MaleText_loc7`='¡Un añejo excelente para celebrar nuestra salvación!' WHERE `ID`=19080;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='평지거인의 냄새를 맡으면 구역질이 난단 말이지.', `MaleText_loc4`='这些陆地上来的家伙的气味让我感到恶心。', `MaleText_loc5`='這些大地行者的氣味讓我覺得惡心。', `MaleText_loc7`='El olor de esos caminantes de la tierra me repugna.', `FemaleText_loc1`='평지거인의 냄새를 맡으면 구역질이 난단 말이지.', `FemaleText_loc4`='这些陆地上来的家伙的气味让我感到恶心。', `FemaleText_loc5`='這些大地行者的氣味讓我覺得惡心。', `FemaleText_loc7`='El olor de esos caminantes de la tierra me repugna.' WHERE `ID`=19081;
