UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 시대가 가까워지고 있구나.', `MaleText_loc4`='我们翘首企盼的日子就快来了。', `MaleText_loc5`='我們的時代正在接近。', `MaleText_loc7`='Nuestra hora se acerca.', `FemaleText_loc1`='우리의 시대가 가까워지고 있구나.', `FemaleText_loc4`='我们翘首企盼的日子就快来了。', `FemaleText_loc5`='我們的時代正在接近。', `FemaleText_loc7`='Nuestra hora se acerca.' WHERE `ID`=19083;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장가르 습지대에 사는 야생늪 일족에겐 정교한 자물쇠가 달린 광주리가 있답니다. 그 광주리를 여는 건 당신 정도의 솜씨라도 결코 쉽지 않을 겁니다.', `MaleText_loc4`='居住在赞加沼泽的蛮沼部族背着带锁的篮子，你应该有兴趣去挑战一下自己的技能。', `MaleText_loc5`='居住在贊格沼澤的菲拉芬擁有附帶精巧鎖閘的柳條籃。想必他們能夠挑戰你的技術。', `MaleText_loc7`='Los Feropantanos que habitan en la Marisma de Zangar tienen cestas de mimbre con cerraduras inteligentes. Sin duda pondrían a prueba hasta tu habilidad.', `FemaleText_loc1`='장가르 습지대에 사는 야생늪 일족에겐 정교한 자물쇠가 달린 광주리가 있답니다. 그 광주리를 여는 건 당신 정도의 솜씨라도 결코 쉽지 않을 겁니다.', `FemaleText_loc4`='居住在赞加沼泽的蛮沼部族背着带锁的篮子，你应该有兴趣去挑战一下自己的技能。', `FemaleText_loc5`='居住在贊格沼澤的菲拉芬擁有附帶精巧鎖閘的柳條籃。想必他們能夠挑戰你的技術。', `FemaleText_loc7`='Los Feropantanos que habitan en la Marisma de Zangar tienen cestas de mimbre con cerraduras inteligentes. Sin duda pondrían a prueba hasta tu habilidad.' WHERE `ID`=19084;
