UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 우리의 땅을 뺏을 수 있을진 몰라도 자유를 뺏을 순 없다! 공격!', `MaleText_loc4`='They can take away our land, but they can''t take away our freedom!  Attack! [PH]', `MaleText_loc5`='他們能奪走我們的土地，但是他們不能奪走我們的自由!攻擊![PH]', `MaleText_loc7`='¡Pueden quitarnos nuestra tierra, pero no podrán quitarnos la libertad! ¡Al ataque! [PH]' WHERE `ID`=19086;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나그란드에 있는 킬소로우 요새의 사물함은 당신 같이 훌륭한 솜씨를 지닌 도적이라도 열기 어려울 겁니다.', `MaleText_loc4`='撬开纳格兰的基尔索罗堡垒里的箱子对你这样的潜行者来说，是一种莫大的挑战。', `MaleText_loc5`='納葛蘭的吉爾索洛堡壘置物箱會有一項大挑戰提供給即使是你這樣技術卓越的盜賊。', `MaleText_loc7`='Los baúles de la Fortaleza Mata’penas de Nagrand sería un reto considerable incluso para $gun pícaro:una pícara; de tu notable habilidad.', `FemaleText_loc1`='나그란드에 있는 킬소로우 요새의 사물함은 당신 같이 훌륭한 솜씨를 지닌 도적이라도 열기 어려울 겁니다.', `FemaleText_loc4`='撬开纳格兰的基尔索罗堡垒里的箱子对你这样的潜行者来说，是一种莫大的挑战。', `FemaleText_loc5`='納葛蘭的吉爾索洛堡壘置物箱會有一項大挑戰提供給即使是你這樣技術卓越的盜賊。', `FemaleText_loc7`='Los baúles de la Fortaleza Mata’penas de Nagrand sería un reto considerable incluso para $gun pícaro:una pícara; de tu notable habilidad.' WHERE `ID`=19087;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아아아악! 저들을 잡아서 처치해라!', `MaleText_loc4`='AAAAAAAAHHHHHHHHHHHHH!  Get them!  Kill them all! [PH]', `MaleText_loc5`='啊...哈!找到他們了!把他們全都殺了! [PH]', `MaleText_loc7`='¡AAAAAAAAHHHHHHHHHHHHH! ¡Cogedlos! ¡Matadlos a todos! [PH]', `FemaleText_loc1`='아아아아악! 저들을 잡아서 처치해라!', `FemaleText_loc4`='AAAAAAAAHHHHHHHHHHHHH!  Get them!  Kill them all! [PH]', `FemaleText_loc5`='啊...哈!找到他們了!把他們全都殺了! [PH]', `FemaleText_loc7`='¡AAAAAAAAHHHHHHHHHHHHH! ¡Cogedlos! ¡Matadlos a todos! [PH]' WHERE `ID`=19088;
