UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발뒤꿈치를 들고 조심해서 가도록. 이 다리를 지나면 지옥이 있으니까.', `MaleText_loc4`='脚步放轻，$r。地狱就在这座桥的前方。', `MaleText_loc5`='輕輕走，$r。這座橋以外就是地獄。', `MaleText_loc7`='Pisa con suavidad, $r. Más allá de este puente se encuentra el infierno.' WHERE `ID`=19091;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 너무 서두르지 마라. 네가 찾는 자유는 바로 위에 있다.', `MaleText_loc4`='啊……不要走得这么匆忙，我的朋友。你的后方才有你追寻的自由。', `MaleText_loc5`='啊...不要這麼急，我的朋友。你要尋找的自由就在身後。', `MaleText_loc7`='Ahh... no tan rápido, $gamigo:amiga;. La libertad que buscas está tras de ti.' WHERE `ID`=19092;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 규칙은 딱 하나지. 모두 싸우고 아무도 그만두지 못한다.', `MaleText_loc4`='我只有一条命令。血战到底，不许退缩。', `MaleText_loc5`='我只有一個規則。每個人都要戰鬥。沒有人逃得過。', `MaleText_loc7`='Solo tengo una norma. Todo el mundo lucha. Nadie abandona.' WHERE `ID`=19093;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일을 제대로 하지 않으면 내가 직접 쏠지도 몰라!', `MaleText_loc4`='谁要是临阵脱逃，我就打爆他的头。', `MaleText_loc5`='你不去做你的工作，我就親自射殺你。', `MaleText_loc7`='Si no haces tu trabajo, te disparo yo mismo.' WHERE `ID`=19094;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서, 이 바보야. 영원히 살고 싶지 않아?', `MaleText_loc4`='给我上，你们这帮猿人，想老不死活一辈子吗？', `MaleText_loc5`='過來你這個大猩猩。你想要長生不死嗎?', `MaleText_loc7`='Vamos, simios. ¿Queréis vivir siempre?' WHERE `ID`=19095;
