UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 썩은 알을 깨고 모두가 놀라는 가운데 내용물을 들이마십니다.', `MaleText_loc4`='%s把腐烂的蛋敲碎，然后在众目睽睽之下开始吮吸它腐烂的核心。', `MaleText_loc5`='%s打破了這個爛雞蛋 - 在所有圍著他的驚恐及驚慌中 - 從它發臭的蛋黃開始喝。', `MaleText_loc7`='%s rompe el huevo y - para horror y consternación de todos a su alrededor – comienza a beber de su putrefacto líquido.' WHERE `ID`=19098;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='인생의 전환점이라 부를 만 했습니다... 잠시만 실례하죠.', `MaleText_loc4`='真是大起大落……对不起，我走开一分钟。', `MaleText_loc5`='那是生命的轉機...請原諒我一分鐘。', `MaleText_loc7`='Eso me ha cambiado la vida... Discúlpame un momento.' WHERE `ID`=19099;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 지금까지 경험한 그 어떤 것보다도 지독한 트림을 합니다.', `MaleText_loc4`='%s打了一个嗝，那味道和声音让你觉得没什么能比它更恶心了……', `MaleText_loc5`='%s打了一個有史以來聽過或聞過最惡臭的嗝。', `MaleText_loc7`='%s suelta el eructo más fétido jamás oído u olido.' WHERE `ID`=19100;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 됐어요... 다시 얘기를 시작할까요.', `MaleText_loc4`='那么好吧，回去工作。', `MaleText_loc5`='好，回歸正題。', `MaleText_loc7`='De acuerdo, volvamos a nuestros asuntos.' WHERE `ID`=19101;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지상 최강의 트림입니다! 살고 싶으면 튀세요!', `MaleText_loc4`='呕！逃命吧！', `MaleText_loc5`='一整個噁心至極!拚命逃跑吧!', `MaleText_loc7`='¡Es una vomitoteca completa y total! ¡CORRED PARA SALVAR LA VIDA!' WHERE `ID`=19102;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왕자님께서 노하실 줄은 알았지만, 난... 제정신이 아니었어. 그들을 풀어줄 수밖에 없었다고! 봐, 위대한 분께서 말씀하시잖아! 잠깐... 캘타스 왕자님께서 보낸 자들이 아니잖아! 좋았어... 네놈들이 죄수를 풀어줬다고 일러바치면 되겠군!', `MaleText_loc4`='我知道王子殿下会非常生气，但是我……我不知道自己怎么回事，居然把它们都放出来了！主人在对我说话，你也看到了……等等，有人来了。你们不是凯尔萨斯派来的！好极了……我会告诉王子殿下，是你们放走了囚犯！', `MaleText_loc5`='我知道王子會生氣，但是我...我身不由己。我必須放了他們!是偉大的造物主命令我這麼做的，你要知道。等等─入侵者。凱爾薩斯並沒有派你來這邊!太好了...我只要跟王子說犯人是你釋放的就可以了!', `MaleText_loc7`='Sabía que el príncipe se enojaría, pero... no he sido yo mismo. ¡Tuve que liberarlos! El Magno me habla. Un momento--intrusos. ¡Kael''thas no los envió! Bien... ¡Le diré al príncipe que ustedes liberaron a los prisioneros!' WHERE `ID`=19103;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나루는 세상에서 가장 위험한 존재들을 이곳에 가두었다. 내 친히 소개하지...', `MaleText_loc4`='纳鲁把多种宇宙中最危险的怪物关在这些牢笼里。请允许我向你们介绍下一种……', `MaleText_loc5`='那魯把最危險的犯人們關在這些囚房裡。讓我向你介紹另一個危險人物...', `MaleText_loc7`='Los naaru encerraron en estas celdas a algunos de los seres más peligrosos que existen. Permítanme presentarles a otro.' WHERE `ID`=19104;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s의 무기가 기묘한 느낌의 불빛으로 번쩍입니다.', `MaleText_loc4`='%s的武器喷出异常的火光。', `MaleText_loc5`='%s的武器發出怪異的火花。', `MaleText_loc7`='Las armas de %s brillan con un fuego antinatural.' WHERE `ID`=19105;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 좋아!', `MaleText_loc4`='很好，很好……又是一个！你的意志是我的了！', `MaleText_loc5`='是的，是的...另一個危險人物!你跟我想的一樣!', `MaleText_loc7`='¡Sí, sí... otro! ¡Tu voluntad me pertenece!' WHERE `ID`=19106;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 봐라, 무한한 힘을 가진 절대 공포의 존재가 강림하신다!', `MaleText_loc4`='看吧！又一个拥有深不可测的力量的恐怖生物！', `MaleText_loc5`='看，又一個不可思議力量的恐怖生物!', `MaleText_loc7`='¡Contemplen, otra criatura terrorífica de incomprensible poder!' WHERE `ID`=19107;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기는 얄리얄리 얄라셩 어디쯤인가? 넌 누구... 으아악, 이햐! 머리가 깨질 듯 아파!', `MaleText_loc4`='我这是在什么鬼地方？你们又是谁……啊啊啊，头好疼啊！', `MaleText_loc5`='這是什麼鬼地方?而你--又是誰，我的頭好痛!', `MaleText_loc7`='¿Pero dónde rayos estoy? ¿Y quiénes...? arrggg, ¡que dolor de cabeza!' WHERE `ID`=19108;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐... 뭐야? 땅딸보 노움? 오, 위대한 분이시여, 노여워 마소서.', `MaleText_loc4`='这是什么？一个卑微的侏儒？我下次会做得更好的，主人。', `MaleText_loc5`='這是什麼?一個卑微的地精?下一次我會做的更好，偉大的造物主。', `MaleText_loc7`='¿Pero qué es esto? ¿Un gnomo endeble? Yo lo haré mejor. Oh, magno.' WHERE `ID`=19109;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 혼란! 이 공포! 위대한 분이시여, 선견지명에 감탄했습니다!', `MaleText_loc4`='混乱！疯狂！啊，您真是太睿智了！是的，我明白了，当然！', `MaleText_loc5`='沒有秩序!混亂!噢，你真是聰明!沒錯，當然，我現在發現了!', `MaleText_loc7`='¡Anarquía! ¡Alboroto! ¡Oh, eres tan inteligente! ¡Sí, ahora lo veo claro!' WHERE `ID`=19110;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 마지막이군. 예. 위대한 분이시여, 즉시 시행하겠습니다!', `MaleText_loc4`='还剩下最后一个牢笼。好的，主人，马上！', `MaleText_loc5`='只剩下一間牢房了。是的，偉大的造物主，馬上照辦!', `MaleText_loc7`='Queda una celda. Sí, oh, magno, ¡ahora mismo!' WHERE `ID`=19111;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나약한 정신은 조종하기 아주 쉽지... 난 시간과 운명조차 건드릴 수 없는 강력한 분께 충성을 맹세했느니라. 이 세계와 저 너머 세계의 어느 누구도 우리를 꺾지 못해... 저 잘난 불타는 군단조차도!', `MaleText_loc4`='控制弱者的思想是非常容易的事情……因为我所效忠的不被时间改变的力量，不被命运左右的力量。这个世界上没有什么力量能与此匹敌……即使是燃烧军团也不行！', `MaleText_loc5`='控制弱者的心智是一件小事...因為我所效忠的是不受時間影響也不受命運擺佈的力量。世上沒有任何力量可以讓我們屈膝...甚至強大的燃燒軍團也不例外!', `MaleText_loc7`='Para mí es fácil controlar la mente de los débiles...porque juro lealtad a poderes no afectados por el tiempo, impasibles ante el destino. No hay fuerza en este o en cualquier otro mundo que albergue poder suficiente para doblegarnos... ¡ni siquiera la poderosa Legión!' WHERE `ID`=19112;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 운명을 마무리 짓고자 내가 왔노라!', `MaleText_loc4`='你们的死期到了！', `MaleText_loc5`='讓你們見證彼此的死亡吧!', `MaleText_loc7`='¡Observen al autor de su destrucción!' WHERE `ID`=19113;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오십시오. 저는 당신의 충실한 종입니다.', `MaleText_loc4`='欢迎您，主人。我是您谦卑的奴仆。', `MaleText_loc5`='歡迎，偉大的造物主。我是你謙卑的僕人。', `MaleText_loc7`='$gBienvenido, oh magno:Bienvenida, oh magna;. Soy tu humilde siervo.' WHERE `ID`=19114;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 산산이 부서집니다.', `MaleText_loc4`='%s炸成了碎片。', `MaleText_loc5`='%s碎為裂片。', `MaleText_loc7`='%s se hace añicos.' WHERE `ID`=19115;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='땅딸보 노움이라고? 친구... 당신이 누구든지 간에 아무도 이 위대한 밀하우스 마나스톰 님을 땅딸보라고는 부르지 않아!', `MaleText_loc4`='“卑微”？我不在乎你是谁，伙计。没有人敢说强大的米尔豪斯是个“卑微”的侏儒！', `MaleText_loc5`='「卑微」嗎?我不管你是誰，朋友︰沒有人能稱強大的米歐浩斯·曼納斯頓叫做「卑微」!', `MaleText_loc7`='¿"Endeble"? Me da igual quien seas pero nadie le dice al poderoso Molino Tormenta de maná que es endeble.' WHERE `ID`=19116;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 좀 준비할 게 있네요. 여러분은 시작하셔도 좋아요. 물 좀 만들어야 해서...', `MaleText_loc4`='等等，我要准备一下。你们先上，我先来做点水……', `MaleText_loc5`='我必須先準備好一些事情。你們先做你們的事。我必須先召喚一些水...', `MaleText_loc7`='Necesito prepararme antes. Empiecen ustedes. Tengo que invocar algo de agua…' WHERE `ID`=19117;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마나석...', `MaleText_loc4`='魔力宝石……', `MaleText_loc5`='法力寶石...', `MaleText_loc7`='Gema de maná...' WHERE `ID`=19118;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음엔 이 백옥 같은 피부를 보호할 마법도 걸고... 자, 한바탕 놀아볼까나!', `MaleText_loc4`='好极了！接下来，还得有些保护性的法术。耶！这样就对了！', `MaleText_loc5`='太棒了!再來，一些防禦性的魔法。嗯，這才對嘛!', `MaleText_loc7`='¡Fantástico! Ahora algunos hechizos protectores. Sí, ¡esto funciona!' WHERE `ID`=19119;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으으, 내 정신 좀 봐. 마나부터 채워야지. 굉장한 기술이 나오니까 쫌만 참아요.', `MaleText_loc4`='当然，我得先补充法力值。你们会看到我发威的，再等一会就行了……', `MaleText_loc5`='我當然需要一些法力。你們一定會愛上它;等著瞧吧...', `MaleText_loc7`='Y no puede faltar un poco de maná. Les va a encantar, esperen y verán…' WHERE `ID`=19120;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쪼오오아았어! 이렇게 신나게 두들겨팰 덩어리를 누가 불러줬지?', `MaleText_loc4`='好啦！那么是哪个蠢货准备好好挨一顿打？！', `MaleText_loc5`='來吧!是誰指名要點一客特大號的送死大餐?', `MaleText_loc7`='¡De acuerdo! ¿Quién pidió una extra grande de derrota?' WHERE `ID`=19121;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제겐 마법이 없습니다.', `FemaleText_loc4`='默认。', `FemaleText_loc5`='棄權。', `FemaleText_loc7`='Defecto.' WHERE `ID`=19122;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저게 마법이 있습니다. 분석해 보셔도 좋아요.', `MaleText_loc4`='我得到了魔法效果，你可以分析它。', `MaleText_loc5`='我擁有這項法術。你可以分析它。', `MaleText_loc7`='Tengo el hechizo. Puedes analizarlo.', `FemaleText_loc1`='저게 마법이 있습니다. 분석해 보셔도 좋아요.', `FemaleText_loc4`='我得到了魔法效果，你可以分析它。', `FemaleText_loc5`='我擁有這項法術。你可以分析它。', `FemaleText_loc7`='Tengo el hechizo. Puedes analizarlo.' WHERE `ID`=19123;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='토쉴리의 연구기지는 최고예요! 이상한 물자가 풍부하고 한적한 아웃랜드의 힘의 원천은 극한의 실험을 하기에는 최적의 조건이랍니다!', `MaleText_loc4`='托什雷的基地是最好的！外域的能量资源是极端实验的理想配置。', `MaleText_loc5`='托斯利基地是最棒的!冷僻及怪異的供給，外域的電源是極致實驗的一個理想裝置!', `MaleText_loc7`='¡La Estación de Toshley es la mejor! ¡La soledad y el suministro de fuentes de poder extrañas de Terrallende son un marco ideal para experimentos extremos!' WHERE `ID`=19124;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 복제인간... 아니, 제 쌍둥이 형제를 만나 보셨나요?', `MaleText_loc4`='你和我的克隆体说过话了吗——我的意思是……我的双胞胎？', `MaleText_loc5`='你有與我的克隆交談--我的意思是...我的雙胞胎嗎?', `MaleText_loc7`='¿Has hablado con mi clon –quiero decir... mi gemelo?' WHERE `ID`=19125;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='각서에 서명을 안 하셨군요! 저나 탤리에게 책임을 묻지 않는다는 각서에 서명을 한 후에 다시 오세요.', `MaleText_loc4`='你还没有签署你的声明！在你签字放弃所有对我和塔利的起诉权利之后再回来吧。', `MaleText_loc5`='你沒簽署你的棄權同意書!在你已經對我或者塔利簽署放棄所有索賠責任之後再來。', `MaleText_loc7`='¡No has firmado tu renuncia! Vuelve cuando hayas firmado todos los derechos de responsabilidad hacia mí o Tally.' WHERE `ID`=19126;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요!', `FemaleText_loc4`='默认。', `FemaleText_loc5`='棄權。', `FemaleText_loc7`='Defecto.' WHERE `ID`=19127;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 제 일은 끝났습니다!', `MaleText_loc4`='我的工作完成了！', `MaleText_loc5`='我在這裡的工作完成了!', `MaleText_loc7`='¡Mi trabajo aquí ha terminado!' WHERE `ID`=19128;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='차원문을 여는 내 마법이 이곳에서는 작동하지 않는 것 같군요. 빌어먹을 나루가 아주 잘 지어놓은 모양입니다.', `MaleText_loc4`='我的传送门创造法术似乎在这里不起作用。该死的纳鲁把这个地方建得滴水不漏。', `MaleText_loc5`='我的傳送門法術在這裡似乎無效。可惡的那魯把這個地方建造的很好。', `MaleText_loc7`='Mis hechizos de creación de portales no parecen funcionar aquí. Los malditos naaru construyeron bien este lugar.' WHERE `ID`=19129;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마침내 우리의 시대가 도래했습니다. 나루와 그들의 동맹은 고통의 진실한 의미를 알게 될 것입니다.', `MaleText_loc4`='我们翘首企盼的日子就快来了。纳鲁和他们的盟友将尝到真正的痛苦。', `MaleText_loc5`='我們的時代終將到來。那魯和他們的同盟者將學習到痛苦真正的意義。', `MaleText_loc7`='Al fin se acerca nuestro momento. Los naaru y sus aliados aprenderán el verdadero significado del sufrimiento.' WHERE `ID`=19130;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='참기 어려운 감옥 생활이었습니다. 이 저주받은 곳에서 한시라도 빨리 벗어나고 싶군요.', `MaleText_loc4`='被关在这个地方是非常痛苦的，越早离开这个可恶的地方越好。', `MaleText_loc5`='我們無法忍受被囚禁。我們能越快離開這個被詛咒的地方越好。', `MaleText_loc7`='Nuestro encarcelamiento era intolerable. Cuanto antes nos marchemos de este maldito lugar, mejor.' WHERE `ID`=19131;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들이 내 순간이동기를 연구기지 밖으로 옮기게 하다니 믿을 수가 없어요! 사고의 영향을 받은 대부분의 노움 친구들은 몇 주 내에 원래 모습을 되찾았다고요. 위대한 노움의 실험에 참가했다는 것은 분명 큰 영광이지요!

게다가 우리는 그 알이 필요했단 말입니다!', `MaleText_loc4`='我不敢相信他们居然把我的传送器弄出城去了！大部分受到事故影响的侏儒在过去的几周内都恢复了正常形态，而且他们应该对参与这么一个伟大的侏儒实验计划而感到荣幸！

此外，我们需要蛋！', `MaleText_loc5`='我不敢相信，他們竟然逼我把傳送器移到鎮外!大部分被意外影響的地精都會在幾週內就恢復成部分人形的模樣，而且能夠參與這樣偉大的地精實驗是一種榮譽!

對了，我們需要蛋!', `MaleText_loc7`='¡No puedo creer que me hicieran trasladar mi transportador fuera de la ciudad! La mayoría de los gnomos afectados por el accidente recobraron algún tipo de forma humanoide a las pocas semanas, y debería haber sido un honor ser un participante de tan importante experimento gnómico!

¡Además, necesitamos los huevos!' WHERE `ID`=19132;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장비가 완성되면 그 장비를 작동시켜 토쉴리의 연구기지까지 이동시키면 된답니다! 일부는 닭으로 변신했다는 보고가 있기는 하지만 과장된 게 분명해요!

저라면 인적이 드문 날만 골라서 사용하겠지만 그렇게까지 조심 안 해도 별문제는 없을 겁니다!', `MaleText_loc4`='等你建好了设备之后，你就可以激活设备，把自己传送到托什雷的基地！据报告称，少部分人被变成了小鸡，但我确信那是夸大其词。

可能的话，如果别人当天已经使用过了这台设备，我会尽量试着不去动它。当然，如果你忍不住想要使用的话，没准它还是会正常运转的。', `MaleText_loc5`='一旦建好這個裝置，你只要簡單地啟動裝置就可以傳送至托斯利基地!據報有一些人被變成了雞，不過我確信他們是誇大其詞!

假如可以的話，我會試用看看並在其他人用過之後讓它停機一天，不過如果你直接使用的話，它大概也會正常運作!', `MaleText_loc7`='Cuando hayas construido el dispositivo, simplemente lo activas para que te transporte a la Estación de Toshley. Varias personas han informado que fueron transformadas en pollos, ¡pero estoy seguro de que exageraban!

Si es posible, intentaría no utilizar el dispositivo un día que lo haya utilizado otra persona, ¡pero seguramente funcionará bien incluso si lo haces!' WHERE `ID`=19133;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='눈망루 마을의 우리 형 잽의 도움을 받아 이곳 52번 구역에 차원 내파기를 만들었네. 고블린 기계공학으로 순간이동이 가능한데 누가 로켓을 사용하겠어?! 자네, 내파기 신호장치를 손수 제작하는 방법을 배울 수 있을 만큼 고블린 기계공학에 능통한가?', `MaleText_loc4`='我在永望镇的兄弟扎普帮我在52区建造了一台空间内爆器。当你拥有地精工程学即时传送装置时，谁还会需要火箭呢？你现在的地精工程学技巧足够娴熟了吗？你能制作自己的内爆器航标了吗？', `MaleText_loc5`='在我永望鎮的兄弟札普幫忙下，我已經在52區這裡建造了一座空間爆破器。當你能夠馬上經由哥布林工程學來進行立即傳送的話，到時還有誰會需要火箭!你會是一位技術純熟到足以學習如何建造你自己的爆破器塔臺的哥布林工程師嗎?', `MaleText_loc7`='Con la ayuda de mi hermano Zap de Vista Eterna he construido un implosionador dimensional aquí, en el Área 52. ¡Quién necesita un cohete, cuando tiene transporte instantáneo a través de ingeniería goblin! ¿Eres $gun ingeniero:una ingeniera; goblin lo suficientemente $gcualificado:cualificada; como para aprender a construir tu propio localizador de implosionador?' WHERE `ID`=19134;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네, 고블린 기계공학에 능통하군. 정말 반가워! 수많은 고블린 기술자들이 차원 분할기 제작법을 배우고 있지만 그 후 아무 소식도 듣지 못했네. 참, 알쏭달쏭한 일이지.', `MaleText_loc4`='我很高兴可以和另一位合格的地精工程师说话！很多地精工程师在学会了制作空间撕裂器后，就杳无音信了。真奇怪。', `MaleText_loc5`='我很高興與另一位合格的哥布林工程師交談!有那麼多哥布林工程師學習如何製造空間撕裂器，但是之後我們就再也沒聽到他們的消息了。真令人想不透。', `MaleText_loc7`='¡Me alegro de hablar con otro ingeniero goblin cualificado! Hay tantos ingenieros goblin que aprenden a hacer el desgarrador de dimensión y nunca volvemos a saber de ellos... Qué extraño.' WHERE `ID`=19135;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안전보증 순간이동기가 당신을 떨어뜨리지 않기를 바랄게요! 물론 그럴 리는 없겠지만 만일을 대비해서 낙하산 망토를 가져가시는 게 좋을 거예요!', `MaleText_loc4`='我希望安全传送器永远都不会让你失望！我认为它是不会出故障的！但是我还是建议你最好带一件降落伞披风……', `MaleText_loc5`='我希望安全傳送器永遠不會令你失望!我就是知道它不會，不過為了以防萬一，我會建議帶一件降落傘披風!', `MaleText_loc7`='¡Espero que el transportador ultraseguro nunca te defraude! Sé que no lo hará, pero te recomiendo llevar una capa paracaídas, ¡por si acaso!' WHERE `ID`=19136;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침착하도록, 친구들!', `MaleText_loc4`='站着别动，伙计们！', `MaleText_loc5`='保持冷靜，男孩們!', `MaleText_loc7`='¡Quedaos, muchachos glaciales!' WHERE `ID`=19137;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='눈을 크게 뜨고 살피도록... 저쪽이 너무 조용한 게 수상해.', `MaleText_loc4`='注意点，伙计们。那边太安静了。', `MaleText_loc5`='夥伴們提高警覺。那裡太安靜了', `MaleText_loc7`='Vigilad, muchachos. Ahí fuera está demasiado tranquilo.' WHERE `ID`=19138;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지원군이 오는 중이다. 힘을 내서 싸워라!', `MaleText_loc4`='增援就在路上。继续战斗！', `MaleText_loc5`='後援上路了。持續戰鬥!', `MaleText_loc7`='Los refuerzos están en camino. ¡Seguid luchando!' WHERE `ID`=19139;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지원군은 언제 오는 거지? 당장 필요한데 말이야!', `MaleText_loc4`='我们的增援在哪里？我现在就要增援！', `MaleText_loc5`='我們的援軍在哪?我要他們馬上過來!', `MaleText_loc7`='¿Dónde están nuestros refuerzos? ¡Los quiero aquí ahora!' WHERE `ID`=19140;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='온다!!', `MaleText_loc4`='来了！！', `MaleText_loc5`='敵人來了!', `MaleText_loc7`='¡¡YA VIENEN!!' WHERE `ID`=19141;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적이 움직인다!', `MaleText_loc4`='敌方目标正在移动！', `MaleText_loc5`='敵人在移動!', `MaleText_loc7`='¡El enemigo está avanzando!' WHERE `ID`=19142;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가자!!', `MaleText_loc4`='我们上吧！', `MaleText_loc5`='我們跳舞吧!!', `MaleText_loc7`='¡VAMOS ALLÁ!' WHERE `ID`=19143;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='날려 버릴 다른 장난감을 데려와라!', `FemaleText_loc4`='再给我带个玩具来！', `FemaleText_loc5`='給我另一個玩具發射!', `FemaleText_loc7`='¡Traedme otro juguete para lanzar!' WHERE `ID`=19144;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='장난감이 필요하다. 다른 지옥불정령을 데려와!', `FemaleText_loc4`='我觉得很好玩。再给我一个地狱火！', `FemaleText_loc5`='我覺得好好玩喔。給我另一個煉獄火!', `FemaleText_loc7`='Me siento juguetona. ¡Traedme otro infernal!' WHERE `ID`=19145;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 악당이야? 누가 악당이냐고? 맞았어! 우리가 악당이지!', `MaleText_loc4`='谁最猛？谁最猛？没错！我们最猛！', `MaleText_loc5`='誰最壞?誰最壞?對:我們最壞!', `MaleText_loc7`='¿Quién manda aquí? ¿Quién? ¡Nosotros!' WHERE `ID`=19146;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꺼내주셔서 감사합니다. 당신에게 빚을 졌네요!', `MaleText_loc4`='谢谢你帮我脱身。算我欠你的！', `MaleText_loc5`='謝謝你將我救出來。我欠你一次!', `MaleText_loc7`='¡Gracias por sacarme de ahí, te debo una!' WHERE `ID`=19147;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 여기서 나갈 수 있을 겁니다. 고맙습니다!', `MaleText_loc4`='现在我应该可以从这里出来了，谢谢！', `MaleText_loc5`='我現在應該能離開這裡了。感謝!', `MaleText_loc7`='Ahora debería poder salir de aquí. ¡Gracias!' WHERE `ID`=19148;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳은 정말 최고예요! 이 모든 기술을 조사하면서 몇 년이라도 보낼 수 있을 것 같다고요!', `MaleText_loc4`='这个地方真疯狂！我可以在这里花上很多年来钻研这些技术！', `MaleText_loc5`='這個地方太瘋狂了!我可以在這花費好幾年研究這裡所有的技術!', `MaleText_loc7`='¡Este lugar es una locura! ¡Podría pasarme años aquí, investigando toda esta tecnología!' WHERE `ID`=19149;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 파멸의 군주 카자크께서 기뻐하실 것이다. 공격 속도를 높여라. 최대한 빨리 오크와 드워프의 요새를 파괴해라.', `MaleText_loc4`='末日领主卡扎克会高兴的。你最好加快你进攻的步伐，用最快的速度消灭这些兽人和矮人的要塞。', `MaleText_loc5`='毀滅領主卡札克會很開心。你應該加快你的攻擊速度。加速破壞獸人及矮人的要塞。', `MaleText_loc7`='El señor de fatalidad Kazzak estará satisfecho. Vas a aumentar el ritmo de tus ataques. Destruid a los orcos y los bastiones de los enanos se precipitarán.' WHERE `ID`=19150;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 문제는 걱정하지 마라. 죽음의 괴철로의 생산량을 늘려 놓았다. 네가 명령을 수행하기에 충분한 지옥불정령을 거느릴 수 있을 것이다. 실패하지 마라, 조바안.', `MaleText_loc4`='不要担心。我已经提高了死亡熔炉的产量，你会拥有足够的地狱火的。不要让我失望，约瓦安。', `MaleText_loc5`='不用擔心。我已經增加了死亡熔爐的產量。你將會得到所有你需要的煉獄火以執行你的命令。別失敗了，裘瓦安。', `MaleText_loc7`='No te preocupes por eso. He aumentado la producción en la Forja Muerta. Tendrás a todos los infernales que quieras para que sigan tus órdenes. No fracases, Jovaan.' WHERE `ID`=19151;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭔가?', `MaleText_loc4`='嗯？', `MaleText_loc5`='有事嗎?', `MaleText_loc7`='¿Sí?' WHERE `ID`=19152;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 힘내라! 좋은 성과를 유지하면 주인님께서 보상을 내리실 것이다.', `MaleText_loc4`='继续好好干活。干得好的话，主人就会奖赏你。', `MaleText_loc5`='繼續保持良好的工作表現。做得好，主人就會獎賞你。', `MaleText_loc7`='Sigue haciendo un buen trabajo. Hazlo bien y el maestro te recompensará.' WHERE `ID`=19153;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='땅을 파라! 주인님의 영광을 위해 땅을 파라!', `MaleText_loc4`='挖呀挖，为了主人挖呀挖！', `MaleText_loc5`='挖!為主人的榮耀而挖!', `MaleText_loc7`='¡Cava! ¡Cava por la gloria del maestro!' WHERE `ID`=19154;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭔가 중요한 것을 발견하는 즉시 내게 보고해라.', `MaleText_loc4`='如果你找到了什么重要的东西，立刻告诉我。', `MaleText_loc5`='假如你發現什麼重要的事，立刻讓我知道。', `MaleText_loc7`='Hazme saber de inmediato si encuentras algo importante.' WHERE `ID`=19155;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님, 찾아주셔서 영광입니다. 분부만 내리십시오.', `MaleText_loc4`='我的主人，您的到来使我们万分荣幸。请问有什么可以效劳的？', `MaleText_loc5`='我的主人，我們因為你的存在而倍感光榮。我要如何服侍你?', `MaleText_loc7`='Mi maestro, nos honra tu presencia. ¿En qué puedo servirte?' WHERE `ID`=19156;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일어나라, 젊은 볼둔이여... 그런 거추장스러운 격식은 필요 없다. 나는 우리의 주인이신 캘타스 왕자님의 명령으로 왔다. 그분께서 마나 폭탄의 진척 상황을 점검해 보라고 명하셨다.', `MaleText_loc4`='起来吧，沃多恩。不用多礼。我是奉凯尔萨斯王子之命而来，他要我来检查一下魔法炸弹的进程。', `MaleText_loc5`='起身，年輕的烏德恩。不要擔心你自己太輕浮。我受我們的主人，凱爾薩斯王子的指示來的。他命令我來檢查法力炸彈的進展。', `MaleText_loc7`='Levanta, joven Voldoun. No te preocupes de las gentilezas. Vengo a instancias de nuestro maestro, el príncipe Kael''thas. Me ordena que compruebe el progreso de la bomba de maná.' WHERE `ID`=19157;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋아요. 당신은 아라코아의 마법에 영향을 받고 있군요. 어서 분석을 해야겠으니 끝낸 후에 얘기하도록 하죠.', `FemaleText_loc4`='太好了，$n，你正在受到魔法的影响。我必须马上分析它，然后我们再谈谈。', `FemaleText_loc5`='很好，$n，你處在法力的影響下。我必須迅速分析它，然後我們才能交談。', `FemaleText_loc7`='Bien, $n, estás bajo la influencia del hechizo. Debo analizarlo rápidamente, después podremos hablar.' WHERE `ID`=19158;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님, 모든 것이 착착 진행되고 있습니다. 세나리온 수풀에서 소규모 원형을 실험한 결과, 매우 성공적이었습니다. 현재 아래쪽 안마당에서 두 번째 폭탄의 연료를 주입하고 있습니다. 그리고 이곳으로 나머지 부품을 가져올 전령을 투렘으로 보냈습니다.', `MaleText_loc4`='一切都进展得非常顺利，我的大人。塞纳里奥树林的小型样本测试非常成功。与此同时，第二个炸弹正在下面的院子里添加燃料。还有，我已经派了个信使去图雷姆把剩余的部分带回这里了。', `MaleText_loc5`='一切都進行得很順利，我的主人。在塞納里奧灌木林那小型的原型測試圓滿成功。第2枚炸彈就在我們談話的同時正在庭園下面按造儀式加滿燃料。而且，我已經派信使到杜瑞去，將其餘的零件帶到我們這裡來。', `MaleText_loc7`='Todo va extremadamente bien, mi señor. Las pruebas del prototipo más pequeño en el Matorral Cenarion fueron un completo éxito. La segunda bomba se está impulsando ritualmente en el patio de abajo mientras hablamos. Y he enviado un mensajero a Tuurem para que nos traiga el resto de partes aquí.' WHERE `ID`=19159;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 정도면 만족하십니까?', `MaleText_loc4`='你满意了吧？', `MaleText_loc5`='你滿意了嗎?', `MaleText_loc7`='¿Estás satisfecho?' WHERE `ID`=19160;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='현재까지는 그렇다. 하지만, 계속 분발하기 바란다. 캘타스 왕자님께서는 무너진 하늘 마루에서 수정 실험이 실패한 것에 대해 실망하셨다. 그래서 세나리온의 드루이드들을 대상으로 폭탄을 실험하는 것이다.', `MaleText_loc4`='暂时可以说不错。无论如何，请将我的到来作为一个催促的信号。凯尔萨斯王子对坠星山地区的水晶实验的失败很不满意，这也是我们选择塞纳里奥的德鲁伊们作为炸弹试验地的原因之一。', `MaleText_loc5`='就目前而言，沒錯。不過，讓我的存在成為一種動力。凱爾薩斯王子對於墜天山脈失敗的水晶試驗而生氣。這就是為什麼我們選擇塞納里奧德魯伊作為炸彈測試場地的理由之一。', `MaleText_loc7`='Por el momento, sí. Sin embargo, permite que mi presencia funcione como motivador. El príncipe Kael''thas estaba enfadado por el fracaso del experimento del cristal en Cresta Cielo Estrellado. Esta es una de las razones por las que escogimos a los druidas de Cenarion para probar la bomba.' WHERE `ID`=19162;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 아래 안마당의 마나 폭탄을 조속한 시간 내에 실전에 투입할 수 있도록 준비하지 못하면 어떤 일이 일어날지는 말 안 해도 알지? 놈들이 숲으로 들어간 이후 여기 투렘과 남쪽의 해골이빨 폐허에서 진행 중인 우리 작전을 사사건건 방해하고 있다.', `MaleText_loc4`='如果院子里的那颗魔法炸弹没有很快对目标发射，不需要我再跟你说会发生什么事情了吧？自从我们到了森林里，不管是这里，还是在图雷姆，或是南面的噬骨废墟，他们对我们行动的干扰都愈加地烦人了。', `MaleText_loc5`='我不需要告訴你庭園下方的這個法力炸彈要是未能使用於目標身上會發生什麼事?自從來到這個森林，他們對我們的運作就變得與日俱增的惱人:在這裡，杜瑞以及噬骨者廢墟的南方。', `MaleText_loc7`='No hace falta que te diga lo que pasará si la bomba de maná que está en el patio no se utiliza en su objetivo pronto, ¿verdad? Desde que se trasladaron al bosque, han ido siendo más molestos para nuestras operaciones: aquí, en Tuurem y al sur, en las Ruinas Mascahuesos.' WHERE `ID`=19163;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절대 실패하지 않을 거라 확신합니다, 주인님. 제가 직접 폭탄 제작을 감독하고 있으며 최종 접근암호도 제가 보관하고 있습니다. 하루 안에 이 근처의 벌레들을 폭탄으로 날려버리겠습니다.', `MaleText_loc4`='我向您保证，我们不会失败，我的主人。我亲自监视着工程的每一步，而且最终的密码掌握在我自己手中。一天以内，我就会让炸弹在周围那些讨厌的家伙身边引爆的。', `MaleText_loc5`='我能對你保證我們不失敗，我的主人。我親自監督每個部分的建設，而且我本人握有最後密碼。在一天的時間內，我就可以炸掉附近的那些害蟲。', `MaleText_loc7`='Puedo asegurarte que no fallaremos, maestro. Estoy supervisando personalmente cada aspecto de la construcción, y los códigos finales están en mi poder. Dentro de un día haré que la bomba detone en esos vecinos pesados.' WHERE `ID`=19164;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지켜보겠다, 샤르스! 만약 네 말대로 되지 않으면 너는 천천히 그리고 고통스럽게 죽게 될 것이다.', `MaleText_loc4`='确保这一点，沙尔斯。否则我会亲自看到你慢慢地被折磨致死。', `MaleText_loc5`='別忘了你要做的事，薩爾斯，否則我會親自把你慢慢的折磨至死。', `MaleText_loc7`='Ocúpate de hacerlo, Sharth, o me encargaré personalmente de tu lenta tortura y muerte.' WHERE `ID`=19165;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 근처의 추출기에서 힘을 빨아들입니다...', `MaleText_loc4`='%s开始从附近的蒸馏器里吸取着什么……', `MaleText_loc5`='%s開始從附近的蒸餾器輸送...', `MaleText_loc7`='%s comienza a canalizar del destilador cercano...' WHERE `ID`=19166;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 마법 시전자에게 마법을 반사합니다.', `MaleText_loc4`='%s把法术反射向施法者。', `MaleText_loc5`='%s將法術反射回它的施咒者。', `MaleText_loc7`='%s envía de vuelta el hechizo a quien lo lanzó.' WHERE `ID`=19167;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='셋!', `MaleText_loc4`='3！', `MaleText_loc5`='三!', `MaleText_loc7`='¡TRES!' WHERE `ID`=19168;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='봤습니까? 겨우 세 개밖에 안 들어갔지만 그리 나쁘진 않군요.', `MaleText_loc4`='看到了吗？就是这样。看上去还不错。', `MaleText_loc5`='看見了嗎?那就是它全部內容。它並沒有那麼糟糕。', `MaleText_loc7`='¿Ves? Eso es todo lo que cuesta. No fue tan malo.' WHERE `ID`=19169;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보아하니, 적들이 찾아왔군. 샤르스, 이 문제부터 우선 해결해라. 그런 다음 마나 폭탄으로 놈들의 마을을 파괴하도록!', `MaleText_loc4`='我似乎认得他们。快点解决掉这里的麻烦，沙尔斯。然后用魔法炸弹摧毁他们的城镇！', `MaleText_loc5`='我相信我可以認出他們。 快去處理這件事，薩爾斯。然後帶法力炸彈去毀掉他們的城鎮!', `MaleText_loc7`='Creo que puedo reconocerlos. Ocúpate de esto rápidamente, Sharth. Después, ¡toma la bomba de maná y destruye su ciudad!' WHERE `ID`=19170;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멈춰라!', `MaleText_loc4`='站住！', `MaleText_loc5`='停止!', `MaleText_loc7`='¡Alto!' WHERE `ID`=19171;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일입니까?', `MaleText_loc4`='大人，请问有什么事？', `MaleText_loc5`='這是什麼，我的主人?', `MaleText_loc7`='¿Qué sucede, mi señor?' WHERE `ID`=19172;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자라스, 즉시 검은 사원으로 돌아가라! 내가... 일리단 님의 명령서를 놓고 온 것 같다. 서둘러라!', `MaleText_loc4`='迦拉斯，你必须立即返回黑暗神殿！我……我似乎将伊利丹大人的命令弄丢了！快！', `MaleText_loc5`='薩拉斯你必須立刻返回黑暗神廟!我...我好像弄錯伊利丹王的命令了。快一點!', `MaleText_loc7`='¡Zarath, debes volver al Templo Oscuro de inmediato! Pa... parece que he extraviado las órdenes de Lord Illidan. ¡Rápido!' WHERE `ID`=19173;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 호위는 누가 합니까? 무슨 일이라도 생기면 일리단 님께서 절 가만두지 않으실 겁니다.', `MaleText_loc4`='大人，您显然不是希望我离开您身边吧？如果您有个什么闪失，伊利丹大人一定会惩罚我的。', `MaleText_loc5`='我的主人，當然你不會希望我留下你沒人隨伺。如果你發生了什麼事，伊利丹王會砍掉我的頭。', `MaleText_loc7`='Mi señor, sin duda no esperas que te deje desatendido. Lord Illidan me cortaría la cabeza si te ocurriera algo.' WHERE `ID`=19174;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자라스, 나 혼자서도 얼마든지 해그늘 주둔지까지 갈 수 있다. 서한을 전달하지 않으면 일리단 님께 우리 모두 죽게 될 것이다! 이만 돌아가도록!', `MaleText_loc4`='迦拉斯，我独自前往日蚀岗哨是不会有事的。如果我们未能将信件按时送达，伊利丹大人一定会发怒的！快上路吧！', `MaleText_loc5`='薩拉斯，我絕對有能力能夠前往日蝕崗哨。如果我們不交付書信，伊利丹王會砍掉我們兩個的頭!你被駁回!', `MaleText_loc7`='Zarath, soy perfectamente capaz de subir este camino hasta Punta Eclipse. ¡Si no entregamos la misiva, Lord Illidan nos cortará la cabeza a los dos! ¡Puedes marcharte!' WHERE `ID`=19175;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분부대로 하겠습니다.', `MaleText_loc4`='如您所愿，大人。', `MaleText_loc5`='如你所願，我的主人。', `MaleText_loc7`='Como desees, mi señor.' WHERE `ID`=19176;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 맛있는 내 피엉겅퀴... 아마도 해그늘 주둔지의 더러운 중독자들 중 한 놈이 흘리고 갔겠지.', `MaleText_loc4`='啊，好棒的血蓟……也许是日蚀岗哨那里的某个瘾君子留下来的。', `MaleText_loc5`='啊，甜甜的，甜甜的血薊...或許是那些日蝕崗哨的下流癮君子其中一個留下的。', `MaleText_loc7`='Ah, dulce cardo de sangre... Probablemente olvidado por uno de esos mugrientos adictos de Punta Eclipse.' WHERE `ID`=19177;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들의 손실이 내게 이렇게 큰 기쁨이 되는구나...', `MaleText_loc4`='他们的损失对我来说就是意外的惊喜……', `MaleText_loc5`='他們的損失無疑是我的收穫...', `MaleText_loc7`='Su pérdida es, sin duda, mi ganancia...' WHERE `ID`=19178;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 로브 속에 피엉겅퀴 한 묶음을 넣습니다.', `MaleText_loc4`='%s把血蓟放进了他的袍子里面。', `MaleText_loc5`='%s將這捆血薊放在他的長袍內。', `MaleText_loc7`='%s se mete el fardo de cardos de sangre en la toga.' WHERE `ID`=19179;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='숨어! 놈들이 자네를 발견하기 전에 어서! 물러나란 말이야!', `MaleText_loc4`='躲起来！在他们看到你之前躲起来！后退！', `MaleText_loc5`='躲起來!在他們看見你之前躲起來!支援!', `MaleText_loc7`='¡Escóndete! ¡Escóndete antes de que te vean! ¡Arriba!' WHERE `ID`=19180;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공격 시간이 얼마 안 남았다. 이카리우스를 끝장내라.', `MaleText_loc4`='进攻的时刻即将到来。消灭伊喀琉斯。', `MaleText_loc5`='進攻的時候即將到來。解決伊卡瑞厄斯。', `MaleText_loc7`='El momento de atacar se acerca. Acabad con Icarius.' WHERE `ID`=19181;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보라크, 피엉겅퀴 한 묶음이 더 필요합니다.', `MaleText_loc4`='伯拉克，我需要另一捆血蓟。', `MaleText_loc5`='柏爾拉克，我需要另幾捆血薊。', `MaleText_loc7`='Borak, necesito otro fardo de cardos de sangre.', `FemaleText_loc1`='보라크, 피엉겅퀴 한 묶음이 더 필요해요.', `FemaleText_loc4`='伯拉克，我需要另一捆血蓟。', `FemaleText_loc5`='柏爾拉克，我需要另幾捆血薊。', `FemaleText_loc7`='Borak, necesito otro fardo de cardos de sangre.' WHERE `ID`=19182;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 있다. 다시는 잃어버리지 마라!', `MaleText_loc4`='给你，不要再弄丢了！', `MaleText_loc5`='你擁有它了。不要再次失去它!', `MaleText_loc7`='Toma. ¡No lo vuelvas a perder!' WHERE `ID`=19183;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런, 빌어먹을! 교묘한 함정이었군. 하지만, 안타깝게도 네놈이 살아 돌아가서 얘기를 전할 가망은 없을 것이다...', `MaleText_loc4`='啊，该死！聪明的陷阱。很可惜，你永远不能活着讲述这个故事了……', `MaleText_loc5`='啊，可惡!狡詐的陷阱。糟糕的是你絕對不可能活著去描述這個故事的...', `MaleText_loc7`='¡Ah, malditos sean todos! Buena trampa. Lástima que no vivirás para contar la historia...' WHERE `ID`=19184;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절대 요청이 아니다.', `MaleText_loc4`='确实，这不是一个要求。', `MaleText_loc5`='的確，這不是個請求。', `MaleText_loc7`='Efectivamente, no es una petición.' WHERE `ID`=19185;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='각하!', `MaleText_loc4`='大人！', `MaleText_loc5`='我的主人!', `MaleText_loc7`='¡Mi señor!' WHERE `ID`=19186;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='듀로 마나괴철로가 보강될 것이다! 울트리스 마나괴철로는 끔찍한 재앙이었어. 같은 실수를 반복하지는 않을 것이다!', `MaleText_loc4`='杜隆必须得到增援！乌提斯完全是个灾难。我不允许这种错误重演！', `MaleText_loc5`='杜羅將被強化!奧崔斯完全是一個災難。我絕不會重複那樣的錯誤!', `MaleText_loc7`='¡Se reforzará a Duro! Ultris fue un desastre total. ¡NO permitiré que se repita ese error!' WHERE `ID`=19187;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금까지 우리는 너무나 많은 실패를 겪었다. 지옥불 성채, 무너진 하늘 마루, 불꽃날개 거점... 캘타스 왕자님께서 일이 이 이상 지연되는 것을 용서치 않을 것이다. 나 역시 완벽한 성공을 원한다!', `MaleText_loc4`='一路上我们受到了太多的挫折：地狱火堡垒、坠星山、火翼岗哨……凯尔萨斯王子不能再容忍任何延误了。除了成功，我什么都不想看到。', `MaleText_loc5`='我們一路上已經有太多挫折︰地獄火堡壘，墜天山脈，火翼崗哨...凱爾薩斯王子無法再容忍更多的延宕了。除了絕對的成功之外，我將無法容忍其他了!', `MaleText_loc7`='Hemos sufrido demasiados contratiempos por el camino: la Ciudadela del Fuego Infernal, Cresta Cielo Estrellado, Alto Ala de Fuego... El príncipe Kael''thas no tolerará más retrasos. ¡Yo no toleraré más que el éxito total!' WHERE `ID`=19188;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠습니다.', `MaleText_loc4`='遵命，主人。', `MaleText_loc5`='是的，我的主人。', `MaleText_loc7`='Sí, mi señor.' WHERE `ID`=19189;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지켜보겠다, 아르도니스!', `MaleText_loc4`='你给我确保一切正常，阿尔杜尼斯！', `MaleText_loc5`='把它處理好，艾登尼斯!', `MaleText_loc7`='¡Encárgate, Ardonis!' WHERE `ID`=19190;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 폭풍우 요새로 돌아간다. 내가 다시 찾아올 일을 만들지 않도록 주의해라!', `MaleText_loc4`='我要返回风暴要塞了。你们最好不要让我有回来的理由！', `MaleText_loc5`='我正要回去風暴要塞。把這件事處理好，別讓我有回來的理由!', `MaleText_loc7`='Vuelvo a El Castillo de la Tempestad. ¡Encárgate de que no tenga motivos para volver!' WHERE `ID`=19191;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='먼저 이곳부터 정리해라! 지금 하던 대화는 나중에 끝내도록 하겠다.', `MaleText_loc4`='做好你自己的事情！我稍后再回来跟你谈。', `MaleText_loc5`='把你的房子整理好!我稍後會回來結束這次的談話。', `MaleText_loc7`='¡Pon en orden tu casa! Volveré para acabar esta conversación más tarde.' WHERE `ID`=19192;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 장화에서 투척용 나이프를 꺼냅니다!', `MaleText_loc4`='%s从他的靴子里拔出了一把飞刀！', `MaleText_loc5`='%s從他的靴子裡抽出一把飛刀!', `MaleText_loc7`='¡%s se saca un cuchillo para lanzar de la bota!', `FemaleText_loc1`='%s|1이;가; 장화에서 투척용 나이프를 꺼냅니다!', `FemaleText_loc4`='%s从他的靴子里拔出了一把飞刀！', `FemaleText_loc5`='%s從他的靴子裡抽出一把飛刀!', `FemaleText_loc7`='¡%s se saca un cuchillo para lanzar de la bota!' WHERE `ID`=19193;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드와 얼라이언스 놈들에게 교훈을 가르쳐 줘야겠다. 평생 잊지 못할 교훈으로!', `MaleText_loc4`='我们应该给联盟和部落一点教训。刻骨铭心的教训！', `MaleText_loc5`='我認為我們應該教訓一下部落和聯盟。一個令他們不會那麼快忘記的教訓!', `MaleText_loc7`='Creo que deberíamos dar una lección a la Horda y a la Alianza. ¡Una que tarden en olvidar!' WHERE `ID`=19194;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='때론 직접 나서야 할 때도 있는 법이지. 발라모어 샤날!', `MaleText_loc4`='唉，有些时候，有些事情，必须得亲自解决才行。Balamore shanal！', `MaleText_loc5`='唉，有些時候，有些事情，必須得親自解決才行。(薩拉斯語)受死吧!', `MaleText_loc7`='Por desgracia a veces tienes que hacer las cosas tu mismo. ¡Balamore shanal!' WHERE `ID`=19195;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 버려진 목걸이를 내려다봅니다. 슬픔에 찬 그녀가 명가의 영혼을 부르는 매혹의 주문을 외웁니다. 신도레이에 대한 고대의 노래가 방 안에 울려 퍼집니다...', `FemaleText_loc4`='%s低头看着地上的项链。女王带着悲伤的神情吟唱了一段咒语，召唤出上层精灵的灵魂。整个房间中都回响着辛多雷那久远的歌声……', `FemaleText_loc5`='%s看著丟在地上的項鍊。悲傷之中，女士唸出充滿魔力的咒語，召喚精靈貴族的鬼魂前來。房間內迴繞著這首有關辛多雷的遠古之歌...', `FemaleText_loc7`='%s mira el collar recuperado. En su tristeza, la dama desprende un encanto que atrae a los espíritus de los Altonato. En la cámara resuena su antigua canción sobre los sin''dorei...' WHERE `ID`=19197;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 잘될 수도 있었겠군요, $n. 이리 오십시오. 그대에게 드릴 물건이 있습니다.', `MaleText_loc4`='还可以更好一些，$n。过来，我有东西给你。', `MaleText_loc5`='那樣可能會更好，$n。來吧，我有些東西給你。', `MaleText_loc7`='Eso podría haber ido mejor, $n. Ven, tengo algo para ti.' WHERE `ID`=19200;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은행', `MaleText_loc4`='银行', `MaleText_loc5`='銀行', `MaleText_loc7`='Banco', `FemaleText_loc1`='은행', `FemaleText_loc4`='银行', `FemaleText_loc5`='銀行', `FemaleText_loc7`='Banco' WHERE `ID`=19201;
