UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비행 조련사', `MaleText_loc4`='飞行管理员', `MaleText_loc5`='飛行管理員', `MaleText_loc7`='Maestro de vuelo', `FemaleText_loc1`='비행 조련사', `FemaleText_loc4`='飞行管理员', `FemaleText_loc5`='飛行管理員', `FemaleText_loc7`='Maestro de vuelo' WHERE `ID`=19203;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우체통', `MaleText_loc4`='邮箱', `MaleText_loc5`='郵箱', `MaleText_loc7`='Buzón', `FemaleText_loc1`='우체통', `FemaleText_loc4`='邮箱', `FemaleText_loc5`='郵箱', `FemaleText_loc7`='Buzón' WHERE `ID`=19204;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저에게 주실 물건이 뭡니까, 대사님?', `MaleText_loc4`='你有什么东西要给我，大使？', `MaleText_loc5`='這就是你要給我的東西嗎，大使?', `MaleText_loc7`='¿Qué es lo que tienes para mí, embajador?', `FemaleText_loc1`='저에게 주실 물건이 뭔가요, 대사님?', `FemaleText_loc4`='你有什么东西要给我，大使？', `FemaleText_loc5`='這就是你要給我的東西嗎，大使?', `FemaleText_loc7`='¿Qué es lo que tienes para mí, embajador?' WHERE `ID`=19205;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대가 좋아할 만한 작은 노래 책입니다. 명가의 애가라고 하는 노래의 가사도 들어 있습니다. 실바나스 여군주께서 하늘에서 불렀던 노래죠.', `MaleText_loc4`='只是一本我觉得你可能会喜欢的小歌集而已。里面记录了一首名叫《上层精灵的挽歌》的歌词，那是希尔瓦娜斯心中的天籁之音。', `MaleText_loc5`='只是一本小歌本，我覺得你可能會想要。裡頭有一首稱為貴族的輓歌的歌詞;就是那首令希瓦娜斯·風行者著迷的曲子。', `MaleText_loc7`='Solo un pequeño libro de canciones que pensé que te gustaría tener. Contiene la letra de una canción conocida como El lamento de los Altonato; la que Lady Sylvanas conjuró del aire.' WHERE `ID`=19206;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 근처에 있는 수컷에게 도움을 요청합니다!', `MaleText_loc4`='%s向附近的雄羊呼救！', `MaleText_loc5`='%s向附近的雄鹿呼救!', `MaleText_loc7`='¡%s pide la ayuda de un varón cercano!' WHERE `ID`=19207;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야수 관리인', `MaleText_loc4`='兽栏管理员', `MaleText_loc5`='獸欄管理員', `MaleText_loc7`='Maestro de establos', `FemaleText_loc1`='야수 관리인', `FemaleText_loc4`='兽栏管理员', `FemaleText_loc5`='獸欄管理員', `FemaleText_loc7`='Maestro de establos' WHERE `ID`=19208;
