UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샤트라스에는 은행이 두 개 있는데 둘 다 도시 중앙의 원형 지구 외곽에 있습니다. 하나는 알도르 사제회의 드레나이들이, 또 다른 하나는 점술가 길드의 블러드 엘프들이 운영하고 있지요.', `MaleText_loc4`='沙塔斯城有两座银行，它们都座落在城市中心的边缘上。一座由奥尔多的德莱尼人运作着，而另一座属于血精灵占星者。', `MaleText_loc5`='在撒塔斯有兩家銀行，都沿著市中心的兩邊。一個由德萊尼奧多爾經營，而另一個由血精靈占卜者經營。', `MaleText_loc7`='Hay dos bancos en Shattrath, ambos situados a lo largo del centro de la ciudad. Uno está dirigido por los draenei Aldor, y el otro por los elfos de sangre Arúspices.', `FemaleText_loc1`='샤트라스에는 은행이 두 개 있는데 둘 다 도시 중앙의 원형 지구 외곽에 있습니다. 하나는 알도르 사제회의 드레나이들이, 또 다른 하나는 점술가 길드의 블러드 엘프들이 운영하고 있지요.', `FemaleText_loc4`='沙塔斯城有两座银行，它们都座落在城市中心的边缘上。一座由奥尔多的德莱尼人运作着，而另一座属于血精灵占星者。', `FemaleText_loc5`='在撒塔斯有兩家銀行，都沿著市中心的兩邊。一個由德萊尼奧多爾經營，而另一個由血精靈占卜者經營。', `FemaleText_loc7`='Hay dos bancos en Shattrath, ambos situados a lo largo del centro de la ciudad. Uno está dirigido por los draenei Aldor, y el otro por los elfos de sangre Arúspices.' WHERE `ID`=19211;
