UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알도르 사제회 은행은 도시 중심부의 북서쪽에 있습니다.', `MaleText_loc4`='奥尔多银行座落在城市中心的西北。', `MaleText_loc5`='奧多爾銀行位於市中心的西北方。', `MaleText_loc7`='El banco de los Aldor está situado al noroeste del centro de la ciudad.', `FemaleText_loc1`='알도르 사제회 은행은 도시 중심부의 북서쪽에 있습니다.', `FemaleText_loc4`='奥尔多银行座落在城市中心的西北。', `FemaleText_loc5`='奧多爾銀行位於市中心的西北方。', `FemaleText_loc7`='El banco de los Aldor está situado al noroeste del centro de la ciudad.' WHERE `ID`=19214;
