UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샤트라스의 여관은 부상당한 난민들로 꽉 차 있답니다. 하지만, 각각 알도르 마루와 점술가 언덕에 있는 알도르 사제회와 점술가 길드로 가면 묵을 곳이 있을 겁니다.', `MaleText_loc4`='沙塔斯城的旅店里住满了受伤的难民。尽管如此，在奥尔多高地和占星者之台还有属于奥尔多的德莱尼人和血精灵占星者自己的旅店。', `MaleText_loc5`='撒塔斯的旅店裡充滿受傷的難民。不過，在奧多爾高地的德萊尼奧多爾和占卜者階梯的血精靈占卜者之中還有空房間。', `MaleText_loc7`='Las posadas de Shattrath están llenas de refugiados heridos. Aun así, hay espacio entre los draenei Aldor y los elfos de sangre Arúspices en Alto Aldor y la Grada del Arúspice.', `FemaleText_loc1`='샤트라스의 여관은 부상당한 난민들로 꽉 차 있답니다. 하지만, 각각 알도르 마루와 점술가 언덕에 있는 알도르 사제회와 점술가 길드로 가면 묵을 곳이 있을 겁니다.', `FemaleText_loc4`='沙塔斯城的旅店里住满了受伤的难民。尽管如此，在奥尔多高地和占星者之台还有属于奥尔多的德莱尼人和血精灵占星者自己的旅店。', `FemaleText_loc5`='撒塔斯的旅店裡充滿受傷的難民。不過，在奧多爾高地的德萊尼奧多爾和占卜者階梯的血精靈占卜者之中還有空房間。', `FemaleText_loc7`='Las posadas de Shattrath están llenas de refugiados heridos. Aun así, hay espacio entre los draenei Aldor y los elfos de sangre Arúspices en Alto Aldor y la Grada del Arúspice.' WHERE `ID`=19216;
