UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알도르 사제회 여관은 샤트라스 상층, 알도르 마루에 있습니다. 그곳으로 가는 승강기는 도시 중심의 북서쪽에 있습니다.', `MaleText_loc4`='奥尔多旅店坐落在沙塔斯城高处的奥尔多高地上。在城市中心的西北方有去那里的升降梯。', `MaleText_loc5`='奧多爾旅店位於撒塔斯城更上層，在奧多爾高地上。通往那裡的升降梯就在市中心的西北邊。', `MaleText_loc7`='La posada Aldor está situada sobre la Ciudad de Shattrath, en Alto Aldor. El elevador para ir está al noroeste del centro de la ciudad.', `FemaleText_loc1`='알도르 사제회 여관은 샤트라스 상층, 알도르 마루에 있습니다. 그곳으로 가는 승강기는 도시 중심의 북서쪽에 있습니다.', `FemaleText_loc4`='奥尔多旅店坐落在沙塔斯城高处的奥尔多高地上。在城市中心的西北方有去那里的升降梯。', `FemaleText_loc5`='奧多爾旅店位於撒塔斯城更上層，在奧多爾高地上。通往那裡的升降梯就在市中心的西北邊。', `FemaleText_loc7`='La posada Aldor está situada sobre la Ciudad de Shattrath, en Alto Aldor. El elevador para ir está al noroeste del centro de la ciudad.' WHERE `ID`=19219;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='점술가 길드 여관은 샤트라스의 상층, 점술가 언덕에 있습니다. 그곳으로 가는 승강기는 도시 중심의 남서쪽에 있으니 그리로 가보십시오.', `MaleText_loc4`='占星者旅店坐落在沙塔斯城的占星者平台上。在城市中心的西南方有去那里的升降梯。', `MaleText_loc5`='占卜者旅店位於撒塔斯城的上面，就在占卜者階梯。通往那裡的升降梯就在市中心的西南邊。', `MaleText_loc7`='La posada Arúspice está situada sobre la Ciudad de Shattrath, en la Grada del Arúspice. El elevador para ir está al suroeste del centro de la ciudad.', `FemaleText_loc1`='점술가 길드 여관은 샤트라스의 상층, 점술가 언덕에 있습니다. 그곳으로 가는 승강기는 도시 중심의 남서쪽에 있으니 그리로 가보십시오.', `FemaleText_loc4`='占星者旅店坐落在沙塔斯城的占星者平台上。在城市中心的西南方有去那里的升降梯。', `FemaleText_loc5`='占卜者旅店位於撒塔斯城的上面，就在占卜者階梯。通往那裡的升降梯就在市中心的西南邊。', `FemaleText_loc7`='La posada Arúspice está situada sobre la Ciudad de Shattrath, en la Grada del Arúspice. El elevador para ir está al suroeste del centro de la ciudad.' WHERE `ID`=19220;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샤트라스의 비행 조련사인 뉴트랄은 도시 중심부의 동쪽에서 찾을 수 있을 겁니다.', `MaleText_loc4`='沙塔斯城的飞行管理员是努特拉尔。你可以在城市中心的东面方找到他。', `MaleText_loc5`='撒塔斯的飛行管理員是紐卓。你可在市中心東邊找到他。', `MaleText_loc7`='El maestro de vuelo de Shattrath es Nutral. Lo encontrarás al este del centro de la ciudad.', `FemaleText_loc1`='샤트라스의 비행 조련사인 뉴트랄은 도시 중심부의 동쪽에서 찾을 수 있을 겁니다.', `FemaleText_loc4`='沙塔斯城的飞行管理员是努特拉尔。你可以在城市中心的东面方找到他。', `FemaleText_loc5`='撒塔斯的飛行管理員是紐卓。你可在市中心東邊找到他。', `FemaleText_loc7`='El maestro de vuelo de Shattrath es Nutral. Lo encontrarás al este del centro de la ciudad.' WHERE `ID`=19221;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우체통은 알도르 사제회와 점술가 길드의 은행과 여관 안팎에서 찾을 수 있습니다.', `MaleText_loc4`='奥尔多和占星者的银行或者旅店附近都有邮箱。', `MaleText_loc5`='你能在奧多爾和占卜者銀行和旅店裡外找到郵箱。', `MaleText_loc7`='Encontrarás buzones de correos dentro o justo fuera de los bancos y posadas de los Aldor y los Arúspices.', `FemaleText_loc1`='우체통은 알도르 사제회와 점술가 길드의 은행과 여관 안팎에서 찾을 수 있습니다.', `FemaleText_loc4`='奥尔多和占星者的银行或者旅店附近都有邮箱。', `FemaleText_loc5`='你能在奧多爾和占卜者銀行和旅店裡外找到郵箱。', `FemaleText_loc7`='Encontrarás buzones de correos dentro o justo fuera de los bancos y posadas de los Aldor y los Arúspices.' WHERE `ID`=19222;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야수 관리인은 알도르 마루의 드레나이 여관과 점술가 언덕의 블러드 엘프 여관 바로 밖에 있습니다.', `MaleText_loc4`='在奥尔多高地的德莱尼旅店和占星者平台的血精灵旅店外面都能找到兽栏管理员。', `MaleText_loc5`='在奧多爾高地的德萊尼旅店和占卜者階梯的血精靈旅店外面就有獸欄管理員。', `MaleText_loc7`='Hay maestros de establos justo fuera de las posadas de los draenei y los elfos de sangre, en Alto Aldor y la Grada del Arúspice.', `FemaleText_loc1`='야수 관리인은 알도르 마루의 드레나이 여관과 점술가 언덕의 블러드 엘프 여관 바로 밖에 있습니다.', `FemaleText_loc4`='在奥尔多高地的德莱尼旅店和占星者平台的血精灵旅店外面都能找到兽栏管理员。', `FemaleText_loc5`='在奧多爾高地的德萊尼旅店和占卜者階梯的血精靈旅店外面就有獸欄管理員。', `FemaleText_loc7`='Hay maestros de establos justo fuera de las posadas de los draenei y los elfos de sangre, en Alto Aldor y la Grada del Arúspice.' WHERE `ID`=19223;
