UPDATE `locales_broadcast_text` SET `MaleText_loc1`='점술가 길드 야수 관리인', `MaleText_loc4`='占星者兽栏', `MaleText_loc5`='占卜者獸欄', `MaleText_loc7`='Establo Arúspice', `FemaleText_loc1`='점술가 길드 야수 관리인', `FemaleText_loc4`='占星者兽栏', `FemaleText_loc5`='占卜者獸欄', `FemaleText_loc7`='Establo Arúspice' WHERE `ID`=19225;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샤트라스의 전투모병관들은 도시 상층부와 고난의 거리를 연결하는 계단에서 자주 모임을 한답니다. 얼라이언스 전투모병관들과 호드 전투모병관은 각기 다른 곳에서 모여 있으며, 투기장 사무관은 전투모병관들의 맞은편에 있습니다.', `MaleText_loc4`='沙塔斯城的军官们经常聚集在上层平台和贫民窟之间的楼梯口。联盟的军官们在一个地方，部落的在另一个地方，竞技场管理员在他们中间。', `MaleText_loc5`='撒塔斯的戰場軍官經常群聚在上城及陰鬱城之間的樓梯井那。聯盟戰場軍官都在同一處，而部落則是在另外一邊，競技場戰場軍官就介於中間面對著他們。', `MaleText_loc7`='Los maestros de guerra de Shattrath a menudo se congregan en los huecos de las escaleras entre la parte alta y baja de la ciudad. Los maestros de guerra de la Alianza se reúnen en un lugar, y los de la Horda en otro, con los maestros de batalla de arena entre ellos y en el extremo contrario.', `FemaleText_loc1`='샤트라스의 전투모병관들은 도시 상층부와 고난의 거리를 연결하는 계단에서 자주 모임을 한답니다. 얼라이언스 전투모병관들과 호드 전투모병관은 각기 다른 곳에서 모여 있으며, 투기장 사무관은 전투모병관들의 맞은편에 있습니다.', `FemaleText_loc4`='沙塔斯城的军官们经常聚集在上层平台和贫民窟之间的楼梯口。联盟的军官们在一个地方，部落的在另一个地方，竞技场管理员在他们中间。', `FemaleText_loc5`='撒塔斯的戰場軍官經常群聚在上城及陰鬱城之間的樓梯井那。聯盟戰場軍官都在同一處，而部落則是在另外一邊，競技場戰場軍官就介於中間面對著他們。', `FemaleText_loc7`='Los maestros de guerra de Shattrath a menudo se congregan en los huecos de las escaleras entre la parte alta y baja de la ciudad. Los maestros de guerra de la Alianza se reúnen en un lugar, y los de la Horda en otro, con los maestros de batalla de arena entre ellos y en el extremo contrario.' WHERE `ID`=19226;
