UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연금술의 거장 로로킴과 스케티스 추방자는 고난의 거리 북서쪽 지역에서 다른 아라코아들과 함께 산답니다.', `MaleText_loc4`='斯克提斯流浪者，宗师级炼金师罗罗基姆和与其他鸦人一起住在贫民窟的西北。', `MaleText_loc5`='大鍊金師羅洛其恩與司凱堤斯流亡者，和一群阿拉卡一起住在陰鬱城的西北方。', `MaleText_loc7`='Lorokeem, gran maestro alquimista y marginado de Skettis, vive entre los otros Arakkoa en la parte noreste del Bajo Arrabal.', `FemaleText_loc1`='연금술의 거장 로로킴과 스케티스 추방자는 고난의 거리 북서쪽 지역에서 다른 아라코아들과 함께 살지요.', `FemaleText_loc4`='斯克提斯流浪者，宗师级炼金师罗罗基姆和与其他鸦人一起住在贫民窟的西北。', `FemaleText_loc5`='大鍊金師羅洛其恩與司凱堤斯流亡者，和一群阿拉卡一起住在陰鬱城的西北方。', `FemaleText_loc7`='Lorokeem, gran maestro alquimista y marginado de Skettis, vive entre los otros arakkoa en la parte noroeste del Bajo Arrabal.' WHERE `ID`=19239;
