UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세상의 끝 선술집은 고난의 거리의 동쪽 끝에서 찾을 수 있습니다.', `MaleText_loc4`='在贫民窟的最东面可以找到天涯旅店。', `MaleText_loc5`='世界的盡頭小酒館就在陰鬱城裡最東邊的那裡。', `MaleText_loc7`='La Taberna del Fin del Mundo se puede encontrar en la parte más oriental de la ciudad baja.', `FemaleText_loc1`='세상의 끝 선술집은 고난의 거리의 동쪽 끝에서 찾을 수 있습니다.', `FemaleText_loc4`='在贫民窟的最东面可以找到天涯旅店。', `FemaleText_loc5`='世界的盡頭小酒館就在陰鬱城裡最東邊的那裡。', `FemaleText_loc7`='La Taberna del Fin del Mundo se puede encontrar en la parte más oriental de la ciudad baja.' WHERE `ID`=19242;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고위 마법부여사 바르돌란은 점술가 언덕의 현자의 도서관에서 만날 수 있습니다. 예술의 대가인 그를 그의 제자들인 장인과 전문가, 그리고 수습생들이 둘러싸고 있지요.', `MaleText_loc4`='高阶附魔师巴尔杜兰在占星者平台的先知图书馆。他是附魔的宗师，身边环绕着他的学生：初级附魔师，中级附魔师，高级附魔师和大师级附魔师。', `MaleText_loc5`='你也許可以在占卜者階梯的先知書庫裡找到最高附魔師巴多蘭。身為一位藝術大師，他身邊總是圍著他的學生︰大師，工匠，專家和短工。', `MaleText_loc7`='El sumo encantador Bardolan se puede encontrar en la Biblioteca del Profeta, en la Grada del Arúspice. Es un gran maestro del arte y está rodeado de sus estudiantes: maestros, artesanos, expertos y oficiales.', `FemaleText_loc1`='고위 마법부여사 바르돌란은 점술가 언덕의 현자의 도서관에서 찾을 수 있습니다. 예술의 대가인 그를 그의 제자들인 장인과 전문가, 그리고 수습생들이 둘러싸고 있지요.', `FemaleText_loc4`='高阶附魔师巴尔杜兰在占星者平台的先知图书馆。他是附魔的宗师，身边环绕着他的学生：初级附魔师，中级附魔师，高级附魔师和大师级附魔师。', `FemaleText_loc5`='你也許可以在占卜者階梯的先知書庫裡找到最高附魔師巴多蘭。身為一位藝術大師，他身邊總是圍著他的學生︰大師，工匠，專家和短工。', `FemaleText_loc7`='El sumo encantador Bardolan se puede encontrar en la Biblioteca del Profeta, en la Grada del Arúspice. Es un gran maestro del arte y está rodeado de sus estudiantes: maestros, artesanos, expertos y oficiales.' WHERE `ID`=19243;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='한숨을 쉬던 %s|1이;가; 무릎을 꿇고 아뮬렛을 집습니다.', `FemaleText_loc4`='%s叹了口气，跪下身捡起了护符。', `FemaleText_loc5`='嘆氣，%s跪下並且得到護符。', `FemaleText_loc7`='Suspirando, %s se arrodilla y recoge el amuleto.' WHERE `ID`=19244;
