UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방어구와 무기를 제작하는 크라두 그림블레이드와 줄라 슬래그퓨리는 고난의 거리의 대용광로에서 일을 하고 있으니 그리로 가보십시오.', `MaleText_loc4`='护甲和武器工匠克拉度·利刃和祖拉·熔怒在贫民窟的大熔炉那里工作。', `MaleText_loc5`='你也許可以在陰鬱城的一座大熔爐那找到護甲和武器工匠克拉杜·恐懼之刃和祖拉·渣怒。', `MaleText_loc7`='Los artesanos de armaduras y armas Kradu Filosiniestro y Zula Furiascoria se pueden encontrar trabajando en una gran forja de la parte baja de la ciudad.', `FemaleText_loc1`='방어구와 무기를 제작하는 크라두 그림블레이드와 줄라 슬래그퓨리는 고난의 거리의 대용광로에서 일을 하고 있으니 그리로 가보십시오.', `FemaleText_loc4`='护甲和武器工匠克拉度·利刃和祖拉·熔怒在贫民窟的大熔炉那里工作。', `FemaleText_loc5`='你也許可以在陰鬱城的一座大熔爐那找到護甲和武器工匠克拉杜·恐懼之刃和祖拉·渣怒。', `FemaleText_loc7`='Los artesanos de armaduras y armas Kradu Filosiniestro y Zula Furiascoria se pueden encontrar trabajando en una gran forja de la parte baja de la ciudad.' WHERE `ID`=19250;
