UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위장복이 하나 더 필요합니다, 보라크. 지난 번에 주신 것을 잃어버렸습니다.', `MaleText_loc4`='我需要另一个伪装，伯拉克。上一个被我弄丢了。', `MaleText_loc5`='我需要另一個偽裝，柏爾拉克。我失去最後一個了。', `MaleText_loc7`='Necesito otro disfraz, Borak. El último lo perdí.', `FemaleText_loc1`='위장복이 하나 더 필요합니다, 보라크. 지난 번에 주신 것을 잃어버렸습니다.', `FemaleText_loc4`='我需要另一个伪装，伯拉克。上一个被我弄丢了。', `FemaleText_loc5`='我需要另一個偽裝，柏爾拉克。我失去最後一個了。', `FemaleText_loc7`='Necesito otro disfraz, Borak. El último lo perdí.' WHERE `ID`=19252;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 있네. 이번에는 좀 더 조심하게나, $n.', `MaleText_loc4`='再试一次，记得小心点，$n。', `MaleText_loc5`='一定要測試，並且要更小心點，$n。', `MaleText_loc7`='Intenta tener más cuidado, $n.' WHERE `ID`=19253;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 우리에게 동료가 생겼군!', `MaleText_loc4`='赶快，我们有朋友来了！', `MaleText_loc5`='快點，我們有伴了!', `MaleText_loc7`='¡Estad más activos, tenemos compañía!' WHERE `ID`=19254;
