UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전부 처리하겠습니다.', `MaleText_loc4`='我来了。', `MaleText_loc5`='我照單全收。', `MaleText_loc7`='Ya lo he superado.', `FemaleText_loc1`='전부 처리하겠습니다.', `FemaleText_loc4`='我来了。', `FemaleText_loc5`='我照單全收。', `FemaleText_loc7`='Ya lo he superado.' WHERE `ID`=19256;
