UPDATE `locales_broadcast_text` SET `MaleText_loc1`='없애버릴 녀석이라도 있습니까?', `MaleText_loc4`='需要我消灭什么东西吗？', `MaleText_loc5`='有東西需要被摧毀嗎?', `MaleText_loc7`='¿Hay que destruir algo?', `FemaleText_loc1`='없애버릴 녀석이라도 있나요?', `FemaleText_loc4`='需要我消灭什么东西吗？', `FemaleText_loc5`='有東西需要被摧毀嗎?', `FemaleText_loc7`='¿Hay que destruir algo?' WHERE `ID`=19258;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도움이 필요합니까, 여러분?', `MaleText_loc4`='你们需要什么帮助吗？', `MaleText_loc5`='你們需要幫忙?', `MaleText_loc7`='¿Necesitáis algo de ayuda, muchachos?', `FemaleText_loc1`='도움이 필요하신가요, 여러분?', `FemaleText_loc4`='你们需要什么帮助吗？', `FemaleText_loc5`='你們需要幫忙?', `FemaleText_loc7`='¿Necesitáis algo de ayuda, muchachos?' WHERE `ID`=19259;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일리단 님의 전갈을 가져왔습니다.', `MaleText_loc4`='我带来了伊利丹大人的口谕。', `MaleText_loc5`='我帶來伊利丹王的話。', `MaleText_loc7`='Traigo mensaje de Lord Illidan.', `FemaleText_loc1`='일리단 님의 전갈을 가져왔습니다.', `FemaleText_loc4`='我带来了伊利丹大人的口谕。', `FemaleText_loc5`='我帶來伊利丹王的話。', `FemaleText_loc7`='Traigo mensaje de Lord Illidan.' WHERE `ID`=19260;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말해 보시오.', `MaleText_loc4`='我在听。', `MaleText_loc5`='我正在聽。', `MaleText_loc7`='Escucho.' WHERE `ID`=19261;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='암호 조각을 옮겨야 합니다. 줄루헤드에게 전달하십시오.', `MaleText_loc4`='把密码碎片运走，送到祖鲁希德那里去。', `MaleText_loc5`='這個密碼碎片需要移至他處。將它送交給祖魯希德。', `MaleText_loc7`='El fragmento de la Clave se debe trasladar. Entregádselo a Zuluhed.', `FemaleText_loc1`='암호 조각을 옮겨야 합니다. 줄루헤드에게 전달하십시오.', `FemaleText_loc4`='把密码碎片运走，送到祖鲁希德那里去。', `FemaleText_loc5`='這個密碼碎片需要移至他處。將它送交給祖魯希德。', `FemaleText_loc7`='El fragmento de la Clave se debe trasladar. Entregádselo a Zuluhed.' WHERE `ID`=19262;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='벨로레...', `FemaleText_loc4`='Belore……', `FemaleText_loc5`='(薩拉斯語)陽光...', `FemaleText_loc7`='Belore...' WHERE `ID`=19263;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s의 손이 비전 에너지로 빛나기 시작합니다!', `MaleText_loc4`='%s的手开始放射出奥术能量的光芒！', `MaleText_loc5`='%s的手開始發光，光芒中隱含秘法能量!', `MaleText_loc7`='¡La mano de %s comienza a brillar de energía Arcana!' WHERE `ID`=19264;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐요? 이 명령을 증명하는 서류는 물론 가져왔겠지?', `MaleText_loc4`='哦？那么你当然也把相关的书面文件带来了吧？', `MaleText_loc5`='噢?你一定帶著書面文件來證明你的請求吧。', `MaleText_loc7`='¿Oh? Por supuesto, tienes documentos que documentan esta solicitud.' WHERE `ID`=19265;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='루스크, 제 말을 제대로 이해하지 못한 모양이군요. 난 일리단 님을 대신하여 그분께서 직접 내리신 명령을 전달하는 중입니다!', `MaleText_loc4`='也许你耳朵不太灵光，卢斯克。我向你传达的是伊利丹大人亲自发布的命令！', `MaleText_loc5`='或許你沒聽到我的話，魯斯克。我正交付給你一個來自伊利丹本人的命令!', `MaleText_loc7`='Quizás no me hayas oído, Ruusk. ¡Te estoy dando una orden del mismo Illidan!', `FemaleText_loc1`='루스크, 제 말을 제대로 이해하지 못한 모양이군요. 난 일리단 님을 대신하여 그분께서 직접 내리신 명령을 전달하는 중입니다!', `FemaleText_loc4`='也许你耳朵不太灵光，卢斯克。我向你传达的是伊利丹大人亲自发布的命令！', `FemaleText_loc5`='或許你沒聽到我說的話，魯斯克。我正交付給你一個來自伊利丹本人的命令!', `FemaleText_loc7`='Quizás no me hayas oído, Ruusk. ¡Te estoy dando una orden del mismo Illidan!' WHERE `ID`=19266;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='똑똑히 들으시오. 우리는 암호 조각을 전달하고 안전하게 보관하는 임무를 맡고 있소. 사절은 일리단 님께서 직접 봉인하신 서한을 가져와야 하오. 서한이 없으면 조각을 전달할 수 없소.', `MaleText_loc4`='听我说，苦工。我们对于运送和保护密码碎片有着严格的流程。大使传达盖有伊利丹大人徽记的信件。没有信件就免谈。', `MaleText_loc5`='聽我說，苦工。我們有一套交付和保管這個密碼碎片的流程。特使交付由伊利丹王密封的書信。沒有書信，就不能運送。', `MaleText_loc7`='Escúchame, peón. Tenemos un proceso para la entrega y custodia del fragmento de la Clave. El enviado entrega la misiva, que ha sido sellada por Lord Illidan. Sin misiva, no hay traslado.' WHERE `ID`=19267;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠습니다. 검은 사원으로 돌아가서 당신이 명령에 불복종했다고 일리단 님께 말씀드리겠습니다. 당신이 조만간 이 세계를 뜰 거라고 미리 부하들에게 알려두는 게 좋을 거요.', `MaleText_loc4`='好吧。我会返回黑暗神殿，告诉伊利丹大人你不想让他如愿。我建议你准备后事吧，告诉你的手下，你即将离开这个世界了。', `MaleText_loc5`='非常好。我會回去黑暗神廟報告伊利丹王你不願意執行他所期望的任務。我建議你可以跟你的下屬交代一下，讓他們知道你很快就會離開這個世界了。', `MaleText_loc7`='Muy bien. Volveré al Templo Oscuro y notificaré a Lord Illidan de tu falta de voluntad de llevar a cabo sus deseos. Sugiero que te organices con tus subordinados y les hagas saber que pronto dejarás este mundo.', `FemaleText_loc1`='알겠습니다. 검은 사원으로 돌아가서 당신이 명령에 불복종했다고 일리단 님께 말씀드리겠습니다. 당신이 조만간 이 세계를 뜰 거라고 미리 부하들에게 알려두는 게 좋을 거요.', `FemaleText_loc4`='好吧。我会返回黑暗神殿，告诉伊利丹大人你不想让他如愿。我建议你准备后事吧，告诉你的手下，你即将离开这个世界了。', `FemaleText_loc5`='非常好。我會回去黑暗神廟報告伊利丹王你不願意執行他所期望的任務。我建議你可以跟你的下屬交代一下，讓他們知道你很快就會離開這個世界了。', `FemaleText_loc7`='Muy bien. Volveré al Templo Oscuro y notificaré a Lord Illidan de tu falta de voluntad de llevar a cabo sus deseos. Sugiero que te organices con tus subordinados y les hagas saber que pronto dejarás este mundo.' WHERE `ID`=19268;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<감정을 억누르고 마른 침을 삼키는 루스크>$B$B그게... 무슨 말씀이시오?', `MaleText_loc4`='<卢斯克艰难地咽了口唾沫。>$B$B我……你是什么意思？', `MaleText_loc5`='<魯斯克困難地嚥下唾液。>$B$B我...你是什麼意思?', `MaleText_loc7`='<Ruusk traga saliva.>$B$BYo... ¿Qué quieres decir?' WHERE `ID`=19269;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='굳이 말로 설명할 필요가 있나요? 일리단 님께서 명령을 거역하는 자에게 어떤 처벌을 내리는지 당신도 잘 알지 않습니까? 이제 저는 가보겠습니다! 안녕, 루스크! 영원히...', `MaleText_loc4`='真的需要让我描述每一个残酷的细节吗？我想我们都很清楚伊利丹大人会如何处置那些违背他命令的人！现在，我必须走了！保重，卢斯克！永别了……', `MaleText_loc5`='我需要詳述令人恐懼的執行細節嗎?我認為我們倆完全知道伊利丹王會怎樣處理違抗他命令的那些人。現在，我必須離開!再會了，魯斯克!永遠...', `MaleText_loc7`='¿Tengo que entrar en detalles sangrientos? Creo que ambos sabemos lo que Lord Illidan hace con aquellos que se enfrentan a sus palabras. ¡Bueno, debo partir! ¡Adiós, Ruusk! Para siempre...', `FemaleText_loc1`='굳이 말로 설명할 필요가 있나요? 일리단 님께서 명령을 거역하는 자에게 어떤 처벌을 내리는지 당신도 잘 알지 않습니까? 이제 저는 가보겠습니다! 안녕, 루스크! 영원히...', `FemaleText_loc4`='真的需要让我描述每一个残酷的细节吗？我想我们都很清楚伊利丹大人会如何处置那些违背他命令的人！现在，我必须走了！保重，卢斯克！永别了……', `FemaleText_loc5`='我需要詳述令人恐懼的執行細節嗎?我認為我們倆完全知道伊利丹王會怎樣處理違抗他命令的那些人。現在，我必須離開!再會了，魯斯克!永遠...', `FemaleText_loc7`='¿Tengo que entrar en detalles sangrientos? Creo que ambos sabemos lo que Lord Illidan hace con aquellos que se enfrentan a sus palabras. ¡Bueno, debo partir! ¡Adiós, Ruusk! Para siempre...' WHERE `ID`=19270;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐, 어딜 그리 바삐 가시오? 그대는 물건을 전달해야 하지 않소? 일은 해야지... 그러면 되지 않겠소? 용아귀 부족의 줄루헤드라고? 물건이 그에게 갈 거요. 일리단 님께는 해그늘 블러드 엘프들이 성심껏 협조해서 명령 수행에 큰 어려움이 없었다고 말씀드려 주시오.$B$B내가 직접 암흑의 인도자 루울을 보내서 조각을 전달하겠소!$B$B루울, 내 말 잘 들었지?', `MaleText_loc4`='等等，你要去哪里？你要我转移碎片，对吗？我马上就安排，行不行？是送给龙喉堡垒的祖鲁希德吗？包在我们身上了。请让伊利丹大人知道，日蚀部队一定不辱使命。$B$B我会派亵渎者鲁尔亲自运送碎片的！$B$B你都听清楚了吧，我说的是鲁尔……', `MaleText_loc5`='等等。你要去哪兒?你需要把東西運送出去，對嗎?讓我們完成這個工作，好嗎?祖魯希德在龍喉嗎?他會收到這個東西。請讓伊利丹王知道伊克利普森完全遵從他的命令並且合作完成了。$B$B我將派遣『晦暗者』魯歐親自遞交這個碎片!$B$B你聽到了，對吧 - 魯歐...', `MaleText_loc7`='Espera. ¿Dónde vas? Necesitabas un traslado, ¿no es correcto? Pues acabemos con ello, ¿de acuerdo? ¿Zuluhed en Faucedraco? Así se hará. Haz saber a Lord Illidan que sus órdenes se llevaron a cabo con la entera colaboración de los eclipsianos.$B$B¡Enviaré a Ruul el Ensombrecedor para que entregue personalmente el fragmento!$B$BMe has oído bien - Ruul...' WHERE `ID`=19271;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='루스크, 현명한 판단입니다. 감사합니다. 그럼 이만...', `MaleText_loc4`='啊，至少你的脑子还不蠢，卢斯克。多谢，请保重。', `MaleText_loc5`='啊，有你到這裡來真好，魯斯克。感謝你，再會。', `MaleText_loc7`='Ah, me alegro de que estés aquí, Ruusk. Gracias y adiós.', `FemaleText_loc1`='루스크, 현명한 판단입니다. 감사합니다. 그럼 이만...', `FemaleText_loc4`='啊，至少你的脑子还不蠢，卢斯克。多谢，请保重。', `FemaleText_loc5`='啊，有你到這裡來真好，魯斯克。感謝你，再會。', `FemaleText_loc7`='Ah, me alegro de que estés aquí, Ruusk. Gracias y adiós.' WHERE `ID`=19272;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당장에라도 도끼를 내리칠 준비가 된 %s|1이;가; 당신의 뒤로 왔다갔다합니다.', `MaleText_loc4`='%s走到你的背后，高举手中的斧子。', `MaleText_loc5`='%s與他的斧準備好跟隨你。', `MaleText_loc7`='%s se coloca tras de ti con su hacha preparada.' WHERE `ID`=19273;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모든 준비가 완료되었습니다, 전쟁인도자님.', `MaleText_loc4`='万事俱备了，战争使者。', `MaleText_loc5`='一切事情都準備好了，戰爭使者。', `MaleText_loc7`='Todo está dispuesto, belisario.' WHERE `ID`=19274;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전쟁인도자님, 그러려면 요새의 지옥불정령을 모조리 동원해야 합니다. 자칫하면 역습을 당할 수가 있습니다.', `MaleText_loc4`='战争使者，这可能需要动用要塞中所有的地狱火，我们也许会很容易遭到反击。', `MaleText_loc5`='戰爭使者，那將需要用到所有堡壘的煉獄火。那有可能使我們對反擊難以防禦。', `MaleText_loc7`='Belisario, eso requerirá el uso de todos los infernales del bastión. Puede que nos deje vulnerables ante un contraataque.' WHERE `ID`=19275;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하나도 안 무섭다고! 덤벼! 앞발 두 개를 몽땅 꺼내서 할퀴어주마!', `MaleText_loc4`='我不怕你们！你们想打架？那就来呀！来呀！我不用前爪都可以打败你们！', `MaleText_loc5`='我不是害怕你!你想要戰鬥嗎?啊，你是嗎?來! 我將把兩支爪子放在背後跟你戰鬥!', `MaleText_loc7`='¡No les tengo miedo! ¿Quieren pelear? ¡Bien! ¡Vamos, pelearé con las garras en la espalda!' WHERE `ID`=19276;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희를 어떻게 해주면 좋을까? 아무 생각도 나지 않아!', `MaleText_loc4`='我该把你怎么办？我完全不知道。', `MaleText_loc5`='現在我該與你做什麼?我完全不能決定。', `MaleText_loc7`='¿Que debería hacer contigo? No me puedo decidir.' WHERE `ID`=19277;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나도 심장 갖고 싶어. 너희들 것 나한테 주면 안 될까?', `MaleText_loc4`='我真的需要一颗心。啊，用你的行吗？', `MaleText_loc5`='我真的能使用心。嘿，我能有你的心嗎?', `MaleText_loc7`='¿Me vendría bien un corazón? Digamos, ¿el tuyo?' WHERE `ID`=19278;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말씀하신 대로 행하겠습니다, 전쟁인도자님. 질문이 하나 있습니다만 여쭤도 되올지요...', `MaleText_loc4`='谨遵教诲，战争使者。还有最后一个问题，我是否可以……', `MaleText_loc5`='應該如你所說的，戰爭使者。最後一個問題，如果我可以的話...', `MaleText_loc7`='Se hará como dices, belisario. Una última pregunta, si se me permite...' WHERE `ID`=19279;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 상자 안에 뭐가 들어 있는 겁니까?', `MaleText_loc4`='箱子里有什么？', `MaleText_loc5`='木箱裡的是什麼東西?', `MaleText_loc7`='¿Qué hay en la caja?' WHERE `ID`=19280;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상자? 너한테 상자를 보낸 적이 없다, 조바안. 이 일보다 더욱 중요한 일이 있지 않던가? 가서 그 일이나 처리하라!', `MaleText_loc4`='箱子？我没有给你箱子啊，约瓦安。你是不是应该去关心点别的？去工作！', `MaleText_loc5`='木箱?我沒有寄木箱給你，裘瓦安。你沒有更重要的事情要擔心嗎?去照料他們!', `MaleText_loc7`='¿Caja? No te envié una caja, Jovaan. ¿No tienes cosas más importantes de las que preocuparte? ¡Ve a ocuparte de ellas!' WHERE `ID`=19281;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가젯잔의 기술자인 랩포지의 도움으로 이곳 토쉴리의 연구기지에 강력한 노움 순간이동기를 만들었어요! 자신의 전용 순간이동기를 만들 수 있을 만큼 실력이 뛰어난 노움 기술자를 돕는 것이 제 행복입니다.', `MaleText_loc4`='由于得到了加基森工程师霍尔迪·水炉的帮助，我在这里托什雷的基地建造了一台威力强大的侏儒传送器！我很乐意帮助任何有技术实力的侏儒工程师来制造他们自己的传送航标。', `MaleText_loc5`='在來自加基森的工程師水爐的幫助下，我已經在托斯利基地建造一座強大的地精傳送門!我很高興能夠幫助任何的地精工程師，以足夠的技能建造他們自己的個人運輸信號燈。', `MaleText_loc7`='¡Con la ayuda del ingeniero Lapforge, de Gadgetzan, he construido un potente transportador gnómico aquí, en la Estación de Toshley! Ayudaría de buena gana a cualquiera ingeniero gnómico con la pericia suficiente a construir su propio localizador de transporte personal.' WHERE `ID`=19282;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='토쉴리의 연구기지에서 이렇게 떨어져 있는 이유가 뭡니까?', `MaleText_loc4`='为什么你离托什雷的基地这么远？', `MaleText_loc5`='你為什麼離托斯利基地這麼遠?', `MaleText_loc7`='¿Por qué estás tan lejos de la Estación de Toshley?', `FemaleText_loc1`='토쉴리의 연구기지에서 이렇게 떨어져 있는 이유가 뭔가요?', `FemaleText_loc4`='为什么你离托什雷的基地这么远？', `FemaleText_loc5`='你為什麼離托斯利基地這麼遠?', `FemaleText_loc7`='¿Por qué estás tan lejos de la Estación de Toshley?' WHERE `ID`=19283;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새로운 전문화를 배울 준비가 되면 타나리스의 스팀휘들 항구에 있는 나라인 수스팬시를 찾아가십시오.', `MaleText_loc4`='如果你想要转换专精，就去找纳瑞安吧。你可以在塔纳利斯的热砂港找到他。', `MaleText_loc5`='當你準備好追尋新的專業時，去找納里安·柔想吧。你可以在塔納利斯的熱砂港找到他。', `MaleText_loc7`='Cuando estés $gpreparado:preparada; para buscar una nueva especialidad, busca a Narain Sabelotodo. Se le puede encontrar en el Puerto Bonvapor, en Tanaris.', `FemaleText_loc1`='새로운 전문화를 배울 준비가 되면 타나리스의 스팀휘들 항구에 있는 나라인 수스팬시를 찾아가십시오.', `FemaleText_loc4`='如果你想要转换专精，就去找纳瑞安吧。你可以在塔纳利斯的热砂港找到他。', `FemaleText_loc5`='當你準備好追尋新的專業時，去找納里安·柔想吧。你可以在塔納利斯的熱砂港找到他。', `FemaleText_loc7`='Cuando estés $gpreparado:preparada; para buscar una nueva especialidad, busca a Narain Sabelotodo. Se le puede encontrar en el Puerto Bonvapor, en Tanaris.' WHERE `ID`=19284;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='창조된 물의 정령 조종', `MaleText_loc4`='控制被召唤的水元素', `MaleText_loc5`='控制召喚的水元素。', `MaleText_loc7`='Controlar elemental de agua conjurado.', `FemaleText_loc1`='창조된 물의 정령 조종', `FemaleText_loc4`='控制被召唤的水元素', `FemaleText_loc5`='控制召喚的水元素。', `FemaleText_loc7`='Controlar elemental de agua conjurado.' WHERE `ID`=19285;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<창조된 물의 정령이 물보라를 일으킬 준비를 마쳤습니다.>', `MaleText_loc4`='<水元素准备涌动了。>', `MaleText_loc5`='<水元素已經準備好奔騰了。>', `MaleText_loc7`='<El elemental de agua está listo para elevarse.>' WHERE `ID`=19286;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<군마가 전투에 참여하려는 굳은 의지를 보이며 당당하게 서 있습니다.>', `MaleText_loc4`='<骑兵自豪地站立着，蓄势待发。>', `MaleText_loc5`='<騎士挺直了胸膛站著，渴望戰鬥。>', `MaleText_loc7`='<El destrero se alza con orgullo, ansioso por que comience la batalla.>' WHERE `ID`=19287;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='인간 군마 조종', `MaleText_loc4`='控制人类骑兵', `MaleText_loc5`='控制人類騎士。', `MaleText_loc7`='Controlar destrero de humanos.', `FemaleText_loc1`='인간 군마 조종', `FemaleText_loc4`='控制人类骑兵', `FemaleText_loc5`='控制人類騎士。', `FemaleText_loc7`='Controlar destrero de humanos.' WHERE `ID`=19288;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강아지처럼 착륙할 수밖에 없었다. 뭐, 어쨌든 상관없다. 조만간 너희 짐승들은 모두 주인님의 손아귀에 들어갈 테니까.', `MaleText_loc4`='像狗一样被强迫落地。无所谓。很快，这些奇妙的生物都将落入主人的掌心。', `MaleText_loc5`='像隻狗一樣倉皇的迫降。沒有關係。不久之後，所有的這些珍奇野獸都將會在主人的控制下。', `MaleText_loc7`='Obligado a aterrizar como un perro. No importa. Pronto todas estas bestias asombrosas estarán bajo el control del maestro.' WHERE `ID`=19289;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 세계는 끝이다.', `MaleText_loc4`='你的生命走到尽头了。', `MaleText_loc5`='你的世界即將結束。', `MaleText_loc7`='Tu mundo llega a su fin.' WHERE `ID`=19290;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하늘이 어두워지고 모든 것이 침묵하리라. 그때가 돼서야 너희는 죽음이 가져다주는 달콤한 평온함을 알게 되리라...', `MaleText_loc4`='天空会陷入黑暗，整个世界也将沉寂。只有那时，你才能体验到死亡那甜蜜的幽静。', `MaleText_loc5`='天空變得黑暗，全部都轉寂靜。只有那時你才知道死亡的甜美沉靜...', `MaleText_loc7`='Los cielos se ensombrecerán y se hará el silencio absoluto. Solo entonces conocerás la dulce serenidad de la muerte...' WHERE `ID`=19291;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<성직자가 곁눈질로 당신을 응시합니다.>', `MaleText_loc4`='<牧师用眼角的余光盯着你。>', `MaleText_loc5`='<教士從它的眼角盯著你。>', `MaleText_loc7`='<El clérigo te mira por el rabillo del ojo.>' WHERE `ID`=19292;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='인간 성직자 조종', `MaleText_loc4`='控制人类祭司', `MaleText_loc5`='控制人類教士', `MaleText_loc7`='Controlar clérigo humano', `FemaleText_loc1`='인간 성직자 조종', `FemaleText_loc4`='控制人类祭司', `FemaleText_loc5`='控制人類教士', `FemaleText_loc7`='Controlar clérigo humano' WHERE `ID`=19293;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<인간 창조술사가 먼 곳을 주시하면서 당당히 서 있습니다.>', `MaleText_loc4`='<召唤师原地矗立，凝视着远方。>', `MaleText_loc5`='<咒術師的站姿透露出殘忍好鬥的氣息，雙眼凝視著遠方。>', `MaleText_loc7`='<El conjurador se alza fiero, con la mirada distante.>' WHERE `ID`=19294;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='인간 창조술사 제어', `MaleText_loc4`='控制人类召唤师', `MaleText_loc5`='控制人類咒術師', `MaleText_loc7`='Controlar conjurador humano', `FemaleText_loc1`='인간 창조술사 제어', `FemaleText_loc4`='控制人类召唤师', `FemaleText_loc5`='控制人類咒術師', `FemaleText_loc7`='Controlar conjurador humano' WHERE `ID`=19295;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<국왕 레인의 지혜와 힘이 비록 체스 말의 모습이지만 밝게 빛납니다.>', `MaleText_loc4`='<即使只是一枚棋子，莱恩国王的力量和智慧仍闪烁着光芒。>', `MaleText_loc5`='<即使擁有王者的氣概，萊恩的智慧以及力量潛能仍然散發出不平凡的光輝。>', `MaleText_loc7`='<La auténtica sabiduría y fuerza de Llane brillan con fuerza, incluso en este parecido del rey.>' WHERE `ID`=19296;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='국왕 레인 조종', `MaleText_loc4`='控制莱恩国王', `MaleText_loc5`='控制萊恩王', `MaleText_loc7`='Controlar rey Llane', `FemaleText_loc1`='국왕 레인 조종', `FemaleText_loc4`='控制莱恩国王', `FemaleText_loc5`='控制萊恩王', `FemaleText_loc7`='Controlar rey Llane' WHERE `ID`=19297;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사이루크가 깨어났다!', `MaleText_loc4`='森卢肯被唤醒了！', `MaleText_loc5`='賽洛庫已經醒來!', `MaleText_loc7`='¡Cyrukh ha despertado!' WHERE `ID`=19298;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너는 영원히 고통을 받을 것이다!', `MaleText_loc4`='你将尝到永恒的痛楚！', `MaleText_loc5`='你將永遠受苦!', `MaleText_loc7`='¡Sufriréis eternamente!' WHERE `ID`=19299;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와라, 필멸의 존재여. 불의 군주를 맞이하라!', `MaleText_loc4`='来吧，凡人，面对炎魔之王！', `MaleText_loc5`='來吧，凡人，面對火焰之王吧!', `MaleText_loc7`='¡Vamos, mortales, enfrentaos al Señor del Fuego!' WHERE `ID`=19300;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사이루크가 너희를 처단하러 왔다!', `MaleText_loc4`='森卢肯来取你们的性命了！', `MaleText_loc5`='賽洛庫為你而來!', `MaleText_loc7`='¡Cyrukh viene por ustedes!' WHERE `ID`=19301;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 불을 갖고 장난 치는 자들은 재가 되리라!', `MaleText_loc4`='玩火者必自焚！', `MaleText_loc5`='那些膽敢玩火者都將被燒成灰!', `MaleText_loc7`='¡Aquellos que osen jugar con fuego serán incinerados!' WHERE `ID`=19302;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불의 소용돌이가 모양을 갖춥니다.', `MaleText_loc4`='一个火焰漩涡显现了出来。', `MaleText_loc5`='一個燃燒的漩渦成形。', `MaleText_loc7`='Un vórtice flameante toma forma.' WHERE `ID`=19303;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 혼자가 아니라네, $n! 모두 힘을 합치면 저 지옥에서 온 불의 악마를 해치울 수 있어!', `MaleText_loc4`='你不是一个人在战斗，你不是一个人，$n！让我们一起放逐这地狱之火的子嗣！', `MaleText_loc5`='你不會獨自一人戰鬥，$n!我們將一同消滅地獄火的爪牙們!', `MaleText_loc7`='¡No luchas $gsolo:sola;, $n! ¡Juntos desterraremos a este engendro de las llamas infernales!' WHERE `ID`=19304;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카라보르의 진혼곡을 끝내는 일을 돕고자 우리가 왔네!', `MaleText_loc4`='我们来帮你对抗卡拉波的挽歌！', `MaleText_loc5`='我們來是為了幫助卡拉伯爾輓歌而戰!', `MaleText_loc7`='¡Hemos venido a ayudar en la lucha contra el dirge de Karabor!' WHERE `ID`=19305;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 전투 준비가 끝났네. $n, 자네만 준비되면 돼.', `MaleText_loc4`='你准备好了我们就开战，$n。', `MaleText_loc5`='你準備好我們就戰鬥吧，$n。', `MaleText_loc7`='Lucharemos cuando estés $gpreparado:preparada;, $n.' WHERE `ID`=19306;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비됐습니다, 오로노크. 사이루크를 해치우고 정령들을 풀어줍시다!', `MaleText_loc4`='我准备好了，欧鲁诺克。让我们消灭森卢肯，解救这些元素吧！', `MaleText_loc5`='我準備好了，歐朗諾克。讓我們毀了賽洛庫並解放那些元素吧!', `MaleText_loc7`='Estoy preparado, Oronok. ¡Destruyamos a Cyrukh y liberemos los elementos!', `FemaleText_loc1`='준비됐습니다, 오로노크. 사이루크를 해치우고 정령들을 풀어줍시다!', `FemaleText_loc4`='我准备好了，欧鲁诺克。让我们消灭森卢肯，解救这些元素吧！', `FemaleText_loc5`='我準備好了，歐朗諾克。讓我們毀了賽洛庫並解放那些元素吧!', `FemaleText_loc7`='Estoy preparada, Oronok. ¡Destruyamos a Cyrukh y liberemos los elementos!' WHERE `ID`=19307;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살로 빚어진 조그마한 생물이여, 그렇게 소원이라면 들어주마! 네게 죽음을 선물하겠다!', `MaleText_loc4`='渺小的血肉之躯们，你们的愿望即将成真！你们的死期即将来临！', `MaleText_loc5`='弱小的血肉之軀，就順從你的希望吧!死亡為你而來!', `MaleText_loc7`='¡Criaturita hecha de carne, deseo concedido! ¡La muerte va a por ti!' WHERE `ID`=19308;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 손아귀에서 정령들을 풀어줄 것이다. 무력으로!', `MaleText_loc4`='我们会用武力把元素之灵从你的魔掌中解救出来！', `MaleText_loc5`='我們將述諸武力將這些元素從你手中釋放!', `MaleText_loc7`='¡Liberaremos a los elementos de tu alcance por la fuerza!' WHERE `ID`=19309;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네만 준비되면 우리는 언제든지 싸울 수 있네.', `MaleText_loc4`='你准备好了我们就开战。', `MaleText_loc5`='當你準備好時我們會加入戰鬥。', `MaleText_loc7`='Lucharemos cuando estés $gpreparado:preparada;.' WHERE `ID`=19310;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경고! 경고! 적대 세력 발견! 토쉴리의 연구기지로 가는 능선에 접근하지 말 것!', `MaleText_loc4`='警报！警报！发现敌人！不要爬上托什雷的基地的屋顶！', `MaleText_loc5`='警告!警告!敵方生物離開!不要上山往托斯利基地前進!', `MaleText_loc7`='¡AVISO! ¡AVISO! ¡FUERA, SERES HOSTILES! ¡NO SUBÁIS LA COLINA HASTA LA ESTACIÓN DE TOSHLEY!' WHERE `ID`=19311;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='띠리릿... R-3D0는 드워프어와 노움어 그리고 인간의 공용어에 능통합니다. 그런데 $c님께서 하는 말은 제 프로그램으로 이해할 수가 없습니다!$B$BR-3D0 부품의 소음 때문에 말씀이 잘 들리지 않으니 크게 얘기해 주시기 바랍니다!', `MaleText_loc4`='我能流利地说两种语言：矮人语，和略带人类口音的侏儒语。但是我根本不知道你在说什么！！$B$B说大声点！齿轮的摩擦让我根本听不见你在说什么！！', `MaleText_loc5`='我精通超過兩種語言︰矮人語，地精語和非常普通的人類語言。但是我不了解你在說什麼!$B$B說大聲點:引擎聲這麼吵，我聽不見你的聲音!', `MaleText_loc7`='DOMINO MÁS DE DOS IDIOMAS: ENÁNICO, GNOMÓTICO Y LA LENGUA COMÚN DE LOS HUMANOS. ¡PERO NO TENGO NI IDEA DE QUÉ ESTÁS DICIENDO!$B$B¡HABLA MÁS ALTO: NO TE OIGO CON EL CHIRRIDO DE MIS ENGRANAJES!' WHERE `ID`=19312;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 네... 내 연구기지를 찾아 주셔서 감사합니다.$B$B둘러보시니 어떠신가요? 여기서 우리가 정말 멋진 일을 해낸 거 같지 않나요?$B$B그건 그렇고 실바나르의 저 꽉 막힌 엘프들을 없애 주면 정말 기쁘겠네요.$B$B여기 일을 좀 도와주십시오. 실험이나 그 밖에 도움이 필요한 일이 아주 많거든요.', `MaleText_loc4`='是的，是的……欢迎来到我的基地。$B$B那么，你觉得怎么样？你是想说我们在这里干得很漂亮是吧？$B$B不管怎样，能摆脱希尔瓦纳的那些乏味的精灵真让我感到高兴。$B$B在这里找点活干吧，那边有很多实验需要人手。', `MaleText_loc5`='是，是...歡迎到我的基地。$B$B那麼，你覺得如何呢?漂亮的俏皮話我們在這裡都說過了，你不來點嗎?$B$B無論如何，我很高興能夠擺脫那些希爾瓦納的自大精靈。$B$B四處找點事做吧;到處都有許多的實驗及匿名者等著需要幫忙。', `MaleText_loc7`='Sí, sí... $gbienvenido:bienvenida; a mi estación.$B$BEntonces, ¿qué te parece? Es bastante ingenioso lo que hemos hecho aquí, ¿no crees?$B$BMe alegro de haberme librado de esos elfos estirados de Sylvanaar, de cualquier modo.$B$BBusca algo útil que hacer por aquí; hay muchos experimentos y todas esas cosas con las que ayudar.' WHERE `ID`=19313;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나루에게 영광을. 모든 적이 성스러운 빛 앞에 무릎을 꿇게 될 것입니다.', `FemaleText_loc4`='荣耀属于纳鲁，$n。敌人将在圣光的照耀下湮灭！', `FemaleText_loc5`='讚美那魯，$n。聖光很快就會戰勝它的敵人。', `FemaleText_loc7`='Gloria a los naaru, $n. La Luz triunfará pronto sobre sus enemigos.' WHERE `ID`=19314;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='캔지스, 가만히 있어봐. 이 수정을 써볼 테니까.', `MaleText_loc4`='坎希斯，待在这儿。我去试用这块水晶。', `MaleText_loc5`='坎希斯，堅持下去。我正要試試看這顆水晶。', `MaleText_loc7`='Cansis, no te muevas. Voy a intentar usar este cristal.' WHERE `ID`=19315;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 자신을 현실로부터 부분적으로 변화시킵니다.', `MaleText_loc4`='%s把自己化作虚体。', `MaleText_loc5`='%s逐步讓他自己脫離現實之外。', `MaleText_loc7`='%s se va retirando parcialmente de la realidad.' WHERE `ID`=19316;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 재미있을 거야... 자, 시험해 볼게.', `MaleText_loc4`='有意思……让我试试。', `MaleText_loc5`='很有趣...讓我試試看。', `MaleText_loc7`='Interesante... Déjame intentar algo.' WHERE `ID`=19317;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='캔지스, 넌 이제 닭이다.', `MaleText_loc4`='坎希斯，你是个胆小鬼。', `MaleText_loc5`='坎希斯。你是隻雞。', `MaleText_loc7`='Cansis. Eres un gallina.' WHERE `ID`=19318;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<살육을 기대하는 듯 그런트의 입가에 침이 잔뜩 고였습니다.>', `MaleText_loc4`='<兽人步兵的嘴里流着口水，期待着一场战斗。>', `MaleText_loc5`='<蠻兵吞了吞口水，做好殺人的準備。>', `MaleText_loc7`='<Al bruto se le hace la boca agua, al esperar el derramamiento de sangre.>' WHERE `ID`=19319;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오크 그런트 조종', `MaleText_loc4`='控制兽人步兵', `MaleText_loc5`='控制獸人蠻兵', `MaleText_loc7`='Controlar bruto orco', `FemaleText_loc1`='오크 그런트 조종', `FemaleText_loc4`='兽人步兵', `FemaleText_loc5`='控制獸人蠻兵', `FemaleText_loc7`='Controlar bruto orco' WHERE `ID`=19320;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; $n|1을;를; 집중 공격합니다!', `MaleText_loc4`='%s注视着$n！', `MaleText_loc5`='%s 盯著 $n!', `MaleText_loc7`='¡%s se centra en $n!', `FemaleText_loc1`='%s|1이;가; $n|1을;를; 집중 공격합니다!', `FemaleText_loc4`='%s注视着$n！', `FemaleText_loc5`='%s 盯著 $n!', `FemaleText_loc7`='¡%s se centra en $n!' WHERE `ID`=19321;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<소환된 악마가 메디브가 정한 게임의 법칙에 대항하고 싶어서 몸을 꿈틀거립니다. 그는 당신의 영혼을 원합니다!>', `MaleText_loc4`='<被召唤出来的恶魔抽搐着，反抗着麦迪文的游戏规则。他想要你的灵魂！>', `MaleText_loc5`='<召喚惡魔正在對抗著麥迪文的遊戲規則，他的身軀不停的顫抖著。他要你的靈魂!>', `MaleText_loc7`='<El belcebú invocado se mueve nervioso, luchando contra las reglas de juego de Medivh. ¡Quiere tu alma!>' WHERE `ID`=19322;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소환된 악마 조종', `MaleText_loc4`='控制被召唤的恶魔', `MaleText_loc5`='控制召喚惡魔', `MaleText_loc7`='Controlar belcebú invocado', `FemaleText_loc1`='소환된 악마 조종', `FemaleText_loc4`='控制被召唤的恶魔', `FemaleText_loc5`='控制召喚惡魔', `FemaleText_loc7`='Controlar belcebú invocado' WHERE `ID`=19323;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='근처의 모든 아라코아가 동쪽을 향해 길고 굵은 충성의 함성을 지릅니다.', `MaleText_loc4`='All of the nearby arokkoa face east and whistle a long, low note of devotion. [PH]', `MaleText_loc5`='所有附近的阿拉卡都面對東方，並吹出長而低沉的祈禱。[PH]', `MaleText_loc7`='Todos los arokkoa cercanos dan al este y silban con una nota grave de devoción. [PH]' WHERE `ID`=19324;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 드워프는 첩자 임무를 수행하던 중 정체가 발각되어 살해된 것 같습니다. 죽음의 괴철로 수행원들이 모두 볼 수 있는 곳에 시체를 둔 것으로 봐서 침입자들에 대한 경고의 의미로 보입니다.', `MaleText_loc4`='这个矮人似乎是在执行侦察任务时被发现而惨遭杀害。死亡熔炉的随从们把他曝尸荒野，也许是用来警告其他的入侵者。', `MaleText_loc5`='這個矮人看來像是在一項監視任務中途被發現並被殺害了。死亡熔爐的侍者將屍體留在外面，也許是想要警告那些其他想要闖入的人。', `MaleText_loc7`='El enano parece haber sido descubierto y asesinado en medio de una misión de espionaje. Los guardas de la Forja Muerta han dejado el cadáver al aire libre, quizás como aviso para otros entrometidos en potencia.' WHERE `ID`=19325;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='플라니스의 짐꾸러미를 회수합니다.', `MaleText_loc4`='拿走弗兰尼斯的背包。', `MaleText_loc5`='取回弗藍尼斯的背包。', `MaleText_loc7`='Recupera la talega de Flanis.', `FemaleText_loc1`='플라니스의 짐꾸러미를 회수합니다.', `FemaleText_loc4`='拿走弗兰尼斯的背包。', `FemaleText_loc5`='取回弗藍尼斯的背包。', `FemaleText_loc7`='Recupera la talega de Flanis.' WHERE `ID`=19326;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일에 매진하라! 최전선에 나갈 준비를 해야 한다!', `MaleText_loc4`='继续工作！你们必须做好奔赴前线的准备！', `MaleText_loc5`='繼續努力!你必須準備好加入前線!', `MaleText_loc7`='¡Sigue trabajando! ¡Debes estar $gpreparado:preparada; para unirte a las primeras líneas!' WHERE `ID`=19327;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너는 불타는 군단의 일원이라 불릴 자격이 없는 녀석이로구나! 더욱 분발해라, 이 벌레 같은 녀석!', `MaleText_loc4`='你还没资格成为燃烧军团的一员！再努力点，蠕虫！', `MaleText_loc5`='你不配被叫作燃燒軍團!再加把勁吧懦夫!', `MaleText_loc7`='¡No mereces pertenecer a la Legión Ardiente! ¡Trabaja más duro, gusano!' WHERE `ID`=19328;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비가 거의 끝났군! 너는 조만간 부름을 받게 될 것이다! 그러면 적을 물리치고 이 땅을 정복해야 한다.', `MaleText_loc4`='你就快够资格了！你很快就会接到召唤，去摧毁我们的敌人，征服这块土地！', `MaleText_loc5`='你幾近完備了!很快地你就會被指派去摧毀我們的敵人，並且征服這塊土地!', `MaleText_loc7`='¡Ya casi estás $gpreparado:preparada;! ¡Pronto te llamarán para destruir a nuestro enemigos y conquistar esta tierra!' WHERE `ID`=19329;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비가 거의 끝났군! 너는 조만간 부름을 받게 될 것이다! 그러면 적을 물리치고 이 땅을 정복해야 한다.', `MaleText_loc4`='你就快够资格了！你很快就会接到召唤，去摧毁我们的敌人，征服这块土地！', `MaleText_loc5`='你幾近完備了!很快地你就會被指派去摧毀我們的敵人，並且征服這塊土地!', `MaleText_loc7`='¡Ya casi estás $gpreparado:preparada;! ¡Pronto te llamarán para destruir a nuestro enemigos y conquistar esta tierra!' WHERE `ID`=19331;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말... 정말 끝났나? 놈이 죽은 게 확실해?', `MaleText_loc4`='这……这一切都结束了？他被消灭了？', `MaleText_loc5`='...能夠讓它結束嗎?他被摧毀了嗎?', `MaleText_loc7`='¿Es... es posible que haya terminado? ¿Está destruido?' WHERE `ID`=19332;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 대지 고리회에서 나온 치유사를 만나야 해. 어서...', `MaleText_loc4`='我们必须和大地之环的萨满祭司谈谈。来……', `MaleText_loc5`='我們必須與陶土議會的薩滿談談。來吧...', `MaleText_loc7`='Debemos hablar con el chamán del Anillo de la Tierra. Ven...' WHERE `ID`=19333;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정령들이 뭐라고 합니까, 토르록? 아무 소리도 들리지 않네요.', `MaleText_loc4`='元素们说了些什么，托洛克？我什么都没听到。', `MaleText_loc5`='元素們說了什麼，托爾洛克?我只聽到寂靜。', `MaleText_loc7`='¿Qué dicen los elementos, Torlok? Solo oigo silencio.' WHERE `ID`=19334;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 의식을 잃습니다.', `MaleText_loc4`='%s失去了知觉。', `MaleText_loc5`='%s失去知覺。', `MaleText_loc7`='%s cae inconsciente.' WHERE `ID`=19335;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 듣는 것이나 제가 듣는 것이나 별로 다를 바는 없습니다, 형제여. 뒤를 보십시오...', `MaleText_loc4`='我听到的和你一样，兄弟。看看你身后……', `MaleText_loc5`='我聽到你所聽到的，兄弟。往後看...', `MaleText_loc7`='Oigo lo mismo que tú, hermano. Mira tras de ti...' WHERE `ID`=19336;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들이 구원을 받았군요! 그럼 우리가 이긴 겁니까?', `MaleText_loc4`='他们得到了救赎！那么我们胜利了？', `MaleText_loc5`='他們被救贖!那麼我們贏了嗎?', `MaleText_loc7`='¡Se han redimido! Entonces, ¿hemos ganado?' WHERE `ID`=19337;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 모든 게 제자리를 찾았습니다. 치유사여, 잘하셨습니다.', `MaleText_loc4`='就应该是现在这样，萨满祭司。你干得不错。', `MaleText_loc5`='現在就是它應該的樣子，薩滿。你做得很好。', `MaleText_loc7`='Ahora es como debería ser, chamán. Has hecho bien.' WHERE `ID`=19338;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 이곳 정령들은 충분히 구원을 받았어요. 하지만, 암호가 다른 이들에게 알려지면... 불의 정령들이 동요하고 있습니다... 이것을 막지 못하면 필멸의 존재들이 온 세계는 멸망할 것입니다.', `MaleText_loc4`='是的……对这里的元素来说，已经很好了，但是密码已经被别人知道了……火焰之灵正在骚动……如果不阻止这股力量，这些凡人所属的世界将会灭亡。', `MaleText_loc5`='是的...對於這裡的元素來說夠好了，但是密碼被另一個知道了...火焰之靈正在騷動...如果這股力量不被制停，這些凡人來自的世界將會瓦解。', `MaleText_loc7`='Sí... Está bien por los elementos que están aquí, pero la clave es conocida para otro... Los espíritus del fuego están confusos... Si no se detiene esta fuerza, el mundo del que vinieron estos mortales cesará de existir.' WHERE `ID`=19339;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필멸의 존재들이여, 안녕히... 대지치유사는 불의 정령들이 무엇을 느끼고 있는지 알고 있습니다.', `MaleText_loc4`='保重，凡人……大地治愈者了解火焰之灵的感受……', `MaleText_loc5`='再會，凡人...大地治癒者知道火會有什麼感覺...', `MaleText_loc7`='Adiós, mortales... El ensalmador de la tierra sabe lo que siente el fuego...' WHERE `ID`=19340;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 우리는 떠나겠습니다. 토르록, 한 가지 청이 있는데...', `MaleText_loc4`='那么我们走了，托洛克。我只有一个要求……', `MaleText_loc5`='我們會離開，接著，托爾洛克。我只有一個請求...', `MaleText_loc7`='Entonces nos marchamos, Torlok. Solo tengo una petición...' WHERE `ID`=19341;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비통의 오로노크와 그 아들들이 대지치유사 토르록에게 자신들의 무기를 건넵니다.', `MaleText_loc4`='欧鲁诺克·裂心等人把他们的武器交给了大地治愈者托洛克。', `MaleText_loc5`='碎心人民把他們的武器給大地治癒者托爾洛克。', `MaleText_loc7`='Los hombres del corazón roto entregan sus armas al ensalmador de la tierra Torlok.' WHERE `ID`=19342;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 위업을 달성하게 해준 영웅들에게 이걸 주십시오.', `MaleText_loc4`='把这些武器交给英雄们，助他们一臂之力。', `MaleText_loc5`='把這些東西給那些可能辦到的英雄們。', `MaleText_loc7`='Da esto a los héroes que lo hicieron posible.' WHERE `ID`=19343;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모든 게 계획대로 되고 있다.', `MaleText_loc4`='一切都在按照计划进展。', `MaleText_loc5`='一切都照著進度在進行。', `MaleText_loc7`='Las cosas avanzan según lo previsto.' WHERE `ID`=19344;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자가 있다는 보고가 들어왔다. 조금이라도 수상한 움직임이 보이는 즉시 내게 알리도록!', `MaleText_loc4`='最近有人发现了入侵者。如果你看到什么异常情况要立刻通知我！', `MaleText_loc5`='據報有入侵者。如果你看見任何異常，立刻通知我!', `MaleText_loc7`='Ha habido informes de intrusos. ¡Me avisarás si ves algo fuera de lo normal!' WHERE `ID`=19345;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이걸 정말로 발사하지는 않겠지?', `MaleText_loc4`='我们永远不会发射这些玩意，对吧？', `MaleText_loc5`='我們從未試著去點燃這些當中的一個，我們有嗎?', `MaleText_loc7`='Nunca vamos a disparar a uno de estos, ¿verdad?', `FemaleText_loc1`='이걸 정말로 발사하지는 않겠죠?', `FemaleText_loc4`='我们永远不会发射这些玩意，对吧？', `FemaleText_loc5`='我們從未試著去點燃這些當中的一個，我們有嗎?', `FemaleText_loc7`='Nunca vamos a disparar a uno de estos, ¿verdad?' WHERE `ID`=19346;
