UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정확하게 어떤 목표를 향해 발사할 작정이지?', `MaleText_loc4`='我们究竟要把这些东西发射到哪里去？', `MaleText_loc5`='沒錯，我們到底要將對著什麼開火?', `MaleText_loc7`='¿Y qué les vamos a disparar exactamente?', `FemaleText_loc1`='정확하게 어떤 목표를 향해 발사할 작정이죠?', `FemaleText_loc4`='我们究竟要把这些东西发射到哪里去？', `FemaleText_loc5`='沒錯，我們到底要將對著什麼開火?', `FemaleText_loc7`='¿Y qué les vamos a disparar exactamente?' WHERE `ID`=19348;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 그 흰 고양이를 얼마나 멀리 날려보낼지 궁금하군...', `MaleText_loc4`='我在想，这玩意能把一只白猫丢多远……', `MaleText_loc5`='我想知道這可以將那隻白色的貓射到多遠...', `MaleText_loc7`='Me pregunto a qué distancia lanzaría esto a ese gato blanco...', `FemaleText_loc1`='이게 그 흰 고양이를 얼마나 멀리 날려보낼지 궁금하네요...', `FemaleText_loc4`='我在想，这玩意能把一只白猫丢多远……', `FemaleText_loc5`='我想知道這可以將那隻白色的貓射到多遠...', `FemaleText_loc7`='Me pregunto a qué distancia lanzaría esto a ese gato blanco...' WHERE `ID`=19349;
