UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부지런히 애쓰도록! 내 말 한 마디면 너는 흑마법사가 소환한 악마의 밥이 될 것이다.', `MaleText_loc4`='用功点！我只想说，你早晚要被丢去喂术士的恶魔。', `MaleText_loc5`='勤勉!只要我的一句話，你就會被餵給術士的惡魔。', `MaleText_loc7`='¡Sé diligente! Una palabra mía y serás pasto de los demonios de los brujos.' WHERE `ID`=19356;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 발밑의 뼈들이 보이나? 이곳을 탈영하려던 자들의 것이다.', `MaleText_loc4`='你看见脚下的尸骨了吗？这就是擅离职守的下场。', `MaleText_loc5`='你看見在你腳下的那些骨頭嗎?那些就是試著擅離崗位的守衛。', `MaleText_loc7`='¿Ves los huesos que están a tus pies? Son de guardias que intentaron abandonar su puesto.' WHERE `ID`=19357;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알았다, 알았다고! 나 춤춘다!', `MaleText_loc4`='好吧，好吧！我跳！', `MaleText_loc5`='好，好!我跳舞!', `MaleText_loc7`='¡De acuerdo, de acuerdo! ¡Mi bailar!' WHERE `ID`=19358;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐지? 새가 알려준 마법 쓰려고? 너 박살 낸다!', `MaleText_loc4`='那是什么？哦，你想使用鸦人的魔法？小心我抽你！', `MaleText_loc5`='那是什麼?噢，你想試著使用小妞魔法嗎?我揍你! !', `MaleText_loc7`='¿Qué es eso? Oh, ¿intentas usar magia de pájaro? ¡Te aplastaré!' WHERE `ID`=19359;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너 혼내 줄거야.', `MaleText_loc4`='你敢抽我我就抽你。', `MaleText_loc5`='我為此而傷害你。', `MaleText_loc7`='Te hago daño por eso.' WHERE `ID`=19360;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<비전 수호병이 당신을 보고 있는 것 같지만 아무 말도 하지 않습니다.>', `MaleText_loc4`='<奥术守护者似乎面对着你，但是没有说话。>', `MaleText_loc5`='<秘法護衛雖然面對著你，但是沒說什麼。>', `MaleText_loc7`='<El guardián Arcano parece mirar hacia ti, pero no dice nada.>' WHERE `ID`=19361;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<비전 수호병이 고난의 거리의 동쪽 끝 지역을 가리킵니다.>', `MaleText_loc4`='<奥术守护者指了指贫民窟的最东面。>', `MaleText_loc5`='<秘法護衛指向陰鬱城最東邊的部分。>', `MaleText_loc7`='<El guardián Arcano hace un gesto hacia la parte más oriental de la parte baja de la ciudad.>' WHERE `ID`=19362;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<비전 수호병이 도시 중앙에서 남동쪽으로 있는 지점을 가리킵니다.>', `MaleText_loc4`='<奥术守护者指了指城市中心东南面的一处地方。>', `MaleText_loc5`='<秘法護衛指向城市中心東南邊的地方。>', `MaleText_loc7`='<El guardián Arcano hace un gesto hacia un lugar al sureste del centro de la ciudad.>' WHERE `ID`=19363;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<비전 수호병이 점술가 언덕 건너편 여관을 가리킵니다.>', `MaleText_loc4`='<奥术守护者指了指平台对面的旅店。>', `MaleText_loc5`='<秘法護衛指向對面的旅館。>', `MaleText_loc7`='<El guardián Arcano hace un gesto al otro lado de la Grada, hacia la posada.>' WHERE `ID`=19364;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잔머리 굴리지 마라! 그랬다간 저놈들과 똑같은 꼴로 만들어 주마!', `MaleText_loc4`='不要动歪念头，否则就送你去见他们！', `MaleText_loc5`='不要想餿主意，也不要讓我看見你與他們一起!', `MaleText_loc7`='¡No te hagas ilusiones o me encargaré de que te unas a ellos!' WHERE `ID`=19365;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<강령사의 몸에서 물결치는 듯한 어둠의 마력이 느껴집니다.>', `MaleText_loc4`='<通灵师的黑暗魔法泛起了波纹。>', `MaleText_loc5`='<通靈師身上泛起了黑暗魔法的漣漪。>', `MaleText_loc7`='<Magia oscura emana ondulante del necrólito.>' WHERE `ID`=19366;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오크 강령사 조종', `MaleText_loc4`='控制兽人通灵师', `MaleText_loc5`='控制獸人通靈師', `MaleText_loc7`='Controlar necrólito orco', `FemaleText_loc1`='오크 강령사 조종', `FemaleText_loc4`='控制兽人通灵师', `FemaleText_loc5`='控制獸人通靈師', `FemaleText_loc7`='Controlar necrólito orco' WHERE `ID`=19367;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<비전 수호병이 도시 중앙에서 동쪽으로 있는 지점을 가리킵니다.>', `MaleText_loc4`='<奥术守护者指了指城市中心东面的一处地方。>', `MaleText_loc5`='<秘法護衛指向城市中心東邊的地方。>', `MaleText_loc7`='<El guardián Arcano hace un gesto hacia un lugar al este del centro de la ciudad.>' WHERE `ID`=19368;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='총명한 제군들은 들어라! 베레디스는 불시에 시찰하는 걸로 유명하다.', `MaleText_loc4`='精神点，士兵们！瓦雷迪斯就喜欢突击检查。', `MaleText_loc5`='趕緊集合!瓦瑞迪斯以突擊檢查聞名。', `MaleText_loc7`='¡Atentas, tropas! Varedis es conocido por realizar inspecciones sorpresa.' WHERE `ID`=19369;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<비전 수호병이 점술가 언덕 건너편의 여관 근처에 있는 우체통을 가리킵니다.>', `MaleText_loc4`='<奥术守护者指了指平台对面的旅店和邮箱。>', `MaleText_loc5`='<秘法護衛指向對面的旅館和附近的郵箱。>', `MaleText_loc7`='<El guardián Arcano hace un gesto a un lugar al otro lado de la Grada, hacia la posada y el buzón de correos cercano.>' WHERE `ID`=19370;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<비전 수호병이 점술가 언덕 건너편의 여관 밖에 있는 야수 관리인을 가리킵니다.>', `MaleText_loc4`='<奥术守护者指了指平台对面的旅店和外面的兽栏管理员。>', `MaleText_loc5`='<秘法守護者指向對面的旅館和其外面的獸欄管理者。>', `MaleText_loc7`='<El Guardián Arcano hace un gesto al otro lado de la Grada, hacia la posada y el maestro de establos que se encuentra fuera.>' WHERE `ID`=19371;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<비전 수호병이 당신이 어떤 전투모병관인지 자세히 설명해 주길 기다리며 꼼짝 않고 서 있습니다.>', `MaleText_loc4`='<奥术守护者静静地站在那，等着你告诉它你想询问哪个战场军官。>', `MaleText_loc5`='<秘法護衛站著不動，等著你詳細說明你所指的是哪個戰場軍官。>', `MaleText_loc7`='<El guardián Arcano se queda inmóvil, esperando que expliques detalladamente a qué maestros de batalla te refieres.>' WHERE `ID`=19372;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽어 나자빠지는 놈들이 많아서 일손이 부족한 형편이다.', `MaleText_loc4`='他们经常翻脸，而且老实说，我们的人手也不够。', `MaleText_loc5`='他們大部份常會轉變成致命的，並且根據情況看，我們人員過少。', `MaleText_loc7`='Muy a menudo son letales, y esto es un eufemismo.' WHERE `ID`=19373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<오크 늑대가 얼어붙은 주둥이로 으르렁대자 당신은 뼈까지 시려오기 시작합니다.>', `MaleText_loc4`='<兽人座狼的血盆大口让你毛骨悚然。>', `MaleText_loc5`='<獸人狼騎兵被冰凍，其咆哮的聲音令你不寒而慄。>', `MaleText_loc7`='<Las temibles fauces congeladas del lobo orco te provocan escalofríos.>' WHERE `ID`=19374;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오크 늑대 조종', `MaleText_loc4`='控制兽人座狼', `MaleText_loc5`='控制獸人狼騎兵', `MaleText_loc7`='Controlar lobo orco', `FemaleText_loc1`='오크 늑대 조종', `FemaleText_loc4`='控制兽人座狼', `FemaleText_loc5`='控制獸人狼騎兵', `FemaleText_loc7`='Controlar lobo orco' WHERE `ID`=19375;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<흑마법사의 눈빛에 깊은 증오가 이글거립니다.>', `MaleText_loc4`='<术士的双眼中积郁着深深的怨毒。>', `MaleText_loc5`='<那個術士的雙眼蘊含了深深的惡意。>', `MaleText_loc7`='<Tras los ojos del brujo arde una malevolencia profunda.>' WHERE `ID`=19376;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오크 흑마법사 조종', `MaleText_loc4`='控制兽人术士', `MaleText_loc5`='控制獸人術士', `MaleText_loc7`='Controlar orco brujo', `FemaleText_loc1`='오크 흑마법사 조종', `FemaleText_loc4`='控制兽人术士', `FemaleText_loc5`='控制獸人術士', `FemaleText_loc7`='Controlar orco brujo' WHERE `ID`=19377;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='추비스 추비시모! 저 물건들을 고쳐놔... 시간이 많지 않단 말이야!', `MaleText_loc4`='库比斯，库比斯！把那些东西修好……我们时间不多了！', `MaleText_loc5`='恰比斯，恰比斯阿!把那些東西修好...我們不能做上一整天!', `MaleText_loc7`='¡Chubis, Chubísimo! Arregla esas cosas... ¡no tenemos todo el día!' WHERE `ID`=19378;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 자네 나이 때는 아침 먹기 전에 절단기들을 전부 고쳐 놓고 또 다른 일을 할 시간이 남았단 말이야. 여명의 설원의 눈밭에서도 마찬가지였다네. 알다시피 거기 오가는 길은 모두 오르막길이라 더 어렵잖아!', `MaleText_loc4`='我像你这个年纪的时候能在早餐前修好所有收割机，还能腾出时间做完其它的杂事。而且还是在冬泉谷的大雪中，而且都要爬山的！', `MaleText_loc5`='在我跟你同樣年紀的時候，在早餐前我就能把那些伐木機都修好，並且還有時間去做所有其他的家務雜活。就在早春的雪裡，一點也不少。而且是在那裡上坡路的兩旁!', `MaleText_loc7`='Cuando tenía tu edad podía arreglar todas esas trituradoras antes del desayuno y aún me quedaba tiempo para mis otras tareas. En la nieve de Cuna del Invierno, nada menos. ¡Y es cuesta arriba los dos caminos!' WHERE `ID`=19379;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='추비스, 거기 일을 마치면 휠러 자동차에 왁스칠 한 번 더 해놓는 것 잊지 마라. 오늘 밤, 우리 마누라랑 드라이브나 한 번 나갈까 하니까...', `MaleText_loc4`='库比斯，当你完成了那边的工作以后，记得在维勒旅行器上再打一层蜡。今晚我想带维勒老妈出去兜兜风。', `MaleText_loc5`='恰比斯，在你完成那裡的工作之後，確認你有幫威勒的車子上了另一層蠟。我今晚想帶媽媽外出兜風。', `MaleText_loc7`='Chubis, cuando hayas terminado con eso, asegúrate de poner otra capa de cera al móvil Ruedas. Quiero sacar a mamá para dar un paseo esta noche.' WHERE `ID`=19380;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 받는 월급이 얼마인지나 알고 있나? 지금 저걸 일이라고 한 거야?', `MaleText_loc4`='我付了多少钱给你？这也叫干活？', `MaleText_loc5`='我付給你多少?你說那個叫成品?', `MaleText_loc7`='¿Cuánto te pago? ¿A eso le llamas trabajar?' WHERE `ID`=19381;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비보를 해고하는 게 아니었는데!', `MaleText_loc4`='我真后悔解雇了贝波！', `MaleText_loc5`='我就知道我不該開除嗶啵的!', `MaleText_loc7`='¡Sabía que no tenía que haber despedido a Beebo!' WHERE `ID`=19382;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<대족장 블랙핸드가 좌중을 내려보며 서 있습니다.>', `MaleText_loc4`='<黑手酋长俯瞰着战场。>', `MaleText_loc5`='<大酋長黑手俯視著大地。>', `MaleText_loc7`='<El Jefe de Guerra Puño Negro domina el campo.>' WHERE `ID`=19383;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장 블랙핸드 조종', `MaleText_loc4`='控制黑手酋长', `MaleText_loc5`='控制大酋長黑手', `MaleText_loc7`='Controlar Jefe de Guerra Puño Negro', `FemaleText_loc1`='대족장 블랙핸드 조종', `FemaleText_loc4`='控制黑手酋长', `FemaleText_loc5`='控制大酋長黑手', `FemaleText_loc7`='Controlar jefe de guerra Puño Negro' WHERE `ID`=19384;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 자네가 저 중 하나만 고쳐 놓으면 휴식 시간을 무려 10분이나 주겠다고. 어떤가? 좋지?', `MaleText_loc4`='好吧，如果你能修好那些东西中的任意一个，我就让你休息十分钟。怎么样？不错吧？', `MaleText_loc5`='好，只要你能設法得到那些修理過的其中一個，我就讓你休息10分鐘。聽起來怎樣?很不錯，對吧?', `MaleText_loc7`='De acuerdo, si consigues arreglar aunque solo sea uno de estos, te dejaré hacer un descanso de diez minutos. ¿Qué tal suena? Bastante bien, ¿eh?' WHERE `ID`=19385;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 곤경에 빠뜨리려는 건가? 할 일이 무척 많단 말이야. 게다가 저기 휠러 영감은 내가 노는 꼴을 두고 보는 법이 없다고.', `MaleText_loc4`='你在给我找事吧？我手头上还有很多工作呢，而且老维勒这个家伙还不让我休息。', `MaleText_loc5`='你想要我惹上麻煩嗎?我這裡有許多工作要做，而且那裡的老人威勒不會讓我有任何機會鬆懈的。', `MaleText_loc7`='¿Quieres que me meta en un lío? Tengo mucho trabajo por hacer aquí, y el viejo Ruedas no me deja tranquilo.' WHERE `ID`=19386;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경비병! 이쪽으로!', `MaleText_loc4`='卫兵们！到我这里来！', `MaleText_loc5`='守衛!在我這裡!', `MaleText_loc7`='¡Guardianes! ¡A mí!' WHERE `ID`=19387;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 번만 더 그러면 가만두지 않을 테다.', `MaleText_loc4`='如果你再敢这么做，我会扭断你的脖子。', `MaleText_loc5`='如果你膽敢再做一次，我就會打斷你的脖子。', `MaleText_loc7`='Si vuelves a hacer eso alguna vez, te rompo el cuello.' WHERE `ID`=19388;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멋지군!', `MaleText_loc4`='真迷人。', `MaleText_loc5`='太棒了。', `MaleText_loc7`='Fascinante.' WHERE `ID`=19389;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 시간과 소리를 연구하는 과학자입니다. 이렇게 소란스러운 분위기에서 어떻게 연구를 하고 일을 하라는 건지 모르겠습니다!$B$B저 바보들이 어디 다른 곳으로 가서 자폭이라도 하게 할 수는 없을까요?$B$B어쨌거나, 제가 유망하긴 하죠. 그건 그렇고 우리가 전에 여기서 만난 적이 있던가요?', `MaleText_loc4`='我是个研究时间和声音的科学家，因此我不十分确信我该怎么来思考，或是找个时间在这喧嚣里来完成什么工作。$B$B为什么这些蠢货不把他们自己炸到其他地方去呢？$B$B啊，好吧，至少我看起来不错。对了， $g小子:小姑娘;，我以前在这里见过你吗？', `MaleText_loc5`='我是研究時間和聲音的科學家，因此我不是很肯定我應該怎樣思考，還是抽出時間在這周遭做些功課，跟這所有的喧鬧一起?!$B$B為什麼這些傻瓜不能把他們自己吹到別的地方呢?$B$B嗯好吧，至少我看起來很好。說吧，$g男孩:美女;，以前我在這附近看過你嗎?', `MaleText_loc7`='¡Soy un científico que estudia el tiempo y el sonido, así que no estoy muy seguro de cómo se supone que tengo que pensar o encontrar el tiempo para hacer nada de trabajo aquí, con todo este ruido!$B$B¿Por qué no van esos estúpidos a volarse a otra parte?$B$BAh, bueno, al menos tengo buen aspecto. Dime, $gmuchacho:preciosa;, ¿te he visto antes por aquí?' WHERE `ID`=19390;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불의 정령이 우리에게 지혜를 내리셨소!', `MaleText_loc4`='请赐予我们智慧吧，火焰之灵！', `MaleText_loc5`='火焰之靈賜予我們智慧!', `MaleText_loc7`='¡Que los espíritus del fuego nos otorguen sabiduría!' WHERE `ID`=19391;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s 아래 공허의 힘이 모입니다!', `MaleText_loc4`='虚空能量聚集在%s的底部！', `MaleText_loc5`='虛無能量集結在%s的營地!', `MaleText_loc7`='¡La energía del vacío se acumula en la base del %s!', `FemaleText_loc1`='%s 아래 공허의 힘이 모입니다!', `FemaleText_loc4`='虚空能量聚集在%s的底部！', `FemaleText_loc5`='虛無能量集結在%s的營地!', `FemaleText_loc7`='¡La energía del vacío se acumula en la base del %s!' WHERE `ID`=19392;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적을 향해 진격할 준비를 해라. 곧 배신자에 대한 총공격을 개시할 것이다.', `MaleText_loc4`='准备向敌人推进。我们很快就会对背叛者发动全面进攻。', `MaleText_loc5`='準備向敵人前進。我們很快就會對背叛者發動全面攻擊。', `MaleText_loc7`='Prepárate para avanzar sobre el enemigo. Pronto lanzaremos un ataque sobre el Traidor.' WHERE `ID`=19393;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='흥, 이따위 감옥에 오래 머물러 있지는 않을 것이다. 어떻게 해서든 일리단을 없앨 것이다.', `FemaleText_loc4`='这个监狱是关不住我的。无论如何我都要取下伊利丹的首级。', `FemaleText_loc5`='這間小屋無法困住我太久。無論如何，我都會取下伊利丹的頭。', `FemaleText_loc7`='No estaré mucho tiempo en esta celda. Tendré la cabeza de Illidan de una forma u otra.' WHERE `ID`=19394;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당장 나를 풀어주지 않으면 내 분노를 피할 수 없을 것이야!', `FemaleText_loc4`='快点放了我！不然就面对我的愤怒吧！', `FemaleText_loc5`='立即釋放我，否則就面對我的憤怒!', `FemaleText_loc7`='¡Libérame inmediatamente o enfréntate a mi ira!' WHERE `ID`=19395;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 쓰레기 같은 뒤틀린 드레나이야, 네가 무슨 계략을 꾸미는지는 모르겠지만 절대로 날 이용할 수는 없다!', `FemaleText_loc4`='我不知道你在预谋着什么诡计，肮脏的破碎者，但是休想把我卷进去！', `FemaleText_loc5`='我不知道你企圖進行什麼樣的詭計，卑鄙的破碎者，不過我不想要讓這件事去沾到任何一點邊!', `FemaleText_loc7`='¡No sé que tipo de ardid tramas, miserable Tábido, pero no quiero formar parte de ello!' WHERE `ID`=19396;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리를 막을 순 없다!', `MaleText_loc4`='你休想阻止我们！', `MaleText_loc5`='你阻止不了我們!', `MaleText_loc7`='¡No puedes detenernos!' WHERE `ID`=19397;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 $r|1이;가; 감히 내 부하들을 다치게 하느냐?', `MaleText_loc4`='哪个$r竟敢伤害我的手下？', `MaleText_loc5`='是什麼$r敢傷害我的羊群?', `MaleText_loc7`='¿Qué $r osa hacer daño a mi rebaño?' WHERE `ID`=19398;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마치 길에서 쓰레기를 치운 것 마냥 누군가 이 오크의 시체를 아무렇게나 한쪽 옆으로 던져 놓았습니다.', `MaleText_loc4`='为了保持道路的整洁，兽人的尸体被随便地丢弃在路的两旁。', `MaleText_loc5`='為了不使走道凌亂，獸人的屍體已經被隨便扔到一旁。', `MaleText_loc7`='El cadáver del orco se ha apartado a un lado para no ensuciar el camino.' WHERE `ID`=19399;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시체를 뒤져 카그로쉬의 짐꾸러미를 찾습니다.', `MaleText_loc4`='在尸体上寻找卡格罗什的背包。', `MaleText_loc5`='為了凱格羅西的背包搜尋屍體。', `MaleText_loc7`='Busca la talega de Kagrosh en el cadáver.', `FemaleText_loc1`='시체를 뒤져 카그로쉬의 짐꾸러미를 찾습니다.', `FemaleText_loc4`='在尸体上寻找卡格罗什的背包。', `FemaleText_loc5`='為了凱格羅西的背包搜尋屍體。', `FemaleText_loc7`='Busca la talega de Kagrosh en el cadáver.' WHERE `ID`=19400;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에 필멸의 생명체들이 왔다고? 뒤틀린 드레나이야, 도대체 무슨 속셈이냐?!', `MaleText_loc4`='这里有凡人？这是什么意思，你这可悲的破碎者！', `MaleText_loc5`='人類，在這裡嗎?這是什麼意思，淒慘的破碎者!', `MaleText_loc7`='¿Mortales, aquí? ¡Qué significa esto, patético Tábido!' WHERE `ID`=19401;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$r|1이여;여;, 두려워하지 말게. 그냥 물 흐르듯 이 상황을 즐겨.', `MaleText_loc4`='不要害怕，$r。继续假装下去。', `MaleText_loc5`='沒有恐懼，$R。只有合作。', `MaleText_loc7`='No tengas miedo, $r. Sigue la corriente.' WHERE `ID`=19402;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='별일 아닐세! 이 아카마와 나의 맹신도들이 감시하는 동안 포로가 달아날 일은 없을 거라고 주인님께 전하게.', `MaleText_loc4`='一点小麻烦而已，我保证！请转告主人，阿卡玛和他手下的死誓者会尽心尽职地看守囚犯。', `MaleText_loc5`='不過就是個討厭的人，我向你保證!告訴主人他的犯人在阿卡瑪以及他的死亡誓言者監守之下將無法脫逃。', `MaleText_loc7`='¡Una simple molestia, te lo aseguro! Dile al maestro que su prisionero no escapará mientras Akama y sus Juramorte lo vigilen.' WHERE `ID`=19403;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 우습게 알면 큰코다칠 줄 알아라, 아카마! 일리단 님에게 감시자를 잘 지켜보라는 명령을 받았다. 뭔가 숨기고 있는 게 들통나면 널 내 손으로 박살 낼 것이다!', `MaleText_loc4`='阿卡玛，别跟我耍花招。伊利丹大人要我密切注视玛维·影歌的一举一动。要是你敢对我隐瞒什么，我就亲手捏碎你！', `MaleText_loc5`='你做得很好，沒有戲弄我，阿卡瑪。伊利丹已經給了我明確的命令，要我緊密注意守衛者。如果我發現你隱藏任何事情不讓我知道，我將親手擊碎你!', `MaleText_loc7`='Harías bien en no jugar conmigo, Akama. Illidan me ha dado órdenes concretas de vigilar de cerca al Celador. ¡Si me ocultas algo, te aplastaré con mis propias manos!' WHERE `ID`=19404;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 방법이 거슬렸다면 용서하게. 하지만, 배신자는 결코 진실을 알아낼 수 없을 거야. 무슨 일이 있어도 난 비밀을 지킬 거라고!', `MaleText_loc4`='请原谅我的粗暴，我不能让背叛者知道真相。无论如何都要守住我的秘密！', `MaleText_loc5`='請原諒我嚴厲的方式，不過背叛者不能獲悉事實。我的秘密必須不惜任何代價的堅守住!', `MaleText_loc7`='Perdona mis duros métodos, pero el Traidor no puede conocer la verdad. ¡Mi secreto debe ser guardado a toda costa!' WHERE `ID`=19405;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 동족은 나를 배신자로 알고 있네. 일리단의 충견으로... 당분간은 그렇게 알고 있는 편이 제일 좋겠지.', `MaleText_loc4`='我的许多同胞都认为我是叛徒……是伊利丹的走狗。现在也许他们这么想才更好。', `MaleText_loc5`='對大多數人我的族人來說我是一個賣國賊...做伊利丹的走狗。他們現在繼續那樣認為是最好的。', `MaleText_loc7`='Gran parte de mi pueblo me conoce como un traidor... como el perrito faldero de Illidan. Es mejor que lo sigan pensando por ahora.' WHERE `ID`=19406;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리가 정말 같은 것을 원한다면 날 풀어줘라, 아카마! 일리단이 죽어야 한다면 바로 내 손으로 죽어야겠어!', `FemaleText_loc4`='如果我们期望的是同一件事，阿卡玛，那么你就放了我！如果伊利丹要死，那也要是死在我的手上！', `FemaleText_loc5`='如果我們真的想要同樣的東西，阿卡瑪，那麼釋放我!如果伊利丹會死，那將是透過我的手!', `FemaleText_loc7`='¡Si de verdad deseamos lo mismo, Akama, libérame! ¡Si Illidan debe morir, será por mis propias manos!' WHERE `ID`=19407;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직은 때가 아닐세, 마이에브... 난 여러 해를 준비해 왔어. 괜히 서두르다가 계획을 망치는 실수를 범할 수는 없어.', `MaleText_loc4`='不会太久了，玛维。我花了这么多年来筹划我的行动——我不能让这个计划因为操之过急而毁于一旦。', `MaleText_loc5`='在適當的時候，瑪翼夫。我已經花費數年準備行動 - 我不能太快攤牌讓我的計畫處於危險中。', `MaleText_loc7`='A su debido tiempo, Maiev. He pasado años preparándome para mi jugada – no puedo permitirme poner en peligro mis planes precipitándome.' WHERE `ID`=19408;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='널 저주한다, 아카마! 나는 네 장기판의 말이 아니야... 내 의지는 나만의 것이야. 내가 일리단을 쓰러뜨릴 때 네 멍청한 계획은 아무짝에도 도움이 안 될 것이다!', `FemaleText_loc4`='我诅咒你，阿卡玛！我不是你的棋子……我有我自己的意志。当我对伊利丹倾泻我的愤怒时，那必定和你愚蠢的阴谋没有任何关系！', `FemaleText_loc5`='詛咒你，阿卡瑪!我不是你遊戲中的棋子...我的意志屬於我自己。當我對伊利丹釋放我的憤怒時，它與你的愚蠢的計畫無關!', `FemaleText_loc7`='¡Te maldigo, Akama! No soy un peón de tu juego... mi voluntad es mía. ¡Cuando desate mi ira sobre Illidan, no tendrá nada que ver con tu estúpido plan!' WHERE `ID`=19409;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모든 보상은 전쟁인도자 사르돈 트루슬라이스가 지급한다.$B$B청구서를 보내는 일이 없기를 바란다.', `MaleText_loc4`='所有悬赏的奖励品都由战争召唤者萨尔东·图斯莱分配。$B$B张贴悬赏令不需支付金币。', `MaleText_loc5`='全部的效命報酬交由喚戰者薩爾登·崔賴斯分配。$B$B不張貼清單。', `MaleText_loc7`='Todas las recompensas por servicios prestados son administradas por el Clamaguerras Sardon Cortecertero.$B$BNo colguéis facturas.' WHERE `ID`=19410;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모든 보상은 전쟁인도자 비어스나웃이 지급할 것이다.$B$B청구서를 보내는 일이 없기를 바란다.', `MaleText_loc4`='所有悬赏的奖励品都由战争召唤者比尔斯诺特分配。$B$B张贴悬赏令不需支付金币。', `MaleText_loc5`='全部的效命報酬交由喚戰者畢爾斯納特分配。$B$B不張貼清單。', `MaleText_loc7`='Todas las recompensas por servicios prestados son administradas por Clamaguerras Birramorro.$B$BNo colguéis facturas.' WHERE `ID`=19411;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘될 겁니다! 우리가 건 보상을 보면 모험가들이 구름떼처럼 몰려올 겁니다!', `MaleText_loc4`='没错！要是他们看到了我们提供的奖励，肯定会过来的。', `MaleText_loc5`='贊成，就這樣做!一旦他們看見我們提出的報酬，他們將再一次跑過來!', `MaleText_loc7`='¡Sí, eso servirá! ¡Vendrán corriendo en cuanto vean la recompensa que hemos colgado!' WHERE `ID`=19412;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 보상이 있다는 걸 알면 모험가들이 그냥 지나칠 리가 없겠죠...', `MaleText_loc4`='有这样的奖励，他们怎么可能拒绝呢？', `MaleText_loc5`='有這樣的獎勵，他們怎能拒絕呢，老兄?', `MaleText_loc7`='Con una recompensa como esa, ¿cómo podrían decir que no?' WHERE `ID`=19413;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 주인이 죽는 모습을 보고 격분하여 자폭합니다.', `MaleText_loc4`='%s看到它的主人死去，狂怒地引爆了自己。', `MaleText_loc5`='%s看見主人死亡後爆出狂怒。', `MaleText_loc7`='%s detona con rabia tras ver morir a su maestro.' WHERE `ID`=19414;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 격분합니다.', `MaleText_loc4`='%s变得非常愤怒。', `MaleText_loc5`='%s變得狂怒。', `MaleText_loc7`='%s monta en cólera.' WHERE `ID`=19415;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구체화의 방을 준비하라. 조만간 또 다른 동맹이 우리 군대와 함께할 것이다!', `MaleText_loc4`='准备好具化间，新的同盟很快就会加入我们！', `MaleText_loc5`='準備好實體化室，另一個盟友不久將加入我們的行列!', `MaleText_loc7`='¡Prepara las cámaras, pronto se unirá a nuestras filas otro aliado!' WHERE `ID`=19416;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 동맹이 도착했다! 구체화의 방으로 가는 길을 열어라!', `MaleText_loc4`='我们的同盟到了！打开具化间！', `MaleText_loc5`='我們的盟友已到達!清出到實體化室的路!', `MaleText_loc7`='¡Ha llegado nuestro aliado! ¡Despejad el camino a la cámara de materialización!' WHERE `ID`=19417;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 순간이동 장치로 가라. 격노의 괴철로 기지가 그대들의 도착을 기다리고 있도다!', `MaleText_loc4`='现在，向传送器进发。铸魔营地：天罚等着你的到来！', `MaleText_loc5`='現在，出發到傳送者那裡。煉冶場憤怒等待你的到達!', `MaleText_loc7`='Bueno, avanza al trasladador. ¡El Campamento Forja Ira aguarda tu llegada!' WHERE `ID`=19418;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꽥! 누가 감히 내 숭배자들을 죽이고 대사제인 날 소환하는 것이냐!', `MaleText_loc4`='Squawk!  Who dare slay my Worshippers and summon me , High Priest A, forth! [PH]', `MaleText_loc5`='嘎!是誰膽敢殺死我的信奉者並且召喚我，高階祭司A，向前![PH]', `MaleText_loc7`='¡Kruaaaac! ¿Quién osa asesinar a mis adoradores e invocarme, el sumo sacerdote A! [PH]' WHERE `ID`=19419;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배가 고프구나! 아이들아, 내게 이 괴철로의 힘을 바쳐라!', `MaleText_loc4`='我饿了！用这座熔炉的能量喂食我吧，孩子们！', `MaleText_loc5`='我渴望!我的孩子，把這只鍛爐的力量餵給我!', `MaleText_loc7`='¡Tengo hambre! ¡Alimentadme con el poder de esta forja, hijos míos!' WHERE `ID`=19420;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청한 놈들! 집합!', `MaleText_loc4`='蠢货们！集合！', `MaleText_loc5`='笨蛋!快集合!', `MaleText_loc7`='¡Estúpidos! ¡Reuníos!' WHERE `ID`=19421;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='초대받지 않은 손님이 있군...', `MaleText_loc4`='We have some uninvited guests.... [PH]', `MaleText_loc5`='我們有一些不速之客... [PH]', `MaleText_loc7`='Tenemos unos invitados sorpresa... [PH]' WHERE `ID`=19422;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오, 이거 재미있겠는데!', `FemaleText_loc4`='Ooh, this shall be fun! [PH]', `FemaleText_loc5`='喔，這會很有趣![PH]', `FemaleText_loc7`='¡Oh, esto será divertido! [PH]' WHERE `ID`=19423;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='토쉴리의 연구기지 여관에 오신 것을 환영합니다. 뭘 도와 드릴까요?', `MaleText_loc4`='欢迎来到托什雷的基地旅店。我能为你做些什么？', `MaleText_loc5`='歡迎到托斯利基地旅店。我能為你做什麼?', `MaleText_loc7`='$gBienvenido:Bienvenida; a la posada de la Estación de Toshley. ¿Qué puedo hacer por ti?' WHERE `ID`=19424;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='보석세공을 배우고 싶으십니까?', `FemaleText_loc4`='你对学习复杂的珠宝加工感兴趣吗？', `FemaleText_loc5`='你對學習珠寶設計的錯綜複雜之處感興趣嗎?', `FemaleText_loc7`='¿Te interesa aprender las complejidades de la joyería?' WHERE `ID`=19425;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보석 추출은 어떻게 하는 겁니까?', `MaleText_loc4`='我该怎么使用选矿技能？', `MaleText_loc5`='我要如何使用勘探?', `MaleText_loc7`='¿Cómo utilizo la prospección?', `FemaleText_loc1`='보석 추출은 어떻게 하는 건가요?', `FemaleText_loc4`='我该怎么使用选矿技能？', `FemaleText_loc5`='我要如何使用勘探?', `FemaleText_loc7`='¿Cómo utilizo la prospección?' WHERE `ID`=19426;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보석은 주로 보석 추출을 통하여 얻을 수 있습니다! 보석 추출을 하려면 여러분의 마법책의 전문 기술란에 있는 보석 추출 기술을 눌러 소지품에 있는 광석 5개에 사용하면 됩니다. 흔히 볼 수 있는 어떤 광석이든 가능합니다!

좋은 광석을 사용하면 더욱 귀한 보석을 추출할 수 있습니다. 따라서 구리 광석보다는 철 광석에서 더욱 희귀한 보석을 얻을 수 있습니다.', `MaleText_loc4`='选矿是找到宝石的主要途径！你只需简单地使用选矿技能（可以在你的法术书的综合标签中找到）就可以在一组五个的矿石中找到宝石。任何非贵重的矿石都可以！

更好的矿石会提供更有价值的宝石，也就是说你从铁矿石里找到的宝石比从铜矿石中找到的更好！', `MaleText_loc5`='勘探是發現寶石的主要方式!你只要使用勘探技能(可於你的法術書一般標籤中找到)，在五個一疊的礦石中提煉出寶石。任何類型的非珍貴礦石都可以!

品質較佳的礦石將可提供更有價值的寶石，因此與銅礦相比，你可以在鐵礦中找到品質較高的寶石。', `MaleText_loc7`='¡La prospección es el método principal para encontrar piedras preciosas! Simplemente usa la habilidad de prospección (que se encuentra en la pestaña Profesiones de tu libro de hechizos) en un montón de cinco minerales para extraerle las piedras preciosas. ¡Cualquier tipo de mineral no precioso servirá! 

Los minerales de mejor calidad proporcionarán piedras preciosas más valiosas, así que encontrarás piedras preciosas de mayor calidad en el mineral de hierro que en el mineral de cobre.', `FemaleText_loc1`='보석은 주로 보석 추출을 통하여 얻을 수 있습니다! 보석 추출을 하려면 여러분의 마법책의 전문 기술란에 있는 보석 추출 기술을 눌러 소지품에 있는 광석 5개에 사용하면 됩니다. 흔히 볼 수 있는 어떤 광석이든 가능합니다!

좋은 광석을 사용하면 더욱 귀한 보석을 추출할 수 있습니다. 따라서 구리 광석보다는 철 광석에서 더욱 희귀한 보석을 얻을 수 있습니다.', `FemaleText_loc4`='选矿是找到宝石的主要途径！你只需简单地使用选矿技能（可以在你的法术书的综合标签中找到）就可以在一组五个的矿石中找到宝石。任何非贵重的矿石都可以！

更好的矿石会提供更有价值的宝石，也就是说你从铁矿石里找到的宝石比从铜矿石中找到的更好！', `FemaleText_loc5`='勘探是發現寶石的主要方式!你只要使用勘探技能(可於你的法術書一般標籤中找到)，在五個一疊的礦石中提煉出寶石。任何類型的非珍貴礦石都可以!

品質較佳的礦石將可提供更有價值的寶石，因此與銅礦相比，你可以在鐵礦中找到品質較高的寶石。', `FemaleText_loc7`='¡La prospección es el método principal para encontrar piedras preciosas! Simplemente usa la habilidad de prospección (que se encuentra en la pestaña profesiones de tu libro de hechizos) en un montón de cinco minerales para extraerle las piedras preciosas. ¡Cualquier tipo de mineral no precioso servirá! 

Los minerales de mejor calidad proporcionarán piedras preciosas más valiosas, así que encontrarás piedras preciosas de mayor calidad en el mineral de hierro que en el mineral de cobre.' WHERE `ID`=19427;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디로 가면 보석세공을 계속 배울 수 있습니까?', `MaleText_loc4`='我在哪里可以继续我的珠宝加工训练？', `MaleText_loc5`='我要去哪裡繼續我的珠寶設計訓練?', `MaleText_loc7`='¿Dónde puedo continuar mi instrucción en joyería?', `FemaleText_loc1`='어디로 가면 보석세공을 계속 배울 수 있나요?', `FemaleText_loc4`='我在哪里可以继续我的珠宝加工训练？', `FemaleText_loc5`='我要去哪裡繼續我的珠寶設計訓練?', `FemaleText_loc7`='¿Dónde puedo continuar mi instrucción en joyería?' WHERE `ID`=19428;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='보석세공을 계속해서 배우고 싶으면 실버문에 있는 텔리아의 상점으로 가십시오. 텔리아의 상점은 왕궁 교역소의 남쪽 끝에 있습니다.', `FemaleText_loc4`='如果你想提高你的技艺，就去银月城吧。泰莉亚的商店就在皇家贸易区的南方尽头。', `FemaleText_loc5`='如果你希望精進你的技能，在銀月城尋找蒂莉雅的商店。它在皇家交易所拍賣場的南方盡頭。', `FemaleText_loc7`='Si deseas mejorar tus habilidades, busca la tienda de Telia, en Lunargenta. Está en el extremo sur del Intercambio Real.' WHERE `ID`=19429;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시험 중...', `MaleText_loc4`='测试……', `MaleText_loc5`='測試中...', `MaleText_loc7`='Probando...' WHERE `ID`=19430;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보석세공에 대해 알고 싶은 게 있으신가요?', `MaleText_loc4`='关于珠宝加工，你想知道些什么？', `MaleText_loc5`='你想學習哪一方面的珠寶設計?', `MaleText_loc7`='¿Qué deseas saber acerca de la joyería?' WHERE `ID`=19431;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='보석세공의 초급 단계를 마치기 전에는 가르쳐 드릴 것이 없습니다.', `FemaleText_loc4`='不要再来找我，等你掌握了初级的珠宝加工技能再说。', `FemaleText_loc5`='在你到達珠寶設計的學徒水準前我們將不再交談。', `FemaleText_loc7`='Hasta que no domines el nivel de aprendiz de joyería no volveremos a hablar.' WHERE `ID`=19432;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내가 알고 있는 보석세공에 대한 지식을 가르쳐 드리겠습니다.', `FemaleText_loc4`='我会和你分享我的珠宝加工知识。', `FemaleText_loc5`='我將與你分享我的珠寶設計知識。', `FemaleText_loc7`='Compartiré contigo mis conocimientos de joyería.' WHERE `ID`=19433;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보석을 만드는 일은 제 인생의 전부랍니다. 제 열정을 담는 일에 동참하시겠습니까?', `MaleText_loc4`='制造珠宝和雕琢宝石是我生存的理由。想让我把这种激情分享给你吗？', `MaleText_loc5`='創造珠寶和寶石是我生存的目的。我能與你分享我的熱情嗎?', `MaleText_loc7`='La creación de joyas y gemas es para lo que vivo. ¿Puedo compartir mi pasión contigo?', `FemaleText_loc1`='보석을 만드는 일은 제 인생의 전부랍니다. 제 열정을 담는 일에 동참하시겠습니까?', `FemaleText_loc4`='制造珠宝和雕琢宝石是我生存的理由。想让我把这种激情分享给你吗？', `FemaleText_loc5`='創造珠寶和寶石是我生存的目的。我能與你分享我的熱情嗎?', `FemaleText_loc7`='La creación de joyas y gemas es para lo que vivo. ¿Puedo compartir mi pasión contigo?' WHERE `ID`=19434;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='절 찾아오는 분들을 전부 가르칠 여유가 있다면 좋겠죠. 안타깝게도 그건 보석세공을 가르치는 순서가 아니랍니다. 파다르가 가르치는 것을 전부 배우기 전까지는 당신을 도울 수 없습니다.', `FemaleText_loc4`='我希望有更多的时间来向所有找我学习的人传授知识，但是做事必须循序渐进。在你把帕达尔教你的东西都学会之前，我帮不了你。', `FemaleText_loc5`='我希望我有更多的時間教導所有比我重要的人，但是哎，沒辦法。除非你已經學會所有帕達爾要教的，否則我不能幫助你。', `FemaleText_loc7`='Desearía tener más tiempo para enseñar a todos los que se dirigieron a mí, pero así no es como funcionan las cosas. Hasta que no hayas aprendido todo lo que Driann tiene que enseñarte, no puedo ayudarte.' WHERE `ID`=19435;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신 같이 보석세공에 대한 해박한 지식을 갖춘 분을 보석세공의 최고의 경지로 이끌게 되어서 영광이로군요. 어떤 것을 배우고 싶습니까?', `FemaleText_loc4`='我很愿意教你这样的技术人才更多的珠宝加工知识。你想知道什么？', `FemaleText_loc5`='我很樂意可以幫助你的某些技能以學習更多的珠寶設計。你想知道些什麼?', `FemaleText_loc7`='Es una bendición poder ayudar a alguien con tus habilidades a aprender más sobre la joyería. ¿Qué deseas saber?' WHERE `ID`=19436;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전장에서 자신의 주인이 쓰러지는 모습을 보자 %s|1이;가; 분노에 휩싸입니다!', `MaleText_loc4`='%s看到它的主人阵亡后，变得异常愤怒！', `MaleText_loc5`='%s看到主人在戰鬥中倒下後狂怒!', `MaleText_loc7`='¡%s monta en cólera después de ver a su maestro caer en la batalla!', `FemaleText_loc1`='전장에서 자신의 주인이 쓰러지는 모습을 보자 %s|1이;가; 분노에 휩싸입니다!', `FemaleText_loc4`='%s看到它的主人阵亡后，变得异常愤怒！', `FemaleText_loc5`='%s看到主人在戰鬥中倒下後狂怒!', `FemaleText_loc7`='¡%s monta en cólera después de ver a su maestro caer en la batalla!' WHERE `ID`=19437;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s의 명령으로 소환수가 격노합니다!', `MaleText_loc4`='%s命令他的宠物进入了狂怒状态！', `MaleText_loc5`='%s讓它的寵物發狂了!', `MaleText_loc7`='¡%s hace que su mascota monte en una cólera bestial!' WHERE `ID`=19438;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s의 두꺼운 비늘이 갈라지기 시작합니다.', `MaleText_loc4`='%s厚重的鳞片开始碎裂。', `MaleText_loc5`='%s的厚殼開始破裂。', `MaleText_loc7`='Las gruesas escamas de %s comienzan a agrietarse.' WHERE `ID`=19439;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s의 비늘이 갈라지자 그 아래 부드러운 속살이 드러납니다.', `MaleText_loc4`='%s的鳞片碎开了，露出了下面的软肉。', `MaleText_loc5`='%s的殼粉碎，露出底下柔軟的肉。', `MaleText_loc7`='Las escamas de %s se hacen añicos, mostrando su suave carne.' WHERE `ID`=19440;
