UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='난 아주 바쁜 몸일세.$B$B당장 처리해야 할 중대한 문제가 있다고!', `FemaleText_loc4`='我非常忙，$r。$B$B我们现在有一个非常棘手的问题需要立刻解决！', `FemaleText_loc5`='我極其忙碌，$r。$B$B我們手上有一個棘手的問題必須立刻處理!', `FemaleText_loc7`='Estoy muy ocupada, $r.$B$B¡Tenemos un problema terrible en nuestras manos del que debemos ocuparnos de inmediato!' WHERE `ID`=19442;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힐다가드, 새 투시경이 필요합니다.', `MaleText_loc4`='希尔达迦，我需要一副新的眼镜。', `MaleText_loc5`='希爾達嘉，我需要一副新的護目鏡。', `MaleText_loc7`='Hildagard, necesito un nuevo par de gafas.', `FemaleText_loc1`='힐다가드, 새 투시경이 필요해요.', `FemaleText_loc4`='希尔达迦，我需要一副新的眼镜。', `FemaleText_loc5`='希爾達嘉，我需要一副新的護目鏡。', `FemaleText_loc7`='Hildagard, necesito un nuevo par de gafas.' WHERE `ID`=19443;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 결코 사라지지 않는다, 필멸의 존재여... 우리의 운명은 고어핀드에게 묶여 있다...', `MaleText_loc4`='我们永远都不会消散，凡人……我们的命运与塔隆紧紧相连……', `MaleText_loc5`='我們絕不會消散，凡人...我們的命運與血魔相繫...', `MaleText_loc7`='Nunca nos disiparemos, mortal... Nuestro destino está unido a Sanguino...', `FemaleText_loc1`='우리는 결코 사라지지 않는다, 필멸의 존재여... 우리의 운명은 고어핀드에게 묶여 있다...', `FemaleText_loc4`='我们永远都不会消散，凡人……我们的命运与塔隆紧紧相连……', `FemaleText_loc5`='我們絕不會消散，凡人...我們的命運與血魔相繫...', `FemaleText_loc7`='Nunca nos disiparemos, mortal... Nuestro destino está unido a Sanguino...' WHERE `ID`=19444;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='테론 고어핀드의 차디찬 손이 너에게 뻗치지 않기를 기도해라...', `MaleText_loc4`='但愿你没有落入塔隆·血魔冰冷的怀抱……', `MaleText_loc5`='祈禱泰朗·血魔不會向你展開令人恐懼的擁抱...', `MaleText_loc7`='Reza para que el abrazo escalofriante de Teron Sanguino no te alcance...', `FemaleText_loc1`='테론 고어핀드의 차디찬 손이 너에게 뻗치지 않기를 기도해라...', `FemaleText_loc4`='但愿你没有落入塔隆·血魔冰冷的怀抱……', `FemaleText_loc5`='祈禱泰朗·血魔不會向你展開令人恐懼的擁抱...', `FemaleText_loc7`='Reza para que el abrazo escalofriante de Teron Sanguino no te alcance...' WHERE `ID`=19445;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 고향을 침략한 자는 바로 너다. 고어핀드가 우리의 원수를 갚아줄 것이다!', `MaleText_loc4`='你侵略了我的家园。血魔会找你报仇的！', `MaleText_loc5`='你侵入了我們的家園。血魔將為我們報仇!', `MaleText_loc7`='Eres tú quien ha invadido nuestro hogar. ¡Sanguino nos vengará!', `FemaleText_loc1`='우리 고향을 침략한 자는 바로 너다. 고어핀드가 우리의 원수를 갚아줄 것이다!', `FemaleText_loc4`='你侵略了我的家园。血魔会找你报仇的！', `FemaleText_loc5`='你侵入了我們的家園。血魔將為我們報仇!', `FemaleText_loc7`='Eres tú quien ha invadido nuestro hogar. ¡Sanguino nos vengará!' WHERE `ID`=19446;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고어핀드가 널 가만두지 않을 것이다, 침입자여!', `MaleText_loc4`='血魔会取下你的首级，入侵者！', `MaleText_loc5`='血魔將砍掉你的頭，闖入者!', `MaleText_loc7`='¡Sanguino te cortará la cabeza, $ginvasor:invasora;!', `FemaleText_loc1`='고어핀드가 널 가만두지 않을 것이다, 침입자여!', `FemaleText_loc4`='血魔会取下你的首级，入侵者！', `FemaleText_loc5`='血魔將砍掉你的頭，闖入者!', `FemaleText_loc7`='¡Sanguino te cortará la cabeza, $ginvasor:invasora;!' WHERE `ID`=19447;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 이곳에 묶여 있다... 영원히. 그것은 고어핀드의 뜻이다.', `MaleText_loc4`='我们……被永久地束缚在了这里。这是血魔的意志。', `MaleText_loc5`='我們被束縛在這裡...永遠地。這是血魔的意思。', `MaleText_loc7`='Estamos destinados aquí... eternamente. Es la voluntad de Sanguino.', `FemaleText_loc1`='우리는 이곳에 묶여 있다... 영원히. 그것은 고어핀드의 뜻이다.', `FemaleText_loc4`='我们……被永久地束缚在了这里。这是血魔的意志。', `FemaleText_loc5`='我們被束縛在這裡...永遠地。這是血魔的意思。', `FemaleText_loc7`='Estamos destinados aquí... eternamente. Es la voluntad de Sanguino.' WHERE `ID`=19448;
