UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘했다, 제군들! 마지막 놈들이다!', `MaleText_loc4`='干得好，士兵们！这是他们最后的挣扎了！', `MaleText_loc5`='做的好，士兵!這是他們的最後一個!', `MaleText_loc7`='¡Buen trabajo, soldados! ¡Estos son los últimos!' WHERE `ID`=19455;
