UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 땅에 대한 일리단의 지배력이 사라지고 있습니다. 느껴지십니까, $n?', `MaleText_loc4`='伊利丹对这个地方的控制逐渐放松了。你能感觉到吗，$n？', `MaleText_loc5`='伊利丹在這塊土地的控制力正在下滑。你能感覺到嗎，$n?', `MaleText_loc7`='El alcance de Illidan sobre esta tierra se deteriora. ¿Lo notas, $n?' WHERE `ID`=19459;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='라자크 기병대와 함께 일해 보면 명령을 따른다는 것이 무엇인지 배울 수 있어요.$B$B첫 번째, 죽을 때까지 싸워라. 두 번째, 동료가 죽을 때까지 싸우는 모습을 구경해라...', `FemaleText_loc4`='当你和拉沙克驯马师一起逃跑的时候，你会学到这么两件事。$B$B第一件是：战斗，直到死亡；第二件是：参照第一件事。', `FemaleText_loc5`='當你與洛薩克的非正式騎兵一起奔跑時，你會學會一點關於遵守命令的事。$B$B第一件事是作戰至死。第二件事是，看第一件事情。', `FemaleText_loc7`='Cuando corras con los Jinetes Férreos de Razak, aprenderás un par de cosas sobre seguir órdenes.$B$BLo primero es que luchas hasta la muerte. Lo segundo es ver lo primero.' WHERE `ID`=19460;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 비행을 축복하려고 고함을 지릅니다.', `MaleText_loc4`='%s祈求着龙神的祝福。', `MaleText_loc5`='%s大聲呼喊為了龍軍團。', `MaleText_loc7`='%s grita por la bendición del Vuelo.', `FemaleText_loc1`='%s|1이;가; 비행을 축복하려고 고함을 지릅니다.', `FemaleText_loc4`='%s祈求着龙神的祝福。', `FemaleText_loc5`='%s大聲呼喊為了龍軍團。', `FemaleText_loc7`='%s grita por la bendición del Vuelo.' WHERE `ID`=19461;
