UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무기를 손질하지 않겠나? 아니면 새 무기가 필요한가? 나중에 후회하느니 미리 준비하는 게 좋을 텐데...', `MaleText_loc4`='你要磨刀还是要一把新武器？安全第一、安全第一……', `MaleText_loc5`='需要將你的刀身磨利，還是選一種新武器?有備無患...', `MaleText_loc7`='¿Necesitas que te afilen la espada, o quizás un arma nueva? Más vale prevenir que curar...' WHERE `ID`=19463;
