UPDATE `locales_broadcast_text` SET `MaleText_loc1`='망치를 구하려는 분이라면 제대로 찾아오셨군요.', `MaleText_loc4`='要是你想买把锤子，那你可找对地方了。', `MaleText_loc5`='如果你要尋找的是一支鐵錘，那你已經來對地方了。', `MaleText_loc7`='Si buscas un martillo, has venido al lugar apropiado.' WHERE `ID`=19465;
