UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 적의 움직임을 신중히 살피며 전진합니다.', `MaleText_loc4`='%s冲向前去，小心地观察着它的敌人。', `MaleText_loc5`='%s衝向前，仔細地觀察它的敵人。', `MaleText_loc7`='%s avanza apresuradamente, observando atentamente a su enemigo.', `FemaleText_loc1`='%s|1이;가; 적의 움직임을 신중히 살피며 전진합니다.', `FemaleText_loc4`='%s冲向前去，小心的看着它的敌人。', `FemaleText_loc5`='%s衝向前，仔細地觀察它的敵人。', `FemaleText_loc7`='%s avanza apresuradamente, observando atentamente a su enemigo.' WHERE `ID`=19467;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음하하하! 어리석은 놈들! 공간과 시간의 틈새에 유배되어 있었던 나를 풀어주었구나. 덕분에 난 자유다!', `MaleText_loc4`='哈哈哈哈哈！你这个蠢货！你把我从时空之间的缝隙中放了出来，终结了我的流放！', `MaleText_loc5`='哈哈哈哈哈! 你這個蠢蛋!你已經將我從空間和時間的空隙放逐中釋放了!', `MaleText_loc7`='¡Jajajaja! ¡Estúpido! ¡Me has liberado de mi destierro en los intersticios que hay entre el espacio y el tiempo!' WHERE `ID`=19468;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드레노어 전체가 내 발밑에서 떨게 되리라! 난 이 세계를 파괴하고 내가 바라는 대로 다시 창조할 것이다!', `MaleText_loc4`='整个德拉诺都会在我脚下颤抖！我会摧毁这个世界，并以我的喜好来重铸它！', `MaleText_loc5`='整個德拉諾都將在我的腳下震動!我將毀滅這個世界，並且以我的心目中的形象重新塑造它!', `MaleText_loc7`='¡Todo Draenor temblará bajo mis pies! ¡Destruiré este mundo y lo volveré a construir a mi semejanza!' WHERE `ID`=19469;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디부터 시작해야 좋을까? 벌레 같은 네놈들 따위에 신경 쓸 시간이 없다. 나는 이 세계를 정복할 거니까!', `MaleText_loc4`='我要从哪里开始？我不能为你这种蠕虫操心。我要征服世界！', `MaleText_loc5`='我該從那裡開始呢?我不能讓自己為了像你這樣的蟲煩惱。有一個世界需要被征服!', `MaleText_loc7`='¿Por dónde empezaré? No puedo molestarme con un gusano como tú. ¡Hay un mundo que conquistar!' WHERE `ID`=19470;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 추방한 바보들은 벌써 오래전에 죽었을 테지. 용군단을 데려와서 나의 새로운 영토를 조사해야겠다. 네놈이 믿는 신에게 다시는 나와 마주치지 않게 해달라고 기도나 올려라.', `MaleText_loc4`='毫无疑问，那些放逐我的蠢货们早就死了。我要俯瞰我的新领地。向你们的神明祈祷吧，祈祷你们不会再被我看到！', `MaleText_loc5`='那些放逐我的蠢蛋無疑死了很久了。我將飛去調查我的新領地。向任何你尊敬的神祈禱我們不會再見面。', `MaleText_loc7`='Sin duda los estúpidos que me desterraron hace tiempo que murieron. Volaré e investigaré mis nuevos dominios. Reza a los dioses en los que creas para que no volvamos a encontrarnos.' WHERE `ID`=19471;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼애애애......', `MaleText_loc4`='不！……', `MaleText_loc5`='不...', `MaleText_loc7`='NOOOOooooooo...' WHERE `ID`=19472;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 가장 가까운 룬 마법진으로 도망가려고 합니다.', `MaleText_loc4`='%s冲向了最近的符文法阵。', `MaleText_loc5`='%s為最近的符文法陣做了一個缺口。', `MaleText_loc7`='%s intenta escapar al círculo de runas más cercano.', `FemaleText_loc1`='%s|1이;가; 가장 가까운 룬 마법진으로 도망가려고 합니다.', `FemaleText_loc4`='%s冲向了最近的符文法阵。', `FemaleText_loc5`='%s為最近的符文法陣做了一個缺口。', `FemaleText_loc7`='%s intenta escapar al círculo de runas más cercano.' WHERE `ID`=19473;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신에게 거짓말은 하지 않겠습니다. 이곳 주변의 상황이 그리 좋지는 않습니다. 우리는 벌레들의 끊임없는 공격에 시달리고 있습니다. 우리 삶과 자유까지 위협받고 있단 말입니다!$B$B책임감 있는 $r|1으로서;로서; 우리를 도와주지 않겠어요?', `MaleText_loc4`='$G孩子:年轻的女士;，我不准备向你撒谎，这里的事情不是那么如意。我们受到了虫子持续的攻击，我们的生活、我们的自由，都受到了威胁！$B$B你愿意尽一位好公民的责任来帮助我们吗？', `MaleText_loc5`='$G年輕人:年輕的女士;，我不打算騙你;這裡的情況並不樂觀。我們不斷被蟲子襲擊，而我們的生命，我們的自由，都在危急關頭!$B$B你會成為一位負責任的居民並且幫助我們嗎?', `MaleText_loc7`='$g Hijo : Jovencita;, no voy a mentirte, las cosas no van bien por aquí. ¡Estamos bajo ataques constantes de los bichos y nuestra misma forma de vida, nuestra libertad, está en juego!$B$B¿Vas a comportarte de forma responsable y ayudar?' WHERE `ID`=19474;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칠흑으로 덮인 밤이 찾아오면 다시 한 번 까마귀가 어둠 속으로 날아올라 본성을 드러낼 것이다. 그때를 대비하라. 충성을 바치면 까마귀와 함께 비상할 것이고, 그렇지 못한 자들은 날개가 잘려 잊혀진 채 비참하게 땅을 걷게 되리라.', `MaleText_loc4`='在最黑暗的夜晚，乌鸦将再次飞起，它将飞入阴影，显露本性。当它到来之时，虔诚的信徒会随它一并飞翔，剩余的人将被遗忘在大地之上，夹着翅膀羞愧不已。', `MaleText_loc5`='烏鴉從最黑暗的夜晚中將再次升起，在暗影裡飛翔，顯示它自然的天性。為它的來臨做好準備，忠實的人將與烏鴉一起飛翔，其餘的人被遺忘，走在大地，折翼和羞恥之中。', `MaleText_loc7`='De la noche más oscura se volverá a elevar el Cuervo, emprenderá el vuelo en las sombras, revelará la naturaleza de su especie. Prepárate para su llegada, pues los fieles se elevarán para emprender el vuelo con el Cuervo, y el resto será olvidado, y deberá caminar sobre el suelo, con alas cortadas y vergüenza.' WHERE `ID`=19475;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마음 굳게 먹고 정신 차려라. 땅에서 발을 뗄 수 없는 노예가 된 이들의 약한 마음을 어둠의 날개들이 교란하여 갉아먹을 것이니라.', `MaleText_loc4`='坚定你的信念，捍卫你的想法。黑暗之翼会淹没与吞噬弱者的信念。他们的双脚将永远无法离开大地高飞。', `MaleText_loc5`='強化你的心智並保衛你的想法。黑色的翅膀將籠罩並且消耗弱者的心智，一群腳離不開地面的奴隸。', `MaleText_loc7`='Armen la mente y protejan sus pensamientos. Las alas oscuras ensombrecerán y consumirán la mente de los débiles, un rebaño de esclavos cuyos pies quizás nunca abandonen el suelo.' WHERE `ID`=19476;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='까마귀가 찾아오고 하늘에 어둠이 깃들면 오래된 피가 다시 한 번 흘러내릴지니. 붉은 밤이 찾아오면 과거가 깨어나리라.', `MaleText_loc4`='古神的血液会因为乌鸦的到来而再度流淌，黑暗将在天际重现。猩红的夜晚，古神将会复生。', `MaleText_loc5`='隨著烏鴉的來臨，古老的血液將再次流動，黑暗返回天空。深紅的夜晚和古老的興起。', `MaleText_loc7`='La antigua sangre fluirá una vez más con la llegada del Cuervo, la vuelta de la oscuridad a los cielos. Noche escarlata y el surgimiento de lo antiguo.' WHERE `ID`=19477;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='까마귀는 준비가 덜 된 상태로 너무 높이 날다가 다시 떨어졌다. 비상할 때를 위해 영겁의 시간은 암흑의 감시자를 준비했다. 지평선 너머 어둠의 망토를 드리우고자...', `MaleText_loc4`='乌鸦曾因贸然飞得太高而被击落。黑暗守望者为了他的飞翔准备了亿万年，就是为了在地平线上拉起黑暗的斗篷。', `MaleText_loc5`='烏鴉曾因飛得太高被打下一次，沒有準備好。萬古已為它的登高準備好黑暗看守者，以便讓黑暗披風跨過地平線。', `MaleText_loc7`='El Cuervo fue abatido una vez por volar demasiado alto, desprevenido. Los eones han preparado al Vigía Oscuro para su ascenso, para que trace la capa oscura en el horizonte.' WHERE `ID`=19478;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 달콤한 속삭임이로군.', `MaleText_loc4`='这是个特别的传闻。', `MaleText_loc5`='這是一句逗趣的密語。', `MaleText_loc7`='Esto es un rumor del momento.' WHERE `ID`=19479;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='테론 고어핀드라고? 그래... 그를 알지.', `MaleText_loc4`='塔隆·血魔？没错……我认识他。', `MaleText_loc5`='泰朗·血魔嗎?是的...我知道他。', `MaleText_loc7`='¿Teron Sanguino? Sí... he oído hablar de él.' WHERE `ID`=19480;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모든 시스템이 연결되었습니다. 준비하십시오. 곧 떠나겠습니다.', `MaleText_loc4`='所有设备已经开启，准备好，我们很快就要离开了。', `MaleText_loc5`='全部系統上線。準備好，我們不久後離開。', `MaleText_loc7`='Todos los sistemas en línea. Prepárate, nos marchamos en breve.' WHERE `ID`=19481;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스케티스 바람술사가 향기로운 풀 한 더미를 불 속에 던져 넣습니다.', `MaleText_loc4`='The Skettis Windwalker throws a bundle of fragrant herbs into the fire. [PH]', `MaleText_loc5`='司凱堤斯風行者把一捆芳香藥草投入火裡。[PH]', `MaleText_loc7`='El surcavientos de Skettis lanza un paquete de hierbas aromáticas al fuego.' WHERE `ID`=19482;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 훌륭하군요! 대단합니다! 굉장한 공연이에요!', `MaleText_loc4`='太精彩了！精彩绝伦！多华丽的演出啊！', `MaleText_loc5`='太燦爛了!太驚人了!真是一個極佳的表演!', `MaleText_loc7`='¡Espléndido! ¡Maravilloso! ¡Una actuación excelente!' WHERE `ID`=19483;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='작업에 착수합니다.', `MaleText_loc4`='出发。', `MaleText_loc5`='繼續。', `MaleText_loc7`='Procede.' WHERE `ID`=19484;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저건 뭐지?', `MaleText_loc4`='那是什么？', `MaleText_loc5`='那是什麼?', `MaleText_loc7`='¿Qué es eso?' WHERE `ID`=19485;
