UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저런 건 처음 봐.', `MaleText_loc4`='我从没见过。', `MaleText_loc5`='我以前從沒看過。', `MaleText_loc7`='Mi no ver eso antes.' WHERE `ID`=19487;
