UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저것 봐... 반짝이는 공이다!', `MaleText_loc4`='看……发亮的球！', `MaleText_loc5`='注意...聖光球!', `MaleText_loc7`='Cuidado... ¡bola de luz!' WHERE `ID`=19490;
