UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저거 갖고 싶어!', `MaleText_loc4`='我想要光明！', `MaleText_loc5`='我需要光線!', `MaleText_loc7`='¡Mi querer luz!' WHERE `ID`=19492;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어렸을 때 난 사제회의 수도자가 되려고 열심히 훈련을 받았소. 사실 여성 총독은 전례가 없는 일이었지.$B$B요즘은 성별이 거의 문제가 되지 않지만. 용기와 확신이야말로 모든 차이를 만드는 근원이라오.', `FemaleText_loc4`='我年轻的时候刻苦训练，是为了成为牧师中的学者。那时候我从没听说过还有女性主教。$B$B现在性别已经不是问题了——那是因为勇气和信仰会改变一切。', `FemaleText_loc5`='我年輕時努力接受訓練以成為一個在教士中的隱士。那時從沒聽過有女性主教。$B$B現在性別不太重要 - 勇氣和信念才是重點。', `FemaleText_loc7`='Cuando era joven me formé con dureza para convertirme en una anacoreta en el sacerdocio. Prácticamente no se había oído de las exarcas femeninas.$B$BHoy en día, el sexo importa poco – es su coraje y convicción lo que marca la diferencia.' WHERE `ID`=19493;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하하, 네 육체는 내 것이다! 우리 운명은 이제 영원히 얽혀 있다.', `MaleText_loc4`='你的躯体为我所有！我们的命运将永远纠缠在一起！', `MaleText_loc5`='你的身體是我的!我們的命運將永遠糾纏。', `MaleText_loc7`='¡Tu cuerpo es mío! Nuestros destinos están entrelazados para siempre.' WHERE `ID`=19494;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다른 장난감을 데려오란 말이야!', `FemaleText_loc4`='给我再弄一个玩具过来！', `FemaleText_loc5`='幫我帶另一個玩具來!', `FemaleText_loc7`='¡Traedme otro juguete!' WHERE `ID`=19495;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='한 놈 더! 다른 놈을 데려오란 말이다!', `FemaleText_loc4`='再来一个！给我再带一个过来！', `FemaleText_loc5`='另一個!幫我帶另一個來!', `FemaleText_loc7`='¡Otro! ¡Traedme otro!' WHERE `ID`=19496;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너 마법 시전 못한다!', `MaleText_loc4`='你别想施放法术！', `MaleText_loc5`='你不能施展法術!', `MaleText_loc7`='¡Tú no lanzar hechizos!' WHERE `ID`=19497;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원래 시간대로 돌아갈 준비가 되셨다면, 제가 그대를 순간이동시켜 드리겠습니다.', `MaleText_loc4`='如果你准备好了，并且希望能尽快回到正常的时间流，我可以把你传送回去。', `MaleText_loc5`='如果你已準備好，並且希望迅速返回正常的時間流，我能傳送你。', `MaleText_loc7`='Si estás $gpreparado:preparada; y deseas volver rápidamente a la corriente normal del tiempo, puedo transportarte.' WHERE `ID`=19498;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원래 시간으로 보내 주십시오.', `MaleText_loc4`='请让我返回我的时间流。', `MaleText_loc5`='把我帶回我的時代。', `MaleText_loc7`='Devuélveme a mi tiempo.', `FemaleText_loc1`='원래 시간으로 보내 주십시오.', `FemaleText_loc4`='请让我返回我的时间流。', `FemaleText_loc5`='把我帶回我的時代。', `FemaleText_loc7`='Devuélveme a mi tiempo.' WHERE `ID`=19499;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간의 흐름을 바꾸는 일은 매우 까다롭고 섬세한 작업이지만 오늘 그대는 훌륭하게 해내셨습니다.', `MaleText_loc4`='修正流动的时间是非常困难和精细的工作，但是你今天表现得很完美。', `MaleText_loc5`='形成時間流是一項非常艱難精細的任務，但是你今天表現的非常令人欽佩。', `MaleText_loc7`='Dar forma al flujo del tiempo es una tarea muy difícil y bastante delicada, pero hoy has realizado una actuación admirable.' WHERE `ID`=19500;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼... 안 돼! 무슨 짓이냐? 내가 주인이야! 내 말 듣지 못해? 나란 말이야! 내가... 으아악! 놈을 억누를 수... 없...어.', `MaleText_loc4`='不……不！你在干什么？我才是主宰！你听到没有？我……啊啊啊啊！控制……不住了。', `MaleText_loc5`='不...不!你做了什麼?我是主人!你沒聽見我在說話嗎?我....啊!無法...控制它。', `MaleText_loc7`='¡No... no! ¿Qué hiciste? ¡Yo soy el amo! ¿Me escuchas? ¡Yo... ahggg! No...puedo contenerlo.' WHERE `ID`=19501;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 해방이구나. 진정한 자유를 맛보는 게 대체 얼마 만인가!', `MaleText_loc4`='我终于解放了。很久都没有感受到真正的自由了！', `MaleText_loc5`='我終於被解放了。我已經很久沒有獲得真正的自由了!', `MaleText_loc7`='Al fin soy libre. ¡Hacía mucho que no disfrutaba la verdadera libertad!' WHERE `ID`=19502;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꾸물거릴 시간이 없다, 멍청아! 우리 길을 막고 있는 저 녀석들을 해치워라! 겁먹지 말고 카르시우스를 없애버리란 말이다!', `MaleText_loc4`='不要浪费时间，蠢货！用我们的力量来消灭那些挡路的家伙！在你被抑制之前消灭卡修斯！', `MaleText_loc5`='不要浪費時間了，傻瓜!用我們的力量殺死那些阻礙我們的東西!在你被制服之前，毀掉卡西亞斯!', `MaleText_loc7`='¡No pierdas el tiempo, estúpido! ¡Usa nuestro poder para matar a aquellos que se interpongan en nuestro camino! ¡Destruye a Karsius antes de que te dominen!' WHERE `ID`=19503;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달아나려는 모습이 보기 애처롭지만 곧 실패할 것이다, 고어핀드. 그 젊은 친구를 보내고 항복해라! 네 갑옷과 무기가 아무리 좋아도 고대정령을 이길 수는 없다!', `MaleText_loc4`='血魔，你最好打消逃跑的念头。离开这个$G小伙子:姑娘;的躯体，投降吧！即便你全力以赴，也是不可能逃走的！', `MaleText_loc5`='你想逃走的可悲企圖將很短暫，血魔。讓$g男孩:女孩;走並屈服!即使用你的盔甲和武器，你也不能戰勝長者!', `MaleText_loc7`='Tu patético intento de escapar será efímero, Sanguino. Deja que $gel chico:la chica; se marche y sométete! ¡Ni siquiera con tu armadura y tus armas puedes vencer a los ancestros!' WHERE `ID`=19504;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 땅을 노리는 자들에게 한 수 가르쳐 주자!', `MaleText_loc4`='给这些想危害我们世界的家伙好好上一课吧！', `MaleText_loc5`='讓這教訓一下那些會對我們土地做出邪惡事情的人!', `MaleText_loc7`='¡Que esto sea una lección para los que fueran a hacer el mal a nuestras tierras!' WHERE `ID`=19505;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨... 짓을 한 건가...', `MaleText_loc4`='你……做了些什么……', `MaleText_loc5`='你...做了些什麼...', `MaleText_loc7`='Qué... has hecho...' WHERE `ID`=19506;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그동안 고마웠다, 이제 네놈은 쓸모가 없으니 가도 좋아.', `MaleText_loc4`='很好。当我不再利用你的躯体时，你就自由了。', `MaleText_loc5`='做得好，小卒。你可以自由離去，因為我不再需要你的身體了。', `MaleText_loc7`='Bien hecho, peón. Eres libre de irte, pues ya no necesito tu cuerpo.' WHERE `ID`=19507;
