UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 죽음의 화신이 다시 한 번 세상에 나타났다! 나 테론 고어핀드가 돌아왔느니...', `MaleText_loc4`='死亡的化身再度降临这个世界！塔隆·血魔回来了……', `MaleText_loc5`='死亡化身已經再一次被釋放在這世界!泰朗·血魔已經回來了...', `MaleText_loc7`='¡La encarnación de la muerte ha sido liberada una vez más sobre el mundo! Teron Sanguino ha vuelto...' WHERE `ID`=19509;
