UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어라? 이젠 저 책 이름이 기억이 안 나네? 그래, 맞아. 아니야, 그건 아닌데...', `MaleText_loc4`='那本书的名字是什么？哦对了，是——不，不，不是那个……', `MaleText_loc5`='那本書的名字是什麼?喔對，它是--不，不，那不是...', `MaleText_loc7`='Bueno, ¿cuál era el título de ese libro? Ah, sí, era – no, no, ese no era...' WHERE `ID`=19543;
