UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안토니다스가 이 오크들과 그들의 ''무기력증''에 대해 흥미로운 견해를 밝히더군.', `MaleText_loc4`='安东尼达斯对于这些兽人和他们的“呆板”有着有趣的见解。', `MaleText_loc5`='安東尼達斯有一些關於這些獸人和他們「昏睡」的有趣想法。', `MaleText_loc7`='Antonidas tiene algunas ideas interesantes sobre esos orcos y su "letargo".' WHERE `ID`=19545;
