UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에이... 그러지 마십시오. 무슨 거래가 이렇습니까? 와서 직접 보시라니까요!', `MaleText_loc4`='三分叫卖七分货啊。都来看看吧！', `MaleText_loc5`='這種便宜買賣不是我在說。自己來看!', `MaleText_loc7`='No me escuches cuando digo que es una ganga. ¡Ven a comprobarlo!' WHERE `ID`=19559;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='블랙무어가 이상한 행동을 한다고 들었습니다.', `MaleText_loc4`='我听说布莱克摩尔最近行为很古怪。', `MaleText_loc5`='我聽說布拉克摩爾最近舉止很奇怪。', `MaleText_loc7`='He oído que Lodonegro ha estado actuando de una forma extraña.', `FemaleText_loc1`='블랙무어가 이상한 행동을 한다고 들었습니다.', `FemaleText_loc4`='我听说布莱克摩尔最近行为很古怪。', `FemaleText_loc5`='我聽說布拉克摩爾最近舉止很奇怪。', `FemaleText_loc7`='He oído que Lodonegro ha estado actuando de una forma extraña.' WHERE `ID`=19560;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 휴가를 어디로 갈지 생각하고 있는데요... 하스글렌이 좋다던데...', `MaleText_loc4`='我正在考虑去度假，听说壁炉谷不错。', `MaleText_loc5`='我正在考慮一個假期。我聽說壁爐谷不錯。', `MaleText_loc7`='Estoy pensando en tomarme unas vacaciones. He oído que la Vega del Amparo es bonita.', `FemaleText_loc1`='아, 휴가를 어디로 갈지 생각하고 있는데요... 하스글렌이 좋다던데...', `FemaleText_loc4`='我正在考虑去度假，听说壁炉谷不错。', `FemaleText_loc5`='我正在考慮一個假期。我聽說壁爐谷不錯。', `FemaleText_loc7`='Estoy pensando en tomarme unas vacaciones. He oído que la Vega del Amparo es bonita.' WHERE `ID`=19561;
