UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일리단의 개들아! 나를 구속한 대가로 너희의 목숨을 받겠다!', `MaleText_loc4`='伊利丹的走狗们！你们会因为囚禁我而付出生命的代价！', `MaleText_loc5`='伊利丹的走狗!你們將為了監禁我而付出生命的代價!', `MaleText_loc7`='¡Perros falderos de Illidan! ¡Pagarán mi encarcelamiento con su vida!' WHERE `ID`=19577;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='감히 내게 덤비는 게냐? 나는 일리단 님에게 직접 훈련을 받은 몸이시다!', `FemaleText_loc4`='你胆敢挑战我？我是伊利丹大人亲手训练出来的！', `FemaleText_loc5`='你竟敢跟我作戰?我是伊利丹親自訓練出來的!', `FemaleText_loc7`='¿Osas luchar conmigo? ¡Me instruyó el mismo Illidan!' WHERE `ID`=19578;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정한 힘이 뭔지 알게 되리라!', `MaleText_loc4`='让你见识见识真正的力量！', `MaleText_loc5`='你將見識到真正的力量!', `MaleText_loc7`='¡Presenciarás poder de verdad!' WHERE `ID`=19579;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제발 어서 죽여달라고 구걸하리라!', `MaleText_loc4`='很快你就会乞求速死的！', `MaleText_loc5`='你很快就會祈求速死!', `MaleText_loc7`='¡Pronto rezarás para tener una muerte rápida!' WHERE `ID`=19580;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭔가 잘못된 것 같군요...', `MaleText_loc4`='这感觉完全不对……', `MaleText_loc5`='這個看起來不太對...', `MaleText_loc7`='Esto no tiene buen aspecto...' WHERE `ID`=19581;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='금속의 마법적 속성이 사라졌군요! 작업을 할 수는 있지만 일반적인 방법으로는 안 되겠습니다.', `MaleText_loc4`='金属的魔法属性消失了！它还能用，但是不能用寻常的方法来锻造了。', `MaleText_loc5`='金屬的魔法特性消失了!它仍然能用，但不是以普通的鍛造方法。', `MaleText_loc7`='¡Las propiedades mágicas del metal han desaparecido! Todavía se puede trabajar, pero no con métodos convencionales de herrería.' WHERE `ID`=19582;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 내 성소에 침입하다니? 짜릿한 고통을 약속하마!', `MaleText_loc4`='你胆敢闯入我的圣地？我要让你堕入痛苦的深渊！', `MaleText_loc5`='你膽敢闖入我的聖所?我要讓你進入痛苦的世界!', `MaleText_loc7`='¿Osas importunarme en mi sagrario? ¡Te prometo un mundo de dolor!' WHERE `ID`=19583;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 이건 아니잖아... 도대체 이게 무슨 일이지?', `MaleText_loc4`='不，不是这样的。这里发生了什么事？', `MaleText_loc5`='不，這不對。這裡發生了什麼事?', `MaleText_loc7`='No, esto no está bien. ¿Qué ha pasado aquí?' WHERE `ID`=19584;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='금속에서 마력이 사라졌네. 그래도 무기를 만들 수는 있지만 평범한 검과 다를 게 없을 거야.', `MaleText_loc4`='金属失去了自身的魔法。我倒是能用它来打造武器，但是它和一口普通的宝剑没什么区别。', `MaleText_loc5`='金屬已經失去它的魔法。我能用它製造一種武器，但是這將不會與世俗刀劍有什麼不同。', `MaleText_loc7`='El metal ha perdido su magia. Podría hacer un arma con él, pero no sería diferente de una espada convencional.' WHERE `ID`=19585;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로서의 후예들 중 한 명을 데려갈 수는 있지만 그에게서 로서의 후예들을 뺏어갈 수는 없소.$B$B<어깨를 으쓱하는 대장장이>$B$B설명하기는 어렵지만 내가 지금 명예의 요새에 있어서는 안 될 것 같다오.$B$B좀 더 큰 곳으로 가야 할 것 같군.', `MaleText_loc4`='你可以让一个人脱离洛萨之子组织，但你不能从他心中抹去这个身份的意义。$B$B<工匠耸了耸肩。>$B$B这很难解释，但是我觉得我不应该呆在荣耀堡。$B$B或许我应该成就一番伟业。', `MaleText_loc5`='你能從洛薩之子中帶走一個人，但是你不能從他那裡帶走那些兒子。$B$B<鐵匠聳聳肩。>$B$B很難解釋，但我不覺得我現在應該在榮譽堡。$B$B也許我應該屬於某個更偉大的地方。', `MaleText_loc7`='Puedes alejar a un hombre de los hijos de Lothar, pero no puedes sacarle a los hijos de su interior.$B$B<El herrero se encoge de hombros.>$B$BEs difícil de explicar, pero no siento que deba estar en el Bastión del Honor ahora mismo, eso es todo.$B$BQuizás esté destinado a formar parte de algo más grande.' WHERE `ID`=19586;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='갈기갈기 찢어버리겠다, 이 악마야!', `FemaleText_loc4`='我要把你撕成碎片，恶魔！', `FemaleText_loc5`='我會把你碎屍萬段，惡魔!', `FemaleText_loc7`='¡Te despedazaré, demonio!' WHERE `ID`=19587;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 훌륭한 요리사, 뭄만이 도시의 정문 근처 여관 바로 옆에 소박한 상점을 차렸습니다.', `MaleText_loc4`='穆曼的小店就在城市主入口附近，就是刚过旅店的那家美食店。', `MaleText_loc5`='慕曼已經在城市的主要入口附近開了她簡陋的商店，就在旅店再過去的地方。絕妙小廚，那一間。', `MaleText_loc7`='Mumman ha establecido su humilde tienda cerca de la entrada principal de la ciudad, justo después de pasar por la posada. Es un cocinero excelente.', `FemaleText_loc1`='우리의 훌륭한 요리사, 뭄만이 도시의 정문 근처 여관 바로 옆에 소박한 상점을 차렸습니다.', `FemaleText_loc4`='穆曼的小店就在城市主入口附近，就是刚过旅店的那家美食店。', `FemaleText_loc5`='慕曼已經在城市的主要入口附近開了她簡陋的商店，就在旅店再過去的地方。絕妙小廚，那一間。', `FemaleText_loc7`='Mumman ha establecido su humilde tienda cerca de la entrada principal de la ciudad, justo después de pasar por la posada. Es un cocinero excelente.' WHERE `ID`=19588;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마나 베틀', `MaleText_loc4`='魔法织布机', `MaleText_loc5`='法力織布機', `MaleText_loc7`='Telar de maná', `FemaleText_loc1`='마나 베틀', `FemaleText_loc4`='魔法织布机', `FemaleText_loc5`='法力織布機', `FemaleText_loc7`='Telar de maná' WHERE `ID`=19589;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시장의 북서쪽 모퉁이에 있는 킬렌 시츠의 의류점에 가면 그대가 찾는 것과 비슷한 베틀이 있소이다.', `MaleText_loc4`='位于花园街市西北角的基伦裁缝店里有你说的那种织布机。', `MaleText_loc5`='奇蘭在商店街西北角的裁縫店有一部像你描述的織布機。', `MaleText_loc7`='La sastrería de Keelen, en la esquina noroeste del Bazar, tiene un telar como el que describes.', `FemaleText_loc1`='시장의 북서쪽 모퉁이에 있는 킬렌 시츠의 의류점에 가면 그대가 찾는 것과 비슷한 베틀이 있소이다.', `FemaleText_loc4`='位于花园街市西北角的基伦裁缝店里有你说的那种织布机。', `FemaleText_loc5`='奇蘭在商店街西北角的裁縫店有一部像你描述的織布機。', `FemaleText_loc7`='La sastrería de Keelen, en la esquina noroeste del Bazar, tiene un telar como el que describes.' WHERE `ID`=19590;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고난의 거리에 있는 상인의 시장으로 가면 마나 베틀을 찾을 수 있을 겁니다.', `MaleText_loc4`='你可以在贫民窟的集市里找到我们的魔法织布机。', `MaleText_loc5`='你能在陰鬱城的商店街裡找到我們的法力織布機。', `MaleText_loc7`='Puedes encontrar nuestro telar de maná en el bazar de los mercaderes, dentro del Bajo Arrabal.', `FemaleText_loc1`='고난의 거리에 있는 상인의 시장으로 가면 마나 베틀을 찾을 수 있을 겁니다.', `FemaleText_loc4`='你可以在贫民窟的集市里找到我们的魔法织布机。', `FemaleText_loc5`='你能在陰鬱城的商店街裡找到我們的法力織布機。', `FemaleText_loc7`='Puedes encontrar nuestro telar de maná en el bazar de los mercaderes, dentro del Bajo Arrabal.' WHERE `ID`=19591;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 열심히 일해라!', `MaleText_loc4`='努力点工作！', `MaleText_loc5`='努力工作!', `MaleText_loc7`='¡Trabaja más duro!' WHERE `ID`=19592;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌을 캐라! 바위를 부셔! 더 빨리! 더 빨리!', `MaleText_loc4`='快挖！快采！快一点！', `MaleText_loc5`='開採岩石!爆裂石塊!快點!快點!', `MaleText_loc7`='¡Mina! ¡Pica la piedra! ¡Más rápido! ¡Más rápido!' WHERE `ID`=19593;
