UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꺼져라, 엘프 꼬맹이. 지금부터는 내가 주인이다!', `MaleText_loc4`='滚开吧，脆弱的精灵。现在我说了算！', `MaleText_loc5`='消失吧，微不足道的精靈。現在開始由我掌管!', `MaleText_loc7`='¡Desaparece, elfo insignificante. ¡Yo mando ahora!' WHERE `ID`=19595;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어, 내가 풀려났도다!', `MaleText_loc4`='我的放逐终于结束了！', `MaleText_loc5`='終於結束了我的流放生涯!', `MaleText_loc7`='¡Al fin acaba mi destierro!' WHERE `ID`=19596;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누구나 마음속에 악마를 품고 살지...', `MaleText_loc4`='我们内心都有一只恶魔……', `MaleText_loc5`='我們所有人都有屬於自己的惡魔...', `MaleText_loc7`='Todos tenemos nuestros demonios...' WHERE `ID`=19597;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 분노를 느껴봐라, 쓰레기 같은 $r 놈아! 절대 피할 수 없으리라!', `FemaleText_loc4`='感受我的愤怒吧，肮脏的$r！你逃不掉的！', `FemaleText_loc5`='感受我的憤怒吧，$r殘渣!你逃不過的!', `FemaleText_loc7`='¡Siente mi ira, $r despreciable! ¡No te saldrás con la tuya!' WHERE `ID`=19598;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 곤히 잠든 나를 깨웠느냐? 그 창은... 내 몸에 아직도 그 흉터가 남아 있다!', `MaleText_loc4`='是谁打扰了我的睡眠？那把矛……那道伤疤还刻在我的身上！', `MaleText_loc5`='誰擾亂我的睡眠?那支矛...我仍然帶著它的傷痕!', `MaleText_loc7`='¿Quién perturba mi sueño? Esa lanza... ¡todavía luzco la cicatriz!' WHERE `ID`=19599;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<비전 수호병이 당신의 설명을 조용히 기다립니다.>', `MaleText_loc4`='<奥术守护者静静地等着你的进一步描述。>', `MaleText_loc5`='<秘法守護者安靜地等待你進一步的製作。>', `MaleText_loc7`='<El guardián Arcano espera en silencio que te expliques con más detalle.>' WHERE `ID`=19600;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 일을 시작하기 전에 악마어 사전을 몇 장 읽습니다.', `MaleText_loc4`='%s在开始工作之前，翻看了几页魔语辞典。', `MaleText_loc5`='%s在開始工作之前，讀了幾頁的惡魔詞典。', `MaleText_loc7`='%s lee varias páginas del Lexicón demoníaco antes de comenzar su trabajo.' WHERE `ID`=19602;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 검에 가장 강력한 악마도 쓰러뜨릴 수 있는 힘을 불어넣었소! 그 어떤 악마도 이 검을 휘두르는 자를 감당하지 못할 것이오!', `MaleText_loc4`='我将足以击杀最强大恶魔的力量注入这把利刃之中！此刀一出，恶魔立扑！', `MaleText_loc5`='在這把劍裡，我注入了擊倒最強大的惡魔所需的力量!沒有任何惡魔可以贏過這種武器的揮舞者!', `MaleText_loc7`='¡Atribuyo a esta espada el poder de abatir al más fuerte de los demonios! ¡Ningún demonio podrá enfrentarse al portador de esta arma!' WHERE `ID`=19603;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악마를 막는 마법이 활활 타오르고 무기에 그 힘이 스며듭니다.', `MaleText_loc4`='光华夺目的反恶魔能量被注入到了武器之中。', `MaleText_loc5`='抗惡魔的魔法對生命閃光，並且浸透武器。', `MaleText_loc7`='La magia antidemoníaca se enciende e imbuye el arma.' WHERE `ID`=19604;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음보다 못한 운명에서 저희를 구해 주셔서 감사합니다, $n. 평생 잊지 못할 은혜를 입었군요.', `MaleText_loc4`='$n，谢谢你将我们从生不如死的惨境中解救出来。你的恩情我们永世不忘。', `MaleText_loc5`='$n，謝謝你把我們從比死更糟的命運中救出來。我們永遠感激你。', `MaleText_loc7`='Gracias, $n, por salvarnos de un destino peor que la muerte. Tienes nuestra gratitud eterna.', `FemaleText_loc1`='죽음보다 못한 운명에서 저희를 구해 주셔서 감사합니다, $n. 평생 잊지 못할 은혜를 입었군요.', `FemaleText_loc4`='$n，谢谢你将我们从生不如死的惨境中解救出来。你的恩情我们永世不忘。', `FemaleText_loc5`='$n，謝謝你把我們從比死更糟的命運中救出來。我們永遠感激你。', `FemaleText_loc7`='Gracias, $n, por salvarnos de un destino peor que la muerte. Tienes nuestra gratitud eterna.' WHERE `ID`=19605;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으아아, 독이...', `MaleText_loc4`='啊……毒性侵袭了我……', `MaleText_loc5`='啊，毒...', `MaleText_loc7`='Aagh, el veneno...' WHERE `ID`=19606;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 기분이 훨씬 좋군.', `MaleText_loc4`='感觉好多了。', `MaleText_loc5`='很好，舒服多了。', `MaleText_loc7`='Mejor, mucho mejor.' WHERE `ID`=19607;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='치유사여, 원하는 게 무엇이오?', `MaleText_loc4`='你想从我这里得到什么，萨满祭司？', `MaleText_loc5`='你想要從我這裡得到什麼，薩滿?', `MaleText_loc7`='¿Qué es lo que quieres de mí, chamán?' WHERE `ID`=19608;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='눈은 장식품으로 달고 다니나? 바로 우리 코앞에 악마가 있는 게 안 보이시오? 여유 병력이 없소!', `MaleText_loc4`='你瞎了吗？你没看见恶魔已经打到家门口了吗？我没有人手给你！', `MaleText_loc5`='你沒長眼睛嗎?你沒看見惡魔就在我們的門階上嗎?我沒有多餘的士兵可差遣!', `MaleText_loc7`='¿Acaso no tienes ojos? ¿No has visto a los demonios en nuestro mismo umbral? ¡No puedo prescindir de ningún soldado!' WHERE `ID`=19609;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 믿는 신에게 기도나 올리시오. 아마도 도와주러 올 거요. 하지만, 호드는 갈 수 없소...', `MaleText_loc4`='向你的神祈祷吧，萨满祭司。也许他们会来帮助你的。然而部落是不可能……', `MaleText_loc5`='向你的神祇祈禱吧，薩滿。或許他們會來幫助你。不過，部落不能...', `MaleText_loc7`='Reza a tus dioses, chamán. Quizás vengan en tu ayuda. Sin embargo, la Horda no puede...' WHERE `ID`=19610;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이보시오, 내가 전에 말했잖소... 우린 도와줄 수가 없다고 수백 번 말했지 않았소?!', `MaleText_loc4`='看，我都跟你说过几万次了，我再告诉你一次：我们帮不了你！', `MaleText_loc5`='聽好，如果我告訴過你一次，就等於我已經告訴過你了一百次︰我們不能幫助你!', `MaleText_loc7`='Mira, si te lo he dicho una vez, te lo he dicho cien: ¡NO PODEMOS AYUDARTE!' WHERE `ID`=19611;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이해할 수가 없군! 당신 눈이 멀기라도 했나? 저 밖에 악마들이 우리 문을 두드리며 쳐들어오려는 게 보이지 않나 보지? 누굴 보내서 당신의 주술사 친구들을 도우라는 거요? 골라보시오!', `MaleText_loc4`='我不明白！你瞎了吗？你没看到恶魔们正在攻击我们的大门吗？我能派谁出去和你的萨满朋友谈话？告诉我！', `MaleText_loc5`='我不懂!你瞎了嗎?你沒看到惡魔就挨在我們的門上嗎?我要派誰去和你的薩滿朋友交談?你說說看!', `MaleText_loc7`='¡No lo pillo! ¿Es que no ves lo que ocurre? ¿No ves los demonios que golpean nuestra puerta? ¿A quién voy a enviar para hablar con tus amigos chamanes? ¡Señálalos!' WHERE `ID`=19612;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정으로 당신을 도와주고 싶지만 그럴 수가 없단 말이오! 쿠르드란 님께서 직접 지시를 내리셨소. 그러니 이제 가보시오!', `MaleText_loc4`='我真的希望我能帮你，但是我不能！库德兰已经给我下达了直接命令。自求多福吧！', `MaleText_loc5`='我真的希望我能幫助你，但是我不能!庫德蘭給了我直接的命令。現在向前走!', `MaleText_loc7`='¡Realmente desearía poder ayudarte, pero no puedo! Kurdran me ha dado órdenes directas. ¡Ahora circula!' WHERE `ID`=19613;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 책은 나에게 모든 적을 능가하는 무한한 힘을 줄 것이다... 난... 무적이 될 거야!', `MaleText_loc4`='这本书将赐予我无尽的力量……我会变得……无坚不摧！', `MaleText_loc5`='這本書會給我超越敵人的無限力量...我會變得...所向披靡!', `MaleText_loc7`='Este libro me daría poder ilimitado sobre mis enemigos... sería... ¡imparable!' WHERE `ID`=19614;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼... $n, 이걸 가져가게! 어둠의 힘이 벌써 내 의지력을 쥐고 흔드는 것이 느껴져! 책을 이용해 베레디스를 해치우게.', `MaleText_loc4`='不……你必须把这东西从我这里拿走，$n！我感觉到它的黑暗力量已经开始动摇我的意志了！用它来消灭瓦雷迪斯吧。', `MaleText_loc5`='不...你必須把它從我這裡拿走，$n!我感覺它的黑暗力量動搖我的意志!用它來摧毀瓦瑞迪斯。', `MaleText_loc7`='No... ¡Debes quedarte esto, $n! ¡Siento cómo su oscuro poder ya domina mi voluntad! Úsalo para destruir a Varedis.' WHERE `ID`=19615;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"게임을 끝낸 지 얼마 되지 않았기 때문에 아직은 제어할 수 없습니다."', `MaleText_loc4`='“因为你刚才离开过棋局，所以你暂时还不能控制我。”', `MaleText_loc5`='「你要控制我還太早了，因為你最近已經離開比賽了 」。', `MaleText_loc7`='"Es demasiado pronto para que me controles, pues has dejado el juego recientemente."' WHERE `ID`=19616;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 전당을 통과하려면 고도의 기술을 요하는 게임에서 날 이겨야 한다! 시작할 준비가 되면 왕을 움직여라...', `MaleText_loc4`='想穿越我的大厅，你就必须用你的精湛棋艺来击败我！当你准备好了之后，就去控制你的国王……', `MaleText_loc5`='要通過我的大廳，你必須在一場競技比賽中戰勝我!當你準備開始時，控制你的國王...', `MaleText_loc7`='¡Para cruzar mi sala, debes vencerme en un juego de habilidad! Controla a tu rey cuando estés $gpreparado:preparada; para comenzar...' WHERE `ID`=19617;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='단장님, X-52 로켓 보호모를 잃어버렸지 뭐예요!', `MaleText_loc4`='长官，我不知道怎么回事，把我的X-52火箭头盔给弄丢了！', `MaleText_loc5`='首領，我好像弄丟我的X-52火箭盔帽!!!!', `MaleText_loc7`='¡¡¡¡Jefe, no sé cómo, pero he perdido mi casco de cohete X-52!!!!', `FemaleText_loc1`='단장님, X-52 로켓 보호모를 잃어버렸지 뭐예요!', `FemaleText_loc4`='长官，我不知道怎么回事，把我的X-52火箭头盔给弄丢了！', `FemaleText_loc5`='首領，我好像弄丟我的X-52火箭盔帽!!!!', `FemaleText_loc7`='¡¡¡¡Jefe, no sé cómo, pero he perdido mi casco de cohete X-52!!!!' WHERE `ID`=19618;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇다면, 어쩔 수 없지. $n, 여기 받게. 앞으로는 보호모를 주의해서 관리하게.$B$B나무에서 저절로 뚝 떨어지는 물건이 아니란 말일세. 알았나?!', `MaleText_loc4`='那么好吧，收好了，一等官员$n。记得以后看好你的头盔。$B$B要知道，那些东西并不是长在树上的！', `MaleText_loc5`='嗯，好吧，拿去，大副$n。只是以後要更小心你的盔帽。$B$B那些東西不長在樹上，你知道的!', `MaleText_loc7`='Bueno, aquí tienes, primer oficial $n. Intenta tener más cuidado con tu casco de ahora en adelante.$B$B¡Estas cosas no crecen en los árboles, ya lo sabes!' WHERE `ID`=19619;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오우거들과 싸울 때 조언을 줄 테니까 무조건 내 말을 따르게!', `MaleText_loc4`='无论我给你什么样的对付食人魔的建议，你都要听取！', `MaleText_loc5`='不管我可以給你什麼建議幫助你對抗巨魔，我都會給你!', `MaleText_loc7`='¡Cualquier consejo que pueda dar para ayudarte en tu lucha contra los ogros, lo tendrás!' WHERE `ID`=19620;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 이어지는 공격을 열심히 피합니다!', `MaleText_loc4`='%s开始敏捷地闪躲攻击！', `MaleText_loc5`='%s開始認真地閃躲遭受的攻擊!', `MaleText_loc7`='¡%s comienza a esquivar ataques intensamente!', `FemaleText_loc1`='%s|1이;가; 이어지는 공격을 열심히 피합니다!', `FemaleText_loc4`='%s开始敏捷地闪躲攻击！', `FemaleText_loc5`='%s開始認真地閃躲遭受的攻擊!', `FemaleText_loc7`='¡%s comienza a esquivar ataques intensamente!' WHERE `ID`=19621;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1을;를; 바라봅니다.', `MaleText_loc4`='面对$n。', `MaleText_loc5`='面對著$n。', `MaleText_loc7`='Enfrentándose a $n.' WHERE `ID`=19622;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 무엇보다도 자네는 우리 호드가 선조의 고향에서 살 수 있는 권리를 찾아주었네.', `MaleText_loc4`='$n，你赢得了我们的信任，欢迎部落的成员在我们的家乡落脚。', `MaleText_loc5`='$n，最重要的是，你為部落贏得了居住於我們先祖家園的權利。', `MaleText_loc7`='$n, tú más que nadie has ganado el derecho a que la Horda habite nuestro hogar ancestral.' WHERE `ID`=19623;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 부족의 유물을 되찾고 오랜 숙적이었던 칼날첨탑 오우거들과 그들을 다스리는 그론들을 무찔러 주었어. 그뿐만 아니라 천둥창까지 돌려줌으로써 우리 천둥군주 부족의 축복을 지켜주었네.', `MaleText_loc4`='你寻获了氏族的神器，你与我们的宿敌——刀塔食人魔和他们的戈隆主人交战，你又将雷霆之刺交回到了我的手中，你的义举捍卫了雷神氏族的赐福。', `MaleText_loc5`='藉由取回我們氏族的手工製品，並且與我們古老的敵人，劍刃巨魔和他們的古羅主人鬥爭，將雷霆之矛歸還到我手上，你已經使雷霆王氏族的庇護獲得保衛。', `MaleText_loc7`='Al recuperar los artefactos de nuestro clan, al reanudar la lucha contra nuestro antiguo enemigo, los ogros Aguja del Filo, y sus maestros gronn, al devolverme la Punta del Trueno, has obtenido la bendición del clan del Señor del Trueno.' WHERE `ID`=19624;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 렉사르와 자네를 지켜봐 왔네. 이 산맥에 사는 호드의 미래를 위해 그를 도와주게. 오우거들을 굴복시키고 그들의 지도자인 용 학살자 그룰을 죽여야만 자네 동족이 안전하게 지낼 수 있지.', `MaleText_loc4`='我一直在关注着你和雷克萨。你必须协助他共同保证这座山脉中的部落的未来。只有降服食人魔并消灭他们的主人——屠龙者格鲁尔，你的人民才会获得真正的安全。', `MaleText_loc5`='我一直在注意你和雷克薩。你必須幫助他保衛部落這些山脈的將來。只有當你強迫巨魔服從，並且殺死他們的主人，弒龍者戈魯爾時，你的族人才會安全。', `MaleText_loc7`='Os he estado observando a Rexxar y a ti. Debes ayudarle a asegurar el futuro de la Horda en estas montañas. Solo cuando hayas obligado a los ogros a someterse y asesinado a su maestro, Gruul el Asesino de Dragones, estará a salvo tu pueblo.' WHERE `ID`=19625;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 우리가 과거에 누렸던 영광을 되살려 주었네.', `MaleText_loc4`='你让我们的回忆倍感荣光。', `MaleText_loc5`='你為我們的回憶帶來榮譽。', `MaleText_loc7`='Honras nuestra memoria.' WHERE `ID`=19626;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 전단에는 거대한 늑대를 처치하는 임무에 대해 자세히 적혀 있습니다. 그 늑대의 은신처는 호드 요새 근처 뾰족 마루의 남쪽에 있다고 합니다.', `MaleText_loc4`='公告上写着去杀死一头凶恶的狼的内容。她的巢穴就在锯齿山的南面，靠近那里的部落要塞。', `MaleText_loc5`='告示的細節說明要處決一隻大野狼。她顯然躲在她鋸齒山脊南邊的巢穴，在部落要塞附近。', `MaleText_loc7`='Los detalles de este anuncio exigen la ejecución de una loba enorme. Parece que tiene su guarida al sur de la Cresta Dentada, cerca de la fortaleza de la Horda.' WHERE `ID`=19627;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 전단의 내용은 당신의 능력으로 감당하기엔 무리가 있습니다.$B$B나중에 다시 확인하는 것이 좋겠습니다.', `MaleText_loc4`='你还不能胜任这份悬赏工作。$B$B你应该过一段时间再回来看看。', `MaleText_loc5`='你讀著一些你覺得尚未準備好去做的事。$B$B你應該稍後再來查看。', `MaleText_loc7`='Lo que lees es algo para lo que no crees estar $gpreparado:preparada;.$B$BDeberías comprobarlo más adelante.' WHERE `ID`=19628;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훌륭해! 나를 섬길 준비가 거의 다 된 것 같구나.', `MaleText_loc4`='很好！我的宠物，看来你已经准备就绪了！', `MaleText_loc5`='非常好!你幾乎準備好當我的寵物了。', `MaleText_loc7`='¡Excelente! Casi estás $gpreparado:preparada;.', `FemaleText_loc1`='훌륭해! 나를 섬길 준비가 거의 다 된 것 같구나.', `FemaleText_loc4`='很好！我的宠物，看来你已经准备就绪了！', `FemaleText_loc5`='非常好!你幾乎準備好當我的寵物了。', `FemaleText_loc7`='¡Excelente! Casi estás $gpreparado:preparada;.' WHERE `ID`=19629;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 잘하고 있다.', `MaleText_loc4`='你进步得很快。', `MaleText_loc5`='你適應的很好。', `MaleText_loc7`='Estás mejorando mucho.', `FemaleText_loc1`='아주 잘하고 있다.', `FemaleText_loc4`='你进步得很快。', `FemaleText_loc5`='你適應的很好。', `FemaleText_loc7`='Estás mejorando mucho.' WHERE `ID`=19630;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아! 곧 조련을 마치고 현장에 투입할 수 있겠군.', `MaleText_loc4`='很好！你很快就可以被指派给一名骑士了。', `MaleText_loc5`='好極了!很快你就會準備好成為一名騎手。', `MaleText_loc7`='¡Bien! Pronto podrás ser $gun jinete:una amazona;.', `FemaleText_loc1`='좋아! 곧 조련을 마치고 현장에 투입할 수 있겠군.', `FemaleText_loc4`='很好！你很快就可以被指派给一名骑士了。', `FemaleText_loc5`='好極了!很快你就會準備好成為一名騎手。', `FemaleText_loc7`='¡Bien! Pronto podrás ser $gun jinete:una amazona;.' WHERE `ID`=19631;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청한 비룡 같으니! 시키는 그대로 따라하는 것도 못해?', `MaleText_loc4`='笨龙！你什么时候才能学会跟随？', `MaleText_loc5`='愚蠢的龍!你什麼時候才能學會聽從指令?', `MaleText_loc7`='¡Draco estúpido! ¿Cuándo aprenderás a seguir indicaciones?', `FemaleText_loc1`='멍청한 비룡 같으니! 시키는 그대로 따라하는 것도 못해?', `FemaleText_loc4`='笨龙！你什么时候才能学会跟随？', `FemaleText_loc5`='愚蠢的龍!你什麼時候才能學會聽從指令?', `FemaleText_loc7`='¡Draco estúpido! ¿Cuándo aprenderás a seguir indicaciones?' WHERE `ID`=19632;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 간단한 훈련 하나도 제대로 못 마치면 안락사시킬 줄 알아.', `MaleText_loc4`='要是你总是完不成这些简单的任务，我就把你解决了。', `MaleText_loc5`='如果你一直做不好這些簡單的任務，你就會被奚落。', `MaleText_loc7`='Si continúas fracasando en estas tareas sencillas, serás $gsacrificado:sacrificada;.', `FemaleText_loc1`='이렇게 간단한 훈련 하나도 제대로 못 마치면 안락사시킬 줄 알아.', `FemaleText_loc4`='要是你总是完不成这些简单的任务，我就把你解决了。', `FemaleText_loc5`='如果你一直做不好這些簡單的任務，你就會被奚落。', `FemaleText_loc7`='Si continúas fracasando en estas tareas sencillas, serás $gsacrificado:sacrificada;.' WHERE `ID`=19633;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실패하는 걸 지켜보는 일도 이제 지겹구나. 시키는 대로 못하면 데리고 있을 이유가 없지.', `MaleText_loc4`='你一次又一次的失败让我对你丧失了信心。如果你不听从我们的指示，留你何用？', `MaleText_loc5`='你的失敗讓我厭倦。如果你不能按指示去做，你對我們就沒有用處。', `MaleText_loc7`='Tus fracasos me están cansando. Si no puedes hacer lo que se te indica, no nos servirás de nada.', `FemaleText_loc1`='실패하는 걸 지켜보는 일도 이제 지겹구나. 시키는 대로 못하면 데리고 있을 이유가 없지.', `FemaleText_loc4`='你一次又一次的失败让我对你丧失了信心。如果你不听从我们的指示，留你何用？', `FemaleText_loc5`='你的失敗讓我厭倦。如果你不能按指示去做，你對我們就沒有用處。', `FemaleText_loc7`='Tus fracasos me están cansando. Si no puedes hacer lo que se te indica, no nos servirás de nada.' WHERE `ID`=19634;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 이제 배운 대로 해봐!', `MaleText_loc4`='按指示行事！', `MaleText_loc5`='現在，執行指令!', `MaleText_loc7`='¡Ahora sigue las instrucciones!', `FemaleText_loc1`='자, 이제 배운 대로 해봐!', `FemaleText_loc4`='按指示行事！', `FemaleText_loc5`='現在，執行指令!', `FemaleText_loc7`='¡Ahora sigue las instrucciones!' WHERE `ID`=19635;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽을 준비나 해라!', `MaleText_loc4`='受死吧！', `MaleText_loc5`='準備受死吧!', `MaleText_loc7`='¡Prepárate para morir!' WHERE `ID`=19636;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<비전 수호병이 도시 중심부의 북동쪽 계단을 가리킵니다.>', `MaleText_loc4`='<奥术守护者指了指平台下面，城市中心东北方向的楼梯。>', `MaleText_loc5`='<秘法守護者指著階層下方的一個地方，城中心東北方的一個樓梯井。>', `MaleText_loc7`='<El guardián Arcano hace un gesto hacia un lugar bajo la Grada, un hueco de la escalera al noreste del centro de la ciudad.>' WHERE `ID`=19637;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<비전 수호병이 도시 중심부의 남동쪽 계단을 가리킵니다.>', `MaleText_loc4`='<奥术守护者指了指平台下面，城市中心东南方向的楼梯。>', `MaleText_loc5`='<秘法守護者指著階層下方的一個地方，城中心東南方的一個樓梯井。>', `MaleText_loc7`='<El guardián Arcano hace un gesto hacia un lugar bajo la Grada, un hueco de la escalera al sureste del centro de la ciudad.>' WHERE `ID`=19638;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<비전 수호병이 고난의 거리에서 북서쪽에 있는 지역을 가리킵니다. 바로 샤트라스의 아라코아가 거주하는 곳입니다.>', `MaleText_loc4`='<奥术守护者指了指贫民窟的西北部分，沙塔斯城的鸦人居住地。>', `MaleText_loc5`='<秘法守護者指向陰鬱城的西北方，撒塔斯的阿拉卡就住在那。>', `MaleText_loc7`='<El guardián Arcano hace un gesto hacia la parte noreste de la parte baja de la ciudad, donde habitan los arakkoa de Shattrath.>' WHERE `ID`=19640;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<비전 수호병이 고난의 거리를 가리킵니다. 대용광로가 있는 곳입니다.>', `MaleText_loc4`='<奥术守护者指了指下面的贫民窟，在那里可以找到一座巨大的熔炉。>', `MaleText_loc5`='<秘法守護者向下指著陰鬱城，那裡可能有一個大熔爐。>', `MaleText_loc7`='<El guardián Arcano hace un gesto hacia la parte baja de la ciudad, donde se puede encontrar una gran forja.>' WHERE `ID`=19641;
