UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속해라! 난 더 강해질 테니까!', `MaleText_loc4`='继续，杀了他们吧！我会变得更强大！', `MaleText_loc5`='繼續，殺死他們!我會做的更好!', `MaleText_loc7`='¡Adelante, mátenlos! ¡Es mejor para mi!' WHERE `ID`=19643;
