UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 그 어느 때보다 더 강력하다!', `MaleText_loc4`='我从来都没有如此强大过！', `MaleText_loc5`='我比以前更加的強大!', `MaleText_loc7`='¡Tengo más poder que nunca!' WHERE `ID`=19645;
