UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<비전 수호병이 고난의 거리의 북동쪽 지역을 가리킵니다.>', `MaleText_loc4`='<奥术守护者指了指贫民窟的东北区域。>', `MaleText_loc5`='<秘法守護者指向陰鬱城的東北區。>', `MaleText_loc7`='<El guardián Arcano hace un gesto hacia la sección nororiental de la parte baja de la ciudad.>' WHERE `ID`=19647;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<비전 수호병이 알도르 마루를 가리킵니다.>', `MaleText_loc4`='<奥术守护者指了指奥尔多高地。>', `MaleText_loc5`='<秘法守護者指向奧多爾高地。>', `MaleText_loc7`='<El guardián Arcano hace un gesto hacia Alto Aldor.>' WHERE `ID`=19648;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<비전 수호병이 고난의 거리에서 열린 시장 쪽을 가리킵니다.>', `MaleText_loc4`='<奥术守护者指了指贫民窟的露天市场。>', `MaleText_loc5`='<秘法守護者指向那些陰鬱城的公開市場。>', `MaleText_loc7`='<El guardián Arcano hace un gesto hacia el mercado al aire libre de la parte baja de la ciudad.>' WHERE `ID`=19650;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알도르 마루에 오신 것을 환영합니다. 도움이 필요하십니까?', `MaleText_loc4`='欢迎来到奥尔多高地，你在寻求指引吗？', `MaleText_loc5`='歡迎來到奧多爾高地。你在尋找引導嗎?', `MaleText_loc7`='$gBienvenido:Bienvenida; a Alto Aldor. ¿Buscas orientación?', `FemaleText_loc1`='알도르 마루에 오신 것을 환영해요. 도움이 필요하세요?', `FemaleText_loc4`='欢迎来到奥尔多高地，你在寻求指引吗？', `FemaleText_loc5`='歡迎來到奧多爾高地。你在尋找引導嗎?', `FemaleText_loc7`='$gBienvenido:Bienvenida; a Alto Aldor. ¿Buscas orientación?' WHERE `ID`=19651;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알도르 마루의 남쪽 지역에 편안히 쉴만한 장소를 제공하는 여관이 있습니다.', `MaleText_loc4`='医护中心位于奥尔多高地的南部。', `MaleText_loc5`='你可以在奧多爾高地南部找到照顧者中心。', `MaleText_loc7`='Encontrarás un centro de cuidadores en la parte sur de Alto Aldor.', `FemaleText_loc1`='알도르 마루의 남쪽 지역에 편안히 쉴만한 장소를 제공하는 여관이 있습니다.', `FemaleText_loc4`='医护中心位于奥尔多高地的南部。', `FemaleText_loc5`='你可以在奧多爾高地南部找到照顧者中心。', `FemaleText_loc7`='Encontrarás un centro de cuidadores en la parte sur de Alto Aldor.' WHERE `ID`=19652;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여관 근처에서 우체통을 하나 찾을 수 있을 겁니다.', `MaleText_loc4`='医护中心附近就有邮箱。', `MaleText_loc5`='你可以在照顧者中心附近找到郵箱。', `MaleText_loc7`='Encontrarás un buzón de correo cerca del centro de cuidadores.', `FemaleText_loc1`='여관 근처에서 우체통을 하나 찾을 수 있을 겁니다.', `FemaleText_loc4`='医护中心附近就有邮箱。', `FemaleText_loc5`='你可以在照顧者中心附近找到郵箱。', `FemaleText_loc7`='Encontrarás un buzón de correo cerca del centro de cuidadores.' WHERE `ID`=19653;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여관 근처에서 야수 관리인을 찾을 수 있을 겁니다.', `MaleText_loc4`='兽栏管理员在医护中心附近。', `MaleText_loc5`='你可以在照顧者中心附近找到獸欄管理員。', `MaleText_loc7`='Encontrarás al maestro de establos cerca del centro de cuidadores.', `FemaleText_loc1`='여관 근처에서 야수 관리인을 찾을 수 있을 겁니다.', `FemaleText_loc4`='兽栏管理员在医护中心附近。', `FemaleText_loc5`='你可以在照顧者中心附近找到獸欄管理員。', `FemaleText_loc7`='Encontrarás al maestro de establos cerca del centro de cuidadores.' WHERE `ID`=19654;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전문 마법부여사 주리는 알도르 마루 남쪽에 있습니다.', `MaleText_loc4`='你可以在奥尔多高地的南部找到附魔训练师苏蕾。', `MaleText_loc5`='你可以在奧多爾高地的南邊找到祖瑞，我們的附魔訓練師。', `MaleText_loc7`='Encontrarás a la instructora de encantamiento Zurii en la parte sur de Alto Aldor.', `FemaleText_loc1`='전문 마법부여사 주리는 알도르 마루 남쪽에 있습니다.', `FemaleText_loc4`='你可以在奥尔多高地的南部找到附魔训练师苏蕾。', `FemaleText_loc5`='你可以在奧多爾高地的南邊找到祖瑞，我們的附魔訓練師。', `FemaleText_loc7`='Encontrarás a la instructora de encantamiento Zurii en la parte sur de Alto Aldor.' WHERE `ID`=19655;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알도르 마루 북쪽에 보석세공의 대가 하마나르가 있습니다.', `MaleText_loc4`='你可以在奥尔多高地的北部找到宗师级珠宝匠哈曼纳尔。', `MaleText_loc5`='我們的珠寶設計大師哈曼那就在奧多爾高地的北邊。', `MaleText_loc7`='El gran maestro joyero Hamanar se encuentra en la parte norte de Alto Aldor.', `FemaleText_loc1`='알도르 마루 북쪽에 보석세공의 대가 하마나르가 있습니다.', `FemaleText_loc4`='你可以在奥尔多高地的北部找到宗师级珠宝匠哈曼纳尔。', `FemaleText_loc5`='我們的珠寶設計大師哈曼那就在奧多爾高地的北邊。', `FemaleText_loc7`='El gran maestro joyero Hamanar se encuentra en la parte norte de Alto Aldor.' WHERE `ID`=19656;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까? 저는 실버문 인사장교입니다. 제 임무는 호드 훈장을 받은 모험가들을 돕는 것입니다.$B$B꼭 정해진 양의 훈장을 가져와야 하는 것은 아니지만 한 번에 열 개씩 묶어서 가져오는 것이 이득이 가장 많습니다. 훈장을 가져오면 그대의 공적을 기록해 놓겠습니다. 그러면 실버문에서 그대의 명성이 드높아질 겁니다.', `MaleText_loc4`='你好，$C——我是银月城的嘉奖官。我的职责就是帮助那些获得部落荣誉徽章的冒险者们。$B$B我一次可以收取不同数量的徽章，但是对你来说，一次缴纳10枚徽章就能获得最高的收益。我会保留你缴纳徽章的记录，你在银月城的声望也会因此提高。', `MaleText_loc5`='你好，$c - 我是代表銀月城的表揚官。幫助已經得到部落榮譽徽章的冒險者是我的職責。$B$B我接受不同數量的徽記，但是對你最有利的兌換是一次同時交出10枚。當你交出你的徽記時，我將把你的功績輸入我們的記錄中。因此，你將為你的職責和服務贏得來自銀月城的認可。', `MaleText_loc7`='Saludos, $c – soy un oficial de Honor que actúa en nombre de la ciudad de Lunargenta. Mi deber es ayudar a los aventureros que hayan recibido sellos de mención de honor de la Horda.$B$BAcepto sellos en diferentes cantidades, pero el intercambio más beneficioso para ti es entregarlos en series de diez a la vez. Introduciré tus hazañas en nuestros registros cuando entregues tus sellos. Como resultado, obtendrás reconocimiento de la ciudad de Lunargenta por tu deber y servicio.', `FemaleText_loc1`='안녕하세요? 저는 실버문 인사장교랍니다. 제 임무는 호드 훈장을 받은 모험가들을 돕는 거예요.$B$B꼭 정해진 양의 훈장을 가져와야 하는 것은 아니지만 한 번에 열 개씩 묶어서 가져오는 것이 이득이 가장 많아요. 훈장을 가져오면 그대의 공적을 기록해 놓을게요. 그러면 실버문에서 그대의 명성이 드높아질 거랍니다.', `FemaleText_loc4`='你好，$C——我是银月城的嘉奖官。我的职责就是帮助那些获得部落荣誉徽章的冒险者们。$B$B我一次可以收取不同数量的徽章，但是对你来说，一次缴纳10枚徽章就能获得最高的收益。我会保留你缴纳徽章的记录，你在银月城的声望也会因此提高。', `FemaleText_loc5`='你好，$c - 我是代表銀月城的表揚官。幫助已經得到部落榮譽徽章的冒險者是我的職責。$B$B我接受不同數量的徽記，但是對你最有利的兌換是一次同時交出10枚。當你交出你的徽記時，我將把你的功績輸入我們的記錄中。因此，你將為你的職責和服務贏得來自銀月城的認可。', `FemaleText_loc7`='Saludos, $c – soy una oficial de Honor que actúa en nombre de la ciudad de Lunargenta. Mi deber es ayudar a los aventureros que hayan recibido sellos de mención de honor de la Horda.$B$BAcepto sellos en diferentes cantidades, pero el intercambio más beneficioso para ti es entregarlos en series de diez a la vez. Introduciré tus hazañas en nuestros registros cuando entregues tus sellos. Como resultado, obtendrás reconocimiento de la ciudad de Lunargenta por tu deber y servicio.' WHERE `ID`=19657;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, $c|1이여;여;. 저는 엑소다르의 인사장교입니다. 얼라이언스 무공 훈장을 받은 모험가들을 돕는 것이 제 임무랍니다.$B$B훈장을 꼭 정해진 양만큼 가져와야 하는 건 아니지만 한 번에 열 개씩 가져오시는 것이 가장 이득이 될 겁니다. 훈장을 가져오면 당신의 공적을 기록해 놓겠습니다. 그러면 엑소다르에서 당신의 명성이 올라가지요.', `MaleText_loc4`='你好，$C——我是埃索达的嘉奖官。我的职责就是帮助那些获得联盟荣誉徽章的冒险者们。$B$B我一次可以收取不同数量的徽章，但是对你来说，一次缴纳10枚徽章就能获得最高的收益。我会保留你缴纳徽章的记录，你在埃索达的声望也会因此提高。', `MaleText_loc5`='你好，$c - 我是代表艾克索達的表揚官。幫助已經得到聯盟榮譽徽章的冒險者是我的職責。$B$B我接受不同數量的徽記，但是對你最有利的兌換是一次同時交出10枚。當你交出你的徽記時，我將把你的功績輸入我們的記錄中。因此，你將因你的職責和服務贏得艾克索達的認可。', `MaleText_loc7`='Saludos, $c – soy un oficial de honor que actúa en nombre de El Exodar. Mi deber es ayudar a los aventureros que hayan recibido sellos de mención de honor de la Alianza.$B$BAcepto sellos en diferentes cantidades, pero el intercambio más beneficioso para ti es entregarlos en series de diez a la vez. Introduciré tus hazañas en nuestros registros cuando entregues tus sellos. Como resultado, obtendrás reconocimiento de El Exodar por tu deber y servicio.', `FemaleText_loc1`='안녕하십니까, $c|1이여;여;. 저는 엑소다르의 인사장교입니다. 얼라이언스 무공 훈장을 받은 모험가들을 돕는 것이 제 임무랍니다.$B$B훈장을 꼭 정해진 양만큼 가져와야 하는 건 아니지만 한 번에 열 개씩 가져오시는 것이 가장 이득이 될 겁니다. 훈장을 가져오면 당신의 공적을 기록해 놓겠습니다. 그러면 엑소다르에서 당신의 명성이 올라가지요.', `FemaleText_loc4`='你好，$C——我是埃索达的嘉奖官。我的职责就是帮助那些获得联盟荣誉徽章的冒险者们。$B$B我一次可以收取不同数量的徽章，但是对你来说，一次缴纳10枚徽章就能获得最高的收益。我会保留你缴纳徽章的记录，你在埃索达的声望也会因此提高。', `FemaleText_loc5`='你好，$c - 我是代表艾克索達的表揚官。幫助已經得到聯盟榮譽徽章的冒險者是我的職責。$B$B我接受不同數量的徽記，但是對你最有利的兌換是一次同時交出10枚。當你交出你的徽記時，我將把你的功績輸入我們的記錄中。因此，你將因你的職責和服務贏得艾克索達的認可。', `FemaleText_loc7`='Saludos, $c – soy una oficial de honor que actúa en nombre de El Exodar. Mi deber es ayudar a los aventureros que hayan recibido sellos de mención de honor de la Alianza.$B$BAcepto sellos en diferentes cantidades, pero el intercambio más beneficioso para ti es entregarlos en series de diez a la vez. Introduciré tus hazañas en nuestros registros cuando entregues tus sellos. Como resultado, obtendrás reconocimiento de El Exodar por tu deber y servicio.' WHERE `ID`=19658;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황천바위거인?! 놈이 그 거대한 발을 한 발짝만 옮겨도 당신들은 쥐포가 될 거라고! 고맙지만, 난 됐어!', `MaleText_loc4`='灵岩巨人？！那东西一脚就能把你踩扁！不用了，谢谢！', `MaleText_loc5`='虛空石?!那東西會用它巨大的腳一步就把你踩扁!不用了謝謝!', `MaleText_loc7`='¡¿Roca abisal?! ¡Esa cosa te aplastará con una sola pisada de su enorme pie! ¡No, gracias!', `FemaleText_loc1`='황천바위거인?! 놈이 그 거대한 발을 한 발짝만 옮겨도 당신들은 쥐포가 될 거라고! 고맙지만, 난 됐어!', `FemaleText_loc4`='灵岩巨人？！那东西一脚就能把你踩扁！不用了，谢谢！', `FemaleText_loc5`='虛空石?!那東西會用它巨大的腳一步就把你踩扁!不用了謝謝!', `FemaleText_loc7`='¡¿Roca abisal?! ¡Esa cosa te aplastará con una sola pisada de su enorme pie! ¡No, gracias!' WHERE `ID`=19659;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지난번에 누군가 황천바위거인의 목에 걸린 현상금을 노리고 나간 적이 있었는데 우리에게 돌아온 것이라고는 무모한 모험가의 납작한 시체뿐이었다고!', `MaleText_loc4`='上次有人妄想获得灵岩巨人的赏金，最后那个愚蠢的冒险者被踩成了照片。', `MaleText_loc5`='上次某人嘗試在虛空石身上收集物產，而我們收回的全部都是被壓的扁扁的蠻勇冒險者!', `MaleText_loc7`='La última vez que alguien fue a intentar cobrar la recompensa a la Roca Abisal, ¡todo lo que recuperamos fue una capa comprimida de aventurero temerario!', `FemaleText_loc1`='지난번에 누군가 황천바위거인의 목에 걸린 현상금을 노리고 나간 적이 있었는데 우리에게 돌아온 것이라고는 무모한 모험가의 납작한 시체뿐이었다고!', `FemaleText_loc4`='上次有人妄想获得灵岩巨人的赏金，最后那个愚蠢的冒险者被踩成了照片。', `FemaleText_loc5`='上次某人嘗試在虛空石身上收集物產，而我們收回的全部都是被壓的扁扁的蠻勇冒險者!', `FemaleText_loc7`='¡La última vez que alguien fue a intentar cobrar la recompensa a la Roca Abisal, todo lo que recuperamos fue una capa comprimida de aventurero temerario!' WHERE `ID`=19660;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼날 산맥은 엄청난 기회의 땅일세. 그런 기회를 이용하는 데 자기들이 다른 이들보다 우위에 있다고 생각하는 자들이 있다니 정말 유감스러워.$B$B세나리온 원정대는 얼마나 잘났기에 우리보고 이래라저래라 말이 많은 거지?', `MaleText_loc4`='刀锋山是充满机遇的地方。不幸的是总有些家伙自认为他们要比其他人更能占有先机。$B$B塞纳里奥远征队觉得他们自己是谁？居然敢在这里对我们指手画脚？', `MaleText_loc5`='劍刃山脈是一個有極好機會的地方。多麼不幸，有些人認為自己在利用這樣機會的事情上是比其他人高高在上的。$B$B塞納里奧遠征隊以為他們是誰可以告訴我們什麼事可以做什麼事不能做?', `MaleText_loc7`='Las Montañas Filospada son un lugar de grandes oportunidades. Qué mala suerte que algunos consideren estar por encima de los demás en asuntos que se refieren a aprovecharse de tales oportunidades.$B$B¿Quién se cree que es la Expedición de Cenarion para decirnos lo que podemos o no podemos hacer aquí?' WHERE `ID`=19661;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감독관이여, 나는 세나리온 원정대를 대표해서 당신과 협상을 하고자 여기 왔습니다.', `MaleText_loc4`='工头，我是来代表塞纳里奥远征队和你谈判的。', `MaleText_loc5`='監督者，我代表塞納里奧遠征隊來這裡談判。', `MaleText_loc7`='Sobrestante, estoy aquí para negociar en nombre de la Expedición de Cenarion.', `FemaleText_loc1`='감독관이여, 나는 세나리온 원정대를 대표해서 당신과 협상을 하고자 여기 왔습니다.', `FemaleText_loc4`='工头，我是来代表塞纳里奥远征队和你谈判的。', `FemaleText_loc5`='監督者，我代表塞納里奧遠征隊來這裡談判。', `FemaleText_loc7`='Sobrestante, estoy aquí para negociar en nombre de la Expedición de Cenarion.' WHERE `ID`=19662;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='협상? 협상이라고 했나!$B$B우리 입장을 명확하게 얘기해 주지. 우리는 무엇이든 우리 의지대로 할 자유가 있다. 세나리온 원정대는 이 산맥의 주인이 아니라는 말이지.$B$B협상이란 있을 수 없네! 이제 그 드루이드들에게 가서 앞으로도 우리는 원하는 일을 그대로 진행할 것이라 전하게.', `MaleText_loc4`='谈判？谈判！$B$B请允许我把我们的立场完全说清楚。我们是自由人，没有人能干涉我们的自由。塞纳里奥远征队并不是这片山脉的主人。$B$B所以没有什么好谈的！现在，回去告诉那些德鲁伊，我们还是要我行我素。', `MaleText_loc5`='談判?談判!$B$B讓我把我們的立場說清楚。我們是一支自由的民族，能夠做我們想要做的事並隨意來去。塞納里奧遠征隊不擁有這條山脈。$B$B沒有談判!現在，回到德魯伊那裡告訴他們我們將繼續想做什麼就做什麼。', `MaleText_loc7`='¿Negociaciones? ¡NEGOCIACIONES!$B$BPermíteme dejar totalmente clara nuestra postura. Somos un pueblo libre, capaz de hacer lo que queramos y movernos como nos plazca. La Expedición de Cenarion no es dueña de esta cadena montañosa.$B$B¡No habrá negociaciones! Ahora vuelve con los druidas y diles que seguiremos haciendo lo que nos plazca.' WHERE `ID`=19663;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 이 산맥의 균형을 회복할 수 있는지 확인하고자 이곳 루안 숲으로 왔소.$B$B그런데 아라코아와 고룡교단의 방해 때문에 일이 어렵게 됐소이다.$B$B그래도 당신과 사미아처럼 우리를 도와주려는 친구들이 있어서 얼마나 다행인지 모른다오.', `MaleText_loc4`='我们来到卢安荒野是想看看是否能够帮助这些山脉恢复自然的平衡。$B$B然而，我们与鸦人和拜龙教之间的矛盾让这个任务变得困难起来。$B$B幸运的是，还有像你和萨米亚那样的人愿意帮助我们。', `MaleText_loc5`='我們已經來到魯安曠野，看看是否我們能重建這些山岳的自然平衡。$B$B但是，阿拉卡和巨龍教團的干擾使得這成為一項艱難的任務。$B$B很幸運還有那些像你和沙彌亞一樣願意幫助我們的人。', `MaleText_loc7`='Hemos venido a la Foresta Ruuan para ver si podemos restablecer el equilibrio de la naturaleza en estas montañas.$B$BSin embargo, la intromisión de los arakkoa y el Culto Vermis está dificultando la tarea.$B$BAfortunadamente, hay gente como tú y Samia, dispuesta a echarnos una mano.' WHERE `ID`=19664;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하, 다시 돌아오셨다? 내가 마음을 고쳐먹을 거라고 진짜 기대하는 건가?$B$B꺼져.', `MaleText_loc4`='哈哈，你回来了？你不会真的期盼我改变心意吧？$B$B你错了。', `MaleText_loc5`='哈哈，你回來了?你不是真的期望我改變主意吧，是嗎?$B$B滾開。', `MaleText_loc7`='Jaja, ¿has vuelto? No esperarás en serio que cambie de opinión acerca de ti, ¿verdad?$B$BPiérdete.' WHERE `ID`=19665;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언덕 아래 조종장치를 몇 개를 만들어 놓았네. 빨리 아무 조종장치나 선택해서 지옥절단기를 조종하게! 시간이 얼마 없단 말일세.', `MaleText_loc4`='我在斜坡下装好了几个控制器。快去那里控制魔能机甲！你的时间非常有限。', `MaleText_loc5`='我已經在斜坡上裝了一些控制器。快速到達其中一個並且控制住惡魔劫奪者!你的時間有限。', `MaleText_loc7`='He manipulado unas cuantas consolas de control por la pendiente. ¡Toma una rápidamente y controla al atracador vil! Tendrás un límite de tiempo.' WHERE `ID`=19666;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시험 비행할 준비가 됐습니다.', `MaleText_loc4`='我已经准备好开始测试飞行了！', `MaleText_loc5`='我準備進行好我的飛行試驗!', `MaleText_loc7`='¡Estoy preparado para mi prueba de vuelo!', `FemaleText_loc1`='시험 비행할 준비가 됐어요.', `FemaleText_loc4`='我已经准备好开始测试飞行了！', `FemaleText_loc5`='我準備進行好我的飛行試驗!', `FemaleText_loc7`='¡Estoy preparada para mi prueba de vuelo!' WHERE `ID`=19667;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라잔의 영지로 보내 주십시오.', `MaleText_loc4`='送我到拉扎安码头去！', `MaleText_loc5`='帶我到雷森平台!', `MaleText_loc7`='¡Llévame a la Zona de Aterrizaje de Razaan!', `FemaleText_loc1`='라잔의 영지로 보내 주세요.', `FemaleText_loc4`='送我到拉扎安码头去！', `FemaleText_loc5`='帶我到雷森平台!', `FemaleText_loc7`='¡Llévame a la Zona de Aterrizaje de Razaan!' WHERE `ID`=19668;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='루안으로 보내 주십시오.', `MaleText_loc4`='带我去卢安。', `MaleText_loc5`='帶我到魯安曠野。', `MaleText_loc7`='Llévame a Ruuan.', `FemaleText_loc1`='루안으로 보내 주세요.', `FemaleText_loc4`='带我去卢安。', `FemaleText_loc5`='帶我到魯安曠野。', `FemaleText_loc7`='Llévame a Ruuan.' WHERE `ID`=19669;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='까마귀 숲으로 보내 주십시오.', `MaleText_loc4`='带我去乌鸦林。', `MaleText_loc5`='帶我到烏鴉林。', `MaleText_loc7`='Llévame al Bosque del Cuervo.', `FemaleText_loc1`='까마귀 숲으로 보내 주세요.', `FemaleText_loc4`='带我去乌鸦林。', `FemaleText_loc5`='帶我到烏鴉林。', `FemaleText_loc7`='Llévame al Bosque del Cuervo.' WHERE `ID`=19670;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노래하는 마루로 보내 주십시오.', `MaleText_loc4`='带我去晶歌山脉。', `MaleText_loc5`='帶我到美聲山脊。', `MaleText_loc7`='Llévame a Cresta Canto.', `FemaleText_loc1`='노래하는 마루로 보내 주세요.', `FemaleText_loc4`='带我去晶歌山脉。', `FemaleText_loc5`='帶我到美聲山脊。', `FemaleText_loc7`='Llévame a Cresta Canto.' WHERE `ID`=19671;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 총을 연결하도록!!', `MaleText_loc4`='把枪都准备好！！！！', `MaleText_loc5`='讓那些槍上戰場!', `MaleText_loc7`='¡¡ALINEAD ESAS ARMAS!!' WHERE `ID`=19672;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방어 포탑 발사!', `MaleText_loc4`='开火！', `MaleText_loc5`='發射防禦槍!', `MaleText_loc7`='¡DISPARAD LAS ARMAS!' WHERE `ID`=19673;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 우리가 통제할 수 있습니다. 기병대 여러분, 이만 해산해도 좋습니다.', `MaleText_loc4`='我们可以控制住形势了。硬汉队，你们可以休息了。', `MaleText_loc5`='接下來就交給我們吧。騎兵們你們可以離開了。', `MaleText_loc7`='Podemos encargarnos nosotros a partir de aquí. Jinetes Férreos, podéis retiraros.' WHERE `ID`=19674;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 빨리 말하게. 시간이 별로 없어!', `MaleText_loc4`='说快点，$n。我们没有太多时间！', `MaleText_loc5`='講快一點，$n。我們沒有很多時間!', `MaleText_loc7`='Habla rápido, $n. ¡No tenemos mucho tiempo!', `FemaleText_loc1`='$n, 빨리 말하게. 시간이 별로 없어!', `FemaleText_loc4`='说快点，$n。我们没有太多时间！', `FemaleText_loc5`='講快一點，$n。我們沒有很多時間!', `FemaleText_loc7`='Habla rápido, $n. ¡No tenemos mucho tiempo!' WHERE `ID`=19675;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수집 중', `MaleText_loc4`='收集中', `MaleText_loc5`='收集中', `MaleText_loc7`='Recoger', `FemaleText_loc1`='수집 중', `FemaleText_loc4`='收集中', `FemaleText_loc5`='收集中', `FemaleText_loc7`='Recoger' WHERE `ID`=19676;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 불규칙 전이 영역에서 전하가 감지되는군요! 최근에 돌개바람 축전장치를 사용한 게 틀림없어요. 전하가 완전히 사라지기 전에는 다시 사용할 수 없습니다...', `MaleText_loc4`='我在你的大肠后部区域检测到了电荷！你最近肯定使用过风动电容器……在电荷消失前，你不能再使用它了……', `MaleText_loc5`='我在你的帕拿拉布賴電子地區偵測到一個能量源!你最近一定使用ZC號 -- 你必須等到能量逐漸消失後才能再次使用它...', `MaleText_loc7`='¡Detecto una carga en tu región paranarbulátrica! Debes de haber utilizado el Cefirium Capacitorium últimamente – no puedes volver a usarlo hasta que se agote la carga...' WHERE `ID`=19677;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 세이블메인 남작님의 명령에 따라 고룡교단 때문에 어려움을 겪고 있는 세나리온 원정대를 돕고자 여기 왔습니다.$B$B이런 일은 제 전문이죠.', `FemaleText_loc4`='我的主人萨博迈恩男爵派我来这里帮助塞纳里奥远征队解决他们与拜龙教之间的问题。$B$B我是这方面的专家。', `FemaleText_loc5`='我受我的主人，沙伯邁恩男爵委託來此，幫助塞納里奧遠征隊處理巨龍教團的麻煩。$B$B我在這些事情方面算是個專家。', `FemaleText_loc7`='Estoy aquí a instancias de mi maestro, el Barón Sablecrín, para ayudar a la Expedición de Cenarion con sus problemas con el Culto Vermis.$B$BSoy bastante experta en estas cosas.' WHERE `ID`=19678;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='천한 놈들을 상대하며 품위를 손상시키고 싶진 않았는데... 너희들이 자초한 일이다.', `FemaleText_loc4`='我本不想屈尊与你们交战，但是你们让我别无选择……', `FemaleText_loc5`='我不願和你的族人交戰來貶低自己，但你讓我別無選擇...', `FemaleText_loc7`='No quería rebajarme y tener contacto con su clase, pero no me dejan elección...' WHERE `ID`=19679;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='찾는 중', `MaleText_loc4`='搜索中', `MaleText_loc5`='搜尋中', `MaleText_loc7`='Buscando', `FemaleText_loc1`='찾는 중', `FemaleText_loc4`='搜索中', `FemaleText_loc5`='搜尋中', `FemaleText_loc7`='Buscando' WHERE `ID`=19680;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누아르, 괜찮나? 오늘 별로 좋아 보이지 않는군...', `MaleText_loc4`='努埃尔，你还好吧？你今天看上去有些不大对劲。', `MaleText_loc5`='奴阿爾，你感覺好嗎?你今天看起來不像你。', `MaleText_loc7`='Nuaar, ¿te encuentras bien? Hoy no pareces tú.' WHERE `ID`=19681;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 가보게, 감독관! 우리 얘기는 끝났다.$B$B지체하지 말고 당장 루안 숲으로 가서 임무를 수행하도록!', `MaleText_loc4`='滚开，工头！我们已经谈过了。$B$B别再磨蹭了，去卢安荒野执行命令吧。', `MaleText_loc5`='走開，監督者!我們已經談過了。$B$B不要再在魯安曠野拖拖拉拉的執行你的訂單!', `MaleText_loc7`='¡Lárgate, sobrestante! Ya hemos hablado.$B$B¡Deja de arrastrar los pies y ejecuta tus órdenes en la Foresta Ruuan!' WHERE `ID`=19682;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 괜찮습니다. 걱정해 주시니 고맙군요. 그래 듣자하니 절 보자고 하셨다고요?', `MaleText_loc4`='我很好，谢谢你。你在找我？', `MaleText_loc5`='我很好，謝謝。 你找我嗎?', `MaleText_loc7`='Estoy bien, gracias. ¿Has preguntado por mí?', `FemaleText_loc1`='전 괜찮습니다. 걱정해 주시니 고맙군요. 그래 듣자하니 절 보자고 하셨다고요?', `FemaleText_loc4`='我很好，谢谢你。你在找我？', `FemaleText_loc5`='我很好，謝謝。 你找我嗎?', `FemaleText_loc7`='Estoy bien, gracias. ¿Has preguntado por mí?' WHERE `ID`=19683;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 회의를 해야지. 본론부터 말하겠어.$B$B감독관, 자네가 담당하는 루안 숲의 목재와 가축 수집 속도가 크게 떨어졌네.$B$B우리에겐 그 자원이 꼭 필요하다는 걸 알고 있겠지? 그런데 자넨 세나리온 원정대의 드루이드들이 우리 물자 수집을 방해하도록 놔두고 있어!', `MaleText_loc4`='是的，让我们静下心来商讨一下吧。$B$B实际上，你负责把木材和家畜汇聚到卢安荒野，而你的进度越来越慢了。$B$B我们需要那些资源，但是你却让塞纳里奥远征队的德鲁伊来妨碍我们！', `MaleText_loc5`='對了，會議。讓我們開始認真的看待它。$B$B事實上你負責在魯安曠野收集的木材和家畜，速度已經慢到變成一條細流。$B$B我們需要那些資源，但是你已經允許塞納里奧遠征隊的德魯伊在那裡礙事!', `MaleText_loc7`='Cierto, la reunión. Vayamos al grano, entonces.$B$BEl hecho es que la madera y el ganado que se está reuniendo de la Foresta Ruuan, de lo que tú eres responsable, ha disminuido sobremanera.$B$B¡Necesitamos esos recursos, pero has permitido que los druidas de la Expedición de Cenarion se interpongan en nuestro camino!' WHERE `ID`=19684;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 그건 제 잘못이 아닙니다. 정말입니다.', `MaleText_loc4`='哦，这不是我的错，我向你保证。', `MaleText_loc5`='喔，這不是我的錯，我能向你保證。', `MaleText_loc7`='Oh, no es culpa mía, te lo aseguro.', `FemaleText_loc1`='오, 그건 제 잘못이 아닙니다. 정말입니다.', `FemaleText_loc4`='哦，这不是我的错，我向你保证。', `FemaleText_loc5`='喔，這不是我的錯，我能向你保證。', `FemaleText_loc7`='Oh, no es culpa mía, te lo aseguro.' WHERE `ID`=19685;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='변명은 필요 없네. 난 결과만을 원해!$B$B우리가 여기서 하는 일이 장난 같나? 이번 일을 제대로 하지 못하면 소위 사회 개혁론자라는 자들의 부름을 받게 될 뿐 아니라, 검은날개 소굴에서 진급하기도 어려워질 것이 뻔하단 말이야.$B$B그게 자네가 원하는 건가?', `MaleText_loc4`='我不要借口，我需要结果！$B$B你觉得我像是在开玩笑吗？如果我们不这么做的话，那么不仅那些所谓的好人们会跑过来叫嚷，而且这也对提升黑翼的繁荣没有任何价值。$B$B那是你想看到的结果吗？', `MaleText_loc5`='我不想聽藉口，我只要結果!$B$B你以為我們是在這裡當一個笑話嗎?如果我們這次沒有辦法完成，那麼不僅所謂的社會改良家會來召喚，我們也將被認為沒本事在黑翼的排行內提升。$B$B這就是你想要的嗎?', `MaleText_loc7`='¡No quiero excusas, exijo resultados!$B$B¿Crees que lo estamos haciendo aquí es una broma? Si no lo hacemos bien, no solo vendrán los llamados bienhechores, sino que también se nos considerará indignos para la elevación en las filas de Alanegra.$B$B¿Es eso lo que quieres?' WHERE `ID`=19686;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음, 아니... 아닙니다. 결코 제가 바라는 바가 아니란 걸 아시잖아요?', `MaleText_loc4`='呃，不……不，我压根没想过。', `MaleText_loc5`='嗯，不...不，我一點都不想要那樣。', `MaleText_loc7`='Mm, no... no, no quiero eso en absoluto.', `FemaleText_loc1`='음, 아니... 아닙니다. 결코 제가 바라는 바가 아니란 걸 아시잖아요?', `FemaleText_loc4`='呃，不……不，我压根没想过。', `FemaleText_loc5`='嗯，不...不，我一點都不想要那樣。', `FemaleText_loc7`='Mm, no... no, no quiero eso en absoluto.' WHERE `ID`=19687;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좀 더 그럴듯한 변명 거리를 내놓아 보게.$B$B이봐, 누아르. 이런 얘기는 안 하려고 했는데, 어차피 자네도 연루될 테니 얘기하는 게 좋겠군. 막스나르가 루안 숲의 드루이드들에게 총공격을 계획하고 있네. 그는 이곳에서 그 세나리온 드루이드들을 완전히 몰아내고 싶어하지.$B$B우리는 볼더모크 오우거들과 싸우고 있기 때문에 전선이 확대되면 감당할 여력이 없네. 그래서 내가 루안 숲의 아라코아와 휴전 협정을 맺었지.$B$B자네 생각은 어떤가?', `MaleText_loc4`='你怎么着也应该说得可信一点吧。$B$B努埃尔，我原本不打算告诉你这件事的，但是你还是知道为好，因为你跟这件事扯上关系了。玛克纳尔正筹划着对卢安荒野的德鲁伊们发动一次全面进攻，并且把他们一网打尽。$B$B对我们来说，和砾石食人魔们战斗已经足够糟糕了，所以我们不能双线作战。我准备和鸦人签署短暂的停战协议。$B$B你觉得怎么样？', `MaleText_loc5`='你至少可以試著讓自己聽起來有說服力一點。$B$B聽著，奴阿爾，我本來不打算告訴你這事，但是我也有可能告訴你，因為它也與你有關。麥克斯納爾正在魯安曠野計畫對德魯伊做全面的攻擊。而且他打算徹底消滅他們。$B$B和圓面巨魔作戰已經夠糟的了，我們無法再對付另一個戰線。我已經與阿拉卡安排暫時停戰。$B$B那麼，你認為怎麼樣?', `MaleText_loc7`='Al menos podrías intentar sonar algo convincente.$B$BMira, Nuaar, no iba a decirte esto, pero quizás sea lo mejor, porque también va a involucrarte a ti. Maxnar planea un ataque total a los druidas de la Foresta Ruuan. Y pretende aniquilarlos.$B$BYa es lo malo que hayamos estado luchando contra los ogros Peña''mok, así que no podemos permitirnos tener que encargarnos de otro frente. He organizado una tregua temporal con los arakkoa.$B$BBueno, ¿qué opinas?' WHERE `ID`=19688;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대단하군요. 공격은 언제 합니까?', `MaleText_loc4`='太棒了。我们什么时候进攻？', `MaleText_loc5`='令人印象深刻。我們什麼時候攻擊?', `MaleText_loc7`='Impresionante. ¿Cuándo atacamos?', `FemaleText_loc1`='대단하군요. 공격은 언제 합니까?', `FemaleText_loc4`='太棒了。我们什么时候进攻？', `FemaleText_loc5`='令人印象深刻。我們什麼時候攻擊?', `FemaleText_loc7`='Impresionante. ¿Cuándo atacamos?' WHERE `ID`=19689;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 이 순간에도 최종 진격 준비가 진행되고 있네. 나머지는 자네가 루안 숲에서 얼마나 빨리 군대를 조직하느냐에 달렸네.$B$B빨리 끝낼 수 있을 것 같나?', `MaleText_loc4`='我们现在正紧锣密鼓地进行着最后的准备。剩下的就要看你能多快地组织起你在卢安荒野的力量了。$B$B你觉得你能迅速搞定这件事吗？', `MaleText_loc5`='就在我們講話時，我們正一起做最後的準備。剩下的就看你在魯安曠野能多快組織你的軍隊。$B$B你認為你能處理這些並快速完成嗎?', `MaleText_loc7`='Estamos organizando los preparativos definitivos mientras hablamos. El resto dependerá de con qué rapidez puedas organizar tus tropas en la Foresta Ruuan.$B$B¿Crees que puedes ocuparte de eso y tenerlo hecho rápidamente?' WHERE `ID`=19690;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론입니다!', `MaleText_loc4`='当然！', `MaleText_loc5`='沒問題!', `MaleText_loc7`='¡Por supuesto!', `FemaleText_loc1`='물론입니다!', `FemaleText_loc4`='当然！', `FemaleText_loc5`='沒問題!', `FemaleText_loc7`='¡Por supuesto!' WHERE `ID`=19691;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 바로 그 자세야!$B$B오늘 우리 회의는 아주 유익했네. 이제 공격 준비에 대해 한결 안심이 되는군. 자네 같은 감독관이 최전선에 버티고 있는데 우리가 어떻게 질 수 있겠나?$B$B좋아. 진격 명령을 내리도록 하지. 루안 숲으로 돌아가서 만반의 준비를 하도록!', `MaleText_loc4`='这就对了！$B$B这次小碰头会让我很高兴，我对进攻更有信心了。有你这样的领袖在前线，我们怎么可能输呢？$B$B好吧，这是你的行军令。返回卢安荒野，付诸实施吧！', `MaleText_loc5`='這就對了!$B$B我很高興我們有這個小會議。我現在對攻擊更有信心了。有你這樣的領導人在前線，我們怎麼會失敗?$B$B好了，你可以進軍了。現在回到魯安曠野開始攻擊吧!', `MaleText_loc7`='¡Esa es la actitud!$B$BMe alegro de que hayamos tenido esta breve reunión. Me siento mucho mejor con respecto al ataque ahora. Como líderes como tú en el frente, ¿cómo vamos a perder?$B$BBueno, ya tienes tus órdenes de marcha. ¡Ahora vuelve a la Foresta Ruuan y haz que suceda!' WHERE `ID`=19692;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='코로크, 어둠달 골짜기 거인들의 힘을 빌려주십시오. 주인님도 보통 통치자와 다르지 않습니다. 이 세계에서 반대 세력을 진압하는데 협조를 아끼지 않은 이들을 절대 모른 척하시진 않을 겁니다.', `FemaleText_loc4`='借给我们影月谷巨人的力量吧，考罗克。主人是非常公正的，他会善待那些在征服反对者的过程中给予他帮助的人。', `FemaleText_loc5`='借予我們影月巨人的力量，科羅克。主人是一位公正的統治者。他一定會照顧那些協助征服這個世界反抗者的人。', `FemaleText_loc7`='Danos la fuerza de los gigantes de Sombraluna, Corok. El maestro es un gobernante justo. Se asegurará de cuidar de aquellos que ayudaron a dominar a los disidentes de este mundo.' WHERE `ID`=19693;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 디멘시우스에게 힘을 전달하기 시작합니다.', `MaleText_loc4`='%s开始把能量引导入迪门修斯。', `MaleText_loc5`='%s開始引導能量進入迪曼修斯。', `MaleText_loc7`='%s comienza a canalizar energía hacia Dimensius.' WHERE `ID`=19694;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='만약... 우리가 협조하지 않는다면?', `MaleText_loc4`='那么……如果我们不这样呢？', `MaleText_loc5`='那麼...如果我們不這樣呢?', `MaleText_loc7`='Y... ¿si no lo hacemos?' WHERE `ID`=19695;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신은 나의 주인이신 일리단 님의 적이 되는 겁니다. 그러면 살아남을 수 없으리라는 사실은 알고 있겠지요? 과연 거인들이 해그늘 주둔지의 군대를 상대할 수 있을까요?', `FemaleText_loc4`='那么你就是伊利丹大人的敌人，而伊利丹的敌人都会灭亡。你的巨人能经受得住日蚀岗哨军队的进攻吗？', `FemaleText_loc5`='然後你成為我的主人，伊利丹的敵人。伊利丹的敵人被毀滅了。你的巨人們能抵擋來自日蝕崗哨的軍隊攻擊嗎?', `FemaleText_loc7`='Entonces os convertiréis en enemigos de mi señor, Illidan. Los enemigos de Illidan son destruidos. ¿Son capaces tus gigantes de resistir un ataque de las tropas de la Punta Eclipse?' WHERE `ID`=19696;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아마... 상대도 안 되겠지...', `FemaleText_loc4`='不……我不觉得可以……', `FemaleText_loc5`='不...我不這麼認為...', `FemaleText_loc7`='No... no lo pensaba...' WHERE `ID`=19697;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적들이 왔군! 안전한 장소에 있을 때 부르게나.', `MaleText_loc4`='敌人接近了！等你到达安全位置的时候再召唤我。', `MaleText_loc5`='敵人接近!等你到安全的位置時再召喚我。', `MaleText_loc7`='¡Se aproximan enemigos! Llámame cuando estés en un lugar seguro.', `FemaleText_loc1`='적들이 왔군! 안전한 장소에 있을 때 부르게나.', `FemaleText_loc4`='敌人接近了！等你到达安全位置的时候再召唤我。', `FemaleText_loc5`='敵人接近!等你到安全的位置時再召喚我。', `FemaleText_loc7`='¡Se aproximan enemigos! Llámame cuando estés en un lugar seguro.' WHERE `ID`=19698;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='원래부터 카라잔이 그렇게 불길한 느낌이 들만큼 조용한 곳은 아니었답니다. 카라잔의 운명에 암흑이 드리운 것은 메디브가 죽고 난 이후부터였습니다. 우리는 메디브가 죽었다고 믿었지요.', `FemaleText_loc4`='卡拉赞并非永远被厄运所笼罩。卡拉赞的黑暗是在麦迪文死后才降临的。或者说是我们认为如此。', `FemaleText_loc5`='卡拉贊並非總是十分...不祥。卡拉贊的黑暗轉變只會伴隨著麥迪文的死。或者說我們相信的是麥迪文的死。', `FemaleText_loc7`='Karazhan no fue siempre tan... siniestro. El oscurecimiento de Karazhan llegó solo con la muerte de Medivh. O con lo que creemos que fue la muerte de Medivh.' WHERE `ID`=19699;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사용 중', `MaleText_loc4`='使用', `MaleText_loc5`='使用中', `MaleText_loc7`='Utilizando', `FemaleText_loc1`='사용 중', `FemaleText_loc4`='使用', `FemaleText_loc5`='使用中', `FemaleText_loc7`='Utilizando' WHERE `ID`=19700;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자세를 똑바로 해라! 내 병사 중에 발자레크 님 앞에서 군기 빠진 모습을 보이는 자는 있을 수 없다!', `MaleText_loc4`='站直了！我不会让瓦萨雷克看到我的部队里还有那么懒散的士兵。', `MaleText_loc5`='整隊!在弗札克面前，我不能讓我的單位裡有如此不守紀律的士兵。', `MaleText_loc7`='¡Firmes! No toleraré soldados tan indisciplinados en mi unidad ante Val''zareq.', `FemaleText_loc1`='자세를 똑바로 해라! 내 병사 중에 발자레크 님 앞에서 군기 빠진 모습을 보이는 자는 있을 수 없다!', `FemaleText_loc4`='站直了！我不会让瓦萨雷克看到我的部队里还有那么懒散的士兵。', `FemaleText_loc5`='整隊!在弗札克面前，我不能讓我的單位裡有如此不守紀律的士兵。', `FemaleText_loc7`='¡Firmes! No toleraré soldados tan indisciplinados en mi unidad ante Val''zareq.' WHERE `ID`=19701;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발자레크 님 앞에서 내 명예에 해가 되는 행동은 절대 용납할 수 없다. 알아들었나?', `MaleText_loc4`='别在瓦萨雷克面前羞辱我。明白吗？', `MaleText_loc5`='在弗札克面前你不准侮辱我。夠清楚嗎?', `MaleText_loc7`='No harás nada que me deshonre ante Val''zareq. ¿Queda claro?', `FemaleText_loc1`='발자레크 님 앞에서 내 명예에 해가 되는 행동은 절대 용납할 수 없다. 알아들었나?', `FemaleText_loc4`='别在瓦萨雷克面前羞辱我。明白吗？', `FemaleText_loc5`='在弗札克面前你不准侮辱我。夠清楚嗎?', `FemaleText_loc7`='No harás nada que me deshonre ante Val''zareq. ¿Queda claro?' WHERE `ID`=19702;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘하고 있다. 그대로 계속해라!', `MaleText_loc4`='你做得很好。继续保持！', `MaleText_loc5`='你做的很好。保持下去!', `MaleText_loc7`='Lo estás haciendo bien. ¡Sigue así!', `FemaleText_loc1`='잘하고 있다. 그대로 계속해라!', `FemaleText_loc4`='你做得很好。继续保持！', `FemaleText_loc5`='你做的很好。保持下去!', `FemaleText_loc7`='Lo estás haciendo bien. ¡Sigue así!' WHERE `ID`=19703;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 알겠습니다!', `MaleText_loc4`='遵命！', `MaleText_loc5`='好的，長官!', `MaleText_loc7`='¡Señor, sí, señor!', `FemaleText_loc1`='네, 알겠습니다!', `FemaleText_loc4`='遵命！', `FemaleText_loc5`='好的，長官!', `FemaleText_loc7`='¡Señor, sí, señor!' WHERE `ID`=19704;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분부대로 하겠습니다!', `MaleText_loc4`='遵命，长官！', `MaleText_loc5`='聽你差遣，長官!', `MaleText_loc7`='¡A sus órdenes, señor!', `FemaleText_loc1`='분부대로 하겠습니다!', `FemaleText_loc4`='遵命，长官！', `FemaleText_loc5`='聽你差遣，長官!', `FemaleText_loc7`='¡A sus órdenes, señor!' WHERE `ID`=19705;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절대 실망시키지 않겠습니다!', `MaleText_loc4`='我们不会令阁下失望的！', `MaleText_loc5`='我們不會令你失望，長官!', `MaleText_loc7`='¡No le fallaremos, señor!', `FemaleText_loc1`='절대 실망시키지 않겠습니다!', `FemaleText_loc4`='我们不会令阁下失望的！', `FemaleText_loc5`='我們不會令你失望，長官!', `FemaleText_loc7`='¡No le fallaremos, señor!' WHERE `ID`=19706;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런트여, 너무 멀리까지 왔군. 이제 되돌아갈 방법은 없소.', `MaleText_loc4`='事情到了这一步，我们已经不能回头了。', `MaleText_loc5`='你已經走了這麼遠，哼哼。現在不可能回頭了。', `MaleText_loc7`='Has llegado hasta aquí, bruto. Ya no puedes volver atrás.' WHERE `ID`=19707;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코르크론 신호용 권총을 잃어 버렸는데 새로 하나 얻을 수 있을까요?', `MaleText_loc4`='我把库卡隆信号枪弄丢了。能再给我一把吗？', `MaleText_loc5`='我弄丟了我的柯爾克隆信號槍，先生。可以再給我一支嗎?', `MaleText_loc7`='He perdido mi pistola de bengalas de Kor''kron, señor. ¿Puedo tener otra?', `FemaleText_loc1`='코르크론 신호용 권총을 잃어 버렸는데 새로 하나 얻을 수 있을까요?', `FemaleText_loc4`='我把库卡隆信号枪弄丢了。能再给我一把吗？', `FemaleText_loc5`='我弄丟了我的柯爾克隆信號槍，先生。可以再給我一支嗎?', `FemaleText_loc7`='He perdido mi pistola de bengalas de Kor''kron, señor. ¿Puedo tener otra?' WHERE `ID`=19708;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 인내심의 한계를 시험하는군. 당신 가방 속에 새 신호용 권총을 넣었으니 이젠 잃어버리지 마시오!', `MaleText_loc4`='我对你越来越没耐心了，步兵。我又在你的包裹里放了一把新的信号枪。嗯？为什么要说“又”呢？这次别再弄丢了！', `MaleText_loc5`='你在考驗我的耐性，哼哼。我已經把新的信號槍放在你的背包裡了。試著不要弄丟這支!', `MaleText_loc7`='Estás agotando mi paciencia, bruto. He metido la nueva pistola de bengalas en tu talega. ¡Intenta no perder esta!' WHERE `ID`=19709;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고룡교단 검은새끼용이 그물에 걸려 무기력하게 누워 있습니다.', `MaleText_loc4`='拜龙教的黑色龙崽无助地躺在网里。', `MaleText_loc5`='巨龍教團黑色幼龍被網住而無助的躺在這裡。', `MaleText_loc7`='La cría negra Culto Vermis yace aquí, atrapada e indefensa.' WHERE `ID`=19710;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고룡교단 검은새끼용 잡기', `MaleText_loc4`='收集拜龙教黑色龙崽。', `MaleText_loc5`='收集巨龍教團黑色幼龍。', `MaleText_loc7`='Recoge la cría negra Culto Vermis.', `FemaleText_loc1`='고룡교단 검은새끼용 잡기', `FemaleText_loc4`='收集拜龙教黑色龙崽。', `FemaleText_loc5`='收集巨龍教團黑色幼龍。', `FemaleText_loc7`='Recoge la cría negra Culto Vermis.' WHERE `ID`=19711;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘이 빠진 고룡교단 검은새끼용을 재빨리 가방에 넣습니다.', `MaleText_loc4`='你迅速将被驯服的幼崽放入包内。', `MaleText_loc5`='你迅速地把被制服的幼龍放進你的背包裡。', `MaleText_loc7`='Te metes rápidamente la mansa cría en la talega.' WHERE `ID`=19712;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오십시오, 감독관님. 공격 준비는 됐습니까?', `MaleText_loc4`='嗨，监工。准备好发动攻击了吗？', `MaleText_loc5`='嗨，監督者。準備好戰鬥了嗎?', `MaleText_loc7`='Hola, sobrestante. ¿$gPreparado:Preparada; para el ataque?', `FemaleText_loc1`='어서 오십시오, 감독관님. 공격 준비는 됐습니까?', `FemaleText_loc4`='嗨，监工。准备好发动攻击了吗？', `FemaleText_loc5`='嗨，監督者。準備好戰鬥了嗎?', `FemaleText_loc7`='Hola, sobrestante. ¿$gPreparado:Preparada; para el ataque?' WHERE `ID`=19713;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감독관님, 필요하신 거라도 있으신가요?', `MaleText_loc4`='您需要什么吗，长官？', `MaleText_loc5`='你需要什麼嗎，主人?', `MaleText_loc7`='¿Hay algo que necesite, señor?', `FemaleText_loc1`='감독관님, 필요하신 거라도 있으신가요?', `FemaleText_loc4`='您需要什么吗，长官？', `FemaleText_loc5`='你需要什麼嗎，主人?', `FemaleText_loc7`='¿Hay algo que necesite, señor?' WHERE `ID`=19714;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='몸이 안 좋아 보이시는군요, 감독관님.', `MaleText_loc4`='你看上去气色不好，监工。', `MaleText_loc5`='你看起來不太好，監督者。', `MaleText_loc7`='No tienes buen aspecto, sobrestante.', `FemaleText_loc1`='몸이 안 좋아 보이시는군요, 감독관님.', `FemaleText_loc4`='你看上去气色不好，监工。', `FemaleText_loc5`='你看起來不太好，監督者。', `FemaleText_loc7`='No tienes buen aspecto, sobrestante.' WHERE `ID`=19715;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='콜피스 다크스케일이 당신을 찾는다고 들었습니다.', `MaleText_loc4`='我听说库尔菲斯·暗鳞一直在找你。', `MaleText_loc5`='我聽說克菲斯·暗鱗一直在找你。', `MaleText_loc7`='He oído que Kolphis Rangoscuro te ha estado buscando.', `FemaleText_loc1`='콜피스 다크스케일이 당신을 찾는다고 들었습니다.', `FemaleText_loc4`='我听说库尔菲斯·暗鳞一直在找你。', `FemaleText_loc5`='我聽說克菲斯·暗鱗一直在找你。', `FemaleText_loc7`='He oído que Kolphis Rangoscuro te ha estado buscando.' WHERE `ID`=19716;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사미아, 혹시 콜피스 다크스케일이 누군지 아시오?', `MaleText_loc4`='萨米亚，你知道谁是库尔菲斯·暗鳞吗？', `MaleText_loc5`='沙彌亞，你知道克菲斯·暗鱗是誰嗎?', `MaleText_loc7`='Samia, ¿sabes quién es Kolphis Rangoscuro?' WHERE `ID`=19717;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그는 서쪽에 있는 검은날개 소굴의 고룡교단의 부사령관이에요.', `FemaleText_loc4`='嗯，他是拜龙教的人，西边黑翼集会所的副指挥。', `FemaleText_loc5`='是的，他是西邊黑翼集會所的巨龍教團副指揮。', `FemaleText_loc7`='Sí, es el segundo de a bordo del Culto Vermis en el Aquelarre Ala Negra, al oeste.' WHERE `ID`=19718;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드루이드들은 엄청난 힘의 원천을 뽑아냈어요! 그들은 동물로 변신할 수 있고... 번개와 강렬한 달빛을 쏠 수도 있죠. 저는 그들이 가진 능력의 비밀을 밝혀내고야 말 거예요!$B$B혹시 로브 안에 충전지를 착용하고 있는지도 몰라요...', `MaleText_loc4`='这些德鲁伊好像有一个巨大的能量源！他们可以变成动物……放射出闪电和强烈的月光……我必须要弄清楚他们是怎么做到这些的！$B$B也许他们的长袍下绑着蓄电池……', `MaleText_loc5`='這些德魯伊已開發了驚人的力量來源!他們可以變成動物...投射閃電和強烈的月光...我必須知道他們怎麼辦到的!$B$B也許他們的長袍下都戴著電池...', `MaleText_loc7`='¡Esos druidas han explotado una tremenda fuente de energía! Se pueden convertir en animales... proyectar relámpagos y luz lunar intensa... ¡Debo descubrir cómo lo hacen!$B$BQuizás llevan cargas bajo la toga...' WHERE `ID`=19719;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번 비행에서 탈리가 연료 문제를 해결할 때까지는 축전장치에 추가 연료가 좀 필요할 겁니다. 5개 부대가 그 일을 해야만 합니다!', `MaleText_loc4`='在塔雷弄好飞行操作指南前，电容器还需要更多的燃料。5组应该够了！', `MaleText_loc5`='在塔利解決掉此次飛行的問題之前，ZC號將需要更多的燃料。5個單位的燃料應該就夠了!', `MaleText_loc7`='Hasta que Tally no resuelva los problemas menores de este vuelo, el Capacitorium necesitará algo de combustible adicional. ¡Cinco unidades deberían bastar!' WHERE `ID`=19720;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저한테 연료가 있습니다! 절 까마귀 숲으로 데려다 주십시오.', `MaleText_loc4`='我有燃料！带我去乌鸦林。', `MaleText_loc5`='我有燃料! 帶我到烏鴉林。', `MaleText_loc7`='¡Tengo el combustible! Llévame al Bosque del Cuervo.', `FemaleText_loc1`='저한테 연료가 있습니다! 절 까마귀 숲으로 데려다 주십시오.', `FemaleText_loc4`='我有燃料！带我去乌鸦林。', `FemaleText_loc5`='我有燃料! 帶我到烏鴉林。', `FemaleText_loc7`='¡Tengo el combustible! Llévame al Bosque del Cuervo.' WHERE `ID`=19721;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<얼빠진 표정으로 당신을 맞이하며 위아래로 훑어보는 아라코아>$B$B우리의 노력이 결실을 거둔 것 같기는 한데 우리가 막으려는 것보다 훨씬 끔찍한 생물인가요?', `MaleText_loc4`='<鸦人用诡异的眼神上下打量着你。>$B$B我们的努力非但没有结果，怎么反而还招来了一个新的怪物？', `MaleText_loc5`='<阿拉卡不停地注視著你，並且在注視你和透視你之間來回交替。>$B$B是什麼讓我們努力工作，但又比我們想阻止的憎恨更龐大?', `MaleText_loc7`='<El arakkoa te dedica una mirada fija y encantada, y alterna entre mirarte y mirar a través de ti.>$B$B¿Qué han provocado nuestros esfuerzos, aparte de una abominación mayor que la que intentábamos evitar?' WHERE `ID`=19722;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='2007년 2월 16일까지 초읽기: $4262d일$B순수 날짜: $4262e', `MaleText_loc4`='Countdown to February 16th, 2007: $4262d$BRaw number: $4262e', `MaleText_loc5`='倒數計時至2007年2月16日︰$4262d$B原始編碼︰$4262e', `MaleText_loc7`='Cuenta atrás hasta el 16 de febrero de 2007: $4262d$BNúmero en bruto: $4262e' WHERE `ID`=19723;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 군대는 폭풍의 눈을 차지하고자 여기 아웃랜드에서 호드를 상대로 전투를 벌이고 있습니다. 물론 격렬한 황천의 에너지 속에서 싸우는 일은 위험하지요. 당신은 우리와 함께할 자질을 갖추고 있습니까?', `MaleText_loc4`='在外域，为了争夺风暴之眼的控制权，我们与部落展开了激烈的战斗。在虚空的狂暴能量之间战斗是很危险的。你是否想加入我们呢？', `MaleText_loc5`='在外域這裡，我們的部隊與部落戰鬥以控制暴風之眼。在虛空的狂怒能量中戰鬥是危險的。你有那個能力加入我們嗎?', `MaleText_loc7`='En Terrallende nuestras tropas luchan contra la Horda para controlar el Ojo de la Tormenta. Es peligroso luchar entre las fieras energías del Vacío. ¿Tienes lo que hay que tener para unirte a nosotros?', `FemaleText_loc1`='우리 군대는 폭풍의 눈을 차지하고자 여기 아웃랜드에서 호드를 상대로 전투를 벌이고 있습니다. 물론 격렬한 황천의 에너지 속에서 싸우는 일은 위험하지요. 당신은 우리와 함께할 자질을 갖추고 있습니까?', `FemaleText_loc4`='在外域，为了争夺风暴之眼的控制权，我们与部落展开了激烈的战斗。在虚空的狂暴能量之间战斗是很危险的。你是否想加入我们呢？', `FemaleText_loc5`='在外域這裡，我們的部隊與部落戰鬥以控制暴風之眼。在虛空的狂怒能量中戰鬥是危險的。你有那個能力加入我們嗎?', `FemaleText_loc7`='En Terrallende nuestras tropas luchan contra la Horda para controlar el Ojo de la Tormenta. Es peligroso luchar entre las fieras energías del Vacío. ¿Tienes lo que hay que tener para unirte a nosotros?' WHERE `ID`=19724;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭풍의 눈의 마나 저장고는 매우 귀중한 자원이오. 드레나이에게 뺏길 수는 없지! 거기, 잠시만! 우리의 싸움에 동참해서 그대의 가치를 증명해 보이시오!', `MaleText_loc4`='风暴之眼中的魔法晶格非常珍贵，我们不能把它们拱手送给德莱尼人！你！协助我们作战吧！在战火中证明你的价值！', `MaleText_loc5`='暴風之眼裡的法力電池是一件寶貴的東西;我們不能讓德萊尼得到它們!喂!展現你的用處並在戰鬥中幫助我們吧!', `MaleText_loc7`='Las células de maná que hay en el interior del Ojo de la Tormenta son muy valiosas. ¡No podemos permitirnos perderlas y que los draenei las encuentren! ¡Eh, tú! ¡Haz algo útil y ayúdanos en la lucha!', `FemaleText_loc1`='폭풍의 눈의 마나 저장고는 매우 귀중한 자원이오. 드레나이에게 뺏길 수는 없지! 거기, 잠시만! 우리의 싸움에 동참해서 그대의 가치를 증명해 보이시오!', `FemaleText_loc4`='风暴之眼中的魔法晶格非常珍贵，我们不能把它们拱手送给德莱尼人！你！协助我们作战吧！在战火中证明你的价值！', `FemaleText_loc5`='暴風之眼裡的法力電池是一件寶貴的東西;我們不能讓德萊尼得到它們!喂!展現你的用處並在戰鬥中幫助我們吧!', `FemaleText_loc7`='Las celdas de maná que hay en el interior del Ojo de la Tormenta mana son muy valiosas. ¡No podemos permitirnos perderlas y que los draenei las encuentren! ¡Eh, tú! ¡Haz algo útil y ayúdanos en la lucha!' WHERE `ID`=19725;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n! 어서 오게! 아제로스의 알터랙 계곡에서 피 튀기는 싸움이 벌어지고 있다는 소식은 자네도 들어봤겠지. 우리는 뛰어난 용사들을 소집하고 있네. 스톰파이크 경비대와 함께 서리늑대 부족을 물리쳐 주게!', `MaleText_loc4`='$n！过来！相信你肯定听说过艾泽拉斯大陆上著名的奥特兰克山谷吧。我们需要集合所有强壮的士兵，与雷矛卫兵一起击败霜狼氏族！', `MaleText_loc5`='$n!過來這裡!你一定知道艾澤拉斯的奧特蘭克山谷內進行著激烈的戰鬥。我們需要每一位能召集的健壯戰士。與雷矛守衛作戰並且擊敗霜狼!', `MaleText_loc7`='¡$n! ¡Ven aquí! Sin duda sabes de la batalla que tiene lugar en el Valle de Alterac, en Azeroth. Necesitamos a cualquier combatiente capacitado que podamos reunir. ¡Lucha contra la Guardia Pico Tormenta y vence a los Lobo Gélido!', `FemaleText_loc1`='$n! 어서 오게! 아제로스의 알터랙 계곡에서 피 튀기는 싸움이 벌어지고 있다는 소식은 자네도 들어봤겠지. 우리는 뛰어난 용사들을 소집하고 있네. 스톰파이크 경비대와 함께 서리늑대 부족을 물리쳐 주게!', `FemaleText_loc4`='$n！过来！相信你肯定听说过艾泽拉斯大陆上著名的奥特兰克山谷吧。我们需要集合所有强壮的士兵，与雷矛卫兵一起击败霜狼氏族！', `FemaleText_loc5`='$n!過來這裡!你一定知道艾澤拉斯的奧特蘭克山谷內進行著激烈的戰鬥。我們需要每一位能召集的健壯戰士。與雷矛守衛作戰並且擊敗霜狼!', `FemaleText_loc7`='¡$n! ¡Ven aquí! Sin duda sabes de la batalla que tiene lugar en el Valle de Alterac, en Azeroth. Necesitamos a cualquier combatiente capacitado que podamos reunir. ¡Lucha contra el Guardia Pico Tormenta y vence a los Lobo Gélido!' WHERE `ID`=19726;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 비행의 착륙 장소는 멀리 노래하는 마루입니다. 매우 위험한 비행이죠!$B$B이런 비행에는 서명된 각서를 받아둬야 하는데...', `MaleText_loc4`='这次飞行将把你带到远方的晶歌山脉。那里是非常危险的！$B$B正因为如此，我需要你签一份免责声明……', `MaleText_loc5`='這次飛行將帶你到美聲山脊較遠的地方。非常危險!$B$B因此，我將要需要一張已簽署的棄權證明書...', `MaleText_loc7`='Este vuelo te lleva al punto remoto de Cresta Canto. ¡Muy peligroso!$B$BPor esto, voy a tener que necesitar una renuncia firmada...' WHERE `ID`=19727;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서명된 각서를 가지고 있습니다! 노래하는 마루로 보내 주십시오!', `MaleText_loc4`='我已经签署免责声明了！把我发射到晶歌山脉去吧！', `MaleText_loc5`='我有已簽署的棄權證明書!將我發射至美聲山脊!', `MaleText_loc7`='¡Tengo la renuncia firmada! ¡Lánzame a Cresta Canto!', `FemaleText_loc1`='서명된 각서를 가지고 있습니다! 노래하는 마루로 보내 주십시오!', `FemaleText_loc4`='我已经签署免责声明了！把我发射到晶歌山脉去吧！', `FemaleText_loc5`='我有已簽署的棄權證明書!將我發射至美聲山脊!', `FemaleText_loc7`='¡Tengo la renuncia firmada! ¡Lánzame a Cresta Canto!' WHERE `ID`=19728;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뾰족 마루로 보내 주십시오.', `MaleText_loc4`='送我回到锯齿山。', `MaleText_loc5`='送我回鋸齒山脊。', `MaleText_loc7`='Devuélveme a la Cresta Dentada.', `FemaleText_loc1`='뾰족 마루로 보내 주십시오.', `FemaleText_loc4`='送我回到锯齿山。', `FemaleText_loc5`='送我回鋸齒山脊。', `FemaleText_loc7`='Devuélveme a la Cresta Dentada.' WHERE `ID`=19729;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노래하는 마루로 보내 주십시오.', `MaleText_loc4`='把我送回晶歌山脉。', `MaleText_loc5`='送我回美聲山脊。', `MaleText_loc7`='Devuélveme a Cresta Canto.', `FemaleText_loc1`='노래하는 마루로 보내 주십시오.', `FemaleText_loc4`='把我送回晶歌山脉。', `FemaleText_loc5`='送我回美聲山脊。', `FemaleText_loc7`='Devuélveme a Cresta Canto.' WHERE `ID`=19730;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라잔의 영지으로 보내 주십시오.', `MaleText_loc4`='送我回到拉扎安码头。', `MaleText_loc5`='送我回雷森平台。', `MaleText_loc7`='Devuélveme a la Zona de Aterrizaje de Razaan.', `FemaleText_loc1`='라잔의 영지으로 보내 주십시오.', `FemaleText_loc4`='送我回到拉扎安码头。', `FemaleText_loc5`='送我回雷森平台。', `FemaleText_loc7`='Devuélveme a la Zona de Aterrizaje de Razaan.' WHERE `ID`=19731;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='루안 숲으로 보내 주십시오.', `MaleText_loc4`='把我送回卢安荒野。', `MaleText_loc5`='送我回魯安曠野。', `MaleText_loc7`='Devuélveme a la Foresta Ruuan.', `FemaleText_loc1`='루안 숲으로 보내 주십시오.', `FemaleText_loc4`='把我送回卢安荒野。', `FemaleText_loc5`='送我回魯安曠野。', `FemaleText_loc7`='Devuélveme a la Foresta Ruuan.' WHERE `ID`=19732;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='까마귀 숲으로 보내 주십시오.', `MaleText_loc4`='送我回到乌鸦林。', `MaleText_loc5`='送我回烏鴉林。', `MaleText_loc7`='Devuélveme al Bosque del Cuervo.', `FemaleText_loc1`='까마귀 숲으로 보내 주십시오.', `FemaleText_loc4`='送我回到乌鸦林。', `FemaleText_loc5`='送我回烏鴉林。', `FemaleText_loc7`='Devuélveme al Bosque del Cuervo.' WHERE `ID`=19733;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 늘 더 많은 시험 비행 자료가 필요하답니다! 어디로 가고 싶으세요?', `MaleText_loc4`='我们永远渴望得到更多的飞行资料！你想去哪里？', `MaleText_loc5`='我們總渴望更多的飛行數據!你想去哪裡?', `MaleText_loc7`='¡Siempre codiciamos más datos de vuelo! ¿Dónde quieres ir?' WHERE `ID`=19734;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전에 갔던 지역으로 가고 싶습니다!', `MaleText_loc4`='我想飞回曾经去过的地方！', `MaleText_loc5`='我想飛往老地方!', `MaleText_loc7`='¡Quiero volar a un lugar antiguo!', `FemaleText_loc1`='전에 갔던 지역으로 가고 싶습니다!', `FemaleText_loc4`='我想飞回曾经去过的地方！', `FemaleText_loc5`='我想飛往老地方!', `FemaleText_loc7`='¡Quiero volar a un lugar antiguo!' WHERE `ID`=19735;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 방패를 들어올려 강력하게 방어합니다!', `MaleText_loc4`='%s举起了他的盾牌，进入了防御状态！', `MaleText_loc5`='%s舉起他的護盾，強而有力的防禦!', `MaleText_loc7`='¡%s alza su escudo en defensa enérgica!', `FemaleText_loc1`='%s|1이;가; 방패를 들어올려 강력하게 방어합니다!', `FemaleText_loc4`='%s举起了他的盾牌，进入了防御状态！', `FemaleText_loc5`='%s舉起他的護盾，強而有力的防禦!', `FemaleText_loc7`='¡%s alza su escudo en defensa enérgica!' WHERE `ID`=19736;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일리단, 감히 내 아이들을 공격하다니! 협정은 깨졌다. 우리는 엘프의 편에 서지 않을 것이다! 절대로!', `MaleText_loc4`='啊啊啊！你居然袭击了我的孩子，伊利丹！我们之间的盟约完了，巨人与精灵誓不两立！誓不两立！', `MaleText_loc5`='你已經輕率地攻擊了我的孩子，伊利丹!約定中止。巨人絕不會與精靈站在同一陣線!絕不!', `MaleText_loc7`='¡Has atacado a mis hijos descaradamente, Illidan! El pacto queda roto. ¡Los gigantes nunca se pondrán del lado de los elfos! ¡NUNCA!' WHERE `ID`=19737;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 비전 에너지를 시전하기 시작합니다...', `MaleText_loc4`='%s开始引导奥术能量……', `MaleText_loc5`='%s開始引導秘法能量...', `MaleText_loc7`='%s comienza a canalizar energía arcana...' WHERE `ID`=19738;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 완강하게 저항하며 울부짖습니다.', `MaleText_loc4`='%s挑衅地咆哮着。', `MaleText_loc5`='%s反抗的怒吼。', `MaleText_loc7`='%s ruge, desafiante.' WHERE `ID`=19739;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='깊숙한 곳에서부터 거대한 톱니바퀴 돌아가는 소리가 들립니다...', `MaleText_loc4`='你听到了从深处传来的齿轮转动声……', `MaleText_loc5`='你聽見深淵底下巨大齒輪攪動生命的聲音...', `MaleText_loc7`='Oyes el sonido de una enorme maquinaria agitándose bajo las profundidades...' WHERE `ID`=19740;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동굴 속에서 문이 열리는 희미한 소리가 들립니다.', `MaleText_loc4`='你听到山洞中传来了微弱的开锁声。', `MaleText_loc5`='你在洞穴裡聽到一扇門被開啟的微弱聲音。', `MaleText_loc7`='Oyes el débil sonido de una puerta que se abre en la cueva.' WHERE `ID`=19741;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일입니까? 새로운 정보를 얻었습니까?', `MaleText_loc4`='怎么样了，$r？你有什么新的消息吗？', `MaleText_loc5`='哪是什麼，$r?你蒐集到一些新的資訊了嗎?', `MaleText_loc7`='¿Qué sucede, $r? ¿Has reunido información nueva?', `FemaleText_loc1`='무슨 일입니까? 새로운 정보를 얻었습니까?', `FemaleText_loc4`='怎么样了，$r？你有什么新的消息吗？', `FemaleText_loc5`='哪是什麼，$r?你蒐集到一些新的資訊了嗎?', `FemaleText_loc7`='¿Qué sucede, $r? ¿Has reunido información nueva?' WHERE `ID`=19742;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적의 공격입니다! 방어하십시오! 저는 이 주변을 날고 있을 테니 방해하는 무리가 없을 때 다시 불러주십시오!', `MaleText_loc4`='我们被袭击了！保护好你自己！天上更安全一些，我先撤了。等海岸安全了之后再叫我回来吧！', `MaleText_loc5`='我們被攻擊了!保護你自己!我要走捷徑。當海岸淨空時叫我回來!', `MaleText_loc7`='¡Nos atacan! ¡Defiéndete! Tomaré el camino más rápido. ¡Llámame cuando no haya moros en la costa!', `FemaleText_loc1`='적의 공격입니다! 방어하십시오! 저는 이 주변을 날고 있을 테니 방해하는 무리가 없을 때 다시 불러주십시오!', `FemaleText_loc4`='我们被袭击了！保护好你自己！天上更安全一些，我先撤了。等海岸安全了之后再叫我回来吧！', `FemaleText_loc5`='我們被攻擊了!保護你自己!我要走捷徑。當海岸淨空時叫我回來!', `FemaleText_loc7`='¡Nos atacan! ¡Defiéndete! Tomaré el camino más rápido. ¡Llámame cuando no haya moros en la costa!' WHERE `ID`=19743;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너는 절대 격노의 심장을 가질 수 없다! 그 힘은 일리단 님의 것이다!', `MaleText_loc4`='你永远都别想得到愤怒之心！那是属于伊利丹大人的！', `MaleText_loc5`='你將永遠得不到狂怒之心!它的能量是屬於伊利丹的!', `MaleText_loc7`='¡Nunca tendrás el corazón de furia! ¡Su poder pertenece a Illidan!' WHERE `ID`=19744;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='각서가 한 장 더 필요합니다!', `MaleText_loc4`='我需要另一份免责声明！', `MaleText_loc5`='我需要另一張棄權證書!', `MaleText_loc7`='¡Necesito otra renuncia!', `FemaleText_loc1`='각서가 한 장 더 필요합니다!', `FemaleText_loc4`='我需要另一份免责声明！', `FemaleText_loc5`='我需要另一張棄權證書!', `FemaleText_loc7`='¡Necesito otra renuncia!' WHERE `ID`=19745;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭔가? 바쁜 거 안 보이나?', `MaleText_loc4`='又怎么了？你没看到我正在忙吗？', `MaleText_loc5`='什麼事?你看不出來我是一個忙碌的矮人嗎?', `MaleText_loc7`='¿Entonces, qué es? ¿No ves que soy un enano ocupado?' WHERE `ID`=19746;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영주님, 와일드해머 신호용 권총이 하나 더 필요합니다.', `MaleText_loc4`='我需要一把新的蛮锤信号枪。', `MaleText_loc5`='我需要另一支蠻錘信號槍，男爵。', `MaleText_loc7`='Necesito otra pistola de bengalas de Martillo Salvaje, Señor feudal.', `FemaleText_loc1`='영주님, 와일드해머 신호용 권총이 하나 더 필요해요.', `FemaleText_loc4`='我需要一把新的蛮锤信号枪。', `FemaleText_loc5`='我需要另一支蠻錘信號槍，男爵。', `FemaleText_loc7`='Necesito otra pistola de bengalas de Martillo Salvaje, Thane.' WHERE `ID`=19747;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알았네, 제군. 자네 가방 안에 넣어 두었네. 이번에는 잃어버리지 말게!', `MaleText_loc4`='好了，士兵。新的信号枪已经装到你的包里了，不要再把它弄丢了。', `MaleText_loc5`='交易完成，士兵。替換的信號槍在你的包包裡。不要遺失!', `MaleText_loc7`='Está hecho, soldado. La pistola de bengalas de repuesto está en tu talega. ¡No la pierdas!' WHERE `ID`=19748;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽어, 벌레들아!', `MaleText_loc4`='受死吧，虫子们！', `MaleText_loc5`='死吧，小蟲們!', `MaleText_loc7`='¡Morid, gusanos!' WHERE `ID`=19749;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 미지의 땅을 탐험하는 것도 중요하지만 아제로스를 버려서는 안 됩니다! 파멸단과 싸움에서 승리하려면 그 어느 때보다도 당신의 도움이 절실하게 필요합니다. 아라시의 자원들을 안전하게 지켜야 합니다!', `MaleText_loc4`='在新大陆的探索无疑非常重要，但是你不能遗忘艾泽拉斯！我们比以前更加需要你去和污染者作战！那些资源需要得到保护！', `MaleText_loc5`='雖然探索這些新土地無疑是重要的，但你不可遺棄艾澤拉斯!我們現在比從前和那些污染者對抗時更需要你。那些資源必須被妥善保護!', `MaleText_loc7`='Aunque explorar estas nuevas tierras es, sin duda, importante, ¡no debes abandonar Azeroth! Te necesitamos más que nunca en la lucha contra los Rapiñadores. ¡Hay que proteger esos recursos!', `FemaleText_loc1`='이 미지의 땅을 탐험하는 것도 중요하지만 아제로스를 버려서는 안 됩니다! 파멸단과 싸움에서 승리하려면 그 어느 때보다도 당신의 도움이 절실하게 필요합니다. 아라시의 자원들을 안전하게 지켜야 합니다!', `FemaleText_loc4`='在新大陆的探索无疑非常重要，但是你不能遗忘艾泽拉斯！我们比以前更加需要你去和污染者作战！那些资源需要得到保护！', `FemaleText_loc5`='雖然探索這些新土地無疑是重要的，但你不可遺棄艾澤拉斯!我們現在比從前和那些污染者對抗時更需要你。那些資源必須被妥善保護!', `FemaleText_loc7`='Aunque explorar estas nuevas tierras es, sin duda, importante, ¡no debes abandonar Azeroth! Te necesitamos más que nunca en la lucha contra los Rapiñadores. ¡Hay que proteger esos recursos!' WHERE `ID`=19750;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠시만요! 도움이 필요해요! 야만적인 전쟁노래 오크들이 잿빛 골짜기의 신비와 아름다움을 파괴하고 있습니다. 전장에 나가 적과 맞서주십시오. 아제로스로 돌아가서 은빛날개 파수대의 명예를 위해 싸워주십시오! 도와주시겠습니까?', `MaleText_loc4`='嗨，$C！我们需要你的帮助！战歌氏族的那些野蛮兽人正在破坏风景如画的灰谷，我们希望你能在战场上跟这帮家伙一较高下。跟我们返回艾泽拉斯世界，为了银翼哨兵的荣耀而战！好吗？', `MaleText_loc5`='你，$c!我們需要你的幫助!粗暴的戰歌獸人正在破壞梣谷的奇蹟和美景，我們需要你的力量在戰場上對抗他們。與我們一起回到艾澤拉斯，為銀翼哨兵的榮譽而戰鬥!你願意加入我們嗎?', `MaleText_loc7`='¡Tú, $c! ¡Necesitamos tu ayuda! Los toscos orcos Grito de Guerra están destruyendo las maravillas y la belleza de Vallfresno, y necesitamos tu fuerza para enfrentarnos a ellos en el campo de batalla. ¡Vuelve con nosotros a Azeroth y lucha por el honor de los centinelas Ala de Plata! ¿Te unirás a nosotros?', `FemaleText_loc1`='잠시만요! 도움이 필요해요! 야만적인 전쟁노래 오크들이 잿빛 골짜기의 신비와 아름다움을 파괴하고 있습니다. 전장에 나가 적과 맞서주십시오. 아제로스로 돌아가서 은빛날개 파수대의 명예를 위해 싸워주십시오! 도와주시겠습니까?', `FemaleText_loc4`='嗨，$C！我们需要你的帮助！战歌氏族的那些野蛮兽人正在破坏风景如画的灰谷，我们希望你能在战场上跟这帮家伙一较高下。跟我们返回艾泽拉斯世界，为了银翼哨兵的荣耀而战！好吗？', `FemaleText_loc5`='你，$c!我們需要你的幫助!粗暴的戰歌獸人正在破壞梣谷的奇蹟和美景，我們需要你的力量在戰場上對抗他們。與我們一起回到艾澤拉斯，為銀翼哨兵的榮譽而戰鬥!你願意加入我們嗎?', `FemaleText_loc7`='¡Tú, $c! ¡Necesitamos tu ayuda! Los toscos orcos Grito de Guerra están destruyendo las maravillas y la belleza de Vallfresno, y necesitamos tu fuerza para enfrentarnos a ellos en el campo de batalla. ¡Vuelve con nosotros a Azeroth y lucha por el honor de los centinelas Ala de Plata! ¿Te unirás a nosotros?' WHERE `ID`=19751;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래... 무슨 일이오? 바쁜 게 안 보이시오?', `MaleText_loc4`='嗯……你想要什么，$r？你没看到我这里正忙着吗？', `MaleText_loc5`='是的... 你想要什麼，$r?你沒看到我在這裡忙嗎?', `MaleText_loc7`='Sí... ¿qué quieres, $r? ¿No ves que estoy ocupado?' WHERE `ID`=19752;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 속담이 있지. "물고기를 잡아주면 하루밖에 못 먹이지만 낚시하는 법을 가르쳐 주면 평생을 먹일 수 있다." 물론 당신은 그 생선을 요리하고 싶겠지? 요리야말로 내 전공이라고 할 수 있소.', `MaleText_loc4`='古语说得好，“授人以鱼，不如授之以渔，授人以鱼只救一时之急，授人以渔则可解一生之需。”当然，你如果想学煮鱼的话，找我就对了。', `MaleText_loc5`='有一句諺語說，「與其給他魚吃，還不如教他釣魚」。當然，你可能想要煮那條魚，而那是我進來的地方。', `MaleText_loc7`='Hay un viejo dicho, "Dale un pescado a un hombre; lo has alimentado un día. Enseña a pescar a un hombre y lo habrás alimentado toda una vida." Por supuesto, querrás cocinar ese pescado, y ahí es donde entro yo.' WHERE `ID`=19753;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요, $n 님! 모험은 즐겁게 하고 있나요? 제 실험은 아주 잘 진행되고 있답니다...$B$B나중에 와서 한번 보세요! 앞으로도 시험 비행 기회가 더 있을 것 같으니까요!', `MaleText_loc4`='你好，$n！你的冒险怎么样了？我的实验进展很不错……$B$B记得以后要经常回来看看我！我可能有更多的测试飞行机会给你哦！', `MaleText_loc5`='哈囉，$n!你的冒險如何?我的實驗進行的很順利...$b$b記得要再來和我聊聊!我搞不好會有更多飛行試驗機會給你!', `MaleText_loc7`='¡Hola, $n! ¿Cómo van tus aventuras? Mis experimentos progresan bien...$B$B¡Asegúrate de volver conmigo más adelante! ¡Quizás te tenga más oportunidades de probar vuelos!' WHERE `ID`=19754;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 ''요리''라는 기술에 대해 좀 더 자세히 알려주십시오.', `MaleText_loc4`='能告诉我更多的关于“烹饪”的事情吗？', `MaleText_loc5`='告訴我更多關於你稱為「烹飪」的事情?', `MaleText_loc7`='Cuéntame más sobre eso que llamas "cocinar".', `FemaleText_loc1`='그 ''요리''라는 기술에 대해 좀 더 자세히 알려주세요.', `FemaleText_loc4`='能告诉我更多的关于“烹饪”的事情吗？', `FemaleText_loc5`='告訴我更多關於你稱為「烹飪」的事情?', `FemaleText_loc7`='Cuéntame más sobre eso que llamas "cocinar".' WHERE `ID`=19755;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 그대에게 힘과 명예를... 알터랙 계곡에는 당신과 같은 용사가 필요해요. 서리늑대 부족의 영토를 지켜야 합니다! 아제로스로 돌아가서 도움을 주시겠어요?', `MaleText_loc4`='力量和荣誉，$c。我们非常渴望像你这样的士兵能前往奥特兰克山谷，保卫霜狼氏族的领土！你会回到艾泽拉斯帮助我们吗？', `MaleText_loc5`='力量和榮譽，$c。我們在奧特蘭克山谷需要像你一樣熱心的士兵;霜狼的領土必須被保衛!你會返回艾澤拉斯提供你的協助嗎?', `MaleText_loc7`='Fuerza y honor, $c. Necesitamos soldados con ganas de aprender como tú en el Valle de Alterac; ¡el territorio de los Lobo Gélido debe ser defendido! ¿Volverás a Azeroth para prestar tu ayuda?', `FemaleText_loc1`='$c|1이여;여;, 그대에게 힘과 명예를... 알터랙 계곡에는 당신과 같은 용사가 필요해요. 서리늑대 부족의 영토를 지켜야 합니다! 아제로스로 돌아가서 도움을 주시겠어요?', `FemaleText_loc4`='力量和荣誉，$c。我们非常渴望像你这样的士兵能前往奥特兰克山谷，保卫霜狼氏族的领土！你会回到艾泽拉斯帮助我们吗？', `FemaleText_loc5`='力量和榮譽，$c。我們在奧特蘭克山谷需要像你一樣熱心的士兵;霜狼的領土必須被保衛!你會返回艾澤拉斯提供你的協助嗎?', `FemaleText_loc7`='Fuerza y honor, $c. Necesitamos soldados con ganas de aprender como tú en el Valle de Alterac; ¡el territorio de los Lobo Gélido debe ser defendido! ¿Volverás a Azeroth para prestar tu ayuda?' WHERE `ID`=19756;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$R 친구! 그래, 자네! 아라시 분지에 있어야 할 시간에 왜 여기서 빈둥거리며 시간을 낭비하고 있나? 아라소르 연맹이 무자비한 공격을 퍼붓고 있어. 자네의 도움이 필요하네. 물론 보상도 있을 거야!', `MaleText_loc4`='$c！是的，就是你！为什么你会在这座破败的城市里闲逛着浪费时间，而不是出现在阿拉希盆地的战场上？我们阿拉索联军正被敌人无情地攻击，我们需要你的奉献，而且你也一定会得到奖励的！', `MaleText_loc5`='$R!對，就是你!你為什麼在該去阿拉希盆地的時候浪費你的時間在這座殘破的城市鬼混?阿拉索聯軍的攻擊是殘酷無情的;我們需要你的貢獻，而你將被獎勵!', `MaleText_loc7`='¡$R! ¡Sí, tú! ¿Por qué pierdes el tiempo en esta ciudad en ruinas cuando deberías estar en la Cuenca de Arathi? La Liga de Arathor ataca despiadadamente; ¡se necesita tu ayuda, y se te recompensará!', `FemaleText_loc1`='$R 친구! 그래, 자네! 아라시 분지에 있어야 할 시간에 왜 여기서 빈둥거리며 시간을 낭비하고 있나? 아라소르 연맹이 무자비한 공격을 퍼붓고 있어. 자네의 도움이 필요하네. 물론 보상도 있을 거야!', `FemaleText_loc4`='$c！是的，就是你！为什么你会在这座破败的城市里闲逛着浪费时间，而不是出现在阿拉希盆地的战场上？我们阿拉索联军正被敌人无情地攻击，我们需要你的奉献，而且你也一定会得到奖励的！', `FemaleText_loc5`='$R!對，就是你!你為什麼在該去阿拉希盆地的時候浪費你的時間在這座殘破的城市鬼混?阿拉索聯軍的攻擊是殘酷無情的;我們需要你的貢獻，而你將被獎勵!', `FemaleText_loc7`='¡$R! ¡Sí, tú! ¿Por qué pierdes el tiempo en esta ciudad en ruinas cuando deberías estar en la Cuenca de Arathi? La Liga de Arathor ataca despiadadamente; ¡se necesita tu ayuda, y se te recompensará!' WHERE `ID`=19757;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$C 친구, 아제로스의 숲에서 진행 중인 우리 일을 은빛날개 파수대가 방해하고 있어. 자네가 가서 놈들을 몰아내 주게! 우리를 도와주면 전쟁노래 정찰대 사이에서 좋은 평판과 명예를 얻을 수 있을 걸세. 어서 동참하게!', `MaleText_loc4`='$C，回到艾泽拉斯吧， 银翼哨兵妨碍了我们在森林里的伐木工作。我们需要你赶赴那边的前线，将战线推回去！如果你帮助我们，就将获得无上的荣誉，在战歌氏族当中也会积累很高的声望——现在就加入我们吧！', `MaleText_loc5`='$C，從前在艾澤拉斯的時候，樹林裡的銀翼哨兵阻礙我們的前進。我們需要你在前線將他們擊退!你將因為幫助我們而贏得戰歌先遣騎極大的尊敬和聲望 - 現在加入我們吧!', `MaleText_loc7`='$C, en Azeroth, los centinelas Ala de Plata obstaculizan nuestro avance por el bosque. ¡Te necesitamos en el frente de batalla para hacerlos retroceder! Conseguirás un gran honor y reputación entre los escoltas Grito de Guerra por ayudarnos - ¡únete a nosotros ahora!', `FemaleText_loc1`='$C 친구, 아제로스의 숲에서 진행 중인 우리 일을 은빛날개 파수대가 방해하고 있어. 자네가 가서 놈들을 몰아내 주게! 우리를 도와주면 전쟁노래 정찰대 사이에서 좋은 평판과 명예를 얻을 수 있을 걸세. 어서 동참하게!', `FemaleText_loc4`='$C，回到艾泽拉斯吧， 银翼哨兵妨碍了我们在森林里的伐木工作。我们需要你赶赴那边的前线，将战线推回去！如果你帮助我们，就将获得无上的荣誉，在战歌氏族当中也会积累很高的声望——现在就加入我们吧！', `FemaleText_loc5`='$C，從前在艾澤拉斯的時候，樹林裡的銀翼哨兵阻礙我們的前進。我們需要你在前線將他們擊退!你將因為幫助我們而贏得戰歌先遣騎極大的尊敬和聲望 - 現在加入我們吧!', `FemaleText_loc7`='$C, en Azeroth, los centinelas Ala de Plata obstaculizan nuestro avance por el bosque. ¡Te necesitamos en el frente de batalla para hacerlos retroceder! Conseguirás un gran honor y reputación entre los escoltas Grito de Guerra por ayudarnos - ¡únete a nosotros ahora!' WHERE `ID`=19758;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='목숨을 보존하게. 어서 여기서 나가! 붉은 인장대에게 발각되면 그 즉시 자네를 죽일 걸세.', `MaleText_loc4`='先救救你自己吧，$r。立刻从这个地方逃走！如果你被发现的话，一定会被火色魔印就地处死。', `MaleText_loc5`='救你自己吧，$r。從這個地方逃離!如果你被發現，赤紅法印將立即處決你。', `MaleText_loc7`='Sálvate, $r. ¡Huye de este lugar! El Sigilo Carmesí te ejecutará en el acto si te descubre.', `FemaleText_loc1`='목숨을 보존하게. 어서 여기서 나가! 붉은 인장대에게 발각되면 그 즉시 자네를 죽일 걸세.', `FemaleText_loc4`='先救救你自己吧，$r。立刻从这个地方逃走！如果你被发现的话，一定会被火色魔印就地处死。', `FemaleText_loc5`='救你自己吧，$r。從這個地方逃離!如果你被發現，赤紅法印將立即處決你。', `FemaleText_loc7`='Sálvate, $r. ¡Huye de este lugar! El Sigilo Carmesí te ejecutará en el acto si te descubre.' WHERE `ID`=19759;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고블린 스팀휘들 결투 대회가 곧 시작됩니다. 현재 투기장에서 연습 경기가 벌어지고 있습니다. 본선 전투는 $4262d 후에 시작됩니다.', `MaleText_loc4`='热砂格斗联赛就要开始了。现在，地精们正在竞技场组织练习赛，正式的排位赛将在$4262d后开始。', `MaleText_loc5`='哥布林熱砂戰鬥同盟很快就要開始了。他們現在正在競技場舉行練習賽，而積分賽將在$4262d後開始。', `MaleText_loc7`='El Círculo de Lucha goblin Bonvapor comienza pronto. Celebran combates de práctica en la arena ahora, pero los combates de clasificación comienzan en $4262d.', `FemaleText_loc1`='고블린 스팀휘들 결투 대회가 곧 시작됩니다. 현재 투기장에서 연습 경기가 벌어지고 있습니다. 본선 전투는 $4262d 후에 시작됩니다.', `FemaleText_loc4`='热砂格斗联赛就要开始了。现在，地精们正在竞技场组织练习赛，正式的排位赛将在$4262d后开始。', `FemaleText_loc5`='哥布林熱砂戰鬥同盟很快就要開始了。他們現在正在競技場舉行練習賽，而積分賽將在$4262d後開始。', `FemaleText_loc7`='El Círculo de Lucha goblin Bonvapor comienza pronto. Celebran combates de práctica en la arena ahora, pero los combates de clasificación comienzan en $4262d.' WHERE `ID`=19760;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일리단의 이름으로!', `MaleText_loc4`='以伊利丹的名义！', `MaleText_loc5`='以伊利丹之名!', `MaleText_loc7`='¡En nombre de Illidan!' WHERE `ID`=19761;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님을 위하여!', `MaleText_loc4`='为了我们的主人！', `MaleText_loc5`='為了我們的守護神!', `MaleText_loc7`='¡Por nuestro patrón!' WHERE `ID`=19762;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽어라, 침입자여!', `MaleText_loc4`='受死吧，入侵者！', `MaleText_loc5`='死吧，闖入者!', `MaleText_loc7`='¡Muere, $gintruso:intrusa;!' WHERE `ID`=19763;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달아날 곳은 없다...', `MaleText_loc4`='休想逃走……', `MaleText_loc5`='沒有人逃的了...', `MaleText_loc7`='No habrá forma de huir...' WHERE `ID`=19764;
