UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고블린 스팀휘들 결투 대회가 시작되었어요. 가젯잔이나 나그란드, 그리고 칼날 산맥의 투기장 밖에서 투기장 팀 창단허가서를 파는 투기장 조직위원을 찾을 수 있어요.', `MaleText_loc4`='热砂格斗联赛已经开始了。竞技场组织者正在加基森、纳格兰竞技场和刀锋山竞技场外兜售竞技场战队登记表。', `MaleText_loc5`='哥布林熱砂戰鬥同盟已開始。你可以在加基森裡，納葛蘭和劍刃山脈的競技場外找到販賣競技場隊伍登記表的競技場登記員。', `MaleText_loc7`='El Círculo de Lucha goblin Bonvapor ha comenzado. Puedes encontrar organizadores de combates vendiendo estatutos de equipos de arena en Gadgetzan y fuera de la arena de Nagrand y de las Montañas Filospada.', `FemaleText_loc1`='고블린 스팀휘들 결투 대회가 시작되었어요. 가젯잔이나 나그란드, 그리고 칼날 산맥의 투기장 밖에서 투기장 팀 창단허가서를 파는 투기장 조직위원을 찾을 수 있어요.', `FemaleText_loc4`='热砂格斗联赛已经开始了。竞技场组织者正在加基森、纳格兰竞技场和刀锋山竞技场外兜售竞技场战队登记表。', `FemaleText_loc5`='哥布林熱砂戰鬥同盟已開始。你可以在加基森裡，納葛蘭和劍刃山脈的競技場外找到販賣競技場隊伍登記表的競技場登記員。', `FemaleText_loc7`='El Círculo de Lucha goblin Bonvapor ha comenzado. Puedes encontrar organizadores de combates vendiendo estatutos de equipos de arena en Gadgetzan y fuera de la arena de Nagrand y de las Montañas Filospada.' WHERE `ID`=19767;
