UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일리단 님을 위해서라면 고결한 이 한 몸, 얼마든지 희생할 수 있다. 오늘 너희는 위대한 토를로스의 제물이 될 것이다...', `MaleText_loc4`='为了伊利丹大人，我甚至愿意牺牲这强大的体魄。今天，你一定会倒下——成为我托洛斯刀下的亡魂……', `MaleText_loc5`='為了伊利丹王，我甚至願意犧牲這完美的體格。今天，你將倒下 - 另一名托洛斯的受害者...', `MaleText_loc7`='Por Lord Illidan, sacrificaría hasta este magnífico físico. En el día de hoy, caerás – otra víctima de Torloth...' WHERE `ID`=19788;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고블린 스팀휘들 결투 대회가 곧 시작될걸세. 현재 투기장에서 연습 경기가 벌어지고 있는데 본선 전투는 $4262d 후에 시작될 게야.', `MaleText_loc4`='热砂格斗联赛就要开始了。现在，地精们正在竞技场组织练习赛，正式的排位赛将在$4262d后开始。', `MaleText_loc5`='哥布林熱砂戰鬥同盟很快就要開始了。他們現在正在競技場舉行練習賽，而積分賽將在$4262d後開始。', `MaleText_loc7`='El Círculo de Lucha goblin Bonvapor comienza pronto. Celebran combates de práctica en la arena ahora, pero los combates de clasificación comienzan en $4262d.', `FemaleText_loc1`='고블린 스팀휘들 결투 대회가 곧 시작될걸세. 현재 투기장에서 연습 경기가 벌어지고 있는데 본선 전투는 $4262d 후에 시작될 게야.', `FemaleText_loc4`='热砂格斗联赛就要开始了。现在，地精们正在竞技场组织练习赛，正式的排位赛将在$4262d后开始。', `FemaleText_loc5`='哥布林熱砂戰鬥同盟很快就要開始了。他們現在正在競技場舉行練習賽，而積分賽將在$4262d後開始。', `FemaleText_loc7`='El Círculo de Lucha goblin Bonvapor comienza pronto. Celebran combates de práctica en la arena ahora, pero los combates de clasificación comienzan en $4262d.' WHERE `ID`=19789;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<서투른 공용어로 말하는 회색의 검투사> 뭐라고? 나한테 볼일이라도 있나? 그렇다면, 투기장으로 와라. 너 같은 풋내기 ''호드''나 ''얼라이언스''에게 낭비할 시간 따위는 없으니까.', `MaleText_loc4`='<灰头发的角斗士用结结巴巴的通用语说着。>什么？你对我有意见？上竞技场去解决吧。我不会为你们的什么小“部落”和小“联盟”浪费时间。', `MaleText_loc5`='<蒼老的鬥士用彆腳的普通語說著。>什麼?你對我有意見?把它帶到競技場。我不會浪費時間在你的小「部落」和「聯盟」上。', `MaleText_loc7`='<El gladiador de sienes plateadas habla en lengua común vacilante.> ¿Qué? ¿Tienes algún problema conmigo? Llévalo a la arena. No pierdo el tiempo con ustedes, pequeños de la "Horda" y de la "Alianza."' WHERE `ID`=19790;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검투사가 순위 경기에서 승리하면 내가 입고 있는 것과 같은 장비를 착용할 수 있는 권리를 획득하게 된다.', `MaleText_loc4`='角斗士们通过在竞技场的段位赛中取胜来获得使用我身上这套装备的权利。', `MaleText_loc5`='藉由贏得競技場積分賽，鬥士們便可穿戴像我這樣的裝備。', `MaleText_loc7`='Los gladiadores obtienen el derecho a llevar equipamiento como el mío ganando encuentros de arena puntuados.' WHERE `ID`=19791;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<서투른 공용어로 말하는 회색의 검투사> 뭐라고? 나한테 볼일이라도 있나? 그렇다면, 투기장으로 와라. 너 같은 풋내기 ''호드''나 ''얼라이언스''에게 낭비할 시간 따위는 없으니까.', `MaleText_loc4`='<身经百战的角斗士用结结巴巴的通用语说着。>什么？你对我有意见？上竞技场去解决吧。我不会为你们的什么小“部落”和小“联盟”浪费时间。', `MaleText_loc5`='<老練的鬥士用彆腳的獸人語說著。>什麼?你對我有意見?把它帶到競技場。我不會浪費時間在你的小「部落」和「聯盟」上。', `MaleText_loc7`='<El gladiador veterano habla en lengua orca vacilante.> ¿Qué? ¿Tienes algún problema conmigo? Llévalo a la arena. No pierdo el tiempo con ustedes, pequeños de la "Horda" y de la "Alianza."' WHERE `ID`=19792;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='순위 경기에서 승리하면 검투사는 내가 입은 것과 같은 장비를 착용할 권리를 획득하게 되오.', `MaleText_loc4`='角斗士们通过在竞技场的段位赛中取胜来获得使用我身上这套装备的权利。', `MaleText_loc5`='藉由贏得競技場積分賽，鬥士們便可穿戴像我這樣的裝備。', `MaleText_loc7`='Los gladiadores obtienen el derecho a llevar equipamiento como el mío ganando encuentros de arena puntuados.' WHERE `ID`=19793;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샤트라스로 돌아가, 영웅이여. 가서 아달의 지혜를 구하게.', `MaleText_loc4`='回到沙塔斯城去吧，英雄。寻求阿达尔的真知灼见吧。', `MaleText_loc5`='返回撒塔斯，英雄。尋找阿達歐的智慧。', `MaleText_loc7`='Vuelve a Shattrath, héroe. Busca la sabiduría de A''dal.' WHERE `ID`=19794;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='암흑의 시대가 우리를 찾아왔네. 당대 최고의 영웅들마저 일리단 앞에 무릎을 꿇는다면 우리는 어찌해야 하나?', `MaleText_loc4`='黑暗的日子已经降临在我们头上，$n。如果我们最强大的英雄也倒在了伊利丹的面前，我们又该怎么办？', `MaleText_loc5`='黑暗的日子降臨在我們身上，$n。當我們最偉大的英雄都在伊利丹的力量前倒下，我們還能做些什麼?', `MaleText_loc7`='Se acercan días oscuros para nosotros, $n. ¿Qué vamos a hacer cuando hasta nuestros mayores héroes caen ante el poder de Illidan?' WHERE `ID`=19795;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 가운데로 움직이도록! 조만간 일리단의 분노가 폭발할 거야!', `MaleText_loc4`='快点，到平台中间去！伊利丹很快就会释放他的怒火了！', `MaleText_loc5`='快，快來平台中間!伊利丹不久之後就會暴怒了!', `MaleText_loc7`='¡Rápido, id al centro de la plataforma! ¡Pronto se desatará la furia de Illidan!' WHERE `ID`=19796;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 바보들이 감히 이 일리단 스톰레이지 님의 길을 막느냐? 병사들아, 저 벌레들을 제거해라!', `MaleText_loc4`='什么样的蠢货胆敢站在伊利丹·怒风面前？士兵们，消灭这些蝼蚁！', `MaleText_loc5`='什麼樣的蠢蛋敢在伊利丹·怒風面前站著?士兵，毀滅這些小蟲!', `MaleText_loc7`='¿Qué clase de persona estúpida osa alzarse ante Illidan Tempestira? ¡Soldados, destruid a estos insectos!' WHERE `ID`=19797;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희는 붉은 인장대의 상대가 되지 못한다. 정신파괴자들아, 이 무모한 놈들의 숨통을 끊어줘라!', `MaleText_loc4`='你对于火色魔印来说，根本不算什么挑战。碎灵者们，终结这个废物吧！', `MaleText_loc5`='你不是赤紅法印的對手。笨蛋，結束這場胡鬧!', `MaleText_loc7`='No eres un desafío para el Sigilo Carmesí. ¡Rompementes, acabad con esta tontería!' WHERE `ID`=19798;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두 다리가 성할 때 달아나라. 곧 대군주들을 보내겠다...', `MaleText_loc4`='趁你还能跑的时候，快跑吧。大领主马上就要来了……', `MaleText_loc5`='趁你還能跑時快點跑。大領主很快就到了...', `MaleText_loc7`='Corre mientras puedas. Los altos señores vienen pronto...' WHERE `ID`=19799;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='토를로스, 네 주인의 부르노니 나와서 싸워라!', `MaleText_loc4`='托洛斯，你的主人在召唤你！', `MaleText_loc5`='托洛斯，你的主人叫你!', `MaleText_loc7`='¡Torloth, tu maestro llama!' WHERE `ID`=19800;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='결국, 붉은 인장대에게 승리했군. 그리고 이제는 내게 도전하겠다는 건가? 아서스도 날 꺾지 못했는데 감히 너희 따위가 그런 생각을 품다니? 어디 덤벼봐라! $n, 검은 사원이 너를 기다리고 있다...', `MaleText_loc4`='你竟然击败了火色魔印，还想挑战我的统治吗？即使是阿尔萨斯都不能打败我，你们这些家伙竟然也敢做这种梦？那么我要告诉你，来吧！来吧，$n！我就在黑暗神殿里等着你……', `MaleText_loc5`='所以你擊敗了赤紅法印。現在想挑戰我的統治嗎?連阿薩斯都沒辦法戰勝我，你還膽敢懷有這樣的想法嗎?那麼我對你說，來吧!來吧$n!黑暗神廟等著你...', `MaleText_loc7`='Así que has derrotado al Sigilo Carmesí. ¿Y ahora quieres desafiar mi dominio? Ni siquiera Arthas pudo derrotarme y, aun así, ¿osas siquiera albergar tales pensamientos? Entonces, ¡te digo que vengas! ¡Ven, $n! El Templo Oscuro aguarda...' WHERE `ID`=19801;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기! 스팀휘들 결투 대회라고 들어는 봤나?

가젯잔이나 나그란드, 그리고 칼날 산맥의 투기장 밖에서 투기장 팀 창단허가서를 파는 투기장 조직위원을 찾을 수 있다고.', `MaleText_loc4`='哟！你听说过热砂港搏击会吗？

你可以在加基森城内以及纳格兰和刀锋山的竞技场外面找到竞技场组织者，他正在出售竞技场战队登记表。', `MaleText_loc5`='喂!你聽說過熱砂戰鬥同盟嗎?

你可以在加基森裡，納葛蘭和劍刃山脈的競技場外找到販賣競技場隊伍登記表的競技場登記員。', `MaleText_loc7`='¡Eh! ¿Has oído hablar del Círculo de Lucha de Bonvapor?

Puedes encontrar organizadores de combates vendiendo estatutos de equipos de arena en Gadgetzan y fuera de la arena de Nagrand y de las Montañas Filospada.', `FemaleText_loc1`='거기! 스팀휘들 결투 대회라고 들어는 봤나?

가젯잔이나 나그란드, 그리고 칼날 산맥의 투기장 밖에서 투기장 팀 창단허가서를 파는 투기장 조직위원을 찾을 수 있다고.', `FemaleText_loc4`='哟！你听说过热砂港搏击会吗？

你可以在加基森城内以及纳格兰和刀锋山的竞技场外面找到竞技场组织者，他正在出售竞技场战队登记表。', `FemaleText_loc5`='喂!你聽說過熱砂戰鬥同盟嗎?

你可以在加基森裡，納葛蘭和劍刃山脈的競技場外找到販賣競技場隊伍登記表的競技場登記員。', `FemaleText_loc7`='¡Eh! ¿Has oído hablar del Círculo de Lucha de Bonvapor?

Puedes encontrar organizadores de combates vendiendo estatutos de equipos de arena en Gadgetzan y fuera de la arena de Nagrand y de las Montañas Filospada.' WHERE `ID`=19802;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, 감독관님! 휴가라도 오셨나요? 다시 루안 숲으로 발령받으신 후로는 이 근처에서 거의 못 뵌 것 같은데...$B$B제가 물건 좀 봐주십시오. 마지막으로 뵀을 때와 비교해서 별로 바뀐 게 없을지도 모르지만 대신 양이 아주 많아요.$B$B그리고 앞으로는 아는 척이라도 좀 해주세요!', `MaleText_loc4`='你好。在休息吗，监工？自从你被派去卢安荒野以后，我们就很少能在这里看到你了。$B$B看看我这些东西，似乎跟我们上次见面的时候没什么改变，但是我这里存货很多。$B$B别这么客气嘛！', `MaleText_loc5`='嘿。監督者，休息一下吧?自從你被分派到魯安曠野我們就很少見到你了。$B$B看一下我的東西。雖然和我們上次交談的時候差不多，但是我有大量存貨。$B$B不要像個陌生人一樣!', `MaleText_loc7`='Hola. ¿Te tomas un descanso, sobrestante? Ya no te vemos demasiado por aquí desde que te reasignaron a la Foresta Ruuan.$B$BEcha un vistazo a lo que tengo que ofrecer. Puede que no haya cambiado demasiado desde que hablamos por última vez, pero tengo en abundancia.$B$B¡Y no seas $gun extraño:una extraña;!' WHERE `ID`=19803;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 뭘 가지고 있는지 한번 보세.', `MaleText_loc4`='非常好，让我看看你有什么。', `MaleText_loc5`='非常好，讓我看看你有什麼。', `MaleText_loc7`='Muy bien, déjame ver qué tienes.', `FemaleText_loc1`='좋아, 뭘 가지고 있는지 한번 보세.', `FemaleText_loc4`='非常好，让我看看你有什么。', `FemaleText_loc5`='非常好，讓我看看你有什麼。', `FemaleText_loc7`='Muy bien, déjame ver qué tienes.' WHERE `ID`=19804;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용 학살자 그룰과 그의 일곱 아들을 빼놓고 내가 가장 혐오하는 것이 바로 방해받는 것이다!', `MaleText_loc4`='我讨厌别人打断我说话，但我更讨厌屠龙者格鲁尔和他的七个儿子！', `MaleText_loc5`='只有我對弒龍者戈魯爾和他七個兒子的憎恨才能超越我對阻礙的嫌惡!', `MaleText_loc7`='¡Mi aversión a las interrupciones solo se ve eclipsada por mi odio hacia Gruul el Asesino de Dragones y sus siete hijos!' WHERE `ID`=19805;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$4262d 후에 투기장 순위 경기가 다시 시작된다네. 자칭 우승을 노리고 몰려든 용사들이 이미 몸을 풀며 기술을 가다듬고 최상의 장비를 갖췄다고. 자네도 대전에 참여할 준비가 됐나?', `MaleText_loc4`='竞技场排位赛会在$4262d后开始。想要成为冠军的人已经开始忙着磨炼技术和寻找最好的装备了。你呢，准备好了吗？', `MaleText_loc5`='競技場積分賽將在$4262d後開始。鬥士們忙著磨練他們的技能，並且取得他們最好的裝備。你準備好了嗎?', `MaleText_loc7`='Los encuentros de arena puntuados comienzan en $4262d. Los aspirantes a campeones ya están ocupados perfeccionando sus habilidades y adquiriendo el mejor equipo que pueden. ¿Estarás $gpreparado:preparada;?', `FemaleText_loc1`='$4262d 후에 투기장 순위 경기가 다시 시작된다네. 자칭 우승을 노리고 몰려든 용사들이 이미 몸을 풀며 기술을 가다듬고 최상의 장비를 갖췄다고. 자네도 대전에 참여할 준비가 됐나?', `FemaleText_loc4`='竞技场排位赛会在$4262d后开始。想要成为冠军的人已经开始忙着磨炼技术和寻找最好的装备了。你呢，准备好了吗？', `FemaleText_loc5`='競技場積分賽將在$4262d後開始。鬥士們忙著磨練他們的技能，並且取得他們最好的裝備。你準備好了嗎?', `FemaleText_loc7`='Los encuentros de arena puntuados comienzan en $4262d. Los aspirantes a campeones ya están ocupados perfeccionando sus habilidades y adquiriendo el mejor equipo que pueden. ¿Estarás $gpreparado:preparada;?' WHERE `ID`=19806;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리... 아이들을... 구해줘...', `FemaleText_loc4`='你必须……解救……我的孩子们……', `FemaleText_loc5`='你一定要...解救...我的孩子...', `FemaleText_loc7`='Debes... liberar... a mis hijos...' WHERE `ID`=19807;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 완성됐다.', `MaleText_loc4`='喂，已经完成了。', `MaleText_loc5`='喏，完成了。', `MaleText_loc7`='Toma, está terminado.' WHERE `ID`=19808;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이대로는 얼마 못 갑니다! 저들의 날개도 결국은...', `MaleText_loc4`='他们不能继续这样！他们的翅膀终将……', `MaleText_loc5`='他們不能繼續這樣!他們的翅膀最終將給予...', `MaleText_loc7`='¡No lo pueden mantener arriba! Al final, sus alas cederán...' WHERE `ID`=19809;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='딱 한 발로 끝장내주지...', `MaleText_loc4`='只需华丽的一射……', `MaleText_loc5`='只要一發好的射擊...', `MaleText_loc7`='Solo un buen disparo...' WHERE `ID`=19810;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 드린 신앙의 고서를 읽어보십시오. 고서를 다 익힌 후 다시 오시기 바랍니다.', `FemaleText_loc4`='去读一下我给你的圣洁之书，$n。你从书里学到些东西之后，再来和我谈谈。', `FemaleText_loc5`='閱讀我給你的聖潔之書，$n。當你已經從書本學到東西時，再與我談話。', `FemaleText_loc7`='Lee el escrito sobre divinidad que te he dado, $n. Cuando hayas aprendido cosas del libro, vuelve a hablar conmigo.' WHERE `ID`=19811;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 돌발톱 바위갈퀴 시체 안에서 뭔가를 주워듭니다.', `MaleText_loc4`='%s拾起了剥石者的尸体碎块。', `MaleText_loc5`='%s撿起撕掠者屍體。', `MaleText_loc7`='%s coge la carcasa de despellejador.' WHERE `ID`=19812;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 운명이 결정되었다.', `MaleText_loc4`='你的命运早已注定。', `MaleText_loc5`='你的命運注定如此。', `MaleText_loc7`='Tu destino está escrito.' WHERE `ID`=19813;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금까지의 혼돈은 맛보기에 불과하다...', `MaleText_loc4`='我所播种的混乱只是一个开端……', `MaleText_loc5`='我在這散播的混亂只不過是剛剛開始而已...', `MaleText_loc7`='El caos que he sembrado aquí es solo una muestra...' WHERE `ID`=19814;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 무한한 선구자 중... 한 명일 뿐...', `MaleText_loc4`='我只是一个……不值一提的小角色。', `MaleText_loc5`='我只不過是...宇宙中的一個塵埃而已。', `MaleText_loc7`='Solo soy uno de... infinitas multitudes.' WHERE `ID`=19815;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명령에 복종하라. 나약한 자여...', `MaleText_loc4`='你将听从我的指挥。', `MaleText_loc5`='你將聽從我的命令，弱者。', `MaleText_loc7`='Tú me obedecerás, enclenque.' WHERE `ID`=19816;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너의 의지는 나의 것이다.', `MaleText_loc4`='你的意志不再属于自己了。', `MaleText_loc5`='你的意志已不再屬於你自己。', `MaleText_loc7`='Tu voluntad ya no te pertenece.' WHERE `ID`=19817;
