UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님... 실망시켜 드려서 죄송합니다...', `MaleText_loc4`='主人……我辜负了你……', `MaleText_loc5`='主人...我讓你失望了...', `MaleText_loc7`='Maestro... te he fallado...' WHERE `ID`=19820;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밤하늘의 무한한 별처럼 온 우주를 덮으리라!', `MaleText_loc4`='我们遍布宇宙的每一个角落，像群星一样无穷无尽！', `MaleText_loc5`='我們跨越宇宙之間，被我們摧毀的世界像星星一樣數不盡!', `MaleText_loc7`='¡Abarcamos el universo, somos tantos como las estrellas!' WHERE `ID`=19821;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐요, 무슨 일인지는 모르지만, 저 무뢰한을 혼내줄 요량이라면 내 기꺼이 도와드리죠!', `MaleText_loc4`='我不知道这里发生了什么事情，但是我会很高兴和你们一起收拾这个无理的蠢材！', `MaleText_loc5`='我不知道這裡發生什麼事，但是我很高興加入你對抗這無恥的低能兒!', `MaleText_loc7`='¡No tengo ni idea de qué sucede aquí, pero me uniré con mucho gusto a tu lucha contra este imbécil insolente!' WHERE `ID`=19822;
