UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 정도야 식은 죽 먹기보다 더 쉽지!', `MaleText_loc4`='我甚至都没有流一滴汗！', `MaleText_loc5`='我甚至沒有流下一滴汗!', `MaleText_loc7`='¡Ni si quiera me hizo sudar!' WHERE `ID`=19824;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언제든지 덤비라고.', `MaleText_loc4`='你们随时都可以来跟我一起作战！', `MaleText_loc5`='你們任何時候都可以再來找我。', `MaleText_loc7`='Vuelvan cuando quieran.' WHERE `ID`=19825;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='화끈하게 놀아주마, 귀여운 것!', `MaleText_loc4`='我要把你们烤熟了！', `MaleText_loc5`='我要點燃你們那些紅潤的臉頰!', `MaleText_loc7`='¡Los voy a encender un poco, insolentes!' WHERE `ID`=19826;
