UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와줘! 여러분의 사랑으로 치유의 힘을 모아주세요! 노움 죽네!', `MaleText_loc4`='治疗我！天杀的，赶快治疗我！我要嗝屁了！', `MaleText_loc5`='治療我!為了神恩，治療我!我快要死了!!', `MaleText_loc7`='¡Cúrame! ¡Por todo lo sagrado, cúrame! ¡Me muero!' WHERE `ID`=19828;
