UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 돌발톱 바위갈퀴 시체를 게걸스럽게 먹습니다.', `MaleText_loc4`='%s狼吞虎咽地将剥石者的尸体吃了个精光。', `MaleText_loc5`='%s飢餓地吃著撕掠者屍體。', `MaleText_loc7`='%s devora con hambre la carcasa de despellejador.' WHERE `ID`=19848;
