UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 또 다른 $c|1이;가; 검투사가 되려고 왔군? 좋아!

스팀휘들 결투 대회의 순위 경기에 참가하려면 반드시 내가 파는 투기장 팀 창단허가서에 서명하고 팀을 구성해야 한다네.', `MaleText_loc4`='啊，又有一个想成为角斗士的$c，嗯？很好！

我可以卖给你参加热砂搏击会的赛事所必需的竞技场战队登记表。', `MaleText_loc5`='另一個想當鬥士的$c啊?很好!

我專賣參加熱砂戰鬥同盟積分賽將需要的競技場隊伍登記表。', `MaleText_loc7`='Ah, $gotro:otra; $c que quiere ser $ggladiador:gladiadora;, ¿eh? ¡Bien!

Vendo los estatutos de equipos de arena que necesitarás para participar en los combates de clasificación del Círculo de Lucha de Bonvapor.', `FemaleText_loc1`='아, 또 다른 $c|1이;가; 검투사가 되려고 왔군? 좋아!

스팀휘들 결투 대회의 순위 경기에 참가하려면 반드시 내가 파는 투기장 팀 창단허가서에 서명하고 팀을 구성해야 한다네.', `FemaleText_loc4`='啊，又有一个想成为角斗士的$c，嗯？很好！

我可以卖给你参加热砂搏击会的赛事所必需的竞技场战队登记表。', `FemaleText_loc5`='另一個想當鬥士的$c啊?很好!

我專賣參加熱砂戰鬥同盟積分賽將需要的競技場隊伍登記表。', `FemaleText_loc7`='Ah, $gotro:otra; $c que quiere ser $ggladiador:gladiadora;, ¿eh? ¡Bien!

Vendo los estatutos de equipos de arena que necesitarás para participar en los combates de clasificación del Círculo de Lucha de Bonvapor.' WHERE `ID`=19850;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='투기장 팀은 어떻게 만드나요?', `MaleText_loc4`='怎样才能组建一支竞技场战队？', `MaleText_loc5`='我要如何組成競技場隊伍?', `MaleText_loc7`='¿Cómo formo un equipo de arena?', `FemaleText_loc1`='투기장 팀은 어떻게 만드나요?', `FemaleText_loc4`='怎样才能组建一支竞技场战队？', `FemaleText_loc5`='我要如何組成競技場隊伍?', `FemaleText_loc7`='¿Cómo formo un equipo de arena?' WHERE `ID`=19852;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직은 투기장 팀 창단허가서를 팔지 않아. 허가서가 있어야 스팀휘들 결투 대회의 순위 경기에 참가할 수 있지.

하지만, 투기장 사무관을 찾아가서 연습 경기에는 참가할 수 있지. 연습은 많이 할수록 좋지.', `MaleText_loc4`='热砂搏击会还未开始出售你参加排位赛所必需的竞技场战队登记表。

不过，你现在可以找个竞技场管理员，让他安排你参加练习比赛。练习是永远不嫌多的。', `MaleText_loc5`='熱砂戰鬥同盟目前沒賣你參加積分賽需要的競技場隊伍登記表。

不過，你還是可以找競技場戰場軍官參加一些練習賽。開始訓練都不會太晚。', `MaleText_loc7`='El Círculo de Lucha Bonvapor todavía no vende los estatutos de equipos de arena que necesitarás para participar en los combates de clasificación.

Aun así, puedes buscar a un maestro de batalla de arena y hacer asaltos de práctica. Nunca es demasiado pronto para empezar a entrenar.', `FemaleText_loc1`='아직은 스팀휘들 결투 대회의 순위 경기에 참가하는 데 필요한 투기장 팀 창단허가서를 판매하고 있지 않답니다.

하지만 투기장 사무관에게 찾아가서 연습 경기에는 참가할 수 있지요. 연습은 많이 할수록 좋은 거랍니다.', `FemaleText_loc4`='热砂搏击会还未开始出售你参加排位赛所必需的竞技场战队登记表。

不过，你现在可以找个竞技场管理员，让他安排你参加练习比赛。练习是永远不嫌多的。', `FemaleText_loc5`='熱砂戰鬥同盟目前沒賣你參加積分賽需要的競技場隊伍登記表。

不過，你還是可以找競技場戰場軍官參加一些練習賽。開始訓練都不會太晚。', `FemaleText_loc7`='El Círculo de Lucha Bonvapor todavía no vende los estatutos de equipos de arena que necesitarás para participar en los combates de clasificación.

Aun así, puedes buscar a un maestro de batalla de arena y hacer asaltos de práctica. Nunca es demasiado pronto para empezar a entrenar.' WHERE `ID`=19853;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 자만심이 파멸로 이끌리라! 경비병, 힘을 보태줘야겠다!', `MaleText_loc4`='你的自负将给你带来灭亡！卫兵，把你们的力量借给我!', `MaleText_loc5`='你的自負將是你毀滅的原因!守衛們，把你們的力量借給我!', `MaleText_loc7`='¡Su exceso de confianza será su perdición! ¡Guardias, préstenme su fuerza!' WHERE `ID`=19854;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='해골망치 초소는 우리 주둔지로 안성맞춤이라네! 기형을 일으키는 피눈물 부족 놈들과 아주 가까워서 놈들의 오염된 피 냄새를 맡을 수도 있지! 동족을 배반하고 악마와 계약을 맺은 일족에게 복수를 하기에 이보다 더 좋은 곳이 어디 있나?', `FemaleText_loc4`='断背岗哨真是一处优秀的营地！离那些血环的邪兽人们那么近，甚至都可以闻到他们肮脏的血液的味道！那个氏族竟然遗忘了它的同伴，还和恶魔之间达成了协议，让我们在此向他们发起复仇吧！', `FemaleText_loc5`='斷脊氏族崗哨是一個重要的駐紮地點!血之谷的異常是如此的靠近，你能聞到他們邪惡的鮮血!還有什麼地方比這更適合對一個背棄同志，與惡魔達成條約的氏族進行復仇呢?', `FemaleText_loc7`='¡La Avanzada Rompeloma es un lugar genial en el que estar destinado! ¡Las aberraciones del Foso Sangrante están tan cerca que se puede oler su infecta sangre! ¿Qué mejor lugar para vengarse de un clan que ha traicionado a sus hermanos y ha hecho un pacto con demonios?' WHERE `ID`=19855;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돼지!!!', `MaleText_loc4`='小猪！！！', `MaleText_loc5`='小豬!!!', `MaleText_loc7`='¡¡¡Cerdito!!!' WHERE `ID`=19856;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돼지고기야!', `MaleText_loc4`='猪排！', `MaleText_loc5`='豬排!', `MaleText_loc7`='¡Chuletas de cerdo!' WHERE `ID`=19857;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='격노의 심장이라... 오래전 나는 벨렌이 격노의 심장을 사용할 때 그 힘을 몸소 목격했지. 지금 느껴지는 힘은 그때 그 힘과 똑같군그래!', `MaleText_loc4`='愤怒之心……很久以前，维伦持有它的时候，我目睹过它的力量。而现在，我依然可以感觉到相同的力量正在它内部澎湃着！', `MaleText_loc5`='狂怒之心...我很久以前目睹過它的力量，當費倫揮舞它時。我現在就感覺到相同的力量穿過它!', `MaleText_loc7`='El corazón de furia... Presencié su poder antaño, cuando Velen lo blandía. ¡Ahora siento la misma energía fluyendo a través de él!' WHERE `ID`=19858;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 수정의 힘만 있으면 나와 내 결사단은... 무적이 될 것이다! 그러면, 우리는 일리단을 해치울 수 있어! 우리는... 일리단을 대신해서 아웃랜드의 주인이 될 것이다!', `MaleText_loc4`='有了这块水晶的力量，我的死誓者和我……将会不可抵挡！我们甚至可以消灭伊利丹！我们可以……替代他成为新的外域之王！', `MaleText_loc5`='由於這顆水晶的力量，我和我的死亡誓言者...我們不能自己!我們可以摧毀伊利丹!我們可以...接替他成為外域的領主!', `MaleText_loc7`='Con los poderes de este cristal, mis juramortes y yo... ¡seríamos imparables! ¡Podríamos destruir a Illidan! Podríamos... ¡reemplazarlo como señores de Terrallende!' WHERE `ID`=19859;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만, 그건 내가 본 계시와는 다르구나... 내 백성들은 그렇게 자유의 몸이 되는 것이 아니야...', `MaleText_loc4`='但那不是纳鲁在我的梦境中给予我的指示……那不是……我解救同胞的方式。', `MaleText_loc5`='但是那不是我被授予的洞察力的一部分...那不是...我的人怎樣才會被釋放。', `MaleText_loc7`='Pero eso no es parte de la visión que tuve... así no es... como mi pueblo será liberado.' WHERE `ID`=19860;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='페어웨더와 저는 이곳에서 실바나르의 권리를 대변하고 있습니다.$B$B이곳 드루이드들은 호드들이 이곳을 통과하도록 허락할 뿐만 아니라 편의를 봐주고 있어 소름이 끼친답니다.', `MaleText_loc4`='法维瑟和我在这里代表着希尔瓦纳的利益。$B$B这里的德鲁伊未免过于热情好客了，竟然允许部落随意穿越这里，这让我感到非常不安。', `MaleText_loc5`='費爾威德和我來這裡代表希爾瓦納的利益。$B$B德魯伊們非常通融，但是允許部落穿越這裡讓我有種毛骨悚然的感覺。', `MaleText_loc7`='Buentiempo y yo estamos aquí representando los intereses de Sylvanaar.$B$BLos druidas han sido más que acogedores, pero permitir que la Horda pase por aquí me pone los pelos de punta.' WHERE `ID`=19861;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑다, 필멸의 존재여...', `MaleText_loc4`='你好，凡人。', `MaleText_loc5`='你好，凡人。', `MaleText_loc7`='Saludos, mortal.' WHERE `ID`=19862;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용이여, 말씀해 보십시오.', `MaleText_loc4`='我在听着呢，龙。', `MaleText_loc5`='我正在聽，巨龍。', `MaleText_loc7`='Escucho, dragón.', `FemaleText_loc1`='용이여, 말씀해 보십시오.', `FemaleText_loc4`='我在听着呢，龙。', `FemaleText_loc5`='我正在聽，巨龍。', `FemaleText_loc7`='Escucho, dragón.' WHERE `ID`=19863;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황천날개 벌판의 동쪽 경계으로 가면 용아귀 요새가 펼쳐져 있지. 바로 그곳에서 잔인한 용아귀 오크들이 비룡을 조련하려고 고문을 하고 있다. 많은 비룡이 용아귀 부족의 명령을 듣느니 차라리 희망을 버리고 말았지. 나머지 비룡들은... 용아귀 오크들에게 사로잡혀 요새로 끌려갈까 두려워 다시는 땅으로 내려오지 않았다.', `MaleText_loc4`='龙喉要塞坐落在灵翼平原的东部区域。在那里，无数残酷的龙喉氏族兽人正在折磨着他们抓来的虚空幼龙，甚至尝试扭曲它们的意志。很多幼龙就此放弃了对自由的希望，选择屈服，并开始遵守龙喉兽人的命令。而其它幼龙……它们因为害怕被龙喉兽人抓住而不敢降落，只能在天上不停地飞翔。', `MaleText_loc5`='在虛空之翼農場東方的區域有一座龍喉堡壘。殘酷的龍喉獸人氏族在那裡拷問他們捕獲的龍，試圖使他們屈從於他們的意志。其中很多已經放棄希望，改為服從龍喉的命令。而其他的...他們拒絕登陸，擔心龍喉主戰派捕獲他們並且把他們帶回堡壘。', `MaleText_loc7`='En los tramos orientales de los Campos de Ala Abisal se encuentra la Fortaleza Faucedraco. Es allí donde el cruel clan de orcos Faucedraco tortura a los dracos que capturan intentando doblegarlos a su voluntad. Muchos han perdido la esperanza y ceden a la voluntad de los Faucedraco. Los demás... se niegan a desembarcar por miedo a que las partidas de guerra Faucedraco los capturen y los lleven de vuelta a la fortaleza.' WHERE `ID`=19864;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만, 당신의 종족은 용이잖아요! 어떻게 오크들에게 그런 능력이 있습니까?', `MaleText_loc4`='但你们是龙啊！这些兽人怎么敢这样对待你们？', `MaleText_loc5`='但你們是龍!獸人怎能對你做這些事?', `MaleText_loc7`='¡Pero sois dragones! ¿Cómo os pudieron hacer esto los orcos?', `FemaleText_loc1`='하지만, 당신의 종족은 용이잖아요! 어떻게 오크들에게 그런 능력이 있습니까?', `FemaleText_loc4`='但是你们是龙！这些兽人怎么敢这样对待你们？', `FemaleText_loc5`='但你們是龍!獸人怎能對你做這些事?', `FemaleText_loc7`='¡Pero sois dragones! ¿Cómo os pudieron hacer esto los orcos?' WHERE `ID`=19865;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는... 우리에게는 힘이 없다. 일리단은 줄루헤드를 찾아 용아귀 오크들의 지도자로 보냈다. 이 오크는 알렉스트라자를 사로잡아 감금했던 인물이다. 그런 힘을 가진 자에게 우리가 어떻게 맞서겠나? 위상을 사로잡았던 자에게!$B$B그리고 더더욱 그럴 수 없었던 이유는 놈이 그녀를 데려갔기 때문이다.', `MaleText_loc4`='我……我们无力反抗。伊利丹找到了龙喉氏族的首领祖鲁希德。他曾经参与过抓获和囚禁阿莱克丝塔萨的行动。我们要怎么才能反抗这样的力量呢？他甚至曾经捕获过一只强大的守护巨龙！$B$B而且他同样这么简单地捕获了我的配偶。', `MaleText_loc5`='我...我們是弱小的。伊利丹發現並且交給龍喉他們的領導人--祖魯希德。這個獸人就是負責捕捉和監禁雅立史卓莎的那個。我們怎能與這樣的力量戰鬥?他抓住了一名守護巨龍!$B$B而且一樣容易地，帶走了我的夥伴。', `MaleText_loc7`='Yo... No tenemos ningún poder. Illidan encontró y entregó a los Faucedraco a su líder - Zuluhed. Este orco era el único responsable de la captura y encarcelamiento de Alexstrasza. ¿Cómo podríamos luchar contra tal poder? ¡Capturó a un Aspecto!$B$BY con igual facilidad, se llevó a mi compañera.' WHERE `ID`=19866;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 연인을 말입니까?', `MaleText_loc4`='你的配偶？', `MaleText_loc5`='你的朋友?', `MaleText_loc7`='¿Tu compañera?', `FemaleText_loc1`='당신의 연인을 말인가요?', `FemaleText_loc4`='你的配偶？', `FemaleText_loc5`='你的朋友?', `FemaleText_loc7`='¿Tu compañera?' WHERE `ID`=19867;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<고개를 끄덕이는 넬타라쿠>$B$B카리나쿠... 그녀는 용아귀 요새 꼭대기에 갇혀 있다. 난 여러 차례 그녀를 구하려고 시도했지만. 모두 실패했다. 그대는 그 괴물들과 싸운 경험이 있는 걸로 아는데... 내 말이 맞나?', `MaleText_loc4`='<奈尔萨拉库点了点头。>$B$B卡瑞纳库……她被关押在龙喉要塞的顶部。为了解救她，我已经试遍了各种方法。不幸的是，所有的尝试都失败了……你曾经和这些野蛮的家伙战斗过吗？', `MaleText_loc5`='<奈爾斯阿拉古點頭。>$B$B凱瑞納古...她被關在龍喉堡壘頂端。我已經做了很多嘗試去解救她。全部都失敗了...你以前曾與這些野獸戰鬥過，不是嗎?', `MaleText_loc7`='<Neltharaku asiente.>$B$BKarynaku... está prisionera en lo alto de la Fortaleza Faucedraco. He intentado liberarla muchas veces. He fracasado todas ellas... Has luchado antes contra esas bestias, ¿no es cierto?' WHERE `ID`=19868;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용이여, 지금까지 저는 수많은 적과 싸웠습니다. 당신을 돕겠습니다.', `MaleText_loc4`='我与许多野蛮的家伙都战斗过，龙。我会帮你的。', `MaleText_loc5`='我曾經跟很多野獸、龍戰鬥過。我會幫助你。', `MaleText_loc7`='He luchado contra muchas bestias, dragón. Te ayudaré.', `FemaleText_loc1`='용이여, 지금까지 저는 수많은 적과 싸웠습니다. 당신을 돕겠습니다.', `FemaleText_loc4`='我与许多野蛮的家伙都战斗过，龙。我会帮你的。', `FemaleText_loc5`='我曾經跟很多野獸、龍戰鬥過。我會幫助你。', `FemaleText_loc7`='He luchado contra muchas bestias, dragón. Te ayudaré.' WHERE `ID`=19869;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부탁한다, $n|1이여;여;. 격노의 심장을 안전한 곳으로 가져가야 한다... 자네가 아달에게 가져가라!', `MaleText_loc4`='$n，你必须把愤怒之心带到安全的地方去……你必须把它交给阿达尔！', `MaleText_loc5`='拜託，$n。你必須將狂怒之心帶到某個安全的地方...你必須將它帶給阿達歐!', `MaleText_loc7`='Por favor, $n. Debes llevar el corazón de furia a un lugar seguro... ¡debes llevarlo a A''dal!' WHERE `ID`=19870;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아타말 수정을 포기하시겠다... 일리단을 상대할 그대의 계획이 어떻게 되나 보고 싶다는 이유만으로? 뒤틀린 드레나이여, 이거 어찌할 바를 모르겠군. 아마도 나 혼자 일을 진행해야겠군... 적어도 지금은 말이오.', `FemaleText_loc4`='你愿意放弃阿塔玛水晶吗……只是为了你们反抗伊利丹的计划能够顺利进行？这让我很感兴趣，破碎者。或许，我至少暂时会与你合作……', `FemaleText_loc5`='你願意放棄阿塔莫水晶...只是為了徹底實行你對抗伊利丹的計畫嗎?你激起了我的興趣，破碎者。或許我會合作...現在，至少。', `FemaleText_loc7`='¿Me darías un cristal de Ata''mal... solo para llevar a cabo tu plan contra Illidan? Me intrigas, $gTábido:Tábida;. Puede que colabore... por ahora, al menos.' WHERE `ID`=19871;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='반갑네.', `FemaleText_loc4`='Hellfire Peninsula - Mordiba default', `FemaleText_loc5`='地獄火半島 - 莫爾迪巴原始設定問候語', `FemaleText_loc7`='Península del Fuego Infernal - predeterminado de Mordiba' WHERE `ID`=19872;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자 발견! 위험 요소 즉시 제거 요망!', `MaleText_loc4`='发现入侵者！立即终结威胁！', `MaleText_loc5`='發現入侵者!立即消除威脅!', `MaleText_loc7`='¡$gIntruso detectado:Intrusa detectada;! ¡Neutralizando amenaza inmediatamente!' WHERE `ID`=19873;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방어선 붕괴! $R 처치 요망!', `MaleText_loc4`='边界已被突破！消灭$R！！', `MaleText_loc5`='邊緣被破壞!毀滅$R!', `MaleText_loc7`='¡Perímetro transgredido! ¡Destruir $r!' WHERE `ID`=19874;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='허가받지 않은 침입자 발견! 처벌 절차 가동!', `MaleText_loc4`='身份未经确认！防御程序自动激活！', `MaleText_loc5`='發現未經授權的人員!懲罰程序啟動。', `MaleText_loc7`='¡Personal no autorizado identificado! Protocolo de castigo activado.' WHERE `ID`=19875;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동력 수준이 적절해 보이는군. 울트리스 마나괴철로에서 본 것 같은 이상 현상은 전혀 없어.', `MaleText_loc4`='能量水平应该很稳定了。瞧这些参数，至少不像我们在法力熔炉：乌提斯看到那样的那样混乱。', `MaleText_loc5`='力量程度看來足夠。沒有像我們在法力熔爐奧崔斯看見的異常跡象。', `MaleText_loc7`='Los niveles de energía parecen adecuados. No hay signos de anomalías como las que vimos en la Forja de Maná Ultris.' WHERE `ID`=19876;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 황천의 기운을 받고 분노에 휩싸입니다!', `MaleText_loc4`='%s的怒火甚至可以充满整个虚空！', `MaleText_loc5`='%s陷入一陣狂怒!', `MaleText_loc7`='¡%s monta en cólera alimentada por el vacío!' WHERE `ID`=19877;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 계획대로 진행되고 있군. 캘타스 왕자님께서 기뻐하실 거야.', `MaleText_loc4`='所有事情都正按照日程进行着。凯尔萨斯王子会感到非常高兴的。', `MaleText_loc5`='一切事情將按照預定計畫進行。凱爾薩斯王子應該會高興。', `MaleText_loc7`='Todo va según lo planeado. El príncipe Kael''thas debería estar satisfecho.' WHERE `ID`=19878;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 주변에 무능력한 놈들만 득실거리는 이유가 뭘까? 그래도 어쩌면... 부하 중에 쓸 만한 놈이 나올지도 모르지.', `MaleText_loc4`='为什么我身边总是有无数的低能儿呢？好吧，也许在不久将来的某一天，我的某些手下会突然长出个脑子来。', `MaleText_loc5`='為什麼我身邊一定得是些無能的人呢?好吧，或許我的一些下屬最後能長出腦子。', `MaleText_loc7`='¿Por qué debo estar rodeado de incompetentes? Bueno, quizás a alguno de mis subordinados le acabe creciendo un cerebro.' WHERE `ID`=19879;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 물러나며 고함을 지르더니 황천의 문을 엽니다.', `MaleText_loc4`='%s在撤退中大声呼喊着，打开了回到虚空的传送门。', `MaleText_loc5`='%s大聲呼喊撤退，打開通往虛空的門。', `MaleText_loc7`='%s grita en retirada, abriendo las puertas al vacío.' WHERE `ID`=19880;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 할 일은 서로 싸우는 것이 아니라 오우거 일족들을 단결시키는 것입니다.', `MaleText_loc4`='我们需要统一所有食人魔氏族，而不是让各氏族互相争斗。', `MaleText_loc5`='我們應該讓巨魔氏族團結，而不是跟彼此作戰。', `MaleText_loc7`='Deberíamos estar uniendo los clanes de ogros, no luchando unos contra otros.' WHERE `ID`=19881;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 결코 단결할 수 없을까요? 이렇게 서로 싸우고 죽이다가는 언젠가는 사라질 겁니다.', `MaleText_loc4`='我们要什么时候才能学会团结？这样继续互相争斗下去，很快我们就会被历史所遗忘的。', `MaleText_loc5`='我們永遠學不會一起努力嗎?或者我們乾脆地殺掉彼此，並且被遺忘在時間裡。', `MaleText_loc7`='¿Aprenderemos algún día a trabajar juntos? ¿O simplemente nos mataremos el uno al otro y se nos olvidará con el tiempo?' WHERE `ID`=19882;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='각 부족의 지도자들은 내 말을 들어야 합니다. 단결만이 살길이에요. 그 외에는 파멸을 면할 방법이 없습니다.', `MaleText_loc4`='真希望各氏族的首领都能过来听一听我的话。团结是唯一的生存之道，任何其它道路都只会给我们带来毁灭的结局。', `MaleText_loc5`='要是部落的領導人能聽信該多好。團結是唯一的答案。所有其他道路都將引導我們步向毀滅。', `MaleText_loc7`='Si al menos escucharan los líderes de los clanes. Todos los caminos llevan a nuestra destrucción.' WHERE `ID`=19883;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='단결하자는 나의 연설은 우리 오우거 일족들을 위한 것이지 $R, 너희한테 한 말이 아니야!', `MaleText_loc4`='我的团结号召是针对各食人魔氏族的，而不是你，$R！', `MaleText_loc5`='我的團結訊息是給巨魔氏族，不是給你的，$R!', `MaleText_loc7`='¡Mi mensaje de unidad va dirigido a los clanes de ogros, no a ti, $r!' WHERE `ID`=19884;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 이상 내 동족을 죽이게 놔둘 수 없다! 죽을 준비나 해라!', `MaleText_loc4`='我再也不能允许你杀死我的同胞了！受死吧！', `MaleText_loc5`='我不允許你再殺死任何一個我的族人!準備死吧!', `MaleText_loc7`='¡No permitiré que mates a nadie más de mi especie! ¡Prepárate para morir!' WHERE `ID`=19885;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈을 오우거 공공의 적으로 선포한다. 형벌은 바로 죽음이다!', `MaleText_loc4`='我宣布你是食人魔氏族的敌人，你将被判处死刑！', `MaleText_loc5`='我判決你是巨魔氏族的敵人。死亡就是懲罰!', `MaleText_loc7`='Decreto que eres $gun enemigo:una enemiga; de los clanes de ogros. ¡El castigo es la muerte!' WHERE `ID`=19886;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훌륭해! 신선한 육체가 있군!', `MaleText_loc4`='太棒了！新鲜的零件！', `MaleText_loc5`='太好了!新鮮的零件!', `MaleText_loc7`='¡Excelente! ¡Partes nuevas!' WHERE `ID`=19887;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모든 장기를 실험용으로 기증하겠다니 이렇게 친절할 데가!', `MaleText_loc4`='真高兴，又有人来捐献器官了！', `MaleText_loc5`='你能捐贈器官真是太好心了!', `MaleText_loc7`='¡Es muy amable por tu parte que dones tus órganos!' WHERE `ID`=19888;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기뻐해라. 네놈의 뇌는 누더기골렘에 넣어서 잘 재활용할 테니까.', `MaleText_loc4`='你的大脑会在某个憎恶身上发挥很好的作用，为此自豪吧。', `MaleText_loc5`='驕傲點，你的大腦將在一個我憎惡的事物上充分發揮作用。', `MaleText_loc7`='Puedes sentirte $gorgulloso:orgullosa;, tu cerebro tendrá buen uso en una de mis abominaciones.' WHERE `ID`=19889;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대가 찾는 정보는... 공짜로 줄 순 없지. 우리가 공통의 적을 노리고 있다는 사실을 먼저 증명해 보이게나.', `MaleText_loc4`='我不能那么慷慨地……与你分享信息。你必须向我证明，你与我有着共同的敌人。', `MaleText_loc5`='你尋找的訊息...我不能免費給你。你必須證明你和我同仇敵愾。', `MaleText_loc7`='La información que buscas... no puedo dártela tan libremente. Tendrás que demostrar que tus enemigos son los mismos que los míos.' WHERE `ID`=19890;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만! 네놈의 지저분하고 뜨끈한 피는 이미 충분히 맛봤다!', `MaleText_loc4`='够了！我受够你们这些肮脏的热血生物了！', `MaleText_loc5`='夠了!我已經受夠了你污穢溫暖的鮮血!', `MaleText_loc7`='¡Ya basta! ¡Ya he tenido bastante con ustedes, sucios sangre caliente!' WHERE `ID`=19891;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청하고 우스운 것... 박살 내주마!', `MaleText_loc4`='愚蠢的小家伙！我打！', `MaleText_loc5`='愚蠢弱小的東西。我要重擊你!', `MaleText_loc7`='Cosa estúpida y endeble. ¡Yo romper!' WHERE `ID`=19892;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='열 받았어. 얼굴에 한 방 날린다!', `MaleText_loc4`='我抓狂了。我要抽你的脸！', `MaleText_loc5`='我發狂了。你的臉會被重重一擊!', `MaleText_loc7`='Yo enfadado. ¡Yo golpear en cara a ti!' WHERE `ID`=19893;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='화났다. 으아아아!', `MaleText_loc4`='我生气了。啊呀呀呀呀呀呀！', `MaleText_loc5`='我生氣了。啊啊啊!', `MaleText_loc7`='Yo enfadado. ¡Aaaah!' WHERE `ID`=19894;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조만간 파멸의 군주 카자크께서 저 불쌍한 오크와 인간들에게 우리의 진정한 힘을 보여주실 것이다!', `MaleText_loc4`='末日领主卡扎克很快就会在这些可怜的兽人和人类身上倾泻我们全部的力量。', `MaleText_loc5`='毀滅領主卡札克很快將釋放我們全部的力量對付這些可憐的獸人和人類!', `MaleText_loc7`='¡El Señor de fatalidad Kazzak pronto liberará todo nuestro poder sobre esos lamentables orcos y humanos!' WHERE `ID`=19895;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형제들아, 준비하라! 우리는 어둠의 문을 넘어서 아제로스 전체를 무너뜨릴 것이다!', `MaleText_loc4`='准备好，弟兄们！我们马上就可以成功地穿越黑暗之门，整个艾泽拉斯世界也将被我们践踏在脚下！', `MaleText_loc5`='準備好我的兄弟!我們將透過黑暗之門前進，艾澤拉斯的一切都將毀滅!', `MaleText_loc7`='¡Preparaos, hermanos! ¡Nos abriremos camino por el Portal Oscuro y toda Azeroth caerá!' WHERE `ID`=19896;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 파멸의 군주 카자크 님의 뜻을 전파하는 사자들이다! 힘을 키워라! 정신을 바짝 차려라! 그 어떤 것도 불타는 군단의 길을 가로막지 못하게 해라!', `MaleText_loc4`='我们只效忠于末日领主卡扎克！坚强些！提高警惕！任何东西都休想阻挡燃烧军团前进的步伐！', `MaleText_loc5`='我們是毀滅領主卡札克意志執行者!堅強點!警惕點!沒有什麼可以阻礙燃燒軍團的道路!', `MaleText_loc7`='¡No somos más que extensiones de la voluntad del Señor de fatalidad Kazzak! ¡Sé fuerte! ¡Mantente alerta! ¡No dejes que nada se interponga en el camino de la Legión Ardiente!' WHERE `ID`=19898;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='군주의 명령에 복종하고 불타는 군단 사이에서 명예를 얻어라. 실수는 곧 죽음이다!', `MaleText_loc4`='遵守他的命令并以身为燃烧军团的一员而感到自豪吧。如果谁胆敢怯战逃跑，他就必将被消灭！', `MaleText_loc5`='服從他的命令並受燃燒軍團尊敬。若有動搖你將被毀滅!', `MaleText_loc7`='Obedece sus órdenes y serás $ghonrado:honrada; entre la Legión Ardiente. ¡Vacila y serás $gconsumido:consumida;!' WHERE `ID`=19899;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 적의 피로 목욕하는 걸 좋아하지!', `MaleText_loc4`='我喜欢沐浴在敌人的鲜血中！', `MaleText_loc5`='我喜歡沐浴在敵人的鮮血裡。', `MaleText_loc7`='¡Me encanta bañarme en la sangre de mis enemigos!' WHERE `ID`=19900;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사방에서 캘타스와 일리단을 상대로 전투가 벌어지고 있습니다. 절대 패배해서는 안 됩니다!', `FemaleText_loc4`='与凯尔萨斯和伊利丹的战斗仍然在前线继续进行着。我们只可成功，不许失败。', `FemaleText_loc5`='對抗凱爾薩斯和伊利丹的戰役在所有前線上持續著。戰敗不是一種選擇。', `FemaleText_loc7`='La lucha contra Kael''thas e Illidan continúa en todos los frentes. La derrota no es una opción.' WHERE `ID`=19901;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈을 없애고 온전히 묻히지 않게 하리라.', `MaleText_loc4`='等我砍下你的肢体后，一定要把它挂在城墙上。', `MaleText_loc5`='一旦我砍斷你的四肢，我要把你的身體掛在我們的城垛上。', `MaleText_loc7`='Cuando te haya cortado los miembros, quizás cuelgue tu cuerpo de nuestras almenas.' WHERE `ID`=19902;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈이 죽는 꼴을 꼭 봐야겠다!', `MaleText_loc4`='我渴望着你的死亡！', `MaleText_loc5`='我渴望你的死!', `MaleText_loc7`='¡Ansío tu muerte!' WHERE `ID`=19903;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 안녕하신가. 성스러운 빛의 친구라면 샤타르 제단에서 언제든지 환영받지.', `MaleText_loc4`='你好，$n。所有圣光的伙伴在沙塔尔祭坛都会受到欢迎。', `MaleText_loc5`='嗨，$n。薩塔祭壇歡迎所有聖光的朋友。', `MaleText_loc7`='Saludos, $n. Todos los amigos de la Luz son bienvenidos en el Altar de Sha''tar.' WHERE `ID`=19904;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고룡교단은 분명 다른 경로를 이용하고 있소. 우린 아직도 루안 숲 속에서 그들을 찾고 있지 않소?', `MaleText_loc4`='拜龙教肯定走了另一条路。我们仍然可以在卢安荒野看到他们。', `MaleText_loc5`='巨龍教團一定正使用另一條道路。我們仍然可在魯安曠野找到他們。', `MaleText_loc7`='El Culto Vermis debe de estar usando otro camino. Los seguimos encontrando en la Foresta Ruuan.', `FemaleText_loc1`='고룡교단은 분명 다른 경로를 이용하고 있소. 우린 아직도 루안 숲 속에서 그들을 찾고 있소.', `FemaleText_loc4`='拜龙教肯定走了另一条路。我们仍然可以在卢安荒野看到他们。', `FemaleText_loc5`='巨龍教團一定正使用另一條道路。我們仍然可在魯安曠野找到他們。', `FemaleText_loc7`='El Culto Vermis debe de estar usando otro camino. Los seguimos encontrando en la Foresta Ruuan.' WHERE `ID`=19905;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 영혼을 무한한 공허 속으로 던져버리겠다!', `MaleText_loc4`='我要把你的灵魂送入无尽的虚空！', `MaleText_loc5`='我會把你的靈魂送到無限的虛無中!', `MaleText_loc7`='¡Enviaré tu alma al vacío infinito!' WHERE `ID`=19906;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 암흑 속으로 널 집어삼켜 버리겠다!', `MaleText_loc4`='让我的黑暗吞噬你吧！', `MaleText_loc5`='讓我的黑暗把你吞沒!', `MaleText_loc7`='¡Deja que mi oscuridad te absorba!' WHERE `ID`=19907;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공허 속에서는 아무도 네 비명을 듣지 못한다!', `MaleText_loc4`='在虚空中，没人可以听到你的惨叫！', `MaleText_loc5`='在虛無中，沒有人能聽到你的尖叫!', `MaleText_loc7`='¡En el vacío, nadie te podrá oír gritar!' WHERE `ID`=19908;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드의 용감한 오크들이여! 이 문은 그대들을 새로운 운명으로 안내할 것이다! 사냥감이 가득한 아제로스가 그대들을 기다리고 있도다!', `MaleText_loc4`='部落的兽人们！这个入口将是通向全新命运的道路！艾泽拉斯就在你的面前，等待着你们去占领。', `MaleText_loc5`='部落的獸人!這個傳送門是通往你的新命運的途徑!艾澤拉斯就在你的眼前，等待採收!', `MaleText_loc7`='¡Orcos de la Horda! ¡Este portal es la entrada a su nuevo destino! ¡Azeroth está ante ustedes, esperándolos!' WHERE `ID`=19909;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='', `MaleText_loc4`='', `MaleText_loc5`='', `MaleText_loc7`='' WHERE `ID`=19910;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='굴단 님은 진실을 말씀하신다! 우리는 즉시 돌아가서 형제들에게 이 소식을 알려야 한다! 차원문을 통해 돌아가도록!', `MaleText_loc4`='古尔丹说得不错！我们应该一起回去把这个消息告诉我们的弟兄们！从黑暗之门撤退！', `MaleText_loc5`='古爾丹說得沒錯!我們應該立刻回去告訴我們的兄弟這個消息!通過傳送門撤退!', `MaleText_loc7`='¡Gul''dan dice la verdad! ¡Deberíamos volver de inmediato para contar las noticias a nuestros hermanos! ¡Retirarnos a través del portal!' WHERE `ID`=19911;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 여기서 기다려야 하오. 그자들이 굴 내부를 확인하고자 다른 이들을 정찰 보냈소.', `MaleText_loc4`='我们得在这里等着。他们已经派人进去侦查了。', `MaleText_loc5`='我們要在這裡等待。他們派其它人先行檢查隧道內部。', `MaleText_loc7`='Debemos esperar aquí. Enviaron a otros primero para comprobar el interior del túnel.', `FemaleText_loc1`='우리는 여기서 기다려야 하오. 그자들이 굴 내부를 확인하고자 다른 이들을 정찰 보냈소.', `FemaleText_loc4`='我们得在这里等着。他们已经派人进去侦查了。', `FemaleText_loc5`='我們要在這裡等待。他們派其它人先行檢查隧道內部。', `FemaleText_loc7`='Debemos esperar aquí. Enviaron a otros primero para comprobar el interior del túnel.' WHERE `ID`=19912;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 내 눈을 가져가려 하다니! 네 영혼을 박살내서 앞이 보이지 않아 울먹이는 내 임프에게 먹이로 주고 말겠다!', `MaleText_loc4`='你居然胆敢拿走我的眼睛！我要碾碎你的灵魂，用它来祭奠我盲目和怨怒的小鬼！', `MaleText_loc5`='你竟敢拿走我的眼睛!我會粉碎你的靈魂並且把它餵給我瞎眼弱小的小鬼!', `MaleText_loc7`='¡Cómo osas llevarte mi ojo! ¡Aplastaré tu alma y alimentaré con ella a mis diablillos ciegos y quejumbrosos!' WHERE `ID`=19913;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 둥지로 와라, 건방진 것! 와서 그 무례함의 대가를 치러라!', `MaleText_loc4`='到我的巢穴来吧，小崽子们！到我这里来，为你们的傲慢付出代价吧！', `MaleText_loc5`='進來我的藏身處，小鬼!來我這裡，並為你的無禮付出代價!', `MaleText_loc7`='¡Ven a mi guarida, cachorro! ¡Ven a mí y paga por tu insolencia!' WHERE `ID`=19914;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='선구자여, 성스러운 빛이 함께하기를...', `FemaleText_loc4`='圣光与你同在，先驱者。', `FemaleText_loc5`='聖光與你同在，先驅者。', `FemaleText_loc7`='Que la Luz sea contigo, presagista.' WHERE `ID`=19915;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='일리단이 움직이지 않는 이유가 대체 뭐지? 이렇게 마냥 기다리고만 있으니 병사들이 불안해하고 있소.', `FemaleText_loc4`='为什么伊利丹还没有开始行动？我们的军队已经等得心神不安了。', `FemaleText_loc5`='伊利丹為什麼還沒行動?這樣的等待讓我們的部隊感到不安。', `FemaleText_loc7`='¿Por qué no ha dado su paso Illidan? Toda esta espera está haciendo que nuestras tropas estén intranquilas.' WHERE `ID`=19916;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대체 어떤 존재가 저 사악한 고룡교단을 섬기는 것이오?', `MaleText_loc4`='什么东西竟然会为那些险恶的拜龙教效力？', `MaleText_loc5`='能為那些不幸的巨龍教團鄙惡者做些什麼事?', `MaleText_loc7`='¿Qué tipo de cosa serviría a esos despreciables y siniestros Cultos Vermis?', `FemaleText_loc1`='대체 어떤 존재가 저 사악한 고룡교단을 섬기는 겁니까?', `FemaleText_loc4`='什么东西竟然会为那些险恶的拜龙教效力？', `FemaleText_loc5`='能為那些不幸的巨龍教團鄙惡者做些什麼事?', `FemaleText_loc7`='¿Qué tipo de cosa serviría a esos despreciables y siniestros Cultos Vermis?' WHERE `ID`=19917;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='총독님, 배신자는 그 행동을 예측할 수 없는 적입니다. 그렇다고 제가 두려워하는 것은 아닙니다. 성스러운 빛이 우리와 함께하는 한 우리는 오늘, 또는 그가 공격을 결정하는 그날 반드시 승리할 것입니다.', `MaleText_loc4`='背叛者并不是一个循规蹈矩的敌人，大主教。但不管怎样，我一点也不害怕他，因为圣光与我们同在。今天，明天，或者无论什么时候，他若选择进攻，我们就能打败他！', `MaleText_loc5`='背叛者不是最可預測的仇敵，主教。但是我沒有恐懼，有聖光站在我這邊，不管今天、明天、或任何他選擇攻擊的時候，我們都將擊敗他。', `MaleText_loc7`='El Traidor no ha sido el más predecible de los enemigos, Exarca. Sin embargo, no tengo miedo; con la Luz de nuestra parte derrotaremos a sus tropas hoy, mañana o cuando decida atacar.' WHERE `ID`=19918;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 주인이 누군지 잊지 마라. 일리단 님께서 이 세계와 그 너머를 통치하실 것이다.', `MaleText_loc4`='永远不要忘记你在为谁效力。伊利丹会统治这个世界，以及所有的世界。', `MaleText_loc5`='絕對不要忘記你效忠於誰。伊利丹將統治這塊土地和更遠之處。', `MaleText_loc7`='Nunca olvides a quién sirves. Illidan gobernará esta tierra y más allá.' WHERE `ID`=19919;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고룡교단은 어떻게 그 많은 추종자들을 거느리고 있는 거요? 그들은 대체 어디서 온 겁니까?!', `MaleText_loc4`='拜龙教是怎么弄到这么多追随者的？他们是哪里来的？！', `MaleText_loc5`='巨龍教團如何獲得那麼多的跟隨者?他們從哪來的?!', `MaleText_loc7`='¿Cómo ha conseguido tantos seguidores el Culto Vermis? ¡¿De dónde vienen?!', `FemaleText_loc1`='고룡교단은 어떻게 그 많은 추종자들을 거느리고 있지요? 그들은 대체 어디서 온 겁니까?!', `FemaleText_loc4`='拜龙教是怎么弄到这么多追随者的？他们是哪里来的？！', `FemaleText_loc5`='巨龍教團如何獲得那麼多的跟隨者?他們從哪來的?!', `FemaleText_loc7`='¿Cómo ha conseguido tantos seguidores el Culto Vermis? ¡¿De dónde vienen?!' WHERE `ID`=19920;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님께서는 완전한 복종을 바라신다. 너는 그 명령을 따르게 될 것이다!', `MaleText_loc4`='主人希望得到你完全的服从，你必须应允！', `MaleText_loc5`='主人希望你完全的服從而你要遵從!', `MaleText_loc7`='¡El maestro desea tu obediencia total, y tú cumplirás!' WHERE `ID`=19921;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조만간 적들은 우리에게 자비를 구걸하리라. 그렇지 않으면 우리 발아래 한 줌의 재로 변할 테니까!', `MaleText_loc4`='很快，我们所有的敌人都会祈求我们的仁慈，或成为我们脚下的碎骨！', `MaleText_loc5`='很快地我們全部的敵人都將求饒或是成為我們腳下被粉碎的骨頭!', `MaleText_loc7`='¡Nuestros enemigos pronto suplicarán misericordia o serán huesos aplastados bajo nuestros pies!' WHERE `ID`=19922;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 온 지 얼마 안 되는 분이시군요... 그렇다면, 우리 전통에 대해서도 잘 모르시겠군요? 달숲에서 굉장한 축제가 열리고 있어요. 해마다 우리의 선조를 기리는 시기가 바로 지금입니다. 당신도 초대를 받았어요! 축제를 함께 즐기고 싶다면 아무 대도시로나 가십시오!', `MaleText_loc4`='据我所知，你最近才加入我们，可能并不清楚我们的传统。月光林地那边正在举办一场庞大的庆典。这是一年一度向长者们致敬的日子，你被邀请了！如果你想加入的话，去任何一座城市都可以！', `MaleText_loc5`='我了解你最近才加入我們，因此可能沒注意到我們的傳統。在月光林地裡，一個盛大的慶典正在進行。這是我們榮耀祖先的時刻，而你當然被邀請了!如果你願意參加，就前往我們的城市之一!', `MaleText_loc7`='Me doy cuenta de que hace poco que te has unido a nosotros y, por eso, puede que no conozcas nuestras tradiciones. En Claro de la Luna, está teniendo lugar una celebración estupenda. Es una época del año en la que honramos a nuestros ancestros, y desde luego, ¡estás $ginvitado:invitada;! ¡Viaja hasta una de nuestras ciudades si deseas unirte a nosotros!', `FemaleText_loc1`='여기 온 지 얼마 안 되는 분이시군요... 그렇다면, 우리 전통에 대해서도 잘 모르시겠군요? 달숲에서 굉장한 축제가 열리고 있어요. 해마다 우리의 선조를 기리는 시기가 바로 지금입니다. 당신도 초대를 받았어요! 축제를 함께 즐기고 싶다면 아무 대도시로나 가십시오!', `FemaleText_loc4`='据我所知，你最近才加入我们，可能并不清楚我们的传统。月光林地那边正在举办一场庞大的庆典。这是一年一度向长者们致敬的日子，你被邀请了！如果你想加入的话，去任何一座城市都可以！', `FemaleText_loc5`='我了解你最近才加入我們，因此可能沒注意到我們的傳統。在月光林地裡，一個盛大的慶典正在進行。這是我們榮耀祖先的時刻，而你當然被邀請了!如果你願意參加，就前往我們的城市之一!', `FemaleText_loc7`='Me doy cuenta de que hace poco que te has unido a nosotros y, por eso, puede que no conozcas nuestras tradiciones. En Claro de la Luna, está teniendo lugar una celebración estupenda. Es una época del año en la que honramos a nuestros ancestros, y desde luego, ¡estás $ginvitado:invitada;! ¡Viaja hasta una de nuestras ciudades si deseas unirte a nosotros!' WHERE `ID`=19923;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 고개를 돌려 뒤를 바라보며 조용하게 투덜거립니다.', `MaleText_loc4`='%s发出了一声低吼，看了看自己的后面。', `MaleText_loc5`='%s發出低沉，平靜的嗥叫，順著它的肩膀回頭望。', `MaleText_loc7`='%s emite un gruñido silencioso mientras mira por encima del hombro.', `FemaleText_loc1`='%s|1이;가; 고개를 돌려 뒤를 바라보며 조용하게 투덜거립니다.', `FemaleText_loc4`='%s发出了一声低吼，看了看自己的后面。', `FemaleText_loc5`='%s發出低沉，平靜的嗥叫，順著它的肩膀回頭望。', `FemaleText_loc7`='%s emite un gruñido silencioso mientras mira por encima del hombro.' WHERE `ID`=19924;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐 찾은 게 있소이까?', `MaleText_loc4`='你看到了什么？有什么东西吗？', `MaleText_loc5`='你看到什麼?有東西嗎?', `MaleText_loc7`='¿Qué ves? ¿Algo?', `FemaleText_loc1`='뭐 찾은 게 있나요?', `FemaleText_loc4`='你看到了什么？有什么东西吗？', `FemaleText_loc5`='你看到什麼?有東西嗎?', `FemaleText_loc7`='¿Qué ves? ¿Algo?' WHERE `ID`=19925;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앞에 고룡교단이 있소?', `MaleText_loc4`='拜龙教就在前面？', `MaleText_loc5`='前面有巨龍教團的人嗎?', `MaleText_loc7`='¿Hay algún Culto Vermis delante?', `FemaleText_loc1`='앞에 고룡교단이 있나요?', `FemaleText_loc4`='拜龙教就在前面？', `FemaleText_loc5`='前面有巨龍教團的人嗎?', `FemaleText_loc7`='¿Hay algún Culto Vermis delante?' WHERE `ID`=19926;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들을 찾았소?', `MaleText_loc4`='你找到他们了吗？', `MaleText_loc5`='你找到他們了嗎?', `MaleText_loc7`='¿Los has encontrado?', `FemaleText_loc1`='그들을 찾았나요?', `FemaleText_loc4`='你找到他们了吗？', `FemaleText_loc5`='你找到他們了嗎?', `FemaleText_loc7`='¿Los has encontrado?' WHERE `ID`=19927;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 위에 그들이 얼마나 많이 있소?', `MaleText_loc4`='他们有很多人吗？', `MaleText_loc5`='那裡，有很多他們的人嗎?', `MaleText_loc7`='¿Hay muchos allí arriba?', `FemaleText_loc1`='저 위에 그들이 얼마나 많이 있나요?', `FemaleText_loc4`='他们有很多人吗？', `FemaleText_loc5`='那裡，有很多他們的人嗎?', `FemaleText_loc7`='¿Hay muchos allí arriba?' WHERE `ID`=19928;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽어라, 쓰레기 같은 점술가 길드 놈!', `MaleText_loc4`='去死吧，占星者猪！', `MaleText_loc5`='死吧，占卜者人渣!', `MaleText_loc7`='¡Muere, escoria Arúspice!' WHERE `ID`=19929;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알도르 사제회의 개들을 해치워라!', `MaleText_loc4`='消灭这些奥尔多狗！', `MaleText_loc5`='摧毀這些奧多爾無賴!', `MaleText_loc7`='¡Destruye a esos perros Aldor!' WHERE `ID`=19930;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 아제로스에서는 달의 축제가 한창입니다! 이 흥겨운 명절에 아제로스로 돌아가서 조상을 기리는 시간을 가져보세요! 달숲으로 가면 축제를 가장 화끈하게 즐길 수 있죠. 스톰윈드, 아이언포지, 다르나서스, 썬더 블러프, 오그리마, 그리고 언더시티에서 눈만 깜짝하면 달숲으로 순간이동할 수 있어요. 그럼, 축제에서 뵙죠!', `MaleText_loc4`='艾泽拉斯各地都在庆祝春节！回到那边去吧，在这个伟大的节日向你的长者表达敬意吧！最大的庆典活动会在月光林地举行，但我们在暴风城、铁炉堡、达纳苏斯、雷霆崖、奥格瑞玛和幽暗城也都提供了方便快捷的传送器。希望能在那边见到你，一定要来哦！', `MaleText_loc5`='艾澤拉斯正在全力慶祝新年慶典!回到那裡，並在此精采的慶典上向你的長者致敬!主要的慶典可在月光林地找到，而我們有提供自暴風城、鐵爐堡、達納蘇斯、雷霆崖、奧格瑪、和幽暗城的簡易傳送。我們希望在那裡見到你!', `MaleText_loc7`='¡El Festival Lunar está totalmente en marcha en Azeroth! ¡Vuelve allí y honra a tus ancianos en esta maravillosa celebración! Los principales festejos se pueden encontrar en Claro de la Luna, pero hemos proporcionado un transporte cómodo desde Ventormenta, Forjaz, Darnassus, Cima del Trueno, Orgrimmar, y Entrañas. ¡Esperamos verte allí!', `FemaleText_loc1`='지금 아제로스에서는 달의 축제가 한창입니다! 이 흥겨운 명절에 아제로스로 돌아가서 조상을 기리는 시간을 가져보세요! 달숲으로 가면 축제를 가장 화끈하게 즐길 수 있죠. 스톰윈드, 아이언포지, 다르나서스, 썬더 블러프, 오그리마, 그리고 언더시티에서 눈만 깜짝하면 달숲으로 순간이동할 수 있어요. 그럼, 축제에서 뵙죠!', `FemaleText_loc4`='艾泽拉斯各地都在庆祝春节！回到那边去吧，在这个伟大的节日向你的长者表达敬意吧！最大的庆典活动会在月光林地举行，但我们在暴风城、铁炉堡、达纳苏斯、雷霆崖、奥格瑞玛和幽暗城也都提供了方便快捷的传送器。希望能在那边见到你，一定要来哦！', `FemaleText_loc5`='艾澤拉斯正在全力慶祝新年慶典!回到那裡，並在此精采的慶典上向你的長者致敬!主要的慶典可在月光林地找到，而我們有提供自暴風城、鐵爐堡、達納蘇斯、雷霆崖、奧格瑪、和幽暗城的簡易傳送。我們希望在那裡見到你!', `FemaleText_loc7`='¡El Festival Lunar está totalmente en marcha en Azeroth! ¡Vuelve allí y honra a tus ancianos en esta maravillosa celebración! Los principales festejos se pueden encontrar en Claro de la Luna, pero hemos proporcionado un transporte cómodo desde Ventormenta, Forjaz, Darnassus, Cima del Trueno, Orgrimmar, y Entrañas. ¡Esperamos verte allí!' WHERE `ID`=19931;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐야? 여기가 어디죠? 말도 안 돼! 당신 꼴을 좀 보세요! 그리고 이곳은 정말! 목록에도 없는데! 어휴, 서류가 잔뜩 밀렸을 텐데...$b$b<조그만 공책에 미친 듯이 기록을 하는 고블린>$b$b이봐, 여기 이러고 서서 구경만 할 바에 내 사촌 덜렁발 큐이피를 찾아가 보는 게 어때요? 대도시 중 한 곳에 있을 거요. 그러니까, 오그리마, 스톰윈드, 썬더 블러프, 아이언포지, 언더시티, 다르나서스를 돌보고 있죠. 어서, 어서 가라니까요!', `MaleText_loc4`='什么？我在哪里？这根本不对！看看你！看看这个地方！它不在我的列表上啊！看来又得搞一大堆文件了……$B$B<地精疯狂地在一个小本上写着东西。>$b$b看，要是你除了站在这里和东张西望以外没有其他事情可做的话，为什么不去各大城市拜访一下我的表兄弟匹德菲特呢？据说他正照顾着奥格瑞玛、暴风城、雷霆崖、铁炉堡、幽暗城和达纳苏斯的事务。去吧，离开这里！', `MaleText_loc5`='什麼?這是哪裡?這根本不對!看看你!看看這個地方!這不在我的清單上!肯定會有非常多的文書工作...$b$b<那些哥布林在小筆記本裡瘋狂地寫著。>$b$b看，如果你已經沒有比站在那裡發呆更好的事可做，你怎麼不去拜訪我在主要城市之一的表弟，丘比特·傳播者?聽說他正在處理奧格瑪，暴風城，雷霆崖，鐵爐堡，幽暗城和達納蘇斯的事。去吧，離開這裡!', `MaleText_loc7`='¿Qué? ¿Dónde estoy? ¡Esto no está nada bien! ¡Mírate! ¡Mira este lugar! ¡No está en mi lista! Va a haber mucho papeleo...$b$b<El goblin escribe frenéticamente en una libretita.>$b$bMira, si no tienes nada mejor que hacer que quedarte ahí de pie y mirar, ¿por qué no vas a visitar a mi primo, Kwee Q. Pies Rápidos, a una de las ciudades principales? Aquí dice que se ocupa de Orgrimmar, Ventormenta, Cima del Trueno, Forjaz, Entrañas y Darnassus. ¡Vamos, fuera de aquí!', `FemaleText_loc1`='뭐야? 여기가 어디죠? 말도 안 돼! 당신 꼴을 좀 보세요! 그리고 이곳은 정말! 목록에도 없는데! 어휴, 서류가 잔뜩 밀렸을 텐데...$b$b<조그만 공책에 미친 듯이 기록을 하는 고블린>$b$b이봐, 여기 이러고 서서 구경만 할 바에 내 사촌 덜렁발 큐이피를 찾아가 보는 게 어때요? 대도시 중 한 곳에 있을 거요. 그러니까, 오그리마, 스톰윈드, 썬더 블러프, 아이언포지, 언더시티, 다르나서스를 돌보고 있죠. 어서, 어서 가라니까요!', `FemaleText_loc4`='什么？我在哪里？这根本不对！看看你！看看这个地方！它不在我的列表上啊！看来又得搞一大堆文件了……$B$B<地精疯狂地在一个小本上写着东西。>$b$b看，要是你除了站在这里和东张西望以外没有其他事情可做的话，为什么不去各大城市拜访一下我的表兄弟匹德菲特呢？据说他正照顾着奥格瑞玛、暴风城、雷霆崖、铁炉堡、幽暗城和达纳苏斯的事务。去吧，离开这里！', `FemaleText_loc5`='什麼?這是哪裡?這根本不對!看看你!看看這個地方!這不在我的清單上!肯定會有非常多的文書工作...$b$b<那些哥布林在小筆記本裡瘋狂地寫著。>$b$b看，如果你已經沒有比站在那裡發呆更好的事可做，你怎麼不去拜訪我在主要城市之一的表弟，丘比特·傳播者?聽說他正在處理奧格瑪，暴風城，雷霆崖，鐵爐堡，幽暗城和達納蘇斯的事。去吧，離開這裡!', `FemaleText_loc7`='¿Qué? ¿Dónde estoy? ¡Esto no está nada bien! ¡Mírate! ¡Mira este lugar! ¡No está en mi lista! Va a haber mucho papeleo...$b$b<El goblin escribe frenéticamente en una libretita.>$b$bMira, si no tienes nada mejor que hacer que quedarte ahí de pie y mirar, ¿por qué no vas a visitar a mi primo, Kwee Q. Pies Rápidos, a una de las ciudades principales? Aquí dice que se ocupa de Orgrimmar, Ventormenta, Cima del Trueno, Forjaz, Entrañas y Darnassus. ¡Vamos, fuera de aquí!' WHERE `ID`=19932;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 오크들이 반드시 풀어야만 하는 비밀이 이곳에 있네. 우리의 과거, 미래, 그리고 우리 내면을 살펴볼 수 있는 비밀들 말일세.$B$B이 비밀을 푸는 것이 내 소망일세... 자네, 나와 뜻을 함께하지 않겠나?', `MaleText_loc4`='这里有着我们兽人不顾一切想要揭开的秘密。有关我们过去的秘密，有关我们未来的秘密，还有能够反映我们内心的秘密。$B$B我毕生的愿望就是揭开这些秘密的面纱……你愿意和我一起进行研究吗？', `MaleText_loc5`='這個地方有一些我們急於揭露的秘密，獸人。我們的過去，未來，以及窺探我們內心的秘密。$B$B洞察這些秘密是我的希望...你會與我一起走過那條道路嗎?', `MaleText_loc7`='En este lugar yacen misterios que nosotros, los orcos, ansiamos descubrir. Misterios de nuestro pasado, misterios de nuestro futuro y misterios que ofrecen fugaces vistazos a nuestro interior.$B$BMi esperanza es desvelarlos... ¿Me ayudarás a conseguirlo?' WHERE `ID`=19933;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 이런!', `MaleText_loc4`='噢，不！', `MaleText_loc5`='哦，不!', `MaleText_loc7`='¡Oh, no!' WHERE `ID`=19934;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 더는 볼 수가 없구려. 아라코아가 까마귀 숲의 수호자들을 상대로 벌이는 사악한 짓을 막아야 하오!', `MaleText_loc4`='我再也看不下去了。鸦人们企图令乌鸦林的保护者堕落腐化，我们必须粉碎他们邪恶的阴谋！', `MaleText_loc5`='我看不下去了。我們必須破壞阿拉卡正向烏鴉林保衛者所做的邪惡壞事!', `MaleText_loc7`='No puedo seguir mirando. ¡DEBEMOS deshacer este mal que los arakkoa están perpetrando contra los protectores del Bosque del Cuervo!' WHERE `ID`=19935;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어서 와라. 환영식을 제대로 치러줄 테니까!', `FemaleText_loc4`='过来，我会好好欢迎你们的！', `FemaleText_loc5`='過來。我會確保你受到禮貌的對待!', `FemaleText_loc7`='Den un paso adelante. ¡Les daré la bienvenida que se merecen!' WHERE `ID`=19936;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오, 그만 좀 질질 짜라!', `FemaleText_loc4`='啊，不要哀号了。', `FemaleText_loc5`='喔，停止你的啜泣!', `FemaleText_loc7`='¡Oh, deja de lloriquear!' WHERE `ID`=19937;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='임무 완료!', `FemaleText_loc4`='任务完成！', `FemaleText_loc5`='任務完成!', `FemaleText_loc7`='¡Misión cumplida!' WHERE `ID`=19938;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이젠 이 몸께서 직접 상대해 주겠다!', `FemaleText_loc4`='你可不是在跟跑龙套的打交道！', `FemaleText_loc5`='你不會再和那些低等生物打交道了!', `FemaleText_loc7`='¡Ya no se enfrentan a un subordinado!' WHERE `ID`=19939;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='반도르 쇼렐러란!', `FemaleText_loc4`='Band''or shorel''aran！', `FemaleText_loc5`='(薩拉斯語)準備道別吧!', `FemaleText_loc7`='¡Band’or shorel’aran!' WHERE `ID`=19940;
