UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 엄청난 에너지를 방출하기 시작합니다!', `MaleText_loc4`='%s开始放射出巨大的能量！', `MaleText_loc5`='%s開始散發出大量能量!', `MaleText_loc7`='¡%s comienza a irradiar enormes cantidades de energía!' WHERE `ID`=20005;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금은 몸 풀기에 불과하지! 진짜 훈련은 훨씬 고될 것이다!', `MaleText_loc4`='把这当成热身运动好了！真正的训练远比这来得艰苦！', `MaleText_loc5`='把這想成是暖身吧!你真正的訓練將嚴厲得多!', `MaleText_loc7`='¡Considéralo un calentamiento! ¡Tu entrenamiento real será mucho más duro!' WHERE `ID`=20006;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성공입니다! 탐지기를 지옥불 성채의 마력에 맞춰서 조정했습니다. 정말 강력한 힘이군요!$B$B그곳에는 타락한 오크들이 헤아릴 수 없이 많습니다... 하지만, 그게 전부가 아닙니다! 성벽 안에서 악마의 힘이 느껴집니다...$B$B당신이 마음을 열면 제가 당신의 정신을 붙잡아서, 간단히 말해서 당신을 조종해서 양피지에 예언 결과를 적어드리겠습니다.', `MaleText_loc4`='成功了！我已经完成了与地狱火堡垒的同调，并与堡垒的魔法能量相互融合。啊，这种力量！$B$B地狱火堡垒中盘踞着不计其数的邪兽人……但是，事情并非如此简单！那些城墙后也涌动着恶魔的力量，我感觉得出……$B$B如果你愿意让我控制你的心灵——别担心，只是暂时的，那么我就能挥笔在羊皮纸上为你记录我发现的一切……', `MaleText_loc5`='成功了!我瞭解地獄火堡壘和它裡面的魔法了!多強大的力量啊!$B$B在那個地方有數不盡的魔獄獸人...而且還不只這樣!我也感覺到在那些牆裡有惡魔的力量...$b$b假如你打開自己的心靈，那麼我就可抓住你的心智 -- 簡短地提醒你 -- 並在羊皮紙上為你記錄下我的發現...', `MaleText_loc7`='¡Éxito! Me he ajustado a la Ciudadela del Fuego Infernal y a la magia que hay en su interior. ¡Ah, tanta energía!$B$BHay innumerables orcos viles en aquel lugar... ¡pero eso no es todo! También siento poder demoníaco dentro de esos muros...$B$BSi te abres, podré comprender tu mente -- brevemente --, tomar pluma y pergamino y registrar mis hallazgos para ti...' WHERE `ID`=20007;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋습니다. 허락하겠어요.', `MaleText_loc4`='当然。你可以控制我。', `MaleText_loc5`='是的，占卜者。你可以擁有我。', `MaleText_loc7`='Sí, arúspice. Puedes poseerme.', `FemaleText_loc1`='좋습니다. 허락하겠어요.', `FemaleText_loc4`='当然。你可以控制我。', `FemaleText_loc5`='是的，占卜者。你可以擁有我。', `FemaleText_loc7`='Sí, arúspice. Puedes poseerme.' WHERE `ID`=20008;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그가 오는 소리를 들은 것 같아.', `MaleText_loc4`='他正朝这边走来，我听得见。', `MaleText_loc5`='我想我聽到他現在正過來呢。', `MaleText_loc7`='Creo que ahora lo oigo venir.' WHERE `ID`=20009;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙네, 친구. 용의 무덤에서 데려온 이 비룡은 숨어 있는 고크를 끌어낼 미끼라네!', `MaleText_loc4`='谢谢你，朋友。这条巨龙之末的幼龙正好做饵，诱使苟克现身！', `MaleText_loc5`='謝謝，我的朋友。這隻來自飛龍之末的龍正是我們需要誘騙苟克現身的東西!', `MaleText_loc7`='Gracias, $gamigo:amiga;. ¡Este draco del Cabo del Dragón es justo lo que necesitamos como cebo para sacar a Goc de su escondite!' WHERE `ID`=20010;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 빨리 가야만 하나? 알았네. 명예로운 여정이 되길 빌겠네.', `MaleText_loc4`='你急着离开吗？好吧，愿你在旅途中总能受到礼遇。', `MaleText_loc5`='你一定要這麼快離開嗎?非常好，願你的旅行會帶給你榮譽。', `MaleText_loc7`='¿Debes irte tan pronto? Muy bien, que tu viaje te dé honor.' WHERE `ID`=20011;
