UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무거운 걸 들어달라고 불렀을 테지.', `MaleText_loc4`='大概是帮你搬东西之类的。', `MaleText_loc5`='大概是要做你那粗重的工作吧。', `MaleText_loc7`='Probablemente para hacer tu trabajo.' WHERE `ID`=20052;
