UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너야말로 철저함과는 거리가... 잠깐, 여기 손님들이 오신 것 같군...', `MaleText_loc4`='你真应该被——等等，我们有伴了……', `MaleText_loc5`='你就是那個應該要─等等，我們有伴了...', `MaleText_loc7`='Tú eres quien debería... Espera: tenemos compañía.' WHERE `ID`=20054;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내가 널 왜 부르겠어?', `FemaleText_loc4`='我为什么要叫你？', `FemaleText_loc5`='什麼?我找你幹嘛?', `FemaleText_loc7`='¿Porque te llamaría?' WHERE `ID`=20055;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='흥, 네 축 쳐진 아랫배를 써먹을 데가 있으면 한번 생각해 보지.', `FemaleText_loc4`='如果我想找人来像个肥胖的孔雀一样走台步，那我会叫你的。', `FemaleText_loc5`='當我想要找個像胖孔雀一樣的人來走台步的時候，我就會找你。', `FemaleText_loc7`='Cuando necesito a alguien para pavonearse como un pavo relleno, te llamo a ti.' WHERE `ID`=20056;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='흥! 네가 철저하게 하는 일이라곤 그것뿐이지? 쉬트 샤?', `FemaleText_loc4`='你还知道保证这个词啊，sheet-sah？', `FemaleText_loc5`='你知道什麼是保證嗎，(惡魔語)混蛋?', `FemaleText_loc7`='¿Qué sabes tú de compromisos, sheet-sah?' WHERE `ID`=20057;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꼭 다시 돌아와서 네놈들을 찾고 말겠다!', `MaleText_loc4`='我会回来收拾你们的！', `MaleText_loc5`='我會回來找你們所有人的!', `MaleText_loc7`='¡Volveré por todos ustedes!' WHERE `ID`=20058;
