UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야, 폭죽이다!', `MaleText_loc4`='呀哈，焰火！', `MaleText_loc5`='耶，煙火!', `MaleText_loc7`='¡Bien, fuegos artificiales!', `FemaleText_loc1`='이야, 폭죽이다!', `FemaleText_loc4`='呀哈，焰火！', `FemaleText_loc5`='耶，煙火!', `FemaleText_loc7`='¡Bien, fuegos artificiales!' WHERE `ID`=20064;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적들이 우리 마을을 둘러싸고 있네. 난 모크나탈을 위해 더 열심히 싸울 걸세. 그런데 우리와 싸우는 적의 군대는 다른 방법을 선택했지.$B$B자네가 모크나탈에 필요한 존재라는 걸 증명하고 싶다면 우리가 적을 물리칠 수 있도록 도와줘.', `MaleText_loc4`='莫克纳萨村周围都是敌人的势力范围。若不是这些敌对势力迫使我们不得不为了生存而战，我相信莫克纳萨氏族会拥有更美好的生活。$B$B想要向莫克纳萨氏族证明自己的价值，就帮助我们消灭这些敌人吧。', `MaleText_loc5`='我們的敵人包圍我們。我本來能讓摩克納薩爾有更好的生活，但是我們所對抗的力量已為我們選擇了其他方式。$B$B假如你要證明自己對摩克納薩爾的價值，就幫助我們消滅他們。', `MaleText_loc7`='Nuestros enemigos nos rodean. Me gustaría que los Mok''Nathal tuvieran una vida mejor, pero las tropas contra las que luchamos han escogido otro camino para nosotros.$B$BSi quieres demostrar tu valía a los Mok''Nathal, ayúdanos a eliminarlos.' WHERE `ID`=20065;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그론이 아웃랜드의 진정한 강자다!', `MaleText_loc4`='戈隆才是外域的主宰！', `MaleText_loc5`='古羅是外域裡真正的力量!', `MaleText_loc7`='¡Los Gronn son el auténtico poder de Terrallende!' WHERE `ID`=20066;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그룰 님의 손아귀에서 벗어나지 못할 것이다!', `MaleText_loc4`='休想打败格鲁尔之手！', `MaleText_loc5`='你擊敗不了戈魯爾之手!', `MaleText_loc7`='¡No derrotarán a la mano de Gruul!' WHERE `ID`=20067;
