UPDATE `locales_broadcast_text` SET `MaleText_loc1`='3차 대전쟁에서 패했을 당시 그 뼈저린 고통은 절대 잊을 수 없다. 오랫동안 복수의 이날을 기다려 왔노라. 이제 불타는 군단의 그림자가 세계 곳곳에 드리워질지니, 너희 같은 하등 종족이 멸망하는 건... 시간문제일 뿐이다.', `MaleText_loc4`='我仍然清晰地记得上次战争败北的耻辱。我等待复仇的机会已经等得太久了。现在，军团的阴影将笼罩这个世界，你们彻底毁灭的日子……已经不远了。', `MaleText_loc5`='我永遠記得在第三次大戰結束後戰敗的傷痛。我為我的報復行動等了很久。現在燃燒軍團的陰影降臨在這個世界上。摧毀你失敗的計畫...只是早晚的事而已。', `MaleText_loc7`='Recuerdo el dolor de la derrota al fin de la Tercera Guerra. He esperado demasiado para vengarme. Ahora la sombra de la Legión se precipita sobre este mundo. Es cuestión de tiempo para que su inútil creación... desaparezca.' WHERE `ID`=20076;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불타는 군단이 온 세상을 지배하리라!', `MaleText_loc4`='军团将会征服一切！', `MaleText_loc5`='燃燒軍團將征服一切!', `MaleText_loc7`='¡La Legión lo conquistará todo!' WHERE `ID`=20077;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필멸의 종족은 모두 멸망하리라!', `MaleText_loc4`='所有的凡人都将灭亡!', `MaleText_loc5`='所有的凡人都將死亡!', `MaleText_loc7`='¡Todo mortal perecerá!' WHERE `ID`=20078;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모든 생명의 뿌리를 뽑아버리겠다!', `MaleText_loc4`='所有的生命都将被根除！', `MaleText_loc5`='所有的生命都必須被消滅!', `MaleText_loc7`='¡Se debe erradicar toda forma de vida!' WHERE `ID`=20079;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뼈도 못 추리게 해주마!', `MaleText_loc4`='我要把你们生吞活剥!', `MaleText_loc5`='我會把你的肉從骨頭上剝下來!', `MaleText_loc7`='¡Les voy arrancar la carne de los huesos!' WHERE `ID`=20080;
