UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 비천한 족속들!', `MaleText_loc4`='可笑的蠢货！', `MaleText_loc5`='卑鄙的小人!', `MaleText_loc7`='¡Despojo miserable!' WHERE `ID`=20082;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우주의 질서가 새롭게 정립되리라!', `MaleText_loc4`='宇宙将获得新生。', `MaleText_loc5`='這世界將被重新改造。', `MaleText_loc7`='Se creará un nuevo universo.' WHERE `ID`=20083;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불타는 군단에... 패배란 없다.', `MaleText_loc4`='军团……永远不会……失败。', `MaleText_loc5`='燃燒軍團...永遠不會...戰敗的。', `MaleText_loc7`='La Legión... jamás... caerá.' WHERE `ID`=20084;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='물은 곧... 생명... 여기 아웃랜드에서 물을 구하기란 결코 쉽지 않지. 오직 우리만이 물을 통제할 수 있다. 마침내 우리 귀족들이 이 세계에서 본래 자리를 되찾을 시간이 왔도다!', `FemaleText_loc4`='水……就是生命。在外域，它已经变成了一种稀有的资源，一种我们要牢牢控制住的资源。我们是上层精灵，现在，夺回我们在这个世界上的地位的时机已经成熟了！', `FemaleText_loc5`='水...就是生命。在外域，它已經變成了一種稀有的資源，一種我們要牢牢控制住的資源。我們是高等精靈，現在，時機已經成熟，我們終將奪回在這個世界裡的地位!', `FemaleText_loc7`='El agua... es vida. Se ha convertido en un bien codiciado en Terrallende, un bien que solo nosotros controlaremos. ¡Somos los Altonatos, y al fin ha llegado la hora de recuperar nuestro lugar en el mundo!' WHERE `ID`=20085;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나의 공격을 받아라!', `FemaleText_loc4`='直指人心！', `FemaleText_loc5`='直取心臟!', `FemaleText_loc7`='¡Justo al corazón!' WHERE `ID`=20086;
