UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='육지에 사는 더러운 놈들같으니!', `FemaleText_loc4`='我唾弃你们，地表的渣滓！', `FemaleText_loc5`='我唾棄你們，地表的渣滓!', `FemaleText_loc7`='¡Los desprecio, inmundicia de la superficie!' WHERE `ID`=20091;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='때가 왔다! 한 놈도 살려두지 마라!', `FemaleText_loc4`='机会来了！一个活口都不要留下！', `FemaleText_loc5`='機會來了!一個活口都不要留下!', `FemaleText_loc7`='¡Ha llegado el momento! ¡No dejen a nadie en pie!' WHERE `ID`=20092;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네놈은 여기까지다!', `FemaleText_loc4`='你的生命终结了！', `FemaleText_loc5`='你的死期到了!', `FemaleText_loc7`='¡Se te acabó el tiempo!' WHERE `ID`=20093;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='넌 실패했다!', `FemaleText_loc4`='你失败了！', `FemaleText_loc5`='你失敗了!', `FemaleText_loc7`='¡Has fracasado!' WHERE `ID`=20094;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='벨레메 안델레이!', `FemaleText_loc4`='Be''lemer an-delei！', `FemaleText_loc5`='(納迦語)你徹底的失敗了!', `FemaleText_loc7`='¡Be''lemer an-delei!' WHERE `ID`=20095;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='일리단이시여, 용서... 하십시오.', `FemaleText_loc4`='伊利丹大人，我……我很抱歉。', `FemaleText_loc5`='伊利丹王，我...我很...抱歉。', `FemaleText_loc7`='Lord Illidan, yo... lo... siento.' WHERE `ID`=20096;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 지옥절단기는 아직 제대로 작동하지 않는 것 같습니다.', `MaleText_loc4`='这台魔能机甲似乎尚未激活。', `MaleText_loc5`='這個惡魔劫奪者看起來還沒有完全進入運作。', `MaleText_loc7`='Parece que este atracador vil no está operativo aún.' WHERE `ID`=20097;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<응축된 황천 가스를 주입합니다.>', `MaleText_loc4`='<注入浓缩的虚空瓦斯。>', `MaleText_loc5`='<操縱濃縮的虛空氣體。>', `MaleText_loc7`='<Administrar el gas abisal condensado.>', `FemaleText_loc1`='<응축된 황천 가스를 주입합니다.>', `FemaleText_loc4`='<注入浓缩的虚空瓦斯。>', `FemaleText_loc5`='<操縱濃縮的虛空氣體。>', `FemaleText_loc7`='<Administrar el gas abisal condensado.>' WHERE `ID`=20098;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이방인이여, 자네가 본 사실에 어리둥절 하겠지?$B$B우리는 선조께서 남긴 기억의 불꽃을 유지하고 찬양함으로써 그분들의 업적을 기린다네.', `MaleText_loc4`='陌生人，眼前的景象令你困惑吧？$B$B我们供奉着氏族先祖的记忆碎片，以此表达我们对先祖的崇拜之情。', `MaleText_loc5`='陌生人，被你所見的事物感到困惑嗎?$B$B我們藉由讓祖先的記憶火焰持續燃燒並向它祭拜，來讚揚我們祖先的靈魂。', `MaleText_loc7`='¿Te asombra lo que ves, $gextraño:extraña;?$B$BElogiamos a los espíritus de nuestros ancestros manteniendo viva la llama de su recuerdo y rindiéndole homenaje.' WHERE `ID`=20099;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 굵고 거친 소리로 으르렁거립니다.', `MaleText_loc4`='%s发出一声低吼。', `MaleText_loc5`='%s的喉嚨發出一聲低沉的咆哮。', `MaleText_loc7`='%s deja escapar un gruñido grave y gutural.' WHERE `ID`=20100;
