UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼소환사님, 황천의 비룡의 영혼을 구하려면 토템이 더 필요합니다.', `MaleText_loc4`='唤灵者，我需要更多的图腾来拯救虚空幼龙的灵魂。', `MaleText_loc5`='招魂師，我需要更多的圖騰來拯救虛空龍的靈魂。', `MaleText_loc7`='Clamaespíritus, necesito más tótems para salvar a los espíritus de los dracos abisales.', `FemaleText_loc1`='영혼소환사님, 황천의 비룡의 영혼을 구하려면 토템이 더 필요합니다.', `FemaleText_loc4`='唤灵者，我需要更多的图腾来拯救虚空幼龙的灵魂。', `FemaleText_loc5`='招魂師，我需要更多的圖騰來拯救虛空龍的靈魂。', `FemaleText_loc7`='Clamaespíritus, necesito más tótems para salvar a los espíritus de los dracos abisales.' WHERE `ID`=20112;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 어쩔 수 없지. 하지만, 이건 나무에서 자라나는 열매처럼 그냥 떨어지는 물건이 아니라는 사실만은 알아두라고.$B$B<잠시 생각에 잠기는 영혼소환사>$B$B잠시만 기다리게...', `MaleText_loc4`='嗯，好吧。但是你要知道，这些东西不是长在树上的。$B$B<唤灵者想了一会儿。>$B$B哦，等等……', `MaleText_loc5`='嗯，好吧，但是你知道這些東西不會長在樹上。$B$B<招魂師考慮了片刻。>$B$B喔，等一下...', `MaleText_loc7`='Bueno, de acuerdo, pero ya sabes que estas cosas con crecen en los árboles.$B$B<El clamaespíritus piensa en ello un momento.>$B$BEspera un momento...' WHERE `ID`=20113;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새처럼 생긴 그 이상한 자들이 우리를 잡아먹으려고 했던 거로군요. 우웩!', `MaleText_loc4`='我想那些怪异的鸟人是来吃我们的。真恶心！', `MaleText_loc5`='我覺得那些奇怪的鳥人要把我們吃了。 噁心!', `MaleText_loc7`='Creo que esos tipos pájaro raros iban a comernos. ¡Qué asco!', `FemaleText_loc1`='새처럼 생긴 그 이상한 자들이 우리를 잡아먹으려고 했던 거로군요. 우웩!', `FemaleText_loc4`='我想那些怪异的鸟人是来吃我们的。真恶心！', `FemaleText_loc5`='我覺得那些奇怪的鳥人要把我們吃了。 噁心!', `FemaleText_loc7`='Creo que esos tipos pájaro raros iban a comernos. ¡Qué asco!' WHERE `ID`=20114;
