UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나루에게 찬양을! 드디어 풀려났네요. 이제 혼자 탈출해 보겠습니다.', `MaleText_loc4`='感谢纳鲁，我得救了。我会照顾好自己的。', `MaleText_loc5`='感謝那魯，我安全了。我會自己試著讓它淨化的。', `MaleText_loc7`='Alabanzas para los naaru, estoy salvado. Intentaré huir yo solo.', `FemaleText_loc1`='나루에게 찬양을! 드디어 풀려났네요. 이제 혼자 탈출해 보겠습니다.', `FemaleText_loc4`='感谢纳鲁，我得救了。我会照顾好自己的。', `FemaleText_loc5`='感謝那魯，我安全了。我會自己試著讓它淨化的。', `FemaleText_loc7`='Alabanzas para los naaru, estoy salvada. Intentaré huir yo sola.' WHERE `ID`=20143;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다치긴 했지만 아직 달릴 수 있습니다. 고맙습니다, 이방인이여.', `MaleText_loc4`='我受伤了，不过我还跑得动。谢谢你，陌生人。', `MaleText_loc5`='我雖然受傷了，不過我還是可以跑，謝謝你陌生人。', `MaleText_loc7`='Estoy herido, pero aún puedo correr. Gracias, $gextraño:extraña;.', `FemaleText_loc1`='다치긴 했지만 아직 달릴 수 있습니다. 고맙습니다, 이방인이여.', `FemaleText_loc4`='我受伤了，不过我还跑得动。谢谢你，陌生人。', `FemaleText_loc5`='我雖然受傷了，不過我還是可以跑，謝謝你陌生人。', `FemaleText_loc7`='Estoy herida, pero aún puedo correr. Gracias, $gextraño:extraña;.' WHERE `ID`=20144;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 고맙습니다, 이방인이여.', `MaleText_loc4`='谢谢你，陌生人。', `MaleText_loc5`='謝謝你陌生人。', `MaleText_loc7`='Gracias, $gextranjero:extranjera;.', `FemaleText_loc1`='정말 고맙습니다, 이방인이여.', `FemaleText_loc4`='谢谢你，陌生人。', `FemaleText_loc5`='謝謝你陌生人。', `FemaleText_loc7`='Gracias, $gextranjero:extranjera;.' WHERE `ID`=20145;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 너무 아파서 당신과 함께 싸우진 못 해요. 대신 제 동료를 찾아보십시오.', `MaleText_loc4`='我很虚弱，不能与你并肩作战。请找到我的朋友们。', `MaleText_loc5`='我太虛弱了無法和你一起戰鬥，拜託請找到我的朋友們。', `MaleText_loc7`='Estoy demasiado débil para luchar contigo. Por favor, encuentra a mis amigos.', `FemaleText_loc1`='당신과 함께 싸우기엔 제가 너무 약합니다. 대신 제 동료를 찾아보십시오.', `FemaleText_loc4`='我很虚弱，不能与你并肩作战。请找到我的朋友们。', `FemaleText_loc5`='我太虛弱了無法和你一起戰鬥，拜託請找到我的朋友們。', `FemaleText_loc7`='Estoy demasiado débil para luchar contigo. Por favor, encuentra a mis amigos.' WHERE `ID`=20146;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끄는 중', `MaleText_loc4`='正在熄灭', `MaleText_loc5`='熄滅吧。', `MaleText_loc7`='Apagándose', `FemaleText_loc1`='끄는 중', `FemaleText_loc4`='正在熄灭', `FemaleText_loc5`='熄滅吧。', `FemaleText_loc7`='Apagándose' WHERE `ID`=20147;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 산책하면서 기지개를 활짝 켜니 기분이 좋군. 내가 도울 일이라도 있나, $c|1이여;여;?', `MaleText_loc4`='四处走走，伸展四肢，这种感觉真好。$c，有什么我可以帮忙的吗？', `MaleText_loc5`='可以四處行動並打倒那四人是件好事，有什麼我可以幫忙的嗎，$C?', `MaleText_loc7`='Es agradable caminar y estirar las piernas. ¿Hay algo en lo que pueda ayudarte, $c?' WHERE `ID`=20148;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악마추종자의 방독면이 부서졌습니다. 새로 하나 얻을 수 있을까요?', `MaleText_loc4`='我不小心弄坏了魔誓防毒面具，你能再给我一个吗？', `MaleText_loc5`='邪誓防毒面具被摧毀了，你還有其他的嗎?', `MaleText_loc7`='La máscara de gas Jurapenas fue destruida, ¿tienes otra?', `FemaleText_loc1`='악마추종자의 방독면이 부서졌습니다. 새로 하나 얻을 수 있을까요?', `FemaleText_loc4`='我不小心弄坏了魔誓防毒面具，你能再给我一个吗？', `FemaleText_loc5`='邪誓防毒面具被摧毀了，你還有其他的嗎?', `FemaleText_loc7`='La máscara de gas Jurapenas fue destruida, ¿tienes otra?' WHERE `ID`=20149;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, $c님? 기계가 이런 부탁을 하다니 좀 뻔뻔하다고 생각하실지도 모르지만 제가 지옥불 성채의 마력에 맞추는 조정 작업을 하는 동안 틀림없이 지옥불 성채에서 나온 지옥 감시자들이 방해할 겁니다!$B$B그러니 호드의 훌륭한 영웅이시여, 부디 절 보호해 주십시오!', `MaleText_loc4`='你好，$C。请原谅我的无理，不过我得提醒你——在我完成与地狱火堡垒同调的过程中，地狱火守卫必定会趁着我最脆弱的时候发动攻击！$B$B那么，拿出部落勇士的样子来，像个英雄那样……保护我！', `MaleText_loc5`='你好啊，$c。請容許我大膽地提醒你，當我與地獄火堡壘的魔法合一時，毫無疑問的，地獄火的典獄官們都會來騷擾我的!$B$B所以呢，請盡到部落成員的責任，扮演英雄的角色...保護好我!', `MaleText_loc7`='Saludos, $c. Si se me permite el atrevimiento, te recuerdo que, mientras me ajusto a la magia de la Ciudadela del Fuego Infernal, sin duda habrá celadores del Fuego Infernal pisándome los talones.$B$BAsí que te pido que seas un miembro honesto de tu Horda y actúes como el héroe... ¡y me protejas!' WHERE `ID`=20150;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='모르데나쿠... 그대의 동맹이 우리를 구해주고 쓰레기 같은 줄루헤드를 해치웠네. 이제 이 영웅들은 우리 황천의 용군단의 영원한 친구가 되었네.', `FemaleText_loc4`='莫德奈……你的盟友拯救了我们，并杀死了卑鄙的祖鲁希德。他们永远是灵翼龙族的朋友。', `FemaleText_loc5`='摩德奈骨...你的盟友拯救了我們並消滅了卑鄙的祖魯希德，他們是虛空之翼永遠的朋友。', `FemaleText_loc7`='Mordenaku... Tus aliados nos han salvado y han destruido al desdichado, Zuluhed. Siempre serán amigos del Ala Abisal.' WHERE `ID`=20151;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='시간이 지나면 우리는 또다시 필멸의 존재들의 도움을 청하리라. 이 세계를 건너면 우리의 능력도 사라지니 필멸의 존재들만이 우리가 드레노어에서 원래 자리를 찾도록 도와줄 수 있다. 그들을 돌봐 주도록, 모르데나쿠...', `FemaleText_loc4`='将来我们会再次需要凡人的帮助。在这个世界上，我们与生俱来的权利遭到了破坏。凡人的种族会帮助我们重新夺回灵翼龙族在德拉诺世界的地位。莫德奈，你要守护他们……', `FemaleText_loc5`='我們早晚會再需要這些凡人的協助，自從來到這個世界以後我們的生存權已經被剝奪了，而這些人類種族可以幫助我們收回德拉諾的土地。摩德奈骨，照顧他們...', `FemaleText_loc7`='Con el tiempo, necesitaremos de nuevo la ayuda de los mortales. En este mundo, nuestro derecho de nacimiento está destruido. Serán las razas mortales las que nos ayuden a recuperar nuestro legítimo lugar en Draenor. Protégelos, Mordenaku...' WHERE `ID`=20152;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='필멸의 존재여, 안녕히... 그대에게 영원한 빚을 졌노라.', `FemaleText_loc4`='再见，凡人。我们会永远感激你的。', `FemaleText_loc5`='再會了，平凡人。我們會永遠感激你的。', `FemaleText_loc7`='Adiós, mortal. Siempre estaremos en deuda contigo.' WHERE `ID`=20153;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 당신 안으로 들어갈 수 있도록 허락해 주셔서 감사합니다. 당신의 정신은 매우 다채롭긴 한데 제 취향보다는 살짝 가벼운 것 같습니다... 아니면 제가 너무 오래 머물렀는지도!', `MaleText_loc4`='谢谢你肯让我洞察你的内心，$n。你的灵魂很有趣，只是比我想象得要聪明许多……不然我还会多待一会儿的！', `MaleText_loc5`='謝謝你允許我到這裡拜訪，$n。你有一個充滿色彩的靈魂，但是比我想得還鮮明...或許我可以待在這兒久一點了!', `MaleText_loc7`='Gracias por dejarme visitarte, $n. Tienes un alma muy colorida, pero es un poco más brillante de lo que prefiero... ¡o me habría quedado más tiempo!' WHERE `ID`=20154;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 우리를 죽음보다 못한 운명에서 구해주셨습니다. $n, 당신은 모크나탈 선조의 영원한 은인입니다.', `MaleText_loc4`='$n，你拯救了我们，否则莫克纳萨氏族将遭遇比死亡更悲惨的命运。氏族的先祖永远感激你。', `MaleText_loc5`='你把我們從悲慘的死亡命運中拯救出來，$n。摩克納薩爾的祖先都對你有著無限的感激之情。', `MaleText_loc7`='Nos has salvado de un destino peor que la muerte, $n. Tienes la gratitud eterna de los ancestros de Mok''Nathal.', `FemaleText_loc1`='당신은 우리를 죽음보다 못한 운명에서 구해주셨습니다. $n, 당신은 모크나탈 선조의 영원한 은인입니다.', `FemaleText_loc4`='$n，你拯救了我们，否则莫克纳萨氏族将遭遇比死亡更悲惨的命运。氏族的先祖永远感激你。', `FemaleText_loc5`='你把我們從悲慘的死亡命運中拯救出來，$n。摩克納薩爾的祖先都對你有著無限的感激之情。', `FemaleText_loc7`='Nos has salvado de un destino peor que la muerte, $n. Tienes la gratitud eterna de los ancestros de Mok''Nathal.' WHERE `ID`=20155;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 감히 내 카르가스 사령관 중 한 명을 죽였느냐? 이 일에 대한 대가는 반드시 목숨으로 치러야 한다!', `MaleText_loc4`='是哪个胆大妄为的家伙杀死了卡加斯指挥官？我要你用生命偿还这一切！', `MaleText_loc5`='是誰膽敢殺了我卡加斯的指揮官?你會為此付出...血債血償!', `MaleText_loc7`='¿Quién osa asesinar a unos de mis comandantes de Kargath? Pagarás por esto... ¡en tu propia carne!' WHERE `ID`=20156;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 하늘을 가리킵니다.', `MaleText_loc4`='%s指着头顶的天空。', `MaleText_loc5`='%s指向上方的天空。', `MaleText_loc7`='%s señala el cielo.' WHERE `ID`=20157;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밀하우스, 당신은 이제 자유의 몸입니다. 여기서 나가십시오!', `MaleText_loc4`='你自由了，米尔豪斯。离开这儿吧！', `MaleText_loc5`='米歐浩斯你自由了，離開這裡吧!', `MaleText_loc7`='Eres libre, Molino. ¡Largo de aquí!', `FemaleText_loc1`='밀하우스, 당신은 이제 자유의 몸입니다. 여기서 나가십시오!', `FemaleText_loc4`='你自由了，米尔豪斯。离开这儿吧！', `FemaleText_loc5`='米歐浩斯你自由了，離開這裡吧!', `FemaleText_loc7`='Eres libre, Molino. ¡Largo de aquí!' WHERE `ID`=20158;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 나루의 시험을 견뎌낼 만큼 강하지 않소. 좀 더 강해진 후 다시 오시오.', `MaleText_loc4`='以你现在的能力不可能通过纳鲁的试炼。等你成长为强大的勇士之后再来找我吧。', `MaleText_loc5`='你的力量還不足以忍受那魯的試驗，當你變得更強的時候再回來找我吧。', `MaleText_loc7`='No tienes el poder suficiente como para someterte a la prueba de los naaru. Vuelve a mí cuando seas más fuerte.' WHERE `ID`=20159;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 불어라, 이 더러운 난민아! 해골 무덤에서 네놈들의 마차가 무슨 짓을 꾸미고 있지?', `MaleText_loc4`='快说，肮脏的难民！你们的车队在白骨荒野干什么？', `MaleText_loc5`='說話啊，你們這些邪惡的流亡者!你們的軍隊來到白骨荒野有何目的?', `MaleText_loc7`='¡Habla, sucio refugiado! ¿Qué hacia tu caravana en El Vertedero de Huesos?', `FemaleText_loc1`='어서 불어라, 이 더러운 난민아! 해골 무덤에서 네놈들의 마차가 무슨 짓을 꾸미고 있지?', `FemaleText_loc4`='快说，肮脏的难民！你们的车队在白骨荒野干什么？', `FemaleText_loc5`='說話啊，你們這些邪惡的流亡者!你們的軍隊來到白骨荒野有何目的?', `FemaleText_loc7`='¡Habla, sucio refugiado! ¿Qué hacia tu caravana en El Vertedero de Huesos?' WHERE `ID`=20160;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 여기를 떠납시다. 이 미친 자들에게 충분히 시달렸으니 말입니다!', `MaleText_loc4`='我们离开这里吧。我受够这些疯子了！', `MaleText_loc5`='我們離開這個地方吧，我受夠這群瘋子了!', `MaleText_loc7`='Vayámonos de este lugar. ¡Ya he tenido suficiente con estos locos!' WHERE `ID`=20161;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하십시오! 이교도들이 몰려오고 있습니다!', `MaleText_loc4`='小心！更多信徒来啦！', `MaleText_loc5`='小心!有更多的教徒來了!', `MaleText_loc7`='¡Cuidado! ¡Vienen más cultores!' WHERE `ID`=20162;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서부터는 저 혼자 갈 수 있습니다. 제 친구 메케다가 당신의 선행에 대해 보상을 할 겁니다.', `MaleText_loc4`='我能找到回去的路了。我的朋友米克达会好好奖励你的。', `MaleText_loc5`='我會從這裡找路出去的，對於你的英勇行動，我的朋友麥克達會給予你獎勵的。', `MaleText_loc7`='Puedo orientarme desde aquí. Mi amigo Mekeda te recompensará por tus amables acciones.' WHERE `ID`=20163;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무 데도 못 간다, 어리석은 놈!', `MaleText_loc4`='蠢货，哪儿都别想去！', `MaleText_loc5`='蠢蛋，你那兒也去不了!', `MaleText_loc7`='¡No irás a ninguna parte, $gestúpido:estúpida;!', `FemaleText_loc1`='아무 데도 못 간다, 어리석은 놈!', `FemaleText_loc4`='蠢货，哪儿都别想去！', `FemaleText_loc5`='蠢蛋，你那兒也去不了!', `FemaleText_loc7`='¡No irás a ninguna parte, $gestúpido:estúpida;!' WHERE `ID`=20164;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리한테서 쉽게 벗어날 수 있을 줄 알았느냐!', `MaleText_loc4`='别想轻易逃跑！', `MaleText_loc5`='你無法輕易地從我們這裡脫逃的!', `MaleText_loc7`='¡No escaparás de nosotros tan fácilmente!', `FemaleText_loc1`='우리한테서 쉽게 벗어날 수 있을 줄 알았느냐!', `FemaleText_loc4`='别想轻易逃跑！', `FemaleText_loc5`='你無法輕易地從我們這裡脫逃的!', `FemaleText_loc7`='¡No escaparás de nosotros tan fácilmente!' WHERE `ID`=20165;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아무짝에도 쓸모없는 바보들! 우리가 아킨둔을 차지했어야 하는 건데... 쥐새끼처럼 기어오르는 네놈들을 보니 한숨만 절로 나오는구나!', `FemaleText_loc4`='无能的蠢货！奥金顿是我们的……瞧瞧你们那抱头鼠窜的丑样儿！', `FemaleText_loc5`='你們這些無能的蠢蛋們!奧齊頓將成為我們的了...看看你們就像是一群過街老鼠!', `FemaleText_loc7`='¡Estúpidos incompetentes! Auchindoun debería haber sido nuestra... ¡miraos, arrastrándoos como ratas!' WHERE `ID`=20166;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동족들을 찾는 일, 얼라이언스와의 싸움, 그리고 오우거와 놈들을 다스리는 그론과의 전쟁...$B$B이 모든 것들이 내 어깨를 무겁게 짓누르고 있네.$B$B가끔 도움을 받기도 하지만 그런다고 달라지는 건 없지.', `MaleText_loc4`='我们苦苦搜寻着失散的族人，随时要提防联盟的袭击，还要与食人魔和他们的戈隆主子抗争。$B$B$c，氏族的重担都落在我的肩上。$B$B因此，有时我不得不向外界寻求帮助。', `MaleText_loc5`='搜尋我們受難的同胞、抵抗聯盟的侵襲以及跟巨魔和他們的古羅將領的戰爭。$B$B所有的事情都壓在我的肩頭上，$c。$B$B就算是我也需要不時的幫助。', `MaleText_loc7`='La búsqueda de mi pueblo. Nuestra lucha contra la Alianza. La guerra contra los ogros y sus maestros gronn.$B$BTodas estas cosas son un gran peso sobre mis hombros, $c.$B$BHasta a mí me viene bien algo de ayuda de vez en cuando.' WHERE `ID`=20167;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와이번이 검은 비룡 시체를 땅에 떨어트립니다.', `MaleText_loc4`='双足飞龙将一具黑色幼龙的尸体扔在地上。', `MaleText_loc5`='雙足翼龍把一個黑龍的屍體丟在地面上。', `MaleText_loc7`='El dracoleón deja caer un cadáver de draco negro en el suelo.' WHERE `ID`=20168;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아킨둔은 우리 선조에게 영혼의 고향입니다. 그곳은 제쳐놓고라도 모든 뒤틀린 드레나이는 한때 드레나이였죠... 우리는 모두 같은 영혼을 갖고 있습니다.', `MaleText_loc4`='奥金顿是先祖灵魂的家园。或许那里是破碎者的禁地，但是所有的破碎者都曾是德莱尼人……我们的灵魂是一样的。', `MaleText_loc5`='奧齊頓是我祖先靈魂的家，我們可以不去看管它，但是它曾經被德萊尼破壞殆盡...我們的靈魂都是一樣的。', `MaleText_loc7`='Auchindoun es el hogar de los espíritus de mis ancestros. Quizás no lo parezcamos, pero todos los Tábidos fuimos Draenei antaño... nuestros espíritus son los mismos.' WHERE `ID`=20169;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 드루이드들을 이용하라고 그녀에게 전해라!', `MaleText_loc4`='让她派德鲁伊去做那件事！', `MaleText_loc5`='跟她說叫德魯伊使用這個東西!', `MaleText_loc7`='¡Dile que use a los druidas para eso!' WHERE `ID`=20170;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들이 굴복하지 않는다면 그녀가 그들을 죽일 것이다!', `MaleText_loc4`='如果他们不肯屈服，那么就让她毁灭他们！', `MaleText_loc5`='如果他們不願屈服的話，那麼她就得眼睜睜地看著他們全部都死光光!', `MaleText_loc7`='¡Si no doblan la rodilla, ella tiene que encargarse de que sean destruidos!' WHERE `ID`=20171;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠... 난 그들의 행동에 찬성하지 않았다. 그녀에게 그 일을 처리하라고 전하라.', `MaleText_loc4`='我并没有同意他们那样做。让她去解决这件事。', `MaleText_loc5`='我不贊同他們的行動，告訴她處理好這件事。', `MaleText_loc7`='No sancioné sus acciones. Dile que se ocupe de ello.' WHERE `ID`=20172;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 좋아. 하지만, 우선 그녀에게 검은새끼용을 생포해야 한다는 사실을 확실하게 알려주고 와라.', `MaleText_loc4`='很好，不过要让她明白，首先要抓的是黑龙幼崽。', `MaleText_loc5`='非常好，但她非常確定這些黑色幼龍得先捕獲才行。', `MaleText_loc7`='Muy bien, pero asegúrate de que ella sabe que primero hay que capturar a las crías oscuras.' WHERE `ID`=20173;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 그녀에게 사소한 것까지 일일이 다 지시해야 하나? 여기도 처리해야 할 중요한 문제가 산더미 같단 말이다.', `MaleText_loc4`='每件小事都要我来告诉她该怎么做吗？我有更重要的事情要处理。', `MaleText_loc5`='我一定得告訴她所有的細節嗎?我需要處理這邊的重大議題。', `MaleText_loc7`='¿Debo decirle cada detalle que tiene que hacer? Tengo asuntos más importantes de los que ocuparme aquí.' WHERE `ID`=20174;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 와라, 작은 친구야. 좋은 소식이라도 가져왔느냐?', `MaleText_loc4`='嗨，小家伙。你有什么消息要告诉我吗？', `MaleText_loc5`='你好啊，小傢伙，你帶來了什麼消息呢?', `MaleText_loc7`='Hola, pequeña. ¿Qué noticias traes?' WHERE `ID`=20175;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금은 그 일에 관여하고 싶지 않다고 그녀에게 전하라. 세나리온 원정대 드루이드들은 그들을 떼어냈다며 아주 좋아할 것이야.', `MaleText_loc4`='告诉她我不想在这种时候招惹是非。塞纳里奥远征队巴不得摆脱他们呢。', `MaleText_loc5`='告訴她說這一次我不想和這件事有關聯了，塞納里奧遠征隊應該感到更高興才對，因為他們可以自己清除他們。', `MaleText_loc7`='Dile que no quiero estar relacionado con esto en este momento. La Expedición de Cenarion debería estar más que satisfecha de deshacerse de ellos.' WHERE `ID`=20176;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니다. 난 아직도 전투를 지원할 예언 속의 인물을 찾고 있다고 그녀에게 전하라. 그럴 가능성이 있는 지원자가 거의 없구나.', `MaleText_loc4`='不。告诉她我仍然在寻找预言中提到的那个能协助我战胜戈隆的英雄。从目前的情况来看，有希望的候选者寥寥无几。', `MaleText_loc5`='不，通知她說我還在尋找那個預言中要幫助我這場戰役的人，這是少數有可能的候選人了。', `MaleText_loc7`='No. Infórmala de que sigo buscando al profetizado que tiene que ayudarme en el combate. Hay muy pocos candidatos prometedores.' WHERE `ID`=20177;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; $n|1이;가; 준 부적을 검사합니다...', `MaleText_loc4`='%s检查着$n给他的护符……', `MaleText_loc5`='%s檢查了一下$n給他的護符...', `MaleText_loc7`='%s inspecciona el dije que $n le dio...' WHERE `ID`=20178;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 정찰병 데닝이 가지고 있던 물건이군. 그가 전사하던 장면이 기억나오...', `MaleText_loc4`='啊，这是德宁下士的东西。我还记得他倒在血泊中的情景……', `MaleText_loc5`='啊，這是屬於士兵鄧寧的，我記得當他掉進...', `MaleText_loc7`='Ah, esto era del soldado Denning. Recuerdo cuando cayó...' WHERE `ID`=20179;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하사관 스톤웰이 가지고 있던 것이군... 그는 야전 병원을 지키다 전사했소...', `MaleText_loc4`='这是斯通威尔下士的护符……他在战地医院的保卫战中英勇牺牲……', `MaleText_loc5`='這個是屬於下士史登威爾的...他為了保護野外急救站而死...', `MaleText_loc7`='Este era del cabo Buenapiedra... murió protegiendo un hospital de campaña...' WHERE `ID`=20180;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 정찰병 가딩... 언제나 제일 먼저 함박웃음을 터트리던 친구지... 피눈물 부족 녀석들이 그를 제거하기 전까지는 말이야!', `MaleText_loc4`='啊，是……加丁下士。他的脸上总是挂着笑容……直到那次被血环士兵割开了喉咙！', `MaleText_loc5`='啊，是的...士兵固德林，他總是很愛笑...直到一場血之谷的戰役撕裂了他的喉嚨!', `MaleText_loc7`='Ah, sí... el soldado Valedor. Siempre reía el primero... ¡hasta que una banda de Foso Sangrante le arrancó la garganta!' WHERE `ID`=20181;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이것은 한때 내 상관이었던 하사관 란탁의 것이군. 노병 란탁보다 박력이 넘치는 군인은 없을 거요...', `MaleText_loc4`='这枚护符来自兰塔克中士，他曾是我的长官。没有哪个士兵能比他更坚强……', `MaleText_loc5`='這個徽記是從我之前的一位長官蘭塔克中士那邊得到的，你絕對不可能找到一個比老蘭塔克還堅毅的士兵...', `MaleText_loc7`='Esta insignia es del sargento Rantack, que antaño fue mi superior. Nunca encontrarías un soldado más duro que el viejo Rantack...' WHERE `ID`=20182;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 제스고르의 피눈물 요새가 있는 쪽으로 돌아섭니다...', `MaleText_loc4`='%s面向塞斯高的血环堡垒……', `MaleText_loc5`='%s面對薩斯葛爾的血之谷堡壘...', `MaleText_loc7`='%s mira hacia la fortaleza Foso Sangrante de Zeth''Gor...' WHERE `ID`=20183;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='망할 놈들! 이 타락한 오크 놈들아, 모두 죽어버려라! 너희에게 힘을 준 어둠의 힘이 네놈들의 영혼을 집어삼킬 것이다!', `MaleText_loc4`='我诅咒你们！我诅咒你们这些该死的血环兽人！让你们的灵魂在黑暗中腐化吧！', `MaleText_loc5`='太可惡了!你們這些該死的魔獄獸人!希望你們的靈魂墮落於黑暗力量之下，腐爛殆盡!', `MaleText_loc7`='¡$gMaldito:Maldita; seas! ¡Malditos sean todos tus puñeteros orcos viles! ¡Que sus almas se pudran en la barriga del poder oscuro que los impulse!' WHERE `ID`=20184;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠의 의회는 불타는 군단의 날카로운 감시 속에서 죽음의 괴철로를 운영하고 있네.', `MaleText_loc4`='在燃烧军团的监控下，暗影议会负责死亡熔炉的正常运转。', `MaleText_loc5`='死亡熔爐在燃燒軍團的監督之下，由暗影議會負責營運。', `MaleText_loc7`='La Forja Muerta está dirigida por el Consejo de la Sombra, bajo el ojo vigilante de la Legión.' WHERE `ID`=20185;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여어, 귀여운 친구! 부탁 하나만 들어주겠니? 남작님께 내가 어떻게 했으면 좋겠느냐고 물어봐 주렴.', `FemaleText_loc4`='嗨，小可爱！帮我个忙……问问男爵他想让我做些什么。', `FemaleText_loc5`='嗨，小鬼頭!幫我ㄧ個忙...幫我問男爵他到底想要我幫他做什麼。', `FemaleText_loc7`='¡Hola, monada! Hazme un favor... pregunta al barón qué quiere que haga sobre ya sabes qué.' WHERE `ID`=20186;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 아래가 죽음의 괴철로인데 이름 하나는 정말 잘 지었더군요. 장비만 제대로 갖춰지면 어둠의 의회는 불타는 군단에게 지옥불정령을 무한대로 공급할 겁니다.', `MaleText_loc4`='下面就是死亡熔炉，死亡……这个名字取得真是恰当。如果任由他们运转死亡熔炉，暗影议会就可以源源不断地为燃烧军团提供地狱火大军。', `MaleText_loc5`='下方就是叫做死亡熔爐的地方。如果任由他們的設備生產，暗影議會就會提供燃燒軍團用之不盡的煉獄火了。', `MaleText_loc7`='Abajo se encuentra la Forja Muerta, que tiene un nombre acertado. Si se le dejara hacer lo que pretende, el Consejo de la Sombra suministraría a la Legión con una multitud interminable de infernales.' WHERE `ID`=20187;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그분께 그들이 제안을 ''거절''했다고 전해 주겠니?', `FemaleText_loc4`='告诉他，他们拒绝了他的“出价”。', `FemaleText_loc5`='告訴他說他們拒絕他的「好意」。', `FemaleText_loc7`='Dile que han rechazado su "oferta".' WHERE `ID`=20188;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그들을 처리하라고? 내가 어떻게 그들을 처리하라는 거지?', `FemaleText_loc4`='和他们打交道？我要怎么和他们打交道？', `FemaleText_loc5`='解決他們?我要怎麼解決他們?', `FemaleText_loc7`='¿Ocuparme de ellos? ¿Cómo se supone que voy a ocuparme de ellos?' WHERE `ID`=20189;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='맞아. 우리는... 그러니까... 그 검은새끼용들을... 검사해야 돼.', `FemaleText_loc4`='对。我们，嗯，需要……检验……那些黑龙幼崽。', `FemaleText_loc5`='好吧...我們...嗯...需要檢查...這些黑色幼龍。', `FemaleText_loc7`='Bien. Tenemos, ehhh, que... examinar... estas crías oscuras.' WHERE `ID`=20190;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='앞으로 어떻게 할 건지 여쭤보고 즉시 돌아와라!', `FemaleText_loc4`='去问问他，接下来他想怎么着，然后回来告诉我！', `FemaleText_loc5`='問他到底想怎麼進行，然後馬上趕回來!', `FemaleText_loc7`='¡Pregúntale cómo quiere proceder y vuelve enseguida!' WHERE `ID`=20191;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='남작님이 뭐라고 하셨니?', `FemaleText_loc4`='男爵想要些什么？', `FemaleText_loc5`='男爵到底想要什麼?', `FemaleText_loc7`='¿Qué quiere el barón?' WHERE `ID`=20192;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 세나리온 친구들이 많은 도움이 될 거라고 전해 주려무나.', `FemaleText_loc4`='告诉他，塞纳里奥的朋友帮了我们的大忙。', `FemaleText_loc5`='告訴他我們塞納里奧的朋友們會盡全力幫助他的!', `FemaleText_loc7`='Dile que nuestros amigos de Cenarion han sido de lo más útiles.' WHERE `ID`=20193;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오... 우리 귀염둥이가 소식을 가져온 모양이죠?', `FemaleText_loc4`='他找到那?西了吗？', `FemaleText_loc5`='他找到那個東西了嗎?', `FemaleText_loc7`='¿Ha encontrado ya al Único?' WHERE `ID`=20194;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나의 백성은 에너지와 마력에 중독됐지. 태양샘이 파괴되자 지독한 금단 현상이 발생했다. 미래에 온 것을... 환영하노라. 중단하기에는 이미 늦었다. 이제 아무도 날 막지 못해! 셀라마 아샬라노레!', `MaleText_loc4`='魔法，能量，我的人民陷入其中不能自拔……自从太阳之井被摧毁之后就是如此。欢迎来到未来。真遗憾，你们无法阻止什么。没有人可以阻止我了！Selama ashal’anore！！', `MaleText_loc5`='能量。力量。我的人民陷入其中不能自拔...自從太陽之井被摧毀之後就顯得更加明顯。歡迎來到未來。真遺憾，你們無法阻止什麼。沒有人可以阻止我了﹗(薩拉斯語)為了人民的正義!', `MaleText_loc7`='Energía. Poder. Mi pueblo es adicta a ellos… una dependencia que se puso de manifiesto cuando la Fuente del Sol fue destruida. Bienvenidos… al futuro. Es una pena que sea demasiado tarde para que se interpongan. ¡Ya nadie puede detenerme! ¡Selama ashal’anore!' WHERE `ID`=20195;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세상을 거꾸로 뒤집으면 어떻게 되는지 구경해 볼까..', `MaleText_loc4`='如果世界变得上下颠倒，你们会怎么办呢？', `MaleText_loc5`='如果世界變得上下顛倒，你們會怎麼辦呢?', `MaleText_loc7`='Veamos cómo se las arreglan con el mundo al revés.' WHERE `ID`=20198;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마냥 서 있기만 하려니 힘들지 않나?', `MaleText_loc4`='站不住脚了吗？', `MaleText_loc5`='站不住腳了嗎?', `MaleText_loc7`='Hay que andar con pies de plomo.' WHERE `ID`=20199;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='태양의 힘으로!', `MaleText_loc4`='以太阳之名！', `MaleText_loc5`='以太陽之名!', `MaleText_loc7`='¡Por el poder del Sol!' WHERE `ID`=20200;
