UPDATE `locales_broadcast_text` SET `MaleText_loc1`='애들 장난이군.', `MaleText_loc4`='小孩子的把戏。', `MaleText_loc5`='小孩子的把戲。', `MaleText_loc7`='Esto es pan comido.' WHERE `ID`=20206;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쿠엘 탈라스를... 위하여!', `MaleText_loc4`='为了……奎尔……萨拉斯！', `MaleText_loc5`='為了...奎爾...薩拉斯!', `MaleText_loc7`='¡Por... Quel''...Thalas!' WHERE `ID`=20207;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이대로 물러날 내가 아니다! 반드시 내가 설계한 미래를 실현하리라! 이제 진정한 힘을 느껴 보아라!', `MaleText_loc4`='我的心血是不会被你们轻易浪费的！我精心谋划的未来是不会被你们轻易破坏的！感受我真正的力量吧！', `MaleText_loc5`='我的心血是不會被你們輕易浪費的!我精心謀劃的未來是不會被你們輕易破壞的!感受我真正的力量吧!', `MaleText_loc7`='¡No he llegado hasta aquí para que me detengan! ¡El futuro que he planeado no se pondrá en peligro! ¡Van a probar el verdadero poder!' WHERE `ID`=20208;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='터널 반대편에서 고룡교단 신도들이 몰려들고 있다는 걸 알고 있습니다. 우리는 여기서 방어할 것입니다.', `MaleText_loc4`='狂热的黑龙崇拜者现在就聚集在龙颅小径的另一头。我们要与他们抗衡。', `MaleText_loc5`='我們知道在另一邊的隧道那裡有一大群巨龍教徒，我們得在這裡作好準備才行。', `MaleText_loc7`='Sabemos que los cultores del Culto Vermis se congregan al otro lado del túnel. Resistiremos aquí.' WHERE `ID`=20209;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='숨을 곳이나 마련해 둬라!', `FemaleText_loc4`='你们最好找掩护。', `FemaleText_loc5`='你們最好找掩護。', `FemaleText_loc7`='Sera mejor que se cubran.' WHERE `ID`=20210;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법봉의 영향을 받아 정신을 빼앗긴 %s의 눈이 빛납니다.', `MaleText_loc4`='%s被魔杖占据了心灵，双目呆滞地盯着前方。', `MaleText_loc5`='%s的眼睛因法杖的效果控制了他的心志而顯得呆滯。', `MaleText_loc7`='Los ojos de %s se ponen vidriosos cuando los efectos de la varita se apoderan de su mente.' WHERE `ID`=20211;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법봉의 마력이 %s|1을;를; 구속하는 것 같더니 점차 사라집니다.', `MaleText_loc4`='魔杖似乎控制了%s的心智，但是魔法效果很快就消失了。', `MaleText_loc5`='法杖的魔法看起來似乎圍繞在%s的身上，之後卻漸漸消失了。', `MaleText_loc7`='La magia de la varita parece dominar a %s, pero se desvanece.' WHERE `ID`=20212;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새가 아니라면 제대로 안 먹히지!', `MaleText_loc4`='这玩意好像对鸦人之外的生物不起作用！', `MaleText_loc5`='沒有一件事是可以一蹴而成的!', `MaleText_loc7`='¡No trabajar es bueno para los no pájaros!' WHERE `ID`=20213;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런 오합지졸을 봤나!', `FemaleText_loc4`='真是一群乌合之众！', `FemaleText_loc5`='好一群烏合之眾!', `FemaleText_loc7`='¡Cuánta gente!' WHERE `ID`=20214;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악마추종자의 방독면을 복제할 기회를 얻다니 정말 운이 좋군.', `MaleText_loc4`='我能制造出完全相同的魔誓防毒面具来，这真是件好事。', `MaleText_loc5`='太好了，我可以製作一模一樣的邪誓防毒面具。', `MaleText_loc7`='Menos mal que pude hacer copias de la máscara de gas Jurapenas.' WHERE `ID`=20215;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='적들을 통과시키지 마라! 저기, 저쪽이다!', `FemaleText_loc4`='不要让他们通过小径！瞧，他们在那里！', `FemaleText_loc5`='別讓他們通過!小心，他們在那裡!', `FemaleText_loc7`='¡No los dejes pasar! ¡Mira, por aquí!' WHERE `ID`=20216;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어서 이번 공격을 시작하지 않으면 막스나르가 내 은신처를 차지할 것이다!', `FemaleText_loc4`='如果我们不立即发动攻击，玛克纳尔肯定会剥了我的皮！', `FemaleText_loc5`='如果我們不快點進行攻擊的話，麥克斯納爾得躲在我的庇護之下才行。', `FemaleText_loc7`='¡Maxnar va a encontrar mi escondite si no ponemos este ataque en proceso pronto!' WHERE `ID`=20217;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='누구 감독관님 본 적 있나?', `FemaleText_loc4`='有谁看到监工了吗？', `FemaleText_loc5`='有誰看到監督者了?', `FemaleText_loc7`='¿Alguien ha visto al sobrestante?' WHERE `ID`=20218;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='거기, 너! 지금 무슨 짓을 하는 거냐?!', `FemaleText_loc4`='喂，说你呢！你知道自己在干什么吗？！', `FemaleText_loc5`='就是你!你以為你在做什麼?!', `FemaleText_loc7`='¡Estás ahí! ¡¿Qué crees que estás haciendo?!' WHERE `ID`=20219;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='공격할 생각이 있긴 있는 건가, 그런데도 온종일 이러고만 있을 셈인가?', `FemaleText_loc4`='好吧，我们这是要发动攻击呢，还是整天在这里闲逛？', `FemaleText_loc5`='這麼說，我們要不要攻擊他們，還是我們就這樣消磨一整天?', `FemaleText_loc7`='Bueno, ¿vamos a atacar o vamos a estar pululando por aquí todo el día?' WHERE `ID`=20220;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='누가 저 바보들에게 물러서라고 해라. 저렇게 설치고 돌아다니다가는 죽음을 면치 못하리라!', `FemaleText_loc4`='去告诉那些蠢货，别一个劲儿地往前冲。这简直是自寻死路！', `FemaleText_loc5`='誰去告訴那些蠢蛋後退，他們若是單獨前去只有被屠殺的份!', `FemaleText_loc7`='Que alguien diga a esos estúpidos que se mantengan alejados. ¡Los masacran cuando van allí solos!' WHERE `ID`=20221;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='표범으로 변신해서 숨어 있는 드루이드가 있다. 여기에 사냥꾼도 있는 것 같다. 놈을 처리하라!', `FemaleText_loc4`='有个德鲁伊变成小豹子潜伏在附近。我们这里有猎人吧！去解决这家伙！', `FemaleText_loc5`='有一個德魯伊以獵豹形態在附近潛行，我以為我們這裡有獵人才對，把這件事解決一下吧!', `FemaleText_loc7`='Hay un druida husmeando con sigilo en forma de gato. Creía que teníamos cazadores aquí. ¡Ocupaos de ello!' WHERE `ID`=20222;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n, 어서 오세요. 제 특기는 달빛 옷감을 다루는 일이지요. 달빛매듭 전문가가 되고 싶은 재봉사들이 제게 종종 지도를 부탁하러 오지요.', `FemaleText_loc4`='欢迎你，$n。我擅长利用原始月布制作精美的衣物。那些想要学习月布专精的裁缝们常常来我这里讨教新知识。', `FemaleText_loc5`='歡迎啊，$n。我是原始月布的裁縫專家，那些有興趣成為月布專家的人通常都會要求我訓練他們。', `FemaleText_loc7`='$gBienvenido:Bienvenida;, $n. Tengo pericia en el arte de trabajar con tela lunar primigenia. Los sastres interesados en ser especialistas en tejido lunar me piden a menudo que les enseñe nuestras artes.' WHERE `ID`=20223;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그대에게는 제가 가르쳐드릴 게 없는데요. 물건 구경은 얼마든지 하셔도 좋아요. 그대가 사용할 만한 건 하나도 없을 테지만.', `FemaleText_loc4`='我已经没有什么新知识可以教给你了，$c。当然，你可以随意浏览我出售的货物，但是它们对你来说似乎没有什么用处了。', `FemaleText_loc5`='恐怕我能教你的只有一些皮毛而已，$c。當然，你可以隨意看看我的東西，只是你找不到你能用的東西。', `FemaleText_loc7`='Me temo que hay poco que pueda enseñarte, $c. Eres libre para echar un vistazo a mi mercancía, por supuesto, pero no la encontrarás útil.' WHERE `ID`=20224;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물건을 좀 보여주십시오.', `MaleText_loc4`='让我看看你出售的货物。', `MaleText_loc5`='給我看看你賣的東西吧。', `MaleText_loc7`='Muéstrame lo que tienes en venta.', `FemaleText_loc1`='물건을 좀 보여주세요.', `FemaleText_loc4`='让我看看你出售的货物。', `FemaleText_loc5`='給我看看你賣的東西吧。', `FemaleText_loc7`='Muéstrame lo que tienes en venta.' WHERE `ID`=20225;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='반가워요! 저는 여기 샤트라스에서 마법불꽃 재봉술을 전문으로 하는 기지라고 해요. 경쟁이 치열한 것은 아니지만 마법불꽃 재봉술에 관심이 있고 아직 전문화를 익히지 않으셨다면 제가 도와드릴 수 있어요.', `FemaleText_loc4`='很高兴遇见你！我名叫金吉，是常驻沙塔斯城的魔焰裁缝大师。如果你对魔焰裁缝感兴趣，而还没有决定裁缝专精方向的话，我可以帮你。', `FemaleText_loc5`='很高興遇見你!我叫蓋吉，是撒塔斯的居民也是魔焰裁縫專家，不管你是不是競爭對手，只要你還沒選擇你的裁縫專精系別並且有興趣成為一個專家級的魔焰裁縫師，我都很樂意幫助你。', `FemaleText_loc7`='¡Encantada de conocerte! Soy Gidge, la experta en sastrería con fuego de hechizo residente en Shattrath. No es que haya competencia, pero si te interesa aprender a ser $gun sastre:una sastra; fuego de hechizo y no te has decidido por una especialidad, puedo ayudarte.' WHERE `ID`=20226;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='재봉사가 아니라면 제 도안에 별 관심도 없으시겠죠. 그렇지만, 구경은 마음대로 해도 좋아요!', `FemaleText_loc4`='如果你不是裁缝的话，我想你是不会对我出售的图样感兴趣的，不过还是欢迎你来看看！', `FemaleText_loc5`='如果你不是裁縫師的話，我想我的圖樣無法引起你的興趣，不過歡迎你隨意看看!', `FemaleText_loc7`='Si no eres sastre, no creo que te interese ninguno de mis patrones, ¡pero puedes echar un vistazo si quieres!' WHERE `ID`=20227;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그림자매듭 재봉술에 관심이 있다면 제가 기꺼이 돕겠습니다.', `MaleText_loc4`='如果你想要购买图样，或是学习暗纹裁缝的话，我很乐意帮忙。', `MaleText_loc5`='如果你是在找有關影紋裁縫的花樣或知識，我很樂意幫助你。', `MaleText_loc7`='Si buscas patrones o conocimientos sobre la sastrería con tejido de sombra, te ayudaré con mucho gusto.' WHERE `ID`=20228;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죄송합니다만 제 물건은 적어도 바늘귀에 실은 꿸 줄 아는 분들에게나 도움이 될 걸요.$B$B장담컨대, 재봉술이 손수건을 짜맞추는 일보다는 훨씬 쓸모가 있을 거예요.', `MaleText_loc4`='对不起，$c。只有懂得针线活儿的裁缝才会对我出售的货物感兴趣。$B$B我敢说，裁缝这门手艺远比做一块手帕要复杂得多。', `MaleText_loc5`='我很抱歉，$c，但是這些是我一針一線所縫製出來最合適的商品。$B$B我可以向你保證，裁縫是比在手帕上繡字還難的技術。', `MaleText_loc7`='Lo siento, $c, pero mis mercancías son adecuadas para aquellos que saben por qué extremo de la aguja se introduce el hilo.$B$BTe aseguro que la confección es mucho más que bordar pañuelos.' WHERE `ID`=20229;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아달, 폭풍우 요새의 열쇠를 잃어버려서 새 열쇠가 필요합니다.', `MaleText_loc4`='阿达尔，我弄丢了风暴要塞的钥匙，你能再给我一把吗？', `MaleText_loc5`='阿達歐，我弄丟風暴要塞的鑰匙，我需要一把代替品。', `MaleText_loc7`='A''dal, he perdido la llave de El Castillo de la Tempestad y necesito un recambio.', `FemaleText_loc1`='아달, 폭풍우 요새의 열쇠를 잃어버려서 새 열쇠가 필요합니다.', `FemaleText_loc4`='阿达尔，我弄丢了风暴要塞的钥匙，你能再给我一把吗？', `FemaleText_loc5`='阿達歐，我弄丟風暴要塞的鑰匙，我需要一把代替品。', `FemaleText_loc7`='A''dal, he perdido la llave de El Castillo de la Tempestad y necesito un recambio.' WHERE `ID`=20230;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방해하도록 놔두지 않겠습니다!', `MaleText_loc4`='我不能允许你们介入！', `MaleText_loc5`='我不准你涉入這件事!', `MaleText_loc7`='¡No puedo permitir que interfieran!' WHERE `ID`=20231;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물건을 보여주십시오.', `MaleText_loc4`='让我看看你出售的货物。', `MaleText_loc5`='給我看看你賣的東西吧。', `MaleText_loc7`='Muéstrame lo que tienes en venta.', `FemaleText_loc1`='물건을 보여주세요.', `FemaleText_loc4`='让我看看你出售的货物。', `FemaleText_loc5`='給我看看你賣的東西吧。', `FemaleText_loc7`='Muéstrame lo que tienes en venta.' WHERE `ID`=20232;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳을 깨끗이 정화하겠다!', `MaleText_loc4`='我要将你彻底净化！', `MaleText_loc5`='我會把你從這個地方淨化掉!', `MaleText_loc7`='¡Te eliminaré de este lugar!' WHERE `ID`=20233;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들과 다를 게 하나도 없구나!', `MaleText_loc4`='你也毫无力量！', `MaleText_loc5`='你比他們還不如!', `MaleText_loc7`='¡No eres mejor que ellos!' WHERE `ID`=20234;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이럴 수밖에 없었습니다.', `MaleText_loc4`='他们强迫我这么做的。', `MaleText_loc5`='這是他們逼我的...', `MaleText_loc7`='Me han forzado a hacerlo...' WHERE `ID`=20235;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선택의 여지가 없었습니다.', `MaleText_loc4`='我没有选择。', `MaleText_loc5`='我別無選擇。', `MaleText_loc7`='No tuve elección.' WHERE `ID`=20236;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저도 그림자매듭 재봉술 전문가가 되고 싶어요. 가르쳐 주실래요?', `MaleText_loc4`='我想成为暗纹裁缝大师。你能教我吗？', `MaleText_loc5`='我想成為影紋裁縫專家，你可以教我嗎?', `MaleText_loc7`='Deseo convertirme en experto en sastrería con tejido de sombra. ¿Puedes instruirme?', `FemaleText_loc1`='저도 그림자매듭 재봉술 전문가가 되고 싶어요. 가르쳐 주실래요?', `FemaleText_loc4`='我想成为暗纹裁缝大师。你能教我吗？', `FemaleText_loc5`='我想成為影紋裁縫專家，你可以教我嗎?', `FemaleText_loc7`='Deseo convertirme en experto en sastrería con tejido de sombra. ¿Puedes instruirme?' WHERE `ID`=20237;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어... 해방이다...', `MaleText_loc4`='我……自由了。', `MaleText_loc5`='我被...釋放了。', `MaleText_loc7`='Soy... libre.' WHERE `ID`=20238;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오염된 건... 내가 아니라... 너희다!', `MaleText_loc4`='你……是疾病……不是我！', `MaleText_loc5`='你...才有病...而不是我!', `MaleText_loc7`='¡Ustedes son... la enfermedad, no yo!' WHERE `ID`=20239;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저도 달빛매듭 전문가가 되고 싶어요. 가르쳐 주실래요?', `MaleText_loc4`='我想成为月布裁缝大师。你能教我吗？', `MaleText_loc5`='我想成為月布裁縫專家，你可以教我嗎?', `MaleText_loc7`='Deseo convertirme en especialista en sastrería con tela lunar. ¿Puedes instruirme?', `FemaleText_loc1`='저도 달빛매듭 전문가가 되고 싶어요. 가르쳐 주실래요?', `FemaleText_loc4`='我想成为月布裁缝大师。你能教我吗？', `FemaleText_loc5`='我想成為月布裁縫專家，你可以教我嗎?', `FemaleText_loc7`='Deseo convertirme en especialista en sastrería con tela lunar. ¿Puedes instruirme?' WHERE `ID`=20240;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저도 마법불꽃 전문가가 되고 싶어요. 가르쳐 주실래요?', `MaleText_loc4`='我想成为魔焰裁缝大师。你能教我吗？', `MaleText_loc5`='我想成為魔焰裁縫專家，你可以教我嗎?', `MaleText_loc7`='Deseo convertirme en especialista en sastrería de fuego de hechizo. ¿Puedes instruirme?', `FemaleText_loc1`='저도 마법불꽃 전문가가 되고 싶어요. 가르쳐 주실래요?', `FemaleText_loc4`='我想成为魔焰裁缝大师。你能教我吗？', `FemaleText_loc5`='我想成為魔焰裁縫專家，你可以教我嗎?', `FemaleText_loc7`='Deseo convertirme en especialista en sastrería de fuego de hechizo. ¿Puedes instruirme?' WHERE `ID`=20241;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여사제님, 어떤 도움이라도 감사히 받겠습니다.', `MaleText_loc4`='女祭司，无论你给予我什么样的帮助，我都会感激你的。', `MaleText_loc5`='女祭司，對於妳所能提供的任何幫助我都感到相當感激。', `MaleText_loc7`='Agradecería cualquier ayuda que me pudieras prestar, sacerdotisa.', `FemaleText_loc1`='여사제님, 어떤 도움이라도 감사히 받겠어요.', `FemaleText_loc4`='女祭司，无论你给予我什么样的帮助，我都会感激你的。', `FemaleText_loc5`='女祭司，對於妳所能提供的任何幫助我都感到相當感激。', `FemaleText_loc7`='Agradecería cualquier ayuda que me pudieras prestar, sacerdotisa.' WHERE `ID`=20242;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 여신의 눈물은 엘룬의 축복을 받은 것으로 아키몬드의 사악한 마법에 대항할 힘을 드릴 것입니다. 잘 사용하십시오.', `FemaleText_loc4`='这些被艾露恩祝福过的女神之泪蕴藏着强大的力量，可以帮助你对抗阿克蒙德的邪恶魔法。好好利用女神之泪的力量吧。', `FemaleText_loc5`='藉由伊露恩的女神之淚可以獲得祝福，她的力量可以幫助你對抗阿克蒙德的邪惡魔法，好好使用她們的力量吧。', `FemaleText_loc7`='Estas lágrimas de la diosa han sido bendecidas por Elune, y su energía te ayudará a combatir la magia vil de Archimonde. Usa bien su energía.' WHERE `ID`=20243;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들은 내 말을 두려워하지. 저들은 날 본보기로 삼았다. 이건 진정한 신이신 넵튤론 님을 조롱하는 일이다.$B$B<침을 뱉는 스카디스>$B$B필멸의 존재여, 저들은 천벌을 받을 거다. 언젠가 바다사냥꾼의 영광스러운 손이 낫으로 잡초를 잘라내는 듯이 신을 믿지 않는 자들을 쓸어버리리라.', `MaleText_loc4`='他们害怕我的预言。他们囚禁了我，想要起到罚一儆百的效果，以示对真神耐普图隆的嘲笑。$B$B<斯卡希斯吐了口唾沫。>$B$B凡人，他们会受到惩罚的。总有一天，猎潮者会挥起武器，就像镰刀收割成熟的庄稼那样，将这群丧失信仰的家伙统统歼灭。', `MaleText_loc5`='他們害怕我的言語，所以狠狠的教訓了我以示眾人。這對一位真神，奈普圖隆來說真是一個諷刺呀。$B$B<司卡利斯吐口水。>$B$B凡人啊，報應來了。獵潮者的光榮之手將有一天會像是在鐮刀收割般地殺死這些不信之徒。', `MaleText_loc7`='Temen mis palabras. Hacen que sea un ejemplo. Una parodia del único dios verdadero, Neptulon.$B$B<Skar''this escupe.>$B$BSe acerca el jusssto castigo, mortal. La gloriosa mano del Cazamareas se extenderá hasta los no creyentes como una guadaña contra una nueva cosecha.' WHERE `ID`=20244;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 무덤에는 끔찍한 마법의 흔적이 남아 있소이다. 모든 방법을 동원해서 이 깊은 상처를 치료해야 하오.', `MaleText_loc4`='可怕的魔法滋扰着这片荒野。我们必须竭尽所能，治愈大地的创伤。', `MaleText_loc5`='這些破壞恐怕是那些可怕的魔法所造成的，我們得盡可能的治療這些重大的創傷。', `MaleText_loc7`='Estas ruinas están marcadas por una magia terrible. Debemos hacer lo posible por curar esta gran herida.' WHERE `ID`=20245;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='*경고!* 오직 한 가지 재봉술만 전문화할 수 있습니다.', `MaleText_loc4`='*注意！*你只能选择一种裁缝专精。', `MaleText_loc5`='*警告!*你只能選擇一種裁縫的專精系別。', `MaleText_loc7`='*¡AVISO!* Solo puedes seleccionar una especialidad de sastrería.', `FemaleText_loc1`='*경고!* 오직 한 가지 재봉술만 전문화할 수 있습니다.', `FemaleText_loc4`='*注意！*你只能选择一种裁缝专精。', `FemaleText_loc5`='*警告!*你只能選擇一種裁縫的專精系別。', `FemaleText_loc7`='*¡AVISO!* Solo puedes seleccionar una especialidad de sastrería.' WHERE `ID`=20246;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='*경고!* 오직 한 가지 재봉술만 전문화할 수 있습니다.', `MaleText_loc4`='*注意！*你只能选择一种裁缝专精。', `MaleText_loc5`='*警告!*你只能選擇一種裁縫的專精系別。', `MaleText_loc7`='*¡AVISO!* Solo puedes seleccionar una especialidad de sastrería.', `FemaleText_loc1`='*경고!* 오직 한 가지 재봉술만 전문화할 수 있습니다.', `FemaleText_loc4`='*注意！*你只能选择一种裁缝专精。', `FemaleText_loc5`='*警告!*你只能選擇一種裁縫的專精系別。', `FemaleText_loc7`='*¡AVISO!* Solo puedes seleccionar una especialidad de sastrería.' WHERE `ID`=20247;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='*경고!* 오직 한 가지 재봉술만 전문화할 수 있습니다.', `MaleText_loc4`='*注意！*你只能选择一种裁缝专精。', `MaleText_loc5`='*警告!*你只能選擇一種裁縫的專精系別。', `MaleText_loc7`='*¡AVISO!* Solo puedes seleccionar una especialidad de sastrería.', `FemaleText_loc1`='*경고!* 오직 한 가지 재봉술만 전문화할 수 있습니다.', `FemaleText_loc4`='*注意！*你只能选择一种裁缝专精。', `FemaleText_loc5`='*警告!*你只能選擇一種裁縫的專精系別。', `FemaleText_loc7`='*¡AVISO!* Solo puedes seleccionar una especialidad de sastrería.' WHERE `ID`=20248;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 피난민들은 엄청난 고통을 겪어왔으며 분명 앞으로도 더 많은 고통이 기다리고 있소. 그들을 도와줘서 정말 고맙소. 지금 당장 할 일이 없으시다면 작은 부탁 하나만 들어주시오.', `MaleText_loc4`='这些难民们承受了巨大的痛苦，毫无疑问，将来他们还会遭遇更大的痛苦。你慷慨地帮助了他们，为此我向你表示感谢。如果你已经完成了自己的使命，那么我能请你再帮我个小忙吗？', `MaleText_loc5`='這些難民遭受到莫大的苦難，而且毫無疑問的他們的苦痛也會越來越多。我很感謝你幫助他們，如果你現在可以再盡你所能的話，我希望我可以再拜託你一件小事。', `MaleText_loc7`='Estos refugiados han sufrido enormemente y, sin duda, sufrirán más. Ya los has ayudado y te lo agradezco. Si has hecho todo lo que puedes por ahora, te pediría un pequeño favor.' WHERE `ID`=20249;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음의 문은 다른 세계로 열리는 차원문입니다. 불타는 군단은 그곳에서 지옥사냥개 같은 짐승들을 기르지요. 그러니까, 그런 짐승들이 보인다면 죽음의 문을 통해서 나온 것이 분명하므로 가장 먼저 이곳을 지나갈 겁니다.$B$B최근 우리는 불타는 군단이 차원문을 통해 그 짐승들을 소환했다는 사실을 알아냈습니다.$B$B모든 것이 파괴되는 돌이킬 수 없는 지경에 이르기 전에 죽음의 문을 닫아야 합니다!', `MaleText_loc4`='燃烧军团在另一个位面养殖了大量恶魔猎犬和其他犬类恶魔，并开启了一道被称为死亡之门的传送门，以便将这些生物召唤至这个世界。无论什么时候，只要你看见那些犬类恶魔，它们必定是穿越死亡之门而来的。$B$B最近，我们察觉到燃烧军团加快了召唤恶魔猎犬的速度。$B$B你必须尽快关闭死亡之门，否则事态将一发不可收拾。', `MaleText_loc5`='死亡之門的入口將在這個世界打開，燃燒軍團要利用這個門來繁殖惡魔犬和其他恐怖的犬齒生物。只要你看到這些從那裡來的生物，必定是先通過那道門來到這裡的。B$B最近，我們知道燃燒軍團要從這個入口召喚這些生物。$B$B你必須在他們造成不可收拾的情況之前，先把死亡之門關閉才行，要不然一切都會毀了!', `MaleText_loc7`='La Puerta de la Muerte es un portal que se abre al mundo que la Legión Ardiente utiliza para alimentar a sus canes manáfagos y a otros horrores de tipo canino. Cuando veas a alguna de esas criaturas, de ahí es de donde proviene, y primero pasa por aquí.$B$BÚltimamente nos hemos dado cuenta de que la Legión Ardiente ha aumentado sus convocatorias de estas criaturas a través del portal.$B$B¡Debes cerrar la Puerta de la Muerte antes de que se convierta en una marea inexorable y todo esté perdido!', `FemaleText_loc1`='죽음의 문은 다른 세계로 열리는 차원문입니다. 불타는 군단은 그곳에서 지옥사냥개 같은 짐승들을 기르지요. 그러니까, 그런 짐승들이 보인다면 죽음의 문을 통해서 나온 것이 분명하므로 가장 먼저 이곳을 지나갈 겁니다.$B$B최근 우리는 불타는 군단이 차원문을 통해 그 짐승들을 소환했다는 사실을 알아냈습니다.$B$B모든 것이 파괴되는 돌이킬 수 없는 지경에 이르기 전에 죽음의 문을 닫아야 합니다!', `FemaleText_loc4`='燃烧军团在另一个位面养殖了大量恶魔猎犬和其他犬类恶魔，并开启了一道被称为死亡之门的传送门，以便将这些生物召唤至这个世界。无论什么时候，只要你看见那些犬类恶魔，它们必定是穿越死亡之门而来的。$B$B最近，我们察觉到燃烧军团加快了召唤恶魔猎犬的速度。$B$B你必须尽快关闭死亡之门，否则事态将一发不可收拾。', `FemaleText_loc5`='死亡之門的入口將在這個世界打開，燃燒軍團要利用這個門來繁殖惡魔犬和其他恐怖的犬齒生物。只要你看到這些從那裡來的生物，必定是先通過那道門來到這裡的。B$B最近，我們知道燃燒軍團要從這個入口召喚這些生物。$B$B你必須在他們造成不可收拾的情況之前，先把死亡之門關閉才行，要不然一切都會毀了!', `FemaleText_loc7`='La Puerta de la Muerte es un portal que se abre al mundo que la Legión Ardiente utiliza para alimentar a sus canes manáfagos y a otros horrores de tipo canino. Cuando veas a alguna de esas criaturas, de ahí es de donde proviene, y primero pasa por aquí.$B$BÚltimamente nos hemos dado cuenta de que la Legión Ardiente ha aumentado sus convocatorias de estas criaturas a través del portal.$B$B¡Debes cerrar la Puerta de la Muerte antes de que se convierta en una marea inexorable y todo esté perdido!' WHERE `ID`=20251;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 고통을 받는 영혼을 정화하고자 이 땅에 왔지만, 공격을 받은 이후론 내 임무가 실패할까 봐 걱정일세. 너무나 많은 이들이 이 무덤에서 희생되었어. 제발 그들을 도와주게나.', `MaleText_loc4`='我来这里是为了净化那些不安分的灵魂，但是在那次袭击后我就担心自己的任务会失败。白骨荒野夺走了太多生命，请你一定要帮助他们。', `MaleText_loc5`='我來到這塊土地是為了淨化冤靈，但是在那場攻擊之後我怕我的任務已經失敗了。更多的生命喪失在荒野之中，拜託你一定得幫幫他們。', `MaleText_loc7`='Vine a esta tierra para purificar espíritus purificados, pero, después del ataque, me temo que mi misión ha fracasado. Se han perdido tantos... por favor, debes ayudarlos.' WHERE `ID`=20252;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오래전 어둠의 의회는 아킨둔 안에서 사악한 의식을 치르려 했지. 의식은 실패했고 그 결과 자네 주위에 보이는 무덤이 생겼네. 죽은 드레나이의 해골과 영혼이 지금 이 땅을 배회하고 있어. 난 우리 선조의 무덤을 정화하는 임무를 맡고 여기 왔지만 위험 요소가 너무 많아서 여기 남아 피난민들을 보호하고 있네.', `FemaleText_loc4`='很久以前，暗影议会在奥金顿之内进行了一次黑暗典礼。他们的失败创造出了你现在所看到的荒野，在那里游荡着无数的骷髅与死去德莱尼人的灵魂。我原本是被派来清理这处先祖之坟墓的，但是因为这里十分危险，我必须继续留在这里保护难民们。', `FemaleText_loc5`='很久以前，暗影議會試著在奧齊頓裡舉行黑暗儀式，現在你舉目所及的荒野就是他們儀式的失敗產物。死去的德萊尼靈魂現在在這塊土地上飄蕩，我想淨化我祖先的墳墓，但是我得留在這裡保護這些難民免得他們受到更多的危險。', `FemaleText_loc7`='Antaño, el Consejo de la Sombra intentó realizar un ritual oscuro dentro de Auchindoun. Su fracaso creó los residuos que ves a tu alrededor. Los huesos y los espíritus de los Draenei caídos frecuentan esta tierra ahora. Fui enviado para limpiar las tumbas de mis ancestros, pero, con tantos peligros, debo permanecer aquí para proteger a los refugiados.' WHERE `ID`=20253;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 꽥 소리를 내더니 장막의 샬라스를 향해 갑니다. 서둘러 따라가야 합니다!', `MaleText_loc4`='%s叫喊着冲向沙拉斯鸦巢。快点跟上去！', `MaleText_loc5`='%s嘎嘎的叫著並且向迷霧撒拉斯前進，快點跟著他!', `MaleText_loc7`='¡%s grazna y se dirige hacia Velo Shalas. ¡Apresúrate y síguelo!' WHERE `ID`=20254;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 나무 앞에서 잠시 멈추더니 안으로 들어갑니다.', `MaleText_loc4`='%s在树前短暂地停了一下，然后直接向里面冲了进去。', `MaleText_loc5`='%s在樹前他短暫的休息了一下，接著又往裡面前進。', `MaleText_loc7`='%s se calla brevemente ante el árbol y se dirige a su interior.' WHERE `ID`=20255;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 뭔가를 찾고 있는 것 같습니다. 당신이 따라오기를 바랍니다.', `MaleText_loc4`='%s似乎正在寻找什么东西。它想让你跟着它。', `MaleText_loc5`='%s似乎在找什麼東西，他要你跟隨著他。', `MaleText_loc7`='%s parece estar buscando algo. Quiere que lo sigas.' WHERE `ID`=20256;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 아래쪽 탑 쪽으로 날아갑니다! 따라잡으려면 뛰어내려야 합니다. 서두르십시오!', `MaleText_loc4`='%s飞到了平台下方！如果你不想跟它走失，最好直接跳下去，快一点！', `MaleText_loc5`='%s飛到下方的平台了!如果你想跟上他，最好跳下去，快點啊!', `MaleText_loc7`='¡%s vuela hasta la plataforma que hay debajo! Será mejor que saltes si quieres seguir el ritmo. ¡Date prisa!' WHERE `ID`=20257;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 부드러운 삼겹살 좋아해!', `MaleText_loc4`='我喜欢嫩一点的熏火腿！', `MaleText_loc5`='我就像是軟嫩的培根肉!', `MaleText_loc7`='¡Yo gustar beicon suave!' WHERE `ID`=20258;
