UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 모두 잘 들으십시오! 내 주변에 원형으로 포진한 후 조사를 떠나도록 합시다!', `MaleText_loc4`='好吧，听好了！在我周围排成圆圈，然后出发！', `MaleText_loc5`='好吧，聽好了!繞著我圍成一圈並離開這兒!', `MaleText_loc7`='¡De acuerdo, escuchad! ¡Haced un círculo a mi alrededor y marchaos!' WHERE `ID`=20314;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 코를 킁킁거리더니 이 비밀 장소를 불만스러워 합니다.', `MaleText_loc4`='%s看了看周围，有些不满意这个隐藏点。', `MaleText_loc5`='%s四處聞了聞，對這個隱蔽點感到不滿意。', `MaleText_loc7`='%s olfatea a su alrededor, insatisfecho con este escondite.' WHERE `ID`=20315;
