UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 고크의 단잠을 깨우는 게 누구냐?', `MaleText_loc4`='是谁胆敢把苟克从宁静的睡梦中吵醒？', `MaleText_loc5`='是誰敢把沉睡中的苟克吵醒?', `MaleText_loc7`='¿Quién osa despertar a Goc de su tranquilo sueño?' WHERE `ID`=20317;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 모크나탈의 아들이자 호드의 용사인 렉사르다.', `MaleText_loc4`='我是雷克萨，莫克纳萨之子，部落的勇士。', `MaleText_loc5`='我叫雷克薩，摩克納薩爾之子，部落的勇士。', `MaleText_loc7`='Soy Rexxar, hijo de Mok''Nathal, campeón de la Horda.' WHERE `ID`=20318;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 손아귀로 무고한 이들에게 고통을 주던 일도 이제는 끝이다. 내 이름을 걸고 맹세하는데 널 죽이고 말겠다.', `MaleText_loc4`='他们所承受的痛苦就要结束了。以我的名义，我会在此终结你的生命。', `MaleText_loc5`='他們在你魔爪之下所受的苦難即將結束。以吾之名，我要結束你的生命。', `MaleText_loc7`='Y su tormento en tus manos llega a su fin. Por mi nombre que pondré fin a tu vida.' WHERE `ID`=20319;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽을 준비나 해라.', `MaleText_loc4`='准备迎接你的末日吧。', `MaleText_loc5`='請你做好最後的準備。', `MaleText_loc7`='Prepárate para el final.' WHERE `ID`=20320;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 이름은 이 고크의 손에 죽어간 수많은 이들처럼 하찮은 것일 뿐이다. 이제 널 뭉개주지!', `MaleText_loc4`='对我而言，你就和其他死在强大的苟克手中的家伙一样，微不足道。', `MaleText_loc5`='你的名字對我來說一點都不重要，就像那些死在苟克力量之下的數千亡魂一樣。我將會碾碎你跟$n!', `MaleText_loc7`='Tu nombre es tan insignificante para mí como el nombre de los miles que han muerto bajo el poder de Goc. ¡Os machacare a ti y a $n!' WHERE `ID`=20321;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 목숨을 가져갈 위대한 자의 이름이나 알아두는 것이 좋을 것이다.', `MaleText_loc4`='如果你到死也不知道是谁取了你的小命，那也太不公平了。', `MaleText_loc5`='你絕對知道是誰想要奪取你的生命。', `MaleText_loc7`='Es justo que sepas el nombre de quien te quitará la vida.' WHERE `ID`=20323;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='남작 세이블메인... 바로 네가 마지막 숨을 헐떡거리며 내뱉을 이름이다.', `MaleText_loc4`='我是萨博迈恩男爵。你很快就要呼出生命中的最后一口气息了。', `MaleText_loc5`='沙伯邁恩男爵，在你臨死前快吸取最後的一口氣吧。', `MaleText_loc7`='Barón Sablecrín. Estará en tus labios mientras dejas escapar tu último suspiro.' WHERE `ID`=20324;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 시작해 볼까?', `MaleText_loc4`='我们开始吧。', `MaleText_loc5`='我們開始動手吧。', `MaleText_loc7`='Comencemos.' WHERE `ID`=20325;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 없었으면 승리하지 못했을 것일세. 천둥군주 요새에서 다시 얘기하도록 하세나.', `MaleText_loc4`='要是没有你，我不可能获得这次胜利。我们回雷神要塞之后再说吧。', `MaleText_loc5`='沒有你我們是無法獲得勝利的。我們回到雷霆王村會告訴大家的。', `MaleText_loc7`='No podría haber alcanzado esta victoria sin ti. Volveremos a hablar en el Bastión Señor del Trueno.' WHERE `ID`=20326;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 벗어난 후에 다시 얘기하도록 하자.', `MaleText_loc4`='我们应该谈谈，不过不是在这里。', `MaleText_loc5`='我們會再交談的，不過不在這裡。', `MaleText_loc7`='Volveremos a hablar, pero lejos de aquí.' WHERE `ID`=20327;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c님, 우리가 작업하는 동안 안전하게 지켜주시기 바랍니다. 일을 마치면 보상을 드리겠습니다.', `MaleText_loc4`='好吧，$r，你只需要在我们工作的时候保护我们不被伤害。等我们回去以后会付给你酬劳的。', `MaleText_loc5`='好吧，$r，當我們在工作的時候你要確保我們的安全，等我們回去後我們會付你錢的。', `MaleText_loc7`='De acuerdo, $r, cuídate del peligro mientras trabajamos. Te pagaremos cuando volvamos.' WHERE `ID`=20328;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 발굴 작업을 진행할 곳은 여기서 바로 북쪽입니다. 자, 갑시다.', `MaleText_loc4`='那个挖掘站就在这里的北面。', `MaleText_loc5`='挖掘地點就在這裡的北邊。', `MaleText_loc7`='La excavación está al norte de aquí.' WHERE `ID`=20329;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 도착했군! 모두 땅을 팝시다!', `MaleText_loc4`='我们到了！开始挖掘！', `MaleText_loc5`='就是這裡了!開始挖吧!', `MaleText_loc7`='¡Estamos aquí! ¡Comienza a cavar!' WHERE `ID`=20330;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 모래 아래 뭔가 묻혀 있는 것 같아요!', `MaleText_loc4`='我觉得这里的沙子底下埋着东西！', `MaleText_loc5`='我認為在這個沙土之下埋藏著什麼東西!', `MaleText_loc7`='¡Creo que hay algo enterrado aquí, bajo la arena!' WHERE `ID`=20331;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 힘냅시다. 거의 다 팠습니다!', `MaleText_loc4`='就快了！', `MaleText_loc5`='快拿到了!', `MaleText_loc7`='¡Casi lo tengo!' WHERE `ID`=20332;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이럴 수가 있나! 이게 뭐지!? 이... 이건 북 같은데...', `MaleText_loc4`='以布莱恩喜欢吃的烂香蕉的名义！这是什么？看上去……像只鼓。', `MaleText_loc5`='布萊恩的香蕉!那是什麼!?看起來...好像是一架鼓耶。', `MaleText_loc7`='¡Por los platanitos de Brann! ¡¿Qué es eso!? Parece... parece un tambor.' WHERE `ID`=20333;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오... 대단하군요... 이런 북이 나오다니...', `MaleText_loc4`='哇……一只鼓。', `MaleText_loc5`='哇...一架鼓耶。', `MaleText_loc7`='Guau... un tambor.', `FemaleText_loc1`='오... 대단하군요... 이런 북이 나오다니...', `FemaleText_loc4`='哇……一只鼓。', `FemaleText_loc5`='哇...一架鼓耶。', `FemaleText_loc7`='Guau... un tambor.' WHERE `ID`=20334;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번 발견은 현대 고고학의 초석에 큰 파장을 불러올 겁니다.', `MaleText_loc4`='这个发现肯定会动摇现代考古学的基础理念。', `MaleText_loc5`='這個發現絕對會動搖現代考古學的根基。', `MaleText_loc7`='Este descubrimiento sin duda sacudirá los cimientos de la arqueología moderna.', `FemaleText_loc1`='이번 발견은 현대 고고학의 초석에 큰 파장을 불러올 겁니다.', `FemaleText_loc4`='这个发现肯定会动摇现代考古学的基础理念。', `FemaleText_loc5`='這個發現絕對會動搖現代考古學的根基。', `FemaleText_loc7`='Este descubrimiento sin duda sacudirá los cimientos de la arqueología moderna.' WHERE `ID`=20335;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 정말 대단한 발견이로군요. 근데 이제 여길 떠나도 되지 않을까요? 이런 사막에 있으려니까 두드러기가 나는 것 같아서요.', `MaleText_loc4`='是啊，太棒了。我们现在能回去了吗？这片沙漠让我浑身发痒。', `MaleText_loc5`='是的，沒錯，我們可以離開了嗎?這個沙漠讓我得了蕁麻疹。', `MaleText_loc7`='Sí, genial. ¿Podemos irnos ya? Este desierto me da urticaria.', `FemaleText_loc1`='네, 정말 대단한 발견이로군요. 근데 이제 여길 떠나도 되지 않을까요? 이런 사막에 있으려니까 두드러기가 나는 것 같아서요.', `FemaleText_loc4`='是啊，太棒了。我们现在能回去了吗？这片沙漠让我浑身发痒。', `FemaleText_loc5`='是的，沒錯，我們可以離開了嗎?這個沙漠讓我得了蕁麻疹。', `FemaleText_loc7`='Sí, genial. ¿Podemos irnos ya? Este desierto me da urticaria.' WHERE `ID`=20336;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 제정신입니까? 이런 북을 쳐보지도 않고 가자는 말인가요? 아이언포지의 자손이라면 절대 그런 말 못합니다! 암요, 절대 안 되고 말고요!', `MaleText_loc4`='你疯了吗？你竟然不希望我去敲打这只鼓，不希望看看接下来会发生什么事？那可有违铁炉堡之子的名声！绝不能这样！', `MaleText_loc5`='你瘋了不成?你要我在還沒打鼓之前就把鼓丟在這裡逃跑?這不是鐵爐堡之子的行為!我辦不到!', `MaleText_loc7`='¿Has perdido el juicio? ¿Esperas que deje atrás un tambor sin tocarlo primero? ¡No este hijo de Forjaz! ¡No, señor!' WHERE `ID`=20337;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 시작합니다!', `MaleText_loc4`='来了！', `MaleText_loc5`='走吧!', `MaleText_loc7`='¡Aquí va!' WHERE `ID`=20338;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 상황이 발생하니까 당신이 우리에게 실리더스를 수색하여 모래 노움의 증거를 찾으라고 했던 일이 생각나는군요.', `MaleText_loc4`='这让我想起了过去，那时候，你为了寻找所谓沙漠侏儒的证据，让我们搜遍了整个希利苏斯。', `MaleText_loc5`='這讓我想起上次你要我們搜索整個希利蘇斯尋找沙塵地精的證據。', `MaleText_loc7`='Eso me recuerda la vez que nos hiciste registrar a Silithus para encontrar pruebas de gnomos de arena.', `FemaleText_loc1`='이런 상황이 발생하니까 당신이 우리에게 실리더스를 수색하여 모래 노움의 증거를 찾으라고 했던 일이 생각나는군요.', `FemaleText_loc4`='这让我想起了过去，那时候，你为了寻找所谓沙漠侏儒的证据，让我们搜遍了整个希利苏斯。', `FemaleText_loc5`='這讓我想起上次你要我們搜索整個希利蘇斯尋找沙塵地精的證據。', `FemaleText_loc7`='Eso me recuerda la vez que nos hiciste registrar a Silithus para encontrar pruebas de gnomos de arena.' WHERE `ID`=20339;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 당신이 20세기 역병의 치료제를 찾았다고 말하던 때도 새록새록 기억나는군요. 그런데 그것마저 뭐였죠? 그 20세기인가 뭔가 하는 그거 말입니다!', `MaleText_loc4`='还有那一次，你告诉我们说，你发现了治愈20世纪疾病的办法。这所谓的20世纪又到底是什么东西？', `MaleText_loc5`='要不然你告訴我們那次你發現了二十世紀瘟疫的治療方法。那究竟是什麼?二十世紀又是什麼?', `MaleText_loc7`='O aquella vez que nos dijiste que habías descubierto la cura para la peste del siglo veinte. ¿Qué es eso? ¿El siglo veinte?', `FemaleText_loc1`='또 당신이 20세기 역병의 치료제를 찾았다고 말하던 때의 기억이 새록새록 나는군요. 그런데 그것마저 뭐였죠? 그 20세기인가 뭔가 하는 그거 말입니다!', `FemaleText_loc4`='还有那一次，你告诉我们说，你发现了治愈20世纪疾病的办法。这所谓的20世纪又到底是什么东西？', `FemaleText_loc5`='要不然你告訴我們那次你發現了二十世紀瘟疫的治療方法。那究竟是什麼?二十世紀又是什麼?', `FemaleText_loc7`='O aquella vez que nos dijiste que habías descubierto la cura para la peste del siglo veinte. ¿Qué es eso? ¿El siglo veinte?' WHERE `ID`=20340;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한때 난 모든 도전자들의 도전을 받아주는 일을 즐기곤 했지만, 그렇게 쉽게 이기는 싸움이 지겨워진지 오래입니다.$B$B이제는 시약 사업을 진척시키고 황혼의 망치단에서 겪은 일을 책으로 쓰면서 하루를 보내고 있답니다.', `MaleText_loc4`='我曾以接受别人的挑战为乐，但是他们无一例外地都败了，我早已厌倦了这种廉价的胜利。$B$B现在，我将精力放在经营材料生意上，还打算写一本回忆录，记录我在暮光之锤度过的岁月。', `MaleText_loc5`='過去我讓自己接受任何人的挑戰，把這當成一種娛樂，但我已經開始厭倦這樣輕鬆的勝利。$B$B現在，我打算花點時間在此地的試劑事業上，並寫一本有關我對暮光之錘的經驗談。', `MaleText_loc7`='Solía divertirme aceptando retos de cualquiera que me los ofreciera, pero hace tiempo que me he cansado de victorias tan fáciles.$B$BPor ahora, me estoy tomando algo de tiempo para que mi negocio de componentes despegue y para escribir un libro sobre mis experiencias en Martillo Crepuscular.' WHERE `ID`=20341;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래도 지금 상황이, 여명의 설원 빙하 아래 아서스의 ''사촌'' 유골이 묻혀 있다는 소리를 들었다고 레톨이 말하던 그때보다 더 어이없진 않네요. 그거 때문이라도 난 당신을 용서할 수가 없어요, 레톨. 진심이라고요... 아서스의 사촌이 어쩌고저쩌고라고요?', `MaleText_loc4`='我觉得还是那一次最劲。那次他说他认为阿尔萨斯表弟的骨骼被冻在冬泉谷的冰河之下。我永远都不会原谅你，雷托尔。说真的……阿尔萨斯的表弟又是乜了？', `MaleText_loc5`='我不認為這是他第一次聽到阿薩斯「親戚」的骨骸被冰凍在冬泉谷的冰河之下，我絕不會忘記那一次的，里同。我是說真的...阿薩斯的親戚?', `MaleText_loc7`='No creo que supere la vez que nos dijo que había oído que el esqueleto del "primo" de Arthas estaba congelado bajo un glaciar de Cuna del Invierno. Nunca te perdonaré esa, Letoll. Es que, ya te vale... ¿el primo de Arthas?', `FemaleText_loc1`='그래도 지금 상황이, 여명의 설원 빙하 아래 아서스의 ''사촌'' 유골이 묻혀 있다는 소리를 들었다고 레톨이 말하던 그때보다 더 어이없진 않네요. 그거 때문이라도 난 당신을 용서할 수가 없어요, 레톨. 진심이라고요... 아서스의 사촌이 어쩌고저쩌고라고요?', `FemaleText_loc4`='我觉得还是那一次最劲。那次他说他认为阿尔萨斯表弟的骨骼被冻在冬泉谷的冰河之下。我永远都不会原谅你，雷托尔。说真的……阿尔萨斯的表弟又是乜了？', `FemaleText_loc5`='我不認為這是他第一次聽到阿薩斯「親戚」的骨骸被冰凍在冬泉谷的冰河之下，我絕不會忘記那一次的，里同。我是說真的...阿薩斯的親戚?', `FemaleText_loc7`='No creo que supere la vez que nos dijo que había oído que el esqueleto del "primo" de Arthas estaba congelado bajo un glaciar de Cuna del Invierno. Nunca te perdonaré esa, Letoll. Es que, ya te vale... ¿el primo de Arthas?' WHERE `ID`=20342;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 뭐가 뭔지 모르겠군요. 지금 이 상황은, 레톨 당신이 우리는 사실 어떤 상상의 존재이며, 우리가 단지 그들의 즐거움을 위해 존재한다고 말하던 그때보다 더 화가 나지는 않아요. 가족과 함께 식사를 하는 동안엔 잘 넘어갔지만 말입니다.', `MaleText_loc4`='我真不知道雷托尔脑子里装的是什么。有一次他居然试图说服我们，说我们不过是某种生物臆想出来的意识体，是他们用来取乐的调剂品。那段时间，每次晚餐的时候他都会喋喋不休地说个不停。', `MaleText_loc5`='我不知道。這一定比不上之前他試著說服我們相信世界上的事物都只是某些人創造出來的幻想，而這些人創造我們出來只是為了好玩而已。這個故事被當成我們家的餐前笑話。', `MaleText_loc7`='No sé. No es posible que supere la vez que intentó convencernos de que en realidad todos somos producto de la imaginación de algún ser y que solo nos usa para diversión personal. Eso duró toda la comida con la familia.', `FemaleText_loc1`='정말 뭐가 뭔지 모르겠군요. 지금 이 상황은, 레톨 당신이 우리는 사실 어떤 상상의 존재이며, 우리가 단지 그들의 즐거움을 위해 존재한다고 말하던 그때보다 더 화가 나지는 않아요. 가족과 함께 식사를 하는 동안엔 잘 넘어갔지만 말입니다.', `FemaleText_loc4`='我真不知道雷托尔脑子里装的是什么。有一次他居然试图说服我们，说我们不过是某种生物臆想出来的意识体，是他们用来取乐的调剂品。那段时间，每次晚餐的时候他都会喋喋不休地说个不停。', `FemaleText_loc5`='我不知道。這一定比不上之前他試著說服我們相信世界上的事物都只是某些人創造出來的幻想，而這些人創造我們出來只是為了好玩而已。這個故事被當成我們家的餐前笑話。', `FemaleText_loc7`='No sé. No es posible que supere la vez que intentó convencernos de que en realidad todos somos producto de la imaginación de algún ser y que solo nos usa para diversión personal. Eso duró toda la comida con la familia.' WHERE `ID`=20343;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 자, 입 좀 다뭅시다! 이제 이 북을 치겠으니 우리 얘기는 여기서 끝입니다!', `MaleText_loc4`='闭嘴！反正我现在就要狠敲这只鼓！', `MaleText_loc5`='不要再亂叫了!我要打鼓了，就是這樣!', `MaleText_loc7`='¡Cerrad el pico! ¡Voy a golpear este tambor y se acabó!' WHERE `ID`=20344;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신에게 도전할 생각은 없어요. 그저 물건 좀 구경하고 싶을 뿐입니다.', `MaleText_loc4`='我无意与你为敌，不过我想看看你的货物。', `MaleText_loc5`='我不會向你挑戰的，但是我想看看你的東西。', `MaleText_loc7`='No te desafiaré, pero me gustaría ver tus mercancías.', `FemaleText_loc1`='당신에게 도전할 생각은 없어요. 그저 물건 좀 구경하고 싶을 뿐입니다.', `FemaleText_loc4`='我无意与你为敌，不过我想看看你的货物。', `FemaleText_loc5`='我不會向你挑戰的，但是我想看看你的東西。', `FemaleText_loc7`='No te desafiaré, pero me gustaría ver tus mercancías.' WHERE `ID`=20345;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방금 그 소린 뭐였죠?', `MaleText_loc4`='那么，你们都听到了吗？', `MaleText_loc5`='嘿，你們聽到了嗎?', `MaleText_loc7`='Decid, ¿oís eso, muchachos?', `FemaleText_loc1`='방금 그 소린 뭐였죠?', `FemaleText_loc4`='那么，你们都听到了吗？', `FemaleText_loc5`='嘿，你們聽到了嗎?', `FemaleText_loc7`='Decid, ¿oís eso, muchachos?' WHERE `ID`=20346;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 지붕에서 평생 일을 해야 할지도 모르겠는데...', `MaleText_loc4`='看上去，我们得在这屋顶上永远工作下去了。', `MaleText_loc5`='感覺我們已經修了一輩子的屋頂。', `MaleText_loc7`='Parece como si trabajáramos en este tejado desde siempre.' WHERE `ID`=20347;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='낯빛이 싹 바뀌는군요! 그러게 내가 여기 뭔가 있다고 말하지 않았습니까!', `MaleText_loc4`='哈哈！我告诉过你这里有东西的！', `MaleText_loc5`='你的臉!我告訴過你，有東西在你的臉上!', `MaleText_loc7`='¡EN TU CARA! ¡Te dije que aquí había algo!' WHERE `ID`=20348;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금쯤이면 우리가 지붕 수리를 끝냈어야 한다고 생각하시겠지요.', `MaleText_loc4`='你是不是觉得我们现在就应该修好屋顶？', `MaleText_loc5`='你一定以為我們修到現在已經把這個屋頂修補好了。', `MaleText_loc7`='Pensaba que ya deberíamos haber terminado de reparar el tejado.' WHERE `ID`=20349;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='망치질을 하면 할수록 구멍이 더 커진단 말입니다.', `MaleText_loc4`='好像我捶得越多，这个洞就会越大。', `MaleText_loc5`='看起來我得自己用這個錘子敲出一個大洞出來了。', `MaleText_loc7`='Es como si, cuanto más martilleara, mayor se hiciera este agujero.' WHERE `ID`=20350;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다들 힘을 냅시다! 일에 전혀 진전이 없단 말입니다.', `MaleText_loc4`='加快速度，小子们。我们在这里还没任何进展。', `MaleText_loc5`='快點啊，孩子們。我們一點進展都沒有。', `MaleText_loc7`='Aumentad el ritmo, muchachos. No estamos progresando nada aquí.' WHERE `ID`=20351;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='못이 부족할 것 같은데...', `MaleText_loc4`='我觉得钉子快用完了。', `MaleText_loc5`='我想我們的釘子用光了。', `MaleText_loc7`='Creo que nos estamos quedando sin clavos.' WHERE `ID`=20352;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 겨우 4살밖에 안 먹었다고요.', `FemaleText_loc4`='我只有四岁。', `FemaleText_loc5`='我才四歲而已。', `FemaleText_loc7`='Solo tengo cuatro años.' WHERE `ID`=20353;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일만 하고 쉬지 않으면 어떻게... 아, 입 다물고 망치질이나 하겠습니다.', `MaleText_loc4`='都给我工作，不要再开玩笑了……我会闭上嘴，继续敲。', `MaleText_loc5`='只工作不玩耍...我會乖乖閉嘴認真工作。', `MaleText_loc7`='Solo trabajar... me callo y sigo dándole al martillo.' WHERE `ID`=20354;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 엄마 아빠 못 보셨나요?', `FemaleText_loc4`='你看到过我爸爸妈妈吗？', `FemaleText_loc5`='你有看到我的媽咪和爹地嗎?', `FemaleText_loc7`='¿Has visto a mi mami y a mi papi?' WHERE `ID`=20355;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아웃랜드에서 대규모 전쟁이 벌어지고 있다는 말을 들었습니다. 만약 그곳에도 지붕이 있다면 수리가 필요할 텐데...', `MaleText_loc4`='我听说在外域发生过许多次大战。我在想，是否那边也有屋顶需要修理……', `MaleText_loc5`='我聽說外域展開了激烈的戰爭。不知道那邊有沒有人的屋頂需要修理...', `MaleText_loc7`='He oído que se están llevando a cabo grandes guerras en Terrallende. Me pregunto si habrá algún tejado allí que necesite reparaciones...' WHERE `ID`=20356;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안텔라리온 님, 아직 숲에 나가 놀면 안 되나요?', `FemaleText_loc4`='安塔里恩，现在去森林里玩是否安全呢？', `FemaleText_loc5`='安德烈利安，現在可以安全的在這個森林裡玩了嗎?', `FemaleText_loc7`='Antelarion, ¿ya es seguro jugar en el bosque?' WHERE `ID`=20357;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전 아제로스에서 왔는데 거기가 어딘지 아세요?', `FemaleText_loc4`='我觉得我是从英——格兰来的，你知道那是哪里吗？', `FemaleText_loc5`='我想我是從英格蘭來的，你知道那兒在哪裡嗎?', `FemaleText_loc7`='Creo que provengo de Ingla-Terra, ¿sabes dónde está?' WHERE `ID`=20358;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무엇보다 대체 어떤 녀석이 여관 지붕에 구멍을 냈는지가 궁금하군요. 아웃랜드 끝자락에서 동전을 떨어뜨리면 어떤 일이 생기는지 아십니까?', `MaleText_loc4`='我想知道一开始到底是什么在旅馆的屋顶上弄了这么个洞。我还想知道，在外域的边缘扔个铜币下去会发生什么情况？', `MaleText_loc5`='我在想當初是什麼東西在旅館屋頂上穿了個洞。如果你把一枚銅幣從外域的邊緣丟下去會掉到哪邊去呢?', `MaleText_loc7`='Me pregunto qué hizo un agujero en el tejado de la posada. ¿Ves lo que pasa cuando dejas caer una pieza de cobre por el borde de Terrallende?' WHERE `ID`=20359;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 큰 새를 이겼다고 안텔라리온님이 그러셨어요. 그때 안텔라리온님이 절 데리러 오시긴 했지만요... 안텔라리온님은 정말 멋져요!', `FemaleText_loc4`='安塔里恩说我是从大鸟上掉下来的，当我掉下来的时候他抓住了我……他真厉害！', `FemaleText_loc5`='安德烈利安說當他抓到我時，我是從一隻大鳥身上跌落下來的...他長的真好看!', `FemaleText_loc7`='Antelarion dice que me caí de un gran pájaro, y me cogió al caer... ¡Es tan guapo!' WHERE `ID`=20360;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c! 거기 그러고 멍하니 서 있지 말고 가서 $g그:그녀;를 도와주십시오!', `MaleText_loc4`='不要就这么站在那里！帮帮$g他:她;！', `MaleText_loc5`='別站著發呆!幫助$g他:她;呀!', `MaleText_loc7`='¡No te quedes ahí! ¡$gAyúdalo:Ayúdala;!' WHERE `ID`=20361;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 북을 집어듭니다.', `MaleText_loc4`='%s捡起了鼓。', `MaleText_loc5`='%s把鼓撿起來。', `MaleText_loc7`='%s coge el tambor.' WHERE `ID`=20362;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 정말 큰 도움이 되었습니다! 놈들이 더 몰려오기 전에 여기서 나갑시다! 드워포위츠에게 당신이 일을 매우 잘했다고 전할 테니 그에게 가보십시오.', `MaleText_loc4`='你给予了我们相当大的帮助，$R！我们赶紧离开这儿吧，免得再惹麻烦上身！我会转告杜瓦弗维兹，说你出色地完成了自己的任务。', `MaleText_loc5`='你真是個最佳的支援，$r!在其他的東西出現之前我們快離開這裡吧!我會讓德拉弗懷玆 知道你這個年輕人做得真的很好!', `MaleText_loc7`='¡Has sido de gran ayuda, $r! ¡Vayámonos de aquí antes de que aparezcan más cosas de estas! Haré saber a Enaniski que hiciste la tarea que se te encomendó de forma admirable.' WHERE `ID`=20363;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 여기 남아서 충분히 싸울 수 있으니 당신 자신을 방어하십시오.', `MaleText_loc4`='我还能站起来，还能战斗。你也关心一下自己吧。', `MaleText_loc5`='我還有足夠的力氣起身來戰鬥。做好作戰的準備吧。', `MaleText_loc7`='Me quedan fuerzas suficientes para mantenerme en pie y luchar. Prepárate.' WHERE `ID`=20364;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐냐?! 누가 감히 불타는 군단을 방해하느냐?', `MaleText_loc4`='什么？！是谁胆敢给燃烧军团惹麻烦？', `MaleText_loc5`='什麼?!誰敢阻擾燃燒軍團?', `MaleText_loc7`='¡¿QUÉ?! ¿Quién osa molestar a la Legión Ardiente?' WHERE `ID`=20365;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영원한 고통을 맛보게 해주마, 어리석은 놈!', `MaleText_loc4`='准备接受无尽的折磨吧，凡人！', `MaleText_loc5`='你這平凡的傢伙，作好受盡無數苦痛的準備吧!', `MaleText_loc7`='¡Prepárate para la tortura eterna, mortal!' WHERE `ID`=20366;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='운명을 거스를 방법은 없다!', `MaleText_loc4`='什么都无法阻止你的末日！', `MaleText_loc5`='你的命運已經完蛋了!', `MaleText_loc7`='¡Nada evitará tu muerte!' WHERE `ID`=20367;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하! 불속에서 네 놈의 뼈가 타는 향긋한 냄새를 맡겠구나!', `MaleText_loc4`='我要把你从表皮到骨髓都完全烤熟，我一定会很喜欢那滋味！', `MaleText_loc5`='從吱吱作響的火中，我聞到你的骨髓透著一股油脂鮮美的味道!', `MaleText_loc7`='¡Disfrutaré del olor de grasa cuando tu tuétano crepite al fuego!' WHERE `ID`=20368;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 날 공격하다니?!', `MaleText_loc4`='你胆敢袭击我？！', `MaleText_loc5`='你竟然敢攻擊我?!', `MaleText_loc7`='¡¿OSAS atacarme?!' WHERE `ID`=20369;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 무례함의 대가로 천천히 아주 고통스럽게 죽어가게 될 것이다!', `MaleText_loc4`='你胆敢冒犯我！我要慢慢地将你折磨至死！', `MaleText_loc5`='你會慢慢地受到折磨直到你死去為止!', `MaleText_loc7`='¡Sufrirás todo lo posible hasta el fin de los tiempos por esta afrenta!' WHERE `ID`=20370;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 차원의 추격자의 혈액을 모읍니다.', `MaleText_loc4`='%s开始收集迁跃追迹者的血液。', `MaleText_loc5`='%s收集扭曲追趕者的血。', `MaleText_loc7`='%s recoge la sangre del persecutor de distorsión.' WHERE `ID`=20371;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장난은 여기까지다! 이제 진정한 우주의 분노를 보여주마.', `MaleText_loc4`='我受够了！现在我要让你们看看宇宙的愤怒！', `MaleText_loc5`='夠了!現在我要呼喚宇宙中失衡的能量。', `MaleText_loc7`='¡Ya es suficiente! Ahora emplazo la furia del mismo cosmos.', `FemaleText_loc1`='장난은 여기까지다! 이제 진정한 우주의 분노를 보여주마.', `FemaleText_loc4`='我受够了！现在我要让你们看看宇宙的愤怒！', `FemaleText_loc5`='夠了!現在我要呼喚宇宙中失衡的能量。', `FemaleText_loc7`='¡Ya es suficiente! Ahora emplazo la furia del mismo cosmos.' WHERE `ID`=20372;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 공허의 세계와... 하나가 되리라!', `MaleText_loc4`='我和虚空……融为了一体！', `MaleText_loc5`='我會與虛無...合而為一!', `MaleText_loc7`='Me FUNDO... ¡con el VACÍO!', `FemaleText_loc1`='나는 공허의 세계와... 하나가 되리라!', `FemaleText_loc4`='我和虚空……融为了一体！', `FemaleText_loc5`='我會與虛無...合而為一!', `FemaleText_loc7`='Me FUNDO... ¡con el VACÍO!' WHERE `ID`=20373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 녀석은 아직도 좀 약한 것 같군.', `MaleText_loc4`='这一条似乎仍然有点虚弱。', `MaleText_loc5`='小傢伙看起來還是很虛弱的樣子。', `MaleText_loc7`='Este todavía parece un podo débil.' WHERE `ID`=20374;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 녀석은 언젠가 좋은 탈것이 될 거야.', `MaleText_loc4`='它总有一天会成为不错的坐骑。', `MaleText_loc5`='總有一天這小傢伙會變成很好的坐騎。', `MaleText_loc7`='Este debería ser una montura excelente algún día.' WHERE `ID`=20375;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 새끼에게 먹이를 좀 더 갖다주라고!', `MaleText_loc4`='多给这条龙崽一点食物！', `MaleText_loc5`='餵這隻幼龍一點東西吃!', `MaleText_loc7`='¡Tráele más comida a esta cría!' WHERE `ID`=20376;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 먹고 튼튼하게 자라거라, 내 보물아.', `MaleText_loc4`='我的宝贝，再长大一点，再强壮一点吧。', `MaleText_loc5`='讓我的寶貝成長茁壯吧。', `MaleText_loc7`='Crece grande y fuerte, tesoro.' WHERE `ID`=20377;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용아귀 부족이 예전의 영광을 되찾을 수 있도록 당신이 도와야 합니다.', `MaleText_loc4`='你将帮助龙喉氏族重夺荣耀。', `MaleText_loc5`='你得幫助龍喉氏族重返榮耀。', `MaleText_loc7`='Devolverás su antigua gloria al clan Faucedraco.' WHERE `ID`=20378;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 아비는 내 아이들을 살해하고 시신을 용의 무덤에 있는 칼날 같은 바위에 던져버렸다. 아이들의 원혼을 달래주려면 너는 여기서 죽어야 한다! 장난은 여기까지다. 넘쳐 오르는 나의 분노를 받아 보아라!', `MaleText_loc4`='你的父亲杀死了我的孩子，还残忍地将他们的尸骸钉在巨龙之末的岩石上。你必须为此付出生命的代价！这场闹剧该结束了。尝尝我满腔的怒火吧！', `MaleText_loc5`='你父親殺了我的孩子並把他們的屍體刺穿在飛龍之末的岩石之劍上。為此，你要死!這荒唐的一切夠了。準備好挑戰我全部的憤怒吧!', `MaleText_loc7`='Tu padre destruyó a mis hijos y dejó sus cadáveres empalados en los filos rocosos de Fin de Dragón. ¡Por esto, morirás! Ya basta de esta farsa. ¡Prepárate para enfrentarte a toda mi ira!' WHERE `ID`=20379;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 엄청난 힘을 뿜어내기 시작합니다.', `MaleText_loc4`='%s散发出无尽的能量。', `MaleText_loc5`='%s開始釋放出巨大的力量。', `MaleText_loc7`='%s comienza a emanar una energía inmensa.' WHERE `ID`=20380;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 고크의 제단에서 이렇게 무례한 짓을 하는 게 누구냐?', `MaleText_loc4`='是谁胆敢侮辱苟克的祭坛？', `MaleText_loc5`='誰敢公然覬覦苟克祭壇?', `MaleText_loc7`='¿Quién osa colocar esta afrenta sobre el altar de Goc?' WHERE `ID`=20381;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='렉사르가 다가오면서 동굴 위에서 날개를 퍼덕이는 소리가 들립니다.', `MaleText_loc4`='从峡谷的高处传来了翅膀拍击的声音。雷克萨来了！', `MaleText_loc5`='當雷克薩靠近時你聽到峽谷高空中傳來翅膀拍打的聲音。', `MaleText_loc7`='Oyes el sonido de alas batiendo arriba en el cañón mientras Rexxar se aproxima.', `FemaleText_loc1`='렉사르가 다가오면서 동굴 위에서 날개를 퍼덕이는 소리가 들립니다.', `FemaleText_loc4`='从峡谷的高处传来了翅膀拍击的声音。雷克萨来了！', `FemaleText_loc5`='當雷克薩靠近時你聽到峽谷高空中傳來翅膀拍打的聲音。', `FemaleText_loc7`='Oyes el sonido de alas batiendo arriba en el cañón mientras Rexxar se aproxima.' WHERE `ID`=20382;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연금술 실험대', `MaleText_loc4`='炼金实验室', `MaleText_loc5`='鍊金實驗室', `MaleText_loc7`='Laboratorio de alquimia', `FemaleText_loc1`='연금술 실험대', `FemaleText_loc4`='炼金实验室', `FemaleText_loc5`='鍊金實驗室', `FemaleText_loc7`='Laboratorio de alquimia' WHERE `ID`=20383;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 도시에 있는 연금술사 로로킴은 실험대를 직접 가지고 다닙니다. 당신에게는 좀 생소하게 들릴지도 모르겠지만 결국엔 그는 아라코아니까요. 하지만, 크게 문제 될 건 없을 겁니다. 그를 만나려면 고난의 거리의 북서쪽 지역으로 가시면 됩니다.', `MaleText_loc4`='我们的常驻炼金师罗罗基姆把他的设备都一起带了过来。不过，这些设备和你以前习惯使用的略微有些不同——毕竟他是个鸦人——但这些设备应该足以满足你要求。他就在贫民窟的西北部分。', `MaleText_loc5`='事實上，我們的鍊金師羅洛其恩隨身帶著他的鍊金裝備。也許他跟你過去找的鍊金師有一點不太一樣 - 他是個阿拉卡，不過他應該能滿足你的需求了。他就落腳在陰鬱城的西北部。', `MaleText_loc7`='Nuestro alquimista residente, Lorokeem, se trajo su equipamiento con él, de hecho. Puede ser ligeramente diferente de lo que acostumbras a usar – es un después de todo – pero debería satisfacer tus necesidades. Lleva el mando en la parte noreste de la parte baja de la ciudad.', `FemaleText_loc1`='우리 도시에 있는 연금술사 로로킴은 실험대를 직접 가지고 다닙니다. 당신에게는 좀 생소하게 들릴지도 모르겠지만 결국엔 그는 아라코아니까요. 하지만, 크게 문제 될 건 없을 겁니다. 그를 만나려면 고난의 거리의 북서쪽 지역으로 가시면 됩니다.', `FemaleText_loc4`='我们的常驻炼金师罗罗基姆把他的设备都一起带了过来。不过，这些设备和你以前习惯使用的略微有些不同——毕竟他是个鸦人——但这些设备应该足以满足你要求。他就在贫民窟的西北部分。', `FemaleText_loc5`='事實上，我們的鍊金師羅洛其恩隨身帶著他的鍊金裝備。也許他跟你過去找的鍊金師有一點不太一樣 - 他是個阿拉卡，不過他應該能滿足你的需求了。他就落腳在陰鬱城的西北部。', `FemaleText_loc7`='Nuestro alquimista residente, Lorokeem, se trajo su equipamiento con él, de hecho. Puede ser ligeramente diferente de lo que acostumbras a usar – es un después de todo – pero debería satisfacer tus necesidades. Lleva el mando en la parte noreste de la parte baja de la ciudad.' WHERE `ID`=20384;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보석 상인', `MaleText_loc4`='宝石商人', `MaleText_loc5`='珠寶商人', `MaleText_loc7`='Mercader de gemas', `FemaleText_loc1`='보석 상인', `FemaleText_loc4`='宝石商人', `FemaleText_loc5`='珠寶商人', `FemaleText_loc7`='Mercader de gemas' WHERE `ID`=20385;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보석 상인은 두 명 있습니다. 한 명은 점술가 길드와, 다른 한 명은 알도르 사제회와 손을 잡고 일하고 있지요. 어느 보석 상인을 찾습니까?', `MaleText_loc4`='这里居住着两位宝石商人：一位与占星者走得很近，而另一个忠诚于奥尔多。你在找哪个？', `MaleText_loc5`='這個地方有兩位珠寶商人:其中一個為占卜者工作，另外一個則效忠於 奧多爾，你要找的是誰?', `MaleText_loc7`='Hay dos mercaderes de gemas residentes: uno trabaja estrechamente con los Arúspices, y el otro es leal a los Aldor. ¿A quién buscas?', `FemaleText_loc1`='보석 상인은 두 명 있습니다. 한 명은 점술가 길드와, 다른 한 명은 알도르 사제회와 손을 잡고 일하고 있지요. 어느 보석 상인을 찾습니까?', `FemaleText_loc4`='这里居住着两位宝石商人：一位与占星者走得很近，而另一个忠诚于奥尔多。你在找哪个？', `FemaleText_loc5`='這個地方有兩位珠寶商人:其中一個為占卜者工作，另外一個則效忠於 奧多爾，你要找的是誰?', `FemaleText_loc7`='Hay dos mercaderes de gemas residentes: uno trabaja estrechamente con los Arúspices, y el otro es leal a los Aldor. ¿A quién buscas?' WHERE `ID`=20386;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알도르 사제회 보석 상인', `MaleText_loc4`='奥尔多宝石商人', `MaleText_loc5`='奧多爾珠寶商人', `MaleText_loc7`='Mercader de gemas Aldor', `FemaleText_loc1`='알도르 사제회 보석 상인', `FemaleText_loc4`='奥尔多宝石商人', `FemaleText_loc5`='奧多爾珠寶商人', `FemaleText_loc7`='Mercader de gemas Aldor' WHERE `ID`=20388;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이넷세라는 보석세공 도구와 다양한 보석을 취급하는 똑똑한 여자입니다. 알도르 마루의 북쪽으로 가면 그녀의 상점을 찾을 수 있을 겁니다.', `MaleText_loc4`='英妮瑟拉是个贩卖各种宝石以及珠宝加工用品的精明女人。你可以在奥尔多高地的北部找到她的商店。', `MaleText_loc5`='伊奈思娜是個精明的女人，她有許多的寶石和珠寶設計的材料，你可以在奧多爾高地的北部找到她的店。', `MaleText_loc7`='Inessera es una mujer astuta que lleva varias gemas, así como suministros de joyería. Puedes encontrar su tienda en la parte norte de Alto Aldor.', `FemaleText_loc1`='이넷세라는 보석세공 도구와 다양한 보석을 취급하는 똑똑한 여자입니다. 알도르 마루의 북쪽으로 가면 그녀의 상점을 찾을 수 있을 겁니다.', `FemaleText_loc4`='英妮瑟拉是个贩卖各种宝石以及珠宝加工用品的精明女人。你可以在奥尔多高地的北部找到她的商店。', `FemaleText_loc5`='伊奈思娜是個精明的女人，她有許多的寶石和珠寶設計的材料，你可以在奧多爾高地的北部找到她的店。', `FemaleText_loc7`='Inessera es una mujer astuta que lleva varias gemas, así como suministros de joyería. Puedes encontrar su tienda en la parte norte de Alto Aldor.' WHERE `ID`=20389;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='점술가 길드 보석 상인', `MaleText_loc4`='占星者宝石商人', `MaleText_loc5`='占卜者珠寶商人', `MaleText_loc7`='Mercader de gemas Arúspice', `FemaleText_loc1`='점술가 길드 보석 상인', `FemaleText_loc4`='占星者宝石商人', `FemaleText_loc5`='占卜者珠寶商人', `FemaleText_loc7`='Mercader de gemas Arúspice' WHERE `ID`=20390;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='먼저 리스리드가 약간... 무서운 여자라는 점부터 말씀드려야겠네요. 하지만, 당신이 필요한 물건은 모두 가지고 있을 겁니다. 그녀는 점술가 언덕의 동쪽에서 상점을 운영하고 있습니다.', `MaleText_loc4`='利萨尔丝可能……看上去有点凶，但是她出售你想要的东西。她在占星者平台的东部。', `MaleText_loc5`='麗斯瑞司剛開始看起來可能會有一點...可怕，不過她有你想找的東西。她在占卜者階梯的東部地區販賣她的商品。', `MaleText_loc7`='Lisrythe puede ser un poco... intimidante al principio, pero tiene lo que buscas. Vende su mercancía en la parte oriental de la Grada del Arúspice.', `FemaleText_loc1`='먼저 리스리드가 약간... 무서운 여자라는 점부터 말씀드려야겠네요. 하지만, 당신이 필요한 물건은 모두 가지고 있을 겁니다. 그녀는 점술가 언덕의 동쪽에서 상점을 운영하고 있습니다.', `FemaleText_loc4`='利萨尔丝可能……看上去有点凶，但是她出售你想要的东西。她在占星者平台的东部。', `FemaleText_loc5`='麗斯瑞司剛開始看起來可能會有一點...可怕，不過她有你想找的東西。她在占卜者階梯的東部地區販賣她的商品。', `FemaleText_loc7`='Lisrythe puede ser un poco... intimidante al principio, pero tiene lo que buscas. Vende su mercancía en la parte oriental de la Grada del Arúspice.' WHERE `ID`=20391;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<육중한 손가락으로 점술가 언덕의 동쪽을 가리킵니다.>', `MaleText_loc4`='<这台构造体生物对着平台的东部做了个手势。>', `MaleText_loc5`='<這棟建築物標示出它是位於該區東部的地方。>', `MaleText_loc7`='<El constructo hace un gesto hacia la parte oriental de la Grada.>' WHERE `ID`=20392;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엑소다르의 드레나이에게 우호적 평판을 얻기 전에는 당신을 훈련시킬 수 없습니다.', `MaleText_loc4`='在你向埃索达的德莱尼人证明你是我们朋友之前，我是不会训练你的。', `MaleText_loc5`='除非你可以證明你自己是艾克索達德萊尼的朋友，不然我無法訓練你。', `MaleText_loc7`='No voy a instruirte hasta que demuestres ser $gamigo:amiga; de los draenei de El Exodar.', `FemaleText_loc1`='엑소다르의 드레나이에게 우호적 평판을 얻기 전에는 당신을 훈련시킬 수 없습니다.', `FemaleText_loc4`='在你向埃索达的德莱尼人证明你是我们朋友之前，我是不会训练你的。', `FemaleText_loc5`='除非你可以證明你自己是艾克索達德萊尼的朋友，不然我無法訓練你。', `FemaleText_loc7`='No voy a instruirte hasta que demuestres ser $gamigo:amiga; de los draenei de El Exodar.' WHERE `ID`=20393;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드레나이에게 확고한 동맹 평판을 얻기 전에는 당신을 훈련시킬 수 없습니다.', `MaleText_loc4`='如果你还没有在德莱尼人阵营中达到崇拜声望，我是不会训练你的。', `MaleText_loc5`='除非你與德萊尼達到崇拜的聲望，不然我無法訓練你。', `MaleText_loc7`='No te voy a instruir hasta que seas $gexaltado:exaltada; a ojos de los draenei.', `FemaleText_loc1`='드레나이에게 확고한 동맹 평판을 얻기 전에는 당신을 훈련시킬 수 없습니다.', `FemaleText_loc4`='如果你还没有在德莱尼人阵营中达到崇拜声望，我是不会训练你的。', `FemaleText_loc5`='除非你與德萊尼達到崇拜的關係，不然我無法訓練你。', `FemaleText_loc7`='No te voy a instruir hasta que seas $gexaltado:exaltada; a ojos de los draenei.' WHERE `ID`=20394;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 녀석들을 잡아먹어라, 내 아이들아!', `MaleText_loc4`='放狗！', `MaleText_loc5`='釋放這群卑劣的人吧!', `MaleText_loc7`='¡Soltad a los perros!' WHERE `ID`=20395;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수도자님, 준비됐습니다. 퇴마 의식을 시작하시지요.', `MaleText_loc4`='我准备好了，学者。开始驱魔仪式吧。', `MaleText_loc5`='隱士，我準備好了，開始施展驅邪術吧。', `MaleText_loc7`='Estoy listo, Anacoreta. Comencemos el exorcismo.', `FemaleText_loc1`='수도자님, 준비됐습니다. 퇴마 의식을 시작하시지요.', `FemaleText_loc4`='我准备好了，学者。开始驱魔仪式吧。', `FemaleText_loc5`='隱士，我準備好了，開始施展驅邪術吧。', `FemaleText_loc7`='Estoy lista, Anacoreta. Comencemos el exorcismo.' WHERE `ID`=20396;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 고맙소! 내 안에 있던 암흑의 기운이 사라졌어! 다시 앞이 보이는군... 나를 구해준 자의 얼굴이 보여!', `MaleText_loc4`='喔，谢谢你！我体内的黑暗物质已经被驱除了！我的眼睛又能看见东西了……啊，我看到了救世主的脸庞！', `MaleText_loc5`='謝謝你!我內心的黑暗深淵已被解放，我又可以看見了...我看見救命恩人的臉龐!', `MaleText_loc7`='¡Oh, gracias! ¡La negrura que había en mi interior se ha disipado! Veo de nuevo... ¡y veo la cara de quien me ha salvado!' WHERE `ID`=20397;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='썩 물러가라, $c! 우리를 그냥 두지 않으면 다음에는 네 몸에 들어가 진정한 절망감이 무엇인지 보여주겠다!', `MaleText_loc4`='滚开，$c！离我们远点，否则我们会让你知道什么是真正的绝望！', `MaleText_loc5`='滾開，$c!不要煩我們，否則我們下次會讓你陷入真正的絕望!', `MaleText_loc7`='¡Vete, $c! ¡Déjanos en paz o entraremos en ti y te mostraremos lo que es la auténtica desesperación!' WHERE `ID`=20398;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='때가 되었군. 이제 퇴마 의식을 시작하겠습니다...', `MaleText_loc4`='是时候了。驱魔仪式马上开始……', `MaleText_loc5`='時間到了。驅邪祭儀現在開始...', `MaleText_loc7`='Es la hora. El rito del exorcismo comenzará ahora...' WHERE `ID`=20400;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='철저히 준비하십시오. 절대 악마들이 의식을 방해하도록 놔둬서는 안 됩니다. 그러면 우리의 숭고한 영혼을 잃게 됩니다...', `MaleText_loc4`='做好准备。不要让这仪式被打断，否则我们会失去他……', `MaleText_loc5`='做好準備，儀式不可以中斷，不然我們會失去我們的病人...', `MaleText_loc7`='Prepárate. No dejes que el ritual se interrumpa o podríamos perder a nuestro paciente...' WHERE `ID`=20401;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저리 비켜라. 이 녀석의 영혼은 내 것이다!', `MaleText_loc4`='小心。这个蠢货交给我来对付。', `MaleText_loc5`='保持距離。這個蠢蛋是我的。', `MaleText_loc7`='Mantente alejado. El infeliz es mío.' WHERE `ID`=20402;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='인간이여, 빛으로 정화되리니! 마력의 오염에 휩쓸리지 않을지어다!', `MaleText_loc4`='让圣光净化你吧，人类！让恶魔的腐蚀不再吞噬你的灵魂！', `MaleText_loc5`='人類，用聖光淨化你吧!別讓惡魔腐敗征服你。', `MaleText_loc7`='¡Purifícate con la Luz, $ghumano:humana;! No dejes que la corrupción demoníaca te abrume.' WHERE `ID`=20403;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물러가라, 사악한 어둠의 존재여! 이곳에서 너는 한낱 힘없는 존재에 불과하다!', `MaleText_loc4`='退却吧，肮脏的黑暗！你在这里没有力量！', `MaleText_loc5`='回去，黑暗的邪惡生物!你們在這裡沒有力量!', `MaleText_loc7`='¡Atrás, nauseabundos seres de la oscuridad! ¡Aquí no tenéis poder!' WHERE `ID`=20404;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛의 힘이 너를 쓰러뜨리리라! 네 지옥으로 돌아가라!', `MaleText_loc4`='让圣光的力量来驱散你！回到你的深渊去吧！', `MaleText_loc5`='聖光的力量在逼迫著你!回到黑暗深淵去吧!', `MaleText_loc7`='¡La energía de la Luz te fuerza! ¡De vuelta a tu agujero!' WHERE `ID`=20405;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성스러운 빛의 이름으로 명한다! 빛의 이름으로 내, 너를 암흑의 구렁텅이로 몰아내리라!', `MaleText_loc4`='以圣光的名义！以圣光的名义号令你！圣光将会把你抛回黑暗的深渊中去！', `MaleText_loc5`='以聖光之名!聖光命令著你!聖光讓你陷入黑暗的深淵!', `MaleText_loc7`='¡En nombre de la Luz! ¡Es la Luz quien te ordena! ¡Es la Luz quien te arrojó a las profundidades de la Oscuridad!' WHERE `ID`=20406;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으... 난 물러설 수... 없다!', `MaleText_loc4`='我……不能……失败！', `MaleText_loc5`='我...不能...退縮!', `MaleText_loc7`='¡No... debo... vacilar!' WHERE `ID`=20407;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성스러운 빛은 나의 안내자이자... 나의 양식이니라!', `MaleText_loc4`='圣光指引着我……它一直支持着我！', `MaleText_loc5`='聖光是我的指引...是我的食糧!', `MaleText_loc7`='La Luz es mi guía... ¡es mi sustento!' WHERE `ID`=20408;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나를 속일 수는 없다, 악마여! 내 믿음이 커지는 만큼 네 힘은 약해지리니!', `MaleText_loc4`='你欺骗不了我，恶魔！你的力量因为我对信念的坚持而渐渐变弱了！', `MaleText_loc5`='惡魔，你騙不了我的!你的力量持續衰弱，正如我信念不斷壯大!', `MaleText_loc7`='¡No puedes engañarme, demonio! ¡Tu fuerza mengua mientras mi fe se refuerza!' WHERE `ID`=20409;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그... 숭고한 영혼에서... 떠날... 지어다!', `MaleText_loc4`='你……会……离开……这个人的……躯体！', `MaleText_loc5`='你...要...離開...這個...人!', `MaleText_loc7`='¡Dejarás... a... este... hombre!' WHERE `ID`=20410;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으... 우리에게 시간을 줘... 이 인간 녀석은 죽게 놔두란 말이다... 나는 아무것도 아니다... 으, 나는 아무것도 아니란 말이야... 두려워하라... 수도자를... 바라다... 바라다.', `MaleText_loc4`='给我们一点时间……让这人死去吧……我谁都不是……我谁都不是……让那学者感到恐惧吧……让那学者感到恐惧吧……巴拉达……巴拉达。', `MaleText_loc5`='給我們時間...讓這個人死...我誰也不是...我誰也不是...害怕隱士...害怕隱士...巴瑞達...巴瑞達。', `MaleText_loc7`='Danos tiempo... Deja que el hombre muera... No soy nadie... No soy nadie... Teme al anacoreta... Teme al anacoreta... Barada... Barada.' WHERE `ID`=20411;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 아직은 안 된다! 이 영혼은 우리 것이다!', `MaleText_loc4`='不！不要！这个灵魂属于我们！', `MaleText_loc5`='不!還不行!這個靈魂是我們的!', `MaleText_loc7`='¡No! ¡Todavía no! ¡Esta alma es nuestra!' WHERE `ID`=20412;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너는 절대 성공할 수 없다, 필멸의 존재여! 네 육체의 껍데기는 피를 흘리며 고통스럽게 약해지다가 내 손에 죽게 되리라. 그리고 그 영혼은 멀리 암흑 속으로 내던져질 것이야.', `MaleText_loc4`='你不会成功的，凡人！这具躯壳很快就会逐渐衰老，生疮，流血而亡。他的灵魂将永远被禁锢在黑暗中。', `MaleText_loc5`='凡人，你們是無法成功的!在我完成之前，這個外殼將會破爛不堪、起泡流血。而它的靈魂將會被驅散至黑暗之中。', `MaleText_loc7`='¡No lo conseguirás, mortal! Este cuerpo estará decrépito, con ampollas y sangrante antes de que acabe con él. Y su espíritu será arrojado a la Oscuridad mucho antes.' WHERE `ID`=20413;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아악! 주문을 멈춰라, 수도자여! 멈추지 않으면 너희 한심한 족속들이 상상도 못한 고통을 맛보게 해주겠다!', `MaleText_loc4`='啊！停止你的咒语，学者！停下，否则我会让你体会到你们这些可悲的凡人从未想象过的痛苦！', `MaleText_loc5`='啊!停止唸咒吧，隱士!快停止，要不然我會讓你嚐嚐你可悲的族人想像不到的痛苦!', `MaleText_loc7`='¡Ah! ¡Detén los conjuros, Anacoreta! ¡Detente o te mostraré un dolor que tu patético pueblo nunca ha podido imaginarse!' WHERE `ID`=20414;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너의 선조가 보이는구나, 수도자여! 그들은 어둠 속에서 몸부림치며 괴로워하고 있다... 너희 선조가 우리와 함께 있다!', `MaleText_loc4`='我看到了你的祖先，学者！他们在黑暗中翻滚着，尖叫着……他们和我们在一起！', `MaleText_loc5`='隱士，我看到你的祖先了!他們在黑暗中痛苦的扭動尖叫...他們與我們同在!', `MaleText_loc7`='¡Veo a tus ancestros, anacoreta! Se retuercen y gritan en la oscuridad... ¡están con nosotros!' WHERE `ID`=20415;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소용없는 짓이다, 멍청한 드레나이 녀석! 너희 힘으로는 내게서 이 불쌍한 인간을 빼앗을 수 없다. 이자는 내 것이야!', `MaleText_loc4`='这是徒劳的，德莱尼人！你和你弱小的助手们夺不回这个悲惨人类的控制权。他是我的！', `MaleText_loc5`='德萊尼，這是沒用的!你和你的小幫手無法控制這個可悲的人類。他是我的!', `MaleText_loc7`='¡Es inútil, draenei! Tu pequeño ayudante y tú no podéis arrancarme el control de este patético humano. ¡Es mío!' WHERE `ID`=20416;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 영혼을 갈가리 찢어서 악마의 불꽃 위에서 천천히 익혀주겠다!', `MaleText_loc4`='我会把你的灵魂撕成碎片，把它们放在恶魔之火上慢慢灸烤！', `MaleText_loc5`='我會將你的靈魂撕成碎片並且慢慢地用惡魔火焰烘烤它們!', `MaleText_loc7`='¡Haré pedazos tu alma y los asaré lentamente sobre fuego demoníaco!' WHERE `ID`=20417;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소용없다, 수도자여! 말도 안 되는 희망 따위는 버려라.', `MaleText_loc4`='一切都失败了，学者！放弃残存的希望吧。', `MaleText_loc5`='什麼都沒了，隱士!捨棄最後的希望。', `MaleText_loc7`='¡Todo está perdido, anacoreta! Abandona cualquier esperanza que albergues.' WHERE `ID`=20418;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물러서! 이번엔 내 주문을 받아라... 신념의 파괴자! 고통의 창조자! 다시 돌아오는 날엔 오늘 네가 저지른 만행을 똑같이 되돌려받으리라!', `MaleText_loc4`='退散！我命令你退散……信念的腐蚀者！痛苦的创造者！不要再回来，否则你会遭受到和今天同样的失败命运。', `MaleText_loc5`='回去!你給我回去...信仰的墮落者!痛苦的肇始者!別再回來了，要不然你會遭受和今天一樣的命運!', `MaleText_loc7`='¡Atrás! Atrás, te digo... ¡Corruptor de la fe! ¡Autor de dolor! ¡No vuelvas o correrás la misma suerte que hoy!' WHERE `ID`=20419;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='디버그 오류: 대상을 찾을 수 없습니다!', `MaleText_loc4`='纠错信息：找不到目标！', `MaleText_loc5`='Debug Error: 找不到目標!', `MaleText_loc7`='Debug Error: Couldn''t find a target!' WHERE `ID`=20420;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나의 마법을 받아라! 부정한 영혼이여!', `MaleText_loc4`='我要驱逐你！肮脏的邪灵！', `MaleText_loc5`='我要驅散你!不潔的靈魂!', `MaleText_loc7`='¡Yo te expulso! ¡Espíritu impuro!' WHERE `ID`=20421;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 빛의 존재에서... 떨어져라!', `MaleText_loc4`='滚开……从这个皈依圣光的人身上滚开！', `MaleText_loc5`='走吧...遠離這個聖光生物!', `MaleText_loc7`='Sal... ¡de esta criatura de la Luz!' WHERE `ID`=20422;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사라져라! 빛의 이름과 신과 세상의 모든 정의를 대신하여 명한다!', `MaleText_loc4`='滚开！以善良的名义！以正义的名义！以圣光的名义！', `MaleText_loc5`='走吧!以聖光，仁慈，和所有公正的事物之名!', `MaleText_loc7`='¡Vete! ¡En nombre de la Luz, la Bondad y de todo lo que es justo!' WHERE `ID`=20423;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='징검다리 거점은 더할 나위 없이 튼튼하니 걱정하지 마십시오! 그러나 만약의 상황에 대비하여 그리핀에 올라탈 준비를 하십시오. 이 땅이 조각날 수도 있으니까요...', `MaleText_loc4`='不要担心，破碎岗哨固若金汤！不过为了以防万一，如果基地开始碎裂的话，你要马上跳上狮鹫……', `MaleText_loc5`='不要擔心。破碎崗哨是一座堅固的堡壘!但是以防萬一，如果基底開始崩塌就立刻跳上獅鷲獸...', `MaleText_loc7`='No te preocupes. ¡El Puesto Devastación es de lo más sólido! Pero, por si acaso, prepárate para saltar sobre un grifo si la plataforma comienza a romperse...' WHERE `ID`=20424;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 나를 능가했으니 서로 기술을 시험토록 하라! 대전을 시작하려면 양 진영의 왕을 제어하면 된다.', `MaleText_loc4`='现在你遇到了我，让我们看看谁的棋艺更加优秀吧！控制国王便可开始棋局。', `MaleText_loc5`='既然你們已勝過我，彼此對抗測試一下你們的技能!控制住任一位國王開始遊戲。', `MaleText_loc7`='¡Ahora que me han superado, pongan a prueba sus habilidades el uno contra el otro! Tomen control de cualquiera de los reyes para comenzar a jugar.' WHERE `ID`=20425;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1과;와; 마주합니다.', `MaleText_loc4`='面对着$n。', `MaleText_loc5`='挑戰$n。', `MaleText_loc7`='de cara a $n.' WHERE `ID`=20426;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아달, 말씀드리기 부끄럽지만, 알카트라즈로 가는 열쇠를 잃어버리고 말았습니다.', `MaleText_loc4`='阿达尔，我很惭愧，我不知怎么把禁魔监狱的钥匙弄丢了。', `MaleText_loc5`='阿達歐，我感到很羞愧，我不知道怎麼搞的竟然把通往亞克崔茲的鑰匙搞丟了。', `MaleText_loc7`='A''dal, me da vergüenza decir que, de algún modo, he perdido la llave del Arcatraz.', `FemaleText_loc1`='아달, 말씀드리기 부끄럽지만, 알카트라즈로 가는 열쇠를 잃어버리고 말았어요.', `FemaleText_loc4`='阿达尔，我很惭愧，我不知怎么把禁魔监狱的钥匙弄丢了。', `FemaleText_loc5`='阿達歐，我感到很羞愧，我不知道怎麼搞的竟然把通往亞克崔茲的鑰匙搞丟了。', `FemaleText_loc7`='A''dal, me da vergüenza decir que, de algún modo, he perdido la llave del Arcatraz.' WHERE `ID`=20427;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<종소리처럼 은은히 마음속에 울려 퍼지면서 안도감을 주는 아달의 음성>$B$B열쇠를 그대의 가방 안에 넣어놓을 테니 아무 걱정하지 마시오.', `MaleText_loc4`='<阿达尔和谐而婉转的音响再次传入了你的心灵。>$B$B不要担心，孩子。看看你的背包，你会再次找到它的。', `MaleText_loc5`='<阿達歐溫暖的聲音傳入你的心裡，鼓舞著你。>$B$B別擔心，孩子。看看你的背包，你就可以再一次找到它。', `MaleText_loc7`='<El timbre de voz de A''dal resuena de modo tranquilizador por tu mente.>$B$BNo te preocupes, $ghijo:hija;. Mira en tu talega y la volverás a encontrar.' WHERE `ID`=20428;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$r|1이여;여;, 절 찾아오셨습니까?', `MaleText_loc4`='$R，你想跟我谈谈？', `MaleText_loc5`='你有事要和我說嗎，$r?', `MaleText_loc7`='¿Deseas hablar conmigo, $r?' WHERE `ID`=20429;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='승부사의 전당의 입구에 걸린 저주가 풀리려는 듯, 카라잔의 전당이 심하게 흔들립니다.', `MaleText_loc4`='当附着在象棋大厅门上的诅咒被驱散的同时，卡拉赞的大厅也开始剧烈地颤抖。', `MaleText_loc5`='投機者大廳之門的詛咒已經被解開了，卡拉贊的大廳為之劇烈搖晃。', `MaleText_loc7`='Las salas de Karazhan tiemblan, mientras se alza la maldición que sellaba las puertas de la Sala del Tablero.' WHERE `ID`=20430;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 이 무덤에서 수많은 위험을 보았습니다. 어떤 생물이 경솔한 자들을 습격하려고 자욱한 먼지 속에 아직도 숨어있을지 누가 알겠습니까?', `MaleText_loc4`='我在这片荒野上看到了许多危险的存在。谁会注意到那些生物竟然潜伏在灰烬中，准备伏击那些粗心大意的旅者呢？', `MaleText_loc5`='我已經在這片荒原看過太多危險了。誰知道在荒原的塵土之下還潛伏了什麼怪物準備伏擊那些粗心的旅人呢?', `MaleText_loc7`='He visto muchos peligros en estos residuos. ¿Quién sabe qué criaturas acechan en el polvo para atacar al desprevenido?' WHERE `ID`=20431;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈들의 노력은 수포로 돌아갔다! 이미 세계수의 힘을 빨아들이기 시작했다. 이제 세계의 심장은 영원히 박동을 멈추리라!', `MaleText_loc4`='你们所有的努力全都是白费力气，我已经开始吸取世界之树的力量了！很快，你们这个世界的将失去活力。', `MaleText_loc5`='你所做的努力都是白費的，吸取世界之樹的魔力早就已經開始了!很快你們的世界將會失去生命的脈動!', `MaleText_loc7`='¡Todos sus esfuerzos han sido en vano! ¡El Árbol del Mundo ya ha empezado a secarse! ¡Pronto el corazón de su mundo dejará de latir!' WHERE `ID`=20432;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 우리 알도르 사제회에 대한 평판이 충분하지 않거나 사제회에 헌신하지 않는군요.', `MaleText_loc4`='你没有足够的声望，或尚未宣誓效忠奥尔多。', `MaleText_loc5`='你對奧多爾的聲望不足或者尚未宣誓效忠奧多爾。', `MaleText_loc7`='No tienes suficiente reputación con los Aldor o no les has jurado lealtad.', `FemaleText_loc1`='당신은 우리 알도르 사제회에 대한 평판이 충분하지 않거나 사제회에 헌신하지 않는군요.', `FemaleText_loc4`='你没有足够的声望，或尚未宣誓效忠奥尔多。', `FemaleText_loc5`='你對奧多爾的聲望不足或者尚未宣誓效忠奧多爾。', `FemaleText_loc7`='No tienes suficiente reputación con los Aldor o no les has jurado lealtad.' WHERE `ID`=20433;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 우리 점술가 길드에 대한 평판이 충분하지 않거나 길드에 헌신하지 않는군요.', `MaleText_loc4`='你没有足够的声望，或尚未宣誓效忠占星者。', `MaleText_loc5`='你對占卜者的聲望不足或者尚未宣誓效忠占卜者。', `MaleText_loc7`='No tienes suficiente reputación con los Arúspices o no les has jurado lealtad.', `FemaleText_loc1`='당신은 우리 점술가 길드에 대한 평판이 충분하지 않거나 길드에 헌신하지 않는군요.', `FemaleText_loc4`='你没有足够的声望，或尚未宣誓效忠占星者。', `FemaleText_loc5`='你對占卜者的聲望不足或者尚未宣誓效忠占卜者。', `FemaleText_loc7`='No tienes suficiente reputación con los Arúspices o no les has jurado lealtad.' WHERE `ID`=20434;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 내가 풀려났군! 감사합니다, 친절하신 $r|1이여;여;. 즉시 세나리온 원정대에 돌아가야겠습니다! 원정대 모두가 당신의 공적을 알게 될 것입니다. 내 맹세하지요.', `MaleText_loc4`='我终于自由了！谢谢你，高尚的$r。我必须马上回到远征队去！我发誓一定会把你的事迹告诉他们的。', `MaleText_loc5`='我終於自由了!感謝你，仁慈的$r。我必須馬上返回遠征隊!我會讓他們知道你的義行。我發誓。', `MaleText_loc7`='¡Al menos soy libre! Gracias, gentil $r. ¡Debo volver a la expedición lo antes posible! Les contaré lo que has hecho por mí. Te lo prometo.', `FemaleText_loc1`='드디어 내가 풀려났군! 감사합니다, 친절하신 $r|1이여;여;. 즉시 세나리온 원정대에 돌아가야겠습니다! 원정대 모두가 당신의 공적을 알게 될 것입니다. 내 맹세하지요.', `FemaleText_loc4`='我终于自由了！谢谢你，高尚的$r。我必须马上回到远征队去！我发誓一定会把你的事迹告诉他们的。', `FemaleText_loc5`='我終於自由了!感謝你，仁慈的$r。我必須馬上返回遠征隊!我會讓他們知道你的義行。我發誓。', `FemaleText_loc7`='¡Al menos soy libre! Gracias, gentil $r. ¡Debo volver a la expedición lo antes posible! Les contaré lo que has hecho por mí. Te lo prometo.' WHERE `ID`=20435;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 하라매드 님께 당신의 영웅적인 일화를 들려드릴 것입니다! 모든 무역연합 일원들이 당신의 이름을 알게 될 겁니다. 고맙습니다, 친구여!', `MaleText_loc4`='我会把你的英雄事迹亲自讲述给哈拉迈德听！星界财团的所有人都会知道你的名字，$n。感谢你，我的朋友。', `MaleText_loc5`='我會親自向哈拉瑪德陳述你的英勇事蹟!聯合團全體人員都將知道你的大名，$n。感謝你，我的朋友。', `MaleText_loc7`='¡Le contaré la historia de nuestros héroes a Haramad en persona! Todo el Consorcio conocerá tu nombre, $n. Gracias.' WHERE `ID`=20436;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='시간의 수호자의 일원이 당신의 도움에 감사를 표하고 있습니다. 시간의 지배자께서 이번 결과에 만족해하실 겁니다...', `FemaleText_loc4`='时光守护者感谢你的帮助。时间之王一定会为这个结果而感到高兴的……', `FemaleText_loc5`='時光守望者感謝你的協助。永恆之王若是知道這個結果一定會很滿意...', `FemaleText_loc7`='Los Vigilantes del Tiempo te agradecen tu ayuda. El Atemporal se alegrará de este resultado...' WHERE `ID`=20437;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐... 뭐지? 내가 어디 있는 겁니까? 어떻게... 내가 어떻게... 저주받을 에테리얼 녀석들! 우리가 공격받았을 때 전 샤트라스를 나와 호위 임무를 수행하고 있었습니다! 어서 샤트라스로 돌아가야겠군요! 당신의 이름은 고난의 거리의 친구로서 기억될 겁니다, $n|1이여;여;.', `MaleText_loc4`='这是什么？我在哪里？怎么回事……我怎么……该死的虚灵！我在沙塔斯城外执行护卫任务的时候遭到了伏击！现在，我必须马上回到城市里去！你的名字一定会被贫民窟的居民铭记的，$n。', `MaleText_loc5`='發生什麼事了?這是哪裡?我...我怎麼會...該死的以太族!我本來在執行一項從撒塔斯城出發的護送任務，後來我們受到了伏擊!我必須馬上返回撒塔斯城!你的大名將被陰鬱城的人們以盟友之名流傳著，$n。', `MaleText_loc7`='¿Qué pasa? ¿Dónde estoy? ¿Cómo...? ¿Cómo...? ¡Malditos etéreos! ¡Participaba en una misión como escolta en Shattrath cuando caímos en una emboscada! ¡Debo volver a la ciudad ya! Grabaremos tu nombre como aliado del Bajo Arrabal, $n.' WHERE `ID`=20438;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛의 가호가 있기를! 내 감금이 드디어 풀렸구나... 영웅이시어, 감사합니다. 아달께서 당신의 공적을 알게 되실 겁니다.', `MaleText_loc4`='感谢圣光！我终于又获得了自由……感谢你，英雄。我会把你的英雄事迹告诉阿达尔。', `MaleText_loc5`='感謝聖光!終於從我的幽禁之中解脫啦...感謝你，我的英雄。阿達歐將會流傳你的英勇事蹟。', `MaleText_loc7`='¡Bendita Luz! Al fin libre de mi confinamiento... Gracias, héroe. A''dal sabrá de tu heroísmo.', `FemaleText_loc1`='빛의 가호가 있기를! 내 감금이 드디어 풀렸구나... 영웅이시어, 감사합니다. 아달께서 당신의 공적을 알게 되실 겁니다.', `FemaleText_loc4`='感谢圣光！我终于又获得了自由……感谢你，英雄。我会把你的英雄事迹告诉阿达尔。', `FemaleText_loc5`='感謝聖光!終於從我的幽禁之中解脫啦...感謝你，我的英雄。阿達歐將會流傳你的英勇事蹟。', `FemaleText_loc7`='¡Bendita Luz! Al fin libre de mi confinamiento... Gracias, héroe. A''dal sabrá de tu heroísmo.' WHERE `ID`=20439;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$R|1이;가; 나를 구해주셨군요! 감사합니다! 우리 종족들도 당신에게 고마워한답니다!', `MaleText_loc4`='$r救了我！谢谢你！我的族人同样会感谢你！', `MaleText_loc5`='$R救我!感謝你!我的同胞們也會感謝你!', `MaleText_loc7`='¡$R, sálvame! ¡Gracias! ¡Mi pueblo te da las gracias también!' WHERE `ID`=20440;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 눈을 들여다보라... 그 깊은 곳에서 너의 종말을 보리라!', `MaleText_loc4`='看着我的眼睛……在这里寻找你的死亡吧……', `MaleText_loc5`='看我的眼中...有你死亡的倒影...', `MaleText_loc7`='Mírame a los ojos... Encuentra la muerte dentro...' WHERE `ID`=20441;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='삼켜지리라! 일리단 군주께서 가시는 길에 있는 모든 자들이 삼켜지리라!', `MaleText_loc4`='自由！自由地吞噬那些试图阻挠伊利丹大人的家伙吧！', `MaleText_loc5`='我自由啦!我可以自由的殺光那些妄想阻止伊利丹王的可憐蟲!', `MaleText_loc7`='¡LIBRE! ¡LIBRE PARA DEVORAR TODO LO QUE SE PONGA EN EL CAMINO DE LORD ILLIDAN!' WHERE `ID`=20442;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너의 망각의 문이 열렸다! 피의 파도가 솟아오르리라!', `MaleText_loc4`='通向毁灭的大门已经被打开了！让血腥的杀戮开始吧！', `MaleText_loc5`='你已經殺到麻木不仁了!現場血流成河。', `MaleText_loc7`='¡La puerta de tu olvido se ha abierto! Sube la marea de sangre.' WHERE `ID`=20443;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일천 가지에 하나 더 해서 네 녀석에게 죽음을 선포해 주마!', `MaleText_loc4`='无数的征兆都清楚地说明，你死定了！', `MaleText_loc5`='我有一千零一種讓你死亡的方法!', `MaleText_loc7`='¡Una y mil formas de que todos hablen de tu muerte!' WHERE `ID`=20444;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자! 왕 돌아오셨다, 요 녀석!', `MaleText_loc4`='什么！国王回来了，宝贝！', `MaleText_loc5`='喔耶!大王回來了，寶貝!', `MaleText_loc7`='¡OH! ¡EL REY HA VUELTO!' WHERE `ID`=20445;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아웃랜드에선 점심거리 널려 있다! 얼마나 좋은 곳인가! 자, 식사 시간이다!', `MaleText_loc4`='外域的监狱开饭了！多好的世界啊！到吃饭的时间了！', `MaleText_loc5`='在外域，竟然會為了一頓午餐坐牢!這是什麼世界阿!午餐時間到了!', `MaleText_loc7`='¡En Terrallende, comida gratis en la prisión! ¡Qué mundo! ¡Hora de comer!' WHERE `ID`=20446;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오직 피와 살을...', `MaleText_loc4`='只有血肉……', `MaleText_loc5`='只有血肉而已...', `MaleText_loc7`='Solo carne y sangre...' WHERE `ID`=20447;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기만자를 위하여! 킬제덴을 위하여!', `MaleText_loc4`='为了欺诈者！为了基尔加丹！', `MaleText_loc5`='為了欺詐者!為了基爾加丹!', `MaleText_loc7`='¡Por el Falsario! ¡Por Kil''jaeden!' WHERE `ID`=20448;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='죽어라! 죽음만이 널 기다리는 유일한 것이다!', `FemaleText_loc4`='死吧！等待你的只有死亡！', `FemaleText_loc5`='死亡!前方只有死亡等待著你!', `FemaleText_loc7`='¡Muerte! ¡Solo aguarda la Muerte!' WHERE `ID`=20449;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 손에 입을 맞춰라...', `FemaleText_loc4`='给我们一个吻……', `FemaleText_loc5`='給我們一吻吻吻...', `FemaleText_loc7`='Danos un besssso...' WHERE `ID`=20450;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아웃랜드의 분쟁은 그 어떤 곳보다 더 심각한 파국으로 치닫고 있네. 그 싸움의 가장 불쌍한 희생양은 바로 부모를 잃고 홀로 남은 아이들이지.$B$B스케티스의 아라코아들이 샤트라스를 크게 위협하고 있는 지금, 그 어느 때보다 도움의 손길이 필요한 고아들이 많다네. 밝은 미래에 대한 어떠한 희망도 없이 살아가는 아이들이지.$B$B하지만, 자네라면 그 아이들을 도와줄 수 있네. 지금은 어린이 주간일세. $c|1이여;여;, 고아들의 외로운 삶에 기적과 같은 기쁨을 선물해 주게나.', `FemaleText_loc4`='外域的战争比我之前所经历过的任何战争都要惨烈。大部分受害者都是那些留在后方的孩子。$B$B现在，斯克提斯的鸦人对沙塔斯城的威胁进一步加剧，那里会有更多的孤儿需要照顾。这些孩子几乎已经看不到光明的未来。$B$B但是，你却有能力为他们做些什么。儿童周来了，$c，我恳求你给这些孩子的生活带来些乐趣和奇迹吧。', `FemaleText_loc5`='我從未見過一塊土地經歷像外域如此激烈的戰爭與衝突。最悲慘的受害者是那些被遺棄的孩子們。$B$B而現在撒塔斯城與司凱堤斯的阿拉卡之間的衝突將導致更多的孤兒需要人照顧。這些孩子們通常在沒有未來的希望下成長。$B$B但是你有能力改變這個情形。現在是兒童週，$c，我懇求你自願將歡樂與希望帶給這些孤兒們。', `FemaleText_loc7`='Los conflictos en Terrallende son los más cruentos que nunca haya visto. Y las víctimas más trágicas son los niños que quedan atrás.$B$BAhora, con la amenaza contra Shattrath de los arakkoa de Skettis, surgirán aún más huérfanos a los que cuidar. Estos niños a menudo viven sin la esperanza de un futuro.$B$BPero tú puedes hacer algo al respecto. Es la Semana de los Niños, $c, y te ruego que trabajes como voluntario para llevar alegría e ilusión a la vida de un niño.' WHERE `ID`=20451;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어린이 주간은 아직 끝나지 않았잖아요. 그래서 말인데, 블러드 엘프 고아 호루라기를 또 얻을 수 있을까요?', `MaleText_loc4`='儿童周还没有结束……我能得到另一个血精灵孤儿哨吗？', `MaleText_loc5`='兒童週尚未結束...我可以再向你要一個血精靈孤兒哨嗎?', `MaleText_loc7`='La Semana de los Niños todavía no ha terminado... ¿Me puedes dar otro silbato de huérfano elfo de sangre?', `FemaleText_loc1`='어린이 주간은 아직 끝나지 않았잖아요. 그래서 말인데, 블러드 엘프 고아 호루라기를 또 얻을 수 있을까요?', `FemaleText_loc4`='儿童周还没有结束……我能得到另一个血精灵孤儿哨吗？', `FemaleText_loc5`='兒童週尚未結束...我可以再向你要一個血精靈孤兒哨嗎?', `FemaleText_loc7`='La Semana de los Niños todavía no ha terminado... ¿Me puedes dar otro silbato de huérfano elfo de sangre?' WHERE `ID`=20452;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어린이 주간은 아직 끝나지 않았잖아요. 그래서 말인데, 드레나이 고아 호루라기를 또 얻을 수 있을까요?', `MaleText_loc4`='儿童周还没有结束……我能得到另一个德莱尼孤儿哨吗？', `MaleText_loc5`='兒童週尚未結束...我可以再向你要一個德萊尼孤兒哨嗎?', `MaleText_loc7`='La Semana de los Niños todavía no ha terminado... ¿Me puedes dar otro silbato de huérfana draenei?', `FemaleText_loc1`='어린이 주간은 아직 끝나지 않았잖아요. 그래서 말인데, 드레나이 고아 호루라기를 또 얻을 수 있을까요?', `FemaleText_loc4`='儿童周还没有结束……我能得到另一个德莱尼孤儿哨吗？', `FemaleText_loc5`='兒童週尚未結束...我可以再向你要一個德萊尼孤兒哨嗎?', `FemaleText_loc7`='La Semana de los Niños todavía no ha terminado... ¿Me puedes dar otro silbato de huérfana draenei?' WHERE `ID`=20453;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 외로워요. 이 근처에 제 또래 친구들이 더 많았으면 좋겠어요. 어떤 때는 샤트라스 고아원 시절이 그립답니다.', `MaleText_loc4`='我很寂寞。我希望在这里有更多的和我同龄的孩子。有时候，我真的很怀念在沙塔斯城孤儿院的日子。', `MaleText_loc5`='我很孤單。真希望這裡有更多和我同齡的孩子。有時候我還真懷念在撒塔斯城孤兒院的日子。', `MaleText_loc7`='Me siento solo. A veces me gustaría que hubiese más niños de mi edad por aquí. A veces echo de menos el orfanato de Ciudad de Shattrath.' WHERE `ID`=20454;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙습니다! 살란드리아랑 다시 얘기할 수 있어서 기뻤어요!', `MaleText_loc4`='谢谢你，$g先生:女士;！能再和萨兰蒂亚谈话实在是太好了！', `MaleText_loc5`='謝謝你，$g先生:女士;!能再和瑟蘭德雅說話真是太好了!', `MaleText_loc7`='¡Gracias, $g señor : señora;! ¡Ha sido genial poder hablar con Salandria de nuevo!' WHERE `ID`=20455;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아직도 출발 안 하고 뭐 우물쭈물하시는 거예요?', `FemaleText_loc4`='我们到了吗？', `FemaleText_loc5`='到了嗎?', `FemaleText_loc7`='¿Falta mucho?' WHERE `ID`=20456;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='히추!!!', `FemaleText_loc4`='哈克乌！！！', `FemaleText_loc5`='胡秋!!!', `FemaleText_loc7`='¡¡¡Hch''uu!!!' WHERE `ID`=20457;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='도르나가 만남의 돌을 살펴본 후 만지기 시작합니다.', `FemaleText_loc4`='多尔南开始观察起这座石质建筑，并轻轻触摸起它的柱子来。', `FemaleText_loc5`='朵娜開始勘查這個石式建築物，然後觸碰它。', `FemaleText_loc7`='Dornaa comienza a examinar el edificio de piedra y despues lo toca.' WHERE `ID`=20458;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 자유의 몸이 되었군! 하지만 비밀이... 노출될 위험에 처했습니다. 아카마에게 위험을 알려야만 합니다!', `MaleText_loc4`='我自由了！但是秘密……有泄露的危险。必须警告阿卡玛！', `MaleText_loc5`='我自由了!可是那件秘密...危險了。必須警告阿卡瑪!', `MaleText_loc7`='¡Soy libre! Pero ahora el secreto... peligra. ¡Debo advertir a Akama!' WHERE `ID`=20459;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나가들이 내 의지를 꺾어놓을 뻔했지만... 비밀이 아직 드러나지 않았습니다. 당신에게 감사 드립니다.', `MaleText_loc4`='纳迦几乎就要击碎我的意志了……不过秘密仍然很安全，谢谢你。', `MaleText_loc5`='納迦幾乎要突破我的心防了...但是我還是沒有洩露那件秘密，感謝你。', `MaleText_loc7`='Los nagas casi logran que me rinda... pero el secreto aún está a salvo, gracias a ti.' WHERE `ID`=20460;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제 친구 히추를 만날 수 있게 절 이리로 데려와 주셔서 감사해요!', `FemaleText_loc4`='感谢你带我到这里来看望哈克乌！', `FemaleText_loc5`='感謝你帶我來這裡見我的朋友，胡秋!', `FemaleText_loc7`='¡Gracias por traerme hasta aquí a ver a mi amigo, Hch''uu!' WHERE `ID`=20461;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='왜 이젠 아웃랜드를 드레노어라고 부르지 않는 거죠?', `FemaleText_loc4`='为什么外域不再叫作德拉诺了？', `FemaleText_loc5`='為什麼外域不再叫做德拉諾了呢?', `FemaleText_loc7`='¿Por qué no llaman Draenor a Terrallende ya?' WHERE `ID`=20462;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='와! 정말 멋지다!', `FemaleText_loc4`='哦，哇喔！', `FemaleText_loc5`='哦!', `FemaleText_loc7`='¡Oh, guao!' WHERE `ID`=20463;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이곳이 온 세상의 모험가들이 모이는 곳인가요? 절 좀 도와주세요!', `FemaleText_loc4`='所有的冒险者都是都是从这里出发的吗？', `FemaleText_loc5`='這裡是所有探險家聚集的地方嗎?幫幫我。', `FemaleText_loc7`='¿Es de aquí de donde vienen los aventureros? Ayudadme.' WHERE `ID`=20464;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='악마는 뒤틀린 황천에서 왔잖아요. 그런데 악마가 죽으면 어디로 가나요?', `FemaleText_loc4`='如果恶魔是掉下来的，他们是从哪里掉下来的呢？', `FemaleText_loc5`='如果惡魔們降臨大地，那麼他們是從何而來呢?', `FemaleText_loc7`='Si los demonios cayeron, ¿de dónde cayeron?' WHERE `ID`=20465;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우와, 말도 안 돼!', `FemaleText_loc4`='哇，是不是真的啊！', `FemaleText_loc5`='喔不，不可能!', `FemaleText_loc7`='¡Ah! ¡Ni hablar!' WHERE `ID`=20466;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='살란드리아가 거대한 어둠의 문을 보더니 놀라서 입을 딱 벌리고 쳐다봅니다.', `FemaleText_loc4`='萨兰蒂亚惊愕地看着巨大的黑暗之门。', `FemaleText_loc5`='瑟蘭德雅目瞪口呆的站在黑暗之門的前面感到敬畏。', `FemaleText_loc7`='Salandria se levanta y se queda boquiabierta y sobrecogida ante el inmenso Portal Oscuro.' WHERE `ID`=20467;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='와, 이런!', `FemaleText_loc4`='以圣光的名义！', `FemaleText_loc5`='以聖光之名!', `FemaleText_loc7`='¡Por la Luz!' WHERE `ID`=20469;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뒤틀린 황천이 꽈배기같이 매듭지어진 모양인가요? 그리고 그 황천이 뭔가요? 보육원 원장님이 말씀하시길 사람에게 황천에 대해서 물어봐서는 안 된다고 하셨긴 하지만...', `FemaleText_loc4`='是不是扭曲虚空的形成就像椒盐卷饼那样？还有，“虚空”是什么意思？孤儿院长说我不应该问别人“虚空”是什么感觉。', `FemaleText_loc5`='扭曲虛空的形狀像椒鹽脆餅一樣嗎?什麼是虛空?孤兒監護員說我不應該問別人虛空的事。', `FemaleText_loc7`='¿El Vacío Abisal tiene forma de ocho? ¿Y qué quiere decir Vacío? La matrona del orfanato dice que debería preguntarle a la gente por sus vacíos.' WHERE `ID`=20470;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<하늘 쪽을 흘긋 올려다보는 모르디스>$B$B솔직히 루크와 코르백스가 누리는 자유가 좀 부럽습니다. 세속에 관한 책임에서 자유롭다는 건 진정 큰 축복이죠.$B$B미래에 다시 비상할 수 있겠지만 그에 앞서 끝마쳐야 할 일이 있습니다.', `MaleText_loc4`='<莫希斯注视着天空。>$B$B从某种程度上说，我很羡慕鲁克和考瓦克斯所享受的自由。摆脱大地的束缚事实上是一种伟大的祝福。$B$B将来我会再次进入天空飞翔的，不过我必须先完成一项使命。', `MaleText_loc5`='<莫西斯朝天空掃視。>$B$B某一方面，我忌妒魯克及寇瓦克斯所享有的自由。從世俗的責任中解放的確就是一種最好的祝福。$B$B未來將再次見我展翅高飛，不過首先我得先完成一件任務。', `MaleText_loc7`='<Morthis observa el cielo.>$B$BEn parte, envidio la libertad que disfrutan Grajo y Corvax. En efecto es una gran bendición estar libre de ataduras terrenales.$B$BEl futuro me verá volar de nuevo, pero antes me debo ocupar de una tarea.' WHERE `ID`=20471;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나잔이 하늘에서 내려옵니다.', `MaleText_loc4`='纳杉从天空中缓缓落下。', `MaleText_loc5`='納桑從天而降。', `MaleText_loc7`='Nazan desciende de los cielos.' WHERE `ID`=20472;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='게제 님은 제가 이곳에 와서 수습 과정을 거치도록 정말 잘 대해주시고 이 모든 재미있는 것들을 배우게 해 주셨어요.$B$B<고개를 떨구는 질>$B$B그래도 동생과 떨어져 지내는 건 싫네요.', `MaleText_loc4`='杰赫真是个好人，他让我来这里当学徒。于是我也学到了许多有趣的东西。$B$B<希尔低下了头。>$B$B不过，我讨厌远离妹妹的生活。', `MaleText_loc5`='吉札很好心的讓我來這裡當學徒，學習所有這些有趣的東西，$g先生:女士;。$B$B<吉歐感到很羞愧。>$B$B但是，我很想念我妹妹。她還在撒塔斯城的孤兒院裡。', `MaleText_loc7`='Gezhe ha sido muy amable al dejarme venir aquí a aprender y practicar con todo esto tan divertido, $g señorito : señorita;.$B$B<Jheel agacha la cabeza.>$B$BPero odio estar alejado de mi hermana.' WHERE `ID`=20473;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$G형:누나;, 제 여동생을 이리로 데려와서 절 만나게 해 주셔서 다시 한번 감사 드려요!', `MaleText_loc4`='$n$G先生:小姐;，谢谢你来带我的小妹妹来看我！', `MaleText_loc5`='再次謝謝你帶我妹妹來探望我$n$G先生:小姐;!', `MaleText_loc7`='¡Gracias de nuevo por traer a mi hermana a visitarme, $G Sr. : Sra.; $n!' WHERE `ID`=20474;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='질 오빠!!!', `FemaleText_loc4`='希尔！！！', `FemaleText_loc5`='吉歐!!!', `FemaleText_loc7`='¡¡¡Jheel!!!' WHERE `ID`=20475;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='도르나가 오빠에게 달려가 와락 안깁니다. 두 어린이가 얘기를 나누기 시작합니다.', `FemaleText_loc4`='多尔南给了她哥哥一个深情的拥抱，然后两个孩子开始唧唧喳喳地聊起天来。', `FemaleText_loc5`='朵娜衝向她哥哥，給他一個大大的擁抱，然後兩個孩子便開始交談。', `FemaleText_loc7`='Dornaa le da un gran abrazo a su hermano y los dos niños empiezan a hablar.' WHERE `ID`=20476;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='질 오빠가 곧 보육원으로 돌아오게 되었으면 좋겠어요.', `FemaleText_loc4`='我希望希尔能快点回到孤儿院。', `FemaleText_loc5`='我希望吉歐可以快點回來孤兒院。', `FemaleText_loc7`='Espero que Jheel pueda volver al orfanato pronto.' WHERE `ID`=20477;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오랜만에 만난 살란드리아와 히추가 그간 밀렸던 이야기를 하기 시작합니다.', `FemaleText_loc4`='萨兰蒂亚和哈克乌开始回忆起过去一年间发生在她们身上的事情。', `FemaleText_loc5`='瑟蘭德雅和胡秋開始敘舊，聊著過去一年發生在他們身上的事。', `FemaleText_loc7`='Salandria y Hch''uu se ponen al día de lo que les ha pasado durante el último año.' WHERE `ID`=20478;
