UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 호드 깃발을 기지로 반환했습니다!', `MaleText_loc4`='$n将部落军旗放回到旗座上了！', `MaleText_loc5`='部落旗幟被$n歸還到它的基地了!', `MaleText_loc7`='¡$n ha devuelto la bandera de la Horda a su base!' WHERE `ID`=20480;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살란드리아? 정말 내 친구 살란드리아 맞구나!', `MaleText_loc4`='萨兰蒂亚？萨兰蒂亚！！！', `MaleText_loc5`='瑟蘭德雅?瑟蘭德雅!!!', `MaleText_loc7`='¡¡¡Salandria!!!' WHERE `ID`=20481;
