UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나중에 또 봐, 오빠!', `FemaleText_loc4`='我们很快会再见面的，哥哥！', `FemaleText_loc5`='再見了，哥哥!', `FemaleText_loc7`='¡Hasta pronto, hermano mayor!' WHERE `ID`=20484;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='와, 정말 있잖아! 불의 정령에게 가까이 다가가서 자세히 봐야겠어요!', `FemaleText_loc4`='哈哈，这是真的。我要走近一点去看看正在燃烧的那个。', `FemaleText_loc5`='哈，是真的!我要去仔細看看有火焰的那個!', `FemaleText_loc7`='¡Je, es verdad! ¡Voy a mirar mejor al de fuego!' WHERE `ID`=20485;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오우, 뜨거!', `FemaleText_loc4`='哦！好烫！', `FemaleText_loc5`='哎唷!燙!!', `FemaleText_loc7`='¡Caliente!' WHERE `ID`=20486;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='도르나가 천천히 걷다가 오로스가 그녀에게 축복을 내려주자 공손한 태도로 돌아섭니다.', `FemaleText_loc4`='多尔南缓缓走远。突然，她转过身来，带着敬畏的神情注视着对她施放了祝福的沃洛斯。', `FemaleText_loc5`='當歐蘿絲給予朵娜祝福，她慢慢地走著並敬畏地轉身。', `FemaleText_loc7`='Dornaa camina lentamente y hace una reverencia mientras O''ros la bendice.' WHERE `ID`=20487;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='헤헷, 오로스 님, 텔레파시가 재밌네요. 고맙습니다, 오로스 님! 잘 지내겠다고 약속할게요!', `FemaleText_loc4`='嘻嘻，你的心灵对话让我觉得很有意思。谢谢你，沃洛斯！我答应你，一定会乖乖的！', `FemaleText_loc5`='哈哈，你的腦子呵呵發笑。謝謝你，歐蘿絲!我保證會乖乖的!!', `FemaleText_loc7`='Je, je, tus palabras me divierten. ¡Gracias, O''ros! ¡Prometo portarme bien!' WHERE `ID`=20489;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='올룸. 무사한 걸 보니 한결 맘이 놓이는군.', `MaleText_loc4`='奥鲁姆，我的老朋友。看到你一切安好，真是令人欣慰。', `MaleText_loc5`='歐蘭...老朋友。很高興看到你平安無事。', `MaleText_loc7`='Olum, viejo amigo. ¡Qué bueno ver que estás a salvo!' WHERE `ID`=20490;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일리단은 분명히 의심을 품을 게야. 항상 그랬던 것처럼 이 상황에 맞서야만 하네.', `MaleText_loc4`='伊利丹会起疑心，这是毫无疑问的。不过我们会挺过去的，一直以来不都是这样吗？', `MaleText_loc5`='伊利丹會起疑心...那是一定的。不過我們能應付過去，就跟往常一樣。', `MaleText_loc7`='Illidan sospechará... eso es seguro. Nos las arreglaremos, como siempre.' WHERE `ID`=20491;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진심은 아니겠지. 자네가 치른 희생은 이미 너무나도 크지 않은가.', `MaleText_loc4`='你……不要开玩笑，奥鲁姆。你已经做出了太多的牺牲。', `MaleText_loc5`='你不是...認真的，歐蘭。你的犧牲已經夠大了。', `MaleText_loc7`='No puedes hablar en serio, Olum. Tu sacrificio ya ha sido enorme.' WHERE `ID`=20492;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 결심을 되돌릴 순 없겠군. 우리가 성심을 다해 자네를 영혼의 세계로 인도하겠네.', `MaleText_loc4`='看来你已经做出了决定，那么好吧。我们会尽可能让你进入灵魂世界的过程没有痛苦。', `MaleText_loc5`='看來你心意已決。我們會盡力指引你進入靈魂的世界。', `MaleText_loc7`='Parece que ya has decidido. Te guiaremos al mundo de los espíritus con toda la bondad posible.' WHERE `ID`=20493;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 가게. 이 세상에서 할 일을 다하면 다음 세상에서 또 만나세.', `MaleText_loc4`='再会，我的朋友。当我们在这个世界的使命完结之后，就可以在另一个世界中再次相聚了。', `MaleText_loc5`='再會，我的朋友。完成了這個世界上的使命之後，我們就可以在另一個世界中再次相聚了。', `MaleText_loc7`='Adiós, amigo. Nos veremos en el otro mundo al acabar nuestros cometidos en este.' WHERE `ID`=20494;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님! 바쉬 님에게서 도망친 반역자를 찾았습니다! 여기 놈의 몸뚱아리를 보십시오!', `MaleText_loc4`='主人！我们抓住了从瓦丝琪那里逃跑的叛徒！他的尸体就躺在我的面前！', `MaleText_loc5`='主人!我們找到從瓦許那裡逃脫的背叛者了!他的屍體就躺在我面前...毫無生氣!', `MaleText_loc7`='¡Amo! ¡Encontramos al traidor que escapó de Vashj! ¡Su cuerpo yace ante mí... sin vida!' WHERE `ID`=20495;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님! 오해하시는 겁니다. 정보에 의하면 주인님을 배신하려는 자가 내부에 있습니다. 바로 그 오만한 캘타스 놈 말입니다! 놈은 킬제덴과 손을 잡고 아웃랜드의 권좌에서 주인님을 몰아내려고 합니다!', `MaleText_loc4`='但是，大人！您误解了我的行动……我确实知道有个您非常信任的人想要背叛您，他就是凯尔萨斯那条狗！他现在投靠了基尔加丹，想要取代您，统治外域！', `MaleText_loc5`='但是，陛下!您誤判了我的行為...我真的知道您身邊有某個人計畫背叛您。是那個走狗，凱爾薩斯!他和基爾加丹結盟想取代您成為外域之王!', `MaleText_loc7`='¡Pero, señor! Has malinterpretado mis actos... Sé de alguien cercano que planea traicionarte. ¡Ese perro de Kael''thas! ¡Se ha aliado con Kil''jaeden para reemplazarte como señor de Terrallende!' WHERE `ID`=20496;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분부대로 따르겠습니다!', `MaleText_loc4`='遵命，大人！', `MaleText_loc5`='我會全力以赴的，主人!', `MaleText_loc7`='¡Así se hará, mi señor!' WHERE `ID`=20497;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아카마! 보고는 받았나? 바쉬의 추종자들에게 발각당했어. 우리의 비밀이 드러날 위험에 처했네!', `MaleText_loc4`='阿卡玛！你听到消息了吗？我被瓦丝琪的人跟踪了。我们的秘密就要暴露了！', `MaleText_loc5`='阿卡瑪!你知道了嗎?我被瓦許的追隨者發現了。我們的秘密就要暴露了!', `MaleText_loc7`='¡Akama! ¿Lo sabes? Me descubrieron los seguidores de Vashj. ¡Nuestro secreto peligra!' WHERE `ID`=20498;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일리단은 날 찾아내서 잿빛혓바닥 결사단의 비밀을 모두 캐내겠지. 배신자의 능력이란 그런 거니까! 이제 한 가지 방법밖엔 없어. 이번 일에서 내 몫은 여기까지네. 난 영혼의 세계로 떠나야 해.', `MaleText_loc4`='伊利丹必定会抓住我，那时候，他肯定会得知灰舌部队的秘密。这对他来说根本没有什么难度！不，我们只有一个办法。是我的愚蠢和疏忽导致了今天的局面，那么就让我进入灵魂的世界，结束这次危机。', `MaleText_loc5`='伊利丹必定會抓住我，那時候，他肯定會得知灰舌部隊的秘密。這對他來說根本沒有什麼難度﹗不，我們只有一個辦法。是我的愚蠢和疏忽導致了今天的局面，那麼就讓我進入靈魂的世界，結束這次危機。', `MaleText_loc7`='Illidan me encontrará y entonces... Intentará quitarme el secreto Lengua de Ceniza: ¡tal es el poder del Traidor! No... solo hay una salida. Ya no soy útil a la causa... Tengo que ir al mundo de los espíritus.' WHERE `ID`=20499;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 이미 결심을 굳혔네. 이건 내 일생을 바친 계획이야. 그 목표를 위태롭게 하는 일은 우리 신념을 위해 목숨까지 바친 모든 이들을 배신하는 일일세.', `MaleText_loc4`='我已经下定了决心，不要再劝说我了。我把自己的生命都献给了我们的计划，如果现在前功尽弃，我们怎么能对得起那些为此牺牲的伙伴？', `MaleText_loc5`='我已經決定了，別再勸我了，我已決定把自己的生命獻給我們的計畫。再說，如果現在前功盡棄，我們怎麼能對得起那些已為此犧牲的夥伴?', `MaleText_loc7`='Mi decisión es definitiva, no me harás cambiar de opinión. He dedicado mi vida a nuestro plan. Ponerlo en peligro ahora seria una traición a todos los que han muerto por la causa antes que yo.' WHERE `ID`=20500;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙네, 아카마... 내 가는 길을 형제들에게 둘러싸여 맞이하게 되다니 영광이로군. 친구여, 안녕히... 우리 종족을 잘 부탁하네.', `MaleText_loc4`='谢谢你，阿卡玛。你让我感到了无上的荣耀，我感到自己的兄弟们就在身边。再会，朋友。好好指引我们的同胞。', `MaleText_loc5`='謝謝你，阿卡瑪。你讓我感到了無上榮耀，讓我感到兄弟們就在身邊。再會，朋友。好好指引我們的同胞。', `MaleText_loc7`='Gracias, Akama. Me honras con este momento rodeado de mis hermanos. Adiós, guía bien a nuestro pueblo.' WHERE `ID`=20501;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일리단이 날 쫓고 있어. 이곳은 안전하지 않아. 자네도 위험하네!', `MaleText_loc4`='伊利丹正在搜捕我。我在这里非常危险，我们大家都非常危险。', `MaleText_loc5`='伊利丹正在追捕我。我在這裡非常危險，我們大家都非常危險。', `MaleText_loc7`='Illidan me busca. No estoy seguro aquí... nadie lo está.' WHERE `ID`=20502;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$g오빠:언니;도 느껴져요?', `FemaleText_loc4`='你感觉到了吗？', `FemaleText_loc5`='你感覺到了嗎?', `FemaleText_loc7`='¿Lo sientes?' WHERE `ID`=20503;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어서 와요. 우리가 가서 확인해 보자고요!', `FemaleText_loc4`='过来，我们去看看！', `FemaleText_loc5`='來吧，一起去看看!', `FemaleText_loc7`='¡Venga, vamos a verlo!' WHERE `ID`=20504;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='바로 저 앞이에요!', `FemaleText_loc4`='就在前面！', `FemaleText_loc5`='就在前面!', `FemaleText_loc7`='¡Está justo ahí!' WHERE `ID`=20505;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우와, 저들이 나루의 마력을 빨아들이는 건가요? 왠지 좀 웃기네...', `FemaleText_loc4`='哦，哇噻，他们正在从那个纳鲁身上抽取能量吗？好有趣啊……', `FemaleText_loc5`='喔，哇，他們在引導的是一個那魯嗎?我覺得好有趣...', `FemaleText_loc7`='Oh, vaya, ¿es eso un naaru? Me siento rara...' WHERE `ID`=20506;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 매혹적인 도시를 다 둘러보셨다면 우리와 함께 축제를 즐겨보는 건 어때요? 지금 달숲에서는 달의 축제가 한창입니다. 어떤 대도시에서나 축제 장소로 순간이동시켜 드리고 있죠. 참, 달숲으로 가면 구경꾼들과 신나는 춤 한판 잊지 마세요.', `MaleText_loc4`='逛完了这座奇异的城市之后，也许你会有兴趣和我们一起来庆祝。春节庆典正在月光林地进行着，其它城市也都有前往庆典的传送点。过来和我们一起狂欢吧！', `MaleText_loc5`='等你拜訪完這個奇特的城市，或許你就會有興趣和我們一起慶祝。新年慶典在月光林地進行;其他城市有傳送點可前往慶祝。一起來加入其他的狂歡者吧!', `MaleText_loc7`='Cuando hayas acabado tu visita a esta exótica ciudad, quizá te interese celebrar con nosotros. El Festival Lunar está en marcha en Claro de la Luna. Hay transporte desde las otras ciudades a la fiesta. ¡Ven y únete a la celebración!', `FemaleText_loc1`='이 매혹적인 도시를 다 둘러보셨다면 우리와 함께 축제를 즐겨보는 건 어때요? 지금 달숲에서는 달의 축제가 한창입니다. 어떤 대도시에서나 축제 장소로 순간이동시켜 드리고 있죠. 참, 달숲으로 가면 구경꾼들과 신나는 춤 한판 잊지 마세요.', `FemaleText_loc4`='逛完了这座奇异的城市之后，也许你会有兴趣和我们一起来庆祝。春节庆典正在月光林地进行着，其它城市也都有前往庆典的传送点。过来和我们一起狂欢吧！', `FemaleText_loc5`='等你拜訪完這個奇特的城市，或許你就會有興趣和我們一起慶祝。新年慶典在月光林地進行;其他城市有傳送點可前往慶祝。一起來加入其他的狂歡者吧!', `FemaleText_loc7`='Cuando hayas acabado tu visita a esta exótica ciudad, quizá te interese celebrar con nosotros. El Festival Lunar está en marcha en Claro de la Luna. Hay transporte desde las otras ciudades a la fiesta. ¡Ven y únete a la celebración!' WHERE `ID`=20507;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='와, 정말 굉장한 광경이야!', `FemaleText_loc4`='哇喔，跑得真快！', `FemaleText_loc5`='哇，還真是匆忙!', `FemaleText_loc7`='¡Guao, qué carrera!' WHERE `ID`=20508;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='살란드리아가 넋 나간 표정으로 자신을 이끄는 강력한 힘 쪽으로 한 발짝씩 내딛습니다.', `FemaleText_loc4`='萨兰蒂亚似乎很迷惑，缓缓地走到了这个给她带来奇妙感觉的东西前。', `FemaleText_loc5`='瑟蘭德雅似乎處在恍惚的狀態下，朝著她感覺到的東西而前進。', `FemaleText_loc7`='Como apresurada, Salandria se mueve hacia lo que siente.' WHERE `ID`=20509;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='도르나가 거대한 어둠의 문에 놀라 입을 딱 벌리곤 멍하니 바라봅니다.', `FemaleText_loc4`='多尔南站在巨大的黑暗之门前，满怀敬畏地张大了嘴。', `FemaleText_loc5`='朵娜站在巨大的黑暗之門下並因敬畏而目瞪口呆。', `FemaleText_loc7`='Dornaa se levanta y se queda boquiabierta y sobrecogida ante el inmenso Portal Oscuro.' WHERE `ID`=20510;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$r|1이여;여;, 예서 무얼 하고 계십니까?', `MaleText_loc4`='你在这里干什么，$r？', `MaleText_loc5`='你在這幹嘛，$r?', `MaleText_loc7`='¿Qué haces aquí, $r?' WHERE `ID`=20511;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 무릎을 꿇고서 유리병 안을 달샘 물로 채웁니다.', `MaleText_loc4`='%s跪了下来，用月亮井的水装满了整个水瓶。', `MaleText_loc5`='%s跪著，將瓶子裝滿月井水。', `MaleText_loc7`='%s se arrodilla, llena el vial con agua de la Poza de la Luna' WHERE `ID`=20512;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물약이 완성되었습니다. 에메랄드의 꿈속에 머물고 있는 클린타르가 우리가 그의 안식을 방해하는 걸 용서하길 바랄 뿐입니다.', `MaleText_loc4`='药水已经完成了。我只希望克林塔尔能够原谅我们打断了他在翡翠梦境的逗留。', `MaleText_loc5`='藥水完成了。我只能希望克林塔能夠原諒我們打擾他在翡翠夢境的生活。', `MaleText_loc7`='La poción está lista. Ahora solo queda esperar que Clintar nos perdone por interrumpir su estancia en el Sueño Esmeralda.' WHERE `ID`=20513;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='살란드리아가 놀라서 턱이 빠질 정도로 입을 딱 벌리고 잘라도르무를 쳐다봅니다.', `FemaleText_loc4`='萨兰蒂亚在看到扎拉多姆时，下巴几乎都要碰到地上了。', `FemaleText_loc5`='瑟蘭德雅在看到薩拉多姆的影像時驚訝得合不攏嘴。', `FemaleText_loc7`='A Salandria se le quedan los ojos como platos al ver a Zaladormu.' WHERE `ID`=20514;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋아라, 내가 좋아하는... 엄마야, 저게 뭐야? 살려줘요!', `FemaleText_loc4`='哈哈，我喜欢！唔……发生了什么事？救救我！', `FemaleText_loc5`='沒錯，我喜歡!嗚...發生什麼事了?救救我!', `FemaleText_loc7`='¡Bien, yo! Eh... ¿qué ocurre? ¡Salvadme!' WHERE `ID`=20515;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 각성의 물약을 조제할 수 있는 이는 이 세계에 몇 안 남았습니다. 제가 그중 하나라는 사실을 감사하게 생각하셔야 할 겁니다.', `MaleText_loc4`='在这个世界上没有几个人有能力使用唤醒戒卫了，$n。我们很幸运，因为我就是其中之一。', `MaleText_loc5`='在這世界上只剩幾個人會製作清醒防護藥劑，$n。很幸運得是我就是其中一個。', `MaleText_loc7`='Quedan muy pocos en el mundo que puedan preparar el Resguardo de despertar, $n. Tenemos la fortuna de yo sea uno de ellos.' WHERE `ID`=20516;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 약초를 달샘 물과 혼합하여 각성의 물약을 만듭니다.', `MaleText_loc4`='%s把药草和月亮井水混合在一起以制造唤醒戒卫。', `MaleText_loc5`='%s混合了這些藥草及月井水製造出清醒防護藥劑。', `MaleText_loc7`='%s combina las hierbas con el agua de la Poza de la Luna para crear el Resguardo de despertar.' WHERE `ID`=20517;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아란을 꺾었다고요? 그래요, 녀석의 영향력이 약해진 것이 느껴지는군요. 아주 약간이지만 말입니다. 그래도, 문지기로서 제 본분을 다할 정도는 되는군요! $n, 수호자의 도서관으로 순간이동시켜 드릴까요?', `MaleText_loc4`='埃兰被打败了？啊……我能感觉到他的控制已经被解开了——虽然感觉很微弱。但是这足够让我继续履行看门人的工作了！你愿意被传送到守护者的图书馆吗，$n？', `MaleText_loc5`='埃蘭已經戰敗了嗎?太好了...我可以感覺到他的勢力已經縮減了 - 即使只有一點點。但是這樣就足夠我執行身為一個看門人該做的事情了!你想要傳送至守護者圖書館嗎，$n?', `MaleText_loc7`='¿Aran ha sido vencido? Sí... Siento que su puño se ha debilitado, aunque solo un poco. Lo suficiente para permitirme hacer mi trabajo como portero. ¿Quieres que te transporte hasta la Biblioteca del Guardián, $n?' WHERE `ID`=20518;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수호자의 도서관으로 보내 주십시오.', `MaleText_loc4`='请把我传送到守护者的图书馆去吧。', `MaleText_loc5`='請將我傳送至守護者圖書館。', `MaleText_loc7`='Por favor, llévame a la Biblioteca del Guardián.', `FemaleText_loc1`='수호자의 도서관으로 보내 주세요.', `FemaleText_loc4`='请把我传送到守护者的图书馆去吧。', `FemaleText_loc5`='請將我傳送至守護者圖書館。', `FemaleText_loc7`='Por favor, llévame a la Biblioteca del Guardián.' WHERE `ID`=20519;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠시 제 말을 들으십시오!', `MaleText_loc4`='等等！！', `MaleText_loc5`='等等!', `MaleText_loc7`='¡ESPERA!' WHERE `ID`=20520;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 아이는 아무 짓도 하지 않았고, 앞으로 그녀가 할 일들과 실패할 일들에 대해 어떠한 책임도 지우지 않을 것입니다.', `MaleText_loc4`='这个女孩什么都没有做，而且她不应该为她在将来可能做的、或者没能做到的任何事情负任何责任。', `MaleText_loc5`='這個女孩什麼都沒做，而且未來將不必承擔她可能做過的，或是失敗的責任。', `MaleText_loc7`='Esta niña no ha hecho nada, y no será responsable de lo que pueda hacer o dejar de hacer en el futuro.' WHERE `ID`=20521;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 가도 좋다, 아이야...', `MaleText_loc4`='没事了，孩子。', `MaleText_loc5`='平靜的去吧，孩子。', `MaleText_loc7`='Ve en paz.' WHERE `ID`=20522;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 무릎을 꿇더니 벌떡 일어납니다. 하지만, 자신이 어디 있는지 알아차리지 못하는 것 같습니다.', `MaleText_loc4`='%s突然跪下，但他的心思似乎游离在别处。', `MaleText_loc5`='%s迅速變成了跪姿，不過看起來好像他是在別的地方一樣。', `MaleText_loc7`='%s se pone de rodillas, pero parece estar en otro lado.' WHERE `ID`=20523;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자여, 이세라 님의 영역에서 뭘 하는 거지? 우리를 떠나게! 이곳은 그대 종족을 환영하지 않아!', `MaleText_loc4`='你在伊瑟拉的领域里干什么，入侵者？走开！你们在这里不受欢迎！', `MaleText_loc5`='你在伊瑟拉的領土之內做什麼，闖入者?你給我離開!這裡不歡迎你這種族類!', `MaleText_loc7`='¿Qué haces en el reino de Ysera, intruso? ¡Márchate! ¡Ya! ¡Los de tu especie no son bienvenidos aquí!' WHERE `ID`=20524;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 발꿈치를 딛고 서서 주위를 둘러봅니다.', `MaleText_loc4`='%s站稳了脚跟，开始辨识周围的环境。', `MaleText_loc5`='%s站了起來，開始辨認周遭的環境。', `MaleText_loc7`='%s se levanta y empieza a reconocer su entorno.' WHERE `ID`=20525;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 그의 주인과 정신의 결속을 이룹니다.', `MaleText_loc4`='%s和它的主人联系着，正试图建立灵魂的联接。', `MaleText_loc5`='%s與其主人連接，建立一道靈魂聯結。', `MaleText_loc7`='%s se une a su maestro, se crea un vínculo de espíritu.', `FemaleText_loc1`='%s|1이;가; 그의 주인과 정신의 결속을 이룹니다.', `FemaleText_loc4`='%s和它的主人联系着，正试图建立灵魂的联接。', `FemaleText_loc5`='%s與其主人連接，建立一道靈魂聯結。', `FemaleText_loc7`='%s se une a su maestro, se crea un vínculo de espíritu.' WHERE `ID`=20526;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘라도르무를 보더니 도르나가 입을 떡 벌리며 놀랍니다.', `FemaleText_loc4`='多尔南在看到扎拉多姆时，下巴几乎都要碰到地上了。', `FemaleText_loc5`='朵娜在看到薩拉多姆的影像時驚訝得合不攏嘴。', `FemaleText_loc7`='A Dornaa se le quedan los ojos como platos al ver a Zaladormu.' WHERE `ID`=20527;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='와, 저분은 매우 크시네요! 음... 무슨 일이죠? 앗, 절 구해주세요!', `FemaleText_loc4`='哇，他真是个大家伙啊！嗯……怎么回事？救救我！', `FemaleText_loc5`='哇喔，他長得真大!嗚...發生什麼事?救我!', `FemaleText_loc7`='¡Guao, menudo ejemplar! Eh... ¿qué pasa? ¡Salvadme!' WHERE `ID`=20528;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$C $n|1이여;여;, 다시 만나서 반갑군. 도르나가 자네가 잘 있는지 알고 싶다면서 $g오빠:언니;를 찾아달라고 어찌나 보채던지...', `FemaleText_loc4`='很高兴再次见到你，$c$n。多尔南一直在问起你。', `FemaleText_loc5`='很高興又見到你了，$C$n。朵娜一直探問你的消息。', `FemaleText_loc7`='Me alegro de verte de nuevo, $c $n. Dornaa ha estado preguntado por ti.' WHERE `ID`=20529;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$C $n|1이여;여;, 다시 만나서 반갑군. 살란드리아가 자네가 잘 있는지 알고 싶다면서 $g오빠:언니;를 찾아달라고 어찌나 보채던지...', `FemaleText_loc4`='很高兴再次见到你，$c$n。萨兰蒂亚一直在问起你。', `FemaleText_loc5`='很高興又見到你了，$C$n。瑟蘭德雅一直都在探問你的消息。', `FemaleText_loc7`='Me alegro de verte de nuevo, $c $n. Salandria ha estado preguntado por ti.' WHERE `ID`=20530;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아웃랜드의 분쟁은 그 어떤 곳보다 더 심각한 파국으로 치닫고 있네. 그 싸움의 가장 불쌍한 희생양은 바로 부모를 잃고 홀로 남은 아이들이지.$B$B스케티스의 아라코아들이 샤트라스를 크게 위협하고 있는 지금, 그 어느 때보다 도움의 손길이 필요한 고아들이 많다네. 밝은 미래에 대한 어떠한 희망도 없이 살아가는 아이들이지.', `FemaleText_loc4`='外域的战争比起我所经历过的任何战争都惨烈。大部分悲惨的受害人都是那些留在后方的孩子。$B$B现在，斯克提斯的鸦人对沙塔斯城的威胁进一步加剧，那里也会有更多的孤儿需要照顾。这些孩子看不到光明的未来。$B$B但是你却有能力为他们做些什么。儿童周来了，$c，我恳求你给这些孩子的生活带来些乐趣和奇迹吧。', `FemaleText_loc5`='外域的衝突比我看過的所有都還要致命。而最不幸的犧牲就是那些被遺留下來的孩童。$B$B現在，隨著來自司凱堤斯的阿拉卡這股反抗撒塔斯的威脅，將會有更多的孤兒需要照顧。這些孩童通常都活在沒有一個光明未來的絕望之中。', `FemaleText_loc7`='Los conflictos en Terrallende son los más cruentos que nunca haya visto. Y las víctimas más trágicas son los niños que quedan atrás.$B$BAhora, con la amenaza contra Shattrath de los arakkoa de Skettis, surgirán aún más huérfanos a los que cuidar. Estos niños a menudo viven sin la esperanza de un futuro.' WHERE `ID`=20531;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$r|1이여;여;, 놈들이 날 쫓고 있어! 놈들에게 발각되기 전에 이곳에 왜 왔는지부터 말하게! 놈들이 날 잡으면, 나와 그대는 끝장이란 말이야!', `MaleText_loc4`='他们还在追我，$r！快点，在我们被发现前告诉我，你来这里干什么！要是被他们抓住了，我们两个人都得死！', `MaleText_loc5`='他們在追我，$r!快點，在我們被發現前告訴我為什麼你會來這裡!要是讓他們抓到我，就代表你跟我都會死!', `MaleText_loc7`='¡Me persiguen, $r! ¡Rápido, dime qué haces aquí antes de que nos encuentren! ¡Si me alcanzan, me darán muerte y a ti también!' WHERE `ID`=20532;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s에게 졸음이 몰려옵니다.', `MaleText_loc4`='%s渐渐变得昏昏欲睡。', `MaleText_loc5`='%s變得昏昏欲睡。', `MaleText_loc7`='A %s le entra sueño.' WHERE `ID`=20533;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 다시 돌아가야 해... 아무리 놈들이라도 에메랄드의 꿈속에서는... 날 찾진 못할 테니까...', `MaleText_loc4`='我必须回去休息了……他们肯定不会在这里找到我的……翡翠梦境……', `MaleText_loc5`='我必須休息...他們一定沒辦法找到我在這...翡翠夢境...', `MaleText_loc7`='Debo volver a mi descanso... no deben hallarme aquí... el Sueño Esmeralda...' WHERE `ID`=20534;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<이 드루이드는 주위는 안중에도 없는 듯이 깊은 잠에 빠진 것 같습니다.>', `MaleText_loc4`='<这位德鲁伊似乎陷入了沉睡，全然忘却了他周围的环境。>', `MaleText_loc5`='<這個德魯伊好像深深沉睡了，對周遭全無反應。>', `MaleText_loc7`='<El druida parece estar en un sueño profundo, totalmente ajeno a lo que le rodea.>' WHERE `ID`=20535;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='클린타르를 깨웁니다.', `MaleText_loc4`='试着叫醒克林塔尔。', `MaleText_loc5`='試著叫醒克林塔。', `MaleText_loc7`='Intenta despertar a Clintar.', `FemaleText_loc1`='클린타르를 깨웁니다.', `FemaleText_loc4`='试着叫醒克林塔尔。', `FemaleText_loc5`='試著叫醒克林塔。', `FemaleText_loc7`='Intenta despertar a Clintar.' WHERE `ID`=20536;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$r|1이여;여;, 제발 서두르게나. 저들은 날 뒤쫓는 걸 멈추지 않을 것일세! 난 저들을 벗어날 수가 없어... 이곳에서조차 말이네!', `MaleText_loc4`='我求你了，$r，快一点。他们是不会放弃追踪的！就算是在这里，我也无法从他们手中逃脱！', `MaleText_loc5`='我打賭你會是最快的，$r。他們將不會放棄追蹤我!我無法躲過他們的追捕，即使是在這也一樣!', `MaleText_loc7`='Te lo ruego, $r, date prisa. ¡No dejarán de perseguirme! ¡No podré escapar de ellos! ¡Ni siquiera aquí!' WHERE `ID`=20537;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대는... 저들과 한패가 아니로군! 놈들이 우릴 발각하기 전에 어서 벗어나자고! 서두르게!', `MaleText_loc4`='你……你不是他们的同党！快，在他们找到我们之前，得躲进某个隐密的地方！快点！', `MaleText_loc5`='你 - 你不是他們的人!我們得在被他們找到之前逃走!快點!', `MaleText_loc7`='Tú, ¡tú no eres de los suyos! ¡Larguémonos de aquí antes de que nos encuentren! ¡Rápido!' WHERE `ID`=20538;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물러서시오, $n. 이 안에 아마 에테리움이 만들어 놓은 함정이 있을 것이오.', `MaleText_loc4`='退后点，$n。这可能是一个复仇军的陷阱。', `MaleText_loc5`='退後，$n。這有可能是一個以太皇族陷阱。', `MaleText_loc7`='Retrocede, $n. Puede ser una trampa de El Etereum.' WHERE `ID`=20539;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 인양된 에테리움 감옥에 에테리움 감옥 열쇠를 사용합니다.', `MaleText_loc4`='%s在复仇军牢房上使用复仇军监牢钥匙。', `MaleText_loc5`='%s對被搶救的以太皇族監獄使用以太皇族監獄鑰匙。', `MaleText_loc7`='%s usa la llave de prisión de El Etereum en la prisión de El Etereum rescatada.' WHERE `ID`=20540;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드 웰러의 무기고에 있는 인간 무기 전문가 우 핑과 엑소다르의 교역 지구에 있는 드레나이 무기 전문가 한디르나 아이언포지의 잘나가는 무기 상점에 있는 노움 무기 전문가인 빅시 워블봉크에게서 석궁 사용법에 대해서 배울 수 있답니다.', `MaleText_loc4`='你可以从暴风城维勒武器店的人类武器大师吴平、埃索达贸易阶梯的德莱尼武器大师韩迪尔或是铁炉堡密林武器店内的侏儒武器大师比克斯那里学会使用弩。', `MaleText_loc5`='想要學習弩可以去找暴風城內維勒武器店的人類武器大師吳平、艾克索達內貿易區的德萊尼武器大師哈戴爾或者是鐵爐堡內密林武器店的地精武器大師比克斯。', `MaleText_loc7`='El arte de las ballestas te lo puede enseñar Woo Ping, el maestro de armas humano del Arsenal de Weller en Ventormenta; Handiir, el maestro de armas draenei de la Grada de los Mercaderes dentro de El Exodar; o Bixi Tambaleapié, el maestro de armas gnomo que está dentro de Armas Mil Maderas en Forjaz.', `FemaleText_loc1`='스톰윈드 웰러의 무기고에 있는 인간 무기 전문가 우 핑과 엑소다르의 교역 지구에 있는 드레나이 무기 전문가 한디르나 아이언포지의 잘나가는 무기 상점에 있는 노움 무기 전문가인 빅시 워블봉크에게서 석궁 사용법에 대해서 배울 수 있답니다.', `FemaleText_loc4`='你可以从暴风城维勒武器店的人类武器大师吴平、埃索达贸易阶梯的德莱尼武器大师韩迪尔或是铁炉堡密林武器店内的侏儒武器大师比克斯那里学会使用弩。', `FemaleText_loc5`='想要學習弩可以去找暴風城內維勒武器店的人類武器大師吳平、艾克索達內貿易區的德萊尼武器大師哈戴爾或者是鐵爐堡內密林武器店的地精武器大師比克斯。', `FemaleText_loc7`='El arte de las ballestas te lo puede enseñar Woo Ping, el maestro de armas humano del Arsenal de Weller en Ventormenta; Handiir, el maestro de armas draenei de la Grada de los Mercaderes dentro de El Exodar; o Bixi Tambaleapié, el maestro de armas gnomo que está dentro de Armas Mil Maderas en Forjaz.' WHERE `ID`=20541;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사령관님... 전 이 세상에서 더는 삶을 이어갈 수 없습니다... 우리가 투옥된... 다른 세계에서 온... 수백만... 수천만의 생물들이... 에테리움 때문에 수감되어 있습니다... 그들 중의 다수가 우리의 동맹입니다. 기필코... 기필코 다른 이들을 살려내야 합니다... 지금이라도... 그리 늦지 않았습니다...', `MaleText_loc4`='指挥官……我在这个世界中的时间不多了……监狱……成百……上千……从其它世界来的生物……被……被复仇军关押在那里。他们大部分是我们的朋友。必须……必须拯救他们……现在……现在还来得及……', `MaleText_loc5`='指揮官...我再活也不久了...前往一處監獄...成百...成千...從另一個世界來的生物...被監禁...被以太皇族監禁著。他們之中有很多我們的盟友。務必...務必要救出其他人...現在...現在還為時不晚...', `MaleText_loc7`='Comandante... ya no estoy en este mundo... Cercados sin salida... cientos... miles... seres de otros mundos... Encarcelados… Encarcelados por El Etereum. Muchos son nuestros aliados. Debe... Debe salvar al resto... Aún... Aún hay tiempo...' WHERE `ID`=20542;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아저씬 제 꿈에 나타난 그분이군요!', `FemaleText_loc4`='你就是那个在我梦里出现过的人。', `FemaleText_loc5`='你就是我夢中的人!', `FemaleText_loc7`='¡Eres el hombre de mi sueño!' WHERE `ID`=20543;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저런 멍청한 녀석들! 도대체 무슨 짓을 한 거지! 저들이 어떤 소름끼치는 것들을 가두고 있는 것이지? 무슨 짓을 꾸미는 거란 말이냐! 영웅이여, 다시금 당신의 도움이 필요하오. 우리와 우리의 친구들을 도와주시오.', `MaleText_loc4`='那些笨蛋！他们都干了些什么！他们都监禁了一些什么恐怖的东西？又是什么目的？我仍然需要你的帮助，英雄。帮助我们。帮助你的人民。', `MaleText_loc5`='那些笨蛋!他們做了什麼!他們握有什麼恐怖的東西?為了什麼目的?我再度需要你的協助，英雄。幫助我。幫助你的人民。', `MaleText_loc7`='¡Esos necios! ¿Pero qué han hecho? ¿Qué horrores ocultan? ¿Y cuál es su propósito? Necesitaré tu ayuda de nuevo, héroe. Ayúdanos. Ayuda a tu gente.' WHERE `ID`=20544;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇단다, 아이야. 그 꿈에서 네가 나에게 뭘 보여줬는지 기억하느냐?', `MaleText_loc4`='是的，我就是，孩子。还有你记得你在梦里展示给我的一切吗？', `MaleText_loc5`='我就是，孩子。你還記得在那些夢境中你給我看了什麼嗎?', `MaleText_loc7`='Sí que se trata de mí, peque. ¿Y recuerdas lo que me mostraste en esos sueños?' WHERE `ID`=20545;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다르나서스의 전사의 정원에 있는 나이트 엘프 무기 전문가인 일예니아 문파이어가 활의 사용법에 대해서 가르쳐 줄 겁니다.', `MaleText_loc4`='居住在达纳苏斯战士区的暗夜精灵武器大师伊琳尼雅·月火可以教你使用弓。', `MaleText_loc5`='伊琳尼雅·月火，住在達納蘇斯戰士區的夜精靈武器大師，能夠教導你使用弓的方式。', `MaleText_loc7`='Ilyenia Fuegolunar, elfa de la noche maestra de armas que reside en el Bancal del Guerrero en Darnassus podrá entrenarte en el uso de los arcos.', `FemaleText_loc1`='다르나서스의 전사의 정원에 있는 나이트 엘프 무기 전문가인 일예니아 문파이어가 활의 사용법에 대해서 가르쳐 줄 겁니다.', `FemaleText_loc4`='居住在达纳苏斯战士区的暗夜精灵武器大师伊琳尼雅·月火可以教你使用弓。', `FemaleText_loc5`='伊琳尼雅·月火，住在達納蘇斯戰士區的夜精靈武器大師，能夠教導你使用弓的方式。', `FemaleText_loc7`='Ilyenia Fuegolunar, elfa de la noche maestra de armas que reside en el Bancal del Guerrero en Darnassus podrá entrenarte en el uso de los arcos.' WHERE `ID`=20546;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 아저씨 말씀은... 꿈에서 했던 걸 여기서도 할 수 있느냐는 거세요?', `FemaleText_loc4`='你的意思是，我也能在这里做吗？', `FemaleText_loc5`='你是說，我也可以在這進行嗎?', `FemaleText_loc7`='¿Quieres decir que puedo hacerlo aquí también?' WHERE `ID`=20547;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇단다, 해 보아라.', `MaleText_loc4`='试试。', `MaleText_loc5`='試看看。', `MaleText_loc7`='Prueba.' WHERE `ID`=20548;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대단하구나, 도르나야. 정말로 대단해!', `MaleText_loc4`='太令人吃惊了，多尔南。真的太令人吃惊了！', `MaleText_loc5`='太神奇了，朵娜。真的是太神奇了!', `MaleText_loc7`='Sorprendente, Dornaa. ¡Verdaderamente sorprendente!' WHERE `ID`=20549;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='와, 제가 해냈어요! 해냈다고요!!!', `FemaleText_loc4`='我成功了，我成功了！！！', `FemaleText_loc5`='我做到了，我做到了!!!', `FemaleText_loc7`='¡¡¡Lo logré, lo logré!!!' WHERE `ID`=20550;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 멋진 상점에 있는 빅시 워블봉크가 당신에게 단검 사용법에 대해서 알려줄 것이오. 아직도 다른 무기 전문가를 찾고 있다면 다르나서스에 있는 일예니아 문파이어나 엑소다르에 있는 한디르, 스톰윈드에 있는 우 핑이 몇 가지 무기 사용법에 대해서 알려 줄 겁니다. 난 단검 사용법에 대해서는 모릅니다.', `MaleText_loc4`='这家店里的比克斯可以教你使用匕首。如果你还想认识其他人的话，暴风城的吴平、埃索达的韩迪尔和达纳苏斯的伊琳尼雅·月火也都能教你。至于我，我一直不喜欢用匕首战斗。', `MaleText_loc5`='這間特別商店裡的比克斯能夠教導你使用匕首。如果你還想再往外找的話，其他還有 - 暴風城的吳平，艾克索達的哈戴爾，達納蘇斯的伊琳尼雅·月火 - 都能告訴你一兩件事。我，我從來都不是使用刀劍戰鬥的人。', `MaleText_loc7`='Bixi Tambaleapié podrá entrenarte con las dagas en esta misma tienda. Y, si aun así quieres buscar más lejos, Woo Ping en Ventormenta, Handiir en El Exodar o Ilyenia Fuegolunar de Darnassus podrán enseñarte un par de cosas también. A mí personalmente, nunca me ha gustado su estilo.', `FemaleText_loc1`='이 멋진 상점에 있는 빅시 워블봉크가 당신에게 단검 사용법에 대해서 알려줄 것이오. 아직도 다른 무기 전문가를 찾고 있다면 다르나서스에 있는 일예니아 문파이어나 엑소다르에 있는 한디르, 스톰윈드에 있는 우 핑이 몇 가지 무기 사용법에 대해서 알려 줄 겁니다. 난 단검 사용법에 대해서는 모릅니다.', `FemaleText_loc4`='这家店里的比克斯可以教你使用匕首。如果你还想认识其他人的话，暴风城的吴平、埃索达的韩迪尔和达纳苏斯的伊琳尼雅·月火也都能教你。至于我，我一直不喜欢用匕首战斗。', `FemaleText_loc5`='這間特別商店裡的比克斯能夠教導你使用匕首。如果你還想再往外找的話，其他還有 - 暴風城的吳平，艾克索達的哈戴爾，達納蘇斯的伊琳尼雅·月火 - 都能告訴你一兩件事。我，我從來都不是使用刀劍戰鬥的人。', `FemaleText_loc7`='Bixi Tambaleapié podrá entrenarte con las dagas en esta misma tienda. Y, si aun así quieres buscar más lejos, Woo Ping en Ventormenta, Handiir en El Exodar o Ilyenia Fuegolunar de Darnassus podrán enseñarte un par de cosas también. A mí personalmente, nunca me ha gustado su estilo.' WHERE `ID`=20551;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다르나서스의 전사의 정원에 있는 나이트 엘프 무기 전문가인 일예니아 문파이어나 아이언포지의 잘나가는 무기 상점에 있는 드워프 무기 전문가 불리위프가 장착 무기의 사용법에 대해서 가르쳐 줄 겁니다.', `MaleText_loc4`='达纳苏斯战士区的武器大师伊琳尼雅·月火，或是铁炉堡密林武器店的矮人武器大师布里维夫，都能教你如何使用拳套。', `MaleText_loc5`='伊琳尼雅·月火，達納蘇斯戰士區的夜精靈武器大師，或是布里維夫，鐵爐堡內密林武器店的矮人武器大師，都能夠教導你使用拳類武器的方式。', `MaleText_loc7`='Ilyenia Fuegolunar, elfa de la noche maestra de armas del Bancal del Guerrero en Darnassus, o Buliwyf, el enano maestro de armas de Armas Mil Maderas en Forjaz podrán entrenarte en el uso de las armas de puño.', `FemaleText_loc1`='다르나서스의 전사의 정원에 있는 나이트 엘프 무기 전문가인 일예니아 문파이어나 아이언포지의 잘나가는 무기 상점에 있는 드워프 무기 전문가 불리위프가 장착 무기의 사용법에 대해서 가르쳐 줄 겁니다.', `FemaleText_loc4`='达纳苏斯战士区的武器大师伊琳尼雅·月火，或是铁炉堡密林武器店的矮人武器大师布里维夫，都能教你如何使用拳套。', `FemaleText_loc5`='伊琳尼雅·月火，達納蘇斯戰士區的夜精靈武器大師，或是布里維夫，鐵爐堡內密林武器店的矮人武器大師，都能夠教導你使用拳類武器的方式。', `FemaleText_loc7`='Ilyenia Fuegolunar, elfa de la noche maestra de armas del Bancal del Guerrero en Darnassus, o Buliwyf, el enano maestro de armas de Armas Mil Maderas en Forjaz podrán entrenarte en el uso de las armas de puño.' WHERE `ID`=20552;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잠시 정신 집중하고는 도르나가 네 마리의 정령 군사를 소환합니다.', `FemaleText_loc4`='全神贯注片刻之后，多尔南召唤出了元素之力。', `FemaleText_loc5`='專注一會兒後，朵娜召喚出元素界的力量。', `FemaleText_loc7`='Dornaa se concentra durante un momento e invoca las fuerzas elementales.' WHERE `ID`=20553;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사격법에 대해서 얘기해야 할 자는 아이언포지 내에 잘나가는 무기 상점에서 만날 수 있는 불리위프랍니다.', `MaleText_loc4`='能教你使用枪的是布里维夫，去铁炉堡的密林武器店找他吧。', `MaleText_loc5`='有關射擊方面可以找布里維夫談談，你可以在鐵爐堡內的密林武器店找到他。', `MaleText_loc7`='Si quieres hablar de armas de fuego, debes dirigirte a Buliwyf. Lo encontrarás en Armas Mil Maderas en Forjaz.', `FemaleText_loc1`='사격법에 대해서 얘기해야 할 자는 아이언포지 내에 잘나가는 무기 상점에서 만날 수 있는 불리위프랍니다.', `FemaleText_loc4`='能教你使用枪的是布里维夫，去铁炉堡的密林武器店找他吧。', `FemaleText_loc5`='有關射擊方面可以找布里維夫談談，你可以在鐵爐堡內的密林武器店找到他。', `FemaleText_loc7`='Si quieres hablar de armas de fuego, debes dirigirte a Buliwyf. Lo encontrarás en Armas Mil Maderas en Forjaz.' WHERE `ID`=20554;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 있는 이 친구 불리위프가 총에 대한 모든 것을 기쁘게 당신에게 가르쳐 줄 겁니다!', `MaleText_loc4`='布里维夫会很高兴把他所知道的一切关于枪的知识都教给你的！', `MaleText_loc5`='布里維夫會很樂意教導你所有與槍械相關的知識!', `MaleText_loc7`='¡Aquí Buliwyf te enseñará con gusto todo lo que hay que saber sobre armas de fuego!', `FemaleText_loc1`='여기 있는 이 친구 불리위프가 총에 대한 모든 것을 기쁘게 당신에게 가르쳐 줄 겁니다!', `FemaleText_loc4`='布里维夫会很高兴把他所知道的一切关于枪的知识都教给你的！', `FemaleText_loc5`='布里維夫會很樂意教導你所有與槍械相關的知識!', `FemaleText_loc7`='¡Aquí Buliwyf te enseñará con gusto todo lo que hay que saber sobre armas de fuego!' WHERE `ID`=20555;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 연합왕자 하라매드 님의 명으로 이곳에 왔소이다. 이상한 일들이 폭풍 첨탑에서 벌어지고 있소.', `MaleText_loc4`='我是按照节点亲王哈拉迈德的吩咐来这里的。奇怪的事情似乎正在风暴尖塔中酝酿着。', `MaleText_loc5`='我是奉奈薩斯王子哈拉瑪德的命令來到這裡。有奇怪的東西正在風暴之尖活動著。', `MaleText_loc7`='Estoy a quí a instancias del príncipe-nexo Haramad. Están ocurriendo cosas extrañas en La Flecha de la Tormenta.' WHERE `ID`=20556;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$g오빠:언니;가 너무 보고 싶을 거예요! 다시 절 보러 오신다고 약속해 주실 거죠?', `FemaleText_loc4`='我会想你的，$n！答应我你会经常回来看我。', `FemaleText_loc5`='我會很想你，$n!記得要來看我喔。', `FemaleText_loc7`='¡Voy a echarte tanto de menos, $n! Prométeme que vendrás a visitarme.' WHERE `ID`=20557;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='게임을 다시 하고 싶다면, 체스판을 원래대로 배치하도록 하라.', `MaleText_loc4`='请重置棋盘，我们想再玩一次。', `MaleText_loc5`='請重置西洋棋盤，我們想要再玩一場。', `MaleText_loc7`='Reinicia el tablero, queremos jugar de nuevo.', `FemaleText_loc1`='게임을 다시 하고 싶다면, 체스판을 원래대로 배치하도록 하라.', `FemaleText_loc4`='请重置棋盘，我们想再玩一次。', `FemaleText_loc5`='請重置西洋棋盤，我們想要再玩一場。', `FemaleText_loc7`='Reinicia el tablero, queremos jugar de nuevo.' WHERE `ID`=20558;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수수께끼의 존재가 에메랄드의 꿈을 침입했네. 놈의 사악한 힘이 우리 세계까지 흘러 넘치려고 해! $n, 우리가 막아야 하네! 그래서 내가 직접 그대와 동행할 수 없는 거야.', `MaleText_loc4`='一个阴暗而险恶的幽魂正在侵袭翡翠梦境。它的力量正迅速向我们的世界中蔓延，$n。我们必须对抗它，这也是我不能亲自陪伴你们作战的原因。', `MaleText_loc5`='一個陰暗，不祥的鬼魂侵入了翡翠夢境。它的力量準備要漫延我們的世界，$n。我們必須抵擋住它!那就是我為何無法親自陪同你的原因。', `MaleText_loc7`='Una presencia oscura y siniestra ha invadido el Sueño Esmeralda. Su poder está listo para entrar en nuestro mundo, $n. ¡Debemos resistirnos! Por eso no puedo acompañarte en persona.' WHERE `ID`=20559;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='유물이 있는 장소로 안내해 주겠어. 그대는 나를 잘 보호해 주게나. 오직 유물의 수호자인 나의 영혼만이 봉인을 풀 수 있다네.', `MaleText_loc4`='我会带领你去圣物的位置，但你必须保护好我的灵魂。只有身为圣物守护者的我，才能破除净化之匣的封印。', `MaleText_loc5`='我將會引領你前往聖物的所在地，不過你必須好好保護我的靈魂。作為聖物的引導者，只有我能夠破壞聖物箱的封印。', `MaleText_loc7`='Te llevaré hasta el lugar donde se encuentran las reliquias, pero tú debes guardar mi espíritu. Como guardián de las reliquias, solo yo puedo romper los sellos de los relicarios.' WHERE `ID`=20560;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$g오빠:언니;, 정말 보고 싶을 거예요! 날 보러 꼭 다시 온다고 약속해요!', `FemaleText_loc4`='我会想你的，$n！答应我你会经常回来看我。', `FemaleText_loc5`='我會很想你，$n!記得要來看我喔。', `FemaleText_loc7`='¡Voy a echarte tanto de menos, $n! Prométeme que vendrás a visitarme.' WHERE `ID`=20561;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에메랄드의 꿈속을 벗어난 %s|1이;가; 현실 세계로 나왔습니다.', `MaleText_loc4`='一个%s从翡翠梦境中侵入了现实世界！', `MaleText_loc5`='一隻%s從翡翠夢境繃出來到這個清醒的世界。', `MaleText_loc7`='¡%s aparece en el mundo de los despiertos desde el Sueño Esmeralda!' WHERE `ID`=20562;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='첫 번째 유물이로군. 두 개 더 남았네. $n, 어서 따라오게.', `MaleText_loc4`='这是第一件圣物，不过还有两个。跟着我，$n。', `MaleText_loc5`='那就是第一個聖器，不過那裡還有第二個。跟著我，$n。', `MaleText_loc7`='La primera reliquia ya está, pero aún hay dos más. Sígueme, $n.' WHERE `ID`=20563;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두 번째 유물을 회수했군. 잠시 쉬었다가 마지막 유물이 있는 곳으로 가세나.', `MaleText_loc4`='我已经拿到了第二件圣物。休息一会，然后我们继续去最后一个净化之匣那里。', `MaleText_loc5`='我發現了第二個聖器。休息一下，接著我們就能繼續找到最後的聖物箱。', `MaleText_loc7`='He recuperado la segunda requilia. Descansa un momento y después seguiremos con el último relicario.' WHERE `ID`=20564;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청한 드루이드 녀석! 스스로 영혼과 육신을 분열한 것은 제 무덤 파기였다. 봐라, 더 약해지지 않았느냐?! 에메랄드의 꿈을 지배하실 우리 주인님께 문을 열어드리고 있구나. 네 영혼과 육신 모두 이곳에서 끝장나리라!', `MaleText_loc4`='愚蠢的德鲁伊！精神与肉体的分离使你变得虚弱不堪，我的主人即将支配整个翡翠梦境，你的灵魂和你的身体将会在这里湮灭！', `MaleText_loc5`='笨蛋德魯伊!分裂你的靈魂導致你清醒過來，為我的主人開啟了統治翡翠夢境的大門。你的靈魂及你的軀殼都將葬身此地!', `MaleText_loc7`='¡Druida necio! Al dividir tu esencia te has debilitado y has abierto la puerta para que mi maestro domine el Sueño Esmeralda. ¡Tu espíritu y tu cuerpo morirán aquí!' WHERE `ID`=20565;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 아비아나의 유물을 꿈지기 루로사에게 건넵니다.', `MaleText_loc4`='%s把艾维娜圣物交给了梦境卫士鲁罗萨。', `MaleText_loc5`='%s將艾維娜的聖物交給夢境看守者盧羅莎。', `MaleText_loc7`='%s entrega las Reliquias de Aviana al celador de sueños Lurosa.' WHERE `ID`=20566;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 사라져라!', `MaleText_loc4`='滚出这里！', `MaleText_loc5`='離開此地!', `MaleText_loc7`='¡Fuera de aquí!' WHERE `ID`=20567;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절대로 에메랄드의 꿈을 네놈들 손에 넣을 수는 없다!', `MaleText_loc4`='翡翠梦境永远都不会属于你！', `MaleText_loc5`='翡翠夢境永遠都不會是你的!', `MaleText_loc7`='¡El Sueño Esmeralda jamás será tuyo!' WHERE `ID`=20568;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드워프 무기 전문가인 불리위프가 한손 도끼와 양손 도끼 사용법 모두를 가르쳐 줄 겁니다. 그 친구는 아이언포지에 있는 잘나가는 무기 상점에서 찾을 수 있답니다.', `MaleText_loc4`='矮人武器大师布里维夫能教你怎么使用单手斧和双手斧。你可以在铁炉堡的密林武器店找到他。', `MaleText_loc5`='矮人武器大師布里維夫可以訓練你單手及雙手斧兩種武器。你可以在鐵爐堡的密林武器店找到他。', `MaleText_loc7`='El maestro de armas enano Buliwyf te puede entrenar tanto con hachas de una mano como de dos manos. Lo encontrarás en Armas Mil Maderas en Forjaz.', `FemaleText_loc1`='드워프 무기 전문가인 불리위프가 한손 도끼와 양손 도끼 사용법 모두를 가르쳐 줄 겁니다. 그 친구는 아이언포지에 있는 잘나가는 무기 상점에서 찾을 수 있답니다.', `FemaleText_loc4`='矮人武器大师布里维夫能教你怎么使用单手斧和双手斧。你可以在铁炉堡的密林武器店找到他。', `FemaleText_loc5`='矮人武器大師布里維夫可以訓練你單手及雙手斧兩種武器。你可以在鐵爐堡的密林武器店找到他。', `FemaleText_loc7`='El maestro de armas enano Buliwyf te puede entrenar tanto con hachas de una mano como de dos manos. Lo encontrarás en Armas Mil Maderas en Forjaz.' WHERE `ID`=20569;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 있는 불리위프보다 도끼에 대해 아는 훌륭한 전문가는 없습니다! 한손은 물론이고 양손 도끼 모두에 대해서 그는 달인이랍니다!', `MaleText_loc4`='据我所知没有比这里的布里维夫更出色的斧子专家了！单手斧，双手斧……他都是大师。', `MaleText_loc5`='我再也沒有認識比這裡的布里維夫更好的製斧專家了!單手，雙手...他都專精!', `MaleText_loc7`='No conozco mejor experto en hachas que Buliwyf. Una mano, dos... ¡lo domina todo!', `FemaleText_loc1`='여기 있는 불리위프보다 도끼에 대해 아는 훌륭한 전문가는 없습니다! 한손은 물론이고 양손 도끼 모두에 대해서 그는 달인이랍니다!', `FemaleText_loc4`='据我所知没有比这里的布里维夫更出色的斧子专家了！单手斧，双手斧……他都是大师。', `FemaleText_loc5`='我再也沒有認識比這裡的布里維夫更好的製斧專家了!單手，雙手...他都專精!', `FemaleText_loc7`='No conozco mejor experto en hachas que Buliwyf. Una mano, dos... ¡lo domina todo!' WHERE `ID`=20570;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 내 친구인 불리위프가 장착 무기 사용법에 대해서 알려줄 것입니다. 혹은 원하신다면 다르나서스 전사의 정원에 있는 나이트 엘프 무기 전문가인 일예니아 문파이어에게서도 배울 수 있을 겁니다!', `MaleText_loc4`='我的朋友布里维夫能指示你怎么使用拳套……或者，如果你喜欢女性教师的话，达纳苏斯战士区的暗夜精灵武器大师伊琳尼雅·月火同样能教会你！', `MaleText_loc5`='我在這裡的夥伴布里維夫可以告訴你如何使用拳套武器...或者，如果你比較喜歡，伊琳尼雅·月火 - 位於達納蘇斯戰士區的夜精靈武器大師 - 也可以告訴你!', `MaleText_loc7`='Mi colega Buliwyf aquí te puede enseñar a usar las armas de puño... o, si prefieres, Ilyenia Fuegolunar, la elfa de la noche maestra de armas que está en el Bancal del Guerrero en Darnassus podrá enseñarte también.', `FemaleText_loc1`='여기 내 친구인 불리위프가 장착 무기 사용법에 대해서 알려줄 것입니다. 혹은 원하신다면 다르나서스 전사의 정원에 있는 나이트 엘프 무기 전문가인 일예니아 문파이어에게서도 배울 수 있을 겁니다!', `FemaleText_loc4`='我的朋友布里维夫能指示你怎么使用拳套……或者，如果你喜欢女性教师的话，达纳苏斯战士区的暗夜精灵武器大师伊琳尼雅·月火同样能教会你！', `FemaleText_loc5`='我在這裡的夥伴布里維夫可以告訴你如何使用拳套武器...或者，如果你比較喜歡，伊琳尼雅·月火 - 位於達納蘇斯戰士區的夜精靈武器大師 - 也可以告訴你!', `FemaleText_loc7`='Mi colega Buliwyf aquí te puede enseñar a usar las armas de puño... o, si prefieres, Ilyenia Fuegolunar, la elfa de la noche maestra de armas que está en el Bancal del Guerrero en Darnassus podrá enseñarte también.' WHERE `ID`=20571;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 내 혈기 왕성한 친구인 빅시 워블봉크가 당신에게 석궁 사용법에 대해서 알려줄 것일세. 자네가 다른 무기 전문가를 찾는다면 다르나서스의 전사의 정원에 있는 일예니아 문파이어를 만나 보거나, 엑소다르의 교역 지구에 있는 드레나이 무기 전문가인 한디르를 만나 보게나.', `MaleText_loc4`='那个勇敢的比克斯就能教你怎么使用弩。不过如果你在找其他训练师的话，可以去找达纳苏斯战士区的伊琳尼雅·月火，或者是埃索达内贸易阶梯的德莱尼人武器大韩迪尔。', `MaleText_loc5`='我在這裡的勇敢同伴比克斯可以訓練你使用弩。不過如果你想找其他的訓練師，你也許想要找看看位於達納蘇斯戰士區的伊琳尼雅·月火，或者也許你可以找位於艾克索達內貿易區的德萊尼武器大師哈戴爾。', `MaleText_loc7`='Mi valiente compañero Bixi Tambaleapié aquí te enseñará de ballestas. Sin embargo, si buscas otros instructores, quizá quieras probar con Ilyenia Fuegolunar en el Bancal del Guerrero en Darnassus, o quizá con el maestro de armas draenei Handiir, que está en la Grada de los Mercaderes en El Exodar.' WHERE `ID`=20572;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다르나서스의 전사의 정원에 있는 나이트 엘프 무기 전문가 일예니아 문파이어가 활 사용법에 대해서 알려 줄 것일세.', `MaleText_loc4`='居住在达纳苏斯战士区的暗夜精灵武器大师伊琳尼雅·月火能指导你怎么使用弓。', `MaleText_loc5`='伊琳尼雅·月火，居住於達納蘇斯戰士區的夜精靈武器大師，能夠告訴你如何使用一把弓。', `MaleText_loc7`='Ilyenia Fuegolunar, elfa de la noche maestra de armas que reside en el Bancal del Guerrero en Darnassus podrá entrenarte a usar un arco.', `FemaleText_loc1`='다르나서스의 전사의 정원에 있는 나이트 엘프 무기 전문가 일예니아 문파이어가 활 사용법에 대해서 알려 줄 것일세.', `FemaleText_loc4`='居住在达纳苏斯战士区的暗夜精灵武器大师伊琳尼雅·月火能指导你怎么使用弓。', `FemaleText_loc5`='伊琳尼雅·月火，居住於達納蘇斯戰士區的夜精靈武器大師，能夠告訴你如何使用一把弓。', `FemaleText_loc7`='Ilyenia Fuegolunar, elfa de la noche maestra de armas que reside en el Bancal del Guerrero en Darnassus podrá entrenarte a usar un arco.' WHERE `ID`=20573;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한디르와 불리위프가 철퇴가 얼마나 크건 간에 상관없이 철퇴를 올바르게 휘두르는 법에 대해서 알려줄 것입니다. 아이언포지의 잘나가는 무기 상점에 있는 불스위프를 찾을 수 있을 겁니다. 한디르는 엑소다르의 교역 지구에서 드레나이들을 가르치며 그의 일과를 보내고 있습니다.', `MaleText_loc4`='韩迪尔和布里维夫都能指导你怎么挥舞锤子，无论大小。你可以在铁炉堡的密林武器店内找到布里维夫，而韩迪尔则整天待在埃索达的贸易阶梯训练着德莱尼人。', `MaleText_loc5`='哈戴爾及布里維夫兩者都能夠告訴你正確揮舞錘子的方法，無論大小。你可以去鐵爐堡密林武器店裡找到布里維夫。哈戴爾住在艾克索達，在貿易區訓練德萊尼。', `MaleText_loc7`='Tanto Handiir como Buliwyf pueden enseñarte a usar una maza correctamente, sea del tamaño que sea. Encontrarás a Buliwyf dentro de Armas Mil Maderas en Forjaz. Handiir pasa los días en El Exodar formando a draenei en la Grada de los Mercaderes.', `FemaleText_loc1`='한디르와 불리위프가 철퇴가 얼마나 크건 간에 상관없이 철퇴를 올바르게 휘두르는 법에 대해서 알려줄 것입니다. 아이언포지의 잘나가는 무기 상점에 있는 불스위프를 찾을 수 있을 겁니다. 한디르는 엑소다르의 교역 지구에서 드레나이들을 가르치며 그의 일과를 보내고 있습니다.', `FemaleText_loc4`='韩迪尔和布里维夫都能指导你怎么挥舞锤子，无论大小。你可以在铁炉堡的密林武器店内找到布里维夫，而韩迪尔则整天待在埃索达的贸易阶梯训练着德莱尼人。', `FemaleText_loc5`='哈戴爾及布里維夫兩者都能夠告訴你正確揮舞錘子的方法，無論大小。你可以去鐵爐堡密林武器店裡找到布里維夫。哈戴爾住在艾克索達，在貿易區訓練德萊尼。', `FemaleText_loc7`='Tanto Handiir como Buliwyf pueden enseñarte a usar una maza correctamente, sea del tamaño que sea. Encontrarás a Buliwyf dentro de Armas Mil Maderas en Forjaz. Handiir pasa los días en El Exodar formando a draenei en la Grada de los Mercaderes.' WHERE `ID`=20574;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='둔기라면 불리위크의 전문 분야지요! 그는 투덜거리며 이 상점을 돌아다닌답니다. 그의 훈련 기술이 맘에 들지 않는다면, 한디르라고 둔기에 관해서 잘 아는 엑소다르에 있는 드레나이 무기 전문가가 있다고 들었으니 그리로 가 보십시오! 그는 엑소다르에 교역 지구에서 만날 수 있을 겁니다.', `MaleText_loc4`='锤子是布里维夫的最拿手的武器！他就在这家店附近。如果你不喜欢他的训练方法，我听说埃索达的德莱尼的武器大师韩迪尔同样也知道怎么摆弄锤子！他就在贸易阶梯那里。', `MaleText_loc5`='錘類武器是布里維夫的專長!他就在這家店的某處，發勞騷中。如果他的訓練技術非你的風格，我聽說艾克索達的德萊尼武器大師，哈戴爾，也對武器有他的一套方式!他就在貿易區的上層。', `MaleText_loc7`='¡Las mazas son la especialidad de Buliwyf! Está en algún lugar de esta tienda, refunfuñando. Si sus técnicas de entrenamiento no son de tu gusto, he oído que el maestro de armas draenei en El Exodar, Handiir, también es un gran experto. Se encuentra en la Grada de los Mercaderes.', `FemaleText_loc1`='둔기라면 불리위크의 전문 분야지요! 그는 투덜거리며 이 상점을 돌아다닌답니다. 그의 훈련 기술이 맘에 들지 않는다면, 한디르라고 둔기에 관해서 잘 아는 엑소다르에 있는 드레나이 무기 전문가가 있다고 들었으니 그리로 가 보십시오! 그는 엑소다르에 교역 지구에서 만날 수 있을 겁니다.', `FemaleText_loc4`='锤子是布里维夫的最拿手的武器！他就在这家店附近。如果你不喜欢他的训练方法，我听说埃索达的德莱尼的武器大师韩迪尔同样也知道怎么摆弄锤子！他就在贸易阶梯那里。', `FemaleText_loc5`='錘類武器是布里維夫的專長!他就在這家店的某處，發勞騷中。如果他的訓練技術非你的風格，我聽說艾克索達的德萊尼武器大師，哈戴爾，也對武器有他的一套方式!他就在貿易區的上層。', `FemaleText_loc7`='¡Las mazas son la especialidad de Buliwyf! Está en algún lugar de esta tienda, refunfuñando. Si sus técnicas de entrenamiento no son de tu gusto, he oído que el maestro de armas draenei en El Exodar, Handiir, también es un gran experto. Se encuentra en la Grada de los Mercaderes.' WHERE `ID`=20575;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우 핑은 장창의 전문가랍니다. 그는 스톰윈드에 있는 웰러의 무기고에서 학생들을 가르치고 있으니 그리로 가 보십시오.', `MaleText_loc4`='吴平是长柄武器的大师。他一般在暴风城的维勒武器店训练学生。', `MaleText_loc5`='吳平是長柄武器大師。他就在暴風城的維勒武器店訓練他的學生。', `MaleText_loc7`='Woo Ping es el maestro de las armas de asta. Entrena a sus pupilos en el Arsenal de Weller en Ventormenta.', `FemaleText_loc1`='우 핑은 장창의 전문가랍니다. 그는 스톰윈드에 있는 웰러의 무기고에서 학생들을 가르치고 있으니 그리로 가 보십시오.', `FemaleText_loc4`='吴平是长柄武器的大师。他一般在暴风城的维勒武器店训练学生。', `FemaleText_loc5`='吳平是長柄武器大師。他就在暴風城的維勒武器店訓練他的學生。', `FemaleText_loc7`='Woo Ping es el maestro de las armas de asta. Entrena a sus pupilos en el Arsenal de Weller en Ventormenta.' WHERE `ID`=20576;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지팡이 사용법이라면 스톰윈드 웰러의 무기고에 있는 전문가인 우 핑이나 다르나서스의 전사의 정원에 있는 나이트 엘프 일예니아 문파이어에게서 배울 수 있을 겁니다.', `MaleText_loc4`='暴风城维勒武器店的武器大师吴平和达纳苏斯战士区的伊琳尼雅·月火都能教会你怎么使用法杖。', `MaleText_loc5`='法杖類武器是由暴風城維勒武器店的武器大師，吳平所教授，還有伊琳尼雅·月火，於達納蘇斯的戰士區訓練夜精靈們。', `MaleText_loc7`='Tanto Woo Ping, el maestro que se encuentra en el Arsenal de Weller en Ventormenta, como Ilyenia Fuegolunar que entrena a los elfos de la noche en el Bancal del Guerrero de Darnassus podrán formarte en el arte de los bastones.', `FemaleText_loc1`='지팡이 사용법이라면 스톰윈드 웰러의 무기고에 있는 전문가인 우 핑이나 다르나서스의 전사의 정원에 있는 나이트 엘프 일예니아 문파이어에게서 배울 수 있을 겁니다.', `FemaleText_loc4`='暴风城维勒武器店的武器大师吴平和达纳苏斯战士区的伊琳尼雅·月火都能教会你怎么使用法杖。', `FemaleText_loc5`='法杖類武器是由暴風城維勒武器店的武器大師，吳平所教授，還有伊琳尼雅·月火，於達納蘇斯的戰士區訓練夜精靈們。', `FemaleText_loc7`='Tanto Woo Ping, el maestro que se encuentra en el Arsenal de Weller en Ventormenta, como Ilyenia Fuegolunar que entrena a los elfos de la noche en el Bancal del Guerrero de Darnassus podrán formarte en el arte de los bastones.' WHERE `ID`=20577;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한디르와 우 핑이라는 두 도검 전문가가 있습니다. 한디르는 엑소다르의 교역 지구에서 만날 수 있으며, 우 핑은 스톰윈드 내에 있는 웰러의 무기고에서 만날 수 있답니다.', `MaleText_loc4`='联盟有两名使剑的大师：韩迪尔和吴平。你可以在埃索达的贸易阶梯找到前者，而后者可以在暴风城的维勒武器店找到。', `MaleText_loc5`='劍的部分有兩位大師:哈戴爾以及吳平。前者可於艾克索達的貿易區找到他，而後者則可於暴風城裡的維勒武器店找到。', `MaleText_loc7`='Hay dos maestros de la espada: Handiir y Woo Ping. El primero se encuentra en la Grada de los Mercaderes en El Exodar, y el segundo en el Arsenal de Weller en Ventormenta.', `FemaleText_loc1`='한디르와 우 핑이라는 두 도검 전문가가 있습니다. 한디르는 엑소다르의 교역 지구에서 만날 수 있으며, 우 핑은 스톰윈드 내에 있는 웰러의 무기고에서 만날 수 있답니다.', `FemaleText_loc4`='联盟有两名使剑的大师：韩迪尔和吴平。你可以在埃索达的贸易阶梯找到前者，而后者可以在暴风城的维勒武器店找到。', `FemaleText_loc5`='劍的部分有兩位大師:哈戴爾以及吳平。前者可於艾克索達的貿易區找到他，而後者則可於暴風城裡的維勒武器店找到。', `FemaleText_loc7`='Hay dos maestros de la espada: Handiir y Woo Ping. El primero se encuentra en la Grada de los Mercaderes en El Exodar, y el segundo en el Arsenal de Weller en Ventormenta.' WHERE `ID`=20578;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다르나서스의 전사의 정원에 있는 일예니아 문파이어와 아이언포지의 잘나가는 무기 상점에 있는 빅시 워블봉크가 당신에게 어떻게 투척 무기를 사용할 수 있는지 알려줄 수 있습니다.', `MaleText_loc4`='达纳苏斯战士区的伊琳尼雅·月火和铁炉堡密林武器店的比克斯都能指导你怎么适当地使用投掷武器。', `MaleText_loc5`='達納蘇斯戰士區的伊琳尼雅·月火以及鐵爐堡密林武器店的比克斯兩者都能告訴你正確使用投擲武器的方法。', `MaleText_loc7`='Tanto Ilyenia Fuegolunar en el Bancal del Guerrero en Darnassus como Bixi Tambaleapié de Armas Mil Maderas en Forjaz te podrán enseñar a lanzar las armas arrojadizas correctamente.', `FemaleText_loc1`='다르나서스의 전사의 정원에 있는 일예니아 문파이어와 아이언포지의 잘나가는 무기 상점에 있는 빅시 워블봉크가 당신에게 어떻게 투척 무기를 사용할 수 있는지 알려줄 수 있습니다.', `FemaleText_loc4`='达纳苏斯战士区的伊琳尼雅·月火和铁炉堡密林武器店的比克斯都能指导你怎么适当地使用投掷武器。', `FemaleText_loc5`='達納蘇斯戰士區的伊琳尼雅·月火以及鐵爐堡密林武器店的比克斯兩者都能告訴你正確使用投擲武器的方法。', `FemaleText_loc7`='Tanto Ilyenia Fuegolunar en el Bancal del Guerrero en Darnassus como Bixi Tambaleapié de Armas Mil Maderas en Forjaz te podrán enseñar a lanzar las armas arrojadizas correctamente.' WHERE `ID`=20579;
