UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 빅시가 투척 무기를 던지는 방법에 대해서 알려줄 겁니다. 다르나서스가 더 가까우시다면, 그곳의 전사의 정원에 있는 일예니아 문파이어를 만나보십시오.', `MaleText_loc4`='这里的比克斯能教你怎么使用投掷武器。要是你去达纳苏斯更方便的话，也可以去找那里战士区的伊琳尼雅·月火学习。', `MaleText_loc5`='這裡的比克斯能夠教導你如何投擲武器。如果你離達納蘇斯夠近的話，去那裡與戰士區的伊琳尼雅·月火談談。', `MaleText_loc7`='Bixi te ayudará a aprender a lanzar las armas arrojadizas. Si Darnassus es más tu estilo, habla con Ilyenia Fuegolunar, que está en el Bancal del Guerrero.', `FemaleText_loc1`='여기 빅시가 투척 무기를 던지는 방법에 대해서 알려줄 겁니다. 다르나서스가 더 가까우시다면, 그곳의 전사의 정원에 있는 일예니아 문파이어를 만나보십시오.', `FemaleText_loc4`='这里的比克斯能教你怎么使用投掷武器。要是你去达纳苏斯更方便的话，也可以去找那里战士区的伊琳尼雅·月火学习。', `FemaleText_loc5`='這裡的比克斯能夠教導你如何投擲武器。如果你離達納蘇斯夠近的話，去那裡與戰士區的伊琳尼雅·月火談談。', `FemaleText_loc7`='Bixi te ayudará a aprender a lanzar las armas arrojadizas. Si Darnassus es más tu estilo, habla con Ilyenia Fuegolunar, que está en el Bancal del Guerrero.' WHERE `ID`=20592;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나와 함께하는 것인가, $n?', `MaleText_loc4`='你会帮我吗，$n？', `MaleText_loc5`='你了解我的意思嗎，$n?', `MaleText_loc7`='¿Estás conmigo, $n?' WHERE `ID`=20593;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무기에 대한 기술을 배우고자 하신다면, 제가 알려드릴 수 있습니다.', `MaleText_loc4`='如果你需要武器训练，我可以向你提供。', `MaleText_loc5`='如果你在尋找武器的訓練課程，我可以告訴你。', `MaleText_loc7`='Si buscas instrucción en las armas, yo la ofrezco.' WHERE `ID`=20594;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 다른 무기 사용법을 배우고 싶은 건가요? 그럼 내가 어디로 가야 할지 알려주도록 하지요. 당신이 배우고자 하는 무기가 어떤 것인지 알려주세요.', `MaleText_loc4`='啊，你希望去其他地方训练？我会指引你的。告诉我你对什么武器有兴趣。', `MaleText_loc5`='啊，你想要到外面去受訓嗎?我會指引你的。告訴我什麼樣的武器吸引了你的注意。', `MaleText_loc7`='Ah, así que quieres entrenarte lejos de aquí. Te guiaré. Dime qué arma ha despertado tu interés.' WHERE `ID`=20595;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='유물 세 개를 모두 모았군. 그런데 내 기력이 급속도로 떨어지고 있네. 어서 꿈지기 루로사에게 돌아가야 해! 다음으로, 무얼 해야 할지 그가 알려줄 걸세.', `MaleText_loc4`='我们已经得到了全部三件圣物，不过我的能量正在迅速消失。我们必须立刻回到梦境卫士鲁罗萨那里去！他会告诉你接下来该怎么做。', `MaleText_loc5`='我們擁有了所有的三個聖器，不過我的能量已經快速的消弱了。我們一定要回去找夢境看守者盧羅莎!他會讓你知道你的下一步該是什麼。', `MaleText_loc7`='Ya tenemos las tres reliquias, pero mi energía se pierde con rapidez. ¡Debemos volver hasta el celador de sueños Lurosa! Él te indicará qué debes hacer a continuación.' WHERE `ID`=20596;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너어어어어무 귀엽다!!!', `FemaleText_loc4`='太可爱了！！！', `FemaleText_loc5`='太可愛了!!!', `FemaleText_loc7`='¡¡¡Qué monadaaaa!!!' WHERE `ID`=20597;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='꺄르르르... 안녕! 작고 귀여운 아가야!', `FemaleText_loc4`='啊……你好啊，小宝贝！', `FemaleText_loc5`='哇喔...你好啊，小寶貝!', `FemaleText_loc7`='Oooh... ¡Hola, pequeñines!' WHERE `ID`=20598;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저들은 무척 작네요.', `FemaleText_loc4`='他们实在太小了。', `FemaleText_loc5`='他們好迷你喔。', `FemaleText_loc7`='Son tan pequeñitos.' WHERE `ID`=20599;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='와...', `FemaleText_loc4`='啊……', `FemaleText_loc5`='哇喔...', `FemaleText_loc7`='Oooh...' WHERE `ID`=20600;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='루로사, 아비아나의 유물은 $n의 손에 맡겨서 모르디스 위스퍼윙에게 전하면 될 거야. 나는 당장 에메랄드의 꿈으로 돌아가야만 하네. $n|1이;가; 실패하지 않도록 잘 인도해 주게.', `MaleText_loc4`='鲁罗萨，我把艾维娜圣物委托给$n转交莫希斯·轻翼了。现在我必须彻底地回到翡翠梦境去了。不要让$n失败！', `MaleText_loc5`='盧羅莎，我將艾維娜的聖物託管給$n，他將會將東西帶去給莫西斯·語翼。我現在必須完整的回到翡翠夢境去。別讓$n失敗!', `MaleText_loc7`='Lurosa, confío las Reliquias de Aviana a $n, que las llevará hasta Morthis Alasusurro. Ahora debo regresar al Sueño Esmeralda por completo. ¡No dejes que $n fracase!' WHERE `ID`=20601;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='음... 이건 냄새가 좀 이상한데...', `FemaleText_loc4`='唔……这东西闻起来很有趣。', `FemaleText_loc5`='嗯嗯...這個聞起來有點好笑。', `FemaleText_loc7`='Mmm.. este huele rarito.' WHERE `ID`=20602;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말 큰 눈을 가지셨네요!', `FemaleText_loc4`='你的眼睛真大啊！', `FemaleText_loc5`='你的眼睛真大!', `FemaleText_loc7`='¡Qué ojos más grandes tienes!' WHERE `ID`=20603;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나도 요렇게 조그마했을 때가 있었을까?!', `FemaleText_loc4`='我不记得曾经有这么小过。', `FemaleText_loc5`='我不記得曾經這麼小過。', `FemaleText_loc7`='No recuerdo haber sido nunca tan peque.' WHERE `ID`=20604;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아유, 귀여워라!', `FemaleText_loc4`='多可爱啊！', `FemaleText_loc5`='真是可愛!', `FemaleText_loc7`='¡Qué cosita!' WHERE `ID`=20605;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하나시와 사요크에게 가면 한손 도끼는 물론 양손 도끼 사용법을 배울 수 있네. 오그리마, 명예의 골짜기로 가면 만날 수 있지.', `MaleText_loc4`='哈纳什和塞尤克可以教会你如何使用单手斧和双手斧。你可以在奥格瑞玛的荣誉谷找到他们。', `MaleText_loc5`='哈納什與塞尤克兩者都能訓練你使用單手及雙手斧。可以在奧格瑪的榮譽谷找到他們。', `MaleText_loc7`='Tanto Hanashi como Sayoc podrán entrenarte en el uso de las hachas de una y dos manos. Se encuentran en el Valle del Honor en Orgrimmar.', `FemaleText_loc1`='하나시와 사요크에게 가면 한손 도끼는 물론 양손 도끼 사용법을 배울 수 있네. 오그리마, 명예의 골짜기로 가면 만날 수 있지.', `FemaleText_loc4`='哈纳什和塞尤克可以教会你如何使用单手斧和双手斧。你可以在奥格瑞玛的荣誉谷找到他们。', `FemaleText_loc5`='哈納什與塞尤克兩者都能訓練你使用單手及雙手斧。可以在奧格瑪的榮譽谷找到他們。', `FemaleText_loc7`='Tanto Hanashi como Sayoc podrán entrenarte en el uso de las hachas de una y dos manos. Se encuentran en el Valle del Honor en Orgrimmar.' WHERE `ID`=20606;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오그리마, 명예의 골짜기에 사는 사요크와 하나시라는 무기 전문가들에게서 활 쏘는 법을 배울 수 있지. 실버문의 원정순찰대 광장에 있는 무기 전문가, 일레다가 활쏘기라면 둘째 가라면 서러운 실력을 자랑하지.', `MaleText_loc4`='奥格瑞玛荣誉谷内的武器大师塞尤克和哈纳什可以教你如何射箭，银月城远行者广场的武器大师伊蕾达同样也是这方面的专家。', `MaleText_loc5`='奧格瑪內榮譽谷的武器大師，塞尤克與哈納什，都能教授你使用弓射箭的方法。伊利達，銀月城遠行者廣場的武器大師，也是箇中好手。', `MaleText_loc7`='Los maestros de armas del Valle del Honor de Orgrimmar, Sayoc y Hanashi, te enseñarán cómo disparar un arco. Ileda, la maestra de armas de Lunargenta se encuentra en la Plaza del Errante y también es una experta.', `FemaleText_loc1`='오그리마, 명예의 골짜기에 사는 사요크와 하나시라는 무기 전문가들에게서 활 쏘는 법을 배울 수 있지. 실버문의 원정순찰대 광장에 있는 무기 전문가, 일레다가 활쏘기라면 둘째 가라면 서러운 실력을 자랑하지.', `FemaleText_loc4`='奥格瑞玛荣誉谷内的武器大师塞尤克和哈纳什可以教你如何射箭，银月城远行者广场的武器大师伊蕾达同样也是这方面的专家。', `FemaleText_loc5`='奧格瑪內榮譽谷的武器大師，塞尤克與哈納什，都能教授你使用弓射箭的方法。伊利達，銀月城遠行者廣場的武器大師，也是箇中好手。', `FemaleText_loc7`='Los maestros de armas del Valle del Honor de Orgrimmar, Sayoc y Hanashi, te enseñarán cómo disparar un arco. Ileda, la maestra de armas de Lunargenta se encuentra en la Plaza del Errante y también es una experta.' WHERE `ID`=20608;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='석궁이라면 역시 아키발드가 전문이지. 그 무기 전문가는 언더시티의 군사 지구로 가면 찾을 수 있어.', `MaleText_loc4`='阿基巴德是用弩的大师。他是幽暗城的武器大师，就居住在军事区。', `MaleText_loc5`='阿基巴德是十字弩大師。他是幽暗城的武器大師，就在戰爭區那。', `MaleText_loc7`='Archibald es el maestro de la ballesta. Es el maestro de armas de Entrañas y se encuentra en el Barrio de la Guerra.', `FemaleText_loc1`='석궁이라면 역시 아키발드가 전문이지. 그 무기 전문가는 언더시티의 군사 지구로 가면 찾을 수 있어.', `FemaleText_loc4`='阿基巴德是用弩的大师。他是幽暗城的武器大师，就居住在军事区。', `FemaleText_loc5`='阿基巴德是十字弩大師。他是幽暗城的武器大師，就在戰爭區那。', `FemaleText_loc7`='Archibald es el maestro de la ballesta. Es el maestro de armas de Entrañas y se encuentra en el Barrio de la Guerra.' WHERE `ID`=20609;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세 명의 무기 전문가에게서 단검 사용법을 배울 수 있지. 언더시티의 군사 지구에 있는 아키발드, 오그리마 명예의 골짜기에 있는 사요크, 실버문의 원정순찰대 광장에 있는 일레다 중에서 마음에 드는 스승을 찾아가게.', `MaleText_loc4`='你可以从三个武器大师那里寻求匕首的使用指导：幽暗城军事区的阿基巴德，奥格瑞玛荣誉谷内的塞尤克，和银月城远行者广场的伊蕾达。', `MaleText_loc5`='學習匕首可找以下三位武器大師:幽暗城戰爭區的阿基巴德，奧格瑪榮譽谷的塞尤克，以及銀月城遠行者廣場的伊利達。', `MaleText_loc7`='Hay tres maestros de armas preparados para instruirte en el arte de las dagas: Archibald del Barrio de la Guerra en Entrañas, Sayoc del Valle del Honor en Orgrimmar e Ileda en la Plaza del Errante de Lunargenta.', `FemaleText_loc1`='세 명의 무기 전문가에게서 단검 사용법을 배울 수 있지. 언더시티의 군사 지구에 있는 아키발드, 오그리마 명예의 골짜기에 있는 사요크, 실버문의 원정순찰대 광장에 있는 일레다 중에서 마음에 드는 스승을 찾아가게.', `FemaleText_loc4`='你可以从三个武器大师那里寻求匕首的使用指导：幽暗城军事区的阿基巴德，奥格瑞玛荣誉谷内的塞尤克，和银月城远行者广场的伊蕾达。', `FemaleText_loc5`='學習匕首可找以下三位武器大師:幽暗城戰爭區的阿基巴德，奧格瑪榮譽谷的塞尤克，以及銀月城遠行者廣場的伊利達。', `FemaleText_loc7`='Hay tres maestros de armas preparados para instruirte en el arte de las dagas: Archibald del Barrio de la Guerra en Entrañas, Sayoc del Valle del Honor en Orgrimmar e Ileda en la Plaza del Errante de Lunargenta.' WHERE `ID`=20610;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오그리마에서 못생긴 오크 사요크가 단검 쓰는 법을 가르쳐주지. 다른 도시에서 배우고 싶다면 실버문의 원정순찰대 광장에 있는 일레다나 언더시티의 군사 지구에 있는 아키발드에게 가서 얘기해 보게.', `MaleText_loc4`='那个丑陋的兽人塞尤克可以教你如何使用匕首。要是你想在其他地方学的话，也可以去银月城远行者广场找伊蕾达或是去幽暗城军事区找阿基巴德，如何？', `MaleText_loc5`='塞尤克，這邊那個醜陋的獸人，可以教你使用匕首。你想要在別的地方學習的話，你可以找銀月城遠行者廣場的伊利達或是幽暗城戰爭區的阿基巴德談談，知道嗎?', `MaleText_loc7`='Sayoc, este feo orco, te enseña de dagas. Si buscas otro lugar, habla con Ileda en la Plaza del Errante de Lunargenta o con Archibald en el Barrio de la Guerra de Entrañas. ¿Vale?', `FemaleText_loc1`='오그리마에서 못생긴 오크 사요크가 단검 쓰는 법을 가르쳐주지. 다른 도시에서 배우고 싶다면 실버문의 원정순찰대 광장에 있는 일레다나 언더시티의 군사 지구에 있는 아키발드에게 가서 얘기해 보게.', `FemaleText_loc4`='那个丑陋的兽人塞尤克可以教你如何使用匕首。要是你想在其他地方学的话，也可以去银月城远行者广场找伊蕾达或是去幽暗城军事区找阿基巴德，如何？', `FemaleText_loc5`='塞尤克，這邊那個醜陋的獸人，可以教你使用匕首。你想要在別的地方學習的話，你可以找銀月城遠行者廣場的伊利達或是幽暗城戰爭區的阿基巴德談談，知道嗎?', `FemaleText_loc7`='Sayoc, este feo orco, te enseña de dagas. Si buscas otro lugar, habla con Ileda en la Plaza del Errante de Lunargenta o con Archibald en el Barrio de la Guerra de Entrañas. ¿Vale?' WHERE `ID`=20611;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장착 무기라면 오그리마의 무기 전문가인 사요크한테 가서 배우게. 그 오크는 요새 명예의 골짜기에서 지내더군.', `MaleText_loc4`='你可以在奥格瑞玛的兽人武器大师塞尤克那里学会使用拳套。他每天都在荣誉谷。', `MaleText_loc5`='拳套是由位於奧格瑪的獸人武器大師，塞尤克所指導。他通常都在榮譽谷那。', `MaleText_loc7`='Sayoc, el maestro de armas de Orgrimmar te enseñará cómo usar las armas de puño. Pasa sus días en el Valle del Honor.', `FemaleText_loc1`='장착 무기라면 오그리마의 무기 전문가인 사요크한테 가서 배우게. 그 오크는 요새 명예의 골짜기에서 지내더군.', `FemaleText_loc4`='你可以在奥格瑞玛的兽人武器大师塞尤克那里学会使用拳套。他每天都在荣誉谷。', `FemaleText_loc5`='拳套是由位於奧格瑪的獸人武器大師，塞尤克所指導。他通常都在榮譽谷那。', `FemaleText_loc7`='Sayoc, el maestro de armas de Orgrimmar te enseñará cómo usar las armas de puño. Pasa sus días en el Valle del Honor.' WHERE `ID`=20612;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적들에게 크게 한 방 날리고 싶은가 보지? 저기 사요크한테 가서 이야기하게. 그가 장착 무기 쓰는 법을 가르쳐 줄 거야.', `MaleText_loc4`='你想学习拳套的使用方法吗？和这里的塞尤克谈谈，他会教你的。', `MaleText_loc5`='你想要拳擊事物，對吧?去跟這裡的塞尤克談談。他會教你的。', `MaleText_loc7`='Así que te gusta dar puñetazos. Bueno, entonces habla con Sayoc. Él te enseñará.', `FemaleText_loc1`='적들에게 크게 한 방 날리고 싶은가 보지? 저기 사요크한테 가서 이야기하게. 그가 장착 무기 쓰는 법을 가르쳐 줄 거야.', `FemaleText_loc4`='你想学习拳套的使用方法吗？和这里的塞尤克谈谈，他会教你的。', `FemaleText_loc5`='你想要拳擊事物，對吧?去跟這裡的塞尤克談談。他會教你的。', `FemaleText_loc7`='Así que te gusta dar puñetazos. Bueno, entonces habla con Sayoc. Él te enseñará.' WHERE `ID`=20613;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='총기류 사용법이라면 안세크화가 가르치지. 썬더 블러프 중앙의 하층 봉우리로 가면 그 타우렌 무기 전문가를 만날 수 있어.', `MaleText_loc4`='我们的射击教师是安塞瓦，居住在雷霆崖中部高地底层的牛头人武器大师。', `MaleText_loc5`='我們的射擊指導是位於雷霆崖低層中部高地的牛頭人武器大師，安塞瓦。', `MaleText_loc7`='Nuestro instructor de armas de fuego es Ansekhwa, el maestro de armas tauren que se encuentran en la elevación media central de Cima del Trueno.', `FemaleText_loc1`='총기류 사용법이라면 안세크화가 가르치지. 썬더 블러프 중앙의 하층 봉우리로 가면 그 타우렌 무기 전문가를 만날 수 있어.', `FemaleText_loc4`='我们的射击教师是安塞瓦，居住在雷霆崖中部高地底层的牛头人武器大师。', `FemaleText_loc5`='我們的射擊指導是位於雷霆崖低層中部高地的牛頭人武器大師，安塞瓦。', `FemaleText_loc7`='Nuestro instructor de armas de fuego es Ansekhwa, el maestro de armas tauren que se encuentran en la elevación media central de Cima del Trueno.' WHERE `ID`=20614;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='둔기 사용법은 안세크화한테 가서 배우게. 썬더 블러프 중앙의 하층 봉우리에서 찾을 수 있지.', `MaleText_loc4`='安塞瓦会教你怎么使用锤子，你可以在雷霆崖的中部高地底层找到他。', `MaleText_loc5`='錘類武器由安塞瓦所教導，可以在雷霆崖的低層中部高地找到他。', `MaleText_loc7`='Ansekhwa enseña sobre las mazas y se encuentra en la elevación menor central de Cima del Trueno.', `FemaleText_loc1`='둔기 사용법은 안세크화한테 가서 배우게. 썬더 블러프 중앙의 하층 봉우리에서 찾을 수 있지.', `FemaleText_loc4`='安塞瓦会教你怎么使用锤子，你可以在雷霆崖的中部高地底层找到他。', `FemaleText_loc5`='錘類武器由安塞瓦所教導，可以在雷霆崖的低層中部高地找到他。', `FemaleText_loc7`='Ansekhwa enseña sobre las mazas y se encuentra en la elevación menor central de Cima del Trueno.' WHERE `ID`=20615;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장창 다루는 법이라면 포세이큰 무기 전문가인 아키발드가 정통하지. 언더시티의 군사 지구로 가보게. 아니면, 실버문의 원정순찰대 광장에 있는 블러드 엘프 무기 전문가인 일레다에게 가도 쓸만한 장창 기술을 가르쳐 줄 거야.', `MaleText_loc4`='遗忘者的武器大师阿基巴德知道如何使用长柄武器，他就在幽暗城的军事区训练其他人。银月城远行者广场的血精灵武器大师伊蕾达也能教你相同的技能。', `MaleText_loc5`='被遺忘者的武器大師阿基巴德對長柄武器有他的一套方法。他在幽暗城的軍事區訓練人們。銀月城遠行者廣場的血精靈武器大師，伊利達，也可以告訴你相關的技巧。', `MaleText_loc7`='El maestro de armas de los Renegados es Archibald y conoce bien las armas de asta. Entrena a otros en el Barrio de la Guerra en Entrañas. Ileda, el maestro de armas elfo de sangre de la Plaza del Errante en Lunargenta, tambíen puede enseñarte las técnicas adecuadas.', `FemaleText_loc1`='장창 다루는 법이라면 포세이큰 무기 전문가인 아키발드가 정통하지. 언더시티의 군사 지구로 가보게. 아니면, 실버문의 원정순찰대 광장에 있는 블러드 엘프 무기 전문가인 일레다에게 가도 쓸만한 장창 기술을 가르쳐 줄 거야.', `FemaleText_loc4`='遗忘者的武器大师阿基巴德知道如何使用长柄武器，他就在幽暗城的军事区训练其他人。银月城远行者广场的血精灵武器大师伊蕾达也能教你相同的技能。', `FemaleText_loc5`='被遺忘者的武器大師阿基巴德對長柄武器有他的一套方法。他在幽暗城的軍事區訓練人們。銀月城遠行者廣場的血精靈武器大師，伊利達，也可以告訴你相關的技巧。', `FemaleText_loc7`='El maestro de armas de los Renegados es Archibald y conoce bien las armas de asta. Entrena a otros en el Barrio de la Guerra en Entrañas. Ileda, el maestro de armas elfo de sangre de la Plaza del Errante en Lunargenta, tambíen puede enseñarte las técnicas adecuadas.' WHERE `ID`=20616;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지팡이 사용법은 오그리마, 명예의 골짜기에 있는 트롤 무기 전문가인 하나시, 아니면 썬더 블러프 중앙의 하층 봉우리에 있는 타우렌 무기 전문가인 안세크화에게 가서 배우게.', `MaleText_loc4`='奥格瑞玛荣誉谷的巨魔武器大师哈纳什和雷霆崖中部高地底层的牛头人武器大师安塞瓦可以教你如何使用法杖。', `MaleText_loc5`='法杖類武器由位於奧格瑪榮譽谷的食人妖武器大師，哈納什所教導，以及位於雷霆崖低層中部高地進行訓練的牛頭人武器大師，安塞瓦。', `MaleText_loc7`='Tanto Hanashi, el maestro de armas trol del Valle del Honor de Orgrimmar como Ansekhwa, el maestro de armas tauren que entrena en la elevación menor central de Cima del Trueno podrán formarte en el arte de los bastones.', `FemaleText_loc1`='지팡이 사용법은 오그리마, 명예의 골짜기에 있는 트롤 무기 전문가인 하나시, 아니면 썬더 블러프 중앙의 하층 봉우리에 있는 타우렌 무기 전문가인 안세크화에게 가서 배우게.', `FemaleText_loc4`='奥格瑞玛荣誉谷的巨魔武器大师哈纳什和雷霆崖中部高地底层的牛头人武器大师安塞瓦可以教你如何使用法杖。', `FemaleText_loc5`='法杖類武器由位於奧格瑪榮譽谷的食人妖武器大師，哈納什所教導，以及位於雷霆崖低層中部高地進行訓練的牛頭人武器大師，安塞瓦。', `FemaleText_loc7`='Tanto Hanashi, el maestro de armas trol del Valle del Honor de Orgrimmar como Ansekhwa, el maestro de armas tauren que entrena en la elevación menor central de Cima del Trueno podrán formarte en el arte de los bastones.' WHERE `ID`=20617;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지팡이 사용법이라면 하나시가 잘 알지. 좀 더 엄한 스승을 찾는다면 썬더 블러프로 가보게. 그곳 중앙의 하층 봉우리에서 안세크화가 제자들에게 가르침을 내리고 있으니까.', `MaleText_loc4`='这里的哈纳什知道怎么使用法杖。如果你想找一个更强健的教师，就去雷霆崖，安塞瓦会在中部高地底层教你。', `MaleText_loc5`='這裡的哈納什對法杖類武器很熟悉。如果你想要一個強力的指導者，到雷霆崖去。安塞瓦會在低層中部高地處指導你。', `MaleText_loc7`='Hanashi conoce bien los bastones. Si buscas un instructor más robusto, ve a Cima del Trueno. Ansekhwa te enseñará más cosas, está en el alto central inferior.' WHERE `ID`=20618;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실버문의 원정순찰대 광장에 사는 블러드 엘프, 일레다가 제자들에게 한손 검과 양손 검 쓰는 법을 가르치지. 언더시티의 무기 전문가, 아키발드한테 가도 배울 수 있어. 군사 지구로 가보게.', `MaleText_loc4`='银月城远行者广场的血精灵伊蕾达会教你学习使用单手剑和双手剑。幽暗城的武器大师阿基巴德同样也能教你，他就在军事区。', `MaleText_loc5`='血精靈的伊利達，可在銀月城的遠行者廣場中找到他，訓練他的學生單手及雙手劍。阿基巴德，幽暗城的武器大師，也能夠訓練你;他就在軍事區那。', `MaleText_loc7`='Ileda de los elfos de sangre, en la Plaza del Errante de Lunargenta, entrena a sus estudiantes tanto con espadas de una mano como de dos. Archibald, el maestro de armas de Entrañas también te entrenará. Está en el Barrio de la Guerra.', `FemaleText_loc1`='실버문의 원정순찰대 광장에 사는 블러드 엘프, 일레다가 제자들에게 한손 검과 양손 검 쓰는 법을 가르치지. 언더시티의 무기 전문가, 아키발드한테 가도 배울 수 있어. 군사 지구로 가보게.', `FemaleText_loc4`='银月城远行者广场的血精灵伊蕾达会教你学习使用单手剑和双手剑。幽暗城的武器大师阿基巴德同样也能教你，他就在军事区。', `FemaleText_loc5`='血精靈的伊利達，可在銀月城的遠行者廣場中找到他，訓練他的學生單手及雙手劍。阿基巴德，幽暗城的武器大師，也能夠訓練你;他就在軍事區那。', `FemaleText_loc7`='Ileda de los elfos de sangre, en la Plaza del Errante de Lunargenta, entrena a sus estudiantes tanto con espadas de una mano como de dos. Archibald, el maestro de armas de Entrañas también te entrenará. Está en el Barrio de la Guerra.' WHERE `ID`=20619;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='투척 무기라면 오그리마의 무기 전문가인 사요크와 하나시가 정말 예술로 다루지. 그들은 명예의 골짜기에서 제자를 양성하고 있다네. 아니면, 실버문의 원정순찰대 광장에 있는 일레다도 당대 최고의 투척 기술을 보유하고 있으니 찾아가 보게나.', `MaleText_loc4`='奥格瑞玛的武器大师塞尤克和哈纳什是真正的投掷武器专家。他们在荣誉谷训练所有对此有兴趣的学生；如果想看更加优雅的投掷姿势，那么没人比得上银月城远行者广场的伊蕾达。', `MaleText_loc5`='塞尤克與哈納什，奧格瑪的武器大師，是專精投擲武器的大師。他們在榮譽谷訓練那些自願的學生們。不過，以此項技術的專精程度來說，銀月城遠行者廣場的伊利達才是所向無敵。', `MaleText_loc7`='Sayoc y Hanashi, los maestros de armas de Orgrimmar, son auténticos artesanos de las armas arrojadizas. Entrenan a pupilos obsecuentes en el Valle del Honor. Claro que si buscas una astucia imbatible, ve a ver a Ileda de la Plaza del Errante de Lunargenta.', `FemaleText_loc1`='투척 무기라면 오그리마의 무기 전문가인 사요크와 하나시가 정말 예술로 다루지. 그들은 명예의 골짜기에서 제자를 양성하고 있다네. 아니면, 실버문의 원정순찰대 광장에 있는 일레다도 당대 최고의 투척 기술을 보유하고 있으니 찾아가 보게나.', `FemaleText_loc4`='奥格瑞玛的武器大师塞尤克和哈纳什是真正的投掷武器专家。他们在荣誉谷训练所有对此有兴趣的学生；如果想看更加优雅的投掷姿势，那么没人比得上银月城远行者广场的伊蕾达。', `FemaleText_loc5`='塞尤克與哈納什，奧格瑪的武器大師，是專精投擲武器的大師。他們在榮譽谷訓練那些自願的學生們。不過，以此項技術的專精程度來說，銀月城遠行者廣場的伊利達才是所向無敵。', `FemaleText_loc7`='Sayoc y Hanashi, los maestros de armas de Orgrimmar, son auténticos artesanos de las armas arrojadizas. Entrenan a pupilos obsecuentes en el Valle del Honor. Claro que si buscas una astucia imbatible, ve a ver a Ileda de la Plaza del Errante de Lunargenta.' WHERE `ID`=20620;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='석궁이라면 아키발드가 전문이지. 그 무기 전문가는 언더시티의 군사 지구에서 찾을 수 있네.', `MaleText_loc4`='阿基巴德是弩类武器的教师。他是幽暗城的武器大师，就在军事区。', `MaleText_loc5`='阿基巴德，十字弩的大師。他是幽暗城的武器大師，位於軍事區那。', `MaleText_loc7`='Archibald es el maestro de la ballesta. Es el maestro de armas de Entrañas y se encuentra en el Barrio de la Guerra.', `FemaleText_loc1`='석궁이라면 아키발드가 전문이지. 그 무기 전문가는 언더시티의 군사 지구에서 찾을 수 있네.', `FemaleText_loc4`='阿基巴德是弩类武器的教师。他是幽暗城的武器大师，就在军事区。', `FemaleText_loc5`='阿基巴德，十字弩的大師。他是幽暗城的武器大師，位於軍事區那。', `FemaleText_loc7`='Archibald es el maestro de la ballesta. Es el maestro de armas de Entrañas y se encuentra en el Barrio de la Guerra.' WHERE `ID`=20621;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='총기류는 안세크화가 전문이야. 그 타우렌 무기 전문가는 썬더 블러프 중앙의 하층 봉우리에 있지.', `MaleText_loc4`='我们的射击老师是雷霆崖中部高地底层的牛头人武器大师安塞瓦。', `MaleText_loc5`='我們的射擊指導，安塞瓦，位於雷霆崖低層中部高地的牛頭人武器大師。', `MaleText_loc7`='Nuestro instructor de armas de fuego es Ansekhwa, el maestro de armas tauren que se encuentran en la elevación media central de Cima del Trueno.', `FemaleText_loc1`='총기류는 안세크화가 전문이야. 그 타우렌 무기 전문가는 썬더 블러프 중앙의 하층 봉우리에 있지.', `FemaleText_loc4`='我们的射击老师是雷霆崖中部高地底层的牛头人武器大师安塞瓦。', `FemaleText_loc5`='我們的射擊指導，安塞瓦，位於雷霆崖低層中部高地的牛頭人武器大師。', `FemaleText_loc7`='Nuestro instructor de armas de fuego es Ansekhwa, el maestro de armas tauren que se encuentran en la elevación media central de Cima del Trueno.' WHERE `ID`=20622;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='둔기 쓰는 법이라면 안세크화에게 가서 배우게. 썬더 블러프 중앙의 하층 봉우리에 있으니까...', `MaleText_loc4`='他们都是从在雷霆崖中部高地底层的安塞瓦那里学会使用锤子的。', `MaleText_loc5`='錘類武器，是由安塞瓦指導，可以在雷霆崖低層的中部高地找到他。', `MaleText_loc7`='Ansekhwa enseña de mazas y está en la elevación menor central de Cima del Trueno.', `FemaleText_loc1`='둔기 쓰는 법이라면 안세크화에게 가서 배우게. 썬더 블러프 중앙의 하층 봉우리에 있으니까...', `FemaleText_loc4`='他们都是从在雷霆崖中部高地底层的安塞瓦那里学会使用锤子的。', `FemaleText_loc5`='錘類武器，是由安塞瓦指導，可以在雷霆崖低層的中部高地找到他。', `FemaleText_loc7`='Ansekhwa enseña de mazas y está en la elevación menor central de Cima del Trueno.' WHERE `ID`=20623;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장창 다루는 법이라면 포세이큰 무기 전문가, 아키발드가 최고지. 언더시티의 군사 지구에서 제자들을 가르친다네. 실버문의 원정순찰대 광장에 있는 블러드 엘프 무기 전문가, 일레다도 쓸만한 장창 기술을 알고 있지.', `MaleText_loc4`='遗忘者的武器大师阿基巴德知道如何耍长柄武器，他就在幽暗城的军事区训练着其他人。银月城远行者广场的血精灵武器大师伊蕾达也能教你相同的技能，朋友。', `MaleText_loc5`='那位被遺忘者武器大師阿基巴德對長柄武器有他的一套方法。他在幽暗城的戰爭區訓練其他人。伊利達，銀月城內遠行者廣場的血精靈武器大師，也會告訴你正確的技巧，小子。', `MaleText_loc7`='El maestro de armas de los Renegados, Archibald, sabe lo que hace con las astas. Entrena a otros en el Barrio de la Guerra de Entrañas. Ileda, la maestra de armas elfo de sangre de la Plaza del Errante en Lunargenta te enseñará las técnicas correctas también, colega.', `FemaleText_loc1`='장창 다루는 법이라면 포세이큰 무기 전문가, 아키발드가 최고지. 언더시티의 군사 지구에서 제자들을 가르친다네. 실버문의 원정순찰대 광장에 있는 블러드 엘프 무기 전문가, 일레다도 쓸만한 장창 기술을 알고 있지.', `FemaleText_loc4`='遗忘者的武器大师阿基巴德知道如何耍长柄武器，他就在幽暗城的军事区训练着其他人。银月城远行者广场的血精灵武器大师伊蕾达也能教你相同的技能，朋友。', `FemaleText_loc5`='那位被遺忘者武器大師阿基巴德對長柄武器有他的一套方法。他在幽暗城的戰爭區訓練其他人。伊利達，銀月城內遠行者廣場的血精靈武器大師，也會告訴你正確的技巧，小子。', `FemaleText_loc7`='El maestro de armas de los Renegados, Archibald, sabe lo que hace con las astas. Entrena a otros en el Barrio de la Guerra de Entrañas. Ileda, la maestra de armas elfo de sangre de la Plaza del Errante en Lunargenta te enseñará las técnicas correctas también, colega.' WHERE `ID`=20624;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실버문의 원정순찰대 광장에 사는 블러드 엘프, 일레다가 제자들에게 한손 검과 양손 검 쓰는 법을 가르치지. 언더시티의 무기 전문가, 아키발드한테 가도 배울 수 있어. 군사 지구로 가보게.', `MaleText_loc4`='银月城远行者广场的血精灵伊蕾达会教你学习使用单手剑和双手剑。幽暗城的武器大师阿基巴德同样也能教你，他就在军事区。', `MaleText_loc5`='血精靈的伊利達，位於銀月城的遠行者廣場，訓練她的學生使用單手及雙手劍。阿基巴德，位於幽暗城的武器大師，也可以訓練你，小子。他就在軍事區。', `MaleText_loc7`='Ileda de los elfos de sangre, en la Plaza del Errante de Lunargenta, entrena a sus estudiantes tanto con espadas de una mano como de dos. Archibald, el maestro de armas de Entrañas también te entrenará, colega. Está en el Barrio de la Guerra.', `FemaleText_loc1`='실버문의 원정순찰대 광장에 사는 블러드 엘프, 일레다가 제자들에게 한손 검과 양손 검 쓰는 법을 가르치지. 언더시티의 무기 전문가, 아키발드한테 가도 배울 수 있어. 군사 지구로 가보게.', `FemaleText_loc4`='银月城远行者广场的血精灵伊蕾达会教你学习使用单手剑和双手剑。幽暗城的武器大师阿基巴德同样也能教你，他就在军事区。', `FemaleText_loc5`='血精靈的伊利達，位於銀月城的遠行者廣場，訓練她的學生使用單手及雙手劍。阿基巴德，位於幽暗城的武器大師，也可以訓練你，小子。他就在軍事區。', `FemaleText_loc7`='Ileda de los elfos de sangre, en la Plaza del Errante de Lunargenta, entrena a sus estudiantes tanto con espadas de una mano como de dos. Archibald, el maestro de armas de Entrañas también te entrenará, colega. Está en el Barrio de la Guerra.' WHERE `ID`=20625;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='왜 다른 무기를 배우려고 하시는지 이해가 가지 않는군요... 하지만, 정 고집을 피운다면 길 정도는 알려드릴 수 있습니다. 어떤 무기 훈련을 받고 싶은지 꼭 집어서 말씀해 보세요.', `FemaleText_loc4`='我不知道为什么你想学些其他技能……但我想我能为你找到合适的训练师。你具体想要什么训练？', `FemaleText_loc5`='我無法了解為何你想要學其他的東西...不過我猜想我能夠指引你正確的方向。你之後有特別想要進行哪一種訓練嗎?', `FemaleText_loc7`='No entiendo por qué quieres aprender otra cosa... pero supongo que puedo indicarte adónde ir. ¿Qué tipo de instrucción te interesa?' WHERE `ID`=20626;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='훈련을 받으러 온 게 아니라면 멀찌감치 떨어지십시오. 바쁘니까 방해하지 말란 말입니다.', `FemaleText_loc4`='既然你不是过来接受训练的，就站后面点，不要妨碍我工作。', `FemaleText_loc5`='如果你不是要來訓練的，就退後點讓我好好工作。', `FemaleText_loc7`='Si no estás aquí para entrenar, vete y déjame trabajar.' WHERE `ID`=20627;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실망스럽구나, 아카마! 내 몸소 저 벌레만도 못한 반역자를 심문하려 했거늘! 네 놈의 충성심부터 확인해 봐야겠다.', `MaleText_loc4`='你让我失望了，阿卡玛。我本想要亲自审讯这条狡猾的虫子！现在我有些怀疑你们这些破碎者的忠诚了。', `MaleText_loc5`='阿卡瑪，你真令我失望。我會親自審問這個奸詐的鼠輩!我開始質疑你的忠誠度了，失落者。', `MaleText_loc7`='Me decepcionas, Akama. ¡Quería interrogar al traidor yo mismo! Comienzo a dudar de tu lealtad, Tábido.' WHERE `ID`=20628;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 거짓말을 한다고 생각하진 않는다, 아카마. 캘타스 놈의 배신도 그리 놀라운 일은 아니지. 하지만, 너의 종족이 그와 연루되었다는 사실은 너의 충성심을 의심하게 하는구나.', `MaleText_loc4`='看来你没有撒谎，阿卡玛。凯尔萨斯的背叛并没有让我感到多么吃惊，我并没有某些家伙所想的那样健忘。你的同族与他有重大的牵连，这让我不得不质疑你的忠诚。', `MaleText_loc5`='看來你沒有撒謊，阿卡瑪。凱爾薩斯的背叛並沒有讓我感到吃驚，我並沒有某些傢伙所想像的那樣健忘。你的同族與他有重大的牽連，這讓我不得不質疑你的忠誠。', `MaleText_loc7`='No siento mentiras en tu voz, Akama. La traición de Kael''thas no me sorprende. No ignoro todo lo que me rodea como algunos piensan. Que uno de los tuyos estuviera involucrado con él pone en duda tu lealtad.' WHERE `ID`=20629;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 잿빛혓바닥 결사단을 폭풍우 요새로 보내서 캘타스 놈이 애지중지하는 생물을 없애라. 알라르라는 불사조 말이다! 너도 놈의 편이 아니라는 걸 확인해야겠다. 배신할 생각은 꿈에도 말아라.', `MaleText_loc4`='将你的灰舌部队派进风暴要塞，去杀掉他最得意的部下，那只名叫奥的凤凰。以此来向我证明你不是他的同党。不要妄图背叛我，破碎者。我们都知道你的灵魂在谁的掌握中！', `MaleText_loc5`='派你的灰舌進入風暴要塞並殺掉他最有價值的財產，一隻叫作歐爾的鳳凰。我必須得知道你不是站在他們那邊的人。別想要背叛我，失落者。我們兩個都很明白是誰佔有你的靈魂!', `MaleText_loc7`='Envía tu Lengua de Ceniza al Castillo de la Tempestad y mata su más preciada posesión, el fénix Al''ar. Debo saber que no estás de su lado. No intentes traicionarme, Tábido. ¡Ambos sabemos a quién pertenece tu alma!' WHERE `ID`=20630;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사방에 우리를 둘러싸고 있는 에테리움들을 조심하시오.', `MaleText_loc4`='提防那些包围我们的复仇军。', `MaleText_loc5`='當心那些包圍我們四方的以太皇族。', `MaleText_loc7`='Cuidado con El Etereum que nos rodea por todas partes.' WHERE `ID`=20631;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 보랏빛 인장을 잃어버렸습니다만 새로 하나 주실 수 있습니까?', `MaleText_loc4`='我把紫罗兰徽记给弄丢了，请再给我一个。', `MaleText_loc5`='我遺失了我的紫羅蘭徽記所以想要一個替代品。', `MaleText_loc7`='He perdido mi sello Violeta y busco otro.', `FemaleText_loc1`='제 보랏빛 인장을 잃어버렸습니다만 새로 하나 주실 수 있나요?', `FemaleText_loc4`='我把紫罗兰徽记给弄丢了，请再给我一个。', `FemaleText_loc5`='我遺失了我的紫羅蘭徽記所以想要一個替代品。', `FemaleText_loc7`='He perdido mi sello Violeta y busco otro.' WHERE `ID`=20632;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내.. 내가 자유의 몸이 되었군! 에테리움들은 내가 그들의 요구를 들어줄 때까지 날 고문하려고 했었지. 당신이 이곳에 오지 못할까 걱정했소이다. 그랬다면 난 그들의 고문에 굴복하고 말았을 테니까 말이오.', `MaleText_loc4`='我……我自由了！复仇军打算折磨我，直到我交出他们所要的东西。若不是你及时赶到，我肯定会屈服于他们的折磨。', `MaleText_loc5`='我...我自由了!以太皇族計畫著要折磨我直到我對他們的要求讓步。我擔心，要是你再不來，我就一定會被屈打成招了。', `MaleText_loc7`='¡Soy... libre! El Etereum planeaba torturarme hasta que obedeciera todos sus mandatos. Si no hubieses aparecido, me temo que habría cedido a su tormento.' WHERE `ID`=20633;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$r|1이여;여;. 이걸 알아 두시오. 이 무덤의 끝에 있는 샤파르의 감금실 내에는 상상할 수조차 없는 힘을 지닌 생물이 쉬고 있소이다. 감금실의 힘이 그 생물을 통제하고 있지. 그 생물을 없애고자 한다면 더 조사를 진행하기 전에 야미르 사령관에게 돌아가야 하오!', `MaleText_loc4`='知道吗，$c，在这座陵墓尽头的沙法尔的房间内，有一个具备强大力量的生物正在休眠。它目前被静止间的力量控制着。如果你想消灭它，就必须先回到阿米尔那里去！', `MaleText_loc5`='看看這個，$r。在這些墓穴盡頭的薩法爾房間內棲息著一隻怪物擁有令人無法想像的力量。藉由靜止密室的力量壓制著。如果你想要消滅它的話，你一定要在你進行更進一步的冒險之前回去找阿密爾。', `MaleText_loc7`='Escucha bien, $r. Dentro de las Cámaras de Shaffar al final de estas tumbas descansa una criatura de inimaginable poder. Está bajo el control de la Cámara de Estasis. ¡Debes volver a Ameer antes de seguir avanzando si quieres destruirla!' WHERE `ID`=20634;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이리 오시오. 내가 그동안 본 것 중 가장 멋진 탈것을 타는 방법에 대해서 알려 주도록 하겠소. 음... 훈련 비용을 감당할 충분한 소지금이 있는 거요?', `MaleText_loc4`='过来，我会教如何骑乘这些坐骑。不过，你……带了足够的钱来付这笔费用吧？', `MaleText_loc5`='過來然後我會讓你見識到前所未見的方式來駕馭這匹優良野獸。我相信，你...有足夠的金錢可以付費吧?', `MaleText_loc7`='Ven y yo te mostraré cómo montar las mejores bestias que jamás hayas visto. Tú... tendrás suficiente oro para pagar por mis servicios... Supongo.', `FemaleText_loc1`='이리 오시오. 내가 그동안 본 것 중 가장 멋진 탈것을 타는 방법에 대해서 알려 주도록 하겠소. 음... 훈련 비용을 감당할 충분한 소지금이 있는 거요?', `FemaleText_loc4`='过来，我会教如何骑乘这些坐骑。不过，你……带了足够的钱来付这笔费用吧？', `FemaleText_loc5`='過來然後我會讓你見識到前所未見的方式來駕馭這匹優良野獸。我相信，你...有足夠的金錢可以付費吧?', `FemaleText_loc7`='Ven y yo te mostraré cómo montar las mejores bestias que jamás hayas visto. Tú... tendrás suficiente oro para pagar por mis servicios... Supongo.' WHERE `ID`=20635;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$c|1이여;여;, 영원의 숲으로 오신 것을 환영합니다. 타이미온과 저는 지금까지 칼날 산맥의 아라코아들을 연구해 왔답니다. 우리는 이곳 아라코아들이 테로카르 숲에 서식하는 그들의 사촌들과 놀라운 차이를 보인다는 사실을 발견했습니다.', `FemaleText_loc4`='欢迎来到常青林，$c。坦莫和我一直在研究刀锋山一带的鸦人，最近，我们发现他们和那些泰罗卡森林的鸦人之间有着一些令人担忧的差别。', `FemaleText_loc5`='歡迎來到永恆樹林，$c。泰姆昂與我已經研究劍刃山脈的阿拉卡有一段時日了，我們也發現了他們和他們在泰洛卡的親戚們具有一些令人擔心的差異性。', `FemaleText_loc7`='Bienvenido a Soto Eterno, $c. Timeon y yo llevamos algún tiempo estudiando a los arakkoa de las Montañas Filospada y hemos encontrado algunas diferencias alarmantes entre ellos y sus primos de Terokkar.' WHERE `ID`=20636;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<아라코아 유령이 손을 뻗어 당신의 얼굴을 만져보지만, 누구인지 알아보지 못한다는 느낌이 듭니다.>$B$B로카람, 너냐?', `MaleText_loc4`='<鸦人的幽灵逐渐接近你，仿佛是在辨认你。但你觉得它似乎总是看不清楚。>$B$B罗卡拉姆，是你吗？', `MaleText_loc5`='<這個阿拉卡鬼魂向你靠過來好像試著要辨認你是誰。你印象中它無法清楚的看見你。>$B$B洛卡拉姆，是你嗎?', `MaleText_loc7`='<El fantasma Arakkoa se acerca a ti como si tratara de identificarte. Tienes la impresión de que no puede verte con claridad.>$B$B¿Rokkaram, eres tú?' WHERE `ID`=20637;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네... 네, 저예요...', `MaleText_loc4`='是的……是的，是我……', `MaleText_loc5`='是的...沒錯，就是我...', `MaleText_loc7`='Sí...sí, soy yo...', `FemaleText_loc1`='네... 네, 저예요...', `FemaleText_loc4`='是的……是的，是我……', `FemaleText_loc5`='是的...沒錯，就是我...', `FemaleText_loc7`='Sí...sí, soy yo...' WHERE `ID`=20638;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미안하다, 얘야... 물어볼 수밖에 없구나. 시력이 예전 같지 않아서 말이지. 대신, 까마귀 신께서는 오랜 수명을 선물하셨지.$B$B머지않아, 네가 내 자리를 물려받을 때가 올 거란다. 내가 알고 있는 모든 걸 너에게 가르쳐 주었다. 내 단 하나 후회가 되는 것은 나에게 신성한 까마귀 경전을 찾을 자격이 있다는 것을 입증하지 못한 것이다.', `MaleText_loc4`='请原谅我质问你，孩子。我的视力已经不如从前了，但是乌鸦之神赐我长生。$B$B不久之后，你就会接替我的位置。我将我所知道的知识都传授给了你。唯一的遗憾就是我没能夺回氏族神圣的乌鸦之书。', `MaleText_loc5`='原諒我對你的質疑，我的兒子。我的眼力已大不如前，不過烏鴉已經祝福我長命百歲了。$B$B<塞可往他的肩膀後看了一眼，就像他要傳達一個秘密一樣。>$B$B很快，就會是你取代我的時候了。我會將我所有的知識傳授給你。我唯一的悔恨就是我無法取回我們神聖的烏鴉聖典來證明我的價值。', `MaleText_loc7`='Perdona que te interrogue, hijo mío. Mi vista ya no es lo que era, pero el Cuervo me ha bendecido con una vida larga.$B$BPronto llegará el momento de que ocupes mi lugar. Te he enseñado todo lo que sé. Tan solo me arrepiento de no haber sido digno de recuperar el sagrado Libro del Cuervo.' WHERE `ID`=20639;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장로님, 그 경전에 대해 좀 더 말씀해 주세요.', `MaleText_loc4`='是的，长者。告诉我关于乌鸦之书的故事吧。', `MaleText_loc5`='是的，長者。告訴我更多關於這本書的事。', `MaleText_loc7`='Sí anciano. Cuéntame más acerca del libro.', `FemaleText_loc1`='장로님, 그 경전에 대해 좀 더 말씀해 주세요.', `FemaleText_loc4`='是的，长者。告诉我关于乌鸦之书的故事吧。', `FemaleText_loc5`='是的，長者。告訴我更多關於這本書的事。', `FemaleText_loc7`='Sí anciano. Cuéntame más acerca del libro.' WHERE `ID`=20640;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스케티스에 있는 반역자 사촌들이 우리에게서 경전을 훔쳐가 조각조각 내서 그들의 초라한 도시에 파묻어버린 이후 충실한 신도들은 수치심 속에 살고 있단다!$B$B내 아들아, 까마귀 신께서 그것을 되찾아오는 자로 너를 지목하시길 빌어라. 얘야, 항상 믿음을 갖고 경전의 말씀을 새기고 예언을 잊지 말려무나. "까마귀 신께서 적들의 꿈속에서 일어나 세상 밖으로 나오시리라."', `MaleText_loc4`='自从斯克提斯的鸦人同胞背信弃义，从我们手中偷走乌鸦之书，打破石板并将碎裂的石板碎片掩埋在他们那肮脏的城市中之后，鸦神真正的信徒便永远地生活在耻辱之中。$B$B祈祷乌鸦之神能挑中你，让你成为夺回神圣书典的英雄吧。孩子，要时刻保持信仰，并永远铭记这条预言：“与乌鸦之神为敌的人们，鸦神会从你们的睡梦中进入这个世界。”', `MaleText_loc5`='忠實的信徒們一直活在羞恥中，自從我們位於司凱堤斯那些背叛的族人從我們身邊偷走聖典，打碎它的石板，並在他們那個卑鄙的城市將碎片燒毀!$B$B祈禱烏鴉將選中你來取回聖典，我的兒子。要有信心並永遠記取預言，「烏鴉重回這個世界將始於敵人之夢。」', `MaleText_loc7`='¡Los verdaderos creyentes hemos vivido avergonzados desde el día que nuestros traidores primos de Skettis nos robaron el libro, rompieron la tablilla y enterraron los fragmentos en su despreciable ciudad!$B$BReza para que el Cuervo te elija para restaurarlo, hijo mío. Ten fe y recuerda la profecía: "De los sueños de sus enemigos surgirá el Cuervo en el mundo"' WHERE `ID`=20641;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그록이 지원군을 찾는다. 조그마한 $r들아, 산으로 가서 피망치 일족 좀 구해줘!', `MaleText_loc4`='葛罗克需要帮助。小$r，快去刀锋山帮助血槌氏族吧！', `MaleText_loc5`='葛羅克尋求幫忙。小$r去山脈那幫助血槌!', `MaleText_loc7`='Grok busca ayuda. ¡$gPequeño:Pequeña; $r ve a las montañas y ayuda al Machacasangre!' WHERE `ID`=20642;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모그도그 만나러 가니?', `MaleText_loc4`='你去找莫戈多格吗？', `MaleText_loc5`='你去見了莫格多克?', `MaleText_loc7`='¿Vas a ver a Mog''dorg?' WHERE `ID`=20643;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 최고의 실력을 갖춘 영웅을 찾고 있네. 피망치 일족은 물론 이 산맥을 거머쥔 그론들의 폭정에 시달리는 모든 오우거를 해방시킬 영웅 말일세.$B$B가능한 모든 것을 배우고 나서 날 다시 찾아오게나. $c|1이여;여;, 때가 올 때까지 이 일은 절대 비밀에 부쳐야 하네. 우리가 몰래 추진하는 일들이 절대로 그론의 귀에 들어가서는 안 되니까...', `MaleText_loc4`='我正在寻找一名技艺超群的英雄。$G他:她;将召集其他人拯救血槌氏族，并从戈隆的残暴统治下解放生活在刀锋山的所有食人魔氏族。$B$B当你了解到更多的知识之后再来找我吧。但是，$c，在此之前请你保持低调，以免被戈隆察觉到我们的动机。', `MaleText_loc5`='我在找尋一個技術絕佳的$g英雄:英雌;。$G他:她;將會召集其他人來解救血槌氏族，還有來自我們古羅迫害者殘暴統治的所有位於這些山脈的巨魔。$B$B等你盡其所能的學完所有事物後回來找我。不過，$c，守住這個秘密免得古羅得到有關我們地下行動的風聲。', `MaleText_loc7`='Busco un $g héroe : heroína; de gran habilidad. $G Él : Ella; reunirá a los demás para salvar al Clan Machacasangre y a todos los ogros de estas montañas de la tiranía de nuestros opresores gronn.$B$BVuelve a mí cuando hayas averiguado todo lo que puedas. Pero, $c, mantén esto en secreto hasta que llegue el momento o los gronn se enterarán de nuestro movimiento clandestino.' WHERE `ID`=20644;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리를 옭아맨 족쇄를 부수고 다시금 자유로운 오우거로 살아가려면 반드시 그룰의 아들들을 없애야만 하네.$B$B우리의 비밀 저항 운동이 성공하려면 조용하지만, 신속하게 모든 일을 처리해야 해.', `MaleText_loc4`='如果我们想摆脱身上的枷锁，再次享受自由的滋味，就必须杀死所有的格鲁尔之子！$B$B但是，我们必须隐秘行动，只有通过秘密的抵抗行动，我们才有机会获得成功。', `MaleText_loc5`='如果我們想要擺脫我們的束縛並再次活得如同自由的巨魔的話就一定要打倒戈魯爾之子!$B$B如果我們的暗中反抗要成功的話，我們就一定要安靜的進行，但是速度要快。', `MaleText_loc7`='¡Los Hijos de Gruul han de ser derrotados si pretendemos librarnos de nuestros grilletes y volver a vivir como ogros libres! $B$BDebemos trabajar silenciosamente pero rápido si queremos que nuestra resistencia clandestina tenga alguna posibilidad de éxito.' WHERE `ID`=20645;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='줄리스 대령이 이 위험천만한 퇴마 의식을 통해서만 구원받을 수 있을 것 같아 걱정이군.', `MaleText_loc4`='要想拯救尤勒斯上校，恐怕只能利用那种危险性很高的仪式——是的，驱魔仪式。', `MaleText_loc5`='我擔心喬渥上校可能只能藉由一種危險的儀式來挽救...一種驅邪儀式。', `MaleText_loc7`='Temo que solo sea posible salvar al Coronel Jules mediante un peligroso ritual: un exorcismo.' WHERE `ID`=20646;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 우리가 준비해야 할 많은 것들을 나와 상의하도록 합시다.', `MaleText_loc4`='告诉我，$n，我们还要准备些什么……', `MaleText_loc5`='跟我談談，$n，我們有很多事情要準備...', `MaleText_loc7`='Habla conmigo, $n, ya que tenemos mucho que preparar...' WHERE `ID`=20647;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그록은 도움이 필요한데... 왜 아무도 안 도와주는 거야?!', `MaleText_loc4`='葛罗克需要帮助！为什么没人帮忙啊？', `MaleText_loc5`='葛羅克需要幫助!為什麼沒人要幫忙?', `MaleText_loc7`='Grok necesitar ayuda. ¿Por qué nadie ayudar?' WHERE `ID`=20648;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도움을 청하려고 주위를 둘러보던 %s|1이;가; 한숨을 쉽니다.', `MaleText_loc4`='%s环顾四周，却发现没有人愿意帮助自己，只得叹了口气。', `MaleText_loc5`='四處尋找協助，%s嘆了口氣。', `MaleText_loc7`='Buscando ayuda, %s suspira' WHERE `ID`=20649;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 일리단 님을 실망시켜서는 안 된다.', `MaleText_loc4`='我们不能辜负背叛者。', `MaleText_loc5`='我們一定不能讓背叛者失望。', `MaleText_loc7`='No debemos defraudar al Traidor.' WHERE `ID`=20650;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곧 우리의 시대가 도래할 것이다!', `MaleText_loc4`='很快，我们的时代就要来了！', `MaleText_loc5`='很快，我們的時代會來臨的!', `MaleText_loc7`='¡Pronto llegará nuestro momento!' WHERE `ID`=20651;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성채에서 연락이 있었나?', `MaleText_loc4`='堡垒那边有消息吗？', `MaleText_loc5`='堡壘那有任何消息嗎?', `MaleText_loc7`='¿Hemos recibido algún contacto de la Ciudadela?' WHERE `ID`=20652;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 돌연변이 오크들의 냄새는 역겹단 말이야.', `MaleText_loc4`='这些变异兽人的味道让我感到恶心。', `MaleText_loc5`='這些突變獸人的味道真讓我覺得噁心。', `MaleText_loc7`='El olor de estos orcos mutantes me repugna.' WHERE `ID`=20653;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오우거는 출입 금지입니다. 당신이 우리 단골을 다 내쫓고 있잖아!', `MaleText_loc4`='食人魔，请离开这里。你正在打扰我们的客户！', `MaleText_loc5`='巨魔，請離開。你打擾到我們的顧客了!', `MaleText_loc7`='Ogro, por favor, márchate.¡Estás molestando a la clientela!' WHERE `ID`=20654;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그록, 다시는 여기 나타나지 마십시오. 이 근처는 얼씬도 말라고 전에도 분명히 경고했을 텐데요...', `MaleText_loc4`='不要再这样了，葛罗克。我跟你说过的，离远点！', `MaleText_loc5`='別又來了，葛羅克。之前不是告訴你離遠一點嗎!', `MaleText_loc7`='Otra vez no, Grok.¡Se te ha dicho que te mantengas alejado!' WHERE `ID`=20655;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그록, 여기서 당장 나가십시오!', `MaleText_loc4`='葛罗克，出去。', `MaleText_loc5`='葛羅克，拿到外面去。', `MaleText_loc7`='Grok, llévalo fuera.' WHERE `ID`=20656;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직도 도와줄 일손을 구하지 못했나요?', `MaleText_loc4`='还没有人帮你吗，食人魔？', `MaleText_loc5`='還沒有人幫忙你嗎，巨魔?', `MaleText_loc7`='¿Aún no te ha ayudado nadie, ogro?' WHERE `ID`=20657;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오우거야, 당장 꺼져라!', `MaleText_loc4`='食人魔，快走开！', `MaleText_loc5`='巨魔，走開!', `MaleText_loc7`='¡Ogro, márchate!' WHERE `ID`=20658;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그록, 전에도 분명히 경고했습니다. 이곳을 떠나십시오!', `MaleText_loc4`='葛罗克，跟你说过多少次了，出去！', `MaleText_loc5`='葛羅克，之前就跟你說過了，到外面去!', `MaleText_loc7`='¡Grok, se te ha dicho que te quedes fuera!' WHERE `ID`=20659;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경비병, 이 오우거가 제 발로 나가지 않겠다면 도시 밖까지 친절히 모셔다 드리도록!', `MaleText_loc4`='卫兵，如果这个食人魔还不离开的话，就把他“护送”出去。', `MaleText_loc5`='守衛，如果巨魔不離開的話，就護送他出去。', `MaleText_loc7`='Guardias, si este ogro no se va, sáquenlo fuera.' WHERE `ID`=20660;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 오우거가 이곳에 다시는 얼씬도 않도록 부드럽게 매만져 주실 분 어디 없으십니까?', `MaleText_loc4`='有人愿意帮帮这个食人魔吗？那样他就不会再回来了。', `MaleText_loc5`='有人可以幫幫這個巨魔讓他不要再回來嗎?', `MaleText_loc7`='Por favor, ¿alguien puede ayudar a este ogro para que no vuelva?' WHERE `ID`=20661;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저리 비키시오, 그록! 그대는 올라갈 수 없소!', `MaleText_loc4`='闪开，葛罗克，你不能去上面。', `MaleText_loc5`='走開，葛羅克，你不能上來。', `MaleText_loc7`='Avanza Grok, no puedes subir.', `FemaleText_loc1`='저런, 딱하기도 해라... 그래도 규정은 규정이니까 저 위로 올려 보낼 수는 없소.', `FemaleText_loc4`='啊，甜心，你知道我不能让你去上面。命令始终是命令。', `FemaleText_loc5`='噢，小甜心，你知道我不能讓你上來那裡的。規矩就是規矩。', `FemaleText_loc7`='¡Oh! cielo, sabes que no puedo dejar que te subas ahí. Las reglas son las reglas.' WHERE `ID`=20662;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 대답은 여전히 "안 돼!"다. 넌 더는 올라갈 수 없다!', `MaleText_loc4`='回答仍然是不，葛罗克。你不能去上面。', `MaleText_loc5`='答案還是不，葛羅克。你不能上來。', `MaleText_loc7`='La respuesta sigue siendo no, Grok. No puedes subir.', `FemaleText_loc1`='여기 얼씬도 말라고 분명히 경고했을 텐데... 썩 꺼져!', `FemaleText_loc4`='我记得我告诉过你，不要到这附近来。走开！', `FemaleText_loc5`='我想我已經跟你說過不要到這裡來。走開!', `FemaleText_loc7`='Creí que te había dicho que no vinieras por aquí. ¡Avanza!' WHERE `ID`=20663;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난쟁이들아, 아무도 칼날 산맥으로 가서 모그도그를 도와주지 않으면 그록 정말 화낸다!', `MaleText_loc4`='要是你们这些小家伙不去刀锋山和莫戈多格谈话，葛罗克会生气的！', `MaleText_loc5`='葛羅克會生氣要是弱小的人不去劍刃山脈跟乾癟的莫格多克談談。', `MaleText_loc7`='¡Grok enfadarse si pequeños endebles no ir a Montañas Filospada a hablar con Mog''dorg!' WHERE `ID`=20664;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적들이 오고 있다! 위치를 사수하라!', `MaleText_loc4`='敌人就在我们眼前！守住你们的阵地！', `MaleText_loc5`='敵人就在我們上方!站好你的位置!', `MaleText_loc7`='¡El enemigo está sobre nosotros!¡Resistid!', `FemaleText_loc1`='적들이 오고 있다! 위치를 사수하라!', `FemaleText_loc4`='敌人就在我们眼前！守住你们的阵地！', `FemaleText_loc5`='敵人就在我們上方!站好你的位置!', `FemaleText_loc7`='¡El enemigo está sobre nosotros!¡Resistid!' WHERE `ID`=20665;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛의 적들은 모두 무릎 꿇으리라!', `MaleText_loc4`='圣光的敌人必须被消灭！', `MaleText_loc5`='聖光的敵人必定會被摧毀!', `MaleText_loc7`='¡Los enemigos de La Luz deben ser derrotados!', `FemaleText_loc1`='빛의 적들은 모두 무릎 꿇으리라!', `FemaleText_loc4`='圣光的敌人必须被消灭！', `FemaleText_loc5`='聖光的敵人必定會被摧毀!', `FemaleText_loc7`='¡Los enemigos de La Luz deben ser derrotados!' WHERE `ID`=20666;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지리를 위해! 샤타르를 위해!', `MaleText_loc4`='为了克希利！为了沙塔尔！', `MaleText_loc5`='為了希瑞!為了薩塔!', `MaleText_loc7`='¡Por Xi''ri!¡Por los Sha’tar!', `FemaleText_loc1`='지리를 위해! 샤타르를 위해!', `FemaleText_loc4`='为了克希利！为了沙塔尔！', `FemaleText_loc5`='為了希瑞!為了薩塔!', `FemaleText_loc7`='¡Por Xi''ri!¡Por los Sha’tar!' WHERE `ID`=20667;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일리다리여, 마지막 숨을 거둘 시간이 멀지 않았다!', `MaleText_loc4`='你们的末日到来了，伊利达雷！', `MaleText_loc5`='你的死期就在眼前了，伊利達瑞!', `MaleText_loc7`='¡Tu fin está cerca Illidari!', `FemaleText_loc1`='일리다리여, 마지막 숨을 거둘 시간이 멀지 않았다!', `FemaleText_loc4`='你们的末日到来了，伊利达雷！', `FemaleText_loc5`='你的死期就在眼前了，伊利達瑞!', `FemaleText_loc7`='¡Tu fin está cerca Illidari!' WHERE `ID`=20668;
