UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이리 오너라, 악마 녀석! 죽음이 널 기다리고 있다!', `MaleText_loc4`='来吧，恶魔！死亡正等待着你！', `MaleText_loc5`='靠近一點，惡魔!等死吧!', `MaleText_loc7`='¡Acércate más demonio!¡La muerte te espera!', `FemaleText_loc1`='이리 오너라, 악마 녀석! 죽음이 널 기다리고 있다!', `FemaleText_loc4`='来吧，恶魔！死亡正等待着你！', `FemaleText_loc5`='靠近一點，惡魔!等死吧!', `FemaleText_loc7`='¡Acércate más demonio!¡La muerte te espera!' WHERE `ID`=20670;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형편없는 녀석... 너의 주인이라는 자가 누리던 영광은 끝났다!', `MaleText_loc4`='可怜虫……你主人的计划破产了！', `MaleText_loc5`='可憐蟲...你的主人氣數已盡!', `MaleText_loc7`='Patético gusano...¡los días de tu amo han terminado!', `FemaleText_loc1`='형편없는 녀석... 너의 주인이라는 자가 누리던 영광은 끝났다!', `FemaleText_loc4`='可怜虫……你主人的计划破产了！', `FemaleText_loc5`='可憐蟲...你的主人氣數已盡!', `FemaleText_loc7`='Patético gusano...¡los días de tu amo han terminado!' WHERE `ID`=20671;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 녀석의 주인에게 전할 전언이 있다, 이 더러운 녀석!', `MaleText_loc4`='我有个消息要带给你们的主人，渣滓！', `MaleText_loc5`='我有訊息通報你的主人，人渣!', `MaleText_loc7`='¡Escoria! Tengo un mensaje para tu amo.', `FemaleText_loc1`='네 녀석의 주인에게 전할 전언이 있다, 이 더러운 녀석!', `FemaleText_loc4`='我有个消息要带给你们的主人，渣滓！', `FemaleText_loc5`='我有訊息通報你的主人，人渣!', `FemaleText_loc7`='¡Escoria! Tengo un mensaje para tu amo.' WHERE `ID`=20672;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 헛것이 보이나? 이렇게 많은 시간이 흘러버렸는데... 진정 자네인가, 로카람?$B$B사이칼을 찾는다면 소용돌이 누각의 서쪽에 있는 수정들 틈을 걷고 있는지 살펴보게. 그는 그곳에 있는 원시적이고 야만적인 존재에 단단히 홀린 듯하네. 어떤 것도 잘못되어 보이진 않지만 말이야.', `MaleText_loc4`='我眼花了吗？我们很久没有见过面了，罗卡拉姆兄弟，真的是你吗？$B$B你在找塞克卡尔？他就在漩涡峰西部的水晶田中。他说自己可以在那里感受到某种原始的、未开化的超自然力量，并为此神魂颠倒；但是在旁人看来，那片水晶田并没有什么异常现象。', `MaleText_loc5`='我的眼睛會欺騙我嗎?那真的是你嗎，洛卡拉姆兄弟，在過了這些時日之後?$B$B如果你要找塞可，他就在漩渦尖塔西側的水晶之間走來走去。他好像專注於那裡一個他稱之作殘酷，原始的鬼魂，雖然好像沒有任何不對勁。', `MaleText_loc7`='¿Acaso me engañan mis ojos? ¿Eres realmente tú, hermano Rokkaram, después de todo este tiempo?$B$BSi estás buscando a Sai''kkal, suele caminar entre los cristales en la zona oeste de La Cumbre del Vórtice. Parece preocupado por algo que él describe como una presencia bruta y primitiva en ese lugar, aunque no he visto nada así.' WHERE `ID`=20673;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 부서지기 시작합니다!', `MaleText_loc4`='%s开始分裂了！', `MaleText_loc5`='%s開始四分五裂!', `MaleText_loc7`='¡%s comienza a partirse en dos!' WHERE `ID`=20674;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 까마귀석이 묻힌 곳을 찾아내려고 땅을 이곳저곳 파헤칩니다.', `MaleText_loc4`='%s一路沿地面探测，寻找着被埋在土下的乌鸦石。', `MaleText_loc5`='%s搜尋埋在地下的烏鴉石', `MaleText_loc7`='%s busca piedras del cuervo enterradas en el suelo' WHERE `ID`=20675;
