UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='목욕할 때가 좀 지났네요. *킁킁* $g오빠:언니;는 저보다 더 심한 것 아니에요?!', `FemaleText_loc4`='我觉得我需要洗个澡。*嗅* 我想你也要洗个澡！', `FemaleText_loc5`='我想我需要洗個澡。*嗅*我覺得你也需要!', `FemaleText_loc7`='Creo que necesito un baño. *sniff* ¡Creo que tú también necesitas uno!' WHERE `ID`=20677;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='타우렌 성기사가 성스러운 빛을 받들면 소기사가 되나요?', `FemaleText_loc4`='一个牛头人圣骑士会是一头圣牛吗？', `FemaleText_loc5`='一個牛頭人聖騎士會是一隻神聖的牛嗎?', `FemaleText_loc7`='¿Podría un paladín Tauren ser un toro bravo?' WHERE `ID`=20678;
