UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='일리단도 사실 맘속은 착한 분인 거 같아요. 그 아찌한테도 엄마가 계셨다면...', `FemaleText_loc4`='我敢打赌伊利丹其实是个好人，他只是需要母爱。', `FemaleText_loc5`='我打賭伊利丹私底下一定是個好人。他只是需要一個媽媽。', `FemaleText_loc7`='Seguro que, en el fondo, Illidan es un tío majo. Solo necesita una mamá.' WHERE `ID`=20680;
