UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='불타는 군단이 그렇게 무섭다면, 그냥 물을 확 끼얹으면 되는 거 아니에요? 그럼 그냥 군단이 되잖아요.', `FemaleText_loc4`='如果燃烧军团是这么大的麻烦，为什么就不能给他们浇些水呢？那么他们就只好停止燃烧了。', `FemaleText_loc5`='如果燃燒軍團是這樣一個問題，為什麼不用水倒在他們身上?那麼他們就只能是軍團了。', `FemaleText_loc7`='Si la Legión Ardiente es un problema tan grande, ¿por qué no les echamos agua? Así solo serían una legión' WHERE `ID`=20686;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$g오빠:언니;는 그렇게 많이 먹는데도 어떻게 살이 안 찌는 거예요?', `FemaleText_loc4`='你为什么吃这么多也不会胖？', `FemaleText_loc5`='你如何吃吃喝喝這麼多，但卻不會發胖呀?', `FemaleText_loc7`='¿Cómo lo haces para comer y beber tanto y no engordar?' WHERE `ID`=20687;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='음, $g오빠:언니;, 궁금한 게 있는데요. 밤이 돼서 나루 님이 졸리면요, 그 광채를 끄고 주무시나요?', `FemaleText_loc4`='纳鲁睡觉的时候是不是要把圣光关掉的？', `FemaleText_loc5`='那魯想要睡覺時會關掉聖光嗎?', `FemaleText_loc7`='¿Los naaru apagan la luz cuando quieren dormir?' WHERE `ID`=20688;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 잠시 당신을 쳐다보더니 따라오라는 듯한 날갯짓을 합니다.', `MaleText_loc4`='%s默默注视了你片刻，然后示意你跟着。', `MaleText_loc5`='%s盯著你看了幾秒，然後示意你跟隨著他走。', `MaleText_loc7`='%s te mira un instante y te indica que le sigas.' WHERE `ID`=20689;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='헤헤, 내가 너무 가까이 다가갔나 봐. 걱정하지 마세요. 전 괜찮으니까!', `FemaleText_loc4`='呵呵，我靠得有些近。不用担心，我很好。', `FemaleText_loc5`='嘿，我有點太靠近了。別擔心，我很好。', `FemaleText_loc7`='Je, me he acercado un poco demasiado. No te preocupes, estoy bien.' WHERE `ID`=20690;
