UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위험을 감지한 %s|1이;가; 도망칩니다.', `MaleText_loc4`='%s感觉到了危险，迅速逃跑了。', `MaleText_loc5`='%s感覺到危險並逃走。', `MaleText_loc7`='%s percibe el peligro y huye.' WHERE `ID`=20692;
