UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야마르 사령관님, 하라매드의 눈을 잃어버려서 새로 하나 얻고자 합니다.', `MaleText_loc4`='我弄丢了哈拉迈德之眼，能再给我一个吗，阿米尔？', `MaleText_loc5`='阿密爾，我失去了哈拉瑪德之眼並想要一個新的。', `MaleText_loc7`='He perdido el ojo de Haramad y necesito un repuesto, Ameer.', `FemaleText_loc1`='야마르 사령관님, 하라매드의 눈을 잃어버려서 새로 하나 얻고자 합니다.', `FemaleText_loc4`='我弄丢了哈拉迈德之眼，能再给我一个吗，阿米尔？', `FemaleText_loc5`='阿密爾，我失去了哈拉瑪德之眼並想要一個新的。', `FemaleText_loc7`='He perdido el ojo de Haramad y necesito un repuesto, Ameer.' WHERE `ID`=20694;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 대규모의 순화 마법을 시전하기 시작합니다.', `MaleText_loc4`='%s开始吟唱一个非常圣洁的法术。', `MaleText_loc5`='%s開始引導一種無限純潔的法術。', `MaleText_loc7`='%s comienza a canalizar un hechizo de pureza inmensa.' WHERE `ID`=20695;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='점술가 길드의 용사들이여, 앞으로 나아가라! 일리단의 추종자들에게 우리의 힘을 보여주자!', `FemaleText_loc4`='前进，占星者！让伊利丹的侍从们见识一下我们的厉害！', `FemaleText_loc5`='往前，占卜者!讓伊利丹的僕人看看我們的武器有多堅韌!', `FemaleText_loc7`='¡Adelante Arúspices! ¡Mostrad a los lacayos de Illidan el genio de nuestro acero!' WHERE `ID`=20696;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='야수를 다루는 방법에 대해서 한두 가지는 아는 것 같지만 말입니다, 하늘을 나는 녀석을 다뤄본 적이 있나요? 우리 와일드해머 드워프들은 누구에게도 뒤지지 않게 하늘을 나는 법을 알고 있지요. 당신 꽤나 기개가 있는 친구이니 약간의 수업료만 내신다면, 제가 하늘을 나는 좋은 방법을 정확하게 알려드리겠습니다.', `FemaleText_loc4`='你也许了解一点点驾驭走兽的技巧，但是你有乘坐飞禽自由飞翔的经历吗？蛮锤矮人懂得如何驯养最好的飞行坐骑。如果你有胆的话，只需付一笔小钱，我就教给你这项技能。', `FemaleText_loc5`='你也許在對待動物方面有一兩把刷子，不過你曾經到過天上嗎?我們蠻錘們知道如何有效地駕馭風。如果你有勇氣的話，只要一點點的費用，我將會好好的訓練你。', `FemaleText_loc7`='Puede que sepas un par de cosas acerca de montar animales pero ¿has despegado alguna vez? Los Martillo Salvaje sabemos como cabalgar el viento con los mejores. Si te atreves, te enseñaré como Dios manda por un módico precio.' WHERE `ID`=20697;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와일드해머를 생각하면 뭐가 생각나나, 응? 자네가 사리분별을 할 줄 아는 친구라면 그리핀 기수가 생각나겠지! 어둠달 골짜기에 맹금의 봉우리가 없긴 하지만 우린 아직 좋은 재고품이 있지. 그래, 좋은 재고 말이야. 내 예쁜 그리핀들을 쭉 둘러보고 자네의 눈길을 끄는 게 있는지 보라고!', `MaleText_loc4`='提到蛮锤氏族时你会想到什么呢？当然是狮鹫骑士啦！影月谷虽说不是鹰巢山，但我们的狮鹫数量依然很充足，嗯，非常充足。瞧瞧那些美丽的小宝贝儿，你看上哪一只了呀？', `MaleText_loc5`='當你想到蠻錘時你會聯想到什麼呢，嗯?獅鷲獸駕駛，如果你還有印象的話!影月不是鷹巢山，不過我們仍然有好貨色可以提供給你，是的，好貨色喔。看一看我的小美人們並看看你挑中當中的哪一隻吧!', `MaleText_loc7`='¿Qué es lo primero que te viene en mente cuando piensas en los Martillo Salvaje?¡Jinetes de Grifos si estás en tus cabales! Sombraluna no es Pico Nidal, pero también tenemos buenas mercancías para ti, eso es, buenas mercancías. ¡Echa un vistazo a mis bellezas a ver si alguna te llama la atención!' WHERE `ID`=20698;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='브룬, 당신이 파는 그리핀을 보여 주십시오.', `MaleText_loc4`='让我看看你的狮鹫，拉瑟尔。', `MaleText_loc5`='讓我看看你的獅鷲獸，布朗恩。', `MaleText_loc7`='Muéstrame tus grifos, Brunn.', `FemaleText_loc1`='브룬, 당신이 파는 그리핀을 보여 주세요.', `FemaleText_loc4`='让我看看你的狮鹫，拉瑟尔。', `FemaleText_loc5`='讓我看看你的獅鷲獸，布朗恩。', `FemaleText_loc7`='Muéstrame tus grifos, Brunn.' WHERE `ID`=20699;
