UPDATE `locales_broadcast_text` SET `MaleText_loc1`='처량한 녀석들. 감히 일리단 님의 사원을 공격하려 했느냐? 좋다, 네 무덤으로 만들어주마!', `MaleText_loc4`='可怜的家伙，你们胆敢进攻伊利丹大人的神殿？好吧，我会让这里变成你们的墓地！', `MaleText_loc5`='可鄙的小人。你膽敢侵犯伊利丹的神廟?很好，我會讓此成為你的死亡之床!', `MaleText_loc7`='Lamentables desdichados. ¿Osan asaltar el templo de Illidan? Muy bien ¡que sea su lecho de muerte!' WHERE `ID`=20719;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그래요. 당신이 이겼다고! 항복!!! 해치지만 마세요!', `FemaleText_loc4`='好吧，你赢了！我投降！不要伤害我！', `FemaleText_loc5`='好吧，你贏了!我投降!只要不要傷害我!', `FemaleText_loc7`='Vale, ¡tú ganas! ¡Me rindo! ¡Pero no me hagas daño!' WHERE `ID`=20720;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='헤헤, 성난남녘 월장석은 내 손안에 있지롱! 날 어쩌지는 못할 거야. 영원히!', `FemaleText_loc4`='看到吗？我得到了南国之怒月亮石，而你无能为力。再见！', `FemaleText_loc5`='瞧?我已經拿到怒水河月亮石了，而你對此無能為力。再見!', `FemaleText_loc7`='¿Ves? Tengo la piedra lunar de Furia del Sur y no hay nada que puedas hacer. ¡Adiós!' WHERE `ID`=20721;
