UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크르릉! 네 영혼을 조각조각 내어 먼지로 갈아 버리리라!', `MaleText_loc4`='啊！我要撕碎你的灵魂！', `MaleText_loc5`='啊哈!我將要撕裂你的靈魂並把它磨成塵末!', `MaleText_loc7`='¡Argh! ¡Te arrancaré el alma y la convertiré en polvo!' WHERE `ID`=20726;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='약하구나, 작은 벌레 같은 녀석들! 네 녀석들의 영혼은 삼킬 가치가 없겠구나...', `MaleText_loc4`='太弱了，小虫子！你的灵魂还不够塞牙缝呢……', `MaleText_loc5`='太弱了，小蟲子們!你們的靈魂不值得一食...', `MaleText_loc7`='¡Débiles insectos inmundos! No vale la pena engullir sus almas...' WHERE `ID`=20727;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정 원한다면 입맞춤을 허락하겠습니다. 남들 보기 전에 얼른!', `MaleText_loc4`='如果你愿意的话，可以吻我，快来吧。', `MaleText_loc5`='如果你喜歡的話你可以親吻我，不過動作要快。', `MaleText_loc7`='Puedes besarme si quieres, pero hazlo rápido.', `FemaleText_loc1`='정 원한다면 입맞춤을 허락할게요. 남들 보기 전에 얼른!', `FemaleText_loc4`='如果你愿意的话，可以吻我，快来吧。', `FemaleText_loc5`='如果你喜歡的話你可以親吻我，不過動作要快。', `FemaleText_loc7`='Puedes besarme si quieres, pero hazlo rápido.' WHERE `ID`=20728;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불꽃놀이를 구경할 다음 기회를 절대 놓치지 마시오! 오후 6시부터 시작해서 매시간 장관이 펼쳐진다오!', `MaleText_loc4`='下次烟火表演的时候你一定要来这里看哦！下午6点开始，每个准点的时刻都会有表演哦！', `MaleText_loc5`='確定你有為了下一場煙火秀到處張貼佈告!晚下6點開始，每個小時整點一次!', `MaleText_loc7`='¡Asegúrate de estar por aquí para el siguiente espectáculo de pirotecnia! Son cada hora a partir de las 6pm.', `FemaleText_loc1`='불꽃놀이를 구경할 다음 기회를 절대 놓치지 마시오! 오후 6시부터 시작해서 매시간 장관이 펼쳐진다오!', `FemaleText_loc4`='下次烟火表演的时候你一定要来这里看哦！下午6点开始，每个准点的时刻都会有表演哦！', `FemaleText_loc5`='確定你有為了下一場煙火秀到處張貼佈告!晚下6點開始，每個小時整點一次!', `FemaleText_loc7`='¡Asegúrate de estar por aquí para el siguiente espectáculo de pirotecnia! Son cada hora a partir de las 6pm.' WHERE `ID`=20729;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='친구여, 편히 앉아 목을 축이시오. 낭떠러지 같은 데만 피해서 마시면 뭐, 별 탈 있겠소?!', `MaleText_loc4`='来喝一杯，朋友。只是在喝酒时小心别摔下去。', `MaleText_loc5`='朋友自己找點喝的吧。只要記得在喝的時候離暗礁遠一點就好了。', `MaleText_loc7`='Sírvete algo de beber. Tan solo asegúrate de estar lejos del alféizar mientras bebes.', `FemaleText_loc1`='친구여, 편히 앉아 목을 축이시오. 낭떠러지 같은 데만 피해서 마시면 뭐, 별 탈 있겠소?!', `FemaleText_loc4`='来喝一杯，朋友。只是在喝酒时小心别摔下去。', `FemaleText_loc5`='朋友自己找點喝的吧。只要記得在喝的時候離暗礁遠一點就好了。', `FemaleText_loc7`='Sírvete algo de beber. Tan solo asegúrate de estar lejos del alféizar mientras bebes.' WHERE `ID`=20730;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불꽃놀이가 끝나면 술잔들이 차려질 거요. 그러면 형제자매들과 축배를 올립시다!', `MaleText_loc4`='美酒将在烟火表演之后拿出来。我们可以在那时为朋友们干杯！', `MaleText_loc5`='煙火後，將會推出高腳杯。我們接著將會對我們的同伴舉杯!', `MaleText_loc7`='Después de los fuegos artificiales se sacarán las copas. ¡Entonces brindaremos por nuestros camaradas!', `FemaleText_loc1`='불꽃놀이가 끝나면 술잔들이 차려질 거요. 그러면 형제자매들과 축배를 올립시다!', `FemaleText_loc4`='美酒将在烟火表演之后拿出来。我们可以在那时为朋友们干杯！', `FemaleText_loc5`='煙火後，將會推出高腳杯。我們接著將會對我們的同伴舉杯!', `FemaleText_loc7`='Después de los fuegos artificiales se sacarán las copas. ¡Entonces brindaremos por nuestros camaradas!' WHERE `ID`=20731;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='축제를 즐깁시다!', `MaleText_loc4`='尽情享受庆典吧！', `MaleText_loc5`='好好慶祝吧!', `MaleText_loc7`='¡Disfrutad de los festejos!', `FemaleText_loc1`='축제를 즐깁시다!', `FemaleText_loc4`='尽情享受庆典吧！', `FemaleText_loc5`='好好慶祝吧!', `FemaleText_loc7`='¡Disfrutad de los festejos!' WHERE `ID`=20732;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오후 6시부터 시작해서 매시간, 이 도시에서 불꽃놀이의 장관이 펼쳐진답니다.', `MaleText_loc4`='从下午6点开始，每个准点的时刻，城里都会有烟火表演哦！', `MaleText_loc5`='下午6點開使，城裡每個小時整點都會有一場異常盛大的煙火表演。', `MaleText_loc7`='A partir de las 6pm, habrá un espectáculo de fuegos artificiales cada hora.', `FemaleText_loc1`='오후 6시부터 시작해서 매시간, 이 도시에서 불꽃놀이의 장관이 펼쳐진답니다.', `FemaleText_loc4`='从下午6点开始，每个准点的时刻，城里都会有烟火表演哦！', `FemaleText_loc5`='下午6點開使，城裡每個小時整點都會有一場異常盛大的煙火表演。', `FemaleText_loc7`='A partir de las 6pm, habrá un espectáculo de fuegos artificiales cada hora.' WHERE `ID`=20733;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='술통 안에 기가 막힌 음료가 들었습니다. $c|1이여;여;, 쭉 들이켜세요!', `MaleText_loc4`='小桶里的酒太棒了。干杯，$c！', `MaleText_loc5`='桶裡的飲料是神聖的。喝吧，$c!', `MaleText_loc7`='La bebida de los barriles es divina. ¡Bebe, $c!', `FemaleText_loc1`='술통 안에 기가 막힌 음료가 들었습니다. $c|1이여;여;, 쭉 들이켜세요!', `FemaleText_loc4`='小桶里的酒太棒了。干杯，$c！', `FemaleText_loc5`='桶裡的飲料是神聖的。喝吧，$c!', `FemaleText_loc7`='La bebida de los barriles es divina. ¡Bebe, $c!' WHERE `ID`=20734;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불꽃놀이가 끝난 후 술잔이 차려지면 축배를 올립시다!', `MaleText_loc4`='在烟火表演以后，他们就会拿出美酒，这样我们就能好好干一杯了！', `MaleText_loc5`='煙火之後，他們將會推出高腳杯所以我們就能舉杯慶祝!', `MaleText_loc7`='¡Después de los fuegos artificiales sacarán las copas para que podamos brindar!', `FemaleText_loc1`='불꽃놀이가 끝난 후 술잔이 차려지면 축배를 올립시다!', `FemaleText_loc4`='在烟火表演以后，他们就会拿出美酒，这样我们就能好好干一杯了！', `FemaleText_loc5`='煙火之後，他們將會推出高腳杯所以我們就能舉杯慶祝!', `FemaleText_loc7`='¡Después de los fuegos artificiales sacarán las copas para que podamos brindar!' WHERE `ID`=20735;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋았어, 잔치가 시작됐군!', `MaleText_loc4`='太棒了，宴会时间到了！', `MaleText_loc5`='好極了，派對的時間到了!', `MaleText_loc7`='¡Genial, es la hora de la fiesta!', `FemaleText_loc1`='좋았어, 잔치가 시작됐군!', `FemaleText_loc4`='太棒了，宴会时间到了！', `FemaleText_loc5`='好極了，派對的時間到了!', `FemaleText_loc7`='¡Genial, es la hora de la fiesta!' WHERE `ID`=20736;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 침묵을 지키며 결정을 내리는 동안 조용한 긴장감이 주위의 샤타르 군대에게 드리워집니다.', `MaleText_loc4`='%s一言不发，心中权衡着要做出怎样的抉择。站在他旁边的沙塔尔军队鸦雀无声，空气中弥漫着紧张的气氛……', `MaleText_loc5`='當希瑞做決定時，%s陷入了沉默且附近的薩塔軍隊籠罩在安靜的緊張中。', `MaleText_loc7`='%s se queda callado y una tensión silenciosa cae sobre las cercanas tropas Sha’tar, al tiempo que Xi''ri toma una decisión.' WHERE `ID`=20737;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이리 가까이 오너라, 아가야. 나는 물론이고 $n 님은 절대 널 해치지 않아.', `FemaleText_loc4`='靠近点，年轻人。完全不用害怕我和$n。', `FemaleText_loc5`='靠近一點，年輕人。沒什麼好怕我或$n的。', `FemaleText_loc7`='Acércate más, joven. No hay nada que temer en mí ni en $n.' WHERE `ID`=20738;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 조심스럽게 관찰자 엘라이라 곁으로 날아갑니다.', `MaleText_loc4`='%s谨慎地走近观察者艾莱亚。', `MaleText_loc5`='%s小心的接近看守者艾雷雅。', `MaleText_loc7`='%s se aproxima con cautela a la Vigía Elaira.' WHERE `ID`=20739;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님의 중요한 임무를 돕도록 내가 널 훈련시킬 거란다. 성공하면 자유롭게 풀어줄 테니까 집으로 돌아가렴.', `FemaleText_loc4`='为了帮助$n完成一个非常重要的任务，我要训练你一下。然后，我保证会让你重获自由。', `FemaleText_loc5`='我打算培養你去協助$n每一次重要的任務。在那之後，我承諾你將會獲得自己回到家裡去。', `FemaleText_loc7`='Voy a entrenarte para ayudar a $n con una tarea muy importante. Después de eso, te prometo que podrás volver a casa.' WHERE `ID`=20740;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뽐내기만 좋아하는 멍청이들의 허술하기 짝이 없는 방어로군. 지리, 내 직접 너를 없애주리라!', `MaleText_loc4`='就凭你这副可怜虫的模样还敢高谈阔论什么守护圣光？蠢货！克希利，我要消灭你！', `MaleText_loc5`='一股來自因聖光而自我膨脹的傻瓜的可悲防禦。希瑞，我將會親自毀了你!', `MaleText_loc7`='Una miserable defensa de los tontos inflados de luz. ¡Xi''ri, te consumiré yo mismo!' WHERE `ID`=20741;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금이다, 마이에브. 복수의 한을 풀어라!', `MaleText_loc4`='时机到了，玛维！释放你的怒火吧！', `MaleText_loc5`='時機到了，瑪翼夫!釋放你的憤怒!', `MaleText_loc7`='¡Es el momento Maiev! ¡Desata tu furia!' WHERE `ID`=20742;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='수년간 이 순간만을 기다려 왔노라. 일리단과 그의 졸개들은 파멸을 맞으리라!', `FemaleText_loc4`='这一天我已经等待许多年了！伊利丹和他的走狗都将彻底被毁灭！', `FemaleText_loc5`='這一天我已經等待了許多年了﹗伊利丹和他的走狗都將徹底被毀滅﹗', `FemaleText_loc7`='Llevo años esperando este momento. ¡Illidan y sus perritos falderos serán destruidos!' WHERE `ID`=20743;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리를 본 자는 다 없앤다... 일리단의 귀에 들어가선 안 돼.', `MaleText_loc4`='把所有看到我们的人都杀掉……一定不能让伊利丹得知我们的到来！', `MaleText_loc5`='把所有看到我們的人都殺掉!一定不能讓伊利丹得知我們的到來。', `MaleText_loc7`='Maten a todo el que nos vea... Illidan no debe enterarse.' WHERE `ID`=20744;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아카마, 너의 운명은 결정되었다. 주인님께서 너의 배신을 알게 되시리라!', `MaleText_loc4`='你的死期就要到了，阿卡玛。主人马上就会得知你的背叛！', `MaleText_loc5`='阿卡瑪，你已經選擇了你的命運!主人將會得知你的背叛!', `MaleText_loc7`='Has sellado tu destino Akama. ¡El maestro tendrá noticias de tu traición!' WHERE `ID`=20745;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 이 아카마는 그 누구의 종도 아니다!', `MaleText_loc4`='阿卡玛没有主人了。再也没有了。', `MaleText_loc5`='阿卡瑪沒有主人了。再也沒有了。', `MaleText_loc7`='Akama no tiene amo. Ya no.' WHERE `ID`=20746;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아카마가 바가스의 마지막 말에 귀를 기울이자 %s|1이;가; 조심스럽게 어둠 속으로 숨어듭니다.', `FemaleText_loc4`='趁阿卡玛专注地听着瓦加斯的遗言时，%s偷偷躲到了隐蔽之处。', `FemaleText_loc5`='%s在阿卡瑪的注意力被瓦卡斯的臨死之言轉移時謹慎地悄悄隱入陰影中。', `FemaleText_loc7`='%s se oculta discretamente entre las sombras mientras la atención de Akama se dirige a las últimas palabras de Vagath.' WHERE `ID`=20747;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 계획은 이미 위험에 처했다. 마이에브가 그녀의 방식으로 일을 처리하고자 결정 한 것 같군.', `MaleText_loc4`='我们的计划早已危在旦夕。好像玛维决定以她自己的方式来做事。', `MaleText_loc5`='我們的計畫陷入危險了。瑪翼夫好像決定要以自己的方式來行動。', `MaleText_loc7`='Nuestro plan ya peligra. Parece que Maiev ha decidido hacer las cosas a su manera.' WHERE `ID`=20748;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 사원의 남쪽 벽의 갈라진 틈으로 시선을 옮깁니다.', `MaleText_loc4`='%s的注意力转移到了神殿南墙的一道裂缝上。', `MaleText_loc5`='%s的注意力被神廟南面的牆所發出的爆裂聲吸引。', `MaleText_loc7`='La atención de %s se dirige a una grieta en la pared sur del templo.' WHERE `ID`=20749;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마이에브가 함께하건 아니건 우리는 강행해야 한다! 사원 안으로! 어서 움직여라!', `MaleText_loc4`='无论玛维是不是和我们在一起，我们都必须继续。进去！快点！', `MaleText_loc5`='不管有沒有瑪翼夫，我們都必須繼續。裡面!', `MaleText_loc7`='Debemos continuar con o sin Maiev. ¡Dentro! ¡Rápido!' WHERE `ID`=20750;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네 도움이 필요하면 호루라기를 불게. 동쪽으로, 스케티스로 날아가려무나. 그곳에서 $n의 신호를 기다리렴.', `FemaleText_loc4`='当我们需要你时就会发出号令。飞去东方，到斯克提斯去，在那里等待着$n的信号。', `FemaleText_loc5`='在你需要的時候你將會聽到信號聲。往東飛去，到司凱堤斯，並在那等待$n的信號。', `FemaleText_loc7`='Cuando hagas falta, oirás la llamada. Vuela hacia el este, a Skettis, y espera la señal de $n.' WHERE `ID`=20751;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='새매야, 정말 고맙구나. 네가 없었으면 우린 몇 년이고 까마귀 경전을 찾느라 헤맸을지도 몰라. 이제 나그란드에 있는 네 집으로 돌아가거라.', `FemaleText_loc4`='年轻的麻鹰，如果没有你，我们恐怕要花上几年的时间才能找到乌鸦之书。带着我们的感激返回纳格兰吧。', `FemaleText_loc5`='年輕的雀鷹，沒有你，尋找烏鴉聖典的工作將會花費好幾年。帶著我們的感謝回到你位於納葛蘭的家。', `FemaleText_loc7`='Nos habría llevado años encontrar el Libro del Cuervo sin ti, joven gavilán. Regresa con nuestra gratitud a tu hogar en Nagrand.' WHERE `ID`=20752;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이거야! 진짜 까마귀 경전을 우리 손에 넣었네요!', `FemaleText_loc4`='这就是了！这就是真正的……乌鸦之书！', `FemaleText_loc5`='就是這個!真的就是這個 - 烏鴉聖典!', `FemaleText_loc7`='¡Este es! ¡Este es realmente – el Libro del Cuervo!' WHERE `ID`=20753;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타락의 향연이 끝이 났다! 마그테리돈이 $n|1과;와; $g그:그녀;의 동료가 보여준 무용 앞에 무릎을 꿇고 만 것이다! 얼라이언스의 강대함이 비로소 증명되었다. 지옥의 군주 사령관이 패배했다!', `MaleText_loc4`='堕落与腐化的盛宴已经不复存在了！玛瑟里顿在$n和$g他:她;的伙伴们面前倒下了！它的灭亡见证了联盟力量的伟大！一个深渊领主被消灭了！', `MaleText_loc5`='不會再有墮落的享受!瑪瑟里頓已經在和英勇的$n以及$g他的:她的; 同伴們的戰鬥中被打敗了!見證聯盟的力量!深淵領主指揮官被消滅了!', `MaleText_loc7`='¡El festín de la corrupción ha sido eliminado! ¡Magtheridon ha sucumbido a la destreza en batalla de $n y sus aliados! ¡Observad el poder de la Alianza! ¡Un comandante señor del foso ha sido destruido!' WHERE `ID`=20754;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 형제와 자매들이여, 듣거라! 우리 적의 시대에 종지부가 찍혔다! 우리는 남아 있는 타락한 오크들을 물리쳐야만 한다! 쥐새끼와 같은 그 오크들을 모조리 없애도록 하라! 로서의 후예로서의 사명감을 가지고 나아가라!', `MaleText_loc4`='兄弟们，姐妹们！敌人的末日降临了！我们必须打击剩余的邪兽人！把他们像虫子那样消灭掉！在洛萨之子的庇护下继续战斗吧！', `MaleText_loc5`='備戰的兄弟和姐妹們聽我說!我們敵人的末日到了!我們必須擊倒剩下的魔獄獸人!把他們像害蟲一樣終結掉!帶著洛薩之子的恩惠和你一起吧!', `MaleText_loc7`='¡Escúchenme hermanos y hermanas en la batalla! ¡El tiempo de nuestros enemigos llega a su fin! ¡Extermínenlos como las alimañas que son! ¡Lleven con ustedes la gracia de los hijos de Lothar!' WHERE `ID`=20755;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기 다 적혀 있군요... 어떻게 까마귀 신의 추종자들이 까마귀 신에 저항하는 정령들을 사로잡아서 돌로 된 제단 안에 영원히 가뒀는지 이제 알겠어요! 이 경전에는 까마귀 신의 이름도 나와 있어요! ''안주''로군요! 그 신의 이름은 역사 속에 묻혀 사라졌다고 생각했는데...', `FemaleText_loc4`='一切都真相大白了……乌鸦之神的追随者将敌人的灵魂永久地禁锢在石像中，以此俘获和制服他们。石板甚至提到了乌鸦之神的名字——安苏。我一直以为他的名字早已湮没在历史的长河中！', `FemaleText_loc5`='都在這裡...烏鴉的追隨者如何被抓到以及被敵人之靈所囚禁，將他們永遠的困在石頭形態中!這個石板甚至還提到烏鴉神的名字 - 安祖。我以為它已經消失在歷史中了!', `FemaleText_loc7`='¡Aquí está todo...el modo en que los seguidores del Cuervo capturaron y dominaron los espíritus rivales, atrapándolos para siempre en monumentos de piedra ocultos! La tablilla también menciona el nombre del dios Cuervo: Anzu. ¡Creí que esto se había perdido para siempre!' WHERE `ID`=20756;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='또 흥미로운 내용이 있군요. 피로 얼룩진 전투와 까마귀 신의 몰락에 대한 설명이 끝나고 예언이 나와요. 내용인즉슨, 안주가 자신의 재림을 저지하려는 적들의 꿈속에 나타나 괴롭힐 거라네요.', `FemaleText_loc4`='石板上还记载着别的信息。在一段血腥战斗和乌鸦之神落败的描述之后，有一个预言：安苏将在敌人的梦境中出现，扭曲他们的意志，以重返这个世界……', `FemaleText_loc5`='這裡還有其他的東西。在一場血淋淋的戰鬥及烏鴉族陷落的描述之後，有一道預言。安祖將會棲身於他的敵人夢中，扭曲他們以回到這個世界...', `FemaleText_loc7`='Hay algo más aquí. Después de la descripción de una sangrienta batalla y de la caída del Cuervo hay una profecía. Anzu atormentará los sueños de sus enemigos, distorsionándolos para provocar su vuelta a este mundo...' WHERE `ID`=20757;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='예상대로 이 경전에서 필요한 정보를 얻어냈습니다. 놈이 에메랄드의 꿈에 더 피해를 주기 전에, 이 정보를 이용해 안주를 끌어내 쓰러뜨려야 합니다!', `FemaleText_loc4`='石板应证了我先前的猜想。我们必须利用这条信息，在安苏对翡翠梦境造成更大的破坏之前，将他召唤到这个世界中，然后击败他！', `FemaleText_loc5`='就跟我想的一樣，這塊石板提供了我們需要的證據。如今，我們必須在他對翡翠夢境造成更大傷害前利用這個資訊來引出並打敗這個安祖!', `FemaleText_loc7`='Como yo pensaba, la tablilla contiene la confirmación que necesitamos. ¡Ahora tenemos que usar esta información para vencer a Anzu antes de que pueda hacer más daño al Sueño Esmeralda!' WHERE `ID`=20758;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 까마귀석을 찾는 일에 도움을 준 새매에게 인사합니다.', `FemaleText_loc4`='%s向帮忙确定乌鸦石位置的麻鹰致谢。', `FemaleText_loc5`='%s對幫忙找出烏鴉石的雀鷹打招呼。', `FemaleText_loc7`='%s saluda al gavilán que ayudó a encontrar las Piedras del Cuervo.' WHERE `ID`=20759;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구원자들이여, 나아가라! 우리의 신성한 사원에서 저 악마들을 몰아내라!', `MaleText_loc4`='前进，守备官！把这些恶魔从我们圣洁的神殿里赶出来！', `MaleText_loc5`='復仇者們，前進!把這些惡魔從我們神聖的神廟中趕走!', `MaleText_loc7`='¡Adelante vindicadores! ¡Echad a estos demonios de nuestro templo sagrado!' WHERE `ID`=20761;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 이 아웃랜드를 달리는 녀석들을 다루는 법을 알고 있는 것 같군. 하지만 자네가 날고 싶다면 말이야, 훈련과 헌신은 물론이고 돈도 좀 필요할 것이야. 자네 돈 좀 있지 않나?', `MaleText_loc4`='你似乎懂得如何驾驭野兽在地面行走，但是如果你想要在天空翱翔的话，就需要经过刻苦的训练，当然还需要金币。你身上有金币的，对吧？', `MaleText_loc5`='你看起來好像對你周遭的陸行性動物很有一套的樣子，不過如果你想要飛起，就需要訓練及專心一致。還有金錢。你有金錢，對吧?', `MaleText_loc7`='Parece que sabes manejarte con una bestia que corre por la tierra pero si quieres mejorar, necesitarás entrenamiento y dedicación. Y oro. Tienes oro, ¿verdad?' WHERE `ID`=20762;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='튼실한 녀석들이죠, 그렇죠? 이곳에서 우리가 키우는 와이번들은 드레노어의 위험한 혹한의 날씨에도 견딜 수 있도록 훈련되었답니다. 이 와이번들에게서 믿음과 강한 체력을 느끼실 수 있을 겁니다.', `FemaleText_loc4`='瞧这些漂亮的野兽。我们在这里饲养双足飞龙，并训练这些既可靠又勇敢的野兽适应德拉诺世界严酷的天气环境。', `FemaleText_loc5`='很棒的動物，對吧?我們這裡養的翼龍都是訓練來面對德拉諾最猛烈及最奇怪的天氣狀況。你會發現他們很可靠且堅強。', `FemaleText_loc7`='Son buenas bestias, ¿verdad? Los dracoleones que criamos aquí están entrenados para soportar las condiciones climatológicas extremas y duras de Draenor. Verás que son fiables y robustos.' WHERE `ID`=20763;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다마, 와이번들을 보여주세요.', `MaleText_loc4`='让我看看你的双足飞龙，达玛。', `MaleText_loc5`='讓我看看那些翼龍，達瑪。', `MaleText_loc7`='Déjame ver los dracoleones, Dama', `FemaleText_loc1`='다마, 와이번들을 보여주세요.', `FemaleText_loc4`='让我看看你的双足飞龙，达玛。', `FemaleText_loc5`='讓我看看那些翼龍，達瑪。', `FemaleText_loc7`='Déjame ver los dracoleones, Dama' WHERE `ID`=20764;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지옥불 성채는 우리 것이다! 일리단 휘하에 있던 타락한 오크 군대의 본거지가 사라졌다! $n|1과;와; $g그:그녀;의 친구들이 마그테리돈을 쓰러뜨렸노라!', `MaleText_loc4`='地狱火堡垒是我们的了！伊利丹的邪兽人军团已经不复存在了！玛瑟里顿在$n和$g他:她;的朋友们面前倒下了！', `MaleText_loc5`='地獄火堡壘是我們的!伊利丹的魔獄獸人軍隊來源斷了!瑪瑟里頓已經被強大的$n以及$g他的:她的;同伴擊倒了!', `MaleText_loc7`='¡La Ciudadela del Fuego Infernal es nuestra! ¡La fuente de la armada de orcos viles de Illidan ha sido destruida! Magtheridon ha caído ante el poder de $n y sus aliados.' WHERE `ID`=20765;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 무기를 들고 일어나서 지금까지도 살아 있는 타락한 오크 잔당을 쓸어버리자. 대족장을 위한 소임을 다하라! 호드를 위하여!', `MaleText_loc4`='决战的时刻到了！让我们拿起武器，消灭残余的邪兽人势力吧！为了你们的酋长而战！为了部落而战！', `MaleText_loc5`='現在就是我們起身反抗並打擊剩餘魔獄獸人的時候了!為了你們的大酋長!為了部落!', `MaleText_loc7`='¡Ha llegado el momento de levantarnos y acabar con los orcos viles que quedan! ¡Háganlo por su Jefe de Guerra! ¡Por la Horda!' WHERE `ID`=20766;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어리석은 자여, 결코 참매의 정수가 네 손안에 들어가는 일은 없을 것이다!', `MaleText_loc4`='蠢货！山鹰精华永远不会落入你的手中！', `MaleText_loc5`='蠢蛋!獵鷹精華永遠不會是你們的!', `MaleText_loc7`='¡Loco! ¡La esencia del halcón nunca será tuya!' WHERE `ID`=20767;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='까마귀 신의 시대가 도래했도다. 네놈들의 시대는 여기까지다!', `MaleText_loc4`='乌鸦之神的时代即将来临，而你的末日就在眼前！', `MaleText_loc5`='烏鴉的時代快到了，但是你的則會在此結束!', `MaleText_loc7`='¡Se acerca el tiempo del Cuervo, pero el tuyo acabará aquí!' WHERE `ID`=20768;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 네가 까마귀 신의 충성스러운 신도들을 방해하느냐?', `MaleText_loc4`='你胆敢打扰乌鸦之神的忠实追随者？', `MaleText_loc5`='你膽敢打擾烏鴉的忠實追隨者?', `MaleText_loc7`='¿Osas molestar a los leales seguidores del Cuervo?' WHERE `ID`=20769;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 그 자만심이 죽음을 재촉하리라!', `MaleText_loc4`='你会为你的傲慢而付出代价，$c！', `MaleText_loc5`='你將會因你的驕傲而死，$c!', `MaleText_loc7`='¡Morirás por tu exceso de orgullo, $c!' WHERE `ID`=20770;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수리매는 쓰러졌다. 다시는 날아오르지 못할 것이다! 헛된 임무는 일찌감치 포기해라!', `MaleText_loc4`='猎鹰被击败了，它注定再也不会出现了！你的任务失败了！', `MaleText_loc5`='獵隼被打敗了，註定永遠不會再起!你的任務毫無成功的希望!', `MaleText_loc7`='¡El halcón ha sido derrotado, condenado a no volver jamás! ¡Tu misión es en vano!' WHERE `ID`=20771;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예언의 계시대로 까마귀 신은 반드시 재림하실 것이노라. 네놈에게 미래를 거스를 힘은 없어!', `MaleText_loc4`='乌鸦之神会像预言所说的那样重返这个世界，而你根本没有能力阻止他！', `MaleText_loc5`='烏鴉將會如同預言所說的回到我們身邊，你無力抵擋的!', `MaleText_loc7`='¡El Cuervo volverá a nosotros tal y como dice la profecía y tú no tienes poder para impedirlo!' WHERE `ID`=20772;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 네 녀석이 날 소환한 것이냐?', `MaleText_loc4`='你胆敢召唤我？', `MaleText_loc5`='你膽敢召喚我?', `MaleText_loc7`='¿Osas invocarme?' WHERE `ID`=20773;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 깊은 숨을 쉽니다!', `MaleText_loc4`='%s深深吸了一口气！', `MaleText_loc5`='%s深深地吸了一口氣!', `MaleText_loc7`='¡%s respira hondo!' WHERE `ID`=20774;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 불덩이 작렬을 시전합니다!', `MaleText_loc4`='%s开始施放炎爆术！', `MaleText_loc5`='%s開始施展炎爆術!', `MaleText_loc7`='%s comienza a lanzar una piroexplosión' WHERE `ID`=20775;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샤트라스 전체가 정적으로 휩싸입니다.', `MaleText_loc4`='沉默突然笼罩着整个沙塔斯城。', `MaleText_loc5`='沉默向撒塔斯襲來。', `MaleText_loc7`='El silencio cae sobre Shattrath.' WHERE `ID`=20776;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s의 생각이 머릿속을 파고듭니다.', `MaleText_loc4`='%s的思想似乎侵入了你的心灵。', `MaleText_loc5`='%s的想法侵入你的心靈。', `MaleText_loc7`='Los pensamientos de %s invaden tu mente.' WHERE `ID`=20777;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='캘타스 선스트라이더가 $n|1과;와; $g그의:그녀의; 친구들에게 패하였다.', `MaleText_loc4`='凯尔萨斯·逐日者被$n和$g他:她;的伙伴们打败了。', `MaleText_loc5`='凱爾薩斯·逐日者已經被$n以及$g他的:她的;同伴們擊倒了。', `MaleText_loc7`='Kael''thas Caminante del Sol ha sido vencido por $n y sus aliados.' WHERE `ID`=20778;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 폭풍우 요새에 남아 있는 블러드 엘프 녀석들을 몰아낼 때가 되었다. 무기를 들고 아달의 전장의 노랫소리로 기세를 올려라!', `MaleText_loc4`='现在，攻击风暴要塞内的残余血精灵的时刻已经来临了。拿起武器！让阿达尔的战歌激励你们吧！', `MaleText_loc5`='現在就是打擊風暴要塞的血精靈殘黨的時候了。拿起武器讓阿達歐的戰鬥之歌加持你!', `MaleText_loc7`='Es el momento de atacar a los elfos de sangre que quedan en El Castillo de la Tempestad. ¡Tomad las armas y dejad que el canto de batalla de A''dal os dé fuerza!' WHERE `ID`=20779;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 출신은 물론, 하늘경비대에 들어오기 전까지 무슨 일을 하고 살았는지 궁금하지도 않지만 여기 있는 동안만큼은 지시사항대로 따라야 할 걸세.', `MaleText_loc4`='我不关心你是谁，或是你在天空卫队以外做些什么。不过只要你在这里，你就要听从我的命令。', `MaleText_loc5`='我不在意你是何方神聖或者你在禦天者外面做了什麼事，不過當你到這來你就得奉命行事。', `MaleText_loc7`='No me importa quién eres ni qué haces fuera de la Guardia del cielo, pero mientras estés aquí harás lo que se te diga.' WHERE `ID`=20780;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 배고프다. 과일이 맛나 보이는군.', `MaleText_loc4`='我饿了。水果应该很好吃。', `MaleText_loc5`='我餓了。水果看起來很好吃。', `MaleText_loc7`='Yo hambre. Fruta parecer rica.' WHERE `ID`=20781;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주름투성이 모그도그가 그록한테 도시로 가라고 했다. 피망치 일족을 도와줄 착한 종족을 찾아보라고. 그래서 그록 여기 왔다.', `MaleText_loc4`='枯瘦的莫戈多格告诉葛罗克，要去城市里为血槌氏族寻求帮助。葛罗克就来了。', `MaleText_loc5`='乾癟的莫格多克告訴葛羅克到城裡去，為血槌尋求幫助。葛羅克去。', `MaleText_loc7`='Mog''dorg el Marchito decir a Grok que ir a ciudad, conseguir ayuda para Machacasangres. Grok ir.' WHERE `ID`=20782;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무도 안 도와주면 그록 여기서 난장판 만들 거야!', `MaleText_loc4`='要是没人帮忙，葛罗克就打人！', `MaleText_loc5`='如果沒有人幫忙，葛羅克去殺!', `MaleText_loc7`='Si nadie ayudar, Grok destrozar.' WHERE `ID`=20783;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼날첨탑 일족은 정정당당하게 싸우지 않는다. 그들을 도와주는 그론 있지. 너 칼날 산맥으로 가라. 주름투성이 모그도그와 얘기해라. 그론 죽여라.', `MaleText_loc4`='刀塔氏族没有公平地战斗。他们有戈隆帮忙。你去刀锋山，和枯瘦的莫戈多格谈谈。去消灭戈隆吧。', `MaleText_loc5`='劍刃氏族打得不公平。有古羅幫忙他們。你到劍刃山脈去。去跟乾癟的莫格多克談談。殺掉古羅。', `MaleText_loc7`='Clan Filospada no pelear limpio. Tener gronn para ayudar. Tú ir a Montañas Filospada. Hablar con Mog''dorg el Marchito. Matar gronn.' WHERE `ID`=20784;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 트롤! 왜 이 부적은 아무 효과가 없지?', `MaleText_loc4`='嘿，巨魔！为什么这个符咒没有用？！', `MaleText_loc5`='嗨，食人妖!為什麼這個符咒沒作用?!', `MaleText_loc7`='¡Hey Troll! ¿Por qué no funcionar este amuleto?' WHERE `ID`=20785;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 자라면 무두장이가 될 거예요!', `MaleText_loc4`='等我长大以后，我要成为一个制革工人！', `MaleText_loc5`='等我長大我要成為一位製皮匠!', `MaleText_loc7`='¡Cuando sea mayor quiero ser curtidor!' WHERE `ID`=20786;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무어?', `MaleText_loc4`='嗯？', `MaleText_loc5`='啊?', `MaleText_loc7`='¿Eh?' WHERE `ID`=20787;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐라고?', `MaleText_loc4`='什么？', `MaleText_loc5`='什麼?', `MaleText_loc7`='¿Qué?' WHERE `ID`=20788;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그록 사과 다 먹어치운 거 아니다. 봐, 한 광주리나 남았잖아!', `MaleText_loc4`='葛罗克没有吃掉所有苹果。看，那里还有一篮。', `MaleText_loc5`='葛羅克沒有吃了所有的蘋果。瞧，那邊還有一籃呢!', `MaleText_loc7`='Grok no comer todas las manzanas, ¡quedar una en cesta!' WHERE `ID`=20789;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 성난 오크가 그랬어. 뭉개버리는 거 내가 다 봤다! 그록이 그 오크 깔아뭉개줄까?', `MaleText_loc4`='就是那个愤怒的兽人。他弄碎了它们！想让葛罗克去打他吗？', `MaleText_loc5`='那就是那個生氣的獸人。他打他們!要葛羅克去打他們嗎?', `MaleText_loc7`='Ser ese orco enfadado. ¡Él estropearlas! ¿Querer que Grok estropearlo?' WHERE `ID`=20790;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오우거의 새로운 $G왕:여왕;에게 모두 경례하라!', `MaleText_loc4`='大家为$n，食人魔新的$G国王:女王;欢呼吧！', `MaleText_loc5`='向你致敬，$n，新的巨魔$G國王:女王;!!!', `MaleText_loc7`='¡Saludad a $n, $g Nuevo:nueva; $g rey:reina; de los ogros!' WHERE `ID`=20791;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나루여, 네 어리석은 일꾼이 임무를 완수하지 못했구나. 반쯤 죽었다고 칠만큼 흠씬 두들겨맞고 왔더군... 우리가 너의 배를 지휘했을 때는 그런 실수는 벌어지지 않았다.', `MaleText_loc4`='你手下那群猴子可耻地失败了，纳鲁。虽然我已经落败，但是我还活着……当我们控制纳鲁飞船的时候，绝对没有犯下这样的错误。', `MaleText_loc5`='你派來的那些蠢猴子沒有把工作完成，那魯。被打倒了但依舊活著...當我們統治你的飛船時可沒犯下同樣的錯誤。', `MaleText_loc7`='Tus fantoches no consiguieron terminar el trabajo, naaru. Apaleado pero vivo… Nosotros no cometimos ese error cuando tomamos el mando de tu nave.' WHERE `ID`=20792;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 다 뭘 위한 것이냐? 하찮은 것을 위한 거란 말인가? 넌 너무 늦었다. 준비는 이미 끝났으니 말이야. 곧 주인님께서 귀환을 하실 것이다.', `MaleText_loc4`='这一切都是为了什么？几样无关紧要的小玩意？太迟了。迎接主人归来的准备工作早就开始了。很快，他就会重返这个世界。', `MaleText_loc5`='這一切為了什麼?飾品?你太遲了。準備工作已經開始，很快地主人就要進行回歸了。', `MaleText_loc7`='¿Todo eso para qué? ¿Baratijas? Llegas muy tarde. Los preparativos ya han comenzado. El maestro pronto volverá.' WHERE `ID`=20793;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 너나 그 바보 같은 일리단 녀석이 나를 막을 방법은 없다! 너와 일리단 모두 태어났을 때부터 나를 섬기게 된 것이다. 자기도 모르게 말이지.', `MaleText_loc4`='你，或是伊利丹那个蠢货，都根本不能阻止我！你们一直扮演着我的仆从的角色，只是你们对此一无所知罢了。', `MaleText_loc5`='你或者是那個蠢貨伊利丹，都無法阻止我!你們兩個全都在不知不覺中協助了我。', `MaleText_loc7`='¡Y no hay nada que tú o ese estúpido de Illidan podáis hacer para detenerme! Ambos me habéis servido por voluntad propia – sin daros cuenta.' WHERE `ID`=20794;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 누가 아제로스를 그의 욕망의 손길에서 벗어나게 하지? 너? 아니면 너의 바보 같은 친구들?', `MaleText_loc4`='他的双眼中折射出欲望的光芒，谁能从他的凝视下拯救艾泽拉斯世界？你？就凭你？还有这些帮你打杂的猴子？', `MaleText_loc5`='誰又會從他貪婪的眼神下拯救艾澤拉斯?你嗎?還是你的那些蠢猴子?', `MaleText_loc7`='¿Y quién salvará Azeroth de su hambrienta mirada? ¿Tú? ¿Tus monos?' WHERE `ID`=20795;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무기를 버리고 킬제덴의 강인함에 굴복할 지어다!', `MaleText_loc4`='放下武器，向基尔加丹的力量屈服吧！', `MaleText_loc5`='放下你的武器並聽從強大的基爾加丹!', `MaleText_loc7`='¡Dejad las armas y sucumbid al poder de Kil''jaeden!' WHERE `ID`=20796;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 어떻게 이럴 수가?', `MaleText_loc4`='不！这怎么可能？', `MaleText_loc5`='不!這怎麼可能?', `MaleText_loc7`='¡No! ¿Cómo es posible?' WHERE `ID`=20797;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하급 정령들은 오래전에 갇혀 돌아오지 못한다! 난 나 자신이 수호자가 되기로 결정했다! 넌 그동안 뭘 했지?', `MaleText_loc4`='很久之前，那些下等的灵魂就被囚禁起来了，再也没有回来！我亲自挑选了守护者！而你都做了些什么？', `MaleText_loc5`='次等鬼魂被盡錮了很長一段時間，永遠無法回去!是我自己選擇守衛的!你做了什麼呢?', `MaleText_loc7`='¡Los espíritus inferiores fueron encarcelados hace años para nunca regresar! ¡Yo mismo elegí los guardianes! ¿Qué has hecho?' WHERE `ID`=20798;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너의 건방진 태도에 대한 대가는 고통이 될 것이다! 넌 에메랄드의 꿈을 나의 것으로 차지하고자 하는 내 의지를 꺾지 못한다!', `MaleText_loc4`='你会为你的傲慢付出痛苦的代价！你休想阻止我夺走翡翠梦境！', `MaleText_loc5`='痛苦將會是你傲慢的代價!你無法阻止我將翡翠夢境納為己有!', `MaleText_loc7`='¡El dolor será el precio por tu insolencia! ¡No puedes evitar que me apodere del Sueño Esmeralda!' WHERE `ID`=20799;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='키스를 받으면 정말 좋을 거 같군요.', `MaleText_loc4`='一个吻就可以了。', `MaleText_loc5`='一個吻會很好。', `MaleText_loc7`='Un beso estaría muy bien.', `FemaleText_loc1`='키스를 받으면 정말 좋을 거 같군요.', `FemaleText_loc4`='一个吻就可以了。', `FemaleText_loc5`='一個吻會很好。', `FemaleText_loc7`='Un beso estaría muy bien.' WHERE `ID`=20800;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음 불꽃놀이 시간에도 들르도록 하세요! 저녁 6시에 시작해서 정시에 계속 된답니다!', `MaleText_loc4`='下次烟火表演的时候你一定要来哦。下午六点开始，每个准点的时刻都有表演！', `MaleText_loc5`='確定你有為了下一場煙火秀到處張貼佈告!晚下6點開始，每個小時整點一次!', `MaleText_loc7`='¡Asegúrate de estar por aquí para el siguiente espectáculo de pirotecnia! Son cada hora a partir de las 6pm.', `FemaleText_loc1`='다음 불꽃놀이 시간에도 들르도록 하세요! 저녁 6시에 시작해서 정시에 계속 된답니다!', `FemaleText_loc4`='下次烟火表演的时候你一定要来哦。下午六点开始，每个准点的时刻都有表演！', `FemaleText_loc5`='確定你有為了下一場煙火秀到處張貼佈告!晚下6點開始，每個小時整點一次!', `FemaleText_loc7`='¡Asegúrate de estar por aquí para el siguiente espectáculo de pirotecnia! Son cada hora a partir de las 6pm.' WHERE `ID`=20801;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마음껏 술을 즐기세요, 친구. 술 마시는 동안엔 난간 근처로만 안 가도록 하시면 됩니다.', `MaleText_loc4`='来喝一杯，朋友。只是在喝酒时小心不要掉下去。', `MaleText_loc5`='朋友自己找點喝的吧。只要記得在喝的時候離暗礁遠一點就好了。', `MaleText_loc7`='Sírvete algo de beber. Tan solo asegúrate de estar lejos del alféizar mientras bebes.', `FemaleText_loc1`='마음껏 술을 즐기세요, 친구. 술 마시는 동안엔 난간 근처로만 안 가도록 하시면 된답니다.', `FemaleText_loc4`='来喝一杯，朋友。只是在喝酒时小心不要掉下去。', `FemaleText_loc5`='朋友自己找點喝的吧。只要記得在喝的時候離暗礁遠一點就好了。', `FemaleText_loc7`='Sírvete algo de beber. Tan solo asegúrate de estar lejos del alféizar mientras bebes.' WHERE `ID`=20802;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불꽃놀이가 끝나면, 술잔이 나올 겁니다. 그럼 우린 동료를 위해 축배를 할 거랍니다!', `MaleText_loc4`='烟火表演之后他们还会把美酒拿出来。到时候我们就可以为朋友们干杯了！', `MaleText_loc5`='煙火後，將會推出高腳杯。我們接著將會對我們的同伴舉杯!', `MaleText_loc7`='Después de los fuegos artificiales se sacarán las copas. ¡Entonces brindaremos por nuestros camaradas!', `FemaleText_loc1`='불꽃놀이가 끝나면, 술잔이 나올 겁니다. 그럼 우린 동료를 위해 축배를 할 거랍니다!', `FemaleText_loc4`='烟火表演之后他们还会把美酒拿出来。到时候我们就可以为朋友们干杯了！', `FemaleText_loc5`='煙火後，將會推出高腳杯。我們接著將會對我們的同伴舉杯!', `FemaleText_loc7`='Después de los fuegos artificiales se sacarán las copas. ¡Entonces brindaremos por nuestros camaradas!' WHERE `ID`=20803;
