UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저녁 6시에 불꽃놀이가 시작되면, 도시는 정시마다 호화로운 광경이 펼쳐질 겁니다.', `MaleText_loc4`='从下午六点开始，每个准点的时刻，城里都会有烟火表演哦！', `MaleText_loc5`='下午6點開使，城裡每個小時整點都會有一場異常盛大的煙火表演。', `MaleText_loc7`='A partir de las 6pm, habrá un espectáculo de fuegos artificiales cada hora.', `FemaleText_loc1`='저녁 6시에 불꽃놀이가 시작되면, 도시는 정시마다 호화로운 광경이 펼쳐질 거예요.', `FemaleText_loc4`='从下午六点开始，每个准点的时刻，城里都会有烟火表演哦！', `FemaleText_loc5`='下午6點開使，城裡每個小時整點都會有一場異常盛大的煙火表演。', `FemaleText_loc7`='A partir de las 6pm, habrá un espectáculo de fuegos artificiales cada hora.' WHERE `ID`=20806;
