UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불꽃놀이가 끝나면 축배를 들기 위한 술잔이 나올 겁니다!', `MaleText_loc4`='在烟火表演以后，他们还会拿出美酒，那样我们就能好好干一杯了！', `MaleText_loc5`='煙火秀之後，他們就會將高腳杯推出來，我們就可以舉杯慶祝了!', `MaleText_loc7`='¡Después de los fuegos artificiales sacarán las copas para que podamos brindar!', `FemaleText_loc1`='불꽃놀이가 끝나면 축배를 들기 위한 술잔이 나올 거예요!', `FemaleText_loc4`='在烟火表演以后，他们还会拿出美酒，那样我们就能好好干一杯了！', `FemaleText_loc5`='煙火秀之後，他們就會將高腳杯推出來，我們就可以舉杯慶祝了!', `FemaleText_loc7`='¡Después de los fuegos artificiales sacarán las copas para que podamos brindar!' WHERE `ID`=20808;
