UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 기계는 너무 강해서 우리끼리 감당하기 힘들다. 그러니 발각되기 전에 어서 움직여라!', `MaleText_loc4`='我们可没法就靠这么点人搞定那台机器，趁我们还没被发现，快跑！', `MaleText_loc5`='那個機械對我們每個人來說太強大了，快點，在我們被發現之前!', `MaleText_loc7`='Esta máquina es demasiado poderosa para nosotros solos. Rápido, ¡antes de que nos vean!', `FemaleText_loc1`='저 기계는 너무 강해서 우리끼리 감당하기 힘들다. 그러니 발각되기 전에 어서 움직여라!', `FemaleText_loc4`='我们可没法就靠这么点人搞定那台机器，趁我们还没被发现，快跑！', `FemaleText_loc5`='那個機械對我們每個人來說太強大了，快點，在我們被發現之前!', `FemaleText_loc7`='Esta máquina es demasiado poderosa para nosotros solos. Rápido, ¡antes de que nos vean!' WHERE `ID`=20818;
