UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불타는 군단의 피조물들은 날이 갈수록 더 늘어나고 있군.', `MaleText_loc4`='燃烧军团造出来的东西真是一天比一天邪恶了。', `MaleText_loc5`='軍團的生物確實日漸邪惡了。', `MaleText_loc7`='Las creaciones de la Legión son cada día más grotescas.', `FemaleText_loc1`='불타는 군단의 피조물들은 날이 갈수록 더 늘어나고 있군.', `FemaleText_loc4`='燃烧军团造出来的东西真是一天比一天邪恶了。', `FemaleText_loc5`='軍團的生物確實日漸邪惡了。', `FemaleText_loc7`='Las creaciones de la Legión son cada día más grotescas.' WHERE `ID`=20820;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일리단, 기계 골렘이 문을 두드리는 소리를 네가 얼마나 듣고 있을지 지켜보도록 할까!', `MaleText_loc4`='让我们看看当这个机器恶棍敲你的大门时，你会作何感想，伊利丹！', `MaleText_loc5`='讓我們瞧瞧你要如何享受那討厭的機械去敲你的門，伊利丹!', `MaleText_loc7`='¡A ver si disfrutas cuando esa abominación mecánica toque a tu puerta, Illidan!', `FemaleText_loc1`='일리단, 기계 골렘이 문을 두드리는 소리를 네가 얼마나 듣고 있을지 지켜보도록 할까!', `FemaleText_loc4`='让我们看看当这个机器恶棍敲你的大门时，你会作何感想，伊利丹！', `FemaleText_loc5`='讓我們瞧瞧你要如何享受那討厭的機械去敲你的門，伊利丹!', `FemaleText_loc7`='¡A ver si disfrutas cuando esa abominación mecánica toque a tu puerta, Illidan!' WHERE `ID`=20821;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서, 안으로! 저 녀석들의 공격을 우리가 바라던 소동으로 이용해 먹도록 하자!', `MaleText_loc4`='进去，快点！可以用燃烧军团的进攻作为掩护！', `MaleText_loc5`='裡面，快!讓我們利用軍團的攻擊來分散注意力!', `MaleText_loc7`='¡Adentro, rápido! ¡Aprovechemos la distracción creada por el ataque de la Legión!', `FemaleText_loc1`='어서, 안으로! 저 녀석들의 공격을 우리가 바라던 소동으로 이용해 먹도록 하자!', `FemaleText_loc4`='进去，快点！可以用燃烧军团的进攻作为掩护！', `FemaleText_loc5`='裡面，快!讓我們利用軍團的攻擊來分散注意力!', `FemaleText_loc7`='¡Adentro, rápido! ¡Aprovechemos la distracción creada por el ataque de la Legión!' WHERE `ID`=20822;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용기수들이여, 비상하라!', `MaleText_loc4`='龙骑士，准备起飞！', `MaleText_loc5`='龍騎兵登上坐騎!', `MaleText_loc7`='¡Jinetes de dragones, montad!', `FemaleText_loc1`='용기수들이여, 비상하라!', `FemaleText_loc4`='龙骑士，准备起飞！', `FemaleText_loc5`='龍騎兵登上坐騎!', `FemaleText_loc7`='¡Jinetes de dragones, montad!' WHERE `ID`=20823;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 바보 같은 녀석, 네 정찰 임무로 복귀해라! 그 보호막은 나에겐 너희 백 명보다도 더 소중한 것이니...', `MaleText_loc4`='你这垃圾，回到巡逻队中去！对我来说，那护盾比一百个你都要有价值……', `MaleText_loc5`='繼續巡邏，懦夫!那個盾對我的價值可是比一百個你還要來得珍貴...', `MaleText_loc7`='¡Continúa patrullando, gusano! Este escudo me es más preciado que cien de ustedes juntos...' WHERE `ID`=20824;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 모욕이로구나! 네 불충은 처벌을 면치 못할 것이다!', `MaleText_loc4`='这是赤裸裸的侮辱！你胆敢违抗我的命令，我要惩罚你！', `MaleText_loc5`='這是種冒犯!你的大逆不道將會得到懲罰!', `MaleText_loc7`='¡Esto es una atrocidad! ¡Tu desobediencia no quedará libre de castigo!' WHERE `ID`=20825;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저공 비행 간다!', `MaleText_loc4`='请求低飞掠过哨塔的允许！', `MaleText_loc5`='請求低空飛過塔台!', `MaleText_loc7`='¡Permiso para sacudir la torre!', `FemaleText_loc1`='저공 비행 간다!', `FemaleText_loc4`='请求低飞掠过哨塔的允许！', `FemaleText_loc5`='請求低空飛過塔台!', `FemaleText_loc7`='¡Permiso para sacudir la torre!' WHERE `ID`=20826;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대의를 위해 목숨까지 바친 이들에게 어떤 찬사를 다해도 부족하지. 그대들과 함께 싸워서 영광이었다는 말로 인사를 대신하고 싶군. 이제 당당히 나아가 환호의 함성을 울리도록. 우리가 승리했노라!', `FemaleText_loc4`='对于那些在这场战役中献出生命的勇士，没有什么词语能够表达我们敬意。但是我想说，很荣幸能与你们并肩作战。现在，尽情地庆祝吧，胜利属于我们！！', `FemaleText_loc5`='對那些無私地為眾人奉獻生命的人，再多的言語也無法挽回他們的性命。只能說我很榮幸能和你們每一個人並肩作戰，這就夠了。現在去慶祝吧。勝利是屬於我們的!', `FemaleText_loc7`='No hay palabras suficientes para agradecer a aquellos que entregan sus vidas desinteresadamente por el bien de todos. Basta decir que tengo el honor de haber luchado hombro a hombro con ustedes. Ahora sigan adelante y celebren. ¡La victoria es nuestra!' WHERE `ID`=20827;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 생전에 그렇게 정말 용한 부적이 있다는 소리는 못 들어봤네. 점술가들도 그들의 도서관에서 그런 물건이 존재한다는 기록은 단 한 줄도 발견하지 못했다고 말해주더군.', `MaleText_loc4`='我出生至今就没听说过什么提克巴朗。事实上，占星者们说他们在图书馆中也没有找到任何提及提克巴朗的资料……', `MaleText_loc5`='我這輩子從來沒聽過提巴蘭。事實上，占卜者們告訴我他們在他們的圖書館找不到任何有關提巴蘭的隻字片語。', `MaleText_loc7`='Nunca había oído hablar de un tikbalang en mi vida. De hecho, los Arúspices me han dicho que no encuentran ni una sola mención a un tikbalang en sus libros...' WHERE `ID`=20828;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 깐깐한 친구! 전투에서 살아남아 그런 기록을 남길 수 있었던 자가 없었던 거 아닐까?', `MaleText_loc4`='要知道，他们可不是为了写这个而活的，你说是吧？', `MaleText_loc5`='瞧，小子，他們不是活著來讓人記錄的，知道嗎?!', `MaleText_loc7`='Escúchame, nadie ha sobrevivido y ha podido escribir sobre ellos, ¡¿lo entiendes?!' WHERE `ID`=20829;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갑작스레 %s의 얼굴이 의심스럽다는 표정으로 바뀝니다.', `MaleText_loc4`='%s皱起眉毛，露出怀疑的神色。', `MaleText_loc5`='%s突然轉為一付懷疑面孔。', `MaleText_loc7`='%s eleva la ceja la escepticismo.' WHERE `ID`=20830;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 시민을 모욕하는 건가?', `MaleText_loc4`='你是在侮辱我们的市民吗？', `MaleText_loc5`='你在侮辱我們的居民嗎?', `MaleText_loc7`='¿Estás insultado a nuestros ciudadanos?' WHERE `ID`=20831;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사실인 걸 어쩌나, 친구! 자네는 이 냄새 안 나는가?', `MaleText_loc4`='这就是事实，朋友。你体会不到吗？', `MaleText_loc5`='這是事實，小子。你聞不到嗎?', `MaleText_loc7`='Es la verdad. ¿No lo hueles?' WHERE `ID`=20832;
