UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 그렇게 쉽게 넘어가면 안 돼요! 속임수라니까요!', `MaleText_loc4`='不要这么轻易地被吸引，$n！这是个骗局！', `MaleText_loc5`='不要這麼容易就被騙了，$n!這是個騙局!', `MaleText_loc7`='¡No te dejes engañar tan fácilmente, $n! ¡Es un truco!', `FemaleText_loc1`='$n, 그렇게 쉽게 넘어가면 안 돼요! 속임수라니까요!', `FemaleText_loc4`='不要这么轻易地被吸引，$n！这是个骗局！', `FemaleText_loc5`='不要這麼容易就被騙了，$n!這是個騙局!', `FemaleText_loc7`='¡No te dejes engañar tan fácilmente, $n! ¡Es un truco!' WHERE `ID`=20838;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 속박을 풀고 적들을 쫓아가세요!', `MaleText_loc4`='恢复自由，$n，追击！', `MaleText_loc5`='釋放你自己並追捕他們，$n!', `MaleText_loc7`='¡Libérate y persíguelos, $n!', `FemaleText_loc1`='$n, 속박을 풀고 적들을 쫓아가세요!', `FemaleText_loc4`='恢复自由，$n，追击！', `FemaleText_loc5`='釋放你自己並追捕他們，$n!', `FemaleText_loc7`='¡Libérate y persíguelos, $n!' WHERE `ID`=20839;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 당신을 속박하는 모든 것을 무너뜨리세요!', `MaleText_loc4`='$n，冲破束缚，重获自由吧！', `MaleText_loc5`='掙脫你的手銬，$n!', `MaleText_loc7`='¡Libérate de tus grilletes, $n!', `FemaleText_loc1`='$n, 당신을 속박하는 모든 것을 무너뜨리세요!', `FemaleText_loc4`='$n，冲破束缚，重获自由吧！', `FemaleText_loc5`='掙脫你的手銬，$n!', `FemaleText_loc7`='¡Libérate de tus grilletes, $n!' WHERE `ID`=20840;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 방어하려는 듯 등껍질 속으로 몸을 잔뜩 움츠립니다.', `MaleText_loc4`='%s缩进了龟壳里。', `MaleText_loc5`='%s自衛性的射擊。', `MaleText_loc7`='%s se retrae de modo defensivo.' WHERE `ID`=20841;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 킁킁거리면서 냄새를 맡더니 얼굴을 찡그립니다. 평화감시단원이 주위를 둘러봅니다.', `MaleText_loc4`='%s嗅了嗅空气中的味道，皱起眉头。他往肩膀上瞟了一眼。', `MaleText_loc5`='%s嗅了嗅空氣並皺眉。他往他的肩膀方向瞄了一眼。', `MaleText_loc7`='%s olfatea el aire y frunce el ceño. Echa un vistazo por encima de su hombro.' WHERE `ID`=20842;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 냄새는... 토비아스한테서 나는 것이 분명하군.', `MaleText_loc4`='我认为，那……气味是从托比亚斯那里来的。', `MaleText_loc5`='我相信，那個...香味是來自托比亞斯。', `MaleText_loc7`='Ese olor... es de Tobias, creo.' WHERE `ID`=20843;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잔뜩 찡그렸던 %s의 표정이 음흉하게 바뀝니다.', `MaleText_loc4`='%s失落的神情消失了，换上一副狡猾的模样。', `MaleText_loc5`='%s的沮喪皺眉消失換成一副狡詐面孔。', `MaleText_loc7`='%s pasa de un gesto de frustración a uno pícaro.' WHERE `ID`=20844;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='목욕이라곤... 일 년에 딱 두 번만 하는 것 같은데?', `MaleText_loc4`='……你觉得他会买绳子上的肥皂吗？', `MaleText_loc5`='...你想他可能會買香皂項鍊嗎?', `MaleText_loc7`='Ya sabía yo que no era ni nuevo ni lavado con...' WHERE `ID`=20845;
