UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='탈 아누멘 노 신도레이!', `FemaleText_loc4`='Tal anu''men no sin''dorei！', `FemaleText_loc5`='與血精靈為敵者死!', `FemaleText_loc7`='¡Tal anu''men no sin''dorei!' WHERE `ID`=20849;
