UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아나랄라 벨로레!', `MaleText_loc4`='Anar''alah belore!', `MaleText_loc5`='(薩拉斯語)以太陽之光!', `MaleText_loc7`='¡Anar''alah belore!' WHERE `ID`=20860;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이걸로 안심하긴... 이르다.', `MaleText_loc4`='更大的危机……在等着你们。', `MaleText_loc5`='還有更危險的...等待著你...', `MaleText_loc7`='Más peligros...aguardan...' WHERE `ID`=20861;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 파는 물건이 다른 사람의 마음을 조종할 수 있다고 말하는 건가? 거참 위험한 주장이군...', `MaleText_loc4`='你是不是在暗示你出售的设备可以控制他人的心灵？那可是非常危险的……', `MaleText_loc5`='你是在暗示你賣的裝置可以操縱別人的心智嗎?這可是非常危險的說詞...', `MaleText_loc7`='¿Insinúas que vendes aparatos que dominan la mente de los demás? Esa afirmación es muy peligrosa...' WHERE `ID`=20862;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 화난 얼굴로 자다르를 바라봅니다.', `MaleText_loc4`='%s脸上带着愤怒的表情转向亚达尔。', `MaleText_loc5`='%s怒沖沖的轉向賈達。', `MaleText_loc7`='%s se gira hacia Jadaar con expresión exasperada.' WHERE `ID`=20863;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐. 그래서 나보고 어떻게 장사하라는거야?', `MaleText_loc4`='说实在的，朋友，你在嘲笑我的品位。', `MaleText_loc5`='你破壞了我的格調，老兄。我是認真的。', `MaleText_loc7`='Colega, me estás cortando las alas. En serio.' WHERE `ID`=20864;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='규정에 장사는 있어도 사기는 없네. 게다가 내 말 한마디로 타격을 받으면 안 되는 거잖나.', `MaleText_loc4`='倘若你的“品位”不包括诈骗城里的居民，那么你就不会觉得我的话很“讽刺”。', `MaleText_loc5`='維護你的「格調」並不包括詐欺市民，我的話語無論如何都不應該會「妨礙」它。', `MaleText_loc7`='Suponiendo que tus ‘alas’ no sean estafar a los habitantes de la cuidad, mis palabras no deberían ‘cortarlas’' WHERE `ID`=20865;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알았어, 알았다고.', `MaleText_loc4`='嗯，嗯。', `MaleText_loc5`='是，是。', `MaleText_loc7`='Sí, sí.' WHERE `ID`=20866;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아카마, 너의 불충은 그리 놀랍지도 않구나. 너희 흉측한 형제들을 벌써 오래전에 없애버렸어야 했는데...', `MaleText_loc4`='阿卡玛。你的两面三刀并没有让我感到意外。我早就应该把你和你那些畸形的同胞全部杀掉。', `MaleText_loc5`='阿卡瑪。你的謊言真是老套。我很久前就該殺了你和你那些畸形的同胞。', `MaleText_loc7`='Akama. Tu hipocresía no me sorprende. Debí haber acabado contigo y con tus deformes hermanos hace tiempo.' WHERE `ID`=20867;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='입을 잘도 놀리는구나. 허나, 가당치도 않다!', `MaleText_loc4`='说得好。但是这毫无意义。', `MaleText_loc5`='說得好。但是這毫無意義。', `MaleText_loc7`='Audaces palabras. Pero no...me convencen.' WHERE `ID`=20868;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 사소한 목걸이가 삶의 본질까지 뒤흔들 수 있다고 선전해선 안 되지 않나!', `MaleText_loc4`='你不会是想说你卖的这堆破烂能改变人们的生活吧？', `MaleText_loc5`='你可能無法建議你的這些小東西們掌控對自身生命體的支配!', `MaleText_loc7`='¡No estarás sugiriendo que estos cachivaches tuyos controlan el tejido de la propia vida!' WHERE `ID`=20869;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 성난 목소리로 받아칩니다.', `MaleText_loc4`='%s愤怒地大声咆哮着。', `MaleText_loc5`='%s憤怒的咆哮。', `MaleText_loc7`='%s gruñe enfadado' WHERE `ID`=20870;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디 내기 할텐가?!', `MaleText_loc4`='你想查明吗？！', `MaleText_loc5`='你想要查明?!', `MaleText_loc7`='¿Quieres averiguarlo?' WHERE `ID`=20871;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 무서운 눈길로 그립타를 노려봅니다.', `MaleText_loc4`='%s冷冷地盯着格里伏塔。', `MaleText_loc5`='%s冷淡的瞪了格利夫塔一眼。', `MaleText_loc7`='%s lanza a Griftah una mirada gélida.' WHERE `ID`=20872;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금... 겁 주는 건가?', `MaleText_loc4`='……你在威胁我？！', `MaleText_loc5`='...那是威脅嗎?!', `MaleText_loc7`='¡¿...era eso una AMENAZA?!' WHERE `ID`=20873;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 엄... 아니야.', `MaleText_loc4`='啊……啊……不。', `MaleText_loc5`='啊...呃...吶。', `MaleText_loc7`='Ah... uh... nah.' WHERE `ID`=20874;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 눈살을 찌푸리고 그립타의 뒷통수를 말 없이 쳐다봅니다.', `MaleText_loc4`='%s在格里伏塔的身后皱着眉头，但仍然保持着沉默。', `MaleText_loc5`='%s在格利夫塔的腦後重重地皺起眉頭，但還是保持靜默。', `MaleText_loc7`='%s frunce el ceño severamente tras la cabeza de Griftah, pero permanece en silencio.' WHERE `ID`=20875;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말? "검증" 받았다고? 한번 바닥에 앉아서 이 "검증"된 물건에 대해서 얘길 좀 해봐야겠군, 장사꾼 양반.', `MaleText_loc4`='真的？“保证”？我们要坐下来仔细地谈谈关于你的这个“保证”。', `MaleText_loc5`='真的嗎?「擔保?」我們需要坐下來好好談一下有關你的這個「擔保」，商人。', `MaleText_loc7`='"¿De verdad?"¿Garantizado?" Tendremos que sentarnos y hablar sobre esta "garantía" tuya, mercader.' WHERE `ID`=20876;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 몸을 움츠리고 낮은 목소리로 저주를 퍼붓습니다.', `MaleText_loc4`='%s耷拉着肩膀，轻声祈求着什么。', `MaleText_loc5`='%s垂下他的肩膀，輕聲的唸著咒語。', `MaleText_loc7`='%s encoge los hombros, farfullando juramentos para sí.' WHERE `ID`=20877;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보아하니 자네가 지금 이 자리에서 효과를 입증할 수 있을 것 같진 않구먼.', `MaleText_loc4`='你不如在这里就展示一下你出售的这个护身符的治疗效果……？', `MaleText_loc5`='我不認為你會負起責任馬上在這裡驗證這個護符的治療力量...?', `MaleText_loc7`='¿Supongo que no estarás dispuesto a demostrar el poder sanador del amuleto aquí ahora...?' WHERE `ID`=20878;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어... 안돼, 친구. 이 물건들을 너저분하게 벌여놓는 걸 바라는 건 아니겠지?', `MaleText_loc4`='啊……不，朋友。别把货物搞乱了，行吗？', `MaleText_loc5`='啊...吶，小子。別想把所有商品都搞得亂七八糟的，知嗎?', `MaleText_loc7`='Oh...no, colega. No quiero que se me desordene la mercancía, ¿lo pillas?' WHERE `ID`=20879;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 멋쩍은 듯이 웃습니다.', `MaleText_loc4`='%s紧张地笑了笑。', `MaleText_loc5`='%s緊張的笑了。', `MaleText_loc7`='%s sonríe nerviosamente.' WHERE `ID`=20880;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니야. 하지만, 언제 한번 자네 주장이 맞는지 내 눈으로 확인하고 싶군.', `MaleText_loc4`='好吧。咱们待会儿再谈，不过我很想看看你所宣称的证据。', `MaleText_loc5`='很好。不過，晚一點，我希望看到你聲明的證據。', `MaleText_loc7`='Muy bien. De todos modos, después quiero ver pruebas de tus afirmaciones.' WHERE `ID`=20881;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아! 좋다고. 나중에. 아주 나중에 말이야.', `MaleText_loc4`='嗨！嗨！朋友，待会儿。咱们待会儿再谈。', `MaleText_loc5`='耶!沒錯。晚一點，小子。很晚。', `MaleText_loc7`='¡Sí! Sí. Más tarde, colega. Mucho más tarde.' WHERE `ID`=20882;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이에 대해 수차례 불만이 제기되었네. 그가 수상쩍다는 얘길 들었지. 여기서 이 사업이 합법적인지 아닌지를 보고 문제가 된다면 어떤 행동이든 취할 걸세.', `MaleText_loc4`='到处都是对这个……这个家伙的抱怨声。据说他是个可疑的人物。我是来调查他的生意是否合法的……如果他胆敢做违法的勾当，我就会立即采取行动。', `MaleText_loc5`='關於這個...人，已經有一些抱怨出現了。我聽說他在從事見不得人的勾當。我是到此來判定他的這檔生意是否合法...並於可證明其他事物時提出訴訟。', `MaleText_loc7`='Hemos recibido algunas quejas acerca de este... individuo. Me han comentado que es de carácter sombrío. Estoy aquí para determinar si su negocio es o no legal... y para tomar medidas si es necesario.' WHERE `ID`=20883;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너흰 아직 준비가 안 됐다!', `MaleText_loc4`='你们这是自寻死路！', `MaleText_loc5`='你們還沒準備好!', `MaleText_loc7`='¡NO están preparados!' WHERE `ID`=20884;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원한 카드 한 벌을 완성한다면, 앙갚음의 다크문 카드를 보상으로 받게 될 겁니다. 이 카드를 착용하고 있는 동안은 당신을 공격하는 누구든 성스러운 복수로 고통받게 될 겁니다!', `MaleText_loc4`='如果你集齐一套报复卡片的话，你将获得一张暗月卡片：复仇。当你拿着这张卡片时，任何攻击你的人都有一定几率遭到神圣的复仇。', `MaleText_loc5`='如果你收集整套的狂怒套卡，你將可以得到一張高級暗月卡:復仇作為獎勵。身上穿戴這張卡的同時，任何攻擊你的人都有機會遭到神聖復仇攻擊。', `MaleText_loc7`='Si consigues completar una baraja de Furias, te recompensaremos con un naipe superior de la Luna Negra de la Venganza. Mientras poseas este naipe cualquier jugador que te ataque tendrá una posibilidad de sufrir Venganza Sagrada.' WHERE `ID`=20885;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭풍 카드 한 벌을 완성한다면, 진노의 다크문 카드를 보상으로 받게 될 겁니다. 이 카드를 착용하면 공격이 명중할 때까지 치명타 및 극대화가 증가하는 효과를 얻게 될 겁니다.', `MaleText_loc4`='如果你集齐一套风暴卡片的话，你将获得暗月卡片：怒火。当你拿着这张卡片时，你的法术或物理攻击的爆击几率会不断提高，直到你打出一次爆击。', `MaleText_loc5`='如果你收集整套的風暴套卡，你將可以得到一張高級暗月卡:狂怒作為獎勵。這將會增加你法術或物理攻擊的致命一擊機率直到造成致命一擊為止。', `MaleText_loc7`='Si consigues completar una baraja de Tormentas, te recompensaremos con un naipe superior de la Luna Negra de la Cólera. Esto aumentará tus posibilidades de asestar un impacto crítico con hechizos o ataques físicos hasta que consigas uno.' WHERE `ID`=20886;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='축복 카드 한 벌을 완성한다면, 성전의 다크문 카드를 보상으로 받게 될 겁니다. 이 카드를 착용하면 적에게 피해를 줄 때마다 전투력과 주문력이 증가하는 효과를 얻게 된답니다.', `MaleText_loc4`='如果你集齐一套祝福卡片的话，你将获得暗月卡片：远征。当你拿着这张卡片时，你只需持续战斗，你的法术和物理攻击的伤害就会不断提高。', `MaleText_loc5`='如果你收集整套的祝福套卡，你將可以得到一張高級暗月卡:聖戰作為獎勵。這將會在你戰鬥時增加你的法術以及攻擊傷害。', `MaleText_loc7`='Si consigues completar una baraja de Bendiciones, te recompensaremos con un naipe superior de la Luna Negra de la Cruzada. Esto aumentará el daño que inflijas con tus hechizos y ataques a medida que sigas luchando.' WHERE `ID`=20887;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='열광 카드 한 벌을 완성한다면, 광기의 다크문 카드를 보상으로 받게 될 겁니다. 당신이 적을 처치하면 언제든 광기의 힘이 당신을 채우게 될 겁니다.', `MaleText_loc4`='如果你集齐一套愚人卡片的话，你将获得暗月卡片：疯狂。当你拿着这张卡片时，每当你杀死一个敌人，你就会充满疯狂的力量。', `MaleText_loc5`='如果你收集整套的失心套卡，你將可以得到一張高級暗月卡:瘋狂作為獎勵。這股瘋狂的力量將於你每一次殺死敵人時充滿你的身體。', `MaleText_loc7`='Si consigues completar una baraja de Locuras, te recompensaremos con un naipe superior de la Luna Negra de la Demencia. El poder de la demencia te llenará cada vez que mates a un enemigo.' WHERE `ID`=20888;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원한 카드에 대해 얘기해 주십시오.', `MaleText_loc4`='告诉我更多关于报复套牌的信息。', `MaleText_loc5`='告訴我有關狂怒套卡的事。', `MaleText_loc7`='Háblame sobre la baraja de Furias.', `FemaleText_loc1`='원한 카드에 대해 얘기해 주세요.', `FemaleText_loc4`='告诉我更多关于报复套牌的信息。', `FemaleText_loc5`='告訴我有關狂怒套卡的事。', `FemaleText_loc7`='Háblame sobre la baraja de Furias.' WHERE `ID`=20889;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='열광 카드에 대해 얘기해 주십시오.', `MaleText_loc4`='告诉我更多关于愚人套牌的信息。', `MaleText_loc5`='告訴我有關失心套卡的事。', `MaleText_loc7`='Háblame sobre la baraja de Locuras.', `FemaleText_loc1`='열광 카드에 대해 얘기해 주세요.', `FemaleText_loc4`='告诉我更多关于愚人套牌的信息。', `FemaleText_loc5`='告訴我有關失心套卡的事。', `FemaleText_loc7`='Háblame sobre la baraja de Locuras.' WHERE `ID`=20890;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='축복 카드에 대해 얘기해 주십시오.', `MaleText_loc4`='告诉我更多关于祝福套牌的信息。', `MaleText_loc5`='告訴我有關祝福套卡的事。', `MaleText_loc7`='Háblame sobre la baraja de Bendiciones.', `FemaleText_loc1`='축복 카드에 대해 얘기해 주세요.', `FemaleText_loc4`='告诉我更多关于祝福套牌的信息。', `FemaleText_loc5`='告訴我有關祝福套卡的事。', `FemaleText_loc7`='Háblame sobre la baraja de Bendiciones.' WHERE `ID`=20891;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭풍 카드에 대해 얘기해 주십시오.', `MaleText_loc4`='告诉我更多关于风暴套牌的信息。', `MaleText_loc5`='告訴我有關風暴套卡的事。', `MaleText_loc7`='Háblame sobre la baraja de Tormentas.', `FemaleText_loc1`='폭풍 카드에 대해 얘기해 주세요.', `FemaleText_loc4`='告诉我更多关于风暴套牌的信息。', `FemaleText_loc5`='告訴我有關風暴套卡的事。', `FemaleText_loc7`='Háblame sobre la baraja de Tormentas.' WHERE `ID`=20892;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일리단! 너의 통치를 종식시키기 위해 우리가 왔다! 우리 종족은 물론 아웃랜드 전체를 해방시키리라!', `MaleText_loc4`='我们要终结你的统治，伊利丹！我的人民，以及整个外域，都将重获自由！', `MaleText_loc5`='我們要終結你的統治，伊利丹﹗我的人民，以及整個外域，都將重獲自由﹗', `MaleText_loc7`='Hemos venido a PONER FIN a tu reinado, Illidan. Mi pueblo – y todo Terrallende – serán libres.' WHERE `ID`=20893;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='때가 왔다. 기다리던 순간이!', `MaleText_loc4`='时机来临了，终于等到这一刻了！', `MaleText_loc5`='時機來臨了，終於等到這一刻了﹗', `MaleText_loc7`='¡Ha llegado la hora: es el momento!' WHERE `ID`=20894;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 오우거들은 파멸의 길을 걸었었다오...', `MaleText_loc4`='我们食人魔曾经迷失了自我……', `MaleText_loc5`='我們巨魔曾經迷失...', `MaleText_loc7`='Hubo un tiempo en que los ogros estuvimos perdidos...', `FemaleText_loc1`='우리 오우거들은 파멸의 길을 걸었었다오...', `FemaleText_loc4`='我们食人魔曾经迷失了自我……', `FemaleText_loc5`='我們巨魔曾經迷失...', `FemaleText_loc7`='Hubo un tiempo en que los ogros estuvimos perdidos...' WHERE `ID`=20895;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비록 강하지만, 우린 폭력만 알고 있었소...', `MaleText_loc4`='虽然我们很强大，但却只知道暴力……', `MaleText_loc5`='儘管強大，我們只知道破壞...', `MaleText_loc7`='Aunque éramos poderosos, solo conocíamos la violencia...', `FemaleText_loc1`='비록 강하지만, 우린 폭력만 알고 있었소...', `FemaleText_loc4`='虽然我们很强大，但却只知道暴力……', `FemaleText_loc5`='儘管強大，我們只知道破壞...', `FemaleText_loc7`='Aunque éramos poderosos, solo conocíamos la violencia...' WHERE `ID`=20896;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 오랫동안 치열하게 싸움만 했다오. 그렇게 우리는 싸움이라는 단어로만 그 존재를 표출했었지.', `MaleText_loc4`='我们经历了艰苦卓绝的漫长斗争，每一次都证明了我们食人魔是一股不可忽视的力量。', `MaleText_loc5`='我們辛苦奮戰了許久。我們一次又一次證明我們巨魔是支值得對付的軍隊。', `MaleText_loc7`='Luchamos largo y tendido. Demostramos una y otra vez que los ogros eramos una fuerza a tener en cuenta.', `FemaleText_loc1`='우린 오랫동안 치열하게 싸움만 했다오. 그렇게 우리는 싸움이라는 단어로만 그 존재를 표출했었지.', `FemaleText_loc4`='我们经历了艰苦卓绝的漫长斗争，每一次都证明了我们食人魔是一股不可忽视的力量。', `FemaleText_loc5`='我們辛苦奮戰了許久。我們一次又一次證明我們巨魔是支值得對付的軍隊。', `FemaleText_loc7`='Luchamos largo y tendido. Demostramos una y otra vez que los ogros eramos una fuerza a tener en cuenta.' WHERE `ID`=20897;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 머지않아 우린 서로와 싸우게 되었소. 형제끼리 누가 더 강한지를 결정하기 위해 피를 흘렸던 것이오.', `MaleText_loc4`='不久以后，我们内部开始互相争斗，兄弟之间凭借血腥的战斗来决出谁是最强者。', `MaleText_loc5`='總有一天很快地我們就要面對對方。兄弟間互相爭鬥以決定誰是最強的人。', `MaleText_loc7`='Pero pronto nos volvimos en contra. Luchamos uno contra otro para decidir quién era el más poderoso.', `FemaleText_loc1`='하지만 머지않아 우린 서로와 싸우게 되었소. 형제끼리 누가 더 강한지를 결정하기 위해 피를 흘렸던 것이오.', `FemaleText_loc4`='不久以后，我们内部开始互相争斗，兄弟之间凭借血腥的战斗来决出谁是最强者。', `FemaleText_loc5`='總有一天很快地我們就要面對對方。兄弟間互相爭鬥以決定誰是最強的人。', `FemaleText_loc7`='Pero pronto nos volvimos en contra. Luchamos uno contra otro para decidir quién era el más poderoso.' WHERE `ID`=20898;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비뚤어진 길로 가는 우리의 모습은 선명했었소. 바로 우리 자신이 우리의 가장 큰 적이었고 서로 파괴해 가고 있었던 것이오.', `MaleText_loc4`='很明显，从那以后，我们的种族已经在毁灭的道路上走出了很远。我们成了自己最大的敌人，成了毁灭自身的原因。', `MaleText_loc5`='很明顯的我們的道路已經設定好了。我們是自己最大的敵人，而且我們已經決定要摧毀我們自己。', `MaleText_loc7`='Era evidente que nuestros caminos estaban señalados. Éramos nuestros mayores enemigos y estábamos dispuestos a destruirnos.', `FemaleText_loc1`='비뚤어진 길로 가는 우리의 모습은 선명했었소. 바로 우리 자신이 우리의 가장 큰 적이었고 서로 파괴해 가고 있었던 것이오.', `FemaleText_loc4`='很明显，从那以后，我们的种族已经在毁灭的道路上走出了很远。我们成了自己最大的敌人，成了毁灭自身的原因。', `FemaleText_loc5`='很明顯的我們的道路已經設定好了。我們是自己最大的敵人，而且我們已經決定要摧毀我們自己。', `FemaleText_loc7`='Era evidente que nuestros caminos estaban señalados. Éramos nuestros mayores enemigos y estábamos dispuestos a destruirnos.' WHERE `ID`=20899;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러다 이 수정들 사이에서 우리는 새로운 길을 보게 된 것이오. 바로 평화의 길을...', `MaleText_loc4`='但是如今，在这些水晶之间，我们找到了一条新的道路，一条和平之路。', `MaleText_loc5`='在這些水晶之中我們已經看到了一條新道路，一條和平的道路。', `MaleText_loc7`='Entre estos cristales hemos vislumbrado un nuevo camino, un camino de paz.', `FemaleText_loc1`='그러다 이 수정들 사이에서 우리는 새로운 길을 보게 된 것이오. 바로 평화의 길을...', `FemaleText_loc4`='但是如今，在这些水晶之间，我们找到了一条新的道路，一条和平之路。', `FemaleText_loc5`='在這些水晶之中我們已經看到了一條新道路，一條和平的道路。', `FemaleText_loc7`='Entre estos cristales hemos vislumbrado un nuevo camino, un camino de paz.' WHERE `ID`=20900;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모르디스! 엘룬이시여, 감사 드립니다! 다신 자넬 못 볼 줄 알았네.', `MaleText_loc4`='莫希斯！感谢艾露恩！我还以为我再也看不到你了。', `MaleText_loc5`='莫西斯!感謝伊露恩!我還擔心我無法再見到你了。', `MaleText_loc7`='¡Morthis! ¡Gracias a Elune! Creí que nunca volvería a verte.' WHERE `ID`=20901;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하시오, 친구들. 배신자가 코앞에서 명상을 취하고 있으니...', `MaleText_loc4`='当心点，朋友们。背叛者就在那边的大厅中冥想。', `MaleText_loc5`='當心點，朋友們。背叛者就在那邊的大廳中冥想。', `MaleText_loc7`='Tengan cuidado, amigos. El Traidor medita en el patio de ahí al lado.' WHERE `ID`=20902;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 일리단과 맞설 준비가 되었습니다.', `MaleText_loc4`='我们已经作好面对伊利丹的准备了。', `MaleText_loc5`='我們已經準備好對付伊利丹了。', `MaleText_loc7`='Estamos preparados para enfrentarnos a Illidan.', `FemaleText_loc1`='우린 일리단과 맞설 준비가 되었어요.', `FemaleText_loc4`='我们已经作好面对伊利丹的准备了。', `FemaleText_loc5`='我們已經準備好對付伊利丹了。', `FemaleText_loc7`='Estamos listos para enfrentarnos a Illidan.' WHERE `ID`=20903;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용서하십시오, 왕자님... 제가... 졌습니다.', `MaleText_loc4`='原谅我，王子殿下！我……失败了。', `MaleText_loc5`='原諒我，我的王子!我...失敗了。', `MaleText_loc7`='¡Perdóname mi Príncipe! He... fracasado.' WHERE `ID`=20904;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='각오 단단히 해라!', `MaleText_loc4`='我来了！', `MaleText_loc5`='準備應戰!', `MaleText_loc7`='¡Prepárense!' WHERE `ID`=20905;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경고! 제거 대상 발견!', `MaleText_loc4`='警报！消灭入侵者。', `MaleText_loc5`='警告!你已經被標記為消滅的對象。', `MaleText_loc7`='¡Alerta! Están marcados para exterminación.' WHERE `ID`=20906;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시스템 종... 료...', `MaleText_loc4`='系统……关闭……', `MaleText_loc5`='系統...關...閉...', `MaleText_loc7`='El sistema se está... ce-rran-do.' WHERE `ID`=20907;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제거 완료', `MaleText_loc4`='目标已终结。', `MaleText_loc5`='消滅成功。', `MaleText_loc7`='Exterminación ejecutada.' WHERE `ID`=20908;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무단 침입 생명체 기능 정지.', `MaleText_loc4`='入侵生命体已经停止运转。', `MaleText_loc5`='入侵生命體已失去生命跡象。', `MaleText_loc7`='Forma de vida invasiva no operativa.' WHERE `ID`=20909;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위협 요소 제압.', `MaleText_loc4`='威胁已排除。', `MaleText_loc5`='威脅解除。', `MaleText_loc7`='Amenaza neutralizada.' WHERE `ID`=20910;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대체 공격 실행 중...', `MaleText_loc4`='备用方案启动……', `MaleText_loc5`='開始執行另一個計畫...', `MaleText_loc7`='Iniciando medida alternativa...' WHERE `ID`=20911;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파괴력 변수 계산 중...', `MaleText_loc4`='计算力量参数……', `MaleText_loc5`='計算敵方參數中...', `MaleText_loc7`='Calculando parámetros de fuerza...' WHERE `ID`=20912;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 내 피는 충분한 보상이 아니었단 말인가? 좋다, 우리가 그대의 비전 정수를 되찾도록 해 주겠나? 그런 후에는 발사스에게 빚진 것이 없게 되겠군.', `MaleText_loc4`='这样看来仅凭我的血还不足够来偿还这一切，是吗？好吧，那么再让我恢复你的奥术精华。在这之后，我和巴塔斯就两清了。', `MaleText_loc5`='所以我的血不足以回報，是嗎?很好，讓我們取回你的秘法精華。這之後，我將不再虧欠巴薩斯。', `MaleText_loc7`='Así que mi sangre no fue pago suficiente, ¿eh? Bien, deja que recuperemos tu esencia arcana. Al fin y al cabo no le debo nada a Balthas.' WHERE `ID`=20913;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 소환 더미에 우상을 올려놓습니다.', `MaleText_loc4`='%s在仪式堆上放下一座小雕像。', `MaleText_loc5`='%s在這個儀式中央放置了一個神像。', `MaleText_loc7`='%s coloca un fetiche en la pila ritual.' WHERE `ID`=20914;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일의 진행이 험난하군. 먼저 정령들의 하수인을 소환해야 하네. 그런 후에 그 하수인을 처치하여 내 부하들이 준비를 할 수 있도록 하는 것이야.', `MaleText_loc4`='整个过程将会非常艰巨。我们必须首先召唤出元素侍僧。而你则必须打败这些侍僧，这样一来我的随从就能开始做准备了。', `MaleText_loc5`='過程很費力。我們必須先召喚元素侍僧。然後你一定要殺掉這些侍僧們好讓我們屬下能夠進行準備。', `MaleText_loc7`='El proceso es arduo. Primero debemos invocar a los acólitos de los elementos. Entonces debes destruir a estos acólitos para que mis secuaces puedan preparase.' WHERE `ID`=20915;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘했다! 계속 진행하도록 하지.', `MaleText_loc4`='干得好！让我们继续。', `MaleText_loc5`='做得好!我們繼續吧。', `MaleText_loc7`='¡Bien hecho! Continuemos...' WHERE `ID`=20916;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비하라! 물의 하수인이 곧 나타날 것이니...', `MaleText_loc4`='准备好！水之侍僧很快就要来了……', `MaleText_loc5`='準備好你們自己!水元素侍僧很快就出現了...', `MaleText_loc7`='¡Preparaos! Pronto llegará el acólito de agua.' WHERE `ID`=20917;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나타나라, 대지의 하수인이여!', `MaleText_loc4`='出来吧，地之侍僧！', `MaleText_loc5`='出來吧，土元素侍僧!', `MaleText_loc7`='¡Ven, acólito de tierra!' WHERE `ID`=20918;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불의 하수인이여, 그대의 모습을 드러내라!', `MaleText_loc4`='火之侍僧，现身吧！', `MaleText_loc5`='火，現身吧!', `MaleText_loc7`='¡Muéstrate, fuego!' WHERE `ID`=20919;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 완전무결한 비전 정령을 소환하도록 하지.', `MaleText_loc4`='现在，我们将召唤奥术侍僧。', `MaleText_loc5`='現在將召喚秘法侍僧。', `MaleText_loc7`='Ahora invocamos al acólito arcano.' WHERE `ID`=20920;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희는 내 인내심을 시험하고 있구나!', `MaleText_loc4`='你在考验我的耐心，蠢货！', `MaleText_loc5`='你在試我的耐性，海灘定居者!', `MaleText_loc7`='¡Agotáis mi paciencia, habitantes de la costa!' WHERE `ID`=20921;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이만하면 됐다! 나 나젠투스의 분노를 맛보아라!', `MaleText_loc4`='够了！尝尝高阶督军纳因图斯的真正怒火吧！', `MaleText_loc5`='夠了!嘗嘗高階督軍納珍塔斯的盛怒吧!', `MaleText_loc7`='¡Basta! ¡Sentid toda la furia del gran señor de la guerra Naj''entus!' WHERE `ID`=20922;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='쉬! 조용히 하세요. 아기가 깨겠어요.', `FemaleText_loc4`='嘘！小声点。孩子们正在睡觉。', `FemaleText_loc5`='噓!把你的聲音壓低。寶寶們在睡覺。', `FemaleText_loc7`='¡Shhh! Habla más bajo. Los bebés están durmiendo.' WHERE `ID`=20923;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 자신의 $g왕:여왕;이 화가 난 것을 보고 몸을 웅크립니다.', `MaleText_loc4`='%s看到他的$g国王:女王;大发雷霆之后退缩了。', `MaleText_loc5`='這個%s在他憤怒的$g國王:女王;的注視下抖縮著。', `MaleText_loc7`='El %s se acobarda ante la visión de su $g rey : reina; $g furioso : furiosa;.' WHERE `ID`=20925;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; $n|1을;를; 만나려고 몸단장을 하고는 오우거만이 할 수 있을 것만 같은 방귀를 뀝니다.', `MaleText_loc4`='%s看到$n之后，一不小心放了个典型的食人魔的屁。', `MaleText_loc5`='%s與$n擦身而過並放了個只有巨魔才做得到的屁。', `MaleText_loc7`='%s se roza con $n y se tira un pedo como solo los ogros saben.' WHERE `ID`=20926;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나도 방귀뀌는 거 좋아한다!', `MaleText_loc4`='我也喜欢放屁！', `MaleText_loc5`='我也喜歡放屁!', `MaleText_loc7`='¡A mí también gustar tirar pedos!' WHERE `ID`=20927;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아우, 우리 사이는 이뤄지지 않는다.', `MaleText_loc4`='啊，我不觉得我们两个合适。', `MaleText_loc5`='哇，我不覺得我們之間會有結果的。', `MaleText_loc7`='Oh, yo no creer que lo nuestro funcione.' WHERE `ID`=20928;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 뭘 잘못했나, 내 $g왕:여왕;님?', `MaleText_loc4`='我做错了什么，我的$g国王:女王;陛下？', `MaleText_loc5`='我做錯了什麼，我的$g國王:女王;?', `MaleText_loc7`='¿Qué hacer yo mal, mi $grey:reina;?' WHERE `ID`=20929;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='윽, 때리지 마라!!', `MaleText_loc4`='不要伤害我！', `MaleText_loc5`='沒有受傷!!', `MaleText_loc7`='¡No hacer daño!' WHERE `ID`=20930;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='심연의 해일이 집어삼키리라!', `MaleText_loc4`='深渊中的洪水会淹没你们！', `MaleText_loc5`='深海的洪水，淹沒吧!', `MaleText_loc7`='¡Que las profundidades los arrastren!' WHERE `ID`=20931;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수렁꽃이 터지자 꽃가루가 사방으로 흩날립니다.', `MaleText_loc4`='沼泽花爆炸了，猛烈地喷射着花粉。', `MaleText_loc5`='泥沼花爆開，四處噴灑花粉。', `MaleText_loc7`='El cardo de Mantar explota, llenándolo todo de polen.' WHERE `ID`=20932;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바다의 힘으로!', `MaleText_loc4`='以潮汐的名义！', `MaleText_loc5`='以浪潮之名!', `MaleText_loc7`='¡Por las mareas!' WHERE `ID`=20933;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나의 피조물들아, 놈들을 파괴하라!', `MaleText_loc4`='我的仆从，干掉他们！', `MaleText_loc5`='毀滅他們，我的服從者!', `MaleText_loc7`='¡Destrúyanlos, súbditos míos!' WHERE `ID`=20934;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='숨을 곳은 아무 데도 없다!', `MaleText_loc4`='你们无处可逃！', `MaleText_loc5`='這裡是無處可躲的!', `MaleText_loc7`='¡No se pueden esconder!' WHERE `ID`=20935;
