UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$c|1이여;여;, 어서 상황을 파악하고 정신 차리는 게 좋을 겁니다. 이곳은 스케티스에 있는 멋진 뒤뜰이 아니라 칼날 산맥이란 말입니다! 경솔하게 행동하면 추락하고 불에 탈 겁니다!', `FemaleText_loc4`='你最好快点醒来，新人。这里不是斯克提斯外的某个舒适的后院，这里是刀锋山！一不小心就会导致灾难性的后果！', `FemaleText_loc5`='你最好快點醒過來，菜鳥。這可不是我們在司凱堤斯外的尋常後院;這裡是劍刃山脈!一個失誤就會造成爆炸並燒毀!', `FemaleText_loc7`='Será mejor que te despiertes rápido, novato. Esto no es nuestro cómodo patio trasero en Skettis, ¡esto son las Montañas Filospada! ¡Un paso en falso y será caer y arder!' WHERE `ID`=20967;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좀 더 준비를 갖추고 오게나.', `MaleText_loc4`='准备好以后再到我这里来。', `MaleText_loc5`='等你準備充足後再回來找我。', `MaleText_loc7`='Vuelve a mí cuando estés mejor preparado.' WHERE `ID`=20968;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정수가 주입된 월장석을 잃어버렸습니다. 다시 받을 수 있을까요?', `MaleText_loc4`='我遗失了灌注精华的月亮石。你能再给我一个吗？', `MaleText_loc5`='我遺失了我的精華灌注的月亮石。你能找回它嗎?', `MaleText_loc7`='He perdido mi piedra lunar imbuida de esencia. ¿Me puedes conseguir otra?', `FemaleText_loc1`='정수가 주입된 월장석을 잃어버렸습니다. 다시 받을 수 있을까요?', `FemaleText_loc4`='我遗失了灌注精华的月亮石。你能再给我一个吗？', `FemaleText_loc5`='我遺失了我的精華灌注的月亮石。你能找回它嗎?', `FemaleText_loc7`='He perdido mi piedra lunar imbuida de esencia. ¿Me puedes conseguir otra?' WHERE `ID`=20969;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 세계에 계속 머무르려면 너의 생명의 정수가 필요하다.', `MaleText_loc4`='我需要你的生命精华，只有这样我才能在这个位面继续生存下去。', `MaleText_loc5`='我需要你的生命精華來維持我在這個領域的存在。', `MaleText_loc7`='Necesito tu esencia vital para conservar mi presencia en este reino.' WHERE `ID`=20970;
