UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대용광로가 있는 동쪽 지역에서 약간 북쪽으로 가면 선견자 야바드를 만날 수 있답니다.', `MaleText_loc4`='好吧，现在，你立刻前往大锻炉那里找先知亚瓦德，就在东边略微往北一点。', `MaleText_loc5`='好啦現在，你可以去大鍛爐找先知賈瓦德，就在東邊偏北那裡。', `MaleText_loc7`='Bueno, puedes encontrar al clarividente Javad en la zona de la Gran Fundición, ligeramente hacia el norte del lateral este.', `FemaleText_loc1`='대용광로가 있는 동쪽 지역에서 약간 북쪽으로 가면 선견자 야바드를 만날 수 있답니다.', `FemaleText_loc4`='好吧，现在，你立刻前往大锻炉那里找先知亚瓦德，就在东边略微往北一点。', `FemaleText_loc5`='好啦現在，你可以去大鍛爐找先知賈瓦德，就在東邊偏北那裡。', `FemaleText_loc7`='Bueno, puedes encontrar al clarividente Javad en la zona de la Gran Fundición, ligeramente hacia el norte del lateral este.' WHERE `ID`=20972;
