UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상급기사 피레아노르는 지혜의 골짜기에 있는 스랄의 그롬마쉬 요새에 있네.', `MaleText_loc4`='身为萨尔酋长大人的顾问，派雷亚诺一直待在智慧谷的格罗玛什要塞里。', `MaleText_loc5`='你可以在智慧谷，葛羅瑪許堡，索爾的顧問群中找到大師皮禮諾。', `MaleText_loc7`='Puedes encontrar al maestro Pyreanor entre los consejeros de Thrall en el Fuerte Grommash, en el Valle de la Sabiduría.', `FemaleText_loc1`='상급기사 피레아노르는 지혜의 골짜기에 있는 스랄의 그롬마쉬 요새에 있네.', `FemaleText_loc4`='身为萨尔酋长大人的顾问，派雷亚诺一直待在智慧谷的格罗玛什要塞里。', `FemaleText_loc5`='你可以在智慧谷，葛羅瑪許堡，索爾的顧問群中找到大師皮禮諾。', `FemaleText_loc7`='Puedes encontrar al maestro Pyreanor entre los consejeros de Thrall en el Fuerte Grommash, en el Valle de la Sabiduría.' WHERE `ID`=20975;
