UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대사 돈싱어 님과 저는 태양 궁정을 대표하여 오그리마에 파견되었습니다.$B$B대사께서는 외교 문제를 다루시고 저는 군사 작전과 고유한 어.. 혈기사의 강점에 대해 스랄 님께 조언을 드리고 있습니다.', `MaleText_loc4`='我和银月大使帕拉·晨歌代表逐日王庭来到奥格瑞玛。$B$B大使负责处理各种民事问题，而我则对萨尔提出军事建议，以及宣扬与血骑士合作的……呃，独一无二的优势。', `MaleText_loc5`='曦詠大使和我是太陽王廷在奧格瑪的代表。$B$B大使負責一般事務，而我則是負責索爾軍事活動以及特殊，呃...利益的顧問。', `MaleText_loc7`='La Embajadora Cantoalba y yo representamos a la Corte del Sol aquí, en Orgrimmar.$B$BLa Embajadora se encarga de los asuntos civiles, mientras que yo aconsejo a Thrall sobre campañas militares y las err... ventajas únicas otorgadas por los Caballeros de sangre.' WHERE `ID`=20978;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더욱 강한 나루의 힘에 대해 가르침을 내려주십시오.', `MaleText_loc4`='继续指导我如何使用纳鲁的力量吧。', `MaleText_loc5`='進一步指導我使用那魯的力量。', `MaleText_loc7`='Instruyeme más a fondo acerca del uso del poder de los naaru.', `FemaleText_loc1`='더욱 강한 나루의 힘에 대해 가르침을 내려주십시오.', `FemaleText_loc4`='继续指导我如何使用纳鲁的力量吧。', `FemaleText_loc5`='進一步指導我使用那魯的力量。', `FemaleText_loc7`='Instruyeme más a fondo acerca del uso del poder de los naaru.' WHERE `ID`=20979;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 돌로 되돌아갑니다.', `MaleText_loc4`='%s回到了石化状态。', `MaleText_loc5`='%s回到石頭那。', `MaleText_loc7`='%s se vuelve de piedra.' WHERE `ID`=20980;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신앙의 징표... 있고, 양초... 있고... 불가사의한 가루... 음... 불가사의한 가루? 오, 젠장! 여행자들을 위해서 마법 재료들을 가져오는 건 이번이 마지막이라고. 이 근처에 상인 없나요?', `MaleText_loc4`='神圣符印？有了。蜡烛？有了。魔粉，嗯……魔粉？啊，该死的！我再也不要帮别人带施法材料了。这附近有商人吗？', `MaleText_loc5`='神聖符印?有。蠟燭?有。秘法粉末，呃...秘法粉末?喔，不會吧!這是我最後一次為大家收拾藥劑了。這裡附近有商人嗎?', `MaleText_loc7`='¿Símbolos de divinidad? Correcto. ¿Velas? Correcto. Partículas Arcanas...eh... ¿partículas Arcanas? ¡Oh no! Esta es la última vez que me ofrezco a recoger reactivos. ¿Hay algún vendedor por aquí?', `FemaleText_loc1`='신앙의 징표... 있고, 양초... 있고... 불가사의한 가루... 음... 불가사의한 가루? 오, 젠장! 여행자들을 위해서 마법 재료들을 가져오는 건 이번이 마지막이라고. 이 근처에 상인 없나요?', `FemaleText_loc4`='神圣符印？有了。蜡烛？有了。魔粉，嗯……魔粉？啊，该死的！我再也不要帮别人带施法材料了。这附近有商人吗？', `FemaleText_loc5`='神聖符印?有。蠟燭?有。秘法粉末，呃...秘法粉末?喔，不會吧!這是我最後一次為大家收拾藥劑了。這裡附近有商人嗎?', `FemaleText_loc7`='¿Símbolos de divinidad? Correcto. ¿Velas? Correcto. Partículas Arcanas...eh... ¿partículas Arcanas? ¡Oh no! Esta es la última vez que me ofrezco a recoger reactivos. ¿Hay algún vendedor por aquí?' WHERE `ID`=20981;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='근처에 마법사분 안 계시나요? 물과 빵을 좀 얻어야 하는데...', `MaleText_loc4`='这附近有法师吗？我应该带些水和食物的……', `MaleText_loc5`='這裡附近有法師嗎?我以為有帶食物跟水...', `MaleText_loc7`='¿Hay algún mago por aquí? Se supone que tengo que llevar el agua y la comida...', `FemaleText_loc1`='근처에 마법사분 안 계시나요? 물과 빵을 좀 얻어야 하는데...', `FemaleText_loc4`='这附近有法师吗？我应该带些水和食物的……', `FemaleText_loc5`='這裡附近有法師嗎?我以為有帶食物跟水...', `FemaleText_loc7`='¿Hay algún mago por aquí? Se supone que tengo que llevar el agua y la comida...' WHERE `ID`=20982;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게 물약을 원하는 다음 사람에겐 도가니 샌드위치를 드리지요. 이제 연금술은 안 할 거라고요!', `MaleText_loc4`='谁再问我要药水，我就揍他。我再也不当炼金师了！', `MaleText_loc5`='下一個跟我要求藥劑的人會得到迎面一拳。我不做鍊金術了!', `MaleText_loc7`='El próximo que me pida una poción se va a comer un bocadillo de nudillos. ¡Dejo la alquimia!', `FemaleText_loc1`='내게 물약을 원하는 다음 사람에겐 도가니 샌드위치를 드리지요. 이제 연금술은 안 할 거니까요!', `FemaleText_loc4`='谁再问我要药水，我就揍他。我再也不当炼金师了！', `FemaleText_loc5`='下一個跟我要求藥劑的人會得到迎面一拳。我不做鍊金術了!', `FemaleText_loc7`='El próximo que me pida una poción se va a comer un bocadillo de nudillos. ¡Dejo la alquimia!' WHERE `ID`=20983;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이보라고, 친구. 지금 당장 저 그리핀 중 한 녀석을 썼으면 하는데 말이야...', `MaleText_loc4`='亲娘哎，要是可以骑狮鹫就好了……', `MaleText_loc5`='小子，我現在真的就要使用一隻獅鷲獸...', `MaleText_loc7`='Tío, un grifo de esos me vendría de perlas ahora...', `FemaleText_loc1`='이보세요. 지금 당장 저 그리핀 중 한 녀석을 썼으면 하는데요...', `FemaleText_loc4`='亲娘哎，要是可以骑狮鹫就好了……', `FemaleText_loc5`='小子，我現在真的就要使用一隻獅鷲獸...', `FemaleText_loc7`='Tío, un grifo de esos me vendría de perlas ahora...' WHERE `ID`=20984;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 당신께 보석세공에 대해 알려드릴 수 있습니다. 관심 있으신가요?', `MaleText_loc4`='我可以教你珠宝加工。有兴趣吗？', `MaleText_loc5`='我可以指導你珠寶設計。有興趣嗎?', `MaleText_loc7`='Puedo enseñarte joyería. ¿Te interesa?', `FemaleText_loc1`='전 당신께 보석세공에 대해 알려드릴 수 있습니다. 관심 있으신가요?', `FemaleText_loc4`='我可以教你珠宝加工。有兴趣吗？', `FemaleText_loc5`='我可以指導你珠寶設計。有興趣嗎?', `FemaleText_loc7`='Puedo enseñarte joyería. ¿Te interesa?' WHERE `ID`=20985;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 이 벽 서 있지 않은 거지? 나 계속 두드리고 있는데 소용없군!', `MaleText_loc4`='为什么这堵墙还没建起来？我一直在敲打，但是毫无效果！', `MaleText_loc5`='為什麼這面牆不倒?我一直敲打都沒用!', `MaleText_loc7`='¿Por qué esta pared no tenerse tiesa? ¡Yo seguir golpeando pero no servir de nada!' WHERE `ID`=20986;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절 불러주셔서 감사해요, 작은 분. 우리 일행이 절 버리고 던전으로 떠나버렸거든요!', `MaleText_loc4`='谢谢你召唤我，小家伙。我的队伍把我丢在这里，就直接跑进地下城了！', `MaleText_loc5`='謝謝你的召喚，小東西。我的隊伍沒帶我就前往地城了!', `MaleText_loc7`='Gracias por la invocación, pequeño. ¡Mi grupo se ha ido a la mazmorra sin mí!', `FemaleText_loc1`='절 불러주셔서 감사해요, 작은 분. 우리 일행이 절 버리고 던전으로 떠나버렸거든요!', `FemaleText_loc4`='谢谢你召唤我，小家伙。我的队伍把我丢在这里，就直接跑进地下城了！', `FemaleText_loc5`='謝謝你的召喚，小東西。我的隊伍沒帶我就前往地城了!', `FemaleText_loc7`='Gracias por la invocación, pequeño. ¡Mi grupo se ha ido a la mazmorra sin mí!' WHERE `ID`=20987;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 이 벽 쓰러지지 않는 거지? 뭐냐고?', `MaleText_loc4`='为什么这堵墙还没有倒下？你在干什么？', `MaleText_loc5`='為什麼這面牆不倒下?怎麼做?', `MaleText_loc7`='¿Por qué esta pared no caer? ¿Qué hacer?' WHERE `ID`=20988;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기, 멍청이! 왜 벽 두드리는 거야? 벽 세우는 거지 쓰러지는 거 아니야! 멍청한 오크 같으니! 세워! 세우라고!', `MaleText_loc4`='嘿，蠢货！为什么你要敲这堵墙？我们是要建造墙而不是弄倒它！愚蠢的兽人！建造！我说的是建造！', `MaleText_loc5`='嗨笨蛋!為什麼你要擊打牆壁啊?牆只會起不會倒!笨獸人員!起來!起來!', `MaleText_loc7`='¡Hey estúpido! ¿Por qué golpear pared? ¡Pared subir no bajar! ¡Estúpido orco! ¡Arriba! ¡Arriba!' WHERE `ID`=20989;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말 멋졌어요!', `FemaleText_loc4`='太棒了！', `FemaleText_loc5`='那真整齊!', `FemaleText_loc7`='¡Ha sido efectivo!' WHERE `ID`=20990;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일어나라, 내 아이들아. 너의 주인을 도와라!', `MaleText_loc4`='醒来吧，我的孩子，来帮助你们的主人！', `MaleText_loc5`='醒來，我的孩子們，協助你的主人!', `MaleText_loc7`='¡Despertien hijos míos y ayuden a su amo!' WHERE `ID`=20991;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 원하나? 타락한 오크치고는 냄새가 이상하군...', `MaleText_loc4`='你想要什么？作为一名邪兽人，你闻上去有点古怪……', `MaleText_loc5`='你想要什麼?對魔獄獸人聞起來很古怪...', `MaleText_loc7`='¿Qué querer? Oler raro para ser orco vil...' WHERE `ID`=20992;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 그렇게 어슬렁거리지? 먹을 거라도 필요한 건가?', `MaleText_loc4`='你不是想把这里当做自己家吧。也许你想吃点什么？', `MaleText_loc5`='你沒將這裡當你的家。或許你想吃點什麼東西?', `MaleText_loc7`='Tú no sentir como en tu casa. ¿Quizá querer comer algo?' WHERE `ID`=20993;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 팔고 있습니까?', `MaleText_loc4`='你出售什么货物？', `MaleText_loc5`='你有什麼東西要賣嗎?', `MaleText_loc7`='¿Qué vendes?', `FemaleText_loc1`='뭘 팔고 있나요?', `FemaleText_loc4`='你出售什么货物？', `FemaleText_loc5`='你有什麼東西要賣嗎?', `FemaleText_loc7`='¿Qué vendes?' WHERE `ID`=20994;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 장비를 고쳐주세요. 그럼 물건을 살지도 모르지요.', `MaleText_loc4`='我想让古格修护甲。也许我还会买点什么。', `MaleText_loc5`='我要賈格修護甲。也許我會買點什麼東西來著。', `MaleText_loc7`='Yo querer que Gug arreglar armadura. Quizá yo comprar algo.', `FemaleText_loc1`='제 장비를 고쳐주세요. 그럼 물건을 살지도 모르지요.', `FemaleText_loc4`='我想让古格修护甲。也许我还会买点什么。', `FemaleText_loc5`='我要賈格修護甲。也許我會買點什麼東西來著。', `FemaleText_loc7`='Yo querer que Gug arreglar armadura. Quizá yo comprar algo.' WHERE `ID`=20995;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='때때로 저 가증스러운 블러드 엘프 녀석들이 들러서는 어처구니없는 재료나 독을 요구하기도 하지. 난 일리단 군주님께 용아귀 부족이 비협조적이라는 말을 들을까 봐 항상 재고를 가득 채워놔야 한다고...$B$B<침을 꿀꺽 삼키는 럼푸스>$B$B우린 그렇게 되길 바라지 않아...', `MaleText_loc4`='有时候，那些该死的血精灵会顺路从我这里购买一些特殊的材料或是毒药。我必须随时保持这类货源，以免谣言传到伊利丹大人耳朵里，说龙喉氏族不与血精灵合作……$B$B<鲁姆普斯艰难地咽了口气。>$B$B我们可不希望发生那种事……', `MaleText_loc5`='有時候那些該死的血精靈會停下來並要求一些愚蠢的藥劑或毒藥。我必須隨時保持此類物品的存貨充足免得伊利丹王聽到龍喉不配合...$b$b<藍普斯艱難的吞了口水。>$B$B我們不想要那樣...', `MaleText_loc7`='A veces esos detestables elfos de sangre vienen por aquí y necesitan algún reactivo inane o algún veneno. Tengo que mantener mis reservas de esos productos llenas todo el tiempo para que no le lleguen rumores a Lord Illidan de que los Faucedraco no están colaborando...$B$B<Rumpus traga con dificultad>$B$BNo queremos que pase eso...', `FemaleText_loc1`='때때로 저 가증스러운 블러드 엘프 놈들이 들러서는 어처구니없는 재료나 독을 요구하기도 하지. 난 일리단 군주님께 용아귀 부족이 비협조적이라는 말을 들을까 봐 항상 재고를 가득 채워놔야 한다고...$B$B<침을 꿀꺽 삼키는 럼푸스>$B$B우린 그렇게 되길 바라지 않아...', `FemaleText_loc4`='有时候，那些该死的血精灵会顺路从我这里购买一些特殊的材料或是毒药。我必须随时保持这类货源，以免谣言传到伊利丹大人耳朵里，说龙喉氏族不与血精灵合作……$B$B<鲁姆普斯艰难地咽了口气。>$B$B我们可不希望发生那种事……', `FemaleText_loc5`='有時候那些該死的血精靈會停下來並要求一些愚蠢的藥劑或毒藥。我必須隨時保持此類物品的存貨充足免得伊利丹王聽到龍喉不配合...$b$b<藍普斯艱難的吞了口水。>$B$B我們不想要那樣...', `FemaleText_loc7`='A veces esos detestables elfos de sangre vienen por aquí y necesitan algún reactivo inane o algún veneno. Tengo que mantener mis reservas de esos productos llenas todo el tiempo para que no le lleguen rumores a Lord Illidan de que los Faucedraco no están colaborando...$B$B<Rumpus traga con dificultad>$B$BNo queremos que pase eso...' WHERE `ID`=20996;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파는 물건을 보여주십시오, 럼푸스.', `MaleText_loc4`='你有什么特别的货物吗，鲁姆普斯？', `MaleText_loc5`='你有什麼要賣嗎，藍普斯?', `MaleText_loc7`='¿Qué vendes, Rumpus?', `FemaleText_loc1`='파는 물건을 보여주십시오, 럼푸스.', `FemaleText_loc4`='你有什么特别的货物吗，鲁姆普斯？', `FemaleText_loc5`='你有什麼要賣嗎，藍普斯?', `FemaleText_loc7`='¿Qué vendes, Rumpus?' WHERE `ID`=20997;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 좋아! 이 총 맛을 보고 싶은 거로군, 멍청이? 이리 들어오라고!', `MaleText_loc4`='哦耶！你想尝尝这些枪支的威力吗，渣滓？走近点！', `MaleText_loc5`='喔耶!你想要試看看這些槍嗎，蠢蛋?', `MaleText_loc7`='¡OH SÍ! ¿Quieres probar estas pistolas, gusano? ¡Entra!' WHERE `ID`=20998;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 비단뱀과 어떻게 겨루겠다는 거지? 오오오오, 좋오오오오아, 친구!', `MaleText_loc4`='你怎么和这些巨蟒扭打的？哦哦哦，呀呀呀，兄弟！', `MaleText_loc5`='你要怎麼和這些巨蟒對抗?嗚喔耶耶耶，兄弟!', `MaleText_loc7`='¿Cómo compites contra estas serpientes pitón? ¡Oooooooooh uaaaaaaa, $ghermano:hermana;!' WHERE `ID`=20999;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 소리 들리나? 환호하는 소리가 들리냔 말이다, 친구? 다 이 럴크스터에게 응원을 보내고 있단 말이다!', `MaleText_loc4`='听见了吗？你听见颂歌了吗，兄弟？他们正在为鲁克斯特欢呼！', `MaleText_loc5`='你聽到嗎?你聽到那首曲子嗎，兄弟?他們在為洛克斯人歡呼!', `MaleText_loc7`='¿Has oído eso? ¿Has oído ese canto, $ghermano:hermana;? ¡Están animando al Julkster!' WHERE `ID`=21000;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='럴크광이 사납게 달려들면 어찌할 거냐, 이 녀석????!', `MaleText_loc4`='如果疯狂的鲁克斯特对你大发雷霆，你准备怎么做，兄弟？！', `MaleText_loc5`='你準備在Rulk-a-mania對你暴走時怎麼做呢，兄弟????!', `MaleText_loc7`='¡¿¿¿Qué harás cuando la Julkomanía te atrape???!' WHERE `ID`=21001;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<지리 주위의 광채가 푸른 빛을 띱니다. 이 나루가 전장에 함께하는 동맹으로서 당신을 환영하고 있습니다.>', `MaleText_loc4`='<克希利浑身散发着红色的光芒。纳鲁在欢迎你这位盟友。>', `MaleText_loc5`='<圍繞在希瑞身邊的光跳動地轉為藍色。那魯歡迎你如戰場中的盟友一般。>', `MaleText_loc7`='<La luz que rodea a Xi''ri parpadea en azul. El naaru te da la bienvenida como aliado en el campo de batalla.>' WHERE `ID`=21002;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지리, 당신의 군대와 전투를 함께할 준비가 되었습니다.', `MaleText_loc4`='我愿意与你的军队并肩作战，克希利。', `MaleText_loc5`='希瑞，我準備好參加你的軍隊戰鬥。', `MaleText_loc7`='Estoy preparado para unirme a tus fuerzas en la batalla, Xi''ri.', `FemaleText_loc1`='지리, 당신의 군대와 전투를 함께할 준비가 되었어요.', `FemaleText_loc4`='我愿意与你的军队并肩作战，克希利。', `FemaleText_loc5`='希瑞，我準備好參加你的軍隊戰鬥。', `FemaleText_loc7`='Estoy preparado para unirme a tus fuerzas en la batalla, Xi''ri.' WHERE `ID`=21003;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저곳에 있는 수정들을 확인하라!', `MaleText_loc4`='检查那里的水晶簇！', `MaleText_loc5`='去檢查那邊那些水晶!', `MaleText_loc7`='¡Inspecciona aquellos cristales de allí!' WHERE `ID`=21004;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무것도 못 찾았다고? 좋아. 그럼 저쪽을 확인하라.', `MaleText_loc4`='什么都没找到？好吧。去另一簇看看。', `MaleText_loc5`='你什麼都沒找到?很好。那邊下一個。', `MaleText_loc7`='¿No has encontrado nada? Muy bien. Continúa por allí.' WHERE `ID`=21005;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 부대는 장래성이 있어 보이는군.', `MaleText_loc4`='那簇水晶似乎有异样。', `MaleText_loc5`='那個隊伍看起來很有前途。', `MaleText_loc7`='Esa agrupación parece prometedora.' WHERE `ID`=21006;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 찾고 있는 걸 찾으면 보상을 얻게 될 수도 있다.', `MaleText_loc4`='如果你能帮我找到我梦寐以求的东西，我会好好奖励你的。', `MaleText_loc5`='找到我在尋找的東西，你就可以得到一點甜頭。', `MaleText_loc7`='Encuentra lo que estoy buscando y puede que obtengas algo a cambio.' WHERE `ID`=21007;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 쓸모없다는 생각이 드는구나. 더는 날 실망시키지 마라.', `MaleText_loc4`='我有些怀疑你是个没用的家伙了。不要再让我失望！', `MaleText_loc5`='我開始懷疑你沒有用途。不要再讓我失望了。', `MaleText_loc7`='Empiezo a pensar que no sirves para nada. No me decepciones aún más.' WHERE `ID`=21008;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 바로 그거다. 이번 일은 잘될 것이야.', `MaleText_loc4`='嗯，这些不错。', `MaleText_loc5`='沒錯，就是那個。這些將會做得很精巧。', `MaleText_loc7`='Sí, eso es. Estas servirán.' WHERE `ID`=21009;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$G형제:자매;여, 그대는 황천의 용군단과 피로 결속되어 있다는 걸 잊지 마십시오. 모든 황천의 용군단이 그대를 지지할 것입니다! 적의 심장부를 공격할 때가 바로 지금입니다, 동지여! 우리의 잃어버린 유산을 되찾아야 합니다.', `MaleText_loc4`='你与灵翼龙族结下了深厚的情谊，我们都愿意在背后支持你！朋友，现在就给予我们的敌人致命一击吧！我们必须夺回失去的一切。', `MaleText_loc5`='$G兄弟:姐妹;，你現在經由鮮血的認定與虛空之翼建立密切的關係。現在所有虛空之翼都將會支持你!當下就是打擊我們敵人中心的時候，朋友!我們必須復興我們失去的傳統。', `MaleText_loc7`='$G Hermano:Hermana;, a partir de ahora se te considera $g unido:unida; por la sangre al Ala Abisal. ¡El Ala Abisal al completo está detrás de ti ahora! ¡Ha llegado el momento de atacar al corazón de nuestros enemigos! Debemos reclamar nuestra herencia perdida.' WHERE `ID`=21010;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 우리의 대의를 위해 많은 일을 해 주었습니다. 하지만 날아다니는 탈것 타기의 대가가 되지 않고선 더는 우리와 일을 하지 못하겠군요. 타기의 대가만이 황천날개를 지원할 수 있습니다.', `MaleText_loc4`='你帮了灵翼龙族许多忙，$n。但是在你掌握更高级的骑术之前，是无法有什么进展的。只有最坚定的骑士才能帮助灵翼龙族。', `MaleText_loc5`='你已經為了我們做了許多，$n，但是直到你學會飛行前你可能無法在更進一步了。只有最勇敢的騎士才有辦法協助虛空之翼。', `MaleText_loc7`='Has sido de gran ayuda para nuestra causa, $n, pero no podrás seguir avanzando hasta que domines el arte del vuelo. Solo los jinetes más hábiles pueden ayudar a los Ala Abisal.' WHERE `ID`=21011;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래... 그 대단한 주문을 한번 외워 보거라, 아카아악!', `MaleText_loc4`='是的……施放你珍贵的小法术吧，呱——啊——呱！', `MaleText_loc5`='是的...施展你珍貴的小法術吧，呀喀-啊-呀喀!', `MaleText_loc7`='¡Sí...invoca tus preciosos hechicitos, ak-a-ak!' WHERE `ID`=21012;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비밀 암호를 입력하고 제 황금돼지를 받고 싶습니다.', `MaleText_loc4`='我想要输入神秘兑换码来换取我的金猪宠物。', `MaleText_loc5`='我想要輸入驗證碼以領取我的金豬寵物。', `MaleText_loc7`='Me gustaría introducir el código secreto para recibir mi mascota Cerdo Dorado.', `FemaleText_loc1`='비밀 암호를 입력하고 제 황금돼지를 받고 싶어요.', `FemaleText_loc4`='我想要输入神秘兑换码来换取我的金猪宠物。', `FemaleText_loc5`='我想要輸入驗證碼以領取我的金豬寵物。', `FemaleText_loc7`='Me gustaría introducir el código secreto para recibir mi mascota Cerdo Dorado.' WHERE `ID`=21013;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요. 얼마 전에 열린 특별한 행사에 참가하셨나요?$B$B그렇다면 분명 비밀 암호도 받으셨겠죠? 그 암호를 알려주시면 특별한 상품을 드리죠.', `MaleText_loc4`='你好，$r。你最近有幸参加了特别的活动吧？$B$B那样的话，你可能已经得到了一组神秘兑换码。将神秘兑换码告诉我，我就送你一份特殊的奖励。', `MaleText_loc5`='你好，$r。你有幸運到參加了最近那個特別的活動嗎?$B$B如果有的話，你可能已經得到了一組神秘驗證碼。告訴我你的驗證碼我就會回報你一份特別的禮物。', `MaleText_loc7`='Saludos $r. ¿Tuviste la suerte de asistir al acontecimiento especial de hace poco?$B$BSi fuiste, es posible que hayas aprendido un código secreto. Dime tu código y, a cambio, te daré un premio especial.', `FemaleText_loc1`='안녕하세요. 얼마 전에 열린 특별한 행사에 참가하셨나요?$B$B그렇다면 분명 비밀 암호도 받으셨겠죠? 그 암호를 알려주시면 특별한 상품을 드리죠.', `FemaleText_loc4`='你好，$r。你最近有幸参加了特别的活动吧？$B$B那样的话，你可能已经得到了一组神秘兑换码。将神秘兑换码告诉我，我就送你一份特殊的奖励。', `FemaleText_loc5`='你好，$r。你有幸運到參加了最近那個特別的活動嗎?$B$B如果有的話，你可能已經得到了一組神秘驗證碼。告訴我你的驗證碼我就會回報你一份特別的禮物。', `FemaleText_loc7`='Saludos $r. ¿Tuviste la suerte de asistir al acontecimiento especial de hace poco?$B$BSi fuiste, es posible que hayas aprendido un código secreto. Dime tu código y, a cambio, te daré un premio especial.' WHERE `ID`=21014;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 마법이 너를 무덤으로 이끌 것이다...아카아악...', `MaleText_loc4`='你的魔法将导致你的毁灭……呱——啊——呱……', `MaleText_loc5`='你的魔法就是你失敗的原因...呀喀-啊-呀喀...', `MaleText_loc7`='Tu magia será tu final... ak-a-ak...' WHERE `ID`=21015;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 능력이... 아카악... 너를 해하리라...', `MaleText_loc4`='你的力量……呱——呱……将转而对付你……', `MaleText_loc5`='你的力量...呀喀-呀喀...反擊你...', `MaleText_loc7`='Tus poderes... ak-ak... se vuelven contra ti...' WHERE `ID`=21016;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 약해 빠진... 케 코우... 마력 쯤은... 얼마든지 되돌려 주마...', `MaleText_loc4`='你的法术……呱——呱……脆弱的魔法……轻而易举地就能转而对付你……', `MaleText_loc5`='你的法術...咳-摳...是虛弱的魔法...很容易就能被反彈回去...', `MaleText_loc7`='Tus hechizos... Ke-kaw... son débiles... fáciles de volver en tu contra...' WHERE `ID`=21017;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='땅이 갈라져서 열리기 시작합니다!', `MaleText_loc4`='地面崩裂了！', `MaleText_loc5`='地上開始裂開!', `MaleText_loc7`='El suelo comienza a abrirse.' WHERE `ID`=21018;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='궁극의 심연이 분노하여 땅을 내리찍습니다!', `MaleText_loc4`='苏普雷姆斯愤怒地击打着地面！', `MaleText_loc5`='瑟普莫斯憤怒的捶擊地面!', `MaleText_loc7`='¡Supremus golpea el suelo enfadado!' WHERE `ID`=21019;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자다! 용아귀의 징표에 분노를 쏟아 부어라! 죽여라!', `MaleText_loc4`='入侵者！让龙喉的标记引导你的怒火！杀死$n！', `MaleText_loc5`='入侵者!讓龍喉的印記引導你的憤怒吧!殺了$n!', `MaleText_loc7`='¡INVASORES! ¡Dejen que la marca de los Faucedraco guíe su inquina! ¡Maten a $N!' WHERE `ID`=21020;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='도와 주실 거예요?', `FemaleText_loc4`='你要帮忙吗？', `FemaleText_loc5`='你要幫忙嗎?', `FemaleText_loc7`='¿Vas a ayudar?' WHERE `ID`=21021;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자넨 아무도 속일 수 없네. 이 황천날개 마루의 마법으로도 우리 하늘파괴단의 모든 것을 꿰뚫는 눈을 피해 자네의 정체를 속일 순 없단 말일세!', `MaleText_loc4`='你能骗得了谁，$r？在碎天者敏锐的目光中，即便是灵翼氏族的魔法也不能遮盖你的真面目！', `MaleText_loc5`='你騙不了人的，$r。就算是虛空之翼的魔法也無法讓你躲過破天者的全能之眼。', `MaleText_loc7`='No engañas a nadie, $r. ¡Ni la magia del Ala Abisal puede ocultarte de la vista de los Rompecielos que todo lo ven!' WHERE `ID`=21022;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용아귀 부족의 하늘파괴단과 선조들은 우리의 마법으로도 속지 않으니 조심해야 할 겁니다! 그들을 항상 멀리해야 한다는 걸 잊지 마십시오!', `MaleText_loc4`='小心龙喉碎天者和升腾者，他们能识破我们的魔法！和那些家伙保持距离，切记！', `MaleText_loc5`='當心龍喉破天者以及卓越者們，因為他們不會被我們的魔法給騙了!千萬要跟以上那些人保持距離!', `MaleText_loc7`='¡Ten cuidado con los Rompecielos Faucedraco y los ascendientes, ya que nuestra magia no les distrae! Mantén la distancia con esos seres.' WHERE `ID`=21023;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오우거는 굴복하지 않는다. 그론에게도, 그리고 너같은 약한 $r에게도!', `MaleText_loc4`='食人魔氏族是不会被征服的。我们绝不臣服于戈隆的统治，也不会向你这样的$r低头！', `MaleText_loc5`='巨魔氏族將不會被屈服。不會屈服於古羅，也不會屈服於像你這樣的一個$r小角色!', `MaleText_loc7`='Los clanes ogros no serán subyugados. ¡Ni por los gronn ni por $gun:una; enclenque $r como tú!' WHERE `ID`=21024;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모그도그는 멍청하다, 어떻게 오우거보다도 작은 녀석이 오우거 구할 수 있나?', `MaleText_loc4`='莫戈多格这个蠢货，居然认为那个小个子是我们的救世主。', `MaleText_loc5`='莫格多克是個以為那些小族群當中會有我們救星的蠢蛋。', `MaleText_loc7`='Mog''dorg es un insensato al creer que una de las razas menores será nuestra salvadora.' WHERE `ID`=21025;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기는 오우거의 땅이야, 그론이나 인간, 오크들의 것 아니다!', `MaleText_loc4`='这些山脉是食人魔的地盘。不是戈隆的，也不是人类和兽人的！', `MaleText_loc5`='這些山脈是巨魔的。不是古羅的，不是人類或獸人的!', `MaleText_loc7`='Estas montañas son para ogros. ¡No para gronn, no para humanos ni para orcos!' WHERE `ID`=21026;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모그도그의 꼭두각시에 복종해선 안 돼! 모그도그는 그론 주인님 몰아내고 무능한 주인 섬기려고 한다. 왜 우리 주인님 바꿔야 하지?', `MaleText_loc4`='不要向莫戈多格的傀儡低头！他不过是想以此取代戈隆大王的统治。为什么我们要不停地更换主人呢？', `MaleText_loc5`='不要屈服於莫格多克的傀儡!他會以一個次等貨色來取代我們古羅主宰的位置。為什麼我們得要用另一個來取代一個主人才行?', `MaleText_loc7`='¡No os inclinéis ante la marioneta de Mog''dorg! Él sustituiría a nuestros Señores Supremos gronn por un vasallo de menor clase. ¿Por qué deberíamos sustituir a un maestro por otro?' WHERE `ID`=21027;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='때가 왔다. 오우거 일족의 앞길을 막는 자 모두 죽여라!', `MaleText_loc4`='时机已经成熟。那些挡在氏族前进道路上的家伙们，让他们统统去死！', `MaleText_loc5`='時候到了。打倒擋住氏族的每一個生物吧!', `MaleText_loc7`='Ha llegado el momento. ¡Acabad con toda criatura que se interponga en el camino de los clanes!' WHERE `ID`=21028;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모그도그 거짓말에 속지 마라! 오그릴라는 전설인 거다! 오우거는 오우거를 갈라놓는 침입자들 무찔러 여기에 오우거 세상 만든다!', `MaleText_loc4`='不要听信莫戈多格的谎言！奥格瑞拉是个神仙般的圣地！我们铲除了那些企图分化奴役我们的敌对势力，在这里建立起自己的天堂。', `MaleText_loc5`='不要聽從莫格多克的謊言!歐格利拉並不存在!我們要在這裡以那些想要分裂以及征服我們的人的鮮血建立起我們的天堂!', `MaleText_loc7`='¡No escuchéis las mentiras de Mog''dorg! ¡Ogri''la es un mito! ¡Construyamos nuestro propio cielo aquí con la sangre de los que intenten dividirnos y someternos!' WHERE `ID`=21029;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 오우거이면서도 어떻게 이렇게 정확하게 말할 수 있는지 궁금할 것일세. 그건 바로 오그릴라 주위 대지에서 자라는 수정의 부작용 때문이지. 그곳의 오우거들은 내게 이 지팡이를 선물로 주었고, 이 지팡이의 수정이 내게 지성을 선물로 준 것일세.$B$B자네가 저 위의 오그릴라에서 계속 노력해 준 덕택에 언젠가는 우리 오우거 일족 모두가 이 혜택을 받게 되기를 바랄 수 있게 되었네. 내 $g왕:여왕;이 된 자네가 지금까지 해 주었고 앞으로도 할 일들에 대해 감사를 전하네.', `MaleText_loc4`='你一定很好奇为什么食人魔说话也能这么流利。这是生长在奥格瑞拉周围的水晶簇的副作用。那里的食人魔将这根法杖送给了我，镶嵌在法杖上的水晶赐予了我无穷的智慧。$B$B只要你继续在奥格瑞拉行善，那么总有一天，所有的食人魔同胞都能享受到这种福泽。谢谢你，我的$g国王:女王;。感谢你为我们所做的一切。', `MaleText_loc5`='你一定懷疑過為何我身為一位巨魔卻可以如此清楚的說話。這是生長在歐格利拉周遭區域的水晶所產生的副作用。那裡的巨魔賦予我此項才能，而水晶本身則賦予我智慧。$B$B經由你在上述的歐格利拉所持續進行的一連串行動，我希望有一天能夠將這些好處帶給我所有的巨魔兄弟們。非常謝謝你，我的$g國王:女王;，對你曾做過以及將來會做的事。', `MaleText_loc7`='Debes haberte preguntado por qué hablo con tanta claridad para ser un ogro. Es un efecto secundario de los cristales que crecen en el bancal que rodea Ogri''la. Los ogros de allí me han bendecido con esta vara, y su cristal ha bendecido mi mente.$B$BA través de tus continuas acciones arriba en Ogri''la, espero poder llevar esta bendición a mis hermanos ogros, algún día. Te agradezco todo lo que has hecho y harás, mi $g rey: reina;.' WHERE `ID`=21030;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 형제요. 그리고 우리의 평화를 반대하는 무리에 맞서 서로 뭉칠 것이오.', `MaleText_loc4`='我们是兄弟。我们要团结起来，抵抗那些反对和平的家伙。', `MaleText_loc5`='我們是兄弟。我們將會聯手起而對抗那些妨礙我們和平的人。', `MaleText_loc7`='Somos hermanos. Y nos mantendremos unidos contra aquellos que se oponen a nuestra paz.', `FemaleText_loc1`='우리는 형제요. 그리고 우리의 평화를 반대하는 무리에 맞서 서로 뭉칠 것이오.', `FemaleText_loc4`='我们是兄弟。我们要团结起来，抵抗那些反对和平的家伙。', `FemaleText_loc5`='我們是兄弟。我們將會聯手起而對抗那些妨礙我們和平的人。', `FemaleText_loc7`='Somos hermanos. Y nos mantendremos unidos contra aquellos que se oponen a nuestra paz.' WHERE `ID`=21031;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 나... 죽는다.', `MaleText_loc4`='啊……我……死了。', `MaleText_loc5`='啊...我...死了。', `MaleText_loc7`='Agh... yo... estar... $gmuerto:muerta;.' WHERE `ID`=21032;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오그릴라... 간다.', `MaleText_loc4`='我要去……奥格瑞拉了。', `MaleText_loc5`='我去...歐格利拉。', `MaleText_loc7`='Yo ir... a Ogri''la.' WHERE `ID`=21033;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$G왕:여왕;님... 나 죽여라.', `MaleText_loc4`='伟大的$g国王:女王;陛下，杀了我吧……我很荣幸。', `MaleText_loc5`='我尊敬的...$g國王:女王;殺了我。', `MaleText_loc7`='Yo orgulloso... $grey:reina; matar mí.' WHERE `ID`=21034;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$G왕:여왕;님, $n, 나 이제 죽는다.', `MaleText_loc4`='$g国王:女王;$n陛下，我现在死了。', `MaleText_loc5`='$G國王:女王;$n，我現在要死了。', `MaleText_loc7`='$G Rey : Reina; $n, yo morir ahora.' WHERE `ID`=21035;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈이 불타는 군단의 적이란 말이냐. 벌레 같은 것. 어떤 고통이 널 기다리고 있는지 알고는 있겠지...', `MaleText_loc4`='你对燃烧军团来说已经不陌生了。当然，你也会知道，这意味着怎样的痛苦在等待着你……', `MaleText_loc5`='人渣，你對軍團並不陌生。毫無疑問的，你知道會有什麼樣的折磨在等著你...', `MaleText_loc7`='No eres un extraño para la Legión, escoria. Seguro que sabes qué tormentos te aguardan...' WHERE `ID`=21036;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 오그릴라에 있소.', `MaleText_loc4`='我们就在奥格瑞拉。', `MaleText_loc5`='我們在歐格利拉。', `MaleText_loc7`='Estamos en Ogri''la.', `FemaleText_loc1`='우리는 오그릴라에 있소.', `FemaleText_loc4`='我们就在奥格瑞拉。', `FemaleText_loc5`='我們在歐格利拉。', `FemaleText_loc7`='Estamos en Ogri''la.' WHERE `ID`=21037;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 천국에 있는 것이오.', `MaleText_loc4`='我们就在天堂。', `MaleText_loc5`='我們在天堂。', `MaleText_loc7`='Estamos en el cielo.', `FemaleText_loc1`='우리는 천국에 있는 것이오.', `FemaleText_loc4`='我们就在天堂。', `FemaleText_loc5`='我們在天堂。', `FemaleText_loc7`='Estamos en el cielo.' WHERE `ID`=21038;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 피로 물든 길을 벗어나 수정으로 이어지는 빛나는 길을 가고 있소이다.', `MaleText_loc4`='从前的道路血渍斑斑，如今我们却走在被水晶照耀的道路上。', `MaleText_loc5`='我們已經從血腥之路到了水晶光明之路。', `MaleText_loc7`='Hemos pasado de caminos manchados de sangre a caminos iluminados por cristales.', `FemaleText_loc1`='우리는 피로 물든 길을 벗어나 수정으로 이어지는 빛나는 길을 가고 있소이다.', `FemaleText_loc4`='从前的道路血渍斑斑，如今我们却走在被水晶照耀的道路上。', `FemaleText_loc5`='我們已經從血腥之路到了水晶光明之路。', `FemaleText_loc7`='Hemos pasado de caminos manchados de sangre a caminos iluminados por cristales.' WHERE `ID`=21039;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전쟁터의 함성이 아직도 선명하지만 우리는 이제 수정의 노래에 귀를 기울이고 있소.', `MaleText_loc4`='即使是战争的喧嚣，也无法阻止我们聆听水晶中传出的美妙歌声。', `MaleText_loc5`='盡管戰鬥的聲音音猶在耳，我們還是聽到這些水晶的歌聲。', `MaleText_loc7`='A pesar de que el sonido de la batalla aún es cercano, también oímos la canción de estos cristales.', `FemaleText_loc1`='전쟁터의 함성이 아직도 선명하지만 우리는 이제 수정의 노래에 귀를 기울이고 있소.', `FemaleText_loc4`='即使是战争的喧嚣，也无法阻止我们聆听水晶中传出的美妙歌声。', `FemaleText_loc5`='盡管戰鬥的聲音音猶在耳，我們還是聽到這些水晶的歌聲。', `FemaleText_loc7`='A pesar de que el sonido de la batalla aún es cercano, también oímos la canción de estos cristales.' WHERE `ID`=21040;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적들이 문 앞까지 몰려왔어도 수정의 노래와 빛이 우리를 지켜주었듯이 말이오.', `MaleText_loc4`='即使敌人兵临城下，水晶散发出的光芒依然鼓舞着我们。', `MaleText_loc5`='即使敵人就在我們的門前，水晶的光明及歌聲依舊鼓舞著我們。', `MaleText_loc7`='Incluso con el enemigo llamando a la puerta, la luz y la canción de los cristales nos han sostenido.', `FemaleText_loc1`='적들이 문 앞까지 몰려왔어도 수정의 노래와 빛이 우리를 지켜주었듯이 말이오.', `FemaleText_loc4`='即使敌人兵临城下，水晶散发出的光芒依然鼓舞着我们。', `FemaleText_loc5`='即使敵人就在我們的門前，水晶的光明及歌聲依舊鼓舞著我們。', `FemaleText_loc7`='Incluso con el enemigo llamando a la puerta, la luz y la canción de los cristales nos han sostenido.' WHERE `ID`=21041;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳 오그릴라에서 우린 고등 존재가 되려고 애써왔고 이제 그 방식을 고수할 것이오.', `MaleText_loc4`='在奥格瑞拉，我们达到了一种更高的生活境界。而且我们会继续保持这种状态。', `MaleText_loc5`='在歐格利拉這，我們已經達到一個更高等的存在。我們將以此保持下去。', `MaleText_loc7`='Aquí, en Ogri''la, hemos alcanzado un nivel de existencia superior. Y así lo mantendremos.', `FemaleText_loc1`='이곳 오그릴라에서 우린 고등 존재가 되려고 애써왔고 이제 그 방식을 고수할 것이오.', `FemaleText_loc4`='在奥格瑞拉，我们达到了一种更高的生活境界。而且我们会继续保持这种状态。', `FemaleText_loc5`='在歐格利拉這，我們已經達到一個更高等的存在。我們將以此保持下去。', `FemaleText_loc7`='Aquí, en Ogri''la, hemos alcanzado un nivel de existencia superior. Y así lo mantendremos.' WHERE `ID`=21042;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형제들이여, 저 소리가 들리오?', `MaleText_loc4`='你听见了吗，兄弟？', `MaleText_loc5`='兄弟你有聽到嗎?', `MaleText_loc7`='¿Oís eso, hermanos?', `FemaleText_loc1`='형제들이여, 저 소리가 들리오?', `FemaleText_loc4`='你听见了吗，兄弟？', `FemaleText_loc5`='兄弟你有聽到嗎?', `FemaleText_loc7`='¿Oís eso, hermanos?' WHERE `ID`=21043;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 수정의 노래 속에서 다가오는 전투의 함성이 들리냔 말이오.', `MaleText_loc4`='在水晶的歌唱声中，你可曾听见战争迫近的号角？', `MaleText_loc5`='在水晶的歌聲之外，你有聽到戰鬥的聲音愈來愈近嗎?', `MaleText_loc7`='¿Oís la batalla acercarse a pesar de la canción de los cristales?', `FemaleText_loc1`='저 수정의 노래 속에서 다가오는 전투의 함성이 들리냔 말이오.', `FemaleText_loc4`='在水晶的歌唱声中，你可曾听见战争迫近的号角？', `FemaleText_loc5`='在水晶的歌聲之外，你有聽到戰鬥的聲音愈來愈近嗎?', `FemaleText_loc7`='¿Oís la batalla acercarse a pesar de la canción de los cristales?' WHERE `ID`=21044;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 적이 보이오?', `MaleText_loc4`='你看到我们的敌人了吗？', `MaleText_loc5`='你看到我們的敵人了嗎?', `MaleText_loc7`='¿Veis a nuestros enemigos acercarse?', `FemaleText_loc1`='우리의 적이 보이오?', `FemaleText_loc4`='你看到我们的敌人了吗？', `FemaleText_loc5`='你看到我們的敵人了嗎?', `FemaleText_loc7`='¿Veis a nuestros enemigos acercarse?' WHERE `ID`=21045;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들은 근처에 숨어서 공격을 준비하고 있소이다.', `MaleText_loc4`='他们就潜伏在附近，随时准备发起进攻。', `MaleText_loc5`='他們潛伏在附近準備攻擊。', `MaleText_loc7`='Están al acecho, listos para atacar.', `FemaleText_loc1`='그들은 근처에 숨어서 공격을 준비하고 있소이다.', `FemaleText_loc4`='他们就潜伏在附近，随时准备发起进攻。', `FemaleText_loc5`='他們潛伏在附近準備攻擊。', `FemaleText_loc7`='Están al acecho, listos para atacar.' WHERE `ID`=21046;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 전투 준비는 되었소?', `MaleText_loc4`='我们准备好了吗？', `MaleText_loc5`='我們準備好了嗎?', `MaleText_loc7`='¿Estamos preparados?', `FemaleText_loc1`='자, 전투 준비는 되었소?', `FemaleText_loc4`='我们准备好了吗？', `FemaleText_loc5`='我們準備好了嗎?', `FemaleText_loc7`='¿Estamos preparados?' WHERE `ID`=21047;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수정이 우리 형제들을 계몽시켜 주었지만 우린 계속 경계를 늦춰서는 안 되는 것이오.', `MaleText_loc4`='水晶启迪了我们。但是我们仍然需要保持警惕。', `MaleText_loc5`='水晶已經啟發了我們兄弟。但是我們還是要提防。', `MaleText_loc7`='Hermanos, los cristales nos han iluminado, pero aún debemos mantenernos alerta.', `FemaleText_loc1`='수정이 우리 형제들을 계몽시켜 주었지만 우린 계속 경계를 늦춰서는 안 되는 것이오.', `FemaleText_loc4`='水晶启迪了我们。但是我们仍然需要保持警惕。', `FemaleText_loc5`='水晶已經啟發了我們兄弟。但是我們還是要提防。', `FemaleText_loc7`='Hermanos, los cristales nos han iluminado, pero aún debemos mantenernos alerta.' WHERE `ID`=21048;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$G왕:여왕;님 정말... 오그릴라 있다고... 생각하나?', `MaleText_loc4`='$G国王:女王;陛下，你觉得……世上真的有个……奥格瑞拉吗？', `MaleText_loc5`='$G國王:女王;認為...那裡真的是...歐格利拉嗎?', `MaleText_loc7`='$G Rey : Reina; ¿Crees... que... Ogri''la... existe realmente?' WHERE `ID`=21049;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='작은 $r... 넌 하찮은 $g왕:여왕;이었...다...', `MaleText_loc4`='弱小的$r……你是一个……可怕的$g国王:女王;。', `MaleText_loc5`='小$r...你是一個...恐怖的$g國王:女王;。', `MaleText_loc7`='Endeble $r... fuiste un $g rey: reina;... horrible.' WHERE `ID`=21050;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영원한 명예와 자비와 고어핀드를 위하여.', `MaleText_loc4`='尽其一生，为荣誉，为宽恕，为血魔而战。', `MaleText_loc5`='為了榮耀，為了仁慈，為了血魔。永遠。', `MaleText_loc7`='Por honor, por piedad, por sanguino. Por siempre.' WHERE `ID`=21051;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 새로운 자인가? 흥, 당신은 해내지 못할 것이야...', `MaleText_loc4`='又一个，嗯？你永远都不会成功……', `MaleText_loc5`='另一個，是嗎?你永遠都不會成功的...', `MaleText_loc7`='¿Otro, eh? Nunca lo conseguirás...' WHERE `ID`=21052;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하루에 한 가지 일만 골라 할 수 있다는 걸 잊지 마시오. 그 일은 제쳐놓고, 우리 용아귀 부족은 항상 더 많은 수정을 찾고 있다오. 보잘것없는 일꾼이라도 이 주둔지로 수정을 가져올 순 있으니 말이야.', `MaleText_loc4`='记住，你每天只能做一次收集工作。但是，我们也一直需要更多的水晶。任何废柴苦工都能把那些东西带回营地。', `MaleText_loc5`='記得你一天只能選一樣收集工作來做。除那之外，我們一直都在尋找更多的水晶。任何沒用的苦工都能將那些水晶帶回到營地。', `MaleText_loc7`='Recuerda que solo puedes escoger un trabajo de recolección cada día. Además de eso, siempre buscamos cristales. Hasta el peón más insignificante puede traerlos al campamento.' WHERE `ID`=21053;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 사냥개들이 너의 시체로 잔치를 치르게 되겠구나!', `MaleText_loc4`='我的猎犬将把你的尸体当作一顿美餐！', `MaleText_loc5`='我的獵犬將以你的屍體為食!', `MaleText_loc7`='Mis canes se darán un festín con tu carne.' WHERE `ID`=21054;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 도전의 시간도 이제 거의 끝나가는구나!', `MaleText_loc4`='容你肆意挑衅的日子就要结束了！', `MaleText_loc5`='你反抗的時刻快結束了!', `MaleText_loc7`='¡La hora de tu desafío casi ha terminado!' WHERE `ID`=21055;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 영혼은 이제 끝장이다! 우리의 방어력 무장이 거의 다 되었으니 말이야.', `MaleText_loc4`='你的灵魂注定会被毁灭！我们的护盾防御就快准备就绪了……', `MaleText_loc5`='你的命運已經註定了!我們的防禦已經差不多裝備好了...', `MaleText_loc7`='¡Tu alma está condenada! Nuestras defensas están casi listas...' WHERE `ID`=21056;
