UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 백성들을 쥐고 흔드는 일리단의 손길은 막강하네, $n. 어떻게든 이 모든 걸 끝내야 하네.$B$B준비 되었나, $n? 내 백성들의 운명이 우리에게 달려 있다네.', `MaleText_loc4`='伊利丹对我的氏族的控制非常严密，$n。但是无论如何，一切很快就会结束了。$B$B$n，你准备好了吗？氏族的未来就靠你了。', `MaleText_loc5`='伊利丹對我部族的控制很強硬，$n。這一切將很快地以某種方式結束了。$B$B你準備好了嗎，$n?我的人民的未來就靠我們了。', `MaleText_loc7`='El control de Illidan sobre mi tribu es fuerte, $n. Pronto acabará, de un modo u otro.$B$B¿Quieres seguir adelante, $n? El futuro de mi pueblo está en nuestras manos.' WHERE `ID`=21078;
