UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하늘경비대의 유능한 조종사들에 대해 불평을 늘어놓으면서 %s|1이;가; 엉망이 된 주변을 정리합니다.', `MaleText_loc4`='%s一边咒骂着超速驾驶的天空卫士，一边清理着弄脏的地方。', `MaleText_loc5`='%s在清理的同時小聲地咒罵禦天者自大的飛行員。', `MaleText_loc7`='%s limpia el desastre mientras murmura juramentos contra los pilotos célebres de la Guardia del cielo.', `FemaleText_loc1`='하늘경비대의 유능한 조종사들에 대해 불평을 늘어놓으면서 %s|1이;가; 엉망이 된 주변을 정리합니다.', `FemaleText_loc4`='%s一边咒骂着超速驾驶的天空卫士，一边清理着弄脏的地方。', `FemaleText_loc5`='%s在清理的同時小聲地咒罵禦天者自大的飛行員。', `FemaleText_loc7`='%s limpia el desastre mientras murmura juramentos contra los pilotos célebres de la Guardia del cielo.' WHERE `ID`=21082;
