UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 내가 시초였다... 죽음의 수레바퀴가 수도 없이 돌았지. 참으로 오랜 세월이 흘렀어... 끝내야 할 일이 너무 많다.', `MaleText_loc4`='对我来说，死亡之轮已经旋转了许多次。时间已经流逝了许多……有太多事情要做了。', `MaleText_loc5`='對我來說，死亡之輪已經旋轉了許多次。時間已經流逝了許多...有太多事情要做了。', `MaleText_loc7`='Yo fui el primero, sabes. Para mí, la ruleta de la muerte ha girado muchas veces. Ha pasado tanto tiempo... (Suspira.)Tengo que ponerme al día.' WHERE `ID`=21098;
