UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번 수집 작업을 망쳐 놓다니! 쓸모없는 간아그인 네 녀석과 일을 해야만 하는 이유가 뭐지?', `MaleText_loc4`='你把这一批全都给毁了！为什么我要和你这个渣一样的甘尔葛一起工作。', `MaleText_loc5`='你毀了這一批物品!為什麼我一定要跟你這個沒用的甘納格一起做事。', `MaleText_loc7`='¡Has arruinado este lote! Por qué tendré que trabajar con un despreciable Gan''arg.' WHERE `ID`=21115;
