UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 심판관입니다.', `MaleText_loc4`='我是个审判者。', `MaleText_loc5`='我是審判者的一員。', `MaleText_loc7`='Soy un justicar.', `FemaleText_loc1`='나는 심판관입니다.', `FemaleText_loc4`='我是个审判者。', `FemaleText_loc5`='我是審判者的一員。', `FemaleText_loc7`='Soy una justicar.' WHERE `ID`=21126;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아직 수련이 부족한 당신에게는 가르쳐 드릴 것이 없습니다. 제 옆에 있는 글로레스의 조잡한 기술이라도 배워서 연습을 해 보시기 바랍니다.', `FemaleText_loc4`='你的能力还不够，我教你的东西你肯定理解不了。我强烈建议你找葛洛莉丝谈一谈，先向她学习一点小花样，磨练磨练你的技术吧。', `FemaleText_loc5`='你還不夠格來學習我可能會告訴你的事情。我大力建議你去找這裡那個懶散的哥羅瑞斯磨練一下你生疏的技術再來跟我談。', `FemaleText_loc7`='Aún no has avanzado lo suficiente como para aprender lo que yo pueda enseñarte. Te sugiero que perfecciones tus inmaduras habilidades con las flojas actuaciones de Gloresse antes de hablar conmigo.' WHERE `ID`=21127;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그럼 시작해 보도록 합시다. 제 기술을 전수해 드릴 테니 잘 보고 배우십시오.', `FemaleText_loc4`='让我们开始做事吧，$n。我会让你了解我所掌握的知识，不过，先继续。', `FemaleText_loc5`='讓我們回到正題，$n。我會告訴你我所知道的事，但是跟上。', `FemaleText_loc7`='Manos a la obra, $n. Te enseñaré lo que sé, pero sigue el ritmo.' WHERE `ID`=21128;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 내 군대의 힘을 버텨내지 못한다!', `MaleText_loc4`='你不可能抵挡得住我的军团！', `MaleText_loc5`='你無法抵抗我軍隊的力量!', `MaleText_loc7`='¡No puedes resistir al poder de mis fuerzas!' WHERE `ID`=21129;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자신 있다면 공간이동 관문 안을 자세히 들여다 보아라. 내가 널 위해 아주 특별한 걸 준비해 놨으니 말이다...', `MaleText_loc4`='要是你有胆的话，就凝视着迁跃门内部吧。我已经为你准备了一些特别的东西……', `MaleText_loc5`='如果你敢的話，注視星移門內。我為你準備了特別的東西...', `MaleText_loc7`='Mira en el interior de la puerta de distorsión, si te atreves. Te he preparado algo especial...' WHERE `ID`=21130;
