UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무 데도 가지 못한다!', `MaleText_loc4`='你休想逃走！', `MaleText_loc5`='你哪裡都不能去!', `MaleText_loc7`='¡No vas a ninguna parte!' WHERE `ID`=21138;
