UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모그도그, 나 당신이 원하는 일 알고 있다.', `MaleText_loc4`='莫戈多格，我知道那些你一直想知道的东西。', `MaleText_loc5`='莫格多克，我有你想知道的東西。', `MaleText_loc7`='¡Mog''dorg, yo saber cosas que te interesan!' WHERE `ID`=21141;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 돌아왔다, 대장. 아는 거 말해준다.', `MaleText_loc4`='我回来了，老大。让我告诉你我知道的事情。', `MaleText_loc5`='我回來了，主人。我跟你說我知道了什麼。', `MaleText_loc7`='Yo estar de vuelta, jefe. Yo contar lo que saber.' WHERE `ID`=21142;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모그도그 대장, 그 그론 아무것도 모른다. 나 그 그론 그 계획에 대해서 아무것도 모른다고 확신한다.', `MaleText_loc4`='戈隆什么都不知道，莫戈多格。我确信他们不知道计划。', `MaleText_loc5`='那個古羅什麼都不知道，莫格多克。我確定他們對計畫一無所知。', `MaleText_loc7`='El gronn no saber nada, Mog''dorg. Yo estar seguro de que ellos conocer el plan.' WHERE `ID`=21143;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여러 가지 일 벌어지고 있다 들었다. 곧 우리가 그론 처치하나?', `MaleText_loc4`='我听说许多事情都在进行。我们马上要去杀戈隆了？', `MaleText_loc5`='我聽說很多事情正在進行。我們很快就要殺了古羅?', `MaleText_loc7`='Yo oír que muchas cosas suceder. ¿Nosotros matar gronn pronto?' WHERE `ID`=21144;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모그도그, 나 아무한테도 그거... 그 그론에 대항하는 비밀 계획 말 안 했다.', `MaleText_loc4`='莫戈多格，我不会把对付戈隆的秘密计划告诉任何人。', `MaleText_loc5`='莫格多克，我沒有告訴任何人有關秘...秘...秘...對抗那個古羅的神秘計畫。', `MaleText_loc7`='Mog’dorg, yo no contar nada sobre plan conf...conf...conf...secreto.' WHERE `ID`=21145;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 친구들에게 물어봤다. 다들 준비됐다.', `MaleText_loc4`='我和其他食人魔已经协商好了。他们也准备好了。', `MaleText_loc5`='我跟其他巨魔確認過了。他們準備好了。', `MaleText_loc7`='Yo consultar con otros ogros. Ellos preparados.' WHERE `ID`=21146;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋다. 나 이제 간다.', `MaleText_loc4`='好的，我现在出发了。', `MaleText_loc5`='好，我現在就去。', `MaleText_loc7`='Vale, yo irme ahora.' WHERE `ID`=21147;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너의 처절한 노력은 고통 말고는 아무것도 주지 못한다.', `MaleText_loc4`='这些毫无价值的努力，除了痛苦以外，什么都不能带给你。', `MaleText_loc5`='你微不足道的努力將使你只有痛苦而已。', `MaleText_loc7`='Tus patéticos esfuerzos no te producirán nada más que dolor.' WHERE `ID`=21148;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 해냈군. 네가 알려준 정보는 우리 성공에 결정적 열쇠이다.', `MaleText_loc4`='你干得不错。你提供的信息对我们的成功十分重要。', `MaleText_loc5`='你做得很好。你提供的資訊對於我們的成功很重要。', `MaleText_loc7`='Bien hecho. La información que estás proporcionando es muy importante para nuestro éxito.' WHERE `ID`=21149;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙군, 친구여. 우린 곧 그론에게 묶인 이 노예 신세에서 해방될 거다.', `MaleText_loc4`='谢谢你，朋友。很快，我们就能从戈隆的奴役中解脱出来。', `MaleText_loc5`='謝謝你，朋友。很快的，我們就能從古羅的奴役中解脫了。', `MaleText_loc7`='Gracias, amigo. Pronto dejaremos de ser esclavos del gronn.' WHERE `ID`=21150;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋았어. 네가 지금 하는 일이 언젠가 우리를 저 위의 오그릴라에 있는 우리 동족들에게 합류할 수 있게 할 것이야.', `MaleText_loc4`='太好了。你现在所从事的事业，终有一天会让我们加入奥格瑞拉的同伴们。', `MaleText_loc5`='太棒了。你現在所做得事將可以使我們和我們在歐格利拉的兄弟們會合，以上，總有一天。', `MaleText_loc7`='Excelente. El trabajo que realizas ahora nos permitirá unirnos a nuestros hermanos en Ogri''la, ahí arriba, algún día.' WHERE `ID`=21151;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오그릴라의 고위층분들께서 네가 가져온 정보에 만족하실 것이야.', `MaleText_loc4`='奥格瑞拉得知你给我们带来的信息之后肯定会十分高兴的。', `MaleText_loc5`='那些位於歐格利拉對我說話的高層將會對於你所提供的資訊感到很滿意。', `MaleText_loc7`='Los que me hablan desde Ogri''la, ahí arriba, estarán muy satisfechos con la información que proporcionas.' WHERE `ID`=21152;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그론에 대항하는 우리의 은밀한 작전이 계획대로 진행되고 있다니 좋은 소식이로군. 게다가 외부에서 우리를 도와주는 친구들도 있으니 말이야.', `MaleText_loc4`='这是个好消息，我们反抗戈隆的秘密行动仍旧按计划顺利进行着。而且，现在我们还得到了来自外部的支持与帮助。', `MaleText_loc5`='這是好消息;我們私下的對抗古羅的行動已經進入計畫中了。而且，現在外面也有人在接應我們了。', `MaleText_loc7`='Buenas noticias: nuestra operación encubierta contra el gronn continúa según lo planeado. Y también hay alguien ayudándonos desde fuera.' WHERE `ID`=21153;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그론에 대항한 지하 운동에 걸림돌이 있어서는 안 된다! 추가 정보를 더 입수해서 돌아와라.', `MaleText_loc4`='我们坚定不移地继续反抗戈隆的秘密行动！回去收集更多的信息吧。', `MaleText_loc5`='我們對抗古羅的地下行動一定不能動搖!回去取得更多資訊。', `MaleText_loc7`='¡Nuestro movimiento clandestino contra el gronn no debe vacilar! Vuelve y reúne más información.' WHERE `ID`=21154;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아. 모든 게 계획대로 진행되면, 우린 곧 그론에게서 풀려날 수 있을 것이야. 그러면 칼날 산맥의 모든 오우거들은 오그릴라에서 오는 문명의 축복을 향유할 수 있다는 말이다.', `MaleText_loc4`='好。要是一切都能按计划顺利进行，我们很快就会从戈隆的魔掌中逃脱出来，获得真正的自由。刀锋山的所有食人魔都将从奥格瑞拉这里享受到食人魔文明的祝福。', `MaleText_loc5`='很好。如果所有細節都計畫好了，我們很快就能從古羅手中解放了。那麼所有山領的巨魔都將可以得到來自歐格利拉巨魔的廣大祝福。', `MaleText_loc7`='Bien. Si todo sigue según lo previsto pronto seremos libres. Entonces todos los ogros de las montañas podrán disfrutar de las ilustradas bendiciones de los ogros de Ogri''la.' WHERE `ID`=21155;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 친구여, 근시일 내에 자네도 나와 마찬가지로 오그릴라 수정을 지니게 돼. 그러면 우리를 둘러싼 세상에 대해 더 큰 이해를 하게 될 것이야.', `MaleText_loc4`='不久之后，我的朋友，你就会像我一样得到一块奥格瑞拉水晶。那样的话，你就能更深刻地了解周围的世界。', `MaleText_loc5`='我的朋友，有一天很快的你將會跟我一樣，帶著一顆歐格利拉水晶。那麼你就會對於你周遭的世界有更廣大的了解。', `MaleText_loc7`='Un día cercano, amigo mío, llevarás un cristal de Ogri''la, como yo. Entonces poseerás un mayor entendimiento del mundo que te rodea.' WHERE `ID`=21156;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼요. 제가 관여하지 않는다면요.', `MaleText_loc4`='是。除非这事跟我有关系。', `MaleText_loc5`='沒錯，除非我和這件事有任何的關係。', `MaleText_loc7`='Sí, a menos que tenga algo que hacer con ello.' WHERE `ID`=21157;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내일과 다음 10년 사이에 일어날 일 같아요. 분명해요.', `MaleText_loc4`='在明天到十年后这个阶段期间的某一天就会发生。我肯定。', `MaleText_loc5`='我認為它會發生在明天到下一個十年間的某個時候。一定會的。', `MaleText_loc7`='Veo que eso ocurrirá en algún momento entre mañana y la próxima década. Seguro.' WHERE `ID`=21158;
