UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동료 임프들에게 의견을 물어봤는데요, 한 친구만 빼곤 다 긍정적이네요.', `MaleText_loc4`='我跟其他的小鬼开会讨论了一下，答案是“是”。不过有一个小鬼投了反对票。', `MaleText_loc5`='我已經詢問過我的小鬼夥伴們了，我們覺得沒有問題，除了一個小鬼以外。', `MaleText_loc7`='Lo he consultado con mis colegas diablillos y creemos que sí, todos menos ese diablillo.' WHERE `ID`=21161;
