UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실현 가능성은... 제가 서큐버스 양과 데이트를 할 확률 정도?', `MaleText_loc4`='这个可能性等同于我跟一位魅魔约会的可能性。', `MaleText_loc5`='那就跟我會跟一隻魅魔一起約會的機會一樣嘛。', `MaleText_loc7`='Eso es tan posible como que yo consiga una cita con un súcubo.' WHERE `ID`=21240;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 운세 점치기 실력은 대단하답니다. 그래도 당신은 기회가 없다네요.', `MaleText_loc4`='我预知未来的能力趋于无穷大，不过你成功的机会趋于零。', `MaleText_loc5`='我的預言能力是無人能比的 - 你的機會是:完全沒機會', `MaleText_loc7`='Mis poderes de adivinación son incalculables, tus posibilidades no lo son: ¡ninguna!' WHERE `ID`=21241;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니요. 더 좋은 운세를 얻겠다고 절 흔들려고 하진 마세요!', `MaleText_loc4`='不可能——你继续摇我也不会改变这个答案。', `MaleText_loc5`='不 - 再搖下去我也不會給你更好的答案!', `MaleText_loc7`='No, y no intentes agitarme otra vez a ver si la respuesta es mejor.' WHERE `ID`=21242;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 대답은 ''네''랍니다...', `MaleText_loc4`='答案是肯定的……', `MaleText_loc5`='我答應你...', `MaleText_loc7`='Mi respuesta es "sí"...' WHERE `ID`=21243;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 아니요!', `MaleText_loc4`='……不！', `MaleText_loc5`='...才怪!', `MaleText_loc7`='¡...No!' WHERE `ID`=21244;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아!니!요!라는 대답을 드리려고 해요.', `MaleText_loc4`='答案很简单，看我口型：没门。', `MaleText_loc5`='這一次我要說不不不。', `MaleText_loc7`='Voy a tener que decirte que... no.' WHERE `ID`=21245;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신에겐 전망이 매우 좋지 않네요! 하하, 순순히 받아들이라고요!', `MaleText_loc4`='前景不妙！哈哈哈哈！接受现实吧！', `MaleText_loc5`='前景看起來很糟糕 - 我是在說你!哈哈，認命吧!', `MaleText_loc7`='¡El pronóstico es muy malo... para ti! ¡Je, je! ¡Chúpate esa!' WHERE `ID`=21246;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='설문 결과는 이렇네요. 삐!', `MaleText_loc4`='调查结果表明：哼哼！', `MaleText_loc5`='調查報告顯示:嘖嘖!', `MaleText_loc7`='La encuesta dice: ¡BZZZT!' WHERE `ID`=21247;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋다, 이 침입자 녀석. 내가 네 녀석을 끝까지 쫓아가 주마...', `MaleText_loc4`='非常好，入侵者。你吸引到了我的注意……', `MaleText_loc5`='很好，闖入者。你得到了我全部的注意...', `MaleText_loc7`='Muy bien, intruso. Tienes toda mi atención...' WHERE `ID`=21248;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보아라! 이때를 위해 내가 가장 아끼는 녀석을 남겨 두었지.', `MaleText_loc4`='看！为了这个时刻，我特地留下了我最喜欢的宠物。', `MaleText_loc5`='瞧!我就單單為了如此的理由預定了我最喜歡的寵物。', `MaleText_loc7`='¡Mirad! He reservado mis mascotas favoritas para esta ocasión.' WHERE `ID`=21249;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이놈들은 내가 처리하겠소! 친구들, 어서 배신자를 공격하시오!', `MaleText_loc4`='我来对付这些渣滓！进攻吧，朋友们！向伊利丹发起进攻！', `MaleText_loc5`='我會對付這些雜種!現在出擊，朋友!攻擊背叛者!', `MaleText_loc7`='¡Yo me encargo de estos perros! ¡Ataquen ahora, amigos! ¡Ataquen al Traidor!' WHERE `ID`=21250;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부하들아, 이 반역자에게 응당한 처벌을 내려라!', `MaleText_loc4`='来吧，我的手下。让这个叛徒付出代价！', `MaleText_loc5`='來吧，我的手下。讓這個叛徒付出代價﹗', `MaleText_loc7`='Vengan esbirros míos. ¡Den a ese traidor su merecido!' WHERE `ID`=21251;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어찌 감히 날 건드리려 하느냐!', `MaleText_loc4`='你们这些乌合之众休想碰到我！', `MaleText_loc5`='你們這些烏合之眾休想碰到我﹗', `MaleText_loc7`='¡No me tocarán canallas como ustedes!' WHERE `ID`=21252;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='항복이다! 내가 졌다...', `MaleText_loc4`='我投降，我投降！！这次你赢了……', `MaleText_loc5`='我投降!這次算你贏了...', `MaleText_loc7`='¡Me rindo! Esta vez ganas tú...' WHERE `ID`=21253;
