UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 날카로운 비명을 지르며 주위의 칼리리에게 도움을 요청합니다.', `MaleText_loc4`='%s发出了一声刺耳的尖叫，呼叫周围的卡利鸟来帮忙。', `MaleText_loc5`='%s發出一聲尖鳴，呼喊附近的卡里瑞前來幫忙。', `MaleText_loc7`='%s lanza un alarido estridente, pidiendo ayuda a un kaliri cercano.' WHERE `ID`=21260;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 보이지 않는 존재와 이야기하는 것 같습니다.', `MaleText_loc4`='%s好像在和某个看不见的东西说话。', `MaleText_loc5`='%s好像正在跟一個看不到的對象談話。', `MaleText_loc7`='%s parece hablar con una entidad no visible.' WHERE `ID`=21261;
