UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언젠가, 우리가 이 검은 사원을 다스리게 될 거라고.', `MaleText_loc4`='总有一天，我们会统治这座黑暗的神殿。', `MaleText_loc5`='有一天，我們將會統治這個黑暗神廟。', `MaleText_loc7`='Algún día dominaremos este Templo Oscuro.' WHERE `ID`=21268;
