UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 이제 $n|1이;가; 나서는군!', `MaleText_loc4`='哦，现在轮到$n了！', `MaleText_loc5`='喔，現在開始了$n!', `MaleText_loc7`='¡OH, AHORA ESTÁ ACTIVADO $n!' WHERE `ID`=21270;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='멍청한 수류탄이 오작동을 일으켰지 뭐예요! 고블린 기계공학의 기술이란 정말 대단하다니까요!', `FemaleText_loc4`='手榴弹竟然在这种时候逆火，这蠢东西还真会挑时间啊！我受够了这些所谓的高品质地精工程学制品！', `FemaleText_loc5`='蠢手榴彈真會挑時間出問題!真是高品質的哥布林工程學啊!', `FemaleText_loc7`='¡La estúpida granada eligió un mal momento para fallar! ¡Vaya con la ingeniera goblin de alta calidad!' WHERE `ID`=21271;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리에게 행운이 함께하기를! 하늘의 힘으로!', `MaleText_loc4`='幸运与我们同在！飞向天空吧！', `MaleText_loc5`='幸運與我們同在!升空!', `MaleText_loc7`='¡Qué la fortuna nos acompañe! ¡A los cielos!' WHERE `ID`=21272;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$r|1이여;여;, 그대에게 제안이 있습니다. 그대가 선택하려는 길에 대해서 심사숙고하시기 바랍니다. 그대의 선택은 쉽게 뒤바꿀 수 있는 게 아니니까요.$B$B우리 보랏빛 눈의 감시자에서 그대의 충성을 정식으로 승인해야 할 때가 되었습니다. 그대가 어떤 자격으로 보랏빛 눈의 감시자에 공헌하고자 하는지를 알아야만 그에 적합한 보상을 드릴 수가 있으니까요.', `FemaleText_loc4`='我有个建议，$r。请认真考虑你的选择——一旦做出抉择，就很难反悔了。$B$B你已经通过了忠诚的考验，现在是时候让你正式加入我们的组织了。我必须了解你希望以什么样的方式来为我们效力，以便我们为你提供适当的奖励。', `FemaleText_loc5`='我對你有個提議，$r。請好好思考你的選擇 - 你的決定無法輕易的更改。$B$B該是時候讓我們將你的忠誠正式納入我們的組織了。我必須得知道你希望以什麼樣的資格來為我們效命，我們才知道要如何獎賞你。', `FemaleText_loc7`='Tengo una propuesta para ti, $r. Por favor, considera bien tu elección, pues no será fácil dar marcha atrás.$B$BEs hora de que formalicemos tu alianza con nuestra organización. Necesito saber hasta que punto deseas servirnos, para poder recompensarte apropiadamente.' WHERE `ID`=21273;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어리석은 아카마, 네 목숨이 붙어 있는 시간은 이제 끝났다...', `MaleText_loc4`='愚蠢的阿卡玛，你的生命已经到了尽头……', `MaleText_loc5`='愚蠢的阿卡瑪，你的死期到了...', `MaleText_loc7`='Insensato Akama, tus días de mortal han terminado...' WHERE `ID`=21274;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보라, 아지노스의 불꽃을!', `MaleText_loc4`='让埃辛诺斯的烈焰吞噬你们！', `MaleText_loc5`='讓埃辛諾斯的烈焰吞噬你們!', `MaleText_loc7`='¡Contemplen las LLAMAS de Azzinoth!' WHERE `ID`=21275;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 연구가 끝났습니다! 모두 용감히 싸워주셨습니다! 운이 좀 따라준다면... 본부에서 이 측정 결과를 연구하여 바시르의 의도를 밝혀낼 수도 있을 것입니다! 자, 이제 하늘로 오르십시오!', `MaleText_loc4`='我们的研究完成了！干得好！总部会花大量精力来研究我们获得的测量数据。而且幸运的是，我们还揭开了巴什伊尔的阴谋。现在，启航！', `MaleText_loc5`='我們的研究完成了!完美的一戰!總部將會大量使用我們取得的測量，而且幸運的話，將會揭露貝許爾的企圖。現在，升空吧!', `MaleText_loc7`='¡Hemos completado nuestros estudios! ¡Bien hecho! El cuartel general estudiará detenidamente nuestras mediciones y, con suerte, desvelarán las intenciones de Bash’ir. ¡Ahora, a los cielos!', `FemaleText_loc1`='우리의 연구가 끝났습니다! 모두 용감히 싸워주셨습니다! 운이 좀 따라준다면... 본부에서 이 측정 결과를 연구하여 바시르의 의도를 밝혀낼 수도 있을 것입니다! 자, 이제 하늘로 오르십시오!', `FemaleText_loc4`='我们的研究完成了！干得好！总部会花大量精力来研究我们获得的测量数据。而且幸运的是，我们还揭开了巴什伊尔的阴谋。现在，启航！', `FemaleText_loc5`='我們的研究完成了!完美的一戰!總部將會大量使用我們取得的測量，而且幸運的話，將會揭露貝許爾的企圖。現在，升空吧!', `FemaleText_loc7`='¡Hemos completado nuestros estudios! ¡Bien hecho! El cuartel general estudiará detenidamente nuestras mediciones y, con suerte, desvelarán las intenciones de Bash’ir. ¡Ahora, a los cielos!' WHERE `ID`=21276;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='초보 재봉사들을 위해 특별히 갈라나를 고용하였으니 그녀와 대화해 보시오. 상점을 효율적으로 운영하려고 그러는 것이니 누구라도 그건 지켜 주어야 하지 않겠소?', `MaleText_loc4`='我雇佣贾兰娜对学徒进行基础训练，去和她谈谈吧。我想要将这家店铺的生意运转得越来越有效率，这样所有人——包括赞助者，都会对它表示尊敬。', `MaleText_loc5`='我雇用卡安娜是特別來處理新手的訓練。去跟她談談。這間店面代表著效率及效能，而我期望每個人 - 包括客人本身 - 都能夠重視它。', `MaleText_loc7`='Contraté a Galana para encargarse específicamente de los entrenamientos rudimentarios. Ve a hablar con ella. Esta tienda debe ser gestionada de forma eficiente y efectiva y espero que todos, los patrones incluidos, lo respeten.' WHERE `ID`=21277;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='켈렌의 믿을 수 있는 재봉술 상점에 온 것을 환영하오. 여기라면 그대가 필요로 하는 것을 찾을 수 있을 거요. 배우고 싶은 기술이 있거든 말만 하시오. 기꺼이 가르쳐 드리리다.', `MaleText_loc4`='欢迎来到基伦的裁缝店，你可以在这里找到你需要的商品。如果你愿意向我讨教裁缝技能的话，和我说一声就成，我会很乐意教给你的。', `MaleText_loc5`='歡迎來到奇蘭的可靠裁縫。我想你會發現我的店鋪將會滿足你的需要。如果你想要和我一起訓練，你盡管開口;我很樂意教你的。', `MaleText_loc7`='$gBienvenido:Bienvenida; a la Sastrería Fiable de Keelen. Creo que mi tienda satisfará tus necesidades. Si deseas entrenar conmigo, solo tienes que pedirlo; será un placer enseñarte.' WHERE `ID`=21278;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 뭘 도와드리면 되겠소?', `MaleText_loc4`='我能帮你什么忙吗，$c？', `MaleText_loc5`='有什麼我能幫忙的嗎，$c?', `MaleText_loc7`='¿Cómo puedo ayudarte, $c?' WHERE `ID`=21279;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물건을 좀 보여주십시오.', `MaleText_loc4`='让我看看你在出售什么。', `MaleText_loc5`='給我看看你賣的東西吧。', `MaleText_loc7`='Muéstrame lo que tienes en venta.', `FemaleText_loc1`='물건을 좀 보여주세요.', `FemaleText_loc4`='让我看看你在出售什么。', `FemaleText_loc5`='給我看看你賣的東西吧。', `FemaleText_loc7`='Muéstrame lo que tienes en venta.' WHERE `ID`=21280;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해골더미에서 악한 기운이 풍겨 나옵니다. 아라코아들이 아주 최근까지 해골들을 가져다 놓은 것 같아 두렵습니다.', `MaleText_loc4`='这里散发着污秽的恶臭，看来鸦人最近又堆积了新的战利品。', `MaleText_loc5`='這個顱骨堆發出惡劣的惡臭。你擔心阿拉卡最近在這骨堆上施加了其他的東西。', `MaleText_loc7`='Este montón de calaveras apesta a vileza. Temes que los arakkoa hayan añadido algo al montón recientemente.' WHERE `ID`=21281;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<사냥꾼 게자라크를 소환합니다.>', `MaleText_loc4`='<召唤猎手吉萨拉克。>', `MaleText_loc5`='<召喚女獵人吉札拉。>', `MaleText_loc7`='<Invoca a Gezzarak la Cazadora.>', `FemaleText_loc1`='<사냥꾼 게자라크를 소환합니다.>', `FemaleText_loc4`='<召唤猎手吉萨拉克。>', `FemaleText_loc5`='<召喚女獵人吉札拉。>', `FemaleText_loc7`='<Invoca a Gezzarak la Cazadora.>' WHERE `ID`=21282;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 진정한 힘의 이치를 깨닫게 될 것이다!', `MaleText_loc4`='现在你会看到真正的力量！', `MaleText_loc5`='現在你將會見識真實力量的意義!', `MaleText_loc7`='¡Ahora serás testigo de lo que significa el verdadero poder!' WHERE `ID`=21283;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 기계 장치, 장식품, 아무개, 소형 부품, 무언가, 거시기나 그거이를 찾고 계신다면, 제대로 오신 겁니다!', `FemaleText_loc4`='如果你是在寻找零件、齿轮这种小玩意的话，那么你来对地方了！', `FemaleText_loc5`='如果你在找機件，小東西，那個什麼的，零件，這個什麼的，新東西，或是小玩意兒，那你就來對地方了!', `FemaleText_loc7`='¡Si buscas artilugios, chismes, trastos, cachivaches, chirimbolos, cacharros o cosas, has venido al lugar adecuado!' WHERE `ID`=21284;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물건을 좀... 아니 그것들을 좀 보여주십시오.', `MaleText_loc4`='让我看看你都有些什么……呃，东西……', `MaleText_loc5`='給我看你的各種，呃...東西。', `MaleText_loc7`='Muéstrame tu surtido de...eehhhm...cosas.', `FemaleText_loc1`='물건을 좀... 아니 그것들을 좀 보여주세요.', `FemaleText_loc4`='让我看看你都有些什么……呃，东西……', `FemaleText_loc5`='給我看你的各種，呃...東西。', `FemaleText_loc7`='Muéstrame tu surtido de...eehhhm...cosas.' WHERE `ID`=21285;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 괴철로엔 추가 조율이 필요하다. 어서 들여다 보란 말이다, 이 노예 녀석아!', `MaleText_loc4`='熔炉需要额外的调整。去看看，奴隶！', `MaleText_loc5`='熔爐需要額外的調整。奴隸，進去看看!', `MaleText_loc7`='La forja necesita una puesta a punto adicional. ¡Encárgate de eso esclavo!' WHERE `ID`=21286;
