UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<어둠의 비명소리 아카라이를 소환합니다.>', `MaleText_loc4`='<召唤黑暗尖啸者阿克卡莱。>', `MaleText_loc5`='<召喚黑暗尖叫者阿卡萊。>', `MaleText_loc7`='<Invoca al Estridador oscuro Akkarai.>', `FemaleText_loc1`='<어둠의 비명소리 아카라이를 소환합니다.>', `FemaleText_loc4`='<召唤黑暗尖啸者阿克卡莱。>', `FemaleText_loc5`='<召喚黑暗尖叫者阿卡萊。>', `FemaleText_loc7`='<Invoca al Estridador oscuro Akkarai.>' WHERE `ID`=21289;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디서 본 거 같은데...', `MaleText_loc4`='你看上去很眼熟……', `MaleText_loc5`='你看起來很眼熟...', `MaleText_loc7`='Me resultas familiar...' WHERE `ID`=21290;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 녀석의 뼈는 내 사냥개를 위해 더할 나위 없이 좋은 장난감이로구나.', `MaleText_loc4`='你的骨头会变成我家爱狗最理想的玩具。', `MaleText_loc5`='你的骨頭將會成為我的獵犬非常合適的玩具。', `MaleText_loc7`='Tus huesos serán un juguete ideal para mi can.' WHERE `ID`=21291;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 시야는 이 세계 전역에서 일어나고 있는 사건과 언젠가는 일어날 일들의 환영으로 가득 차 있다네. 이 환영의 대부분은 불길하네만 바꿀 수 없는 일이라고 믿을 필요는 없는 것이야.', `MaleText_loc4`='我的预言梦境中充满了世界各地正在发生着和可能发生的事件的景象。它们大部分都非常可怕，不过，这未必是不可改变的。', `MaleText_loc5`='我的視線布滿著在世界各地正在發生，以及可能會發生的各種事。當中許多都很糟糕，不過我們需要相信他們是會改變的。', `MaleText_loc7`='Mis visiones están llenas de eventos que suceden por el mundo y de algunos que pueden llegar a suceder. Muchos de ellos son desalentadores, pero no debemos creer que no puedan cambiar.' WHERE `ID`=21292;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법 재료가 필요하신 거라면, 정확히 찾아오셨습니다. 샤트라스 어디에서도 더 좋은 상점은 찾기 어려우실 테니까요.', `MaleText_loc4`='需要施法材料的话，你可来对了地方。即使找遍整个沙塔斯城，你也找不到更好的选择了。', `MaleText_loc5`='如果你需要材料，那麼你就來對地方了。你在全撒塔斯城都找不到更好的選擇了。', `MaleText_loc7`='Si necesitas reactivos, has venido al lugar adecuado. No encontrarás una selección mejor en todo Shattrath.' WHERE `ID`=21293;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물건을 좀 보여주십시오.', `MaleText_loc4`='让我看看你有什么货物。', `MaleText_loc5`='給我看看你賣的東西吧。', `MaleText_loc7`='Muéstrame lo que tienes en venta.', `FemaleText_loc1`='물건을 좀 보여주십시오.', `FemaleText_loc4`='让我看看你有什么货物。', `FemaleText_loc5`='給我看看你賣的東西吧。', `FemaleText_loc7`='Muéstrame lo que tienes en venta.' WHERE `ID`=21294;
