UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수리기능 가동!', `MaleText_loc4`='修理模块已经激活！', `MaleText_loc5`='修復模組啟動!', `MaleText_loc7`='¡Modulo de reparación activado!' WHERE `ID`=21299;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누... 누구요? 뭘 원하는 거지?', `MaleText_loc4`='你……你是谁？？你想要什么？', `MaleText_loc5`='你...你是誰??你要幹嘛?', `MaleText_loc7`='¿Quién...quién eres? ¿Qué quieres?' WHERE `ID`=21300;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='비켜서지 않으면 내 방어구에 장식으로 삼겠습니다. 당신의 지도자와 난 주의를 기울어야 할 문제가 있단 말입니다...', `FemaleText_loc4`='在我把你做成我护甲上的又一个装饰前，给我滚到一边去。你的领袖和我有事要商量……', `FemaleText_loc5`='閃邊免得我把你做成另一個我護甲上的裝飾品。你的領導者和我有些事情要處理...', `FemaleText_loc7`='Aparta si no quieres que te convierta en otro adorno para mi armadura. Tu líder y yo tenemos asuntos que atender...' WHERE `ID`=21301;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그... 그렇소. 우린 이제 떠나오... 제발 해치지 마시오...', `MaleText_loc4`='好……好……我们马上走开……请不要伤害我们……', `MaleText_loc5`='是...是...我們現在就離開...請不要傷害我們...', `MaleText_loc7`='Sí... sí, nos movemos... Por favor no hacernos daño...' WHERE `ID`=21302;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 웃습니다.', `FemaleText_loc4`='%s笑了笑。', `FemaleText_loc5`='%s微笑。', `FemaleText_loc7`='%s sonríe.' WHERE `ID`=21303;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 방식에 대해서 알고 있다고 생각했는데 말입니다만...', `FemaleText_loc4`='我还以为你认同我的观点……', `FemaleText_loc5`='我想你會有可能會看到...', `FemaleText_loc7`='Creí que lo verías como yo...' WHERE `ID`=21304;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대군주 모르고르, 마침내 그대를 만나게 되었군요...', `FemaleText_loc4`='莫格霍尔大王，我想……能够和你攀上交情真是荣幸。', `FemaleText_loc5`='霸主莫格，我認為...很榮幸最終讓你了解了。', `FemaleText_loc7`='Señor supremo Mor’ghor, supongo... Un placer conocerte al fin...' WHERE `ID`=21305;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='난 여군주 시네스트라라고 합니다.', `FemaleText_loc4`='我是女伯爵希奈丝特拉。', `FemaleText_loc5`='我是賽絲特拉女士。', `FemaleText_loc7`='Soy Lady Sinestra' WHERE `ID`=21306;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시네스트라여, 난 이번 일을 필요 이상으로 더 질질 끌 생각이 없소. 당신은 시간을 계속 질질 끌어왔지 않소? 그러니 이제 용아귀 부족에 원하는 게 뭔지 말해보시오.', `MaleText_loc4`='我不想说太多废话，女伯爵希奈丝特拉。就直接告诉我你想从龙喉氏族这里得到什么吧。', `MaleText_loc5`='賽絲特拉女士，我將不會拖延超過需要的時間。你已經讓我洗耳恭聽了，現在告訴我你想從龍喉那得到的是什麼。', `MaleText_loc7`='No alargaré esto más de lo necesario Lady Siniestra. Hemos hablado largo y tendido, ahora dime qué quieres de los Faucedraco.' WHERE `ID`=21307;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아제로스에서의 네파리안의 패배에 대해서 필시 들었을 것입니다... 그가 실패했다고는 하지만, 실험은 계속되고 있습니다. 제 주인님께서... 그분께서는 그분의 후계자가 시작했던 일을 계속 진행하고 계십니다.', `FemaleText_loc4`='我相信你肯定已经听说了奈法利安在艾泽拉斯的失败……虽然他失败了，但实验仍然继续着。我的主人……他继续进行着他的儿子没能完成的研究。', `FemaleText_loc5`='無疑的你已經聽說有關奈法利安在艾澤拉斯的失敗了...當他死後，實驗繼續進行中。我的主人...繼續進行他子嗣開始的這項工作。', `FemaleText_loc7`='Sin duda habrás oído hablar de los fracasos de Nefarian en Azeroth... A pesar de que haya caído, los experimentos continúan. Mi maestro... continúa el trabajo que su progenie comenzó.' WHERE `ID`=21308;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 고개를 끄덕입니다.', `FemaleText_loc4`='%s点了点头。', `FemaleText_loc5`='%s點頭。', `FemaleText_loc7`='%s asiente.' WHERE `ID`=21309;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주... 주인님께서? 그분께서 살아계신단 말이오?', `MaleText_loc4`='主……主人？他还活着？', `MaleText_loc5`='那位...那位主人?他活著?', `MaleText_loc7`='¿El... el maestro? ¿Vive?' WHERE `ID`=21310;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='한때 그대는 최고 부관의 자리에 있었지요, 모르고르. 그림 바톨에서 그대의 임무는 그리 쉽게 잊혀지는 게 아니랍니다.', `FemaleText_loc4`='你曾是一位重要的军官，莫格霍尔。我们不会轻易忘记你在格瑞姆巴托所做的一切。', `FemaleText_loc5`='你曾經是一位重要的中尉，莫格。你在格瑞姆巴托的作為令人難忘。', `FemaleText_loc7`='Fuiste un teniente jefe, Mor’ghor. Tu trabajo en Grim Batol no se olvidará fácilmente.' WHERE `ID`=21311;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제... 그대가 발견한 그 황천날개 알이 필요합니다. 결국 그 알들은 주인님의 성과니까요. 당신이 원하는 가격이라면 얼마든지 치를 의향이 있습니다.', `FemaleText_loc4`='现在……我们要你找回龙卵。灵翼龙卵。他们毕竟是主人的东西。无论你出多高的价钱，我们都会和你交换的。', `FemaleText_loc5`='現在...我們需要你發現的那些蛋。虛空之翼的蛋。到底，他們是主人的成果。我們會依你所要求的價格來付款的。', `FemaleText_loc7`='Ahora... Necesitamos los huevos que has recuperado. Los huevos de Ala Abisal. Al fin y al cabo, son un producto del maestro. Pagaremos el precio que pidas.' WHERE `ID`=21312;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 더듬거립니다.', `MaleText_loc4`='%s显得非常紧张，话都说不利索了。', `MaleText_loc5`='%s結結巴巴的說。', `MaleText_loc7`='%s tartamudea.' WHERE `ID`=21313;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조... 좋소, 물론 드려야겠지. 우린 그저 수정과 광석으로 그 알들의 가격을 치렀으면 하오. 우린 탈것이 필요할 테니...', `MaleText_loc4`='是……是，是的……当然，我们只需要这个地方的水晶和矿石。也就是说……我们需要坐骑。', `MaleText_loc5`='呃...是，是...當然。我們只需要來自這個地方的水晶以及礦石。那裡是...我們需要坐騎。', `MaleText_loc7`='Ss... Sí, sí... por supuesto. Solo necesitamos los cristales y minerales de este lugar. Hay... necesitaremos monturas.' WHERE `ID`=21314;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='주인님께서 이 소식에 매우 기뻐하실 겁니다. 검은용군단에서 당신이 원하는 모든 걸 제공할 것임은 물론입니다. 필요하신 만큼 우리의 비룡에 오를 수 있겠군요.', `FemaleText_loc4`='主人听到这个消息一定会很高兴的。黑龙军团会满足你的一切要求，必要的情况下，你可以骑我们的幼龙。', `FemaleText_loc5`='主人聽到這個消息會很高興。黑龍軍團將會提供你所有你所要求的東西。有需要的話你將被准許騎上我們的座龍。', `FemaleText_loc7`='El maestro estará muy satisfecho con estas noticias. El Vuelo Negro os proporcionará todo lo que pidáis. Podréis cabalgar en nuestros dracos si lo necesitáis.' WHERE `ID`=21315;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='모르고르 사령관, 당신의 친절한 협조에 고맙게 생각합니다. 이제 떠나야겠군요.', `FemaleText_loc4`='感谢你的慷慨，莫格霍尔。但我现在必须走了。', `FemaleText_loc5`='感謝你的好意，莫格。我現在必須告辭了。', `FemaleText_loc7`='Agradezco tu atención, Mor’ghor. Ahora debo irme.' WHERE `ID`=21316;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 바닥에 쓰러집니다.', `FemaleText_loc4`='%s倒在了地上。', `FemaleText_loc5`='%s倒了下來。', `FemaleText_loc7`='%s cae al suelo.' WHERE `ID`=21317;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 끝나지 않았다!', `MaleText_loc4`='我和你没完！', `MaleText_loc5`='我不會對你善罷甘休!', `MaleText_loc7`='¡No he acabado contigo!' WHERE `ID`=21318;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살아서 나가지 못할 것이다!', `MaleText_loc4`='你永远都别想活着离开这里！', `MaleText_loc5`='你休想活著離開!', `MaleText_loc7`='¡No saldrás vivo de aquí!' WHERE `ID`=21319;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정하라고!', `MaleText_loc4`='冷静！', `MaleText_loc5`='好冷!', `MaleText_loc7`='¡Relájate!', `FemaleText_loc1`='진정하라고!', `FemaleText_loc4`='冷静！', `FemaleText_loc5`='好冷!', `FemaleText_loc7`='¡Relájate!' WHERE `ID`=21320;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<장화를 닦고 있는 머드럼프>', `MaleText_loc4`='<玛德拉普正在擦着他的靴子。>', `MaleText_loc5`='<馬朗正在擦亮他的靴子。>', `MaleText_loc7`='<El sobrestante jefe Limo limpia sus botas.>' WHERE `ID`=21321;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실력이 눈에 띄게 늘었군. 이제 여기서 더 배울 게 없겠소이다. 혹시 더 배우고 싶은 게 있거든 언더시티에 있는 조셉 그레고리안을 만나보도록 하시오.', `MaleText_loc4`='$c，你的技艺进展得不错嘛，我认为时机已经成熟了。如果你想要进一步提升技能的话，就去幽暗城拜访乔瑟夫·格里高利吧。', `MaleText_loc5`='你的技術很引人注意，$c，而我相信該是你離開這裡的時候了。如果你想要擴展你的見識的話，到幽暗城去找喬瑟夫·格里高利。', `MaleText_loc7`='Tu destreza es admirable, $c, y creo que ha llegado el momento de que abandones este establecimiento. Si deseas ampliar tus horizontes, visita a Josef Gregorian en Entrañas.' WHERE `ID`=21322;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='실력이 아주 많이 늘었군요. 이제는 제가 더 가르쳐 드릴 것이 없답니다. 오그리마라는 도시의 안쪽 냄새나는 곳에 록시크라는 실력이 좋은 기술자가 있다고들 하던데, 그 기술자라면 당신에게 가르쳐 줄 것이 있을 겁니다.', `FemaleText_loc4`='你在工程学上的造诣已经完全超越了我，我没有什么可以教你的了。我听说臭气熏天的奥格瑞玛里面有一位名叫罗克希克的工程师，他技艺精湛，应该能做你的老师。', `FemaleText_loc5`='你已經完全的進步到我所能教導你的範圍之外了。我聽說有一個熟練的工程師叫羅克希克，就位於一座城市叫奧格瑪當中的一處骯髒地區，他應該可以訓練你。', `FemaleText_loc7`='Has mejorado lo suficiente en este campo, hasta quedar por encima de mi capacidad de enseñar. He oído que hay un habilidoso ingeniero llamado Roxxik, que podría entrenarte, en el pozo apestoso de una ciudad llamada Orgrimmar.' WHERE `ID`=21323;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 더 일 안한다!', `MaleText_loc4`='我不干活了！', `MaleText_loc5`='我不要再工作了!', `MaleText_loc7`='¡Yo no trabajar más!' WHERE `ID`=21324;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바보나 일한다! 일 더 안 한다!', `MaleText_loc4`='工作真没劲！我不做了！', `MaleText_loc5`='工作太累了!不要再做了!', `MaleText_loc7`='¡El trabajo es una caca! ¡NO MÁS!' WHERE `ID`=21325;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 강하다! 누구도 내게 뭐 하라고 하지 않는다!', `MaleText_loc4`='我有力气！但没人告诉我干什么！', `MaleText_loc5`='我力量強大!沒有人能夠叫我做事!', `MaleText_loc7`='¡Soy el poderoso! ¡Nadie darme órdenes!' WHERE `ID`=21326;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 몸이 무엇으로 되어 있는지 한번 보자꾸나, $n!', `MaleText_loc4`='让我看看你有什么本事，$n！', `MaleText_loc5`='讓我看看你是怎麼做成的，$n!', `MaleText_loc7`='¡Muéstrame de qué estás hecho, $n!' WHERE `ID`=21327;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 그의 보호막이 부서지자 광포해집니다.', `MaleText_loc4`='%s看见手中的盾牌破碎之后，更加恼怒了。', `MaleText_loc5`='%s在他的盾破碎時變得憤怒。', `MaleText_loc7`='%s se enfada al hacerse añicos su escudo.' WHERE `ID`=21328;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 내 애완동물을 자유롭게 풀어줬구나! 너의 영혼이 녀석의 다음 식사가 되리라.', `MaleText_loc4`='哈哈！你放出了我的宠物！那么你的灵魂就是它的下一顿饭了。', `MaleText_loc5`='哈!你釋放了我的寵物!你的靈魂將是它的下一餐。', `MaleText_loc7`='¡Ja! ¡Has desatado a mi mascota! Tu alma será su próxima comida.' WHERE `ID`=21329;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런트, 차렷!', `MaleText_loc4`='立正，步兵！', `MaleText_loc5`='立正注意，蠻兵!', `MaleText_loc7`='¡Firme, soldado!' WHERE `ID`=21330;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아으으으윽! 알았다, 알았어, 나 일 다시 한다!', `MaleText_loc4`='哇！好吧，好吧。我回去工作！', `MaleText_loc5`='嗚喔喔喔!好，沒問題，我回去工作!', `MaleText_loc7`='¡AAAYYYYY! De acuerdo, de acuerdo, mí volver al trabajo.' WHERE `ID`=21331;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만! 부메랑 그만 던지라고! 나 미안해! 나 일한다!', `MaleText_loc4`='嘿！不要再用训诫靴踢我啦！对不起！我马上就干活！', `MaleText_loc5`='嘿!不要再來迴力靴了!我道歉!我工作!', `MaleText_loc7`='¡HEY! ¡No más botarang! ¡Sentirlo! ¡Yo trabajar!' WHERE `ID`=21332;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아악! 부메랑이 나 아프게 한다! 부메랑보다 일이 더 낫군!', `MaleText_loc4`='啊！训诫靴踢得我好疼！我觉得在训诫靴下会工作得更好！', `MaleText_loc5`='嗚!迴力靴傷了我!我覺得工作比迴力靴好!', `MaleText_loc7`='¡UFF! ¡Botarang hacerme daño! ¡Yo pensar que trabajar mejor que botarang!' WHERE `ID`=21333;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 부메랑으로 나 때리는 거지?? 왜??', `MaleText_loc4`='为什么用训诫靴踢我？？为什么？？', `MaleText_loc5`='為什麼它將迴力靴放在那塊皮上??為什麼??', `MaleText_loc7`='¿POR QUÉ PONER BOTARANG EN PIEL? ¿POR QUÉ?' WHERE `ID`=21334;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아으윽! 부메랑!', `MaleText_loc4`='啊！！训诫靴！！', `MaleText_loc5`='啊!迴力靴!', `MaleText_loc7`='¡ARGH! ¡BOTARANG!' WHERE `ID`=21335;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아야아야! 언젠가 나 저 부메랑 갖는다...', `MaleText_loc4`='啊呀！总有一天我也要拿到训诫靴……', `MaleText_loc5`='啊呀呀!有天我會擁有那個迴力靴...', `MaleText_loc7`='¡AYAYA! Un día de estos yo tener el botarang...' WHERE `ID`=21336;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자 녀석, 네 녀석이 누구건 다른 침입자의 본보기로 삼으리라!', `MaleText_loc4`='不管你是谁，入侵者。我要惩罚你，作为一个警告！', `MaleText_loc5`='無論你是誰，入侵者，我都會拿你來當舉例!', `MaleText_loc7`='¡Seas quien seas, intruso, te usaré como ejemplo!' WHERE `ID`=21337;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='건방진 놈!', `MaleText_loc4`='不自量力！', `MaleText_loc5`='不自量力!', `MaleText_loc7`='¡Cuánta arrogancia!' WHERE `ID`=21338;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 너! 할 얘기가 있으니 이리 와라!', `MaleText_loc4`='你！就是你！我必须和你谈谈！', `MaleText_loc5`='你在那邊!我一定要跟你談談!', `MaleText_loc7`='¡El de allí! ¡Tengo que hablar contigo!' WHERE `ID`=21339;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저주를 퍼부어주마, $r! 나를 오래 붙잡아 두지는 못할 것이다!', `MaleText_loc4`='无尽的诅咒等待着你，$r！这座监狱再也关不住我了！', `MaleText_loc5`='詛咒你一千次，$r!這個監牢將無法將我關太久的!', `MaleText_loc7`='¡Te maldigo mil veces, $r! ¡Esta prisión no me retendrá durante mucho tiempo!' WHERE `ID`=21340;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겁쟁이 녀석, 도망갈 곳은 어디도 없다!', `MaleText_loc4`='你无处可逃了，懦夫！', `MaleText_loc5`='你無路可逃了，懦夫!', `MaleText_loc7`='¡No tienes escapatoria, cobarde!' WHERE `ID`=21341;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뒤틀린 잿빛혓바닥일족이여, 너희의 지도자가 말하노라!', `MaleText_loc4`='灰舌破碎者们，你们的首领有话要说！', `MaleText_loc5`='灰舌部族的失落者，你的領袖在說話!', `MaleText_loc7`='Tábido de la tribu Lengua de ceniza, tu líder habla.' WHERE `ID`=21342;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 배신자는 더 이상 우리를 지배하지 못한다. 잿빛혓바닥일족의 영혼을 지배하던 검은 마법의 힘이 파괴된 것이다!', `MaleText_loc4`='背叛者不再掌控着我们的命运了，他施加在灰舌氏族灵魂上的邪恶魔咒已经消散了！', `MaleText_loc5`='背叛者不再統治我們。他加諸在灰舌靈魂上的黑暗魔法已經被消除了!', `MaleText_loc7`='El Traidor ya no nos domina. ¡La magia oscura que practicaba sobre el alma Lengua de ceniza ha sido destruida!' WHERE `ID`=21343;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠에서 빠져 나와라! 우리의 진정한 적을 물리치기 위해 내가 너희를 다시 이끈다! 쇠사슬을 벗어 던져라! 무기를 들고 일리다리 놈들에 맞서라!', `MaleText_loc4`='从阴影中解脱吧！我将领导你们对抗真正的敌人。脱下你们的镣铐，拿起武器，去对抗你们的伊利达雷主人吧！！', `MaleText_loc5`='從黑暗中現身!我已經回來帶領你們對抗我們真正的敵人!去除你們的鎖鍊，舉起你們的武器對抗你們的伊利達瑞主人吧!', `MaleText_loc7`='¡Salgan de las sombras! ¡He vuelto para guiarlos contra nuestro verdadero enemigo! ¡Despojen de sus cadenas y alcen sus armas contra nuestros amos Illidari!' WHERE `ID`=21344;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='머드럼프, 제 부메랑이 사라졌어요. 그게 엉뚱한 곳으로 날아가서 어떤 쓸모없는 일꾼의 등에 붙어 버렸나 봐요.', `MaleText_loc4`='我把我的训诫靴弄丢了，玛德拉普。我想它可能卡在一个没用的苦工背上了。', `MaleText_loc5`='我遺失了我的迴力靴，馬朗。我想它可能故障了，現在正卡在一個沒用的苦工背後吧。', `MaleText_loc7`='He perdido mi botarang, sobrestante jefe Limo. Creo que puede haber fallado y estar incrustado en el trasero de algún insignificante trabajador.', `FemaleText_loc1`='머드럼프, 제 부메랑이 사라졌어요. 그게 엉뚱한 곳으로 날아가서 어떤 쓸모없는 일꾼의 등에 붙어 버렸나 봐요.', `FemaleText_loc4`='我把我的训诫靴弄丢了，玛德拉普。我想它可能卡在一个没用的苦工背上了。', `FemaleText_loc5`='我遺失了我的迴力靴，馬朗。我想它可能故障了，現在正卡在一個沒用的苦工背後吧。', `FemaleText_loc7`='He perdido mi botarang, sobrestante jefe Limo. Creo que puede haber fallado y estar incrustado en el trasero de algún insignificante trabajador.' WHERE `ID`=21345;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 부메랑으로 흠씬 두들겨 패기 전에 냉큼 꺼지라고!', `MaleText_loc4`='滚开，否则我就用训诫靴踢你。', `MaleText_loc5`='在我用我的迴力靴打你之前快滾。', `MaleText_loc7`='Piérdete antes de que te dé una paliza con mi botarang.' WHERE `ID`=21346;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자신에게 주문 시전', `MaleText_loc4`='[DEBUG] Cast spell on me [DEBUG]', `MaleText_loc5`='[DEBUG]在我身上施法[DEBUG]', `MaleText_loc7`='[DEBUG] Lanzar hechizo sobre mí [DEBUG]', `FemaleText_loc1`='자신에게 주문 시전', `FemaleText_loc4`='[DEBUG] Cast spell on me [DEBUG]', `FemaleText_loc5`='[DEBUG]在我身上施法[DEBUG]', `FemaleText_loc7`='[DEBUG] Lanzar hechizo sobre mí [DEBUG]' WHERE `ID`=21347;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아카마 만세!', `MaleText_loc4`='阿卡玛万岁！', `MaleText_loc5`='阿卡瑪萬歲!', `MaleText_loc7`='¡Saludos Akama!' WHERE `ID`=21348;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 해보시오, 그런트.', `MaleText_loc4`='继续保持下去，步兵。', `MaleText_loc5`='努力並且持續下去，蠻兵。', `MaleText_loc7`='Intenta seguir el ritmo, soldado.' WHERE `ID`=21349;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 지도자에게 영광을! 아카마 만세!', `MaleText_loc4`='为我们的首领欢呼！阿卡玛万岁！', `MaleText_loc5`='我們的領導萬歲!阿卡瑪萬歲!', `MaleText_loc7`='¡Saludad a nuestro líder! ¡Saludos Akama!' WHERE `ID`=21350;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저의 생명의 정수를 거두어주십시오, 주인님!', `MaleText_loc4`='接收我的生命精华吧，主人！', `MaleText_loc5`='主人，拿走我的生命精華吧!', `MaleText_loc7`='¡Toma la esencia de mi vida, maestro!' WHERE `ID`=21351;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 전투에서 동료가 쓰러지는 것을 보고 점점 광포해집니다!', `MaleText_loc4`='%s看到他的朋友们在战斗中倒下，变得愈加愤怒了！', `MaleText_loc5`='%s看到他的盟友一個個在戰鬥中倒下而變得愈來愈憤怒!', `MaleText_loc7`='¡%s está cada vez más enfadado al ver a sus aliados caer en el combate!', `FemaleText_loc1`='%s|1이;가; 전투에서 동료가 쓰러지는 것을 보고 점점 광포해집니다!', `FemaleText_loc4`='%s看到他的朋友们在战斗中倒下，变得愈加愤怒了！', `FemaleText_loc5`='%s看到他的盟友一個個在戰鬥中倒下而變得愈來愈憤怒!', `FemaleText_loc7`='¡%s está cada vez más enfadado al ver a sus aliados caer en el combate!' WHERE `ID`=21352;
