UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제대로 된 일격을 가하지 못하면, 몇 년 동안 비룡의 마구간이나 청소하게 될 줄 알아라!', `MaleText_loc4`='要是你还不使出全力的话，就要被派去清扫一年的幼龙粪便！', `MaleText_loc5`='如果你不開始發動真正的攻擊，你將會去打掃龍的柵欄一整年!', `MaleText_loc7`='¡Si no empiezas a pegar puñetazos de verdad, pasarás el próximo año limpiando los establos de los dracos!', `FemaleText_loc1`='제대로 된 일격을 가하지 못하면, 몇 년 동안 비룡의 마구간이나 청소하게 될 줄 알아라!', `FemaleText_loc4`='要是你还不使出全力的话，就要被派去清扫一年的幼龙粪便！', `FemaleText_loc5`='如果你不開始發動真正的攻擊，你將會去打掃龍的柵欄一整年!', `FemaleText_loc7`='¡Si no empiezas a pegar puñetazos de verdad, pasarás el próximo año limpiando los establos de los dracos!' WHERE `ID`=21356;
