UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 당신도 나처럼 안대를 했군, 그렇지? 친구, 이제 안대를 하고 다니면 안 된다는 걸 확실하게 하고 싶군그래.', `MaleText_loc4`='哦，你喜欢我的眼罩呀？嗯，不过你还是别戴它的好。', `MaleText_loc5`='喔，你喜歡我的眼罩對吧?好吧，只是確認一下你不需要自己戴一個$g少年:少女;。', `MaleText_loc7`='Oh, ¿te gusta mi parche, verdad? Bueno, asegúrate de no tener que llevar uno $g chico : chica;.' WHERE `ID`=21358;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='엥? 무슨 일이죠? 이보세요, 전 좀 바쁘거든요!$B$B아, 도와주러 오신거라면 언제나 환영이랍니다.', `FemaleText_loc4`='嗯？什么？我这里有点忙，朋友！$B$B当然，要是你是来帮忙的，我有着整个世界的时间。', `FemaleText_loc5`='啊?什麼?我這裡有點忙，朋友!$B$B當然，如果你是來這裡幫忙的，我就有很多時間了。', `FemaleText_loc7`='¿Huh? ¿Qué? Estoy un poco ocupada, $gamigo:amiga;.$B$BClaro que si has venido para ayudar, tengo todo el tiempo del mundo.' WHERE `ID`=21359;
