UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와우! 하늘경비대 정말 멋있다!', `MaleText_loc4`='哦嚯！前进，天空卫队！', `MaleText_loc5`='嗚呼!上吧禦天者!', `MaleText_loc7`='¡Yu ju! ¡Bien Guardia del cielo!', `FemaleText_loc1`='와우! 하늘경비대 정말 멋있다!', `FemaleText_loc4`='哦嚯！前进，天空卫队！', `FemaleText_loc5`='嗚呼!上吧禦天者!', `FemaleText_loc7`='¡Yu ju! ¡Bien Guardia del cielo!' WHERE `ID`=21369;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='와우! 가오리를 여기까지 데려와 줘서 고마워요. 이렇게까지 하지 않았어도 되는데...', `FemaleText_loc4`='哇哦！感谢你一路把我带回这里。你原本不需要这样做的。', `FemaleText_loc5`='哇!感謝你費盡方法將它帶回來這裡。你其實不用那樣做得。', `FemaleText_loc7`='¡Guau! Gracias por volver a traerlo hasta aquí. No tenías por qué hacerlo.' WHERE `ID`=21370;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신 훌륭하군요! 저 가오리를 잘 돌보도록 할게요.', `FemaleText_loc4`='你真是个讨人喜欢的家伙。我保证会好好照顾这只以太鳐的。', `FemaleText_loc5`='你是個大好人!我會確保鰭刺有被妥善照顧的。', `FemaleText_loc7`='¡Eres un encanto! Yo me encargaré de que la raya esté bien cuidada.' WHERE `ID`=21371;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이리로 데려와 주서 정말 정말 고마워요! 당신이 내 최고의 조련사가 될 것 같네요!', `FemaleText_loc4`='非常感谢你把它带回来。你会成为我最好的放牧者！', `FemaleText_loc5`='真是太太太太感謝你將它帶回來。我想你將會是我有史以來最好的牧者!', `FemaleText_loc7`='Muuuuchas gracias por volver a traerlo. ¡Creo que vas a ser mi mejor retador!' WHERE `ID`=21372;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오, 가오리가 너무 아름답지 않나요! 이 녀석을 훈련해서 하늘로 날게 하고 싶어 죽겠어요!', `FemaleText_loc4`='噢，她是不是很漂亮啊？我等不及要好好训练她，与她一起在天空翱翔了！', `FemaleText_loc5`='喔，她真是個美人!等不及要好好的訓練她並回到空中去!', `FemaleText_loc7`='Oh, ¿no es una belleza? ¡No puedo esperar a que esté debidamente entrenada y de vuelta en el aire!' WHERE `ID`=21373;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가오리가 너무 귀엽지 않나요? 내 앞에 이런 녀석을 데려와 줘서 정말 고마워요!!!', `FemaleText_loc4`='他是不是很可爱？！感谢你把他带回我这里！！！', `FemaleText_loc5`='他是不是很可愛啊?!感謝你將他帶來給我!!!', `FemaleText_loc7`='¿No es una monada? ¡¡Gracias por traérmelo!!' WHERE `ID`=21374;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하늘경비대엔 이 가오리들이 충분한 적이 절대 없답니다. 당신은 말 그대로... 저희가 떨어지지 않게 해 주시는군요!', `FemaleText_loc4`='天空卫队需要长期补充以太鳐的储量。在你的帮助下，我们才能在天空翱翔。', `FemaleText_loc5`='我們禦天者永遠都缺乏這些鰭刺。你使我們免於缺乏...毫不誇張!', `FemaleText_loc7`='Estos rayos nunca son suficientes para la Guardia del cielo. Nos mantenéis a flote... ¡literalmente!' WHERE `ID`=21375;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='참 잘했어요! 이 가오리는 상태가 괜찮아 보이는군요. 고맙습니다!', `FemaleText_loc4`='干得好！她各方面条件都挺不错的。谢谢你！', `FemaleText_loc5`='做得好!她看起來狀況很好。謝謝你!', `FemaleText_loc7`='¡Bien hecho! Parece estar en buenas condiciones. ¡Gracias!' WHERE `ID`=21376;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='웃후! 훈련할 가오리들이 더 생겼군요!', `FemaleText_loc4`='哇！更多需要训练的虚空鳐！', `FemaleText_loc5`='嗚呼!有更多的鰭刺可以訓練囉!', `FemaleText_loc7`='¡Yu ju! ¡Más rayas para entrenar!' WHERE `ID`=21377;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈이 감히 나를 소환한 것이냐!', `MaleText_loc4`='你竟敢召唤我，$n？', `MaleText_loc5`='你竟敢召喚我，$n?', `MaleText_loc7`='¿Cómo osas invocarme, $n?' WHERE `ID`=21378;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='프리즘 내에 불타는 눈들이 당신의 마음을 불안함으로 뒤덮고 있습니다...', `MaleText_loc4`='棱柱中燃烧的眼睛让你感到恐怖……', `MaleText_loc5`='燒毀在稜柱內的眼睛讓你的心裡充滿一股恐懼的感覺...', `MaleText_loc7`='Unos ojos ardientes dentro del prisma llenan tu mente con un sentimiento de pavor...' WHERE `ID`=21379;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='프리즘에 35개의 에펙시스 결정을 놓습니다.', `MaleText_loc4`='将35块埃匹希斯碎片放入棱柱中。', `MaleText_loc5`='將35個頂尖裂片放進稜柱內。', `MaleText_loc7`='Coloca 35 fragmentos de ápices en el prisma.', `FemaleText_loc1`='프리즘에 35개의 에펙시스 결정을 놓습니다.', `FemaleText_loc4`='将35块埃匹希斯碎片放入棱柱中。', `FemaleText_loc5`='將35個頂尖裂片放進稜柱內。', `FemaleText_loc7`='Coloca 35 fragmentos de ápices en el prisma.' WHERE `ID`=21380;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지옥 수정괴철로로 당신의 에펙시스 결정을 불안정한 야수의 영약으로 변환할 수 있습니다. 이 영약은 더 민첩하고, 강해지면서 체력이 좋아지게 합니다.$B$B아래 목록에서 선택하시기 바랍니다.', `MaleText_loc4`='邪能水晶熔炉可以将埃匹希斯碎片转化成不稳定的野兽合剂。这种合剂能让饮用者变得更加敏捷、强壮，并且更具活力。$B$B来吧，做出你的选择。', `MaleText_loc5`='惡魔水晶熔爐可以用來轉換你的頂尖裂片為野獸的不穩定精鍊藥劑。這些藥水能讓飲用者更加敏捷，更加強壯而且精力充沛。$B$B在下面當中選一個吧。', `MaleText_loc7`='La forja de cristal vil puede usarse para transformar tus fragmentos de ápices en frascos inestables de la bestia. Estos frascos vuelven al que los bebe más ágil, fuerte y feliz.$B$BElige, abajo.' WHERE `ID`=21381;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='10개의 에펙시스 결정을 사용하여 1개의 불안정한 야수의 영약을 얻습니다.', `MaleText_loc4`='用10块埃匹希斯碎片购买1瓶不稳定的野兽合剂', `MaleText_loc5`='購買1瓶野獸的不穩定精鍊藥劑需要10個頂尖裂片。', `MaleText_loc7`='Compra un frasco inestable de la bestia por 10 fragmentos de ápices.', `FemaleText_loc1`='10개의 에펙시스 결정을 사용하여 1개의 불안정한 야수의 영약을 얻습니다.', `FemaleText_loc4`='用10块埃匹希斯碎片购买1瓶不稳定的野兽合剂', `FemaleText_loc5`='購買1瓶野獸的不穩定精鍊藥劑需要花費10個頂尖裂片。', `FemaleText_loc7`='Compra un frasco inestable de la bestia por 10 fragmentos de ápices.' WHERE `ID`=21382;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<가지고 있는 에펙시스 결정을 지옥 수정괴철로에 놓고 레버를 당기자, 괴철로의 장치가 이 세상의 것이 아닌 소리를 내면서 결정을 갈아 가루로 만듭니다. 몇 분이 지난 후에, 장치의 기계 입에서 영약이 튀어나옵니다.>', `MaleText_loc4`='<当你将埃匹希斯碎片放入邪能水晶熔炉并拉下控制杆后，从熔炉中传来了物体被碾碎的声音。很快一瓶合剂就从熔炉口落了出来。>', `MaleText_loc5`='<當你將你的頂尖裂片放進惡魔水晶熔爐並推動控制桿時，這個裝置發出一股沒聽過的聲響，像是在將這些裂片捻為粉塵。幾分鐘後你的藥水就從它的「開口」中掉出來了。>', `MaleText_loc7`='<Al colocar los fragmentos de ápices en la forja de cristal vil y tirar de la palanca, el aparato hace un ruido de otro mundo mientras los convierte en polvo. Unos instantes después tu frasco sale de su "boca".>' WHERE `ID`=21383;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또다시 영약을 만들기 위해 지옥 수정괴철로를 사용합니다.', `MaleText_loc4`='利用邪能水晶熔炉制造另一瓶合剂。', `MaleText_loc5`='使用惡魔水晶熔爐進行另一次採買。', `MaleText_loc7`='Usa la forja de cristal vil para realizar otra compra.', `FemaleText_loc1`='또다시 영약을 만들기 위해 지옥 수정괴철로를 사용합니다.', `FemaleText_loc4`='利用邪能水晶熔炉制造另一瓶合剂。', `FemaleText_loc5`='使用惡魔水晶熔爐進行另一次採買。', `FemaleText_loc7`='Usa la forja de cristal vil para realizar otra compra.' WHERE `ID`=21384;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='50개의 에펙시스 결정을 사용하여 5개의 불안정한 야수의 영약을 얻습니다.', `MaleText_loc4`='用50块埃匹希斯碎片购买5瓶不稳定的野兽合剂', `MaleText_loc5`='購買5瓶野獸的不穩定精鍊藥劑需要50個頂尖裂片。', `MaleText_loc7`='Compra 5 frascos inestables de la bestia por 50 fragmentos de ápices.', `FemaleText_loc1`='50개의 에펙시스 결정을 사용하여 5개의 불안정한 야수의 영약을 얻습니다.', `FemaleText_loc4`='用50块埃匹希斯碎片购买5瓶不稳定的野兽合剂', `FemaleText_loc5`='購買5瓶野獸的不穩定精鍊藥劑需要50個頂尖裂片。', `FemaleText_loc7`='Compra 5 frascos inestables de la bestia por 50 fragmentos de ápices.' WHERE `ID`=21385;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<가지고 있는 에펙시스 결정을 지옥 수정괴철로에 놓고 레버를 당기자, 괴철로의 장치가 이 세상의 것이 아닌 소리를 내면서 결정을 갈아 가루로 만듭니다. 몇 분이 지난 후에, 장치의 기계 입에서 영약이 튀어나옵니다.>', `MaleText_loc4`='<当你将埃匹希斯碎片放入邪能水晶熔炉并拉下控制杆后，从熔炉中传来了物体被碾碎的声音。很快一瓶合剂就从熔炉口落了出来。>', `MaleText_loc5`='<當你將你的頂尖裂片放進惡魔水晶熔爐並推動控制桿時，這個裝置發出一股沒聽過的聲響，像是在將這些裂片捻為粉塵。幾分鐘後你的藥水就從它的「開口」中掉出來了。>', `MaleText_loc7`='<Al colocar los fragmentos de ápices en la forja de cristal vil y tirar de la palanca, el aparato hace un ruido de otro mundo mientras los convierte en polvo. Unos instantes después tu frasco sale de su "boca".>' WHERE `ID`=21386;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바시르 수정괴철로는 에펙시스 결정을 불안정한 마술사의 영약으로 변환하는데 쓰입니다. 이 영약을 마시면 지능이 증가하고 원기가 왕성해지며, 공격력과 치유 능력이 증가합니다.$B$B아래 목록에서 선택하시기 바랍니다.', `MaleText_loc4`='巴什伊尔水晶熔炉可以将埃匹希斯碎片转化成不稳定的巫术合剂。这种合剂能让饮用者变得更加聪明、更具活力，还可以增加法术伤害和治疗效果。$B$B来吧，做出你的选择。', `MaleText_loc5`='貝許爾水晶熔爐可以用來轉換你的頂尖裂片為巫士的不穩定精鍊藥劑。這些藥水能讓飲用者更加聰明，精力充沛，並增加他們傷害以及治療法術的傷害效果。$B$B在下面當中選一個吧。', `MaleText_loc7`='La forja de cristal Bash''ir puede usarse para transformar tus fragmentos de ápices en frascos inestables del hechicero. Estos frascos vuelven al que los bebe más ágil y feliz y aumentan la efectividad de sus hechizos de ataque y sanación.$B$BElige debajo.' WHERE `ID`=21387;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='10개의 에펙시스 결정을 사용하여 1개의 불안정한 마술사의 영약을 얻습니다.', `MaleText_loc4`='用10块埃匹希斯碎片购买1瓶不稳定的巫术合剂', `MaleText_loc5`='購買1瓶巫士的不穩定精鍊藥劑需要10個頂尖裂片', `MaleText_loc7`='Compra un frasco inestable del hechicero por 10 fragmentos de ápices.', `FemaleText_loc1`='10개의 에펙시스 결정을 사용하여 1개의 불안정한 마술사의 영약을 얻습니다.', `FemaleText_loc4`='用10块埃匹希斯碎片购买1瓶不稳定的巫术合剂', `FemaleText_loc5`='購買1瓶巫士的不穩定精鍊藥劑需要10個頂尖裂片', `FemaleText_loc7`='Compra un frasco inestable del hechicero por 10 fragmentos de ápices.' WHERE `ID`=21388;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또다시 영약을 만들기 위해 바시르 수정괴철로를 사용합니다.', `MaleText_loc4`='利用巴什伊尔水晶熔炉制造另一瓶合剂。', `MaleText_loc5`='使用貝許爾水晶熔爐來進行另一次購買。', `MaleText_loc7`='Usa la forja de cristal Bash''ir para realizar otra compra.', `FemaleText_loc1`='또다시 영약을 만들기 위해 바시르 수정괴철로를 사용합니다.', `FemaleText_loc4`='利用巴什伊尔水晶熔炉制造另一瓶合剂。', `FemaleText_loc5`='使用貝許爾水晶熔爐來進行另一次購買。', `FemaleText_loc7`='Usa la forja de cristal Bash''ir para realizar otra compra.' WHERE `ID`=21389;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<가지고 있는 에펙시스 결정을 바시르 수정괴철로의 움푹 패인 곳에 놓고 레버를 당기자, 장치가 수정을 분해합니다. 몇 분이 지난 후에, 당신의 발 앞에 영약이 나타납니다.>', `MaleText_loc4`='<当你将埃匹希斯碎片放入巴什伊尔水晶熔炉并拉下控制杆后，从熔炉中传来了物体被碾碎的声音。很快一瓶合剂就落在了你的脚旁。>', `MaleText_loc5`='<當你將頂尖裂片放進貝許爾水晶熔爐的凹槽並推動控制桿時，這個裝置直接壓碎這些裂片。幾分鐘後你的藥水就出現在你的腳邊了。>', `MaleText_loc7`='<Cuando colocas tus fragmentos de ápices en el hueco de la forja de cristal Bash''ir y tiras de la palanca, el aparato, literalmente, los desintegra. Unos momentos después tu frasco aparece a tus pies.>' WHERE `ID`=21390;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='50개의 에펙시스 결정을 사용하여 5개의 불안정한 마술사의 영약을 얻습니다.', `MaleText_loc4`='用50块埃匹希斯碎片购买5瓶不稳定的巫术合剂', `MaleText_loc5`='購買5瓶巫士的不穩定精鍊藥劑需要50個頂尖裂片', `MaleText_loc7`='Compra 5 frascos inestables del hechicero por 50 fragmentos de ápices.', `FemaleText_loc1`='50개의 에펙시스 결정을 사용하여 5개의 불안정한 마술사의 영약을 얻습니다.', `FemaleText_loc4`='用50块埃匹希斯碎片购买5瓶不稳定的巫术合剂', `FemaleText_loc5`='購買5瓶巫士的不穩定精鍊藥劑需要50個頂尖裂片', `FemaleText_loc7`='Compra 5 frascos inestables del hechicero por 50 fragmentos de ápices.' WHERE `ID`=21391;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<가지고 있는 에펙시스 결정을 바시르 수정괴철로의 움푹 패인 곳에 놓고 레버를 당기자, 장치가 수정을 분해합니다. 몇 분이 지난 후에, 당신의 발 앞에 영약이 나타납니다.>', `MaleText_loc4`='<当你将埃匹希斯碎片放入巴什伊尔水晶熔炉并拉下控制杆后，从熔炉中传来了物体被碾碎的声音。很快一瓶合剂就落在了你的脚旁。>', `MaleText_loc5`='<當你將頂尖裂片放進貝許爾水晶熔爐的凹槽並推動控制桿時，這個裝置直接壓碎這些裂片。幾分鐘後你的藥水就出現在你的腳邊了。>', `MaleText_loc7`='<Cuando colocas tus fragmentos de ápices en el hueco de la forja de cristal Bash''ir y tiras de la palanca, el aparato, literalmente, los desintegra. Unos momentos después tus frascos aparecen a tus pies.>' WHERE `ID`=21392;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 우리의 골칫거리를 날려줄 수 있길 바라오. 우린 10명의 아들을 데리고 있으려 했으나, 녀석들 모두가 하지 말아야 할 것을 하고 싶어하지 뭐요!$B$B그래도 아버지로서, 해야 할 도리는 다하는 것이오.', `MaleText_loc4`='希望你能帮我们解决这件麻烦事。试想一下，如果你有10个儿子，他们都想尝试去做那些自己力所不能及的事，你该怎么办？$B$B尽管如此，我们却必须尽到做父亲的职责。', `MaleText_loc5`='我們希望你能夠舒緩我們的頭痛。你試試看有10個孩子，每一個都想去做他們本來不做的事!$B$B儘管如此，身為一位父親，我們得做好我們的本份。', `MaleText_loc7`='Esperamos que puedas librarnos de nuestros dolores de cabeza. ¡Intenta tener diez hijos, los diez intentando ser algo para lo que no están destinados!$B$BAun así, como padre, hacemos lo que debemos.' WHERE `ID`=21393;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 당신도 아들이 있소?$B$B우리가 오그릴라로 와서 수정이 우릴 더 똑똑하게 만들어 주기 전이 더 행복한 삶이었던 것 같소. 그 전엔 아이들이 말을 안 들으면 녀석의 두 입을 다물게 하려고 머리를 쾅 부딪히게 하면 되었을 테니 말이오. 이제 녀석들이 하는 거라곤 샤타리 하늘경비대에 가려고 우릴 성가시게 하는 게 다이니...$B$B모르는 게 약인데 말이오!', `MaleText_loc4`='你有孩子吗，$c？$B$B听我说，来到奥格瑞拉之后，我们都觉得没有以前快乐了。那些水晶让孩子们变得聪明了许多。从前，我们只需要敲打他们的小脑瓜就能让他们闭嘴。而现在，他们却整天吵着问我们各种各样关于天空卫队的事情。$B$B无知真是幸福！', `MaleText_loc5`='你有小孩嗎，$c?$B$B讓我們告訴你，我們覺得在我們到達歐格利拉，並且被這些水晶變得更有知覺之前快樂多了。以前，我們只要痛打他們的頭就可以讓他們閉嘴。現在他們所做得事就是纏著問我們有關薩塔禦天者的事。$B$B無知是一種福氣啊!', `MaleText_loc7`='¿Tienes hijos, $c?$B$BDeja que te digamos algo, creemos que éramos mucho más felices antes de venir a Ogri''la y que los cristales nos hicieran más conscientes. Antes los habríamos golpeado en la cabeza para callarlos. Ahora, todo lo que hacen es darnos la lata con el Guardia del cielo Sha''tari.$B$B¡La ignorancia es felicidad!' WHERE `ID`=21394;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='휴, 저 녀석은 아직 너무 멍청해서 수정의 영향이 충분치 않다고 말하고 다닌다오. 하지만 녀석도 그 영약을 가져다준 당신에게 고마워하고 있소이다.$B$B이제, 아홉 녀석만 남았군... 아윽!$B$B<한숨을 쉬는 토르커스의 양쪽 머리>$B$B우리 수중에 있는 영약을 원하는 거요? 좋아, 싸게 팔도록 하지.', `MaleText_loc4`='这孩子还是有些愚钝——看来他还需要接受水晶的启迪，不过，谢谢你为他制造了那些合剂。$B$B嗨！还有九个孩子需要你帮忙呢。$B$B<托尔库斯的两个脑袋都叹了口气。>$B$B想从我这里领走一个小孩吗？我愿意便宜卖给你。', `MaleText_loc5`='這個男孩不太會說話 - 發現的水晶還不夠 - 不過，他對於你帶給他的那些藥水還是感覺很感激的。$B$B現在，只剩9個多的孩子要走。唉!$B$B<托卡司的兩個頭同時嘆氣。>$B$B想要帶走一個嗎?我們會賣你便宜一點的。', `MaleText_loc7`='El chico aún es demasiado estúpido para decirlo, no ha habido suficiente exposición a los cristales todavía, pero agradece que le consiguieras esos frascos.$B$BSolo faltan nueve hijos. ¡Gah!$B$B<Las dos cabezas de Torkus suspiran.>$B$B¿Quieres quitarnos uno de las manos? Te lo venderemos baratito.' WHERE `ID`=21395;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오그릴라에 새내기가 오면, 이곳에 있는 수정의 충만한 혜택을 받기에 충분히 노출되진 못한다오. 게다가, 당신은 머리가 하나뿐이니 더 하겠지만 말이오.$B$B한편으로 우리는 이곳에 매우 오랜 시간을 살았소. 그러니 당신이 상상하는 것과 같이 매우 많은 것들에 조예가 깊지.$B$B최근에 우리는 괴철로 기지의 악마들에 매우 관심을 가지게 되었소. 엄밀히 말하자면, 우린 영원히 그 악마들을 없애버릴 방법을 궁리하고 있는 것이라오.$B$B어쨌든 그게 우리 생각이오이다.', `MaleText_loc4`='你刚来奥格瑞拉不久，这些水晶簇的好处你还没有完全体会到呢。何况，你只有一个脑袋。$B$B而我们就不同了。我们在这里住了很长一段时间了。因此，你可以想象我们聪明的头脑精通多少事情。$B$B最近，我们对铸魔营地的恶魔挺感兴趣的。具体来说，我们设计出了一个彻底摆脱他们的好办法。$B$B至少，理论上是那样。', `MaleText_loc5`='身為歐格利拉相關的初訪者，你沒有因為在這裡發現足夠的水晶而獲得他們充份的好處。而且，你只有一個頭而已。$B$B另外一方面，我們已經到這裡有一段時間了。因此，如同你可以想像的，我們已經知道許多重要的事了。$B$B最近，我們對煉冶場的惡魔特別的感興趣。再具體一點，我們已經想出一個方法使我們可以永遠的擺脫他們。$B$B至少，這就是原理。', `MaleText_loc7`='Ya que eres relativamente nuevo en Ogri''la, no has estado expuesto a los cristales el tiempo suficiente para obtener todos sus beneficios. Además, solo tienes una cabeza.$B$BSin embargo, nosotros, como puedes imaginar, sabemos mucho de bastantes cosas.$B$BÚltimamente, nos hemos interesado en los demonios de los Campamentos Forja. En concreto, hemos diseñado una forma de deshacernos de ellos para siempre.$B$BAl menos en teoría.' WHERE `ID`=21396;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하루에 하나 이상의 암흑룬을 만들 수 있으면 좋겠지만 시간만 낭비하는 꼴일 거요. 간단히 물리적으로 불가능한 일이란 말이지. 게다가 이래 가지고는 암흑룬을 통계적으로 신뢰성 있게 만들어 낼 수가 없는 형편이라오.$B$B이곳에 도움을 줄 만큼 더 똑똑한 누군가가 있다면, 그들을 선발해서 필요한 만큼 많은 암흑룬을 얻을 수 있을 테니 우릴 믿으시오.', `MaleText_loc4`='我们希望每天都能制造出一个以上的黑暗符印，但那样做太浪费时间了。从自然法则上来讲也办不到，而且我们的能力有限，这样的出产频率恐怕很难实现。$B$B只要有聪明的家伙愿意帮忙，我们就会将他们征召过来，以此获得更多的黑暗符印。', `MaleText_loc5`='我們希望我們可以在一天內製造出多於一個的暗色符文，不過那可能是浪費時間而已。這簡直是不可能的。而且，我們根本不可能準確的按照速度來製造它們。$B$B相信我們，如果這裡有其他人聰明到可以幫忙的話，他們就會被徵召了，那我們就會有足夠的暗色符文。', `MaleText_loc7`='Nos gustaría poder crear más de una runaoscura diaria, pero sería una pérdida de tiempo. Simplemente, no es físicamente posible. Además, ni siquiera sería fiable crearlas a ese ritmo.$B$BY confía en nosotros, si hubiera alguien lo suficientemente inteligente para ayudar, sería reclutado y tendríamos todas las runaoscuras que quisiéramos.' WHERE `ID`=21397;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바시르 수정괴철로는 에펙시스 결정을 불안정한 마술사의 영약으로 변환하는 데 쓰입니다. 이 영약을 마시면 지능이 향상되고 원기가 왕성해지며, 공격력과 치유 능력이 증가합니다.$B$B그렇지만 1개의 영약을 만드는 데 필요한 10개의 결정을 지니고 있지 않아서 이 괴철로를 작동시킬 수 없는 것 같습니다.', `MaleText_loc4`='巴什伊尔水晶熔炉可以将埃匹希斯碎片转化成不稳定的巫术合剂。这种合剂能让饮用者变得更加聪明，更具活力，还能增加法术伤害和治疗效果。$B$B但是10块埃匹希斯碎片才能购买1瓶合剂，你身上的碎片数量不够。', `MaleText_loc5`='貝許爾水晶熔爐可以用來轉換你的頂尖裂片為巫士的不穩定精鍊藥劑。這些藥水能讓飲用者更加聰明，精力充沛，並增加他們傷害以及治療法術的傷害效果。$B$B不過，看來似乎你連購買一瓶藥水需要的十片裂片都沒有。', `MaleText_loc7`='La forja de cristal Bash''ir puede usarse para transformar tus fragmentos de ápices en frascos inestables del hechicero. Estos frascos vuelven al que los bebe más ágil y feliz y aumentan la efectividad de sus hechizos de ataque y sanación.$B$BSin embargo, parece que no tienes los 10 fragmentos necesarios para comprar un frasco.' WHERE `ID`=21398;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지옥 수정괴철로로 당신의 에펙시스 결정을 불안정한 야수의 영약으로 변환할 수 있습니다. 이 영약은 더 민첩하고, 강해지면서 체력이 좋아지게 합니다.$B$B그렇지만 1개의 영약을 만드는 데 필요한 10개의 결정을 지니고 있지 않아서 이 괴철로를 작동시킬 수 없는 것 같습니다.', `MaleText_loc4`='邪能水晶熔炉可以将埃匹希斯碎片转化成不稳定的野兽合剂。这种合剂能让饮用者变得更加敏捷、强壮和更具活力。$B$B但是10块埃匹希斯碎片才能购买1瓶合剂，你身上的碎片数量不够。', `MaleText_loc5`='惡魔水晶熔爐可以用來轉換你的頂尖裂片為野獸的不穩定精鍊藥劑。這些藥水能讓飲用者更加敏捷，更加強壯而且精力充沛。$B$B不過，看來似乎你連購買一瓶藥水所需的十片裂片都沒有。', `MaleText_loc7`='La forja de cristal vil puede usarse para transformar tus fragmentos de ápices en frascos de la bestia. Estos frascos vuelven al que los bebe más ágil, fuerte y feliz.$B$BSin embargo, parece que no tienes los 10 fragmentos necesarios para comprar un frasco.' WHERE `ID`=21399;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여는 중', `MaleText_loc4`='正在打开', `MaleText_loc5`='開啟', `MaleText_loc7`='Abriendo', `FemaleText_loc1`='여는 중', `FemaleText_loc4`='正在打开', `FemaleText_loc5`='開啟', `FemaleText_loc7`='Abriendo' WHERE `ID`=21400;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가크 작은 $r처럼 오그릴라에 새로 왔다. 저 아래 다른 오우거들은 여기 천국 같다고 항상 말한다. 그렇지만 수정이 가크를 더 똑똑하게 하려고 해서 가크 머리 아프다.$B$B<서로를 보며 고개를 끄덕이는 가크의 두 머리>$B$B우리 수정으로 벼려낸 암흑룬 만드는 거 배운다. 우리가 그거 배우면, 악마들의 공간이동 관문 부순다!', `MaleText_loc4`='甘克和$r一样都是刚来奥格瑞拉的。这里就和下面那些食人魔所说的一样，真是天堂一般的地方。那些水晶簇让甘克变聪明了，但是也让甘克的脑袋很痛。$B$B<甘克的两个脑袋互相点着头。>$B$B我们正在学习制造晶铸黑暗符印。学会的话，就能粉碎恶魔的迁跃门了！', `MaleText_loc5`='賈克像小$r一樣新到歐格利拉。底下的其他巨魔都談論著說它像天堂一樣。不過這些會讓賈克變聰明點的水晶讓賈克的頭好痛。$B$B<賈克的兩個頭互相對彼此點頭。>$B$B我們正在學著製作那個晶鑄暗色符文。當我們學會了，我們就會毀掉那個惡魔的星移門!', `MaleText_loc7`='Gahk nuevo en Ogri''la como $gpequeño:pequeña; $r. Ser como el cielo del que hablan los ogros abajo. Pero a Gahk le duelen las cabezas porque el cristal hacer a Gahk más listo.$B$B<Las dos cabezas de Gahk asienten.>$B$BNosotros aprender a hacer una runaoscura de cristal forjado. ¡Eso ayudar a Ogros a machacar a los demonios!' WHERE `ID`=21401;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가크 이제 똑똑하다! 우리 암흑룬으로 그 수정으로 벼려낸 암흑룬을 만들 수 있는지 알았단 말이다.', `MaleText_loc4`='甘克现在很聪明！我们知道如何将黑暗符印制成晶铸黑暗符印！', `MaleText_loc5`='賈克現在變聰明了!我們知道如何將暗色符文作成晶鑄暗色符文了!', `MaleText_loc7`='¡Gahk ser listo ahora! ¡Nosotros saber convertir la runaoscura en runaoscura de cristal forjado!' WHERE `ID`=21402;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 공간이동 관문 잘 부쉈지만 그 악마들 다시 관문 튼튼하게 하고 있다.$B$B$n 가크에게 암흑룬 더 가져오면 가크 $n 위해 귀한 수정으로 벼려낸 암흑룬 만들어 준다!', `MaleText_loc4`='$n破坏了迁跃门，做得好！但是恶魔又修复了被毁坏的迁跃门。$B$B$n，只要你给甘克另一枚黑暗符印，甘克就为你制作晶铸黑暗符印！', `MaleText_loc5`='$n幹得好能摧毀那些星移門，不過那些惡魔讓星移門變得更強了。$B$B$n替賈克帶回其他的暗色符文然後賈克會為$n做出更特別的晶鑄暗色符文!', `MaleText_loc7`='$n machacar bien puerta de distorsión, pero los demonios volver a hacerse fuertes.$B$B¡$n traer a Gahk más runaoscuras y Gahk hacer runaoscura de cristal forjado especial para $n!' WHERE `ID`=21403;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 오그릴라에 온 것을 환영한다.$B$B이곳의 오우거들은 주위의 수정이 내뿜는 마법을 통해 정신적으로 매우 큰 지각 능력을 얻게 되었다. 수정이 어떻게 작용하는지 완벽하게 알아내진 못했지만, 우리의 새로운 고향에 감사하게 되었고 평화롭게 사는 것이 단 하나의 소망이다.$B$B안타깝게도 악마와 에테리얼들에다가 검은용군단이 그런 평화로움 속에 우릴 내버려 두진 않을 것 같다.', `MaleText_loc4`='欢迎来到奥格瑞拉，$c。$B$B食人魔通过奥格瑞拉周围的水晶簇散发出的魔力获得了敏锐的才智。尽管我们不完全明白这是怎么回事，但我们喜欢这个新家，只想在这里过安宁的生活。$B$B可是恶魔、虚灵，还有黑龙却偏偏要来滋扰生事。', `MaleText_loc5`='歡迎來到歐格利拉，$c。$B$B這裡的巨魔已經設法經由周遭水晶的魔法放射能中大大提升了我們心智的敏銳程度。雖然我們並不完全了解它們是如何運作的，不過我們已經開始欣賞我們的新家，並只想要過平靜的生活。$B$B很不幸的是惡魔及以太族，還有特別是黑龍軍團，將不會讓我們安於平靜。', `MaleText_loc7`='$gBienvenido:Bienvenida; a Ogri''la, $c.$B$BLos ogros aquí hemos conseguido gran agudeza mental gracias a las emanaciones mágicas de los cristales que nos rodean. Aunque no acabamos de entender su funcionamiento, hemos logrado apreciar nuestro nuevo hogar y solo queremos vivir en paz.$B$BPor desgracia, los demonios y etéreos y, en especial, el Vuelo Negro, no nos dejan alcanzar esa paz.' WHERE `ID`=21404;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오그릴라의 모두를 대신해서, 당신의 노력에 감사를 전한다.$B$B<웃음띤 표정을 짓는 추알로르의 오른쪽 머리와 고개를 끄덕이는 추알로르의 왼쪽 머리>$B$B이곳에서 우리를 돕는 것 또한 저 아래 당신이 $g왕:여왕;이 된 우리 형제들을 보호하는 일임을 잊지 마라.', `MaleText_loc4`='我代表奥格瑞拉对你的所做的一切表示感谢，$n。$B$B<库洛尔的左边脑袋点着头，右边脑袋则对着你微笑。>$B$B不要忘了，帮助奥格瑞拉就是帮助我们在刀锋山的食人魔同胞。为了表达对你的敬意，他们已经将你奉为$g国王:女王;。', `MaleText_loc5`='謹代表歐格利拉全體，我們要感謝你的努力，$n。$B$B<當裘阿洛右邊的頭對你笑的同時，左邊的頭對你點了點。>$B$B並且不要忘記，藉由在這裡幫助我們的同時，你也保護了我們在底下那些你已身為$g國王:女王;的同胞們。', `MaleText_loc7`='De parte de todo Ogri''la, agradecemos tus esfuerzos, $n.$B$B<La cabeza izquierda de Chu''a''lor asiente, mientras que su cabeza derecha te sonríe.>$B$BY no olvides que al ayudarnos aquí, también ayudas a proteger a nuestros hermanos allá abajo, para quienes eres como $g un rey : una reina;.' WHERE `ID`=21405;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언제 마법 영약을 더 얻을 수 있는 건가요?', `MaleText_loc4`='我们什么时候再去弄些不可思议的合剂？', `MaleText_loc5`='我們什麼時候要去拿取更多的魔法藥水?', `MaleText_loc7`='¿Cuándo vamos a obtener más frascos mágicos?', `FemaleText_loc1`='언제 마법 영약을 더 얻을 수 있는 건가요?', `FemaleText_loc4`='我们什么时候再去弄些不可思议的合剂？', `FemaleText_loc5`='我們什麼時候要去拿取更多的魔法藥水?', `FemaleText_loc7`='¿Cuándo vamos a obtener más frascos mágicos?' WHERE `ID`=21406;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하늘경비대의 일원이 되는데 필요한 충분한 수량의 마법 영약을 마련한 건가요?', `MaleText_loc4`='那些合剂的数量足够我们加入天空卫队吗？', `MaleText_loc5`='我們擁有足夠的魔法藥水好加入禦天者了嗎?', `MaleText_loc7`='¿Hemos cogido suficientes frascos mágicos para entrar en la Guardia del cielo ya?', `FemaleText_loc1`='하늘경비대의 일원이 되는데 필요한 충분한 수량의 마법 영약을 마련한 건가요?', `FemaleText_loc4`='那些合剂的数量足够我们加入天空卫队吗？', `FemaleText_loc5`='我們擁有足夠的魔法藥水好加入禦天者了嗎?', `FemaleText_loc7`='¿Hemos cogido suficientes frascos mágicos para entrar en la Guardia del cielo ya?' WHERE `ID`=21407;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하늘경비대는 우리의 도움이 필요해요! 마법 영약을 더 구해야 한다고요.', `MaleText_loc4`='天空卫队需要我们的帮助！我们需要更多不可思议的合剂。', `MaleText_loc5`='禦天者需要我們的幫忙!我們需要取得更多的魔法藥水。', `MaleText_loc7`='¡La Guardia de Cielo necesita nuestra ayuda! Tenemos que obtener más frascos mágicos.', `FemaleText_loc1`='하늘경비대는 우리의 도움이 필요해요! 마법 영약을 더 구해야 한다고요.', `FemaleText_loc4`='天空卫队需要我们的帮助！我们需要更多不可思议的合剂。', `FemaleText_loc5`='禦天者需要我們的幫忙!我們需要取得更多的魔法藥水。', `FemaleText_loc7`='¡La Guardia de Cielo necesita nuestra ayuda! Tenemos que obtener más frascos mágicos.' WHERE `ID`=21408;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 하늘경비대의 일원이 되고 싶어 죽겠다고요. 그저 몇 개의 마법 영약이 필요한 거라고요, 아시죠?', `MaleText_loc4`='我们等不及想加入天空卫队了。我们只是需要更多不可思议的合剂而已，对吗？', `MaleText_loc5`='我們等不及要加入禦天者了。我們只需要再多幾瓶的魔法藥劑，對吧?', `MaleText_loc7`='No podemos esperar a unirnos a la Guardia del cielo. Tan solo necesitamos algunos frascos mágicos más, ¿verdad?', `FemaleText_loc1`='우리 하늘경비대의 일원이 되고 싶어 죽겠다고요. 그저 몇 개의 마법 영약이 필요한 거라고요, 아시죠?', `FemaleText_loc4`='我们等不及想加入天空卫队了。我们只是需要更多不可思议的合剂而已，对吗？', `FemaleText_loc5`='我們等不及要加入禦天者了。我們只需要再多幾瓶的魔法藥劑，對吧?', `FemaleText_loc7`='No podemos esperar a unirnos a la Guardia del cielo. Tan solo necesitamos algunos frascos mágicos más, ¿verdad?' WHERE `ID`=21409;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 순위 경기에 참여할 만큼 강하지 못하군그래. 하지만 투기장 사무관에게 가서 연습 경기에는 참여할 수 있다네. 훈련을 시작하는 건 빠를수록 좋은 거라네.', `MaleText_loc4`='凭你的能力，还不够资格参加晋级赛。不过你可以找竞技场管理员谈一谈，参加一些练习赛。训练永远都不会嫌太晚的。', `MaleText_loc5`='你不行。你還不夠強壯到可以加入積分賽。你還是可以找競技場戰場軍官參加一些練習賽。開始訓練都不會太晚。', `MaleText_loc7`='Tú no. No eres lo suficientemente fuerte para participar en partidas de clasificación. Puedes buscar a un maestro de batalla de arena y practicar. Nunca es demasiado pronto para empezar a entrenar.', `FemaleText_loc1`='자네는 순위 경기에 참여할 만큼 강하지 못하군그래. 하지만 투기장 사무관에게 가서 연습 경기에는 참여할 수 있다네. 훈련을 시작하는 건 빠를수록 좋은 거라네.', `FemaleText_loc4`='凭你的能力，还不够资格参加晋级赛。不过你可以找竞技场管理员谈一谈，参加一些练习赛。训练永远都不会嫌太晚的。', `FemaleText_loc5`='你不行。你還不夠強壯到可以加入積分賽。你還是可以找競技場戰場軍官參加一些練習賽。開始訓練都不會太晚。', `FemaleText_loc7`='Tú no. No eres lo suficientemente fuerte para participar en partidas de clasificación. Puedes buscar a un maestro de batalla de arena y practicar. Nunca es demasiado pronto para empezar a entrenar.' WHERE `ID`=21410;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보세요, 하늘경비대예요!!', `MaleText_loc4`='看，是天空卫队！', `MaleText_loc5`='看那就是禦天者!!', `MaleText_loc7`='¡Mirad, es la Guardia del cielo!', `FemaleText_loc1`='보세요, 하늘경비대예요!!', `FemaleText_loc4`='看，是天空卫队！', `FemaleText_loc5`='看那就是禦天者!!', `FemaleText_loc7`='¡Mirad, es la Guardia del cielo!' WHERE `ID`=21411;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 해치러 온 건가? 난 전쟁과 관련해선 아무것도 한 게 없네.$B$B난 그저 병약한 학자일 뿐이란 말일세. 제발 날 내버려 두게나!', `MaleText_loc4`='你要伤害我吗？我可不想和战争扯上关系，$r。$B$B我只是个体弱多病的学者，请你别来打扰我！', `MaleText_loc5`='你是來傷害我的嗎?我跟戰爭毫無關係，$r。$B$B我只是一個病厭厭的學者，請放過我!', `MaleText_loc7`='¿Has venido a hacerme daño? No tengo nada que ver con la guerra, $r.$B$B¡Solo soy un erudito enfermizo, por favor déjame tranquilo!' WHERE `ID`=21412;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 알은 검은용군단의 알에 걸맞게 탄력 있어 보입니다. 많은 수의 에펙시스 결정을 알 옆에 놓는다면, 결정의 진동으로 이 알이 깨질지도 모르겠습니다.', `MaleText_loc4`='这枚龙卵看上去和正常的黑龙卵一样富有弹性。如果你在它附近放上一些埃匹希斯碎片，它们的震动或许能让龙卵裂开？', `MaleText_loc5`='這顆蛋看起來似乎像黑龍軍團的蛋一樣有彈性。或許如果你放很多頂尖裂片在蛋的周邊的話，裂片本身的震動會使它裂開?', `MaleText_loc7`='El huevo parece fuerte tal y como debería ser un huevo del Vuelo Negro. ¿Quizá si colocaras muchos fragmentos de ápices cerca, sus vibraciones harían que el huevo se rompiera?' WHERE `ID`=21413;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 알은 검은용군단의 알에 걸맞게 탄력 있어 보입니다. 많은 수의 에펙시스 결정을 알 옆에 놓는다면, 결정의 진동으로 이 알이 깨질지도 모르겠습니다.$B$B안타깝게도 이 일을 하는데 필요한 35개의 에펙시스 결정을 지니고 있지 않습니다.', `MaleText_loc4`='这枚龙卵看上去和正常的黑龙卵一样富有弹性。如果你在它附近放上一些埃匹希斯碎片，它们的震动或许能让龙卵裂开？$B$B可惜这样做需要35块埃匹希斯碎片，你身上没有足够的水晶。', `MaleText_loc5`='這顆蛋看起來似乎像黑龍軍團的蛋一樣有彈性。或許如果你放置大量的頂尖裂片在蛋周邊的話，裂片本身的震動會使它裂開?$B$B很遺憾的是你好像沒有進行這項工作所需要的35片裂片可以這麼做。', `MaleText_loc7`='El huevo parece fuerte tal y como debería ser un huevo del Vuelo Negro. ¿Quizá si colocaras muchos fragmentos de ápices cerca, sus vibraciones harían que el huevo se rompiera?$B$BUna lástima que no tengas los 35 fragmentos necesarios para llevar a cabo la tarea.' WHERE `ID`=21414;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용의 알 근처에 35개의 에펙시스 결정을 놓아 알을 깹니다.', `MaleText_loc4`='将35块埃匹希斯碎片放在龙卵附近使其碎裂。', `MaleText_loc5`='放置35個頂尖裂片在龍蛋周圍好讓它裂開', `MaleText_loc7`='Coloca 35 fragmentos de ápices cerca del huevo del dragón para romperlo.', `FemaleText_loc1`='용의 알 근처에 35개의 에펙시스 결정을 놓아 알을 깹니다.', `FemaleText_loc4`='将35块埃匹希斯碎片放在龙卵附近使其碎裂。', `FemaleText_loc5`='放置35個頂尖裂片在龍蛋周圍好讓它裂開', `FemaleText_loc7`='Coloca 35 fragmentos de ápices cerca del huevo del dragón para romperlo.' WHERE `ID`=21415;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<에펙시스 결정을 용의 알 주위의 둥지에 놓자, 수정들이 윙윙거리는 소리를 냅니다. 잠시 시간이 흐르니 울퉁불퉁한 껍질에 생긴 구멍에서 작은 검은 새끼용이 나오더니 아빠를 찾는 소리를 냅니다.>', `MaleText_loc4`='<当你将埃匹希斯碎片放在龙卵附近后，它们发出嗡嗡的蜂鸣声。片刻之后，龙卵粗糙的外壳出现了一道裂缝，一只黑龙幼崽破壳而出，尖叫着呼喊它的母亲。>', `MaleText_loc5`='<當你將頂尖裂片放進巢中圍繞在龍蛋旁邊時，他們開始發出嗡嗡的聲音。幾分鐘後粗糙的蛋殼上出現了一條裂縫，接著一隻黑龍寶寶探出頭來，哭著要它的媽媽。>', `MaleText_loc7`='<Cuando colocas los fragmentos de ápices en el nido del huevo, estos comienzan a zumbar. Unos instantes después aparece una grieta en la áspera cáscara y las crías del Vuelo Negro emergen llamando a su madre.>' WHERE `ID`=21416;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='<당신에게 고개를 돌리기 전에 지옥사냥개와 정답게 소곤거리는 안젤라>$B$B지르시는 항상 다른 지옥사냥개들보다 더 작았지만, 크기는 우리 지르시에겐 아무 걱정거리도 아니지. 그리고 아웃랜드는 그런 모든 걸 바꿔놓을 거야. 그렇지, 우리 지르시야?$B$B이 엄마의 작은 천사는 크고 사나운 사냥개로 자랄 거니까, 그럼 그렇고말고, 우리 예쁜 지르시!', `FemaleText_loc4`='<安吉拉在地狱猎犬耳边低语着什么，直到她留意到你。>$B$B和其它地狱猎犬相比，基尔西的体型显得娇小许多，但是这并未影响到它。我相信外域会改变这一切的，基尔西，对吧？$B$B妈妈的小天使一定会成长为一头巨大凶猛的地狱猎犬！一定！', `FemaleText_loc5`='<安琪拉在注意你之前再度對惡魔獵犬低聲的說話。>$B$B澤西永遠都比其他的惡魔獵犬來得小號，不過卻從來不會困擾他。而外域將會改變一切，對吧澤西?$B$B媽咪的小天使將要長大成為一隻巨大，殘爆的惡魔獵犬，沒錯，他就是!', `FemaleText_loc7`='<Angela arrulla de nuevo al manáfago antes de dirigirse a ti.>$B$BJir''ve siempre ha sido más pequeño que los otros manáfagos, pero eso nunca le ha preocupado. Y Terrallende va a cambiar eso, ¿verdad Jir''ve?$B$BEl angelito de mamá va a crecer para convertirse en un manáfago grande y fiero. ¡Eso es!' WHERE `ID`=21417;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 트로프가 용아귀 부족원처럼 날 수 있는 법을 보여주도록 하지요... 그리고 당신은 쓸모없는 친구가 어떻게 죽게 되는지 이 트로프에게 보여줄 것이고 말이죠.', `MaleText_loc4`='特罗普会让你见识到龙喉兽人飞翔的英姿……而你就让特罗普看看没用的渣滓是怎么死的吧。', `MaleText_loc5`='川普將會讓你見識如何像龍喉一樣的飛翔...而你將會讓川普看看如何死得像個廢物。', `MaleText_loc7`='Trope te enseñará a volar como un Faucedraco... Tu le enseñarás a Trope a morir como un desgraciado.' WHERE `ID`=21418;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘했습니다. 분명히 이 트로프에겐 놀랄 일이군요... 가서 제이에게 보고하도록 하세요.', `MaleText_loc4`='你干得不错。让特罗普吃了一惊……向亚恩报告吧。', `MaleText_loc5`='你做得很好。一定會讓川普感到意外...回報給傑。', `MaleText_loc7`='Lo has hecho bien. Una auténtica sorpresa para Trope... Vuelve a informar a Ja’y.' WHERE `ID`=21419;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 엄마를 찾으며 울부짖습니다.', `MaleText_loc4`='%s尖叫着呼唤它的母亲。', `MaleText_loc5`='%s放聲大哭著要找它的媽媽。', `MaleText_loc7`='El %s grita llamando a su madre.' WHERE `ID`=21420;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 어서 끝마치도록 하지...', `MaleText_loc4`='让我们搞定这里的事情吧……', `MaleText_loc5`='讓我們快點結束吧。', `MaleText_loc7`='Acabemos con esto...' WHERE `ID`=21421;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 풋내기 친구. 굉장한 비행이었어. 정말 굉장했다고...', `MaleText_loc4`='菜鸟，你打得真烂。真是烂到渣了……', `MaleText_loc5`='你製造了一場戰鬥煉獄，菜鳥。戰鬥的煉獄...', `MaleText_loc7`='Has organizado una gran pelea, novato. Una gran pelea...' WHERE `ID`=21422;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번 경주는 옛날 방식으로 하도록 하지. 난 얼라이언스가 되고 당신은 서리늑대가 되는 것이오. 이거 신나는군!', `MaleText_loc4`='这让我回忆起了过去的时光。我扮演联盟，你则防守霜狼村。投弹完毕！', `MaleText_loc5`='我將會把狀態回復舊樣。我將會是聯盟，而你屬於霜狼村。把炸彈拿開!', `MaleText_loc7`='Lo haré como en la vieja escuela. Yo seré la Alianza y tú serás la Aldea Lobo gélido. ¡BOMBAS FUERA!' WHERE `ID`=21423;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙소... 이런 비행을 하다니 이거 면목이 없군.', `MaleText_loc4`='感谢你……这可真令我感到羞耻。', `MaleText_loc5`='謝謝你那麼做...被用如此的方法對待真是謙卑。', `MaleText_loc7`='Gracias por eso... Ha sido humillante ser servido de esa forma.' WHERE `ID`=21424;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 곤란한 상황에 부닥친 거라고, $n. 이미 장례 준비를 마쳤길 바라오.', `MaleText_loc4`='这趟飞行之旅可能不太安全，$n。希望你已经安排好了后事。', `MaleText_loc5`='你正處於一次狂暴的航行中，$n。我希望你已經準備好身後事的安排了。', `MaleText_loc7`='Te espera un viaje duro, $n. Espero que hayas hecho los trámites funerarios.' WHERE `ID`=21425;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 본 중에 당신이 최고로군. 내가 이런 말을 하다니 믿을 순 없지만 이제 스카이쉐터 대장과 겨룰 기회가 있을 거요. 아, 그렇지... 썩 잘 되지 못해도 내 편대 조종사가 될 수 있을 거요...', `MaleText_loc4`='你是我见过的最棒的飞行员。真不敢相信我竟然说出这样的话，但是你很可能和汤告鲁士·碎空不相上下哦。还有，要是刚才的进展不是特别顺利的话，你就是我的飞行员了……', `MaleText_loc5`='你是我見過最棒的人了。我無法相信我這麼說，不過你也許有機會對抗碎天者。還有嘿，要是那進行的不是那麼順利，你可以當我的飛行員...', `MaleText_loc7`='Eres el mejor que jamás he visto. No puedo creer que esté diciendo esto, pero puede que tengas alguna posibilidad contra el Devastador del Cielo. Y oye, si eso no sale bien puedes ser mi ayudante...' WHERE `ID`=21426;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 아빠를 찾으며 울어댑니다.', `MaleText_loc4`='%s尖叫着呼唤它的父亲。', `MaleText_loc5`='%s放聲大哭著要找爸爸。', `MaleText_loc7`='El %s grita llamando a su padre.' WHERE `ID`=21427;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<에펙시스 결정을 용의 알 주위의 둥지에 놓자, 수정들이 윙윙거리는 소리를 냅니다. 잠시 시간이 흐르니 울퉁불퉁한 껍질에 생긴 구멍에서 작은 검은 새끼용이 나오더니 아빠를 찾는 소리를 냅니다.>', `MaleText_loc4`='<当你将埃匹希斯碎片放在龙卵附近后，它们发出嗡嗡的蜂鸣声。片刻之后，龙卵粗糙的外壳出现了一道裂缝，一只黑龙幼崽破壳而出，尖叫着呼喊它的父亲。>', `MaleText_loc5`='<當你將頂尖裂片放進巢中圍繞在龍蛋旁邊時，他們開始發出嗡嗡的聲音。幾分鐘後粗糙的蛋殼上出現了一條裂縫，接著一隻黑龍寶寶探出頭來，哭著要它的爸爸。>', `MaleText_loc7`='<Cuando colocas los fragmentos de ápices en el nido del huevo, estos comienzan a zumbar. Unos instantes después aparece una grieta en la áspera cáscara y las crías del Vuelo Negro emergen llamando a su madre.>' WHERE `ID`=21428;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멀베릭!', `MaleText_loc4`='穆维里克！！！', `MaleText_loc5`='穆維里克!', `MaleText_loc7`='¡MULVERICK!' WHERE `ID`=21429;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='화장용 장작더미를 준비해라! $n|1이;가; 이 스카이쉐터 님께 도전을 했구나!', `MaleText_loc4`='准备好葬礼的火堆！$n向汤告鲁士·碎空发起挑战了！', `MaleText_loc5`='準備好火葬堆!$n要挑戰碎天者了!', `MaleText_loc7`='¡Preparad una pira funeraria! ¡$n ha retado a Devastador del Cielo!' WHERE `ID`=21430;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 이런... 실패로군... 새로운 최고의 오크는 $n|1이;가; 되었다!', `MaleText_loc4`='我……我败了……$n才是最优秀的兽人！', `MaleText_loc5`='我...我失敗了...新任最優秀的獸人是$n!', `MaleText_loc7`='Yo... estoy desecho... ¡El nuevo orco del momento es $n!' WHERE `ID`=21431;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='눈물이 다 나는군, $n. 정말 당신이 얼마나 큰 곤경에 빠졌는지 모를 것이야...', `MaleText_loc4`='我为你悲叹，$n。你根本不明白自己陷入了怎样的窘境……', `MaleText_loc5`='我為你感覺難過，$n。你真的不了解你陷入的是什麼情況...', `MaleText_loc7`='Lloro por ti, $n. No tienes ni idea de lo que se te viene encima...' WHERE `ID`=21432;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세나리온 원정대는 저곳에서 목숨을 잃어가는 날 구해주었답니다. 그들에게 내 생명을 빚진 것이지요! 그래서 전 세나리온 원정대의 친구들에게 마법 용품을 지원하고 수리를 해 드리고 있습니다.', `MaleText_loc4`='要不是塞纳里奥远征队，我肯定早就葬身矿洞了……是他们救了我的命！因此，我为塞纳里奥远征队的盟友们提供修理装备以及出售施法材料的服务。', `MaleText_loc5`='塞納里奧遠征隊將我從礦坑內必死的狀況中拯救出來。我欠他們一條命!我為那些塞納里奧遠征隊的同伴提供修理及藥劑販售的服務。', `MaleText_loc7`='La Expedición Cenarion me salvo de una muerte segura dentro de las minas. ¡Les debo mi vida! Ofrezco mis servicios de reparación y venta de reactivos a todos los aliados de la Expedición Cenarion.' WHERE `ID`=21433;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모르토그, 저는 세나리온 원정대의 동지입니다. 보유한 물건을 보여주십시오.', `MaleText_loc4`='我是塞纳里奥远征队的盟友，莫尔托格。让我看看你出售的货物。', `MaleText_loc5`='我是塞納里奧遠征隊的同伴，莫塔格。讓我看看你的貨品。', `MaleText_loc7`='Soy aliado de la Expedición Cenarion, Mortog. Enséñame tus mercancías.', `FemaleText_loc1`='모르토그, 저는 세나리온 원정대의 동지입니다. 보유한 물건을 보여주세요.', `FemaleText_loc4`='我是塞纳里奥远征队的盟友，莫尔托格。让我看看你出售的货物。', `FemaleText_loc5`='我是塞納里奧遠征隊的同伴，莫塔格。讓我看看你的貨品。', `FemaleText_loc7`='Soy aliado de la Expedición Cenarion, Mortog. Enséñame tus mercancías.' WHERE `ID`=21434;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호적수와 싸워본 지도 꽤 오랜 시간이 흘렀군...', `MaleText_loc4`='我很久没有遇到过旗鼓相当的对手了……', `MaleText_loc5`='自從我上一次與匹配的敵人戰鬥至今已經有一陣子了...', `MaleText_loc7`='Ha pasado mucho tiempo desde que luché contra un adversario digno...' WHERE `ID`=21435;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 진정한 힘이 무엇인지 보게 될 것이다!', `MaleText_loc4`='现在，我就让你见识真正的力量！', `MaleText_loc5`='現在你將見證到真正力量的意義!', `MaleText_loc7`='¡Ahora serás testigo de lo que significa el verdadero poder!' WHERE `ID`=21436;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해냈군! 적들을 물리쳤어! 모두 기지로 귀환하라!', `MaleText_loc4`='他们成功了！敌人已被击溃！返回基地！', `MaleText_loc5`='他們做到了!敵人倒下了!回到基地!', `MaleText_loc7`='¡Lo han logrado! ¡Enemigo derribado! ¡Volved a base!', `FemaleText_loc1`='해냈군! 적들을 물리쳤어! 모두 기지로 귀환하라!', `FemaleText_loc4`='他们成功了！敌人已被击溃！返回基地！', `FemaleText_loc5`='他們做到了!敵人倒下了!回到基地!', `FemaleText_loc7`='¡Lo han logrado! ¡Enemigo derribado! ¡Volved a base!' WHERE `ID`=21437;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='임무 중단! 우리의 지상군이 패배했다!', `MaleText_loc4`='放弃任务！我们的地面部队已经落败。', `MaleText_loc5`='任務失敗!我們的地面軍隊被打敗了。', `MaleText_loc7`='¡Aborten misión! Nuestras fuerzas terrestres han sido derrotadas.', `FemaleText_loc1`='임무 중단! 우리의 지상군이 패배했다!', `FemaleText_loc4`='放弃任务！我们的地面部队已经落败。', `FemaleText_loc5`='任務失敗!我們的地面軍隊被打敗了。', `FemaleText_loc7`='¡Aborten misión! Nuestras fuerzas terrestres han sido derrotadas.' WHERE `ID`=21438;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적이 포착되었다! 대형을 갖추고 폭격 준비를 하라!', `MaleText_loc4`='发现敌人！改变阵型，准备轰炸！', `MaleText_loc5`='瞄準敵人!排列隊形並準備轟炸行動!', `MaleText_loc7`='¡Enemigo avistado! ¡En formación y preparaos para las maniobras de bombardeo!', `FemaleText_loc1`='적이 포착되었다! 대형을 갖추고 폭격 준비를 하라!', `FemaleText_loc4`='发现敌人！改变阵型，准备轰炸！', `FemaleText_loc5`='瞄準敵人!排列隊形並準備轟炸行動!', `FemaleText_loc7`='¡Enemigo avistado! ¡En formación y preparaos para las maniobras de bombardeo!' WHERE `ID`=21439;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에서 당신이 할 일이 아주 많을 것이오, $n.', `MaleText_loc4`='你在这里可以找到很多事情做，$n。', `MaleText_loc5`='你在這會找到很多事可以做，$n。', `MaleText_loc7`='Aquí encontrarás mucho que hacer, $n.' WHERE `ID`=21440;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투 태세를 갖춰라! 공격에 대비하라!', `MaleText_loc4`='战斗姿态！准备发动冲锋！', `MaleText_loc5`='戰鬥姿態!準備好防禦攻擊!', `MaleText_loc7`='¡Actitud de batalla! ¡Preparaos para una oleada ofensiva!' WHERE `ID`=21441;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어이쿠, 당신 요즘 바쁘지 않소? 악마들의 포탄 더미를 없애고 새로운 탈것을 보충해 준 점에 대해서 뭐라고 감사해야 할지 모르겠다오.$B$B당신이 우리 일을 무척 쉽게 풀어주고 있다오. 계속 잘해주시기 바라오, 친구!', `MaleText_loc4`='嗨，你最近挺忙的是吧？！你不仅帮助我们轰炸恶魔，还替我们捕捉虚空鳐，我都不知道该怎么感谢你。$B$B你让我们的工作轻松了许多。继续保持下去吧！', `MaleText_loc5`='啊，你現在在忙對吧?!我不知道要怎麼感激你轟炸那些惡魔還有幫我們補充坐騎才好。$B$B你讓我們所有的工作更加便利了。保持良好的工作，$g小夥子:少女;!', `MaleText_loc7`='Ack, has estado $gocupado:ocupada;, ¿verdad? No puedo agradecerte lo suficiente que hayas bombardeado a los demonios y que nos hayas reabastecido de monturas.$B$BEstás haciendo que nuestro trabajo sea más fácil. ¡Sigue así $gchico:chica;!' WHERE `ID`=21442;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='광폭 태세를 갖춰라! 저들을 무자비하게 공격하라!', `MaleText_loc4`='狂暴姿态！无情地攻击他们！', `MaleText_loc5`='狂暴姿態!不顧一切的攻擊他們!', `MaleText_loc7`='¡Actitud rabiosa! ¡Atacadles indiscretamente!' WHERE `ID`=21443;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방어 태세를 갖춰라! 저들의 공세를 방어하고 되받아쳐줘라!', `MaleText_loc4`='防御姿态！用盾牌挡住攻击，然后迅速反击！', `MaleText_loc5`='防禦姿態!保護自己免於他們的打擊並反擊回去!', `MaleText_loc7`='¡Actitud defensiva! ¡Protegeos de sus golpes y volved a atacar!' WHERE `ID`=21444;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 영약이 준비되었으니, 하늘경비대에 우리의 솜씨를 보여줄 수 있겠어요!', `MaleText_loc4`='合剂都准备妥当了，我们要让天空卫队看看我们的决心。', `MaleText_loc5`='現在藥水已經準備好了，我們可以讓禦天者知道我們的請求了!', `MaleText_loc7`='Ahora que los frascos están listos podemos enseñar nuestros movimientos a la Guardia del cielo.' WHERE `ID`=21445;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하늘경비대 친구들, 긴장하라고! 여기 토르커스 2세가 간다!', `MaleText_loc4`='天空卫士，当心！托尔库斯二世来了！', `MaleText_loc5`='禦天者，小心。小托卡司來了!', `MaleText_loc7`='Atenta, Guardia del cielo. ¡Aquí llega Torkus Jr.!' WHERE `ID`=21446;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사령관님! 생도 토르커스 2세가 임무를 보고하러 왔습니다!', `MaleText_loc4`='指挥官阁下！托尔库斯二世向你报告！', `MaleText_loc5`='指揮官，長官!見習生小托卡司報到，長官!', `MaleText_loc7`='¡Comandante, señor! ¡Cadete Torkus Jr. listo para el servicio, señor!' WHERE `ID`=21447;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='허허, 이보시오. 당신의 열의는 높게 사겠으나 이거 원... 어떻게 말해야 할지 모르겠군... 당신은 오우거지 않소.', `MaleText_loc4`='听我说。我钦佩你做出的贡献，但我不知道该怎么说……你，你是个食人魔，孩子。', `MaleText_loc5`='看這裡，小夥子。我欣賞你的奉獻，不過我不確定要不要告訴你這件事...你是個巨魔，孩子。', `MaleText_loc7`='Mira chico, admiro tu dedicación pero no se cómo decirte esto... Hijo, eres un ogro.' WHERE `ID`=21448;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇습니다, 사령관님. 전 오우거입니다만 한번 기회를 주세요! 하늘경비대가 오그릴라로 날아들어온 그 첫 순간부터 준비해 왔단 말입니다!', `MaleText_loc4`='是，长官。我是食人魔，但是请您给我们一个机会吧！自从我们第一次看见天空卫队在奥格瑞拉上空飞翔，就憧憬着这一刻的到来！', `MaleText_loc5`='是，長官。一個巨魔，長官。但是請給我一個機會，長官!我們從第一次禦天者飛越過歐格利拉就開始為此準備了，長官!', `MaleText_loc7`='Sí, señor. Un ogro, señor. ¿Pero dénos una oportunidad, señor! ¡Hemos estado preparándonos para esto desde la primera vez que la Guardia del cielo sobrevoló Ogri''la, señor!' WHERE `ID`=21449;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 받아들일 수 없다는 태도를 보이더니 이륙장으로 향합니다.', `MaleText_loc4`='%s做了个解散的手势，然后走向发射台。', `MaleText_loc5`='%s做了個解散的手勢就轉向起飛坪。', `MaleText_loc7`='%s hace un gesto de desestimación y se dirige a la plataforma de lanzamiento.' WHERE `ID`=21450;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 오우거의 생각을 알아차린 듯 두려움에 몸을 움츠립니다.', `MaleText_loc4`='当%s意识到食人魔在想什么时，它畏缩了。', `MaleText_loc5`='%s在它知道巨魔心裡在想些什麼後就因害怕而畏縮著。', `MaleText_loc7`='%s se encoge aterrorizado al darse cuenta de lo que está pensando el ogro.' WHERE `ID`=21451;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='반드시 이 광산을 다시 우리 소유로 만들어야 합니다!', `FemaleText_loc4`='我们必须在矿洞附近重建我们的要塞！', `FemaleText_loc5`='我們一定要在這些礦坑上重建我們的控制權!', `FemaleText_loc7`='¡Debemos restaurar nuestro poder en estas minas!' WHERE `ID`=21452;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<수렁피 감독관이 투덜거립니다.>', `MaleText_loc4`='<暗血监工咕哝着。>', `MaleText_loc5`='<黑暗之血監督者咕噥著。>', `MaleText_loc7`='<El sobrestante Sangreoscura gruñe.>' WHERE `ID`=21453;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들이 날 없애라고 당신을 보낸 거로군요? 예상했던 일이지요... 공포를 권력의 무기로 삼는 생물들은 모두 똑같으니까요.$B$B그런데 당신은... 저들의 일원이 아니지 않습니까?', `MaleText_loc4`='他们派你来杀我的吧，嗯？我早就猜到了……被恐怖支配的生物都一样。$B$B不过你……你和他们不一样……', `MaleText_loc5`='他們派你過來殺了我，是嗎?真是預料中...被恐怖所統治的生物都一樣。$B$B不過你...你不是他們其中一員...', `MaleText_loc7`='Te han enviado para matarme, ¿eh? Tan predecibles... Las criaturas dominadas por el terror son todas iguales. $B$BPero tú... tú no eres una de ellas...' WHERE `ID`=21454;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감독관, 당신을 만나러 왔습니다.', `MaleText_loc4`='我是为你而来的，监工。', `MaleText_loc5`='我是為了你到這裡來的，監督者。', `MaleText_loc7`='Estoy aquí para ti, sobrestante.', `FemaleText_loc1`='감독관, 당신을 만나러 왔습니다.', `FemaleText_loc4`='我是为你而来的，监工。', `FemaleText_loc5`='我是為了你到這裡來的，監督者。', `FemaleText_loc7`='Estoy aquí para ti, sobrestante.' WHERE `ID`=21455;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 용아귀 부족의 감독관에게 그런 질문을 하다니요!', `MaleText_loc4`='你竟敢质问一个龙喉督工！', `MaleText_loc5`='你竟敢質疑一位龍喉的監督者!', `MaleText_loc7`='¡Cómo te atreves a cuestionar a un sobrestante de los Faucedraco!', `FemaleText_loc1`='감히 용아귀 부족의 감독관에게 그런 질문을 하다니요!', `FemaleText_loc4`='你竟敢质问一个龙喉督工！', `FemaleText_loc5`='你竟敢質疑一位龍喉的監督者!', `FemaleText_loc7`='¡Cómo te atreves a cuestionar a un sobrestante de los Faucedraco!' WHERE `ID`=21456;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감독관이라고요?$B$B당신이 감독관이라면 난 스톰윈드의 왕이겠군. 아, 그렇군... 당신이 저들이 말하는 자였군요.', `MaleText_loc4`='督工？$B$B你不是龙喉督工，正如我不是暴风城的国王一样。对……你就是他们提起的那个家伙。', `MaleText_loc5`='監督者?$B$B要是你是個監督者，那我就是暴風之王了。沒錯...你就是他們口中的那個人。', `MaleText_loc7`='¿Sobrestante?$B$BNo eres más que un sobrestante y yo soy el rey de Ventormenta. Sí... es de ti de quien hablan.' WHERE `ID`=21457;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황천의 용군단말입니다. 우리와 그들이 나눈 밀담에서 그들은 평화를 유지하고 후원을 해 주겠다는 제안을 했습니다. 뒤틀린 드레나이는 진정 느껴보지 못한 그런 평화 말이지요. 그래서 우린 그들의 제안을 받아들였고 많은 인명을 희생하여 토라나쿠가 이 광산의 생물들을 날뛰게 하는 일을 도왔던 것입니다. 내 형제들 중 다수는 이 계획을 위해 자신의 생명을 바쳤지요. 우린 용아귀 부족을 강제로 이주시키면서 궁극적으로는 이 섬에서 떠나도록 하려고 이 광산을 폐광으로 만들고자 했던 것입니다.', `MaleText_loc4`='灵翼龙族。他们说愿意保护破碎者氏族，让我们享受未曾体验过安宁与和平。我们决定接受龙族的恩惠，帮助托兰纳古唤醒了那些居住在矿洞中的生物，并为此付出了巨大的代价。在这场骚乱中，很多兄弟不幸遇难。我们计划让矿洞变成不适合居住的废墟，以此迫使龙喉兽人离开这座岛屿。', `MaleText_loc5`='虛空之翼。他們跟我們溝通。他們提供我們安詳以及保護。有些事失落者永遠無法感覺。我們接受他們的提議，並協助托拉納庫讓這個礦坑的生物覺醒 - 花了我們很大的心力。我的許多兄弟為此奉獻了他們的生命。我們試著要將這個礦坑弄得不適合居住，迫使龍喉重新尋找居所，最後離開這個島嶼。', `MaleText_loc7`='Los Ala Abisal. Nos hablan. Nos han ofrecido paz y protección. Algo que los Tábidos nunca han sentido. Aceptamos su oferta y ayudamos a Toranaku a hacer salir a las criaturas de esta mina, con un gran coste personal para nosotros. Muchos de mis hermanos dieron sus vidas por esta ofensiva. Estábamos intentado hacer de esta mina un lugar inhabitable, forzando a los Faucedraco a cambiar de hogar y finalmente a mudarse.' WHERE `ID`=21458;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 나에 대해서 얘기하는 거죠? 뒤틀린 드레나이여, 무슨 얘기를 하는 겁니까?', `MaleText_loc4`='谁提到了我？你在说什么，破碎者？', `MaleText_loc5`='誰提到我?你在說些什麼，失落者?', `MaleText_loc7`='¿Quién habla de mí? ¿De qué hablas, Tábido?', `FemaleText_loc1`='누가 나에 대해서 얘기하는 거죠? 뒤틀린 드레나이여, 무슨 얘기를 하는 겁니까?', `FemaleText_loc4`='谁提到了我？你在说什么，破碎者？', `FemaleText_loc5`='誰提到我?你在說些什麼，失落者?', `FemaleText_loc7`='¿Quién habla de mí? ¿De qué hablas, Tábido?' WHERE `ID`=21459;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 얘기하십시오.', `MaleText_loc4`='请继续说。', `MaleText_loc5`='請繼續。', `MaleText_loc7`='Continúa, por favor.', `FemaleText_loc1`='계속 얘기하십시오.', `FemaleText_loc4`='请继续说。', `FemaleText_loc5`='請繼續。', `FemaleText_loc7`='Continúa, por favor.' WHERE `ID`=21460;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용아귀 부족은 타락했습니다. 그들은 이 섬의 모든 천연자원을 깡그리 캐내어 검은 사원의 밖에 있는 일리단의 군대를 지원하는데 사용하고 있지요. 그렇게 자신들을 위해 너무도 애를 쓰고 있음에도, 몰래 숨겨둔 것들을 최고 값을 부르는 자들에게 팔아버리고 있는 것입니다.', `MaleText_loc4`='龙喉氏族已经堕落了。他们在岛上疯狂地开采天然资源，并利用这些资源支援伊利丹派驻在黑暗神殿外的军队。当然，他们将大部分资源据为己有，而且把私藏的资源出售给出价最高的人。', `MaleText_loc5`='龍喉墮落了。他們在露天開採這個島嶼的所有自然資源，並用那些資源來提供伊利丹在黑暗神廟之外的軍隊。不過，他們本身拿了不少，並把那些他們私藏的東西賣給出價最高的買家。', `MaleText_loc7`='Los Faucedraco están corruptos. Están despojando a esta isla de sus recursos naturales y usando esos recursos para abastecer a las armadas de Illidan en su salida del Templo Oscuro. De todos modos, esconden gran parte de esos recursos y se los venden al mejor postor.' WHERE `ID`=21461;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 최고 입찰자들은 누구인가요?', `MaleText_loc4`='这些出价者是谁？', `MaleText_loc5`='這些買家有誰?', `MaleText_loc7`='¿Quiénes son estos postores?', `FemaleText_loc1`='그 최고 입찰자들은 누구인가요?', `FemaleText_loc4`='这些出价者是谁？', `FemaleText_loc5`='這些買家有誰?', `FemaleText_loc7`='¿Quiénes son estos postores?' WHERE `ID`=21462;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그건 우리도 모릅니다. 검은용군단이 제3의 독립 세력과 연루되어 있다고 믿습니다. $r, 그것이 당신이 이곳에 온 이유이지요. 당신이 내부에서 이 수수께끼를 풀어내어 황천의 용군단에 구원을 가져다줄 것입니다.$B$B자... 여군주가 내 장갑을 가져오라고 했겠지요?', `MaleText_loc4`='我们不知道。但我们相信黑龙一族以独立的第三方身份参与了此事。这就是你来这里的目标，$r。你要抽丝剥茧般地揭开这个秘密，让灵翼龙族重获自由。$B$B那么……我想矿洞女王要求你带回我的手吧。', `MaleText_loc5`='我們不知道。我們相信黑龍軍團有介入某些獨力的第三者當中。那就是你為什麼在這的原因，$r。你將會從中解開這個謎團並以此回報虛空之翼。$B$B現在...我只想得到她會要你帶回我的手。', `MaleText_loc7`='No sabemos. Creemos que el Vuelo Negro está implicado, al igual que algunas terceras partes independientes. Por eso estás aquí, $r. Desvelarás este misterio desde el interior y traerás la redención a los Ala Abisal.$B$BY ahora... Solo puedo suponer que te ha encargado que me traigas mi mano.' WHERE `ID`=21463;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음... 그렇습니다.', `MaleText_loc4`='呃……是的。', `MaleText_loc5`='好的...是。', `MaleText_loc7`='Bueno...sí.', `FemaleText_loc1`='음... 그렇습니다.', `FemaleText_loc4`='呃……是的。', `FemaleText_loc5`='好的...是。', `FemaleText_loc7`='Bueno...sí.' WHERE `ID`=21464;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 희생이 용아귀 부족의 몰락을 가져다준다면 기쁘게 받아들이도록 하지요.', `MaleText_loc4`='如果它能换来龙喉氏族的衰落，我很乐意做出这样的牺牲。', `MaleText_loc5`='要是這能表示龍喉的落敗的話，我很高興做出這樣的犧牲。', `MaleText_loc7`='Realizaré ese sacrificio con gusto, si eso significa la caída de los Faucedraco.' WHERE `ID`=21465;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크아악! 내가 쓰러지면 네놈을 길동무로 데려가리라!', `MaleText_loc4`='啊！如果我必须死，我会与你同归于尽！', `MaleText_loc5`='啊!如果我一定要死，我會帶著你跟我一起死!', `MaleText_loc7`='¡Aargh! ¡Si caigo, te arrastraré conmigo!' WHERE `ID`=21466;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니, 이보게, 브론코는 안 돼! 아직 길이 덜 들었다고! 올라탔다간 자네까지 죽을걸!', `MaleText_loc4`='嗨，伙计！别挑布隆库！他还没有被驯服！你骑上去的话很可能会没命的！', `MaleText_loc5`='不，小子，不是布朗可!他已經不是失落者了!你去那裡等於是去送死!', `MaleText_loc7`='¡No chico, Bronco no! ¡Aún no está domado! ¡Conseguirás que te mate allí arriba!' WHERE `ID`=21467;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='브론코가 %s의 뒤에서 뛰쳐 나와 멀리 도망갑니다!', `MaleText_loc4`='布隆库猛然一跃，将%s摔了下来，然后逃进了荒野中！', `MaleText_loc5`='布朗可從 %s背後衝撞過去並逃進荒地裡!', `MaleText_loc7`='¡Bronco tira a %s de su espalda y escapa hacia el bosque!' WHERE `ID`=21468;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공포아귀, 나오너라! 침입자 녀석아, 비싼 대가를 치르게 해 주마.', `MaleText_loc4`='恐惧之喉！你会付出昂贵的代价，入侵者……', `MaleText_loc5`='巨齒!你將付出極大的代價，入侵者...', `MaleText_loc7`='¡Fauzatroz! Pagarás con creces, intruso...' WHERE `ID`=21469;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 즉시 이곳을 떠나야 한다!', `MaleText_loc4`='我必须马上离开这个地方！', `MaleText_loc5`='我一定要馬上離開這個地方!', `MaleText_loc7`='¡Debo marcharme de aquí de una vez!' WHERE `ID`=21470;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 가자!', `MaleText_loc4`='[DEBUG] THEN LET''S GO!', `MaleText_loc5`='[DEBUG]那麼我們走吧!', `MaleText_loc7`='[DEBUG] ¡ENTONCES VAMOS!', `FemaleText_loc1`='그럼 가자!', `FemaleText_loc4`='[DEBUG] THEN LET''S GO!', `FemaleText_loc5`='[DEBUG]那麼我們走吧!', `FemaleText_loc7`='[DEBUG] ¡ENTONCES VAMOS!' WHERE `ID`=21471;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='브론코라고? 저 가오리가 좋겠어!', `MaleText_loc4`='布隆库？听上去不错！', `MaleText_loc5`='布朗可?聽起來像是個好人!', `MaleText_loc7`='¿Bronco? ¡Ese suena bien!' WHERE `ID`=21472;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 말을 안 듣는군. 황천의 가오리가 태울 수 있는 건...', `MaleText_loc4`='我觉得你没把我的话听进去。虚空鳐并不是最理想的——', `MaleText_loc5`='我不覺得你在聽我說話。虛空鰭刺不是用來 -', `MaleText_loc7`='Creo que no me estás oyendo. Las rayas abisales no están hechas para --' WHERE `ID`=21473;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에펙시스 유물이 희미하게 빛나며 내부에 숨겨진 지혜를 드러내 보입니다.', `MaleText_loc4`='埃匹希斯圣物闪着微光，似乎里面隐藏着什么东西。', `MaleText_loc5`='頂尖聖物發出微光，透露出內含的一股隱藏的智慧。', `MaleText_loc7`='La reliquia de ápices brilla, revelando la inteligencia oculta en su interior.' WHERE `ID`=21474;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에펙시스 결정을 넣고 유물을 조종합니다!', `MaleText_loc4`='插入1块埃匹希斯碎片，然后开始！', `MaleText_loc5`='插入一個頂尖裂片，然後開始!', `MaleText_loc7`='¡Inserta un fragmento de ápices y comienza!', `FemaleText_loc1`='에펙시스 결정을 넣고 유물을 조종합니다!', `FemaleText_loc4`='插入1块埃匹希斯碎片，然后开始！', `FemaleText_loc5`='插入一個頂尖裂片，然後開始!', `FemaleText_loc7`='¡Inserta un fragmento de ápices y comienza!' WHERE `ID`=21475;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌아와, 브론코! 우린 함께 하늘경비대가 되어야 해!', `MaleText_loc4`='回来吧，布隆库先生！让我们一起加入天空卫队！', `MaleText_loc5`='回來，布朗可先生!我們想要跟禦天者在一起!', `MaleText_loc7`='¡Vuelve, Sr. Bronco! Estaremos juntos en la Guardia del cielo.' WHERE `ID`=21476;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='머리 위로 에펙시스 유적이 나타납니다.', `MaleText_loc4`='你隐约看见了前方的埃匹希斯纪念碑。', `MaleText_loc5`='頂尖紀念碑隱約出現在你上方。', `MaleText_loc7`='El monumento de ápices amenaza desde arriba.' WHERE `ID`=21477;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='35개의 에펙시스 결정을 넣은 후, 시작합니다!', `MaleText_loc4`='插入35块埃匹希斯碎片，然后开始！', `MaleText_loc5`='插入35個頂尖裂片，然後開始!', `MaleText_loc7`='¡Inserta 35 fragmentos de ápices y comienza!', `FemaleText_loc1`='35개의 에펙시스 결정을 넣은 후, 시작합니다!', `FemaleText_loc4`='插入35块埃匹希斯碎片，然后开始！', `FemaleText_loc5`='插入35個頂尖裂片，然後開始!', `FemaleText_loc7`='¡Inserta 35 fragmentos de ápices y comienza!' WHERE `ID`=21478;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영약을 준비해주셔서 고맙습니다.', `MaleText_loc4`='感谢你为我们提供了合剂。', `MaleText_loc5`='謝謝你協助我們有關藥水的事。', `MaleText_loc7`='Gracias por ayudarnos con los frascos.' WHERE `ID`=21479;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방해하지 마라! 참을성 따위는 없다!', `MaleText_loc4`='别打扰我！绝对不能出现任何偏差！', `MaleText_loc5`='不準打擾!沒有耐性!', `MaleText_loc7`='¡Nada de molestias! ¡Tolerancia cero!' WHERE `ID`=21480;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와주셔서 감사합니다. 어서 여기를 빠져나갑시다!', `MaleText_loc4`='谢谢你。我们离开这里吧！', `MaleText_loc5`='謝謝你的幫忙。我們離開這裡吧!', `MaleText_loc7`='Gracias por tu ayuda. ¡Vayámonos de aquí!' WHERE `ID`=21481;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 쉭쉭 소리를 내며 토르커스 2세를 위협합니다.', `MaleText_loc4`='%s朝托尔库斯二世发出嘶嘶的叫声。', `MaleText_loc5`='%s對小托卡司發出很吵鬧的噓聲。', `MaleText_loc7`='%s le sisea a Torkus Jr. en alto.' WHERE `ID`=21482;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정신 바짝 차리게, 대장!', `MaleText_loc4`='立正，队长！', `MaleText_loc5`='立正，上尉!', `MaleText_loc7`='¡Firme, Capitán!' WHERE `ID`=21483;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 가도록 합시다. 이곳을 벗어나고 싶군요.', `MaleText_loc4`='继续前进。我不喜欢这个地方。', `MaleText_loc5`='我們繼續前進。我不喜歡這個地方。', `MaleText_loc7`='Sigamos moviéndonos. No me gusta este lugar.' WHERE `ID`=21484;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 한번 감사 드립니다. 하늘경비대 하사관 도린이 이번 주 충원할 정찰병이 하나 줄어들었다는 걸 알면 기뻐하겠군요.', `MaleText_loc4`='再次谢谢你。如果杜尔因上尉得知本周能少替换一名斥候的话，他肯定会很高兴的。', `MaleText_loc5`='再次謝謝你。士官多林將會很高興聽到這星期會有一位斥候可以替換。', `MaleText_loc7`='Gracias de nuevo. El sargento Doryn se alegrará de oír que tiene un explorador menos que remplazar esta semana.' WHERE `ID`=21485;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='프리즘 내에 불타는 눈들이 당신의 마음을 불안함으로 뒤덮고 있습니다... 이 프리즘의 악마를 소환할 수 있는 35개의 에펙시스 결정이 충분치 않다는 사실을 알고 나니 불안한 마음이 특히나 더 가득해집니다.', `MaleText_loc4`='棱柱中燃烧的眼睛让你感到恐怖……召唤它需要35块埃匹希斯碎片，而你身上没有足够的水晶。', `MaleText_loc5`='燒毀在稜柱內的眼睛讓你的心裡充滿一股恐懼的感覺...特別在知道你沒有35片頂尖裂片可以召喚出惡魔後。', `MaleText_loc7`='Unos ojos ardientes dentro del prisma te llenan de una sensación de pavor... Especialmente al saber que no tienes los 35 fragmentos de ápices necesarios para invocar a este demonio.' WHERE `ID`=21486;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도전자를 받아들일 준비가 되었습니다. 어서 불러오십시오!', `MaleText_loc4`='我准备好面对挑战者了！叫他出来吧！', `MaleText_loc5`='我準備好要面對我的挑戰者了!叫他出來吧!', `MaleText_loc7`='¡Estoy preparado para enfrentarme a mi aspirante! ¡Llámalo!', `FemaleText_loc1`='도전자를 받아들일 준비가 되었습니다. 어서 불러오십시오!', `FemaleText_loc4`='我准备好面对挑战者了！叫他出来吧！', `FemaleText_loc5`='我準備好要面對我的挑戰者了!叫他出來吧!', `FemaleText_loc7`='¡Estoy preparado para enfrentarme a mi aspirante! ¡Llámalo!' WHERE `ID`=21487;
