UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스케티스는 승리하리라!', `MaleText_loc4`='斯克提斯必胜！', `MaleText_loc5`='司凱堤斯獲勝!', `MaleText_loc7`='¡Skettis prevalece!' WHERE `ID`=21491;
