UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스쿠왁!', `MaleText_loc4`='Skwak！', `MaleText_loc5`='嘎!', `MaleText_loc7`='¡Skwak!', `FemaleText_loc1`='스쿠왁!', `FemaleText_loc4`='Skwak！', `FemaleText_loc5`='嘎!', `FemaleText_loc7`='¡Skwak!' WHERE `ID`=21495;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 젊은 아라코아로군, 아닌가? 눈이 어두워서 말이야.$B$B아마도 내 별난 책 중 하나를 사러 왔겠지?', `MaleText_loc4`='你这个小家伙，害我看走了眼。$B$B我猜你是来购买我出售的特殊货物的吧？', `MaleText_loc5`='你是個年輕的小孩對吧?我失去了我的眼睛。$B$B我猜你要到這要買本我的怪奇書典?', `MaleText_loc7`='Eres una pequeña cría, ¿verdad? Mis ojos me decepcionan.$B$B¿Supongo que estás aquí para comprar alguno de mis escritos exóticos?' WHERE `ID`=21496;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배신자의 눈을 똑바로 쳐다봐라!', `MaleText_loc4`='直视背叛者的双眼吧！', `MaleText_loc5`='直視背叛者的雙眼吧!', `MaleText_loc7`='¡Miren los ojos del Traidor!' WHERE `ID`=21497;
