UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 또 이 칼날 맛을 보고 싶은 거냐?', `MaleText_loc4`='谁想成为下一个？', `MaleText_loc5`='下一個輪到誰來嚐嚐我的刀刃?', `MaleText_loc7`='¿Quién será el próximo en probar mi acero?' WHERE `ID`=21499;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정한 힘에 무지한 족속들이여!', `MaleText_loc4`='你们对力量一无所知！', `MaleText_loc5`='你對真正的力量一無所知!', `MaleText_loc7`='¡No saben nada sobre el PODER!' WHERE `ID`=21500;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='만 년 동안 응어리진 증오를 보여주마!', `MaleText_loc4`='感受一万年的仇恨吧！', `MaleText_loc5`='感受一萬年的仇恨吧!', `MaleText_loc7`='¡Sientan el odio de diez mil años!' WHERE `ID`=21501;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연결된 양자 가속장치를 활성화하는 제어기입니다. 이것으로 바시르의 선구자 혹은 바시르를 소환할 수 있습니다.$B$B물론, 이 제어기를 가동시킬 가속장치 모듈이 있어야 합니다.', `MaleText_loc4`='控制器可以激活关联的质子加速器。激活操作将召唤出一名巴什伊尔先驱者，或许就是巴什伊尔本人。$B$B当然，前提是你有加速器模组来激活这台设备。', `MaleText_loc5`='這個控制器能夠被用來啟動鎖鍊的質子催化裝置。這將會召喚出一位貝許爾的先驅者，或者可能是貝許爾本人。$B$B當然，你要有一個催化裝置模組好啟動這個裝置。', `MaleText_loc7`='El controlador puede usarse para activar el acelerador de protones conectados. Esto invocará a uno de los presagistas de Bash’ir, o quizá al propio Bash’ir.$B$BSuponiendo, claro está, que tengas un modulo acelerador para activar el mecanismo.' WHERE `ID`=21502;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연결된 양자 가속장치를 활성화하는 제어기입니다. 이것으로 바시르의 선구자 혹은 바시르를 소환할 수 있습니다.$B$B유감스럽게도 당신은 제어기를 가동시킬 가속장치 모듈을 가지고 있지 않습니다.', `MaleText_loc4`='控制器可以激活关联的质子加速器。激活操作将召唤出一名巴什伊尔先驱者，或许就是巴什伊尔本人。$B$B可惜，你没有加速器模组来激活这台设备。', `MaleText_loc5`='這個控制器能夠被用來啟動鎖鍊的質子催化裝置。這將會召喚出一位貝許爾的先驅者，或者可能是貝許爾本人。$B$B不幸的是你手上並沒有一個催化裝置模組可以啟動這個裝置。', `MaleText_loc7`='El controlador puede usarse para activar el acelerador de protones conectados. Esto invocará a uno de los presagistas de Bash’ir, o quizá al propio Bash’ir.$B$BPor desgracia no tienes un modulo acelerador para activar el mecanismo.' WHERE `ID`=21503;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가속장치 모듈로 양자 가속장치를 가동시켜 바시르나 바시르의 선구자를 소환합니다.', `MaleText_loc4`='利用加速器模组为质子加速器充能，然后召唤巴什伊尔或者一名巴什伊尔先驱者。', `MaleText_loc5`='以一個催化裝置模組提供質子催化裝置動力來召喚貝許爾，或是他的一位先驅者。', `MaleText_loc7`='Usa un módulo acelerador para encender el acelerador de protones e invocar a Bash’ir o a uno de sus presagistas.', `FemaleText_loc1`='가속장치 모듈로 양자 가속장치를 가동시켜 바시르나 바시르의 선구자를 소환합니다.', `FemaleText_loc4`='利用加速器模组为质子加速器充能，然后召唤巴什伊尔或者一名巴什伊尔先驱者。', `FemaleText_loc5`='以一個催化裝置模組提供質子催化裝置動力來召喚貝許爾，或是他的一位先驅者。', `FemaleText_loc7`='Usa un módulo acelerador para encender el acelerador de protones e invocar a Bash’ir o a uno de sus presagistas.' WHERE `ID`=21504;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<제어기에 필요한 가속장치 모듈을 맞추어 넣고, 마지막으로 제어기를 당깁니다. 가속장치 모듈이 잠깐 반짝거리더니 제어기에 동력이 들어오자 모듈의 에너지가 소모됩니다.>', `MaleText_loc4`='<你将加速器模组放入控制器上的凹槽中，然后拉下控制杆。模组顿时散发出光芒，它的能量随着机械的蜂鸣声转化为了动力。>', `MaleText_loc5`='<放置必要的催化裝置模組在控制器的空間中，你按了最後一按。這個模組發了一下光，能量在這個裝置發出聲音運作時開始消耗。>', `MaleText_loc7`='<Al colocar el módulo acelerador requerido en el hueco del controlador, le das un último tirón. El módulo brilla durante un momento y su energía se agota al tiempo que el mecanismo vuelve a la vida.>' WHERE `ID`=21505;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 이겼다... 마이에브. 하지만, 사냥감이 없는 사냥꾼은... 살아갈 힘을 잃는 법... 너도... 내가 없으면... 아무것도 아니야...', `MaleText_loc4`='你赢了……玛维。但是……一个没有目标的猎手……什么都不是。你……离开了我……什么都不是。', `MaleText_loc5`='你贏了...瑪翼夫。但一個女獵人...不打獵就什麼也不是了。你...沒有我...什麼也不是。', `MaleText_loc7`='Has ganado... Maiev. Pero la cazadora... no es NADA... sin su presa. TÚ... no eres... nada... sin mí.' WHERE `ID`=21506;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 끝났군. 네 놈이 졌다.', `FemaleText_loc4`='结束了。你被打败了。', `FemaleText_loc5`='結束了。你被打敗了。', `FemaleText_loc7`='Se acabó. Perdiste.' WHERE `ID`=21507;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='놈이 옳았어. 공허감이... 밀려오는군. 난 아무것도 아니야.', `FemaleText_loc4`='他说得对。我觉得很失落……我……什么都不是。', `FemaleText_loc5`='他說得對。我覺得很失落...我...什麼都不是。', `FemaleText_loc7`='Tiene razón. No siento nada...no soy...nada.' WHERE `ID`=21508;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='용사들이여, 안녕히...', `FemaleText_loc4`='再会，勇士们。', `FemaleText_loc5`='再會，勇士們。', `FemaleText_loc7`='Adiós, campeones.' WHERE `ID`=21509;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음번에는, 준비라도 하고 오는 성의라도 보여봐라!', `MaleText_loc4`='下次给我放尊重点，至少先准备好再来向我挑战！', `MaleText_loc5`='下一次，至少做好準備讓我感到受尊重。', `MaleText_loc7`='¡La próxima vez, al menos, ten el decoro de estar preparado!' WHERE `ID`=21510;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불쌍하구나! 네 뼈에서 살을 잘라내고 영혼의 고통을 느끼게 해 주마!', `MaleText_loc4`='可怜虫！我要让你尝尝粉身碎骨的痛苦！我要毁灭你的灵魂！', `MaleText_loc5`='真可悲!我將會扯下你的骨肉並折磨你的靈魂做為我的消遣。', `MaleText_loc7`='¡Lástima! ¡Desgarraré la carne de sus huesos y arruinaré sus almas por placer!' WHERE `ID`=21511;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정 나의 주인님이 네놈의 작고 애처로운 함정에 빠져들 거라 생각했느냐, $n?', `MaleText_loc4`='你还真以为我的主人会落入你设计的小圈套，$n？', `MaleText_loc5`='你當真以為你可以用你那個可悲，渺小的陷阱來愚弄打敗我的主人嗎，$n?', `MaleText_loc7`='¿Realmente pensaste que podías hacer que mi maestro cayera en tu triste trampita, $n?' WHERE `ID`=21512;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청이들 같으니!', `MaleText_loc4`='蠢货！', `MaleText_loc5`='蠢蛋!', `MaleText_loc7`='¡Insensatos!' WHERE `ID`=21513;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성스러운 축복의 빛이 이 음산한 전당에 다시 한번... 내리쬐리라.', `MaleText_loc4`='圣光会再次照耀这阴暗的大厅……我发誓。', `MaleText_loc5`='聖光會再次照耀這陰暗的大廳...我發誓。', `MaleText_loc7`='La Luz volverá a bendecir estos lúgubres salones... lo juro.' WHERE `ID`=21514;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빅스톤의 허풍 따윈 잊어버리라고. 좋은 물건을 찾고 있나? 이 크릭셀에게 알아보게나. 원하는 물건이 있을 거야, 물론 그에 걸맞은 위치에 있다면 말이야. 그 뭐냐, 투기장 말이야. 겁쟁이들에겐 어울리지 않는 일이지만 말이야, 친구.', `MaleText_loc4`='别理会维克斯顿的话。你想要好东西？那就和克里希谈一谈。如果你的声望够高的话，我正好有你需要的货物。孩子，你要明白，竞技场上的懦夫是没有资格拥有这些东西的。', `MaleText_loc5`='忘掉維斯頓的廣告。你想要好東西嗎?你正在跟這裡的奎克索說話。我剛好有你要的東西，依你得到的聲望提供。你知道的，在競技場。這個東西不是給娘娘腔用的，孩子。', `MaleText_loc7`='Olvida las baratijas de Vixton. ¿Quieres material bueno? Habla con Krixel aquí. Tengo justo lo que necesitas, suponiendo que tengas la reputación adecuada. Ya sabes, en la arena. Este material no es para nenazas.' WHERE `ID`=21515;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='럴크스터, 비타민을 사고 싶어요.', `MaleText_loc4`='我想购买维生素，鲁克斯特。', `MaleText_loc5`='洛克斯人，我想要買維他命。', `MaleText_loc7`='Quiero comprar vitaminas, Julkster.', `FemaleText_loc1`='럴크스터, 비타민을 사고 싶어요.', `FemaleText_loc4`='我想购买维生素，鲁克斯特。', `FemaleText_loc5`='洛克斯人，我想要買維他命。', `FemaleText_loc7`='Quiero comprar vitaminas, Julkster.' WHERE `ID`=21516;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<위엄 가득한 어깨를 퍼덕거리는 플라스카타우르스>', `MaleText_loc4`='<Flaskataur拍打着他巨大的双翼。>', `MaleText_loc5`='<法拉斯卡托揮動他威武的翅膀。>', `MaleText_loc7`='<Flascotaur bate sus majestuosas alas.>' WHERE `ID`=21517;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 사원을 더럽힌 자들이 모두 죽었다. 단 한 명을 제외하곤 말이다!', `MaleText_loc4`='那些玷污这座神殿的家伙已经全部被打败了。除了一个人之外！', `MaleText_loc5`='那些玷污了這個神廟的人都已經打倒了。只剩一個!', `MaleText_loc7`='Los que profanaron este templo han sido derrotados. ¡Todos menos uno!' WHERE `ID`=21518;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멋진 플라스카타우르스 씨, 물건을 보여주십시오.', `MaleText_loc4`='伟大的Flaskataur，让我购买你出售的货物吧。', `MaleText_loc5`='喔偉大的法拉斯卡托，請讓我購買你的商品。', `MaleText_loc7`='Oh gran Frascotaur, permíteme que compre tus mercancías.', `FemaleText_loc1`='멋진 플라스카타우르스 씨, 물건을 보여주세요.', `FemaleText_loc4`='伟大的Flaskataur，让我购买你出售的货物吧。', `FemaleText_loc5`='喔偉大的法拉斯卡托，請讓我購買你的商品。', `FemaleText_loc7`='Oh gran Frascotaur, permíteme que compre tus mercancías.' WHERE `ID`=21519;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 시작한 일을 끝내도록 하세나. 힘을 회복하면 자네를 일리단이 있는 곳으로 안내하겠네.', `MaleText_loc4`='让我们结束这一切吧。当你恢复了全部的力量之后，我会带你去伊利丹的居所。', `MaleText_loc5`='讓我們結束所有開始了的事吧。一旦你回復力量後，我將會帶領你到伊利丹的住所。', `MaleText_loc7`='Terminemos lo que hemos empezado. Te llevaré a la morada de Illidan en cuanto recuperes tus fuerzas.' WHERE `ID`=21520;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일리단과 맞설 시간이 되었네, $n. 준비 되었나?', `MaleText_loc4`='是面对伊利丹的时候了，$n。你准备好了吗？', `MaleText_loc5`='面對伊利丹的時候到了，$n。你準備好了嗎?', `MaleText_loc7`='Ha llegado la hora de enfrentarse a Illidan, $n. ¿Estás listo?' WHERE `ID`=21521;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비 되었습니다. 아카마.', `MaleText_loc4`='我准备好了，阿卡玛。', `MaleText_loc5`='我準備好了，阿卡瑪。', `MaleText_loc7`='Estoy listo, Akama.', `FemaleText_loc1`='준비 되었습니다. 아카마.', `FemaleText_loc4`='我准备好了，阿卡玛。', `FemaleText_loc5`='我準備好了，阿卡瑪。', `FemaleText_loc7`='Estoy listo, Akama.' WHERE `ID`=21522;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희는 하이잘 산의 전투에 대한 시험용를 집중적으로 하고 있습니다. 시험용에 참여하시려면 보랏빛 눈의 감시자에 대한 평판이 우호적 이상이어야만 합니다.$B$B보랏빛 눈의 감시자의 평판은 카라잔의 몬스터 처치 혹은 관련된 퀘스트로 얻으실 수 있습니다.', `MaleText_loc4`='We''re currently focus testing the Battle of Mount Hyjal. You must have at least HONORED reputation with the Violet Eye to participate.$B$BThat''s the reputation you gain while doing Karazhan.', `MaleText_loc5`='我們最近專注在測試海加爾山戰役。你一定要達到紫羅蘭之眼至少尊敬的聲望才可參加。$B$B就是當你在進行卡拉贊時你可以獲得的聲望。', `MaleText_loc7`='Estamos probando la Batalla del Monte Hyjal. Para participar debes tener, como mínimo, reputación HONORABLE con El Ojo Violeta.$B$BEsa es la reputación que ganas la hacer Karazhan.' WHERE `ID`=21523;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 점점 광포해 집니다!', `MaleText_loc4`='%s变得越来越愤怒了！', `MaleText_loc5`='%s變得愈來愈憤怒!', `MaleText_loc7`='%s se enfada cada vez más.', `FemaleText_loc1`='%s|1이;가; 점점 광포해 집니다!', `FemaleText_loc4`='%s变得越来越愤怒了！', `FemaleText_loc5`='%s變得愈來愈憤怒!', `FemaleText_loc7`='%s se enfada cada vez más.' WHERE `ID`=21524;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지미, 하이잘 산에 들어갈 수 있도록 해 주실 수 있습니까?', `MaleText_loc4`='Jimmy, can you please flag me for Mount Hyjal access？', `MaleText_loc5`='吉米，你能夠幫我標示海加爾山的進入權嗎?', `MaleText_loc7`='Jimmy, ¿puedes marcarme para acceder al Monte Hyjal?', `FemaleText_loc1`='지미, 하이잘 산에 들어갈 수 있도록 해 주실 수 있나요?', `FemaleText_loc4`='Jimmy, can you please flag me for Mount Hyjal access?', `FemaleText_loc5`='吉米，你能夠幫我標示海加爾山的進入權嗎?', `FemaleText_loc7`='Jimmy, ¿puedes marcarme para acceder al Monte Hyjal?' WHERE `ID`=21525;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사고 싶은 물건이 있습니다, 지미.', `MaleText_loc4`='Jimmy, I want to buy something.', `MaleText_loc5`='吉米，我想要買東西。', `MaleText_loc7`='Jimmy, quiero comprar algo.', `FemaleText_loc1`='사고 싶은 물건이 있습니다, 지미.', `FemaleText_loc4`='Jimmy, I want to buy something.', `FemaleText_loc5`='吉米，我想要買東西。', `FemaleText_loc7`='Jimmy, quiero comprar algo.' WHERE `ID`=21526;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하이잘 산에 진입하실 수 있도록 설정해 드렸습니다. 준비가 되시면 시간의 동굴로 순간이동시켜 드릴 테니 말씀해 주십시오.', `MaleText_loc4`='Now that you''re attuned to Mount Hyjal, I can teleport you to the Caverns of Time. Just let me know when you are ready.', `MaleText_loc5`='現在你已經海加爾山同步了，我可以將你傳送至時光之穴了。當你準備好了就讓我知道吧。', `MaleText_loc7`='Ahora que estás preparado para el Monte Hyjal puedo teletransportarte a las Cavernas del Tiempo. Cuando estés preparado, házmelo saber.' WHERE `ID`=21527;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하이잘 산으로 갈 준비가 되었습니다, 지미. 저를 순간이동시켜 주십시오!', `MaleText_loc4`='I''m ready for Mount Hyjal, Jimmy. Teleport me！', `MaleText_loc5`='我準備好進入海加爾山了，吉米。傳送我!', `MaleText_loc7`='Estoy preparado para el Monte Hyjal, Jimmy. ¡Teletransportame!', `FemaleText_loc1`='하이잘 산으로 갈 준비가 되었습니다, 지미. 저를 순간이동시켜 주십시오!', `FemaleText_loc4`='I''m ready for Mount Hyjal, Jimmy. Teleport me！', `FemaleText_loc5`='我準備好進入海加爾山了，吉米。傳送我!', `FemaleText_loc7`='Estoy preparado para el Monte Hyjal, Jimmy. ¡Teletranspórtame!' WHERE `ID`=21528;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희는 검은 사원에 대한 테스트를 집중적으로 하고 있습니다. 테스트에 참여하시려면 보랏빛 눈의 감시자에 대한 평판이 우호적 이상이어야만 합니다.$B$B보랏빛 눈의 감시자의 평판은 카라잔의 몬스터 처치 혹은 관련된 퀘스트로 얻으실 수 있습니다.', `MaleText_loc4`='We''re currently focus testing The Black Temple. You must have at least HONORED reputation with the Violet Eye to participate.$B$BThat''s the reputation you gain while doing Karazhan.', `MaleText_loc5`='我們最近專注在測試黑暗神廟。你一定要達到紫羅蘭之眼至少尊敬的聲望才可參加。$B$B就是當你在進行卡拉贊時你可以獲得的聲望。', `MaleText_loc7`='Nos estamos centrando en probar El Templo Oscuro. Para participar debes tener, como mínimo, reputación HONORABLE con El Ojo Violeta.$B$BEsa es la reputación que ganas la hacer Karazhan.' WHERE `ID`=21529;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은 사원에 진입할 수 있는 열쇠와 물건을 좀 구입하고 싶습니다.', `MaleText_loc4`='I wish to purchase the key to the Black Temple and some phat lewtz.', `MaleText_loc5`='我想要購買黑暗神廟的鑰匙還有一些優良裝備。', `MaleText_loc7`='Quiero comprar la llave de El Templo Oscuro y algo de botín.', `FemaleText_loc1`='검은 사원에 진입할 수 있는 열쇠와 물건을 좀 구입하고 싶습니다.', `FemaleText_loc4`='I wish to purchase the key to the Black Temple and some phat lewtz.', `FemaleText_loc5`='我想要購買黑暗神廟的鑰匙還有一些優良裝備。', `FemaleText_loc7`='Quiero comprar la llave de El Templo Oscuro y algo de botín.' WHERE `ID`=21530;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은 사원에 진입할 수 있는 열쇠인 카라보르의 메달을 소지품에 넣어 드렸습니다. 준비가 되셨으면 검은 사원으로 바로 순간이동시켜 드리도록 하겠습니다.', `MaleText_loc4`='Now that you have your Black Temple key (Medallion of Karabor), I can teleport you directly to the Black Temple. Just tell me when you are ready.', `MaleText_loc5`='現在你已經有了黑暗神廟的鑰匙(卡拉伯爾勳章)，我可以直接傳送你到黑暗神廟。當你準備好就跟我說吧。', `MaleText_loc7`='Ahora que tienes tu llave de El Templo Oscuro (Medallón de Karabor), puedo teletransportarte directamente a El Templo Oscuro. Avísame cuando estés $glisto:lista;.' WHERE `ID`=21531;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조니, 검은 사원으로 갈 준비를 마쳤습니다.', `MaleText_loc4`='我准备好进入黑暗神殿了，约翰尼。', `MaleText_loc5`='我準備好前往黑暗神廟了，強尼。', `MaleText_loc7`='Estoy listo para ir a El Templo Oscuro, Johnny.', `FemaleText_loc1`='조니, 검은 사원으로 갈 준비를 마쳤습니다.', `FemaleText_loc4`='我准备好进入黑暗神殿了，约翰尼。', `FemaleText_loc5`='我準備好前往黑暗神廟了，強尼。', `FemaleText_loc7`='Estoy listo para ir a El Templo Oscuro, Johnny.' WHERE `ID`=21532;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑습니다, 친구여! 어떤 물건을 보고 싶은가요?', `MaleText_loc4`='欢迎你，朋友！你想看什么？', `MaleText_loc5`='歡迎朋友!你想要看些什麼呢?', `MaleText_loc7`='¡$gBienvenido amigo:Bienvenida amiga;! ¿Qué te gustaría ver?' WHERE `ID`=21533;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오세요, $G형제:자매;님. 뭘 도와드리면 될까요?', `MaleText_loc4`='你好，朋友。我们能帮你什么忙吗？', `MaleText_loc5`='你好$G兄弟:姐妹;。我們可以怎麼幫助你呢?', `MaleText_loc7`='Saludos $ghermano:hermana;. ¿Cómo podemos servirte?' WHERE `ID`=21534;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필요한 거라도 있나요?', `MaleText_loc4`='我们能帮你什么忙吗？', `MaleText_loc5`='我們要怎麼幫你呢?', `MaleText_loc7`='¿Cómo podemos ayudarte?' WHERE `ID`=21535;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대단하신 분이 오셨군요! 제가 도와드릴 일이 있으면 무엇이든지 말씀하십시오.', `MaleText_loc4`='勇士！我们能帮你什么忙吗？', `MaleText_loc5`='偉大的人!我們要如何為您服務呢?', `MaleText_loc7`='¡Poderoso! ¿Cómo podemos servirte?' WHERE `ID`=21536;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='친구여, 제 상점을 방문해 주시다니 영광입니다. 오늘은 어떤 물건을 권해 드리면 될까요?', `MaleText_loc4`='你来到这里真是我们的荣幸，朋友。我们能帮你什么忙吗？', `MaleText_loc5`='你的光臨另我們備感榮幸，朋友。今天我們能為你服務什麼呢?', `MaleText_loc7`='Tu presencia nos honra, amigo. ¿En qué podemos ayudarte hoy?' WHERE `ID`=21537;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강하신 분! 마음에 드는 음식을 찾으시길 바랍니다.', `MaleText_loc4`='勇士！希望你喜欢我们的食物。', `MaleText_loc5`='偉大的人!我們希望我們的食物能夠讓您覺得滿意。', `MaleText_loc7`='¡Poderoso! Esperamos que nuestra comida sea de tu agrado.' WHERE `ID`=21538;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희 음식은 엄청나게 배가 고프신 분들에게조차도 만족스러우실 겁니다.', `MaleText_loc4`='我们的食物能令最强大的勇士赞不绝口。', `MaleText_loc5`='我們的食物連最強烈的飢餓感都能滿足。', `MaleText_loc7`='Nuestra comida debería saciar incluso el hambre más voraz.' WHERE `ID`=21539;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오그릴라의 친구여, 아직도 배가 고프신가요? 어떤 음식이 좋을까요?', `MaleText_loc4`='还是很饿吗，朋友？我们能帮你什么忙吗？', `MaleText_loc5`='還餓嗎，$G兄弟:姐妹;?我們能幫上什麼忙嗎?', `MaleText_loc7`='¿Aún estás $ghambriento:hambrienta; $ghermano:hermana;? ¿Cómo podemos ayudar?' WHERE `ID`=21540;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 친구이신 당신을 위해 먹자판을 벌려 드리지요.', `MaleText_loc4`='朋友，我们为你准备了一顿美餐。', `MaleText_loc5`='我們為你準備了盛宴，朋友。', `MaleText_loc7`='Tenemos un buen festín para tu amigo.' WHERE `ID`=21541;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 맛의 음식을 제공해 드리면 될까요?', `MaleText_loc4`='我们能为你提供什么美味吗？', `MaleText_loc5`='我們能提供你什麼美味的宴席?', `MaleText_loc7`='¿Qué delicias podemos ofrecerte?' WHERE `ID`=21542;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 전투에서 숨을 거둡니다.', `MaleText_loc4`='%s阵亡了。', `MaleText_loc5`='%s從戰鬥中斷氣。', `MaleText_loc7`='%s cae en la batalla.' WHERE `ID`=21543;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 다시 전투를 시작합니다!', `MaleText_loc4`='%s再次站起来投入战斗！', `MaleText_loc5`='%s復活再戰。', `MaleText_loc7`='¡%s se alza para luchar una vez más!' WHERE `ID`=21544;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아카마 님, 당신은 혼자가 아닙니다.', `MaleText_loc4`='你不是孤身一人，阿卡玛！', `MaleText_loc5`='你並不孤單，阿卡瑪。', `MaleText_loc7`='No estás solo, Akama.' WHERE `ID`=21545;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네의 백성은 항상 자네와 함께일 것이야!', `MaleText_loc4`='你的人民永远和你在一起！', `MaleText_loc5`='你的人民將永遠與你同在!', `MaleText_loc7`='¡Tu gente siempre estará contigo!' WHERE `ID`=21546;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요. 저희 하늘경비대에서 좋은 평판을 얻으면, 스키실 산맥에 있는 저희 기지인 검은바람 비행기지로 바로 보내드릴 수 있답니다.$B$B제 어여쁜 황천의 가오리가 맘에 드시나요? 사랑스러운 녀석이죠.', `FemaleText_loc4`='嘿，朋友。如果你和天空卫队搞好关系的话，我就为你开通前往鸦羽山黑风码头的直达航线。$B$B你喜欢这只漂亮的虚空鳐吗？它真可爱。', `FemaleText_loc5`='嘿，同志。如果你跟禦天者關係良好的話，我可以提供你直接飛行到我們在斯其索山脈的基地，黑風平臺。$B$B你喜歡我美麗的虛空鰭刺嗎?它很可愛。', `FemaleText_loc7`='Hey camarada. Si te llevas bien con la Guardia del cielo puedo ofrecerte un vuelo directo a nuestra base, el Alto de los Vientonegro en las Montañas skethyl.$B$B¿Te gusta mi preciosa raya abisal? Es encantadora.' WHERE `ID`=21547;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혼자선 할 수가 없구나...', `MaleText_loc4`='我一个人无法获胜……', `MaleText_loc5`='我無法獨力完成...', `MaleText_loc7`='No puedo hacer esto solo...' WHERE `ID`=21548;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어서 오세요, $n. 스키실 산맥에 있는 저희 기지인 검은바람 비행기지에 급한 일이 있으신가요? 저에게 예쁘고 작은 황천의 가오리가 준비되어 있답니다.$B$B지금 바로 가고자 하시나요? 말만 하시면 된답니다!', `FemaleText_loc4`='你好，$n。要赶去我们位于鸦羽山的基地黑风码头吗？我为你准备了一只漂亮的小虚空鳐。$B$B现在就出发吗？和我说一声就成！', `FemaleText_loc5`='哈囉，$n。需要快速抵達我們在斯其索山脈的基地，黑風平臺嗎?我有一隻美麗，小型的虛空鰭刺待命中。$B$B你現在就想去嗎?你只要說句話，$g大傢伙:小兔子;!', `FemaleText_loc7`='Hola, $n. ¿Necesitas llegar rápido al Alto de los Vientonegro, nuestra base en las Montañas Skethyl? Tengo una linda raya abisal preparada.$B$B¿Quieres ir ahora? ¡Tan solo di la palabra $gchico grande: nena;!' WHERE `ID`=21549;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 검은바람 비행기지로 갔으면 합니다.', `MaleText_loc4`='是，我愿意乘坐虚空鳐飞往黑风码头。', `MaleText_loc5`='沒錯，我想要到黑風平臺。', `MaleText_loc7`='Sí, me vendría bien que me llevaras al Alto de los Vientonegro.', `FemaleText_loc1`='네, 검은바람 비행기지로 갔으면 합니다.', `FemaleText_loc4`='是，我愿意乘坐虚空鳐飞往黑风码头。', `FemaleText_loc5`='沒錯，我想要到黑風平臺。', `FemaleText_loc7`='Sí, me vendría bien que me llevaras al Alto de los Vientonegro.' WHERE `ID`=21550;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까. 원하신다면 칼날 산맥의 하늘경비대 전초기지까지 바로 날아가는 황천의 가오리를 하나 내어 드리지요.$B$B필요하시면 말씀만 하십시오.', `MaleText_loc4`='你好！如果你想要飞往刀锋山的天空卫队哨站的话，我可以为你准备一只虚空鳐。$B$B和我说一声就成。', `MaleText_loc5`='哈囉，$g先生:小姐;!如果你要的話，我有一隻虛空鰭刺等著帶你到劍刃山脈上的禦天者前哨。$B$B只要跟我說一聲就行了。', `MaleText_loc7`='¡Hola $gseñor:señora;! Si quieres, tengo una raya abisal esperando para llevarte a la Avanzada de la Guardia del Cielo, en lo alto de las montañas Filospada.$B$BTan solo házmelo saber.' WHERE `ID`=21551;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하시오. 당신도 샤타리 하늘경비대에서 더 높은 지위를 얻으면 칼날 산맥의 하늘경비대 전초기지까지 이어지는 직항로를 이용할 수 있을 것이오.', `MaleText_loc4`='你好。如果你在沙塔尔天空卫队的声望再提升一点，我就为你开通前往刀锋山天空卫队哨站的直达航线。', `MaleText_loc5`='你好。當你在薩塔禦天者的官階晉升時，我就能夠提供你直接飛行到我們位於劍刃山脈上的基地，禦天者前哨。', `MaleText_loc7`='Buenos días. Cuando hayas subido un poco más en las filas de la Guardia del cielo Sha’tari, podré ofrecerte un vuelo directo a la Avanzada de la Guardia del Cielo, nuestro campamento en lo alto de las Montañas Filospada.' WHERE `ID`=21552;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론입니다! 저를 하늘경비대 전초기지로 보내 주십시오!', `MaleText_loc4`='当然！送我回天空卫队哨站吧。', `MaleText_loc5`='太棒了!送我到禦天者前哨。', `MaleText_loc7`='¡Claro! Envíame a la Avanzada de la Guardia del cielo!', `FemaleText_loc1`='물론입니다! 저를 하늘경비대 전초기지로 보내 주세요!', `FemaleText_loc4`='当然！送我回天空卫队哨站吧。', `FemaleText_loc5`='太棒了!送我到禦天者前哨。', `FemaleText_loc7`='¡Claro! Envíame a la Avanzada de la Guardia del cielo!' WHERE `ID`=21553;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형제여, 자네의 도움에 감사하네. 우리 백성들은 구원받게 될 것이야!', `MaleText_loc4`='我感谢你们的帮助，兄弟们。我们的人民会报答你们的！', `MaleText_loc5`='我感謝你的協助，兄弟。我們的人民將會回報的!', `MaleText_loc7`='Agradezco su ayuda, hermanos. ¡Nuestro pueblo será redimido!' WHERE `ID`=21554;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하시오, 친구들. 배신자가 코앞에서 명상을 취하고 있으니...', `MaleText_loc4`='当心点，朋友们。背叛者就在那边的大厅中冥想。', `MaleText_loc5`='當心點，朋友們。背叛者就在那邊的大廳中冥想。', `MaleText_loc7`='Tengan cuidado, amigos. El Traidor medita en el patio de ahí al lado' WHERE `ID`=21555;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벌레 같은 녀석, 이걸로 뭘 하고자 하는 것이냐?', `MaleText_loc4`='你这渣滓，你希望怎么解决此事？', `MaleText_loc5`='你希望從這當中達到什麼，蟲子?', `MaleText_loc7`='¿Qué esperas conseguir con esto, insecto?' WHERE `ID`=21556;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모기 잡듯이 네 녀석을 뭉개주마!', `MaleText_loc4`='碾碎你就象捏死一只虫子那样简单！', `MaleText_loc5`='我將會將你像蚊子一樣打碎!', `MaleText_loc7`='¡TE APLASTARÉ COMO A UN MOSQUITO!' WHERE `ID`=21557;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우릴 막을 순 없을 것이다!', `MaleText_loc4`='你阻止不了我们！', `MaleText_loc5`='你無法阻止我們!', `MaleText_loc7`='¡No puedes detenernos!' WHERE `ID`=21558;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필멸의 존재 녀석이 날 화나게 하다니!', `MaleText_loc4`='你让我很生气，凡人！', `MaleText_loc5`='你在惹我生氣，凡人!', `MaleText_loc7`='¡Me estas enfadando, mortal!' WHERE `ID`=21559;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나약한 녀석, 널 두 동강내 주마!', `MaleText_loc4`='我会把你劈成两半的！收敛点，蠢货！', `MaleText_loc5`='我將會把你打成兩半!消失吧，蠢蛋!', `MaleText_loc7`='¡Te partiré en dos! ¡Cede insensato!' WHERE `ID`=21560;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='목숨이 붙어 있을 동안 도망가는 게 좋을 거다!', `MaleText_loc4`='现在就逃吧，趁你还活着的时候逃走吧！', `MaleText_loc5`='趁現在你還活著，快逃吧!', `MaleText_loc7`='¡Huye ahora que aún tienes tu vida!' WHERE `ID`=21561;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이치에 맞게 생각해봐라! 불타는 군단을 막고자 바랄 수조차 없을 것이야! 자, 이성적으로 얘기해 보자꾸나. 내가 너의 그 꿈을 이루는 넘어서는 힘을 줄 수도 있다.', `MaleText_loc4`='理智点！想要阻止燃烧军团？别做白日梦了！让我们用文明的方式来探讨这个问题。我能赐予你连做梦都不敢想的强大的力量！', `MaleText_loc5`='理智點!你不能期望可以阻止燃燒軍團!讓我們以文明的態度來討論一下。我可以給你超越你所能夢想的力量!', `MaleText_loc7`='¡Sé razonable! ¡No puede detenerle a la Legión Ardiente! Discutámoslo de forma civilizada. ¡Puedo ofrecerte más poder del que jamás hayas soñado!' WHERE `ID`=21562;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 문이 그 배신자와 우리 사이에 서 있는 마지막 관문일세. 비켜서게나, 친구들.', `MaleText_loc4`='在我们和伊利丹之间就只剩下这扇门了。站开点，朋友们。', `MaleText_loc5`='這道門就是我們與背叛者之間所有的阻隔了。站開點，朋友。', `MaleText_loc7`='Esta puerta es todo lo que se interpone entre el Traidor y nosotros. Apartad, amigos.' WHERE `ID`=21563;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법불꽃 재봉술과 관련하여 당신이 그동안 익힌 기술을 머릿속에서 지우는 일은 그리 쉬운 작업이 아닙니다. 마법불꽃 재봉술 포기를 선택하시면 그동안 배운 모든 도안에 대해서 까맣게 잊어버리게 될 것입니다.', `MaleText_loc4`='遗忘魔焰裁缝专精并不是件轻松的事。如果你选择放弃，那么你就会忘记所有与魔焰裁缝专精相关的图样！', `MaleText_loc5`='遺忘你的魔焰裁縫技能不是件隨便的事。如果你選擇放棄，你將會失去所有需要魔焰裁縫的製作方法!', `MaleText_loc7`='Olvidar tu habilidad en sastrería con fuego de hechizo no es algo que deba tomarse a la ligera. ¡Si decides eliminarla, olvidarás todas las recetas que necesiten sastrería con fuego de hechizo para realizarlas!', `FemaleText_loc1`='마법불꽃 재봉술과 관련하여 당신이 그동안 익힌 기술을 머릿속에서 지우는 일은 그리 쉬운 작업이 아닙니다. 마법불꽃 재봉술 포기를 선택하시면 그동안 배운 모든 도안에 대해서 까맣게 잊어버리게 될 것입니다.', `FemaleText_loc4`='遗忘魔焰裁缝专精并不是件轻松的事。如果你选择放弃，那么你就会忘记所有与魔焰裁缝专精相关的图样！', `FemaleText_loc5`='遺忘你的魔焰裁縫技能不是件隨便的事。如果你選擇放棄，你將會失去所有需要魔焰裁縫的製作方法!', `FemaleText_loc7`='Olvidar tu habilidad en sastrería con fuego de hechizo no es algo que deba tomarse a la ligera. ¡Si decides eliminarla, olvidarás todas las recetas que necesiten sastrería con fuego de hechizo para realizarlas!' WHERE `ID`=21564;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 비밀 살빼기 작전을 알려 드리지요. 바로 칵테일과 몽상이랍니다. 저희가 술 한잔으로 도와드리지요.', `MaleText_loc4`='我们会为你奉上秘制饮品：鸡尾酒和梦想。至少我们能帮你实现其中一项。', `MaleText_loc5`='我們會讓你加入我們的秘密節食:雞尾酒以及作夢。我們可以一起幫助你。', `MaleText_loc7`='Te contaremos nuestra dieta secreta: cócteles y sueños. Podemos ayudarte con una de las dos cosas.' WHERE `ID`=21565;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법불꽃 재봉술 습득을 취소하고 싶습니다.', `MaleText_loc4`='我想遗忘魔焰裁缝专精。', `MaleText_loc5`='我想要遺忘魔焰裁縫。', `MaleText_loc7`='Deseo olvidar lo aprendido sobre sastrería con fuego de hechizo.', `FemaleText_loc1`='마법불꽃 재봉술 습득을 취소하고 싶습니다.', `FemaleText_loc4`='我想遗忘魔焰裁缝专精。', `FemaleText_loc5`='我想要遺忘魔焰裁縫。', `FemaleText_loc7`='Deseo olvidar lo aprendido sobre sastrería con fuego de hechizo.' WHERE `ID`=21566;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두가 술을 마셔야 하지요. 어떤 술을 드릴까요?', `MaleText_loc4`='所有人都要喝酒。我们能为你做些什么呢？', `MaleText_loc5`='每個人都有一杯飲料。你想要什麼呢?', `MaleText_loc7`='Todo el mundo tiene que beber. ¿Qué te servimos?' WHERE `ID`=21568;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기존에 습득한 지식을 취소하려면 큰 노력이 필요하답니다. 그 희생을 치를 준비가 되었습니까?', `MaleText_loc4`='遗忘你已经学会的知识需要一大笔钱，而且这并不是件容易的事。你真的希望付这笔费用吗？', `MaleText_loc5`='遺忘你的知識是個昂貴的舉動。你願意付出這筆花費嗎?', `MaleText_loc7`='Olvidar tu conocimiento es un esfuerzo caro. ¿Estás dispuesto a pagar el precio?', `FemaleText_loc1`='기존에 습득한 지식을 취소하려면 큰 노력이 필요하답니다. 그 희생을 치를 준비가 되었나요?', `FemaleText_loc4`='遗忘你已经学会的知识需要一大笔钱，而且这并不是件容易的事。你真的希望付这笔费用吗？', `FemaleText_loc5`='遺忘你的知識是個昂貴的舉動。你願意付出這筆花費嗎?', `FemaleText_loc7`='Olvidar tu conocimiento es un esfuerzo caro. ¿Estás dispuesto a pagar el precio?' WHERE `ID`=21569;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑습니다, 친구여. 어떻게 도와 드릴까요?', `MaleText_loc4`='你好，朋友。我们能为你做些什么吗？', `MaleText_loc5`='你好$G兄弟:姐妹;，我能幫忙你什麼呢?', `MaleText_loc7`='Saludos $Ghermano:hermana;, ¿cómo podemos ayudar?' WHERE `ID`=21570;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희가 보유한 술은 갈증에 목이 타들어 가는 사람의 목도 축여준답니다.', `MaleText_loc4`='我们的美酒能滋润最干涸的喉咙。', `MaleText_loc5`='我們的飲料就算連最強烈的口渴都能解渴。', `MaleText_loc7`='Nuestras bebidas deberían saciar hasta la sed más desmedida.' WHERE `ID`=21571;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나와 수다를 떠는 것 말고 뭔가 더 잘할 순 없겠소?$B$B이제 가서 당신의 용맹함을 보여주란 말이오!', `MaleText_loc4`='除了和我闲聊，你就没有别的事可做了吗？$B$B拿出你的勇气来！', `MaleText_loc5`='你除了跟我閒扯外沒有別的事好做了嗎，$g小夥子:小姑娘;?$B$B現在馬上到外面去表現你的勇氣!', `MaleText_loc7`='¿No tienes nada mejor que hacer que molestarme, $Gchico:chica;?$B$B¡Ahora vete de aquí y demuestra tu entereza!' WHERE `ID`=21572;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 그 정신이오! 당신이 해낸 모든 일로 우릴 자랑스럽게 하는군!$B$B그리고 당신도 알다시피 스키실에 있는 우리 기지로 빨리 가고자 한다면, 저리 내려가서 하늘경비대 조련사 이레나에게 얘기해 보시오. 그가 잘 주선해 줄 것이오.', `MaleText_loc4`='这样就对啦！我们为你所做的一切感到光荣！$B$B如果你想要前往我们在鸦羽山的另一处基地，就和天空卫队训练师伊雷娜谈一谈吧。她会很乐意为你安排的。', `MaleText_loc5`='就是這股精神，$g小夥子:小姑娘;!你讓我們大家對你的作為感到驕傲!$B$B你知道的，如果你想要快速的抵達我們在斯其索山脈的另一個基地的話，到下面去跟禦天者管理者艾瑞娜談談。她會讓你好好的起飛。', `MaleText_loc7`='¡Ese es el espíritu, $gchico:chica;! ¡Estamos muy orgullosos del trabajo que estás haciendo para nosotros!$B$BY ya sabes, si quieres un viaje rápido a las Montañas Skethyl, baja a hablar con la cuidadora de la Guardia del cielo Irena. Ella se encargará.' WHERE `ID`=21573;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 하늘경비대 주변에서 존경의 대상이 되어가고 있군그래! 내가 우리 업무를 더 잘 알지 않았다면 말이야, 당신이 내 일을 맡았을 거라고 할 수 있겠군!!!$B$B어쨌거나 하던 방식대로 일을 잘해 나간다면, 사령관 자리쯤이야 따논 당상이라고!', `MaleText_loc4`='你受到了大家的尊敬，朋友！要不是我明白事理的话，肯定会以为你想抢我的饭碗！！！$B$B只要你像之前那样继续帮助我们，你就值得受到这样的尊重！', `MaleText_loc5`='你變成這裡一個受人尊敬的象徵了，$g男孩:女孩;!要不是我知道內情的話，我會說你是搶了我的工作!!!$B$B還是一樣，如果你繼續維持下去的話，你會值得的!', `MaleText_loc7`='¡Te estás convirtiendo en un personaje venerado por aquí $gchico:chica;! ¡Si no supiera que no, pensaría que estás intentando quedarte con mi trabajo!$B$B¡Es igual, si sigues como hasta ahora te lo habrás ganado!' WHERE `ID`=21574;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='술을 마시던지 저리 가 주세요!', `MaleText_loc4`='要么饮酒，要么滚开！', `MaleText_loc5`='要喝或是離開!', `MaleText_loc7`='¡Bebe o vete!' WHERE `ID`=21575;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샤타리 하늘경비대의 최고 요원인데 무슨 말이 필요하겠소!$B$B하지만 너무 우쭐대진 마시구려. 아직 한두 가지 가르쳐줄 요령이 있으니 말이오!$B$B<윙크를 하며 싱긋 웃는 하늘경비대 사령관 켈러>', `MaleText_loc4`='我还能说什么，$n？你是最棒的沙塔尔天空卫士！$B$B别被溢美之词冲昏了头脑。我还有别的东西可以教给你！$B$B<天空指挥官凯勒对你咧嘴一笑，眨了眨眼睛。>', `MaleText_loc5`='我能說什麼，$n?你是薩塔禦天者裡最好的人了!$B$B只是不要被沖昏腦就好。我還是可以教你一兩件事，$g小夥子:小姑娘;!$B$B<天空指揮官凱勒對你露齒而笑並眨眨眼。>', `MaleText_loc7`='¿Qué puedo decir, $n? ¡Eres lo mejor de la Guardia del cielo Sha’tari!$B$BPero no dejes que se te suba a la cabeza. ¡Todavía puedo enseñarte un par de cosas $gchico:chica;!$B$B<El comandante del cielo Keller sonríe y te guiña un ojo.>' WHERE `ID`=21576;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='풋내기 친구, 이곳 주위의 임무에 시간을 잘 활용하고 있는 것 같군요.$B$B하지만 좀 더 시간을 투자하도록 하세요. 아직 악마들이 사라진 건 아니니까요.', `FemaleText_loc4`='我知道你耗费了不少精力来帮助我们，$c。$B$B新手，继续努力吧，歼灭所有的恶魔！', `FemaleText_loc5`='我知道你已經在這裡付出你的時間了，$c。$B$B再多付出多一點;惡魔還沒離開，菜鳥。', `FemaleText_loc7`='Veo que has estado invirtiendo tu tiempo por aquí, $c.$B$BInvierte más, aún quedan demonios, novato.' WHERE `ID`=21577;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 전초기지에 있는 모든 친구들의 입에 당신의 이름이 오르내리는 것 같군요. 너무 자만하지 않는 게 좋을 겁니다. 당신이 더 잘할 수 있다는 걸 알고 있으니까요!$B$B풋내기씨, 내가 지켜보고 있을 거예요.', `FemaleText_loc4`='哨站的每个人都在提起你的名字。别因此沾沾自喜，我知道你能做得更好！$B$B我会继续关注你的，新手。', `FemaleText_loc5`='你的名字好像在崗哨口耳相傳著。不讓要這沖昏你的頭;我知道你可以做得更好!$B$B我會盯著你的，菜鳥。', `FemaleText_loc7`='Tu nombre parece estar en los labios de todo el mundo en la avanzada. ¡No dejes que se te suba a la cabeza; yo sé que aún puedes hacerlo mejor!$B$BTe estaré vigilando, novato.' WHERE `ID`=21578;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 확고한 동맹이여, 원하는 물건이 있으신가요?', `MaleText_loc4`='尊敬的勇士，我们能帮你什么忙吗？', `MaleText_loc5`='我們要如何提供幫忙，令人崇拜的人?', `MaleText_loc7`='¿Cómo podemos ser de ayuda, engrandecido?' WHERE `ID`=21579;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋아요, 당신의 실력을 증명했다는 사실을 인정하겠어요, $n.$B$B내가 전에 심하게 군 건 당신에게서 진정한 하늘경비대의 모습을 보았기 때문이랍니다. 당신이 우리 최고의 기수라고 감히 말하고 싶군요!$B$B언제든 우리를 돕고 싶으시면, 영광으로 여기며 폭탄 더미를 넘겨드리도록 하지요.', `FemaleText_loc4`='好吧，我承认。$n，你已经证明了自己的实力。$B$B如果说我之前对你太过严厉的话，那也是因为我发现你具备一名优秀的天空卫士的潜质。我敢说你就是我们的王牌飞行员！$B$B任何时候你想来帮忙都成，我会为你准备好一组炸弹的。', `FemaleText_loc5`='很好，我承認，你已經證明了你自己還有接下來的一些事，$n。$B$B如果我之前對你很嚴格的話，那是因為我看到你體內有一位真正的禦天者靈魂。我敢說你會是我們手中最好的王牌!$B$B任何時候你想要幫忙的話，我會非常榮幸將另一組炸彈親手交付給你。', `FemaleText_loc7`='Vale, lo admito, has demostrado lo que vales y más, $n.$B$BSi antes he sido dura contigo, ha sido porque he visto la chispa de un auténtico Guardia del cielo en ti. ¡Me atrevería a decir que eres el mejor as que tenemos!$B$BCuando quieras ayudar, estaré más que orgullosa de entregarte otro montón de bombas.' WHERE `ID`=21580;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희가 보유한 물건을 제공해 드릴 수 있어 기쁘군요.', `MaleText_loc4`='我们很高兴为你提供补给。', `MaleText_loc5`='我們很高興能夠提供補及品給你。', `MaleText_loc7`='Nos alegra poder abastecerte.' WHERE `ID`=21581;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 우호적인 친구분, 어떻게 도와드릴까요?', `MaleText_loc4`='尊敬的勇士，我们能帮你什么忙吗？', `MaleText_loc5`='令人尊敬的$G兄弟:姐妹;，我們要怎如何幫忙呢?', `MaleText_loc7`='Honrado $G hermano:hermana;, ¿cómo podemos ayudar?' WHERE `ID`=21582;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$c님, 안녕하세요!$B$B<수줍게 쳐다보는 카티에>$B$B에테르 가오리를 좀 더 데려오고 싶으시면 언제든지 절 보러 오도록 하세요!', `FemaleText_loc4`='嗨，$c！$B$B<卡提害羞地看着你。>$B$B如果你愿意为我们捕捉更多的以太鳐，可以随时过来找我！', `FemaleText_loc5`='你好，$c!$B$B<卡緹狡猾的看著你。>$B$B任何時候要是你想要幫我們看管更多的蒼穹鰭刺，就設法前來見我!', `FemaleText_loc7`='¡Hola $c!$B$B<Khatie te mira astutamente.>$B$B¡Cuando quieras domar más rayas de éter, asegúrate de venir a verme!' WHERE `ID`=21583;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 오랜만에 오셨네요, 오그릴라의 친구분. 어떤 물건을 보여드릴까요?', `MaleText_loc4`='朋友！好久不见！我们能为你做些什么吗？', `MaleText_loc5`='朋友!已經好久了。我們能給你什麼呢?', `MaleText_loc7`='¡Amigo! Ha pasado mucho tiempo. ¿Qué podemos conseguirte?' WHERE `ID`=21584;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 물건을 찾으시나요?', `MaleText_loc4`='你在找什么？', `MaleText_loc5`='你在尋找什麼?', `MaleText_loc7`='¿Qué buscas?' WHERE `ID`=21585;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 당신과 함께 일하게 되어서 무척 영광이었답니다!$B$B가오리를 생포하는 일로 바쁘지 않으시다면, $g어디가서 저녁이라도 함께하실까요? : 우리 함께 나가서 멋진 여자들만의 멋진 시간을 만들어보는 건 어떨까요?;$B$B오, 제가 스키실에 있는 우리 기지로 정말 빨리 보내드릴 수 있다고 얘기했던가요? 그 기지로 가는 방법에 대해서는 하늘경비대 조련사 이레나와 얘기해 보도록 하세요.', `FemaleText_loc4`='你知道吗，$n，很荣幸能和你一起共事！$B$B当你闲下来的时候，或许我们可以共进晚餐？$B$B哦，我们为你开通了前往鸦羽山基地的直达航线，我有没有告诉你这件事啊？如果你想去那里的话，就与天空卫队训练师伊雷娜谈一谈。', `FemaleText_loc5`='你知道的，$n，可以跟你一起工作真是榮幸!$B$B等你不忙著爭論時，也許我們可以$g一起吃個晚餐?:一起來個女孩之夜?;$B$B喔，我有提到我們現在能夠讓你很快速地前往我們在斯其索山脈的基地嗎?要是你想要的話，去找禦天者管理者艾瑞娜談一談。', `FemaleText_loc7`='Ya sabes, $n, es un gran honor trabajar contigo.$B$BCuando no estés domando, quizá podamos $gsalir a cenar : juntarnos para una noche de chicas;.$B$B¡Oh! ¿He mencionado que ahora podemos llevarte a nuestro campamento en las Montañas Skethyl realmente rápido? Si quieres, hablaré con la cuidadora de la Guardia del cielo Irena acerca de eso.' WHERE `ID`=21586;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이곳에 자주 오신 것 같은데, 일을 마친 후에 만나지 못하고 서로 계속 엇갈린 것 같네요.$B$B저 때문인가요?$B$B<일부러 기운을 내는 카티에>$B$B어쨌거나, 제가... 우린 당신이 하늘경비대를 위해 해 준 모든 일에 정말 감사드린다고 얘기하고 싶었답니다!', `FemaleText_loc4`='这么说，你常来这附近，可惜闲暇时我们总是没机会聚聚。$B$B我说得对吗？$B$B<卡提故意流露出振奋的神情。>$B$B不管怎样，我都想告诉你，我……我们真的非常感谢你为天空卫队所做的一切！', `FemaleText_loc5`='那麼，你常常到這附近，不過我們好像常常錯過彼此在下班後聚在一起。$B$B是我嗎?$B$B<卡緹裝得很高興。>$B$B無論如何，我只是想要說我...我們真的很感謝你為禦天者做過的每件事!', `FemaleText_loc7`='Así que parece que habéis andado mucho juntos pero seguís echando de menos quedar juntos después del trabajo.$B$B¿Soy yo?$B$B<Khatie se alegra a propósito.>$B$BDe todos modos, solo quería decir que yo... nosotros apreciamos mucho todo lo que has hecho por la Guardia del cielo.' WHERE `ID`=21587;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='절 게으름뱅이랑 비슷한 경비대원으로 생각하지 않으셨으면 해요, $n 님.$B$B그러니까 제 말은, 당신은 하늘경비대 내에서 무척 유명해지셨고... 음... 저와 같이 지위가 낮은 경비대원하고 어울리진 않으실 테니까 말이죠.$B$B그저 같이 놀고 싶으시다거나 가오리를 좀 더 생포해 오고자 하시면, 전 항상 여기 있을 테니 언제든지 들러주세요!$B$B보고 싶을 거예요...', `FemaleText_loc4`='希望你没把我当做马屁精之类的家伙，$n。$B$B我的意思是，我知道你在天空卫队享有很高的声誉，嗯……我想你大概不会愿意和我这样地位卑微的工人呆在一起。$B$B不过，如果你想出去逛逛，或是一起捕捉以太鳐什么的，随时来找我！我等着你。$B$B我真想你……', `FemaleText_loc5`='我希望你不要覺得我是個好高騖遠，或是差不多的人，$n。$B$B我是說，我知道你現在在禦天者真的很受歡迎，好吧...我相信你不會想要跟一個像我這樣低下的苦工約會。$B$B不過，要是你任何時候想要就出去走走，或想管牧更多的刺脊，隨時都可以來!我會在這裡。$B$B我會想你...', `FemaleText_loc7`='Espero que no creas que soy una acosadora ni nada de eso, $n.$B$BQuiero decir... sé que ahora eres muy $gfamoso:famosa; entre la Guardia del cielo y eso y bien... Estoy segura de que no querrás andar con una humilde currante como yo.$B$B¡Pero si alguna vez quieres quedar para estar juntos o domar algunas rayas más, pásate por aquí! Estaré aquí.$B$BTe echo de menos...' WHERE `ID`=21588;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 유물은 정말 거대한 신비가 아닐 수 없다. 주기적으로 그 유물에 대한 조사를 게을리하지 않으면 그들의 능력에 대한 더 나은 이해를 하게 될 거다.', `MaleText_loc4`='这些圣物伟大而神秘。如果能系统地研究它们，或许就能揭示它们蕴藏的真正力量。', `MaleText_loc5`='這些聖物真是一個偉大的謎團。或許藉由常態性的研究，你將會對他們的效用得到一個更好的評價。', `MaleText_loc7`='Las reliquias son, en verdad, un gran misterio. Quizá si las estudias de forma regular puedas adquirir un mejor conocimiento de sus capacidades.' WHERE `ID`=21589;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<얘기를 시작하는 추알로르의 왼쪽 머리>$B$B우리 도우려고 하는 당신의 열의 매우 호소적이고... $B$B<말을 맺는 추알로르의 오른쪽 머리>$B$B... 우리가 당신의 노력에 매우 감사하고 있다는 거 알아줬으면 한다!', `MaleText_loc4`='<库洛尔的左脑袋在说话。>$B$B你如此热情地帮助我们，真是令人感动呀……$B$B<他的右脑袋作着结论。>$B$B……因此我们想让你知道，我们非常感谢你所做的一切！', `MaleText_loc5`='<裘阿洛左邊的頭開口說，>$B$B我們發現你的熱心幫助我們很動人...$b$b<他右邊的頭作結尾，>$B$B...而我們想要你知道我們真的很感謝你的幫忙!', `MaleText_loc7`='<La cabeza izquierda de Chu''a''lor dice, >$B$B¡Tu entusiasmo nos parece de lo más interesante...$B$B<Su cabeza derecha termina,>...y queremos que sepas que realmente apreciamos tus esfuerzos!' WHERE `ID`=21590;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오그릴라의 확고한 친구분, 철은 단단하지 않답니다. 우리와 같은 생물체가 더 강인하지요. 철은 그걸 휘두르는 자의 힘을 얻지요. 휘두르는 자의 힘을 얻는 건 좋지만... 확고한 친구분께 뭘 도와드리면 될까요?', `MaleText_loc4`='尊贵的英雄，钢铁远没有血肉之躯来得强壮。唯有持有者才能令钢铸武器的效力发挥到极致。嗯，不说这些了……我们能帮你什么忙吗？', `MaleText_loc5`='鋼鐵並不強壯，高貴的人，肉身比較強壯。鋼鐵的力量來自於揮舞的人。不過那夠了...我們要怎麼幫忙你呢，高貴的人?', `MaleText_loc7`='El acero no es fuerte, exaltado, la carne lo es más. El acero toma su fuerza de quien lo empuña. Pero basta de eso... ¿Cómo podemos ayudarte, exaltado?' WHERE `ID`=21591;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳 오그릴라 주위에서 당신의 이름이 경외의 대상이 되고 있군그래.$B$B<섬뜩한 눈길로 쏘아보는 추알로르의 왼쪽 눈>$B$B계속 잘하도록 해, $n!', `MaleText_loc4`='人们已经开始对你表示崇敬了。$B$B<库洛尔的左眼凝视着你，折射出冷漠的目光。>$B$B继续加油，$n！', `MaleText_loc5`='你的名字開始在這周遭受到敬重了。$B$B<裘阿洛的左眼以它冷酷的眼神盯著你。>$B$B保持良好的工作表現，$n!', `MaleText_loc7`='Tu nombre comienza a ser venerado por aquí.$B$B<El ojo izquierdo de Chu''a''lor te perfora con su pétrea mirada.>$B$BSigue así, $n.' WHERE `ID`=21592;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='처음에는 저 아래 오우거들의 $g왕:여왕;이 되더니 이젠 이곳 오그릴라의 오우거들 사이에서 고귀한 신분이 되었구나.$B$B$r 종족에서는 전례가 없는 일인데 당신이 그 살아 있는 증거로군. $n, 고맙다. 그리고 우리 모두가 당신에게 진 빚은 진정 보답할 길이 없을 것이야!', `MaleText_loc4`='首先你成为了刀锋山食人魔的$g国王:女王;，接着又赢得了奥格瑞拉食人魔的尊敬。$B$B从来没有哪个$r能取得这样的成就，你简直是活生生的例证。$n，谢谢你，我们欠你的永远都无法偿还！', `MaleText_loc5`='首先你變成了下面那些巨魔的$g國王:女王;，現在你已經受到身在歐格利拉當中我們的敬重。$B$B這是從未發生在一位$r的身上，現在，你就是一個活生生的證明。我謝謝你，$n，我們都欠你一份永遠都無法回報的人情!', `MaleText_loc7`='Primero te convertiste en $grey:reina; de los ogros de abajo y ahora te has engrandecido entre nosotros, en Ogri''la.$B$BEsto era inimaginable para $gun:una:r; $r y, sin embargo, tú eres la prueba viviente. ¡Te lo agradezco, $n y todos nosotros te debemos más de lo que jamás podremos pagarte!' WHERE `ID`=21593;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='인생에서 당신이 믿을 수 있는 몇 가지가 있지요. 강철이 바로 그렇답니다.', `MaleText_loc4`='一生当中能信任的东西可不多。钢铁就是其中之一。', `MaleText_loc5`='有幾個東西是你生命中可以相信的。鋼鐵，你可以相信。', `MaleText_loc7`='Hay pocas cosas en esta vida en las que puedas confiar. El acero es una de ellas.' WHERE `ID`=21594;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 오우거들을 도와주는 당신과 같은 $r|1이;가; 있어서 영광이오. 당신이 있어주어 우리의 더 나은 미래의 희망이 살아 있는 것이라오.$B$B이제 몇 가지 골칫거리만 날려 버리면 되긴 하지만... 당신 정말 우리 아들 녀석들 중에 한 녀석을 원하지 않소?', `MaleText_loc4`='我们食人魔能得到你这样一位$r的帮助，我感到十分荣幸。你让我们重新拥有了一个光明的未来。$B$B现在，我们只需要处理掉这些剩下来的头疼事务就好了。不过，你确认不想要领养一个我们的孩子吗？', `MaleText_loc5`='可以擁有一個像你這樣的$r幫助我們巨魔真是榮幸。你保有了我們對於更好未來的希望。$B$B現在只要我們能夠擺脫這些頭痛的話。你確定你不要我們其中一個孩子嗎?', `MaleText_loc7`='Es un honor que $gun:una; $r como tú nos ayude a los ogros. Mantienes viva nuestra esperanza de un futuro mejor.$B$BSi tan solo pudiéramos librarnos de estos dolores de cabeza... ¿Estás seguro de que no quieres uno de nuestros hijos?' WHERE `ID`=21595;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강철을 만드는 손에 비하면 강철은 아무것도 아니죠.', `MaleText_loc4`='和钢铁比起来，铸钢者的双手是不是更厉害呢？', `MaleText_loc5`='鋼鐵跟製造它的手相比是什麼呢?', `MaleText_loc7`='¿Qué es el acero comparado con la mano que le da forma?' WHERE `ID`=21596;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우릴 이렇게나 도와주시다니 정말 대단하군. 당신이 아니었다면 우린 벌써 악마들에게 당했거나 검은용군단에 의해 바삭하게 익혀졌을 거라고 감히 말하고 싶소!$B$B이건 다른 얘긴데 우리 아이들을 싸게 팔 의향이 있다고 내가 말하지 않았소? 관심 없단 말이오?', `MaleText_loc4`='你给予了我们这么多帮助，真是令我们感到惊讶。要是没有你，我们肯定早就被恶魔或是黑龙给撵出了家园！$B$B顺便说一句，我们提过想要将一个孩子便宜卖给你，对吧？不要？你不感兴趣吗？', `MaleText_loc5`='你這麼的幫助我們真是令人吃驚。我們敢說要是沒有你的話，我們已經被惡魔攻陷了，或是被黑龍軍團烤成脆片了!$B$B另外，我們真的說過要賣你我們其中一個孩子，便宜，對吧?不要，沒興趣嗎?', `MaleText_loc7`='Es increíble cuanto nos has ayudado. Nos atreveríamos decir que si no fuese por ti, ya nos habrían arrasado los demonios o el Vuelo Negro nos habría chamuscado.$B$BPor otra parte, mencionamos que te venderíamos a uno de nuestros hijos a buen precio, ¿verdad? ¿No te interesa?' WHERE `ID`=21597;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳 오그릴라에서는 강철의 수수께끼를 심사숙고할 시간이 있답니다. 시간이 충분한 건 좋지만... 무엇을 도와드릴까요?', `MaleText_loc4`='在奥格瑞拉这里，我们有足够的时间来沉思有关钢铁的秘密。不过这都是另一个话题了……有什么我可以为你效劳的吗？', `MaleText_loc5`='在歐格利拉這我們有時間去思考有關鋼鐵的謎題。不過夠了，我們可以幫你什麼嗎?', `MaleText_loc7`='Aquí en Ogri''la tenemos tiempo para considerar el acertijo del acero. Pero basta de eso, ¿cómo podemos ayudar?' WHERE `ID`=21598;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모양을 잡아야 할 철이 있으신가요?', `MaleText_loc4`='需要我为你铸造钢铁武器吗？', `MaleText_loc5`='你有需要製做的鋼鐵嗎?', `MaleText_loc7`='¿Tienes acero que necesite ser moldeado?' WHERE `ID`=21599;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 가족들을 보호해 주려고 한 많은 일에 어떻게 고마움을 표현해야 할지 모르겠군.$B$B그리고 전에 우리 아이들을 팔겠다고 말한 건 농담이란 거 알고 있지 않소? 정말 농담이라오... 그럼에도 몇 가지 골칫거리가 있을 거라는 건 눈치채고 있소이다.$B$B아들아, 계속 그럴 거니?!', `MaleText_loc4`='$n，你慷慨地帮助我们，使我们一家子过得其乐融融，我们真不知道要怎么感谢你才好。 $B$B嗯，我们之前开玩笑说要把其中一个小孩卖给你，你没有当真吧？我们真的是在开玩笑呃……虽然这群小子不断地制造麻烦。$B$B嘿，你们就不能安静点吗？！', `MaleText_loc5`='我們怎麼感謝都不足以表達對於你保護我的家庭所做的每一件事，$n。$B$B還有，你真的了解我們之前說要賣一個孩子給你是在開玩笑嗎?不，真的...雖然我們真的感覺到有一對以上的頭痛要來了。$B$B小夥子，冷靜點，你會嗎?!', `MaleText_loc7`='No podemos agradecerte lo suficiente todo lo que has hecho para proteger a nuestra familia, $n.$B$BY te das cuenta de que bromeábamos con lo de venderte a uno de nuestros hijos, ¿verdad? No, en serio... aunque podemos sentir que vamos a tener un par de jaquecas más.$B$B¡Júnior, ¿quieres estarte quieto?!' WHERE `ID`=21600;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 작은 $n 좋아지기 시작했다! 악마들 추방하는 일 정말 잘했다!', `MaleText_loc4`='我们有点开始喜欢小$n了！你好厉害！连恶魔也能打赢！', `MaleText_loc5`='我們開始喜歡你這個小東西了，$n!你揍那些惡魔，幹得好!', `MaleText_loc7`='¡Pequeño $n empezar a gustarnos! ¡Tú machacar demonios muy bien!' WHERE `ID`=21601;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가크 작은 $r $n 좋아한다. 작은 친구 큰 악마 처치해서 작은 악마들 무섭게 만들었다!!$B$B<환하게 웃는 가크의 양쪽 머리>', `MaleText_loc4`='甘克喜欢小$r$n。你杀死了大恶魔，让所有小恶魔们感到害怕！$B$B<甘克的两个脑袋都在对着你笑。>', `MaleText_loc5`='賈克喜歡小，$r$n。你殺了那個那大惡魔;嚇跑了那些小惡魔!$B$B<賈克的兩個頭同時對你露齒而笑。>', `MaleText_loc7`='A Gahk gustar $gpequeño:pequeña; $r $n. ¡Tú matar gran demonio y asustar a todos los demonios pequeños!$B$B<Las dos cabezas de Gahk te sonríen.>' WHERE `ID`=21602;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 여기서 $n 매일 본다!$B$B추알로르 작은 $r 우리의 영웅이라고 그랬다!$B$B$n 이제 우리 오우거들 중에 몇 좋아한다. 그저 가크만 헷갈린다. 우리 오우거들 좋아하려면 $n 더 커야 해서 가크는 당황스럽다!', `MaleText_loc4`='我们永远欢迎你来这里！$B$B库洛尔说$r是我们的英雄！$B$B$n现在就像是我们食人魔的一员了。但是，甘克搞糊涂了，因为他觉得$n需要再长大点。', `MaleText_loc5`='我們確定常常在這看到你!$B$B裘阿洛說小$r是我們的$g英雄:英雌;!$B$B$n現在就是我們巨魔的一員了。不過，賈克覺得困惑，因為$n需要變更大點才行!', `MaleText_loc7`='¡Nosotros ahora verte por aquí todo el tiempo! $B$B¡Chu''a''lor decir que $gpequeño:pequeña:r; $r ser $gnuestro héroe:nuestra heroína;!$B$B$n ser de los nuestros ahora. ¡Pero Gahk estar confundido porque $n necesitar ser más grande para eso!' WHERE `ID`=21603;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 오그릴라의 확고한 친구께 어떤 걸 드리면 될까요?', `MaleText_loc4`='我们能为你做些什么吗，尊贵的$G兄弟:姐妹;？', `MaleText_loc5`='我們能為你準備什麼呢，我們高貴的$G兄弟:姐妹;?', `MaleText_loc7`='¿Qué podemos conseguirte, $Gnuestro engrandecido hermano:nuestra engrandecida hermana;?' WHERE `ID`=21604;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 지원을 해 드리면 될까요?', `MaleText_loc4`='我们能帮你什么忙吗？', `MaleText_loc5`='我們要怎麼變成有幫助的人呢?', `MaleText_loc7`='¿Cómo podemos ayudarte?' WHERE `ID`=21605;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필멸의 존재여, 후회하게 될 것이다! 이 레스히드론은 다시 돌아올 것이란 말이다... 내 복수를 해 주마!', `MaleText_loc4`='你会为此后悔的，凡人！雷萨赫尔顿会回来的……我要复仇！', `MaleText_loc5`='你將會為此後悔的，凡人!雷斯海卓恩將會回來...我將會復仇!', `MaleText_loc7`='¡Te arrepentirás de esto, mortal! Reth''hedron volverá... ¡obtendré mi venganza!' WHERE `ID`=21606;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='새매가 까마귀석의 위치 추적에 성공한 이후로, 엘라이라가 무척 먼 거리에 내 목소리를 전하기 위해 다른 새매 녀석을 훈련시키고 있답니다. 그가 당신이 서판에서 밝혀진 새 영혼을 조사하면서 우리와 교신하는데 도움을 줄 겁니다.', `FemaleText_loc4`='麻鹰被证明在搜索乌鸦石方面是非常有天分的，因此观察者艾莱亚训练了另一只麻鹰远程传递我的声音。当你研究显现在石板上鸟的灵魂时，它可以帮助我们进行联络！', `FemaleText_loc5`='由於雀鷹已經成功的在搜尋烏鴉石一事上展現了牠的能力，看守者艾雷雅已經著手訓練另一隻雀鷹，可以幫我傳遞遠方的消息。他能夠在你調查石板上出現的鳥靈時幫助我們保持連繫!', `FemaleText_loc7`='Ya que los gavilanes han tenido tanto éxito al buscar las piedras del Cuervo, la vigía Elaira ha entrenado otro para que lleve mi voz a gran distancia. ¡Puede ayudarnos a comunicarnos mientras tú investigas a los espíritus pájaro de los que habla la tablilla!' WHERE `ID`=21607;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오그릴라의 우호적인 친구여, 어떻게 도와드릴까요?', `MaleText_loc4`='尊敬的$G兄弟:姐妹;，我们能帮你什么忙吗？', `MaleText_loc5`='光榮的$G兄弟:姐妹;，我要怎麼幫你呢?', `MaleText_loc7`='$GHonrado hermano:Honrada hermana;, ¿Cómo podemos ayudarte?' WHERE `ID`=21608;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요, 친구! 무엇을 도와 드릴까요?', `MaleText_loc4`='你好，朋友！我们能帮你什么忙吗？', `MaleText_loc5`='哈囉朋友!我們能為你做點什麼嗎?', `MaleText_loc7`='¡Hola! ¿Qué podemos hacer por ti?' WHERE `ID`=21609;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 상인들은 당신을 도와드리기 위해 있답니다.', `MaleText_loc4`='我们是来帮忙的。', `MaleText_loc5`='我們是前來這裡幫忙的。', `MaleText_loc7`='Estamos aquí para ayudar.' WHERE `ID`=21610;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$r 친구, 이곳 오그릴라에서 유명해졌군. 잘 된 일이야.$B$B하지만 말이야. 그 하나밖에 없는 머리로 우쭐대진 않으리라 믿어도 되겠지? 아, 그리고 악마를 추방하는 일을 계속 도와주리라 믿어도 되겠소?', `MaleText_loc4`='你在这里的知名度已经相当高了，$r。这是件好事。$B$B我相信你不会被溢美之词冲昏了头脑，你会继续帮助我们放逐恶魔的，对吗？', `MaleText_loc5`='你在這裡建立了良好的名聲，$r。恭喜你。$B$B我們相信你不會只把名聲當作唯一該做的事，你還是會協助我們驅逐惡魔吧?', `MaleText_loc7`='Te has labrado una reputación interesante por aquí, $r. Bien por ti.$B$BEsperamos que no se te suba a tu única cabeza y que sigas ayudándonos a desterrar demonios.' WHERE `ID`=21611;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 당신의 사심 없음에 겸허해 지는군. 여태까지 우리가 좀 거만했긴 하지만, 우리의 태도를 변하게 할 수 있었던 것이 바로 당신의 그 모범적인 행동이라는 걸 여실히 보여줬소.$B$B우리의 감사의 마음을 전하고 악마의 괴철로 기지에 맞서는 우리의 투쟁을 계속 지원해 주었으면 하오.', `MaleText_loc4`='你的无私让我们感到无地自容，$n。先前，我们确实有点自以为是，但是你让我们彻底改变了态度。$B$B谢谢你，希望你会继续帮助我们对抗铸魔营地。', `MaleText_loc5`='在你的無私之下我們顯得卑微，$n。要是過去我們好像有點自傲，請了解是因為你所以我們才能夠改善我們的態度。$B$B我們很感謝你，並希望你會繼續協助我們進行與煉冶場的抗爭。', `MaleText_loc7`='Tu altruismo nos hace sentirnos humildes, $n. Si en el pasado parecimos un poco vanidosos, ten en cuenta que hemos cambiado de actitud siguiendo tu ejemplo.$B$BTe lo agradecemos y esperamos que sigas ayudándonos en nuestra lucha contra los campamentos Forja.' WHERE `ID`=21612;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 가서 수정괴철로를 재조정해라.', `MaleText_loc4`='到这里来重新调整水晶熔炉。', `MaleText_loc5`='到那裡去並重新對準水晶熔爐。', `MaleText_loc7`='Ve allí y recoloca la forja de cristal.' WHERE `ID`=21613;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 나설 때가 되었다! 저 괴철로가 거의 한 시간 동안 고장 나 있다고!', `MaleText_loc4`='你总算露面了！那座熔炉已经坏掉快一小时了！', `MaleText_loc5`='該是你出面的時候了!這個熔爐已經爆炸快一個小時了!', `MaleText_loc7`='¡Ya era hora de que llegaras! ¡Esa forja lleva casi una hora estropeada!' WHERE `ID`=21614;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청한 녀석, 도대체 뭘 한 거야?', `MaleText_loc4`='蠢货，你们都干了些什么？', `MaleText_loc5`='你們做了什麼，你們這些笨蛋?', `MaleText_loc7`='¿Que habéis hecho insensatos?' WHERE `ID`=21615;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쓸모없는 녀석! 너의 무지함에 왜 우리가 고생해야만 하지?', `MaleText_loc4`='白痴！为什么我们必须忍受你们的愚蠢？', `MaleText_loc5`='無能的笨蛋!為什麼我們一定要忍受你們的愚蠢?', `MaleText_loc7`='¡Tontos incompetentes! ¿Por qué tengo que sufrir su estupidez?' WHERE `ID`=21616;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번 실패로 네 노예 생활이 일 년 더 길어질 것이야!', `MaleText_loc4`='你可耻地败了！我要延长你一年的奴役期限！', `MaleText_loc5`='我會因為你的失敗多加你一年的刑期!', `MaleText_loc7`='¡Por tu fracaso, añadiré otro año más a tu periodo de esclavitud!' WHERE `ID`=21617;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳 오그릴라에서 우리와 함께 즐겁게 지내고 계신가요?$B$B밤낮으로 우리 오우거들이 만드는 많은 물품이 있답니다. 당신과 같은 우리의 최고 멋쟁이 친구분께 판매할 엄선된 물품을 준비해 놓고 있는 것이지요!$B$B자, 임무를 수행하시고 이 산맥을 더 평화롭게 만드시는 동안, 때때로 들러서 저희가 보유한 물품을 둘러보도록 하세요.$B$B당신의 임무에 행운이 따르길 바랍니다.', `MaleText_loc4`='你在奥格瑞拉过得很愉快吧？$B$B我们有许多手工打造的好东西。我们挑选出最好的货物，准备出售给你这样酷毙了的客人！$B$B嗯，在你外出执行任务、确保奥格瑞拉安全的同时，有空的时候可以顺路过来看看我们出售的货物。$B$B朋友，祝你好运。', `MaleText_loc5`='你在歐格利拉這裡與我們共渡了一段美好時光嗎?$B$B我們有很多巨魔不分日夜製作的東西。我們將最好的留下來賣給像你這樣優秀的客人!$B$B所以，當你離開去做你的事，並讓山脈變成一個更安全的地方，請常常停下來看看我們有什麼。$B$B祝你出外好運，$g老兄:小妞;。', `MaleText_loc7`='¿Lo estás pasando bien con nosotros en Ogri''la?$B$BNuestros ogros están fabricando muchas cosas, noche y día. ¡Guardamos las mejores para vendérselas a nuestros invitados más enrollados, como tú!$B$BAsí que mientras andes por ahí haciendo lo que haces y convirtiendo las montañas en un lugar más seguro, pásate por aquí de vez en cuando para ver qué tenemos.$B$BSuerte ahí fuera $ghombre:mujer;.' WHERE `ID`=21618;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 대원은 모두 들어라! 우리는 미개한 바시르 악마들을 기습할 것이다. 우리의 임무는 아주 간단하다. 그들의 새로운 기술을 정확히 분석해 낼 때까지 최대한 그 지역을 지켜내는 것이다.', `MaleText_loc4`='游侠们，听好了！让那些野蛮的巴什伊尔恶魔尝点苦头。我们的任务很简单，尽可能地坚守这片区域，获取他们的新技术的准确读数。', `MaleText_loc5`='巡邏員，聽好!我們準備好去迎面痛擊那些野蠻的貝許爾惡魔。我們的任務很簡單。盡量長久佔據這個地區好準確了解他們的新技術。', `MaleText_loc7`='¡Escuchad Forestales! Estamos listos para sembrar el dolor en los demonios paganos Bash’ir. Nuestra misión es simple: tomad el área tiempo suficiente para obtener informes exactos de su nueva tecnología.' WHERE `ID`=21619;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 우리의 적을 너무 과소평가 해서는 안 된다. 우리는 그들을 침략한다. 우리가 적들에게 싸움을 걸고 있다. 그들을 궁지로 몰아넣으면 그들 역시 반격할 것이다.', `MaleText_loc4`='别低估我们的敌人。我们是主动挑衅的入侵者，他们已经被逼得无路可走了。这帮家伙必定会奋起反抗的。', `MaleText_loc5`='但是不要低估我們的敵人。我們入侵他們。我們對他們挑起了戰爭。我們將他們逼入了角落，他們將會反擊。', `MaleText_loc7`='Pero no subestiméis a nuestros enemigos. Los estamos invadiendo. Estamos llevando la lucha ante ellos. Los tenemos acorralados en una esquina y ellos se defenderán.' WHERE `ID`=21620;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 하늘경비대다! 우리는 이렇게 훈련받지 않았는가! 우리는 후퇴를 모른다, 우리는 항복을 모른다. 설사 그것이 죽음일지라도 우리는 임무를 완수할 것이다! 우리는 필요한 정보를 지켜낼 것이고 만일 지켜내지 못한다면 우리는 싸움터에서 죽을 것이다.', `MaleText_loc4`='我们是天空卫士！这就是我们受训的目的。绝不退缩，绝不投降。哪怕明知是去送死，我们也会毫不犹豫地执行使命！宁愿战死沙场，也不会透露那份情报。', `MaleText_loc5`='我們是禦天者!這就是我們受的訓練。我們不會撤退，我們不會投降。我們將會完成我們的任務，就算它代表著死亡!我們將會取得資料，否則我們將會戰死沙場。', `MaleText_loc7`='¡Somos la Guardia del cielo! Esto es para lo que nos han entrenado. No abandonamos y no nos rendimos. ¡Llevaremos nuestra misión a cabo aunque nos cueste la vida! Conseguiremos esa información o moriremos en el campo de batalla.' WHERE `ID`=21621;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='질문이 있으면 해도 좋다!', `MaleText_loc4`='还有谁对此有疑问吗？', `MaleText_loc5`='還有人有問題嗎?', `MaleText_loc7`='¿Alguien tiene preguntas?' WHERE `ID`=21622;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 곧 알게 된다!', `MaleText_loc4`='你很快就能查明真相！', `MaleText_loc5`='你就是要去找出答案!', `MaleText_loc7`='Estás a punto de averiguarlo.' WHERE `ID`=21623;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하늘경비대여, ''하늘로'' 올라라!!', `MaleText_loc4`='天空卫队游侠，准备起飞！！', `MaleText_loc5`='禦天者巡邏員，坐上坐騎!!', `MaleText_loc7`='¡Forestales Guardia del cielo, MONTAD!' WHERE `ID`=21624;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알고 싶은 건 딱 하나입니다! 적들은 어디에 있습니까?', `MaleText_loc4`='朋友，我只想知道一件事，他们在哪里。', `MaleText_loc5`='看吧小子，我只需要知道一件事，就是他們在哪裡。', `MaleText_loc7`='Mira tío, solo necesito saber una cosa: ¿dónde están?', `FemaleText_loc1`='알고 싶은 건 딱 하나입니다! 적들은 어디에 있습니까?', `FemaleText_loc4`='朋友，我只想知道一件事，他们在哪里。', `FemaleText_loc5`='看吧小子，我只需要知道一件事，就是他們在哪裡。', `FemaleText_loc7`='Mira tío, solo necesito saber una cosa: ¿dónde están?' WHERE `ID`=21625;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원하는 게 뭡니까?', `MaleText_loc4`='你想要什么？', `MaleText_loc5`='你要得是什麼?', `MaleText_loc7`='¿Qué quieres?' WHERE `ID`=21626;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 발사스의 사절입니다. 그가 완전무결한 비전 정수를 가져오라고 절 보냈습니다.', `MaleText_loc4`='我是巴塔斯的特使。他派我来收集一份完美的奥术精华。', `MaleText_loc5`='我是巴薩斯的使者。他派我來收集完美的秘法精華。', `MaleText_loc7`='Vengo de parte de Balthas. Me envía a recoger algunas esencias Arcanas inmaculadas.', `FemaleText_loc1`='난 발사스의 사절입니다. 그가 완전무결한 비전 정수를 가져오라고 절 보냈습니다.', `FemaleText_loc4`='我是巴塔斯的特使。他派我来收集一份完美的奥术精华。', `FemaleText_loc5`='我是巴薩斯的使者。他派我來收集完美的秘法精華。', `FemaleText_loc7`='Vengo de parte de Balthas. Me envía a recoger algunas esencias Arcanas inmaculadas.' WHERE `ID`=21627;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조나스, 물건을 보고 싶습니다.', `MaleText_loc4`='霍纳斯，让我看看你出售的货物。', `MaleText_loc5`='喬那斯，讓我看看你可以提供什麼。', `MaleText_loc7`='Jho’nass, muéstrame lo que ofreces.', `FemaleText_loc1`='조나스, 물건을 보고 싶습니다.', `FemaleText_loc4`='霍纳斯，让我看看你出售的货物。', `FemaleText_loc5`='喬那斯，讓我看看你可以提供什麼。', `FemaleText_loc7`='Jho’nass, muéstrame lo que ofreces.' WHERE `ID`=21628;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='켈러 사령관님, 전 데스윙 혈족 망토가 싫습니다.', `MaleText_loc4`='天空指挥官凯勒，我不喜欢这件死亡之翼血脉披风。', `MaleText_loc5`='天空指揮官凱勒，我不喜歡我的死翼披風。', `MaleText_loc7`='Comandante del Cielo Keller, no me gusta mi capa del linaje de Alamuerte.', `FemaleText_loc1`='켈러 사령관님, 전 데스윙 혈족 망토가 싫어요.', `FemaleText_loc4`='天空指挥官凯勒，我不喜欢这件死亡之翼血脉披风。', `FemaleText_loc5`='天空指揮官凱勒，我不喜歡我的死翼披風。', `FemaleText_loc7`='Comandante del Cielo Keller, no me gusta mi capa del linaje de Alamuerte.' WHERE `ID`=21629;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싫다고? 하지만 당신은 이 망토를 얻으려고 무척 열심히 일했잖소! 뭐, 어쨌거나 친구... 원한다면 적당한 가격으로 그 망토를 사들이도록 하지.$B$B망토 하나당 에펙시스 수정 하나로 교환하면 어떻겠소?', `MaleText_loc4`='你不喜欢这件披风？但是你费了这么大力气才搞到手呢！嗯，好吧，如果你愿意的话，我就以适当的价格收购它。$B$B用一块埃匹希斯水晶做为交换怎么样？', `MaleText_loc5`='你不喜歡?但是你很努力工作才得到它的!好吧，$g小夥子:小姑娘;，如果你想要的話，我會出個好價格從你手中買過來。$B$B你覺得用一片頂尖水晶交換你的披風聽起來如何?', `MaleText_loc7`='¿No te gusta? ¡Pero has trabajado muy duro para conseguirla! Bueno $Gchico:chica;, si quieres te la quitaré de las manos por un precio módico.$B$B¿Qué te parece el cambio de tu capa por un cristal de ápices?' WHERE `ID`=21630;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<경례하는 대군주 모르고르>', `MaleText_loc4`='<莫格霍尔大王向你敬礼。>', `MaleText_loc5`='<霸主莫格行禮。>', `MaleText_loc7`='<El señor supremo Mor’ghor saluda.>' WHERE `ID`=21631;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='군사들이여, 이 변종 오크들에게 점술가 길드의 분노를 보여주거라!', `MaleText_loc4`='防御部队，让这帮渣滓尝尝占星者的愤怒！', `MaleText_loc5`='防衛者，讓這些雜種們見識一下占卜者之怒吧!', `MaleText_loc7`='¡Defensores, mostrad a estos chuchos la furia de los Arúspices!' WHERE `ID`=21632;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 준비하라. 한 놈도 살려 두지 마라!', `MaleText_loc4`='士兵们，奋勇作战吧！不要对敌人手下留情！', `MaleText_loc5`='要有自信，士兵。不要對他們寬恕。', `MaleText_loc7`='¡Firmes soldados. No mostréis piedad!' WHERE `ID`=21633;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<테로크를 소환합니다.>', `MaleText_loc4`='<召唤泰罗克。>', `MaleText_loc5`='<召喚泰洛克。>', `MaleText_loc7`='<Invoca a Terokk.>', `FemaleText_loc1`='<테로크를 소환합니다.>', `FemaleText_loc4`='<召唤泰罗克。>', `FemaleText_loc5`='<召喚泰洛克。>', `FemaleText_loc7`='<Invoca a Terokk.>' WHERE `ID`=21634;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋습니다. 그렇게 하지요.', `MaleText_loc4`='听起来不错嘛。', `MaleText_loc5`='那聽起來對我很好。', `MaleText_loc7`='Me parece bien.', `FemaleText_loc1`='좋아요. 그렇게 하죠.', `FemaleText_loc4`='听起来不错嘛。', `FemaleText_loc5`='那聽起來對我很好。', `FemaleText_loc7`='Me parece bien.' WHERE `ID`=21635;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말이오? 한번 교환하면 다시 바꿔주지 않을 것이오.', `MaleText_loc4`='你确定吗，朋友？成交之后一概不予退换哦。', `MaleText_loc5`='你確定嗎，$g小夥子:小姑娘;?一旦我賣給你，我就不會再買回了。', `MaleText_loc7`='¿Estás $gseguro chico:segura chica;? Una vez que comerciemos, no la vas a recuperar.' WHERE `ID`=21636;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말이고 말고요. 데스윙 혈족 망토를 에펙시스 수정으로 교환하고 싶습니다.', `MaleText_loc4`='是的，我确定。我想用这件死亡之翼血脉披风换取一块埃匹希斯水晶。', `MaleText_loc5`='是，我確定。我想要用我的死翼披風交換一個頂尖水晶。', `MaleText_loc7`='Sí, estoy seguro. Deseo cambiar mi capa del linaje de Alamuerte por un cristal de ápices.', `FemaleText_loc1`='정말이고 말고요. 데스윙 혈족 망토를 에펙시스 수정으로 교환하고 싶어요.', `FemaleText_loc4`='是的，我确定。我想用这件死亡之翼血脉披风换取一块埃匹希斯水晶。', `FemaleText_loc5`='是，我確定。我想要用我的死翼披風交換一個頂尖水晶。', `FemaleText_loc7`='Sí, estoy segura. Deseo cambiar mi capa del linaje de Alamuerte por un cristal de ápices.' WHERE `ID`=21637;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋소, 이 망토를 만들 수 있는 하늘경비대원을 찾을 수 있으리라 보오.$B$B여기 당신에게 줄 에펙시스 수정이오. 망토를 받았을 때보단 기분이 나아졌으면 좋겠군그래.', `MaleText_loc4`='很好，我相信别的天空卫士一定能用得着这件披风的。$B$B给，这是你的埃匹希斯水晶。希望它能令你满意。', `MaleText_loc5`='很好，我相信我會在外面找到一位禦天者來好好使用這個披風。$B$B這是你的頂尖水晶。我希望這會比那個披風更讓你覺得快樂點。', `MaleText_loc7`='Bien, seguro que encontraré a algún Guardia del cielo que pueda usar la capa.$B$BAquí tienes tu cristal de ápices. Espero que te haga más feliz que la capa.' WHERE `ID`=21638;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 나를 이리로 불러냈지? 아직은 때가 아니야... 내 힘이 아직 충분하지 않단 말이다! 이놈들... 이 대가는 충분히 치르게 해 주마!', `MaleText_loc4`='是谁把我召唤到了这个世界？星阵尚未排列成线……我的力量还没有完全恢复！你会为此付出代价的！', `MaleText_loc5`='是誰將我召喚到這個世界的?星宿還未相連...我的力量將會消失!你要為此付出代價!', `MaleText_loc7`='¿Quien me llama a este mundo? Las estrellas aún no se han alineado...¡me fallan los poderes! ¡Pagarás por esto!' WHERE `ID`=21639;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='평화가 가득하기를. 아직 그대들이 나설 때가 되지 않았다. 이곳에 남아 어떤 일이 전개될지 보도록 하라.', `MaleText_loc4`='安静点，孩子，还轮不到你呢。你就呆在这里，见证即将发生的事吧。', `MaleText_loc5`='冷靜，孩子，你的時候還未到。留在這裡面對將要出現的事物吧。', `MaleText_loc7`='Calma, $g chico:chica; tu hora aún no ha llegado. Quédate aquí y observa lo que se va a desvelar.' WHERE `ID`=21640;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기 $n 씨, 당신이 멋진 공훈을 세움에 따라서 구입할 수 있는 물품을 만들 거랍니다. 인과응보나 무엇인가랑 같은 것이죠.$B$B그러니 바로 북쪽에 있는 우리 하늘경비대 친구들을 포함해서 당신이 할 수 있는 일에 도움을 주시기 바랍니다.$B$B굉장하군요... 고맙습니다!', `MaleText_loc4`='嘿，$n，只要你继续努力的话，我们出售的货物就任你挑选。这有点像是因果报应的说法吧。$B$B那么，请尽力帮助我们以及北边的天空卫队吧。$B$B嗯……谢谢你！', `MaleText_loc5`='嘿，記住，$n，當你完成許多好事，我們會讓你可以買到這件東西的。這就像是因果循環，或是其他的。$B$B所以，盡量到處幫忙，包括我們位於北邊的禦天者盟友。$B$B太棒了...謝謝!', `MaleText_loc7`='Oye $n, recuerda que dejaremos que compres estás cosas a medida que vayas realizando buenas acciones. Es como el karma, o algo así.$B$BAsí que ayuda a quién puedas, incluidos nuestros amigos de la Guardia del cielo en el norte.$B$B¡Genial... gracias!' WHERE `ID`=21641;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='추알로르가 줄곧 당신에 대해서 좋은 얘기를 해 주더군요, $n 씨. 원하신다면 두서너개의 특별한 오우거 맥주를 팔고 있으니 사시는 게 어떨까요?$B$B그 맥주는 완전 맛있거든요!', `MaleText_loc4`='库洛尔在我面前为你说了一堆好话，$n。怎么样，我们还出售一些特别的食人魔美酒哩。$B$B它们都是非常美味的！', `MaleText_loc5`='裘阿洛已經說過有過你的功績了，$n。如果你要的話，我們有販賣幾種特別的巨魔酒。$B$B真的很好喝喔!', `MaleText_loc7`='Chu''a''lor ha estado hablando bien de ti, $n. Si te interesan, tenemos un par de brebajes especiales ogros en venta.$B$B¡Están muy ricos!' WHERE `ID`=21642;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 당신은 우리 오그릴라에 매우 우호적인 형태의 무언가가 되신 거 같군요. 보아하니 모두가 당신에 대한 얘기를 하는 것 같습니다? 정말 잘 되었어요.$B$B당신이 관심이 가는 물품이 있는지 보도록 합시다. 우린 좋은 물건이 많이 있으니까요.', `MaleText_loc4`='你在这里很受尊敬，朋友。好像每个人都在说起你。真酷。$B$B请随便看看吧，说不定有你感兴趣的东西呢。我们有很多上等货。', `MaleText_loc5`='你在我們這裡就像個偶像，$g老兄:小姐;。幾乎每個人都在談論你，真行。$B$B看看有沒有什麼商品是你有興趣的，我們有很多好東西。', `MaleText_loc7`='Eres una especie de personaje venerado por aquí $Ghombre:nena;. Parece que todo el mundo habla sobre ti. Eso mola.$B$BVeamos si tenemos a la venta algo que te interese. Tenemos muchas cosas bonitas.' WHERE `ID`=21643;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐라 말씀드려야 할지 모르겠네요. 우리의 친구님, 우리가 가진 어떤 물품이든 구입하실 수 있답니다!$B$B어서 구입하세요!', `MaleText_loc4`='还有什么好说的呢，$n？伙计，你可以随意选购店里的商品！$B$B对极了！', `MaleText_loc5`='我們能說什麼呢，$n?$G帥哥:美女;，所有我們店裡的東西你都可以購買喔!$B$B就是現在!', `MaleText_loc7`='¿Qué podemos decir, $n? $GTío:tía;, puedes comprar cualquier cosa que tengamos en la tienda.$B$B¡Adelante!' WHERE `ID`=21644;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그거 위험한 생각의 가지로구려. 어떤 일이 정말 잘못되었다면, 소리도르미 님께서 첫 번째로 아시게 될 것이오.', `MaleText_loc4`='那是个危险的想法。要是真的出了差错，索莉多米肯定会第一个察觉的。', `MaleText_loc5`='這是個危險的想法。要是真的出了什麼差錯，索芮朵蜜會是第一個知道的。', `MaleText_loc7`='Esa es una línea de pensamiento peligrosa. Si realmente ocurriera algo, Soridormi sería la primera en saberlo.' WHERE `ID`=21645;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무한의용군단에 대한 소문이 사실이라고 보세요? 그 소문이... 정통하다는 사실을 알아챘거든요.', `FemaleText_loc4`='你觉得关于永恒龙族的传言是真的吗？我觉得听上去……挺耳熟的。', `FemaleText_loc5`='你覺得有關恆龍軍團的謠傳是真的嗎?我察覺到一種...熟悉感。', `FemaleText_loc7`='¿Crees que los rumores sobre el Vuelo Infinito son ciertos? Lo he sentido... la familiaridad.' WHERE `ID`=21646;
