UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만두게. 자네 같은 자들과는 볼일이 없네.', `MaleText_loc4`='滚开！你别想从我这里得到任何东西。', `MaleText_loc5`='停止。我沒有東西要給像你這樣的人。', `MaleText_loc7`='Vete. No tengo nada para ti.', `FemaleText_loc1`='그만두게. 자네 같은 자들과는 볼일이 없네.', `FemaleText_loc4`='滚开！你别想从我这里得到任何东西。', `FemaleText_loc5`='停止。我沒有東西要給像你這樣的人。', `FemaleText_loc7`='Vete. No tengo nada para ti.' WHERE `ID`=21668;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 방법이 뭐가 잘못된 것인지 가르쳐주고 싶구나.', `MaleText_loc4`='我可以帮你纠正你的错误。', `MaleText_loc5`='我期望能夠教訓你錯誤的做法。', `MaleText_loc7`='Estoy deseando enseñarte en qué te has equivocado.' WHERE `ID`=21669;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선발대원이 나올 줄 알았느냐?', `MaleText_loc4`='你在等我的先驱者吗？', `MaleText_loc5`='你在等待我的先驅者嗎?', `MaleText_loc7`='¿Esperabas a uno de mis heraldos?' WHERE `ID`=21670;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희의 가죽을 시장에 가져다 팔아야겠다. 뭐, 그다지 쓸모 있어 보이지는 않지만 말이야.', `MaleText_loc4`='或许我可以剥下你的皮，然后拿到市场上叫卖。不过还是算了吧，你这身臭皮囊看上去就不值几个钱。', `MaleText_loc5`='也許我可以公開告訴大家你的藏身處。然後再度的，可能就失去價值了。', `MaleText_loc7`='Quizá pueda vender tu pellejo en el mercado. Claro que, es probable que no tenga ningún valor.' WHERE `ID`=21671;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 모듈을 찾아 제어기를 가동시켰지? 어쨌거나 다시 그 짓을 하지는 못할 것이다.', `MaleText_loc4`='你是在什么地方找到激活控制器的模块的？不过无所谓，反正你没有机会再来捣乱了。', `MaleText_loc5`='你究竟是在哪裡找到這個模組來啟動控制器的?沒關係，你將再也沒辦法那麼做。', `MaleText_loc7`='¿Y dónde encontraste el modulo para activar ese controlador? Es igual, no volverás a hacerlo.' WHERE `ID`=21672;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님은 바쁘시지만, 나라면 놀아줄 시간이 있다!', `MaleText_loc4`='主人很忙，我倒是有空陪你玩玩！', `MaleText_loc5`='主人很忙，不過我有得是時間現身跟你玩!', `MaleText_loc7`='El maestro está ocupado, pero yo tenog tiempo para salir a jugar.' WHERE `ID`=21673;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바시르 님이 못 오셔서 서운해 하셨다. 대신 너희를 잘 달래 주라고 나를 보내셨지.', `MaleText_loc4`='巴什伊尔对他不能与你交手表示遗憾，不过他派我来舒缓你失望的情绪。', `MaleText_loc5`='貝許爾很抱歉他無法親自動手，不過他派我單獨前來減輕你的失望。', `MaleText_loc7`='Bash’ir envía sus excusas por no haber podido venir, pero me envía a mi para apaciguar tu decepción.' WHERE `ID`=21674;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 지금 누구랑 어울리고 있는지 알고 있나, $n? 너와 네 친구들에게 내가 직접 가르쳐주마.', `MaleText_loc4`='你知道你正在干什么吗，$n？过来，让我好好教育一下你和你的朋友们。', `MaleText_loc5`='你知道你正在跟誰交手嗎，$n?現在，讓我來教育一下你及你的朋友們。', `MaleText_loc7`='¿Sabes con qué estás jugando, $n? Venid, permitidme que os enseñe a ti y tus amigos.' WHERE `ID`=21675;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님이 명하신 다른 할 일이 있다. 빨리 돌아가야 하니 간단히 끝내자.', `MaleText_loc4`='我还要为主人打点别的事务。我们来个速战速决怎么样，这样我就能做自己的事情了。', `MaleText_loc5`='我還有其他要為主人去做的事。讓我們快速的進行，這樣我才能回去他們身邊。', `MaleText_loc7`='Tengo otros asuntos que atender para el maestro. Acabemos con esto rápido para que pueda volver a ellos.' WHERE `ID`=21676;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 잡동사니 부대의 지원만 믿고 가속장치를 가동시켰단 말이냐?', `MaleText_loc4`='你靠这个东拼西凑而成的破玩意启动了加速器？', `MaleText_loc5`='你只用了這個雜亂的裝置來幫你啟動催化器嗎?', `MaleText_loc7`='¿Has activado el acelerador con el único apoyo de este abigarrado ensamblaje?' WHERE `ID`=21677;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 내 충고를 하나 하지. 꼬리를 집어넣고 저 아래 안전한 골짜기로 날아가라.', `MaleText_loc4`='$n，让我给你点建议：夹起尾巴滚回山谷中的安全地带吧。', `MaleText_loc5`='$n，讓我建議你一些事:收好尾巴，飛回下面這個安全的山谷。', `MaleText_loc7`='Permite que te dé un consejo, $n. Recoge la cola y vuela de nuevo a los valles seguros de allá abajo.' WHERE `ID`=21678;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 내게서 소모된 물건이라도 가져갈 만큼 강하다고 생각하나?', `MaleText_loc4`='你觉得自己本事够大，能从我手里抢走东西吗？', `MaleText_loc5`='你以為你夠$g勇敢:迷人;到從我手中拿走這個枯竭的物品嗎?', `MaleText_loc7`='¿Crees que eres lo suficientemente $ghombre:mujer; para arrebatarme el objeto reducido?' WHERE `ID`=21679;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청이들은 많은데, 처치할 시간이 부족하구나!', `MaleText_loc4`='蠢货太多，时间太少！', `MaleText_loc5`='笨蛋真多，時間真少!', `MaleText_loc7`='¡Tantos insensatos y tan poco tiempo!' WHERE `ID`=21680;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1과;와; 그 친구들이라... 참 독특하구나. 오래 걸리지 않게 해주마.', `MaleText_loc4`='哟，一位$c和$g他:她;的朋友……真是有趣。这应该不会花太长时间的。', `MaleText_loc5`='$c和$g他的:她的;朋友們...好怪。這應該不會花費太久時間。', `MaleText_loc7`='$gUn:Una; $c y sus amigos... ¡qué pintoresco! Esto no debería tardar mucho.' WHERE `ID`=21681;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신은 가장 간단한 마법부여에 대해서도 다 익히지 못했군요. 돌로소스와 대화하셔서 마법부여에 대해서 더 익히고 오시기 바랍니다.', `FemaleText_loc4`='你连最简单的附魔技能都没有学会呢。请你先去向多洛索斯请教吧。', `FemaleText_loc5`='你還沒通曉最簡單的附魔技巧。麻煩你，請去麻煩多洛索斯。', `FemaleText_loc7`='Aún no dominas ni el más simple de los encantamientos. Por favor, molesta a Dolothos en mí lugar.' WHERE `ID`=21682;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='울지 마라, $n. 곧 끝날 것이다. 약속하건대 네 시체에는 침을 뱉지 않으마.', `MaleText_loc4`='别哭啊，$n。很快就会结束了。我保证不往你的尸体上吐口水。', `MaleText_loc5`='不要哭，$n。很快就會結束了。我發誓不會在你的屍體上吐口水。', `MaleText_loc7`='No llores $n. Pronto habrá terminado todo. Prometo no escupir sobre tu cadáver.' WHERE `ID`=21683;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마법부여에 대해서 제가 알려드릴 수 있는 것외에 당신의 기술을 더 발전시키고자 하신다면, 좋은 옷가지들을 훼손시켜야 할 겁니다. 돌발톱 산맥에 있는 해바위 야영지 뒤의 언덕에 있는 하가스가 마법부여의 갖가지 신비에 관한 비밀을 풀었으니 그를 만나보시기 바랍니다.', `FemaleText_loc4`='我已经没有什么新知识可以教给你了，如果你想要进一步提升自己的技能，就需要学会分解这些精美衣物的方法。赫加斯是位精通附魔学的大师，他就隐居在石爪山脉烈日石居背后的山上，去向赫加斯讨教吧。', `FemaleText_loc5`='如果你想要在我教導你之前提升你的訓練的話，你會需要弄髒那些乾淨的衣服。赫加斯已經解開了我們職業上一連串的謎題，並隱身在石爪山脈的烈日石居後面的丘陵上。', `FemaleText_loc7`='Si buscas avanzar tu instrucción más allá de lo que yo te puedo enseñar, necesitarás mancillar esas buenas ropas. Hgarth ha desbloqueado ciertos misterios en nuestra profesión y se oculta tras el Refugio Roca del Sol en la Sierra Espolón.' WHERE `ID`=21684;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용아귀 부족을 막아야 한다...', `MaleText_loc4`='必须阻止龙喉氏族……', `MaleText_loc5`='必須制止龍喉...', `MaleText_loc7`='Los Faucedraco deben ser detenidos...' WHERE `ID`=21685;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오늘은 어떤 장사의 비밀을 파헤치시는데 도움을 드리면 될까요?', `FemaleText_loc4`='今天你想从我这里学到什么新知识呢？', `FemaleText_loc5`='今天我可以幫助你解開什麼專業疑問呢?', `FemaleText_loc7`='¿Qué misterios del comercio puedo ayudarte a desvelar hoy?' WHERE `ID`=21686;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 어처구니없는 바느질은 저기 있는 탈마르가 확인하는 게 가장 좋겠군요. 적절하게 가죽을 경화하는 방법에 대해서 이해하신 후에 오시는 게 좋겠습니다. 당신이 한 작업은 형편없어 보이거든요.', `MaleText_loc4`='可笑的家伙，你最好向那边的塔尔玛讨教几招，在你学会如何正确地加工皮革之后再回来找我吧。还有，你制作出来的皮革真难闻。', `MaleText_loc5`='你最好讓塔瑪爾看一下你那好笑的縫法;也許，在你了解如何正確保存一張皮革後回來找我。你的成品聞起來很臭。', `MaleText_loc7`='Talmar observará mejor tus irrisorias puntadas. Vuelve cuando sepas como curar un pellejo. Tu trabajo apesta.', `FemaleText_loc1`='당신의 어처구니없는 바느질은 저기 있는 탈마르가 확인하는 게 가장 좋겠군요. 적절하게 가죽을 경화하는 방법에 대해서 이해하신 후에 오시는 게 좋겠습니다. 당신이 한 작업은 형편없어 보이거든요.', `FemaleText_loc4`='可笑的家伙，你最好向那边的塔尔玛讨教几招，在你学会如何正确地加工皮革之后再回来找我吧。还有，你制作出来的皮革真难闻。', `FemaleText_loc5`='你最好讓塔瑪爾看一下你那好笑的縫法;也許，在你了解如何正確保存一張皮革後回來找我。你的成品聞起來很臭。', `FemaleText_loc7`='Talmar observará mejor tus irrisorias puntadas. Vuelve cuando sepas como curar un pellejo. Tu trabajo apesta.' WHERE `ID`=21687;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 네 녀석이 추측하는 것보다 더 오랜 세월을 살았다. 존경심을 좀 가져보지 그러나!', `MaleText_loc4`='我比你想象的要年长得多，给我放尊重点！', `MaleText_loc5`='我比你所想的還老。尊重一點!', `MaleText_loc7`='Soy más viejo de lo que puedas imaginar. ¡Muéstrame algo de respeto!' WHERE `ID`=21688;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 녀석의 살점을 삼켜버리면, 불타는 군단 또한 네 동족을 삼키리라!', `MaleText_loc4`='我要吞噬你的肉体！同样，燃烧军团也将毁灭你的族人！', `MaleText_loc5`='就像我可以毀掉你的人一樣，燃燒軍團也可以毀掉你的人民!', `MaleText_loc7`='¡La Legión Ardiente consumirá a tu gente como yo consumiré tu carne!' WHERE `ID`=21689;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날마다 가죽을 입고 지내면서 가혹한 운명의 화살을 맞아 자신이 가죽이 되는 타우렌보다 더 좋은 가죽세공사가 있을 수 있을까요? 당신이 냄새만 좀 참을 수 있다면 썬더 블러프의 우나가 저보다 더 많은 걸 가르쳐드릴 겁니다.', `MaleText_loc4`='说起制革，有谁能比得上整天披着一身好皮的牛头人呢？要知道，哪怕他们遭遇不测，也能从自己身上剥下优质的皮货来。如果你能忍受恶臭的话，就去雷霆崖找犹纳吧，她可以教你更多关于制造皮革的知识。', `MaleText_loc5`='有什麼會比一個天天生活在其中，即使她遇到不幸的事還是可以親自製出優良毛皮的毛皮工作者更好的老師?雷霆崖的猶納比我更能教導你更多的事，只要你能夠忍受惡臭的話。', `MaleText_loc7`='¿Quién mejor para enseñarte a trabajar el cuero que alguien que vive rodeada de él todo el día y podría fabricarse una piel si se enfrentara a un final desafortunado? Una, en la Cima del Trueno, puede enseñarte a hacerlo, si puedes soportar el olor.', `FemaleText_loc1`='날마다 가죽을 입고 지내면서 가혹한 운명의 화살을 맞아 자신이 가죽이 되는 타우렌보다 더 좋은 가죽세공사가 있을 수 있을까요? 당신이 냄새만 좀 참을 수 있다면 썬더 블러프의 우나가 저보다 더 많은 걸 가르쳐드릴 겁니다.', `FemaleText_loc4`='说起制革，有谁能比得上整天披着一身好皮的牛头人呢？要知道，哪怕他们遭遇不测，也能从自己身上剥下优质的皮货来。如果你能忍受恶臭的话，就去雷霆崖找犹纳吧，她可以教你更多关于制造皮革的知识。', `FemaleText_loc5`='有什麼會比一個天天生活在其中，即使她遇到不幸的事還是可以親自製出優良毛皮的毛皮工作者更好的老師?雷霆崖的猶納比我更能教導你更多的事，只要你能夠忍受惡臭的話。', `FemaleText_loc7`='¿Quién mejor para enseñarte a trabajar el cuero que alguien que vive rodeada de él todo el día y podría fabricarse una piel si se enfrentara a un final desafortunado? Una, en la Cima del Trueno, puede enseñarte a hacerlo, si puedes soportar el olor.' WHERE `ID`=21690;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 어서 오세요. 이번만이라도 가죽을 잘 준비하셨다면, 쓸모 있는 물건을 어떻게 만드는지 알려드리도록 하지요.', `MaleText_loc4`='过来，过来。要是你已经准备好了上好的皮革，我会让你看看怎么制作有用的物品。', `MaleText_loc5`='來，過來。如果你這一次可以好好的製作你的毛皮，我就會教你如何做作出耐用的物品。', `MaleText_loc7`='Ven, ven. Si has preparado el cuero adecuadamente, te enseñaré a hacer objetos útiles.', `FemaleText_loc1`='아, 어서 오세요. 이번만이라도 가죽을 잘 준비하셨다면, 쓸모 있는 물건을 어떻게 만드는지 알려드리도록 하지요.', `FemaleText_loc4`='过来，过来。要是你已经准备好了上好的皮革，我会让你看看怎么制作有用的物品。', `FemaleText_loc5`='來，過來。如果你這一次可以好好的製作你的毛皮，我就會教你如何做作出耐用的物品。', `FemaleText_loc7`='Ven, ven. Si has preparado el cuero adecuadamente, te enseñaré a hacer objetos útiles.' WHERE `ID`=21691;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 녀석의 목숨을 빨리 끊어 주마, $n.', `MaleText_loc4`='我会让你死个痛快的，$n。', `MaleText_loc5`='我將會快速的殺死你，$n。', `MaleText_loc7`='Haré que tu muerte sea rápida, $n.' WHERE `ID`=21692;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='먼저 미르베돈에게 당신의 기술을 연마해 보는 게 어떠신가요? 그가 기쁘게 기본기에 대해서 알려줄 겁니다.', `MaleText_loc4`='你为什么不先去米尔温多那里磨炼下自己的技术呢？他会很乐意为你传授基础知识的。', `MaleText_loc5`='為什麼你不先去找米弗丹磨練一下你的技巧?他會很高興指導你基本技術的。', `MaleText_loc7`='¿Por qué no vas primero a mejorar tus habilidades con Mirvedon? Te enseñará lo fundamental encantado.' WHERE `ID`=21693;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 녀석이 믿는 신이 누구든 자비를 베풀어 달라고 빌어라. 너에겐 그런 자비조차 없다는 걸 보여줄 테니...', `MaleText_loc4`='让你信奉的神灵来怜悯你吧，因为我是不会对你有哪怕一丝怜悯的。', `MaleText_loc5`='願你相信的神祝福你。我沒什麼可以告訴你了。', `MaleText_loc7`='Que el dios en el que creas tenga piedad de ti, pues de mí ninguna habrás de recibir.' WHERE `ID`=21694;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바다 저편에 진정한 대장장이 기술을 갖춘 사루 스틸퓨리라는 이름을 가진 자에 대해서 들은 적이 있답니다. $c, 부지런히 당신의 기술을 익히고자 한다면 오그리마에 있는 대장간으로 가야할 겁니다. 행운을 빕니다.', `MaleText_loc4`='我听说，海对面有个名叫萨鲁·钢怒的铁匠大师。如果你想要继续提升你的技能，就去奥格瑞玛的铁匠铺找他吧，$c。祝你好运。', `MaleText_loc5`='我聽說海的那一邊有一個技術高超的鐵匠叫薩魯·鋼怒。如果你想要繼續你的專業技巧，這個在奧格瑪的鐵匠鋪就是你要前往的地方，$c。', `MaleText_loc7`='He oído hablar de un herrero realmente hábil, al otro lado del mar, llamado Saru Furiacerada. Si quieres ofrecerle un trato, debes dirigirte a la herrería de Orgrimmar, $c. Buena suerte.' WHERE `ID`=21695;
