UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미안하지만 꼭 배우고 싶다면, 라지아에게 그대의 볼품없는 물약을 조금 보여줘 보시오. 좀 더... 효능 있는 물약을 만들게 되거든 다시 찾아오시오.', `MaleText_loc4`='拜托。如果你一定要这么做的话，还是让拉斯亚来看看你做出的劣等药剂吧。等你能制作……更有效力的药剂之后，再回来找我。', `MaleText_loc5`='拜託。要是你堅持的話，讓洛希亞知道你那沒說服力的小企圖。等你能夠處理更多事的時候回來找我...', `MaleText_loc7`='Por favor. Muéstrale a Razia tus pequeños y débiles brebajes si es necesario. Vuelve a mí cuando puedas manejar asuntos... más potentes.', `FemaleText_loc1`='미안하지만 꼭 배우고 싶다면, 라지아에게 그대의 볼품없는 물약을 조금 보여줘 보시오. 좀 더... 효능 있는 물약을 만들게 되거든 다시 찾아오시오.', `FemaleText_loc4`='拜托。如果你一定要这么做的话，还是让拉斯亚来看看你做出的劣等药剂吧。等你能制作……更有效力的药剂之后，再回来找我。', `FemaleText_loc5`='拜託。要是你堅持的話，讓洛希亞知道你那沒說服力的小企圖。等你能夠處理更多事的時候回來找我...', `FemaleText_loc7`='Por favor. Muéstrale a Razia tus pequeños y débiles brebajes si es necesario. Vuelve a mí cuando puedas manejar asuntos... más potentes.' WHERE `ID`=21700;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영웅적인 업적이로다!', `MaleText_loc4`='华丽的击杀！', `MaleText_loc5`='華麗的擊殺﹗', `MaleText_loc7`='¡Una muerte gloriosa!' WHERE `ID`=21701;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽을 시간이 멀지 않았구나, $n. 최후의 순간을 즐기거라.', `MaleText_loc4`='你们的死期即将到来，$n。尽情享受生命的最后一刻吧。', `MaleText_loc5`='你的死期即將到來，$n。好好品嚐這最後一刻吧。', `MaleText_loc7`='Tu muerte está próxima, $n. Saborea estos últimos momentos.' WHERE `ID`=21702;
