UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너의 악취가 나기에 네가 온 지 알았다, 작은 $n 녀석. 내 횃대가 너의 육신의 마지막 쉼터가 될 게다.', `MaleText_loc4`='我闻到了你浑身散发着的臭气，渺小的$n。在这里，在我的地盘中，你将永远长眠。', `MaleText_loc5`='我由你的臭味來認識你，小$n。這裡，我的巢穴，就是你最後埋葬的地方。', `MaleText_loc7`='Te reconozco por tu peste, pequeño $n. Aquí, en mi refugio, es donde descansarán tus huesos.' WHERE `ID`=21706;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 없애겠다고? 하하하! 너희가 먼저다!', `MaleText_loc4`='你们想要杀了我？你们先死吧！', `MaleText_loc5`='你們想要殺了我?你們先死吧﹗', `MaleText_loc7`='¿Quieren matarme? ¡Ustedes primero!' WHERE `ID`=21707;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='포세이큰이 그런 특이하고 강력한 약물을 만들지, 그렇지 않소? 자신을 태만으로 물들이지 못하기 때문에 그런 것이지, 내 생각은 그렇소. 그대에게는 잘 된 일이오, 언더시티의 허버트 핼시라는 학자가 이미 필요한 연구를 끝마쳤으니, 남은 일은 직접 그를 만나보는 것 뿐이오.', `MaleText_loc4`='被遗忘者配制出的药剂非常强劲，你不觉得吗？我相信，他们以自身为实验品，经历无数次失败才取得了如此伟大的成就。当然你很幸运，赫伯特·哈尔希医生已经完成了所有必要的研究，你只需去拜访他就行了。', `MaleText_loc5`='被遺忘者正在調配著陰險又激烈的混合劑，你不覺得嗎?我相信，這都因為一次失敗的下毒事件。你很幸運，位於幽暗城的赫伯特·哈爾希醫生已經完成了必要的研究;剩下的就是你去拜訪他了。', `MaleText_loc7`='Los renegados elaboran unos brebajes muy fuertes e intrigantes, ¿no crees? Creo que surgen de la incapacidad de envenenarse a uno mismo con fracasos. Por suerte para ti, el doctor Herbert Halsey, en Entrañas, ha llevado a cabo la investigación necesaria. Tan solo falta que le hagas una visita.', `FemaleText_loc1`='포세이큰이 그런 특이하고 강력한 약물을 만들지, 그렇지 않소? 자신을 태만으로 물들이지 못하기 때문에 그런 것이지, 내 생각은 그렇소. 그대에게는 잘 된 일이오, 언더시티의 허버트 핼시라는 학자가 이미 필요한 연구를 끝마쳤으니, 남은 일은 직접 그를 만나보는 것 뿐이오.', `FemaleText_loc4`='被遗忘者配制出的药剂非常强劲，你不觉得吗？我相信，他们以自身为实验品，经历无数次失败才取得了如此伟大的成就。当然你很幸运，赫伯特·哈尔希医生已经完成了所有必要的研究，你只需去拜访他就行了。', `FemaleText_loc5`='被遺忘者正在調配著陰險又激烈的混合劑，你不覺得嗎?我相信，這都因為一次失敗的下毒事件。你很幸運，位於幽暗城的赫伯特·哈爾希醫生已經完成了必要的研究;剩下的就是你去拜訪他了。', `FemaleText_loc7`='Los renegados elaboran unos brebajes muy fuertes e intrigantes, ¿no crees? Creo que surgen de la incapacidad de envenenarse a uno mismo con fracasos. Por suerte para ti, el doctor Herbert Halsey, en Entrañas, ha llevado a cabo la investigación necesaria. Tan solo falta que le hagas una visita.' WHERE `ID`=21709;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천한 것들이 방해를 해 대니 지겹기 짝이 없구나. 드디어 너의 최후가 왔다, $n!', `MaleText_loc4`='我对这些无意义的干扰感到厌烦了。你的死期到了，$n！', `MaleText_loc5`='我厭倦了沒有意義的打擾了。你的死期到了，$n!', `MaleText_loc7`='Me cansan las interrupciones de los insignificantes. ¡Ha llegado tu hora, $n!' WHERE `ID`=21710;
