UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 날 소환한 게냐? 너의 오만함을 그냥 넘어가진 않을 것이다.', `MaleText_loc4`='你竟敢召唤我？傲慢的家伙，你会受到惩罚的。', `MaleText_loc5`='你竟敢召喚我?你的無知將會受到懲罰。', `MaleText_loc7`='¿Cómo osas invocarme? Tu insolencia será castigada.' WHERE `ID`=21721;
