UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 바시르 영지를 급습하여 그들의 수정괴철로를 조사해 볼 계획입니다. 시간이 되면 도와주셔도 좋습니다! 하늘경비대 에테르 기술단은 대략 $4581d 후에 출발합니다.', `MaleText_loc4`='我们正准备对巴什伊尔码头发动一次进攻，来研究他们的水晶熔炉。请你尽力帮助我们！天空卫队以太技师会在$4581d后出发。', `MaleText_loc5`='我們正準備發動對貝許爾平臺的襲擊，好研究他們的水晶熔爐。要是可以的話請幫忙我們!我們的禦天者蒼穹技師將在大概$4581d後離開。', `MaleText_loc7`='Vamos a asaltar el Alto Bash’ir para estudiar su forja de cristal. ¡Ayúdanos si puedes! ¡Nuestro técnico de éter de la Guardia del cielo saldrá en aproximadamente $4581d.' WHERE `ID`=21773;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='쉽게 얻은 건 쉽게 잃는 법.', `FemaleText_loc4`='来得快，去得也快。', `FemaleText_loc5`='來得快，去得也快。', `FemaleText_loc7`='Fácil vienen, fácil se van.' WHERE `ID`=21774;
