UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성스러운 축복의 빛이 이 음산한 전당에 다시 한번 내리쬐리라.', `MaleText_loc4`='圣光会再次照耀这阴暗的大厅……我发誓。', `MaleText_loc5`='聖光會再次照耀這陰暗的大廳...我發誓。', `MaleText_loc7`='La Luz volverá a bendecir estos lúgubres salones... lo juro.' WHERE `ID`=21786;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공격을 멈추지 마시오! 우리 종족에 대한 놈의 저주를 끝내 주시오.', `MaleText_loc4`='继续战斗，朋友们！杀了他，让我的人民摆脱诅咒！', `MaleText_loc5`='繼續作戰，朋友!殺了他 - 終結我同胞身上的詛咒!', `MaleText_loc7`='¡Sigan luchando, amigos! ¡Mátenlo y acaben con la maldición de mi pueblo!' WHERE `ID`=21787;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하시오. 그놈의 눈을 똑바로 봐서는 안 되오!', `MaleText_loc4`='当心他的视线！不要直视他的眼睛！', `MaleText_loc5`='當心他的視線!不要直視他的眼睛!', `MaleText_loc7`='¡Cuidado con su mirada! ¡No le miréis a los ojos!' WHERE `ID`=21788;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리를 본 자는 다 없앤다... 일리단의 귀에 들어가선 안 돼.', `MaleText_loc4`='把所有看到我们的人都杀掉……一定不能让伊利丹得知我们的到来！', `MaleText_loc5`='把所有看到我們的人都殺掉!一定不能讓伊利丹得知我們的到來。', `MaleText_loc7`='Matad a todo el que nos vea... Illidan no debe enterarse.' WHERE `ID`=21789;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금이다, 마이에브! 복수의 한을 풀어라!', `MaleText_loc4`='时机到了，玛维！释放你的怒火吧！', `MaleText_loc5`='就是現在，瑪翼夫!釋放你的憤怒吧!', `MaleText_loc7`='¡Es el momento Maiev! ¡Desata tu cólera!' WHERE `ID`=21790;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 아카마는 그 누구의 종도 아니다!', `MaleText_loc4`='阿卡玛没有主人了。再也没有了。', `MaleText_loc5`='阿卡瑪沒有主人了。再也沒有了。', `MaleText_loc7`='Akama no tiene amo. Ya no.' WHERE `ID`=21791;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='찾았다! 이걸 측정하려면 도움이 필요한데... 신호를 보내 지원을 요청해야겠군!', `FemaleText_loc4`='新发现！我需要帮助才能完成测量……我要给同伴们发出信号！', `FemaleText_loc5`='大發現!我需要人來協助這些測量...我將會傳送信號給我的同事!', `FemaleText_loc7`='¡Un descubrimiento! Necesito ayuda con estas mediciones... ¡enviaré una señal a mi colega!' WHERE `ID`=21792;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='분열기가 수정괴철로에 에너지를 주입시켜 더 많은 정보가 새어 나온다! 적들을 막아라! 새로운 정보가 수집되는 동안 적들을 막아야 한다!', `FemaleText_loc4`='瓦解炮塔使得水晶熔炉充能过度，由此揭示了更多的秘密！给我守住！在我们收集新数据时守住！', `FemaleText_loc5`='干擾器高舉著對準水晶熔爐，並且發現了更多的秘密!保護它們!在我們取得新資料前守住它們!', `FemaleText_loc7`='¡Las torres de interrupción han sobrecargado la forja de cristal y han desvelado más secretos! ¡Contenedlos! ¡Contenedlos mientras obtenemos más datos!' WHERE `ID`=21793;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='드디어! 우리가 찾던 정보를 알아냈다! 하늘경비대는 즉시 모여라. 빨리 이 결과를 가지고 기지로 돌아가야 한다.', `FemaleText_loc4`='终于！我们寻找多时的信息！天空卫队，迅速集合。我们必须立即返回总部，通报这一消息！', `FemaleText_loc5`='終於!這就是我們尋找的資料!禦天者，快點收集。我們一定要快點將我們的發現送回總部!', `FemaleText_loc7`='¡Al fin! ¡La información que buscábamos! Recogedla rápido, Guardia del cielo. ¡Debemos regresar rápido a nuestros cuarteles con la información!' WHERE `ID`=21794;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이것으로 불안정한 혼합물을 만들 수 있다니... 실험할 에펙시스 결정이 부족해!', `MaleText_loc4`='这座熔炉可以制造出不稳定的合剂……要研究合剂的话，我需要一些埃匹希斯碎片！', `MaleText_loc5`='這個熔爐可以製作不穩定化合物...為了研究他們，我需要頂尖裂片!', `MaleText_loc7`='Esta forja puede hacer brebajes inestables ... ¡para estudiarlos necesito fragmentos de ápices!' WHERE `ID`=21795;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 물에서 수정이 엄청나게 성장하는군... 실험할 에펙시스 결정이 부족해!', `MaleText_loc4`='我在这片水域培植这些令人惊异的水晶。我需要更多的埃匹希斯碎片做为催化剂！', `MaleText_loc5`='我正從這些水中培植驚人的水晶。為了催化劑，我必須擁有更多的頂尖裂片!', `MaleText_loc7`='Estoy cultivando unos cristales asombrosos en estas aguas. Para los catalizadores necesito más fragmentos de ápices.' WHERE `ID`=21796;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놀라운 속성이야! 에펙시스 수정이 조금만 더 있으면 수정 정동석으로 무기와 갑옷을 만들 수 있겠어!', `MaleText_loc4`='它的特性真是令人惊讶！给我点埃匹希斯水晶，我可以用它们制成武器和护甲。', `MaleText_loc5`='它的特性實在太驚人了!將頂尖水晶帶來給我，我將會在水晶洞內製造出武器及護甲。', `MaleText_loc7`='¡Sus propiedades son asombrosas! Tráeme cristales de ápices y yo haré armaduras y armas en geodas de cristal.' WHERE `ID`=21797;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이리 오게, $n. 군주님께서 기다리시네.', `MaleText_loc4`='过来，$n。伊利丹大人在等你。', `MaleText_loc5`='過來，$n。怒風大人在等著。', `MaleText_loc7`='Ven, $n. Lord Tempestira espera.' WHERE `ID`=21798;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용아귀 부족의 용사들이여, 모두 모여라! 너희 중 한 용사가 군주가 되었다! 고개를 숙여 경의를 표하라! 너희의 군주이신 $n 님께 존경과 충성을 바치거라!', `MaleText_loc4`='龙喉氏族的勇士们，都聚集过来吧！就在你们中间，一位佼佼者已经晋升为领主了！向$n领主致敬！表达你们的敬意和忠诚吧！', `MaleText_loc5`='龍喉戰士們，集合!你們其中一員已經達到了大領主的官階了!恭敬地鞠躬!對大領主$n表達出你們的尊敬以及效忠!', `MaleText_loc7`='¡Guerreros de los Faucedraco, acérquense! ¡Uno de ustedes ha logrado el rango de Alto Señor! ¡Inclinen la cabeza como reverencia! ¡Muestren su respeto y lealtad al alto señor $n!' WHERE `ID`=21799;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일리단 님께서 곧 도착할 것이네.', `MaleText_loc4`='伊利丹大人很快就来到这里。', `MaleText_loc5`='伊利丹王將會在這裡一小段時間。', `MaleText_loc7`='Lord Illidan estará aquí pronto.' WHERE `ID`=21800;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해골더미에서 악한 기운이 풍겨옵니다. 아라코아들이 아주 최근까지 해골들을 가져다 놓은 것 같아 두렵습니다.

테로크의 적들의 후손을 불러내려면 잃어버린 시간의 두루마리 10개가 필요합니다.', `MaleText_loc4`='这里散发着污秽的恶臭，看来鸦人最近又堆积了新的战利品。

你需要10张迷失卷轴来召唤泰罗卡仇敌的后裔。', `MaleText_loc5`='這個顱骨堆發生骯髒的惡臭。你擔心阿拉卡最近在這骨堆上施加了其他的東西。

你將會需要10個時光流逝卷軸來召喚出泰洛克敵人的後代。', `MaleText_loc7`='La pila de cráneos apesta a insensatez. Temes que los arakkoa hayan añadido algún cráneo a la pila recientemente.

Necesitarás 10 pergaminos perdidos en el Tiempo para invocar a los descendientes de los adversarios de Terokk.' WHERE `ID`=21801;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 일리단 님을 맞이하라!', `MaleText_loc4`='伊利丹大人万岁！', `MaleText_loc5`='伊利丹王萬歲!', `MaleText_loc7`='¡Saludad todos a Lord Illidan!' WHERE `ID`=21802;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일리단 님, 이 오크가 저와 다른 이들이 이야기하던 용아귀 부족의 용사입니다. 이 용사가 우리에게 승리를 가져다줄 것입니다!', `MaleText_loc4`='伊利丹大人，这位就是我和其他人向您提到过的龙喉氏族的英雄。他会引领我们走向胜利！', `MaleText_loc5`='伊利丹王，這就是我和其他人曾經跟您說過的龍喉獸人。他將會帶領著我們獲得勝利!', `MaleText_loc7`='Lord Illidan, este es el Faucedraco del que te hemos hablado. ¡Él nos guiará a la victoria!' WHERE `ID`=21803;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모르고르, 이게 무슨 짓이냐?', `MaleText_loc4`='这是什么意思，莫格霍尔？', `MaleText_loc5`='莫格，這是什麼意思?', `MaleText_loc7`='¿Qué significa esto, Mor’ghor?' WHERE `ID`=21804;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='군주님이시여... 저는 이해를 하지 못하겠습니다. 이 오크는...', `MaleText_loc4`='但是……大人，我不明白。$n……这个兽人曾经为我们……', `MaleText_loc5`='不過...我的王，我不懂。$n...他這個獸人已經...', `MaleText_loc7`='Pero... Mi señor, no lo comprendo. $n... es el orco que ha...' WHERE `ID`=21805;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 해골의 무덤에서 끔찍한 어둠의 기운이 새어 나옵니다.', `MaleText_loc4`='骨堆中弥漫出一股恐怖的黑暗能量。', `MaleText_loc5`='一股恐怖，黑暗的能量從這個顱骨堆中散發出來。', `MaleText_loc7`='Una energía oscura terrible emana de este montón de cráneos.' WHERE `ID`=21806;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='닥쳐라!', `MaleText_loc4`='安静！', `MaleText_loc5`='安靜!', `MaleText_loc7`='¡SILENCIO!' WHERE `ID`=21807;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헛소리 마라, 이 멍청한 녀석. 어리석고 무능한 광대 같으니...', `MaleText_loc4`='你给我闭嘴，白痴。你真是个不可理喻的蠢材……', `MaleText_loc5`='囉嗦的白痴。你這個什麼都不懂的無能小丑...', `MaleText_loc7`='Idiota charlatán. Bufón incomprensiblemente incompetente...' WHERE `ID`=21808;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이자가 네놈의 용사란 말이냐?', `MaleText_loc4`='这就是你所谓的英雄？', `MaleText_loc5`='『這』就是你的英雄?', `MaleText_loc7`='¿ESTO es tu héroe?' WHERE `ID`=21809;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너는 속았다, 바보 같은 녀석.', `MaleText_loc4`='你们被欺骗了，白痴。', `MaleText_loc5`='你被騙了，傻子。', `MaleText_loc7`='Te han engañado, imbécil.' WHERE `ID`=21810;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이... 이번 일 전체가... 위험할 뻔했단 말이다!', `MaleText_loc4`='整个……计划……都被破坏了！', `MaleText_loc5`='這...整個...行動...已經失敗了!', `MaleText_loc7`='¡La... operación... entera... HA SIDO COMPROMETIDA!' WHERE `ID`=21811;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 벌레의 시체를 조각내어 한 시간 내로 내게 가져와라. 만일 실패하거든 죽음보다 더한 고통에 떨게 해 주겠다.', `MaleText_loc4`='我希望立即在神殿内看到这个渣滓的尸块。否则你们就将遭受比死亡更痛苦的命运！', `MaleText_loc5`='我要在一個小時內看見這個小蟲的屍體一片一片地躺在我的居所中。失敗的話你將會遭受比死亡還慘的命運。', `MaleText_loc7`='Espero ver el caparazón de ese insecto hecho pedazos en mi guarida dentro de una hora. Fracasa y tu destino será mucho peor que la muerte.' WHERE `ID`=21812;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 반지를 둔 곳을 잊어버렸습니다.', `MaleText_loc4`='我好像弄丢了我的指环。', `MaleText_loc5`='我好像弄丟了我的戒指。', `MaleText_loc7`='Parece que he perdido mi anillo.', `FemaleText_loc1`='제 반지를 둔 곳을 잊어버렸습니다.', `FemaleText_loc4`='我好像弄丢了我的指环。', `FemaleText_loc5`='我好像弄丟了我的戒指。', `FemaleText_loc7`='Parece que he perdido mi anillo.' WHERE `ID`=21813;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='임무 중에 쓸 물품이 필요하시오?', `MaleText_loc4`='需要战场补给吗？', `MaleText_loc5`='需要補給品嗎?', `MaleText_loc7`='¿Necesitas provisiones apra el campo?' WHERE `ID`=21814;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘은 어떤 물품을 공급해 드리면 되겠소?', `MaleText_loc4`='长官，我能为你提供什么装备吗？', `MaleText_loc5`='先生，今天我能提供你什麼呢?', `MaleText_loc7`='¿Cómo puedo equiparte hoy, señor?' WHERE `ID`=21815;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요청해야 할 물품이 있으시오?', `MaleText_loc4`='需要补给吗？', `MaleText_loc5`='需要補充一些用品嗎?', `MaleText_loc7`='¿Necesitas requisar algunas provisiones?' WHERE `ID`=21816;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나의 군주님이시여.', `MaleText_loc4`='My $g lord : lady;.', `MaleText_loc5`='我的$g閣下:女士;。', `MaleText_loc7`='Mi $gseñor:señora;.', `FemaleText_loc1`='나의 군주님이시여.', `FemaleText_loc4`='My $g lord : lady;.', `FemaleText_loc5`='我的$g閣下:女士;。', `FemaleText_loc7`='Mi $gseñor:señora;.' WHERE `ID`=21817;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에 오시다니 영광입니다.', `MaleText_loc4`='I am honored by your presence, $t lord : lady; $n.', `MaleText_loc5`='你的出現讓我感到很榮幸，$n$t閣下:女士;。', `MaleText_loc7`='Tu presencia me honra, $t señor : señora; $n.', `FemaleText_loc1`='이곳에 오시다니 영광입니다.', `FemaleText_loc4`='I am honored by your presence, $t lord : lady; $n.', `FemaleText_loc5`='你的出現讓我感到很榮幸，$n$t閣下:女士;。', `FemaleText_loc7`='Tu presencia me honra, $t señor : señora; $n.' WHERE `ID`=21818;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보세요, 저기 $n|1이시군요;시군요;!', `MaleText_loc4`='Look, there''s $n!', `MaleText_loc5`='瞧，是$n!', `MaleText_loc7`='¡Mira, ahí está $n!', `FemaleText_loc1`='보세요, 저기 $n|1이시군요;시군요;! 보세요!', `FemaleText_loc4`='Look, there''s $n!', `FemaleText_loc5`='瞧，是$n!', `FemaleText_loc7`='¡Mira, ahí está $n!' WHERE `ID`=21819;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에 오셨으니, 우린 인제 안전하네요.', `MaleText_loc4`='With you here, we''re saved, $n.', `MaleText_loc5`='有你在這，我們就安全了，$n。', `MaleText_loc7`='Contigo aquí, estamos salvados $n.', `FemaleText_loc1`='이곳에 오셨으니, 우린 인제 안전하네요.', `FemaleText_loc4`='With you here, we''re saved, $n.', `FemaleText_loc5`='有你在這，我們就安全了，$n。', `FemaleText_loc7`='Contigo aquí, estamos salvados $n.' WHERE `ID`=21820;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신과 같은 영웅들이 더 많다면 좋겠네요.', `MaleText_loc4`='If only there were more $g heroes : heroines; such as yourself, $n.', `MaleText_loc5`='但願有更多像你這樣的$g英雄:英雌;，$n。', `MaleText_loc7`='Si tan solo existieran más $ghéroes:heroínas; como tú, $n.', `FemaleText_loc1`='당신과 같은 영웅들이 더 많다면 좋겠네요.', `FemaleText_loc4`='If only there were more $g heroes : heroines; such as yourself, $n.', `FemaleText_loc5`='但願有更多像你這樣的$g英雄:英雌;，$n。', `FemaleText_loc7`='Si tan solo existieran más $ghéroes:heroínas; como tú, $n.' WHERE `ID`=21821;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에 얼마간 머물러 주셨으면 좋겠군요. 시간이 되시면 나중에 들러 주십시오.', `MaleText_loc4`='$n, I hope that you''re staying for a while.  Stop by later if you have the time.', `MaleText_loc5`='$n，我希望你可以在這裡待一陣子。要是你有時間的話，稍後停留一下。', `MaleText_loc7`='Espero que te quedes una temporada, $n. Pásate por aquí luego si tienes tiempo.', `FemaleText_loc1`='이곳에 얼마간 머물러 주셨으면 좋겠군요. 시간이 되시면 나중에 들러 주십시오.', `FemaleText_loc4`='$n, I hope that you''re staying for a while.  Stop by later if you have the time.', `FemaleText_loc5`='$n，我希望你可以在這裡待一陣子。要是你有時間的話，稍後停留一下。', `FemaleText_loc7`='Espero que te quedes una temporada, $n. Pásate por aquí luego si tienes tiempo.' WHERE `ID`=21822;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분부대로 하겠습니다, 군주님!', `MaleText_loc4`='遵命，主人。', `MaleText_loc5`='我的王，事情將會完成。', `MaleText_loc7`='Se hará, mi señor.' WHERE `ID`=21823;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 네놈이 모르고르를 속이려고 했단 말이구나, 그렇지? 일리단 님께 가기 전에 살아서는 구경도 못할 고통을 선사해주마. 기꺼이 내가 당한 복수를 해 주지.', `MaleText_loc4`='你胆敢欺骗莫格霍尔！在将你送到伊利丹大人的神殿之前，我要让你尝尝你想都不敢想的痛苦！我要折磨你，享受复仇的乐趣。', `MaleText_loc5`='所以你想讓欺騙莫格，對嗎?在你被傳送至伊利丹王之前，你將會感覺到無法想像的痛苦。而我將會在我自己的報復中取得快感。', `MaleText_loc7`='Pensaste que podrías poner a Mor’ghor en ridículo, ¿eh? Antes de que te lleven ante Lord Illidan, sentirás un dolor que no creías posible. Me tomaré el placer de obtener mi venganza.' WHERE `ID`=21824;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그를 해치지 못할 걸, 모르고르! $n, 서둘러 등에 오르게나!', `MaleText_loc4`='你休想伤害这个孩子，莫格霍尔！$n，快点，爬到我的背上来！', `MaleText_loc5`='你將無法傷害這個$g男孩:女孩;，莫格!快點，$n，爬到我的背上!', `MaleText_loc7`='¡No harás daño $g al chico:a la chica;, Mor’ghor! ¡Rápido $n, súbete a mi espalda!' WHERE `ID`=21825;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새로운 열쇠를 받아야 할 것 같습니다.', `MaleText_loc4`='我好像弄丢了我的钥匙。', `MaleText_loc5`='我好像弄丟了我們鑰匙。', `MaleText_loc7`='Parece que he perdido la llave.', `FemaleText_loc1`='새로운 열쇠를 받아야 할 것 같습니다.', `FemaleText_loc4`='我好像弄丢了我的钥匙。', `FemaleText_loc5`='我好像弄丟了我們鑰匙。', `FemaleText_loc7`='Parece que he perdido la llave.' WHERE `ID`=21826;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장비를 잘 준비하려면 항상 물품을 구입해야 하오.', `MaleText_loc4`='你永远都无法做好万全的准备。', `MaleText_loc5`='你永遠都無法確實準備的。', `MaleText_loc7`='Nunca se está demasiado preparado.' WHERE `ID`=21827;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도착했구려!', `MaleText_loc4`='你来了！', `MaleText_loc5`='你到了!', `MaleText_loc7`='¡Has llegado!' WHERE `ID`=21828;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='만나서 반갑소, 여행자여.', `MaleText_loc4`='你好，旅行者。', `MaleText_loc5`='你好，旅人。', `MaleText_loc7`='¡Saludos $gviajero:viajera;!', `FemaleText_loc1`='만나서 반갑소, 여행자여.', `FemaleText_loc4`='你好，旅行者。', `FemaleText_loc5`='你好，旅人。', `FemaleText_loc7`='¡Saludos $gviajero:viajera;!' WHERE `ID`=21829;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고삐를 잃어버렸습니다. 새로 하나 주실 수 있으신가요?', `MaleText_loc4`='我把缰绳给弄丢了。你能再给我一根吗？', `MaleText_loc5`='我遺失了我們韁繩。你可以給我另外一個嗎?', `MaleText_loc7`='He perdido mis riendas. ¿Puedes conseguirme otras?', `FemaleText_loc1`='고삐를 잃어버렸습니다. 새로 하나 주실 수 있으신가요?', `FemaleText_loc4`='我把缰绳给弄丢了。你能再给我一根吗？', `FemaleText_loc5`='我遺失了我們韁繩。你可以給我另外一個嗎?', `FemaleText_loc7`='He perdido mis riendas. ¿Puedes conseguirme otras?' WHERE `ID`=21830;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희 에테르 기술자와 호위대가 바시르 영지로 출발하고 있습니다. 그들이 임무를 마칠 수 있게 도와주시기 바랍니다!', `MaleText_loc4`='太空卫队以太技师和他的护卫队正在前往巴什伊尔码头的途中。去那里和他们碰面，帮助他们完成任务吧！', `MaleText_loc5`='我們的蒼穹技師和他的護航隊正前往貝許爾平臺。到那去和他們會面並協助他們完成任務!', `MaleText_loc7`='Nuestro técnico de éter de la Guardia del cielo y su compañía se dirigen al Alto Bash’ir. ¡Únete a ellos allí y ayúdales con su misión!' WHERE `ID`=21831;
