UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일리단의 모든 부관들이 죽었습니다, $n. 앞으로 나아갈 길이 열렸으니 준비되셨으면 어서 가십시오.', `MaleText_loc4`='伊利丹的将领已经全部被打败了，$n。如果你准备就绪，就勇敢地前进吧。', `MaleText_loc5`='所有伊利丹的副官都死了，$n。如果你已經準備好，交戰時刻已來臨。', `MaleText_loc7`='Han caído todos lo tenientes de Illidan, $n. Si estas preparado, el camino está despejado.' WHERE `ID`=21877;
