UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비되었으니 지휘의 방으로 안내해 주십시오.', `MaleText_loc4`='我准备好了。带我去命令大厅吧。', `MaleText_loc5`='我準備好了。帶我去指揮之廳。', `MaleText_loc7`='Estoy preparado. Llévame a la Cámara de Mando.', `FemaleText_loc1`='준비되었으니 지휘의 방으로 안내해 주세요.', `FemaleText_loc4`='我准备好了。带我去命令大厅吧。', `FemaleText_loc5`='我準備好了。帶我去指揮之廳。', `FemaleText_loc7`='Estoy preparado. Llévame a la Cámara de Mando.' WHERE `ID`=21879;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일리단의 하인들이 아직도 이 성소를 지키고 있습니다, $n. 그들이 패하면, 내 힘이 이 사원 내부 깊숙한 곳으로 당신을 안내하게 할 겁니다.', `MaleText_loc4`='伊利丹的侍从依然守护着神殿大厅，$n。如果你打败了他们，我就能带你进入神殿的深处。', `MaleText_loc5`='伊利丹的僕人仍在大廳看守著，$n。一旦他們被擊敗，我的能量就能將你送進神廟深處。', `MaleText_loc7`='Los lacayos de Illidan aún vigilan estos salones, $n. Cuando los hayamos derrotado, mis poderes me permitirán adentrarte más en El Templo Oscuro.' WHERE `ID`=21880;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고작 이 오합지졸을 처리하려고 크아레쉬에서 나를 불러냈단 말인가? 믿을 수 없군! 죽을 준비나 해 둬라!', `MaleText_loc4`='他们把我从卡雷什叫过来就是为了对付这群渣滓？真是难以置信！等着收尸吧！', `MaleText_loc5`='凱瑞西要求我處理那群不適應者?真是另人震驚呀!準備收拾他們!', `MaleText_loc7`='¿Me han hecho venir desde K''aresh para lidiar con esta pandilla de inadaptados? ¡Increíble! ¡Preparaos para ser recogidos!' WHERE `ID`=21881;
