UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하, 하늘은 자기를 여기저기 휘젓고 다니는 $n|1을;를; 별로 좋아하지 않는답니다!', `MaleText_loc4`='呵呵，有$n在天空飞翔，我们的敌人就要小心了！', `MaleText_loc5`='嘿，有$n在飛行時天空還真是不太友善!', `MaleText_loc7`='¡Heh, los cielos no son tan amigables desde que $n vuela en ellos!', `FemaleText_loc1`='하하, 하늘은 자기를 여기저기 휘젓고 다니는 $n|1을;를; 별로 좋아하지 않는답니다!', `FemaleText_loc4`='呵呵，有$n在天空飞翔，我们的敌人就要小心了！', `FemaleText_loc5`='嘿，有$n在飛行時天空還真是不太友善!', `FemaleText_loc7`='¡Heh, los cielos no son tan amigables desde que $n vuela en ellos!' WHERE `ID`=21895;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한가지 분명한 것은 $n 님이 이제 풋내기가 아니라는 겁니다!', `MaleText_loc4`='好吧，有件事是肯定的。$n再也不是移动荣誉了！', `MaleText_loc5`='嗯有件事是可以確定的，$n不再是個小角色了!', `MaleText_loc7`='¡Una cosa es segura, $n ya no es una pepita!', `FemaleText_loc1`='한가지 분명한 것은 $n 님이 이제 풋내기가 아니라는 겁니다!', `FemaleText_loc4`='好吧，有件事是肯定的。$n再也不是移动荣誉了！', `FemaleText_loc5`='嗯有件事是可以確定的，$n不再是個小角色了!', `FemaleText_loc7`='¡Una cosa es segura, $n ya no es una pepita!' WHERE `ID`=21896;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님, 가오리 잡는 건 어떻게 되어갑니까? 요즘 꽤 거칠게 굴지요?', `MaleText_loc4`='$n，你的坐骑还撑得住吧？最近情况很艰难吗？', `MaleText_loc5`='$n，你的坐騎怎麼樣了?這幾天那上面不好過吧?', `MaleText_loc7`='$n, ¿qué tal aguanta tu montura? ¿Es duro estar allí arriba estos días?', `FemaleText_loc1`='$n 님, 가오리 잡는 건 어떻게 되어갑니까? 요즘 꽤 거칠게 굴지요?', `FemaleText_loc4`='$n，你的坐骑还撑得住吧？最近情况很艰难吗？', `FemaleText_loc5`='$n，你的坐騎怎麼樣了?這幾天那上面不好過吧?', `FemaleText_loc7`='$n, ¿qué tal aguanta tu montura? ¿Es duro estar allí arriba estos días?' WHERE `ID`=21897;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 이곳에 상주하는 비행사가 아니시군요, $n 님. 어떻게 지내시나요?', `MaleText_loc4`='嗯，这不是我们的常驻飞行员$n吗……最近怎么样啊，王牌飞行员？', `MaleText_loc5`='嗯，多虧了我們常駐的$g飛行男孩:飛行女孩;，$n。進行的怎麼樣了，高手?', `MaleText_loc7`='Vaya, si es $gnuestro:nuestra; piloto residente, $n. ¿Qué tal te va?', `FemaleText_loc1`='아, 이곳에 상주하는 비행사가 아니시군요, $n 님. 어떻게 지내시나요?', `FemaleText_loc4`='嗯，这不是我们的常驻飞行员$n吗……最近怎么样啊，王牌飞行员？', `FemaleText_loc5`='嗯，多虧了我們常駐的$g飛行男孩:飛行女孩;，$n。進行的怎麼樣了，高手?', `FemaleText_loc7`='Vaya, si es $gnuestro:nuestra; piloto residente, $n. ¿Qué tal te va?' WHERE `ID`=21898;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 내 형제들에게 갈 길을 열어 주었다는 게 느껴지는군. 내 형제들과 사원으로의 내 연결은 아직 강하다네. 사원 내부의 더 깊숙한 곳을 탐험하고 싶은가?', `MaleText_loc4`='你已经清除了前路的障碍，离我的同胞又近了一步。我与他们之间，与这座神殿之间仍然有着强烈的羁绊。你愿意继续深入神殿吗？', `MaleText_loc5`='我感覺你為我的盟友殺出一條生路。我與他們及神廟的感應仍然很強烈。你想要再往深處搜索嗎?', `MaleText_loc7`='Siento que has despejado el camino para mis hermanos. Mi conexión con ellos y con el templo aún es fuerte. ¿Quieres adentrarte más?' WHERE `ID`=21899;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 동족들은 얼마 전에 여기 왔답니다. 그들과 나의 연결 고리가 갈수록 희미해져 가고 있습니다. 안쪽에 있는 강력한 존재가 앞으로 나아갈 길을 수호하고 있으니 조심하십시오.', `MaleText_loc4`='不久前，我的同胞还在这里，但是现在我和他们之间的感应却越来越微弱。一个拥有强大力量的生物守护着庭院，阻止了通往神殿深处的道路。', `MaleText_loc5`='我的盟友不久前在這裡。我與他們的感應愈來愈薄弱。一個強大的靈魂在庭院守衛著前方的路。', `MaleText_loc7`='Mis hermanos estuvieron aquí hace poco. Mi conexión con ellos se ha vuelto débil. Una presencia fuerte en el patio vigila el camino frente a nosotros.' WHERE `ID`=21900;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 결사단에게 데려다 주십시오, 올룸.', `MaleText_loc4`='带我去找其他死誓者，奥鲁姆。', `MaleText_loc5`='帶我去找其他的死亡誓言者，歐蘭。', `MaleText_loc7`='Llévame hasta el otro juramorte, Olum.', `FemaleText_loc1`='다른 결사단에게 데려다 주십시오, 올룸.', `FemaleText_loc4`='带我去找其他死誓者，奥鲁姆。', `FemaleText_loc5`='帶我去找其他的死亡誓言者，歐蘭。', `FemaleText_loc7`='Llévame hasta el otro juramorte, Olum.' WHERE `ID`=21901;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 송곳니를 드러내고 날카로운 소리를 내면서 주변을 위협합니다.', `MaleText_loc4`='%s呲着牙发出嘶嘶声，以示威胁。', `MaleText_loc5`='%s對她週糟的人露出她的毒牙並威脅地發出嘶嘶聲。', `MaleText_loc7`='%s descubre sus colmillos y sisea de forma amenazadora a quienes la rodean.' WHERE `ID`=21902;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈들이 카로그를 가두었구나! 박살내주마!', `MaleText_loc4`='你抓住了卡尔洛格！卡尔洛格抽你！', `MaleText_loc5`='你抓住凱羅格!凱羅格就粉碎你!', `MaleText_loc7`='¡Tú capturar Karrog! ¡Karrog machacarte!' WHERE `ID`=21903;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='땅 밑에서 들려오는 소리를 들어봐라! 네 피를 원하고 있다!', `MaleText_loc4`='听！地底传来的声音！他们要啜饮你的鲜血！', `MaleText_loc5`='聽聽大地之下的聲音!他們呼喚著你的血液!', `MaleText_loc7`='¡Escucha las voces de debajo de la tierra! ¡Piden tu sangre!' WHERE `ID`=21904;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바키즈가 위협적으로 당신을 향해 몸을 비틀자, 무서운 바람이 바키즈를 감쌉니다.', `MaleText_loc4`='瓦克奇斯携着狂风朝你恶狠狠地扑过来。', `MaleText_loc5`='當瓦奇茲威脅地對你扭動，狂暴的風包圍著他。', `MaleText_loc7`='Un viento furioso envuelve a Vakkiz mientras se retuerce amenazadoramente hacia ti.' WHERE `ID`=21905;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이야말로 진정 용감한 하늘경비대원입니다, $n. 우리 모두가 당신에게 빚을 졌습니다.', `MaleText_loc4`='你是我们当中最勇敢的骑士，$n。天空卫队感谢你。', `MaleText_loc5`='你是我們最勇敢的成員之一，$n。禦天者所有人都欠你一份人情。', `MaleText_loc7`='Eres uno de los más valientes, $n. Toda la Guardia del cielo está en deuda contigo.' WHERE `ID`=21906;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='테로크를 이 세계로 불러들이지 말아야 해... 그건 미친 짓이야...', `MaleText_loc4`='别……别将泰罗克召唤到我们的世界，$n……那样做……很愚蠢……', `MaleText_loc5`='不要...把泰洛克帶回我們的世界，$n...那會是...瘋狂...', `MaleText_loc7`='No traigas...a Terokk a nuestro mundo $n... Eso sería... una locura...' WHERE `ID`=21907;
