UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠의 단지를 잃어버린 것 같습니다.', `MaleText_loc4`='我好像把黑色骨灰弄丢了。', `MaleText_loc5`='我好像弄丟了我燻黑的骨灰甕。', `MaleText_loc7`='Parece que he perdido mi urna ennegrecida.', `FemaleText_loc1`='어둠의 단지를 잃어버린 것 같습니다.', `FemaleText_loc4`='我好像把黑色骨灰弄丢了。', `FemaleText_loc5`='我好像弄丟了我燻黑的骨灰甕。', `FemaleText_loc7`='Parece que he perdido mi urna ennegrecida.' WHERE `ID`=21909;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='메디브의 메아리!', `MaleText_loc4`='麦迪文的回音作弊了！', `MaleText_loc5`='麥迪文的回音作弊!', `MaleText_loc7`='¡Eco de Medivh hace trampas!' WHERE `ID`=21910;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n에게 주문 시전을 시도합니다.', `MaleText_loc4`='试着对$n施法。', `MaleText_loc5`='試著對$n施法。', `MaleText_loc7`='Intentando lanzar a $n.' WHERE `ID`=21911;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일리단의 부하들을 처치하는데 가장 숙련된 용사들만이 내 물건을 가질 수 있네.$B$B샤타르, 세나리온 원정대, 그리고 알도르 사제회에 확고한 동맹이라면 다시 고려해 보겠네.', `MaleText_loc4`='只有最擅长追捕伊利丹仆从的猎手才能在我这里选购货物。$B$B当你在沙塔尔、塞纳里奥远征队以及奥尔多的声望达到崇拜时，我才会出售货物给你。', `MaleText_loc5`='只有最擅長對付伊利丹爪牙的老練獵人才能看到我的商品。$B$B等你在薩塔，塞納里奧遠征隊和奧多爾的地位到達崇拜，你就會被認為有這樣的資格。', `MaleText_loc7`='Solo los cazadores con más experiencia de entre los esbirros de Illidan tienen acceso a mis mercancías.$B$BSerás considerado digno cuando tu estado con los Sha’tar, Expedición Cenarion y los Aldor sea exaltado.' WHERE `ID`=21912;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일리단의 부하들을 처치하는데 가장 숙련된 용사들만이 내 물건을 가질 수 있소.$B$B샤타르, 세나리온 원정대, 그리고 점술가 길드에 확고한 동맹이라면 다시 고려해 보겠소.', `MaleText_loc4`='只有最擅长追捕伊利丹仆从的猎手才能在我这里选购货物。$B$B当你在沙塔尔、塞纳里奥远征队以及占星者的声望达到崇拜时，我才会出售货物给你。', `MaleText_loc5`='只有最擅長對付伊利丹爪牙的老練獵人才能看到我的商品。$B$B等你在薩塔，塞納里奧遠征隊和占卜者的地位到達崇拜，你就會被認為有這樣的資格。', `MaleText_loc7`='Solo los cazadores con más experiencia de entre los esbirros de Illidan tienen acceso a mis mercancías.$B$BSerás considerado digno cuando tu estado con los Sha’tar, Expedición Cenarion y los Arúspices sea exaltado.' WHERE `ID`=21913;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하시오. 일리단이 자신의 부하 중 가장 강력한 자들에게만 수여하는 징표를 내게 가져오면 내 연금술 물품을 팔아드리겠소.', `MaleText_loc4`='欢迎你，$n。伊利丹将特殊的徽记赐给了他麾下最强大的仆从，替我取回这些徽记，我就让你选购这些炼金商品。', `MaleText_loc5`='歡迎，$n。把伊利丹贈與他最強大爪牙的印記交給我，我就會讓你看看我的鍊金物品。', `MaleText_loc7`='$gBienvenido:Bienvenida;, $n. Tráeme las marcas que Illidan otorga a sus esbirros más poderosos y te permitiré acceder a mis bienes alquímicos.' WHERE `ID`=21914;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바꾸고 싶은 징표가 있습니다.', `MaleText_loc4`='我要兑换徽记。', `MaleText_loc5`='我有印記要贖回。', `MaleText_loc7`='Tengo marcas que canjear.', `FemaleText_loc1`='바꾸고 싶은 징표가 있습니다.', `FemaleText_loc4`='我要兑换徽记。', `FemaleText_loc5`='我有印記要贖回。', `FemaleText_loc7`='Tengo marcas que canjear.' WHERE `ID`=21915;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잿빛혓바닥 수도두건을 잃어버린 것 같습니다.', `MaleText_loc4`='我好像弄丢了灰舌兜帽。', `MaleText_loc5`='我好像把我的灰舌風帽弄丟了。', `MaleText_loc7`='Parece que he perdido mi capucha de Lengua de ceniza.', `FemaleText_loc1`='잿빛혓바닥 수도두건을 잃어버린 것 같습니다.', `FemaleText_loc4`='我好像弄丢了灰舌兜帽。', `FemaleText_loc5`='我好像把我的灰舌風帽弄丟了。', `FemaleText_loc7`='Parece que he perdido mi capucha de Lengua de ceniza.' WHERE `ID`=21916;
