UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 이제 맥주통을 땄습니다! 우리 건배를 하는 게 어떻겠습니까? 간단하게 할 테니 걱정하지 마십시오.', `MaleText_loc4`='酒桶打开了！现在，我来献上祝酒辞。啊，放心，我尽量简短一些。', `MaleText_loc5`='桶子打開了!現在我想要致個詞。別擔心，我會說的又簡短又風趣。', `MaleText_loc7`='¡El barril está abierto! Ahora me gustaría proponer un brindis. No os preocupéis, será corto y agradable.', `FemaleText_loc1`='자, 이제 맥주통을 땄습니다! 우리 건배를 하는 게 어떻겠습니까? 간단하게 할 테니 걱정하지 마십시오.', `FemaleText_loc4`='酒桶打开了！现在，我来献上祝酒辞。啊，放心，我尽量简短一些。', `FemaleText_loc5`='桶子打開了!現在我想要致個詞。別擔心，我會說的又簡短又風趣。', `FemaleText_loc7`='¡El barril está abierto! Ahora me gustaría proponer un brindis. No os preocupéis, será corto y agradable.' WHERE `ID`=21924;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그론과... 불타는 군단... $n 님이 처리해 줄 수 있는 게 없을까요?', `MaleText_loc4`='戈隆……燃烧军团……什么都难不倒你吗，$n？', `MaleText_loc5`='古羅...軍團...沒有什麼是你不能對付的嗎，$n?', `MaleText_loc7`='Los gronn... la Legión... ¿no hay nada con lo que no puedas, $n?' WHERE `ID`=21925;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님이 근처에 있을 땐 수정이 더 달콤한 노래를 부르는군요.', `MaleText_loc4`='$n在附近的话，连水晶簇都会发出美妙的歌声。', `MaleText_loc5`='當$n在附近的時候水晶就會吟唱甜美的歌曲。', `MaleText_loc7`='Los cristales cantan una canción más dulce cuando $n está cerca.' WHERE `ID`=21926;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='듣자하니 용들이 $n에 대한 약간의 얘기만 들려와도 공포에 떤다고 하더군요.', `MaleText_loc4`='听说只要提起$n的名字，就算是龙也会因为恐惧而战栗。', `MaleText_loc5`='我們聽說龍群一聽到$n的名字就害怕的顫抖。', `MaleText_loc7`='Cuentan que los dragones tiemblan de miedo con solo mencionar a $n.' WHERE `ID`=21927;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수정들이 진정으로 $n 님을 교화한 거로군요.', `MaleText_loc4`='水晶启迪了$n。', `MaleText_loc5`='真正的$n已接受水晶啟迪。', `MaleText_loc7`='$n ha sido realmente iluminado por los cristales.' WHERE `ID`=21928;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님! 수정들이 당신을 찬양하며 노래하고 있어요!', `MaleText_loc4`='$n！水晶在赞美你！', `MaleText_loc5`='$n!水晶吟唱著對你的讚美!', `MaleText_loc7`='¡$n! ¡Los cristales cantan tus alabanzas!' WHERE `ID`=21929;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 오우거들이 $n 님에게 신세를 졌군요.', `MaleText_loc4`='我们感谢你，$n。', `MaleText_loc5`='我們欠你一份感激之情$n。', `MaleText_loc7`='¡Te debemos nuestra gratitud $n!' WHERE `ID`=21930;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그론... 불타는 군단... $n|1이;가; 모두 해치웠다!', `MaleText_loc4`='戈隆……燃烧军团……统统不是$n的对手！', `MaleText_loc5`='古羅...軍團...$n全都打敗他們了!', `MaleText_loc7`='¡El Gronn... la Legión... $n machacar a todos!' WHERE `ID`=21931;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='작은 $n 여기 있을 땐 수정들이 더 예쁘게 노래한다.', `MaleText_loc4`='$n在附近的话，连水晶簇都会发出美妙的歌声。', `MaleText_loc5`='那些水晶在$n在這裡時唱了那首美麗的歌曲。', `MaleText_loc7`='Los cristales cantan una canción bonita cuando $n estar aquí.' WHERE `ID`=21932;
