UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님, 우리를 자랑스럽게 하는 하늘경비대의 최고 기수십니다!', `MaleText_loc4`='$n，你是天空卫队最优秀的飞行员！你是我们的骄傲！', `MaleText_loc5`='$n，你是禦天者中最棒的人;是我們的驕傲!', `MaleText_loc7`='¡$n, eres lo mejor de la Guardia del cielo, haz que nos sintamos orgullosos!', `FemaleText_loc1`='$n 님, 우리를 자랑스럽게 하는 하늘경비대의 최고 기수십니다!', `FemaleText_loc4`='$n，你是天空卫队最优秀的飞行员！你是我们的骄傲！', `FemaleText_loc5`='$n，你是禦天者中最棒的人;是我們的驕傲!', `FemaleText_loc7`='¡$n, eres lo mejor de la Guardia del cielo, haz que nos sintamos orgullosos!' WHERE `ID`=21944;
