UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 준 새매 호루라기를 잃어버렸습니다. 새로 하나 주시겠습니까?', `MaleText_loc4`='我弄丢了你给我的麻鹰哨。能再给我一个吗？', `MaleText_loc5`='我弄丟了你給我的雀鷹哨。你能給我一個新的嗎?', `MaleText_loc7`='He perdido el silbato para gavilanes que me diste. ¿Puedes conseguirme otro?', `FemaleText_loc1`='당신이 준 새매 호루라기를 잃어버렸습니다. 새로 하나 주시겠어요?', `FemaleText_loc4`='我弄丢了你给我的麻鹰哨。能再给我一个吗？', `FemaleText_loc5`='我弄丟了你給我的雀鷹哨。你能給我一個新的嗎?', `FemaleText_loc7`='He perdido el silbato para gavilanes que me diste. ¿Puedes conseguirme otro?' WHERE `ID`=21949;
