UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헴, 이 명예로운 축제를 축하하고자 이곳에 많은 분이 모인 광경을 보니 아주 좋군요. 이런 성대한 축하 행렬은 정말 오랜만입니다.', `MaleText_loc4`='你们都聚在这里庆祝这个伟大的节日，真是令人高兴。我很久没见过这么大规模的庆典了。', `MaleText_loc5`='看到你們大家這麼多人在此慶祝這個光榮的慶典真好。如此重大的慶典已經好久不見了。', `MaleText_loc7`='Es genial ver a tantos de ustedes celebrando esta tradicional fiesta. Ya era hora de organizar una fiesta de esta magnitud.', `FemaleText_loc1`='헴, 이 명예로운 축제를 축하하고자 이곳에 많은 분이 모인 광경을 보니 아주 좋군요. 이런 성대한 축하 행렬은 정말 오랜만입니다.', `FemaleText_loc4`='你们都聚在这里庆祝这个伟大的节日，真是令人高兴。我很久没见过这么大规模的庆典了。', `FemaleText_loc5`='看到你們大家這麼多人在此慶祝這個光榮的慶典真好。如此重大的慶典已經好久不見了。', `FemaleText_loc7`='Es genial ver a tantos de ustedes celebrando esta tradicional fiesta. Ya era hora de organizar una fiesta de esta magnitud.' WHERE `ID`=21957;
