UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 이거 참, 내 앞에 산더미처럼 놓인 일거리가 안 보인단 말입니까?', `MaleText_loc4`='你没发现我在这里正忙着吗？', `MaleText_loc5`='你看不出來我這裡有事在忙嗎?', `MaleText_loc7`='¿No ves que tengo trabajo que hacer?', `FemaleText_loc1`='지금 내 앞에 산더미처럼 놓인 일거리가 안 보인단 말인가요?', `FemaleText_loc4`='你没发现我在这里正忙着吗？', `FemaleText_loc5`='你看不出來我這裡有事在忙嗎?', `FemaleText_loc7`='¿No ves que tengo trabajo que hacer?' WHERE `ID`=21967;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가을 축제가 시작되려면 이제 얼마 남지 않았답니다! 좀 있다가 다시 오셔서 저희가 축제 준비를 끝마쳤는지 확인하도록 하시지요.', `MaleText_loc4`='美酒节马上就要开始啦！到时候千万要记得过来看看哦。', `MaleText_loc5`='從現在到啤酒節開始不會很久!晚點回來看看我們是不是完成了。', `MaleText_loc7`='¡No queda mucho para que comience la Fiesta de la Cerveza! Vuelve dentro de un rato a ver si está todo listo.', `FemaleText_loc1`='가을 축제의 시작이 이제 얼마 남지 않았어요! 좀 있다가 다시 오셔서 저희가 축제 준비를 끝마쳤는지 확인하도록 하세요.', `FemaleText_loc4`='美酒节马上就要开始啦！到时候千万要记得过来看看哦。', `FemaleText_loc5`='從現在到啤酒節開始不會很久!晚點回來看看我們是不是完成了。', `FemaleText_loc7`='¡No queda mucho para que comience la Fiesta de la Cerveza! Vuelve dentro de un rato a ver si está todo listo.' WHERE `ID`=21968;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 친구들이 축제 준비를 다 끝낼 때까지 기다릴 수가 없군요. 일을 마치면 쉬면서 축제를 즐길 수 있을 테니까요.', `MaleText_loc4`='真是等不及看到这些准备工作完工了。我们马上就可以开始享受这个节日啦！', `MaleText_loc5`='我無法等到我們完成前置工作。接著我可以放鬆並好好的享受慶典。', `MaleText_loc7`='Qué ganas tengo de que acabemos de organizar esto. Entonces podré relajarme y disfrutar de las celebraciones.', `FemaleText_loc1`='우리 친구들이 축제 준비를 다 끝낼 때까지 기다릴 수가 없어서 죽겠네요. 일을 마치면 쉬면서 축제를 즐길 수 있을 테니까 말이에요.', `FemaleText_loc4`='真是等不及看到这些准备工作完工了。我们马上就可以开始享受这个节日啦！', `FemaleText_loc5`='我無法等到我們完成前置工作。接著我可以放鬆並好好的享受慶典。', `FemaleText_loc7`='Qué ganas tengo de que acabemos de organizar esto. Entonces podré relajarme y disfrutar de las celebraciones.' WHERE `ID`=21969;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가을 축제는 쉬지 않고 계속되는 축제랍니다. 축제를 준비하는 일도 쉬지 않고 계속되고 말입니다!', `MaleText_loc4`='美酒节是一场永不停止的盛宴！不过，准备这场盛宴也是个永无止境的工作……', `MaleText_loc5`='啤酒節是個不間斷的派對。雖然它的前置作業，是不間斷的工作!', `MaleText_loc7`='La Fiesta de la Cerveza es una celebración sin descanso. Prepararla también es trabajo sin descanso.', `FemaleText_loc1`='가을 축제는 쉬지 않고 계속되는 축제지요. 축제를 준비하는 일도 쉬지 않고 계속되고 말이에요!', `FemaleText_loc4`='美酒节是一场永不停止的盛宴！不过，准备这场盛宴也是个永无止境的工作……', `FemaleText_loc5`='啤酒節是個不間斷的派對。雖然它的前置作業，是不間斷的工作!', `FemaleText_loc7`='La Fiesta de la Cerveza es una celebración sin descanso. Prepararla también es trabajo sin descanso.' WHERE `ID`=21970;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 이제 여길 벗어나세나!', `MaleText_loc4`='我们赶紧离开这里！', `MaleText_loc5`='我們逃出這裡吧!', `MaleText_loc7`='¡Salgamos de aquí!' WHERE `ID`=21971;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 갑시다!', `MaleText_loc4`='出发吧！', `MaleText_loc5`='走吧!', `MaleText_loc7`='¡Vamos!', `FemaleText_loc1`='어서 갑시다!', `FemaleText_loc4`='出发吧！', `FemaleText_loc5`='走吧!', `FemaleText_loc7`='¡Vamos!' WHERE `ID`=21972;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크롱크, 충만한 수정 초점에 대해서 얘기해 주십시오.', `MaleText_loc4`='科隆克，能给我解释一下充能的聚焦水晶有什么用吗？', `MaleText_loc5`='克朗克，告訴我有關充能水晶體的事。', `MaleText_loc7`='Kronk, háblame acerca de los focos de cristal cargados.', `FemaleText_loc1`='크롱크, 충만한 수정 초점에 대해서 얘기해 주십시오.', `FemaleText_loc4`='科隆克，能给我解释一下充能的聚焦水晶有什么用吗？', `FemaleText_loc5`='克朗克，告訴我有關充能水晶體的事。', `FemaleText_loc7`='Kronk, háblame acerca de los focos de cristal cargados.' WHERE `ID`=21973;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수정 초점 말이오? 머리가 하나뿐인 당신은 수정 초점이 뭔지 이해하기가 어려울 테니 우리가 친절하게 설명해 주도록 하겠소.$B$B마력이 고갈된 수정 초점과 10개의 에펙시스 결정을 결합하는 간단한 절차만으로 충만한 수정 초점 하나를 만들 수 있다오. 이 충만한 수정 초점은 약간의 치유력이 있으나 사로잡은 악마에게 사용할 수 있다는 점이 더 중요하지.$B$B충만한 수정 초점은 사로잡은 악마에게서 특별한 힘을 나타내게 하는 데 사용할 수 있다는 것이오. 잠시 후면 가크가 지금 설명한 일을 할 수 있는 임무를 당신에게 줄 것이오.', `MaleText_loc4`='聚焦水晶？当然，我会解释清楚的，毕竟，看上去你只具备完全理解这个概念所必需的一半脑力。$B$B首先，通过一个简单的反应，一块耗尽能量的聚焦水晶可以与十块埃匹希斯碎片产生连接，并在反应结束之后转化为一块充能的聚焦水晶。这些充能的聚焦水晶具备某种医疗能力，但更重要的是，它可以与某只被占据的恶魔产生共效，并应用在特殊的地方。$B$B比如说，每块充能的聚焦水晶的都可以使某只被占据的恶魔展现出特殊的力量。不久之后，甘克就会派你去完成一个类似的任务。', `MaleText_loc5`='水晶體?當然，我們會將它解釋得如同你只有一半的智慧可以了解。$B$B一顆能量耗盡的水晶體可用10片頂尖裂片進行簡單的合成，就會製造出一顆充能水晶體。這些充能水晶體擁有一些治療的功效，不過更重要的是他們對於受到控制的惡魔的成效。$B$B你看，充能水晶體可以使一隻受控制的惡魔展現出特別的能量。稍後，賈克將會有一個那樣的任務要你去執行。', `MaleText_loc7`='¿Los focos de cristal? Te lo explicaré, ya que solo tienes la mitad del cerebro necesario para imaginarlo.$B$BUn foco de cristal mermado puede combinarse con diez fragmentos de ápices, creando un foco de cristal cargado. Estos focos cargados tienen propiedades curativas, pero lo más importante es que pueden usarse con los demonios poseídos.$B$BMira, el foco cargado puede usarse para permitir que un demonio poseído presente poderes especiales. Cuando pase algo de tiempo, Gahk tendrá una misión para ti que consistirá en eso.' WHERE `ID`=21974;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수정 초점 말이오? 머리가 하나뿐인 당신은 수정 초점이 뭔지 이해하기가 어려울 테니 우리가 친절하게 설명해 주도록 하겠소.$B$B마력이 고갈된 수정 초점과 10개의 에펙시스 결정을 결합하는 간단한 절차만으로 충만한 수정 초점 하나를 만들 수 있다오. 이 충만한 수정 초점은 약간의 치유력이 있으나 사로잡은 악마에게 사용할 수 있다는 점이 더 중요하지.$B$B충만한 수정 초점은 사로잡은 악마에게서 특별한 힘을 나타내게 하는 데 사용할 수 있다는 것이오. 암흑룬을 하나 지니고 있다면, 가크가 수정 초점에 대해서 당신에게 얘기해 줄 것이오.', `MaleText_loc4`='聚焦水晶？当然，我会解释清楚的，毕竟，看上去你只具备完全理解这个概念所必需的一半脑力。$B$B首先，通过一个简单的反应，一块耗尽能量的聚焦水晶可以与十块埃匹希斯碎片产生连接，并在反应结束之后转化为一块充能的聚焦水晶。这些充能的聚焦水晶具备某种医疗能力，但更重要的是，它可以与某只被占据的恶魔产生共效，并应用在特殊的地方。$B$B比如说，每块充能的聚焦水晶的都可以使某只被占据的恶魔展现出特殊的力量。不久之后，甘克就会派你去完成一个类似的任务。', `MaleText_loc5`='水晶體?當然，我們會將它解釋得如同你只有一半的智慧可以了解。$B$B一顆能量耗盡的水晶體可用10片頂尖裂片進行簡單的合成，就會製造出一顆充能水晶體。這些充能水晶體擁有一些治療的功效，不過更重要的是他們對於受到控制的惡魔的成效。$B$B你看，充能水晶體可以使一隻受控制的惡魔展現出特別的能量。如果你有暗色符文，賈克就會跟你談談有關的事。', `MaleText_loc7`='¿Los focos de cristal? Claro que te lo explicaremos, ya que solo tienes la mitad del cerebro para imaginártelo.$B$BUn foco de cristal mermado puede combinarse con diez fragmentos de ápices mediante un proceso simple que crea un foco de cristal cargado. Estos focos de cristal cargado tienen propiedades curativas, pero lo más importante es su uso con los demonios poseídos.$B$BEl foco de cristal cargado puede usarse para permitir que un demonio poseído muestre poderes especiales. Si tienes una runaoscura, Gahk te hablará acerca de eso.' WHERE `ID`=21975;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이보라고! 내 말 좀 들어봐! 내가 말이지... 중요하게 할 얘기가 있단 말이야! 쉿... 좀 기다려보라고... 꺼억... 내가 무슨 말을 했더라? 배하고 뭐 떠다니는 거였는데... 딸꾹... 맞아! 그러니까 배를 띄우지 말라고... 딸꾹... 그래, 고맙다고... 꺼억...', `MaleText_loc4`='嘿！听着！我有……我有些非常非常重要的事情要说！里看……等等，我要说虾米来着？船和飘在水面上的……对对！不要飘在船上……谢谢里……', `MaleText_loc5`='嘿!聽好!我已經拿到...我有重要的事要說!坎...等等...偶要唆什麼?某種有關船跟飄浮滴素啦...對啦!不要在船上飄...謝謝你啦...', `MaleText_loc7`='¡Hey! ¡Essscuchad! Tengo...algo importante que desirosh! Esstoo... Esperad... ¿Qué esstaba disiendo? Algo ssobre barcosh y flotar... ¡Shí! No flotéish en un barco... Graciash.', `FemaleText_loc1`='이보세요! 내 말 좀 들어봐요! 내가 말이죠... 중요하게 할 얘기가 있다고요! 쉿... 좀 기다려보세... 꺼억... 내가 무슨 말을 했더라? 배하고 뭐 떠다니는 거였는데... 딸꾹... 맞아! 그러니까 배를 띄우지 말라... 딸꾹... 그래, 고맙다는... 꺼억...', `FemaleText_loc4`='嘿！听着！我有……我有些非常非常重要的事情要说！里看……等等，我要说虾米来着？船和飘在水面上的……对对！不要飘在船上……谢谢里……', `FemaleText_loc5`='嘿!聽好!我已經拿到...我有重要的事要說!坎...等等...偶要唆什麼?某種有關船跟飄浮滴素啦...對啦!不要在船上飄...謝謝你啦...', `FemaleText_loc7`='¡Hey! ¡Essscuchad! Tengo...algo importante que desirosh! Esstoo... Esperad... ¿Qué esstaba disiendo? Algo ssobre barcosh y flotar... ¡Shí! No flotéish en un barco... Graciash.' WHERE `ID`=21976;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='딸꾹... 이제 진정으로 화려한 타기 솜씨가 어떤 건지 보게 될 거라고!', `MaleText_loc4`='现债里看到缀厉害的骑术了吧！', `MaleText_loc5`='現在你將會看到真正高超的騎術!', `MaleText_loc7`='¡Ahora verásh a alguien cabalgar bien de verdad!', `FemaleText_loc1`='딸꾹... 이제 진정으로 화려한 타기 솜씨가 어떤 건지 보게 될 거라고요!', `FemaleText_loc4`='现债里看到缀厉害的骑术了吧！', `FemaleText_loc5`='現在你將會看到真正高超的騎術!', `FemaleText_loc7`='¡Ahora verásh a alguien cabalgar bien de verdad!' WHERE `ID`=21977;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번엔 자국이 남겠지... 음, 잠시 여기서 좀 쉬어야겠군.', `MaleText_loc4`='他们会留下标记的……我要先在这里休息片刻。', `MaleText_loc5`='那將會留下紀錄...我只要在這休息一下。', `MaleText_loc7`='Eso dejará una marca... Descansaré un poco aquí.', `FemaleText_loc1`='이번엔 자국이 남겠지... 아, 여기서 잠시 쉬어야겠네.', `FemaleText_loc4`='他们会留下标记的……我要先在这里休息片刻。', `FemaleText_loc5`='那將會留下紀錄...我只要在這休息一下。', `FemaleText_loc7`='Eso dejará una marca... Descansaré un poco aquí.' WHERE `ID`=21978;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='딸꾹... 여어, 췬구들! 잘 지냈나?', `MaleText_loc4`='嘿，伙计们！最近怎么样？', `MaleText_loc5`='嘿傢伙!進行的如何?', `MaleText_loc7`='¡Hey colegas! ¿Cómo va eso?', `FemaleText_loc1`='딸꾹... 어머, 얘들아! 잘 지냈니?', `FemaleText_loc4`='嘿，伙计们！最近怎么样？', `FemaleText_loc5`='嘿傢伙!進行的如何?', `FemaleText_loc7`='¡Hey colegas! ¿Cómo va eso?' WHERE `ID`=21979;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거 정말 해봐야 한다니까 그러네... 딸꾹...', `MaleText_loc4`='里们不如来试试这个……', `MaleText_loc5`='你們大家一定要試試看坐個...', `MaleText_loc7`='Ushtedesh tienen que probar essto…', `FemaleText_loc1`='아 참 정말 해봐야 한다니까 그러시네... 딸꾹...', `FemaleText_loc4`='里们不如来试试这个……', `FemaleText_loc5`='你們大家一定要試試看坐個...', `FemaleText_loc7`='Ushtedesh tienen que probar essto…' WHERE `ID`=21980;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 이게 다 웬 야단법석이지?', `MaleText_loc4`='这儿怎么搞的啊？', `MaleText_loc5`='這裡的吵雜是怎麼一回事?', `MaleText_loc7`='¿Qué es este alboroto?', `FemaleText_loc1`='어머, 이게 다 웬 야단법석이야?', `FemaleText_loc4`='这儿怎么搞的啊？', `FemaleText_loc5`='這裡的吵雜是怎麼一回事?', `FemaleText_loc7`='¿Qué es este alboroto?' WHERE `ID`=21981;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='술을 마시는 데 있어서 가좡 중요한 건 말이야... 술 취한 척하는 거라고... 딸꾹... 난 그냥 남자인 척 하는거고... 꺼억...', `MaleText_loc4`='喝……喝酒的时候嗫，缀棒的就是装醉咧……，里看，我现寨就在装，像吧……', `MaleText_loc5`='喝酒最棒的事就是裝酒醉...我只素在假裝。', `MaleText_loc7`='Lo mejor de beber es que pareshca que esstás borrasho... Ssolo dishimulo chicosh.', `FemaleText_loc1`='술을 마시는 데 있어서 가좡 중요한 건 말이죠... 술 취한 척하는 거라고요... 딸꾹... 난 그냥 여자인 척 하는거고... 딸꾹...', `FemaleText_loc4`='喝……喝酒的时候嗫，缀棒的就是装醉咧……，里看，我现寨就在装，像吧……', `FemaleText_loc5`='喝酒最棒的事就是裝酒醉...我只素在假裝。', `FemaleText_loc7`='Lo mejor de beber es que pareshca que esstás borrasho... Ssolo dishimulo chicosh.' WHERE `ID`=21982;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐! 누가 예쁜 금봘 드워프 아가씨 봤나? 분명히 방금 여기 있었다고... 딸꾹...', `MaleText_loc4`='嘿！有谁看到附近有没有漂亮的金发矮人妹？我……我发誓，刚才还寨周围看见咧……', `MaleText_loc5`='嘿!有輪坎到那個口愛的金花矮輪嗎?我花誓他悶剛剛還在這...', `MaleText_loc7`='¡Hey! ¿Alguién a vissssto a la preshiosa enana rubia? Juraría que esstaba jushto aquí...', `FemaleText_loc1`='어머 어머! 누가 저 멋진 드워프씨 봤어? 분명히 방금 여기 있었다고... 딸꾹...', `FemaleText_loc4`='嘿！有谁看到附近有没有漂亮的金发矮人妹？我……我发誓，刚才还寨周围看见咧……', `FemaleText_loc5`='嘿!有倫坎到那個口愛的金花矮倫嗎?我花誓他悶剛剛還在這...', `FemaleText_loc7`='¡Hey! ¿Alguién a vissssto a la preshiosa enana rubia? Juraría que esstaba jushto aquí...' WHERE `ID`=21983;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드뒤어 췬구와 함께 술을 마실 수 있다니 좋군... 보통은 집에서 혼자 앉아서 마시는데 말이야... 딸꾹...', `MaleText_loc4`='跟朋友们喝酒最棒啦……平常我只能寨家一个人偷偷喝。', `MaleText_loc5`='最後能跟朋有對飲真素好...平常我組能坐在家裡自己喝而已。', `MaleText_loc7`='Essh genial beber con lossh amigosh... Normalmente yo me sshiento en casa y bebo sssholo.', `FemaleText_loc1`='아, 칭구와 함께 술을 마실 수 있다니 좋네... 보통은 집에서 혼자 앉아서 마시는데 말이야... 딸꾹...', `FemaleText_loc4`='跟朋友们喝酒最棒啦……平常我只能寨家一个人偷偷喝。', `FemaleText_loc5`='最後能跟朋有對飲真素好...平常我組能坐在家裡自己喝而已。', `FemaleText_loc7`='Essh genial beber con lossh amigosh... Normalmente yo me sshiento en casa y bebo sssholo.' WHERE `ID`=21984;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='즐거운 시간 보내라고! <딸꾹!>', `MaleText_loc4`='这美好的时光！<嗝！>', `MaleText_loc5`='美好時光!<嗝!>', `MaleText_loc7`='¡Por los buenos tiempos! <¡hip!>', `FemaleText_loc1`='즐거운 시간 되세요! <딸꾹!>', `FemaleText_loc4`='这美好的时光！<嗝！>', `FemaleText_loc5`='美好時光!<嗝!>', `FemaleText_loc7`='¡Por los buenos tiempos! <¡hip!>' WHERE `ID`=21985;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우헉...', `MaleText_loc4`='啊哦……', `MaleText_loc5`='呃嘔...', `MaleText_loc7`='Uh oh...', `FemaleText_loc1`='우헉...', `FemaleText_loc4`='啊哦……', `FemaleText_loc5`='呃嘔...', `FemaleText_loc7`='Uh oh...' WHERE `ID`=21986;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 큰 입을 벌리곤 $n에게 맹렬히 돌진해 옵니다!', `MaleText_loc4`='%s快速掠过，在$n身上留下了一道很深的伤口！', `MaleText_loc5`='%s猛烈的攻擊，在$n上開出一條很大的裂縫!', `MaleText_loc7`='¡%s ataca, abriendo una gran herida en $n!' WHERE `ID`=21987;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마그니 왕께서 내게 다가와 이번 축제에 대한 이야기를 건네셨을 땐 말이지요, 난 너무 흥분했었답니다. 그래서 그분께 우리 노움족이 제공할 수 있는 작은 손길이 어떨지를 설명해 드렸지요. 우리가 이 축제를 기억할 수 있을 멋진 축제로 만들 수 있을 거라고 말입니다. 아쉽게도, 마그니 왕께서는 간단하게 하길 바라셨습니다. 옛 격식을 존중하길 바라신 것이지요.', `MaleText_loc4`='当麦格尼国王陛下过来找我谈有关节日的事情时，我简直要兴奋得疯过去了。我对他说，有了我这侏儒的一些微小帮助，我们就能制造出一场令所有人都会难以忘怀的盛宴。不过，国王陛下喜欢比较朴素和传统的风格，他更看中缅怀过去之类的事情。', `MaleText_loc5`='當麥格尼王靠近我談及這些我驚訝的慶典時。我開始解釋如何因為地精的一點小幫助，我們能夠真實擁有如此的歡樂可回憶。可惜的是，麥格尼王想讓事情簡單化。他想要榮耀過去。', `MaleText_loc7`='Cuando el rey Magni me habló de estas celebraciones me entusiasmé. Le expliqué cómo podíamos hacer un bombazo digno de mención con un poco de ayuda de los enanos. Por desgracia, el rey quería que fuera algo sencillo. Quería honrar el pasado.', `FemaleText_loc1`='마그니 왕께서 내게 다가와 이번 축제에 대한 이야기를 건네셨을 땐 말이지요, 난 너무 흥분했었답니다. 그래서 그분께 우리 노움족이 제공할 수 있는 작은 손길이 어떨지를 설명해 드렸지요. 우리가 이 축제를 기억할 수 있을 멋진 축제로 만들 수 있을 거라고 말입니다. 아쉽게도, 마그니 왕께서는 간단하게 하길 바라셨습니다. 옛 격식을 존중하길 바라신 것이지요.', `FemaleText_loc4`='当麦格尼国王陛下过来找我谈有关节日的事情时，我简直要兴奋得疯过去了。我对他说，有了我这侏儒的一些微小帮助，我们就能制造出一场令所有人都会难以忘怀的盛宴。不过，国王陛下喜欢比较朴素和传统的风格，他更看中缅怀过去之类的事情。', `FemaleText_loc5`='當麥格尼王靠近我談及這些我驚訝的慶典時。我開始解釋如何因為地精的一點小幫助，我們能夠真實擁有如此的歡樂可回憶。可惜的是，麥格尼王想讓事情簡單化。他想要榮耀過去。', `FemaleText_loc7`='Cuando el rey Magni me habló de estas celebraciones me entusiasmé. Le expliqué cómo podíamos hacer un bombazo digno de mención con un poco de ayuda de los enanos. Por desgracia, el rey quería que fuera algo sencillo. Quería honrar el pasado.' WHERE `ID`=21988;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그분의 그런 마음은 이해할 수 있습니다. 그런데 말입니다. 옛 형식을 고수하고자 하신 마그니 왕께서 맥주통에 노움 마개를 사용할 수 있는 변화를 허락하셨답니다. 그래서 난 새로운 난관을 풀어나가 볼 기회를 얻었지요. 얼마나 빠르고 효과적으로 맥주통을 열 수 있는지와 모든 축제 참석자들에게 일정한 양의 술을 배급할 수 있는지에 대한 난관 말입니다.', `MaleText_loc4`='我对此可以理解，但国王陛下能允许我这个侏儒去开酒桶，已经是个改变了。所以呢，现在我正在研究另一个难题，那就是：如何最有效率地打开酒桶，并把里面的酒平均地分给大家喝，注意平均和最有效率这两个词。', `MaleText_loc5`='我可以了解。不過國王真的同意改變，讓地精來打開桶子。所以我有機會可以進行一個新的問題;如何有效且快速的開啟桶子並分配容量，因此所有的參與者都能快速有效的分到相同的等分。', `MaleText_loc7`='Lo comprendo. Pero el rey permitió un cambio al dejar que un gnomo abriera el barril. Eso me dio la oportunidad de trabajar en un nuevo problema. ¿Cómo abrir el barril rápido y con eficacia y distribuir su contenido de forma que todos los participantes obtengan la misma cantidad?', `FemaleText_loc1`='그분의 그런 마음은 이해할 수 있습니다. 그런데 말입니다. 옛 형식을 고수하고자 하신 마그니 왕께서 맥주통에 노움 마개를 사용할 수 있는 변화를 허락하셨답니다. 그래서 난 새로운 난관을 풀어나가 볼 기회를 얻었지요. 얼마나 빠르고 효과적으로 맥주통을 열 수 있는지와 모든 축제 참석자들에게 일정한 양의 술을 배급할 수 있는지에 대한 난관 말입니다.', `FemaleText_loc4`='我对此可以理解，但国王陛下能允许我这个侏儒去开酒桶，已经是个改变了。所以呢，现在我正在研究另一个难题，那就是：如何最有效率地打开酒桶，并把里面的酒平均地分给大家喝，注意平均和最有效率这两个词。', `FemaleText_loc5`='我可以了解。不過國王真的同意改變，讓地精來打開桶子。所以我有機會可以進行一個新的問題;如何有效且快速的開啟桶子並分配容量，因此所有的參與者都能快速有效的分到相同的等分。', `FemaleText_loc7`='Lo comprendo. Pero el rey permitió un cambio al dejar que un gnomo abriera el barril. Eso me dio la oportunidad de trabajar en un nuevo problema. ¿Cómo abrir el barril rápido y con eficacia y distribuir su contenido de forma que todos los participantes obtengan la misma cantidad?' WHERE `ID`=21989;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래서 난 이 정밀한 작업을 맡을 기계를 고안하는 일에 착수할 최고의 기술자들을 모았답니다! 우린 최선의 방법이 무엇인지 초까지 계산했지요...', `MaleText_loc4`='现在，我手下最精锐的技师们正在研制一台伟大的机器来完成这个使命！我们可以计算出……', `MaleText_loc5`='所以我讓我的頂尖男男女女開始運作機器來進行這個精密的任務!我們已經計算過如何以最佳的時間-', `MaleText_loc7`='¡Así que pedí a mis mejores hombres y mujeres que comenzaran a trabajar en una máquina que desarrollase esa tarea! Hemos calculado al milímetro como dist-', `FemaleText_loc1`='그래서 난 이 정밀한 작업을 맡을 기계를 고안하는 일에 착수할 최고의 기술자들을 모았답니다! 우린 최선의 방법이 무엇인지 초까지 계산했지요...', `FemaleText_loc4`='现在，我手下最精锐的技师们正在研制一台伟大的机器来完成这个使命！我们可以计算出……', `FemaleText_loc5`='所以我讓我的頂尖男男女女開始運作機器來進行這個精密的任務!我們已經計算過如何以最佳的時間-', `FemaleText_loc7`='¡Así que pedí a mis mejores hombres y mujeres que comenzaran a trabajar en una máquina que desarrollase esa tarea! Hemos calculado al milímetro como dist-' WHERE `ID`=21990;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐... 음... 맥주통 따개 74205는 좀 기다려야 할 거 같습니다... 하지만 맥주통 따개 75633의 설계 도안이 있으니 문제없답니다...', `MaleText_loc4`='好吧……那么……我猜开罐器74205得再等一等……此外，我觉着开罐器75633的设计很有意思……', `MaleText_loc5`='唔...呃...我猜開桶器74205將需要等一下了...不過沒事，我已經拿到開桶器75633的一些設計了...', `MaleText_loc7`='Bueno... uh... parece que el Abrebarriles 74205 tendrá que esperar... pero no pasa nada, tengo algunas ideas para el Abrebarriles 75633...', `FemaleText_loc1`='뭐... 음... 맥주통 따개 74205는 좀 기다려야 할 거 같습니다... 하지만 맥주통 따개 75633의 설계 도안이 있으니 문제없습니다...', `FemaleText_loc4`='好吧……那么……我猜开罐器74205得再等一等……此外，我觉着开罐器75633的设计很有意思……', `FemaleText_loc5`='唔...呃...我猜桶子發報鍵74205將需要等一下了...不過沒事，我已經拿到桶子發報鍵75633的一些設計了...', `FemaleText_loc7`='Bueno... uh... parece que el Abrebarriles 74205 tendrá que esperar... pero no pasa nada, tengo algunas ideas para el Abrebarriles 75633...' WHERE `ID`=21991;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 좋아... 열부터 초읽기를 시작해 봅시다, 여러분, 준비되셨나요? 열!', `MaleText_loc4`='好吧，好吧……现在我们就开始十秒倒计时，大家准备好了吗？10！', `MaleText_loc5`='對，沒錯...那麼讓我們從十開始倒數計時，準備好了嗎?十!', `MaleText_loc7`='Vale, vale... Comencemos la cuenta atrás desde diez, ¿preparados? ¡10!', `FemaleText_loc1`='좋아, 좋아... 열부터 초읽기를 시작해 봅시다, 여러분, 준비되셨나요? 열!', `FemaleText_loc4`='好吧，好吧……现在我们就开始十秒倒计时，大家准备好了吗？10！', `FemaleText_loc5`='對，沒錯...那麼讓我們從十開始倒數計時，準備好了嗎?十!', `FemaleText_loc7`='Vale, vale... Comencemos la cuenta atrás desde diez, ¿preparados? ¡10!' WHERE `ID`=21992;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오... 짧은 게 좋으신가 본데... 좋습니다, 영까지 기다리도록 하지요...', `MaleText_loc4`='哦……好吧，让我们先等它归零……', `MaleText_loc5`='喔...好，那麼我只要等0...', `MaleText_loc7`='Oh... vale, esperaré hasta el cero...', `FemaleText_loc1`='오... 짧은 게 좋으신가 본데... 좋습니다, 영까지 기다리도록 하지요...', `FemaleText_loc4`='哦……好吧，让我们先等它归零……', `FemaleText_loc5`='喔...好，那麼我只要等0...', `FemaleText_loc7`='Oh... vale, esperaré hasta el cero...' WHERE `ID`=21993;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='땜장이왕님, 좀 빨리하시죠!', `MaleText_loc4`='快点快点，补锅的！', `MaleText_loc5`='技工，加速!', `MaleText_loc7`='¡Más deprisa, Manitas!', `FemaleText_loc1`='땜장이왕님, 좀 빨리하세요!', `FemaleText_loc4`='快点快点，补锅的！', `FemaleText_loc5`='技工，加速!', `FemaleText_loc7`='¡Más deprisa, Manitas!' WHERE `ID`=21994;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부으면 부을수록 지루함은 덜해진다고요!', `MaleText_loc4`='我们要酒啊啊啊啊！', `MaleText_loc5`='喝的愈多，煩惱愈少!', `MaleText_loc7`='¡MÁS CERVEZA Y MENOS ROLLO!', `FemaleText_loc1`='부으면 부을수록 지루함은 덜해지지요!', `FemaleText_loc4`='我们要酒啊啊啊啊！', `FemaleText_loc5`='喝的愈多，煩惱愈少!', `FemaleText_loc7`='¡MÁS CERVEZA Y MENOS ROLLO!' WHERE `ID`=21995;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 좋아! 이제 마시러 가자고!', `MaleText_loc4`='呀，呀！喝呀喝呀！', `MaleText_loc5`='哈哈，哈哈!讓我們喝吧!', `MaleText_loc7`='¡Sí, sí! ¡Vamos a beber!', `FemaleText_loc1`='좋아요, 좋아! 이제 마시러 가죠!', `FemaleText_loc4`='呀，呀！喝呀喝呀！', `FemaleText_loc5`='哈哈，哈哈!讓我們喝吧!', `FemaleText_loc7`='¡Sí, sí! ¡Vamos a beber!' WHERE `ID`=21996;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아으, 지루하단 말입니다!!', `MaleText_loc4`='无聊死啦！！！', `MaleText_loc5`='無聊死了!!', `MaleText_loc7`='¡ABURRIIIIIIIDO!', `FemaleText_loc1`='아으, 지루해 죽겠네!!', `FemaleText_loc4`='无聊死啦！！！', `FemaleText_loc5`='無聊死了!!', `FemaleText_loc7`='¡ABURRIIIIIIIDO!' WHERE `ID`=21997;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카숭을 마셔보자! 하잉투도 여깄구나! 두꺼비는 덤이런가!', `MaleText_loc4`='喝呀，一口干！喝呀，一口干！喝呀，一口干！', `MaleText_loc5`='喝吧，叮!喝吧，叮!喝吧，叮!', `MaleText_loc7`='¡Bebe Manitas! ¡Bebe Manitas! ¡Bebe Manitas!', `FemaleText_loc1`='카숭을 마셔보자! 하잉투도 여깄구나! 두꺼비는 덤이런가!', `FemaleText_loc4`='喝呀，一口干！喝呀，一口干！喝呀，一口干！', `FemaleText_loc5`='喝吧，叮!喝吧，叮!喝吧，叮!', `FemaleText_loc7`='¡Bebe Manitas! ¡Bebe Manitas! ¡Bebe Manitas!' WHERE `ID`=21998;
