UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 통나무배에 태워 주십시오.', `MaleText_loc4`='吉米，我想搭乘你的独木舟。', `MaleText_loc5`='好哇，我想試試你的獨木舟，吉米。', `MaleText_loc7`='Me gustaría montar en una de tus canoas, Jimmy.', `FemaleText_loc1`='네, 통나무배에 태워 주세요.', `FemaleText_loc4`='吉米，我想搭乘你的独木舟。', `FemaleText_loc5`='好哇，我想試試你的獨木舟，吉米。', `FemaleText_loc7`='Me gustaría montar en una de tus canoas, Jimmy.' WHERE `ID`=22003;
