UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 주목하고 계쉰 모두에게 감솨를... 오늘은 우리 모두가...작게...불어보는...아니쥐...불러보는 날이롸구! 그렇쥐... 우리 모두 스랄 님을 스릴있게 불러보좌구... 그러면 스랄 님께서 우리가 호드를 얼마나 사랑하는쥐 알아주실 거롸고. 쇼드를 위하여!', `MaleText_loc4`='感谢大家……今天我们要……要……是啦！其实……我们要叫萨……萨尔老大……和吉……吉……反……反正……他会明白我们是热爱部落的。部……部落万岁！', `MaleText_loc5`='感削大家來坎我...今忝是一個我們都應該...躺下...小聲...不對...呼喚的日子!就是這樣...我們都應該小小聲呼喚索爾...那樣他將會知道我們深愛部落。為了不落!', `MaleText_loc7`='Graciash a todosh por verme... Hoy essh el día en que todos deberíamossh ser pequeñosh... No... ¡LLAMAR! Essho esh... Deberíamossh llamar a Thrall pequeño... Asshí shabrá que amamossh la Horda. ¡POR LA ESSHPADA!', `FemaleText_loc1`='절 주목하고 계쉰 여러분 모두 감솨드려요... 오늘은 우리 모두가...작게...불어보는...아니지...불러보는 날이뢉니다! 그래요... 우리 모두 스랄 님을 스릴있게 불러보아요... 그러면 스랄 님이 우리가 호드를 얼마나 사랑하는쥐 알아주실 것이에요. 쇼드를 위하여!', `FemaleText_loc4`='感谢大家……今天我们要……要……是啦！其实……我们要叫萨……萨尔老大……和吉……吉……反……反正……他会明白我们是热爱部落的。部……部落万岁！', `FemaleText_loc5`='感削大家來坎我...今忝是一個我們都應該...躺下...小聲...不對...呼喚的日子!就是這樣...我們都應該小小聲呼喚索爾...那樣他將會知道我們深愛部落。為了不落!', `FemaleText_loc7`='Graciash a todosh por verme... Hoy essh el día en que todos deberíamossh ser pequeñosh... No... ¡LLAMAR! Essho esh... Deberíamossh llamar a Thrall pequeño... Asshí shabrá que amamossh la Horda. ¡POR LA ESSHPADA!' WHERE `ID`=22005;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 진짜 멋쥐게 타는 게 뭔쥐 보여 주겠어!', `MaleText_loc4`='来见识一下最厉害的骑术吧！', `MaleText_loc5`='現在你將會看到真正高超的騎術!', `MaleText_loc7`='¡Ahora verásh a alguien cabalgar bien de verdad!', `FemaleText_loc1`='이제 진짜 멋쥐게 타는 게 뭔쥐 보여 주겠어요!!', `FemaleText_loc4`='来见识一下最厉害的骑术吧！', `FemaleText_loc5`='現在你將會看到真正高超的騎術!', `FemaleText_loc7`='¡Ahora verásh a alguien cabalgar bien de verdad!' WHERE `ID`=22006;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 흔적이 남을 것 같은데... 여기서 잠깐 쉬어야겠군.', `MaleText_loc4`='想必会给他人留下深刻的印象……我先在这里休息片刻。', `MaleText_loc5`='那將會留下紀錄...我只要在這休息一下。', `MaleText_loc7`='Eso dejará una marca... Descansaré un poco aquí.', `FemaleText_loc1`='이건 흔적이 남을 것 같은데... 여기서 잠깐 쉬어야겠어요.', `FemaleText_loc4`='想必会给他人留下深刻的印象……我先在这里休息片刻。', `FemaleText_loc5`='那將會留下紀錄...我只要在這休息一下。', `FemaleText_loc7`='Eso dejará una marca... Descansaré un poco aquí.' WHERE `ID`=22007;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐! 당신 호드야? <딸꾹> 나도 호드야!', `MaleText_loc4`='嘿！你挺不挺部落？<嗝儿>我挺！', `MaleText_loc5`='嗨!你為了部落嗎?<嗝>我為了部落!', `MaleText_loc7`='¡Hey! ¿Estás con la Horda? <hip> ¡Yo estoy con la Horda!', `FemaleText_loc1`='저기요! 호드 분이세요? <딸꾹> 저도 호드에요!', `FemaleText_loc4`='嘿！你挺不挺部落？<嗝儿>我挺！', `FemaleText_loc5`='嗨!你為了部落嗎?<嗝>我為了部落!', `FemaleText_loc7`='¡Hey! ¿Estás con la Horda? <hip> ¡Yo estoy con la Horda!' WHERE `ID`=22008;
