UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 다 무슨 난리법석이쥐?', `MaleText_loc4`='这儿怎么搞的啊？', `MaleText_loc5`='這裡的吵雜是怎麼了?', `MaleText_loc7`='¿Qué es este alboroto?', `FemaleText_loc1`='여기서 무슨 난리라도 난 거예요?', `FemaleText_loc4`='这儿怎么搞的啊？', `FemaleText_loc5`='這裡的吵雜是怎麼了?', `FemaleText_loc7`='¿Qué es este alboroto?' WHERE `ID`=22010;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='술 마실 때 줴일 좋은 건 취한 척 할 수 있다는 거쥐... 이건 취한 게 아니라 쬐금 취한 척뫈 하는 거라고.', `MaleText_loc4`='喝……喝酒的时候呢，最棒的就是装醉咧……你们瞧，我装得像吧。', `MaleText_loc5`='喝酒最棒的事就是裝酒醉...我只素在假裝。', `MaleText_loc7`='Lo mejor de beber es que pareshca que esstás borrasho... Ssolo dishimulo chicosh.', `FemaleText_loc1`='술 마실 때 줴일 좋은 건 취한 척 할 수 있다는 거죠... 이건 취한 게 아니라 쬐금 취한 척뫈 하는 거예요.', `FemaleText_loc4`='喝……喝酒的时候呢，最棒的就是装醉咧……你们瞧，我装得像吧。', `FemaleText_loc5`='喝酒最棒的事就是裝酒醉...我只素在假裝。', `FemaleText_loc7`='Lo mejor de beber es que pareshca que esstás borrasho... Ssolo dishimulo chicosh.' WHERE `ID`=22011;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐요! 귀여운 고블린 보쉰 분 계십니까? 확쉴히 조금 전까쥐 여기 있었는데...', `MaleText_loc4`='嘿！有人看见漂亮地精妹了吗？我发誓刚才这里肯定有个……', `MaleText_loc5`='嘿!有輪坎到那個口愛的狗布林嗎?偶花誓他們剛剛在這...', `MaleText_loc7`='¡Hey! ¿Alguién a vissssto a la preshiosa goblin? Juraría que esstaba jushto aquí...', `FemaleText_loc1`='저기요! 귀여운 고블린 보쉰 분 계세요? 확쉴히 조금 전까쥐 여기 있었는데...', `FemaleText_loc4`='嘿！有人看见漂亮地精妹了吗？我发誓刚才这里肯定有个……', `FemaleText_loc5`='嘿!有輪坎到那個口愛的狗布林嗎?偶花誓他們剛剛在這...', `FemaleText_loc7`='¡Hey! ¿Alguién a vissssto a la preshiosa goblin? Juraría que esstaba jushto aquí...' WHERE `ID`=22012;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마지막에 췬구들과 한 잔 하는 건 정말 멋쥔 일이쥐... 보통이라면 그냥 집에서 혼자 마쉬거든.', `MaleText_loc4`='跟朋友们喝酒最棒啦……平常我就只能在家偷喝。', `MaleText_loc5`='最後能跟朋有對飲真素好...平常我組能坐在家裡自己喝而已。', `MaleText_loc7`='Essh genial beber con lossh amigosh... Normalmente yo me sshiento en casa y bebo sssholo.', `FemaleText_loc1`='마지막에 췬구들과 한 잔 하는 건 정말 멋쥔 일이죠... 보통은 그냥 집에서 혼자 마쉬거든요.', `FemaleText_loc4`='跟朋友们喝酒最棒啦……平常我就只能在家偷喝。', `FemaleText_loc5`='最後能跟朋有對飲真素好...平常我組能坐在家裡自己喝而已。', `FemaleText_loc7`='Essh genial beber con lossh amigosh... Normalmente yo me sshiento en casa y bebo sssholo.' WHERE `ID`=22013;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='재밌게들 놀라고! <딸꾹!>', `MaleText_loc4`='真是美好的时光！<嗝儿！>', `MaleText_loc5`='美好時光!<嗝!>', `MaleText_loc7`='¡Por los buenos tiempos! <¡hip!>', `FemaleText_loc1`='재밌게들 노세요! <딸꾹!>', `FemaleText_loc4`='真是美好的时光！<嗝儿！>', `FemaleText_loc5`='美好時光!<嗝!>', `FemaleText_loc7`='¡Por los buenos tiempos! <¡hip!>' WHERE `ID`=22014;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘, 맛있는 음식을 제공해주신 분들께 깊은 감사를 드리오.', `MaleText_loc4`='今天，让我们深刻铭记那些为我们带来温饱的人。', `MaleText_loc5`='今日，我們榮耀那些帶給我們美食及甘露的人們。', `MaleText_loc7`='Hoy honramos a los que nos traen buena comida y buena bebida.', `FemaleText_loc1`='오늘, 맛있는 음식을 제공해주신 분들께 깊은 감사를 드려요.', `FemaleText_loc4`='今天，让我们深刻铭记那些为我们带来温饱的人。', `FemaleText_loc5`='今日，我們榮耀那些帶給我們美食及甘露的人們。', `FemaleText_loc7`='Hoy honramos a los que nos traen buena comida y buena bebida.' WHERE `ID`=22015;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그분들에게 경의를 표하는 뜻에서 서로 실력을 겨뤄보시도록 했소이다.', `MaleText_loc4`='让他们彼此争斗，才能显示出我们对他们的敬意。', `MaleText_loc5`='我們藉由使他們彼此交戰來榮耀他們。', `MaleText_loc7`='Los honramos enviándolos a luchar unos contra otros.', `FemaleText_loc1`='그분들에게 경의를 표하는 뜻에서 서로 실력을 겨뤄보시도록 했어요.', `FemaleText_loc4`='让他们彼此争斗，才能显示出我们对他们的敬意。', `FemaleText_loc5`='我們藉著使他們彼此交戰來榮耀他們。', `FemaleText_loc7`='Los honramos enviándolos a luchar unos contra otros.' WHERE `ID`=22016;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 최고의 양조사인지 가려봅시다. 양조장 쪽에서도 바짝 긴장한 채로 참여하고 있을 겁니다. 전력을 기울이지 않으신다면 양조장 분들을 초대할 이유가 없었겠지요.', `MaleText_loc4`='我们马上就能知道谁是最棒的酿酒师啦。酿酒师们都非常期待这场比赛，否则我们也不会邀请他们了。', `MaleText_loc5`='我們將會知道誰是最優良的啤酒大師。我們知道啤酒廠準備好挑戰。否則我們不會邀請他們。', `MaleText_loc7`='Sabremos quién es el mejor maestro cervecero. Sabemos que las destilerías estarán a la altura, si no, no las habríamos invitado.', `FemaleText_loc1`='누가 최고의 양조사인지 가려보아요. 양조장 쪽에서도 바짝 긴장한 채로 참여하고 있을 거예요. 전력을 기울이지 않으신다면 양조장 분들을 초대할 이유가 없었을 걸요.', `FemaleText_loc4`='我们马上就能知道谁是最棒的酿酒师啦。酿酒师们都非常期待这场比赛，否则我们也不会邀请他们了。', `FemaleText_loc5`='我們將會知道誰是最優良的啤酒大師。我們知道啤酒廠準備好挑戰。否則我們不會邀請他們。', `FemaleText_loc7`='Sabremos quién es el mejor maestro cervecero. Sabemos que las destilerías estarán a la altura, si no, no las habríamos invitado.' WHERE `ID`=22017;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러니 이제, 우리 듬직한 전사 형제들과 더불어 즐겨봅시다!', `MaleText_loc4`='伟大的战士兄弟们，让我们举杯欢庆吧！', `MaleText_loc5`='所以現在，讓我們與我們優秀的戰士兄弟們一同慶祝!', `MaleText_loc7`='¡Así que festejemos junto a nuestros valiosos hermanos guerreros!', `FemaleText_loc1`='그러니 이제 우리 듬직한 전사 형제들과 더불어 즐겨봅시다!', `FemaleText_loc4`='伟大的战士兄弟们，让我们举杯欢庆吧！', `FemaleText_loc5`='那麼現在，讓我們與我們優秀的戰士兄弟們一同慶祝!', `FemaleText_loc7`='¡Así que festejemos junto a nuestros valiosos hermanos guerreros!' WHERE `ID`=22018;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='5부터 세어 내려갑시다. 그다음에 이 늙은 볼진이 여기 있는 맥주통을 따면 누가 최고의 양조사인지 가려질 테지요.', `MaleText_loc4`='从五开始倒数。倒数结束后，老沃金就会打开这只酒桶，我们将评出谁才是最优秀的酿酒大师。', `MaleText_loc5`='讓我們倒數5秒。然後老沃金將會打開這個桶子，我們全都能決定誰才是最優秀的啤酒大師。', `MaleText_loc7`='Contaremos desde cinco. Entonces el viejo Vol''jin abrirá este barril y podremos decidir quién es el mejor maestro cervecero.', `FemaleText_loc1`='5부터 세어 내려갑시다. 그다음에 볼진 님이 여기 있는 맥주통을 따면 누가 최고의 양조사인지 가려질 거예요.', `FemaleText_loc4`='从五开始倒数。倒数结束后，老沃金就会打开这只酒桶，我们将评出谁才是最优秀的酿酒大师。', `FemaleText_loc5`='讓我們倒數5秒。然後老沃金將會打開這個桶子，我們全都能決定誰才是最優秀的啤酒大師。', `FemaleText_loc7`='Contaremos desde cinco. Entonces el viejo Vol''jin abrirá este barril y podremos decidir quién es el mejor maestro cervecero.' WHERE `ID`=22019;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맥주통을 땄소이다! 경기가 시작되었소! 참가자들을 위해 건배를 외칠 테니 나를 따라 잔을 높이 들어주시오.', `MaleText_loc4`='酒桶已经被打开了！比赛开始！让我们一起举杯，为战士们干杯吧……', `MaleText_loc5`='桶子已經被打開了!戰鬥開始!現在，在我舉杯祝福我們的鬥士時，和我一起舉起你們的杯子...', `MaleText_loc7`='¡Se ha abierto el barril! ¡Comienza la batalla! Alzen sus vasos junto a mí para brindar por nuestros combatientes...', `FemaleText_loc1`='나무통을 따셨군요! 경기가 시작되었어요! 참가자들을 위해 건배를 외칠 테니 저를 따라 잔을 높이 들어주세요.', `FemaleText_loc4`='酒桶已经被打开了！比赛开始！让我们一起举杯，为战士们干杯吧……', `FemaleText_loc5`='桶子已經被打開了!戰鬥開始!現在，在我舉杯祝福我們的鬥士時，和我一起舉起你們的杯子...', `FemaleText_loc7`='¡Se ha abierto el barril! ¡Comienza la batalla! Alzen sus vasos junto a mí para brindar por nuestros combatientes...' WHERE `ID`=22020;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드를 위하여 맥주를! 호드를 위하여 건배를!', `MaleText_loc4`='为了部落，酿！为了部落，喝！', `MaleText_loc5`='為了部落而釀!為了部落而飲!', `MaleText_loc7`='¡Destilad por la Horda! ¡Bebed por la Horda!', `FemaleText_loc1`='호드를 위하여 맥주를! 호드를 위하여 건배를!', `FemaleText_loc4`='为了部落，酿！为了部落，喝！', `FemaleText_loc5`='為了部落而釀!為了部落而飲!', `FemaleText_loc7`='¡Destilad por la Horda! ¡Bebed por la Horda!' WHERE `ID`=22021;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='각오해라. 종은 이미 울렸다! 병자와 노인과 어린 아이들을 숨겨라! 너희 모두 죗값을 치를 테니! 자비를 구해라! 심판의 날이 다가왔다!', `MaleText_loc4`='战栗吧，丧钟已为你鸣响！颤抖吧，挽歌已为你宣唱！末日审判已潸然降临，所有生者都要付出代价！', `MaleText_loc5`='做好準備吧，喪鐘已響!把老弱婦孺都藏起來!每個人終將付出代價。顫抖求饒吧，懲罰將至!', `MaleText_loc7`='¡Prepárense, pues las campanas sonaron! ¡Oculten al débil, al niño, al anciano! ¡Cada uno de ustedes saldará su deuda! ¡Imploren clemencia, la cuenta se cierra!' WHERE `ID`=22022;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부어라마셔라를 위하여!', `MaleText_loc4`='美酒万岁！', `MaleText_loc5`='為了喝酒!', `MaleText_loc7`='¡POR LA BIRRA!', `FemaleText_loc1`='부어라마셔라를 위하여!', `FemaleText_loc4`='美酒万岁！', `FemaleText_loc5`='為了喝酒!', `FemaleText_loc7`='¡POR LA BIRRA!' WHERE `ID`=22023;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘은 한 잔 하기 좋은 날이라고, 친구!', `MaleText_loc4`='今天最适合喝酒啦！其实每一天都很适合喝酒！', `MaleText_loc5`='今天是喝酒的好日子!', `MaleText_loc7`='¡Hoy es un buen día para beber!', `FemaleText_loc1`='오늘은 한 잔 하기 좋은 날이네요!', `FemaleText_loc4`='今天最适合喝酒啦！其实每一天都很适合喝酒！', `FemaleText_loc5`='今天是喝酒的好日子!', `FemaleText_loc7`='¡Hoy es un buen día para beber!' WHERE `ID`=22024;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드를 위하여 마시자고!', `MaleText_loc4`='为了部落，干杯！', `MaleText_loc5`='為了部落暢飲!', `MaleText_loc7`='¡Bebed por la Horda!', `FemaleText_loc1`='호드를 위해 마셔요!', `FemaleText_loc4`='为了部落，干杯！', `FemaleText_loc5`='為了部落暢飲!', `FemaleText_loc7`='¡Bebed por la Horda!' WHERE `ID`=22025;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='활활 타오르는구나! 너는 실패했다. 정의가 승리했도다!', `MaleText_loc4`='烈焰吞噬一切！你们精疲力竭，毫无获胜的希望。我要伸张正义！', `MaleText_loc5`='火焰吞噬一切!你的努力已然失敗。不要懷疑，正義獲得了伸張!', `MaleText_loc7`='¡El fuego se apaga! Tu intento ha fallado. Sin sombra de duda, la justicia ha triunfado.' WHERE `ID`=22026;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 불꽃은 흔적조차 남지 않았구나. 죽음의 암흑이여, 내가 너에게 가노라.', `MaleText_loc4`='我的地狱烈焰竟已不再煌煌。你的生命火烛必也要暗褐无光！', `MaleText_loc5`='我的火焰死滅，星火未存。我將親自出馬，將你帶至死寂的黑闇之中。', `MaleText_loc7`='Se extinguió mi llama, nada queda de ella. Te enviaré yo mismo a la oscuridad eterna.' WHERE `ID`=22027;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저주받은 기사 - 공격, 새로운 지역으로 이동.', `MaleText_loc4`='无头骑士——攻击，转移。', `MaleText_loc5`='無頭騎士 - 攻擊，前往新地點。', `MaleText_loc7`='Headless Horseman - Attack, Go to new loc.' WHERE `ID`=22028;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으스러진 손의 전당으로 가는 열쇠를 잃어버렸습니다.', `MaleText_loc4`='我把破碎大厅的钥匙弄丢了。', `MaleText_loc5`='我遺失了破碎大廳的鑰匙。', `MaleText_loc7`='He perdido la llave de Las Salas Arrasadas.', `FemaleText_loc1`='으스러진 손의 전당으로 가는 열쇠를 잃어버렸어요.', `FemaleText_loc4`='我把破碎大厅的钥匙弄丢了。', `FemaleText_loc5`='我遺失了破碎大廳的鑰匙。', `FemaleText_loc7`='He perdido la llave de Las Salas Arrasadas.' WHERE `ID`=22029;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경고 사격 개시!', `MaleText_loc4`='开火示警！', `MaleText_loc5`='開火警告他們!', `MaleText_loc7`='¡Disparad un tiro de aviso!' WHERE `ID`=22030;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 정도면 정신 좀 차렸겠지...', `MaleText_loc4`='让他们吃点苦头……', `MaleText_loc5`='這會讓他們學得教訓的...', `MaleText_loc7`='Así aprenderán...' WHERE `ID`=22031;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠습니다, 부제독님!', `MaleText_loc4`='遵命，长官！', `MaleText_loc5`='是的，長官!', `MaleText_loc7`='¡Sí, sí, señor!' WHERE `ID`=22032;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발사!', `MaleText_loc4`='开火！', `MaleText_loc5`='射擊!', `MaleText_loc7`='¡FUEGO!' WHERE `ID`=22033;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하늘이 어둡구나. 불길이 솟구친다. 운명의 수레바퀴 안에서 네 수고는 무익하도다.', `MaleText_loc4`='天空一片黑暗，火焰仍在肆虐。你的挣扎毫无意义，命运之轮已经开始旋转。', `MaleText_loc5`='天空黑濛。烈焰灼燒。你的掙扎在命運之輪的轉動下皆屬徒勞。', `MaleText_loc7`='El cielo está oscuro. Arde las llamas. En vano luchas, la suerte está echada.' WHERE `ID`=22034;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정화의 불꽃이여, 활활 불타는구나! 시간이 없도다! 나는 곧 물러나리니...', `MaleText_loc4`='小镇仍在燃烧，看这净化的火焰！啊，时间过得真快，我要撤退了！', `MaleText_loc5`='淨化之火焰!城鎮燒不盡!時刻將用罄，我亦欲歸去!', `MaleText_loc7`='¡La ciudad encendida, todo limpia el fuego! ¡Queda poco tiempo, pronto estaré lejos!' WHERE `ID`=22035;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간을 너무 오래 끌었군. 이제 끝을 보겠다.', `MaleText_loc4`='你浪费了太多的时间，凡人。长眠吧！', `MaleText_loc5`='你們浪費太多時間了，凡人。現在你該死了。', `MaleText_loc7`='Ya he perdido demasiado tiempo, mortales. Ahora morirán' WHERE `ID`=22036;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='의심하지 말지니, 정의가 승리했도다!', `MaleText_loc4`='毫不迟疑，伸张正义！', `MaleText_loc5`='沒有懷疑，正義彰顯!', `MaleText_loc7`='No te quepa duda, ya justicia se ha servido.' WHERE `ID`=22037;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알 수 없는 발굽 자국에, 검게 그을린 방패, 휘장은 떨어져 있고... 이 모든 현상을 어떻게 이해해야 하겠습니까?', `MaleText_loc4`='神秘的蹄印，烧焦的盾牌，四散的徽章……这些东西有什么联系吗？', `MaleText_loc5`='神秘的蹄印，燒焦的盾牌，散落的徽章...我們要如何從這所有東西當中理出頭緒來?', `MaleText_loc7`='Misteriosas huellas de pezuñas, escudos agostados, insignias perdidas... ¿qué sentido tiene todo esto?' WHERE `ID`=22038;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 범죄는 반드시 해결해야만 합니다. 여관 위치도 그렇고 파괴된 상태도 심각해서 이번 사건이 아주 까다롭게 됐습니다. 현장을 조사할 때 최대한의 주의를 기울여 주십시오.', `MaleText_loc4`='这种罪行不容姑息。旅店的地理位置和它的离奇被毁让事态变得非常棘手。朋友，用谨慎的态度去树荫旅店展开调查吧。', `MaleText_loc5`='此罪行不允許存在。這座旅店的位置及其破壞的暴行讓此變成一個非常複雜的問題。朋友，嚴密的搜查這個地方。', `MaleText_loc7`='Este crimen no puede quedar sin resolver. La situación de la posada y la violencia de su destrucción lo convierten en un asunto muy delicado. Inspecciona el lugar con el máximo respeto.' WHERE `ID`=22039;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 뭐하십니까? 목숨을 잃은 가족의 재까지 더럽힐 생각입니까? 어서 떠나십시오. 아무도 당신을 반기지 않습니다.', `MaleText_loc4`='你在这里干什么？你还想要继续玷污这个被屠杀的家族所遗留的灰烬吗？离开这个地方。这里不欢迎你。', `MaleText_loc5`='你在這做什麼?你還想要污辱這一家人的骨灰嗎?快離開，這裡不歡迎你。', `MaleText_loc7`='¿Qué haces aquí? ¿Deseas profanar aún más las cenizas de esta familia asesinada? Abandona este lugar. No eres $gbienvenido:bienvenida;.' WHERE `ID`=22040;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 탐지용 가루를 한 번 더 뿌려주시겠습니까?', `MaleText_loc4`='你能再撒一次反光粉吗？', `MaleText_loc5`='你可以再一次散佈鏡映之塵嗎?', `MaleText_loc7`='¿Puedes volver a extender el polvo reflectante?', `FemaleText_loc1`='그 탐지용 가루를 한 번 더 뿌려주시겠어요?', `FemaleText_loc4`='你能再撒一次反光粉吗？', `FemaleText_loc5`='你可以再一次散佈鏡映之塵嗎?', `FemaleText_loc7`='¿Puedes volver a extender el polvo reflectante?' WHERE `ID`=22041;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음... 이상하군...', `MaleText_loc4`='唔……我觉得……', `MaleText_loc5`='嗯嗯...我懷疑...', `MaleText_loc7`='Hmm... Me pregunto...' WHERE `ID`=22042;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바보 같은 마법사들... 재료를 끝까지 다 쓰고는 한 번도 채워놓은 적이 없다니까, 쯧.', `MaleText_loc4`='愚蠢的法师们……总是将材料用得一干二净，还不知道及时补充。', `MaleText_loc5`='笨法師...老是用完最後一個材料又不補充。', `MaleText_loc7`='Estúpidos magos... siempre acaban con los componentes y nunca los reponen.' WHERE `ID`=22043;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그가 약재 가지고 또 뭐라 투덜거리던가요? 지난번에 소환 마법서를 놓고 갔던 건 기억도 못 한답니까?', `MaleText_loc4`='他又在为材料的事发牢骚了？呸，他怎么不提上次将召唤书忘在这里的糗事？', `MaleText_loc5`='他又在抱怨材料的事嗎?他還記得上次他是怎麼丟下召喚圖騰的嗎?', `MaleText_loc7`='¿Se está quejando otra vez por los componentes? ¿Se acuerda de cómo dejó los libros de invocación la última vez?' WHERE `ID`=22044;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어휴, 그게 어디 갔지?', `MaleText_loc4`='那么，它在哪儿？', `MaleText_loc5`='那麼，東西在哪?', `MaleText_loc7`='Ahora, ¿dónde está?' WHERE `ID`=22045;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리를 막을 수 있다고 생각했다면 큰 오산이다, ''친구''.', `MaleText_loc4`='“朋友”，如果你认为自己能阻止我们的话，那你就大错特错了。', `MaleText_loc5`='如果你以為你可以阻止我們的話，你就錯了，「朋友」。', `MaleText_loc7`='Si crees que puedes detenernos, te equivocas "colega".' WHERE `ID`=22046;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방해해 봤자 소용없다! 제이나가 얼마나 비겁한지 우리가 세상에 알리고 말 테다!', `MaleText_loc4`='我们一定要把吉安娜的懦弱行径曝光！', `MaleText_loc5`='你無法阻止我們揭發珍娜是個懦夫的事實!', `MaleText_loc7`='¡No puedes evitar que expongamos la verdad acerca de la cobardía de Jaina!' WHERE `ID`=22047;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 있는 모든 이는 프라우드무어 제독님이 진정한 영웅이셨다는 걸 알게 될 것이다!', `MaleText_loc4`='这些家伙总有一天会明白，普罗德摩尔将军是一位真正的英雄！', `MaleText_loc5`='這些人將會明白普勞德摩爾上將才是真正的英雄!', `MaleText_loc7`='¡Esta gente conocerá al almirante Valiente como el autentico héroe que fue!' WHERE `ID`=22048;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 너 같은 녀석들 때문에 얼라이언스가 약해지고, 우리가 열심히 싸워서 지켜 온 것들을 호드한테 빼앗긴 거야!', `MaleText_loc4`='就是像你这样的家伙削弱了联盟的力量，邀请部落来夺走我们为之奋斗的一切！', `MaleText_loc5`='就是有你這樣的人在害聯盟變弱!無異於邀請部落來奪走所有我們努力的成果!', `MaleText_loc7`='¡Es gente como tú la que debilita la Alianza e invita a la Horda a destruir todo aquello por lo que hemos luchado!' WHERE `ID`=22049;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 긍지를 갖고 테라모어를 지키는 걸 보니 기쁘군, 친구.', `MaleText_loc4`='朋友，感谢你成功地保卫了塞拉摩。', `MaleText_loc5`='很高興看到你以捍衛塞拉摩而自豪，朋友。', `MaleText_loc7`='Me alegra verte defendiendo Theramore con orgullo, colega.' WHERE `ID`=22050;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비번일 때 함께 여관에 가세. 내가 한잔 살 테니. 좋았던 옛날 얘기나 나눠 보세나.', `MaleText_loc4`='等你下班以后，我请你去旅店喝上几杯，一起回忆过去的美好时光。', `MaleText_loc5`='等你休息時，我們到酒館去吧。我請客，然後我們可以追憶過去美好的時光。', `MaleText_loc7`='Cuando no estés de servicio, vayamos a la posada. Pagaré una ronda y podremos recordar maravillosos tiempos pasados.' WHERE `ID`=22051;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네, 옛 영광을 되돌리고 싶다는 생각이 들지는 않나? 내 친구들이 그렇게 할 방도를 아는데 말이야...', `MaleText_loc4`='难道你不怀念往昔的岁月吗？我的朋友知道如何重返荣耀……', `MaleText_loc5`='你想要喚回那些往日時光嗎?我有幾個朋友剛好知道方法...', `MaleText_loc7`='¿No te gustaría que todo volviera a ser como antes? Tengo algunos amigos que saben cómo lograrlo...' WHERE `ID`=22052;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신과는 말이 통할 것 같습니다, 친구. 제이나가 호드와의 전투를 막기 전, 그때의 테라모어가 얼마나 영광스러웠는지 기억하십니까? 오크가 계속 우리를 자극하는데도 칼을 들지 말라는 명령을 받는 게 지겹지도 않으십니까?', `MaleText_loc4`='朋友，你看上去是位通情达理的$c。你可曾记得塞拉摩昔日的光辉岁月？那是吉安娜禁止我们与部落交战之前的事情了。兽人仍在频频挑衅，而我们却被告知不得挑起战乱，你是否对此感到厌倦？', `MaleText_loc5`='你似乎是個明理的$c，朋友。你還記得塞拉摩以前風光的歲月嗎?珍娜要我們放棄對抗部落以前的那段美好時光?你是不是已經厭倦了在獸人一直挑釁我們的時候，還聽到人家跟你說別衝動嗎?', `MaleText_loc7`='Pareces audaz, $c. ¿Recuerdas los días gloriosos de Theramore, antes de que Jaina nos hiciera abandonar la lucha contra la Horda? ¿Estás harto de tener que guardar tu espada mientras los orcos siguen provocándonos?' WHERE `ID`=22053;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 그런 선동에 넘어가지 않는다. 더러운 반역 계획은 다른 데서 털어놓으시지, 이 배신자!', `MaleText_loc4`='你的言论根本影响不了我。去别的地方散布那些叛逆的理论吧，叛徒！', `MaleText_loc5`='你的煽動對我沒有作用。到別處去使出你的骯髒本事吧，背叛者!', `MaleText_loc7`='Tu propaganda no funcionará conmigo. ¡Suelta tu traicionera suciedad en otro lugar, infiel!', `FemaleText_loc1`='나는 그런 선동에 넘어가지 않는다. 더러운 반역 계획은 다른 데서 털어놓으시지, 이 배신자!', `FemaleText_loc4`='你的言论根本影响不了我。去别的地方散布那些叛逆的理论吧，叛徒！', `FemaleText_loc5`='你的煽動對我沒有作用。到別處去使出你的骯髒本事吧，背叛者!', `FemaleText_loc7`='Tu propaganda no funcionará conmigo. ¡Suelta tu traicionera suciedad en otro lugar, infiel!' WHERE `ID`=22054;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저거 보십시오! 과일 수레 옆에 있는 오우거 말입니다. 과일 상인도 전쟁 대비를 하고 있군요...', `MaleText_loc4`='看！水果摊边上有个三层楼高的食人魔。那个水果贩看来想和我们大战一场了……', `MaleText_loc5`='看看那個!接進水果貨車旁邊，有個巨魔。水果商人正在為戰爭做準備...', `MaleText_loc7`='¡Mirad eso! Cerca de los carritos de la fruta... un ogro. El frutero se prepara para la guerra...', `FemaleText_loc1`='저거 보세요! 과일 수레 옆에 있는 오우거 말이에요. 과일 상인도 전쟁 대비를 하고 있네요...', `FemaleText_loc4`='看！水果摊边上有个三层楼高的食人魔。那个水果贩看来想和我们大战一场了……', `FemaleText_loc5`='看看那個!接進水果貨車旁邊，有個巨魔。水果商人正在為戰爭做準備...', `FemaleText_loc7`='¡Mirad eso! Cerca de los carritos de la fruta... un ogro. El frutero se prepara para la guerra...' WHERE `ID`=22055;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전쟁이 일어날 조짐이라고는 저 오우거 뿐입니다. 과일 상인이 괜히 지레짐작하는 겁니다.', `MaleText_loc4`='那个食人魔就是他要发动战争的迹象。水果贩已经坏了道上的规矩！', `MaleText_loc5`='那個巨魔只是第一個顯示戰爭到來的跡象而已。水果商人已經走遠了。', `MaleText_loc7`='Ese ogro es la primera señal de que la guerra se cierne sobre nosotros. El frutero ha ido demasiado lejos.', `FemaleText_loc1`='전쟁이 일어날 조짐이라고는 저 오우거 뿐이에요. 과일 상인이 괜히 지레짐작하는 거라고요.', `FemaleText_loc4`='那个食人魔就是他要发动战争的迹象。水果贩已经坏了道上的规矩！', `FemaleText_loc5`='那個巨魔只是第一個顯示戰爭到來的跡象而已。水果商人做得太過份了。', `FemaleText_loc7`='Ese ogro es la primera señal de que la guerra se cierne sobre nosotros. El frutero ha ido demasiado lejos.' WHERE `ID`=22056;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='과일 상인은 도대체 어떤 작자이기에 저렇게 뻔뻔스러운 행동을 하는 거지? 도움을 받으려고 오우거나 끌어들이고 말이야.', `MaleText_loc4`='哪个水果贩有这个胆子？他竟然买通食人魔当打手。', `MaleText_loc5`='做出如此莽撞行徑的水果商人是誰?他找來一個巨魔幫忙。', `MaleText_loc7`='¿Quién es ese frutero que ha tenido la magnífica idea? Ha traído un ogro como apoyo.', `FemaleText_loc1`='과일 상인은 도대체 어떤 사람이기에 저렇게 뻔뻔스러운 행동을 하는 거죠? 도움을 받으려고 오우거나 끌어들이고 말이죠.', `FemaleText_loc4`='哪个水果贩有这个胆子？他竟然买通食人魔当打手。', `FemaleText_loc5`='做出如此莽撞行徑的水果商人是誰?他找來一個巨魔幫忙。', `FemaleText_loc7`='¿Quién es ese frutero que ha tenido la magnífica idea? Ha traído un ogro como apoyo.' WHERE `ID`=22057;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런! 과일 상인은 목숨이 아까운 게 틀림없군. 지원까지 구한 걸 보니... 뭐, 둘이 잘해보라고.', `MaleText_loc4`='哈！水果贩这下一定很害怕了。他竟然叫来了援军。好吧，这下有的玩了。', `MaleText_loc5`='哈!水果商人一定很擔心他的生命。他在徵求協助。反正兩個人就能進行遊戲了。', `MaleText_loc7`='¡JA! El frutero debe temer por su vida. Ha buscado apoyo. Bueno, todos podemos jugar a ese juego.', `FemaleText_loc1`='이런! 과일 상인은 목숨이 아까운 게 틀림없군요. 지원까지 구한 걸 보니... 뭐, 둘이 잘해보라고 하세요.', `FemaleText_loc4`='哈！水果贩这下一定很害怕了。他竟然叫来了援军。好吧，这下有的玩了。', `FemaleText_loc5`='哈!水果商人一定很擔心他的生命。他在徵求協助。反正兩個人就能進行遊戲了。', `FemaleText_loc7`='¡JA! El frutero debe temer por su vida. Ha buscado apoyo. Bueno, todos podemos jugar a ese juego.' WHERE `ID`=22058;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='과일 상인은 내가 보는 눈이 없다고 생각하는 모양이지? 오우거까지 끌어들인 걸 눈치 못 챌 거로 생각하나?', `MaleText_loc4`='难道那水果贩以为我瞎了吗？我怎么可能看不到他的食人雇佣兵？', `MaleText_loc5`='水果商人是以為我瞎了嗎?他們以為我會沒看到他的巨魔援軍嗎?', `MaleText_loc7`='¿El frutero se piensa que estoy ciego? ¿Creen que no puedo ver su refuerzo ogro?', `FemaleText_loc1`='과일 상인은 내가 보는 눈이 없다고 생각하는 모양이죠? 오우거까지 끌어들인 걸 눈치 못 챌 거로 생각하나요?', `FemaleText_loc4`='难道那水果贩以为我瞎了吗？我怎么可能看不到他的食人雇佣兵？', `FemaleText_loc5`='水果商人是以為我瞎了嗎?他們以為我會沒看到他的巨魔援軍嗎?', `FemaleText_loc7`='¿El frutero se piensa que estoy ciega? ¿Creen que no puedo ver su refuerzo ogro?' WHERE `ID`=22059;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전쟁이 빠른 속도로 가까워지고 있다는 걸 알겠군. 과일 상인이 오우거한테까지 도움을 구했으니 말이야. 나도 어디엔가 도움을 요청해야겠군.', `MaleText_loc4`='我感觉到了真正的战争气息。水果贩已经得到了食人魔的援助，我也必须叫来我的援兵。', `MaleText_loc5`='我感覺戰爭正在快速接近。水果商人已經徵求到一個巨魔的幫助。我應該也要徵求幫助。', `MaleText_loc7`='Presiento que la guerra se acerca presta. El frutero ha buscado la ayuda de un ogro. Puede que yo también necesite buscar ayuda.', `FemaleText_loc1`='전쟁이 빠른 속도로 가까워지고 있다는 걸 알겠네요. 과일 상인이 오우거한테까지 도움을 구했으니 말이에요. 저도 어디엔가 도움을 요청해야겠어요.', `FemaleText_loc4`='我感觉到了真正的战争气息。水果贩已经得到了食人魔的援助，我也必须叫来我的援兵。', `FemaleText_loc5`='我感覺戰爭正在快速接近。水果商人已經徵求到一個巨魔的幫助。我應該也要徵求幫助。', `FemaleText_loc7`='Presiento que la guerra se acerca presta. El frutero ha buscado la ayuda de un ogro. Puede que yo también necesite buscar ayuda.' WHERE `ID`=22060;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저주받은 기사의 마음은 죽지도 못한 채 무언가에 사로잡혀 있어요! 할로윈 기간에는 마을을 자주 습격하는데, 정말 끔찍한 일이 아닐 수 없답니다.', `FemaleText_loc4`='无头骑士的灵魂已经变得疯狂了！在万圣节期间，他随时可能袭击这座村庄！', `FemaleText_loc5`='無頭騎士的不死心智著魔了!在萬鬼節期間，他對這座村子的攻擊頻繁而恐怖。', `FemaleText_loc7`='¡La mente no-muerta de El Jinete decapitado está obsesionada! Durante Halloween, sus ataques contra este pueblo son frecuentes y terribles.' WHERE `ID`=22061;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저주받은 기사가 마을을 공격하고 있어요! 누구든지 저주받은 기사를 처치하고 아이들을 구해주세요!', `FemaleText_loc4`='无头骑士要攻击村子了！谁能救救孩子们，谁能阻止它！', `FemaleText_loc5`='無頭騎士來攻擊村落了!得有人來保護這些孩子們並且阻止他!', `FemaleText_loc7`='¡El Jinete decapitado ataca el pueblo! ¡Alguien debe salvar a los niños y detenerle!' WHERE `ID`=22062;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저주받은 기사가 만드는 공포에서 벗어났군요, 당장은요. 이제 좀 살 것 같네요. 하지만 머리가 있을 때 해치우지 않으면 다시 돌아올 거예요.', `FemaleText_loc4`='现在，无头骑士对我们的威胁已经解除了。我们又可以呼吸到自由的空气了，但如果不能在有头的情况下击败它，它随时还会回来的。', `FemaleText_loc5`='我們現在暫時可免於無頭騎士的恐懼了。我們又可以自在呼吸了，不過在他和他的頭顱合而為一前，他都可能會回來。', `FemaleText_loc7`='De momento, hemos acabado con el terror de El Jinete decapitado. Podemos descansar en paz, pero solo hasta que llegue la oportunidad de vencerle a él y su cabeza, ya que volverá.' WHERE `ID`=22063;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇게 전쟁을 원한다면 기꺼이 치르도록 해주지, 과일 상인!', `MaleText_loc4`='如果你要战争，那么我们就成全你，给你战争，水果贩！', `MaleText_loc5`='如果戰爭就是你想要的話，那麼你所得到的就是戰爭，水果商人!', `MaleText_loc7`='¡SI QUIERES GUERRA, GUERRA TENDRÁS, FRUTERO!', `FemaleText_loc1`='그렇게 전쟁을 원한다면 기꺼이 치르도록 해주죠, 과일 상인!', `FemaleText_loc4`='如果你要战争，那么我们就成全你，给你战争，水果贩！', `FemaleText_loc5`='如果戰爭就是你想要的話，那麼你所得到的就是戰爭，水果商人!', `FemaleText_loc7`='¡SI QUIERES GUERRA, GUERRA TENDRÁS, FRUTERO!' WHERE `ID`=22064;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 데려온 오우거는 하나도 안 무섭소, 과일 상인! 내 전속 부대가 지금 오고 있거든!', `MaleText_loc4`='你的食人魔佣兵吓不倒我，水果贩！我的援军就要到了！', `MaleText_loc5`='你的巨魔嚇不倒我，水果商人!我的軍隊就在路上了!', `MaleText_loc7`='¡TU OGRO NO ME ASUSTA, FRUTERO! ¡MI EJÉRCITO ESTÁ DE CAMINO!', `FemaleText_loc1`='당신이 데려온 오우거는 하나도 안 무섭네요, 과일 상인! 내 전속 부대가 지금 오고 있거든요!', `FemaleText_loc4`='你的食人魔佣兵吓不倒我，水果贩！我的援军就要到了！', `FemaleText_loc5`='你的巨魔嚇不倒我，水果商人!我的軍隊就在路上了!', `FemaleText_loc7`='¡TU OGRO NO ME ASUSTA, FRUTERO! ¡MI EJÉRCITO ESTÁ DE CAMINO!' WHERE `ID`=22065;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살 날이 얼마 안 남았을 거다, 과일 상인! 네놈의 오우거 군대가 어떤지 다 알고 있다고!', `MaleText_loc4`='你的日子到头了！你的食人魔军团不堪一击！', `MaleText_loc5`='你的日子屈指可數了，水果商人!我對你的巨魔軍隊嘹若指掌!', `MaleText_loc7`='¡TIENES LOS DÍAS CONTADOS, FRUTERO! ¡SÉ LO DE TU EJÉRCITO OGRO!', `FemaleText_loc1`='살 날이 얼마 안 남았을 걸요, 과일 상인! 당신의 오우거 군대가 어떤지 다 알고 있다고요!', `FemaleText_loc4`='你的日子到头了！你的食人魔军团不堪一击！', `FemaleText_loc5`='你的日子屈指可數了，水果商人!我對你的巨魔軍隊嘹若指掌!', `FemaleText_loc7`='¡TIENES LOS DÍAS CONTADOS, FRUTERO! ¡SÉ LO DE TU EJÉRCITO OGRO!' WHERE `ID`=22066;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 누가 우리 강아지를 좀 찾아 줬으면 좋겠어요!', `MaleText_loc4`='$n，我真的希望有人能找到我的狗！', `MaleText_loc5`='$n，我真希望有人能找到我的狗!', `MaleText_loc7`='¡$n, espero que alguien encuentre a mi perro!' WHERE `ID`=22067;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 점심을 보고는 기쁜 듯이 짖어댑니다!', `MaleText_loc4`='%s看到午餐之后高兴地叫了起来！', `MaleText_loc5`='%s在看到他的午餐時開心的叫喊出來!', `MaleText_loc7`='¡%s aúlla de placer al ver su comida!' WHERE `ID`=22068;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 점심을 먹습니다.', `MaleText_loc4`='%s开心地吃着午餐。', `MaleText_loc5`='%s在吃他的午餐。', `MaleText_loc7`='%s se come su comida.' WHERE `ID`=22069;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 춤을 추며 고마워합니다.', `MaleText_loc4`='%s跳了一支特殊的舞蹈，对你表示感谢。', `MaleText_loc5`='%s以特別的舞蹈感謝你。', `MaleText_loc7`='%s te da las gracias con un baile especial.' WHERE `ID`=22070;
