UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어쩌다가 사촌 녀석은 가시덤불 골짜기의 화창한 해변에서 노닥대고 있게 된 걸까요?', `MaleText_loc4`='凭什么我的外甥每天都能享受荆棘谷的阳光和海滩呢？舅舅真是不好当。', `MaleText_loc5`='反正就是，為什麼我的親戚就可以享受荊棘谷的熱情海灘?', `MaleText_loc7`='¿Y por qué mi primo puede disfrutar de las suaves playas de Tuercespina?', `FemaleText_loc1`='어쩌다가 사촌 녀석은 가시덤불 골짜기의 화창한 해변에서 노닥대고 있게 된 걸까요?', `FemaleText_loc4`='凭什么我的外甥每天都能享受荆棘谷的阳光和海滩呢？舅舅真是不好当。', `FemaleText_loc5`='反正就是，為什麼我的親戚就可以享受荊棘谷的熱情海灘?', `FemaleText_loc7`='¿Y por qué mi primo puede disfrutar de las suaves playas de Tuercespina?' WHERE `ID`=22072;
