UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그롬골로 가는 비행선은 금방 여기에 도착할 겁니다.', `MaleText_loc4`='飞往格罗姆高的飞艇随时会靠港。', `MaleText_loc5`='前往格羅姆高的飛艇現在應該隨時會抵達這裡。', `MaleText_loc7`='El zepelín a Grom''gol debería llegar de un momento a otro.', `FemaleText_loc1`='그롬골로 가는 비행선은 금방 여기에 도착할 거예요.', `FemaleText_loc4`='飞往格罗姆高的飞艇随时会靠港。', `FemaleText_loc5`='前往格羅姆高的飛艇現在應該隨時會抵達這裡。', `FemaleText_loc7`='El zepelín a Grom''gol debería llegar de un momento a otro.' WHERE `ID`=22074;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그롬골로 가는 비행선이 방금 도착했습니다! 가시덤불 골짜기로 가시는 분들 모두 타세요!', `MaleText_loc4`='飞往格罗姆高的飞艇已经靠港了！要去荆棘谷的就赶快啦！', `MaleText_loc5`='前往格羅姆高的飛艇剛剛抵達!要到荊棘谷的乘客請上船!', `MaleText_loc7`='¡El zepelín a Grom''gol acaba de llegar! ¡Suban todos para ir a Tuercespina!', `FemaleText_loc1`='그롬골로 가는 비행선이 방금 도착했습니다! 가시덤불 골짜기로 가시는 분들 모두 타세요!', `FemaleText_loc4`='飞往格罗姆高的飞艇已经靠港了！要去荆棘谷的就赶快啦！', `FemaleText_loc5`='前往格羅姆高的飛艇剛剛抵達!要到荊棘谷的乘客請上船!', `FemaleText_loc7`='¡El zepelín a Grom''gol acaba de llegar! ¡Suban todos para ir a Tuercespina!' WHERE `ID`=22075;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기요! 비행선이 떠나기 전에 제가 잊지 않고 연료를 채웠던가요? 아, 이런!', `MaleText_loc4`='嘿！我到底给飞艇的油箱里加油了没有？有人能告诉我吗？好吧，随它去吧！', `MaleText_loc5`='嘿!我有記得在飛艇離開前重新加滿油槽嗎?喔，好吧!', `MaleText_loc7`='¡Hey! ¿Me acordé de llenar el depósito antes de que despegara el zepelín? ¡Oh, bueno!', `FemaleText_loc1`='저기요! 비행선이 떠나기 전에 제가 잊지 않고 연료를 채웠던가요? 아, 이런!', `FemaleText_loc4`='嘿！我到底给飞艇的油箱里加油了没有？有人能告诉我吗？好吧，随它去吧！', `FemaleText_loc5`='嘿!我有記得在飛艇離開前重新加滿油槽嗎?喔，好吧!', `FemaleText_loc7`='¡Hey! ¿Me acordé de llenar el depósito antes de que despegara el zepelín? ¡Oh, bueno!' WHERE `ID`=22076;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오그리마로 가는 비행선이 방금 도착했습니다! 듀로타로 가시는 분들 모두 타세요!', `MaleText_loc4`='飞往奥格瑞玛的飞艇已经靠港了！要去杜隆塔尔的就赶快啦！', `MaleText_loc5`='前往奧格瑪的飛艇剛剛抵達!要到杜洛塔的乘客請上船!', `MaleText_loc7`='¡El zepelín hacia Orgrimmar acaba de llegar! ¡Todos a bordo para ir a Durotar!', `FemaleText_loc1`='오그리마로 가는 비행선이 방금 도착했어요! 듀로타로 가시는 분들 모두 타세요!', `FemaleText_loc4`='飞往奥格瑞玛的飞艇已经靠港了！要去杜隆塔尔的就赶快啦！', `FemaleText_loc5`='前往奧格瑪的飛艇剛剛抵達!要到杜洛塔的乘客請上船!', `FemaleText_loc7`='¡El zepelín hacia Orgrimmar acaba de llegar! ¡Todos a bordo para ir a Durotar!' WHERE `ID`=22077;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금쯤은 비행선이 오그리마에 도착했겠군요. 몇 분 안에 다시 올 겁니다.', `MaleText_loc4`='飞艇应该是刚刚到达奥格瑞玛。再等一小会儿吧……', `MaleText_loc5`='飛艇才剛抵達奧格瑪而已。應該會在幾分鐘後回來...', `MaleText_loc7`='El zepelín debería haber llegado a Orgrimmar hace poco. Estará de vuelta en unos minutos...', `FemaleText_loc1`='비행선이 지금쯤은 오그리마에 도착했겠죠. 몇 분 있으면 다시 올 거예요.', `FemaleText_loc4`='飞艇应该是刚刚到达奥格瑞玛。再等一小会儿吧……', `FemaleText_loc5`='飛艇才剛抵達奧格瑪而已。應該會在幾分鐘後回來...', `FemaleText_loc7`='El zepelín debería haber llegado a Orgrimmar hace nada. Estará de vuelta en unos minutos...' WHERE `ID`=22078;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='듀로타에서 근무하는 우리 형이 잘 지내고 있으면 좋겠어요. 그쪽에는 냄새 나는 오크들이 아주 많거든요... 그렇다고 여기가 제일 좋다는 말은 아니지만요.', `MaleText_loc4`='真希望我的兄弟在杜隆塔尔没搞出什么乱子。那边臭烘烘的兽人太多了……不过，这里也不怎么轻松啊……', `MaleText_loc5`='我希望我的兄弟在杜洛塔過得還不錯。那裡有很多友善的獸人...再說，這也不是最好的小艇...', `MaleText_loc7`='Espero que a mi hermano le vaya bien en Durotar. Hay un montón de orcos malolientes allí... Claro que esto tampoco es exactamente un chollo...', `FemaleText_loc1`='듀로타에서 근무하는 우리 오빠가 잘 지내고 있으면 좋겠어요. 그쪽에는 냄새 나는 오크들이 아주 많거든요... 그렇다고 여기가 제일 좋다는 말은 아니지만요.', `FemaleText_loc4`='真希望我的兄弟在杜隆塔尔没搞出什么乱子。那边臭烘烘的兽人太多了……不过，这里也不怎么轻松啊……', `FemaleText_loc5`='我希望我的兄弟在杜洛塔過得還不錯。那裡有很多友善的獸人...再說，這也不是最好的小艇...', `FemaleText_loc7`='Espero que a mi hermano le vaya bien en Durotar. Hay un montón de orcos malolientes allí... Claro que esto tampoco es exactamente un chollo...' WHERE `ID`=22079;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오그리마행 비행선이 저기 가는군요. 이번에는 폭발하지 않았으면 좋겠습니다.', `MaleText_loc4`='前往奥格瑞玛的飞艇已经出发啦。希望这次它不会爆炸。', `MaleText_loc5`='前往奧格瑪的飛艇來了。我希望這次沒有爆炸了。', `MaleText_loc7`='Ahí va el zepelín a Orgrimmar. Espero que esta vez no haya explosiones.', `FemaleText_loc1`='오그리마행 비행선이 저기 가는군요. 이번에는 폭발하지 않았으면 좋겠네요.', `FemaleText_loc4`='前往奥格瑞玛的飞艇已经出发啦。希望这次它不会爆炸。', `FemaleText_loc5`='前往奧格瑪的飛艇來了。我希望這次沒有爆炸了。', `FemaleText_loc7`='Ahí va el zepelín a Orgrimmar. Espero que esta vez no haya explosiones.' WHERE `ID`=22080;
