UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저주받은 기사가 공격하고 있어요! 불길이 마을 전체를 삼켜버릴 듯해요! 어쩌면 좋죠?', `FemaleText_loc4`='无头骑士发动了攻击！火焰可能会吞噬整个村落！我们该怎么办？', `FemaleText_loc5`='無頭騎士發動攻擊了!揚言要燒掉整個村莊!我們要怎麼辦?', `FemaleText_loc7`='¡El Jinete decapitado ataca! ¡El fuego amenaza con consumir el pueblo por completo! ¿Qué vamos a hacer?' WHERE `ID`=22091;
