UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비행선은 언더시티를 막 떠났을 겁니다.', `MaleText_loc4`='飞艇应该是刚刚从幽暗城起航。', `MaleText_loc5`='飛艇應該才剛從幽暗城離開而已。', `MaleText_loc7`='El zepelín debería haber salido de Entrañas hace poco.', `FemaleText_loc1`='비행선은 언더시티를 막 떠났을 거예요.', `FemaleText_loc4`='飞艇应该是刚刚从幽暗城起航。', `FemaleText_loc5`='飛艇應該才剛從幽暗城離開而已。', `FemaleText_loc7`='El zepelín debería haber salido de Entrañas hace nada.' WHERE `ID`=22095;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 그롬골에 가 본 적이 없습니다. 이건 정말 불공평하다고요. 따뜻하고 김이 모락모락 나는 해변... 악어, 랩터... 음... 생각해보니 정말로 거기 가고 싶은 건 아닌 거 같군요.', `MaleText_loc4`='我还没去过格罗姆高呢。这不公平！温暖的沙滩……向着夕阳奔跑的鳄鱼与迅猛龙……啊……等等……或许还是不要去了吧。', `MaleText_loc5`='我從沒到過格羅姆高。真不公平。溫暖，熱情的海灘...鱷魚，迅猛龍...嗯嗯嗯...也許終究我不是真的想到那裡去。', `MaleText_loc7`='Nunca consigo que me lleven a Grom''gol. Es tan injusto. Playas cálidas y vaporosas... Crocoliscos, raptores... hmmm puede que después de todo no tenga tantas ganas de ir.', `FemaleText_loc1`='전 그롬골에 가 본 적이 없어요. 이건 정말 불공평하다고요. 따뜻하고 김이 모락모락 나는 해변... 악어, 랩터... 음... 생각해보니 정말로 거기 가고 싶은 건 아닌 거 같네요.', `FemaleText_loc4`='我还没去过格罗姆高呢。这不公平！温暖的沙滩……向着夕阳奔跑的鳄鱼与迅猛龙……啊……等等……或许还是不要去了吧。', `FemaleText_loc5`='我從沒到過格羅姆高。真不公平。溫暖，熱情的海灘...鱷魚，迅猛龍...嗯嗯嗯...也許終究我不是真的想到那裡去。', `FemaleText_loc7`='Nunca consigo que me lleven a Grom''gol. Es tan injusto. Playas cálidas y vaporosas... Crocoliscos, raptores... hmmm puede que después de todo no tenga tantas ganas de ir.' WHERE `ID`=22096;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그롬골행 비행선이 지금 막 도착했습니다! 가시덤불 골짜기로 가시는 분들은 어서 승선하십시오!', `MaleText_loc4`='飞往格罗姆高的飞艇已经靠港了！要去荆棘谷的就赶快啦！', `MaleText_loc5`='前往格羅姆高的飛艇剛剛抵達!要到荊棘谷的乘客請上船!', `MaleText_loc7`='¡El zepelín a Grom''gol acaba de llegar! ¡Suban todos para ir a Tuercespina!', `FemaleText_loc1`='그롬골행 비행선이 지금 막 도착했어요! 가시덤불 골짜기로 가시는 분들은 어서 승선하세요!', `FemaleText_loc4`='飞往格罗姆高的飞艇已经靠港了！要去荆棘谷的就赶快啦！', `FemaleText_loc5`='前往格羅姆高的飛艇剛剛抵達!要到荊棘谷的乘客請上船!', `FemaleText_loc7`='¡El zepelín a Grom''gol acaba de llegar! ¡Suban todos para ir a Tuercespina!' WHERE `ID`=22097;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서두르세요! 가시덤불 골짜기로 가는 다음 비행선이 곧 출발합니다!', `MaleText_loc4`='快，下一班去荆棘谷的飞艇马上就要出发了！', `MaleText_loc5`='別遲到，下一艘前往荊棘谷的船在一分鐘後離開!', `MaleText_loc7`='¡No te retrases, el próximo viaje hacia Tuercespina sale dentro de un minuto!', `FemaleText_loc1`='서두르세요! 가시덤불 골짜기로 가는 다음 비행선이 곧 출발합니다!', `FemaleText_loc4`='快，下一班去荆棘谷的飞艇马上就要出发了！', `FemaleText_loc5`='別遲到，下一艘前往荊棘谷的船在一分鐘後離開!', `FemaleText_loc7`='¡No te retrases, el próximo viaje hacia Tuercespina sale dentro de un minuto!' WHERE `ID`=22098;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언더시티행 비행선이 지금 막 도착했습니다! 티리스팔 숲으로 가시는 분들은 어서 승선하십시오!', `MaleText_loc4`='飞往幽暗城的飞艇已经靠港了！要去提瑞斯法林地的就赶快啦！', `MaleText_loc5`='前往幽暗城的飛艇剛剛抵達!要到提里斯法林地的乘客請上船!', `MaleText_loc7`='¡El zepelín hacia Entrañas acaba de llegar! ¡Todos a bordo para ir a los Claros de Tirisfal!', `FemaleText_loc1`='언더시티행 비행선이 지금 막 도착했어요! 티리스팔 숲으로 가시는 분들은 어서 승선하세요!', `FemaleText_loc4`='飞往幽暗城的飞艇已经靠港了！要去提瑞斯法林地的就赶快啦！', `FemaleText_loc5`='前往幽暗城的飛艇剛剛抵達!要到提里斯法林地的乘客請上船!', `FemaleText_loc7`='¡El zepelín hacia Entrañas acaba de llegar! ¡Todos a bordo para ir a los Claros de Tirisfal!' WHERE `ID`=22099;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='유서 깊은 티리스팔 숲으로 가는 비행선이 지금 막 도착했습니다! 죽기 전에 최신 포세이큰 패션을 경험하시죠!', `MaleText_loc4`='飞往提瑞斯法林的飞艇已经靠港了！一定要穿上被遗忘者最流行的服饰去冒险呀！', `MaleText_loc5`='前往歷史著名的幽暗城飛艇剛剛抵達!要死就要用最熱門的被遺忘者死法!', `MaleText_loc7`='¡El zepelín a los históricos Claros de Tirisfal acaba de llegar! ¡Qué no os pille la muerte sin lo último en moda renegada!', `FemaleText_loc1`='유서 깊은 티리스팔 숲으로 가는 비행선이 지금 막 도착했어요! 죽기 전에 최신 포세이큰 패션을 경험하세요!', `FemaleText_loc4`='飞往提瑞斯法林的飞艇已经靠港了！一定要穿上被遗忘者最流行的服饰去冒险呀！', `FemaleText_loc5`='前往歷史著名的幽暗城飛艇剛剛抵達!要死就要用最熱門的被遺忘者死法!', `FemaleText_loc7`='¡El zepelín a los históricos Claros de Tirisfal acaba de llegar! ¡Qué no os pille la muerte sin lo último en moda renegada!' WHERE `ID`=22100;
