UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 유인물을 그냥 쓰레기통에 버리는 건 너무 아깝잖아요. 그렇지 않나요?', `FemaleText_loc4`='若是白白浪费掉这些传单就太可惜啦，不是吗？', `FemaleText_loc5`='讓這些傳單白費了是一件可惜的事，對吧?', `FemaleText_loc7`='Sería una pena desaprovechar estos panfletos, ¿verdad?' WHERE `ID`=22105;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 온종일 비행선 부품을 회수했는데 말입니다, 프레자는 시급을 챙겨주는 염치도 없답니다. 그 일로 오신 건 아니지요? 비행선이 어디 있는지 알고 싶으신 거죠? 여하튼 운이 좋으시군요. 저한테 비행선 추적기가 있거든요!', `MaleText_loc4`='我整天都在收集飞艇零件。就这样，弗雷萨还不肯给我加点薪水。至于你，你肯定不是来跟我抢工作的，对吧？我猜你想知道飞艇现在的位置在哪。总之，你运气不错，我这里就有个飞艇追踪装置了！', `MaleText_loc5`='我花了整天的時間在回收飛艇的零件，但弗雷薩卻連適度的付我鐘點費都不肯。不過你不是為此而來這的，對吧?我打賭你想要知道飛艇坐落的地點。好吧，算你走運 - 我手邊剛好有飛艇追蹤裝置!', `MaleText_loc7`='Me paso el día buscando piezas para el zepelín y Frezza no tiene ni la decencia de pagarme por horas. Pero tú no has venido por eso, ¿verdad? Apuesto a que quieres saber dónde está ahora el zepelín. ¡Estás de suerte, tengo mi dispositivo de seguimiento de zepelines aquí!', `FemaleText_loc1`='전 온종일 비행선 부품을 회수했는데 말이에요, 프레자는 시급을 챙겨주는 염치도 없답니다. 당신 그 일로 온 건 아니죠? 비행선이 어디 있는지 알고 싶으신 거죠? 여하튼 운이 좋으시네요. 저한테 비행선 추적기가 있거든요!', `FemaleText_loc4`='我整天都在收集飞艇零件。就这样，弗雷萨还不肯给我加点薪水。至于你，你肯定不是来跟我抢工作的，对吧？我猜你想知道飞艇现在的位置在哪。总之，你运气不错，我这里就有个飞艇追踪装置了！', `FemaleText_loc5`='我花了整天的時間在回收飛艇的零件，但弗雷薩卻連適度的付我鐘點費都不肯。不過你不是為此而來這的，對吧?我打賭你想要知道飛艇坐落的地點。好吧，算你走運 - 我手邊剛好有飛艇追蹤裝置!', `FemaleText_loc7`='Me paso el día buscando piezas para el zepelín y Frezza no tiene ni la decencia de pagarme por horas. Pero tú no has venido por eso, ¿verdad? Apuesto a que quieres saber dónde está ahora el zepelín. ¡Estás de suerte, tengo mi dispositivo de seguimiento de zepelines aquí!' WHERE `ID`=22106;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='조금만 창의적으로 손보면 훨씬 유용하답니다...', `FemaleText_loc4`='只要加入一点创造性的改变，它们会变得更有用……', `FemaleText_loc5`='只要一點點創意的編排，這些東西就會變得更有用...', `FemaleText_loc7`='Con un poquito de edición creativa son mucho más útiles...' WHERE `ID`=22107;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언더시티행 비행선은 지금 어디쯤 있습니까?', `MaleText_loc4`='去往幽暗城的飞艇目前在哪里？', `MaleText_loc5`='前往幽暗城的飛艇現在在哪?', `MaleText_loc7`='¿Dónde está ahora el zepelín a Entrañas?', `FemaleText_loc1`='언더시티행 비행선은 지금 어디쯤 있나요?', `FemaleText_loc4`='去往幽暗城的飞艇目前在哪里？', `FemaleText_loc5`='前往幽暗城的飛艇現在在哪?', `FemaleText_loc7`='¿Dónde está ahora el zepelín a Entrañas?' WHERE `ID`=22108;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그롬골행 비행선은 지금 어디쯤 있습니까?', `MaleText_loc4`='去往格罗姆高的飞艇目前在哪里？', `MaleText_loc5`='前往格羅姆高的飛艇現在在哪?', `MaleText_loc7`='¿Dónde está ahora el zepelín a Grom''gol?', `FemaleText_loc1`='그롬골행 비행선은 지금 어디쯤 있나요?', `FemaleText_loc4`='去往格罗姆高的飞艇目前在哪里？', `FemaleText_loc5`='前往格羅姆高的飛艇現在在哪?', `FemaleText_loc7`='¿Dónde está ahora el zepelín a Grom''gol?' WHERE `ID`=22109;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희 운동에 동참해 주십시오!', `MaleText_loc4`='请考虑一下我们的提议吧！', `MaleText_loc5`='請考慮參與我們的目標!', `MaleText_loc7`='¡Por favor considera unirte a nuestra causa!', `FemaleText_loc1`='이 유인물을 읽어 보시고 저희 운동에 동참해 주세요!', `FemaleText_loc4`='请收下这份传单，考虑一下我们的提议吧！', `FemaleText_loc5`='請拿一張傳單並考慮加入我們的目標!', `FemaleText_loc7`='¡Por favor considera unirte a nuestra causa!' WHERE `ID`=22110;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 고맙소.', `MaleText_loc4`='嗨，谢谢。', `MaleText_loc5`='嘿，謝了。', `MaleText_loc7`='Hey, gracias.', `FemaleText_loc1`='오, 고마워요.', `FemaleText_loc4`='嗨，谢谢。', `FemaleText_loc5`='嘿，謝了。', `FemaleText_loc7`='Hey, gracias.' WHERE `ID`=22111;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 유인물을 읽습니다.', `MaleText_loc4`='%s读着传单。', `MaleText_loc5`='%s在看這張傳單。', `MaleText_loc7`='%s lee el panfleto.', `FemaleText_loc1`='%s|1이;가; 유인물을 읽습니다.', `FemaleText_loc4`='%s读着传单。', `FemaleText_loc5`='%s在看這張傳單。', `FemaleText_loc7`='%s lee el panfleto.' WHERE `ID`=22112;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거... 웃자고 하는 소리겠지. 아니오?', `MaleText_loc4`='这……这只是个玩笑吧？', `MaleText_loc5`='這...這是個玩笑，對吧?', `MaleText_loc7`='Esto... esto es una broma, ¿verdad?', `FemaleText_loc1`='지금 농담하시는 거죠? 그렇죠?', `FemaleText_loc4`='这……这只是个玩笑吧？', `FemaleText_loc5`='這...這是個玩笑，對吧?', `FemaleText_loc7`='Esto... esto es una broma, ¿verdad?' WHERE `ID`=22113;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금껏 읽어본 것들 중에 가장 웃기군. 아주 즐거웠소!', `MaleText_loc4`='我很久没读到过这么好笑的东西啦。你是来逗我开心的吧？', `MaleText_loc5`='那是我這麼久以來看到最好笑的事了。你實在讓我很開心!', `MaleText_loc7`='Esto es lo más divertido que he leído en mucho tiempo. ¡Me has alegrado el día!', `FemaleText_loc1`='지금껏 읽어본 것들 중에 제일 웃겼어요. 아주 즐거웠어요!', `FemaleText_loc4`='我很久没读到过这么好笑的东西啦。你是来逗我开心的吧？', `FemaleText_loc5`='那是我這麼久以來看到最好笑的事了。你實在讓我很開心!', `FemaleText_loc7`='Esto es lo más divertido que he leído en mucho tiempo. ¡Me has alegrado el día!' WHERE `ID`=22114;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신들 모두 정신이 어떻게 된 거 아니오? 정말 이렇게 생각한단 말이오?', `MaleText_loc4`='一群疯子！你们真的相信这东西吗？', `MaleText_loc5`='真是一群瘋子!你真的相信這種東西嗎?', `MaleText_loc7`='¡Menuda panda de lunáticos! ¿De verdad os creéis esto?', `FemaleText_loc1`='당신들 모두 정신이 어떻게 된 거 아니에요? 정말 이렇게 생각한단 말이에요?', `FemaleText_loc4`='一群疯子！你们真的相信这东西吗？', `FemaleText_loc5`='真是一群瘋子!你真的相信這種東西嗎?', `FemaleText_loc7`='¡Menuda panda de lunáticos! ¿De verdad os creéis esto?' WHERE `ID`=22115;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 절대 이딴 일에 동참하지 않을 거요. 하지만 이건 가져가겠소. 화장실에서 쓰기 딱 좋은 재질이로군...', `MaleText_loc4`='我永远都不会参与这样的组织。不过最好留着这个。这东西迟早有用……', `MaleText_loc5`='我從未參與過這樣的事。不過，最好是把這留住。私底下會用得到...', `MaleText_loc7`='Nunca me uniría a nada así. Mejor guardar esto. Puede ser de utilidad en el baño...', `FemaleText_loc1`='저는 절대 이런 일에 동참하지 않을 거예요. 하지만 이건 가져가는 게 좋겠네요. 마침 휴지가 다 떨어졌으니 말이죠...', `FemaleText_loc4`='我永远都不会参与这样的组织。不过最好留着这个。这东西迟早有用……', `FemaleText_loc5`='我從未參與過這樣的事。不過，最好是把這留住。私底下會用得到...', `FemaleText_loc7`='Nunca me uniría a nada así. Mejor guardar esto. Puede ser de utilidad en el baño...' WHERE `ID`=22116;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기, 이봐! 그래 당신! 내가 지금은 좀 상태가 좋지 않지만 곧 벌떡 일어날 거라고! 이리로 와서 내가 가진 것 좀 봐. 여기 엄청나게 희귀하고 멋진 목걸이들이 있다고! 덤도 주지! 이리 오게, 이리 오라고. 구경하고 싶은 거 다 안다니까 그러네.', `MaleText_loc4`='嗨……嗨……嗨！就是你！我也许看上去很萎靡，但我肯定会东山再起的！过来看看我有些什么。最最珍贵和最最不可思议的护身符就在这里！我甚至还弄到了些新玩意！过来，过来，你知道你想要看看的。', `MaleText_loc5`='嘿...嘿...嗨!就是你!我也許失志，但是我會東山再起的!過來這裡看看我弄到的東西。最稀有且最神奇的護符，就在這裡!我還有一些額外的東西!來吧，來吧，你知道你想看一下。', `MaleText_loc7`='¡Je... je...hey! ¡Tú! ¡Puede que esté hundido, pero me levantaré! Ven y mira lo que tengo. ¡Los amuletos más extraños y maravillosos, justo aquí! ¡Hasta he recogido algunos pedacitos extra! Vamos, vamos, sabes que quieres verlos.' WHERE `ID`=22117;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 어때, $r 친구? $G 당신:당신 애인;한테 뭐가 필요한지 알잖나? 바로 꽃이지! 신비한 테로카르 숲에서 방금 가져온 라일락은 어떤가? 이거 귀한 거라고! 엄청나게 귀한 거야! 내 주위를 좀 둘러보게. 하나도 없지 않나? 아름다운 여성에게는 아름다운 꽃을! 그렇지? 맞지?', `MaleText_loc4`='看看这个，$r！你知道你的爱人需要些什么吗？一朵这样的花，一朵只生长在神秘的泰罗卡森林的丁香花。稀有！如此稀有！你在别处可找不到这样的花？名花配美人，不是吗？难·道·不·是·吗？', `MaleText_loc5`='看看這個，$r!你知道$G你:你的甜心;需要什麼嗎?就是這些花。紫丁香，來自於神秘的泰洛卡森林!稀有!非常的稀有!你在我身邊並沒有看到任何紫丁香，對吧?美麗的花給美麗的女士，對吧?對吧?', `MaleText_loc7`='¡Mira esto, $r! ¿Sabes lo que necesita tu amorcito? Una de estas flores. ¡Lilas recién sacadas del místico Bosque de Terokkar! ¡Nada comunes! No ves ninguna por aquí, ¿verdad? Una flor bonita, para una chica bonita, ¿verdad? ¿Verdad?' WHERE `ID`=22118;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놀라운 목걸이를 구경해보게! 정말 희귀한 작품일세! 오랜 세월에 걸쳐 검증을 받은 그립타 가문의 진정한 솜씨 앞에서는 최신 세공 기술도 어린애 장난에 불과하지! 마법 부적을 저렴한 가격에 구입해서 능력을 향상시킬 절호의 기회라고!', `MaleText_loc4`='神奇的护身符！惊人的古玩！格里伏塔……最新……进货的，由经过时间考验的神奇材质做成的新奇珠宝制品！用这些不可思议的法宝来让你自己变得更强大吧，破盘价出售啦！', `MaleText_loc5`='驚人的護符!奇妙的珍品!最新的寶石設計師都不知道且真正神秘的樣式，來自...呃...最近剛搬遷的格利夫塔!用最便宜的價錢就可以有這些神奇的法寶來增強你自己!', `MaleText_loc7`='¡Amuletos maravillosos! ¡Curiosidades increíbles! ¡Los joyeros modernos no tienen nada que hacer contra los métodos místicos del... eehhh... uhm... recién trasladado Griftah! ¡Mejórate con estos talismanes mágicos a precio de ganga!' WHERE `ID`=22119;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알았어, 알았어, 무슨 생각 하는지 알겠네. ''이건 나뭇가지잖아!''라고 생각하고 있지? 하지만 이건 보통 나뭇가지가 아니야, 절대로 아니지! 자네가 지금 보는 나뭇가지는 말이야, 이 세상을 창조한 그 힘이 만든 아주 희귀하고 특별한 물건이라고! 숭고한 힘이 스쳐 지나간 드레노어의 이 환상적인 일부분이 갖고 싶을 게지, 그럴 거야. 이 정도면 거의 거저라고!', `MaleText_loc4`='好吧，好吧，我知道你在想什么。这是根棍子，但它绝不是一根普通的棍子，绝不是！$c，你在这里看到的是一根非常非常稀有，非常非常珍贵，以这个世界特别的力量精炼而成的棍子！你想拥有这被华丽的力量触及过的德拉诺神器吗？我知道你想。千万不要错过了，如果你错过了，那么恭喜你！你买不到了。', `MaleText_loc5`='好，好，我知道你在想什麼。這是根木棒。不過這並不是普通的木棒，不是!你現在所看到的，$c，是隻奇妙少見且價值非凡的木棒，由運作這個世界的極大力量所製作出來!你想要擁有這個驚人的德拉諾物品，被壯觀的力量所觸碰，我知道你會想這麼做。我幾乎都把他們送人了!', `MaleText_loc7`='Vale, vale, sé lo que estás pensando. Esto es un palo. Pero no es un palo NORMAL, ¡no! Lo que ves aquí, $c, es un palo muy poco común y de valor extraordinario, hecho por los mismos poderes que formaron el mundo. Sé que quieres poseer esta fantástica pieza de Draenor, tocada por un magnífico poder. ¡Casi las estoy regalando!' WHERE `ID`=22120;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 자네, 기다려! 최근에 시장 간 적 있나? 내 상품들 꽤 괜찮지? 이봐, 어디 가는 거야?', `MaleText_loc4`='嗨，$c！等等！最近你去市场逛过吗？我的摊位还好吧？', `MaleText_loc5`='嘿，等等，$c!你最近有到過市場嗎?我的攤位還不錯吧，對不對?還在那裡嗎?', `MaleText_loc7`='¡Espera, $c! ¿Has pasado últimamente por el mercado? Mi puesto está bien, ¿verdad? ¿Sigue allí?' WHERE `ID`=22121;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도시 바깥에서까지 나를 쫓다니 믿을 수가 없군. 내가 난민이라도 돼야 하나? 난민 그립타라니! 내가 ''기업적인'' 난민이 된다면 그건 내 탓이 아니라고...', `MaleText_loc4`='我不敢相信他们竟然把我赶出了沙塔斯城。那里难道不是贫民窟吗？我，格里伏塔也是难民啊！不是我的错，我只是个有事业心的难民……', `MaleText_loc5`='我無法相信他們在城外追捕我。這不是應該是個難民營嗎?老格利夫塔是個難民!當個有事業心的難民不是我的錯...', `MaleText_loc7`='No puedo creer que me estéis echando de la ciudad. ¿Es que no es un refugio? El viejo Griftah es un refugiado. No es culpa mía ser un refugiado EMPRESARIO...' WHERE `ID`=22122;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 자네가 무슨 생각을 하는지 알겠네. 이 늙은 그립타에게 문제가 생겼다, 이거지? 이건 아무것도 아니야. 아직 남은 물건이 많다고. 그러니 이리 와서 구경하게.', `MaleText_loc4`='现在，我知道你在想什么了。格里伏塔有些麻烦，但这不算什么。我身边仍然有着很多库存。过来看看我有些什么吧。', `MaleText_loc5`='現在，我知道你在想什麼。老格利夫塔身陷困難中。這沒什麼。我自己本身有許多貨品，所以來我這看看有些什麼吧。', `MaleText_loc7`='Sé lo que estáis pensando: el viejo Griftah es un foco de problemas. Eso no es nada. Aún tengo muchas mercancías, así que ven a ver lo que tengo.' WHERE `ID`=22123;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그립타로 알려진 상인이 사기 행위로 도시에서 쫓겨났습니다. 그자가 팔던 잡동사니를 자세히 조사해야 합니다. 이 물건들을 건드리지 마시고 저희가 조사를 계속하게 해 주십시오.', `MaleText_loc4`='商人格里伏塔因多次诈骗顾客，被判驱逐出沙塔斯城。我们要仔细检查他出售的这些小玩意儿。请配合我们的工作，离开他的摊位。', `MaleText_loc5`='名為格利夫塔的商人已經因其詐欺的行為而被逐出這個城市。我們打算非常小心的重新簡視那些他販賣的小飾品。請保持他的攤位淨空好讓我們進行我們的工作。', `MaleText_loc7`='El mercader conocido como Griftah ha sido exiliado de esta ciudad por sus actividades fraudulentas. Tenemos intención de revisar estos pequeños chismes con mucho cuidado. Por favor, no toques este puesto y déjanos hacer nuestro trabajo.' WHERE `ID`=22124;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기엔 볼 게 없으니 가던 길이나 가십시오.', `MaleText_loc4`='没什么好看的。走开。', `MaleText_loc5`='這裡沒什麼好看的。走開。', `MaleText_loc7`='Aquí no hay nada que ver. Muévete.' WHERE `ID`=22125;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자자, 이 물건들은 공식적으로 조사하고 있으니 거리를 유지해 주십시오.', `MaleText_loc4`='这个摊位正在接受官方的调查。请离这里远点。', `MaleText_loc5`='這個攤位正在進行公務調查中。請保持距離。', `MaleText_loc7`='Este puesto está oficialmente bajo investigación. Mantente alejado.' WHERE `ID`=22126;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='걱정하실 것 없습니다. 여기서 장식품을 팔던 그 사기꾼 녀석은 우리의 아름다운 도시에서 쫓겨났으니까요.', `MaleText_loc4`='你不用担心——那个在这里叫卖“货物”的骗子已经被赶出我们美丽的城市了。', `MaleText_loc5`='你不需要擔心 - 在這裡兜售他的「貨品」的人已被逐出我們美麗的城市了。', `MaleText_loc7`='No tienes que preocuparte – el estafador que traficaba con sus "mercancías" aquí, ha sido exiliado de nuestra justa ciudad.' WHERE `ID`=22127;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='까다로운 검사를 진행 중이니 이 물건들과 거리를 유지해 주십시오.', `MaleText_loc4`='请离开这个摊位。这里正在接受调查。', `MaleText_loc5`='請離開這個攤位;那裡正在進行仔細的盤查中。', `MaleText_loc7`='Mantente alejado de este puesto, hay una delicada investigación en curso.' WHERE `ID`=22128;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 사람들의 걱정에 귀를 기울이지 않는다는 말이 더는 나오지 않도록 하십시오. 이 ''그립타''란 녀석 하나 때문에 생긴 헛소문을 없애야 합니다.', `MaleText_loc4`='我们绝不能落下不听从民众意见的口实。这个“骗子”制造了很多虚假的宣传，现在我们要把事情都纠正过来。', `MaleText_loc5`='千萬不要落人口實說我們沒有在傾聽人民的關心。「格利夫塔」這個人已經做出了不實的發言，而我們打算導正所有事情。', `MaleText_loc7`='Que no se diga que no hacemos caso de las preocupaciones de la gente. Este sujeto "Griftah" ha declarado mentiras y tenemos intención de arreglar las cosas.' WHERE `ID`=22129;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주의를 기울이십시오, $r. 고약한 녀석들이 있으니까요.', `MaleText_loc4`='小心点，$r，有个令人讨厌的家伙在那里。', `MaleText_loc5`='保持警戒，$r;那裡有名聲不好的人物在活動著。', `MaleText_loc7`='Mantente alerta, $r; hay indeseables por aquí.' WHERE `ID`=22130;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 문밖을 여행하려거든 정신 바짝 차리십시오. 화려하게 차려입은 트롤이 당신에게 접근하려고 할 겁니다. 그자가 자신에게 딱 맞는 곳을 유랑하도록 내버려 두십시오.', `MaleText_loc4`='如果你要出城冒险的话，$c，小心那个衣着光鲜的巨魔，他可能会尝试接近你。不要理他，让他在那里享受他应得的放逐吧。', `MaleText_loc5`='你可以到門外去闖一闖，$c，要小心;一個穿著華麗的食人妖可能會試著接近你。把他留在他本應待著的流放地。', `MaleText_loc7`='Si sales fuera de las puertas, $c, mantente alerta, un trol vestido de manera estridente podría intentar acercarse a ti. Déjale en su exilio que es donde debe estar.' WHERE `ID`=22131;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발리브루는 아제로스 최고의 양조장이죠!', `MaleText_loc4`='麦酒，艾泽拉斯最好的酒！', `MaleText_loc5`='麥酒，艾澤拉斯最好的酒坊!', `MaleText_loc7`='¡Cebadiz, la mejor cervecería de Azeroth!', `FemaleText_loc1`='발리브루는 아제로스 최고의 양조장이에요!', `FemaleText_loc4`='麦酒，艾泽拉斯最好的酒！', `FemaleText_loc5`='麥酒，艾澤拉斯最好的酒坊!', `FemaleText_loc7`='¡Cebadiz, la mejor cervecería de Azeroth!' WHERE `ID`=22132;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이리 와서 발리브루의 흑맥주를 드셔보시죠!', `MaleText_loc4`='过来试试我们的黑麦酒吧！', `MaleText_loc5`='來試試我們的濃麥酒喔!', `MaleText_loc7`='¡Ven a probar nuestra negra de Cebadiz!', `FemaleText_loc1`='이리 와서 발리브루의 흑맥주를 드셔보세요!', `FemaleText_loc4`='过来试试我们的黑麦酒吧！', `FemaleText_loc5`='來試試我們的濃麥酒喔!', `FemaleText_loc7`='¡Ven a probar nuestra negra de Cebadiz!' WHERE `ID`=22133;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발리브루는 양조계의 기술 혁신을 이끌어 왔습니다. 발리브루의 신상품 청맥주를 드셔보시죠!', `MaleText_loc4`='麦酒引领了酿酒工艺的革新。来试试我们最新的产品，纯正的麦酒！', `MaleText_loc5`='麥酒在酒坊革新中一直都是領導者。來看看我們最新的作品，清麥酒!', `MaleText_loc7`='Los Cebadiz siempre han sido líderes en innovación en cervecerías. ¡Prueba nuestra nueva creación: la rubia de Cebadiz!', `FemaleText_loc1`='발리브루는 양조계의 기술 혁신을 이끌어 왔죠. 발리브루의 신상품 청맥주를 드셔보세요!', `FemaleText_loc4`='麦酒引领了酿酒工艺的革新。来试试我们最新的产品，纯正的麦酒！', `FemaleText_loc5`='麥酒在酒坊革新中一直都是領導者。來看看我們最新的作品，清麥酒!', `FemaleText_loc7`='Los Cebadiz siempre han sido líderes en innovación en cervecerías. ¡Prueba nuestra nueva creación: la rubia de Cebadiz!' WHERE `ID`=22134;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='썬더브루는 양조 업계에서 최고지.', `MaleText_loc4`='雷霆啤酒，全世界最好的啤酒。', `MaleText_loc5`='雷酒，所有國度中最好的酒坊。', `MaleText_loc7`='¡Cebatruenos, la mejor destilería de todos los reinos!', `FemaleText_loc1`='썬더브루는 양조 업계에서 최고예요.', `FemaleText_loc4`='雷霆啤酒，全世界最好的啤酒。', `FemaleText_loc5`='雷酒，所有國度中最好的酒坊。', `FemaleText_loc7`='¡Cebatruenos, la mejor destilería de todos los reinos!' WHERE `ID`=22135;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='썬더! 썬더! 썬더! 썬더브루, 야호!', `MaleText_loc4`='雷霆！雷霆！雷霆！雷霆啤酒，哈！', `MaleText_loc5`='雷!雷!雷!雷酒，嘿!', `MaleText_loc7`='¡TRUENOS! ¡TRUENOS! ¡TRUENOS! ¡CEBATRUENOS HO!', `FemaleText_loc1`='썬더! 썬더! 썬더! 썬더브루, 야호!', `FemaleText_loc4`='雷霆！雷霆！雷霆！雷霆啤酒，哈', `FemaleText_loc5`='雷!雷!雷!雷酒，嘿!', `FemaleText_loc7`='¡TRUENOS! ¡TRUENOS! ¡TRUENOS! ¡CEBATRUENOS HO!' WHERE `ID`=22136;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시원한 게 필요한 모양인데, 썬더브루가 시원하게 목을 축여 주지!', `MaleText_loc4`='你似乎需要一杯冰镇啤酒，雷霆啤酒是你最好的选择！', `MaleText_loc5`='你看來好像能夠來點冷飲，雷酒合你所需!', `MaleText_loc7`='Parece que te vendría bien una fría. ¡Cebatruenos se encargará de eso!', `FemaleText_loc1`='시원한 게 필요하신 모양인데, 썬더브루가 시원하게 목을 축여 드려요!', `FemaleText_loc4`='你似乎需要一杯冰镇啤酒，雷霆啤酒是你最好的选择！', `FemaleText_loc5`='你看來好像能夠來點冷飲，雷酒合你所需!', `FemaleText_loc7`='Parece que te vendría bien una fría. ¡Cebatruenos se encargará de eso!' WHERE `ID`=22137;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너 술 마시고 싶지?! 우리한테 술 있다!', `MaleText_loc4`='你想喝酒吗！？！我们有酒！！！', `MaleText_loc5`='你想要喝點飲料?!我們有飲料!', `MaleText_loc7`='¡QUIERES BEBIDA! ¡TENEMOS BEBIDA!' WHERE `ID`=22138;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐 너! 오우거 맥주 마셔라! 크고 힘 세진다!', `MaleText_loc4`='嗨，你！！来一杯食人魔佳酿吧！！它会让你变得更大更强壮！！', `MaleText_loc5`='喂，就是你!喝巨魔酒!讓你又大又壯!', `MaleText_loc7`='¡OYE TÚ! ¡BEBE CERVEZAS DE OGROS! ¡TE HARÁN GRANDE Y FUERTE!' WHERE `ID`=22139;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맛을 봤으면 전부 마셔야지! 오우거 맥주!!', `MaleText_loc4`='你试过了最好的，现在试试其它的！食人魔啤酒！！', `MaleText_loc5`='你試過最好的了，現在試試其它的!巨魔酒!!', `MaleText_loc7`='¡LO INTENTAS BIEN, INTÉNTALO TAMBIÉN! ¡CERVEZA OGRA!' WHERE `ID`=22140;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아제로스에서 이보다 나은 맥주는 찾지 못할 겁니다.', `MaleText_loc4`='在艾泽拉斯再也找不到比这更好的啤酒了。', `MaleText_loc5`='你在艾澤拉斯找不到更好的啤酒啦。', `MaleText_loc7`='No encontrarás una cerveza mejor en todo Azeroth.' WHERE `ID`=22141;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 썬더브루가 양조 업계에서 최고라는 자부심을 가지고 있다네.', `MaleText_loc4`='我们有世界上最棒的酿酒厂，雷霆啤酒酿造商们一直引以为傲。', `MaleText_loc5`='我們雷酒相當地自豪我們是全世界最好的啤酒屋。', `MaleText_loc7`='Los Cebatruenos nos enorgullecemos de ser la mejor destilería de todos los reinos.' WHERE `ID`=22142;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우와! 너 정말 우리 술 사는 거야?', `MaleText_loc4`='哇！你真的想要从我们手中购买吗？', `MaleText_loc5`='什麼!你真的想要跟我們買?', `MaleText_loc7`='¡Guau! ¿Realmente quieres comprarnos a nosotros?' WHERE `ID`=22143;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='움직여라, 경비병들! 신나게 썰어 봐라!', `MaleText_loc4`='上前去，卫兵！杀戮时间开始了！', `MaleText_loc5`='上前去，衛兵!殺戮時間開始了!', `MaleText_loc7`='¡Muévanse guardias! ¡Es hora de matar!' WHERE `ID`=22144;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무하하하!', `MaleText_loc4`='哈哈哈！', `MaleText_loc5`='哇-哈-哈!', `MaleText_loc7`='¡Ja, ja, ja!' WHERE `ID`=22145;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 가란 말이다! 누가 더 무섭나, 응? 저들인가? 나인가...', `MaleText_loc4`='卫兵，快上！你们更怕谁！他们……还是我？', `MaleText_loc5`='衛兵，快上!你們更怕誰...他們...還是我?', `MaleText_loc7`='¡Vamos, guardias! ¿A quién le tienen más miedo, a ellos o a mi?' WHERE `ID`=22146;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음? 우으... 크라앙...', `MaleText_loc4`='嗯？啊……呃……', `MaleText_loc5`='嗯嗯?啊...喀，嚕嗯嗯嚕喀...', `MaleText_loc7`='¿Mmm? Uhg... gah, rhmmrugh...' WHERE `ID`=22147;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오크, 일어나라, 목이 탄단 말이다! 마실 걸 좀 팔아라...', `MaleText_loc4`='兽人，快醒醒！我口渴得很！卖点喝的给我……', `MaleText_loc5`='醒一醒，獸人，我快渴死了!賣點什麼給我喝吧...', `MaleText_loc7`='Despierta, orco. ¡Estoy sediento! Véndeme algo de beber...', `FemaleText_loc1`='오크, 일어나라, 목이 탄단 말이다! 마실 걸 좀 팔아라...', `FemaleText_loc4`='兽人，快醒醒！我口渴得很！卖点喝的给我……', `FemaleText_loc5`='醒一醒，獸人，我快渴死了!賣點什麼給我喝吧...', `FemaleText_loc7`='Despierta, orco. ¡Estoy sedienta! Véndeme algo de beber...' WHERE `ID`=22148;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 가야 할 곳도 많고 만나볼 사람도 많다는 걸 보면 모르겠습니까! 비켜나십시오, 촌뜨기 양반!', `MaleText_loc4`='你没看到我有好多事情要忙吗？走开点，农夫！', `MaleText_loc5`='你沒看到我還有地方要去，有對象要見嘛!閃邊去，鄉巴佬!', `MaleText_loc7`='¡No ves que tengo sitios a los que ir y gente que visitar! ¡Aparta campesino!' WHERE `ID`=22149;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐만요! 전 커피가 마시고 싶습니다!', `MaleText_loc4`='等等！我想喝点咖啡！', `MaleText_loc5`='等等!我想要咖啡!', `MaleText_loc7`='¡Espera! ¡Quiero un poco de café!', `FemaleText_loc1`='잠깐만요! 전 커피가 마시고 싶어요!', `FemaleText_loc4`='等等！我想喝点咖啡！', `FemaleText_loc5`='等等!我想要咖啡!', `FemaleText_loc7`='¡Espera! ¡Quiero un poco de café!' WHERE `ID`=22150;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 가라! 가서 녀석들을 처치하고 그 증거를 가져와라!', `MaleText_loc4`='冲锋！冲过去，把他们的脑袋给我带来！', `MaleText_loc5`='就是現在!衝過去，把他們的腦袋給我帶來!', `MaleText_loc7`='¡Cabalguen! ¡Cabalguen por ahí y tráiganme algunas cabezas!' WHERE `ID`=22151;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 내가 누군지 알고 있을 텐데요. 그런데도 날 귀찮게 한단 말입니까?$b$b무슨 일로 이 나를 귀찮게 하는 겁니까?', `MaleText_loc4`='我想你知道我是谁吧。但是，你还是不停地烦我？$b$b你是不是想引起我的注意？', `MaleText_loc5`='我只能假定你知道我是誰。而且還一直打擾我?$b$b你究竟想要我注意什麼?', `MaleText_loc7`='No puedo más que dar por hecho que sabes quien soy. ¿Y aun así insistes en molestarme?$B$B¿Qué puedes querer que requiera mi atención?' WHERE `ID`=22152;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음, 누구시더라?', `MaleText_loc4`='呃，你是谁？', `MaleText_loc5`='呃，你是誰?', `MaleText_loc7`='Uhh, ¿tú quién eres?', `FemaleText_loc1`='음, 누구시더라?', `FemaleText_loc4`='呃，你是谁？', `FemaleText_loc5`='呃，你是誰?', `FemaleText_loc7`='Uhh, ¿tú quién eres?' WHERE `ID`=22153;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이것 참, 바보같이 굴지 마십시오! 제가 바로 그 버드 네드렉입니다!$b$b하이잘 산 정상에서부터 가라앉은 사원의 깊은 곳까지 안 돌아다닌 곳이 없지요. 사실은 말입니다, 그곳을 처음으로 가라앉은 사원이라 부른 사람이 바로 접니다!$b$b네, 바로 저라고요. 뭐, 그렇다고 미안해할 것까진 없습니다.', `MaleText_loc4`='拜托，别讲那种荒谬的话了！我就是巴德·奈德雷克，如假包换！$b$b我游历过这片大陆的每个角落，从海加尔山颠到沉没的神庙都留下了我的足印。事实上，沉没的神庙还是我命名的呢！$b$b是啦，就是我。你还怀疑什么呢。', `MaleText_loc5`='喔拜託，別鬧了!我就是那個唯一的霸德·奈德瑞克$b$b我遍布這個大陸，從海加爾山頂到沉沒的神廟深處。事實上，我就是第一個叫它為沉沒的神廟的人!$b$b沒錯，就是我。別想改變它。', `MaleText_loc7`='Vamos, ¡no seas ridículo! ¡Yo soy el único Budd Magallenas!$B$BHe recorrido toda esta tierra, desde lo alto del Monte Hyjal hasta las profundidades del Templo Sumergido. ¡De hecho, yo fui el primero en llamarlo el Templo Sumergido!$B$BSí, fui yo. Pero no lo pienses demasiado.' WHERE `ID`=22154;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='인내심에 한계가 온다! 계속해라. 태어난 것을 후회하게 해 줘라!', `MaleText_loc4`='我要失去耐心了！继续上，让他们感觉生不如死！', `MaleText_loc5`='我要失去耐心了!上吧:讓他們感覺生不如死!', `MaleText_loc7`='¡Estoy perdiendo la paciencia! ¡Vayan: hagan que deseen no haber nacido!' WHERE `ID`=22155;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='세이지를 만나서 운명을 점쳐보기를 권해드립니다. 그래요, 그래요... 세이지는 놀이죠. 하지만, 세이지는 미래를 점치는 힘을 지닌 아주 특별한 놀이랍니다!$B$B저희는 온갖 새로운 즐길 거리를 마련하여 그 능력을 더 널리 사용하고자 한답니다.', `FemaleText_loc4`='我强烈建议你去找塞格占卜一下……我知道，他是个豺狼人。但是他是个非常特殊的、可以帮你占卜命运的豺狼人！$B$B我们也在不断给马戏团增加新项目以保持吸引力！', `FemaleText_loc5`='我極度推薦你去拜訪賽吉得到你的未來預言。我知道，我知道...他是個食人妖。不過他是一個非常特別的食人妖，擁有占卜你未來的能力!$B$B而且我們一直持續地擴展馬戲團在各方面的新吸引力!', `FemaleText_loc7`='Te recomiendo encarecidamente que visites a Sayge para que te lea tu fortuna. Lo sé, lo sé... es un gnoll. ¡Pero es un gnoll muy especial con el poder de la adivinación!$B$B¡Y continuamente ampliamos la feria con todo tipo de atracciones nuevas!' WHERE `ID`=22156;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그게 아니라 당신이 그런 분이라는 얘기를 들어본 거 같지가 않습니다만...', `MaleText_loc4`='不，我想我不认识你吧。', `MaleText_loc5`='沒有，我沒聽過你這人。', `MaleText_loc7`='No, no he oído hablar de ti.', `FemaleText_loc1`='그게 아니라 당신이 그런 분이라는 얘기를 들어본 거 같지가 않은데...', `FemaleText_loc4`='不，我想我不认识你吧。', `FemaleText_loc5`='沒有，我沒聽過你這人。', `FemaleText_loc7`='No, no he oído hablar de ti.' WHERE `ID`=22157;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진짭니까? 꽤 멋지군요...', `MaleText_loc4`='真的吗？听起来真能打……', `MaleText_loc5`='真的嗎?那的確是事實...', `MaleText_loc7`='¿En serio? Esa es una afirmación peliaguda...', `FemaleText_loc1`='진짜로요? 꽤 멋지네요...', `FemaleText_loc4`='真的吗？听起来真能打……', `FemaleText_loc5`='真的嗎?那的確是事實...', `FemaleText_loc7`='¿En serio? Esa es una afirmación peliaguda...' WHERE `ID`=22158;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 어쨌거나 잘 들으십시오, $c님. 전 액면가보다 나이가 많은데다가 나이대에 비해 지혜롭지요. 그러니 제 말을 의심하지 않는 게 좋을 겁니다.

뭐, 굳이 제가 입 아프게 말할 것도 없지요. 여기저기 마을에서 게시판을 읽어보시죠. 어디에나 제 이름이 있습니다!$b$b아, 게시판 글 제목에 "현상 수배"라고 쓰인 것들은 무시하세요. 사소한 오해의 산물들이죠. 제가 보장하지요.', `MaleText_loc4`='好吧，$c，听我说。我的实际年龄比外表所显示出来的更大，我还拥有超越年龄的智慧。你最好别怀疑我所说的。

当然，若是你不相信我的话呢，就去看看城镇中招贴的公告牌吧。每张上面都写着我的名字！$b$b不过嘛，标有“通缉”字样的公告牌请直接无视吧。我向你保证，那只是误会。', `MaleText_loc5`='沒錯，那麼，聽好，$c。我比我外表所見的還年長，而且比我年齡來得有智慧。你最好不要質疑我。

瞧，你並不需要對我說的話太認真。自己去看看任何一個當地佈告欄上的佈告。隨處都是我!$b$b就當是幫你自己的忙，省略掉開頭的「懸賞」吧。我跟你保證，那只是個誤會。', `MaleText_loc7`='Sí, bien, escucha $c. Soy mayor de lo que aparento y muy sabio para mi edad. Harías bien en no hacerme demasiadas preguntas.

Mira, no tienes que creerme. Lee lo publicado en cualquier tablón de anuncios. ¡Estoy en todas partes!$B$BPero hazte un favor e ignora esas en las que pone "SE BUSCA" en el título. Leves malentendidos, te lo aseguro.' WHERE `ID`=22159;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음... 옛날 동전에... 촌스러운 장신구라...', `MaleText_loc4`='嗯……古老的钱币……难看的珠宝……', `MaleText_loc5`='嗯嗯...古老的錢幣...醜陋的珠寶...', `MaleText_loc7`='Hmm... monedas viejas... joyas feas...' WHERE `ID`=22160;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='촌스러운 장신구가 더 있고... 집으로 부친 편지에... 슬슬 포기하게 되는 걸!', `MaleText_loc4`='又是难看的珠宝……还有家书……我快要放弃希望了！', `MaleText_loc5`='更多醜陋的珠寶...家書...我開始放棄希望了!', `MaleText_loc7`='Más joyas feas... cartas a casa... ¡Estoy empezando a perder la esperanza!' WHERE `ID`=22161;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니... 이게 뭐지? 수갑 한 쌍인데 평범한 것은 아니군. 마법에 걸려있어. 이 짐은 물건이 아니라... 사람이었군!', `MaleText_loc4`='嗨……这是什么？一副镣铐，还不是一般的镣铐呢。上面附有魔法。还有这箱货物，啊，里面有人！', `MaleText_loc5`='嘿...這是什麼?一副鐐銬而不是任何東西。這些上面附有魔法。這項貨物，不是一樣東西...是個人!', `MaleText_loc7`='Hey... ¿qué es esto? Un par de esposas. Y no unas esposas cualquiera. Estas están encantadas. Esta mercancía no era un objeto... ¡era una persona!' WHERE `ID`=22162;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무도 검은무쇠 드워프가 나타날 줄 몰랐겠지!', `MaleText_loc4`='没人料到黑铁矮人会来吧！！', `MaleText_loc5`='黑鐵矮人來了!', `MaleText_loc7`='¡Nadie espera a los enanos Hierro Negro!' WHERE `ID`=22163;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='반갑습니다, $c님. 저는 그리핀 조련술을 저기 있는 발드럭 님에게 배우고 있지요. 저도 언젠가는 이름을 걸고 그리핀을 관리하고 싶어요.', `FemaleText_loc4`='$c，你好。我正在向巴德拉克讨教驾驭狮鹫的窍门。真希望有一天我能拥有自己的狮鹫棚。', `FemaleText_loc5`='幸會，$c。我正在那跟巴德拉克學著管理獅鷲獸的技巧。有一天，我希望可以有我自己的獅鷲獸欄。', `FemaleText_loc7`='$gBienvenido:Bienvenida;, $c. Estoy aprendiendo el arte de manejar grifos con Baldruc. Espero tener mi propio establo de grifos algún día.' WHERE `ID`=22164;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='삐! 삐! 허가받지 않은 정보 검색이 탐지되었습니다. 보안 시스템을 가동합니다.', `MaleText_loc4`='警报！警报！发现有人未经许可就想取出贵重物品。启动安全系统。', `MaleText_loc5`='嗚!嗚!偵測到未經授權的物品拿取。啟動安全系統。', `MaleText_loc7`='¡BIP, BIP! Recogida de bienes no autorizada. Activando sistema de seguridad.' WHERE `ID`=22165;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카일은 어디에 있을까요?', `MaleText_loc4`='狗在哪里？', `MaleText_loc5`='我的小狗哪裡去了?', `MaleText_loc7`='¿Dónde está ese perro?' WHERE `ID`=22166;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혹시 누가 잡아먹은 건 아니겠죠?', `MaleText_loc4`='你能帮我找到我的狗吗？', `MaleText_loc5`='你能幫我找找小狗嗎?', `MaleText_loc7`='¿Me ayudarás a encontrar a mi perro?' WHERE `ID`=22167;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 강아지가 보고 싶어요!', `MaleText_loc4`='我好想它啊！', `MaleText_loc5`='我好想念我的狗!', `MaleText_loc7`='¡Echo mucho de menos a mi perro!' WHERE `ID`=22168;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 사람들이 선술집이나 이런 축제에서 낭만적인 분위기를 찾는지 이해는 가지만 말입니다, 술은 감각을 둔하게 하고 일상의 고달픔을 제대로 인식하지 못하게 한다고요!$b$b그래서 제가 방법을 찾아냈습니다! 각고의 노력과 고생 끝에 특별한 장치를 고안했지요! 이 고글을 쓰면 누구라도 매력적으로 보입니다!$b$b음... 당신도 포함해서 말이지요, 귀여운 분! 어떻습니까? 할인도 해 드리지요!', `MaleText_loc4`='人们总是希望在旅店或是这样的节日聚会上找到艳遇，我非常理解这种想法。但是酒精会让人的感官变得迟钝，让你忘却生计的艰辛。$B$B不过，我找到了解决方法！通过很多次的试验和磨难，我设计出一种特别的装置！只要戴上这些护目镜，所有人都会变得魅力十足！$B$B嗯……包括你，美人！怎么样，我还可以给你打折！', `MaleText_loc5`='我了解有許多人在像這樣的慶典及酒館中尋求羅曼史，但是酒精模糊了感官，使得平日生活中的價值觀全都變得迷迷濛濛!$b$b不過我找到解決的方法了!經過許多的試煉及磨難，我已經設計出一樣驚人的裝置!戴上這副護目鏡，任何人看起來都會很具吸引力!$b$b嗯嗯...包括你，小可愛!告訴你。我可以給你個折扣喔!', `MaleText_loc7`='Comprendo que mucha gente busca el amor en las tabernas y los festivales como este, pero el alcohol nubla los sentidos y dificulta la vida cotidiana.$B$B¡Pero he encontrado una solución! Tras muchas pruebas y tribulaciones, he creado un aparato extraordinario. ¡Con estas gafas puestas, TODO EL MUNDO parece atractivo!$B$BMmm... ¡hasta tú, ricura! ¿Sabes qué? Te haré un descuento.', `FemaleText_loc1`='왜 사람들이 선술집이나 이런 축제에서 낭만적인 분위기를 찾는지 이해는 가지만요, 술은 감각을 둔하게 하고 일상의 고달픔을 제대로 인식하지 못하게 한다고요!$b$b그래서 제가 방법을 찾아냈답니다! 각고의 노력과 고생 끝에 특별한 장치를 고안했지요! 이 고글을 쓰면요, 누구라도 매력적으로 보인다고요!$b$b음... 당신도 포함해서 말이에요, 멋쟁이 씨! 어때요? 할인도 해 드릴게요!', `FemaleText_loc4`='人们总是希望在旅店或是这样的节日聚会上找到艳遇，我非常理解这种想法。但是酒精会让人的感官变得迟钝，让你忘却生计的艰辛。$B$B不过，我找到了解决方法！通过很多次的试验和磨难，我设计出一种特别的装置！只要戴上这些护目镜，所有人都会变得魅力十足！$B$B嗯……包括你，美人！怎么样，我还可以给你打折！', `FemaleText_loc5`='我了解有許多人在像這樣的慶典及酒館中尋求羅曼史，但是酒精模糊了感官，使得平日生活中的價值觀全都變得迷迷濛濛!$b$b不過我找到解決的方法了!經過許多的試煉及磨難，我已經設計出一樣驚人的裝置!戴上這副護目鏡，任何人看起來都會很具吸引力!$b$b嗯嗯...包括你，小可愛!告訴你。我可以給你個折扣喔!', `FemaleText_loc7`='Comprendo que mucha gente busca el amor en las tabernas y los festivales como este, pero el alcohol nubla los sentidos y dificulta la vida cotidiana.$B$B¡Pero he encontrado una solución! Tras muchas pruebas y tribulaciones, he creado un aparato extraordinario. ¡Con estas gafas puestas, TODO EL MUNDO parece atractivo!$B$BMmm... ¡hasta tú, ricura! ¿Sabes qué? Te haré un descuento.' WHERE `ID`=22169;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오우, 또 뵙네요, 멋쟁이 씨! 근육이 정말 끝내주는데요!', `FemaleText_loc4`='哇，过来呀，美人！你的身材真健美！', `FemaleText_loc5`='噢，再走過一次，小可愛!你背部的肌肉線條真美!', `FemaleText_loc7`='¡Oooh, vuelve a pasar, fiera! ¡Tus músculos traseros están muy bien tonificados!' WHERE `ID`=22170;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='야호! 이리로 오세요, 사랑스러운 분!', `FemaleText_loc4`='呀哈！来呀，甜心！', `FemaleText_loc5`='唷吼!就在那，寶貝的東西!', `FemaleText_loc7`='¡Yuju! ¡Aquí, cielito!' WHERE `ID`=22171;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신! 귀여워 죽겠어요! 제가 수집한 도구들을 구경하러 가시는 게 어때요?', `FemaleText_loc4`='嗨！小可爱！你想来看看我收藏的工具吗？', `FemaleText_loc5`='你!可愛的人!你想要到我的地方去看看我的工具收集嗎?', `FemaleText_loc7`='¡Tú! ¡El guapo! ¿Quieres venir a mi casa a ver mi colección de herramientas?' WHERE `ID`=22172;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어머, 자기! 지적인 토론을 하면서도 매력적인 태도를 잃지 않는 여자한테 관심 없으신가요?', `FemaleText_loc4`='嗨，甜心！你对伶牙俐齿魅力四射的女人感兴趣吗？', `FemaleText_loc5`='寶貝!你對於在理性對話的同時還能看起來很迷人的女人感興趣嗎?', `FemaleText_loc7`='¡Cielo! ¿Te interesa una mujer que pueda mantener una conversación inteligente y ser atractiva al mismo tiempo?' WHERE `ID`=22173;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아유... 이 균형잡힌 매력 덩어리 같으니!', `FemaleText_loc4`='呀呼，你的身材简直是黄金比例啊！', `FemaleText_loc5`='呦喔喔喔喔吼，你這個勻稱有魅力的人，就是你!', `FemaleText_loc7`='¡Yuuuujjjuuuuuuu, el macizo bien proporcionado, tú!' WHERE `ID`=22174;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='매혹적인 면모를 어찌나 인상적으로 드러내시는지!', `FemaleText_loc4`='多么迷人的容貌啊！', `FemaleText_loc5`='真是令人印象深刻的誘人景像!', `FemaleText_loc7`='¡Qué impresionante muestra de encantadoras perspectivas!' WHERE `ID`=22175;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리핀을 타고 알카즈 섬에 가서 조사하라는 지시를 전달하라고 여군주이신 제이나 님께서 말씀하셨습니다.', `MaleText_loc4`='吉安娜女士让我来和你谈谈关于乘坐狮鹫调查奥卡兹岛的事。', `MaleText_loc5`='珍娜女士告知我跟你談談有關雇用獅鷲獸前往調查奧卡茲島的事。', `MaleText_loc7`='Lady Jaina me dijo que hablara contigo acerca de usar un grifo para inspeccionar la Isla de Alcaz.', `FemaleText_loc1`='그리핀을 타고 알카즈 섬에 가서 조사하라는 지시를 전달하라고 여군주이신 제이나 님께서 말씀하셨어요.', `FemaleText_loc4`='吉安娜女士让我来和你谈谈关于乘坐狮鹫调查奥卡兹岛的事。', `FemaleText_loc5`='珍娜女士告知我跟你談談有關雇用獅鷲獸前往調查奧卡茲島的事。', `FemaleText_loc7`='Lady Jaina me dijo que hablara contigo acerca de usar un grifo para inspeccionar la Isla de Alcaz.' WHERE `ID`=22176;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일이 난 거죠?', `MaleText_loc4`='怎么了？', `MaleText_loc5`='發生了什麼事?', `MaleText_loc7`='¿Qué ocurre?', `FemaleText_loc1`='무슨 일이 난 거예요?', `FemaleText_loc4`='怎么了？', `FemaleText_loc5`='發生了什麼事?', `FemaleText_loc7`='¿Qué ocurre?' WHERE `ID`=22177;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭘로 드릴까요?', `FemaleText_loc4`='事情会变成什么样呢……', `FemaleText_loc5`='你的決定是什麼呢，小甜心?', `FemaleText_loc7`='¿Qué quieres, cariño?' WHERE `ID`=22178;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 잔 하고 싶습니다.', `MaleText_loc4`='我想要喝一杯。', `MaleText_loc5`='我想要一杯飲料。', `MaleText_loc7`='Quiero una bebida.', `FemaleText_loc1`='한 잔 마시고 싶네요.', `FemaleText_loc4`='我想要喝一杯。', `FemaleText_loc5`='我想要一杯飲料。', `FemaleText_loc7`='Quiero una bebida.' WHERE `ID`=22179;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 요리 솜씨가 굉장히 좋다는 소문이 있던데요.', `MaleText_loc4`='我听说你的厨艺很不错。', `MaleText_loc5`='我聽說你是個一流的廚師。', `MaleText_loc7`='He oído que cocinas bastante bien.', `FemaleText_loc1`='당신 요리 솜씨가 굉장히 좋으시다고 들었어요.', `FemaleText_loc4`='我听说你的厨艺很不错。', `FemaleText_loc5`='我聽說你是個一流的廚師。', `FemaleText_loc7`='He oído que cocinas bastante bien.' WHERE `ID`=22180;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오, 제가 요리를 잘한다고요? 그렇다고 할 수도 있겠지요. 선술집에서 일하다 보면 주방에도 때때로 들어가는 법이라서 수년간 꽤 여러 가지 조리법을 배웠답니다. 특이한 요리는 없지만 그록의 퉁퉁한 배를 채우기엔 충분할 테지요.', `FemaleText_loc4`='啊，我的厨艺吗？应该是吧。作为女招待，当然总得在厨房里跑来跑去的。我确实学到了一些新的菜谱，虽然不是很特殊，但至少可以填饱葛罗克那无底洞一样的胃。', `FemaleText_loc5`='喔，你說我是個廚師?我想你說的沒錯。酒吧女服務員總是偶爾要在廚房裡幹活，而多年來我已經學會了一些食譜。雖然不是什麼特別的菜餚，但是可以豐盛地滿足葛羅克的大胃口。', `FemaleText_loc7`='Oh, ¿yo cocinera? Supongo que es cierto. Una camarera tiene que trabajar en la cocina de vez en cuando y yo he aprendido alguna que otra receta a lo largo de los años. Nada especial, pero son lo suficientemente abundantes como para llenar la considerable barriga de Grok.' WHERE `ID`=22181;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조리법을 더 배우고 싶습니다.', `MaleText_loc4`='我还想学习更多。', `MaleText_loc5`='我想多學一些。', `MaleText_loc7`='Me gustaría aprender más.', `FemaleText_loc1`='조리법을 더 배우고 싶어요.', `FemaleText_loc4`='我还想学习更多。', `FemaleText_loc5`='我想多學一些。', `FemaleText_loc7`='Me gustaría aprender más.' WHERE `ID`=22182;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n, 미안하지만 당신에게 더 알려드릴 게 없답니다. 하지만 우리 요리사가 언제 새로운 요리를 개발할지 모르니 쑥스러워 마시고 나중에 꼭 들러주세요.', `FemaleText_loc4`='很抱歉，$n，但是我已经没有什么可以教你的了。当然，说不定哪天我灵光一闪，就发明出新菜谱啦，所以不要忘了经常回来看看！', `FemaleText_loc5`='很抱歉，$n。你已經學會了我所有的烹飪技巧。當然你永遠不知道我們的廚藝什麼時候會研發出新的食譜，所以別害羞，有空的時候儘管回來找我。', `FemaleText_loc7`='Lo siento, $n, pero ya has aprendido todo lo que sé acerca de cocinar. Por supuesto, nunca se sabe cuando prepararán algo nuevo nuestros cocineros, así que no seas tímido y visítanos de vez en cuando.' WHERE `ID`=22183;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 형제 크릭스는 자기가 오그리마에서 하는 일에 불만이 많습니다. 물론 여긴 세상에서 제일 냄새 나는 곳이긴 하지만, 최소한 저희 사장은 위험수당은 주니까요!

뭐라고요? 비행선이 어디 있는지 알고 싶으시다고요? 저한테 비행선 추적기가 있어서 다행이네요!', `MaleText_loc4`='我的兄弟克里克斯觉得他在奥格瑞玛的工作很糟糕。但和这个地方的恶臭比较起来，那算得了什么？不过至少老板还付给我额外的危险津贴！

