UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흐음, 이 오래된 뼈다귀는 좀 남겨야겠군.', `MaleText_loc4`='嗯，瞧我这身老骨头，看来该休息一会儿啦。', `MaleText_loc5`='嗯嗯，也許我讓這些老骨頭休息一下。', `MaleText_loc7`='Hmmm, quizá descanse un poco estos viejos huesos.' WHERE `ID`=22223;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='버드네 패거리, 말이야?$B$B이런, 버드는 다른 사람을 눈곱만치도 존중 안 하지. 삽질만 할 수 있다면, 아무나 데려다 쓸걸.$B$B...언데드는 빼고 말이야. 버드가 엄청 싫어하는 종족이거든. 개인적인 생각인데 말이지, 좀 무서워하는 게 아닌가 싶어.', `MaleText_loc4`='你是说巴德手下的探险队？$b$b他对任何人都一视同仁的。只要你会用铁铲，他就会雇佣你。$b$b呃……除非你是亡灵。巴德讨厌他们。不过我认为他是害怕亡灵。', `MaleText_loc5`='你是說，霸德的成員?$b$b是，他不太尊重人。他會帶著任何一個會用鏟工作的人$b$b...除了不死族。霸德厭惡他們。我個人是這樣覺得，他是怕他們。', `MaleText_loc7`='¿Te refieres al equipo de Budd?$B$BNo tiene respeto por la gente. ¡Cogería a cualquiera que supiera usar una pala!$B$B... Acepta no-muertos. Budd los odia. Personalmente, creo que les tiene miedo.' WHERE `ID`=22224;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 버드쪽 녀석은 누구입니까?', `MaleText_loc4`='这家伙是巴德手下的一名探险队员吧，他是什么人？', `MaleText_loc5`='這個叫霸德的傢伙是誰啊?', `MaleText_loc7`='¿Quién es ese tal Budd?', `FemaleText_loc1`='이 버드쪽 녀석은 누구죠?', `FemaleText_loc4`='这家伙是巴德手下的一名探险队员吧，他是什么人？', `FemaleText_loc5`='這個叫霸德的傢伙是誰啊?', `FemaleText_loc7`='¿Quién es ese tal Budd?' WHERE `ID`=22225;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 같은 사람이 당신 같은 $r에게 이럴 때 해줄 수 있는 일이 뭐가 있겠어?', `MaleText_loc4`='嗯，我很有本事呢。你要我帮你什么啊？', `MaleText_loc5`='像我這樣的人可以在像這樣的時候為了像你這樣一個$r做什麼事呢?', `MaleText_loc7`='¿Qué puede hacer un tipo como yo por $gun:una; $r como tú en un momento como este?' WHERE `ID`=22226;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 도와드릴까, $c씨?', `MaleText_loc4`='$c，要我帮忙吗？', `MaleText_loc5`='有什麼需要我可以幫忙的嗎，$c?', `MaleText_loc7`='¿Puedo hacer algo por ti, $c?' WHERE `ID`=22227;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='큰 건에 끼고 싶어서 여기 온 거라면, 줄을 서는 게 좋을 거야!$B$B내 몫도 못 챙긴 지 오래되었거든...', `MaleText_loc4`='你是来掠夺战利品的么？去排队候着吧！$b$b我的那份还没有到手呢……', `MaleText_loc5`='如果你是來這參與大掠奪的，你最好排一下隊!$b$b我的部分已經等很久了...', `MaleText_loc7`='¡Si estas aquí para tomar parte en los grandes desechos, ponte en la cola!$B$BMi parte viene con retraso.' WHERE `ID`=22228;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그건 나도 모르지, 친구. 나도 새로 왔거든.$B$B난 할당 받은 만큼 트롤 사냥을 끝내 놓고 그로그주를 마시고 있을 뿐이야, 암 그렇고말고. 이제 남은 볼 일은 버드가 계속 약속하는 그 보물뿐이지...', `MaleText_loc4`='孩子，你可难倒了我。我跟探险队的成员不熟。$b$b这些巨魔烈酒我已经喝腻了，就盼着巴德许诺的财宝呢……', `MaleText_loc5`='我不知道，小子。我是新來的。$b$b我能跟你說的是，我已經有了我的食人妖獵殺量及烈酒可以喝。唯一剩下的就是霸德承諾的寶藏了...', `MaleText_loc7`='Me supera, chico. Soy nuevo en el equipo.$B$BPuedo decirte que he matado montones de trols y bebido mucho grog. Lo único que me falta por ver es el tesoro que Budd está venga a prometer...' WHERE `ID`=22229;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 참 신기한 사람들만 모아놓으셨군요...', `MaleText_loc4`='这帮家伙真有意思……', `MaleText_loc5`='有趣的隊伍你們來到這裡了...', `MaleText_loc7`='Interesante equipo el que tienes aquí...', `FemaleText_loc1`='여기 참 신기한 사람들만 모아놓으셨네요...', `FemaleText_loc4`='这帮家伙真有意思……', `FemaleText_loc5`='有趣的隊伍你們來到這裡了...', `FemaleText_loc7`='Interesante equipo el que tienes aquí...' WHERE `ID`=22230;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='버드네 패거리, 말이야?$B$B이런, 버드는 다른 사람은 눈곱만치도 존중 안 한다고. 삽질만 할 수 있다면, 아무나 데려다 쓸걸.$B$B언데드는 빼고 말이야. 버드가 엄청 싫어하는 종족이거든. 아닌 척 하지만, 좀 무서워도 하지.', `MaleText_loc4`='你是说巴德手下的探险队？啊，他对任何人都一视同仁的。只要你会用铁铲，他就会雇佣你。$b$b除非你是亡灵。巴德讨厌他们。或许是害怕吧。', `MaleText_loc5`='你是說，霸德的成員?$b$b是，他不太尊重人。他會帶著任何一個會用鏟工作的人。$b$b...除了不死族以外。霸德厭惡他們。懼怕他們，可能裝作沒有這事。', `MaleText_loc7`='¿Te refieres al equipo de Budd? Sí, no respeta a las personas. Cogería a cualquiera que supiera usar una pala.$B$BAcepta no-muertos. Budd los odia, es probable que les tenga miedo.' WHERE `ID`=22231;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음, 앞으로 또 누가 합류할지, 그래서 다음엔 누가 죽게 될지 절대 모를걸.$B$B충고 한마디 해달라고? 한 사람에게 너무 달라붙지 말라고.', `MaleText_loc4`='是啊，你永远不会知道下一个入伙的家伙是谁，也不会知道下一个因此事而丧命的家伙是谁。$b$b我的建议么，就是不要和任何人扯上关系。', `MaleText_loc5`='是的，你從不知道下一個誰會加入，或是下一個誰會因那而死。$b$b我的建議?別跟任何人太接近。', `MaleText_loc7`='Sí, nunca se sabe quien va a ser el siguiente en unirse, o el siguiente en morir.$B$B¿Mi consejo? No te encariñes con nadie.' WHERE `ID`=22232;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 말이 맞아. 버드는 이 종족 저 종족 가리지 않고 어중이떠중이 다 긁어 모았다고.$B$B보아하니 술 좀 공짜로 돌리니까 개나 소나 잔뜩 몰려온 거지.', `MaleText_loc4`='说得没错。巴德纠集了形形色色的酒鬼。$b$b似乎只要能喝到免费的美酒，这帮家伙就会抛开彼此的差异与分歧，聚到一起来。', `MaleText_loc5`='同意。霸德從所有生物中聚集這些烏合之眾。$b$b感覺好像當有免費酒會時，會有很多人樂意將他們的差異擺到一邊去。', `MaleText_loc7`='De acuerdo. Budd ha estado recogiendo gente por todo el mundo.$B$BParece que cuando hay bebida gratis la gente está dispuesta a dejar sus diferencias de lado.' WHERE `ID`=22233;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니! 대체 이게 무슨 냄새입니까?', `MaleText_loc4`='哎呀！那是什么味道？', `MaleText_loc5`='唷!這是什麼味道啊?', `MaleText_loc7`='¡Puaj! ¿Qué es ese olor?', `FemaleText_loc1`='아니! 대체 이게 무슨 냄새죠?', `FemaleText_loc4`='哎呀！那是什么味道？', `FemaleText_loc5`='唷!這是什麼味道啊?', `FemaleText_loc7`='¡Puaj! ¿Qué es ese olor?' WHERE `ID`=22234;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<직접 냄새를 맡아보다가 움찔하는 맥>$B$B무언가 기묘한 일이 일어날 듯한 냄새군, $c 친구!', `MaleText_loc4`='<闻了闻身上的气味，然后退了一步>$b$b$c，这就是冒险的味道！', `MaleText_loc5`='<聞了聞他自己，然後畏縮>$b$b那是探險的味道，$c!', `MaleText_loc7`='<Se huele a sí mismo y hace una mueca de asco>$B$B¡Ese es el olor de la aventura, $c!' WHERE `ID`=22235;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<딸꾹> 내 말 들어봐, $r. 거친 트롤들하고 하루나 이틀 정도 씨름하고 나서 무슨 냄새가 나는지 얘기해 보자고!', `MaleText_loc4`='<嗝儿>听好了，$r。不如你也去和那些野蛮的巨魔扭打一番，然后闻闻自己身上的味儿！', `MaleText_loc5`='<嗝>聽好，$r。去花個一或兩天與食人妖打鬥然後再來跟我說你聞起來如何!', `MaleText_loc7`='<hip>Esscucha esto, $r. Passha un par de díassh luchando con trols salvajes y desssspuésh cuéntame cómo hueles.' WHERE `ID`=22236;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아, 그거 말이군. 보자, 요즘은 야영지 주변에 있는 오크 그로그주 말고는 아무것도 없더라고.$B$B내 입맛에는 좀 안 맞는 것 같지만 말이야. 내 말이 무슨 뜻인지 알겠지...', `MaleText_loc4`='瞧，这营地附近只有兽人烈酒而已。$b$b我可不喜欢喝这种酒，你懂我的意思吧……', `MaleText_loc5`='喔喔，那樣啊。瞧，最近營地裡到處都是獸人烈酒。$b$b獸人烈酒似乎不太合我的口味，如果你懂我的意思的話...', `MaleText_loc7`='Oh, eso. Verás, últimamente no ha habido más que grog orco por el campamento.$B$BEl grog orco no parece sentarme bien, tú me entiendes...' WHERE `ID`=22237;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네... 네... 뭐, 계속 떠드시던가요.', `FemaleText_loc4`='哈。就按你说的办。', `FemaleText_loc5`='哼哼。隨便你怎麼說。', `FemaleText_loc7`='Ah ja... Lo que tú digas.' WHERE `ID`=22238;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='멍청하긴...', `FemaleText_loc4`='白痴。', `FemaleText_loc5`='白癡。', `FemaleText_loc7`='Idiota' WHERE `ID`=22239;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제발 입 좀 다물어 주시지요?', `FemaleText_loc4`='你能闭嘴吗？！', `FemaleText_loc5`='拜託你可以閉嘴嗎?!', `FemaleText_loc7`='¡¿Puedes cerrar la boca, por favor?!' WHERE `ID`=22240;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 왜 그냥 박차고 가버리지 않는 건지 다시 물어봐 줄래요?', `FemaleText_loc4`='给我个理由，为什么我就不能离开呢？', `FemaleText_loc5`='可以再提醒我一次，為什麼我沒有立刻拍拍屁股走人?', `FemaleText_loc7`='Vuelve a recordarme por qué no me marcho.' WHERE `ID`=22241;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신은 제가 만나 본 중 최고로 무능력한 관리일 거라고요!', `FemaleText_loc4`='你是我所遇到过的最无能的军官！', `FemaleText_loc5`='你是我見過最不適任的軍官了!', `FemaleText_loc7`='Eres el oficial más incompetente que he conocido en mi vida.' WHERE `ID`=22242;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='선생께서 응당 받으셔야 할 존경을 담아서 한 말씀 올립지요. 좀 제대로 하시지 그래요?', `FemaleText_loc4`='恕我直言，长官，忍耐！', `FemaleText_loc5`='絲毫沒有不敬的意思，長官，戳下去!', `FemaleText_loc7`='Con el debido respeto señor, ¡métaselo por donde le quepa!' WHERE `ID`=22243;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제임스예요? 제임스... 아니, 당신은 제임스가 아니군요. 하지만 난 당신이 누군지 알아요...', `FemaleText_loc4`='詹姆斯？詹姆斯……不，你不是詹姆斯，但我知道你是谁……', `FemaleText_loc5`='詹姆士?詹姆士...不，你不是詹姆士，而且我知道你是誰...', `FemaleText_loc7`='¿James? James... No, tú no eres James, pero sé quién eres...' WHERE `ID`=22244;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리에게 이런 짓을 한 짐승 같은 녀석들을 쫓아 온 친구죠.', `FemaleText_loc4`='你就是追踪那帮野蛮的渣滓，替我们报仇的英雄。', `FemaleText_loc5`='你就是那個在追蹤對我們下此毒手的畜生的人。', `FemaleText_loc7`='Eres $gel que:la que; siguió la pista de los soldados que nos hicieron esto.' WHERE `ID`=22245;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제임스에게... 이 일의 배후에 있는 모든 사람에게... 얘기를 하려고 애썼지만, 어쩔 도리가 없었어요.', `FemaleText_loc4`='我千方百计地想要告诉吉姆……想要告诉所有人……谁才是幕后黑手，可惜始终没有机会……', `FemaleText_loc5`='我努力試著告訴吉姆...告訴任何一個人...兇手是誰，但是我找不到方法...', `FemaleText_loc7`='Intenté por todos medios decírselo a Jim... decírselo a alguien... quién estaba detrás de esto, pero no encontré la forma...' WHERE `ID`=22246;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저희와 제임스를 도와주셔서 감사드립니다. 제임스를 만나시면, 저와 꼬마 지미가 사랑한다고 그리고 기다린다고 전해주세요.', `FemaleText_loc4`='谢谢你为吉姆和我们所做的一切。如果你遇见吉姆，请告诉他我和小吉米始终爱着他，我们一直在等他回家。', `FemaleText_loc5`='謝謝你幫忙我們還有吉姆。如果你見到他，告訴他說小吉米和我都愛他，還有，我們都在等他。', `FemaleText_loc7`='Gracias por ayudarnos y por ayudar a Jim. Si le ves, dile que el pequeño Jimmy y yo le queremos y que le estamos esperando.' WHERE `ID`=22247;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엄마, 아빠는 언제 와?', `MaleText_loc4`='妈妈，我们什么时候能再见到爸爸？', `MaleText_loc5`='媽咪，我們什麼時候可以再見到爹地?', `MaleText_loc7`='Mami, ¿cuándo volveremos a ver a papi?' WHERE `ID`=22248;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='언제 다시 만날 수 있는지는 모르겠지만, 지미야, 엄마는 아빠가 우리 지미를 사랑하고 많이 보고 싶어하신다는 건 알고 있단다.', `FemaleText_loc4`='吉米，我也不知道我们何时才能与你爸爸重逢。但你要知道，他爱你，无时无刻都在思念你。', `FemaleText_loc5`='我不知道我們什麼時候可以再見到爹地，吉米，不過我知道他愛你，他非常想你。', `FemaleText_loc7`='No sé si volveremos a ver a papi, Jimmy, pero sé que te quiere y te echa mucho de menos.' WHERE `ID`=22249;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='세상에, 붕대를 갈아 드릴게요!', `FemaleText_loc4`='哦……见鬼，让我换个绷……带！', `FemaleText_loc5`='老天，讓我來換繃帶!', `FemaleText_loc7`='¡Oh cielos, déjame que cambie esas vendas!' WHERE `ID`=22250;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이러면 감염 속도가 좀 늦춰질 거예요.', `FemaleText_loc4`='这样或许可以延缓感染的速度。', `FemaleText_loc5`='這樣應該能使感染的擴散減緩一些。', `FemaleText_loc7`='Eso debería ralentizar un poco la infección.' WHERE `ID`=22251;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='투르고어! 일어나서 물건 하역하는 일 좀 도우라고, 이 게으른 녀석아!', `FemaleText_loc4`='图高尔！懒惰的家伙，快过来帮我卸货！', `FemaleText_loc5`='透高爾!起床幫我卸貨，你這懶惰的苦工!', `FemaleText_loc7`='¡Turgencio! ¡Levántate y ayúdame a descargar, peón vago!' WHERE `ID`=22252;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 쓸모없는 오크 녀석아! 조금만 기다려 봐라, 언젠가 네 그로그 술잔에 뭔가를 타서 다시는 일어나지 못하게 해 주마...', `FemaleText_loc4`='蠢货！你给我等着，总有一天我会在你的酒里加点料，让你长眠不起……', `FemaleText_loc5`='沒用的獸人!你等著，有天我會在你的酒內下東西讓你永遠都醒不來...', `FemaleText_loc7`='¡Orco inútil! Espérate... un día de estos echare algo en tu grog y nunca volverás a despertarte...' WHERE `ID`=22253;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='브렌드, 말해줘요. 왜 내게는 눈길조차 주지 않는 거죠?', `FemaleText_loc4`='我说，布伦德，你的目光为何从来不在我的身上停留？', `FemaleText_loc5`='說，布瑞德，為什麼你從不對我拋媚眼?', `FemaleText_loc7`='Dime, Brend, ¿por qué a mí nunca me pones ojitos?' WHERE `ID`=22254;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그게... 마지, 당신한테 어떻게 이야기해야 할지 망설이고 있었는데 말이지...', `MaleText_loc4`='噢，玛尔格。事实上，我有话对你说……', `MaleText_loc5`='嗯，馬姬，事實上我曾想要找個方法告訴你...', `MaleText_loc7`='Bien, Marge, he estado buscando la manera de decirte esto...' WHERE `ID`=22255;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무진장 노력했는데, 아무리 술을 마셔도 당신이 못생겨 보이는 걸 날보고 어쩌란 말이야!', `MaleText_loc4`='我试过很多种方法，但只有在我喝醉时才觉得你是个美人！', `MaleText_loc5`='我試著去做，但我似乎無法品嘗你的美!', `MaleText_loc7`='¡Haga lo que haga, no logro verte guapa ni cuando bebo!' WHERE `ID`=22256;
