UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='도움이 좀 필요한데요, $c.$b$b당신의 능력을 좀 보여주시는 게 어떨까요?', `FemaleText_loc4`='$c，我需要帮助。$b$b过来帮帮我怎么样？', `FemaleText_loc5`='我在這還能幫忙，$c。$b$b你讓你自己有點用處可以嗎?', `FemaleText_loc7`='Me vendría bien una mano, $c.$B$B¿Qué tal si empiezas a ser útil?' WHERE `ID`=22276;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 버드라는 작자에 대해 아는 게 있습니까?', `MaleText_loc4`='能告诉我一些关于巴德的事情吗？', `MaleText_loc5`='你能告訴我什麼有關這個霸德傢伙的事嗎?', `MaleText_loc7`='¿Qué me puedes contar de ese tal Budd?', `FemaleText_loc1`='이 버드라는 작자에 대해 아는 게 있나요?', `FemaleText_loc4`='能告诉我一些关于巴德的事情吗？', `FemaleText_loc5`='你能告訴我什麼有關這個霸德傢伙的事嗎?', `FemaleText_loc7`='¿Qué me puedes contar de ese tal Budd?' WHERE `ID`=22277;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋은 소린 나올 게 없어요!$b$b그건 확실하다고요. 버드는 감언이설로 바보들을 낚아다가 술에 취하게 해 놓고는 자기가 하는 더러운 일에 써먹죠. 그들은 살아남는 경우보다 죽음을 맞는 경우가 훨씬 많다고요.', `FemaleText_loc4`='他是个坏人！$b$b我已经看穿他的真面目了。这家伙以财富为诱饵，将那群笨蛋灌得烂醉如泥，然后利用他们做些肮脏的勾当——他们通常会因此而丧命。', `FemaleText_loc5`='沒什麼好事!$b$b我正在調查這個人。他用財富的承諾或者灌醉對方來引誘一些笨蛋替他做事，然後利用這些人做一些見不得人的勾當─通常結果都是將這些人派去送死。', `FemaleText_loc7`='¡Nada bueno!$B$BLe estoy siguiendo la pista. Engaña a los insensatos con promesas de riqueza, los emborracha y los usa para hacer el trabajo sucio, que a menudo acaba matándolos.' WHERE `ID`=22278;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 왜 여기 있는 겁니까?', `MaleText_loc4`='那么，你还待在这儿做什么？', `MaleText_loc5`='那麼你在這裡做什麼呢?', `MaleText_loc7`='¿Entonces qué haces aquí?', `FemaleText_loc1`='그럼 왜 여기 있는 건가요?', `FemaleText_loc4`='那么，你还待在这儿做什么？', `FemaleText_loc5`='那麼你在這裡做什麼呢?', `FemaleText_loc7`='¿Entonces qué haces aquí?' WHERE `ID`=22279;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋은 질문이네요. 제 동생 투르고어에게 물어보시죠.$b$b어쩌면 당신은 대답을 들을지도 모르죠. 그 게으르고, 아무짝에도 쓸모없고... 으으. 말을 말아야지.', `FemaleText_loc4`='问得好。你不妨找我的兄弟图高尔谈谈。$b$b那个懒惰的坏家伙或许会告诉你答案……别让我打开话匣子。', `FemaleText_loc5`='問的好。這個問題你只能去問我的兄弟透高爾了。$b$b也許你可以得到你想要的答案，從那個懶惰、沒用...喔。別讓我開始講起他。', `FemaleText_loc7`='Buena pregunta. Tendrías que preguntárselo a mi hermano Turgencio.$B$BQuizá puedas obtener una respuesta de ese vago, bueno para nada...oohh. No dejes que empiece.' WHERE `ID`=22280;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훌쩍... 우린 다 끝났다고요... 검은무쇠 드워프는... 훌쩍... 나중에 다시 돌아올 겁니다... 훌쩍...', `MaleText_loc4`='啊……我们的酒都没了……黑铁矮人……啊……会回来……啊……', `MaleText_loc5`='吸鼻子...我們都落選了...黑鐵矮人們...吸鼻子...下次再來 ...吸鼻子...', `MaleText_loc7`='Sniff... Estamos todos fuera... Los enanos Hierro Negro... sniff... Vuelve más tarde... sniff', `FemaleText_loc1`='훌쩍... 우린 다 끝났다고요... 검은무쇠 드워프는... 훌쩍... 나중에 다시 돌아올 겁니다... 훌쩍...', `FemaleText_loc4`='啊……我们的酒都没了……黑铁矮人……啊……会回来……啊……', `FemaleText_loc5`='吸鼻子...我們都落選了...黑鐵矮人們...吸鼻子...下次再來 ...吸鼻子...', `FemaleText_loc7`='Sniff... Estamos todas fuera... Los enanos Hierro Negro... sniff... Vuelve más tarde... sniff' WHERE `ID`=22281;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 데서 술을 마련해와야 할 것 같군요.', `MaleText_loc4`='看上去我得去其它地方喝酒了。', `MaleText_loc5`='看來好像我得從別處拿點喝的了。', `MaleText_loc7`='Parece que tendré que conseguir mi bebida en otra parte.', `FemaleText_loc1`='다른 데서 술을 마련해와야 할 것 같군요.', `FemaleText_loc4`='看上去我得去其他地方喝酒了。', `FemaleText_loc5`='看來好像我得從別處拿點喝的了。', `FemaleText_loc7`='Parece que tendré que conseguir mi bebida en otra parte.' WHERE `ID`=22282;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='만나서 반갑습니다. 저는 적당한 주인이 비밀 암호를 가지고 찾아올 때까지 이 새끼용들을 돌보고 있답니다.', `FemaleText_loc4`='你好啊。在这些龙宝宝的主人持兑换码来认领它们之前，我会一直负责照料它们。', `FemaleText_loc5`='你好啊。我會看守著這些幼龍一直到牠的主人帶著正確的密碼前來為止。', `FemaleText_loc7`='Hola. Estoy cuidando de estas crías hasta que lleguen sus dueños con los códigos secretos.' WHERE `ID`=22283;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비밀 암호를 입력하고 황천의 새끼용을 받고 싶습니다.', `MaleText_loc4`='输入认证码以获得虚空龙宝宝宠物。', `MaleText_loc5`='輸入密碼以領取寵物虛空幼龍。', `MaleText_loc7`='Introducir código para recibir la cría abisal.', `FemaleText_loc1`='비밀 암호를 입력하고 황천의 새끼용을 받고 싶어요.', `FemaleText_loc4`='输入认证码以获得虚空龙宝宝宠物。', `FemaleText_loc5`='輸入密碼以領取寵物虛空幼龍。', `FemaleText_loc7`='Introducir código para recibir la cría abisal.' WHERE `ID`=22284;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가엾은 필멸의 존재여, 오닉시아는 아무에게도 대답하지 않는다!', `MaleText_loc4`='可悲的凡人，奥妮克希亚不会任凭你摆布的！', `MaleText_loc5`='可悲的凡人，沒有人夠資格挑戰奧妮克希亞!', `MaleText_loc7`='Lamentable mortal, ¡Onyxia no responde ante nadie!' WHERE `ID`=22285;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한심하기 짝이 없는 네 도전 따위는 누구 하나 알아주지 않고 끝났다. 이제 네 목숨을 빼앗기 전에 좀 가지고 놀아야겠다.', `MaleText_loc4`='就凭你也敢来挑衅。死之前让我好好享受一下玩弄你的乐趣吧。', `MaleText_loc5`='你那可悲的挑戰不會白白浪費掉。我將在你死掉之前盡情的蹂躪你。', `MaleText_loc7`='Tu patético reto no ha pasado desapercibido. Disfrutaré jugando contigo antes de que mueras.' WHERE `ID`=22286;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서두르십시오, 친구! 전 죽기 싫다고요!$b$b녀석들이 포로한테 무슨 짓을 하는지 다 봤습니다. 전 죽기엔 너무 젊어요!$b$b뭐라도 해 보세요, 빨리요!', `MaleText_loc4`='朋友，快！我就要没命了！$b$b我知道他们是如何对待囚犯的！我还这么年轻，我可不想死！$b$b你倒是做点什么啊，快啊！', `MaleText_loc5`='快點，小子!我快完蛋了!$b$b我見過他們對待囚犯的方式，我還太年輕不該這麼早死!$b$b你得做點什麼，快點啊!', `MaleText_loc7`='¡Date prisa, colega! ¡Eh''toy perdido!$B$B¡Veo lo que eh''tán haciendo con los prisioneros y soy demasiado joven pa'' morir!$B$B¡Tienes que hacer algo y pronto!' WHERE `ID`=22287;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 장소에 대해 아는 걸 이야기해 주시겠습니까?', `MaleText_loc4`='你能告诉我这里的情况吗？', `MaleText_loc5`='你能告訴我什麼有關這個地方的事嗎?', `MaleText_loc7`='¿Qué me puedes contar de este lugar?', `FemaleText_loc1`='이 장소에 대해 아는 걸 이야기해 주실래요?', `FemaleText_loc4`='你能告诉我这里的情况吗？', `FemaleText_loc5`='你能告訴我什麼有關這個地方的事嗎?', `FemaleText_loc7`='¿Qué me puedes contar de este lugar?' WHERE `ID`=22288;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐요, 잠시만요!$b$b아는 건 다 이야기해 드리겠습니다! 먼저 이 야만인이랑 녀석들이 키우는 식인 곰한테서 좀 구해달라고요.$b$b어떻습니까?', `MaleText_loc4`='听着，朋友！$b$b我会把我知道的一切都告诉你，但你得先把我从这个恐怖的地方救出去！$b$b怎么样？', `MaleText_loc5`='聽著，老兄!$b$b我會告訴你我所知道的一切，但你必須先將我從這些野蠻生物還有他們兇暴的熊手上救出來。$b$b一言為定?', `MaleText_loc7`='¡Escucha tío!$B$BTe diré todo lo que sé, pero primero tienes que salvarme de estos salvajes y sus osos asesinos.$B$B¿Trato hecho?' WHERE `ID`=22289;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진흙톱니 거점에 있는 고블린들이 브록 여기 머물게 해줘서 기쁘지만 말이야. 가끔 브록 비웃는 소리가 들린다고 생각한다.', `MaleText_loc4`='布洛格很感激收留他的泥链镇地精，不过有时他觉得地精们在嘲笑自己。', `MaleText_loc5`='布洛葛很高興泥鏈營地的哥布林讓他待在這裡，但是有時候覺得他好像聽見他們在笑他。', `MaleText_loc7`='Brogg se alegra de que los goblins de Piñón de Barro le dejen quedarse, pero a veces cree que los oye reírse de él.' WHERE `ID`=22290;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비밀 암호를 입력하고 제 멀록 복장을 받고 싶습니다.', `MaleText_loc4`='我想要输入神秘兑换码以获得我的鱼人服装。', `MaleText_loc5`='我想要輸入驗證碼以領取我的魚人裝束', `MaleText_loc7`='Me gustaría introducir el código secreto para recibir mi traje de múrloc.', `FemaleText_loc1`='비밀 암호를 입력하고 제 멀록 복장을 받고 싶어요.', `FemaleText_loc4`='我想要输入神秘兑换码以获得我的鱼人服装。', `FemaleText_loc5`='我想要輸入驗證碼以領取我的魚人裝束', `FemaleText_loc7`='Me gustaría introducir el código secreto para recibir mi traje de múrloc.' WHERE `ID`=22291;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우와! 탄자르가 풀려났다!$b$b어찌나 다행인지! 게다가 송곳니에 흠집도 안 났군요.$b$b불사신이라고 들어 보셨습니까? 그게 바로 접니다. 부정할 생각 마세요.', `MaleText_loc4`='啊哈！坦扎尔自由啦！$b$b我真走运！竟然毫发未伤。$b$b朋友，我是被命运之神眷顾的幸运儿。是啦。肯定是这样。', `MaleText_loc5`='喔耶!坦札爾被釋放了，老兄!$b$b真幸運啊，受了那麼多苦我竟然還毫髮未損。$b$b老天爺的眷顧呀，老兄。我一定是受到眷顧。不用懷疑。', `MaleText_loc7`='¡Yuju! ¡Tanzar es libre, tío! ¡Qué suerte, todo eso y ni siquiera un colmillo roto!$B$BBendecido, tío. Eso es lo que estoy. No tiene sentido negarlo.' WHERE `ID`=22292;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천만에요... 자 이제 여기서 무슨 일이 벌어지는 것인지 이야기해 주십시오!', `MaleText_loc4`='不客气……告诉我们这儿发生了什么事！', `MaleText_loc5`='不客氣...現在告訴我們這裡發生了什麼事!', `MaleText_loc7`='De nada... ¡Ahora cuéntanos que está pasando!', `FemaleText_loc1`='천만에요... 자 이제 여기서 무슨 일이 벌어지는 것인지 이야기해 주시죠!', `FemaleText_loc4`='不客气……告诉我们这儿发生了什么事！', `FemaleText_loc5`='不客氣...現在告訴我們這裡發生了什麼事!', `FemaleText_loc7`='De nada... ¡Ahora cuéntanos que está pasando!' WHERE `ID`=22293;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='버드에 대해 알려 줄 건 없습니까?', `MaleText_loc4`='能告诉我们关于巴德的事情吗？', `MaleText_loc5`='你能告訴我們什麼關於霸德的事呢?', `MaleText_loc7`='¿Qué puedes contarnos acerca de Budd?', `FemaleText_loc1`='버드에 대해 알려 줄 건 없나요?', `FemaleText_loc4`='能告诉我们关于巴德的事情吗？', `FemaleText_loc5`='你能告訴我們什麼關於霸德的事呢?', `FemaleText_loc7`='¿Qué puedes contarnos acerca de Budd?' WHERE `ID`=22294;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이렇게 추울 줄은 몰랐어요, $r님. 눈과 얼음이 없대도 노스렌드의 얼어붙은 황무지는 정말 지독하군요.', `FemaleText_loc4`='我从未到过这么冷的地方，$r。就算是没有冰雪覆盖，在诺森德的冰荒废土上行走还是异常艰难。', `FemaleText_loc5`='$r，我從沒經歷過這種寒冷。就算沒有冰雪落下，北裂境的冰凍荒原也讓人異常艱辛。', `FemaleText_loc7`='Nunca he experimentado un frío como este, $r. Incluso sin hielo ni nieve, los fríos baldíos de Rasganorte son extremadamente agotadores.' WHERE `ID`=22295;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물건을 사고 싶습니다, 야즈미나.', `MaleText_loc4`='我想要购买一些材料，亚米娜。', `MaleText_loc5`='雅茲米娜，我要買些試劑。', `MaleText_loc7`='Quiero comprar componentes, Yazmina.', `FemaleText_loc1`='물건을 사고 싶어요, 야즈미나.', `FemaleText_loc4`='我想要购买一些材料，亚米娜。', `FemaleText_loc5`='雅茲米娜，我要買些試劑。', `FemaleText_loc7`='Quiero comprar componentes, Yazmina.' WHERE `ID`=22296;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐요, 낯이 있군요. 우리 만난 적이 있나요?', `MaleText_loc4`='你……好似有点面熟。我以前在哪儿见过你吗？', `MaleText_loc5`='嗨，你看起來很面熟，我們見過嗎?', `MaleText_loc7`='Tu cara me suena. ¿Nos conocemos?' WHERE `ID`=22297;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 당신을 알던가요?', `MaleText_loc4`='我认识你吗？', `MaleText_loc5`='我認識你嗎?', `MaleText_loc7`='¿Te conozco?' WHERE `ID`=22298;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='충고 하나 해 드리지요. 노움은 절대 믿지 마십시오.', `MaleText_loc4`='让我给你一个忠告吧：永远不要信任侏儒。', `MaleText_loc5`='給你一個忠告:不要相信地精。', `MaleText_loc7`='Deja que te dé un consejo: nunca te fíes de un gnomo.' WHERE `ID`=22299;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='술이 필요합니다, 쿠트.', `MaleText_loc4`='给我再来点酒，笨蛋。', `MaleText_loc5`='我還要酒，傻蛋。', `MaleText_loc7`='Necesito bebida, Bobo.', `FemaleText_loc1`='술이 필요합니다, 쿠트.', `FemaleText_loc4`='给我再来点酒，笨蛋。', `FemaleText_loc5`='我還要酒，傻蛋。', `FemaleText_loc7`='Necesito bebida, Bobo.' WHERE `ID`=22300;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋습니다. 거래는 거래니까요...$b$b저희가 줄아만에 숨어든 건 밤이었습니다. 좀 둘러볼 생각이었지요.$b$b사방이 조용했습니다. 그런데 어느 순간 마치 나무 사이를 스치는 바람 같은 소리가 나더니, 이 야만인 무리와 놈들의 애완동물한테 둘러싸여 있지 뭡니까! 다음 날 여기 우리 안에서 깨어났지요.$b$b밤낮으로 포로들이 하나씩 죽어나갔습니다. 한 명 죽을 때마다 저 곰처럼 생긴 트롤 녀석은 더 강해지는 것 같았고 말입니다.$b$b그게 탄자르가 이곳에 대해 아는 전부랍니다, 친구. 그리고 더 깊이 알고 싶은 생각은 없어요!', `MaleText_loc4`='好吧，朋友，我告诉你……$b$b那晚我们潜入祖阿曼，想要一探究竟。$b$b夜色寂静，突然传来一阵微风掠过树叶般的飒飒声。没等我们回过神来，就被这帮野蛮的巨魔和他们的宠物包围了！等我醒来的时候已经是次日，我发现自己被囚禁在牢笼中。$b$b日复一日，囚犯们接二连三地惨遭毒手。每杀死一名囚犯，那名熊巨魔的力量就增加一些。$b$b朋友，我对祖阿曼的了解仅限于此。我也不想知道更多了！', `MaleText_loc5`='好吧，老兄，既然答應你就不能反悔...$b$b我們在某個夜晚溜進祖阿曼查看地形。$b$b一切是如此的安靜，直到我們聽到一陣沙沙作響的聲音，就像風吹過樹梢一樣。在尚未來得及反應之前，我們已經被那些野蠻生物還有他們的寵物給包圍了!隔天醒來的時候，我已經身陷牢籠了。$b$b日日夜夜，一個接著一個，囚犯們被處決了。每處決一個囚犯，那個熊一般的食人妖就會找下一個更強壯的囚犯。$b$b這就是我對這個地方的了解，老兄。而且我再也不想成名了!', `MaleText_loc7`='Vale tío, un trato es un trato...$B$BEra de noche cuando nos metimos en Zul''Aman para echar un vistazo.$B$BTodo estaba tranquilo hasta que oímos un susurro, como el viento entre los árboles. ¡Antes de que nos diéramos cuenta estábamos rodeados de un montón de salvajes y sus mascotas! Al día siguiente me levanto aquí, metido en una jaula.$B$BDía y noche mataban a los prisioneros, uno a uno. Cada vez que mataban a uno el trol-oso parecía más fuerte.$B$B¡Eso es todo lo que sé sobre este lugar y no quiero saber nada más!' WHERE `ID`=22301;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크면 마부가 되고 싶어요!', `MaleText_loc4`='等我长大以后，我要当一个马夫！', `MaleText_loc5`='我長大以後也要當馬夫!', `MaleText_loc7`='¡Cuando sea mayor quiero ser mozo de establos!' WHERE `ID`=22302;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만 얘기하고 내 야수나 맡아주렴.', `MaleText_loc4`='别罗嗦了，孩子，我要寄存我的宠物。', `MaleText_loc5`='孩子，別再閒聊了，我要把我的寵物安放進獸欄。', `MaleText_loc7`='Cierra el pico, niño. Tengo que acomodar a mi mascota en el establo.', `FemaleText_loc1`='그만 얘기하고 내 야수나 맡아주렴.', `FemaleText_loc4`='别罗嗦了，孩子，我要寄存我的宠物。', `FemaleText_loc5`='孩子，別再閒聊了，我要把我的寵物安放進獸欄。', `FemaleText_loc7`='Cierra el pico, niño. Tengo que acomodar a mi mascota en el establo.' WHERE `ID`=22303;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 여관은 북쪽의 야만인들이 깨어나기 전에 세워졌죠. 적어도 그거 하나는 다행이랍니다!$B$B오래 묵어가시나요?', `FemaleText_loc4`='这旅馆可是在北边那些野蛮人觉醒之前就建起来了。至少，感谢圣光！$B$B你在这里会呆很久吗？', `FemaleText_loc5`='這座旅店在北邊的蠻族喚醒之前就建好了。好在有聖光!$B$B你會長住在這嗎?', `FemaleText_loc7`='Esta posada fue construida antes de que se despertaran los salvajes del norte. Demos gracias a la Luz por eso.$B$B¿Te quedarás mucho?' WHERE `ID`=22304;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물건을 구경하고 싶습니다, 헤이즐.', `MaleText_loc4`='我想看看你卖的货物，哈吉尔。', `MaleText_loc5`='哈索爾，我想挑挑你的東西。', `MaleText_loc7`='Me gustaría ver tus mercancías, Hazel.', `FemaleText_loc1`='물건을 구경하고 싶어요, 헤이즐.', `FemaleText_loc4`='我想看看你卖的货物，哈吉尔。', `FemaleText_loc5`='哈索爾，我想挑挑你的東西。', `FemaleText_loc7`='Me gustaría ver tus mercancías, Hazel.' WHERE `ID`=22305;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 남자는 멍청이일 뿐입니다!$b$b명예, 부? 체! 여기는 죽음만이 입을 벌리고 기다리는 덫이라고요, 친구!$b$b전 평생 온갖 부족의 트롤을 다 봤지만 말입니다, 여기 있는 녀석들은 다릅니다. 다르지요. 비열하고, 강하고, 교활합니다...$b$b저희가 오는 줄 미리 알았다고 느껴진다고요...', `MaleText_loc4`='那家伙就是个蠢货！$B$B名望，财富？啊呸！朋友，这儿就像个死亡陷阱！$B$B我见过各种巨魔，可他们与其他巨魔截然不同——卑鄙、强壮、狡猾。$b$b他们似乎知道我们潜入了祖阿曼一样……', `MaleText_loc5`='那個人只是一個笨蛋!$b$b名聲，財富?呸!這個地方只是一個死亡陷阱罷了，老兄!$b$b在我的年代裡，我看過各式各樣的食人妖，但這些食人妖，他們不太一樣─鬼鬼祟祟、強壯又狡猾。$b$b在我看來他們早就知道我們要來了...', `MaleText_loc7`='¡Ese hombre no es más que un loco! ¿Fama... fortuna...? ¡Puff! ¡Este lugar no es más que una trampa mortal, tío!$B$BHe visto todo tipo de trols en mi vida, pero estos son diferentes: escurridizos, fuertes, tramposos.$B$BMe daba la sensación de que sabían que veníamos...' WHERE `ID`=22306;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='독과 알코... * 딸꾹* 술을 다루는 건 *딸꾹* 위험한 일이야...', `MaleText_loc4`='*嗝儿*酒精……和毒药……*嗝儿*都是很……危险的……', `MaleText_loc5`='處理*嗝*毒藥和酒...*嗝*酒精很危險...', `MaleText_loc7`='Messhclar *hip* veneno y alco... *hip* bebida esh peligrosssho...' WHERE `ID`=22307;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='재료가 필요합니다, 소렐리.', `MaleText_loc4`='我需要一些材料，苏雷。', `MaleText_loc5`='我需要一些零件，索爾立。', `MaleText_loc7`='Necesito algunos componentes, Sorely.', `FemaleText_loc1`='재료가 필요해요, 소렐리.', `FemaleText_loc4`='我需要一些材料，苏雷。', `FemaleText_loc5`='我需要一些零件，索爾立。', `FemaleText_loc7`='Necesito algunos componentes, Sorely.' WHERE `ID`=22308;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<당신이 다가오는 걸 보자 눈을 굴리는 버드>$b$b아, 당신이로군요. 곧 유명해질 $n 님!$b$b무슨 기쁜 일이 있기에 당신이 절 찾아 주셨을까요?', `MaleText_loc4`='<巴德见你走近，眼珠子一转。>$b$b哟，这不是即将成名的$n么！$b$b您大驾光临真是我的荣幸啊！', `MaleText_loc5`='<霸德看見你靠近的時候轉動了他的眼珠>$b$b喔，是的，即將成為名人的$n!$b$b我能為你和你的夥伴們做些什麼呢?', `MaleText_loc7`='<Budd gira los ojos al ver que te acercas>$B$B¡Ahh, sí, $n, quien pronto conocerá la fama!$B$B¿A qué debo el placer de tu compañía?' WHERE `ID`=22309;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 줄아만으로 보낸 친구들이 당했단 말입니다! 뭔가 조치를 취해야 한다고요!', `MaleText_loc4`='你派去祖阿曼的探险队惨遭屠杀！你倒是做点什么啊！', `MaleText_loc5`='你派去祖阿曼的小隊已經被殲滅了!你必須採取一些行動!', `MaleText_loc7`='¡Están matando al grupo que enviaste a Zul''Aman! ¡Tienes que hacer algo!', `FemaleText_loc1`='당신이 줄아만으로 보낸 친구들이 당했단 말입니다! 뭔가 조치를 취해야 해요!', `FemaleText_loc4`='你派去祖阿曼的探险队惨遭屠杀！你倒是做点什么啊！', `FemaleText_loc5`='你派去祖阿曼的小隊已經被殲滅了!你必須採取一些行動!', `FemaleText_loc7`='¡Están matando al grupo que enviaste a Zul''Aman! ¡Tienes que hacer algo!' WHERE `ID`=22310;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자자, $n 님, 심호흡 한 번 하시고 휴식을 취하시죠. 절 믿으시라고요.$b$b당신은 경험이 부족해서 이렇게 허둥지둥하고 있는 겁니다. 그리고 말이죠, 그런 상태에서는 언제나 진실이 과장되는 법이죠. 아시겠지만 위기 상황 따위는 없습니다.$b$b자, 상황이 정리됐으니 부정적인 생각은 좀 자제해 주시죠. 여기 친구들의 사기에 좋지 않으니까요...', `MaleText_loc4`='好啦，$n，放轻松点，做个深呼吸吧。你要相信我。$b$b你缺乏处理这类情况的经验，才会搞得惊惶失措。心理上的恐惧感往往会夸大事实。所以啦，根本不存在什么危机。$b$b我说，你不要这么消极嘛。这会影响到整个探险队的士气……', `MaleText_loc5`='冷靜，冷靜，$n，放輕鬆然後深呼吸一下。你應該要學著信任我。$b$b這種處境會使缺乏經驗的你慌張，而慌張總是會使人跨大實情。因此你看，其實並沒有什麼危機產生。$b$b現在我們已經解決了你的疑慮，我必須要求你消除你的負面情緒。這會影響成員們的士氣...', `MaleText_loc7`='Vamos, vamos, $n, relájate y respira hondo. Necesitas aprender a confiar en mí.$B$BTu falta de experiencia en estas situaciones está haciendo que te asustes y el miedo siempre exagera la realidad. ¿Ves? No hay ninguna crisis.$B$BAhora que hemos aclarado esto, tengo que pedirte que dejes de ser tan negativo. No es bueno para la moral del equipo...' WHERE `ID`=22311;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 장담한 것만큼 그렇게 뛰어나다면, 왜 혼자서 줄아만을 조사하지 않는 겁니까?', `MaleText_loc4`='你要是真有自己吹嘘的那么能干，为什么不亲自去调查祖阿曼呢？', `MaleText_loc5`='假如你真如你所說的那麼厲害，為什麼你不自己進入祖阿曼進行調查呢?', `MaleText_loc7`='Si eres tan bueno como dices, ¿por qué no investigas Zul''Aman tú mismo?', `FemaleText_loc1`='당신이 그렇게 장담한 것만큼 뛰어나다면, 왜 혼자서 줄아만을 조사하지 않는 거죠?', `FemaleText_loc4`='你要是真有自己吹嘘的那么能干，为什么不亲自去调查祖阿曼呢？', `FemaleText_loc5`='假如你真如你所說的那麼厲害，為什麼你不自己進入祖阿曼進行調查呢?', `FemaleText_loc7`='Si eres tan bueno como dices, ¿por qué no investigas Zul''Aman tú mismo?' WHERE `ID`=22312;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그게 무슨 멍청한 질문입니까? $n 님, 제가 당신을 과대평가했군요.$b$b누군가는 여기 남아서 전체적인 양상에 집중할 필요가 있다는 걸 모르시겠습니까? 그나마 자격이 있는 자가 저뿐이었기에, 휴우... 제가 그 짐을 지게 된 거죠.$b$b사실은 당신이 부럽습니다, $c님. 저야말로 줄아만에 발을 디디고 그 야만인들을 싹 쓸어내는 영웅이 되고 싶었지요. 당신이 얼마나 운이 좋은지 아시겠지요...', `MaleText_loc4`='愚蠢的问题！$n，看来我高估了你。$b$b你应该清楚，必须有人主持大局。我是唯一合格的人选，这副重担只能由我来挑。$b$b$c，说实话，我很羡慕你。我多想亲自深入祖阿曼，铲除那些野蛮的巨魔。你应该感到幸运才是……', `MaleText_loc5`='真是愚蠢的問題!很明顯地，$n，我高估了你。$b$b你應該很清楚的知道總是要有人顧全大局。身為唯一離合格標準還很遠的我，唉，這重擔落在我的肩頭。$b$b老實講，我很羨慕你，$c。我寧願代替其他人進入祖阿曼清理那些野蠻生物。你應該覺得很幸運才對...', `MaleText_loc7`='¡Qué pregunta más tonta! Es evidente que te he sobrestimado, $n.$B$BDebería parecer obvio que alguien tiene que estar concentrado en el plan. Esa tarea recae sobre mí, porque soy el único capacitado para ella.$B$BLa verdad es que te envidio, $c. Yo preferiría ser el que se adentre en Zul''Aman y lo limpie de esos salvajes. Deberías considerarte afortunado...' WHERE `ID`=22313;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발사!', `MaleText_loc4`='开火！', `MaleText_loc5`='射擊!', `MaleText_loc7`='¡Fuego!' WHERE `ID`=22314;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타버려라, 돌연변이 녀석들아. 타버려!', `MaleText_loc4`='烧死你们，异形，烧死你们！', `MaleText_loc5`='燒啊，突變者，燒哇!', `MaleText_loc7`='¡Arded, mutantes, ARDED!' WHERE `ID`=22315;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쭉 들이켜라고, 친구들!', `MaleText_loc4`='孩子们，喝光它！', `MaleText_loc5`='喝吧男孩們!', `MaleText_loc7`='¡Bébanselo todo, chicos!' WHERE `ID`=22316;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잔치는 시끌벅적해야 제 맛이지!', `MaleText_loc4`='不速之客闯入了聚会！', `MaleText_loc5`='派對沒有一些不請自來的人就不算是個派對啦!', `MaleText_loc7`='¡No es una fiesta si no se cuela alguien!' WHERE `ID`=22317;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 "맥주는 공짜"라고 그러지 않았어?', `MaleText_loc4`='刚才谁说有“免费的啤酒”？', `MaleText_loc5`='有人說了「啤酒免費」嗎?', `MaleText_loc7`='¿He oído a alguien decir "cerveza gratis"?' WHERE `ID`=22318;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수습생 가리온과 대화를 나누셔야 한다면, 타베사 님의 오두막 안으로 가보시지요. 적어도 그 안에서, 약재를 전부 슬쩍할 수는 없을 테지요.', `MaleText_loc4`='你可以在塔贝萨的房中找到学徒加里奥。至少，他没法偷走那儿的所有材料。', `MaleText_loc5`='假如你想跟學徒加利昂談話，他就在小屋裡跟塔貝薩在一起。至少在那邊他沒辦法偷走所有的試劑。', `MaleText_loc7`='Si necesitas hablar con el aprendiz Garion, lo encontrarás dentro de la casita con Tabetha. Por lo menos allí no puede robar los componentes.' WHERE `ID`=22319;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사제나 드루이드가 하나라도 이곳에 있으면 얼마나 좋을까요. 제 다친 곳이 다 아물기 전까지는 공부를 계속할 수가 없으니 말이지요.', `MaleText_loc4`='要是有牧师或是德鲁伊在就好了。在康复之前，我没法继续研究工作了。', `MaleText_loc5`='我真希望我們在這裡有個牧師或者德魯伊。在傷勢復原之前，我沒辦法繼續研究。', `MaleText_loc7`='Desearía que tuviéramos un sacerdote o un druida aquí. No puedo continuar mis estudios hasta que me haya recuperado de mis heridas.' WHERE `ID`=22320;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠시만, 말하지 않아도 됩니다... $n 님, 맞지요??$b$b그래, 무슨 일을 도와드리면 되겠습니까?', `MaleText_loc4`='等等，莫非……你是$n，对吧？$b$b我能为你做些什么吗？', `MaleText_loc5`='等等，不要告訴我...$n，是嗎?$b$b我能幫你什麼?', `MaleText_loc7`='Espera, no me lo digas... $n, ¿verdad?$B$B¿Qué puedo hacer por ti?' WHERE `ID`=22321;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전의 동료들은 어떻게 되었습니까?', `MaleText_loc4`='你之前的那些“伙伴”呢？', `MaleText_loc5`='你之前的「夥伴」發生了什麼事啦?', `MaleText_loc7`='¿Qué fue de tus anteriores "socios"?', `FemaleText_loc1`='전의 동료들은 어떻게 되었나요?', `FemaleText_loc4`='你之前的那些“伙伴”呢？', `FemaleText_loc5`='你之前的「夥伴」發生了什麼事啦?', `FemaleText_loc7`='¿Qué fue de tus anteriores "socios"?' WHERE `ID`=22322;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='글쎄요, 당신이 어떤 동료를 얘기하는지에 따라서 할 말이 달라지지요. 몇 년 동안 많은 동료를 만났다 헤어져서 말입니다. 버드 네드렉의 전설에 어떻게든 끼여 보려는 사람이 한둘이겠습니까?!$b$b제 지난 동료 대부분이 부자가 되어 은퇴했다는 사실은 믿어도 됩니다. 다만 그 길이 제가 가고 싶은 길은 아닐 뿐이죠. 전 항상 세계의 위대한 신비를 밝혀내는 일을 해야 한다고 생각해왔습니다. 이거 참 귀찮지만, 제가 아니면 누가 하겠습니까?', `MaleText_loc4`='哦，那要看你所说的“伙伴”是谁。这些年来来往往的人可多啦，唯有巴德·奈德雷克还保持着追寻历史传说的热诚！$b$b大部分人在收获财富之后都隐退了。不过我不会选择这样的道路。我始终觉得，我的使命就是揭开世间神秘事物的面纱。哎，我不去做的话，还有谁肯担起这个差事呢？', `MaleText_loc5`='喔，呃，看你指得是哪個夥伴啊。這些年有許多人來來去去 - 一直只有霸德·奈德瑞克這個人能夠從容的駕著傳說的順風車!$b$b你可以放心，他們大多數都已經變得富有而且都已經退休了。那不過就不是我選的路罷了。你看，我一直都覺得我發堀了這世界上許多偉大的秘密。唉，捨我其誰呢?', `MaleText_loc7`='Ah, bueno, eso depende de a qué socios te refieras. A lo largo de los años muchos han ido y venido, siempre hay alguien ansioso por aprovecharse de la leyenda que es Budd Magallenas.$B$BPuedes descansar tranquilo sabiendo que la mayoría se han jubilado siendo ricos. Pero ese no es el camino que yo he elegido. Yo siempre he sentido que mi destino es desvelar los mayores misterios del mundo. Claro, si no lo hago yo, ¿quién lo hará?' WHERE `ID`=22323;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇다면 최근에 있던 친구들은 어떻게 되었습니까?', `MaleText_loc4`='那么，新近的这支探险队呢？他们的情况如何？', `MaleText_loc5`='最近的成員過得如何 - 他們發生了什麼事?', `MaleText_loc7`='Y los últimos empleados... ¿qué fue de ellos?', `FemaleText_loc1`='최근에 있던 친구들은 어떻게 되었죠?', `FemaleText_loc4`='那么，新近的这支探险队呢？他们的情况如何？', `FemaleText_loc5`='最近的成員過得如何 - 他們發生了什麼事?', `FemaleText_loc7`='Y los últimos empleados... ¿qué fue de ellos?' WHERE `ID`=22324;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 그 친구들이야말로 비극의 주인공이지요.$b$b그들은 줄아만의 저 벽 너머에서 자취를 감췄습니다. 한동안 그들에 대한 소식은 듣지 못했지요.$b$b전 말입니다, 명성과 부에 대한 지나친 집착을 수백 번도 더 봐왔지요. 그들을 잡아두려고도 하고, 아직 준비되지 않았으니 무리라고 설득도 했지만... 결국 그 친구들은 위험에 뛰어들고 말았습니다...', `MaleText_loc4`='啊，他们呀——悲惨的结局。$b$b探险队进入祖阿曼已有数日，至今音信全无。$b$b类似的情形我也见得多了，这帮被名誉和财富冲昏了头脑的蠢货。我警告过他们，没有做好充分的准备就别贸然涉险，可惜他们压根儿没听进去……', `MaleText_loc5`='啊，他們啊 - 那是一個令人難過的故事。$b$b他們消失在祖阿曼城牆後了。我已經好一陣子沒聽說他們的消息。$b$b這種事我已經遇過上百次了;過份的渴求名聲及財寶。我試著阻止他們，告訴他們他們還沒準備好，但是最後他們選擇了冒險...', `MaleText_loc7`='Ah, ellos. Una triste historia.$B$BHan desaparecido tras los muros de Zul''Aman. Hace días que no sé nada de ellos.$B$BLo he visto cientos de veces; esa necesidad desenfrenada de obtener fama y fortuna. Intenté detenerlos, les dije que no estaban preparados, pero ellos decidieron correr el riesgo...' WHERE `ID`=22325;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런, 버드 씨... 살아서 당신 얘기가 사실이라고 증명해 줄 이가 하나라도 있습니까?', `MaleText_loc4`='我说，巴德，有谁能证明你所说的话吗？', `MaleText_loc5`='啊，霸德，有任何還活著的人可以證實你的說法嗎?', `MaleText_loc7`='Vaya, Budd, ¿queda alguien vivo que pueda apoyar tu historia?', `FemaleText_loc1`='이런, 버드 씨... 살아서 당신 얘기가 사실이라고 증명해 줄 이가 하나라도 있나요?', `FemaleText_loc4`='我说，巴德，有谁能证明你所说的话吗？', `FemaleText_loc5`='啊，霸德，有任何還活著的人可以證實你的說法嗎?', `FemaleText_loc7`='Vaya, Budd, ¿queda alguien vivo que pueda apoyar tu historia?' WHERE `ID`=22326;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거 보세요 $n 님, 운이라는 게 언제나 당신 방문을 두드리는 게 아니라는 걸 알아두십시오. 우선 문부터 열고 질문은 나중에 하시라고요. 이런 기회가 항상 있는 건 아닙니다!$b$b그래서, 같이 할 겁니까 말 겁니까, $c님?$b$b<대답을 기다리지 않는 버드>$b$b물론 함께하시겠죠! 자, 할 일이 있는데 지금껏 떠들기만 하고 행동으로 옮기진 않으셨죠. 뭔가 보여주시지 않으면 다른 이를 그 자리에 앉힐지도 모릅니다.$b$b이런 기회라면 죽는시늉이라도 할 친구들이 수천 명이라고요, 네!', `MaleText_loc4`='听着，$n，聪明的话就别放弃唾手可得的财富。这种好事不是每天都能碰上的！$b$b那么，$c，你愿意加入探险队吗？$b$b<巴德没等你答话便继续开口。>$b$b你显然是愿意啦！还有很多工作要做呢，你这家伙废话不少，却没有一点实质行动嘛。你最好做出点成绩给我看，不然我就找人顶替你的位置。$b$b我敢打赌，这样的机遇不知道有多少人垂涎呢！', `MaleText_loc5`='聽著，$n，你應該知道既然當財寶來敲門，你應該打開門先，然後再發問。像這樣的機會不是天天都有的!$b$b現在，你到底要不要加入，$c?$b$b<霸德不等你回答。>$b$b你當然會加入!現在，有件事要先完成，不過到目前我看過了太多人只說不做。我建議你在我找到替代者前先讓我看看你的能耐。$b$b我跟你保證，世上有上千人願意為了這樣的機會而死!', `MaleText_loc7`='Escucha, $n. A estas alturas ya deberías saber que cuando la fortuna llama a tu puerta, primero abres y luego preguntas. ¡No todos los días se presentan oportunidades como esta!$B$B¿Te apuntas o no, $c?$B$B<Budd no espera una respuesta>$B$B¡Pues claro que sí! Vamos, hay mucho trabajo y de momento solo he visto mucha palabrería pero poca acción. Más vale que me demuestres algo antes de que encuentre un sustituto.$B$B¡Te aseguro que mucha gente mataría por una oportunidad como esta!' WHERE `ID`=22327;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요! 저흰 저 아무짝에도 쓸모없는 해적 녀석들이 막고 있어서 완전히 발이 묶였어요.$B$B좀 도와주지 않으실래요?', `MaleText_loc4`='喂喂！我们被那群该死的海盗给堵在海湾里了！$B$B能帮我们出去吗？', `MaleText_loc5`='嗨!我們被那些沒用的海賊給擋在海灣了!$B$B你覺得你有辦法幫助我們逃出去嗎?', `MaleText_loc7`='¡Hola! Esos inútiles piratas nos están bloqueando en la bahía.$B$B¿Crees que puedes ayudarnos?' WHERE `ID`=22328;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요! 저흰 저 아무짝에도 쓸모없는 해적 녀석들이 막고 있어서 완전히 발이 묶였어요.$B$B당신이 폭탄을 몇 발 떨어뜨려 주시면 도움이 될 것 같은데 생각 있으신가요?!$B$B도둑맞은 저희 비행선이 여기 도착했어요. 비행선이 떠나기 전에 어서 타세요!', `MaleText_loc4`='喂喂！我们被那群该死的海盗给堵在海湾里了！$B$B朝他们丢炸弹，看能不能帮我们出去？$B$B我们偷来的飞艇就在那边，趁它起航之前跳上去！', `MaleText_loc5`='你好!我們被海灘上的廢物海賊給困住了!你想你可不可以幫我們的忙，在他們的頭上丟炸彈呢?!$B$B我們偷來的飛艇來了;在她起錨以前快跳上船去!', `MaleText_loc7`='¡Hola! Esos inútiles piratas nos están bloqueando en la bahía.$B$B¿Crees que puedes ayudarnos lanzándoles unas cuantas bombas?$B$BNuestro zepelín robado está aquí, ¡salta a bordo antes de que zarpe!' WHERE `ID`=22329;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요! 저흰 저 아무짝에도 쓸모없는 해적 녀석들이 막고 있어서 완전히 발이 묶였어요.$B$B당신이 폭탄을 몇 발 떨어뜨려 주시면 도움이 될 것 같은데 생각 있으신가요?!$B$B도둑맞은 저희 비행선이 도착하려면 $3078w분도 안 걸릴 거예요. 비행선이 떠나기 전에 꼭 타도록 하세요!', `MaleText_loc4`='喂喂！我们被那群该死的海盗给堵在海湾里了！$B$B朝他们丢炸弹，看能不能帮我们出去？$B$B我们偷来的飞艇在$3078w分钟后就要起航了。趁它起飞之前跳上去！', `MaleText_loc5`='你好!我們被海灘上的廢物海賊給困住了!你想你可不可以幫我們的忙，在他們的頭上丟炸彈呢?!$B$B我們偷來的飛艇$3078w分鐘以內就會到了。在她離開之前記得上去喔!', `MaleText_loc7`='¡Hola! Esos inútiles piratas nos están bloqueando en la bahía.$B$B¿Crees que puedes ayudarnos lanzándoles unas cuantas bombas?$B$BNuestro zepelín robado está a menos de $3078w minutos de aquí. ¡Asegúrate de estar a bordo cuando zarpe!' WHERE `ID`=22330;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요! 저흰 저 아무짝에도 쓸모없는 해적 녀석들이 막고 있어서 완전히 발이 묶였어요.$B$B당신이 폭탄을 몇 발 떨어뜨려 주시면 도움이 될 것 같은데 생각 있으신가요?!$B$B도둑맞은 저희 비행선이 이제 거의 다 왔어요... 이제 소리가 들리는 것 같네요. 비행선이 떠나기 전에 꼭 타도록 하세요!', `MaleText_loc4`='喂喂！我们被那群该死的海盗给堵在海湾里了！$B$B朝他们丢炸弹，看能不能帮我们出去？$B$B我们偷来的飞艇就在那里……我都听见它的声音了！趁它起航之前跳上去！', `MaleText_loc5`='你好!我們被海灘上的廢物海賊給困住了!你想你可不可以幫我們的忙，在他們的頭上丟炸彈呢?!$B$B我們偷來的飛艇就在這附近...我想我聽見她的聲音了。在她離開之前記得上去喔!', `MaleText_loc7`='¡Hola! Esos inútiles piratas nos están bloqueando en la bahía.$B$B¿Crees que puedes ayudarnos lanzándoles unas cuantas bombas?$B$BNuestro zepelín robado casi está aquí... Creo que lo oigo. ¡Asegúrate de estar a bordo cuando zarpe!' WHERE `ID`=22331;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 완전히 죄수 신세라고! 저놈들이 나와 내 아름다운 비행선에 총질을 해 댔지. 대체 뭣 때문에? 내가 호드의 병력과 물건을 실어날라서? 그건 어제오늘 일도 아니잖아!$B$B게다가 이제는 해적 놈들에게 폭탄을 떨어뜨린다면서 비행선으로 이 만을 빙빙 선회하게 한다고. 비행선을 계속 이런 식으로 운행하기에는 부품이 한참 부족한데 말이야! 지금은 쇠꼬챙이와 철사 쪼가리로 간신히 배를 날리는 상태지.$B$B분명히 말하건대 이건 범죄 행위라고!', `MaleText_loc4`='我是个囚犯！$B$B这帮混蛋把我美丽的飞艇从天上打了下来。你知道这是为什么吗？就因为我帮部落运输了一些士兵和补给物资！这算什么新鲜事嘛！真是的！$B$B现在他们逼我开着飞艇在海湾上巡逻，帮他们轰炸海盗。现在飞艇的零件短缺得厉害，她随时都有坠毁的危险！我几乎靠口水和绳子才能保证她不散架！$B$B我跟你说，这是违法的！', `MaleText_loc5`='我簡直就是個囚犯!$B$B他們把我和我美麗的飛艇從空中打了下來。為了什麼?只為了我是運輸人員所以我算部落軍方的人?這可不是什麼新鮮事!$B$B然後他們要我開著她在海灘上繞圈圈，好讓他們可以轟炸海賊。我沒辦法讓飛艇這樣一直飛啊!我可不能光靠口水和鐵絲讓她不會散開來!$B$B我告訴你，這是犯罪!', `MaleText_loc7`='¡Soy un prisionero!$B$BMe derribaron junto a mi precioso zepelín. ¿Y por qué? ¿Por transportar hombres y material para la Horda? ¡Eso no es nuevo!$B$BAhora me obligan a dar vueltas a la bahía con él para bombardear a los piratas. ¡No puedo seguir así! ¡Apenas lo puedo mantener íntegro a base de saliva y alambre!$B$B¡Te digo que es un crimen!' WHERE `ID`=22332;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 완전히 죄수 신세라고! 저놈들이 나와 내 아름다운 비행선에 총질을 해 댔지. 대체 뭣 때문에? 내가 호드의 병력과 물건을 실어날라서? 그건 어제오늘 일도 아니잖아!$B$B게다가 이제는 해적 놈들에게 폭탄을 떨어뜨린다면서 비행선으로 이 만을 빙빙 선회하게 한다고. 비행선을 계속 이런 식으로 운행하기에는 부품이 한참 부족한데 말이야! 지금은 쇠꼬챙이와 철사 쪼가리로 간신히 배를 날리는 상태지.$B$B자네도 비행선이 떠나기 전에 올라탈 작정이겠지. 자네한테 무슨 일이 벌어지든 내게는 책임이 없다는 걸 알아 둬.$B$B분명히 말하건대 이건 범죄 행위라고!', `MaleText_loc4`='我是个囚犯！$B$B这帮混蛋把我美丽的飞艇从天上打了下来。你知道这是为什么吗？就因为我帮部落运输了一些士兵和补给物资！这算什么新鲜事嘛！真是的！$B$B现在他们逼我开着飞艇在海湾上巡逻，帮他们轰炸海盗。现在飞艇的零件短缺得厉害，她随时都有坠毁的危险！我几乎靠口水和绳子才能保证她不散架！$B$B你要是出了什么事，我可不负责，不过你最好趁她起航前跳上去。$B$B我跟你说，这是违法的！', `MaleText_loc5`='我簡直就是個囚犯!$B$B他們把我和我美麗的飛艇從空中打了下來。為了什麼?只為了我是運輸人員所以我算部落軍方的人?這可不是什麼新鮮事!$B$B然後他們要我開著她在海灘上繞圈圈，好讓他們可以轟炸海賊。我沒辦法讓飛艇這樣一直飛啊!我可不能光靠口水和鐵絲讓她不會散開來!$B$B你要是發生了什麼事，我可沒辦法負責，但是你還是得在飛艇離開前趕緊上去。$B$B我告訴你，這是犯罪!', `MaleText_loc7`='¡Soy un prisionero!$B$BMe derribaron junto a mi precioso zepelín. ¿Y por qué? ¿Por transportar hombres y material para la Horda? ¡Eso no es nuevo!$B$BAhora me obligan a dar vueltas a la bahía con él para bombardear a los piratas. ¡No puedo seguir así! ¡Apenas lo puedo mantener íntegro a base de saliva y alambre!$B$BNo me hago responsable de lo que te pueda ocurrir, pero deberías subir a bordo antes de que zarpe.$B$B¡Te digo que es un crimen!' WHERE `ID`=22333;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 완전히 죄수 신세라고! 저놈들이 나와 내 아름다운 비행선에 총질을 해 댔지. 대체 뭣 때문에? 내가 호드의 병력과 물건을 실어날라서? 그건 어제오늘 일도 아니잖아!$B$B게다가 이제는 해적 놈들에게 폭탄을 떨어뜨린다면서 비행선으로 이 만을 빙빙 선회하게 한다고. 비행선을 계속 이런 식으로 운행하기에는 부품이 한참 부족한데 말이야! 지금은 쇠꼬챙이와 철사 쪼가리로 간신히 배를 날리는 상태지.$B$B자네가 저 친구들을 도우려고 여기 왔다면 말인데, 배는 1분 내로 승강장에 들어올 거야.$B$B분명히 말하건대 이건 범죄 행위라고!', `MaleText_loc4`='我是个囚犯！$B$B这帮混蛋把我美丽的飞艇从天上打了下来。你知道这是为什么吗？就因为我帮部落运输了一些士兵和补给物资！这算什么新鲜事嘛！真是的！$B$B现在他们逼我开着飞艇在海湾上巡逻，帮他们轰炸海盗。现在飞艇的零件短缺得厉害，她随时都有坠毁的危险！我几乎靠口水和绳子才能保证她不散架！$B$B如果你愿意帮忙的话，就去那边候着吧。她在1分钟之内就会入港。$B$B我跟你说，这是违法的！', `MaleText_loc5`='我簡直就是個囚犯!$B$B他們把我和我美麗的飛艇從空中打了下來。為了什麼?只為了我是運輸人員所以我算部落軍方的人?這可不是什麼新鮮事!$B$B然後他們要我開著她在海灘上繞圈圈，好讓他們可以轟炸海賊。我沒辦法讓飛艇這樣一直飛啊!我可不能光靠口水和鐵絲讓她不會散開來!$B$B如果你想要幫他們的忙，她一分鐘之內就會返回港口。$B$B我告訴你，這是犯罪!', `MaleText_loc7`='¡Soy un prisionero!$B$BMe derribaron junto a mi precioso zepelín. ¿Y por qué? ¿Por transportar hombres y material para la Horda? ¡Eso no es nuevo!$B$BAhora me obligan a dar vueltas a la bahía con él para bombardear a los piratas. ¡No puedo seguir así! ¡Apenas lo puedo mantener íntegro a base de saliva y alambre!$B$BSi estás seguro de que quieres ayudarles, volverá a atracar en el puerto en menos de un minuto.$B$B¡Te digo que es un crimen!' WHERE `ID`=22334;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 완전히 죄수 신세라고! 저놈들이 나와 내 아름다운 비행선에 총질을 해 댔지. 대체 뭣 때문에? 내가 호드의 병력과 물건을 실어날라서? 그건 어제오늘 일도 아니잖아!$B$B게다가 이제는 해적 놈들에게 폭탄을 떨어뜨린다면서 비행선으로 이 만을 빙빙 선회하게 한다고. 비행선을 계속 이런 식으로 운행하기에는 부품이 한참 부족한데 말이야! 지금은 쇠꼬챙이와 철사 쪼가리로 간신히 배를 날리는 상태지.$B$B자네가 저 친구들을 도우려고 여기 왔다면 말인데, 배는 $3078w분 내로 승강장에 들어올 거야.$B$B분명히 말하건대 이건 범죄 행위라고!', `MaleText_loc4`='我是个囚犯！$B$B这帮混蛋把我美丽的飞艇从天上打了下来。你知道这是为什么吗？就因为我帮部落运输了一些士兵和补给物资！这算什么新鲜事嘛！真是的！$B$B现在他们逼我开着飞艇在海湾上巡逻，帮他们轰炸海盗。现在飞艇的零件短缺得厉害，她随时都有坠毁的危险！我几乎靠口水和绳子才能保证她不散架！$B$B如果你愿意帮忙的话，就去那边候着吧。她在$3078w分钟之内就会入港。$B$B我跟你说，这是违法的！', `MaleText_loc5`='我簡直就是個囚犯!$B$B他們把我和我美麗的飛艇從空中打了下來。為了什麼?只為了我是運輸人員所以我算部落軍方的人?這可不是什麼新鮮事!$B$B然後他們要我開著她在海灘上繞圈圈，好讓他們可以轟炸海賊。我沒辦法讓飛艇這樣一直飛啊!我可不能光靠口水和鐵絲讓她不會散開來!$B$B如果你真的想幫他們，她會在$3078w分鐘以內返回港口。$B$B我告訴你，這是犯罪!', `MaleText_loc7`='¡Soy un prisionero!$B$BMe derribaron junto a mi precioso zepelín. ¿Y por qué? ¿Por transportar hombres y material para la Horda? ¡Eso no es nuevo!$B$BAhora me obligan a dar vueltas a la bahía con él para bombardear a los piratas. ¡No puedo seguir así! ¡Apenas lo puedo mantener íntegro a base de saliva y alambre!$B$BSi estás seguro de que quieres ayudarles, volverá a atracar en el puerto en menos de $3078w minutos.$B$B¡Te digo que es un crimen!' WHERE `ID`=22335;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비행선이 도착했습니다. 비행선 기장은 포로 신세고 비행선 꼴도 말이 아니지만, 어쨌거나 비행선은 2분 안에 다시 출발합니다.', `MaleText_loc4`='我的飞艇刚刚入港。虽然我被扣押起来充当人质，而且飞艇本身的状态也不太好，但是2分钟后，她就要再度起航了。', `MaleText_loc5`='我的飛艇已經靠岸了。儘管我被困為俘虜，以及她身處的糟糕情況，但是她會在兩分鐘後啟程離開碼頭。', `MaleText_loc7`='Mi zepelín ha atracado. A pesar de que estoy cautivo y del pobre estado en el que se encuentra, volverá a abandonar el muelle en dos minutos.' WHERE `ID`=22336;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비행선이 항구 주변을 선회하러 1분 안에 출발합니다! 아, 그리고 누구든 저를 풀어주고 싶으시다면, 제가 비행선 선착장에 있단 걸 기억해 주세요!', `MaleText_loc4`='1分钟后，飞艇就要出发绕海湾一圈了！有没有谁想搭救我啊，我就在码头上。', `MaleText_loc5`='飛艇繞著海灣飛行用不到一分鐘!喔，還有，如果任何人想要放了我，我就在碼頭上。', `MaleText_loc7`='El zepelín zarpará para dar una vuelta a la bahía en menos de un minuto. Ah y si a alguien le apetece liberarme, estaré en el muelle.' WHERE `ID`=22337;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타오르던 화염이 안전하게 사그라졌습니다.', `MaleText_loc4`='熊熊燃烧的火焰熄灭了。', `MaleText_loc5`='燃燒的火焰被安全地熄滅了。', `MaleText_loc7`='Las llamas han sido apagadas de forma segura.' WHERE `ID`=22338;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어지럽히는 중', `MaleText_loc4`='打断', `MaleText_loc5`='撥弄', `MaleText_loc7`='Estropeando', `FemaleText_loc1`='어지럽히는 중', `FemaleText_loc4`='打断', `FemaleText_loc5`='撥弄', `FemaleText_loc7`='Estropeando' WHERE `ID`=22339;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에잇, 후퇴다!!!!', `MaleText_loc4`='撤退！！！！', `MaleText_loc5`='撤退!!!!', `MaleText_loc7`='RETIRADA' WHERE `ID`=22340;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래서, 그 줄아만 발굴 작업은 언제 시작되는 겁니까?', `MaleText_loc4`='那么，祖阿曼的挖掘工作何时开始呀？', `MaleText_loc5`='那麼，這趟祖阿曼的挖掘之旅何時開始呢?', `MaleText_loc7`='¿Cuándo comienza esa excavación de Zul’aman?', `FemaleText_loc1`='그래서, 그 줄아만 발굴 작업은 언제 시작되죠?', `FemaleText_loc4`='那么，祖阿曼的挖掘工作何时开始呀？', `FemaleText_loc5`='那麼，這趟祖阿曼的挖掘之旅何時開始呢?', `FemaleText_loc7`='¿Cuándo comienza esa excavación de Zul’aman?' WHERE `ID`=22341;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거 보세요 $n 님, 운이라는 게 언제나 당신 방문을 두드리는 게 아니라는 걸 알아두십시오. 우선 문부터 열고 질문은 나중에 하시라고요. 이런 기회가 항상 있는 건 아닙니다!$b$b그래서, 같이 할 겁니까 말 겁니까?$b$b<대답을 기다리지 않는 버드>$b$b물론 함께하시겠죠! 자, 할 일이 있는데 지금껏 떠들기만 하고 행동으로 옮기진 않으셨죠. 뭔가 보여주시지 않으면 다른 이를 그 자리에 앉힐지도 모릅니다.$b$b이런 기회라면 죽는시늉이라도 할 친구들이 수천 명이라고요, 네!', `MaleText_loc4`='听着，$n，聪明的话就别放弃唾手可得的财富。这种好事不是每天都能碰上的！$b$b那么，$c，你愿意加入探险队吗？$b$b<巴德没等你答话便继续开口。>$b$b你显然是愿意啦！还有很多工作要做呢，你这家伙废话不少，却没有一点实质行动嘛。你最好做出点成绩给我看，不然我就找人顶替你的位置。$b$b我敢打赌，这样的机遇不知道有多少人垂涎呢！', `MaleText_loc5`='聽著，$n，你應該知道當財富送上門的時候要先開門，其他的以後再說。這種機會可不是天天都有!你到底要不要加入呢?$b$b<霸德並沒有等你回答。>$b$b當然你要加入!現在我有件工作要交給你，目前為止我只看到你耍嘴皮子，卻沒有採取任何行動。我建議在我找別人替代你之前向我展現一點誠意。$b$b我向你保證，數以千計的人都渴望擁有這種機會!', `MaleText_loc7`='Escucha, $n. A estas alturas ya deberías saber que cuando la fortuna llama a tu puerta, primero abres y luego preguntas. ¡No todos los días se presentan oportunidades como esta! ¿Te apuntas o no?$B$B<Budd no espera una respuesta>$B$B¡Pues claro que sí! Vamos, hay mucho trabajo y de momento solo he visto mucha palabrería pero poca acción. Más vale que me demuestres algo antes de que encuentre un sustituto.$B$B¡Te aseguro que mucha gente mataría por una oportunidad como esta!' WHERE `ID`=22342;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기다리세요, $n 님. 제가 일을 서두르기만 했다면 지금의 버드 네드렉이 되지 못했을 겁니다.$b$b지금 최종 준비를 하는 중입니다. 곧 줄아만의 보물과 비밀이 모두 제 것이 될 겁니다!$b$b<잠시 멈춰 당신을 쳐다보더니 킬킬대며 웃는 버드>$b$b아, 제 말은... 우리 것이 된다 이거지요... 네.', `MaleText_loc4`='$n，要有耐心。若是我像你这般草率行事，也就不会成名了。$b$b做好最后的准备工作，祖阿曼的财富和秘密很快就属于我啦！$b$b<巴德看了看你，轻声地笑了。>$b$b……哎呀，我是说属于我们俩啦。', `MaleText_loc5`='拿出你的耐心來，$n。我可不是靠著倉促行事而贏得霸德·奈德瑞克這個名號的。$b$b我已經在做最後的準備，而不久之後祖阿曼的寶藏和秘密都將屬於我的了!$b$b<霸德停止說話並且看了你一下，然後輕笑著。>$b$b...當然，我是說我們的了。', `MaleText_loc7`='Paciencia, $n. No me convertí en el conocidísimo Budd Magallenas a base de apresurarme.$B$B¡Se están llevando a cabo las preparaciones finales y pronto los secretos y tesoros de Zul''Aman serán míos!$B$B<Budd se detiene y te mira durante un instante, entonces se ríe.>$B$B...Quiero decir nuestros, por supuesto.' WHERE `ID`=22343;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으앙, 나 고아원으로 돌아갈래!', `MaleText_loc4`='我想回孤儿院！', `MaleText_loc5`='我要回去孤兒院!', `MaleText_loc7`='¡Quiero volver al orfanato!', `FemaleText_loc1`='으앙, 나 고아원으로 돌아갈래!', `FemaleText_loc4`='我想回孤儿院！', `FemaleText_loc5`='我要回去孤兒院!', `FemaleText_loc7`='¡Quiero volver al orfanato!' WHERE `ID`=22344;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원장님! 저 나쁜 아저씨가 우릴 잡아먹는 건가요?', `MaleText_loc4`='监护员！那个坏人是来吃我们的吗？', `MaleText_loc5`='監護員!那個壞人要來吃了我們嗎?', `MaleText_loc7`='¡Matrona! ¿Nos va a comer ese hombre malo?', `FemaleText_loc1`='원장님! 저 나쁜 아저씨가 우릴 잡아먹는 건가요?', `FemaleText_loc4`='监护员！那个坏人是来吃我们的吗？', `FemaleText_loc5`='監護員!那個壞人要來吃了我們嗎?', `FemaleText_loc7`='¡Matrona! ¿Nos va a comer ese hombre malo?' WHERE `ID`=22345;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 아빠가 살아 계셨으면 불을 꺼 주셨을 텐데!', `MaleText_loc4`='要是我爸爸活着的话，他会把火灭掉的！', `MaleText_loc5`='要是我爸還活著，他就會熄滅那些火焰!', `MaleText_loc7`='¡Si mi padre estuviera vivo, apagaría los fuegos!', `FemaleText_loc1`='저 불 따위 우리 아빠가 살아 계셨으면 아무것도 아니었을걸!', `FemaleText_loc4`='要是我爸爸活着的话，他会把火灭掉的！', `FemaleText_loc5`='要是我爸還活著，他就會熄滅那些火焰!', `FemaleText_loc7`='¡Si mi padre estuviera vivo, apagaría los fuegos!' WHERE `ID`=22346;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 엄마가 살아 계셨으면 저 불을 다 꺼 주셨을걸!', `MaleText_loc4`='要是我妈妈活着的话，她会把火灭掉的！', `MaleText_loc5`='要是我媽還活著，她就會熄滅那些火焰!', `MaleText_loc7`='¡Si mi madre estuviera viva, apagaría los fuegos!', `FemaleText_loc1`='우리 엄마가 살아 계셨다면 불을 꺼 주셨을 거야!', `FemaleText_loc4`='要是我妈妈活着的话，她会把火灭掉的！', `FemaleText_loc5`='要是我媽還活著，她就會熄滅那些火焰!', `FemaleText_loc7`='¡Si mi madre estuviera viva, apagaría los fuegos!' WHERE `ID`=22347;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='집들이 선물 가져왔네, 자를.', `MaleText_loc4`='加尔，这是送你的礼物，祝贺你乔迁新居。', `MaleText_loc5`='我要送你一個喬遷之喜的禮物，加爾。', `MaleText_loc7`='Te he traído un regalo de bienvenida, Jarl.' WHERE `ID`=22348;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 열어보게. 맘에 들 것 같은데...', `MaleText_loc4`='来吧，打开它。我想你会喜欢的。', `MaleText_loc5`='不要緊，打開吧。我想你會喜歡它。', `MaleText_loc7`='Vamos, ábrelo. Creo que te gustará.' WHERE `ID`=22349;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자를?', `MaleText_loc4`='加尔？', `MaleText_loc5`='加爾?', `MaleText_loc7`='¿Jarl?' WHERE `ID`=22350;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='먹을 게 아니면, 받고 싶지 않네.', `MaleText_loc4`='除非是吃的东西，否则我不想要。', `MaleText_loc5`='除非這是我可以吃的東西，不然我不要。', `MaleText_loc7`='A menos que sea algo que se pueda comer, no lo quiero.' WHERE `ID`=22351;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자를, 내가 왔을 때부터 여태까지 계속 정신을 못 차리고 있잖아. 무슨 일이라도 있나?', `MaleText_loc4`='加尔，我总觉得你不太对劲。出了什么事？', `MaleText_loc5`='加爾，自從我來了以後你一點都不像從前的你。到底發生了什麼事?', `MaleText_loc7`='Jarl, no has sido tú mismo desde que llegué. ¿Qué está pasando?' WHERE `ID`=22352;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무 일도 없네. 이 개구리 다리 스튜 만드는 거나 도와주겠나?', `MaleText_loc4`='没什么。有兴趣帮我炖青蛙腿吗？', `MaleText_loc5`='沒事。想不想幫我攪拌一下那些青蛙腿燉肉呢?', `MaleText_loc7`='Nada. ¿Quieres ayudarme a preparar un estofado de anca de rana?' WHERE `ID`=22353;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기까지 온 건 자넬 보고 싶어서네, 자를! 그랬더니 이런 알 수 없는 곳에 텅텅 빈 오두막집에서 개구리 타령이나 하며 살고 있다니! 절망 그 자체로군!', `MaleText_loc4`='加尔，我专程来拜访你！你却躲在这个偏僻的小屋里炖青蛙腿？真是无可救药！', `MaleText_loc5`='我到這裡來是為了看你，加爾!結果我看你竟然住在一個空蕩蕩的小屋裡，四周是鳥不生蛋的地方，並且嘴裡講的竟然是關於青蛙的事情?你真是沒救了!', `MaleText_loc7`='¡He venido a visitarte, Jarl! ¡Y te encuentro viviendo en una cabaña vacía en medio de la nada balbuceando sobre ranas! ¡Eres un caso perdido!' WHERE `ID`=22354;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 우물 너머로 노랫가락을 흥얼거립니다.', `FemaleText_loc4`='%s在井旁哼唱了一支小曲。', `FemaleText_loc5`='%s在井邊哼著歌。', `FemaleText_loc7`='%s tararea una melodía junto al pozo.' WHERE `ID`=22355;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 한숨을 쉽니다.', `FemaleText_loc4`='%s叹了口气。', `FemaleText_loc5`='%s嘆了口氣。', `FemaleText_loc7`='%s suspira.' WHERE `ID`=22356;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 미소 지으며 우물에서 물을 길어올립니다.', `FemaleText_loc4`='%s笑了笑，继续从井中打水。', `FemaleText_loc5`='%s笑咪咪的從井底打著水。', `FemaleText_loc7`='%s sonríe mientras continúa sacando agua del pozo.' WHERE `ID`=22357;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='리산이 우물에 동전을 떨어트리며 본 사람이 없는지 주변을 살핍니다.', `FemaleText_loc4`='莉丝安向井中扔下一枚硬币，然后环顾四周观察着是否有人注意到她。', `FemaleText_loc5`='利桑擲了一枚銅板到井中，還四處張望有沒有人發現。', `FemaleText_loc7`='Lissan tira una moneda al pozo y se da la vuelta para ver si alguien se ha dado cuenta.' WHERE `ID`=22358;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가버리십시오, 당신이 누구든 간에! 마녀 언덕은 내 겁니다... 내 거요!', `MaleText_loc4`='管你是谁，给我滚远点！女巫岭属于我……属于我！', `MaleText_loc5`='不管你是誰，都給我滾開!女巫嶺是我的...我的!', `MaleText_loc7`='¡Vete... seas quién seas! La Colina de las Brujas es mía... ¡mía!', `FemaleText_loc1`='가버려요, 당신이 누구든 간에! 마녀 언덕은 제 거예요... 제 거란 말이에요!', `FemaleText_loc4`='管你是谁，给我滚远点！女巫岭属于我……属于我！', `FemaleText_loc5`='不管你是誰，都給我滾開!女巫嶺是我的...我的!', `FemaleText_loc7`='¡Vete... seas quién seas! La Colina de las Brujas es mía... ¡mía!' WHERE `ID`=22359;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 녀석은... 끔찍한... 악마였습니다...', `MaleText_loc4`='太……太可怕了……恶魔……', `MaleText_loc5`='太...恐怖了...這個惡魔...', `MaleText_loc7`='Fue... terrible... el demonio...', `FemaleText_loc1`='그 녀석은... 끔찍한... 악마였어요...', `FemaleText_loc4`='太……太可怕了……恶魔……', `FemaleText_loc5`='太...恐怖了...這個惡魔...', `FemaleText_loc7`='Fue... terrible... el demonio...' WHERE `ID`=22360;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 영지는... 누군가 다른 사람까지... 곧 타버릴 겁니다...', `MaleText_loc4`='庄园……下一个牺牲者……很快就会被吞噬……', `MaleText_loc5`='這個領地...還有人...將很快的被消滅...', `MaleText_loc7`='La casa... alguien más... pronto se consumirá', `FemaleText_loc1`='그 영지는... 누군가 다른 사람까지... 곧 다 타버릴 거예요...', `FemaleText_loc4`='庄园……下一个牺牲者……很快就会被吞噬……', `FemaleText_loc5`='這個領地...還有人...將很快的被消滅...', `FemaleText_loc7`='La casa... alguien más... pronto se consumirá' WHERE `ID`=22361;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='암흑... 부패... 이 모두가 아무도 눈치를 못 챌 만큼 빠르게 들이닥쳤습니다.', `MaleText_loc4`='黑暗……堕落……悄无声息地侵蚀了大地……', `MaleText_loc5`='黑暗...墮落...來得比任何人得知的還快...', `MaleText_loc7`='La oscuridad... la corrupción... vinieron demasiado rápido sin que nadie se diera cuenta...', `FemaleText_loc1`='암흑... 부패... 이 모두가 아무도 눈치를 못 챌 만큼 빠르게 들이닥쳤어요.', `FemaleText_loc4`='黑暗……堕落……悄无声息地侵蚀了大地……', `FemaleText_loc5`='黑暗...墮落...來得比任何人得知的還快...', `FemaleText_loc7`='La oscuridad... la corrupción... vinieron demasiado rápido sin que nadie se diera cuenta...' WHERE `ID`=22362;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 여기에 왔습니까, 이방인이여? 고통만이 있을 뿐인데! 당신도 우리와 같은 운명에 놓일 겁니다...', `MaleText_loc4`='陌生人，你来这儿做什么？你会堕入痛苦的深渊！落得和我们一样的下场……', `MaleText_loc5`='你為什麼到這裡來，外來者?你將只有痛苦而已!你的命運將與我們相同...', `MaleText_loc7`='¿Por qué has venido aquí? ¡Solo encontrarás dolor! Nuestro destino será el tuyo...', `FemaleText_loc1`='왜 여기에 왔나요, 이방인이여? 고통만이 있을 뿐인데! 당신도 우리와 같은 운명에 놓일 텐데요...', `FemaleText_loc4`='陌生人，你来这儿做什么？你会堕入痛苦的深渊！落得和我们一样的下场……', `FemaleText_loc5`='你為什麼到這裡來，外來者?你將只有痛苦而已!你的命運將與我們相同...', `FemaleText_loc7`='¿Por qué has venido aquí? ¡Solo encontrarás dolor! Nuestro destino será el tuyo...' WHERE `ID`=22363;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='암흑이 전부 삼켜버릴 것입니다... 살아 있는 존재는 모두...', `MaleText_loc4`='黑暗将吞噬一切……生命……', `MaleText_loc5`='黑暗將會消滅所有...所有活著的事物...', `MaleText_loc7`='La oscuridad consumirá a todos... todos los vivos...', `FemaleText_loc1`='암흑이 남김없이 삼켜버릴 거예요... 살아 있는 존재는 모두...', `FemaleText_loc4`='黑暗将吞噬一切……生命……', `FemaleText_loc5`='黑暗將會消滅所有...所有活著的事物...', `FemaleText_loc7`='La oscuridad consumirá a todos... todos los vivos...' WHERE `ID`=22364;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희는 틀렸습니다, 생명이 있으신 분이여. 어서 친구와 함께 여기를 벗어나십시오... 둘 다 목숨을 잃기 전에...', `MaleText_loc4`='太晚了。趁你们还活着……赶紧带着你的朋友离开这里吧。', `MaleText_loc5`='對我們來說已經太遲了，活人。帶著你跟你的朋友離開這裡吧，在你們都還沒被...殺死前...', `MaleText_loc7`='Es demasiado tarde para nosotros, viviente. Coge a tu acompañante y marcharos de aquí antes de que seáis... reclamados...', `FemaleText_loc1`='저희는 이미 끝이에요, 살아계신 분이여. 어서 친구와 함께 여기를 벗어나세요... 둘 다 목숨을 잃기 전에...', `FemaleText_loc4`='太晚了。趁你们还活着……赶紧带着你的朋友离开这里吧。', `FemaleText_loc5`='對我們來說已經太遲了，活人。帶著你跟你的朋友離開這裡吧，在你們都還沒被...殺死前...', `FemaleText_loc7`='Es demasiado tarde para nosotros, viviente. Coge a tu acompañante y marcharos de aquí antes de que seáis... reclamados...' WHERE `ID`=22365;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이미 늦어서 자를도 가망이 없습니다... 너무나 강력한 힘에 붙들려 있기 때문에...', `MaleText_loc4`='对加尔来说太晚了……它的控制力太强大了……', `MaleText_loc5`='對加爾來說已經太遲了...束縛太強烈了...', `MaleText_loc7`='Es demasiado tarde para Jarl... su dominio es demasiado fuerte...', `FemaleText_loc1`='이미 늦어서 자를도 가망이 없어요... 너무나 강력한 힘에 붙들려 있기 때문이죠...', `FemaleText_loc4`='对加尔来说太晚了……它的控制力太强大了……', `FemaleText_loc5`='對加爾來說已經太遲了...束縛太強烈了...', `FemaleText_loc7`='Es demasiado tarde para Jarl... su dominio es demasiado fuerte...' WHERE `ID`=22366;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밤이고 낮이고 제가 하는 일은 여기 앉아서 탄약을 만들고 석궁 활줄을 고치는 겁니다.$B$B제게 맡길 일이 있으신 것 같습니다만?', `MaleText_loc4`='我的工作就是日夜不停地制造弹药或是给弓换弦。$B$B你需要帮助吗？', `MaleText_loc5`='我就只是坐在這，日以繼夜的製作彈藥、調整十字弓弦。$B$B我猜你也要我為你做些什麼吧?', `MaleText_loc7`='Paso el día y la noche aquí sentado haciendo munición y encordando ballestas.$B$B¿Supongo que tu también quieres que haga algo para ti?' WHERE `ID`=22367;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 파는지 좀 보여주십시오, 핀레이.', `MaleText_loc4`='芬雷，让我看看你出售的货物。', `MaleText_loc5`='芬雷，讓我瞧瞧你賣些什麼。', `MaleText_loc7`='Finlay, déjame ver qué tienes a la venta.', `FemaleText_loc1`='뭘 파는지 좀 보여주세요, 핀레이.', `FemaleText_loc4`='芬雷，让我看看你出售的货物。', `FemaleText_loc5`='芬雷，讓我瞧瞧你賣些什麼。', `FemaleText_loc7`='Finlay, déjame ver qué tienes a la venta.' WHERE `ID`=22368;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c님, 당신과 친구들이 아제로스 물정을 잘 안다는 건 분명한 사실이죠. 명성과 부에 목마른 이들도 좀 만나 봤을 겁니다.$b$b줄아만에 가고자 하는 친구들이 있으면 제게 보내 주세요. 당신이 보람을 느끼도록 해 드리지요.', `MaleText_loc4`='听着，$c，我知道你和你的朋友非常熟悉艾泽拉斯世界。你们一定遇见过好些渴求名望和财富的家伙。$b$b如果有谁对祖阿曼感兴趣的话，记得介绍给我认识哟，我会酬谢你的。', `MaleText_loc5`='聽著，$c，很明顯的你及你的朋友對於艾澤拉斯很熟悉。想必你已穿越了幾個追求名利的民族。$b$b派幾個可能有意願進入祖阿曼的人給我，我會讓你的付出有價值的。', `MaleText_loc7`='Escucha, $c, está claro que tú y tus amigos sabéis moveros por Azeroth. Seguramente te hayas encontrado con buscadores de fama y fortuna.$B$BEnvíame a cualquiera que esté dispuesto a adentrarse en Zul''Aman y haré que merezca la pena.' WHERE `ID`=22369;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 가증스러운 발을 딛기 훨씬 전부터 이 땅은 내 것이었노라.', `MaleText_loc4`='在你们这些可怜的种族踏足这里之前，这片土地就属于我了！', `MaleText_loc5`='早在你們卑鄙的族人定居這裡之前，這片土地本來是我的。', `MaleText_loc7`='Esta tierra me pertenecía mucho antes de que tu despreciable especie pusiera sus pies aquí.' WHERE `ID`=22370;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기까지 온 모든 존재는 다 내 소유이니, 너도 예외는 아니로다!', `MaleText_loc4`='所有胆敢冒险进入这里的家伙都会成为我的财产，你也一样！', `MaleText_loc5`='所有膽敢到此地的都是屬於我的，包括你也是!', `MaleText_loc7`='¡Todos los que se adentran aquí me pertenecen, incluido tú!' WHERE `ID`=22371;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기사가 도망간 거예요? 만세!', `MaleText_loc4`='他逃走了？万岁！', `MaleText_loc5`='他走了?耶耶!', `MaleText_loc7`='¿Se ha ido? ¡Hurra!', `FemaleText_loc1`='우리가 이긴 거예요? 만세!', `FemaleText_loc4`='他逃走了？万岁！', `FemaleText_loc5`='他走了?耶耶!', `FemaleText_loc7`='¿Se ha ido? ¡Hurra!' WHERE `ID`=22373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='할로윈 축제는 무섭지만 너무 좋아요!', `MaleText_loc4`='万圣节是个可怕的节日，但我喜欢！', `MaleText_loc5`='萬鬼節是個恐怖的節日，但是我喜歡!', `MaleText_loc7`='Halloween es una fiesta aterradora, ¡pero me gusta!', `FemaleText_loc1`='무섭긴 하지만 할로윈 축제는 너무 재미있어요!', `FemaleText_loc4`='万圣节是个可怕的节日，但我喜欢！', `FemaleText_loc5`='萬鬼節是個恐怖的節日，但是我喜歡!', `FemaleText_loc7`='Halloween es una fiesta aterradora, ¡pero me gusta!' WHERE `ID`=22374;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헤아릴 수 없이 오랜 세월을 이 숲은 불타고 있네. 고대의 마법으로 불타는 이곳은 원시비룡 여왕과 그녀의 배우자가 짝짓기를 하는 장소이기도 하다네.$B$B하지만 오래전에 잊힌 악마가 다시 깨어나, 자신의 목적을 이루고자 여왕의 아이들을 또다시 노예로 삼으려 한다네.$B$B이 브리쿨 무리가 일으키는 혼란 때문에 숲이 넓어지고, 자네 동족들이 위협받는 것이네.', `MaleText_loc4`='在远古魔法的作用下，这场森林大火绵延燃烧了数年都不曾熄灭。这里本是始祖龙女王及其配偶的栖息地。$B$B然而，某个早已被遗忘的邪恶种族已经觉醒，并企图再次奴役始祖龙女王的后裔，让它们为自己服务。$B$B这些维库人最近在灰烬龙巢附近频频滋事，严重威胁到你们的安危。', `MaleText_loc5`='遠在無數年之前，林木已然被焚毀。一股古老的魔力成為了樹林的燃料，並且當成元龍育母與其配偶的交配區。$B$B但是如今，一個久為人們所遺忘的邪惡勢力重新甦醒，並且再次尋求奴役這些元龍育母的後代，以完成他們的意圖。$B$B這幫維酷人造成了一波騷動，將他們的魔爪延伸到了其他的地方，並且威脅到你的族人。', `MaleText_loc7`='Durante miles de años estos bosques han ardido. Se alimentan de una antigua magia y conforman la zona de apareamiento de la madre de linaje y sus consortes protodraco.$B$BPero ahora un mal hace tiempo olvidado se ha despertado y quiere esclavizar a la prole de la madre de linaje para sus propios fines.$B$BEstos vrykuls han causado una alteración que se está extendiendo más allá de los límites del Encierro y amenaza a tu gente.' WHERE `ID`=22375;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 모욕이야! 무례하다고! 유서 깊은 드워프의 전통 행사에 우리를 참가하지 못하게 하다니!', `MaleText_loc4`='这简直是对我们的侮辱！赤裸裸的侮辱！他们拒绝我们参与矮人历史悠久的传统节日！', `MaleText_loc5`='這是一種侮辱!一種冒犯!他們拒絕讓我們參與古老的矮人傳統!', `MaleText_loc7`='¡Esto es un insulto! ¡Una afrenta! ¡Nos impiden participar en las tradiciones ancestrales de los enanos!' WHERE `ID`=22376;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='녀석들이 복수하려고 불량배를 보냈다! 모두 흩어져!', `MaleText_loc4`='他们企图利用蛮力达到复仇的目的！散开！', `MaleText_loc5`='他們派人來報仇了!散開!', `MaleText_loc7`='¡Han enviado a los musculitos para vengarse! ¡Dispersaos!' WHERE `ID`=22377;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 게시판은 진흙톱니 거점에 있는 스팀휘들 대표가 현상 수배를 하거나 직원 모집 공고를 낼 때 사용합니다.', `MaleText_loc4`='这块公告板被热砂集团派驻泥链镇的代表用来张贴悬赏和工作通知。', `MaleText_loc5`='此版面是給泥鏈營地的熱砂代表們張貼賞金和工作告示之用。', `MaleText_loc7`='Los representantes de Bonvapor de Piñón de Barro usan este tablón para colgar información sobre trabajo y recompensas.' WHERE `ID`=22378;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='드라짓에게 행운이 따라 랩터를 잡아줄 분이 불쑥 나타날 것 같진 않네요. 벌써 보상금을 두 번이나 올렸던 터라 하는 말이에요...', `FemaleText_loc4`='我觉得德拉兹特根本找不到有能力杀死那头迅猛龙的人。我的意思是说，他已经两次提升赏金了……', `FemaleText_loc5`='我不認為德拉席特可以找到任何人殺死這隻迅猛龍。我是說，他已經將賞金提高了兩次...', `FemaleText_loc7`='No creo que Drazzit vaya a tener suerte encontrando a alguien que mate a esa ave de rapiña. Vamos, ya ha elevado la recompensa dos veces...' WHERE `ID`=22379;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='계속 쏴라! 증원군을 차단하라!', `FemaleText_loc4`='继续射击！阻挡他们的援军！', `FemaleText_loc5`='持續開火!截斷他們的援軍!', `FemaleText_loc7`='¡Seguid disparando! ¡Incomunicad a sus refuerzos!' WHERE `ID`=22380;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='엄호 사격, 발사!', `FemaleText_loc4`='掩护射击！', `FemaleText_loc5`='掩護射擊，上!', `FemaleText_loc7`='¡Fuego de apoyo, ahora!' WHERE `ID`=22381;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='놈들을 주력 부대에서 떨어뜨려라!', `FemaleText_loc4`='将他们从主力部队中孤立出来！', `FemaleText_loc5`='把他們和主力部隊分開!', `FemaleText_loc7`='¡Mantenedlos separados del grupo principal!' WHERE `ID`=22382;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 친구들에게 변장 도구를 준 건가요?', `MaleText_loc4`='探险队使用的伪装都准备好了吗？', `MaleText_loc5`='你有提供成員們偽裝嗎?', `MaleText_loc7`='¿Has proporcionado disfraces al personal?', `FemaleText_loc1`='그 친구들에게 변장 도구를 줬나요?', `FemaleText_loc4`='探险队使用的伪装都准备好了吗？', `FemaleText_loc5`='你有提供成員們偽裝嗎?', `FemaleText_loc7`='¿Has proporcionado disfraces al personal?' WHERE `ID`=22383;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼요! 그 친구들은 제가 제공할 수 있었던 온갖 편리한 수단은 다 누렸습니다. 정말 뭐가 잘못된 건지 짐작할 수가 없군요.$b$b$c님, 이걸 받으세요. 약간 손을 봐서 몇 군데 바꿨지요. 이제 실패란 있을 수 없습니다!', `MaleText_loc4`='事实上！他们向我提出了所有我能做到的改进建议。我简直不能想像什么地方会有问题。$b$b好吧，$c，拿上这个。我做了一些的修改——一些很小很小的修改。现在没有任何失败的借口了！', `MaleText_loc5`='沒錯!他們已經具備了所有我能招集到的人員應有的長處。我簡直無法想像事情會出錯。$b$b這裡有些東西，$c，挑一件吧。我已經改進它了─其實只有改良幾個小地方罷了。現在我們已經沒有理由會失敗了!', `MaleText_loc7`='¡Cierto! Les dieron todas las ventajas en las que puedo pensar. Simplemente no puedo imaginar qué fue mal.$B$BAquí, $c, toma uno. He hecho un par de modificaciones, pequeños refinamientos. ¡Ahora no hay excusas para el fracaso!' WHERE `ID`=22384;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공짜로 받은 맥주는 마셔 버리고 험상궂은 선술집 녀석들에게 맥주잔을 던지십시오!', `MaleText_loc4`='如果你想要更多的啤酒，把酒杯丢给黑铁酒鬼就行啦！', `MaleText_loc5`='喝下這桶免費的酒，然後把你的酒桶拿來丟暴飲者們!', `MaleText_loc7`='¡Bebe la cerveza gratuita y pon perdidos a los Tragones con tu jarra!', `FemaleText_loc1`='공짜로 받은 맥주는 마셔 버리고 험상궂은 선술집 녀석들에게 맥주잔을 던지세요!', `FemaleText_loc4`='如果你想要更多的啤酒，把酒杯丢给黑铁酒鬼就行啦！', `FemaleText_loc5`='喝下這桶免費的酒，然後把你的酒桶拿來丟暴飲者們!', `FemaleText_loc7`='¡Bebe la cerveza gratuita y pon perdidos a los Tragones con tu jarra!' WHERE `ID`=22385;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 지금 사람들을 줄진에게 희생양으로 내주라고 하는 겁니까?', `MaleText_loc4`='你是在暗示我给祖尔金送去活人祭品吗？', `MaleText_loc5`='你要我提供人員讓你派去找祖爾金送死嗎?', `MaleText_loc7`='¿Estás sugiriendo que te proporcione gente para los sacrificios de Zul’jin?', `FemaleText_loc1`='당신 지금 사람들을 줄진에게 희생양으로 내주라는 건가요?', `FemaleText_loc4`='你是在暗示我给祖尔金送去活人祭品吗？', `FemaleText_loc5`='你要我提供人員讓你派去找祖爾金送死嗎?', `FemaleText_loc7`='¿Estás sugiriendo que te proporcione gente para los sacrificios de Zul’jin?' WHERE `ID`=22386;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당치도 않습니다!!$b$b전 그저 이 세계에 닥친 끔찍한 위협을 제거하려 노력할 뿐이죠. 그리고 당신도 알겠지만, 대가 없이 그런 대단한 일이 이루어지지는 경우는 거의 없습니다.$b$b$n 님, 이렇게 생각해 보십시오. 당신은 평범한 자들에게 영웅이 될 기회를 주는 겁니다! 정말 귀한 기회지요!$b$b당신은 그냥 그런 친구들을 제게 보내면 됩니다. 이후는 제가 알아서 하니까요...', `MaleText_loc4`='说什么呢！$b$b我只是想铲除邪恶势力啊，你应该知道，这种事情肯定要付出代价的嘛。$b$b$n，换个角度来想吧。我这是为普通人谋福利，让他们有机会成为世人瞩目的英雄！多么难得的机遇呀！$b$b你只需让他们来这儿找我，剩下的事就交给我来应付好了……', `MaleText_loc5`='死了這條心吧!$b$b我只是想讓這個世界免於恐懼的威脅，而通常這種事情都需要付出代價，我想你也很清楚這點。$b$b不如這樣想吧，$n。你將讓平凡人也有機會成為英雄!這的確是一個千載難逢的機會!$b$b你只需要以我的方式告訴他們，剩下的就交給我來處理...', `MaleText_loc7`='¡Olvídalo!$B$BSolo estoy tratando de librar al mundo de una horrible amenaza y estoy seguro de que sabes que este tipo de cosas tienen un precio.$B$BMíralo de esta forma, $n. ¡Estarás ofreciendo a tipos normales la posibilidad de convertirse en héroes! ¡Una oportunidad poco habitual!$B$BSolo tienes que enviármelos a mí y yo me encargaré del resto.' WHERE `ID`=22387;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싸구려 술이나 파는 저런 녀석들이 떠들썩하게 자기들만의 축제를 벌이는 꼴을 여기 숨어서 지켜보기만 할 텐가?', `MaleText_loc4`='难道我们就这样躲藏在深山里，任由那帮嗜酒的狂徒在拒绝邀请我们的情况下举办庆典？！', `MaleText_loc5`='我們要躲在我們的山裡，而放任那些酒販舉辦他們熱鬧的小派對卻不找我們參加嗎?!', `MaleText_loc7`='¡¿Vamos a escondernos en nuestra montaña y permitir que esos bebedores empedernidos monten su sarao sin nosotros?!' WHERE `ID`=22388;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇다! 우리는 저들에게 왜 사람들이 검은무쇠 드워프를 거역하지 않는가를 보여줘야 한다!', `MaleText_loc4`='对极了！我们得让这帮家伙明白，和黑铁矮人作对没什么好下场！', `MaleText_loc5`='沒錯!我們要讓他們知道為何你不能通過黑鐵矮人這關!', `MaleText_loc7`='¡ESO ES! ¡Les enseñaremos por qué no conviene enfadar a los enanos Hierro Negro!' WHERE `ID`=22389;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 모두가 아마니 제국을 억압하려 하지. 이제 우린 친구가 있다. 잔달라 부족이 우리와 함께한다. 우리는 더 커졌다. 우리 모두를 막을 순 없어. 전 세계가 피로 물들 것이다!!', `MaleText_loc4`='所有人都想毁灭阿曼尼帝国。但现在，我们有盟友了。我们和赞达拉一同战斗，我们更加强大了！你们无法阻止我们！整个世界都将溺毙在鲜血中！', `MaleText_loc5`='大家都想阻止阿曼尼帝國擴張。現在我們有朋友了。我們跟贊達拉結盟，變得更加強大。你們無法阻止我們全部的人。我們要血洗整個世界!!', `MaleText_loc7`='Todo el mundo intenta acabar con el imperio Amani. Ahora tenemos amigos. Los Zandalari están con nosotros. Somos parte de algo mayor. Somos imparables. ¡El mundo entero se ahogará en sangre!' WHERE `ID`=22390;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='녀석들의 맥주통을 부수자! 가을 축제를 날려 버리자!', `MaleText_loc4`='打碎他们的酒桶！倒掉这些美酒！', `MaleText_loc5`='打碎他們的桶子!讓啤酒節無酒可喝!', `MaleText_loc7`='¡Destrozad sus barriles! ¡SECAD LA Fiesta de la Cerveza!' WHERE `ID`=22391;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물러서 계시는 게 좋을 겁니다. 물고기를 손질하느라 더러운 게 튈 수도 있으니까요.', `MaleText_loc4`='你最好站远点。剖鱼是件肮脏的活。', `MaleText_loc5`='你最好後退一點。清除魚的內臟很容易弄髒衣服。', `MaleText_loc7`='Puede que quieras apartarte. Limpiar peces es un trabajo sucio.' WHERE `ID`=22392;
