UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으핫핫핫! 아제로스의 천한 거주자에게 주는 내 새로운 선물이다! 이제 그 악마 같은 줄진은 끝장났다!', `MaleText_loc4`='艾泽拉斯世界的凡人们，接受我的赐福吧！邪恶的祖尔金已经死啦！', `MaleText_loc5`='這是我送給艾澤拉斯低等居民最新的禮物，邪惡的祖爾金已經被消滅了!', `MaleText_loc7`='¡A modo de reciente regalo de mi parte para los habitantes de Azeroth, el malvado Zul’jin ha desaparecido!' WHERE `ID`=22400;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언더시티에서 마지막에 보낸 10가지 변종은... 전부 쓰레기야!', `MaleText_loc4`='这些是幽暗城送来的最后10份药剂样本……可它们毫无价值！', `MaleText_loc5`='從幽暗城拿來的最後十份菌種...全部都沒用!', `MaleText_loc7`='Las diez últimas cepas de Entrañas... ¡todas ellas inútiles!' WHERE `ID`=22403;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 조건에서는 일 못하겠어! 쓸 만한 변종이 필요해!', `MaleText_loc4`='这样叫我怎么研究！我需要一份能在这种气候下存活的药剂样本！', `MaleText_loc5`='這種狀況底下我沒辦法工作!我需要可行的菌種!', `MaleText_loc7`='¡No puedo trabajar en estas condiciones! ¡Necesitamos una cepa viable!' WHERE `ID`=22404;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들이 보내온 역병 견본으로는 쥐새끼 한 마리 못 죽일 거야!', `MaleText_loc4`='他们送来的药剂样本连只老鼠都杀不死！', `MaleText_loc5`='他們送過來的瘟疫樣本連一隻老鼠都殺不死!', `MaleText_loc7`='¡Las muestras de peste que nos han enviado no harían daño ni a una rata!' WHERE `ID`=22405;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언더시티에서는 역병 연구가 꽤 진척됐었지. 그런데 갑자기 우리가 만든 변종이 실험하는 족족 실패하지 뭔가!', `MaleText_loc4`='幽暗城的药剂样本原本已经取得了一些进展。但是不知道怎么回事，突然又不行了！', `MaleText_loc5`='我們本來在幽暗城研究我們的瘟疫，突然之間，我們的菌種都失效了!', `MaleText_loc7`='Estábamos progresando con nuestra peste en Entrañas. ¡De repente todas nuestras cepas fracasan!' WHERE `ID`=22406;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왕립 연금술 학회에서는 노스렌드에 온 자네를 환영하네, $c. 그럼 실바나스 여왕님을 모시는 우리를 어떻게 도와줄지 말해 보게.', `MaleText_loc4`='皇家药剂师协会欢迎你来到诺森德，$c。你愿意为我们伟大的希尔瓦娜斯女王陛下做些什么呢？', `MaleText_loc5`='$c，皇家藥劑師學會歡迎你來到北裂境。那麼，你要如何為希瓦娜斯效命呢?', `MaleText_loc7`='La Sociedad Real de Boticarios te da la bienvenida a Rasganorte, $c. Y bien, ¿qué vas a hacer para colaborar a la causa de Sylvanas?' WHERE `ID`=22407;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 곰의 혼이 지닌 정수를 흡수합니다!', `MaleText_loc4`='%s吸收了野熊之魂的精华！', `MaleText_loc5`='%s吸收了熊之靈的精華!', `MaleText_loc7`='¡%s absorbe la esencia del espíritu de oso!' WHERE `ID`=22410;
