UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자자자 갑시다!', `MaleText_loc4`='去，去啊！', `MaleText_loc5`='前進前進前進!', `MaleText_loc7`='¡Vamos, vamos, vamos!', `FemaleText_loc1`='자자자 가요 가!', `FemaleText_loc4`='去，去啊！', `FemaleText_loc5`='前進前進前進!', `FemaleText_loc7`='¡Vamos, vamos, vamos!' WHERE `ID`=22414;
