UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 영혼 깨웠어? 다른 돌망치 일족 어디 있지?', `MaleText_loc4`='为什么要惊扰沉睡的鬼魂？别的石槌食人魔呢？！', `MaleText_loc5`='為什麼你要喚醒那些鬼魂呢?其他的石槌巨魔呢?!', `MaleText_loc7`='¿Por qué tú despertar fantasma? ¿Dónde estar otros Quebrantarrocas?' WHERE `ID`=22418;
