UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쉬는 시간이다.', `MaleText_loc4`='休息时间。', `MaleText_loc5`='休息時間。', `MaleText_loc7`='Hora del descanso.', `FemaleText_loc1`='좀 쉬어야지.', `FemaleText_loc4`='休息时间。', `FemaleText_loc5`='休息時間。', `FemaleText_loc7`='Hora del descanso.' WHERE `ID`=22420;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 조심해.', `MaleText_loc4`='留神点。', `MaleText_loc5`='小心吶。', `MaleText_loc7`='Míralo ahí.', `FemaleText_loc1`='거기 조심해.', `FemaleText_loc4`='留神点。', `FemaleText_loc5`='小心吶。', `FemaleText_loc7`='Míralo ahí.' WHERE `ID`=22421;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 머리를 써서 일하라고. 대장님이 주말까지 일을 끝내라고 하셨다!', `MaleText_loc4`='工作的时候动点脑子。上尉要求周末前必须完成这项工事！', `MaleText_loc5`='我們大家得要多動動腦才行，隊長要我們在這週結束把這事搞定。', `MaleText_loc7`='Trabajemos más rápido. ¡El Capitán quiere esto terminado al final de la semana!', `FemaleText_loc1`='좀 영리하게 일해 봐, 친구들. 대장님이 주말까지 일을 끝내라고 하셨다!', `FemaleText_loc4`='工作的时候动点脑子。上尉要求周末前必须完成这项工事！', `FemaleText_loc5`='我們大家得要多動動腦才行，隊長要我們在這週結束把這事搞定。', `FemaleText_loc7`='Trabajemos más rápido. ¡El Capitán quiere esto terminado al final de la semana!' WHERE `ID`=22422;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='휴식 시간 끝났다, 아가씨들.', `MaleText_loc4`='休息时间结束了。', `MaleText_loc5`='小姐們，休息時間結束了。', `MaleText_loc7`='Se acabó el descanso, señoritas.', `FemaleText_loc1`='다시 일할 시간이다, 친구들.', `FemaleText_loc4`='休息时间结束了。', `FemaleText_loc5`='小姐們，休息時間結束了。', `FemaleText_loc7`='Se acabó el descanso, señoritas.' WHERE `ID`=22423;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희가 뭘 짓는 건지 알고나 있나?', `MaleText_loc4`='你知道你在干什么吗？', `MaleText_loc5`='你做事是不是不用大腦的?', `MaleText_loc7`='¿Tienes la más mínima idea de lo que estás haciendo?', `FemaleText_loc1`='지금 뭐 하자는 건가?', `FemaleText_loc4`='你知道你在干什么吗？', `FemaleText_loc5`='你做事是不是不用大腦的?', `FemaleText_loc7`='¿Tienes la más mínima idea de lo que estás haciendo?' WHERE `ID`=22424;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 빨리!', `MaleText_loc4`='动作快点！', `MaleText_loc5`='再快一點!', `MaleText_loc7`='¡Más deprisa!', `FemaleText_loc1`='좀 더 빨리!', `FemaleText_loc4`='动作快点！', `FemaleText_loc5`='再快一點!', `FemaleText_loc7`='¡Más deprisa!' WHERE `ID`=22425;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니! 조금 더 왼쪽... 그래, 이제 됐다.', `MaleText_loc4`='不！向左一点点……好，就这样。', `MaleText_loc5`='不不!往左邊一點點...對，就是那兒。', `MaleText_loc7`='¡No! Un poco más a la izquierda... ahí, eso es.', `FemaleText_loc1`='아니! 조금 아래... 그래, 거기야.', `FemaleText_loc4`='不！向左一点点……好，就这样。', `FemaleText_loc5`='不不!往左邊一點點...對，就是那兒。', `FemaleText_loc7`='¡No! Un poco más a la izquierda... ahí, eso es.' WHERE `ID`=22426;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 기둥 조심해!', `MaleText_loc4`='当心撞上横梁！', `MaleText_loc5`='小心那道光!', `MaleText_loc7`='¡Cuidado con ese haz!', `FemaleText_loc1`='거기 서까래 조심해!', `FemaleText_loc4`='当心撞上横梁！', `FemaleText_loc5`='小心那道光!', `FemaleText_loc7`='¡Cuidado con ese haz!' WHERE `ID`=22427;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 속도로는 제시간에 작업을 끝낼 수 없다.', `MaleText_loc4`='照目前的速度，我们肯定完不成任务。', `MaleText_loc5`='照這個速度來看，我們沒辦法準時完成了。', `MaleText_loc7`='Al paso que vamos, no terminaremos a tiempo.', `FemaleText_loc1`='이 속도로는 제시간에 작업을 끝낼 수 없다.', `FemaleText_loc4`='照目前的速度，我们肯定完不成任务。', `FemaleText_loc5`='照這個速度來看，我們沒辦法準時完成了。', `FemaleText_loc7`='Al paso que vamos, no terminaremos a tiempo.' WHERE `ID`=22428;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 제가 가르칠 수 있는 것이 거의 없습니다, $c|1이여;여;. 보석세공에 대해 좀 더 알고 싶다면 제 동료인 칼린다와 얘기를 나눠 보십시오.', `MaleText_loc4`='$c，我没有什么能教你的了。如果你想要了解更多关于珠宝加工的知识，就和我的同事卡琳达谈谈吧。', `MaleText_loc5`='我能教導你的事還有一點，$c。如果你想要知道更多有關設計的事，請與我的同事卡琳達談談。', `MaleText_loc7`='Ya no te puedo enseñar mucho más, $c. Habla con mi colega Kalinda si deseas aprender más acerca de este arte.' WHERE `ID`=22429;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법부여에 대해 제가 아는 건 다 배우셨군요. 그 이상은 세다나가 가르쳐 드릴 겁니다.', `MaleText_loc4`='我所掌握的附魔技能都传授给你了。去找瑟丹娜吧，她能教给你更多东西。', `MaleText_loc5`='你已經到達了我附魔技能的極限。希丹娜可以引領你更加深入其中。', `MaleText_loc7`='Has alcanzado el límite de mis encantamientos. Sedana puede continuar con tu instrucción.' WHERE `ID`=22430;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='재봉술을 예술의 경지로 끌어올리고 싶으면 제 고용주인 킬렌과 이야기하세요. 저로서는 절대 따라갈 수 없는 실력을 갖췄답니다.', `FemaleText_loc4`='如果你想要进一步提升自己的裁缝技能，就去和我的雇主基伦谈谈吧。他所掌握的裁缝知识远远超越我。', `FemaleText_loc5`='如果你想要更加提升裁縫的藝術，請與我的員工，奇蘭談談。他比我更能讓你見識的更多。', `FemaleText_loc7`='Si quieres continuar avanzando en el noble arte de la sastrería, habla con Keelen, mi patrón. Puede enseñarte más de lo que yo jamás podré.' WHERE `ID`=22431;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 독수리의 혼이 지닌 정수를 흡수합니다!', `MaleText_loc4`='%s吸收了雄鹰之魂的精华！', `MaleText_loc5`='%s吸收了雄鷹之靈的精華!', `MaleText_loc7`='¡%s absorbe la esencia del espíritu de águila!' WHERE `ID`=22432;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 스라소니의 혼이 지닌 정수를 흡수합니다!', `MaleText_loc4`='%s吸收了山猫之魂的精华！', `MaleText_loc5`='%s吸收了山貓之靈的精華!', `MaleText_loc7`='¡%s absorbe la esencia del espíritu de lince!' WHERE `ID`=22433;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 용매의 혼이 지닌 정수를 흡수합니다!', `MaleText_loc4`='%s吸收了龙鹰之魂的精华！', `MaleText_loc5`='%s吸收了龍鷹之靈的精華!', `MaleText_loc7`='¡%s absorbe la esencia del espíritu de dracohalcón!' WHERE `ID`=22435;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기 상황은 생각보다 더 끔찍해요! 비행선은 배배 꼬인 금속이랑 불타는 연료를 뭉쳐 놓은 꼴이 돼버렸다고요!', `FemaleText_loc4`='这里的情况比我想象的糟得多！飞艇并不比一堆扭曲的金属和燃烧的燃料好多少！', `FemaleText_loc5`='這裡的情況比我想像的還糟!那艘飛艇只比一堆扭曲的廢鐵加上起火的燃料還要好一點!', `FemaleText_loc7`='¡La situación allí es peor de lo que pensaba! ¡El zepelín es poco más que un amasijo de hierros retorcidos y combustible ardiendo!' WHERE `ID`=22436;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바다사자가 당신의 존재를 알아채고 경고의 의미로 큰 소리를 내기 시작합니다!', `MaleText_loc4`='你惊动了一头海狮，它立即向同伴发出了警报。', `MaleText_loc5`='因為你的出現，海獅豹起了戒心，並威嚇得咆哮!', `MaleText_loc7`='¡Tu presencia ha alertado a un león marino que ha comenzado a bramar a modo de advertencia!' WHERE `ID`=22437;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다! 구해주시지 않았더라면 저 짐승 같은 녀석들이 제게 무슨 짓을 했을지 모릅니다.', `MaleText_loc4`='谢谢你！真不知道那些野蛮人会怎么对付我。', `MaleText_loc5`='感謝你!真不知道那些禽獸本來打算怎麼對付我。', `MaleText_loc7`='¡Gracias! Mejor no pensar en lo que esos soldados me habrían hecho.', `FemaleText_loc1`='감사해요! 구해주시지 않았더라면 저 짐승 같은 녀석들이 제게 무슨 짓을 했을지 몰라요.', `FemaleText_loc4`='谢谢你！真不知道那些野蛮人会怎么对付我。', `FemaleText_loc5`='感謝你!真不知道那些禽獸本來打算怎麼對付我。', `FemaleText_loc7`='¡Gracias! Mejor no pensar en lo que esos soldados me habrían hecho.' WHERE `ID`=22438;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배고픈 %s|1이;가; 당신을 보고 입맛을 다십니다!', `MaleText_loc4`='%s发现了一顿美餐！', `MaleText_loc5`='%s感覺到一頓有可能吃得到的餐點!', `MaleText_loc7`='¡Un %s percibe una comida potencial!' WHERE `ID`=22439;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='테라모어에 오신 것을 환영합니다, $c님.', `FemaleText_loc4`='欢迎来到塞拉摩，$c。', `FemaleText_loc5`='歡迎來到塞拉摩，$c。', `FemaleText_loc7`='Te doy la bienvenida a Theramore, $c.' WHERE `ID`=22440;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 검은바위 산에서 왔다네.
너희 맥주를 마셔버릴 거야!
검은무쇠 드워프는 거짓말을 안해.
그러니 조심하는 게 좋을걸!', `MaleText_loc4`='我们来自黑石山，
我们来喝你的酒！
黑铁矮人说到做到，
你对此清楚得很！', `MaleText_loc5`='喔，我們來自黑石山，
我們是喝酒狂!
黑鐵矮人，他們從來不說謊，
這樣你知道沒被誆!', `MaleText_loc7`='Oh, somos de la Montaña Roca Negra,
¡Venimos a beber su cerveza!
Los enanos Hierro Negro no mienten,
¡Y saben que es la verdad!', `FemaleText_loc1`='우리는 검은바위 산에서 왔다네.
너희 맥주를 마셔버릴 거야!
검은무쇠 드워프는 거짓말을 안해.
그러니 조심하는 게 좋을걸!', `FemaleText_loc4`='我们来自黑石山，
我们来喝你的酒！
黑铁矮人说到做到，
你对此清楚得很！', `FemaleText_loc5`='喔，我們來自黑石山，
我們是喝酒狂!
黑鐵矮人，他們從來不說謊，
這樣你知道沒被誆!', `FemaleText_loc7`='Oh, somos de la Montaña Roca Negra,
¡Venimos a beber su cerveza!
Las enanos Hierro Negro no mienten,
¡Y saben que es la verdad!' WHERE `ID`=22441;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은무쇠 흑맥주도 안 마시고
검은무쇠 맥주도 안 판다네!
우리를 빼놓고 가을 축제를 한다고?
해 보라지! 후회하게 될걸!', `MaleText_loc4`='你未曾体会过我们的痛楚，
你未曾品尝过我们的麦酒！
美酒节上缺了我们的参与？
试试看吧，你只会落得惨败的结果！', `MaleText_loc5`='沒試過我們的苦味啤酒，
你就不會供應我們的麥芽酒!
但是啤酒節中沒有我們的份兒?
試試看，你會失望的!', `MaleText_loc7`='No probarán nuestra amarga,
no servirán nuestra cerveza,
pero, ¿celebrar la fiesta sin nuestro lote?
¡Inténtenlo y fracasarán!', `FemaleText_loc1`='검은무쇠 흑맥주도 안 마시고
검은무쇠 맥주도 안 판다네!
우리를 빼놓고 가을 축제를 한다고?
해 보라지! 후회하게 될걸!', `FemaleText_loc4`='你未曾体会过我们的痛楚，
你未曾品尝过我们的麦酒！
美酒节上缺了我们的参与？
试试看吧，你只会落得惨败的结果！', `FemaleText_loc5`='沒試過我們的苦味啤酒，
你就不會供應我們的麥芽酒!
但是啤酒節中沒有我們的份兒?
試試看，你會失望的!', `FemaleText_loc7`='No probarán nuestra amarga,
no servirán nuestra cerveza,
pero, ¿celebrar la fiesta sin nuestro lote?
¡Inténtenlo y fracasarán!' WHERE `ID`=22442;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코렌에게 잔을 넘기자!
헐레이 블랙브레스한테도 줘야지!
이 맥주는 심심해. 톡 쏘는 맛도 없고!
하지만 어쨌든 맥주라네! 아싸!', `MaleText_loc4`='举杯向科林祝酒，
还有霍尔雷·黑须！
酒味淡雅不上头，
好在它还算是杯酒！', `MaleText_loc5`='那麼就舉杯敬寇仁,
還有霍爾雷·黑息也是!
這酒很淡，沒那麼有勁，
不過喂!至少這是酒!', `MaleText_loc7`='¡Alzen una jarra por Coren,
y también por Hurley Negrálito!
¡Esta bebida es débil y no pega mucho,
pero, al menos, es cerveza!', `FemaleText_loc1`='코렌에게 잔을 넘기자!
헐레이 블랙브레스한테도 줘야지!
이 맥주는 심심해. 톡 쏘는 맛도 없고!
하지만 어쨌든 맥주라네! 아싸!', `FemaleText_loc4`='举杯向科林祝酒，
还有霍尔雷·黑须！
酒味淡雅不上头，
好在它还算是杯酒！', `FemaleText_loc5`='那麼就舉杯敬寇仁,
還有霍爾雷·黑息也是!
這酒很淡，沒那麼有勁，
不過喂!至少這是酒!', `FemaleText_loc7`='¡Alzen una jarra por Coren,
y también por Hurley Negrálito!
¡Esta bebida es débil y no pega mucho,
pero, al menos, es cerveza!' WHERE `ID`=22443;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생맥주도 흑맥주도 마셔버릴 거야!
맥주잔도 맥주통도 비워버릴 거야!
마시고 떠들고 떠들고 마시자!
다리에 감각이 없을 때까지!', `MaleText_loc4`='我们畅饮辛辣的烈酒，
喝光所有的酒桶！
饮酒、猜拳，猜拳、饮酒，
直到双腿失去知觉！', `MaleText_loc5`='我們將會喝光你的烈酒及啤酒，
喝乾所有品脫跟酒桶!
我們將會一邊喝一邊吵，一邊吵又一邊喝，
一直到我們無法站穩為止!', `MaleText_loc7`='Beberemos tu rubia y tu negra,
vaciaremos las jarras y barriles!
¡Beberemos y pelearemos y pelearemos y beberemos,
hasta que nos sintamos los pies!', `FemaleText_loc1`='생맥주도 흑맥주도 마셔버릴 거야!
맥주잔도 맥주통도 비워버릴 거야!
마시고 떠들고 떠들고 마시자!
다리에 감각이 없을 때까지!', `FemaleText_loc4`='我们畅饮辛辣的烈酒，
喝光所有的酒桶！
饮酒、猜拳，猜拳、饮酒，
直到双腿失去知觉！', `FemaleText_loc5`='我們將會喝光你的烈酒及啤酒，
喝乾所有品脫跟酒桶!
我們將會一邊喝一邊吵，一邊吵又一邊喝，
一直到我們無法站穩為止!', `FemaleText_loc7`='Beberemos tu rubia y tu negra,
vaciaremos las jarras y barriles!
¡Beberemos y pelearemos y pelearemos y beberemos,
hasta que nos sintamos los pies!' WHERE `ID`=22444;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맥주를 전부 다 마셔 버리면
어둠괴철로로 돌아가야지.
라그나로스에게 쓰디쓴 건배를...
맥주는 한 방울도 안 갖다줄 거지만!', `MaleText_loc4`='饮下所有的美酒
我们跳到暗影熔炉上
向拉格纳罗斯举杯……
……但是一滴酒都不给他尝！', `MaleText_loc5`='等到酒都消失
在影爐中我們將會，
敬拉格納羅斯一杯苦味啤酒...
... 不過一滴都不給他!', `MaleText_loc7`='Y cuando no quede cerveza
saltaremos a Forjatiniebla,
¡brindaremos con una amarga por Ragnaros...pero no le daremos ni una gota!', `FemaleText_loc1`='맥주를 전부 다 마셔 버리면
어둠괴철로로 돌아가야지.
라그나로스에게 쓰디쓴 건배를...
맥주는 한 방울도 안 갖다줄 거지만!', `FemaleText_loc4`='饮下所有的美酒
我们跳到暗影熔炉上
向拉格纳罗斯举杯……
……但是一滴酒都不给他尝！', `FemaleText_loc5`='等到酒都消失
在影爐中我們將會，
敬拉格納羅斯一杯苦味啤酒...
... 不過一滴都不給他!', `FemaleText_loc7`='Y cuando no quede cerveza
saltaremos a Forjatiniebla,
¡brindaremos con una amarga por Ragnaros...pero no le daremos ni una gota!' WHERE `ID`=22445;
