UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장교님과 대화를 나누는 동안에도 최고의 병력이 대기하고 있습니다!', `MaleText_loc4`='炮兵们正在执行轰炸任务呢，长官！', `MaleText_loc5`='即便我們在交談的時候，我仍然有最優秀的戰士在上面，長官!', `MaleText_loc7`='¡Tengo a mis mejores hombres y mujeres encargándose de eso incluso mientras hablamos, señor!' WHERE `ID`=22459;
