UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모든 대포, 준비.', `MaleText_loc4`='所有炮台，准备。', `MaleText_loc5`='全火砲預備。', `MaleText_loc7`='Todos los cañones preparados.', `FemaleText_loc1`='모든 대포, 준비.', `FemaleText_loc4`='所有炮台，准备。', `FemaleText_loc5`='全火砲預備。', `FemaleText_loc7`='Todos los cañones preparados.' WHERE `ID`=22461;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스코른이랑 지평선 너머 여기저기로 신나게 쏴대고 나니 돌아온 일이 뭔지 아십니까?$B$B포탄 회수 임무란 말입니다!$B$B전 이런 일을 하자고 입대한 게 아니란 말입니다. 무슨 말인지 아시겠습니까?', `MaleText_loc4`='这些炮弹每天都会被打到斯克恩或是地平线那边的某些地方去，但你知道为什么晚上又会回到这里吗？$B$B炮弹回收任务！$B$B但这工作跟我的合约完全不对口，你知道吗？', `MaleText_loc5`='斯考恩的砲火滿天，但是你曉得我被安排到什麼工作?$B$B回收砲彈!$B$B你知道嗎，我真不懂我當時我簽下去了什麼職務?', `MaleText_loc7`='Tanto disparar a Skorn y a otros lugares en el horizonte y ¿qué crees que me ha tocado?$B$B¡Recuperar bolas de cañón!$B$BYo no me apunté para esto, ¿sabes?' WHERE `ID`=22463;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='휴식을 취할 시간이에요. 아니면 식사를 하고 쉬실 건가요?$B$B글쎄, 누군가 그럴 자격이 있다면 바로 당신이시랍니다!', `FemaleText_loc4`='休息会吧，小甜甜，要不要来点吃的，放松放松？$B$B这里就你最需要休息啦。', `FemaleText_loc5`='休息一下吧，親愛的，也許放輕鬆吃點東西?$B$B唉，如果說有誰應當休息的話，那一定就是你!', `FemaleText_loc7`='Ha llegado la hora de descansar, cielo. ¿O prefieres algo de comer y un poco de relax?$B$BBueno, si alguien se lo merece, eres tú.' WHERE `ID`=22464;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 음식이 있습니까, 셀레스트?', `MaleText_loc4`='有什么吃的，塞蕾丝？', `MaleText_loc5`='有什麼東西好吃呀，莎莉絲蒂?', `MaleText_loc7`='¿Qué tienes para comer, Celeste?', `FemaleText_loc1`='어떤 음식이 있나요, 셀레스트?', `FemaleText_loc4`='有什么吃的，塞蕾丝？', `FemaleText_loc5`='有什麼東西好吃呀，莎莉絲蒂?', `FemaleText_loc7`='¿Qué tienes para comer, Celeste?' WHERE `ID`=22465;
