UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살살해, 이 녀석아! 허수아비까지 망가뜨릴 거 뭐 있어!', `MaleText_loc4`='放松，孩子！别把这靶子给打散架了。', `MaleText_loc5`='輕點，小子，別把假人現在就毀了!', `MaleText_loc7`='¡Con calma! ¡No destroces el muñeco ahora!' WHERE `ID`=22468;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='항복입니다! 칼을 치우세요!', `MaleText_loc4`='我投降！把刀拿开！', `MaleText_loc5`='我投降!別拔刀!', `MaleText_loc7`='¡Me rindo! ¡Guarda tu arma!' WHERE `ID`=22469;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신과 함께 가겠습니다. 제 부하들은 용서해 주십시오. 착한 젊은이들인데 잠시 길을 잘못 들었을 뿐이에요...', `MaleText_loc4`='我跟你回去。请放过我的手下吧。他们还很年轻，犯点小错误也是难免的……', `MaleText_loc5`='我會跟你一起走。只要饒了我的人。他們是很好的傢伙，只是犯了個錯...', `MaleText_loc7`='Yo iré contigo, pero ten piedad de mis hombres. Son buenos chicos que solo han cometido un error...' WHERE `ID`=22470;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 뭐지? 아니야, 아니야, 뭔가 잘못된 게 틀림없어. 내가 설명할 수 있어어어어어어어어...', `MaleText_loc4`='这是什么？不，这中间肯定有误会。我可以解……解释……', `MaleText_loc5`='這是什麼?不，不，這一定是誤會。我可以解...釋...', `MaleText_loc7`='¿Qué es esto? No, no, tiene que haber un error. Puedo explicaaaarloooo...' WHERE `ID`=22471;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 네놈이 버드인가?', `MaleText_loc4`='嗯，这就是巴德？', `MaleText_loc5`='那麼，這就是霸德嗎?', `MaleText_loc7`='¿Así que eh''te es Budd?' WHERE `ID`=22472;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈이 내 포로들이 저주를 퍼붓던 그 벌레 같은 녀석이로군? 실망이로구나. 좀 잘난 녀석이리라 기대했건만!', `MaleText_loc4`='你就是那个被俘虏们终日咒骂的家伙？我还以为你有多大能耐呢！', `MaleText_loc5`='你就是我的俘虜在咒罵的對象?我還以為是什麼了不起的人物呢!', `MaleText_loc7`='¿Tú eres el gusano al que maldicen mis cautivos? ¡Me eh''peraba más!' WHERE `ID`=22473;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈의 그 바보 같은 친구들이 내 감옥을 채우는 동안에 내가 널 죽이면 멍청한 거겠구나.', `MaleText_loc4`='只要你们能将祭品塞满这些笼子，我就不会要你们的命。', `MaleText_loc5`='只要像你們這種的笨蛋可以塞滿我的籠子當作祭品，我才不會笨到去殺死你。', `MaleText_loc7`='Mientras tus insensatos sigan llenando mis jaulas con sacrificios sería absurdo que te matara.' WHERE `ID`=22474;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 이건 알아두어라, 조그마한 녀석아. 내 장작더미가 꺼져가더라도 네놈이 어디에 숨는다 하더라도 네놈의 뼈로 불을 지피리라!', `MaleText_loc4`='你给我听着——如果篝火堆旺不起来，无论你躲在何处，我都会把你揪出来，用你当燃料！', `MaleText_loc5`='聽好了，小傢伙─不管你躲到哪裡，當我柴堆上的火勢變小的時候，我會拿你的骨頭當柴燒!', `MaleText_loc7`='Pero ten eh''to en cuenta, pequeño hombrecito, no impoh''ta dónde te escondas. ¡Cuando mis piras se eh''tén apagando las alimentaré con tus huesos!' WHERE `ID`=22475;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러고 나면 영원히 네놈의 영혼은 내 장난감이 될 게다...', `MaleText_loc4`='从此以后，你的灵魂将永远是我的玩物……', `MaleText_loc5`='然後，你的靈魂將永遠的變成我的玩物...', `MaleText_loc7`='Y entonces tu alma será mi juguete para toda la eternidad...' WHERE `ID`=22476;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='작은 버드 녀석아, 다시 보자꾸나. 조만간 널 찾아주마...', `MaleText_loc4`='巴德，我们总会碰面的。我相信这一天很快就要来了。', `MaleText_loc5`='我們還會再見的，小傢伙霸德。我打賭我們遲早會再見面的。', `MaleText_loc7`='Nos volveremos a ver, pequeño Budd. Apoh''taría a que más temprano que tarde.' WHERE `ID`=22477;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='급한 일이 아니라면 이야기할 시간이 없소, 시민이여. 테라모어의 성문을 지키는 건 중대한 임무라오.', `MaleText_loc4`='除非有紧急事务，否则我没有太多时间与你闲聊，公民。我肩负着保卫塞拉摩的重要使命。', `MaleText_loc5`='除非緊急，我沒那麼多時間聊天，老百姓。塞拉摩的門戶就是我最大的責任。', `MaleText_loc7`='Si no es urgente, no tengo demasiado tiempo para hablar. Las puertas de Theramore son mi mayor responsabilidad.' WHERE `ID`=22478;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아덴 부관은 항상 성문을 지키는 임무에 자원하지. 잘 된 일이야.$B$B난 내 자리가 마음에 드오. 부하 경비병들 감시하기에도 좋고, 상인 딸내미들도 잘 보이니까 말이오.', `MaleText_loc4`='艾登中尉总是自愿地承担起驻守城门的重任。我对此没什么意见。$b$b我喜欢呆在岗哨，既能看到手下的侍卫，还能欣赏商人的女儿。', `MaleText_loc5`='亞汀中尉總是自願接大門的崗哨。我倒是沒有意見。$B$B我的崗哨總是可以同時清楚地看到所有的守衛還有商人的女兒們。', `MaleText_loc7`='El teniente Aden siempre se ofrece para encargarse de las puertas. A mí me parece bien.$B$BTengo un puesto que me ofrece, al mismo tiempo, una buena vista de mis guardias Y de las hijas de los mercaderes.' WHERE `ID`=22479;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='교대하러 왔소? 시간이 다 된 것 같은데... 혹시 교대해 줄 마음이 들면 내게 말해 주시오. 술이나 몇 잔 마시게.', `MaleText_loc4`='你是来换班的吗？时间刚刚好呢。如果你愿意换班的话，我就能喝上两杯啦。', `MaleText_loc5`='你是來這裡跟我換班的嗎?我相信換班的時間差不多到了。嗯，假如你想要跟我換班的話，跟我說一聲。我正好想喝點東西。', `MaleText_loc7`='¿Has venido a sustituirme? Estoy seguro de que casi es hora. Bueno, si de todas formas deseas sustituirme, avísame. Me vendría bien una bebida... o tres.' WHERE `ID`=22480;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='데피아즈단 녀석들이 잠수에서 제일 중요한 게 뭔지 몰라서 다행이라오!', `MaleText_loc4`='感谢圣光，迪菲亚的那帮家伙对潜水一窍不通。', `MaleText_loc5`='感謝聖光，迪菲亞對潛水一無所知!', `MaleText_loc7`='¡Gracias a la Luz que los Defias no tienen ni idea de bucear!' WHERE `ID`=22481;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수리한 잠수 장비를 잃어버렸습니다. 하나 더 있나요?', `MaleText_loc4`='我的潜水设备弄丢了，你还有备用的吗？', `MaleText_loc5`='我沒有修理過的潛水裝備了。你有多的嗎?', `MaleText_loc7`='Ya no tengo el equipo de buceo reparado. ¿Tienes uno de sobra?', `FemaleText_loc1`='수리한 잠수 장비를 잃어버렸어요. 하나 더 있나요?', `FemaleText_loc4`='我的潜水设备弄丢了，你还有备用的吗？', `FemaleText_loc5`='我沒有修理過的潛水裝備了。你有多的嗎?', `FemaleText_loc7`='Ya no tengo el equipo de buceo reparado. ¿Tienes uno de sobra?' WHERE `ID`=22482;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발사!', `MaleText_loc4`='开火！', `MaleText_loc5`='開火!', `MaleText_loc7`='¡Fuego!' WHERE `ID`=22483;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 제공하는 빈약한 수준을 훨씬 넘어서는 설계도를 배우셔야겠군요. 여기 있는 단웨가 진정한 공학적 기쁨을 누리게 해 줄 거예요!', `FemaleText_loc4`='我能提供的工程学结构图非常有限，你得向丹文讨教讨教。他会让你见识到工程学的精妙之处！', `FemaleText_loc5`='你所需要的遠遠超過我所能提供的東西，但丹威那裡有些真正高科技的新花樣唷!', `FemaleText_loc7`='Lo que necesitas son esquemas que van más allá de mis exiguas ofertas. Danwe puede mostrarte algunas verdaderas delicias tecnológicas.' WHERE `ID`=22484;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='딱 맞춰 왔군! 어서 여기서 나가세.', `MaleText_loc4`='你就不能挑个更好的时候来吗！我们赶紧离开这里。', `MaleText_loc5`='你早不來晚不來!我們快逃出去吧。', `MaleText_loc7`='¡No podrías haber llegado en mejor momento! Huyamos de aquí.' WHERE `ID`=22485;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 떠나야지... 하지만 그 전에 얼라이언스 놈들에게 날 잊지 못할 선물을 주고 가야겠네!', `MaleText_loc4`='好了，我们走吧……但别忘记给联盟留下点终身难忘的东西！', `MaleText_loc5`='是的，我們走吧...但是走之前，我們應該留給聯盟大軍一些讓他們永遠記得我們的東西才對!', `MaleText_loc7`='Sí, partamos... ¡pero no antes de que nuestros anfitriones de la Alianza tengan algo por lo que recordarnos!' WHERE `ID`=22486;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 야영지에는 보급품이 넉넉하지 않다네. 그런데 문제까지 생긴다면 놈들로서는 정말 수치스러운 일일 거야.', `MaleText_loc4`='这座营地的补给物资有限。真要出什么差错的话，他们就完蛋了。', `MaleText_loc5`='他們在這個營地中的補給品很有限。若是他們發生了不幸那就太遺憾了。', `MaleText_loc7`='En este campamento tienen los suministros limitados. Sería una auténtica pena que les sucediera algo.' WHERE `ID`=22487;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아담스 경비대장님께서 할그린드에서 벌어지는 일을 조사하도록 나를 여기 보냈소. 하지만 이 이상은 다가갈 수 없소. 그나마 이 버려진 브리쿨 탑 덕분에 감시의 눈길을 피하는 거라오.$B$B포세이큰이 저기서 뭔가 대단히 나쁜 일을 꾸미는 게 분명하오. 느껴진다고!', `MaleText_loc4`='亚当斯上尉派我来调查哈尔格林德到底发生了什么事。我以这座被废弃的维库人哨塔为掩护，费了好大的工夫，最多只能靠到这么近了。$B$B被遗忘者一定在秘密策划着什么。我感觉得到！', `MaleText_loc5`='亞當斯隊長派我來這裡調查霍葛萊發生了什麼事情。然而，就差一點我就能搞清楚了;廢棄的維酷高塔提供了我一些躲避偵查之眼的掩蔽。$B$B被遺忘者在那兒鬼鬼祟祟的，我感覺得出來!', `MaleText_loc7`='El capitán Adams me envía a investigar qué está ocurriendo en Haltorboll. Pero esto es lo más cerca que he conseguido acercarme, la torre vrykul abandonada me otorga cierta protección ante ojos entrometidos.$B$BLos Renegados están tramando algo allí. ¡Puedo sentirlo!' WHERE `ID`=22488;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 이거야... 잘 탄다!', `MaleText_loc4`='啊，对……看着它烧个精光！', `MaleText_loc5`='啊，沒錯...燒吧!', `MaleText_loc7`='¡Ah, sí... míralo arder!' WHERE `ID`=22489;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거의 다 됐다!', `MaleText_loc4`='我们离成功很近了！', `MaleText_loc5`='我們快要完成了!', `MaleText_loc7`='¡Ya casi hemos terminado!' WHERE `ID`=22490;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 연금술사에게 함부로 대들면 어떻게 되는지 알았겠지, 이 못 배워먹은 얼라이언스 녀석들아!', `MaleText_loc4`='你们这帮联盟的渣滓，尝尝药剂师的厉害吧！', `MaleText_loc5`='這就是惹上藥劑師的下場，你們這些聯盟混蛋!', `MaleText_loc7`='¡Eso os enseñará a no meteros con un boticario, perros sin madre de la Alianza!' WHERE `ID`=22491;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 여기서 도망가세나.', `MaleText_loc4`='我们赶紧逃离这里吧！', `MaleText_loc5`='咱們快點逃出這裡。', `MaleText_loc7`='Retirémonos de aquí a toda prisa.' WHERE `ID`=22492;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쏘지 마라! 연금술사가 지나가겠다!', `MaleText_loc4`='别动手！是药剂师！', `MaleText_loc5`='停火!藥劑師回來了!', `MaleText_loc7`='¡No disparéis! ¡Boticario a la vista!' WHERE `ID`=22493;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네에게 빚을 졌네. 복수의 상륙지에 있는 라이샌더와 이야기해 보게. 그가 적절한 보상을 해줄 걸세.', `MaleText_loc4`='我们欠你的情，朋友。与复仇港的雷杉德尔谈谈吧，他会给你一份适当的酬劳。', `MaleText_loc5`='我們欠你一次，朋友。和復仇臺地的黎珊達聊聊;他會安排合適的獎賞給你。', `MaleText_loc7`='Te debemos una, colega. Habla con Lysander en Campo Venganza; él te proporcionará una recompensa adecuada.' WHERE `ID`=22494;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하하하! 비밀을 밝혀야 해!', `MaleText_loc4`='啊哈哈哈哈！我要挖掘出真相！', `MaleText_loc5`='啊哈哈哈!我一定是發現秘密了!', `MaleText_loc7`='¡Jajaaaja! ¡Debo averiguar los secretos!', `FemaleText_loc1`='하하하하! 비밀을 밝혀야 내야 해!', `FemaleText_loc4`='啊哈哈哈哈！我要挖掘出真相！', `FemaleText_loc5`='啊哈哈哈!我一定是發現秘密了!', `FemaleText_loc7`='¡Jajaaaja! ¡Debo averiguar los secretos!' WHERE `ID`=22495;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더는 알고 싶지 않아. 제발 잊어버리게 해 줘!', `MaleText_loc4`='我什么都不想知道了。让我都忘了吧！', `MaleText_loc5`='我不想再知道更多了。讓我忘掉!', `MaleText_loc7`='Ya no quiero saber. ¡Hazme olvidar!', `FemaleText_loc1`='더는 알고 싶지 않으니 모두 잊게 해 줘!', `FemaleText_loc4`='我什么都不想知道了。让我都忘了吧！', `FemaleText_loc5`='我不想再知道更多了。讓我忘掉!', `FemaleText_loc7`='Ya no quiero saber. ¡Hazme olvidar!' WHERE `ID`=22496;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연구하고 발굴하는 자는 진실을 밝혀내게 되지.', `MaleText_loc4`='人们只要专注于研究和挖掘，他们就能发现真相。', `MaleText_loc5`='當有人研究挖掘，他就會揭發真相。', `MaleText_loc7`='Cuando uno estudia y excava, acaba desvelando la verdad.', `FemaleText_loc1`='연구하고 발굴하는 자는 진실을 밝혀내게 되는 법이지.', `FemaleText_loc4`='人们只要专注于研究和挖掘，他们就能发现真相。', `FemaleText_loc5`='當有人研究挖掘，他就會揭發真相。', `FemaleText_loc7`='Cuando una estudia y excava, acaba desvelando la verdad.' WHERE `ID`=22497;
