UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간이 조금만 더 있었더라면!', `MaleText_loc4`='如果时间再充裕一点就好了！', `MaleText_loc5`='除非有更多的時間才行!', `MaleText_loc7`='¡Si tan solo tuviéramos más tiempo!', `FemaleText_loc1`='시간이 조금만 더 있었더라면 좋았을 텐데!', `FemaleText_loc4`='如果时间再充裕一点就好了！', `FemaleText_loc5`='除非有更多的時間才行!', `FemaleText_loc7`='¡Si tan solo tuviéramos más tiempo!' WHERE `ID`=22501;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용서하소서, 위대한 분이시여. 진실을 파헤칠 생각은 없었나이다!', `MaleText_loc4`='原谅我吧，伟大的主！我不是故意要挖掘真相的。', `MaleText_loc5`='喔，大人，原諒我。我不是故意要知道真相的!', `MaleText_loc7`='Perdóname, oh magnífico. ¡No era mi intención descubrir la verdad!', `FemaleText_loc1`='용서하소서, 위대한 분이시여. 진실을 파헤칠 생각은 없었습니다!', `FemaleText_loc4`='原谅我吧，伟大的主！我不是故意要挖掘真相的。', `FemaleText_loc5`='喔，大人，原諒我!我不是故意要知道真相的。', `FemaleText_loc7`='Perdóname, oh magnífico. ¡No era mi intención descubrir la verdad!' WHERE `ID`=22502;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진실이 너희를 해방할 것이다! 우리와 마찬가지로 너희들도 그 분과 영원히 함께하리라!', `MaleText_loc4`='这真相将给予你自由。很快，你就会成为我们的一员！', `MaleText_loc5`='真相才能拯救你!像我們一樣的話，你就要跟它永遠待在這了!', `MaleText_loc7`='La verdad te hará libre. ¡Al igual que nosotros, estarás con ELLO para siempre!', `FemaleText_loc1`='진실이 너희를 해방할 것이다! 우리와 마찬가지로 너희들도 그 분과 영원히 함께하리라!', `FemaleText_loc4`='这真相将给予你自由。很快，你就会成为我们的一员！', `FemaleText_loc5`='真相才能拯救你!像我們一樣的話，你就要跟它永遠待在這了!', `FemaleText_loc7`='La verdad te hará libre. ¡Al igual que nosotros, estarás con ELLO para siempre!' WHERE `ID`=22503;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진실을 알게 된 이상, 돌려보낼 수는 없다!', `MaleText_loc4`='既然你已经知道了真相，我就更不能让你离开了！', `MaleText_loc5`='既然你知道了真相，我就不能讓你走了!', `MaleText_loc7`='Ahora que conoces la verdad no puedo permitir que te marches.', `FemaleText_loc1`='진실을 알게 된 이상, 그냥 살려 보낼 순 없다!', `FemaleText_loc4`='既然你已经知道了真相，我就更不能让你离开了！', `FemaleText_loc5`='既然你知道了真相，我就不能讓你走了!', `FemaleText_loc7`='Ahora que conoces la verdad no puedo permitir que te marches.' WHERE `ID`=22504;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곧 모든 게 끝날 것이다. 곧 입에 오르내려서는 안 되는 분의 축복을 받으리라!', `MaleText_loc4`='一切即将结束。接受那位不可名状之存在的拥抱吧！', `MaleText_loc5`='一切很快就要結束了。很快你就要落入那個不能說出名字的人的懷抱了!', `MaleText_loc7`='Pronto habrá acabado todo. ¡Pronto te abrazará Aquel Que No Debe Ser Nombrado!', `FemaleText_loc1`='모든 게 곧 끝나겠구나. 곧 입에 오르내려서는 안 되는 분의 축복을 받으리라!', `FemaleText_loc4`='一切即将结束。接受那位不可名状之存在的拥抱吧！', `FemaleText_loc5`='一切很快就要結束了。', `FemaleText_loc7`='Pronto habrá acabado todo. ¡Pronto te abrazará Aquel Que No Debe Ser Nombrado!' WHERE `ID`=22505;
