UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오늘은 당신에게 보여드릴 도안이 한두 가지 있을까요?', `FemaleText_loc4`='今天我是不是可以为你展示一两张新图样？', `FemaleText_loc5`='今天要不要讓我給你看看一兩張圖樣呢?', `FemaleText_loc7`='¿Hay algún patrón que pueda enseñarte hoy?' WHERE `ID`=22513;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 제 지식의 한계를 뛰어넘었군요. 저기 있는 베마린이 당신을 더 가르쳐 줄 겁니다.', `MaleText_loc4`='你的锻造技能已经超越了我所掌握的范围，不过那边的波玛尔能教给你更多知识。', `MaleText_loc5`='你的知識已經超越了我，但那邊的貝瑪倫可以教你更多東西。', `MaleText_loc7`='Has superado mi propio conocimiento, pero Bemarrin, allí, puede enseñarte mucho más.' WHERE `ID`=22514;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제 지식으로는 당신을 더 가르칠 수가 없네요. 캠베론은 저보다 뛰어난 연금술사이니 실력을 더 쌓고 싶으면 그와 이야기해 보세요.', `FemaleText_loc4`='我所掌握的知识非常有限，卡博隆在炼金术方面的造诣比我厉害得多。如果你想要继续提升自己的技能，就和他谈谈吧。', `FemaleText_loc5`='我怕你已經達到了我知識的極限，坎伯朗在鍊金術的造詣遠勝於我。如果你對進一步研究還感興趣的話，就去和他談談吧。', `FemaleText_loc7`='Me temo que has llegado al límite de mi conocimiento. Camberon es más hábil que yo en la alquimia. Habla con él si deseas seguir avanzando.' WHERE `ID`=22515;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 정보가 정확하다고 판단하지 않았다면 제이나가 이렇게 급하게 전갈을 보냈을 리 없지.', `MaleText_loc4`='如果消息来源不可靠的话，吉安娜女士也不会急着派信使来暴风城。', `MaleText_loc5`='假如珍娜女士不信任她的消息來源的話，她也不會如此匆忙的派出信差。', `MaleText_loc7`='Lady Jaina no enviaría a un mensaje con tanta prisa si no creyera que su información es fiable.' WHERE `ID`=22516;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='데피아즈단이 국왕의 실종에 관련이 있음이 명백하니, 태도를 바꾸어 녀석들을 적극적으로 공격할 걸세.', `MaleText_loc4`='迪菲亚兄弟会寻得了新的庇护，他们在暴风城国王失踪事件中显然扮演了不光彩的角色，我们必须重新制定进攻迪菲亚兄弟会的计划。', `MaleText_loc5`='隨著他們的新贊助人還有明顯地在國王的失蹤事件上涉案，我在毫無選擇下只好重新擬定一個對付迪菲亞的進攻計畫。', `MaleText_loc7`='Con su recién encontrado patrocinio y aparente papel en la desaparición del rey, no veo más opción que planear una nueva ofensiva contra los Defias.' WHERE `ID`=22517;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제이나에게 내 감사를 전하게. 그리고 우리의 군주께서 안전하게 돌아오시는 그날까지 우리는 데피아즈단을 쫓을 거라고 이야기하게.', `MaleText_loc4`='代我向吉安娜女士致谢。请转告她，在国王安全归来之前，我们不会停止对迪菲亚兄弟会及其支持组织的攻击。', `MaleText_loc5`='幫我向珍娜女士表達我的感謝之意，並且讓她知道我們將會追捕迪菲亞和幕後的黑手，直到我們的君主安全的回來!', `MaleText_loc7`='¡Transmite mi agradecimiento a Lady Jaina y hazle saber que perseguiré a los Defias y a quienes les apoyen hasta que nuestro señor regrese sano y salvo!' WHERE `ID`=22518;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리날리스가 저보다 훨씬 뛰어납니다. 그녀와 이야기해 더 많은 지식을 쌓도록 하세요.', `MaleText_loc4`='$c，莱纳里斯更适合担当你的导师。想要学习更多关于制皮的知识，就和她谈谈吧。', `MaleText_loc5`='萊娜利斯能給你的幫助比我還多，$c。去和她談談讓她教你更多東西。', `MaleText_loc7`='Lynalis podrá ayudarte más que yo, $c. Habla con ella si quieres aprender más.' WHERE `ID`=22519;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='바보같이 굴지 마요, 볼바르!', `FemaleText_loc4`='伯瓦尔，别犯傻了！', `FemaleText_loc5`='別傻了，伯瓦爾!', `FemaleText_loc7`='¡No seas insensato, Bolvar!' WHERE `ID`=22520;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='데피아즈단은 한 무리의 폭력배에 불과합니다. 이런 근거 없는 주장에 신경 쓸 게 아니라 스톰윈드의 진짜 적과 싸우는 데 집중해야 해요!', `FemaleText_loc4`='迪菲亚兄弟会不过是群乌合之众。我们要对付的应该是真正有威胁的对手，而不是在这里捕风捉影。', `FemaleText_loc5`='迪菲亞只是一群暴徒罷了。我們應該忙著跟暴風城真正的敵人戰鬥，而不是整天跟著毫無根據的猜測而行動!', `FemaleText_loc7`='Los Defias son poco más que una banda de matones. Deberíamos estar ocupados combatiendo a los verdaderos enemigos de Ventormenta en vez de perseguir especulaciones sin fundamento.' WHERE `ID`=22521;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드로 갈 준비가 됐습니다.', `MaleText_loc4`='我已经做好前往暴风城的准备了。', `MaleText_loc5`='我已經準備好前往暴風城。', `MaleText_loc7`='Estoy listo para viajar a Ventormenta.', `FemaleText_loc1`='스톰윈드로 갈 준비가 됐어요.', `FemaleText_loc4`='我已经做好前往暴风城的准备了。', `FemaleText_loc5`='我已經準備好前往暴風城。', `FemaleText_loc7`='Estoy lista para viajar a Ventormenta.' WHERE `ID`=22522;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='만나서 반갑소, $c.', `MaleText_loc4`='很高兴见到你，$c。', `MaleText_loc5`='很高興見到你，$c。', `MaleText_loc7`='Encantado de conocerte, $c.' WHERE `ID`=22523;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='테라모어로 보내 주시겠습니까? 급히 제이나 님께 바리안 폐하의 전갈을 전해야 합니다.', `MaleText_loc4`='能替我捎个信吗？乌瑞恩国王有一封紧急信件要交给塞拉摩岛的吉安娜女士。', `MaleText_loc5`='你可以帶我到塞拉摩嗎?烏瑞恩王有一個緊急訊息要我傳遞給珍娜·普勞德摩爾女士。', `MaleText_loc7`='¿Puedes enviarme a Theramore? Tengo un mensaje urgente del rey Wrynn para Lady Jaina.', `FemaleText_loc1`='테라모어로 보내 주시겠어요? 급히 제이나 님께 바리안 폐하의 전갈을 전해야 합니다.', `FemaleText_loc4`='能替我捎个信吗？乌瑞恩国王有一封紧急信件要交给塞拉摩岛的吉安娜女士。', `FemaleText_loc5`='你可以帶我到塞拉摩嗎?烏瑞恩王有一個緊急訊息要我傳遞給珍娜·普勞德摩爾女士。', `FemaleText_loc7`='¿Puedes enviarme a Theramore? Tengo un mensaje urgente del rey Wrynn para Lady Jaina.' WHERE `ID`=22524;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오그릴라의 평화 되찾아야 한다!', `MaleText_loc4`='奥格瑞拉必将恢复和平！', `MaleText_loc5`='歐格利拉的和平將會重新恢復!', `MaleText_loc7`='¡La paz volverá a Ogri''la!' WHERE `ID`=22525;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제부터는 루크하고 얘기해보게나, $n, 지식을 더하고자 한다면 말이야.', `MaleText_loc4`='$n，想要提升你的炼金术技能，就去找鲁克谈谈吧。', `MaleText_loc5`='路克正在和你說話，$n，來提升你的技巧吧。', `MaleText_loc7`='Ahora debes hablar con Lucc para mejorar tu habilidad, $n.' WHERE `ID`=22526;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다크문 카드는 야수, 축복, 정령, 원한, 열광, 차원문, 폭풍, 대장군의 여덟 종류가 있는데, 각각 A에서 8까지 8장으로 구성되어 있어요. 여덟 가지 중 어느 하나라도 8장을 모두 모으면 카드 한 벌로 바꿀 수 있는데, 그걸 학자 타데우스 팔레오에게 가져가면 강력한 장신구로 바꿔줄 거예요.', `FemaleText_loc4`='暗月卡片共有八套：野兽、祝福、元素、报复、愚人、入口、风暴和督军，每套卡片各有八张。如果你能集齐一套八张卡片，就能用一副暗月套牌在萨杜斯·帕雷教授处兑换到强大的饰品。', `FemaleText_loc5`='暗月卡有八種種類:野獸，祝福，元素，狂怒，失心，傳送門，風暴以及督軍，每套八張卡片，由一到八。如果你收集到完整一套八張卡片，你可將它們轉為一副交給我們的薩杜斯·帕里歐教授，交換一個力量強大的飾品。', `FemaleText_loc7`='Existen ocho tipos de cartas de la Luna Negra: Bestias, Bendiciones, Elementales, Furias, Locuras, Tormentas, Portales y Señores de la Guerra. Cada palo tiene ocho cartas que van del as al ocho. Si reúnes las ocho cartas de un mismo palo, puedes convertirlas en una baraja que podrás entregar al profesor Thaddeus Paleo a cambio de un poderoso abalorio.' WHERE `ID`=22527;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저주받은 기사의 마음은 광기로 가득해요! 할로윈 기간에는 저주받은 기사가 언제라도 이 마을을 습격해 올 수 있어 불안하답니다.', `FemaleText_loc4`='无头骑士的灵魂已经变得疯狂了！在万圣节期间，他随时可能袭击这座村庄！', `FemaleText_loc5`='無頭騎士受到瘟疫而神智不清了!在萬鬼節期間，他隨時都有可能來攻擊這個村莊。', `FemaleText_loc7`='¡La mente de El Jinete decapitado está apestada de demencia! Durante Halloween, puede atacar este poblado en cualquier momento.' WHERE `ID`=22528;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저주받은 기사가 마을에 불을 질렀어요! 아이들을 보호해야 합니다!', `FemaleText_loc4`='无头骑士正在村子里到处放火！我们必须要保护孩子们！', `FemaleText_loc5`='無頭騎士在村莊裡放火!我們一定要保護孩子們!', `FemaleText_loc7`='¡El Jinete decapitado ha incendiado el pueblo! ¡Debemos proteger a los niños!' WHERE `ID`=22529;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저주받은 기사가 공격하고 있어요! 어서 호드의 동지들을 도와 마을을 지켜주세요!', `FemaleText_loc4`='无头骑士来了！快一点，帮助你们的部落同胞保卫村庄！', `FemaleText_loc5`='無頭騎士正在攻擊!快點，加入你的部落同袍一起保護村莊!', `FemaleText_loc7`='¡El Jinete decapitado ataca! ¡Rápido, ayuden a sus hermanos de la Horda a defender el pueblo!' WHERE `ID`=22530;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지금 당장은 저주받은 기사를 쫓아냈군요. 잠시 숨을 돌릴 수 있겠지만 경계를 늦추지는 말아야 합니다.', `FemaleText_loc4`='无头骑士暂时被击退了。我们可以稍微松口气，但是仍然不能掉以轻心。', `FemaleText_loc5`='無頭騎士被趕走了，起碼目前如此。我們可以先鬆一口氣了，但還是要提高警覺。', `FemaleText_loc7`='De momento, hemos ahuyentado a El Jinete decapitado. Podemos recuperar el aliento, pero no debemos bajar la guardia.' WHERE `ID`=22531;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무섭긴 하지만 전 할로윈 축제가 너무 좋아요!', `MaleText_loc4`='万圣节是个可怕的节日，但我喜欢！', `MaleText_loc5`='萬鬼節是個恐怖的節日，但是我喜歡!萬鬼節是個恐怖的節日，但是我喜歡!萬鬼節是個恐怖的節日，但是我喜歡!', `MaleText_loc7`='Halloween es una fiesta aterradora, ¡pero me gusta!', `FemaleText_loc1`='할로윈 축제는 무섭지만 너무 재미있어요!', `FemaleText_loc4`='万圣节是个可怕的节日，但我喜欢！', `FemaleText_loc5`='萬鬼節是個恐怖的節日，但是我喜歡!', `FemaleText_loc7`='Halloween es una fiesta aterradora, ¡pero me gusta!' WHERE `ID`=22532;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앗, 무슨 일이에요?', `MaleText_loc4`='发生了什么事？', `MaleText_loc5`='發生了什麼事?', `MaleText_loc7`='¿Qué está ocurriendo?', `FemaleText_loc1`='웃, 무슨 일이죠?', `FemaleText_loc4`='发生了什么事？', `FemaleText_loc5`='發生了什麼事?', `FemaleText_loc7`='¿Qué está ocurriendo?' WHERE `ID`=22533;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으앙, 나 보육원으로 돌아갈래!', `MaleText_loc4`='我想回孤儿院去！', `MaleText_loc5`='我要回去孤兒院!', `MaleText_loc7`='¡Quiero volver al orfanato!', `FemaleText_loc1`='으앙, 나 보육원으로 돌아갈래!', `FemaleText_loc4`='我想回孤儿院去！', `FemaleText_loc5`='我要回去孤兒院!', `FemaleText_loc7`='¡Quiero volver al orfanato!' WHERE `ID`=22534;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원장님! 저주받은 기사가 우릴 잡아먹는 건가요?', `MaleText_loc4`='监护员！无头骑士会吃掉我们吗？', `MaleText_loc5`='監護員!那個無頭騎士是要來吃我們的嗎?', `MaleText_loc7`='¡Matrona! ¿Nos va a comer El Jinete decapitado?', `FemaleText_loc1`='원장님! 저주받은 기사가 우릴 잡아먹을까요?', `FemaleText_loc4`='监护员！无头骑士会吃掉我们吗？', `FemaleText_loc5`='監護員!那個無頭騎士是要來吃我們的嗎?', `FemaleText_loc7`='¡Matrona! ¿Nos va a comer El Jinete decapitado?' WHERE `ID`=22535;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 아빠가 살아 계셨다면 불을 꺼 주셨을 거야!', `MaleText_loc4`='要是爸爸还活着的话，他会赶来灭火的！', `MaleText_loc5`='要是我爸還活著，他就會熄滅那些火焰!', `MaleText_loc7`='¡Si mi padre estuviera vivo, apagaría los fuegos!', `FemaleText_loc1`='우리 아빠가 살아 계셨으면 저 불을 다 꺼 주셨을걸!', `FemaleText_loc4`='监护员！那个坏人会吃掉我们吗？', `FemaleText_loc5`='要是我爸還活著，他就會熄滅那些火焰!', `FemaleText_loc7`='¡Si mi padre estuviera vivo, apagaría los fuegos!' WHERE `ID`=22536;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 불 따위 우리 엄마가 살아 계셨음 아무것도 아니었을걸!', `MaleText_loc4`='要是妈妈还活着的话，她会赶来灭火的！', `MaleText_loc5`='要是我媽還活著，她就會熄滅那些火焰!', `MaleText_loc7`='¡Si mi madre estuviera viva, apagaría los fuegos!', `FemaleText_loc1`='우리 엄마가 살아 계셨음 불을 꺼 주셨을 텐데!', `FemaleText_loc4`='要是妈妈还活着的话，她会赶来灭火的！', `FemaleText_loc5`='要是我媽還活著，她就會熄滅那些火焰!', `FemaleText_loc7`='¡Si mi madre estuviera viva, apagaría los fuegos!' WHERE `ID`=22537;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기사가 사라진 거예요? 와, 만세!', `MaleText_loc4`='他逃走了吗？万岁！', `MaleText_loc5`='他走了嗎?耶耶!', `MaleText_loc7`='¿Se ha ido? ¡Hurra!', `FemaleText_loc1`='기사가 도망간 거예요? 와, 만세!', `FemaleText_loc4`='他逃走了吗？万岁！', `FemaleText_loc5`='他走了嗎?耶耶!', `FemaleText_loc7`='¿Se ha ido? ¡Hurra!' WHERE `ID`=22538;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아웃랜드 최고의 쇼에 다시 오신 것을 환영합니다! 다시 뵙게 돼서 정말 기뻐요!$B$B어서 오세요! 다시 한번 마음껏 즐기시기 바랍니다. 다크문 축제에는 항상 새롭고 신나는 것들이 늘어만 가고 있으니 구석구석 둘러보세요! 그동안 발견한 온갖 놀라운 물건들을 구경하세요! 어린이라면 모두 좋아할 만한 것들을 아낌없이 준비해 놓았답니다!', `MaleText_loc4`='欢迎再次光临外域最精彩的盛会，朋友！很高兴再次见到你。$B$B来，尽情体验我们精心准备的节目吧。记得四下看看哟，我们会不断在暗月马戏团中引进新奇刺激的玩意儿！瞧瞧这些熟悉或是新鲜的事物！我们会尽力为孩子们带来欢乐！', `MaleText_loc5`='歡迎回到全外域最偉大的表演，我的朋友!很高興再次看到你。$B$B請往前走並享受我們所提供的一切。請務必要四處逛逛，因為我們會不斷的為暗月馬戲團增加新鮮而刺激的事物!讓我們所發現的各種新舊的奇特事物為你帶來前所未有的驚奇吧!我們會繼續不遺餘力地為各個年齡的小孩帶來雀躍不已的興奮感受!', `MaleText_loc7`='¡$gBienvenido:Bienvenida; de nuevo al mejor espectáculo de Terrallende, $gamigo:amiga;! Es un verdadero placer volver a verte.$B$BAcércate y observa todo lo que ofrecemos. ¡No dejes de echar un vistazo, ya que estamos continuamente añadiendo cosas nuevas a la Feria de la Luna Negra! ¡Maravíllate con todo lo que hemos descubierto! ¡Seguimos sin reparar en gastos para proporcionaros diversiones con las que deleitar a niños de todas las edades!' WHERE `ID`=22539;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아웃랜드 최고의 쇼에 오신 것을 환영합니다!$B$B어서 오셔서 마음껏 즐기세요. 다크문 유랑단이 이 드넓고 신비한 세계를 유랑하며 발견한 온갖 놀라운 물건들을 구경하시라니까요! 다양한 연령층의 어린이들이 모두 좋아할 만한 것들을 아낌없이 준비해 놓았답니다!', `MaleText_loc4`='朋友，你好。欢迎光临外域最精彩的盛会！$B$B来，尽情体验我们精心准备的节目吧。瞧瞧这些新奇玩意儿，它们是暗月马戏团从这个广袤而神秘的世界中收集来的！我们会尽力为孩子们带来欢乐！', `MaleText_loc5`='你好!我的朋友們，歡迎參觀全外域最偉大的表演!$B$B請往前走並享受我們所提供的一切。讓暗月馬戲團在這個巨大而神秘的世界上所發現的奇特事物為你帶來前所未有的驚奇!我們會繼續不遺餘力地為各個年齡的小孩帶來雀躍不已的興奮感受!', `MaleText_loc7`='¡Saludos, $gamigo:amiga;, y $gbienvenido:bienvenida; al mayor espectáculo de Terrallende!$B$BAcércate y observa todo lo que tenemos que ofrecer. ¡Maravíllate con todo lo que la Feria de la Luna Negra ha descubierto en este vasto y misterioso mundo! ¡No hemos reparado en gastos para proporcionar diversiones con las que deleitar a niños de todas las edades!' WHERE `ID`=22540;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아제로스 최고의 쇼... 다크문 축제에 오신 모든 분들을 환영합니다! 자, 주저하지 말고 이곳에서 여러분을 기다리는 흥미진진한 모험과 흥분을 맘껏 즐기십시오! 남녀노소 모두를 위하여 신비로운 볼거리와 상품들이 잔뜩 준비되어 있답니다. 혹시 모험을 하시던 중에 다크문 카드를 발견했다면 잊지 말고 여기 있는 학자를 찾아가 보세요!', `MaleText_loc4`='欢迎来到艾泽拉斯世界最精彩的盛会——暗月马戏团！别害羞，尽情享受冒险的刺激吧！神秘新奇的奖励唾手可得。如果你在旅途中捡到暗月卡片，记得和教授谈谈哟！', `MaleText_loc5`='歡迎所有人來到艾澤拉斯最偉大的盛會...暗月馬戲團!冒險和刺激正在等著你，別害羞!這兒出售各種新奇的貨物，老少皆宜啦。記得跟教授談談你在旅途中發現的暗月卡片的事情。', `MaleText_loc7`='Bienvenidos al espectáculo más impresionante de todo Azeroth... ¡La Feria de la Luna Negra! ¡Aventura y excitación los espera! Misterios y premios para jóvenes y viejos. Y no olviden hablar con el Profesor si se han encontrado con alguna carta de la Luna Negra en sus viajes.' WHERE `ID`=22541;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아제로스 최고의 쇼에 오신 것을 환영합니다!$B$B어서 와서 마음껏 즐기시기 바랍니다. 즐길 거리와 볼거리가 가득하답니다! 이 신비하고 광활한 세계에서 다크문 축제 유랑단이 발견한 온갖 놀라운 물건들을 구경하세요! 아이들이라면 모두 좋아할 재미있는 물건들을 아낌없이 준비해 놓았습니다!', `MaleText_loc4`='朋友，你好。欢迎光临艾泽拉斯世界最精彩的盛会！$B$B来，尽情体验我们精心准备的节目吧。随意参观吧！瞧瞧这些新奇玩意儿，它们是暗月马戏团从这个广袤而神秘的世界中收集来的！我们会尽力为孩子们带来欢乐！', `MaleText_loc5`='你好!朋友們，歡迎參觀艾澤拉斯大陸上最偉大的表演!$B$B請往前走並享受我們所提供的一切。讓暗月馬戲團在這個巨大而神秘的世界上所發現的奇特事物為你帶來前所未有的驚奇!我們會繼續不遺餘力地為各個年齡的小孩帶來雀躍不已的興奮感受!', `MaleText_loc7`='¡Hola, amigos, les doy la bienvenida al mayor espectáculo de todo Azeroth!$B$BPasen y disfruten de todo lo que podemos ofrecerles. ¡Suban en las atracciones y disfruten de las vistas! ¡Sorpréndanse con las maravillas que la Feria de la Luna Negra ha descubierto en este vasto y misterioso mundo! No hemos reparado en gastos para poder ofrecer una diversión tan increíble que deleitará a niños de todas las edades.' WHERE `ID`=22542;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아웃랜드 최고의 쇼, 다크문 축제에 오신 것을 환영합니다! 지금까지 모두 재미있는 시간 보내고 있다면 좋겠습니다! 네블기어의 다크문 별난 동물원도 들러 보시고 여기 있는 예브와 그의 친구들도 꼭 만나 보세요!', `MaleText_loc4`='大家玩得还开心吗？很好！欢迎来到外域最精彩的盛会——暗月马戏团！记得与亚布·尼比盖尔和他的朋友谈谈。', `MaleText_loc5`='大家都還玩得開心嗎?太好啦!歡迎來到暗月馬戲團，全外域最精采的表演!在進入尼比蓋爾的暗月珍奇館之前，記得要和亞布和他的朋友談談唷。', `MaleText_loc7`='¿Todo el mundo se está divirtiendo? ¡Genial! ¡Bienvenidos a la Feria de la Luna Negra, el mayor espectáculo de todo Terrallende! Aseguraos de hablar con Yebb y sus amigos cuando visitéis el Zoo de Singularidades Luna Negra de Tesorillos.' WHERE `ID`=22543;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세계 최고의 행사인 다크문 축제에 오신 모든 분들을 환영합니다! 맛난 음식과 독한 술, 이국적인 유물과 깜짝 놀랄만한 물건들, 그리고 점쟁이의 운명 상담 등 눈이 휘둥그레질만한 재미가 끝없이 준비되어 있답니다! 다크문 축제 상품권이 있다면 잊지 말고 겔바스 그림게이트에게 가서 교환하세요! 다섯 개 이상만 있으면 누구나 이 세상에서 최고로 멋진 상품을 받을 수 있으니까요. 꽝은 없으니 안심하셔도 좋습니다!', `MaleText_loc4`='欢迎大家来到世上最隆重的庆典——暗月马戏团！我们拥有各色各样美味的食品、甘甜的佳酿、奇异的器物、神秘的塔罗牌、精美的礼品，还有难以自抑的激动氛围！别忘记在吉瓦斯·格里加特处兑换暗月马戏团奖券！五张奖券就能兑换到哦，还有更多令人称奇的奖品在等着你呢。所有人都有份！', `MaleText_loc5`='歡迎大家來到暗月馬戲團，所有世界上最偉大的盛事!我們這裡什麼都有...美味的食物，濃烈的飲料，奇特的工藝品，神秘的占卜，驚人的獎品還有無盡的驚奇!別忘了把你的暗月馬戲團獎品券交給吉瓦斯·葛萊蓋特!只要五張票或是更多，你就有機會贏得全外域最不可思議的獎品。每個人都是贏家!', `MaleText_loc7`='¡Bienvenidos todos a la Feria de la Luna Negra, el mayor evento de todo el mundo! ¡Lo tenemos todo: deliciosa comida, bebidas fuertes, artefactos exóticos, la buenaventura, premios sorpresa y diversión sin fin! ¡No olviden entregar sus vales para la Feria de la Luna Negra a Gelvas Roñoso! Todo lo que hace falta son cinco o más para conseguir los mejores premios de todo Terrallende. ¡Todo el mundo sale ganando!' WHERE `ID`=22544;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='야수는 잘 돌봐 드릴 테니 걱정하지 마세요!', `FemaleText_loc4`='我会照顾好你的宠物的，不要担心！', `FemaleText_loc5`='安啦，我會好好照顧你的寵物的!', `FemaleText_loc7`='Cuidaré bien de tus mascotas, no te preocupes.' WHERE `ID`=22545;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다크문 축제는 아웃랜드 전체에서 가장 큰 행사랍니다!', `MaleText_loc4`='暗月马戏团是整个外域最隆重的庆典！', `MaleText_loc5`='暗月馬戲團將會是全外域最盛大的事情!', `MaleText_loc7`='¡La Feria de la Luna Negra es el mayor evento de todo Terrallende!', `FemaleText_loc1`='다크문 축제는 아웃랜드 전체에서 가장 큰 행사랍니다!', `FemaleText_loc4`='暗月马戏团是整个外域最隆重的庆典！', `FemaleText_loc5`='暗月馬戲團將會是全外域最盛大的事情!', `FemaleText_loc7`='¡La Feria de la Luna Negra es el mayor evento de todo Terrallende!' WHERE `ID`=22546;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 이 특제 맥주잔도 던지십시오!!', `MaleText_loc4`='谁来品尝一下，绝赞的美酒噢！！', `MaleText_loc5`='誰來試試這個超級酒!!', `MaleText_loc7`='¡TIENEN QUE PROBAR ESTA SÚPER CERVEZA!', `FemaleText_loc1`='누가 이 특제 맥주잔도 던지세요!!', `FemaleText_loc4`='谁来品尝一下，绝赞的美酒噢！！', `FemaleText_loc5`='誰來試試這個超級酒!!', `FemaleText_loc7`='¡TIENEN QUE PROBAR ESTA SÚPER CERVEZA!' WHERE `ID`=22547;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='테라모어에 온 걸 환영하오, $c. 찾는 거라도 있소?', `MaleText_loc4`='欢迎来到塞拉摩，$c。你在找什么？', `MaleText_loc5`='歡迎來到塞拉摩島，$c。你在找什麼東西嗎?', `MaleText_loc7`='$gBienvenido:Bienvenida; a Theramore, $c. ¿Buscas algo?', `FemaleText_loc1`='테라모어에 오신 걸 환영해요, $c님. 찾으시는 거라도 있나요?', `FemaleText_loc4`='欢迎来到塞拉摩，$c。你在找什么？', `FemaleText_loc5`='歡迎來到塞拉摩島，$c。你在找什麼東西嗎?', `FemaleText_loc7`='$gBienvenido:Bienvenida; a Theramore, $c. ¿Buscas algo?' WHERE `ID`=22548;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 영리한 분이신 것 같은데... 여기, 이 유인물 한 번 읽어보시겠습니까?', `MaleText_loc4`='你看起来是个非常明智的人。为什么不来读一读这份传单并谈谈你的想法呢？', `MaleText_loc5`='你看起來像是一個聰明的人。你何不看看這些傳單然後加入你的想法呢?', `MaleText_loc7`='Pareces una persona inteligente. ¿Por qué no te lees uno de estos panfletos y reflexionas sobre él?', `FemaleText_loc1`='아주 영리한 분이신 것 같은데... 여기, 이 유인물 한 번 읽어보시죠?', `FemaleText_loc4`='你看起来是个非常明智的人。为什么不来读一读这份传单并谈谈你的想法呢？', `FemaleText_loc5`='你看起來像是一個聰明的人。你何不看看這些傳單然後加入你的想法呢?', `FemaleText_loc7`='Pareces una persona inteligente. ¿Por qué no te lees uno de estos panfletos y reflexionas sobre él?' WHERE `ID`=22549;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 아닙니다! $n|1이;가; 그랬습니다. 맹세합니다!', `MaleText_loc4`='不是我！我发誓，其实是$n干的！', `MaleText_loc5`='不是我!是$n做的，我發誓!', `MaleText_loc7`='¡No fui yo! ¡Lo hizo $n, lo juro!' WHERE `ID`=22550;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우와악, 뜨거워! 이 모든 게 다 $n의 생각이었다고요! 내 젤 친한 친구 몇 녀석도 숲트롤입니다요...', `MaleText_loc4`='啊啊啊！这都是$n的主意！森林巨魔是我最好的朋友……', `MaleText_loc5`='唉唷!這整件事是$n的主意!我的好朋友裡面有一些是森林食人妖...', `MaleText_loc7`='¡AAYYYYYY! ¡Todo fue idea de $n! Algunos de mis mejores amigos son trols de bosque...' WHERE `ID`=22551;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발가드에 병력을 그렇게 많이 남겨 두는 게 아니었어. 켈러 부제독은 밉살스러운 이기주의자야!$B$B이 적은 병력으로 어떻게 명령을 수행하겠나? 여기는 물론 빌더바르 요새가 준비되면 거기도 지킬 수 있을 만큼 많은 인원이 필요하단 말일세!$B$B그나마 자네가 와 줘서 문제를 해결할 희망이 보이는군.', `MaleText_loc4`='真不该把主力部队留在瓦加德。都是凯勒中将那个自大狂的错！$B$B现在手头就这么点人，我们怎么执行任务？这里的要塞需要驻军，维德瓦堡垒也需要部队！$B$B不过你既然来了，或许我们需要担心的就能少一些啦。', `MaleText_loc5`='我們不該讓那麼多人留在瓦爾加德的。海軍中將凱勒，那個讓人受不了的自我主義者!$B$B我要怎麼用這麼少人來完成命令?我需要足夠的人手待在要塞裡面，準備就緒之後，同時安排適切兵力駐防威德瓦堡壘!$B$B既然你來了，至少我們的問題可望解決了。', `MaleText_loc7`='No deberíamos haber dejado a tantos atrás, en Valgarde. ¡El almirante Keller, ese insufrible ególatra!$B$B¿Cómo voy a cumplir mis órdenes con tan pocos? ¡Necesito hombres suficientes para que se queden aquí en la fortaleza y aun así poder asignar las tropas necesarias al Fuerte Vildervar cuando esté listo!$B$BAl menos nos queda algo de esperanza de poder resolver nuestros problemas ahora que estás aquí.' WHERE `ID`=22552;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대장님께서 저랑 의논하고 싶어하시는 문제에 대해 조언을 해 드렸습니다만, 오히려 당신 말을 더 귀 기울여 들으실 것 같군요.', `MaleText_loc4`='我按照上尉的意思，提供了针对部分决策的参考意见，但是我觉得他更想听听你的看法。', `MaleText_loc5`='我建議隊長事情要和我分擔，但是我感覺他可能情願聽你的。', `MaleText_loc7`='Aconsejo al Capitán en los asuntos que decide compartir conmigo, pero tengo la sensación de que preferiría escucharte a ti.' WHERE `ID`=22553;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 많은 입을 누가 다 먹여 살리는지 아세요? 바로 저라고요!$B$B요리하며, 청소하며, 뭐든 다 제 몫이라니까요!', `FemaleText_loc4`='这么多张嘴要喂，谁来喂？我！$B$B做饭、洗碗，还有买菜什么的全都是我在做！', `FemaleText_loc5`='這些嘴巴都在等著吃，誰得完成這件事?就是我!$B$B所有煮飯，打掃，還有其它的事!', `FemaleText_loc7`='Todas estas bocas que alimentar y ¿quién tiene que hacerlo? ¡Yo!$B$B¡Cocinar, limpiar y todo lo demás!' WHERE `ID`=22554;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 탈영병 속옷 반값에 할인합니다? 이 쓰레기는 도대체 뭐요?', `MaleText_loc4`='……逃亡者内衣对折出售？这是什么玩意儿？', `MaleText_loc5`='...獲得叛逃者貼身衣物五折的折扣?這是什麼廢話?', `MaleText_loc7`='¿... recibe el 50 por ciento de descuento en ropa interior de desertores? ¿Qué es esta basura?', `FemaleText_loc1`='... 탈영병 속옷을 반값에 할인합니다? 대체 이 쓰레기는 뭐지요?', `FemaleText_loc4`='……逃亡者内衣对折出售？这是什么玩意儿？', `FemaleText_loc5`='...獲得叛逃者貼身衣物五折的折扣?這是什麼廢話?', `FemaleText_loc7`='¿... recibe el 50 por ciento de descuento en ropa interior de desertores? ¿Qué es esta basura?' WHERE `ID`=22555;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 탈영병이 된 여러분은 밧줄에 묶여 수영하기나 개 목욕시키기 등의 여러 여가 활동을 즐기실 수 있습니다? 이거 웃기는군!', `MaleText_loc4`='……逃亡者能尽情享受游泳与喂狗的乐趣？可笑！', `MaleText_loc5`='...身為一名叛逃者，你可以享受拴繩綑綁的游泳或者打扮成狗的休閒活動?真荒謬!', `MaleText_loc7`='¿... como desertor, disfrutarás de actividades como nadar atado y cuidar perros? ¡Qué ridículo!', `FemaleText_loc1`='... 탈영병이 된 여러분은 밧줄에 묶여 수영하기나 개 목욕시키기 등의 여러 여가 활동을 즐기실 수 있습니다? 이거 웃기는군요!', `FemaleText_loc4`='……逃亡者能尽情享受游泳与喂狗的乐趣？可笑！', `FemaleText_loc5`='...身為一名叛逃者，你可以享受拴繩綑綁的游泳或者打扮成狗的休閒活動?真荒謬!', `FemaleText_loc7`='¿... como desertor, disfrutarás de actividades como nadar atado y cuidar perros? ¡Qué ridículo!' WHERE `ID`=22556;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 평생 이렇게 장엄하고 새로움으로 가득 찬 곳은 처음 보는군.$B$B악마에게 오염되지 않고 고급 지식이 숨겨진 채였다면 좋았을 텐데 말이야.', `MaleText_loc4`='这些年来，我从来没想过还能看见这样的新疆界。$B$B只是，这里已经被邪恶玷污，亘古流传的知识也被掩埋了。', `MaleText_loc5`='在我的一生之中從沒有想過能夠目睹這樣壯麗的新疆域。$B$B要是它沒有受到邪惡與理應成為禁忌的知識所污染就好了。', `MaleText_loc7`='Jamás en mi vida creí que vería una frontera tan espectacular.$B$BOjalá no estuviera contaminada por el mal y por un saber que está mejor oculto.' WHERE `ID`=22557;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여태껏 살면서 별별 광경을 다 봤지만 속삭임 협곡의 탐험가 연맹에 일어난 변화는 그중에서도 으뜸이지요.$B$B목숨을 부지하고 빠져나온 것만도 천만다행으로 여긴답니다!', `MaleText_loc4`='我也算得上是经历丰富吧，可这次探险者协会在低语峡谷的遭遇还是超出了我的想象。$B$B能从那里逃生，我真是万幸！', `MaleText_loc5`='我這輩子見識過很多事物，但以發生在低語峽谷中探險者協會的改變最為了不起。$B$B我實在很開心我毫髮無傷的離開那裡了。', `MaleText_loc7`='He visto muchas cosas en mi vida, pero el cambio sufrido por la Liga de Expedicionarios en Garganta Susurro las supera a todas.$B$B¡Me alegro de haber podido escapar de allí con la piel intacta!' WHERE `ID`=22558;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 탈영병들은 모든 시민이 온종일 곡예를 할 수 있는 테라모어를 원합니다? 이게 대체 무슨 소리요?', `MaleText_loc4`='……逃亡者要建立一个新的塞拉摩岛，所有的城民都能为所欲为？这是什么狗屁？', `MaleText_loc5`='...叛逃者所追求的塞拉摩是一個市民們可以整天自在地玩耍的地方?這是哪一派的胡言亂語?', `MaleText_loc7`='¿... los desertores buscan un Theramore donde los ciudadanos puedan pasar el día haciendo malabarismos? ¿Qué es esta tontería?', `FemaleText_loc1`='... 탈영병들은 모든 시민이 온종일 곡예를 할 수 있는 테라모어를 원합니다? 이게 대체 무슨 소리예요?', `FemaleText_loc4`='……逃亡者要建立一个新的塞拉摩岛，所有的城民都能为所欲为？这是什么狗屁？', `FemaleText_loc5`='...叛逃者所追求的塞拉摩是一個市民們可以整天自在地玩耍的地方?這是哪一派的胡言亂語?', `FemaleText_loc7`='¿... los desertores buscan un Theramore donde los ciudadanos puedan pasar el día haciendo malabarismos? ¿Qué es esta tontería?' WHERE `ID`=22559;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 가진 기술의 한계까지 도달했군요. 파리 님께서 제 스승이셨으니 당신께도 가르침을 주시리라 확신합니다.', `MaleText_loc4`='我没有什么能教给你的了。去找我的导师法里谈谈吧，她会传授给你更多关于珠宝加工的新知识的。', `MaleText_loc5`='你已經到達了我的技藝極限。法芮是我的導師，我相信她可以繼續指導你。', `MaleText_loc7`='Has alcanzado el límite de mi habilidad. Farii me instruyo a mí y estoy seguro de que también te instruirá a ti.' WHERE `ID`=22560;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 닭을 테라모어의 상징으로 지정하자고?! 이 사람들 제정신이 아니군!', `MaleText_loc4`='……把小鸡绘在塞拉摩岛的旗帜上？！这些家伙是不是疯了！', `MaleText_loc5`='...把雞制定為塞拉摩的官方標誌?!這些傢伙瘋了!', `MaleText_loc7`='¿... establecer la gallina como el emblema oficial de Theramore? ¡Estos tíos están locos!', `FemaleText_loc1`='... 닭을 테라모어의 상징으로 지정하자고요?! 이 사람들 정신 나갔네!', `FemaleText_loc4`='……把小鸡绘在塞拉摩岛的旗帜上？！这些家伙是不是疯了！', `FemaleText_loc5`='...把雞制定為塞拉摩的官方標誌?!這些傢伙瘋了!', `FemaleText_loc7`='¿... establecer la gallina como el emblema oficial de Theramore? ¡Estos tíos están locos!' WHERE `ID`=22561;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 헤어젤을 구매하기 위한 기금을 만들자? 필요 없소. 난 내 머리 모양에 만족하오!', `MaleText_loc4`='……建立一笔基金来购买发胶？算了吧，我喜欢我现在的发型！', `MaleText_loc5`='...為了購買髮膠而成立一筆基金?我喜歡現在的髮型，謝了!', `MaleText_loc7`='¿... crear un fondo para la compra de gomina? Me gusta mi pelo tal y como está, gracias.', `FemaleText_loc1`='... 헤어젤을 구매하기 위한 기금을 만들자고요? 뭣 때문에요? 전 제 머리가 맘에 드는걸요!', `FemaleText_loc4`='……建立一笔基金来购买发胶？算了吧，我喜欢我现在的发型！', `FemaleText_loc5`='...為了購買髮膠而成立一筆基金?我喜歡現在的髮型，謝了!', `FemaleText_loc7`='¿... crear un fondo para la compra de gomina? Me gusta mi pelo tal y como está, gracias.' WHERE `ID`=22562;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련의 다음 단계는 미알입니다, $c님. 당신은 이미 제가 가르칠 수 있는 수준을 넘어섰답니다.', `MaleText_loc4`='朋友，接下来由米阿尔做你的导师吧。我已经没有什么可教给你的了。', `MaleText_loc5`='米歐是你訓練的下一站，$c朋友。你已經成長到我能夠指導的程度外了。', `MaleText_loc7`='Miall es el próximo paso en tu instrucción $gamigo:amiga; $c. Has superado lo que yo puedo enseñarte.' WHERE `ID`=22563;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 밑에서 공부하는 시간도 이제 끝이 보이는군요. 이 이상은 아캄이 기꺼이 가르쳐 드릴 겁니다.', `MaleText_loc4`='朋友，你在我这里的受训课程就快结束了。阿克汉姆会继续向你传授新知识的。', `MaleText_loc5`='你在我這的訓練接近尾聲了，朋友。艾克漢會很高興繼續指導你更深入的事物。', `MaleText_loc7`='Tú instrucción conmigo se acerca a su fin, amigo. Akham seguirá instruyéndote con gusto.' WHERE `ID`=22564;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 다른 스승을 만나 당신의 지식을 더 넓힐 때가 온 것 같군요. 기계공학 분야에서 재미있고 놀라운 기술은 옥킬이 많이 개발해왔죠. 그러니 새로운 지식을 찾아 나아가는 당신의 여정도 잘 이끌어 줄 거예요, 아시겠죠?', `FemaleText_loc4`='现在是你向别的导师讨教新知识的时候了。奥克基尔在工程学方面的造诣非同寻常，他会继续指引你的。', `FemaleText_loc5`='該是你向其它導師學習的時候了;奧克伊歐已經解開了許多令人目眩神迷的工程奧秘，將可引領你在發現道路上前進，對吧?', `FemaleText_loc7`='Es hora de que aumentes tu conocimiento con otro instructor. Ockil ha desvelado muchas maravillas fascinantes de la ingeniería y te guiará en tu camino hacia los descubrimientos.' WHERE `ID`=22565;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='입에 발린 말로 날 추켜 세우는군요. 하지만 그런 식의 관심은 내가 아니라 내 동료인 레픽이 받아야 할 겁니다.', `FemaleText_loc4`='过奖了，你应该找我的同事雷菲克谈谈的。', `FemaleText_loc5`='你過獎了，不過現在你該專心學習的對象是我的同事瑞費克，不是我。', `FemaleText_loc7`='Me halagas, pero es mi colega Refik el que merece tu atención ahora, no yo.' WHERE `ID`=22566;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저도 아직 풀지 못한 수수께끼를 파헤치려고 하는군요, $C|1이여;여;. 부탁이니, 이런 문제는 저 대신 나호그와 상의해주세요.', `FemaleText_loc4`='$c，我所掌握的附魔技能已经不能满足你求知的欲望了。请和纳霍加谈谈吧。', `FemaleText_loc5`='你渴望學習的是我也尚未理解的知識，$c。請你找奈歐格替你解惑吧。', `FemaleText_loc7`='Buscas desvelar misterios que yo no he desvelado aún, $c. Habla de estos asuntos con Nahogg.' WHERE `ID`=22567;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='걷기도 전에 뛰려고 하시는군요. 훈련을 받으시려면 페룰과 얘기해보십시오, 그리고 대리 출석은 꿈도 꾸지 마십시오.', `MaleText_loc4`='学习讲究循序渐进，不能操之过急。和费卢尔谈谈吧，好好向他讨教。', `MaleText_loc5`='你必須先學會走路才能開始跑步。去跟費魯歐談談關於訓練的事宜，並且用心的跟他學習。', `MaleText_loc7`='Debes andar antes de correr. Habla con Feruul para que te entrene y presta atención a sus clases.' WHERE `ID`=22568;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 한 걸음 더 나아갈 때입니다. 다르나서스 장인의 정원에 있는 나이트 엘프 텔로니스가 다음 단계 훈련을 맡아 줄 겁니다.', `MaleText_loc4`='现在是你继续提升技能的时候了。前往达纳苏斯的工匠区找泰龙尼斯谈谈吧，接下来由他来训练你。', `MaleText_loc5`='是時候該邁出你的下一步了。達納蘇斯工匠區的夜精靈泰龍尼斯可以提供你下一個階段的訓練。', `MaleText_loc7`='Ha llegado el momento de cambiar de tercio. Telonis, un elfo de la noche que se encuentra en el Bancal del Artesano en Darnassus es el próximo paso en tu instrucción.' WHERE `ID`=22569;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연금술의 기초를 배우고자 한다면 당신이 만나봐야 할 사람은 데리즈입니다.', `MaleText_loc4`='如果你想要了解炼金术的基础知识，就和迪里兹谈谈吧。', `MaleText_loc5`='假如你想學習鍊金術的基礎知識，迪瑞茲是你的最佳人選。', `MaleText_loc7`='Si quieres aprender lo básico sobre alquimia, debes hablar con Deriz.' WHERE `ID`=22570;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='텔드랏실에 있는 커다란 나뭇가지를 보고 싶지 않으십니까? 그러시다면 좋을 텐데요. 왜냐하면 당신을 더 가르칠 수 있는 엘프가 거기 있으니까요. 다르나서스 장인의 정원에서 에이네실을 찾아보십시오.', `MaleText_loc4`='$n，你想目睹泰达希尔巨大的树枝吗？你真该去那儿，有位暗夜精灵能教给你更多关于炼金术的知识。去达纳苏斯的工匠区找安尼希尔谈谈吧。', `MaleText_loc5`='你是否曾經想過參觀泰達希爾的枝幹呢，$n?你應該去看看，因為那邊有一名精靈可以教你更多的知識。前往達納蘇斯的工匠區尋找安尼希爾吧。', `MaleText_loc7`='¿Alguna vez has deseado ver las ramas de Teldrassil, $n? Deberías, pues allí hay un elfo que puede enseñarte más. Busca a Ainethil en Darnassus, en el Bancal del Artesano.' WHERE `ID`=22571;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아직은 안 되겠네요. 에드렘하고 얘기해보세요. 그 친구가 무엇을 알아야 하는지 가르쳐 줄 거예요.', `FemaleText_loc4`='现在还不是时候呢，你先和埃德雷姆谈谈吧。他会教给你关于锻造的基础知识的。', `FemaleText_loc5`='拜託，現在不要打擾我。去跟艾德瑞姆談談。他可以傳授你想知道的事情。', `FemaleText_loc7`='Por favor, ahora no. Habla con Edrem. Él puede mostrarte lo que necesitas saber.' WHERE `ID`=22572;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='"다음 단계는 무엇일까?"라는 질문을 스스로 던져봤겠지요. 저에게 그 해답이 있답니다. 대장기술에 대해서 더 심도 있게 배우고자 한다면 바다를 건너 아이언포지라고 알려진 장엄한 곳으로 여행을 떠나야 해요. 아이언포지는 동부 왕국에서 가장 큰 대장간이라 할 수 있죠! 대용광로에 있는 벤구스 딥포지가 더 자세히 가르쳐 줄 거예요.', `FemaleText_loc4`='你很可能会问，“接下来该找谁呢？”我知道答案。要学习更多关于锻造的知识，你就得跨越无尽之海，前往庄严的铁炉堡。铁炉堡中的那尊熔炉是世上最大的！大熔炉处的本古斯·深炉就是你要找的训练师。', `FemaleText_loc5`='你可以問問你自己，「下一步是什麼?」我有答案。想要學習更多有關我們的技術，你一定得越過海洋到一個令人讚嘆的地方，名為鐵爐堡。那裡的熔爐是本大陸最大的一個!位於大鍛爐的本古斯·深爐可以教導你更多的事物。', `FemaleText_loc7`='"Puedes preguntarte "" ¿Y ahora qué?". Yo tengo la respuesta. Para aprender más sobre nuestro arte, debes atravesar el mar hasta un lugar sobrecogedor llamado Forjaz. ¡Su forja es una de las mayores del mundo! Bengus Forjahonda, en La Gran Fundición puede continuar con tu instrucción."' WHERE `ID`=22573;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타우렌 족장들이 정시마다 이 무대에서 공연을 펼칩니다. 그들의 활기찬 공연을 즐겨보십시오. 공연의 강렬함에 흠뻑 빠져들어 보고자 하신다면 우리의 멋진 공연단에 응원의 박수를 보내 주시기 바랍니다!', `MaleText_loc4`='牛头人酋长每小时都会登台表演一次。提起精神来吧，让吟游诗人激发他们的灵感，将这盛会吟唱成令人难忘的诗篇！', `MaleText_loc5`='牛頭大佬將會在每個小時開始時於舞台上演出。表現出一點活力:為這些音樂家歡呼!讓他們感受到這些活動的熱度!', `MaleText_loc7`='Los Tauren Chieftains tocan en este escenario cada hora. Muestra un poco de energía: ¡anima a los juglares para capturar un poco de la intensidad del espectáculo!' WHERE `ID`=22574;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 바쁘다네, $c|1이여;여;. 쿠드리하고 의논하는 게 나을 걸세.', `MaleText_loc4`='$c，我正忙着呢。你最好和库德里恩谈谈训练的事儿。', `MaleText_loc5`='我可是很忙的，$c。你的時間最好花在跟庫德瑞學習上。', `MaleText_loc7`='Estoy ocupado, $c. Aprovecharías mejor tu tiempo si trataras con Kudrii.' WHERE `ID`=22575;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타우렌 족장들의 공연이 30분 후에 그 막을 올립니다! 샤트라스의 바로 남쪽, 테로카르에서 펼쳐지는 다크문 축제의 시작을 즐기러 오십시오!', `MaleText_loc4`='牛头人酋长音乐会将在30分钟后开演！快来泰罗卡森林欢庆暗月马戏团开张吧，就在沙塔斯城以南！', `MaleText_loc5`='牛頭大佬演唱會將在三十分鐘後開始!快來慶祝暗月馬戲團在泰洛卡全新開幕，就在撒塔斯城南邊!', `MaleText_loc7`='¡El concierto de los Tauren Chieftains comenzará en 30 minutos! Ven a celebrar el inicio de la Feria de la Luna Negra en Terokkar, justo al sur de la Ciudad de Shattrath.' WHERE `ID`=22576;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타우렌 족장들의 공연이 15분 후에 그 막을 올립니다! 샤트라스의 바로 남쪽, 테로카르에서 펼쳐지는 다크문 축제의 시작을 즐기러 오십시오!', `MaleText_loc4`='牛头人酋长音乐会将在15分钟后开演！快来泰罗卡森林欢庆暗月马戏团开张吧，就在沙塔斯城以南！', `MaleText_loc5`='牛頭大佬演唱會將在十五分鐘後開始!快來慶祝暗月馬戲團在泰洛卡全新開幕，就在撒塔斯城南邊!', `MaleText_loc7`='¡El concierto de los Tauren Chieftains comenzará en 15 minutos! Ven a celebrar el inicio de la Feria de la Luna Negra en Terokkar, justo al sur de la Ciudad de Shattrath.' WHERE `ID`=22577;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타우렌 족장들의 공연이 5분 후에 그 막을 올립니다! 샤트라스의 바로 남쪽, 테로카르에서 펼쳐지는 다크문 축제의 시작을 즐기러 오십시오!', `MaleText_loc4`='牛头人酋长音乐会将在5分钟后开演！快来泰罗卡森林欢庆暗月马戏团开张吧，就在沙塔斯城以南！', `MaleText_loc5`='牛頭大佬演唱會將在五分鐘後開始!快來慶祝暗月馬戲團在泰洛卡全新開幕，就在撒塔斯城南邊!', `MaleText_loc7`='¡El concierto de los Tauren Chieftains comenzará en 5 minutos! Ven a celebrar el inicio de la Feria de la Luna Negra en Terokkar, justo al sur de la Ciudad de Shattrath.' WHERE `ID`=22578;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 강력한 마법부여는 내 능력 밖의 일일세, $n. 이제 엘윈 숲을 지나 아조라의 탑으로 배움의 길을 떠나게나. 그곳에 가면 자네에게 다음 단계의 가르침을 줄 스승이 있을 걸세. 이름은 키타 파이어윈드라고 한다네.', `MaleText_loc4`='$n，我所掌握的附魔技能相当有限。你应该前往艾尔文森林的阿祖拉之塔，基塔·费温德就居住在塔中，她是你的下一任导师。', `MaleText_loc5`='你想學的附魔知識已經超越我所知的範圍了，$n。接下來你應該去艾爾文森林的阿祖拉之塔找基塔·費溫德。她是你的下一位導師。', `MaleText_loc7`='Los encantamientos más poderosos escapan a mi conocimiento, $n. Tu camino debería guiarte a través del Bosque de Elwynn hasta la Torre de Azora, donde se encuentra tu próximo tutor. Su nombre es Kitta Vientofuego.' WHERE `ID`=22579;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아웃랜드의 여행자 여러분, 한판 놀아볼 준비가 되셨나요?! 자, 날이면 날마다 오는 공연이 아닙니다. 우리의 멋진 타우렌 족장들의 공연을 시작하겠습니다!', `MaleText_loc4`='外域的居民们，你们准备好了吗？牛头人酋长音乐会现在正式开演！', `MaleText_loc5`='外域的人們，準備好要搖滾了嗎?!牛頭大佬演唱會現在開始!', `MaleText_loc7`='Gentes de Terrallende, ¿estáis listos para el rock? ¡Comienza el concierto de los Tauren Chieftains!' WHERE `ID`=22580;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 능력에 맞는 간단한 설계도를 배우고자 하신다면 게르마스와 얘기해 보시는 게 좋겠군요.', `MaleText_loc4`='就你目前的水平来说，向基尔玛斯讨教些简单的设计图就成啦。', `MaleText_loc5`='如果你想的話，去與吉赫瑪斯談談有關你技能等級的簡單概論。', `MaleText_loc7`='Para obtener esquemas de tu nivel de habilidad habla con Ghermas.' WHERE `ID`=22581;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노움! 노움들은 신기한 친구들이지요. 대단하단 종족이고 말입니다! 물론 기술공학 분야에 해박한 지식을 보유하고 있기도 하지요! 아이언포지로 가서 땜장이 마을에서 스프링스핀들 피즐기어를 만나보시는 게 어떨까요?', `MaleText_loc4`='侏儒！侏儒是神奇的种族。他们别提有多棒了！侏儒在工程学上的造诣真是登峰造极啊！前往铁炉堡的侏儒区，和宾斯匹德谈谈吧。', `MaleText_loc5`='地精!地精是神奇的種族。妙極了!而且他們手中握有此種工程技術的知識!你一定要到鐵爐堡去，到地精區，與賓斯匹德談談。', `MaleText_loc7`='¡Gnomos! Los gnomos son un pueblo maravilloso. ¡Fabuloso! ¡Y tienen gran conocimiento sobre el arte de la ingeniería! Debes viajar a Forjaz, a Ciudad Manitas y hablar con Muello Saltarín.' WHERE `ID`=22582;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 길을 걸었던 선배들의 노력에 존경을 표하도록 하세요. 케이아트가 바로 당신을 가르칠 분이랍니다.', `MaleText_loc4`='啧啧。尊重你的长者。卡亚特才是你的导师。', `MaleText_loc5`='尊敬你們的長者，凱亞特將可以訓練你。', `MaleText_loc7`='Tsk. Respeta a tus mayores. Es Kayaart quien debe entrenarte.' WHERE `ID`=22583;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 가르쳐 드릴 수 있는 한계에 도달하셨지만 아직 더 배울 게 남아 있답니다. 바다 건너 스톰윈드의 마법사 지구에 가면 훌륭한 실력의 재봉사가 살고 있지요. 이름은 조르지오 볼레로라고 하는데 이제부터는 그분이 당신을 훈련하시리라 생각합니다. 가서 그분과 얘기해 보십시오.', `MaleText_loc4`='我所掌握的裁缝技能非常有限，已经没有什么可以教你的了。在无尽之海的另一边，暴风城的法师区中有一位伟大的裁缝。他名叫乔吉奥·波利罗，我想由他来做你的导师比较合适。去那儿和他谈谈吧。', `MaleText_loc5`='你已經達到了我的知識極限，但是你還有更多東西可以學。越過海洋前往暴風城的法師區，有一位裁縫大師。他的名字叫喬吉奧·波利羅，我想他可以繼續訓練你，去和他談談吧。', `MaleText_loc7`='Has alcanzado el límite de mi saber, pero aún te queda mucho por aprender. Cruzando el mar, en el Barrio de los Magos de la Ciudad de Ventormenta, habita un gran sastre. Su nombre es Georgio Bolero y creo que te entrenará. Ve a hablar con él.' WHERE `ID`=22584;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 익힌 기술은 정말 인상깊군요, $n! 더 많은 기술을 배우도록 아웃랜드로 떠날 시간이군요. 지옥불 반도로 가면 타티아나가 명예의 요새 학생으로 받아들여 줄 거예요. 아, 알도르 사제회와 일하는 것이 좋다면 샤트라스 알도르 마루에 있는 하마나르에게 배울 수도 있답니다.', `FemaleText_loc4`='$n，你的进展真是令我吃惊！现在你该前往外域学习更多关于珠宝加工的新知识了。你可以去地狱火半岛的荣耀堡找塔蒂亚娜谈谈。如果你更喜欢奥尔多的话，就去沙塔斯城的奥尔多高地找哈曼纳尔。', `FemaleText_loc5`='你的技藝成長得非常驚人，$n!為了讓你的技巧更加精進，你得要前往外域。塔蒂安娜可以收你為徒，她就在地獄火半島的榮譽堡。如果你喜歡與奧多爾合作的話，哈曼那也可以指導你，他在撒塔斯城的奧多爾高地上。', `FemaleText_loc7`='Me impresiona tu habilidad, $n. Es hora de que te dirijas a Terrallende para aprender más. Si vas a la Península del Fuego Infernal, Tatiana te admitirá como estudiante en el Bastión del Honor. O, si prefieres trabajar con los Aldor, Hamanar puede instruirte en la Ciudad de Shattrath, en el Alto Aldor.' WHERE `ID`=22585;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='훌륭한 장인이 되었군요, $c. 실력을 더 높이고 싶다면 아웃랜드로 가야 해요. 지옥불 반도의 스랄마에 있는 칼랜이 당신을 가르쳐줄 겁니다. 정 원하신다면 샤트라스 알도르 마루로 얌전 빼는 하마나르를 찾아가 보셔도 되겠죠. 별로 추천하고 싶진 않지만요.', `FemaleText_loc4`='$c，你的进展真是神速啊！现在你该前往外域学习更多关于珠宝加工的新知识了。你可以去地狱火半岛的萨尔玛找卡莱恩谈谈。如果你更喜欢奥尔多的话，就去沙塔斯城的奥尔多高地找哈曼纳尔。他是个相当假正经的家伙，我可不建议你去找他。', `FemaleText_loc5`='你的技藝成長得非常驚人，$c。為了讓你的技巧更加精進，你得要前往外域。卡連恩可以繼續訓練你，他就在地獄火半島的索爾瑪。如果你想要的話，你也可以前往撒塔斯城的奧多爾高地，和那個過分拘謹的哈曼那談談，雖然我並不推薦就是了。', `FemaleText_loc7`='Tus habilidades son inmensas, $c. Para continuar con tu instrucción debes ir a Terrallende. Kalaen te entrenará en Thrallmar, en la Península del Fuego Infernal. Si lo prefieres, puedes hablar con el remilgado Hamanar en el alto Aldor en la Ciudad de Shattrath, aunque yo no te lo recomendaría.' WHERE `ID`=22586;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='들어라, 비겁자여! 일격에 널 끝내리니! 이제 뜨거운 맛을 봐라!', `MaleText_loc4`='嗤！感受燃烧的烈焰吧！', `MaleText_loc5`='聽著!我唾棄你!現在...感受灼燒吧!', `MaleText_loc7`='¡Oye, cobarde! ¡Eres tú a quien desprecio! ¡Pues siente ahora, el fuego!' WHERE `ID`=22587;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 얘기는 이미 했다고 생각하는데, 브록. 이 건물 안에서 지낼 수는 없어. 너를 재울 수도 있지만, 그러면 다른 사람들은 아무도 못 잔다고!', `MaleText_loc4`='布洛格，我记得我们谈过这个问题。你不能待在房间里。当然啦，你是可以塞进去，不过其他人就没空间了！', `MaleText_loc5`='我以為我們已經討論過這件事了，布洛葛。你不能待在這個建築物裡。當然你可以塞的進去，但是這樣就沒有位置留給其他人了!', `MaleText_loc7`='Creía que ya habíamos hablado de esto, Brogg. No puedes quedarte en este edificio. Claro que puede cobijarte, pero no queda sitio para nadie más.' WHERE `ID`=22588;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='브록 여기서 지내도 된다고 네가 말했다! 돌망치 일족 땅 다시 찾게 도와준다고 너 브록한테 약속했다!', `MaleText_loc4`='你说过布洛格可以待在这里的！你许诺过会帮助布洛格夺回石槌氏族的土地！', `MaleText_loc5`='你說布洛葛可以待在這裡的!你答應過布洛葛要奪回石槌氏族的領地!', `MaleText_loc7`='¡Dijiste que Brogg podía quedarse! ¡Prometiste a Brogg que ayudarías a recuperar el montículo del clan Quebrantarrocas!' WHERE `ID`=22589;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 여기서 지내도 좋다고 우리가 그랬는데, 하지만 이 건물은 우리 본부라고! 우리 작전 설명서와 계획서가 여기 전부 있단 말이야!', `MaleText_loc4`='是，我们是说过你可以待在这儿，但是这间房子是我们的总部！所有的手册和蓝图都存放在里面！', `MaleText_loc5`='是的，我們說你可以待在這裡，但這個建築物是我們的總部!我們所有的手冊還有藍圖都儲存在這裡!', `MaleText_loc7`='Sí, dijimos que podías quedarte aquí, ¡pero este edificio es nuestro cuartel general! ¡Todos nuestros manuales y anteproyectos están guardados aquí!' WHERE `ID`=22590;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래도 브록에게 맞는 집 여기밖에 없다! 고블린은 집 너무 작게 만든다!!', `MaleText_loc4`='但这是唯一适合布洛格的房子，地精的房子都太小太小啦！', `MaleText_loc5`='但這是唯一塞得下布洛葛的建築物!哥布林蓋的建築物都太小了!', `MaleText_loc7`='¡Pero este es el único edificio que sirve a Brogg! ¡Los goblins hacen los edificios muy pequeños!' WHERE `ID`=22591;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오우거가 너무 큰 거라고 말하고 싶어! 너를 설득해서 당장 나가게 할 수 없다는 건 아는데, 그렇다고 영원히 이대로 머물 수 있을 거라고는 생각하지 말라고!', `MaleText_loc4`='我想说，食人魔的体型也太大了吧！好吧，我打消说服你挪动地方的念头，不过这只是暂时的！', `MaleText_loc5`='我覺得是因為巨魔的體型太大了!我想我不會現在就說服你離開，但是別以為這個情況可以永久持續下去!', `MaleText_loc7`='¡Me atrevería a decir que hicieron a los ogros demasiado grandes! ¡Veo que no voy a convencerte de que te mudes, pero no creas que esto es permanente!' WHERE `ID`=22592;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='땅이... 얼어붙었네. 시체마차가 움직일 수 없으니 여기 이대로 갇혀버린 셈이야.', `MaleText_loc4`='地面……已经完全结冰了。我们只能傻傻地坐在这里，这些绞肉车哪里都不能去。', `MaleText_loc5`='大地...一片冰封，我們簡直就是活靶;這些血屍戰車哪兒都不能去了。', `MaleText_loc7`='La tierra... está helada. Somos presas fáciles aquí. Estos carros de despojos no van a ir a ningún sitio.' WHERE `ID`=22593;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고위집행관 안셀름 님께서 상황 보고를 듣고자 하십니다.', `MaleText_loc4`='高级执行官安希尔姆要求你立刻报告情况。', `MaleText_loc5`='高階執行官安賽姆需要一份關於現況的報告。', `MaleText_loc7`='El sumo ejecutor Anselm quiere un informe de la situación.', `FemaleText_loc1`='고위집행관 안셀름 님께서 상황 보고를 듣고자 하세요.', `FemaleText_loc4`='高级执行官安希尔姆要求你立刻报告情况。', `FemaleText_loc5`='高階執行官安賽姆需要一份關於現況的報告。', `FemaleText_loc7`='El sumo ejecutor Anselm quiere un informe de la situación.' WHERE `ID`=22594;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보면 모르나? 땅이 바위처럼 얼어붙었잖나!$B$B시체마차 바퀴는 기껏해야 진흙탕이나 지나갈 정도밖엔 안 되지. 마차를 끌어내려면 누더기골렘과 사슬이 있어야 하네.', `MaleText_loc4`='这也太可怕了吧？这地面简直冻得跟岩石一样硬！$B$B你瞧，这些轮子之前还是陷在烂泥里，现在和泥土冻成一块了！恐怕得叫个憎恶用铁链将它们拖出来。', `MaleText_loc5`='那看起來像什麼?地面凍得跟石頭一樣!$B$B血屍戰車的輪子建來最好是行駛在泥巴地上的。我們需要一頭憎惡以及一些鏈條來搶救這些戰車。', `MaleText_loc7`='¿Qué parece? ¡El suelo está helado como un témpano!$B$BLas ruedas de estos carros de despojos fueron construidas para avanzar sobre barro como mucho. Vamos a necesitar una abominación y algunas cadenas para moverlos.' WHERE `ID`=22595;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 절대 담쟁이 마을을 고향이라 부르지 않겠다. 그런 짓은 우리의 정당한 땅을 되찾으리라는 희망을 포기하는 거나 마찬가지니.', `MaleText_loc4`='我绝不会把蕨墙村当作自己的家。那么做就等于放弃了收复失地的希望。', `MaleText_loc5`='我永遠不會把蕨牆村當作自己的家園。這麼做就等於放棄了奪回我們領土的希望。', `MaleText_loc7`='Nunca llamaré al Poblado Murohelecho mi hogar. Hacer eso es abandonar la esperanza de reclamar las tierras que nos pertenecen.' WHERE `ID`=22596;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, $c님. 저는 아쉴리고요, 절 좀 도와주셨으면 좋겠는데 왜냐하면 버드 아저씨가 역겨운 트롤하고 냄새 나는 오크하고 멍청한 인간하고 술 취한 드워프하고 저를 여기 보냈는데 초 못된 트롤들이 우릴 붙잡아서 질질 끌고 가서 커다란 고양이 트롤이랑 여기에 집어넣었는데 그 고양이 트롤이 진짜 진짜 성질이 더러워서 우리에 있는 사람들을 다 잡아먹었고 조금만 더 있으면 저도 잡아먹을 거 같은데 저 혼자선 나갈 수가 없으니까 그러니까...$b$b<깊이 숨을 몰아쉬는 아쉴리>$b$b저거 좀 없애 주실 수 있어요?', `FemaleText_loc4`='嗨，$c。我叫阿什莉，巴德派我和一群令人讨厌的巨魔和臭气熏天的兽人和愚蠢的人类还有一个喝醉的矮人来这儿结果我们被一群超级超级坏的巨魔抓住了然后我们就被关进了笼子更可怕的是这里还有一头非常非常残忍的巨魔豹它专吃牢笼中的囚犯所以我想它很快就会来吃我了但是凭我自己的力量是不可能逃出这里的所以……$B$B<阿什莉深深地吸了口气。>$b$b你能杀死那头猛兽吗？', `FemaleText_loc5`='你好啊，$c，我是阿西利，我被關在籠子裡了你可以幫幫我嗎因為霸德派我跟一些噁心的食人妖還有臭死人的獸人還有一些愚蠢的人類還有喝醉的矮人進來這裡然後我們中了一群超級壞的食人妖埋伏接著他們把我們拖來這裡並且把我跟一個很大又很像小貓咪的食人妖放在一起他真的很兇很兇而且把籠子裡的人都殺光光了然後我想接著不用多久他也會殺了我但是我又無法靠自己的力量逃出去，所以...$b$b<阿西利深深地吸了一口氣。>$b$b你可以去殺了那個東西嗎?', `FemaleText_loc7`='Hola $c. Soy Ashli, tienes que ayudarme porque estoy atrapada en esta jaula desde que Budd me envió aquí con unos asquerosos trols y malolientes orcos y algunos humanos tontos y un enano borracho y unos trols súper malos nos tendieron una emboscada y nos arrastraron y me metieron aquí con el gato trol grande que es muy muy malo y mata a la gente de las jaulas y creo que me va a matar también a mí muy pronto pero no puedo salir por mí misma así que...$B$B< Ashli respira hondo.>$B$B¿Puedes ayudarme a escapar de aquí?' WHERE `ID`=22597;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고블린 검보 스튜 솥', `MaleText_loc4`='地精杂烩煲', `MaleText_loc5`='哥布林燴肉罐', `MaleText_loc7`='Tetera de potaje goblin', `FemaleText_loc1`='고블린 검보 스튜 솥', `FemaleText_loc4`='地精杂烩煲', `FemaleText_loc5`='哥布林燴肉罐', `FemaleText_loc7`='Tetera de potaje goblin' WHERE `ID`=22598;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='낚시 의자', `MaleText_loc4`='钓鱼椅', `MaleText_loc5`='釣魚椅', `MaleText_loc7`='Silla para pescar', `FemaleText_loc1`='낚시 의자', `FemaleText_loc4`='钓鱼椅', `FemaleText_loc5`='釣魚椅', `FemaleText_loc7`='Silla para pescar' WHERE `ID`=22599;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='유령 호랑이', `MaleText_loc4`='幽灵虎坐骑', `MaleText_loc5`='鬼靈之虎坐騎', `MaleText_loc7`='Montura tigre espectral', `FemaleText_loc1`='유령 호랑이', `FemaleText_loc4`='幽灵虎坐骑', `FemaleText_loc5`='鬼靈之虎坐騎', `FemaleText_loc7`='Montura tigre espectral' WHERE `ID`=22600;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 해냈어 친구들! 이제 험상궂은 주정뱅이 선술집으로 가서 다친 친구들 $3096W명을 생각하며 더 마시자고!', `MaleText_loc4`='我们成功了！现在，我们要返回黑铁酒吧，和$3096W个受伤的弟兄一起喝个痛快！', `MaleText_loc5`='我們做到了，小子!現在回到黑鐵酒吧去，我們來為了受傷的$3096W位而乾杯吧!', `MaleText_loc7`='¡Lo logramos chicos! ¡Ahora volvamos a Tragapenas y bebamos por los $3096W que fueron heridos!' WHERE `ID`=22601;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='후퇴해!! 벌써 $3096W명이나 누웠으니 더 잃을 수는 없어!', `MaleText_loc4`='撤退！已经死掉$3096W个黑铁矮人了，我们承受不起更多的人员伤亡了！！', `MaleText_loc5`='撤退!!我們已經失去$3096W了，無法承受再失去別的了!!', `MaleText_loc7`='¡RETIRADA! ¡Ya hemos perdido $3096W y no podemos permitirnos perder más!' WHERE `ID`=22602;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 쌩쌩한 드워프가 $3094W명이나 있다고!', `MaleText_loc4`='这儿有$3094W个活蹦乱跳的矮人！', `MaleText_loc5`='那裡有$3094W個行進中的矮人!', `MaleText_loc7`='¡Hay $3094W enanos activos!' WHERE `ID`=22603;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빌어먹을 얼음 덩어리 땅 같으니! 전선으로 시체마차를 끌고 갈 수 없잖아!', `MaleText_loc4`='诅咒这片冻土！我们的绞肉车还怎么上前线！', `MaleText_loc5`='詛咒這塊冰天雪地!我們不可能把血屍戰車移到前線的!', `MaleText_loc7`='¡Maldita sea esta tierra helada! ¡Nunca podremos llevar estos carros de despojos al frente!' WHERE `ID`=22604;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='망할! 차라리 분해하는 게 낫겠군. 이제 쓸모가 없겠어.', `MaleText_loc4`='见鬼！还不如把这些东西拆成零件好了！它们根本毫无用处。', `MaleText_loc5`='該死啊!我們還得把這些零件拆下來!這些對我們一點用也沒有。', `MaleText_loc7`='¡Maldición! ¡Deberíamos desmontar estos en trocitos! No nos sirven de nada.' WHERE `ID`=22605;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간이 별로 없으니 바퀴를 파내라!', `MaleText_loc4`='快把轮子挖出来，我们没时间了！', `MaleText_loc5`='把輪子挖出來，我們沒多少時間了!', `MaleText_loc7`='¡Sacad las ruedas de ahí, no tenemos mucho tiempo!' WHERE `ID`=22606;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠시만, 이방인. 앉아서 떠드는 건 나도 무척 좋아하는데 말이지, 머리가 지독하게 쾅쾅 울려대서 말이야.$b$b저기 아무짝에도 쓸모없는 트롤 녀석들 난리 치는 거 좀 멈춰봐. 그러고 나서 이야기하세. 어때?', `MaleText_loc4`='陌生人，听着。我很乐意坐下来聊聊，不过我头痛得厉害。$b$b不如你先让这帮一无是处的巨魔安静点，然后我们再谈，怎么样？', `MaleText_loc5`='聽著，陌生人，我很樂意坐下來跟你好好的談談，但是有一股吵雜的聲音令我頭痛不已。$b$b不如你讓這些沒用的食人妖停止製造這種噪音。接著我們就可以好好的談談，好嗎?', `MaleText_loc7`='Escucha colega, me encantaría sentarme a hablar, pero me duele muchísimo la cabeza.$B$B¿Qué tal si haces que esos inútiles trols dejen de montar tanto escándalo y luego hablamos?' WHERE `ID`=22607;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 자네한테 빚을 졌다고, $r.$b$b사실 자네가 나타나기 전까지만 해도 이제 술은 다 마셨구나 싶었다니까.', `MaleText_loc4`='好吧，$r，算我欠你情啦。$b$b在你出现之前，我还以为这是我最后一口酒呢。', `MaleText_loc5`='那麼，我想我該向你說聲謝謝，$r。$b$b事實上，假如你沒出現的話我想我可能會把我僅有的最後一個酒杯都給吞下肚了呢。', `MaleText_loc7`='Bueno, supongo que debo darte las gracias, $r.$B$BLa verdad es que, hasta que has llegado, creía que me había tragado mi última jarra de cerveza.' WHERE `ID`=22608;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 어쩌다가 당신 같은 드워프가 이런 지경에 처했습니까?', `MaleText_loc4`='那么，一个像你这样的矮人到底是怎样沦落到这里的呢？', `MaleText_loc5`='那麼，像你這樣的矮人是怎麼淪落到這個地方的呢?', `MaleText_loc7`='¿Cómo acaba un enano como tú en un lugar como este?', `FemaleText_loc1`='그래, 어쩌다가 당신 같은 드워프가 이런 지경에 처했나요?', `FemaleText_loc4`='那么，一个像你这样的矮人到底是怎样沦落到这里的呢？', `FemaleText_loc5`='那麼，像你這樣的矮人是怎麼淪落到這個地方的呢?', `FemaleText_loc7`='¿Cómo acaba un enano como tú en un lugar como este?' WHERE `ID`=22609;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='슬픈 이야길세... 조금 부끄러운 이야기이기도 하고.$b$b알다시피, 드워프가 워낙 술을 좋아하지 않나. 나도 예외는 아니라고. 아니, 오히려 남들보다 더 술을 밝힌다네.$b$b그래서 버드한테 달려간 게야. 버드가 그로그주를 줄 테니 자기 수하로 들어오라고 했거든. 후회할 짓을 해버린 게지.$b$b어느 날 밤, 코도도 재울 만큼 그로그주를 퍼마시고는, 어울리지도 않게 버드네 무리를 쫓아서 줄아만에 들어왔지.$b$b그러고 나서 정신을 차려보니 우리 안이었다네.', `MaleText_loc4`='那是个伤心的故事——还有几分尴尬。$b$b矮人嗜酒如命可是众所周知的事。我自然也不例外，而且我对美酒的喜爱程度完全超越了我的想象。$b$b就这样，我遇见了巴德。他说只要我愿意加入探险队，就能尽情享受所有的美酒。我经受不了诱惑，做出了令我后悔至今的决定。$b$b那天晚上，我喝下足以放倒一头科多兽的烈酒之后，跟随巴德的杂牌探险队进入了祖阿曼。$b$b待我清醒时，发现自己已经沦为囚犯了。', `MaleText_loc5`='那是一個悲傷的故事─也有點令人難為情的故事。$b$b你知道的，我們族人是出了名的愛喝酒。而我也不例外。看起來我愛喝酒的程度比我想像的還嚴重。$b$b於是我跑去找霸德，他說只要我成為他的組員就可以盡情喝個夠─接下來的決定讓我感到後悔。$b$b有一晚，我喝了足夠醉倒一隻科多獸的酒，霸德引誘我跟著他那無法勝任的小組進入祖阿曼。$b$b我記得的下一件事情就是我在那個牢籠中醒過來了。', `MaleText_loc7`='Esa es una historia triste y un poco humillante.$B$BMi gente es conocida por tener buen gusto para la bebida, ya sabes. Y yo no soy una excepción. Parece que tengo más sed de lo normal.$B$BAsí que ya ves, me encontré con el viejo Budd y me ofreció todo el grog que pudiera beber, si me unía a su equipo, algo de lo que me he arrepentido.$B$BUna noche, después de beber como para tumbar a un kodo, me engatusaron para que siguiera al equipo de inadaptados de Budd a Zul''Aman.$B$BEso es lo último que recuerdo antes de encontrarme en esta jaula.' WHERE `ID`=22610;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우와, 절 우리에서 꺼내 주시다니 너무 감사한 게요 저는 여기 너무너무 오래 있었는데 여기선 양고기 저민 거 일주일은 햇볕에 내다 놓은 것 같은 냄새가 나고 저는 양고기 싫은데 왜냐하면 제가 작았을 때, 말하자면 더 작았을 때, 잠시 양이 됐던 적이 있어서 양이 된다는 게 어떤 기분인지 알고요 누구한테 잡아먹히기 싫고요 특히 고양이 분장을 한 성장 과잉 트롤한테 잡아먹히는 건 더 싫거든요...$b$b<깊이 숨을 몰아쉬는 아쉴리>$b$b제 머리 엉망이죠?', `FemaleText_loc4`='噢，谢谢你帮我逃离了牢笼我被囚禁了好久那里闻起来就像被太阳曝晒了一周的碎羊肉但是呢我很讨厌羊肉因为我在很小很小的时候被变成了一头羊而且长达一分钟因此我很清楚做羊的滋味所以我自然不希望被吃掉尤其是被打扮得像猫的大巨魔吃掉……$b$b<阿什莉深深地吸了一口气。>$b$b我的发型没乱吧？', `FemaleText_loc5`='喔，非常感謝你將我從那個牢籠之中救了出來，因為我被關太久了，那裡的味道聞起來就像是剁碎的羊肉放在陽光下曬了一整個禮拜一樣，而我可是一點都不想提起羊肉，那是因為我小時候，比現在還小一點的時候，我真的有過被人變形成一隻羊一陣子的經驗，所以我知道當一隻羊是什麼樣的感覺，並且我不喜歡有人把我吃掉，尤其是一個打扮起來像一隻小貓咪，營養又過盛的食人妖...$b$b<阿西利深深地吸了一口氣。>$b$b我的髮型亂掉了嗎?', `FemaleText_loc7`='Oh, muchas gracias por sacarme de esa jaula porque llevo tanto tiempo ahí y olía a carne de oveja picada que ha estado al sol durante una semana y, para empezar, no me gusta la carne de oveja, porque cuando era pequeña, bueno más pequeña, me convirtieron en oveja durante un minuto, así que sé como es ser una oveja y no quiero que alguien me coma, sobre todo si es muy grande y va vestido de gatito...$B$B< Ashli respira hondo>$B$B¿Qué tal tengo el pelo?' WHERE `ID`=22611;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어쩌다가 당신같이 활발한 작은 노움이 이런 난장판에 잡혀 있게 됐습니까?', `MaleText_loc4`='像你这样自信的小侏儒怎么会陷入如此窘境呢？', `MaleText_loc5`='像你這樣可愛的小地精怎麼會陷入這場困境之中呢?', `MaleText_loc7`='¿Cómo ha podido meterse en semejante lío una gnomita tan alegre como tú?', `FemaleText_loc1`='어쩌다가 당신같이 활발한 작은 노움이 이런 난장판에 잡혀 있게 됐나요?', `FemaleText_loc4`='像你这样自信的小侏儒怎么会陷入如此窘境呢？', `FemaleText_loc5`='像你這樣可愛的小地精怎麼會陷入這場困境之中呢?', `FemaleText_loc7`='¿Cómo ha podido meterse en semejante lío una gnomita tan alegre como tú?' WHERE `ID`=22612;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 집 바깥에서 토끼한테 마법을 좀 연습해서 강한 마법사 돼서 놈리건에 가서 나쁜 놈들 다 물리치고 노움 모두 고향에 돌아가게 하고 싶었는데 엄마가 저는 모험을 떠나기엔 너무 어리다고 그랬는데 그때 만난 버드 아저씨가 말하길 어리지 않다는 마음가짐만 가지면 어린애가 아닌 거니까 자기 친구들이랑 여기 와서 연습해서 강한 마법사가 되라고 그랬는데 전부 잡혀서 우리 안에 처박혔어요...$b$b<깊이 숨을 몰아쉬는 아쉴리>$b$b그런데요, 당신 진짜 $r 맞아요?', `FemaleText_loc4`='我本想利用家门口的小兔子练习我的魔法技能这样我就能消灭盘踞在诺莫瑞根的坏人让所有侏儒回到自己的家园但是妈妈说我还太年轻不适合出来冒险再后来我遇到了巴德先生他说我其实很成熟啦完全可以和他的朋友们一起来这里他还说我可以在这里进行全面的练习呢接下来我们就被抓住了然后被关进了笼子……$b$b<阿什莉深深地吸了一口气。>$b$b你真的是$r吗？', `FemaleText_loc5`='我想要對著我家外的兔子練習我的法術好讓我的魔法更強大才可以去殺掉所有諾姆瑞根的壞人好讓所有地精回到家鄉去不過媽媽說我要去冒險還太年輕了不過之後我遇到了霸德先生他告訴我你只和你覺得的一樣年輕所以我可以和他的朋友一起到這裡來就可以得到所有我需要的練習不過之後我們就被抓了被關在籠子裡...$b$b<阿西利深深地吸了一口氣。>$b$b你真的是個$r嗎?', `FemaleText_loc7`='Quería practicar mis hechizos con los conejitos que hay fuera de mi casa para mejorar mi magia y poder ir a matar a los malos de Gnomeregan y dejar que todos los gnomos volvieran a casa pero mamá dijo que era demasiado joven para meterme en aventuras pero entonces conocí al señor Budd y me dijo que solo eres tan joven como te sientes y que podía venir aquí con sus amigos y conseguiría toda la práctica que necesitaba pero entonces nos cogieron y enjaularon...$B$B<Ashli respira hondo.>$B$B¿Eres $gun auténtico:una auténtica; $r?' WHERE `ID`=22613;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좌초된 얼라이언스 선원들은 죽을 것을 알면서도 필사적으로 저항하고 있어요.$B$B나름 감동적이긴 해도 한편으로는 한심하군요.', `FemaleText_loc4`='进退两难的联盟水手想必已经明白他们难逃一死，却选择了负隅顽抗。$B$B真是可悲可叹啊。', `FemaleText_loc5`='這些擱淺的聯盟水手知道他們活不久了，所以拼了老命的抵抗。$B$B英勇而可悲。', `FemaleText_loc7`='Los marineros varados de la Alianza saben que van a morir, pero aun así luchan contra nosotros con todas sus fuerzas.$B$BImpresionante y patético al mismo tiempo.' WHERE `ID`=22614;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='적막한 해안에 있는 얼라이언스가 전멸하는 것은 시간문제입니다. 포위당한데다 수적으로도 열세니까요.', `FemaleText_loc4`='击败荒弃海岸的联盟只是时间问题。他们已经被包围了，而且我们还占有数量优势。', `FemaleText_loc5`='遺棄水岸的聯盟軍隊潰敗只是時間上的問題，他們不僅被包圍，軍力也遠遜於我方。', `FemaleText_loc7`='Es cuestión de horas que aplasten a los Alianzas de Playa Derelicta. Están rodeados y son inferiores en número.' WHERE `ID`=22615;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='실바나스 여왕님의 뜻에 따라, 적은 파멸할 것입니다.', `FemaleText_loc4`='希尔瓦娜斯的意志在上，我们的敌人终将失败。', `FemaleText_loc5`='奉希瓦娜斯的意志，我們的敵人將被擊敗。', `FemaleText_loc7`='Por la voluntad de Sylvanas, nuestros enemigos caerán.' WHERE `ID`=22616;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고위집행관 안셀름 님께서 보고하라 하셨습니다.', `MaleText_loc4`='高级执行官安希尔姆要求你立刻报到。', `MaleText_loc5`='高階執行官安賽姆要求你的回報。', `MaleText_loc7`='El sumo ejecutor Anselm quiere tu informe.', `FemaleText_loc1`='고위집행관 안셀름 님께서 보고하라 하셨어요.', `FemaleText_loc4`='高级执行官安希尔姆要求你立刻报到。', `FemaleText_loc5`='高階執行官安賽姆要求你的回報。', `FemaleText_loc7`='El sumo ejecutor Anselm quiere tu informe.' WHERE `ID`=22617;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='벽을 따라 설치된 대포 두 문 때문에 진격이 늦어집니다. 저 대포가 없다면 우리 군대는 아무런 손실 없이 그들의 요새로 돌격할 수 있겠지요.$B$B대포를 파괴하거나 포탄이 떨어질 때까지 기다리거나 해야 합니다. 안셀름님께서 결정하시겠지만요.', `FemaleText_loc4`='就是城墙上的那两尊大炮延缓了我们的攻城速度。要是没有它们的保护，城墙上的守军早就会被我们杀得丢下要塞仓皇逃命去了。$B$B现在我们有两个选择，摧毁那些大炮，或者等他们弹药消耗完。就看安希尔姆怎么决定吧。', `FemaleText_loc5`='就是牆上的那兩尊火砲不斷減緩我們的攻勢。只要沒了火砲的援護，我們就能不費一兵一卒的情形下衝破他們的防禦工事。$B$B要不奪下火砲，要不就等到他們彈盡援絕。我想，安賽姆要做決定。', `FemaleText_loc7`='Esos dos cañones de la pared son lo que nos está ralentizando. Sin su protección, nuestras fuerzas podrían asaltar su fortificación sin sufrir ninguna baja.$B$BO eliminamos esos cañones o esperamos a que se queden sin munición. Elección de Anselm, supongo.' WHERE `ID`=22618;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그 저주받은 기사는 한때는 은빛 성기사단의 일원으로서 동료 성기사들과 같은 영웅이었지만 저주를 받았죠. 붉은십자군 수도원에서 미쳐가면서, 그는 자기가 살아 있고 나머지가 다 죽은 이들이라고 믿기 시작했어요.$B$B이제 그의 열정은 빛을 향해 있지 않아요. 할로윈 축제가 다가오면 그는 아제로스의 여러 마을에 암흑과 불길을 몰고 온답니다.', `FemaleText_loc4`='无头骑士本是白银之手的成员，可惜这位昔日的英雄被诅咒了。他盘踞在血色修道院中，失去理智的无头骑士竟然认为自己还活着，我们才是没有生命的亡者。$B$B他再也不是圣光忠诚的仆从了。随着万圣节的来临，他在艾泽拉斯世界各地的村落中散播着阴暗的种子，还有那仇恨的火焰。', `FemaleText_loc5`='無頭騎士，本來是白銀之手的一位騎士，也是他手下聖騎士中的一位英雄，卻受到了詛咒。他在血色修道院內發瘋了，相信除了他以外的我們都是不死族。$B$B現在，他的熱情不再服侍聖光。隨著萬鬼節的到來，他到處在艾澤拉斯的村落散佈絕望及烈火。', `FemaleText_loc7`='El Jinete decapitado, que una vez fue un caballero de la Mano de Plata y un héroe entre los paladines, está maldito. Se volvió loco dentro del Monasterio Escarlata y cree que él está vivo y nosotros muertos.$B$BAhora su fervor ya no está al servicio de la Luz. Con la llegada de Halloween lleva la penumbra y el fuego a los pueblos de Azeroth.' WHERE `ID`=22619;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저주받은 기사가 누굽니까?', `MaleText_loc4`='无头骑士是谁？', `MaleText_loc5`='誰是無頭騎士?', `MaleText_loc7`='¿Quién es El Jinete decapitado?', `FemaleText_loc1`='저주받은 기사가 누구지요?', `FemaleText_loc4`='无头骑士是谁？', `FemaleText_loc5`='誰是無頭騎士?', `FemaleText_loc7`='¿Quién es El Jinete decapitado?' WHERE `ID`=22620;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신경 쓸 거 없소, $r. $b$b크라즈는 죽은 거나 마찬가지요. 어서 떠나시오, $r. 사악한 트롤들이 당신까지 붙잡기 전에 말이오.', `MaleText_loc4`='别管我，$r。$b$b克拉斯活着跟死了也没什么两样。趁那些巨魔还没发现你，快逃命吧。', `MaleText_loc5`='別管我了，$r。$b$b卡拉茲跟死了沒什麼兩樣。你快走吧，$r，不然那些壞食人妖也會抓住你的。', `MaleText_loc7`='No te preocupes por mí, $r.$B$BKraz está casi muerto. Vete ahora $r, antes de que los trols malos te atrapen.' WHERE `ID`=22621;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='적을 없애려면 네놈들의 영혼을 빌려야겠다!', `FemaleText_loc4`='把你们的灵魂给我，帮助我消灭敌人！', `FemaleText_loc5`='把你們的靈魂給我，幫助我消滅敵人!', `FemaleText_loc7`='¡Denme sus almas para poder acabar con el enemigo!' WHERE `ID`=22622;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭉개라! 얼굴을 뭉개버려라!', `MaleText_loc4`='把他们打成肉酱！把他们的脸打扁！', `MaleText_loc5`='擊敗他們!打破他們的臉!', `MaleText_loc7`='¡Destrozadlos! ¡Destrozad sus caras!' WHERE `ID`=22623;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위치를 사수하라! 브리쿨 놈들을 막아라!', `MaleText_loc4`='守住防线！把维库人赶回去！', `MaleText_loc5`='堅守陣地!擋住維酷人!', `MaleText_loc7`='¡Mantengan la posición! ¡Retengan a los hombres vrykul!' WHERE `ID`=22624;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='브리쿨 놈들을 죽여라! 실바나스를 위하여!', `MaleText_loc4`='杀光维库杂种！希尔瓦娜斯万岁！', `MaleText_loc5`='殺光維酷人渣!為了希瓦娜斯!', `MaleText_loc7`='¡Matad basura vrykul! ¡Por Sylvanas!' WHERE `ID`=22625;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='브리쿨 놈이 지나가게 두지 마라! 깡그리 죽여라!', `MaleText_loc4`='别让维库人冲过去！杀光他们！', `MaleText_loc5`='不要讓維酷人通過!統統殺光!', `MaleText_loc7`='¡No dejéis que pasen vrykul! ¡Matadlos a todos!' WHERE `ID`=22626;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고르스가 직접 나서야겠다!', `MaleText_loc4`='看来有的事还是得戈斯亲自动手！', `MaleText_loc5`='葛司得自己親手解決一些事情!', `MaleText_loc7`='¡Algunas cosas tiene que hacerlas el propio Gorth!' WHERE `ID`=22627;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너는 고르스 새끼손가락 한 방으로도 보낼 수 있다!', `MaleText_loc4`='你不是戈斯的对手！', `MaleText_loc5`='你不是葛司的對手!', `MaleText_loc7`='¡No eres rival para Gorth!' WHERE `ID`=22628;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고르스는 죽어도 상관 안 한다! 고르스는 다시 꿰매면 된다!', `MaleText_loc4`='戈斯不在乎会不会搭上性命！戈斯要把他们都打扁！', `MaleText_loc5`='葛司不在意他是不是死了!葛司要一起拖延!', `MaleText_loc7`='¡A Gorth no le importa morir! ¡A Gorth lo vuelven a montar!' WHERE `ID`=22629;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자유다! 크라즈 인생은 여기서 끝인 줄 알았는데.$b$b고맙소, $c.', `MaleText_loc4`='自由啦！克拉斯的痛苦结束了。$b$b谢谢你，$c。', `MaleText_loc5`='自由!卡拉茲的生命已經結束了。$b$b感謝你，$c。', `MaleText_loc7`='¡Libertad! La vida de Kraz había terminado.$B$BGracias, $c.' WHERE `ID`=22630;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어쩌다 이렇게 됐습니까, 오크?', `MaleText_loc4`='兽人，你怎么啦？', `MaleText_loc5`='發生了什麼事，獸人?', `MaleText_loc7`='¿Qué te ha ocurrido, orco?', `FemaleText_loc1`='어쩌다 이렇게 됐나요, 오크?', `FemaleText_loc4`='兽人，你怎么啦？', `FemaleText_loc5`='發生了什麼事，獸人?', `FemaleText_loc7`='¿Qué te ha ocurrido, orco?' WHERE `ID`=22631;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크라즈는 이 저주받은 곳에 오지 않았어야 했소... 인간을 믿어서는 안 된다는 걸 알았어야 했소. 나는 바보였소, $c. 그의 조언에 따라 여기 왔다면 당신도 속은 거요.$b$b버드, 그 인간이 2달 동안 생사를 모르고 있는 내 아들을 마지막으로 봤다고 했소. 줄아만 안에서 아들을 찾을 수 있을 거라고 나를 꼬드겼지...$b$b그래서 그의 일행을 따라 여기 왔고, 모두 붙잡혔소. 당신이 도와주지 않았더라면 죽을 운명을 피할 수 없었을 거요.$b$b고맙소, 이방인이여.', `MaleText_loc4`='克拉斯就不该来这个鬼地方……不该相信人类。我真是个大傻瓜，$c，你莫非也是听信了巴德的鬼话来进来的？$b$b我的儿子已经失踪两个月了，据说有人最后一次看见他是和巴德在一起。巴德说我或许可以在祖阿曼中找到他的下落……$b$b我跟着探险队来到这里，然后沦为俘虏。要不是你帮忙，我肯定没命了。$b$b陌生人，谢谢你。', `MaleText_loc5`='卡拉茲從來就不該到這個被詛咒的地方...應該要知道人類不可信任。我真是個瞎了的笨蛋，$c，要是你聽從他的建議的話那你就也一樣了。$b$b我的兒子，消失三天了，最後一次看到他是跟個人類在一起，就是霸德。他告訴我可以在祖阿曼裡找到他...$b$b我跟著他們到這來，然後跟著剩下的人被抓起來。沒有你的幫助，我一定會死的。$b$b謝謝你，陌生人。', `MaleText_loc7`='Kraz nunca debió haber venido a este maldito lugar... Debería haber sabido que el humano no era de fiar. Fui un ciego insensato, $c, y tú también lo serás si sigues su consejo.$B$BMi hijo, perdido durante dos lunas, fue visto por última vez con el humano, Budd. Me dijo que podría encontrarlo dentro de las murallas de Zul''Aman...$B$BYo seguí a su gente hasta aquí y me capturaron junto a los demás. Sin tu ayuda, estaría condenado a morir.$B$BGracias.' WHERE `ID`=22632;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 해냈다! 우리가 테시르를 물리쳤다!', `MaleText_loc4`='成功了！我们打败了泰瑟尔！', `MaleText_loc5`='我們成功了!我們已經擊敗了泰瑟爾!', `MaleText_loc7`='¡Lo hemos logrado! ¡Hemos vencido a Tethyr!' WHERE `ID`=22633;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바다 괴물을 우리가 처치했다!', `MaleText_loc4`='我们打败了海怪！', `MaleText_loc5`='我們擊敗了海裡的怪物!', `MaleText_loc7`='¡Hemos vencido al monstruo marino!' WHERE `ID`=22634;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='추위를 잊고 잠시 쉬도록 하시오. 그대를 환대하오.', `MaleText_loc4`='过来暖和暖和，让你那一身疲倦的骨头歇歇。我们很好客的。', `MaleText_loc5`='快進來，外面冰天雪地的，讓你疲勞的筋骨好好休息一下。請享受我們的招待吧。', `MaleText_loc7`='Ven, resguárdate del frío y descansa tus agotados huesos un rato. Nuestra hospitalidad es tuya.', `FemaleText_loc1`='추위를 잊고 잠시 쉬도록 하시오. 그대를 환대하오.', `FemaleText_loc4`='过来暖和暖和，让你那一身疲倦的骨头歇歇。我们很好客的。', `FemaleText_loc5`='快進來，外面冰天雪地的，讓你疲勞的筋骨好好休息一下。請享受我們的招待吧。', `FemaleText_loc7`='Ven, resguárdate del frío y descansa tus agotados huesos un rato. Nuestra hospitalidad es tuya.' WHERE `ID`=22635;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='넌 이 의식을 막을 수 없다! 나의 남편, 왕께서 깨어나신다!', `FemaleText_loc4`='你已经无法阻止我了！我们的王，马上就要苏醒了！', `FemaleText_loc5`='你已經無法阻止我了!吾王馬上就要甦醒了!', `FemaleText_loc7`='¡No detendrás mi labor aquí!  ¡Mi esposo-rey despertará!' WHERE `ID`=22636;
