UPDATE `locales_broadcast_text` SET `MaleText_loc1`='열쇠... 열쇠를 찾으십시오!', `MaleText_loc4`='钥匙……你得先找到钥匙！', `MaleText_loc5`='鑰匙...你們一定要找到鑰匙!', `MaleText_loc7`='La llave... ¡Tienes que encontrar la llave!', `FemaleText_loc1`='열쇠... 열쇠를 찾아오셔야 합니다!', `FemaleText_loc4`='钥匙……你得先找到钥匙！', `FemaleText_loc5`='鑰匙...你們一定要找到鑰匙!', `FemaleText_loc7`='La llave... ¡Tienes que encontrar la llave!' WHERE `ID`=22638;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='브리쿨 녀석들이 열쇠를 가진 걸 본 것 같습니다.', `MaleText_loc4`='我好像在那些维库人身上见过钥匙。', `MaleText_loc5`='我想我在某位維酷人身上看見了鑰匙。', `MaleText_loc7`='Creo que vi una llave en uno de esos vrykuls.', `FemaleText_loc1`='브리쿨 녀석들이 열쇠를 가진 걸 본 거 같아요.', `FemaleText_loc4`='我好像在那些维库人身上见过钥匙。', `FemaleText_loc5`='我想我在某位維酷人身上看見了鑰匙。', `FemaleText_loc7`='Creo que vi una llave en uno de esos vrykuls.' WHERE `ID`=22639;
