UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저자들이 지하묘지에서 뭔가 부정한 의식을 진행하고 있어요. 그리고 제가 곧 제물로 바쳐질 겁니다!', `MaleText_loc4`='他们正在下面的墓穴中举行邪恶的仪式，我马上就要变成他们的祭品了！', `MaleText_loc5`='他們在底下的墓穴進行邪穢的儀式，我馬上就要被獻祭啦!', `MaleText_loc7`='¡Están llevando a cabo rituales impíos en las catacumbas y yo estoy a punto de ser el sacrificio!', `FemaleText_loc1`='저들이 지하묘지에서 뭔가 부정한 의식을 진행하고 있어요. 그 의식에 제가 곧 제물로 바쳐질 겁니다!', `FemaleText_loc4`='他们正在下面的墓穴中举行邪恶的仪式，我马上就要变成他们的祭品了！', `FemaleText_loc5`='他們在底下的墓穴進行邪穢的儀式，我馬上就要被獻祭啦!', `FemaleText_loc7`='¡Están llevando a cabo rituales impíos en las catacumbas y yo estoy a punto de ser el sacrificio!' WHERE `ID`=22642;
