UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 끝이군.', `MaleText_loc4`='这就是一切的结束。', `MaleText_loc5`='沒救了。', `MaleText_loc7`='Es el fin.', `FemaleText_loc1`='이제 끝이구나.', `FemaleText_loc4`='这就是一切的结束。', `FemaleText_loc5`='沒救了。', `FemaleText_loc7`='Es el fin.' WHERE `ID`=22644;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 고맙습니다! 고마워요!', `MaleText_loc4`='噢，谢谢你，谢谢你！', `MaleText_loc5`='喔，謝謝你，謝謝你!', `MaleText_loc7`='¡Oh, gracias, gracias!', `FemaleText_loc1`='오, 고맙습니다! 정말 고마워요!', `FemaleText_loc4`='噢，谢谢你，谢谢你！', `FemaleText_loc5`='喔，謝謝你，謝謝你!', `FemaleText_loc7`='¡Oh, gracias, gracias!' WHERE `ID`=22645;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙습니다. 절대 잊지 않겠습니다!', `MaleText_loc4`='谢谢你，我永远不会忘记你的恩情！', `MaleText_loc5`='謝謝，大恩沒齒難忘!', `MaleText_loc7`='Gracias. ¡Nunca olvidaré esto!', `FemaleText_loc1`='고맙습니다. 이 은혜는 절대 잊지 않겠어요!', `FemaleText_loc4`='谢谢你，我永远不会忘记你的恩情！', `FemaleText_loc5`='謝謝，大恩沒齒難忘!', `FemaleText_loc7`='Gracias. ¡Nunca olvidaré esto!' WHERE `ID`=22646;
