UPDATE `locales_broadcast_text` SET `MaleText_loc1`='브리쿨들은 악마입니다. 처치해야 합니다!', `MaleText_loc4`='必须消灭那些邪恶的维库人！', `MaleText_loc5`='維酷人很邪惡，一定要消滅他們!', `MaleText_loc7`='¡Los vrykuls son malignos y han de ser destruidos!', `FemaleText_loc1`='브리쿨들은 악마예요. 없애야 한단 말입니다!', `FemaleText_loc4`='必须消灭那些邪恶的维库人！', `FemaleText_loc5`='維酷人很邪惡，一定要消滅他們!', `FemaleText_loc7`='¡Los vrykuls son malignos y han de ser destruidos!' WHERE `ID`=22650;
