UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='놈들이 윈드러너호를 손에 넣게 내버려두지 마라, 얼간이들아! 물러서지 마!', `FemaleText_loc4`='你们这群蠢货，不能让风行者号落入敌人手中！给我顶住！', `FemaleText_loc5`='廢物，別讓他們拿下風行者號!堅守陣地!', `FemaleText_loc7`='¡No dejéis que tomen El Brisaveloz, chuchos inútiles! ¡Resistid!' WHERE `ID`=22653;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 모래톱을 정찰하는 놈들은 내장을 발라줘야겠다! 우리가 놈들이 설치한 덫에 제 발로 걸어 들어간 거야!', `FemaleText_loc4`='我要军法处置负责侦查这片海域的斥候！我们钻进了一个大圈套！', `FemaleText_loc5`='我要把偵查這些沙洲的偵查兵開場剖肚!我們踏入他們天殺的陷阱了!', `FemaleText_loc7`='¡Voy a destripar a los oteadores que exploraron estos arrecifes! ¡Hemos caído de lleno en su maldita trampa!' WHERE `ID`=22654;
