UPDATE `locales_broadcast_text` SET `MaleText_loc1`='궁수 제자리에! 사격 대기!', `MaleText_loc4`='弓箭手准备！瞄准！', `MaleText_loc5`='射手預備!待命射擊!', `MaleText_loc7`='¡Arqueros listos! ¡No disparéis!' WHERE `ID`=22662;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도대체 얼마나 어리석은 녀석이기에 감히 허락도 없이 여왕 폐하의 땅에 발을 들여놓는단 말인가?', `MaleText_loc4`='哪个蠢货竟敢不经觐见就擅自闯入陛下的领域？', `MaleText_loc5`='是誰那麼大膽未經通報就闖入陛下的領域?', `MaleText_loc7`='¿Quién es el insensato que se atreve a adentrarse en los dominios de su majestad sin ser anunciado?' WHERE `ID`=22663;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물이 나에게 평온을 주리라...', `MaleText_loc4`='水，赐予我宁静……', `MaleText_loc5`='水給予我寧靜...', `MaleText_loc7`='Agua otórgame serenidad...' WHERE `ID`=22664;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐, 그럴지도. 하지만, 우리 주인님의 영역을 침범한 건 네놈이지. 주인님께서는 그 일만으로도 너희를 단숨에 쓸어버릴 수도 있었지! 아서스 님께서는 도망친 노예에게 사랑도 자비도 베풀지 않으시니까.', `MaleText_loc4`='但是，你闯入了主上的领域。就凭僭越入侵这一点，他就有权处决你！阿尔萨斯大人对那些逃跑的奴隶没有任何的怜悯与仁慈！', `MaleText_loc5`='啊，但是闖進我們主人領土的人是你，他大可因為這個罪過就把你立刻攆出去!阿薩斯對逃跑的奴隸可沒什麼愛與耐心。', `MaleText_loc7`='Ah, pero eres tú el que se adentra en el territorio de nuestro maestro. Podría eliminarte en un instante por esta trasgresión. Arthas no tiene paciencia ni cariño en lo referente a los esclavos que se escapan.' WHERE `ID`=22665;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 화로에서 새어 나오는 희미한 연기를 들이마십니다.', `MaleText_loc4`='%s吸入了从火炉中腾起的轻烟。', `MaleText_loc5`='%s吸入了從爐子發散出來的細微煙絲。', `MaleText_loc7`='%s inhala los menudos zarcillos de humo que emanan del quemador.' WHERE `ID`=22666;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 최면에 빠집니다.', `MaleText_loc4`='%s突然陷入了精神恍惚的状态。', `MaleText_loc5`='%s進入一種恍惚狀態。', `MaleText_loc7`='%s entra en trance.' WHERE `ID`=22668;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러나... 그분께서는 네놈이 스톰윈드에서 온 북쪽바다 함대를 상대로 거둔 승리를 보시고 너에게 가능성이 있다고 평가하셨다. 네가 상황을 파악하고 난 다음에 유치한 반란을 저지른 실바나스를 저버릴 가능성 말이다.', `MaleText_loc4`='但是……他已经得知了你们战胜暴风城北方舰队的消息，并且相信你们有足够的潜力，能够明察事理并抛弃希尔瓦娜斯幼稚的复仇理论。', `MaleText_loc5`='但是...他已知曉你戰勝暴風城北方艦隊的消息，並且認可了你的潛力。擁有認清時務、放棄希瓦娜斯幼稚反叛的潛力。', `MaleText_loc7`='Pero... se ha enterado de tu victoria sobre la Flota Norte de Ventormenta y cree que tienes potencial. Potencial para entrar en razón y abandonar la infantil rebelión de Sylvanas.' WHERE `ID`=22669;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙구나, 정령들아.', `MaleText_loc4`='谢谢你们，万物之灵。', `MaleText_loc5`='謝謝你，靈魂。', `MaleText_loc7`='Gracias, espíritus.' WHERE `ID`=22670;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아서스 님께서는 상상할 수조차 없는 힘을 내리실 것이다. 스컬지의 품으로 돌아왔을 때 지휘할 대군에 비하면, 지금 네놈이 이끄는 하찮은 군대 따위는 아무것도 아니지.', `MaleText_loc4`='阿尔萨斯准备赐予你力量，超乎你想象的力量。比起以后你将领导的天灾军团来说，眼下你手中的军队简直脆弱得可笑。', `MaleText_loc5`='阿薩斯準備賜予你超乎想像的力量。你在這裡所帶領的弱小軍隊，和回到天譴軍團麾下聽命於你的陣容相比根本不值一提。', `MaleText_loc7`='Arthas está preparado para ofrecerte más poder del que puedes imaginar. El endeble ejército que diriges aquí palidecería si fuera comparado con las falanges que tendrías a tu mando si regresaras al abrazo de la Plaga.' WHERE `ID`=22671;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으악, 검은무쇠 드워프다!!!', `MaleText_loc4`='黑铁矮人！！！', `MaleText_loc5`='黑鐵矮人!!!', `MaleText_loc7`='Enanos Hierro Negro', `FemaleText_loc1`='악, 검은무쇠 드워프가 나타났다!!!', `FemaleText_loc4`='黑铁矮人！！！', `FemaleText_loc5`='黑鐵矮人!!!', `FemaleText_loc7`='Enanos Hierro Negro' WHERE `ID`=22672;
