UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세상 모든 곳이 멸망하더라도 여긴 안전할 거다.', `MaleText_loc4`='我们在这里很安全，兄弟姐妹都很安全，但这世界都要毁灭了。', `MaleText_loc5`='我的兄弟姊妹，我們在這裡很安全，但是世上其他的生物就只能消逝了。', `MaleText_loc7`='Aquí estamos a salvo, mis hermanos y hermanas, mientras que el resto del mundo perecerá.' WHERE `ID`=22682;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가끔은 진실을 몰랐으면 하고 바랄 때도 있지. 하지만 이내 아는 게 최선이라는 걸 깨닫기 마련이다.', `MaleText_loc4`='有时候，我甚至希望我什么也不知道。但很快我就意识到现在这样也挺好的。', `MaleText_loc5`='有時候，我真希望我什麼都不知道。但是後來我發現這才是最好的情況。', `MaleText_loc7`='En ocasiones yo desearía no saberlo. Pero sé que es lo mejor.' WHERE `ID`=22683;
