UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미간을 노려라! 바로 저 짐승들의 약점이다!', `MaleText_loc4`='瞄准它们的眉心！那里是怪兽的弱点！', `MaleText_loc5`='對準雙眼間射擊!那些野獸的弱點在那!', `MaleText_loc7`='¡Disparadle entre los ojos! ¡Esas bestias son vulnerables ahí!', `FemaleText_loc1`='미간을 노려! 저 짐슴들의 약점을 노려라!', `FemaleText_loc4`='瞄准它们的眉心！那里是怪兽的弱点！', `FemaleText_loc5`='對準雙眼間射擊!那些野獸的弱點在那!', `FemaleText_loc7`='¡Disparadle entre los ojos! ¡Esas bestias son vulnerables ahí!' WHERE `ID`=22690;
