UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 괴물들을 통과시켜서는 안 된다! 제군들, 위치를 사수하라!', `MaleText_loc4`='别让这些怪物冲进城门！士兵们，坚守防线！', `MaleText_loc5`='別讓那些怪物穿過這道門!堅持住，士兵!', `MaleText_loc7`='¡No dejéis que esos monstruos atraviesen la puerta! ¡Manteneos firmes, soldados!', `FemaleText_loc1`='저 괴물들이 한 발짝이라도 들어놓게 해서는 안 된다! 위치를 사수하라!', `FemaleText_loc4`='别让这些怪物冲进城门！士兵们，坚守防线！', `FemaleText_loc5`='別讓那些怪物穿過這道門!堅持住，士兵!', `FemaleText_loc7`='¡No dejéis que esos monstruos atraviesen la puerta! ¡Manteneos firmes, soldados!' WHERE `ID`=22692;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신을 지원하고 보호하는 임무를 띠고 왔습니다.$B$B명령을 내려 주십시오.', `MaleText_loc4`='$g先生:女士;！我负责保护你的安全。$B$B请下令吧！', `MaleText_loc5`='$G長官:女士;!我來這兒協助防禦。$B$B您的命令是?', `MaleText_loc7`='$G Señor : Señora; estoy aquí para $gayudarle y defenderle:ayudarla y defenderla;.$B$B¿Sus órdenes?' WHERE `ID`=22693;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오랫동안 난 나를 잃었었지. 드디어 이제 내 영혼이 얼마나 암흑 속에 물들었는지 알게 되었구려...', `MaleText_loc4`='这些年来，我一直处于迷失的混沌中。现在，我终于看到自己的灵魂变得有多么黑暗……', `MaleText_loc5`='多年來，我迷失了。如今，終於，我看到我的靈魂變得多麼黑暗...', `MaleText_loc7`='Durante años estuve perdido. Ahora, por fin, veo la oscuridad que había anidado en mi alma...' WHERE `ID`=22694;
