UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나도 몰라. 하지만 무척 크고 화가 나 있다는 건 확실해!', `MaleText_loc4`='我不知道，我只知道他们体型魁梧，性情狂暴！', `MaleText_loc5`='我不知道，不過他們很大，而且他們很髒!', `MaleText_loc7`='No lo sé, ¡pero son grandes y están enfadados!', `FemaleText_loc1`='모르겠는걸. 하지만 무척 크고 화가 나 있다는 건 확실하군!', `FemaleText_loc4`='我不知道，我只知道他们体型魁梧，性情狂暴！', `FemaleText_loc5`='我不知道，不過他們很大，而且他們很髒!', `FemaleText_loc7`='No lo sé, ¡pero son grandes y están enfadados!' WHERE `ID`=22707;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분명히 노움은 아니야.', `MaleText_loc4`='总之他们绝对不是侏儒。', `MaleText_loc5`='他們肯定不是地精。', `MaleText_loc7`='Definitivamente no son gnomos.', `FemaleText_loc1`='절대 노움은 아니라고.', `FemaleText_loc4`='总之他们绝对不是侏儒。', `FemaleText_loc5`='他們肯定不是地精。', `FemaleText_loc7`='Definitivamente no son gnomos.' WHERE `ID`=22708;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='목숨 걸고 싸우기 전에 질문을... 아니, 잠깐... 알 게 뭐야! 모두 없애버려!', `MaleText_loc4`='先停止战斗，让我来问问他们……好吧……管他的！杀啊！', `MaleText_loc5`='先停手，讓我來問問他們 - 喔，等等...誰理他們!殺就對了!', `MaleText_loc7`='Permite que pare de luchar por mi vida y pregúntales... oh, espera... ¡Qué más da! ¡Solo mata!', `FemaleText_loc1`='목숨 걸고 싸우기 전에 질문을... 아니, 잠깐... 알 게 뭐람! 다 없애버리자고!', `FemaleText_loc4`='先停止战斗，让我来问问他们……好吧……管他的！杀啊！', `FemaleText_loc5`='先停手，讓我來問問他們 - 喔，等等...誰理他們!殺就對了!', `FemaleText_loc7`='Permite que pare de luchar por mi vida y pregúntales... oh, espera... ¡Qué más da! ¡Solo mata!' WHERE `ID`=22709;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그게 무슨 상관이야?', `MaleText_loc4`='这重要吗？', `MaleText_loc5`='有這麼嚴重嗎?', `MaleText_loc7`='¿Realmente importa?', `FemaleText_loc1`='그게 무슨 상관이냐고!', `FemaleText_loc4`='这重要吗？', `FemaleText_loc5`='有這麼嚴重嗎?', `FemaleText_loc7`='¿Realmente importa?' WHERE `ID`=22710;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어림짐작이지만, 아무래도 놈들은 저기 거대하고 사악해 보이는 성에서 오는 것 같군. 물론 아닐 수도 있지만 말이야.', `MaleText_loc4`='我觉得他们是从那座邪恶的大城堡里冒出来的。好吧，我只是瞎猜而已，或许猜错了。', `MaleText_loc5`='雖然是從暗處來的全面射擊，但是我猜他們是從那座巨大的邪惡城堡來的。不過，我有可能會猜錯。', `MaleText_loc7`='No es más que una suposición, pero creo que vienen de ese maléfico castillo gigante. Podría equivocarme.', `FemaleText_loc1`='아무래도 이 녀석들 저기 거대하고 사악해 보이는 성에서 오는 것 같은데... 아닐 수도 있지만 말이지.', `FemaleText_loc4`='我觉得他们是从那座邪恶的大城堡里冒出来的。好吧，我只是瞎猜而已，或许猜错了。', `FemaleText_loc5`='雖然是從暗處來的全面射擊，但是我猜他們是從那座巨大的邪惡城堡來的。不過，我有可能會猜錯。', `FemaleText_loc7`='No es más que una suposición, pero creo que vienen de ese maléfico castillo gigante. Podría equivocarme.' WHERE `ID`=22711;
