UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 이제 죽은 목숨인가? 모르겠는데... 그냥 내 생각이야.', `MaleText_loc4`='我们会死吗？我不知道……猜测而已。', `MaleText_loc5`='我們死了嗎?我也不清楚...亂猜的。', `MaleText_loc7`='¿Nosotros muertos? No sé... Era solo una idea.', `FemaleText_loc1`='우리 이제 죽은 목숨이야? 모르겠군... 그냥 생각해 본 거라고.', `FemaleText_loc4`='我们会死吗？我不知道……猜测而已。', `FemaleText_loc5`='我們死了嗎?我也不清楚...亂猜的。', `FemaleText_loc7`='¿Nosotros muertos? No sé... Era solo una idea.' WHERE `ID`=22713;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='64,000골드짜리 질문인데, 안 그래?', `MaleText_loc4`='你问的是奖金高达64,000金的竞猜问题？', `MaleText_loc5`='這真是個重要的問題，不是嗎?', `MaleText_loc7`='Esa es la pregunta de los 64000 oros, ¿verdad?', `FemaleText_loc1`='64,000골드짜리 질문인걸, 안 그래?', `FemaleText_loc4`='你问的是奖金高达64,000金的竞猜问题？', `FemaleText_loc5`='這真是個重要的問題，不是嗎?', `FemaleText_loc7`='Esa es la pregunta de los 64000 oros, ¿verdad?' WHERE `ID`=22714;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얘네들이 질문 좀 그만하랜다! 입 다물고 싸워!', `MaleText_loc4`='他们只想让你闭嘴！别废话了，战斗吧！', `MaleText_loc5`='他們要你停止發問!殺就對了!', `MaleText_loc7`='¡Quieren que dejes de hacer preguntas! ¡Cállate y lucha!', `FemaleText_loc1`='질문 좀 그만하라잖아! 그 입 다물고 싸우라고!', `FemaleText_loc4`='他们只想让你闭嘴！别废话了，战斗吧！', `FemaleText_loc5`='他們要你停止發問!殺就對了!', `FemaleText_loc7`='¡Quieren que dejes de hacer preguntas! ¡Cállate y lucha!' WHERE `ID`=22715;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흐르는 모래의 2차 전쟁이 있을 때 세나리온 요새에서의 생각이 나는데... 그 오크 기억 나나? 사울팽이었나? 그런 무시무시한 놈은 난생처음 봤어.', `MaleText_loc4`='让我想起了第二次流沙之战时我驻守塞纳里奥要塞的日子……还记得那个兽人吗？是叫萨鲁法尔？他是我见过的最厉害的家伙。', `MaleText_loc5`='提醒了我在第二次流沙大戰期間駐守在塞納里奧城堡的時光...記得那個獸人嗎?薩魯法爾?是我見過最該死的東西了。', `MaleText_loc7`='Me recuerda a cuando estaba destinado en el Fuerte Cenarion durante la segunda guerra del Mar de Dunas... ¿Recuerdas a aquel orco? ¿Colmillosauro? La cosa más terrible que jamás he visto.', `FemaleText_loc1`='흐르는 모래의 2차 전쟁이 벌어졌을 때 세나리온 요새에서의 기억이 나는군... 그 오크 기억 나? 사울팽이었나? 그런 무시무시한 녀석은 난생처음 봤다니까.', `FemaleText_loc4`='让我想起了第二次流沙之战时我驻守塞纳里奥要塞的日子……还记得那个兽人吗？是叫萨鲁法尔？他是我见过的最厉害的家伙。', `FemaleText_loc5`='提醒了我在第二次流沙大戰期間駐守在塞納里奧城堡的時光...記得那個獸人嗎?薩魯法爾?是我見過最該死的東西了。', `FemaleText_loc7`='Me recuerda a cuando estaba destinada en el Fuerte Cenarion durante la segunda guerra del Mar de Dunas... ¿Recuerdas a aquel orco? ¿Colmillosauro? La cosa más terrible que jamás he visto.' WHERE `ID`=22716;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 오크를 좋아하는 건 아니지만, 그자가 지금 여기 있었으면 좋겠군. 이런 것들 따윈 한 방에 끝장낼 텐데!', `MaleText_loc4`='我对兽人没有好感，但是如果现在他在这里就好了。他能将这些家伙大卸八块！', `MaleText_loc5`='我不喜歡獸人，但是，對呀，我希望他現在在這裡。他可以把這些東西給拆了!', `MaleText_loc7`='No soy un amante de los orcos, pero desearía que estuviera aquí ahora. ¡Él desmantelaría estas cosas!', `FemaleText_loc1`='오크를 좋아하는 건 아니지만, 그 녀석이 지금 여기 있었으면 싶네. 이런 것들 따윈 한 방에 끝장낼 텐데 말이야!', `FemaleText_loc4`='我对兽人没有好感，但是如果现在他在这里就好了。他能将这些家伙大卸八块！', `FemaleText_loc5`='我不喜歡獸人，但是，對呀，我希望他現在在這裡。他可以把這些東西給拆了!', `FemaleText_loc7`='No soy una amante de los orcos, pero desearía que estuviera aquí ahora. ¡Él desmantelaría estas cosas!' WHERE `ID`=22717;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='듣기로는 그 친구 스랄의 오른팔이라더군. 쉬는 시간에 용을 잡아서 머리를 매달고 다닌다더라고.', `MaleText_loc4`='听说他待在萨尔身边。没事就在城墙上挂龙头解闷。', `MaleText_loc5`='聽說他是索爾的左右手。閒來沒事就在掛龍頭。', `MaleText_loc7`='He oído que es la mano derecha de Thrall. En sus ratos libres cuelga cabezas de dragón.', `FemaleText_loc1`='듣자하니 그 녀석 스랄의 오른팔이라더군. 쉬는 시간에 용을 잡아서 머리를 매달고 다닌다던데 말이야.', `FemaleText_loc4`='听说他待在萨尔身边。没事就在城墙上挂龙头解闷。', `FemaleText_loc5`='聽說他是索爾的左右手。閒來沒事就在掛龍頭。', `FemaleText_loc7`='He oído que es la mano derecha de Thrall. En sus ratos libres cuelga cabezas de dragón.' WHERE `ID`=22718;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라그나로스를 직접 정령의 세계로 보내버렸다는 말도 있었지...', `MaleText_loc4`='听说他亲自将不可一世的拉格纳罗斯送回了元素位面……', `MaleText_loc5`='聽說他親自把拉格納羅斯趕回了元素界域...', `MaleText_loc7`='He oído que envió a Ragnaros de vuelta a los planos elementales él solito...', `FemaleText_loc1`='라그나로스를 직접 정령의 세계로 보내버렸다는 말도 있었어...', `FemaleText_loc4`='听说他亲自将不可一世的拉格纳罗斯送回了元素位面……', `FemaleText_loc5`='聽說他親自把拉格納羅斯趕回了元素界域...', `FemaleText_loc7`='He oído que envió a Ragnaros de vuelta a los planos elementales él solito...' WHERE `ID`=22719;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한때 그대는 생명을 잃었지...', `MaleText_loc4`='你感受到了死亡的恐惧……', `MaleText_loc5`='你曾嘗過死亡的滋味...', `MaleText_loc7`='Ya conociste la muerte...', `FemaleText_loc1`='한때 그대는 생명을 잃었지...', `FemaleText_loc4`='你感受到了死亡的恐惧……', `FemaleText_loc5`='你曾嘗過死亡的滋味...', `FemaleText_loc7`='Ya conociste la muerte...' WHERE `ID`=22720;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제는 죽음의 참맛을 느껴보아라!', `MaleText_loc4`='尝尝死亡的滋味吧！', `MaleText_loc5`='現在，感受終結吧!', `MaleText_loc7`='¡Ahora mírala de cerca!', `FemaleText_loc1`='이제는 죽음의 참맛을 느껴보아라!', `FemaleText_loc4`='尝尝死亡的滋味吧！', `FemaleText_loc5`='現在，感受終結吧!', `FemaleText_loc7`='¡Ahora mírala de cerca!' WHERE `ID`=22721;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='브리쿨을 보아라! 전쟁을 치르는 힘이나 파괴력이 그야말로 예술의 경지라 할 만큼 완벽하다. 브리쿨은 이미 리치 왕께 운명을 맡겼다! 이미 브리쿨 주거지가 여기를 겹겹이 에워쌌으며, 그 수는 이끄는 군대의 다섯 배가 훌쩍 넘을 정도이다.', `MaleText_loc4`='千万小心那些维库人！这是一个嗜血而凶残的种族，每日所想不过是征伐与杀戮。更何况，他们已经向巫妖王宣誓效忠！维库人在附近建立了多处定居点，他们的人数几乎是你们的5倍。', `MaleText_loc5`='看看那些維酷人!他們是一種將戰爭與破壞進行到近乎藝術程度的種族。他們追隨巫妖王遠離了家園!他們在你的四周定居了下來，而他們的人數是你的五倍有餘。', `MaleText_loc7`='¡Observen a los vrykuls! Una raza que ha perfeccionado la guerra y la destrucción hasta convertirlas en un arte. ¡Ya se han unido al Rey Exánime! Sus moradas los rodean y en cantidad probablemente sean cinco veces más que ustedes.' WHERE `ID`=22722;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 선택해라, 안셀름. 리치 왕의 품으로 돌아가 함께 싸우든가, 네놈의 여왕인지 뭔지 하는 존재에 계속 충성하든가 말이다. 여왕을 택한다면, 리치 왕의 군대가 너를 이 땅에서 몰아내고 진정한 분노가 무엇인지 맛보게 해 주리라!', `MaleText_loc4`='做出选择吧，安希尔姆。回到巫妖王的军队，与天灾军团并肩作战或者对你所谓的女王保持忠诚，直到天灾军团将你驱出他们的家园！', `MaleText_loc5`='你自己做決定吧，安賽姆。回到巫妖王身邊和他們並肩作戰，或者是繼續效忠你所謂的女王，忍受他們將你從家園趕走的怒火!', `MaleText_loc7`='La elección es tuya, Anselm. ¡Vuelve al ejército del Rey Exánime y lucha en sus filas o mantén tu lealtad a la que llamas tu reina y sufre la ira del ejército mientras te sacan a patadas de su tierra!' WHERE `ID`=22723;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이리 와. 냥이야, 냥이야...', `MaleText_loc4`='这里这里，小猫咪……', `MaleText_loc5`='在這裡，小貓小貓...', `MaleText_loc7`='Aquí, gatito, gatito...' WHERE `ID`=22724;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디 있는 거냐? 교활한 고양이 녀석들!', `MaleText_loc4`='你在哪儿呢？你这只鬼鬼祟祟的小坏猫！', `MaleText_loc5`='你在哪啊小子?這群該死小貓鬼鬼祟祟的!', `MaleText_loc7`='¿Dónde eh''tás, colega? ¡Los malditos gatos son escurridizos!' WHERE `ID`=22725;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쿠 야! 거기 있구나!', `MaleText_loc4`='耶！你在这里！', `MaleText_loc5`='喔耶!你在這裡!', `MaleText_loc7`='¡Genial! ¡Ahí eh''tás!' WHERE `ID`=22726;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쯧쯧, 이봐! 넌 고양이 찾는다고 온종일 여기 있었다고!', `MaleText_loc4`='瞧你！你这一整天都在找它们啊！', `MaleText_loc5`='看看你這小子!你將整天在這試著把他們找出來!', `MaleText_loc7`='¡Mírate, colega! ¡Llevas fuera todo el día intentando encontrah''los!' WHERE `ID`=22727;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기 하나 있다!', `MaleText_loc4`='那儿有一只！', `MaleText_loc5`='那裡有一個!', `MaleText_loc7`='¡Ahí hay uno, colega!' WHERE `ID`=22728;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아라날, 레델! 너희도 같은 운명을 맞으리라!', `MaleText_loc4`='Aranal ledel! 他们的命运归你们处置！', `MaleText_loc5`='(薩拉斯語)甦醒吧，爪牙們!他們的命運掌握在你手中!', `MaleText_loc7`='¡Aranal, ledel!  ¡Su destino les pertenecerá!' WHERE `ID`=22729;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 그리핀들은 아직 이곳의 지형을 익히는 중입니다, $c님. 그래서 협만 내에 있는 가까운 곳으로밖에 보내드리지 못하겠네요. 어디로 가시겠습니까?', `MaleText_loc4`='$c，我们的狮鹫还在学着适应这里复杂的地貌，因此我只能为你提供峡湾内的短途飞行服务。你想去哪儿啊？', `MaleText_loc5`='我們的獅鷲獸還在認識當地的地勢，$c，所以我只能提供你峽灣其他地方的短程航線。你想要去哪兒呢?', `MaleText_loc7`='Nuestros grifos aún se están familiarizando con la tierra, $c, así que solo puedo ofrecerte vuelos cortos a otros lugares del fiordo. ¿Adónde quieres ir?', `FemaleText_loc1`='우리 그리핀들은 아직 이곳의 지형을 익히는 중입니다, $c님. 그래서 협만 내에 있는 가까운 곳으로밖에 보내드리지 못하겠네요. 어디로 가시겠습니까?', `FemaleText_loc4`='$c，我们的狮鹫还在学着适应这里复杂的地貌，因此我只能为你提供峡湾内的短途飞行服务。你想去哪儿啊？', `FemaleText_loc5`='我們的獅鷲獸還在認識當地的地勢，$c，所以我只能提供你峽灣其他地方的短程航線。你想要去哪兒呢?', `FemaleText_loc7`='Nuestros grifos aún se están familiarizando con la tierra, $c, así que solo puedo ofrecerte vuelos cortos a otros lugares del fiordo. ¿Adónde quieres ir?' WHERE `ID`=22730;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발가드 항만으로 보내 주십시오.', `MaleText_loc4`='我要前往瓦加德港。', `MaleText_loc5`='帶我到瓦爾加德港口。', `MaleText_loc7`='Llévame al Puerto de Valgarde.', `FemaleText_loc1`='발가드 항만으로 보내 주세요.', `FemaleText_loc4`='我要前往瓦加德港。', `FemaleText_loc5`='帶我到瓦爾加德港口。', `FemaleText_loc7`='Llévame al Puerto de Valgarde.' WHERE `ID`=22731;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서부경비대 성채로 보내 주십시오.', `MaleText_loc4`='我要前往西部卫戍要塞。', `MaleText_loc5`='帶我到鎮西要塞。', `MaleText_loc7`='Llévame a la Fortaleza de la Guardia Oeste.', `FemaleText_loc1`='서부경비대 성채로 보내 주세요.', `FemaleText_loc4`='我要前往西部卫戍要塞。', `FemaleText_loc5`='帶我到鎮西要塞。', `FemaleText_loc7`='Llévame a la Fortaleza de la Guardia Oeste.' WHERE `ID`=22732;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빌더바르 요새로 보내 주십시오.', `MaleText_loc4`='我要前往维德瓦堡垒。', `MaleText_loc5`='帶我到威德瓦堡壘。', `MaleText_loc7`='Llévame a Fuerte Vildervar.', `FemaleText_loc1`='빌더바르 요새로 보내 주세요.', `FemaleText_loc4`='我要前往维德瓦堡垒。', `FemaleText_loc5`='帶我到威德瓦堡壘。', `FemaleText_loc7`='Llévame a Fuerte Vildervar.' WHERE `ID`=22733;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서두를 거 없다.', `MaleText_loc4`='别这么快。', `MaleText_loc5`='別急別急。', `MaleText_loc7`='No tan rápido.' WHERE `ID`=22734;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피를 내게 바쳐라!', `MaleText_loc4`='我要你的血！', `MaleText_loc5`='你的鮮血是屬於我的!', `MaleText_loc7`='¡Tu sangre es mía!' WHERE `ID`=22736;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 헛기침을 합니다.', `MaleText_loc4`='%s清了清嗓子。', `MaleText_loc5`='%s清了清他的喉嚨。', `MaleText_loc7`='%s se aclara la garganta.' WHERE `ID`=22737;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='온 기지에 공포심이 가득한 걸 느낄 수 있다... 리치 왕의 군대가 스톰윈드를, 아이언포지를 점령한대도 제군들이 두려움을 느낄 것 같나? 아니! 그렇지 않을 것이다. 왜냐고? 그때쯤이면 이미 제군들은 시체가 되어 있을 테니까.', `MaleText_loc4`='每一次我望向这个基地时，唯一能看到……就是恐惧……等到天灾军团占领了铁炉堡或是暴风城以后，你们还会感到恐惧吗？不！不会了！知道为什么吗？因为那时候你们早已没命了。', `MaleText_loc5`='我環顧整座基地，我只看見了恐懼...如果巫妖王的大軍就駐紮在暴風城、鐵爐堡，你會被嚇唬到嗎?不!你不會。你想知道為什麼嗎?因為你死定了，這就是為什麼。', `MaleText_loc7`='Observo esta base y todo lo que veo es miedo... ¿Vais a estar asustados cuando los ejércitos del Rey Exánime campen a sus anchas por Ventormenta? ¿Forjaz? ¡NO! ¿Y sabéis por qué? Porque estaréis muertos, por eso.' WHERE `ID`=22738;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러니 두려움이 등뼈를 타고 올라와 머리끝이 쭈뼛하고 바지에 오줌이라도 지릴 것 같은 기분이 들어도, 참아내라. 두려움을 분노로 승화시켜라. 그 공포만이 제군들이 목숨을 부지하게 해 줄 것이다.', `MaleText_loc4`='如果你感觉脊椎下传来阵阵凉意，甚至有尿裤子的冲动，倒是应该感到欣慰。让这种感觉刺激你的情绪吧。恐惧是唯一能让你保持呼吸的情感。', `MaleText_loc5`='當你感受到你的尾椎傳來一陣刺痛，而你馬上就要尿褲子的時候，接受它。讓它激怒你。那種恐懼感是唯一能讓你繼續呼吸的事情。', `MaleText_loc7`='Así que cuando sientas ese cosquilleo en la base de tu médula y estás a punto de mojarte los pantalones, abrázalo. Deja que te llene de ira. Ese miedo es lo único que te va a mantener con vida.' WHERE `ID`=22739;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알아들었나? 무슨 말인지 이해가 되느냔 말이다! 나는 이제 고향에 관짝이나 사망 통지서 따위를 보내고 싶지 않다.', `MaleText_loc4`='我说得够清楚了吧？你们听明白没？我可不想再送更多的棺材或者阵亡通知单回去了。', `MaleText_loc5`='我說得清楚嗎?你懂我在說什麼嗎?我可不想送回家更多的棺材或者是慰問信。', `MaleText_loc7`='¿Está claro? ¿Me estáis entendiendo? No quiero tener que enviar más cartas ni más ataúdes a casa.' WHERE `ID`=22740;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제거 중', `MaleText_loc4`='移除', `MaleText_loc5`='移除', `MaleText_loc7`='Eliminando', `FemaleText_loc1`='제거 중', `FemaleText_loc4`='移除', `FemaleText_loc5`='移除', `FemaleText_loc7`='Eliminando' WHERE `ID`=22741;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 호박 머리가 불길한 일을 예감하듯 연기를 피웁니다...', `MaleText_loc4`='南瓜头冒出了邪恶的烟雾……', `MaleText_loc5`='南瓜頭不祥地悶燒著...', `MaleText_loc7`='La cabeza calabaza arde y deja un mal presentimiento...' WHERE `ID`=22742;
