UPDATE `locales_broadcast_text` SET `MaleText_loc1`='작살을 뽑아내자 %s|1이;가; 고통스럽게 비명을 지릅니다.', `MaleText_loc4`='%s在你拔下鱼叉时痛苦地大叫起来。', `MaleText_loc5`='當魚叉被拔出來的同時，%s痛苦的大叫。', `MaleText_loc7`='%s grita agónicamente al retirar el arpón.', `FemaleText_loc1`='작살을 뽑자 %s|1이;가; 고통스럽게 비명을 지릅니다.', `FemaleText_loc4`='%s在你拔下鱼叉时痛苦地大叫起来。', `FemaleText_loc5`='當魚叉被拔出來的同時，%s痛苦的大叫。', `FemaleText_loc7`='%s grita agónicamente al retirar el arpón.' WHERE `ID`=22744;
