UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으윽... 안 돼... 고룡해골에... 살아남은... 친구들이...', `MaleText_loc4`='不……不……龙颅村……还有……幸存者……', `MaleText_loc5`='不...不...我族的人民...龍顱...有些還活著...', `MaleText_loc7`='No... no... Nuestra gente... Calavermis... algunos viven...', `FemaleText_loc1`='안 돼... 안... 고룡해골에... 살아남은... 우리 친구들이...', `FemaleText_loc4`='不……不……龙颅村……还有……幸存者……', `FemaleText_loc5`='不...不...我族的人民...龍顱...有些還活著...', `FemaleText_loc7`='No... no... Nuestra gente... Calavermis... algunos viven...' WHERE `ID`=22747;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 상처는... 살아 돌아가기엔... 너무 큽니다... 우리 친구들이 철창에 갇혀 있습니다... 의식에 희생될...', `MaleText_loc4`='我的伤势太重了。没法活着回去了……村民们……被关在笼子里……仪式……', `MaleText_loc5`='我傷得太重了。我撐不過去...我們的市民被關在牢裡...儀式...', `MaleText_loc7`='Mis heridas son demasiado graves. No lo conseguiré... Nuestros ciudadanos enjaulados... ritual...', `FemaleText_loc1`='제 상처가 너무 커... 살아 돌아갈 수 없겠네요... 우리 친구들이 철창에 갇혀 있습니다...', `FemaleText_loc4`='我的伤势太重了。没法活着回去了……村民们……被关在笼子里……仪式……', `FemaleText_loc5`='我傷得太重了。我撐不過去...我們的市民被關在牢裡...儀式...', `FemaleText_loc7`='Mis heridas son demasiado graves. No lo conseguiré... Nuestros ciudadanos enjaulados... ritual...' WHERE `ID`=22748;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피를 너무 많이... 흘려... 이미 늦었습니다... 나는 상관하지 마세요. 켈러 님께 ... 살아남은 이들이 아직 안에 있다고 전해주...', `MaleText_loc4`='我……不行了……失血过多……别管我了，告诉凯勒……还有人在里面……', `MaleText_loc5`='我沒救了...流太多血了...忘了我吧，告訴凱勒...裡面還有些人活著...', `MaleText_loc7`='Estoy acabado... demasiada pérdida de sangre... Olvídate de mí, dile a Keller... Queda gente viva dentro...', `FemaleText_loc1`='전 피를 너무... 많이 흘려... 이미 늦은 것 같습니다... 전 상관하지 마시고... 켈러 님께... 아직 저 안에 살아남은 이들이 있다고...', `FemaleText_loc4`='我……不行了……失血过多……别管我了，告诉凯勒……还有人在里面……', `FemaleText_loc5`='我沒救了...流太多血了...忘了我吧，告訴凱勒...裡面還有些人活著...', `FemaleText_loc7`='Estoy acabada... demasiada pérdida de sangre... Olvídate de mí, dile a Keller... Queda gente viva dentro...' WHERE `ID`=22749;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 가족에게 꼭 ... 사랑한다고... 언제나 사랑한다고...', `MaleText_loc4`='务必转告我的家人……我……永远……爱他们……', `MaleText_loc5`='我的家人一定曉得...我...為他們...永遠付出...', `MaleText_loc7`='Mi familia debe ser informada... Yo... por ellos... siempre por ellos...', `FemaleText_loc1`='제 가족에게... 사랑한다고... 언제나 사랑한다고... 꼭 전해주세요.', `FemaleText_loc4`='务必转告我的家人……我……永远……爱他们……', `FemaleText_loc5`='我的家人一定曉得...我...為他們...永遠付出...', `FemaleText_loc7`='Mi familia debe ser informada... Yo... por ellos... siempre por ellos...' WHERE `ID`=22750;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='녀석들은 우릴 작살에 꽂아 나머지 친구들에게 경고로 삼았습니다... 아직 살아남은... 포로가...', `MaleText_loc4`='他们把我们钉在这里，就是为了给其他人一个警告……还有些人活着……囚禁……', `MaleText_loc5`='他們拋下我們，當作殺雞儆猴...有些還活著...成了階下囚...', `MaleText_loc7`='Nos dejaron aquí empalados como advertencia para los demás... Algunos aún vivos... prisioneros de...', `FemaleText_loc1`='녀석들이 우리를 꿰뚫어 나머지 사람들에게 경고로 삼은 겁니다... 아직 살아남은... 우리 친구들이...', `FemaleText_loc4`='他们把我们钉在这里，就是为了给其他人一个警告……还有些人活着……囚禁……', `FemaleText_loc5`='他們拋下我們，當作殺雞儆猴...有些還活著...成了階下囚...', `FemaleText_loc7`='Nos dejaron aquí empalados como advertencia para los demás... Algunos aún vivos... prisioneros de...' WHERE `ID`=22751;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반드시 복수해주십시오, 이방인이여... 녀석... 들에게... 지옥을...', `MaleText_loc4`='为我复仇，陌生人……让他们……下地狱……', `MaleText_loc5`='為我的死復仇，陌生人...讓...他們...下地獄...', `MaleText_loc7`='No dejes mi muerte sin vengar, caminante... que...lo pasen... mal...', `FemaleText_loc1`='반드시 복수해주십시오, 이방인이여... 녀석... 들에게... 지옥을...', `FemaleText_loc4`='为我复仇，陌生人……让他们……下地狱……', `FemaleText_loc5`='為我的死復仇，陌生人...讓...他們...下地獄...', `FemaleText_loc7`='No dejes mi muerte sin vengar, caminante... que...lo pasen... mal...' WHERE `ID`=22752;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다, 영웅이여. 허락하신다면 당신과 함께 싸워 우릴 잡아둔 녀석들에게 복수하고 싶습니다!', `MaleText_loc4`='谢谢你，英雄。如果你不介意的话，我想呆在你的身边，向那些家伙复仇！', `MaleText_loc5`='請接受我的感謝，英雄。若是不介意，請讓我跟隨你，並為了被俘的弟兄復仇!', `MaleText_loc7`='Te lo agradezco, valiente. Si no te importa, me gustaría quedarme contigo y obtener un poco de venganza contra mis captores.', `FemaleText_loc1`='감사합니다, 영웅이여. 허락하신다면 당신과 함께 싸워 우릴 잡아간 놈들에게 복수하고 싶어요!', `FemaleText_loc4`='谢谢你，英雄。如果你不介意的话，我想呆在你的身边，向那些家伙复仇！', `FemaleText_loc5`='請接受我的感謝，英雄。若是不介意，請讓我跟隨你，並為了被俘的弟兄復仇!', `FemaleText_loc7`='Te lo agradezco, valiente. Si no te importa, me gustaría quedarme contigo y obtener un poco de venganza contra mis captores.' WHERE `ID`=22753;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 여기서 벗어나지 못하도록 비는 게 좋을 거다, 이 녀석들아.', `MaleText_loc4`='你最好祈祷这笼子能永远关着我，渣滓。', `MaleText_loc5`='混蛋，你最好保佑我不會逃出去。', `MaleText_loc7`='Reza para que no escape de aquí, escoria.', `FemaleText_loc1`='내가 여기서 벗어나지 못하도록 비는 게 좋을걸? 나쁜 녀석들.', `FemaleText_loc4`='你最好祈祷这笼子能永远关着我，渣滓。', `FemaleText_loc5`='混蛋，你最好保佑我不會逃出去。', `FemaleText_loc7`='Reza para que no escape de aquí, escoria.' WHERE `ID`=22754;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러니 날 도와주시오... 이 우리에서 벗어나면 녀석들에게 전부 되갚아 줄 거요.', `MaleText_loc4`='帮帮我……只要我能从这个该死的笼子里出来，这帮家伙就有苦头吃了。', `MaleText_loc5`='幫幫我...要是讓我逃出了這個籠子，一定讓他們好好付出代價。', `MaleText_loc7`='Así que ayúdame... Si escapo de esta jaula sufrirán las consecuencias.', `FemaleText_loc1`='그러니 절 좀 도와주세요... 이 우리에서 벗어나면 녀석들에게 전부 갚아 줄 거예요.', `FemaleText_loc4`='帮帮我……只要我能从这个该死的笼子里出来，这帮家伙就有苦头吃了。', `FemaleText_loc5`='幫幫我...要是讓我逃出了這個籠子，一定讓他們好好付出代價。', `FemaleText_loc7`='Así que ayúdame... Si escapo de esta jaula sufrirán las consecuencias.' WHERE `ID`=22755;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='복수할 기회를 줘서 고맙소, 친구여. 이제 발가드로 돌아가겠소.', `MaleText_loc4`='还能有机会略略报复一下真好。我这就动身返回瓦加德，朋友。', `MaleText_loc5`='感謝你讓我有機會可以復仇。我現在準備返回瓦爾加德了，朋友。', `MaleText_loc7`='Gracias por darme la oportunidad de vengarme. Ahora voy a volver a Valgarde, colega.', `FemaleText_loc1`='복수할 기회를 줘서 고마워요. 이제 전 발가드로 돌아가겠습니다.', `FemaleText_loc4`='还能有机会略略报复一下真好。我这就动身返回瓦加德，朋友。', `FemaleText_loc5`='感謝你讓我有機會可以復仇。我現在準備返回瓦爾加德了，朋友。', `FemaleText_loc7`='Gracias por darme la oportunidad de vengarme. Ahora voy a volver a Valgarde, colega.' WHERE `ID`=22756;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 피를 보려고 기를 쓰는구나! 하지만, 아직 멀었다... 네 녀석이 없애야 할 건, 내 머리다!', `MaleText_loc4`='你们竟如此渴望将我灭亡。可却不知，首级还在，我便可避过一切灾殃！', `MaleText_loc5`='你竟如此渴望我血盡而亡。但只要我的頭顱尚在，你就休想將我擊敗!', `MaleText_loc7`='Desesperado estás por ver mi sangre fluir, para ello es mi cabeza que debes destruir.' WHERE `ID`=22757;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헛된 몸부림이로군.', `MaleText_loc4`='瞧你这丧气的模样。', `MaleText_loc5`='真是沒用的攻勢。', `MaleText_loc7`='Un gesto infructuoso.' WHERE `ID`=22758;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='서두르세요, $c님!$b$b위기를 극복하려면 할 일이 많아요.', `FemaleText_loc4`='快点，$c！$b$b这场危机快要失控了。', `FemaleText_loc5`='動作快，$c!$b$b危機絲毫沒有受到控制。', `FemaleText_loc7`='¡Date prisa, $c!$B$BEsta crisis está de todo menos bajo control.' WHERE `ID`=22759;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 고맙습니다! 이 짐승 녀석들을 처치해서 당신의 도움에 보답하게 해 주십시오!', `MaleText_loc4`='非常感谢！我也去杀那些野蛮人，就当算是感谢你，帮你的忙了。', `MaleText_loc5`='感激不盡!請容許我把這幾頭野獸殺掉當作報答吧!', `MaleText_loc7`='¡Muchas gracias! ¡Permite que te devuelva el favor matando algunas docenas de estas bestias!', `FemaleText_loc1`='이렇게 고마울 때가요! 이 짐승들을 처치하여 당신에게 보답하게 해 주세요!', `FemaleText_loc4`='非常感谢！我也去杀那些野蛮人，就当算是感谢你，帮你的忙了。', `FemaleText_loc5`='感激不盡!請容許我把這幾頭野獸殺掉當作報答吧!', `FemaleText_loc7`='¡Muchas gracias! ¡Permite que te devuelva el favor matando algunas docenas de estas bestias!' WHERE `ID`=22760;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙습니다, 친구여. 함께 싸울 사람이 더 필요하지 않으십니까?', `MaleText_loc4`='谢谢你，朋友。你的队伍还需要人吗？', `MaleText_loc5`='謝了，朋友。在找尋隊友嗎?', `MaleText_loc7`='Gracias, colega. ¿Buscas a alguien para que se una a tu grupo?', `FemaleText_loc1`='고맙습니다. 함께 싸울 동료가 더 필요하지 않으세요?', `FemaleText_loc4`='谢谢你，朋友。你的队伍还需要人吗？', `FemaleText_loc5`='謝了，朋友。在找尋隊友嗎?', `FemaleText_loc7`='Gracias, colega. ¿Buscas a alguien para que se una a tu grupo?' WHERE `ID`=22761;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발가드로 돌아가기 전까지 당신을 돕겠습니다. 제가 할 수 있는 최소한의 일이군요.', `MaleText_loc4`='在我返回瓦加德之前我会尽量帮助你。这是我唯一能做的事了。', `MaleText_loc5`='我會在返回瓦爾加德之前幫助你逃出去。這起碼是我可以做到的事情。', `MaleText_loc7`='Te ayudaré a salir antes de volver a Valgarde. Es lo menos que puedo hacer.', `FemaleText_loc1`='발가드로 돌아가기 전까지 당신을 도울게요. 제가 할 수 있는 일은 이 정도뿐이군요.', `FemaleText_loc4`='在我返回瓦加德之前我会尽量帮助你。这是我唯一能做的事了。', `FemaleText_loc5`='我會在返回瓦爾加德之前幫助你逃出去。這起碼是我可以做到的事情。', `FemaleText_loc7`='Te ayudaré a salir antes de volver a Valgarde. Es lo menos que puedo hacer.' WHERE `ID`=22762;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='녀석들이 죄수들을 의식이 행해지는 샬레르브론이라는 곳에 제물로 바친다고 하더군요.', `MaleText_loc4`='我听说他们在仪式广场上将囚犯当作祭品供奉给天神。我想，那地方应该是叫亚勒伯龙……', `MaleText_loc5`='我聽見他們正在上面的儀式場地獻祭囚犯，我想，那個地方叫做夏勒布隆...', `MaleText_loc7`='He oído que están celebrando sacrificios en su zona de rituales. Creo que el lugar se llama Gjalerbron...', `FemaleText_loc1`='녀석들이 죄수들을 의식이 행해지는 샬레르브론이라는 곳에 제물로 바친다고 하더군요.', `FemaleText_loc4`='我听说他们在仪式广场上将囚犯当作祭品供奉给天神。我想，那地方应该是叫亚勒伯龙……', `FemaleText_loc5`='我聽見他們正在上面的儀式場地獻祭囚犯，我想，那個地方叫做夏勒布隆...', `FemaleText_loc7`='He oído que están celebrando sacrificios en su zona de rituales. Creo que el lugar se llama Gjalerbron...' WHERE `ID`=22763;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 마지막이라 생각하지 마라. 우트가드 군대가 네놈들을 짓밟고 나면 네 시체에 침을 뱉으러 와 줄 테니!', `MaleText_loc4`='这绝不是你最后一次看见我。等乌特加德的大军将你践踏至渣后，我还会回来朝你的尸体吐口水！', `MaleText_loc5`='這會是你聽到我說的最後一句話。俄特加德的部隊消滅你們以後，我會回去吐口水在你的屍體上!', `MaleText_loc7`='Esta no será la última vez que nos veamos. ¡Volveré para escupir sobre tu cadáver cuando los ejércitos de Utgarde hayan caído sobre ti!' WHERE `ID`=22764;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 영혼을 집어삼킬 때 네 부하 놈들이 내지르는 마지막 숨소리나 똑똑히 들어 둬라!', `MaleText_loc4`='我要吸取你们的灵魂，我要听你们临死前的哀号！', `MaleText_loc5`='仔細聽聽，當我吸吮你的手下的靈魂時他們垂死的喘息吧!', `MaleText_loc7`='¡Escucha el aliento moribundo de tus hombres mientras me bebo sus almas!' WHERE `ID`=22766;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디로 가나, $n? 내 박쥐라면 어디든 순식간에 날아갈 수 있지.', `MaleText_loc4`='你需要长途旅行么，$n？我的蝙蝠会很快把你送到目的地的。', `MaleText_loc5`='你想要去哪兒嗎，$n?我的蝙蝠會立刻把你帶到那邊。', `MaleText_loc7`='¿Buscas transporte a algún lugar, $n? Mis murciélagos te llevarán allí en un abrir y cerrar de ojos.' WHERE `ID`=22767;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='윈드러너호로 날아가야 합니다. 공적인 용무입니다!', `MaleText_loc4`='我需要飞往风行者号。紧急军务！', `MaleText_loc5`='我要飛去往風行者號。純屬公事!', `MaleText_loc7`='Necesito volar hasta El Brisaveloz. ¡Asuntos oficiales!', `FemaleText_loc1`='윈드러너호로 날아가야 해요. 공적인 용무랍니다!', `FemaleText_loc4`='我需要飞往风行者号。紧急军务！', `FemaleText_loc5`='我要飛去往風行者號。純屬公事!', `FemaleText_loc7`='Necesito volar hasta El Brisaveloz. ¡Asuntos oficiales!' WHERE `ID`=22768;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 죽은 자의 시체에 자신의 힘을 집중합니다.', `FemaleText_loc4`='%s将能量引导向死者的遗体。', `FemaleText_loc5`='%s將她的能量灌注到陣亡的屍首上。', `FemaleText_loc7`='%s concentra sus energías en los cadáveres de los caídos.' WHERE `ID`=22769;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하찮은 것...', `FemaleText_loc4`='卑劣……', `FemaleText_loc5`='毫無價值...', `FemaleText_loc7`='Indigno...' WHERE `ID`=22770;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='쓸모없는 제물이여...', `FemaleText_loc4`='没有价值的祭品……', `FemaleText_loc5`='無用的祭品...', `FemaleText_loc7`='Una ofrenda despreciable...' WHERE `ID`=22771;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='유죄다...', `FemaleText_loc4`='令人不快的裁决……', `FemaleText_loc5`='不吉的裁定...', `FemaleText_loc7`='Un veredicto desfavorable...' WHERE `ID`=22772;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='넌 실패했다...', `FemaleText_loc4`='你失败了……', `FemaleText_loc5`='你輸了...', `FemaleText_loc7`='Habéis fracasado...' WHERE `ID`=22773;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하사관, 망원경을 빌려주십시오.', `MaleText_loc4`='中士，把你的望远镜借给我。', `MaleText_loc5`='士官，把你的望遠鏡借我。', `MaleText_loc7`='Sargento, préstame tu catalejo.', `FemaleText_loc1`='하사관, 망원경을 빌려주세요.', `FemaleText_loc4`='中士，把你的望远镜借给我。', `FemaleText_loc5`='士官，把你的望遠鏡借我。', `FemaleText_loc7`='Sargento, préstame tu catalejo.' WHERE `ID`=22774;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 죄수의 눈앞에서 열쇠를 흔들어 보입니다.', `MaleText_loc4`='%s在囚犯面前得意地摇晃着钥匙。', `MaleText_loc5`='%s在囚犯的面前甩盪著一把鑰匙。', `MaleText_loc7`='%s balancea una llave frente al prisionero.' WHERE `ID`=22775;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부디 조심하게나, $r.$b$b앞서 왔던 이들처럼 죽고 싶지 않다면 말일세.', `MaleText_loc4`='脚下小心，$r。$b$b你绝不会是第一个死在这里的人。', `MaleText_loc5`='小心謹慎，$r。$b$b你不會是第一個死在這裡的人。', `MaleText_loc7`='Camina con cuidado, $r.$B$BNo serías el primero que muere aquí.' WHERE `ID`=22776;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갖고 싶으냐, 원숭아? 갖고 싶어?', `MaleText_loc4`='你想要吗，猴子？要不要啊？', `MaleText_loc5`='猴子，你想要嗎?想要嗎??', `MaleText_loc7`='¿Lo quieres, mono? ¿Lo quieres?' WHERE `ID`=22777;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈들의 악취에 구역질이 난다. 앵거보다 님만 아니었으면 내 손으로 직접 처치했을 텐데 말이야.', `MaleText_loc4`='你身上的臭味熏死我了。要不是为了安格博达女王，我早就杀了你。', `MaleText_loc5`='你身上的臭味讓我作嘔。要不是安格博妲，我一定會親手殺了你。', `MaleText_loc7`='Tu peste me pone enfermo. Si no fuera por Inquinoda, te mataría yo mismo.' WHERE `ID`=22778;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='심판의 날이 곧 다가온다. 너 같은 돌연변이는 끝장날 거다.', `MaleText_loc4`='清算之日即将来临。你这样的异端将被彻底消灭……', `MaleText_loc5`='清算的日子近了。像你這樣的畸形非死不可...', `MaleText_loc7`='El día del juicio se acerca. Las aberraciones como tú serán destruidas...' WHERE `ID`=22779;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미천한 족속아, 네 마을이 얼마나 더 버틸 수 있다고 생각하지? 머지않아 부서질 것이다...', `MaleText_loc4`='你觉着你的镇子还能撑多久？马上就完蛋啦……瞧着吧，小东西。', `MaleText_loc5`='你以為你的小鎮撐得了多久?很快就會被毀掉的...很快，小朋友。', `MaleText_loc7`='¿Cuánto más crees que podrá aguantar tu ciudad? Pronto será aplastada... Pronto, criaturita.' WHERE `ID`=22780;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 미천한 족속아, 무서워서 벌벌 떠는 상대를 어떻게 막겠다는 거냐?', `MaleText_loc4`='我倒要看看你们如何抑止内心的恐惧而奋起反抗，小家伙！', `MaleText_loc5`='你要怎麼對抗你最害怕的東西呢，小朋友?', `MaleText_loc7`='¿Cómo detendrás aquello que tanto temes, criaturita?' WHERE `ID`=22781;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 마음이 어둠에 물드는구나... 난 곧 심판을 받을 것이다... 발키르의 이름으로! 리치 왕의 이름으로!', `MaleText_loc4`='我心中的黑暗面正逐渐膨胀……我就要接受审判了……为了瓦格里！为了巫妖王！', `MaleText_loc5`='我的心越來越黑暗...很快的，我也會被審判...為了華爾琪!為了巫妖王!這一切都值得...', `MaleText_loc7`='Mi corazón se oscurece... Pronto seré juzgado... ¡Digno de los Val''kyr! ¡Digno del Rey Exánime!' WHERE `ID`=22782;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 생물이 암흑 속에서 빠져나와 그 모습을 드러냅니다!', `MaleText_loc4`='一只潜伏在阴影中的生物显身了！', `MaleText_loc5`='一個生物從幽影中浮現!', `MaleText_loc7`='¡Una criatura emerge de las sombras!' WHERE `ID`=22783;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멀리서 대포의 굉음이 들리고 포탄의 휘파람 같은 소리가 그 뒤를 따라 하늘에 울려퍼집니다.', `MaleText_loc4`='空中传来炮弹划过的声音，远处的火光忽隐忽现。', `MaleText_loc5`='遠方傳來砲火，接著就是砲彈劃過頭頂的聲響。', `MaleText_loc7`='En la distancia se oye el fuego de los cañones, seguido del silbante sonido de una bala de cañón que llega desde arriba.' WHERE `ID`=22784;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 얼라이언스 놈들, 끈질긴 것만은 인정해야겠어! 포세이큰 병사가 가득한 구축함에 뛰어들다니... 이건 자살행위나 마찬가지야.', `FemaleText_loc4`='这些联盟蛤蟆真是太讨厌了！居然还敢登上满员的被遗忘者驱逐舰……这真是我听过的最愚蠢的自杀方式。', `FemaleText_loc5`='這些聯盟爛貨真帶種!登上了滿載船員的被遺忘者驅逐艦...那是我從來沒有聽說過的自殺行動。', `FemaleText_loc7`='¡Estos soplagaitas de la Alianza son duros! Embarcarse en destructores tripulados por Renegados... eso sí que es comportamiento suicida.' WHERE `ID`=22785;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='허! 내가 승천하는 걸 막을 수 있다고 생각하나? 이제 누구도 나를 막을 수 없다!', `MaleText_loc4`='哈哈！就凭你也想阻止我完成升华仪式？没人有这个本事！', `MaleText_loc5`='哈!你以為這樣就能阻止我飛升嗎?沒有人能阻止我!', `MaleText_loc7`='¡Ja! ¿Pensabas interferir en mi ascensión? ¡Ya nada puede detenerme!' WHERE `ID`=22786;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈이 뭘 하려는지 내가 모르리라 생각하느냐? 네놈이 무슨 짓을 하고 다녔는지 못 본 줄 아느냐?', `MaleText_loc4`='你以为我不知道你想干什么吗？你以为我没有在观察着你的一举一动吗？', `MaleText_loc5`='你以為我不曉得你想幹嘛嗎?你以為我沒有監視你嗎?', `MaleText_loc7`='¿Crees que no sé lo que intentas hacer? ¿Crees que no te he estado observando?' WHERE `ID`=22787;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈은 나의 승천을 막을 수 없다, 하찮은 $r. 이제 죽어라!', `MaleText_loc4`='你不可能阻止我完成升华仪式，卑微的$r。去死吧！', `MaleText_loc5`='別想阻止我飛升，渺小的$r，受死吧!', `MaleText_loc7`='No detendrás mi ascensión, $gpequeño:pequeña:r; $r. ¡Es hora de morir!' WHERE `ID`=22788;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 네놈은 나를 이길 수 없어!', `MaleText_loc4`='不可能！你不可能击败我！', `MaleText_loc5`='不!你別想打敗我!', `MaleText_loc7`='¡No! ¡No me vencerás!' WHERE `ID`=22789;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저와 우리 자매 모두 그대를 환영한답니다, $r님.', `FemaleText_loc4`='我和姐妹们都欢迎您造访，$R。', `FemaleText_loc5`='我和姊妹們歡迎你，$r。', `FemaleText_loc7`='Mis hermanas y yo te damos la bienvenida, $r.' WHERE `ID`=22790;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안타깝구나, 하프단.', `FemaleText_loc4`='太不走运了，哈尔弗丹。', `FemaleText_loc5`='哈弗丹，真是不幸吶。', `FemaleText_loc7`='Qué mala suerte, Halfdan.' WHERE `ID`=22791;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네게는 승천할 자격이 없다, 하프단. 망각 속으로 사라져라!', `FemaleText_loc4`='哈尔弗丹，你没有资格获得升华。你的灵魂将坠入湮灭的深渊！', `FemaleText_loc5`='哈弗丹，我們發現你沒有飛升的資格。讓你的靈魂知道什麼是消亡吧!', `FemaleText_loc7`='Creemos que no eres digno de ascender, Halfdan. ¡Deja que tu alma conozca el olvido!' WHERE `ID`=22792;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적 함대를 상대로 실험했던 결과 보고서가 들어왔습니다!', `MaleText_loc4`='对敌军舰队的测试报告出来了，长官！', `MaleText_loc5`='長官，測試敵艦的報告進來了!', `MaleText_loc7`='¡Han llegado informes de la prueba de la flota enemiga, señor!' WHERE `ID`=22793;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기... 좋은 소식은 우리가 증원군을 물리쳤다는 것입니다.', `MaleText_loc4`='呃……好消息是增援部队撤退了。', `MaleText_loc5`='嗯...好消息是我們逼得援軍回頭了。', `MaleText_loc7`='Bueno... la buena noticia es que hemos obligado a los refuerzos a dar la vuelta.' WHERE `ID`=22794;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='역병이 그다지... 치명적이지 않았습니다. 하지만 메스꺼움, 불안감, 심한 복통 같은 증상을 유발했다고 보고되었습니다.', `MaleText_loc4`='这种药剂效力不是非常……强。但是，目前已知的有害效果包括晕眩、平衡感丧失和剧烈的胃痛。', `MaleText_loc5`='瘟疫不是那麼的...致命。然而，報告指出，有害效果包括了噁心、平衡失調和嚴重的胃痛。', `MaleText_loc7`='La peste no ha resultado del todo... fatal. Pero los informes acerca de los efectos dañinos incluyen nauseas, pérdida de equilibrio y dolor agudo de estómago.' WHERE `ID`=22795;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠습니다!', `MaleText_loc4`='是，长官！', `MaleText_loc5`='是，長官!', `MaleText_loc7`='¡Sí, señor!' WHERE `ID`=22796;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아. 내용이 뭔가? 사망자 수는 집계되었나?', `MaleText_loc4`='很好。那么结果如何呢？', `MaleText_loc5`='很好。有損失嗎?人員傷亡呢?', `MaleText_loc7`='Excelente. ¿De qué información disponemos? ¿Tenemos un recuento de cadáveres?' WHERE `ID`=22797;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니, 왜 말을 못하나? 나쁜 소식은 뭔가?', `MaleText_loc4`='直说吧！坏消息是什么？', `MaleText_loc5`='嗯，有話快說!壞消息是什麼?', `MaleText_loc7`='¡Venga, escúpelo! ¿Cuál es la mala noticia?' WHERE `ID`=22798;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경계하게, $n.$b$b아직 숲에서 벗어나지 못했으니...', `MaleText_loc4`='保持警惕，$n。$b$b我们还没有走出这片森林呢……', `MaleText_loc5`='保持清醒，$n。$b$b我們還沒出林子呢...', `MaleText_loc7`='Mantente alerta, $n.$B$BAún no estamos a salvo...' WHERE `ID`=22799;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='심한 복통?', `MaleText_loc4`='没有效果？', `MaleText_loc5`='腹痛如絞嗎?', `MaleText_loc7`='¿Dolor agudo de estómago?' WHERE `ID`=22800;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='심한 복통이라고 했나?!', `MaleText_loc4`='没有效果！！！？？？', `MaleText_loc5`='肚子痛到打滾嗎?', `MaleText_loc7`='¿DOLOR AGUDO DE ESTÓMAGO?' WHERE `ID`=22801;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 왕립 연금술 학회란 말이다! 고작 배탈 따위나 일으키는 게 우리의 임무라고 생각하나!', `MaleText_loc4`='我们是皇家药剂师协会的成员！药剂引起胃痛不在我们的工作范围之内！', `MaleText_loc5`='我們是皇家藥劑師學會!我們的工作描述裡面不包括引起肚子痛啦!', `MaleText_loc7`='¡Somos la Sociedad Real de Boticarios! ¡Provocar dolores de tripa no es parte de la descripción de nuestro trabajo!' WHERE `ID`=22802;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기는 덜떨어진 놈들만 있나? 내일 아침까지 새로운 역병 품종을 완벽하게 분석해서 보고하도록! 지금 당장 시작하게, 라비엔!', `MaleText_loc4`='你们都是业余的吗？明天早上，我要见到一份完整的分析报告！拉维恩，给我做事去！', `MaleText_loc5`='為什麼我身邊的全是菜鳥?我要新菌種的全面性分析，明天早上就要!快去吧，拉維安!', `MaleText_loc7`='¿Estoy rodeado de principiantes? ¡Quiero un análisis completo de la nueva cepa mañana por la mañana! ¡Ponte a ello, Ravien!' WHERE `ID`=22803;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='환영하네, 이방인. 도와줄 곳을 찾는다면 제대로 찾아왔네.$B$B죽은 자들이 깨어나 땅 위를 걸어다니고, 또한 배를 타고 바다를 건너 속속들이 도착하는 중이네. 이 협만은 우리에게도 더는 안전하지 않네. 곧 안전한 곳을 찾아 북쪽으로 이동해야 하네.', `MaleText_loc4`='你好，陌生人。如果你是在找一处用武之地，那么恭喜你，你找到了。$B$B那些亡者从坟墓中爬出来，在大地上游荡，并乘着船飘洋过海来到这里。峡湾的局势越来越严峻了，再这样下去，我们就不得不往北逃亡了。', `MaleText_loc5`='你好，陌生人。如果你正在尋找需要幫助的所在，那麼你來對地方了。$B$B死者甦醒，在大地之上行走，從大洋的另一頭乘船飄流至此。即便對我們來說，峽灣也變得太危險了。要不了多久，我們必須前往北邊尋找更安全的地方。', `MaleText_loc7`='Hola, $gforastero:forastera;. Si buscas un lugar necesitado de tu ayuda, no cabe duda de que lo has encontrado.$B$BLos muertos se levantan, caminan por la tierra, llegan en barcos desde el otro lado del gran océano. El fiordo se vuelve demasiado peligroso incluso para nosotros y pronto tendremos que ir hacia el norte en busca de tierras más seguras.' WHERE `ID`=22804;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신을 보호하고 도와드리겠습니다.$B$B다음은 어떻게 공격하실 겁니까?', `MaleText_loc4`='我是来此协助与保护你的。$B$B接下来我们要如何打击敌军呢？', `MaleText_loc5`='我來這裡幫助並護衛你的。$B$B下一步我們該如何打擊敵人?', `MaleText_loc7`='Estoy aquí para ayudar y defender.$B$B¿Cómo vamos a atacar al enemigo?' WHERE `ID`=22805;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='망원경을 빌려주십시오.', `MaleText_loc4`='望远镜借我用一下。', `MaleText_loc5`='請你把望遠鏡借給我。', `MaleText_loc7`='Préstame ese catalejo, por favor.', `FemaleText_loc1`='망원경을 빌려주세요.', `FemaleText_loc4`='望远镜借我用一下。', `FemaleText_loc5`='請你把望遠鏡借給我。', `FemaleText_loc7`='Préstame ese catalejo, por favor.' WHERE `ID`=22806;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가까이 오게, 젊은이. 내 귀는 예전 같지 않은데다 목소리를 높이고 싶지는 않네.', `FemaleText_loc4`='过来点，年轻人，我的耳朵已经不那么好用了，说话声音也不如以前洪亮了。', `FemaleText_loc5`='靠近點，年輕人;我的聽力不復當年，也沒辦法大聲說話了。', `FemaleText_loc7`='Acércate, joven, mis oídos ya no son lo que eran y no me gusta levantar la voz.' WHERE `ID`=22807;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 멍청한 몸뚱이야, 난 이쪽에 있다!', `MaleText_loc4`='我在这儿呢，你这蠢货！', `MaleText_loc5`='我在這裡，你這笨蛋!', `MaleText_loc7`='¡Estoy aquí, cuerpo imbécil!' WHERE `ID`=22808;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대장님, 아무래도 지휘관 계급장을 잃어버린 것 같습니다.', `MaleText_loc4`='上尉，我弄丢了指挥官徽记。', `MaleText_loc5`='上尉，我不知道怎麼地弄丟了我的指揮徽記。', `MaleText_loc7`='Capitán, he perdido mi insignia de mando.', `FemaleText_loc1`='대장님, 아무래도 지휘관 계급장을 잃어버린 것 같아요.', `FemaleText_loc4`='上尉，我弄丢了指挥官徽记。', `FemaleText_loc5`='上尉，我不知道怎麼地弄丟了我的指揮徽記。', `FemaleText_loc7`='Capitán, he perdido mi insignia de mando.' WHERE `ID`=22809;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알았네, 여기 하나 더 있네. 이번엔 잃어버리지 않도록 하게!', `MaleText_loc4`='好吧，再给你一枚。这次千万别再弄丢了！', `MaleText_loc5`='好極了，這裡有另外一個。別錯失這一個!', `MaleText_loc7`='Bien, aquí tienes otra. ¡Procura no perder esta!' WHERE `ID`=22810;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='애쉬토템 족장님, 주신 징표를 잃어버린 것 같습니다.', `MaleText_loc4`='灰烬图腾酋长，我弄丢了你给我的徽章。', `MaleText_loc5`='灰燼圖騰酋長，我弄丟了你給我的硬幣。', `MaleText_loc7`='Cabecilla Tótem de Ceniza, he perdido la muestra que me entregaste.', `FemaleText_loc1`='애쉬토템 족장님, 주신 징표를 잃어버린 것 같아요.', `FemaleText_loc4`='灰烬图腾酋长，我弄丢了你给我的徽章。', `FemaleText_loc5`='灰燼圖騰酋長，我弄丟了你給我的硬幣。', `FemaleText_loc7`='Cabecilla Tótem de Ceniza, he perdido la muestra que me entregaste.' WHERE `ID`=22811;
