UPDATE `locales_broadcast_text` SET `MaleText_loc1`='망할 풀로이 녀석! 대체 암호를 어디다 둔 거야!', `MaleText_loc4`='该死，普罗伊！你把密码表放到哪去了！', `MaleText_loc5`='可惡，普爾羅伊!你把密碼放哪了!', `MaleText_loc7`='¡Maldito seas, Pulroy! ¿Dónde has puesto esas claves?' WHERE `ID`=22817;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와주기를 하나 맥주를 권하길 하나... 드워프를 이렇게 버려두다니 연맹 녀석들이랑 마찬가지로군!', `MaleText_loc4`='就像这探险者协会一样把我一个人丢在这里，甚至连一口麦酒都没得喝！', `MaleText_loc5`='就像是協會丟下一個矮人既沒人幫忙又沒有酒喝!', `MaleText_loc7`='¡Típico de la Liga abandonar a un enano sin ayuda y sin cerveza!' WHERE `ID`=22818;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 그 많은 사람을 다 잃을 수가 있지?', `MaleText_loc4`='你怎么会让整个探险队都丢了性命？', `MaleText_loc5`='你是怎麼損失一整群人手的?', `MaleText_loc7`='¿Cómo se pierde un grupo entero de gente?' WHERE `ID`=22819;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디 어떤 녀석이 찾아왔나 볼까?', `MaleText_loc4`='看看这是谁来了。', `MaleText_loc5`='看看是誰加入遊戲了。', `MaleText_loc7`='Mira qué ha venido a jugar.', `FemaleText_loc1`='어떤 녀석이 왔나 보자꾸나.', `FemaleText_loc4`='看看这是谁来了。', `FemaleText_loc5`='看看是誰加入遊戲了。', `FemaleText_loc7`='Mira qué ha venido a jugar.' WHERE `ID`=22820;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벌써 며칠째 켈러의 병사들에게서 소식이 없군... 흠, 무소식이 희소식이겠지.', `MaleText_loc4`='这些天，凯勒的士兵都没带回什么消息……不过，没有消息就是最好的消息。', `MaleText_loc5`='凱勒的手下最近什麼也沒交給我...我想，沒消息就是好消息吧。', `MaleText_loc7`='Los soldados de Keller no me han traído nada desde hace días... Supongo que la ausencia de noticias es una buena noticia.' WHERE `ID`=22821;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈 따위는 영생을 누릴 수 없다!', `MaleText_loc4`='你的生命到此结束！', `MaleText_loc5`='你不會獲得什麼永恆的生命!', `MaleText_loc7`='¡No habrá vida eterna para ti!', `FemaleText_loc1`='네놈 따위는 영생을 누릴 수 없다!', `FemaleText_loc4`='你的生命到此结束！', `FemaleText_loc5`='你不會獲得什麼永恆的生命!', `FemaleText_loc7`='¡No habrá vida eterna para ti!' WHERE `ID`=22822;
