UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 종족은 세상을 좀먹는 쓰레기일 뿐이다!', `MaleText_loc4`='你的种族就是世界的污点！', `MaleText_loc5`='你的種族簡直就是這世界的疾病!', `MaleText_loc7`='¡Tu raza es una enfermedad en el mundo!', `FemaleText_loc1`='너희 종족은 세상을 좀먹는 쓰레기일 뿐이야!', `FemaleText_loc4`='你的种族就是世界的污点！', `FemaleText_loc5`='你的種族簡直就是這世界的疾病!', `FemaleText_loc7`='¡Tu raza es una enfermedad en el mundo!' WHERE `ID`=22824;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앗! 켈러 씨! 폐허에서 소식 없었나요? 아무런 전갈도 없었나요?', `MaleText_loc4`='天啊！凯勒！遗址那里的情况怎么样了？还是没消息吗？', `MaleText_loc5`='喂!凱勒!廢墟裡有傳來什麼消息嗎?任何消息??', `MaleText_loc7`='¡Oye! ¡Keller! ¿Se sabe algo de las ruinas? ¿Cualquier cosa?' WHERE `ID`=22825;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 조용하게 투덜거립니다.', `MaleText_loc4`='%s低声嘟囔着。', `MaleText_loc5`='%s氣喘吁吁地埋怨。', `MaleText_loc7`='%s murmura algo entre dientes.' WHERE `ID`=22826;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='휴... 맥소르프 씨, 그 폐허로 벌써 세 번도 더 구조대를 보냈지만 아무도 돌아오지 않았다고 이미 말하지 않았습니까. 전 지금 이 항구가 가라앉지 않고 잘 유지되도록 하는 일에 얼이 빠질 정도로 바쁘단 말입니다! 제발 작작 좀 하세요!', `MaleText_loc4`='我已经跟你说过很多次了，米科索夫。我已经派出至少三支救援队进入遗址了，而且一支都没有回来。我还要保证港口的正常运转呢！你马上从我面前消失！', `MaleText_loc5`='麥克索夫，我早就告訴過你了，我已經派了不下三組救援隊前進廢墟裡面而一個都沒回來。我為了將這座港口保持運作與完整而疲於奔命!所以你少來煩我!', `MaleText_loc7`='Ya te lo he dicho, McSorf. He enviado nada menos que tres equipos de rescate a las ruinas y ninguno ha regresado. ¡Estoy trabajando sin descanso para mantener este puerto a flote y de una sola pieza! ¡DÉJAME EN PAZ!' WHERE `ID`=22827;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='치료제가 효과 있었으면 좋겠네요.', `FemaleText_loc4`='只能祈祷治疗方案能生效了。', `FemaleText_loc5`='我只希望治療能起效用。', `FemaleText_loc7`='Espero que el tratamiento funcione.' WHERE `ID`=22828;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여러분을 모두 돌봐주기엔 의료 보급품이 너무 부족해요.', `FemaleText_loc4`='我根本没有能治疗你们的药品和器械。', `FemaleText_loc5`='我實在是沒有足夠的醫療用品來治療你們全部的人。', `FemaleText_loc7`='No tengo los suministros médicos que necesito para trataros a todos.' WHERE `ID`=22829;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='걱정하지 마세요. 이 야즈미나가 돌봐 드리죠.', `FemaleText_loc4`='别担心，士兵。亚米娜会照顾好你的。', `FemaleText_loc5`='別擔心，士兵。雅茲米娜會來照顧你。', `FemaleText_loc7`='No te preocupes, soldado. Yazmina cuidará de ti.' WHERE `ID`=22830;
