UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스 증원군을 차단해야 하니 박쥐를 태워주십시오.', `MaleText_loc4`='我需要搭乘巨型蝙蝠去拦截联盟援军。', `MaleText_loc5`='我需要一頭騎乘用蝙蝠，攔截聯盟的援軍。', `MaleText_loc7`='Necesito un murciélago de montar para interceptar los refuerzos de la Alianza.', `FemaleText_loc1`='얼라이언스 증원군을 차단해야 하니 박쥐를 태워주세요.', `FemaleText_loc4`='我需要搭乘巨型蝙蝠去拦截联盟援军。', `FemaleText_loc5`='我需要一頭騎乘用蝙蝠，攔截聯盟的援軍。', `FemaleText_loc7`='Necesito un murciélago de montar para interceptar los refuerzos de la Alianza.' WHERE `ID`=22832;
