UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 액체는 뭐지? 냄새가 고약해!', `MaleText_loc4`='这液体……真是难闻！', `MaleText_loc5`='這液體...它冒煙了!', `MaleText_loc7`='¡Ese líquido... apesta!', `FemaleText_loc1`='무슨 액체지... 악취가 나!', `FemaleText_loc4`='这液体……真是难闻！', `FemaleText_loc5`='這液體...它冒煙了!', `FemaleText_loc7`='¡Ese líquido... apesta!' WHERE `ID`=22837;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘을 보여주마... 한꺼번에.', `MaleText_loc4`='现在，让我来告诉你们什么叫……数量优势。', `MaleText_loc5`='現在，讓我來告訴你們什麼叫數量優勢...', `MaleText_loc7`='Les demostraré fuerza... con números.' WHERE `ID`=22838;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아웃랜드에서는 다크문 축제를 테로카르 숲에 엽니다. 저희는 샤트라스 바로 남쪽에 천막을 칠 겁니다!', `MaleText_loc4`='当暗月马戏团开始展览的时候，他们会出现在泰罗卡森林。我们会在沙塔斯城南边搭建帐篷！', `MaleText_loc5`='暗月馬戲團在外域的泰洛卡森林開張的時候，我們會在撒塔斯城的南方搭建我們的帳篷!', `MaleText_loc7`='Cuando la Feria de la Luna Negra esté abierta, se celebrará en el Bosque de Terokkar en Terrallende. ¡Estaremos montando nuestras tiendas justo al sur de la Ciudad de Shattrath!' WHERE `ID`=22839;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 아웃랜드의 샤트라스 바로 남쪽, 테로카르 숲에서 다크문 축제가 열리고 있습니다. 꼭 구경 가세요!', `MaleText_loc4`='暗月马戏团正在外域的泰罗卡森林开张，就在沙塔斯城的南边。走过路过不要错过！', `MaleText_loc5`='暗月馬戲團到外域的泰洛卡森林來了，就在撒塔斯城的南邊。走過路過不要錯過!', `MaleText_loc7`='La Feria de la Luna Negra se celebra ahora en el Bosque de Terokkar, en Terrallende, justo al sur de Ciudad de Shattrath. ¡No te lo pierdas!' WHERE `ID`=22840;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신과 함께 일해 영광이었습니다.', `MaleText_loc4`='能与你一起战斗是我的荣幸。', `MaleText_loc5`='能為你服務是我的榮幸。', `MaleText_loc7`='Ha sido un placer servir junto a ti.' WHERE `ID`=22841;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신과 함께 싸울 수 있어 영광이었습니다.', `MaleText_loc4`='与你并肩战斗对我来说是莫大的荣誉。', `MaleText_loc5`='和你並肩作戰是我的榮幸。', `MaleText_loc7`='Ha sido un honor luchar a tu lado.' WHERE `ID`=22842;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련받은 역병사냥개가 북쪽에서 풍겨오는 냄새를 맡고 그곳으로 달려갈 자세를 잡습니다.', `MaleText_loc4`='猎犬似乎闻到了北边有什么东西，正全速冲向气味的发源地。', `MaleText_loc5`='獵犬似乎發現了北邊的氣味，準備朝源頭跑去。', `MaleText_loc7`='El can parece percibir un rastro desde el norte y se prepara para correr hacia su origen.' WHERE `ID`=22843;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사냥개가 목표 지점에 도착했을 때 위쪽에서 무슨 소리가 들리자 깜짝 놀라 도망치려고 합니다.', `MaleText_loc4`='冲到目的地后，猎犬却变得躁动不安，似乎想要逃窜。看来是被那股气味给唬到了。', `MaleText_loc5`='當抵達了目的地之後，獵犬被前頭的聲響嚇得準備要逃跑。', `MaleText_loc7`='Al llegar a su destino el can se asusta por un ruido y parece listo para huir.' WHERE `ID`=22844;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='역병을 써먹을 데는 많은데 시간이 부족하구나!', `MaleText_loc4`='药剂的用途如此广泛，我们得加紧研究！', `MaleText_loc5`='瘟疫的用途真多，可惜時間太少了!', `MaleText_loc7`='¡Tantos usos para la peste y tan poco tiempo!' WHERE `ID`=22845;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지난번 실험에서 거의 회복되지 않았나? 한 번 더 실험해보지...', `MaleText_loc4`='你是不是已经完全恢复了？我们再试一次……', `MaleText_loc5`='你已經從最後一次復原了嗎?那我們再試一次吧...', `MaleText_loc7`='¿Ya casi te has recuperado de la última vez? Volvamos a intentarlo...' WHERE `ID`=22846;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠, 어떻게든 압력을 좀 낮춰야겠군...', `MaleText_loc4`='嗯，要略微降低压力才行……', `MaleText_loc5`='嗯，壓力一定因為某個原因減輕了...', `MaleText_loc7`='Hmm... Hay que aliviar un poco la presión...' WHERE `ID`=22847;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실험 대상이 아직도 숨을 쉬고 있군. 더 투여해야겠어...', `MaleText_loc4`='实验体仍在呼吸。再来一份剂量……', `MaleText_loc5`='目標生物還在呼吸，需要額外的劑量...', `MaleText_loc7`='El sujeto aún respira. Es hora de otra dosis...' WHERE `ID`=22848;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 짧은 시간에 끝내다니 놀랍군. 한 번 더 해봐야겠어...', `MaleText_loc4`='能在这么短的时间内取得这样的进展已经很了不起了。我们再试一次……', `MaleText_loc5`='這麼短時間內就把這東西準備好了，真令人訝異，讓我們再試一次吧...', `MaleText_loc7`='Es una maravilla que hayamos logrado montar esto en tan poco tiempo. Volvamos a intentarlo...' WHERE `ID`=22849;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기분이 어떤지 말해보게.', `MaleText_loc4`='告诉我你感觉怎么样。', `MaleText_loc5`='告訴我這讓你感覺如何?', `MaleText_loc7`='Dime cómo te hace sentir esto.' WHERE `ID`=22850;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='굉장히 튼튼한 실험체로군. 그럼 한 번 더...', `MaleText_loc4`='实验体的生命力还真是顽强啊。加大剂量……', `MaleText_loc5`='好個健壯的實驗品。那麼，再來一個吧...', `MaleText_loc7`='Tenemos un sujeto muy robusto. Una vez más, entonces...' WHERE `ID`=22851;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 근처에 있는 밸브를 돌리고 손에 바늘을 든 채 철창으로 시선을 돌립니다.', `MaleText_loc4`='%s拧动阀门，专注地盯着笼子，手中握着一支羽毛笔。', `MaleText_loc5`='%s轉動了附近的活門，將注意力轉移到牢籠中，手中拿著鵝毛筆。', `MaleText_loc7`='%s gira una válvula cercana y dirige su atención a la jaula, pluma en mano.' WHERE `ID`=22852;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공포의 왕께서 지켜보고 계시다! 오늘 싸움터에서 전사할 수 있기를! 자비로운 심판이 내려지기를!', `MaleText_loc4`='恐惧之王已经向我们致意了！祈祷吧！我们今天或许将战死沙场！祈祷吧！最终的审判已经来临！', `MaleText_loc5`='恐懼之王向你問候!祈禱今天就是我們戰死的日子!祈禱審判對我們有利!', `MaleText_loc7`='¡El Rey del Terror envía sus respetos! ¡Rezad para que hoy sea el día en que fallezcamos en la batalla! ¡Rezad para que el juicio sea favorable!' WHERE `ID`=22853;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전부 다 훌륭하군요. 딱 하나만 고르려니 쉽지 않네요.', `FemaleText_loc4`='这些都非常不错。非要从中选一个的话，真有点难以做决定。', `FemaleText_loc5`='這些都很傑出。很難從裡面只挑出一個來。', `FemaleText_loc7`='Todos estos son excelentes. Va a ser difícil elegir solo uno.' WHERE `ID`=22854;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이게 좋을 것 같아요. 이제 조각을 해야겠어요. 쉬운 작업은 아닐 거예요. 난 설인 암컷이 짝짓기할 때 내는 소리가 어떤지도 모른다 말이에요!', `FemaleText_loc4`='很好，我找到合适的号角啦。现在我要开始雕刻了，这恐怕会很难。我根本没听过雌雪人的叫声！', `FemaleText_loc5`='我想我已經找到能用的，而我要開始雕刻的工作了。我想這不大容易，我根本不知道母雪人求偶的叫聲聽起來是什麼!', `FemaleText_loc7`='Creo que he encontrado el que usaré. Ahora tengo que comenzar a grabarlo. No creo que vaya a ser fácil. ¡Ni siquiera sé como es la llamada de apareamiento de la hembra yeti!' WHERE `ID`=22855;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='기본적으로는 거의 다 조각했지만, 더 세밀히 조각하기 전에 검사 좀 해봐야겠어요. 도와주실 수 있나요, $n?', `FemaleText_loc4`='我已经把大部分基础图案雕刻好了，在完成雕刻之前需要测试一下。你愿意帮我测试吗，$n？', `FemaleText_loc5`='我將最基礎的雕刻工作搞定了，而再我繼續之前，我得先測試過才行。你願意幫我這件事嗎，$n?', `FemaleText_loc7`='Tengo la mayoría del grabado hecho, pero no puedo continuar sin haberlo probado. ¿Quieres echarme una mano con eso, $n?' WHERE `ID`=22856;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공포의 왕께 내 생명을 바치겠다!', `MaleText_loc4`='恐惧之王万岁！', `MaleText_loc5`='為了恐懼之王而生!', `MaleText_loc7`='¡Mi vida por el Rey del Terror!', `FemaleText_loc1`='공포의 왕께 내 생명을 바치리라!', `FemaleText_loc4`='恐惧之王万岁！', `FemaleText_loc5`='為了恐懼之王而生!', `FemaleText_loc7`='¡Mi vida por el Rey del Terror!' WHERE `ID`=22857;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='각오는 돼 있습니다, 주인님!', `MaleText_loc4`='牺牲生命也在所不辞！领主阁下！', `MaleText_loc5`='我們隨時準備好赴死，大人!', `MaleText_loc7`='¡Estoy listo para morir, mi señor!', `FemaleText_loc1`='각오는 돼 있습니다, 주인님!', `FemaleText_loc4`='牺牲生命也在所不辞！领主阁下！', `FemaleText_loc5`='我們隨時準備好赴死，大人!', `FemaleText_loc7`='¡Estoy lista para morir, mi señor!' WHERE `ID`=22858;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자를 막아내겠습니다, 주인님!', `MaleText_loc4`='我们马上就会消灭这些入侵者，主上。', `MaleText_loc5`='大人，入侵者會被擋下的。', `MaleText_loc7`='Todo aquel que se entrometa será detenido, mi señor.', `FemaleText_loc1`='침입자를 막아내겠습니다, 주인님!', `FemaleText_loc4`='我们马上就会消灭这些入侵者，主上。', `FemaleText_loc5`='大人，入侵者會被擋下的。', `FemaleText_loc7`='Todo aquel que se entrometa será detenido, mi señor.' WHERE `ID`=22859;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 중 누군가는 오늘 승천할 것이다.', `MaleText_loc4`='今天，我们中的一员将得到升华。', `MaleText_loc5`='就在今天，我們之中有人能夠飛升。', `MaleText_loc7`='Uno de nosotros ascenderá hoy.', `FemaleText_loc1`='우리 중 누군가는 오늘 승천할 것이다.', `FemaleText_loc4`='今天，我们中的一员将得到升华。', `FemaleText_loc5`='就在今天，我們之中有人能夠飛升。', `FemaleText_loc7`='Uno de nosotros ascenderá hoy.' WHERE `ID`=22860;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 중 누군가는 오늘 승천하리라.', `MaleText_loc4`='今天，我们中的一员将得到升华。', `MaleText_loc5`='就在今天，我們之中有人能夠飛升。', `MaleText_loc7`='Uno de nosotros ascenderá hoy.', `FemaleText_loc1`='우리 중 누군가는 오늘 승천하리라.', `FemaleText_loc4`='今天，我们中的一员将得到升华。', `FemaleText_loc5`='就在今天，我們之中有人能夠飛升。', `FemaleText_loc7`='Uno de nosotros ascenderá hoy.' WHERE `ID`=22861;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발키르가 우리 곁에 있다, 형제자매들이여! 리치 왕을 위해 모든 것을 희생하는 자에게 영광이 있으리라!', `MaleText_loc4`='瓦格里就在我们身边，兄弟们，姐妹们！那些为巫妖王牺牲的人将得到荣光！', `MaleText_loc5`='華爾琪與我們同在，兄弟姊妹們!榮耀只屬於全心奉獻給巫妖王的人!', `MaleText_loc7`='¡Las Val''kyr nos rodean, hermanos y hermanas! ¡La gloria es para aquellos que lo sacrifican todo por el Rey Exánime!' WHERE `ID`=22862;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='토르발트의 아들 군나르가 왔다! 죽을 준비나 해둬라!', `MaleText_loc4`='贡纳·索瓦德森在此！拿命来！', `MaleText_loc5`='古拿，索瓦德之子，已經來了!準備好迎接你的死期吧!', `MaleText_loc7`='¡Gunnar, hijo de Thorvard, ha llegado! ¡Prepárense para enfrentarse a su final!' WHERE `ID`=22863;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잉그바르 님께서 이 벌레들을 해치울 용기수를 보내셨다! 놈들은 곧 진정한 브리쿨 군대와 마주하게 될 것이다!', `MaleText_loc4`='因格瓦尔已经派出龙骑兵去消灭那些蝼蚁了！很快他们就将面临觉醒的维库军团的毁灭性打击！', `MaleText_loc5`='因格瓦派了他的龍騎士空襲了那些臭蟲!要不了多久，他們將要面對甦醒的維酷大軍!', `MaleText_loc7`='¡Ingvar envía a sus jinetes de dragones para que se abalancen sobre estos insectos! ¡Pronto se enfrentarán a la renovada fuerza de los vrykuls!' WHERE `ID`=22864;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘껏 싸워라, 형제들이여! 전쟁의 메아리로 우리 혈족을 깨우자!', `MaleText_loc4`='努力战斗，兄弟们！用战斗的回响让同胞们觉醒吧！', `MaleText_loc5`='弟兄們，奮勇作戰!用戰爭的回響喚醒我們沉睡的同胞!', `MaleText_loc7`='¡Luchad con fuerza, hermanos! ¡Despertad a nuestros hermanos que duermen con los ecos de la guerra!' WHERE `ID`=22865;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='Sacrifice event triggered - beginning countdown...', `MaleText_loc4`='献祭仪式启动——倒计时开始……', `MaleText_loc5`='啟動獻祭事件 - 開始倒數...', `MaleText_loc7`='Evento de sacrificio activado – comenzando la cuenta atrás...' WHERE `ID`=22866;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='윈터스코른에 대적하는 놈들은 갈기갈기 찢어놓을 것이다!', `MaleText_loc4`='斯克恩的敌人，你们很快就会被撕成碎片！', `MaleText_loc5`='溫特斯考恩的敵人，你們將會被撕成碎片!', `MaleText_loc7`='¡Enemigos de los Inbjerskorn, os arrancaremos extremidad tras extremidad!' WHERE `ID`=22867;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='브리쿨의 보금자리에서 이놈들을 몰아내라!', `MaleText_loc4`='把这些蝼蚁赶出维库人的家园！', `MaleText_loc5`='將這個人渣從維酷的家園趕出去!', `MaleText_loc7`='¡Sacad a esta basura de la tierra de los vrykuls!' WHERE `ID`=22868;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악! 제발 그만 뿌려!', `MaleText_loc4`='啊！不要再喷了！', `MaleText_loc5`='啊!別再噴了!', `MaleText_loc7`='¡ARGH! ¡Otra vez con el pulverizador no!' WHERE `ID`=22869;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 짓을... 아악!', `MaleText_loc4`='那是什……啊！', `MaleText_loc5`='那是什 - 啊!', `MaleText_loc7`='¿Qué es ese ru--? ¡Agh!' WHERE `ID`=22870;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='브란의 수염이여, 제발 그만해!', `MaleText_loc4`='以布莱恩胡子的名字，停！', `MaleText_loc5`='布萊恩的鬍子啊，快停手!', `MaleText_loc7`='La barba de Brann, ¡PARA!' WHERE `ID`=22871;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드워프가 철창 속에서 기침을 하고 뜻 모를 말을 중얼거리며 덜덜 떱니다.', `MaleText_loc4`='关在笼里的矮人一面咳嗽，一面打喷嚏，全身都在颤抖。', `MaleText_loc5`='這名矮人在牢籠中一面咳嗽、吐痰，還一面發抖。', `MaleText_loc7`='El enano tose, esputa y tiembla en la jaula.' WHERE `ID`=22872;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='철창 속에 갇힌 드워프에게서 낮고 절망적인 신음만이 새어 나옵니다.', `MaleText_loc4`='笼中的矮人发出低沉而绝望的呻吟。', `MaleText_loc5`='被關住的矮人發出一陣低沉而沮喪的哀號。', `MaleText_loc7`='El enano enjaulado deja escapar un grave gemido de desesperación.' WHERE `ID`=22873;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 우리 안에서 힘없이 창살을 흔듭니다.', `MaleText_loc4`='%s无力地摇晃着笼子的栏杆。', `MaleText_loc5`='%s孱弱的搖晃著牢籠的欄杆。', `MaleText_loc7`='%s agita débilmente los barrotes de la jaula.' WHERE `ID`=22874;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 다시 우리 창살 쪽으로 낙심한 듯 힘없이 쓰러집니다.', `MaleText_loc4`='%s沮丧地靠在笼子的栏杆上。', `MaleText_loc5`='%s沮喪的倒向牢籠的欄杆。', `MaleText_loc7`='%s se deja caer abatido contra los barrotes.' WHERE `ID`=22875;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈이 내 저녁 식사를 방해한 것이냐? 네놈 짓이냐?', `MaleText_loc4`='你就是那个打扰我吃晚餐的家伙吗？是你吗？', `MaleText_loc5`='是「你」打斷我的晚餐嗎?嗯，不是嗎?', `MaleText_loc7`='¿Eres TÚ quien ha interrumpido mi cena? ¿Lo eres?' WHERE `ID`=22876;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='설인 암컷치고는 너무 못생기고 왜소하다 싶었다! 감히 나를 화나게 하다니...', `MaleText_loc4`='你也算是雌雪人吗？又丑又不丰满！你快让我抓狂了……', `MaleText_loc5`='妳又醜又瘦，不夠格當一個母雪人!而且妳把我給惹火了...', `MaleText_loc7`='¡Eres demasiado fea y flaca para ser una hembra yeti! Y ahora me estás enfadando...' WHERE `ID`=22877;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신을 바라보는 게 썩 기분 좋지만은 않군요!$B$B할 일이 많은데 시간이 없단 말이에요.', `FemaleText_loc4`='真高兴见到你！$B$B要做的工作还有很多，我们的时间偏偏不多了。', `FemaleText_loc5`='看到你我一點都不開心!$B$B還有工作要完成，而且時間不多了。', `FemaleText_loc7`='¡Cómo me alegro de verte!$B$BHay trabajo que hacer y no tenemos demasiado tiempo.' WHERE `ID`=22878;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맥주통 수호대 표시를 교환하고 싶습니다...', `MaleText_loc4`='我要兑换酒桶保卫者的戳记……', `MaleText_loc5`='我有酒桶保管者印記可以兌換...', `MaleText_loc7`='Tengo marcas de protector de barril para canjear...', `FemaleText_loc1`='맥주통 수호대 표시를 교환하고 싶어요...', `FemaleText_loc4`='我要兑换酒桶保卫者的戳记……', `FemaleText_loc5`='我有酒桶保管者印記可以兌換...', `FemaleText_loc7`='Tengo marcas de protector de barril para canjear...' WHERE `ID`=22879;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나한테 뭘 원하는 거지?', `MaleText_loc4`='你想让我做什么？', `MaleText_loc5`='你要我做什麼?', `MaleText_loc7`='¿Qué quieres de mí?' WHERE `ID`=22880;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 풀어줘, 이 겁쟁이들아! 내가 드워프 맛을 아주 똑똑히 보여줄 테니!', `MaleText_loc4`='让我出来，懦夫！老子要让你知掉矮人的厉害！', `MaleText_loc5`='快放了我，懦夫!讓你們瞧瞧矮人是用什麼做成的!', `MaleText_loc7`='¡Soltadme, cobardes! ¡Os enseñaré de qué estamos hechos los enanos!' WHERE `ID`=22881;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마을 사람들에게 무슨 짓을 한 거냐?!', `MaleText_loc4`='你想对村民们做什么！？', `MaleText_loc5`='你對村子裡的人做了些什麼!?', `MaleText_loc7`='¿Qué han hecho con la gente de este poblado?' WHERE `ID`=22882;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고르스는 죽음이 두렵지 않다! 포세이큰이 나를 다시 꼬매줄 거다.', `MaleText_loc4`='戈斯从来不怕战死。被遗忘者只要把我重新拼起来就行了。', `MaleText_loc5`='葛司不擔心被殺。他們被遺忘者可以把我再拼湊回來。', `MaleText_loc7`='Gorth no tiene miedo a morir. Los Renegados me volverán a montar.' WHERE `ID`=22883;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고르스는 가끔 혼란스럽다. 고르스는 사람을 아주 잘 죽여서 부대장이 되었다. 그런데 이제는 고르스가 죽이러 나갈 일이 없다!', `MaleText_loc4`='戈斯有时候也很迷茫。戈斯是个好杀手，所以升到了中士。但戈斯很不习惯没有东西杀的日子！', `MaleText_loc5`='葛司有的時候很疑惑。葛司很會殺人，所以葛司當上了中士。可是現在葛斯沒人可以殺了!', `MaleText_loc7`='A veces Gorth está confuso. A Gorth se le da bien matar gente, así que a Gorth lo hacen sargento. ¡Pero ahora Gorth ya no puede matar a nadie!' WHERE `ID`=22884;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='브리쿨은 우리보다 더 크고 힘도 세다. 하지만, 우리가 더 잘생겼다!', `MaleText_loc4`='维库人身材高大，也比我们强壮。但！我们比他们长得帅！', `MaleText_loc5`='維酷人比我們還要更高大更強壯。不過我們比較帥!', `MaleText_loc7`='Vrykuls son más grandes y fuertes que nos. ¡Pero nos es más guapo!' WHERE `ID`=22885;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='블라스텐하이머 5000 초특급 대포는 사람을 쏘아 올리는 멋진 장치예요. 거의 용이 날아가는 속도로 탑승자를 발사하는 이 대포는 블라스텐하이머가의 자랑이자 기쁨으로, 그들의 위대한 업적을 전 세계에 알렸죠!$B$B새처럼 자유롭게 하늘로 날아오르고 싶다면 샤트라스에 있는 빛의 정원으로 가서 맥시마 블라스텐하이머를 찾아보세요. 그녀가 벽 너머 작은 연못으로 당신을 발사해 줄 거예요!', `FemaleText_loc4`='雷管5000型超级大炮是一种代表世界最尖端技术水平的单人发射装置，它能以龙的速度将人发射出去。发明该设施的地精家族是家喻户晓的航空领域先驱，这种超级大炮已经成为了家族的荣耀！$B$B如果你想象鸟儿一样在空中翱翔，就去沙塔斯城的圣光广场找玛克希玛·雷管吧。她会把你发射到城外的小池塘去！', `FemaleText_loc5`='衝擊者5000型超級大砲是一種最先進的單人拋射儀器。他以龍的速度運送裝載，這個大砲是布萊頓海默家的驕傲與喜悅，他們的航空與彈藥技術是出了名的!$B$B如果你想和鳥一樣在空中翱翔，就去撒塔斯城的聖光露臺找瑪克希瑪·布萊頓海默。她會在城牆外一個小池塘的目標地向你瞄準!', `FemaleText_loc7`='El Ultracañón Pimpampum 5000 es un artefacto único para el lanzamiento de personas que proyecta su carga a una velocidad cercana a la del vuelo de un dragón. Este cañón es el orgullo de la familia Pimpampum, conocida en todo el mundo por sus derroches en el campo de la aeronáutica.$B$BSi quieres probar el cañón y volar como un pájaro, busca a Maxima Pimpampum en el Bancal de la Luz en la Ciudad de Shattrath. Te lanzará a algún lugar desde un pequeño estanque fuera de los muros de la ciudad.' WHERE `ID`=22886;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우릴 돕는 임무를 띤 사람이라면 이럴 때 어떤 행동을 할까요?', `MaleText_loc4`='如何才能得到帮助呢？', `MaleText_loc5`='如果有個人希望附近的人能幫忙，他該怎麼做呢?', `MaleText_loc7`='¿Qué tiene que hacer un chico para conseguir un poco de ayuda por aquí?' WHERE `ID`=22887;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='광산에 나타난 거대한 설인 얘기를 분명히 들으셨을 텐데요?', `MaleText_loc4`='你知道矿洞里有只巨型雪人，对不对？', `MaleText_loc5`='你知道礦坑裡有個巨型雪人，對吧?', `MaleText_loc7`='Ya sabes lo del yeti gigante de la mina, ¿verdad?' WHERE `ID`=22888;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='설인이라고요, 설인! 덩치 크고 덥수룩한 데다 무시무시한 뿔이 달린 짐승 말이에요!', `MaleText_loc4`='那是雪·人！雪人啊！你到底知不知道啊，就是那种又大又臭还长着角的大怪兽！', `MaleText_loc5`='雪-人。雪人!你明白吧，就是那隻巨大、頭上還有血紅觸角的毛茸茸東西?', `MaleText_loc7`='Es Y-E-T-I. ¡Yeti! Ya sabes, esas cosas gigantes y peludas con cuernos ensangrentados.' WHERE `ID`=22889;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그놈 때문에 부하들이 광산을 확장하지 못하고 있어요. 그곳의 광석은 얼라이언스에게 꼭 필요한데 말입니다!', `MaleText_loc4`='它让我们的矿工完全没法开采矿石。联盟急需那种矿石！', `MaleText_loc5`='它不斷的阻撓我的人手開拓礦坑。聯盟需要礦石!', `MaleText_loc7`='Esta impidiendo que mis chicos amplíen la mina. ¡La Alianza necesita esa mena!' WHERE `ID`=22890;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 말 안 들립니까?! 얼라이언스의 진군을 방해한 죄로 아담스 경비대장님이 당신네를 매질하면 내가 그 모습을 두 눈으로 똑똑히 봐 주겠습니다!', `MaleText_loc4`='你聋了吗？你这是在拖延联盟的军事行动，如果亚当斯上尉为此责罚你的话，我也脱不了干系！', `MaleText_loc5`='你聾啦?!等亞當斯隊長因為你妨害了聯盟的利益鞭打你的時候，我會在現場的!', `MaleText_loc7`='¿Estás sordo? ¡Estaré allí cuando el capitán Adams te esté azotando por retrasar el avance de la Alianza!' WHERE `ID`=22891;
