UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 존스, 방금 그거 들었어? 저쪽에서 무슨 소리가 들린 것 같은데...', `MaleText_loc4`='你听见什么没有，琼斯？我好像……听到了什么东西……在那边……', `MaleText_loc5`='瓊斯，你聽見了什麼嗎?我似乎聽見那裏有什麼聲音...', `MaleText_loc7`='¿Oyes algo, Jones? Me parecía haber oído algo, justo allí...', `FemaleText_loc1`='들었어요, 존스? 저쪽에서 무슨 소리가 들린 것 같은데요...', `FemaleText_loc4`='你听见什么没有，琼斯？我好像……听到了什么东西……在那边……', `FemaleText_loc5`='瓊斯，你聽見了什麼嗎?我似乎聽見那裏有什麼聲音...', `FemaleText_loc7`='¿Oyes algo, Jones? Me parecía haber oído algo, justo allí...' WHERE `ID`=22897;
