UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$C|1이여;여;, 정말 떠날 준비가 다 된 건가? 잠시만 기다리게.', `MaleText_loc4`='$C，你做好动身的准备了？稍等。', `MaleText_loc5`='$C，你確定準備好要離開了嗎?多待一會兒吧。', `MaleText_loc7`='$C, ¿estás $gseguro:segura; de que estás $gpreparado:preparada; para partir? Tómate un momento.' WHERE `ID`=22904;
