UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그녀는 역시 한결같이 아름다워! 그럼 나 대신 그녀에게 내 사랑을 전해주게, $n.', `MaleText_loc4`='她依然那么美丽！$n，拜托你转告我的话！', `MaleText_loc5`='她從未如此的美麗!拜託你，$n，為了我將這句話告訴她!', `MaleText_loc7`='¡Está más hermosa que nunca! ¡Por favor, $n, díselo de mi parte!' WHERE `ID`=22906;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사랑해요, 내 소중한 이레나.', `MaleText_loc4`='我爱你，亲爱的伊雷娜。', `MaleText_loc5`='我愛妳，我珍愛的艾琳娜。', `MaleText_loc7`='Te quiero, mi preciosa Irena.' WHERE `ID`=22907;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이레나가 조용히 흐느낍니다.', `FemaleText_loc4`='伊雷娜低声呜咽着。', `FemaleText_loc5`='艾琳娜輕聲哭泣著。', `FemaleText_loc7`='Irena llora suavemente.' WHERE `ID`=22908;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간이 끝났다! 실패했으니... 나머지 포로들은 이제 죽을 거다.', `MaleText_loc4`='时间到了！你失败了……剩下的囚犯很快就会化为灰烬。', `MaleText_loc5`='時間到!你失敗了...所有剩下的囚犯都要被燒死。', `MaleText_loc7`='¡Se acabó el tiempo! Has fracasado... Los prisioneros que quedaban han sido AHUMADOS.' WHERE `ID`=22909;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기로 여행하는 동안 비틀린 숲과 샬레르브론에 너무 가까이 갔던 게 실수였던 모양이네.', `MaleText_loc4`='或许我们选择靠近裂木森林和亚勒伯龙的道路是个错误。', `MaleText_loc5`='也許來到這個太靠近裂木森林和夏勒布隆的地方，是個天大的錯誤。', `MaleText_loc7`='Quizá fue un error viajar tan cerca de El Bosque Hendido y Gjalerbron para llegar aquí.' WHERE `ID`=22910;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='4명의 모든 포로를 구출했다! You are teh uber!', `MaleText_loc4`='四名囚犯都得救啦！你很强大！', `MaleText_loc5`='四個囚犯全部都獲救了!你是最棒的!', `MaleText_loc7`='¡Los cuatro prisioneros salvados! ¡Eres el mejor!' WHERE `ID`=22911;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이리 오십시오, 영웅이여. 빛이 우리를 인도하고 보호할 것입니다.', `MaleText_loc4`='来吧，英雄。圣光将指引我们前进并一路保护我们。', `MaleText_loc5`='來吧，英雄。聖光將會引導並保護我們。', `MaleText_loc7`='Ven, héroe. La Luz nos guiará y protegerá.' WHERE `ID`=22912;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛의 눈부신 심판을 받아라, 악마야!', `MaleText_loc4`='来面对圣光的审判吧，恶魔！', `MaleText_loc5`='面對聖光炫目的審判吧，惡魔!', `MaleText_loc7`='¡Afronta el cegador juicio de la Luz, demonio!' WHERE `ID`=22913;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='차가운 어둠으로 돌아가라!', `MaleText_loc4`='滚回寒冷的黑暗中去吧！', `MaleText_loc5`='滾回你那冰冷的黑暗之中!', `MaleText_loc7`='¡Vuelve a la fría oscuridad!' WHERE `ID`=22914;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 태어난 지옥으로 돌려보내 주마!', `MaleText_loc4`='我要把你重新打回地狱里去！', `MaleText_loc5`='我會將你送回你原來的地獄!', `MaleText_loc7`='¡Te devolveré al infierno que te engendró!' WHERE `ID`=22915;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 이룰론 트루블레이드 경의 곁에 성스러운 유물을 놓습니다.', `MaleText_loc4`='%s将神圣的古器放在伊鲁伦·图布雷勋爵身旁。', `MaleText_loc5`='%s將神聖法器放在埃盧隆·真刃領主身邊。', `MaleText_loc7`='%s coloca el artefacto sacro junto a Lord Irulon Filoveraz.' WHERE `ID`=22916;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 임무의 시작과 함께 내 임무는 끝났습니다, 이룰론 님. 이제 작별이군요. 빛이 인도하시기를.', `MaleText_loc4`='伊鲁伦，我的任务完成了，接下来一切都交给你了。再见，愿圣光指引你前进的道路。', `MaleText_loc5`='厄盧隆，當我的衝鋒結束，就輪到你了。再會，願聖光指引你。', `MaleText_loc7`='Mi carga acaba donde comienza la tuya, Irulon. Adiós y que la Luz te guíe.' WHERE `ID`=22917;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 고기 냄새를 맡고 잠에서 깨어나 분노에 찬 포효를 내지릅니다!', `MaleText_loc4`='%s闻到了肉味，猛然惊醒过来并发出了愤怒的嚎叫！', `MaleText_loc5`='%s聞到了肉味，從睡眠狀態醒過來，大聲怒吼!', `MaleText_loc7`='¡%s huele la carne, despierta de su letargo y ruge furioso!' WHERE `ID`=22918;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 병엔... 우리 마법이 통하지 않아!', `MaleText_loc4`='我们的魔法……对这种疾病完全没有作用！', `MaleText_loc5`='我們的法術...對付疾病一點用也沒有!', `MaleText_loc7`='¡Nuestra magia... es inútil contra esta enfermedad!' WHERE `ID`=22919;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신이 우리를 버렸어!', `MaleText_loc4`='神已经遗弃了我们！', `MaleText_loc5`='諸神遺棄我們了!', `MaleText_loc7`='¡Los dioses nos han abandonado!' WHERE `ID`=22920;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 파멸할 거야, 형제! 역병이 안에서부터 우리를 갉아먹는다!', `MaleText_loc4`='末日临近了，兄弟们！我们会被彻底吞噬！', `MaleText_loc5`='末日接近了，兄弟!這場瘟疫會從內將我們吞噬殆盡!', `MaleText_loc7`='¡El final se acerca, hermanos! ¡Esta peste nos devora desde dentro!' WHERE `ID`=22921;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안전 문제로 협만 내 근거리 비행밖에 허용되지 않습니다. 어디로 가시겠어요?', `MaleText_loc4`='安全起见，我只能为你安排峡湾区域的短途飞行。那么，你想去哪呢？', `MaleText_loc5`='為了你的安全起見，我只能讓你在峽灣中飛到其他短程的地方。你想要前往的目的地是?', `MaleText_loc7`='Por tu seguridad, solo puedo autorizar vuelos cortos a otras zonas del fiordo. ¿A qué lugar quieres ir?', `FemaleText_loc1`='안전 문제로 협만 내 근거리 비행밖에 허용되지 않습니다. 어디로 가시겠어요?', `FemaleText_loc4`='安全起见，我只能为你安排峡湾区域的短途飞行。那么，你想去哪呢？', `FemaleText_loc5`='為了你的安全起見，我只能讓你在峽灣中飛到其他短程的地方。你想要前往的目的地是?', `FemaleText_loc7`='Por tu seguridad, solo puedo autorizar vuelos cortos a otras zonas del fiordo. ¿A qué lugar quieres ir?' WHERE `ID`=22922;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='복수의 상륙지로 보내 주십시오.', `MaleText_loc4`='将我送往复仇港吧。', `MaleText_loc5`='帶我去復仇臺地。', `MaleText_loc7`='Llévame a Campo Venganza.', `FemaleText_loc1`='복수의 상륙지으로 보내 주세요.', `FemaleText_loc4`='将我送往复仇港吧。', `FemaleText_loc5`='帶我去復仇臺地。', `FemaleText_loc7`='Llévame a Campo Venganza.' WHERE `ID`=22923;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신 아가만드로 보내 주십시오.', `MaleText_loc4`='将我送往新阿加曼德吧。', `MaleText_loc5`='帶我到新阿加曼德。', `MaleText_loc7`='Llévame a Nuevo Agamand.', `FemaleText_loc1`='신 아가만드로 보내 주세요.', `FemaleText_loc4`='将我送往新阿加曼德吧。', `FemaleText_loc5`='帶我到新阿加曼德。', `FemaleText_loc7`='Llévame a Nuevo Agamand.' WHERE `ID`=22924;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='박쥐들이 아직 길을 모르니 울부짖는 협만 바깥으로는 보내줄 수 없습니다. 어디로 가고 싶으신가요?', `MaleText_loc4`='我无法为你安排前往嚎风峡湾之外区域的飞行。这些蝙蝠并不清楚那些航线。那么，你打算去哪儿？', `MaleText_loc5`='我無法提供你任何凜風峽灣外的事物。蝙蝠還不知道外面的路。你想去哪呢?', `MaleText_loc7`='No puedo ofrecerte nada fuera del Fiordo Aquilonal. Los murciélagos aún no conocen los caminos. ¿Adónde quieres ir?', `FemaleText_loc1`='박쥐들이 아직 길을 모르니 울부짖는 협만 바깥으로는 보내줄 수 없습니다. 어디로 가고 싶으신가요?', `FemaleText_loc4`='我无法为你安排前往嚎风峡湾之外区域的飞行。这些蝙蝠并不清楚那些航线。那么，你打算去哪儿？', `FemaleText_loc5`='我無法提供你任何凜風峽灣外的事物。蝙蝠還不知道外面的路。你想去哪呢?', `FemaleText_loc7`='No puedo ofrecerte nada fuera del Fiordo Aquilonal. Los murciélagos aún no conocen los caminos. ¿Adónde quieres ir?' WHERE `ID`=22925;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겨울발굽 야영지로 보내 주십시오.', `MaleText_loc4`='将我送往冬蹄营地吧。', `MaleText_loc5`='帶我到冬蹄營地。', `MaleText_loc7`='Llévame al Campamento Pezuña Invernal.', `FemaleText_loc1`='겨울발굽 야영지로 보내 주세요.', `FemaleText_loc4`='将我送往冬蹄营地吧。', `FemaleText_loc5`='帶我到冬蹄營地。', `FemaleText_loc7`='Llévame al Campamento Pezuña Invernal.' WHERE `ID`=22926;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싸우는 게 꼭 어린애 수준이군!', `MaleText_loc4`='瞧你这花拳秀腿的！', `MaleText_loc5`='你出的拳像個娘兒們!', `MaleText_loc7`='¡Peleas como una niña!', `FemaleText_loc1`='싸우는 게 꼭 어린애 수준이야!', `FemaleText_loc4`='瞧你这花拳秀腿的！', `FemaleText_loc5`='你出的拳像個娘兒們!', `FemaleText_loc7`='¡Peleas como una niña!' WHERE `ID`=22927;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='표적 허수아비도 이것보다는 세게 때리겠군.', `MaleText_loc4`='我觉得和假人对练都比和你来得有用。', `MaleText_loc5`='我對著目標假人訓練的結果比較好。', `MaleText_loc7`='Entreno mejor contra un muñeco-diana.', `FemaleText_loc1`='이거 너무 약해서 표적 허수아비로도 못 써먹겠네.', `FemaleText_loc4`='我觉得和假人对打都比和你来得有用。', `FemaleText_loc5`='我對著目標假人訓練的結果比較好。', `FemaleText_loc7`='Entreno mejor contra un muñeco-diana.' WHERE `ID`=22928;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='눈이나 뜨고 훈련하지 그래?', `MaleText_loc4`='你训练的时候怎么跟睡着了一样。', `MaleText_loc5`='你好像一邊睡覺一邊練習。', `MaleText_loc7`='Practicas como si estuvieras durmiendo.', `FemaleText_loc1`='아무리 그래도 졸면서 훈련받으면 안 되지.', `FemaleText_loc4`='你训练的时候怎么跟睡着了一样。', `FemaleText_loc5`='你好像一邊睡覺一邊練習。', `FemaleText_loc7`='Practicas como si estuvieras durmiendo.' WHERE `ID`=22929;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너와 훈련할 때야 살살 하겠지만, 별것도 아닌 녀석들이 왔을 땐 절대 봐주지 않겠어.', `MaleText_loc4`='要是那帮小东西敢杀进来，我可不会像跟你对练的时候那样克制。', `MaleText_loc5`='當這些小傢伙來的時候，我不會和你一樣退縮不前。', `MaleText_loc7`='Cuando vengan los pequeños, no me contendré como lo estoy haciendo contigo.', `FemaleText_loc1`='너와 훈련할 때야 살살 하겠지만, 별것도 아닌 녀석들을 상대할 땐 어림도 없지.', `FemaleText_loc4`='要是那帮小东西敢杀进来，我可不会像跟你对练的时候那样克制。', `FemaleText_loc5`='當這些小傢伙來的時候，我不會和你一樣退縮不前。', `FemaleText_loc7`='Cuando vengan los pequeños, no me contendré como lo estoy haciendo contigo.' WHERE `ID`=22930;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좀 쉬었다 하겠나, 물주먹?', `MaleText_loc4`='老太太，要不要休息一下啊？', `MaleText_loc5`='老太婆，你應該要休息一會兒吧?', `MaleText_loc7`='¿Seguro que no necesitas un descanso, vieja?', `FemaleText_loc1`='정말 안 쉬어도 되겠어, 굼벵이?', `FemaleText_loc4`='老太太，要不要休息一下啊？', `FemaleText_loc5`='老太婆，你應該要休息一會兒吧?', `FemaleText_loc7`='¿Seguro que no necesitas un descanso, vieja?' WHERE `ID`=22931;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이것도 공격이라고 하는 건가?', `MaleText_loc4`='你的拳头缺乏力道！', `MaleText_loc5`='你出的拳一點力氣也沒有!', `MaleText_loc7`='¡Luchas de forma lamentable!', `FemaleText_loc1`='설마 간지럼 공격을 하러 온 건 아니겠지?', `FemaleText_loc4`='你的拳头缺乏力道！', `FemaleText_loc5`='你出的拳一點力氣也沒有!', `FemaleText_loc7`='¡Luchas de forma lamentable!' WHERE `ID`=22932;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연습 경기라도 필요한가? 어쨌든 밥 먹을 이는 몇 개 남겨주지!', `MaleText_loc4`='不管你是练还是不练，都得满地找牙！', `MaleText_loc5`='不管你要不要練習，我都會打得你滿地找牙!', `MaleText_loc7`='¡Entrenamiento o no, vas a escupir dientes!', `FemaleText_loc1`='여기서 살아나가더라도 평생 틀니를 끼고 살게 해 주겠어!', `FemaleText_loc4`='不管你是练还是不练，都得满地找牙！', `FemaleText_loc5`='不管你要不要練習，我都會打得你滿地找牙!', `FemaleText_loc7`='¡Entrenamiento o no, vas a escupir dientes!' WHERE `ID`=22933;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 때리는 척만 하지 말고 진짜로 때려보란 말이다!', `MaleText_loc4`='来呀，你倒是给我一拳啊！', `MaleText_loc5`='拜託，你到底在打哪裡啊?', `MaleText_loc7`='¡Vamos, deja de intentarlo y golpéame de una vez!', `FemaleText_loc1`='자, 때리는 척만 하지 말고 진짜로 때려봐!', `FemaleText_loc4`='来呀，你倒是给我一拳啊！', `FemaleText_loc5`='拜託，你到底在打哪裡啊?', `FemaleText_loc7`='¡Vamos, deja de intentarlo y golpéame de una vez!' WHERE `ID`=22934;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 저녁거리를 지키려고 모습을 드러냅니다!', `MaleText_loc4`='一只%s突然窜了出来，想要护食。', `MaleText_loc5`='一個%s看起來在保護牠的晚餐。', `MaleText_loc7`='Un %s parece defender su cena.' WHERE `ID`=22935;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 평생을 군대에서 보냈지. 수많은 깃발 아래에서 수많은 전투를 경험했지만, 언제나 다른 사람을 위한 전쟁이었어.$B$B이번에는 그렇지 않네. 여기 보이는 포세이큰 병사들은 모두 한 가지 목적을 위해 모였지. 바로 아서스의 죽음 말일세.', `MaleText_loc4`='我一生戎马，经历过无数战争的洗礼。我曾在不同的旗帜下作战，不过那都是别人的战争。$B$B这次却截然不同了。这些被遗忘者士兵来这里的理由都只有一个。阿尔萨斯必须死。', `MaleText_loc5`='我打了一輩子的仗，東征西討，服役於不同麾下 - 但都是為了我的族人而戰。$B$B這次不同，你所見到的每個被遺忘者將士們，前來這裡只為了一個理由。殺了阿薩斯。', `MaleText_loc7`='He pasado mi vida entera en el ejército. He luchado en muchas guerras, bajo muchos estandartes, pero siempre han sido las guerras de otros.$B$BEsta vez no es así. Cada soldado Renegado que ves aquí ha venido por un único motivo. Arthas ha de morir.' WHERE `ID`=22936;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이것 보쇼, 길. 내 제안을 좀 더 고려해보지 않겠소? 당신 부하들이 모으는 설인 모피나 솜털을 내가 가진 가죽이나 절인 고기랑 교환하고 싶은데 말이지.', `MaleText_loc4`='嗨，基尔，再考虑考虑我的提议？你瞧，我有大量兽皮和腌肉，想和你交换厚重的雪人毛皮或是你们正在加工的羽毛。', `MaleText_loc5`='嗨，吉爾，好好考慮過我提的條件了嗎?我有很多的皮革和醃肉可以交換你的重雪人毛皮，或是你的手下正在忙著處理的那個東西。', `MaleText_loc7`='¡Hey, Gil! ¿Has considerado mi oferta? Tendré conservadas muchas pieles y carne para cambiar por esos pesados pelajes o pelusillas de yeti con los que tus hombres están trabajando.' WHERE `ID`=22937;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제탄, 나도 당신하고 거래하고 싶지만, 이 물건은 모두 얼라이언스 원정군의 재산이라오.', `MaleText_loc4`='我很想跟你做生意，杰森，但这些东西都是联盟远征军的财产。', `MaleText_loc5`='傑桑，雖然我很想跟你做生意，但是這些東西全都屬於聯盟遠征部隊的財產。', `MaleText_loc7`='A pesar de que me encantaría hacer negocios contigo, Jethan, todo esto es propiedad de las fuerzas expedicionarias de la Alianza.' WHERE `ID`=22938;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어쩌면 죽을 사람이 다 죽고 나서 남는 물건으로 거래할 수 있을지도 모르겠소. 부대가 회색 구릉지로 이동할 때가 되면 분명히 당신네와 거래할 기회가 생길 거요.', `MaleText_loc4`='或许等战事消停之后，我可以考虑用余货给你做交易。不过你干嘛不和远征军做生意啊，他们要进军灰熊丘陵了，急需大量物资。', `MaleText_loc5`='也許，當一切都穩定下來以後，我可以談些交易，獲取利益。我相信如果軍隊開向灰白之丘，會帶給你的人民許多的生意。', `MaleText_loc7`='Quizá, una vez que todo haya pasado, tú y yo podamos sacar beneficio a los excedentes. Estoy seguro de que las tropas serán un gran negocio para tu gente en su camino hacia las Colinas Pardas.' WHERE `ID`=22939;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그거 기대되는군. 그때까지 고기를 잘 보관해야겠소. 제대로 된 병참장교라면 식량 공급을 마다할 리가 없으니까.', `MaleText_loc4`='嗯，我很期待能和远征军做生意。这样的话，我就要好好地保存这些肉啦。优秀的军需官是不会拒绝可靠的补给品入库的。', `MaleText_loc5`='我很期待這件事。我猜我得趕緊把這些肉醃起來，一個好的軍需官是不會減少可靠的軍糧供給。', `MaleText_loc7`='Estaré esperándolo. Entonces creo que conservaré esta carne. Un buen intendente nunca rechazaría un suministro de raciones fiable.' WHERE `ID`=22940;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발리브루는 아제로스 최고의 양조장이랍니다! 가을 축제에서 확인해 보시죠!', `MaleText_loc4`='麦酒，艾泽拉斯最好的酒！来美酒节尝尝吧！', `MaleText_loc5`='麥酒，艾澤拉斯最好的酒坊!來啤酒節看看吧!', `MaleText_loc7`='¡Cebadiz, la mejor cervecería de Azeroth! ¡No te los pierdas en la Fiesta de la Cerveza!', `FemaleText_loc1`='발리브루는 아제로스 최고의 양조장이지요! 가을 축제 때 꼭 들러주세요!', `FemaleText_loc4`='麦酒，艾泽拉斯最好的酒！来美酒节尝尝吧！', `FemaleText_loc5`='麥酒，艾澤拉斯最好的酒坊!來啤酒節看看吧!', `FemaleText_loc7`='¡Cebadiz, la mejor cervecería de Azeroth! ¡No te los pierdas en la Fiesta de la Cerveza!' WHERE `ID`=22941;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='썬더브루는 최고의 맥주를 만듭니다! 가을 축제에서 확인해 보세요!', `MaleText_loc4`='雷酒，全世界最好的酒。来美酒节尝尝吧！', `MaleText_loc5`='雷酒，所有國度中最好的酒坊。啤酒節的時候來看看吧!', `MaleText_loc7`='¡Cebatruenos, la mejor destilería de todos los reinos! ¡No te los pierdas en la Fiesta de la Cerveza!', `FemaleText_loc1`='썬더브루는 최고의 맥주를 만들지요! 가을 축제 때 꼭 들러주세요!', `FemaleText_loc4`='雷酒，全世界最好的酒。来美酒节尝尝吧！', `FemaleText_loc5`='雷酒，所有國度中最好的酒坊。啤酒節的時候來看看吧!', `FemaleText_loc7`='¡Cebatruenos, la mejor destilería de todos los reinos! ¡No te los pierdas en la Fiesta de la Cerveza!' WHERE `ID`=22942;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배고파? 여기서 잠도 잘 수 있어.', `MaleText_loc4`='饿了吗？你还可以在这里睡觉哦。', `MaleText_loc5`='餓嗎?也可以睡在這裡喔。', `MaleText_loc7`='¿Hambriento? También puedes dormir aquí.' WHERE `ID`=22943;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정신 똑바로 차리십시오, $r. 우린 언데드들에게 포위당했단 말입니다.', `MaleText_loc4`='保持警惕，$r，我们已经被亡灵包围了。', `MaleText_loc5`='保持清醒，$r，我們被這裡的行屍走肉給包圍了。', `MaleText_loc7`='Mantente alerta, $r, estamos rodeados de muertos andantes.' WHERE `ID`=22944;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙습니다, 이방인이여.', `MaleText_loc4`='谢谢你，陌生人。', `MaleText_loc5`='謝謝你，陌生人。', `MaleText_loc7`='Gracias, $gforastero:forastera;.', `FemaleText_loc1`='감사합니다, 이방인이여.', `FemaleText_loc4`='谢谢你，陌生人。', `FemaleText_loc5`='謝謝你，陌生人。', `FemaleText_loc7`='Gracias, $gforastero:forastera;.' WHERE `ID`=22945;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 돌아가야 합니다. 즐거운 사냥이 되시기를.', `MaleText_loc4`='我必须回去，祝你狩猎愉快。', `MaleText_loc5`='我要回去了，祝你狩獵順利。', `MaleText_loc7`='He de regresar. Te deseo buena caza.', `FemaleText_loc1`='저는 돌아가야 해요. 멋진 사냥이 되시기를.', `FemaleText_loc4`='我必须回去，祝你狩猎愉快。', `FemaleText_loc5`='我要回去了，祝你狩獵順利。', `FemaleText_loc7`='He de regresar. Te deseo buena caza.' WHERE `ID`=22946;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대지와 바람의 정령이 그대를 축복하기를.', `MaleText_loc4`='愿天地间的精魂永远保佑你。', `MaleText_loc5`='願大地和空氣之靈的祝福降臨在你身上。', `MaleText_loc7`='Que los espíritus de la tierra y el aire te bendigan.', `FemaleText_loc1`='대지와 바람의 정령이 그대에게 축복을 내리길.', `FemaleText_loc4`='愿天地间的精魂永远保佑你。', `FemaleText_loc5`='願大地和空氣之靈的祝福降臨在你身上。', `FemaleText_loc7`='Que los espíritus de la tierra y el aire te bendigan.' WHERE `ID`=22947;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저를 죽음에서 구해 주셨군요. 그대에게 빚을 졌습니다.', `MaleText_loc4`='你救了我的命。我欠你一份情。', `MaleText_loc5`='你把我從死神手中救了出來，我欠你一命。', `MaleText_loc7`='Me has salvado de una muerte segura. Te debo una.', `FemaleText_loc1`='제 목숨을 살려 주셨군요. 그대에게 빚을 졌어요.', `FemaleText_loc4`='你救了我的命。我欠你一份情。', `FemaleText_loc5`='你把我從死神手中救了出來，我欠你一命。', `FemaleText_loc7`='Me has salvado de una muerte segura. Te debo una.' WHERE `ID`=22948;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비틀린 숲을 지나가는 게 아니었습니다. 다른 사람들처럼 우리도 조심했어야 했어요!', `MaleText_loc4`='我们不应该穿越裂木森林的。是个人都该明白这点！', `MaleText_loc5`='我們本來就不該經過裂木森林的，這誰都曉得!', `MaleText_loc7`='Nunca debimos haber viajado por El Bosque Hendido. ¡Todo el mundo lo sabe!', `FemaleText_loc1`='비틀린 숲을 가로지르다니, 바보 같은 짓을 했어요. 누구나 아는 사실인데!', `FemaleText_loc4`='我们不应该穿越裂木森林的。是个人都该明白这点！', `FemaleText_loc5`='我們本來就不該經過裂木森林的，這誰都曉得!', `FemaleText_loc7`='Nunca debimos haber viajado por El Bosque Hendido. ¡Todo el mundo lo sabe!' WHERE `ID`=22949;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이상한 유령이 이 땅을 돌아다닙니다. 조심하십시오!', `MaleText_loc4`='这里到处都是幽魂。小心！', `MaleText_loc5`='奇怪的鬼魂在大地上遊蕩，小心了!', `MaleText_loc7`='Extraños fantasmas caminan por estas tierras. ¡Ten cuidado!', `FemaleText_loc1`='이 땅엔 이상한 유령이 가득해요. 조심하세요!', `FemaleText_loc4`='这里到处都是幽魂。小心！', `FemaleText_loc5`='奇怪的鬼魂在大地上遊蕩，小心了!', `FemaleText_loc7`='Extraños fantasmas caminan por estas tierras. ¡Ten cuidado!' WHERE `ID`=22950;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들은 우리를 한 명씩 데려갔습니다. 분명히 다른 생존자가 있을 겁니다.', `MaleText_loc4`='他们将我们分别关押起来。我敢肯定还有其他的幸存者。', `MaleText_loc5`='他們一個一個的把我們抓走。我確定還有其他的倖存者。', `MaleText_loc7`='Nos capturaron uno a uno. Estoy seguro de que hay otros supervivientes.', `FemaleText_loc1`='그들은 우리를 한 명씩 데려갔어요. 어딘가 다른 생존자가 있을 거예요.', `FemaleText_loc4`='他们将我们分别关押起来。我敢肯定还有其他的幸存者。', `FemaleText_loc5`='他們一個一個的把我們抓走。我確定還有其他的倖存者。', `FemaleText_loc7`='Nos capturaron uno a uno. Estoy segura de que hay otros supervivientes.' WHERE `ID`=22951;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신에게 목숨을 빚졌습니다, 이방인이여.', `MaleText_loc4`='我欠你一条命，陌生人。', `MaleText_loc5`='陌生人，你救了我一命。', `MaleText_loc7`='Tengo una deuda de vida contigo, $gforastero:forastera;.', `FemaleText_loc1`='당신이 절 구하셨습니다, 이방인이여.', `FemaleText_loc4`='我欠你一条命，陌生人。', `FemaleText_loc5`='陌生人，你救了我一命。', `FemaleText_loc7`='Tengo una deuda de vida contigo, $gforastero:forastera;.' WHERE `ID`=22952;
