UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들의 고통을 들이마셔라, 형제여!', `MaleText_loc4`='以他们的痛苦为乐趣吧！', `MaleText_loc5`='在他們的苦痛中狂飲吧，弟兄們!', `MaleText_loc7`='¡Regodéate en su miseria, hermano!' WHERE `ID`=22954;
