UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕의 뜻에 따라 죽음을 맞아라!', `MaleText_loc4`='以巫妖王的名义，死吧！', `MaleText_loc5`='願你死於巫妖王的恩寵之下!', `MaleText_loc7`='¡Ojalá mueras con el favor del Rey Exánime!' WHERE `ID`=22956;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이미론의 영광을 위해 싸우자! 리치 왕의 이름으로 숨을 거두자!', `MaleText_loc4`='为伊米隆国王的荣耀而战！我们不惜为巫妖王陛下而死！', `MaleText_loc5`='為了依米倫的榮光而戰!為了巫妖王之名而亡!', `MaleText_loc7`='¡Luchamos por la gloria de Ymiron! ¡Morimos en nombre del Rey Exánime!' WHERE `ID`=22957;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐...', `MaleText_loc4`='等一等……', `MaleText_loc5`='等等...', `MaleText_loc7`='Espera un minuto...' WHERE `ID`=22958;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 그냥...', `MaleText_loc4`='这只是……', `MaleText_loc5`='它就只是...', `MaleText_loc7`='Es solo...' WHERE `ID`=22959;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맥주! 흔해빠진 맥주잖아!', `MaleText_loc4`='啤酒！只是啤酒而已！', `MaleText_loc5`='啤酒!就只是啤酒!', `MaleText_loc7`='¡Cerveza! ¡Simple cerveza!' WHERE `ID`=22960;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='특별한 점이라고는 눈꼽만큼도 없군.', `MaleText_loc4`='这酒真是稀松平常，毫无新意。', `MaleText_loc5`='一點也沒有不尋常的地方。', `MaleText_loc7`='No tiene nada de extraordinario.' WHERE `ID`=22961;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 당신! 그릭에게는 한마디도 하지 마시오! 알겠소?', `MaleText_loc4`='你！不许告诉葛瑞克！听到没有？', `MaleText_loc5`='你!這件事別跟格里克說!你聽到我說的了嗎?', `MaleText_loc7`='¡Tú! ¡Ni una palabra a Grick sobre esto! ¿Me oyes?' WHERE `ID`=22962;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야생의 혼이 내 편이다...', `MaleText_loc4`='狂野的灵魂与我同在……', `MaleText_loc5`='狂野的靈魂與我同在...', `MaleText_loc7`='Lucho con un espíritu indomable…' WHERE `ID`=22963;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혼이여, 이리 돌아오라!', `MaleText_loc4`='灵魂，到我这里来！', `MaleText_loc5`='靈魂，回到我這裡來!', `MaleText_loc7`='¡Espíritu, vuelve a mí!' WHERE `ID`=22964;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 근처는 안전합니다. 당신은 자유예요!', `MaleText_loc4`='已经很安全了。你自由啦！', `MaleText_loc5`='已經沒有危險了。你自由了!', `MaleText_loc7`='No hay moros en la costa. ¡Eres libre!', `FemaleText_loc1`='이 근처는 안전합니다. 당신은 자유예요!', `FemaleText_loc4`='已经很安全了。你自由啦！', `FemaleText_loc5`='已經沒有危險了。你自由了!', `FemaleText_loc7`='No hay moros en la costa. ¡Eres libre!' WHERE `ID`=22965;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쉿! 여기! 우리 안일세. 이리 오게. 자네가 누군지 좀 보자고.', `MaleText_loc4`='喂！这里，来牢笼这里。过来让我看看你。', `MaleText_loc5`='喂!上面這邊，籠子裡。過來讓我看看你。', `MaleText_loc7`='¡Pssst! Aquí arriba, en la jaula. Ven y deja que te vea.' WHERE `ID`=22966;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐... 그냥 거기 앉아서 구경만 할 참인가? 자네 구조대 맞아?', `MaleText_loc4`='喂……你就准备坐在那里沾沾自喜吗？你到底是不是来救人的啊？', `MaleText_loc5`='哈嚕...你居然就打算一屁股坐在那邊?這算哪門子的救援?', `MaleText_loc7`='Hooolaaaaa... ¿Vais a quedaros ahí sentados dándoos palmaditas en la espalda? ¿Pero qué clase de rescatadores sois?' WHERE `ID`=22967;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기... 이왕이면 여기 위로 산책 와서 내가 탈출하게 도와주는 게 어떤가?', `MaleText_loc4`='我说……别在那儿闲逛，过来帮我一把好吗？', `MaleText_loc5`='所以...能不能遛達到上面來，幫我逃出去啊?', `MaleText_loc7`='Y... ¿qué tal si alguno de ustedes sube aquí y me ayuda a salir?' WHERE `ID`=22968;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 여기라고... 덫에 걸린 드워프 본 적 있나? 이리 와 주게. 나랑 얘기 좀 하자고.', `MaleText_loc4`='喂！这里……被困的矮人这里。来啦，我有话对你讲。', `MaleText_loc5`='唷呵。在這...這個被困住的矮人。過來，讓我跟你說句話。', `MaleText_loc7`='Yuuujuuuu. Aquí arriba... el enano atrapado. Venga, déjame hablar contigo.' WHERE `ID`=22969;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일을 하다 말 셈인가? 탈출할 수 있는 상황인지 와서 좀 알려 주게!', `MaleText_loc4`='别半途而废啊。告诉我，我能安全逃离此地了吧？', `MaleText_loc5`='別放著工作到一半人就跑掉，現在。來，告訴我現在逃走安不安全!', `MaleText_loc7`='No te vayas dejando el trabajo a medio hacer. Ven y dime si será seguro escapar ahora.' WHERE `ID`=22970;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아킬존이시여, 침략자들이 다가옵니다!', `MaleText_loc4`='埃基尔松，入侵者靠近了！', `MaleText_loc5`='阿奇爾森，入侵者靠近了!', `MaleText_loc7`='¡Akil''zon, los invasores se acercan!' WHERE `ID`=22971;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경기장엔 침입자의 피가 흘러 넘칠 것이다! 이 울루프가 왔다!', `MaleText_loc4`='擅自闯入竞技场的家伙将付出血的代价！沃鲁夫来了！', `MaleText_loc5`='擂台上會淹滿了入侵者之血!歐路夫在此!', `MaleText_loc7`='¡El círculo rebosará con la sangre de los entrometidos! ¡Oluf ha llegado!' WHERE `ID`=22972;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='포로를 풀어라! 피르주스가 놈들을 모두 해치울 것이다!', `MaleText_loc4`='放出所有俘虏！芬尔乌斯要把他们全碾成渣！', `MaleText_loc5`='放出囚犯!佛久斯會殺光他們!', `MaleText_loc7`='¡Soltad a los prisioneros! ¡Firjus los destruirá!' WHERE `ID`=22973;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피르주스는 하찮은 놈에 지나지 않았다. 리치 왕의 진정한 병사에게도 용감하게 덤빌 수 있는지 두고 보자!', `MaleText_loc4`='芬尔乌斯算什么！让巫妖王手下真正的士兵来试试你的战力吧。', `MaleText_loc5`='佛久斯不算什麼!讓我這個巫妖王的真正戰士來試試你的技巧吧!', `MaleText_loc7`='¡Firjus era indigno! ¡Pon a prueba tu destreza en la batalla contra un auténtico soldado del Rey Exánime!' WHERE `ID`=22974;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아... 살덩이를 거두어 주마...', `MaleText_loc4`='很好……肉……更多的肉……', `MaleText_loc5`='很好...更多收穫的肉...', `MaleText_loc7`='Bien... Más carne para la cosecha...' WHERE `ID`=22975;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 페트로프는 저를 이런 멍청한 드워프들과 함께 여기로 보낼 수가 있죠?', `MaleText_loc4`='我经不起派特洛夫的说辞，居然同意跟着一帮无能的矮人到了这里。', `MaleText_loc5`='我怎麼會讓派特洛夫說服我帶著這些無能的矮人出來這裡?!', `MaleText_loc7`='¿Cómo permití que Petrov me convenciera para venir aquí con estos enanos incompetentes?' WHERE `ID`=22976;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게 약속한 지원은 대체 어디 있나요?', `MaleText_loc4`='他还许诺说会派增援力量过来，可人呢？', `MaleText_loc5`='那些答應我要來的援助咧?', `MaleText_loc7`='¿Dónde está la ayuda que se me prometió?' WHERE `ID`=22977;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='박쥐 똥은 저절로 모이진 않는단 말이에요!', `MaleText_loc4`='总得有人去收集粪便啊！', `MaleText_loc5`='大便可不會自己跑到你手上!', `MaleText_loc7`='¡Ese guano no va a recogerse solo!' WHERE `ID`=22978;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 비틀린 숲엔 절대 못 들어가요. 거긴 귀신이 나오잖아요!', `MaleText_loc4`='我说什么都不会踏进裂木森林一步，那地方闹鬼了！', `MaleText_loc5`='不要逼我進去裂木森林;那裡鬧鬼耶!', `MaleText_loc7`='¡No voy a ir a El Bosque Hendido de ninguna manera! ¡Ese lugar está maldito!' WHERE `ID`=22979;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌아가면 페트로프 씨를 가만두지 않을 거예요!', `MaleText_loc4`='等我们回去，我一定要杀了派特洛夫！', `MaleText_loc5`='只要我們一回去，我就要宰了派特洛夫!', `MaleText_loc7`='¡Cuando volvamos, voy a matar a Petrov!' WHERE `ID`=22980;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 더 북쪽으로 갈 수는 없어요! 저 커다란 거미 좀 보라고요!', `MaleText_loc4`='我不会再向北挪一步了！那些蜘蛛好大！', `MaleText_loc5`='牠們一路跟著我向北去!這些蜘蛛超大的!', `MaleText_loc7`='¡Hasta aquí es lo más al norte que pienso ir! ¡Esas arañas son enormes!' WHERE `ID`=22981;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='페트로프 씨는 도와줄 사람이 더 올 거라고 약속했어요. 대체 왜 이렇게 오래 걸리는 건가요?!', `MaleText_loc4`='派特洛夫许诺说马上就派援兵过来。怎么这么久都没动静？！', `MaleText_loc5`='派特洛夫答應我要送更多人手來的，怎麼這麼久還沒到?!', `MaleText_loc7`='Petrov me prometió que recibiríamos más ayuda. ¿Por qué está tardando tanto?' WHERE `ID`=22982;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 내가 저 아래에서 비행기를 정비하는 게 아니라 박쥐 똥이나 긁어모으고 있어야 하나요!', `MaleText_loc4`='我本该留在那里鼓捣飞行器的，却被派到这里来收集蝙蝠粪便！', `MaleText_loc5`='我本來是應該在底下維修飛行器，不是負責收集大便!', `MaleText_loc7`='¡Debería estar allí trabajando en las máquinas voladoras, no encargado de recoger guano!' WHERE `ID`=22983;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여긴 안전한 장소라야 하는 거 아닌가요! 안전하기는커녕 사방에 굶주린 검은늑대들만 득실거린다니, 뭐가 어떻게 되는 건지 땜장이왕만이 아시겠지!', `MaleText_loc4`='这里应该很安全！总比被一群饥饿的座狼给包围了要好，大工匠恐怕也会认可这一点！', `MaleText_loc5`='這地方應該很安全的!結果我們在一群飢餓的座狼中間，高等技工一定知道些什麼!', `MaleText_loc7`='¡Se suponía que este lugar era seguro! ¡Pero, en cambio, estamos rodeados de huargos hambrientos y el Manitas Mayor sabe qué más!' WHERE `ID`=22984;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='페크넛, 입 좀 다물어요!', `FemaleText_loc4`='菲纳特，嘘！', `FemaleText_loc5`='喔，費克努，噓!', `FemaleText_loc7`='¡Oh Feknut, calla!' WHERE `ID`=22985;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아무 일 없을 거예요, 페크넛. 괜찮을 거라고요.', `FemaleText_loc4`='一切都会好起来的，菲纳特。别担心。', `FemaleText_loc5`='一切會好轉的，費克努，看著吧。', `FemaleText_loc7`='Todo va a ir bien, Feknut. Ya lo verás.' WHERE `ID`=22986;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='페크넛, 제발 그만해요. 난 야렌이 걱정돼서 죽겠는데 당신은 전혀 도움이 안 되는군요.', `FemaleText_loc4`='菲纳特，别这样。我很担心亚伦的安危，你就别给我添乱了。', `FemaleText_loc5`='費克努，拜託停下來，我擔心你和賈倫一點忙都幫不上。', `FemaleText_loc7`='Feknut, por favor, para. Estoy preocupada por Jaren y no me estás ayudando.' WHERE `ID`=22987;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네, 네, 우리 모두 당신이 요새에 머무르길 바랐다는 거 알아요?', `FemaleText_loc4`='对，我们都希望你能在要塞里安静地呆着。', `FemaleText_loc5`='是的，我們全都希望你能留在要塞裡。', `FemaleText_loc7`='Sí y todos desearíamos que te hubieses quedado en el fuerte.' WHERE `ID`=22988;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='페크넛! 그만해요!', `FemaleText_loc4`='菲纳特！够了！', `FemaleText_loc5`='費克努!夠了沒!', `FemaleText_loc7`='¡Feknut! ¡Basta!' WHERE `ID`=22989;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이봐요, 일을 스스로 해결할 방법을 생각해 봤더라면 당신은 요새로 좀 더 빨리 돌아갈 수 있었을 걸요.', `FemaleText_loc4`='不如你试着独立完成那些工作，这样说不定你还能快点返回要塞呢。', `FemaleText_loc5`='你曉得嗎，你可以想辦法自己完成工作，這樣你可以更快回到要塞。', `FemaleText_loc7`='¿Sabes? Podrías pensar en hacer el trabajo tú mismo. Así podrías volver al fuerte más rápido.' WHERE `ID`=22990;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제발 조용히 좀 해요, 페크넛. 당신 때문에 머리가 다 아파요.', `FemaleText_loc4`='菲纳特，你给我安静一会儿。吵得我头痛。', `FemaleText_loc5`='費克努請你安靜，你讓我的頭很痛。', `FemaleText_loc7`='Feknut por favor cállate. Me estás dando dolor de cabeza.' WHERE `ID`=22991;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='페크넛, 제발! 페트로프가 머지않아 반드시 도와줄 사람을 보낼 거예요.', `FemaleText_loc4`='菲纳特，拜托！派特洛夫很快就会派帮手来了！', `FemaleText_loc5`='費克努，拜託!我相信派特洛夫馬上就會派給你更多幫手的。', `FemaleText_loc7`='¡Feknut, por favor! ¡Estoy segura de que Petrov te enviará más ayuda pronto!' WHERE `ID`=22992;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방어가 허물어졌다! 공격하라!', `MaleText_loc4`='他们的防线被攻破了！进攻！', `MaleText_loc5`='防禦崩潰了!進攻!', `MaleText_loc7`='¡Sus defensas están bajas! ¡Atacad!', `FemaleText_loc1`='방어가 허물어졌다! 공격하라!', `FemaleText_loc4`='他们的防线被攻破了！进攻！', `FemaleText_loc5`='防禦崩潰了!進攻!', `FemaleText_loc7`='¡Sus defensas están bajas! ¡Atacad!' WHERE `ID`=22993;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으하하, 자유다!', `MaleText_loc4`='啊，自由了！', `MaleText_loc5`='啊啊，自由!', `MaleText_loc7`='¡Ahh, libertad!' WHERE `ID`=22994;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 구해 줬으니 보상을 해야 도리겠지. 보자... 그 야만인 녀석들이 내 가방을 어디다 뒀지?', `MaleText_loc4`='你救了我的命，我自然会报答你。不过那帮野蛮人把我的背包藏哪儿了？', `MaleText_loc5`='你拯救了我，我一定要獎勵你這才公平。那麼，那些野人把我的背袋放到哪了?', `MaleText_loc7`='Supongo que lo justo será que te recompense por rescatarme. ¿Dónde habrán puesto mi cartera esos salvajes?' WHERE `ID`=22995;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쑥스러워 말게. 편하게 받으라고. 자네가 도와주지 않았더라면 저 짐승 같은 놈들이 지금쯤 내 머리를 찌그러뜨리고 있을 걸세.', `MaleText_loc4`='别不好意思。随意挑吧。要不是你帮忙，我早就完了。', `MaleText_loc5`='別害羞。自己來吧。如果不是你的幫忙，他們這些混蛋大概現在就把我的頭縮成乾屍了吧。', `MaleText_loc7`='No sean tímidos. Agarren lo que quieran. Si no fuera por su ayuda, eso salvajes estarían reduciendo mi cabeza ahora mismo.' WHERE `ID`=22996;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만하게, 이룰론.', `MaleText_loc4`='够了，伊鲁伦。', `MaleText_loc5`='厄盧隆，夠了。', `MaleText_loc7`='Eso será suficiente, Irulon.' WHERE `ID`=22997;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폴드링 대영주님, 모습을 드러내시면 안 됩니다!', `MaleText_loc4`='弗丁大人，您不能露面！', `MaleText_loc5`='弗丁大人，你千萬不能現身!', `MaleText_loc7`='¡Lord Vadín, no debe descubrirse!' WHERE `ID`=22998;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 위장을 벗습니다.', `MaleText_loc4`='%s脱掉伪装。', `MaleText_loc5`='%s移除了他的偽裝。', `MaleText_loc7`='%s se quita el disfraz.' WHERE `ID`=22999;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 아이는... 아니, 사실은 검을 정화하는 데 참여한 모든 기사는 죽음을 면할 수도 있었어.', `MaleText_loc4`='他的死，事实上……在净化灰烬使者的过程中，所有骑士的死本来都是可以避免的。', `MaleText_loc5`='在尋回這把劍途中，使得這位男孩死亡，甚至所有騎士的死亡，其實都是可以避免的。', `MaleText_loc7`='La muerte del chico y, de hecho, las de todos los caballeros involucrados en la redención de la hoja podrían haberse evitado.' WHERE `ID`=23000;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들의 죽음이 내 영혼을 무겁게 짓누르고 있네.', `MaleText_loc4`='他们的逝去让我倍感沉痛。', `MaleText_loc5`='他們的死使我的靈魂倍感沉重。', `MaleText_loc7`='Sus muertes son una pesada carga para mi alma.' WHERE `ID`=23001;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대영주님, 자유를 위한 길에는 언제나 비극이 따르게 마련입니다. 대영주님을 잃는 위험을 감수할 수는 없었습니다. 그런 일이 생긴다면 십자군은 무너질 테니까요.', `MaleText_loc4`='自由之路总是铺垫着悲剧，大人。但我们不能让您做出牺牲。北伐军无法承受如此沉重的打击。', `MaleText_loc5`='通往自由的路上總是上演著悲劇，大人。我們不能冒著失去你的風險，十字軍撐不過這一擊的。', `MaleText_loc7`='El camino de la libertad siempre ha estado lleno de tragedias, señor. No podíamos arriesgarnos a perderle. La Cruzada no podría sobrevivir a semejante golpe.' WHERE `ID`=23002;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 얼굴을 찡그립니다.', `MaleText_loc4`='%s流露出痛苦的神情。', `MaleText_loc5`='%s表情扭曲。', `MaleText_loc7`='%s hace una mueca de dolor.' WHERE `ID`=23003;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 직접 노스렌드로 그 검을 가져왔어야 했네. 내가 감당해야 하는 짐이었던 것을...', `MaleText_loc4`='这把剑本来应该由我带来诺森德的。从此以后，它所背负的一切就让我来承担吧。', `MaleText_loc5`='原本應該是我帶著這把劍前往北裂境，這是我應該肩負的責任。', `MaleText_loc7`='Yo debería haber sido el que llevara la hoja a Rasganorte. Yo debía portar esa carga.' WHERE `ID`=23004;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 그대의 말이 옳네, 이룰론. 우리는 자유를 누리는 대가로 수천 명을 잃게 되겠지.', `MaleText_loc4`='伊鲁伦，你说得对。自由的代价是沉重的，毫无疑问还会有上千名骑士为此牺牲。', `MaleText_loc5`='不過你是對的，厄盧隆。要讓我們獲得自由必將使騎士團再賠上數以千計的生命。', `MaleText_loc7`='Pero tienes razón, Irulon. Nuestra libertad les costará, sin duda, miles de vidas más.' WHERE `ID`=23005;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 파멸의 인도자를 집어듭니다.', `MaleText_loc4`='%s拿起灰烬使者。', `MaleText_loc5`='%s拾起了灰燼使者。', `MaleText_loc7`='%s coge la Crematoria.' WHERE `ID`=23006;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 말이 들리느냐, 아서스? 은빛십자군이 너를 처단하러 왔다! 네 왕국은 정의의 이름으로 무너질 것이야! 성스러운 빛의 힘으로 말이다!', `MaleText_loc4`='阿尔萨斯，你听见了吗？银色北伐军来了！你的王国将被正义的审判彻底毁灭！我以圣光之名起誓！', `MaleText_loc5`='聽到了嗎，阿薩斯?銀白十字軍要來了!你的王國將在毀於正義之力下!以聖光之名!', `MaleText_loc7`='¿Me oyes, Arthas? ¡La Cruzada Argenta viene a por ti! ¡Tu reino se derrumbará bajo el peso de la justicia! ¡Por la Luz!' WHERE `ID`=23007;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[조잡한 브리쿨어] 비요른네 엄마는 얼레리꼴레리!', `MaleText_loc4`='[维库人土语] Bjorns mottar haelgond sygar！', `MaleText_loc5`='[粗陋的維酷語]Bjorns mottar haelgond sygar!', `MaleText_loc7`='[Vrykul ordinario] ¡Bjorns mottar haelgond sygar!', `FemaleText_loc1`='[조잡한 브리쿨어] 비요른네 엄마는 얼레리꼴레리!', `FemaleText_loc4`='[维库人土语] Bjorns mottar haelgond sygar！', `FemaleText_loc5`='[粗陋的維酷語]Bjorns mottar haelgond sygar!', `FemaleText_loc7`='[Vrykul ordinario] ¡Bjorns mottar haelgond sygar!' WHERE `ID`=23008;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그딴 식으로 우리 어머니를 모독하지 마라!', `MaleText_loc4`='你竟敢辱骂我的妈妈！', `MaleText_loc5`='沒有人敢這樣講我媽!!!', `MaleText_loc7`='¡Nadie habla así de mi madre!' WHERE `ID`=23009;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여보세요, 다르게 생긴 분! 여기 탄자르가 있다는 걸 잊지 말란 말입니다.', `MaleText_loc4`='嗨！你是不是忘记坦扎尔还在这里了？', `MaleText_loc5`='嘿老兄!你不會忘了在這裡的坦札爾吧。', `MaleText_loc7`='¡Hey, colega! No te olvides de Tanzar aquí arriba.' WHERE `ID`=23010;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좀 다르게 생기신 분, 당신이 트롤곰 죽였습니까? 그럼 이제 탄자르 밖으로 나가도 되겠습니까?', `MaleText_loc4`='朋友，你除掉巨魔熊了吗？坦扎尔现在安全了？', `MaleText_loc5`='你殺了食人妖熊嗎，老兄?坦札爾現在出去安全了嗎?', `MaleText_loc7`='¿Has matado al trol oso, colega? ¿Es seguro que Tanzar salga ahora?' WHERE `ID`=23011;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 밖에 누구든 말입니다. 탄자르 목소리 들리는 분 없습니까?', `MaleText_loc4`='嗨，有人吗？', `MaleText_loc5`='嗨。有人聽到坦札爾嗎?', `MaleText_loc7`='Hola. ¿No hay nadie que oiga a Tanzar?' WHERE `ID`=23012;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저라면 눈 깜짝할 사이에 이 자물쇠를 열 수 있습니다. 도망가도 괜찮을 만큼 안전해지면 그냥 와서 말씀만 하십시오.', `MaleText_loc4`='朋友，我就是闭着眼睛也能打开这把锁。你只需告诉我什么时候能安全逃走就行啦。', `MaleText_loc5`='我睡夢中都可以把這個鎖橇開，老兄。只要進來告訴我已經安全了可以出去就好。', `MaleText_loc7`='Podría abrir eh''ta cerradura incluso dormido. Tú solo avísame cuando sea seguro escapar.' WHERE `ID`=23013;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제에에발! 누가 이 불쌍하고 늙은 탄자르를 구해주십시오.', `MaleText_loc4`='救命！谁来救救可怜的坦扎尔！', `MaleText_loc5`='拜託!誰來救救可憐的老坦札爾。', `MaleText_loc7`='¡Poor favooor! ¡Qué alguien salve al pobre Tanzar!' WHERE `ID`=23014;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날로라크는 죽었습니다. 나오셔도 됩니다.', `MaleText_loc4`='纳洛拉克已经死了，你自由了。', `MaleText_loc5`='納羅拉克已經死了，你可以離去了。', `MaleText_loc7`='Nalorakk está muerto, eres libre de irte.', `FemaleText_loc1`='날로라크는 죽었어요. 나오셔도 됩니다.', `FemaleText_loc4`='纳洛拉克已经死了，你自由了。', `FemaleText_loc5`='納羅拉克已經死了，你可以離去了。', `FemaleText_loc7`='Nalorakk está muerto, eres libre de irte.' WHERE `ID`=23015;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고대의 암호가 땅에 떨어집니다.', `MaleText_loc4`='古代密码表落到了地上。', `MaleText_loc5`='上古密碼掉到地上。', `MaleText_loc7`='La clave antigua cae al suelo.' WHERE `ID`=23016;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 역병인도자는 평범한 연금술사보다 조금 더 실용적인 편이지. 결국, 우리가 하는 연구는 역병을 어떻게 잘 퍼트리느냐 하는 것이니 말일세.$B$B그렇다고 우리의 이론적 기반이 부실하다는 말은 아니야. 단지 실무 작업을 더... 좋아할 뿐이지.', `MaleText_loc4`='相比起来，药剂师更强调实践吧。毕竟我们在负责后勤工作的。$B$B这并不代表我们的理论基础知识不够扎实。我们只是……做实事而已。', `MaleText_loc5`='我們瘟疫使者容易比一般的藥劑師再實際一點。畢竟，我們負責瘟疫的散播流程。$B$B這並不表示我們的理論背景不充足，我們只是比較喜歡...親手處理事情。', `MaleText_loc7`='Los pesteadores tendemos a ser ligeramente más prácticos que el boticario medio. Al fin y al cabo nos encargamos de la logística de distribuir la peste.$B$BEso no quiere decir que nuestro trasfondo teórico no sea sólido como una roca. Simplemente preferimos... estar manos a la obra.' WHERE `ID`=23017;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피르주스는 아무것도 두려워하지 않는다! 도전자를 내보내라!', `MaleText_loc4`='芬尔乌斯无所畏惧！让那些斗士上前来吧！', `MaleText_loc5`='佛久斯一無所懼!把戰鬥員放出來!', `MaleText_loc7`='¡Firjus no teme a nada! ¡Soltad a los combatientes!' WHERE `ID`=23018;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕께 바칠 영혼이 더 필요하다! 덤벼라, 미천한 것들아! 덤벼라!', `MaleText_loc4`='巫妖王又能收割更多的灵魂啦！来呀，小子们，来呀！', `MaleText_loc5`='把更多的靈魂獻給巫妖王!來吧，小傢伙!來吧!', `MaleText_loc7`='¡Más almas para el Rey Exánime! ¡Venid, pequeños! ¡Venid!' WHERE `ID`=23019;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저주받은 기사 본 적 있으세요? 그가 여기 나타나면 내가 혼내주고 호박도 빼앗아야지!', `MaleText_loc4`='你见过无头骑士吗？要是他到这里来的话，我会和他战斗，然后偷走他的南瓜！', `MaleText_loc5`='你有看過無頭騎士嗎?如果他到這裡來，我就會與他戰鬥並把他的南瓜偷走!', `MaleText_loc7`='¿Has visto a El Jinete decapitado? ¡Si viene aquí, lucharé con él y le robaré su calabaza!', `FemaleText_loc1`='저주받은 기사 본 적 있으세요? 그가 여기 나타나면 내가 혼내주고 호박도 빼앗아야지!', `FemaleText_loc4`='你见过无头骑士吗？要是他到这里来的话，我会和他战斗，然后偷走他的南瓜！', `FemaleText_loc5`='你有看過無頭騎士嗎?如果他到這裡來，我就會與他戰鬥並把他的南瓜偷走!', `FemaleText_loc7`='¿Has visto a El Jinete decapitado? ¡Si viene aquí, lucharé con él y le robaré su calabaza!' WHERE `ID`=23020;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 물통 속에서 노는 게 좋은데 그건 애들 놀라고 만들어 놓은 게 아니래요.', `MaleText_loc4`='我喜欢在大水桶里划水，但是他们说那不是给孩子们玩的。', `MaleText_loc5`='我喜歡在水桶內玩耍，但是我被警告說這兒童不宜。', `MaleText_loc7`='Me gusta jugar en la barrica de agua, pero me han dicho que no es para niños.', `FemaleText_loc1`='전 물통 속에서 노는 게 좋은데 그건 애들 놀라고 만들어 놓은 게 아니래요.', `FemaleText_loc4`='我喜欢在大水桶里划水，但是他们说那不是给孩子们玩的。', `FemaleText_loc5`='我喜歡在水桶內玩耍，但是我被警告說這兒童不宜。', `FemaleText_loc7`='Me gusta jugar en la barrica de agua, pero me han dicho que no es para niños.' WHERE `ID`=23021;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물통이랑 물동이는 불 끄라고 있는 거래요. 혹시 소방관이세요?', `MaleText_loc4`='他们说这些水桶是灭火用的。你是个消防队员吗？', `MaleText_loc5`='他們說桶子跟籃子是用來救火用的。你是個救火員嗎?', `MaleText_loc7`='Dicen que la barrica y los cubos son para apagar fuegos. ¿Eres bombero?', `FemaleText_loc1`='물통이랑 물동이는 불 끄라고 있는 거래요. 혹시 소방관이세요?', `FemaleText_loc4`='他们说这些水桶是灭火用的。你是个消防队员吗？', `FemaleText_loc5`='他們說桶子跟籃子是用來救火用的。你是個救火員嗎?', `FemaleText_loc7`='Dicen que la barrica y los cubos son para apagar fuegos. ¿Eres bombero?' WHERE `ID`=23022;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저주받은 기사는 소름끼치는 유령들이랑 사람들이랑 같이 붉은십자군 수도원에서 산대요.', `MaleText_loc4`='无头骑士与其他令人毛骨悚然的鬼魂和人类一起住在血色修道院。', `MaleText_loc5`='無頭騎士跟其它所有恐怖的鬼魂還有人們一起住在血色修道院中。', `MaleText_loc7`='El Jinete decapitado vive en el Monasterio Escarlata con los demás fantasmas y humanos aterradores.', `FemaleText_loc1`='저주받은 기사는 소름끼치는 유령들이랑 사람들이랑 같이 붉은십자군 수도원에서 산대요.', `FemaleText_loc4`='无头骑士与其他令人毛骨悚然的鬼魂和人类一起住在血色修道院。', `FemaleText_loc5`='無頭騎士跟其它所有恐怖的鬼魂還有人們一起住在血色修道院中。', `FemaleText_loc7`='El Jinete decapitado vive en el Monasterio Escarlata con los demás fantasmas y humanos aterradores.' WHERE `ID`=23023;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여관에서 사탕이랑 맛있는 걸 준대요! 원장님이 그러시는데 우리한테 사탕 안 주면...장난을 쳐도 된대요!', `MaleText_loc4`='他们正在旅店里分发糖果！守护者格雷沃基说要是他们不给我们糖果……我们就去和他们捣乱！', `MaleText_loc5`='他們在旅店提供糖果及款待!監護人獰眼說如果他們不給我們糖吃...那我們就對他們搗蛋!', `MaleText_loc7`='¡Están dando dulces y regalos en la posada! La guardiana Macabro dice que si no nos dan un regalo... ¡podemos gastarles una broma!', `FemaleText_loc1`='여관에서 사탕이랑 맛있는 걸 준대요! 원장님이 그러시는데 우리한테 사탕 안 주면...장난을 쳐도 된대요!', `FemaleText_loc4`='他们正在旅店里分发糖果！守护者格雷沃基说要是他们不给我们糖果……我们就去和他们捣乱！', `FemaleText_loc5`='他們在旅店提供糖果及款待!監護人獰眼說如果他們不給我們糖吃...那我們就對他們搗蛋!', `FemaleText_loc7`='¡Están dando dulces y regalos en la posada! La guardiana Macabro dice que si no nos dan un regalo... ¡podemos gastarles una broma!' WHERE `ID`=23024;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저주받은 기사 본 적 있어요? 원장님이 그자가 나타나면 쳐다보지 말래요. 안 그러면 우리를 호박으로 만든대요!', `MaleText_loc4`='你见过无头骑士吗？守护者格雷沃基说，如果他出现了的话，千万不要看他，否则他会把我变成南瓜！', `MaleText_loc5`='你有看過無頭騎士嗎?監護人說如果我看著他，他就會把我變成一顆南瓜!', `MaleText_loc7`='¿Has visto a El Jinete decapitado? La Matrona dice que si le miro, me convertirá en una calabaza.', `FemaleText_loc1`='저주받은 기사 본 적 있어요? 원장님이 그자가 나타나면 쳐다보지 말래요. 안 그러면 우리를 호박으로 만든대요!', `FemaleText_loc4`='你见过无头骑士吗？守护者格雷沃基说，如果他出现了的话，千万不要看他，否则他会把我变成南瓜！', `FemaleText_loc5`='你有看過無頭騎士嗎?監護人說如果我看著他，他就會把我變成一顆南瓜!', `FemaleText_loc7`='¿Has visto a El Jinete decapitado? La Matrona dice que si le miro, me convertirá en una calabaza.' WHERE `ID`=23025;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물통에서 물동이를 채우세요. 뿌리면 재미있거든요!', `MaleText_loc4`='你可以在大水桶里打满一桶水。泼水真有趣！', `MaleText_loc5`='你可以在水桶那裝滿一桶子水。潑水很好玩!', `MaleText_loc7`='Puedes llenar un cubo en la barrica de agua. ¡Es divertido salpicar!', `FemaleText_loc1`='물통에서 물동이를 채우세요. 뿌리면 재미있거든요!', `FemaleText_loc4`='你可以在大水桶里打满一桶水。泼水真有趣！', `FemaleText_loc5`='你可以在水桶那裝滿一桶子水。潑水很好玩!', `FemaleText_loc7`='Puedes llenar un cubo en la barrica de agua. ¡Es divertido salpicar!' WHERE `ID`=23026;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아싸! 탄자르 자유입니다!', `MaleText_loc4`='呜哈！坦扎尔自由了！', `MaleText_loc5`='哇呼!坦札爾自由了!', `MaleText_loc7`='¡Yuju! ¡Tanzar es libre!' WHERE `ID`=23027;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이전에 스톰윈드에서 온 병사 아저씨들이 불길에 맞서 싸우는 것을 보았어요. 저도 크면 그 아저씨들처럼 될래요!', `MaleText_loc4`='我看到暴风城来的士兵们在灭火。他们是英雄！', `MaleText_loc5`='我看過之前一群來自暴風城的士兵救過火。他們是英雄!', `MaleText_loc7`='Antes he visto soldados de Ventormenta apagando un fuego. ¡Eran héroes!', `FemaleText_loc1`='이전에 스톰윈드에서 온 병사 아저씨들이 불길에 맞서 싸우는 것을 보았어요. 진짜 정의의 기사 같았어요!', `FemaleText_loc4`='我看到暴风城来的士兵们在灭火。他们是英雄！', `FemaleText_loc5`='我看過之前一群來自暴風城的士兵救過火。他們是英雄!', `FemaleText_loc7`='Antes he visto soldados de Ventormenta apagando un fuego. ¡Eran héroes!' WHERE `ID`=23028;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저주받은 기사는 붉은십자군 수도원에서 살고 있대요. 가끔 밖으로 나오면 어른들까지 겁먹지만, 전 아니에요!', `MaleText_loc4`='无头骑士居住在血色修道院。有时候他会出来吓唬小孩子，但我不怕！', `MaleText_loc5`='無頭騎士住在血色修道院。有時候他會出來嚇嚇大人們，不過不是我!', `MaleText_loc7`='El Jinete decapitado vive en el Monasterio Escarlata. A veces viene y asusta a los mayores, pero a mí no.', `FemaleText_loc1`='저주받은 기사는 붉은십자군 수도원에서 살고 있대요. 가끔 밖으로 나오면 어른들도 벌벌 떨지만, 전 끄떡도 안 해요!', `FemaleText_loc4`='无头骑士居住在血色修道院。有时候他会出来吓唬小孩子，但我不怕！', `FemaleText_loc5`='無頭騎士住在血色修道院。有時候他會出來嚇嚇大人們，不過不是我!', `FemaleText_loc7`='El Jinete decapitado vive en el Monasterio Escarlata. A veces viene y asusta a los mayores, pero a mí no.' WHERE `ID`=23029;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예전엔 여관에서 사탕을 얻었거든요. 더 받고 싶지만 이 썩는다고 안 된대요.', `MaleText_loc4`='我从旅店那里得到了一些糖果！不过我还想要更多！', `MaleText_loc5`='我以前跟旅店要到一些糖果。我等不及去要更多的糖了!', `MaleText_loc7`='Antes me han dado dulces en la posada. ¡No puedo esperar a que me den más!', `FemaleText_loc1`='예전엔 여관에서 사탕을 얻었거든요. 더 받고 싶지만 살찐다고 안 된대요.', `FemaleText_loc4`='我从旅店那里得到了一些糖果！不过我还想要更多！', `FemaleText_loc5`='我以前跟旅店要到一些糖果。我等不及去要更多的糖了!', `FemaleText_loc7`='Antes me han dado dulces en la posada. ¡No puedo esperar a que me den más!' WHERE `ID`=23030;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='운이 좋았군요! 여기 있는 게 탄자르 물건 같습니다...', `MaleText_loc4`='太幸运了！这不是坦扎尔的东西吗……', `MaleText_loc5`='真幸運!這裡有一個坦札爾的東西...', `MaleText_loc7`='¡Qué suerte! Esta es una de las posesiones de Tanzar...' WHERE `ID`=23031;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 받으십시오. 당신에게 주는 선물입니다. 탄자르의 멋진 탈출을 축하하자는 뜻입니다!', `MaleText_loc4`='好啦。这是给你的礼物，庆祝坦扎尔的顺利逃脱！', `MaleText_loc5`='東西現在就在那裡。一份給你的禮物，慶祝坦札爾的大逃脫!', `MaleText_loc7`='Toma. ¡Un regalo pa'' ti, pa'' celebrar la gran huida de Tanzar!' WHERE `ID`=23032;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 왼쪽으로 조금 더... 아니, 아니야, 그래, 그렇지...', `MaleText_loc4`='再往左一点——不，不，往右……', `MaleText_loc5`='現在往左邊一點點 - 不，不，右邊...', `MaleText_loc7`='Un poco más a la izquierda, no, no, derecha...' WHERE `ID`=23033;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음음... 왼쪽, 오른쪽, 돌리고, 누르면...', `MaleText_loc4`='唔……左转、右转、扭一扭、按下去……', `MaleText_loc5`='嗯嗯...左邊，右邊，擺動，按壓...', `MaleText_loc7`='Hrmm... izquierda, derecha, menea, aprieta...' WHERE `ID`=23034;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 조금만 더 깊이... 거의 다 됐습니다...', `MaleText_loc4`='再深一点——快好啦……', `MaleText_loc5`='再深一點 - 快拿到了...', `MaleText_loc7`='Un poco más profundo. Ya casi lo tengo...' WHERE `ID`=23035;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고통의 소굴로...', `MaleText_loc4`='进入那座洞穴吧，它就是痛苦之源……', `MaleText_loc5`='深入痛苦的深淵...', `MaleText_loc7`='A la guarida del sufrimiento...' WHERE `ID`=23036;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자 봅시다, 누르고, 흔들고, 돌리고, 돌리면...', `MaleText_loc4`='让我看看，按下去、扭一扭、我转、我再转……', `MaleText_loc5`='現在就讓我們來瞧瞧，壓一壓，搖一搖，轉，轉...', `MaleText_loc7`='Veamos, aprieta, agita, gira, gira...' WHERE `ID`=23037;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 하나의 영혼이 스컬지에 합류한다!', `MaleText_loc4`='啧啧，新鲜的灵魂！', `MaleText_loc5`='又一個給天譴軍的靈魂!', `MaleText_loc7`='¡Otra alma para la Plaga!' WHERE `ID`=23038;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='육신은 저 아래 비참한 노예들의 먹이지...', `MaleText_loc4`='下面那些卑贱的奴隶有肉吃啦……', `MaleText_loc5`='這是給底下悲慘奴隸的血肉...', `MaleText_loc7`='Carne para los miserables esclavos de abajo...' WHERE `ID`=23039;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='약해... 최하급 언데드밖에 못 되겠어. 구덩이에 처넣어라!', `MaleText_loc4`='太弱了……只配喂给下面那些卑贱的亡灵。扔下去！', `MaleText_loc5`='弱小...只配最低等的不死生物。丟進坑裡!', `MaleText_loc7`='Debilidad... Solo apta para los más miserables no-muertos. ¡Al foso!' WHERE `ID`=23040;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 약해졌습니다!', `FemaleText_loc4`='%s显得非常虚弱！', `FemaleText_loc5`='%s看起來很虛弱!', `FemaleText_loc7`='¡%s parece débil!' WHERE `ID`=23041;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='감사합니다. 자매들을 다시 만나지도 못하고 죽는 줄 알았어요!', `FemaleText_loc4`='谢谢你。我还以为我再也见不到我的姐妹啦！', `FemaleText_loc5`='謝謝你，我想我要是沒看見我的姊妹們，我就死定了!', `FemaleText_loc7`='Gracias. ¡Creí que moriría sin volver a ver a mis hermanas!' WHERE `ID`=23042;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기가 어디죠? 난 어떻게 된 거죠? 당신이... 날 구해준 건가요?', `FemaleText_loc4`='我在哪里？发生了什么事？是你……救了我？', `FemaleText_loc5`='這是哪裡?我發生了什麼事?你...你救了我嗎?', `FemaleText_loc7`='¿Dónde estoy? ¿Qué me ha pasado? Me... ¿me has liberado?' WHERE `ID`=23043;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='루리엘이 도와줄 줄 알았어요! 감사합니다, 친구여. 루리엘에게도 고맙다고 전해주세요!', `FemaleText_loc4`='我就知道鲁莉尔蕾会派人来救我的！谢谢你，朋友，也帮我谢谢鲁莉尔蕾！', `FemaleText_loc5`='我就知道露麗兒會派救兵來!謝謝你，朋友，同時向露麗兒送上我的感謝!', `FemaleText_loc7`='¡Sabía que Lurielle enviaría ayuda! ¡Te lo agradezco y dale a Lurielle las gracias de mi parte también!' WHERE `ID`=23044;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디 볼까나, 누르고, 흔들고, 돌리고, 돌리면...', `MaleText_loc4`='让我看看，按下去、扭一扭、我转、我再转……', `MaleText_loc5`='現在就讓我們來瞧瞧，壓一壓，搖一搖，轉，轉...', `MaleText_loc7`='Veamos, aprieta, agita, gira, gira...' WHERE `ID`=23045;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네에게 너무나도 감사하고 있네, $c.$b$b내가 자네를 위해 할 일이 있다면 편하게 이야기하게.', `MaleText_loc4`='$c，谢谢你。$b$b要是有什么事我能帮上忙的，尽管开口。', `MaleText_loc5`='由衷地感謝你，$c。$b$b如果有任何需要我的地方，盡管跟我說。', `MaleText_loc7`='Tienes mi gratitud, $c.$B$BSi hay algo que pueda hacer por ti, tan solo dilo.' WHERE `ID`=23046;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이젠 안전하오? 누군가가 그 트롤괴물을 해치웠소?', `MaleText_loc4`='安全了吗？是谁杀死了巨魔？', `MaleText_loc5`='安全嗎?誰殺了這隻食人妖野獸?', `MaleText_loc7`='¿Es seguro? ¿Quién ha matado a las bestias trol?' WHERE `ID`=23047;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크라즈 살았소!', `MaleText_loc4`='克拉斯捡回了一条命！', `MaleText_loc5`='卡拉茲還活著!', `MaleText_loc7`='¡Kraz vive!' WHERE `ID`=23048;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크라즈에게 가까이 오시오. 이 고마운 마음을 받아 주시오.', `MaleText_loc4`='到克拉斯这里来吧，接受我的感谢。', `MaleText_loc5`='去找卡拉茲。接受我的謝意。', `MaleText_loc7`='¡Venid con Kraz! Aceptad mi gratitud.' WHERE `ID`=23049;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엄청난 트롤 괴물 처치하신 분들을 크라즈는 만나야 하오!', `MaleText_loc4`='克拉斯肯定是遇到了伟大的巨魔克星！', `MaleText_loc5`='卡拉茲一定要見見殺掉這個大型食人妖野獸的人!', `MaleText_loc7`='¡Kraz debe conocer a los asesinos de la gran bestia trol!' WHERE `ID`=23050;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 구해주신 분들! 이리 와서 크라즈와 얘기 좀 나눠 보시겠소.', `MaleText_loc4`='我的英雄！过来和克拉斯谈谈。', `MaleText_loc5`='我的救星!過來跟卡拉茲談談。', `MaleText_loc7`='¡Mis liberadores! Venid a hablar con Kraz.' WHERE `ID`=23051;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='탐험가 연맹의 배려로 여기 따라올 수 있었어요. 비틀린 숲과 주변 지역이 이렇게 위험한 것을 보니, 도움 없이 혼자 왔다가는 큰일이 날 뻔했군요.', `FemaleText_loc4`='探险者协会允许我跟他们一起来真是太好了。但是裂木森林和周边区域实在是太危险，我没带帮手就闯了进来，真是蠢到家了。', `FemaleText_loc5`='探險者協會真好心，願意讓我一路跟著。可是，裂木森林和附近地區危險重重，孤立無援的我看起來真像傻瓜。', `FemaleText_loc7`='Fue todo un detalle por parte de la Liga de Expedicionarios permitirme ir con ellos. De todas formas, con los riesgos de El Bosque Hendido y alrededores, parece que venir sin ayuda habría sido una locura.' WHERE `ID`=23052;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저도 저주받은 기사와 싸우는 데 힘을 보태고 싶지만요... 그림워치 선생님이 허락을 안 하실 거예요!', `MaleText_loc4`='我想去帮他们打败无头骑士，但是老格雷沃基不让我去！', `MaleText_loc5`='我想要幫忙擊退無頭騎士，不過老獰眼不準我去!', `MaleText_loc7`='¡Quería ayudar a luchar contra El Jinete decapitado, pero el viejo Macabro no me ha dejado!', `FemaleText_loc1`='저도 저주받은 기사와 싸우는 데 힘을 보태고 싶지만... 그림워치 선생님이 허락을 안 하실 거예요!', `FemaleText_loc4`='我想去帮他们打败无头骑士，但是老格雷沃基不让我去！', `FemaleText_loc5`='我想要幫忙擊退無頭騎士，不過老獰眼不準我去!', `FemaleText_loc7`='¡Quería ayudar a luchar contra El Jinete decapitado, pero el viejo Macabro no me ha dejado!' WHERE `ID`=23053;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음번에 저주받은 기사가 오면 또 함께 무찔러요!', `MaleText_loc4`='无头骑士下次再过来的话，我们同样会再次打败他！', `MaleText_loc5`='無頭騎士捲土重來的時候，我們會再次擊敗他的!', `MaleText_loc7`='¡La próxima vez que venga El Jinete decapitado volveremos a machacarlo!', `FemaleText_loc1`='다음번에 저주받은 기사가 오면 또 함께 무찔러요!', `FemaleText_loc4`='无头骑士下次再过来的话，我们同样会再次打败他！', `FemaleText_loc5`='無頭騎士捲土重來的時候，我們會再次擊敗他的!', `FemaleText_loc7`='¡La próxima vez que venga El Jinete decapitado volveremos a machacarlo!' WHERE `ID`=23054;
