UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은늑대 위장복을 잃어버렸습니다.', `MaleText_loc4`='我弄丢了座狼伪装服。', `MaleText_loc5`='我弄丟了我的座狼偽裝。', `MaleText_loc7`='He perdido mi disfraz de huargo.', `FemaleText_loc1`='검은늑대 위장복을 잃어버렸어요.', `FemaleText_loc4`='我弄丢了座狼伪装服。', `FemaleText_loc5`='我弄丟了我的座狼偽裝。', `FemaleText_loc7`='He perdido mi disfraz de huargo.' WHERE `ID`=23068;
