UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 그걸 잃어버릴 수 있나? 할 수 없군. 이번에는 절대 잃어버리지 말게.', `MaleText_loc4`='怎么会弄丢呢？好吧好吧，别再弄丢了。', `MaleText_loc5`='怎麼可能會搞丟?好吧，但不要連這個也搞丟了。', `MaleText_loc7`='¿Cómo has podido perderlo? Muy bien, pero procura no "perder" este también.' WHERE `ID`=23070;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실험에 실패한 혼합물이 바닥에 엎질러지자 살아서 움직입니다!', `MaleText_loc4`='调配失败的混合物溅到了地板上，呈现出了奇特的生命迹象！', `MaleText_loc5`='失敗的混和物濺了一地，而且好像活了起來!', `MaleText_loc7`='¡El brebaje inservible cae al suelo y parece cobrar vida!' WHERE `ID`=23071;
