UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='겨울발굽 야영지를 그리워하겠지만 애쉬토템 족장님께서 이런 결정을 내린 까닭은 이해한답니다. 고향이 주는 편안함을 죽을 때까지 누릴 수는 없는 법이지요.', `FemaleText_loc4`='我会很想念冬蹄营地的，但是我能理解灰烬图腾酋长做出的决定。我们没有能力永远维持家园这个温暖的港湾。', `FemaleText_loc5`='我會想念冬蹄營地的，但我瞭解為何灰燼圖騰酋長做了這個決定。家就是那個無法永遠負擔起的安逸之所。', `FemaleText_loc7`='Voy a echar de menos el Campamento Pezuña Invernal, pero comprendo por qué ha tomado esta decisión el Cabecilla Tótem de Ceniza. El hogar es una comodidad que no siempre podemos permitirnos.' WHERE `ID`=23073;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<난도질당해 바닥에 널브러진 신 아가만드 연금술사의 시체입니다.>', `MaleText_loc4`='<地上躺着一具新阿加曼德药剂师残缺不全的尸体。>', `MaleText_loc5`='<這裡躺了一具血肉糢糊的新阿加曼德藥劑師屍體。>', `MaleText_loc7`='<Aquí yace el cuerpo destrozado de uno de los boticarios de Nuevo Agamand.>' WHERE `ID`=23074;
