UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 우트가드 성채에서, 잉그바르 님 곁에서 싸우고 있어야 했다! 그런데 너 같은 구더기나 막고 있단 말이지.', `MaleText_loc4`='我本应该呆在乌特加德城堡，与因格瓦尔并肩作战的！现在却被派来对付你这样的废物。', `MaleText_loc5`='我應該在俄特加德要塞中，和因格瓦並肩作戰!但是，我卻負責看守你這樣的蛆蟲。', `MaleText_loc7`='¡Debería estar en la Fortaleza de Utgarde, luchando junto a Ingvar! Sin embargo me encargan cuidar de pequeños gusanos como tú.' WHERE `ID`=23076;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 널 그냥 죽이지 않는지 이해할 수가 없군.', `MaleText_loc4`='为什么不直接杀掉你呢，真是奇怪。', `MaleText_loc5`='為什麼我們不殺了你就得了，這實在超乎我的理解。', `MaleText_loc7`='No consigo comprender por qué no te matamos.' WHERE `ID`=23077;
