UPDATE `locales_broadcast_text` SET `MaleText_loc1`='브리쿨의 피를 순수하게 보존하자!', `MaleText_loc4`='一定要保持维库人纯正的血统！', `MaleText_loc5`='維酷族必須保持純淨!', `MaleText_loc7`='¡Vrykul debe permanecer puro!', `FemaleText_loc1`='브리쿨의 피를 순수하게 보존하자!', `FemaleText_loc4`='一定要保持维库人纯正的血统！', `FemaleText_loc5`='維酷族必須保持純淨!', `FemaleText_loc7`='¡Vrykul debe permanecer puro!' WHERE `ID`=23127;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왕이시여, 자비를 베푸소서! 그들은 우리의 혈육입니다!', `MaleText_loc4`='我的国王，手下留情！那是我们的骨肉啊！', `MaleText_loc5`='饒他們一命吧，吾王!他們是我們的手足啊!', `MaleText_loc7`='¡Ten piedad, mi rey! ¡Son de nuestra misma sangre!', `FemaleText_loc1`='왕이시여, 자비를 베푸소서! 그들은 우리의 혈육입니다!', `FemaleText_loc4`='我的国王，手下留情！那是我们的骨肉啊！', `FemaleText_loc5`='饒他們一命吧，吾王!他們是我們的手足啊!', `FemaleText_loc7`='¡Ten piedad, mi rey! ¡Son de nuestra misma sangre!' WHERE `ID`=23128;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들이 우리를 약해지게 한다! 그 존재만으로 우리의 힘이 꺾인다! 그들을 모두 없애라!', `MaleText_loc4`='它们是祸害！维库人的力量会因它们的存在而削弱！杀掉它们！', `MaleText_loc5`='他們弱化了我們!我們的力量因為他們的存在而被稀釋了!殺光他們!', `MaleText_loc7`='¡Nos debilitan! ¡Su existencia diluye nuestra fuerza! ¡Destruidlos a todos!', `FemaleText_loc1`='그들이 우리를 약해지게 한다! 그 존재만으로 우리의 힘이 꺾인다! 그들을 모두 없애라!', `FemaleText_loc4`='它们是祸害！维库人的力量会因它们的存在而削弱！杀掉它们！', `FemaleText_loc5`='他們弱化了我們!我們的力量因為他們的存在而被稀釋了!殺光他們!', `FemaleText_loc7`='¡Nos debilitan! ¡Su existencia diluye nuestra fuerza! ¡Destruidlos a todos!' WHERE `ID`=23129;
