UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왕께서 말씀하신다!', `MaleText_loc4`='国王有话要说！', `MaleText_loc5`='國王要說話了!', `MaleText_loc7`='¡El rey va a hablar!', `FemaleText_loc1`='왕께서 말씀하신다!', `FemaleText_loc4`='国王有话要说！', `FemaleText_loc5`='國王要說話了!', `FemaleText_loc7`='¡El rey va a hablar!' WHERE `ID`=23132;
