UPDATE `locales_broadcast_text` SET `MaleText_loc1`='브리쿨이여, 그대들의 왕이 하는 말에 귀 기울여라!', `MaleText_loc4`='维库人，国王恳请你们安静下来！', `MaleText_loc5`='維酷人，你的王懇求你聆聽!', `MaleText_loc7`='¡Vrykuls, su rey los implora que escuchen!' WHERE `ID`=23134;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신은 우리를 버렸다!', `MaleText_loc4`='神灵抛弃了我们！', `MaleText_loc5`='諸神遺棄我們了!', `MaleText_loc7`='¡Los dioses nos han abandonado!' WHERE `ID`=23135;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='청중이 공포에 질려 숨을 들이켭니다.', `MaleText_loc4`='人群在惊惶中骚动起来。', `MaleText_loc5`='群眾嚇得倒抽一口氣。', `MaleText_loc7`='La multitud grita aterrorizada.' WHERE `ID`=23136;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 지금, 가장 절박한 이 시대에조차 신은 우리를 기만했노라!', `MaleText_loc4`='在最黑暗的时刻，他们依然不忘嘲笑我们！', `MaleText_loc5`='即使到了現在，我們最黑暗的時刻，他們仍然一直嘲弄我們!', `MaleText_loc7`='¡Incluso ahora, en nuestro momento de más necesidad, se burlan de nosotros!' WHERE `ID`=23137;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 티탄을 가장 절실히 찾는 이때 그들은 어디에 있는가? 우리의 여인들은 두 발로 혼자 설 수조차 없는, 꼴사나운 기형아들을 낳고 있다. 약하고, 추하고... 쓸모없는 것들을...', `MaleText_loc4`='在我们最需要泰坦指引的时候，他们又在哪儿呢？氏族诞生了畸形的胎儿，它们面貌丑陋，甚至无法站立！又丑又弱……一无是处……', `MaleText_loc5`='當我們最需要泰坦的時候，他們在哪兒?我們的女人生下了畸形兒 - 醜陋的矮個兒，連站都站不穩!又弱又醜...一無是處...', `MaleText_loc7`='¿Dónde están los titanes cuando más los necesitamos? ¡Nuestras mujeres dan a luz aberraciones, enanos desfigurados incapaces de mantenerse de pie! Débiles y feos... Inútiles...' WHERE `ID`=23138;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이미론은 고뇌했다. 왕좌에 오래도록 앉아 왜 우리가 이런 곤경에 처했는지 깊이 고민했다. 해답은... 이유는... 단 하나뿐이다...', `MaleText_loc4`='伊米隆身心疲惫。自从我坐上王位，就一直在思考为什么维库人的生活如此艰难。答案只有一个……只有一个……', `MaleText_loc5`='依米倫備嘗艱辛。長久以來，我坐在王位上，苦思力索著我們的苦難。只有一個答案...一個理由...', `MaleText_loc7`='Ymiron ha trabajado duro. Largo tiempo he pasado sentado en mi trono pensando en nuestra apremiante situación. Solo hay una respuesta... una razón...' WHERE `ID`=23139;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='티탄 외에 그 누가 그런 저주를 내릴 수 있는가? 무엇이 그런 강력한 힘을 가질 수 있는가?', `MaleText_loc4`='除了泰坦，还有谁能对我们下这样的诅咒？谁能拥有那样的力量？', `MaleText_loc5`='除了泰坦以外還有誰能降下這種詛咒?還有什麼可以擁有這種力量?', `MaleText_loc7`='¿Pues quién, además de los propios titanes, podría condenar a tal maldición? ¿Qué podría tener tanto poder?' WHERE `ID`=23140;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해답은 없다... 우리에게 저주를 내린 건 바로 티탄이기 때문이다!', `MaleText_loc4`='没有……是泰坦诅咒了我们！', `MaleText_loc5`='這問題沒有答案...因為是泰坦詛咒我們的!', `MaleText_loc7`='Y la respuesta es nada... ¡Pues son los titanes quienes nos han maldecido!' WHERE `ID`=23141;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='청중이 여기저기서 시끄럽게 떠들어댑니다.', `MaleText_loc4`='人群喧闹起来。', `MaleText_loc5`='群眾嘩然。', `MaleText_loc7`='La multitud aplaude.' WHERE `ID`=23142;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 이 순간부터 모든 브리쿨은 낡은 믿음을 버린다! 우리는 더는 해묵은 신을 섬기지 않을 것이다! 모든 브리쿨은 이미론에게 충성을 다하라! 이미론이 고귀한 우리 종족을 보호할 것이다!', `MaleText_loc4`='今天，所有的维库人都将抛弃过去的信仰！废除我们曾经信奉的神灵！维库人将效忠伊米隆国王！伊米隆会保护我们的！', `MaleText_loc5`='就在這一天，所有的維酷族人背棄了他們原有的信仰!我們廢除了古老的諸神!所有的維酷族宣示效忠依米倫!依米倫會保護我們高貴的種族!', `MaleText_loc7`='¡En este día todos los vrykuls olvidarán sus antiguas creencias! ¡Renunciaremos a nuestros dioses antiguos! ¡Todos los vrykuls jurarán lealtad a Ymiron! ¡Ymiron protegerá nuestra noble raza!' WHERE `ID`=23143;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='청중이 환호합니다.', `MaleText_loc4`='人群欢呼起来。', `MaleText_loc5`='群眾歡呼。', `MaleText_loc7`='La multitud aclama.' WHERE `ID`=23144;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 브리쿨에게 첫 번째 명령을 내리겠노라! 브리쿨의 어버이가 낳은 모든 기형아는 태어나는 즉시 제거한다! 우리의 피를 반드시 순수하게 보존해야 한다! 이미론의 명령을 어기는 자는 샬레르브론으로 보내 처형할 것이다!', `MaleText_loc4`='现在，我颁布第一道法令！所有维库人畸形婴儿一出生就要立即被处死！我们必须保证血统的纯正！违抗伊米隆国王的法令的维库人将被带往亚勒伯龙处决！', `MaleText_loc5`='這就是我給維酷人頒布的第一條法令!由維酷人父母所生下的畸形寶寶都將在出生後處死!我們的血脈必須永保純正!凡違反依米倫法令者將被帶往夏勒布隆處斬!', `MaleText_loc7`='¡Y ahora mi primer decreto para los vrykuls! Todos los infantes nacidos de padre y madre vrykuls que presenten deformaciones deberán ser destruidos en el momento del nacimiento. ¡Nuestra sangre ha de permanecer siempre pura! ¡Quienes sean descubiertos violando el decreto de Ymiron serán llevados a Gjalerbron para su ejecución!' WHERE `ID`=23145;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 이를 드러내고 웃습니다.', `MaleText_loc4`='%s咧嘴一笑。', `MaleText_loc5`='%s邪惡地笑了笑。', `MaleText_loc7`='%s sonríe.' WHERE `ID`=23146;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 주술의 냄새가 나는구나... 그 덕에 여기까지 왔나 보군. 한때는, 나도 주술사였지.', `MaleText_loc4`='萨满的精魂将你带来了这里……我能感应到空气中涌动着那种力量。*巫妖王大笑起来* 我也曾是个萨满祭司。', `MaleText_loc5`='薩滿之道引領你到了這裡...空氣中瀰漫著那股味道。*巫妖王大笑*我也曾是個薩滿。', `MaleText_loc7`='El chamanismo te trajo aquí... Su esencia impregna el aire. *El Rey Exánime ríe* Yo era un chamán.' WHERE `ID`=23147;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니. 이자는 아직 멀었어.', `MaleText_loc4`='不，我的仆从。这一个还没有准备好。', `MaleText_loc5`='不，我的僕從，這傢伙還沒準備好。', `MaleText_loc7`='No, lacayo. No está listo.' WHERE `ID`=23148;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필멸의 존재여, 내게서 죽음이 느껴지느냐? 그 죽음은 내가 만지는 모든 것을 덮치지. 손가락만 까딱해도, 네 영혼은 지옥에 떨어져 영원히 괴로움에 몸부림칠 것이다.', `MaleText_loc4`='你感觉到了吗，凡人？死亡之力从我的每一寸皮肤上渗透出来，覆盖了所有我碰触过的事物。只要我的手指轻轻一触，你的灵魂就将在诅咒中永远地凋零消逝。', `MaleText_loc5`='凡人，你感受到了嗎?死亡從我身上滲透而出，我所觸及之處盡遭吞噬。彈指之間你的靈魂就會永遠在詛咒中凋零。', `MaleText_loc7`='¿Lo sientes, mortal? En mano muerte que cubre todo lo que toco. Con un solo chasquido de mis dedos tu alma se podrirá condenada por toda la eternidad.' WHERE `ID`=23149;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만... 아직은 리치 왕을 섬길 때가 아니다... 그래... 더 큰 운명이 너를 기다린다. 힘을... 나를 섬기기 전에, 너는 더 큰 힘을 길러야 한다.', `MaleText_loc4`='但……现在还不是让你为巫妖王效力的时候。是的，更伟大的命运还在等待着你。力量……在你为我效劳之前，你必须获得更多的力量。', `MaleText_loc5`='但是...你侍奉巫妖王的時候未到。是的，更偉大的命運正等待著你。力量...要侍奉我之前，你必須獲得更多的力量。', `MaleText_loc7`='Pero, aún no es tu hora de servir al Rey Exánime. Sí, un destino mayor te espera. Poder... tienes que volverte más poderoso para servirme.' WHERE `ID`=23150;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보아라, 발키르. 내가 이자를 움켜쥐는 것을 보아라. 아직 여물지 않았다는 걸 알겠느냐? 이 존재가 꽃피고, 말라 비틀어져 떨어지는 것을 보아라.', `MaleText_loc4`='看仔细了，瓦格里。看我如何施压。你瞧，它还没有成熟呢。接着它就会爆裂，毫无生气地陨落。', `MaleText_loc5`='看著，華爾琪。看著我施加壓力。你有發現它還沒成熟嗎?看著它爆裂，失去生氣地倒下吧。', `MaleText_loc7`='Ahora observa, val''kyr. Observa como aplico presión. ¿Puedes ver que aún no está listo? Observa como rebota sin vida en el suelo.' WHERE `ID`=23151;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저자를 원하십니까, 폐하?', `FemaleText_loc4`='需要为您准备好一切吗？', `FemaleText_loc5`='陛下，我們要為您準備好嗎?', `FemaleText_loc7`='¿Se lo preparamos, mi señor?' WHERE `ID`=23152;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 만세로군요. 여러분이 그 사악한 트롤을 제때에 해치우고 하릴없이 살해될뻔한 저를 구해주시고, 노예가 되어 아제로스를 삼키는 그들의 사악한 음모에 힘을 더할 뻔한 제 순결한 작은 영혼을 지켜주신데다 목숨을 걸고 완전히 죽을뻔한 저를 구해 내신 것을 보고나니 어떤 분이건 어디에서 오신 분이건 저를 여기에서 구해 내신 그 친절함에 보답을 해드려야 할 것이며 보답해드릴 방도를 찾고자 온 힘을 기울일 거예요...$B$B<숨을 깊게 들이마시는 아쉴리.>$B$B여러분이 사탕을 좋아하셨으면 좋겠는데요...', `FemaleText_loc4`='哇噢——你杀死了巨魔坏蛋不仅挽救了我的性命使我幼小而纯洁的灵魂免遭奴役还粉碎了他们企图利用我的力量来帮助他们统治艾泽拉斯世界的邪恶计划你冒着生命危险将我从死亡的边缘拉了回来因此不管你是谁也不管你从哪儿来我都要好好地报答你的救命之恩你相信我啦我会竭尽所能地报答你的……$b$b<阿什莉深深地吸了口气。>$b$b我希望你会喜欢糖果……', `FemaleText_loc5`='喔耶 - 你適時的殺了那個壞食人妖好讓我不會被無助的殺害並解救了我這無辜的小靈魂又破壞了他們想要統治艾澤拉斯的邪惡陰謀並又見試到你是如何冒險解救我遠離必死的境界我一定要回報你的仁慈無論你是誰或是從哪來的所以我幫逃出這裡我將會盡我所能的去找方法酬謝你...$b$b<阿西利深深地吸了一口氣。>$b$b我希望你會喜歡糖果...', `FemaleText_loc7`='¡Oh hurra! Has matado al trol malo justo a tiempo de salvarme de ser asesinada y de que mi inocente alma fuera esclavizada y utilizada para añadir más poder a su malvado plan para conquistar Azeroth y viendo como has arriesgado tu vida para salvarme de una muerte segura debo compensarte por tu bondad independientemente de quién seas o de dónde hayas venido para ayudarme a salir de aquí y haré lo posible por recompensarte...$B$B<Ashli respira hondo.>$B$BEspero que te gusten los dulces...' WHERE `ID`=23153;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 안전하다고, 꼬마 노움양. 이제 밖으로 나와도 돼.', `MaleText_loc4`='安全了，小侏儒。你现在可以出来了。', `MaleText_loc5`='安全了，小地精。你現在可以出來了。', `MaleText_loc7`='Es seguro, pequeño gnomo. Puedes salir.', `FemaleText_loc1`='이제 안전해요, 꼬마 노움양. 이제 밖으로 나와도 돼요.', `FemaleText_loc4`='安全了，小侏儒。你现在可以出来了。', `FemaleText_loc5`='安全了，小地精。你現在可以出來了。', `FemaleText_loc7`='Es seguro, pequeño gnomo. Puedes salir.' WHERE `ID`=23154;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러죠. 근처에 있던 드워프 시체에서 찾은 것입니다.', `MaleText_loc4`='当然。我是在附近一具矮人的尸体上找到的。', `MaleText_loc5`='當然了，我是在附近一具矮人的屍體上找到的。', `MaleText_loc7`='Claro. Lo encontré en el cadáver de un enano aquí cerca.' WHERE `ID`=23155;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='야호호호호! 당신이 그렇게 커다랗고 못된 트롤을 때려눕혔다니 정말 멋진 일이고요, 이 우리 손잡이에 제 키가 안 닿는다는 게 정말로 진짜 나쁜 일인 까닭은 안 그랬더라면 제가 뛰어올라서 그 녀석을 산산조각 내버린 후에 다른 불쌍한 수감자들을 모두 죽이고 저를 그토록 겁에 질리게 한 대가를 치르게 했을 거니까... 아 그런데 당신에게 뭔가 더 부탁한다는 게 미안하긴 하지만 이리 오셔서 저 좀 꺼내주실 수 있을까요?', `FemaleText_loc4`='哇！你是怎么把那个大个子的巨魔坏蛋撂翻在地的呀可惜我连这个笼子的把手都够不着不然我肯定会跳到他身上狠狠地揍他一顿我要为那些惨死在他手中的俘虏报仇这个坏蛋可把我吓得够呛你帮了我这么大的忙我其实挺不好意思的不过能麻烦你过来打开牢笼吗？', `FemaleText_loc5`='唷耶!真是太驚奇了你是如何像那樣把那個大壞蛋食人妖打倒在地的我沒辦法碰到這個籠子的把手真是太糟了否則我就會跳進去然後揍他一頓好向他討回殺害其他可憐囚犯還有那麼壞的嚇唬我的公道雖然我覺得向你要求幫忙不太好不過你可以過來放我出去嗎?', `FemaleText_loc7`='¡Guay! Ha sido increíble como has machacado a ese gran trol malo y es una pena que yo no pueda alcanzar la manilla de esta jaula o hubiera saltado y le hubiera pegado una paliza por matar a los demás pobres prisioneros y asustarme tanto y me siento mal por pedirte más ayuda pero ¿podrías venir y sacarme de aquí?' WHERE `ID`=23156;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 여기 있습니다.', `MaleText_loc4`='当然。', `MaleText_loc5`='當然。', `MaleText_loc7`='Por supuesto.' WHERE `ID`=23157;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='음음... 그러니까 당신이 천천히 숨을 고르고 그렇게 끔찍한 괴물과 그토록 힘든 싸움을 오래 한 후에 영웅이 된 기분을 즐기신다고 비난하는 건 절대 아니지만 다 마치고 나서 여기 있는 저를 잊어버리지는 않았으면 좋겠는데요, 왜냐하면 제가 좀 작긴 해도 당신이 보여준 그 놀라운 용기에 보답할 방법 정도는 알지도 모르니까 말이지요...', `FemaleText_loc4`='哎咳……我觉得吧，在和那个恐怖的怪物艰难地打斗了这么久之后你花上点时间休息兼庆祝一番我绝对没有任何意见啊不过呢你最好别忘记我还在这里呢虽然我看上去个子玲珑不过我还是有能力报答你的恩情的……', `FemaleText_loc5`='嗯哼...那麼，我大概一定不能責怪你慢慢喘息並慶賀自己與那個恐怖的怪物在經過如此漫長且艱辛的一戰後的勇敢而且結束那麼久之後你沒有忘記我在這裡雖然我很小我想我還是能找到方法來酬謝你超凡的勇氣...', `FemaleText_loc7`='Ejem... así que, no los culpo por tomarse su tiempo y recuperar el aliento y felicitarlos por su heroísmo después de una batalla tan dura con ese horrible monstruo siempre y cuando al terminar no se olviden de mí porque aunque soy pequeña creo que puedo encontrar algún modo de recompensarlos por su valor...' WHERE `ID`=23158;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그러니까... 그런 끔찍한 죽음을 면하게 된 후에 이런 불평을 하고 싶지는 않지만 제가 아직 여기 이 더러운 우리에 갇혀 있다는 걸 당신이 좀 알아주셨으면 좋겠다고 생각할 뿐이고 이쪽으로 오셔서 저를 좀 나가게 해주셔서 당신이 그 커다란, 미친, 무시무시한, 트롤 같은 고양이... 아니 고양이 같은 트롤을 처치했다는 멋진 승리를 축하하시는데 도움을 드린다면 진짜로 근사할 거라는 말이에요.', `FemaleText_loc4`='我说……虽然我讨厌那种刚从死亡边缘捡回一条命就开始喋喋不休抱怨起来的家伙不过呢我也要提醒你我还被关在这个肮脏的笼子里呢如果你能放我出去的话我就可以和你一起分享打败那头恐怖的巨魔豹的喜悦啦……', `FemaleText_loc5`='那麼...我不想在從恐怖的死亡中被拯救出來時還在抱怨我只是覺得你應該知道我還被困在這些髒亂的籠子中並且如果你能過來並放我出去的話那真是太棒了因為我可以幫你慶祝你精采地戰勝那個巨大瘋狂嚇人的食人妖-貓...之類的鬼東西。', `FemaleText_loc7`='Miren... odio quejarme después de haber sido salvada de una muerte horrible pero pensaba que deberían saber que aún estoy atascada en una de estas terribles jaulas de aquí arriba y sería genial si pudieran subir y liberarme para que los pueda ayudar a celebrar su increíble victoria sobre ese aterrador gato trol...cosa.' WHERE `ID`=23159;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여러분 모두 무지무지 서두르셔야 할 것 같다고 제가 확신하는 건 아마 더 크고 무서운 괴물들이 있을지도 몰라서이지만 또 서둘러 나가시기 전에 잠시 짬을 내셔서 저를 이 우리에서 꺼내러 와주신다면 저는 정말 기쁘고 흥분되어서 몸을 가누지도 못할 것 같은데 1분만 시간을 들이신다면야 제가 바로 여기서... 기다리고 있으니까... 아주 침착하게 말이지요...', `FemaleText_loc4`='我知道你们都在赶时间可能还需要去打败更大更危险的怪物不过如果你们肯费费神把我从这个笼子里放出去的话我一定会异常兴奋的所以要是你们愿意花上这么一点时间的话我就会很耐心……很耐心……很耐心地在这里等着哟……', `FemaleText_loc5`='我相信你們大家一定都很忙而且可能有更多大型危險怪物要殺不過如果你可以花一點點時間在匆忙離開前幫我離開這個籠子的話我會感到很開心並對我勉強可以控制我自己而感到興奮所以如果你可以花一點時間的話我就在這裡...耐心的...等著...', `FemaleText_loc7`='Estoy segura de que tenéis mucha prisa y probablemente más monstruos peligrosos que matar pero si pudierais tomaros un momento para sacarme de esta jaula antes de marcharos me haría muy feliz y me emocionaría y no sé si podría contenerme así que si tenéis un momento estaré aquí arriba... esperando... pacientemente...' WHERE `ID`=23160;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노스렌드를 여행할 수 있게 해 드리지요. 준비가 끝나면 말씀하십시오. 시작 지점으로 순간이동시켜 드리겠습니다.', `MaleText_loc4`='诺森德的旅程就要拉开序幕。你准备好了就告诉我，我会将你传送到起始地区。', `MaleText_loc5`='我可以揭開你在北裂境的旅程。當你準備好以後讓我知道，我會將你傳送至起始點。', `MaleText_loc7`='Puedo ayudarte a comenzar tu viaje a Rasganorte. Avísame cuando quieras ir y te teletransportaré a tu punto de inicio.' WHERE `ID`=23161;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비됐습니다!', `MaleText_loc4`='我准备好了！', `MaleText_loc5`='我準備好了!', `MaleText_loc7`='¡Estoy listo para ir!', `FemaleText_loc1`='준비됐습니다!', `FemaleText_loc4`='我准备好了！', `FemaleText_loc5`='我準備好了!', `FemaleText_loc7`='¡Estoy lista para ir!' WHERE `ID`=23162;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가라! 네 주인의 명령을 따르라!', `MaleText_loc4`='去吧！遵照主人的命令行事！', `MaleText_loc5`='快去吧!完成你的主人的命令!', `MaleText_loc7`='¡Ahora ve! ¡Cumple la voluntad de tus maestros!' WHERE `ID`=23163;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='줄아만으로 가고 싶소? 내가 데려다 주겠소.', `MaleText_loc4`='朋友，你想去祖阿曼？我带你去吧。', `MaleText_loc5`='想要去祖阿曼嗎，老兄?我可以帶你過去喔。', `MaleText_loc7`='¿Quieres ir a Zul''Aman? Yo te llevaré.' WHERE `ID`=23164;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='줄아만으로 보내 주십시오!', `MaleText_loc4`='带我去祖阿曼！', `MaleText_loc5`='帶我去祖阿曼!', `MaleText_loc7`='¡Llévame a Zul''Aman!', `FemaleText_loc1`='줄아만으로 보내 주십시오!', `FemaleText_loc4`='带我去祖阿曼！', `FemaleText_loc5`='帶我去祖阿曼!', `FemaleText_loc7`='¡Llévame a Zul''Aman!' WHERE `ID`=23165;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저승으로 보내 주마!', `MaleText_loc4`='你马上就要死了！', `MaleText_loc5`='你很快就會死了!', `MaleText_loc7`='¡Morirán pronto!' WHERE `ID`=23166;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고통을 안겨주마!', `MaleText_loc4`='让我带给你们痛苦！', `MaleText_loc5`='我帶來痛苦!', `MaleText_loc7`='¡Yo traigo el dolor!' WHERE `ID`=23167;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희들이 짐승을 불러냈다. 놀랄 준비나 해라!', `MaleText_loc4`='你们召唤野兽？你马上就要大大的后悔了！', `MaleText_loc5`='你們既然將野獸召喚出來，就將付出更多的代價!', `MaleText_loc7`='¡Si llaman a la bestia, recibirán más de lo que esperan!' WHERE `ID`=23168;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날로라크 나가신다!', `MaleText_loc4`='纳洛拉克，变形，出发！', `MaleText_loc5`='別擋納羅拉克的路!', `MaleText_loc7`='¡Dejen pasar a Nalorakk!' WHERE `ID`=23169;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기회가 있었건만, 이젠 너무 늦었다!', `MaleText_loc4`='你们曾有过机会的，但现在太迟了！', `MaleText_loc5`='你曾有過機會的;但現在太遲了!', `MaleText_loc7`='¡Tuvieron su oportunidad; ahora es demasiado tarde!' WHERE `ID`=23170;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 뭐라 할 테냐, 응?', `MaleText_loc4`='现在你们有什么好说的啊？', `MaleText_loc5`='現在你們有什麼好說的啊?', `MaleText_loc7`='¿Qué dices ahora, eh?' WHERE `ID`=23171;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아마니 제국이 다시 지배하리라!', `MaleText_loc4`='阿曼尼帝国万岁！', `MaleText_loc5`='阿曼尼將再度統治!', `MaleText_loc7`='¡Los Amani vuelven a eh''tar al mando!' WHERE `ID`=23172;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나... 다른 세상에서 기다리겠다...', `MaleText_loc4`='我会在另一个世界里等你们的！', `MaleText_loc5`='我...會在另一個世界等著...', `MaleText_loc7`='Estaré... esperando en el más allá...' WHERE `ID`=23173;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잔달라가 우릴 돕는다. 이제 누구도 아마니를 괴롭히지 못해!', `MaleText_loc4`='赞达拉给了我们力量。没人能和阿曼尼作对啦！', `MaleText_loc5`='贊達拉給了我們力量。沒有人敢再欺負阿曼尼了!', `MaleText_loc7`='Los Zandalari nos dan fuerza. ¡Nadie volverá a despreciar a los Amani!' WHERE `ID`=23174;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오호, 난 새로운 기술을 익혔지... 내 형제, 곰처럼...', `MaleText_loc4`='看好了，我有许多新招，比如变个熊……', `MaleText_loc5`='噢等等。我有新花招...像是我的熊兄弟...', `MaleText_loc7`='Mira. Tengo algunos trucos nuevos... como mi hermano oso...' WHERE `ID`=23175;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='독수리의 눈을 피할 수는 없다!', `MaleText_loc4`='没人能逃过猎鹰的眼睛！', `MaleText_loc5`='誰都逃不過雄鷹之爪!', `MaleText_loc7`='¡No hay forma de esconderse del águila!' WHERE `ID`=23176;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 내 새로운 형제, 송곳니와 발톱을 보아라!', `MaleText_loc4`='现在来见识一下我的尖牙和利爪吧！', `MaleText_loc5`='來，介紹一下我的新兄弟:利牙和爪子!', `MaleText_loc7`='¡Les presento a mis nuevos hermanos: colmillo y garra!' WHERE `ID`=23177;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용매를 하늘에서만 찾을 필요는 없다!', `MaleText_loc4`='遮天的龙鹰降临了！', `MaleText_loc5`='要看龍鷹，不必抬頭，眼前就有了!', `MaleText_loc7`='¡No hace falta mirar al cielo para ver al dracohalcón!' WHERE `ID`=23178;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불길로 너희를 끝장내 주마!', `MaleText_loc4`='烈火会烧光你们！', `MaleText_loc5`='用火燒也很快!', `MaleText_loc7`='¡El fuego los matará igual de rápido!' WHERE `ID`=23179;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직도 모르겠나? 난 천하무적이다!', `MaleText_loc4`='这就是为什么他们叫我“战神”！', `MaleText_loc5`='這就是為什麼他們說我無敵啦!', `MaleText_loc7`='¡Por esto dicen que soy INVENCIBLE!' WHERE `ID`=23180;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다 아마니 디 츄카!', `MaleText_loc4`='Da Amani di chuka！', `MaleText_loc5`='阿曼尼萬歲!', `MaleText_loc7`='¡Da Amani di chuka!' WHERE `ID`=23181;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 많은 놈들이 너처럼 쓰러지리라.', `MaleText_loc4`='更多的人会像你们一样倒下。', `MaleText_loc5`='還有人會像你一樣死。', `MaleText_loc7`='Muchos más caerán como tú.' WHERE `ID`=23182;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 쓰러져도... 우리 아마니 제국은... 절대로 사라지지 않는다.', `MaleText_loc4`='就算我倒下了……阿曼尼帝国……绝不会消亡……', `MaleText_loc5`='就算我死了...阿曼尼帝國...也永不會滅。', `MaleText_loc7`='Quizá yo caiga... pero el imperio Amani... nunca morirá.' WHERE `ID`=23183;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우와아! 살았다, 살았어, 살았다고! 오, 제가 당신을 마음 깊이 사랑하게 되었다고 말하는 게 너무 저답지 않은 말이 아니었으면 좋겠고요, 아, 가방을 찾아야 할 텐데. 당신은, 아시다시피, 절 구하시려고 엄청나게 애쓰고 고생하셨으니까 뭔가 특별한 걸 받을 자격이 있으시잖아요...', `FemaleText_loc4`='耶！我自由啦，自由啦！如果我现在就告诉你们我有多么喜欢你们应该不会太唐突吧我希望能快点找到我的包裹因为像你们这样当之无愧的英雄应该受到奖赏啦，你知道的，以此感谢你们这一路走来的艰辛……', `FemaleText_loc5`='耶!我還活著，我還活著，我還活著!喔，我希望這樣不會太冒失，我想告訴你我好愛你啊，希望我可以找到我的背包，因為你肯定值得一點額外的東西，你知道的，為了你的努力以及所有你為了救我而經驗過的事...', `FemaleText_loc7`='¡Weeee! ¡Estoy viva, estoy viva, estoy viva! Oh, espero que no sea demasiado directo deciros que os quiero a todos y que espero encontrar mi bolsa porque realmente os merecéis algo más, ya sabéis, por el esfuerzo y por todo lo que habéis pasado para salvarme...' WHERE `ID`=23184;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='흠, 이 안에 들었는지도 모르겠네요. 아, 그나저나 말이죠, 제가 화염구를 시전하는 동안에 방귀쟁이 퍼지릭이 슬그머니 다가온 때 얘기를 해 드렸나요? 우리가 그를 방귀쟁이라고 부르는 이유는요, 음, 신경 쓰실 거 없고요, 그냥 정말 때가 안 좋았고요, 엄마는 진짜 화가 나셨죠... 제 눈썹이 이제야 새로 자라기 시작했답니다...', `FemaleText_loc4`='唔，或许是这个吧——顺便提一句，我有没有告诉过你“双响喇叭”法迪利克的事？有一次这家伙趁我搓火球时在我背后吓我。我们之所以叫他“双响喇叭”是因为，啊……当我没说吧。那次事件搞得妈妈非常生气，瞧，我的眉毛到现在也没长出来……', `FemaleText_loc5`='嗯，也許就是這個 - 喔對了，我有跟你說過有次范居銳克雙角在我施展火球術的時候偷襲我的事嗎?我們叫他雙角是因為，呃，不管它，反正就是個恐怖的時間點，然後媽媽超火大的 - 我的眉毛現在才長回來...', `FemaleText_loc7`='Mmm, quizá haya acertado. Oh, por cierto... ¿te he contado ya lo de aquella vez en que Dulcito Dos-pitidos se me apareció de repente cuando lanzaba una bola de Fuego? Lo llamamos Dos-pitidos porque... bueno, no importa... La cuestión es que apareció en tan mal momento y mi madre estaba tan enfadada... por fin me están creciendo las cejas de nuevo...' WHERE `ID`=23185;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이봐요, 바텐더! 한 좐 더 돌려요!', `FemaleText_loc4`='嘿，酒保，再来一杯！', `FemaleText_loc5`='嘿，酒保，再來一巡!', `FemaleText_loc7`='¡Hey, camarero! ¡Otra ronda!' WHERE `ID`=23186;
