UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제이슨, 나 칵테일 이거보다 맛있게 만들 줄 알아요... 힉!', `FemaleText_loc4`='贾森，我能搅出更多的泡沫来。', `FemaleText_loc5`='傑森吶，我露一手絕對比你厲害得多啦。', `FemaleText_loc7`='Yo lo puedo hasher mussho mejor, Jasshon.' WHERE `ID`=23188;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='폭탄을 만들려면... 딸꾹! 이 물건을 페트로프에게 갖다 줘야... 갖다 줘야 한다고요!', `FemaleText_loc4`='嗯……你应该把这玩意儿送给派特洛夫制作炸弹！', `FemaleText_loc5`='你應該...你應該把這東西送給派特洛夫，跟他交換炸彈!', `FemaleText_loc7`='¡Deberíashh... deberíash enviarle eshhta cosha a Petrov para sus bombas!' WHERE `ID`=23189;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='드레스 무진장 예쁘네요, 셀레스트. 정말 예쁜 언니야. 솨랑합니다, 여러분... 딸꾹!', `FemaleText_loc4`='塞蕾丝，你这身衣服真漂亮。你太美啦。我爱你们……嗝儿！', `FemaleText_loc5`='妳的衣服好漂亮，妳好美。我愛你們...嗝!', `FemaleText_loc7`='Esssh un vesshtido muy bonito, Celesshte. Eressh tan bonita. Ossh quiero... ¡hip!' WHERE `ID`=23190;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만 마시는 게 좋을 것 같습니다만.', `MaleText_loc4`='再喝下去，你就要醉了。', `MaleText_loc5`='我以為你早該夠了。', `MaleText_loc7`='Creo que ya has tenido suficiente.' WHERE `ID`=23191;
