UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 누구십니까? 머리 꼭대기만 겨우 보이는데. 술을 마셔도 되는 나이이긴 한 겁니까?', `MaleText_loc4`='谁在讲话？我几乎看不见你的脑袋。你到了法定的饮酒年纪了吗？', `MaleText_loc5`='是誰在說話?我幾乎可以看到你的頭頂了耶，你確定你真的過了能喝酒的年紀了嗎?', `MaleText_loc7`='¿Quién es esa que habla? Apenas puedo verte la coronilla. ¿Estás segura de que tienes edad suficiente para beber?' WHERE `ID`=23193;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='페피, 당신이라면 드워프도 뻗게 할 겁니다.', `MaleText_loc4`='贝比，我敢打赌矮人都喝不过你。', `MaleText_loc5`='派比，我相信你私底下一定能喝下一個矮人。', `MaleText_loc7`='Peppy, ¡bebes más que los peces del villancico!' WHERE `ID`=23194;
