UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바텐더가 콧노래를 흥얼거리며 일을 계속합니다.', `MaleText_loc4`='酒保一边工作一边哼着小曲儿。', `MaleText_loc5`='酒保邊工作邊哼著曲子。', `MaleText_loc7`='El camarero tararea una melodía mientras trabaja.' WHERE `ID`=23197;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='리산! 리산 화이트! 얘는 대체 어디 간 거야?', `FemaleText_loc4`='莉丝安！莉丝安·怀特！她在哪儿？', `FemaleText_loc5`='利桑!利桑·懷特!那女孩在哪?', `FemaleText_loc7`='¡Lissan! ¡Lissan Blanco! ¿Dónde está esa chica?' WHERE `ID`=23198;
