UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='리산! 얘 또 우물에서 딴생각하는 게 분명해!', `FemaleText_loc4`='莉丝安！我敢打赌她又跑到井边做白日梦了！', `FemaleText_loc5`='利桑!我賭那個女孩又在井邊做白日夢了!', `FemaleText_loc7`='¡Lissan! ¡Apuesto a que esa chica está soñando despierta en el pozo otra vez!' WHERE `ID`=23200;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='<투덜투덜> 주제에 옷은 참 잘 입는단 말이야! <투덜투덜>', `FemaleText_loc4`='<嘟囔>这身衣服真的很漂亮呢！<嘟囔>', `FemaleText_loc5`='<發牢騷>這衣服還真好看啊!<發牢騷>', `FemaleText_loc7`='<Queja> ¡Bonito vestido! < Queja >' WHERE `ID`=23201;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뾰족엄니가 더 필요해요!', `FemaleText_loc4`='我需要更多的铲齿鹿！', `FemaleText_loc5`='多給我一點鍬牙!', `FemaleText_loc7`='¡Necesito más colmipala!' WHERE `ID`=23202;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='부두 일꾼들은 또 쉬는 건가요? 난 저기 있는 물건들이 필요하다고요!', `FemaleText_loc4`='这些码头工人又闹罢工了？！我需要那些补给物资！', `FemaleText_loc5`='你說那些碼頭工人又休息了?我需要那些補給品啊!', `FemaleText_loc7`='¿Ya están descansando otra vez los trabajadores del muelle? ¡Necesito esos suministros!' WHERE `ID`=23203;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 오늘 중으로 요리해야 하는 재료를 보며 한숨을 쉽니다.', `FemaleText_loc4`='%s想要今天还有不少工作要做，不由地叹了口气。', `FemaleText_loc5`='%s為了她接下來的一整天還得煮那麼多飯而唉聲嘆氣。', `FemaleText_loc7`='%s suspira por todo lo que aún tiene que cocinar.' WHERE `ID`=23204;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고마워요, 귀여운 노움 아가씨. 우리도 당신을 사랑해요.', `FemaleText_loc4`='谢谢你，甜心。我们也爱你。', `FemaleText_loc5`='謝謝你，小甜心，我也愛你。', `FemaleText_loc7`='Gracias, cielo. Nosotros también te queremos.' WHERE `ID`=23205;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아뇨, 이것도 아니네요. 음, 이 근처 어딘가에 있을 텐데... 아무튼 제가 그 냄새 나는 우리에서 나와서 행복해서 죽을 지경이라고 말씀드렸나요? 우리 안에서 달린다는 건 거의 불가능하지만 어쨌든 전 달렸는데 가끔은 너무 빨리 달려서 우리 벽을 뛰어다니게 돼서 결국은 뛰어다니는 건 그만두고 그냥 원을 그리면서 빙글빙글 돌았답니다...', `FemaleText_loc4`='啊，那里也没有——好吧，它一定在这附近啦。我有没有跟你说过离开那个臭烘烘的牢笼是件多么美妙的事情？笼子空间狭小不过我凭借灵巧的身段能在奔跑哟只是有时候我跑得太快了就跟飞檐走壁似的所以呢我决定在里面转圈子玩……', `FemaleText_loc5`='不，也不在那個裡面 - 好吧，一定是在這附近的某處，順帶一提，我有說過能夠離開那個發臭的籠子是多美好的事嗎?要在那四處跑根本是不可能的事，我試了各種方法，但是有時候我得走快一點好讓我的散步止於籠子邊緣，所以最後我就停止嘗試，只在籠內踱圈圈而已...', `FemaleText_loc7`='No, en esa tampoco, bueno, debe estar por aquí, en algún lugar, por cierto, ¿he mencionado lo maravilloso que es estar fuera de esa apestosa jaula? Era casi imposible darse la vuelta allí pero lo hice de todas formas pero algunas veces cogí tanta velocidad que acabé andando por las paredes de la jaula así que dejé de intentarlo y me limité a caminar en círculos.' WHERE `ID`=23206;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저기 제 가방이 있군요! 드디어 찾았으니 선물로 드릴 거고요 살아 계시는 내내 이 멋진 시간을 모두 기억하실 수 있도록 이 선물을 당신이 정말로 마음에 들어 하셨으면 좋겠고요 저는 몇백 년이 지나도 이 순간을 잊지 않을 거니까 절 생각하실 땐 속으로 미소 지어 주셨으면 하고요 빨리 집에 돌아가서 엄마한테 이 모든 일에 대해서 말하고 싶어 입이 다 간질거리네요... 제 귀걸이 맘에 드세요?', `FemaleText_loc4`='我的包裹！终于找到啦这是我送你的礼物我真心希望你会喜欢它因为我要你们记住这刻美好时光一辈子都不要忘记啊我还希望你每次看到它的时候都能笑一笑要知道我是永远不会忘记你们的我迫不及待地想要回家告诉妈妈这次的冒险之旅啦……你觉得我这副耳环好看吗？', `FemaleText_loc5`='不，也不在那個裡面 - 好吧，一定是在這附近的某處，順帶一提，我有說過能夠離開那個發臭的籠子是多美好的事嗎?要在那四處跑根本是不可能的事，我試了各種方法，但是有時候我得走快一點好讓我的散步止於籠子邊緣，所以最後我就停止嘗試，只在籠內踱圈圈而已...', `FemaleText_loc7`='¡Ahí está mi bolsa! Por fin la he encontrado y es mi regalo para ti. Espero que te guste mucho porque quiero que recuerdes este fantástico momento mientras vivas. Y espero que cuando pienses en él sonrías porque yo sé que no lo olvidaré ni en un millón de años y cuando vuelva a casa tengo un montón de ganas de contarle a mi madre todo lo que ha pasado... ¿Te gustan mis pendientes?' WHERE `ID`=23207;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 절 구해주셨군요! 저들이 반드시 절 물에 빠뜨려 죽일 거로 생각했었답니다.', `MaleText_loc4`='你救了我的命，朋友！我还以为他们会把我淹死呢。', `MaleText_loc5`='你救了我，老兄!我還以為他們鐵定要把我給淹死了呢。', `MaleText_loc7`='¡Me has salvado! Estaba convencido de que me iban a ahogar.' WHERE `ID`=23208;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 당신을 도울 일이 있거든 서슴지 말고 말씀하십시오, 바깥에서 오신 분이여.', `MaleText_loc4`='朋友，需要帮忙的话尽管开口。', `MaleText_loc5`='你需要任何幫助的話儘管跟我說吧，老兄。', `MaleText_loc7`='Avísame si puedo echarte una mano con algo.' WHERE `ID`=23209;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스의 군사력이 약해지고 있습니다!', `MaleText_loc4`='联盟的增援快要耗尽了！', `MaleText_loc5`='聯盟方的戰力即將耗盡了!', `MaleText_loc7`='¡El equipo de la Alianza se está quedando sin refuerzos!', `FemaleText_loc1`='얼라이언스의 군사력이 약해지고 있습니다!', `FemaleText_loc4`='联盟的增援快要耗尽了！', `FemaleText_loc5`='聯盟方的戰力即將耗盡了!', `FemaleText_loc7`='¡El equipo de la Alianza se está quedando sin refuerzos!' WHERE `ID`=23210;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드의 군사력이 약해지고 있습니다!', `MaleText_loc4`='部落的增援快要耗尽了！', `MaleText_loc5`='部落方的戰力即將耗盡了!', `MaleText_loc7`='¡El equipo de la Horda se está quedando sin refuerzos!', `FemaleText_loc1`='호드의 군사력이 약해지고 있습니다!', `FemaleText_loc4`='部落的增援快要耗尽了！', `FemaleText_loc5`='部落方的戰力即將耗盡了!', `FemaleText_loc7`='¡El equipo de la Horda se está quedando sin refuerzos!' WHERE `ID`=23211;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네도 알겠지만, 건장한 트롤 녀석들이 주변을 돌아다니지만 않는다면 여기도 꽤 쾌적하다네.', `MaleText_loc4`='要是没有这些高大的巨魔，这里倒是一处舒适的好地方。', `MaleText_loc5`='你知道嗎，這個地方少了一大堆魁梧的食人妖四處遊蕩，真可以說是感覺棒透了。', `MaleText_loc7`='¿Sabes? Si no hubiese tantos trols rondando por aquí, este lugar sería bastante agradable.' WHERE `ID`=23212;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 일을 겪고도 내가 예전 같으려나. 헤, 맥주 한 잔이면 괜찮아질 걸세. 내기를 해도 좋아.', `MaleText_loc4`='我想我再也回不到从前了吧。呵呵，来一品脱酒应该就成。', `MaleText_loc5`='我懷疑經歷過這件事之後我還是不是原來的自己。嘿，我打賭喝一口好酒可以忘卻世上任何不愉快的事。', `MaleText_loc7`='Me pregunto si seré el mismo después de esto. No hay nada que una buena cerveza no cure.' WHERE `ID`=23213;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진짜 모험이었네. 집에 가서 이야기하면 아무도 안 믿어줄 테지만...', `MaleText_loc4`='这才是真正的冒险。那些足不出户的孩子肯定难以想象这样的经历……', `MaleText_loc5`='這真是精采的一場冒險。家裡的那些人一定不會相信這裡發生的事...', `MaleText_loc7`='Menuda aventura. Los chicos no se lo van a creer cuando vuelva...' WHERE `ID`=23214;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 있는 동안 돌아다니면서 여기저기 쑤셔보고 보물이나 찾아볼 작정이네. 설마 나 같은 드워프가 두 번 잡힐 리가 있겠나?', `MaleText_loc4`='我应该趁自己被囚禁在祖阿曼时四处逛逛，搞点财宝什么的——毕竟，对我这样的矮人来说，再多吃点苦头也没什么关系吧？', `MaleText_loc5`='趁我還在這裡的時候，我應該低調的混進去然後四處查探寶物。畢竟，像我這樣的矮人被抓到第二次的機率能有多高?', `MaleText_loc7`='Lo que voy a hacer es ir ahí abajo y ver si encuentro algún tesoro ya que estoy aquí. ¿Qué posibilidades hay de que un enano como yo repita suerte de nuevo?' WHERE `ID`=23215;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 딱 맞춰서 구해 줬네. 그 짐승들이 포로한테 무슨 짓을 했는지 자네도 봤어야 해...', `MaleText_loc4`='你真像一场及时雨。瞧瞧那帮野蛮人是如何对待囚犯的……', `MaleText_loc5`='你的拯救行動來的正是時候。你應該看看那些殘忍的傢伙們怎麼對待囚犯的...', `MaleText_loc7`='La ayuda llegó justo a tiempo. Deberías haber visto lo que esos bestias les hicieron a los prisioneros...' WHERE `ID`=23216;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 손자들한테 들려주기 딱 좋은 이야깃거리구먼. 확실해... 내가 손자 손녀 생길 만큼 오래 산다면 말이지만.', `MaleText_loc4`='我一定会把这个故事讲给我的孙子听……只要我能活到抱孙子的那一天。', `MaleText_loc5`='這將會是一個可跟孫兒女們分享的好故事，我確定...但是，我得先活得夠久才能生出他們。', `MaleText_loc7`='No hay duda de que tendré una gran historia que contar a mis nietos... Eso si logro salir de esta con vida.' WHERE `ID`=23217;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 같은 날 모르는 사람의 도움이 얼마나 고마운지 뼈저리게 느끼는 게지. 눈물 나는군... 헤, 맥주 한 잔이면 다 괜찮아질 걸세.', `MaleText_loc4`='像你这样的陌生人也能慷慨伸出援手，真是感动得令我落泪……嗨，只有喝上几杯才能表达我的感谢。', `MaleText_loc5`='像今天這樣的日子就能讓你懂得感激陌生人的善行─害我的眼框都濕了...不過呢，只要喝一口好酒就可以忘卻所有的感傷。', `MaleText_loc7`='En días como estos la gratitud ante la amabilidad de un extraño hace que se me salten las lágrimas... Eh, no hay nada que una buena cerveza no cure.' WHERE `ID`=23218;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어쩌면 책이라도 한 권 써야겠어... ''하코르의 줄아만 안내서''. 이야, 거 괜찮은데!', `MaleText_loc4`='也许我应该写本书……“哈考尔的祖阿曼指南”。不错，我喜欢这个书名。', `MaleText_loc5`='也許我該出一本書...《哈克爾的祖阿曼導覽》。沒錯，我喜歡這個主意。', `MaleText_loc7`='Quizá deba escribir un libro... ''Guía de Harkor de Zul''Aman''. Sí, me gusta como suena.' WHERE `ID`=23219;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 겁낼 전혀 필요 없다고!', `MaleText_loc4`='相信我，真的没什么可担心的！', `MaleText_loc5`='朋友們，說真的，這沒什麼好擔心的!', `MaleText_loc7`='¡Chicos, de verdad, no hay nada de lo que preocuparse!' WHERE `ID`=23220;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스는 모두 멍청이야! 애써 봤자 헛수고라는 걸 모르나?', `MaleText_loc4`='联盟这帮蠢货！他们没有意识到所有努力都是白费的吗！', `MaleText_loc5`='聯盟的白痴!難道他們不曉得這只是白費力氣嗎?', `MaleText_loc7`='¡Idiotas de la Alianza! ¿No se dan cuenta de que sus esfuerzos son inútiles?' WHERE `ID`=23221;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래... 목이 달아난 닭 마냥 도망가라고.', `MaleText_loc4`='好啊，让大家像无头苍蝇一样东奔西跑吧。', `MaleText_loc5`='對，我們全都得像無頭蒼蠅亂竄。', `MaleText_loc7`='Sí, demos vueltas corriendo como pollos con la cabeza cortada.' WHERE `ID`=23222;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두꺼비마저 달아나는 건가? 믿을 수가 없군!', `MaleText_loc4`='连那些蛤蟆都……？难以置信！', `MaleText_loc5`='就連蟾蜍也是?不可思議!', `MaleText_loc7`='¿Incluso lo sapos? ¡Increíble!' WHERE `ID`=23223;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청이들! 이런 짓을 할 줄 알았어! 그래서 미리 역병 수조에 방화 처리를 해 두었지. 으하하하하하하!', `MaleText_loc4`='那群笨蛋！我就知道他们会这么做，但是他们没有料到我事先做了防火处理。哈哈哈哈哈哈！', `MaleText_loc5`='笨蛋!我早知道他們會這麼做，所以我早就把這些瘟疫槽改造成防火的啦。哇哈哈哈哈!', `MaleText_loc7`='¡Insensatos! Sabía que intentarían eso, así que hice los tanques de peste a prueba de fuego. ¡Jaajaajaaa!' WHERE `ID`=23224;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신경 쓰지 말게... 우린 할 일이 있지 않나!', `MaleText_loc4`='别管那么多……我们还有很多工作要做！', `MaleText_loc5`='別管他...我們還要幹活!', `MaleText_loc7`='¡Ignora eso... tenemos trabajo!' WHERE `ID`=23225;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼간이들! 역병에 딱 맞는 온도까지 끌어올릴 수 있었는데!', `MaleText_loc4`='蠢货！高温很可能是完善药剂样本的重要条件。', `MaleText_loc5`='笨蛋!溫度升高最是適合瘟疫的環境了!', `MaleText_loc7`='¡Insensatos! ¡Un aumento en la temperatura podría ser lo que perfeccionase la plaga!' WHERE `ID`=23226;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저런, 불이 조금 붙었군. 다들 허둥지둥 날뛰잖아!', `MaleText_loc4`='噢，只是一点点小火嘛。大家都恐慌了！', `MaleText_loc5`='喔，稍微起火，大家都怕死了!', `MaleText_loc7`='Oooh, un pequeño fuego. ¡Asustaos todos!' WHERE `ID`=23227;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='작업이 중단되자 역병술사가 한숨을 쉽니다.', `MaleText_loc4`='药剂师的研究被中断，他叹了口气。', `MaleText_loc5`='瘟疫使者為著這突如其來的干擾嘆了一口氣。', `MaleText_loc7`='El pesteador suspira ante la interrupción.' WHERE `ID`=23228;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 주위를 둘러보며 동료의 과잉 반응에 얼굴을 찡그립니다.', `MaleText_loc4`='%s环顾四周，皱了皱眉头，觉得同事们的反应明显过激了。', `MaleText_loc5`='環顧四周，%s為了他同胞過度的反應而操心，皺起了眉頭。', `MaleText_loc7`='Mirando a su alrededor, %s frunce el ceño ante lo que considera una reacción exagerada por parte de sus compatriotas.' WHERE `ID`=23229;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 고개를 젓고는 실험을 계속합니다.', `MaleText_loc4`='%s摇了摇头，继续开始研究工作。', `MaleText_loc5`='%s搖了搖頭，繼續他的研究。', `MaleText_loc7`='%s agita la cabeza antes de continuar con su investigación.' WHERE `ID`=23230;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불이 붙은 근처의 역병 수조가 겉으로 보기에는 변화가 없자, %s|1이;가; 영감을 받은 것 같습니다.', `MaleText_loc4`='%s若有所思地注视着附近着火的药剂罐头。', `MaleText_loc5`='可能是因為附近的瘟疫儲存槽起火而激發了靈感，%s顯然有了好主意。', `MaleText_loc7`='Sin, aparentemente, inmutarse ante el cercano tanque de peste en llamas, %s parece inspirado.' WHERE `ID`=23231;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 영혼까지... 죽이지는... 못해!', `MaleText_loc4`='你们……永远无法消灭……我的灵魂！', `MaleText_loc5`='你們...永遠無法消滅...我的靈魂!', `MaleText_loc7`='¡No pueden... matar... mi espíritu!' WHERE `ID`=23232;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='징징대지 마라!', `MaleText_loc4`='别吵啦！', `MaleText_loc5`='別吵了!', `MaleText_loc7`='¡Ya basta de lloriquear!' WHERE `ID`=23233;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꺼져버려!', `MaleText_loc4`='你们什么也得不到！', `MaleText_loc5`='你真沒用!', `MaleText_loc7`='¡No tienes nada!' WHERE `ID`=23234;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 사냥꾼이다! 너흰 먹잇감이고...', `MaleText_loc4`='我是猎鹰，而你们，就是猎物！', `MaleText_loc5`='我是掠食者!而你們，就是獵物!', `MaleText_loc7`='¡Yo soy el depredador! Ustedes la presa...' WHERE `ID`=23235;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래 봤자 시간 낭비다!', `MaleText_loc4`='你们所做的一切不过是浪费我的时间！', `MaleText_loc5`='你們所做的一切不過是浪費我的時間!', `MaleText_loc7`='¡Solo están malgastando mi tiempo!' WHERE `ID`=23236;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇게 해야 하오. 원래 이 문이 잠겨 있던 방식은 해제되었으니.', `MaleText_loc4`='这样应该就没问题了。这扇大门的机关已经被解除了。', `MaleText_loc5`='那應該辦得到。這道門的主上鎖結構已經失效。', `MaleText_loc7`='Esto debería servir. El mecanismo de cierre principal de la puerta ha sido anulado.' WHERE `ID`=23237;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신경 써주셔서 감사합니다만, 저희는 줄아만을 탐험해볼 작정입니다.', `MaleText_loc4`='感谢关心，不过我们有意要探索祖阿曼。', `MaleText_loc5`='感謝關心，不過我們打算要去探索祖阿曼。', `MaleText_loc7`='Gracias por tu interés, pero tenemos intención de explorar Zul''Aman.', `FemaleText_loc1`='신경 써주시는 건 감사하지만, 저희는 줄아만을 탐험해볼 작정이에요.', `FemaleText_loc4`='感谢关心，不过我们有意要探索祖阿曼。', `FemaleText_loc5`='感謝關心，不過我們打算要去探索祖阿曼。', `FemaleText_loc7`='Gracias por tu interés, pero tenemos intención de explorar Zul''Aman.' WHERE `ID`=23238;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디 이번엔 또 뭐요, 다른 버드네 어중이떠중이 무리요?$B$B물러서시오, $r. 다치거나, 더 험한 꼴 보기 전에.', `MaleText_loc4`='让我猜猜，你是巴德派来的另一队乌合之众吧？$b$b$r，趁你还没受伤——甚至送命之前离开这里吧。', `MaleText_loc5`='讓我猜猜，另一團霸德的烏合之眾?$b$b走開，$r，在你受傷 - 或遇到更糟的事之前。', `MaleText_loc7`='Déjame adivinar, otro grupo de gentuza de Budd.$B$BFuera de aquí, $r, antes de que os hagáis daño o incluso algo peor...' WHERE `ID`=23239;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='줄아만에 얼마나 위험한지는 잘 알고 있습니다. 그러니 제 앞길을 막지 마십시오. 다시는 이런 부탁하지 않을 겁니다.', `MaleText_loc4`='我很清楚这里有多危险。我再说一遍，别挡路。', `MaleText_loc5`='我察覺到此地的危險。現在離開道路上，我不會再說第二次。', `MaleText_loc7`='Soy consciente de los peligros de este lugar. Ahora aparta de mi camino; no te lo pediré dos veces.', `FemaleText_loc1`='줄아만에 얼마나 위험한지는 잘 알고 있지요. 그러니 제 앞길을 막진 마세요. 다시는 이런 부탁하지 않을 거예요..', `FemaleText_loc4`='我很清楚这里有多危险。我再说一遍，别挡路。', `FemaleText_loc5`='我察覺到此地的危險。現在離開道路上，我不會再說第二次。', `FemaleText_loc7`='Soy consciente de los peligros de este lugar. Ahora aparta de mi camino; no te lo pediré dos veces.' WHERE `ID`=23240;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳은 내가 전체적으로 연구해왔으니 바보 같은 보물 사냥꾼들이 덤벼들어 박물관으로 가져갈 만한 보물을 훔쳐가게 두지는 않을 것이오. 내가 앞장서리다.', `MaleText_loc4`='我详细地研究了这个地方，我不会允许任何像你们这样的窃贼进入这地方，并偷走属于博物馆的财宝。', `MaleText_loc5`='我已經四處搜尋過這個區域了，我不允許任何愚蠢的寶藏獵人襲擊並偷取屬於博物館內的東西。我將會領導此次的任務。', `MaleText_loc7`='He estudiado este complejo en detalle y no voy a permitir que un caza tesoros de poca monta se plante aquí y me robe lo que me pertenece por derecho. Yo dirigiré esta carga.' WHERE `ID`=23241;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사실, 당신네는 그냥 여기 있는 게 돕는 거요. 거치적거리기만 할 뿐이니...', `MaleText_loc4`='事实上，你最好留在这里。你只会坏我的事……', `MaleText_loc5`='事實上，你最好待在這裡。你只會妨礙我...', `MaleText_loc7`='De hecho, sería mejor que te quedaras aquí. Solo me estorbarías...' WHERE `ID`=23242;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런 건 관심 없으니, 저리 비켜나시오. 곤란한 상황에 닥치더라도 굳이 날 찾아오진 마시오...', `MaleText_loc4`='无论如何都别来烦我，就算你惹上麻烦也不要叫我……', `MaleText_loc5`='不管怎樣，別擋住我的路，還有別在你惹麻煩時特地召喚我...', `MaleText_loc7`='De todas formas, apártate de mi camino y no te molestes en llamarme cuando te metas en un lío...' WHERE `ID`=23243;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여보게! 나는 다른 누구보다도 산양을 잘 다루지만, 그렇다고 양조장이를 돕고 가을 축제에 협력하는 걸 등한시하지는 않는다고. 자네도 원한다면 참여할 수 있어.$b$b아직 할 말이 안 끝났으니 기다리게!$b$b가을 축제 일을 돕는다는 건 말이지, 세상에서 제일 빠른 산양을 타 볼 수 있다는 걸세!', `MaleText_loc4`='嗨！我是最优秀的赛羊手，这并不代表我就乐意帮助那些酿酒商。你高兴的话，你去帮他们好了。$B$B等等，我还没说完呢！$B$B你要是能帮到酿酒商，就有机会骑上世界上最好的赛羊！', `MaleText_loc5`='嗨你好!只因為我比任何人都會競速山羊，不代表我無法出力幫助酒廠。如果你喜歡的話可以幫忙。$b$b不過等等，還有別的!$b$b幫忙啤酒節的事宜代表你有機會可以騎乘各種族中最迅捷的山羊!', `MaleText_loc7`='¡Hey! Que sea capaz de montar en carnero más rápido que nadie, no quiere decir que no vaya a ayudar a los destiladores. Puedes ayudar si quieres.$B$B¡Pero espera que aún hay más!$B$BAyudar en la Fiesta de la Cerveza te da la posibilidad de montar en algunos de los carneros más rápidos de los reinos!' WHERE `ID`=23244;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카라노스에서 맥주통을 날라 올 일손이 아직 필요하십니까?', `MaleText_loc4`='你还需要找人从卡拉诺斯运回酒桶吗？', `MaleText_loc5`='你還需要人從卡拉諾斯幫忙運送酒桶嗎?', `MaleText_loc7`='¿Aún necesitas ayuda con el envío de barriles de Kharanos?', `FemaleText_loc1`='카라노스에서 맥주통을 날라 올 일손이 아직 필요하세요?', `FemaleText_loc4`='你还需要找人从卡拉诺斯运回酒桶吗？', `FemaleText_loc5`='你還需要人從卡拉諾斯幫忙運送酒桶嗎?', `FemaleText_loc7`='¿Aún necesitas ayuda con el envío de barriles de Kharanos?' WHERE `ID`=23245;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거인을 지배할 수 있으리라 생각하는 룬을 새기려는 참입니다.', `MaleText_loc4`='接下来，我会帮你雕刻符文，它拥有支配巨人的力量。', `MaleText_loc5`='我把這個符文刻出來，我想你就能控制巨人了。', `MaleText_loc7`='Solo voy a grabar las runas que creo que te proporcionarán el control de un gigante.' WHERE `ID`=23246;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"북쪽"과 "서쪽"을 뜻하는 룬은 뺐습니다. 거인에게 어떤 영향을 미칠지 확실하지 않아서 말입니다. 그리고 얼마 동안 제어할 수 있을지 정하는 룬도 넣고 있습니다.', `MaleText_loc4`='我省掉了代表“北面”和“西面”的符文，因为我还不确定它们会对巨人产生怎样的影响。而且，我还添加了限制控制时间的符文。', `MaleText_loc5`='我將意味著「北方」和「西方」的符文給刪除了，因為我不確定它們是如何對巨人產生影響的。我也歸結出一個符文是用來限制你能控制它的時間。', `MaleText_loc7`='Estoy omitiendo las runas del "norte" y "oeste" porque no estoy seguro de cómo afectan al gigante. También voy a incluir una runa para limitar el tiempo que lo puedes controlar.' WHERE `ID`=23247;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 있습니다, 지배의 룬입니다... 그 이름대로 작동한다면 말이지만 말입니다. 무쇠 드워프가 만든 것만큼 사악한 의도는 없지만 쓸 만할 겁니다.', `MaleText_loc4`='瞧，命令符文……希望能起作用。它并不没有铁矮人那股邪恶的气息，却同样具备操纵巨人的能力。', `MaleText_loc5`='好了，指揮符文...但願如此。遠不及他們的鐵矮人同胞邪惡，但是很有用。', `MaleText_loc7`='Ahí está, la runa de mando... espero. No tan perversa como su prima enana férrea, pero funcional.' WHERE `ID`=23248;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 북동쪽을 응시합니다!', `MaleText_loc4`='%s凝视着东北方！', `MaleText_loc5`='%s凝視著東北方!', `MaleText_loc7`='¡%s mira fijamente hacia el noreste!' WHERE `ID`=23249;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 소환의 돌을 쳐다보고는 한숨을 쉽니다.', `MaleText_loc4`='%s盯着集合石，叹了口气。', `MaleText_loc5`='%s望著召喚石嘆氣。', `MaleText_loc7`='%s mira hacia las piedras de invocación y suspira.' WHERE `ID`=23250;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으하하, 여기 보이나? 그립타가 돌아왔다고! 내 사랑스러운 노점에, 내 오랜 상품들 곁에 말이야! 장사할 준비도 마쳤지!$b$b더 나아지고, 강해지고, 빨라지고 싶나? 여기 있는 목걸이를 쓰면 그렇게 된다고. 검증된 작품이야! 어서 와서 가격까지 착한 기적의 목걸이 하나 사게! 내 반값에 주지!', `MaleText_loc4`='啊哈哈哈，瞧见了吗？格里伏塔回来了！我带着一堆古董回到了熟悉的货摊前，而且我已经准备好和你做买卖了！$b$b想要变得更健壮更强大更矫健吗？我出售的护身符都具备这些功能哟。来吧，掏钱买个绝世珍宝吧！破盘价啦！', `MaleText_loc5`='啊哈哈，你有看到嗎?格利夫塔回來了!回到我的攤位，帶著我的舊東西，準備好繼續跟你做生意!$b$b想要變得更好，更強壯，更迅速嗎?這些護符的每一個都保證如我所說的作用一般。過來買一個奇妙的玩意兒吧!物超所值喔!', `MaleText_loc7`='Jaja, ¿ves esto? ¡Griftah ha VUELTO! ¡De nuevo en mi puesto, con mis antiguas mercancías y listo para hacer tratos contigo!$B$B¿Quieres ser mejor, más rápido, más fuerte? Cada uno de estos amuletos hace lo que te estoy contando. ¡Anímate y compra uno de estos adornos milagrosos! ¡A precio de ganga!' WHERE `ID`=23251;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자다! 경보를 울려라!', `MaleText_loc4`='又有入侵者，敲响警钟！', `MaleText_loc5`='又有入侵者!敲響警鐘!', `MaleText_loc7`='¡Más intrusos! ¡Hagan sonar la alarma!' WHERE `ID`=23252;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혼들이 오늘 잔치를 벌이겠구나! 의식을 시작해라. 포로를 제물로 바쳐라... 새 손님을 맞아야지!', `MaleText_loc4`='今天，所有的灵魂将饕餮不已！开始仪式吧，献祭所有的囚徒……为我们的新客人腾出空间！', `MaleText_loc5`='靈魂們今天要好好享用祭品!儀式開始，獻祭那些囚徒...將空間留給我們的新訪客!', `MaleText_loc7`='¡Hoy los espíritus celebrarán! ¡Comienzen con las ceremonias, sacrifiquen a los prisioneros... hagan espacio para nuestros invitados!' WHERE `ID`=23253;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘든 시기를 함께 겪고 나면 묘한 우정이 싹트는 법이지요. 옛 로데론을 방문하여 포세이큰이 밀짚인형을 제물로 불태우는 광경을 보시는 것도 괜찮을 겁니다.', `MaleText_loc4`='黑暗的岁月可以促成奇怪的友谊。如果能去旧洛丹伦，观看被遗忘者们烧毁稻草人的话也挺不错的。', `MaleText_loc5`='黑暗的時代成就了不可思議的友誼。也許值得到舊羅德隆一遊，觀看被遺忘者焚燒他們的小稻草人。', `MaleText_loc7`='Los tiempos oscuros dan lugar a extrañas amistades. Puede que valga la pena visitar la vieja Lordaeron para ver como los Renegados queman su pequeño hombrecillo de mimbre.', `FemaleText_loc1`='힘든 시기를 함께 겪고 나면 묘한 우정이 싹트는 법이지요. 옛 로데론을 방문하여 포세이큰이 밀짚인형을 제물로 불태우는 광경을 보시는 것도 괜찮을 거예요.', `FemaleText_loc4`='黑暗的岁月可以促成奇怪的友谊。如果能去旧洛丹伦，观看被遗忘者们烧毁稻草人的话也挺不错的。', `FemaleText_loc5`='黑暗的時代成就了不可思議的友誼。也許值得到舊羅德隆一遊，觀看被遺忘者焚燒他們的小稻草人。', `FemaleText_loc7`='Los tiempos oscuros dan lugar a extrañas amistades. Puede que valga la pena visitar la vieja Lordaeron para ver como los Renegados queman su pequeño hombrecillo de mimbre.' WHERE `ID`=23254;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 축제는 얼라이언스가 아니라 호드가 만든 걸로 알고 있습니다. 왜 우리가 이런 축제를 따라하는지 모르겠군요.', `MaleText_loc4`='这个节日原本是部落发明的，不是联盟。真不明白我们为什么也要庆祝。', `MaleText_loc5`='我了解這個節慶不是我們盟友創造的，而是整個部落。我們為什麼要跟著一起做，我真的不知道。', `MaleText_loc7`='Sé que esta fiesta no es una creación de nuestros aliados, sino de la Horda. Lo que no sé es por qué hacemos lo mismo.', `FemaleText_loc1`='이 축제는 얼라이언스가 아니라 호드가 만든 걸로 알고 있습니다. 왜 우리가 이런 축제를 따라하는지 모르겠네요.', `FemaleText_loc4`='这个节日原本是部落发明的，不是联盟。真不明白我们为什么也要庆祝。', `FemaleText_loc5`='我了解這個節慶不是我們盟友創造的，而是整個部落。我們為什麼要跟著一起做，我真的不知道。', `FemaleText_loc7`='Sé que esta fiesta no es una creación de nuestros aliados, sino de la Horda. Lo que no sé es por qué hacemos lo mismo.' WHERE `ID`=23255;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 뭐에서 벗어난 걸 축하한다고요? 흥, 누가 그런 걸 신경 쓰나요? 사탕이나 더 주시죠!', `MaleText_loc4`='我们这是在庆祝谁摆脱了谁的束缚？呸，管他呢？！我要更多的糖果！', `MaleText_loc5`='我們正在慶祝那個誰因為什麼而重獲自由?呸，誰在意啊?!給我們更多的糖果!', `MaleText_loc7`='¿Celebramos que quién se liberó de qué? Bah ¿A quién le importa? ¡Más caramelos!', `FemaleText_loc1`='누가 뭐에서 벗어난 걸 축하한다고요? 흥, 누가 그런 걸 신경 쓰나요? 사탕이나 더 주시죠!', `FemaleText_loc4`='我们这是在庆祝谁摆脱了谁的束缚？呸，管他呢？！我要更多的糖果！', `FemaleText_loc5`='我們正在慶祝那個誰因為什麼而重獲自由?呸，誰在意啊?!給我們更多的糖果!', `FemaleText_loc7`='¿Celebramos que quién se liberó de qué? Bah ¿A quién le importa? ¡Más caramelos!' WHERE `ID`=23256;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 사람들이 노움한테는 설탕도 필요 없다고 하는 건가요?!', `MaleText_loc4`='为什么每个人都不停地说侏儒只想要更多的糖果？！', `MaleText_loc5`='為什麼每個人一直都說我們地精最不需要的東西就是更多的糖果?!', `MaleText_loc7`='¿Por qué todo el mundo se empeña en que lo ÚLTIMO que necesitamos los gnomos es más azúcar?', `FemaleText_loc1`='왜 사람들이 노움한테는 설탕도 필요 없다고 하는 거죠?!', `FemaleText_loc4`='为什么每个人都不停地说侏儒只想要更多的糖果？！', `FemaleText_loc5`='為什麼每個人一直都說我們地精最不需要的東西就是更多的糖果?!', `FemaleText_loc7`='¿Por qué todo el mundo se empeña en que lo ÚLTIMO que necesitamos las gnomas es más azúcar?' WHERE `ID`=23257;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 사탕을 전부 공짜로 나눠주면 장사가 안될 텐데 아니면... 그냥 사은품이로군요... 일단 여관에 들어오게 한 다음에, 고기를 팔고 바가지를 씌우는 거죠. 누군지 머리 참 잘 썼군요!', `MaleText_loc4`='我说，免费的糖果真是个赔钱的买卖。呃……或许它们只是招揽顾客的减价货呢……糖果诱使你进入旅店，接下来你就要花钱吃肉啦。太棒了！', `MaleText_loc5`='讓我告訴你，這些免費的糖果真是一樁不划算的生意。或者說...這些東西只是一些噱頭罷了...他們因此把客人騙進旅店，然後用其他的餐點賺你一筆。真是聰明!', `MaleText_loc7`='Todos estos caramelos gratis son un mal negocio, te lo digo yo. O... a lo mejor solo son un engañabobos... te llevan a la posada y después ya eres suyo. ¡Es brillante!', `FemaleText_loc1`='이 사탕을 전부 공짜로 나눠주면 장사가 안될 텐데요. 아니면... 그냥 사은품이로군요... 일단 여관에 들어오게 한 다음에, 고기를 팔고 바가지를 씌우는 거죠. 누군지 머리 참 잘 썼네요!', `FemaleText_loc4`='我说，免费的糖果真是个赔钱的买卖。呃……或许它们只是招揽顾客的减价货呢……糖果诱使你进入旅店，接下来你就要花钱吃肉啦。太棒了！', `FemaleText_loc5`='讓我告訴你，這些免費的糖果真是一樁不划算的生意。或者說...這些東西只是一些噱頭罷了...他們因此把客人騙進旅店，然後用其他的餐點賺你一筆。真是聰明!', `FemaleText_loc7`='Todos estos caramelos gratis son un mal negocio, te lo digo yo. O... a lo mejor solo son un engañabobos... te llevan a la posada y después ya eres suya. ¡Es brillante!' WHERE `ID`=23258;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='할로윈 축제가 끝나면 이 호박들을 다 날려 버릴 겁니다. 제가 아는 한 최고로 멋진 날이 되겠지요!', `MaleText_loc4`='万圣节结束后我们就要打碎所有的南瓜。那将会是我最开心的日子！', `MaleText_loc5`='在萬鬼節結束時我們將會砸掉這些所有的南瓜。那是我知道最棒的日子了!', `MaleText_loc7`='Cuando acabe Halloween destrozaremos estas calabazas. ¡Será el mejor día de mi vida!', `FemaleText_loc1`='할로윈 축제가 끝나면 이 호박들을 다 날려 버릴 겁니다. 제가 아는 한 최고로 멋진 날이 되겠지요!', `FemaleText_loc4`='万圣节结束后我们就要打碎所有的南瓜。那将会是我最开心的日子！', `FemaleText_loc5`='在萬鬼節結束時我們將會砸掉這些所有的南瓜。那是我知道最棒的日子了!', `FemaleText_loc7`='Cuando acabe Halloween destrozaremos estas calabazas. ¡Será el mejor día de mi vida!' WHERE `ID`=23259;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말이야 바른말이지, 무서운 적이 하나 더 탄생한 걸 축하하다니 이상하군요. 게다가 그 축제에서 얼라이언스가 뭉친다니요.', `MaleText_loc4`='退一步说，庆祝另一位死敌的诞辰真是件诡异的事。不过，我们还是会参加盟友们的节日。', `MaleText_loc5`='去慶祝另一個該死的敵人誕生是件很怪的事，至少可以這麼說。不過，我們還是會於參與我們盟友他們的慶典。', `MaleText_loc7`='Celebrar el nacimiento de otro enemigo mortal es extraño, por decir algo. Aun así, nos uniremos a las festividades de nuestros aliados.', `FemaleText_loc1`='말이야 바른말이지, 무서운 적이 하나 더 탄생한 걸 축하하다니 이상해요. 게다가 그 축제에서 얼라이언스가 뭉친다니요.', `FemaleText_loc4`='退一步说，庆祝另一位死敌的诞辰真是件诡异的事。不过，我们还是会参加盟友们的节日。', `FemaleText_loc5`='去慶祝另一個該死的敵人誕生是件很怪的事，至少可以這麼說。不過，我們還是會於參與我們盟友他們的慶典。', `FemaleText_loc7`='Celebrar el nacimiento de otro enemigo mortal es extraño, por decir algo. Aun así, nos uniremos a las festividades de nuestros aliados.' WHERE `ID`=23260;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='포세이큰이 자기네가 얻은 자유를 축하하는 것도 당연하네. 그보다 더 중요한 일이 뭐가 있겠나?', `MaleText_loc4`='被遗忘者有权庆祝自己重获自由。还有什么比这更重要的吗？', `MaleText_loc5`='被遺忘者慶祝他們的自由是對的。還有什麼更重要呢?', `MaleText_loc7`='Los Renegados hacen bien en celebrar su libertad. ¿Acaso hay algo más importante?', `FemaleText_loc1`='포세이큰이 자기네가 얻은 자유를 축하하는 것도 당연하네. 그보다 더 중요한 일이 뭐가 있겠나?', `FemaleText_loc4`='被遗忘者有权庆祝自己重获自由。还有什么比这更重要的吗？', `FemaleText_loc5`='被遺忘者慶祝他們的自由是對的。還有什麼更重要呢?', `FemaleText_loc7`='Los Renegados hacen bien en celebrar su libertad. ¿Acaso hay algo más importante?' WHERE `ID`=23261;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='포세이큰이 밤마다 커다란 밀짚인형을 제물로 태우는 의미는 도통 모르겠소. 하긴 우리네 의식도 포세이큰에게는 마찬가지로 이상하게 보일 테니...', `MaleText_loc4`='被遗忘者每晚都会焚毁一个巨大的稻草人，真不明白这样做的意义何在，不过我们的仪式在他们眼中应该也很奇怪。', `MaleText_loc5`='我不了解被遺忘者每晚焚燒大型稻草像的涵意，不過我們自己的儀式在他們看起來一定也是很奇怪吧。', `MaleText_loc7`='No entiendo qué significado tiene que los Renegados quemen una gran efigie de mimbre cada noche, pero seguro que a ellos nuestros rituales les parecen igual de raros.', `FemaleText_loc1`='포세이큰이 밤마다 커다란 밀짚인형을 제물로 태우는 의미는 도통 모르겠더군요. 하긴 우리네 의식도 포세이큰에게는 마찬가지로 이상하게 보일 테니...', `FemaleText_loc4`='被遗忘者每晚都会焚毁一个巨大的稻草人，真不明白这样做的意义何在，不过我们的仪式在他们眼中应该也很奇怪。', `FemaleText_loc5`='我不了解被遺忘者每晚焚燒大型稻草像的涵意，不過我們自己的儀式在他們看起來一定也是很奇怪吧。', `FemaleText_loc7`='No entiendo qué significado tiene que los Renegados quemen una gran efigie de mimbre cada noche, pero seguro que a ellos nuestros rituales les parecen igual de raros.' WHERE `ID`=23262;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='할로윈 때면 왜 포세이큰이 밤마다 밀짚인형을 태우는지 모르겠단 말이야. 차라리 진짜를 쓰지. 우리 축제라면 그렇게 할 텐데...', `MaleText_loc4`='万圣节期间，被遗忘者每晚都会焚毁一个稻草人。真不明白他们为什么不烧真人，不过这大概是他们的节日传统吧。', `MaleText_loc5`='我不知道為什麼被遺忘者要在每個萬鬼節晚上焚燒稻草人而非真人，不過這就是他們的節慶。', `MaleText_loc7`='No sé por qué los Renegados queman un hombrecillo de mimbre en vez de uno de verdad cada noche de Halloween, pero es su fiesta.', `FemaleText_loc1`='할로윈 때면 왜 포세이큰이 밤마다 밀짚인형을 태우는지 모르겠어요. 차라리 진짜를 쓰지 말이어요. 우리 축제라면 그렇게 할 거랍니다.', `FemaleText_loc4`='万圣节期间，被遗忘者每晚都会焚毁一个稻草人。真不明白他们为什么不烧真人，不过这大概是他们的节日传统吧。', `FemaleText_loc5`='我不知道為什麼被遺忘者要在每個萬鬼節晚上焚燒稻草人而非真人，不過這就是他們的節慶。', `FemaleText_loc7`='No sé por qué los Renegados queman un hombrecillo de mimbre en vez de uno de verdad cada noche de Halloween, pero es su fiesta.' WHERE `ID`=23263;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='할로윈 기간에는 밴시 여왕님께서 리치 왕과 스컬지의 손아귀에서 저희를 구해 내신 그날을 기념하며 축하한다오. 매일 저녁 언더시티 외곽에서 열리는 밀짚인형 화형식에 꼭 참가해 보시오.', `MaleText_loc4`='我们在万圣节上狂欢，纪念女妖之王将我们从巫妖王和天灾军团的魔掌中解救出来。每晚在幽暗城外都会举办稻草人晚会，记得参加哦。', `MaleText_loc5`='我們在萬鬼節期間慶祝這個由女妖之王將我們從巫妖王及天譴軍團手中解放出來的日子。一定要參加每晚在幽暗城外舉行的稻草人節。', `MaleText_loc7`='Durante Halloween celebramos el día en que la Reina alma en pena nos liberó de las garras del Rey Exánime y de la Plaga. No te pierdas el Festival del Hombre de Mimbre que se celebra cada noche a las afueras de Entrañas.', `FemaleText_loc1`='할로윈 기간에는 밴시 여왕님께서 리치 왕과 스컬지의 손아귀에서 저희를 구해 내신 그날을 기념하며 축하하지요. 매일 저녁 언더시티 외곽에서 열리는 밀짚인형 화형식에 꼭 참가해 보세요.', `FemaleText_loc4`='我们在万圣节上狂欢，纪念女妖之王将我们从巫妖王和天灾军团的魔掌中解救出来。每晚在幽暗城外都会举办稻草人晚会，记得参加哦。', `FemaleText_loc5`='我們在萬鬼節期間慶祝這個由女妖之王將我們從巫妖王及天譴軍團手中解放出來的日子。一定要參加每晚在幽暗城外舉行的稻草人節。', `FemaleText_loc7`='Durante Halloween celebramos el día en que la Reina alma en pena nos liberó de las garras del Rey Exánime y de la Plaga. No te pierdas el Festival del Hombre de Mimbre que se celebra cada noche a las afueras de Entrañas.' WHERE `ID`=23264;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 증거를 잃어버릴 수가 있습니까?!', `MaleText_loc4`='你居然把证据给弄丢了？！', `MaleText_loc5`='你怎會把證據弄丟了?!', `MaleText_loc7`='¡¿Cómo puedes haber perdido las pruebas?!' WHERE `ID`=23265;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안전한 줄 알았지요! 당신네 평화감시단이 이 도시의 도둑 단속만 제대로 했어도 이런 일은 없었을 겁니다!', `MaleText_loc4`='我以为很安全嘛！要是你们这帮卫兵能惩治惩治沙塔斯城中的小偷，就不会发生这样的事件！', `MaleText_loc5`='我想它應該很安全!如果你的保安官有努力控制這個城中的小偷們的話，事情就不會發生!', `MaleText_loc7`='¡Creí que era seguro! ¡Si tus pacificadores tuvieran influencia suficiente para controlar a los ladrones de esta ciudad, esto no habría ocurrido!' WHERE `ID`=23266;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 실수를 평화감시단 탓으로 돌리는 겁니까? 간단한 임무였소. 그 트롤 녀석은 명백히 사기꾼이었지요!', `MaleText_loc4`='你想把这事推到卫兵头上来掩饰自己的疏忽吗？这么个简单的任务你都办不好。那巨魔显然是个骗子！', `MaleText_loc5`='你為了你自己的過錯而責怪保安官?你被委託一個簡單的任務。這個食人妖很明顯得就是個騙子!', `MaleText_loc7`='¿Culpas de tu fracaso a los pacificadores? Se te encomendó una simple tarea. ¡Obviamente el trol era un fraude!' WHERE `ID`=23267;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나를 보라고, 난 무작위로 만들어지는 존재야! 자 5초 안에 갈 거야!', `MaleText_loc4`='看，随机挑选开始！五秒内就有结果！', `MaleText_loc5`='你看，我正在隨機化!要來了喔(倒數5秒)!', `MaleText_loc7`='¡MÍRAME, SOY ALEATORIO! AQUÍ LLEGA (EN 5 SEGUNDOS)!' WHERE `ID`=23268;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미라로 만든 트롤이라니... 모양을 보니 급하게 만들어졌군.', `MaleText_loc4`='巨魔木乃伊……看上去处理得很草率。', `MaleText_loc5`='乾癟的食人妖...根據他們的外表看來進行過了快速的防腐。', `MaleText_loc7`='Trols momificados... embalsamados a toda prisa a juzgar por su aspecto.' WHERE `ID`=23270;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음. 이 새가 왜 중요한지 이해가 안 되는데.', `MaleText_loc4`='嗯。我还是不明白这只鸟的含义。', `MaleText_loc5`='嗯嗯。這隻鳥的含義困擾著我。', `MaleText_loc7`='Hmm. No consigo recordar el significado de este pájaro.' WHERE `ID`=23271;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 불길은 몇 년 동안 계속 타오르고 있어. 트롤치고는 기이할 정도로 헌신적인 모습이랄까.', `MaleText_loc4`='数年来，这些篝火堆都不曾熄灭。它们对巨魔来说有着非同寻常的意义。', `MaleText_loc5`='這火已經穩定延燒了好幾年。食人妖獨特的奉獻儀式。', `MaleText_loc7`='Estas hogueras llevan años ardiendo continuamente. Una dedicación poco común en los trols.' WHERE `ID`=23272;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헷갈리는데. 분명히 저들은 제물을 바쳐 엄청난 힘을 얻어내고 있어. 하지만, 뭘 위해서지?', `MaleText_loc4`='奇怪。很明显，他们利用献祭仪式获取强大的力量。但他们的目的是什么呢？', `MaleText_loc5`='真困惑。他們很明顯的從他們的獻祭中得到很大的力量。不過為了什麼呢?', `MaleText_loc7`='Extraño. Es evidente que están logrando mucho poder con sus sacrificios, pero ¿para qué?' WHERE `ID`=23273;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서는 재료를 아주 흥미로운 방법으로 사용했군. 풍부한 색감에 굵직굵직한 선, 심오한 상징성까지... 인상적이야.', `MaleText_loc4`='瞧这雕刻手法。丰富的色彩、粗壮的线条、深奥的符号……令人叹为观止。', `MaleText_loc5`='很有趣的材料使用。大量的色彩，強健的線條，深刻的象徵...引人注目。', `MaleText_loc7`='Curioso uso de materiales aquí. Rico en color, líneas marcadas, profundo simbolismo... llamativo.' WHERE `ID`=23274;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 조각은 분명히 예전에 쓰던 트롤 짚인형을 기원으로 만들었군.', `MaleText_loc4`='这尊雕像和其它巨魔雕像截然不同。', `MaleText_loc5`='此雕像為一偏離先前食人妖肖像的象徵。', `MaleText_loc7`='Esta estatua es una novedad significativa respecto a las efigies trols anteriores.' WHERE `ID`=23275;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇지, 그래. 이건 어떤 존재가 결합했음을 나타내는 거라 확신할 수 있어. 환상적이야.', `MaleText_loc4`='是啦，我确信这代表着多个实体的融合。太神奇啦。', `MaleText_loc5`='沒錯，沒錯，我十分確定這代表一眾多本質的結合。真吸引人。', `MaleText_loc7`='Sí, sí, estoy bastante convencido de que esto representa una unión de entidades. Fascinante.' WHERE `ID`=23276;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어라. 머리카락 뭉치와, 털갈이로 빠진 깃털에, 뼛조각과, 부분부분 탄 물질까지, 이건 옷조각인가?', `MaleText_loc4`='哟。纠结的毛发、脱落的羽毛、碎裂的骨头、被烧焦的不明物——或许是衣物？', `MaleText_loc5`='呃。糾纏成團的頭髮，脫下的毛皮，一堆骨頭，部份燒毀的材料 - 可能是衣物吧?', `MaleText_loc7`='Argh. Matas de pelo enmarañado, plumas mudadas, trozos de hueso, materiales parcialmente quemados, ¿ropa quizás?' WHERE `ID`=23277;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폐기물을 잘 싸서, 단정하게 옆에 쌓아 두었다니. 극도의 잔인함과 대조되는 정갈함이라... 주목할만한 일이군.', `MaleText_loc4`='装满垃圾的袋子被整齐地堆在一旁，和血腥的现场形成强烈的……视觉冲击。', `MaleText_loc5`='垃圾打包，堆疊並整齊的放在一邊。這樣的秩序與極度野蠻相比...引人注目。', `MaleText_loc7`='Desperdicios apilados y limpiamente apartados. Tanto orden contrasta con la barbaridad extrema... extraordinario.' WHERE `ID`=23278;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 문화가 거부하는 내용을 연구하면 그 문화를 깊이 있게 알 수 있는 법이지.', `MaleText_loc4`='研究垃圾也能了解到这个文明的不少信息。', `MaleText_loc5`='一個人能夠藉由閱讀其殘渣來學到一種文化的價值。', `MaleText_loc7`='Se puede aprender mucho acerca de una cultura examinando sus desperdicios.' WHERE `ID`=23279;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 뭐지? 부러진 이빨이라... 어떤 종류의 거대한 고양잇과 생물에서 나온 듯한데... 이거 참 기묘하군...', `MaleText_loc4`='这是什么？一颗牙齿么？好象是某只大型猫科动物嘴里掉出来的。真奇怪……', `MaleText_loc5`='這是什麼?一顆壞掉的牙。可能來自某種巨型貓類。真怪...', `MaleText_loc7`='¿Qué es esto? Un diente roto. Probablemente de algún tipo de gato gigante. Extraño...' WHERE `ID`=23280;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='재와 까맣게 탄 뼈라니, 심란하군. 견본으로 좀 가져가야겠어.', `MaleText_loc4`='灰烬与枯骨，就这么散落着。我必须取一份样品。', `MaleText_loc5`='灰燼及焦黑的骨頭，大多都沒經過處置。我一定要取點樣本。', `MaleText_loc7`='Cenizas y huesos carbonizados, muy inquietante. Debo tomar una muestra.' WHERE `ID`=23281;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이상해... 여태까지 알려진 트롤 전통 문양 중에 이 모자이크와 비슷하게 생긴 것은 없는데.', `MaleText_loc4`='奇怪啊……，这上面的镶嵌着的图案跟任何已知的巨魔传统风格都完全没有任何接近之处。', `MaleText_loc5`='真怪...這些馬賽克工藝品不像任何已知的食人妖傳統。', `MaleText_loc7`='Extraño... estos mosaicos no guardan parecido con ninguna tradición trol conocida.' WHERE `ID`=23282;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 생긴 통은 이 지역에선 특이한 건데. 짧달막한 데다 둥글고...', `MaleText_loc4`='这些是祖阿曼特有的桶吧。桶身很短、很圆……', `MaleText_loc5`='像這種的桶子在此區是獨特的。短、圓...', `MaleText_loc7`='Este tipo de barriles son únicos en esta región. Bajos, redondos...' WHERE `ID`=23283;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='즐거운 할로윈 축제되세요!', `MaleText_loc4`='万圣节快乐！', `MaleText_loc5`='萬鬼節快樂!', `MaleText_loc7`='¡Feliz Halloween!', `FemaleText_loc1`='즐거운 할로윈 축제되세요!', `FemaleText_loc4`='万圣节快乐！', `FemaleText_loc5`='萬鬼節快樂!', `FemaleText_loc7`='¡Feliz Halloween!' WHERE `ID`=23284;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으음... 캔디를 너무 많이 먹은 것 같은데...', `MaleText_loc4`='我好像吃了太多的糖果……', `MaleText_loc5`='我想我吃了太多糖果了...', `MaleText_loc7`='Creo que he comido demasiados dulces...', `FemaleText_loc1`='이런... 캔디를 너무 많이 먹은 것 같은데...', `FemaleText_loc4`='我好像吃了太多的糖果……', `FemaleText_loc5`='我想我吃了太多糖果了...', `FemaleText_loc7`='Creo que he comido demasiados dulces...' WHERE `ID`=23285;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 나중에 사탕 얻으러 가야죠.', `MaleText_loc4`='我们待会再玩“不给糖果就恶作剧”的游戏吧。', `MaleText_loc5`='我們應該晚點來玩不給糖就搗蛋的遊戲。', `MaleText_loc7`='Deberíamos jugar al truco o trato más tarde.', `FemaleText_loc1`='우리 나중에 사탕 얻으러 가야죠.', `FemaleText_loc4`='我们待会再玩“不给糖果就恶作剧”的游戏吧。', `FemaleText_loc5`='我們應該晚點來玩不給糖就搗蛋的遊戲。', `FemaleText_loc7`='Deberíamos jugar al truco o trato más tarde.' WHERE `ID`=23286;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이상합니다... 왜 우리가 이런 날을 축하하는 걸까요?', `MaleText_loc4`='你知道……我们为什么要庆祝这个节日吗？', `MaleText_loc5`='你知道...為什麼我們得要慶祝這個節日嗎?', `MaleText_loc7`='¿Sabes... por qué CELEBRAMOS esta fiesta?', `FemaleText_loc1`='이상해요... 왜 우리가 이런 날을 축하하는 거죠?', `FemaleText_loc4`='你知道……我们为什么要庆祝这个节日吗？', `FemaleText_loc5`='你知道...為什麼我們得要慶祝這個節日嗎?', `FemaleText_loc7`='¿Sabes... por qué CELEBRAMOS esta fiesta?' WHERE `ID`=23287;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='1년 중 이때는 우리의 동맹인 포세이큰에게 매우 의미가 깊은 때랍니다.', `MaleText_loc4`='我们的被遗忘者同盟在每年的这个时候都要举办重要的庆典。', `MaleText_loc5`='這時節對我們被遺忘者來說十分的重要。', `MaleText_loc7`='Esta época del año es bastante importante para nuestros aliados Renegados.', `FemaleText_loc1`='1년 중 이때는 우리의 동맹인 포세이큰에게 매우 의미가 깊은 때랍니다.', `FemaleText_loc4`='我们的被遗忘者同盟在每年的这个时候都要举办重要的庆典。', `FemaleText_loc5`='這時節對我們被遺忘者來說十分的重要。', `FemaleText_loc7`='Esta época del año es bastante importante para nuestros aliados Renegados.' WHERE `ID`=23288;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아제로스엔 이상한 전통이 많군요. 이 축제는 맘에 듭니다.', `MaleText_loc4`='艾泽拉斯世界有很多奇怪的传统。我就喜欢万圣节这个传统节日。', `MaleText_loc5`='艾澤拉斯有許多奇怪的傳統。這個，我喜歡。', `MaleText_loc7`='Azeroth tiene muchas tradiciones extrañas. Esta me gusta.', `FemaleText_loc1`='아제로스엔 이상한 전통이 많네요. 이 축제는 맘에 들어요.', `FemaleText_loc4`='艾泽拉斯世界有很多奇怪的传统。我就喜欢万圣节这个传统节日。', `FemaleText_loc5`='艾澤拉斯有許多奇怪的傳統。這個，我喜歡。', `FemaleText_loc7`='Azeroth tiene muchas tradiciones extrañas. Esta me gusta.' WHERE `ID`=23289;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 맥주 맛 사탕은 없는 겁니까?!', `MaleText_loc4`='怎么就没有啤酒味的糖果呢？！', `MaleText_loc5`='為什麼沒有啤酒口味的糖果啊?!', `MaleText_loc7`='¿Por qué no existen los caramelos con sabor a cerveza?', `FemaleText_loc1`='왜 맥주 맛 사탕은 없는 거죠?!', `FemaleText_loc4`='怎么就没有啤酒味的糖果呢？！', `FemaleText_loc5`='為什麼沒有啤酒口味的糖果啊?!', `FemaleText_loc7`='¿Por qué no existen los caramelos con sabor a cerveza?' WHERE `ID`=23290;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사탕 아니면 골탕? 골탕먹이는 게 훨씬 재밌어요!', `MaleText_loc4`='再来捣乱啊，我说，再来啊。这里可有“真正”的糖哦！', `MaleText_loc5`='我說啊，更多的惡作劇。就是真正的甜頭!', `MaleText_loc7`='Yo digo que más trucos. ¡Esos tratos son de verdad!', `FemaleText_loc1`='사탕 아니면 골탕? 골탕먹이는 게 훨씬 재밌어요!', `FemaleText_loc4`='再来捣乱啊，我说，再来啊。这里可有“真正”的糖哦！', `FemaleText_loc5`='我說啊，更多的惡作劇。就是真正的甜頭!', `FemaleText_loc7`='Yo digo que más trucos. ¡Esos tratos son de verdad!' WHERE `ID`=23291;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음 밀짚인형 태울 때에는 꼭 참가해야겠군.', `MaleText_loc4`='我们一定得参加下次的稻草人焚烧祭典。', `MaleText_loc5`='我們應該要參加下一次的點燃稻草人。', `MaleText_loc7`='Deberíamos acudir a la próxima quema del hombrecillo de mimbre.', `FemaleText_loc1`='다음 밀짚인형 태울 때에는 꼭 참가해야겠어요.', `FemaleText_loc4`='我们一定得参加下次的稻草人焚烧祭典。', `FemaleText_loc5`='我們應該要參加下一次的點燃稻草人。', `FemaleText_loc7`='Deberíamos acudir a la próxima quema del hombrecillo de mimbre.' WHERE `ID`=23292;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 사탕 얻으러 갈 여관이 남았습니까?', `MaleText_loc4`='还有其它的旅店可以捣乱的吗？', `MaleText_loc5`='有更多旅店可以讓我們進去要糖嗎?', `MaleText_loc7`='¿Hay más posadas que podamos visitar para jugar a truco o trato?', `FemaleText_loc1`='아직 사탕 얻으러 갈 여관이 남았나요?', `FemaleText_loc4`='还有其它的旅店可以捣乱的吗？', `FemaleText_loc5`='有更多旅店可以讓我們進去要糖嗎?', `FemaleText_loc7`='¿Hay más posadas que podamos visitar para jugar a truco o trato?' WHERE `ID`=23293;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 뒤틀린 밤에 저주를. 그래도 사탕은 맛있군요.', `MaleText_loc4`='让这个变态的夜晚去见鬼吧。不过，糖倒是真不错。', `MaleText_loc5`='今晚的詭異氣氛真該死。雖然，糖果很棒。', `MaleText_loc7`='Maldito sea este giro de la noche. Eso sí, los dulces están buenos.', `FemaleText_loc1`='이 뒤틀린 밤에 저주를. 그래도 사탕은 맛있네요.', `FemaleText_loc4`='让这个变态的夜晚去见鬼吧。不过，糖倒是真不错。', `FemaleText_loc5`='今晚的詭異氣氛真該死。雖然，糖果很棒。', `FemaleText_loc7`='Maldito sea este giro de la noche. Eso sí, los dulces están buenos.' WHERE `ID`=23294;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='포세이큰은 이 자유를 축하할 권리가 있네.', `MaleText_loc4`='被遗忘者一定要庆祝他们重获自由！', `MaleText_loc5`='被遺忘者慶祝他們的自由是對的。還有什麼更重要呢?', `MaleText_loc7`='Los Renegados hacen bien en celebrar su libertad.', `FemaleText_loc1`='포세이큰은 이 자유를 축하할 권리가 있네.', `FemaleText_loc4`='被遗忘者一定要庆祝他们重获自由！', `FemaleText_loc5`='被遺忘者慶祝他們的自由是對的。還有什麼更重要呢?', `FemaleText_loc7`='Los Renegados hacen bien en celebrar su libertad.' WHERE `ID`=23295;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희 동맹의 성스러운 날을 기념하는 것도 임무라 할 수 있답니다. 좀 이상하기는 해도 말입니다.', `MaleText_loc4`='就算感觉陌生与奇怪，我们也有义务尊重盟友们的神圣节日。', `MaleText_loc5`='榮耀我們盟友的神聖日子是我們的責任，不管多怪異。', `MaleText_loc7`='Es nuestro deber honrar los días sagrados de nuestros aliados por extraños que sean.', `FemaleText_loc1`='저희 동맹의 성스러운 날을 기념하는 것도 임무라 할 수 있지요. 좀 이상하기는 해도 말이에요.', `FemaleText_loc4`='就算感觉陌生与奇怪，我们也有义务尊重盟友们的神圣节日。', `FemaleText_loc5`='榮耀我們盟友的神聖日子是我們的責任，不管多怪異。', `FemaleText_loc7`='Es nuestro deber honrar los días sagrados de nuestros aliados por extraños que sean.' WHERE `ID`=23296;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쫄깃쫄깃하고 말랑말랑한 사탕 없을까요? 씹는 맛이 좀 남다른...', `MaleText_loc4`='真该发明个侏儒夹心软糖啥的……', `MaleText_loc5`='有人應該用彈性地精核心來做糖果。', `MaleText_loc7`='Alguien debería inventar un caramelo relleno de gnomo masticable.', `FemaleText_loc1`='쫄깃쫄깃하고 말랑말랑한 사탕 없나요? 씹는 맛이 좀 남다른...', `FemaleText_loc4`='真该发明个侏儒夹心软糖啥的……', `FemaleText_loc5`='有人應該用彈性地精核心來做糖果。', `FemaleText_loc7`='Alguien debería inventar un caramelo relleno de gnomo masticable.' WHERE `ID`=23297;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 포세이큰의 시대가 왔구나!', `MaleText_loc4`='现在是被遗忘者的时代！', `MaleText_loc5`='現在是被遺忘者的時間了!', `MaleText_loc7`='¡ESTE es el momento de los Renegados!', `FemaleText_loc1`='이제 포세이큰의 시대가 왔어요!', `FemaleText_loc4`='现在是被遗忘者的时代！', `FemaleText_loc5`='現在是被遺忘者的時間了!', `FemaleText_loc7`='¡ESTE es el momento de los Renegados!' WHERE `ID`=23298;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 축제를 기회 삼아 돈을 더 버는 방법이 분명히 있을 텐데...', `MaleText_loc4`='肯·定·有什么办法能趁这节日的时候发上一笔！', `MaleText_loc5`='『一定』有辦法可以從這個節日賺更多的錢。', `MaleText_loc7`='TIENE que haber un modo de ganar dinero con esta fiesta.', `FemaleText_loc1`='이런 축제를 빌미로 돈을 더 버는 방법이 분명히 있을 텐데...', `FemaleText_loc4`='肯·定·有什么办法能趁这节日的时候发上一笔！', `FemaleText_loc5`='『一定』有辦法可以從這個節日賺更多的錢。', `FemaleText_loc7`='TIENE que haber un modo de ganar dinero con esta fiesta.' WHERE `ID`=23299;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여관주인들은 사탕을 공짜로 나눠준다고 화가 났어요.', `MaleText_loc4`='旅店老板们居然免费发糖，真是疯了。', `MaleText_loc5`='旅店老闆一定是瘋了才會免費給這些招待。', `MaleText_loc7`='Los taberneros se han vuelto locos y están haciendo regalitos.', `FemaleText_loc1`='여관주인들은 사탕을 공짜로 나눠준다고 화가 났어요.', `FemaleText_loc4`='旅店老板们居然免费发糖，真是疯了。', `FemaleText_loc5`='旅店老闆一定是瘋了才會免費給這些招待。', `FemaleText_loc7`='Los taberneros se han vuelto locos y están haciendo regalitos.' WHERE `ID`=23300;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='블리즈컨에 오신 것을 환영합니다! 지금 이 선착장을 임시로 대여하여 여러분을 노스렌드로 보내드리고 있습니다. 여기서 별로 멀지 않을 겁니다. 즐거운 시간 보내십시오!', `MaleText_loc4`='欢迎来到暴雪嘉年华！这座临时租借来的码头能带你前往诺森德。船只很快就会靠岸了。祝你旅途愉快！', `MaleText_loc5`='你好，歡迎來到Blizzcon!我們暫時借了這處碼頭送你的北裂境。很快就會到了，玩的開心!', `MaleText_loc7`='¡Saludos y bienvenido a la Blizzcon! Hemos tomado prestado este muelle por un tiempo para transportarte a Rasganorte. Pronto estarás allí. ¡Disfrútalo!' WHERE `ID`=23301;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 그쪽 임무는 도시를 안전하게 지키는 거 아닙니까! 거리에 범죄자들이 넘쳐나는데 내가 어떻게 그 ''간단한 임무''를 수행할 수 있겠소? 더러운 도둑놈 맞힐까 봐 마음 놓고 침도 못 뱉는 곳이 바로 샤트라스요!', `MaleText_loc4`='你的责任就是保障城市的安全！如果大街上到处都是行为卑鄙的家伙，我怎么执行那个“简单的任务”？瞧，在沙塔斯城随便吐口唾沫就能砸到一个肮脏的小偷。', `MaleText_loc5`='而且你被委任維護本城市的安危!我該如何進行我的「簡單任務」要是街道上充滿著低階層人士?我在撒塔斯吐口口水都會打到一些卑鄙的偷竊者。', `MaleText_loc7`='¡Y a ti se te ha encomendado que la ciudad sea segura! ¿Cómo quieres que lleve a cabo mi "simple tarea" si las calles están llenas de indeseables? No puedo escupir en Shattrath sin que le caiga a algún mugriento ladrón.' WHERE `ID`=23302;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 그렇다고 내가 길거리에 침을 뱉는다는 말은 아닙니다...', `MaleText_loc4`='……当然，我不会真的吐口水啦。', `MaleText_loc5`='...當然，我不會隨便吐口水就是。', `MaleText_loc7`='... claro que yo nunca escupiría.' WHERE `ID`=23303;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠흠, 카일 씨, 이 방을 맞은편으로 가려고 엄청나게 노력하고 있소... 나를 좀 진정시켜 주시오!', `MaleText_loc4`='哎咳，凯雷先生，我正在努力穿越这个房间……请帮帮我吧！', `MaleText_loc5`='嗯哼，凱雷先生，我正試著努力穿越過這個房間...請修復我!', `MaleText_loc7`='Ejem, señor Kyle, estoy intentando atravesar la habitación con todas mis fuerzas... ¡Arrégleme por favor!' WHERE `ID`=23304;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영원토록 곰의 혼을 섬기는 것보다 좋은 일이 있을까? 가까이 와라. 영혼을 내게 바쳐라!', `MaleText_loc4`='还有什么能比永久侍奉熊之圣魂更好呢？来呀，将你们的灵魂交给我！', `MaleText_loc5`='有什麼能比侍奉偉大的熊靈以換取永恆的生命還好呢?靠近一點，把你們的靈魂交給我!', `MaleText_loc7`='¿Qué podría ser mejor que servir el espíritu de oso eternamente? Acérquense... ¡Tráiganme sus almas!' WHERE `ID`=23305;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이방인들의 냄새가 난다. 운명을 늦추려 하지 마라. 어서 와라. 금방 끝내주지.', `MaleText_loc4`='闻到你们的气味了，陌生人。别再逃避命运了。过来吧，我很快会把你们献祭给灵魂。', `MaleText_loc5`='聞到你們的氣味了，陌生人。別再逃避命運了。過來吧，我很快會把你們獻祭給靈魂。', `MaleText_loc7`='Puedo olerlos, forasteros. No retrasen su destino. Vengan a mí ahora y haré que sus sacrificios sean rápidos.' WHERE `ID`=23306;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 독수리에게 영혼을 맡겨라. 너희들의 희생이 헛되지 않을 테니...', `MaleText_loc4`='我的猎鹰将把你们的灵魂带到我这里。你们的牺牲也并非毫无意义……', `MaleText_loc5`='我的雄鷹將把你們的靈魂帶到我這裡。你們的犧牲將不會白費...', `MaleText_loc7`='Mis águilas me traerán sus espíritus. Sus sacrificios no serán en vano...' WHERE `ID`=23307;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽을 시간이다, 이방인들이여. 너희들은 여기 오지 말아야 했어...', `MaleText_loc4`='陌生人，你们很快就将步入死亡。你们根本不该来到这里……', `MaleText_loc5`='陌生人，你們很快就將步入死亡。你們根本就不該來到這裡...', `MaleText_loc7`='Su muerte será rápida, forasteros. Nunca debieron venir aquí...' WHERE `ID`=23308;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와라, 멍청이들. 빈 우리를 채워라...', `MaleText_loc4`='来呀，蠢蛋们，来把我的笼子塞满吧……', `MaleText_loc5`='來吧，蠢蛋們。我還有許多空籠子等著你們...', `MaleText_loc7`='Vengan, tontos. Llenen mis jaulas vacías' WHERE `ID`=23309;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='손님이 찾아오셨군. 모두 죽어라. 나는 더 강해진다!', `MaleText_loc4`='我已经等待很久了，陌生人。你的死亡将使我更强大！', `MaleText_loc5`='我已經等待很久了，陌生人。你的死亡使我更強大!', `MaleText_loc7`='Estoy esperando, forasteros. ¡Sus muertes me harán más fuerte!' WHERE `ID`=23310;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대지에서 일어나라, 형제들이여!', `MaleText_loc4`='兄弟们，复活吧！', `MaleText_loc5`='弟兄們，從大地中現身吧!', `MaleText_loc7`='¡Alzaos de la tierra, hermanos míos!' WHERE `ID`=23311;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강철의 주인께서 우리에게 임무를 내리셨다!', `MaleText_loc4`='铁领主交给我们一项任务！', `MaleText_loc5`='鐵矮人主人有任務給我們!', `MaleText_loc7`='¡Nuestros maestros de hierro tienen una misión para nosotros!' WHERE `ID`=23312;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 와라, 친구들. 너희 몸이 내 새끼를 배불리고 너희 영혼이 내 힘이 되리라!', `MaleText_loc4`='过来，朋友们。你们的尸体将是孩子们最好的食物，而你们的灵魂则将壮大我的力量！', `MaleText_loc5`='來吧，朋友們。你們的軀體將會餵食我的寶寶們，你們的靈魂將會讓我充滿力量!', `MaleText_loc7`='Vengan forasteros. El espíritu del dracohalcón quiere almas dignas.' WHERE `ID`=23313;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오너라, 이방인들이여. 용매의 혼은 신선한 영혼에 굶주렸지.', `MaleText_loc4`='过来，陌生人。龙鹰之圣魂已经饥渴太久了。', `MaleText_loc5`='來吧，陌生人。龍鷹之靈渴望著夠份量的靈魂。', `MaleText_loc7`='Vengan, amigos. ¡Sus cuerpos alimentarán a mis crías y sus almas me llenarán de poder!' WHERE `ID`=23314;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나를 따라 산으로 간다! 주인님의 계획을 실천하는 거다!', `MaleText_loc4`='跟着我进入山岭，执行主人的计划！', `MaleText_loc5`='跟我進山裡去完成主人的計畫!', `MaleText_loc7`='¡Seguidme a las montañas para ejecutar el plan de los maestros!' WHERE `ID`=23315;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무나 골라 봐라, 침입자들아! 내 사제 모두가 너희를 반겨줄 테니까.', `MaleText_loc4`='自由选择吧，入侵者们！我手下任何一位祭司都愿意陪陪你们。', `MaleText_loc5`='自由選擇吧，入侵者們!我手下任何一位祭司都願意陪陪你們。', `MaleText_loc7`='¡Elijan, intrusos! Mis sacerdotes estarán encantados de buscarles alojamiento…' WHERE `ID`=23316;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부끄러울 거 없어. 이전에도 수천 명이 왔었다. 너희만 제물이 되는 게 아니야.', `MaleText_loc4`='别害怕。你们之前有千百人尝试过，你们并不孤独。', `MaleText_loc5`='別害怕。你們之前有千百人過來嘗試過。你們並不孤獨。', `MaleText_loc7`='No sean tímidos. Miles han venido antes que ustedes. No estarán solos en su sacrificio.' WHERE `ID`=23317;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희는 실패한다, 이방인들이여. 먼저 온 손님들도 우리 힘만 키워 주고 말았지!', `MaleText_loc4`='你们就要失败了，陌生人。很多人也曾尝试过，但他们只是使我们更强大！', `MaleText_loc5`='你們就要失敗了，陌生人。很多人也曾嘗試過，但他們只是使我們更強大!', `MaleText_loc7`='Van a fracasar, forasteros. ¡Muchos lo intentaron antes, pero solo nos volvieron más fuertes!' WHERE `ID`=23318;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 당신이 그렇게 질색하는 범죄자 중 하나를 영원히 내쫓으려고 했던 겁니다! 다음번엔, 나한테 필요한 사람은 ''유능한'' 수색요원이라고 확실히 이야기해야겠소!', `MaleText_loc4`='我知道你有多讨厌那些卑鄙的家伙，我这不正在设法将他们永久驱逐出沙塔斯城吗！下次，我一定要求配备一名有能力的调查员！', `MaleText_loc5`='我正試著去驅逐那些你一直以來如此厭惡的低階層人士!下一次，我會確切指明我要的是個能幹的調查者!', `MaleText_loc7`='¡Estaba tratando de expulsar a uno de esos indeseables que tanto odias! ¡La próxima vez me aseguraré de explicar que necesito un investigador competente!' WHERE `ID`=23319;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 징징거리는 말 지겨워 죽겠네.', `MaleText_loc4`='你什么时候才会停止瞎扯淡？', `MaleText_loc5`='你有停止過閒聊嗎?', `MaleText_loc7`='¿Alguna VEZ dejas de balbucir?' WHERE `ID`=23320;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s가 얼굴을 찌푸리며 고개를 돌립니다.', `MaleText_loc4`='%s板着脸，把头扭向一边。', `MaleText_loc5`='%s沉下臉並看往別處。', `MaleText_loc7`='%s frunce el ceño y mira hacia otro lado.' WHERE `ID`=23321;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 떠버리를 참아주기엔 돈을 너무 적게 받았는데...', `MaleText_loc4`='我凭什么要忍受这个自吹自擂的家伙……', `MaleText_loc5`='那個人可沒有付我足夠的錢來忍受這個吹牛專家...', `MaleText_loc7`='Ese hombre no me pagó lo suficiente para aguantar a este fanfarrón...' WHERE `ID`=23322;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s가 눈살을 찌푸리며 수색요원 아스릭을 바라봅니다.', `MaleText_loc4`='%s对调查员艾斯瑞克皱了皱眉头。', `MaleText_loc5`='%s對調查員亞斯里克皺眉並挑起一邊的眉毛。', `MaleText_loc7`='%s mira al investigador Asric con el ceño fruncido y arquea una ceja.' WHERE `ID`=23323;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 뭐라고 하셨지요?', `MaleText_loc4`='什么？', `MaleText_loc5`='什麼?', `MaleText_loc7`='¿Qué ha sido eso?' WHERE `ID`=23324;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 아무것도 아닙니다. 그냥 혼잣말이죠.', `MaleText_loc4`='没什么。我只是在自言自语罢了。', `MaleText_loc5`='喔，沒什麼。只不過想得太大聲而已。', `MaleText_loc7`='Oh, nada. Solo pensaba en voz alta.' WHERE `ID`=23325;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='들인 수고가 아깝군, 침입자들아. 의식이 거의 끝나 간다.', `MaleText_loc4`='你们的努力全都白费了，献祭完成了，你们很快也将被囚禁。', `MaleText_loc5`='你們的努力是徒然的，入侵者。儀式已經接近完成了。', `MaleText_loc7`='Sus esfuerzos han sido en vano, intrusos. Los rituales ya casi se han completado.' WHERE `ID`=23326;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 우리가 텅 비고 의식이 끝나면, 너희가 그 자리를 채우게 될 것이다.', `MaleText_loc4`='很快，笼子就会变空，献祭就将完成，而你们，则会代替他们的位置。', `MaleText_loc5`='很快，籠子就會變空，獻祭就將完成，而你們則會代替他們的位置。', `MaleText_loc7`='Pronto las jaulas estarán vacías, los sacrificios se habrán completado y ustedes ocuparan sus puestos allí.' WHERE `ID`=23327;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간이 다 됐다. 너희들이 구하지 못한 저 영혼들과 곧 만나게 해 주마.', `MaleText_loc4`='时间不多了，陌生人。很快你们的灵魂也将落得跟前人一样的下场。', `MaleText_loc5`='時間緊迫，陌生人。很快的你們將會加入那些你們無力拯救的靈魂之中。', `MaleText_loc7`='Se les acaba el tiempo, forasteros. Pronto se unirán a las almas de los que no lograron salvar.' WHERE `ID`=23328;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서둘러라, 사제들! 놈들이 의식을 방해하게 두지 마라!', `MaleText_loc4`='动作快点，祭司们！仪式绝不能被中断！', `MaleText_loc5`='動作快點，祭司們!儀式絕不能被中斷!', `MaleText_loc7`='¡Dense prisa sacerdotes míos! ¡Los rituales no deben interrumpirse!' WHERE `ID`=23329;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제게 의뢰하시는 분들은 대부분 값지고 희귀한 것을 찾으십니다.$B$B$c님은 그런 물건을 구해주실 수 있는 분 같군요. 그 대가로 당신이 탐내고 계신 걸 드리지요.$B$B오늘 제가 구하려는 물건 얘기를 좀 더 해볼까요?', `MaleText_loc4`='这些珍贵的器物都是我的客户指名预订的呢。$b$b$c，只要你能帮我找回来，我是绝对不会亏待你的，我懂你的心思啦。$B$B我们来谈谈今天的订单如何？', `MaleText_loc5`='我的顧客尋找的多是稀有且珍貴的物品。$B$B你可以是那個將東西帶來給我的人，$c。我提供的報酬會是你所渴望的事物。$B$B我們要不要多談些今天我想要取得的東西呢?', `MaleText_loc7`='Muchos son objetos poco comunes y muy preciados que busca mi clientela.$B$BTú podrías traérmelos, $c. A cambio te ofreceré lo que codicies.$B$B¿Hablamos de eso que me gustaría poder obtener hoy?' WHERE `ID`=23330;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황천 바람을 타고 주문이 날아왔고, 마둔은 들었습니다.$B$B누구든 마둔에게 오시면 오늘 처치해야 할 존재를 바람이 알려줄 겁니다.', `MaleText_loc4`='玛哈杜恩听见虚空风中传来的低语声。$B$B有人来到玛哈杜恩面前，谈论起今天的猎物。', `MaleText_loc5`='虛空之風細語著一項命令，而瑪頓恩聽到了。$B$B有一名$g男人:女人;將經過瑪頓恩的面前，而他們討論的正是虛空之風今日要殺的目標。', `MaleText_loc7`='Una orden es susurrada por los vientos abisales y Mah''duun escucha.$B$B$g Un hombre:Una mujer; se presenta ante Mah''duun y hablan sobre aquellos a los que el viento quiere que maten hoy.' WHERE `ID`=23331;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리에게 실패란 없다!', `MaleText_loc4`='我们不会失败！', `MaleText_loc5`='我們不會失敗!', `MaleText_loc7`='¡No fracasaremos!' WHERE `ID`=23332;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시도는 좋았다만, 이제 너희도 실패자의 반열에 들겠구나.', `MaleText_loc4`='你们的努力值得赞赏……但现在，你们就将加入死者的行列了。', `MaleText_loc5`='你們的努力值得讚賞...但現在你們就將加入死者的行列了。', `MaleText_loc7`='Buen intento... pero ahora se unirán a las almas de los que ya han caído.' WHERE `ID`=23333;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지켜봐라. 제물을 바치면 혼과의 결속이 강해지지. 이제, 누구도 우릴 막지 못하리라!', `MaleText_loc4`='注意！所有的祭品都将增强我们与灵魂世界的联系。很快，我们就将无坚不摧！', `MaleText_loc5`='注意。所有的祭品都將增強我們與靈魂世界的聯繫。很快，我們就將無堅不摧!', `MaleText_loc7`='¡Miren! Cada ofrenda fortalecerá nuestros lazos con el mundo de los espíritus. ¡Pronto seremos imparables!' WHERE `ID`=23334;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리 나쁘진 않았다... 너희 덕분에 저들의 운명이 조금 늦춰졌으니. 이제 내게 오너라. 너희가 가치 있는 제물임을 증명하라.', `MaleText_loc4`='你们干得还不坏……你们的努力竟然略略延缓了那不可避免的命运。来我这里吧，你们已经证明自己将是很好的祭品。', `MaleText_loc5`='你們做得不錯...你們的努力稍微延遲了無可避免之事的發生。來我這吧，你們已經證明了自己是夠份量的祭品了。', `MaleText_loc7`='No lo han hecho del todo mal... Sus esfuerzos han retrasado brevemente lo inevitable. Vengan a mí, han demostrado ser ofrendas dignas.' WHERE `ID`=23335;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 심한 소음을 내기 시작합니다.', `MaleText_loc4`='%s喷溅着水花。', `MaleText_loc5`='%s開始口吐白沫。', `MaleText_loc7`='%s comienza a esputar.' WHERE `ID`=23337;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='봐, 작동하고 있어.', `MaleText_loc4`='看，起作用了。', `MaleText_loc5`='看啊，成功了。', `MaleText_loc7`='Mira, funciona.' WHERE `ID`=23338;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소방 기술을 연습할 수 있도록 이곳을 꾸몄답니다. 마을이 언제 위험에 처할지 모르니까요!', `MaleText_loc4`='我们建立这个营地是为了练习灭火技术。你永远都不会知道火灾什么时候会降临！', `MaleText_loc5`='我們設立這個地區是為了作消防演練。你永遠不知道城鎮什麼時候會陷入災難之中!', `MaleText_loc7`='Hemos preparado esta zona para practicar las técnicas de apagado de fuegos. ¡Nunca se sabe cuando estará en peligro la ciudad!', `FemaleText_loc1`='소방 기술을 연습할 수 있도록 이곳을 꾸몄답니다. 마을이 언제 위험에 처할지 모르잖아요!', `FemaleText_loc4`='我们建立这个营地是为了练习灭火技术。你永远都不会知道火灾什么时候会降临！', `FemaleText_loc5`='我們設立這個地區是為了作消防演練。你永遠不知道城鎮什麼時候會陷入災難之中!', `FemaleText_loc7`='Hemos preparado esta zona para practicar las técnicas de apagado de fuegos. ¡Nunca se sabe cuando estará en peligro la ciudad!' WHERE `ID`=23339;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자신이 좀 멋지다고 생각하죠. 안 그래요, 풋내기씨? 투기장에서 실력을 발휘했다면 제가 드릴 게 좀 있죠. 좋은 물건이고 말고요, 크릭셀씨 물건하고는 차원이 다르단 말이에요. 크릭셀씨 물건은 한물갔다는 거, 알고 있죠?$B$B아, 어쨌든 오늘 하루 득템하시라는 말이에요.', `FemaleText_loc4`='孩子，看来你相当自信哦？如果你能在竞技场中占一席之地，我倒是可以送你点什么。是相当不错的东西呢，比克里希的那些破玩意儿好多啦。$b$b祝你好运。', `FemaleText_loc5`='我打賭你覺得你很強悍，對吧，小子?如果你可以讓你自己在競技場上活下來的話，我猜我應該會有什麼可以給你。好東西，跟奎克索的東西不一樣。那正是最後一季，你知道吧?$b$b喔，還有祝你有個美好的一天。', `FemaleText_loc7`='Te crees muy duro ¿eh? Puede que tenga algo para ti si superas la arena. Buen material, no como el de Krixel. Eso es de la temporada pasada ¿sabes?$B$BOh, y que tengas un buen día.' WHERE `ID`=23340;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇네, 우린 여기서 소방 훈련을 한다네. 호드에게 영광을!', `MaleText_loc4`='我们是来练习灭火技术的。荣耀归于部落！', `MaleText_loc5`='我們在這練習消防技巧。榮耀屬於部落!', `MaleText_loc7`='Aquí practicamos las técnicas para apagar fuegos. ¡Honor a la Horda!', `FemaleText_loc1`='그렇네, 우린 여기서 소방 훈련을 한다네. 호드에게 영광을!', `FemaleText_loc4`='我们是来练习灭火技术的。荣耀归于部落！', `FemaleText_loc5`='我們在這練習消防技巧。榮耀屬於部落!', `FemaleText_loc7`='Aquí practicamos las técnicas para apagar fuegos. ¡Honor a la Horda!' WHERE `ID`=23341;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘하셨습니다! 정말로 불이 나도 아무 문제 없겠군요!', `MaleText_loc4`='不错不错！看来我们已经准备好面对真正的火灾了。', `MaleText_loc5`='做的好!等真正發生火災的時候我們已經有萬全的準備了!', `MaleText_loc7`='¡Bien hecho! ¡Cuando se enciendan los verdaderos fuegos, estaremos preparados!', `FemaleText_loc1`='잘하셨어요! 정말로 불이 나도 아무 문제 없겠네요!', `FemaleText_loc4`='不错不错！看来我们已经准备好面对真正的火灾了。', `FemaleText_loc5`='做的好!等真正發生火災的時候我們已經有萬全的準備了!', `FemaleText_loc7`='¡Bien hecho! ¡Cuando se enciendan los verdaderos fuegos, estaremos preparados!' WHERE `ID`=23342;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서두르십시오, $c님! 칼바위 언덕이 불타고 있습니다! 어서 가서 불을 끄십시오!', `MaleText_loc4`='快点，$c！剃刀岭失火了！快上！快去灭火！', `MaleText_loc5`='快，$c!火舌已經蔓延整個剃刀嶺了!快去!幫忙救火!', `MaleText_loc7`='¡Rápido, $c! ¡Cerrotajo está ardiendo! ¡Ve a apagar esos fuegos!', `FemaleText_loc1`='서두르세요, $c님! 칼바위 언덕이 불타고 있어요! 어서 가서 불을 끄세요!', `FemaleText_loc4`='快点，$c！剃刀岭失火了！快上！快去灭火！', `FemaleText_loc5`='快，$c!火舌已經蔓延整個剃刀嶺了!快去!幫忙救火!', `FemaleText_loc7`='¡Rápido, $c! ¡Cerrotajo está ardiendo! ¡Ve a apagar esos fuegos!' WHERE `ID`=23343;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님, 황금골 마을이 불타고 있습니다! 가서 불 끄는 일을 도와주십시오!', `MaleText_loc4`='$n，闪金镇着火了！快去帮忙灭火！', `MaleText_loc5`='$n，閃金鎮的房舍燒起來了!快去幫忙救火!', `MaleText_loc7`='¡$n, Villadorada está ardiendo! ¡Ve y ayúdales a apagar el fuego!', `FemaleText_loc1`='$n 님, 황금골 마을이 불타고 있어요! 가서 불 끄는 일을 도와주세요!', `FemaleText_loc4`='$n，闪金镇着火了！快去帮忙灭火！', `FemaleText_loc5`='$n，閃金鎮的房舍燒起來了!快去幫忙救火!', `FemaleText_loc7`='¡$n, Villadorada está ardiendo! ¡Ve y ayúdales a apagar el fuego!' WHERE `ID`=23344;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 투기장이 적성에 안 맞았던 모양이군요? 좋습니다. 첫 번째 시즌에서 남은 방어구가 빅스톤한테 좀 있는 모양인데, 저흰 그걸 어떻게든 치워버릴 작정입니다. 그래도 세상에 공짜는 없다는 건 아시겠지요?', `MaleText_loc4`='好吧，或许竞技场并不适合你？维克斯顿还有些第一季的存货，我们正想处理掉呢。不过天下没有免费的大餐，你懂我的意思吧？', `MaleText_loc5`='好吧，可能這些競技場不適合你，對吧?好。維斯頓有些第一季剩下的護甲，而我們得用某些方法來擺脫它。不過沒有不勞而獲的東西，知道我的意思吧?', `MaleText_loc7`='Bien, puede que las arenas no sean lo tuyo, ¿verdad? Vale. Vixton tiene algunas sobras de armadura de la primera temporada y tenemos que deshacernos de ellas. Pero nada es gratis ¿me entiendes?', `FemaleText_loc1`='그래, 투기장이 적성에 안 맞았던 모양이네요? 좋아요. 첫 번째 시즌에서 남은 방어구가 빅스톤한테 좀 있는 모양인데, 저흰 그걸 어떻게든 치워버릴 작정이에요. 그래도 세상에 공짜는 없다는 건 알죠?', `FemaleText_loc4`='好吧，或许竞技场并不适合你？维克斯顿还有些第一季的存货，我们正想处理掉呢。不过天下没有免费的大餐，你懂我的意思吧？', `FemaleText_loc5`='好吧，可能這些競技場不適合你，對吧?好。維斯頓有些第一季剩下的護甲，而我們得用某些方法來擺脫它。不過沒有不勞而獲的東西，知道我的意思吧?', `FemaleText_loc7`='Bien, puede que las arenas no sean lo tuyo, ¿verdad? Vale. Vixton tiene algunas sobras de armadura de la primera temporada y tenemos que deshacernos de ellas. Pero nada es gratis ¿me entiendes?' WHERE `ID`=23345;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, 친절한 여행자님, 사심 없이 베푸신 선행에 감사를 표합니다.', `MaleText_loc4`='善良的陌生人，我向你的无私致敬。', `MaleText_loc5`='你好啊，好心的陌生人，感謝你和你無私的行為。', `MaleText_loc7`='Saludos y gracias por tu desinteresado acto.' WHERE `ID`=23346;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이교도들이 제가 가졌던 전부를 빼앗아 갔습니다만, 저를 붙잡고 있던 자에게서 구한 이 부적은 당신께 드리고 싶습니다.', `MaleText_loc4`='这群野蛮人将我洗劫一空，不过我从他们身上偷来的咒符倒是可以送给你。', `MaleText_loc5`='這些異教徒把我的東西都搶走了，但是我可以把我從俘虜者身上取得的符咒送給你。', `MaleText_loc7`='Esos paganos me han robado mis pertenencias, pero puedo ofrecerte este talismán que les quité a mis captores.' WHERE `ID`=23347;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕히 가십시오.', `MaleText_loc4`='再见。', `MaleText_loc5`='再見。', `MaleText_loc7`='Adiós.' WHERE `ID`=23348;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내년에는, 오닉시아나 밸라스트라즈로 변장할 거야. 아, 그게 그건가?', `MaleText_loc4`='明年我计划装扮成一个海盗或者一个刺客。', `MaleText_loc5`='明年，我不是打扮成海盜就是打扮成刺客。', `MaleText_loc7`='El año que viene me disfrazaré de corsario o de asesino.', `FemaleText_loc1`='내년에는, 해적이나 암살자로 변장해 봐야지.', `FemaleText_loc4`='明年我计划装扮成一个海盗或者一个刺客。', `FemaleText_loc5`='明年，我不是打扮成海盜就是打扮成刺客。', `FemaleText_loc7`='El año que viene me disfrazaré de corsaria o de asesina.' WHERE `ID`=23349;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='할로윈에 가면 쓰는 거 좋아하십니까?', `MaleText_loc4`='你觉着这个面具怎么样？', `MaleText_loc5`='你覺得這個面具如何呢?', `MaleText_loc7`='¿Qué te parece la máscara?', `FemaleText_loc1`='할로윈 때 어떤 가면을 쓰세요?', `FemaleText_loc4`='你觉着这个面具怎么样？', `FemaleText_loc5`='你覺得這個面具如何呢?', `FemaleText_loc7`='¿Qué te parece la máscara?' WHERE `ID`=23350;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스를 위하여!', `MaleText_loc4`='为了联盟！', `MaleText_loc5`='為了聯盟!', `MaleText_loc7`='¡Por la Alianza!', `FemaleText_loc1`='얼라이언스를 위하여!', `FemaleText_loc4`='为了联盟！', `FemaleText_loc5`='為了聯盟!', `FemaleText_loc7`='¡Por la Alianza!' WHERE `ID`=23351;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 골드 어딨지? 내 맥주 어딨지? 내 발은 어딨느냐고?', `MaleText_loc4`='我的钱呢？我的酒呢？我的脚呢？', `MaleText_loc5`='我的金子呢?我的啤酒呢?我的腳呢?', `MaleText_loc7`='¿Dónde estar mi oro? ¿Dónde estar mi cerveza? ¿Dónde estar mis pies?', `FemaleText_loc1`='내 골드 어딨죠? 내 맥주는 어딨죠? 내 발은 어딨는 거예요?', `FemaleText_loc4`='我的钱呢？我的酒呢？我的脚呢？', `FemaleText_loc5`='我的金子呢?我的啤酒呢?我的腳呢?', `FemaleText_loc7`='¿Dónde estar mi oro? ¿Dónde estar mi cerveza? ¿Dónde estar mis pies?' WHERE `ID`=23352;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우아아아악! 난 죽고 싶지 않아! 영원히 살고 싶단 말이야! 이건 옳지 않아!', `MaleText_loc4`='哇哇！我还不想死啊！我要永生啊！这完全就不公平啊！', `MaleText_loc5`='哇!我不想死!我想永遠地活下去!真是不公平!', `MaleText_loc7`='¡Buaaahhh! ¡No quiero morir! ¡Quiero vivir eternamente! ¡No es justo!', `FemaleText_loc1`='우아아아앙! 전 죽고 싶지 않아요! 영원히 살고 싶단 말이에요! 억울해요!', `FemaleText_loc4`='哇哇！我还不想死啊！我要永生啊！这完全就不公平啊！', `FemaleText_loc5`='哇!我不想死!我想永遠地活下去!真是不公平!', `FemaleText_loc7`='¡Buaaahhh! ¡No quiero morir! ¡Quiero vivir eternamente! ¡No es justo!' WHERE `ID`=23353;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우우! 전 불쌍하고 조그만 노움일 뿐이에요. 저희는 출신 도시도 없... 아, 잠깐만요.', `MaleText_loc4`='噗嗤！我是一个小侏儒！而且……，我没有主……呃，算了……', `MaleText_loc5`='那算什麼!我是一個可憐的小地精，而且我們還失去了諾姆...喔，等等。', `MaleText_loc7`='¡Buaahhh! Soy un pobre gnomito y no tengo una capi... oh, espera.', `FemaleText_loc1`='엉엉! 전 불쌍하고 조그만 노움일 뿐이에요. 저희는 출신 도시도 없... 아, 잠깐만요.', `FemaleText_loc4`='噗嗤！我是一个小侏儒！而且……，我没有主……呃，算了……', `FemaleText_loc5`='那算什麼!我是一個可憐的小地精，而且我們還失去了諾姆...喔，等等。', `FemaleText_loc7`='¡Buaahhh! Soy una pobre gnomita y no tengo una capi... oh, espera.' WHERE `ID`=23354;
