UPDATE `locales_broadcast_text` SET `MaleText_loc1`='촉수 괴물 같은 내 얼굴을 보고 벌벌 떨어라, 아제로스의 주민들이여!', `MaleText_loc4`='绝望吧！看着我的章鱼脸，绝望吧！可笑的艾泽拉斯人！', `MaleText_loc5`='看著我瘋狂的觸鬚臉龐然後絕望吧，艾澤拉斯生物!', `MaleText_loc7`='¡Mira mi loca cara de tentáculos y desespera, ciudadano de Azeroth!', `FemaleText_loc1`='촉수 괴물 같은 내 얼굴을 보고 벌벌 떨어라, 아제로스의 주민들이여!', `FemaleText_loc4`='绝望吧！看着我的章鱼脸，绝望吧！可笑的艾泽拉斯人！', `FemaleText_loc5`='看著我瘋狂的觸鬚臉龐然後絕望吧，艾澤拉斯生物!', `FemaleText_loc7`='¡Mira mi loca cara de tentáculos y desespera, ciudadano de Azeroth!' WHERE `ID`=23356;
