UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저그 저그! 모크라! 얼...다부!', `MaleText_loc4`='Zug zug！Mok''ra！Er...Dabu！', `MaleText_loc5`='嘖嘖!摩卡什!呃...是的!', `MaleText_loc7`='Zug zug! Mok''ra! ¡Er... Dabu!', `FemaleText_loc1`='저그 저그! 모크라! 얼...다부!', `FemaleText_loc4`='Zug zug！Mok''ra！Er...Dabu！', `FemaleText_loc5`='嘖嘖!摩卡什!呃...是的!', `FemaleText_loc7`='Zug zug! Mok''ra! ¡Er... Dabu!' WHERE `ID`=23359;
