UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 부두 마법 배웠다고, 이 녀석아!', `MaleText_loc4`='老子有了疯狂巫毒啦，哥们！', `MaleText_loc5`='我中了瘋狂的巫毒之術，老兄!', `MaleText_loc7`='¡Yo tener el vudú loco, tío!', `FemaleText_loc1`='저 부두 마법 배웠다고요, 괴물씨!', `FemaleText_loc4`='老子有了疯狂巫毒啦，哥们！', `FemaleText_loc5`='我中了瘋狂的巫毒之術，老兄!', `FemaleText_loc7`='¡Yo tener el vudú loco, tío!' WHERE `ID`=23361;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는야 날씬하고 가냘픈 한 송이 꽃이라네!', `MaleText_loc4`='我是一朵秀丽而脆弱的小花花！', `MaleText_loc5`='我是一枝纖細，嬌貴的花朵!', `MaleText_loc7`='¡Soy una esbelta y delicada flor!', `FemaleText_loc1`='저는 호리 호리 가냘픈 한 송이 꽃이랍니다!', `FemaleText_loc4`='我是一朵秀丽而脆弱的小花花！', `FemaleText_loc5`='我是一枝纖細，嬌貴的花朵!', `FemaleText_loc7`='¡Soy una esbelta y delicada flor!' WHERE `ID`=23362;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐! 마지막 남은 닭고기 네가 먹었나? 특별히 먹으려고 남겨둔 건데!', `MaleText_loc4`='嗨！你吃掉了最后一只鸡？我原本打算将它留到特殊的时刻再吃的！', `MaleText_loc5`='嘿!你把最後的一隻雞吃掉了嗎?我可是為了特殊情況才把牠留下來的耶!', `MaleText_loc7`='¡Hey! ¿Te has comido el pollo que quedaba? ¡Lo reservaba para una ocasión especial!', `FemaleText_loc1`='이봐! 마지막 남은 닭고기 네가 먹었어? 특별히 먹으려고 남겨둔 건데!', `FemaleText_loc4`='嗨！你吃掉了最后一只鸡？我原本打算将它留到特殊的时刻再吃的！', `FemaleText_loc5`='嘿!你把最後的一隻雞吃掉了嗎?我可是為了特殊情況才把牠留下來的耶!', `FemaleText_loc7`='¡Hey! ¿Te has comido el pollo que quedaba? ¡Lo reservaba para una ocasión especial!' WHERE `ID`=23363;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스를 위해! 아니... 호드를 위해! 잠깐... 내가 어디 소속이었지?', `MaleText_loc4`='为了联盟！等等……为了部落！等等，我是哪边的来着……', `MaleText_loc5`='為了聯盟!等一下...為了部落!等一下...我到底站在哪一邊?', `MaleText_loc7`='¡Por la Alianza! Espera... ¡la Horda! Espera... ¿Qué era yo?', `FemaleText_loc1`='얼라이언스를 위해! 아니... 호드를 위해! 잠깐... 내가 어디 소속이었지?', `FemaleText_loc4`='为了联盟！等等……为了部落！等等，我是哪边的来着……', `FemaleText_loc5`='為了聯盟!等一下...為了部落!等一下...我到底站在哪一邊?', `FemaleText_loc7`='¡Por la Alianza! Espera... ¡la Horda! Espera... ¿Qué era yo?' WHERE `ID`=23364;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드를 위해! 아니... 얼라이언스를 위해! 잠깐... 내가 어디 소속이었지?', `MaleText_loc4`='为了部落！不……联盟！嗯……我戴着哪个面具？', `MaleText_loc5`='為了部落!不...為了聯盟!呃...我戴的是哪一方的面罩?', `MaleText_loc7`='¡Por la Horda! No... ¡la Alianza! Uh... ¿Qué máscara tenía yo?', `FemaleText_loc1`='호드를 위해! 아니... 얼라이언스를 위해! 잠깐... 내가 어디 소속이었지?', `FemaleText_loc4`='为了部落！不……联盟！嗯……我戴着哪个面具？', `FemaleText_loc5`='為了部落!不...為了聯盟!呃...我戴的是哪一方的面罩?', `FemaleText_loc7`='¡Por la Horda! No... ¡la Alianza! Uh... ¿Qué máscara tenía yo?' WHERE `ID`=23365;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흥, 지금은 그렇게 말해도 저녁 먹을 땐 생각이 달라질걸!', `MaleText_loc4`='你现在当然这么说啦，等待会吃饭的时候你肯定就不会这么想了！', `MaleText_loc5`='你現在會這麼說啦，等到晚餐來了你就不會這麼想了!', `MaleText_loc7`='¡Eso lo dices ahora, pero a la hora de la cena pensarás de otra manera!', `FemaleText_loc1`='흥, 지금은 그렇게 말해도 저녁 먹을 땐 생각이 달라질걸!', `FemaleText_loc4`='你现在当然这么说啦，等待会吃饭的时候你肯定就不会这么想了！', `FemaleText_loc5`='你現在會這麼說啦，等到晚餐來了你就不會這麼想了!', `FemaleText_loc7`='¡Eso lo dices ahora, pero a la hora de la cena pensarás de otra manera!' WHERE `ID`=23366;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌 부스러기를 먹을지언정 네가 먹다 남긴 음식 따윈 손 안 대!', `MaleText_loc4`='就算只能啃石头充饥，我也不会吃你剩下的东西！', `MaleText_loc5`='除非天底下只剩下石頭可以吃，要不然我不會吃你的剩菜的!', `MaleText_loc7`='¡No comería tus sobras ni si lo único que tuviera para comer fueran escombros!', `FemaleText_loc1`='돌 부스러기를 먹을지언정 네가 먹다 남긴 음식 따윈 손 안 대!', `FemaleText_loc4`='就算只能啃石头充饥，我也不会吃你剩下的东西！', `FemaleText_loc5`='除非天底下只剩下石頭可以吃，要不然我不會吃你的剩菜的!', `FemaleText_loc7`='¡No comería tus sobras ni si lo único que tuviera para comer fueran escombros!' WHERE `ID`=23367;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알았습니다, 그럼 좀 따라와 보십시오.', `MaleText_loc4`='跟着我，小姑娘。', `MaleText_loc5`='好吧，跟我來，女孩。', `MaleText_loc7`='Bien, sígueme, chica.', `FemaleText_loc1`='알았어요, 그럼 좀 따라와 보세요.', `FemaleText_loc4`='跟着我，小姑娘。', `FemaleText_loc5`='好吧，跟我來，女孩。', `FemaleText_loc7`='Bien, sígueme, chica.' WHERE `ID`=23368;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='유용하게 쓰시길 빕니다, $n.', `MaleText_loc4`='$n，希望你能用得着它。', `MaleText_loc5`='希望它能好好的侍奉你，$n。', `MaleText_loc7`='Ojalá te sirva bien, $n.' WHERE `ID`=23369;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아야! 잘 좀 보고 던져!', `MaleText_loc4`='哎唷！扔东西的时候小心点！', `MaleText_loc5`='哎唷!小心你把那東西丟到哪!', `MaleText_loc7`='¡Ay! ¡Mira adónde tiras esa cosa!', `FemaleText_loc1`='이봐! 제대로 좀 던져!', `FemaleText_loc4`='哎唷！扔东西的时候小心点！', `FemaleText_loc5`='哎唷!小心你把那東西丟到哪!', `FemaleText_loc7`='¡Ay! ¡Mira adónde tiras esa cosa!' WHERE `ID`=23370;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='환상적이군! 이 잿불은 거의 열을 발생시키지 않잖아.', `MaleText_loc4`='太神奇了！这些余烬没有丝毫的热度。', `MaleText_loc5`='太好了!這些灰燼幾乎沒有熱度。', `MaleText_loc7`='¡Fascinante! De algún modo estas brasas no generan apenas calor.' WHERE `ID`=23371;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠, 이 연기에서는 한 번도 맡아본 적이 없는 냄새가 나는데. 뭘 태우는 건지 궁금하군.', `MaleText_loc4`='我从来没有闻过这样诡异的烟味。他们在烧什么呢？', `MaleText_loc5`='這個煙跟我之前聞過的不一樣。我想知道他們在這燒些什麼。', `MaleText_loc7`='Este humo no se parece a nada que haya olido antes. Me pregunto qué estarán quemando.' WHERE `ID`=23372;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠흠, 고맙소 이방인.', `MaleText_loc4`='陌生人，谢谢你。', `MaleText_loc5`='嗯嗯，謝謝你陌生人。', `MaleText_loc7`='Hmmm, gracias colega.' WHERE `ID`=23373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아쉽지만 여기서 찾아낸 건, 이 낡은 함뿐이오. 가져가시오.', `MaleText_loc4`='除了这只古老的箱子，我也没别的东西可给你的了。收下吧。', `MaleText_loc5`='我恐怕就只有這個在這發現的老舊胸甲而已。歡迎你拿走它。', `MaleText_loc7`='Me temo que solo tengo este viejo baúl que he descubierto aquí. Es todo tuyo.' WHERE `ID`=23374;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 안에 든 것이... 쓸모 있었으면 하오.', `MaleText_loc4`='希望你能……用得着。', `MaleText_loc5`='我希望你會發現它...是有用的。', `MaleText_loc7`='Espero que sus contenidos te resulten... útiles.' WHERE `ID`=23375;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음을 기약하며...', `MaleText_loc4`='再见……', `MaleText_loc5`='直到我們下次見面...', `MaleText_loc7`='Hasta la próxima...' WHERE `ID`=23376;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가을 축제에선 항상 맥주통이 부족하다네!$B$B내 개인 산양 한 마리하고 그 고삐를 빌려주겠네.$B$B맥주통을 하나 가져다줄 때마다 동전을 몇 개 주지. 그때마다 산양도 좀 더 오래 타게 해주겠네! 주의하게! 일단 이 일을 시작하면, 내일까지는 다시 할 수 없다고! 자 준비는 되었나?', `MaleText_loc4`='美酒节上总是需要大量的酒桶！$B$B我会让你从我们这里借一头山羊和一根缰绳。$B$B你每给我带来一个酒桶，我就给你一些奖币，作为你给我带来酒桶的感谢，我甚至会让你更久地使用我的山羊！

但是，只要你开始了，在明天以前你就不能再做了。

你确定已经准备好了吗？', `MaleText_loc5`='啤酒節總是需要更多的酒桶!$b$b我會借給你一頭私人山羊的韁繩。$b$b每一次你帶一個酒桶給我，我就給你一些獎品章。你每帶來一個酒桶，我還會加長你使用山羊的時間!  

注意!一旦你開始了，你就得再等到明天才能再進行一次。

你確定你已經準備好要這麼做了嗎?', `MaleText_loc7`='¡Siempre hacen falta más barriles en la Fiesta de la Cerveza!$B$BTe prestaré las riendas de uno de mis carneros personales.$B$BPor cada barril que me traigas te daré unas fichas. ¡Hasta dejaré que te quedes con el carnero un ratito más por cada barril! 

¡Presta atención! Una vez que empieces, no podrás repetirlo hasta mañana.

¿Estás seguro de que estás preparado?', `FemaleText_loc1`='가을 축제에선 항상 맥주통이 부족하지요!$B$B내 개인 산양 한 마리하고 그 고삐를 빌려주겠어요.$B$B맥주통을 하나 가져다줄 때마다 동전을 몇 개 드리죠. 그때마다 산양도 좀 더 오래 타게 해주겠어요! 알아두세요! 일단 이 일을 시작하면, 내일까지는 다시 할 수 없어요! 자 준비는 되었나요?', `FemaleText_loc4`='美酒节上总是需要大量的酒桶！$B$B我会让你从我们这里借一头山羊和一根缰绳。$B$B你每给我带来一个酒桶，我就给你一些奖币，作为你给我带来酒桶的感谢，我甚至会让你更久地使用我的山羊！

但是，只要你开始了，在明天以前你就不能再做了。

你确定已经准备好了吗？', `FemaleText_loc5`='啤酒節總是需要更多的酒桶!$b$b我會借給你一頭私人山羊的韁繩。$b$b每一次你帶一個酒桶給我，我就給你一些獎品章。你每帶來一個酒桶，我還會加長你使用山羊的時間!  

注意!一旦你開始了，你就得再等到明天才能再進行一次。

你確定你已經準備好要這麼做了嗎?', `FemaleText_loc7`='¡Siempre hacen falta más barriles en la Fiesta de la Cerveza!$B$BTe prestaré las riendas de uno de mis carneros personales.$B$BPor cada barril que me traigas te daré unas fichas. ¡Hasta dejaré que te quedes con el carnero un ratito más por cada barril! 

¡Presta atención! Una vez que empieces, no podrás repetirlo hasta mañana.

¿Estás seguro de que estás preparado?' WHERE `ID`=23377;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 일할 준비가 되었습니다! 좋은 산양으로 주십시오!', `MaleText_loc4`='我今天准备为你工作！给我点好酒！', `MaleText_loc5`='今天我已經準備好為你工作了!給我好東西吧!', `MaleText_loc7`='¡Estoy listo para trabajar para ti hoy! ¡Dame algo bueno!', `FemaleText_loc1`='오늘 일할 준비가 되었어요! 좋은 산양으로 주세요!', `FemaleText_loc4`='我今天准备为你工作！给我点好酒！', `FemaleText_loc5`='今天我已經準備好為你工作了!給我好東西吧!', `FemaleText_loc7`='¡Estoy lista para trabajar para ti hoy! ¡Dame algo bueno!' WHERE `ID`=23378;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='드디어! 누군가 저를 구해 주는군요...', `FemaleText_loc4`='哦！差不多该有人来救我了……', `FemaleText_loc5`='喔喔!該是有人解救我的時候了...', `FemaleText_loc7`='¡Oooh! Ya era hora de que alguien me rescatara...' WHERE `ID`=23379;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말 감사합니다. 부디 이걸 받아주세요. 여기를 기억하게 할 만한 건 아무것도 지니기 싫거든요.', `FemaleText_loc4`='我想我应该感激你。请收下这个。我不希望留着任何会让我想起这个地方的东西。', `FemaleText_loc5`='我想我應該會很高興。請接受這個。我不想要任何會提醒我想到這個地方的東西。', `FemaleText_loc7`='Supongo que debería agradecértelo. Por favor, toma esto. No quiero nada que me recuerde a este lugar.' WHERE `ID`=23380;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='붙잡혔을 때 트롤 녀석들한테 훔친 겁니다. 어쩌면 당신이 녀석들을 상대할 때 써먹을 수 있을지도 모르죠.', `FemaleText_loc4`='在我被抓住时，我从一名巨魔身上偷来了这枚咒符。或许你能利用它来对付这帮家伙。', `FemaleText_loc5`='我在被抓的時候從那些食人妖當中一個的身上拿走的。也許你可以找個方法用它來對抗他們。', `FemaleText_loc7`='Se lo quité a uno de los trols mientras me capturaban. Quizá puedas encontrar un modo de usarlo en su contra.' WHERE `ID`=23381;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기는 이제 지긋지긋해요. 안녕히.', `FemaleText_loc4`='我受够这个地方了。再见。', `FemaleText_loc5`='我已經受夠了這個地方。再會。', `FemaleText_loc7`='Ya me he cansado de este lugar. Adiós.' WHERE `ID`=23382;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오오, 드디어!', `FemaleText_loc4`='啊，终于！', `FemaleText_loc5`='啊啊啊，終於!', `FemaleText_loc7`='¡Ahhh, por fin!' WHERE `ID`=23383;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잡히기 직전에 이 부적을 찾았어요. 당신에게 유용할지도 모르겠네요...', `FemaleText_loc4`='在他们抓到我之前，我找到了这枚咒符。或许你能用得着……', `FemaleText_loc5`='喂，我在他們抓到我之前剛好發現了這個符咒。也許它會對你在這裡有些幫助...', `FemaleText_loc7`='Encontré este amuleto justo antes de que me capturaran. Quizá pueda servirte de algo aquí...' WHERE `ID`=23384;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그게 도움이 됐으면 좋겠네요. 이 혐오스러운 짐승들을 누군가 막아야만 해요!', `FemaleText_loc4`='我希望你能用得着它。必须阻止这群卑鄙的禽兽！', `FemaleText_loc5`='我希望它會有所幫助。一定要制止這些邪惡的野獸!', `FemaleText_loc7`='Espero que te sirva de ayuda. ¡Es necesario detener a esas infames bestias!' WHERE `ID`=23385;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='행운을 빌어요!', `FemaleText_loc4`='祝你好运！', `FemaleText_loc5`='祝你好運!', `FemaleText_loc7`='¡Buena suerte!' WHERE `ID`=23386;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 드디어. 정말 반가운 일이오.', `MaleText_loc4`='瞧，形势转好呀。', `MaleText_loc5`='哎呀。真是個令人開心的逆轉。', `MaleText_loc7`='Bien. Que cambio de planes más agradable' WHERE `ID`=23387;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 주정뱅이 녀석들 중 하나가 아니라 나를 구하다니, 정말 탁월한 선택이었소.', `MaleText_loc4`='你救的是我，而不是那些醉鬼，你应该感到庆幸。', `MaleText_loc5`='你很幸運救到的是我，而不是其它那些可憐的醉鬼。', `MaleText_loc7`='Tienes suerte de haberme rescatado tú y no uno de esos pobres borrachos.' WHERE `ID`=23388;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 감사와 함께 이 돈을 받아 주시오. 폐를 끼친 데 대한 보답이오.', `MaleText_loc4`='请收下这点微不足道的报酬，接受我的谢意吧。', `MaleText_loc5`='請收下這份報酬，連同我的感謝，為了你所遇到的麻煩。', `MaleText_loc7`='Acepta este pago y mi gratitud por las molestias.' WHERE `ID`=23389;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하시오, $n.', `MaleText_loc4`='保重，$n。', `MaleText_loc5`='保重，$n。', `MaleText_loc7`='Cuídate, $n.' WHERE `ID`=23390;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와! 살았다! 고마워요, $n!', `MaleText_loc4`='耶！我得救了！谢谢你，$n。', `MaleText_loc5`='哇喔!我得救了!謝謝你，$n。', `MaleText_loc7`='¡Yujuuu! ¡Estoy salvado! Gracias, $n.' WHERE `ID`=23391;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 이런. 이게 대체 무슨 냄새지... 잠깐. 하, 어이쿠! 제 감각이 돌아오려면 시간이 좀 걸리겠는데요.', `MaleText_loc4`='我的天哪，那是什么气味——噢，哎呦！我的嗅觉恐怕要好一会儿才能恢复了。', `MaleText_loc5`='喔，我的天啊。那是什麼味道 - 喔等等，哎呀!我猜我的感官會需要一點時間來重新調整。', `MaleText_loc7`='Oh, cielos. ¿Qué es ese olor...? Espera, je, je, ¡ups! Creo que necesitaré algo de tiempo para recuperar mis sentidos.' WHERE `ID`=23392;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미안하군요, 친구. 자, 여기 있어요. 이 정도면 절 구하는 데 쓰신 비용이 충당되겠죠?', `MaleText_loc4`='抱歉，朋友。收下吧，这应该能弥补你在营救我的过程中遭受的损失。', `MaleText_loc5`='我道歉，朋友們。現在，這裡。這應該會對解救我所造成的損失有所幫助。', `MaleText_loc7`='Lo siento, amigos. Aquí tienen. Esto ayudará a cubrir los gastos de mi rescate.' WHERE `ID`=23393;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나중에 봐요!', `MaleText_loc4`='再见！', `MaleText_loc5`='再會啦!', `MaleText_loc7`='¡Hasta luego!' WHERE `ID`=23394;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 재료 다듬어서 요리했지? 뭘 기다리는 거야?!', `MaleText_loc4`='你把那些材料都切好并扔下锅了吗？你在磨蹭什么呢？！', `MaleText_loc5`='這些材料已經切好下鍋了嗎?為什麼那麼慢?!', `MaleText_loc7`='¿Ya están cortados y cocinados esos ingredientes? ¿Entonces a qué esperamos?' WHERE `ID`=23395;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 해야 할 요리가 한참 남았어! 놀지 말라고!', `MaleText_loc4`='今天还有好几道菜要做！赶紧！', `MaleText_loc5`='今天還有一打的盤子要洗!動作快點!', `MaleText_loc7`='¡Aún tenemos que acabar una docena de platos hoy! ¡Muévete!' WHERE `ID`=23396;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='팔꿈치 기름을 좀 집어넣어! 자네가 만들 때는 그냥 기름도 좀 넣는 게 좋을지도 모르겠군. 마그하르 녀석들은 갈래발굽 기름에 환장하니까 말이야.', `MaleText_loc4`='放点牛油进去！可能还需要加点普通油脂。玛格汉兽人可喜欢裂蹄牛油啦！', `MaleText_loc5`='放一點肘部的油脂進去!也許可以同時放一點一般的油脂進去。那些瑪格哈人非常喜歡裂蹄脂肪的味道。', `MaleText_loc7`='¡Échale un poco de grasa de codo! ¡Y ya que estás, un poco de grasa normal también! A esos mag''har les gusta la grasa de Uñagrieta.' WHERE `ID`=23397;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='알았어요, 알았다고요! 스튜 만드는 데 집중하게 입 좀 다물어 주시죠!', `FemaleText_loc4`='好啦！闭上你的嘴，让我们做好这道菜！', `FemaleText_loc5`='對，對!閉上你的嘴讓我完成這份燉肉!', `FemaleText_loc7`='¡Sí, sí! ¡Cállate y déjame acabar este estofado!' WHERE `ID`=23398;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='천재 씨, 물이 더 빨리 끓게 해 주시죠!', `FemaleText_loc4`='天哪，你就不能快点把水煮沸吗！', `FemaleText_loc5`='水不會因此就滾的，天才!', `FemaleText_loc7`='¡No puedo hacer que el agua hierva más rápido, genio!' WHERE `ID`=23399;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='언제 완성되냐고요? 다 되면 완성되겠죠! 짜증나!', `FemaleText_loc4`='该煮好的时候自然会煮好的！', `FemaleText_loc5`='該好的時候就會好，豈有此理!', `FemaleText_loc7`='¡Estará cuando esté, maldita sea!' WHERE `ID`=23400;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 이게 꿈이 아닌가? 내가... 내가 그 끔찍한 저주에서 벗어난 건가?', `MaleText_loc4`='啊，这是真的吗？我……我摆脱了那个可怕的诅咒？', `MaleText_loc5`='喔，這有可能嗎?我...我擺脫了那個可怕的詛咒了?', `MaleText_loc7`='Oh, ¿es cierto? ¿Ya no... cargo con esa horrible maldición?' WHERE `ID`=23401;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 감사를 말로는 다 표현할 수 없군요, $n. 당신의 친절에 진심으로 감사드립니다.', `MaleText_loc4`='$n，任何语言都不足以表达我的感激之情。', `MaleText_loc5`='言語無法傳達我的感謝。$n。感謝你的仁慈。', `MaleText_loc7`='Las palabras no pueden expresar mi gratitud, $n. Gracias por tu amabilidad.' WHERE `ID`=23402;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보시다시피, 이 야만인들한테 잡히는 바람에 가진 게 별로 없습니다. 하지만, 뭐라도 드리고 싶군요. 와서 쓸만한 게 있는지 살펴보시죠.', `MaleText_loc4`='你也看到啦，被这帮野蛮人洗劫后我身上也没多少值钱货了。但是我愿意与你分享我仅有的一切。来瞧瞧吧。', `MaleText_loc5`='就像你看得到的，我在被那些野人抓住之後所剩不多，不過歡迎你看看我所有的東西。來吧，看一下。', `MaleText_loc7`='Como puedes ver, no me queda casi nada desde que esos salvajes me atraparon, pero puedes quedarte con lo que tengo. Ven, echa un vistazo.' WHERE `ID`=23403;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 잡히기 전에 어서 여기를 떠야겠습니다. 멀리 가진 않을 테니 필요한 게 있으시면 저를 다시 찾으세요.', `MaleText_loc4`='我得走啦，省得又被抓住。如果你有任何需要，都可以来找我。', `MaleText_loc5`='我現在得走了，在我再度被抓住之前。如果你有需要任何物品的話，我不會走太遠的。', `MaleText_loc7`='Debo irme antes de que me vuelvan a pillar. Si necesitas algo, no estaré lejos.' WHERE `ID`=23404;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='으음, 오동통한 파리! 다시 맛볼 수 있어서 정말 기쁘군.', `FemaleText_loc4`='嗯……苍蝇！好在现在我能尝尝它们的味道啦。', `FemaleText_loc5`='嗯嗯，蒼蠅!既然我能夠品嚐他們會更好。', `FemaleText_loc7`='¡Mmmm, moscas! Mucho mejores ahora que puedo saborearlas.' WHERE `ID`=23405;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='죽은 자들 사이에 돌아오게 해 줘서 정말 고맙네.', `FemaleText_loc4`='能变回从前的样子真好，谢谢你。', `FemaleText_loc5`='回到死亡中感覺真好，謝謝你。', `FemaleText_loc7`='Es agradable volver a encontrarse entre las sin vida, gracias a ti.' WHERE `ID`=23406;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내가 가진 물건 중에 자네에게 필요한 게 있을지도 모르지. 자, 한번 살펴보게.', `FemaleText_loc4`='或许我这里有你感兴趣的东西？过来，看看有喜欢的吗？', `FemaleText_loc5`='或許我可以提供你一些有趣的東西?來吧，看看有沒有什麼你喜歡的東西吧。', `FemaleText_loc7`='Quizá pueda ofrecerte algo que te interese. Ven a ver si te gusta algo.' WHERE `ID`=23407;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 가야겠네, $n. 나중에 보세.', `FemaleText_loc4`='我得走了，$n。再见。', `FemaleText_loc5`='我現在一定得走了，$n。再見。', `FemaleText_loc7`='He de irme, $n. Nos vemos.' WHERE `ID`=23408;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='낙하지점 확인을 시작합니다!', `MaleText_loc4`='开始检查投掷点！', `MaleText_loc5`='落下點檢查開始!', `MaleText_loc7`='¡Iniciando comprobación de punto de lanzamiento!' WHERE `ID`=23409;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가고일의 습격이다! 대응 사격 준비!', `MaleText_loc4`='石像鬼发动了攻击！兄弟们，握紧你们的步枪！', `MaleText_loc5`='石像鬼來襲!舉起你的火槍，老兄!', `MaleText_loc7`='¡Las gárgolas atacan! ¡Tomen sus rifles!' WHERE `ID`=23410;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이야! 나 다시 사람 됐다!', `FemaleText_loc4`='耶！我又变成女孩啦！', `FemaleText_loc5`='耶!我又是個女孩了!', `FemaleText_loc7`='¡Chachi! ¡Vuelvo a ser una chica!' WHERE `ID`=23411;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='구해 주셔서 고마워요. 역겨운 개구리 되는 거 정말 싫거든요!', `FemaleText_loc4`='谢谢你救了我。我讨厌变成青蛙！', `FemaleText_loc5`='感謝你救了我。我討厭變成一隻噁心的青蛙!', `FemaleText_loc7`='Gracias por rescatarme. ¡Odio ser una asquerosa rana!' WHERE `ID`=23412;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='엄마가 낯선 사람하고 이야기하지 말랬지만, 친절하게도 절 구해 주셨으니까... 제가 납치되기 전에 찾은 멋진 물건을 드릴게요.', `FemaleText_loc4`='我不喜欢和陌生人讲话，不过你看上去挺友善的。给，这是我被绑架前找到的小玩意儿。', `FemaleText_loc5`='我真的不該跟陌生人交談，不過你對我這麼好。這裡有個特別的東西，是我在被綁架前剛好發現的。', `FemaleText_loc7`='Se supone que no debería hablar con extraños, pero tú has sido muy amable conmigo. Aquí tienes algo especial que encontré antes de que me secuestraran.' WHERE `ID`=23413;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 가야겠어요. 조심하세요!', `FemaleText_loc4`='我得走了。小心！', `FemaleText_loc5`='我該走了。保重!', `FemaleText_loc7`='Tengo que irme. ¡Ten cuidado!' WHERE `ID`=23414;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경고! 전원 공급 저하. 긴급 조치 실행.', `MaleText_loc4`='警告！电源供给失效——启动紧急措施。', `MaleText_loc5`='警告!能量供應失常 - 啟動緊急措施。', `MaleText_loc7`='¡Atención! Fallo en el suministro de energía, activando medidas de seguridad.' WHERE `ID`=23415;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크리스마스까지 남은 시간: $3930d.', `MaleText_loc4`='离圣诞节还有$3930d天。', `MaleText_loc5`='距離聖誕節還有:$3930d。', `MaleText_loc7`='Tiempo que falta hasta navidad: $3930d.', `FemaleText_loc1`='크리스마스까지 남은 시간: $3930d.', `FemaleText_loc4`='离圣诞节还有$3930d天。', `FemaleText_loc5`='距離聖誕節還有:$3930d。', `FemaleText_loc7`='Tiempo que falta hasta navidad: $3930d.' WHERE `ID`=23416;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아악, 바보같으니! 당신 때문에 모든 것을 다 망쳤다고요!', `MaleText_loc4`='啊，蠢货！你毁了一切！', `MaleText_loc5`='喔不!你搞砸了所有的事情!', `MaleText_loc7`='¡Oh, tonto! ¡Lo has arruinado todo!' WHERE `ID`=23417;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저렇게 멀리 뛰는 게 얼마나 근사한 일인지 알기나 해요?', `MaleText_loc4`='你觉得它能跳多远？', `MaleText_loc5`='你知道能夠一次跳那麼遠有多棒嗎?', `MaleText_loc7`='¿Te imaginas lo genial que es saltar a esa distancia?' WHERE `ID`=23418;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아 그러니까, 어쨌든 친구들이 좀 그리워지기 시작했어요. 아마 내가 이런 생각을 했다는 건 안 믿겠지요! 아, 여기, 이거 받으세요. 숨바꼭질하다가 찾은 거예요.', `MaleText_loc4`='我开始想念我的朋友了——他们肯定不会相信我的经历！哦，给你——这是我在玩捉迷藏游戏的时候找到的。', `MaleText_loc5`='好吧，反正我也開始想念我的好朋友了─他們一定不會相信的!喔，這給你，這是我在玩捉迷藏的時候找到的東西。', `MaleText_loc7`='Bueno, de todas formas empezaba a echar de menos a mis amigos... ¡No se lo van a creer! Toma, puedes quedarte esto, lo encontré jugado al escondite.' WHERE `ID`=23419;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래도 개구리 소리는 낼 수 있는지 어디 확인해 볼까요...', `MaleText_loc4`='让我看看我还能不能发出那种声音……', `MaleText_loc5`='讓我們看看我還能不能發出那種聲音...', `MaleText_loc7`='A ver si todavía puedo hacer ese ruido...' WHERE `ID`=23420;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흐으음. 마음은 고맙지만, 도와줄 필요까진 없었다고요.', `MaleText_loc4`='嗯。谢谢你的好意，不过我不需要帮助。', `MaleText_loc5`='哼嗯。謝謝你，但是我不需要任何幫助。', `MaleText_loc7`='Pfff. Gracias igualmente, pero no necesitaba ayuda.' WHERE `ID`=23421;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 처했던 상황을 되돌릴 주문을 연구하던 중이었고 이제 거의 다 찾았... <끄아아악> 이런!', `MaleText_loc4`='我试图念诵咒语来摆脱困境，我其实就快成功啦<呱>……我的天哪！', `MaleText_loc5`='我正在研究一個可以解除我目前困境的咒語，而我即將發現一個<呱呱呱>...喔我的天啊!', `MaleText_loc7`='Estaba trabajando en un hechizo que contrarrestara este apuro y estaba a punto de encontrar un <CROOAAC>... ¡Oh, cielos!' WHERE `ID`=23422;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음, 어쨌건 신세를 좀 진 것 같네요. 여기, 이거 하나 받으세요. 저한텐 많이 있으니까.', `MaleText_loc4`='好吧，我应该报答你的——给，收下吧。这玩意儿我多得是。', `MaleText_loc5`='嗯，我想我的確欠你一點人情─來，收下這樣東西吧。我還有很多。', `MaleText_loc7`='Bien, supongo que te debo algo... Toma, quédate uno de estos. Tengo muchos.' WHERE `ID`=23423;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳을 빨리 뜨시는 게 좋을 걸요. 여기서는 개구리로 모습이 바뀌는 게 좋은 일 축에 드니까요.', `MaleText_loc4`='你或许想离开这儿。我倒觉得在这种鬼地方被变成青蛙算是幸运的了。', `MaleText_loc5`='你最好考慮離開這裡。變成一隻青蛙在這裡而言已經算是運氣好了。', `MaleText_loc7`='Puede que quieras marcharte de este lugar. Creo que ser transformado en rana es una de las mejores cosas que te pueden pasar aquí.' WHERE `ID`=23424;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어머나! 어여쁜 제 모습으로 돌아왔네요? 멋져요! 평생 개구리의 모습으로 살아가야 하는 게 아닌가 생각했다고요.', `FemaleText_loc4`='哦！我恢复先前的美貌啦？太好了！我还以为要当一辈子青蛙呢。', `FemaleText_loc5`='喔!我恢復成以前美麗的容貌了嗎?真是太棒了!我還以為我會永遠當一隻青蛙。', `FemaleText_loc7`='¡Oh! ¡Tan guapa como siempre! ¡Qué bien! Pensé que sería una rana de por vida.' WHERE `ID`=23425;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='진짜 짜증이 났었어요. 온몸은 끈적거리는데다가, 내가 내 눈을 계속 핥고 있었다고요!', `FemaleText_loc4`='太可怕了。我的皮肤变得黏糊糊的，我的舌头还一直在舔着自己的眼珠！', `FemaleText_loc5`='那個時候真是糟透了。我全身又黏又滑，而且我一直不停的舔我的眼睛!', `FemaleText_loc7`='Ha sido terrible. ¡Era viscosa y no hacia más que lamerme los ojos!' WHERE `ID`=23426;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오셔서 제 마법을 풀어주셔서 정말 감사해요. 여기 트롤 상자 하나 받으시고 절 기억해주세요.', `FemaleText_loc4`='谢谢你救了我。请收下这只巨魔货箱，就当作我们之间的回忆吧。', `FemaleText_loc5`='感謝老天爺有你的幫忙。請從這些食人妖寶箱中挑一個收下當作我送你的紀念品吧。', `FemaleText_loc7`='Gracias al cielo que has venido. Quédate una de estas cajas trol para recordarme.' WHERE `ID`=23427;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 구역질 나는 연못은 두 번 다시 보기도 싫거든요. 감사드려요, $n 님. 절대로 잊지 못할 거예요!', `FemaleText_loc4`='我再也不想看见这个肮脏的池塘了。谢谢你，$n。我永远都不会忘记你！', `FemaleText_loc5`='我再也不想看見這個討厭的池塘了。感謝你，$n。我永遠不會忘記你!', `FemaleText_loc7`='No quiero volver a ver esta asquerosa charca. Gracias, $n. ¡Nunca te olvidaré!' WHERE `ID`=23428;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정신이 나갔었나 봅니다. 그렇게 까다로운 작전에 점술가 길드가 협력하도록 허가하다니...', `MaleText_loc4`='我肯定是疯了，让一个占星者来帮忙处理这么一个棘手的工作……', `MaleText_loc5`='我必須拋開我的感受，允許一個占卜者來幫忙如此棘手的工作...', `MaleText_loc7`='He debido perder un tornillo... Permitir que un Arúspice colaborase en una operación tan delicada...' WHERE `ID`=23429;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 할 일은 다 했습니다. 이 도시를 지켜내는 일은 권한 밖의 일이지요. 그 일을 하라고 사람들이 당신을 "평화감시단"이라 부르는 게 아닐까 싶습니다만?', `MaleText_loc4`='我做了我该做的一切。不过保护城市的安宁并不是我的职责，不然要你这个卫兵干什么？', `MaleText_loc5`='我提供了服務。保護這個城市不是我的職責。我相信這就是為什麼他們稱呼你們為「保安官」的原因嗎?', `MaleText_loc7`='Yo cumplí con mi cometido. La protección de la ciudad está fuera de mi jurisdicción. Creo que por eso os llaman "¿pacificadores?"' WHERE `ID`=23430;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 이 조사를 철저히 하고 있었다면, 장담하건대, 그 증거가 온전히 남아 있었을 겁니다. 그 대신, 상당히 의문이 가는 당신 식대로 했더니...', `MaleText_loc4`='如果是我们全权负责调查的话，我向你保证，证据仍然会很安全。可惜，我们使用了你的狗屁方法……', `MaleText_loc5`='我們曾全權經手調查，我向你保證，證據會妥善保存。其實，我們用得是你高度質疑的方式...', `MaleText_loc7`='Si nos hubiéramos encargado de la investigación completa, te aseguro que las pruebas habrían estado a salvo. Sin embargo, utilizamos tus cuestionables métodos...' WHERE `ID`=23431;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇겠지요. 제 방법이 좀 불확실하긴 합니다. 그렇지만 처음 장소에서 "그립타"를 사기꾼이라고 밝혀낸 것은 제 방법이었음을 짚고 넘어가고 싶군요! 그냥 평화나 감시하고 계시죠, 간단한 임무조차도 해내지 못하면서 무슨!', `MaleText_loc4`='当然，我的方法可能有待商榷。那就是我行事的方式，不过我要说明的是，是我的方法首先揭示了格里夫塔这个骗子的真面目。你所要做的只是保证城市的安宁，但你并没有完成这个简单的任务！', `MaleText_loc5`='當然。我的方式不可靠。這是我的法則，我會註記，首先揭露那個「格利夫塔」為騙子!你只要保持平靜，而你卻在那個簡單的任務中失敗了!', `MaleText_loc7`='Por supuesto. Mis métodos son cuestionables. He de apuntar que fue mi metodología la que descubrió que "Griftah" era un fraude. ¡Tú solo tenías que mantener la paz y has fracasado en tan fácil tarea!' WHERE `ID`=23432;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무능한 데다가, 코나 훌쩍이는 주제에 겉멋만 들었군.', `MaleText_loc4`='你这个无能的家伙，只会说大话的败家子。', `MaleText_loc5`='不合格，愛哭的花花公子。', `MaleText_loc7`='Incompetente dandi llorón.' WHERE `ID`=23433;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘난 척하며 틀에 박힌 소리나 해대는 허풍선이 같으니.', `MaleText_loc4`='你这个自负的家伙，保守的空谈家。', `MaleText_loc5`='太浮誇了，急躁的碎嘴者。', `MaleText_loc7`='Presuntuoso charlatán mojigato.' WHERE `ID`=23434;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1과;와; 수색요원 아스릭이 서로 말없이 노려보는 눈빛이 심상치 않습니다.', `MaleText_loc4`='%s和调查员艾斯瑞克怒目而视。', `MaleText_loc5`='%s及調查員亞斯里克安靜的瞪著彼此，瞇起他們的眼睛。', `MaleText_loc7`='%s y el investigador Asric se miran en silencio, con los ojos entrecerrados.' WHERE `ID`=23435;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이봐요, $g잘생긴 오빠:이쁜 언니;! 뭐 필요한 것 없어요?', `FemaleText_loc4`='嗨！有什么我可以帮忙的吗？', `FemaleText_loc5`='嘿，美人!我可以幫你做什麼嗎?', `FemaleText_loc7`='¡Hola $gguapito:guapita;! ¿Qué puedo hacer por ti?' WHERE `ID`=23436;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러니까 내가 뭘 찾고 있는지 알고 싶단 건가요? 그 자세 맘에 드는군요... 튼튼하고 용기 있는 사람이 필요합니다. 머리도 잘 쓰면 좋겠지만, 당신은 그게 안 되니 몸으로 때워야겠군요.$B$B그 성가신 검은무쇠 드워프들이 공격해오면 그들에게 맥주잔을 던지면 돼요. 그냥 맥주를 채워서 던지는 거죠. 간단하답니다.$B$B드워프 한 녀석씩 쓰러뜨릴 때마다 표시가 매겨질 겁니다. 그러면 저한테 오세요. 표시 하나마다 상품권을 드리도록 하죠.', `MaleText_loc4`='这么看来你想知道我在寻找什么吗？我正在找一个既勇敢又强壮的家伙。聪明是一方面啦，不过你也得有一定的肌肉才行。$B$B当那些讨厌的黑铁矮人进攻时，你要以投掷杯子的方式来攻击他们——就是扔杯子击倒他们就这么简单。$B$B你每打倒一个矮人，你就会被标记一次。和我交谈，我就会根据你得到的印记数量发给你奖券。', `MaleText_loc5`='所以你想要知道我在找什麼嗎?我喜歡那個想法...我在找強壯又勇敢的人。聰明是一回事，不過你還要能夠有點肌肉來加分。$b$b無論那些討人厭的黑鐵矮人何時來攻擊，你都能對他們丟擲酒桶來攻擊他們。只要把它喝光然後丟出去。很簡單的。$b$b你每擊倒一個矮人，你就得到分數。來跟我談談，我會以你擁有的每一點分數來給予獎品券。', `MaleText_loc7`='¿Así que quieres saber qué estoy buscando? Me gusta... Busco a alguien fuerte y valiente. El cerebro es importante, pero tienes que tener músculos que lo apoyen.$B$BCuando esos molestos enanos Hierro Negro ataquen, puedes devolverles el ataque lanzándoles una jarra. Bébetela y tira. Fácil.$B$BPor cada enano que derribes, serás marcado. Habla conmigo y te daré un vale por cada marca que tengas.', `FemaleText_loc1`='그러니까 내가 뭘 찾고 있는지 알고 싶단 거죠? 그 자세 맘에 드는군요... 튼튼하고 용기 있는 사람이 필요해요. 머리도 잘 쓰면 좋겠지만, 당신은 그게 안 되니 몸으로 때우면 되겠군요.$B$B그 성가신 검은무쇠 드워프들이 공격해오면 그들을 향해 맥주잔을 던지면 돼요. 그냥 맥주를 채워서 던지는 거죠. 간단하답니다.$B$B드워프 한 녀석씩 쓰러뜨릴 때마다 표시를 받을 거예요. 그러면 저한테 오세요. 표시 하나마다 상품권을 드리도록 하죠.', `FemaleText_loc4`='这么看来你想知道我在寻找什么吗？我正在找一个既勇敢又强壮的家伙。聪明是一方面啦，不过你也得有一定的肌肉才行。$B$B当那些讨厌的黑铁矮人进攻时，你要以投掷杯子的方式来攻击他们——就是扔杯子击倒他们就这么简单。$B$B你每打倒一个矮人，你就会被标记一次。和我交谈，我就会根据你得到的印记数量发给你奖券。', `FemaleText_loc5`='所以你想要知道我在找什麼嗎?我喜歡那個想法...我在找強壯又勇敢的人。聰明是一回事，不過你還要能夠有點肌肉來加分。$b$b無論那些討人厭的黑鐵矮人何時來攻擊，你都能對他們丟擲酒桶來攻擊他們。只要把它喝光然後丟出去。很簡單的。$b$b你每擊倒一個矮人，你就得到分數。來跟我談談，我會以你擁有的每一點分數來給予獎品券。', `FemaleText_loc7`='¿Así que quieres saber qué estoy buscando? Me gusta... Busco a alguien fuerte y valiente. El cerebro es importante, pero tienes que tener músculos que lo apoyen.$B$BCuando esos molestos enanos Hierro Negro ataquen, puedes devolverles el ataque lanzándoles una jarra. Bébetela y tira. Fácil.$B$BPor cada enano que derribes, serás marcado. Habla conmigo y te daré un vale por cada marca que tengas.' WHERE `ID`=23437;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비행기가 아름답지 않습니까? 조종해 보고 싶으시지요?', `MaleText_loc4`='瞧，她多漂亮呀！想带她出去兜兜风吗？', `MaleText_loc5`='她不是很美嗎?要讓她帶你兜個一圈嗎?', `MaleText_loc7`='¿No es preciosa? ¿Quieres llevarla a dar una vuelta?' WHERE `ID`=23438;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맥주통 수호대 표시를 찾는다는 얘기는 들었습니다. 저건 다 뭡니까?', `MaleText_loc4`='我听说你在寻找酒桶保卫者的印记。那是什么？', `MaleText_loc5`='我聽說你在尋找酒桶保管者印記。那是什麼啊?', `MaleText_loc7`='He oído que buscas marcas de protector de barriles. ¿Qué son?', `FemaleText_loc1`='맥주통 수호대 표시를 찾는다는 얘기는 들었어요. 저건 다 뭔가요?', `FemaleText_loc4`='我听说你在寻找酒桶保卫者的印记。那是什么？', `FemaleText_loc5`='我聽說你在尋找酒桶保管者印記。那是什麼啊?', `FemaleText_loc7`='He oído que buscas marcas de protector de barriles. ¿Qué son?' WHERE `ID`=23439;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 말도 안 되는 당신 고글은 어떻게 된 겁니까?', `MaleText_loc4`='你的疯狂眼镜有什么用？', `MaleText_loc5`='你的護目鏡怎麼那麼古怪?', `MaleText_loc7`='¿Qué son esas gafas tan raras?', `FemaleText_loc1`='그 말도 안 되는 당신 고글은 어떻게 된 거죠?', `FemaleText_loc4`='你的疯狂眼镜有什么用？', `FemaleText_loc5`='你的護目鏡怎麼那麼古怪?', `FemaleText_loc7`='¿Qué son esas gafas tan raras?' WHERE `ID`=23440;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='목소리를 낮추게. 저들이 들으면 곤란하니까.', `MaleText_loc4`='小声点，$c。别被他们发现了。', `MaleText_loc5`='小聲點，$c，可別讓它們聽見我們。', `MaleText_loc7`='Mantén la voz baja, $c. No queremos que nos oigan.' WHERE `ID`=23441;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='궁금한 게 더 있습니다.', `MaleText_loc4`='我还有一个问题。', `MaleText_loc5`='我有另外一個問題。', `MaleText_loc7`='Tengo otra pregunta.', `FemaleText_loc1`='궁금한 게 더 있어요.', `FemaleText_loc4`='我还有一个问题。', `FemaleText_loc5`='我有另外一個問題。', `FemaleText_loc7`='Tengo otra pregunta.' WHERE `ID`=23442;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 거기! 경주용 산양과 산양 경주에 대해서 좀 더 알아보고 싶지 않나?', `MaleText_loc4`='嗨！你有兴趣知道更多关于赛羊和赛羊会的事吗？', `MaleText_loc5`='嘿你好!有興趣學學更多有關競速山羊及山羊競速的事嗎?', `MaleText_loc7`='¡Hola! ¿Te interesa aprender más sobre los carneros de carreras y las carreras de carneros?', `FemaleText_loc1`='이봐요, 거기! 경주용 산양과 산양 경주에 대해서 좀 더 알아보고 싶지 않으신가요?', `FemaleText_loc4`='嗨！你有兴趣知道更多关于赛羊和赛羊会的事吗？', `FemaleText_loc5`='嘿你好!有興趣學學更多有關競速山羊及山羊競速的事嗎?', `FemaleText_loc7`='¡Hola! ¿Te interesa aprender más sobre los carneros de carreras y las carreras de carneros?' WHERE `ID`=23443;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공짜로 탈 수 있습니까?', `MaleText_loc4`='我能免费得到一匹坐骑？', `MaleText_loc5`='我會得到一隻免費坐騎嗎?', `MaleText_loc7`='¿Tendré una montura gratuita?', `FemaleText_loc1`='공짜로 탈 수 있나요?', `FemaleText_loc4`='我能免费得到一匹坐骑？', `FemaleText_loc5`='我會得到一隻免費坐騎嗎?', `FemaleText_loc7`='¿Tendré una montura gratuita?' WHERE `ID`=23444;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 산양을 더 빨리 달리게 할 수는 없습니까?', `MaleText_loc4`='我要怎么样才能让山羊跑得更快些？', `MaleText_loc5`='我要如何使我的山羊跑得更快一點?', `MaleText_loc7`='¿Cómo puedo hacer que mi carnero vaya más deprisa?', `FemaleText_loc1`='제 산양을 더 빨리 달리게 할 수는 없나요?', `FemaleText_loc4`='我要怎么样才能让山羊跑得更快些？', `FemaleText_loc5`='我要如何使我的山羊跑得更快一點?', `FemaleText_loc7`='¿Cómo puedo hacer que mi carnero vaya más deprisa?' WHERE `ID`=23445;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='속도를 다르게 하려면 어떻게 해야 합니까?', `MaleText_loc4`='速度有什么区别？', `MaleText_loc5`='不同的速度代表什麼意思?', `MaleText_loc7`='¿Qué es eso de las distintas velocidades?', `FemaleText_loc1`='속도를 다르게 하려면 어떻게 해야 하나요?', `FemaleText_loc4`='速度有什么区别？', `FemaleText_loc5`='不同的速度代表什麼意思?', `FemaleText_loc7`='¿Qué es eso de las distintas velocidades?' WHERE `ID`=23446;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='산양이 저 때문에 녹초가 될 수도 있습니까?', `MaleText_loc4`='我的山羊会筋疲力尽吗？', `MaleText_loc5`='我可以累垮我的山羊嗎?', `MaleText_loc7`='¿Puedo cansar a mi carnero?', `FemaleText_loc1`='산양이 저 때문에 녹초가 될 수도 있나요?', `FemaleText_loc4`='我的山羊会筋疲力尽吗？', `FemaleText_loc5`='我可以累垮我的山羊嗎?', `FemaleText_loc7`='¿Puedo cansar a mi carnero?' WHERE `ID`=23447;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 복잡하게 들리는군요...', `MaleText_loc4`='听上去很复杂……', `MaleText_loc5`='那聽起來都很複雜...', `MaleText_loc7`='Eso parece muy complicado...', `FemaleText_loc1`='아주 복잡하게 들리는군요...', `FemaleText_loc4`='听上去很复杂……', `FemaleText_loc5`='那聽起來都很複雜...', `FemaleText_loc7`='Eso parece muy complicado...' WHERE `ID`=23448;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 임무 하나를 맡으시면, 산양을 한 마리 빌려드립니다. 그냥 빌려드리는 거라서 계속 탈 수 있는 게 아니랍니다. 산양이 좀 느린 것 같이 보일 수도 있지만 그럴 때는 고삐를 조금 늦추면 제 속도를 낼 겁니다.$B$B우리 산양은 사과를 좋아한답니다. 길에 사과가 담긴 통을 몇 개 놨으니 지나가면서 꼭 챙겨가십시오. 사과를 먹이면 녀석은 피곤한 것도 모르게 될 겁니다.', `MaleText_loc4`='在你接受了任务之后，我们会借给你一头山羊。只是借你而已，所以你不能永远拥有它。山羊可能看上去有点慢，不过只要甩几下缰绳，它就会加快速度。$B$B我们的山羊爱吃苹果。我们已经在一路上放了很多苹果，记得顺路吃几个。吃苹果会让你的山羊忘记疲惫。', `MaleText_loc5`='當你接受其中一個任務時，我們將會借你一頭山羊。因為是借的，所以你不會永遠持有牠。山羊也許看起來速度很慢，不過只要稍微放鬆韁繩，牠就會加快速度。$b$b我們的山羊愛死蘋果了。我們已經在沿路放置了幾籃蘋果，所以記得要停下來。吃蘋果將會使你的山羊忘記牠的疲累。', `MaleText_loc7`='Cuando aceptes una de estas tareas, te prestaremos un carnero de carreras. Es un préstamo, así que no durará para siempre. El carnero puede parecer lento, pero dale con las riendas y cogerá el ritmo.$B$BA nuestros carneros les encantan las manzanas. Hemos colocado algunos contenedores con manzanas por el camino, así que asegúrate de parar junto a ellos. Comer manzanas hará que tu carnero olvide lo cansado que está.', `FemaleText_loc1`='여기 임무 하나를 맡으시면, 산양을 한 마리 빌려드립니다. 그냥 빌려드리는 거라서 계속 탈 수 있는 게 아니랍니다. 산양이 좀 느린 것 같이 보일 수도 있지만 그럴 때는 고삐를 조금 늦추면 제 속도를 낼 겁니다.$B$B우리 산양은 사과를 좋아한답니다. 길에 사과가 담긴 통을 몇 개 놨으니 지나가면서 꼭 챙겨가십시오. 사과를 먹이면 녀석은 피곤한 것도 모르게 될 겁니다.', `FemaleText_loc4`='在你接受了任务之后，我们会借给你一头山羊。只是借你而已，所以你不能永远拥有它。山羊可能看上去有点慢，不过只要甩几下缰绳，它就会加快速度。$B$B我们的山羊爱吃苹果。我们已经在一路上放了很多苹果，记得顺路吃几个。吃苹果会让你的山羊忘记疲惫。', `FemaleText_loc5`='當你接受其中一個任務時，我們將會借你一頭山羊。因為是借的，所以你不會永遠持有牠。山羊也許看起來速度很慢，不過只要稍微放鬆韁繩，牠就會加快速度。$b$b我們的山羊愛死蘋果了。我們已經在沿路放置了幾籃蘋果，所以記得要停下來。吃蘋果將會使你的山羊忘記牠的疲累。', `FemaleText_loc7`='Cuando aceptes una de estas tareas, te prestaremos un carnero de carreras. Es un préstamo, así que no durará para siempre. El carnero puede parecer lento, pero dale con las riendas y cogerá el ritmo.$B$BA nuestros carneros les encantan las manzanas. Hemos colocado algunos contenedores con manzanas por el camino, así que asegúrate de parar junto a ellos. Comer manzanas hará que tu carnero olvide lo cansado que está.' WHERE `ID`=23449;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='산양을 받으실 때 고삐도 같이 드립니다. 할머니가 물려주신 고삐는 아니지만, 어쨌든 쓸 수는 있으니까요!$B$B산양이 어느 정도 속도를 낼 때까지 고삐를 좀 늦추십시오. 계속 고삐를 늦추면서 이랴이랴! 그러면 나는 듯이 달릴 겁니다!$B$B하지만, 더 빨리 달릴수록 더 쉽게 지치니 조심하셔야 합니다.', `MaleText_loc4`='给你山羊的同时，你也同样会得到一根缰绳。这可不是什么祖传的宝贝，你得真的去使用它！$B$B甩甩缰绳就可以让它加快些速度。你的缰绳放得越松，山羊就会跑得越快。$B$B不过它跑得越快，就越容易疲劳。所以你得注意点。', `MaleText_loc5`='當你得到一隻山羊時，你也會得到韁繩。不過這可不是你祖母的韁繩，你必須使用它!$b$b只要放鬆韁繩數次就可稍稍加快速度。持續的放鬆韁繩然後盡情奔馳吧!你會飛起來的!$b$b不過牠跑得愈快就愈容易覺得累。所以你得小心點。', `MaleText_loc7`='Cuando te dan un carnero, también te entregan las riendas. Pero estas no son las riendas de la abuelita, estas tienes que usarlas.$B$BUsa las riendas para conseguir velocidad. Sigue usándolas y ¡arre! ¡Estarás volando!', `FemaleText_loc1`='산양을 받으실 때 고삐도 같이 드립니다. 할머니가 물려주신 고삐는 아니지만, 어쨌든 쓸 수는 있으니까요!$B$B산양이 어느 정도 속도를 낼 때까지 고삐를 좀 늦추세요. 계속 고삐를 늦추면서 이랴이랴! 그러면 나는 듯이 달릴 거예요!$B$B하지만, 더 빨리 달릴수록 더 쉽게 지치니 조심하셔야 해요.', `FemaleText_loc4`='给你山羊的同时，你也同样会得到一根缰绳。这可不是什么祖传的宝贝，你得真的去使用它！$B$B甩甩缰绳就可以让它加快些速度。你的缰绳放得越松，山羊就会跑得越快。$B$B不过它跑得越快，就越容易疲劳。所以你得注意点。', `FemaleText_loc5`='當你得到一隻山羊時，你也會得到韁繩。不過這可不是你祖母的韁繩，你必須使用它!$b$b只要放鬆韁繩數次就可稍稍加快速度。持續的放鬆韁繩然後盡情奔馳吧!你會飛起來的!$b$b不過牠跑得愈快就愈容易覺得累。所以你得小心點。', `FemaleText_loc7`='Cuando te dan un carnero, también te entregan las riendas. Pero estas no son las riendas de la abuelita, estas tienes que usarlas.$B$BUsa las riendas para conseguir velocidad. Sigue usándolas y ¡arre! ¡Estarás volando!' WHERE `ID`=23450;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='산양 고삐를 늦추기 시작하면, 속도가 달라지는게 보입니다. 처음에 산양은 걷는 속도로 움직이기 시작합니다. 고삐를 더 늦추면 속보로 걷습니다. 속보로 걷는 산양 고삐를 좀 더 늦추면 그보다 더 빨리 구보로 걷게 됩니다. 구보로 걸을 때 고삐를 더 늦추면 전속력으로 질주할 겁니다.', `MaleText_loc4`='你只要一开始甩甩缰绳，就可以看到山羊速度的改变。它起初是步行，甩几下缰绳以后就会开始疾走，在它疾走的时候再来几下，就会开始慢跑了。在它慢跑得时候再加把劲，就可以让它飞奔起来。', `MaleText_loc5`='一旦你開始放鬆山羊的韁繩，你會看到牠的速度改變了。牠一開始是用走的。稍稍放鬆韁繩牠就會開始快步前進。當牠快步前進時多放鬆幾下就會變成慢跑。當牠慢跑時再放鬆幾下就會讓牠疾馳起來了。', `MaleText_loc7`='Una vez que empieces a usar las riendas con el carnero, verás su velocidad cambiar. Comienza andando. Tira un poco de las riendas y se pondrá a trotar. Usa las riendas mientras trota para que vaya a medio galope. Tirar un poco más de las riendas hará que galope.', `FemaleText_loc1`='산양 고삐를 늦추기 시작하면, 속도가 달라지는게 보이죠. 처음에 산양은 걷는 속도로 움직이기 시작하지요. 고삐를 더 늦추면 속보로 걸어요. 속보로 걷는 산양 고삐를 좀 더 늦추면 그보다 더 빨리 구보로 걷게 돼요. 구보로 걸을 때 고삐를 더 늦추면 전속력으로 질주할 거예요.', `FemaleText_loc4`='你只要一开始甩甩缰绳，就可以看到山羊速度的改变。它起初是步行，甩几下缰绳以后就会开始疾走，在它疾走的时候再来几下，就会开始慢跑了。在它慢跑得时候再加把劲，就可以让它飞奔起来。', `FemaleText_loc5`='一旦你開始放鬆山羊的韁繩，你會看到牠的速度改變了。牠一開始是用走的。稍稍放鬆韁繩牠就會開始快步前進。當牠快步前進時多放鬆幾下就會變成慢跑。當牠慢跑時再放鬆幾下就會讓牠疾馳起來了。', `FemaleText_loc7`='Una vez que empieces a usar las riendas con el carnero, verás su velocidad cambiar. Comienza andando. Tira un poco de las riendas y se pondrá a trotar. Usa las riendas mientras trota para que vaya a medio galope. Tirar un poco más de las riendas hará que galope.' WHERE `ID`=23451;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 오랫동안 산양을 계속 천천히 걷게 하거나 전속력으로 달리게 하면 지치고 맙니다. 산양이 기운을 차리게 하고 싶으면, 보통 속도나 느린 속도로 걷게 하십시오. 주변에 사과를 담아놓은 통으로 산양을 데려가서 사과를 먹이면 기운을 차릴 겁니다.', `MaleText_loc4`='让你的山羊慢跑或者飞奔太久的话，它会精疲力尽。如果你想让山羊恢复，让它步行或疾走一会儿就行了。如果附近有苹果就更好了，带它去吃一点，可以更快地恢复。', `MaleText_loc5`='使你的山羊維持在慢跑或是疾馳時間過久的話會讓牠精疲力盡。如果你想讓你的山羊恢復體力的話，讓牠用走的或是快步前進。如果附近有蘋果籃的話，把他帶到那去恢復體力。', `MaleText_loc7`='Mantener al carnero a medio galope o galope durante demasiado tiempo hará que se canse. Si quieres que tu carnero se recupere un poco, deja que ande o trote. Si hay contenedores de manzanas cerca, llévalo junto a ellos.', `FemaleText_loc1`='너무 오랫동안 산양을 계속 천천히 걷게 하거나 전속력으로 달리게 하면 지치고 말지요. 산양이 기운을 차리게 하고 싶으시면, 보통 속도나 느린 속도로 걷게 하세요. 주변에 사과를 담아놓은 통으로 산양을 데려가서 사과를 먹이면 기운을 차릴 거예요.', `FemaleText_loc4`='让你的山羊慢跑或者飞奔太久的话，它会精疲力尽。如果你想让山羊恢复，让它步行或疾走一会儿就行了。如果附近有苹果就更好了，带它去吃一点，可以更快地恢复。', `FemaleText_loc5`='使你的山羊維持在慢跑或是疾馳時間過久的話會讓牠精疲力盡。如果你想讓你的山羊恢復體力的話，讓牠用走的或是快步前進。如果附近有蘋果籃的話，把他帶到那去恢復體力。', `FemaleText_loc7`='Mantener al carnero a medio galope o galope durante demasiado tiempo hará que se canse. Si quieres que tu carnero se recupere un poco, deja que ande o trote. Si hay contenedores de manzanas cerca, llévalo junto a ellos.' WHERE `ID`=23452;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='산양 경주는 보기보다 쉽지만, 몇 가지 요령이 필요하답니다. 고삐를 사용하고, 기회가 있을 때마다 한 사과를 먹이고, 너무 지치지 않도록 주의하시면 됩니다.', `MaleText_loc4`='赛羊其实比看上去更简单，不过要掌握的话还是需要技术的。如果你能避免让你的山羊精疲力尽，你只需要用用缰绳，吃吃苹果就可以了。', `MaleText_loc5`='山羊競速本身比看起來的簡單多了，不過它是需要技巧來統御的。只要使用你的韁繩，還有可以的話讓牠吃吃蘋果，避免你的山羊精疲力盡。', `MaleText_loc7`='Montar en carnero es más fácil de lo que parece, pero hace falta habilidad para ser un experto. Usa las riendas, come manzanas si puedes y evita que tu carnero se canse.', `FemaleText_loc1`='산양 경주는 보기보다 쉽지만, 몇 가지 요령이 필요하지요. 고삐를 사용하고, 기회가 있을 때마다 한 사과를 먹이고, 너무 지치지 않도록 주의하시면 된답니다.', `FemaleText_loc4`='赛羊其实比看上去更简单，不过要掌握的话还是需要技术的。如果你能避免让你的山羊精疲力尽，你只需要用用缰绳，吃吃苹果就可以了。', `FemaleText_loc5`='山羊競速本身比看起來的簡單多了，不過它是需要技巧來統御的。只要使用你的皮鞭，可以的話讓牠吃吃蘋果，以避免你的山羊精疲力盡。', `FemaleText_loc7`='Montar en carnero es más fácil de lo que parece, pero hace falta habilidad para ser un experto. Usa las riendas, come manzanas si puedes y evita que tu carnero se canse.' WHERE `ID`=23453;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠... 이상하군. 난 자네가 그 스컬지 수정과 연결된 뭔가를 찾았다고 생각했는데 말이야.$B$B우린 어떻게든 저 방어막을 해제하고 적을 무너뜨릴 방법을 찾아야 하네. 그곳으로 돌아가서 뭔가 발견할 때까지 스컬지를 좀 더 처치할 수 있겠나?', `MaleText_loc4`='$c，真是奇怪。我以为你已经发现了与天灾水晶关联的东西。$B$B我们必须设法关闭水晶的护盾，然后彻底摧毁它们。在你有所发现之前不如再回去多杀些天灾军团的成员？', `MaleText_loc5`='嗯，$c，這真的很奇怪。我以為你早就找到和這些天譴水晶相關連的東西了。$B$B我們真的應該找出怎麼關閉他們護盾的方法，好解決他們。你認為你能重返那裡，多殺一些天譴軍直到找出線索嗎?', `MaleText_loc7`='Es extraño, $c. Pensaba que habrías encontrado algo relacionado con esos cristales apestadores.$b$bDeberíamos encontrar una manera de derribar sus escudos para acabar con ellos. ¿Crees que podrías salir ahí y matar a unos cuantos miembros más de la Plaga hasta que des con algo?' WHERE `ID`=23454;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음은 이미 겪어 보았노라. 이제 어떤 모험이 날 기다리는가?', `MaleText_loc4`='我曾经经历过这样的结局。这次会有新意吗？', `MaleText_loc5`='我也曾面對過這樣的末路。還有什麼新的冒險在等著呢?', `MaleText_loc7`='Hasta este punto he llegado antes. ¿Qué nueva aventura tendré por delante?' WHERE `ID`=23455;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='음? 뭔가?$B$B시간 없으니 빨리 말해 보게!', `FemaleText_loc4`='嗯？这是什么？$B$B别浪费时间！', `FemaleText_loc5`='嗯?你想說什麼?$B$B時間不等人啊!', `FemaleText_loc7`='¿Sí? ¿Qué ocurre?$B$B¡El tiempo no espera a nadie!' WHERE `ID`=23456;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='널 위해 남겨뒀다, 덩치 큰 녀석아!', `MaleText_loc4`='我特意为你留着这个呢！', `MaleText_loc5`='我留下這些東西給你，大孩子!', `MaleText_loc7`='¡He estado reservando esto para ti, machote!' WHERE `ID`=23457;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이상하군. 난 자네가 스컬지들에게서 스컬지 수정을 처리하는 데 유용하게 쓸 뭔가를 찾았다고 생각했는데 말이야.$B$B확실하게 말해야겠군, $c 친구. 해안으로 돌아가서 뭔가 쓸 만한 걸 찾을 때까지 녀석들을 계속 처치하게.', `FemaleText_loc4`='奇怪，我还以为你从那些天灾军团成员身上找到了关闭瘟疫水晶的方法呢。$B$B$c，我建议你有所发现之前，返回海滩继续屠杀他们。', `FemaleText_loc5`='奇怪，我以為你早就已經從天譴軍身上找到可以用來對付這些天譴水晶的東西了。$B$B如果我能建議，我也真的這麼建議，$c，回去海灘，繼續屠殺他們，直到你能找到有用的東西給我為止。', `FemaleText_loc7`='Extraño. Pensaba que habrías encontrado algo útil en esos miembros de la Plaga que pudieran ayudarnos con los cristales apestadores.$B$BSi puedo sugerirlo, y lo sugiero, $c, vuelve a la playa y continúa matándolos hasta que encuentres algo que me pueda servir.' WHERE `ID`=23458;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계획대로 되어가고 있습니다, 팰컨크레스트 경. 단언컨대 이제는 시간문제일 뿐입니다.', `MaleText_loc4`='一切正在按照计划进行着，法库雷斯特公爵。我向你保证，这只是时间问题。', `MaleText_loc5`='事情一如計畫發展，法庫雷斯特領主。我跟您保證，只是時間長短的問題而已。', `MaleText_loc7`='Todo va según lo planeado, Lord Falconcrest. Te aseguro que solo es cuestión de tiempo.', `FemaleText_loc1`='계획대로 되어가고 있어요, 팰컨크레스트 경. 단언컨대 이제는 시간문제일 뿐이지요.', `FemaleText_loc4`='一切正在按照计划进行着，法库雷斯特公爵。我向你保证，这只是时间问题。', `FemaleText_loc5`='事情一如計畫發展，法庫雷斯特領主。我跟您保證，只是時間長短的問題而已。', `FemaleText_loc7`='Todo va según lo planeado, Lord Falconcrest. Te aseguro que solo es cuestión de tiempo.' WHERE `ID`=23459;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋은 소식을 가져왔다고 생각해도 되겠나?', `MaleText_loc4`='我想你应该是带来了什么好消息吧？', `MaleText_loc5`='我猜你帶來了好消息?', `MaleText_loc7`='¿Supongo que traes buenas noticias?', `FemaleText_loc1`='좋은 소식을 가져왔다고 생각해도 될까?', `FemaleText_loc4`='我想你应该是带来了什么好消息吧？', `FemaleText_loc5`='我猜你帶來了好消息?', `FemaleText_loc7`='¿Supongo que traes buenas noticias?' WHERE `ID`=23460;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하나 살 수 없습니까?', `MaleText_loc4`='有办法可以买到山羊吗？', `MaleText_loc5`='有辦法買一隻嗎?', `MaleText_loc7`='¿Hay algún modo de comprar uno?', `FemaleText_loc1`='하나 살 수 없을까요?', `FemaleText_loc4`='有办法可以买到山羊吗？', `FemaleText_loc5`='有辦法買一隻嗎?', `FemaleText_loc7`='¿Hay algún modo de comprar uno?' WHERE `ID`=23461;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가을 축제 상품권을 넉넉히 모으셨다면 가을 축제 광장에 있는 상품권 교환원이 "명예 양조장이" 손도장을 드릴 겁니다.$b$b그 도장을 받아 오셔야 가을 축제 특선 길들인 산양을 사실 수 있답니다. 하지만 만만한 가격이 아니라는 건 알아두셔야 합니다!', `MaleText_loc4`='如果你有足够多的美酒节奖券，美酒节营地的奖券兑换员就可以给你一个“荣誉酿酒商”的戳印。$b$b有了那个戳印，我就可以卖给你一头美酒节赛羊。不过我要提醒你，它们可并不便宜！', `MaleText_loc5`='如果你得到了夠多的啤酒節獎品券，位於啤酒營地的貝爾碧·迅移會給你一個『榮譽釀酒者』手印。$b$b那個手印將可讓我賣給你一匹啤酒節騎乘用山羊。不過提醒你，它們可不便宜啊!', `MaleText_loc7`='"Si consigues suficientes vales para la Fiesta de la Cerveza, el canjeador de vales, en el campamento de la Fiesta de la Cerveza, te dará un "Sello de "Cervecero Honorario"".$B$BEse sello me permitirá venderte un carnero de montar de la Fiesta de la Cerveza. ¡Pero recuerda que no son baratos!', `FemaleText_loc1`='가을 축제 상품권을 넉넉히 모으셨다면 가을 축제 광장에 있는 상품권 교환원이 "명예 양조장이" 손도장을 드릴 거예요.$b$b그 도장을 받아 오셔야 가을 축제 특선 길들인 산양을 사실 수 있지요. 하지만 만만한 가격이 아니라는 건 알아두셔야 해요!', `FemaleText_loc4`='如果你有足够多的美酒节奖券，美酒节营地的奖券兑换员就可以给你一个“荣誉酿酒商”的戳印。$b$b有了那个戳印，我就可以卖给你一头美酒节赛羊。不过我要提醒你，它们可并不便宜！', `FemaleText_loc5`='如果你得到了夠多的啤酒節獎品券，位於啤酒營地的貝爾碧·迅移會給你一個『榮譽釀酒者』手印。$b$b那個手印將可讓我賣給你一匹啤酒節騎乘用山羊。不過提醒你，它們可不便宜啊!', `FemaleText_loc7`='"Si consigues suficientes vales para la Fiesta de la Cerveza, el canjeador de vales, en el campamento de la Fiesta de la Cerveza, te dará un "Sello de "Cervecero Honorario"".$B$BEse sello me permitirá venderte un carnero de montar de la Fiesta de la Cerveza. ¡Pero recuerda que no son baratos!' WHERE `ID`=23462;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가을 축제 특선 산양을 구입하고 싶습니다.', `MaleText_loc4`='我想买一头美酒节赛羊。', `MaleText_loc5`='我想要買一匹啤酒節騎乘用山羊。', `MaleText_loc7`='Me gustaría comprar un carnero de montar de la Fiesta de la Cerveza.', `FemaleText_loc1`='가을 축제 특선 산양을 구입하고 싶어요.', `FemaleText_loc4`='我想买一头美酒节赛羊。', `FemaleText_loc5`='我想要買一匹啤酒節騎乘用山羊。', `FemaleText_loc7`='Me gustaría comprar un carnero de montar de la Fiesta de la Cerveza.' WHERE `ID`=23463;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가발양 기획사를 눈여겨 봐주십시오! 가을 축제 발리브루 양조사들입니다!', `MaleText_loc4`='来3-B展位看看！美酒节的麦酒！', `MaleText_loc5`='快來3-B娛樂看看!啤酒節的麥酒釀酒大師!', `MaleText_loc7`='¡No te pierdas la diversión 3C! ¡Cerveza de cerveceros Cebadiz!', `FemaleText_loc1`='가발양 기획사를 눈여겨 봐주세요! 가을 축제 발리브루 양조사들이에요!', `FemaleText_loc4`='来3-B展位看看！美酒节的麦酒！', `FemaleText_loc5`='快來3-B娛樂看看!啤酒節的麥酒釀酒大師!', `FemaleText_loc7`='¡No te pierdas la diversión 3C! ¡Cerveza de cerveceros Cebadiz!' WHERE `ID`=23464;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 발리브루가 발로 만들어도! 썬더브루보다는 나을 겁니다. 배부르지도 않고, 속 쓰리지도 않은 깔끔한 맛일 테니까요...', `MaleText_loc4`='麦酒是不会让你感到腹胀，也不会上头……的美酒。雷酒可不敢这么说。', `MaleText_loc5`='麥酒家的啤酒!不會讓你又撐又脹，也不會害死你...雷酒可不敢做這種保證!', `MaleText_loc7`='¡Cerveza Cebadiz! No te llenará, no te matará... Los Cebatruenos no pueden decir lo mismo.', `FemaleText_loc1`='우리 발리브루가 발로 만들어도! 썬더브루보다는 나을 거예요. 배부르지도 않고, 속 쓰리지도 않은 깔끔한 맛일 테니 말이죠...', `FemaleText_loc4`='麦酒是不会让你感到腹胀，也不会上头……的美酒。雷酒可不敢这么说。', `FemaleText_loc5`='麥酒家的啤酒!不會讓你又撐又脹，也不會害死你...雷酒可不敢做這種保證!', `FemaleText_loc7`='¡Cerveza Cebadiz! No te llenará, no te matará... Los Cebatruenos no pueden decir lo mismo.' WHERE `ID`=23465;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여러분 입맛에 딱 맞는 건 발리브루입니다! 가을 축제에서 발리브루 맥주 맛을 꼭 확인하십시오!', `MaleText_loc4`='麦酒是你的最佳选择！去美酒节尝尝麦酒吧！', `MaleText_loc5`='麥酒會好好招待你!快來看看啤酒節的麥酒!', `MaleText_loc7`='¡Cebadiz te tratará bien! ¡No te pierdas a los Cebadiz en la Fiesta de la Cerveza!', `FemaleText_loc1`='여러분 입맛에 딱 맞는 건 발리브루죠! 가을 축제에서 발리브루 맥주 맛을 꼭 확인하세요!', `FemaleText_loc4`='麦酒是你的最佳选择！去美酒节尝尝麦酒吧！', `FemaleText_loc5`='麥酒會好好招待你!快來看看啤酒節的麥酒!', `FemaleText_loc7`='¡Cebadiz te tratará bien! ¡No te pierdas a los Cebadiz en la Fiesta de la Cerveza!' WHERE `ID`=23466;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가을 축제에서 천둥벼락이 치길 바라신 분들! 천둥벼락같이 화끈한 맛, 썬더브루가 바로 제격입니다!', `MaleText_loc4`='美酒节上就要喝真正的酒，雷酒！', `MaleText_loc5`='啤酒節召來了閃電!這就是雷酒!', `MaleText_loc7`='¡La Fiesta de la Cerveza ha invocado a los truenos! ¡A los Cebatruenos!', `FemaleText_loc1`='가을 축제에서 천둥벼락이 치길 바라신 분들! 천둥벼락같이 화끈한 맛, 썬더브루가 바로 제격이죠!', `FemaleText_loc4`='美酒节上就要喝真正的酒，雷酒！', `FemaleText_loc5`='啤酒節召來了閃電!這就是雷酒!', `FemaleText_loc7`='¡La Fiesta de la Cerveza ha invocado a los truenos! ¡A los Cebatruenos!' WHERE `ID`=23467;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밋밋한 맥주 때문에 파티가 밋밋하십니까, 썬더브루가 해결해 드립니다! 가을 축제에 오셔서 썬더브루의 맛을 확인해 보십시오!', `MaleText_loc4`='你想尽情享受欢乐吗？雷酒就是你最好的选择！去美酒节试试吧！', `MaleText_loc5`='有時候你想要徹夜狂歡，雷酒幫你一把!快來啤酒節看看!', `MaleText_loc7`='¡Cuando quieras fiesta de verdad, Cebatruenos te ayudará! ¡No te los pierdas en la Fiesta de la Cerveza!', `FemaleText_loc1`='밋밋한 맥주 때문에 파티가 밋밋하신가요, 썬더브루가 해결해 드립니다! 가을 축제에 오셔서 썬더브루의 맛을 확인해 보세요!', `FemaleText_loc4`='你想尽情享受欢乐吗？雷酒就是你最好的选择！去美酒节试试吧！', `FemaleText_loc5`='有時候你想要徹夜狂歡，雷酒幫你一把!快來啤酒節看看!', `FemaleText_loc7`='¡Cuando quieras fiesta de verdad, Cebatruenos te ayudará! ¡No te los pierdas en la Fiesta de la Cerveza!' WHERE `ID`=23468;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신비한 마법을 맛보고 싶으십니까? 최고의 경지에 도달한 썬더브루 양조사들! 그들이 빚어낸 신비한 맛을 가을 축제에서 맛보십시오!', `MaleText_loc4`='你能感觉到这魔力吗？雷酒酿造师所释放的魔力！去美酒节看看吧！', `MaleText_loc5`='你有感受到魅力嗎?雷酒啤酒大師解放了!到啤酒節來看看他們吧!', `MaleText_loc7`='¿Sientes la magia? ¡Los maestros cerveceros de Cebatruenos andan sueltos! ¡No te los pierdas en la Fiesta de la Cerveza!', `FemaleText_loc1`='신비한 마법을 맛보고 싶으신가요? 최고의 경지에 도달한 썬더브루 양조사들! 그들이 빚어낸 신비한 맛을 가을 축제에서 맛보세요!', `FemaleText_loc4`='你能感觉到这魔力吗？雷酒酿造师所释放的魔力！去美酒节看看吧！', `FemaleText_loc5`='你有感受到魅力嗎?雷酒啤酒大師解放了!到啤酒節來看看他們吧!', `FemaleText_loc7`='¿Sientes la magia? ¡Los maestros cerveceros de Cebatruenos andan sueltos! ¡No te los pierdas en la Fiesta de la Cerveza!' WHERE `ID`=23469;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 삶은 여기서 끝이다, 침략자여!', `MaleText_loc4`='入侵者，你的生命结束了！', `MaleText_loc5`='入侵者，你的生命馬上就會結束了!', `MaleText_loc7`='¡Tu vida acaba ahora, invasor!', `FemaleText_loc1`='목숨을 거두어 주마, 침략자여!', `FemaleText_loc4`='入侵者，你的生命结束了！', `FemaleText_loc5`='入侵者，你的生命馬上就會結束了!', `FemaleText_loc7`='¡Tu vida acaba ahora, invasor!' WHERE `ID`=23470;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저승으로 보내주마, 미천한 것!', `MaleText_loc4`='让我送你的灵魂去极乐世界吧！', `MaleText_loc5`='小東西，我讓你靈魂去死後的世界吧!', `MaleText_loc7`='¡Enviaré tu alma al más allá, insignificante criatura!', `FemaleText_loc1`='저승으로 보내주마, 미천한 것!', `FemaleText_loc4`='让我送你的灵魂去极乐世界吧！', `FemaleText_loc5`='小東西，我讓你靈魂去死後的世界吧!', `FemaleText_loc7`='¡Enviaré tu alma al más allá, insignificante criatura!' WHERE `ID`=23471;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상대할 가치라도 있는지 보자!', `MaleText_loc4`='让我们瞧瞧你是不是个值得尊敬的对手！', `MaleText_loc5`='讓我們來試試你究竟配不配當我的對手!', `MaleText_loc7`='¡Veremos si eres un oponente digno!', `FemaleText_loc1`='상대할 가치라도 있는지 보자!', `FemaleText_loc4`='让我们瞧瞧你是不是个值得尊敬的对手！', `FemaleText_loc5`='讓我們來試試你究竟配不配當我的對手!', `FemaleText_loc7`='¡Veremos si eres un oponente digno!' WHERE `ID`=23472;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈을 죽일 수 있어서 정말 기쁘구나, $c!', `MaleText_loc4`='$c，杀死你对我来说真是莫大的乐趣！', `MaleText_loc5`='我極為樂意宰了你，$c!', `MaleText_loc7`='¡Disfrutaré mucho masacrándote, $c!', `FemaleText_loc1`='네놈을 죽일 수 있어서 정말 기쁘다, $c!', `FemaleText_loc4`='$c，杀死你对我来说真是莫大的乐趣！', `FemaleText_loc5`='我極為樂意宰了你，$c!', `FemaleText_loc7`='¡Disfrutaré mucho masacrándote, $c!' WHERE `ID`=23473;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 땅에 네 영혼이 쉴 곳 따윈 없다!', `MaleText_loc4`='你的灵魂将永无宁日！', `MaleText_loc5`='在這片大地，你的靈魂將永不安息!', `MaleText_loc7`='¡Tú espíritu no hallará la paz en estas tierras!', `FemaleText_loc1`='이 땅에 네 영혼이 쉴 곳 따윈 없다!', `FemaleText_loc4`='你的灵魂将永无宁日！', `FemaleText_loc5`='在這片大地，你的靈魂將永不安息!', `FemaleText_loc7`='¡Tú espíritu no hallará la paz en estas tierras!' WHERE `ID`=23474;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='차가운 암흑이 네 영혼을 기다린다!', `MaleText_loc4`='阴冷的黑暗等待着你的灵魂！', `MaleText_loc5`='冰冷的黑暗等待著你的靈魂!', `MaleText_loc7`='¡La fría oscuridad aguarda a tu alma!', `FemaleText_loc1`='차가운 암흑이 네 영혼을 기다린다!', `FemaleText_loc4`='阴冷的黑暗等待着你的灵魂！', `FemaleText_loc5`='冰冷的黑暗等待著你的靈魂!', `FemaleText_loc7`='¡La fría oscuridad aguarda a tu alma!' WHERE `ID`=23475;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 생명을 거두어 그분께 바치겠다!', `MaleText_loc4`='我会终结你的生命，让你陷入堕落的深渊！', `MaleText_loc5`='我會結束你的性命，並且讓你永遠聽命於他!', `MaleText_loc7`='¡Acabaré con tu vida y te someteré a su servicio!', `FemaleText_loc1`='네 생명을 거두어 그분께 바치겠다!', `FemaleText_loc4`='我会终结你的生命，让你陷入堕落的深渊！', `FemaleText_loc5`='我會結束你的性命，並且讓你永遠聽命於他!', `FemaleText_loc7`='¡Acabaré con tu vida y te someteré a su servicio!' WHERE `ID`=23476;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 해달라고 할 줄 몰랐는데!', `MaleText_loc4`='我以为你不会这么主动的！', `MaleText_loc5`='我以為你永遠不會問!', `MaleText_loc7`='¡Pensaba que no lo preguntarías nunca!' WHERE `ID`=23477;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 바로 개구리 스타일이지!', `MaleText_loc4`='这就是我说的“青蛙风格”！', `MaleText_loc5`='那就是我所謂的青蛙風格!', `MaleText_loc7`='¡Por eso te llamo ranita mía!' WHERE `ID`=23478;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='별로 오래 걸리진 않을 거야, 안 그래?', `MaleText_loc4`='不会太久吧？', `MaleText_loc5`='這不會花太久時間，對吧?', `MaleText_loc7`='Esto no tardará demasiado, ¿verdad?' WHERE `ID`=23479;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벌레는 먹으라고 주진 않을 거라 약속할게...', `MaleText_loc4`='我保证不会让你得疣……', `MaleText_loc5`='我答應你不會給你樹瘤...', `MaleText_loc7`='Prometo que no te saldrán verrugas...' WHERE `ID`=23480;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주변에서 모조를 별로 못 봐서 그래...', `MaleText_loc4`='周围跑来跑去的魔汁还不够多……', `MaleText_loc5`='魔精永遠都不夠分配...', `MaleText_loc7`='Nunca hay suficiente mojo...' WHERE `ID`=23481;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='들어 봐, $n, 내가 여기서 멀지 않은 조그만 늪을 하나 아는데 말이야...', `MaleText_loc4`='喂，$n，我知道有块沼泽离这里不远……', `MaleText_loc5`='聽著，$n，我知道離這不遠的地方有一個小沼澤...', `MaleText_loc7`='Escucha, $n, conozco una pequeña charca no muy lejos de aquí...' WHERE `ID`=23482;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 사는 수련잎으로 갈까? 아니면 내 잎?', `MaleText_loc4`='是你的莲花叶子还是我的？', `MaleText_loc5`='是你的蓮葉還是我的?', `MaleText_loc7`='¿Tu hoja de nenúfar o la mía?' WHERE `ID`=23483;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조그만 개구리가 된 것 같지?', `MaleText_loc4`='感觉有点像小青蛙，是吗？', `MaleText_loc5`='覺得像一隻小青蛙，是嗎?', `MaleText_loc7`='¿Te ha salido un poco rana?' WHERE `ID`=23484;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모조가 $n의 주머니 속으로 폴짝 뛰어듭니다!', `MaleText_loc4`='魔汁跳进了$n的口袋。', `MaleText_loc5`='莫巧跳進了$n的口袋!', `MaleText_loc7`='¡Mojo salta al bolsillo de $n!' WHERE `ID`=23485;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='젊은이, 자네에겐 더 보여줄 게 없군. 가서 지옥불 반도의 명예의 요새에서 레보스키를 찾아보라고. 나보다 훨씬 잘 가르쳐줄 게야!', `MaleText_loc4`='我没什么可以教你的了，孩子。去找荣耀堡的莱布斯基——就在地狱火半岛。他能教你更多东西！', `MaleText_loc5`='我已經沒有可以教你的東西了，孩子。去地獄火半島的榮譽堡找樂柏斯基吧。他可以教你更多的東西!', `MaleText_loc7`='Ya no puedo enseñarte nada más. Busca a Lebowski en el Bastión del Honor, en la Península del Fuego Infernal. ¡Él te enseñará más que yo!' WHERE `ID`=23486;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='젊은이에겐 더 보여줄 게 없네. 가서 지옥불 반도의 스랄마에서 제빅을 찾아보라고. 나보다 훨씬 잘 가르쳐줄 테니 말이야!', `MaleText_loc4`='我没什么可以教你的了，孩子。去找萨尔玛的塞比格——就在地狱火半岛。他能教你更多东西！', `MaleText_loc5`='我已經沒有可以教你的東西了，孩子。去地獄火半島的索爾瑪找澤比克吧。他可以教你更多的東西!', `MaleText_loc7`='Ya no puedo enseñarte nada más. Busca a Zebig en Thrallmar, en la Península del Fuego Infernal. ¡Él te enseñará más que yo!' WHERE `ID`=23487;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 맨주먹으로, 그리고 피와 눈물로 이 항만을 이룩했습니다, 친구여.$B$B절대로 발가드를 포기하지 않을 거라는 내 말을 믿어도 좋습니다.', `MaleText_loc4`='这里是我们辛辛苦苦用双手建设起来的！朋友，它凝聚着我们的血和泪。$B$B相信我，我们绝对不会放弃瓦加德。', `MaleText_loc5`='我們徒手把這個地方建好的!吾友，那真是血淚交織啊。$B$B相信我的話:我們從沒有放棄瓦爾加德堡的念頭。', `MaleText_loc7`='¡Construimos este lugar con nuestras manos desnudas! Sangre y lágrimas.$B$BCréeme cuando te digo esto: no tenemos intención de abandonar el control de Valgarde.' WHERE `ID`=23488;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='후퇴! 우리는 $3151W의 희생자를 내며 밀리고 있다! 피해가 막심하다! 물러나라!', `MaleText_loc4`='撤退！我们遭到了重创，还有$3151W个人员伤亡！我们不能承受这样的损失！撤退！！', `MaleText_loc5`='撤退!!我們輸了且已有$3151W的傷亡!無法繼續損失下去!撤退!!', `MaleText_loc7`='¡RETIRADA! ¡Nos han dado una paliza y tenemos $3151W bajas! ¡No podemos asumir tantas pérdidas! ¡RETROCEDED!' WHERE `ID`=23489;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 해냈다, 친구들! 험상궂은 주정뱅이 선술집으로 돌아가서 상처 입은 $3151W명 몫까지 마셔버리자!', `MaleText_loc4`='我们赢了！现在回到黑铁酒吧里去，让我们为那$3151W个受伤的伙伴干杯！', `MaleText_loc5`='我們做到了，小子!回到黑鐵酒吧去，我們來為了受傷的$3151W位乾杯吧!', `MaleText_loc7`='¡Lo logramos chicos! ¡Ahora volvamos a Tragapenas y bebamos por los $3151W que fueron heridos!' WHERE `ID`=23490;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐 친구, 여기 내가 가진 건 아주 극적인 발견이라고. 자네가 한 번도 본 적이 없는 거란 말이야! 게다가 판매도 싸게 한다니까!$b$b보다시피, 난 선술집에서 완벽한 인연을 찾으려고 돈을 써대는 데 질려버렸어. 그래서 이걸 만들었지. 고글 덕에 이제 "모두 다" 완벽해 보인다고. 이 귀여운 걸 쓰면 기분이 나빠질 리가 없다는 거지!$b$b어때? 하나 시험해 보겠나? 내 주머니 채우는 것도 좀 도와 줄 겸 말이야. 자네 얼굴에 반했으니, 까짓 거 할인도 해 주지!', `MaleText_loc4`='嘿，朋友，我拿来的这个东西可以说是一个伟大的成就，一件你从未看到过的东西！不过现在你可以买到它，可以非常便宜地买到它！$B$B你知道，我已经厌倦了花钱在酒馆里找寻完美的人。所以我做了这个东西……这副眼镜可以让每个人看上去都是那么完美无缺。你可别错过这种好东西！$B$B那么，你想试试吗？让我的口袋里多一点钱？既然你看上去那么完美，我会给你打折的！', `MaleText_loc5`='嘿朋友，我手上的東西是個大發現，從來沒有見過這樣的東西喔!現在正出售中，便宜的呢!$b$b瞧，我已經懶得在酒館中花錢尋找完美的人。所以我做了這些護目鏡，而現在每個人看起來都超完美的。我是指你就不會搞錯那些自大的傻小子啦!$b$b那麼，你想要試試看這些東西，幫我的荷包賺點錢嗎?因為你看起來這麼棒，我還會給你折扣喔!', `MaleText_loc7`='¡Amigo, lo que tengo aquí es una novedad sin precedentes! ¡Y está en venta a muy buen precio!$B$BVerás, estaba harto de gastar dinero en las tabernas buscando a mi media naranja, así que hice estas gafas y ahora TODO EL MUNDO es la viva imagen de la perfección. ¡No hay posibilidad de error!$B$BSi quieres probarlas, tendrás que acolchar mis bolsillos. ¡Ya que tienes tan buen aspecto te haré un descuento!', `FemaleText_loc1`='이봐 친구, 여기 내가 가진 건 아주 극적인 발견이라고. 자네가 한 번도 본 적이 없는 거란 말이야! 게다가 판매도 싸게 한다니까!$b$b보다시피, 난 선술집에서 완벽한 인연을 찾으려고 돈을 써대는 데 질려버렸어. 그래서 이걸 만들었지. 고글 덕에 이제 "모두 다" 완벽해 보인다고. 이 귀여운 걸 쓰면 기분이 나빠질 리가 없다는 거지!$b$b어때? 하나 시험해 보겠나? 내 주머니 채우는 것도 좀 도와 줄 겸 말이야. 자네 얼굴에 반했으니, 까짓 거 할인도 해 주지!', `FemaleText_loc4`='嘿，朋友，我拿来的这个东西可以说是一个伟大的成就，一件你从未看到过的东西！不过现在你可以买到它，可以非常便宜地买到它！$B$B你知道，我已经厌倦了花钱在酒馆里找寻完美的人。所以我做了这个东西……这副眼镜可以让每个人看上去都是那么完美无缺。你可别错过这种好东西！$B$B那么，你想试试吗？让我的口袋里多一点钱？既然你看上去那么完美，我会给你打折的！', `FemaleText_loc5`='嘿朋友，我手上的東西是個大發現，從來沒有見過這樣的東西喔!現在正出售中，便宜的呢!$b$b瞧，我已經懶得在酒館中花錢尋找完美的人。所以我做了這些護目鏡，而現在每個人看起來都超完美的。我是指你就不會搞錯那些自大的傻小子啦!$b$b那麼，你想要試試看這些東西，幫我的荷包賺點錢嗎?因為你看起來這麼棒，我還會給你折扣喔!', `FemaleText_loc7`='¡Amigo, lo que tengo aquí es una novedad sin precedentes! ¡Y está en venta a muy buen precio!$B$BVerás, estaba harto de gastar dinero en las tabernas buscando a mi media naranja, así que hice estas gafas y ahora TODO EL MUNDO es la viva imagen de la perfección. ¡No hay posibilidad de error!$B$BSi quieres probarlas, tendrás que acolchar mis bolsillos. ¡Ya que tienes tan buen aspecto te haré un descuento!' WHERE `ID`=23491;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 세상의 모든 걸 모으고 있지, 귀염둥이! 맥주통 수호대 표시에 대해 물었나? 그건 자기가 싸움의 기술을 안다는 걸 보여 주지.$b$b검은무쇠 드워프 녀석을 때려눕힐 때마다 표시가 생긴다고. 표시 하나마다 상품권을 주지.$b$b아흑, 이 상품권을 잃는 건 가슴 아프단 말이야... 그건 다시 자기를 만나서, 또 떠나는 걸 지켜봐야 한단 소리니 말이야...', `MaleText_loc4`='我在寻找各种各样的东西！不过你所说的那些印记，酒桶保护者的印记？那些东西可以证明你知道如何应付战斗。$B$B每当你打倒一个黑铁矮人，你就会得到一个印记。我会用一张奖券来交换你所得到的印记。$B$B给出这些奖券让我感到很痛苦，但它同样意味着我能再次看到你，不过还得看到你再次离开……', `MaleText_loc5`='寶貝我在尋找各式各樣的東西!不過你提到的那些印記，是酒桶保管者印記嗎?那些印記告訴我你懂得如何在戰鬥中自處。$b$b每次你打倒一個黑鐵矮人，你就會得到一個印記。你每得到一個印記，我就會給你一張獎品券。$b$b把這些獎品券發出去讓我覺得很痛苦，不過這也代表我會再度見到你，並再度目送你離去...', `MaleText_loc7`='Busco un poco de todo, pero esas marcas de las que hablas, las marcas de protector de barriles me demuestran que sabes pelear.$B$BCada vez que vences a un enano Hierro Negro consigues una marca. Por cada marca que consigas yo te daré un vale.$B$BMe duele entregar estos vales, pero también significa que te volveré a ver y te volveré a ver partir...', `FemaleText_loc1`='전 모든 잡동사니를 다 찾고 있죠! 하지만, 맥주통 수호대 표시에 대해 물으셨죠? 그건 당신이 싸움의 기술을 안다는 걸 보여 주지요.$b$b검은무쇠 드워프 녀석을 때려눕힐 때마다 표시가 생겨요. 표시 하나마다 상품권을 한 장씩 드리지요.$b$b이 상품권을 잃는 건 너무나 가슴 아파요... 왜냐하면 그건 다시 당신을 만나서, 또 떠나는 걸 지켜봐야 한단 소리니 말이죠...', `FemaleText_loc4`='我在寻找各种各样的东西！不过你所说的那些印记，酒桶保护者的印记？那些东西可以证明你知道如何应付战斗。$B$B每当你打倒一个黑铁矮人，你就会得到一个印记。我会用一张奖券来交换你所得到的印记。$B$B给出这些奖券让我感到很痛苦，但它同样意味着我能再次看到你，不过还得看到你再次离开……', `FemaleText_loc5`='寶貝我在尋找各式各樣的東西!不過你提到的那些印記，是酒桶保管者印記嗎?那些印記告訴我你懂得如何在戰鬥中自處。$b$b每次你打倒一個黑鐵矮人，你就會得到一個印記。你每得到一個印記，我就會給你一張獎品券。$b$b把這些獎品券發出去讓我覺得很痛苦，不過這也代表我會再度見到你，並再度目送你離去...', `FemaleText_loc7`='¡Busco todo tipo de cosas, cielo! Pero esas marcas de las que hablas, las marcas de protector de barriles me demuestran que sabes pelear.$B$BCada vez que vences a un enano Hierro Negro consigues una marca. Por cada marca que consigas yo te daré un vale.$B$BMe duele entregar estos vales, pero también significa que te volveré a ver y te volveré a ver partir...' WHERE `ID`=23492;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지나가면서 내 옆에 멈추고 싶어 했던 거 다 안다고. 뭘 해 드릴까, 귀여운 친구?', `MaleText_loc4`='我看到你在街对面闲逛，就满心希望你可以到这边来。那么，甜心，有什么需要我为你效劳的？', `MaleText_loc5`='我看著你走過並希望你會停下來。那麼甜心，我可以幫你什麼呢?', `MaleText_loc7`='Te vi por el camino y esperaba que te pasaras por aquí. ¿Qué puedo hacer por ti, cielo?' WHERE `ID`=23493;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맥주통 수호대 표시를 교환하고 싶습니다...', `MaleText_loc4`='我要兑换酒桶保卫者的戳记……', `MaleText_loc5`='我有酒桶保管者印記可以兌換...', `MaleText_loc7`='Tengo marcas de protector de barril para canjear...', `FemaleText_loc1`='맥주통 수호대 표시를 교환하고 싶어요...', `FemaleText_loc4`='我要兑换酒桶保卫者的戳记……', `FemaleText_loc5`='我有酒桶保管者印記可以兌換...', `FemaleText_loc7`='Tengo marcas de protector de barril para canjear...' WHERE `ID`=23494;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 맥주통 수호대 표시를 찾는단 얘기를 들었습니다. 그게 뭡니까?', `MaleText_loc4`='我听说你正在寻找酒桶保卫者的印记。那是什么？', `MaleText_loc5`='我聽說你在尋找酒桶保管者印記。那是什麼啊?', `MaleText_loc7`='He oído que buscas marcas de protector de barriles. ¿Qué son?', `FemaleText_loc1`='당신이 맥주통 수호대 표시를 찾는단 얘기를 들었어요. 그게 뭐죠?', `FemaleText_loc4`='我听说你正在寻找酒桶保卫者的印记。那是什么？', `FemaleText_loc5`='我聽說你在尋找酒桶保管者印記。那是什麼啊?', `FemaleText_loc7`='He oído que buscas marcas de protector de barriles. ¿Qué son?' WHERE `ID`=23495;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 이상한 고글은 대체 뭡니까?', `MaleText_loc4`='你的疯狂眼镜有什么用？', `MaleText_loc5`='你的護目鏡怎麼那麼古怪?', `MaleText_loc7`='¿Qué son esas gafas tan raras?', `FemaleText_loc1`='그 이상한 고글은 대체 뭐죠?', `FemaleText_loc4`='你的疯狂眼镜有什么用？', `FemaleText_loc5`='你的護目鏡怎麼那麼古怪?', `FemaleText_loc7`='¿Qué son esas gafas tan raras?' WHERE `ID`=23496;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 이봐, 귀염둥이! 아휴, 예뻐 죽겠어!', `MaleText_loc4`='嗨，美女！帅哥！', `MaleText_loc5`='嘿，嘿甜心!長得很正喔!', `MaleText_loc7`='¡Hey, cielito! ¡Estás para comerte!' WHERE `ID`=23497;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기요! 끝내주는 언니들, 여기 좀 보세요!', `MaleText_loc4`='嗨！美女，过来！', `MaleText_loc5`='嘿! 小可愛，這裡啊!', `MaleText_loc7`='¡Hey! ¡Aquí, pedacito de cielo!' WHERE `ID`=23498;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와! 한 덩치하는 누님! 제 상대가 되시려나 어쩌려나?', `MaleText_loc4`='哟！大家伙！你觉得你能对付得了我吗？', `MaleText_loc5`='唷!大小姐!你想你有大到可以解決我嗎?', `MaleText_loc7`='¡Hola nena! ¿Crees que tienes lo que hace falta para manejarme?' WHERE `ID`=23499;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 섹시한 당신! 이봐, $c! 돈 좋아해? 난 부자라고! 이리 와서 금화 구경할래?', `MaleText_loc4`='嗨，强壮的家伙！嗨，$c！你喜欢钱吗？我很有钱！到这来看看我的金币怎么样？', `MaleText_loc5`='嘿強壯的傢伙!嘿，$c!你喜歡錢嗎?我有喔!你何不過來這裡看看我的金幣?', `MaleText_loc7`='¡Hey nena! ¡Hey, $c! ¿Te gusta el dinero? ¡Yo estoy forrado! ¿Por qué no vienes a ver mis monedas de oro?' WHERE `ID`=23500;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헤이, 거기! 그래, 자기! 몸매가 정말 예술이네!', `MaleText_loc4`='嗨，嗨！亲爱的，你的身材真不错！', `MaleText_loc5`='嘿，嘿! 寶貝你的身材真好!', `MaleText_loc7`='¡Hey, hey! ¡Tienes un tipo perfecto!' WHERE `ID`=23501;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우와! 다시 지나가 봐, 멋진 아가씨!', `MaleText_loc4`='哇！美女！', `MaleText_loc5`='哇喔! 姑娘再走過一次嘛!', `MaleText_loc7`='¡Hey! ¡Vuelve a pasar por aquí nena!' WHERE `ID`=23502;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='현장감독이 경비병을 더 데려오겠다고 하지 않았나? 대체 어디 있는 거지?', `MaleText_loc4`='工头不是说他要带些卫兵过来吗？他们在哪儿呢？', `MaleText_loc5`='工頭不是說他要帶一些守衛來嗎?人哩?', `MaleText_loc7`='¿No dijo el capataz que iba a traer algunos guardias? ¿Dónde están?', `FemaleText_loc1`='현장감독이 경비병을 더 데려오겠다고 하지 않았어? 대체 어딨는 거야?', `FemaleText_loc4`='工头不是说他要带些卫兵过来吗？他们在哪儿呢？', `FemaleText_loc5`='工頭不是說他要帶一些守衛來嗎?人哩?', `FemaleText_loc7`='¿No dijo el capataz que iba a traer algunos guardias? ¿Dónde están?' WHERE `ID`=23503;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='광산을 더 확장하지 않으면 광석을 필요한 만큼 채취할 수 없지. 아담스 경비대장이 우리 가죽을 벗기려 들 거야!', `MaleText_loc4`='如果我们不继续开凿矿井，从哪儿弄来所需的矿石呢。没有矿石的话，亚当斯上尉会剥了我们的皮！', `MaleText_loc5`='如果我們不擴展礦業，我們就沒辦法滿足我們所需要的礦石了。亞當斯隊長會把我們的皮給剝了!', `MaleText_loc7`='Si no expandimos la mina, no conseguiremos todas las menas que necesitamos. ¡El capitán Adams se pondrá furioso!', `FemaleText_loc1`='광산을 더 확장하지 않으면 광석을 필요한 만큼 채취할 수 없지. 아담스 경비대장이 우리 가죽을 벗기려 들 거야!', `FemaleText_loc4`='如果我们不继续开凿矿井，从哪儿弄来所需的矿石呢。没有矿石的话，亚当上尉会剥了我们的皮！', `FemaleText_loc5`='如果我們不擴展礦業，我們就沒辦法滿足我們所需要的礦石了。亞當斯隊長會把我們的皮給剝了!', `FemaleText_loc7`='Si no expandimos la mina, no conseguiremos todas las menas que necesitamos. ¡El capitán Adams se pondrá furioso!' WHERE `ID`=23504;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='짝뿔과 맞서겠단 말입니까? 당신 정말 간이 크군요.', `MaleText_loc4`='你打算向裂角挑战？我说，你可真勇敢。', `MaleText_loc5`='要你去對付碎角?你真勇敢，我把東西拿給你。', `MaleText_loc7`='¿Vas a enfrentarte a Modorro? Reconozco que eres valiente.', `FemaleText_loc1`='짝뿔을 처치하시겠다고요? 당신 정말 대담하시군요.', `FemaleText_loc4`='你打算向裂角挑战？我说，你可真勇敢。', `FemaleText_loc5`='要你去對付碎角?你真勇敢，我把東西拿給你。', `FemaleText_loc7`='¿Vas a enfrentarte a Modorro? Reconozco que eres valiente.' WHERE `ID`=23505;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈에게 지옥 구경을 시켜 주시오!', `MaleText_loc4`='替我们好好地教训他！', `MaleText_loc5`='為了我們，讓他痛不欲生!', `MaleText_loc7`='¡Haz que lo pasen mal de nuestra parte!', `FemaleText_loc1`='놈을 끝장내 버리세요!', `FemaleText_loc4`='替我们好好地教训他！', `FemaleText_loc5`='為了我們，讓他痛不欲生!', `FemaleText_loc7`='¡Haz que lo pasen mal de nuestra parte!' WHERE `ID`=23506;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보시다시피 지금은 별로 바쁘지 않습니다. 당신 관 정도야 짜 드릴 수 있죠...', `MaleText_loc4`='你瞧，我们眼下还不算太忙。不如帮你做个棺材……', `MaleText_loc5`='你知道，我們現在一點都不忙。我們可以動手為你打造一具棺木...', `MaleText_loc7`='Ya sabes, ahora no estamos ocupados. Podríamos comenzar a construirte un ataúd...', `FemaleText_loc1`='아시겠지만, 지금은 조금 한가하거든요. 무덤을 파 드릴 시간 정도야 있어요...', `FemaleText_loc4`='你瞧，我们眼下还不算太忙。不如帮你做个棺材……', `FemaleText_loc5`='你知道，我們現在一點都不忙。我們可以動手為你打造一具棺木...', `FemaleText_loc7`='Ya sabes, ahora no estamos ocupados. Podríamos comenzar a construirte un ataúd...' WHERE `ID`=23507;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보통 개는 이제 내 주위에 얼씬거리지 않는다오. 그걸 알았을 때는 얼마나 비참했는지... 난 개를 정말 사랑했소.$B$B지금은 역병사냥개들이 그 자리를 대신한다오. 보기에 썩... 좋은 녀석들은 아니지만 그건 나도 마찬가지 아니겠소!', `MaleText_loc4`='正常的狗根本不敢靠近我。当我发现这点时深受打击……我其实是很喜欢动物的。$B$B天灾犬是不错的替代品。当然，它们的模样……并不好看。但你知道吗，我的相貌也好看不到哪儿去！', `MaleText_loc5`='這些日子，普通的狗根本不會靠近我。當我發現我過去原來很喜歡野獸時...我十分驚訝。$B$B瘟疫獵犬倒是個不錯的替代品，雖然牠們...其貌不揚，但是話說回來，我也不怎樣好看啊!', `MaleText_loc7`='Actualmente, los perros normales ni se me acercan. Me quedé hecho polvo cuando lo descubrí... Me encantaban las bestias.$B$BPero, de todos modos, los canes de peste son buenos sustitutos. No son tan... bonitos. Pero bueno... ¡yo tampoco!' WHERE `ID`=23508;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거, 곱게 끝나지는 않겠군.', `MaleText_loc4`='情况不妙啊。', `MaleText_loc5`='這一切將難以善了。', `MaleText_loc7`='Esto no va a acabar bien...', `FemaleText_loc1`='어떻게 될지 두려운데.', `FemaleText_loc4`='情况不妙啊。', `FemaleText_loc5`='這一切將難以善了。', `FemaleText_loc7`='Esto no va a acabar bien...' WHERE `ID`=23509;
