UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아제로스에서 이보다 더 나은 맥주는 찾지 못할 걸세.', `MaleText_loc4`='你在艾泽拉斯找不到更好的酒了。', `MaleText_loc5`='你在艾澤拉斯找不到更好的啤酒啦。', `MaleText_loc7`='No encontrarás una cerveza mejor en todo Azeroth.' WHERE `ID`=23511;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐요, 친구, 업계 최고의 맥주를 마실 준비가 됐나요?', `MaleText_loc4`='嗨，朋友，你想试试全世界最好的酒吗？', `MaleText_loc5`='老兄，你想試試諸國最棒的啤酒嗎?', `MaleText_loc7`='¿Te sientes en condiciones de probar la mejor cerveza de todos los reinos?' WHERE `ID`=23512;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기, 키 큰 자네 말이야... 알딸딸한 기분에 젖고 싶은 거 같은데? 드론의 양조장이 도와 주지!', `MaleText_loc4`='嗨，就是你。那个高个子……想来点刺激的吗?  德罗恩的酿酒厂可以帮助你！', `MaleText_loc5`='你，高個子的那個...想在胸膛上增添一點毛髮嗎?德羅恩釀酒廠能夠幫助你!', `MaleText_loc7`='Oye... el alto... ¿Quieres que te salga pelo en el pecho? ¡Prueba la cerveza de la Destilería de Drohn!', `FemaleText_loc1`='거기, 키 큰 당신 말이에요... 알딸딸한 기분에 젖고 싶으신 거 같은데요? 드론의 양조장이 도와 드리죠!', `FemaleText_loc4`='嗨，就是你。那个高个子……想来点刺激的吗?  德罗恩的酿酒厂可以帮助你！', `FemaleText_loc5`='你，高個子的那個...想在胸膛上增添一點毛髮嗎?德羅恩釀酒廠能夠幫助你!', `FemaleText_loc7`='Oye... el alto... ¿Quieres que te salga pelo en el pecho? ¡Prueba la cerveza de la Destilería de Drohn!' WHERE `ID`=23513;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드론의 술은 전설이 됐지! 이리 와서 전설을 맛보라고!', `MaleText_loc4`='德罗恩的美酒简直是个传说！过来尝尝传说中的美酒吧！', `MaleText_loc5`='德羅恩啤酒是用傳奇素材所釀!快來嚐嚐傳奇的味道!', `MaleText_loc7`='¡De la cerveza de Drohn están hechas las leyendas! ¡Ven a probar la leyenda!', `FemaleText_loc1`='드론의 술은 전설이 됐다고요! 이리 와서 전설을 맛보세요!', `FemaleText_loc4`='德罗恩的美酒简直是个传说！过来尝尝传说中的美酒吧！', `FemaleText_loc5`='德羅恩啤酒是用傳奇素材所釀!快來嚐嚐傳奇的味道!', `FemaleText_loc7`='¡De la cerveza de Drohn están hechas las leyendas! ¡Ven a probar la leyenda!' WHERE `ID`=23514;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돈 주고 살 수 있는 거 중에 드론의 양조장에서 만든 맥주가 최고지! "월간 고블린 맥주"에서 "끝내주는 맥주"로 뽑힌 거라고!', `MaleText_loc4`='德罗恩的酿酒厂里有着你能用钱买到的最好的酒！他们曾被《地精美酒月刊》评为“世上最好的佳酿”！', `MaleText_loc5`='德羅恩釀酒廠出產市面上最好的啤酒!他們是由哥布林每月啤酒所票選出來的「卓越啤酒」!', `MaleText_loc7`='¡La Destilería de Drohn tiene la mejor cerveza que el dinero puede comprar! ¡Fueron elegidos "cerveza excepcional" por el suplemento cervecero goblin!', `FemaleText_loc1`='돈 주고 살 수 있는 거 중에 드론의 양조장에서 만든 맥주가 최고라고요! "월간 고블린 맥주"에서 "끝내주는 맥주"로 뽑혔는걸요!', `FemaleText_loc4`='德罗恩的酿酒厂里有着你能用钱买到的最好的酒！他们曾被《地精美酒月刊》评为“世上最好的佳酿”！', `FemaleText_loc5`='德羅恩釀酒廠出產市面上最好的啤酒!他們是由哥布林每月啤酒所票選出來的「卓越啤酒」!', `FemaleText_loc7`='"¡La Destilería de Drohn tiene la mejor cerveza que el dinero puede comprar! ¡Fueron elegidos "cerveza excepcional" por el suplemento cervecero goblin!' WHERE `ID`=23515;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드를 위해 건배! 자네도 호드를 위해 마시나? 드론의 양조장에서 보여달라고!', `MaleText_loc4`='我们为部落干杯！你也是为部落干杯吗？来德罗恩的酿酒厂让我们看看！', `MaleText_loc5`='我們為了部落乾杯!你會為了部落乾杯嗎?到德羅恩釀酒廠向我們證明!', `MaleText_loc7`='¡Bebemos por la Horda! ¿Tú bebes por la Horda? ¡Ven a demostrárnoslo al puesto de la Destilería de Drohn!', `FemaleText_loc1`='호드를 위해 건배! 당신도 호드를 위해 마시나요? 드론의 양조장에서 보여주세요!', `FemaleText_loc4`='我们为部落干杯！你也是为部落干杯吗？来德罗恩的酿酒厂让我们看看！', `FemaleText_loc5`='我們為了部落乾杯!你會為了部落乾杯嗎?到德羅恩釀酒廠向我們證明!', `FemaleText_loc7`='¡Bebemos por la Horda! ¿Tú bebes por la Horda? ¡Ven a demostrárnoslo al puesto de la Destilería de Drohn!' WHERE `ID`=23516;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐 자네! 촬리의 부두 양조장에서 만든 맥주를 마신다고 죽지는 않는다고! 물론 그럴 만한 것도 있지만 말이야...', `MaleText_loc4`='嗨！塔卡里的巫毒酒不会让你喝了就死的！但他们也有一种酒可以让你喝了就死……', `MaleText_loc5`='就是你!提洽里的巫毒釀酒者弄到了一杯不會害死你的啤酒!不過他們也拿到了一杯或許會...', `MaleText_loc7`='¡Oye tú! ¡La Cervecería vudú de T''chali tiene una cerveza que no te matará! Pero también tienen otra que podría...', `FemaleText_loc1`='이봐요 당신! 촬리의 부두 양조장에서 만든 맥주를 마신다고 당신이 죽는 건 아니라고요! 물론 그럴 만한 것도 있지만 말이에요...', `FemaleText_loc4`='嗨！塔卡里的巫毒酒不会让你喝了就死的！但他们也有一种酒可以让你喝了就死……', `FemaleText_loc5`='就是你!提洽里的巫毒釀酒者弄到了一杯不會害死你的啤酒!不過他們也拿到了一杯或許會...', `FemaleText_loc7`='¡Oye tú! ¡La Cervecería vudú de T''chali tiene una cerveza que no te matará! Pero también tienen otra que podría...' WHERE `ID`=23517;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='인생을 최대한 즐기고 싶다면 촬리의 부두 맥주를 마셔야지!', `MaleText_loc4`='如果你想充分享受生活，你就必须尝尝塔卡里的巫毒酒！', `MaleText_loc5`='如果你想要圓滿的生活，你就會需要提洽里巫毒啤酒!', `MaleText_loc7`='¡Si quieres vivir la vida al máximo, tienes que probar la cerveza vudú de T''chali!', `FemaleText_loc1`='인생을 최대한 즐기고 싶다면 촬리의 부두 맥주를 마셔야지요!', `FemaleText_loc4`='如果你想充分享受生活，你就必须尝尝塔卡里的巫毒酒！', `FemaleText_loc5`='如果你想要圓滿的生活，你就會需要提洽里巫毒啤酒!', `FemaleText_loc7`='¡Si quieres vivir la vida al máximo, tienes que probar la cerveza vudú de T''chali!' WHERE `ID`=23518;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='촬리의 부두 맥주보다 나은 건 못 찾을걸! "주간 고블린 맥주"에서 "최고의 맥주"로 뽑힌 상품이라고!', `MaleText_loc4`='塔卡里的巫毒酒是你所能找到的最好的酒！他们曾被《地精美酒周报》评为“世上最好的佳酿”！', `MaleText_loc5`='提洽里的巫毒酒廠有你能找到最好的啤酒!他們是由哥布林每週啤酒所票選出來的「最佳啤酒」!', `MaleText_loc7`='¡La Cervecería vudú de T''chali tiene la mejor cerveza que puedas encontrar! ¡Fueron elegidos "mejor cerveza" por el semanal cervecero goblin!', `FemaleText_loc1`='촬리의 부두 맥주보다 나은 건 못 찾을걸요! "주간 고블린 맥주"에서 "최고의 맥주"로 뽑힌 상품이라고요!', `FemaleText_loc4`='塔卡里的巫毒酒是你所能找到的最好的酒！他们曾被《地精美酒周报》评为“世上最好的佳酿”！', `FemaleText_loc5`='提洽里的巫毒酒廠有你能找到最好的啤酒!他們是由哥布林每週啤酒所票選出來的「最佳啤酒」!', `FemaleText_loc7`='¡La Cervecería vudú de T''chali tiene la mejor cerveza que puedas encontrar! ¡Fueron elegidos "mejor cerveza" por el semanal cervecero goblin!' WHERE `ID`=23519;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제대로 놀 줄 안다면 드론의 양조장을 선택하셔야지요! 가을 축제에서 확인해 보십시오!', `MaleText_loc4`='德罗恩的酿酒厂可以让你尽享欢乐！来美酒节尝尝吧！', `MaleText_loc5`='德羅恩釀酒廠知道如何好好享樂!到啤酒節來看看他們吧!', `MaleText_loc7`='¡La Destilería de Drohn sí que sabe correrse una juerga! ¡No te los pierdas en la Fiesta de la Cerveza!', `FemaleText_loc1`='제대로 놀 줄 안다면 드론의 양조장을 선택하셔야지요! 가을 축제에서 확인하시죠!', `FemaleText_loc4`='德罗恩的酿酒厂可以让你尽享欢乐！来美酒节尝尝吧！', `FemaleText_loc5`='德羅恩釀酒廠知道如何好好享樂!到啤酒節來看看他們吧!', `FemaleText_loc7`='¡La Destilería de Drohn sí que sabe correrse una juerga! ¡No te los pierdas en la Fiesta de la Cerveza!' WHERE `ID`=23520;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진짜 좋은 술이 뭔지 제대로 아는 오크들과 가을 축제를 즐겨봅시다! 가을 축제에서 드론의 양주장에 꼭 들러 주십시오!', `MaleText_loc4`='同知道什么是真正美酒的兽人一起庆祝美酒节吧！来美酒节尝尝德罗恩的佳酿！', `MaleText_loc5`='與知道什麼才是真正好喝的獸人一起慶祝啤酒節吧!到啤酒節來看看德羅恩釀酒廠!', `MaleText_loc7`='¡Celebra la Fiesta de la Cerveza con los orcos que saben distinguir una buena bebida! ¡No te pierdas la Destilería de Drohn!', `FemaleText_loc1`='진짜 좋은 술이 뭔지 제대로 아는 오크들과 가을 축제를 즐겨보아요! 가을 축제에 꼭 들러 주세요!', `FemaleText_loc4`='同知道什么是真正美酒的兽人一起庆祝美酒节吧！来美酒节尝尝德罗恩的佳酿！', `FemaleText_loc5`='與知道什麼才是真正好喝的獸人一起慶祝啤酒節吧!到啤酒節來看看德羅恩釀酒廠!', `FemaleText_loc7`='¡Celebra la Fiesta de la Cerveza con los orcos que saben distinguir una buena bebida! ¡No te pierdas la Destilería de Drohn!' WHERE `ID`=23521;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오크가 한 방 날릴 줄 안다고 생각하셨다면, 오크 맥주도 드셔 보십시오. 더 강력한 한 방을 날려주니까요! 드론의 양조장에 오셔서 확인하십시오, 가을 축제에서만 만나실 수 있습니다!', `MaleText_loc4`='如果你以为兽人给你脑袋上来一下就已经够狠了，就去体验一下更狠的吧！去德罗恩的酿酒厂试试看，只有美酒节才有哦！', `MaleText_loc5`='如果你覺得獸人的勁道很大，來試試他們的酒，後勁更大!到德羅恩釀酒廠來親眼看看，只有在啤酒節喔!', `MaleText_loc7`='Si crees que los orcos pegan fuerte, prueba su cerveza. ¡Pega aún más! ¡Compruébalo en el puesto de la Destilería de Drohn de la Fiesta de la Cerveza!', `FemaleText_loc1`='오크 남자처럼 화끈하게 한 방 날려주는 오크 맥주를 드셔 보세요. 드론의 양조장에 오시면 확인하실 수 있답니다. 이번 가을 축제가 화끈한 오크 맥주를 만날 수 있는 절호의 기회랍니다!', `FemaleText_loc4`='如果你以为兽人给你脑袋上来一下就已经够狠了，就去体验一下更狠的吧！去德罗恩的酿酒厂试试看，只有美酒节才有哦！', `FemaleText_loc5`='如果你覺得獸人的勁道很大，來試試他們的酒，後勁更大!到德羅恩釀酒廠來親眼看看，只有在啤酒節喔!', `FemaleText_loc7`='Si crees que los orcos pegan fuerte, prueba su cerveza. ¡Pega aún más! ¡Compruébalo en el puesto de la Destilería de Drohn de la Fiesta de la Cerveza!' WHERE `ID`=23522;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드론의 양조장으로 오셔서 형제자매 여러분과 함께 호드를 위하여 건배하십시오!', `MaleText_loc4`='去德罗恩的酿酒厂加入你的兄弟姐妹们，一起为部落干杯！', `MaleText_loc5`='偕同你的兄弟姐妹們到德羅恩釀酒廠來為了部落暢飲吧!', `MaleText_loc7`='¡Únete a tus hermanos y hermanas en el puesto de la Destilería de Drohn y bebe por la Horda!', `FemaleText_loc1`='드론의 양조장으로 오셔서 형제자매 여러분과 함께 호드를 위하여 건배하세요!', `FemaleText_loc4`='去德罗恩的酿酒厂加入你的兄弟姐妹们，一起为部落干杯！', `FemaleText_loc5`='偕同你的兄弟姐妹們到德羅恩釀酒廠來為了部落暢飲吧!', `FemaleText_loc7`='¡Únete a tus hermanos y hermanas en el puesto de la Destilería de Drohn y bebe por la Horda!' WHERE `ID`=23523;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말로 오크나 오우거가 만든 맥주를 드시겠다는 겁니까? 가을 축제에서 촬리의 부두 양조장을 선택하신다면 후회하지 않으실 겁니다!', `MaleText_loc4`='你真的想喝兽人或食人魔酿的酒吗？你最好去美酒节尝尝塔卡里的巫毒酒！', `MaleText_loc5`='你真的會喝來自獸人及巨魔那的酒嗎?現在你有更好的選擇，到啤酒節的提洽里的巫毒酒廠看看吧!', `MaleText_loc7`='¿Realmente beberías cerveza de los orcos o de los ogros? ¡Si quieres probar algo bueno de verdad visita el puesto de la Cervecería vudú de T''chali en la Fiesta de la Cerveza!', `FemaleText_loc1`='정말로 오크나 오우거가 만든 맥주를 드시겠다는 건가요? 가을 축제에서 촬리의 부두 양조장을 선택하신다면 후회하지 않으실 거예요!', `FemaleText_loc4`='你真的想喝兽人或食人魔酿的酒吗？你最好去美酒节尝尝塔卡里的巫毒酒！', `FemaleText_loc5`='你真的會喝來自獸人及巨魔那的酒嗎?現在你有更好的選擇，到啤酒節的提洽里的巫毒酒廠看看吧!', `FemaleText_loc7`='¿Realmente beberías cerveza de los orcos o de los ogros? ¡Si quieres probar algo bueno de verdad visita el puesto de la Cervecería vudú de T''chali en la Fiesta de la Cerveza!' WHERE `ID`=23524;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이국적인 맛의 맥주를 즐기시는 분이라면, 가을 축제에서는 촬리의 부두 양조장 맥주가 제격입니다!', `MaleText_loc4`='如果你想喝些异国风味的酒，美酒节上有塔卡里的巫毒酒！', `MaleText_loc5`='如果你可以來點特別的酒，啤酒節的提洽里的巫毒酒廠正合你所需!', `MaleText_loc7`='¡Si te apetece una cerveza exótica, en la Cervecería vudú de T''chali que hay en la Fiesta de la Cerveza tienen lo que necesitas!', `FemaleText_loc1`='이국적인 맛의 맥주를 즐기시는 분이라면, 가을 축제에서는 촬리의 부두 양조장에서 제대로 즐길 수 있지요!', `FemaleText_loc4`='如果你想喝些异国风味的酒，美酒节上有塔卡里的巫毒酒！', `FemaleText_loc5`='如果你可以來點特別的酒，啤酒節的提洽里的巫毒酒廠正合你所需!', `FemaleText_loc7`='¡Si te apetece una cerveza exótica, en la Cervecería vudú de T''chali que hay en la Fiesta de la Cerveza tienen lo que necesitas!' WHERE `ID`=23525;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='긴장 한번 풀어보시렵니까? 가을 축제에 오셔서 촬리의 부두 양조장을 찾아주시면 부드럽게 넘어가는 맥주를 맛보실 수 있습니다!', `MaleText_loc4`='需要放松吗？去美酒节的塔卡里巫毒酒馆看看，那里的酒会让你感到舒畅！', `MaleText_loc5`='想要放鬆嗎?到啤酒節來試試提洽里的巫毒酒廠順喉的飲料吧!', `MaleText_loc7`='¿Necesitas relajarte? ¡Visita el puesto de la Cervecería vudú de T''chali en la Fiesta de la Cerveza para evitar un mal trago!', `FemaleText_loc1`='긴장 한번 풀어보시겠어요? 가을 축제에 오셔서 촬리의 부두 양조장을 찾아주시면 부드럽게 넘어가는 맥주를 맛보실 수 있을 거예요!', `FemaleText_loc4`='需要放松吗？去美酒节的塔卡里巫毒酒馆看看，那里的酒会让你感到舒畅！', `FemaleText_loc5`='想要放鬆嗎?到啤酒節來試試提洽里的巫毒酒廠順喉的飲料吧!', `FemaleText_loc7`='¿Necesitas relajarte? ¡Visita el puesto de la Cervecería vudú de T''chali en la Fiesta de la Cerveza para evitar un mal trago!' WHERE `ID`=23526;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흥겨움이 넘치는 곳이라면 촬리의 부두 맥주가 어울리지요! 가을 축제에 오셔서 흥겨움을 만끽하십시오!', `MaleText_loc4`='塔卡里的巫毒酒可以让狂欢一直继续下去！去美酒节看看吧！', `MaleText_loc5`='提洽里的巫毒酒幫助派對進行!來啤酒節來參加派對吧!', `MaleText_loc7`='¡La cerveza vudú de T''chali mantiene viva la fiesta! ¡No te pierdas la diversión en la Fiesta de la Cerveza!', `FemaleText_loc1`='흥겨움이 넘치는 곳이라면 촬리의 부두 맥주가 딱이지요! 가을 축제에 오셔서 흥겨움을 만끽하세요!', `FemaleText_loc4`='塔卡里的巫毒酒可以让狂欢一直继续下去！去美酒节看看吧！', `FemaleText_loc5`='提洽里的巫毒酒幫助派對進行!來啤酒節來參加派對吧!', `FemaleText_loc7`='¡La cerveza vudú de T''chali mantiene viva la fiesta! ¡No te pierdas la diversión en la Fiesta de la Cerveza!' WHERE `ID`=23527;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다 어디 갔지? 당장 알을 부화시켜!', `MaleText_loc4`='孵化者呢？快去孵蛋！', `MaleText_loc5`='雌鷹哪裡去啦?快去孵蛋!', `MaleText_loc7`='¿Dónde está mi criador? ¡A trabajar en esos huevos!' WHERE `ID`=23528;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기서 소방 기술을 연습하고 있지. 포세이큰에 힘을!', `FemaleText_loc4`='这里是练习灭火技术的地方，为了被遗忘者！', `FemaleText_loc5`='我們在此演練消防技巧。被遺忘者萬歲!', `FemaleText_loc7`='Aquí practicamos las técnicas para apagar fuegos. ¡Poder para los Renegados!' WHERE `ID`=23529;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 쓰러지는구나! 두려워 마라, 형제들이여! 그 무엇도 그대를 스톤포지와 갈라놓지 못하게 하라!', `MaleText_loc4`='我败了！弟兄们，别害怕！没有谁能将你们赶出岩石熔炉！', `MaleText_loc5`='我戰死了!別害怕，弟兄們!別讓任何事情阻止你們抵達石鑄堡!', `MaleText_loc7`='¡He caído! ¡No temáis, hermanos! ¡No permitáis que nada os aleje de la Forja de Piedra!' WHERE `ID`=23530;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아프단 말이다! 아우우우 우 우 아우우우!', `FemaleText_loc4`='好痛！好痛啊！！！', `FemaleText_loc5`='痛死了!喔喔喔喔喔喔喔喔喔!', `FemaleText_loc7`='¡Duele! ¡Ayyyyy ay ay aaaaayy!' WHERE `ID`=23531;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='클레이튼은 정말 멋져요!', `MaleText_loc4`='克雷顿太帅了！', `MaleText_loc5`='克雷頓很棒!', `MaleText_loc7`='¡Clayton es GENIAL!', `FemaleText_loc1`='클레이튼은 정말 멋져요!', `FemaleText_loc4`='克雷顿太帅了！', `FemaleText_loc5`='克雷頓很棒!', `FemaleText_loc7`='¡Clayton es GENIAL!' WHERE `ID`=23532;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='클레이튼은 하나도 안 멋져요!', `MaleText_loc4`='克雷顿不帅了！', `MaleText_loc5`='克雷頓不棒!', `MaleText_loc7`='¡Clayton NO es genial!', `FemaleText_loc1`='클레이튼은 하나도 안 멋져요!', `FemaleText_loc4`='克雷顿不帅了！', `FemaleText_loc5`='克雷頓不棒!', `FemaleText_loc7`='¡Clayton NO es genial!' WHERE `ID`=23533;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 고통에 찬 비명을 지르며 몸부림치고는 숨을 거둡니다.', `MaleText_loc4`='%s在临死前扭动着身躯，发出痛苦的呼喊声。', `MaleText_loc5`='%s尖叫著痛苦的扭曲著身體，接著便昏了過去。', `MaleText_loc7`='%s grita y se retuerce agónicamente antes de desmayarse.' WHERE `ID`=23534;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비명을 듣는 것만큼 즐거운 일도 없지.', `MaleText_loc4`='我最喜欢尖叫声了。', `MaleText_loc5`='我最喜歡的就是尖叫了。', `MaleText_loc7`='Lo que más me gusta son los gritos.' WHERE `ID`=23535;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 이방인들은 약해빠진 데다 금방 죽어버리는군.', `MaleText_loc4`='要令这些意志脆弱的外来者屈服真是太容易了。', `MaleText_loc5`='這些外地人脆弱而且隨便就能擊垮。', `MaleText_loc7`='Estos forasteros son débiles y fáciles de aplastar.' WHERE `ID`=23536;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 침략자 녀석들이 형벌을 얼마나 견딜 수 있는지 봐야겠군.', `MaleText_loc4`='我倒要看看这帮入侵者能承受怎样的折磨。', `MaleText_loc5`='讓我們來瞧瞧，這些入侵者能受得了多少懲罰。', `MaleText_loc7`='Veamos cuánto castigo pueden soportar estos invasores.' WHERE `ID`=23537;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 좋아! 아직 살아있군. 좀 더 재미를 볼 수 있겠어!', `MaleText_loc4`='很好！你还活着。我又有乐子咯！', `MaleText_loc5`='好!很好!你還活著。對我來說更好玩了!', `MaleText_loc7`='¡Bien! ¡Bien! Aún vives. ¡Más diversión para mí!' WHERE `ID`=23538;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='몸집이 작은 것치고는 생각보다 강하군.', `MaleText_loc4`='这帮家伙体型不大，意志倒是强硬得多嘛。', `MaleText_loc5`='就牠們的體型來看，比我預期中的還要吃苦耐勞。', `MaleText_loc7`='Son más duros de lo que hubiera esperado de alguien de su tamaño.' WHERE `ID`=23539;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n의 혼합물을 만드는 데 실패했습니다. 새 혼합물을 처음부터 다시 만들어야 합니다.', `MaleText_loc4`='$n的混合剂被毁坏了！必须重做一瓶。', `MaleText_loc5`='$n的合成物毀了，只能從頭再製造一份了。', `MaleText_loc7`='El brebaje de $n está arruinado. Hay que crear uno nuevo desde cero.' WHERE `ID`=23540;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살겠다는 생각은 버려라, $r. 난 밤이고 낮이고 이 짓을 계속할 수 있으니까 말이다.', `MaleText_loc4`='放弃求生的欲望吧。我可以整日整夜地折磨你。', `MaleText_loc5`='放棄求生的意志吧!我會日以繼夜的折磨你。', `MaleText_loc7`='¡Renuncia a tu voluntad de vivir! Puedo pasarme el día y la noche haciendo esto.' WHERE `ID`=23541;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<울팡이 긴 울음소리를 내더니 당신의 냄새를 맡습니다. 그러자 당신은 울팡이 말하는 바를 이해할 수 있습니다.>$B$B이상한 흰 늑대 가르왈이 북쪽에서 와서는 내가 이끌던 무리를 빼앗았네. 내가 다시 우두머리가 되려면 놈의 목을 쳐야만 하네.', `MaleText_loc4`='<乌尔芬低声嚎叫，嗅了嗅你身上的气味；接着你就明白了他的语言。>$B$B北方那头名叫迦瓦尔的白色座狼带走了我的狼群。我要割断他的喉咙，重新成为群族的首领。', `MaleText_loc5`='<巫牙高聲嚎叫，對你嗅了嗅，而你聽得懂牠說了些什麼。>$B$B來自北方的詭異白座狼，賈爾沃，奪走了我的狼群。我們必須得割斷牠的喉嚨，好讓我再一次成為座狼首領。', `MaleText_loc7`='<Ulkang aúlla y te huele, y tú puedes entender lo que dice.>$B$BEl extraño huargo blanco del norte, Garwal, se ha apoderado de mi manada. Debemos rajarle la garganta para que yo vuelva a ser el huargo alfa.' WHERE `ID`=23542;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 새끼를 보며 정답게 울어댑니다.', `MaleText_loc4`='%s对着雏鸟咕咕地叫。', `MaleText_loc5`='%s對著小角鷹獸咕咕叫。', `MaleText_loc7`='%s arrulla a las crías.' WHERE `ID`=23543;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기하고 칼바위 언덕 사이에서 비행선이 추락하는 바람에 술 유통 구조가 완전히 엉망이 됐어! 매시간 몰려드는 거 같은 저 검은무쇠 드워프들도 골치고!$b$b그러니 날 도우려거든, 이렇게 하라고. 내 산양과 산양 고삐를 빌려주지.$b$b맥주통을 가져올 때마다 상품 교환 동전을 주겠어. 아니, 맥주통을 가져올 때마다 산양도 더 오래 탈 수 있게 해주지!$b$b하지만 일단 이 일을 시작하면 내일까지 다시 할 수는 없다고.$b$b준비됐지?', `MaleText_loc4`='在剃刀岭和这里之间发生的坠毁事故把酿造流程搞的一塌糊涂！但那也不能改变黑铁矮人几乎每小时一次的进攻！$B$B如果你想帮忙的话，那么这样，我会让你从我们这里借一头山羊和一根缰绳。$B$B你每给我带来一个酒桶，我就给你些奖币，作为你给我带来酒桶的感谢，我甚至会让你更久地使用我的山羊！

但是，只要你开始了，在明天以前你就不能再做了。

你确定已经准备好了吗？', `MaleText_loc5`='發生在這裡及剃刀嶺之間的爆炸將我們的啤酒配送機制搞得一團亂!黑鐵矮人好像大約一個小時會來攻擊一次!$b$b所以如果你想幫忙的話，這有解決方法。我會借你一些韁繩以及一頭我的山羊。$b$b每次你帶給我一桶酒桶，我就會給你一些獎品章。你每帶一桶酒桶給我，我還會讓你使用這隻山羊的時間延長一點!$b$b不過，一旦你開始了，到明天之前你都不能再進行一次。$b$b你確定你準備好要開始了嗎?', `MaleText_loc7`='¡El accidente de Cerrotajo está entorpeciendo la llegada de la cerveza! ¡Y los ataques de los enanos Hierro Negro cada hora no están ayudando!$B$BAsí que si quieres ayudar, este es el trato: te prestaré unas riendas y uno de mis carneros.$B$BPor cada barril que me traigas te daré unas fichas. Hasta dejaré que te quedes con el carnero un ratito más por cada barril$B$B¡PERO una vez que empieces, no podrás repetirlo hasta mañana.$B$B¿Estás seguro de que estás preparado?', `FemaleText_loc1`='여기하고 칼바위 언덕 사이에서 벌어진 추락이 술 유통 구조를 완전히 망쳐 놨어! 매시간 몰려드는 거 같은 저 검은무쇠 드워프들도 골치고!$b$b그러니 만약 돕고 싶다면, 이렇게 하라고. 내 산양과 산양 고삐를 빌려주지.$b$b맥주통을 가져올 때마다 상품 교환 동전을 주겠어. 아니, 맥주통을 가져올 때마다 산양도 더 오래 탈 수 있게 해주지!$b$b하지만 일단 이 일을 시작하면 내일까지 다시 할 수는 없다고.$b$b준비됐지?', `FemaleText_loc4`='在剃刀岭和这里之间发生的坠毁事故把酿造流程搞的一塌糊涂！但那也不能改变黑铁矮人几乎每小时一次的进攻！$B$B如果你想帮忙的话，那么这样，我会让你从我们这里借一头山羊和一根缰绳。$B$B你每给我带来一个酒桶，我就给你些奖币，作为你给我带来酒桶的感谢，我甚至会让你更久地使用我的山羊！

但是，只要你开始了，在明天以前你就不能再做了。

你确定已经准备好了吗？', `FemaleText_loc5`='發生在這裡及剃刀嶺之間的爆炸將我們的啤酒配送機制搞得一團亂!黑鐵矮人好像大約一個小時會來攻擊一次!$b$b所以如果你想幫忙的話，這有解決方法。我會借你一些韁繩以及一頭我的山羊。$b$b每次你帶給我一桶酒桶，我就會給你一些獎品章。你每帶一桶酒桶給我，我還會讓你使用這隻山羊的時間延長一點!$b$b不過，一旦你開始了，到明天之前你都不能再進行一次。$b$b你確定你準備好要開始了嗎?', `FemaleText_loc7`='¡El accidente de Cerrotajo está entorpeciendo la llegada de la cerveza! ¡Y los ataques de los enanos Hierro Negro cada hora no están ayudando!$B$BAsí que si quieres ayudar, este es el trato: te prestaré unas riendas y uno de mis carneros.$B$BPor cada barril que me traigas te daré unas fichas. Hasta dejaré que te quedes con el carnero un ratito más por cada barril$B$B¡PERO una vez que empieces, no podrás repetirlo hasta mañana.$B$B¿Estás seguro de que estás preparado?' WHERE `ID`=23544;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 일할 준비가 다 됐습니다! 저 산양을 주세요!', `MaleText_loc4`='我准备为你工作了！给我一头山羊！', `MaleText_loc5`='我今天準備好要為你工作了!給我山羊吧!', `MaleText_loc7`='¡Estoy listo para trabajar para ti! ¡Dame ese carnero!', `FemaleText_loc1`='오늘 일할 준비가 다 됐어요! 저 산양을 주세요!', `FemaleText_loc4`='我准备为你工作了！给我一头山羊！', `FemaleText_loc5`='我今天準備好要為你工作了!給我山羊吧!', `FemaleText_loc7`='¡Estoy lista para trabajar para ti! ¡Dame ese carnero!' WHERE `ID`=23545;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼바위 언덕 근처의 추락 지점에서 맥주통을 날라 올 일손이 아직 필요하십니까?', `MaleText_loc4`='你仍然需要帮忙从剃刀岭附近的坠毁点那里搬运酒桶吗？', `MaleText_loc5`='你還需要人幫忙搬運剃刀嶺附近爆炸地點的酒桶嗎?', `MaleText_loc7`='¿Aún necesitas ayuda para transportar algunos barriles desde el lugar de accidente cerca de Cerrotajo?', `FemaleText_loc1`='칼바위 언덕 근처의 추락 지점에서 맥주통을 날라 올 일손이 아직 필요하세요?', `FemaleText_loc4`='你仍然需要帮忙从剃刀岭附近的坠毁点那里搬运酒桶吗？', `FemaleText_loc5`='你還需要人幫忙搬運剃刀嶺附近爆炸地點的酒桶嗎?', `FemaleText_loc7`='¿Aún necesitas ayuda para transportar algunos barriles desde el lugar de accidente cerca de Cerrotajo?' WHERE `ID`=23546;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 ''정식으로 수입된'' 우리 경주용 산양을 살펴보는 걸 봤네... 산양 경주의 열정에 빠지고 싶어하는 거 다 보인다고... 하지만 놀고 싶으면 먼저 일을 해야지.$b$b한데, 이 산양을 탈 수만 있다면 일이나 노는 거나 비슷하다고.', `MaleText_loc4`='我看到你在欣赏我们合法拥有的赛羊……我能感觉到，你想要参加赛羊会……不过在你参与之前，你必须得做些事。$B$B嗯，对于这些山羊来说，工作和玩其实是一样的。', `MaleText_loc5`='我看到你在欣賞我們合法取得的競速山羊...我看得出來你想要感受山羊競速的快感...但在你能夠騎上山羊並且競速之前，你得先工作。$b$b沒錯，工作跟競速對這些山羊來說是一樣的。', `MaleText_loc7`='Veo que inspeccionas los carneros que hemos obtenido de forma totalmente legal... Sé que quieres descubrir la sensación de montar en un carnero... Pero antes de jugar hay que trabajar.$B$BBueno, cuando se trata de estos carneros jugar y trabajar son lo mismo.' WHERE `ID`=23547;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='들었소, 제탄? 강철깃털은 어미라오. 그러니 함부로 잡을 생각 마시오.', `MaleText_loc4`='杰森，你给我听着。既然钢羽还有一窝嗷嗷待哺的雏鸟，你就别想动她。', `MaleText_loc5`='聽見了嗎，傑桑?既然我們知道鋼羽已經當媽媽了，你就不能將鋼羽當作是獎賞。', `MaleText_loc7`='¿Has oído eso, Jethan? No vas a conseguir ese trofeo Pluma de Acero ahora que sabemos que es una madre.' WHERE `ID`=23548;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 안 된단 거요? 새끼도 박제로 만들어서 어미 양옆에 놓으면 얼마나 멋질지 생각을...', `MaleText_loc4`='为什么啊？如果我们能将她和雏鸟做成标本，陈列在一起也挺不错的呀——', `MaleText_loc5`='為什麼不?想想要是兩邊都有小角鷹獸的話，這會有多好看 --', `MaleText_loc7`='¿Por qué no? Piensa en lo mucho que mejorará su aspecto con las crías a cada lado...' WHERE `ID`=23549;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제탄!', `MaleText_loc4`='杰森！', `MaleText_loc5`='傑桑!', `MaleText_loc7`='¡Jethan!' WHERE `ID`=23550;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜요? 회색 구릉지에서는 원래 그렇게 하는데.', `MaleText_loc4`='干嘛啊？我们在灰熊丘陵的时候可不就是这么做的嘛。', `MaleText_loc5`='什麼?事情在灰白之丘我們就是那麼幹的。', `MaleText_loc7`='¿Qué? Solo digo que así es como hacemos las cosas en las Colinas Pardas.' WHERE `ID`=23551;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무쇠 드워프는 이렇게 생긴 상자에 도구를 보관합니다. 천막 근처에서 찾아보세요.', `MaleText_loc4`='他们将工具放在这样的箱子里。去营帐附近找找看。', `MaleText_loc5`='他們把工具放在類似這樣的箱子裡面，在附近的涼亭裡面找找看吧。', `MaleText_loc7`='Guardan sus armas en cajas con este aspecto. Búscalas cerca de los pabellones.' WHERE `ID`=23552;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저번에 아이언포지 앞에서 군인 아저씨들이 불 끄시는 걸 봤어요. 그런 게 영웅의 모습이죠!', `MaleText_loc4`='我之前看到过铁炉堡的士兵灭火。他们是英雄！', `MaleText_loc5`='我看過之前一群來自鐵爐堡的士兵救過火。他們是英雄!', `MaleText_loc7`='Antes he visto a algunos soldados de Forjaz apagando un fuego. ¡Parecían héroes!', `FemaleText_loc1`='저번에 아이언포지 앞에서 군인 아저씨들이 불 끄시는 걸 봤어요. 정말 멋있었어요!', `FemaleText_loc4`='我之前看到过铁炉堡的士兵灭火。他们是英雄！', `FemaleText_loc5`='我看過之前一群來自鐵爐堡的士兵救過火。他們是英雄!', `FemaleText_loc7`='Antes he visto a algunos soldados de Forjaz apagando un fuego. ¡Parecían héroes!' WHERE `ID`=23553;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 멀뚱멀뚱 서 있지 말라고요! 카라노스가 불타고 있단 말입니다! 가서 도우라고요! 아우, 아까운 술...', `MaleText_loc4`='$n，不要傻站在那里！卡拉诺斯正在燃烧！快去帮忙！啊，所有的酒……', `MaleText_loc5`='$n，不要只是站在那啊!卡拉諾斯燒起來了!去幫忙!天啊，那些酒...', `MaleText_loc7`='¡Espabila, $n! ¡Kharanos está ardiendo! ¡Ve a ayudar! Toda esa cerveza...', `FemaleText_loc1`='$n, 멀뚱멀뚱 서 있지 마세요! 카라노스가 불타고 있어요! 가서 도우라고요! 아아, 아까운 술...', `FemaleText_loc4`='$n，不要傻站在那里！卡拉诺斯正在燃烧！快去帮忙！啊，所有的酒……', `FemaleText_loc5`='$n，不要只是站在那啊!卡拉諾斯燒起來了!去幫忙!天啊，那些酒...', `FemaleText_loc7`='¡Espabila, $n! ¡Kharanos está ardiendo! ¡Ve a ayudar! Toda esa cerveza...' WHERE `ID`=23554;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불 끄는 연습을 하고 싶다면 여기가 딱 좋습니다. 주변에 눈 무더기야 있지만, 스틸그릴이나 저 노움 녀석들이 언제 폭발을 일으킬지 모르니까 말이죠.', `MaleText_loc4`='如果你想接受灭火训练，那么你来对了地方。虽然在这附近到处都是雪，但你永远都不知道贝尔丁·钢架还是那些侏儒什么时候会引起一场爆炸，对吧？', `MaleText_loc5`='如果你想要進行消防演練，這裡就是了。在這附近可能會有一堆雪，不過你永遠不知道何時鋼架或是那些地精們會引起爆炸，對吧?', `MaleText_loc7`='Si buscas un lugar para apagar fuegos de práctica, has venido al lugar adecuado. Puede que haya un montículo de nieve, pero nunca se sabe cuando van a causar una explosión los Brasacerada o los gnomos.', `FemaleText_loc1`='불 끄는 연습을 하고 싶다면 여기가 딱 좋지요. 주변에 눈 무더기야 있지만, 스틸그릴이나 저 노움 녀석들이 언제 폭발을 일으킬지 모르니까 말이에요.', `FemaleText_loc4`='如果你想接受灭火训练，那么你来对了地方。虽然在这附近到处都是雪，但你永远都不知道贝尔丁·钢架还是那些侏儒什么时候会引起一场爆炸，对吧？', `FemaleText_loc5`='如果你想要進行消防演練，這裡就是了。在這附近可能會有一堆雪，不過你永遠不知道何時鋼架或是那些地精們會引起爆炸，對吧?', `FemaleText_loc7`='Si buscas un lugar para apagar fuegos de práctica, has venido al lugar adecuado. Puede que haya un montículo de nieve, pero nunca se sabe cuando van a causar una explosión los Brasacerada o los gnomos.' WHERE `ID`=23555;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 하늘 감시초소가 불타고 있습니다! 가서 불 끄는 걸 도우십시오!', `MaleText_loc4`='$n，碧蓝岗哨的村庄正在燃烧！快去帮忙灭火！', `MaleText_loc5`='$n，藍色守望的村落燒起來了!去幫忙滅火!', `MaleText_loc7`='¡$n, la Avanzada Azur está ardiendo! ¡Ayúdales a apagar el fuego!', `FemaleText_loc1`='$n, 하늘 감시초소가 불타고 있어요! 가서 불 끄는 걸 도우세요!', `FemaleText_loc4`='$n，碧蓝岗哨的村庄正在燃烧！快去帮忙灭火！', `FemaleText_loc5`='$n，藍色守望的村落燒起來了!去幫忙滅火!', `FemaleText_loc7`='¡$n, la Avanzada Azur está ardiendo! ¡Ayúdales a apagar el fuego!' WHERE `ID`=23556;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소방 기술을 연습할 수 있도록 이곳을 꾸몄답니다. 마을이 언제 위험에 처할지 모르니까요!', `MaleText_loc4`='我们设立这个地方就是为了练习灭火。你永远都无法预知村子什么时候会有危险。', `MaleText_loc5`='我們設立這個地區是為了作消防演練。你永遠不知道城鎮什麼時候會陷入災難之中!', `MaleText_loc7`='Hemos preparado esta zona para practicar las técnicas de apagado de fuegos. ¡Nunca se sabe cuando estará en peligro la ciudad!', `FemaleText_loc1`='소방 기술을 연습할 수 있도록 이곳을 꾸몄답니다. 마을이 언제 위험에 처할지 모르잖아요!', `FemaleText_loc4`='我们设立这个地方就是为了练习灭火。你永远都无法预知村子什么时候会有危险。', `FemaleText_loc5`='我們設立這個地區是為了作消防演練。你永遠不知道城鎮什麼時候會陷入災難之中!', `FemaleText_loc7`='Hemos preparado esta zona para practicar las técnicas de apagado de fuegos. ¡Nunca se sabe cuando estará en peligro la ciudad!' WHERE `ID`=23557;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 멍청한 사고뭉치 칭구! 요새 어떻 지내?$B$B이 동네 별스럽지 않나, 이 바보!', `MaleText_loc4`='喂，你！干嘛呢，勤快点！$B$B没看到这里人人都忙着么，你这个饭桶！', `MaleText_loc5`='唷喝，老兄!混得不錯吧，你這個壞蛋!$B$B這個地方很誇張啊!', `MaleText_loc7`='¡Ah del barco, asere! ¿Qué ocurre, perro de agua salada?$B$B¡Este lugal es todo extraño, cheche!' WHERE `ID`=23558;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 나가는 것 같군, 칭구! 부유한 상인 물건 많이 털었? 웬만 좀 뿌리는 게 좋아... 과욕 목 조르는 법!', `MaleText_loc4`='朋友，瞧你那副得意忘形的模样！你是不是从哪个富商那儿抢到什么好东西了？财富是要大家分享的……朋友，别小气嘛！', `MaleText_loc5`='看起來春風滿面啊，我的朋友!你洗劫了哪個小販嗎?分一點...不要當鐵公雞啦，老兄!', `MaleText_loc7`='¡Tienes buen aspecto, compay! ¿Robaste a algún masetero? Será mejor que repartas las riquesas... ¡no seas un sucio perro agarrao, camarada!' WHERE `ID`=23559;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기 좀 봐, 칭구! 저 천박 바보 완전 끝났어. 저 저속한 녀석 바닷물 실컷 마시다 배 밑바닥 끌려가 곧 귀신 된다.', `MaleText_loc4`='瞧那边！那蠢货把农夫给惹火了。这下麻烦了吧，我看他的小命难保啦。', `MaleText_loc5`='看過來呀，朋友!那個白痴對那個農夫發飆啦。那個牛脾氣混蛋大禍臨頭了，老兄...就要被殺了變鬼啦，老兄。', `MaleText_loc7`='¡Mira tú allá, compay! ¡Ese tío con escorbuto está cabreando al guajiro! El muy terco va a tragar sal, yunta...  lo van a pasar pol debajo de la quilla y se va a quedar hecho un trapo, asere.' WHERE `ID`=23560;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노새에게 편자를 신기는 데 얼마나 내야 합니까?', `MaleText_loc4`='为骡子钉上马蹄铁要花多少钱啊？', `MaleText_loc5`='幫我的騾子釘馬蹄鐵要花我多少錢?', `MaleText_loc7`='¿Cuánto me costará herrar a mis mulos?' WHERE `ID`=23561;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기선 편자 같은 건 취급 안 합니다. 게다가 지금은 원정대 일만 맡게 되어 있어요.', `MaleText_loc4`='我们不负责给骡子钉马蹄铁。准确地说，那是远征队的事儿。', `MaleText_loc5`='我們這裡不幫騾子釘馬蹄鐵。還有，現在那只屬於遠征軍的生意。', `MaleText_loc7`='Aquí no herramos mulos. Además, por el momento aquí solo se atienden asuntos de la expedición.' WHERE `ID`=23562;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말귀를 못 알아듣는군! 빨리 준비하지 못하면 집 짓기 좋은 땅을 다 뺏긴단 말입니다!', `MaleText_loc4`='你完全不了解状况！如果我不赶紧出发的话，好的建筑用地都会被别人抢先霸占啦！', `MaleText_loc5`='你不懂!要是我不趕快走，所有好的開墾者耕地會被奪走的!', `MaleText_loc7`='¡No lo entiendes! ¡Si no estoy listo para irme pronto, toda la tierra buena para construir la granja estará cogida!' WHERE `ID`=23563;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나랑은 상관없어요! 집을 못 지을까 봐 그렇게 안달복달이면 이 요새에다 집 짓고 들어가 사시던가!', `MaleText_loc4`='这又不是我的问题！如果你这么着急建房子的话，就在要塞里建好了，省得你整天抱怨！', `MaleText_loc5`='這不是我的問題啊!如果你真的這麼急著要蓋自己的房子，就在堡壘裡面做然後不要再發牢騷了!', `MaleText_loc7`='¡No es mi problema! ¡Si estás tan ansioso por construirte una casa, hazlo aquí en el fuerte y deja de quejarte!' WHERE `ID`=23564;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사실이다, 칭구! 이 일대에서 북쪽바다 약탈자만큼 강한 해적 없다!$B$B열 받게 안 하는 게 좋다. 웃기지도 않지! 그래도 미련한 녀석 매 맞게 마련!', `MaleText_loc4`='朋友，我说的是实话！北海海盗是世界上最强硬的海盗。$B$B你最好不要惹事。算啦！反正所有的白痴海盗都会被处死！', `MaleText_loc5`='我是說真的，朋友!沒有誰比這兒的北海掠劫者還要更厲害啦，老兄!$B$B你最好不要生他們的氣嘿，老兄。算了吧!誰的行為舉止才開始瘋瘋癲癲就準備「去親砲手的女兒」了，朋友!', `MaleText_loc7`='¡Es la verdad, compay! ¡No hay marinero más duro que los piratas del Mar del Norte! Mejor no enfadar a nadie, camarada. ¡Fíjate tú! ¡Todos los marineros estúpidos acaban siendo asotaos, compay!' WHERE `ID`=23565;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼, 이제 내 모루에서 당신 나귀 좀 치워주면 고맙겠습니다...', `MaleText_loc4`='你能不能从我的熔炉旁滚开……', `MaleText_loc5`='那麼，你可不可以好心的滾開我的火爐呢...', `MaleText_loc7`='Ahora, si eres tan amable de alejar eso de mi forja...' WHERE `ID`=23566;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저건 말입니다, 대장장이 양반, 노새라고요!', `MaleText_loc4`='那，那是头骡子！', `MaleText_loc5`='長官，那是頭騾子!', `MaleText_loc7`='¡Eso es un mulo, señor!' WHERE `ID`=23567;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음... 무슨 말입니까?', `MaleText_loc4`='嗯……那是什么？', `MaleText_loc5`='呃...那是什麼?', `MaleText_loc7`='Um... ¿qué ha sido eso?', `FemaleText_loc1`='음... 무슨 말이죠?', `FemaleText_loc4`='嗯……那是什么？', `FemaleText_loc5`='呃...那是什麼?', `FemaleText_loc7`='Um... ¿qué ha sido eso?' WHERE `ID`=23568;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야단법석에 건방지다! 망할 녀석, 날 화나게 하겠다 이거?$B$B그럼 잘해봐, 겁쟁이 악당. 그럼 내일 보자!', `MaleText_loc4`='朋友，你这样就很无耻了。你是想惹我发火是吧？滚，你这个懦弱的海盗。明天再见！', `MaleText_loc5`='你的臉皮越來越厚了，老兄!你其實只是想要惹火我吧?你這條癩皮狗!$B$B滾蛋啦，你這個膽小的海賊。明天天亮就來見我!', `MaleText_loc7`='¡Y ahora te pones cheche! ¿Intentas ofenderme, pulgoso chucho de tierra firme?$B$bApártate, cobarde pillastre. ¡Voy en pira, t''aluego!' WHERE `ID`=23569;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빌더바르 요새에 잘 오셨소, 용감한 개척자 여러분! 주위의 모든 땅이 우리 손길을 기다리고 있소!', `MaleText_loc4`='欢迎来到维德瓦堡垒！瞧，那片土地等着你去占领呢！', `MaleText_loc5`='歡迎來到威德瓦堡壘，勇敢的開墾者!這裡有一整片大陸等著被佔有呢!', `MaleText_loc7`='¡Bienvenidos al Fuerte Vildervar, valientes conquistadores! ¡Hay un continente entero esperando a ser reclamado!' WHERE `ID`=23570;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노스렌드가 척박한 땅인 것은 분명하지만, 우린 강인하고 굳센 사람들이니 충분히 이 일을 해낼 수 있소!', `MaleText_loc4`='是啊，诺森德的环境极其恶劣，但是我们拥有强壮的体魄和勇敢的精神，能面对一切挑战！', `MaleText_loc5`='的確，北裂境是個嚴酷的地方，但是我們的族人更強壯，足以勝任!', `MaleText_loc7`='Cierto, Rasganorte es una tierra dura, ¡pero nuestra gente es fuerte, robusta y muy apta para la tarea!' WHERE `ID`=23571;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 검으로 이 땅을 손에 넣고 우리의 농기구로 이 땅을 일구어 나갈 것입니다! 여러분은 거친 땅을 길들인 자로서 두고두고 기억될 것이오!', `MaleText_loc4`='我们要用刀剑夺得这片土地的所有权，然后用犁来开垦荒地！而你们，将作为拓荒的先驱者，被后世传颂。', `MaleText_loc5`='我們會用這把劍贏得這片地，用這張犁劃過這片地!你們將被後人永遠記住，第一位駕馭這塊蠻荒大陸的人!', `MaleText_loc7`='¡Ganaremos esta tierra con la espada y la domaremos con el arado! ¡Sois los hombres y mujeres que serán recordados por haber amansado el continente salvaje!' WHERE `ID`=23572;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 여러분은 혼자가 아니오. 내 부하들이 여러분에게 가장 필요한 보급품을 짐노새에 실어 가져왔소.', `MaleText_loc4`='你们并不孤单。我们特意准备了一群骡子，运送你们所需的补给物资。', `MaleText_loc5`='但，你在那兒並不孤單。我和我的手下準備了運貨馱騾載有你急需的補給品。', `MaleText_loc7`='Pero no estaréis solos allí. Mis hombres y yo hemos preparado mulas de carga con los suministros que os resultarán necesarios.' WHERE `ID`=23573;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도끼, 곡괭이, 씨앗, 못, 음식, 담요, 물... 필요한 건 뭐든지 거기 다 있소. 가격도 딱 적당할 거요.', `MaleText_loc4`='斧头、锄头、种子、钉子、食物、毯子、水……任凭你们挑选。价格非常合理哟。', `MaleText_loc5`='斧頭、鍬、種子、釘子、食物、毛毯、飲水...都在這了，為了你準備好。你也會發現我的價格非常合理。', `MaleText_loc7`='Hachas, picos, clavos, comida, mantas, agua... todo esto os está esperando allí. Creo que mis precios os parecerán muy razonables.' WHERE `ID`=23574;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='충분하고도 남을 만큼 많이 있소. 만약 다른 물건이 필요하다면 주저하지 말고 요청하시오!', `MaleText_loc4`='我的物资供应非常充足。如果你们还需要其它的货物，欢迎随时来找我！', `MaleText_loc5`='東西應有盡有，如果你還要其他貨物，別擔心，儘管開口要!', `MaleText_loc7`='Hay más que suficiente para ir tirando. Si necesitáis otros bienes, no dudéis en pedirlos.' WHERE `ID`=23575;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 친애하는 소비자 여러... 아니, 친구들이여. 모든 이를 위해 이 땅을 개척해 나갑시다!', `MaleText_loc4`='我忠诚的顾客，呃……朋友们，来吧，征服这片土地！', `MaleText_loc5`='那麼，我親愛的顧客...呃，我是說朋友，為了我們的人民前去征服這片土地吧!', `MaleText_loc7`='¡Ahora, mis leales clien... err amigos, id y conquistad esta tierra para nuestra gente!' WHERE `ID`=23576;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러니까, 당신이 새로 왔다는 그 잘난 친군가 보군요?$B$B<땅에 침을 뱉는 조렉>$B$B흠, 그래요...', `MaleText_loc4`='你是新来的吧，瞧你那副自以为是的模样。$B$B<索雷克朝地上吐了口唾沫。>$B$B肯定是……', `MaleText_loc5`='你就是那個最近剛到鎮上的高手，是嗎?$B$B<索芮克朝著地上吐了一口唾沫。>$B$B是啦...', `MaleText_loc7`='Así que eres la novedad en la ciudad, ¿eh?$B$B<Zorek escupe al suelo.>$B$BSí...' WHERE `ID`=23577;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 예술에 대해서는 잘 몰라도... 내가 뭘 좋아하는지는 잘 알지!', `MaleText_loc4`='我不太懂艺术……但是我知道自己喜欢什么！', `MaleText_loc5`='我不懂藝術品...但是我知道我喜歡什麼!', `MaleText_loc7`='No sé mucho yo sobre arte... pero sé lo que me gusta.' WHERE `ID`=23578;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여어, 형제! 이제 가서 술 한잔 돌려. 여기 있는 무기력한 친구들 말이야.', `MaleText_loc4`='嘿，兄弟！给我们来点啤酒吧。你瞧，酒杯都空了。', `MaleText_loc5`='是的，我的朋友!現在就去拿瓶酒來，這裡的都空了。', `MaleText_loc7`='¿Qué bolá, asere? Ve y pilla un poco de walfarina, esto está muerto.' WHERE `ID`=23579;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 봐, 애송이! 해적 춤이 어떤 건지 제대로 보여 준다!', `MaleText_loc4`='伙计，瞧好啦。我来让你见识一下什么是真正的舞蹈。', `MaleText_loc5`='好好看著，伙計!我讓你見識一下什麼叫做跳舞!', `MaleText_loc7`='¡Mira bien, desgraciado! ¡Te enseñaré cómo bailan los piratas!' WHERE `ID`=23580;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 그런 동네 아냐. 어떤 반항쟁이도 내 칭구한테 장난치고 도망 못 가.', `MaleText_loc4`='朋友，你瞧，谁敢欺负我的朋友，我就让他没好果子吃！', `MaleText_loc5`='這群人都很棒，老兄，沒有什麼痞子可以惹毛我的朋友全身而退的!', `MaleText_loc7`='¡Aquí se respeta el grado, guanajo! ¡Nadie fastidia a mis consortes y se va sin más!' WHERE `ID`=23581;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<늙은 얼음지느러미가 모래 위에 그림을 그립니다. 대충 그린 그림이지만 당신이 도와주기를 바란다는 것을 알 수 있습니다.>', `MaleText_loc4`='<老冰鳞在沙地上画画，希望你能从粗糙的图案上看出他是在企求你的帮助。>', `MaleText_loc5`='<老冰鰭在沙地上緩步行走。從他跟著你的樣子來看，你猜他需要你的幫助。>', `MaleText_loc7`='<El Viejo Aleta Helada dibuja en la arena. De los primitivos dibujos que hace deduces que quiere que le ayudes.>' WHERE `ID`=23582;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 불 끄는 연습을 합니다.', `MaleText_loc4`='我们在这里练习灭火技术。', `MaleText_loc5`='我們在此練習消防技巧。', `MaleText_loc7`='Aquí practicamos las técnicas para apagar fuegos.', `FemaleText_loc1`='여기서 불 끄는 연습을 해요.', `FemaleText_loc4`='我们在这里练习灭火技术。', `FemaleText_loc5`='我們在此練習消防技巧。', `FemaleText_loc7`='Aquí practicamos las técnicas para apagar fuegos.' WHERE `ID`=23583;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서요, $c! 불꽃이 매날개 광장을 집어삼키고 있습니다! 가세요! 불을 끄세요!', `MaleText_loc4`='快点，$c！鹰翼广场到处都是火焰！走！去扑灭那些火焰！', `MaleText_loc5`='動作快，$c!火舌已經蔓延到獵鷹之翼廣場了!快!快去救火!', `MaleText_loc7`='¡Rápido, $c! ¡La Plaza Alalcón está ardiendo! ¡Ve a apagar esos fuegos!', `FemaleText_loc1`='어서요, $c! 불꽃이 매날개 광장을 집어삼키고 있어요! 가세요! 불을 끄세요!', `FemaleText_loc4`='快点，$c！鹰翼广场到处都是火焰！走！去扑灭那些火焰！', `FemaleText_loc5`='動作快，$c!火舌已經蔓延到獵鷹之翼廣場了!快!快去救火!', `FemaleText_loc7`='¡Rápido, $c! ¡La Plaza Alalcón está ardiendo! ¡Ve a apagar esos fuegos!' WHERE `ID`=23584;
