UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='명심해요, 여보. 우린 온천수가 솟아나는 땅을 구해야 해요.', `FemaleText_loc4`='亲爱的，我们得找到一块带温泉的好地方。', `FemaleText_loc5`='親愛的，記住，我們需要一小塊有熱溫泉的地方喔。', `FemaleText_loc7`='Recuerda cariño, tenemos que conseguir un terreno con un bonito manantial calentito.' WHERE `ID`=23605;
