UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그리고 끔찍한 늑대나, 거인이나, 그 이상하게 생긴 산양이 있는 곳은 싫어요!', `FemaleText_loc4`='我可不希望在咱们的土地上遇见恐怖的狼、巨人或是丑陋的山羊。', `FemaleText_loc5`='還有，我也不希望我們的土地上有討厭的狼，巨人，或者是醜不拉機的山羊喔!', `FemaleText_loc7`='¡Y no quiero que nuestro terreno tenga ningún horrible lobo, ni gigantes, ni carneros feos!' WHERE `ID`=23607;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 여보. 하지만 작물을 심고 수확하기 전까진 그 양고기를 먹어야 한단 건 알아 둬요...', `MaleText_loc4`='你说得对，亲爱的。不过在庄稼成熟之前，咱们还不得靠羊肉维持生计……', `MaleText_loc5`='好啦，親愛的，可是你要知道，在我們開始播種之前，你還是得吃這些兇暴山羊肉當晚餐耶...', `MaleText_loc7`='Sí, cariño. Sabes que cenarás carne de carnero hasta que se plante la cosecha...' WHERE `ID`=23608;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그럼 곧 당신 노새를 잡아야겠네요! 그러고 보니, 뭣 하러 저 짐승을 여기까지 끌고 온 거죠?', `FemaleText_loc4`='我宁可屠宰那些骡子！我说，你为什么不带些牲畜来呢？', `FemaleText_loc5`='那我寧願吃你的那頭騾子!不過，你到底為什麼要把這頭畜生帶來?', `FemaleText_loc7`='¡Antes descuartizaría a ese mulo tuyo! ¿Por qué has traído esa bestia aquí?' WHERE `ID`=23609;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 목소리보다 차라리 그놈 울음소리를 듣는 게 마음이 편하겠소, 여보.', `MaleText_loc4`='亲爱的，我宁可听骡子叫也不愿意听你讲话。', `MaleText_loc5`='我寧願聽驢叫叫也不願意聽你抱怨，親愛的。', `MaleText_loc7`='Preferiría escuchar su rebuzno al tuyo, cielo.' WHERE `ID`=23610;
