UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<늙은 얼음지느러미가 경계하듯 바라봅니다. 무뚝뚝하게 그만 가 보라는 듯 머리를 꾸벅이면서 물고기 같은 눈을 깜빡입니다.>', `MaleText_loc4`='<老冰鳞警惕地盯着你，他漫不经心地晃动着脑袋，眨巴着死鱼眼。>', `MaleText_loc5`='<老冰鰭謹慎地望著你，上下點了他的頭一下，眨了眨眼睛做簡短的結束。>', `MaleText_loc7`='<El Viejo Aleta Helada te mira con recelo, su ojo de pez parpadea mientras él mueve su cabeza hacia arriba y hacia abajo a modo de brusco rechazo.>' WHERE `ID`=23622;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공동주택을 파괴했습니다! 멀리서 비상경보가 들립니다.', `MaleText_loc4`='长屋被摧毁了！警报声响彻云霄。', `MaleText_loc5`='長屋被毀了!遠處就能聽見警鐘的聲音。', `MaleText_loc7`='¡La casa comunal está destruida! Se oyen alarmas a lo lejos.' WHERE `ID`=23623;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방어하십시오! 작살총으로 불타는 창을 쏘세요! 자기 무기에 당하는 맛이 어떤지 녀석들에게 가르쳐 주시라고요!', `MaleText_loc4`='士兵，学会自我保护！用长枪将他们从空中打下来！以牙还牙！', `MaleText_loc5`='大兵，堅守陣地!用火焰長槍把他們射下天空!讓他們也嚐嚐自己加諸在別人身上的苦果是什麼滋味!', `MaleText_loc7`='¡Defiéndete, soldado! ¡Tíralos del cielo con la lanza ardiente! ¡Deja que prueben su propia medicina!' WHERE `ID`=23624;
