UPDATE `locales_broadcast_text` SET `MaleText_loc1`='현명한 사람에겐 한 마디면 충분하다는 말이 있지. 집으로 돌아가게.$b$b근심 걱정 없는 명랑한 여행자가 나설 자리가 아니야. 자네 같은 이가 여기 발을 들였다간 뼈와 살이 분리되고 말 걸세.', `MaleText_loc4`='陌生人，我说你还是回去吧。$b$b这里不是供你游历的风景地。它会摧毁你的躯体，嚼碎你的骨头。', `MaleText_loc5`='奉勸你一句話，陌生人，回到你原來的地方吧。$b$b這裡並不適合無憂無慮的探險者。這裡會將你這種人吞食掉，只留下骨頭而已。', `MaleText_loc7`='Escucha estas sabias palabras y vuelve a tu casa.$B$BEste no es lugar para aventureros despreocupados. Te engullirá y escupirá tus huesos.' WHERE `ID`=23636;
