UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"으아아아아아아아... 미치겠군!" 잠깐... 이게 아닌 것 같은데...', `MaleText_loc4`='“耶……酒精真令人发狂呀！”等等……酒劲来没上来呢……', `MaleText_loc5`='「呀啊啊啊啊...它把我惹毛啦!」等等...事情不該是這樣的呀...', `MaleText_loc7`='"¡Aaaaaaaaaarrr... m''estoy volviendo quimbao!" Espera... esto no es así...', `FemaleText_loc1`='"이야아아아아아아... 정말 죽겠네!" 잠깐... 이게 아닌 것 같은데...', `FemaleText_loc4`='“耶……酒精真令人发狂呀！”等等……酒劲来没上来呢……', `FemaleText_loc5`='「呀啊啊啊啊...它把我惹毛啦!」等等...事情不該是這樣的呀...', `FemaleText_loc7`='"¡Aaaaaaaaaarrr... m''estoy volviendo quimbá!" Espera... esto no es así...' WHERE `ID`=23658;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앉아서 한 잔 하시오, 친구! 나한테도 한 잔 사 주고!', `MaleText_loc4`='朋友，坐下来喝一杯吧！也给我来一杯！', `MaleText_loc5`='拿張椅子喝杯酒吧，朋友!要是你有椅子也幫我拿一張吧!', `MaleText_loc7`='¡Siéntate y agarra una bebida, compay! ¡Y ya que estás, tráeme una a mí!', `FemaleText_loc1`='앉아서 한 잔 하세요! 저한테도 한 잔 사 주시고요!', `FemaleText_loc4`='朋友，坐下来喝一杯吧！也给我来一杯！', `FemaleText_loc5`='拿張椅子喝杯酒吧，朋友!要是你有椅子也幫我拿一張吧!', `FemaleText_loc7`='¡Siéntate y agarra una bebida, compay! ¡Y ya que estás, tráeme una a mí!' WHERE `ID`=23659;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='...그 녀석은 두 다리가 의족이고, 왼손은 갈고리고, 두 눈알은 유리 눈에, 코는 나무로 깎아 만든 코야!', `MaleText_loc4`='……那个卑鄙的海盗安着两条木腿，左手是个铁钩，他还有两颗玻璃假眼和木头鼻子！', `MaleText_loc5`='...那個海賊有兩條假腿，左手有個鉤子，兩顆玻璃眼珠，和一條木頭鼻子!', `MaleText_loc7`='¡... ese susio perro de mar tenía dos patas de palo, un garfio po mano derecha, dos ojos de cristal y una narís de madera!', `FemaleText_loc1`='...그 녀석은 두 다리가 의족에, 왼손은 갈고리고, 두 눈깔은 유리 눈에, 코는 나무로 깎아 만든 코라니까!', `FemaleText_loc4`='……那个卑鄙的海盗安着两条木腿，左手是个铁钩，他还有两颗玻璃假眼和木头鼻子！', `FemaleText_loc5`='...那個海賊有兩條假腿，左手有個鉤子，兩顆玻璃眼珠，和一條木頭鼻子!', `FemaleText_loc7`='¡... ese susio perro de mar tenía dos patas de palo, un garfio po mano derecha, dos ojos de cristal y una narís de madera!' WHERE `ID`=23660;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아. 희생양이 하나 늘었군.', `MaleText_loc4`='啧啧，送上门来的祭品。', `MaleText_loc5`='太棒了，另外一頭被獻祭的羔羊。', `MaleText_loc7`='Excelente, otro cordero para el sacrificio.' WHERE `ID`=23661;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇게 죽고 싶으냐?', `MaleText_loc4`='你是来送死的吧？', `MaleText_loc5`='我們就這麼急著找死嗎?', `MaleText_loc7`='¿Estamos tan ansiosos por morir?' WHERE `ID`=23662;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너 또한 리치 왕을 섬기게 될 것이다.', `MaleText_loc4`='你也会成为巫妖王的仆从。', `MaleText_loc5`='你也將服侍巫妖王。', `MaleText_loc7`='Tú también servirás al Rey Exánime.' WHERE `ID`=23663;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='의식을 제대로 진행하려면 재료가 더 필요하지.', `MaleText_loc4`='我们的仪式能添上新的祭品啦。', `MaleText_loc5`='又有可以補充儀式的材料了。', `MaleText_loc7`='Más ingredientes para impulsar nuestros rituales aquí.' WHERE `ID`=23664;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 그래서 그가 말했지. "당연히 두 개로 보일 리가 없지! 난 눈알이 하나뿐이니까!"', `MaleText_loc4`='……因此他说“我只有一颗眼珠！当然不会重影！”', `MaleText_loc5`='...然後他說啦「我當然不會看見兩個你!我可只有一顆眼睛!」', `MaleText_loc7`='... y entonces va y dise "¡Claro que no veo doble! ¡Solo tengo un ojo!"', `FemaleText_loc1`='... 그러니 그가 이렇게 말하더군. "당연히 두 개로 보일 리가 없지! 난 눈알이 하나뿐이니까!"', `FemaleText_loc4`='……因此他说“我只有一颗眼珠！当然不会重影！”', `FemaleText_loc5`='...然後他說啦「我當然不會看見兩個你!我可只有一顆眼睛!」', `FemaleText_loc7`='... y entonces va y dise "¡Claro que no veo doble! ¡Solo tengo un ojo!"' WHERE `ID`=23665;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 와라, 조그만 녀석. 놀고 싶으냐?', `MaleText_loc4`='嗨，咱们来玩玩吧？', `MaleText_loc5`='嗨，小傢伙，來玩的嗎?', `MaleText_loc7`='Hola, peque. ¿Has venido a jugar?' WHERE `ID`=23666;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕께 생명을 바쳐라!', `MaleText_loc4`='你是为巫妖王而活的！', `MaleText_loc5`='你的生命是巫妖王的!', `MaleText_loc7`='¡Tu vida por el Rey Exánime!' WHERE `ID`=23667;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불가사의가 뭔지 네게 보여 주지.', `MaleText_loc4`='我会让你大吃一惊的。', `MaleText_loc5`='我有很多好東西要給你呢。', `MaleText_loc7`='Tengo tantas maravillas para mostrarte.' WHERE `ID`=23668;
