UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엿이나 먹으라고? 어디 엿이 있어야지...', `MaleText_loc4`='亲吻炮手的女儿？为什么我总是碰不到心仪的少女……', `MaleText_loc5`='要去親砲手的女兒?但我從來沒見過那女人...', `MaleText_loc7`='¿Tirarme a la borda? Pero si ni siquiera la conozco...', `FemaleText_loc1`='엿이나 먹으라고? 어디 엿이 있어야지...', `FemaleText_loc4`='亲吻炮手的女儿？为什么我总是碰不到心仪的少女……', `FemaleText_loc5`='要去親砲手的女兒?但我從來沒見過那女人...', `FemaleText_loc7`='¿Tirarme a la borda? Pero si ni siquiera la conozco...' WHERE `ID`=23670;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='테리가 그 그림 중 한 점을 천 골드에 팔았다고 들었는데 말이야. 나도 그 미술품 거래에 한 몫 거들어야겠어!', `MaleText_loc4`='听说泰里镶个画框就能赚1000金币。或许我也该考虑做工艺品生意！', `MaleText_loc5`='我聽說泰瑞銷贓他們的畫賺了幾千枚金幣耶。我想我也可以來點藝術品買賣!', `MaleText_loc7`='Oí que Terry consiguió mil oros traficando con uno d''esos cuadros. ¡A lo mejor yo también me puedo haser marchante de arte!', `FemaleText_loc1`='듣자하니 테리가 그 그림 중 한 점을 천 골드에 팔았다고 들었거든. 나도 그 미술품 거래에 동참해야겠는걸!', `FemaleText_loc4`='听说泰里镶个画框就能赚1000金币。或许我也该考虑做工艺品生意！', `FemaleText_loc5`='我聽說泰瑞銷贓他們的畫賺了幾千枚金幣耶。我想我也可以來點藝術品買賣!', `FemaleText_loc7`='Oí que Terry consiguió mil oros traficando con uno d''esos cuadros. ¡A lo mejor yo también me puedo haser marchante de arte!' WHERE `ID`=23671;
