UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 자네 친구인가, 그레직스? 이 친구, 전혀... 해적답지 않은데.', `MaleText_loc4`='格雷兹克斯，这是你朋友？$g他:她;不太像……海盗。', `MaleText_loc5`='格瑞希克斯，這是你朋友嗎?$g他:她;看起來不是很...海賊。', `MaleText_loc7`='¿$gEste:Esta; é tu consorte, Grezzix? No tiene mucha pinta de pirata...', `FemaleText_loc1`='이게 네 친구라고, 그레직스? 흠, 전혀... 해적같이 생기지 않았는데.', `FemaleText_loc4`='格雷兹克斯，这是你朋友？$g他:她;不太像……海盗。', `FemaleText_loc5`='格瑞希克斯，這是你朋友嗎?$g他:她;看起來不是很...海賊。', `FemaleText_loc7`='¿$gEste:Esta; é tu consorte, Grezzix? No tiene mucha pinta de pirata...' WHERE `ID`=23673;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 멋지군. 괜찮다면 한 잔 더 하고 싶은데. 같이 하겠소, $n?', `MaleText_loc4`='那些酒可棒啦。你不介意的话，我想回去喝几杯。你要一起来吗，$n？', `MaleText_loc5`='我確定他們人很好。如果不介意的話，我要帶些喝的回去。$n，你要一起來嗎?', `MaleText_loc7`='Estoy seguro de que están de ampanga. Si no te importa, debo seguir dándole al chispetrén. ¿Vienes tú, $n?', `FemaleText_loc1`='정말 멋진데, 뭐. 괜찮다면 한 잔 더 하고 싶은데. 같이 할래요, $n?', `FemaleText_loc4`='那些酒可棒啦。你不介意的话，我想回去喝几杯。你要一起来吗，$n？', `FemaleText_loc5`='我確定他們人很好。如果不介意的話，我要帶些喝的回去。$n，你要一起來嗎?', `FemaleText_loc7`='Estoy segura de que están de ampanga. Si no te importa, debo seguir dándole al chispetrén. ¿Vienes tú, $n?' WHERE `ID`=23674;
