UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무런 저항도 하지 않다니... 실망스럽군.', `MaleText_loc4`='真令我失望啊，竟然不做反抗。', `MaleText_loc5`='多讓人氣餒;毫無抵抗力。', `MaleText_loc7`='Qué decepción: nada de resistencia.' WHERE `ID`=23679;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 희생이 우리를 북돋우리라.', `MaleText_loc4`='你的牺牲会让我们获得更多力量。', `MaleText_loc5`='你的犧牲將會替我們的成果加速。', `MaleText_loc7`='Tu sacrificio impulsará nuestros esfuerzos.' WHERE `ID`=23680;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해적 야영지는 바로 코앞이야. 괜찮다면 난 좀 누워 있고 싶군. 머리가 아파 죽겠어.', `MaleText_loc4`='无赖港就在前面。如果你不介意的话，我要去躺会儿。我头痛得厉害。', `MaleText_loc5`='無賴角就在前方。如果你不介意的話，我想要躺下休息一下子。我的頭快痛死了。', `MaleText_loc7`='El Cabo Pillastre está justo ahí delante. Si no t''importa voy a tumbarme un momento. La cabesa me está matando, asere.', `FemaleText_loc1`='해적 야영지는 바로 코앞이야. 괜찮다면 난 좀 누워 있고 싶군. 머리가 아파 죽겠어.', `FemaleText_loc4`='无赖港就在前面。如果你不介意的话，我要去躺会儿。我头痛得厉害。', `FemaleText_loc5`='無賴角就在前方。如果你不介意的話，我想要躺下休息一下子。我的頭快痛死了。', `FemaleText_loc7`='El Cabo Pillastre está justo ahí delante. Si no t''importa voy a tumbarme un momento. La cabesa me está matando, asere.' WHERE `ID`=23681;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 그만 지껄여라.', `MaleText_loc4`='别喋喋不休。', `MaleText_loc5`='你不要再跟我磨牙了。', `MaleText_loc7`='Se acabó el parloteo para ti.' WHERE `ID`=23682;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='애타게 구조를 기다려도 결국 아무도 오지 않았지?', `MaleText_loc4`='你还指望谁来救你是吧？可是都没有人露面呢。', `MaleText_loc5`='我多想被救啊，但是沒有人來呀，對吧?', `MaleText_loc7`='Tanto esperar a que te rescaten... pero no ha venido nadie, ¿verdad?' WHERE `ID`=23683;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 음... "친구들!" 이 $g자:아가씨;가 내가 말했던 "내 친구"일세! 말 그대로 "바다의 공포"인 친구라네!', `MaleText_loc4`='喂，嗯……“伙计！”这就是我向你提过的家伙！$g他:她;可是真正的“海洋的霸主”！', `MaleText_loc5`='唷喝，嗯...「朋友」!這就是我跟你提過的$g小鬼:小妞;，「我的朋友」!$g他:她;是名符其實的「海上煞星」!', `MaleText_loc7`='¡Ah del balco, umm... "bucanero"! $gEste es el compay:Esta es la chama; $gdel que:de la que; te hablaba. ¡Es un auténtico "terror del mar"!' WHERE `ID`=23684;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네? 날아가고 싶다고요? 그... 그그그그그... 그렇겐 아... 아... 아아안 되죠!', `MaleText_loc4`='嗯？你想飞？不……这是不可能的！', `MaleText_loc5`='什麼?你想要飛?不行啊...不不不不，這不該發生的!', `MaleText_loc7`='¿Sip? ¿Quieres volar? Nop... ¡No-no-no de eso nada!' WHERE `ID`=23685;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탐험가 연맹의 공무를 수행 중입니다, 맥고이버. 탐험가 연맹 전초기지로 보내 주십시오!', `MaleText_loc4`='米克高维尔，我负责处理探险者协会的官方事宜。带我去探险者协会哨站！', `MaleText_loc5`='探險者協會公事喔，馬概先。帶我去探險者協會前哨吧!', `MaleText_loc7`='Asuntos oficiales de la Liga de Expedicionarios, McGoyver. ¡Llévame a la Avanzada de la Liga de Expedicionarios!', `FemaleText_loc1`='탐험가 연맹의 공무를 수행 중입니다, 맥고이버. 탐험가 연맹 전초기지로 보내 주세요!', `FemaleText_loc4`='米克高维尔，我负责处理探险者协会的官方事宜。带我去探险者协会哨站！', `FemaleText_loc5`='探險者協會公事喔，馬概先。帶我去探險者協會前哨吧!', `FemaleText_loc7`='Asuntos oficiales de la Liga de Expedicionarios, McGoyver. ¡Llévame a la Avanzada de la Liga de Expedicionarios!' WHERE `ID`=23686;
