UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저주받을 개구리 같으니! 그래, 난 예전에 남쪽바다 해적단의 일원이었어. 그게 뭐 어쨌다는 건가, 친구? 당장 절단을 내 주겠어!', `MaleText_loc4`='呸！是，我也是南海海盗的一员了——如果你想打什么鬼主意，就趁早死了这条心。信不信我现在就砍翻你！', `MaleText_loc5`='詛咒那隻青蛙!對啦，我加入了南海海賊團 - 你想威脅他們嗎，朋友?我現在就把你給砍了!', `MaleText_loc7`='¡Maldita rana! Sí, me uní a la tripulasión del Mar del Sur; ¿tienes algo que decir tú, $gcompadre:chama;? ¡Te rajaré aquí y ahora!' WHERE `ID`=23690;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요! 가을 축제에 오신 걸 환영합니다!', `MaleText_loc4`='嗨，欢迎来到美酒节！', `MaleText_loc5`='嗨你好，歡迎光臨啤酒節!', `MaleText_loc7`='¡Hola! Te doy la bienvenida a la Fiesta de la Cerveza.' WHERE `ID`=23691;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑습니다, 우리의 친구분! 가을 축제 광장에 오신 걸 환영합니다!', `MaleText_loc4`='你好，朋友！欢迎来到美酒节！', `MaleText_loc5`='哈囉，朋友!歡迎光臨啤酒節場地!', `MaleText_loc7`='¡Hola, colega! ¡Te doy la bienvenida a la zona de la Fiesta de la Cerveza!' WHERE `ID`=23692;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요, 거기 멋진 $c님! 아이언포지의 연례 행사, 가을 축제를 즐기세요!', `MaleText_loc4`='欢迎，$c！欢迎参加铁炉堡一年一度的美酒节庆典！', `MaleText_loc5`='歡迎，好心的$c!歡迎光臨鐵爐堡一年一次的啤酒節慶典!', `MaleText_loc7`='¡Saludos, amable $c! ¡Te doy la bienvenida a la Fiesta de la Cerveza anual de Forjaz!' WHERE `ID`=23693;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어리석은 것, 내가 하려는 일을 방해할 순 없다! 이제 최후를 맞으리라!', `MaleText_loc4`='傻瓜，你阻止不了我！受死吧！', `MaleText_loc5`='傻孩子，我的大業已經開始，你阻止不了的!去見你的末日吧!', `MaleText_loc7`='¡Insensata criaturita, no detendrás lo que he puesto en marcha! ¡Ahora, enfréntate a tu perdición!' WHERE `ID`=23694;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나를 상대하면 네 친구들을 구해낼 수 있다고, 진정으로 그렇게 생각하는 건가?', `MaleText_loc4`='你真的认为能击败我，救出你的朋友吗？', `MaleText_loc5`='你真的認為對抗我，可以有希望拯救你的朋友嗎?', `MaleText_loc7`='¿Realmente creías que enfrentándote a mí tendrías alguna posibilidad de salvar a tus amigos?' WHERE `ID`=23696;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 녀석, 아니 어떤 게 이런 짓을 한 거야?!', `MaleText_loc4`='谁会做出这样的事情？！', `MaleText_loc5`='到底是什麼人或什麼東西會做出這樣的事情，老兄?!', `MaleText_loc7`='¿Qué o quién haría algo así, tío?' WHERE `ID`=23697;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여어, 거기 있는 친구! 가을 축제에 오신 걸 환영합니다. 이리 와서 몇 잔 걸치세요!', `MaleText_loc4`='嗨，欢迎参加美酒节。过来喝上几杯吧！', `MaleText_loc5`='嗨你好，歡迎光臨啤酒節。進來喝幾杯吧!', `MaleText_loc7`='Hola, es agradable contar con tu presencia en la Fiesta de la Cerveza. ¡Entra y bebe una cerveza... o tres!' WHERE `ID`=23698;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놀라 자빠질 지경이군!', `MaleText_loc4`='我的脑子一片混沌！', `MaleText_loc5`='我想得頭都快炸了!', `MaleText_loc7`='¡Estoy ALUCINANDO!' WHERE `ID`=23699;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요즘 어때요, 친구? 가을 축제 광장에 오신 걸 환영합니다! 저쪽에서 마실 것을 팔고 있답니다!', `MaleText_loc4`='怎么了，朋友？欢迎来到美酒节！现在就去买些酒喝喝吧！', `MaleText_loc5`='最近怎樣啊，朋友?歡迎光臨啤酒節場地!去買點喝的吧!', `MaleText_loc7`='¿Qué tal, colega? ¡Te doy la bienvenida a la zona de la Fiesta de la Cerveza! ¡Ahora ve a por una bebida!' WHERE `ID`=23700;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야, 또 다른 $c님이시로군요! 함께 올해의 가을 축제를 축하합시다. 가서 마시고 즐기자고요!', `MaleText_loc4`='嗨，$c！欢迎来到美酒节庆典……现在尽情享受这里的美酒美食吧！', `MaleText_loc5`='嗨你好，是另外一個$c!歡迎光臨我一年一度的啤酒節慶典...現在就去好好享用食物及喝點什麼吧!', `MaleText_loc7`='¡Hey hey, es $gotro:otra; $c! Te doy la bienvenida a mi celebración anual de la Fiesta de la Cerveza... ¡Ahora bebe y disfruta!' WHERE `ID`=23701;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세상에나 마상에나 드워프의 양탄자에 이런 짓을 하다니! 어떻게 이럴 수가 있지!', `MaleText_loc4`='你是故意来毁坏矮人的地毯的吧！你怎么能这样！', `MaleText_loc5`='你不可以就這樣跑過來，對矮人的毯子做這種事!你就是不能這樣啦!', `MaleText_loc7`='¡No puedes llegar y hacer esto a la alfombra de un enano! ¡Estas cosas no se hacen!' WHERE `ID`=23702;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 고개를 젓습니다.', `FemaleText_loc4`='%s摇了摇头。', `FemaleText_loc5`='%s搖搖她的頭。', `FemaleText_loc7`='%s agita la cabeza.' WHERE `ID`=23703;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='녀석들이 그 양탄자에 무슨 짓을 한 건지...', `FemaleText_loc4`='他们竟然如此对待那条地毯，可耻！', `FemaleText_loc5`='真是無恥，他們竟然對那條毯子做出這種事情。', `FemaleText_loc7`='Una vergüenza lo que le han hecho a esa alfombra.' WHERE `ID`=23704;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하하하! 절대로 내 망원경을 얻을 수 없을 거다, 더러운 녀석!', `MaleText_loc4`='呀啊啊啊！别想得到我的望远镜，你这只配滚去舱底喝污水的蠢货！', `MaleText_loc5`='呀啊啊啊!混帳，你別想拿到我的望遠鏡!', `MaleText_loc7`='¡Arrrrrrr! ¡Nunca pillaréis mi catalejo, ratas de mar!' WHERE `ID`=23705;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호저, 불쌍한 녀석! 아빠다!', `MaleText_loc4`='霍泽，宝贝！爸爸来啦！', `MaleText_loc5`='哈瑟，老傢伙!你老爸來囉!', `MaleText_loc7`='¡Hozzer, chico grande! ¡Aquí viene papá!' WHERE `ID`=23706;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='니들마이어, 누가 저런 짓을 했다고 생각해?', `MaleText_loc4`='尼德梅尔，你觉得是谁干的呢？', `MaleText_loc5`='尼朵麥爾，你覺得是誰幹的?', `MaleText_loc7`='¿Quién crees que lo ha hecho, Gujameyer?' WHERE `ID`=23707;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생각할 것도 없지, 와드! 난 누가 저런 괘씸한 짓을 했는지 알아!', `MaleText_loc4`='还用想吗？我知道是谁，也只有他们能做出这样的龌龊事！', `MaleText_loc5`='我沒在想是誰，華德!我知道是誰會做出這種可惡的事情!', `MaleText_loc7`='¡No creo nada, Wad! ¡Sé perfectamente quién cometería semejante atrocidad!' WHERE `ID`=23708;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이리 오렴, 날쌘부리야. 저쪽을 정찰하러 가자.', `FemaleText_loc4`='来，谷迪，我们去探险吧。', `FemaleText_loc5`='來吧，古迪，我們去搜索這個區域。', `FemaleText_loc7`='Vamos Gudi, exploremos la zona.' WHERE `ID`=23709;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빌어먹을 쇳덩어리 사촌들이 한 짓이라고! 확실해!', `MaleText_loc4`='肯定是那些混蛋铁矮人表亲！肯定是！', `MaleText_loc5`='那一定是我們的可惡鐵族親戚!一定是!', `MaleText_loc7`='¡Han sido nuestros primos férreos! ¡Seguro!' WHERE `ID`=23710;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전혀 그 친구들 짓 같지 않은데, 형제.', `MaleText_loc4`='不可能吧。', `MaleText_loc5`='兄弟，這不太可能吧。', `MaleText_loc7`='Eso es muy poco probable, hermano.' WHERE `ID`=23711;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='윌리엄, 산마루에 신선한 약초가 자란 걸 봤어요. 채집해 올 수 있는지 베카나한테 물어봐 주실래요?', `FemaleText_loc4`='威廉，山脊上长着一丛新鲜的草药。叫贝卡娜来采一下吧。', `FemaleText_loc5`='威廉，我看到一種新的藥草生長在山脊那。去叫貝肯娜去採回來。', `FemaleText_loc7`='William, he visto un crecimiento de hierbas en la cresta. Pídele a Becanna que las recoja.' WHERE `ID`=23712;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 친구들 짓이 아니라고?! 왜 그렇게 생각하는지 말해 봐, 형제. 난 직감으로 알 수 있다고!', `MaleText_loc4`='你不信！？兄弟，我打赌一定是他们！你为什么不相信我？', `MaleText_loc5`='不可能，是嗎!?那你告訴我為什麼你會這麼想啊，兄弟，我可是打從骨子裡知道我是對的!', `MaleText_loc7`='Poco probable, ¿eh? ¡Cómo puedes pensar eso cuando yo estoy segurísimo de que es cierto!' WHERE `ID`=23713;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 친구들은 쇠로 만들어졌으니까 그렇지, 이 멍청이야! 이해력은 나랑 달리 아버지한테서 전혀 물려받질 못했군. 내가 장담한다니까!', `MaleText_loc4`='因为他们是铁制的啊，你这个大笨蛋！看来你一点都没有继承爸爸的聪明才智！', `MaleText_loc5`='因為他們是鐵做的啊，白痴!你一點也沒遺傳到老爹留給我的判斷力 - 這點我很確定!', `MaleText_loc7`='¡Porque están hechos de hierro tontorrón! No tienes ninguno de los sentidos que yo heredé de papi, eso seguro.' WHERE `ID`=23714;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래! 그거야! 넌 어떻게 만날 그러냐! 꼭 그렇게 아버지를 들먹여야겠냐! 일어나! 나랑 한 판 붙자! 괜히 앉아서 얻어맞고 나중에 딴소리 말고!', `MaleText_loc4`='够了！别说了！兄弟，我受够你了！干嘛提到爸爸！起来！我要跟你决斗！别坐在那儿挨打，不然待会又要听你抱怨了！', `MaleText_loc5`='夠了!夠了!兄弟，我受夠你了!你就是要把老爸扯進來，是嗎!起來打架啊!我可不要因為你坐著的時候動手，然後聽你抱怨不公平!', `MaleText_loc7`='¡Se acabó! ¡Se acabó! ¡Ya me he hartado de ti, hermano! Tenias que hablar de papi, ¿verdad? ¡Levántate y lucha! ¡No quiero patearte mientras estás sentado y luego aguantar tus lloriqueos!' WHERE `ID`=23715;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좀 진정하지 못하겠냐! 쓸데없는 일로 성질 부리지 말란 말이야! 지난번에 무슨 일이 있었는지 기억 안 나? 좀 앉으라고!', `MaleText_loc4`='你冷静点！无缘无故地发什么脾气呀！还记得上次你乱撒气的后果吗？坐下啦！', `MaleText_loc5`='別激動，可以嘛!不用為了這麼一點雞毛蒜皮的事情鬧翻吧!還記得上回發生什麼事情嗎?現在給我坐下!', `MaleText_loc7`='¡Cálmate! ¡No hay que ponerse así por nada! ¿Recuerdas lo que pasó la última vez? ¡Ahora siéntate!' WHERE `ID`=23716;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 조용하게 투덜거립니다.', `MaleText_loc4`='%s嘟囔着。', `MaleText_loc5`='%s在嘴裡咕噥說著什麼。', `MaleText_loc7`='%s refunfuña entre dientes.' WHERE `ID`=23717;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어서요. 가서 물어보세요.', `FemaleText_loc4`='拜托，叫她来呀。', `FemaleText_loc5`='來吧，動手吧。', `FemaleText_loc7`='Vamos, tan solo hazlo.' WHERE `ID`=23718;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐라고요? 왜 저더러 물어보라는 겁니까?', `MaleText_loc4`='什么？为什么要我去？', `MaleText_loc5`='什麼?為什麼你要我來動手?', `MaleText_loc7`='¿Qué? ¿Por qué quieres que lo haga?' WHERE `ID`=23719;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알았습니다. 말해볼게요.', `MaleText_loc4`='好吧，我去叫她。', `MaleText_loc5`='好，我會告訴她。', `MaleText_loc7`='Vale, se lo diré.' WHERE `ID`=23720;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 숨을 깊게 들이마십니다.', `MaleText_loc4`='%s深深地吸了一口气。', `MaleText_loc5`='%s深深地吸了一口氣。', `MaleText_loc7`='%s respira hondo.' WHERE `ID`=23721;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어라, 보통 여기 있었는데...', `MaleText_loc4`='奇怪，她通常都待在这儿的……', `MaleText_loc5`='真怪，她通常都在這裡的...', `MaleText_loc7`='Extraño... normalmente está aquí...' WHERE `ID`=23722;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕, 어, 베카나, 뭐냐하면... 아, 엘레나가 약초를 찾았답니다! 좀 가져다 줄 수 있을까요?', `MaleText_loc4`='嗨，贝卡娜，我……嗯，艾蕾娜发现了一丛草药！你能去采一下吗？', `MaleText_loc5`='嗨，嗯，貝肯娜，我的意思是說...呃，伊蘭娜發現了一些藥草!你能去拔回來嗎?', `MaleText_loc7`='Hola, ehm, Becanna, quiero decir... ehm, Elenna ha encontrado algunas hierbas. ¿Puedes ir a recogerlas?' WHERE `ID`=23723;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고마워요! 혹시, 어, 도움이 필요하면 와서 절 부르세요... 정말입니다. 제가 필요하면 도와 드리겠습니다!', `MaleText_loc4`='谢谢！如果你……嗯，需要帮助的话就来采我……啊，我是说，就来找我，我很乐意帮忙的！', `MaleText_loc5`='謝了!如果你呃，需要任何幫助的話，就來拔我...我是說，來找我，我會幫忙的!', `MaleText_loc7`='¡Gracias! Si necesitas ayuda ven a recogerme...estoooo...ven a buscarme y te ayudaré.' WHERE `ID`=23725;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 약간 얼굴을 붉히고 걸어갑니다.', `MaleText_loc4`='%s红着脸走开了。', `MaleText_loc5`='%s微微臉紅的走開。', `MaleText_loc7`='%s se sonroja y se marcha.' WHERE `ID`=23726;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='와, 이 사과 정말 맛있네요!', `FemaleText_loc4`='啊，这些苹果实在太可口了！', `FemaleText_loc5`='喔，這些蘋果真是美味!', `FemaleText_loc7`='¡Oh, estas manzanas son realmente deliciosas!' WHERE `ID`=23727;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 오빠한테도 꼭 먹어 보라고 해야겠어요.', `FemaleText_loc4`='我的弟弟肯定想尝尝的。', `FemaleText_loc5`='我的兄弟真的要試試這些。', `FemaleText_loc7`='Mi hermano tiene que probarlas.' WHERE `ID`=23728;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙지만, 지금은 별로 배가 고프지 않아.', `MaleText_loc4`='谢谢你，但我现在并不是很饿。', `MaleText_loc5`='謝了，不過我現在不是那麼餓。', `MaleText_loc7`='Gracias, pero ahora mismo no tengo mucha hambre.' WHERE `ID`=23729;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕, 윌리엄! 무슨 일이지요?', `FemaleText_loc4`='嗨，威廉，什么事？', `FemaleText_loc5`='嗨，威廉，什麼事?', `FemaleText_loc7`='Hola, William. ¿Qué hay?' WHERE `ID`=23730;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오, 고마워요! 곧 가서 가져올게요.', `FemaleText_loc4`='啊，谢谢你！我一会就去。', `FemaleText_loc5`='哎呀，謝謝你!我一定會快點去拿的。', `FemaleText_loc7`='¡Ah, gracias! Me aseguraré de ir a cogerlas pronto.' WHERE `ID`=23731;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='별말씀을요, 혼자서도 충분해요. 고마워요.', `FemaleText_loc4`='不用，我自己能搞定。谢谢你。', `FemaleText_loc5`='吶，我可以處理的。謝了。', `FemaleText_loc7`='Nah, puedo encargarme yo. Gracias.' WHERE `ID`=23732;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이번엔 같이 가자고 부탁하는 게 낫겠어. 또 늑대한테 공격받기는 싫으니까.', `FemaleText_loc4`='我最好在采集草药之前问清楚状况。我可不想再次被狼袭击。', `FemaleText_loc5`='這次我最好先問過再去拔草。我可不想被另一隻狼攻擊。', `FemaleText_loc7`='Será mejor que pregunte antes de ir coger hierbas esta vez. No quiero que me ataque otro lobo.' WHERE `ID`=23733;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='윌리엄은 정말 웃겨요. 툭하면 얼굴이 빨개진다니까요.', `FemaleText_loc4`='威廉真有趣。他常常脸红。', `FemaleText_loc5`='那個威廉很有趣。他的臉總是一直在變紅。', `FemaleText_loc7`='Ese William es tan gracioso... Siempre se sonroja.' WHERE `ID`=23734;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='얼라이언스의 고귀한 전사님이 그럴 리가 없잖아요. 참! 엘레나가 약초를 찾았대요. 가서 가져올게요.', `FemaleText_loc4`='我相信，高贵的联盟士兵心里肯定惦念着其它更重要的事情。噢！艾蕾娜发现了一些草药，我去帮她采一下。', `FemaleText_loc5`='我相信一位聯盟的高等士兵會有更好的想法。喔!伊蘭娜發現了一些藥草，所以我要去將它們拔回來。', `FemaleText_loc7`='Estoy segura de que un noble soldado de la Alianza tiene cosas mejores en las que pensar. ¡Oh! Elenna ha encontrado algunas hierbas, así que voy a recogerlas.' WHERE `ID`=23735;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 약초를 근처에 옮겨 심습니다.', `FemaleText_loc4`='%s将草药种植在附近。', `FemaleText_loc5`='%s移植附近的藥草。', `FemaleText_loc7`='%s vuelve a plantar las hierbas cerca.' WHERE `ID`=23736;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='흠... 그럼 조심하는 게 좋을걸. 그 사람 너한테 반한 걸지도 모르잖니. 난 그 사람 여동생도 왠지 믿음이 안 가더구나...', `FemaleText_loc4`='嗯……好吧，小心点，他可能爱上你了。我也不太相信他那个姐姐……', `FemaleText_loc5`='嗯嗯...好吧，小心點，他可能對你有意思。我也不信任他那個姐妹...', `FemaleText_loc7`='Hmm... Bueno, ten cuidado, puede que se ponga un poco pesado. Yo tampoco me fío de su hermana...' WHERE `ID`=23737;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그래, 베카. 정원에 있는 덤불 옆에 놔두렴. 늑대 조심하고!', `FemaleText_loc4`='好吧，贝卡，把它们放在树丛旁的花园里就行了。要小心狼！', `FemaleText_loc5`='很好，貝肯娜，就把它們留在園子裡的灌木叢旁吧。當心狼群喔!', `FemaleText_loc7`='Vale, Becca, déjalas en el jardín junto al arbusto. ¡Ten cuidado con los lobos!' WHERE `ID`=23738;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음... 아, 제가 검은바위 산 심장부 깊숙이 탐험했던 이야기 해 드렸던가요?', `MaleText_loc4`='……我告诉过你那时候我深入黑石山的中心地带探险的事吗？', `MaleText_loc5`='...還有，我有跟你說過那次我深入黑石山中心冒險的事嗎?', `MaleText_loc7`='¿...y te he hablado de cuando me aventuré en el corazón de la Montaña Roca Negra?' WHERE `ID`=23739;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그건 제가 오크를 한 방에 무찌르고 이 어깨덮개를 벗겨 냈을 때였지요.', `MaleText_loc4`='那时，我就这么用力一砍杀死了那兽人，然后拿走了这副肩甲。', `MaleText_loc5`='就是那時候我一刀殺了這個獸人然後拿走了這些肩甲。', `MaleText_loc7`='Fue entonces cuando maté al orco con un gran tajo y me llevé todas estas bufas.' WHERE `ID`=23740;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='굉장히 튼튼한 도끼를 거기에서 하나 찾아냈거든요, 막 벼려낸 놈으로 말이지요.', `MaleText_loc4`='我在那里发现了一把锋利的斧子，一把刚从烈火中铸造出来的利斧。', `MaleText_loc5`='我在那發現了一把剛自火中鍛造出來的巨大斧頭。', `MaleText_loc7`='Encontré una poderosa hacha allí, recién forjada en el fuego.' WHERE `ID`=23741;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기에서, 이 가슴보호갑을 제 손으로 만들어 냈죠, 몇 시간 동안이나 용광로에서 씨름하면서요.', `MaleText_loc4`='我亲手在熔炉旁辛勤地铸造了几个小时，终于铸成了这件胸甲。', `MaleText_loc5`='在那，我在鍛爐中努力了許久，親手打造了這個胸甲。', `MaleText_loc7`='Allí elaboré este peto con mis propias manos, trabajando duro durante horas en la forja.' WHERE `ID`=23742;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='트롤 녀석 주머니 깊숙이 근사한 보석이 하나 있더군요, 그래서 짭짤한 가격을 받고 팔아버렸죠!', `MaleText_loc4`='我在一个巨魔的口袋里找到了一颗漂亮的宝石，虽说不是什么八心八箭，但是我把它卖了个不错的价钱！', `MaleText_loc5`='那裡，在一個食人妖口袋的深處就是這顆美麗的寶石，我將它賣了個漂亮的價格!', `MaleText_loc7`='¡Allí, en el fondo del bolsillo de un trol encontré la preciosa gema que vendí a muy buen precio!' WHERE `ID`=23743;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='.. 멋지게 한 방 날려, 멀록을 처치했죠, 차갑고 끈적끈적한 손에서 수정구를 떨어뜨리더군요!', `MaleText_loc4`='……我就这么用力一拳，打倒了那个鱼人，从它那又冰凉又粘稠的手中拿到了这颗宝珠！', `MaleText_loc5`='..伴隨一次巨大的爆炸，我殺了一隻魚人，從他冰冷，黏滑的手中釋放了這顆寶珠!', `MaleText_loc7`='¡...de un potente golpe maté a un múrloc, liberando el orbe de sus frías y viscosas manos!' WHERE `ID`=23744;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 제가 줄아만 숲 깊숙한 곳까지 탐험했던 그 시절을 잊지 않으려는 것 뿐입니다.', `MaleText_loc4`='……我不会忘记去祖阿曼森林深处冒险的那段时光。', `MaleText_loc5`='...不要忘記那次我冒險深入祖阿曼叢森林內。', `MaleText_loc7`='... no hay que olvidar la ocasión en que me aventuré en las profundidades de los bosques de Zul''Aman.' WHERE `ID`=23745;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 저희는 끝없이 밀려오는 실리시드와 싸웠고 실리더스에 있는 뜨거운 모래는 제 얼굴을 불태웠지요.', `MaleText_loc4`='……当我们在希利苏斯与一波波的异种虫作战时，燃烧的砂粒灼烧着我的脸。', `MaleText_loc5`='...希利蘇斯火熱的沙礫在我們與一波又一波的異種交戰時灼痛我的臉頰。', `MaleText_loc7`='...la ardiente arena de Silithus agostada mi cara mientras nos enfrentábamos a las interminables oleadas de silítidos.' WHERE `ID`=23746;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 그 도시는 불타서 예전의 모습이라고는 찾아볼 수 없는 검게 그을린 폐허가 되어버렸죠. 한 때는 인간이 살던 곳이었는데 언데드 군대가 봉기했습니다.', `MaleText_loc4`='……整座城市都被烧毁了，只留下了一片烧焦的废墟。人们倒下，当他们重新站起来的时候，就变成了亡灵的军团。', `MaleText_loc5`='...城市燒燬了，無論它曾經是怎樣，現在都是一個燒焦的廢墟。不死軍團發跡於人類曾經居住的地方。', `MaleText_loc7`='...la ciudad estaba quemada, no quedaba más que una ruina agostada. Los ejércitos de no-muertos se alzaban donde antes vivía gente.' WHERE `ID`=23747;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 제가 저 멀리 혈투의 전장까지 탐험했던 얘기는 해드렸던가요?', `MaleText_loc4`='……我有没有跟你说过我到厄运之槌深处探险的事？', `MaleText_loc5`='...我有跟你說過那時我在厄運之槌的深入探險嗎?', `MaleText_loc7`='¿...te he hablado de cuando exploré la frontera lejana de La Masacre?' WHERE `ID`=23748;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 한숨짓습니다...', `MaleText_loc4`='%s叹了口气……', `MaleText_loc5`='%s嘆息...', `MaleText_loc7`='%s suspira...' WHERE `ID`=23749;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 말없이 고개만 끄덕입니다...', `MaleText_loc4`='%s默默地点了点头……', `MaleText_loc5`='%s默默的點了點頭...', `MaleText_loc7`='%s asiente en silencio...' WHERE `ID`=23750;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 건성으로 얘기를 듣습니다...', `MaleText_loc4`='%s不耐烦地听着……', `MaleText_loc5`='%s不耐煩的聽著...', `MaleText_loc7`='%s escucha con impaciencia...' WHERE `ID`=23751;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벡살루스가 순수한 힘을 방출합니다!', `MaleText_loc4`='维萨鲁斯放射出纯净的能量！', `MaleText_loc5`='維克索魯斯發出純淨能量!', `MaleText_loc7`='¡Vexallus libera energía pura!' WHERE `ID`=23752;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 근처의 지옥 수정에서 힘을 끌어냅니다. 수정을 파괴하십시오!', `MaleText_loc4`='%s开始吸取附近邪能水晶的能量。快摧毁它！', `MaleText_loc5`='%s開始從附近的惡魔水晶進行導引，快摧毀它!', `MaleText_loc7`='%s comienza a canalizar el cristal vil cercano. ¡Destrúyelo!' WHERE `ID`=23753;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='환영합니다, 친구! 가을 축제 광장에 잘 오셨습니다! 가을 축제엔 즐길 거리가 아주 많지요. 양조장끼리 경쟁하는 걸 지켜보는 것도 재미있답니다. 궁금하신 게 있으면 언제든 절 찾으세요!', `MaleText_loc4`='欢迎来到美酒节，朋友！在赞美那些相互对抗的酿酒厂之间的友好竞争精神时，我们可以得到很多乐趣。如果你有任何疑问，找我就是了！', `MaleText_loc5`='歡迎光臨啤酒節場地，朋友!當我們在慶祝釀酒場對手間友善競賽的精神時，這裡還有許多東西可以好好享用。如果你有任何疑問的話，請告訴我!', `MaleText_loc7`='¡Te doy la bienvenida a la zona de la Fiesta de la Cerveza, colega! Hay mucho de lo que disfrutar aquí mientras celebramos el espíritu de la competición amistosa entre destilerías rivales. ¡Avísame si tienes alguna pregunta!' WHERE `ID`=23754;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='식당가', `MaleText_loc4`='食物和饮料', `MaleText_loc5`='食物和飲料', `MaleText_loc7`='Comida y bebida', `FemaleText_loc1`='식당가', `FemaleText_loc4`='食物和饮料', `FemaleText_loc5`='食物和飲料', `FemaleText_loc7`='Comida y bebida' WHERE `ID`=23755;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='교환 동전과 기념품', `MaleText_loc4`='奖币和纪念品', `MaleText_loc5`='獎品章和紀念品', `MaleText_loc7`='Fichas y souvenirs', `FemaleText_loc1`='교환 동전과 기념품', `FemaleText_loc4`='奖币和纪念品', `FemaleText_loc5`='獎品章和紀念品', `FemaleText_loc7`='Fichas y souvenirs' WHERE `ID`=23756;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='산양 경주장', `MaleText_loc4`='赛羊', `MaleText_loc5`='山羊競速', `MaleText_loc7`='Montar en carnero', `FemaleText_loc1`='산양 경주장', `FemaleText_loc4`='赛羊', `FemaleText_loc5`='山羊競速', `FemaleText_loc7`='Montar en carnero' WHERE `ID`=23757;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑소, $r. 나는 사냥의 달인이자 세계 최고의 매부리인 히달고라고 하오. 내 어깨에 앉은 이 무시무시한 녀석은 엑셀시어요.$B$B"매부리가 대체 뭘 하는 사람이지?"라고 생각할지 모르겠는데, 내가 알려주지. 바로 사냥을 하는 사람이지! 매부리란 맹금류를 이용해서 사냥감을 잡는 자를 일컫는다오. 길들인 맹금으로 사냥해 보고 싶소? 그렇다면 이 히달고가 가르쳐 주겠소!', `MaleText_loc4`='你好，$r。我是希达尔格，擅长狩猎，算得上是一流的驯鹰大师。停在我肩膀上的就是杀人机器木丝了。$B$B你可能会想，“驯鹰师是干什么的呢？”我来告诉你——我们是优秀的猎手！训鹰术是一门利用经过特殊训练的猛禽来狩猎的艺术。你对此感兴趣吗？希达尔格可以教你！', `MaleText_loc5`='你好，$r，我是海達戈，我是狩獵大師，世界級的馴鷹者。你見到停在我肩上的殺人機器正是伊克賽西爾。$B$B你也許會納悶，「馴鷹人到底是做什麼的?」嗯，我來告訴你我們做些什麼 - 我們狩獵!「馴鷹」是一種利用鳥兒獵殺並捕捉獵物的一種藝術。你也許對學習利用一頭訓練過的猛禽狩獵感興趣?海達戈可以教你!', `MaleText_loc7`='Saludos, $r. Soy Hidalgo, maestro de la caza y uno de los mejores halconeros del mundo. Esta máquina de matar que ves posada sobre mi hombro es Excelsior.$B$BPuede que estés pensando: "¿Qué diablos hace un halconero?" Yo te lo diré: ¡cazamos! La halconería es el arte de usar un ave rapaz para cazar y recoger la presa. ¿Quizá te interese aprender a cazar con un ave entrenada? ¡Hidalgo puede enseñarte!' WHERE `ID`=23758;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가을 축제는 최고의 먹을 거리와 마실 거리를 모두 즐길 기회랍니다. 뜬금없는 소리 아니라니까요! 기분을 상쾌하게 만드는 수제 맥주와 소시지, 프렛첼이 다양하게 갖춰져 있으니 그저 슬쩍 한번 둘러라도 보시기 바랍니다. 이보다 더 좋은 건 없을 걸요. 게다가 작은 동전 하나면 다 됩니다요!', `MaleText_loc4`='美酒节就是个享受这个世界中最好的食物和美酒的盛典，一点都不夸张。过来看看这么多清爽的手工啤酒、节日香肠、椒盐卷饼和奶酪。还有什么比这更好的呢？而且你只需要花那么一丁点钱。', `MaleText_loc5`='啤酒節就是好好地在各大陸中享用美食及美酒，而且那一點都不誇大!只要看一眼手邊這些令人精神振奮的手工啤酒及節日香腸，鹹脆餅，以及起司。你將找不到更好的東西，而且只需要如此低廉的花費!', `MaleText_loc7`='La Fiesta de la Cerveza consiste en disfrutar de la mejor comida y bebida de la zona ¡y no exagero! Prueba las cervezas caseras vigorizantes, las salchichas, los pretzels y los quesos. ¡No encontrarás nada tan bueno por tan poco dinero!' WHERE `ID`=23759;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가을 축제에서 맥주와 소시지 다음으로 인기 있는 거라면 단연 기념품입죠! 전통 축제 의상부터 맛난 맥주가 담긴 꼬마 술잔까지, 갖가지 가을 축제 관련 상품을 벨비 퀵스위치에게서 구입하실 수 있답니다. 가을 축제 상품 교환 동전만 넉넉히 챙겨오세요. 그래야 물건을 사실 수 있으니까요! 가을 축제 광장 주변에서 도움의 손길을 뻗으시면 교환 동전을 얻으실 수 있습니다.', `MaleText_loc4`='除了啤酒和香肠，美酒节最受欢迎的就是纪念品了！不管是传统节日的服装，还是美酒的袖珍酒桶，一切应有尽有，你可以在贝尔比这里买到各种美酒节的主题物品。记得你手上要有足够多的美酒节奖币，因为你只能用它们来购买纪念品。你可以通过在美酒节的场地附近帮忙来获取奖币。', `MaleText_loc5`='僅次於啤酒與香腸，啤酒節中最受歡迎的部分就是紀念品!從傳統節日服裝至美味啤酒的迷你桶，所有啤酒節的主題商品都可從貝爾碧·迅移那找到。只要確認手中擁有大量的啤酒節獎品章，因為這是唯一可以購買紀念品的方式!你可以在啤酒節場地附近幫忙來掙得啤酒節獎品章。', `MaleText_loc7`='Después de la cerveza y las salchichas, la parte más popular de la Fiesta de la Cerveza son los souvenirs. Desde las vestimentas tradicionales hasta mini-barriles de sabrosa cerveza, Belbi Tiratrastos tiene toda clase de objetos basados en la Fiesta de la Cerveza. ¡Pero asegúrate de que tienes suficientes fichas de la Fiesta de la Cerveza, ya que es la única forma de comprarlos! Puedes conseguir fichas ayudando en la zona de la Fiesta.' WHERE `ID`=23760;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불의 세례를 받아라! 무슨 일이냐?', `MaleText_loc4`='让火焰净化一切吧！嗨，怎么了？', `MaleText_loc5`='讓火焰淨化一切!嘿，你好嗎?', `MaleText_loc7`='¡SED PURGADOS POR EL FUEGO! Hey, ¿qué hay?' WHERE `ID`=23761;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='산양 경주는 가을 축제의 멋진 전통 행사랍니다. 더 자세히 알고 싶다면 산양 우리 옆에 서 있는 폴 앰버스틸과 얘기해 보시죠. 흥겨운 시간이 되실 겁니다. 게다가 말입니다, 산양 경주는 가을 축제 상품 교환 동전을 구할 수 있는 절호의 기회거든요!', `MaleText_loc4`='赛羊会是美酒节的一个重要传统节目。如果你想知道更多的信息，就去和羊圈旁的波尔·冻石谈谈。而且那也是获取美酒节奖币的好方法！', `MaleText_loc5`='山羊競速是啤酒節偉大傳統之一。如果你想要了解更多的話，去與後面山羊獸欄的保爾·安伯斯堤爾談談。那是個正確的，「並且」會是個獲得啤酒節獎品章的絕佳方式!', `MaleText_loc7`='Las carreras de carneros son una de las grandes tradiciones de la Fiesta de la Cerveza. Si quieres más información, habla con Pol Semperámbar junto al establo de carneros. ¡Es muy divertido y puede ser una buena manera de conseguir fichas para la Fiesta de la Cerveza!' WHERE `ID`=23762;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까. 가을 축제에 오신 것을 환영합니다! 머리가 뒤죽박죽으로 복잡해질 만큼 즐길 거리가 너무 많아서 궁금한 점이 생겼다면, 저에게 말씀하세요. 질문할 게 없는 분들은 가서 맥주와 프렛첼이나 사드세요!', `MaleText_loc4`='嗨，欢迎来到美酒节！在这里你可以享受各种乐趣，如果你有任何问题的话，随时可以过来问我。不然，就去买些啤酒和椒盐卷饼吧！', `MaleText_loc5`='嗨你好，歡迎光臨啤酒節!在那裡有一堆方式能讓你盡興，所以你要是有什麼問題呢，你就告訴我。除此之外，去買幾瓶啤酒跟一包鹹脆餅吧!', `MaleText_loc7`='¡Hola, te doy la bienvenida a la Fiesta de la Cerveza! Hay muchas formas de divertirse aquí, así que si tienes alguna pregunta, avísame. Si no, ve a comprar una cerveza y un pretzel.' WHERE `ID`=23763;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가을 축제라면 무조건 맥주와 먹을 거리들이죠, 게다가 저희가 만드는 음식보다 더 좋은 건 없답니다. 제 말이 거짓말 같죠? 저희의 맛좋은 맥주와 소시지, 프렛첼과 치즈를 한번 드셔보세요. 깜짝 놀라실 겁니다. 근방에서 만날 수 있는 최고의 음식인데다 가격도 이보다 더 쌀 수는 없으니까요!', `MaleText_loc4`='美酒节的意义就在于美食和美酒，而且我们所提供的就是最好的！你觉得我在撒谎？看看我们的那些美酒、香肠、椒盐卷饼和奶酪吧。你会发现，你周围都是最棒的美食，而且你找不到比这更便宜的了！', `MaleText_loc5`='啤酒節全都是啤酒及食物，且不會有其他比我們端上的菜色更好了。懷疑我在騙人嗎?只要看看我們這些美味的啤酒、香腸、鹹脆餅以及起司。你將會知道:這是附近最好的食物，而且找不到更便宜的了!', `MaleText_loc7`='La comida y la bebida lo son todo en la Fiesta de la Cerveza y no hay nada mejor que lo que estamos sirviendo. ¿Crees que miento? Prueba las sabrosas cervezas, salchichas, galletas saladas y los quesos que tenemos. Ya lo verás: ¡lo mejor y lo más barato!' WHERE `ID`=23764;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끝내주는 가을 축제 산양 경주는 모두 다 좋아하는 것이죠. 더 자세히 알고 싶으신가요? 산양 우리 옆에 있는 드리즈 텀블퀵에게 가보세요. 즐거움을 만끽하세요. 그리고 산양 경주를 즐기면서 가을 축제 상품 교환 동전도 타세요!', `MaleText_loc4`='每个人都喜欢那些疯狂的美酒节赛羊。想要了解更多信息吗？去和羊圈旁的德利兹·塔波奎克谈谈吧。享受一点乐趣，并获取一些美酒节奖币！', `MaleText_loc5`='每個人都愛死了那些瘋狂的啤酒節競速山羊了。想要了解更多嗎?去跟後面山羊獸欄的德瑞茲·迅跌談談。祝你玩得開心，並贏取一些啤酒節獎品章!', `MaleText_loc7`='A todo el mundo le gustan esos carneros de carreras de la Fiesta de la Cerveza. ¿Quieres saber más? Habla con Driz Pataplaf abajo en el establo de carneros. Pásalo pipa y gana algunas fichas para la Fiesta de la Cerveza.' WHERE `ID`=23765;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐요 이봐, 잊지 말고 가을 축제 기념품 챙기세요! 전통 축제 의상에서 시원한 맥주가 담긴 꼬마 술잔까지 뭐든지 있습니다. 블릭스 픽스위젯과 얘기만 하면 다 되는데, 그 대신 가을 축제 상품 교환 동전은 잔뜩 가지고 있어야 합니다... 그래야 기념품을 구입할 수 있으니까요! 가을 축제 광장 주변에서 이것저것 돕다 보면 동전을 얻게 되실 겁니다.', `MaleText_loc4`='嗨，记得给你自己弄些美酒节的纪念品！不管是传统节日的服装还是美酒的袖珍酒桶，应有尽有。只要去找布利克斯·菲克维特就行了，但是首先请确保你手上有着足够的美酒节奖券……因为你只能用它们来购买纪念品。你可以通过在美酒节的场地附近帮忙以获取奖券。', `MaleText_loc5`='嗨嗨，別忘了幫你自己搶一些啤酒節紀念品!我們有各式各樣的東西，從傳統節日服裝到滿載美味啤酒的迷你桶都有。只要去跟布力克斯·修械談談，不過得確認一下你手上有夠多的啤酒節獎品章...這是購買紀念品的唯一方式!你可以在啤酒節場地附近幫忙來掙得啤酒節獎品章。', `MaleText_loc7`='¡Oye, no te olvides de llevarte algún souvenir de la Fiesta de la Cerveza! Tenemos de todo: desde las vestimentas tradicionales hasta mini-barriles de sabrosa cerveza. Habla con Blix Chirimbolo, pero asegúrate de que tienes suficientes fichas de la Fiesta de la Cerveza... ¡es la única manera de comprarlos! Puedes conseguir fichas ayudando en la zona de la Fiesta.' WHERE `ID`=23766;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='반갑습니다, 엘룬의 빛이 그대와 함께하시길...', `FemaleText_loc4`='你好，愿艾露恩之光与你同在。', `FemaleText_loc5`='你好，願伊露恩之光保佑你。', `FemaleText_loc7`='Saludos, la Luz de Elune te acompaña.' WHERE `ID`=23767;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알리시아가 쓴 시를 한 번 더 읽어주시겠습니까?', `MaleText_loc4`='你能再为我读一次奥利卡的诗吗？', `MaleText_loc5`='你能夠再唸一次艾利西亞之詩給我聽嗎?', `MaleText_loc7`='¿Puedes volver a leerme el poema de Alicia?', `FemaleText_loc1`='알리시아가 쓴 시를 한 번 더 읽어주시겠어요?', `FemaleText_loc4`='你能再为我读一次奥利卡的诗吗？', `FemaleText_loc5`='你能夠再唸一次艾利西亞之詩給我聽嗎?', `FemaleText_loc7`='¿Puedes volver a leerme el poema de Alicia?' WHERE `ID`=23768;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='읽어드리고 말고요!

내 무덤가에 서서 울지 마세요,
난 무덤에도 있지 않고, 잠든 것도 아니니까요.

내가 있는 곳은 천 갈래의 바람,
노스렌드의 빛나고 환한 눈 위를 넘어 불어오지요.

나는 부드러운 빗줄기,
서부 몰락지대에 황금빛 곡식 위로 떨어지죠.

내가 있는 곳은 이른 아침의 고요함,
가시덤불 골짜기 정글의 울창한 푸름 속에서 느껴지지요.

내가 있는 곳은 크고 웅장한 북소리,
나그란드를 가로질러 천둥 같은 발굽 소리로 울려나지요.

나는 따스하게 반짝이는 별들,
부드러운 꿈을 꾸는 다르나서스를 비춰주지요.

노래하는 새들 사이에,
모든 사랑스러움 사이에 내가 있어요.
그러니 내 무덤가에서 울지 마세요,
나는 거기 없으니까요. 나는 죽은 게 아니니까요.', `FemaleText_loc4`='我非常乐意！

不要在我的墓碑前哭泣，
我不在那里，我没有长眠。

我是凛冽的寒风，
掠过诺森德的雪原。

我是温柔的春雨，
滋润着西部荒野的麦田。

我是清幽的黎明，
弥漫在荆棘谷的林间。

我是雄浑的鼓声，
飞越纳格兰的云端。

我是温暖的群星，
点缀达纳苏斯的夜晚。

我是高歌的飞鸟，
留存于美好的人间。

不要在我的墓碑前哭泣，
我不在那里，我从未长眠。', `FemaleText_loc5`='我很樂意為你朗讀!

不要在我的墳塋上落淚，
我不在那裡，我也不入土長眠。

我伴著群風飛舞狂嘯，
拂過北裂境的晶白霜雪。

我是和煦的細雨，
落在西部荒野的金黃麥田上。

我是清晨的靜默，
漾在荊棘谷的叢林與綠蔓間。

我在壯盛喧天的戰鼓聲中，
伴著雷鳴般的蹄踏橫跨納葛蘭。

我是閃著溫暖微光的繁星，
散落在達納蘇斯的柔軟夢境。

我在鳴禽的宛囀之間，
我在一切的美好之中。

不要在我的墳塋上落淚，
我不在那裡。我也沒有死去。', `FemaleText_loc7`='¡Me encantaría leértelo!

No permanezcas ante mi tumba llorando,
no estoy allí, no estoy descansando.

Estoy en los miles de vientos que los árboles mueven,
en Rasganorte sobre la brillante nieve.

Soy la suave lluvia que cae gentilmente
en los campos de Páramos de Poniente.

Estoy en la calma matutina,
de la selva de Tuercespina.

Estoy en el redoble magistral,
de las pezuñas en Nagrand al pisar.

En las cálidas y brillantes estrellas me muevo,
mientras soñando sobre Darnassus me elevo.

Estoy en los pájaros cantores
y en las cosas que inspiran pasiones.

No permanezcas ante mi tumba llorando,
no estoy allí, no estoy descansando.' WHERE `ID`=23769;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='태워다 드릴까요?', `MaleText_loc4`='想搭一程顺风船么？', `MaleText_loc5`='想要乘坐嗎?', `MaleText_loc7`='¿Quieres dar una vuelta?' WHERE `ID`=23770;
