UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벡살루스가 폭주합니다!', `MaleText_loc4`='维萨鲁斯过载了！', `MaleText_loc5`='維克索魯斯超載!', `MaleText_loc7`='¡Vexallus se sobrecarga!' WHERE `ID`=23781;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거 말이죠, 사냥이란 자고로 고글을 썼을 때 해야 한답니다!', `MaleText_loc4`='我跟你说啊，猎艳的最佳方法就是保持良好的风度，还要戴上这种护目镜！', `MaleText_loc5`='讓我告訴你，正確的打獵方法就是先戴上護目鏡!', `MaleText_loc7`='¡Como oyes! ¡La mejor manera de cazar es con las gafas puestas!' WHERE `ID`=23782;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='*꽥!* 이봐! 내 해적 변장 좀 봐! 하하하! *꽥!*', `MaleText_loc4`='*呀呀！*嘿！看我的海盗伪装！耶！*呀呀！*', `MaleText_loc5`='<呱呱!>啊呵!看我這身海賊偽裝!呀啊啊!<呱呱!>', `MaleText_loc7`='*¡Graznido!* ¡Ah del barco! ¡Mira mi disfrás de pirata! ¡Aarrrr! * ¡Graznido!*' WHERE `ID`=23783;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='*까악!* 해적처럼 말해 봐! 으르렁! *꽤애애액!*', `MaleText_loc4`='*呱*讲话得像个海盗才行啊！耶！*呀呀！*', `MaleText_loc5`='<嘎嘎!>學海賊說話!呀啊啊!<呱呱!>', `MaleText_loc7`='*¡Graznido!* ¡Habla como un pirata! ¡Aarrr! *¡Graznido!*' WHERE `ID`=23784;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='*꽤애애액!* 닥쳐, 닥쳐. 멍청한 새! 너 때문에 우리 다 죽는다! *까아아악!*', `MaleText_loc4`='*呀呀！*你这蠢货，给我闭嘴！我们会被你害死的！*呱！*', `MaleText_loc5`='<呱呱呱!>閉嘴啦，笨鳥!你會害我們被殺的!<嘎嘎嘎嘎!>', `MaleText_loc7`='*¡Graznido!* ¡Cállate, estúpido pájaro! ¡Lograrás que nos maten a todos! *¡Graznido!*' WHERE `ID`=23785;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주둥이 다물어, 이 깃털 달린 멍청이야! 해적들이 네놈을 갈라서 모자로 쓰기 전에!', `MaleText_loc4`='叫什么叫，你简直是个白痴！那些海盗会把你剁了，然后拔下你的羽毛插在帽子上！', `MaleText_loc5`='把你的陷阱收起來，你這個有翅膀的白痴!這些海賊會把你開膛破肚做成帽子戴!', `MaleText_loc7`='¡Sierra el pico, analfaburro emplumao! ¡Estos piratas podrían rajarte y llevarte de sombrero!' WHERE `ID`=23786;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<당신의 손을 쪼아대는 바위매>', `MaleText_loc4`='<岩石猎鹰啄着你的手。>', `MaleText_loc5`='<這生物啄食著你手上的東西。>', `MaleText_loc7`='<La criatura picotea tu mano.>' WHERE `ID`=23787;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<지렁이를 보자 배고픈 듯 울어대는 바위매>', `MaleText_loc4`='<猎鹰发出饥饿的叫声，想要吃幼虫。>', `MaleText_loc5`='<石隼為了食物飢餓的鳴叫著。>', `MaleText_loc7`='<El falcón grazna hambriento pidiendo una larva.>' WHERE `ID`=23788;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바위매에게 지렁이를 먹입니다.', `MaleText_loc4`='<喂食岩石猎鹰。>', `MaleText_loc5`='<把幼蛆餵給石隼吃。>', `MaleText_loc7`='<Dale la larva al falcón de roca.>', `FemaleText_loc1`='바위매에게 지렁이를 먹입니다.', `FemaleText_loc4`='<喂食岩石猎鹰。>', `FemaleText_loc5`='<把幼蛆餵給石隼吃。>', `FemaleText_loc7`='<Dale la larva al falcón de roca.>' WHERE `ID`=23789;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 모든 걸 잃었습니다, 형제여. 카마구아에서 피난처를 제공해 준다니 정말 감사합니다.', `MaleText_loc4`='兄弟，我们已经失去了一切。幸运的是，卡玛古为我们提供了容身之所。', `MaleText_loc5`='我們什麼都沒了，兄弟。我們要感謝卡瑪廓提供我們避難所。', `MaleText_loc7`='Lo perdimos todo, hermano. Agradecemos a Komawa que nos dé cobijo.' WHERE `ID`=23790;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가장 도움이 절실할 때 우리를 도와주셨습니다. 바다가 그대에게 풍요로움을 선사하길.', `MaleText_loc4`='你在我们最需要的时候伸出了援手。愿海洋赐予你财富。', `MaleText_loc5`='你在我們需要幫忙的時候伸出援手。願大洋讓你滿載而歸。', `MaleText_loc7`='Nos ayudas en momentos de necesidad. Que los océanos te proporcionen abundante captura.' WHERE `ID`=23791;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다, 아키아루크. 당신이 베푼 친절은 이스카알에도 널리 알려졌습니다.', `MaleText_loc4`='谢谢你，阿加鲁克。我们在伊斯卡尔就听说了你的事迹。', `MaleText_loc5`='謝謝你，艾奇亞魯克。即使在伊斯考，您的善行仍然如雷貫耳。', `MaleText_loc7`='Gracias, Akiaruk. En Iskaal también hemos oído hablar de tu amabilidad.' WHERE `ID`=23792;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타유트카께서 당신과 당신의 마을을 보살피시기를.', `MaleText_loc4`='愿塔尤卡保佑你和你的村落。', `MaleText_loc5`='願塔尤卡報答你和你的村落。', `MaleText_loc7`='Que Tayutka os lo pague a ti y a tu pueblo.' WHERE `ID`=23793;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='눈을 내리까는 게 좋을 걸세, "친구!" 내 말이 무슨 뜻인지 안다면 말이지!$B$B으하하하하!', `MaleText_loc4`='“朋友”，你最好埋下头！希望你懂我的意思！$B$B耶！', `MaleText_loc5`='頭壓低一點，「朋友」!如果你知道我在說什麼的話!$B$B呀啊啊!', `MaleText_loc7`='Será mejor que mantengas la cabesa gacha, "asere". Si entiendes lo que quiero desir.$B$B¡Yarrrrr!' WHERE `ID`=23794;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='머지않았어요, 내 사랑. 곧 당신이 깨어나 아제로스에 공포가 무엇인지 보여주겠죠!', `FemaleText_loc4`='亲爱的，快啦。你很快就会苏醒过来，艾泽拉斯世界将在恐惧中颤抖！', `FemaleText_loc5`='快了，吾愛。很快，你就會醒來，整個艾澤拉斯將會知道何謂恐懼!', `FemaleText_loc7`='Pronto, amor mío. ¡Pronto despertarás y Azeroth conocerá el miedo!' WHERE `ID`=23795;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='일어나요, 이미론. 다시 당신이 군림할 시간이에요.', `FemaleText_loc4`='苏醒吧，伊米隆国王。时机已经成熟，你很快就能重掌统治权。', `FemaleText_loc5`='甦醒吧，依米倫，繼續你統治的時代近了!', `FemaleText_loc7`='Despierta, Ymiron, se acerca el momento de que continúes tu reinado.' WHERE `ID`=23796;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='눈을 떠요, 내 사랑. 리치 왕의 힘이 당신 안에 거하니, 온 세상이 공포에 떨 거예요.', `FemaleText_loc4`='从沉睡中醒来吧，我的爱。有了巫妖王的支持，世界将因你而颤抖。', `FemaleText_loc5`='吾愛，別再沉眠了，只要有巫妖王的力量支持你，世界將為之震撼。', `FemaleText_loc7`='No duermas más, amor mío. Con el poder del Rey Exánime respaldándote el mundo temblará.' WHERE `ID`=23797;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='왜 이렇게 오래 걸리지? 너희 주인이 약속한 대로라면, 네놈들이 도와주면 의식이 더 빨리 진행돼야 하는데!', `FemaleText_loc4`='仪式怎么要进行这么久？你的主子向我保证过，说有了你的帮助，仪式会快很多的！', `FemaleText_loc5`='為什麼這個儀式要花這麼長的時間?你的主人保證有你的幫忙可以加速進度的!', `FemaleText_loc7`='¿Por qué está tardando tanto este ritual? ¡Tu maestro aseguró que con tu ayuda se agilizaría el proceso!' WHERE `ID`=23798;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='훨씬 더 노력해라! 이미론 왕께서 깨어나 등극하실 것이니!', `FemaleText_loc4`='加倍努力！伊米隆国王很快就要苏醒了，接着他将登上王座！', `FemaleText_loc5`='加倍努力!依米倫王才會被喚醒飛升!', `FemaleText_loc7`='¡Doblen sus esfuerzos! ¡El Rey Ymiron se despertará y ascenderá!' WHERE `ID`=23799;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리를 이토록 저주한 티탄에게 파멸 있으라! 이미론, 나의 왕이시여! 눈을 뜨소서!', `FemaleText_loc4`='该死的泰坦诅咒了我们！伊米隆，我的国王，张开双眼吧！', `FemaleText_loc5`='咒罵那些詛咒我們的泰坦!依米倫，吾王，睜開雙眼吧!', `FemaleText_loc7`='¡Malditos sean los titanes por maldecirnos así! ¡Ymiron, mi rey, abre los ojos!' WHERE `ID`=23800;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나의 남편, 우리의 왕께서 부활할 시간이 다가왔다. 쓸모없는 버러지들을 함께 이 세계에서 몰아내리라!', `FemaleText_loc4`='是时候了，我的丈夫，我们的国王很快就能重新回到我们身边啦。我要和他一起铲除世间的蝼蚁！', `FemaleText_loc5`='我的丈夫，我們的王，是時候重新團結我們了。我們將一同洗淨這個世界的卑惡災禍!', `FemaleText_loc7`='Ha llegado el momento de que mi marido, nuestro rey, se reúna con nosotros. ¡Juntos liberaremos al mundo de esta indigna plaga!' WHERE `ID`=23801;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='의식이 너무 더디게 진행된다. 제물이 더 필요해!', `FemaleText_loc4`='仪式进行得太慢啦。需要更多的祭品！', `FemaleText_loc5`='儀式進展的太緩慢了。我們需要更多的祭品!', `FemaleText_loc7`='El ritual progresa muy lentamente. ¡Necesitamos más sacrificios!' WHERE `ID`=23802;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직이다, 이미론. 널 위한 계획은 따로 있다. 너는 우트가드 첨탑에서 나를 계속 섬길 것이다. 만약 이 벌레들이 살아남아 다시 너를 찾는다면, 그땐 네 아내의 복수를 할 수 있겠지.', `MaleText_loc4`='不要着急，伊米隆。我对你另有安排。你先回到乌特加德之巅去，在那里更好地为我效劳。如果真有这些蝼蚁再次找上你的那一天，到时你就可以亲自为妻子复仇了。', `MaleText_loc5`='時候未到，依米倫。我對你另有安排。你更適合在俄特加德之巔為我效命。如果這些蛆蟲存活下來，再次見到你，你就能夠為你的妻子復仇。', `MaleText_loc7`='Todavía no, Ymiron. Tengo otros planes para ti. Me rendirás un mejor servicio desde el Pináculo de Utgarde. Y si esos insectos sobreviven, y te buscan otra vez, tendrás la oportunidad de vengar a tu esposa.' WHERE `ID`=23803;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 누굴 사냥한다고?', `MaleText_loc4`='谁才是猎物啊？', `MaleText_loc5`='到底是誰狩獵誰啊?', `MaleText_loc7`='¿Quién está cazando a quién?' WHERE `ID`=23804;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 쉬운 사냥감이군...', `MaleText_loc4`='真容易对付……', `MaleText_loc5`='輕而易舉...', `MaleText_loc7`='Una presa tan fácil...' WHERE `ID`=23805;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 저녁엔 네놈이 반찬이다!', `MaleText_loc4`='今晚我们要吃你的肉，喝你的血！', `MaleText_loc5`='今晚，我們要拿你下酒!', `MaleText_loc7`='¡Esta noche celebramos contigo!' WHERE `ID`=23806;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 이 결투장을 관리하지. 돈을 걸고 싶다면 마음 놓고 걸게. 승부를 조작하는 놈이 있으면 바다로 향한 널빤지 위에 세워 버릴 테니까.$B$B빈말이 아니라네!', `MaleText_loc4`='我负责主持格斗比赛。你想不想赌一把啊？怎么样，有信心吗？但是——谁敢搞贿赂选手的猫腻，我就让他走跳板。$B$B我会亲自维持比赛的公平！', `MaleText_loc5`='這裡的拳賽都是我辦的。你想要下注，就要賭的有把握 - 要是被抓到操縱拳賽，你就給我去走跳板吧。$B$B我會自己確認的!', `MaleText_loc7`='Yo llevo las peleas aquí. Si quieres apostar, haslo con confiansa; si encontramos a alguien amañando las peleas, lo pasamos pol la quilla.$B$B¡D''eso m''aseguro yo, cheche!' WHERE `ID`=23807;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='블러드 엘프의 보물은 다른 것들과는 달라. 금이나 비단, 보석으로 만들어져서가 아니라 그 안에 녹아든, 그리고 그 자체인 신도레이의 장인정신이 귀한 것이기 때문이지.', `MaleText_loc4`='与其他种族不同，血精灵的财富不仅仅局限于金币、丝绸或是宝石之类的原材料。辛多雷精妙的工艺本身就是无价的财富。', `MaleText_loc5`='血精靈的寶藏跟其他人的不一樣，不會只是金子或絲綢或寶石這種實用的物質，辛多雷的工藝的價值在其內在或本身。', `MaleText_loc7`='Tesoros de los elfos de sangre sin igual. No es solo por el oro, la seda o las gemas que usan como materiales; la artesanía sin''dorei tiene valor por sí misma.' WHERE `ID`=23808;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신에게 빚을 받아오라고 타루크가 날 보냈습니다..', `MaleText_loc4`='塔鲁克派我来收欠款。', `MaleText_loc5`='塔廬克派我來向你收帳。', `MaleText_loc7`='Taruk me envía a recoger lo que debes.', `FemaleText_loc1`='당신에게 빚을 받아오라고 타루크가 날 보냈어요.', `FemaleText_loc4`='塔鲁克派我来收欠款。', `FemaleText_loc5`='塔廬克派我來向你收帳。', `FemaleText_loc7`='Taruk me envía a recoger lo que debes.' WHERE `ID`=23809;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 시험하지 마라, 천박하기 그지없는 놈! 나는 혈기사 훈련을 받은 몸이란 말이다!', `MaleText_loc4`='别惹我，败狗！老子是接受过血骑士正统训练的强者！', `MaleText_loc5`='別挑戰我，爛貨!我可是受過血騎士之道的訓練呢!', `MaleText_loc7`='¡No me pongas a prueba, perro de agua dulce! ¡Conozco las artes de los Caballeros de sangre!' WHERE `ID`=23810;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 졌어! 내가 졌다고! 쿠엘탈라스를 걸고 맹세하겠어! 죽이지 마!', `MaleText_loc4`='我认输！我认输！以奎尔萨拉斯的名义！不要杀我！', `MaleText_loc5`='我投降!我投降!我的奎爾薩拉斯呀!別殺我!', `MaleText_loc7`='¡Me rindo! ¡Me rindo! ¡Por Quel''thalas! ¡No me mates!' WHERE `ID`=23811;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갚을게! 갚는다고! 으악! 제발 때리지 마!', `MaleText_loc4`='我还钱！我还钱！呀～！不要伤害我！', `MaleText_loc5`='我付錢!我付錢!唉唷!別弄傷我!', `MaleText_loc7`='¡Pagaré! ¡Pagaré! ¡Aaayyyyy! ¡No me hagas daño!' WHERE `ID`=23812;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 내놓으시지, 해리!', `MaleText_loc4`='还钱，哈瑞！', `MaleText_loc5`='付錢啦，哈利!', `MaleText_loc7`='¡Paga, Harry!', `FemaleText_loc1`='어서 내놓으시지, 해리!', `FemaleText_loc4`='还钱，哈瑞！', `FemaleText_loc5`='付錢啦，哈利!', `FemaleText_loc7`='¡Paga, Harry!' WHERE `ID`=23813;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그 미친 조나 스털링이 제게 날이면 날마다 시키는 일이라곤 그저 갑판 걸레질뿐이에요.$B$B갑판 청소라니?!$B$B전 마법사라고요! 걸레질 따윈 안 해요! 그저 평범하게 쓸고 닦는 방식으로는 말이죠.', `FemaleText_loc4`='“疯狗”约纳·斯特林要我整日整夜地打扫甲板。$B$B打扫甲板？！$B$B我是个法师，凭什么让我做这种杂事！就算要打扫，也该玩点新花样吧。', `FemaleText_loc5`='日復一日，『瘋子』喬納·斯德林就光叫我洗甲板。$B$B洗所有的甲板耶?!$B$B我是法師，我絕不拖地!至少不是用一般人的拖地方法啦。', `FemaleText_loc7`='Lo único que elll Loco Jonah Sterling quiele que haga es fregalll la''h cubielllta''h todo'' los días.$B$B¿Fregalll las cubielta''h?$B$B¡Yo soy maga, yo NO friego cubiellltas! Al menos no de la manela mundana.' WHERE `ID`=23814;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마셔, 이 천박한 자식아!', `MaleText_loc4`='喝光啊，你真不够意思！', `MaleText_loc5`='乾了它，你這個無賴!', `MaleText_loc7`='¡Bebed, chuchos d''agua dulse!' WHERE `ID`=23815;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='먹고 마셔! 즐겨 보자고! 다음은 너야!', `MaleText_loc4`='吃！喝！快乐起来！下一轮酒该你请啦！', `MaleText_loc5`='給我吃!給我喝!不要給我愁眉苦臉!下一個就輪到你了!', `MaleText_loc7`='¡Come! ¡Bebe! ¡Sé felí! ¡La próxima ronda corre de tu cuenta!' WHERE `ID`=23816;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끝까지 마셔, 친구! 황금골에는 못 마셔서 안달 난 애들이 넘쳐나는 거 몰라?', `MaleText_loc4`='小子，喝光你的朗姆酒！要知道，闪金镇还有着口渴的孤儿呢！', `MaleText_loc5`='朋友，給我把酒喝光!閃金鎮還有很多口渴的孤兒你知道嗎?', `MaleText_loc7`='¡Acábate el ron, mi amol! Hay huérfanos sedientos en Villadorada, ¿tú sabes?' WHERE `ID`=23817;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='조용히 좀 해 줄래요? 누가 알아차렸다간 우리 둘 다 죽은 목숨이라고요.', `FemaleText_loc4`='安静点好吗？要是被人发现，我们就死定了。', `FemaleText_loc5`='安靜點好嗎?要是誰聽見了，我們就死定了。', `FemaleText_loc7`='Estate callad$go:a;, ¿quieres? Si alguien nos pilla, estamos muert$go:a;s l$go:a;s dos.' WHERE `ID`=23818;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋아요, 친구들! 누가 이 향긋한 럼주를 주문했죠? 당신인가요, 재키?', `FemaleText_loc4`='好吧，伙计！谁点了风味朗姆酒啊？小杰克，是你吗？', `FemaleText_loc5`='好吧，夥伴們，到底是誰點了這杯加味蘭姆酒?是你嗎，傑克小子?', `FemaleText_loc7`='¡De acuerdo, chicos! ¿Quién ha pedido el ron especiado? ¿Has sido tú, Jackie?' WHERE `ID`=23819;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='걱정하지 말아요, 멋쟁이씨. 이건 공짜니까요.', `FemaleText_loc4`='没事，甜心。这杯是免费的。', `FemaleText_loc5`='沒關係，甜心，這杯本店免費招待。', `FemaleText_loc7`='Está bien, cielo. Esta corre a cargo de la casa.' WHERE `ID`=23820;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공짜 술...? 내가 제일 좋아하는 술이군!', `MaleText_loc4`='免费的朗姆酒？啊……这可是我的最爱！', `MaleText_loc5`='免費的酒?哇...這是我的最愛耶!', `MaleText_loc7`='¿Ron gratis? ¡Cumbancha, ese es mi preferíiio!' WHERE `ID`=23821;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넵튤론이시여! 오늘은... 너무 많이... 마셨군!', `MaleText_loc4`='太棒了！喝得……有点……多了！', `MaleText_loc5`='親愛的奈普圖隆!這杯...有點...太過量了!', `MaleText_loc7`='¡Dulse Neptulon! ¡Eso fue... una bebida... de más!' WHERE `ID`=23822;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<이 해적은 너무 많이 마신 게 분명합니다. 한동안은 곯아떨어져 있을 것으로 보입니다.>', `MaleText_loc4`='<这个海盗显然是喝多了，看上去有点不省人事。>', `MaleText_loc5`='<這個海賊看來是喝掛了，他暫時醒不過來。>', `MaleText_loc7`='<Es evidente que este pirata ha bebido demasiado. Parece estar inconsciente por el momento.>' WHERE `ID`=23823;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<해적의 주머니를 조심스럽게 뒤져 타루크에게 갖다줄 돈을 찾습니다.>', `MaleText_loc4`='<谨慎地翻开海盗的口袋，寻找塔鲁克的欠款。>', `MaleText_loc5`='<仔細的在海賊的口袋裡面找尋塔廬克的款項。>', `MaleText_loc7`='<Busca discretamente el pago de Taruk en los bolsillos del pirata.>', `FemaleText_loc1`='<해적의 주머니를 조심스럽게 뒤져 타루크에게 갖다줄 돈을 찾습니다.>', `FemaleText_loc4`='<谨慎地翻开海盗的口袋，寻找塔鲁克的欠款。>', `FemaleText_loc5`='<仔細的在海賊的口袋裡面找尋塔廬克的款項。>', `FemaleText_loc7`='<Busca discretamente el pago de Taruk en los bolsillos del pirata.>' WHERE `ID`=23824;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 보고 있나? 한 잔 더 따라!', `MaleText_loc4`='看什么看？再给我来一杯！', `MaleText_loc5`='看什麼看?給我倒酒!', `MaleText_loc7`='¿Qué bolá? ¿Qué tú miras? ¡Sírveme otra bebida!' WHERE `ID`=23825;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭘 드릴까요? 럼주? 맥주?$B$B아니면 뭔가 다른 걸 드릴까요?', `FemaleText_loc4`='来点什么呢？朗姆酒？还是麦酒？$B$B或者你想尝尝别的？', `FemaleText_loc5`='要點什麼?蘭姆酒?麥酒?$B$B還是其他的?', `FemaleText_loc7`='Entonces, ¿qué va a ser? ¿Ron? ¿Cerveza?$B$B¿O quizá otra cosa?' WHERE `ID`=23826;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잭에게 한 잔 사고 싶습니다. 뭔가... 엄청나게 독한 걸로요.', `MaleText_loc4`='我想请杰克喝一杯。最好是……那种后劲儿特足的饮料。', `MaleText_loc5`='我想要請傑克喝一杯。或許來點...特烈的。', `MaleText_loc7`='Me gustaría pagarle una bebida a Jack. Quizá algo... extra fuerte.', `FemaleText_loc1`='잭에게 한 잔 사고 싶어요. 뭔가... 엄청나게 독한 걸로요.', `FemaleText_loc4`='我想请杰克喝一杯。最好是……那种后劲儿特足的饮料。', `FemaleText_loc5`='我想要請傑克喝一杯。或許來點...特烈的。', `FemaleText_loc7`='Me gustaría pagarle una bebida a Jack. Quizá algo... extra fuerte.' WHERE `ID`=23827;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잭의 부하들이 보는 앞에서 그에게 수작을 부리겠다고요?$B$B뭐랄까... 바보 같은 생각이네요. 혼쭐이 날 걸요. 난 금화 한 닢도 안 되는 돈에 목숨을 걸 생각이 없어요. 그러니 일을 저지를 거면 내가 이 자리를 피할 때까지 좀 기다려 줘요.', `FemaleText_loc4`='你想公然和杰克叫板是吗？$B$B嘿，我得说着这绝对是个……愚蠢的决定。这会让你损失惨重的。我可不想冒着丢掉小命的危险去干这种一分钱都挣不来的破事。嗯，你最好等我跑远了再动手。', `FemaleText_loc5`='你要在傑克手下的面前耍他?$B$B會打算這麼做的我想只有...白痴。嗯，這會要你付出代價，我不會為了區區幾毛錢冒生命危險，你也最好等我離開是非之地後再行動。', `FemaleText_loc7`='¿Vas a hacerle una de las tuyas a Jack delante de sus chicos?$B$BEso requiere mucha... estupidez. Bueno, será tu problema. Yo no voy a arriesgar mi vida por menos de un oro. ¡Y será mejor que esperes a que me haya ido antes de hacer nada!' WHERE `ID`=23828;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 골드로 필요한 걸 사도록 하십시오.', `MaleText_loc4`='给，你可以用这枚金币买给自己想要的东西。', `MaleText_loc5`='這裡是一枚金幣，給自己買點好東西吧。', `MaleText_loc7`='Aquí tienes un oro. Cómprate algo bonito.', `FemaleText_loc1`='이 골드로 필요한 걸 사도록 하세요.', `FemaleText_loc4`='给，你可以用这枚金币买给自己想要的东西。', `FemaleText_loc5`='這裡是一枚金幣，給自己買點好東西吧。', `FemaleText_loc7`='Aquí tienes un oro. Cómprate algo bonito.' WHERE `ID`=23829;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론이지, 귀염둥이. 술값은 해리 앞으로 달아 놓으라고. 그 친구 나한테 한 잔 사기로 했으니 말이야!', `MaleText_loc4`='当然啦，亲爱的。把它算到哈里的账上好不好呀？他欠我一杯酒呢！', `MaleText_loc5`='那是當然啦，親愛的。把它記在哈利的帳上，好吧?他欠我一杯!', `MaleText_loc7`='Claro, mi amol. Apúntalo en la cuenta de Harry, ¿vale? ¡Me debe una bebida!' WHERE `ID`=23830;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 됐네요, $n! 이 덩어리라면 될 거예요! 이제 걸레질 좀 제대로 하겠네!', `FemaleText_loc4`='好啦，$n！这肯定管用！让我们好好打扫一下吧！', `FemaleText_loc5`='這就是我們要的啦，$n!這塊油脂一定能符合我們的要求!看看什麼叫做真正的拖地!', `FemaleText_loc7`='¡Allá vamos, $n! ¡Esta grasa selvi''lá! ¡Y ahora vamos a fregalll de veldá!' WHERE `ID`=23831;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저것 보세요! 티없이 깨끗하군요!', `FemaleText_loc4`='瞧！一尘不染！', `FemaleText_loc5`='看著它們作用!太完美了!', `FemaleText_loc7`='¡Míralas! ¡Sin una mancha!' WHERE `ID`=23832;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하하하! 내 보물을 가져가고 싶다면... 싸워 이기고 가져가라!', `MaleText_loc4`='呀啊啊啊！想要夺得我的财宝……你要费一番功夫了！', `MaleText_loc5`='呀啊啊!如果你在找的是我的寶藏...那你得打一架才行!', `MaleText_loc7`='¡Arrrr! ¡Si buscas tú mi tesoro... tendrás que luchar!' WHERE `ID`=23833;
