UPDATE `locales_broadcast_text` SET `MaleText_loc1`='됐어... 이제 그만 마셔야지!', `MaleText_loc4`='够了……我喝不下了！', `MaleText_loc5`='夠了...不要再灌我喝酒了!', `MaleText_loc7`='Ya tá... ¡s''acabó el grog pa mí!', `FemaleText_loc1`='그래... 그만 마실 때가 된 거야!', `FemaleText_loc4`='够了……我喝不下了！', `FemaleText_loc5`='夠了...不要再灌我喝酒了!', `FemaleText_loc7`='Ya tá... ¡s''acabó el grog pa mí!' WHERE `ID`=23835;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신더브루 고글 써 봤습니까? 정말 놀라울 만큼 불편한데!', `MaleText_loc4`='你戴过合成酿酒护目镜吗？超级难受的！', `MaleText_loc5`='你有戴過模擬醉眼護目鏡嗎?戴起來意外地不舒服!', `MaleText_loc7`='¿Alguna vez te has probado unas gafas birratizadoras? ¡Son sorprendentemente incómodas!' WHERE `ID`=23836;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은무쇠 드워프의 공격', `MaleText_loc4`='黑铁矮人进攻', `MaleText_loc5`='黑鐵矮人襲擊', `MaleText_loc7`='Enano Hierro Negro ataca', `FemaleText_loc1`='검은무쇠 드워프의 공격', `FemaleText_loc4`='黑铁矮人进攻', `FemaleText_loc5`='黑鐵矮人襲擊', `FemaleText_loc7`='Enano Hierro Negro ataca' WHERE `ID`=23837;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭣 때문인지 몰라도 검은무쇠 드워프가 굉장히 화가 났어요. 거의 30분마다 나타나서 맥주통을 다 부수고는 도망간다니까요!$b$b물론 당신과 무슨 상관이냐고 묻고 싶으시겠지요?$b$b이유를 말씀드리죠... 왜냐하면 녀석들이 부수는 맥주통은 공짜 맥주를 제공하는 맥주통이니까요! 제대로 들으셨지요? 공짜 맥주라고요!$b$b그러니 저 드워프 녀석들이 나타났을 때 주위에 계시거든, 맥주통 지키는 데 시간 좀 내 달라고요.', `MaleText_loc4`='那些黑铁矮人简直是失心疯了，他们几乎每个小时都要来一次，打碎酒桶之后就跑掉了！$B$B也许你要问，“我为什么要关心这个呢？”$B$B那么我告诉你，他们破坏掉的都是提供免费啤酒的酒桶！没错，免费的！$B$B如果你正好遇到黑铁矮人破坏酒桶，别忘了帮我们保护这些免费的美酒！', `MaleText_loc5`='某件事激怒了那些黑鐵矮人。他們幾乎每半個小時就出現一次，把所有的桶子破壞後揚長而去!$b$b因此你一定會想問。「這干我什麼事?」$b$b我來告訴你...因為他們的破壞使我們無法提供免費的啤酒!你沒聽錯，免費的啤酒!$b$b所以，如果那些矮人來襲時你在附近的話，花點時間幫忙保護這些桶子吧。', `MaleText_loc7`='Los enanos Hierro negro están irritados por algo. Vienen casi cada media hora, rompen todos los barriles y se van.$B$BTe estarás preguntando "¿y a mí qué?"$B$BTe lo explicare... ¡Los barriles que rompen evitan que regalemos cerveza gratis! Me has oído bien: cerveza gratis.$B$BAsí que, si estás por aquí cuando aparezcan esos enanos, dedica un minutos a ayudar a proteger los barriles.' WHERE `ID`=23838;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가을 축제는 끝내주는 축제지요! 그런데 말입니다... 곤란한 게 딱 하나 있는데, 바로 검은무쇠 드워프의 공격입니다. 거의 30분마다 몰려온다고요!$b$b녀석들의 목표는 바로 공짜 맥주를 받아 마실 수 있는 맥주통입니다! 양조사들이 친절하게 베푸는 진짜 좋은 맥주라고요!$b$b보세요, 검은무쇠 드워프가 나타났을 때 주위에 계시거든, 공짜 맥주 지키는 데 손 좀 빌려 주시죠!', `MaleText_loc4`='美酒节是个完美的节日！不过万事无绝对，黑铁矮人就是这个节日中的一个小麻烦。他们几乎每个小时都要来一次！$B$B他们的目标是提供免费啤酒的酒桶，而且那些啤酒还都是最棒的上等啤酒！$B$B你看，如果你正好遇到黑铁矮人破坏酒桶，别忘了帮我们保护这些免费的美酒！', `MaleText_loc5`='啤酒節是個無懈可擊的節日!不過美中不足的是黑鐵矮人的襲擊。他們幾乎每半個小時就來一次!$b$b攻擊目標是那些發送「免費」啤酒的桶子!這些都是由啤酒大師所提供的美味啤酒!$b$b聽著，如果你在那些黑鐵矮人出現時剛好在附近的話，幫忙保護一下這些「免費」的啤酒。', `MaleText_loc7`='¡La Fiesta de la Cerveza es la festividad perfecta! Pero tiene un inconveniente: los ataques de los enanos Hierro Negro. Tienen lugar casi cada media hora.$B$BLos atacantes se ceban con los barriles que dan cerveza GRATUITA. Y es una cerveza muy buena que regalan los maestros cerveceros.$B$BSi estás por aquí cuando aparezcan los enanos Hierro Negro, echa una mano y protege la cerveza GRATUITA.' WHERE `ID`=23839;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘을! 더... 크으윽, 더...!', `MaleText_loc4`='能量！多点，多点，再多点！', `MaleText_loc5`='力量!多一點，更多，還要更多!', `MaleText_loc7`='¡El poder! ¡Más, más, más!' WHERE `ID`=23840;
