UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕, 칭구!', `MaleText_loc4`='呀啊啊啊，朋友！', `MaleText_loc5`='呀啊啊啊啊，老兄!', `MaleText_loc7`='¡Arrrrr! ¿Qué bolá, asere?' WHERE `ID`=23849;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 돌아왔소, $n.', `MaleText_loc4`='欢迎回来，$n。', `MaleText_loc5`='歡迎回來，$n。', `MaleText_loc7`='Te doy la bienvenida de nuevo, $n.' WHERE `ID`=23850;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 네 주인에 대한 보답이냐, 이 더러운 짐승아? 끄아아아아!', `MaleText_loc4`='你就是这样报答主子的吗？你这烂熊！啊啊啊啊啊！', `MaleText_loc5`='這就是你回報主人的方法嗎，你這個忘恩負義的傢伙?啊啊啊!!', `MaleText_loc7`='¿Así es como pagas tú a tu maestro, saco de pulgas? ¡¡Arrrrrgghh!!' WHERE `ID`=23851;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저 망할 조나 스털링이 우릴 이 꼴로 만들었어요. 그가 동굴 안에 죽치고 있지만 않았더라면 전쟁 중에 해군을 습격하는 게 바보짓이라는 것 정도는 알았을 텐데 말이에요.', `FemaleText_loc4`='约纳·斯特林这个蠢货迟早要害死我们。如果他多花点时间观察局势的话，就会明白在战争期间攻击职业海军是件多么愚蠢的事。', `FemaleText_loc5`='那個該死的喬納·斯德林將會帶領我們滅亡。要是他多花點時間走出他的洞穴看看，他就會了解在戰時攻擊專業海軍是多愚蠢的事。', `FemaleText_loc7`='Este maldito Jonah Sterling nos llevará a la perdición. Si pasara más tiempo fuera de su cueva, vería que atacar a armadas profesionales en tiempos de guerra es una locura.' WHERE `ID`=23852;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신은 그만 떠나는 게 좋겠어요, $n. 조나의 죽음에 내가 관여했다는 소문을 퍼트리고 싶지는 않으니까요.$B$B내가 예전 선장을 죽게 했다는 사실까지 굳이 알리지 않아도, 저 해적들을 이끌기란 아주 고될 걸요.', `FemaleText_loc4`='你最好快滚，$n。我不想和约纳的死扯上关系。$B$B他们还不知道我杀了以前的船长取而代之，我才能勉强坐稳头领的位置。', `FemaleText_loc5`='你最好馬上離開，$n。我不希望喬納的死最後牽涉到我。$B$B要在這個圈子建立起自己的領導地位已經不容易了，萬一他們還知道我做掉了他們之前的船長就更難了。', `FemaleText_loc7`='Será mejor que te largues, $n. No quiero que relacionen la muerte de Jonah conmigo.$B$BYa será bastante complicado llegar a ser la líder de esta panda sin que sepan que ordené la muerte de su anterior capitán.' WHERE `ID`=23853;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 주인의 몸을 덥석 삼킵니다.', `MaleText_loc4`='%s吞食着主人的尸体。', `MaleText_loc5`='%s把他的主人一口吞了下去。', `MaleText_loc7`='%s devora el cuerpo de su maestro.' WHERE `ID`=23854;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대지와 바다가 크게 변하고 있습니다. 당신도... 그들도... 많이 변하고 있지요.$B$B카마구아가 사는 방식도 이런 변화 때문에 위험에 처했습니다. 어떻게 하려고 하십니까?', `MaleText_loc4`='沧海桑田，你，还有他们……世事变幻。$B$B卡玛古因此受到威胁。你能为我们做些什么呢？', `MaleText_loc5`='這片土地和水源受到了許多改變:包括你，包括他們...很大的改變。$B$B這些改變威脅到了卡瑪廓的生存方式。換做是你會怎麼做?', `MaleText_loc7`='Muchas cosas cambian tanto en tierra como en el agua: tú, ellos... muchas cosas cambian.$B$BLa forma de vida de Komawa se ve amenazada por estos cambios. ¿Qué harás?' WHERE `ID`=23855;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 소질이 없다고 했나요? 왈트는 뭘 몰라도 한참은 모른다니까요! 내가 얼마나 손쉽게 저 무쇠 드워프들을 쓸어내고 이 야영지를 만들어 발굴현장의 동태를 살피고 있는지 몰라서 하는 소리라니까요.', `MaleText_loc4`='我是个外行，嗯？沃尔特讲话不经过大脑吗？我独自一人就教训了那些铁矮人，还在这里搭建起营地观察挖掘场的动静。', `MaleText_loc5`='我差勁透了，啊?渥特根本不懂他在說什麼鬼話!我單槍匹馬就把這些鐵矮人趕走了，還在這裡設立了營地監視挖掘場的一舉一動。', `MaleText_loc7`='Estoy fuera de mi elemento, ¿eh? ¡Walt no sabe de qué está hablando! Yo solito saqué el hierro de esos enanos y acampé para observar lo que ocurría en la excavación.' WHERE `ID`=23856;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기 저 친구, 지금 양탄자 때문에 꽤 화가 났답니다.', `MaleText_loc4`='瞧，那家伙正在为地毯的事烦恼呢。', `MaleText_loc5`='那位仁兄，就遠處那位，為了他的毯子感到很難過。', `MaleText_loc7`='El Nota, está muy disgustado por su alfombra, ¿sabes?' WHERE `ID`=23857;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까.', `MaleText_loc4`='晚上好。', `MaleText_loc5`='晚安，官爺。', `MaleText_loc7`='Buenas, colega.', `FemaleText_loc1`='안녕하십니까.', `FemaleText_loc4`='晚上好。', `FemaleText_loc5`='晚安，官爺。', `FemaleText_loc7`='Buenas, colega.' WHERE `ID`=23858;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바다표범 암컷과 바다표범 수컷이 사랑에 빠졌습니다.', `MaleText_loc4`='暗礁母海狮和公海狮找到了真爱。', `MaleText_loc5`='暗礁母海獅和她的新男伴找到了真愛。', `MaleText_loc7`='La hembra de arrecife y su nuevo macho dominante descubren el amor verdadero.' WHERE `ID`=23859;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발진합니다.', `MaleText_loc4`='启动。', `MaleText_loc5`='發動中。', `MaleText_loc7`='Lanzando.' WHERE `ID`=23860;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일어나라, 병사들이여. 나가서 싸워라! 이 쇠락한 기사에게 승리를 안겨다오!', `MaleText_loc4`='士兵们，起来战斗吧！为死去的骑士带来胜利的荣耀！', `MaleText_loc5`='士兵們起立，挺身奮戰!讓這個位死去的騎士得到最後的勝利!', `MaleText_loc7`='Un soldado se yergue enfrentando el desafío. Sea la victoria para el caballero abatido.' WHERE `ID`=23861;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 초읽기를 해주십시오!', `MaleText_loc4`='开始倒计时！', `MaleText_loc5`='開始倒數!', `MaleText_loc7`='¡Comenzad la cuenta atrás!', `FemaleText_loc1`='어서 초읽기를 해주세요!', `FemaleText_loc4`='开始倒计时！', `FemaleText_loc5`='開始倒數!', `FemaleText_loc7`='¡Comenzad la cuenta atrás!' WHERE `ID`=23862;
