UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왈트가 검은무쇠 주괴를 모아오라고 절 보냈습니다.', `MaleText_loc4`='沃尔特派我来要一些黑铁条。', `MaleText_loc5`='渥特派我來撿一些黑鐵錠。', `MaleText_loc7`='Walt me ha enviado a recoger algunos lingotes de hierro negro.', `FemaleText_loc1`='왈트가 검은무쇠 주괴를 모아오라고 절 보냈습니다.', `FemaleText_loc4`='沃尔特派我来要一些黑铁条。', `FemaleText_loc5`='渥特派我來撿一些黑鐵錠。', `FemaleText_loc7`='Walt me ha enviado a recoger algunos lingotes de hierro negro.' WHERE `ID`=23868;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저... 저... 전초기지로 돌아가고 싶으시단 거죠?', `MaleText_loc4`='呃……这么说……你打算启程返回前哨站，是吧？', `MaleText_loc5`='我猜...猜...猜想你想要駛回哨站，對吧?', `MaleText_loc7`='Su... su... supongo que quieres volver a la avanzada. ¿Yarp?' WHERE `ID`=23869;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네.', `MaleText_loc4`='是的。', `MaleText_loc5`='對囉。', `MaleText_loc7`='Yarp.', `FemaleText_loc1`='네.', `FemaleText_loc4`='是的。', `FemaleText_loc5`='對囉。', `FemaleText_loc7`='Yarp.' WHERE `ID`=23870;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왈트의 작업대를 사용할 수 있습니다.', `MaleText_loc4`='沃尔特的工作台可以使用了。', `MaleText_loc5`='渥特的工作臺隨時可以使用。', `MaleText_loc7`='El banco de trabajo de Walt está listo para ser usado.' WHERE `ID`=23871;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<작업대에 올라가 왈트가 입혀주는 대로 골렘 갑옷을 착용합니다.>', `MaleText_loc4`='<跳上工作台，让沃尔特将你塞进魔像中。>', `MaleText_loc5`='<站到工作臺上面去，好讓渥特把你裝進魔像裝裡面。>', `MaleText_loc7`='<Sube al banco de trabajo y deja que Walt te ponga el traje de gólem.>', `FemaleText_loc1`='<작업대에 올라가 왈트가 입혀주는 대로 골렘 갑옷을 착용합니다.>', `FemaleText_loc4`='<跳上工作台，让沃尔特将你塞进魔像中。>', `FemaleText_loc5`='<站到工作臺上面去，好讓渥特把你裝進魔像裝裡面。>', `FemaleText_loc7`='<Sube al banco de trabajo y deja que Walt te ponga el traje de gólem.>' WHERE `ID`=23872;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 완벽한 창조물 좀 보라고!', `MaleText_loc4`='瞧，完美的作品！', `MaleText_loc5`='請看我那完美的作品!', `MaleText_loc7`='¡Observad mi perfecta creación!' WHERE `ID`=23873;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하루에 두 번, 아침 6시와 저녁 6시에 땜장이왕 멕카토크께서 직접 가을 축제 광장으로 나오셔서 맥주통 따기 의식을 거행하신답니다. 절대 놓치지 마세요!', `MaleText_loc4`='每天两次，分别是在早上6点15分和下午6点15分，大工匠梅卡托克会亲自来到美酒节的现场，主持开酒罐仪式。千万别错过！', `MaleText_loc5`='一天兩次，早上及晚上六點15分，大工匠梅卡托克本人為開桶儀式親臨啤酒節場地。千萬別錯過!', `MaleText_loc7`='El mismísimo Manitas Mayor Mekkatorque viene a la zona de la Fiesta de la Cerveza para la ceremonia de apertura del barril dos veces al día, a las seis y cuarto de la mañana y a las seis y cuarto de la tarde. ¡No te la pierdas!' WHERE `ID`=23874;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='워, 워, 워! 모두 멈추라고, 친구들!', `MaleText_loc4`='哇欧，哇欧，哇欧！伙计们，稳住！', `MaleText_loc5`='嚇啊，嚇啊，嚇啊!先全部停下來，朋友!', `MaleText_loc7`='¡GUAU, GUAU, GUAU! ¡Sujetad todo, tíos!' WHERE `ID`=23875;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드워프들이 모두 큰 소리로 낄낄댑니다.', `MaleText_loc4`='矮人们突然都大笑起来。', `MaleText_loc5`='矮人們爆出笑聲。', `MaleText_loc7`='Todos los enanos rompen a reír.' WHERE `ID`=23876;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맥주통 따기', `MaleText_loc4`='开酒罐仪式', `MaleText_loc5`='開桶儀式', `MaleText_loc7`='La apertura del barril', `FemaleText_loc1`='맥주통 따기', `FemaleText_loc4`='开酒罐仪式', `FemaleText_loc5`='開桶儀式', `FemaleText_loc7`='La apertura del barril' WHERE `ID`=23877;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 바위와 철의 신이시여... 그거... 그걸로 대체 뭘 하겠다는 거야?', `MaleText_loc4`='噢，尊贵的岩石与钢铁领主，您……您打算如何处理呢 ？', `MaleText_loc5`='喔，親愛的石與鐵之主啊，你究竟要...我重申...你究竟要拿它幹嘛?', `MaleText_loc7`='Oh santos señores de piedra y acero, ¿qué... repito... QUÉ vas a hacer con eso?' WHERE `ID`=23878;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하루에 두 번, 아침 여섯 시와 저녁 여섯 시에 어둠사냥꾼 볼진 님이 직접 가을 축제 광장에 나와서 맥주통 따기 행사를 진행합니다. 이런 구경거리를 놓치는 바보는 아니시겠죠?', `MaleText_loc4`='每天两次，分别是在早上6点15分和下午6点15分，暗影猎手沃金会亲自来到美酒节的现场，主持开酒罐仪式。千万别错过！', `MaleText_loc5`='一天兩次，早上及晚上六點15分，暗影獵人沃金本人為開桶儀式親臨啤酒節場地。錯過的是呆子!', `MaleText_loc7`='El mismísimo cazador de las Sombras Vol''jin viene a la zona de la Fiesta de la Cerveza para la ceremonia de apertura del barril dos veces al día, a las seis y cuarto de la mañana y a las seis y cuarto de la tarde. ¡No te la puedes perder!' WHERE `ID`=23879;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 그거론 절대 성공할 수 없어. 무쇠 드워프들이 그런 잡동사니에 속을 리가 없잖아!', `MaleText_loc4`='朋友，这行不通的。铁矮人才不会喜欢那个大家伙！', `MaleText_loc5`='天啊，永遠也別想成功了。鐵矮人從不上這些破銅爛鐵的當!', `MaleText_loc7`='Tío, eso no funcionará. ¡Esos enanos férreos nunca picarán con ese pedazo de chatarra!' WHERE `ID`=23880;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='10분만 지나면 볼진 님의 "맥주통 따기" 행사가 시작됩니다!', `MaleText_loc4`='再过10分钟，沃金就要来主持开酒罐仪式啦！', `MaleText_loc5`='再過10幾分鐘沃金就要打開啤酒節酒桶了!', `MaleText_loc7`='¡Solo quedan 10 minutos para que Vol''jin abra el barril de la Fiesta de la Cerveza!' WHERE `ID`=23881;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='20분 후에 볼진 님의 "맥주통 따기" 행사가 시작됩니다!', `MaleText_loc4`='再过20分钟，沃金就要来主持开酒罐仪式啦！', `MaleText_loc5`='20分鐘後沃金將會打開啤酒節酒桶!', `MaleText_loc7`='¡Dentro de 20 minutos Vol''jin abrirá el barril de la Fiesta de la Cerveza!' WHERE `ID`=23882;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 몰라도 한참 모르는군, 레브론스키! 주제넘은 소리하곤! 무쇠 드워프들은 자기들이 뭐에 당했는지도 모를 거야! 자넨 그 양탄자에 묻은 똥의 비밀이나 파헤치는 거 계속하고, 나 같은 진짜 과학자님께서 하시는 일에는 참견하지 말라고!', `MaleText_loc4`='雷波斯基，不懂就别折腾了！完全没有必要！那些铁矮人不会知道真相的！你不如回去调查到底是谁在你的地毯上捣鬼，这里的工作就交给真正的科学家吧！', `MaleText_loc5`='你真是差勁透了，雷布隆斯基!就是差勁透了!鐵矮人不會知道被什麼東西打中!你何不回去搞清楚你毯子上巨無霸大便的謎團，然後讓正牌的科學家繼續工作!', `MaleText_loc7`='¡Estás fuera de tu elemento, Lebronski! ¡Eres innecesario! ¡Esos enanos férreos no sabrán qué les golpeó! ¡Ahora, por qué no vuelves a dedicarte a desvelar el misterio del gigantesco zurullo de tu alfombra y dejas que los científicos de verdad hagan su trabajo!' WHERE `ID`=23883;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='볼진 님이 출발하셨습니다! 여러분, "맥주통 따기" 행사가 곧 시작됩니다!', `MaleText_loc4`='沃金来了！开酒罐仪式马上就要开始啦！', `MaleText_loc5`='沃金在路上了!「開桶儀式」將於短短幾分鐘後開始!', `MaleText_loc7`='¡Vol''jin está de camino! ¡La "apertura del barril" tendrá lugar dentro de unos minutos!' WHERE `ID`=23884;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='웃겨서 죽을 거 같아! 누가 저 친구 좀 말려줘!', `FemaleText_loc4`='我非常伤心！就别开玩笑了！', `FemaleText_loc5`='我笑到哭出來了!拜託，誰來停止這個笑話!', `FemaleText_loc7`='¡Estoy llorando! ¡Por favor, dejad de ser graciosos!' WHERE `ID`=23885;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='20분 후에 땜장이왕 멕카토크 님의 "맥주통 따기" 행사가 시작됩니다!', `MaleText_loc4`='再过20分钟，大工匠梅卡托克就要来主持开酒罐仪式啦！', `MaleText_loc5`='20分鐘後大工匠梅卡托克將會打開啤酒節酒桶!', `MaleText_loc7`='¡Dentro de 20 minutos el Manitas Mayor Mekkatorque abrirá el barril de la Fiesta de la Cerveza!' WHERE `ID`=23886;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='10분만 지나면 땜장이왕 멕카토크 님의 "맥주통 따기" 행사가 시작됩니다!', `MaleText_loc4`='再过10分钟，大工匠梅卡托克就要来主持开酒罐仪式啦！', `MaleText_loc5`='只要再10分鐘，大工匠梅卡托克將會開啟啤酒節酒桶!', `MaleText_loc7`='¡En tan solo 10 minutos el Manitas Mayor Mekkatorque abrirá el barril de la Fiesta de la Cerveza!' WHERE `ID`=23887;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='땜장이왕 멕카토크 님이 출발하셨습니다! 여러분, "맥주통 따기" 행사가 곧 시작됩니다!', `MaleText_loc4`='大工匠梅卡托克来了！开酒罐仪式马上就要开始啦！', `MaleText_loc5`='大工匠梅卡托克在路上了!「開桶」儀式將於短短幾分鐘後開始!', `MaleText_loc7`='¡El Manitas Mayor Mekkatorque está de camino! ¡La ceremonia de "apertura del barril" comenzará dentro de unos minutos!' WHERE `ID`=23888;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아버지가 살아서 저 꼴을 보셨어야 하는데!', `MaleText_loc4`='要是爸爸能活着看到这一天该多好啊！', `MaleText_loc5`='要是老爸活著看到這一幕就好了!', `MaleText_loc7`='¡Si papi viviera para ver esto!' WHERE `ID`=23889;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 지금 무슨 짓을 하려는 건지 알고나 있나? 나 레브론스키는 자네가 내 양탄자 위로 그 고철덩이를 끌고 다니는 게 싫단 말이네.', `MaleText_loc4`='我说，你知道自己在干什么吗？你竟然拖着那个金属玩意儿踩过雷波斯基的地毯，看我怎么收拾你。', `MaleText_loc5`='你以為你在幹嘛，老兄?雷布隆斯基可沒感謝你叫你的廢鐵在我的毯子上拖來拖去啊。', `MaleText_loc7`='¿Qué crees que estás haciendo, tío? A Lebronski NO le gusta que arrastres tus partes de metal sueltas por su alfombra.' WHERE `ID`=23890;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='굉장한데. 어쩌면 이 고철덩이가 뭔가 해낼지도 모르겠어...', `MaleText_loc4`='很好。这桶螺钉或许能起作用……', `MaleText_loc5`='好極了，老兄。看來這桶螺絲釘畢竟有點用處...', `MaleText_loc7`='Aparta, tío. Puede que este cubo de tornillos lo consiga después de todo...' WHERE `ID`=23891;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무쇠룬 피조물 모델명 U-9207는 당신의 말투가 마음에 들지 않습니다. 양탄자 소멸 작업을 시작합니다, 레브론스키.', `MaleText_loc4`='铁符文构造体U-9207无法识别你的声音。雷波斯基，现在开始摧毁你的地毯。', `MaleText_loc5`='型號U-9207鐵符文傀儡討厭你說話的聲調。雷布隆斯基，對你的毯子進行全面性的摧毀。', `MaleText_loc7`='Al Ensamblaje Runaférrea Modelo U-9207 no le gusta tu tono de voz. Comenzando aniquilación total de tu alfombra, Lebronski.' WHERE `ID`=23892;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='목숨을 잃고 싶지 않으면 *쩔그럭* 저를 따라오십시오.', `MaleText_loc4`='想活命的话*噼啪*就跟着我。', `MaleText_loc5`='如果你還想活命<劈啪>就跟我來。', `MaleText_loc7`='Ven conmigo si *crujido* quieres vivir.' WHERE `ID`=23893;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야벤 썬더브루가 맥주통을 지키고 있습니다. 야벤이 지하실에 있는 동안에는 맥주통에 손도 댈 수 없습니다.', `MaleText_loc4`='加文·雷酒负责看管酒窖。只要他呆在地下室，这些酒桶就十分安全。', `MaleText_loc5`='這桶麥芽酒由加文·雷酒看管著。只要他在地窖裡，誰都別想碰這些麥芽酒桶。', `MaleText_loc7`='Este barril de cerveza está protegido por Jarven Cebatruenos. Mientras él esté en el sótano, ningún barril será molestado.' WHERE `ID`=23894;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경보! 경보! 적들의 방어선 통과가 감지되었습니다! 수가 증가하고 있습니다.', `MaleText_loc4`='警报！警报！构造体检测到敌人已经越过了我们的防线。加速。', `MaleText_loc5`='警報!警報!傀儡感應到敵人破壞了我們的防禦。速度提升。', `MaleText_loc7`='¡Alerta! ¡Alerta! Ensamblaje detecta que los enemigos han atravesado nuestras defensas. Acelerad el ritmo.' WHERE `ID`=23895;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피조물이 임무 보고합니다. 최우선 임무: 감시', `MaleText_loc4`='构造体载体汇报。主要功能：监视。', `MaleText_loc5`='母艦級傀儡回報任務。主要功能:監督作業。', `MaleText_loc7`='Ensamblaje de clase transporte presentándose para trabajar. Función principal: supervisar.' WHERE `ID`=23896;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에는 감시할 대상이 없습니다. 명령에 따라 임무를 계속합니다.', `MaleText_loc4`='未发现异常。继续执行指派的任务。', `MaleText_loc5`='這裡沒什麼好看的，繼續你們各自分配的工作。', `MaleText_loc7`='No hay nada que ver aquí. Continúa con tus tareas asignadas.' WHERE `ID`=23897;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위대한 창조주를 맞이하십시오.', `MaleText_loc4`='向我们的创造者欢呼。', `MaleText_loc5`='所有人向偉大的造物主喝采。', `MaleText_loc7`='¡Aclamen todos al gran creador!' WHERE `ID`=23898;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피조물의 작업에 방해되는 요인은 모두 제거합니다. 해산하십시오.', `MaleText_loc4`='胡乱调用构造体的功能将导致程序终结。前进。', `MaleText_loc5`='直到傀儡終止行動以前，要不斷的妨礙它的運作，快去吧。', `MaleText_loc7`='Interferir en las funciones de ensamblaje tiene como resultado la aniquilación. Muévete.' WHERE `ID`=23899;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무쇠 드워프는 피조물에게 질문할 수 없습니다. 파괴 작업을 진행합니다.', `MaleText_loc4`='构造体不解答铁矮人提出的任何问题。启动摧毁程序。', `MaleText_loc5`='鐵矮人的僕從絕不能質疑傀儡。進行解構。', `MaleText_loc7`='Ensamblaje no ha de ser cuestionado por sirviente hierro férreo. Comenzar deconstrucción.' WHERE `ID`=23900;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피조물은 하급 존재들과 대화하도록 승인되지 않았습니다. 하급 존재들은 생산량을 두 배로 높여야 합니다.', `MaleText_loc4`='构造体不得与低等生物交谈。低等生物必须努力工作。', `MaleText_loc5`='傀儡並未授權與低等生物溝通。生物必須加倍努力。', `MaleText_loc7`='Ensamblaje no está autorizado a hablar con seres inferiores. El ser ha de doblar sus esfuerzos.' WHERE `ID`=23901;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지갑을 분실하셨습니까? 피조물이 화폐로 가득 찬 지갑을 발견했습니다.', `MaleText_loc4`='你丢了钱包？构造体找到了装满金币的钱包。', `MaleText_loc5`='你的皮夾掉了?傀儡發現了有著過剩貨幣的皮夾。', `MaleText_loc7`='¿Has perdido la cartera? Ensamblaje ha encontrado una cartera con exceso de efectivo.' WHERE `ID`=23902;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정지! 신분을 밝혀라!', `MaleText_loc4`='站住！立即出示身份证明！', `MaleText_loc5`='站住!立刻表明身分!', `MaleText_loc7`='¡Alto! ¡Identifícate inmediatamente!' WHERE `ID`=23903;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 구역은 출입 금지다!', `MaleText_loc4`='这里禁止入内！', `MaleText_loc5`='這裡是禁區!', `MaleText_loc7`='¡Esta es una sección no autorizada!' WHERE `ID`=23904;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 같은 친구는 처음 보는데...', `MaleText_loc4`='我没见过你这样的家伙。', `MaleText_loc5`='這附近我可從沒見過你。', `MaleText_loc7`='Nunca he visto a ninguno de ustedes por aquí.' WHERE `ID`=23905;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기다려라! 멈춰!', `MaleText_loc4`='喂！站住！', `MaleText_loc5`='不准動!停止!', `MaleText_loc7`='¡Basta! ¡Para!' WHERE `ID`=23906;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정지!! 정지!! 이젠 고철들이 저절로 움직이나?', `MaleText_loc4`='站住！！站住！！废铁现在会自己移动了？', `MaleText_loc5`='停!!停啊!!!破銅爛鐵自己長腳跑了?', `MaleText_loc7`='¡¡Para!! ¡¡Para!! ¿La chatarra ahora se mueve sola?' WHERE `ID`=23907;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='틀렸어!', `MaleText_loc4`='回答错误！', `MaleText_loc5`='答錯了!', `MaleText_loc7`='¡Respuesta incorrecta!' WHERE `ID`=23908;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='즐거웠다, $n. 정말 즐거웠어...', `MaleText_loc4`='很好，$n。非常好……', `MaleText_loc5`='演得好，$n，演得好，真的...', `MaleText_loc7`='Bien jugado, $n. Sin duda, bien jugado...' WHERE `ID`=23909;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래... 미안하군. 어디까지 얘기했지?', `MaleText_loc4`='好吧……是我的错。我这是在哪儿？', `MaleText_loc5`='好啦...我的錯。我剛說到哪兒了?', `MaleText_loc7`='Vale... fallo mío. ¿Por dónde iba?' WHERE `ID`=23910;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 위대한 창조자를 맞이하라!', `MaleText_loc4`='为伟大的创造者欢呼吧！', `MaleText_loc5`='所有人向偉大的造物主喝采!', `MaleText_loc7`='¡Aclamen todos al gran creador!' WHERE `ID`=23911;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론 그 말이 맞아. 계속하지.', `MaleText_loc4`='你当然是对的。继续。', `MaleText_loc5`='當然啦，你說的沒錯，請繼續。', `MaleText_loc7`='Tienes razón, por supuesto. Continúa.' WHERE `ID`=23912;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무례를 용서하시오!', `MaleText_loc4`='原谅我的傲慢！', `MaleText_loc5`='請恕我失禮!', `MaleText_loc7`='¡Disculpa mi insolencia!' WHERE `ID`=23913;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='창조자의 전언을 가지고 왔나?', `MaleText_loc4`='你是替创造者传话的吗？', `MaleText_loc5`='你從造物者那兒帶來了什麼口信?', `MaleText_loc7`='¿Traes un mensaje del creador?' WHERE `ID`=23914;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두 배로 일해야겠군!', `MaleText_loc4`='我们会加倍努力的！', `MaleText_loc5`='我們會加倍努力的!', `MaleText_loc7`='¡Doblaremos nuestros esfuerzos!' WHERE `ID`=23915;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='작업을 계속해야 한다. 생산량을 두 배로 올려라.', `MaleText_loc4`='继续工作。努力工作。', `MaleText_loc5`='工作一定要繼續，加倍努力。', `MaleText_loc7`='El trabajo ha de continuar. Doblen sus esfuerzos.' WHERE `ID`=23916;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그분은 모든 것을 보고 계신다.', `MaleText_loc4`='什么都瞒不过布隆特斯。', `MaleText_loc5`='布隆特什麼都知道。', `MaleText_loc7`='Brontes lo ve todo.' WHERE `ID`=23917;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빈둥거리지 마라.', `MaleText_loc4`='不要到处闲逛。', `MaleText_loc5`='不准打混。', `MaleText_loc7`='No holgazaneéis.' WHERE `ID`=23918;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해체 작업을 계속한다.', `MaleText_loc4`='继续摧毁。', `MaleText_loc5`='繼續破壞。', `MaleText_loc7`='Continuad con la desconstrucción.' WHERE `ID`=23919;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지원군이 이동 중이다. 기능이 저하되어서는 안 된다.', `MaleText_loc4`='援军正在途中。确保功能正常。', `MaleText_loc5`='援軍派遣中，功能不能終止。', `MaleText_loc7`='Refuerzos en camino. La función no debe disminuir.' WHERE `ID`=23920;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='토석인 침입자를 제거한다.', `MaleText_loc4`='消灭土灵入侵者。', `MaleText_loc5`='摧毀土靈的侵擾。', `MaleText_loc7`='Destruir infestación terrenal.' WHERE `ID`=23921;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오너라, 하인들아! 네 주인이 명한다!', `MaleText_loc4`='侍从们，过来吧！主人在召唤你们！', `MaleText_loc5`='快來，嘍囉們!主人呼喚你們!', `MaleText_loc7`='¡Vengan, esbirros! ¡Su maestro los llama!' WHERE `ID`=23922;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭풍우 봉우리에서 너희 형제가 하는 일이 매우 빠른 속도로 진행되고 있다. 머지않아 아버지께서 자유로워질 것이다.', `MaleText_loc4`='你在风暴峭壁的同胞的工作日趋白热化。很快，我们的创造者就能重获自由了。', `MaleText_loc5`='你的兄弟們在風暴群山的工作進度，已經接近到了瘋狂的速度。要不了多久，父親就會重獲自由了。', `MaleText_loc7`='El trabajo de tu hermanos en Las Cumbres Tormentosas ha alcanzado un ritmo frenético. Pronto, padre será liberado.' WHERE `ID`=23923;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='북쪽의 너희 형제가 돌 괴수를 굴복시켜 울두아르로 가는 길에 배치했다. 머지않아 판테온의 나머지 방어군도 제거될 것이다.', `MaleText_loc4`='你在北方的同胞已经征服了那些石头怪物，指挥他们朝奥杜尔前进。很快，万神殿剩余的防御力量就会被消灭。', `MaleText_loc5`='你北方的弟兄們征服了石巨獸，還把牠們安置在通往奧杜亞的必經之路上。很快的，萬神殿的殘兵就會被殲滅了。', `MaleText_loc7`='Tus hermanos del norte han subyugado behemoths de piedra y los han puesto en camino hacia Ulduar. Pronto, las defensas restantes del Panteón serán neutralizadas.' WHERE `ID`=23924;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필멸의 존재들이 이 지역에서 만든 세 균열은 반드시 봉해야 한다. 그렇지 않으면 대지가 우리의 작업을 보고 들어, 끊임없이 우리를 방해할 것이다.', `MaleText_loc4`='我们必须设法封锁凡人在这片区域开启的三条裂隙。大地能知晓我们的所作所为。如果不能关闭地表的裂缝，它就会继续妨碍我们的宏伟计划。', `MaleText_loc5`='這三座由這兒的凡人所開啟的縫隙一定要被封鎖起來。大地聽得見也看得見我們的一舉一動，如果道路不關閉，也將繼續干預我們的進度。', `MaleText_loc7`='Las tres fisuras abiertas por los mortales en esta región han de ser silenciadas. La tierra ve y oye lo que hacemos y seguirá dificultando nuestros esfuerzos si la vía no es cortada.' WHERE `ID`=23925;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳을 파묻어라! 네 주인이 명한다!', `MaleText_loc4`='把这里埋了！这是主人的命令！', `MaleText_loc5`='把這個地方埋起來!你的主人命令你!', `MaleText_loc7`='¡Entierren este lugar! ¡Su maestro lo ordena!' WHERE `ID`=23926;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천둥소리가 동굴 곳곳에 울려 퍼집니다.', `MaleText_loc4`='雷鸣声响彻整个山洞。', `MaleText_loc5`='雷聲傳遍了整座洞窟。', `MaleText_loc7`='El sonido del trueno retumba en la caverna.' WHERE `ID`=23927;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천둥소리가 점점 사라집니다.', `MaleText_loc4`='雷鸣声逐渐减弱了。', `MaleText_loc5`='雷聲消散了。', `MaleText_loc7`='El sonido del trueno se disipa.' WHERE `ID`=23928;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비됐습니다, 왈트.', `MaleText_loc4`='我准备好了，沃尔特。', `MaleText_loc5`='渥特，我準備好出發了。', `MaleText_loc7`='Estoy listo para ir, Walt.', `FemaleText_loc1`='준비됐습니다, 왈트.', `FemaleText_loc4`='我准备好了，沃尔特。', `FemaleText_loc5`='渥特，我準備好出發了。', `FemaleText_loc7`='Estoy lista para ir, Walt.' WHERE `ID`=23929;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='작동 체계가 곧 정지됩니다. 3... 2...', `MaleText_loc4`='系统故障。3……2……', `MaleText_loc5`='系統錯誤將於3秒...2秒...', `MaleText_loc7`='Fallo del sistema en 3... 2...' WHERE `ID`=23930;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='먹어라, 형제들아!', `MaleText_loc4`='尽情享用吧，兄弟们！', `MaleText_loc5`='盡情享用吧，兄弟們!', `MaleText_loc7`='¡Aliméntense, hermanos míos!' WHERE `ID`=23931;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='작동 체계가 정지되었습니다. *철컥*', `MaleText_loc4`='系统故障*滴答*', `MaleText_loc5`='系統錯誤<喀啦>', `MaleText_loc7`='El sistema está fallando *clic*' WHERE `ID`=23932;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곧 추락합니다. *쿵*', `MaleText_loc4`='即将坠毁*咣*', `MaleText_loc5`='即將當機<?噹>', `MaleText_loc7`='Fallo inminente *clonk*' WHERE `ID`=23933;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피조물이 정지합니다. *삑*', `MaleText_loc4`='构造体即将关闭*哔*', `MaleText_loc5`='傀儡離線<嗶>', `MaleText_loc7`='Ensamblaje desconectándose *bip*' WHERE `ID`=23934;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='*딸각* 비행 체계에 오류가 발생했습니다. *철커덩*', `MaleText_loc4`='*滴答*飞行系统故障*哐*', `MaleText_loc5`='<喀啦>飛行系統異常<?噹>', `MaleText_loc7`='*clic* Fallo en los sistemas de vuelo *clang*' WHERE `ID`=23935;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필멸의 존재여, 잠시 제 말을 들으십시오.', `MaleText_loc4`='等等，凡人，我有话和你说。', `MaleText_loc5`='等一等，凡人，請你聆聽我的話語。', `MaleText_loc7`='Quietos, mortales y escuchad mis palabras.' WHERE `ID`=23936;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 수정구를 들여다보니 마음을 이끄는 친근한 힘이 느껴집니다.', `MaleText_loc4`='当你凝视宝珠时，你感到一股熟悉的力量正在影响你的思绪。', `MaleText_loc5`='當你凝視著寶珠，你感覺到一股熟悉的力量在你的心靈中拉扯。', `MaleText_loc7`='Al mirar dentro del orbe, sientes una fuerza familiar arrastrando tu mente.' WHERE `ID`=23937;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수정구가 이끄는 대로 몸을 맡깁니다...', `MaleText_loc4`='让宝珠引导你的思绪……', `MaleText_loc5`='讓寶珠引領你前往...', `MaleText_loc7`='Permite que el orbe te lleve...', `FemaleText_loc1`='수정구가 이끄는 대로 몸을 맡깁니다...', `FemaleText_loc4`='让宝珠引导你的思绪……', `FemaleText_loc5`='讓寶珠引領你前往...', `FemaleText_loc7`='Permite que el orbe te lleve...' WHERE `ID`=23938;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직은 수정구에 맞게 조율되지 않았습니다.', `MaleText_loc4`='你还不能和占卜宝珠产生共鸣。', `MaleText_loc5`='你尚未與占卜寶珠同調。', `MaleText_loc7`='Aún no estás armonizado con el orbe de visión.' WHERE `ID`=23939;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='눈앞에 있는 수정구에 정신을 집중하니 서서히 마음이 열립니다...', `MaleText_loc4`='你凝视着面前的宝珠，思绪渐渐飘散……', `MaleText_loc5`='當你專注於眼前的寶珠時，你的心靈逐漸開放...', `MaleText_loc7`='Tu mente se va abriendo gradualmente a medida que te concentras en el orbe ante ti...' WHERE `ID`=23940;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭍입니다, 코왈스키 일등항해사님! 항구가 보입니다!', `MaleText_loc4`='是陆地，科瓦斯基先生！港口就在前方，长官！', `MaleText_loc5`='有島嶼，可沃斯基先生!看到港口了，長官!', `MaleText_loc7`='¡Tierra a la vista, Sr. Kowalski! ¡Puerto a la vista, señor!' WHERE `ID`=23941;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수고했다, 헨더스.', `MaleText_loc4`='谢谢你，亨德尔先生。', `MaleText_loc5`='感謝你，漢德斯先生。', `MaleText_loc7`='Gracias, Sr. Henders.' WHERE `ID`=23942;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='입항하시오, 메란 항해사.', `MaleText_loc4`='梅拉先生，请你驶向港口。', `MaleText_loc5`='請帶我們入港，梅朗先生。', `MaleText_loc7`='Llévenos al puerto, Sr. Mehran.' WHERE `ID`=23943;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뒷주머니 선장님! 곧 항구에 도착합니다!', `MaleText_loc4`='托格雷船长！我们即将抵达目的地，长官！', `MaleText_loc5`='小鬍子船長!我們馬上就要抵達了，長官!', `MaleText_loc7`='¡Capitán Alijo! ¡Pronto llegaremos, señor!' WHERE `ID`=23944;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙네, 코왈스키! 자리로 돌아가 배가 제대로 정박하는지 감독하게!', `MaleText_loc4`='谢谢你，科瓦斯基先生！你可以回去继续监督进港情况了！', `MaleText_loc5`='感謝你，可沃斯基先生!你可以回到你的崗位去監督船隻靠岸了。', `MaleText_loc7`='¡Gracias, Sr. Kowalski! ¡Puede volver a su puesto para supervisar el atraque!' WHERE `ID`=23945;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 수고했다. 다음 항구까지 안전하게 항해하자.', `MaleText_loc4`='干得好。请把我们安全带到下一个港口吧。', `MaleText_loc5`='幹得好，大家。請帶領我們安穩到達我們的下一個港口吧。', `MaleText_loc7`='Bien hecho a todos. Llévenos sanos y salvos a nuestro próximo puerto.' WHERE `ID`=23946;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뒷주머니 선장님이 최고라고요!', `MaleText_loc4`='托格雷船长是最棒的！', `MaleText_loc5`='小鬍子船長是最棒的!', `MaleText_loc7`='¡El capitán Alijo es el MEJOR!' WHERE `ID`=23947;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 갑판을 청소했어요!', `MaleText_loc4`='我在拖洗甲板！', `MaleText_loc5`='我打掃甲板!', `MaleText_loc7`='¡Yo friego las cubiertas!' WHERE `ID`=23948;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멜리호는 세상에서 제일 멋진 배지요!', `MaleText_loc4`='梅蕾女士号永远是最棒的船！', `MaleText_loc5`='梅利女士號是有史以來最棒的船!', `MaleText_loc7`='¡El Lady Mehley es el mejor barco DE TODOS!' WHERE `ID`=23949;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갑판을 청소하며 햇볕을 쬐어서 구루병이 다 나았어요!', `MaleText_loc4`='拖洗甲板治好了我的驼背！', `MaleText_loc5`='打掃甲板治好了我的駝背!', `MaleText_loc7`='¡Fregar cubiertas me curó el raquitismo!' WHERE `ID`=23950;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예, 알겠습니다. 코왈스키 일등항해사님.', `MaleText_loc4`='是，是，科瓦斯基先生。', `MaleText_loc5`='明白了，可沃斯基先生。', `MaleText_loc7`='Sí, sí, señor Kowalski.' WHERE `ID`=23951;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시대가 변하고 있습니다, $n. 전쟁이 닥쳐왔어요.$B$B과연 우리 쿠레나이가 그에 맞서 일어나 동지들을 도울 것인가... 아니면 한 쪽 구석에서 주저하고만 있을까요?', `MaleText_loc4`='形势正在发生变化，$n。战争开始了。$B$B是让我们的人民抓住机遇去帮助盟友们……还是在一旁静观局势发展呢？', `MaleText_loc5`='時代改變了，$n。戰爭來臨了。$B$B我的族人會在這個時機崛起並且協助我們的盟友...或是我們會繼續在邊緣苟延?', `MaleText_loc7`='Los tiempos cambian, $n. La guerra ha llegado.$B$B¿Se alzará nuestra gente en esta ocasión y ayudará a nuestros aliados... o nos quedaremos al margen?' WHERE `ID`=23952;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='승객분과 대화를 나눌 시간이 별로 없습니다. 죄송합니다.', `MaleText_loc4`='对不起，我没时间闲聊。', `MaleText_loc5`='我沒有什麼時間可以聊天，抱歉。', `MaleText_loc7`='No tengo tiempo para hablar, lo siento.' WHERE `ID`=23953;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 일하는 게 안 보이시나요? 코왈스키씨가 저한테 설교를 늘어놓기 전에 저리 가세요.', `FemaleText_loc4`='没看见我正忙着吗？离我远点，别让科瓦斯基撞见了。', `FemaleText_loc5`='你沒看到我正在這裡忙嗎，$g小夥子:姑娘;?在被可沃斯基看到我在閒聊之前，快滾。', `FemaleText_loc7`='¿No ves que estoy trabajando $gchico:chica;? Lárgate antes de que Kowalski me vea charlando.' WHERE `ID`=23954;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='항해하기 좋은 날씨로군요, 그렇지요?', `MaleText_loc4`='真是个启航的好日子，对吧？', `MaleText_loc5`='啟航的好日子，對吧?', `MaleText_loc7`='Un buen día para navegar, ¿verdad?' WHERE `ID`=23955;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='토골리 선장님은 일을 잔뜩 시킨다니까요... 하지만 좋은 선장님이긴 해요. 그럼요, 그렇고 말고요.', `MaleText_loc4`='在托格雷手下做事非常辛苦，不过他是位好船长。', `MaleText_loc5`='多茍利對我們很嚴格，不過他是個好船長，沒錯。', `MaleText_loc7`='Torgoley nos hace trabajar duro, pero es un buen capitán.' WHERE `ID`=23956;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 우리 중에 남은 이가 별로 없소, $n. 오랜 적이 돌아온다는 건 우리로서는 정말 심각한 문제라오.', `MaleText_loc4`='我们剩下的人不多了，$n。宿敌的回归让我们忧虑万分。', `MaleText_loc5`='我們已經沒剩多少人了，$n。我們古老宿敵的回歸令人非常擔憂。', `MaleText_loc7`='No quedamos muchos, $n. El regreso de nuestro viejo enemigo es motivo de gran preocupación.' WHERE `ID`=23957;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 배와 선원들에게서 눈을 떼면 안 되오. 당신과 대화를 나누지 못하는 결례를 용서하시리라 믿소.', `MaleText_loc4`='我得密切注意船只和船员的情况。请原谅我不能和你闲聊。', `MaleText_loc5`='我必須得盯牢這艘船及船員，好心的$g先生:女士;。你一定要原諒我無法停下來跟你進行交談。', `MaleText_loc7`='Debo prestar atención al barco y a la tripulación, $gbuen hombre:buena mujer;. Perdona que no me pare a hablar contigo.' WHERE `ID`=23958;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멜리호는 테라모어 가까이에 있소. 우린 멜리호의 승객들을 보호하는 일을 맡고 있소.', `MaleText_loc4`='梅蕾女士号长期停靠塞拉摩岛，我们奉命保护船只上的乘客。', `MaleText_loc5`='梅利女士號真的就在塞拉摩，我們已經被指派去守衛船上的乘客了。', `MaleText_loc7`='El Lady Mehley pasa tanto tiempo en Theramore que nos han encargado que cuidemos de sus pasajeros.', `FemaleText_loc1`='멜리호는 테라모어 가까이에 있어요. 저희는 멜리호의 승객들을 보호하는 일을 맡고 있지요.', `FemaleText_loc4`='梅蕾女士号长期停靠塞拉摩岛，我们奉命保护船只上的乘客。', `FemaleText_loc5`='梅利女士號真的就在塞拉摩，我們已經被指派去守衛船上的乘客了。', `FemaleText_loc7`='El Lady Mehley pasa tanto tiempo en Theramore que nos han encargado que cuidemos de sus pasajeros.' WHERE `ID`=23959;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 웅장한 멜리호에 타신 것을 환영합니다. 저는 이 배의 선장인 토골리라고 합니다.$b$b이 배와 관련해서 궁금하신 게 있으시다면, 편하게 말씀하십시오. 더 하실 말씀이 없으시다면, 부디 이번 여행을 즐겨 주시기 바랍니다. 제가 늘 즐겁게 여행하듯이 말이죠... 제가 좋아하는 구절 하나 말씀드리자면 이렇습니다.$b$b배에 대한 경험이란 그 위에 올라 세상을 흥미롭게 발견해 나가는 것이다. 무언가가 없어도 완벽히 해나갈 수 있음을 발견하는 것이다.', `MaleText_loc4`='欢迎乘坐梅蕾女士号。我是船长托格雷。$b$b我负责解答所有关于这艘船的疑问，并祝愿大家旅途愉快。就像我喜欢的座右铭那样：对我来说，船只的意义在于带你游历全世界。没有它，你就无法享受这样美妙的体验。', `MaleText_loc5`='歡迎來到雄偉的梅利女士號。我是多茍利船長。$b$b如果你對這艘船有任何的疑問，請盡情提問;其他，則請好好享受這趟旅程，一同我一直以來的一樣...最後，容我引述一段我最喜愛的內容:我的航船經驗就是，一個人能夠在這些船上發覺這世界有趣的一面。也有人不需藉此就能完全做到。', `MaleText_loc7`='Te doy la bienvenida al majestuoso Lady Mehley. Soy el capitán Torgoley.$B$BSi tienes preguntas acerca del barco formúlalas, si no, disfruta del viaje como yo siempre hago... Después de todo, citando a uno de mis escribas favoritos: Mi experiencia con los barcos es que en ellos uno realiza interesantes descubrimientos acerca del mundo. Descubre que puede vivir sin él.' WHERE `ID`=23960;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멜리호', `MaleText_loc4`='梅蕾女士号', `MaleText_loc5`='梅利女士號', `MaleText_loc7`='El Lady Mehley', `FemaleText_loc1`='멜리호', `FemaleText_loc4`='梅蕾女士号', `FemaleText_loc5`='梅利女士號', `FemaleText_loc7`='El Lady Mehley' WHERE `ID`=23961;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음식과 음료', `MaleText_loc4`='食物和饮料', `MaleText_loc5`='食物和飲料', `MaleText_loc7`='Comida y bebida', `FemaleText_loc1`='음식과 음료', `FemaleText_loc4`='食物和饮料', `FemaleText_loc5`='食物和飲料', `FemaleText_loc7`='Comida y bebida' WHERE `ID`=23962;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물건 구입과 수리', `MaleText_loc4`='物品和装备', `MaleText_loc5`='物品和工具', `MaleText_loc7`='Bienes y equipo', `FemaleText_loc1`='물건 구입과 수리', `FemaleText_loc4`='物品和装备', `FemaleText_loc5`='物品和工具', `FemaleText_loc7`='Bienes y equipo' WHERE `ID`=23963;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"뒷주머니라니 무슨 뜻이지요?"', `MaleText_loc4`='“鼠胆船长”？', `MaleText_loc5`='「小鬍子?」', `MaleText_loc7`='"¿Alijo?"', `FemaleText_loc1`='"뒷주머니라니 무슨 뜻인가요?"', `FemaleText_loc4`='“鼠胆船长”？', `FemaleText_loc5`='「小鬍子?」', `FemaleText_loc7`='"¿Alijo?"' WHERE `ID`=23964;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 멜리호가 바로 이 배의 이름입니다, 정말 좋은 배죠.$B$B아시겠지만 이런 배는 여러 가지를 배우게 된답니다. 어떤 훌륭한 시인이 이런 말을 했었죠. ''밤에 움직이는 배는 신호 하나만을 켠 채 어둠 속에서도 들리는 목소리만 가지고 멀리서 서로 지나쳐갈 때 대화를 나눈다.'' 삶의 바다라는 것도 그렇지요. 누군가와 스치고 지나가고 대화를 나누지만, 보기만 하고 목소리만 듣는 거지요. 그리고 그 후에는 다시 어둠이, 침묵이 밀려오는 거랍니다.', `MaleText_loc4`='是呀，梅蕾女士号，她是一艘很漂亮的船。$b$b你知道，呆在船上能学到很多知识的。有首诗说得好：苍茫黑夜中两只落寞行船，擦身而过时互相道安，风笛长鸣，堪堪见到模糊的形，片刻后却只余远去的影；人生亦如这广阔的洋，你我的船不期中徜徉而遇，彼此仅是浅烙下容与音，即又遁入黑暗与寂静。', `MaleText_loc5`='是，那就是她的名字，她真是艘好船。$b$b你知道的，還有好多東西可以從這些船艦上學習。一個偉大的詩人曾說:在夜晚穿行的船隻，交錯時彼此傾訴，只有一個暗號，一聲黑暗中的遠音;就像在生命的汪洋中，我們擦肩時互語，只有一顧，只有一言，接著黑暗再臨，寂默再現。', `MaleText_loc7`='Sí, ese es su nombre y es un buen barco.$B$BHay mucho que aprender de ese tipo de naves, ya sabes. Un gran poeta dijo una vez: Los barcos pasan en la noche y se comunican con solo pasar, solo una señal y una voz lejana en la oscuridad. Así que, en la vida en el océano, pasamos y nos comunicamos con solo una mirada y una voz, la oscuridad de nuevo y el silencio.' WHERE `ID`=23965;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭔가 드시고 싶다면, 그레이스 주방장이 입맛에 맞게 요리해드릴 겁니다.', `MaleText_loc4`='肚子饿的话，可以找厨师长格莱斯。', `MaleText_loc5`='如果你想要點什麼的話，船艙長葛蕾絲可以滿足你的需求。', `MaleText_loc7`='Si deseas sustento, la jefa de galera Grace puede ayudarte.' WHERE `ID`=23966;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 부탁하시든 이 배의 기술자이자 배급담당인 코움스 씨가 가져다 드릴 겁니다. 게다가 무엇이든 척척 고칠 수 있으니, 손볼 게 있으면 말씀하십시오.', `MaleText_loc4`='考布斯先生是随船的工程师和军需官，他出售各种你可能需要的物资。若是你想要修理装备的话，也可以找他哦，他技术不错的。', `MaleText_loc5`='這艘船的工程師及軍需官，康伯斯先生，可以提供任何你可能需要的物品。要是你的引擎需要維修的話，他也是一位技術不錯的修補工。', `MaleText_loc7`='El señor Combs, el ingeniero e intendente del barco puede proporcionarte cualquier suministro que necesites. También es un gran manitas si necesitas reparar tu equipo.' WHERE `ID`=23967;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 네, 그... 그 이름요. 글쎄요... 사람들 말로는, 명성은 선의와 마찬가지로, 쌓을 때는 노력을 많이 해야 하지만 무너지는 건 한순간이라고 하더군요. 어떻게 그런지, 또 왜 그런지까지 아실 필요는 없겠지요. 제가 그런 이름을 갖게 된 사연은 그냥 이 정도에서 끝냅시다.', `MaleText_loc4`='啊，是啊……这个名字。嗯……人们常说，好名字就像美好的愿望，你需要用心经营，却很可能因一次失误前功尽弃。至于我的名字的由来嘛，不用说也知道为什么别人这么称呼我吧……', `MaleText_loc5`='啊，沒錯，那個...名字。嗯...如同他們說的，是個好名字，就像信譽一樣，一點小差錯就會毀掉許多的努力。不需要去深究方法及理由;只要說，那就是我為何會被某些人如此稱呼的原因就好了。', `MaleText_loc7`='Ah, sí, eso... el nombre. Bueno... dicen que un buen nombre, como la buena voluntad, se consigue mediante muchas acciones y se pierde con solo una. No vale la pena entrar en detalles de cómo o por qué, digamos, sin más, que así es como me llaman algunos.' WHERE `ID`=23968;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='망자가 일어나 감히 그들의 땅을 지나려는 자들에게 복수하려고 합니다. 돌아가세요!', `MaleText_loc4`='亡者已经复苏，任何敢于穿越亡者领地的人都会遭到疯狂的报复。回去吧！', `MaleText_loc5`='死者復活，並對那些膽敢侵入他們領域的生物復仇，回頭吧!', `MaleText_loc7`='Los muertos se levantan y buscan vengarse de cualquiera que se atreva a pasar por sus dominios. ¡Volved atrás!' WHERE `ID`=23969;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파헤쳐진 땅에서 성스러운 물건을 도둑맞았다. 애시리테스의 방패를 잃어버렸다. 안식은 영원히 오지 않을 것이다.', `MaleText_loc4`='大地开裂，神器失窃。古神之盾已经遗失。混乱将会笼罩世界。', `MaleText_loc5`='在這片破碎的地面上，聖徽不翼而飛。阿薩瑞特之盾失蹤。動盪將難以停止。', `MaleText_loc7`='El sacramento fue robado sobre suelo destrozado. El escudo de los Aesirites se ha perdido. El malestar será eterno.' WHERE `ID`=23970;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭풍 강타 지팡이를 도둑맞았다. 이 땅에 저주를! 폭풍은 절대로 멎지 않을 것이다!', `MaleText_loc4`='风暴愤怒法杖被盗。这片大陆遭到了诅咒！风暴永远不会停息！', `MaleText_loc5`='風暴之怒法杖被盜走了。詛咒降下這片大地!風暴將永不止息!', `MaleText_loc7`='Han hurtado el bastón de la Furia de la Tormenta. ¡Una maldición sobre esta isla! ¡Las tormentas nunca cesarán!' WHERE `ID`=23971;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이술도프의 얼어붙은 심장은 제자리에 돌아올 때까지 이 땅을 괴롭힐 것이다. 심장을 움켜쥔 자는 얼어붙은 피의 저주에 쫓겨 고통받으리라...', `MaleText_loc4`='除非伊斯多弗的冰冷之心归位，否则它迟早会吞噬这片大陆。但凡拥有它的人，无一例外地被冰冷鲜血诅咒所困扰，为他们的痛楚默哀吧……', `MaleText_loc5`='不把伊蘇鐸夫的冰凍心臟還回去的話，會把整片大地吞噬的。當冰凍血液的詛咒侵擾著他們，悲慘命運降臨在握有心臟的人身上...', `MaleText_loc7`='El corazón congelado de Isuldof consumirá esta tierra hasta que sea devuelto. Malditos sean quienes guardan el corazón pues la maldición de la sangre helada les persigue...' WHERE `ID`=23972;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크발디르의 고대 갑옷을 입으려는 어리석은 자에게 백만 년간의 고통 있으리라. 안개와 연기를 조심하라, 필멸의 존재들이여. 종말이 너희를 찾아올 것이니.', `MaleText_loc4`='那些试图穿上克瓦迪尔的上古甲胄的蠢货将会尝到无尽的痛苦。凡人，当心这片迷雾，你很可能丢掉性命。', `MaleText_loc5`='千年的苦痛等待著蠢人穿上這件科瓦迪爾的上古盔甲。凡人，小心霧靄;它們將帶來你的末日。', `MaleText_loc7`='La angustia de diez mil años aguarda a cualquier insensato que se ponga la antigua armadura de los Kvaldir. Tengan cuidado con la niebla y la bruma, mortales, pues con ellas se acerca su fin.' WHERE `ID`=23973;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 운이 좋아요. 이런 범선의 선장 급사는 아무 타우렌이나 하는 게 아니니까요! 그레직스 님은 이 끝내주는 전투 통나무배까지 몰게 해주셨다고요.', `MaleText_loc4`='我真幸运。没几个牛头人能成为护卫舰的船员的！格雷兹克斯甚至让我操纵这些不可思议的战斗快艇。', `MaleText_loc5`='我很幸運。沒有多少牛頭人可以在這樣的護衛艦上當船艙服務員好嗎!格瑞希克斯甚至派我來管這些不可思議的戰鬥獨木舟呢。', `MaleText_loc7`='Tuve suerte. ¡No muchos tauren llegan a moso de camarote en una fragata como esta! Y Grezzix me deja encargarme de estas increíbles canoas de batalla.' WHERE `ID`=23974;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='농담 따먹기나 할 시간이 없단다, 루. 해적 야영지로 보내 줘.', `MaleText_loc4`='我没功夫和你闲聊，洛伊。带我去无赖港。', `MaleText_loc5`='我沒時間跟你磨牙了，阿路，帶我去無賴角。', `MaleText_loc7`='No tengo tiempo pa charlal, Lou. Llévame tú al Cabo Pillastre.', `FemaleText_loc1`='농담 따먹기나 할 시간이 없어, 루. 해적 야영지로 보내 주렴.', `FemaleText_loc4`='我没功夫和你闲聊，洛伊。带我去无赖港。', `FemaleText_loc5`='我沒時間跟你磨牙了，阿路，帶我去無賴角。', `FemaleText_loc7`='No tengo tiempo pa charlal, Lou. Llévame tú al Cabo Pillastre.' WHERE `ID`=23975;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='브리쿨의 분노가 너를 삼킬 것이다!', `MaleText_loc4`='维库人的怒火将吞噬你！', `MaleText_loc5`='維酷人的怒火將會吞噬你!', `MaleText_loc7`='¡La furia de los vrykuls os consumirá!' WHERE `ID`=23976;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 힘이 온몸에 넘쳐 흐른다! 나는 이제 신이다!', `MaleText_loc4`='它的能量在我体内流淌！我是神！！！', `MaleText_loc5`='它的能量充滿了我全身上下!我就是神!', `MaleText_loc7`='¡Su poder fluye dentro de mí! ¡SOY UN DIOS!' WHERE `ID`=23977;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='압둘은 황소처럼 튼튼하지!', `MaleText_loc4`='阿卜杜尔像牛一样强壮！！', `MaleText_loc5`='阿巴督爾壯得跟牛一樣!', `MaleText_loc7`='¡ABDUL ES FUERTE COMO UN TORO!' WHERE `ID`=23978;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게 도전하겠다고? 17대 1이라도 문제없다!', `MaleText_loc4`='你想挑战我？我拥有十倍于常人的力量！！！！', `MaleText_loc5`='你這是在挑戰我嗎?我擁有十個人的力量!', `MaleText_loc7`='¿ME ESTÁS RETANDO? ¡TENGO LA FUERZA DE DIEZ HOMBRES!' WHERE `ID`=23979;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈이 감히! 이 압둘이 그 머리를 창끝에 매달아주마!', `MaleText_loc4`='你这不怕死的蠢货！阿卜杜尔要让你知道厉害的！', `MaleText_loc5`='大膽!阿巴督爾要把你的頭插在長矛上!', `MaleText_loc7`='¿CÓMO TE ATREVES? ¡ABDUL PONDRÁ TU CABEZA EN UNA LANZA!' WHERE `ID`=23980;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나를... 도와주오! 더는... 버틸 수가... 없어!', `MaleText_loc4`='我……需要你们的……帮助！我……快支持不住了！', `MaleText_loc5`='我...需要你們的...幫助!我...快支持不住了!', `MaleText_loc7`='¡Necesito... su ayuda! ¡No aguantaré mucho más!' WHERE `ID`=23981;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으아아악! 내 정신을 지켜주시오!', `MaleText_loc4`='啊！我要疯了，快帮帮我！', `MaleText_loc5`='啊!!在我失去理智之前，幫幫我!', `MaleText_loc7`='¡Aggh! ¡Ayudadme o perderé la cabeza!' WHERE `ID`=23982;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서요! 날 잃어 가고 있어!', `MaleText_loc4`='快！我的心志快要完全丧失了！', `MaleText_loc5`='快!我的心智快要完全喪失了!', `MaleText_loc7`='¡Rápido! ¡No queda mucho tiempo!' WHERE `ID`=23983;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맞설 상대가 없는 힘... 난... 더 더 그러모아야 해!', `MaleText_loc4`='无与伦比的能量……我……想要……更多！', `MaleText_loc5`='前所未有的力量...我...渴求...更多!', `MaleText_loc7`='¡Poder sin igual... quiero... más!', `FemaleText_loc1`='맞설 상대가 없는 힘... 난... 더 더 그러모아야 한다!', `FemaleText_loc4`='无与伦比的能量……我……想要……更多！', `FemaleText_loc5`='前所未有的力量...我...渴求...更多!', `FemaleText_loc7`='¡Poder sin igual... quiero... más!' WHERE `ID`=23984;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악마의 에너지가... 내 혈관을 따라 흐르는구나!', `MaleText_loc4`='邪能……流遍我全身吧……', `MaleText_loc5`='魔化能量...在我的血脈中奔騰!', `MaleText_loc7`='¡Energía vil... fluye por mis venas!', `FemaleText_loc1`='악마의 에너지가... 내 혈관을 따라 흐르는군!', `FemaleText_loc4`='邪能……流遍我全身吧……', `FemaleText_loc5`='魔化能量...在我的血脈中奔騰!', `FemaleText_loc7`='¡Energía vil... fluye por mis venas!' WHERE `ID`=23985;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악마여, 너의 생명력은 내겐 곧 영양분이다... 바로 킬제덴 님의 선물이란 말이다!', `MaleText_loc4`='你的生命会让我变得更强壮，恶魔……基尔加丹给我们的礼物！', `MaleText_loc5`='你們的生命將是我的養分，惡魔...基爾加丹給我們的禮物!', `MaleText_loc7`='Tu energía vital es mi alimento, demonio... ¡El regalo que nos hace Kil''jaeden!', `FemaleText_loc1`='악마여, 너의 생명력은 곧 내 영양분이란다... 바로 킬제덴 님이 주신 선물이지!', `FemaleText_loc4`='你的生命会让我变得更强壮，恶魔……基尔加丹给我们的礼物！', `FemaleText_loc5`='你們的生命將是我的養分，惡魔...基爾加丹給我們的禮物!', `FemaleText_loc7`='Tu energía vital es mi alimento, demonio... ¡El regalo que nos hace Kil''jaeden!' WHERE `ID`=23986;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='머지않아 나는 그 어떤 엘프보다 강해질 거야! 킬제덴 님의 곁에서 그분을 모시게 될 거란 말이다!', `MaleText_loc4`='很快我就会比其他精灵更强壮了！我会效忠基尔加丹！', `MaleText_loc5`='我很快就要比所有精靈都要更強大!我將在基爾加丹的身邊服侍!', `MaleText_loc7`='¡Pronto seré más fuerte que ningún elfo! ¡Serviré junto a Kil''jaeden!', `FemaleText_loc1`='난 곧 그 어떤 엘프보다도 강해지겠지! 킬제덴 님의 곁에서 그분을 보필할 거야!', `FemaleText_loc4`='很快我就会比其他精灵更强壮了！我会效忠基尔加丹！', `FemaleText_loc5`='我很快就要比所有精靈都要更強大!我將在基爾加丹的身邊服侍!', `FemaleText_loc7`='¡Pronto seré más fuerte que ningún elfo! ¡Serviré junto a Kil''jaeden!' WHERE `ID`=23987;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더... 좀 더... 더 많이!', `MaleText_loc4`='多点……多点……再多点！！！', `MaleText_loc5`='多一點，更多，還要更多!!!', `MaleText_loc7`='¡¡¡Más... más... MÁS!!!', `FemaleText_loc1`='더... 좀 더... 더 많이!', `FemaleText_loc4`='多点……多点……再多点！！！', `FemaleText_loc5`='多一點，更多，還要更多!!!', `FemaleText_loc7`='¡¡¡Más... más... MÁS!!!' WHERE `ID`=23988;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쿠엘다나스 섬으로 가는 차원문을 만들어 그곳에 있는 태양샘에 도착하려면 우선 차원문을 가동할 만한 에너지를 얻어야 합니다.$B$B작업은 현재 $3269w 퍼센트까지 마친 상태입니다. 우리를 도와주시겠습니까, $c|1이여;여;?', `MaleText_loc4`='如果我们要建造一道前往奎尔丹纳斯岛和太阳之井的传送门，就需要有足够多的强力能量资源来开启传送门。$B$B我们现在已经完成了$3269w%%。你愿意帮助我们吗，$c？', `MaleText_loc5`='如果我們想要成功地建立一道傳送門通往奎爾達納斯之島，聯絡整個太陽之井。我們一定會需要一個強大的能量來源好維持傳送門。$B$B我們的目標已經完成了$3269w％。你願意幫助我們嗎，$c?', `MaleText_loc7`='Si queremos tener éxito al crear un portal a la Isla de Quel''Danas, y a La Fuente del Sol que se encuentra en su interior, debemos adquirir una fuente de energía con potencia suficiente para encender el portal.$B$BNuestros esfuerzos están completados al $3269w %. ¿Nos ayudarás, $c?' WHERE `ID`=23989;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 차원문은 아제로스로 연결된 다른 문과는 다릅니다. 차원문을 유지하려면 더 많은 마나 저장기가 필요하지요.$B$B마나 저장기를 계속 보충하지 않으면 쿠엘다나스 섬과 태양샘으로 가는 길을 포기할 수밖에 없습니다.', `MaleText_loc4`='这道传送门与其它连接艾泽拉斯世界的传送门不同。为了让它持续工作，我们需要有更多的法力晶格。$b$b否则我们就有可能失去通向奎尔丹纳斯岛和太阳之井的捷径。', `MaleText_loc5`='這座傳送門不像其他通往艾澤拉斯的。要維持它，我們需要更多的法力電池。$B$B否則我們就會失去通往奎爾達納斯之島與太陽之井的通道。', `MaleText_loc7`='Este portal no es como los demás que llevan de vuelta a Azeroth. Para mantenerlo debemos conseguir más células de maná.$B$BO corremos ese riesgo o perdemos nuestro acceso a la Isla de Quel''Danas y a La Fuente del Sol.' WHERE `ID`=23990;
