UPDATE `locales_broadcast_text` SET `MaleText_loc1`='핵 과부하가 감지되었습니다. 시스템 기능 장애가 감지되었습니다...', `MaleText_loc4`='核心超出负荷。检测到系统故障……', `MaleText_loc5`='偵測到核心超載。偵測到系統錯誤...', `MaleText_loc7`='Sobrecarga detectada en el núcleo. Fallo de sistema detectado...', `FemaleText_loc1`='핵 과부하가 감지되었습니다. 충전 상태에 들어갑니다...', `FemaleText_loc4`='核心超出负荷。检测到系统故障……', `FemaleText_loc5`='偵測到核心超載。充能中...', `FemaleText_loc7`='Sobrecarga detectada en el núcleo. Fallo de sistema detectado...' WHERE `ID`=24008;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수정이 미약하게 고동칩니다. 수정을 보호하던 힘은 약해졌지만 완전히 고갈되지는 않았습니다.', `MaleText_loc4`='水晶发出微弱的光芒。它的保护能量变得很弱，但并没有完全消失。', `MaleText_loc5`='水晶虛弱地脈動著。它的防衛能量越來越低，但還沒有完全耗盡。', `MaleText_loc7`='El cristal parpadea débilmente. Su energía protectora se ha debilitado, pero no se ha agotado del todo.' WHERE `ID`=24009;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='<승낙하는 뜻으로 당신에게 고개를 끄덕이는 고결한 플라스카사우르>', `FemaleText_loc4`='<高贵的弗拉斯卡萨赞许地对你点了点头。>', `FemaleText_loc5`='<高貴的弗拉斯卡索贊同地對你點頭。>', `FemaleText_loc7`='<El noble Frascosaur asiente con la cabeza.>' WHERE `ID`=24010;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무엇을 가져오셨습니까?', `MaleText_loc4`='你想要什么？', `MaleText_loc5`='有什麼事嗎?', `MaleText_loc7`='¿Qué tienes para mí?', `FemaleText_loc1`='무엇을 가져오셨나요?', `FemaleText_loc4`='你想要什么？', `FemaleText_loc5`='有什麼事嗎?', `FemaleText_loc7`='¿Qué tienes para mí?' WHERE `ID`=24011;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희는 현재 유령의 땅에 있는 10인 공격대 던전인 줄아만을 조사하는데 중점을 두고 있습니다. 줄아만에 들어가시려면 68 레벨 이상이어야 합니다.', `MaleText_loc4`='我们现在正在测试祖阿曼，一个位于幽魂之地的10人团队副本。你需要达到68级才能进入。', `MaleText_loc5`='我們現在正集中測試祖阿曼，一個在鬼魂之地的10人團隊地城。你必須至少達到68級以上才能進入。', `MaleText_loc7`='Actualmente estamos probando Zul''Aman, una mazmorra para bandas de 10 jugadores en las Tierras Fantasma. Deber ser, al menos, nivel 68 para poder entrar.' WHERE `ID`=24012;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 줄아만에 들어갈 준비가 되어 있습니다, 제베디아. 순간이동시켜 주십시오!', `MaleText_loc4`='尊特拉华达，我已经做好去祖阿曼的准备了。传送我吧！', `MaleText_loc5`='我已經準備好進入祖阿曼了，捷蒂雅。傳送我!', `MaleText_loc7`='Estoy preparado para Zul''Aman, Jebediah. ¡Teletranspórtame!', `FemaleText_loc1`='저는 줄아만에 들어갈 준비가 되어 있답니다, 제베디아. 순간이동시켜 주세요!', `FemaleText_loc4`='尊特拉华达，我已经做好去祖阿曼的准备了。传送我吧！', `FemaleText_loc5`='我已經準備好進入祖阿曼了，捷蒂雅。傳送我!', `FemaleText_loc7`='Estoy preparada para Zul''Aman, Jebediah. ¡Teletranspórtame!' WHERE `ID`=24013;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='임무가 입력되었습니다. 보안 작업을 시작합니다.', `MaleText_loc4`='目标确定。启动安全程序。', `MaleText_loc5`='目標尋獲。開始例行安全程序。', `MaleText_loc7`='Objetivo adquirido. Iniciando rutina de seguridad.' WHERE `ID`=24014;
