UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배치를 완료했습니다. 침입자들을 제압합니다.', `MaleText_loc4`='命令接受成功。入侵者将被消灭。', `MaleText_loc5`='部屬完成。入侵者將被排除。', `MaleText_loc7`='Despliegue realizado con éxito. Los intrusos serán neutralizados.' WHERE `ID`=24016;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 비전 마력으로 충만해졌습니다.', `MaleText_loc4`='%s周身充满了奥术能量。', `MaleText_loc5`='%s獲得了秘法力量的充能。', `MaleText_loc7`='El %s se energiza con poder Arcano.' WHERE `ID`=24017;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, $r님.$b$b마침내 가게를 열었어요. 마음에 드는 물건이 있으면 좋겠네요!', `FemaleText_loc4`='你好，$r。$b$b我的商店终于开张了。希望你能找到你想要的东西！', `FemaleText_loc5`='歡迎，$r。$b$b我的店舖終於開了。希望你有看到喜歡的!', `FemaleText_loc7`='Saludos, $r.$B$BAl fin está abierta mi tienda. ¡Espero que te guste lo que hay!' WHERE `ID`=24018;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, $c님.$b$b이곳엔 도움이 필요한 일이 아주 많아요. 불행하게도 저로서는 보급품을 모두 얻기 전까지 도와드릴 수가 없을 것 같네요.$b$b일을 시작하는 데 필요한 서슬가시 뿌리를 아직 $3223w 퍼센트밖에 모으지 못했거든요. 도와주신다면 정말 큰 도움이 될 거예요. 약속할게요.', `FemaleText_loc4`='你好啊，$c。$B$B这里有很多事需要帮忙，不过在我得到所有必需的补给之前，我几乎什么都帮不了你。$B$B在我开始工作之前，必须得到足够的荆刺根须，不过目前只有$3223w%%的存量。你的帮助会对我的工作进展非常重要，真的。', `FemaleText_loc5`='日安，$c。$b$b這裡還有好多事情等著完成。可惜我目前幫不上你的忙，除非我能拿到我的補給品。$b$b我現在才取得$3223w％的刺棘根莖。你提供的任何協助都是有價值的，我向你保證。', `FemaleText_loc7`='Buenos días, $c.$B$BHay mucho que hacer para ayudar aquí. Por desgracia, no puedo hacer mucho por ti hasta que consiga todos mis suministros.$B$BPor ahora tengo el $3223w % de las raíces de Rajaespina que necesito para empezar. Te aseguro que cualquier ayuda que me puedas prestar merecerá la pena.' WHERE `ID`=24019;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크와! 네놈은 날 죽일 수 없다, 나는 불사신이니까!', `MaleText_loc4`='呱！你杀不了我，我是无敌的！', `MaleText_loc5`='喀!你殺不死我，我是永生不朽的!', `MaleText_loc7`='¡Kwa! ¡No puedes matarme, soy inmortal!' WHERE `ID`=24020;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서둘러라! 불길로 지상군을 지원하라. 그 고대의 마법으로 테로크의 보호막을 제거해야 한다.', `MaleText_loc4`='快！利用火焰来支援地面部队。它的远古魔力应该可以清除泰罗克的护盾。', `MaleText_loc5`='快點!使用這些火焰支援地面軍隊。它的古老魔法應該可以淨化泰洛克的護盾。', `MaleText_loc7`='¡Rápido! Usad las llamas para apoyar a las tropas terrestres. Su magia ancestral debería limpiar el escudo de Terokk.', `FemaleText_loc1`='서둘러라! 불길로 지상군을 지원하라. 그 고대의 마법으로 테로크의 보호막을 제거해야 한다.', `FemaleText_loc4`='快！利用火焰来支援地面部队。它的远古魔力应该可以清除泰罗克的护盾。', `FemaleText_loc5`='快點!使用這些火焰支援地面軍隊。它的古老魔法應該可以淨化泰洛克的護盾。', `FemaleText_loc7`='¡Rápido! Usad las llamas para apoyar a las tropas terrestres. Su magia ancestral debería limpiar el escudo de Terokk.' WHERE `ID`=24021;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 관문은 캘타스의 군대가 태양샘으로 후퇴할 때 사용하던 겁니다. 그의 추종자들 일부가 아직 여기 남아 있지요. 불타는 군단은 그들에게 정말... 이상한 방법으로 보상했었지요.', `FemaleText_loc4`='凯尔萨斯的军队就是从这里撤退到太阳之井的。他的一些走狗仍然残留在这里，燃烧军团以最不平常的方式奖赏着他们……', `FemaleText_loc5`='這就是凱爾的軍隊用來逃往太陽之井的通道。一些只會奉承他的走狗被留了下來，而且燃燒軍團還以...不尋常的方法獎賞了他們。', `FemaleText_loc7`='Este es el portal que usaron los ejércitos de Kael para retirarse a La Fuente del Sol. Algunos de sus perritos falderos continúan aquí, la Legión los ha recompensado de una forma muy... poco habitual.' WHERE `ID`=24022;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='섬을 돌아다니는 부서진 파수병들을 봤나요? 행동을 제어하는 수정을 약간만 개조하면 그 파수병들을 사용해서 전략 요충지를 방어할 수 있을 거예요.$B$B태양너울 성소는 머지않아 손에 넣을 수 있을 겁니다. 작업이 $3244w 퍼센트 정도 진행되었으니까요.', `FemaleText_loc4`='你有没有看到那些在岛上游荡的魔像守卫？只要对控制它们行动的水晶核心做一些小小的改动，就能让我们获得它们的控制权，用它们来保护战略要地。$b$b阳湾圣殿很快就会是我们的了，眼下我们的目标完成率已经达到了$3244w%%。', `FemaleText_loc5`='你有看到島上那些受損漫遊的哨兵嗎?只需要對控制水晶做些調整，就讓我們控制這些哨兵，並且用他們來守衛我們的戰略據點。$B$B日境聖所很快就是我們的。我們目前的目標達成率為$3244w％。', `FemaleText_loc7`='¿Has visto los centinelas dañados que vagan por la isla? Unas cuantas modificaciones en los cristales que controlan su comportamiento nos permitirán controlarlos y usarlos para asegurar posiciones tácticas.$B$BEl Sagrario de Tramo del Sol será nuestro en un abrir y cerrar de ojos. Hemos completado nuestra meta en un $3244w %.' WHERE `ID`=24023;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='성소를 차지하는 데 성공했어요. 파수병을 계속 우리 것으로 개조해서 다른 전략 요충지에 경비병으로 배치할 수 있을 거예요.', `FemaleText_loc4`='我们成功地拿下了圣殿。我们可以继续转变这些魔像守卫，用它们来保护其它的战略要地。', `FemaleText_loc5`='我們成功地拿下了聖所。我們可以繼續轉換那些哨兵，用他們來防衛其他戰略位置。', `FemaleText_loc7`='Hemos logrado tomar el Sagrario. Podemos seguir convirtiendo a los centinelas y usarlos como guardias en otras posiciones tácticas.' WHERE `ID`=24024;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어이! 자비로운 수녀호의 표를 예약하시려고? 제대로 찾아오셨네...', `MaleText_loc4`='喂！伙计，你想要预订慈悲修女号的座位？你找对地方啦……', `MaleText_loc5`='唷喝!你想要登記搭乘慈悲姐妹號嗎，朋友?那你就來對地方了...', `MaleText_loc7`='¡Ah del barco! ¿Tú quieres un boleto pa subir a bordo del Hermana Misericordia? Viniste al lugal adecuao...' WHERE `ID`=24025;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더는 바다에 소중한 생명을 희생시킬 순 없습니다.', `MaleText_loc4`='我们必须确保不会再有谁葬身大海。', `MaleText_loc5`='我們必須確保不會再於海中失去任何靈魂。', `MaleText_loc7`='Debemos asegurarnos de no perder más almas a manos del mar.', `FemaleText_loc1`='더는 바다에 희생되는 영혼이 없도록 해야겠어요.', `FemaleText_loc4`='我们必须确保不会再有谁葬身大海。', `FemaleText_loc5`='我們必須確保不會再於海中失去任何靈魂。', `FemaleText_loc7`='Debemos asegurarnos de no perder más almas a manos del mar.' WHERE `ID`=24026;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엉덩이를 노려라!', `MaleText_loc4`='瞄准，往死里打！', `MaleText_loc5`='瞄準那個混蛋!', `MaleText_loc7`='¡Apuntad al trasero!' WHERE `ID`=24027;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발사! 보물이 탐나거든 쏴라, 이놈들아!', `MaleText_loc4`='开火！亲爱的，为了财宝，开火吧！', `MaleText_loc5`='開火!為了寶藏開火，朋友們!', `MaleText_loc7`='¡Fuego! ¡Disparad por el botín, compadres!' WHERE `ID`=24028;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살아생전에는 네 녀석이 이겼을지 몰라도, 죽은 나는 절대로 못 이길 거다! 발사!', `MaleText_loc4`='有人或许能风光一辈子，但是总不可能在死后也为所欲为吧！开火！', `MaleText_loc5`='它也許活著的時候贏得了我們，但是它不可能連死後也贏得了!開火!', `MaleText_loc7`='¡Quisá ganó en vida, pero no ganará en el más allá! ¡FUEGO!' WHERE `ID`=24029;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죄송합니다만 $c님, 저는 한 눈 팔지 않고 제 임무를 해야 합니다.', `MaleText_loc4`='$c，请原谅，我必须专心工作。', `MaleText_loc5`='原諒我$c，不過我必須專心於我的工作中。', `MaleText_loc7`='Perdóname $c, pero he de concentrarme en mi trabajo.', `FemaleText_loc1`='죄송합니다만 $c님, 일을 할 때는 한 눈 팔 수가 없답니다.', `FemaleText_loc4`='$c，请原谅，我必须专心工作。', `FemaleText_loc5`='原諒我$c，不過我必須專心於我的工作中。', `FemaleText_loc7`='Perdóname $c, pero he de concentrarme en mi trabajo.' WHERE `ID`=24030;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='많은 목숨이 바다에서 길을 잃었습니다. 그 영혼을 찾는 건 나와 위습에게 지워진 몫이지.', `MaleText_loc4`='很多人葬身大海。我和小精灵负责在海面上搜寻灵魂。', `MaleText_loc5`='許多人在大海中失去了身影。我，以及這些幽光，則負責尋找那些靈魂。', `MaleText_loc7`='Muchas almas se han perdido a manos de los mares. Yo y los fuegos fatuos tenemos la misión de encontrarlas.', `FemaleText_loc1`='많은 목숨이 바다에서 길을 잃었습니다. 그 영혼을 찾는 건 저와 위습이 부여받은 임무이지요.', `FemaleText_loc4`='很多人葬身大海。我和小精灵负责在海面上搜寻灵魂。', `FemaleText_loc5`='許多人在大海中失去了身影。我，以及這些幽光，則負責尋找那些靈魂。', `FemaleText_loc7`='Muchas almas se han perdido a manos de los mares. Yo y los fuegos fatuos tenemos la misión de encontrarlas.' WHERE `ID`=24031;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소를로프의 보물이 바닥에 떨어집니다.', `MaleText_loc4`='索罗夫的财宝掉在了地上。', `MaleText_loc5`='索洛夫的寶藏灑了一地。', `MaleText_loc7`='El botín de Sorlof cae al suelo.' WHERE `ID`=24032;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위습과 저는 헤매는 영혼이 또 있는지 바다를 살펴봅니다.', `MaleText_loc4`='我和小精灵守护着那些迷失的灵魂。', `MaleText_loc5`='幽光與我留意著大海中任何迷失的靈魂。', `MaleText_loc7`='Los fuegos fatuos y yo vigilamos los mares en busca de almas perdidas.', `FemaleText_loc1`='위습과 저는 헤매는 영혼이 또 있나 없나 바다를 살펴보지요.', `FemaleText_loc4`='我和小精灵守护着那些迷失的灵魂。', `FemaleText_loc5`='幽光與我留意著大海中任何迷失的靈魂。', `FemaleText_loc7`='Los fuegos fatuos y yo vigilamos los mares en busca de almas perdidas.' WHERE `ID`=24033;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바다는 위험하기 짝이 없는 곳입니다, $c. 그러니 경계를 늦추지 말아야 합니다.', `MaleText_loc4`='海洋是个危险的地方，$c。我们必须保持警惕。', `MaleText_loc5`='大海是個危險之地，$c。我們一定要非常小心。', `MaleText_loc7`='Los mares son un lugar peligroso, $c. Debemos estar alerta.', `FemaleText_loc1`='바다는 위험하기 짝이 없는 곳이지요, $c. 그러니 경계를 늦추지 말아야 합니다.', `FemaleText_loc4`='海洋是个危险的地方，$c。我们必须保持警惕。', `FemaleText_loc5`='大海是個危險之地，$c。我們一定要非常小心。', `FemaleText_loc7`='Los mares son un lugar peligroso, $c. Debemos estar alerta.' WHERE `ID`=24034;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금은 당신과 얘기하기 좀 곤란합니다.', `MaleText_loc4`='我现在恐怕不能和你谈话。', `MaleText_loc5`='我現在恐怕無法跟你交談。', `MaleText_loc7`='Me temo que no puedo hablar contigo ahora.', `FemaleText_loc1`='지금은 당신과 얘기를 나누기 좀 곤란해요.', `FemaleText_loc4`='我现在恐怕不能和你谈话。', `FemaleText_loc5`='我現在恐怕無法跟你交談。', `FemaleText_loc7`='Me temo que no puedo hablar contigo ahora.' WHERE `ID`=24035;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘이 고프다!', `MaleText_loc4`='我好饿！', `MaleText_loc5`='我餓了!', `MaleText_loc7`='¡Estoy hambriento!' WHERE `ID`=24036;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 힘은... 내 것이야!', `MaleText_loc4`='能量……是我的！', `MaleText_loc5`='力量...是屬於我的!', `MaleText_loc7`='¡El poder... será mío!' WHERE `ID`=24037;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈들은 나를 막을 수 없다!', `MaleText_loc4`='你阻止不了我！', `MaleText_loc5`='你無法阻止我!', `MaleText_loc7`='¡No me detendréis!' WHERE `ID`=24038;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수호의 수정... 그 힘이 필요해!', `MaleText_loc4`='水晶结界……我需要能量！', `MaleText_loc5`='水晶結界...我要吞食!', `MaleText_loc7`='Los resguardos de cristal... ¡He de alimentarme!' WHERE `ID`=24039;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말... 엄청난... 힘이야.', `MaleText_loc4`='这么……多……能量。', `MaleText_loc5`='這麼...多...的能量。', `MaleText_loc7`='Tanto... poder.' WHERE `ID`=24040;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 이 힘이야, 느낄 수 있어!', `MaleText_loc4`='能量……我能感觉到！', `MaleText_loc5`='能量!我要吞食它!', `MaleText_loc7`='La energía; ¡puedo sentirla!' WHERE `ID`=24041;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 수호의 수정은 우리가 되찾는다!', `MaleText_loc4`='我们会重新夺回这些结界的！', `MaleText_loc5`='我們會奪回這些結界!', `MaleText_loc7`='¡Recuperaremos esos resguardos!' WHERE `ID`=24042;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈들은 우리 수정을 가질 자격이 없어!', `MaleText_loc4`='你不能夺走我们的结界！', `MaleText_loc5`='你不能霸佔我們的結界!', `MaleText_loc7`='¡No podéis quedaros con nuestros resguardos!' WHERE `ID`=24043;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요호호, 노움이 얼마나 용감한지 봤지?!', `MaleText_loc4`='啊哈哈哈，来一瓶侏儒烈酒庆祝一下！', `MaleText_loc5`='唷呵呵，一瓶地精的靈魂!', `MaleText_loc7`='¡Jo, jo, jo y una botella de walfarina gnómica!' WHERE `ID`=24044;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='녀석이 쓰러졌다!', `MaleText_loc4`='一炮轰成渣啊！', `MaleText_loc5`='她開槍啦!', `MaleText_loc7`='¡Cómo vuela!' WHERE `ID`=24045;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='술과 여자가 우리를 기다리는군!', `MaleText_loc4`='尽情享受美酒和女人！', `MaleText_loc5`='為了美酒和女人!', `MaleText_loc7`='¡Ron y chamas pa todos!' WHERE `ID`=24046;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 애송이, 보물을 가져와!', `MaleText_loc4`='受死吧，旱鸭子！', `MaleText_loc5`='旱鴨子，接招吧!', `MaleText_loc7`='¡Toma eso, marinero d''agua dulse!' WHERE `ID`=24047;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보물은 우리 것이다!', `MaleText_loc4`='财宝属于我们！', `MaleText_loc5`='寶藏是我們的了!', `MaleText_loc7`='¡El botín será nuestro!' WHERE `ID`=24048;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 캘타스 왕자님의 모습을 봤나?', `MaleText_loc4`='……你见过凯尔萨斯现在的样子了吗？', `MaleText_loc5`='...你有看到凱爾薩斯當時的模樣嗎?', `MaleText_loc7`='¿... te has fijado en el aspecto de Kael''thas?' WHERE `ID`=24049;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='봤지. 폭풍우 요새 공격 이후로 전혀 딴 사람이 되셨더군.', `MaleText_loc4`='嗯。自从风暴要塞被攻击以来，他就变得有些不一样了。', `MaleText_loc5`='是的。自從在風暴要塞之戰後，他完全變了模樣。', `MaleText_loc7`='Sí. No ha vuelto a ser el mismo desde el ataque en El Castillo de la Tempestad.' WHERE `ID`=24050;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그분은 그곳에서 패하고 나서 버려져 계셨지. 델리사 여사제님께서 그때 나타나지 않으셨다면 어떻게 됐을지 아무도 모를 일이야.', `MaleText_loc4`='他被打倒在地，人人都以为他已经死了。要不是女祭司德莉希亚及时赶到，谁知道会发生什么！', `MaleText_loc5`='他被擊敗後只剩下等死的命運。如果女牧師戴利莎當時沒有即時抵達，誰知道後來會發生什麼事!', `MaleText_loc7`='Le apalearon y le abandonaron para morir. ¡Si la sacerdotisa Delrissa no hubiera llegado, quién sabe qué habría ocurrido!' WHERE `ID`=24051;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그분의 그 눈빛... 지금 보면 아주 오싹하다니까.', `MaleText_loc4`='他现在的眼神……让我感到害怕。', `MaleText_loc5`='他現在的眼神...令我感到害怕。', `MaleText_loc7`='Esa mirada en sus ojos... me asusta.' WHERE `ID`=24052;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맞아. 하지만 우리로서는 끝까지 그분을 따라야지. 그분께서 준비하시는 동안 성역을 방어하는 게 우리의 임무잖나.', `MaleText_loc4`='是的，不过我们还将始终追随着他。我们的职责就是在他进行准备的时候守护这里。', `MaleText_loc5`='是的，但我們仍會追隨他，直到最後。我們的職責就是在他做準備時，守護這座庇護所。', `MaleText_loc7`='Sí, pero le seguiremos hasta el fin. Es nuestro deber proteger este santuario mientras él se prepara.' WHERE `ID`=24053;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비? 무슨 준비?', `MaleText_loc4`='准备？准备什么？', `MaleText_loc5`='準備?準備什麼?', `MaleText_loc7`='¿Se prepara? ¿Se prepara para qué?' WHERE `ID`=24054;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 있잖나, 그분의... 귀환 말이야.', `MaleText_loc4`='他的……回归。', `MaleText_loc5`='他...回來了。', `MaleText_loc7`='Su... retorno.' WHERE `ID`=24055;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 숨 막힌 듯한 표정을 짓습니다.', `MaleText_loc4`='%s大吃了一惊。', `MaleText_loc5`='%s倒抽一口氣。', `MaleText_loc7`='%s deja escapar un grito sofocado.' WHERE `ID`=24056;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='친구여, 당신에게 나루의 가호가 있기를.', `MaleText_loc4`='纳鲁祝福你，我的朋友。', `MaleText_loc5`='那魯的祝福眷顧你，我的朋友。', `MaleText_loc7`='Que el naaru te bendiga, colega.' WHERE `ID`=24057;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내겐 별다른 임무가 부여되지 않았다는 걸 알 거요. 그래서 그런지 전선 가까이에서 임무를 수행하는 게 기분 전환하기에 딱 좋지.', `MaleText_loc4`='我这边的行动倒不是很频繁。在战区中如此靠近前线，真是紧张刺激。', `MaleText_loc5`='你可以看得出來我這裡沒有太多工作。在如此靠近前線的戰鬥區域服務是個不錯的轉換。', `MaleText_loc7`='No hay mucha acción en mi trabajo, servir tan cerca de las primeras líneas en una zona de combate es un cambio agradable.' WHERE `ID`=24058;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='작전이라고 하니 말입니다만, 제가 공습 명령을 받았습니다.', `MaleText_loc4`='说到行动，我接到命令，要去发动一次空袭。', `MaleText_loc5`='說到工作，我最近受命要進行一次空中攻擊。', `MaleText_loc7`='Hablando de acción, me han ordenado llevar a cabo un ataque aéreo.', `FemaleText_loc1`='작전이라고 하니 말인데요, 공습 명령을 받았어요.', `FemaleText_loc4`='说到行动，我接到命令，要去发动一次空袭。', `FemaleText_loc5`='說到工作，我最近受命要進行一次空中攻擊。', `FemaleText_loc7`='Hablando de acción, me han ordenado llevar a cabo un ataque aéreo.' WHERE `ID`=24059;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말이지 난 이 악마들과 도저히 같이 있을 수가 없어!', `MaleText_loc4`='我完全忍受不了这些恶魔了！', `MaleText_loc5`='我再也無法忍受那些惡魔的存在了!', `MaleText_loc7`='¡De verdad que no puedo soportar la presencia de estos demonios!' WHERE `ID`=24060;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맞아! 파멸의 수호병이 목욕하는 걸 본 게 도대체 언제지?', `MaleText_loc4`='是啊！你上次看到末日守卫洗澡是什么时候？', `MaleText_loc5`='對!你上次看到末日守衛洗澡是什麼時候?', `MaleText_loc7`='¡Sí! ¿Cuándo fue la última vez que viste a un guardia apocalíptico darse un baño?' WHERE `ID`=24061;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 온 화단을 짓밟으면서 순찰을 다니는 그 더러운 놈들 얘긴 꺼내고 싶지도 않아.', `MaleText_loc4`='……更不用说花园里到处都是那些讨厌的深渊巡逻队了。', `MaleText_loc5`='...更別提那些該死的冥淵火，整天在花圃上橫行。', `MaleText_loc7`='...por no mencionar que esos condenados abisales patrullan pisando las flores.' WHERE `ID`=24062;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도대체 그놈들이 왜 필요한 거야?', `MaleText_loc4`='但是我们为什么需要他们？', `MaleText_loc5`='我們怎麼會需要它們?', `MaleText_loc7`='¿Para qué los necesitamos?' WHERE `ID`=24063;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='캘타스 왕자님께서 필요하다고 하셨으니까 그렇지.', `MaleText_loc4`='凯尔萨斯大人坚持要这么做。', `MaleText_loc5`='凱爾薩斯大人這麼堅持。', `MaleText_loc7`='Lord Kael''thas ha insistido en ello.' WHERE `ID`=24064;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일이 끝나면 제발 그분께서 녀석들을 차원문 저편으로 돌려보냈으면 좋겠어.', `MaleText_loc4`='好吧，我希望等他们的事情搞定之后，凯尔萨斯会把他们送回传送门的另一端去……', `MaleText_loc5`='好吧，我希望一旦任務完成，他就能立刻讓那些傢伙穿過傳送門滾回去...', `MaleText_loc7`='Bueno, espero que cuando hayan acabado los devuelvan al otro lado del portal...' WHERE `ID`=24065;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 동조하며 고개를 끄덕입니다.', `MaleText_loc4`='%s赞许地点了点头。', `MaleText_loc5`='%s同意地點頭。', `MaleText_loc7`='%s asiente mostrando su acuerdo.' WHERE `ID`=24066;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 강하게 훈련해라! 이제 캘타스 왕자님 곁을 지킬 충성스러운 호위병은 우리뿐이다!', `MaleText_loc4`='努力训练！我们是凯尔萨斯身边仅存的忠诚卫士。', `MaleText_loc5`='訓練認真一點!我們是凱爾薩斯所剩下最忠誠的防衛者。', `MaleText_loc7`='¡Entrenad más duro! ¡Somos todo lo que queda de los leales defensores de Kael''thas!' WHERE `ID`=24067;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분발해라! 우리는 목숨을 바쳐서라도 태양샘을 지켜내야만 한다!', `MaleText_loc4`='认真一点！必要的时候，我们必须以生命来保卫太阳之井！', `MaleText_loc5`='扛起責任來!如果必要的話，我要以生命來守護太陽之井!', `MaleText_loc7`='¡Arrimad el hombro! ¡Defenderemos La Fuente del Sol con nuestras vidas si es necesario!' WHERE `ID`=24068;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='캘타스 왕자 님께서는 더는 실패를 용납하지 않으실 거다!', `MaleText_loc4`='凯尔萨斯不能容忍再次失败！', `MaleText_loc5`='凱爾薩斯不會再忍受任何失敗!', `MaleText_loc7`='¡Kael''thas no tolerará más fallos!' WHERE `ID`=24069;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시!', `MaleText_loc4`='再来一次！', `MaleText_loc5`='再一次!', `MaleText_loc7`='¡Otra vez!' WHERE `ID`=24070;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새벽칼날단은 모든 신도레이를 위해 이 땅을 지킬 것이다. 더는 물러설 수 없다!', `MaleText_loc4`='晨锋部队会为所有的辛多雷守卫这片土地。我们没有任何退路！', `MaleText_loc5`='曦刃將會為了辛多雷全體守護這座島嶼。沒有任何退縮的空間!', `MaleText_loc7`='Los Hojalba defenderán esta tierra en nombre de todos los sin''dorei. ¡No hay vuelta atrás!' WHERE `ID`=24071;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 여기 놀러 온 게 아니다. 우리의 마음, 우리의 영혼, 우리를 속박하는 중독으로부터 탈출하는 길이 바로 이곳, 쿠엘다나스에 있다.', `MaleText_loc4`='这里不是度假胜地——我们的生命，我们的灵魂，最终能够摆脱魔瘾的希望，都让我们和奎尔丹纳斯紧紧联系在一起。', `MaleText_loc5`='沒有偷閒的時間 - 我們的心，我們的靈魂，束縛我們的癮頭的最終解決之道，就在奎爾達納斯。', `MaleText_loc7`='Esto no son unas vacaciones: nuestros corazones, nuestras almas, la liberación final de las adicciones que nos atan están aquí en Quel''Danas.' WHERE `ID`=24072;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='버림받은 자들처럼 되고 싶나? 싫은가?! 그렇다면 이번에는 전력을 다해 싸워라!', `MaleText_loc4`='你想得到失心者那样的下场吗？不想吧？！那么现在就给我努力一点！', `MaleText_loc5`='你希望自己最後落得像個鄙惡者嗎?不要?那這次就多用點心!', `MaleText_loc7`='¿Queréis acabar como los desdichados? ¿No? ¡Entonces poned más interés esta vez!' WHERE `ID`=24073;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='킬제덴 님의 인내심을 시험하지 마라! 나루의 추종자들을 끝장내 버려라!', `MaleText_loc4`='基尔加丹快要失去耐心了！把那些纳鲁的仆从们消灭干净！', `MaleText_loc5`='基爾加丹的耐心越來越少!那魯所有的僕人永遠毀滅!', `MaleText_loc7`='¡La paciencia de Kil''jaeden se agota! ¡Destruid a los lacayos del naaru de una vez por todas!' WHERE `ID`=24074;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갈퀴흉터 열쇠', `MaleText_loc4`='库斯卡钥匙', `MaleText_loc5`='考斯卡鑰匙', `MaleText_loc7`='Llave Cicatriz Espiral', `FemaleText_loc1`='갈퀴흉터 열쇠', `FemaleText_loc4`='库斯卡钥匙', `FemaleText_loc5`='考斯卡鑰匙', `FemaleText_loc7`='Llave Cicatriz Espiral' WHERE `ID`=24075;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음이 무서운가? 실패하면 그보다 더한 공포가 기다리고 있다! 필멸의 존재들을 해치우란 말이다!', `MaleText_loc4`='你畏惧死亡？如果你失败的话，会有远比死亡更加痛苦的下场等着你！去消灭那些凡人！', `MaleText_loc5`='你恐懼死亡嗎?若你是失敗，將會有更糟的等著你!殺死那些凡人!', `MaleText_loc7`='¿Temes a la muerte? ¡Si fracasas te espera algo mucho peor! ¡Mata a los mortales!' WHERE `ID`=24076;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 위치로 돌아가라! 전투는 아직 끝나지 않았다!', `MaleText_loc4`='回到你的岗位上去！战斗还没有结束！', `MaleText_loc5`='回到你的崗位!戰鬥還沒結束!', `MaleText_loc7`='¡Vuelvan a sus puestos! ¡Esta batalla aún no ha terminado!' WHERE `ID`=24077;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='태양너울 무기고를 점령했다! 악마를 새벽 광장으로 몰아넣었다!', `MaleText_loc4`='阳湾军械库是我们的了！我们已经把那些恶魔逼退到黎明广场去了！', `MaleText_loc5`='日境軍械庫是我們的了!我們將惡魔們逼退到曙光廣場了!', `MaleText_loc7`='¡El Arsenal de Tramo del Sol es nuestro! ¡Hemos hecho retroceder a los demonios hasta La Plaza Crepuscular!' WHERE `ID`=24078;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 태양너울 성소를 점령했소! 샤트라스로 전령을 보내 이제 우리가 움직일 차례라고 알리시오!', `MaleText_loc4`='我们已经占领了阳湾圣殿！通知沙塔斯城，我们现在要开始行动了！', `MaleText_loc5`='我們奪下了日境聖所!快把消息傳回撒塔斯，我們現在可以行動了!', `MaleText_loc7`='¡Hemos tomado el Sagrario de Tramo del Sol! ¡Informad a Shattrath, hemos de avanzar ahora!' WHERE `ID`=24079;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='태양너울 성소를 점령하는 일은 우리 계획의 첫 단계였습니다. 다음 임무는 무기고를 차지하는 것이지요.$B$B현재 $3233w 퍼센트 정도 진행된 상태입니다.', `MaleText_loc4`='占领阳湾圣殿是我们战斗计划的第一步。下一步是要控制军械库。$b$b我们的目标完成率已经达到百分之$3233w了。', `MaleText_loc5`='佔領日境聖所只是我們作戰計畫的第一步。下一個目標就是軍械庫。$B$B我們目前的目標達成率為$3233w％。', `MaleText_loc7`='Capturar el Sagrario de Tramo del Sol era el primer paso de nuestro plan de batalla. Nuestras órdenes son tomar el control del arsenal a continuación.$B$BHemos completado nuestra meta en un $3233w %.' WHERE `ID`=24080;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무기고를 장악하는 데 성공했습니다. 하지만 이 섬에는 우리가 해야 할 일이 아직 남았습니다.', `MaleText_loc4`='我们已经夺取了军械库的控制权，但我们在岛上的工作还没有完成。', `MaleText_loc5`='我們控制了軍械庫，但是我們在島上的任務還沒結束。', `MaleText_loc7`='Hemos tomado el control del arsenal, pero nuestro trabajo en esta isla aún no ha terminado.' WHERE `ID`=24081;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 군대가 태양너울 무기고를 점령할 수 있도록 죽음의 흉터에서 양동작전을 펼치라는 임무를 받았습니다. 악마를 직접 처치하는 것만큼 멋지지는 않지만, 우리가 이길 수 있다면 그것으로 족하답니다.$B$B이 임무는 현재 $3233w 퍼센트 진행된 상태입니다.', `FemaleText_loc4`='我的任务是在死亡之痕吸引敌人的注意力，这样我们的军队就可以拿下阳湾军械库了。虽然听上去并不像和恶魔直接交锋那么吸引人，但如果这能让我们赢下这场战争，那我一定会全力去做。$B$B我们的目标完成率已经达到了百分之$3233w。', `FemaleText_loc5`='我的任務就是在死亡之痕造成干擾，好讓我們的部隊可以佔領日境軍械庫。這幾乎和面對面殺死惡魔一樣吸引人。$B$B我們目前的目標達成率為$3233w％。', `FemaleText_loc7`='Mis órdenes son crear una distracción en La Cicatriz Muerta para que nuestras fuerzas puedan tomar el Arsenal de Tramo del Sol. Puede que no sea tan glamuroso como matar demonios cara a cara, pero si nos ayuda a ganar esta batalla yo me apunto.$B$BHemos completado nuestra meta en un $3233w %.' WHERE `ID`=24082;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 태양 공격대가 무기고를 점령했어요, $n. 하지만 이걸로는 이겼다고 할 수 없어요. 불타는 군단이 가만히 있지 않을 테니까요.', `FemaleText_loc4`='我们已经夺下了军械库，$n。尽管如此，我们仍然不能沾沾自喜，满足现状。燃烧军团不会就此停下他们的脚步。', `FemaleText_loc5`='我們佔領了軍械庫，$n。然而，我們卻不能因為這點勝利而歇息。因為燃燒軍團肯定不會停歇。', `FemaleText_loc7`='Hemos capturado el arsenal, $n. Pero no nos durmamos en los laureles. La Legión no lo hará.' WHERE `ID`=24083;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노력한 보람이 있군. 마침내 태양너울 성소를 점령했소, $n. 그리로 가서 도움을 줄 친구가 있는지 알아보시오.', `MaleText_loc4`='我们的努力得到了回报。我们已经占领了阳湾圣殿，$n。去那里看看有什么可以帮忙的吧。', `MaleText_loc5`='我們的努力獲得了回報。我們佔領了日境聖所，$n。去那邊看看你能幫得上什麼忙。', `MaleText_loc7`='Nuestros esfuerzos han dado su fruto. Hemos capturado el Sagrario de Tramo del Sol, $n. Ve a ver si hay alguien a quien puedas ayudar.' WHERE `ID`=24084;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성소의 수호물을 가동하면 그곳을 빠르게 확보하는 데 도움이 될 거요. 불타는 군단과 캘타스에게 총공격을 가할 때 버림받은 엘프 녀석들의 방해를 받아 좋을 게 없지 않소.$B$B작업은 현재 $3244w퍼센트 정도 진행된 상태라오.', `MaleText_loc4`='武装圣殿的防御结界可以让我们更快地占领它。我们不希望在全力攻击燃烧军团和凯尔萨斯时还要为失心者的偷袭操心。$B$B我们的目标完成率已经达到$3244w%%了。', `MaleText_loc5`='強化聖所周圍的結界可以幫助我們更快地鞏固此地。我們可不希望有任何鄙惡者干擾我們對燃燒軍團還有凱爾的全面進攻。$B$B我們目前的目標達成率為$3244w％。', `MaleText_loc7`='Armar los resguardos en el sagrario nos ayudará a asegurarlo antes. No queremos que ningún desdichado se interponga en nuestro camino cuando desatemos un ataque a gran escala contra la Legión y Kael.$B$BHemos completado el $3244w % de nuestro objetivo.' WHERE `ID`=24085;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여어, 이거 $n 아니신가요? 다시 보니 반갑군요!', `MaleText_loc4`='$n，很高兴再次看到你！', `MaleText_loc5`='$n，很高興再次看到你!', `MaleText_loc7`='¡$n, me alegro de volver a verte!', `FemaleText_loc1`='$n 아니신가요? 다시 보니 반갑군요!', `FemaleText_loc4`='$n，很高兴再次看到你！', `FemaleText_loc5`='$n，很高興再次看到你!', `FemaleText_loc7`='¡$n, me alegro de volver a verte!' WHERE `ID`=24086;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 저기 좀 보라고, $n|1이야;야;!', `MaleText_loc4`='大家看，是$n！', `MaleText_loc5`='大家看，是$n!', `MaleText_loc7`='¡Mirad todos, es $n!', `FemaleText_loc1`='다들 저기 좀 보세요, $n|1이야;야;!', `FemaleText_loc4`='大家看，是$n！', `FemaleText_loc5`='大家看，是$n!', `FemaleText_loc7`='¡Mirad todos, es $n!' WHERE `ID`=24087;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새벽칼날단, 악마, 그리고 나가 녀석들아. 긴장해라, $n|1이;가; 돌아왔다.', `MaleText_loc4`='晨锋部队、恶魔和纳迦们要小心了，因为$n回来收拾他们了！', `MaleText_loc5`='曦刃軍團、惡魔還有納迦當心了，$n回來了。', `MaleText_loc7`='Tengan cuidado Hojalba, demonios y nagas: $n ha vuelto.', `FemaleText_loc1`='새벽칼날단, 악마, 그리고 나가 녀석들아. 긴장해라, $n|1이;가; 돌아왔단 말이다.', `FemaleText_loc4`='晨锋部队、恶魔和纳迦们要小心了，因为$n回来收拾他们了！', `FemaleText_loc5`='曦刃軍團、惡魔還有納迦當心了，$n回來了。', `FemaleText_loc7`='Tengan cuidado Hojalba, demonios y nagas: $n ha vuelto.' WHERE `ID`=24088;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님, 저희와 함께 있어 주셔서 정말 영광입니다.', `MaleText_loc4`='$n$G大人:女士;，您能与我们并肩作战，我们感到很荣幸。', `MaleText_loc5`='$G大人:女士;，$n，我們能有您在這裡真是幸運。', `MaleText_loc7`='$GSeñor:Señora;, $n, es una suerte que esté con nosotros.', `FemaleText_loc1`='$n 님, 저희와 함께 있어 주시다니 영광이로군요.', `FemaleText_loc4`='$n$G大人:女士;，您能与我们并肩作战，我们感到很荣幸。', `FemaleText_loc5`='$G大人:女士;，$n，我們能有您在這裡真是幸運。', `FemaleText_loc7`='$GSeñor:Señora;, $n, es una suerte que esté con nosotros.' WHERE `ID`=24089;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 검은 사원이 포위되었다고?', `MaleText_loc4`='……黑暗神殿正在被围攻？', `MaleText_loc5`='...黑暗神廟正在被圍攻?', `MaleText_loc7`='¿... están asediando El Templo Oscuro?' WHERE `ID`=24090;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아카마와 타락한 동료들이 알라르를 살해하고 난 다음에 바로 알도르 사제회와 점술가 길드 병력이 폭풍우 요새로 들이닥쳤다더군. 우리는 일리단을 처치하자마자 그 자리를 떴으니 다행이었지.', `MaleText_loc4`='在阿卡玛和他卑鄙的同党们干掉奥之后不久，奥尔多和占星者的军队就对黑暗神殿发动了攻击。还好我们及时离开了伊利丹。', `MaleText_loc5`='在阿卡瑪與他邪惡手下殺死歐爾之後，奧多爾和占卜者的部隊就開始猛烈地攻擊神廟。幸好我們盡快捨棄了伊利丹。', `MaleText_loc7`='Las fuerzas de los Aldor y los Arúspices asaltaron la ciudadela poco después de que Akama y sus infectos hermanos matasen a Al’ar. Elegimos un buen momento para abandonar a Illidan.' WHERE `ID`=24091;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 듣기로는 한 스무 녀석 정도가 폭풍의 눈으로 쳐들어가서 알라르를 죽였다던데.', `MaleText_loc4`='我听说有二十来人闯进风暴要塞，把他给干掉了。', `MaleText_loc5`='我聽說他們有二十幾個人闖入風暴核心並且殺死了他。', `MaleText_loc7`='Había oído que unos cuantos entraron en el Ojo y lo mataron.' WHERE `ID`=24092;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스물? 그럴 리가. 못해도 마흔 명은 있었을걸.', `MaleText_loc4`='才二十个？不可能吧，少于四十个人根本不可能。', `MaleText_loc5`='二十?不可能，絕對不可能少於四十個人。', `MaleText_loc7`='¿Veinte? Imposible, no podían ser menos de cuarenta.' WHERE `ID`=24093;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='글쎄, 어쩌면 백 명쯤 됐는지도 모르지...', `MaleText_loc4`='好吧，也许是有一百人左右吧……', `MaleText_loc5`='嗯，或許人數更多，譬如說是一百...', `MaleText_loc7`='Bueno, puede que más bien fuesen unos cien...' WHERE `ID`=24094;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 그 뭐 같은 아카마가 배신자 일리단을 배신하는 것도 시간문제겠군...', `MaleText_loc4`='阿卡玛那条狗，他背叛那个背叛者也只是时间问题而已……', `MaleText_loc5`='早晚阿卡瑪那隻狗也會出賣背叛者的...', `MaleText_loc7`='Solo es cuestión de tiempo que ese perro, Akama, traicione al Traidor también...' WHERE `ID`=24095;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용기호의 선원들은 승객 여러분이 즐겁게 여행하며 빠르게 목적지에 도착하실 수 있도록 온 힘을 다할 것입니다.', `MaleText_loc4`='勇者号上的水手将竭诚为你提供温馨舒适的服务。', `MaleText_loc5`='勇氣號的船員將會盡全力讓你的旅途迅速又舒適。', `MaleText_loc7`='La tripulación de El Valentía hará todo lo que esté en sus manos para que tu viaje sea tan rápido y agradable como sea posible.' WHERE `ID`=24096;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죄송합니다만, 나중에 이야기합시다. 이만 안녕히.', `MaleText_loc4`='不好意思，我们还是另找时间谈吧。再见。', `MaleText_loc5`='抱歉，不過我們日後一定會談談的。再見。', `MaleText_loc7`='Lo siento, pero tendremos que hablar en otro momento. Adiós.' WHERE `ID`=24097;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님이 무너진 태양 공격대와 함께 싸우니 다행이지 뭐야.', `MaleText_loc4`='破碎残阳很幸运能有$n与我们并肩作战。', `MaleText_loc5`='破碎之日進攻部隊有$n站在我們這一邊真是幸運。', `MaleText_loc7`='La Ofensiva Sol Devastado tiene suerte de que $n este de nuestro lado.', `FemaleText_loc1`='$n 님이 무너진 태양 공격대와 함께 싸워주다니 정말 다행이에요.', `FemaleText_loc4`='破碎残阳很幸运能有$n与我们并肩作战。', `FemaleText_loc5`='破碎之日進攻部隊有$n站在我們這一邊真是幸運。', `FemaleText_loc7`='La Ofensiva Sol Devastado tiene suerte de que $n este de nuestro lado.' WHERE `ID`=24098;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님이 아니었더라면 우린 진작에 죽은 목숨이라니까.', `MaleText_loc4`='要不是$n，我们可能早就死光了。', `MaleText_loc5`='要不是因為$n，我們早就死了。', `MaleText_loc7`='Si no fuera por $n, hace tiempo que estaríamos todos muertos.', `FemaleText_loc1`='$n 님이 아니었더라면 우린 진작에 죽은 목숨이지요.', `FemaleText_loc4`='要不是$n，我们可能早就死光了。', `FemaleText_loc5`='要不是因為$n，我們早就死了。', `FemaleText_loc7`='Si no fuera por $n, hace tiempo que estaríamos todos muertos.' WHERE `ID`=24099;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님, 도와주셔서 정말 고맙습니다. 당신이 없었더라면 이런 성과는 거두지 못했을 겁니다.', `MaleText_loc4`='$n，再次感谢你能帮助我们。如果没有你，我们根本不可能有这样的成就。', `MaleText_loc5`='$n，再次感謝你的協助。要沒有你，我們做不到這些事情。', `MaleText_loc7`='$n, gracias de nuevo por ayudarnos. No podríamos haber logrado nada de esto sin ti.', `FemaleText_loc1`='$n 님, 도와주셔서 정말 감사해요. 당신이 없었더라면 이런 성과는 거두지 못했을 거랍니다.', `FemaleText_loc4`='$n，再次感谢你能帮助我们。如果没有你，我们根本不可能有这样的成就。', `FemaleText_loc5`='$n，再次感謝你的協助。要沒有你，我們做不到這些事情。', `FemaleText_loc7`='$n, gracias de nuevo por ayudarnos. No podríamos haber logrado nada de esto sin ti.' WHERE `ID`=24100;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='용기호에 오신 것을 환영합니다, $g선생님:부인;. 할 일이 있어서 저는 이만...', `FemaleText_loc4`='欢迎乘坐勇者号。不好意思，失陪……', `FemaleText_loc5`='歡迎來到勇氣號，$g先生:女士;。現在如果可以的話，請容許我...', `FemaleText_loc7`='$gBienvenido:Bienvenida; a El Valentía, $gseñor:señora;. Ahora, si me disculpa...' WHERE `ID`=24101;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님께 만세 삼창!', `MaleText_loc4`='为$n欢呼三声！', `MaleText_loc5`='為$n歡呼三聲!', `MaleText_loc7`='¡Tres hurras por $n!', `FemaleText_loc1`='$n 님께 만세 삼창!', `FemaleText_loc4`='为$n欢呼三声！', `FemaleText_loc5`='為$n歡呼三聲!', `FemaleText_loc7`='¡Tres hurras por $n!' WHERE `ID`=24102;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='함께하게 되어 정말 영광입니다, $n.', `MaleText_loc4`='$n，能为您效劳，我感到很荣幸。', `MaleText_loc5`='能和你並肩作戰是我的榮幸，$n。', `MaleText_loc7`='Es un honor servir junto a ti, $n.', `FemaleText_loc1`='함께하게 되니 정말 영광이네요, $n.', `FemaleText_loc4`='$n，能为您效劳，我感到很荣幸。', `FemaleText_loc5`='能和你並肩作戰是我的榮幸，$n。', `FemaleText_loc7`='Es un honor servir junto a ti, $n.' WHERE `ID`=24103;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님께서 정말 여러 차례 악마들을 막아내 주셨지.', `MaleText_loc4`='$n化解了无数次恶魔的攻势。', `MaleText_loc5`='$n抵擋了那些惡魔無數次。', `MaleText_loc7`='$n ha mantenido a los demonios a raya en innumerables ocasiones.', `FemaleText_loc1`='$n 님께서 정말 여러 차례 악마들을 막아내 주셨지요.', `FemaleText_loc4`='$n化解了无数次恶魔的攻势。', `FemaleText_loc5`='$n抵擋了那些惡魔無數次。', `FemaleText_loc7`='$n ha mantenido a los demonios a raya en innumerables ocasiones.' WHERE `ID`=24104;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 웨이브싱어 일등항해사님이 너무 부러워요. 왜냐고요? 그분은 여자인 저보다도 예쁘시잖아요!', `FemaleText_loc4`='我有点嫉妒维瓦·水歌了。为什么？他比我更优秀！', `FemaleText_loc5`='我真是嫉妒我們的浪詠先生。為什麼，他一整個就是比我漂亮!', `FemaleText_loc7`='Casi siento celos de nuestro señor Canto de las Olas. ¡Puede que sea más guapo que yo!' WHERE `ID`=24105;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 새벽칼날단 블러드 엘프였다면 $n의 모습을 보자마자 이 섬에서 헤엄쳐 도망갔을 거라니까...', `MaleText_loc4`='如果我是那些晨锋血精灵的话，我一看到$n来了就会立即跳水游走。', `MaleText_loc5`='要是我是那些曦刃血精靈，我一定用游的也要逃離這座島，因為$n就在這裡。', `MaleText_loc7`='Si yo fuera uno de esos elfos de sangre Hojalba, ahora que $n está aquí estaría alejándome de la isla a nado.', `FemaleText_loc1`='내가 새별칼날단 블러드 엘프였다면 $n의 모습을 보자마자 이 섬에서 헤엄쳐 도망갔을 거예요.', `FemaleText_loc4`='如果我是那些晨锋血精灵的话，我一看到$n来了就会立即跳水游走。', `FemaleText_loc5`='要是我是那些曦刃血精靈，我一定用游的也要逃離這座島，因為$n就在這裡。', `FemaleText_loc7`='Si yo fuera uno de esos elfos de sangre Hojalba, ahora que $n está aquí estaría alejándome de la isla a nado.' WHERE `ID`=24106;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님이 처치한 버림받은 엘프 녀석은 대체 얼마나 될까?', `MaleText_loc4`='你觉得$n终结了多少失心者的痛苦？', `MaleText_loc5`='你覺得$n替多少鄙惡者終結了他們的悲劇?', `MaleText_loc7`='¿Con cuántos desdichados crees que ha acabado $n?', `FemaleText_loc1`='$n 님이 처치한 버림받은 엘프 녀석은 대체 얼마나 될까요?', `FemaleText_loc4`='你觉得$n终结了多少失心者的痛苦？', `FemaleText_loc5`='你覺得$n替多少鄙惡者終結了他們的悲劇?', `FemaleText_loc7`='¿Con cuántos desdichados crees que ha acabado $n?' WHERE `ID`=24107;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 주목! 우리의 용사 $n 님이 오신다!', `MaleText_loc4`='快看，我们最棒的勇士$n，在这里！', `MaleText_loc5`='大家注意，$n，我們最棒的就在這裡!', `MaleText_loc7`='¡Firmes, $n, uno de los mejores, está aquí!', `FemaleText_loc1`='모두 주목하세요! 우리의 용사 $n 님이 오시네요!', `FemaleText_loc4`='快看，我们最棒的勇士$n，在这里！', `FemaleText_loc5`='大家注意，$n，我們最棒的就在這裡!', `FemaleText_loc7`='¡Firmes, $n, uno de los mejores, está aquí!' WHERE `ID`=24108;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='선원 노릇 하기엔 제 이름이 좀 불길하죠?', `FemaleText_loc4`='对水手来说，这是个不幸的名字，是吗？', `FemaleText_loc5`='對一個水手來說，不是個好名字，不是嗎?', `FemaleText_loc7`='Un nombre poco apropiado para un marinero, ¿no te parece?' WHERE `ID`=24109;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 돌아오셨습니다, $n 님.', `MaleText_loc4`='欢迎回来，$n。', `MaleText_loc5`='歡迎回來，$n。', `MaleText_loc7`='Te damos la bienvenida de nuevo, $n.', `FemaleText_loc1`='다시 오신 걸 환영해요, $n 님.', `FemaleText_loc4`='欢迎回来，$n。', `FemaleText_loc5`='歡迎回來，$n。', `FemaleText_loc7`='Te damos la bienvenida de nuevo, $n.' WHERE `ID`=24110;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 영웅이 납시는군. 잘 계셨습니까, $n?', `MaleText_loc4`='我们的英雄来了！最近过得怎么样，$n？', `MaleText_loc5`='我們的$g英雄:女英雄;就在這兒!你好嗎，$n?', `MaleText_loc7`='¡Ahí está nuestro $ghéroe:heroína;! ¿Qué tal te va, $n?', `FemaleText_loc1`='저기 우리 영웅이 오시는군요. 잘 계셨나요, $n?', `FemaleText_loc4`='我们的英雄来了！最近过得怎么样，$n？', `FemaleText_loc5`='我們的$g英雄:女英雄;就在這兒!你好嗎，$n?', `FemaleText_loc7`='¡Ahí está nuestro $ghéroe:heroína;! ¿Qué tal te va, $n?' WHERE `ID`=24111;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님이 안 계셨더라면 이 공격대는 실패한 연합군으로 남았을 겁니다. 내가 장담하지요.', `MaleText_loc4`='我承认，如果不是$n，整场战役都会一败涂地。', `MaleText_loc5`='我敢保證要是沒有$n，整個進攻計畫一定會慘敗。', `MaleText_loc7`='Te aseguro que sin ti, $n, esta ofensiva habría sido un fracaso.', `FemaleText_loc1`='장담하는데 $n 님이 안 계셨더라면 이 공격대의 임무는 모두 실패로 돌아갔을 겁니다.', `FemaleText_loc4`='我承认，如果不是$n，整场战役都会一败涂地。', `FemaleText_loc5`='我敢保證要是沒有$n，整個進攻計畫一定會慘敗。', `FemaleText_loc7`='Te aseguro que sin ti, $n, esta ofensiva habría sido un fracaso.' WHERE `ID`=24112;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어찌됐건 당신의 업적은 이곳에 영원히 남을 겁니다, $n!', `MaleText_loc4`='无论怎样，我们都将永远赞扬你所作出的努力，$n！', `MaleText_loc5`='不管如何，你的貢獻永遠會在這裡備受尊崇，$n!', `MaleText_loc7`='¡Pase lo que pase tus esfuerzos siempre serán exaltados aquí, $n!', `FemaleText_loc1`='누가 뭐래도 당신의 업적은 이곳에 영원히 남을 겁니다, $n!', `FemaleText_loc4`='无论怎样，我们都将永远赞扬你所作出的努力，$n！', `FemaleText_loc5`='不管如何，你的貢獻永遠會在這裡備受尊崇，$n!', `FemaleText_loc7`='¡Pase lo que pase tus esfuerzos siempre serán exaltados aquí, $n!' WHERE `ID`=24113;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 머리가 반백이고 선원 중에 제일 나이가 든 건 사실이지만, 여전히 가장 억센 뱃사람이랍니다! 어때요? 그렇죠? 오우거만한 이 팔뚝 좀 보십시오!', `MaleText_loc4`='他大概是年纪最大、最有经验的水手了吧，他的体格最强壮！嗯？嗯？和食人魔一样粗壮的手臂！', `MaleText_loc5`='我這個灰髮的老水手雖然是船員中最老的，不過也是當中最強悍的!是吧?是吧?手臂就像巨魔一樣粗壯!', `MaleText_loc7`='Puede que este canoso lobo de mar sea el más viejo de la tripulación, pero también es el más duro del grupo. ¡Mira! ¡Mira! ¡Sus brazos parecen los de un ogro!' WHERE `ID`=24114;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 죽음의 흉터에서 악마들을 잡으셨군요, $n 님?', `MaleText_loc4`='最近在死亡之痕蹂躏那些恶魔吗，$n？', `MaleText_loc5`='晚點再對付那些死亡之痕的那些惡魔，$n?', `MaleText_loc7`='¿Has arrasado a los demonios de La Cicatriz Muerta últimamente, $n?', `FemaleText_loc1`='또 죽음의 흉터에서 악마들을 초토화하신 건가요, $n 님?', `FemaleText_loc4`='最近在死亡之痕蹂躏那些恶魔吗，$n？', `FemaleText_loc5`='晚點再對付那些死亡之痕的那些惡魔，$n?', `FemaleText_loc7`='¿Has arrasado a los demonios de La Cicatriz Muerta últimamente, $n?' WHERE `ID`=24115;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님, 조만간 술 한 잔 대접하도록 하지요.', `MaleText_loc4`='$n，哪天我请你喝杯酒吧。', `MaleText_loc5`='$n，我一直很想買杯飲料請你。', `MaleText_loc7`='$n, uno de estos días quiero invitarte a una bebida.', `FemaleText_loc1`='$n 님, 조만간 술 한 잔 대접할게요.', `FemaleText_loc4`='$n，哪天我请你喝杯酒吧。', `FemaleText_loc5`='$n，我一直很想買杯飲料請你。', `FemaleText_loc7`='$n, uno de estos días quiero invitarte a una bebida.' WHERE `ID`=24116;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님께서 돌아오지 않았다면 이곳이 어떻게 됐을지 생각하고 싶지도 않군그래.', `MaleText_loc4`='我简直不敢想象，如果$n决定不再回来的话，这里将会变成什么样子。', `MaleText_loc5`='我不敢想像如果$n不會來的話，會發生什麼事。', `MaleText_loc7`='No quiero ni imaginarme lo que pasará aquí si $n decide no volver.', `FemaleText_loc1`='$n 님께서 돌아오지 않았다면 이곳이 어떻게 됐을지 생각하고 싶지도 않네요.', `FemaleText_loc4`='我简直不敢想象，如果$n决定不再回来的话，这里将会变成什么样子。', `FemaleText_loc5`='我不敢想像如果$n不會來的話，會發生什麼事。', `FemaleText_loc7`='No quiero ni imaginarme lo que pasará aquí si $n decide no volver.' WHERE `ID`=24117;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저희는 용기호의 승객 여러분을 목숨 걸고 지키겠다고 맹세했답니다. 루테란 마을과 스톰윈드 항구를 잇는 항로를 안전하게 지켜야지요.', `FemaleText_loc4`='我们发誓要全力保卫勇者号乘客。必须确保鲁瑟兰村至暴风城港口航道的安全。', `FemaleText_loc5`='我們立過誓要盡其所能來保護勇氣號上的乘客。一定要維持魯瑟蘭村與暴風港間航道的安全。', `FemaleText_loc7`='Hemos jurado hacer todo lo que esté en nuestras manos para proteger a los pasajeros de El Valentía. La línea marítima entre la Aldea Rut''theran y el Puerto de Ventormenta ha de ser segura.' WHERE `ID`=24118;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님, 당신 모습을 보는 것만으로도 얼마나 안심이 되는지 모를 거랍니다.', `MaleText_loc4`='$n，你不知道看到你给我们带来了多大的安慰。', `MaleText_loc5`='$n，我看到你的時候整個人都鬆了一口氣!', `MaleText_loc7`='¡$n, no sabes cuánto nos alivia verte!', `FemaleText_loc1`='$n 님, 당신 모습을 보는 것만으로도 얼마나 안심이 되는지 모를 거예요.', `FemaleText_loc4`='$n，你不知道看到你给我们带来了多大的安慰。', `FemaleText_loc5`='$n，我看到你的時候整個人都鬆了一口氣!', `FemaleText_loc7`='¡$n, no sabes cuánto nos alivia verte!' WHERE `ID`=24119;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='희한하군요... 마침 당신 얘기를 하고 있었답니다, $n 님!', `MaleText_loc4`='太巧了……我们刚提到你，$n！', `MaleText_loc5`='真是巧了...我們正好聊到你，$n!', `MaleText_loc7`='Qué coincidencia... ¡justo estábamos hablando sobre ti, $n!', `FemaleText_loc1`='우연치곤 희한하네요... 마침 당신 얘기를 나누고 있었거든요, $n 님!', `FemaleText_loc4`='太巧了……我们刚提到你，$n！', `FemaleText_loc5`='真是巧了...我們正好聊到你，$n!', `FemaleText_loc7`='Qué coincidencia... ¡justo estábamos hablando sobre ti, $n!' WHERE `ID`=24120;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님께서 여기 계시는데 누가 보초병이 필요하겠어!', `MaleText_loc4`='有$n在这里，谁还需要魔像守卫？', `MaleText_loc5`='誰需要哨兵?$n在這裡耶!', `MaleText_loc7`='¿Quién necesita centinelas? ¡$n está aquí!', `FemaleText_loc1`='$n 님께서 여기 계시는데 누가 보초병 따위가 필요하겠어요?', `FemaleText_loc4`='有$n在这里，谁还需要魔像守卫？', `FemaleText_loc5`='誰需要哨兵?$n在這裡耶!', `FemaleText_loc7`='¿Quién necesita centinelas? ¡$n está aquí!' WHERE `ID`=24121;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님, 그 영광을 우리도 함께 누리게 해 주시겠습니까?', `MaleText_loc4`='嗨，$n，也给我们留点事做吧，让我们也能得到些赞扬好不好啊？', `MaleText_loc5`='嘿，$n，把一點戰功光榮留給我們嘛?', `MaleText_loc7`='Hey, $n, deja algo de gloria para nosotros, ¿vale?', `FemaleText_loc1`='$n 님, 그 영광을 우리도 함께 누리게 해 주시겠어요?', `FemaleText_loc4`='嗨，$n，也给我们留点事做吧，让我们也能得到些赞扬好不好啊？', `FemaleText_loc5`='嘿，$n，把一點戰功光榮留給我們嘛?', `FemaleText_loc7`='Hey, $n, deja algo de gloria para nosotros, ¿vale?' WHERE `ID`=24122;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새벽칼날단을 태양너울 항구에서 몰아냈소! 우리가 승리했소!', `MaleText_loc4`='晨锋部队被赶出了阳湾港口！我们胜利了！', `MaleText_loc5`='曦刃部隊已經被逐出了日境港!我們勝利了!', `MaleText_loc7`='¡Las fuerzas Hojalba han sido eliminadas del Puerto de Tramo del Sol! ¡Hoy es nuestro día!' WHERE `ID`=24123;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조사 중', `MaleText_loc4`='检查', `MaleText_loc5`='檢查中', `MaleText_loc7`='Examinando', `FemaleText_loc1`='조사 중', `FemaleText_loc4`='检查', `FemaleText_loc5`='檢查中', `FemaleText_loc7`='Examinando' WHERE `ID`=24124;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여어, 젊은이. 처녀의 몽상호에 온 걸 환영하네. 나는 렌치노즐 선장이고, 자네는 검은바다 해적단의 보호 아래 안전하게 항해할 걸세. 붉은해적단은 배에 저장해 둔 엄청난 양의 화약과 용맹한 우리 선원들이 무서워서 가까이 오지 않을 테니 말이야. 알겠지만, 일종의 보험이라고.$b$b질문이 있다면, 젊은이, 내가 대답해 주지.', `MaleText_loc4`='嗨，孩子。欢迎乘坐少女之爱号。我是维克诺兹船长，能与黑水海盗一起航行是你的荣幸。血帆海盗根本不敢靠近，因为我们有最精锐的水手，货舱里还堆放着大量火药。你知道，所谓安全保障嘛。$b$b如果你有有疑问，尽管来问我好了。', `MaleText_loc5`='嘿，小子。你登上的是少女之愛號。我是擰鼻船長，你已獲得在黑水強盜群中航行的特權。血帆無法靠近，無法與我精明的船員及手中的大量火藥比擬。你知道的，保險起見。$b$b如果你有任何問題的話，小子，我會知無不言的。', `MaleText_loc7`='Hola. Estás a bordo de La Fantasía de la Doncella. Yo soy el capitán Cánula y tienes el privilegio de navegar en el orgullo de los Asaltantes Aguasnegras. Los Velasangre no se nos acercan gracias a mi astuta tripulación y a la gran cantidad de pólvora que llevamos en la bodega. El seguro, ya sabes.$B$BSi tienes alguna pregunta, yo te daré respuestas.' WHERE `ID`=24125;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='처녀의 몽상호', `MaleText_loc4`='少女之爱号', `MaleText_loc5`='少女之愛號', `MaleText_loc7`='La Fantasía de la Doncella', `FemaleText_loc1`='처녀의 몽상호', `FemaleText_loc4`='少女之爱号', `FemaleText_loc5`='少女之愛號', `FemaleText_loc7`='La Fantasía de la Doncella' WHERE `ID`=24126;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 지금 자네가 탄 배가 바로 그 배지. 정말 아름답지 않나? 남작님이 얼마 전에 날 여기 선장으로 임명했지. 내 배가 아니라서 이름을 붙일 수는 없었다네. 이름에 대한 내 의견이 궁금하다면, 젊은이, 이 배에 이름을 붙인 뱃사람은 원하는 만큼 항구에서 시간을 보내지 못하고 바다에만 너무 오래 있었던 듯하다고. 내 말이 무슨 뜻인지 안다면 말이지만.', `MaleText_loc4`='这就是少女之爱号。她很漂亮，是吧？不久前，公爵委派我担任这艘船的船长。她本不属于我，因此“少女之爱”这个名字不是我取的。我猜为她取名的水手大概是在海上航行太久了，没能好好享受港口的美妙时光。你懂我的意思吗？', `MaleText_loc5`='沒錯，你正站在她上面。很美，對吧?大財主任命我為船長了。她起初並不屬於我，因此名字不是我取的;小子，如果你想知道我的意見的話，我想當初為她命名的水手花了太多的時間在海上，待在港口的時間並不多，如果你懂我的意思的話。', `MaleText_loc7`='Sí, te encuentras sobre él. Una preciosidad, ¿verdad? El Barón me nombró capitán hace algún tiempo. No fue mío desde el principio, así que no lo bauticé yo; si quieres mi opinión, creo que el marinero que lo bautizó pasaba demasiado tiempo en el mar y muy poco en tierra, si sabes a qué me refiero.' WHERE `ID`=24127;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배가 꾸르륵거린다면 주방장인 스틸벨리한테 가보게나. 하지만 우리끼리 이야기인데, 그냥 항구에 도착하길 기다리는 게 나을 거라고. 요리할 때 남의 위장을 생각해 주는 사람이 아니라서 말이야.', `MaleText_loc4`='如果你的肚子饿得咕咕叫，就去找厨师长拜雷·钢胃谈谈，可别说是我告诉你的这家伙的名字可是有来历的……', `MaleText_loc5`='如果你飢腸轆轆的話，去找船艙長鋼腹談談，不過我們之間知道就好?你可能會想等一下。他會叫那個名字不是沒有原因的。', `MaleText_loc7`='Si te ruge el estómago, habla con el Jefe de galera Tripacero, pero, entre tú y yo, quizá prefieras esperar. Se llama así por algo.' WHERE `ID`=24128;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='설마 스팀휘들 무역회사의 배에 기술자가 없겠나? 톨크스핀들이 다양한 물건을 팔고 있네. 수리가 필요하면 물건도 재빨리 고쳐 준다고.', `MaleText_loc4`='热砂港的船只怎可能没有工程师呢？托克斯宾德出售所有你需要的物品。如果你想要修理物品的话，他的技术也不错哟。', `MaleText_loc5`='一艘熱砂船沒有工程師的話行嗎，對不對?矩軸可以幫忙你所有的需求。他對於快速修復東西也很在行，如果這就是你在尋找的東西。', `MaleText_loc7`='¿Qué sería un barco Bonvapor sin un ingeniero? Ejepar puede ayudarte con cualquier cosa que necesites. También es muy hábil reparando cosas rápido, si eso es lo que quieres.' WHERE `ID`=24129;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='페더문 수색선에 오른 것을 환영하오. 이 배는 페더문 요새와 잊혀진 해안 사이를 오가며 바다에서 실종된 이들을 찾고 있소. 제대로 준비하지 않으면 바다는 위험하기 그지없는 곳이라오.$b$b챙겨야 할 게 있다면 우리 배의 선창 담당자들과 이야기하시오. 그대에게 도움이 된다면 그들은 정말로 기뻐할 거요.', `MaleText_loc4`='欢迎乘坐羽月渡船号。我们往返于羽月要塞和被遗忘的海岸，搜寻不幸的落水者。大海暗藏危机，你必须做好充分的准备。$b$b你可以和食物供给商谈谈，购买足够的干粮。他们会很乐意帮忙的。', `MaleText_loc5`='歡迎登上羽月渡口。我們往來於羽月要塞及被遺忘的海岸之間搜尋那些在海上失蹤的人們。大海對那些沒做好準備的人來說會是個危險的地方。$b$b如果你需要準備什麼的話，請與我們的物資供應者談談。他們會很樂意幫忙你的。', `MaleText_loc7`='Te doy la bienvenida a bordo del Transbordador de Plumaluna. Viajamos entre el Bastión Plumaluna y La Costa Olvidada buscando a quienes se perdieron en el mar. Este mar puede ser un lugar peligroso si no estás preparado.$B$BSi necesitas prepararte, habla con nuestros proveedores. Están más que dispuestos a ayudarte.' WHERE `ID`=24130;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달무리호의 승무원을 대표해 그대를 환영합니다, $c. 배에서 내리기 전에 선창 담당자가 파는 물건을 둘러보시는 게 어떻습니까?', `MaleText_loc4`='我代表月海之浪号的全体船员欢迎你,$c。希望在起航之前，我们的食物供应商能帮你准备好一切。', `MaleText_loc5`='謹代表月霧號的船員，歡迎你$c。我希望你會在與我們分別前好好使用我們準備的糧食。', `MaleText_loc7`='En nombre de la tripulación del Espuma de la Luna, te doy la bienvenida $c. Espero que hagas uso de nuestras provisiones antes de partir.' WHERE `ID`=24131;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엘룬의 축복호에 온 걸 환영하오. 승선할 때 발밑을 조심하시오, $r. 엘룬께서는 이렇게 새 친구를 보내 우리를 축복하셨지만, 여전히 우리에겐 바다에서의 고충이 짐 지워져 있소.$b$b하지만, 바다나 새로운 세계에서 길을 잃은 영혼을 되찾는 건 진정 엘룬 여신의 축복이라오.', `MaleText_loc4`='搭乘艾露恩的祝福号时请保持警惕，$r。虽然艾露恩保佑我们找到了新的盟友，但是深不可测的海洋依然危机四伏。$B$B但是，在月神的感召下，我们承担起搜寻失落灵魂的重任。', `MaleText_loc5`='登上伊露恩祝福號時請留意你的腳步，$r。雖然伊露恩使我們有幸發現我們的新朋友，但是我們在大海中也有過艱辛的時候。$b$b不過，找回迷失於大海中或是迷失在一個新世界中的靈魂的確都是來自伊露恩的祝福。', `MaleText_loc7`='Ten cuidado a bordo del Bendición de Elune, $r. Aunque Elune nos ha bendecido con el descubrimiento de nuestros nuevos amigos, también hemos sufrido la dureza del mar.$B$BSin embargo, recuperar almas perdidas en el mar o en un nuevo mundo es una auténtica bendición de Elune.' WHERE `ID`=24132;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엘룬 여신의 축복 덕분에 저희는 수많은 발견을 해냈습니다. 하지만 그렇다고 방심하면 안 되겠지요, $c님.', `MaleText_loc4`='在航海之旅中，艾露恩一直庇护着我们。但是我们仍然要保持警惕，$c。', `MaleText_loc5`='伊露恩在我們每一次的發現中祝福過我們很多次。不過我們必須保持警戒，$c。', `MaleText_loc7`='Elune nos ha bendecido muchas veces con los descubrimientos que hemos realizado. Pero debemos permanecer atentos, $c.', `FemaleText_loc1`='엘룬 여신의 축복 덕분에 저희는 수많은 발견을 해냈어요. 하지만 그렇다고 방심하면 안 되겠지요, $c님.', `FemaleText_loc4`='在航海之旅中，艾露恩一直庇护着我们。但是我们仍然要保持警惕，$c。', `FemaleText_loc5`='伊露恩在我們每一次的發現中祝福過我們很多次。不過我們必須保持警戒，$c。', `FemaleText_loc7`='Elune nos ha bendecido muchas veces con los descubrimientos que hemos realizado. Pero debemos permanecer atentos, $c.' WHERE `ID`=24133;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='양해해 주세요, $r님, 제가 맡은 일은 집중해서 해야 하니까요.', `FemaleText_loc4`='不好意思，$r，我必须专心工作。', `FemaleText_loc5`='請原諒我，$r，我必須專心工作。', `FemaleText_loc7`='Discúlpame, $r, he de concentrarme en mi trabajo.' WHERE `ID`=24134;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='죄송해요, 위습이나 선장님께 제가 찾아낸 내용을 보고하는 것 말고 다른 사람과 얘기할 짬이 전혀 없네요. 이해해 주세요.', `FemaleText_loc4`='对不起，除了与小精灵交流并向船长汇报我的发现之外，我没时间和其他人闲聊。请原谅。', `FemaleText_loc5`='很抱歉，我除了跟幽光還有船長報告我的發現之外，沒有多少時間可以跟人聊天。請原諒我。', `FemaleText_loc7`='Lo siento, no tengo tiempo para hablar con nadie más que los fuegos fatuos y el Capitán para informar de mis hallazgos. Discúlpame.' WHERE `ID`=24135;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='처녀의 몽상호에 타신 것을 환영하는 바요. 항구까지 안전하고 편안하게 모실 것을 약속드리오.', `MaleText_loc4`='欢迎乘坐少女之爱号。她将载你安全驶往港口。', `MaleText_loc5`='歡迎登上少女之愛號。它將會一路順風的抵達港口。', `MaleText_loc7`='$gBienvenido:Bienvenida; a bordo de La Fantasía de la Doncella. Debería ser una travesía tranquila hasta el puerto.' WHERE `ID`=24136;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노움의 옆구리를 여러 번 찔러대면 얼마나 유용한 정보를 얻어낼 수 있는지 알면 아마 놀랄 걸세. 묶인 상태를 벗어나는 꼼수나 맛있는 과자를 굽는 비법, 심지어 하늘을 나는 기계를 만드는 비법까지 말이지.', `MaleText_loc4`='如果你狠狠地捏一个侏儒，是可以学到很多东西的：比如说逃脱的小伎俩，制作美味的曲奇饼干，甚至可以学到如何制造飞行器。', `MaleText_loc5`='如果你用力壓榨地精的話，你可以從他身上學到很驚人的東西:逃脫捆綁的聰明小把戲，製造美味的餅乾，甚至連如何製造出一台飛行器都有。', `MaleText_loc7`='Es increíble lo que puedes aprender de un gnomo si lo estrujas con fuerza suficiente: trucos astutos sobre cómo librarse de unas ataduras, hacer galletas deliciosas e, incluso, cómo construir una máquina voladora.' WHERE `ID`=24137;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하늘을 나는 기계라고요?', `MaleText_loc4`='飞行器？', `MaleText_loc5`='飛行器?', `MaleText_loc7`='¿Máquinas voladoras?', `FemaleText_loc1`='하늘을 나는 기계라고요?', `FemaleText_loc4`='飞行器？', `FemaleText_loc5`='飛行器?', `FemaleText_loc7`='¿Máquinas voladoras?' WHERE `ID`=24138;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노움 옆구리를 자주 찌르십니까?', `MaleText_loc4`='你经常捏侏儒吗？', `MaleText_loc5`='你常壓榨地精嗎?', `MaleText_loc7`='¿Estrujas gnomos a menudo?', `FemaleText_loc1`='노움 옆구리를 자주 찌르시나 보죠?', `FemaleText_loc4`='你经常捏侏儒吗？', `FemaleText_loc5`='你常壓榨地精嗎?', `FemaleText_loc7`='¿Estrujas gnomos a menudo?' WHERE `ID`=24139;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기회가 생길 때마다 찌른다네. 운동도 될뿐더러 노움 녀석들이 무슨 연구를 하고 있나 알아내는 데는 제격이라네. 뭐 지난 경험한 바에 비추어 얘기하자면, 좋은 연구는 아니더군.', `MaleText_loc4`='我一有空就会这么做。感觉非常不错，同时也能让我把握他们的心思——照我的经验来说，通常没什么好事。', `MaleText_loc5`='常常。這是好活動，讓我可以知道他們在忙些什麼--就我的經驗來說，絕對不是好事。', `MaleText_loc7`='Siempre que puedo. Es un ejercicio magnífico y me mantiene informado sobre lo que traman, que sé por experiencia, que nunca es nada bueno.' WHERE `ID`=24140;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그거... 멋지군요. 하늘을 나는 기계는 어떤 겁니까?', `MaleText_loc4`='那实在是……太棒了。你说的飞行器是什么？', `MaleText_loc5`='真是...太棒了。這些飛行器如何呢?', `MaleText_loc7`='Eso... es genial. ¿Qué sabes de esas máquinas voladoras?', `FemaleText_loc1`='그거... 멋지네요. 하늘을 나는 기계는 어떤 건가요?', `FemaleText_loc4`='那实在是……太棒了。你说的飞行器是什么？', `FemaleText_loc5`='真是...太棒了。這些飛行器如何呢?', `FemaleText_loc7`='Eso... es genial. ¿Qué sabes de esas máquinas voladoras?' WHERE `ID`=24141;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다! 저도 지금 찔러 보도록 하죠.', `MaleText_loc4`='谢谢提醒！我现在就去试试。', `MaleText_loc5`='謝了!我現在就試試看。', `MaleText_loc7`='¡Gracias! Lo probaré ahora!', `FemaleText_loc1`='고마워요! 저도 지금 바로 찔러 볼게요.', `FemaleText_loc4`='谢谢提醒！我现在就去试试。', `FemaleText_loc5`='謝了!我現在就試試看。', `FemaleText_loc7`='¡Gracias! Lo probaré ahora!' WHERE `ID`=24142;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 죽일 듯한 기세로 격분합니다!', `MaleText_loc4`='%s变得极为狂暴！', `MaleText_loc5`='%s變得極為狂暴!', `MaleText_loc7`='¡%s entra en frenesí asesino!' WHERE `ID`=24143;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 분노에 휩싸입니다!', `MaleText_loc4`='%s变得愤怒了！', `MaleText_loc5`='%s暴怒了起來!', `MaleText_loc7`='¡%s se enfurece!' WHERE `ID`=24144;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연', `MaleText_loc4`='风筝', `MaleText_loc5`='風箏', `MaleText_loc7`='Cometa', `FemaleText_loc1`='연', `FemaleText_loc4`='风筝', `FemaleText_loc5`='風箏', `FemaleText_loc7`='Cometa' WHERE `ID`=24145;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로켓닭', `MaleText_loc4`='火箭鸡', `MaleText_loc5`='火箭雞', `MaleText_loc7`='Gallina cohete', `FemaleText_loc1`='로켓닭', `FemaleText_loc4`='火箭鸡', `FemaleText_loc5`='火箭雞', `FemaleText_loc7`='Gallina cohete' WHERE `ID`=24146;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='종이비행기', `MaleText_loc4`='纸飞机', `MaleText_loc5`='紙飛機', `MaleText_loc7`='Avión de papel', `FemaleText_loc1`='종이비행기', `FemaleText_loc4`='纸飞机', `FemaleText_loc5`='紙飛機', `FemaleText_loc7`='Avión de papel' WHERE `ID`=24147;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으윽... 저쪽에 있는 게으른 주방장이 특별 요리를 권하면, 부디 자기 자신을 위해서 그냥 바닷속에 던져버리시오. 마크루라 몇 마리를 죽이는 게 살고자 하는 의지를 잃는 것보다야 낫지 않소?', `MaleText_loc4`='嗯……如果那个讨厌的船长向你推销他的特价品，你就直接把那些烂货扔进海里去。说不定有些龙虾人会因此丧命，不过好在你能捡回一条命呀。', `MaleText_loc5`='噁噁噁...要是那邊那個骯髒的船艙長要你吃他的特別餐的話，幫你自己個忙，把它丟到海裡吧。它可能可以殺死幾個你想致之死地的龍蝦人。', `MaleText_loc7`='Urrrk... si ese avaricioso jefe de galera te ofrece su especial, hazte un favor y tíralo al océano. Puede que mate algunos makruras en vez de tus ganas de vivir.' WHERE `ID`=24148;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요.$b$b이제 움직일 시간이에요! 올지 안 올지 알 수 없는 보급품을 마냥 기다릴 수는 없잖아요.$b$b병사들에게 제대로 된 장비를 공급하려면 모루가 필요해요. 모루는 현재까지 $3228w 퍼센트 완성되었답니다.$b$b모루가 완성되면, 제가 만들어드릴 수 있는 더 강력한 물건들이 많아질 겁니다.', `FemaleText_loc4`='你好，$r。$B$B让我们开动起来！根本不要指望那些也许永远都到不了的补给。$B$B我需要一块铁砧才能为我们的军队提供装备，但是现在只完成了$3228w%%。$b$b等铁砧完成之后，我就可以为你锻造许多强大的武器装备了。', `FemaleText_loc5`='嗨，$r。$b$b動手吧!別浪費時間等那些可能永遠也不會到的補給。$b$b我需要我的鐵砧來替部隊打造裝備。目前才完成了$3228w％。$b$b當鐵砧完成後，我將可以為你做出更多強而有力的物品。', `FemaleText_loc7`='Hola, $r.$B$B¡Pongámonos manos a la obra! No tiene sentido esperar unos suministros que podrían no llegar nunca.$B$BNecesito mi yunque para poder equipar a las tropas debidamente. Ahora mismo está completado en un $3228w %.$B$BY cuando el yunque esté terminado, habrá muchos más objetos poderosos que podré forjar para ti.' WHERE `ID`=24149;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, $n.$b$b모루가 완성되어서 이제 병사들이 장비를 갖출 수 있게 됐어요. 물론 이 일도 중요하지만, 아직 할 일이 많이 남았답니다.$b$b당신에게 더 중요한 건 말이죠, 제가 만들 수 있는 새로운 물건이 있다는 거죠. 아마 관심이 갈 거예요.', `FemaleText_loc4`='你好，$n。$b$b我已经造好了铁砧，可以开始装备我们的军队了。这一步对我们来说非常重要，不过仍然有许多事需要去做。$B$B对你来说更重要的是：我可以制造新的武器装备了！也许你会对此感兴趣。', `FemaleText_loc5`='嗨，$n。$b$b現在我已經完成了鐵砧，可以開始替部隊提供裝備了。這是很重要的一步，但還有許多事情得去做。$b$b更重要的是，我能製作新東西了，你可能會很感興趣的東西。', `FemaleText_loc7`='Hola, $n.$B$BAhora que he terminado de crear mi yunque, puedo comenzar a equipar a nuestras tropas. Es un gran paso, pero aún queda mucho por hacer.$B$BLo que más debería importarte a ti es que ahora podré crear cosas nuevas que podrían interesarte.' WHERE `ID`=24150;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리가 항구를 장악했습니다. 그리고 이 배는 정말 괜찮은 전리품이죠. 아직 항해에 써먹을 수 없는 게 아쉬울 따름입니다.$B$B그나저나, 초록아가미 해안의 나가를 감시하라는 명령을 받았는데...$B$B그대가 좀 도와줄 수 있을까요?', `FemaleText_loc4`='我们已经拿下了港口，这艘船真的算是个不错的奖励。只不过她还不适合航海。$B$B对了，我得到命令去监视绿鳃海岸一带的纳迦。$B$B你觉得你能帮帮我吗？', `FemaleText_loc5`='我們拿下了港口，而這艘船更是額外的收穫。可惜她已經不再適合航行了。$B$B不過我被指派要干擾綠鰓海岸的納迦。$B$B你能給我一些幫助嗎?', `FemaleText_loc7`='Hemos tomado el puerto y este barco es un bonito extra. Una pena que aún no se pueda llevar al mar.$B$BMientras, se me ha ordenado que supervise el desbaratamiento de los nagas en la Costa Branquia Verde.$B$B¿Crees que puedes ayudarme?' WHERE `ID`=24151;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새벽칼날단의 증원군을 차단하려고 합니다.', `MaleText_loc4`='我必须阻止晨锋部队的增援。', `MaleText_loc5`='我需要截斷曦刃的增援部隊。', `MaleText_loc7`='Tengo que interceptar a los refuerzos Hojalba.', `FemaleText_loc1`='새벽칼날단의 증원군을 차단하려고 합니다.', `FemaleText_loc4`='我必须阻止晨锋部队的增援。', `FemaleText_loc5`='我需要截斷曦刃的增援部隊。', `FemaleText_loc7`='Tengo que interceptar a los refuerzos Hojalba.' WHERE `ID`=24152;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천둥부름호에 탑승한 걸 환영하네!$b$b폭발이라던가 그 비슷한 사건에 대해 불평하는 사람들은 무시하라고. 정말이야. 누구나 실수는 하는 거지. 서로에게 관대한 마음가짐을 가져야 한다고.$b$b이봐, 만약 어떤 비행선이 22번이나 23번쯤 추락했다면 그 선장은 욕을 먹을 수도 있지... 하지만 그보다 적은 수라면 별일 아니라고.', `MaleText_loc4`='欢迎登上唤雷号！$b$b不用理会那群整天抱怨爆炸或者类似东西的家伙。真的，每个人都会犯错误，我们应该开除掉一些懒惰的家伙。$b$b你看，我知道如果有一个船长的船坠毁了22还是23次是有点……但任何少于那个次数的事故就根本算不得什么了。', `MaleText_loc5`='歡迎登上喚雷者號!$b$b別在意那些對爆炸或類似事情有所埋怨的人們。我是說真的，每個人都有犯錯的時候。我們應該放過他們。$b$b瞧，我可以了解如果一位船長動不動就想把自己的船炸個22或23次的話...不過除此之外的事不值得一提。', `MaleText_loc7`='¡Te doy la bienvenida a bordo de El invocador del trueno!$B$BNo prestes atención a esa gente que se queja sobre explosiones y cosas así. Lo digo en serio, todo el mundo comete errores. Hay que tener un poco de confianza.$B$BMira, lo entendería si un capitán hubiera hundido su barco 22 o 23 veces... pero menos que eso no es digno de mención.' WHERE `ID`=24153;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<투덜투덜> 왜 아무것도 없는 데서 산이 마구 튀어나오는 걸까요... 다섯 번이나!', `MaleText_loc4`='<抱怨> 那些山都不知道从哪里钻出来的……五次都是突然出现！', `MaleText_loc5`='<咕噥著>我猜那些山是憑空出現的...總共5次!', `MaleText_loc7`='<Refunfuña> Creo que esas montañas han aparecido de la nada... ¡las cinco veces!' WHERE `ID`=24154;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<투덜투덜> 비행선이 바다에 추락하는 건 있을 수 없는 일이라고 생각하시겠지요. 네 번이나 그랬다면 더 믿어지지 않으실 테고요!', `MaleText_loc4`='<抱怨> 你可能会觉得让一艘飞艇撞进海里挺困难的，但是前后发生了四次就更不可思议了！', `MaleText_loc5`='<咕噥著>你一定認為將一艘飛艇墜落到海裡不簡單。你一定認為能摔上四次更困難吧!', `MaleText_loc7`='<Refunfuña> ¿Crees que estrellar un zepelín contra el océano es difícil? ¡Más difícil sería hacerlo 4 veces!' WHERE `ID`=24155;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<투덜투덜> 호수에 추락하는 사태까지 생긴 적은 없다고 말씀드릴 수 있다면 얼마나 좋을까요. 아니면 호수에 추락한 적은 한 번밖에 없다고 말씀드릴 수 있다면 얼마나 좋을까요... 하지만 사실 저희는 네 개의 서로 다른 호수에 추락한 적이 있답니다. 그중에 하나는 로다미어 호수라죠!', `MaleText_loc4`='<抱怨> 我真希望我们能设法避免坠入湖中。我真希望我们只坠入湖中一次……但实际上，我们先后坠入四面湖中，其中还包括洛丹米尔湖！', `MaleText_loc5`='<咕噥著>我多希望我可以說我們會努力避免墜落到湖裡。我多希望我可以說我們只墜落過湖裡一次...不過我們已經墜落過4個不同的湖了，包括洛丹米爾湖!', `MaleText_loc7`='<Refunfuña> Me gustaría poder decir que nunca nos hemos estrellado contra un lago. Me gustaría poder decir que solo nos hemos estrellado contra un lago una vez... ¡Pero nos hemos estrellado en 4 lagos diferentes, incluido el Lago Lordamere!' WHERE `ID`=24156;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희 비행선이 소나무 가지에 별로 상하지 않았다는 게 정말 놀랍군요.$b$b그렇다고 저희가 세 번이나 숲에 떨어진 적이 있다는 게 용서되는 건 아니지만요.', `MaleText_loc4`='很幸运，那些松树枝看上去并没有怎么伤到飞艇。$b$b不过那也不是我们三次坠毁在森林里的借口。', `MaleText_loc5`='我對於松樹枝似乎沒有對我們的船造成嚴重損害的事印象深刻。$b$b並不是因為這樣我們才會墜落在同一個森林裡三次。', `MaleText_loc7`='Me impresiona que las ramas de los pinos no dañen demasiado nuestra nave.$B$BClaro que eso no es excusa para las 3 veces que nos hemos estrellado contra un bosque.' WHERE `ID`=24157;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='텔드랏실을 보게 되리라고는 상상도 못 했어요... 아, 물론 텔드랏실에 추락한다는 상상도 못 해보긴 했죠.', `MaleText_loc4`='我从未想过我能看见泰达希尔……我也的确没想到我们会坠入泰达希尔。', `MaleText_loc5`='我從來沒想過我會親眼見到泰達希爾...我當然從來沒想到我們會墜落在泰達希爾。', `MaleText_loc7`='Jamás pensé que llegaría a ver Teldrassil... Y te juro que jamás pensé que nos estrellaríamos contra Teldrassil.' WHERE `ID`=24158;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 간신히 썬더 블러프를 두 번 지나갔을 뿐이란 말입니다!', `MaleText_loc4`='现在我们已经成功地穿越雷霆崖两次了！', `MaleText_loc5`='我們現在得設法穿越雷霆崖兩次!', `MaleText_loc7`='¡Hemos conseguido atravesar Cima del Trueno dos veces!' WHERE `ID`=24159;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<투덜투덜> 하나도 긁히지 않은 채 버섯구름 봉우리를 스리슬쩍 빠져나온 우리 배가, 어떻게 소금 평원에 추락해서 불타 버렸는지 아직도 모르겠단 말입니다.', `MaleText_loc4`='<抱怨> 我真不知道为什么我们能毫发无损地穿过千针石林的那一大堆石柱，最后却坠毁在闪光平原上！', `MaleText_loc5`='<咕噥著>我還是不知道我們是如何設法潛入通過千針石林還沒被發現，卻只是在閃光平原墜毀而已!', `MaleText_loc7`='<Refunfuña> ¡Aún no sé cómo hemos logrado atravesar Las Mil Agujas sin un arañazo, para acabar estrellándonos y ardiendo en El Desierto de Sal!' WHERE `ID`=24160;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='짜릿한 걸 좋아하신다면, 아무도 저희 선장님을 못 따라오죠! 전 이 일이 너무나 좋답니다!', `FemaleText_loc4`='如果你喜欢刺激，那可是我们船长最擅长的事了！我爱这份工作！', `FemaleText_loc5`='如果你喜歡刺激的話，我們的船長是箇中高手!我愛死這份工作了!', `FemaleText_loc7`='¡Si te gustan las emociones fuertes, nuestro Capitán es el mejor! ¡Adoro este trabajo!' WHERE `ID`=24161;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='묻지 말게...', `MaleText_loc4`='不要多问……', `MaleText_loc5`='不要問...', `MaleText_loc7`='No preguntes...' WHERE `ID`=24162;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리에게 생긴 그 재난 때문에 나더러 뭐라 하진 말라고... 어디로 가는지조차 볼 수 없었거든!$b$b하긴 어디로 가는지 보지 못했다고 나를 비난할 수도 있겠지만...$b$b안돼! 기다리라고! 난 이 배를 안전하게 댈 수 있단 말이야... 이건 선장님이 내리신 명령이 틀림없어! 아마 우리를 한계까지 밀어붙이고 어떻게 견뎌내는지, 어떻게 수리하는지 시험하고 싶은가봐.', `MaleText_loc4`='你不能把我们的坏运气都怪在我的头上吧……我甚至都不知道我要去哪！$b$b尽管也许那意思是说你能责怪我……$b$b不！等等！我能把这艘船完好的停进港口的……但那肯定是船长发出的命令！也许他喜欢挑战我们的极限来测试我们的生存能力还有修理技术。', `MaleText_loc5`='這件事故你不能怪我...我甚至連我要去哪都不知道!$b$b雖然也許那表示你可以責怪我...$b$b不!等等!我還可以將船停靠...這有可能是船長下的命令!也許他喜歡將我們逼到極限，然後測試我們生存及修理的能力。', `MaleText_loc7`='No puedes culparme por estos contratiempos... ¡Ni siquiera puedo ver por dónde vamos!$B$BAunque quizá eso signifique que sí puedes culparme...$B$B¡No! ¡Espera! Puedo atracar esta nave perfectamente... ¡Deben de ser las órdenes del Capitán! Quizá esté forzándonos al límite y examinando nuestra capacidad de supervivencia y reparación.' WHERE `ID`=24163;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘했어요, $n.', `FemaleText_loc4`='干得好，$n。', `FemaleText_loc5`='做得漂亮，$n。', `FemaleText_loc7`='Buen trabajo, $n.' WHERE `ID`=24164;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 가져오는 정화된 금속은 그 양이 얼마든지 다 쓸 수 있답니다. 당신이 가져올 수 있는 정화된 금속 양이 얼마나 되든지 다 쓸 수 있답니다.', `FemaleText_loc4`='你有多少净化过的金属，我就要多少。', `FemaleText_loc5`='所有你能提供的淨化後的金屬我都用得上。', `FemaleText_loc7`='Me vendrá bien todo el metal purificado que me puedas proporcionar.' WHERE `ID`=24165;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이대로 간다면 머지않아 우리 병사들에게 최고의 장비를 지급할 수 있을 거예요.', `FemaleText_loc4`='照这样下去，我们的人很快就会有最好的装备了。', `FemaleText_loc5`='照這個進度，很快所有的男女都能獲得最好的武裝。', `FemaleText_loc7`='A este paso, nuestros hombres y mujeres serán los mejor equipados en un abrir y cerrar de ojos.' WHERE `ID`=24166;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고마워요, $n!', `FemaleText_loc4`='谢谢你，$n！', `FemaleText_loc5`='感謝你，$n!', `FemaleText_loc7`='¡Gracias, $n!' WHERE `ID`=24167;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='두드리는 모습이 아주 그럴싸하네요. 혹시 대장장이인가요?', `FemaleText_loc4`='你干得太棒了。你是不是以前当过铁匠？', `FemaleText_loc5`='你的姿勢很棒。你該不會是個鐵匠吧?', `FemaleText_loc7`='Tu forma es excelente. ¿No serás herrero por casualidad?' WHERE `ID`=24168;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나가의 광석과 당신이 가져온 정화된 금속이라면 거의 무적인 합금을 만들 수 있어요.', `FemaleText_loc4`='有了纳迦的矿石和你提供的纯净金属，就可以铸造出一种几乎无懈可击的合金了。', `FemaleText_loc5`='配合上那些納迦礦石，還有你提供的淨化金屬可以造出近乎無敵的合金。', `FemaleText_loc7`='Junto con las menas de los naga, el metal purificado que nos suministras formará una aleación casi invulnerable.' WHERE `ID`=24169;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='계속되는 당신의 노력은 우리 공격대에 정말 큰 도움이 된답니다.', `FemaleText_loc4`='你在这里所做的工作对我们有着不可估量的作用。', `FemaleText_loc5`='你在這裡的努力對進攻部隊來說非常有價值。', `FemaleText_loc7`='Tu trabajo aquí es de gran valor para la ofensiva.' WHERE `ID`=24170;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='장비를 정화해 줘서 고마워요, $n. 할 일이 많아 시간이 정말 부족했거든요.', `FemaleText_loc4`='谢谢你帮我净化这些金属，$n。事情实在太多了，我根本没时间去做。', `FemaleText_loc5`='謝謝你親手淨化那些武裝，$n。我實在有太多事情得做，沒有時間處理這些。', `FemaleText_loc7`='Gracias por purificar el armamento tu mismo, $n. Tengo mucho que hacer y muy poco tiempo.' WHERE `ID`=24171;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마을 전체에서 비밀리에 투표가 붙여져 이름을 바꾸기 전까지 저는 이올롤이라고 알려졌던 사람이었습니다. 그 투표 결과는 이름을 바꾸던가 코르키와 같은 길을 가던가 하라는 거였지요. 당신도 이름을 바꾸는 쪽을 선택했을 것입니다. 새로 바꾼 제 이름 어떻습니까? 엄청나게 좋아졌다 생각 안하십니까?$B$B어쨌거나, 일거리를 찾고 있다면 게시판을 확인해보십시오.', `MaleText_loc4`='我的名字曾经是埃欧罗，这是我的故事：有一天，村子里进行了一场秘密的投票，最终那次投票导致我改变了自己的名字。他们让我选择是改名字还是像考尔奇一样。要是你的话，你也会这么做的吧。你觉得我的新名字怎么样？有很大的改进，对吧？$b$b对了，如果你在找活干的话，去布告栏那里看看吧。', `MaleText_loc5`='我本來叫做洛羅，直到全鎮秘密的投票將我的名字給改了。我只能接受他們替我取的新名字，不然就得叫做柯爾奇。如果換作是你也會和我的選擇一樣吧。你覺得我的新名字如何呢?好聽多了，對嗎?$B$B對了，假如你想找工作的話可以去看看佈告欄。', `MaleText_loc7`='Solían llamarme Iolol hasta que se hizo una votación secreta en la ciudad que dio como resultado que tuviera que cambiarme el nombre. Era eso o seguir los pasos de Corki. Tú habrías hecho lo mismo. ¿Qué te parece mi nuevo nombre? Un gran avance, ¿verdad?$B$BPor cierto, mira el tablón de anuncios si buscas trabajo.' WHERE `ID`=24172;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서쪽에서 용매가 날아온다! 저 $c|1을;를; 떨어트려!', `MaleText_loc4`='西边出现龙鹰！把那个$c打下来！', `MaleText_loc5`='龍鷹從西邊過來了!把那個$c給射下來!', `MaleText_loc7`='¡Dracohalcón acercándose por el Oeste! ¡Derribad a $Gese:esa:c; $c!' WHERE `ID`=24173;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용매가 들어오게 해서는 안 돼! 사격 개시!', `MaleText_loc4`='不要让那龙鹰通过这里！开火！', `MaleText_loc5`='別讓那隻龍鷹通過!開火!', `MaleText_loc7`='¡No dejéis que pase ese dracohalcón! ¡Abrid fuego!' WHERE `ID`=24174;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무너진 태양 공격대 녀석들이다! 발사!', `MaleText_loc4`='破碎残阳的垃圾！随意开火！', `MaleText_loc5`='該死的破碎之日人渣!自由開火!', `MaleText_loc7`='¡Basura del Sol Devastado! ¡Fuego a discreción!' WHERE `ID`=24175;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뒤는 걱정 말라고, $n!', `MaleText_loc4`='我们掩护你，$n！', `MaleText_loc5`='我們掩護你，$n!', `MaleText_loc7`='¡Te cubrimos, $n!', `FemaleText_loc1`='뒤는 걱정 말라고, $n!', `FemaleText_loc4`='我们掩护你，$n！', `FemaleText_loc5`='我們掩護你，$n!', `FemaleText_loc7`='¡Te cubrimos, $n!' WHERE `ID`=24176;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상공으로 올라가서 공격하십시오. $n|1을;를; 엄호하자!', `MaleText_loc4`='爬升！从上方进攻！让我们想办法给$n提供一些掩护。', `MaleText_loc5`='往上去，從上頭攻擊他們。幫$n爭取一點掩護。', `MaleText_loc7`='Moveos y disparadles desde arriba. Intentemos cubrir a $n.', `FemaleText_loc1`='상공으로 올라가서 공격하세요. $n|1을;를; 엄호하자!', `FemaleText_loc4`='爬升！从上方进攻！让我们想办法给$n提供一些掩护。', `FemaleText_loc5`='往上去，從上頭攻擊他們。幫$n爭取一點掩護。', `FemaleText_loc7`='Moveos y disparadles desde arriba. Intentemos cubrir a $n.' WHERE `ID`=24177;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한바탕 놀아보자고! 화끈하게, 번개같이 날려버리자!', `MaleText_loc4`='表演时间到了！炸得再狠点，再快点！', `MaleText_loc5`='精采的來啦!猛力開火!再快一點!', `MaleText_loc7`='¡Es la hora del espectáculo! ¡Arremeted contra ellos fuerte, arremeted contra ellos rápido!', `FemaleText_loc1`='한바탕 놀아보자고! 화끈하게, 번개같이 날려버려!', `FemaleText_loc4`='表演时间到了！炸得再狠点，再快点！', `FemaleText_loc5`='精采的來啦!猛力開火!再快一點!', `FemaleText_loc7`='¡Es la hora del espectáculo! ¡Arremeted contra ellos fuerte, arremeted contra ellos rápido!' WHERE `ID`=24178;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 도와드릴까요? 혹시 애완용 돼지를 찾으십니까?', `MaleText_loc4`='有什么我能帮你的吗？也许你在找一头宠物猪吧？', `MaleText_loc5`='有什麼我可以幫忙你的嗎?像是，找一隻寵物豬?', `MaleText_loc7`='¿Puedo ayudarte en algo? ¿Quizá buscas un cerdo mascota?' WHERE `ID`=24179;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황금돼지', `MaleText_loc4`='金猪', `MaleText_loc5`='金豬', `MaleText_loc7`='Cerdo de oro', `FemaleText_loc1`='황금돼지', `FemaleText_loc4`='金猪', `FemaleText_loc5`='金豬', `FemaleText_loc7`='Cerdo de oro' WHERE `ID`=24180;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은돼지', `MaleText_loc4`='银猪', `MaleText_loc5`='銀豬', `MaleText_loc7`='Cerdo de plata', `FemaleText_loc1`='은돼지', `FemaleText_loc4`='银猪', `FemaleText_loc5`='銀豬', `FemaleText_loc7`='Cerdo de plata' WHERE `ID`=24181;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진형을 갖추십시오! 죽음의 흉터에 다 왔습니다.', `MaleText_loc4`='战斗阵形！死亡之痕就在前面！', `MaleText_loc5`='維持隊形!我們即將到達死亡之痕。', `MaleText_loc7`='¡Colocaos en formación! Nos acercamos a La Cicatriz Muerta.', `FemaleText_loc1`='진형을 갖추십시오! 죽음의 흉터에 다 왔습니다.', `FemaleText_loc4`='战斗阵形！死亡之痕就在前面！', `FemaleText_loc5`='維持隊形!我們即將到達死亡之痕。', `FemaleText_loc7`='¡Colocaos en formación! Nos acercamos a La Cicatriz Muerta.' WHERE `ID`=24182;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 폭탄으로 빠르게 밀어붙여야 합니다. 악마 중에 어떤 녀석들은 정통으로 맞아도 쓰러지지 않으니까요.', `MaleText_loc4`='加快填弹速度。有些恶魔已经是风一吹就要倒了。', `MaleText_loc5`='轟炸的速度加快。有些惡魔需要一發以上的炸藥正面命中才能擊倒。', `MaleText_loc7`='Date prisa con esas cargas. Un solo tiro directo no va a ser suficiente para derribar a algunos de estos demonios.', `FemaleText_loc1`='그 폭탄으로 빠르게 밀어붙여야 합니다. 악마 중에 어떤 녀석들은 정통으로 맞아도 쓰러지지 않으니까요.', `FemaleText_loc4`='加快填弹速度。有些恶魔已经是风一吹就要倒了。', `FemaleText_loc5`='轟炸的速度加快。有些惡魔需要一發以上的炸藥正面命中才能擊倒。', `FemaleText_loc7`='Date prisa con esas cargas. Un solo tiro directo no va a ser suficiente para derribar a algunos de estos demonios.' WHERE `ID`=24183;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악마들한테서 눈을 떼지 마십시오. 오늘은 스컬지를 사냥하러 온 게 아닙니다.', `MaleText_loc4`='盯着恶魔。我们今天不是来消灭那些亡灵天灾的。', `MaleText_loc5`='瞄準那些惡魔。我們今天不是來消滅天譴軍團的。', `MaleText_loc7`='No perdáis de vista a los demonios. Hoy no nos preocupamos de matar a la Plaga.', `FemaleText_loc1`='악마들한테서 눈을 떼지 마십시오. 오늘은 스컬지를 사냥하러 온 게 아니니까요.', `FemaleText_loc4`='盯着恶魔。我们今天不是来消灭那些亡灵天灾的。', `FemaleText_loc5`='瞄準那些惡魔。我們今天不是來消滅天譴軍團的。', `FemaleText_loc7`='No perdáis de vista a los demonios. Hoy no nos preocupamos de matar a la Plaga.' WHERE `ID`=24184;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 냄새 나는 놈들을 무찔러라!', `MaleText_loc4`='碾碎这些讨厌的垃圾！', `MaleText_loc5`='粉碎這些臭死人的廢物!', `MaleText_loc7`='¡Aplastad estas apestosas cáscaras!' WHERE `ID`=24185;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들을 박살 내라! 갈아서 먼지로 만들어버려!', `MaleText_loc4`='粉碎他们！把他们的骨头碾进泥土里！', `MaleText_loc5`='打爛他們!把他們的骨頭磨成粉!', `MaleText_loc7`='¡Machacadlos! ¡Hundid sus huesos en el barro!' WHERE `ID`=24186;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='버텨라, 버러지들아! 주인님이 돌아오실 때까지 이 태양샘을 지켜야 한다!', `MaleText_loc4`='用力点，蝼蚁！我们必须在主人回归前保证太阳之井的安全！', `MaleText_loc5`='用力點，蛆蟲!我們一定把太陽之井清理乾淨，好等主人回來!', `MaleText_loc7`='¡Más duro, gusanos! ¡Hemos de mantener La Fuente del Sol limpia para el retorno del maestro!' WHERE `ID`=24187;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들을 불태워라! 갑옷을 부수고 상처를 입히란 말이다!', `MaleText_loc4`='烧死他们！把他们碎尸万段！', `MaleText_loc5`='燒毀他們的屍體，扯爛他們的皮，粉碎他們咯咯作響的外殼!', `MaleText_loc7`='¡Quemad sus cuerpos, arrancadles la piel a tiras, aplastad sus chirriantes caparazones!' WHERE `ID`=24188;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 어떤 공포도 내가 네 녀석 몸을 꿰뚫는 것보다 두렵지는 않을걸!', `MaleText_loc4`='这里没有什么能比我更让你感到恐怖的了！', `MaleText_loc5`='等我解決你，你就會知道你先前遇過的各種恐怖都只是小意思!', `MaleText_loc7`='¡Ningún horror es comparable a lo que te enfrentarás cuando haya acabado contigo!' WHERE `ID`=24189;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽거나 죽이거나! 그것이 불타는 군단의 방식이다!', `MaleText_loc4`='要么胜利要么死亡！这就是军团的行事风格！', `MaleText_loc5`='戰勝或是被擊倒!這就是燃燒軍團的準則!', `MaleText_loc7`='¡Machaca o sé machacado! ¡Así son las cosas con la Legión!' WHERE `ID`=24190;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽거나 죽이거나! 그것이 불타는 군단의 방식이다!', `MaleText_loc4`='要么胜利要么死亡！这就是军团的行事风格！', `MaleText_loc5`='戰勝或是被擊倒!這就是燃燒軍團的準則!', `MaleText_loc7`='¡Machaca o sé machacado! ¡Así son las cosas con la Legión!' WHERE `ID`=24191;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지옥의 군주라는 게 겨우 구더기의 새끼였구나, 브루탈루스!', `MaleText_loc4`='我听说深渊领主是蛆虫变成的，布鲁塔卢斯！', `MaleText_loc5`='我聽說深淵領主全都是蛆長出來的，布魯托魯斯!', `MaleText_loc7`='¡He oído que los señores del foso nacen de los gusanos, Brutallus!', `FemaleText_loc1`='지옥의 군주라는 게 겨우 구더기의 새끼였구나, 브루탈루스!', `FemaleText_loc4`='我听说深渊领主是蛆虫变成的，布鲁塔卢斯！', `FemaleText_loc5`='我聽說深淵領主全都是蛆長出來的，布魯托魯斯!', `FemaleText_loc7`='¡He oído que los señores del foso nacen de los gusanos, Brutallus!' WHERE `ID`=24192;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새파란 날짐승 주제에 입만 살았구나! 구더기와 상대가 되는지 어디 한 번 내려와 봐라!', `MaleText_loc4`='小蓝鸟又在说大话了！你不如下来看看能不能把我这条虫子从泥土里啄出来！', `MaleText_loc5`='小藍鳥你的口氣還真大!為什麼你不過來，看看你能不能把這隻蛆從爛泥裡挖出來!', `MaleText_loc7`='¡Demasiada palabrería para un pajarraco azul! ¿Por qué no bajas a ver si puedes sacar a este gusano de la mugre?' WHERE `ID`=24193;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주목!', `MaleText_loc4`='立正！', `MaleText_loc5`='注意!', `MaleText_loc7`='¡ATENCIÓN!' WHERE `ID`=24194;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑다, 신병 제군들. 난 훈련교관 바둠이다. 제군들은 앞으로 며칠간 교육을 받게 된다.', `MaleText_loc4`='新兵们，你们好。我是教官巴尔杜姆。在接下来的几天内，你们会接受我的训练。', `MaleText_loc5`='你好，新兵。我是訓練中士巴度恩。接下來幾天你將會接受一連串的適應與訓練。', `MaleText_loc7`='Hola nuevos reclutas. Soy el sargento de maniobras Bahduum. Durante los próximos días vais a recibir orientación.' WHERE `ID`=24195;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쿠엘다나스 섬은 캘타스 선스트라이더 왕자의 군대가 장악했다. 그가 죽었다는 정보가 입수된 바 있지만, 이 정보는 잘못된 것이다.', `MaleText_loc4`='凯尔萨斯·逐日者王子的军队占领了奎尔丹纳斯岛。先前的情报表明他已经死了，但情报错了。', `MaleText_loc5`='奎爾達納斯之島充斥著凱爾薩斯·逐日者王子的部隊。情報先前認定他已經死了，但情報單位錯了。', `MaleText_loc7`='La Isla de Quel''Danas ha sido invadida por las fuerzas del príncipe Kael''thas Caminante del Sol. El servicio de inteligencia lo tenía clasificado como fallecido. El servicio de inteligencia estaba equivocado.' WHERE `ID`=24196;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 고원에서 그자와 그의 악마들이 태양샘을 가동시켜 그자들의 우두머리인 킬제덴을 다시 이 세계로 불러올 균열을 만들려고 한다.', `MaleText_loc4`='他和他的恶魔同伴们正在高地上设法重新点燃太阳井，打开一道裂缝，把他们的首领基尔加丹重新召唤回这个世界。', `MaleText_loc5`='在高地之上，他和他的惡魔夥伴正打算要重新點燃太陽之井並且打開一道裂隙讓他們的老大基爾加丹進入這個世界。', `MaleText_loc7`='En la meseta, él y sus demoniacos amigos están intentando volver a poner La Fuente del Sol en funcionamiento y abrir una brecha para traer a su jefe, Kil''jaeden, de vuelta al mundo.' WHERE `ID`=24197;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 임무는 놈의 총알받이를 최대한 많이 없애면서 우리 지도자들이 모셔온 전문가들을 지원하는 것이다.', `MaleText_loc4`='我们的任务是在支援上头派来的特种部队的同时，尽可能多的消灭凯尔萨斯的手下。', `MaleText_loc5`='我們的任務就是一面支援高層指派的專家，同時盡可能地把對方的雜碎掃蕩乾淨。', `MaleText_loc7`='Nuestro trabajo es limpiar la mayor parte posible de este forraje, mientras apoyamos a los especialistas que han traído los jefazos.' WHERE `ID`=24198;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말할 것도 없겠지만, 제군들이 살아서 돌아갈 확률은 매우 낮다. 하지만 배운 걸 기억하고 그대로만 한다면 그 확률은 얼마든지 높일 수 있다.', `MaleText_loc4`='不用说也知道，我们中的很多人将一去不复返。但你们只需要牢记训练的内容，时刻保持警惕，就可以大大提高生还的机率。', `MaleText_loc5`='不用說，我們其中很多人恐怕再也回不了家。但如果你牢記你的訓練，並且隨時提高警覺，你就可以大大提高自己的存活機率。', `MaleText_loc7`='No hace falta que nos digas que muchos de nosotros no regresaremos a casa, pero si recuerdas el entrenamiento y te mantienes alerta aumentarás tus posibilidades.' WHERE `ID`=24199;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이상이다. 정신 똑바로 차려라, 제군들.', `MaleText_loc4`='我要说的就这些了。认真点，孩子们。', `MaleText_loc5`='我現在只能說。集中注意力，孩子們。', `MaleText_loc7`='Eso es todo lo que tengo que decir por ahora. Manteneos centrados chicos y chicas.' WHERE `ID`=24200;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황금돼지', `MaleText_loc4`='金猪', `MaleText_loc5`='金豬', `MaleText_loc7`='Cerdo de oro', `FemaleText_loc1`='황금돼지', `FemaleText_loc4`='金猪', `FemaleText_loc5`='金豬', `FemaleText_loc7`='Cerdo de oro' WHERE `ID`=24201;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은돼지', `MaleText_loc4`='银猪', `MaleText_loc5`='銀豬', `MaleText_loc7`='Cerdo de plata', `FemaleText_loc1`='은돼지', `FemaleText_loc4`='银猪', `FemaleText_loc5`='銀豬', `FemaleText_loc7`='Cerdo de plata' WHERE `ID`=24202;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내려와라! 네놈의 날개를 찢어 거름으로 만들어 주마! 그러면 용족이랍시고 뻐기는 네놈도 구더기 신세가 되겠지!', `MaleText_loc4`='有种就下来啊！我会撕下你的翅膀，把你的尸首埋在泥土里。咱们看看谁会变成土里的蛆虫，你这条没用的龙！', `MaleText_loc5`='滾下來!我要把你的雙翼從肩膀撕裂，把你的嘴埋進泥裡。然後你只配當蛆，飛龍!', `MaleText_loc7`='¡Baja aquí! Te arrancaré las alas de los hombros y te entregaré como alimento para la mugre. ¡Y entonces TÚ serás el gusano, dragón!' WHERE `ID`=24203;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 차가운 음식을 좋아하지!', `MaleText_loc4`='我喜欢冷一点的食物！', `MaleText_loc5`='我喜歡我的餐點更涼一點!', `MaleText_loc7`='¡Me gusta la comida un poco más fría!', `FemaleText_loc1`='난 차가운 음식을 좋아하지!', `FemaleText_loc4`='我喜欢冷一点的食物！', `FemaleText_loc5`='我喜歡我的餐點更涼一點!', `FemaleText_loc7`='¡Me gusta la comida un poco más fría!' WHERE `ID`=24204;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크아아아! 날 고드름으로 만들 셈이냐! 내려와라! 진짜 뜨겁다는 게 어떤 건지 가르쳐 주마!', `MaleText_loc4`='啊哈哈哈哈！你想把我冻起来吗？下来啊，我会给你的生命添加一些真正的热量。', `MaleText_loc5`='嘎啊啊啊!你以為能把我變成冰柱嗎?有種就下來這裡，我會在你的人生中留下無法抹滅的火焰。', `MaleText_loc7`='¡Grraaarrr! ¿Crees que puedes convertirme en un carámbano? Baja aquí y pondré un poco de fuego en tu vida.' WHERE `ID`=24205;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기껏 이거란 말인가? 네 친구 스물네 놈쯤 더 불러와서 다시 덤비지 그러나, $r!', `MaleText_loc4`='这是什么可怜的魔法？你不如带上二十四个最棒的伙伴再回来试一次，怎么样？', `MaleText_loc5`='這是什麼可悲的魔法?我看你還是重新尋找24位好朋友然後再來一次吧，$r!', `MaleText_loc7`='¿Qué es esta patética magia? ¿Qué tal si vuelves con veinticuatro de tus mejores amigos y lo vuelves a intentar, $r?' WHERE `ID`=24206;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련교관님, 지금 막 남쪽에서 도착했습니다. 명령을 내려 주십시오!', `MaleText_loc4`='长官，我们已经从南面进入了。有何指示？', `MaleText_loc5`='報告長官，我們剛從南方飛抵這裡。您有何命令?', `MaleText_loc7`='Señor, acabamos de volar desde el Sur. ¿Cuáles son sus órdenes?', `FemaleText_loc1`='훈련교관님, 지금 막 남쪽에서 도착했습니다. 명령을 내려 주시기 바랍니다!', `FemaleText_loc4`='长官，我们已经从南面进入了。有何指示？', `FemaleText_loc5`='報告長官，我們剛從南方飛抵這裡。您有何命令?', `FemaleText_loc7`='Señor, acabamos de volar desde el Sur. ¿Cuáles son sus órdenes?' WHERE `ID`=24207;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예, 알겠습니다!', `MaleText_loc4`='遵命，长官！', `MaleText_loc5`='遵命!', `MaleText_loc7`='¡Sí, señor!', `FemaleText_loc1`='예, 알겠습니다!', `FemaleText_loc4`='遵命，长官！', `FemaleText_loc5`='遵命!', `FemaleText_loc7`='¡Sí, señor!' WHERE `ID`=24208;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아. 분대원들과 함께 위치로 돌아가라. 해야 할 일이 있다.', `MaleText_loc4`='非常好，让你的小队列好阵型。还有工作要做。', `MaleText_loc5`='非常好。到你所屬的部隊裡排好隊形吧。我們有正事要辦。', `MaleText_loc7`='Muy bien. Colócate en formación con el resto de tu escuadrón. Hay trabajo que hacer.' WHERE `ID`=24209;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알았다. 조용히 하도록. 제군들, 지금 우리에겐 할 일은 많지만 시간은 없다.', `MaleText_loc4`='好吧，安静。我们有很多事需要做，但时间只有那么一点。', `MaleText_loc5`='好，冷靜點。我們有太多事情得做，時間卻太少。', `MaleText_loc7`='Bien, callaos. Tenemos mucho que hacer y muy poco tiempo.' WHERE `ID`=24210;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 드레나이들 중 일부는 스케티스에서 또 일부는 어둠달 골짜기에서 만났던 것 같군. 하지만 지금 이곳은 아제로스고 상황이 좋지 않다.', `MaleText_loc4`='我曾经和一些德莱尼人在斯克提斯并肩作战，也曾经和另一些德莱尼人在影月谷对抗伊利丹。然而现在，我们是在艾泽拉斯，这里的情况看上去很艰险。', `MaleText_loc5`='我曾經和某些德萊尼在司凱堤斯與影月谷並肩。但現在我們身在艾澤拉斯，而情勢看來更加險惡。', `MaleText_loc7`='Draenei, he estado con algunos de ustedes antes en Skettis y con otros en el Valle Sombraluna. Pero ahora estamos en Azeroth y la situación parece complicada.' WHERE `ID`=24211;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우선 신도레이들은 잘 들어라. 나는 무엇보다도 기강을 중시한다. 점술가 길드와 있을 때와는 전혀 분위기가 다를 것이야. 그러니 전력을 기울이든가 아니면 당장 배로 돌아가라!', `MaleText_loc4`='首先，我要告诉你们这些辛多雷，我的要求很严格……这和占星者们的行事方式并不一样。要么给我打起精神，要么就给我滚回去！', `MaleText_loc5`='首先，你們這些辛多雷聽著。我指揮一艘嚴格的船艦...這可跟你們習慣的占卜者船艦不同。要嘛全力以赴，不然就給我滾回去!', `MaleText_loc7`='Pero primero, escuchad sin''dorei. Yo dirijo esto muy estrictamente... esto no va a ser como cuando estabais con los Arúspices. ¡Arrimad el hombro o volved al bote!' WHERE `ID`=24212;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 주사위는 던져졌다. 쿠엘다나스 섬에 온 것을 환영한다. 태양샘은 남쪽 고원에 있고, 캘타스 왕자는 동쪽에 있는 마법학자의 정원에 숨어 있다.', `MaleText_loc4`='既然没人有异议，欢迎来到奎尔丹纳斯岛。太阳之井就在南边的高地上，而凯尔萨斯王子则躲藏在东面的魔导师平台里。', `MaleText_loc5`='現在快滾過來吧，歡迎來到奎爾達納斯之島。太陽之井就在南方的高地上，而凱爾薩斯王子所佔據的博學者殿堂則在東邊。', `MaleText_loc7`='Ahora que nos hemos quitado eso de en medio, bienvenidos a la Isla de Quel''Danas. La Fuente del Sol se encuentra en la meseta al Sur y el príncipe Kael’thas está en el Bancal del Magister al Este.' WHERE `ID`=24213;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위에서 불러들인 ''모험가''라는 자들을 지원하는 일이 우리가 이곳에서 맡은 임무다. 우리는 그들이 섬 곳곳의 요충지를 방어하는 일을 돕고, 맡은 임무를 수행할 수 있도록 그들을 보호해야 한다.', `MaleText_loc4`='我们是来这里支援那些高级军官召集来的所谓“冒险者”的。我们会帮助他们守卫岛上的关键位置，让他们远离战火，这样他们就能安心去做他们的事情了。', `MaleText_loc5`='我們是來這邊協助那些厚顏自稱『冒險者』的傢伙們。我們會幫他們守住島上的關鍵地點，並且讓他們遠離衝突，好讓他們可以正常工作。', `MaleText_loc7`='Estamos aquí como apoyo para los denominados “aventureros” que el jefazo ha llamado. Les ayudaremos a defender los puntos clave de la isla y contrarrestaremos los ataques para que puedan hacer su trabajo.' WHERE `ID`=24214;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='질문 있나? 없다면 자세한 지시와 명령은 각자의 분대장에게서 받도록 해라. 이상이다. 건투를 빈다!', `MaleText_loc4`='你们可以从小队指挥官那里得到更进一步的分配和指示。如果没有什么其他问题，就这样，好运！', `MaleText_loc5`='如果女士們沒有任何問題，你們將可以從小組長那邊取得進一步的指示與協助。以上。祝好運!', `MaleText_loc7`='Si ninguna de ustedes señoritas, tiene preguntas, podrán obtener más instrucciones y tareas de sus líderes de escuadrón.' WHERE `ID`=24215;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='태양샘에 온 것을 환영한다. 날씨도 따뜻하고 경치도 훌륭하지만, 제군들은 이곳에 휴가를 온 것이 아니다!', `MaleText_loc4`='欢迎来到太阳之井。尽管这里气候宜人，景色秀丽，但女士们先生们，你们不是来这里度假的！', `MaleText_loc5`='歡迎來到太陽之井。儘管溫度適中且風景優美，不過各位先生小姐們，你們可不是來渡假的!', `MaleText_loc7`='Bienvenidos a La Fuente del Sol, señores y señoras. ¡A pesar de las agradables temperaturas y las pintorescas vistas, no estáis de vacaciones!' WHERE `ID`=24216;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='현재 상황은 이렇다. 경험 많고 더 좋은 장비를 갖춘 병력이 캘타스 왕자를 향해 진격하는 동안, 우리는 온 힘을 기울여 방어하고 있다.', `MaleText_loc4`='现在的情况是这样：在那些更有经验、并且装备精良的伙计们对付凯尔萨斯王子时，我们正在努力保护我们所能保护的一切。', `MaleText_loc5`='目前的情況看來是:我們盡力固守，而那些較有經驗和裝備較好的人則去對付凱爾薩斯王子。', `MaleText_loc7`='La situación actual es la siguiente: nosotros resistimos en la medida de lo posible, mientras que aquellos con más experiencia y mejor equipo atacan al príncipe Kael''thas.' WHERE `ID`=24217;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇다. 우리는 그자가 죽었다고 알고 있었지만 실상은 그렇지 않다. 그자는 태양샘을 통해 불타는 군단의 우두머리, 킬제덴을 이 세상으로 불러들이려 한다.', `MaleText_loc4`='我知道，我们也以为他已经死了，不过事实并非如此。他正设法用太阳之井将燃烧军团的主子——基尔加丹带到这个世界来。', `MaleText_loc5`='我知道，我們也認為他死了，但這不是關鍵。他試圖利用太陽之井將燃燒軍團的主人，基爾加丹，帶入這個世界。', `MaleText_loc7`='Lo sé, nosotros también creíamos que estaba muerto, pero no es el caso. Está intentando usar La Fuente del Sol para traer al señor de la Legión Ardiente, Kil''jaeden, a este mundo.' WHERE `ID`=24218;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 한 번 말하지만, 그자가 성공한다면 이 세상은 아웃랜드에서 지금껏 일어났던 일보다 훨씬 험한 상황에 부닥칠 거다. 그러니 무슨 수를 써서라도 이를 막아내야 한다.', `MaleText_loc4`='我跟你们打保票，如果他成功了，这个世界将会遭受比外域更严重的灾难！所以，我们必须保证这一切不会发生。', `MaleText_loc5`='讓我向你們保證，如果他真的成功，這個世界將會變得比外域更悲慘!讓我們確保這件事情不會實現。', `MaleText_loc7`='¡Dejad que os asegure que, si él tiene éxito, este mundo sufrirá mucho más de lo que sufrió Terrallende! Así que asegurémonos de que eso no pase.' WHERE `ID`=24219;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전사들은 요충지 방어 임무에 배치될 것이고, 사수들은 적의 공중병력을 막아내는 임무를 맡을 것이다.', `MaleText_loc4`='在猎人们被指派狙击敌方飞行员的同时，战士们也将被分配前往关键地区进行防御。', `MaleText_loc5`='戰士會部屬來防守關鍵位置，你的射手則要協助阻止對方的飛行部隊靠近。', `MaleText_loc7`='Los guerreros se desplegarán para controlar posiciones clave, mientras que a tus tiradores se les asignará mantener a los aviadores enemigos a raya.' WHERE `ID`=24220;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 제군들에게 줄 특별 임무에 대한 명령을 기다리는 중이다. 그때까지 언제든지 이동할 수 있는 상태를 갖추고 여기서 대기해라!', `MaleText_loc4`='我正在等待着给你们指派特殊任务的命令。在此期间，请待在这里随时准备出发！', `MaleText_loc5`='我等著你的指派。並且待在這裡，做好準備等待關鍵的一刻!', `MaleText_loc7`='Estoy esperando las órdenes sobre tus misiones específicas. Mientras tanto, quédate por aquí y prepárate para actuar en cualquier momento.' WHERE `ID`=24221;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='태양너울 무기고 공략은 어떤 상황입니까?', `MaleText_loc4`='占领阳湾军械库的战斗有什么新消息吗？', `MaleText_loc5`='日境軍械庫的戰鬥有什麼消息嗎?', `MaleText_loc7`='¿Se sabe algo de la batalla para tomar el Arsenal de Tramo del Sol?', `FemaleText_loc1`='태양너울 무기고 공략은 어떤 상황입니까?', `FemaleText_loc4`='占领阳湾军械库的战斗有什么新消息吗？', `FemaleText_loc5`='日境軍械庫的戰鬥有什麼消息嗎?', `FemaleText_loc7`='¿Se sabe algo de la batalla para tomar el Arsenal de Tramo del Sol?' WHERE `ID`=24222;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물어봐 줘서 고맙군요. 무기고 공략은 현재 $3233w 퍼센트까지 진행됐습니다.$B$B전투마법사 아린나와 선구자 이누로가 당신의 도움을 바라니 쿠엘다나스 섬에 있는 태양너울 성소에서 그들을 찾아보세요.', `MaleText_loc4`='很高兴你问起这个，我们占领军械库的计划已经实施了百分之$3233w。$B$B我知道战斗法师艾尔娜和先驱者伊努罗需要你的帮助。去奎尔丹纳斯岛上的阳湾圣殿找他们谈谈吧。', `MaleText_loc5`='我很高興你問了。我們完成了計畫的$3233w％。$B$B我知道戰鬥法師艾里娜和先驅者因努羅需要你的幫忙。你可以在奎爾達納斯之島的日境聖所找到他們。', `MaleText_loc7`='Me alegra que me lo preguntes. Nuestros esfuerzos por tomar el arsenal están al $3233w % de lo planeado.$B$BSé que la maga de batalla Arynna y el presagista Inuuro necesitan tu ayuda. Búscalos dentro del Sagrario de Tramo del Sol, en la Isla de Quel''Danas.' WHERE `ID`=24223;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='태양너울 무기고에 있는 모루와 가열로가 완성되려면 얼마나 남았습니까?', `MaleText_loc4`='我们还要多久才能完成阳湾军械库的铁砧和熔炉？', `MaleText_loc5`='我們還要多久才能完成日境軍械庫的鐵砧與熔爐?', `MaleText_loc7`='¿Cuánto nos queda para completar el yunque y la forja en el Arsenal de Tramo del Sol?', `FemaleText_loc1`='태양너울 무기고에 있는 모루와 가열로가 완성되려면 얼마나 남았습니까?', `FemaleText_loc4`='我们还要多久才能完成阳湾军械库的铁砧和熔炉？', `FemaleText_loc5`='我們還要多久才能完成日境軍械庫的鐵砧與熔爐?', `FemaleText_loc7`='¿Cuánto nos queda para completar el yunque y la forja en el Arsenal de Tramo del Sol?' WHERE `ID`=24224;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하우타에게 들었을 때는 대략 $3228w 퍼센트 정도 완성됐다고 하더군요.$B$B그걸 완성하는 게 얼마나 중요한지는 두말할 필요도 없겠지요. 앞으로 더 좋은 갑옷과 무기가 필요할 테니 말입니다. 그러려면 모루와 가열로는 반드시 필요한 도구랍니다.$B$B태양너울 무기고 뒤쪽에 가 보면 그 대장장이 친구를 만날 수 있을 겁니다, $n.', `MaleText_loc4`='上次我从霍尔萨那里听说我们已经完成了百分之$3228w。$B$B我不知道该怎么形容这些设施对我们来说有多么重要。我们的人民需要更好的武器和装备，而铁砧和熔炉则是这一切的关键所在。$B$B铁匠铺就在阳湾军械库的后面，$n。', `MaleText_loc5`='我從荷莎那邊聽來，她說我們才完成了目標的$3228w％。$B$B我無法說明完成這些對我們的計畫來說有多重要。我們的男女戰士都需要更好的鎧甲與武器，而鐵砧與熔爐是關鍵。$B$B你將會在日境軍械庫找到鐵匠，$n。', `MaleText_loc7`='Las últimas noticias que tuve de Hauthaa indicaban que estábamos al $3228w %.$B$BNo puedo expresar lo necesario que es para nuestros esfuerzos que los creemos. Nuestros hombres y mujeres van a necesitar mejores armaduras y armas, y el yunque y la forja son la clave para ello.$B$BEncontrarás a la herrera detrás del Arsenal de Tramo del Sol, $n.' WHERE `ID`=24225;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 질문이 있습니다.', `MaleText_loc4`='我还有其他事想问你。', `MaleText_loc5`='我有些別的事情要詢問你。', `MaleText_loc7`='Tengo que preguntarte sobre algo más.', `FemaleText_loc1`='다른 질문이 있어요.', `FemaleText_loc4`='我还有其他事想问你。', `FemaleText_loc5`='我有些別的事情要詢問你。', `FemaleText_loc7`='Tengo que preguntarte sobre algo más.' WHERE `ID`=24226;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='총독님, 태양너울 항구는 성공적으로 점령했습니까?', `MaleText_loc4`='主教，我们有没有拿下阳湾港口？', `MaleText_loc5`='主教，我們拿下日境港了嗎?', `MaleText_loc7`='Exarca, ¿hemos tomado ya el Puerto de Tramo del Sol?', `FemaleText_loc1`='총독님, 태양너울 항구는 성공적으로 점령했나요?', `FemaleText_loc4`='主教，我们有没有拿下阳湾港口？', `FemaleText_loc5`='主教，我們拿下日境港了嗎?', `FemaleText_loc7`='Exarca, ¿hemos tomado ya el Puerto de Tramo del Sol?' WHERE `ID`=24227;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아쉽게도 아직 점령하지 못했답니다. 하지만 보고에 따르면 현재 $3238w 퍼센트 정도 진행되었다고 하더군요.$B$B혹시 도울 생각이 있다면 쿠엘다나스 섬의 태양너울 무기고에서 마법학자 일라스타나 구원자 카알란을 만나 보십시오.', `MaleText_loc4`='真不幸，我们还没有拿下港口，不过报告说我们的进程已经达到了百分之$3238w。$B$B$n，如果你想帮忙的话，去奎尔丹纳斯岛的阳湾军械库找魔导师伊拉斯塔和守备官凯兰谈谈吧。', `MaleText_loc5`='不，很不幸地我們還沒拿下港口。然而，報告顯示我們已經完成了$3238w％的目標。$B$B$n，如果你想要幫忙，可以去找奎爾達納斯之島上日境軍械庫的博學者伊拉斯塔和復仇者卡藍。', `MaleText_loc7`='No, por desgracia aún no hemos tomado el puerto. Sin embargo, los informes indican que estamos al $3238w %.$B$B$n, si quieres ayudar busca al magister Ilastar y al vindicador Kaalan en el Arsenal de Tramo del Sol, en la Isla de Quel''Danas.' WHERE `ID`=24228;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나순 님, 태양너울 항구에 연금술 실험대가 완성되려면 얼마나 걸릴지 아십니까?', `MaleText_loc4`='纳苏恩，你觉得我们还要多久才能在阳湾港口布置一个炼金台？', `MaleText_loc5`='納蘇安，你知道還要多久我們才能在日境港有一座鍊金實驗室?', `MaleText_loc7`='Nasuun, ¿sabes cuánto falta para que tengamos un laboratorio de alquimia en el Puerto de Tramo del Sol?', `FemaleText_loc1`='나순 님, 태양너울 항구에 연금술 실험대가 완성되려면 얼마나 걸릴지 아시나요?', `FemaleText_loc4`='纳苏恩，你觉得我们还要多久才能在阳湾港口布置一个炼金台？', `FemaleText_loc5`='納蘇安，你知道還要多久我們才能在日境港有一座鍊金實驗室?', `FemaleText_loc7`='Nasuun, ¿sabes cuánto falta para que tengamos un laboratorio de alquimia en el Puerto de Tramo del Sol?' WHERE `ID`=24229;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연금술 실험대가 완성되려면 조금 더 걸릴 겁니다, $n. 마르나의 말로는 현재 $3223w 퍼센트까지 조립을 완료했다고 하더군요.$B$B도울 생각이 있다면 태양너울 항구 여관 안에서 마르나를 찾아보십시오.', `MaleText_loc4`='炼金台还没完全准备好，$n。不过玛尔娜说她已经完成了$3223w%%。$B$B如果你想帮她一把的话，就去阳湾港口的旅店里找她吧。', `MaleText_loc5`='鍊金實驗室還沒準備好，$n。瑪納說她才準備了$3223w％，然而。$B$B如果你願意協助她的話，你可以在日境港的旅店中找到她。', `MaleText_loc7`='El laboratorio de alquimia aún no está preparado, $n. Pero Mar''nah dice que lo tiene montado al $3223w %.$B$BSi quieres ayudarle, la encontrarás dentro de la posada en el Puerto de Tramo del Sol.' WHERE `ID`=24230;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='태양샘 고원의 마법 장벽 해제 작업은 어떻게 되고 있습니까?', `MaleText_loc4`='摧毁太阳之井高地中的魔法屏障的进展如何了？', `MaleText_loc5`='關於被拆解的太陽之井高地魔法障壁你瞭解多少?', `MaleText_loc7`='¿Qué sabes acerca del derribo de las puertas mágicas en la Meseta de La Fuente del Sol?', `FemaleText_loc1`='태양샘 고원의 마법 장벽 해제 작업은 어떻게 되고 있나요?', `FemaleText_loc4`='摧毁太阳之井高地中的魔法屏障的进展如何了？', `FemaleText_loc5`='關於被拆解的太陽之井高地魔法障壁你瞭解多少?', `FemaleText_loc7`='¿Qué sabes acerca del derribo de las puertas mágicas en la Meseta de La Fuente del Sol?' WHERE `ID`=24231;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='첫 번째 관문인 아가마스를 돌파하려고 애쓰는 중입니다. $c|1이여;여;, 쿠엘다나스 섬으로 가서 어떻게든 저희를 도와주십시오!', `MaleText_loc4`='我们仍然在尝试摧毁第一道屏障阿加麦斯。拜托你了，$c，请立即前往奎尔丹纳斯岛，尽一切可能帮助我们！', `MaleText_loc5`='我們還在努力終結第一道障壁。拜託，$c，前往奎爾達納斯之島並盡量幫忙我們!', `MaleText_loc7`='Aún estamos intentando derribar Agamath, la primera puerta. ¡Por favor, $c, ve a la Isla de Quel''Danas y ayuda en lo que sea posible!' WHERE `ID`=24232;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='첫 번째 관문인 아가마스를 돌파했고 킬제덴의 두 부관인 여군주 사크로래쉬와 대흑마법사 알리테스를 처치해야 합니다.$B$B$c|1이여;여;, 당신의 친구들과 함께 가서 도와주십시오! 두 번째 관문인 로헨도르가 우리의 다음 과제입니다.', `MaleText_loc4`='第一道屏障阿加麦斯已经被摧毁了，基尔加丹的两个副官——萨洛拉丝女王和高阶术士奥蕾塞丝——必须接受正义的制裁。$B$B召集你的伙伴吧，$c，攻入太阳之井！第二道屏障洛希多尔是我们的下一个目标。', `MaleText_loc5`='初始之門， 阿格瑪司已經被破壞了，而基爾加丹的兩大副官，莎珂蕾希女士和大術士艾黎瑟絲，一定得被消滅。$B$B召集你的朋友們，$c，解決它!洛罕鐸，次之門是我們下一個目標。', `MaleText_loc7`='Hemos derribado la primera puerta, Agamath, y ahora tenemos que destruir a dos de las tenientes de Kil''jaeden, Lady Sacrolash y la bruja suprema Alythess.$B$BReúne a tus amigos, $c, y encargaros de ellas. Rohendor, la segunda puerta, es nuestro próximo objetivo.' WHERE `ID`=24233;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두 번째 관문인 로헨도르를 파괴했습니다만 태양샘 고원의 마지막 마법 장벽인 아르코니수스가 아직도 우리를 가로막고 있습니다, $n.$B$B할 수 있는 일을 다하여 태양샘에 지원하여 당신의 노력을 지지해 주십시오.', `MaleText_loc4`='第二道屏障洛希多尔已经被摧毁了，但是埃库尼苏——太阳之井高地最后的那道魔法屏障挡住了我们，$n。$B$B继续尽一切可能帮助我们吧。', `MaleText_loc5`='洛罕鐸，次之門已被終止，不過最後一道太陽之井高地的魔法屏障，亞坎努斯，還抵擋著我們，$n。$B$B盡全力繼續努力協助太陽之井。', `MaleText_loc7`='Rohendor, la segunda puerta, ha sido derribada, pero la última barrera mágica de la Meseta de La Fuente del Sol, Archonisus, se nos resiste, $n.$B$BContinúa con tus esfuerzos para ayudar a La Fuente del Sol como te sea posible.' WHERE `ID`=24234;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해냈어! 우리도 살아남고 배도 멀쩡하고! 그렇다고 손이 놀면 안 되지! 도착할 때까지 긴장을 늦추지 말라고!', `MaleText_loc4`='成功了！我们毫发无损地完成了这次航行！不过现在还不是偷懒的时候！加大马力，准备靠港！', `MaleText_loc5`='我們做到了!我們再一次連同船艦完好如初的活下來了!不過不能懈怠!努力推進，直到我們進入碼頭!', `MaleText_loc7`='¡Lo logramos! ¡Hemos sobrevivido a otro viaje con el barco intacto! ¡Pero eso no es motivo para relajarse! ¡Seguid presionando hasta que atraquemos!' WHERE `ID`=24235;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정박 준비!', `FemaleText_loc4`='准备靠港！', `FemaleText_loc5`='準備靠岸!', `FemaleText_loc7`='¡Prepárense para atracar!' WHERE `ID`=24236;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전속력으로 운항하라고, 코퍼볼트 군!', `MaleText_loc4`='考伯伯特先生，全速前进！', `MaleText_loc5`='全速前進，螺栓先生!', `MaleText_loc7`='¡A toda marcha, señor Perno de Cobre!' WHERE `ID`=24237;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빠르고 편안하게 운항하라고, 코퍼팬츠 군.', `MaleText_loc4`='赶快出发吧，考伯培特先生。', `MaleText_loc5`='銅褲先生，帶領我們舒適安穩的出發吧。', `MaleText_loc7`='¡Sáquenos de aquí suavemente y sin demora, señor Pantalones de Cobre!' WHERE `ID`=24238;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코퍼팟 군, 출발해도 좋네.', `MaleText_loc4`='考伯波特先生，可以出发了。', `MaleText_loc5`='銅罐先生，你可以帶領我們出發了。', `MaleText_loc7`='Señor Tarro de Cobre, puede sacarnos de aquí.' WHERE `ID`=24239;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코퍼탑 군... 속력을 내라고!', `MaleText_loc4`='考伯托特先生……快点！', `MaleText_loc5`='銅頂先生...用力打!', `MaleText_loc7`='Señor Tapa de cobre, ¡empújelo!' WHERE `ID`=24240;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='선장님, 제 이름은요... 오, 신경 쓰지 마세요...', `FemaleText_loc4`='先生，我的名字是……啊，算了……', `FemaleText_loc5`='先生，我的名字是...喔，算了...', `FemaleText_loc7`='Señor, me llamo... Oh, no importa...' WHERE `ID`=24241;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='페어웨더 항해사, 부디 최저 속도로 전진하시오!', `FemaleText_loc4`='菲尔维兹先生，请你稍微慢点！', `FemaleText_loc5`='費爾威德先生，抱歉請慢速前進!', `FemaleText_loc7`='¡Señor Buentiempo, reduzca avante, por favor!' WHERE `ID`=24242;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='선장님, 그건 그렇고요. 제 이름은 코퍼넛이라고요!', `FemaleText_loc4`='顺便说一声，我的名字是考伯纳特！', `FemaleText_loc5`='對了，先生，我的名字叫銅螺!', `FemaleText_loc7`='¡Por cierto, me llamo Tornillos de Cobre, Señor!' WHERE `ID`=24243;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='비슷하네요, 선장님...', `FemaleText_loc4`='先生，你差点就把我的名字叫对了……', `FemaleText_loc5`='結束，先生...', `FemaleText_loc7`='Casi, señor...' WHERE `ID`=24244;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='방금은 제 이름을 거의 제대로 부르셨어요, 선장님.', `FemaleText_loc4`='先生，你几乎快要把我的名字说对了。', `FemaleText_loc5`='你那時候差點唸對我的名字了，先生。', `FemaleText_loc7`='Esta vez casi acertó mi nombre, señor.' WHERE `ID`=24245;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='선장님, 최소한 제가 여자인지 남자인지는 알아주시죠...', `FemaleText_loc4`='先生，你至少得认清我的性别吧……', `FemaleText_loc5`='先生，如果你能至少弄對我的性別...', `FemaleText_loc7`='Señor, si al menos pudiera dirigirse a mí con el género correcto...' WHERE `ID`=24246;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='태양샘을 통해서 킬제덴이 되돌아온다면 우리는 지난 만 년 동안 겪어본 적이 없는 전쟁에 직면하게 될 거요!', `MaleText_loc4`='如果基尔加丹通过太阳之井进入这个世界，我们就将陷入一场一万年以来最残酷的战争。', `MaleText_loc5`='萬一基爾加丹覺醒，通過太陽之井進入我們的世界，他將會掀起一場大戰，就像在10,000年前那樣。', `MaleText_loc7`='Si Kil''jaeden atraviesa La Fuente del Sol, nuestro mundo se verá envuelto en una guerra sin precedentes en los últimos 10000 años.' WHERE `ID`=24247;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='첫 번째 관문 아가마스를 무너트리는 데 성공했습니다! 지금은 두 번째 관문인 로헨도르가 우리를 가로막고 있습니다.$B$B우리 마법사들이 로헨도르의 방어를 $3255w 퍼센트만큼 무너뜨린 상태입니다.', `MaleText_loc4`='第一道屏障，阿加麦斯，已经被摧毁了！现在第二道屏障洛希多尔挡住了我们前进的道路。$B$B我们的法师已经摧毁了洛希多尔百分之$3255w的防御屏障。', `MaleText_loc5`='初始之門， 阿格瑪司已經被攻破了!次之門洛罕鐸現在阻擋著我們的道路。$B$B我們的法師已經穿透了次之門，洛罕鐸$3255w％的防禦。', `MaleText_loc7`='¡La primera puerta, Agamath, ha sido derribada! Rohendor, la segunda puerta, bloquea nuestro paso ahora.$B$BNuestros magos han derribado el $3255w % de las defensas de la segunda puerta, Rohendor.', `FemaleText_loc1`='첫 번째 관문 아가마스를 무너트리는 데 성공했습니다! 지금은 두 번째 관문인 로헨도르가 우리를 가로막고 있어요.$B$B우리 마법사들이 로헨도르의 방어를 $3255w 퍼센트만큼 무너뜨린 상태랍니다.', `FemaleText_loc4`='第一道屏障，阿加麦斯，已经被摧毁了！现在第二道屏障洛希多尔挡住了我们前进的道路。$B$B我们的法师已经摧毁了洛希多尔百分之$3255w的防御屏障。', `FemaleText_loc5`='初始之門， 阿格瑪司已經被攻破了!次之門洛罕鐸現在阻擋著我們的道路。$B$B我們的法師已經穿透了次之門，洛罕鐸$3255w％的防禦。', `FemaleText_loc7`='¡La primera puerta, Agamath, ha sido derribada! Rohendor, la segunda puerta, bloquea nuestro paso ahora.$B$BNuestros magos han derribado el $3255w % de las defensas de la segunda puerta, Rohendor.' WHERE `ID`=24248;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마침내 로헨도르를 파괴했습니다. 이제 마지막 관문인 아르코니수스만 남았습니다.$B$B지금 우리 마법사들이 마지막 관문 아르코니수스의 방어를 $3257w 퍼센트만큼 돌파한 상황입니다.', `MaleText_loc4`='洛希多尔已经被摧毁，现在只剩下埃库尼苏了。$B$B我们的法师们已经摧毁了埃库尼苏百分之$3257w的防御屏障。', `MaleText_loc5`='洛罕鐸已經被瓦解了，只剩下亞坎努斯還存在。$B$B我們的法師已經穿透了終末之門，亞坎努斯$3257w％的防禦。', `MaleText_loc7`='Rohendor ha sido destruida. Ya solo falta la entrada, Archonisus.$B$BNuestros magos han derribado el $3257w % de las defensas de la puerta final, Archonisus.' WHERE `ID`=24249;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아르코니수스를 무너트렸지만... 아아... 너무 늦었군...$B$B킬제덴이 해방되다니! 이제는 그대와 같은 영웅들이 우리의 유일한 희망이오.', `MaleText_loc4`='埃库尼苏已经不复存在，但是，我们……太迟了……$B$B基尔加丹被释放了！我们唯一的希望只剩下这个世界的英雄们了！', `MaleText_loc5`='亞坎努斯已經蕩然無存了。唉，我們...我們太遲了...$b$b基爾加丹已經被降臨了!這個世界的英雄們是我們唯一的希望了。', `MaleText_loc7`='Archonisus ya no existe. ¡Ay de nosotros! Es... es demasiado tarde…$B$B¡Kil''jaeden ha sido liberado! Los héroes del mundo son nuestra única esperanza ahora.' WHERE `ID`=24250;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='퀵픽스!! 여기 아래 문제가 좀 생겼어!!', `MaleText_loc4`='奎菲克斯！！我们遇到麻烦了！', `MaleText_loc5`='速修!!下面出了問題!!', `MaleText_loc7`='¡Ayuda! ¡Tenemos un problema aquí abajo!' WHERE `ID`=24251;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 여행을 성공적으로 마쳤군! 탑에 가까이 대라고, 제군들!', `MaleText_loc4`='又一次成功的航行！伙计们，准备停靠在飞艇塔上！', `MaleText_loc5`='另一趟成功的旅程!來吧小夥子，讓我們低空飛過塔台吧!', `MaleText_loc7`='¡Otro exitoso viaje! ¡Vamos, chicos, volemos cerca de la torre!' WHERE `ID`=24252;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 여행 때 우리가 얼마나 운이 좋았는지 믿어지지가 않는다니까! 난 정말 세상에서 제일가는 창공의 선장이라고!', `MaleText_loc4`='真不敢相信，那次旅行实在是太幸运了！我是全世界最好的天空船长！', `MaleText_loc5`='我不敢相信我們那趟旅程有多幸運!我真的是所有國度中最棒的領空隊長!', `MaleText_loc7`='¡Me cuesta creer la suerte que tuvimos en ese viaje! ¡Realmente soy el mejor Capitán del cielo de todos los reinos!' WHERE `ID`=24253;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 안전하군! 하지만 속력이 너무 느렸어! 눈에 바람이 들어오는 게 느껴지도록 몰아라!', `MaleText_loc4`='我们安全了！但我们飞得还不够快！我想要的是那种风抚过脸庞的感觉！', `MaleText_loc5`='我們安全了!不過我們還不夠快!我只想要感覺眼中滿滿的風!', `MaleText_loc7`='¡Estamos a salvo! ¡Pero no íbamos suficientemente deprisa! ¡Solo quiero sentir el viento en mis ojos!' WHERE `ID`=24254;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='"강철의 독수리호"라. 흠. 이건 군용 항공기가 아니고 여객선이라고요! 하지만, 이봐요, 일은 일이잖아요? 월급만 제대로 준다면야 얼마든지 "봄블라스트" 선장님께 맞장구쳐 드리죠 뭐.$b$b어쨌든, 저희 비행선에 오신 걸 환영해요.', `FemaleText_loc4`='铁鹰号是客船，并不是战舰！好吧，对我来说这仅仅是一份工作。只要王子肯付工钱，我就顺从那个喜欢自吹自擂的船长。$b$b不管怎样，欢迎上船。', `FemaleText_loc5`='「鐵鷹。」嗯。它是艘客船，而非戰禽!不過嘿，工作就是工作，而我將迎合船長「浮誇」，既然好人都付錢了。$b$b無論如何，歡迎登船。', `FemaleText_loc7`='"El Águila de Hierro." Bah. ¡Es un barco de pasajeros, no una nave de guerra! Pero bueno, un trabajo es un trabajo y mientras el Príncipe siga pagando, tendré contento al capitán "Pretencioso”.$B$BDe todas formas, te doy la bienvenida a bordo.' WHERE `ID`=24255;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금은 좀 바쁜데요.', `MaleText_loc4`='有点忙。', `MaleText_loc5`='有點忙。', `MaleText_loc7`='Ligeramente ocupado.', `FemaleText_loc1`='지금은 좀 바쁜데요.', `FemaleText_loc4`='有点忙。', `FemaleText_loc5`='有點忙。', `FemaleText_loc7`='Ligeramente ocupada.' WHERE `ID`=24256;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일인가요? 제가 좀 바쁘거든요.', `MaleText_loc4`='什么？我现在很忙。', `MaleText_loc5`='什麼?我現在很忙。', `MaleText_loc7`='¿Qué? Estoy ocupado.', `FemaleText_loc1`='무슨 일인가요? 전 바빠요.', `FemaleText_loc4`='什么？我现在很忙。', `FemaleText_loc5`='什麼?我現在很忙。', `FemaleText_loc7`='¿Qué? Estoy ocupada.' WHERE `ID`=24257;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='근무 중입니다. 그만 가세요. 가란 말입니다.', `MaleText_loc4`='忙着呢，走开。', `MaleText_loc5`='值勤中。滾。開。', `MaleText_loc7`='Estoy de servicio. VETE. DE. AQUÍ.', `FemaleText_loc1`='근무 중이거든요. 가세요. 가시라고요.', `FemaleText_loc4`='忙着呢，走开。', `FemaleText_loc5`='值勤中。滾。開。', `FemaleText_loc7`='Estoy de servicio. VETE. DE. AQUÍ.' WHERE `ID`=24258;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐 고치실 거라도 있나요? 고급형 자동판매기를 이용하세요.', `MaleText_loc4`='你有东西需要修理吗？请使用售货机器人。', `MaleText_loc5`='你有東西需要修理嗎?請使用販賣機。', `MaleText_loc7`='¿Necesitas arreglar algo? Usa el Vendo-trón Deluxe.', `FemaleText_loc1`='뭐 고치실 거라도 있으신가요? 고급형 자동판매기를 이용해 주세요.', `FemaleText_loc4`='你有东西需要修理吗？请使用售货机器人。', `FemaleText_loc5`='你有東西需要修理嗎?請使用販賣機。', `FemaleText_loc7`='¿Necesitas arreglar algo? Usa el Vendo-trón Deluxe.' WHERE `ID`=24259;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 오그리마에서 가시덤불 골짜기에 있는 주둔 기지 그롬골 주둔지로 오가는 이 비행선을 지키지.', `MaleText_loc4`='我们保护着这艘由奥格瑞玛飞往荆棘谷格罗姆高营地的飞艇。', `MaleText_loc5`='我們保護這艘從奧格瑪航行至荊棘谷格羅姆高營地的飛船。', `MaleText_loc7`='Protegemos esta nave en su trayecto de Orgrimmar al Campamento Grom''gol en la Vega de Tuercespina.', `FemaleText_loc1`='우리는 오그리마에서 가시덤불 골짜기에 있는 주둔 기지 그롬골 주둔지로 오가는 이 비행선을 지킨다네.', `FemaleText_loc4`='我们保护着这艘由奥格瑞玛飞往荆棘谷格罗姆高营地的飞艇。', `FemaleText_loc5`='我們保護這艘從奧格瑪航行至荊棘谷格羅姆高營地的飛船。', `FemaleText_loc7`='Protegemos esta nave en su trayecto de Orgrimmar al Campamento Grom''gol en la Vega de Tuercespina.' WHERE `ID`=24260;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금은 안되거든. $g총각:아가씨;... 할 일이 있거든. 나중에 보자고.', `MaleText_loc4`='现在没空，朋友……我有事要做，再见。', `MaleText_loc5`='不是現在，$g夥伴:甜心;...我有事情要忙。再見。', `MaleText_loc7`='Ahora no, $gtío:cielo;... Tengo cosas que hacer. Nos vemos.' WHERE `ID`=24261;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 모는 비행선은 아제로스에서 제일 근사한 거야. 예전엔 쌍등포에다 도시 하나쯤은 가루로 만들만한 폭탄까지 싣고 다녔었단 말이지... 이 비행선 그림자가 비치기만 해도 적군들은 혼비백산해서 도망갔을 정도라고.$B$B뭣이라? 당연히 사실이고 말고!', `MaleText_loc4`='我管理着艾泽拉斯最坚固的飞船。她曾经靠两门轻型火炮就炸平了一座城市，真的……她投射下的阴影就足以让敌人魂飞魄散。$b$b什么？这当然是真的！', `MaleText_loc5`='我駕駛艾澤拉斯裡最堅固的飛船。她曾經裝備著雙輕型火砲和足以夷平一座城市的炸藥，你知道的...光是她的影子就足夠擊退敵人了。$b$b什麼?這當然是真的!', `MaleText_loc7`='Estoy al mando de la más rigurosa nave de Azeroth. Solía estar equipada con cañones de luz gemelos y bombas suficientes para borrar del mapa una ciudad, ya sabes... su mera sombra era capaz de aniquilar ejércitos.$B$B¿Qué? ¡Claro que es verdad!' WHERE `ID`=24262;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 곰으로 변신합니다!', `MaleText_loc4`='%s变形成为了一头熊！', `MaleText_loc5`='%s變身為一隻熊!', `MaleText_loc7`='¡%s se transforma en oso!' WHERE `ID`=24263;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='태양너울 통제권은 이제 거의 우리 손 안에 있습니다. 지금 이대로 항구에서 증원군이 올라오지 못하도록 막아낸다면 반드시 성공할 수 있을 겁니다.$B$B목표는 $3238w퍼센트 만큼 달성했습니다.', `MaleText_loc4`='阳湾港很快就要被我们控制了。如果我们能够持续不断地让港口得到增援，那就必胜无疑了。$B$B我们的目标完成率已经达到了$3238w%%。', `MaleText_loc5`='我們快可以鞏固對日境地區的控制權了。假如我們設法讓那個港口無法獲得援軍支援的話，我們就可以辦到了。$B$B我們目前的目標達成率為$3238w％。', `MaleText_loc7`='Casi hemos consolidado nuestro control en Tramo del Sol. Si evitamos que el puerto consiga refuerzos tendremos éxito.$B$BHemos completado el $3238w % de nuestra meta.' WHERE `ID`=24264;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 해냈습니다, $n. 태양너울 통제권을 손에 넣은 이상 곧 완벽한 승리가 눈앞에 있습니다.', `MaleText_loc4`='成功了，$n。掌控了阳湾港之后，我们离全面胜利只有一步之遥了。', `MaleText_loc5`='我們成功了，$n。現在日境已經在我們的控制之下，沒多久我們就可以達到完全的勝利。', `MaleText_loc7`='Lo hemos logrado, $n. Con Tramo del Sol bajo nuestro control estamos a un paso de la victoria absoluta.' WHERE `ID`=24266;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전쟁에서 죽은 이들을 추모할 기념비를 세울 자금을 마련하고 있어요. 승리를 위해 목숨을 희생한 이들을 잊어서는 안 되죠.$B$B현재까지 총 자금의 $3275w 퍼센트를 모금했답니다.', `FemaleText_loc4`='我正在收集捐款，为那些在战争中牺牲的勇士们建造一座纪念碑。对我们来说，铭记这些为了取得胜利而牺牲的伙伴是非常有意义的。$B$B我们的目标完成率已经达到了百分之$3275w。', `FemaleText_loc5`='我正在募集資金來蓋一座紀念碑，以紀念那在戰爭中死去的英雄。我們不能忘記那些為了獲得勝利而犧牲的人們。$B$B我們目前的目標達成度為$3275w％。', `FemaleText_loc7`='Estoy recolectando fondos para construir un monumento en honor de aquellos que murieron en la guerra. Es importante que no olvidemos los sacrificios que hemos hecho para obtener la victoria.$B$BHemos completado esta meta en un $3275w %.' WHERE `ID`=24267;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아름답지 않나요? 우리는 크나큰 희생이 치러진 지난 세월을 반드시 기억해야 해요. 그리고 승리한 전쟁일지라도 우리가 치른 대가를 잊어서는 안 된답니다.', `FemaleText_loc4`='这座纪念碑不漂亮吗？对我们来说，铭记这些为胜利而牺牲的伙伴们非常有意义。我们永远都不能忘记战争的代价——即便是那些我们最终获胜的战争。', `FemaleText_loc5`='這個紀念碑很美吧?牢記那些歷史上的重大犧牲是很重要的，免得我們忘記那些戰爭的代價 - 既使是那些勝利的戰爭。', `FemaleText_loc7`='¿No es precioso el monumento? Es importante recordar los momentos de nuestra historia en los que se hicieron grandes sacrificios para no olvidar que todas las guerras tienen un precio, incluso las que se ganan.' WHERE `ID`=24268;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐 눈을 붙여야겠습니다. 배가 멈춰있는 동안 좀 봐주실 수 있으십니까?', `MaleText_loc4`='我去打个瞌睡。你觉得自己能在飞船停泊期间控制好她吗？', `MaleText_loc5`='我要去打個小盹。你覺得你有辦法在船靜止時好好照顧她嗎?', `MaleText_loc7`='Voy a echarme una siestecita. ¿Crees que podrás encargarte de la nave mientras esté parada?' WHERE `ID`=24269;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알았습니다, 멀미약을 가져다 드릴 테니 1초만 기다리시지요...', `MaleText_loc4`='好吧，等我一会儿，我去拿轴承……', `MaleText_loc5`='沒問題，給我點時間去拿我的軸承...', `MaleText_loc7`='Vale, dame un segundo para que coja mis pertenencias...' WHERE `ID`=24270;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자 갑시다, 떠납시다!', `MaleText_loc4`='该出发了！', `MaleText_loc5`='上路了!', `MaleText_loc7`='¡Es hora de partir!' WHERE `ID`=24271;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배웅 나온 사람들에게 인사하시지요. 출발할 시간입니다!', `MaleText_loc4`='精彩的旅途即将展开！', `MaleText_loc5`='該是在旅途中表演的時候了!', `MaleText_loc7`='¡Hora de llevar el espectáculo a la carretera!' WHERE `ID`=24272;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법처럼 멋진 제 실력을 발휘할 시간이로군요!', `MaleText_loc4`='看我的！', `MaleText_loc5`='該是使用我的魔法的時候了!', `MaleText_loc7`='¡Es hora de demostrar lo que sé hacer!' WHERE `ID`=24273;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러게, 여긴 내가 처리할 수 있으니.', `MaleText_loc4`='前进，我能搞定。', `MaleText_loc5`='請便，我可以處理這個部分。', `MaleText_loc7`='Vamos, me puedo encargar de esta parte.' WHERE `ID`=24274;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와 줘! 지금 떠난단 말이야!', `MaleText_loc4`='喂！我们要出发了！', `MaleText_loc5`='幫幫我!我們要離開了!', `MaleText_loc7`='¡AYÚDENME! ¡NOS VAMOS!' WHERE `ID`=24275;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일어나!! 지금 출항한다고!', `MaleText_loc4`='醒醒！！我们要启航了！', `MaleText_loc5`='醒醒啊!!我們要離開了!', `MaleText_loc7`='¡DESPERTAD! ¡NOS ESTAMOS ALEJANDO DEL MUELLE!' WHERE `ID`=24276;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='낮잠 시간은 끝났어!! 출발이야, 출발!', `MaleText_loc4`='别睡了！！我们要出发了！', `MaleText_loc5`='打盹結束!!我們要出發了!', `MaleText_loc7`='¡SE ACABÓ LA SIESTA! ¡NOS VAMOS!' WHERE `ID`=24277;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말로 그 문을 통과하고 싶다면, 적어도 세 사람의 힘은 보태야 하오. 이리 따라오시오!', `MaleText_loc4`='如果你真的想打开那些门，就至少需要3个人的力量！跟我来！', `MaleText_loc5`='如果你真的想要通過那些門的話，你將得借給我至少三個人的力量!跟緊了!', `MaleText_loc7`='¡Si realmente queréis atravesar esas puertas necesitaré la fuerza de, al menos, tres personas! ¡Seguidme!' WHERE `ID`=24278;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 큰 소리로 헛기침을 합니다.', `FemaleText_loc4`='%s大声地清了清喉咙。', `FemaleText_loc5`='%s大聲的清了清她的喉嚨。', `FemaleText_loc7`='%s se aclara la garganta en alto.' WHERE `ID`=24279;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='파수병, 다 왔으니 이제 그만 일어나요!', `FemaleText_loc4`='飞艇已经靠港。站好了！', `FemaleText_loc5`='看守者，我們已經靠岸了。起身!', `FemaleText_loc7`='Vigía, hemos atracado. ¡En pie!' WHERE `ID`=24280;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='배를 댈 때 서 있지도 못할 만큼 일이 힘들다는 말인가요? 가족까지 딸렸다고 해서 일자리를 드렸던 거란 말이에요. 당신을 채용한 사실을 후회하지 않도록 해줘요.', `FemaleText_loc4`='你的工作很辛苦吗？累得连我们靠港的时候你都没有力气站好？我是看着你的家族的面子上，才给了你这份差事。别让我后悔自己的决定。', `FemaleText_loc5`='你的工作有這麼累到讓你甚至無法在我們靠岸時站得好好的嗎?我給你這個職位是給你家族面子。別讓我後悔做了那個決定。', `FemaleText_loc7`='¿Acaso es tan duro tu trabajo que no te queda energía para estar preparado cuando atracamos? Te di este trabajo para hacer un favor a tu familia. No hagas que me arrepienta.' WHERE `ID`=24281;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저희 배에 타신 것을 환영해요, $c님. 갖고 계신 짐은 내려놓고 여행을 즐기셨으면 해요. "보라공주호"에 타셨으니, 손님께서 편하게 계시기만을 바란답니다. 여행하는 동안 필요한 게 있으시다면 아래층에 있는 자동판매기를 이용해주세요.', `FemaleText_loc4`='欢迎上船，$c。放下行李，享受你的旅程吧。在紫色公主号上，我们希望您心情愉快。如果你在船上有什么需要的话，船舱里有售货机可以为您服务。', `FemaleText_loc5`='歡迎登艦$c。卸下重擔好好享受這趟旅途。在「紫色公主號」上我們希望你能夠覺得放鬆。假如你登船後有任何需要的話，我們樓下備有販賣機。', `FemaleText_loc7`='Te doy la bienvenida a bordo, $c. Relájate y disfruta del viaje. A bordo del "Princesa púrpura" queremos que te relajes. Tenemos máquinas de refrescos y comida abajo por si necesitas algo mientras estas a bordo.' WHERE `ID`=24282;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='능률적으로 일하는 선원이 되려면 휴식이 중요하지요. 적당히 쉬게 해주시면, 선원들은 일을 더 잘할 겁니다.', `MaleText_loc4`='娱乐是让船员保持工作效率的重要手段。心情轻松了，他们的表现才会更好。', `MaleText_loc5`='休息與消遣是成為一個有效率的船員的關鍵。讓船員好好休息，他們才能表現得更好。', `MaleText_loc7`='La relajación es la clave para conseguir una tripulación eficiente. Deja que la tripulación se relaje y trabajará mejor.' WHERE `ID`=24283;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선장님이야 멋진 분이지요! 배가 도착하면 쉴 시간이 생깁니다. 제가 가장 고대하는 순간이지요.', `MaleText_loc4`='船长真是太明理啦！我们在靠港后可以去放松一下！那是我最向往的时刻。', `MaleText_loc5`='船長太棒了!我們有時間在我們靠岸時好好放鬆一下。那是最令我盼望的時刻。', `MaleText_loc7`='¡El Capitán es genial! Nos da tiempo para relajarnos cuando atracamos. Esos son los momentos que más me gustan.' WHERE `ID`=24284;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='몇 초라도 쉬게 해주십시오.', `MaleText_loc4`='请让我休息一小会。', `MaleText_loc5`='請容許我休息一下。', `MaleText_loc7`='Por favor, permíteme descansar unos segundos.' WHERE `ID`=24285;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='5분만 더 자게 해주십시오...', `MaleText_loc4`='让我再睡会吧，就五分钟，朋友……', `MaleText_loc5`='媽，再讓我多睡五分鐘...', `MaleText_loc7`='Déjame dormir cinco minutitos más...' WHERE `ID`=24286;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금은 바빠, 친구.', `MaleText_loc4`='我现在很忙。', `MaleText_loc5`='我現在很忙。', `MaleText_loc7`='Ahora estoy ocupado.', `FemaleText_loc1`='지금은 바쁘다고요.', `FemaleText_loc4`='我现在很忙。', `FemaleText_loc5`='我現在很忙。', `FemaleText_loc7`='Ahora estoy ocupada.' WHERE `ID`=24287;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐 고칠 거라도 있나? 고급형 자동판매기를 이용하라고.', `MaleText_loc4`='你有东西需要修理吗？请使用售货机器人。', `MaleText_loc5`='你需要修理東西嗎?請使用販賣機。', `MaleText_loc7`='¿Necesitas arreglar algo? Usa el Vendo-trón.', `FemaleText_loc1`='뭐 고칠 거라도 있으세요? 고급형 자동판매기를 이용하세요.', `FemaleText_loc4`='你有东西需要修理吗？请使用售货机器人。', `FemaleText_loc5`='你需要修理東西嗎?請使用販賣機。', `FemaleText_loc7`='¿Necesitas arreglar algo? Usa el Vendo-trón.' WHERE `ID`=24288;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 얘기할 시간 없다고.', `MaleText_loc4`='我现在没时间和你闲聊。', `MaleText_loc5`='我現在沒空討論這個。', `MaleText_loc7`='No tengo tiempo para hablar ahora.', `FemaleText_loc1`='지금 얘기할 시간 없거든요.', `FemaleText_loc4`='我现在没时间和你闲聊。', `FemaleText_loc5`='我現在沒空討論這個。', `FemaleText_loc7`='No tengo tiempo para hablar ahora.' WHERE `ID`=24289;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그롬골에서 언더시티로 가는 여행은 참 아름답습니다. 조금 지루하긴 해도 말입니다. 그렇다고 근무중에 잠들 수야 없지요.', `FemaleText_loc4`='尽管从格罗姆高营地到幽暗城的航线平淡无奇，但是一路上的风景秀色宜人。可是这并不能成为工作时候睡着的理由。', `FemaleText_loc5`='從葛羅姆高到幽暗城的飛行是多麼的美麗而平靜。當然這不是在工作中睡著的藉口。', `FemaleText_loc7`='El vuelo desde Grom''gol a Entrañas es precioso, pero muy tranquilo. Aunque eso no es excusa para quedarse dormido en el trabajo.' WHERE `ID`=24290;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 계산이 맞는다면, 이 징을 쳐야 저 문이 무너져 내릴 거요. 헛소리처럼 들린다는 걸 나도 알지만, 거짓말 하나도 안 보태고 솔직히 말하자면, 이건 시대를 앞지른 발상이라 생각하오!', `MaleText_loc4`='如果我的计算正确的话，敲打这面锣就可以打开那扇门。我知道，这实在太疯狂了，不过说真的，我想这可能是个节约时间的好主意。', `MaleText_loc5`='如果我的計算是正確的，敲響那個銅鑼將可以打開那扇門。這很瘋狂，我知道，但老實說，我認為這是個超越時代的好主意!', `MaleText_loc7`='Si mis cálculos son correctos, golpear este gong abrirá esa puerta. Es una locura, lo sé, pero para serte sincero, creo que es una idea revolucionaria.' WHERE `ID`=24291;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='', `MaleText_loc4`='', `MaleText_loc5`='', `MaleText_loc7`='' WHERE `ID`=24292;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='먼지와 더러움을 피해 안으로 들어 오세요. 잠시 젖은 몸도 말리시고요.', `MaleText_loc4`='进来休息一会儿吧，远离灰尘和泥沼吧。', `MaleText_loc5`='經過了灰燼與污泥。讓你自己風乾一陣子吧。', `MaleText_loc7`='Entra y líbrate de la ceniza y la mugre. Sécate con un hechizo.' WHERE `ID`=24293;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋을 대로 하시오. 하지만 안에 들어가려거든 최소한 세 명은 나를 도와야 하오. 따라오시오...', `MaleText_loc4`='准备好。如果我们想进去的话，至少得有3个人帮我。跟着我……', `MaleText_loc5`='請自便。如果我們要進去的話，你們其中至少要有五個人協助我。跟我來...', `MaleText_loc7`='Adelante. Si vamos a entrar necesito que tres de ustedes me ayuden. Sigueme…' WHERE `ID`=24294;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 계산에 따르면, 충분한 인원이 한꺼번에 징을 울리면 이 문을 막은 봉인이 깨져 안으로 들어갈 수 있을 거요.', `MaleText_loc4`='根据我的计算，如果我们有足够多的人同时敲锣的话，那么这些门上的封印就会被揭开，这样我们就能进去了。', `MaleText_loc5`='根據我的計算，只要我們夠多人一起敲響銅鑼，這樣那些門扉的封印就會破裂，我們就能進去了。', `MaleText_loc7`='Según mis cálculos si varios de nosotros golpeamos el gong a la vez, el sello de estas puertas se romperá y podremos entrar.' WHERE `ID`=24295;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겁이 나는 모양이군. 그만두는 게 나을지도 모르겠소. 저기서 당신 같은 이들을 기다리는 건 죽음뿐일 테니까...', `MaleText_loc4`='我承认我害怕了。也许这样更好——只有死亡在那里等待着像你们这样的人。', `MaleText_loc5`='害怕吧，我這麼想。或許這樣比較好 - 對你的同類來說，這裡除了死亡別無他物...', `MaleText_loc7`='Achantados, supongo. Probablemente sea mejor así, ahí no hay nada más que muerte para la gente como tú...' WHERE `ID`=24296;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 다음 순회 공연을 기획하는 동안 타우렌 족장들은 실버문에 머무르고 있습니다. 연습이 없을 때는 지금 제 위에 보이는 발코니에서 시간을 보내곤 하지요. 마음껏 손을 흔드세요... 관심 받는 걸 아주 좋아하거든요.

당장은 공연 계획도 없고 일꾼을 모집하지도 않습니다만, 나중에 또 들러 주십시오. 무슨 일이 생길지 누가 알겠습니까?', `MaleText_loc4`='牛头人酋长乐队在下一场巡回演出期间会停留在银月城。他们经常在没有练习任务的时候在我上方的阳台上懒洋洋地晒太阳。请随意和他们打招呼吧……他们喜欢被关注的感觉。

我们暂时不需要新的人手，不过你可以时常来看看。谁知道会发生什么？', `MaleText_loc5`='牛頭大佬在我替他們安排下一場巡迴演出時都會待在銀月城裡。他們沒排練的時候通常會在我上方的樓臺裡消磨時間。放心揮手吧...他們喜歡接受注目。

我們目前沒有接受表演或是工作人員，不過你以後可以常來連繫看看。誰知道會發生什麼事呢?', `MaleText_loc7`='Los Tauren Chieftains se quedarán en Lunargenta mientras preparo su próxima gira. Cuando no están ensayando, suelen estar en el balcón que hay sobre mí. No te cortes y saluda... les encanta la atención.

Por ahora no estamos contratando gente ni para el espectáculo ni para el personal, pero puedes volver a comprobarlo más tarde. ¿Quién sabe qué puede pasar?' WHERE `ID`=24297;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='테로카르 숲에서 저분들의 공연을 보신 적이 있습니까? 끝내준다고요!', `MaleText_loc4`='你有没有看过他们在泰罗卡森林的表演？太精彩了！', `MaleText_loc5`='你有看過他們在泰洛卡森林的表演嗎?太驚人了!', `MaleText_loc7`='¿Conseguiste ver su espectáculo en el Bosque de Terokkar? ¡Fue fantástico!', `FemaleText_loc1`='테로카르 숲에서 저분들의 공연을 보신 적이 있나요? 아아, 정말 멋있었어요!', `FemaleText_loc4`='你没看过他们在泰罗卡森林的表演吗？太精彩了！', `FemaleText_loc5`='你有看過他們在泰洛卡森林的表演嗎?太驚人了!', `FemaleText_loc7`='¿Conseguiste ver su espectáculo en el Bosque de Terokkar? ¡Fue fantástico!' WHERE `ID`=24298;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타우렌 족장들은 아제로스를 통틀어 제일 유명한 가수랍니다!', `MaleText_loc4`='牛头人酋长乐队一定是整个艾泽拉斯最著名的乐队了！', `MaleText_loc5`='牛頭大佬一定是整個艾澤拉斯最知名的藝人!', `MaleText_loc7`='¡Los Tauren Chieftains son los juglares más famosos de todo Azeroth!', `FemaleText_loc1`='타우렌 족장들은 온 아제로스에서 최고로 유명한 가수라고요!', `FemaleText_loc4`='牛头人酋长乐队一定是整个艾泽拉斯最著名的乐队了！', `FemaleText_loc5`='牛頭大佬一定是整個艾澤拉斯最知名的藝人!', `FemaleText_loc7`='¡Los Tauren Chieftains son los juglares más famosos de todo Azeroth!' WHERE `ID`=24299;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저분들이 실버문에 얼마나 머무를 예정인지 궁금합니다. 여기서 공연한다면 정말 좋을 텐데요!', `MaleText_loc4`='我想知道他们会在银月城待多久，真希望他们能在这里表演！', `MaleText_loc5`='我想知道他們會在銀月城待多久。我希望他們可以在這裡進行演出!', `MaleText_loc7`='Me pregunto cuánto tiempo más se quedarán en Lunargenta. ¡Espero que toquen ahí!', `FemaleText_loc1`='저분들이 실버문에 얼마나 머무르실지 궁금하네요. 여기서 공연까지 하신다면 얼마나 좋을까요!', `FemaleText_loc4`='我想知道他们会在银月城待多久，真希望他们能在这里表演！', `FemaleText_loc5`='我想知道他們會在銀月城待多久。我希望他們可以在這裡進行演出!', `FemaleText_loc7`='Me pregunto cuánto tiempo más se quedarán en Lunargenta. ¡Espero que toquen ahí!' WHERE `ID`=24300;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기 올라가서 저분들과 이야기해볼 수 있다면 무슨 짓이든 할 겁니다...', `MaleText_loc4`='如果可以的话，我愿付出一切来找寻一个上台和他们谈话的机会……', `MaleText_loc5`='我願意付出所有以換取一次可以上去跟他們聊聊的機會...', `MaleText_loc7`='Daría lo que fuera por poder hablar con ellos...', `FemaleText_loc1`='아아... 저기 올라가서 저분들이랑 이야기해볼 수 있다면 무슨 짓이든 할 텐데...', `FemaleText_loc4`='如果可以的话，我愿付出一切来找寻一个上台和他们谈话的机会……', `FemaleText_loc5`='我願意付出所有以換取一次可以上去跟他們聊聊的機會...', `FemaleText_loc7`='Daría lo que fuera por poder hablar con ellos...' WHERE `ID`=24301;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='준비되지 않은 채 적과 맞서서는 안 돼요, $n. 당신이 자신의 능력을 증명해 보인다면 아주 강력한 물건을 드리겠어요.', `FemaleText_loc4`='不要在还未准备好的时候就去战斗，$n。倘若你已经向我们证明了自己的能力……我就可以给你提供一些非常强大的装备。', `FemaleText_loc5`='不要毫無準備地和敵人交戰，$n。我可以提供你非常強大的物品...因為你已經向我們證明了自己。', `FemaleText_loc7`='No luches contra el enemigo sin estar preparado, $n. Puedo proporcionarte objetos muy poderosos... siempre y cuando nos hayas demostrado lo que vales.' WHERE `ID`=24302;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='캘타스의 추종자들은 이제 겸손이란 게 뭔지 배울 것이오. 우리가 이제 새벽칼날단을 쳐부수고 태양너울 항구를 되찾을 테니.$B$B임무는 지금 $3238w 퍼센트까지 달성한 상태요.', `MaleText_loc4`='很快凯尔萨斯的走狗们就会得到深刻的教训。我们很快就会碾碎晨锋部队，把阳湾港口从他们手里夺回来。$b$b我们的目标完成率已经达到$3238w%%了。', `MaleText_loc5`='凱爾的寵物是該在羞辱中學上一課。我們將會擊潰曦刃軍團並且從他們手中奪下日境港。$B$B我們目前的目標達成率為$3238w％。', `MaleText_loc7`='Vamos a enseñar una humillante lección a los lacayos de Kael. Aplastaremos al ejército Hojalba y les arrebataremos el Puerto de Tramo del Sol.$B$BHemos completado el $3238w % de nuestra meta.' WHERE `ID`=24303;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 태양너울을 점령했소. 캘타스의 추종자들은 도망치고 있소... 이제 그자들을 편안히 잠들게 해 줄 때라오!', `MaleText_loc4`='阳湾港是我们的了。凯尔萨斯的走狗们落荒而逃……是时候让他们脱离苦海了！', `MaleText_loc5`='日境屬於我們了。凱爾的走狗四散奔逃...是時候來終結他們的苦難了!', `MaleText_loc7`='Tramo del Sol es nuestro. Los perros de Kael están huyendo... ¡Es hora de acabar con su sufrimiento!' WHERE `ID`=24304;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 타우렌 족장들을 도와주는 일꾼들을 관리하고 있습니다.

아시겠지만, 짐을 싸고, 운전하고, 마차에서 짐을 내리고, 무대를 세우고 해체하고, 무대에 불꽃 효과를 설치하고, 뭐 그런 종류의 일들을 한단 말이지요.', `MaleText_loc4`='我是牛头人酋长乐队的后勤人员主管。

你知道啦，就是打包、转运、卸货、搭建拆卸舞台、调试灯光效果，所有这类事情。', `MaleText_loc5`='我負責管理支援牛頭大佬的工作人員。

你知道的:打包，開車，還有樂器拆卸，舞台搭蓋及拆掉，設置煙火，所有這種類的事。', `MaleText_loc7`='Estoy al mando de los trabajadores que acompañan a los Tauren Chieftains.

Ya sabes: cargar, conducir y descargar los vagones, montar y desmontar el escenario, colocar la pirotecnia y ese tipo de cosas.' WHERE `ID`=24305;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 슈바이처는 내 오랜 친구라오... 아주 소중한 거지, 그, 우정이란 거 말이오. 샤트라스에서 이 친구를 다시 만나기 전에는 그런 감정이 어떤 건지 잊고 살았다오.

요새 슈바이처는 티리스팔 숲에 잘 오지 못하니까, 안부를 전하고 싶으면 순간이동의 보주를 사용해 내가 여기 오는 게 낫겠다고 생각했다오.', `MaleText_loc4`='舒维瑟尔是我的一个老朋友了……很有价值。我的意思是指我们的友谊。我以为我已经遗忘了那种感觉，直到我们再次在沙塔斯城相遇。

他最近并不常在提瑞斯法林地，所以我想通过传送宝珠过去，向他问个好。', `MaleText_loc5`='這裡的史懷哲是我的老朋友...那，是一件貴重的東西。我是說，友情。我想我會忘掉這種感覺，直到我們再度在撒塔斯城遇見。

這些日子他沒有常常待在提里斯法，所以我想我會使用這裡的傳送之門去傳達我的問候。', `MaleText_loc7`='Schweitzer es un viejo amigo mío... una cosa de gran valor. Me refiero a la amistad. Creía que había olvidado esa sensación hasta que volvimos a encontrarnos en la Ciudad de Shattrath.

Ya no pasa tanto tiempo en Tirisfal, así que se me ocurrió traer el Orbe de traslado aquí para saludarle.' WHERE `ID`=24306;
