UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겨울맞이 축제가 끝나기 전에 겨울 할아버지를 만날 기회가 있으면 좋겠군요.', `MaleText_loc4`='我希望在冬幕节结束之前有机会去拜访一下冬天爷爷。', `MaleText_loc5`='我希望我有機會能在冬幕節結束前去拜訪冬天爺爺。', `MaleText_loc7`='Espero tener la oportunidad de ver al Gran Padre Invierno antes de que termine el Festival de Invierno.', `FemaleText_loc1`='겨울맞이 축제가 끝나기 전에 겨울 할아버지를 한 번 만나뵐 수 있으면 좋겠어요.', `FemaleText_loc4`='我希望在冬幕节结束之前有机会去拜访一下冬天爷爷。', `FemaleText_loc5`='我希望我有機會能在冬幕節結束前去拜訪冬天爺爺。', `FemaleText_loc7`='Espero tener la oportunidad de ver al Gran Padre Invierno antes de que termine el Festival de Invierno.' WHERE `ID`=24323;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='굴뚝나무 목장조합의 고블린들은 이맘때가 되면 언제나 멋진 물건들을 판답니다.', `MaleText_loc4`='每年的这个时候，烟林牧场的地精们总是会出售一些非常棒的糖果。', `MaleText_loc5`='燻木牧場的哥布林在每年的這個時候都會賣些好東西。', `MaleText_loc7`='Los goblins de Pastos de Bosquehumeante siempre tienen unas golosinas magníficas en esta época del año.', `FemaleText_loc1`='굴뚝나무 목장조합의 고블린들은 매년 이 시기면 언제나 멋진 물건들을 판매해요.', `FemaleText_loc4`='每年的这个时候，烟林牧场的地精们总是会出售一些非常棒的糖果。', `FemaleText_loc5`='燻木牧場的哥布林在每年的這個時候都會賣些好東西。', `FemaleText_loc7`='Los goblins de Pastos de Bosquehumeante siempre tienen unas golosinas magníficas en esta época del año.' WHERE `ID`=24324;
