UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전설에 따르면 거대한 괴수 오멘이 달숲에 있는 엘룬아라 호수에 잠들어 있으며 일 년에 딱 한 번 나타난다고 하오. 단지 전설일지도 모르지만 말이오.', `MaleText_loc4`='传说强大的年兽沉睡在月光林地的月神湖底，每年只会醒来一次。不过那也只是个传说。', `MaleText_loc5`='傳說年獸沉睡在月光林地的月神湖水裡，一年只出現一次。但是那只是一個傳說。', `MaleText_loc7`='La leyenda dice que la gran bestia Augurio duerme en las aguas del Lago Elune''ara en Claro de la Luna y solo aparece una vez al año. Pero solo es una leyenda.', `FemaleText_loc1`='전설에 따르면 거대한 괴수 오멘이 달숲에 있는 엘룬아라 호수에 잠들어 있으며 일 년에 딱 한 번 나타난다고 하더군요. 하지만 단지 전설일 뿐이겠죠 뭐.', `FemaleText_loc4`='传说强大的年兽沉睡在月光林地的月神湖底，每年只会醒来一次。不过那也只是个传说。', `FemaleText_loc5`='傳說年獸沉睡在月光林地的月神湖水裡，一年只出現一次。但是那只是一個傳說。', `FemaleText_loc7`='La leyenda dice que la gran bestia Augurio duerme en las aguas del Lago Elune''ara en Claro de la Luna y solo aparece una vez al año. Pero solo es una leyenda.' WHERE `ID`=24332;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 달의 축제 기간에 장로들을 찾아가서 그분들의 지혜를 배워야 하오.', `MaleText_loc4`='春节期间，我们应该花些时间去寻找长者，并领略他们的智慧。', `MaleText_loc5`='在新年慶典期間，我們應該花時間尋找我們的長輩並且聽取他們的智慧。', `MaleText_loc7`='Durante el Festival Lunar, deberíamos tomarnos algo de tiempo para buscar a nuestros ancianos y ser testigos de su sabiduría.', `FemaleText_loc1`='우리는 달의 축제 기간에 장로들을 찾아가서 그분들의 지혜를 배워야 합니다.', `FemaleText_loc4`='春节期间，我们应该花些时间去寻找长者，并领略他们的智慧。', `FemaleText_loc5`='在新年慶典期間，我們應該花時間尋找我們的長輩並且聽取他們的智慧。', `FemaleText_loc7`='Durante el Festival Lunar, deberíamos tomarnos algo de tiempo para buscar a nuestros ancianos y ser testigos de su sabiduría.' WHERE `ID`=24333;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불꽃놀이 구경해 보신 적 있소? 요즘이 1년 중에 폭죽을 사기 가장 좋은 때라오.', `MaleText_loc4`='你看过烟花吗？现在是一年当中买烟花放的最佳季节！', `MaleText_loc5`='你有看過煙火嗎?現在可是一年之中購買它們的最佳時機。', `MaleText_loc7`='¿Has visto los fuegos artificiales? Este es el mejor momento del año para comprarlos.', `FemaleText_loc1`='불꽃놀이 구경해 보신 적 있으신가요? 요즘이 1년 중에 폭죽을 사기 가장 좋은 때랍니다.', `FemaleText_loc4`='你看过烟花吗？现在是一年当中买烟花放的最佳季节！', `FemaleText_loc5`='你有看過煙火嗎?現在可是一年之中購買它們的最佳時機。', `FemaleText_loc7`='¿Has visto los fuegos artificiales? Este es el mejor momento del año para comprarlos.' WHERE `ID`=24334;
