UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불꽃놀이 본 적 있으십니까? 불꽃놀이 폭죽을 사려면 지금이 딱 좋을 때입니다.', `MaleText_loc4`='你看过烟花吗？现在是一年当中买烟花放的最佳季节！', `MaleText_loc5`='你有看過煙火嗎?現在可是一年之中購買它們的最佳時機。', `MaleText_loc7`='¿Has visto los fuegos artificiales? Este es el mejor momento del año para comprarlos.', `FemaleText_loc1`='불꽃놀이 본 적 있나요? 불꽃놀이 폭죽을 사려면 지금이 딱 좋을 때거든요.', `FemaleText_loc4`='你看过烟花吗？现在是一年当中买烟花放的最佳季节！', `FemaleText_loc5`='你有看過煙火嗎?現在可是一年之中購買它們的最佳時機。', `FemaleText_loc7`='¿Has visto los fuegos artificiales? Este es el mejor momento del año para comprarlos.' WHERE `ID`=24351;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밤의 안식처에서 온 드루이드들이 달의 축제를 축하하려 멋진 축하 잔치를 달숲에서 벌였습니다.', `MaleText_loc4`='月光林地的德鲁伊正在举办隆重的庆典，庆祝春节的到来。', `MaleText_loc5`='永夜港的德魯伊將在月光林地舉辦一場盛大的慶典，來歡度新年節慶。', `MaleText_loc7`='Los druidas de Amparo de la Noche han organizado una gran celebración en Claro de la Luna con motivo del Festival Lunar.', `FemaleText_loc1`='밤의 안식처에서 온 드루이드들이 달의 축제를 축하하려 멋진 축하 잔치를 달숲에서 벌였어요.', `FemaleText_loc4`='月光林地的德鲁伊正在举办隆重的庆典，庆祝春节的到来。', `FemaleText_loc5`='永夜港的德魯伊將在月光林地舉辦一場盛大的慶典，來歡度新年節慶。', `FemaleText_loc7`='Los druidas de Amparo de la Noche han organizado una gran celebración en Claro de la Luna con motivo del Festival Lunar.' WHERE `ID`=24352;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방어가 최선의 공격이다라... 그런 말이야 누구나 할 수 있소.', `MaleText_loc4`='最好的防守就是进攻，这是尽人皆知的。', `MaleText_loc5`='攻擊就是最好的防禦，這個道理大家都知道。', `MaleText_loc7`='La mejor defensa es un buen ataque; todo el mundo lo sabe.' WHERE `ID`=24353;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아무리 좋은 무기라도 그걸 쓸 만큼 오래 살지 않으면 아무 소용없지, $c.', `FemaleText_loc4`='如果你没法保证自己能活下来，那么再强的武器对你来说也毫无意义，$c。', `FemaleText_loc5`='如果你沒辦法活得夠久來配戴武器，那麼再強大的武器也不夠好，$c。', `FemaleText_loc7`='Un arma fuerte no sirve de nada si no vives el tiempo suficiente para blandirla, $c.' WHERE `ID`=24354;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가우르그글! 블르글브르글 그르글!', `MaleText_loc4`='Gawurgggl！Blrgl-brgl grgl！', `MaleText_loc5`='嘎嗚嚕咕咕嚕!哺嚕咕嚕 - 哺嚕咕嚕，咕嚕咕嚕!', `MaleText_loc7`='¡Gawurgggl! ¡Blrgl-brgl grgl!' WHERE `ID`=24355;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리와 대화하는 법을 배웠나 봐, $r. 뭐 그렇게 대단한 일은 아니라고 생각하지만.$B$B반드시 처치해야 할 겨울지느러미 배반자들이 저 건너편에 있어.', `MaleText_loc4`='$r，你已经掌握了与我们交流的诀窍，不过这算不了什么。$B$B水塘那边还有大群的冬鳞背叛者等着你去收拾呢。', `MaleText_loc5`='$r，你學會了和我們溝通的技巧，但是我一點也不驚訝。$B$B有很多冬鰭魚人的叛徒在水的對岸，一定要殺掉。', `MaleText_loc7`='Has aprendido un truco para hablar con nosotros, $r, pero no me impresiona.$B$BEn el agua hay traidores Aleta Invernal que matar.' WHERE `ID`=24356;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음!', `MaleText_loc4`='下一个！', `MaleText_loc5`='下一位!', `MaleText_loc7`='¡Siguiente!' WHERE `ID`=24357;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아. 자네 같은 사람이 더 있으면 좋으련만. 시민 연락원에게 보고하고 임무를 받도록 하게.', `MaleText_loc4`='不错，我们需要你这样的人手。向平民联络官报到吧，他会为你分配工作。', `MaleText_loc5`='是啊，我們可以好好運用你的才能。向平民聯絡處回報，好讓你有工作指派。', `MaleText_loc7`='Sí. Nos vendrían bien algunos más como tú. Preséntate ante el coordinador de civiles para que te asigne una labor.' WHERE `ID`=24358;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네에게 맡길 만한 일이 좀 있군. 시민 연락원에게 보고하게.', `MaleText_loc4`='我倒是能提供适合你的工作机会。向平民联络官报到吧。', `MaleText_loc5`='我有一些職缺給你。向平民聯絡處回報。', `MaleText_loc7`='Tengo algunas vacantes en tu línea de trabajo. Preséntate ante el coordinador de civiles.' WHERE `ID`=24359;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 같은 사람은 이미 충분히 모집했다고 생각했는데, 지금 보니 아직 자리가 좀 남았군. 시민 연락원에게 보고하게.', `MaleText_loc4`='我还以为人手已经够了，不过好像还有一些空缺。向平民联络官报到吧。', `MaleText_loc5`='我以為你們這些人已經夠了，但是看起來還有一些職缺的樣子，向平民聯絡處回報吧。', `MaleText_loc7`='Creía que teníamos suficiente personal con tu perfil, pero parece que tenemos algunas vacantes. Preséntate ante el coordinador de civiles.' WHERE `ID`=24360;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아. 자네는 꽤 경험이 많은 것 같군. 당장 시민 연락원에게 보고하게. 자네 같은 사람이 더 필요해!', `MaleText_loc4`='很好，你在这块领域算得上是熟练工。立即向平民联络官报到吧，我们需要你这样的人手！', `MaleText_loc5`='很好，你在你的工作領域中經歷豐富。立刻向平民聯絡處回報，我們需要多一點你這樣的人才!', `MaleText_loc7`='Sí, tienes mucha experiencia en tu campo de trabajo. Preséntate ante el coordinador de civiles inmediatamente, ¡necesitamos más gente como tú!' WHERE `ID`=24361;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보다시피 난 두 눈 다 멀쩡해. 여기에서 뭐가 어떻게 돌아가는지 다 보인다고!', `MaleText_loc4`='我又不是瞎子。我能看到真实的情况！', `MaleText_loc5`='我沒瞎，你知道嗎。這附近發生什麼我看得一清二楚!', `MaleText_loc7`='No estoy ciego, ¿sabes? ¡Veo lo que está pasando aquí!' WHERE `ID`=24362;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 일 할 사람은 넘쳐! 여기 자네 검이 있으니 병영에 가서 보고하고 임무를 받게!', `MaleText_loc4`='又是来应征士兵的！喏，这是你的剑。去兵营报到吧！', `MaleText_loc5`='再也不用囉!這是你的劍，向兵營回報你的任務!', `MaleText_loc7`='¡Ya basta! Aquí tienes tu espada. Preséntate en el cuartel para trabajar.' WHERE `ID`=24363;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아글르글글르글그르르르!', `MaleText_loc4`='Ahglrglglrglgrrr！', `MaleText_loc5`='啊咕嚕咕嚕咕嚕咕嚕!', `MaleText_loc7`='¡Ahglrglglrglgrrr!' WHERE `ID`=24364;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겁낼 것 없네, 친구. 여기 검과 방패가 있네. 병영에 가서 보고하고 임무를 받게나.', `MaleText_loc4`='别害怕，朋友。这是你的剑和盾。去兵营报到吧。', `MaleText_loc5`='朋友，恐怕不行。這是你的劍和盾，向兵營回報你的任務吧。', `MaleText_loc7`='Me temo que no, colega. Aquí tienes tu espada y escudo. Preséntate en el cuartel para trabajar.' WHERE `ID`=24365;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런 훌륭한 팔로 말인가? 아마도 자네는 최전방으로 가야 할 것 같네. 병영에 가서 보고하게.', `MaleText_loc4`='啧啧，瞧你这强壮的胳膊？朋友，前线正需要你这样的勇士。去兵营报到吧。', `MaleText_loc5`='這是你持劍的手嗎?我恐怕你得去前線了，朋友。向兵營回報。', `MaleText_loc7`='¿Con un brazo como ese? Me temo que te necesitamos en las líneas de frente, colega. Preséntate en el cuartel.' WHERE `ID`=24366;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마음이 다 아프군... 나도 채워야 할 할당량이 있어서 어쩔 수가 없네. 자네도 이해하겠지? 칼은 다룰 줄 아나? 병영으로 가 보게.', `MaleText_loc4`='你让我很伤心呢——我得招满分配的名额，你知道吗？你能拿剑吗？去兵营报到好了。', `MaleText_loc5`='你傷透了我的心 - 我還有沒有使用的配額，你知道嗎?你能帶把劍嗎?去兵營那拿吧。', `MaleText_loc7`='Me rompes el corazón. Tengo números que alcanzar, ¿sabes? ¿Puedes blandir una espada? Pues ve al cuartel.' WHERE `ID`=24367;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자리가 하나 더 있었던 것 같은데... 이런, 내가 잘못 알았군. 하나가 아니라 일곱이었네. 자네가 칼 좀 쓰는 사람이었으면 좋겠군. 병영에 가서 보고하게.', `MaleText_loc4`='似乎我们还需要一名……啊，不对。是七名士兵。希望你擅长使剑——去兵营报到吧。', `MaleText_loc5`='看起來我們還有空間再容納一個...不，我的錯。還有七個，不是一個，希望你很會使劍 - 向兵營回報吧。', `MaleText_loc7`='Parece que tenemos sitio para uno más... no, fallo mío. Eso es un siete, no un uno. Espero que se te de bien lo de la espada. Preséntate en el cuartel.' WHERE `ID`=24368;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이보게들, 계속 움직이게.', `MaleText_loc4`='下一位，下一位。', `MaleText_loc5`='讓它繼續運作吧，小子。', `MaleText_loc7`='Seguid así, gente.' WHERE `ID`=24369;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 다음!', `MaleText_loc4`='下一位！', `MaleText_loc5`='下一位，請!', `MaleText_loc7`='¡Siguiente, por favor!' WHERE `ID`=24370;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='목수 일을 했습니다.', `MaleText_loc4`='木匠，长官。', `MaleText_loc5`='長官，我是木工。', `MaleText_loc7`='Carpintero, señor.', `FemaleText_loc1`='목수예요.', `FemaleText_loc4`='木匠。', `FemaleText_loc5`='木工。', `FemaleText_loc7`='Carpintera.' WHERE `ID`=24371;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배를 건조했습니다, 징집관님.', `MaleText_loc4`='造船工，长官。', `MaleText_loc5`='長官，我是造船工人。', `MaleText_loc7`='Carpintero de barcos, señor.', `FemaleText_loc1`='배 만드는 일을 했어요.', `FemaleText_loc4`='造船工。', `FemaleText_loc5`='造船工人。', `FemaleText_loc7`='Carpintera de barcos.' WHERE `ID`=24372;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='농사를 지었습니다, 징집관님.', `MaleText_loc4`='雇农，大人。', `MaleText_loc5`='大人，我是農場工人。', `MaleText_loc7`='Jornalero, mi señor.', `FemaleText_loc1`='농장에서 일했어요, 징집관님.', `FemaleText_loc4`='雇农，长官。', `FemaleText_loc5`='長官，我是農場工人。', `FemaleText_loc7`='Jornalera, mi señor.' WHERE `ID`=24373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='재단사였습니다.', `MaleText_loc4`='裁缝。', `MaleText_loc5`='裁縫。', `MaleText_loc7`='Sastre.', `FemaleText_loc1`='재봉사 일을 했어요, 징집관님.', `FemaleText_loc4`='裁缝，大人。', `FemaleText_loc5`='大人，我是女裁縫師。', `FemaleText_loc7`='Costurera, mi señor.' WHERE `ID`=24374;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대장장이였습니다.', `MaleText_loc4`='铁匠。', `MaleText_loc5`='鐵匠。', `MaleText_loc7`='Herrero.', `FemaleText_loc1`='대장간에서 일했어요.', `FemaleText_loc4`='铁匠。', `FemaleText_loc5`='鐵匠。', `FemaleText_loc7`='Herrera.' WHERE `ID`=24375;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='석공이었습니다, 징집관님.', `MaleText_loc4`='泥瓦匠，长官。', `MaleText_loc5`='長官，我是石匠。', `MaleText_loc7`='Mampostero, señor.', `FemaleText_loc1`='석공이었어요, 징집관님.', `FemaleText_loc4`='泥瓦匠，长官。', `FemaleText_loc5`='長官，我是石匠。', `FemaleText_loc7`='Mampostera, señor.' WHERE `ID`=24376;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='광산에서 일했습니다.', `MaleText_loc4`='矿工。', `MaleText_loc5`='礦工。', `MaleText_loc7`='Minero.', `FemaleText_loc1`='광부였습니다, 징집관님.', `FemaleText_loc4`='矿工，长官。', `FemaleText_loc5`='長官，我是礦工。', `FemaleText_loc7`='Minera, señor.' WHERE `ID`=24377;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요리사였습니다.', `MaleText_loc4`='厨师。', `MaleText_loc5`='廚師。', `MaleText_loc7`='Cocinero.', `FemaleText_loc1`='요리를 했죠, 징집관님.', `FemaleText_loc4`='厨师，长官。', `FemaleText_loc5`='長官，我是廚師。', `FemaleText_loc7`='Cocinera, señor.' WHERE `ID`=24378;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 겨울지느러미 멀록을 감시하러 얼마 전에 여기로 왔습니다. 놈들처럼 변장하고서 말입니다. 그러고는 거리를 두고 녀석들의 일상을 기록했습니다.$B$B그렇지만, 얼마 지나지 않아 모든 것이 변해버렸습니다.$B$B콜다라에서 발생한 지진으로 산사태가 일어나 근처에 있던 동굴이 전부 드러났지요. 거기서 이상한 마크루라가 하나 나와서는 겨울지느러미 일족의 어린 멀록들을 납치해갔습니다. 멀록들이 구하러 동굴로 갔다가, 마크루라에게 세뇌된 상태로 다시 나타났습니다.$B$B영향을 받지 않은 나머지 멀록이 이곳으로 후퇴하는 바람에, 어쩔 수 없이 제가 그들을 이끌게 되었습니다.', `MaleText_loc4`='不久前，我来这里观察冬鳞鱼人。我伪装成他们的模样，保持着一定的距离，记录鱼人的日常生活情况。$B$B没过多久，一切都改变了。$B$B考达拉的一场地震引发山崩，附近的洞穴都露了出来。居住在洞穴中的龙虾人开始偷窃冬鳞蝌蚪。鱼人们试图拯救他们的后代，但是一旦他们进入洞穴，就像被转换了心智似的，沦为了龙虾人的走狗。$B$B那些尚未堕落的鱼人撤退到这里，我勉为其难地成为了他们的首领。', `MaleText_loc5`='我最近來這觀察冬鰭魚人。我打扮的跟他們一樣，和他們保持距離，記載著他們的日常生活。$B$B可是，在我到這不久以後，一切都變了。$B$B凜懼島發生的地震造成了坍方，附近的洞窟因此暴露出來。從裡面跑出一隻龍蝦人，偷走了冬鰭魚人的蝌蚪。然後，魚人進去洞窟解救他們的小寶寶，他們再度現身時，全身發著光，受到了龍蝦人的影響。$B$B如今，未受影響的魚人撤退到這裡，我則心不甘情不願的成了他們的領導者。', `MaleText_loc7`='Hace poco vine aquí para estudiar a los múrlocs Aleta Invernal. Disfrazado como uno de ellos, mantuve las distancias y tomé notas sobre su vida diaria.$B$BSin embargo, poco después de mi llegada todo cambió.$B$BUn terremoto en Gelidar causó un corrimiento de tierras que dejó al descubierto las cavernas cercanas. De ahí salió un extraño makrura que robó los renacuajos de los Aleta Invernal. Cuando los múrlocs entraron en las cavernas para recuperar a sus crías, volvieron a salir brillando y bajo la influencia del makrura.$B$BAhora los que no han sido afectados se han refugiado aquí y yo he tomado el mando a regañadientes.' WHERE `ID`=24379;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멀록왕 아옳아옳, 미안하지만 당신의 멀록 위장복을 잃어버린 것 같습니다.', `MaleText_loc4`='姆嘎姆嘎国王，我弄丢了你的备用鱼人服。对不起。', `MaleText_loc5`='莫戈莫戈大王，我一不小心把你的備用服裝弄不見了，對不起喔。', `MaleText_loc7`='Rey Mrgl-Mrgl, he perdido su disfraz de múrloc. Lo siento.', `FemaleText_loc1`='멀록왕 아옳아옳, 미안하지만 당신의 멀록 위장복을 잃어버린 것 같습니다.', `FemaleText_loc4`='姆嘎姆嘎国王，我弄丢了你的备用鱼人服。对不起。', `FemaleText_loc5`='莫戈莫戈大王，我一不小心把你的備用服裝弄不見了，對不起喔。', `FemaleText_loc7`='Rey Mrgl-Mrgl, he perdido su disfraz de múrloc. Lo siento.' WHERE `ID`=24380;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='걱정하지 마십시오. 그대가 잃어버린 장비를 채집꾼 하나가 찾아왔으니까요.$B$B자, 여기 있습니다만, 좀 조심해 주셨으면 좋겠습니다. 클랙시무스에게 가까이 다가가려고 쓸데없이 겨울지느러미 멀록을 해치는 일은 없었으면 하니까요.', `MaleText_loc4`='别担心，$n。我们帮你找到了那件意外丢失的鱼人服。$B$B喏，拿好了，千万要小心哦。再搞丢的话，你还得消灭更多的冬鳞鱼人才能杀回克拉西姆斯的巢穴。我可不愿意让你再费这么大劲。', `MaleText_loc5`='別擔心，$n，收集者在你不小心弄丟的地方找到了服裝。$B$B喏，拿去，但是多加小心。我不願見到你一路打進克拉希穆司，並且沿路殺死無辜的冬鰭魚人。', `MaleText_loc7`='No te preocupes, $n, uno de los recolectores encontró el disfraz donde tú lo perdiste por accidente.$B$BTómalo, pero ten más cuidado. No me gustaría que tuvieras que abrirte camino hasta Claximus y matar más múrlocs Aleta Invernal innecesariamente.' WHERE `ID`=24381;
