UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 형제자매가 모두 미쳐버렸어! 여기서 나가게 도와줄 수 있어?', `MaleText_loc4`='我的兄弟姐妹都发疯了！你能帮我逃离这里吗？', `MaleText_loc5`='我的兄弟姊妹都發瘋了!你覺得能幫我逃離這裡嗎?', `MaleText_loc7`='¡Mis hermanos y hermanas se han vuelto locos! ¿Crees que puedes ayudarme a salir de aquí?' WHERE `ID`=24388;
