UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 말을 알아들을 수 있나요? 난 당신 말을 알아들을 수 있어요!', `MaleText_loc4`='你能听懂我说的话？我能听懂你说的！', `MaleText_loc5`='你聽得懂我說的話?我聽得懂你說的話耶!', `MaleText_loc7`='¿Tú puedes entenderme? ¡Yo puedo entenderte!' WHERE `ID`=24391;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$R 양반, 내가 왜 당신과 얘기해야 하죠? 이런 사태가 일어난 것도 다 당신들 책임일 텐데!', `MaleText_loc4`='$R，我为什么要和你说话？这堆烂摊子很可能就是拜你们所赐！', `MaleText_loc5`='$R，為什麼我要跟你說話?也許是你的族人先造成這場騷動的!', `MaleText_loc7`='$R, ¿por qué iba a querer hablar contigo? ¡Probablemente fue tu gente la que provocó este desastre!' WHERE `ID`=24392;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 조개도 채집해야 하고, 범고래도 잡아야 합니다. 도와줄 게 아니면 저리 가세요!', `MaleText_loc4`='我们要忙着收集贝壳和消灭逆戟鲸呢。你要么来帮忙，要么就别挡路！', `MaleText_loc5`='還有很多的蚌殼要撿，很多的虎鯨要殺。要不就幫忙，否則別擋路!', `MaleText_loc7`='Hay almejas que recoger y orcas que matar. ¡Ayuda o apártate!' WHERE `ID`=24393;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='블러글그르 무르브르글... 장난이에요. 난 당신 말을 알아들을 수 있어요.', `MaleText_loc4`='Blurglgr murbrgl……开个玩笑，我能听懂你的话。', `MaleText_loc5`='哺嚕咕嚕咕嚕 姆哺嚕咕嚕...開玩笑的啦，我聽得懂你說什麼。', `MaleText_loc7`='Blurglgr murbrgl... es broma. Te entiendo.' WHERE `ID`=24394;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마을에 있던 우리 형제자매들이 왜 미쳐버렸는지 아직 알아내지 못하셨나요?', `MaleText_loc4`='你查明村落里的鱼人发狂的原因了吗？', `MaleText_loc5`='你找出為什麼村子裡的兄弟姊妹都發瘋了嗎?', `MaleText_loc7`='¿Ya has averiguado por qué se han vuelto locos nuestros hermanos y hermanas del poblado?' WHERE `ID`=24395;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 동굴에 들어가면 안 되는 줄 알고 있었어요. 거긴 이상한 곳이라고요!', `MaleText_loc4`='我就知道我们不应该进入洞穴。那里的状况太异常了！', `MaleText_loc5`='我就知道我們不該進去那座洞窟的。那一點也不自然!', `MaleText_loc7`='Sabía que no deberíamos haber entrado en esas cuevas. ¡No es natural!' WHERE `ID`=24396;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새로운 멀록왕 아옳아옳에게는 뭔가 수상쩍은 점이 있어. 하지만, 그게 정확히 뭔지는 모르겠단 말이지.', `MaleText_loc4`='总觉得新国王姆嘎姆嘎有什么地方不对劲，但是又说不上来是哪儿有问题', `MaleText_loc5`='那個新國王莫戈莫戈有點可疑，但是我指不出來哪裡怪。', `MaleText_loc7`='Algo me huele a chamusquina en el nuevo rey Mrgl-Mrgl, pero no consigo averiguar el qué.' WHERE `ID`=24397;
