UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대단하군. 월급은 얼마나 준대?', `MaleText_loc4`='啧啧，他们给他什么报酬？', `MaleText_loc5`='哇，那他們薪水怎麼樣?', `MaleText_loc7`='Guau, ¿cuánto pagan?', `FemaleText_loc1`='대단하군. 월급은 얼마나 준대?', `FemaleText_loc4`='啧啧，他们给他什么报酬？', `FemaleText_loc5`='哇，那他們薪水怎麼樣?', `FemaleText_loc7`='Guau, ¿cuánto pagan?' WHERE `ID`=24408;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='월급은 무슨... 한 푼도 안 준다더군.', `MaleText_loc4`='报酬？哦，他们并不给他任何报酬。', `MaleText_loc5`='薪水?嗯，他們一毛也沒付。', `MaleText_loc7`='¿Pagar? Bueno, no pagan nada.', `FemaleText_loc1`='월급은 무슨... 한 푼도 안 준다더군.', `FemaleText_loc4`='报酬？哦，他们并不给他任何报酬。', `FemaleText_loc5`='薪水?嗯，他們一毛也沒付。', `FemaleText_loc7`='¿Pagar? Bueno, no pagan nada.' WHERE `ID`=24409;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐? 그럼 거긴 뭐 하러 들어간 거야?', `MaleText_loc4`='什么？那他为什么做这种傻事？', `MaleText_loc5`='什麼?他為什麼做這種蠢事?', `MaleText_loc7`='¿Qué? ¿Por qué haría una cosa tan absurda?', `FemaleText_loc1`='뭐라고? 그럼 거긴 뭐 하러 들어간 거래?', `FemaleText_loc4`='什么？那他为什么做这种傻事？', `FemaleText_loc5`='什麼?他為什麼做這種蠢事?', `FemaleText_loc7`='¿Qué? ¿Por qué haría una cosa tan absurda?' WHERE `ID`=24410;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='몰라. 종족의 생존이라느니, 미래상이라느니, 영웅적인 업적이라느니 주절대긴 하는데 도대체 무슨 소리를 하는 건지 모르겠어.', `MaleText_loc4`='我不知道，也许是为了种族的生存，未来的愿景，英勇的事迹之类的东西吧。', `MaleText_loc5`='我不知道，種族的存續、未來的預言、高貴的情操，諸如此類的。', `MaleText_loc7`='No lo sé, supervivencia de su raza, planes de futuro, valientes hazañas, blah, blah, blah.', `FemaleText_loc1`='몰라. 종족의 생존이라느니, 미래상이라느니, 영웅적인 업적이라느니 주절대긴 하는데 도대체 무슨 소리를 하는 건지...', `FemaleText_loc4`='我不知道，也许是为了种族的生存，未来的愿景，英勇的事迹之类的东西吧。', `FemaleText_loc5`='我不知道，種族的存續、未來的預言、高貴的情操，諸如此類的。', `FemaleText_loc7`='No lo sé, supervivencia de su raza, planes de futuro, valientes hazañas, blah, blah, blah.' WHERE `ID`=24411;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='썩은 매타조알 같은 소리하고 있군그래.', `MaleText_loc4`='对我来说这些东西就好似一堆腐烂的陆行鸟蛋一样。', `MaleText_loc5`='聽起好像一堆爛掉的陸行鷹蛋。', `MaleText_loc7`='A mí me suena igual que un montón de huevos de Halcón zancudo podridos.', `FemaleText_loc1`='썩은 매타조알 같은 소리하고 있군.', `FemaleText_loc4`='对我来说这些东西就好似一堆腐烂的陆行鸟蛋一样。', `FemaleText_loc5`='聽起好像一堆爛掉的陸行鷹蛋。', `FemaleText_loc7`='A mí me suena igual que un montón de huevos de Halcón zancudo podridos.' WHERE `ID`=24412;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 아니래. 나라면 도저히 못 할 거야. 여기 월급으로도 충분한걸.', `MaleText_loc4`='是啊，我是永远都不会做这种傻事的。这里的报酬真不错。', `MaleText_loc5`='是呀，我才不會幹這種事。這裡的薪水太棒了。', `MaleText_loc7`='Sí, yo nunca podría hacer eso. El sueldo es demasiado bueno aquí.', `FemaleText_loc1`='누가 아니래. 나라면 도저히 못 할 거야. 여기 월급으로도 충분한걸.', `FemaleText_loc4`='是啊，我是永远都不会做这种傻事的。这里的报酬真不错。', `FemaleText_loc5`='是呀，我才不會幹這種事。這裡的薪水太棒了。', `FemaleText_loc7`='Sí, yo nunca podría hacer eso. El sueldo es demasiado bueno aquí.' WHERE `ID`=24413;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맞아. 난 다음 달쯤 제대해서 아제로스 해안에 사 놓은 땅에 내려가서 지냈으면 좋겠어.', `MaleText_loc4`='是啊，我希望下个月就能退休。我在艾泽拉斯海岸边买下了一块地皮，希望能去那里安度晚年。', `MaleText_loc5`='對呀。我希望下個月可以撤退，然後在艾澤拉斯的海岸買下一片土地。', `MaleText_loc7`='Sí. Espero jubilarme el mes que viene y mudarme a una pequeña extensión de tierra que compré en la costa de Azeroth.', `FemaleText_loc1`='맞아. 난 다음 달쯤 제대해서 아제로스 해안에 사 놓은 땅에 내려가서 지냈으면 좋겠어.', `FemaleText_loc4`='是啊，我希望下个月就能退休。我在艾泽拉斯海岸边买下了一块地皮，希望能去那里安度晚年。', `FemaleText_loc5`='對呀。我希望下個月可以撤退，然後在艾澤拉斯的海岸買下一片土地。', `FemaleText_loc7`='Sí. Espero jubilarme el mes que viene y mudarme a una pequeña extensión de tierra que compré en la costa de Azeroth.' WHERE `ID`=24414;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멋지군. 인생이 바로 그런 거지...', `MaleText_loc4`='太棒了。这才是生活……', `MaleText_loc5`='真棒。這才是人生...', `MaleText_loc7`='Genial. Eso es vida...', `FemaleText_loc1`='멋진데. 인생이 바로 그런 거 아니겠어...', `FemaleText_loc4`='太棒了。这才是生活……', `FemaleText_loc5`='真棒。這才是人生...', `FemaleText_loc7`='Genial. Eso es vida...' WHERE `ID`=24415;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='캘타스 왕자님께서 태양샘을 다시 가동하려면 얼마나 걸리지?', `MaleText_loc4`='凯尔萨斯大人重新激活太阳井还要多久？', `MaleText_loc5`='凱爾薩斯大人還要多久才會重新點燃太陽之井?', `MaleText_loc7`='¿Cuánto falta para que Lord Kael''thas reactive La Fuente del Sol?', `FemaleText_loc1`='캘타스 왕자님께서 태양샘을 다시 가동하려면 얼마나 걸릴까?', `FemaleText_loc4`='凯尔萨斯大人重新激活太阳井还要多久？', `FemaleText_loc5`='凱爾薩斯大人還要多久才會重新點燃太陽之井?', `FemaleText_loc7`='¿Cuánto falta para que Lord Kael''thas reactive La Fuente del Sol?' WHERE `ID`=24416;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='금방 되겠지. 아웃랜드 최고의 마법사들을 모아 소환을 돕게 할 거라고 하던데...', `MaleText_loc4`='很快。我听说他聚集了外域所有最强大的法师来帮他召唤。', `MaleText_loc5`='快了。我聽說他召集了外域所有最強大的施法者來協助召喚儀式。', `MaleText_loc7`='Pronto. He oído que ha reunido a los taumaturgos más poderosos de Terrallende para que le ayuden a realizar la invocación.', `FemaleText_loc1`='금방 되겠지. 아웃랜드 최고의 마법사들을 모아 소환을 돕게 할 거라고 하니 말이야.', `FemaleText_loc4`='很快。我听说他聚集了外域所有最强大的法师来帮他召唤。', `FemaleText_loc5`='快了。我聽說他召集了外域所有最強大的施法者來協助召喚儀式。', `FemaleText_loc7`='Pronto. He oído que ha reunido a los taumaturgos más poderosos de Terrallende para que le ayuden a realizar la invocación.' WHERE `ID`=24417;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='솔직히 말해 신도레이야말로 가장 위대한 종족이야.', `MaleText_loc4`='的确，辛多雷是最伟大的种族。', `MaleText_loc5`='是的，辛多雷是最偉大的人種。', `MaleText_loc7`='Cierto, los sin''dorei son la mejor raza de todas.', `FemaleText_loc1`='솔직히 말해 신도레이야말로 가장 위대한 종족이야.', `FemaleText_loc4`='的确，辛多雷是最伟大的种族。', `FemaleText_loc5`='是的，辛多雷是最偉大的人種。', `FemaleText_loc7`='Cierto, los sin''dorei son la mejor raza de todas.' WHERE `ID`=24418;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맞아. 우리는 이 육체의 덫을 벗어 던지고 살게라스가 먼 옛날에 약속한 힘을 얻어야 해.', `MaleText_loc4`='是啊，我们将会升华到一个新的高度，并得到萨格拉斯很久以前就承诺给我们的力量。', `MaleText_loc5`='是呀，我們應該不需要再受限於凡人的肉體，而獲得薩格拉斯很久以前就承諾的力量。', `MaleText_loc7`='Sí, ascenderemos más allá de las vulgares ataduras de nuestra espiral de mortalidad y obtendremos el poder que Sargeras nos prometió hace tanto tiempo.', `FemaleText_loc1`='맞아. 우리는 이 육체의 덫을 벗어 던지고 살게라스가 먼 옛날에 약속한 힘을 얻어야 한다고.', `FemaleText_loc4`='是啊，我们将会升华到一个新的高度，并得到萨格拉斯很久以前就承诺给我们的力量。', `FemaleText_loc5`='是呀，我們應該不需要再受限於凡人的肉體，而獲得薩格拉斯很久以前就承諾的力量。', `FemaleText_loc7`='Sí, ascenderemos más allá de las vulgares ataduras de nuestra espiral de mortalidad y obtendremos el poder que Sargeras nos prometió hace tanto tiempo.' WHERE `ID`=24419;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='머지않아 저 어리석은 종족들이 우리의 힘을 맛보게 될 거야.', `MaleText_loc4`='这些愚蠢的凡人们很快就会见识到我们的力量。', `MaleText_loc5`='這些愚蠢的凡人種族不久之後將見識到我們的力量。', `MaleText_loc7`='Estas estúpidas razas mortales pronto verán nuestro poder.', `FemaleText_loc1`='머지않아 저 어리석은 종족들이 우리의 힘을 맛보게 되겠지.', `FemaleText_loc4`='这些愚蠢的凡人们很快就会见识到我们的力量。', `FemaleText_loc5`='這些愚蠢的凡人種族不久之後將見識到我們的力量。', `FemaleText_loc7`='Estas estúpidas razas mortales pronto verán nuestro poder.' WHERE `ID`=24420;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='캘타스 님과 불타는 군단을 위해!', `MaleText_loc4`='为了凯尔萨斯和燃烧军团！', `MaleText_loc5`='為了凱爾薩斯和燃燒軍團!', `MaleText_loc7`='¡Por Kael''thas y la Legión Ardiente!', `FemaleText_loc1`='캘타스 님과 불타는 군단을 위해!', `FemaleText_loc4`='为了凯尔萨斯和燃烧军团！', `FemaleText_loc5`='為了凱爾薩斯和燃燒軍團!', `FemaleText_loc7`='¡Por Kael''thas y la Legión Ardiente!' WHERE `ID`=24421;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='캘타스 님과 불타는 군단을 위해!', `MaleText_loc4`='为了凯尔萨斯和燃烧军团！', `MaleText_loc5`='為了凱爾薩斯和燃燒軍團!', `MaleText_loc7`='¡Por Kael''thas y la Legión!', `FemaleText_loc1`='캘타스 님과 불타는 군단을 위해!', `FemaleText_loc4`='为了凯尔萨斯和燃烧军团！', `FemaleText_loc5`='為了凱爾薩斯和燃燒軍團!', `FemaleText_loc7`='¡Por Kael''thas y la Legión!' WHERE `ID`=24422;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어둠이 불꽃을 지피리라!', `FemaleText_loc4`='火焰将在阴影中燃烧！', `FemaleText_loc5`='火焰將在陰影中燃燒!', `FemaleText_loc7`='¡Sombras para ayudar al fuego!' WHERE `ID`=24423;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사크로래쉬가 방향을 돌려 암흑 회오리를 $n에게 시전합니다.', `FemaleText_loc4`='萨洛拉丝向$n施放暗影新星。', `FemaleText_loc5`='莎珂蕾希對$n施放暗影新星。', `FemaleText_loc7`='Sacrolash dirige Nova de las Sombras hacia $n.' WHERE `ID`=24424;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌격!', `MaleText_loc4`='冲锋！', `MaleText_loc5`='衝鋒!', `MaleText_loc7`='¡Carga!' WHERE `ID`=24425;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='알리테스가 방향을 돌려 거대한 불길을 $n에게 시전합니다.', `FemaleText_loc4`='奥蕾塞丝向$n施放燃烧。', `FemaleText_loc5`='艾黎瑟絲對$n施放焚焰。', `FemaleText_loc7`='Alythess dirige Conflagración hacia $n.' WHERE `ID`=24426;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 착하지. 여기서 그냥 먹기만 하면 된단다.', `MaleText_loc4`='好孩子，好孩子。你在这里乖乖的吃吧。', `MaleText_loc5`='好女孩，乖女孩。你就待在這裡吃點東西就好。', `MaleText_loc7`='Buena chica, buena chica. Quédate aquí y come.' WHERE `ID`=24427;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='됐습니다, $n. 이제 당신은 겨울지느러미 멀록과 대화도 할 수 있고, 말뜻도 이해할 수 있습니다.', `MaleText_loc4`='$n，你已经能够与冬鳞鱼人沟通了。', `MaleText_loc5`='拿去吧，$n，現在你就能和冬鰭魚人交談，並且瞭解他們說的話。', `MaleText_loc7`='Ahí tienes, $n, ahora podrás hablar con los Aleta Invernal y entenderles.' WHERE `ID`=24428;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형제들이 깨어났다. 너희가 한 노력은 헛수고일 뿐...', `MaleText_loc4`='我的同胞已经醒了。你的努力白费了……', `MaleText_loc5`='我的弟兄們甦醒了，你們的努力也將白費...', `MaleText_loc7`='Mis hermanos se han despertado. Tus esfuerzos son en vano...' WHERE `ID`=24429;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 늦었다. 보잘것없는 존재여. 네게 닥쳐오는 안개가 느껴지느냐? 크발디르가 돌아온다...', `MaleText_loc4`='太迟了，小东西。迷雾已经逼近。克瓦迪尔回来了……', `MaleText_loc5`='小傢伙，你們現在才要獻祭太晚了。感覺到大霧逐漸逼近嗎?科瓦迪爾回來了...', `MaleText_loc7`='Tu ofrenda llega demasiado tarde, criaturita. ¿Puedes sentir la niebla que se cierne sobre ti? Los Kvaldir regresan...' WHERE `ID`=24430;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 웃습니다.', `MaleText_loc4`='%s大笑。', `MaleText_loc5`='%s大笑。', `MaleText_loc7`='%s ríe.' WHERE `ID`=24431;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바다를 보아라. 너의 파멸이 굽이치는 파도를 타고 온다.', `MaleText_loc4`='瞧瞧波涛汹涌的大海，潮水高涨的时刻就是你的末日。', `MaleText_loc5`='看著這片海洋，當潮起的時候將伴隨你的末日降臨。', `MaleText_loc7`='Mira hacia los mares, pues tu perdición se acerca con el oleaje.' WHERE `ID`=24432;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안개와 연기를 타고 크발디르가 올 것이다. 살아서 숨 쉴 수 있을 때 도망가라...', `MaleText_loc4`='克瓦迪尔从迷雾中迫近。逃跑吧，趁你还有命在，逃吧。', `MaleText_loc5`='科瓦迪爾從霧靄之中逐步進逼。趁你還能呼吸的時候快點逃跑吧...', `MaleText_loc7`='Los Kvaldir se aproximan entre la niebla y la bruma. Huid mientras aún respiráis el aire de los vivos...' WHERE `ID`=24433;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 아투이크입니다. 카마구아 칼루아크 부족 족장이지요.', `MaleText_loc4`='我是阿图伊克，卡玛古的卡鲁亚克氏族酋长。', `MaleText_loc5`='我是阿推克，卡瑪廓這裡卡魯耶克的酋長。', `MaleText_loc7`='Soy Atuik, cabecilla de los Kalu''ak de Komawa.' WHERE `ID`=24434;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='웬 쥐방울만한 녀석이 여길 들어오느냐? 멀록은 아닌 것 같은데.', `MaleText_loc4`='那边过来个什么小东西。不是鱼人吧。', `MaleText_loc5`='這一小口食物是怎麼來的?我想應該不是這魚人中的一隻。', `MaleText_loc7`='¿Un pequeño grupo se acerca? No creo que sea de múrlocs.' WHERE `ID`=24435;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$r 맛을 본 지도 꽤 오래됐군.', `MaleText_loc4`='上次品尝$r的美味已经是很久之前的事啦。', `MaleText_loc5`='自從上次嚐過$r已經很久很久囉。', `MaleText_loc7`='Ha pasado mucho tiempo desde la última vez que saboreé $r.' WHERE `ID`=24436;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 뭐지? 넌 겨울지느러미 일족이 아니다!', `MaleText_loc4`='这是什么？你不是冬鳞鱼人！', `MaleText_loc5`='這是什麼?你可不是冬鰭魚人!', `MaleText_loc7`='¿Qué es esto? Tú no eres uno de los Aleta Invernal.' WHERE `ID`=24437;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멀록왕 아옳아옳이 네놈을 보낸 거냐? 난 놈의 정체를 알고 있다!', `MaleText_loc4`='是“姆嘎姆嘎国王”派你来的？我知道他的真面目！', `MaleText_loc5`='是「莫戈莫戈大王」派你來的嗎?我知道他的真實身分!', `MaleText_loc7`='¿Te envía el rey Mrgl-Mrgl? ¡Yo sé qué es en verdad!' WHERE `ID`=24438;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이봐, 철이 거의 다 떨어져 가고 있다고! 쇠막대기 하나라도 아껴서 써야 해. 무슨 말인지 알지?', `FemaleText_loc4`='铁锭快用光了！所以一块也不能浪费，明白吗？', `FemaleText_loc5`='小夥子，我們的鐵不夠用了!不要給我看到浪費任何一塊鐵棒，聽到了沒?', `FemaleText_loc7`='¡Nos estamos quedando sin hierro, chicos! No quiero ver ni una sola barra desperdiciada, ¿me oís?' WHERE `ID`=24439;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어이! 누가 주석을 다 써버리는 거야? 아무리 내가 여자지만, 재료를 낭비하는 녀석은 가만두지 않겠어!', `FemaleText_loc4`='啊！这是谁啊，居然快把锡锭用光了？你们再浪费材料试试，别以为我是女人就不敢踢你们的屁股！', `FemaleText_loc5`='欸!誰把錫都用光了?不要以為我是娘兒們就不會因為浪費資源就痛扁你們啊!', `FemaleText_loc7`='¡Anda! ¿Quién ha usado todo el estaño? ¡No creáis que porque sea una chica no puedo patearos el culo por malgastar los materiales!' WHERE `ID`=24440;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='모두 지금까지 잘해 줬어. 앞으로 들어오는 신병도 새 칼을 받을 수 있게 해줘야지. 계속 힘내자고!', `FemaleText_loc4`='干得不错。我们还在不断招募新兵，他们还等着用新武器呢。继续加油！', `FemaleText_loc5`='到目前為止做得都不錯。新兵不斷的加入，他們也都會需要新的刀劍。繼續加油!', `FemaleText_loc7`='Buen trabajo hasta ahora. Siguen llegando reclutas y todos van a necesitar nuevas espadas. ¡Seguid así!' WHERE `ID`=24441;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아주 좋아 보이네. 잘했어.', `FemaleText_loc4`='看上去不错嘛。挺好的。', `FemaleText_loc5`='看起來不錯嘛，幹得好。', `FemaleText_loc7`='Estas tienen buena pinta. Un gran trabajo.' WHERE `ID`=24442;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나쁘진 않군. 내가 전에 가르쳐 준 방법으로 쇠를 담금질해 보도록.', `FemaleText_loc4`='还不错。下次你在回火的时候可以试试我教你的窍门。', `FemaleText_loc5`='還不賴。當你冶煉鋼鐵時，試著用用我教你的這招。', `FemaleText_loc7`='No está mal. Prueba ese truco que te enseñé cuando temples el acero.' WHERE `ID`=24443;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이건 못쓰겠군. 식히면 부서져 버릴 거야. 그냥 녹여서 포탄을 만드는 데 쓰자고.', `FemaleText_loc4`='这样不行；冷却之后金属就会变脆。把它们熔了吧，还能做成弹药用用。', `FemaleText_loc5`='這沒辦法用;它一旦冷卻下來就太脆弱了。把金屬熔掉，然後做成彈藥。', `FemaleText_loc7`='Esta no sirve, una vez que se enfríe será quebradiza. Funde el metal, lo usaremos para munición.' WHERE `ID`=24444;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='숙련된 솜씨라는 건 바로 이런 거지. 어떻게 만들었는지 나중에 보여 달라고. 약속하는 거야?', `FemaleText_loc4`='这就是技术啊！你一定要把其中的窍门告诉我。说定咯？', `FemaleText_loc5`='這才是我所謂的好手藝。你一定要讓我知道你是怎麼做的。一言為定?', `FemaleText_loc7`='Esto es lo que yo llamo artesanía. Tendrás que mostrarme cómo la has hecho. ¿Lo prometes?' WHERE `ID`=24445;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$G아빠:엄마;?', `MaleText_loc4`='$G爸爸:妈妈;？', `MaleText_loc5`='$G爸比:媽咪;?', `MaleText_loc7`='¿$G Pa-pá : Ma-má;?' WHERE `ID`=24446;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알루르글글.', `MaleText_loc4`='Alurglgl。', `MaleText_loc5`='啊嚕咕嚕。', `MaleText_loc7`='Alurglgl.' WHERE `ID`=24447;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='집에 가는 거야?', `MaleText_loc4`='我能回家了吗？', `MaleText_loc5`='我要回家嗎?', `MaleText_loc7`='¿Yo ir a casa?' WHERE `ID`=24448;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놀자!', `MaleText_loc4`='来玩吧！', `MaleText_loc5`='來玩吧!', `MaleText_loc7`='¡Jugar!' WHERE `ID`=24449;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쉿... $r, 이리 좀 와 봐! 고래 시체 옆이야.', `MaleText_loc4`='嘘……$r，就在那里！那条死鲸鱼旁边。', `MaleText_loc5`='喂...$r，我在這!死掉的鯨魚旁邊。', `MaleText_loc7`='¡Psst... $r, aquí! Junto a la ballena muerta.' WHERE `ID`=24450;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저주받을 캘타스와 악마 놈들! 우리의 노력은 수포로 돌아갔지만, 그 얼간이들은 우리가 싸움을 포기한 거로 생각하지. 이미 여군주 리아드린 님께서 우리를 위한 새로운 힘의 근원을 찾고 있소. 우리는 그렇게 쉽게 무너지지 않을 것이오.', `MaleText_loc4`='该死的凯尔萨斯和他的走狗们！我们的一切都没有了，但他们竟然愚蠢到认为我们不会反击。女伯爵莉亚德琳已经给我们找到了一种新的能量源。我们不会坐以待毙。', `MaleText_loc5`='凱爾薩斯和他的魔化血精靈真該死!我們過去所做的努力已經毀於一旦，若他們認為我們不會還手的話就是蠢蛋。在這之前，莉雅德倫女士已經替我們找到新的能量來源。我們才不會如此容易就被打倒。', `MaleText_loc7`='¡Malditos sean Kael''thas y sus sangrevil! Han destruido todo por lo que hemos trabajado, pero están locos si creen que no contraatacaremos. Por el momento, Lady Liadrin busca una nueva fuente de poder para nuestra orden. No nos destruirán tan fácilmente.' WHERE `ID`=24451;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='알리테스! 네 불꽃은 내 안에 살아 있어!', `FemaleText_loc4`='奥蕾塞丝！你的火焰会在我心中燃烧下去！', `FemaleText_loc5`='艾黎瑟絲!你的火焰會在我的心中燃燒下去!', `FemaleText_loc7`='¡Alythess! ¡Tu fuego arde dentro de mí!' WHERE `ID`=24452;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<주변의 소동에 불안한 기색을 보이는 용매>', `MaleText_loc4`='<龙鹰似乎由于附近的骚动而变得狂乱起来。>', `MaleText_loc5`='<龍鷹似乎因為周遭的騷動而感到不安。>', `MaleText_loc7`='<La conmoción que le rodea parece inquietar al dracohalcón.>' WHERE `ID`=24453;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도로 닫아!', `MaleText_loc4`='就差一点！', `MaleText_loc5`='關閉!', `MaleText_loc7`='¡Cierra!' WHERE `ID`=24454;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엄마가 그랬는데, 모르는 멀록은 따라가지 말래!', `MaleText_loc4`='才不要跟陌生人走！', `MaleText_loc5`='別跟著陌生人走!', `MaleText_loc7`='¡No ir con extraños!' WHERE `ID`=24455;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으우우... $R|1이잖아;잖아;!', `MaleText_loc4`='呃……$r！', `MaleText_loc5`='哎唷...$r!', `MaleText_loc7`='¡Puagh... $r!' WHERE `ID`=24456;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$G아빠:엄마;가 아니잖아!', `MaleText_loc4`='你不是我的$g爸爸:妈妈;！', `MaleText_loc5`='你不是$G爸比:媽咪;!', `MaleText_loc7`='¡Tú no $g pa-pá : ma-má;!' WHERE `ID`=24457;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오그리마를 파괴한 행위는 그냥 오크를 공격한 것이 아니라 호드 전체를 모욕한 거나 다름없네. 호드라는 존재 자체를 위협하는 공격이지!$B$B리치 왕은 공포가 싹트도록 씨앗을 심으려 했네.$B$B이 요새...$B$B<주변에 있는 요새의 벽을 가리키는 가로쉬>$B$B아서스가 벌인 전쟁 때문에 이런 요새까지 만들었네.$B$B호드는 아무것도 두려워하지 않네...', `MaleText_loc4`='对奥格瑞玛的攻击不仅是向兽人宣战，更是对部落的冒犯。这是对我们的侮辱！$B$B巫妖王企图散播恐惧的种子。$B$B这些……$B$B<加尔鲁什指着他周围的防御工事。>$B$B这就是阿尔萨斯一役的战果。$B$B部落决不退缩……', `MaleText_loc5`='夷平奧格瑪不僅是對獸人發動攻擊而已，更是對部落公然挑釁，危害到我們的生存!$B$B巫妖王企圖播下恐懼的種子。$B$B而這些...$b$b<卡爾洛斯指著他四周強化過的圍牆。>$B$B這就是阿薩斯戰役的結果。$B$B部落一無所懼...', `MaleText_loc7`='Al arrasar Orgrimmar no solo atacaron a los orcos, sino a toda la Horda. ¡Fue un ataque contra nuestra existencia!$B$BEl Rey Exánime pretendía sembrar el miedo.$B$BEsto...$B$B<Garrosh señala hacia las paredes fortificadas que le rodean.>$B$BEsto es el resultado de la campaña de Arthas.$B$BLa Horda no teme a nada...' WHERE `ID`=24458;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용매를 타고 태양너울까지 이동합니다.', `MaleText_loc4`='<骑上龙鹰前往阳湾港。>', `MaleText_loc5`='<騎乘著龍鷹前往日境。>', `MaleText_loc7`='<Ve hasta Tramo del Sol en el dracohalcón.>', `FemaleText_loc1`='용매를 타고 태양너울까지 이동합니다.', `FemaleText_loc4`='<骑上龙鹰前往阳湾港。>', `FemaleText_loc5`='<騎乘著龍鷹前往日境。>', `FemaleText_loc7`='<Ve hasta Tramo del Sol en el dracohalcón.>' WHERE `ID`=24459;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 부하가 아니렷다. 멀록왕 아옳아옳이 내게서 항복을 받아내라고 네놈을 보냈겠지. 네놈을 더 잘 볼 수 있게 가까이 와라.', `MaleText_loc4`='你不是我们的同胞。是姆嘎姆嘎国王派你谈判投降条件的吧。走近一些，让我好好看看你。', `MaleText_loc5`='你不是我族的人。莫戈莫戈大王一定是派你來談談合解的條件。靠近點好讓我看清楚你。', `MaleText_loc7`='No eres uno de los míos. Supongo que el rey Mrgl-Mrgl te envía para hablar sobre las condiciones de la rendición. Acércate para que pueda verte mejor.' WHERE `ID`=24460;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 비열한 여군주 리아드린 때문에 당신께서 괴로워하십니까? 그녀와 추종자들은 빛을 왜곡하고 우리가 지켜낸 가치를 흉내 내고 있을 뿐입니다!', `MaleText_loc4`='您为什么能允许这个卑鄙的女伯爵莉亚德琳前来谒见？她和她的手下扭曲了圣光，还取笑我们所坚持的一切！', `MaleText_loc5`='為什麼你會因為那個卑劣的莉雅德倫女士出現而痛苦?她和她的追隨者曲解了聖光，而且嘲弄我們所竭力支持的一切!', `MaleText_loc7`='¿Por qué sufres la presencia de esa despreciable Lady Liadrin? ¡Ella y sus seguidores distorsionan la Luz y se burlan de todo lo que defendemos!' WHERE `ID`=24461;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정하시게, 장군. 빛은 믿음을 가지고 샤트라스에 들어오는 모든 이들을 환영한다오.', `MaleText_loc4`='容忍，将军。圣光善待所有心怀虔诚的信念来到沙塔斯城的访客。', `MaleText_loc5`='耐心點，將軍。聖光會擁抱每一個進入撒塔斯的虔誠信徒。', `MaleText_loc7`='Paciencia, general. La Luz abraza a todos aquellos que entran en Shattrath con buenas intenciones.' WHERE `ID`=24462;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샤트라스에 온 걸 환영하오, 여군주 리아드린. 그대가 오기만을 오랫동안 기다렸소이다.', `MaleText_loc4`='欢迎来到沙塔斯城，女伯爵莉亚德琳。我们在这里等你很久了。', `MaleText_loc5`='歡迎你來到撒塔斯，莉雅德倫女士。我們誠心期盼著你的到來。', `MaleText_loc7`='Bienvenida a Shattrath, Lady Liadrin. Llevábamos tiempo esperando tu llegada.' WHERE `ID`=24463;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='얘기할 기회를 주셔서 감사합니다, 아달. 우리가 므우루에게 한 짓 때문에 그대의 여러 동맹이 나와 내 기사들을 멸시한다는 걸 압니다.', `FemaleText_loc4`='阿达尔，感谢您能给我这么一个说话的机会。我知道您的支持者们大多都厌恶我和我的手下对待穆鲁的方式。', `FemaleText_loc5`='感謝你讓我說出心中的話，阿達歐。我知道你的許多盟友們都鄙視我和我的騎士們對待莫魯的行徑。', `FemaleText_loc7`='Gracias por permitirme hablar con A''dal. Sé que muchos de tus aliados nos odian a mí y a mis caballeros por el trato que dimos a M''uru.' WHERE `ID`=24464;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='난 우리가 잘못된 길을 선택했다는 걸 깨달았습니다. 우린 우리가 왕자라고 부르던 자에게 배신당한 겁니다. 힘을 갈망한 나머지 그는 악마들을 보내 우리를 공격하더니 태양샘으로 므우루를 데려갔습니다.', `FemaleText_loc4`='但我认识到我们走上了一条错误的道路。那个被我们称为王子的男人背叛了我们。因为他对力量的渴望，他派出了魔血精灵攻击我们，还把穆鲁带去了太阳之井。', `FemaleText_loc5`='我已經了解到我們的道路是錯誤的了。我們被我們稱之為王子的人背叛。在他對權力的強烈欲望下，他派遣了魔化血精靈前來攻擊我們，並且偷偷地將莫魯帶到了太陽之井。', `FemaleText_loc7`='Me he dado cuenta de que seguíamos un camino equivocado. Fuimos traicionados por el hombre al que llamábamos nuestro Príncipe. En su sed de poder, envió a los sangrevil a atacarnos y a llevarse a M''uru a La Fuente del Sol como por arte de magia.' WHERE `ID`=24465;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대와 우리 백성들 모두 캘타스와 그 부하들에게 큰 고통을 받았소, 여군주여. 그대의 기사단은 스스로 운명을 결정할 수는 없었지만, 그대로 있다면 결국 죽게 될 것이오.', `MaleText_loc4`='女伯爵莉亚德琳，我们的人民都遭受着凯尔萨斯和他的手下所带来的巨大痛苦。你的人民并不应该为他们曾做过的事情负责，但是如果不做出改变的话，他们必将因此灭亡。', `MaleText_loc5`='我們兩方的人民都受過凱爾薩斯之手及其密探的荼毒，莉雅德倫女士。你的人民過去無法主導他們自身的命運，但要是他們不改變的話，他們都將會死。', `MaleText_loc7`='Nuestros pueblos han sufrido mucho a manos de Kael''thas y sus seguidores, Lady Liadrin. Tu pueblo no fue culpable de su propio destino, pero morirá si no cambia.' WHERE `ID`=24466;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='므우루는 이미 오래전에 자신이 가야 할 길을 받아들였소. 그가 처할 운명을 알면서도 말이오. 그대도 그대의 역할을 받아들일 수 있겠소?', `MaleText_loc4`='穆鲁很久以前就理解了他的角色，他很清楚在他身上会发生些什么。你理解你自己的角色吗？', `MaleText_loc5`='莫魯很久前就接受了他在此事中的角色，全程了解會發生在他身上的事情。你可以接受你自己的部份嗎?', `MaleText_loc7`='M''uru aceptó su papel hace mucho y sabía perfectamente lo que le pasaría. ¿Aceptarás tú el tuyo?' WHERE `ID`=24467;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='도... 도저히 이해할 수 없군요. 그대와 므우루는 이 모든 일이 일어나리라는 걸 알았단 말입니까?', `FemaleText_loc4`='我……我不明白。您——和穆鲁——很久以前就知道会发生这一切？', `FemaleText_loc5`='我...我不明白。你 -- 和莫魯 -- 全都知道這件事會發生?', `FemaleText_loc7`='No… no entiendo. ¿Tú y M''uru sabíais desde el principio que esto iba a ocurrir?' WHERE `ID`=24468;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 상황을 예견한 자는 내가 아니라 벨렌이었소이다.', `MaleText_loc4`='并不是我预言了这一切，而是德莱尼人的领袖维伦：', `MaleText_loc5`='做出預言的人並不是我，而是身為德萊尼的費倫:', `MaleText_loc7`='No fui yo quien lo presagió, sino Velen de los draenei:' WHERE `ID`=24469;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='''은빛 달이 피에 씻기고,''', `MaleText_loc4`='“银月之城，充满鲜血与死亡。”', `MaleText_loc5`='「銀色之月，浸染於血中，」', `MaleText_loc7`='''Luna argentea, en sangre bañada,''' WHERE `ID`=24470;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='''부서진 빛의 검을 들고 어두운 밤을 헤매네.''', `MaleText_loc4`='“误入夜晚的歧途，役使破碎的圣光。”', `MaleText_loc5`='「引領外道者進入黑夜，手持著破碎的聖光之劍。」', `MaleText_loc7`='''En la noche extraviada, con una espada de Luz quebrada armada.''' WHERE `ID`=24471;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='''부서지고 배신당한 채, 태양을 지배하며 서 있을 뿐.''', `MaleText_loc4`='“饱经磨难，叛徒突现，遮蔽太阳的光芒。”', `MaleText_loc5`='「破碎，繼而被追逐太陽之者所背離。」', `MaleText_loc7`='''Rota, por uno traicionada, sobre el sol a horcajadas.''' WHERE `ID`=24472;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='''칠흑 같은 밤, 피에 맹세할 때 여기사는 구원을 받으리라.''', `MaleText_loc4`='“在最黑暗的时刻，以鲜血铭誓的女伯爵挺身而出，救赎之路重显。”', `MaleText_loc5`='「在最黑暗之時，救贖降臨，英勇的女士以血立下誓言。」', `MaleText_loc7`='''En la hora más oscura llega la redención, como una dama que en sangre ha jurado.''' WHERE `ID`=24473;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 알겠군요. 선스트라이더 가문과 가짜 왕자에 대한 내 충성을 거두어야겠습니다.', `FemaleText_loc4`='我现在都明白了。从现在起，我不再效忠于逐日者家族的那个背信弃义的王子。', `FemaleText_loc5`='我現在看清了。我拋棄我對逐日者議會及其假冒王子的忠誠。', `FemaleText_loc7`='Ahora lo veo claro. Retiro mi lealtad a la estirpe Caminante del Sol y a su falso Príncipe.' WHERE `ID`=24474;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최전방으로 가기 전에 마지막으로 한 잔 더 하고 싶은데, 괜찮겠나?', `MaleText_loc4`='在上前线之前，让我们再喝一杯吧？', `MaleText_loc5`='去前線之前，再喝一杯吧?', `MaleText_loc7`='¿Un último trago antes de ir al frente?' WHERE `ID`=24475;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론이지. 안 될 게 뭐 있나?', `MaleText_loc4`='当然好，为什么不呢？', `MaleText_loc5`='那當然，有何不可?', `MaleText_loc7`='Claro, ¿por qué no?' WHERE `ID`=24476;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 혈기사단이 그대와 함께 싸우겠습니다, 아달.', `FemaleText_loc4`='我们会和您并肩战斗，阿达尔。', `FemaleText_loc5`='我們將會與你並肩作戰，阿達歐。', `FemaleText_loc7`='Lucharemos junto a ti, A''dal.' WHERE `ID`=24477;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인장! 제일 독한 맥주로 주시오. 우린 최전방으로 떠날 거라오.', `MaleText_loc4`='老板！把你们最烈的麦酒拿上来。我们就要上前线了。', `MaleText_loc5`='酒吧老闆!把你最烈的酒送上來。我們要上前線打仗啦。', `MaleText_loc7`='¡Camarero! Trae la cerveza más fuerte que tengas. Nos vamos al frente.' WHERE `ID`=24478;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인장, 융통성 좀 발휘해 줄 수 없소? 우리 얼굴 다시 못 볼지도 모르잖소.', `MaleText_loc4`='你不会收我们的酒钱，对吧？我们可能回不来了。', `MaleText_loc5`='你真的為了我們破例了，對吧?我們也許回不來了。', `MaleText_loc7`='Harás una excepción por nosotros, ¿verdad? Puede que no volvamos.' WHERE `ID`=24479;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대의 기사단이 합세한다면 무너진 태양 공격대는 틀림없이 강해질 것이오, 여군주 리아드린이여.', `MaleText_loc4`='破碎残阳肯定会因为骑士们的加入而更加强大，女伯爵莉亚德琳。', `MaleText_loc5`='你的騎士增援當然會對破碎之日進攻部隊有所幫助，莉雅德倫女士。', `MaleText_loc7`='La Ofensiva Sol Devastado sabrá aprovechar la unión de tus caballeros, Lady Liadrin.' WHERE `ID`=24480;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='태양샘 전투는 그대가 새로 내디딜 첫 걸음이 될 것이오, 리아드린이여. 샤트라스는 그대와 그대를 따르는 모든 이들에게 열려 있소.', `MaleText_loc4`='太阳之井战役是你的崭新开始，女伯爵莉亚德琳。沙塔斯城欢迎你和你的追随者们。', `MaleText_loc5`='太陽之井一役不過是你新道路的第一步，莉雅德倫女士。撒塔斯永遠都為你敞開大門，並全體跟隨著你。', `MaleText_loc7`='La batalla por La Fuente del Sol no es más que el primer paso en tu nuevo camino, Lady Liadrin. Shattrath está abierta para ti y para tus seguidores.' WHERE `ID`=24481;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 이걸로 끝이로군. 그만 가지.', `MaleText_loc4`='那就这样吧。我们走了。', `MaleText_loc5`='我猜時候到了。我們走吧。', `MaleText_loc7`='Creo que eso es todo. Allá vamos.' WHERE `ID`=24482;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='윽, 지금까지 마셔본 것 중에 제일 맛없는 맥주였어.', `MaleText_loc4`='从没喝过那么差劲的啤酒。', `MaleText_loc5`='這是我喝過最難喝的啤酒。', `MaleText_loc7`='Es la peor cerveza que he probado nunca.' WHERE `ID`=24483;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='킬제덴을 제거하고 실버문을 다시 일으킬 것을 내 혈기사들의 칼에 맹세하겠습니다.', `FemaleText_loc4`='我以血骑士的佩剑起誓，击败基尔加丹，恢复银月城昔日的辉煌。', `FemaleText_loc5`='我保證我的血騎士團會打敗基爾加丹並重建銀月。', `FemaleText_loc7`='Prometo que los filos de mis Caballeros de sangre lucharán por la derrota de Kil''jaeden y la restauración de Lunargenta.' WHERE `ID`=24484;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='캘타스 ''왕자''가 그를 우리에게 넘겼을 때, 우리는 그의 힘이 새로운 시대로 우릴 이끌 것이라 여겼습니다.', `FemaleText_loc4`='当他还是我们所敬仰的凯尔萨斯王子时，我们以为他的力量能引领我们的人民进入一个崭新的时代。', `FemaleText_loc5`='當他被凱爾薩斯「王子」送給我們時，我們相信他的力量可以幫助我們引領我們的人民進入一個新的時代。', `FemaleText_loc7`='Cuando el ''príncipe'' Kael''thas nos lo entregó, creímos que su poder nos ayudaría a guiar a nuestra gente hacia una nueva era.' WHERE `ID`=24485;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 포위당했네... 적이 사방에서 밀려오고 있네, 젊은 헬스크림이여.', `MaleText_loc4`='我们被包围了……加尔鲁什，敌人正从四面八方涌来。', `MaleText_loc5`='我們被包圍了...年輕的地獄吼，我們的敵人從四面八方湧入。', `MaleText_loc7`='Estamos rodeados… Nuestros enemigos presionan desde todos los lados, joven Grito Infernal.' WHERE `ID`=24486;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스컬지 놈들이 개떼처럼 북쪽에서부터 내려오는 중이네.', `MaleText_loc4`='天灾军团如蝗虫一般挥师北下。', `MaleText_loc5`='天譴軍就像是蝗蟲一樣由北邊從天而降。', `MaleText_loc7`='La Plaga desciende desde el norte como si fueran langostas.' WHERE `ID`=24487;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스가 이 지역으로 안전하게 수송하는 길은 단 하나뿐이네. 게다가 그마저도 저 무시무시한 안개 때문에 놓칠 위험에 처해 있지.', `MaleText_loc4`='联盟控制着这个地区唯一一条安全的航道，即便如此，这条航道也面临着随时被致命的迷雾吞噬的危险。', `MaleText_loc5`='聯盟掐住了這個區域唯一的運輸路線，即便是這樣，他們也得冒著在這片駭人大霧中迷失方向的危險。', `MaleText_loc7`='La Alianza controla la única ruta marítima segura de esta región y eso también podría perderse entre estas temibles brumas.' WHERE `ID`=24488;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='재보급을 받을 수 있는 유일한 항구는 이 저주받은 대륙 반대편에 있는데, 그나마도 포세이큰이 장악했네!', `MaleText_loc4`='唯一能够正常运转的补给港口位于这片大陆的另一端，在被遗忘者手中！', `MaleText_loc5`='在這個該死的大陸另外一頭，我們唯一可用的補給港口，被遺忘者已經把它控制住了!', `MaleText_loc7`='El único puerto en el que podemos reabastecernos está al otro lado de este maldito continente y bajo el control de los Renegados.' WHERE `ID`=24489;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비행선으로 운반할 수 없는 물자는 여기까지 오려면 배로 길고 긴 노스렌드를 지나야 하네.', `MaleText_loc4`='无法用地精飞艇运送的物资必须通过航运，横穿整个诺森德才能到我们这里。', `MaleText_loc5`='任何飛艇載不動的東西都得用船運，長途跋涉前往北裂境才能到我們這。', `MaleText_loc7`='Todas las cosas que no puedan ser cargadas en nuestros zepelines deberán ser transportadas en barco hasta Rasganorte para que lleguen a nuestras manos.' WHERE `ID`=24490;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 투덜거립니다.', `MaleText_loc4`='%s咕哝着。', `MaleText_loc5`='%s嘀咕著。', `MaleText_loc7`='%s gruñe.' WHERE `ID`=24491;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='항로... 보급품... 지겹도록 들었더니 귀에 딱지가 앉을 지경이군요! 필요한 건 호드의 투쟁 정신뿐입니다, 사울팽! 이 얼어붙은 황무지에 요새까지 굳건히 세운 이상 그 무엇도 우릴 막을 순 없습니다!', `MaleText_loc4`='航道……补给……我快给你烦死了！萨鲁法尔，部落需要的只是勇者无畏的精神罢了！既然我们已经在这片冰原上站稳了脚跟，还有什么能阻挡我们呢！', `MaleText_loc5`='運輸路線...補給線...你這樣是煩也不煩!我們需要的不是別的，而是部落的戰士精神，薩魯法爾!既然我們堅決要入侵這片冰封的荒地，那麼什麼都阻止不了我們!', `MaleText_loc7`='Rutas de navegación… suministros… ¡Me matas de aburrimiento! ¡No necesitamos nada más que al espíritu guerrero de la Horda, Colmillosauro! ¡Ahora que estamos firmemente afianzados en este baldío helado nada podrá detenernos!' WHERE `ID`=24492;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공성 무기, 탄약, 방어구... 이런 준비도 없이 저 얼음왕관의 벽을 어떻게 무너트릴 생각인가?', `MaleText_loc4`='攻城器械、弹药、重型盔甲……没有这些，你打算如何轰开冰冠冰川的城墙？', `MaleText_loc5`='攻城機具，彈藥，重鎧甲...沒有這些東西，你要建議如何敲碎寒冰皇冠的高牆呢?', `MaleText_loc7`='Maquinaria de asedio, munición, armadura pesada… ¿Cómo pretendes destrozar las paredes de Corona de Hielo sin eso?' WHERE `ID`=24493;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계획 말입니까? 제 계획이 뭔지 보여드리지요!', `MaleText_loc4`='我的计划？你很快就会明白的！', `MaleText_loc5`='建議?我直接做給你看我建議什麼!', `MaleText_loc7`='¿Proponer? ¡Te mostraré lo que propongo!' WHERE `ID`=24494;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기... 이제 저희도 수송로가 있지 않습니까.', `MaleText_loc4`='瞧……我们已经开辟出了一条航道。', `MaleText_loc5`='瞧...我們有了運輸路線了。', `MaleText_loc7`='Eso es… Ahora tenemos una ruta marítima.' WHERE `ID`=24495;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='게다가 덤으로...', `MaleText_loc4`='不仅如此……', `MaleText_loc5`='只要測量得當...', `MaleText_loc7`='Y un poco más...' WHERE `ID`=24496;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌아온 탕아께서 계속 그렇게 말해 오셨지!', `MaleText_loc4`='这就是你所谓的计划吗！', `MaleText_loc5`='所以，敗家子開口說話了!', `MaleText_loc7`='¡El hijo pródigo ha hablado!' WHERE `ID`=24497;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 그 아버지에 그 아들이군. 헬스크림, 언제나 성급하지... 성급하고 무모해.', `MaleText_loc4`='加尔鲁什，你的脾气和你父亲简直一模一样。总是这么暴躁……既暴躁又卤莽。', `MaleText_loc5`='地獄吼，你父親的血液強烈的在你體內奔流著。永遠是那麼缺乏耐性...缺乏耐性又莽撞行事。', `MaleText_loc7`='La sangre de tu padre fluye por tus venas, Grito Infernal. Impaciente como siempre... Impaciente e imprudente.' WHERE `ID`=24498;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주문각인을 배워볼 생각이 있습니까?', `MaleText_loc4`='想学习铭文吗？', `MaleText_loc5`='有興趣學習銘文嗎?', `MaleText_loc7`='¿Te interesa aprender algo sobre inscripción?', `FemaleText_loc1`='주문각인을 배워볼 생각이 있나요?', `FemaleText_loc4`='想学习铭文吗？', `FemaleText_loc5`='有興趣學習銘文嗎?', `FemaleText_loc7`='¿Te interesa aprender algo sobre inscripción?' WHERE `ID`=24499;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자넨 그저 무조건 앞으로 달려나가는 것만 알아. 뒷일은 생각도 않고 말이지.', `MaleText_loc4`='你脑子里只想着战争与杀戮，完全不考虑后果。', `MaleText_loc5`='你一頭殺進一場殊死戰，卻絲毫沒有考慮過結果。', `MaleText_loc7`='Te lanzas de cabeza a una guerra encarnizada sin tener en cuenta las consecuencias.' WHERE `ID`=24500;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뒷일 얘기까지 하지는 마시지요, 어르신.', `MaleText_loc4`='别跟我谈什么后果，老家伙。', `MaleText_loc5`='老頭，不要跟我談結果。', `MaleText_loc7`='No me hables de consecuencias, viejo.' WHERE `ID`=24501;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 아버지가 마신 그 피를 나도 마셨네, 가로쉬. 저주스러운 만노로스의 독이 내 혈관을 타고 요동쳤다네.', `MaleText_loc4`='加尔鲁什，我和你的父亲都饮下了恶魔领主的鲜血。玛诺洛斯的诅咒同样在我的血脉里流淌。', `MaleText_loc5`='我與你的父親飲著同樣的血液，卡爾洛斯。瑪諾洛斯的詛咒毒液同樣流淌在我的血管之中。', `MaleText_loc7`='Bebí de la misma sangre que tu padre, Garrosh. El veneno maldito de Mannoroth también fluía por mis venas.' WHERE `ID`=24502;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적의 육신과 정신, 그 모두에 내 무기를 찔러넣었지.', `MaleText_loc4`='我也曾征战沙场，令敌人心胆俱裂。', `MaleText_loc5`='我掄起武器砍向我的敵人的身體，還有他們的心靈。', `MaleText_loc7`='Incrusté mis armas en los cuerpos y mentes de mis enemigos.' WHERE `ID`=24503;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 그롬은 영광스러운 죽음으로써 우리 모두를 피의 저주에서 자유롭게 했지만... 과거의 끔찍한 기억까지는 씻어내지 못했지.', `MaleText_loc4`='格罗姆付出了生命的代价，将我们从诅咒中解放出来，但他无法让我们忘记那段可怕的岁月。', `MaleText_loc5`='並當葛羅光榮戰死之時 - 將我們所有人從血的詛咒中解救出來 - 但是他揮不去的，是過往駭人的記憶。', `MaleText_loc7`='Y aunque Grom murió de forma gloriosa liberándonos de la maldición de sangre, no pudo borrar las terribles memorias de nuestro pasado.' WHERE `ID`=24504;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러한 그롬의 행동도 우리가 저지른 참사까지는 지울 수 없었네.', `MaleText_loc4`='他也无法抹去我们犯下的可怕罪行。', `MaleText_loc5`='他的舉動無法抹滅我們所犯下的恐怖行為。', `MaleText_loc7`='Su acto no podía borrar los horrores que habíamos cometido.' WHERE `ID`=24505;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 잠시 말을 멈춥니다.', `MaleText_loc4`='%s顿了一顿。', `MaleText_loc5`='%s停頓了一會兒。', `MaleText_loc7`='%s hace una pausa.' WHERE `ID`=24506;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저주에서 벗어나고서 겨울이 닥치자, 나 같은 노련한 오크 수백 명은 절망의 늪에 빠지고 말았지.', `MaleText_loc4`='诅咒解除后的那个严冬，数以百计的兽人士兵都在绝望中迷失了方向，我也不例外。', `MaleText_loc5`='在血的詛咒之後，緊跟的是寒冬，數以百計的獸人老兵，像我一樣，陷入了深深哀傷裡面。', `MaleText_loc7`='Al invierno siguiente de que se levantara la maldición, cientos de orcos veteranos como yo cedieron a la desesperación.' WHERE `ID`=24507;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 마음은 마침내 자유를 얻었네. 그랬지... 그렇게 자유로운 마음으로, 우리가 불타는 군단에 영혼을 빼앗겼을 때 저질렀던 끔찍한 일들을 다시 떠올렸네.', `MaleText_loc4`='我们终于恢复了理智，是的……终于能够反省自己在燃烧军团驱使下做出的鲁莽行径。', `MaleText_loc5`='我們的意志終於解放，是的...在軍團的控制之下，我們從曾經做過那難以置信的行為中，解放出來。', `MaleText_loc7`='Nuestras mentes eran al fin libres, sí... Libres para revivir todos los impensables actos que habíamos cometido bajo la influencia de la Legión.' WHERE `ID`=24508;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 고개를 끄덕입니다.', `MaleText_loc4`='%s点了点头。', `MaleText_loc5`='%s點了點頭。', `MaleText_loc7`='%s asiente con la cabeza.' WHERE `ID`=24509;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노련한 오크 대부분이 절망에 빠진 이유는 드레나이 아이 목소리 때문이었네. 한 번 들으면 절대로 잊을 수 없지...', `MaleText_loc4`='最让他们愧疚难安的就是德莱尼小孩的哭喊声……日夜萦绕在耳畔……', `MaleText_loc5`='我想，德萊尼孩童的哀號，讓他們退縮了...你永遠也忘不了的...', `MaleText_loc7`='Creo que fue el sonido de los niños draenei el que desquició a la mayoría... Nunca se olvida...' WHERE `ID`=24510;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='톱니멧돼지 농장에 가 본 적 있나? 잡을 수 있을 만큼 돼지가 자랐을 때... 바로 그 소리 말일세. 돼지 멱 따는 그 소리... 엄청나게 큰 소리로 울려 퍼지는 걸세. 우리같이 나이 든 전사들에게는 정말이지 힘든 시기였지.', `MaleText_loc4`='你去过野猪农场吧？猪长到适合屠宰的年纪时……对，那种惨烈的嘶叫。你听过猪临死前的哀嚎声么……非常刺耳。那些日子对我们这样的老兵来说真是煎熬。', `MaleText_loc5`='你去過野豬農場嗎?當野豬到了該屠宰的年紀的時候...就是那種聲音。殺豬的聲音...餘音不絕。這對我們這種老兵來說是最難熬的時刻了。', `MaleText_loc7`='¿Alguna vez has estado en La Pocilga? Cuando los puercos alcanzan la edad para la matanza... Es ese sonido. El sonido de los puercos al morir... Es el que más alto resuena. Son momentos duros para nosotros, los veteranos.' WHERE `ID`=24511;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만, 그 아이들이 정말로 천진난만할 뿐이라고 확신할 수 있습니까? 커서 우리에게 무기를 들이댈지 누가 알겠습니까!', `MaleText_loc4`='你总不会认为那些孩子会永远单纯吧？他们长大之后，就会拿起武器来对付我们了！', `MaleText_loc5`='但是你難道就認為這些孩童生下來就是無辜的嗎?他們有可能長大之後，拾起武器對抗我們!', `MaleText_loc7`='¿No creerás que esos niños eran inocentes? ¡Al crecer habrían empuñado las armas contra nosotros!' WHERE `ID`=24512;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 고개를 흔듭니다.', `MaleText_loc4`='%s摇了摇头。', `MaleText_loc5`='%s搖了搖頭。', `MaleText_loc7`='%s agita la cabeza.' WHERE `ID`=24513;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 험상궂은 얼굴로 가로쉬를 노려봅니다.', `MaleText_loc4`='%s用冷酷的目光盯着加尔鲁什。', `MaleText_loc5`='%s嚴峻的看著卡爾洛斯。', `MaleText_loc7`='%s mira a Garrosh severamente.' WHERE `ID`=24514;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 지금 적의 아이들만 놓고 얘기하는 게 아닐세...', `MaleText_loc4`='我指的不仅仅是敌人的孩子……', `MaleText_loc5`='我說的並不完全是敵人的孩童啊...', `MaleText_loc7`='No hablo solo de los hijos de nuestros enemigos…' WHERE `ID`=24515;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 우리를 또다시 어둠의 길로 끌고 가도록 내버려두진 않겠네, 젊은 헬스크림. 그런 날이 오면 내 손으로 자네를 처치해 주겠네...', `MaleText_loc4`='加尔鲁什，我不能坐视不管，任由你带领族人重新踏上那条黑暗的道路。我会在局势无可挽回之前亲手杀了你……', `MaleText_loc5`='我不會任由你把我們帶回那條晦暗的道路，年輕的地獄吼。我會在那天到來以前親手殺了你...', `MaleText_loc7`='No permitiré que nos hagas descender por ese oscuro camino de nuevo, joven Grito Infernal. Antes te mataría con mis propias manos…' WHERE `ID`=24516;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 초소로 발길을 돌립니다.', `MaleText_loc4`='%s回到了自己的王座。', `MaleText_loc5`='%s返回他的崗位。', `MaleText_loc7`='%s regresa a su puesto.' WHERE `ID`=24517;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 그토록 오래 살아남았습니까, 사울팽? 마음속에 있는 기억 때문에 무너지지 않고 말입니다.', `MaleText_loc4`='萨鲁法尔，你能活那么久吗？昔日的阴影难道不会吞噬你的躯壳吗？', `MaleText_loc5`='你是怎麼苟活這麼久的，薩魯法爾?不是因為你自己的回憶而痛苦萬分嗎?', `MaleText_loc7`='¿Cómo has logrado sobrevivir durante tanto tiempo, Colmillosauro? ¿No has sido víctima de tus propias memorias?' WHERE `ID`=24518;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돼지고기를 먹지 않는다네... 물론, 쇠고기도.', `MaleText_loc4`='我可不吃猪肉……', `MaleText_loc5`='還有，我從不吃豬肉...', `MaleText_loc7`='Yo no como cerdo...' WHERE `ID`=24519;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 침을 뱉습니다.', `MaleText_loc4`='%s啐了一口。', `MaleText_loc5`='%s啐了一口唾沫。', `MaleText_loc7`='%s escupe.' WHERE `ID`=24520;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 제군들! 출격하게!', `MaleText_loc4`='嘿，士兵！准备出发！', `MaleText_loc5`='沒錯，大兵!起飛時間!', `MaleText_loc7`='¡Sí, soldado! ¡Despegamos!' WHERE `ID`=24521;
