UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드 화톳불', `MaleText_loc4`='部落篝火。', `MaleText_loc5`='部落營火', `MaleText_loc7`='Hoguera de la Horda.', `FemaleText_loc1`='호드 화톳불', `FemaleText_loc4`='部落篝火。', `FemaleText_loc5`='部落營火', `FemaleText_loc7`='Hoguera de la Horda.' WHERE `ID`=24523;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드 화톳불이 있는 곳에 도착했습니다! 이 화톳불을 모독하고 꺼 버리십시오!', `MaleText_loc4`='你发现了一堆部落篝火。亵渎这堆篝火，扑灭它吧！', `MaleText_loc5`='你已經接近一座部落營火了!褻瀆這座營火並將它撲滅!', `MaleText_loc7`='¡Has llegado a una hoguera de la Horda! ¡Profana esta hoguera y acaba con ella!' WHERE `ID`=24524;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네에게 필요한 게 있을 걸세, 친구.', `MaleText_loc4`='朋友，我这里有你需要的东西。', `MaleText_loc5`='朋友，你想要的東西，喜爾這都有。', `MaleText_loc7`='¡Cel tiene lo que necesitas, colega!' WHERE `ID`=24525;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드 화톳불을 꺼 버립니다!', `MaleText_loc4`='扑灭部落篝火！', `MaleText_loc5`='撲滅部落的營火!', `MaleText_loc7`='¡Acaba con la hoguera de la Horda!', `FemaleText_loc1`='호드 화톳불을 꺼 버립니다!', `FemaleText_loc4`='扑灭部落篝火！', `FemaleText_loc5`='撲滅部落的營火!', `FemaleText_loc7`='¡Acaba con la hoguera de la Horda!' WHERE `ID`=24526;
