UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한여름 불꽃축제는 모두를 위한 축제랍니다!', `MaleText_loc4`='每个人都能享受到仲夏火焰节的乐趣！', `MaleText_loc5`='仲夏火焰節慶要讓每一個人同歡慶祝!', `MaleText_loc7`='¡Todo el mundo puede encontrar algo con lo que disfrutar en el Festival de Fuego del Solsticio de Verano!', `FemaleText_loc1`='한여름 불꽃축제는 모두를 위한 축제입니다!', `FemaleText_loc4`='每个人都能享受到仲夏火焰节的乐趣！', `FemaleText_loc5`='仲夏火焰節慶要讓每一個人同歡慶祝!', `FemaleText_loc7`='¡Todo el mundo puede encontrar algo con lo que disfrutar en el Festival de Fuego del Solsticio de Verano!' WHERE `ID`=24528;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스 화톳불이 있는 곳에 도착했습니다! 이 화톳불을 모독하고 꺼 버리십시오!', `MaleText_loc4`='你发现了一堆联盟篝火。亵渎这堆篝火，扑灭它吧！', `MaleText_loc5`='你已經接近一座聯盟營火了!褻瀆這座營火並將它撲滅!', `MaleText_loc7`='¡Has llegado a una hoguera de la Alianza! ¡Profana esta hoguera y acaba con ella!' WHERE `ID`=24529;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스 화톳불을 꺼 버립니다!', `MaleText_loc4`='扑灭联盟篝火！', `MaleText_loc5`='撲滅聯盟的營火!', `MaleText_loc7`='¡Acaba con la hoguera de la Alianza!', `FemaleText_loc1`='얼라이언스 화톳불을 꺼 버립니다!', `FemaleText_loc4`='扑灭联盟篝火！', `FemaleText_loc5`='撲滅聯盟的營火!', `FemaleText_loc7`='¡Acaba con la hoguera de la Alianza!' WHERE `ID`=24530;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드 녀석들이 우리 불꽃을 훔치려 했어. 고스란히 갚아줬으면 좋겠군.', `MaleText_loc4`='部落已经尝试来偷取我们的火焰了。我希望能以其人之道，还治其人之身。', `MaleText_loc5`='部落試圖偷走我們的火焰。我們也要回敬他們。', `MaleText_loc7`='La Horda ha intentado robar nuestras llamas. Espero que les devolvamos el favor.', `FemaleText_loc1`='호드 놈들이 우리 불꽃을 훔치려 했어. 고스란히 갚아줬으면 좋겠단 말이야.', `FemaleText_loc4`='部落已经尝试来偷取我们的火焰了。我希望能以其人之道，还治其人之身。', `FemaleText_loc5`='部落試圖偷走我們的火焰。我們也要回敬他們。', `FemaleText_loc7`='La Horda ha intentado robar nuestras llamas. Espero que les devolvamos el favor.' WHERE `ID`=24531;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스의 불꽃은 강하고 진실되게 타오르리라!', `MaleText_loc4`='联盟的火焰在熊熊燃烧！', `MaleText_loc5`='聯盟的火焰熾盛而真實!', `MaleText_loc7`='¡Los fuegos de la Alianza arden fuertes y reales!', `FemaleText_loc1`='얼라이언스의 불꽃은 강하고 진실되게 타오르리라!', `FemaleText_loc4`='联盟的火焰在熊熊燃烧！', `FemaleText_loc5`='聯盟的火焰熾盛而真實!', `FemaleText_loc7`='¡Los fuegos de la Alianza arden fuertes y reales!' WHERE `ID`=24532;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스가 우리 불꽃을 훔치려 드는 꼴을 봤으면 좋겠군.', `MaleText_loc4`='我倒想看到联盟来试着偷我们的火焰。', `MaleText_loc5`='我認為聯盟想要偷取我們的火焰。', `MaleText_loc7`='Me gustaría ver como intenta robar nuestra llama la Alianza.', `FemaleText_loc1`='얼라이언스가 우리 불꽃을 훔치려 드는 꼴을 봤으면 좋겠단 말이야.', `FemaleText_loc4`='我倒想看到联盟来试着偷我们的火焰。', `FemaleText_loc5`='我認為聯盟想要偷取我們的火焰。', `FemaleText_loc7`='Me gustaría ver como intenta robar nuestra llama la Alianza.' WHERE `ID`=24533;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드의 불꽃은 절대로 꺼지지 않는다!', `MaleText_loc4`='部落的火焰永远都不会熄灭！', `MaleText_loc5`='部落的火焰永遠也不會熄滅!', `MaleText_loc7`='¡Los fuegos de la Horda nunca se extinguirán!', `FemaleText_loc1`='호드의 불꽃은 절대로 꺼지지 않는다!', `FemaleText_loc4`='部落的火焰永远都不会熄灭！', `FemaleText_loc5`='部落的火焰永遠也不會熄滅!', `FemaleText_loc7`='¡Los fuegos de la Horda nunca se extinguirán!' WHERE `ID`=24534;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한여름 불꽃축제는 여름을 기념하는 최고의 시간이라고!', `MaleText_loc4`='仲夏节是每个夏天里最重要最欢乐的时刻！', `MaleText_loc5`='仲夏火焰節慶是慶祝夏天的重要時刻!', `MaleText_loc7`='¡El Festival de Fuego del Solsticio de Verano es un momento magnífico para celebrar el verano!', `FemaleText_loc1`='한여름 불꽃축제는 여름을 기념하는 최고의 시간이지!', `FemaleText_loc4`='仲夏节是每个夏天里最重要最欢乐的时刻！', `FemaleText_loc5`='仲夏火焰節慶是慶祝夏天的重要時刻!', `FemaleText_loc7`='¡El Festival de Fuego del Solsticio de Verano es un momento magnífico para celebrar el verano!' WHERE `ID`=24535;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한여름 불꽃축제 마지막에 치러지는 불꽃놀이가 가장 좋아.', `MaleText_loc4`='我很喜欢看仲夏火焰节结束时的烟花表演。', `MaleText_loc5`='我最喜歡仲夏火焰節慶末尾時的煙火秀。', `MaleText_loc7`='Me encanta el espectáculo de fuegos artificiales al final del Festival de Fuego del Solsticio de Verano.', `FemaleText_loc1`='한여름 불꽃축제 마지막에 치러지는 불꽃놀이가 가장 좋아.', `FemaleText_loc4`='我很喜欢看仲夏火焰节结束时的烟花表演。', `FemaleText_loc5`='我最喜歡仲夏火焰節慶末尾時的煙火秀。', `FemaleText_loc7`='Me encanta el espectáculo de fuegos artificiales al final del Festival de Fuego del Solsticio de Verano.' WHERE `ID`=24536;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리에게는 언제나 공포심이 가장 강력한 무기였네. 언제나 혼란과 의심 속에서 모든 전쟁을 치르며 승리하고 또 패배했지. 그럼 공포를 모르는 적과는 어떻게 싸워야 하는가?$B$B<고개를 젓는 사울팽>$B$B우리가 노스렌드에서 싸우는 상대는 스컬지뿐만이 아닐세. 저들이 우리를 산산조각 내기 전에 정신을 다잡도록 스스로와 싸워야 하네...', `MaleText_loc4`='恐惧永远是我们最强大的武器。整场战争的胜负就取决于敌人的惊恐与犹疑。那么，对面不知道恐惧为何物的敌人，我们要怎么打呢？$B$B<萨鲁法尔摇了摇头。>$B$B我们不仅要在诺森德与天灾军团作战，还要在他们将我们击溃之前，努力控制住自己的情绪。', `MaleText_loc5`='一直以來，恐懼是我們最大的武器。不安與猜忌掌控了戰爭的勝負。那麼，我們該怎麼對抗一個不知恐懼為何物的敵人呢?$B$B<薩魯法爾搖搖頭。>$B$B我們不光只是對抗北裂境的天譴軍，我們還要在他們撕碎我們以前，固守我們的知覺...', `MaleText_loc7`='El miedo siempre ha sido nuestra arma más eficaz. Se han ganado y perdido guerras enteras apoyándose en los temblorosos hombros de la duda y la turbación. Entonces, ¿cómo se lucha contra un enemigo que no conoce el miedo?$B$B<Colmillosauro agita la cabeza.>$B$BEn Rasganorte no solo luchamos contra la Plaga, luchamos por mantener el control de nuestros sentidos antes de que nos destrocen...' WHERE `ID`=24537;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='숄라자르 분지까지 진군할 수 있도록 이 전초기지는 만반의 준비를 해야 하네.$B$B거기 멍하니 서 있지 말게, $c. 나가서 명예롭게 피를 흘리며 호드의 이름을 떨쳐 보이게!', `MaleText_loc4`='我们要做好进军索拉查盆地的准备。$B$B别光站在那儿啊，$c。为部落的荣耀而战吧！', `MaleText_loc5`='我們需要將這個前哨準備好，好推進休拉薩盆地。$B$B別只是站在那裡，$c。到外面去，用榮耀和濺散的鮮血表現部落!', `MaleText_loc7`='Tenemos que preparar esta avanzada para el ataque a la Cuenca de Sholazar.$B$BNo te quedes ahí $gparado:parada:c; $c. ¡Ve y representa a la Horda derramando sangre y con honor!' WHERE `ID`=24538;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 난장판을 정리해야 하지만 불평 따위는 하지 않겠네.$B$B호드로서 긍지가 조금이라도 있다면 나를 도와주게!', `FemaleText_loc4`='我还有一堆乱七八糟的事情要处理呢，但是我不会有丝毫抱怨。$B$B如果你还为自己身处部落自豪的话，就来帮我一把！', `FemaleText_loc5`='我必需要把這一團亂清理乾淨，但是我不會抱怨。$B$B如果你還有一絲部落的驕傲的話，幫幫我!', `FemaleText_loc7`='Tengo que limpiar este desastre, pero lo haré sin quejarme.$B$B¡Si tuvieras un poco de orgullo de la Horda, me ayudarías!' WHERE `ID`=24540;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무... 늦었습니다...', `MaleText_loc4`='已经……太迟了……', `MaleText_loc5`='對我來說...太遲了...', `MaleText_loc7`='Es... demasiado tarde para mí...', `FemaleText_loc1`='너무... 늦었어요...', `FemaleText_loc4`='已经……太迟了……', `FemaleText_loc5`='對我來說...太遲了...', `FemaleText_loc7`='Es... demasiado tarde para mí...' WHERE `ID`=24541;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='복수해 주십시오...', `MaleText_loc4`='为我报仇……', `MaleText_loc5`='為我報仇...', `MaleText_loc7`='Vengadme...', `FemaleText_loc1`='복수해 주세요...', `FemaleText_loc4`='为我报仇……', `FemaleText_loc5`='為我報仇...', `FemaleText_loc7`='Vengadme...' WHERE `ID`=24542;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='복수해 주십시오...', `MaleText_loc4`='为我报仇……', `MaleText_loc5`='為我報仇...', `MaleText_loc7`='Vengadme...', `FemaleText_loc1`='복수해 주세요...', `FemaleText_loc4`='为我报仇……', `FemaleText_loc5`='為我報仇...', `FemaleText_loc7`='Vengadme...' WHERE `ID`=24543;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다, $r|1이여;여;. 당신의 친절을 잊지 않겠습니다.', `MaleText_loc4`='谢谢你，$r。我不会忘记你的帮助的。', `MaleText_loc5`='謝謝你，$r。我不會忘記善良的你。', `MaleText_loc7`='Gracias, $r. No olvidaré tu amabilidad.', `FemaleText_loc1`='감사합니다, $r|1이여;여;. 당신의 친절을 잊지 않겠어요.', `FemaleText_loc4`='谢谢你，$r。我不会忘记你的帮助的。', `FemaleText_loc5`='謝謝你，$r。我不會忘記善良的你。', `FemaleText_loc7`='Gracias, $r. No olvidaré tu amabilidad.' WHERE `ID`=24544;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='덕분에 살았습니다, $c님. 감사합니다!', `MaleText_loc4`='你救了我，$c。谢谢你！', `MaleText_loc5`='你救了我，$c，謝謝你!', `MaleText_loc7`='Me has salvado, $c. ¡Gracias!', `FemaleText_loc1`='덕분에 살았어요, $c님. 감사합니다!', `FemaleText_loc4`='你救了我，$c。谢谢你！', `FemaleText_loc5`='你救了我，$c，謝謝你!', `FemaleText_loc7`='Me has salvado, $c. ¡Gracias!' WHERE `ID`=24545;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다, $r|1이여;여;. 당신이 구해주지 않았다면 저도 저 무리의 일원이 됐을 겁니다!', `MaleText_loc4`='谢谢你，$r。要不是你出手帮忙，我已经落得和他们一样的下场了！', `MaleText_loc5`='謝謝你，$r。沒有你的幫助，我大概就會變成他們其中一員了!', `MaleText_loc7`='Gracias, $r. ¡Sin tu ayuda me habría convertido en uno de ellos!', `FemaleText_loc1`='감사합니다, $r|1이여;여;. 당신이 구해주지 않았다면 저도 저 무리의 일원이 됐을 거예요!', `FemaleText_loc4`='谢谢你，$r。要不是你出手帮忙，我已经落得和他们一样的下场了！', `FemaleText_loc5`='謝謝你，$r。沒有你的幫助，我大概就會變成他們其中一員了!', `FemaleText_loc7`='Gracias, $r. ¡Sin tu ayuda me habría convertido en uno de ellos!' WHERE `ID`=24546;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정령의 목소리가 사방에서 들려오네. 들리는가?', `FemaleText_loc4`='灵魂在我们身边低语。你听见了吗，$r？', `FemaleText_loc5`='靈魂在我們周圍絮語著。$r，聽見了嗎?', `FemaleText_loc7`='Los espíritus hablan alrededor nuestro. ¿Estás escuchando, $r?' WHERE `ID`=24547;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 숨을 깊게 들이마십니다.', `MaleText_loc4`='%s深深地吸了一口气。', `MaleText_loc5`='%s深深地吸了一口氣。', `MaleText_loc7`='%s respira hondo.', `FemaleText_loc1`='%s|1이;가; 숨을 깊게 들이마십니다.', `FemaleText_loc4`='%s深深地吸了一口气。', `FemaleText_loc5`='%s深深地吸了一口氣。', `FemaleText_loc7`='%s respira hondo.' WHERE `ID`=24548;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스틸조의 짐마차 경비병 시체가 쓰러져 있습니다.', `MaleText_loc4`='这里躺着一具钢腭的车队卫兵的尸体。', `MaleText_loc5`='這裡躺著一具鋼顎商隊守衛的屍體。', `MaleText_loc7`='Aquí yace el cuerpo de uno de los guardias de caravana de Quijacero.', `FemaleText_loc1`='스틸조의 짐마차 경비병 시체가 쓰러져 있습니다.', `FemaleText_loc4`='这里躺着一具钢腭的车队卫兵的尸体。', `FemaleText_loc5`='這裡躺著一具鋼顎商隊守衛的屍體。', `FemaleText_loc7`='Aquí yace el cuerpo de uno de los guardias de caravana de Quijacero.' WHERE `ID`=24549;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스틸조의 짐마차 일꾼 시체 하나가 쓰러져 있습니다.', `MaleText_loc4`='这里躺着一具钢腭的车队工人的尸体。', `MaleText_loc5`='這裡躺著一具鋼顎商隊工人的屍體。', `MaleText_loc7`='Aquí yace el cadáver de uno de los trabajadores de caravana de Quijacero.', `FemaleText_loc1`='스틸조의 짐마차 일꾼 시체 하나가 쓰러져 있습니다.', `FemaleText_loc4`='这里躺着一具钢腭的车队工人的尸体。', `FemaleText_loc5`='這裡躺著一具鋼顎商隊工人的屍體。', `FemaleText_loc7`='Aquí yace el cadáver de uno de los trabajadores de caravana de Quijacero.' WHERE `ID`=24550;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황혼의 신도들은 우리가 지키고자 노력한 모든 것들을 무너트리려 하네. 닥쳐올 이 재앙을 미리 방지하는 것이 우리의 임무지.', `MaleText_loc4`='暮光教派仇视一切我们珍视的东西。我们发誓要尽一切努力保卫这里，不让他们造成的灾祸将这里毁灭，$r。', `MaleText_loc5`='暮光教派想要毀壞我們努力保護的一切。我們的職責就是防範這種災難發生，$r。', `MaleText_loc7`='El Culto Crepuscular intenta deshacer todo lo que luchamos para preservar. Hemos jurado evitar que ocurra esta calamidad, $r.', `FemaleText_loc1`='황혼의 신도들은 우리가 지키고자 노력한 모든 것들을 무너트리려 하네. 닥쳐올 이 재앙을 미리 방지하는 것이 우리의 임무지.', `FemaleText_loc4`='暮光教派仇视一切我们珍视的东西。我们发誓要尽一切努力保卫这里，不让他们造成的灾祸将这里毁灭，$r。', `FemaleText_loc5`='暮光教派想要毀壞我們努力保護的一切。我們的職責就是防範這種災難發生，$r。', `FemaleText_loc7`='El Culto Crepuscular intenta deshacer todo lo que luchamos para preservar. Hemos jurado evitar que ocurra esta calamidad, $r.' WHERE `ID`=24551;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경계를 늦춰서는 안 되오! 호드가 우리의 방어선을 뚫고 의식을 방해하려 하오!', `MaleText_loc4`='大人，当心！部落计划突破防线来破坏我们的仪式！', `MaleText_loc5`='大人，做好準備!部落計畫要穿透我們的防禦，並且阻止儀式!', `MaleText_loc7`='¡Señores, manténganse en guardia! ¡La Horda planea atravesar nuestras defensas y detener la ceremonia!' WHERE `ID`=24552;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 지휘관은 대체 무슨 생각을 한 겁니까? 우리 부족의 신성한 묘지 가운데로 짐마차를 끌고 지나가다니!', `MaleText_loc4`='你的指挥官在想什么呢？居然带领商队穿越我们神圣的墓地！', `MaleText_loc5`='你的指揮官在想什麼?帶著你的商隊經過我們神聖的墓地!', `MaleText_loc7`='¿En qué estaba pensando tu comandante? ¡Atravesar nuestro sagrado cementerio con tu caravana!' WHERE `ID`=24553;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스틸조 유령이 지금 이 자리에 나타나고 있군요... 감이 옵니다.', `MaleText_loc4`='钢腭的灵魂仍在这里徘徊……我能感觉到。', `MaleText_loc5`='你的鋼顎氏族正在此地作祟...我感覺得到。', `MaleText_loc7`='Su Quijacero atormenta este lugar ahora... Puedo sentirlo.' WHERE `ID`=24554;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방황하는 영혼들을 처리하는데 할 일을 하십시오, 레이지피스트.', `MaleText_loc4`='怒拳，尽你所能地镇压那些骚动的灵魂。', `MaleText_loc5`='怒拳，不擇手段平息這些不得安寧的靈魂。', `MaleText_loc7`='Haz lo que debas para sofocar a los espíritus inquietos, Puñofuria.' WHERE `ID`=24555;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타락한 지휘관의 영혼을 무찌르는 것은 우리 모두의 목숨을 걸고 해야할 만큼 가치 있는 일입니다.', `MaleText_loc4`='我们要不惜一切代价消灭死去的指挥官的灵魂。', `MaleText_loc5`='要消滅你那墮落的指揮官靈魂，就算賠上我們所有人的生命也在所不惜。', `MaleText_loc7`='Vale la pena dar nuestras vidas para eliminar el espíritu de su comandante caído.' WHERE `ID`=24556;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스틸조를 처리하기 전까지 타운카 영혼들은 편히 잠들지 못할 것입니다.', `MaleText_loc4`='只有除掉钢腭，牛头人的灵魂才能安息。', `MaleText_loc5`='解決鋼顎以前，坦卡族的靈魂都無法安息。', `MaleText_loc7`='Los espíritus de los taunka no descansarán hasta que alguien se ocupe de Quijacero.' WHERE `ID`=24557;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대 호드와 관계를 맺기 시작하는 우리 부족으로서는 썩 달가운 일이 아닙니다.', `MaleText_loc4`='就我们和部落的关系而言，这显然不是一个良好的开端。', `MaleText_loc5`='對我的族人與你的部落關係來說，這不是個好的開始。', `MaleText_loc7`='Este no es un buen comienzo para las relaciones entre mi gente y tu Horda.' WHERE `ID`=24558;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일단 행동을 개시하면 신속하게 움직일 겁니다. 가는 길에 뭐가 나타나든 전부 쓰러뜨린다는 각오를 하십시오.', `MaleText_loc4`='一旦我们开始行动，速度会很快。请你做好准备，帮助我们扫清路上的障碍。', `MaleText_loc5`='我們不動則已，一動就是要迅捷如風。準備好將所有擋在我們面前的一切清除徹底。', `MaleText_loc7`='Cuando nos movamos, nos moveremos rápido. Preparaos para acabar con cualquier cosa que se interponga en nuestro camino.' WHERE `ID`=24559;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대의 대군주가 저를 돕겠다고 약속했습니다. 보내겠다던 중요한 분은 어디 있습니까?', `MaleText_loc4`='博古洛克大王曾许诺会帮助我们。但他派来的重要人物在哪儿呢？', `MaleText_loc5`='你的霸主承諾要提供援助，他說要指派的那位重要人士在哪裡?', `MaleText_loc7`='Tu Señor Supremo me prometió ayuda. ¿Dónde está esa persona importante que iba a enviar?' WHERE `ID`=24560;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 우리 공격을 지원할 것이다. 조상님께 안식을 선사하자!', `MaleText_loc4`='$n会帮助我们展开攻击。让祖先的灵魂重归宁静吧！', `MaleText_loc5`='$n將會參與我們的突襲行動。讓我們將安寧帶給我們的先祖吧!', `MaleText_loc7`='$n va a unirse a nuestro ataque. ¡Hagamos que mis ancestros descansen en paz!' WHERE `ID`=24561;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공격 개시!', `MaleText_loc4`='出击！', `MaleText_loc5`='我們上啊!', `MaleText_loc7`='¡ATACAMOS!' WHERE `ID`=24562;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='매복이다. 저들에게 안식을 되찾아줘라!', `MaleText_loc4`='发动伏击。让他们重新安息吧！', `MaleText_loc5`='偷襲，把他們送回安息之地!', `MaleText_loc7`='Una emboscada. ¡Devolvedlos a su eterno descanso!' WHERE `ID`=24563;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘을 아껴 두십시오. 바로 저 앞이 스틸조가 쓰러진 곳입니다.', `MaleText_loc4`='打起精神来。钢腭就死在前面。', `MaleText_loc5`='恢復你的力量，鋼顎被打倒的地方就在不遠處。', `MaleText_loc7`='Recupera tus fuerzas. El lugar donde Quijacero fue derribado está justo ahí.' WHERE `ID`=24564;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='개만도 못한 놈의 깃발과 시체가 저기 있군요. 저게 뭡니까? 그가 다가옵니다!', `MaleText_loc4`='喏，瞧见那面旗帜和他的尸体了吧。怎么回事？他朝我们冲了过来！', `MaleText_loc5`='這有獵犬的旌旗和他的屍體。那是什麼?他就快來了!', `MaleText_loc7`='Ahí está el estandarte del perro y ahí su cadáver. ¿Qué es eso? ¡Está sobre nosotros!' WHERE `ID`=24565;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 싸워주셨습니다. 이제 북쪽에 있는 그대 쪽 오크 전초기지로 가서 대군주 보르고로크 님께 우리가 성공했다고 알려주십시오.', `MaleText_loc4`='你做得很好。返回北方的兽人要塞吧，告诉博古洛克大王我们成功了！', `MaleText_loc5`='你攻擊得很出色，現在，我們要往北前進，到你們獸人的崗哨，通報霸主博格洛克我們獲勝的消息!', `MaleText_loc7`='Has luchado bien. ¡Ahora ve hacia el norte hasta tu avanzada orca e informa al señor supremo Bor''gorok de nuestro éxito!' WHERE `ID`=24566;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디 내 영혼을 해방해 봐라, 더러운 녀석!', `MaleText_loc4`='拯救我的灵魂吧，混蛋！', `MaleText_loc5`='要是可以釋放我的靈魂吧，朋友!', `MaleText_loc7`='¡Libera mi alma si puedes!' WHERE `ID`=24567;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 자유다! 고맙다.', `MaleText_loc4`='我自由了！谢谢你。', `MaleText_loc5`='我得救了!謝謝你。', `MaleText_loc7`='¡Soy libre! Gracias.' WHERE `ID`=24575;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 명예를 잃었네. 마그모스에서 선견자와 함께 죽었어야 했는데.$B$B날 혼자 내버려 두게.', `MaleText_loc4`='我真是无地自容。我应该和先知一起死在犸格莫斯的。$B$B让我静一静。', `MaleText_loc5`='這真是奇恥大辱。我早該跟著先知一起死在瑪格默斯的。$B$B讓我一個人好好靜一靜。', `MaleText_loc7`='Soy una deshonra. Debí haber muerto con el clarividente en Magmoth.$B$BDéjame meditar.' WHERE `ID`=24579;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기에 있는 바람의 정령이 동요하고 있다. 조심하라... 그대를 순순히 보내지 않을 것이다.', `MaleText_loc4`='附近的气元素躁动不安。小心……它们不会让你安全通过的。', `MaleText_loc5`='這兒的風元素永不止息。小心...它們不會讓你毫髮無傷的通過的。', `MaleText_loc7`='El elemento de aire está inquieto en este lugar. Cuidado... No conseguirás pasar indemne.' WHERE `ID`=24580;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 좋아. 아주 좋아...', `MaleText_loc4`='对，对，非常好……', `MaleText_loc5`='沒錯，沒錯，非常好...', `MaleText_loc7`='Sí, sí, muy bien...', `FemaleText_loc1`='좋아, 좋아. 아주 좋아...', `FemaleText_loc4`='对，对，非常好……', `FemaleText_loc5`='沒錯，沒錯，非常好...', `FemaleText_loc7`='Sí, sí, muy bien...' WHERE `ID`=24581;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피의 공작님께서 아주 기뻐하시겠군...', `MaleText_loc4`='血王子一定会对此感到满意的……', `MaleText_loc5`='血親王應該會很滿意這些東西...', `MaleText_loc7`='El Príncipe de Sangre debería estar muy satisfecho con estos...', `FemaleText_loc1`='피의 공작님께서 아주 기뻐하시겠군...', `FemaleText_loc4`='血王子一定会对此感到满意的……', `FemaleText_loc5`='血親王應該會很滿意這些東西...', `FemaleText_loc7`='El Príncipe de Sangre debería estar muy satisfecho con estos...' WHERE `ID`=24582;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 좀 약해 보이는데... 뭐, 상관없지...', `MaleText_loc4`='看上去有点脆弱呢……不过无所谓啦……', `MaleText_loc5`='這東西看起來有點脆弱...不過，不要緊...', `MaleText_loc7`='Este parece un poco frágil… bueno, no importa…', `FemaleText_loc1`='이건 좀 약해 보이는데... 뭐, 상관없지...', `FemaleText_loc4`='看上去有点脆弱呢……不过无所谓啦……', `FemaleText_loc5`='這東西看起來有點脆弱...不過，不要緊...', `FemaleText_loc7`='Este parece un poco frágil… bueno, no importa…' WHERE `ID`=24583;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조금 모자랄 것도 같은데...', `MaleText_loc4`='也许我们还需要一些……', `MaleText_loc5`='也許，我們會需要多一點...', `MaleText_loc7`='Quizá necesitemos más...', `FemaleText_loc1`='조금 모자랄 것도 같은데...', `FemaleText_loc4`='也许我们还需要一些……', `FemaleText_loc5`='也許，我們會需要多一點...', `FemaleText_loc7`='Quizá necesitemos más...' WHERE `ID`=24584;
