UPDATE `locales_broadcast_text` SET `MaleText_loc1`='웬 놈이냐?! 만찬을 즐기던 중이었는데!', `MaleText_loc4`='搞什么啊？！是谁打扰我享用美餐！', `MaleText_loc5`='這是什麼意思?我還沒享用完我的大餐!', `MaleText_loc7`='¡¿Qué significa esto?! ¡Aún no he terminado mi festín!', `FemaleText_loc1`='웬 놈이냐?! 만찬을 즐기던 중이었는데!', `FemaleText_loc4`='搞什么啊？！是谁打扰我享用美餐！', `FemaleText_loc5`='這是什麼意思?我還沒享用完我的大餐!', `FemaleText_loc7`='¡¿Qué significa esto?! ¡Aún no he terminado mi festín!' WHERE `ID`=24586;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곧 주인님께 바칠 피를 더 구해야겠어...', `MaleText_loc4`='我们要为主人收集更多的鲜血……', `MaleText_loc5`='很快，我們就需要給主人準備更多的鮮血了...', `MaleText_loc7`='Puede que pronto necesitemos más sangre para el maestro…', `FemaleText_loc1`='곧 주인님께 바칠 피를 더 구해야겠어...', `FemaleText_loc4`='我们要为主人收集更多的鲜血……', `FemaleText_loc5`='很快，我們就需要給主人準備更多的鮮血了...', `FemaleText_loc7`='Puede que pronto necesitemos más sangre para el maestro…' WHERE `ID`=24587;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 그래. 주인님의 만찬을 준비할 시간이군...', `MaleText_loc4`='啊，主人的用餐时间快到了……', `MaleText_loc5`='啊，是的，差不多是時候該上主人的晚餐了...', `MaleText_loc7`='Ah, sí, ya casi es la hora de la cena del maestro…', `FemaleText_loc1`='아, 그래. 주인님의 만찬을 준비할 시간이군...', `FemaleText_loc4`='啊，主人的用餐时间快到了……', `FemaleText_loc5`='啊，是的，差不多是時候該上主人的晚餐了...', `FemaleText_loc7`='Ah, sí, ya casi es la hora de la cena del maestro…' WHERE `ID`=24588;
