UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절 풀어줘서 고맙습니다! 파도의 가호가 항상 함께하길 빌겠습니다.', `MaleText_loc4`='谢谢你救了我！愿好运永远伴随你。', `MaleText_loc5`='謝謝你救了我!願浪潮總是偏愛你。', `MaleText_loc7`='¡Gracias por liberarme! ¡Que las mareas siempre te favorezcan!' WHERE `ID`=24596;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙습니다, $c|1이여;여;. 다시는 풀려나지 못할 줄 알았더랬죠.', `MaleText_loc4`='谢谢你，$c。我还以为自己再也出不来了。', `MaleText_loc5`='請收下我的感激之意，$c。我以為不會有人來救我了。', `MaleText_loc7`='Te lo agradezco, $c. Creí que nunca sería libre.' WHERE `ID`=24597;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카스칼라는 이곳에서 일어난 일을 절대 잊지 않을 겁니다.', `MaleText_loc4`='卡斯卡拉会铭记你的恩情。', `MaleText_loc5`='卡斯卡拉族人毋忘此處所發生的一切。', `MaleText_loc7`='No permitas que Kashala olvide lo que ha sucedido aquí.' WHERE `ID`=24598;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙습니다, $c|1이여;여;. 바람과 바다가 항상 보호하시길.', `MaleText_loc4`='谢谢你，$c。愿微风与海洋保佑你。', `MaleText_loc5`='謝謝你，$c，願風與海送你至安全的地方。', `MaleText_loc7`='Gracias, $c. Que los mares y los vientos te protejan en tus viajes.' WHERE `ID`=24599;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카스칼라들이 당신에게 큰 빚을 졌습니다, $c|1이여;여;.', `MaleText_loc4`='卡斯卡拉欠你一份情，$c。', `MaleText_loc5`='卡斯卡拉的我族人民欠你一次人情，$c。', `MaleText_loc7`='La gente de Kashala está en deuda contigo, $c.' WHERE `ID`=24600;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와줘서 고맙습니다, $c|1이여;여;. 조상께서 항상 보살피시길 빌겠습니다.', `MaleText_loc4`='$c，谢谢你给予我们的帮助，愿先祖永远庇佑你。', `MaleText_loc5`='願先祖永遠幫助你，$c，一如你所幫助我的那樣。', `MaleText_loc7`='Que los ancestros siempre te ayuden, $c, como tú me has ayudado a mí.' WHERE `ID`=24601;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 조상님들을 공경해 주십시오.', `MaleText_loc4`='向我们的先祖致敬。', `MaleText_loc5`='榮耀我的先祖。', `MaleText_loc7`='Honra a mis ancestros.' WHERE `ID`=24602;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부디 묘지에 평화를 찾아 주십시오.', `MaleText_loc4`='必须恢复墓地的安宁。', `MaleText_loc5`='埋葬場一定要被復原。', `MaleText_loc7`='El enterramiento ha de ser restaurado.' WHERE `ID`=24603;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 임무를 완수하지 못하고 죽는군요.', `MaleText_loc4`='在完成任务前我就丢了性命。', `MaleText_loc5`='我死在任務完成之前。', `MaleText_loc7`='Muero antes de completar mi tarea.' WHERE `ID`=24604;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 여기서 조상님들께 갈 것입니다.', `MaleText_loc4`='就让我与先祖们一起安息吧。', `MaleText_loc5`='我在此回歸先祖的懷抱。', `MaleText_loc7`='Aquí voy a unirme con mis ancestros.' WHERE `ID`=24605;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무도 우릴 막을 수 없다!', `MaleText_loc4`='谁也不能阻止我们！', `MaleText_loc5`='誰也阻止不了我們!', `MaleText_loc7`='¡Nada podrá detenernos!' WHERE `ID`=24606;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽어도 네놈과 함께 죽겠다!', `MaleText_loc4`='和我一起进入坟墓吧！', `MaleText_loc5`='進墳墓吧!', `MaleText_loc7`='¡Ve a la tumba!' WHERE `ID`=24607;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 성스러운 안식처를 모욕하는 것도 이제 끝이다!', `MaleText_loc4`='这片神圣的安息之地终于恢复了宁静！', `MaleText_loc5`='污穢這片神聖棲息之地的一切，如今將終結!', `MaleText_loc7`='¡La profanación de este sagrado lugar de descanso termina ahora!' WHERE `ID`=24608;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 프라우드후프다. 나는 지지 않는다!', `MaleText_loc4`='傲蹄必胜！', `MaleText_loc5`='傲蹄族在此，萬夫莫敵!', `MaleText_loc7`='¡Soy un Pezuña Orgullosa, no fracasaré!' WHERE `ID`=24609;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='남쪽 사람들이 우리 땅에 발을 디디면 이런 일이 생긴다.', `MaleText_loc4`='那些南方人来到这里后，才发生了这样的事。', `MaleText_loc5`='南方人來到我們的土地之後，事情就這麼發生了。', `MaleText_loc7`='Esto es lo que pasa cuando los sureños vienen a nuestras tierras.' WHERE `ID`=24610;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳이 다시 평화로워질 때까지 나는 절대 멈추지 않을 것이다.', `MaleText_loc4`='除非这片土地恢复安宁，否则我不会后退一步的。', `MaleText_loc5`='在這個地方恢復寧靜之前，我不會罷手的。', `MaleText_loc7`='No me detendré hasta que la paz vuelva a reinar en este lugar.' WHERE `ID`=24611;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조상님께서 무덤 속에서조차 편히 쉬지 못하시는 걸 보니 참으로 괴롭습니다.$B$B전투사령관 스틸조의 저주받은 유령은 반드시 물리쳐야 합니다. 이 성스러운 땅에 짐마차를 끌고 들어온 어리석은 자의 유령 말입니다.', `MaleText_loc4`='看到先祖的灵魂无法安息，我非常痛心。$B$B指挥官斯尔加·钢腭这个蠢货居然带领商队穿越这片神圣的墓地，我们必须消灭他那被诅咒的灵魂。', `MaleText_loc5`='眼見我的先祖從他們的墓地中被侵擾，讓我悲痛莫名。$B$B我們一定要擊敗那個被詛咒的靈魂 - 軍隊指揮官鋼顎，他率領著他的商隊愚蠢的通過這片神聖的土地。', `MaleText_loc7`='Me duele ver que mis ancestros son molestados en su descanso eterno.$B$BDebemos atacar al espíritu maldito del insensato comandante en jefe Quijacero, quien guió esta caravana a través de esta tierra sagrada.' WHERE `ID`=24612;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대는 그대의 동족을 명예롭게 했습니다, $r. 스틸조의 유령을 처리하는 것을 도와준 데 다시 한 번 감사를 드립니다.$B$B이번 사건은 실로 통탄할 일이었지만, 시간이 지나면 우리는 반드시 친구가 될 수 있으리라 믿습니다.', `MaleText_loc4`='$r，你为你的族人赢得了荣耀。再次感谢你帮助我们消灭了钢腭的灵魂。$B$B尽管我们之间有过误会，但我相信我们很快就能成为真正的朋友。', `MaleText_loc5`='你讓你的族人倍感光榮，$r。再次感激你伸出援手解決鋼顎的靈魂。$B$B儘管發生這樣痛苦的誤會，我仍相信，我們的族人將遲早成為朋友。', `MaleText_loc7`='Honras a tu gente, $r. Gracias de nuevo por ayudarme a encargarme del espíritu de Quijacero.$B$BEstoy seguro de que nuestros pueblos llegarán a ser amigos, a pesar de este lamentable malentendido.' WHERE `ID`=24613;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 도끼를 주겠네, 용감한 자여! 함께 이 벌레를 쓸어버리세!', `MaleText_loc4`='英雄，我愿为你效劳！让我们一起干掉这些家伙！', `MaleText_loc5`='英雄，這是我的斧頭!讓我們一起把這些蟲子殺掉吧!', `MaleText_loc7`='¡Mi hacha es tuya, valiente! ¡Juntos destruiremos a esos insectos!', `FemaleText_loc1`='내 도끼를 주겠네, 용감한 자여! 함께 이 벌레를 쓸어버리세!', `FemaleText_loc4`='英雄，我愿为你效劳！让我们一起干掉这些家伙！', `FemaleText_loc5`='英雄，這是我的斧頭!讓我們一起把這些蟲子殺掉吧!', `FemaleText_loc7`='¡Mi hacha es tuya, valiente! ¡Juntos destruiremos a esos insectos!' WHERE `ID`=24614;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 전쟁노래 요새로 돌아가야겠네. 건투를 비네, 용맹한 자여!', `MaleText_loc4`='我必须返回战歌要塞了。英雄，好好战斗吧！', `MaleText_loc5`='我得回去戰歌堡了，奮勇作戰吧，英雄!', `MaleText_loc7`='He de regresar al Bastión Grito de Guerra. ¡Lucha duro, valiente!', `FemaleText_loc1`='나는 전쟁노래 요새로 돌아가야겠네. 건투를 비네, 용맹한 자여!', `FemaleText_loc4`='我必须返回战歌要塞了。英雄，好好战斗吧！', `FemaleText_loc5`='我得回去戰歌堡了，奮勇作戰吧，英雄!', `FemaleText_loc7`='He de regresar al Bastión Grito de Guerra. ¡Lucha duro, valiente!' WHERE `ID`=24615;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 전쟁노래 요새로 돌아가야겠네, 영웅이여. 적의 피로 강을 물들이고 그들이 슬퍼하는 순간에 잔치를 벌이길 바라네!', `MaleText_loc4`='英雄，我必须返回战歌要塞了。愿你浴血沙场，令敌人闻风丧胆！', `MaleText_loc5`='我得回去戰歌堡了，英雄。願你沐浴在敵人之血中，大啖他們的懊悔!', `MaleText_loc7`='He de regresar al Bastión Grito de Guerra, valiente. ¡Nada en la sangre de nuestros enemigos y aliméntate de su dolor!', `FemaleText_loc1`='나는 전쟁노래 요새로 돌아가야겠네, 영웅이여. 적의 피로 강을 물들이고 그들이 슬퍼하는 순간에 잔치를 벌이길 바라네!', `FemaleText_loc4`='英雄，我必须返回战歌要塞了。愿你浴血沙场，令敌人闻风丧胆！', `FemaleText_loc5`='我得回去戰歌堡了，英雄。願你沐浴在敵人之血中，大啖他們的懊悔!', `FemaleText_loc7`='He de regresar al Bastión Grito de Guerra, valiente. ¡Nada en la sangre de nuestros enemigos y aliméntate de su dolor!' WHERE `ID`=24616;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕히 가십시오, 동지여. 저는 전쟁노래 요새로 돌아가야겠습니다.', `MaleText_loc4`='再见，朋友。我必须返回战歌要塞了。', `MaleText_loc5`='再會了，朋友，我得趕回戰歌堡。', `MaleText_loc7`='Adiós, colega. He de regresar al Bastión Grito de Guerra.', `FemaleText_loc1`='안녕히 가십시오, 동지여. 저는 전쟁노래 요새로 돌아가야겠습니다.', `FemaleText_loc4`='再见，朋友。我必须返回战歌要塞了。', `FemaleText_loc5`='再會了，朋友，我得趕回戰歌堡。', `FemaleText_loc7`='Adiós, colega. He de regresar al Bastión Grito de Guerra.' WHERE `ID`=24617;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 만날 때까지 안녕히, 영웅이여. 또 다른 사명이 나를 부르니 이만 가겠네!', `MaleText_loc4`='再见。我得奉命离开了！', `MaleText_loc5`='直到我們再度相遇的那天，英雄。我還有職責未盡!', `MaleText_loc7`='Hasta que nos volvamos a ver, valiente. El deber me llama.', `FemaleText_loc1`='다시 만날 때까지 안녕히, 영웅이여. 또 다른 사명이 나를 부르니 이만 가겠네!', `FemaleText_loc4`='再见。我得奉命离开了！', `FemaleText_loc5`='直到我們再度相遇的那天，英雄。我還有職責未盡!', `FemaleText_loc7`='Hasta que nos volvamos a ver, valiente. El deber me llama.' WHERE `ID`=24618;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 나의 명상을 방해하느냐?', `MaleText_loc4`='是谁打断了我的冥想？', `MaleText_loc5`='誰打斷了我的冥想?!', `MaleText_loc7`='¿Quién interrumpe mi meditación?', `FemaleText_loc1`='누가 나의 명상을 방해하느냐?', `FemaleText_loc4`='是谁打断了我的冥想？', `FemaleText_loc5`='誰打斷了我的冥想?!', `FemaleText_loc7`='¿Quién interrumpe mi meditación?' WHERE `ID`=24619;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정령들이 그대를 지켜주기를, 동지여 나는 전쟁노래 요새로 돌아가야 하네.', `MaleText_loc4`='灵魂在护佑着你，朋友。我必须返回战歌要塞了。', `MaleText_loc5`='靈魂守護著你，朋友。我必須回去戰歌堡了。', `MaleText_loc7`='Los espíritus te protegen, colega. He de regresar al Bastión Grito de Guerra.', `FemaleText_loc1`='정령들이 그대를 지켜주기를, 동지여 나는 전쟁노래 요새로 돌아가야 하네.', `FemaleText_loc4`='灵魂在护佑着你，朋友。我必须返回战歌要塞了。', `FemaleText_loc5`='靈魂守護著你，朋友。我必須回去戰歌堡了。', `FemaleText_loc7`='Los espíritus te protegen, colega. He de regresar al Bastión Grito de Guerra.' WHERE `ID`=24620;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조상님들이 그대를 지켜주실 걸세, 영웅이여. 잘 가게!', `MaleText_loc4`='愿先祖与你同在。再见！', `MaleText_loc5`='先祖保佑你，英雄。再會了!', `MaleText_loc7`='Que los ancestros estén contigo, valiente. ¡Adiós!', `FemaleText_loc1`='조상님들이 그대를 지켜주실 걸세, 영웅이여. 잘 가게!', `FemaleText_loc4`='愿先祖与你同在。再见！', `FemaleText_loc5`='先祖保佑你，英雄。再會了!', `FemaleText_loc7`='Que los ancestros estén contigo, valiente. ¡Adiós!' WHERE `ID`=24621;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구해줘서 고맙네, 동지여! 나도 자네를 돕겠네.', `MaleText_loc4`='得救了！谢谢你，我愿意随时为你效劳。', `MaleText_loc5`='得救啦!感謝你，我會幫助你的，朋友。', `MaleText_loc7`='¡Rescatado! Cuenta con mi agradecimiento y ayuda, colega.', `FemaleText_loc1`='구해줘서 고맙네, 동지여! 나도 자네를 돕겠네.', `FemaleText_loc4`='得救了！谢谢你，我愿意随时为你效劳。', `FemaleText_loc5`='得救啦!感謝你，我會幫助你的，朋友。', `FemaleText_loc7`='¡Rescatada! Cuenta con mi agradecimiento y ayuda, colega.' WHERE `ID`=24622;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 함께 스컬지 무리에서 이놈들을 없애 버리세!', `MaleText_loc4`='让我们一起毁掉天灾军团的采石场！', `MaleText_loc5`='我們會並肩作戰將礦場的天譴軍趕走!', `MaleText_loc7`='¡Lucharemos juntos para librar a esta cantera de la Plaga!', `FemaleText_loc1`='우리 함께 스컬지 무리에서 이놈들을 없애 버리세!', `FemaleText_loc4`='让我们一起毁掉天灾军团的采石场！', `FemaleText_loc5`='我們會並肩作戰將礦場的天譴軍趕走!', `FemaleText_loc7`='¡Lucharemos juntos para librar a esta cantera de la Plaga!' WHERE `ID`=24623;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='태양샘의 분노로, 저는 해방되었습니다!', `MaleText_loc4`='感谢太阳之井，我自由了！', `MaleText_loc5`='以太陽井之怒，我逃出來了!', `MaleText_loc7`='¡Por la furia de La Fuente del Sol, estoy liberado!', `FemaleText_loc1`='태양샘의 분노로, 저는 해방되었습니다!', `FemaleText_loc4`='感谢太阳之井，我自由了！', `FemaleText_loc5`='以太陽井之怒，我逃出來了!', `FemaleText_loc7`='¡Por la furia de La Fuente del Sol, estoy liberado!' WHERE `ID`=24624;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반드시 복수하겠습니다! 쿠엘탈라스를 위해! 신도레이를 위해!', `MaleText_loc4`='燃起复仇的怒火！为了奎尔萨拉斯！为了辛多雷！', `MaleText_loc5`='我要復仇!為了奎爾薩拉斯!為了辛多雷!', `MaleText_loc7`='¡La venganza será mía! ¡Por Quel''Thalas! ¡Por los sin''dorei!', `FemaleText_loc1`='반드시 복수하겠습니다! 쿠엘탈라스를 위해! 신도레이를 위해!', `FemaleText_loc4`='燃起复仇的怒火！为了奎尔萨拉斯！为了辛多雷！', `FemaleText_loc5`='我要復仇!為了奎爾薩拉斯!為了辛多雷!', `FemaleText_loc7`='¡La venganza será mía! ¡Por Quel''Thalas! ¡Por los sin''dorei!' WHERE `ID`=24625;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어? 여기가 어디지? 느낌이 나빠! 도망가자!', `MaleText_loc4`='嗯？我在哪儿？看起来不太妙！逃命要紧！', `MaleText_loc5`='嗄?我在哪?這看起來不大妙!我要閃了!', `MaleText_loc7`='¿Eh? ¿Dónde yo? ¡Esto no tener buena pinta! ¡Mí correr!' WHERE `ID`=24626;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='만세! 나 자유다!', `MaleText_loc4`='好啊！我自由了！', `MaleText_loc5`='喔耶!我自由啦!', `MaleText_loc7`='¡HURRA! ¡MI LIBRE!' WHERE `ID`=24627;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고마워요, 친구!', `MaleText_loc4`='谢了，伙计！', `MaleText_loc5`='謝啦，老兄!', `MaleText_loc7`='¡Gracias, colega!' WHERE `ID`=24628;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모르투스씨가 엄청나게 화낼 텐데! 바로 집에 가야겠다.', `MaleText_loc4`='摩尔图斯工头一定会大发雷霆的！我得赶紧回去。', `MaleText_loc5`='莫吐斯先生會瘋掉!我還是先回家好了。', `MaleText_loc7`='¡El señor Mortuus se va a enfadar mucho! Yo ir a casa ahora.' WHERE `ID`=24629;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 자꾸 바구니에 기름칠하라고 하지? 나 저 기름 싫은데!', `MaleText_loc4`='为什么非要我把洗涤剂放到篮子里？我讨厌洗涤剂！', `MaleText_loc5`='為什麼它一直叫我把乳液放進籃子裡?我一點也不喜歡乳液!', `MaleText_loc7`='¿Por qué sigue diciendo que ponga la crema en la cesta? ¡A mí no gustar la crema!' WHERE `ID`=24630;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저길 봐라, 우그소르. 저것들이 뭔지 알겠느냐?', `MaleText_loc4`='乌格索，瞧。你知道他们是谁吗？', `MaleText_loc5`='看看他們，烏格。你知道他們是什麼嗎?', `MaleText_loc7`='Míralos, Ug. ¿Sabes qué son?' WHERE `ID`=24631;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니요, 아빠. 돼지처럼 보이는데. 돼지인가요?', `MaleText_loc4`='嗯。他们看上去像是猪啊。是猪吗？', `MaleText_loc5`='不知道，爸爸。他們看起來像是豬。牠們是豬嗎?', `MaleText_loc7`='No, papi. Parecen cerdos. ¿Son cerdos?' WHERE `ID`=24632;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저놈들은...', `MaleText_loc4`='他们……', `MaleText_loc5`='那些...', `MaleText_loc7`='Esos...' WHERE `ID`=24633;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저놈들은 겁쟁이야.', `MaleText_loc4`='他们是胆小鬼。', `MaleText_loc5`='他們是懦夫。', `MaleText_loc7`='Esos son cobardes.' WHERE `ID`=24634;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겁쟁이 돼지인 건가요, 아빠?', `MaleText_loc4`='他们是胆小的猪？', `MaleText_loc5`='牠們是膽小的豬嗎，爸爸?', `MaleText_loc7`='¿Son unos cerdos cobardes, papi?' WHERE `ID`=24635;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 고개를 흔듭니다.', `MaleText_loc4`='%s摇了摇头。', `MaleText_loc5`='%s搖了搖頭。', `MaleText_loc7`='%s agita la cabeza.' WHERE `ID`=24636;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니다, 내 아들아. 녀석들은 얼라이언스 군인이다. 우리의 원수지.', `MaleText_loc4`='不对，儿子。他们是联盟的士兵，是我们不共戴天的敌人。', `MaleText_loc5`='不是，我親愛的孩子，他們是聯盟的士兵。我們的死敵。', `MaleText_loc7`='No, sangre de mi sangre, son soldados de la Alianza. Nuestros enemigos acérrimos.' WHERE `ID`=24637;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 아빠, 그럼 저들은 뭘 겁내는 거죠? 왜 여기 있는 건가요?', `MaleText_loc4`='可是他们在怕什么呢？他们到这儿来做什么？', `MaleText_loc5`='可是，爸爸，他們在怕些什麼?他們為什麼在這裡?', `MaleText_loc7`='Pero papi, ¿de qué tienen miedo? ¿Por qué están aquí?' WHERE `ID`=24638;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='녀석들은 자신의 고향을... 자신의 가족을 저버렸기 때문에 여기 있는 거란다...', `MaleText_loc4`='因为他们不愿意保卫自己的家园……和家人……', `MaleText_loc5`='他們在此的原因是，不願意守護自己的家園...自己的家人...', `MaleText_loc7`='Están aquí porque no desean defender sus hogares... a sus familias...' WHERE `ID`=24639;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모든 걸 내던지고 제 발로 우리에게 항복한 거지.', `MaleText_loc4`='他们放弃了抵抗，缴械投降——完全出于自愿。', `MaleText_loc5`='他們 - 自願的 - 放棄一切，向我們投誠。', `MaleText_loc7`='Han cedido y se han rendido, voluntariamente, ante nosotros.' WHERE `ID`=24640;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들은 죽는 걸 두려워하고 있단다, 우그소르.', `MaleText_loc4`='乌格索，他们怕死。', `MaleText_loc5`='烏格索，他們怕死。', `MaleText_loc7`='Ug''thor, tienen miedo a morir.' WHERE `ID`=24641;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 머리를 긁적입니다.', `MaleText_loc4`='%s抓了抓脑袋。', `MaleText_loc5`='%s抓抓自己的頭。', `MaleText_loc7`='%s se rasca la cabeza.' WHERE `ID`=24642;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난... 이해가 안 되는데요, 아빠.', `MaleText_loc4`='我……我不太明白，爸爸。', `MaleText_loc5`='我...我不懂，爸爸。', `MaleText_loc7`='No... no entiendo, papi.' WHERE `ID`=24643;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 가슴을 펴고 발돋움을 합니다.', `MaleText_loc4`='%s挺起胸膛，踮起脚尖。', `MaleText_loc5`='%s挺起了他的胸膛，踮起腳尖站著。', `MaleText_loc7`='%s saca pecho y se pone de puntillas.' WHERE `ID`=24644;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='록타르 오가르, 아빠!', `MaleText_loc4`='Lok''tar ogar！', `MaleText_loc5`='不勝即亡，爸爸!', `MaleText_loc7`='¡Lok''tar ogar, papi!' WHERE `ID`=24645;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 웃습니다.', `MaleText_loc4`='%s笑了。', `MaleText_loc5`='%s笑了。', `MaleText_loc7`='%s ríe.' WHERE `ID`=24646;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 우그소르. 승리가 아니면 죽음을!', `MaleText_loc4`='乌格索，这就是真理啊。要么胜利，要么死亡！', `MaleText_loc5`='就是這樣，烏格，不勝即死!', `MaleText_loc7`='Eso es, Ug. ¡Victoria o muerte!' WHERE `ID`=24647;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[서투른 공용어] 들어, 꼬맹이, 겁쟁이들! 꼬맹이들, 죽어라! 자유 위해 죽어라!', `MaleText_loc4`='[不流畅的通用语] 懦夫，听见了吗？死！为自由而死！', `MaleText_loc5`='[操著不流利的普通語]聽到沒，男人，你這懦夫?男人就是要死!男人為了自由而死!', `MaleText_loc7`='[En lengua común con dificultad] ¿Escuchar chico, cobardes? ¡Chico morir! ¡Chico morir por la libertad!' WHERE `ID`=24648;
