UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대장님... 네룹아르가 공중 공격을 합니다! 수... 수백 마리가 남쪽에서 우리 방어선 위로 몰려오고 있습니다!', `MaleText_loc4`='上尉……尼鲁巴尔蛛怪发动了空袭！有好几百只！他们来了……从南面扑向我们的防御线！', `MaleText_loc5`='上尉...奈幽巴的飛蟲來了!好幾百隻!從...從南邊!遠比我們的守軍多!', `MaleText_loc7`='Capitán... ¡Voláteres Nerub''ar! ¡Cientos de ellos! Vienen... ¡Vienen desde el Sur! ¡A las defensas!', `FemaleText_loc1`='대장님... 네룹아르가 공중 공격을 합니다! 수... 수백 마리가 남쪽에서 우리 방어선 위로 몰려오고 있습니다!', `FemaleText_loc4`='上尉……尼鲁巴尔蛛怪发动了空袭！有好几百只！他们来了……从南面扑向我们的防御线！', `FemaleText_loc5`='上尉...奈幽巴的飛蟲來了!好幾百隻!從...從南邊!遠比我們的守軍多!', `FemaleText_loc7`='Capitán... ¡Voláteres Nerub''ar! ¡Cientos de ellos! Vienen... ¡Vienen desde el Sur! ¡A las defensas!' WHERE `ID`=24653;
