UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들을 상대할 준비를 해야겠군... 우리에게 알려주느라 수고했네.', `MaleText_loc4`='我们必须立即备战……你的预警非常及时。', `MaleText_loc5`='我們會準備好對付他們的...通報我們這件事做的很好。', `MaleText_loc7`='Estaremos preparados… Has hecho bien en avisarnos.' WHERE `ID`=24656;
