UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오직 그대만이 카가니슈에게서 나를 구할 수 있다네, $n.', `MaleText_loc4`='$n，只有你能从卡加尼舒的魔掌中救出我。', `MaleText_loc5`='$n，只有你能從卡甘尼蘇的手上把我救出來。', `MaleText_loc7`='Solo tú puedes salvarme de Kajanishu, $n.' WHERE `ID`=24661;
