UPDATE `locales_broadcast_text` SET `MaleText_loc1`='임페리안에게 휴전할 의사가 있다고 알려라. 하지만 먼저 물보라가 내 땅에서 물장난을 그만둬야 할 것이야!', `MaleText_loc4`='转告因波莉安，我会考虑停战的提议。但是卓恩必须先停止对我们的攻击！', `MaleText_loc5`='告訴英波里安，我會考慮停止敵對的態度。但是，首先，翻湧必須停止他波濤般的入侵，來阻止我現身!', `MaleText_loc7`='Dile a Imperean que consideraré un cese de las hostilidades. ¡Pero primero, Xurn tiene que abandonar sus intromisiones acuáticas en mi colina!' WHERE `ID`=24667;
