UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 말에... 따르겠다. 잿불바람이 내 웅덩이를 계속 끓여대지만 않는다면 휴전에 응하기로 하지.', `MaleText_loc4`='我……投降。只要西米尔不再侵犯我的地盘，我愿意休战。', `MaleText_loc5`='我...我投降。只要沸滾同意不要煮沸我的池子，我同意休戰。', `MaleText_loc7`='Me… rindo. Siempre y cuando Cocer acepte dejar de hacer que mi charca hierva, estaré de acuerdo con el armisticio.' WHERE `ID`=24670;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 내 앞에서 사라져라. 내 눈에 다시 띌 만큼 어리석지는 않겠지.', `MaleText_loc4`='你，立即从我的视线中消失。最好别让我再看见你。', `MaleText_loc5`='馬上從我面前滾開。要是你識相就不要在我眼前出現。', `MaleText_loc7`='Ahora, desaparece de mi vista. Si sabes lo que te conviene, no volverás a presentarte ante mí.' WHERE `ID`=24671;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드 군대를 박살 내는 건 커다란 기쁨이지. 갈기갈기... 조각조각...', `MaleText_loc4`='我很乐意与部落的军队交手……将他们撕得粉碎……', `MaleText_loc5`='我很樂意將部落的軍隊四分五裂...從頭到腳、一片一片的撕開...', `MaleText_loc7`='Disfrutaré mucho destrozando las fuerzas de la Horda… miembro a miembro y pieza a pieza...' WHERE `ID`=24672;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 역겨운 놈의 시체를 리치 왕의 군대가 똑똑히 보게 하라! 호드는 호락호락하지 않다는 걸 알려 줘라!', `MaleText_loc4`='让巫妖王的军队瞧瞧看看这具尸体吧，让他们明白部落绝不手软！', `MaleText_loc5`='讓巫妖王大軍好好看著這具可憐蟲的屍首，讓他們曉得，部落不會手下留情的!', `MaleText_loc7`='¡Dejad que las tropas del Rey Exánime observen el cadáver de este desdichado y que se den cuenta de que la Horda no cederá!' WHERE `ID`=24673;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모여라, 제군들! 다함께 놈들의 등껍질에서 전리품을 챙겨라!', `MaleText_loc4`='士兵，集合！去敌人的尸体上掠夺战利品吧！', `MaleText_loc5`='大兵，集合了!帶著你們從敵人身上拿來的甲殼戰利品集合!', `MaleText_loc7`='¡Reúnanse soldados! ¡Reúnanse y tomen sus trofeos de entre los caparazones del enemigo!' WHERE `ID`=24674;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 감히 내게 덤비느냐?!', `MaleText_loc4`='你竟敢招惹我？！', `MaleText_loc5`='誰這麼大膽?!', `MaleText_loc7`='¡¿Quién se atreve?!' WHERE `ID`=24675;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈의 뼈다귀를 재로 만들어주마!', `MaleText_loc4`='我要把你锉骨扬灰！', `MaleText_loc5`='我要把你的骨頭燒成灰!', `MaleText_loc7`='¡Convertiré tus huesos en ceniza!' WHERE `ID`=24676;
