UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파도로 네놈을 박살 내주마!', `MaleText_loc4`='我要把你碾碎！', `MaleText_loc5`='我會用千鈞巨浪沖垮你!', `MaleText_loc7`='¡Te aplastaré bajo el peso de mis olas!' WHERE `ID`=24679;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 내 웅덩이에 기어들어와?!', `MaleText_loc4`='你竟敢跨进我的地盘！', `MaleText_loc5`='膽敢闖盡我的池子裡?!', `MaleText_loc7`='¡¿Osas entrar en mi poza!?' WHERE `ID`=24680;
