UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈의 시체를 물고기에게 던져주지.', `MaleText_loc4`='我要拿你的尸体去喂鱼。', `MaleText_loc5`='你的屍骨會被我的魚群分食。', `MaleText_loc7`='Tu cadáver alimentará a mis peces.' WHERE `ID`=24682;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오, 이런... 놈들이 선견자님의 영혼을 구속해버렸군!', `FemaleText_loc4`='噢不……他们禁锢了他的灵魂！', `FemaleText_loc5`='不好了...他們把他的靈魂束縛了起來!', `FemaleText_loc7`='¡Oh no... han encadenado su espíritu!' WHERE `ID`=24683;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서쪽의 정찰 임무를 진행하는 동안 와이번을 여럿 잃었소. 스컬지들은 첩자로 보이는 자들을 무자비하게 공격한다오.$B$B다행스럽게도 조련사의 목숨만 걸면 되는 방법이 있다오. 이 방법으로 나삼의 평원을 건넌 자들 중 30% 정도는 살아남았소이다. 와이번을 이용했을 때보다 생존율이 30%나 증가한 거지!', `MaleText_loc4`='在西部的侦察行动中，我们损失了许多出色的双足飞龙。天灾军团对任何可疑的探子都不会手下留情。$B$B幸运的是，我想出了解决办法，虽然这样可能会威胁到骑手的性命。你要知道，在纳萨姆平原的侦察行动中，骑手的生还率已经高达30%了。而我们之前使用双足飞龙的时候，简直可以说是有去无回！', `MaleText_loc5`='我們在偵察西方的時候損失了不少雙足飛龍。天譴軍團對於任何可能是間諜的生物都發出無情的攻擊。$B$B所幸，我想出了一個解決之道，只拿騎乘者的性命冒險。搭渡船通過納森平原一般來講有30%的生還機率，這比我們之前使用雙足飛龍時，可是足足提升了30%呢!', `MaleText_loc7`='Hemos perdido a muchos de nuestros jinetes del viento en misiones de exploración al oeste. La Plaga no tiene piedad en sus ataques contra los posibles espías.$B$BPor suerte, he encontrado una solución que solo pone en peligro la vida del jinete. La tasa de supervivencia entre los que han sido transportados hasta las Llanuras de Nasam es del 30%. ¡Eso es un 30% más que cuando estábamos usando jinetes del viento!' WHERE `ID`=24684;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가로쉬의 상륙지로 보내 주십시오, 야니.', `MaleText_loc4`='亚尼，送我到加尔鲁什码头吧。', `MaleText_loc5`='送我去卡爾洛斯臺地，亞尼。', `MaleText_loc7`='Envíame al Desembarco de Garrosh, Yanni.', `FemaleText_loc1`='가로쉬의 상륙지로 보내 주세요, 야니.', `FemaleText_loc4`='亚尼，送我到加尔鲁什码头吧。', `FemaleText_loc5`='送我去卡爾洛斯臺地，亞尼。', `FemaleText_loc7`='Envíame al Desembarco de Garrosh, Yanni.' WHERE `ID`=24685;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='선견자님! 다시 만나뵙다니 정말 기쁩니다!', `FemaleText_loc4`='先知！很高兴能与你重逢！', `FemaleText_loc5`='先知!再次看見你真讓我開心!', `FemaleText_loc7`='¡Clarividente! ¡Me alegra tanto volver a verte!' WHERE `ID`=24686;
