UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 이제 좀 쉬어야겠군. 여러 가지로 도와줘서 고맙네.', `MaleText_loc4`='我得好好休息了。感谢你给予我的帮助。', `MaleText_loc5`='如今，我必須休息。感謝你所做的一切。', `MaleText_loc7`='Y ahora he de descansar. Gracias por todo lo que has hecho.' WHERE `ID`=24688;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 생명줄을 해치지 마라!', `MaleText_loc4`='不准伤害母蛾！', `MaleText_loc5`='別傷了生命賜予者!', `MaleText_loc7`='¡No hacer daño al dador de vida!' WHERE `ID`=24689;
