UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생명줄을 보호하라!', `MaleText_loc4`='保护母蛾！', `MaleText_loc5`='完美的生命賜予者!', `MaleText_loc7`='¡Proteger dador de vida!' WHERE `ID`=24691;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$C|1이여;여;, 좀 물어볼 게 있네.', `MaleText_loc4`='$C，我要请你帮个忙。', `MaleText_loc5`='$C，我有一些事要請教你。', `MaleText_loc7`='$C, tengo que pedirte algo.' WHERE `ID`=24692;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 이미 명예를 잃었네. 마그모스에서 선견자님과 함께 죽었어야 했단 말이네.', `MaleText_loc4`='我太可耻了。我应该和先知一起死在犸格莫斯的。', `MaleText_loc5`='這真是奇恥大辱。我早該跟著先知一起死在瑪格默斯的。', `MaleText_loc7`='Soy una deshonra. Debí haber muerto con el clarividente en Magmoth.' WHERE `ID`=24693;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 %s|1을;를; 포획할 수 있습니다.', `MaleText_loc4`='%s可以被捕获了。', `MaleText_loc5`='%s可以被捕獲了。', `MaleText_loc7`='Ahora %s puede ser capturado.' WHERE `ID`=24694;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생명줄을 지켜라!', `MaleText_loc4`='保护母蛾！', `MaleText_loc5`='保護生命賜予者!', `MaleText_loc7`='¡Proteger dador de vida!' WHERE `ID`=24695;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭔가... 다르군.', `MaleText_loc4`='我感觉……有些异样。', `MaleText_loc5`='我感覺...不同了。', `MaleText_loc7`='Me siento... diferente.' WHERE `ID`=24696;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선견자님, 살아계신 걸 보니 기쁩니다.', `MaleText_loc4`='先知，你还活着！我真是太高兴了。', `MaleText_loc5`='先知，很高興看到你還活著。', `MaleText_loc7`='Clarividente, que bien que estés vivo.' WHERE `ID`=24697;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 웃으며 자리에 앉아 편히 쉽니다.', `MaleText_loc4`='%s笑了笑，坐下来享受这难得的安宁。', `MaleText_loc5`='%s一邊微笑著，一邊坐下好好的休息一下。', `MaleText_loc7`='%s sonríe y se sienta para disfrutar de un más que merecido descanso.' WHERE `ID`=24698;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선견자님, 살아계셨군요!', `MaleText_loc4`='先知，你还活着！', `MaleText_loc5`='先知，你活下來了!', `MaleText_loc7`='¡Clarividente, estás vivo!' WHERE `ID`=24699;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여건이 허락하면 더 많은 가르침을 주시기 바랍니다.', `FemaleText_loc4`='如果你准备好了，我就要进行下一阶段的训练了。', `FemaleText_loc5`='當你準備好以後，我很期待未來的訓練。', `FemaleText_loc7`='Me gustaría seguir entrenando cuando estés en condiciones.' WHERE `ID`=24700;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고지, 도구도 없이 뭘 하라는 말이야!', `MaleText_loc4`='格尔基，没有工具我怎么干活！', `MaleText_loc5`='沒有工具的話，你是要我們怎麼做啊，寇治!', `MaleText_loc7`='¿Qué se supone que voy a hacer sin herramientas, Garganta?' WHERE `ID`=24701;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제대로 된 도구가 없으면 전차같이 복잡한 건 못 고친단 말이야!', `MaleText_loc4`='没有合适的工具，我可没办法修理坦克这类构造复杂的装置！', `MaleText_loc5`='老兄，要是沒有適當的裝備的話，要修理像坦克一樣複雜的東西是不可能的!', `MaleText_loc7`='¡No puedo arreglar algo tan complejo como un tanque sin el material adecuado, colega!' WHERE `ID`=24702;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전쟁노래 부족에게선 아무 연락도 없었나? 조만간 보급품을 받을 수는 있는 거냔 말이야?', `MaleText_loc4`='有什么消息吗？我们的补给物资快到了吧？', `MaleText_loc5`='你從戰歌堡打聽到什麼風聲嗎?馬上就能拿到補給品了嗎?', `MaleText_loc7`='¿Tienes noticias de Grito de Guerra? ¿Vamos a recibir suministros pronto?' WHERE `ID`=24703;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으, 집에 가고 싶어... 제복을 벗고 호드와 인연을 끊고 싶단 말이야!', `MaleText_loc4`='我想回家……脱下这身军装，离开部落！', `MaleText_loc5`='我想要回家...脫掉這身制服離開部落!', `MaleText_loc7`='Quiero irme a casa… ¡Quitarme este uniforme y abandonar la Horda!' WHERE `ID`=24704;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 열심히 일하지 않으면 가서 두들겨 패 주겠다, 이 일꾼 녀석들!', `MaleText_loc4`='给我卖力工作，不然我揍死你们！', `MaleText_loc5`='你們這些苦工再不工作，我就要過去痛扁你們啦!', `MaleText_loc7`='¡Peones, trabajad con más ganas o iré ahí y os daré una paliza!' WHERE `ID`=24705;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 전초기지는 아직 미완성이란 말이다! 말리고스와 푸른용군단이 습격하면 어쩔 셈이냐?', `MaleText_loc4`='前哨站的建设尚未完工！万一玛里苟斯和蓝龙军团发动袭击怎么办？', `MaleText_loc5`='崗哨還沒準備好!要是瑪里苟斯和他的藍龍軍團攻過來怎麼辦?', `MaleText_loc7`='¡Esta avanzada no está lista! ¿Qué pasará si Malygos y el Vuelo Azul deciden atacar?' WHERE `ID`=24706;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서둘러라! 얼라이언스보다 먼저 숄라자르 분지에 도착해야 한다!', `MaleText_loc4`='快点！我们必须抢在联盟之前进入索拉查盆地！', `MaleText_loc5`='工作快一點!我們一定要趕在聯盟之前推進休拉薩盆地!', `MaleText_loc7`='¡Trabajad más deprisa! ¡Debemos atacar la Cuenca de Sholazar antes que la Alianza!' WHERE `ID`=24707;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='속도가 너무 느려, 일꾼 녀석들아. 제 속도가 날 때까지 식량을 반으로 줄이겠다!', `MaleText_loc4`='进度落后啊！你们给我卖力点，不然今天的伙食减半！', `MaleText_loc5`='你們這些苦工的進度落後了。在你們趕上進度以前，糧食統統減半!', `MaleText_loc7`='Tus peones se están quedando atrás. ¡Media ración hasta que retomen el ritmo!' WHERE `ID`=24708;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희같이 형편없는 일꾼 놈들은 처음 본다! 몇 대 맞아야 정신을 차리겠나?', `MaleText_loc4`='从来没见过这么差劲的苦工！我的训诫靴哪儿去了？', `MaleText_loc5`='這真的是一群我所看過最可悲的苦工了!我的迴力靴咧?', `MaleText_loc7`='¡Este es el grupo de peones más patético que he visto en mi vida! ¿Dónde está mi botarang?' WHERE `ID`=24709;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맹세하건대 더 빨리 일하지 않으면 네놈들을 내 늑대 밥으로 만들겠다!', `MaleText_loc4`='要是你再拖拖拉拉的，我就送你去喂狼！', `MaleText_loc5`='我發誓，你們要是工作不加快，我會把你們拿去餵座狼!', `MaleText_loc7`='¡Te juro que como no empieces a trabajar más rápido, te voy a entregar como alimento para mi huargo!' WHERE `ID`=24710;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희는 졸병이라 자존심도 없느냐? 전쟁노래 요새에서 지원군이 올 때까지 이 전초기지를 정비하지 못하면 그 가치없는 몸뚱이는 모두 무덤 속에 눕게 될 것이다!', `MaleText_loc4`='你们这帮蠢货就没有一点自尊心吗？要么在战歌要塞的援军抵达之前修好哨站，要么就等死吧！', `MaleText_loc5`='你們這些蠻兵沒有榮譽感嗎?你們最好把這個崗哨準備好，給那些從戰歌堡來的援軍使用，要不然你們這些沒有用的屍體就給我裝滿整座墓園!', `MaleText_loc7`='¿Es que los brutos no tienen orgullo? ¡Si esta avanzada no está preparada para recibir los refuerzos del Bastión Grito de Guerra, sus cadáveres llenarán el cementerio!' WHERE `ID`=24711;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='5분간 휴식. 하하, 농담이다! 너희가 무슨 얼라이언스인 줄 아나?', `MaleText_loc4`='休息五分钟吧。哈哈，开个玩笑！你以为我们是谁，联盟吗？！', `MaleText_loc5`='來個五分鐘休息吧。哈哈，開玩笑的啦!你以為這是什麼，聯盟嗎?', `MaleText_loc7`='Hagamos un descanso de cinco minutos. ¡Ja, ja, ja, es broma! ¿Qué os habéis creído que es esto? ¿La Alianza?' WHERE `ID`=24712;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가로쉬의 상륙지와 팔에아 모두 저 안개 때문에 사라져버렸네. 여기에 남을 만큼 정신 나간 자들은 우리밖에 없단 말이야!', `MaleText_loc4`='迷雾已经蔓延到了加尔鲁什码头和帕尔依。我们却还留在这里，真是疯了！', `MaleText_loc5`='卡爾洛斯臺地和帕雷亞兩地被大霧所橫掃，我們是少數幾個瘋到留下來的，老兄!', `MaleText_loc7`='Tanto Desembarco de Garrosh como Pal''ea fueron barridos por la niebla. ¡Somos los únicos suficientemente locos como para quedarnos aquí, colega!' WHERE `ID`=24713;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='피즈크랭크는 사사건건 간섭이고 장비도 제대로 없는데, 나인들 어떻게 일을 제대로 하겠어요?', `FemaleText_loc4`='菲兹兰克死命地催我，可我手里没有任何工具，这叫我怎么做事啊？！', `FemaleText_loc5`='嘶軸整天就是緊盯著我，然後所有的工具都不在我手邊，這樣是要我怎麼做事嘛?!', `FemaleText_loc7`='¿Cómo quieres que trabaje sin mis cosas y con Palanqueta resoplándome en el cogote?' WHERE `ID`=24714;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다 됐어요. 짜잔! 잘못될 리 없는 크래프티의 초고급 축소 광선총입니다!', `FemaleText_loc4`='伙计，好啦。这台超级缩小射线枪原型机可供使用啦！', `FemaleText_loc5`='看著吧，伙計，一把卡芙緹的超進階初體版微縮光束槍為你效勞!', `FemaleText_loc7`='Allá vamos. ¡Un rayo reductor prototípico ultraavanzado de Ingeniosa a tu servicio!' WHERE `ID`=24715;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 해안에 서린 안개는 스컬지 때문에 생긴 것이 아닙니다. 스컬지들이 여기로 오지 않는 것을 보면 놈들도 이 안개를 두려워하는 것 같습니다.$B$B보다시피 이 안개는 살아 있지요. 저 꿈틀거리는 대기 속에는 죽음이 도사리고 있습니다... $B$B당신도 저 속으로 들어갔다간 사라져버리고 말 겁니다. 안개에 먹혀버릴 거란 말입니다!$B$B저 안갯속으로 들어갔다가 살아 돌아온 자는 한 번도 보지 못했습니다.', `MaleText_loc4`='你在海岸上目睹的一切并不是天灾军团造成的。事实上他们也害怕这片迷雾——你也瞧见了，连天灾军团都不肯涉足此地。$B$B朋友，迷雾中危机四伏。死亡的气息就萦绕在那片雾气中……$B$B一旦你踏入禁地，就会付出生命的代价。迷雾会吞噬你！$B$B我们还没有见过谁能活着从迷雾中走出来的。', `MaleText_loc5`='你在這個海岸所見的一切並非天譴軍幹得好事。事實上，我們相信天譴軍也很怕這股大霧 - 也是為何他們進不來的原因。$B$B懂了嗎，這陣霧是活的，朋友。在那些輕飄飄的霧縷中潛藏著死亡...$b$b要是你踏入它的魔爪，你會消失。這陣霧會殺了你!$B$B我從沒見過有人能從這陣霧中活著回來。', `MaleText_loc7`='Lo que ves en esta costa no es fruto de la Plaga. De hecho, creemos que la Plaga también teme a esta niebla... puede que ese sea el motivo por el que no vienen aquí.$B$BVerás, la niebla está viva, colega. Dentro de esos zarcillos de aire yace la muerte...$B$BSi entras en sus dominios, te desvanecerás. ¡La niebla te llevará!$B$BNunca hemos visto a nadie regresar de la niebla con vida.' WHERE `ID`=24716;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타 버려라, 땅에 사는 것들아! 불타버려라!', `MaleText_loc4`='燃烧吧，旱鸭子！燃烧吧！', `MaleText_loc5`='燒呀，陸地人!燒呀!', `MaleText_loc7`='¡Arde, habitante de la tierra! ¡ARDE!' WHERE `ID`=24717;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 막 이놈들을 정복하기 시작했을 뿐이다... 재미를 볼 시간은 아직 많이 있다.', `MaleText_loc4`='我们的征服之旅才刚刚开始……以后有的是乐子。', `MaleText_loc5`='征服這些人才不過剛開始而已...還有很多時間可以好好搞些樂子。', `MaleText_loc7`='La subyugación de este pueblo no ha hecho más que comenzar... aún tenemos tiempo para jugar y divertirnos.' WHERE `ID`=24718;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안갯속에서 재가 되어라!', `MaleText_loc4`='在迷雾中化为灰烬吧！', `MaleText_loc5`='變成霧中的灰燼吧!', `MaleText_loc7`='¡Convertíos en cenizas en la niebla!' WHERE `ID`=24719;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 도착한 뒤로, 제일 끔찍한 악몽에서나 느낄 법한 두려움을 마주해 왔지만, 저 안개 뒤에 있는 놈들은 그 어떤 방법으로도 대비할 수 없었소.$B$B<고개를 끄덕이는 무투>$B$B저 안개 너머, 여기서 몇 미터 되지도 않는 곳에 크발디르라 하는 피에 굶주린 괴물들이 있소. 그 안갯속에서 돌아온 사람은 아무도 없었을뿐더러, 안개가 밀려들 때 원래 정박지에 있던 사람 중에 빠져나온 이도 거의 없다오. 그 후로 헬스크림은 그 지역을 몹쓸 곳이라 선언했다오. 들어가겠다면 그만큼 위험을 감수해야 할 것이오...', `MaleText_loc4`='自打我来到这里，就目睹了原本只存在于噩梦中的恐怖景象，但是没有什么能比潜伏在迷雾中的可怕生物更让人毛骨悚然了。$B$B<穆图点了点头。>$B$B就在距离我们几码的雾气中，盘踞着一种名叫克瓦迪尔的噬血生物。迷雾席卷码头时，只有少数的幸运儿捡回了性命。从那之后，但凡进入迷雾的人无一生还。地狱咆哮也因此将这里划为禁区。如果你坚持要进去的话，后果自负……', `MaleText_loc5`='到這以後，原本一直困擾我的最黑暗的惡夢，如今成真了，但除此之外沒有別的東西能讓我準備好面對霧中的惡獸。$B$B<穆圖點點頭。>$B$B通過這片大霧，就在離我們不遠的地方，有著一頭名叫科瓦迪爾的嗜血生物，沒有人能從這片霧中返回，同樣的，原本就在臺地上的人，當這片霧升起之後，也鮮少有逃出來的。從此以後，地獄吼便譴責這塊地方。如果要進去，後果只有自己負責了...', `MaleText_loc7`='Desde que llegué aquí he visto horrores que antes solo habitaban en mis peores pesadillas, pero nada podría haberme preparado para lo que se oculta tras la niebla.$B$B<Mootoo asiente.>$B$BAl otro lado de esa niebla, a solo unos metros de aquí, se encuentran unas criaturas sedientas de sangre conocidas como Kvaldir. Nadie ha regresado de la niebla y pocos de los que habitaban aquí cuando se formó la niebla lograron huir. Desde entonces la zona ha sido declarada no habitable por Grito Infernal. Entra bajo tu propia responsabilidad...' WHERE `ID`=24720;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저... 저기...$B$B<벌벌 떠는 무투의 딸>$B$B절 구해주러 오셨나요?', `FemaleText_loc4`='我……你是……$B$B<小穆图浑身颤抖。>$B$B你是来救我的吗？', `FemaleText_loc5`='我...你是...$b$b<穆圖渾身發抖。>$B$B你是來救我的嗎?', `FemaleText_loc7`='Yo...tú...$B$B<Mootoo tiembla.>$B$B¿Estás aquí para salvarme?' WHERE `ID`=24721;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='독사의 아귀호가 투스카르 불꽃에 휩싸입니다!', `MaleText_loc4`='毒蛇之喉被烈焰吞没了！', `MaleText_loc5`='巨蛇之喉被巨牙海民之火吞噬了!', `MaleText_loc7`='¡El fuego de los colmillarr está engullendo Las Fauces de la Sierpe!' WHERE `ID`=24722;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쿠르 드라카르호가 투스카르 불꽃에 휩싸입니다!', `MaleText_loc4`='库尔达卡被烈焰吞没了！', `MaleText_loc5`='科·德拉卡被巨牙海民之火吞噬了!', `MaleText_loc7`='¡El Kur Drakkar es engullido por el fuego de los colmillarr!' WHERE `ID`=24723;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보르의 망치호가 투스카르 불꽃에 휩싸입니다!', `MaleText_loc4`='伯尔之锤被烈焰吞没了！', `MaleText_loc5`='伯爾之錘被巨牙海民之火吞噬了!', `MaleText_loc7`='¡El Martillo de Bor es engullido por el fuego de los colmillarr!' WHERE `ID`=24724;
