UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 정수를 손에 넣겠다고? 오너라. 네가 돌과 얼음만큼 단단한지 어디 한번 보자!', `MaleText_loc4`='你想夺走我的原始精华？来吧，让我瞧瞧你是否像冻石那般坚硬！', `MaleText_loc5`='你想要拿走我的元神精華?來呀，讓我瞧瞧你是否像岩石與寒冰一般堅硬!', `MaleText_loc7`='¿Quieres apoderarte de mi esencia fundamental? ¡Ven, veamos si eres tan duro como la piedra y el hielo!' WHERE `ID`=24726;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꽁꽁 얼어 부서져라. 살진 네 몸은 그런 대접을 받는 게 어울리지.', `MaleText_loc4`='像你这样的血肉之躯，被冻僵之后就能很轻易地结果你的性命。这就是你的下场。', `MaleText_loc5`='冰凍、粉碎，這是你那血肉之軀唯一的下場。', `MaleText_loc7`='Congelarlo y destruirlo. Eso es todo para lo que sirve tu cadáver.' WHERE `ID`=24727;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여긴 네가 올 곳이 아니다. 죽어라!', `MaleText_loc4`='这里不欢迎你。去死吧！', `MaleText_loc5`='你在此不受歡迎，死吧!', `MaleText_loc7`='No eres $gbienvenido:bienvenida; aquí. ¡Muere!' WHERE `ID`=24728;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 존재가 이 땅의 균형을 깨트리고 있다. 너는 반드시 사라져야 해!', `MaleText_loc4`='你打破了这里的平衡。去死吧！', `MaleText_loc5`='你的出現讓這片大地失去了平衡，你必須要被剷除!', `MaleText_loc7`='Tu presencia desequilibra la tierra. ¡Hay que eliminarte!' WHERE `ID`=24729;
