UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물러나세요! 이건 진짜 불이라 화상을 입을 수 있다니까요!', `MaleText_loc4`='退后点！我拿着真正的火焰，它真的会烧伤你！', `MaleText_loc5`='後退!我在處理的是真正的火焰，這可是真的會燒傷你的喔!', `MaleText_loc7`='¡Atrás! ¡Esto es fuego de verdad y puede quemaros!' WHERE `ID`=24731;
