UPDATE `locales_broadcast_text` SET `MaleText_loc1`='옷을 벗겨 냅니다.', `MaleText_loc4`='拿走他们的衣物。', `MaleText_loc5`='拿走他們的服裝。', `MaleText_loc7`='Coger sus ropas.', `FemaleText_loc1`='옷을 벗겨 냅니다.', `FemaleText_loc4`='拿走他们的衣物。', `FemaleText_loc5`='拿走他們的服裝。', `FemaleText_loc7`='Coger sus ropas.' WHERE `ID`=24733;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='키잡이가 네놈을 맞이해주마!', `MaleText_loc4`='舵手奥拉布斯来对付你了！', `MaleText_loc5`='舵手來也!', `MaleText_loc7`='¡El timonel viene a por ti!' WHERE `ID`=24734;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어리석은 녀석! 말리고스 님의 종은 적을 돕느니 스스로 목숨을 끊을 것이다...', `MaleText_loc4`='可悲的蠢货！玛里苟斯的仆人宁死也不会为敌人效劳……', `MaleText_loc5`='可悲的蠢蛋!瑪里苟斯的奴僕死的比通敵者快...', `MaleText_loc7`='¡Pobre idiota! Un servidor de Malygos preferiría morir antes que ayudar al enemigo...' WHERE `ID`=24735;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으히히히! 어디 계속해 보시지, $c! 절대로 말하지 않겠다!', `MaleText_loc4`='啊啊！$c，有什么手段尽管使出来吧！我什么也不会说的！', `MaleText_loc5`='呃啊!你就這麼一點能耐嗎，$c!我什麼也不會說的!', `MaleText_loc7`='¡Aargh! ¡Demuestra lo que sabes hacer, $c! ¡No te contaré NADA!' WHERE `ID`=24736;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으히히하하하! 풀어줘! 난 아는 게 없어! 정말이다!', `MaleText_loc4`='我想找人好好聊聊！', `MaleText_loc5`='啊啊啊!放了我!我發誓我對你一點用處也沒有!', `MaleText_loc7`='¡Aahhhh! ¡Libérame! No te serviré de nada. ¡Lo juro!' WHERE `ID`=24737;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만! 간지러워 죽겠어, 그만해 줘. 제발...', `MaleText_loc4`='你有什么要问我的吗？', `MaleText_loc5`='停手!我求你，請你停手。拜託...', `MaleText_loc7`='¡Para! Te lo ruego, por favor, para. Por favor...' WHERE `ID`=24738;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으히히... 알았어! 내가 졌다. 네놈들의 그 고귀하신 대마법사는 봉인된 공중 감옥에 갇혀 있다. 구하려고 해 봤자 열쇠는 살란드 님께서 직접 지니고 계시다. 네놈들은 바보짓을 하는 거야!', `MaleText_loc4`='告诉你吧，我们已经封印了那位尊贵的大法师。就算你能找到她，可钥匙在莎尔兰德手中。你不过是在白费力气！', `MaleText_loc5`='好吧!我被打敗了。你珍貴的大法師被關在某座監獄裡，凌空建起並且層層封印住。即使你試著要接近她，沙爾倫她親自看守著鑰匙。你的任務真愚蠢!', `MaleText_loc7`='¡Basta! He perdido. Tu querida archimaga está en una prisión, elevada y sellada. Incluso si consigues llegar hasta ella, la propia Salrand tiene la llave. ¡Tu misión es un disparate!' WHERE `ID`=24739;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으히히히... 너무하는군! 내가 아는 건 다 말했다. 왜 날 계속 괴롭히는 거지?', `MaleText_loc4`='够了！我知道的事都告诉你了。你再逼问下去也问不出什么了！', `MaleText_loc5`='夠了!我把我所知道的都告訴你了。繼續虐待我一點意義也沒有!', `MaleText_loc7`='¡Basta! Te he contado todo lo que sé. ¡Tu incesante abuso no tiene sentido!' WHERE `ID`=24740;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래! 그 보잘것없는 나가 동상은 뭉개버려라.', `MaleText_loc4`='对！打碎那尊恶心的纳迦雕像。', `MaleText_loc5`='對!毀了那座討厭的納迦雕像。', `MaleText_loc7`='¡Sí! Destroza la lastimosa estatua naga.', `FemaleText_loc1`='그래! 그 보잘것없는 나가 동상은 뭉개버려라.', `FemaleText_loc4`='对！打碎那尊恶心的纳迦雕像。', `FemaleText_loc5`='對!毀了那座討厭的納迦雕像。', `FemaleText_loc7`='¡Sí! Destroza la lastimosa estatua naga.' WHERE `ID`=24741;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아즈샤라와 그녀의 거짓말에 파멸을!', `MaleText_loc4`='让艾萨拉女王带着她的谎言去死吧！', `MaleText_loc5`='艾薩拉和她的謊言都去死吧!', `MaleText_loc7`='¡Muerte a Azshara y sus mentiras!', `FemaleText_loc1`='아즈샤라와 그녀의 거짓말에 파멸을!', `FemaleText_loc4`='让艾萨拉女王带着她的谎言去死吧！', `FemaleText_loc5`='艾薩拉和她的謊言都去死吧!', `FemaleText_loc7`='¡Muerte a Azshara y sus mentiras!' WHERE `ID`=24742;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 바다마녀를 죽였고 우리 신은 바다마녀의 여왕을 죽이시리라!', `MaleText_loc4`='我们杀掉了那些海巫，而我们膜拜的神自然会杀死她们的女王！', `MaleText_loc5`='我們宰了海巫，我們的神也會把她們的女王宰了!', `MaleText_loc7`='¡Hemos matado a las brujas marinas y nuestro dios matará a su reina!', `FemaleText_loc1`='우리는 바다마녀를 죽였고 우리 신은 바다마녀의 여왕을 죽이시리라!', `FemaleText_loc4`='我们杀掉了那些海巫，而我们膜拜的神自然会杀死她们的女王！', `FemaleText_loc5`='我們宰了海巫，我們的神也會把她們的女王宰了!', `FemaleText_loc7`='¡Hemos matado a las brujas marinas y nuestro dios matará a su reina!' WHERE `ID`=24743;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알 만한 분들이 왜 이러시나요. 근무 중인 군인에게 술을 제공할 수는 없습니다. 제가 사령관님께 죽는 꼴을 그렇게 보고 싶은 건가요?', `MaleText_loc4`='你们应该知道军纪吧。执行执勤任务的步兵禁止饮酒。你们是不是想让将军宰了我？', `MaleText_loc5`='你們這些小夥子知道規矩的，值勤的時候不准喝酒，你要將軍親手殺了我嗎?', `MaleText_loc7`='Ya sabéis cómo funciona esto. Nada de alcohol para los militares de servicio. ¿Quieres que el General me mate con sus propias manos?' WHERE `ID`=24744;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='허허, 이거 참 알겠습니다... 알겠어요... 하지만 제가 주더라는 얘긴 하지 마세요!', `MaleText_loc4`='好吧，不喝就是了……但是你别想抢走这些酒！', `MaleText_loc5`='好啦，好啦...但是你沒有從我這兒把東西拿走啊!', `MaleText_loc7`='Vale, vale... ¡pero no os las he dado yo!' WHERE `ID`=24745;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저를 탈출시켜 주신다니 고맙습니다, $c님. 아... 아버지께 돌아가는 길을 알 것 같아요. 나쁜 놈들이 절 해치지 못하게 지켜 주세요.', `FemaleText_loc4`='谢谢你，$r。我……我知道如何才能回到父亲身边。请保护我，别让我受到伤害。', `FemaleText_loc5`='$r，謝謝你所作的。我...我想我曉得該怎麼回去我父親身邊。請不要讓這些壞東西傷害我。', `FemaleText_loc7`='Gracias por hacer esto, $r. Creo... creo que sé llegar de vuelta hasta mi padre. Por favor, no dejes que las cosas malas me hagan daño.' WHERE `ID`=24746;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아버지의 생령이 느껴져요. 분명 이 방향이에요... 이쪽으로 오세요, $n 님.', `FemaleText_loc4`='我能感觉到父亲的光环。他肯定就在这个方向……跟我来，$n。', `FemaleText_loc5`='我能感受到我父親的光環。他一定在這個方向...$n，快來。', `FemaleText_loc7`='Puedo sentir el aura de mi padre. Definitivamente es por aquí... vamos, $n.' WHERE `ID`=24747;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='앞쪽에 안개 사이로 틈이 보여요. 거의 다 왔어요!', `FemaleText_loc4`='前方的迷雾出现了缺口。我们就要到了！', `FemaleText_loc5`='我在上頭的薄霧中看到了一線曙光。我們愈來愈接近了!', `FemaleText_loc7`='Veo un claro en la niebla. ¡Nos estamos acercando!' WHERE `ID`=24748;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아빠! 아빠! 저 왔어요!', `FemaleText_loc4`='爸爸！爸爸，我得救了！', `FemaleText_loc5`='父親!父親，我得救了!', `FemaleText_loc7`='¡PADRE! ¡Padre, estoy salvada!' WHERE `ID`=24749;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 장로 무투를 껴안습니다.', `FemaleText_loc4`='%s拥抱了长者穆图。', `FemaleText_loc5`='%s擁抱了穆圖長者。', `FemaleText_loc7`='%s abraza al anciano Mootoo.' WHERE `ID`=24750;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='딸아! 돌아왔구나!', `MaleText_loc4`='我的女儿！你终于回来了！', `MaleText_loc5`='女兒!你回來了!', `MaleText_loc7`='¡Hija! ¡Has vuelto!' WHERE `ID`=24751;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋아요, $n. 여기 있어요. 감쪽같은 데다 냄새까지 완벽한 전쟁노래 오크 위장복이에요!', `FemaleText_loc4`='$n，好啦。你瞧，这套战歌兽人伪装是不是很棒呢！它拥有完美的幻象效果，还散发着兽人那特有的气味！', `FemaleText_loc5`='$n，好吧，看這件:幻術強化、戰歌獸人偽裝，同時有嗅覺影像!', `FemaleText_loc7`='Bien, $n, allá vamos: ¡un disfraz de orco Grito de Guerra realza-ilusorio, con olorvisión incluida!' WHERE `ID`=24752;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 무투, 정말 고맙게 생각하오.', `MaleText_loc4`='$n，穆图感谢你。', `MaleText_loc5`='穆圖感謝你，$n。', `MaleText_loc7`='Mootoo te da las gracias, $n.' WHERE `ID`=24753;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나를 부정할 수는 없다! 이 세계는 멸망하리라!', `MaleText_loc4`='我是不会失败的！这个世界注定要毁灭！', `MaleText_loc5`='我是不會失敗的!這個世界注定要毀滅!', `MaleText_loc7`='¡No seré rechazado! ¡Este mundo caerá!' WHERE `ID`=24754;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으히히히하하... 그마아아안! 이건 너무 비인간적이잖아! 원하는 걸 말해줬잖나... 차라리 날 죽여 줘!', `MaleText_loc4`='不！！！这太过份了！你已经问出大法师的下落了……为什么还不放了我？', `MaleText_loc5`='不～～!這根本就是殘忍的折磨!你已經拿到你要的東西了...你何不就直接殺了我就好?', `MaleText_loc7`='¡Noooooo! ¡Esta tortura es inhumana! Ya tienes lo que querías… ¿Por qué no me matas?' WHERE `ID`=24755;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='후후히히히... 이봐, 난 이미 불었다고, $r! 이건 시간 낭비야...', `MaleText_loc4`='我所知道的统统告诉你了，$r！你这是在浪费时间……', `MaleText_loc5`='我已經把資訊交給你了，$r!你在浪費我的時間...', `MaleText_loc7`='¡Te he dado la información, $r! Estás malgastando tu tiempo...' WHERE `ID`=24756;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 안개는 죽음 그 자체예요... 가리는 것도, 봐주는 법도 없지요.', `FemaleText_loc4`='迷雾意味着死亡……它悄无声息，残酷冷酷。', `FemaleText_loc5`='這陣霧是就是死亡...毫無情緒，更別提感情。', `FemaleText_loc7`='La niebla está muerta... inconsciente, sin compasión.' WHERE `ID`=24757;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭡니까, $c 양반? 너무 잘나셔서 우리처럼 줄은 못 서겠다 이겁니까?', `MaleText_loc4`='怎么啦，$c？你是不是觉得自己相当优秀，不屑与我们为伍了？', `MaleText_loc5`='$c，怎麼樣?你覺得你太棒了，所以不屑和剩下的我們為伍嗎?', `MaleText_loc7`='¿Qué pasa, $c? ¿Acaso te crees demasiado $gbueno:buena; para hacer cola?', `FemaleText_loc1`='뭐죠, $c씨? 너무 잘나셔서 우리처럼 줄은 못 서겠다 이건가요?', `FemaleText_loc4`='怎么啦，$c？你是不是觉得自己相当优秀，不屑与我们为伍了？', `FemaleText_loc5`='$c，怎麼樣?你覺得你太棒了，所以不屑和剩下的我們為伍嗎?', `FemaleText_loc7`='¿Qué pasa, $c? ¿Acaso te crees demasiado $gbueno:buena; para hacer cola?' WHERE `ID`=24758;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크래프티, 전쟁노래 오크 위장복을 잃어버렸습니다.', `MaleText_loc4`='沃比斯波基，我弄丢了战歌兽人伪装。', `MaleText_loc5`='卡芙緹，我把我的戰歌獸人偽裝搞丟了。', `MaleText_loc7`='Ingeniosa, he perdido mi disfraz de orco Grito de Guerra.', `FemaleText_loc1`='크래프티, 전쟁노래 오크 위장복을 잃어버렸어요.', `FemaleText_loc4`='沃比斯波基，我弄丢了战歌兽人伪装。', `FemaleText_loc5`='卡芙緹，我把我的戰歌獸人偽裝搞丟了。', `FemaleText_loc7`='Ingeniosa, he perdido mi disfraz de orco Grito de Guerra.' WHERE `ID`=24759;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크래프티, 전쟁노래 깃발이 하나 더 필요합니다.', `MaleText_loc4`='沃比斯波基，我需要一面战歌旗帜。', `MaleText_loc5`='卡芙緹，我要另外一根戰歌旌旗。', `MaleText_loc7`='Ingeniosa, necesito otro estandarte Grito de Guerra.', `FemaleText_loc1`='크래프티, 전쟁노래 깃발이 하나 더 필요해요.', `FemaleText_loc4`='沃比斯波基，我需要一面战歌旗帜。', `FemaleText_loc5`='卡芙緹，我要另外一根戰歌旌旗。', `FemaleText_loc7`='Ingeniosa, necesito otro estandarte Grito de Guerra.' WHERE `ID`=24760;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이보시오! 기다리시오!', `MaleText_loc4`='嘿，伙计们！等一等！', `MaleText_loc5`='嘿，大夥，停下來等等!', `MaleText_loc7`='¡Hey, chicos! ¡Esperad!' WHERE `ID`=24761;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신을 보니 기쁘기 그지없군요! 이 녹슨 쇠구슬과 사슬을 끊어버리려고 했지만 전 힘이 없어서 말이에요.$B$B아니, 멀뚱멀뚱 보기만 할 거예요? 이것 좀 풀어주시죠!', `MaleText_loc4`='你总算露面啦！我很虚弱，怎么都扭不断这些生锈的锁链。$B$B别站在那儿呀！帮我弄断它！', `MaleText_loc5`='看到你真是太棒了!我太虛弱了，無法破壞這個生鏽的球和鐵鍊。$B$B哎，別只是站在那啊!快幫我鬆綁!', `MaleText_loc7`='¡Me alegro de verte! Estoy demasiado débil para romper los eslabones de esta cadena.$B$B¡Bueno no te quedes ahí! ¡Libérame!' WHERE `ID`=24762;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어, 저기요? 거기 누구 있어요?', `MaleText_loc4`='呃，嗨？有人吗？', `MaleText_loc5`='欸，哈囉?外面有人嗎?', `MaleText_loc7`='Ehm... ¿Hola? ¿Hay alguien ahí?' WHERE `ID`=24763;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐요, 당신! 그래, 당신 말이에요! 당신 발소리가 들려요! 이리 와서 나 좀 구해 줘요!', `MaleText_loc4`='嘿！嘿，就是你！我听见你的声音啦！快把我救出去！', `MaleText_loc5`='嘿，你!對，就是你!我聽到你了!給我過來把我救出去!', `MaleText_loc7`='¡Oye, tú! ¡Sí, tú! ¡Puedo oírte! ¡Ven y sácame de aquí!' WHERE `ID`=24764;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 내 존재를 완전히 잊어버렸다고 생각하던 참이었어요!', `MaleText_loc4`='我还以为他们早把我忘了呢！', `MaleText_loc5`='我不禁開始懷疑，他們統統把我給忘了!', `MaleText_loc7`='¡Estoy empezando a pensar que se han olvidado de mí!' WHERE `ID`=24765;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 그저 친구를 사귀고 싶었을 뿐인데, 갑자기 빠악... 그러곤 이렇게 묶여 있게 된 거죠!', `MaleText_loc4`='你瞧，小侏儒不过是想交几个朋友呀，然后“砰！”地一声……接下来发生的事你都知道啦，他被绑起来了！', `MaleText_loc5`='某個地精想要交朋友，然後，碰...接下來，你知道的，他就被手銬銬住了!', `MaleText_loc7`='Un gnomo intenta hacer amigos y, de repente, BAMM... ¡para cuando se da cuenta está encadenado!' WHERE `ID`=24766;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기에요 여기. 내 말 들리는 거 다 알아요. 이 사슬 좀 끊어줄 수 있겠어요?', `MaleText_loc4`='我在这儿呢。我知道你能听见。能帮我弄断这些链子吗？', `MaleText_loc5`='我在這裡，我知道你聽的見我。你覺得你可以讓我從這些鐵鍊中出去嗎?', `MaleText_loc7`='Estoy aquí. Sé que puedes oírme. ¿Crees que podrías librarme de estos grilletes?' WHERE `ID`=24767;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 어때요? 여기서 날 내보내 주면, 당신이 생각하는 것보다 훨씬 좋은 보상을 주겠어요!', `MaleText_loc4`='我们来做个交易吧：如果你把我从这儿救出去，我就给你一大笔钱，多到超出你的想象！', `MaleText_loc5`='我有個想法:如果你可以幫助我活著逃?這裡，你就可以得到一分出乎意料的大獎勵!', `MaleText_loc7`='Hagamos un trato: si me dejas salir de aquí con vida, obtendrás una recompensa mayor de lo que puedas imaginar.' WHERE `ID`=24768;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기요! 마그모스레가르 옆에 말이에요!', `MaleText_loc4`='嘿！这儿呢，犸格莫斯雷加的巢穴里！', `MaleText_loc5`='嘿!就在瑪格默斯瑞卡的洞裡!', `MaleText_loc7`='¡Hey! ¡Aquí, en el foso de Magmothregar!' WHERE `ID`=24769;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐 하세요? 제가 마그모스레가르한테 잡아먹히면 좋겠어요? 좀 구해주시죠!', `MaleText_loc4`='想什么呢？我可不要当犸格莫斯雷加的开胃菜！把我弄出这个鬼地方！', `MaleText_loc5`='什麼?你覺得我想要當瑪格默斯瑞卡的下一道開胃菜?把我弄出去!', `MaleText_loc7`='¿Qué? ¿Crees que quiero ser el próximo aperitivo de Magmothregar? ¡Sácame de aquí!' WHERE `ID`=24770;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 지금 일에서 손을 놓을 수가 없는데요.$B$B무슨 일이죠?', `MaleText_loc4`='我现在很忙，$c。$B$B我能为你做什么呢？', `MaleText_loc5`='我現在可是手上的東西應有盡有，$c。$B$B我能幫你什麼忙嗎?', `MaleText_loc7`='Ahora mismo estoy muy ocupado, $c.$B$B¿Qué puedo hacer por ti?' WHERE `ID`=24771;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아요. 시간 낭비하지 말고 빨리 나가요!', `MaleText_loc4`='好啦，别浪费时间嘛。我们快走！', `MaleText_loc5`='好了，不要浪費時間，趕快離開這兒吧!', `MaleText_loc7`='Bien, no hay tiempo que perder. ¡Salgamos de aquí!' WHERE `ID`=24772;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 가볼까요.', `MaleText_loc4`='我们走。', `MaleText_loc5`='走吧。', `MaleText_loc7`='Allá vamos.' WHERE `ID`=24773;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 이 신선한 공기! 여기서부터 비행장까지는 저 혼자 갈 수 있겠어요. 피즈크랭크에게 제가 무사히 돌아왔다고 꼭 전해주세요. 정말 고마워요, $n!', `MaleText_loc4`='啊，清新的空气！我能自己返回机场啦。记得转告菲兹兰克我已经平安啦。谢谢你，$n！', `MaleText_loc5`='啊，新鮮的空氣!這裡開始我就能自己走到機場了。記得要告訴嘶軸我安然無恙。非常謝謝你，$n!', `MaleText_loc7`='¡Ah, aire fresco! Puedo llegar hasta la pista de aterrizaje yo solo desde aquí. Asegúrate de decirle a Palanqueta que he vuelto sano y salvo. ¡Muchas gracias, $n!' WHERE `ID`=24774;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 비행장이 보이는군요! 고마워요. 여기서부터는 혼자 갈 수 있어요. 피즈크랭크 제가 무사히 돌아왔다고 꼭 전해주세요.', `MaleText_loc4`='终于能返回机场啦！谢谢你，我自己回去就行了。记得转告菲兹兰克我已经平安啦！', `MaleText_loc5`='終於到機場了!謝謝你，到這以後我就能自己走了。一定要告訴嘶軸我安全回去了!', `MaleText_loc7`='¡La pista de aterrizaje al fin! Gracias, puedo seguir solo desde aquí. Asegúrate de decirle a Palanqueta que he vuelto sano y salvo.' WHERE `ID`=24775;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왼쪽으로 올라가면 되지 싶어요. 출발!', `MaleText_loc4`='我觉得应该走左边这条路。走吧！', `MaleText_loc5`='我想就是這條路直走到底左轉，走吧!', `MaleText_loc7`='Creo que es por aquí hacia la izquierda. ¡Vamos!' WHERE `ID`=24776;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더러운 놈들!', `MaleText_loc4`='恶心的家伙！', `MaleText_loc5`='骯髒的生物!', `MaleText_loc7`='¡Criatura inmunda!' WHERE `ID`=24777;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대화하려고 온 상대를 죽이려 들다니, 멍청이들 같으니!', `MaleText_loc4`='我是来找你们聊天的，可你们这群没脑子的家伙竟然想杀了我！', `MaleText_loc5`='我是來好好談談的，但是你這個無腦的東西卻想要殺掉我!', `MaleText_loc7`='¡He venido aquí para hablar, pero ustedes, cosas descerebradas, habian intentado matarme!' WHERE `ID`=24778;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 다시 사슬에 묶진 못할걸!', `MaleText_loc4`='别想再把我绑起来！', `MaleText_loc5`='你不可以再用鐵鍊拴住我!', `MaleText_loc7`='¡No me encadenarás otra vez!' WHERE `ID`=24779;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 간식거리가 아니라고!', `MaleText_loc4`='我可不是什么开胃小菜！', `MaleText_loc5`='我 不 是 開 胃 菜 !', `MaleText_loc7`='¡NO SOY UN APERITIVO!' WHERE `ID`=24780;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나도 이제 깨달았어! 스노볼트랑은 말이 안 통한단 걸!', `MaleText_loc4`='好的坏蛋就是死掉的坏蛋！', `MaleText_loc5`='只有死的害蟲才是好的害蟲!', `MaleText_loc7`='¡Vermen bueno, vermen muerto!' WHERE `ID`=24781;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싸움은 그만! 이 녀석만 잡고 어서 여기서 나가자고요!', `MaleText_loc4`='打够啦！快点解决这帮家伙，我们离开这里吧！', `MaleText_loc5`='不要再吵架了!趕快解決這件事逃出去啦!', `MaleText_loc7`='¡Basta de pelear! ¡Acabemos esto y salgamos de aquí!' WHERE `ID`=24782;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐요! 전 여기 있다고요!', `MaleText_loc4`='嘿！我就在这儿！', `MaleText_loc5`='嘿!我在這裡走路喔!', `MaleText_loc7`='¡Hey! ¡Estoy caminando aquí!' WHERE `ID`=24783;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사람들이 날 잊었다니, 믿을 수가 없어... 죽어라!', `MaleText_loc4`='真不敢相信，我的同胞居然把我忘了。去死吧！', `MaleText_loc5`='我不敢相信我的人民把我給忘了。死吧!', `MaleText_loc7`='No puedo creer que mi propia gente se haya olvidado de mí. ¡Muere!' WHERE `ID`=24784;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 사랑스러운 비행장. 다시는 이 작은 활주로를 못 보는 줄 알았네.', `MaleText_loc4`='哦，亲爱的机场，我再也看不到你那笔直的小跑道了。', `MaleText_loc5`='喔，可愛的簡易機場，我再也看不到你的小跑道了。', `MaleText_loc7`='Oh, dulce pista de aterrizaje, nunca volveré a ver tu terminal.' WHERE `ID`=24785;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 널브러진 코도를 게걸스럽게 뜯어먹습니다.', `MaleText_loc4`='%s开始吞食无助的科多兽。', `MaleText_loc5`='%s大啖無助的科多獸。', `MaleText_loc7`='%s se da un festín con el indefenso kodo.' WHERE `ID`=24786;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명령만 내려주십시오, 장군님. 임의로 운용하실 수 있는 2개 연대 병력을 한 달 내로 준비하겠습니다.', `MaleText_loc4`='将军，我向你保证，我能在一个月内招募到两个团的兵力。', `MaleText_loc5`='下令吧，將軍。就這一個月的時間，我給你兩個團的兵力任由你指揮。', `MaleText_loc7`='Dígalo, General. Tendré dos regimientos a su disposición dentro de un mes.' WHERE `ID`=24787;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 좋습니다, 장군님. 장군님께서 마음만 고쳐먹으신다면 저희 쪽 사람들은 기꺼이 병력을 지원하겠습니다.', `MaleText_loc4`='好吧，将军。如果你改变主意的话，我们会很乐意提供军事援助的。', `MaleText_loc5`='非常好，將軍。要是你改變心意，我的人民會非常樂意提供軍事協助的。', `MaleText_loc7`='Muy bien, General. Si cambia de idea, mi gente estará más que dispuesta a proporcionar ayuda militar.' WHERE `ID`=24788;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장군님, 저희 병사들은 대부분 일반 주민이나 농민입니다. 착하긴 해도 어렸을 때부터 쌓아온 편견이나 미신은 떨쳐버리지 못했습니다. 이 특이한 동맹군과 함께 싸우기에는 좀 무리가 있습니다.', `MaleText_loc4`='将军，我们的军队主要是由村民和农夫构成的。他们都是很好的人，但是还没有完全摆脱自小养成的偏见和迷信。他们还没有准备好与外来盟友并肩作战。', `MaleText_loc5`='我們的軍隊，將軍，大多是由村民和農民所組成。善良，卻無法完全擺脫生長過成中的偏見和迷信。他們還無法和我們來自異地的盟友並肩作戰。', `MaleText_loc7`='Nuestras tropas están formadas por aldeanos y campesinos principalmente, General. Buenos hombres, pero aún conservan los prejuicios y supersticiones con los que crecieron. No están preparados para luchar junto a nuestros exóticos aliados.' WHERE `ID`=24789;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대의 제안을 심사숙고해 보겠소, 선구자. 그리고 그대 편 사절에게 고문 역할을 맡기도록 하지.', `MaleText_loc4`='先驱者，我会认真考虑你的建议。同时，我们也会随时向你们咨询的。', `MaleText_loc5`='你提供的條件我們會審慎評估的，先驅者。同時，我們將利用你的代表身分作為諮詢的成員。', `MaleText_loc7`='Tu oferta será considerada cuidadosamente, presagista. Mientras tanto, nos vendrá bien que tu delegación desempeñe el papel de consejero.' WHERE `ID`=24790;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스컬지가 우리를 포위했네. 얼마간은 마을을 방어할 수 있겠지만, 결국 저들을 물리치지 못한다면 우리는 모두 죽을 걸세.', `MaleText_loc4`='我们已经被天灾军团包围了。从目前的情况看，我们还能坚持一段时间。但这将是一场你死我活的战斗。', `MaleText_loc5`='天譴軍包圍了我們，我們還能守住村莊一會兒，但是如果我們不能擊敗他們，他們會輾過我們的。', `MaleText_loc7`='La Plaga nos tiene rodeados. Podemos conseguir que el poblado resista un rato, pero si no logramos derrotarlos, nos invadirán.' WHERE `ID`=24791;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생각할 것도 없습니다. 공격해야 합니다. 우리가 불리하다는 건 알지만, 타운카로서 가만히 앉아 당할 수만은 없습니다.', `MaleText_loc4`='我们别无选择，只能发动进攻。我知道局势对我们不利，但是牦牛人绝不能坐以待毙。', `MaleText_loc5`='選項很明確，我們必須進攻。我知道成功的機率對我們不利，但是坦卡族絕不會放任這些屠殺者不管的。', `MaleText_loc7`='La elección es clara. Debemos atacar. Sé que tenemos todas las de perder, pero los taunka no van al matadero en silencio.' WHERE `ID`=24792;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 차라리 도끼를 움켜쥐고 적의 피를 뒤집어쓴 채로 죽어가겠습니다!', `MaleText_loc4`='就算是死，我也要紧握沾满敌人鲜血的战斧！', `MaleText_loc5`='我將手握巨斧死在敵人的血泊之中!', `MaleText_loc7`='¡Moriré con mis hachas en las manos y empapado en la sangre de nuestros enemigos!' WHERE `ID`=24793;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='감옥에 먼지가 앉을 지경이구나. 당장 죄수를 더 잡아들여!', `FemaleText_loc4`='囚犯的鲜血都快抽干啦。马上给我抓些俘虏回来！', `FemaleText_loc5`='牢籠中的血乾了。馬上帶給我更多的囚犯!', `FemaleText_loc7`='Estas jaulas están desangradas. ¡Traed más prisioneros inmediatamente!' WHERE `ID`=24794;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당장 감옥을 채우지 않으면 말리고스 님께서 이유를 물으실 것이다!', `FemaleText_loc4`='我们得尽快塞满这些牢笼，否则玛里苟斯就会察觉！', `FemaleText_loc5`='要立刻塞滿囚犯，不然瑪里苟斯會知道的!', `FemaleText_loc7`='¡Hay que llenar estas prisiones inmediatamente o Malygos sabrá por qué!' WHERE `ID`=24795;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='죄수를 더 잡아와라! 아제로스에서 멋대로 마법을 휘두르는 놈들을 다 쓸어버릴 때까지 멈춰선 안 돼!', `FemaleText_loc4`='我需要更多的俘虏！将艾泽拉斯世界那些毫无节制的施法者都干掉！别停手！', `FemaleText_loc5`='把更多的囚犯帶下去!在徹底淨化艾澤拉斯所有莽撞的魔法使用者之前，片刻都不得休息!', `FemaleText_loc7`='¡Traed más prisioneros! ¡No descanséis hasta que Azeroth esté limpio de estos imprudentes usuarios de la magia!' WHERE `ID`=24796;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 감옥을 마법사로 가득 채워라! 말리고스 님의 명령이다!', `FemaleText_loc4`='往这些牢笼里塞满法师！这是玛里苟斯的命令！', `FemaleText_loc5`='把這些牢房關滿法師!這是瑪里苟斯的命令!', `FemaleText_loc7`='¡Llenad estas prisiones de magos! ¡Malygos lo exige!' WHERE `ID`=24797;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전장에서의 장렬한 최후라는 낭만에 내 전사들을 희생할 생각은 없네. 살아남고자 벌인 싸움에서 아무도 살아남지 못한다면 그게 무슨 소용인가?', `MaleText_loc4`='我不会让将士们为了所谓的“荣耀”白白送命。如果没人能活下来，那么为生存而战还有什么意义呢？', `MaleText_loc5`='我不能因光榮戰死沙場這種不切實際的想法就犧牲我的戰士們。如果沒人存活，那為了生死存亡而奮鬥又有什麼用?', `MaleText_loc7`='No sacrificaré a mis guerreros basándome en ideas románticas de una muerte gloriosa en el campo de batalla. ¿Qué sentido tiene luchar por la supervivencia si no sobrevive nadie?' WHERE `ID`=24798;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언젠가 싸울 날이 올 걸세, 두름. 하지만 먼저 이 불리한 상황을 뒤집을 가능성이 있는지부터 찾아봐야지. 뭔가 좋은 생각이 있는가, 아이레?', `MaleText_loc4`='杜尔姆，战争看来是不可避免的。但首先，我们得找到扭转局势的法子。埃恩雷，你有什么提议吗？', `MaleText_loc5`='德姆，戰爭是遲早的事，但是在這之前，我們必須得找出一個將勝利機會扳平的方法。艾睿，你給我的吩咐是?', `MaleText_loc7`='Ya habrá tiempo para luchar, Durm. Pero primero tenemos que encontrar un modo de equilibrar la balanza. ¿Qué quieres que haga, Aeire?' WHERE `ID`=24799;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='조상님들은 적을 혼란에 빠트리는 방법을 알고 계셨어요. 그 지혜를 사용한다면 스컬지의 약점을 찾거나 적의 지휘관을 쓰러트릴 수 있을 겁니다. 지도자 없는 스컬지는 곧 우리 용사들 앞에 무너져 내리겠지요.', `FemaleText_loc4`='我们的先祖懂得如何扰乱敌人的心智。我们可以利用这种能力找出天灾军团的弱点，或是杀死他们的指挥官。没有了首领的指挥，天灾军团很快就会败下阵来。', `FemaleText_loc5`='先祖們知曉一種混淆敵人感官的方法，我們可以藉由這種知識找出天譴軍的弱點，或是直接打擊他們的指揮官。一旦除去他們的領導者，天譴軍就會在我們的戰士面前倒下。', `FemaleText_loc7`='Los antepasados conocían un modo de desconcertar a los enemigos. Podríamos usar este conocimiento para descubrir las debilidades de la Plaga o para atacar a sus comandantes. Sin sus líderes, la Plaga caerá ante nuestros guerreros.' WHERE `ID`=24800;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명예라곤 찾아볼 수 없는 계획이군요.', `MaleText_loc4`='啧啧，卑鄙的阴谋。', `MaleText_loc5`='不光榮的陰謀。', `MaleText_loc7`='Una estratagema deshonrosa.' WHERE `ID`=24801;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 생각하는 명예는 대체 얼마나 값진 것인가, 두름? 자네의 목숨을 버릴 만큼? 내 목숨만큼? 아니면 어릴 때부터 자네를 길러준, 눈멀고 늙은 대부 마한의 목숨을 희생할 만큼 값진가?', `MaleText_loc4`='杜尔姆，你所谓的荣誉又能挽救什么？你的性命？我的性命？还是抚养你长大的盲眼老人玛罕宗父的性命？', `MaleText_loc5`='你的榮耀到底有什麼價值，德姆?你的生命嗎?還是我的?又或者是從小將你撫養長大，盲眼老主父瑪哈的生命呢?', `MaleText_loc7`='¿Cuánto vale tu honor, Durm? ¿Tu vida? ¿La mía? ¿La vida del ciego abuelo Mahan que cuidó de ti durante tu infancia?' WHERE `ID`=24802;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽은 자에게 명예란 아무 의미도 없네. 전사는 명예를 위해 전장에서 죽어갈 수도 있지만, 족장은 그보다 더 많은 것을 책임져야 하는 법이야. 현자 아이레의 계획에 따르기로 하고 마을을 계속 방어하세.', `MaleText_loc4`='对死人而言，荣誉还有什么意义。战士可以为了荣耀投身沙场，但酋长要考虑的问题则要多得多。我们决定采取先知埃恩雷的计划，继续保卫村落。', `MaleText_loc5`='對死人來說，榮譽一點意義也沒有。戰士也許會為了榮譽而投入戰爭之中，但是身為酋長則要看得更長遠。我們將按照賢者艾睿的計畫持續護衛村子。', `MaleText_loc7`='El honor no tiene ningún valor para un hombre muerto. Un guerrero puede lanzarse a la batalla por el honor, pero un cabecilla es responsable de mucho más. Seguiremos los planes de la sabia Aeire y continuaremos defendiendo nuestro poblado.' WHERE `ID`=24803;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='천천히 말하게, $r. 자네 언어에는 익숙하지 않다네.', `FemaleText_loc4`='慢点说，孩子。我还不熟悉你们的语言。', `FemaleText_loc5`='孩子，說慢點，我對你獨特的腔調很陌生。', `FemaleText_loc7`='Habla despacio, $gniño:niña;, tu extraño idioma es nuevo para mí.' WHERE `ID`=24804;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='목소리를 낮추십시오, $r|1이여;여;. 하마트는 나이가 많아서 휴식이 필요합니다.', `FemaleText_loc4`='请你小点声，$r。哈玛特老了，她需要休息。', `FemaleText_loc5`='拜託，小聲一點，$r。哈邁特老了，需要休息。', `FemaleText_loc7`='Baja la voz, $r. Hamat es mayor y necesita descansar.' WHERE `ID`=24805;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭔가 행동을 해야 하네. 스컬지가 우리를 몰살하기 전에 놈들에게 어떻게 대항할지 결정해야만 해.', `MaleText_loc4`='该采取行动了。我们必须在天灾军团摧毁我们之前解决他们。', `MaleText_loc5`='該是行動的時候了。在天譴軍把我們吞沒之前，我們得決定怎麼解決他們。', `MaleText_loc7`='Ha llegado la hora de entrar en acción. Debemos decidir qué hacer con la Plaga antes de que nos consuma.' WHERE `ID`=24807;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='녀석들은 소모품일 뿐이다. 자, 봐라! 살게라스가 해내지 못한 일을 내가 해낼 것이다! 이 보잘것없는 세상을 갈가리 찢어발기고 불타는 군단의 진정한 주인으로 우뚝 서리라! 종말이 다가왔다! 어디 한번 세계를 구해 봐라!', `MaleText_loc4`='这个消耗品已经没用了！不管它了！现在我已经做到了连萨格拉斯都没有做到的事情！我要彻底毁灭这个世界，真正成为燃烧军团的主宰者！末日已经到来啦！让这个世界就此支离破碎吧！', `MaleText_loc5`='該犧牲的都已經結束了，就任他們去吧!現在我將完成薩格拉斯都辦不到的事!我要搾乾這個悲慘的世界，並確保我成為燃燒軍團的真正主人!末日已經到來!讓這個世界開始毀滅吧!', `MaleText_loc7`='Los prescindibles han muerto. ¡Qué así sea! ¡Ahora triunfaré donde Sargeras no lo logró! ¡Desangraré este despreciable mundo y aseguraré mi puesto como el verdadero amo de la Legión Ardiente! ¡El final ha llegado! ¡Dejen que se devele el misterio de este mundo!' WHERE `ID`=24808;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 네 영혼은 스컬지의 것이다, 죽어야 할 존재여.', `MaleText_loc4`='凡人，你的灵魂归天灾军团了。', `MaleText_loc5`='凡人，你的靈魂現在是屬於天譴軍的了。', `MaleText_loc7`='Ahora sus almas pertenecen a la Plaga, mortales.' WHERE `ID`=24809;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이레, $n|1이;가; 가죽을 구해 왔네. 내가 토하기 전에 어서 가져가 주게.', `MaleText_loc4`='埃恩雷，$n将你要的兽皮带回来了。请你赶快把它们拿走，我真是受不了这玩意儿。', `MaleText_loc5`='艾睿，$n把你的皮革帶來了。快，在我吐出來之前拿走。', `MaleText_loc7`='Aeire, $n ha traído tus pellejos. Cógelos antes de que me ponga enfermo.' WHERE `ID`=24810;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='바로 가져가겠습니다. 용감한 족장님이 가죽 몇 장 때문에 벌벌 떨게 할 수는 없죠.', `FemaleText_loc4`='我会拿走的。怎么能让伟大的酋长被一堆兽皮吓得瑟瑟发抖呢。', `FemaleText_loc5`='我會收下的。我們強大的酋長不該害怕區區幾張皮革。', `FemaleText_loc7`='Yo cogeré esos. No podemos permitir que el poderoso cabecilla esté aterrorizado por unos pellejos.' WHERE `ID`=24811;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이게 무슨 소란이냐?!', `FemaleText_loc4`='这是怎么回事呢？！', `FemaleText_loc5`='這場騷動有何含意?!', `FemaleText_loc7`='¡¿Qué significa esta interrupción?!' WHERE `ID`=24812;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='돌아가서 일해라! 소란은 내가 처리했다.', `FemaleText_loc4`='回去做事！我已经摆平了来惹事的家伙。', `FemaleText_loc5`='回去工作!我已經把混亂解決了。', `FemaleText_loc7`='¡Sigamos trabajando! Ya me he encargado de nuestra pequeña distracción.' WHERE `ID`=24813;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님께 드릴 시체가 더 필요하다...', `MaleText_loc4`='主人需要更多的尸体……', `MaleText_loc5`='給主人找更多的屍體...', `MaleText_loc7`='Más cuerpos para el maestro...' WHERE `ID`=24814;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여는 중', `MaleText_loc4`='打开', `MaleText_loc5`='開啟', `MaleText_loc7`='Abriendo', `FemaleText_loc1`='여는 중', `FemaleText_loc4`='打开', `FemaleText_loc5`='開啟', `FemaleText_loc7`='Abriendo' WHERE `ID`=24815;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='열쇠는 내가 부쉈다! 너희가 아끼는 그 대마법사는 이제 말리고스 님의 것이야!', `FemaleText_loc4`='钥匙已经被我摧毁了！你们那位尊贵的大法师归玛里苟斯了！', `FemaleText_loc5`='我毀掉了鑰匙!你最珍愛的大法師屬於瑪里苟斯了!', `FemaleText_loc7`='¡He destruido la llave! ¡Tu adorado archimago pertenece a Malygos!' WHERE `ID`=24816;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더러운 괴물들! 나즈자타의 심연에 계신 아즈샤라 여왕님께서 내 원수를 갚아주실 것이다!', `MaleText_loc4`='卑鄙的家伙！以纳沙塔尔的名义，艾萨拉女王会为我报仇的！', `MaleText_loc5`='背叛的生物!以納沙塔爾深淵之名，艾薩拉女士會為我復仇!', `MaleText_loc7`='¡Traidoras criaturas! ¡Por las profundidades de Nazjatar, Lady Azshara me vengará!', `FemaleText_loc1`='더러운 괴물들! 나즈자타의 심연에 계신 아즈샤라 여왕님께서 내 원수를 갚아주실 것이다!', `FemaleText_loc4`='卑鄙的家伙！以纳沙塔尔的名义，艾萨拉女王会为我报仇的！', `FemaleText_loc5`='背叛的生物!以納沙塔爾深淵之名，艾薩拉女士會為我復仇!', `FemaleText_loc7`='¡Traidoras criaturas! ¡Por las profundidades de Nazjatar, Lady Azshara me vengará!' WHERE `ID`=24817;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 이제 조상님 영혼이 있는 곳으로 가겠지요...', `MaleText_loc4`='我就要去见先祖的灵魂了……', `MaleText_loc5`='我要去跟我先祖的靈魂團聚了...', `MaleText_loc7`='Voy a juntarme con los espíritus de mis antepasados...', `FemaleText_loc1`='저는 이제 조상님 영혼이 있는 곳으로 가겠지요...', `FemaleText_loc4`='我就要去见先祖的灵魂了……', `FemaleText_loc5`='我要去跟我先祖的靈魂團聚了...', `FemaleText_loc7`='Voy a juntarme con los espíritus de mis antepasados...' WHERE `ID`=24818;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오락거리로 살려뒀다만... 이제 우리 손으로 직접 죽여주마!', `MaleText_loc4`='本来嘛，我们还打算让你多活些时日的。不过我们决定现在就结束你的性命！', `MaleText_loc5`='你也許從我們的消遣活動中存活了下來，但是現在，你將會死在我們手中!', `MaleText_loc7`='¡Puede que hayas sobrevivido para entretenernos, pero ahora te mataremos con nuestras propias manos!', `FemaleText_loc1`='오락거리로 살려뒀다만... 이제 우리 손으로 직접 죽여주마!', `FemaleText_loc4`='本来嘛，我们还打算让你多活些时日的。不过我们决定现在就结束你的性命！', `FemaleText_loc5`='你也許從我們的消遣活動中存活了下來，但是現在，你將會死在我們手中!', `FemaleText_loc7`='¡Puede que hayas sobrevivido para entretenernos, pero ahora te mataremos con nuestras propias manos!' WHERE `ID`=24819;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='누가 감히 내 일을 방해하는 거냐? 모습을 보여라, 겁쟁이 같으니!', `FemaleText_loc4`='竟敢打扰我的工作？！胆小鬼，不敢露面吗！', `FemaleText_loc5`='誰那麼大膽干擾我工作!?現身吧，懦夫!', `FemaleText_loc7`='¿Quién osa interrumpir mi trabajo? ¡Muéstrate, cobarde!' WHERE `ID`=24820;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='누가 감히 내 일을 방해하는 거냐? 모습을 보여라, 겁쟁이 같으니!', `FemaleText_loc4`='竟敢打扰我的工作？！胆小鬼，不敢露面吗！', `FemaleText_loc5`='誰那麼大膽干擾我工作!?現身吧，懦夫!', `FemaleText_loc7`='¿Quién osa interrumpir mi trabajo? ¡Muéstrate, cobarde!' WHERE `ID`=24821;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수정구에 힘을 쏟겠습니다! 준비하세요!', `MaleText_loc4`='我会将我的力量导入宝珠中！准备好！', `MaleText_loc5`='我會將我的力量導入寶珠中!準備好!', `MaleText_loc7`='¡Canalizaré mi poder en los orbes! ¡Preparaos!' WHERE `ID`=24822;
