UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음의 요새가 고장 나 탈라마스에 추락했다는 이야기를 리치 왕께서 들으신다면 우리 모두 재로 돌아가게 될 거다.', `MaleText_loc4`='如果被巫妖王发现塔尔拉玛斯出了故障，那我们就完蛋了。', `MaleText_loc5`='要是巫妖王發現我們因為機件失靈而讓塔爾拉瑪斯墜毀的話，我們肯定要化為灰燼。', `MaleText_loc7`='Si el Rey Exánime descubre que estrellamos Talramas debido a un fallo, nos hará picadillo.' WHERE `ID`=24879;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 빨리 움직여라! 해가 지기 전까지 이륙하지 못하면 리치 왕께서 몸소 우리를 처형하실 것이다!', `MaleText_loc4`='快一点啦！我们必须在今天之内起飞，不然巫妖王一定会要了我们的命。', `MaleText_loc5`='再快點!我們必須在世界末日之前飛起來，否則巫妖王一定會毀掉我們的。', `MaleText_loc7`='¡Más deprisa! Si no estamos volando al acabar el día, no cabe duda de que el Rey Exánime nos destruirá.' WHERE `ID`=24880;
