UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋아요, $n 님. 시작할게요. 엘룬 여신이건 대지모신이건, 어쨌거나 성공하기를 빌어주세요!', `FemaleText_loc4`='好啦，$n。交叉手指，虔诚地祈祷好运降临吧！', `FemaleText_loc5`='好啦，$n，我們上吧，不管是求神、拜佛、焚香還是禱告，總之祝我們好運吧!', `FemaleText_loc7`='Vale, $n, allá vamos. ¡Cruza los dedos de las manos, de los pies, los ojos y cualquier otra cosa que puedas cruzar!' WHERE `ID`=24888;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 이런, 오작동했잖아! 어쩐지... 가벼워진 기분인데요.', `FemaleText_loc4`='天哪，这玩意儿不行啊！我觉得有点……轻飘飘的。', `FemaleText_loc5`='壞了，他不動!不知道為什麼我感覺...變輕了。', `FemaleText_loc7`='¡Oh no, no ha funcionado! Por algún motivo me siento más... ligera.' WHERE `ID`=24889;
