UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 무슨 일이 벌어지고 있는지 말해 주십시오, 피즈크랭크.', `MaleText_loc4`='菲兹兰克，出了什么事。', `MaleText_loc5`='告訴我這裡所發生的事情，嘶軸。', `MaleText_loc7`='Dime qué está pasando aquí, Palanqueta.', `FemaleText_loc1`='여기서 무슨 일이 벌어지고 있는지 말해 주세요, 피즈크랭크.', `FemaleText_loc4`='菲兹兰克，出了什么事。', `FemaleText_loc5`='告訴我這裡所發生的事情，嘶軸。', `FemaleText_loc7`='Dime qué está pasando aquí, Palanqueta.' WHERE `ID`=24896;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야기를 다시 들려 주십시오, 피즈크랭크.', `MaleText_loc4`='菲兹兰克，把你的故事再说一遍吧。', `MaleText_loc5`='嘶軸，再跟我說一次你的故事。', `MaleText_loc7`='Vuelve a contarme tu historia, Palanqueta.', `FemaleText_loc1`='이야기를 다시 들려 주세요, 피즈크랭크.', `FemaleText_loc4`='菲兹兰克，把你的故事再说一遍吧。', `FemaleText_loc5`='嘶軸，再跟我說一次你的故事。', `FemaleText_loc7`='Vuelve a contarme tu historia, Palanqueta.' WHERE `ID`=24897;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아요, 그럼 일단 앉으세요. 다 얘기하려면 시간이 좀 걸릴 테니까요.$B$B이 얼어붙은 지옥에 처음 왔을 무렵, 용맹의 성채에 있는 알로스 장군이 저와 이 용감한 비행 부대에 특명을 내렸지요. 얼라이언스의 작전 수행을 위해 전진 비행기지를 세우라는 거였어요.$B$B그래서 세워진 것이 이 비행장이지요. 분명히 말하건대, 사방에 짐승들이 득실대고, 땅은 얼어서 바위처럼 단단한지라 작업하는 데 아주 고생이 많았다고요! 하지만 우린 해냈지요. 그것도 아주 빨리!', `MaleText_loc4`='好吧，坐吧。说来话长。$B$B当我们首次踏足这片冰封地狱时，无畏要塞的阿洛斯将军交给飞行敢死队一项特殊的任务。为了扩展联盟的势力范围，他命令我们建设一座空军基地。$B$B这个小机场就是我们的成果啦。这鬼地方到处都是肮脏的野兽，土地还冻得跟石头一样硬，你知道我们有多不容易吗！但是我们排除万难，在短期内就建成了这座机场！是不是很厉害呀！', `MaleText_loc5`='好吧，請坐。這個故事可能需要花點時間。$B$B當我們第一次來到這個冰封地獄時，下面那個驍勇要塞的阿爾洛斯將軍給了我一組飛行敢死隊和一個特別任務:為聯盟建立一個前鋒空軍基地。$B$B成果就是這個簡易機場。我跟你說，處理這些討厭的野獸還有冰到硬梆梆的石頭並不容易!不過我們努力，也很快就做到了!', `MaleText_loc7`='Vale, siéntate entonces. Esto puede llevarnos un rato.$B$BCuando llegamos a este infierno congelado, el general Arlos, en la Fortaleza Denuedo, nos encomendó a mí y a mi grupo de temerarios pilotos una tarea especial: debíamos establecer una base aérea avanzada para las operaciones de la Alianza.$B$BEsta pista de aterrizaje es el resultado. Permíteme que te diga que no fue fácil con todas esas terribles bestias y el suelo durísimo por su estado de congelación. ¡Pero lo logramos y lo hicimos rápido!' WHERE `ID`=24898;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속하십시오.', `MaleText_loc4`='继续讲呀。', `MaleText_loc5`='請繼續。', `MaleText_loc7`='Continúa.', `FemaleText_loc1`='계속하세요.', `FemaleText_loc4`='继续讲呀。', `FemaleText_loc5`='請繼續。', `FemaleText_loc7`='Continúa.' WHERE `ID`=24899;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여하튼, 여길 건설하는 데 모래와 연료가 많이 필요했죠. 마침 근처에 있던 웅덩이가 재료를 구하기에 딱 좋았어요.$B$B어떤 모래에는 마법적인 속성까지 깃들어 있었거든요... 뭔가 얽힌 얘기가 있을 것 같죠? 하지만 그 얘기는 일단 접어두고...$B$B그래서 우린 물을 모조리 퍼내고 그 한가운데에 채굴 현장을 차렸지요. 주 흡입관이 막혀버리기 전까진 일이 아주 잘 풀렸어요.', `MaleText_loc4`='嗯……为了确保机场的正常运转，我们需要抽取大量的沙砾和石油。这附近的池塘恰好有丰富的储量。$B$B某些沙砾甚至具有魔法属性……你能想象其中的潜在利润吗！？好吧，我就不扯远了。$B$B于是我们抽走大部分池水，在池塘中央修筑了泵站。本来一切都进展得挺顺利的，直到有一天，主管道突然堵塞了。', `MaleText_loc5`='不管怎樣，我們需要替機器灌入大量的砂石及油。附近的池子完美地擁有這兩種物品。$B$B當中部分的砂子甚至擁有魔法特性...可以說是有可能嘛!?不過那是另一個故事了。$B$B所以，我們抽乾了大部分的水，並在中央建立了幫浦站。每件事都進行得很順利，直到有一天，主抽取管塞住了。', `MaleText_loc7`='De todas formas, tuvimos que bombear mucha arena y aceite para la maquinaria. Las charcas cercanas resultaron perfectas para ello.$B$BIncluso parte de la arena tenía propiedades mágicas... ¿podríamos hablar de beneficios? Pero esa es otra historia.$B$BAsí que drenamos la mayoría del agua y construimos la estación de bombeo justo en el medio. Todo iba como la seda hasta que un día la tubería de succión principal se atascó.' WHERE `ID`=24900;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐만요, 아까 뭐라고 하셨지요?', `MaleText_loc4`='等等。你刚才说什么？', `MaleText_loc5`='等等，退回剛說的話。你最後說了什麼?', `MaleText_loc7`='Espera, rebobina. ¿Qué es lo último que has dicho?', `FemaleText_loc1`='잠깐, 아까 뭐라고 하셨죠?', `FemaleText_loc4`='等等。你刚才说什么？', `FemaleText_loc5`='等等，退回剛說的話。你最後說了什麼?', `FemaleText_loc7`='Espera, rebobina. ¿Qué es lo último que has dicho?' WHERE `ID`=24901;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얘기해 두지만, 여기서부턴 나중에 안 사실이에요. 전 그때 거기 없었으니까요.$B$B인부들이 막힌 펌프를 뚫으려고 조사해 보니, 펌프 안에 노움처럼 생긴 로봇 파편이 끼어 있었던 거예요! 물론 그 멍청이들은 우리한테 알리지도 않고 그걸 다시 조립하려고 밤낮으로 끙끙댔지요.$B$B채굴 현장과 연락이 끊어진 건 바로 그때부터예요.', `MaleText_loc4`='不过呢，当时我并不在场，所以接下来发生的事我是后来才知道的。$B$B他们从主管道中扒拉出一些零件来，似乎是机械侏儒的部件！结果，那群“勤奋”的蠢货就擅自将这玩意儿拼接起来了！$B$B从此，我们就与泵站失去了联系。', `MaleText_loc5`='提醒你，因為我當時並不在那裡，所以這個部分是我後來才知道的。$B$B當他們一步步將抽取管連結上幫浦時，吸上來了一隻看起來像是地精的機器人!當然，這些傻蛋沒有知會我們，就日夜加工地把東西組裝起來。$B$B我們就是在這時候與幫浦站失去連絡。', `MaleText_loc7`='Ten en cuenta que esta parte la descubrí posteriormente, porque yo no estaba allí entonces.$B$BCuando la desmontaron, encontraron las piezas de un robot que parecía un gnomo. Por supuesto los muy insensatos trabajaron día y noche para reconstruirlo sin avisarnos.$B$BEs entonces cuando perdimos el contacto con la estación de bombeo.' WHERE `ID`=24902;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='며칠씩 연락이 되지 않아 조사대를 파견해 봤죠. 하지만 그들은 돌아오지 않았어요.$B$B다음 날 다른 조사대를 파견했지만 결과는 마찬가지였고, 공중 정찰대에 속한 비행기도 몇 대 잃었다고요.$B$B결국 저는 도움을 요청하라고 스카이호퍼를 남쪽으로 보내고, 최악의 사태에 대비했지요. 최강의 전력을 갖추고 그곳으로 갈 수 있도록 무기와 방어구, 로봇을 열심히 만들었어요.$B$B그리고 며칠 전 그곳에 갔을 때, 우린 두 눈을 의심할 수밖에 없었어요!', `MaleText_loc4`='接连几天都没有泵站的消息，我就派了一支侦察队去查看情况。可是他们再也没有回来。$B$B第二天，我又派出一队，结果他们还是跟蒸发了似的。此外，我们还损失了好几架侦察机。$B$B事情到这一步，我不得不派人去了南边寻求支援，让剩余的队员留下来做最坏的打算。我们全力锻造护甲、武器以及机器人，准备全副武装地进军泵站。$B$B几天前，当我们到达那里时，顿时被眼前的情景惊呆了！', `MaleText_loc5`='經過幾天的音信全無，我派了一組偵察隊伍前往平台。他們再也沒有回來過。$B$B隔天我又派出了另一組人員，並在空中偵察中損失了兩艘飛行器。$B$B那時候，我派了某人到南方去尋求協助，而我們留下來準備面對最糟的情況。我們轉而專注製作護甲，武器和機器人，這樣我們就能準備完善的出發前往那裡。$B$B幾天前在我們出發後，我們看到了令外意外的東西!', `MaleText_loc7`='Tras un par de días sin noticias, envié a una partida de reconocimiento a la plataforma. Jamás regresaron.$B$BEnvié a otro grupo al día siguiente con el mismo resultado y perdí un par de máquinas voladoras durante el reconocimiento aéreo.$B$BLlegados a ese punto, envié a alguien en busca de ayuda al sur y nos preparamos para lo peor. Concentramos todo nuestro esfuerzo en hacer armaduras, armas y robots para dirigirnos hacia allí con toda nuestra fuerza.$B$BCuando lo hicimos, hace un par de días, no podíamos creer lo que encontramos.' WHERE `ID`=24903;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 도저히 말로는 설명할 수 없는 것들을 봤다고요.$B$B내 부하들은 어디에도 보이지 않았고, 그들 대신 로봇과 인조인간이 사방에서 작업 중이었어요!$B$B이 ''인조인간''들은 하나같이 노움처럼 생겼는데, 우리가 오기를 기다리고 있었다더군요. 실제로 놈들은 마치 우릴 알고 있다는 듯이 이상하게 행동했어요. 우린 포위되어 순식간에 채굴 현장 꼭대기로 붙잡혀갔지요.$B$B거기서 우린 놈들의 우두머리가 누군지, 그리고 그가 살아남은 노움들에게 무슨 짓을 저지르는지 목격하고 만 거예요!', `MaleText_loc4`='确实如此，那场面真是难以形容。$B$B泵站的工作人员都不见了踪影，取而代之的是一支名副其实的机器人大军！$B$B他们和侏儒的外形相似，还说什么一直在等我们呢。诡异的是，那些机器人好像真的认识我们。我们被包围了，接着就被拖到了泵站的顶层。$B$B在那里我们见到了他们的首领，并目睹了他对幸存的侏儒所做的坏事！', `MaleText_loc5`='就像我說的，我們在那裡看到的景象非常難以形容。$B$B我連一個手下都沒看到，取代他們的則是名符其實的機器人及人造人大軍，四處在忙著它們的工作!$B$B這些人造人外表看起來像是地精，它們說它們一直在等著我們。事實上，他們以奇怪的方式動作著，就好像認得我們一樣。我們被包圍，並迅速帶上幫浦站的頂層。$B$B我們就是在那看到他們的首領，並且看到他們對其它倖存下來的地精做了些什麼 !', `MaleText_loc7`='Como te iba contando, no era posible explicar lo que vimos allí.$B$BMi gente había desaparecido y en su lugar había un auténtico ejército de robots y androides campando a sus anchas.$B$BLos androides tenían aspecto de gnomos y dijeron que habían estado esperándonos. De hecho, a su modo, actuaban como si nos conocieran. Nos rodearon y rápidamente nos llevaron a lo más alto de la estación de bombeo.$B$B¡Fue entonces cuando vimos a su líder y lo que estaba haciendo con los gnomos supervivientes!' WHERE `ID`=24904;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우두머리는 자신을 톱니반장 메카조드라고 부르더군요. 우리가 도착했을 때, 놈은 생존자를 새로운 기계류로 변형하는 데 열심이었어요!$B$B그놈은 우리를 열렬히 환영하고는, 전설 속의 울두아르에서 나온 티탄 수호자 ''조물주''가 처음으로 창조한 노움이 자기라는 거예요.$B$B부하들이 수천 년 전에 고장 난 쓰레기를 실수로 파내 버린 것이 분명했지요. 그런 몹쓸 녀석 바로 위에 채굴 현장을 차리다니, 우린 참 운이 없었어요.', `MaleText_loc4`='他自称是机甲专家麦卡佐德。我们被押上泵站顶层时，他正忙着将幸存者转换成机械生物！$B$B麦卡佐德热情地欢迎了我们，并解释说他是“大建筑师”的杰作，这位建筑师则是来自奥杜尔的泰坦守护者。$B$B我们这才明白，原来是这家伙堵塞了主管道。他显然出过什么故障，被埋在地底有数千年了吧，却因此重见天日。我们正好将泵站建在他的头顶，也真够“幸运”的。', `MaleText_loc5`='他自稱為齒輪大師梅卡佐德。當我們抵達時，他正忙著將倖存者轉化為機器生物!$B$B他熱烈的歡迎我們，並解釋他是由某個位於傳說中的奧杜亞大廳，稱之為「大建築師」的泰坦看守者所創造出來的首位地精。$B$B很顯然地，他就是我的團隊意外地在數千年前他發生故障的地點所吸出來的障礙。而我們只是碰巧在他上方建立了幫浦站。', `MaleText_loc7`='Se hace llamar el maestro de palancas Mecazod. ¡Cuando llegamos, estaba ocupado trasvasando los cerebros de los supervivientes a cuerpos mecánicos!$B$BNos saludó con afecto y nos explicó que él era uno de los primeros gnomos creados por algo llamado "el gran arquitecto", un vigilante titán del legendario Ulduar.$B$BPor lo visto, él era el obstáculo que mi equipo había absorbido accidentalmente del lugar en el que se había estropeado miles de años atrás. ¡Y nosotros tuvimos que construir nuestra estación de bombeo justo sobre él!' WHERE `ID`=24905;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='채굴 현장에 있던 수리공들이 그 괴물을 조립해서 다시 ''살려내고'' 만 거죠.$B$B그리고 놈은 감사의 표시로, 놈이 말하는 ''육체의 저주''에서 우릴 해방하고 있는 거예요.$B$B메카조드의 말에 따르면, 육체라는 건 티탄의 모든 창조물이 나쁜 형태로 변해버린 거래요! 바꿔 말하자면 우리는 원래 로봇 형태로 창조되었는데, 수천 년의 세월 동안 육체를 가진 존재로 변해갔다는 말이죠!$B$B웃기는 소리라는 건 저도 잘 알아요.', `MaleText_loc4`='在泵站机械师的帮助下，这家伙“活”了过来。$B$B于是，他打算帮助我们“治疗”所谓的“血肉诅咒”，以此表达他的感激之情。$B$B按照麦卡佐德的说法，正是这种诅咒在逐渐侵蚀泰坦的创造物！换句话说，最初我们都是机械侏儒之类的玩意儿，在经历了数千年的演变之后，才成为有血有肉的生物的！$B$B这简直太荒谬了。', `MaleText_loc5`='幫浦站的技師將他重新組合，讓他「活」了起來。$B$B現在，為了答謝，為了回報，他治療了我們所有人身上被他稱為「血肉詛咒」的東西。$B$B據梅卡佐德所說，那是所有泰坦創生物最終都將面臨的命運!換句話說，我們大概開始都會像某種機器人，然後，經過數千年，再慢慢轉變為有血有肉的生物體!$B$B十分荒謬，我知道。', `MaleText_loc7`='Los mecánicos de la estación lo habían reconstruido, devolviéndolo a la "vida".$B$BY ahora, como agradecimiento, nos iba a devolver el favor curándonos del mal que él denomina "la maldición de la carne".$B$BSegún Mecazod, es una dolencia que acaba afectando a todas las creaciones de los titanes. Dicho de otra forma, todos empezamos siendo robots de algún tipo y con el paso de los milenios poco a poco nos vamos volviendo seres de carne.$B$BLo sé, es absurdo.' WHERE `ID`=24906;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그건 전혀 ''치료''처럼 보이지도 않았고, 웬 미친 로봇이 내 부하를 토막 내면서 지껄이는 헛소리를 듣고 싶은 생각도 전혀 없었어요!$B$B우린 정상적인 노움이라면 누구나 했을 행동을 했지요... 도망치는 거요! 뭐 사실 대부분은 거기서 낙하산을 타고 뛰어내렸을 뿐이에요. 그래서 어떻게 됐는지는 여길 둘러봤으니 이미 아시겠지요.$B$B살아서 돌아온 이들은 그리 많지 않고, 처리할 다른 일도 태산같이 쌓였어요. 북쪽에는 마그나타우르, 동쪽에는 스컬지, 게다가 설상가상으로 북서쪽에는 호드 놈들이 둥지를 틀었다고요!', `MaleText_loc4`='这哪里是什么“治疗”啊，而且我也不打算继续听这个机械疯子的胡言乱语，尤其是他还当面屠杀我们的同胞！$B$B你瞧，我们都是心智正常的侏儒……只能选择逃跑！好吧，大多数人都纵身跃下了平台，结果你也看到了。$B$B只有少数幸运儿得以逃生。我们势单力薄，本来就疲于应付北方的猛犸人和东方的天灾军团。如今，部落又在西北方扎营，局势真是糟糕透顶！', `MaleText_loc5`='這在我看起來不像是種「治療」，而我也不打算站在旁邊聽某個瘋狂機器人長篇大論，尤其他還正在屠殺我的族人!$B$B我們做出了任何一個神智清醒的地精會做的事...腳底抹油!好吧，事實上，我們撐著降落傘從平台邊跳下去，不過你可以料想的到。$B$B我們當中能夠回到這裡的人手不多，我們的人數也還不夠去處理其他的事情，像是北邊的猛瑪象人以及東邊的天譴軍團。更糟的是，部落剛好在西北邊設了據點!', `MaleText_loc7`='A mí no me parecía una "cura" y no estaba dispuesto a quedarme parado escuchando a un robot demente mientras masacraba a mi gente.$B$BHicimos lo que cualquier gnomo en su sano juicio hubiera hecho... ¡corrimos! Bueno, de hecho, la mayoría de nosotros nos lanzamos en paracaídas desde la plataforma, pero te haces una idea.$B$BSolo unos pocos conseguimos regresar aquí y aún estamos bastante mermados, pues también nos tenemos que encargar de todo lo demás: el magnatauro al norte y la Plaga al este. ¡Por no mencionar que la Horda se ha establecido al noroeste!' WHERE `ID`=24907;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 우리가 처한 상황을 이해하시겠지요, $n 님?$B$B우리가 직접 모든 걸 다 처리할 수도 없는 상황인 데다, 솔직히 말해 그럴 능력도 안 된다고요. 앞으로 어떤 일을 처리해야 하는지는 징키가 잘 알아요. 가서 그녀를 만나보세요.$B$B몸뚱이를 온전하게 갖춘 채로 이 망할 곳에서 나가게 해 주기만 하면 더 바랄 게 없겠어요.', `MaleText_loc4`='$n，我们陷入了进退维谷的窘境。$B$B我们根本没有能力应付眼前的种种状况，说实话，我真是心有余而力不足啊。我建议你去找金吉谈一谈。她或许会告诉你接下来要怎么办。$B$B只希望你能在确保我们的安全的同时，处理好这堆烂摊子。', `MaleText_loc5`='而那就是我們現在發現自己的地方，$n。$B$B我們可能沒辦法自己處理這所有的事情，而且坦白講，這對我來說太複雜了，金基知道該怎麼辦。你應該馬上去見她。$B$B我只希望你可以帶我們安全的逃出這片混亂。', `MaleText_loc7`='Eso explica nuestro estado actual, $n.$B$BNo podemos encargarnos de esto nosotros solos y, para serte sincero, me siento un poco perdido en este asunto. Jinky sabe lo que hay que hacer. Deberías ir a verla ahora.$b$bSolo espero que seas capaz de sacarnos de este lío con nuestros cuerpos intactos.' WHERE `ID`=24908;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='올 것이 왔군, $n. 종말의 시작이지. 자네도 직접 목격하게 된 걸세...', `MaleText_loc4`='你瞧，$n。世界末日很快就会降临。而你，将成为这噩梦的终结者……', `MaleText_loc5`='這就是了，$n，世界末日的開端。而你是來為它送行的...', `MaleText_loc7`='Esto es todo, $n. El comienzo del fin del mundo. Y tú estás aquí para verlo...' WHERE `ID`=24909;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가세나...', `MaleText_loc4`='我们走……', `MaleText_loc5`='我們走吧...', `MaleText_loc7`='Vamos...' WHERE `ID`=24910;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 전부인가? 위대한 호드가 모을 수 있는 병력이 고작 이것뿐이란 말인가?', `MaleText_loc4`='就这样？这就是伟大的部落所能召集到的全部人手？', `MaleText_loc5`='就這樣?這就是偉大的部落所能集結的全部人手嗎?', `MaleText_loc7`='¿Esto es todo? ¿La poderosa Horda no ha podido conseguir nada más?' WHERE `ID`=24911;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비참하군.', `MaleText_loc4`='真可悲。', `MaleText_loc5`='真可悲。', `MaleText_loc7`='Patético.' WHERE `ID`=24912;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너 같은 녀석들을 도저히 이해할 수 없더군. 영웅놀이나 하는 녀석들...', `MaleText_loc4`='我真是搞不懂你这样的人物。英雄……', `MaleText_loc5`='我永遠都不懂你們這種人。所謂的英雄...', `MaleText_loc7`='Nunca entendí a los tipos como tú. El héroe...' WHERE `ID`=24913;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 순리에 따르지 않는 건가? 왜 운명에 맞서려는 거지?', `MaleText_loc4`='为什么不选择放弃？为什么要执泥于必然的结局？', `MaleText_loc5`='為什麼你就是不能當作沒事呢?為什麼老是要去挑戰不可避免之事?', `MaleText_loc7`='¿Por qué no te rindes? ¿Por qué luchas contra lo inevitable?' WHERE `ID`=24914;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕을 막을 수는 없다. 포기해라.', `MaleText_loc4`='巫妖王是不可战胜的。认命吧。', `MaleText_loc5`='巫妖王無人能擋，接受這個事實。', `MaleText_loc7`='No se puede detener al Rey Exánime. Acéptalo.' WHERE `ID`=24915;
