UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 $g녀석:여자;의 시체를 가져가서 되살려낼 준비를 해라.', `MaleText_loc4`='把$g他:她;带走，准备复活仪式。', `MaleText_loc5`='把$g他:她;帶走，並準備將$g他:她;復生。', `MaleText_loc7`='$gLleváoslo:Lleváosla; y $gpreparadlo:preparadla; para la reanimación.' WHERE `ID`=24917;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n의 몸에 손끝 하나 대기도 전에 네 오그라든 심장을 내 손으로 열어주마, 강령술사여.', `MaleText_loc4`='巫师，在你伤害$n之前，我就会徒手将你干枯的徽记拿过来。', `MaleText_loc5`='死靈法師，在你動$n一根寒毛之前，我會用我的雙手將你那乾枯的心臟給挖出來。', `MaleText_loc7`='Antes de que $n sufra ningún daño, te arrancaré el corazón con mis propias manos, nigromante.' WHERE `ID`=24918;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자넨 절대 혼자가 아니었다네, $n.', `MaleText_loc4`='$n，你永远不会孤单。', `MaleText_loc5`='你永遠不會孤軍奮戰，$n。', `MaleText_loc7`='Nunca estuviste $gsolo:sola;, $n.' WHERE `ID`=24919;
