UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 육체가 먼지와 부스러기만 남을 때까지 모든 힘을 다해 싸울 것이다. 끝까지 싸울 것이야.', `MaleText_loc4`='我们将竭尽全力于你抗衡——直到化为尘埃。我们会战斗到最后一刻。', `MaleText_loc5`='我的族人會用盡一切對抗你 - 直到我們化成灰燼為止。我們會對抗你直到一切都結束為止。', `MaleText_loc7`='Lucharemos contra ustedes con cada fibra de nuestro ser hasta que no seamos más que polvo y deshechos. Lucharemos hasta el final.' WHERE `ID`=24924;
