UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 전쟁노래 요새로 돌아가야 하네. 헬스크림 님께서 이곳에서 일어난 일을 분명히 알고 싶어하실 걸세. 그리고 사울팽 님께도 무슨 일이 일어났는지도 말이야...', `MaleText_loc4`='朋友，你应该立即返回战歌要塞。地狱咆哮一定很想知道……关于萨鲁法尔的故事。', `MaleText_loc5`='你應該馬上回去戰歌堡，朋友。地獄吼一定想要聽聽剛剛在這發生的事...有關薩魯法爾的...', `MaleText_loc7`='Ahora deberías regresar al Bastión Grito de Guerra, colega. Grito Infernal querrá estar al tanto de lo que acaba de ocurrir aquí... de lo de Colmillosauro...' WHERE `ID`=24934;
