UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 순간전송기는 우리 목숨이나 마찬가지야. 제대로 작동하지 않으면 우린 그냥 죽는 거라고!', `FemaleText_loc4`='这台转换器是我们生存的关键。如果修不好它，我们就死定了！', `FemaleText_loc5`='傳送器是我們活下來的關鍵。要是它沒辦法完整運作的話，我們就糟糕了!', `FemaleText_loc7`='Esta transmateria es la clave para sobrevivir. Si no logramos que funcione correctamente, ¡no lo contaremos!' WHERE `ID`=24954;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네가 그걸 제대로 고쳐놓지 않으면, 우린 분명히 숯불구이 신세가 될 거라고!', `FemaleText_loc4`='要是你不能让这玩意儿正常运转，我们就完蛋了！', `FemaleText_loc5`='要是你不能讓那東西全面運作，我們就糗了!', `FemaleText_loc7`='¡Si no logras que funcione correctamente, acabaremos como una tostada!' WHERE `ID`=24955;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청한 노예 정령 같으니! 너와 네 주인은 쓸데없이 간섭한 대가를 치를 거다!', `MaleText_loc4`='愚蠢的元素仆从！你和你的主人会付出代价的！', `MaleText_loc5`='愚蠢的元素奴僕!你和你的主人都將為了你愛管閒事付出代價!', `MaleText_loc7`='¡Esclavo elemental estúpido! ¡Tú y tu maestro pagaréis por haberos entrometido así!' WHERE `ID`=24956;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='징키, 징키... 난 온 힘을 다하고 있다고!', `MaleText_loc4`='金吉，没看见我正在绞尽脑汁地鼓捣这玩意儿吗！', `MaleText_loc5`='金基呀，金基，我已經盡我所知的去做了!', `MaleText_loc7`='¡Jolines, Jinky, lo estoy haciendo lo mejor que sé!' WHERE `ID`=24957;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 순간전송기 기술자로 보여? 그리고, 아예 작동 안 하는 것도 아니잖아. 전송받기만 하는 거라도...', `MaleText_loc4`='我看上去像是修理转换器的专家吗？！至少这玩意儿的输入装置……还能用。', `MaleText_loc5`='對你來說，我看起來像傳輸技工嗎?!至少我們有收入...多少啦。', `MaleText_loc7`='¡¿Tengo pinta de técnico de transmateria?! Al menos tenemos entrada... o algo así.' WHERE `ID`=24958;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 팅키가 나가버린 건 내 잘못이 아니야. 이건 걔가 만든 거라고... 난 그저 끼우고 붙이는 것밖에 못 봤단 말이야.', `MaleText_loc4`='你瞧，又不是我让丁奇跑掉的。这玩意儿是她的宝贝……她不费吹灰之力就能让它运转起来的。', `MaleText_loc5`='聽著，汀基飛走不是我的錯，那東西是她的寶貝...我只是看著她只用口水和膠水就把它搞定了，難怪會出事。', `MaleText_loc7`='Mira, no es mi culpa que Mañosa se haya marchado. Esta cosa es su bebé... la he visto mantenerlo funcionando a base de saliva y pegamento.' WHERE `ID`=24959;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 대애애애애단히 도움이 돼... 지 않는군!', `MaleText_loc4`='你真是……一点用都没有！', `MaleText_loc5`='你真是幫了我們大～～～～～～忙...才怪!', `MaleText_loc7`='Eres de gran ayuda… ¡O MÁS BIEN NO!' WHERE `ID`=24960;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 거의 다 된 것 같은데... 이 다이얼만 돌리고 나면... 윽, 이런.', `MaleText_loc4`='嗯，我觉得似乎是修好了。只要转动仪表盘，……啊噢！', `MaleText_loc5`='對啦，我猜我想到了。只要把這個鍵這麼扭一下...唔，糟糕。', `MaleText_loc7`='Sí, creo que por fin lo tengo. No hay más que girar esta rueda y… oh, oh.' WHERE `ID`=24961;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나라면 아직은 그걸 쓰지 않겠지만, 직접 시험해 보고 싶다면 마음대로 하라고.', `MaleText_loc4`='我才不要使用这玩意儿呢，你想要测试的话，请便好了。', `MaleText_loc5`='我還不能使用它，不過你要是想要測試的話請自便。', `MaleText_loc7`='Yo no lo usaría aún, pero puedes probarlo en tu persona cuando quieras.' WHERE `ID`=24962;
