UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기가 어디야? 당신 누구죠? 이 이상한 느낌은 뭐지?', `MaleText_loc4`='我在哪儿？你是谁？为什么我的感觉这么奇怪？', `MaleText_loc5`='這是哪裡?你是誰?這是什麼奇怪的感覺?', `MaleText_loc7`='¿Dónde estoy? ¿Quién eres? ¿Qué es esta sensación tan extraña?', `FemaleText_loc1`='여기가 어디야? 당신 누구죠? 이 이상한 느낌은 뭐지?', `FemaleText_loc4`='我在哪儿？你是谁？为什么我的感觉这么奇怪？', `FemaleText_loc5`='這是哪裡?你是誰?這是什麼奇怪的感覺?', `FemaleText_loc7`='¿Dónde estoy? ¿Quién eres? ¿Qué es esta sensación tan extraña?' WHERE `ID`=24971;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='메카조드는 미쳤어요! 더 늦기 전에 당신이 막아야 해요!', `MaleText_loc4`='麦卡佐德发疯了！你必须立即阻止他！', `MaleText_loc5`='梅卡佐德發瘋了!在一切都太遲以前你一定要阻止他!', `MaleText_loc7`='¡Mecazod ha perdido la cabeza! ¡Debes detenerlo antes de que sea demasiado tarde!', `FemaleText_loc1`='메카조드는 미쳤어요! 더 늦기 전에 당신이 막아야 해요!', `FemaleText_loc4`='麦卡佐德发疯了！你必须立即阻止他！', `FemaleText_loc5`='梅卡佐德發瘋了!在一切都太遲以前你一定要阻止他!', `FemaleText_loc7`='¡Mecazod ha perdido la cabeza! ¡Debes detenerlo antes de que sea demasiado tarde!' WHERE `ID`=24972;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 끔찍했어요! 모두 다 개조당했다고요!', `MaleText_loc4`='太可怕了！他们全变成了机械！', `MaleText_loc5`='太恐怖了!他們都變了!', `MaleText_loc7`='¡Ha sido horrible! ¡Los han cambiado a todos!', `FemaleText_loc1`='정말 끔찍했어요! 모두 다 개조당했다고요!', `FemaleText_loc4`='太可怕了！他们全变成了机械！', `FemaleText_loc5`='太恐怖了!他們都變了!', `FemaleText_loc7`='¡Ha sido horrible! ¡Los han cambiado a todos!' WHERE `ID`=24973;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈은 그걸 육체의 저주라고 하더군요. 메카조드는 정신이 나갔어요!', `MaleText_loc4`='麦卡佐德说那是“血肉诅咒”。他发疯了！', `MaleText_loc5`='他把它稱作血肉詛咒。梅卡佐德錯亂了!', `MaleText_loc7`='Lo llamó la maldición de la carne… ¡Mecazod está trastornado!', `FemaleText_loc1`='놈은 그걸 육체의 저주라고 하더군요. 메카조드는 정신이 나갔어요!', `FemaleText_loc4`='麦卡佐德说那是“血肉诅咒”。他发疯了！', `FemaleText_loc5`='他把它稱作血肉詛咒。梅卡佐德錯亂了!', `FemaleText_loc7`='Lo llamó la maldición de la carne… ¡Mecazod está trastornado!' WHERE `ID`=24974;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 탈영병들은 수치스럽기 그지없는 일을 저질렀네. 눈으로 직접 봐야 믿을 법한, 정말로 수치스러운 짓이지. 그래서 우그소르를 여기 데려왔네... 이 아이도 알아야 하지 않겠나.', `MaleText_loc4`='逃兵的行径让我们倍感羞耻。这种耻辱感是如此强烈，你只有在亲身经历后才能有所体会。这也是乌格索来到这里的原因……他必须得到教训。', `MaleText_loc5`='這些叛逃者的行為使我們全體蒙羞。一個如此強大的恥辱，必須親眼證實才有辦法了解。這就是為什麼烏格索在這的原因...這個男孩必須學習這個道理。', `MaleText_loc7`='Las acciones de estos desertores nos ponen a todos en evidencia. Solo los que son testigos de su magnitud entienden la vergüenza que supone. Por eso Ug''thor está aquí… Debe aprender.' WHERE `ID`=24975;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 말을 하기 부끄럽지만... 노르크. 제 탈영병이 어디 갔는지 모르겠습니다.', `MaleText_loc4`='诺克，我真是难以启齿……逃兵不见了。', `MaleText_loc5`='我不好意思說，諾克，不過我的叛逃者不見了。', `MaleText_loc7`='Me avergüenza decirlo, Nork, pero mi desertor ha desaparecido.', `FemaleText_loc1`='이런 말을 하기 부끄럽지만... 노르크. 제 탈영병이 어디 갔는지 모르겠어요.', `FemaleText_loc4`='诺克，我真是难以启齿……逃兵不见了。', `FemaleText_loc5`='我不好意思說，諾克，不過我的叛逃者不見了。', `FemaleText_loc7`='Me avergüenza decirlo, Nork, pero mi desertor ha desaparecido.' WHERE `ID`=24976;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번에는 주의해서 호송하게, $n. 얼라이언스와 서로 체면을 지키는 건 중요한 문제일세.', `MaleText_loc4`='$n，别让这名逃兵再溜走了。至少我们得维护联盟的颜面。', `MaleText_loc5`='試著別再把這一個叛逃者搞丟了，$n。這很重要，至少我們嘗試著與聯盟保持表面的和平。', `MaleText_loc7`='Intenta no perder este, $n. Es importante que al menos intentemos mantener las apariencias ante la Alianza.' WHERE `ID`=24977;
