UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말했잖아요, 순간전송기는 싫다고! 난 이제 기계노움이 아닌데, 잘못되면 어쩌라고요!', `MaleText_loc4`='别再跟我提什么转换器了！我已经不是机械侏儒了。', `MaleText_loc5`='我說，不，傳遞者!至少我再也不是機械地精了。', `MaleText_loc7`='¡He dicho que NADA de transmateria! Por lo menos ya no soy un mecagnomo.', `FemaleText_loc1`='말했잖아요, 순간전송기는 싫다고! 난 이제 기계노움이 아닌데, 잘못되면 어쩌라고요!', `FemaleText_loc4`='别再跟我提什么转换器了！我已经不是机械侏儒了。', `FemaleText_loc5`='我說，不，傳遞者!至少我再也不是機械地精了。', `FemaleText_loc7`='¡He dicho que NADA de transmateria! Por lo menos ya no soy un mecagnomo.' WHERE `ID`=24987;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 피와 살로 이루어진 노움이 되다니! 기분 좋군요!', `MaleText_loc4`='我又变回血肉之躯啦。这才是最重要的！', `MaleText_loc5`='我又再度有血有肉了。那才是最重要的事!', `MaleText_loc7`='¡Vuelvo a ser de carne y hueso! ¡Eso es lo único que importa!', `FemaleText_loc1`='다시 피와 살로 이루어진 노움이 되다니! 기분 좋군요!', `FemaleText_loc4`='我又变回血肉之躯啦。这才是最重要的！', `FemaleText_loc5`='我又再度有血有肉了。那才是最重要的事!', `FemaleText_loc7`='¡Vuelvo a ser de carne y hueso! ¡Eso es lo único que importa!' WHERE `ID`=24988;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밖에 나가지 마세요. 웅덩이에 로봇과 기계노움이 쫙 깔렸다고요!', `MaleText_loc4`='千万别进入池塘，那里到处是机器人和机械侏儒！', `MaleText_loc5`='別出去那裡。那池子間到處都是機器人跟機械地精!', `MaleText_loc7`='No salgas. ¡Las pozas están llenas de robots y mecagnomos!', `FemaleText_loc1`='밖에 나가지 마세요. 웅덩이에 로봇과 기계노움이 쫙 깔렸다고요!', `FemaleText_loc4`='千万别进入池塘，那里到处是机器人和机械侏儒！', `FemaleText_loc5`='別出去那裡。那池子間到處都是機器人跟機械地精!', `FemaleText_loc7`='No salgas. ¡Las pozas están llenas de robots y mecagnomos!' WHERE `ID`=24989;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이상한 기분이군요. 당신이 날 되살려 준 게 고맙지가 않아요...', `MaleText_loc4`='感觉怪怪的。你在重新组装我的时候是不是出了什么差错……', `MaleText_loc5`='我覺得很好笑。我不認為你完全恢復我了...', `MaleText_loc7`='Me siento raro. No creo que me hayas reintegrado correctamente...', `FemaleText_loc1`='이상한 기분이군요. 당신이 날 되살려 준 게 고맙지가 않아요...', `FemaleText_loc4`='感觉怪怪的。你在重新组装我的时候是不是出了什么差错……', `FemaleText_loc5`='我覺得很好笑。我不認為你完全恢復我了...', `FemaleText_loc7`='Me siento rara. No creo que me hayas reintegrado correctamente...' WHERE `ID`=24990;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지휘관에게 알려야 해요. 메카조드가 공격할 거야! 우린 망했어!', `MaleText_loc4`='立即转告指挥官：麦卡佐德准备向我们发动袭击！我们完蛋了！', `MaleText_loc5`='需要通知指揮官:梅卡佐德計畫發動一場攻擊!我們死定了!', `MaleText_loc7`='Hay que informar al comandante: ¡Mecazod planea un ataque! ¡Estamos perdidos!', `FemaleText_loc1`='지휘관에게 알려야 해요. 메카조드가 공격할 거야! 우린 망했어!', `FemaleText_loc4`='立即转告指挥官：麦卡佐德准备向我们发动袭击！我们完蛋了！', `FemaleText_loc5`='需要通知指揮官:梅卡佐德計畫發動一場攻擊!我們死定了!', `FemaleText_loc7`='Hay que informar al comandante: ¡Mecazod planea un ataque! ¡Estamos perdidos!' WHERE `ID`=24991;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='효과가 끝내주는군요! 무기력해지셨지요? 약해지셨지요? 열도 나지 않았습니까?', `FemaleText_loc4`='真是厉害！你有没有觉得四肢无力？很虚弱吗？体内一阵潮热？', `FemaleText_loc5`='這實在是太糟糕了!對你一點用也沒有嗎?虛弱?潮紅?', `FemaleText_loc7`='¡Qué positivamente horrible! ¿Te quedaste $gindefenso:indefensa;? ¿Sin fuerzas? ¿Tenías golpes de calor?' WHERE `ID`=24992;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간이 없습니다!', `MaleText_loc4`='没时间可以浪费了！', `MaleText_loc5`='沒有時間了!', `MaleText_loc7`='¡No hay tiempo que perder!' WHERE `ID`=24993;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명심하시오, $n. 그 핏빛포자 가루를 사용하면 감모스에 있는 어떤 마그나타우르도 약하게 할 수 있소.', `MaleText_loc4`='$n，血孢花粉能削弱犸格莫斯所有猛犸人的力量。', `MaleText_loc5`='還有，$n，記得，血孢粉末可以讓所有甘默斯的猛瑪象人弱化。', `MaleText_loc7`='Y recuerda, $n, el polvo de sanguiespora se puede usar para debilitar a todos los magnatauros de Gammoth.' WHERE `ID`=24994;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고맙습니다. 달라란의 친구여.', `FemaleText_loc4`='谢谢你，达拉然的朋友。', `FemaleText_loc5`='謝謝你，達拉然之友。', `FemaleText_loc7`='Gracias, camarada de Dalaran.' WHERE `ID`=24995;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기서 지체하면 안 됩니다... 좀 안전한 곳으로 갈 테니 가까이 오세요.', `FemaleText_loc4`='我们不能在这里久留……靠近我，我们要转移到安全的地方去。', `FemaleText_loc5`='這兒不能再待了...靠近點 - 我會帶領我們到安全的地方。', `FemaleText_loc7`='No debemos permanecer aquí... No os alejéis y os guiaré a algún lugar seguro.' WHERE `ID`=24996;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생명 유지 물질 수집 완료.', `MaleText_loc4`='状态：已完成生命物质的收集。', `MaleText_loc5`='狀態:生命給予實體聚集完成。', `MaleText_loc7`='Estado: recolecta de sustancia recuperadora de vida completada.' WHERE `ID`=24997;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼빠진 땜장이 녀석들. 그런 보잘것없는 물건으로 정말 날 막을 수 있다고 생각하느냐?', `MaleText_loc4`='蠢货，你真以为你那可笑的创造物能阻止我吗？', `MaleText_loc5`='弱智的技工，你真的覺得你那可悲的東西可以阻止我嗎?', `MaleText_loc7`='Estúpido manitas, ¿realmente crees que tu patética creación puede detenerme?' WHERE `ID`=24998;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 부근에서는 조심하십시오, $r. 이 근방에 사는 녀석들은 자비심이라곤 없으니 말입니다.', `FemaleText_loc4`='$r，处处小心啊。血孢平原生活着许多残忍的生物。', `FemaleText_loc5`='小心這些心皮，$r。這些當地人可是很殘忍的。', `FemaleText_loc7`='Ten cuidado por aquí, $r. Los nativos son despiadados.' WHERE `ID`=24999;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 기계노움이다... 저항은 무의미하다.', `MaleText_loc4`='我们是机械侏儒……放弃抵抗吧。', `MaleText_loc5`='我們是機械地精...不要做無謂的抵抗。', `MaleText_loc7`='Somos mecagnomos... es inútil resistirse.' WHERE `ID`=25000;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너는 저주받았다. 우리가 그 저주를 치료하겠다.', `MaleText_loc4`='你被诅咒了，我们会治好你的。', `MaleText_loc5`='你們被詛咒了，我們是來治療的。', `MaleText_loc7`='Tú estás maldito y nosotros somos la solución.' WHERE `ID`=25001;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='육체는 약하다. 우리가 너를 보다 강하고... 빠르게 바꿔 주마.', `MaleText_loc4`='血肉之躯太脆弱了。我们能让你变得更加完美、强壮……敏捷。', `MaleText_loc5`='血肉之軀太虛弱了。我可以讓你更強、更壯...更快。', `MaleText_loc7`='La carne es débil. Te haremos mejor, más fuerte... más rápido.' WHERE `ID`=25002;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저주를 풀어 주마. 우리에게는 기술이 있으니까.', `MaleText_loc4`='我们能移除你身上的诅咒，我们拥有强大的科技。', `MaleText_loc5`='我們可以解除你的詛咒，我們有那種技術。', `MaleText_loc7`='Podemos quitarte la maldición, tenemos la tecnología.' WHERE `ID`=25003;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='톱니반장님께서 허약한 육체를 벗어나게 해 주실 거다.', `MaleText_loc4`='机甲专家能改造你那虚弱的血肉之躯。', `MaleText_loc5`='齒輪大師針對你脆弱的肉體有些計畫。', `MaleText_loc7`='El maestro de palancas tiene planes para tu débil carne.' WHERE `ID`=25004;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘은 북풍의 땅, 내일은 전 세계가 될 것이다!', `MaleText_loc4`='今天，北风苔原是我们的。明天，全世界都是我们的！', `MaleText_loc5`='今天，僅僅是北風凍原，明天，就是全世界!', `MaleText_loc7`='Hoy, la Tundra Boreal. ¡Mañana, el mundo!' WHERE `ID`=25005;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네게 내린 저주를 풀어 주마!', `MaleText_loc4`='让我们移除你身上的诅咒吧！', `MaleText_loc5`='你會被解咒的!', `MaleText_loc7`='¡Te liberaré de la maldición!' WHERE `ID`=25006;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리와 함께 완벽한 존재가 되자, $g형제:자매;여!', `MaleText_loc4`='我们能让你变得完美。', `MaleText_loc5`='完好無缺的回來，$g兄弟:姊妹;。', `MaleText_loc7`='Ven a alcanzar la perfección con nosotros $g hermano:hermana;.' WHERE `ID`=25007;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보수 작업을 개시한다.', `MaleText_loc4`='开始维修。', `MaleText_loc5`='維修啟動。', `MaleText_loc7`='Mantenimiento iniciado.' WHERE `ID`=25008;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='임무 보고합니다!', `MaleText_loc4`='长官，向您报到！', `MaleText_loc5`='前來報到，$g先生:女士;!', `MaleText_loc7`='¡Me presento para trabajar, $gseñor:señora;!' WHERE `ID`=25009;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 동족의 원수를 갚겠다고 투스카르의 율법에 맹세했습니다... 이 살인마들이 팔에아를 완전히 불태워버렸습니다.', `MaleText_loc4`='以海象人的名义起誓，我要为族人复仇……这帮凶手将帕尔依烧得精光。', `MaleText_loc5`='我以巨牙海民的律法起誓，我將會為我的族人復仇...這些兇手燒毀了整個帕雷亞。', `MaleText_loc7`='He jurado bajo ley colmillarr que vengaría a mi pueblo... estos asesinos redujeron Pal''ea a cenizas.' WHERE `ID`=25010;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 농민, 귀족, 상인의 아들과 거지를 치료했습니다. 이 보잘것없는 지식을 당신과도 나눌 수 있게 해 주십시오. 죽음 앞에서 우리는 모두 같은 존재입니다.', `MaleText_loc4`='我医治过农夫、贵族、商贩和乞丐。我要告诉你一个真理：面对死亡时，我们都一样。', `MaleText_loc5`='我曾經治療過農民、貴族、商人之子與乞丐，讓我跟你分享一些智慧的話語 - 當面對死亡的時候，每個人都是一樣的。', `MaleText_loc7`='He tratado a campesinos, nobles, hijos de mercaderes y pordioseros. Permíteme que comparta algo de sabiduría contigo: cuando miramos a los ojos de la muerte, todos somos iguales.' WHERE `ID`=25011;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='트웡키!', `MaleText_loc4`='托奇！', `MaleText_loc5`='噹機!', `MaleText_loc7`='¡Twonky!' WHERE `ID`=25012;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='ED-210 작동 개시!', `MaleText_loc4`='ED-210来啦！', `MaleText_loc5`='ED-210上線!', `MaleText_loc7`='¡ED-210 conectado!' WHERE `ID`=25013;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 메카조드 님이 보낸 전령이다. 네게 걸린 저주를 풀어주마!', `MaleText_loc4`='我是麦卡佐德的使者。我们会治好你的！', `MaleText_loc5`='我來通報梅卡佐德的信息，你們會被解咒的!', `MaleText_loc7`='Soy el heraldo de Mecazod. ¡Te libraré de la maldición!' WHERE `ID`=25014;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쓸데없는 참견도 이걸로 끝이다. 내가 널 쓰러뜨리고 나면 메카조드 님이 저주를 풀어주실 것이다.', `MaleText_loc4`='闹剧该结束了。一旦我搞定你，麦卡佐德就会治愈你身上的诅咒。', `MaleText_loc5`='你的胡鬧要告一段落了，只要我解決你，梅卡佐德就可以解除你的詛咒。', `MaleText_loc7`='Tu intromisión está llegando a su fin. Mecazod levantará tu maldición cuando yo haya acabado contigo.' WHERE `ID`=25015;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네싱워리가 네 가죽을 몇 푼이나 쳐 줄지 궁금하군!', `MaleText_loc4`='如果我献上你的皮，说不定奈辛瓦里会赏我点什么！', `MaleText_loc5`='我真想知道用你的皮可以跟奈辛瓦里換到什麼!', `MaleText_loc7`='¡Me pregunto qué me dará Nesingwary por tu pellejo!', `FemaleText_loc1`='네싱워리가 네 가죽을 몇 푼이나 쳐 줄지 궁금하군!', `FemaleText_loc4`='如果我献上你的皮，说不定奈辛瓦里会赏我点什么！', `FemaleText_loc5`='我真想知道用你的皮可以跟奈辛瓦里換到什麼!', `FemaleText_loc7`='¡Me pregunto qué me dará Nesingwary por tu pellejo!' WHERE `ID`=25016;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헤멧이 네 뼈를 어딘가 유용하게 써먹을 거다!', `MaleText_loc4`='我猜老赫米特肯定会用得着你的骨头的！', `MaleText_loc5`='我肯定老赫米特一定可以用你的骨頭來做點什麼!', `MaleText_loc7`='¡Estoy seguro de que el viejo Hemet podrá hacer algo con tus huesos!', `FemaleText_loc1`='헤멧이 네 뼈를 어딘가 유용하게 써먹을 거다!', `FemaleText_loc4`='我猜老赫米特肯定会用得着你的骨头的！', `FemaleText_loc5`='我肯定老赫米特一定可以用你的骨頭來做點什麼!', `FemaleText_loc7`='¡Estoy segura de que el viejo Hemet podrá hacer algo con tus huesos!' WHERE `ID`=25017;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발굽 50개만 더 모으면 새 총을 가질 수 있어!', `MaleText_loc4`='还要50只蹄子我就能有新火枪啦！', `MaleText_loc5`='只要再50多個蹄子，我就可以有新槍了!', `MaleText_loc7`='¡Cincuenta pezuñas más y tendré la pistola nueva!', `FemaleText_loc1`='발굽 50개만 더 모으면 새 총을 가질 수 있어!', `FemaleText_loc4`='还要50只蹄子我就能有新火枪啦！', `FemaleText_loc5`='只要再50多個蹄子，我就可以有新槍了!', `FemaleText_loc7`='¡Cincuenta pezuñas más y tendré la pistola nueva!' WHERE `ID`=25018;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽여, 죽여, 죽여어어어!!!', `MaleText_loc4`='杀杀杀！！！！！', `MaleText_loc5`='殺殺殺!!!!!!!', `MaleText_loc7`='¡¡¡¡¡¡MATAR, MATAR, MATAR!!!!!!', `FemaleText_loc1`='죽여, 죽여, 죽여어어어!!!', `FemaleText_loc4`='杀杀杀！！！！！', `FemaleText_loc5`='殺殺殺!!!!!!!', `FemaleText_loc7`='¡¡¡¡¡¡MATAR, MATAR, MATAR!!!!!!' WHERE `ID`=25019;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 저녁거리는 네 녀석이다!', `MaleText_loc4`='今天晚上有肉吃啦！', `MaleText_loc5`='晚上有嫩肉排吃了!', `MaleText_loc7`='¡Esta noche toca ternera!', `FemaleText_loc1`='오늘 저녁거리는 네 녀석이다!', `FemaleText_loc4`='今天晚上有肉吃啦！', `FemaleText_loc5`='晚上有嫩肉排吃了!', `FemaleText_loc7`='¡Esta noche toca ternera!' WHERE `ID`=25020;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뿔, 발굽, 꼬리, 모피, 가죽, 피부, 뭐든지 좋아!', `MaleText_loc4`='角、角茸、蹄子、尾巴、毛、皮……什么都成！', `MaleText_loc5`='牛角，鹿角，蹄子，尾巴，毛皮，獸皮，外皮，管它什麼都可以啦!', `MaleText_loc7`='¡Cuernos, cornamentas, pezuñas, colas, pelajes, pellejos, pieles, ME DA IGUAL!', `FemaleText_loc1`='뿔, 발굽, 꼬리, 모피, 가죽, 피부, 뭐든지 좋아!', `FemaleText_loc4`='角、角茸、蹄子、尾巴、毛、皮……什么都成！', `FemaleText_loc5`='牛角，鹿角，蹄子，尾巴，毛皮，獸皮，外皮，管它什麼都可以啦!', `FemaleText_loc7`='¡Cuernos, cornamentas, pezuñas, colas, pelajes, pellejos, pieles, ME DA IGUAL!' WHERE `ID`=25021;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 바로 진정한 재미지!', `MaleText_loc4`='让我们较量一下吧！', `MaleText_loc5`='現在「這」才是競技活動!', `MaleText_loc7`='¡ESTO es deporte!', `FemaleText_loc1`='이게 바로 진정한 재미지!', `FemaleText_loc4`='让我们较量一下吧！', `FemaleText_loc5`='現在「這」才是競技活動!', `FemaleText_loc7`='¡ESTO es deporte!' WHERE `ID`=25022;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='포기해라, 하찮은 짐승아!', `MaleText_loc4`='放弃吧，小鬼！', `MaleText_loc5`='放棄吧，小畜生!', `MaleText_loc7`='¡Ríndete, pequeña bestia!', `FemaleText_loc1`='포기해라, 하찮은 짐승아!', `FemaleText_loc4`='放弃吧，小鬼！', `FemaleText_loc5`='放棄吧，小畜生!', `FemaleText_loc7`='¡Ríndete, pequeña bestia!' WHERE `ID`=25023;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이야, 나를 찾고 있었느냐? 왜 나를 죽이려 하느냐, $n? 난 단지 도우려는 것뿐인데.', `MaleText_loc4`='孩子，你是来找我的吗？$n，为什么要杀我呢？我只是想帮忙啊。', `MaleText_loc5`='孩子，你在找我嗎?$n，你為什麼要殺我?我不過是想幫忙而已。', `MaleText_loc7`='¿Me buscabas? ¿Por qué vienes a matarme, $n? Yo solo quería ayudar.' WHERE `ID`=25024;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 다시 조립되었으니 우리는 완벽의 시대로 돌아갈 수 있다... 티탄의 시대로 말이다!', `MaleText_loc4`='我再次复苏啦，这样我们就能回到那个完美的时代……泰坦的时代！', `MaleText_loc5`='既然我已經被重新組裝完畢，我們又能重返完美的年代...泰坦的年代!', `MaleText_loc7`='Ahora que me han vuelto a montar podemos regresar a una era de perfección... ¡a la era de los titanes!' WHERE `ID`=25025;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만, 네 눈을 보고 네 맥박을 들으니 알겠구나. 너는 내가 약속한 영생을 뿌리치고 날 파괴할 작정임을 말이다!', `MaleText_loc4`='你的眼神和心跳骗不了我，虽然我能让你永生，但是你还是会杀了我！', `MaleText_loc5`='但是，我從你的眼睛中看出，你的脈搏中聽見，你將無視我所提出的不朽生命而毀掉我!', `MaleText_loc7`='Pero lo veo en tus ojos y lo oigo en el latido de tu corazón. ¡Me destruirías a pesar de mi oferta de inmortalidad!' WHERE `ID`=25026;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋다. 일이 이렇게 되어 슬프구나. 너희를 모두 내 자식처럼 생각했건만... 그래야만 한다면, 죽여 주마!', `MaleText_loc4`='非常好。事情变成这样真令我难过。我把你们都当作自己的孩子。如果有必要的话，我会杀了你的！', `MaleText_loc5`='很好，事情走到這步田地讓我萬分痛心，我把你們每一個視如己出。但如果必要我還是會親手殺了你們!', `MaleText_loc7`='Muy bien. Lamento que hayamos tenido que llegar a esto. Cuido de todos ustedes como si fueran mis propios hijos. ¡Te mataré si es necesario!' WHERE `ID`=25027;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대는 정당한 동기와 진실한 마음을 지니고 행동합니까? 그렇다면, 동물을 윤리적이고 따뜻하게 대하는 동물보호협회를 대표해 그대를 환영합니다. 어둠의 꼬임에 넘어가 동물과 공존하지 않고 그들을 해치는 무리가 있습니다. 그대가 그런 행동만 하지 않는다면, 동물보호협회는 그대를 동맹으로 여길 겁니다.', `MaleText_loc4`='你是否心怀虔诚，崇尚正义？如果是，欢迎你与德鲁伊一起为保护动物贡献力量。只要你没有误入歧途，没有伤害过那些与我们共同分享这片天空的生灵，你就是仁德会的朋友。', `MaleText_loc5`='你的動機公正且內心忠誠嗎?如果是，德魯伊動物人道對待協會很歡迎你。只要你不會轉向墮落的黑暗道路，傷害那些允許我們與之共存的動物們，D.E.H.T.A.都會將你視為盟友。', `MaleText_loc7`='¿Es justa tu causa y fiel tu corazón? Si es así, los Druidas por la Ética y Humanidad en el Trato de Animales te damos la bienvenida. Mientras no pasees por el oscuro camino de la depravación y hagas daño a los animales que nos han permitido coexistir en su mundo, D.E.H.T.A te considerará un aliado.' WHERE `ID`=25028;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기적이군! 스스로 가죽을 벗어버리다니!', `MaleText_loc4`='真是怪事！这畜生剥掉了自己的皮！', `MaleText_loc5`='這是奇蹟!野獸自己剝皮了!', `MaleText_loc7`='¡Es un milagro! ¡La bestia se ha despellejado a sí misma!', `FemaleText_loc1`='기적이군! 스스로 가죽을 벗어버리다니!', `FemaleText_loc4`='真是怪事！这畜生剥掉了自己的皮！', `FemaleText_loc5`='這是奇蹟!野獸自己剝皮了!', `FemaleText_loc7`='¡Es un milagro! ¡La bestia se ha despellejado a sí misma!' WHERE `ID`=25029;
