UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이것만 있으면 네싱워리 스테이크 나이프 세트를 받을 수 있겠어!', `MaleText_loc4`='就差一只，我就能弄齐一套奈辛瓦里牛排刀啦！', `MaleText_loc5`='奈辛瓦里牛排刀組是我最不想要的東西!', `MaleText_loc7`='¡Este es el último que necesito para conseguir el juego de cuchillos para carne de Nesingwary!', `FemaleText_loc1`='이것만 있으면 네싱워리 스테이크 나이프 세트를 받을 수 있겠어!', `FemaleText_loc4`='就差一只，我就能弄齐一套奈辛瓦里牛排刀啦！', `FemaleText_loc5`='奈辛瓦里牛排刀組是我最不想要的東西!', `FemaleText_loc7`='¡Este es el último que necesito para conseguir el juego de cuchillos para carne de Nesingwary!' WHERE `ID`=25031;
