UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 조종사는 추락으로 목숨을 잃었습니다.', `MaleText_loc4`='这名飞行侦察员未能在空难中生还。', `MaleText_loc5`='這位偵查駕駛員沒能從他的中隊墜機事件中存活下來。', `MaleText_loc7`='Este piloto de reconocimiento no sobrevivió al accidente de su escuadrón.' WHERE `ID`=25041;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조종사의 계급장을 찾습니다.', `MaleText_loc4`='寻找飞行员的佩章。', `MaleText_loc5`='找出駕駛員徽記。', `MaleText_loc7`='Busca la insignia de piloto.', `FemaleText_loc1`='조종사의 계급장을 찾습니다.', `FemaleText_loc4`='寻找飞行员的佩章。', `FemaleText_loc5`='找出駕駛員徽記。', `FemaleText_loc7`='Busca la insignia de piloto.' WHERE `ID`=25042;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정신 나갔어요? 우릴 다 날려버릴 뻔했잖아요! 이 잔해는 다른 일이 다 끝나거든 제가 처리할 거라고요.', `MaleText_loc4`='你疯了吗？你差点把我们炸上天！等我搞定其他事情再来处理这堆残骸吧。', `MaleText_loc5`='你瘋了嗎?你差點就把我們炸翻天!在其他東西完成以前，這個殘骸由我來看管。', `MaleText_loc7`='No estás bien de la cabeza. ¡Estás a punto de volarnos por los aires! Yo me encargaré de este destrozo cuando haya acabado con todo lo demás.' WHERE `ID`=25043;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='망할 드루이드 놈들이 머리에 피도 안 마른 녀석을 사지에 몰아넣는군? 원하는 대로 해 주마, 애송이!', `MaleText_loc4`='这帮德鲁伊是专程派些小鬼来送死的吗？蛤蜊主宰成全你！', `MaleText_loc5`='那些德魯伊他們現在都派小孩來送死嗎?蚌殼大師真感謝，朋友!', `MaleText_loc7`='¿Esos druidas están enviando niños a morir? ¡El maestro de almejas tiene que hacer algo, colega!' WHERE `ID`=25044;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 가죽을 벗겨서 팔아도 고객들은 눈치를 못 채겠지!', `MaleText_loc4`='你的皮也成啊，反正客户也瞧不出什么差别！', `MaleText_loc5`='把你的皮剝掉，我們的客戶永遠都不知道哪裡不同!', `MaleText_loc7`='¡Bien despellejado nuestros clientes no notarán la diferencia!' WHERE `ID`=25045;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 고마운 듯 울음소리를 냅니다!', `MaleText_loc4`='%s发出了赞许的叫声！', `MaleText_loc5`='%s贊同的發出吼聲!', `MaleText_loc7`='¡%s trompetea mostrando aprobación!' WHERE `ID`=25046;
