UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우릴 바보로 아느냐! 동물의 피를 뒤집어쓴 주제에 무슨 변명이냐!', `MaleText_loc4`='你把我们当傻子吗！你身上沾满了动物的鲜血！', `MaleText_loc5`='你以為我們是傻蛋嘛!你全身都是動物的血!', `MaleText_loc7`='¿Crees que somos tontos? ¡Estás cubierto en sangre de animal!', `FemaleText_loc1`='우리가 모를 줄 아느냐! 네 몸에 묻은 동물의 피가 아직 마르지도 않았다!', `FemaleText_loc4`='你把我们当傻子吗！你身上沾满了动物的鲜血！', `FemaleText_loc5`='你以為我們是傻蛋嘛!你全身都是動物的血!', `FemaleText_loc7`='¿Crees que somos tontos? ¡Estás cubierto en sangre de animal!' WHERE `ID`=25052;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도살자! 죽어라!', `MaleText_loc4`='刽子手！去死吧！', `MaleText_loc5`='劊子手!死吧!', `MaleText_loc7`='¡CARNICERO! ¡MUERE!', `FemaleText_loc1`='죽어라, 잔인한 놈!', `FemaleText_loc4`='刽子手！去死吧！', `FemaleText_loc5`='劊子手!死吧!', `FemaleText_loc7`='¡CARNICERO! ¡MUERE!' WHERE `ID`=25053;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어린 동물을 죽이다니, 이 백정 같은 놈! 대가를 치를 것이다!', `MaleText_loc4`='屠夫！凶手！你会付出代价的！', `MaleText_loc5`='幼獸殺手!兇手!你會得到報應的!', `MaleText_loc7`='¡Asesino de terneras! ¡Sicario! ¡Pagarás por esto!', `FemaleText_loc1`='살인자나 다름없는 놈! 힘없는 새끼를 죽이다니! 우리가 가만둘 줄 아느냐!', `FemaleText_loc4`='屠夫！凶手！你会付出代价的！', `FemaleText_loc5`='幼獸殺手!兇手!你會得到報應的!', `FemaleText_loc7`='¡Asesino de terneras! ¡Sicario! ¡Pagarás por esto!' WHERE `ID`=25054;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='채집 중', `MaleText_loc4`='采集', `MaleText_loc5`='收集', `MaleText_loc7`='Recolección' WHERE `ID`=25055;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진짜 한심을 넘어서 두심하군. 신도레이는 드레나이 같은 잡종들과는 상종하지 않는 법인데 말이지.', `MaleText_loc4`='实在太可悲了。辛多雷是不会和德莱尼杂种们联合起来的。', `MaleText_loc5`='真是可悲。辛多雷並沒有打算要跟像德萊尼這樣的雜種混在一起。', `MaleText_loc7`='Realmente patético. Se suponía que los sin''dorei no debían mezclarse con chuchos como los draenei.' WHERE `ID`=25056;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희도 우리가 곧 처리해 주마.', `MaleText_loc4`='我们很快就会好好收拾你。', `MaleText_loc5`='我們很快就會解決你們。', `MaleText_loc7`='Nos encargaremos de ti muy pronto.' WHERE `ID`=25057;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신네 블러드 엘프가 너무 늦기 전에 다시 우리와 손을 잡았으면 합니다.', `MaleText_loc4`='血精灵应当在一切为时太晚之前加入我们的行列。', `MaleText_loc5`='你們血精靈應該要即時的重返族群。', `MaleText_loc7`='Ustedes, los elfos de sangre, deberían reunirse con el rebaño antes de que sea demasiado tarde.' WHERE `ID`=25058;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='캘타스 왕자님께서는 당신네 모두를 다 감안하고 계획을 세워두셨습니다.', `MaleText_loc4`='你们都在凯尔萨斯王子的掌控之中。', `MaleText_loc5`='凱爾薩斯王子對你們全體皆有所計畫。', `MaleText_loc7`='El príncipe Kael''thas tiene planes para todos ustedes.' WHERE `ID`=25059;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘껏 도망쳐라. 그래 봤자 벼룩인 주제에. 너희 그 잘난 나루 지도자들에게 곧 끝장날 것이라고 전해라!', `MaleText_loc4`='快跑吧，败狗们。告诉你们的纳鲁主人，末日就在眼前！', `MaleText_loc5`='跑吧，廢物。去告訴你們的那魯主人末日就快到了!', `MaleText_loc7`='Corran, perros. ¡Diganle a sus maestros naaru que el final se acerca!' WHERE `ID`=25060;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 섬에 침입한 게 뭐 대수라도 되는 줄 아느냐? 너희는 다 죽은 목숨이나 마찬가지다!', `MaleText_loc4`='你们在岛上发动的可笑攻势毫无价值。很快你们全都会死！', `MaleText_loc5`='你們的入侵毫無意義。很快的你們將全數被殲滅!', `MaleText_loc7`='Su pequeña incursión en la isla no significa nada. ¡Pronto estarán todos muertos!' WHERE `ID`=25061;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='태양샘의 힘이 다시 한 번 쓰일 것이다!', `MaleText_loc4`='太阳之井的力量将会再次被我们掌握！', `MaleText_loc5`='太陽之井的力量將重新被掌握!', `MaleText_loc7`='¡El poder de La Fuente del Sol volverá a ser aprovechado de nuevo!' WHERE `ID`=25062;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조만간 너희도 저 악마처럼 우리를 섬길 것이다!', `MaleText_loc4`='你们应该就像那些恶魔一样听从我们的命令。', `MaleText_loc5`='到時，你們也會如同惡魔服侍我們一樣供我們使喚。', `MaleText_loc7`='Con el tiempo ustedes también obedecerán a nuestra voluntad, del mismo modo en que nos sirven los demonios.' WHERE `ID`=25063;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새로운 지령 입력. 마법학자이신 $n 님께 복종합니다.', `MaleText_loc4`='获得新的指示。按魔导师$n的命令行事。', `MaleText_loc5`='收到新的指令。聽從$g博學者:博學者;$n的命令。', `MaleText_loc7`='Nuevas directivas adquiridas. Obedecer $g al magister:a la magistrix; $n.' WHERE `ID`=25064;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배치 대상 미발견. 성소 탐색 중. 해당 지역은 태양 너울.', `MaleText_loc4`='没有找到部署目标。搜索类别：圣殿。方位：阳湾港。', `MaleText_loc5`='未發現部署目標。搜尋種類:聖所。地點:日境。', `MaleText_loc7`='No se ha encontrado el objetivo para el despliegue. Buscando tipo: Sagrario. Ubicación: Tramo del Sol.' WHERE `ID`=25065;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법학자이신 $n 님은 대단한 투사입니다. 분명히 캘타스 왕자님께서도 $n 마법학자님을 굉장히 자랑스러워 하실 것입니다.', `MaleText_loc4`='魔导师$n是一个伟大的战士，魔导师$n一定会让凯尔萨斯王子感到非常自豪。', `MaleText_loc5`='博學者$n是位偉大的鬥士。博學者$n必定讓凱爾薩斯王子感到非常驕傲。', `MaleText_loc7`='$g El magister:la magistrix; $n es muy eficaz en el combate. El príncipe Kael''thas ha de estar muy orgulloso $g del magister:de la magistrix; $n.' WHERE `ID`=25066;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아서스와 스컬지로부터 태양샘을 보호합니다. 문제 발생. 태양샘이 발견되지 않았습니다.', `MaleText_loc4`='保护太阳之井免受阿尔萨斯和天灾军团破坏。错误：未找到太阳之井。', `MaleText_loc5`='保護太陽之井免於遭受阿薩斯及天譴軍團的荼毒。錯誤:未發現太陽之井。', `MaleText_loc7`='Proteger La Fuente del Sol de Arthas y la Plaga. Error: Fuente del Sol no encontrada.' WHERE `ID`=25067;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대륙 어디나 불타오르는 우리 불꽃에는 맹렬한 기운과 진실한 마음이 가득합니다!', `MaleText_loc4`='让我们的火焰在整片大陆上熊熊燃烧吧！', `MaleText_loc5`='我們的火焰在陸地各處中強烈又真實的燃燒著!', `MaleText_loc7`='¡Nuestras llamas arden fuertes y leales a través del territorio!', `FemaleText_loc1`='대륙 어디나 불타오르는 우리 불꽃에는 맹렬한 기운과 진실한 마음이 가득하답니다!', `FemaleText_loc4`='让我们的火焰在整片大陆上熊熊燃烧吧！', `FemaleText_loc5`='我們的火焰在陸地各處中強烈又真實的燃燒著!', `FemaleText_loc7`='¡Nuestras llamas arden fuertes y leales a través del territorio!' WHERE `ID`=25068;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끈으로 장식된 축제 기둥 앞에서 벌써 춤춰보셨습니까?', `MaleText_loc4`='你在彩带杆那里跳过舞吗？', `MaleText_loc5`='你在緞帶柱邊跳過舞了嗎?', `MaleText_loc7`='¿Has bailado ya en el poste de las cintas?', `FemaleText_loc1`='끈으로 장식된 축제 기둥에서 벌써 춤춰보셨다고요?', `FemaleText_loc4`='你在彩带杆那里跳过舞吗？', `FemaleText_loc5`='你在緞帶柱邊跳過舞了嗎?', `FemaleText_loc7`='¿Has bailado ya en el poste de las cintas?' WHERE `ID`=25069;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불꽃 마술사들이 부리는 묘기, 정말 대단합니다!', `MaleText_loc4`='我羡慕那个家伙玩火炬的技巧。', `MaleText_loc5`='我欽佩火炬雜耍師的技術。', `MaleText_loc7`='Admiro la habilidad de los malabaristas de antorchas.', `FemaleText_loc1`='불꽃 마술사들이 부리는 묘기, 정말 대단하지요!', `FemaleText_loc4`='我羡慕那个家伙玩火炬的技巧。', `FemaleText_loc5`='我欽佩火炬雜耍師的技術。', `FemaleText_loc7`='Admiro la habilidad de los malabaristas de antorchas.' WHERE `ID`=25070;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 이 매머드 학살자 카우에게 도전하겠다고? 내 분노를 느껴 보아라!', `MaleText_loc4`='你要向猛犸毁灭者卡奥挑战！？啧啧，来一较高下吧！', `MaleText_loc5`='你在挑戰「長毛象摧毀者」卡烏嗎!?面對我、感受我的雷霆吧!', `MaleText_loc7`='¿Retas a Kaw, el Destructor de Mamuts? ¡Entonces enfréntate a mí y siente mis relámpagos!' WHERE `ID`=25071;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, $n, 어떤 물건이 맘에 드나?', `MaleText_loc4`='那么，$n，你想要什么东西？', `MaleText_loc5`='那麼，$n，你喜歡哪一樣東西啊?', `MaleText_loc7`='Entonces, $n, ¿qué objeto te interesa?' WHERE `ID`=25072;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놀랍기 그지없는 얼룩 제거용 정전기학 광선총을 동네에서 제일 먼저 소유하는 기쁨을 누리시죠!', `MaleText_loc4`='来率先体验一下超级无敌的静电除污器吧！', `MaleText_loc5`='成為團體中首位擁有電荷污漬破壞器的人吧!', `MaleText_loc7`='¡Sea el primero de su bloque en poseer el increíble Eliminador Electroestático de Máculas!' WHERE `ID`=25073;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 광선총은 무너진 태양 공격대의 최첨단 군사학 기술을 이용한 거고요, 아무리 오래 찌든 때라도 단번에 날려버린답니다!', `MaleText_loc4`='源自破碎残阳的军用高端技术，轻松去除各类顽固污渍！', `MaleText_loc5`='來自破碎之日進攻部隊最先進的軍隊科技，可輕易將頑固的污漬擊破!', `MaleText_loc7`='Derivado de la tecnología militar punta de la Ofensiva Sol Devastado, ¡elimina fácilmente las manchas más rebeldes!' WHERE `ID`=25074;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='포도주 흘린 자국, 풀물, 심지어 애완동물 배설물 자국도 얼룩 제거용 정전기학 광선총 앞에선 상대가 안 되죠!', `MaleText_loc4`='无论是酒渍、泥渍，还是宠物留下的污渍，静电除污器都能将它们清除干净！', `MaleText_loc5`='酒漬，草漬，連寵物污漬都不是電荷污漬破壞器的對手!', `MaleText_loc7`='¡Ni las manchas de vino, ni las de su mascota son un problema para el Eliminador Electroestático de Máculas!' WHERE `ID`=25075;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 망설이지 마세요! 지금 당장 주문하시면 제가 만든 와플제 초강력 다리미를 끼워드리죠!', `MaleText_loc4`='不要犹豫了！现在订购还能得到我免费赠送的超导聊天铁！', `MaleText_loc5`='別再遲疑了!現在就下訂購買我的電荷污漬破壞器，不需要額外費用喔!', `MaleText_loc7`='¡No espere! ¡Encárguelo ahora y reciba mi Gofrera Ultra-Cinética sin coste adicional!' WHERE `ID`=25076;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 신기하고 진귀한 물건 말이로군. 우린 안목 있는 여행자들을 위한 아제로스의 희귀한 물건들을 전문으로 취급하지.$B$B이렇게 나를 찾아온 걸 보니 자넨 찾는 물건이 있는 게로군.', `MaleText_loc4`='啊——各种珍品都在这里！我们专门为有识别能力的冒险者挑选艾泽拉斯世界的宝贝。$B$B既然你来找我谈话了，我想你肯定已经想好要什么了吧。', `MaleText_loc5`='啊 - 奇異又罕見的東西。我們專門為慧眼獨具的冒險家研究艾澤拉斯中獨一無二的物品。$B$B既然你都在跟我說話了，想必你一定對於你要找的東西有所了解。', `MaleText_loc7`='Ah, rarezas y artículos poco comunes. Estamos especializados en los objetos totalmente únicos de Azeroth para los aventureros más exigentes.$B$BSupongo que si estás hablando conmigo es porque tienes una idea de lo que estás buscando.' WHERE `ID`=25077;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아제로스의 영웅들', `MaleText_loc4`='艾泽拉斯英雄传', `MaleText_loc5`='艾澤拉斯的英雄', `MaleText_loc7`='Héroes de Azeroth', `FemaleText_loc1`='아제로스의 영웅들', `FemaleText_loc4`='艾泽拉斯英雄传', `FemaleText_loc5`='艾澤拉斯的英雄', `FemaleText_loc7`='Héroes de Azeroth' WHERE `ID`=25078;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='포인트 교환', `MaleText_loc4`='积分兑换', `MaleText_loc5`='點數清償', `MaleText_loc7`='Redención de puntos', `FemaleText_loc1`='포인트 교환', `FemaleText_loc4`='积分兑换', `FemaleText_loc5`='點數清償', `FemaleText_loc7`='Redención de puntos' WHERE `ID`=25079;
