UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아웃랜드의 불꽃', `MaleText_loc4`='外域之火', `MaleText_loc5`='外域之火', `MaleText_loc7`='Fuegos de Terrallende', `FemaleText_loc1`='아웃랜드의 불꽃', `FemaleText_loc4`='外域之火', `FemaleText_loc5`='外域之火', `FemaleText_loc7`='Fuegos de Terrallende' WHERE `ID`=25081;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='군단의 행진', `MaleText_loc4`='军团的远征', `MaleText_loc5`='燃燒軍團的進軍', `MaleText_loc7`='La marcha de la Legión', `FemaleText_loc1`='군단의 행진', `FemaleText_loc4`='军团的远征', `FemaleText_loc5`='燃燒軍團的進軍', `FemaleText_loc7`='La marcha de la Legión' WHERE `ID`=25082;
