UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 물건은 뭐가 있습니까?', `MaleText_loc4`='你还有什么其它的促销内容吗？', `MaleText_loc5`='你還有什麼其他的促銷嗎?', `MaleText_loc7`='¿Qué otras promociones tienes?', `FemaleText_loc1`='다른 물건은 뭐가 있나요?', `FemaleText_loc4`='你还有什么其它的促销内容吗？', `FemaleText_loc5`='你還有什麼其他的促銷嗎?', `FemaleText_loc7`='¿Qué otras promociones tienes?' WHERE `ID`=25084;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐요, 선구자 씨, 조사는 어떻게 진행되고 있나요? 당신이 그 결과를 일러주기만 하면 와플제 초강력 다리미를 드릴 수도 있는데!', `MaleText_loc4`='嘿，先驱者，调查进行得怎么样了？如果你在订购期限前购买的话，就有机会得到一块超导聊天铁哦。', `MaleText_loc5`='嘿，先驅者，調查的進展如何啊?如果你想要馬上得到結果的話，也許那裡的一塊超強力鐵模可以幫忙你喔!', `MaleText_loc7`='Hey, presagista, ¿qué tal va esa investigación? ¡Si esos resultados llegan rápido, puede que te ganes una Gofrera Ultra-Cinética!' WHERE `ID`=25085;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조사하는 중입니다, 와플프라이 씨. 뭐 다른 할 일 없으신가요? 새로운 기계 장치를 시험해 봐야 한다든가...', `MaleText_loc4`='一切进展顺利，瓦菲雷。你不是要去做些产品示范之类的事情吗？', `MaleText_loc5`='調查正在進行中，炸餅。你難道沒有產品發表或是別的事情可以做嗎?', `MaleText_loc7`='Está llegando, Papasfritas. ¿No tienes alguna demostración de producto que hacer o algo así?' WHERE `ID`=25086;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카우의 미늘창이 두 토막으로 부러져 땅에 떨어집니다!', `MaleText_loc4`='卡奥的三叉戟断成两截，掉在了地上！', `MaleText_loc5`='卡烏的長戟斷成兩截掉到地上!', `MaleText_loc7`='¡La alabarda de Kaw se parte en dos y cae al suelo!', `FemaleText_loc1`='카우의 미늘창이 두 토막으로 부러져 땅에 떨어집니다!', `FemaleText_loc4`='卡奥的三叉戟断成两截，掉在了地上！', `FemaleText_loc5`='卡烏的長戟斷成兩截掉到地上!', `FemaleText_loc7`='¡La alabarda de Kaw se parte en dos y cae al suelo!' WHERE `ID`=25087;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='연금술사들이 특정한 보석들을 변환할 수 있다는 걸 아십니까? 마르나와 이 문제에 대해 이야기를 좀 나눴죠.$B$B그녀의 솜씨는 정말 훌륭해요. 그러니 마르나의 실험실만 완성되면, 세월 속에서 사라졌다고 여겨지는 보석을 그녀와 제가 만들어낼 수 있을 겁니다.', `FemaleText_loc4`='你知道炼金师可以转化特定的宝石吗？玛尔娜和我讨论过这个问题。$B$B我深信只要能给她造好炼金台，就可以让她发挥自己的才干。这样一来我和她也就可以去制造那些被认为已经失传的宝石了。', `FemaleText_loc5`='你知道鍊金師可以轉化某些寶石嗎?瑪納和我一直都在討論這件事。$B$B我確信她擁有非凡的能力，一旦她的實驗室落成，她和我將可以製造出傳說中失傳已久的寶石。', `FemaleText_loc7`='¿Sabías que los alquimistas pueden transmutar ciertas gemas? Mar''nah y yo hemos estado hablando sobre esto.$B$BEstoy convencida de que con su destreza, en cuanto su laboratorio esté terminado, ella y yo podremos crear gemas que se creían perdidas para siempre.' WHERE `ID`=25088;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='해냈습니다, $n. 마르나는 아주 특별한 보석들을 변환하는 법을 익혔어요. 저는 그 보석들을 어떻게 사용하는지 배웠고요.', `FemaleText_loc4`='我们成功了，$n。玛尔娜已经学会一些非常特殊的宝石的转化方法了。我也已经知道了该如何好好利用它们。', `FemaleText_loc5`='我們做到了，$n。瑪納已經學會如何轉化非一般寶石了。而我則學會了如何使用它們。', `FemaleText_loc7`='Bien hecho, $n. Mar''nah ha aprendido a transmutar unas gemas muy especiales. Y yo he aprendido a trabajarlas.' WHERE `ID`=25089;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 태양너울에서 반드시 승리할 것이오! 여기 나루가 나타나 우리를 축복해 주었소!', `MaleText_loc4`='我们已经在阳湾港取得了全面的胜利！纳鲁祝福着我们！', `MaleText_loc5`='我們位於日境的勝利是全面性的!那魯以他們的到來祝福著我們!', `MaleText_loc7`='¡Nuestra victoria en Tramo del Sol es definitiva! ¡Los naaru nos bendicen con su presencia!' WHERE `ID`=25090;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두려워하지 마십시오, $r|1이여;여;. 우리의 목적지는 같습니다.', `MaleText_loc4`='不要害怕，$r。我们有着相同的目标。', `MaleText_loc5`='別被嚇著了，$r。我們的結局會是一樣的。', `MaleText_loc7`='No temas, $r. Nuestro fin es el mismo.' WHERE `ID`=25091;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 누구십니까?', `MaleText_loc4`='你是谁？', `MaleText_loc5`='你是誰?', `MaleText_loc7`='¿Quién eres tú?', `FemaleText_loc1`='당신은 누구신가요?', `FemaleText_loc4`='你是谁？', `FemaleText_loc5`='你是誰?', `FemaleText_loc7`='¿Quién eres tú?' WHERE `ID`=25092;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 푸른용군단의 일원인 칼렉고스입니다.$b$b태양샘에서 스며 나오기 시작한 에너지를 한동안 지켜봤지요. 그 무서운 에너지는 이 세계에 종말을 불러올지도 모릅니다!', `MaleText_loc4`='我是蓝龙军团的卡雷苟斯。$B$B我监视太阳之井形成的能量已经有一段时间了，但是现在我意识到，它那可怕的能量也许会导致世界的毁灭！', `MaleText_loc5`='我是卡雷苟斯，隸屬於藍龍軍團。$b$b我看顧著形成中的太陽之井力量已經好一陣子了，但是現在我發現它駭人的力量將會導致我們的世界毀滅!', `MaleText_loc7`='Yo soy Kalecgos del Vuelo Azul.$B$BLlevo tiempo observando los nacientes poderes de La Fuente del Sol...¡Pero ahora sé que su terrible poder podría provocar el fin de nuestro mundo!' WHERE `ID`=25093;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 여기에 오셨습니까?', `MaleText_loc4`='你在这里干什么？', `MaleText_loc5`='是什麼將你引領至此地來?', `MaleText_loc7`='¿Qué te trae a este lugar?', `FemaleText_loc1`='왜 여기에 오셨나요?', `FemaleText_loc4`='你在这里干什么？', `FemaleText_loc5`='是什麼將你引領至此地來?', `FemaleText_loc7`='¿Qué te trae a este lugar?' WHERE `ID`=25094;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 불타는 군단 군주인 킬제덴과 그 수하들에게 사로잡힌 인간 아가씨를 구하러 동료와 함께 여기 왔습니다.$b$b저희는 캘타스가 태양샘 저 깊숙한 곳을 통해 불타는 군단 군주인 킬제덴을 소환하려고 한다는 걸 알았지요!$b$b이 세계를 지키려면 반드시 이를 막아야 합니다! 저는 이 끔찍한 계획이 실패했음을 확인할 사명을 지니고 있습니다.', `MaleText_loc4`='我和一个朋友一起赶来，想要从燃烧军团的首领基尔加丹手中营救一位年轻的姑娘。$B$B我们发现凯尔萨斯正在尝试从太阳之井的深处召唤出基尔加丹！$B$B为了这个世界——我们不能让他的计划成功！我的任务就是阻止他们。', `MaleText_loc5`='我和一位朋友前來解救一位年輕的人類女性逃離軍團領主，基爾加丹與其邪惡手下的掌控。$b$b我們發現凱爾薩斯正試圖將基爾加丹從太陽之井的深處召喚出來。$b$b為了這個世界好 - 不能讓這件事發生!我保證會親自阻止這件事。', `MaleText_loc7`='Un amigo y yo hemos venido a rescatar a una joven mujer humana de las garras del Señor de la Legión, Kil''jaeden, y sus infames esbirros.$B$BHemos descubierto que Kael''thas está tratando de invocar al señor de la Legión, Kil''jaeden, desde lo más profundo de la mismísima Fuente del Sol.$B$B¡Por el bien de este mundo, eso no puede suceder! Me he comprometido a evitarlo.' WHERE `ID`=25095;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희가 어떻게 당신을 도우면 되겠습니까?', `MaleText_loc4`='我们有什么可以帮你的吗？', `MaleText_loc5`='我們要怎麼協助你呢?', `MaleText_loc7`='¿Qué podemos hacer para ayudarte?', `FemaleText_loc1`='저희가 어떻게 당신을 도우면 될까요?', `FemaleText_loc4`='我们有什么可以帮你的吗？', `FemaleText_loc5`='我們要怎麼協助你呢?', `FemaleText_loc7`='¿Qué podemos hacer para ayudarte?' WHERE `ID`=25096;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='캘타스를 쓰러뜨리려면 그대들 모두가 각자 노력해야 합니다.$b$b능력이 된다면 군대를 소집해 태양샘에 산재하는 수많은 문제를 해결해 보는 것도 좋겠습니다.$b$b어쩌면 우리는 거기서 다시 만날지도 모르지요.', `MaleText_loc4`='打败凯尔萨斯是一件值得你专心去做的事情。$B$B除此之外，如果你能组织一支军队的话，太阳之井里面还有许多邪恶的家伙需要你去处理。$B$B也许我们会在那里再次相遇。', `MaleText_loc5`='擊敗凱爾薩斯是一個適合你們全體意志的任務。$b$b除此之外，如果你們能夠組成一支軍隊，太陽之井裡有許多的錯誤待修正。$b$b或許我們會在那裡重逢。', `MaleText_loc7`='Vencer a Kael''thas es una tarea a la que tendrás que prestar toda tu atención.$B$BAdemás, si eres capaz de organizar un ejército, hay muchas más cosas de las que encargarse en La Fuente del Sol.$B$BQuizá volvamos a encontrarnos allí.' WHERE `ID`=25097;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방해하지 마라!', `MaleText_loc4`='这里不允许你来打扰！', `MaleText_loc5`='你無權介入!', `MaleText_loc7`='¡No puedes interferir!', `FemaleText_loc1`='어떤 녀석이 방해하는 거냐!', `FemaleText_loc4`='这里不允许你来打扰！', `FemaleText_loc5`='你無權介入!', `FemaleText_loc7`='¡No puedes interferir!' WHERE `ID`=25098;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 꿈이 실현되리라!', `MaleText_loc4`='我们的理想终将实现！', `MaleText_loc5`='我們的看法將會被理解!', `MaleText_loc7`='¡Nuestra visión se llevará a cabo!', `FemaleText_loc1`='우리의 꿈은 실현될 것이다!', `FemaleText_loc4`='我们的理想终将实现！', `FemaleText_loc5`='我們的看法將會被理解!', `FemaleText_loc7`='¡Nuestra visión se llevará a cabo!' WHERE `ID`=25099;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정령이 너를 처단하리라!', `MaleText_loc4`='元素会将你们彻底毁灭！', `MaleText_loc5`='元素將會摧毀你!', `MaleText_loc7`='¡Los elementos te aplastarán!', `FemaleText_loc1`='정령이 너를 처단할 것이다!', `FemaleText_loc4`='元素会将你们彻底毁灭！', `FemaleText_loc5`='元素將會摧毀你!', `FemaleText_loc7`='¡Los elementos te aplastarán!' WHERE `ID`=25100;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오세요, $c님. 이쪽 불꽃에 경의를 표하러 온 적이 있으신가요?$b$b얼라이언스가 있는 곳 어디나 우리 축제 불꽃이 타오른다는 걸 잊지 마세요. 괜찮으시다면 시간을 좀 내어 그 불꽃 전부를 찾아가 보시는 건 어떨까요?$B$B호드도 마찬가지로 자기네 불꽃을 피운답니다. 호드의 불꽃을 발견하면 그런 가치없는 노력은 좀 모독해줘도 좋을 겁니다.', `MaleText_loc4`='欢迎，$c。你有没有向这团火焰表达你的敬意？$B$B记住：我们的节日火焰在联盟的每一片土地上燃烧，如果你有时间的话，去向它们一一表达你的敬意。$B$B当然部落也点燃了他们自己的火焰，如果你有看到的话，记得去踏灭那些毫无价值的东西。', `MaleText_loc5`='歡迎，$c。你是來榮耀這座火焰的嗎?$b$b記住:我們的節慶火焰在每個擁有聯盟營區的土地上燃燒著。如果可以的話，花點時間前去榮耀每一座火焰吧。$b$b部落也是一樣，燃燒著屬於他們的火焰。當你遇到部落的火焰時，你還是褻瀆一下像這樣沒有意義的努力比較好。', `MaleText_loc7`='Saludos, $c. ¿Has venido a honrar esta llama?$B$BRecuerda: las hogueras de nuestro festival arden en todas las regiones con un asentamiento de la Alianza. Saca tiempo para honrarlas a todas si puedes.$B$BLa Horda también tiene sus propios fuegos. Harías bien en profanar esos indignos esfuerzos cuando los veas.', `FemaleText_loc1`='어서 오세요, $c님. 이쪽 불꽃에 경의를 표하러 온 적이 있으신가요?$b$b얼라이언스가 있는 곳 어디나 우리 축제 불꽃이 타오른다는 걸 잊지 마세요. 괜찮으시다면 시간을 좀 내어 그 불꽃 전부를 찾아가 보시는 건 어떨까요?$B$B호드도 마찬가지로 자기네 불꽃을 피운답니다. 호드의 불꽃을 발견하면 그런 가치없는 노력은 좀 모독해줘도 좋을 겁니다.', `FemaleText_loc4`='欢迎，$c。你有没有向这团火焰表达你的敬意？$B$B记住：我们的节日火焰在联盟的每一片土地上燃烧，如果你有时间的话，去向它们一一表达你的敬意。$B$B当然部落也点燃了他们自己的火焰，如果你有看到的话，记得去踏灭那些毫无价值的东西。', `FemaleText_loc5`='歡迎，$c。你是來榮耀這座火焰的嗎?$b$b記住:我們的節慶火焰在每個擁有聯盟營區的土地上燃燒著。如果可以的話，花點時間前去榮耀每一座火焰吧。$b$b部落也是一樣，燃燒著屬於他們的火焰。當你遇到部落的火焰時，你還是褻瀆一下像這樣沒有意義的努力比較好。', `FemaleText_loc7`='Saludos, $c. ¿Has venido a honrar esta llama?$B$BRecuerda: las hogueras de nuestro festival arden en todas las regiones con un asentamiento de la Alianza. Saca tiempo para honrarlas a todas si puedes.$B$BLa Horda también tiene sus propios fuegos. Harías bien en profanar esos indignos esfuerzos cuando los veas.' WHERE `ID`=25101;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 얼어붙은 땅의 지배자 네다르에게 도전하는 거냐?!', `MaleText_loc4`='你竟敢挑战北风苔原的领主尼达尔！？', `MaleText_loc5`='你好大的膽子挑戰凍原之王尼達爾!?', `MaleText_loc7`='¿Osas retar a Nedar, señor de la tundra?' WHERE `ID`=25102;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 무모함 때문에 죽는 줄 알아라!', `MaleText_loc4`='你的卤莽会毁了你！', `MaleText_loc5`='你的魯莽將造成你的死亡!', `MaleText_loc7`='¡Tu impetuosidad será tu final!' WHERE `ID`=25103;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 절대 이길 수 없어!', `MaleText_loc4`='你没有任何机会！', `MaleText_loc5`='想都不要想!', `MaleText_loc7`='¡No tienes ninguna posibilidad!' WHERE `ID`=25104;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보십시오, 저 아름다운 한여름의 불꽃을!', `MaleText_loc4`='看，夏日的烈焰！', `MaleText_loc5`='瞧，夏日火焰!', `MaleText_loc7`='¡Observad las llamas del verano!', `FemaleText_loc1`='보게나, 저 아름다운 한여름의 불꽃을!', `FemaleText_loc4`='看，夏日的烈焰！', `FemaleText_loc5`='瞧，夏日火焰!', `FemaleText_loc7`='¡Observad las llamas del verano!' WHERE `ID`=25105;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='데지 않게 조심하십시오!', `MaleText_loc4`='小心，不要被烧着了！', `MaleText_loc5`='當心點，別燒著了!', `MaleText_loc7`='¡Cuidado, no te quemes!', `FemaleText_loc1`='데지 않게 조심하게나!', `FemaleText_loc4`='小心，不要被烧着了！', `FemaleText_loc5`='當心點，別燒著了!', `FemaleText_loc7`='¡Cuidado, no te quemes!' WHERE `ID`=25106;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불꽃 축제는 재밌게 즐기고 계십니까?', `MaleText_loc4`='对火焰节满意吗？', `MaleText_loc5`='喜歡火焰節慶嗎?', `MaleText_loc7`='¿Disfrutando del Festival del Fuego?', `FemaleText_loc1`='불꽃 축제는 재밌게 즐기고 계신가?', `FemaleText_loc4`='对火焰节满意吗？', `FemaleText_loc5`='喜歡火焰節慶嗎?', `FemaleText_loc7`='¿Disfrutando del Festival del Fuego?' WHERE `ID`=25107;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오십시오! 이곳에 있는 불꽃에 예를 갖추셨습니까?', `MaleText_loc4`='欢迎！你有没有向这块大陆上的火焰表达你的敬意？', `MaleText_loc5`='歡迎!你榮耀過此地的火焰了嗎?', `MaleText_loc7`='¡Te doy la bienvenida! ¿Has honrado ya la llama de esta tierra?', `FemaleText_loc1`='어서 오시게! 이곳에 있는 불꽃에 예를 갖추셨나?', `FemaleText_loc4`='欢迎！你有没有向这块大陆上的火焰表达你的敬意？', `FemaleText_loc5`='歡迎!你榮耀過此地的火焰了嗎?', `FemaleText_loc7`='¡Te doy la bienvenida! ¿Has honrado ya la llama de esta tierra?' WHERE `ID`=25108;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 세계는 눈에 보이지 않는 방식으로 깊이 상처를 입었습니다. 심지어 시간의 흐름마저 약간 달라진 것 같아요.', `FemaleText_loc4`='这个世界遭受了许多我们肉眼看不到的破坏。甚至是时间的通路都感觉有些异常。', `FemaleText_loc5`='這個世界在各方面都遭受到超乎我們肉眼可見的破壞。甚至連時間的進程都感受到莫名的異常。', `FemaleText_loc7`='Este mundo ha sido dañado más allá de lo que nuestros ojos pueden ver. Incluso el paso del tiempo parece diferente en cierto modo.' WHERE `ID`=25109;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그대는 저희에게 큰 도움을 주셨습니다. 저는 중요한 임무를 띠고 여기 왔지만, 원하신다면 기꺼이 시간의 동굴로 보내 드리겠습니다.', `FemaleText_loc4`='你为我们做了很多。我来这里是为了执行一项重要的任务，不过如果你需要前往时光之穴的话，我很乐意带你去那里。', `FemaleText_loc5`='你已經為我們付出了許多。我目前在這裡執行一項重要的任務，但是如果你有需要前往時光之穴的話，我會很樂意帶領你前往。', `FemaleText_loc7`='Has hecho mucho por nosotros. Estoy llevando a cabo una importante misión, pero si necesitas ir a las Cavernas del Tiempo estaré encantada de llevarte hasta allí.' WHERE `ID`=25110;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간의 동굴로 보내 주십시오.', `MaleText_loc4`='送我去时光之穴。', `MaleText_loc5`='帶我前往時光之穴。', `MaleText_loc7`='Llévame a las Cavernas del Tiempo.', `FemaleText_loc1`='시간의 동굴로 보내 주세요.', `FemaleText_loc4`='送我去时光之穴。', `FemaleText_loc5`='帶我前往時光之穴。', `FemaleText_loc7`='Llévame a las Cavernas del Tiempo.' WHERE `ID`=25111;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조종사의 시체에서 노움 비상 도구함을 찾습니다.', `MaleText_loc4`='在飞行员的尸体上搜寻应急工具包。', `MaleText_loc5`='從屍體中尋找飛行員的緊急工具箱。', `MaleText_loc7`='Registra el cuerpo del piloto en busca del equipo de emergencia.', `FemaleText_loc1`='조종사의 시체에서 노움 비상 도구함을 찾습니다.', `FemaleText_loc4`='在飞行员的尸体上搜寻应急工具包。', `FemaleText_loc5`='從屍體中尋找飛行員的緊急工具箱。', `FemaleText_loc7`='Registra el cuerpo del piloto en busca del equipo de emergencia.' WHERE `ID`=25112;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='순록 발굽 30개면 조준경 달린 총을 준다고? 물론 계약해야지!', `MaleText_loc4`='30只驯鹿蹄子换一把带瞄准镜的步枪？！成交！', `MaleText_loc5`='三十隻馴鹿蹄換一把火槍的瞄準器?!算我一份!', `MaleText_loc7`='¿Treinta pezuñas de caribú por un rifle con mira telescópica? ¡Me apunto!', `FemaleText_loc1`='순록 발굽 30개면 조준경 달린 총을 준다고요? 계약!', `FemaleText_loc4`='30只驯鹿蹄子换一把带瞄准镜的步枪？！成交！', `FemaleText_loc5`='三十隻馴鹿蹄換一把火槍的瞄準器?!算我一份!', `FemaleText_loc7`='¿Treinta pezuñas de caribú por un rifle con mira telescópica? ¡Me apunto!' WHERE `ID`=25113;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신들이 누군지는 모르겠지만, 진주 10개면 받는다는 저 조갯살 보호모는 아주 맘에 쏙 드는군!', `MaleText_loc4`='我不认识你们，但是用10颗珍珠换那个蚌壳头盔似乎很合算！', `MaleText_loc5`='我是不清楚你們怎麼樣啦，但是拿十顆珍珠換一頂蚌肉盔真是棒呆了!', `MaleText_loc7`='No sé qué piensan ustedes, pero ese casco de carne de almeja a cambio de diez perlas tiene buena pinta.', `FemaleText_loc1`='당신들이 누군지는 모르겠지만, 진주 10개면 받는다는 저 조갯살 보호모는 아주 맘에 쏙 드는군요!', `FemaleText_loc4`='我不认识你们，但是用10颗珍珠换那个蚌壳头盔似乎很合算！', `FemaleText_loc5`='我是不清楚你們怎麼樣啦，但是拿十顆珍珠換一頂蚌肉盔真是棒呆了!', `FemaleText_loc7`='No sé qué piensan ustedes, pero ese casco de carne de almeja a cambio de diez perlas tiene buena pinta.' WHERE `ID`=25114;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='솔직히 얘기합시다. 난 레인에게 매머드 코를 15개나 줬는데 그가 나한테 준 건 고작 스테이크 써는 데나 쓸 법한 단검 한 세트뿐이었소. 어떻게 이럴 수가 있소? 어떻게 거래를 이런 식으로 하냐고?!', `MaleText_loc4`='让我直说吧：我用15根猛犸象牙和兰恩做买卖，他给了我一套匕首。我拿这玩意儿来切牛排吗？他怎么能这样？这买卖也太好做了吧？', `MaleText_loc5`='讓我搞懂來:我給了蘭恩十五根象鼻子，然後他給我一組可以用來當牛排刀的匕首?他怎麼辦到的?他要怎麼樣才能作成這筆驚人的生意??', `MaleText_loc7`='Deja que aclare esto: ¿le doy a Sendero quince trompas de mamut y él me da un juego de dagas que puedo usar como cuchillos para carne? ¿Cómo lo hace? ¿Cómo hace unos tratos tan alucinantes?', `FemaleText_loc1`='솔직히 얘기하자고요. 난 레인에게 매머드 코를 15개나 줬는데 그가 나한테 준 건 고작 스테이크 써는 데나 쓸 법한 단검 한 세트뿐이었다고요. 어떻게 이럴 수가 있죠? 어떻게 거래를 이런 식으로 하냐고요?!', `FemaleText_loc4`='让我直说吧：我用15根猛犸象牙和兰恩做买卖，他给了我一套匕首。我拿这玩意儿来切牛排吗？他怎么能这样？这买卖也太好做了吧？', `FemaleText_loc5`='讓我搞懂來:我給了蘭恩十五根象鼻子，然後他給我一組可以用來當牛排刀的匕首?他怎麼辦到的?他要怎麼樣才能作成這筆驚人的生意??', `FemaleText_loc7`='Deja que aclare esto: ¿le doy a Sendero quince trompas de mamut y él me da un juego de dagas que puedo usar como cuchillos para carne? ¿Cómo lo hace? ¿Cómo hace unos tratos tan alucinantes?' WHERE `ID`=25115;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말도 안 돼! 코뿔소 머리 30개에 코뿔소 보호모 하나를 주는 게 아주, 아주 싼 가격이라고? 두 개는 받아야겠소!', `MaleText_loc4`='不是吧！30个犀牛头就能换一个犀牛头盔？给我来两个！', `MaleText_loc5`='不會吧!犀牛頭盔帽只要三十顆犀牛頭的超低價?那我要兩頂!', `MaleText_loc7`='¡No puede ser! ¿Cascos de cabeza de rinoceronte al ridículo precio de treinta cabezas de rinoceronte? ¡Por ese precio me llevo dos!', `FemaleText_loc1`='말도 안 돼! 코뿔소 머리 30개에 코뿔소 보호모 하나를 주는 게 아주, 아주 싼 가격이라고요? 두 개는 받아야겠어요!', `FemaleText_loc4`='不是吧！30个犀牛头就能换一个犀牛头盔？给我来两个！', `FemaleText_loc5`='不會吧!犀牛頭盔帽只要三十顆犀牛頭的超低價?那我要兩頂!', `FemaleText_loc7`='¡No puede ser! ¿Cascos de cabeza de rinoceronte al ridículo precio de treinta cabezas de rinoceronte? ¡Por ese precio me llevo dos!' WHERE `ID`=25116;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 식으로 하면 네싱위리는 파산하고 말 걸! 레인은 자기가 뭘 하는지도 모르는 게야!', `MaleText_loc4`='如果奈辛瓦里一意孤行的话，他很快就会完蛋了！兰恩根本就不知道他在干什么！', `MaleText_loc5`='他只要這樣繼續搞下去，奈辛瓦里就會破產啦!蘭恩根本不清楚他在做什麼!', `MaleText_loc7`='¡Nesingwary se va a arruinar si sigue así! ¡Probablemente Sendero no tenga ni idea de qué está haciendo!', `FemaleText_loc1`='이런 식으로 하면 네싱위리는 파산하고 말 걸요! 레인은 자기가 뭘 하는지도 모르는 거예요!', `FemaleText_loc4`='如果奈辛瓦里一意孤行的话，他很快就会完蛋了！兰恩根本就不知道他在干什么！', `FemaleText_loc5`='他只要這樣繼續搞下去，奈辛瓦里就會破產啦!蘭恩根本不清楚他在做什麼!', `FemaleText_loc7`='¡Nesingwary se va a arruinar si sigue así! ¡Probablemente Sendero no tenga ni idea de qué está haciendo!' WHERE `ID`=25117;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 자식은 자기를 가죽왕이라고 하지만, 난 그냥 망할 놈이라고 부르지! 순록 새끼를 50마리나 잡아서 가죽을 벗겨다 주니, 고작 주는 거라곤 쥐털로 만든 겨울 양말 한 켤레가 전부라고! 그게 말이 되나?', `MaleText_loc4`='他居然自称皮草男爵——要我说，他简直是个吸血鬼！我用50张驯鹿皮换回的只是一双老鼠皮制成的冬袜？', `MaleText_loc5`='他自稱毛皮大亨 - 我說他是個混蛋!我收到一組全新鼠毛皮製成的冬襪，只用了50隻小馴鹿的皮?', `MaleText_loc7`='¡Se hace llamar el Barón de las pieles, pero yo lo llamo zoquete! ¿Por solo matar y desollar cincuenta caribús beige consigo un par de calcetines de invierno nuevos hechos con piel de rata?', `FemaleText_loc1`='그 자식은 자기를 가죽왕이라고 하지만, 난 그냥 망할 놈이라고 불러요! 순록 새끼를 50마리나 잡아서 가죽을 벗겨다 주니, 고작 주는 거라곤 쥐털로 만든 겨울 양말 한 켤레가 전부라니! 그게 말이 되나요?', `FemaleText_loc4`='他居然自称皮草男爵——要我说，他简直是个吸血鬼！我用50张驯鹿皮换回的只是一双老鼠皮制成的冬袜？', `FemaleText_loc5`='他自稱毛皮大亨 - 我說他是個混蛋!我收到一組全新鼠毛皮製成的冬襪，只用了50隻小馴鹿的皮?', `FemaleText_loc7`='¡Se hace llamar el Barón de las pieles, pero yo lo llamo zoquete! ¿Por solo matar y desollar cincuenta caribús beige consigo un par de calcetines de invierno nuevos hechos con piel de rata?' WHERE `ID`=25118;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동물 떼가 해럴드 레인을 짓밟으며 지나갑니다!', `MaleText_loc4`='哈罗德·兰恩被犀牛撞倒了！', `MaleText_loc5`='哈洛德·蘭恩被一群暴衝的獸群輾了過去!', `MaleText_loc7`='¡Harold Sendero es arrollado por una estampida!', `FemaleText_loc1`='동물 떼가 해럴드 레인을 짓밟으며 지나갑니다!', `FemaleText_loc4`='哈罗德·兰恩被犀牛撞倒了！', `FemaleText_loc5`='哈洛德·蘭恩被一群暴衝的獸群輾了過去!', `FemaleText_loc7`='¡Harold Sendero es arrollado por una estampida!' WHERE `ID`=25119;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 귀를 먹게 할 속셈인가? 애처로운 시도로군... 잠깐... 이게 무슨 소리지?', `MaleText_loc4`='你想打倒我？可怜虫……等等……那是什么声音？', `MaleText_loc5`='你要震聾我?真可悲...等等...那是什麼聲響?', `MaleText_loc7`='¿Estás tratando de dejarme sordo? Patético... Espera... ¿Qué es ese sonido?' WHERE `ID`=25120;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='투기장 사무관', `MaleText_loc4`='竞技场管理员', `MaleText_loc5`='競技場戰場軍官', `MaleText_loc7`='Maestros de batalla de arena', `FemaleText_loc1`='투기장 사무관', `FemaleText_loc4`='竞技场管理员', `FemaleText_loc5`='競技場戰場軍官', `FemaleText_loc7`='Maestros de batalla de arena' WHERE `ID`=25121;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='투기장 사무관은 고난의 거리 남동쪽 벽 근처에 있습니다.', `MaleText_loc4`='竞技场管理员就在东南面贫民窟的墙边。', `MaleText_loc5`='競技場戰場軍官就在沿著圍牆的陰鬱城東南邊。', `MaleText_loc7`='Los maestros de batalla de arena se encuentran al sudeste del Bajo Arrabal, junto a la muralla.', `FemaleText_loc1`='투기장 사무관은 고난의 거리 남동쪽 벽 근처에 있습니다.', `FemaleText_loc4`='竞技场管理员就在东南面贫民窟的墙边。', `FemaleText_loc5`='競技場戰場軍官就在沿著圍牆的陰鬱城東南邊。', `FemaleText_loc7`='Los maestros de batalla de arena se encuentran al sudeste del Bajo Arrabal, junto a la muralla.' WHERE `ID`=25122;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기 돌이 마지막일 거예요. 넵튤론 군대와 우리가 맺은 결속은 절대 깨어지지 않을 겁니다.', `FemaleText_loc4`='这些石头应该是最后一批了。我们和耐普图隆部队的合作将会无懈可击。', `FemaleText_loc5`='這些石頭應是最後一批了。我們和奈普圖隆軍隊的聯手將是無懈可擊的。', `FemaleText_loc7`='Estas piedras deberían ser las últimas. Nuestra coordinación con las fuerzas de Neptulon será impecable.' WHERE `ID`=25123;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그렇지요오. 바다사냥꾼은 우리가 여기까지 왔다는 사실에 기뻐할 거예요. 불의 군주가 지배하는 힘이 약해지리라 생각해요.', `FemaleText_loc4`='是的，猎潮者会对这项部署非常满意。火焰领主的威力将被削弱。', `FemaleText_loc5`='沒錯。獵潮者將會對此進展感到滿意。炎魔的控制將會變弱。', `FemaleText_loc7`='Sssí. El cazamareas estará satisfecho con estos avances. El control del Señor del Fuego se debilitará.' WHERE `ID`=25124;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 따로 준비한 건 없나요? 서리 군주는 차원문으로 가는 길을 확보할 수 있을까요?', `FemaleText_loc4`='那么你们自己的准备做得怎么样了？冰霜之王会打开通往传送门的道路吗？', `FemaleText_loc5`='你本身的準備工作呢?冰霜領主會有辦法通往傳送門嗎?', `FemaleText_loc7`='¿Y tus preparativos? ¿El Señor de la Escarcha tendrá un camino hasta el portal?' WHERE `ID`=25126;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그동안은 스카디스가 정보를 잘 전해 주었어요. 저희는 강제 노역소로 나아가면서 당신네 냉기술사들이 오기를 기다렸답니다.', `FemaleText_loc4`='卡希斯已经告诉我们了。我们已经进入了奴隶围栏，就等你们的冰术师了。', `FemaleText_loc5`='司卡利斯都告知我們了。我們已經用我們的方法進入奴隸監獄並靜候你的冰寒之力。', `FemaleText_loc7`='Skar''this nos ha informado bien. Nos hemos abierto paso hasta el Recinto de los Esclavos y estamos esperando a tus criománticos.' WHERE `ID`=25127;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='일단 아훈이 완전히 준비되면 갈퀴송곳니 저수지에서 의식을 벌여 구해낼 거예요. 그러면 불의 군주와 서리 군주 사이에 충돌이 일어나 이 세계를 뿌리째 갈라놓겠지요. 저희의 궁극적인 목표가 마침내 눈앞에 있어요...', `FemaleText_loc4`='盘牙水库的仪式将在埃霍恩完全准备好的时候唤醒它，炎魔之王和冰霜之王的冲突将会对这个世界的根基造成伤害。我们的最终目的终于就要实现了……', `FemaleText_loc5`='一旦艾胡恩完全做好準備，位於盤牙的儀式將會引領他直接到達，而其於炎魔及冰霜之王間所造成的衝突將會使這個世界的基礎破裂。我們的最終目標即將達成了...', `FemaleText_loc7`='El ritual en Colmillo Torcido traerá a Ahune cuando esté totalmente preparado y la lucha resultante entre el Señor del Fuego y el Señor de la Escarcha desgarrará los cimientos de este mundo. Al fin nuestros objetivos principales están al alcance...' WHERE `ID`=25128;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='깃발 운반자가 약해져서 쉽게 공격할 수 있습니다!', `MaleText_loc4`='旗手变得脆弱了！', `MaleText_loc5`='旗幟持有者變得有機可趁了!', `MaleText_loc7`='¡Los portadores de las banderas se han vuelto vulnerables a los ataques!' WHERE `ID`=25129;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='깃발 운반자가 점점 약해져서 더욱 쉽게 공격할 수 있습니다!', `MaleText_loc4`='旗手变得更加脆弱了！', `MaleText_loc5`='旗幟持有者變得愈來愈有機可趁!', `MaleText_loc7`='¡Los portadores de las banderas se han vuelto más vulnerables a los ataques!' WHERE `ID`=25130;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네싱워리가 노스렌드의 야생동물을 마구 사냥하는 것을 일단 멈추긴 했지만, 곧 뭔가 다른 방법으로 같은 짓을 계속할 겁니다! 그대가 잘 감시해야 합니다, $n 님!$B$B무엇보다도 유혹에 빠지지 않게 조심하십시오... 그 악마는 그대를 홀리려고 할 테니. 만약 그런 일이 생기더라도 반드시 이겨내야 합니다!', `MaleText_loc4`='奈辛瓦里不会停止杀害诺森德的野生动物的，他迟早会再下毒手。你必须保持警惕，$n！$B$B无论如何，不要屈服于任何可能出现的诱惑……这家伙一定会企图迷惑你。坚持住！', `MaleText_loc5`='雖然奈辛瓦里在北裂境的狩獵進度被打斷，但是他要發動另外一波狩獵只是時間的問題。$n，你要保持警覺!$B$B更重要的，千萬不能動搖你的立場...惡魔會不斷誘惑你。如果不幸發生了，你一定要忍住!', `MaleText_loc7`='Aunque hemos detenido las incursiones de Nesingwary en la vida salvaje de Rasganorte, solo es cuestión de tiempo que lo vuelva a intentar. ¡Debes permanecer alerta, $n!$B$BPero lo más importante es que no cedas, te ofrezca lo que te ofrezca... El demonio intentará engañarte. Cuando eso ocurra, deberás resistir.' WHERE `ID`=25131;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='페직스, 그 작은 엔진 문제를 우리가 해결한 것 같소.', `MaleText_loc4`='菲兹克斯，我想我们已经搞定引擎的故障了。', `MaleText_loc5`='菲奇司，我想我們已經把你引擎小小的毛病解決了。', `MaleText_loc7`='Fezzix, creo que he solucionado el pequeño problema de tu motor.' WHERE `ID`=25132;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 달궈, 이 덩치만 큰 얼간이들아!', `MaleText_loc4`='保持高温，你这蠢货！', `MaleText_loc5`='保持它們的溫度你這個大笨瓜!', `MaleText_loc7`='¡Mantenlos calientes, tontorrón!' WHERE `ID`=25133;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가만히 있으면 무기가 저절로 만들어지나! 더 빨리!', `MaleText_loc4`='这些武器是不会自动锻造好的！再快一点！', `MaleText_loc5`='這些武器不會自己長出來!動作快!', `MaleText_loc7`='¡Esas armas no se van a construir solas! ¡Más deprisa!' WHERE `ID`=25134;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그걸 망치질이라고 하는 거냐? 이따위 풋내기를 어떻게 믿으란 말인가?', `MaleText_loc4`='你管这叫锻造？和我共事的怎么尽是些外行人？！', `MaleText_loc5`='這也敢叫做錘擊?我到底是跟什麼業餘人士一起工作?', `MaleText_loc7`='¿Eso es lo que tú llamas un martillazo? ¿Con qué clase de principiantes estoy trabajando?' WHERE `ID`=25135;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 그런 식으로 하면 상자에 처넣고 ''불량품''이라고 써 붙여서 집으로 보내버리겠다!', `MaleText_loc4`='你就抱着那堆垃圾吧。我要在你胸前贴上“失败者”的标签，然后将你塞进箱子里寄给你的母亲。', `MaleText_loc5`='你只要敢繼續這樣亂搞，我保證把你打包寄回去你老媽，然後胸口寫著:看你生下的廢物。', `MaleText_loc7`='Sigue haciendo el patán y te enviaré de vuelta con tu mamá en una caja y con una nota pegada al pecho que diga: FRACASO.' WHERE `ID`=25136;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런 조잡한 쓰레기 따위로 우리 병사들더러 뭘 하라는 거냐?', `MaleText_loc4`='这种劣质货对我们的士兵有用吗？', `MaleText_loc5`='還有，我們的士兵「到底」和那些粗製濫造的廢物有何干係?', `MaleText_loc7`='¿Y QUÉ se supone que tienen que hacer nuestros soldados con ese trozo de basura?' WHERE `ID`=25137;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 작업에 거치적거리기만 하는군! 짐 싸서 나가!', `MaleText_loc4`='你这个只会捅娄子的蠢货！带上你的行李给我滚！', `MaleText_loc5`='你是這次行動中的恥辱!你給我捲鋪蓋走路!', `MaleText_loc7`='¡Eres una vergüenza para esta operación! ¡Recoge tus cosas y márchate!' WHERE `ID`=25138;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새 부품이 있으니 이제 드디어 이 고철을 비행기로 바꿔놓을 수 있겠군!', `MaleText_loc4`='有了这些新零件，我总算可以将这堆东西组装成飞行器了！', `MaleText_loc5`='有了這些零件，我終於可以將這一大塊垃圾變成一台飛行器了!', `MaleText_loc7`='¡Con estas piezas nuevas, por fin podré convertir esta chatarra en una máquina voladora!' WHERE `ID`=25139;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 엔진이 작동하지 않는 거지? 전원공급장치에 뭔가 문제라도 있나?', `MaleText_loc4`='这引擎怎么不动？莫非是电池出了问题？', `MaleText_loc5`='為什麼這個引擎就是不會動?我們恢復的能量電池到底有什麼問題?', `MaleText_loc7`='¿Por qué no funciona este motor? ¿Qué falla en las células de energía que hemos conseguido?' WHERE `ID`=25140;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 처음으로 돌아갔군. 이 망할 놈을 공중에 띄우려면 대체 어떻게 해야 하는 거야?', `MaleText_loc4`='恐怕要从头来过了。到底要怎么样这玩意儿才能飞起来？', `MaleText_loc5`='我猜，只能回到原點了。要怎樣才能讓這東西離開地面呢?', `MaleText_loc7`='De vuelta al principio, supongo. ¿Qué es lo que hace falta para levantar esta cosa del suelo?' WHERE `ID`=25141;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 말도 안 되는 기술을 철석같이 믿다가 낭패를 볼 줄 알았소, 페직스. 마침 내게 다른 방법이 있소이다.', `MaleText_loc4`='菲兹克斯，我告诉过你很多次了，别太相信这架飞行器的稳定性，它迟早会把你搞得半死的。幸好我们还有别的替代物。', `MaleText_loc5`='菲奇司，我嘗試過告訴你那個你全心全意信賴的機械怪東西會讓你失敗。幸運的是，我想我知道什麼可以替代它。', `MaleText_loc7`='Feezix, he intentado explicarte que todos esos rituales técnicos en los que tienes tanta fe fracasarían. Por suerte, creo que conozco una alternativa.' WHERE `ID`=25142;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번엔 분명히 작동할 거야... 그렇지?', `MaleText_loc4`='这次总行了吧……对吧？', `MaleText_loc5`='這次真的可以成功了...吧?', `MaleText_loc7`='Esta vez va a funcionar en serio... ¿verdad?' WHERE `ID`=25143;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='먹어라, 우리 늑대야... 힘을 비축해 둬라.', `MaleText_loc4`='吃吧，我的兄弟……你需要恢复力量。', `MaleText_loc5`='吃一點，狼兄弟...恢復你的力量吧。', `MaleText_loc7`='Come, hermano lobo… Recupera tus fuerzas.' WHERE `ID`=25144;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내일 우린 싸우게 될 거다, 형제여. 오늘은 배를 채워둬야 해.', `MaleText_loc4`='明天我们就要投身战斗了。今天我们一定要吃得饱饱的。', `MaleText_loc5`='兄弟，明日，我們奮戰，今日，我們大吃大喝。', `MaleText_loc7`='Mañana luchamos, hermano. Hoy nos alimentamos.' WHERE `ID`=25145;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 자랑스럽구나, 내 늑대 형제여.', `MaleText_loc4`='兄弟，我为你自豪。', `MaleText_loc5`='狼兄弟，你讓我很驕傲。', `MaleText_loc7`='Estoy orgulloso de ti, hermano lobo.' WHERE `ID`=25146;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='먹어라, 형제여. 마음껏 먹어둬. 내일은 어찌 될지 모르니...', `MaleText_loc4`='兄弟，吃吧。好好吃一顿，我们可能再也见不到明天了……', `MaleText_loc5`='吃吧，兄弟。多吃點，這是你的最後一餐了...', `MaleText_loc7`='Come ahora, hermano. Sáciate, pues no sabemos qué puede ocurrir mañana...' WHERE `ID`=25147;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='작동하는군요, 도레인! 진짜로 작동한다고요!', `MaleText_loc4`='成功了，多莱安！你看！它动起来了……', `MaleText_loc5`='杜然，成功啦!你看!它真的成功啦...', `MaleText_loc7`='¡Funciona, Dorain! ¡Mira! Funciona de verdad…' WHERE `ID`=25148;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 날 지배할 수 없다, 하찮은 $r|1이여;여;!', `MaleText_loc4`='别想控制我，小$r！', `MaleText_loc5`='你不要想主宰我，渺小的$r!', `MaleText_loc7`='¡No podrás conmigo, endeble $r!' WHERE `ID`=25149;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='간다아아아아아!!!!!!', `MaleText_loc4`='我要飞啦！', `MaleText_loc5`='我上囉!', `MaleText_loc7`='¡Allá vooooooooooooyyyyyyyyy!' WHERE `ID`=25150;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으악!', `MaleText_loc4`='好痛！', `MaleText_loc5`='好痛!', `MaleText_loc7`='¡AAY!' WHERE `ID`=25151;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='집어치워! 고블린 발명품은 이제 지긋지긋해!', `MaleText_loc4`='我放弃了！我受够地精的这些小玩意了！', `MaleText_loc5`='我投降!哥布林的精密工藝會壞掉啦!', `MaleText_loc7`='¡Me rindo! ¡Demasiada ingenuidad goblin!' WHERE `ID`=25152;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서리 군주가 승리를 거두었습니다.', `MaleText_loc4`='冰霜之王赢了。', `MaleText_loc5`='冰霜領主獲勝了。', `MaleText_loc7`='¡El Señor de la Escarcha ha vencido!' WHERE `ID`=25153;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 왜 모인 거야?', `MaleText_loc4`='我们要讨论什么呢？', `MaleText_loc5`='這場會議的目的是什麼?', `MaleText_loc7`='¿De qué va esta reunión?', `FemaleText_loc1`='우리 왜 모인 거죠?', `FemaleText_loc4`='我们要讨论什么呢？', `FemaleText_loc5`='這場會議的目的是什麼?', `FemaleText_loc7`='¿De qué va esta reunión?' WHERE `ID`=25154;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 도구들은 쓰레기야!', `MaleText_loc4`='这些工具全是废物！', `MaleText_loc5`='這些工具根本是垃圾!', `MaleText_loc7`='¡Estas herramientas son basura!', `FemaleText_loc1`='이 도구들은 쓰레기야!', `FemaleText_loc4`='这些工具全是废物！', `FemaleText_loc5`='這些工具根本是垃圾!', `FemaleText_loc7`='¡Estas herramientas son basura!' WHERE `ID`=25155;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 걸로 어떻게 물건을 만들라는 거야!', `MaleText_loc4`='你还指望我们能靠这些东西造出什么来？！', `MaleText_loc5`='他們怎麼可以期待我們用這些東西刻出什麼呢!', `MaleText_loc7`='¿Cómo quieren que trabajemos con estas cosas?', `FemaleText_loc1`='이런 걸로 어떻게 물건을 만들라고 하는 건지 원!', `FemaleText_loc4`='你还指望我们能靠这些东西造出什么来？！', `FemaleText_loc5`='他們怎麼可以期待我們用這些東西刻出什麼呢!', `FemaleText_loc7`='¿Cómo quieren que trabajemos con estas cosas?' WHERE `ID`=25156;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다 모였나?', `MaleText_loc4`='他们都在这儿吗？', `MaleText_loc5`='他們全都在那嗎?', `MaleText_loc7`='¿Ya están todos?' WHERE `ID`=25157;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 명 빼고 다 모였소.', `MaleText_loc4`='除了一个，其他都在。', `MaleText_loc5`='全部都在，除了一個之外。', `MaleText_loc7`='Todos menos uno.' WHERE `ID`=25158;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 정도면 괜찮아.', `MaleText_loc4`='那就行了。', `MaleText_loc5`='那對我來說已經夠了。', `MaleText_loc7`='Da igual. Yo empiezo.' WHERE `ID`=25159;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠시 주목 좀 해 줘!', `MaleText_loc4`='能专心听我说两句吗！', `MaleText_loc5`='你們可以暫時聽我說一下話嗎!', `MaleText_loc7`='Os pido un momento de atención.' WHERE `ID`=25160;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 얘기를 하느라 이렇게 떠드는 거야? 만능 스패너? 강화 아다만타이트를 어떻게 녹이는지도 몰라 끙끙대는 거야? 아니면 사기 치고 도망간 노움 때문에 징징대는 거야?', `MaleText_loc4`='你喋喋不休地在讲什么呢？你在谈论扳手，在抱怨硬化精金锭的熔炼标准，还在因为被别的侏儒敲诈了一笔而哭泣……', `MaleText_loc5`='因為你們在談論什麼?談論著有關扳手的事，嘀咕著有關熔煉特堅鋼的工作，鬼叫著某個地精剝削了你們...', `MaleText_loc7`='Porque… ¿de qué habláis? ¿Sobre llaves de tuerca arcoluz, os quejáis por los requisitos necesarios para fundir adamantita endurecida, lloráis porque algún gnomo os ha timado...?' WHERE `ID`=25161;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진짜로 중요한 얘기 한번 해 보자고.', `MaleText_loc4`='让我们来谈谈要紧的事吧。', `MaleText_loc5`='讓我們來談談重要的事吧。', `MaleText_loc7`='Vamos a hablar de algo muy importante.' WHERE `ID`=25162;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 아침 이슬 내려놔! 그건 장인이나 마시는 거야.', `MaleText_loc4`='把晨露酒放下！晨露酒是给技师喝的。', `MaleText_loc5`='放下那瓶晨露酒!晨露酒只提供給工匠使用。', `MaleText_loc7`='¡Y tú DEJA ese rocío de gloria matinal donde estaba! ¡Es solo para los artesanos!' WHERE `ID`=25163;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 지금 장난치는 것 같아? 난 장난치는 게 아니야. 오그리마에서 여기까지 왔다고. 노그의 작업소에서 당신들에게 자비를 베풀러 온 거야.', `MaleText_loc4`='你以为我是来找麻烦的？拜托，我才没那么闲。我从奥格瑞玛的诺格机械店出发，走了好远的路才到这里。我是来帮忙的哦。', `MaleText_loc5`='你以為我是來跟你們胡鬧的嗎?我不是在跟你們亂。我來自奧格瑪。我是從諾格機械店來這的，我來這是為了執行一項仁慈的任務。', `MaleText_loc7`='¿Crees que estoy bromeando? Pues no estoy bromeando. He venido de Orgrimmar. Vengo del taller de Nogg. Y he venido por misericordia.' WHERE `ID`=25164;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 레브니야?', `MaleText_loc4`='你叫利维尼？', `MaleText_loc5`='你叫雷凡尼?', `MaleText_loc7`='¿Tú eres Leveny?' WHERE `ID`=25165;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맞아.', `MaleText_loc4`='对。', `MaleText_loc5`='沒錯。', `MaleText_loc7`='Sí.' WHERE `ID`=25166;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러고도 네가 장인이야, 이 노움 같은 놈아?', `MaleText_loc4`='你还敢自称是技师，你这侏儒杂种？', `MaleText_loc5`='你自稱是一位工匠是嗎，你這個地精之子?', `MaleText_loc7`='¿Y tú te consideras artesano, hijo de gnomo?' WHERE `ID`=25167;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 왜 당신한테 그런 소리를 들어야 하나, 형씨!', `MaleText_loc4`='我没有义务来听你胡扯，先生！', `MaleText_loc5`='我不需要聽你廢話，先生!', `MaleText_loc7`='¡No pienso escuchar esta chorrada!', `FemaleText_loc1`='이봐요, 제가 왜 당신한테 그런 소리를 들어야 하나요!', `FemaleText_loc4`='我没有义务来听你胡扯，先生！', `FemaleText_loc5`='我不需要聽你廢話，先生!', `FemaleText_loc7`='¡No tengo por qué escuchar sus tonterías, señor!' WHERE `ID`=25168;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론 그런 말 들을 필요는 없어, 친구. 왜냐하면, 좋은 소식이 있는데 그게 뭐냐면 바로 당신들이 해고됐다는 거니까! 그리고 나쁜 소식은 당신들, 그러니까 당신네 모두에게 오늘 밤부터 딱 1주일 동안 복직할 기회를 준다는 거지. 오늘 밤부터 작업해서 말이야.', `MaleText_loc4`='你们当然不是好伙伴啦，因为你们都被解雇了！这算是个好消息吧。那么，坏消息是，我会给你们一周的时间，根据表现决定是否让你们复职。就从今天晚上开始吧。', `MaleText_loc5`='你的確是不用，夥伴，因為好消息是「你被解雇了」!壞消息是你剩下 - 你只剩下 - 一個星期的時間返回你的工作崗位，從今晚開始算起。開始今晚的工作吧。', `MaleText_loc7`='¡Claro que no, amigo, porque la buena noticia es que ESTÁS DESPEDIDO! Y la mala noticia es que todos, todos ustedes tienen una sola semana para reconquistar sus puestos, empezando esta noche, empezando con la construcción de esta noche.' WHERE `ID`=25169;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 주목할 맘이 생겼나? 잘됐군. 이달에 열리는 기술자 선발 대회 때문에 할 얘기가 더 있거든.', `MaleText_loc4`='哦……现在可以专心听我说话了吗？很好，这个月的制造合同里又添加了新内容。', `MaleText_loc5`='喔...現在大家都聽到我了嗎?很好，因為我們為本月的雕刻競賽增加了些小東西。', `MaleText_loc7`='Oh, ¿ahora ya me prestáis atención? Bien... porque vamos a añadir algo al concurso de artesanía de este mes.' WHERE `ID`=25170;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다 알다시피 1등 상품은 터보 충전 비행기거든. 2등 상품이 뭔지 궁금한 사람 있어?', `MaleText_loc4`='如你们所知，头等奖是一架涡轮加速飞行器。有人想知道二等奖是什么吗？', `MaleText_loc5`='如你們所知，首獎是渦輪飛行器。有人想知道貳獎是什麼嗎?', `MaleText_loc7`='Como todos sabéis el primer premio es una máquina voladora turboalimentada. ¿Alguien quiere ver el segundo premio?' WHERE `ID`=25171;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='2등 상품은 신관 배선이야.', `MaleText_loc4`='二等奖是保险丝。', `MaleText_loc5`='貳獎就是一些保險絲。', `MaleText_loc7`='El segundo premio es un cableado de fusibles.' WHERE `ID`=25172;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='3등 상품은 ''해고''야! 감이 좀 오나?', `MaleText_loc4`='三等奖就是炒鱿鱼！听明白了吗？', `MaleText_loc5`='參獎就是「你被解雇了」!了解了嗎?', `MaleText_loc7`='¡El tercer premio es el DESPIDO! ¿Lo habéis comprendido?' WHERE `ID`=25173;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='웃음이 나와, 지금? 도구는 다 있잖아! 그게 다 스랄 님이 사 주신 거라고. 당장 도면을 꺼내 읽어봐! 만약 지급받은 도구로도 공성 무기를 못 만들 정도라면, 아무것도 못 만든다는 얘기야. 아무짝에도 쓸모없다는 소리지. 그럴 거면 다 때려치우고 첫 비행선을 타고 여기서 꺼져. 어차피 잘릴 테니까!', `MaleText_loc4`='笑什么？你们手里拿着工具！萨尔花大价钱买了这些工具。把图纸掏出来好好看一看！要是你们不能借助工具造出攻城器械来，你们就是一帮一无是处的蠢货。那样的话，你们就给我滚！坐上地精飞艇马上给我滚！', `MaleText_loc5`='現在你們笑了?你們手上都有工具!索爾花了好多錢採買那些工具。拿出你們的藍圖並好好閱讀內容!如果你們不能用手上的工具來建造攻城機具的話，你們什麼都做不成，你們什麼都不是，去撞牆吧夥伴，然後去外邊搭上首班的飛艇，因為你們玩完了!', `MaleText_loc7`='¿Se rien ahora? ¡Les han dado herramientas! Thrall las ha pagado caras. ¡Saca los planos y léelos! Si no son capaces de construir máquinas de asedio con esas herramientas es que no son capaces de construir nada y ¡son inútiles! ¡Tomen el primer zepelín que salga porque se van a quedar en la calle!' WHERE `ID`=25174;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도구가 너무 부실하다고!', `MaleText_loc4`='这些工具太差劲了！', `MaleText_loc5`='工具太爛了!', `MaleText_loc7`='¡Esas herramientas son malas!' WHERE `ID`=25175;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도구가 부실하다고? 당신이 부실하겠지! 난 이 바닥에서만 50년을 일했다고.', `MaleText_loc4`='工具差劲？是你们太差劲了！我干这行已经50年了！', `MaleText_loc5`='工具太爛?你才人太爛哩!我已經在這行幹了50年了。', `MaleText_loc7`='¿Que las herramientas son malas? Tú sí que eres malo. Llevo en este negocio cincuenta años.' WHERE `ID`=25176;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 당신 이름은 뭐야?', `MaleText_loc4`='你说你叫什么名字？', `MaleText_loc5`='喂，你叫什麼名字?', `MaleText_loc7`='¿Cómo te llamas?', `FemaleText_loc1`='이봐요, 당신 이름이 뭐예요?', `FemaleText_loc4`='你说你叫什么名字？', `FemaleText_loc5`='喂，你叫什麼名字?', `FemaleText_loc7`='¿Cómo te llamas?' WHERE `ID`=25177;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노움 애호가, 그게 내 이름이지! 왠지 알아, 친구? 당신네는 다 부서진 외발 자전거를 타고 여기에 왔고, 나는 5,000골드짜리 최고급 장갑 와이번을 타고 여기 날아왔기 때문이지. 그러니 노움 애호가가 내 이름이야!', `MaleText_loc4`='我名叫侏儒情人！你知道这是怎么来的吗？你瞧，你就只能骑着小破独轮车，我胯下却是一只价值5000金币，全副武装的双足飞龙。哼哼，我就叫侏儒情人！', `MaleText_loc5`='地精情人，這就是我的名字!你知道為什麼嘛，兄弟?因為你騎著一台故障的單輪車進來這家店，而我則是乘著一隻價值5,000金，頂級的裝甲雙足翼龍到這的。「那」就是我的名字!', `MaleText_loc7`='¡Que le den por el gnomo! ¡Así me llamo! ¿Sabes por qué, amigo? Porque tú has llegado al taller en un monociclo asqueroso y yo en un dracoleón con armadura de 5000 oros. ¡ASÍ me llamo yo!' WHERE `ID`=25178;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언-제-나라는 거야. 언 - 언제나, 제 - 제품을, 나 - 나오게 한다. 언제나 제품을 나오게 한다. 언제나 제품을 만들어 내는 거라고!', `MaleText_loc4`='永远——在——制造。永远在制造。永远在制造！', `MaleText_loc5`='M-D-S。M-忙，D-到，S-死。忙到死。忙到死!', `MaleText_loc7`='S-E-C. S-siempre, E-estar, C-construyendo. Siempre estar construyendo. ¡Siempre estar construyendo!' WHERE `ID`=25179;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='string ID로 기술을 시전합니다...', `MaleText_loc4`='Cast with string ID on Action...', `MaleText_loc5`='動作時與字串ID一同施展...', `MaleText_loc7`='Lanzar con string ID en acción...' WHERE `ID`=25180;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='string ID로 주문을 시전합니다...', `MaleText_loc4`='Cast with string ID in spell...', `MaleText_loc5`='法術中與字串ID一同施展...', `MaleText_loc7`='Lanzar con string ID en hechizo...' WHERE `ID`=25181;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇게 돈 많고 잘난 양반이 왜 여기까지 와서 패배자 나부랭이들한테 시간을 낭비하실까?', `MaleText_loc4`='像你这样能赚大钱的英雄，跑来这里做什么呀？干嘛在失败者身上浪费时间呢？', `MaleText_loc5`='你真是個英雄，你身上有那麼多的財物 - 你為什麼會到這裡來浪費時間在一幫廢物身上呢?', `MaleText_loc7`='Siendo tan famoso y rico, ¿qué haces aquí perdiendo el tiempo con cuatro desgraciados?', `FemaleText_loc1`='그렇게 돈 많고 잘난 양반이 왜 여기까지 와서 패배자 나부랭이들한테 시간을 낭비하시나요?', `FemaleText_loc4`='像你这样能赚大钱的英雄，跑来这里做什么呀？干嘛在失败者身上浪费时间呢？', `FemaleText_loc5`='你真是個英雄，你身上有那麼多的財物 - 你為什麼會到這裡來浪費時間在一幫廢物身上呢?', `FemaleText_loc7`='Eres un auténtico héroe, tienes tanto oro… ¿qué haces aquí perdiendo el tiempo con semejante panda de perdedores?' WHERE `ID`=25182;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 코도가 보여? 이 코도가 보이느냐고! 이 코도는 당신네 공구상자 같은 집보다 더 비싸다고. 알겠어, 친구들? 그게 바로 나야. 당신네는 하찮을 뿐이야.', `MaleText_loc4`='你看见这头科多兽了吗？你·看·见·这·头·科·多·兽·了·吗？！它比你那件工具“库房”值钱多了。你瞧，我是大人物。而你什么都不是。', `MaleText_loc5`='你看到這隻科多獸?你有看到這隻科多獸嗎?這隻科多獸的價值比你稱為房子的那個工具箱還貴。你瞧，夥伴，這就是我的身分。而你什麼都不是。', `MaleText_loc7`='¿Ves este kodo? ¿VES ESTE KODO? Este kodo vale más que esa caja de herramientas que llamas ‘casa’. Ya ves, colega, este soy yo. Y tú no eres nada.' WHERE `ID`=25183;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 보주를 사용하면 낙사나르로 가는 차원문이 열립니다.', `MaleText_loc4`='使用这颗宝珠将开启通往纳克萨纳尔的传送门。', `MaleText_loc5`='使用寶珠將會造出一座通往納克薩爾的傳送門。', `MaleText_loc7`='Utilizar este orbe creará un portal que lleva a Naxxanar.' WHERE `ID`=25184;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수정구를 사용합니다.', `MaleText_loc4`='使用宝珠。', `MaleText_loc5`='使用寶珠。', `MaleText_loc7`='Usa el orbe.', `FemaleText_loc1`='수정구를 사용합니다.', `FemaleText_loc4`='使用宝珠。', `FemaleText_loc5`='使用寶珠。', `FemaleText_loc7`='Usa el orbe.' WHERE `ID`=25185;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 새 도구야. 가젯잔표 초강력 도구지. 당신네한테는 그냥 돈뭉치요. 그리고 절대 손에 못 넣지. 왜냐하면, 이걸 당신들이 쓰면 돼지 목에 진주 목걸이나 마찬가지니까. 이건 장인들만 쓰는 도구라고, 장인들만!', `MaleText_loc4`='这批新工具是加基森赞助的。对你来说，它们像金子一般宝贵。不过你别想得到它们。这样的东西若是给你，相当于丢进垃圾箱啦。这是为技师准备的。只有技师才配得上它！', `MaleText_loc5`='這些是新工具。加基森的能量工具。對你來說，這些都是錢。不過你不能拿走它們。因為將這些東西交給你，就像把它們丟進廢物堆一樣。這些是給工匠使用的。僅限工匠!', `MaleText_loc7`='Estas son las herramientas nuevas. Son herramientas de poder de Gadgetzan. Y para ustedes son de oro. Y no se las vamos a dar. ¿Por qué? Porque dárselas a ustedes es como tirarlas a la basura. Son para artesanos de verdad.' WHERE `ID`=25186;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드 공성 무기를 만들려면 청동 볼 베어링이 필요하지. 그럼 작업을 시작하든가 일을 때려치우든가 하라고!', `MaleText_loc4`='制造攻城器械需要铜球轴承。动作快点，不然就给我滚蛋！', `MaleText_loc5`='要替部落打造一台攻城機具，必須得用上銅球軸承。要是不能適應這個計畫就給我去敲磚頭!', `MaleText_loc7`='Hay que tenerlas bien puestas para construir maquinaria de asedio para la Horda. ¡Continuad con el programa o largaros!' WHERE `ID`=25187;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 보주를 사용하면 낙사나르 상층으로 가는 차원문이 열립니다.', `MaleText_loc4`='使用这颗宝珠将开启通往纳克萨纳尔上层的传送门。', `MaleText_loc5`='這顆寶珠可以生出一扇通往納克薩爾上層的傳送門。', `MaleText_loc7`='Este orbe creará un portal a Naxxanar superior.' WHERE `ID`=25188;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 보주를 사용하면 엔킬라 사원으로 가는 차원문이 열립니다.', `MaleText_loc4`='使用这颗宝珠将开启返回圣城恩其拉的传送门。', `MaleText_loc5`='這顆寶珠可以生出一扇讓你返回恩吉拉聖城的傳送門。', `MaleText_loc7`='Este orbe creará un portal que te llevará de vuelta a la Ciudad Templo de En''kilah.' WHERE `ID`=25189;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안비나, 깨어나 줘! 네 도움이 필요해!', `MaleText_loc4`='安薇娜，你必须觉醒过来！这个世界需要你！', `MaleText_loc5`='安薇娜，你必須覺醒過來!這個世界需要你!', `MaleText_loc7`='¡Anveena, debes despertar! ¡Este mundo te necesita!' WHERE `ID`=25190;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이겨내야만 돼! 진정한 너 자신이 돼야만 해! 바로 지금이라고, 안비나!', `MaleText_loc4`='你必须清醒过来！变回过去的你，变回你原来的样子！就是现在，安薇娜！', `MaleText_loc5`='你必須清醒過來!你必須變回原本的你!就是現在，安薇娜!', `MaleText_loc7`='¡Déjate llevar! ¡Tienes que convertirte en lo que el destino ha decidido que debes ser! ¡Es el momento Anveena!' WHERE `ID`=25191;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사랑해, 안비나! 내 목소리를 들어줘! 날 위해서라도 제발 돌아와! 오직 너만이 태양샘을 정화할 수 있어!', `MaleText_loc4`='安薇娜，我爱你！仔细聆听我的声音！回到我的身边来！只有你才能净化太阳之井！', `MaleText_loc5`='安薇娜，我愛你!仔細聆聽我的聲音!回到我身邊來!只有你才能淨化太陽之井!', `MaleText_loc7`='¡Anveena, te quiero! ¡Concéntrate en mi voz! ¡Hazlo por mí! ¡Solo tú puedes purificar La Fuente del Sol!' WHERE `ID`=25192;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 나야 안비나! 이제 운명에 몸을 맡겨!', `MaleText_loc4`='对，安薇娜！投入命运的怀抱吧！', `MaleText_loc5`='對，安薇娜!投入命運的懷抱吧!', `MaleText_loc7`='¡Sí, Anveena! ¡Entrégate a los brazos del destino!' WHERE `ID`=25193;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕, 내 사랑 안비나... 그대 이름을 기억하는 이는 적겠지만, 세상을 구한 건 바로 그대야. 이제 타락은 걷혔어, 안비나... 영웅들이여, 그녀의 희생이 헛되지 않게 해 주오.', `MaleText_loc4`='永别了，我挚爱的安薇娜。尽管只有我们少数人会记住你，但是你今天的英勇事迹改变了命运的轨迹。曾被玷污的太阳之井又重归纯净。英雄们，千万不要让安薇娜白白地牺牲。', `MaleText_loc5`='永別了，我摯愛的安薇娜。儘管你改變了命運的軌跡，但仍只有我們少數會記住你。曾被玷污的現在又回歸純淨。英雄們，千萬不要讓她白白地犧牲。', `MaleText_loc7`='Adiós, Anveena, amor mío. Pocos recordarán tu nombre, pero hoy has cambiado el destino. Lo que antes estaba corrupto, ahora está purificado. Héroes, no dejéis que su sacrificio sea en vano.' WHERE `ID`=25194;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='난 이제 주인님만을 섬겨요.', `FemaleText_loc4`='我现在只效忠于主人。', `FemaleText_loc5`='我現在只效忠於主人。', `FemaleText_loc7`='Ahora solo sirvo al maestro.' WHERE `ID`=25195;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하지만 난... 잊어버렸어요. 어떻게 돌아가야 하는지 모르겠어요.', `FemaleText_loc4`='但我似乎迷失了……，我找不到回去的路。', `FemaleText_loc5`='但我似乎迷失了...我找不到回去的路。', `FemaleText_loc7`='Pero estoy… perdida. No encuentro el camino de vuelta.' WHERE `ID`=25196;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='칼렉... 당신이에요?', `FemaleText_loc4`='卡雷……卡雷？', `FemaleText_loc5`='卡雷克...卡雷克?', `FemaleText_loc7`='Kalec... ¿Kalec?' WHERE `ID`=25197;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='악몽이 끝났어요! 마법이 풀렸어! 안녕, 칼렉... 사랑해요...', `FemaleText_loc4`='噩梦结束了！法术被破除了！再见，亲爱的卡雷！', `FemaleText_loc5`='惡夢結束了!法術被破解了!再見，卡雷克，我的愛!', `FemaleText_loc7`='¡La pesadilla ha terminado! ¡El hechizo se ha roto! ¡Adiós Kalec, amor mío!' WHERE `ID`=25198;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으아! 태양샘의 마력이... 나를... 거부한다! 무슨 짓을 한 거지? 무슨 짓을 한 거냐???', `MaleText_loc4`='啊啊啊！太阳之井的能量……开始……对抗我！你们都做了些什么？你们都做了些什么？？', `MaleText_loc5`='啊呃!太陽之井的能量...開始...對抗我!你們都做了些什麼?你們都做了些什麼??', `MaleText_loc7`='¡Aggghh! ¡Los poderes de La Fuente del Sol... se vuelven... contra mí! ¿Qué han hecho? ¿¿¿Qué han hecho???' WHERE `ID`=25199;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에너지 절약 상태에 들어갑니다.', `MaleText_loc4`='单位进入节能模式。', `MaleText_loc5`='隊伍進入能量保護模式。', `MaleText_loc7`='Unidad iniciando modo de ahorro de energía.' WHERE `ID`=25200;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='접근 중인 위협이 감지되었습니다. 에너지 절약 상태를 해제합니다.', `MaleText_loc4`='检测到威胁。解除节能模式。', `MaleText_loc5`='偵測到本地周邊威脅。退出能量保護模式。', `MaleText_loc7`='Detectada amenaza cercana. Abandonando modo de ahorro de energía.' WHERE `ID`=25201;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적이다! 파수병을 작동시키는 동안 저들을 막아라!', `MaleText_loc4`='发现敌人！你们上去顶住！我去启动魔像！', `MaleText_loc5`='發現敵人!在我試著啟動防護罩的同時展開攻擊!', `MaleText_loc7`='¡Enemigos avistados! ¡Ataquen mientras intento activar un protector!', `FemaleText_loc1`='적이다! 파수병을 작동시키는 동안 저들을 막아라!', `FemaleText_loc4`='发现敌人！你们上去顶住！我去启动魔像！', `FemaleText_loc5`='發現敵人!在我試著啟動防護罩的同時展開攻擊!', `FemaleText_loc7`='¡Enemigos avistados! ¡Ataquen mientras intento activar un protector!' WHERE `ID`=25202;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적의 출현이 감지되었습니다.', `MaleText_loc4`='发现敌人。', `MaleText_loc5`='發現敵人蹤跡。', `MaleText_loc7`='Presencia enemiga detectada.' WHERE `ID`=25203;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n, 이제 저들의 영혼을 풀어주고, 뭐라 하는지 들어보세.', `FemaleText_loc4`='现在让我们释放他们的灵魂，听一听他们要说些什么吧。', `FemaleText_loc5`='那麼，$n，把他們的靈魂釋放出來，聆聽他們要說些什麼。', `FemaleText_loc7`='Ahora, $n, liberemos esas almas y escuchemos lo que tienen que contar.' WHERE `ID`=25204;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구해주셔서 고맙습니다. 저희는 우연히 톱니반장 메카조드의 조각을 발견해서 다시 조립해냈습니다.', `MaleText_loc4`='谢谢你救了我们。我们偶然发现了机甲专家麦卡佐德的零件，并把他重新组装了起来。', `MaleText_loc5`='感謝你拯救了我們。我們意外地找到了齒輪大師梅卡佐德的零件，還把它給修好了。', `MaleText_loc7`='Gracias por salvarnos. Por accidente, encontramos las piezas del maestro de palancas Mecazod y lo volvimos a montar.', `FemaleText_loc1`='구해주셔서 고마워요. 저희는 우연히 톱니반장 메카조드의 조각을 발견해서 다시 조립해냈지요.', `FemaleText_loc4`='谢谢你救了我们。我们偶然发现了机甲专家麦卡佐德的零件，并把他重新组装了起来。', `FemaleText_loc5`='感謝你拯救了我們。我們意外地找到了齒輪大師梅卡佐德的零件，還把它給修好了。', `FemaleText_loc7`='Gracias por salvarnos. Por accidente, encontramos las piezas del maestro de palancas Mecazod y lo volvimos a montar.' WHERE `ID`=25205;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='작동 개시. 목표를 공격합니다.', `MaleText_loc4`='系统已启动，开始攻击目标。', `MaleText_loc5`='隊伍現在為作戰及攻擊目標。', `MaleText_loc7`='La unidad está ahora operativa y atacando objetivos.' WHERE `ID`=25206;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 보답으로 그는 소위 ''저주''를 풀어줬어요. 우리를 ''고쳐''서 기계 상태로 되돌린다면서 말이에요.', `MaleText_loc4`='作为感谢，他要为我们“驱除诅咒”，将我们“变回”机械体。', `MaleText_loc5`='他用「解詛咒」我們作為回報。他說，他把我們「修」好了，所以我們才能回到這副機器人模樣。', `MaleText_loc7`='A cambio, nos quitó la maldición diciendo que nos estaba curando al devolvernos a nuestro estado de ensamblajes mecánicos.', `FemaleText_loc1`='그 보답으로 그는 소위 ''저주''를 풀어줬어요. 우리를 ''고쳐''서 기계 상태로 되돌린다면서 말이에요.', `FemaleText_loc4`='作为感谢，他要为我们“驱除诅咒”，将我们“变回”机械体。', `FemaleText_loc5`='他用「解詛咒」我們作為回報。他說，他把我們「修」好了，所以我們才能回到這副機器人模樣。', `FemaleText_loc7`='A cambio, nos quitó la maldición diciendo que nos estaba curando al devolvernos a nuestro estado de ensamblajes mecánicos.' WHERE `ID`=25207;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그는 티탄의 모든 창조물이 ''육체의 저주''에 걸린 거라고 주장하더군요. 태초의 노움은 기계노움이라나요.', `MaleText_loc4`='他声称泰坦的创造物都中了什么“血肉的诅咒”。他还说侏儒原本都是机械侏儒。', `MaleText_loc5`='他宣稱所有泰坦的造物都成了他口中「血肉詛咒」的犧牲品。他還說地精的起源是來自於機械地精。', `MaleText_loc7`='Afirma que todas las creaciones de los titanes son víctimas de lo que él llama "la maldición de la carne". Dice que los primeros gnomos fueron una vez mecagnomos.', `FemaleText_loc1`='그는 티탄의 모든 창조물이 ''육체의 저주''에 걸린 거라고 주장하더군요. 태초의 노움은 기계노움이라나요.', `FemaleText_loc4`='他声称泰坦的创造物都中了什么“血肉的诅咒”。他还说侏儒原本都是机械侏儒。', `FemaleText_loc5`='他宣稱所有泰坦的造物都成了他口中「血肉詛咒」的犧牲品。他還說地精的起源是來自於機械地精。', `FemaleText_loc7`='Afirma que todas las creaciones de los titanes son víctimas de lo que él llama "la maldición de la carne". Dice que los primeros gnomos fueron una vez mecagnomos.' WHERE `ID`=25208;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그놈은 완전히 정신이 나갔습니다! 너무 늦기 전에 누군가 나서서 놈을 막아야 합니다!', `MaleText_loc4`='他疯了！必须阻止他，否则就迟了！', `MaleText_loc5`='他真的發瘋了!誰來阻止他，否則大家就完蛋了!', `MaleText_loc7`='¡Está fatal de lo suyo! ¡Alguien ha de poner fin a esa locura antes de que sea demasiado tarde para todos!', `FemaleText_loc1`='그놈은 완전히 정신이 나갔어요! 너무 늦기 전에 누군가 나서서 놈을 막아야 해요!', `FemaleText_loc4`='他疯了！必须阻止他，否则就迟了！', `FemaleText_loc5`='他真的發瘋了!誰來阻止他，否則大家就完蛋了!', `FemaleText_loc7`='¡Está fatal de lo suyo! ¡Alguien ha de poner fin a esa locura antes de que sea demasiado tarde para todos!' WHERE `ID`=25209;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='읽는 중', `MaleText_loc4`='监测数据', `MaleText_loc5`='開始讀數', `MaleText_loc7`='Tomando mediciones' WHERE `ID`=25210;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='참으로 끔찍한 소식이로군!', `FemaleText_loc4`='这消息太可怕了！', `FemaleText_loc5`='這些消息真驚悚!', `FemaleText_loc7`='¡Eso, sin duda, son noticias preocupantes!' WHERE `ID`=25211;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저 망할 스컬지에게 쫓겨난다면 우린 끝장이에요! 여기 정착민은 노스렌드에서 새롭게 출발하려고 모든 걸 바쳤단 말이에요!$B$B차라리 목숨 걸고 싸우는 쪽을 택하겠어요.', `FemaleText_loc4`='我绝不容许天灾军团将我们驱逐出这里！我们放弃了一切，准备在诺森德开始新的生活。$B$B我向你保证，我们会拼死抵抗的。', `FemaleText_loc5`='如果這些該死的天譴軍團要把我們趕走的話，我會被罵死!我們這些移民者放棄所有的東西來到北裂境開始新生活。$B$B你最好相信我們會努力奮戰到底。', `FemaleText_loc7`='¡Solo me faltaba que la maldita Plaga nos vaya a echar de aquí! Los colonos lo dimos todo para comenzar nuevas vidas en Rasganorte.$B$BSerá mejor que creas que vamos a luchar con uñas y dientes.' WHERE `ID`=25212;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 얼음 조각에서 빙하가 마구 몰려오며 부딪치는 장중한 소리가 울려 나옵니다. 또한, 그 한기 때문에 머릿속에는 생명도, 끝도 없는 겨울만이 떠오릅니다.', `MaleText_loc4`='这块冰晶碎片中竟传来了深远之处冰川碎裂的声响。它的冰冷将你的思维彻底抛入了毫无生气的无尽寒冻。', `MaleText_loc5`='這塊冰的裂片呼應著入侵的冰川深處，爆裂的聲響。它的冷冽使你的想法轉變為無生息，無止境的寒冬。', `MaleText_loc7`='En este fragmento de hielo retumba el eco del estruendo profundo y sonoro de los glaciares que se desplazan. El frío transforma tus pensamientos en un invierno eterno y sin vida.' WHERE `ID`=25213;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서리 군주 아훈을 소환합니다.', `MaleText_loc4`='召唤冰霜之王埃霍恩。', `MaleText_loc5`='召喚冰霜領主，艾胡恩。', `MaleText_loc7`='Invoca a Ahune, el Señor de la Escarcha.', `FemaleText_loc1`='서리 군주 아훈을 소환합니다.', `FemaleText_loc4`='召唤冰霜之王埃霍恩。', `FemaleText_loc5`='召喚冰霜領主，艾胡恩。', `FemaleText_loc7`='Invoca a Ahune, el Señor de la Escarcha.' WHERE `ID`=25214;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뒤에서 뭔가 소리가 들립니다!', `MaleText_loc4`='你身后有动静！', `MaleText_loc5`='你背後有動靜!', `MaleText_loc7`='¡Hay un ruido detrás de ti!' WHERE `ID`=25215;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑소, $n. 나는 이 늑대 무리를 보살피는 듀르코트 울프브라더라고 하오.', `MaleText_loc4`='欢迎你，$n。我是杜尔克特·狼兄，氏族的守护者。', `MaleText_loc5`='你好，$n。我是德寇特·狼伴，狼群的保護者。', `MaleText_loc7`='Saludos, $n. Soy Durkot Hermano Lobo, protector de la manada.' WHERE `ID`=25216;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌 그 자체와 놓인 받침대 주변으로 냉혹한 한기가 뿜어져 나옵니다. 돌의 단면 안쪽 깊숙이 푸른 빛이 조용히 고동칩니다.', `MaleText_loc4`='石头散发出一阵寒气，冻结住了周围的空气和放置石头的平台。在石头的深处，一道蓝色的光芒跳动着，等待着。', `MaleText_loc5`='石頭散發微微的寒意，使其周遭的空氣及放置的平台凝結成冰。在其多面的深處，一隻藍龍蟄伏於其中，等待著。', `MaleText_loc7`='La piedra irradia un frío amargo, helando el aire a su alrededor y la plataforma sobre la que se asienta. En su interior una luz azul parpadea, esperando.', `FemaleText_loc1`='돌 그 자체와 놓인 받침대 주변으로 냉혹한 한기가 뿜어져 나옵니다. 돌의 단면 안쪽 깊숙이 푸른 빛이 조용히 고동칩니다.', `FemaleText_loc4`='石头散发出一阵寒气，冻结住了周围的空气和放置石头的平台。在石头的深处，一道蓝色的光芒跳动着，等待着。', `FemaleText_loc5`='石頭散發微微的寒意，使其周遭的空氣及放置的平台凝結成冰。在其多面的深處，一隻藍龍蟄伏於其中，等待著。', `FemaleText_loc7`='La piedra irradia un frío amargo, helando el aire a su alrededor y la plataforma sobre la que se asienta. En su interior una luz azul parpadea, esperando.' WHERE `ID`=25217;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌 위에 손을 올려놓습니다.', `MaleText_loc4`='把你的手放在石头上。', `MaleText_loc5`='將你的手放在石頭上。', `MaleText_loc7`='Apoya tus manos en la piedra.', `FemaleText_loc1`='돌 위에 손을 올려놓습니다.', `FemaleText_loc4`='把你的手放在石头上。', `FemaleText_loc5`='將你的手放在石頭上。', `FemaleText_loc7`='Apoya tus manos en la piedra.' WHERE `ID`=25218;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사방에 스컬지입니다! 이건... 완전히 악몽이라고요!', `MaleText_loc4`='到处都是天灾军团！这真是……一场噩梦！', `MaleText_loc5`='到處都是天譴軍!惡夢...成真了!', `MaleText_loc7`='¡La Plaga está por todas partes! Esto es... una pesadilla.' WHERE `ID`=25219;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 운을 시험해 봐라!', `MaleText_loc4`='来呀，试试你们的运气吧！', `MaleText_loc5`='來吧，試試你們的運氣吧!', `MaleText_loc7`='¡Venid a probar suerte!' WHERE `ID`=25220;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='멈추세요, 영웅들이여! 이 악마를 처치하기 전에 알아내야 할 게 있습니다!', `FemaleText_loc4`='等等，朋友们！送这只恶魔下地狱之前，我还有些事要问它。', `FemaleText_loc5`='等等，朋友們!送這隻惡魔下地獄之前，我還有些事要問它!', `FemaleText_loc7`='¡Esperad, amigos! ¡Tenemos información que obtener antes de que este demonio se enfrente a su destino!' WHERE `ID`=25221;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불쌍한 도마뱀 같으니! 널 기다리는 건 죽음뿐이다!', `MaleText_loc4`='可笑的大蜥蜴！你只有死路一条！', `MaleText_loc5`='可笑的大蜥蜴!你到這來就只有死路一條了!', `MaleText_loc7`='¡Endebles lagartijas! ¡La muerte es la única respuesta que encontraréis aquí!' WHERE `ID`=25222;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 마법이 귀엽기도 하지!', `MaleText_loc4`='哈哈哈！你的魔法太脆弱太可笑了！', `MaleText_loc5`='哈哈!你的魔法太脆弱太可笑了!', `MaleText_loc7`='¡Bah! ¡Tu magia es débil!' WHERE `ID`=25223;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='박살 내 주마!', `MaleText_loc4`='我要把你碾碎！', `MaleText_loc5`='我把你碾碎!', `MaleText_loc7`='¡Los aplastaré!' WHERE `ID`=25224;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꽤 괜찮았다만, 이 정도론 아직 멀었다!', `MaleText_loc4`='有点意思，但我还在等待真正的挑战！', `MaleText_loc5`='真有趣，但我還在等待真正的挑戰!', `MaleText_loc7`='¡Ha sido divertido, pero sigo esperando un auténtico reto!' WHERE `ID`=25225;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='악마여, 안비나는 어디 있나? 칼렉은 어떻게 된 거지?', `FemaleText_loc4`='安薇娜在哪，恶魔？卡雷怎么了？', `FemaleText_loc5`='惡魔，安薇娜在哪裡?卡雷克發生了什麼事?', `FemaleText_loc7`='¿Dónde está Anveena, demonio? ¿Qué ha sido de Kalec?' WHERE `ID`=25226;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그들이 어디 있는지 말해라!', `FemaleText_loc4`='你必须说出他们的下落！', `FemaleText_loc5`='你必須說出他們的下落!', `FemaleText_loc7`='¡Me dirás dónde están!' WHERE `ID`=25227;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어서! 묻기도 지겹구나!', `FemaleText_loc4`='说！我可不耐烦了！', `FemaleText_loc5`='說!我可不耐煩了!', `FemaleText_loc7`='¡Habla! ¡Me estoy hartando de preguntar!' WHERE `ID`=25228;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='말리고스 님... 저는... 최선을 다했습니다.', `FemaleText_loc4`='玛里苟斯大人……我……尽力了……', `FemaleText_loc5`='瑪里苟斯，我的主人...我...盡力了。', `FemaleText_loc7`='Malygos, señor... hice.. lo que... pude.' WHERE `ID`=25229;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아서스는 언데드 벌레 몇 마리면 우릴 동부 왕국으로 돌려보낼 수 있다고 생각하나 본데... 그건 큰 착각이지.', `MaleText_loc4`='阿尔萨斯以为他手下的几名亡灵渣滓就能将我们赶回东部王国……他会尝到后果的。', `MaleText_loc5`='阿薩斯以為只要派遣少數的不死小蟲就可以將我們逃回東部王國...他有得忙了。', `MaleText_loc7`='Arthas cree que algunos de sus gusanos no-muertos van a hacer que volvamos corriendo a los Reinos del Este... está muy equivocado.' WHERE `ID`=25230;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 어둠의 세력이 이 땅에서 몰래 활개치고 있네. 눈을 크게 뜨고 용기를 잃지 말게.', `MaleText_loc4`='黑暗的力量正在这片土地上蔓延。$n，睁大眼睛，鼓起勇气吧。', `MaleText_loc5`='黑暗的勢力侵害這座島嶼，$n，睜大你的眼睛，鼓起你的勇氣。', `MaleText_loc7`='En esta tierra están actuando fuerzas ocultas, $n. Mantén los ojos abiertos y el valor firme.' WHERE `ID`=25231;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아가마스 관문이 무너졌다!', `FemaleText_loc4`='阿加麦斯之门被攻破了！', `FemaleText_loc5`='阿格瑪司之門已被破壞!', `FemaleText_loc7`='¡La puerta Agamath ha sido agrietada!' WHERE `ID`=25232;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='로헨도르 관문이 무서졌다! 앞으로 나아가라, 용사들이여!', `FemaleText_loc4`='洛希多尔之门被击碎了！勇士们，进攻！', `FemaleText_loc5`='洛罕鐸之門已被粉碎!勇士們，往前走!', `FemaleText_loc7`='¡La puerta Rohendor ha sido destrozada! ¡Adelante, campeones!' WHERE `ID`=25233;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아코니수스 관문은 무너졌다! 태양샘으로 가는 길이 열렸다!', `FemaleText_loc4`='埃库尼苏之门已经不复存在了！太阳之井就在眼前！', `FemaleText_loc5`='亞坎努斯之門消失了!前往太陽之井的道路清空了!', `FemaleText_loc7`='¡La puerta Archonisus ya no existe! ¡El camino hacia La Fuente del Sol está despejado!' WHERE `ID`=25234;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='항상 누군가는 병역 의무에서 면제되지요. 노련한 어부란 유용한 존재랍니다... 사령관도 먹어야 사는 법이니 말입니다.', `MaleText_loc4`='我们中的某些人打算逃避兵役。任何时候，好的渔夫总是有用的……将军也得吃饭啊。', `MaleText_loc5`='我們之中有些人會逃避兵役，好的漁夫總是很好用...即使是將軍，總也要吃東西吧。', `MaleText_loc7`='Algunos intentamos evitar las tareas militares. Un buen pescador siempre viene bien... incluso los generales necesitan comer.' WHERE `ID`=25235;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이쪽으로 오십시오.', `MaleText_loc4`='$g先生:女士;，这边走。', `MaleText_loc5`='請隨我來，$g先生:女士;。', `MaleText_loc7`='Por aquí, $g señor:señora;.' WHERE `ID`=25236;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저주받은 자들의 교단에 대해 무엇을 아십니까?', `MaleText_loc4`='你知道诅咒教派的情况吗？', `MaleText_loc5`='你對詛咒神教的認識有多少?', `MaleText_loc7`='¿Qué sabes acerca del Culto de los Malditos?', `FemaleText_loc1`='저주받은 자들의 교단에 대해 무엇을 아시나요?', `FemaleText_loc4`='你知道诅咒教派的情况吗？', `FemaleText_loc5`='你對詛咒神教的認識有多少?', `FemaleText_loc7`='¿Qué sabes acerca del Culto de los Malditos?' WHERE `ID`=25237;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 순종하는 듯한 울음소리를 냅니다.', `MaleText_loc4`='%s顺从地哀嚎起来。', `MaleText_loc5`='%s順服的嗥叫著。', `MaleText_loc7`='%s aúlla mostrando conformidad.' WHERE `ID`=25238;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 교단 활동에 연루되었다고 믿을 만한 증거가 있습니다.', `MaleText_loc4`='我有理由相信你参与了信徒的行动。', `MaleText_loc5`='我有理由相信你涉嫌教徒的活動。', `MaleText_loc7`='Tengo motivos para creer que estás involucrado en actividades cultoras.', `FemaleText_loc1`='당신이 교단 활동에 연루되었다고 믿을 만한 증거가 있습니다.', `FemaleText_loc4`='我有理由相信你参与了信徒的行动。', `FemaleText_loc5`='我有理由相信你涉嫌教徒的活動。', `FemaleText_loc7`='Tengo motivos para creer que estás involucrado en actividades cultoras' WHERE `ID`=25239;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날마다 부엌일이라니. 머지않아 내 실력이 다 녹슬겠군.', `MaleText_loc4`='每天都在厨房里做同样的事。要不了多久肯定会厌倦的。', `MaleText_loc5`='又是另外一個在廚房裡工作的日子，沒一會兒就覺得無聊了。', `MaleText_loc7`='Otro día más trabajando en la cocina. Después de un tiempo se vuelve un rollo.' WHERE `ID`=25240;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='교대할 때가 다 됐소. 졸려서 죽겠군. 무슨 말인지 알겠소?', `MaleText_loc4`='差不多到换班的时间了。我好想眯一会儿，你明白我的意思吧？', `MaleText_loc5`='我的輪值時間總算要到了，等不及要趕緊去瞇一下，你懂嗎?', `MaleText_loc7`='Mi turno casi ha terminado. No puedo esperar para plegar la oreja, ¿sabes a qué me refiero?' WHERE `ID`=25241;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저주받은 자들의 교단에서 얼마나 오래 활동했습니까?', `MaleText_loc4`='你为诅咒教派效劳多长时间了？', `MaleText_loc5`='你為詛咒神教賣命有多久了?', `MaleText_loc7`='¿Cuánto tiempo llevas trabajando para el Culto de los Malditos?', `FemaleText_loc1`='저주받은 자들의 교단에서 얼마나 오래 활동했나요?', `FemaleText_loc4`='你为诅咒教派效劳多长时间了？', `FemaleText_loc5`='你為詛咒神教賣命有多久了?', `FemaleText_loc7`='¿Cuánto tiempo llevas trabajando para el Culto de los Malditos?' WHERE `ID`=25242;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠...', `MaleText_loc4`='好吧……', `MaleText_loc5`='那麼...', `MaleText_loc7`='Bien...' WHERE `ID`=25243;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기까지인가 보군. 그렇다고 내가 곱게 죽어줄 거라고는 생각지 마라!', `MaleText_loc4`='好吧，然后呢？我不会坐以待毙的！', `MaleText_loc5`='我想已經沒有其他的解決方式了，是嗎?我可不會乖乖地束手就擒!', `MaleText_loc7`='Entonces, supongo que esto es todo. ¡No me hundiré en silencio!' WHERE `ID`=25244;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어! 이 바보 같은 장난도 끝났군... 아서스 님, 제게 힘을 주소서!', `MaleText_loc4`='总算不用遮遮掩掩了！阿尔萨斯，赐予我力量吧！', `MaleText_loc5`='總算!猜謎結束了...阿薩斯賜給我力量!', `MaleText_loc7`='¡Por fin! Se acabó esta farsa... ¡Arthas dame fuerza!' WHERE `ID`=25245;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누구한테 덤비는 건지 제대로 모르는 모양이구나, $c! 죽어라!', `MaleText_loc4`='$c，你还不知道自己招惹到什么人了吧！死神在朝你招手呢！', `MaleText_loc5`='$c，你不清楚惹到誰了!死神在向你招手!', `MaleText_loc7`='¡No sabes con quién te estás metiendo, $c! ¡La muerte te llama!' WHERE `ID`=25246;
