UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 얼마면 되겠어요? 여기 5천 골드면 되겠어요?', `MaleText_loc4`='没钱花了？来，给你5000枚金币。', `MaleText_loc5`='需要金錢嗎?這裡有5,000。', `MaleText_loc7`='¿Necesitas oro? Aquí tienes 5000 monedas.', `FemaleText_loc1`='그래, 얼마면 되겠어요? 여기 5천 골드면 되겠어요?', `FemaleText_loc4`='没钱花了？来，给你5000枚金币。', `FemaleText_loc5`='需要金錢嗎?這裡有5,000。', `FemaleText_loc7`='¿Necesitas oro? Aquí tienes 5000 monedas.' WHERE `ID`=25257;
