UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 소환수를 우리에 넣고 충성도를 최대로 올려 드리겠습니다.', `MaleText_loc4`='你可以在我这里寄放你的宠物，而且我可以帮你提高它们的忠诚度。', `MaleText_loc5`='我可以寄放你的寵物並將他們的忠誠度增加到最大。', `MaleText_loc7`='Puedo cobijar a tus mascotas y maximizar su lealtad.', `FemaleText_loc1`='제가 소환수를 우리에 넣고 충성도를 최대로 올려 드리지요.', `FemaleText_loc4`='你可以在我这里寄放你的宠物，而且我可以帮你提高它们的忠诚度。', `FemaleText_loc5`='我可以寄放你的寵物並將他們的忠誠度增加到最大。', `FemaleText_loc7`='Puedo cobijar a tus mascotas y maximizar su lealtad.' WHERE `ID`=25259;
