UPDATE `locales_broadcast_text` SET `MaleText_loc1`='운명은 마드리고사에게 너무 가혹했습니다. 해야 할 일을 하셨지만, 이 전투가 끝나려면 멀었습니다!', `MaleText_loc4`='虽然玛蒂苟萨的命运不该如此悲惨，你们的所作所为仍然是必须和必要的，不过，这场战争远未结束！', `MaleText_loc5`='瑪卓苟莎的命運不該如此悲慘。但你們只盡了自己的本分，而這場戰爭尚未結束!', `MaleText_loc7`='Madrigosa merecía un destino mejor. Hicisteis lo que teníais que hacer, pero esta batalla aún no ha acabado.' WHERE `ID`=25261;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 이용', `MaleText_loc4`='存放宠物', `MaleText_loc5`='獸欄', `MaleText_loc7`='Establo', `FemaleText_loc1`='우리 이용', `FemaleText_loc4`='存放宠物', `FemaleText_loc5`='獸欄', `FemaleText_loc7`='Establo' WHERE `ID`=25262;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크나큰 빚을 졌습니다. 킬제덴을 쓰러뜨린다면, 이 세계 역시 그대들에게 빚을 지는 겁니다.', `MaleText_loc4`='我欠你们一份情。当我们战胜基尔加丹时，整个世界都会感激你们的。', `MaleText_loc5`='我欠你們太多了。當我們一起戰勝了基爾加丹時，整個世界都會欠你們許多。', `MaleText_loc7`='Estaré en deuda con ustedes eternamente. Cuando hayamos triunfado sobre Kil’jaeden, este mundo también lo estará.' WHERE `ID`=25263;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아서스는 한 때 인간 왕자였어요. 그가 노스렌드로 끌고 온 군대는 끔찍한 운명을 맞이했지요.$B$B우리 오빠 타사리안도 그 군대의 일원이었어요.', `FemaleText_loc4`='阿尔萨斯曾是万民敬仰的人类王子。他所率领的诺森德远征军遭遇了可怕的命运。$B$B我的哥哥萨萨里安就是军中的一员。', `FemaleText_loc5`='阿薩斯曾經是人類的王子。他帶去北裂境的大軍下場非常慘澹。$B$B我的哥哥，薩沙理安，當時也在那支軍隊裡。', `FemaleText_loc7`='Hace tiempo Arthas fue un príncipe humano. El ejército que guió hasta Rasganorte sufrió un fatídico destino.$B$BMi hermano Thassarian era miembro de aquel ejército.' WHERE `ID`=25264;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='떠날 준비가 되었습니다, 듀르코트.', `MaleText_loc4`='我准备好动身啦，杜尔克特。', `MaleText_loc5`='德寇特，我準備好離開了。', `MaleText_loc7`='Estoy listo para partir,Durkot.', `FemaleText_loc1`='떠날 준비가 되었습니다, 듀르코트.', `FemaleText_loc4`='我准备好动身啦，杜尔克特。', `FemaleText_loc5`='德寇特，我準備好離開了。', `FemaleText_loc7`='Estoy lista para partir,Durkot.' WHERE `ID`=25265;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가장 빠른 늑대가 당신을 타운카르 마을까지 데려다 줄 거요. 용사여, 준비가 끝나면 알려주시오.', `MaleText_loc4`='勇士，我会让速度最快的座狼载你前往牦牛村。你准备好之后就告诉我吧。', `MaleText_loc5`='勇士，我族最快的狼騎已經就緒，送你去坦卡雷村了。準備好就告訴我吧。', `MaleText_loc7`='El más veloz de mis lobos te llevará hasta el Poblado Taunka''le. Avísame cuando estés en condiciones.' WHERE `ID`=25266;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생명을 걸고 호드를 지킨다!', `MaleText_loc4`='我愿意为部落献出生命！', `MaleText_loc5`='$g先生:女士;，我的性命屬於部落!', `MaleText_loc7`='¡$gSeñor:Señora;, mi vida por la Horda!', `FemaleText_loc1`='호드를 지킵니다, 생명을 걸고!', `FemaleText_loc4`='我愿意为部落献出生命！', `FemaleText_loc5`='$g先生:女士;，我的性命屬於部落!', `FemaleText_loc7`='¡$gSeñor:Señora;, mi vida por la Horda!' WHERE `ID`=25267;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오십시오, 용사님.', `MaleText_loc4`='欢迎回来，勇士。', `MaleText_loc5`='歡迎回來，勇士。', `MaleText_loc7`='$gBienvenido:Bienvenida; de vuelta, adalid.', `FemaleText_loc1`='어서 오세요, 용사님.', `FemaleText_loc4`='欢迎回来，勇士。', `FemaleText_loc5`='歡迎回來，勇士。', `FemaleText_loc7`='$gBienvenido:Bienvenida; de vuelta, adalid.' WHERE `ID`=25268;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신과 같은 편에서 싸울 수 있어 영광입니다.', `MaleText_loc4`='很荣幸能和你并肩战斗。', `MaleText_loc5`='能夠隨伺在你身邊是一種榮耀，$g先生:女士;。', `MaleText_loc7`='Es un honor servir junto a usted, $gseñor:señora;.', `FemaleText_loc1`='당신과 같은 편에서 싸울 수 있어 영광이에요.', `FemaleText_loc4`='很荣幸能和你并肩战斗。', `FemaleText_loc5`='能夠隨伺在你身邊是一種榮耀，$g先生:女士;。', `FemaleText_loc7`='Es un honor servir junto a usted, $gseñor:señora;.' WHERE `ID`=25269;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='록타르 오가르!', `MaleText_loc4`='Lok''tar ogar！', `MaleText_loc5`='(獸人語)不勝即亡!', `MaleText_loc7`='¡Lok''tar ogar!', `FemaleText_loc1`='록타르 오가르!', `FemaleText_loc4`='Lok''tar ogar！', `FemaleText_loc5`='(獸人語)不勝即亡!', `FemaleText_loc7`='¡Lok''tar ogar!' WHERE `ID`=25270;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='트롬카, 영웅이여!', `MaleText_loc4`='Throm-Ka，英雄！', `MaleText_loc5`='(獸人語)你好，英雄!', `MaleText_loc7`='¡Throm-Ka, héroe!', `FemaleText_loc1`='트롬카, 영웅이여!', `FemaleText_loc4`='Throm-Ka，英雄！', `FemaleText_loc5`='(獸人語)你好，英雄!', `FemaleText_loc7`='¡Throm-Ka, héroe!' WHERE `ID`=25271;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대의 힘과 결단력이 있는 한 우린 절대 쓰러지지 않소!', `MaleText_loc4`='有了你的力量和决心，我们一定能获胜！', `MaleText_loc5`='有了你的力量和決心，我們不可能失敗的!', `MaleText_loc7`='¡Con tu fuerza y determinación, no podemos fracasar!', `FemaleText_loc1`='그대의 힘과 결단력이 있는 한 우린 절대 쓰러지지 않아요!', `FemaleText_loc4`='有了你的力量和决心，我们一定能获胜！', `FemaleText_loc5`='有了你的力量和決心，我們不可能失敗的!', `FemaleText_loc7`='¡Con tu fuerza y determinación, no podemos fracasar!' WHERE `ID`=25272;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기 영웅이 가십니다!', `MaleText_loc4`='瞧！英雄！', `MaleText_loc5`='那裡有個英雄!', `MaleText_loc7`='¡Por allí camina un héroe!', `FemaleText_loc1`='저기 영웅이 가시는군요!', `FemaleText_loc4`='瞧！英雄！', `FemaleText_loc5`='那裡有個英雄!', `FemaleText_loc7`='¡Por allí camina un héroe!' WHERE `ID`=25273;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님이시다! 고개를 숙여라!', `MaleText_loc4`='瞧！$n！快鞠躬！', `MaleText_loc5`='是$n耶!快敬禮!', `MaleText_loc7`='¡Es $n! ¡Inclinaos!', `FemaleText_loc1`='$n 님이시네요! 고개를 숙이세요!', `FemaleText_loc4`='瞧！$n！快鞠躬！', `FemaleText_loc5`='是$n耶!快敬禮!', `FemaleText_loc7`='¡Es $n! ¡Inclinaos!' WHERE `ID`=25274;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 당신을 향해 환호합니다.', `MaleText_loc4`='%s向你欢呼。', `MaleText_loc5`='%s為你歡呼。', `MaleText_loc7`='%s te aclama.', `FemaleText_loc1`='%s|1이;가; 당신을 향해 환호합니다.', `FemaleText_loc4`='%s向你欢呼。', `FemaleText_loc5`='%s為你歡呼。', `FemaleText_loc7`='%s te aclama.' WHERE `ID`=25275;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 광부, 농부, 기술자이지 군인이 아니오. 하지만 필요하다면 우리는 맨주먹으로라도 우리 땅을 지킬 거요.', `MaleText_loc4`='是，我们不过是一群手无寸铁的矿工、农夫和工匠。可是情况危急时，我们也会赤手空拳地抗争到底，像士兵那样守卫我们的家园。', `MaleText_loc5`='我們是礦工，農夫和工匠 - 不是士兵。但是必要的時候，即使赤手空拳我們也會努力保衛我們的土地。', `MaleText_loc7`='Somos mineros, granjeros y artesanos, no soldados. Pero defenderemos nuestra tierra con los puños desnudos si es necesario.' WHERE `ID`=25276;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죄송합니다만, 저는 사냥꾼에게만 편의를 제공합니다.', `MaleText_loc4`='抱歉，但我只跟猎人打交道。', `MaleText_loc5`='抱歉，我的服務僅可供獵人使用。', `MaleText_loc7`='Lo siento, pero mis servicios solo son útiles para los cazadores.', `FemaleText_loc1`='죄송합니다만, 저는 사냥꾼에게만 편의를 제공하지요.', `FemaleText_loc4`='抱歉，但我只跟猎人打交道。', `FemaleText_loc5`='抱歉，我的服務僅可供獵人使用。', `FemaleText_loc7`='Lo siento, pero mis servicios solo son útiles para los cazadores.' WHERE `ID`=25277;
