UPDATE `locales_broadcast_text` SET `MaleText_loc1`='특성을 새로 구성할 수 있도록 모든 특성을 삭제해 드리겠습니다.$b$b특성 초기화 비용은 횟수를 거듭할수록 늘어납니다.', `MaleText_loc4`='我可以清除你所有的天赋，这样你就可以重新选择了。$B$B不过每次的价格都会变得越来越贵。', `MaleText_loc5`='我能消除你所有的天賦，讓你可以重新進行選擇。$b$b你每進行一次所需的費用都會變得更貴。', `MaleText_loc7`='Puedo borrar todos tus talentos para que puedas elegir otros nuevos.$B$BEste proceso es más caro cada vez que lo repites.', `FemaleText_loc1`='특성을 새로 구성할 수 있도록 모든 특성을 삭제해 드리겠습니다.$b$b특성 초기화 비용은 횟수를 거듭할수록 늘어납니다.', `FemaleText_loc4`='我可以清除你所有的天赋，这样你就可以重新选择了。$B$B不过每次的价格都会变得越来越贵。', `FemaleText_loc5`='我能消除你所有的天賦，讓你可以重新進行選擇。$b$b你每進行一次所需的費用都會變得更貴。', `FemaleText_loc7`='Puedo borrar todos tus talentos para que puedas elegir otros nuevos.$B$BEste proceso es más caro cada vez que lo repites.' WHERE `ID`=25284;
