UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필요한 게 있으신가요? 물건이 아주 많지는 않지만 손님께서 생각하시는 만큼은 있답니다... 신중하게 생각하고 선별한 물건들이니까요.', `MaleText_loc4`='想要点什么吗？可想而知……能供你挑选的东西也不多。', `MaleText_loc5`='我可以為你弄些什麼來嗎?我賣的東西並不多，但是你可以確信...所有東西都物超所值。', `MaleText_loc7`='¿Puedo traerte algo? Mi surtido es un poco limitado, pero era de esperar... teniendo en cuenta la situación.' WHERE `ID`=25308;
