UPDATE `locales_broadcast_text` SET `MaleText_loc1`='국가를 위해 죽는 일은 군인의 의뭅니다. 하지만 이 전쟁을 어리석다고 말하는 게 반역이라면, 저도 반역자겠군요.', `MaleText_loc4`='为国家牺牲是军人的职责。如果将这场战争称为闹剧就算是叛国的话，那我就是一名十足的叛徒了。', `MaleText_loc5`='為國家捐軀是士兵的天職。但是如果批評這場戰爭愚蠢就是通敵的話，那我就是叛徒。', `MaleText_loc7`='Morir por su país es el deber de un soldado. Pero si decir que esta guerra es una locura es traición, entonces soy un traidor.' WHERE `ID`=25310;
