UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼음안개... 얼음안개가... 안 돼!!! 영웅이여, 어서 오세요! 절 따라오십시오!', `MaleText_loc4`='冰雾村……但愿不是冰雾村……不！！！快！英雄，跟我来！', `MaleText_loc5`='冰霧...不是冰霧...不!!!快點過來，英雄!跟著我!', `MaleText_loc7`='Bruma de Hielo... Bruma de Hielo no... ¡¡¡NO!!! Rápido, ¡sígueme!', `FemaleText_loc1`='얼음안개... 얼음안개가... 안 돼!!! 영웅이여, 어서 오세요! 절 따라오세요!', `FemaleText_loc4`='冰雾村……但愿不是冰雾村……不！！！快！英雄，跟我来！', `FemaleText_loc5`='冰霧...不是冰霧...不!!!快點過來，英雄!跟著我!', `FemaleText_loc7`='Bruma de Hielo... Bruma de Hielo no... ¡¡¡NO!!! Rápido, ¡sígueme!' WHERE `ID`=25314;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 신호 연기를 자세히 보고 무슨 뜻인지 읽어냅니다.', `MaleText_loc4`='%s熟练地破译出了烽烟中包含的信息。', `MaleText_loc5`='%s專業地鑑定起濃煙信號下所隱藏的信息。', `MaleText_loc7`='%s descifra expertamente los mensajes escondidos en las señales de humo.', `FemaleText_loc1`='%s|1이;가; 신호 연기를 자세히 보고 무슨 뜻인지 읽어냅니다.', `FemaleText_loc4`='%s熟练地破译出了烽烟中包含的信息。', `FemaleText_loc5`='%s專業地鑑定起濃煙信號下所隱藏的信息。', `FemaleText_loc7`='%s descifra expertamente los mensajes escondidos en las señales de humo.' WHERE `ID`=25315;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$r|1이여;여;, 저는 지금 무척 바쁩니다. 방해하지 말아 주세요.', `FemaleText_loc4`='我现在很忙，$r。让我静一静。', `FemaleText_loc5`='我現在很忙，$r，請不要來煩我。', `FemaleText_loc7`='Ahora estoy muy ocupada, $r. Por favor, déjame sola.' WHERE `ID`=25316;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어떻게 된 건가요, $n 님? 제가 그대를 믿고 딸려 보낸 피난민은 어디 있나요?', `FemaleText_loc4`='出什么事了，$n？我要你护送那位村民撤离，结果呢？', `FemaleText_loc5`='$n，發生什麼事了?我拜託你照顧的疏散者呢?', `FemaleText_loc7`='¿Qué ha ocurrido, $n? ¿Dónde está el evacuado que te confié?' WHERE `ID`=25317;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죄송하지만 호위하던 피난민을 잃었습니다. 다른 피난민을 호위하게 해 주시겠습니까? 당신을 실망시키지 않겠습니다!', `MaleText_loc4`='很抱歉，我没能完成护送任务，那位村民不幸丧命了。能再给我一次机会吗？我保证不会再让你失望了！', `MaleText_loc5`='我要很遺憾的通知你，先前委託我護送的疏散者已經死掉了。你可以讓我去護送另一個疏散者嗎?我不會再讓你失望的!', `MaleText_loc7`='Siento informarte de que el evacuado que me encargaste escoltar ha fallecido. ¿Podrías permitirme escoltar a otro evacuado, por favor? ¡No volveré a fallarte!', `FemaleText_loc1`='죄송하지만 호위하던 피난민을 잃었어요. 다른 피난민을 호위하게 해 주시겠어요? 당신을 실망시키지 않겠어요!', `FemaleText_loc4`='很抱歉，我没能完成护送任务，那位村民不幸丧命了。能再给我一次机会吗？我保证不会再让你失望了！', `FemaleText_loc5`='我要很遺憾的通知你，先前委託我護送的疏散者已經死掉了。你可以讓我去護送另一個疏散者嗎?我不會再讓你失望的!', `FemaleText_loc7`='Siento informarte de que el evacuado que me encargaste escoltar ha fallecido. ¿Podrías permitirme escoltar a otro evacuado, por favor? ¡No volveré a fallarte!' WHERE `ID`=25318;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='서두르세요, $n 님! 피난민을 용의 안식처에 있는 워툭 아이스본에게 데려가세요!', `FemaleText_loc4`='快，$n！带这位村民逃离此地，与龙骨荒野的沃图克碰面！', `FemaleText_loc5`='快，$n!把疏散者送到龍骨荒野瓦圖克·冰誕那裡!', `FemaleText_loc7`='¡Deprisa, $n! ¡Lleva al evacuado junto a Guerratuk Hielonato en el Cementerio de Dragones!' WHERE `ID`=25319;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다시는 저를 실망시키지 마세요, $n 님. 피난민이 안전하게 도착하도록 해 주세요.', `FemaleText_loc4`='别再让我失望了，$n。你要保证带领这位村民安全撤离。', `FemaleText_loc5`='$n，不要再讓我失望了。確保疏散行動的安全。', `FemaleText_loc7`='No vuelvas a fallarme, $n. Asegúrate de que este evacuado queda a salvo.' WHERE `ID`=25320;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말해라, 리치! 언데드라고 해서 내가 보여줄 고통을 피해갈 수는 없다!', `MaleText_loc4`='巫妖，说话啊！即便你有不死的本事也难逃此劫！', `MaleText_loc5`='說，巫妖!永生不死將無法讓你逃過接下來你即將承受的事情!', `MaleText_loc7`='¡Habla, exánime! ¡La no-muerte no te salvará de lo que pienso hacerte!' WHERE `ID`=25321;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요, $g남자다운:아리따운:c; $c님. $g요새 어떠십니까?:오늘 예쁘군요.;', `MaleText_loc4`='Hi $gmanly:womanly:c; $c, $ghow''s it hangin?:you look pretty.;', `MaleText_loc5`='嗨$g強壯的:有氣質的:c;$c，$g最近如何?:你看起來真美。;', `MaleText_loc7`='Hola $gviril:femenina:c; $c, $g¿cómo va eso?:estás preciosa.;', `FemaleText_loc1`='안녕하세요, $g멋쟁이:예쁜이; 씨. 잘 지내시죠?', `FemaleText_loc4`='Hi $gmanly:womanly:c; $c, $ghow''s it hangin?:you look pretty.;', `FemaleText_loc5`='嗨$g強壯的:有氣質的:c;$c，$g最近如何?:你看起來真美。;', `FemaleText_loc7`='Hola $gviril:femenina; $c, $g¿cómo va eso?:estás preciosa.;' WHERE `ID`=25322;
