UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정하라, 비룡이여.', `MaleText_loc4`='放松点，幼龙。', `MaleText_loc5`='小飛龍，別害怕。', `MaleText_loc7`='Tranquilo, pequeño draco.' WHERE `ID`=25325;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 이걸로 충분히 연구를 진행할 수 있을 것이다...', `MaleText_loc4`='很好，这将使我的研究更进一步……', `MaleText_loc5`='很好，這東西應該會對我的研究有所幫助...', `MaleText_loc7`='Sí, este debería ayudar a que mis estudios avancen...' WHERE `ID`=25326;
