UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 종류의 야수를 원하시나요?', `MaleText_loc4`='你喜欢什么样的宠物？', `MaleText_loc5`='你想要哪一種類的寵物?', `MaleText_loc7`='¿Qué tipo de mascota quieres?', `FemaleText_loc1`='어떤 종류의 야수를 원하시나요?', `FemaleText_loc4`='你喜欢什么样的宠物？', `FemaleText_loc5`='你想要哪一種類的寵物?', `FemaleText_loc7`='¿Qué tipo de mascota quieres?' WHERE `ID`=25328;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 야수를 관리해 드림과 동시에 새로운 야수를 제공해 드리겠습니다.', `MaleText_loc4`='在我这里可以存放宠物，也可以领取新宠物。', `MaleText_loc5`='我可以同時寄放及給予新的寵物。', `MaleText_loc7`='Puedo hacer ambas cosas: cobijar y entregar nuevas mascotas.', `FemaleText_loc1`='제가 야수를 관리해 드림과 동시에 새로운 야수를 제공해 드리겠습니다.', `FemaleText_loc4`='在我这里可以存放宠物，也可以领取新宠物。', `FemaleText_loc5`='我可以同時寄放及給予新的寵物。', `FemaleText_loc7`='Puedo hacer ambas cosas: cobijar y entregar nuevas mascotas.' WHERE `ID`=25329;
