UPDATE `locales_broadcast_text` SET `MaleText_loc1`='늑대', `MaleText_loc4`='狼', `MaleText_loc5`='狼', `MaleText_loc7`='Lobo', `FemaleText_loc1`='늑대', `FemaleText_loc4`='狼', `FemaleText_loc5`='狼', `FemaleText_loc7`='Lobo' WHERE `ID`=25344;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님... 원하신다면... 이 미천한 사제를 없애도 됩니까? 고통스럽게요, 네?', `MaleText_loc4`='主人……你要我……杀死这名小祭司？让他痛苦地死去，对吗？', `MaleText_loc5`='主人...你想要...我殺了小牧師?讓他痛不欲生，是嗎?', `MaleText_loc7`='¿Maestro... querer... yo matar lamentable sacerdote? Hacer dolor, ¿verdad?' WHERE `ID`=25345;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래... 나약한 자여... 이 백골에게 목숨을 구걸해라!', `MaleText_loc4`='是的，渺小的弱者……向鲁瑞德求饶吧！', `MaleText_loc5`='是的，弱者...求路瑞德饒你一命!', `MaleText_loc7`='Sí, debilucho... ¡ruega a Escabroso por tu vida!' WHERE `ID`=25346;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음을 섬기나, 미천한 자여? 죽음이 바로 여기다!', `MaleText_loc4`='你崇拜死亡？死亡就在眼前！', `MaleText_loc5`='你崇拜死亡嗎，小傢伙?死亡就在這!', `MaleText_loc7`='¿Adoras a la muerte, hombrecito? ¡La muerte está aquí!' WHERE `ID`=25347;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아서스여, 우리를 구원하소서... 우린 파멸했어!', `MaleText_loc4`='阿尔萨斯救了我们——我们完了！', `MaleText_loc5`='阿薩斯救救我們 - 我們失敗了!', `MaleText_loc7`='Arthas sálvanos. ¡Estamos perdidos!', `FemaleText_loc1`='아서스여, 우리를 구원하소서... 우린 파멸했어!', `FemaleText_loc4`='阿尔萨斯救了我们——我们完了！', `FemaleText_loc5`='阿薩斯救救我們 - 我們失敗了!', `FemaleText_loc7`='Arthas sálvanos. ¡Estamos perdidos!' WHERE `ID`=25348;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 죽음의 기사는... 미쳤어!', `MaleText_loc4`='死亡骑士……他疯了！', `MaleText_loc5`='死亡騎士他...瘋了!', `MaleText_loc7`='El caballero de la Muerte... ¡está loco!', `FemaleText_loc1`='저 죽음의 기사는... 미쳤어!', `FemaleText_loc4`='死亡骑士……他疯了！', `FemaleText_loc5`='死亡騎士他...瘋了!', `FemaleText_loc7`='El caballero de la Muerte... ¡está loco!' WHERE `ID`=25349;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지구라트가 무너졌다! 사원으로 대피하라!', `MaleText_loc4`='祭塔失守了！向神庙撤退！', `MaleText_loc5`='通靈塔失守了!逃回神殿去!', `MaleText_loc7`='¡Hemos perdido el zigurat! ¡Huyamos al templo!', `FemaleText_loc1`='지구라트가 무너졌다! 사원으로 대피하라!', `FemaleText_loc4`='祭塔失守了！向神庙撤退！', `FemaleText_loc5`='通靈塔失守了!逃回神殿去!', `FemaleText_loc7`='¡Hemos perdido el zigurat! ¡Huyamos al templo!' WHERE `ID`=25350;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[PH] - 마력의 탑이 최근 들어 초래한 혼란을 비롯하여 키린 토와 마법을 사용하는 모든 필멸자를 처치하려는 말리고스의 노력에 대해 이야기합니다... 라엘로라즈에게 말리고스와 마력 전쟁에 대한 정보를 더 얻을 수 있음을 플레이어에게 알려 줍니다.', `MaleText_loc4`='[PH] - talks about the instability the nexus has been causing recently - about Malygos'' efforts to destroy the Kirin Tor and all mortal magic-users... Refers players to Raelorasz for more info about Malygos and the Nexus war.', `MaleText_loc5`='[PH] - 談到最近奧核之心所造成的不安 - 以及瑪里苟斯處心積慮要毀掉祈倫托和所有凡人魔法使用者...轉介玩家向瑞洛拉茲尋求更多關於瑪里苟斯，以及奧核之心的戰爭。', `MaleText_loc7`='[PH] - talks about the instability the nexus has been causing recently - about Malygos'' efforts to destroy the Kirin Tor and all mortal magic-users... Refers players to Raelorasz for more info about Malygos and the Nexus war.' WHERE `ID`=25351;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정신을 집중하라, 필멸의 존재여. 그대가 경험한 어떤 전쟁과도 다른 전쟁이 이곳에서 벌어질 것이다.$b$b여기서 조금이라도 도움이 되려면 그대가 지닌 능력을 모두 발휘해야 함을 명심하라.', `MaleText_loc4`='别走神啊。这场战争非比寻常，前线的气氛尤其紧张。$b$b想帮忙的话就打起精神来，让我看看你有多大的本事。', `MaleText_loc5`='凡人，專注你的思緒。這與你所見過的戰爭前線不大一樣。$b$b如果你想要幫上點忙，你得完整控制你的身體機能才行。', `MaleText_loc7`='Concéntrate, mortal. Esta es la línea de frente de una guerra como jamás has visto.$B$BNecesitarás el control total de tus facultades si quieres servirnos de algo.' WHERE `ID`=25352;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제발... 우리가 받은 모든 명령은 낙사나르에서 내려온 겁니다... 나와 내 부하들은 아무것도 모릅니다!', `MaleText_loc4`='求你了……我们只是执行来自纳克萨纳尔的命令啊……我和我的手下都被蒙在鼓里了！', `MaleText_loc5`='拜託...我們的命令都來自納克薩爾...我和我的手下被困在黑暗之中!', `MaleText_loc7`='Por favor... todas nuestras órdenes vienen de Naxxanar... ¡mis hombres y yo no sabemos nada!' WHERE `ID`=25353;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='간청합니다, 죽음의 기사여! 당신의 부하를 물러가게 해 주십시오! 뭐든 하겠습니다!', `MaleText_loc4`='求求你，死亡骑士！别让你的手下靠近我！你说什么我都照做啊！', `MaleText_loc5`='我乞求你，死亡騎士!叫你的手下遠離我!我什麼事情都肯做!', `MaleText_loc7`='¡Te lo ruego, caballero de la Muerte! ¡Mantén a tu esbirro alejado de mí! ¡Haré lo que sea!' WHERE `ID`=25354;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자비를 베푸십시오! 당신도 한때는 우리 편이지 않았습니까! 기억나지 않으십니까?', `MaleText_loc4`='发发慈悲吧！你曾经是我们中的一员！你不记得了吗？', `MaleText_loc5`='饒了我!你曾經是我們的一分子!你不記得了嗎?', `MaleText_loc7`='¡Piedad! ¡Hubo un tiempo en el que estuviste con nosotros! ¿No lo recuerdas?' WHERE `ID`=25355;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간 벌기 퀘스트 완료 이벤트에 필요한 던전 항목 효과를 기다리는 중입니다.', `MaleText_loc4`='Wating for dungeon particle effects to implement completion event for Buying Time quest.', `MaleText_loc5`='等待地城實測效果來實行「購買時間」任務的完成事件。', `MaleText_loc7`='Esperando que los efectos de las partículas de la mazmorra implementen el evento de finalización para la misión Comprando Tiempo.' WHERE `ID`=25356;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님, 신도들을 침투시켜 얼라이언스 지도부를 장악하는 계획이 착착 진행되고 있습니다.', `MaleText_loc4`='陛下，我们的教徒已经顺利地混入联盟的地盘并取得了一定的控制权。', `MaleText_loc5`='我的主人，我方教徒滲透與掌控聯盟權力結構的活動非常順利。', `MaleText_loc7`='Mi Señor, la infiltración y control de la estructura de poder de la Alianza por nuestros fieles está en marcha.' WHERE `ID`=25357;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제게 허락하신 힘은 인간의 마음을 조종하는 데 대단히 유용했습니다. 지금 보여 드릴 제물이 그 증겁니다.', `MaleText_loc4`='您赐予我的力量使我能够更好地控制人类的思维。这些祭品就是证据。', `MaleText_loc5`='你給予我的力量讓我得以大舉影響人類的心智。我帶來這些獻禮好證明我的進展。', `MaleText_loc7`='El poder que me confirió me ha dotado de una gran influencia sobre las mentes humanas. Traigo estas ofrendas como prueba de mi progreso.' WHERE `ID`=25358;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='레리사!', `MaleText_loc4`='莉蕾萨！', `MaleText_loc5`='蕾瑞莎!', `MaleText_loc7`='¡Leryssa!' WHERE `ID`=25359;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 동생에게 무슨 짓을 한 거냐, 이 사악한 엘프 자식아?!', `MaleText_loc4`='你这个混蛋精灵杂种，你对我的妹妹做了什么！？', `MaleText_loc5`='你這精靈惡棍，你對我妹妹做了什麼!?', `MaleText_loc7`='¡¿Qué le hiciste a mi hermana, escoria élfica?!' WHERE `ID`=25360;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 침입자를 처리하게 해주십시오. 놈들에게 지옥을 맛보여 주겠습니다.', `MaleText_loc4`='让我来对付这些入侵者吧。我会将他们的内脏拿去喂蛆。', `MaleText_loc5`='大人，請容我對付這些入侵者吧。我會把他們的內臟拿去餵蛆。', `MaleText_loc7`='Permítame ocuparme de los intrusos, mi Señor. Alimentaré a los gusanos con sus entrañas.' WHERE `ID`=25361;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발라나르, 여기 임무를 훌륭히 수행하고 있군. 무척 기쁘구나.', `MaleText_loc4`='你在这里所取得的进展令人眼前一亮，血之王子。我很满意。', `MaleText_loc5`='血親王，你在本區的進展令人印象深刻，我很滿意。', `MaleText_loc7`='Tu progreso en esta región fue impresionante, príncipe de sangre.  Me complace.' WHERE `ID`=25362;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호, 이것 참 놀랍군, 타사리안. 모그레인이나 다른 죽음의 기사들은 몇 달째 소식이 없는데. 다시 스컬지에 돌아오겠다는 의사로 받아들여도 되겠나?', `MaleText_loc4`='这可真是个惊喜，萨萨里安。我已经数月没有听到有关莫格莱尼和其他死亡骑士的消息了。我猜，你是回来重新加入天灾军团的？', `MaleText_loc5`='真是個驚喜，薩沙理安。數月以來我未曾聽聞莫格萊尼或其他死亡騎士的消息。我猜你是想再次加入天譴軍團，對吧?', `MaleText_loc7`='Qué sorpresa, Thassarian. Hace meses que no sé nada de Mograine o los demás caballeros de la muerte. ¿Supongo que vienes a reincorporarte a la Plaga?' WHERE `ID`=25363;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 실망시키지 마라, 산레인. 이 멍청이의 머리를 손에 넣기 전에는 얼음왕관으로 돌아오지 마라.', `MaleText_loc4`='别让我失望，萨莱因。把这个蠢货的首级带回冰冠冰川，否则就不用回去见我了。', `MaleText_loc5`='不要讓我失望，煞婪。把這蠢貨的頭帶回寒冰皇冠，否則，就不必回來了。', `MaleText_loc7`='No me falles, San''layn. Regresa a la Corona de Hielo con la cabeza de este tonto o no regreses.' WHERE `ID`=25364;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예, 주인님!', `MaleText_loc4`='遵命，陛下！', `MaleText_loc5`='是的，主人!', `MaleText_loc7`='¡Sí, mi señor!' WHERE `ID`=25365;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='차라리 혀를 깨물겠다. 이 쓰레기 같은 놈... 넌 부하들을 배신했어, 아서스! 맹세코 널 가만두지 않겠다!', `MaleText_loc4`='我宁愿自行了断。为了你对同胞犯下的罪行，阿尔萨斯，为了你对我犯下的罪行，你会付出代价的！我发誓！', `MaleText_loc5`='我寧願割斷自己的喉嚨也不要效忠你。阿薩斯，你一定會為你對自己的部屬...以及對我...所做的一切付出代價!我發誓!', `MaleText_loc7`='Antes me quito mi propia vida. Pagarás por lo que les hiciste a tus hombres, Arthas... ¡y por lo que me hiciste a mí! Lo juro.' WHERE `ID`=25366;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 무슨 소리지? 황혼의 소환사가 도착한 건가?', `MaleText_loc4`='那是什么声音？暮光召唤者到了吗？', `MaleText_loc5`='那是什麼聲音?暮光召喚者抵達了嗎?', `MaleText_loc7`='¿Qué es ese ruido? ¿Han llegado los invocadores Crepusculares?', `FemaleText_loc1`='이게 무슨 소리죠? 황혼의 소환사가 도착한 건가요?', `FemaleText_loc4`='那是什么声音？暮光召唤者到了吗？', `FemaleText_loc5`='那是什麼聲音?暮光召喚者抵達了嗎?', `FemaleText_loc7`='¿Qué es ese ruido? ¿Han llegado los invocadores Crepusculares?' WHERE `ID`=25367;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안돼! 너무 일러... 군주 아훈 님의 힘은 아직 완전하지 않단 말이다!', `MaleText_loc4`='不！现在还不是时候——埃霍恩大人还未得到全部的能量！', `MaleText_loc5`='不!太快了 - 艾胡恩領主還未處於全力狀態!', `MaleText_loc7`='¡NO! Es demasiado pronto. ¡Lord Ahune aún no tiene toda su potencia!', `FemaleText_loc1`='안돼! 너무 일러... 군주 아훈 님의 힘은 아직 완전하지 않단 말이다!', `FemaleText_loc4`='不！现在还不是时候——埃霍恩大人还未得到全部的能量！', `FemaleText_loc5`='不!太快了 - 艾胡恩領主還未處於全力狀態!', `FemaleText_loc7`='¡NO! Es demasiado pronto. ¡Lord Ahune aún no tiene toda su potencia!' WHERE `ID`=25368;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='촘촘한 비전 감옥을 잃어버린 것 같습니다. 제가 혹시 여기에 두고 가지 않았습니까?', `MaleText_loc4`='我好像弄丢了强化奥术牢笼。在你这儿吗？', `MaleText_loc5`='我好像弄丟了增強的秘法監牢。我有把它放在你這裡嗎?', `MaleText_loc7`='Parece que he perdido la prisión Arcana aumentada. ¿La dejé aquí contigo?', `FemaleText_loc1`='촘촘한 비전 감옥을 잃어버린 것 같아요. 제가 혹시 여기에 두고 가지 않았나요?', `FemaleText_loc4`='我好像弄丢了强化奥术牢笼。在你这儿吗？', `FemaleText_loc5`='我好像弄丟了增強的秘法監牢。我有把它放在你這裡嗎?', `FemaleText_loc7`='Parece que he perdido la prisión Arcana aumentada. ¿La dejé aquí contigo?' WHERE `ID`=25369;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 있다, $n.$b$b좀 더 조심하거라. 알겠느냐?', `MaleText_loc4`='$n，给。$b$b小心点，好吗？', `MaleText_loc5`='$n，拿去吧。$b$b萬事小心，好嗎?', `MaleText_loc7`='Aquí tienes, $n.$B$BTen más cuidado, ¿vale?' WHERE `ID`=25370;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 이런 분쟁이 일어난 것입니까?', `MaleText_loc4`='引发这次冲突的原因是什么？', `MaleText_loc5`='這場衝突的起因是什麼?', `MaleText_loc7`='¿Cuál es la causa de este conflicto?', `FemaleText_loc1`='왜 이런 분쟁이 일어난 건가요?', `FemaleText_loc4`='引发这次冲突的原因是什么？', `FemaleText_loc5`='這場衝突的起因是什麼?', `FemaleText_loc7`='¿Cuál es la causa de este conflicto?' WHERE `ID`=25371;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필멸의 존재여, 서리 군주님께서 이 세계에 오시는 것을 막지는 못하리라. 바다사냥꾼님이 휘두르는 권력이 라그나로스의 힘을 완전히 무너뜨리고, 네 땅을 동토의 왕국으로 만들리라!', `MaleText_loc4`='你无法阻止冰霜之王进入这个世界，凡人。猎潮者的力量将毁灭属于拉格纳罗斯的一切，将你们的土地变成一块冰封的乐园！', `MaleText_loc5`='凡人，你將無法阻止冰霜領主進入這個世界。獵潮者的力量將會永遠的摧毀拉格納羅斯，讓你的土地變成一個冰凍天堂!', `MaleText_loc7`='No podrás evitar que el Señor de la Escarcha entre en este mundo, mortal. El poder del cazamareas aplastará el de Ragnaros para siempre y tu tierra se convertirá en un paraíso helado.', `FemaleText_loc1`='필멸의 존재여, 서리 군주님께서 이 세계에 오시는 것을 막지는 못하리라. 바다사냥꾼님이 휘두르는 권력이 라그나로스의 힘을 완전히 무너뜨리고, 네 땅을 동토의 왕국으로 만들리라!', `FemaleText_loc4`='你无法阻止冰霜之王进入这个世界，凡人。猎潮者的力量将毁灭属于拉格纳罗斯的一切，将你们的土地变成一块冰封的乐园！', `FemaleText_loc5`='凡人，你將無法阻止冰霜領主進入這個世界。獵潮者的力量將會永遠的摧毀拉格納羅斯，讓你的土地變成一個冰凍天堂!', `FemaleText_loc7`='No podrás evitar que el Señor de la Escarcha entre en este mundo, mortal. El poder del cazamareas aplastará el de Ragnaros para siempre y tu tierra se convertirá en un paraíso helado.' WHERE `ID`=25372;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아훈이 일어날 때, 우리도 준비되어 있겠지요?', `MaleText_loc4`='当埃霍恩出现时，我们能准备好吗？', `MaleText_loc5`='當艾胡恩出現時，我們會準備好了嗎?', `MaleText_loc7`='¿Estaremos preparados cuando Ahune salga a la superficie?', `FemaleText_loc1`='아훈이 일어날 때, 우리도 준비되어 있겠지요?', `FemaleText_loc4`='当埃霍恩出现时，我们能准备好吗？', `FemaleText_loc5`='當艾胡恩出現時，我們會準備好了嗎?', `FemaleText_loc7`='¿Estaremos preparados cuando Ahune salga a la superficie?' WHERE `ID`=25373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희가 정신을 불꽃에 집중할 때 그대는 아훈의 하수인들을 견뎌내야 합니다. 서리 군주가 약해지기 전에는 가까이 가지 마십시오.', `MaleText_loc4`='你一定要在我们引导火焰的这段时间内挡住埃霍恩的手下。在我们削弱埃霍恩之前，不要靠近它。', `MaleText_loc5`='你必須在我們導入我們的火焰時讓艾胡恩的手下活著。別靠近冰霜領主，直到我們可以消滅他為止。', `MaleText_loc7`='Debes sobrevivir a los esbirros de Ahune mientras canalizamos nuestras llamas. No te acerques al Señor de la Escarcha hasta que podamos destruirlo.', `FemaleText_loc1`='저희가 불꽃을 하나로 모을 때 그대는 아훈의 하수인들을 견뎌내야 합니다. 서리 군주가 약해지기 전에는 가까이 가지 마세요.', `FemaleText_loc4`='你一定要在我们引导火焰的这段时间内挡住埃霍恩的手下。在我们削弱埃霍恩之前，不要靠近它。', `FemaleText_loc5`='你必須在我們導入我們的火焰時讓艾胡恩的手下活著。別靠近冰霜領主，直到我們可以消滅他為止。', `FemaleText_loc7`='Debes sobrevivir a los esbirros de Ahune mientras canalizamos nuestras llamas. No te acerques al Señor de la Escarcha hasta que podamos destruirlo.' WHERE `ID`=25374;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 공격하시오! 아훈의 힘이 약해졌을 때 얼어붙은 핵을 치시오!', `MaleText_loc4`='攻击！趁埃霍恩的力量被削弱的时候，攻击它的霜冻之心！', `MaleText_loc5`='發動攻擊!在艾胡恩清醒時攻擊他的冰霜核心!', `MaleText_loc7`='¡Atacad ahora! ¡Atacad el núcleo congelado de Ahune mientras está debilitado!', `FemaleText_loc1`='지금 공격하세요! 아훈의 힘이 약해졌을 때 얼어붙은 핵을 치세요!', `FemaleText_loc4`='攻击！趁埃霍恩的力量被削弱的时候，攻击它的霜冻之心！', `FemaleText_loc5`='發動攻擊!在艾胡恩清醒時攻擊他的冰霜核心!', `FemaleText_loc7`='¡Atacad ahora! ¡Atacad el núcleo congelado de Ahune mientras está debilitado!' WHERE `ID`=25375;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼어붙은 심연이 너를 부른다, $r! 우리와 합류해라!', `MaleText_loc4`='$r，冰封的地狱在向你招手！跟我们走吧！', `MaleText_loc5`='凜冽的深淵正向你招手，$r!加入我們!', `MaleText_loc7`='¡El gélido abismo te llama, $r! ¡Únete a nosotros!' WHERE `ID`=25376;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성물함은 네놈이 손댈 물건이 아니다, $n! 이 죄에 대한 대가를 치르게 해주마.', `MaleText_loc4`='$n，你别想拿走护符匣！你会为你犯下的罪行付出代价的。', `MaleText_loc5`='$n，骨匣不是你們該拿的東西!為你們犯下的過錯付出代價吧。', `MaleText_loc7`='¡No puedes llevarte la filacteria, $n! Pagarás por tu transgresión.' WHERE `ID`=25377;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대지가 무섭게 요동치고 있습니다!$B$B어둠의 존재가 산레인을 이끌고 다시 일어났고, 용족은 마력의 탑을 둘러싸고 전쟁을 벌이지요. 게다가 브리쿨마저 다시 깨어났습니다.$B$B당신의 동족은 그들과 싸우려고 배를 타고 북쪽으로 향하고 있으니 우리 칼루아크는 그 한가운데에 낀 셈입니다.$B$B그리고 이제는 무언가 아주 극악한 일이 벌어져 세상에 흐르는 마력 때문에 땅덩어리가 갈라지고 있습니다. 살아남으려면 우린 안전한 보금자리를 찾아야만 해요.$B$B제 옆에 있는 두 사절 때문에 골치가 아프군요... 당신이 저희 동족을 도와주지 않겠습니까, $r|1이여;여;?', `MaleText_loc4`='局势动荡！$B$B巫妖王率领萨莱因卷土重来，巨龙们纷纷投身魔枢之战，而维库人也在此时再度觉醒。$B$B你们乘坐木船来到严寒的极北之地与他们作战。各方势力互相牵制，形势大乱，使得海象人处于进退维谷的尴尬境地。$B$B眼下，新的邪恶势力又企图利用魔法力量彻底炸毁这片土地。我们必须寻找一处安全的避风港才能继续生存下去。$B$B这两位大使让我挺为难的……$r，你愿意帮助我的族人吗？', `MaleText_loc5`='大地正處於巨大的混亂之中!$B$B黑暗者伴隨著煞婪一族再度前來，龍群則忙於牠們偉大的奧核戰爭，而維酷人再次甦醒。$B$B你的人民搭乘著木船往北出航前去加入戰鬥，而我們卡魯耶克則被困在其中。$B$B而現在，某些極為邪惡的東西發生了，大地因為世界的魔法能量而爆發。我們一定得找到一個安全的地方，讓我們得以存活。$B$B這兩個大使讓我很頭疼...或許你可以幫幫我的人民，$r?', `MaleText_loc7`='¡Esta región está muy alborotada!$B$BLos oscuros cabalgan de nuevo junto con sus San''layn, los dragones luchan en su gran guerra de El Nexo y los vrykuls han vuelto a despertar.$B$BTu gente navega hacia el norte en sus barcos de madera y luchan unos contra otros y nosotros, los Kalu''ak, estamos atrapados en medio.$B$BY ahora, mediante alguna temible maldad, la tierra explota con la energía mágica del mundo. Tenemos que encontrar un refugio seguro donde tengamos una posibilidad de sobrevivir. Estos dos embajadores me dan dolor de cabeza... quizá tú puedas ayudar a mi gente, $r.' WHERE `ID`=25378;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에휴... 살마 살딘 아줌마가 만든 서부정통 스튜 한 그릇만 먹었으면 소원이 없겠어.', `MaleText_loc4`='伙计，我愿意用任何东西来换一碗老萨尔玛·萨丁的杂味炖肉。', `MaleText_loc5`='老天，我現在願意花一切代價吃一碗老薩爾瑪·薩丁的西部荒野燉肉。', `MaleText_loc7`='Lo que daría ahora por un cuenco de estofado de los Páramos de Poniente de la vieja Salma Saldean.' WHERE `ID`=25379;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='짬밥에 건빵만 먹고 어떻게 살라는 건지.', `MaleText_loc4`='别指望稀饭和干面包能帮助我们渡过难关。', `MaleText_loc5`='硬麵包和稀飯被吃得一點也不剩。', `MaleText_loc7`='No se puede sobrevivir a base de gachas y galletas.' WHERE `ID`=25380;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그거 알아? 그거 사실은 살딘 아줌마의 요리법이 아니야.', `MaleText_loc4`='要知道，这份食谱并不是萨丁发明的。', `MaleText_loc5`='你知道，這並不是真正的薩丁配方。', `MaleText_loc7`='¿Sabes? En realidad no es la receta de Saldean.' WHERE `ID`=25381;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그건 살마 살딘 아줌마가 아니라 우리 엄마가 개발한 요리법이야. 우리 부모님이 늙은말 블랑쉬를 데리고 서부 몰락지대를 떠날 때, 지나가는 사람한테 그 조리법을 살마 아줌마한테 전해 달라고 부탁했어.', `MaleText_loc4`='这才不是萨尔玛·萨丁发明的食谱。它属于我的母亲。我的父母带着老马布兰契离开西部荒野时，让某个旅行者把这份食谱送给了萨尔玛。', `MaleText_loc5`='這不是薩爾瑪·薩丁的食譜。這是我老媽的。就在我老媽和老爹駕著老馬布蘭契離開西部荒野之前，她拜託行人把食譜送給了薩爾瑪。', `MaleText_loc7`='No es la receta de Salma Saldean. Es de mi mami. Le pidió a alguien que pasaba por allí que se la llevara a Salma antes de que ella y papi abandonaran los Páramos de Poniente con la vieja Blanchy.' WHERE `ID`=25382;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐라고?', `MaleText_loc4`='什么？', `MaleText_loc5`='啥?', `MaleText_loc7`='¿Qué?' WHERE `ID`=25383;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사라고사를 상대할 준비가 되었습니다!', `MaleText_loc4`='我已经准备好对付莎拉苟萨了！', `MaleText_loc5`='我準備好挑戰薩拉苟莎了!', `MaleText_loc7`='¡Estoy preparado para enfrentarme a Saragosa!', `FemaleText_loc1`='사라고사를 상대할 준비가 됐어요!', `FemaleText_loc4`='我已经准备好对付莎拉苟萨了！', `FemaleText_loc5`='我準備好挑戰薩拉苟莎了!', `FemaleText_loc7`='¡Estoy preparada para enfrentarme a Saragosa!' WHERE `ID`=25384;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 그래? 최소한 살딘 씨네 가족은 상황이 나빠졌을 때도 서부 몰락지대에서 도망치진 않았어.', `MaleText_loc4`='是吗？好吧，至少萨丁没有在局势艰难时逃离西部荒野。', `MaleText_loc5`='是嗎?嗯，至少薩丁一家並沒有在情況變的很艱困的時候逃離西部荒野。', `MaleText_loc7`='¿Sí? Bueno, al menos los Saldean no huyeron de los Páramos de Poniente cuando las cosas se pusieron feas.' WHERE `ID`=25385;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 으스대지 마라. 무슨 생각을 하는지 알겠다만, 폭풍우 요새는 잠시 머무르는 곳이었을 뿐이야. 내가 정말로 눈먼 반쪽짜리 나이트 엘프 잡종 따위에게 미래를 맡길 거라고 생각했나?', `MaleText_loc4`='别拿那种眼神看着我！我知道你们在想些什么，但风暴要塞的失败早就过去了。你们真以为我会把命运交给一个又瞎又粗野又下贱的暗夜精灵杂种？', `MaleText_loc5`='別如此得意!我知道你在想什麼，但風暴要塞只不過是一場小小的挫敗而已。你真的以為我會把未來交給一個瞎了眼的半混血夜精靈嗎?', `MaleText_loc7`='¡No sean tan engreídos! Sé lo que están pensando, pero El Castillo de la Tempestad no era más que una distracción. ¿Realmente creyeron que confiaría el futuro a un perro ciego medio elfo de la noche?' WHERE `ID`=25386;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 그럴 리가. 일리단은 더 원대한 계획을 실현할 도구이자 하찮은 발판이었을 뿐이다! 바로 지금을 위한... 그리고 이번엔, 너희도 날 방해할 수 없어!', `MaleText_loc4`='噢，显然不是，我只是利用他而已，他不过是我庞大计划的一个垫脚石！我真正的目标在这里……而且，这一次不会再被你们干扰到了！', `MaleText_loc5`='喔不，他不過是一個被利用的工具，一個更偉大計畫中的踏腳石罷了!所有的一切都是為了現在...而這一次你無法阻止我!', `MaleText_loc7`='¡Oh no, él solo era un instrumento, el primer paso de un plan mucho mayor! Todo nos ha llevado hasta aquí... ¡y esta vez no os interpondréis!' WHERE `ID`=25387;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='복수여, 타올라라!', `MaleText_loc4`='复仇之炎，燃烧吧！', `MaleText_loc5`='復仇之焰，燃燒吧!', `MaleText_loc7`='¡La venganza arde!' WHERE `ID`=25388;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='펠로민 아샬!', `MaleText_loc4`='Felomin Ashal！', `MaleText_loc5`='(薩拉斯語)火焰吞噬!', `MaleText_loc7`='¡Felomin Ashal!' WHERE `ID`=25389;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세상을... 거꾸로... 뒤집어주마.', `MaleText_loc4`='我要让你们的世界……彻底颠覆……', `MaleText_loc5`='我要讓你們的世界徹底顛覆。', `MaleText_loc7`='Pondré su mundo... cabeza... abajo.' WHERE `ID`=25390;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님, 제게 힘을 주소서.', `MaleText_loc4`='主人，赐予我力量。', `MaleText_loc5`='主人，賜予我力量。', `MaleText_loc7`='Maestro, otórgame fuerza.' WHERE `ID`=25391;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무... 편안해하지는 마라.', `MaleText_loc4`='不会让你们好过的。', `MaleText_loc5`='不會...讓你們好過的。', `MaleText_loc7`='No os pongáis... demasiado cómodos.' WHERE `ID`=25392;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런다고 달라질 것 같으냐! 주인님께서 널 가만두지 않을 것이다! 피의 강에서 허우적대라! 세상은 불타버릴 것이다! 으아아!', `MaleText_loc4`='我的死根本算不了什么！主人一定会消灭你们的！你们会溺毙在自己的鲜血中！这个世界将会熊熊燃烧！啊！', `MaleText_loc5`='我的死根本算不了什麼!主人一定會消滅你們的!你們將浸浴在自己的血液裡!這個世界將被燒毀殆盡!啊!', `MaleText_loc7`='¡Mi muerte no supone nada! ¡El maestro acabará con ustedes! ¡Se ahogarán en su propia sangre! ¡Este mundo arderá! ¡Aaaghh!' WHERE `ID`=25393;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그대를 다시 만나 참으로 기쁘구나, $n|1이여;여;.', `FemaleText_loc4`='很高兴能再见到你，$n。', `FemaleText_loc5`='$n，能再一次見到你真的很開心。', `FemaleText_loc7`='Es un verdadero placer volver a verte, $n.' WHERE `ID`=25394;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 엄마, 아빠를 모욕하지 마! 그 말 취소해!', `MaleText_loc4`='不准侮辱我的父母！收回你的话！', `MaleText_loc5`='沒有人可以污辱老爹和老媽!把話收回去!', `MaleText_loc7`='¡Nadie insulta a mami y papi! ¡Retíralo!' WHERE `ID`=25395;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='못 하겠다면 어쩔 건데! 네 부모님은 겁쟁이야. 너도 마찬가지고, 펄브라우!', `MaleText_loc4`='我偏要说！你的父母都是胆小鬼，你也是，弗布隆！', `MaleText_loc5`='你聽到我說的了!你的父母是懦夫，你也一樣，法布隆!', `MaleText_loc7`='¡Has oído lo que he dicho! ¡Tus padres son unos cobardes igual que tú, Cejade!' WHERE `ID`=25396;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크발디르는 잔혹한 놈들입니다, $n 님. 하지만 저는 이 성스러운 카스칼라를 버릴 수가 없습니다. 우리가 정령을 저버리지 않는다면 정령들 또한 우리를 저버리지 않을 겁니다.', `MaleText_loc4`='$n，克瓦迪尔生性残忍，可是我不能放弃神圣的卡斯卡拉。只要我们不抛弃灵魂，灵魂就不会抛弃我们。', `MaleText_loc5`='科瓦迪爾很殘忍，$n。但是我沒有辦法將神聖的卡斯卡拉棄之不顧。如果我們不放棄靈魂，靈魂也就不會遺棄我們。', `MaleText_loc7`='Los Kvaldir no tienen piedad, $n. Pero no puedo abandonar la sagrada Kashala. Si no abandonamos a los espíritus, ellos tampoco nos abandonarán.' WHERE `ID`=25397;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카스칼라가 공격받고 있습니다! 도망칠 수 있을 때까지는 막아내야 합니다.', `MaleText_loc4`='卡斯卡拉遭到攻击！我们必须拖住敌军，直到所有人安全撤离。', `MaleText_loc5`='卡斯卡拉遭受攻擊!在我們有辦法逃跑之前，我們一定要拖住他們。', `MaleText_loc7`='¡Están atacando Kashala! Debemos mantenerlos a distancia hasta que podamos escapar.' WHERE `ID`=25398;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알았어, 취소한다고! 너희 부모님은 겁쟁이가 아니야!', `MaleText_loc4`='好吧，我收回我的话！你的父母不是胆小鬼！', `MaleText_loc5`='好了，我拿回來了!你的父母不是懦夫了!', `MaleText_loc7`='¡Vale! ¡Lo retiro! ¡Tu papi y tu mami no eran cobardes!' WHERE `ID`=25399;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저주받은 거인 녀석들! 싸우고 싶다면 싸워주마!', `MaleText_loc4`='该死的巨人！如果他们想打仗，那就打吧！', `MaleText_loc5`='該死的巨人!如果他們想要開戰，那就如他們所願!', `MaleText_loc7`='¡Malditos hombres-gigante! ¡Si quieren lucha, lucha tendrán!' WHERE `ID`=25400;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 말을 알아들어서 다행이군...', `MaleText_loc4`='很高兴你能站在我的角度考虑问题……', `MaleText_loc5`='很高興你決定用我的方法來看事情了...', `MaleText_loc7`='Me alegra que hayas decidido ver las cosas a mi manera...' WHERE `ID`=25401;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오십시오, $c. 여기 불꽃에 경의를 표하러 온 적이 있으십니까?$b$b호드가 있는 곳 어디나 축제 불꽃이 타오른다는 것을 잊지 마십시오. 시간을 낼 수 있다면 전부 찾아가보는 건 어떻겠습니까?$B$B얼라이언스도 마찬가지로 자기네 불꽃을 피운다 합니다. 얼라이언스 불꽃같이 쓸데없는 짓은 발견했을 때 좀 모독해주는 게 좋을 겁니다.', `MaleText_loc4`='欢迎你，$c。你祭拜过这座火堆了吗？$b$b记住：所有部落人民定居的地方，都会有我们的节日之火在那里熊熊地燃烧着。$b$b联盟也一样，在各处都点起了他们自己的火焰。当你看见这些火堆时，不妨亵渎之，对我们会有帮助的。', `MaleText_loc5`='歡迎，$c。你是來榮耀這座火焰的嗎?$b$b記住:我們的節慶火焰在每個擁有部落營區的土地上燃燒著。如果可以的話，花點時間前去榮耀每一座火焰吧。$b$b聯盟也是一樣，燃燒著屬於他們的火焰。當你遇到聯盟的火焰時，你還是褻瀆一下像這樣沒有意義的努力比較好。', `MaleText_loc7`='Saludos, $c. ¿Has venido a honrar esta llama?$B$BRecuerda: las hogueras de nuestro festival arden en todas las regiones con un asentamiento de la Horda. Saca tiempo para honrarlas a todas si puedes.$B$BLa Alianza también tiene sus propios fuegos. Harías bien en profanar esos indignos esfuerzos cuando los veas.', `FemaleText_loc1`='어서 오세요, $c. 여기 불꽃에 경의를 표한 적이 있으신가요?$b$b잊지 마세요. 호드가 있는 곳 어디나 우리 축제 불꽃이 타오르고 있다는 것을 말이죠. 시간을 낼 수 있다면 전부 찾아가보세요.$B$B얼라이언스도 마찬가지로 자기네 불꽃을 피운다더군요. 얼라이언스 불꽃같이 쓸데없는 짓은 발견했을 때 좀 모독해줘도 좋을 거예요.', `FemaleText_loc4`='欢迎你，$c。你祭拜过这座火堆了吗？$b$b记住：所有部落人民定居的地方，都会有我们的节日之火在那里熊熊地燃烧着。$b$b联盟也一样，在各处都点起了他们自己的火焰。当你看见这些火堆时，不妨亵渎之，对我们会有帮助的。', `FemaleText_loc5`='歡迎，$c。你是來榮耀這座火焰的嗎?$b$b記住:我們的節慶火焰在每個擁有部落營區的土地上燃燒著。如果可以的話，花點時間前去榮耀每一座火焰吧。$b$b聯盟也是一樣，燃燒著屬於他們的火焰。當你遇到聯盟的火焰時，你還是褻瀆一下像這樣沒有意義的努力比較好。', `FemaleText_loc7`='Saludos, $c. ¿Has venido a honrar esta llama?$B$BRecuerda: las hogueras de nuestro festival arden en todas las regiones con un asentamiento de la Horda. Saca tiempo para honrarlas a todas si puedes.$B$BLa Alianza también tiene sus propios fuegos. Harías bien en profanar esos indignos esfuerzos cuando los veas.' WHERE `ID`=25402;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필멸의 영웅들이여, 오늘 이 승리는 오래전에 예견되었다네. 내 형제가 고통스럽게 내뱉은 패배의 울부짖음은 온 우주에 울려 퍼질 걸세. 그리고 불타는 성전에 맞서 싸우는 이들에게 새로운 희망을 전파하겠지.', `MaleText_loc4`='凡人英雄们，很早以前的预言之中就昭示了你们今天的胜利。我那堕落兄弟的凄惨号叫将会响彻整个宇宙——这也会把希望带给那些仍然在反抗着燃烧军团的人们。', `MaleText_loc5`='凡人的英雄們 - 你們今日的勝利實現了古老的預言。我兄弟被擊敗的痛苦哀嚎將在整個宇宙迴響 - 帶給所有仍在抵抗燃燒遠征的人們新的希望。', `MaleText_loc7`='Héroes mortales, su victoria de hoy aquí fue profetizada hace mucho. El angustiado grito de derrota de mi hermano resonará en el universo y llevará una esperanza renovada a todos los que aún se enfrentan a la Legión Ardiente.' WHERE `ID`=25403;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불타는 군단의 진정한 패배가 멀지 않았으니, 그대들이 거센 불길에 맞서 이 세계를 지켜왔음을 마음에 새기고 가슴을 펴게나.', `MaleText_loc4`='燃烧军团彻底灭亡的日子又更近了一步，你们再一次将这个世界从火焰中拯救下来，你们应当为此而自豪！', `MaleText_loc5`='燃燒軍團徹底敗亡的日子又更近了一步，你們已經從戰火下拯救了無數個世界，你們應當為此而自豪!', `MaleText_loc7`='Mientras se acerca la derrota definitiva de la Legión, sentíos orgullosos sabiendo que habéis salvado incontables mundos de la llama.' WHERE `ID`=25404;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘은 한 시대에 종언을 고하는 날이자, 또한 새로운 장을 여는 날이라네...', `MaleText_loc4`='这一天标志着一个结束，这一天也宣告了一个全新的开始……', `MaleText_loc5`='就如同這天標示了一場終結，它同時也宣告了另一個開始...', `MaleText_loc7`='Del mismo modo que marca un final, este día también anuncia un nuevo comienzo...' WHERE `ID`=25405;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘은 한 시대에 종언을 고하는 날이자, 또한 새로운 장을 여는 날이라네...', `MaleText_loc4`='这一天标志着一个结束，这一天也宣告了一个全新的开始……', `MaleText_loc5`='就如同這天標示了一場終結，它同時也宣告了另一個開始...', `MaleText_loc7`='Del mismo modo que marca un final, este día también anuncia un nuevo comienzo...' WHERE `ID`=25406;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대들이 쓰러뜨려야만 했던 엔트로피우스는 한때는 고귀한 나루, 므우루였다네. 생전에 므우루는 막대한 빛과 희망을 뿜는 존재였지. 한동안, 눈먼 이들이 그 힘을 훔치려고 했다네...', `MaleText_loc4`='你们之前消灭的那只熵魔，曾经是一位高贵的纳鲁，他名叫穆鲁。生前，他一直将代表着光明与希望的能量带给世人。不过，有一段时间，一些迷茫的孩子却囚禁了它，偷取这些能量。', `MaleText_loc5`='那個你們被迫消滅的生物，安卓普斯，曾是一名高貴的那魯，莫魯。生前，莫魯引導了聖光與希望的廣大能量。而曾有一段時間，有些迷失的人們試圖偷取這些能量...', `MaleText_loc7`='La criatura Entropius, a quien os habéis visto obligados a destruir, fue otrora el noble naaru M’uru. En vida, M’uru canalizó grandes energías de LUZ y ESPERANZA. Durante algún tiempo, algunos descaminados intentaron robar esas energías...' WHERE `ID`=25407;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저희의 불손함은 용서받을 길이 없습니다. 가장 고귀한 존재 중 하나를 더럽혔으니까요. 이 죄는 씻을 수가 없을 겁니다.', `FemaleText_loc4`='我们的傲慢是无法宽恕的。我们竟然加害于一位如此高贵的存在，这样的罪孽永远也无法弥补。', `FemaleText_loc5`='我們的傲慢是無法寬恕的。我們竟然加害於一位如此高貴的存在，這樣的罪孽永遠也無法彌補。', `FemaleText_loc7`='Nuestra arrogancia fue imperdonable. Condenamos a uno de los seres más nobles jamás conocidos. Nunca expiaremos este pecado.' WHERE `ID`=25408;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반드시 그렇지는 않다네. 므우루가 쓰러진 곳에서 신성한 나루의 불꽃을 다시 찾았으니까! 젊은 블러드 엘프여, 믿음이 머무는 곳에는 언제나 희망이 있다네.', `MaleText_loc4`='幸运的是，我在这位高贵的纳鲁陨落的地方回收了他的火种！在火种中，希望仍然没有消逝，年轻的血精灵。', `MaleText_loc5`='然而幸運的是，我們從它殞落之處取回了高貴那魯的生命星火!只要信仰仍在，希望就永遠不滅，年輕的血精靈。', `MaleText_loc7`='¡La buena noticia es que he recuperado la chispa del noble naaru del lugar en que cayó! Donde hay fe nunca se pierde la esperanza, joven elfo de sangre.' WHERE `ID`=25409;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말인가요?', `FemaleText_loc4`='可以吗？', `FemaleText_loc5`='可以嗎?', `FemaleText_loc7`='¿Es posible...?' WHERE `ID`=25410;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필멸자여, 므우루의 심장을 들여다보게! 흠집 하나 없지 않은가. 천지창조의 그 순간처럼, 만물을 생성하는 빛에 정화된 것이라네.', `MaleText_loc4`='凝视它，凡人们，凝视穆鲁这颗依然纯洁无瑕的心。沐浴在这创生的光芒之中吧，就如同在沐浴晨曦一般。', `MaleText_loc5`='注意看著，凡人 - 看著莫魯的心!純潔無瑕。沐浴在造物的聖光中 - 如同拂曉晨曦。', `MaleText_loc7`='¡Observad ahora, mortales, el CORAZÓN DE M’URU! Inmaculado. Bañado por la luz de la creación, como en el amanecer.' WHERE `ID`=25411;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간이 지나면, 이 심장이 품은 빛과 희망이 태양샘을, 아니 그 너머까지를 채울 걸세... 어쩌면 한 종족의 영혼 또한 다시 채울지도 모르지.', `MaleText_loc4`='很快，其中蕴涵着的光明与希望——将重新构成一个不仅仅只是能量源泉的事物……或许，它们将构成一个国家的灵魂。', `MaleText_loc5`='隨著時間，其中的聖光與希望 - 將不只是力量的源泉，而會讓更多事物獲得重生...或許，它們也能讓一個國家的靈魂重生。', `MaleText_loc7`='Con el tiempo, la luz y la esperanza que contiene renacerán para ser más que esta simple fuente de poder... Quizá revivan el alma de una nación.' WHERE `ID`=25412;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='축복받은 조상님들이여! 느껴집니다... 크나큰 사랑이... 넘치는 은총이! 도저히... 말로 표현할 수가 없어요...', `FemaleText_loc4`='多么神圣的灵魂！我感觉到……那么博爱……那么高贵……这……不是语言可以形容的……', `FemaleText_loc5`='讚美先祖!我感覺到了...那麼多的愛...那麼多的慈悲...沒有...言語...可以形容...', `FemaleText_loc7`='¡Benditos antepasados! Lo siento... tanto amor... tanta gracia... no hay... palabras... es imposible describirlo...' WHERE `ID`=25413;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구원일세, 젊은이. 우리 모두를 감싸 안는...', `MaleText_loc4`='救赎，孩子。它在等待着我们所有人。', `MaleText_loc5`='救贖，孩子。它在等待著我們所有人。', `MaleText_loc7`='La salvación, joven. Es lo que nos espera a todos.' WHERE `ID`=25414;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕히...', `MaleText_loc4`='再见。', `MaleText_loc5`='再見...', `MaleText_loc7`='Adiós...' WHERE `ID`=25415;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='광석 수레의 제동장치가 풀리자 선로에서 날카로운 마찰음이 들립니다.', `MaleText_loc4`='被放开的矿车在铁轨上移动起来，发出“吱吱”声。', `MaleText_loc5`='夾雜著與鐵軌摩擦的嘎嘎聲，礦車動了。', `MaleText_loc7`='La vagoneta de mena cruje contra los raíles al soltarla.' WHERE `ID`=25416;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='낙담하지 마십시오. 이런 일을 겪어도 실버문은 굳건히 서 있을 것입니다.', `MaleText_loc4`='别灰心丧气。即使是发生了这样一系列事件，银月城依然会保持强大的。', `MaleText_loc5`='別灰心。銀月將會在這場事件中保持堅強。', `MaleText_loc7`='No te desmoralices. Lunargenta permanecerá fuerte a lo largo del curso de estos acontecimientos.' WHERE `ID`=25417;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야수 기술 습득 취소', `MaleText_loc4`='遗忘宠物天赋', `MaleText_loc5`='解除寵物的訓練', `MaleText_loc7`='Desentrenar mascota.', `FemaleText_loc1`='야수 기술 습득 취소', `FemaleText_loc4`='遗忘宠物天赋', `FemaleText_loc5`='解除寵物的訓練', `FemaleText_loc7`='Desentrenar mascota.' WHERE `ID`=25418;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 보유한 모든 야수의 특성을 취소하여 다른 특성을 가르치게 해 드릴 수 있습니다.$b$b야수에게 가르친 기술을 취소할 때마다 돈이 더 많이 듭니다.', `MaleText_loc4`='我可以清除宠物的所有天赋，这样你可以重新教给它。$B$B不过每次的价格都会变得越来越贵。', `MaleText_loc5`='我可以消除你寵物的所有天賦，讓你可以重新教導牠。$b$b你每進行一次所需的費用都會變得更貴。', `MaleText_loc7`='Puedo borrar todos los talentos de tu mascota para que puedas enseñarle otros nuevos.$B$BEste proceso es más caro cada vez que lo repites.', `FemaleText_loc1`='당신이 보유한 모든 야수의 특성을 취소하여 다른 특성을 가르치게 해 드릴 수 있습니다.$b$b야수에게 가르친 기술을 취소할 때마다 돈이 더 많이 듭니다.', `FemaleText_loc4`='我可以清除宠物的所有天赋，这样你可以重新教给它。$B$B不过每次的价格都会变得越来越贵。', `FemaleText_loc5`='我可以消除你寵物的所有天賦，讓你可以重新教導牠。$b$b你每進行一次所需的費用都會變得更貴。', `FemaleText_loc7`='Puedo borrar todos los talentos de tu mascota para que puedas enseñarle otros nuevos.$B$BEste proceso es más caro cada vez que lo repites.' WHERE `ID`=25419;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='습득한 야수 기술을 모두 취소합니다.', `MaleText_loc4`='确认遗忘宠物天赋', `MaleText_loc5`='確認解除寵物的訓練', `MaleText_loc7`='Confirmar desentrenar mascota.', `FemaleText_loc1`='습득한 야수 기술을 모두 취소합니다.', `FemaleText_loc4`='确认遗忘宠物天赋', `FemaleText_loc5`='確認解除寵物的訓練', `FemaleText_loc7`='Confirmar desentrenar mascota.' WHERE `ID`=25420;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 젊은 투스카르는 익사가 아니라 전투 중에 살해당한 것 같습니다.', `MaleText_loc4`='这名年轻的海象人似乎经历过一场激烈的打斗，不像是淹死的。', `MaleText_loc5`='這頭年輕的巨牙海民看起來是戰死的，而不是溺死的。', `MaleText_loc7`='Este joven colmillarr parece haber muerto en combate en vez de ahogado.' WHERE `ID`=25421;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<시체를 뒤져 이슬리루크의 토템을 찾습니다.>', `MaleText_loc4`='<在尸体上寻找伊斯利鲁克的图腾。>', `MaleText_loc5`='<在屍體中尋找依斯里魯克的圖騰。>', `MaleText_loc7`='<Busca el tótem de Issliruk en el cadáver.>', `FemaleText_loc1`='<시체를 뒤져 이슬리루크의 토템을 찾습니다.>', `FemaleText_loc4`='<在尸体上寻找伊斯利鲁克的图腾。>', `FemaleText_loc5`='<在屍體中尋找依斯里魯克的圖騰。>', `FemaleText_loc7`='<Busca el tótem de Issliruk en el cadáver.>' WHERE `ID`=25422;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놀아줄 시간이 없다!', `MaleText_loc4`='你们只会浪费我的时间！', `MaleText_loc5`='你們只會浪費我的時間!', `MaleText_loc7`='¡Tan solo malgastáis mi tiempo!' WHERE `ID`=25423;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘을 원해! 끝없는 힘을!', `MaleText_loc4`='我的渴求是无限的！', `MaleText_loc5`='我的渴求是無限的!', `MaleText_loc7`='¡Mi hambre no conoce límites!' WHERE `ID`=25424;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래!! 나는 신이다!', `MaleText_loc4`='对，没错，我就是神！', `MaleText_loc5`='對，沒錯，我就是神!', `MaleText_loc7`='¡Sí! ¡Soy un dios!' WHERE `ID`=25425;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안돼... 더, 조금 더!', `MaleText_loc4`='不……更多，我还要更多！', `MaleText_loc5`='不...更多，我還要更多!', `MaleText_loc7`='No... ¡Más, debo conseguir más!' WHERE `ID`=25426;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무도 날 이기지 못해!', `MaleText_loc4`='我是无敌的！', `MaleText_loc5`='我所向披靡!', `MaleText_loc7`='¡Soy invencible!' WHERE `ID`=25427;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흥, 기분 전환이 됐군.', `MaleText_loc4`='别打扰我了！', `MaleText_loc5`='別打擾我了!', `MaleText_loc7`='¡Basta de distracciones!' WHERE `ID`=25428;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는... 무적이란... 말이다...', `MaleText_loc4`='我……是……无……', `MaleText_loc5`='我是...無--', `MaleText_loc7`='Soy... Inven...' WHERE `ID`=25429;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저들을 밟아줘라.', `FemaleText_loc4`='消灭他们！', `FemaleText_loc5`='殲滅他們。', `FemaleText_loc7`='Aniquiladlos.' WHERE `ID`=25430;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭔가... 잘못됐어...', `FemaleText_loc4`='这……这可不在计划……之内……', `FemaleText_loc5`='跟我計畫的...不一樣。', `FemaleText_loc7`='Esto no lo había planeado.' WHERE `ID`=25431;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어머, 끔찍해라!', `FemaleText_loc4`='噢，天啊，你们真可怕！', `FemaleText_loc5`='喔，恐怖!', `FemaleText_loc7`='¡Oh, qué horror!' WHERE `ID`=25432;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='재수가 좋았지?', `FemaleText_loc4`='天啊，你们运气怎么就这么好？', `FemaleText_loc5`='天啊，你們運氣怎麼就這麼好?', `FemaleText_loc7`='¡Qué suerte tenéis!' WHERE `ID`=25433;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이젠 화가 나는데.', `FemaleText_loc4`='现在我可真有点火了。', `FemaleText_loc5`='現在我可真有點火了。', `FemaleText_loc7`='Ahora me estoy enfadando.' WHERE `ID`=25434;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='천한 것들! 내 손으로 끝내주마!', `FemaleText_loc4`='该死的废物！看我亲自解决你们！', `FemaleText_loc5`='該死的廢物!看我親自解決你們!', `FemaleText_loc7`='¡Malditos lacayos! ¡Acabaré con ustedes yo misma!' WHERE `ID`=25435;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='시작이 좋은걸.', `FemaleText_loc4`='这就是一个好的开始。', `FemaleText_loc5`='這就是一個好的開始。', `FemaleText_loc7`='Esto es un buen comienzo.' WHERE `ID`=25436;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='몇 명 더 있지 않았나...', `FemaleText_loc4`='我发誓你们还会有更多人躺下的……', `FemaleText_loc5`='我發誓你們還會有更多人躺下的...', `FemaleText_loc7`='Hubiera jurado que erais más...' WHERE `ID`=25437;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다음엔 더 여럿이 와야겠다. 그렇지?', `FemaleText_loc4`='看样子你们要“灭团”了？', `FemaleText_loc5`='看樣子你們要「滅團」了?', `FemaleText_loc7`='Ya no queda mucho del "grupo", ¿eh?' WHERE `ID`=25438;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='혼자란 외로운 법이지.', `FemaleText_loc4`='“一”这个数字，可真令人感到孤独。', `FemaleText_loc5`='一這個數字，可真令人感到孤單。', `FemaleText_loc7`='El uno es un número tan solitario.' WHERE `ID`=25439;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 너무 시시했어.', `FemaleText_loc4`='一场完胜，绝对的完胜。', `FemaleText_loc5`='剛才，真是刺激呀。', `FemaleText_loc7`='Ha sido genial, en serio.' WHERE `ID`=25440;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='케리스트라자, 여기서 볼일은 끝났습니다. 변위의 보호막으로 보내주십시오.', `MaleText_loc4`='克莉斯塔萨，我完成了自己的使命。请送我回到永生之盾。', `MaleText_loc5`='凱瑞史卓莎，我這裡的任務完成了。請讓我返回隘境之盾。', `MaleText_loc7`='He terminado aquí, Keristrasa. Por favor, llévame de vuelta al Escudo de Tránsito.', `FemaleText_loc1`='케리스트라자, 여기서 볼일은 끝났어요. 변위의 보호막으로 보내주세요.', `FemaleText_loc4`='克莉斯塔萨，我完成了自己的使命。请送我回到永生之盾。', `FemaleText_loc5`='凱瑞史卓莎，我這裡的任務完成了。請讓我返回隘境之盾。', `FemaleText_loc7`='He terminado aquí, Keristrasa. Por favor, llévame de vuelta al Escudo de Tránsito.' WHERE `ID`=25441;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한여름 축제 이야기꾼이 당신과 이야기해보라고 했습니다.', `MaleText_loc4`='节日诗人要我来找你。', `MaleText_loc5`='節慶故事使者要我來跟你談談。', `MaleText_loc7`='El cuentacuentos del Festival me ha pedido que hable contigo.', `FemaleText_loc1`='한여름 축제 이야기꾼이 당신과 이야기해보라더군요.', `FemaleText_loc4`='节日诗人要我来找你。', `FemaleText_loc5`='節慶故事使者要我來跟你談談。', `FemaleText_loc7`='El cuentacuentos del Festival me ha pedido que hable contigo.' WHERE `ID`=25442;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대가 와주어서 기쁩니다. 이쪽 불꽃을 보시고 경의도 표했으니... 적 진영 불꽃도 파악하고, 꺼버린 다음... 한여름 축제 이야기꾼에게 돌아가 보상을 받으시면 됩니다.', `MaleText_loc4`='很高兴你能来。我想你已经很了解我们的火焰了，这些，你需要祭拜……不过，不知道你是否了解敌人的火焰……对于那些，你必须浇灭……去吧，回来以后可以向他领取奖赏。', `MaleText_loc5`='我很高興你來了。現在你了解了我們的火焰，還有榮耀火焰的事...還有敵人的火焰，以及熄滅它們的事...你可以回去找他並接受獎勵了。', `MaleText_loc7`='Entonces me alegro de que hayas venido. Ahora que ya has aprendido acerca de honrar nuestros fuegos... y acerca de apagar los de nuestros enemigos... puedes volver a verle para que te recompense.', `FemaleText_loc1`='그대가 와주어서 기뻐요. 이쪽 불꽃을 보시고 경의도 표했으니... 적 진영 불꽃도 파악하고, 꺼버린 다음... 한여름 축제 이야기꾼에게 돌아가 보상을 받으시면 된답니다.', `FemaleText_loc4`='很高兴你能来。我想你已经很了解我们的火焰了，这些，你需要祭拜……不过，不知道你是否了解敌人的火焰……对于那些，你必须浇灭……去吧，回来以后可以向他领取奖赏。', `FemaleText_loc5`='我很高興你來了。現在你了解了我們的火焰，還有榮耀火焰的事...還有敵人的火焰，以及熄滅它們的事...你可以回去找他並接受獎勵了。', `FemaleText_loc7`='Entonces me alegro de que hayas venido. Ahora que ya has aprendido acerca de honrar nuestros fuegos... y acerca de apagar los de nuestros enemigos... puedes volver a verle para que te recompense.' WHERE `ID`=25443;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대가 와주어서 기쁩니다. 이쪽 불꽃을 보고 경의도 표하셨으니... 적 진영 불꽃도 파악하고, 꺼버린 다음... 한여름 축제 이야기꾼에게 돌아가 보상을 받으십시오.', `MaleText_loc4`='很高兴你能来。我想你已经很了解我们的火焰了，这些，你需要祭拜……不过，不知道你是否了解敌人的火焰……对于那些，你必须浇灭……去吧，回来以后可以向他领取奖赏。', `MaleText_loc5`='我很高興你來了。現在你了解了我們的火焰，還有榮耀火焰的事...還有敵人的火焰，以及熄滅它們的事...你可以回去找他並接受獎勵了。', `MaleText_loc7`='Entonces me alegro de que hayas venido. Ahora que ya has aprendido acerca de honrar nuestros fuegos... y acerca de apagar los de nuestros enemigos... puedes volver a verle para que te recompense.', `FemaleText_loc1`='그대가 와주어서 기뻐요. 저희쪽 불꽃을 보고 경의도 표하셨으니... 적 진영 불꽃도 파악하고, 꺼버린 다음... 한여름 축제 이야기꾼에게 돌아가 보상을 받으세요.', `FemaleText_loc4`='很高兴你能来。我想你已经很了解我们的火焰了，这些，你需要祭拜……不过，不知道你是否了解敌人的火焰……对于那些，你必须浇灭……去吧，回来以后可以向他领取奖赏。', `FemaleText_loc5`='我很高興你來了。現在你了解了我們的火焰，還有榮耀火焰的事...還有敵人的火焰，以及熄滅它們的事...你可以回去找他並接受獎勵了。', `FemaleText_loc7`='Entonces me alegro de que hayas venido. Ahora que ya has aprendido acerca de honrar nuestros fuegos... y acerca de apagar los de nuestros enemigos... puedes volver a verle para que te recompense.' WHERE `ID`=25444;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한여름 축제 현자가 당신과 이야기해보라고 했습니다.', `MaleText_loc4`='节日博学者要我来找你。', `MaleText_loc5`='節慶博學大師要我來跟你談談。', `MaleText_loc7`='El maestro cultural del Festival me ha pedido que hable contigo.', `FemaleText_loc1`='한여름 축제 현자가 당신과 이야기해보라더군요.', `FemaleText_loc4`='节日博学者要我来找你。', `FemaleText_loc5`='節慶博學大師要我來跟你談談。', `FemaleText_loc7`='El maestro cultural del Festivalme ha pedido que hable contigo.' WHERE `ID`=25445;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n! 그대가 어떻게 되었는지 궁금하던 참이었다. 왜 이렇게 오래 걸렸느냐?', `FemaleText_loc4`='$n！我一直在担心你。有事耽搁了吗？', `FemaleText_loc5`='$n!我還在想說你不知道如何了。是什麼把你絆住了?', `FemaleText_loc7`='¡$n! Me preguntaba dónde estarías. ¿Por qué te has retrasado?' WHERE `ID`=25446;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그대가 충분히 주의하고 있으리라 믿는다...$b$b이곳은 위험한 곳이고, 만약 그대에게 무슨 일이 생겼더라면 난 자신을 용서하지 못했을 것이다.', `FemaleText_loc4`='希望你已经做好了防范措施……$b$b这里非常危险，如果你出了什么事，我是不会原谅自己的。', `FemaleText_loc5`='我相信你已經做好預防措施了...$b$b這地方很危險，要是你有個三長兩短，我可無法原諒我自己。', `FemaleText_loc7`='Espero que estés tomando todas las precauciones necesarias...$B$BEste es un lugar peligroso y no podría perdóname que te ocurriera algo.' WHERE `ID`=25447;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='서둘러야 한다, $n. 더 늦으면 말리고스의 끔찍한 계획을 막을 수 없게 되리라.', `FemaleText_loc4`='$n，我们必须尽快阻止玛里苟斯。否则他的阴谋一旦得逞，就会产生毁灭性的后果。', `FemaleText_loc5`='我們一定得快點，$n。瑪里苟斯的毀滅計畫很快將無法可擋。', `FemaleText_loc7`='Debes darte prisa, $n. Los ruinosos planes de Malygos pronto serán irreversibles.' WHERE `ID`=25448;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지금과 같은 시절에는 좋은 친구가 그 무엇보다도 소중한 법이다.$b$b별일이 없길 바란다, $n. 위험하기 짝이 없는 이곳에서도 그대가 부디 무사하기를...', `FemaleText_loc4`='在动荡不安的年代，好朋友简直是无价之宝。$b$b保重，$n。尽可能地保护好自己……', `FemaleText_loc5`='在這種時候，親愛的朋友是最珍貴的。$b$b注意安全，$n。要像待在這種地方一樣的安全...', `FemaleText_loc7`='En momentos como este, los amigos de verdad son muy valiosos.$B$BMantente a salvo, $n. Tan a salvo como se pueda estar en un lugar como este...' WHERE `ID`=25449;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그대가 날 감옥에서 구해주지 않았다면, 난 지금쯤 굴복했을 것이다.$b$b나는 잊히지 않았어...', `FemaleText_loc4`='要不是你出手相助，我肯定已经死在监牢里了。$b$b我怎么都忘不了……', `FemaleText_loc5`='要不是你從監獄中救出我，我現在肯定已經死了。$b$b我並沒有忘記...', `FemaleText_loc7`='Si no me hubieras rescatado de aquella prisión, probablemente habría sucumbido ya.$b$bNo lo he olvidado...' WHERE `ID`=25450;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자비를 베풀지 마라! 투스카르는 한 놈도 남기지 말고 모두 죽여라!', `MaleText_loc4`='别心软！杀光海象人！', `MaleText_loc5`='手下不要留情!殺光所有巨牙海民!', `MaleText_loc7`='¡No tengáis piedad! ¡Matad hasta el último de los colmillarr!' WHERE `ID`=25451;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이곳에서 우리 임무가 끝나면, 날 구해준 그대에게 반드시 보답하겠노라.', `FemaleText_loc4`='当我们完成使命后，会设法报答你的救命之恩的。', `FemaleText_loc5`='等我們在這的職責解決，我會好好酬謝你的救命之恩。', `FemaleText_loc7`='Cuando hayamos acabado nuestro cometido aquí, encontraré un modo de recompensarte por mi rescate.' WHERE `ID`=25452;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='천천히... 힘이 돌아오고 있노라.$b$b머지않아 내 진정한 모습을 보여줄 수 있을 것이야.', `FemaleText_loc4`='我的力量在逐渐恢复……$b$b很快你就能见识到我真正的实力。', `FemaleText_loc5`='我的力量回復了，慢慢地...$b$b我希望很快就能夠讓你見識到我真實樣貌的榮耀。', `FemaleText_loc7`='Recupero mis fuerzas poco a poco...$B$BEspero poder mostrarte la gloria de mi verdadera forma pronto.' WHERE `ID`=25453;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싸워라, 크발디르! 카스칼라를 완전히 태워버려라!', `MaleText_loc4`='战斗吧，克瓦迪尔！将卡斯卡拉夷为平地！', `MaleText_loc5`='進攻，科瓦迪爾!將卡斯卡拉燒到寸草不留!', `MaleText_loc7`='¡Seguid luchando, Kvaldir! ¡Reduciremos Kashala a cenizas!' WHERE `ID`=25454;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='투스카르 녀석이 지금까지 본 건 아무것도 아니다! 우리의 힘을 똑똑히 보여줘라!', `MaleText_loc4`='海象人还没见识过我们的力量呢！让他们尝尝厉害！', `MaleText_loc5`='這些巨牙海民什麼都不懂!讓他們見識一下我們的能力!', `MaleText_loc7`='¡Estos colmillarr no han visto nada! ¡Mostradles de qué somos capaces!' WHERE `ID`=25455;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽여라! 모두 죽여!', `MaleText_loc4`='杀！把他们统统杀光！', `MaleText_loc5`='殺掉他們!殺光他們!', `MaleText_loc7`='¡Matadlos! ¡Matadlos a todos!' WHERE `ID`=25456;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아... $b$b여기는 어디지?', `FemaleText_loc4`='噢……$b$b我在哪儿？', `FemaleText_loc5`='唔...$b$b這是哪?', `FemaleText_loc7`='Oh...$b$b¿Dónde estoy?' WHERE `ID`=25457;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한마디로 말해, 마법이다.$b$b짧은 생을 사는 무책임한 필멸자들은 자신의 행동이 얼마나 오랫동안 영향을 미치는지 알지 못하니라.$b$b비전 에너지는 너무 무분별하게 사용되었고, 그 때문에 세계의 균형이 흐트러지고 있다. 이 상태가 계속된다면 아제로스는 곧 멸망하리니.$b$b적어도 이 사실에 대해서는 양쪽 모두가 공감하고 있다. 하지만 의회에서 결정을 내리기도 전에, 말리고스는 자신만의 계획을 실행에 옮기기 시작했다.$b$b이제 우리는 그에게 맞서 싸울 수밖에 없노라.', `MaleText_loc4`='简言之，就是魔法。$b$b凡人的生命如此短暂，他们从不考虑自己的行为可能会造成怎样的长远影响。$b$b过于活跃的奥术能量严重影响了世界的稳定。如果听之任之的话，艾泽拉斯世界迟早会被毁灭。$b$b对于这一点，我们已经达成了共识。可还没等我们组织起专门的议会，玛里苟斯就擅自采取了行动。$b$b我们别无选择，只能与他作战。', `MaleText_loc5`='簡而言之，魔法。$b$b不負責任的凡人們在他們短暫的生命裡毫不考慮自身行動所帶來的永續後果。$b$b秘法能量被過度抽取，逐漸破壞世界的平衡。如果這種情形繼續下去，艾澤拉斯很快的就會滅亡了。$b$b關於這件事，雙方都同意了。但在來得及舉行議會之前，瑪里苟斯已經開始把他的計畫付諸實行。$b$b我們別無選擇，只有與他正面衝突。', `MaleText_loc7`='En una sola palabra: magia.$B$BLos irresponsables mortales con sus cortas vidas no piensan en los efectos a largo plazo de sus acciones.$B$BLas energías Arcanas han sido liberadas de forma demasiado liberal, desbaratando el equilibrio del mundo. Si esto sigue así, Azeroth pronto será aniquilado.$B$BAmbas partes están de acuerdo en esto. Pero antes de que se pudiera planear un concilio, Malygos puso en marcha su plan.$B$BNo hemos tenido más elección que enfrentarnos a él.' WHERE `ID`=25458;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말리고스가 누굽니까?', `MaleText_loc4`='玛里苟斯是谁？', `MaleText_loc5`='誰是瑪里苟斯?', `MaleText_loc7`='¿Quién es Malygos?', `FemaleText_loc1`='말리고스가 누군가요?', `FemaleText_loc4`='玛里苟斯是谁？', `FemaleText_loc5`='誰是瑪里苟斯?', `FemaleText_loc7`='¿Quién es Malygos?' WHERE `ID`=25459;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 행동을 시작했다, $r|1이여;여;. 하지만 진행 속도가 너무나도 느리구나.', `MaleText_loc4`='$r，我们取得了一些进展，但还是太慢了。', `MaleText_loc5`='我們進步了，$r，不過速度還是太慢。', `MaleText_loc7`='Estamos progresando, $r, pero demasiado despacio.' WHERE `ID`=25460;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 반드시 성공해야 한다! 아제로스의 운명이 경각에 처했노라...', `MaleText_loc4`='我们不能失败！艾泽拉斯世界的命运就维系在这脆弱的平衡上……', `MaleText_loc5`='我們一定要成功!艾澤拉斯的命運危在旦夕...', `MaleText_loc7`='¡Tenemos que lograrlo! El destino de Azeroth depende de ello...' WHERE `ID`=25461;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말리고스는 마법의 지배자이자 푸른용군단의 수장이니라. 그는 푸른용의 위상이고, 아제로스에서 가장 오래된 존재 중 하나이지.$b$b수천 년 동안 그를 지배하던 광기에서 말리고스가 회복되고 있다는 말도 있지만, 최근 행적을 보면 아직도 광기에서 벗어나지 못한 것이 분명하다.$b$b이 진퇴양난의 상황을 해결하고자 그가 내놓은 해결책이란, 아제로스에서 마법을 사용하는 모든 존재를 찾아내서 말살하는 것이니라.$b$b붉은용군단은 생명의 수호자로서 행동을 개시할 수밖에 없게 되었다.$b$b이제 용족과 용족이 싸운다. 이 연약한 세상의 운명 또한 경각에 달렸노라.', `MaleText_loc4`='魔法之王玛里苟斯是蓝龙军团的统帅。作为蓝龙守护者，他是艾泽拉斯世界最古老的生物之一。$b$b据说他已经从数千年来的疯狂中觉醒，可是他最近的行为表明他远没有恢复理智。$b$b对于我们的困境，他竟然决定以摧毁艾泽拉斯世界所有施法者的方式来解决。$b$b生命守护者红龙不得不采取行动。$b$b蓝龙军团和红龙军团展开了一场激战，世界的命运，就取决于那脆弱的平衡。', `MaleText_loc5`='『織法者』瑪里苟斯，魔法之王，藍龍軍團的主人。他是藍龍的守護巨龍，艾澤拉斯最古老的生物之一。$b$b傳說他已從持續億萬年的瘋狂中甦醒，但從他最近的行徑看來，我相信他還是瘋的。$b$b他解決我們困境的方法就是將艾澤拉斯之中所有行始魔法的凡人找出來並殺光。$b$b作為生命的守護者，此舉迫使紅龍軍團展開行動。$b$b龍與龍之間現在相互對抗，而我們脆弱世界的命運正危在旦夕。', `MaleText_loc7`='Malygos el Tejehechizos, el Señor de la magia, maestro del Vuelo Azul. Es el Aspecto dragón Azul, una de las criaturas más antiguas de Azeroth.$B$BDicen que se está recuperando de una locura que ha durado milenios, pero sus acciones recientes me hacen pensar que aún no está cuerdo.$B$BLa solución que propone para nuestro problema es buscar y matar a todos los mortales de Azeroth que usen la magia.$B$BAl ser el guardián de la vida, el Vuelo Rojo se ha visto obligado a entrar en acción.$B$BAhora un dragón lucha contra otro y el destino de nuestro frágil mundo depende del resultado.' WHERE `ID`=25462;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다시 만나서 기쁘군요, 라엘로라즈.', `FemaleText_loc4`='莱洛拉斯，很高兴能再见到你。', `FemaleText_loc5`='瑞洛拉茲，很高興又見到你了。', `FemaleText_loc7`='Raelorasz, me alegra volver a verte.' WHERE `ID`=25463;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='케리스트라자! 상황이 더 좋았더라면 환영식이라도 해줄 텐데. 그대를 돌려준 운명에 깊이 감사하오.', `MaleText_loc4`='克莉斯塔萨！要不是局势恶劣，我真希望为你举行欢迎仪式。你平安地回来了，命运真是仁慈。', `MaleText_loc5`='凱瑞史卓莎!我希望情況可允許以更適當的方式歡迎你。命運是慈悲的，讓你得以回到我們身邊。', `MaleText_loc7`='¡Keristrasza! Desearía que las circunstancias nos permitieran darte una bienvenida más apropiada. El destino ha sido amable al devolverte a nosotros.' WHERE `ID`=25464;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대가 돌아오게 해 준 운명에 진정으로 감사하오.', `MaleText_loc4`='你平安地回来了，命运真是仁慈。', `MaleText_loc5`='命運是慈悲的，讓你得以回到我們身邊。', `MaleText_loc7`='El destino ha sido amable al devolverte a nosotros.' WHERE `ID`=25465;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='운명은 우리에게 더 감사할 일을 베풀고 있답니다. 말리고스는 지금 아끼던 것을 잃었습니다. 만약 그 사실을 깨달으면, 그는 안전한 마력의 탑 밖으로 나올 게 분명해요.', `FemaleText_loc4`='我们得到了命运的青睐。玛里苟斯遭受了沉重的打击。当他清楚地认识到眼前的局势之后，肯定不甘心龟缩在相对安全的魔枢。', `FemaleText_loc5`='命運，看起來不只是慈悲而已。一擊就擊垮瑪里苟斯。當他得到消息時，我相信他將會讓奧核之心保持安然無恙。', `FemaleText_loc7`='Parece que el destino ha sido más que amable. Se ha asestado un duro golpe a Malygos. Espero que cuando se entere abandone la seguridad de El Nexo.' WHERE `ID`=25466;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말리고스가... 모습을 드러낸다고? 이런 기회가 올 것이라고는 꿈도 꾸지 못했소. 당장 우리 동족을 소집하겠소!', `MaleText_loc4`='玛里苟斯——现身？天大的好机会啊。我这就去召集同胞！', `MaleText_loc5`='瑪里苟斯 - 弱點大開?這種機會我連想都不敢想。我馬上召集弟兄們!', `MaleText_loc7`='¿Malygos? ¿Al descubierto? Jamás hubiera soñado con una oportunidad como esta. Reuniré a nuestros hermanos inmediatamente.' WHERE `ID`=25467;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론이오, 그대여. 그럼 우리가 다시 만나는 날까지...', `MaleText_loc4`='当然，女王。再见……', `MaleText_loc5`='當然，我的女士。直到我們再次見面之前...', `MaleText_loc7`='Por supuesto, mi señora. Hasta la próxima...' WHERE `ID`=25468;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='준비를 단단히 시키세요, 라엘로라즈. 말리고스의 힘은 지금까지 본 그 어떤 것과도 다릅니다. 작전이 성공한다 해도 그의 계획을 다소 지연하는 정도에 지나지 않을 거예요.', `FemaleText_loc4`='莱洛拉斯，让他们做好准备吧。他们从未见识过玛里苟斯的力量。这次行动恐怕也只能暂缓他的计划。', `FemaleText_loc5`='叫他們準備好，瑞洛拉茲。瑪里苟斯的力量是他們從未見識過的強大。我們可能只能用聲東擊西的方法來拖延他的計畫。', `FemaleText_loc7`='Prepáralos bien, Raelorasz. El poder de Malygos no se parece a nada que hayan visto antes. Esta distracción tan solo servirá para retrasar sus planes.' WHERE `ID`=25469;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 미소를 짓습니다.', `FemaleText_loc4`='%s笑了。', `FemaleText_loc5`='%s露出笑容', `FemaleText_loc7`='%s sonríe' WHERE `ID`=25471;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='라엘로라즈, 안녕히.', `FemaleText_loc4`='再见，莱洛拉斯。', `FemaleText_loc5`='再見了，瑞洛拉茲。', `FemaleText_loc7`='Adiós, Raelorasz.' WHERE `ID`=25472;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기다려라, 친애하는 $n. 아직 때가 이르다. 곧 신호탄을 다시 쏘아 올릴 때가 오리니, 그때 시작해라...', `MaleText_loc4`='$n，耐心点。时机尚未成熟。火焰腾起之后我们再动手……', `MaleText_loc5`='耐心點，$g寶貝:親愛的;$n。時間點不太適合。趕快點燃照明彈，我們就可以開始...', `MaleText_loc7`='Paciencia, $gquerido:querida; $n. Aún no es el momento. Vuelve a lanzar la bengala pronto y comenzaremos...', `FemaleText_loc1`='기다려라, 친애하는 $n. 아직 때가 이르다. 곧 신호탄을 다시 쏘아 올릴 때가 오리니, 그때 시작해라...', `FemaleText_loc4`='$n，耐心点。时机尚未成熟。火焰腾起之后我们再动手……', `FemaleText_loc5`='耐心點，$g寶貝:親愛的;$n。時間點不太適合。趕快點燃照明彈，我們就可以開始...', `FemaleText_loc7`='Paciencia, $gquerido:querida; $n. Aún no es el momento. Vuelve a lanzar la bengala pronto y comenzaremos...' WHERE `ID`=25473;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가까이 오너라, $n. 그대에게 안 좋은 일이 생긴다면 나는 견딜 수 없을 것이다.', `FemaleText_loc4`='跟紧我，$n。我不能让你受到任何伤害。', `FemaleText_loc5`='待在我身邊，$n。我不能讓你受到任何傷害。', `FemaleText_loc7`='Mantente cerca de mí, $n. No podría soportar que te ocurriera algo.' WHERE `ID`=25474;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='말리고스!', `FemaleText_loc4`='玛里苟斯！！', `FemaleText_loc5`='瑪里苟斯!!', `FemaleText_loc7`='¡¡MALYGOS!!' WHERE `ID`=25475;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너의 소중한 배우자는 너를 실망시켰다. 이제 네가 파멸할 차례다!', `FemaleText_loc4`='你的配偶已经完蛋了。下一个就轮到你了！', `FemaleText_loc5`='你心愛的配偶已經失敗了。下一個死的就是你!', `FemaleText_loc7`='Tu preciada consorte te ha fallado. ¡Tú serás el próximo en caer!' WHERE `ID`=25476;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오너라, 마법의 지배자여. 와서 되살릴 수 있을지 보아라...', `FemaleText_loc4`='来吧，魔法之王，夺回你亲爱的配偶……', `FemaleText_loc5`='來吧，魔法之王，復活你心愛的配偶...', `FemaleText_loc7`='Ven, señor de la magia, y recupera a tu preciosa consorte...' WHERE `ID`=25477;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='...네 소중한 배우자의 시체를 말이다!', `FemaleText_loc4`='……夺回她的尸体吧！', `FemaleText_loc5`='...剩餘的部分吧!', `FemaleText_loc7`='¡... lo que queda de ella!' WHERE `ID`=25478;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가자, $n|1이여;여;. 우리의 노력이 어떤 결실을 보았는지 확인하자꾸나.', `FemaleText_loc4`='跟我来，$n。让我们瞧瞧目前取得的成果。', `FemaleText_loc5`='來吧，$n。我們來瞧瞧努力的成果。', `FemaleText_loc7`='Ven, $n. Observemos los frutos de nuestro esfuerzo.' WHERE `ID`=25479;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사라고사? 도대체 무슨 일이 생긴 거요?', `MaleText_loc4`='莎拉苟萨？你怎么了？', `MaleText_loc5`='薩拉苟莎!你怎麼了?', `MaleText_loc7`='¿Saragosa? ¿Qué te ha pasado?' WHERE `ID`=25480;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나와 함께 가자꾸나. 이곳은 안전하지 않다.', `FemaleText_loc4`='跟我来。这里不安全。', `FemaleText_loc5`='跟我走。這裡不安全。', `FemaleText_loc7`='Ven conmigo. Este lugar no es seguro.' WHERE `ID`=25481;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자다! 성소에 발을 들이지 못하게 해라!', `MaleText_loc4`='入侵者！别让他们进入圣殿！', `MaleText_loc5`='入侵者!別讓他們進入聖所!', `MaleText_loc7`='¡Intrusos! ¡No dejéis que entren en el Sagrario!' WHERE `ID`=25482;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피조물들이여, 목숨을 걸고 수도를 방어하라!', `MaleText_loc4`='构造体，要不惜一切代价保住我们的主城！', `MaleText_loc5`='傀儡們，全力保衛主城!', `MaleText_loc7`='¡Ensamblajes, defended la capital cueste lo que cueste!' WHERE `ID`=25483;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싸워라, 아이들아! 한 치도 봐주지 마라!', `MaleText_loc4`='战斗吧，孩子们！不要对敌人心软！', `MaleText_loc5`='戰鬥，我的孩子們!讓敵人知道什麼叫生不如死!', `MaleText_loc7`='¡A la batalla, mis pequeños! ¡No mostréis piedad al enemigo!' WHERE `ID`=25484;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='케리스트라자! 네가 내 짝을 능가했군... 그렇다면 네가 그 자리를 대신해 줘야겠다!', `MaleText_loc4`='克莉斯塔萨！你杀死了我的配偶……那就由你来代替她吧！', `MaleText_loc5`='凱瑞史卓莎!你打敗了我的配偶...而現在，「你」將取代她的位置!', `MaleText_loc7`='¡Keristrasza! ¡Has ganado a mi consorte... y ahora TÚ ocuparás su lugar!' WHERE `ID`=25485;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영주님을 위하여! 로켄을 위하여!', `MaleText_loc4`='为了领主！为了洛肯！', `MaleText_loc5`='為了族長!為了洛肯!', `MaleText_loc7`='¡Por el señor feudal! ¡Por Loken!' WHERE `ID`=25486;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바위의 후손을 뭉개버려라, 무쇠 형제들아!', `MaleText_loc4`='同胞们，消灭岩石的子嗣！', `MaleText_loc5`='打碎這些石之子，我的鐵弟兄們!', `MaleText_loc7`='¡Aplastad a los hijos de la piedra, mis férreos hermanos!' WHERE `ID`=25487;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 그만! 네가 내 짝을 능가했군... 그렇다면 네가 그 자리를 대신해 줘야겠다!', `MaleText_loc4`='够了！你杀死了我的配偶……那就由你来代替她吧！', `MaleText_loc5`='夠了!你已經打敗我的配偶...現在「你」將取代她的位置!', `MaleText_loc7`='¡Basta! ¡Has ganado a mi consorte... y ahora TÚ ocuparás su lugar!' WHERE `ID`=25488;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='절대 그럴 수 없다!', `FemaleText_loc4`='休想！', `FemaleText_loc5`='絕不!', `FemaleText_loc7`='¡Nunca!' WHERE `ID`=25489;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무쇠의 자식들의 만행도 이걸로 끝이다!', `MaleText_loc4`='钢铁的暴政到头了！', `MaleText_loc5`='鐵的暴行終將結束!', `MaleText_loc7`='¡La tiranía del hierro está a punto de terminar!' WHERE `ID`=25490;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='서둘러라, $n! 어서 도망치거라! 살아남아서, 여기서 시작한 일을 끝내거라...', `FemaleText_loc4`='快跑，$n！快！你必须活下去，完成我们未竟的事业……', `FemaleText_loc5`='快點，$n!快點逃!要活下去完成我們在這裡起頭的事情...', `FemaleText_loc7`='¡Date prisa, $n!' WHERE `ID`=25491;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 주인은 절대 우리를 지배하지 못한다!', `MaleText_loc4`='你的主子永远别想征服岩石！', `MaleText_loc5`='你們的主人永遠都無法征服石頭!', `MaleText_loc7`='¡Sus maestros nunca conquistarán la piedra!' WHERE `ID`=25492;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로켄은 절대 승리할 수 없다!', `MaleText_loc4`='洛肯必将失败！', `MaleText_loc5`='洛肯永遠不會獲勝!', `MaleText_loc7`='¡Loken nunca triunfará!' WHERE `ID`=25493;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 너 따윈 두려워하지 않는다, 이 무쇠 자식아!', `MaleText_loc4`='我们才不怕你呢。来啊，钢铁的子嗣！', `MaleText_loc5`='我們並不怕你，鐵之子!', `MaleText_loc7`='¡No os tememos, hijos del hierro!' WHERE `ID`=25494;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으아!! 난 이제 말리고스의 노예가 아니다! 덤벼라, 끝장을 내주마!', `MaleText_loc4`='啊！我不再是玛里苟斯的奴隶了！所有挑战我的人都要被消灭！', `MaleText_loc5`='啊!!我不再是瑪里苟斯的奴隸了!所有挑戰我的人都要被消滅!', `MaleText_loc7`='¡Aggh! ¡Ya no seré un esclavo de Malygos! ¡Retenme y serán destruidos!' WHERE `ID`=25496;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 쓸어 주마.', `MaleText_loc4`='我要净化你们！', `MaleText_loc5`='我要淨化你們!', `MaleText_loc7`='¡Los purgaré!' WHERE `ID`=25497;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정한 고통은 이제 시작이다!', `MaleText_loc4`='你们的痛楚才刚开始！', `MaleText_loc5`='你們的痛楚才剛開始!', `MaleText_loc7`='¡Su dolor no ha hecho más que comenzar!' WHERE `ID`=25498;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='킬제덴의 이름으로!', `MaleText_loc4`='以基尔加丹的名义！', `MaleText_loc5`='以基爾加丹的名義!', `MaleText_loc7`='¡En el nombre de Kil''jaeden!' WHERE `ID`=25499;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 이미 경고했다!', `MaleText_loc4`='我警告过你们了！', `MaleText_loc5`='我早就警告過你了。', `MaleText_loc7`='¡Estabas avisado!' WHERE `ID`=25500;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 완전히 깨어났다! 모두 없애 주마!', `MaleText_loc4`='我的觉醒已经完成了！你们的死期到了！', `MaleText_loc5`='我已經完全地覺醒了!你們的死期到了!', `MaleText_loc7`='¡Mi despertar se ha completado! ¡Morirán!' WHERE `ID`=25501;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='킬제덴을 막아야 합니다!', `MaleText_loc4`='必须立刻消灭基尔加丹！', `MaleText_loc5`='必須立刻消滅基爾加丹!', `MaleText_loc7`='¡Kil’jaeden debe ser destruido!' WHERE `ID`=25502;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세계의 운명이 여러분께 달렸습니다!', `MaleText_loc4`='这个世界危在旦夕！', `MaleText_loc5`='這個世界危在旦夕!', `MaleText_loc7`='¡El destino de este mundo está en juego!' WHERE `ID`=25503;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무도 널 도울 수 없어! 내 할 일이 거의 끝나 간다!', `MaleText_loc4`='已经来不及了！我的工作马上就要完成了！', `MaleText_loc5`='已經來不及了!我的工作馬上就要完成了!', `MaleText_loc7`='¡No habrá indulto! ¡Ya casi he terminado mi labor aquí!' WHERE `ID`=25504;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는... 절대... 지지 않는다!', `MaleText_loc4`='我绝不会落到……输的……那一边。', `MaleText_loc5`='我絕不會落到...輸的...那一邊!', `MaleText_loc7`='¡Yo... nunca... pierdo!' WHERE `ID`=25505;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 고통은 내 행복이지!', `MaleText_loc4`='你的痛苦就是我的欢乐！', `MaleText_loc5`='我以你的悲慘為樂!', `MaleText_loc7`='¡Me deleito en su miseria!' WHERE `ID`=25506;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피를 보고야 말겠다.', `MaleText_loc4`='我就要这么看着你流血！', `MaleText_loc5`='我要你見血!', `MaleText_loc7`='¡Miraré mientras sangráis!' WHERE `ID`=25507;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가련한 필멸자여!', `MaleText_loc4`='可悲的凡人！', `MaleText_loc5`='可悲的凡人!', `MaleText_loc7`='¡Penoso mortal!' WHERE `ID`=25508;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말하지 않았나? 나는 항상 이긴다!', `MaleText_loc4`='没听说过吗？我永远属于赢的一方！', `MaleText_loc5`='沒聽說過嗎?我永遠屬於贏的一方!', `MaleText_loc7`='¿No te has enterado? ¡Yo siempre gano!' WHERE `ID`=25509;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장난은 이걸로 끝이다!', `MaleText_loc4`='很好，我已经把你们玩够了！', `MaleText_loc5`='很好，我已經把你們玩夠了!', `MaleText_loc7`='¡Basta ya de juegos!' WHERE `ID`=25510;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='타락... 증오... 혼돈... 이는 본질이리라.', `FemaleText_loc4`='背叛……憎恨……混乱，这是一切的支柱。', `FemaleText_loc5`='墮落...憎恨...混亂。這是一切的支柱。', `FemaleText_loc7`='Depravación... odio... caos. Estos son los pilares.' WHERE `ID`=25511;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고통... 혼란... 의심... 이는 형상이며.', `FemaleText_loc4`='痛楚……迷惑……猜忌，这是一切的基石。', `FemaleText_loc5`='痛楚...迷惑...猜忌，這是一切的基石。', `FemaleText_loc7`='Miseria... confusión... recelo. Estas son las señales.' WHERE `ID`=25512;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='불꽃이 어둠을 돋우리라!', `FemaleText_loc4`='阴影将在火焰下存在！', `FemaleText_loc5`='陰影將在火焰下存在!', `FemaleText_loc7`='¡Fuego para ayudar a las sombras!' WHERE `ID`=25513;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='불꽃이 너를 태운다.', `FemaleText_loc4`='火焰将你吞噬！', `FemaleText_loc5`='火焰吞噬。', `FemaleText_loc7`='¡El fuego consume!' WHERE `ID`=25514;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='에딜 하라크!', `FemaleText_loc4`='Edir harach！', `FemaleText_loc5`='(惡魔語)火焰將你吞噬!', `FemaleText_loc7`='¡Edir harach!' WHERE `ID`=25515;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사크로래쉬!', `FemaleText_loc4`='萨洛拉丝！', `FemaleText_loc5`='莎珂蕾希!', `FemaleText_loc7`='¡Sacrolash!' WHERE `ID`=25516;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네 운은 이제 다했다!', `FemaleText_loc4`='你们的好运到此为止了！', `FemaleText_loc5`='你們的好運到此為止了!', `FemaleText_loc7`='¡Su racha de suerte ha acabado!' WHERE `ID`=25517;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='데레크... 마눌...', `FemaleText_loc4`='Der''ek……manul。', `FemaleText_loc5`='(惡魔語)我的火焰...熄滅了。', `FemaleText_loc7`='Der''ek... manul.' WHERE `ID`=25518;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어둠이 너를 삼킨다.', `FemaleText_loc4`='暗影将你包围。', `FemaleText_loc5`='暗影將你包圍。', `FemaleText_loc7`='Las sombras engullen.' WHERE `ID`=25519;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이낙 크레율!', `FemaleText_loc4`='Ee-nok Kryul！', `FemaleText_loc5`='(惡魔語)暗影將你包圍!', `FemaleText_loc7`='¡Ee-nok Kryul!' WHERE `ID`=25520;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너희에게 시간이란 사치품이다!', `FemaleText_loc4`='时间，这是你永远也无法拥有的奢侈之物。', `FemaleText_loc5`='時間是你無法再擁有的奢侈品!', `FemaleText_loc7`='¡El tiempo es un lujo que ya no podéis permitiros!' WHERE `ID`=25521;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내가... 희미해진다.', `FemaleText_loc4`='我……要消失了。', `FemaleText_loc5`='我...消失。', `FemaleText_loc7`='Me... desvanezco.' WHERE `ID`=25522;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='와주셔서 기쁘군요, $c님. 태양샘 고원은 지금 군사적으로 상황이 꽤 좋지 않습니다.', `FemaleText_loc4`='我真高兴能在这里看见你，$c。目前太阳之井高地一带的战略状况非常糟糕。', `FemaleText_loc5`='我很慶幸有你在這裡，$c。太陽之井高地的戰況相當糟。', `FemaleText_loc7`='Me alegra que estés aquí, $c. La situación militar en la Meseta de La Fuente del Sol es bastante desalentadora.' WHERE `ID`=25523;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상황 보고서를 보여 주십시오, 대장님.', `MaleText_loc4`='报告全部状况，上尉。', `MaleText_loc5`='上尉，請給我一份戰況報告。', `MaleText_loc7`='Infórmeme acerca de la situación, Capitana.', `FemaleText_loc1`='상황 보고서를 보여 주세요, 대장님.', `FemaleText_loc4`='报告全部状况，上尉。', `FemaleText_loc5`='上尉，請給我一份戰況報告。', `FemaleText_loc7`='Infórmeme acerca de la situación, Capitana.' WHERE `ID`=25524;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무너진 태양 공격대가 쿠엘다나스 섬 외곽 지역에서 상황을 크게 진척시켰습니다. 킬제덴의 군대는 밀려나는 중이며, 나는 혼란스러운 틈을 타 소규모 정찰단을 이끌고 태양샘 고원 안으로 갔습니다. 우리 부대는 무리해 광장을 통과할 때 태양칼날단 소속 블러드 엘프 무리 몇몇을 발견하고 전투를 벌였습니다. 그리고 그 전투는 곧 엄청난 재앙으로 돌변하고 말았지요.', `FemaleText_loc4`='破碎残阳目前在奎尔丹纳斯岛的外围地域进展非常良好，基尔加丹的部队正被我们逼得节节败退。此外，趁着双方掌握地域的混乱，我直接派一小支侦察部队进入了太阳之井。我的部队目前已经通过了幻日广场，还曾在那附近发现了一小队血精灵，并与之交战，结果，那场战斗很快就变成了一场灾难。', `FemaleText_loc5`='破碎之日進攻部隊在奎爾達納斯之島的外圍地區推進了一大步。基爾加丹的軍隊被逼退了，在這場混亂中我在太陽之井高地裡領導一小隊偵察軍隊。我的隊伍行進了幻日廣場，遇到了一群日刃血精靈，接著我們與敵人進行戰鬥。那場戰鬥很快的變成了一場災難。', `FemaleText_loc7`='La Ofensiva Sol Devastado ha realizado un gran progreso en las zonas exteriores de la Isla de Quel''Danas. Están rechazando a las tropas de Kil''jaeden y, en medio del caos, he logrado guiar a una pequeña fuerza de exploradores dentro de la Meseta de La Fuente del Sol. Mis tropas avanzaron a través de la Plaza del Parhelio, avistaron a un grupo de elfos de sangre Filosol y se enzarzaron en una lucha contra el enemigo. Esta lucha no tardó en convertirse en un desastre.' WHERE `ID`=25525;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐가 잘못되기라도 했습니까?', `MaleText_loc4`='发生了什么事？', `MaleText_loc5`='發生了什麼事?', `MaleText_loc7`='¿Qué es lo que ha ido mal?', `FemaleText_loc1`='뭐가 잘못되기라도 했나요?', `FemaleText_loc4`='发生了什么事？', `FemaleText_loc5`='發生了什麼事?', `FemaleText_loc7`='¿Qué es lo que ha ido mal?' WHERE `ID`=25526;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기 태양샘 고원에 있는 킬제덴 수호자들은 우리가 섬 바깥에서 마주쳤던 그 어떤 존재보다도 강력하더군요. 불타는 군단은 우리 비전 수호병 기술 체계를 악의 기운으로 왜곡시켜 훨씬 더 사악한 존재를 만들어 냈습니다. 태양칼날단 파수병 단 하나가 엄청난 수의 우리 병사를 처치하는 걸 보고는, 신속히 퇴각하라고 명령을 내렸습니다. 지금은 태양샘 고원에서 부대가 완전히 빠져나왔기를 바랍니다만, 어쨌든 적이 추격을 그만두었다는 말에는 놀라지 않을 수 없었습니다.', `FemaleText_loc4`='基尔加丹派驻在太阳井之内的卫兵远远比外面这些我们遇到过的要强大。军团将那里面的魔像全部灌入了恶魔能量能，转为他们所用。仅仅只是一只炎刃保卫者就将我派去的小队打得丢盔弃甲，我只好立刻命令他们撤退。我当时推断敌人会立刻将我的部队全部赶出高地区域，可令我吃惊的是，他们没有展开任何追击行动。', `FemaleText_loc5`='基爾加丹在太陽之井高地的防衛者比我們在島外所面對的更加強大。軍團甚至以魔化能量扭曲了我們的秘法守護者技術，製造出更為邪惡的事物。只要一隻日刃保衛者就殲滅了我的軍隊，所以我下令立時撤退。我希望我的小隊可以整個退出高地，不過敵方卻停止追擊，令我大吃一驚。', `FemaleText_loc7`='Los defensores de Kil''jaeden aquí, en La Fuente del Sol, son mucho más fuertes que cualquier cosa a la que nos hayamos enfrentado fuera de la isla. La Legión ha distorsionado nuestra tecnología de los guardianes Arcanos con energía vil para crear algo mucho más siniestro. Uno solo de esos protectores Filosol diezmó mis tropas y tuve que ordenar una retirada rápida. Esperaba que expulsaran a mi escuadrón de la isla, pero me sorprendieron dejando de perseguirnos.' WHERE `ID`=25527;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 추격을 멈추었답니까?', `MaleText_loc4`='他们为什么停下来了？', `MaleText_loc5`='為什麼他們停止追擊了呢?', `MaleText_loc7`='¿Por qué se detuvieron?', `FemaleText_loc1`='왜 추격을 멈추었나요?', `FemaleText_loc4`='他们为什么停下来了？', `FemaleText_loc5`='為什麼他們停止追擊了呢?', `FemaleText_loc7`='¿Por qué se detuvieron?' WHERE `ID`=25528;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이유는 모르겠지만, 어쨌든 추격을 그만뒀다니 기쁩니다. 이렇게 잠시 휴전하는 동안 수도자 엘바돈이 제 휘하에 있는 사람들을 많이 구해낼 수 있을 테니 말입니다. 최고 비밀 정찰단 몇 명을 앞서 보냈더니 흥미있는 몇 가지를 알려왔습니다. 거의 모든 태양칼날단 파수병의 동력이 꺼진 상태라고 합니다! 킬제덴의 군대가 동력을 절약하는 듯합니다. 게다가 파수병 하나만 작동시켜 저희를 견제할 수 있다는 점에 만족하는 것 같군요. 그대와 동료 여러분이 기어이 안으로 들어가시겠다면, 작전 계획을 하나 알려 드릴 테니 들어주셨으면 합니다.', `FemaleText_loc4`='不知道，但我对这个结果表示庆幸。他们行动上的迟缓使我有机会派出学者埃尔巴顿救下了许多小队成员。我又派出了一些擅长潜行和匿踪的斥候进去侦察了一下，他们带回了一些很有意思的消息。据说，所有的炎刃保卫者都停止运作了！基尔加丹的军队大概不想浪费它们的能量，只启动了一台炎刃保卫者用于对付我们。如果你和你的朋友想突入其中的话，就请允许我先制订一个进攻计划。', `FemaleText_loc5`='我不知道，不過我很慶幸他們這樣做。此舉讓隱士艾邦頓得以在我的指令下拯救許多人們。我已經派出了幾位密探，他們回報了幾件很有趣的事。幾乎所有的日刃保衛者的能源都變低了!基爾加丹的軍隊好像在保存他們的能量，並似乎對於只派一隻保衛者就控制我們這件事感到很滿意。如果你和你的同伴想要攻進去，請允許我提出一則攻擊計畫的建議。', `FemaleText_loc7`='No sé, pero me alegra que lo hicieran. Este respiro ha permitido al anacoreta Elbadon salvar a muchos de los hombres y mujeres que están bajo mi mando. He enviado a algunos de mis exploradores más sigilosos y me han informado de algo interesante. ¡Casi todos los protectores Filosol se han quedado sin energía! Parece que las tropas de Kil''jaeden están conservando su energía y parecen satisfechos conteniéndonos con un solo protector activo. Si tú y tus compañeros queréis entrar por la fuerza, permíteme que te sugiera un plan de ataque.' WHERE `ID`=25529;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고견을 들려주신다니 감사합니다.', `MaleText_loc4`='非常感谢你的建议。', `MaleText_loc5`='洗耳恭聽。', `MaleText_loc7`='Agradezco tu opinión.', `FemaleText_loc1`='고견을 들려주신다니 감사해요.', `FemaleText_loc4`='非常感谢你的建议。', `FemaleText_loc5`='洗耳恭聽。', `FemaleText_loc7`='Agradezco tu opinión.' WHERE `ID`=25530;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='작동 중지된 태양칼날단 파수병을 이용하십시오. 태양칼날단 정찰병이 그대를 발견하면, 근처에 있는 태양칼날단 파수병을 다시 작동시키려 할 것입니다. 그러지 못하도록 재빨리 정찰병을 처치하십시오. 그 블러드 엘프 정찰병을 처치한 다음에 파수병에 있는 근접 감지 장치를 건드리지 않으면, 싸우지 않고도 파수병 옆을 지나칠 수 있습니다. 그러면 시간과 노력을 많이 절약할 수 있을 것입니다.', `FemaleText_loc4`='你要充分利用他们那些已经关闭了的炎刃保卫者。如果被炎刃斥候发现的话，我敢肯定那些血精灵会立刻冲向最近的炎刃保卫者旁，试图启动它。你们得立刻冲上去杀了他。消灭了那些血精灵之后，只要你不激活那些保卫者的近距传感器，应该就可以安然通过，不用费力消灭它们了。这可以为你节省无数的时间和资源。', `FemaleText_loc5`='利用他們撤退的日刃保衛者。要是有日刃斥候鎖定你，我相信那位精靈將會試著重新啟動一隻附近的日刃保衛者。快速殺了他，別讓他那麼做。殺了血精靈後，只要你不啟動保衛者附近的感應器，你應該可以安全的通過他們。這麼做將可節省你的時間和資源。', `FemaleText_loc7`='Aprovechaos de sus protectores Filosol desactivados. Si alguno de sus exploradores Filosol os ve, seguro que intentará reactivar un protector Filosol cercano. Matadlo rápido para evitar eso. Tras eliminar a los elfos de sangre, siempre y cuando no activéis los sensores de proximidad de los protectores, podréis pasar sin tener que luchar. Eso os ahorrará tiempo y recursos.' WHERE `ID`=25531;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='셀라나 대장이 여기 태양샘 고원에서 고군분투하는 그대를 도우라고 하였습니다.', `MaleText_loc4`='塞拉娜上尉命令我协助你们在太阳之井高地一带的行动。', `MaleText_loc5`='賽拉娜上尉吩咐我前來協助你進行在太陽之井高地的工作。', `MaleText_loc7`='La capitana Selana me ha ordenado que colabore con tus esfuerzos aquí, en la Meseta de La Fuente del Sol.' WHERE `ID`=25532;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='태양샘 관문은 지금 어떤 상태입니까?', `MaleText_loc4`='目前太阳之井内各道门的状况怎样？', `MaleText_loc5`='太陽之井的門戶目前情況為何?', `MaleText_loc7`='¿Cuál es el estado actual de las puertas de La Fuente del Sol?', `FemaleText_loc1`='태양샘 관문은 지금 어떤 상태인가요?', `FemaleText_loc4`='目前太阳之井内各道门的状况怎样？', `FemaleText_loc5`='太陽之井的門戶目前情況為何?', `FemaleText_loc7`='¿Cuál es el estado actual de las puertas de La Fuente del Sol?' WHERE `ID`=25533;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='첫 번째 관문인 아가마스가 뚫렸습니다. 이제 가장 강력한 킬제덴 부하 중 여군주 사크로래쉬와 대흑마법사 알리테스를 공격할 수 있습니다.', `MaleText_loc4`='第一道门阿加麦斯已经被完全破坏了。基尔加丹手下的两位高级军官萨洛拉丝女王和高阶术士奥蕾塞丝已经暴露在我军的攻势之下。', `MaleText_loc5`='初始之門， 阿格瑪司已經被破壞了。基爾加丹最強大的兩個副官，莎珂蕾希女士和大術士艾黎瑟絲，現在變得有機可趁。', `MaleText_loc7`='Agamath, la primera puerta ha sido agrietada. Dos de las tenientes más poderosas de Kil''jaeden son vulnerables nuestros ataques ahora.' WHERE `ID`=25534;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세 관문 다 충분히 공략할 수 있는 상태입니다. 태양너울 항구에 있는 대마법사 네툴에게 조언을 구하고 관문을 여는 데 힘을 보태셨으면 합니다.', `MaleText_loc4`='所有三道屏障都在运转中。你可以去阳湾港口找大法师奈苏尔，协助他来解除这些屏障。', `MaleText_loc5`='三個屏障完全運作中。與位於日境港的大法師奈蘇爾商量協助開啟這些門戶的工作。', `MaleText_loc7`='Las tres barreras funcionan a la perfección. Habla con el archimago Ne''thul para ayudar a abrir las puertas.' WHERE `ID`=25535;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='첫 번째 관문인 아가마스와 두 번째 관문인 로헨도르가 파괴되었습니다. 세 번째 관문인 아르코니수스만 남았습니다.', `MaleText_loc4`='第一道门阿加麦斯和第二道门洛希多尔都已经被完全摧毁，只剩下第三道门埃库尼苏了。', `MaleText_loc5`='阿格瑪司，初始之門 以及洛罕鐸，次之門現在皆已摧毀。只剩下亞坎努斯，參之門。', `MaleText_loc7`='Agamath, la primera puerta y Rohendor, la segunda, han sido destruidas. Solo falta Archonisus, la tercera puerta.' WHERE `ID`=25536;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='태양샘으로 진입하지 못하도록 막던 모든 관문이 파괴되었습니다. 태양샘으로 들어가 킬제덴이 이 세계로 오지 못하게 막아야 합니다!', `MaleText_loc4`='所有挡在你前往太阳之井路上的魔法屏障都已经被摧毁了。前往太阳之井吧！立刻阻止基尔加丹进入这个世界！', `MaleText_loc5`='所有抵擋你進入太陽之井的屏障皆已摧毀。前進太陽之井並阻止基爾加丹進入這個世界!', `MaleText_loc7`='Todas las barreras que impedían que llegaras a La Fuente del Sol han sido destruidas. ¡Entra en La Fuente del Sol y evita que Kil''jaeden entre en este mundo!' WHERE `ID`=25537;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼렉고스가 자유롭게 되었으니 태양 향점으로 순간이동 시켜주실 수 있습니까?', `MaleText_loc4`='既然卡雷苟斯已经自由了，你能将我传送到巅峰之台吗？', `MaleText_loc5`='卡雷苟斯自由了，你能夠傳送我傳至頂尖崗哨嗎?', `MaleText_loc7`='Ahora que Kalecgos es libre, ¿puedes teletransportarme a La Cúspide?', `FemaleText_loc1`='칼렉고스가 자유롭게 되었으니 태양 향점으로 순간이동 시켜주실 수 있나요?', `FemaleText_loc4`='既然卡雷苟斯已经自由了，你能将我传送到巅峰之台吗？', `FemaleText_loc5`='卡雷苟斯自由了，你能夠傳送我傳至頂尖崗哨嗎?', `FemaleText_loc7`='Ahora que Kalecgos es libre, ¿puedes teletransportarme a La Cúspide?' WHERE `ID`=25538;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여군주 사크로래쉬와 대흑마법사 알리테스를 물리쳤으니 마녀의 성소로 순간이동 시켜줄 수 있습니까?', `MaleText_loc4`='现在萨洛拉丝女王和高阶术士奥蕾塞丝都已经被打败了，你能把我传送到巫女密室吗？', `MaleText_loc5`='現在莎珂蕾希女士和大術士艾黎瑟絲都被擊倒了，你可以傳送我至女巫聖所。', `MaleText_loc7`='Ahora que Lady Sacrolash y la Bruja suprema Alythess han sido derrotadas, ¿puedes teletransportarme al Sagrario de la Bruja?', `FemaleText_loc1`='여군주 사크로래쉬와 대흑마법사 알리테스를 물리쳤으니 마녀의 성소로 순간이동 시켜줄 수 있나요?', `FemaleText_loc4`='现在萨洛拉丝女王和高阶术士奥蕾塞丝都已经被打败了，你能把我传送到巫女密室吗？', `FemaleText_loc5`='現在莎珂蕾希女士和大術士艾黎瑟絲都被擊倒了，你可以傳送我至女巫聖所。', `FemaleText_loc7`='Ahora que Lady Sacrolash y la Bruja suprema Alythess han sido derrotadas, ¿puedes teletransportarme al Sagrario de la Bruja?' WHERE `ID`=25539;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='킬제덴에게 가는 길을 확보했습니다! 저를 태양샘 근처로 보내주실 수 있습니까?', `MaleText_loc4`='我们已经可以直接面对基尔加丹了！你能把我传送到太阳之井旁边吗？', `MaleText_loc5`='我們已經清出前往基爾加丹的路了!你可以傳送我至太陽之井附近嗎?', `MaleText_loc7`='¡Hemos despejado el camino hasta Kil''jaeden! ¿Puedes teletransportarme cerca de La Fuente del Sol?', `FemaleText_loc1`='킬제덴에게 가는 길을 확보했어요! 저를 태양샘 근처로 보내주실 수 있나요?', `FemaleText_loc4`='我们已经可以直接面对基尔加丹了！你能把我传送到太阳之井旁边吗？', `FemaleText_loc5`='我們已經清出前往基爾加丹的路了!你可以傳送我至太陽之井附近嗎?', `FemaleText_loc7`='¡Hemos despejado el camino hasta Kil''jaeden! ¿Puedes teletransportarme cerca de La Fuente del Sol?' WHERE `ID`=25540;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대들만 싸우는 게 아닙니다! 푸른용군단이 힘을 보탤 겁니다!', `MaleText_loc4`='你们并不是在孤军奋战！蓝龙军团会帮助你们消灭欺诈者！', `MaleText_loc5`='你們並不是在孤軍奮戰!藍龍軍團會幫助你們消滅欺詐者!', `MaleText_loc7`='¡No estáis solos! ¡El Vuelo Azul os ayudará a derrotar al Falsario!' WHERE `ID`=25541;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 수정구에 힘을 불어넣었습니다! 어서요!', `MaleText_loc4`='我又将能量灌入了另一颗宝珠！快去使用它！', `MaleText_loc5`='我又將能量灌入了另一顆寶珠!快去使用它!', `MaleText_loc7`='¡He otorgado mi poder a otro orbe! ¡Usadlo rápido!' WHERE `ID`=25542;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 수정구가 준비됐습니다! 서두르세요!', `MaleText_loc4`='又有一颗宝珠准备好了！快点行动！', `MaleText_loc5`='又有一顆寶珠準備好了!快點行動!', `MaleText_loc7`='¡Otro orbe preparado! ¡Daos prisa!' WHERE `ID`=25543;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 순간을 위해 모든 계획을 세웠다!', `MaleText_loc4`='我所有的计划都是为了这一刻的到来！', `MaleText_loc5`='我所有的計畫都是為了這一刻的到來!', `MaleText_loc7`='¡Todos mis planes para esto!' WHERE `ID`=25544;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정신 바짝 차려라. 시간 낭비 말고!', `MaleText_loc4`='集中注意力，不要浪费时间！', `MaleText_loc5`='集中注意力，不要浪費時間!', `MaleText_loc7`='¡Centraos, no perdáis el tiempo!' WHERE `ID`=25545;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 충분히 기다렸다!', `MaleText_loc4`='我的等待太漫长了！', `MaleText_loc5`='我的等待太漫長了!', `MaleText_loc7`='¡Ya he esperado suficiente!' WHERE `ID`=25546;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나를 실망시키면 영원히 고통받으리라!', `MaleText_loc4`='要是让我失望的话，就准备接受惩罚吧！', `MaleText_loc5`='要是讓我失望的話，就準備承受永恆的折磨吧!', `MaleText_loc7`='¡Falladme y sufriréis eternamente!' WHERE `ID`=25547;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 소녀를 빨아들여라! 빈 껍데기만 남을 때까지 힘을 모조리 빼앗아!', `MaleText_loc4`='抽取她的力量！抽空她，直到她只剩下一具空空的躯壳为止！', `MaleText_loc5`='吸乾那個女孩!吸光她的力量，直到她只剩一具空殼!', `MaleText_loc7`='¡Vaciad a la chica! ¡Drenad su poder hasta que no quede más que una cáscara vacía!' WHERE `ID`=25548;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파멸이 점점 더 가까워진다!', `MaleText_loc4`='离毁灭又近了一步！', `MaleText_loc5`='離毀滅又近了一步!', `MaleText_loc7`='¡Un paso más hacia la destrucción!' WHERE `ID`=25549;
