UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누굴 믿을 수 있겠나?', `MaleText_loc4`='你还能相信谁？', `MaleText_loc5`='你還能相信誰!', `MaleText_loc7`='¿En quién puedes confiar?' WHERE `ID`=25551;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적은 이 안에 있다!', `MaleText_loc4`='敌人就在你们中间！', `MaleText_loc5`='敵人就在你們之中!', `MaleText_loc7`='¡El enemigo está entre ustedes!' WHERE `ID`=25552;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혼돈!', `MaleText_loc4`='混乱！', `MaleText_loc5`='混亂!', `MaleText_loc7`='¡Caos!' WHERE `ID`=25553;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파괴!', `MaleText_loc4`='毁灭！', `MaleText_loc5`='毀滅!', `MaleText_loc7`='¡Destrucción!' WHERE `ID`=25554;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='망각!', `MaleText_loc4`='消亡！', `MaleText_loc5`='消亡!', `MaleText_loc7`='¡Olvido!' WHERE `ID`=25555;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일이야? 벌써 배가 고파? 걱정하지 마, 내가 귀리를 가져올게.', `MaleText_loc4`='怎么啦？你饿了吗？别担心，我来找燕麦。', `MaleText_loc5`='那是什麼，女孩?你已經餓了?別擔心，我會把燕麥弄來的。', `MaleText_loc7`='¿Qué pasa, niña? ¿Ya tienes hambre? No te preocupes, iré a por la avena.' WHERE `ID`=25556;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디 보자, 귀리 자루가 어디에 있으려나?', `MaleText_loc4`='他们把燕麦放哪儿了呢？', `MaleText_loc5`='好了，他們把燕麥放在哪裡?', `MaleText_loc7`='Veamos... ¿dónde guardan esa avena?' WHERE `ID`=25557;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음... 저쪽인가...', `MaleText_loc4`='嗯……可能在那儿。', `MaleText_loc5`='嗯...也許在那裡。', `MaleText_loc7`='Hmm... quizá allí.' WHERE `ID`=25558;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니야... 여기도 없는데.', `MaleText_loc4`='不对……这里也没有燕麦。', `MaleText_loc5`='不...這裡也沒有燕麥。', `MaleText_loc7`='No... aquí tampoco hay avena.' WHERE `ID`=25559;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일로 태양샘에 오셨습니까?', `MaleText_loc4`='你为什么来到太阳之井？', `MaleText_loc5`='是什麼讓你來到太陽之井?', `MaleText_loc7`='¿Qué te trae a La Fuente del Sol?', `FemaleText_loc1`='무슨 일로 태양샘에 오셨나요?', `FemaleText_loc4`='你为什么来到太阳之井？', `FemaleText_loc5`='是什麼讓你來到太陽之井?', `FemaleText_loc7`='¿Qué te trae a La Fuente del Sol?' WHERE `ID`=25560;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 불타는 군단 군주인 킬제덴과 그 수하들에게 사로잡힌 인간 아가씨를 구하러 동료 한 명과 함께 여기 왔습니다.$b$b저희는 캘타스가 태양샘 저 깊숙한 곳을 통해 불타는 군단 군주인 킬제덴을 소환하려고 한다는 걸 알았지요!$b$b이 세계를 지키려면 반드시 이를 막아야 합니다! 저는 이 끔찍한 계획이 실패했음을 확인할 사명을 지니고 있습니다.', `MaleText_loc4`='我和一个朋友一起赶来，想要从燃烧军团的首领基尔加丹手中营救一位年轻的姑娘。$B$B我们发现凯尔萨斯正在尝试从太阳之井的深处召唤出基尔加丹！$B$B为了这个世界——我们不能让他的计划成功！我的任务就是阻止他们。', `MaleText_loc5`='我和一位朋友前來解救一位年輕的人類女性逃離軍團領主基爾加丹與其邪惡手下的掌控。$b$b我們發現凱爾薩斯正試圖將基爾加丹從太陽之井的深處召喚出來。$b$b為了整個世界的安危 - 這件事絕不能發生!我保證會親自阻止這件事。', `MaleText_loc7`='Un amigo y yo hemos venido a rescatar a una joven mujer humana de las garras del Señor de la Legión, Kil''jaeden, y sus infames esbirros.$B$BHemos descubierto que Kael''thas está tratando de invocar al señor de la Legión, Kil''jaeden, desde lo más profundo de la mismísima Fuente del Sol.$B$B¡Por el bien de este mundo, eso no puede suceder! Me he comprometido a evitarlo.' WHERE `ID`=25561;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혼자 오신 게 아니군요?', `MaleText_loc4`='你不是一个人来的？', `MaleText_loc5`='你是否獨自前來?', `MaleText_loc7`='¿No estás solo aquí?', `FemaleText_loc1`='혼자 오신 게 아니군요?', `FemaleText_loc4`='你不是一个人来的？', `FemaleText_loc5`='你是否獨自前來?', `FemaleText_loc7`='¿No estás solo aquí?' WHERE `ID`=25562;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마드리고사가 저와 동행했지만 태양샘 안에서 서로 떨어지고 말았습니다.$b$b부디 그녀가 안전했으면 좋겠군요...', `MaleText_loc4`='玛蒂苟萨与我结伴而行，但是我们在太阳之井走散了。$B$B愿命运庇护她。', `MaleText_loc5`='瑪卓苟莎在此趟旅行中和我同行，不過我們在太陽之井中分散了。$b$b希望命運眷顧，她平安無恙。', `MaleText_loc7`='Madrigosa me acompañó en este viaje, pero nos hemos separado en La Fuente del Sol.$B$BEspero que el destino la mantenga a salvo.' WHERE `ID`=25563;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='유한한 생명에 불과한 한 여성에게서 킬제덴이 무얼 원하는 겁니까?', `MaleText_loc4`='基尔加丹为什么会对普通的人类女孩感兴趣？', `MaleText_loc5`='基爾加丹怎麼會對一個凡人女性有興趣?', `MaleText_loc7`='¿Qué podría querer Kil''jaeden de una mujer mortal?', `FemaleText_loc1`='유한한 생명에 불과한 한 여성에게서 킬제덴이 무얼 원하는 건가요?', `FemaleText_loc4`='基尔加丹为什么会对普通的人类女孩感兴趣？', `FemaleText_loc5`='基爾加丹怎麼會對一個凡人女性有興趣?', `FemaleText_loc7`='¿Qué podría querer Kil''jaeden de una mujer mortal?' WHERE `ID`=25564;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안비나는 단순한 필멸의 존재가 아닙니다, $r|1이여;여;. 안비나의 본질을 꿰뚫어본 자라면 그녀를 소유하고자 수단 방법을 가리지 않지요.$b$b한때 그녀가 저를 구했습니다. 그러니 저도 그녀를 돕고 싶습니다.', `MaleText_loc4`='$r，安薇娜绝不是“普通”的凡人。那些家伙一旦感知到蕴藏在她体内的强大能量，就会不择手段地想要将她占为己有。$b$b安薇娜曾经救过我，现在是我报恩的时候了。', `MaleText_loc5`='安薇娜不只是凡人，$r。那些瞭解她真實本質的人都想要擁有她。$b$b她曾經救過我，現在我想要報答她的恩惠。', `MaleText_loc7`='Anveena no es una simple mortal, $r. Aquellos que reconocen su verdadera naturaleza harían todo lo posible para poseerla.$B$BEn una ocasión me rescató a mí y ahora tengo intención de devolverle el favor.' WHERE `ID`=25565;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한여름 축제는 즐겁게 보내고 있나, $c? 불꽃지기는 축제 불꽃을 지키고, 나는 역사가로서 이 축제를 옛 이야기로 남기지. 물론 올해 축제 행사도 다 글로 옮긴다네. 아직은 만사가 무난하게 흘러가는 듯한데, 안 그런가?$B$B잘 알겠지만, $n, 축제 불꽃에는 고유한 힘이 있어 축제 기간 내내 타오를 수 있지. 우리가 축제 불꽃을 피우는 것처럼, 적 진영 도시 깊숙이에서도 성스러운 불꽃이 피어오르고 있으리라 확신한다네...', `MaleText_loc4`='$c，玩得开心吗？护火者负责照看熊熊燃烧的篝火，而我更像是守护火焰节历史的学者。当然，我还负责记录每年节日庆典的情况。到目前为止，一切都进展得很顺利，你认为呢？$b$b$n，你应该知道，火焰节期间燃起的簇簇篝火都蕴藏着与生俱来的能量。我们照看着自己的篝火，但是在敌人的主城深处，也会燃起这样神圣的火焰……', `MaleText_loc5`='喜歡這個節慶嗎，$c?$b$b雖說火焰持護者偏向當前的火焰，但我也不只是個只熟悉節慶過去的歷史學家而已。當然，我也記錄今年的節慶活動。目前一切進展的很順利，你不覺得嗎?$b$b你知道的，$n，在節日中持續燃燒的節慶火焰中潛藏著力量。我們看顧著我們的火焰，但我確信在我們敵人的城市深處有著神聖的火焰在燃燒著...', `MaleText_loc7`='¿Estás disfrutando del festival, $c?$b$bMientras los vigilantes de la Llama se ocupan de las hogueras del presente, yo soy más bien un historiador y me interesan mucho los festivales anteriores. Por supuesto, estoy documentando las celebraciones de este año. De momento, todo está saliendo bien, ¿no crees?$b$b¿Sabes, $n? Hay un poder inherente a todas las hogueras del festival que se prenderán durante estas fiestas. Nosotros cuidamos las nuestras pero estoy seguro de que en las ciudades enemigas arden hogueras sagradas...', `FemaleText_loc1`='한여름 축제는 즐겁게 보내고 계신가요, $c? 불꽃지기는 축제 불꽃을 지키고, 저는 역사가로서 이 축제를 옛 이야기로 남기지요. 물론 올해 축제 행사도 기록하고 있어요. 아직은 만사가 무난하게 흘러가는 듯한데, 안 그런가요?$B$B아시겠지만, $n, 축제 불꽃에는 고유한 힘이 있어 축제 기간 내내 타오를 수 있어요. 우리가 축제 불꽃을 피우는 것처럼, 적 진영 도시 깊숙이에서도 성스러운 불꽃이 피어오르고 있으리라 확신해요...', `FemaleText_loc4`='$c，玩得开心吗？护火者负责照看熊熊燃烧的篝火，而我更像是守护火焰节历史的学者。当然，我还负责记录每年节日庆典的情况。到目前为止，一切都进展得很顺利，你认为呢？$b$b$n，你应该知道，火焰节期间燃起的簇簇篝火都蕴藏着与生俱来的能量。我们照看着自己的篝火，但是在敌人的主城深处，也会燃起这样神圣的火焰……', `FemaleText_loc5`='喜歡這個節慶嗎，$c?$b$b雖說火焰持護者偏向當前的火焰，但我也不只是個只熟悉節慶過去的歷史學家而已。當然，我也記錄今年的節慶活動。目前一切進展的很順利，你不覺得嗎?$b$b你知道的，$n，在節日中持續燃燒的節慶火焰中潛藏著力量。我們看顧著我們的火焰，但我確信在我們敵人的城市深處有著神聖的火焰在燃燒著...', `FemaleText_loc7`='¿Estás disfrutando del festival, $c?$b$bMientras los vigilantes de la Llama se ocupan de las hogueras del presente, yo soy más bien un historiador y me interesan mucho los festivales anteriores. Por supuesto, estoy documentando las celebraciones de este año. De momento, todo está saliendo bien, ¿no crees?$b$b¿Sabes, $n? Hay un poder inherente a todas las hogueras del festival que se prenderán durante estas fiestas. Nosotros cuidamos las nuestras pero estoy seguro de que en las ciudades enemigas arden hogueras sagradas...' WHERE `ID`=25566;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 야영지에 오신 것을 환영합니다, $c|1이여;여;. 원한다면 얼마든지 머물러도 좋습니다.', `MaleText_loc4`='$c，欢迎来到我们的营地。你可以在这里休息。', `MaleText_loc5`='歡迎來到我們的營地，$c。請別覺得拘束，想待就待下來吧。', `MaleText_loc7`='Te damos la bienvenida a nuestro campamento, $c. Puedes descansar aquí si lo deseas.', `FemaleText_loc1`='우리 야영지에 오신 것을 환영합니다, $c|1이여;여;. 원한다면 얼마든지 머물러도 좋습니다.', `FemaleText_loc4`='$c，欢迎来到我们的营地。你可以在这里休息。', `FemaleText_loc5`='歡迎來到我們的營地，$c。請別覺得拘束，想待就待下來吧。', `FemaleText_loc7`='Te damos la bienvenida a nuestro campamento, $c. Puedes descansar aquí si lo deseas.' WHERE `ID`=25567;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물건을 사고 싶습니다.', `MaleText_loc4`='我想从你这里买点什么。', `MaleText_loc5`='我想要跟你買。', `MaleText_loc7`='Deseo comprarte algo.', `FemaleText_loc1`='물건을 사고 싶어요.', `FemaleText_loc4`='我想从你这里买点什么。', `FemaleText_loc5`='我想要跟你買。', `FemaleText_loc7`='Deseo comprarte algo.' WHERE `ID`=25568;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리에게 남은 건 아무것도 없습니다.', `MaleText_loc4`='这鬼地方什么都没有。', `MaleText_loc5`='這裡對我們來說已經沒有意義了。', `MaleText_loc7`='No queda nada para nosotros aquí.', `FemaleText_loc1`='우리에게 남은 건 아무것도 없습니다.', `FemaleText_loc4`='这鬼地方什么都没有。', `FemaleText_loc5`='這裡對我們來說已經沒有意義了。', `FemaleText_loc7`='No queda nada para nosotros aquí.' WHERE `ID`=25569;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 가족들은 어린아이들까지 무참하게 살해당했답니다.', `MaleText_loc4`='我的家人都被残忍地杀害了。连孩子都不能幸免。', `MaleText_loc5`='我的家族被殘忍的屠殺了。連小孩子都不放過。', `MaleText_loc7`='Mi familia fue asesinada sin piedad. Incluso los jóvenes.', `FemaleText_loc1`='내 가족들은 어린아이들까지 무참하게 살해당했답니다.', `FemaleText_loc4`='我的家人都被残忍地杀害了。连孩子都不能幸免。', `FemaleText_loc5`='我的家族被殘忍的屠殺了。連小孩子都不放過。', `FemaleText_loc7`='Mi familia fue asesinada sin piedad. Incluso los jóvenes.' WHERE `ID`=25570;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕은 이 땅에서 저지른 짓의 대가로 지옥에 떨어질 겁니다.', `MaleText_loc4`='巫妖王对这片土地所做的一切，足以让他永远在地狱之火中倍受煎熬。', `MaleText_loc5`='願巫妖王因為他在這片土地的所作所為永遠受地獄之火中焚燒。', `MaleText_loc7`='Ojalá el Rey Exánime arda en el fuego infernal por lo que le ha hecho a esta tierra.', `FemaleText_loc1`='리치 왕은 이 땅에서 저지른 짓의 대가로 지옥에 떨어질 겁니다.', `FemaleText_loc4`='巫妖王对这片土地所做的一切，足以让他永远在地狱之火中倍受煎熬。', `FemaleText_loc5`='願巫妖王因為他在這片土地的所作所為永遠受地獄之火中焚燒。', `FemaleText_loc7`='Ojalá el Rey Exánime arda en el fuego infernal por lo que le ha hecho a esta tierra.' WHERE `ID`=25571;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리에겐 이제 집이라고 부를 수 있는 곳조차 없습니다.', `MaleText_loc4`='我们已经是无家可归的人了。', `MaleText_loc5`='我們現在是無家可歸的人。', `MaleText_loc7`='Ahora somos un pueblo sin un lugar al que llamar hogar.', `FemaleText_loc1`='우리에겐 이제 집이라고 부를 수 있는 곳조차 없습니다.', `FemaleText_loc4`='我们已经是无家可归的人了。', `FemaleText_loc5`='我們現在是無家可歸的人。', `FemaleText_loc7`='Ahora somos un pueblo sin un lugar al que llamar hogar.' WHERE `ID`=25572;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스컬지는 세상의 모든 생명체를 파멸시킬 두려움이라곤 없는 괴물들이에요.', `MaleText_loc4`='天灾军团是不懂得恐惧的机器，他们只知道摧毁这个世界上所有的生命。', `MaleText_loc5`='天譴軍團是一種不知恐懼為何的機器，用來終結這世界上所有的生命體。', `MaleText_loc7`='La Plaga es una intrépida máquina programada para acabar con la vida de este mundo.', `FemaleText_loc1`='스컬지는 세상의 모든 생명체를 파멸시킬, 두려움이라곤 없는 괴물들이에요.', `FemaleText_loc4`='天灾军团是不懂得恐惧的机器，他们只知道摧毁这个世界上所有的生命。', `FemaleText_loc5`='天譴軍團是一種不知恐懼為何的機器，用來終結這世界上所有的生命體。', `FemaleText_loc7`='La Plaga es una intrépida máquina programada para acabar con la vida de este mundo.' WHERE `ID`=25573;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들이 헬스크림이라 부르는 자만이 우리의 유일한 희망입니다.', `MaleText_loc4`='被他们称为“地狱咆哮”的那个人恐怕是我们最后的希望了。', `MaleText_loc5`='被他們稱作地獄吼的那個人也許是我們唯一的希望。', `MaleText_loc7`='Aquel a quien llaman Grito Infernal puede ser nuestra única esperanza.', `FemaleText_loc1`='그들이 헬스크림이라 부르는 자만이 우리의 유일한 희망입니다.', `FemaleText_loc4`='被他们称为“地狱咆哮”的那个人恐怕是我们最后的希望了。', `FemaleText_loc5`='被他們稱作地獄吼的那個人也許是我們唯一的希望。', `FemaleText_loc7`='Aquel a quien llaman Grito Infernal puede ser nuestra única esperanza.' WHERE `ID`=25574;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 호드만이 우리를 구원할 수 있습니다.', `MaleText_loc4`='现在只有部落能救我们了。', `MaleText_loc5`='現在只有部落可以拯救我們了。', `MaleText_loc7`='Solo la Horda puede salvarnos ahora.', `FemaleText_loc1`='이제 호드만이 우리를 구원할 수 있습니다.', `FemaleText_loc4`='现在只有部落能救我们了。', `FemaleText_loc5`='現在只有部落可以拯救我們了。', `FemaleText_loc7`='Solo la Horda puede salvarnos ahora.' WHERE `ID`=25575;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 끝인지도 모르겠군요... 최후의 날이 다가오고 말았습니다.', `MaleText_loc4`='也许是这样吧……我们的末日终于来了。', `MaleText_loc5`='或許就是這樣...末日最後還是降臨在我們的身上。', `MaleText_loc7`='Quizá esto sea todo... el fin del mundo ha llegado ya.', `FemaleText_loc1`='이제 끝인지도 모르겠군요... 최후의 날이 다가오고 말았습니다.', `FemaleText_loc4`='也许是这样吧……我们的末日终于来了。', `FemaleText_loc5`='或許就是這樣...末日最後還是降臨在我們的身上。', `FemaleText_loc7`='Quizá esto sea todo... el fin del mundo ha llegado ya.' WHERE `ID`=25576;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 친구는 내가 보는 앞에서 살해당했어요. 이제 내게 남은 거라곤 복수심뿐입니다.', `MaleText_loc4`='在我负责警戒时，敌人杀害了我的伙伴。现在我只想着报仇。', `MaleText_loc5`='我被迫看著他們殺死我的伴侶。現在我心中只剩下復仇的念頭。', `MaleText_loc7`='Me obligaron a mirar mientras asesinaban a mi compañero. En mi corazón solo queda venganza.', `FemaleText_loc1`='내 친구는 내가 보는 앞에서 살해당했어요. 이제 내게 남은 거라곤 복수심뿐입니다.', `FemaleText_loc4`='在我负责警戒时，敌人杀害了我的伙伴。现在我只想着报仇。', `FemaleText_loc5`='我被迫看著他們殺死我的伴侶。現在我心中只剩下復仇的念頭。', `FemaleText_loc7`='Me obligaron a mirar mientras asesinaban a mi compañero. En mi corazón solo queda venganza.' WHERE `ID`=25577;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기회가 있다면 우린 호드의 일원이 되어야 합니다. 우리가 힘을 합친다면 스컬지를 무너트릴 수 있을 거예요.', `MaleText_loc4`='有机会的话，我们应该加入部落。只要团结起来，天灾军团就如同渣一般。', `MaleText_loc5`='如果有機會的話，我們應該加入部落。天譴軍團會在我們團結的力量下潰散。', `MaleText_loc7`='Si tenemos la oportunidad, deberíamos unirnos a la Horda. La Plaga se desmoronará bajo la fuerza de nuestro grupo.', `FemaleText_loc1`='기회가 있다면 우린 호드의 일원이 되어야 합니다. 우리가 힘을 합친다면 스컬지를 무너트릴 수 있을 거예요.', `FemaleText_loc4`='有机会的话，我们应该加入部落。只要团结起来，天灾军团就如同渣一般。', `FemaleText_loc5`='如果有機會的話，我們應該加入部落。天譴軍團會在我們團結的力量下潰散。', `FemaleText_loc7`='Si tenemos la oportunidad, deberíamos unirnos a la Horda. La Plaga se desmoronará bajo la fuerza de nuestro grupo.' WHERE `ID`=25578;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아서스... 난 그자를 저주합니다.', `MaleText_loc4`='阿尔萨斯……我呸！', `MaleText_loc5`='阿薩斯...我唾棄阿薩斯。', `MaleText_loc7`='Arthas... escupo sobre Arthas.', `FemaleText_loc1`='아서스... 난 그자를 저주합니다.', `FemaleText_loc4`='阿尔萨斯……我呸！', `FemaleText_loc5`='阿薩斯...我唾棄阿薩斯。', `FemaleText_loc7`='Arthas... escupo sobre Arthas.' WHERE `ID`=25579;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 북풍길을 가로지를 때 강령술사들의 습격을 받았습니다. 내가 어찌할 수 있었겠습니까?', `MaleText_loc4`='穿越横贯冰原时我们遭到了通灵师的袭击。在那种情况下，我能干什么呢？', `MaleText_loc5`='我們在穿過越風之地的路途中遭到死靈法師攻擊。我能怎麼辦?', `MaleText_loc7`='Los nigromantes nos atacaron en la carretera que atraviesa Transborea. ¿Qué podía hacer yo?', `FemaleText_loc1`='우리가 북풍길을 가로지를 때 강령술사들의 습격을 받았습니다. 내가 어찌할 수 있었겠습니까?', `FemaleText_loc4`='穿越横贯冰原时我们遭到了通灵师的袭击。在那种情况下，我能干什么呢？', `FemaleText_loc5`='我們在穿過越風之地的路途中遭到死靈法師攻擊。我能怎麼辦?', `FemaleText_loc7`='Los nigromantes nos atacaron en la carretera que atraviesa Transborea. ¿Qué podía hacer yo?' WHERE `ID`=25580;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽을 게 뻔한 상황에서 도망치는 자를 겁쟁이라고 부를 수 있습니까?', `MaleText_loc4`='面对死亡时选择逃跑也算是胆小鬼吗？', `MaleText_loc5`='當一個人在面臨自己的死期時逃跑是不是很怯懦?', `MaleText_loc7`='¿Es de cobardes correr cuando te enfrentas a tu propio final?', `FemaleText_loc1`='죽을 게 뻔한 상황에서 도망치는 자를 겁쟁이라고 부를 수 있습니까?', `FemaleText_loc4`='面对死亡时选择逃跑也算是胆小鬼吗？', `FemaleText_loc5`='當一個人在面臨自己的死期時逃跑是不是很怯懦?', `FemaleText_loc7`='¿Es de cobardes correr cuando te enfrentas a tu propio final?' WHERE `ID`=25581;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타운카르 없이는 더는 사는 의미가 없습니다.', `MaleText_loc4`='失去了牦牛村，生命也不再有意义了。', `MaleText_loc5`='沒有坦卡雷，生命就再也沒有意義了。', `MaleText_loc7`='Sin Taunka''le no vale la pena vivir.', `FemaleText_loc1`='타운카르 없이는 더는 사는 의미가 없습니다.', `FemaleText_loc4`='失去了牦牛村，生命也不再有意义了。', `FemaleText_loc5`='沒有坦卡雷，生命就再也沒有意義了。', `FemaleText_loc7`='Sin Taunka''le no vale la pena vivir.' WHERE `ID`=25582;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 자신을 증명할 기회가 다시 한 번 왔으면 좋겠습니다.', `MaleText_loc4`='我请求他们给我一个机会，让我证明自己。', `MaleText_loc5`='我懇求他們給我一個證明自己的機會。', `MaleText_loc7`='Espero que me den la oportunidad de demostrar lo que valgo.', `FemaleText_loc1`='나 자신을 증명할 기회가 다시 한 번 왔으면 좋겠습니다.', `FemaleText_loc4`='我请求他们给我一个机会，让我证明自己。', `FemaleText_loc5`='我懇求他們給我一個證明自己的機會。', `FemaleText_loc7`='Espero que me den la oportunidad de demostrar lo que valgo.' WHERE `ID`=25583;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어쨌든, 우린 단체로 결정을 내려야 합니다.', `MaleText_loc4`='无论发生什么，我们必须做出统一的决定。', `MaleText_loc5`='好吧，無論發生什麼事，我們都得像個團體一樣來做決定。', `MaleText_loc7`='Pase lo que pase, hemos de tomar la decisión en grupo.', `FemaleText_loc1`='어쨌든, 우린 단체로 결정을 내려야 합니다.', `FemaleText_loc4`='无论发生什么，我们必须做出统一的决定。', `FemaleText_loc5`='好吧，無論發生什麼事，我們都得像個團體一樣來做決定。', `FemaleText_loc7`='Pase lo que pase, hemos de tomar la decisión en grupo.' WHERE `ID`=25584;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 있거라, 정든 북풍의 땅이여.', `MaleText_loc4`='再见，亲爱的冰原。', `MaleText_loc5`='再見了，心愛的凍原。', `MaleText_loc7`='Adiós, amada tundra.', `FemaleText_loc1`='잘 있거라, 정든 북풍의 땅이여.', `FemaleText_loc4`='再见，亲爱的冰原。', `FemaleText_loc5`='再見了，心愛的凍原。', `FemaleText_loc7`='Adiós, amada tundra.' WHERE `ID`=25585;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으으... 여긴 정말 춥군.', `MaleText_loc4`='啊……好冷啊。', `MaleText_loc5`='嗚呃...這上頭好冷。', `MaleText_loc7`='Brrrr... Hace frío aquí arriba.' WHERE `ID`=25586;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빨래통! 내 빨래 어떻게 된 거야?', `MaleText_loc4`='水桶！我要洗的衣服呢？', `MaleText_loc5`='桶子!我的送洗衣物呢?', `MaleText_loc7`='¡Cubos! ¿Dónde está mi colada?' WHERE `ID`=25587;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세탁하는 중이라고, 몰슨. 못 기다리겠으면 직접 하든가.', `MaleText_loc4`='我正在洗呢，墨尔森。你想要洗得快一点的话，就自己动手吧。', `MaleText_loc5`='我正在弄，摩爾森。如果你想要快點完成，你就自己動手弄。', `MaleText_loc7`='Estoy en ello, Molsen. Si la quieres más rápido, hazla tú.' WHERE `ID`=25588;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='호드가 타운카를 보호할 겁니다. 진정하세요, 친구여.', `FemaleText_loc4`='部落会保护牦牛人的。冷静点，朋友。', `FemaleText_loc5`='部落會保護坦卡族。冷靜下來，朋友。', `FemaleText_loc7`='La Horda protegerá a los taunka. Cálmate, amigo.' WHERE `ID`=25589;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말도 안 돼.', `MaleText_loc4`='没门。', `MaleText_loc5`='想都別想。', `MaleText_loc7`='Ni en broma.' WHERE `ID`=25590;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 군인이야, 빨래통. 내 임무는 싸우는 거라고... 빨래는 네 일이지.', `MaleText_loc4`='我是一名士兵，水桶。你知道的，是战士……而你是个洗衣工。', `MaleText_loc5`='我是個士兵，桶子。你知道，就是進行戰鬥的人...你才是洗衣服的人。', `MaleText_loc7`='Soy un soldado, Cubos. Ya sabes... un luchador... Tú eres el chico de la colada.' WHERE `ID`=25591;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='솔직히 그나마도 잘 못하잖아! 내 휘장을 어떻게 만들어 놨는지 생각 안 나?', `MaleText_loc4`='还是个不合格的洗衣工！记得你把我的战袍洗成什么样了吗？', `MaleText_loc5`='做的不好!你還記得你對我的軍服做了什麼好事嗎?', `MaleText_loc7`='¡Y no el mejor! ¿Recuerdas lo que le hiciste a mi tabardo?' WHERE `ID`=25592;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 그대들의 타우렌 자매입니다, 타운카 여러분. 우리에게는 같은 피가 흐르니 그대들에게 위협이 될 일은 없을 겁니다. 여러분은 안전해요.', `FemaleText_loc4`='我们是姐妹。牛头人和牦牛人流着相同的血液，现在没有谁能伤害你了。你安全了。', `FemaleText_loc5`='我是你的牛頭人姐妹，坦卡族。我們的血源相同，也因此，我們不會傷害你。你很安全。', `FemaleText_loc7`='Soy tu hermana tauren, taunka. La misma sangre corre por nuestras venas, y por esto nadie te hará daño. Estás a salvo.' WHERE `ID`=25593;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가로쉬 님께서 곧 최정예 병사들을 보내실 겁니다. 그들이 여러분을 호드의 품으로 인도할 거예요.', `FemaleText_loc4`='加尔鲁什很快就会派出最精锐的军队。他们会代表部落朝你张开温暖的怀抱。', `FemaleText_loc5`='卡爾洛斯很快就會送出他最好的士兵。他們將會帶領你進入部落溫暖的懷抱裡。', `FemaleText_loc7`='Garrosh pronto enviará a sus soldados más capaces. Ellos te guiarán hacia los abiertos y expectantes brazos de la Horda.' WHERE `ID`=25594;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='곧 그대들은 아그마르의 망치에 있는 견고한 성벽의 보호를 받을 겁니다, 타운카 여러분.', `FemaleText_loc4`='牦牛人，你很快就会进入固若金汤的阿格玛之锤。', `FemaleText_loc5`='你很快就會受到阿格瑪之錘的堅固保護了，坦卡族。', `FemaleText_loc7`='Pronto habrás traspasado la impenetrable muralla del Martillo de Agmar, taunka.' WHERE `ID`=25595;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정의롭고 진실한 자는 구원을 받을 겁니다. 우리와 함께한다면 그대들은 안전해요.', `FemaleText_loc4`='只有那些为正义和真理而战的人才能得到救赎。只要加入我们，你就安全了。', `FemaleText_loc5`='救贖只會作用於那些理由正直且真實的人身上。加入我們，你就會獲得拯救。', `FemaleText_loc7`='La salvación llega a aquellos cuya causa es honrada y verdadera. Únete a nosotros y la encontrarás.' WHERE `ID`=25596;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그건 네 잘못이라고, 몰슨. 그런 일이 생기는 게 싫거든 앞으로 빨래를 내놓을 때 색깔을 구분해서 내놓던가...', `MaleText_loc4`='那全是你自己的错，墨尔森。现在你该学会将不同颜色的衣服分开洗了吧……', `MaleText_loc5`='那一整個都是你的錯，摩爾森。也許從今以後你會懂得分辨自己的立場...', `MaleText_loc7`='Eso fue culpa tuya, Molsen. Quizá así aprendas a separar los colores a partir de ahora...' WHERE `ID`=25597;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='휘장이 분홍색이 돼 있었다고, 빨래통. 분홍색! 그게 뭐냔 말이야...', `MaleText_loc4`='水桶，我的战袍被染成了粉红色。粉红色！你说这……', `MaleText_loc5`='這個徽章在我帶回來時是粉紅色的，桶子。是粉紅色!你想一想...', `MaleText_loc7`='El tabardo era rosa cuando me lo devolviste, Cubos. ¡Rosa! Recuerda eso...' WHERE `ID`=25598;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부대원들이 한 주일 내내 날 비웃었다고! 다시는 그런 짓 하지 마!', `MaleText_loc4`='我被他们嘲笑了整整一周！别再犯这种错误了！', `MaleText_loc5`='整個小隊嘲笑了我整整一週!別讓這種事再次發生了!', `MaleText_loc7`='¡Todo el pelotón se estuvo riendo de mí una semana entera! ¡No dejes que eso vuelva a ocurrir!' WHERE `ID`=25599;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 그래. 맘대로 해.', `MaleText_loc4`='好吧。随你便。', `MaleText_loc5`='很好。隨你開心。', `MaleText_loc7`='Bien. Como quieras.' WHERE `ID`=25600;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 사절 브라이트후프를 향해 환호합니다.', `MaleText_loc4`='%s对特使艾米萨·闪蹄欢呼。', `MaleText_loc5`='%s為特使亮蹄而歡呼。', `MaleText_loc7`='%s anima a la emisaria Pezuña Brillante.', `FemaleText_loc1`='%s|1이;가; 사절 브라이트후프를 향해 환호합니다.', `FemaleText_loc4`='%s对特使艾米萨·闪蹄欢呼。', `FemaleText_loc5`='%s為特使亮蹄而歡呼。', `FemaleText_loc7`='%s anima a la emisaria Pezuña Brillante.' WHERE `ID`=25601;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 기쁨의 눈물을 흘립니다.', `MaleText_loc4`='%s喜极而泣。', `MaleText_loc5`='%s流下了幸福的淚水。', `MaleText_loc7`='%s llora lágrimas de alegría.', `FemaleText_loc1`='%s|1이;가; 기쁨의 눈물을 흘립니다.', `FemaleText_loc4`='%s喜极而泣。', `FemaleText_loc5`='%s流下了幸福的淚水。', `FemaleText_loc7`='%s llora lágrimas de alegría.' WHERE `ID`=25602;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 수긍하는 의미로 함성을 지릅니다!', `MaleText_loc4`='%s咆哮着表示赞同！', `MaleText_loc5`='%s贊同的大吼!', `MaleText_loc7`='¡%s ruge mostrando aprobación!', `FemaleText_loc1`='%s|1이;가; 수긍하는 의미로 함성을 지릅니다!', `FemaleText_loc4`='%s咆哮着表示赞同！', `FemaleText_loc5`='%s贊同的大吼!', `FemaleText_loc7`='¡%s ruge mostrando aprobación!' WHERE `ID`=25603;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 짓이야? 그건 내 저녁밥이라고!', `MaleText_loc4`='你有毛病吗？那是我的饭菜！', `MaleText_loc5`='你有什麼毛病啊?先是晚餐!', `MaleText_loc7`='¿Qué diablos te pasa? ¡Eso era la cena!' WHERE `ID`=25604;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이젠 저녁밥이 아니고 빨래야.', `MaleText_loc4`='现在不得不清洗衣物了。', `MaleText_loc5`='現在又是送洗衣物。', `MaleText_loc7`='Ahora es la colada.' WHERE `ID`=25605;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가만 안 둘 줄 알아, 빨래통! 내 말 들었지? 너 죽었어!', `MaleText_loc4`='你死定了，水桶！你听见没？你死定了！', `MaleText_loc5`='你死定了，桶子!有聽我說的話嗎?死定了!', `MaleText_loc7`='¡Estás muerto, Cubos! ¿Me oyes? ¡Muerto!' WHERE `ID`=25606;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 사절 브라이트후프에게 감사합니다.', `MaleText_loc4`='%s向特使艾米萨·闪蹄致谢。', `MaleText_loc5`='%s感謝特使亮蹄。', `MaleText_loc7`='%s da las gracias a la emisaria Pezuña Brillante.', `FemaleText_loc1`='%s|1이;가; 사절 브라이트후프에게 감사합니다.', `FemaleText_loc4`='%s向特使艾米萨·闪蹄致谢。', `FemaleText_loc5`='%s感謝特使亮蹄。', `FemaleText_loc7`='%s da las gracias a la emisaria Pezuña Brillante.' WHERE `ID`=25607;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, 아저씨. 저도 공연할 준비가 되었답니다!', `FemaleText_loc4`='嗨，来点摇滚乐吧！', `FemaleText_loc5`='哈囉先生，我準備好要搖滾了!', `FemaleText_loc7`='Hola, señor. ¡Estoy lista para el rock!' WHERE `ID`=25608;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, 저는 아저씨들 너무너무 좋아해요! 저도 함께 무대에 서고 싶어요!', `FemaleText_loc4`='嗨，我是你们的歌迷！来点摇滚乐吧！', `FemaleText_loc5`='嘿大伙們，我是你們最忠心的粉絲!我準備好要搖滾了!', `FemaleText_loc7`='Hey, chicos, soy su mayor fan. ¡Estoy lista para el rock!' WHERE `ID`=25609;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저 좀 보세요! 저도 아저씨들처럼 멋지게 연주할 수 있어요!', `FemaleText_loc4`='瞧，伙计们！我也能摇滚起来！', `FemaleText_loc5`='大家看看!我可以像你們一樣搖滾!', `FemaleText_loc7`='¡Miren esto chicos! ¡Puedo hacerlo igual de bien que ustedes!' WHERE `ID`=25610;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우와! 제가 시그 니시우스 아저씨를 감동시켰나 봐요! 아저씨가 미소 지으시는 걸 봤다니까요! 내년엔 저도 같이 공연할 수 있을 거예요!', `FemaleText_loc4`='哇！我成功地吸引了西格·尼修斯的注意！他刚才对着我笑啦！我敢打赌明年我就能加入这支乐队！', `FemaleText_loc5`='哇喔!我努力讓席格·尼修斯印象深刻!我看到他笑開了!我猜我明年可以加入他們!', `FemaleText_loc7`='¡Guau! ¡He conseguido impresionar a Sig Nicious! ¡Le he visto sonreír! ¡Seguro que puedo unirme a ellos el año que viene!' WHERE `ID`=25611;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='살란드리아가 손을 흔듭니다.', `FemaleText_loc4`='萨兰蒂亚挥舞着双手。', `FemaleText_loc5`='瑟蘭德雅在空中揮舞她的雙手。', `FemaleText_loc7`='Salandria agita su mano en el aire.' WHERE `ID`=25612;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='살란드리아가 기타 치는 흉내를 내며 호드의 힘이라는 노래를 부릅니다.', `FemaleText_loc4`='萨兰蒂亚模仿弹吉他的动作，哼着一首颂扬部落力量的歌曲。', `FemaleText_loc5`='瑟蘭德雅開始演奏無形的吉他，唱出「部落之力」。', `FemaleText_loc7`='Salandria hace como que toca la guitarra y empieza a cantar The Power of the Horde.' WHERE `ID`=25613;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정령들에 감사해야겠군! 눈보라 때문에 크발디르의 함선이 속도를 늦췄다!', `MaleText_loc4`='感谢灵魂！暴风雪会减慢克瓦迪尔船只的航速！', `MaleText_loc5`='感謝靈魂!這場暴風雪可以讓科瓦迪爾的船隻慢下來!', `MaleText_loc7`='¡Gracias a los espíritus! ¡La ventisca retrasará a los barcos Kvaldir!' WHERE `ID`=25614;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정령들이 우리의 부탁을 들어주었군요! 느껴지십니까, $n 님?', `MaleText_loc4`='灵魂听见我们的祈祷了！$n，你能感觉到吗？', `MaleText_loc5`='靈魂已經接收到了!你有感覺到嗎，$n?', `MaleText_loc7`='¡Los espíritus han escuchado! ¿Puedes sentirlo, $n?' WHERE `ID`=25615;
