UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치의 성물함이 있는 곳으로 데려가 다오, 황혼아.', `MaleText_loc4`='黄昏，带我去找巫妖的护符匣。', `MaleText_loc5`='我需要你帶領我前往巫妖的骨匣所在之處，幽暮。', `MaleText_loc7`='Necesito que me lleves hasta la filacteria del exánime, Anochecer.', `FemaleText_loc1`='리치의 성물함이 있는 곳으로 데려가 줘, 황혼아.', `FemaleText_loc4`='黄昏，带我去找巫妖的护符匣。', `FemaleText_loc5`='我需要你帶領我前往巫妖的骨匣所在之處，幽暮。', `FemaleText_loc7`='Necesito que me lleves hasta la filacteria del exánime, Anochecer.' WHERE `ID`=25617;
