UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<버드가 그저 가만히 못 들은 척하고 있습니다. 가까이서 보니 그의 가면 아래로 침이 흘러내리는 것이 보입니다.>', `MaleText_loc4`='<巴德强作镇静，假装没有听你讲话。你专注地盯着他，发现一滴口水从他的面具下落下。>', `MaleText_loc5`='<霸德一動也不動，假裝沒聽到你說的話。靠近一看，你看見他的面具底下滴下幾滴口水。>', `MaleText_loc7`='<Budd se queda muy quieto, haciendo como que no te escucha. Inspeccionándolo de cerca puedes ver un poco de baba caer bajo su máscara.>' WHERE `ID`=25644;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<버드가 웅크린 채로 몸을 앞뒤로 흔들며 트롤의 언어같이 들리는 말로 중얼댑니다.>', `MaleText_loc4`='<巴德来回扭动，用巨魔语念叨着什么。>', `MaleText_loc5`='<霸德前後擺動他的臀部，喃喃唸著某種聽起來像是食人妖語的話。>', `MaleText_loc7`='<Budd se balancea en cuclillas, farfullando algo que parece ser lengua trol.>' WHERE `ID`=25645;
