UPDATE `locales_broadcast_text` SET `MaleText_loc1`='버드 씨, 이리 오십시오. 얼음 트롤들과 한 판 놀아 봅시다!', `MaleText_loc4`='来吧，巴德。和冰巨魔较量的时刻来临了！', `MaleText_loc5`='來吧，霸德。該跟這些寒冰食人妖玩玩了!', `MaleText_loc7`='Vamos, Budd. ¡Es hora de jugar con los trols de hielo!', `FemaleText_loc1`='버드 씨, 이리 오세요. 얼음 트롤들과 한 판 놀아 보시죠!', `FemaleText_loc4`='来吧，巴德。和冰巨魔较量的时刻来临了！', `FemaleText_loc5`='來吧，霸德。該跟這些寒冰食人妖玩玩了!', `FemaleText_loc7`='Vamos, Budd. ¡Es hora de jugar con los trols de hielo!' WHERE `ID`=25656;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우와, 눈부셔!', `MaleText_loc4`='噢，闪闪发光的宝贝！', `MaleText_loc5`='哦喔喔，閃亮亮的東西!', `MaleText_loc7`='¡Ooooh, brillante!' WHERE `ID`=25657;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐요! 절 트롤 형제들한테 데려다 주십시오!', `MaleText_loc4`='嘿，朋友！带我去看看那些巨魔兄弟呀！', `MaleText_loc5`='欸，老兄!帶我去找我的食人妖弟兄!', `MaleText_loc7`='¡Ey, colega! ¡Llévame con mis hermanos trols!' WHERE `ID`=25658;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='트롤식 술래잡기를 할 시간이군요, 친구!', `MaleText_loc4`='朋友，就让你见识一下巨魔的把戏！', `MaleText_loc5`='玩食人妖抓人遊戲囉，老兄!', `MaleText_loc7`='¡Es hora de jugar a pillar al trol, colega!' WHERE `ID`=25659;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘은 트롤 형제들이 아주 재밌어하겠어요, 친구!', `MaleText_loc4`='这些巨魔朋友今天可有乐子了！', `MaleText_loc5`='我的食人妖弟兄今天找了不少樂子，老兄!', `MaleText_loc7`='¡Mi hermanos trol se van a divertir de lo lindo hoy, colega!' WHERE `ID`=25660;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헤헤헤! 이거 정말 재미있을 겁니다, 친구!', `MaleText_loc4`='嘿嘿嘿！这肯定会非常有趣！', `MaleText_loc5`='嘿嘿嘿!這一定很好玩，老兄!', `MaleText_loc7`='¡Je, je, je! ¡Esto va a ser divertido, colega!' WHERE `ID`=25661;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 길이 맞습니까, 친구?', `MaleText_loc4`='朋友，你确信我们没走错路？', `MaleText_loc5`='你覺得我們有走對路嗎，老兄?', `MaleText_loc7`='¿Seguro que es por aquí, colega?' WHERE `ID`=25662;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<킁킁> 냄새가 나는데요, 친구.', `MaleText_loc4`='<嗅，嗅>朋友，我能嗅出他们的气味。', `MaleText_loc5`='<嗅了嗅>我可以聞到他們，老兄。', `MaleText_loc7`='<snif, snif> Puedo olerlos, colega.' WHERE `ID`=25663;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 술맛처럼 끝내주는 건 세상 어디에도 없지요.', `MaleText_loc4`='敲打脑袋就是表达爱意的完美方式。', `MaleText_loc5`='沒什麼比敲頭更棒的了。', `MaleText_loc7`='Nada expresa “te quiero” como un toquecito en la cabeza.' WHERE `ID`=25664;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알았습니다, 버드. 가서 트롤을 찾아오십시오...', `MaleText_loc4`='好吧，巴德。去找你的巨魔朋友……', `MaleText_loc5`='好，霸德。去抓一隻食人妖...', `MaleText_loc7`='Vale, Budd. Ve a pillar al trol...', `FemaleText_loc1`='알았습니다, 버드. 가서 트롤을 찾아오세요...', `FemaleText_loc4`='好吧，巴德。去找你的巨魔朋友……', `FemaleText_loc5`='好，霸德。去抓一隻食人妖...', `FemaleText_loc7`='Vale, Budd. Ve a pillar al trol...' WHERE `ID`=25666;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='승리가 아니면 죽음뿐! 호드를 위하여!', `MaleText_loc4`='非胜即死！为了部落！', `MaleText_loc5`='不勝即亡!為了部落!', `MaleText_loc7`='¡Victoria o muerte! ¡Por la Horda!', `FemaleText_loc1`='승리가 아니면 죽음뿐! 호드를 위하여!', `FemaleText_loc4`='非胜即死！为了部落！', `FemaleText_loc5`='不勝即亡!為了部落!', `FemaleText_loc7`='¡Victoria o muerte! ¡Por la Horda!' WHERE `ID`=25667;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 됐습니다, 형제여!', `MaleText_loc4`='兄弟，来吧！', `MaleText_loc5`='換你當了，弟兄!', `MaleText_loc7`='¡Tú la llevas, colega!' WHERE `ID`=25668;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니, 아닙니다, 친구. 여기에는 트롤이 없어요...', `MaleText_loc4`='不对，不对。这里没有巨魔……', `MaleText_loc5`='不，不，老兄。這兒沒有食人妖...', `MaleText_loc7`='No, no, colega. Aquí no hay trols...' WHERE `ID`=25669;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋습니다, 친구. 트롤 형제들 근처에 가면 말해 주세요.', `MaleText_loc4`='好啦。什么时候才能找到那些巨魔兄弟呀？', `MaleText_loc5`='好，老兄。我們靠近我的食人妖弟兄的時候再告訴我。', `MaleText_loc7`='Vale, colega. Avísame cuando estemos cerca de mis hermanos trols.' WHERE `ID`=25670;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='태양샘 고원에 있는 관문 세 개가 모두 무너졌습니다, $n.$B$B병력을 집결하여 킬제덴이 아제로스에 들어오지 못하도록 막아야 합니다. 너무 늦기 전에 말입니다!', `MaleText_loc4`='$n，太阳井之岛的三座大门已被全部摧毁。$B$B集合你的军队，阻止基尔加丹进入艾泽拉斯世界！', `MaleText_loc5`='太陽之井高地的三道門全都被終結了，$n。$B$B你必須得率領你的隊伍在一切都太遲以前阻止基爾加丹進入艾澤拉斯!', `MaleText_loc7`='Las tres puertas de la Meseta de La Fuente del Sol han sido derribadas, $n.$B$B¡Has de organizar tus tropas y evitar que Kil''jaeden entre en Azeroth antes de que sea demasiado tarde!' WHERE `ID`=25671;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 브란의 일지 중 가장 마지막 기록을 읽습니다.', `MaleText_loc4`='%s翻阅着布莱恩的日记，查看最新记录的日志。', `MaleText_loc5`='%s從布萊恩日誌中最近的幾行字開始讀起。', `MaleText_loc7`='%s lee las anotaciones más recientes del diario de Brann.' WHERE `ID`=25672;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놀랍군! 이 내용에 따르면 브란은 토르 모단 깊숙한 곳에서 신비로운 룬문자 판을 찾았다고 하네!', `MaleText_loc4`='天哪！日志中提到布莱恩在索尔莫丹深处发现了一块刻有神秘符文的石板！', `MaleText_loc5`='真令人訝異!上面說布萊恩在鐸爾莫丹，發現了一塊神秘的符文板!', `MaleText_loc7`='¡Impresionante! ¡Aquí dice que Brann descubrió una misteriosa placa rúnica en las profundidades de Thor Modan!' WHERE `ID`=25673;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='브란은 거인과 그들의 동맹이 공격했을 때 이 룬문자에 대한 지침서를 작성하고 있었다고 하는군.', `MaleText_loc4`='布莱恩写道，正在他尝试破译符文内容时，遭到了巨人和他们的盟友的袭击。', `MaleText_loc5`='布萊恩寫著，當巨人和其盟友來攻的時候，他正在寫一份符文記號的簡介。', `MaleText_loc7`='Brann escribe que estaba creando una guía sobre esos símbolos rúnicos cuando los gigantes y sus aliados atacaron.' WHERE `ID`=25674;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그가 룬문자 판에 쓰인 내용을 해독하는 법을 기록해두긴 했지만 해독한 내용 자체는 기록하지 않은 것 같네.', `MaleText_loc4`='他记录下大段已被破译的符文，却没有留下他的翻译。', `MaleText_loc5`='他寫到了有破解了符文板上的文字，但是並未記將翻譯記載在上頭。', `MaleText_loc7`='Informa de que ha descifrado parte de la escritura de la placa rúnica, pero no parece que anotara la traducción.' WHERE `ID`=25675;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마그니 폐하의 수염에 걸고, 우린 그가 서판을 읽는 데 사용한 룬 열쇠를 다시 만들어야 하네. 그의 흔적을 거의 따라잡은 것 같군!', `MaleText_loc4`='以麦格尼·铜须的名义，我们必须完成他未竟的工作，重铸解读石板的符文钥石！', `MaleText_loc5`='麥格尼的鬍子在上，我們得重塑那把他用來閱讀石板的符文之鑰。我們就快要跟上他的腳步了!', `MaleText_loc7`='¡Por las barbas de Magni! Tenemos que reconstruir la clave rúnica que usó para leer la placa. ¡Podríamos estar pisándole los talones!' WHERE `ID`=25676;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고대의 플룻을 잃어버렸으니 다시 받았으면 합니다, 에리단.', `MaleText_loc4`='艾瑞丹，我把上古长笛弄丢了，想再要一支。', `MaleText_loc5`='我把上古長笛弄丟了，需要一個新的，艾瑞丹。', `MaleText_loc7`='He perdido la Flauta de los antiguos y necesito una de recambio, Eridan.', `FemaleText_loc1`='고대의 플룻을 잃어버렸으니 다시 받았으면 해요, 에리단.', `FemaleText_loc4`='艾瑞丹，我把上古长笛弄丢了，想再要一支。', `FemaleText_loc5`='我把上古長笛弄丟了，需要一個新的，艾瑞丹。', `FemaleText_loc7`='He perdido la Flauta de los antiguos y necesito una de recambio, Eridan.' WHERE `ID`=25677;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 괴롭히지 마십쇼, 친구!', `MaleText_loc4`='朋友，别伤害我！', `MaleText_loc5`='不要傷害我，老兄!', `MaleText_loc7`='¡No me hagas daño, colega!' WHERE `ID`=25678;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='트롤의 힘을 보여드리죠, 친구!', `MaleText_loc4`='朋友，这就是巨魔的力量！', `MaleText_loc5`='食人妖最強，老兄!', `MaleText_loc7`='¡Poder trol, colega!' WHERE `ID`=25679;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐가 문젭니까? 트롤 처음 봅니까?', `MaleText_loc4`='别大惊小怪的。朋友，你没见过巨魔吗？', `MaleText_loc5`='你有什麼毛病啊，老兄?你沒見過食人妖?', `MaleText_loc7`='¿Qué te pasa, colega? ¿Nunca has visto un trol?' WHERE `ID`=25680;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 제 형제들을 어디서 찾아야 하는지 모르는 듯한데...', `MaleText_loc4`='朋友，我有一种感觉，就是你根本就不知道我那些兄弟在哪儿对不对。', `MaleText_loc5`='我猜你不知道上哪兒找我的弟兄是吧，老兄。', `MaleText_loc7`='Estaba pensando que tú no sabes dónde encontrar a mis hermanos, colega.' WHERE `ID`=25681;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='관두십시오. 제 형제들은 제가 직접 찾겠습니다.', `MaleText_loc4`='算啦。我自己去找他们。', `MaleText_loc5`='算了，老兄。我自己去找我的弟兄們。', `MaleText_loc7`='Olvídalo, colega. Iré a buscar a mis hermanos yo mismo.' WHERE `ID`=25682;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리... 길을 잃은 것 같습니다, 친구...', `MaleText_loc4`='我们好像迷路了……', `MaleText_loc5`='我想我們迷路了，老兄...', `MaleText_loc7`='Creo que estamos perdidos, colega...' WHERE `ID`=25683;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아들아, 팔에아의 전사자들은 안식을 얻지 못할 것이다. 나가 여사제를 찾아라!', `MaleText_loc4`='孩子，帕尔依的亡魂无法安息。找到纳迦女祭司的下落！', `MaleText_loc5`='帕雷亞的亡靈無法安息，孩子。找出那個納迦女祭司!', `MaleText_loc7`='Los caídos de Pal''ea no descansarán, hijo. ¡Encuentra a la sacerdotisa naga!' WHERE `ID`=25684;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='채찍파도 일족이 과거의 영광을 되찾을 수는 없겠지만, 이 더러운 뱃놈들은 녀석들이 저지른 짓의 대가를 치를 것이다... 반드시!', `FemaleText_loc4`='裂鞭海岸昔日的荣耀不复存在，我发誓，这些混蛋会为此付出代价！', `FemaleText_loc5`='裂鞭族將永遠無法重返過去的榮耀，但是這些駕船的惡棍將為了他們的行為付出代價 - 我發誓!', `FemaleText_loc7`='Tralladón nunca volverá a su antigua gloria, pero... ¡Juro que esas escorias marineras pagarán por lo que han hecho!' WHERE `ID`=25685;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='''무쇠와 바위의 요람으로 돌아가리라.''', `MaleText_loc4`='“将回到钢铁与岩石的摇篮。”', `MaleText_loc5`='「該當返回鋼鐵與石頭的搖籃之中。」', `MaleText_loc7`='''Volverá a la cuna de hierro y piedra.''', `FemaleText_loc1`='''무쇠와 바위의 요람으로 돌아가리라.''', `FemaleText_loc4`='“将回到钢铁与岩石的摇篮。”', `FemaleText_loc5`='「該當返回鋼鐵與石頭的搖籃之中。」', `FemaleText_loc7`='''Volverá a la cuna de hierro y piedra.''' WHERE `ID`=25686;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='''로켄의 이름으로 바위의 자손을 멸망시켜라.''', `MaleText_loc4`='“以洛肯的名义，摧毁岩石的子孙。”', `MaleText_loc5`='「以洛肯之名，消滅石之裔。」', `MaleText_loc7`='''En el nombre de Loken, destruye a los descendientes de la piedra.''', `FemaleText_loc1`='''로켄의 이름으로 바위의 자손을 멸망시켜라.''', `FemaleText_loc4`='“以洛肯的名义，摧毁岩石的子孙。”', `FemaleText_loc5`='「以洛肯之名，消滅石之裔。」', `FemaleText_loc7`='''En el nombre de Loken, destruye a los descendientes de la piedra.''' WHERE `ID`=25687;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='''폭풍 속에 잠든 울두아르로 돌아오라.''', `MaleText_loc4`='“回到坐落在风暴峭壁的奥杜尔。”', `MaleText_loc5`='「回到奧杜亞，在風暴之擁中安歇。」', `MaleText_loc7`='''Regresará a Ulduar, acurrucado en el abrazo la tormenta.''', `FemaleText_loc1`='''폭풍 속에 잠든 울두아르로 돌아오라.''', `FemaleText_loc4`='“回到坐落在风暴峭壁的奥杜尔。”', `FemaleText_loc5`='「回到奧杜亞，在風暴之擁中安歇。」', `FemaleText_loc7`='''Regresará a Ulduar, acurrucado en el abrazo la tormenta.''' WHERE `ID`=25688;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='''무쇠의 후예들아, 부름에 응하라. 이제 서둘러 울두아르로 향하라.''', `MaleText_loc4`='“钢铁的后裔，倾听这呼唤吧。赶快前往奥杜尔。”', `MaleText_loc5`='「鐵之子，回應召喚。速至奧杜亞。」', `MaleText_loc7`='''Hijos del hierro escuchad la llamada. Id deprisa a Ulduar.''', `FemaleText_loc1`='''무쇠의 후예들아, 부름에 응하라. 이제 서둘러 울두아르로 향하라.''', `FemaleText_loc4`='“钢铁的后裔，倾听这呼唤吧。赶快前往奥杜尔。”', `FemaleText_loc5`='「鐵之子，回應召喚。速至奧杜亞。」', `FemaleText_loc7`='''Hijos del hierro escuchad la llamada. Id deprisa a Ulduar.''' WHERE `ID`=25689;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='''창조주의 가장 위대한 아이들이여, 일어나 그대들의 권리를 쟁취하라.''', `MaleText_loc4`='“造物主最伟大的子嗣们，索求你们与生俱来的权力吧。”', `MaleText_loc5`='造物者的子嗣中最偉大的呀，喚醒並奪回你們的天職吧。', `MaleText_loc7`='Grandes hijos del Hacedor, alcen y reclamen su derecho de linaje.''', `FemaleText_loc1`='''창조주의 가장 위대한 아이들이여, 일어나 그대들의 권리를 쟁취하라.''', `FemaleText_loc4`='“造物主最伟大的子嗣们，索求你们与生俱来的权力吧。”', `FemaleText_loc5`='造物者的子嗣中最偉大的呀，喚醒並奪回你們的天職吧。', `FemaleText_loc7`='Grandes hijos del Hacedor, alcen y reclamen su derecho de linaje.''' WHERE `ID`=25690;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='타운카들을 보호하고 작게나마 편의를 제공하는 일은 우리의 의무랍니다.', `FemaleText_loc4`='我们必须保护这些牦牛人，并尽可能地安慰他们。', `FemaleText_loc5`='保護這些坦卡族並盡我們所能讓他們過得舒適，這是我們的責任。', `FemaleText_loc7`='Es nuestro deber proteger a estos taunka y ofrecerles las comodidades que nos sean posibles.' WHERE `ID`=25691;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사절님, 호드 연합 피의 맹세를 잃어버렸습니다. 하나 더 주실 수 있겠습니까?', `MaleText_loc4`='大使，我弄丢了部落的血誓。你能再给我一份吗？', `MaleText_loc5`='密使，我遺失了部落的血誓。你可以再給我一個嗎?', `MaleText_loc7`='Emisario, he perdido el juramento de sangre de la Horda. ¿Podrías darme otro?', `FemaleText_loc1`='사절님, 호드 연합 피의 맹세를 잃어버렸어요. 하나 더 주실 수 있을까요?', `FemaleText_loc4`='大使，我弄丢了部落的血誓。你能再给我一份吗？', `FemaleText_loc5`='密使，我遺失了部落的血誓。你可以再給我一個嗎?', `FemaleText_loc7`='Emisario, he perdido el juramento de sangre de la Horda. ¿Podrías darme otro?' WHERE `ID`=25692;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 아이들은 살 겁니다. 사랑과 애정 속에서 그들은 호드의 강한 일원으로 성장할 것이고, 끔찍했던 어린 시절의 기억은 시간이 지나면서 점차 바래겠지요.', `FemaleText_loc4`='这些孩子会活下去的。他们会在关爱中长大，成为坚强的部落勇士。时间会让他们淡忘那些悲惨的过去。', `FemaleText_loc5`='這些小孩會活下去。在愛與關懷之中他們將會成長為強壯的部落成員，而他們恐怖破碎的回憶將會被淡忘。', `FemaleText_loc7`='Estos infantes vivirán. Con amor y afecto crecerán para convertirse en fuertes miembros de la Horda y, con el tiempo, los horribles recuerdos de sus destrozadas vidas se desvanecerán.' WHERE `ID`=25693;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그래, 그래, 아가야. 이제 괜찮단다.', `FemaleText_loc4`='亲爱的，一切都会好起来的。', `FemaleText_loc5`='好了，好了，甜心。一切都會好的。', `FemaleText_loc7`='Cálmate, cielo. Todo va a salir bien.' WHERE `ID`=25694;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='귀여운 아가. 배고프지 않니? 이 트윈브리즈 아줌마를 봐서라도 뭔가 먹어 주지 않으련?', `FemaleText_loc4`='我的小天使，你不饿吗？听蒂布雷兹阿姨的话，吃点东西好吗？就吃一点？', `FemaleText_loc5`='我的小天使。你餓了嗎?你願意為雙風阿姨吃一點東西嗎?一點點就好?', `FemaleText_loc7`='Angelito. ¿Tienes hambre? ¿Comerás por la tía Brisas Gemelas? ¿Un poquitín?' WHERE `ID`=25695;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 아이는 위대한 용사로 성장할 거예요. 그렇지, 아가야?', `FemaleText_loc4`='他会成长为一名勇敢的战士。亲爱的，是不是呀？', `FemaleText_loc5`='這個小傢伙長大會成為一個偉大的戰士。不是嗎，親愛的?', `FemaleText_loc7`='Este se convertirá en un gran guerrero. ¿Verdad, pequeñín?' WHERE `ID`=25696;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아니면 트윈브리즈 아줌마처럼 주술사가 될래?', `FemaleText_loc4`='你想不想像蒂布雷兹阿姨那样，成为一名萨满祭司？', `FemaleText_loc5`='也許你會像雙風阿姨一樣當個薩滿?', `FemaleText_loc7`='¿Serás chamán como la tía Brisas Gemelas?' WHERE `ID`=25697;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 울음을 터뜨립니다.', `MaleText_loc4`='%s哭了。', `MaleText_loc5`='%s哭了。', `MaleText_loc7`='%s llora.' WHERE `ID`=25698;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='먹음직스러운 향료를 이렇게 가져다 주다니. 감사합니다, $n 님.', `MaleText_loc4`='$n，再次感谢你为我带来这么好闻的熏香。', `MaleText_loc5`='再次謝謝你，$n，提供了這股令人愉悅的薰香。', `MaleText_loc7`='Gracias de nuevo, $n, por este delicioso incienso.' WHERE `ID`=25699;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일어나시오, 그리셀다. 이쪽이라오.', `MaleText_loc4`='格里西达，快醒醒。嘿。', `MaleText_loc5`='醒醒，葛薩爾妲。拿著，女孩。', `MaleText_loc7`='Despierta, Griselda. Aquí, chica.' WHERE `ID`=25700;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 여기 있는 줄 절대 모를 거요, 그렇지 않소? 림피 조와 플라넬 맥기처럼 잡혀갈 순 없어!', `MaleText_loc4`='这里很安全，对吧？他们抓走了乔伊和米克基，我们得躲起来，不能让他们发现。', `MaleText_loc5`='他們永遠找不到我們的，對吧?我們不會讓他們像抓走『瘸子』喬和『法蘭絨』麥克基一樣抓到我們的!', `MaleText_loc7`='Nunca nos encontrarán aquí. ¿Verdad? ¡No dejaremos que nos atrapen como hicieron con Joe el Cojo y Flannel McGee!' WHERE `ID`=25701;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 우린 저 괴물들한테서 도망친 거라고! 저것들은 우리랑은 다르다오, 그리셀다.', `MaleText_loc4`='我们已经摆脱那些怪物了！格里西达，他们和我们截然不同。', `MaleText_loc5`='不，我們逃過那些怪獸了!他們和我們完全不同，葛薩爾妲。', `MaleText_loc7`='No, nosotros escapamos de esos monstruos. No se parecen en nada a nosotros, Griselda.' WHERE `ID`=25702;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신과 난 사냥꾼이오. 늑대인간은 여기 없소. 없고말고.', `MaleText_loc4`='我们是猎人。这里没有狼人。', `MaleText_loc5`='我們是獵人，你和我都是。這裡沒有狼人，女士。', `MaleText_loc7`='Somos cazadores, tú y yo. No hay hombres lobo aquí, no señora.' WHERE `ID`=25703;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='눈을 떼지 마시오! 절대로 잡혀선 안 되오!', `MaleText_loc4`='小姑娘，保持警惕！别让他们抓到我们！', `MaleText_loc5`='留神注意他們，女孩!別讓他們抓住我們!', `MaleText_loc7`='Mantente alerta, chica. ¡No dejes que nos atrapen!' WHERE `ID`=25704;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='킬제덴이 정신을 집중하여 암흑의 기운을 모읍니다.', `MaleText_loc4`='基尔加丹开始引导黑暗能量。', `MaleText_loc5`='基爾加丹開始引導黑暗能量。', `MaleText_loc7`='Kil''jaeden comienza a canalizar energía oscura.' WHERE `ID`=25705;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일어나라, 허약한 것들아! 일어나 스컬지를 섬겨라!', `MaleText_loc4`='站起来吧！效忠天灾军团吧！', `MaleText_loc5`='復甦吧弱者們!復甦並且為天譴軍團服務!', `MaleText_loc7`='¡Levantaos, debiluchos! ¡Levantaos y servid a la Plaga!' WHERE `ID`=25706;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더는 기다릴 수 없다고 너희 지휘관에게 전해라! 대체 동맹을 맺을 생각이 있는 거냐 없는 거냐?', `MaleText_loc4`='你去告诉指挥官，我一刻也呆不下去了！他到底还想不想结盟？！', `MaleText_loc5`='回去告訴你的指揮官，我不會再多等一秒鐘!他到底還要不要盟友?!', `MaleText_loc7`='¡Dile a tu comandante que no esperaré ni un segundo más! ¿Le interesa esta alianza o no?' WHERE `ID`=25707;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마지막 회담 이후로 끝도 없이 여기서 기다렸다! 고라모쉬의 의식은 대체 언제 끝나는 거지?!', `MaleText_loc4`='上次会面之后我就被晾在一边！古拉莫什什么时候才能完成仪式？', `MaleText_loc5`='自從我們上次碰面以來我就一直在等!戈拉莫什麼時候才會完成他的儀式?', `MaleText_loc7`='¡He esperado una eternidad desde nuestra última reunión! ¿Cuándo acabará Goramosh con su ritual?' WHERE `ID`=25708;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n에게 강제 시전 중', `MaleText_loc4`='Casting kill credit on $n', `MaleText_loc5`='正在對$n施展擊殺獎勵', `MaleText_loc7`='Lanzando kill credit sobre $n' WHERE `ID`=25709;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도저히 참을 수가 없군! 난 연합왕자를 대신해 이곳에 왔다. 기다리려고 온 게 아니란 말이다! 고라모쉬가 나를 기다려야 옳은 것 아닌가!', `MaleText_loc4`='无理！我是节点亲王的代表，古拉莫什居然将我晾在一旁！只有他等我的份儿！', `MaleText_loc5`='忍無可忍!我代表的是奈薩斯的王子，我不是來等人的!戈拉莫什應該等我才對!', `MaleText_loc7`='¡Esto es insufrible! ¡Represento a un Príncipe-nexo, no debería tener que esperar! ¡Goramosh debería estar esperándome a mí!' WHERE `ID`=25710;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말리고스는 너희 지휘관이 이 협정을 가장 우선하여 처리할 것이라고 내게 친히 말했다. 이제 길을 비켜라!', `MaleText_loc4`='玛里苟斯亲自向我保证，指挥家会优先处理此次谈判的所有事宜。让我过去！', `MaleText_loc5`='瑪里苟斯親自向我保證過你們的指揮官會把這個協議的內容視為最優先事項。現在就讓我通過!', `MaleText_loc7`='Malygos me aseguró personalmente que tu comandante convertiría los detalles de este acuerdo en su principal prioridad. ¡Ahora déjame pasar!' WHERE `ID`=25711;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나를 더 기다리게 한다면 에테리움과 푸른용군단의 협정을 다시 고려할 수밖에 없다!', `MaleText_loc4`='如果再让我多等一会儿，我就要重新考虑复仇军与蓝龙军团之间的协议了！', `MaleText_loc5`='如果要我再等下去，我就必須要重新考慮考慮以太皇族和藍龍軍團之間的協議了!', `MaleText_loc7`='¡Si tengo que esperar mucho más, me veré obligado a reconsiderar el acuerdo propuesto entre El Etereum y el Vuelo Azul!' WHERE `ID`=25712;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈은 하인일 뿐이다! 더는 못 기다리겠어! 당장 고라모쉬에게 안내해라!', `MaleText_loc4`='你不过是个身份卑微的小杂兵！我不能再等了！立刻带我去见古拉莫什！', `MaleText_loc5`='你不過就是個賤民罷了!我不會再等下去!立刻帶我去找戈拉莫什!', `MaleText_loc7`='¡No eres más que un subordinado! ¡No esperaré más! ¡Llévame ante Goramosh inmediatamente!' WHERE `ID`=25713;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 뭐야? 더 늦어지게 생겼군!', `MaleText_loc4`='什么？还要等？！', `MaleText_loc5`='這是怎麼樣，還要拖延?', `MaleText_loc7`='¿Qué significa esto? ¿Más retrasos?' WHERE `ID`=25715;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 늦었다! 협정은 이미 맺어졌다. 남은 것은 사소한 문제들뿐이지. 아주 사소한 문제 말이다... 바로 너 같은!', `MaleText_loc4`='你来晚了！协议已经达成。只剩下一些无关紧要的细节。比如……如何处理你！', `MaleText_loc5`='你太遲了!條約已經談好了。還差一些細節。小細節...就像是你!', `MaleText_loc7`='¡Llegas demasiado tarde! El acuerdo ya ha sido negociado. Solo faltan los detalles. Pequeños detalles... ¡como tú!' WHERE `ID`=25716;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 향료를 허겁지겁 삼킵니다. 걸신이라도 들린 듯이!', `MaleText_loc4`='%s吞噬了薰香。好胃口！', `MaleText_loc5`='%s吃掉這個薰香。它餓壞了!', `MaleText_loc7`='%s devora el incienso. ¡Está famélico!' WHERE `ID`=25717;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무나 좋습니다! 기운이 가득 찬 향료입니다!', `MaleText_loc4`='真是太棒啦！香味中充斥着能量！', `MaleText_loc5`='真是太棒了!全身充滿著能量!', `MaleText_loc7`='¡Tan bueno! ¡Tan cargado de energía!' WHERE `ID`=25718;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불덩이가 자라나는 데 필요한 것이 여기 다 들어 있습니다!', `MaleText_loc4`='熊熊燃烧的火炬就应该散发出这样浓烈的香味！', `MaleText_loc5`='裡頭有著所有成長中的小焦焰需要的東西!', `MaleText_loc7`='¡Es todo lo que un pequeño agostador puede necesitar!' WHERE `ID`=25719;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 껄껄대며 웃습니다!', `MaleText_loc4`='%s放声大笑！', `MaleText_loc5`='%s邊吼邊笑!', `MaleText_loc7`='¡%s brama de risa!' WHERE `ID`=25720;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제야! 드디어! 우리가 세웠던 계획이 이루어질 것입니다!', `MaleText_loc4`='就是现在！我们的计划生效啦！', `MaleText_loc5`='就是現在!終於!我們的計畫可以生效了!', `MaleText_loc7`='¡Ahora! ¡Al fin! ¡Podemos llevar a cabo nuestros planes!' WHERE `ID`=25721;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무릎을 꿇어라, 보잘것없는 작은 존재여! 라그나로스 님께서 보내신 사자의 권능 앞에 무릎을 꿇어라!', `MaleText_loc4`='渺小的凡人，跪下！向炎魔之王拉格纳罗斯的使者致敬！', `MaleText_loc5`='跪下，渺小的凡人!跪在拉格納羅斯使者的力量前!', `MaleText_loc7`='¡ARRODÍLLATE, PEQUEÑO MORTAL! ¡ARRODÍLLATE ANTE EL PODER DEL HERALDO DE RAGNAROS!' WHERE `ID`=25722;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 모두 불꽃으로 스러지리라!', `MaleText_loc4`='你们都将在火焰中化为灰烬！', `MaleText_loc5`='你們都將死於烈焰之中!', `MaleText_loc7`='¡TODOS FALLECERÉIS EN LAS LLAMAS!' WHERE `ID`=25723;
