UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 호드의 타운카입니다! 이 세계에서 스컬지를 몰아내려고 왔습니다!', `MaleText_loc4`='我是部落的成员，我要消灭天灾军团！', `MaleText_loc5`='我是部落的坦卡族，我來此是為了把天譴軍團趕出這世界!', `MaleText_loc7`='¡Soy un taunka de la Horda y he venido para eliminar a la Plaga de este mundo!', `FemaleText_loc1`='저는 호드의 타운카입니다! 이 세계에서 스컬지를 몰아내려고 왔습니다!', `FemaleText_loc4`='我是部落的成员，我要消灭天灾军团！', `FemaleText_loc5`='我是部落的坦卡族，我來此是為了把天譴軍團趕出這世界!', `FemaleText_loc7`='¡Soy un taunka de la Horda y he venido para eliminar a la Plaga de este mundo!' WHERE `ID`=25726;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳은 비극과 혼돈의 한가운데에서 스컬지에 대항하고 있군요! 호드의 일원이 되기를 잘했습니다.', `MaleText_loc4`='时局动荡不安，我们却顽强地抵御了天灾军团猛烈的攻势！能成为部落的一员真是荣幸。', `MaleText_loc5`='在一切的悲劇和混亂之中，這個地方面對天譴軍團仍屹立不搖!身為部落的一員真好。', `MaleText_loc7`='¡Entre la tragedia y el caos, este lugar continúa desafiando a la Plaga! Me gusta ser parte de la Horda.', `FemaleText_loc1`='이곳은 비극과 혼돈의 한가운데에서 스컬지에 대항하고 있군요! 호드의 일원이 되기를 잘했습니다.', `FemaleText_loc4`='时局动荡不安，我们却顽强地抵御了天灾军团猛烈的攻势！能成为部落的一员真是荣幸。', `FemaleText_loc5`='在一切的悲劇和混亂之中，這個地方面對天譴軍團仍屹立不搖!身為部落的一員真好。', `FemaleText_loc7`='¡Entre la tragedia y el caos, este lugar continúa desafiando a la Plaga! Me gusta ser parte de la Horda.' WHERE `ID`=25727;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽거나 죽이거나, 둘 중 하납니다!', `MaleText_loc4`='我怀着必死的信念投身战斗！', `MaleText_loc5`='我來這裡，不是殺敵就是被殺!', `MaleText_loc7`='¡He venido a matar o morir!', `FemaleText_loc1`='죽거나 죽이거나, 둘 중 하납니다!', `FemaleText_loc4`='我怀着必死的信念投身战斗！', `FemaleText_loc5`='我來這裡，不是殺敵就是被殺!', `FemaleText_loc7`='¡He venido a matar o morir!' WHERE `ID`=25728;
