UPDATE `locales_broadcast_text` SET `MaleText_loc1`='블러드 엘프 보물 중에서 파시는 게 있습니까?', `MaleText_loc4`='你卖这类东西吗？', `MaleText_loc5`='這玩意你有賣嗎?', `MaleText_loc7`='¿Vendes estas cosas?', `FemaleText_loc1`='블러드 엘프 보물 중에서 파시는 게 있나요?', `FemaleText_loc4`='你卖这类东西吗？', `FemaleText_loc5`='這玩意你有賣嗎?', `FemaleText_loc7`='¿Vendes estas cosas?' WHERE `ID`=25731;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 제겐의 칼에 반사되는 햇살을 보고 넋을 잃습니다.', `MaleText_loc4`='%s被塞吉刀刃上反射的光芒迷惑了。', `MaleText_loc5`='%s陶醉在賽吉恩的小刀所反射的陽光之中。', `MaleText_loc7`='%s alucina al ver el reflejo del sol en el cuchillo de Zeh''gehn.' WHERE `ID`=25732;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 정박 중인 배로 시선을 돌리며 시끄럽게 울어댑니다.', `MaleText_loc4`='%s盯着停泊的船只，发出急促的叫声。', `MaleText_loc5`='%s一面緊盯著停泊入港的船，一面滿懷渴望的低語著。', `MaleText_loc7`='%s croa ansiosamente mientras dirige su mirada hacia el barco atracado.' WHERE `ID`=25733;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼 받아라, 못생긴 개굴! 형제 배신 누구인지 보여라!', `MaleText_loc4`='看着我的刀子，蠢货！看着它，告诉我是谁背叛了我的兄弟！', `MaleText_loc5`='嚐嚐我的刀子，你這醜陋的青蛙!吃我一刀，讓我看看誰敢惹我的兄弟!', `MaleText_loc7`='¡Mira bien tú mi cuchillo, susio croador! ¡Míralo y dime quién osa desafiar a mis hermanos!' WHERE `ID`=25734;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 그래, 지맥의 방향이 이미 바뀌었다는 건 알아들었단 말이다. 더는 못 기다리겠군... 당장 고라모쉬를 데려와라!', `MaleText_loc4`='能量线被扭曲了，这我知道。我不能再等下去了……去把古拉莫什叫来！', `MaleText_loc5`='是，是，我已經聽說地脈轉向的事了。我不能再等了...立刻召喚戈拉莫什!', `MaleText_loc7`='Sí, sí, comprendo que la línea Ley ya ha sido desviada. No esperaré más... ¡Llama a Goramosh inmediatamente!' WHERE `ID`=25735;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭풍 바늘이 제대로 작동하는 것처럼 보이는데. 이제 고라모쉬와 협상 조건에 대해 의논할 수 있겠지?', `MaleText_loc4`='湍流之针看上去运转正常嘛。古拉莫什现在一定能抽出时间来谈谈我们的协议吧？', `MaleText_loc5`='你的極濤磁針似乎效果完美。現在戈拉莫什有空進一步談談協議了吧?', `MaleText_loc7`='Tu aguja de flujo ha funcionado a la perfección. ¿Seguro que Goramosh tiene tiempo para continuar hablando del acuerdo propuesto?' WHERE `ID`=25736;
