UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음... 개구리가 자네더러 배신자라는군, "친구".', `MaleText_loc4`='嗯……青蛙说你就是叛徒，我的“朋友”。', `MaleText_loc5`='嗯...青蛙說你是個叛徒，『好夥伴』。', `MaleText_loc7`='Ummm... la rana dice que eres un traidor, "asere".', `FemaleText_loc1`='음... 개구리가 당신보고 배신자라는군요, "친구".', `FemaleText_loc4`='嗯……青蛙说你就是叛徒，我的“朋友”。', `FemaleText_loc5`='嗯...青蛙說你是個叛徒，『好夥伴』。', `FemaleText_loc7`='Ummm... la rana dice que eres un traidor, "asere".' WHERE `ID`=25738;
