UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 해적들이 항상 보물을 땅에 파묻는지 도무지 이해 안 된단 말이죠. 난 말입니다... 보물은 내 손이 닿는 데 두고 싶거든요.', `MaleText_loc4`='真搞不懂为什么有些海盗喜欢把财宝埋起来，你看……我就喜欢将它们放在随手可及的地方。', `MaleText_loc5`='我老是搞不懂為什麼有些海賊要把寶藏埋起來。我...我喜歡把它放在觸手可及的地方。', `MaleText_loc7`='Jamás comprendí pol qué algunos piratas entierran sus tesoros. A mí me gusta tenerlo a mano.' WHERE `ID`=25744;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='점심 먹어야지!', `MaleText_loc4`='开饭了！', `MaleText_loc5`='午餐!', `MaleText_loc7`='¡LA COMIDA!' WHERE `ID`=25745;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거대한 거북배, 파도의 여행자호가 여기서 용의 안식처에 있는 모아키 항구까지 이동합니다.', `MaleText_loc4`='大海龟“踏浪者”将从这个港口游往龙骨荒野的莫亚基港口。', `MaleText_loc5`='巨海龜波濤行者將從此地前往龍骨荒野的默亞基港。', `MaleText_loc7`='La gran tortuga marina Caminante de las Olas viaja desde este muelle hasta Puerto Moa''ki, en el Cementerio de Dragones.' WHERE `ID`=25746;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거북배를 타고 모아키 항구로 가고 싶습니다.', `MaleText_loc4`='我要坐大海龟前往莫亚基港口。', `MaleText_loc5`='我想要乘坐巨海龜前往默亞基港。', `MaleText_loc7`='Me gustaría tomar la gran tortuga marina a Puerto Moa''ki.', `FemaleText_loc1`='거북배를 타고 모아키 항구로 가고 싶어요.', `FemaleText_loc4`='我要坐大海龟前往莫亚基港口。', `FemaleText_loc5`='我想要乘坐巨海龜前往默亞基港。', `FemaleText_loc7`='Me gustaría tomar la gran tortuga marina a Puerto Moa''ki.' WHERE `ID`=25747;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스 증기 쇄빙선 북해의 창날호는 이곳에서 동부 왕국에 속한 바다를 지나 저습지에 있는 메네실 항구까지 항해합니다.', `MaleText_loc4`='联盟的蒸汽动力破冰船“北海之矛”将穿越东部王国的海域，开往湿地的米奈希尔港。', `MaleText_loc5`='聯盟的蒸汽破冰船北矛號由此，越過東部王國的海洋，航向濕地的米奈希爾港。', `MaleText_loc7`='Picanorte, el rompehielos de vapor de la Alianza, navega desde aquí hasta el Puerto de Menethil, en Los Humedales, a través del mar de los Reinos del Este.' WHERE `ID`=25748;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='메네실 항구로 가는 배를 타고 싶습니다.', `MaleText_loc4`='我要坐船前往莫亚基港口。', `MaleText_loc5`='我想要乘船前往米奈希爾港。', `MaleText_loc7`='Quiero tomar el barco al Puerto de Menethil.', `FemaleText_loc1`='메네실 항구로 가는 배를 타고 싶어요.', `FemaleText_loc4`='我要坐船前往莫亚基港口。', `FemaleText_loc5`='我想要乘船前往米奈希爾港。', `FemaleText_loc7`='Quiero tomar el barco al Puerto de Menethil.' WHERE `ID`=25749;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배 한 척이 이곳과 서부경비대 성채를 왕래하오. 가끔은 병사나 특별한 손님이 타기도 하지만, 대체로 보급품을 운반하는 배라오.', `MaleText_loc4`='这里与西部卫戍要塞有船运往来，有时军队和商旅队会搭乘船只，但是大多数时候都是运送急需的补给品。', `MaleText_loc5`='一艘在此地與鎮西要塞之間往返的船，有時候載運部隊偶爾還有一般乘客，但最重要的是運輸補給。', `MaleText_loc7`='Un barco navega entre este lugar y la Fortaleza de la Guardia Oeste, a veces lleva tropas y algún pasajero ocasional, pero la mayoría de las veces lleva suministros de suma necesidad.' WHERE `ID`=25750;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배를 타고 서부경비대 성채로 가고 싶습니다.', `MaleText_loc4`='我要坐船前往西部卫戍要塞。', `MaleText_loc5`='我想搭船前往鎮西要塞。', `MaleText_loc7`='Quiero tomar el barco a la Fortaleza de la Guardia Oeste.', `FemaleText_loc1`='배를 타고 서부경비대 성채로 가고 싶어요.', `FemaleText_loc4`='我要坐船前往西部卫戍要塞。', `FemaleText_loc5`='我想搭船前往鎮西要塞。', `FemaleText_loc7`='Quiero tomar el barco a la Fortaleza de la Guardia Oeste.' WHERE `ID`=25751;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모아키 항구에는 거북배가 둘 있습니다. 파도의 여행자호와 초록섬호라고 하는데, 우누페와 카마구아를 오가는 녀석들이지요.', `MaleText_loc4`='莫亚基港口因两只大海龟“踏浪者”和“绿背岛”而闻名。它们往返于乌努比和卡玛古。', `MaleText_loc5`='默亞基港多虧有兩隻巨海龜:波濤行者與綠島。他們悠游於昂紐沛與卡瑪廓之間。', `MaleText_loc7`='Puerto Moa''ki ha sido bendecido con dos grandes tortugas marinas: Caminante de las Olas e Isla Verde. Nadan entre Unu''pe y Komawa.' WHERE `ID`=25752;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우누페로 가는 거북배를 타고 싶습니다.', `MaleText_loc4`='我要坐大海龟前往乌努比。', `MaleText_loc5`='我想乘坐巨海龜前往昂紐沛。', `MaleText_loc7`='Me gustaría tomar la gran tortuga marina a Unu''pe.', `FemaleText_loc1`='우누페로 가는 거북배를 타고 싶습니다.', `FemaleText_loc4`='我要坐大海龟前往乌努比。', `FemaleText_loc5`='我想乘坐巨海龜前往昂紐沛。', `FemaleText_loc7`='Me gustaría tomar la gran tortuga marina a Unu''pe.' WHERE `ID`=25753;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카마구아로 가는 거북배를 타고 싶습니다.', `MaleText_loc4`='我要坐大海龟前往卡玛古。', `MaleText_loc5`='我想乘坐巨海龜前往卡瑪廓。', `MaleText_loc7`='Me gustaría tomar la gran tortuga marina a Komawa.', `FemaleText_loc1`='카마구아로 가는 거북배를 타고 싶습니다.', `FemaleText_loc4`='我要坐大海龟前往卡玛古。', `FemaleText_loc5`='我想乘坐巨海龜前往卡瑪廓。', `FemaleText_loc7`='Me gustaría tomar la gran tortuga marina a Komawa.' WHERE `ID`=25754;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='노스렌드로 가고 싶은 거군요, 그렇죠? 크라켄 호는 여기를 출발해서 북풍의 땅에 있는 용맹의 성채로 간답니다.', `FemaleText_loc4`='想去诺森德，是吧？蒸汽动力船“海怪号”将载你前往北风苔原的无畏要塞。', `FemaleText_loc5`='急著想到北裂境?蒸汽船海怪號由此航向北風凍原的驍勇要塞。', `FemaleText_loc7`='Tienes ganas de ir a Rasganorte, ¿verdad? El Kraken a vapor navega desde aquí hasta la Fortaleza Denuedo, en la Tundra Boreal.' WHERE `ID`=25755;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용맹의 성채로 가는 배를 타고 싶습니다.', `MaleText_loc4`='我要坐船前往无畏要塞。', `MaleText_loc5`='我想搭船前往驍勇要塞。', `MaleText_loc7`='Quiero tomar el barco a la Fortaleza Denuedo.', `FemaleText_loc1`='용맹의 성채로 가는 배를 타고 싶어요.', `FemaleText_loc4`='我要坐船前往无畏要塞。', `FemaleText_loc5`='我想搭船前往驍勇要塞。', `FemaleText_loc7`='Quiero tomar el barco a la Fortaleza Denuedo.' WHERE `ID`=25756;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노스렌드로 갈 생각이라면, 울부짖는 협만의 발가드까지 가는 쇄빙선인 북해의 창날호를 타면 될 겁니다.', `MaleText_loc4`='想去诺森德的话，就乘坐破冰船“北海之矛”吧。它会载你前往嚎风峡湾的瓦加德。', `MaleText_loc5`='如果你想前去北裂境的話，破冰船北矛號由此航向凜風峽灣的瓦爾加德。', `MaleText_loc7`='Si quieres viajar a Rasganorte, el rompehielos Picanorte navega desde aquí hasta Valgarde, en el Fiordo Aquilonal.' WHERE `ID`=25757;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발가드로 가는 배를 타고 싶습니다.', `MaleText_loc4`='我要坐船前往瓦加德。', `MaleText_loc5`='我想搭船前往瓦爾加德。', `MaleText_loc7`='Quiero tomar el barco a Valgarde.', `FemaleText_loc1`='발가드로 가는 배를 타고 싶어요.', `FemaleText_loc4`='我要坐船前往瓦加德。', `FemaleText_loc5`='我想搭船前往瓦爾加德。', `FemaleText_loc7`='Quiero tomar el barco a Valgarde.' WHERE `ID`=25758;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='용맹의 성채로 갈 생각이라면 이곳과 북풍의 땅을 오가는 화물선을 탈 수 있어요. 어쩌다 한두 명씩 타려는 사람이 있으니 선원들도 별로 신경 쓰지 않을 거예요.', `FemaleText_loc4`='想去无畏要塞的话，就跳上开往北风苔原的货船吧。他们不介意偶尔捎几名旅客的。', `FemaleText_loc5`='如果你想前往驍勇要塞，你可以搭上在此地與北風凍原航行的貨船。他們不在意多一、兩個額外的乘客。', `FemaleText_loc7`='Si quieres llegar a la Fortaleza Denuedo, puedes subirte a bordo del barco de mercancías que circula entre este lugar y la Tundra Boreal. No les importa llevar uno o dos pasajeros de vez en cuando.' WHERE `ID`=25759;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용맹의 성채로 가는 배를 타고 싶습니다.', `MaleText_loc4`='我要坐船前往无畏要塞。', `MaleText_loc5`='我想搭船前往驍勇要塞。', `MaleText_loc7`='Quiero tomar el barco a la Fortaleza Denuedo.', `FemaleText_loc1`='용맹의 성채로 가는 배를 타고 싶어요.', `FemaleText_loc4`='我要坐船前往无畏要塞。', `FemaleText_loc5`='我想搭船前往驍勇要塞。', `FemaleText_loc7`='Quiero tomar el barco a la Fortaleza Denuedo.' WHERE `ID`=25760;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐요! 동부 왕국이 그리운가요? 돌아가고 싶어 몸이 근질근질하다면 크라켄 호를 타고 스톰윈드로 돌아가면 돼요. 아, 따뜻한 공기가 그리워라!', `MaleText_loc4`='嗨！你想念东部王国了吧？如果你想回去的话，“海怪号”正要返回暴风城。那里的气候肯定比这里温暖得多！', `MaleText_loc5`='你好呀!想念東部王國了吧，哈?那麼，如果你思鄉病真的犯了想回去，海怪號將返回暴風港。我懂，我喜歡溫暖的天氣!', `MaleText_loc7`='¡Hola! Echas de menos los Reinos del Este, ¿verdad? Bueno, si realmente quieres volver, el Kraken navega de vuelta a Ventormenta. ¡Yo agradecería un clima más cálido!' WHERE `ID`=25761;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배를 타고 스톰윈드 항구로 가고 싶습니다.', `MaleText_loc4`='我要坐船前往暴风城港口。', `MaleText_loc5`='我想搭船前往暴風港。', `MaleText_loc7`='Quiero tomar el barco al Puerto de Ventormenta.', `FemaleText_loc1`='배를 타고 스톰윈드 항구로 가고 싶어요.', `FemaleText_loc4`='我要坐船前往暴风城港口。', `FemaleText_loc5`='我想搭船前往暴風港。', `FemaleText_loc7`='Quiero tomar el barco al Puerto de Ventormenta.' WHERE `ID`=25762;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 축복받은 거북배, 초록섬호가 이곳과 용의 안식처에 있는 모아키 항구를 왕래합니다.', `MaleText_loc4`='大海龟“绿背岛”将从这个港口游往龙骨荒野的莫亚基港口。', `MaleText_loc5`='我們受祝福的巨海龜，綠島，往返於此地與龍骨荒野的默亞基港。', `MaleText_loc7`='Nuestra bendita gran tortuga marina, Isla Verde, viaja desde aquí hasta Puerto Moa''ki, en el Cementerio de Dragones.' WHERE `ID`=25763;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거북배를 타고 모아키 항구로 가고 싶습니다.', `MaleText_loc4`='我要坐大海龟前往莫亚基港口。', `MaleText_loc5`='我想乘坐巨海龜前往默亞基港。', `MaleText_loc7`='Me gustaría tomar la gran tortuga marina a Puerto Moa''ki.', `FemaleText_loc1`='거북배를 타고 모아키 항구로 가고 싶어요.', `FemaleText_loc4`='我要坐大海龟前往莫亚基港口。', `FemaleText_loc5`='我想乘坐巨海龜前往默亞基港。', `FemaleText_loc7`='Me gustaría tomar la gran tortuga marina a Puerto Moa''ki.' WHERE `ID`=25764;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전에 있던 곳으로 돌아가고 싶으세요? 구름의 입맞춤호를 타면 티리스팔 숲으로 우아하게 날아갈 수 있어요.', `MaleText_loc4`='嗨。你想回到艾泽拉斯世界吗？搭乘“吻云号”返回提瑞斯法林地吧。', `MaleText_loc5`='唷，想要回到舊世界?乘著拂雲號優雅地飛回提里斯法林地吧。', `MaleText_loc7`='Ey. ¿Quieres volver al viejo mundo? Vuela hasta los Claros de Tirisfal con estilo a bordo del Besanubes.' WHERE `ID`=25765;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='티리스팔 숲으로 가는 비행선을 타고 싶습니다.', `MaleText_loc4`='我要坐地精飞艇前往提瑞斯法林地。', `MaleText_loc5`='我想要搭乘飛艇前往提里斯法林地。', `MaleText_loc7`='Quiero tomar el zepelín a los Claros de Tirisfal.', `FemaleText_loc1`='티리스팔 숲으로 가는 비행선을 타고 싶어요.', `FemaleText_loc4`='我要坐地精飞艇前往提瑞斯法林地。', `FemaleText_loc5`='我想要搭乘飛艇前往提里斯法林地。', `FemaleText_loc7`='Quiero tomar el zepelín a los Claros de Tirisfal.' WHERE `ID`=25766;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기요! 노스렌드로 가실 생각이면 질풍호를 타시죠. 북풍의 땅에 있는 전쟁노래 요새로 한 번에 갈 수 있답니다.', `MaleText_loc4`='嗨。你可以乘坐“强风号”前往诺森德。她会载你飞往北风苔原的战歌要塞。', `MaleText_loc5`='嘿，你好呀。如果你想要到北裂境，那麼就搭上強風號吧。她將會帶你直飛往北風凍原的戰歌堡。', `MaleText_loc7`='Hola. Si quieres llegar a Rasganorte, El Viento Poderoso es la mejor manera de ir. Te llevará directamente al Bastión Grito de Guerra, en la Tundra Boreal.' WHERE `ID`=25767;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전쟁노래 요새로 가는 비행선을 타고 싶습니다.', `MaleText_loc4`='我要坐地精飞艇前往战歌要塞。', `MaleText_loc5`='我想要搭乘飛艇前往戰歌堡。', `MaleText_loc7`='Quiero tomar el zepelín al Bastión Grito de Guerra.', `FemaleText_loc1`='전쟁노래 요새로 가는 비행선을 타고 싶어요.', `FemaleText_loc4`='我要坐地精飞艇前往战歌要塞。', `FemaleText_loc5`='我想要搭乘飛艇前往戰歌堡。', `FemaleText_loc7`='Quiero tomar el zepelín al Bastión Grito de Guerra.' WHERE `ID`=25768;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요? 전쟁노래 요새로 갈 생각이세요? 야생의 처녀호를 타면 순식간에 도착할 수 있어요. 노스렌드에서 제일 빠른 비행선이거든요!', `FemaleText_loc4`='嗨，你想去战歌要塞？搭乘“野姑娘号”吧，眨眼工夫就能到。她是诺森德最快的地精飞艇！', `FemaleText_loc5`='嗨，你好嗎?要搭個便車去戰歌堡?野丫頭號可以用全速把你送到那邊。她可是全北裂境最快的飛艇!', `FemaleText_loc7`='Hola, ¿cómo te va? ¿Quieres ir al Bastión Grito de Guerra? La Joven Salvaje te llevará allí en un abrir y cerrar de ojos. ¡Es el zepelín más veloz de todo Rasganorte!' WHERE `ID`=25769;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전쟁노래 요새로 가는 비행선을 타고 싶습니다.', `MaleText_loc4`='我要坐地精飞艇前往战歌要塞。', `MaleText_loc5`='我想要搭乘飛艇前往戰歌堡。', `MaleText_loc7`='Quiero tomar el zepelín al Bastión Grito de Guerra.', `FemaleText_loc1`='전쟁노래 요새로 가는 비행선을 타고 싶어요.', `FemaleText_loc4`='我要坐地精飞艇前往战歌要塞。', `FemaleText_loc5`='我想要搭乘飛艇前往戰歌堡。', `FemaleText_loc7`='Quiero tomar el zepelín al Bastión Grito de Guerra.' WHERE `ID`=25770;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='노스렌드가 기다리고 있어요. 멋진 구름의 입맞춤호를 타면 바다 건너 울부짖는 협만에 있는 복수의 상륙지까지 곧장 갈 수 있죠.', `FemaleText_loc4`='$r，诺森德等你去开拓。“吻云号”会载你前往嚎风峡湾的复仇港。', `FemaleText_loc5`='北裂境在等著你，$r。雄偉的拂雲號將會帶你渡過汪洋，前往凜風峽灣的復仇臺地。', `FemaleText_loc7`='Rasganorte aguarda, $r. El majestuoso Besanubes te llevará a través del mar hasta Campo Venganza en el Fiordo Aquilonal.' WHERE `ID`=25771;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='복수의 상륙지로 가는 비행선을 타고 싶습니다.', `MaleText_loc4`='我要坐地精飞艇前往复仇港。', `MaleText_loc5`='我想要搭乘飛艇前往復仇臺地。', `MaleText_loc7`='Quiero tomar el zepelín a Campo Venganza.', `FemaleText_loc1`='복수의 상륙지로 가는 비행선을 타고 싶어요.', `FemaleText_loc4`='我要坐地精飞艇前往复仇港。', `FemaleText_loc5`='我想要搭乘飛艇前往復仇臺地。', `FemaleText_loc7`='Quiero tomar el zepelín a Campo Venganza.' WHERE `ID`=25772;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='집에 가는 건가요, $c님? 집이 칼림도어라면 질풍호를 타고 가면 됩니다. 듀로타까지 곧장 날아간다고요.', `MaleText_loc4`='$c，想回家吗？如果你住在卡利姆多的话，“强风号”可以送你一程。她将直接飞往杜隆塔尔。', `MaleText_loc5`='回家嗎，$c?如果你家在卡林多的話，強風號可以帶你過去。她從這裡直飛杜洛塔。', `MaleText_loc7`='¿Vas a casa, $c? El Viento Poderoso te llevará hasta allí si tu hogar está en Kalimdor. Vuela directamente desde aquí hasta Durotar.' WHERE `ID`=25773;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비행선을 타고 듀로타로 가고 싶습니다.', `MaleText_loc4`='我要坐地精飞艇前往杜隆塔尔。', `MaleText_loc5`='我想搭飛艇去杜洛塔。', `MaleText_loc7`='Quiero tomar el zepelín a Durotar.', `FemaleText_loc1`='비행선을 타고 듀로타로 가고 싶어요.', `FemaleText_loc4`='我要坐地精飞艇前往杜隆塔尔。', `FemaleText_loc5`='我想搭飛艇去杜洛塔。', `FemaleText_loc7`='Quiero tomar el zepelín a Durotar.' WHERE `ID`=25774;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 빨리! 더 빨리 움직여라! 이 장비들을 오늘 코르크론 선봉기지에 전달해야 한다!', `MaleText_loc4`='快！快！这些武器必须今天送抵库卡隆先锋营地！', `MaleText_loc5`='快點!快點!這些裝備今天一定得要送到柯爾克隆先鋒駐地!', `MaleText_loc7`='¡Más deprisa! ¡Más deprisa! ¡Estos armamentos han de ser entregados en la Vanguardia Kor''kron HOY!' WHERE `ID`=25775;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희를 쫓아내고 고블린을 고용해 버릴까! 날 실망시키지 마라!', `MaleText_loc4`='如果能用地精将你们统统替换掉，我会很高兴的！别让我失望！', `MaleText_loc5`='我會開心地用哥布林來頂替你的位置!不要讓我失望!', `MaleText_loc7`='¡Estaré encantado de cambiaros por goblins! ¡No me falléis!' WHERE `ID`=25776;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아그마르 대군주께서는 우리에게 더 많은 것을 기대하고 계신다! 그분을 실망시켜 드려서는 안 된다!', `MaleText_loc4`='阿格玛大王等着我们的好消息呢！我们不能让他失望！', `MaleText_loc5`='霸主阿格瑪要我們做得更好!不要讓他失望!', `MaleText_loc7`='¡El señor supremo Agmar espera más de nosotros! ¡No debemos decepcionarle!' WHERE `ID`=25777;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 이 상자 위에서 뛰어내리게 하지 마라! 눈에서 별이 보이게 해 주마, 이 게으른 오크 녀석들.', `MaleText_loc4`='别逼我从箱子上跳下来！我会把你痛打一顿的。', `MaleText_loc5`='不要讓我跌下這個箱子!我會揍扁你的腦袋，獸人。', `MaleText_loc7`='¡No me hagas saltar de este cajón! ¡Te aplastaré la cabeza, orco!' WHERE `ID`=25778;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='복수의 상륙지로 가려는 거야? 야생의 처녀호를 타면 24시간 언제라도 왕복할 수 있다고.', `MaleText_loc4`='嗨，你想去复仇港吗？欢迎搭乘“野姑娘号”往返航班，全天24小时服务。', `MaleText_loc5`='唷，想到搭個便車到復仇臺地嗎?野丫頭號往返兩地，全年無休。', `MaleText_loc7`='Ey. ¿Quieres llegar a Campo Venganza? La Joven Salvaje hace trayectos de ida y vuelta, de día y de noche.' WHERE `ID`=25779;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비행선을 타고 복수의 상륙지로 가고 싶습니다.', `MaleText_loc4`='我要坐地精飞艇前往复仇港。', `MaleText_loc5`='我想要搭乘飛艇前往復仇臺地。', `MaleText_loc7`='Quiero tomar el zepelín a Campo Venganza.', `FemaleText_loc1`='비행선을 타고 복수의 상륙지로 가고 싶어요.', `FemaleText_loc4`='我要坐地精飞艇前往复仇港。', `FemaleText_loc5`='我想要搭乘飛艇前往復仇臺地。', `FemaleText_loc7`='Quiero tomar el zepelín a Campo Venganza.' WHERE `ID`=25780;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐요, 예쁜 아가씨. 이 제부탄에게 융단이 두 장 있는데, 여기 와서 몸이라도 좀 녹이고 가지 않겠어요?', `MaleText_loc4`='嘿，美人儿，塞布坦有两条毯子！为什么不过来一起暖和缓和呢，嗯？', `MaleText_loc5`='嗨，漂亮的小妞，齊布坦這裡有兩條破毯子!為什麼不來幫他暖一暖身子呢，嗯?', `MaleText_loc7`='¡Hey bella señorita! ¡Zebu''tan tiene dos alfombras aquí! ¿Por qué no vienes y le das calorcito?' WHERE `ID`=25781;
