UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='준비됐니, 깡총 군? 나한테 바싹 붙어서 늑대가 오는지 잘 지켜봐야 해!', `FemaleText_loc4`='小毛球，准备好了吗？靠近我，小心这些狼！', `FemaleText_loc5`='你準備好了嗎，軟綿綿先生?待在我身邊，小心那些狼!', `FemaleText_loc7`='¿Estás listo, Floppy? ¡Quédate cerca de mí y ten cuidado con los lobos!' WHERE `ID`=25802;
