UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼을 무사히 분리하셨군요! 그럼 이제 제 눈이 되어 주어야겠습니다. 함께 깊숙한 곳까지 들어가지요.', `MaleText_loc4`='你成功释放了自己的灵魂！现在你可以充当我的眼睛了。让我们找出真相。', `MaleText_loc5`='你成功解放你的靈魂了!你可以當我的眼睛。我們一起來弄清楚這究竟是怎麼回事。', `MaleText_loc7`='¡Has conseguido liberar tu espíritu! Ahora serás mis ojos. Juntos llegaremos hasta el fondo de la cuestión.' WHERE `ID`=25811;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드에 대한 배신과 기타 반역 혐의로 여기 언급된 이들에게 현상금을 건다!$B$B보상은 고르트 경비대장님께서 내리실 것이다.', `MaleText_loc4`='悬赏猎杀部落叛徒！$B$B赏金由高尔特上尉提供。', `MaleText_loc5`='懸賞: 殺死所有通敵背叛部落的傢伙!$B$B苟爾特隊長會支付全額賞金。', `MaleText_loc7`='¡Se busca MUERTO por traición y otros actos traicioneros contra la Horda!$B$BTodas las recompensas serán pagadas por el capitán Gort.' WHERE `ID`=25812;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마을에 거의 다 왔군요. 주위를 잘 살펴보십시오.', `MaleText_loc4`='你已经到村子上方了。睁大你的眼睛。', `MaleText_loc5`='你現在進入村莊了。睜大眼睛注意四週。', `MaleText_loc7`='Estás llegando al poblado. Mantén los ojos bien abiertos.' WHERE `ID`=25813;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='순간이동기 사용을 허가해 주십시오. 준비됐습니다!', `MaleText_loc4`='开始传送吧，我准备好了！', `MaleText_loc5`='替我淨空傳送器，我已經準備好了!', `MaleText_loc7`='Da el visto bueno para que use el teletransportador. ¡Es el momento!', `FemaleText_loc1`='순간이동기 사용을 허가해 주세요. 준비됐습니다!', `FemaleText_loc4`='开始传送吧，我准备好了！', `FemaleText_loc5`='替我淨空傳送器，我已經準備好了!', `FemaleText_loc7`='Da el visto bueno para que use el teletransportador. ¡Es el momento!' WHERE `ID`=25814;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호수 바닥이 어떻게 된 거지요? 이상한 힘이 흘러나오고 있는데요.', `MaleText_loc4`='湖床上发生了什么事？有奇怪的能量从那里涌出。', `MaleText_loc5`='湖床發生了什麼事情?奇怪的力量從底下不斷冒出來。', `MaleText_loc7`='¿Qué ha ocurrido con el lecho del lago? Emana una energía extraña.' WHERE `ID`=25815;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요! 고소공포증 따위는 없으시길 빕니다!$b$b여기 연습용 낙하산이 있어요. 빨리 착륙할 때 쓰는 물건이죠. 부드럽게 날아서 내려서고 싶으면 비행기를 타든지 하세요. 아드레날린이 솟구치는 기분을 느끼고 싶다면, 뛰어내리는 겁니다. 그리고 마지막 순간에 낙하산을 펴는 거죠. 원래 그렇게 쓰라고 만들어진 물건이라고요. 번개 같은 움직임 말입니다! 하실 수 있겠어요?$b$b낙하산은 몇 초밖에 쓸 수 없으니, 시간을 잘 맞춰야 할 겁니다. 솔직히 당신은 이걸 잘 다룰 사람으로 보이진 않네요, $c님. 제 눈이 틀렸다는 걸 당신이 증명해 주시면 좋겠군요.', `MaleText_loc4`='欢迎你，$c！希望你没有恐高症！$b$b我为你准备了练习用的降落伞。它们是在紧急着陆时使用的。如果你想要缓缓落地，还不如骑着坐骑随便蹦两下呢。如果你想体验极速快感，就要从高处跳下来，在快到落地时打开降落伞！动作要快！你的反应够快吗？$b$b降落伞的效果只能持续几秒，因此你必须在适当的时机使用它。不知道你能不能掌握其中的诀窍。希望你成功。', `MaleText_loc5`='歡迎，$c!希望你沒有懼高症!$b$b我替你拿了一件練習用降落傘。這個是用來快速降落用的。如果你是想四處遨翔的話，找隻坐騎比較快。如果你想追求刺激或是什麼腎上腺素的快感，你可以直接跳下去。然後在最後一個安全點之前拉開降落傘。這東西就是這麼運作。動作快!你準備好要來點刺激了嗎?$b$b降落傘只會維持幾秒鐘。所以你需要精準地把握時間。我不確定你是不是能控制它，$c。我希望你能證明我的猜想是錯的。', `MaleText_loc7`='¡$gBienvenido:Bienvenida;, $c! ¡Espero que no te den miedo las alturas!$b$bTengo un paracaídas de prácticas para ti. Estos se usan para aterrizajes rápidos. Si quieres caer suavemente, usa una montura. Si quieres acción y un subidón de adrenalina: tírate y abre el paracaídas lo más tarde posible. Para eso están. ¡Acción rápida! ¿Te apetece un poco de acción rápida?$b$bEl salto solo dura unos segundos. Así que tendrás que calcular bien el tiempo. No tengo claro que seas capaz de hacerlo, $c. A ver si me demuestras lo contrario.', `FemaleText_loc1`='안녕하세요! 고소공포증 따위는 없으시길 빌어요!$b$b여기 연습용 낙하산이 있어요. 빨리 착륙할 때 쓰는 물건이죠. 부드럽게 날아서 내려서고 싶으면 비행기를 타든지 하세요. 아드레날린이 솟구치는 기분을 느끼고 싶다면, 뛰어내리는 겁니다. 그리고 마지막 순간에 낙하산을 펴는 거죠. 원래 그렇게 쓰라고 만들어진 물건이라고요. 번개 같은 움직임 말이에요! 하실 수 있겠어요?$b$b낙하산은 몇 초밖에 쓸 수 없으니, 시간을 잘 맞춰야 할 겁니다. 솔직히 당신은 이걸 잘 다룰 사람으로 보이진 않네요, $c님. 제 눈이 틀렸다는 걸 당신이 증명해 주시길 바라요.', `FemaleText_loc4`='欢迎你，$c！希望你没有恐高症！$b$b我为你准备了练习用的降落伞。它们是在紧急着陆时使用的。如果你想要缓缓落地，还不如骑着坐骑随便蹦两下呢。如果你想体验极速快感，就要从高处跳下来，在快到落地时打开降落伞！动作要快！你的反应够快吗？$b$b降落伞的效果只能持续几秒，因此你必须在适当的时机使用它。不知道你能不能掌握其中的诀窍。希望你成功。', `FemaleText_loc5`='歡迎，$c!希望你沒有懼高症!$b$b我替你拿了一件練習用降落傘。這個是用來快速降落用的。如果你是想四處遨翔的話，找隻坐騎比較快。如果你想追求刺激或是什麼腎上腺素的快感，你可以直接跳下去。然後在最後一個安全點之前拉開降落傘。這東西就是這麼運作。動作快!你準備好要來點刺激了嗎?$b$b降落傘只會維持幾秒鐘。所以你需要精準地把握時間。我不確定你是不是能控制它，$c。我希望你能證明我的猜想是錯的。', `FemaleText_loc7`='¡$gBienvenido:Bienvenida;, $c! ¡Espero que no te den miedo las alturas!$b$bTengo un paracaídas de prácticas para ti. Estos se usan para aterrizajes rápidos. Si quieres caer suavemente, usa una montura. Si quieres acción y un subidón de adrenalina: tírate y abre el paracaídas lo más tarde posible. Para eso están. ¡Acción rápida! ¿Te apetece un poco de acción rápida?$b$bEl salto solo dura unos segundos. Así que tendrás que calcular bien el tiempo. No tengo claro que seas capaz de hacerlo, $c. A ver si me demuestras lo contrario.' WHERE `ID`=25816;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼... 안 돼! 내 동족이 모두 죽거나 미쳐버리다니!', `MaleText_loc4`='不……不！我的族人要么变成了亡魂，要么丧失了心智！', `MaleText_loc5`='不...不!我的同胞不是死了就是瘋了!', `MaleText_loc7`='No... ¡no! ¡Mi gente se ha convertido en espíritus muertos o se ha vuelto loca!' WHERE `ID`=25817;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저쪽에 있는 조각상, 장로 마나로아가 당신을 보고 있군요. 이건 좋은 징조입니다!', `MaleText_loc4`='那是长者玛纳洛的雕像，它注视着你。这是个好兆头！', `MaleText_loc5`='長者馬納洛亞，就是那尊雕像，正看著你。這是個好兆頭!', `MaleText_loc7`='El ancestro Mana''loa, esa estatua de ahí, te ve. ¡Esta es una buena señal!' WHERE `ID`=25818;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌아오십시오, $n 님. 육체에서 너무 오래 떨어져 있으면 돌아오지 못할 수도 있답니다. 의논할 것이 많군요.', `MaleText_loc4`='回来吧，$n。如果你的灵魂离开肉体太久的话，可能会回不去的。我们需要好好谈一谈。', `MaleText_loc5`='回來吧，$n。如果你離開你的軀體太久，你就得承擔回不來的風險。我們得好好談談。', `MaleText_loc7`='Vuelve, $n. Si pasas demasiado tiempo fuera de tu cuerpo, corres el riesgo de no poder volver. Tenemos mucho de lo que hablar.' WHERE `ID`=25819;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하쉽니까! 앉아서 한 잔 하쉬지 그래요?', `MaleText_loc4`='你好啊，伙计！坐下来喝一杯吧，怎么样？', `MaleText_loc5`='早安，朋友!找個位置坐下喝點什麼，好吧?', `MaleText_loc7`='¡Buenas, colega! Siéntate y echa un trago.' WHERE `ID`=25820;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그로그주가 더 필요합니다, 맥.', `MaleText_loc4`='再来两杯好酒，马克。', `MaleText_loc5`='麥客，給我上好的美酒。', `MaleText_loc7`='Necesito algo más de tu magnifico grog, Mack.', `FemaleText_loc1`='그로그주가 더 필요해요, 맥.', `FemaleText_loc4`='再来两杯好酒，马克。', `FemaleText_loc5`='麥客，給我上好的美酒。', `FemaleText_loc7`='Necesito algo más de tu magnifico grog, Mack.' WHERE `ID`=25821;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 지금입니다, 영웅들이여! 기만자가 약해진 틈을 타 공격하십시오!', `MaleText_loc4`='趁他虚弱时发动攻击！杀死基尔加丹！', `MaleText_loc5`='上啊，英雄們，趁他現在最虛弱的時候!戰勝詐欺者!', `MaleText_loc7`='¡Atacad ahora, héroes, mientras está debilitado! ¡Eliminad al Falsario!' WHERE `ID`=25822;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐... 여기, 우체통 옆이네. 빨리 오게. 미행한 자가 없는지 확인하고.', `MaleText_loc4`='嘘……这里，邮箱旁边。快过来，你没有被跟踪吧。', `MaleText_loc5`='嘿...這裡，郵箱旁邊啦。趕快過來，還要確保你沒有被跟蹤喔。', `MaleText_loc7`='Pssst... Aquí, en el buzón. Ven deprisa y asegúrate de que no te sigue nadie.' WHERE `ID`=25823;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그대가 자랑스럽군요.', `FemaleText_loc4`='我为你感到骄傲，孩子。', `FemaleText_loc5`='孩子，我為你感到驕傲。', `FemaleText_loc7`='Estoy orgullosa de ti, pequeño.' WHERE `ID`=25824;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그대라면 호드의 위대한 용사가 될 수 있을 겁니다.', `FemaleText_loc4`='你会成为部落出色的战士的。', `FemaleText_loc5`='你會成為部落優秀的戰士。', `FemaleText_loc7`='Serás un gran guerrero de la Horda.' WHERE `ID`=25825;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우린 얼음안개를 되찾을 겁니다. 우리 도시에서 아눕아르들을 몰아낼 겁니다.', `FemaleText_loc4`='我们要夺回冰雾村，将阿努巴尔赶出我们的家园。', `FemaleText_loc5`='我們將奪回冰霧村，把阿努巴族從我們的城市中趕出去。', `FemaleText_loc7`='Retomaremos Bruma de Hielo. Los Anub''ar serán expulsados de nuestra ciudad.' WHERE `ID`=25826;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아직 최악의 상대가 남았답니다. 이제 우린 리치 왕의 왕국을 멸망시킬 겁니다.', `FemaleText_loc4`='最艰难的时刻已经过去了。我们很快就能推翻巫妖王的暴政。', `FemaleText_loc5`='最糟的情況已經結束了，用不了多久，我們就會終結巫妖王統治。', `FemaleText_loc7`='Ya hemos pasado lo peor. Pronto acabaremos con el reinado del Rey Exánime.' WHERE `ID`=25827;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 풀어줘라, 이 악마들아!', `MaleText_loc4`='放我出去，朋友！', `MaleText_loc5`='朋友，放我出去!', `MaleText_loc7`='¡Soltadme, demonios!' WHERE `ID`=25828;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 무슨 신을 믿는지 알 바 아니지만, 내가 풀려나지 않기를 비는 게 좋을 거다!', `MaleText_loc4`='你最好祈祷我永远也出不来！', `MaleText_loc5`='最好向你信的神祈禱我不會被放出來!', `MaleText_loc7`='¡Rezad a los dioses en los que creáis para que nunca me liberen!' WHERE `ID`=25829;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 속박에서 벗어나는 날에는 네 녀석들을 모두 지옥으로 되돌려보내 주마!', `MaleText_loc4`='我要冲破禁锢我的牢笼，将你们统统送进地狱！', `MaleText_loc5`='我將破除束縛，並把你送回你來的地獄去!', `MaleText_loc7`='¡Romperé estas ataduras que me retienen y os enviaré de vuelta al infierno del que salisteis!' WHERE `ID`=25830;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 녀석들의 고문 따위에는 굴복하지 않는다! 절대로!', `MaleText_loc4`='我不会屈服的！绝不！', `MaleText_loc5`='不管你怎麼折磨我，我也不會屈服的!永遠!', `MaleText_loc7`='¡Nunca sucumbiré a tus torturas! ¡NUNCA!' WHERE `ID`=25831;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 마을회관으로 이동하시오! 우리가 무기를 가져왔소! 장비를 갖추고 스컬지 놈들을 몰아냅시다!', `MaleText_loc4`='大家都到市政厅去！我们带来了一批武器！大家都武装起来，把天灾军团赶走！', `MaleText_loc5`='快躲進市政廳，所有人都要!我把武器帶來了!武裝自己，擊退天譴軍!', `MaleText_loc7`='¡Todos al concejo! ¡Os hemos traído armas! ¡Armaos y detened a la Plaga!' WHERE `ID`=25832;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽어라!', `MaleText_loc4`='杀！', `MaleText_loc5`='殺戮時刻!', `MaleText_loc7`='¡Hora de matar!' WHERE `ID`=25833;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='때가 되었군! 안 그래도 백골이 따분하던 참이다!', `MaleText_loc4`='是时候了！鲁瑞德早就耐不住了！', `MaleText_loc5`='是時候了!路瑞德越來越無聊。', `MaleText_loc7`='¡Ya era hora! Escabroso empezaba a aburrirse.' WHERE `ID`=25834;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아서스의 애완견이로군? 죽어라!', `MaleText_loc4`='阿尔萨斯的走狗？去死吧！', `MaleText_loc5`='你是阿薩斯的走狗?受死吧!', `MaleText_loc7`='¿Tú perrito faldero de Arthas? ¡Tú morir!' WHERE `ID`=25835;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋게 끝날 거라고는 생각하지 마라!', `MaleText_loc4`='你不会……有好下场的！', `MaleText_loc5`='對你來說...也許不是什麼好結局!', `MaleText_loc7`='¡Esto no acabar... bien para ti!' WHERE `ID`=25836;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 백골... 당신과 함께 일하는 데도 익숙해지는군.', `MaleText_loc4`='鲁瑞德和你……应该能够合作的。', `MaleText_loc5`='路瑞德會習慣...跟你一起工作的。', `MaleText_loc7`='Escabroso podría acostumbrarse... a trabajar contigo.' WHERE `ID`=25837;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 원했던 건 다시 한 번 내 왕을 섬기는 것뿐이었소. 인류를 위해, 인류의 공적에 맞서 싸우고 싶었지.$B$B하지만 우리는 이교도들에게 제압당했고... 이 타락의 근원이 되는 모든 징조가 낙사나르를 향하고 있소.', `MaleText_loc4`='我一直希望能再次为国王效劳。出于人道精神，一起对抗共同的敌人。$B$B但是我发现有教徒混进了我们中间……而所有证据都表明，纳克萨纳尔就是这场灾难的源头。', `MaleText_loc5`='我所盼望的只是再度為吾王效命，為了人類，對抗共同的敵人。$B$B但是，我發現我們的人被神教的敗類所滲透了...而種種的跡象都指向了納克薩爾，正是這個敗壞的源頭。', `MaleText_loc7`='Todo lo que deseaba era volver a servir a mi rey. Por la humanidad, contra un enemigo común.$B$BPero sin embargo descubro que hay inmundos cultores infiltrados entre nosotros... y todas las señales apuntan hacia Naxxanar como origen de esta podredumbre.' WHERE `ID`=25838;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들의 지도자는 여기서 모든 이교도에게 명령을 내린다오. 녀석이 곧 모습을 드러낼 거요.$B$B절대로 이 기회를 놓쳐서는 안 되오.', `MaleText_loc4`='教徒接到的指令都来自于他们的首领。这家伙也许很快就会出现。$B$B这是个好机会。', `MaleText_loc5`='這裡就是教徒命令傳來的地方。他們的領導人一定馬上就會現身了。$B$B別把機會錯過了。', `MaleText_loc7`='De aquí es de donde vienen las órdenes de los cultores. Su líder aparecerá pronto.$B$BNo dejemos pasar esta oportunidad.' WHERE `ID`=25839;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꼭 해냅시다, 타사리안. 지금이 아니면 다시는 못 할 겁니다.', `MaleText_loc4`='动手吧，萨萨里安。否则就再也没机会了。', `MaleText_loc5`='一起上吧，薩沙理安。不做就沒機會了。', `MaleText_loc7`='Hagámoslo, Thassarian. Es ahora o nunca.', `FemaleText_loc1`='꼭 해냅시다, 타사리안. 지금이 아니면 다시는 못 할 겁니다.', `FemaleText_loc4`='动手吧，萨萨里安。否则就再也没机会了。', `FemaleText_loc5`='一起上吧，薩沙理安。不做就沒機會了。', `FemaleText_loc7`='Hagámoslo, Thassarian. Es ahora o nunca.' WHERE `ID`=25840;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게.. 대체 무슨 일이...', `MaleText_loc4`='怎么回事……我怎么了？', `MaleText_loc5`='怎麼回事...我怎麼了?', `MaleText_loc7`='¿Qué... qué me sucedió?' WHERE `ID`=25841;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오빠! 살아 있었구나!', `FemaleText_loc4`='萨萨里安！你还活着！', `FemaleText_loc5`='薩沙理安!你還活著!', `FemaleText_loc7`='¡Thassarian! ¡Estás vivo!' WHERE `ID`=25842;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='난... 난 오빠가 죽은 줄만 알았어.', `FemaleText_loc4`='我还以为……还以为你已经死了。', `FemaleText_loc5`='我還以為...還以為你已經死了。', `FemaleText_loc7`='Pensé que... Pensé que estabas... muerto.' WHERE `ID`=25843;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='레리사! 너, 너 괜찮니?', `MaleText_loc4`='莉蕾萨……你……你没事吧？', `MaleText_loc5`='蕾瑞莎...妳...妳沒事!', `MaleText_loc7`='Leryssa, ¡e-estás bien!' WHERE `ID`=25844;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직은 너와 함께 돌아갈 수 없어, 레리사. 난 스컬지와 볼일이 남았거든.', `MaleText_loc4`='我还不能跟你回家，莉蕾萨。我和天灾军团之间的账还没有算清呢。', `MaleText_loc5`='我還不能和妳回家，蕾瑞莎。我和天譴軍團之間的帳還沒算清楚。', `MaleText_loc7`='Aún no puedo regresar a casa contigo, Leryssa. No he terminado del todo con la Plaga.' WHERE `ID`=25845;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 말이 맞을지도 모르지. 난 조국에 대한 임무는 끝냈다. 하지만 아직 나 자신에게 빚진 게 있어.', `MaleText_loc4`='也许你是对的，莉蕾萨。我早已经不再亏欠我的祖国和国王任何东西，可是……我还欠自己一个交代。', `MaleText_loc5`='妳也許是對的，妹妹。我對吾土與吾王的責任已盡。但是，我對自己卻還有所虧欠。', `MaleText_loc7`='Tal vez tengas razón, hermana. He cumplido con mis obligaciones con mi tierra y mi rey. Pero todavía tengo pendiente algo personal.' WHERE `ID`=25846;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으어어... 머리가 깨질 것 같아...', `MaleText_loc4`='啊……我感到头晕目眩。', `MaleText_loc5`='啊!我感到頭暈目眩...', `MaleText_loc7`='Ah... mi cabeza gira sin parar.' WHERE `ID`=25847;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='싫어! 가지 마! 오빠는 나라를 위해 싸운다지만, 누가 인정해 줄 것 같아? 여기 보낸 건 죽으라는 소리라고!', `FemaleText_loc4`='别再离我而去了！你想为你的祖国而战，可你的祖国根本不愿意接纳你！他们派你来送死！', `FemaleText_loc5`='別再離開我!你希望能為了你的家園奮戰，但是他們根本不想要你!他們派你來送死的!', `FemaleText_loc7`='¡No vuelvas a dejarme! ¡Quieres que luche por tu pueblo, pero ni siquiera te quieren a ti! ¡Te enviaron aquí a morir!' WHERE `ID`=25848;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='난 그 표정이 뭔지 알아. 내가 뭐라고 해도 안 되는 거겠지. 하지만 오빠가 또 죽으면...', `FemaleText_loc4`='你的眼神说明了一切……我说服不了你。别再让我听到你的噩耗了……', `FemaleText_loc5`='我認得你那個眼神...我是不可能說服你不要去的了。如果你又送命...', `FemaleText_loc7`='Conozco esa mirada: no lograré disuadirte de esto. Si te me mueres una vez más…' WHERE `ID`=25849;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='걱정하지 마, 레리사. 무슨 일이 있어도 난 돌아갈 거다. 넌 세상에 단 하나 남은 내 가족이니까.', `MaleText_loc4`='别担心，莉蕾萨。我完成使命后就回去找你。那时，世界上就再也没有任何东西能阻挡我回家的脚步了。', `MaleText_loc5`='別擔心，蕾瑞莎。事情結束之後，我會回到妳身邊的。世上沒有任何東西，能阻止我回到唯一的親人身邊。', `MaleText_loc7`='No te preocupes, Leryssa. Regresaré a ti cuando haya terminado. Nada en el mundo evitará que regrese a casa con la única familia que me queda.' WHERE `ID`=25850;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='항구를 차지했소! 적들을 몰아냈소! 태양너울은 우리 차지요!', `MaleText_loc4`='我们占领了港口！敌人已经落败，阳湾港属于我们！', `MaleText_loc5`='我們拿下了港口!敵人已經被打退了。日境是我們的了!', `MaleText_loc7`='¡Hemos tomado el puerto! El enemigo ha sido expulsado. ¡Tramo del Sol es nuestro!' WHERE `ID`=25851;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도망쳐!', `MaleText_loc4`='赶紧逃命吧，朋友！', `MaleText_loc5`='老兄，逃命吧!', `MaleText_loc7`='¡Corre por tu vida, colega!' WHERE `ID`=25852;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스컬지가 사방에 깔렸다!', `MaleText_loc4`='朋友，这里到处都是天灾军团！', `MaleText_loc5`='老兄，到處都是天譴軍!', `MaleText_loc7`='¡La plaga está por todas partes!' WHERE `ID`=25853;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='조그만 $n, 왜 나를 불러낸 것인가? 그대도 이 땅의 트롤과 한편인가? 나를 죽이고 내 힘을 차지하려고 온 것인가?', `FemaleText_loc4`='$n，为什么召唤我？你和这里的巨魔在策划什么阴谋？你想要杀死我，夺取我的力量吗？', `FemaleText_loc5`='親愛的小$n，為什麼要召喚我?你和這塊土地上的食人妖合作了嗎?你要來殺死我並且佔據我的力量嗎?', `FemaleText_loc7`='$gPequeño:Pequeña; $n, ¿por qué me llamas? ¿Estás colaborando con los trols de esta tierra? ¿Has venido a matarme y quedarte con mi poder?' WHERE `ID`=25854;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='트롤 모두 알아서 살아남아야 해!', `MaleText_loc4`='朋友，各自保命吧！', `MaleText_loc5`='每個食人妖各自顧各自的吧，老兄!', `MaleText_loc7`='¡Cada trol tiene que hacer lo que más le conviene!' WHERE `ID`=25855;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저리 비켜!', `MaleText_loc4`='别挡道！', `MaleText_loc5`='不要擋路，老兄!', `MaleText_loc7`='¡Aparta de mi camino, colega!' WHERE `ID`=25856;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드락타론은 끝장이야, 친구!', `MaleText_loc4`='达克萨隆要塞失守了！', `MaleText_loc5`='老兄，德拉克薩隆要淪陷啦!', `MaleText_loc7`='¡Drak''Tharon está perdida, colega!' WHERE `ID`=25857;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스컬지가 사방에 깔렸다!', `MaleText_loc4`='这里到处都是天灾军团！', `MaleText_loc5`='到處都是天譴軍團啊!', `MaleText_loc7`='¡La plaga está por todas partes!' WHERE `ID`=25858;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달려!!', `MaleText_loc4`='快跑！', `MaleText_loc5`='快跑!', `MaleText_loc7`='¡Cooooorreeeeee!' WHERE `ID`=25859;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너는 큰 실수를 했다, 필멸의 존재여... 도망칠 곳은... 없다...', `MaleText_loc4`='凡人，你犯了个致命的错误……别想逃跑……', `MaleText_loc5`='凡人，你犯下了滔天大禍了...你逃不出去啦...', `MaleText_loc7`='Hassss cometido un error tremendo, mortal... no hay essscapatoria...' WHERE `ID`=25860;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배신자들아! 심판의 날과 함께 너의 종말도 다가올 거다! 네 잘난 리치 왕이 선조의 심판에서 널 구해줄 수 있는지 보자! 죽어라!', `MaleText_loc4`='叛徒！审判之日已经来临，你的死期也到了！我倒要看看你效忠的巫妖王能否让你逃脱命运的审判！死吧！', `MaleText_loc5`='叛徒!報應的時候來了，這也會是你的死期!在祖靈的審判面前，看看你的巫妖王還有沒有辦法拯救你!受死吧!', `MaleText_loc7`='¡Traidores! ¡El día del Juicio Final se acerca y con él su fin! ¡Entonces veremos si su Rey Exánime puede librarlos del juicio de los ancestros! ¡Ahora mueran!' WHERE `ID`=25861;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안비나의 희생은 우리 모두에게 새로운 희망을 선사해 주었습니다.', `MaleText_loc4`='安薇娜的牺牲为我们带来了新的希望。', `MaleText_loc5`='安薇娜的犧牲為我們大家的未來帶來全新的希望。', `MaleText_loc7`='El sacrificio de Anveena nos ha dado nuevas esperanzas para el futuro.' WHERE `ID`=25862;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그대에게서 어떤 불안정함이 느껴지는구나. 그들과 한편이건 아니건 나는 그대를 믿을 수 없다. 칼루아크에 대한 내 점괘를 알고 싶다면 먼저 그대 자신을 내게 증명하라.', `FemaleText_loc4`='你是卡鲁亚克氏族的朋友？我对此持保留意见。如果你想让我为他们占卜的话，就先证明自己的忠诚吧。', `FemaleText_loc5`='我在你身上嗅到了不確定性，不管你是不是他們一夥的，我都不會相信你。如果你想要我替卡魯耶克預言，你得先證明你自己才行。', `FemaleText_loc7`='Siento incertidumbre en ti y no me da confianza, estés con ellos o no. Si deseas mi augurio para los Kalu''ak, tendrás que demostrarme lo que vales.' WHERE `ID`=25863;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그대에게 작은 명령을 내리겠다. 내 앞의 심해에 몸을 던져, 나의 영역에 발을 들이고 내 뜻에 따를 것임을 증명하라.', `FemaleText_loc4`='我要你做的事也不算太过分。当着我的面跳入深海吧，这样你才能与我的精神融合，以此表达你的诚意。', `FemaleText_loc5`='我必須逼你做一件小小的事情。從我前面這個地方跳下去，和我的元素在一起，才能顯示出你的屈從。', `FemaleText_loc7`='Te impondré una leve obligación. Salta al vacío ante mí para ponerte en mi situación y mostrarme así tu sumisión.' WHERE `ID`=25864;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='비록 내가 명령했으나, 선택은... 마지막 발걸음을 내딛는 것은 그대의 뜻이다. 20초 안에 결정하거라.', `FemaleText_loc4`='虽说我提出了要求，不过你可以选择跳或是不跳。我给你20秒做决定。', `FemaleText_loc5`='雖然你被逼著這麼做，但是選擇權，與你跳下去之前的最後一步，則操之於你。你還有二十秒鐘的時間可以決定。', `FemaleText_loc7`='Aunque tienes la obligación, la elección y el último paso antes del salto están en tus manos. Tienes 20 segundos más para decidirte.' WHERE `ID`=25865;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그렇군... 그대는 실패했다, $n. 예언은 듣지 못할 것이다. 확고한 결의가 생기기 전에는 나를 불러내지 마라!', `FemaleText_loc4`='$n，你拒绝了我的要求。那么我也拒绝占卜卡鲁亚克氏族的命运。在你鼓起勇气接受挑战之前，别再召唤我！', `FemaleText_loc5`='很好，$n，你失敗了。這份預言不是你該知道的東西。在你鼓起勇氣之前不要再召喚我!', `FemaleText_loc7`='Muy bien, $n, has fracasado. No te mereces conocer la profecía. ¡No vuelvas a llamarme hasta que encuentres tus agallas!' WHERE `ID`=25866;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘했다, $n. 그대는 충분히 경의를 표했다. 이제 칼루아크에게 반드시 전해야 할 사실을 알려 주겠다.', `FemaleText_loc4`='很好，$n。你充分表达了自己的诚意。我会如约告诉你关于卡鲁亚克氏族的命运，请转告他们吧。', `FemaleText_loc5`='幹得好，$n。你敬畏的態度我記住了。我有一些消息要你轉達給卡魯耶克知道。', `FemaleText_loc7`='Bien hecho, $n. Tu muestra de respeto ha sido debidamente anotada. Ahora, tengo información que has de transmitir a los Kalu''ak.' WHERE `ID`=25867;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='간단하다. 투스카르에게 도망쳐서는 아니 된다고 알려라. 만약 도망친다면 그들의 영혼은 노스렌드의 악마에게 갈기갈기 찢길 것이다.', `FemaleText_loc4`='请你转告卡鲁亚克海象人，逃亡是没有出路的。一旦选择逃亡，他们的灵魂将被诺森德滋生的邪灵毁灭。', `FemaleText_loc5`='快走，然後告訴巨牙海民們他們不能逃跑。如果他們逃了，他們的靈魂將會被北裂境中的邪惡力量給毀滅的。', `FemaleText_loc7`='Básicamente, tienes que decir a los colmillarr que no pueden huir. Si lo hacen, sus espíritus serán destruidos por la creciente maldad de Rasganorte.' WHERE `ID`=25868;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='비술사에게 일러라. 그의 동족은 호드와 얼라이언스의 곁에서 함께 싸우며 말리고스와 리치 왕의 군대에 맞서야 한다고 일러라.', `FemaleText_loc4`='告诉秘法师，卡鲁亚克氏族必须与部落和联盟并肩战斗，共同抵抗玛里苟斯和巫妖王的军队。', `FemaleText_loc5`='告訴秘法師，他的人民應該站在部落和聯盟這邊來對抗瑪里苟斯和巫妖王。', `FemaleText_loc7`='Dile al místico que su gente ha de unirse a la Horda o la Alianza en la lucha contra los ejércitos de Malygos y el Rey Exánime.' WHERE `ID`=25869;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 내가 그대에게 전한 말을 품고 돌아가라. 그대가 할 수 있는 일을 하라, $r|1이여;여;.', `FemaleText_loc4`='你的使命已经达成，游回去吧。尽你所能地帮助他们，$r。', `FemaleText_loc5`='帶著我傳授給你的知識游回去吧。盡你所能的幫助他們，$r。', `FemaleText_loc7`='Nada de vuelta con el conocimiento que te he proporcionado. Haz lo que puedas por ellos, $r.' WHERE `ID`=25870;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어? 뭐야?! 저리 가라고!', `MaleText_loc4`='嗯？干什么？！走开。', `MaleText_loc5`='嗯?什麼?!閃一邊去。', `MaleText_loc7`='¿Eh? ¿Qué? Lárgate.' WHERE `ID`=25871;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전쟁 기계를 새로 만들 수만 있다면 분노의 관문으로 가져가서 꽤 큰돈을 벌 수 있을 텐데 말이에요.$B$B예전에 몇 번 만들어 봤던 건 뭐랄까... 안정성 면에서 부족했지요. 하지만 여기에 있는 제 비행기는 효과적인 폭탄을 달아주기만 하면 꽤 쓸모가 있을 거라고요.', `FemaleText_loc4`='如果能制造出新型的空中作战机器，我肯定能在天谴之门大赚一笔。$B$B我们进行过多次尝试，但是效果并不……理想。可别小瞧我的飞行器，一旦我鼓捣出完善的轰炸系统，它就能成为彪悍的战斗机。', `FemaleText_loc5`='如果我可以造一台新的戰爭機器，我就可以在憤怒之門賺到一大筆錢!$B$B我們之前的玩意並不是很...穩定，但如果我能設計出一種高效能轟炸系統的話，我的飛行器應該就可以用了。', `FemaleText_loc7`='Si consigo crear una nueva máquina de guerra, sé que conseguiré un buen dinerito por ella en la Puerta de Cólera.$B$BAlgunas de nuestras anteriores acciones no han sido del todo... estables, pero mi máquina voladora debería ser suficiente si consigo desarrollar un sistema de bombardeo efectivo para ella.' WHERE `ID`=25872;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돈 냄새가 나는군! 아버지가 항상 말씀하신 대로야. 돈을 벌기 가장 좋은 때는 전쟁이 났을 때지.', `MaleText_loc4`='趁这时候赶紧捞钱啊！我老爸经常说：战争是发横财的绝好机会。', `MaleText_loc5`='有一大筆錢等著我們去賺!就像俗語說的 - 沒有比戰爭更適合發財的時機了。', `MaleText_loc7`='¡Tenemos dinero que conseguir! Ya lo decía papi: los mejores tiempos para hacer fortuna son los tiempos de guerra.' WHERE `ID`=25873;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고대의 석상 앞에 서자 알 수 없는 존재감이 느껴집니다.', `MaleText_loc4`='站在这尊远古神像前，你产生了某种异样的感觉。', `MaleText_loc5`='當你站在這尊古老的人偶面前，你感覺到好像有什麼東西現身了。', `MaleText_loc7`='Sientes una extraña presencia mientras permaneces frente al ídolo.' WHERE `ID`=25874;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수천 년 동안 예언가의 눈이 박혀 있던 곳에는 이제 움푹 팬 자국만이 남았습니다.', `MaleText_loc4`='数千年来存放预言者之眼的位置如今已是空空如也。', `MaleText_loc5`='原本預言者之眼安置了千年的位置，只剩下一座空蕩蕩的壁龕。', `MaleText_loc7`='En el lugar donde el ojo de los profetas descansó durante milenios solo queda una hornacina vacía.' WHERE `ID`=25875;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='석상의 머리 부분에서 예언가의 눈을 제거합니다.', `MaleText_loc4`='从神像脸上取下预言者之眼。', `MaleText_loc5`='把預言者之眼從雕像的臉上拿出來。', `MaleText_loc7`='Saca el ojo de los profetas de la cara del ídolo.', `FemaleText_loc1`='석상의 머리 부분에서 예언가의 눈을 제거합니다.', `FemaleText_loc4`='从神像脸上取下预言者之眼。', `FemaleText_loc5`='把預言者之眼從雕像的臉上拿出來。', `FemaleText_loc7`='Saca el ojo de los profetas de la cara del ídolo.' WHERE `ID`=25876;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 기다리겠다.', `MaleText_loc4`='朋友，等你的好消息。', `MaleText_loc5`='我會等著你，老兄。', `MaleText_loc7`='Te estaré esperando, colega.' WHERE `ID`=25877;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서둘러라, $n. 기다릴 테니까, 친구.', `MaleText_loc4`='别浪费时间了，$n。等你的好消息。', `MaleText_loc5`='快一點，$n。我會等著你，老兄。', `MaleText_loc7`='Date prisa, $n. Te estaré esperando, colega.' WHERE `ID`=25878;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='흥미로운 발견이군요, $n. 그런데 이걸로 뭘 해야 할지를 모르겠네요.', `FemaleText_loc4`='$n，这真是有趣的发现，不过我对此一头雾水啊。', `FemaleText_loc5`='$n，這是個有趣的發現，可惜我不知道該怎麼加以利用。', `FemaleText_loc7`='Es un descubrimiento intrigante, $n, pero no sé qué hacer con él.' WHERE `ID`=25879;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='처음 보는 언어로 적혀 있는 데다, 우리가 아는 한 이건 그냥 병사의 일지에요.', `FemaleText_loc4`='我们都看不懂上面的文字，大概只是某个士兵的日志吧。', `FemaleText_loc5`='雖然看不懂這種語言，但就我們所知，這是某個士兵的日記。', `FemaleText_loc7`='El idioma no nos resulta familiar y, por lo que sabemos, podría no ser más que el diario de un soldado.' WHERE `ID`=25880;
