UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드워프어로 기록된 일지로군. 갈겨 쓴 부분은 못 읽겠지만, 한 가지는 확실하오.', `MaleText_loc4`='这是矮人语啊……字迹真是潦草啊，不过我还是看出点眉目来了。', `MaleText_loc5`='這本日記是用矮人語寫成的，雖然我無法分辨潦草的字跡，但這是我唯一能確定的。', `MaleText_loc7`='Este diario está escrito en enánico. No puedo leer estos garabatos, pero hay una cosa que sí entiendo.' WHERE `ID`=25883;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='''브란 브론즈비어드''. 이자는 아이언포지 국왕의 동생이잖소? 너무 성급하게 판단한 건지도 모르겠소, 팔루나.', `MaleText_loc4`='布莱恩·铜须？他不是铁炉堡国王的兄弟吗？帕鲁纳，搞错了吧。', `MaleText_loc5`='「布萊恩·銅鬚」，鐵爐堡國王的兄弟?你大概話講太快了吧，帕努納。', `MaleText_loc7`='''Brann Barbabronce. '' ¿El hermano del rey de Forjaz? Puede que hayas hablado demasiado pronto, Paluna.' WHERE `ID`=25884;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무슨 뜻인가요?', `FemaleText_loc4`='什么意思？', `FemaleText_loc5`='這是什麼意思?', `FemaleText_loc7`='¿Qué quieres decir?' WHERE `ID`=25885;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 드워프 왕족을 인질로 잡고 있을 때 돌아올 이득을 한번 생각해 보시오.', `MaleText_loc4`='你想啊，劫持矮人皇室的重要成员做人质，那赎金得多高啊。', `MaleText_loc5`='想想，如果一個矮人皇室成員是我們的階下囚，這是多麼有價值的人物。', `MaleText_loc7`='Piensa en lo valioso que sería un miembro de la familia real enana como rehén.' WHERE `ID`=25886;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그자가 이 지역에 있다면 반드시 우리가 찾아내야 하오. 하지만 먼저 이 일지를 해독할 방법부터 찾아야겠소.', `MaleText_loc4`='如果他在这附近的话，我们必须找到他。但是首先，我们需要破译这本日志。', `MaleText_loc5`='要是他在這附近，我們一定要把他找出來。不過，我們要做的第一件事情，是解讀這本日記。', `MaleText_loc7`='Si está en esta zona, debemos encontrarlo. Pero primero tendremos que encontrar el modo de descifrar este diario.' WHERE `ID`=25887;
