UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오세요! 쉴 곳이 필요하시다면 제가 해결해 드리죠!', `MaleText_loc4`='欢迎！想找地方休息的话，我能为你提供食宿服务哦。', `MaleText_loc5`='歡迎光臨!如果你找不到地方休息，我可以替你解決這個問題。', `MaleText_loc7`='¡Te doy la bienvenida! Si necesitas un lugar para descansar, puedo solucionarlo.', `FemaleText_loc1`='어서 오세요! 쉴 곳이 필요하시다면 제가 해결해 드리죠!', `FemaleText_loc4`='欢迎！想找地方休息的话，我能为你提供食宿服务哦。', `FemaleText_loc5`='歡迎光臨!如果你找不到地方休息，我可以替你解決這個問題。', `FemaleText_loc7`='¡Te doy la bienvenida! Si necesitas un lugar para descansar, puedo solucionarlo.' WHERE `ID`=25900;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='척후병 보르타크의 예상이 맞았군요. 브란 브론즈비어드는 근래에 토르 모단에 갔었어요. 이 일지에는 그가 거기서 발견한 내용이 적혀 있군요.', `FemaleText_loc4`='斥候沃塔肯的直觉是正确的。布莱恩·铜须最近确实造访过索尔莫丹，并在这本日志上记录了他的发现。', `FemaleText_loc5`='斥候沃塔克的預感沒有錯，布萊恩·銅鬚最近造訪鐸爾莫丹，這本日記記載了他的發現。', `FemaleText_loc7`='La corazonada del explorador Vor''takh era correcta. Brann Barbabronce visitó Thor Modan hace poco y este diario recoge sus descubrimientos.' WHERE `ID`=25901;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그는 전투가 시작되기 전에 유적을 탐험했고, 예언이 새겨진 룬문자 판 3개를 발견한 모양이에요.', `FemaleText_loc4`='他趁战争打响前探察了这片废墟，发现了三块刻有预言的符文板。', `FemaleText_loc5`='他設法在戰鬥開始之前探索了遺跡，發現了三塊刻有預言的符文板。', `FemaleText_loc7`='Consiguió explorar las ruinas antes de que comenzara la batalla, descubriendo tres placas rúnicas con profecías grabadas.' WHERE `ID`=25902;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='브란이 해독한 내용이 기록되어 있지는 않지만, 일지를 보면 전투가 시작되기 전에 그것들을 다 암기했다고 기록돼 있어요.', `FemaleText_loc4`='布莱恩并没有记录译文，日志中只提到他在躲避战乱前背下了所有的符文。', `FemaleText_loc5`='布萊恩並沒有寫下翻譯，上面寫說但是他在逃離那場戰鬥之前已經把它們牢牢記住了。', `FemaleText_loc7`='Brann no ha anotado las traducciones, pero dice que se las aprendió de memoria antes de escapar de la batalla.' WHERE `ID`=25903;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그 룬문자 판들을 해석할 수 있다면 브란을 찾아내 잡을 수 있을 거예요.', `FemaleText_loc4`='如果你能破译这些符文板，我们就能找到布莱恩。', `FemaleText_loc5`='如果你能夠翻譯這些石板，我們就能抓到布萊恩。', `FemaleText_loc7`='Si consigues traducir esas placas, podremos encontrar y capturar a Brann.' WHERE `ID`=25904;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마그모스 분쇄자가 전진합니다!', `MaleText_loc4`='犸格莫斯碾压者正在行动！', `MaleText_loc5`='瑪格默斯粉碎者開始活動!', `MaleText_loc7`='¡Triturador de Magmoth en marcha!' WHERE `ID`=25905;
