UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죄송합니다, 대사님. 전 명령을 거스를 수 없습니다.', `MaleText_loc4`='很抱歉。上命难违，请你理解。', `MaleText_loc5`='很抱歉，大使。我的命令很清楚。', `MaleText_loc7`='Mis disculpas, embajador. Tengo órdenes precisas.', `FemaleText_loc1`='죄송합니다, 대사님. 전 명령을 거스를 수 없습니다.', `FemaleText_loc4`='很抱歉。上命难违，请你理解。', `FemaleText_loc5`='很抱歉，大使。我的命令很清楚。', `FemaleText_loc7`='Mis disculpas, embajador. Tengo órdenes precisas.' WHERE `ID`=25919;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 아서스를 물리칠 걸세! 스컬지는 위대한 호드의 힘 앞에 무릎 꿇을 걸세!', `MaleText_loc4`='我们要杀死阿尔萨斯！即便是天灾军团，也不能与部落抗衡！', `MaleText_loc5`='我們會粉碎阿薩斯!天譴軍團無法抵擋部落的力量!', `MaleText_loc7`='¡Aplastaremos a Arthas! ¡La Plaga no podrá resistir contra la fuerza de la Horda!' WHERE `ID`=25920;
