UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여긴 너희가 올 곳이 아니다. 도둑질을 하려거든 다른 데로 가 봐라!', `FemaleText_loc4`='这里不欢迎你。滚远点，到别处打劫去吧！', `FemaleText_loc5`='我們的家鄉不歡迎你。滾開去別的地方掠奪!', `FemaleText_loc7`='No sois bienvenidos en nuestro hogar. ¡Marchaos a buscar otra tierra que saquear!' WHERE `ID`=25922;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 얼마나 잘하는지 보여 드리겠습니다! 연습용 낙하산을 이리 주십시오!', `MaleText_loc4`='我来做示范！把练习用的降落伞包递给我！', `MaleText_loc5`='讓我來示範給你看!把練習降落傘拿給我!', `MaleText_loc7`='¡Yo te enseñaré! ¡Dame ese paracaídas de prácticas!', `FemaleText_loc1`='제가 얼마나 잘하는지 보여 드리죠! 연습용 낙하산을 이리 주세요!', `FemaleText_loc4`='我来做示范！把练习用的降落伞包递给我！', `FemaleText_loc5`='讓我來示範給你看!把練習降落傘拿給我!', `FemaleText_loc7`='¡Yo te enseñaré! ¡Dame ese paracaídas de prácticas!' WHERE `ID`=25923;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이번에는 제어장치가 완벽하게 작동하고 있어요!', `FemaleText_loc4`='目前控制组件运转正常！', `FemaleText_loc5`='這下子控制零件完美的運作了!', `FemaleText_loc7`='¡Los componentes de control están funcionando a la perfección esta vez!' WHERE `ID`=25924;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='누구한테 폭탄을 시험하지? 하피? 하하하... 잠깐... 저게 뭐야?', `FemaleText_loc4`='找谁来测试炸弹呢？鹰身人吗？哈哈……等等……那是什么？', `FemaleText_loc5`='炸彈找誰測試?鷹身人?哈哈...等等...那是什麼?', `FemaleText_loc7`='¿Contra quién probar la bomba? ¿Las arpías? Je, je... espera... ¿qué es eso?' WHERE `ID`=25925;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안 돼! 내 기계... 내 폭탄! 안 돼! 이 하피 놈들을 가만두나 봐라!', `FemaleText_loc4`='不！我的机器……我的炸弹！好吧！那些鹰身人死定了！', `FemaleText_loc5`='不!我的機器...我的炸彈!夠了!鷹身人死定了!', `FemaleText_loc7`='¡NO! ¡Mi máquina... mis bombas! ¡YA BASTA! ¡Esas arpías me las van a PAGAR!' WHERE `ID`=25926;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정령이여, 나의 뜻에 복종하라.', `MaleText_loc4`='灵魂，屈服于我的意志吧。', `MaleText_loc5`='靈魂，你將臣服於我的意志之下。', `MaleText_loc7`='Espíritu, te someterás a mi voluntad.' WHERE `ID`=25927;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너는 나에게 구속되었다, 정령이여! 너는 풍차를 계속해서 돌려야만 한다. 머뭇거리지 마라!', `MaleText_loc4`='接受被束缚的命运吧，灵魂！你的任务是保持磨坊运转——保持风力均衡！', `MaleText_loc5`='你被我束縛住了，靈魂!你的任務就是讓磨坊轉動 - 不要跌倒!', `MaleText_loc7`='¡Estás vinculado a mí, espíritu! Tu labor es mantener el molino en movimiento, ¡no vaciles!' WHERE `ID`=25928;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바람을 일으켜 풍차를 계속 움직여라, 정령이여!', `MaleText_loc4`='操纵风力让磨坊保持运转，灵魂！', `MaleText_loc5`='讓風服從吹動風車的工作吧，精靈!', `MaleText_loc7`='¡Controla el viento para que el molino siga girando, espíritu!' WHERE `ID`=25929;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='북풍이여! 나의 명을 받들라!', `MaleText_loc4`='北风！照我说的去做！', `MaleText_loc5`='北風啊!聽從我的命令!', `MaleText_loc7`='¡Viento del norte! ¡Harás lo que yo ordene!' WHERE `ID`=25930;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거센 바람이 풍차를 감싸고, 나무가 삐걱대는 소리를 내며 풍차가 빠르게 돕니다.', `MaleText_loc4`='狂风紧紧地贴着磨坊高速旋转，使周围的树木发出了呻吟声。', `MaleText_loc5`='風立刻包圍了風車，讓它轉動起來，木材吱嘎作響。', `MaleText_loc7`='El viento que rodea el molino comienza a moverse rápidamente, haciendo que las vigas crujan.' WHERE `ID`=25931;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맹렬한 바람이 타운카 풍차를 에워싸는 가운데, 정령이 골이 난 듯 칼리마그어로 나직하게 투덜거리는 소리가 들립니다.', `MaleText_loc4`='寒冷的狂风环绕着牦牛人的磨坊，用古卡利姆多语低声诉说着它的怨恨。', `MaleText_loc5`='一陣冷風環繞著坦卡磨坊，還送來一陣元素語的抱怨。', `MaleText_loc7`='Una ráfaga helada rodea el molino Taunka, en la ráfaga se pueden distinguir suaves y resentidos susurros en Kalimag.' WHERE `ID`=25932;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갑작스러운 바람을 타고 풍차가 점점 빨리 돌기 시작합니다.', `MaleText_loc4`='突然卷起的狂风将风力磨坊的风帆扯得紧紧的。', `MaleText_loc5`='風車的帆因為這陣突如其來的風而繃緊了。', `MaleText_loc7`='Las velas de molino se tensan por el repentino viento.' WHERE `ID`=25933;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='적이 집중점에 가까이 가지 못하게 해라!', `FemaleText_loc4`='别让他们靠近！', `FemaleText_loc5`='不要讓他們靠近節點!', `FemaleText_loc7`='¡Mantenedlos alejados del foco!' WHERE `ID`=25934;
