UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님을 위해서라면 기꺼이 죽으리...', `MaleText_loc4`='能为主人而死，我很荣幸……', `MaleText_loc5`='我很樂意為主人而死...', `MaleText_loc7`='Moriré gustosamente por el maestro...' WHERE `ID`=25937;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 승리에는 아무 의미도 없다.', `MaleText_loc4`='你的胜利毫无意义。', `MaleText_loc5`='你的勝利毫無意義。', `MaleText_loc7`='Tu victoria no significa nada.' WHERE `ID`=25938;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 다시 일어날 것이다. 훨씬... 더... 강하게...', `MaleText_loc4`='我会再站起来的，变得……更加……强大……', `MaleText_loc5`='我會再度復活，變的更強...更...強...', `MaleText_loc7`='Volveré a alzarme, más poderoso... mucho... más...' WHERE `ID`=25939;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='투기장 사무관을 찾고 있나? 그들은 대도시나 마을과 마을 사이에서 만날 수 있지.$B$B날 통해서 이곳에 머물 수 있으니 그렇게 하라고. 그리고 가고자 하는 대도시로 순간이동시켜 줄 수 있단 말이지.', `MaleText_loc4`='你在寻找竞技场管理员吗？他们在城镇之间来回行走，或是呆在主城。$B$B你可以将炉石绑在这儿。我还能将你传送到任意主城去。', `MaleText_loc5`='在找競技場戰場軍官嗎?你可以在城鎮間的道路上找到他們，或是主城裡。$B$B你可以綁定在這裡，我也能把你傳送至其中一個主城。', `MaleText_loc7`='¿Buscas un maestro de batalla de arena? Puedes encontrarlos en las carreteras entre las ciudades o en las capitales.$B$BPuedes vincularte aquí, conmigo. También puedo teletransportarte a una de esas capitales.', `FemaleText_loc1`='투기장 사무관을 찾고 계신가요? 그들은 대도시나 마을과 마을 사이에서 만날 수 있답니다.$B$B저를 통해서 이곳에 머무실 수 있답니다. 그리고 제가 가고자 하는 대도시로 순간이동시켜 드리겠습니다.', `FemaleText_loc4`='你在寻找竞技场管理员吗？他们在城镇之间来回行走，或是呆在主城。$B$B你可以将炉石绑在这儿。我还能将你传送到任意主城去。', `FemaleText_loc5`='在找競技場戰場軍官嗎?你可以在城鎮間的道路上找到他們，或是主城裡。$B$B你可以綁定在這裡，我也能把你傳送至其中一個主城。', `FemaleText_loc7`='¿Buscas un maestro de batalla de arena? Puedes encontrarlos en las carreteras entre las ciudades o en las capitales.$B$BPuedes vincularte aquí, conmigo. También puedo teletransportarte a una de esas capitales.' WHERE `ID`=25940;
