UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새로운 세상이 열린다, 내 자식들아! 곧 아졸네룹의 언데드 군단이 깨어나 이 세상을 뒤덮으리라!', `MaleText_loc4`='孩子们，又是新的一天！艾卓-尼鲁布的天灾军团很快就要征服这个世界了！', `MaleText_loc5`='新的一天，孩子們!很快的，阿茲歐-奈幽的不死軍團就會接掌這個世界!', `MaleText_loc7`='¡Amanece un nuevo día, hijos míos! ¡Pronto las legiones de no-muertos de Azjol-Nerub se alzarán y dominarán este mundo!' WHERE `ID`=25953;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난... 자유다!', `MaleText_loc4`='我……自由了！', `MaleText_loc5`='我...自由...了!', `MaleText_loc7`='¡Soy... LIBRE!' WHERE `ID`=25954;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 녀석들이 내 동족들에게 무슨 짓을 한 거란 말인가...', `MaleText_loc4`='他们对我的族人做了什么……', `MaleText_loc5`='他們對我的子民做了什麼...', `MaleText_loc7`='Qué han hecho a mi gente...' WHERE `ID`=25955;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선조의 분노가 너를 처단할 것이다, 괴물아!', `MaleText_loc4`='你将为自己的所作所为付出代价，接受先祖的惩罚吧！', `MaleText_loc5`='你要為了你的所作所為面對先祖的狂怒，妖怪!', `MaleText_loc7`='¡La furia de los ancestros caerá sobre ti por lo que has hecho, monstruo!' WHERE `ID`=25956;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일어나라, 형제여... 일어나라... 일어나서 다시 한 번 싸워라.', `MaleText_loc4`='重生吧，我的兄弟……站起来……再次投入战斗。', `MaleText_loc5`='重生降臨了，我的弟兄們...復活吧...復活，然後再一次參戰。', `MaleText_loc7`='Ahí llega el renacimiento, hermanos míos... Alzaos... Alzaos y luchad una vez más.' WHERE `ID`=25957;
