UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너의 자유는 오래가지 않을 것이다, 아이스미스트!', `MaleText_loc4`='别以为你们从此就高枕无忧了！', `MaleText_loc5`='你的自由會帶來短命，冰霧!', `MaleText_loc7`='¡Tu libertad no durará mucho, Bruma de Hielo!' WHERE `ID`=25959;
