UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 왜 이렇게 잘난 거지?', `MaleText_loc4`='我怎么这么厉害啊？', `MaleText_loc5`='為什麼我這麼棒呢?', `MaleText_loc7`='¿Por qué soy tan buena persona?', `FemaleText_loc1`='난 왜 이렇게 잘난 거지?', `FemaleText_loc4`='我怎么这么厉害啊？', `FemaleText_loc5`='為什麼我這麼棒呢?', `FemaleText_loc7`='¿Por qué soy tan buena persona?' WHERE `ID`=25969;
