UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='최대한 빨리 보고서를 가지고 돌아오겠습니다.', `FemaleText_loc4`='我们很快就会返回牦牛村汇报情况的。', `FemaleText_loc5`='我們會很快帶著報告回來。', `FemaleText_loc7`='Regresaremos pronto con nuestro informe.' WHERE `ID`=25973;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 저기 있소. 타이마, 여기 정도면 전부 관찰하고 보고서를 쓸 수 있겠소?', `MaleText_loc4`='瞧，虫孔。台玛，别再往前走啦。我们已经了解到足够多的信息，回去好吗？', `MaleText_loc5`='它們就在那裡。泰瑪，我們這樣子夠近嗎?', `MaleText_loc7`='Allí están. Taima, ¿estamos lo suficientemente cerca como para ver todo y elaborar el informe?' WHERE `ID`=25974;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아니요. 이 정도는 이미 전에 다 알고 있었습니다. 더 가까이 가서 저들이 얼마나 깊이까지 들어가는지 봐야 합니다.', `FemaleText_loc4`='不行。这样是不够的。我们最好再靠近些，瞧瞧这些虫孔到底有多深。', `FemaleText_loc5`='不夠。這些我們已經知道一段時間了。我們得再靠近一點，觀察他們究竟進展如何。', `FemaleText_loc7`='No. Esto lo sabíamos desde hace algún tiempo. Tenemos que acercarnos más y ver hasta dónde llegan.' WHERE `ID`=25975;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇다면, 네루비안 사이를 뚫고 가야겠군.', `MaleText_loc4`='那样的话，我们就必须和蛛魔交手了。', `MaleText_loc5`='那麼我們就從這些奈幽蟲族中殺開一條血路吧。', `MaleText_loc7`='Entonces nos abrimos paso entre los nerubianos.' WHERE `ID`=25976;
