UPDATE `locales_broadcast_text` SET `MaleText_loc1`='박살 내 주마, 보잘것없는 생물!', `MaleText_loc4`='可怜虫，我们要杀死你！', `MaleText_loc5`='我們會毀掉你這個渺小的生物的!', `MaleText_loc7`='¡Te destruiremos, lamentable criatura!' WHERE `ID`=25980;
