UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적들이 더욱 강해진다! 날 도와라!', `MaleText_loc4`='敌人越战越勇！快帮帮我！', `MaleText_loc5`='敵人越來越強了!幫幫我!', `MaleText_loc7`='¡El enemigo es cada vez más fuerte! ¡Ayudadme!' WHERE `ID`=25982;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누구도 우리의 운명을 바꿀 순 없다!', `MaleText_loc4`='没有谁能阻止我们完成使命！', `MaleText_loc5`='沒有人可以阻擋我們的天命!', `MaleText_loc7`='¡Nadie nos apartará de nuestro destino!' WHERE `ID`=25983;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로켄 님의 영광을 위하여!', `MaleText_loc4`='为洛肯的荣耀而战！', `MaleText_loc5`='為了洛肯的榮光!', `MaleText_loc7`='¡Por la gloria de Loken!' WHERE `ID`=25984;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입한 대가를 치르게 해 주마!', `MaleText_loc4`='你会为此付出代价的！', `MaleText_loc5`='你會為你的雞婆付出代價!', `MaleText_loc7`='¡Pagarás por tu intromisión!' WHERE `ID`=25985;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크룬의 헛된 싸움에 끼어들다니, 어리석은 녀석!', `MaleText_loc4`='蠢货，你替库伦卖命是毫无意义的！', `MaleText_loc5`='替庫倫打這場沒用的戰鬥，你真是個蠢蛋!', `MaleText_loc7`='¡Estás loco por luchar en la desesperada batalla de Kurun!' WHERE `ID`=25986;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 목숨은 여기서 끝이다, 바위의 동맹 녀석!', `MaleText_loc4`='去死吧，石头的盟友！', `MaleText_loc5`='你的命是我的，石頭的盟友!', `MaleText_loc7`='¡Has perdido el derecho a la vida, aliado de la piedra!' WHERE `ID`=25987;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, 파후.', `MaleText_loc4`='帕乌，你好。', `MaleText_loc5`='你好，帕胡。', `MaleText_loc7`='Hola, Pahu.', `FemaleText_loc1`='안녕하세요, 파후.', `FemaleText_loc4`='帕乌，你好。', `FemaleText_loc5`='你好，帕胡。', `FemaleText_loc7`='Hola, Pahu.' WHERE `ID`=25988;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파후가 수색꾼에게 안전한 곳에 저장할 비상식량을 건넵니다.', `MaleText_loc4`='远行者从帕乌手中接过包裹，迅速将它藏了起来。', `MaleText_loc5`='帕胡將一個包裹交給遠偵斥候，然後他小心的將包裹收起來。', `MaleText_loc7`='Un paquete pasa de las manos de Pahu a las de Largo Camino, quien lo guarda a salvo.', `FemaleText_loc1`='파후가 수색꾼에게 안전한 곳에 저장할 비상식량을 건넵니다.', `FemaleText_loc4`='远行者从帕乌手中接过包裹，迅速将它藏了起来。', `FemaleText_loc5`='帕胡將一個包裹交給遠偵斥候，然後他小心的將包裹收起來。', `FemaleText_loc7`='Un paquete pasa de las manos de Pahu a las de Largo Camino, quien lo guarda a salvo.' WHERE `ID`=25989;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요! 당신께 전달할 비상식량이 있답니다.', `FemaleText_loc4`='嗨！我给你带干粮来啦。', `FemaleText_loc5`='你好!你的乾糧就在我這兒。', `FemaleText_loc7`='¡Hola! Aquí tengo tus raciones.' WHERE `ID`=25990;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하게, 그리고 빨리 돌아오게. 상황을 어서 파악해야 하니 말일세.', `MaleText_loc4`='小心，快去快回吧。我们不能再盲目行事了。', `MaleText_loc5`='小心，快去快回，我們無法承受沒有消息進來的後果。', `MaleText_loc7`='Ten cautela, pero regresa rápido. No podemos permitirnos quedar ciegos.' WHERE `ID`=25991;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 하늘 저 멀리 날아갑니다.', `MaleText_loc4`='%s飞走了。', `MaleText_loc5`='%s飛走了。', `MaleText_loc7`='¡%s se aleja volando!' WHERE `ID`=25992;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 녀석은 북쪽으로 오는 배를 타지 않았어야 했어!', `MaleText_loc4`='朋友，你不应该朝北航行的！', `MaleText_loc5`='老兄，你不該搭船來北邊的!', `MaleText_loc7`='¡No deberías haber cogido el barco al norte, colega!' WHERE `ID`=25993;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 다이노, 내 누나야. 타진니는 이제 죽는다.', `MaleText_loc4`='啊，迪诺，我的妹妹。塔辛尼要死了。', `MaleText_loc5`='噢，迪諾，我的妹妹。塔辛尼要死了。', `MaleText_loc7`='Oh, Deino, mi hermana. Ta''zinni morir ahora.' WHERE `ID`=25994;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경고! 비행기가 작전 지역을 벗어났습니다. 전원이 곧 차단됩니다.', `MaleText_loc4`='警告！载具已经离开操纵区。即将关闭。', `MaleText_loc5`='警告!飛行器已經偏離了操作區域。電源即將關閉。', `MaleText_loc7`='¡Aviso! El vehículo ha abandonado la zona de operaciones. Apagado inminente.' WHERE `ID`=25995;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈은 대가를 치를 거다!', `MaleText_loc4`='你会为此付出代价的！', `MaleText_loc5`='你要為此付出代價!', `MaleText_loc7`='¡Pagarás por eso!' WHERE `ID`=25996;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 녀석이 이길 수 있을 것 같으냐!', `MaleText_loc4`='别想赢我！', `MaleText_loc5`='我不會讓你贏的!', `MaleText_loc7`='¡No te dejaré ganar!' WHERE `ID`=25997;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='할로케는 안 돼!', `FemaleText_loc4`='哈鲁克，不！', `FemaleText_loc5`='不要是哈羅凱!', `FemaleText_loc7`='¡Haloke no!' WHERE `ID`=25998;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아눕에칸를 물리쳤습니다. 껍질 조각을 승리의 증표로 삼으십시오!', `MaleText_loc4`='阿努布耶坎被打败了！随便捡一块虫壳碎片，作为你获胜的证明吧！', `MaleText_loc5`='阿努貝坎被打倒了!拿走他軀體的一塊碎片以證明你的勝利!', `MaleText_loc7`='¡Anub''et''kan ha caído! ¡Coge un fragmento de su caparazón como prueba de tu victoria!' WHERE `ID`=25999;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 딸의 편지를 받을 수 있게 해 줘서 고맙소, $c.$B$B그 아이의 죽음은 헛되지 않았으니 안심하시오. 푸른용군단은 반드시 이 대가를 치르게 될 거요.$B$B내가 직접 그렇게 만들 것이오!', `MaleText_loc4`='$c，谢谢你，自从收到女儿的来信后，我就一直在关注这件事。$B$B她的牺牲总算不是徒劳的，愿她的灵魂安息。蓝龙军团会付出惨痛的代价的。$B$B我等着这一天！', `MaleText_loc5`='感謝你，$c，讓我能收到我女兒的信。$B$B安息吧，他的死將不會白費。藍龍軍團要為此付出代價。$B$B我將會親眼見證!', `MaleText_loc7`='Gracias por hacerme llegar la carta de mi hija, $c.$B$BPuedes tener la certeza de que su muerte no habrá sido en vano. El Vuelo Azul pagará por esto$B$B¡Me encargaré de ello personalmente!' WHERE `ID`=26000;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='출발 준비를 하시오, $n. 호위 부대가 오지 못한다면 당신이 날 호위해줘야 하오.', `MaleText_loc4`='准备上马吧，$n。既然他们不愿意派人护送我，那我就只能指望你了。', `MaleText_loc5`='準備好就上坐騎吧，$n。如果無法請軍隊護送我，我猜就是得你來做了。', `MaleText_loc7`='Prepárate para cabalgar, $n. Si el ejército no se preocupa de mandarme un escolta, supongo que tendrás que hacerlo tú.', `FemaleText_loc1`='출발 준비를 하세요, $n. 호위 부대가 오지 못한다면 당신이 날 호위해줘야 합니다.', `FemaleText_loc4`='准备上马吧，$n。既然他们不愿意派人护送我，那我就只能指望你了。', `FemaleText_loc5`='準備好就上坐騎吧，$n。如?無法請軍隊護送我，我猜就是得你來做了。', `FemaleText_loc7`='Prepárate para cabalgar, $n. Si el ejército no se preocupa de mandarme un escolta, supongo que tendrás que hacerlo tú.' WHERE `ID`=26001;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은빛시내 마을은 여기서 북서쪽에 있소. 사냥꾼과 덫사냥꾼들로 구성된 조그마한 집단이지. 그들은 여기 지형에 익숙하니, 같은 편이 된다면 우리에게 도움이 될 거요.', `MaleText_loc4`='银溪镇就在西北方。镇上的居民都是猎户。他们熟知这里的地貌，如果能争取到他们的支持，对我们是非常有利的。', `MaleText_loc5`='銀溪鎮就在這裡西北邊。一個由獵人和陷捕者所組成的小聚落。他們對這一帶瞭若指掌 -- 要是能讓他們加入我們陣營一定很有幫助。', `MaleText_loc7`='Arroyoplata está al noroeste de aquí. Una pequeña comunidad de cazadores y tramperos. Conocen la orografía de la zona, sería conveniente que estuvieran de nuestro lado.', `FemaleText_loc1`='은빛시내 마을은 여기서 북서쪽에 있어요. 사냥꾼과 덫사냥꾼들로 구성된 조그마한 집단이지요. 그들은 이 땅의 지형에 익숙하니, 같은 편이 된다면 우리에게 도움이 될 겁니다.', `FemaleText_loc4`='银溪镇就在西北方。镇上的居民都是猎户。他们熟知这里的地貌，如果能争取到他们的支持，对我们是非常有利的。', `FemaleText_loc5`='銀溪鎮就在這裡西北邊。一個由獵人和陷捕者所組成的小聚落。他們對這一帶瞭若指掌 -- 要是能讓他們加入我們陣營一定很有幫助。', `FemaleText_loc7`='Arroyoplata está al noroeste de aquí. Una pequeña comunidad de cazadores y tramperos. Conocen la orografía de la zona, sería conveniente que estuvieran de nuestro lado.' WHERE `ID`=26002;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지름길로 갑시다. 늑대를 조심하시오.', `MaleText_loc4`='抄近路吧。小心附近的座狼。', `MaleText_loc5`='我們正在抄捷徑。當心座狼。', `MaleText_loc7`='Vamos a tomar un atajo. Tengan cuidado con los huargos.', `FemaleText_loc1`='지름길로 갑시다. 늑대를 조심하세요.', `FemaleText_loc4`='抄近路吧。小心附近的座狼。', `FemaleText_loc5`='我們正在抄捷徑。當心座狼。', `FemaleText_loc7`='Vamos a tomar un atajo. Tengan cuidado con los huargos.' WHERE `ID`=26003;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 앞이로군.', `MaleText_loc4`='镇子就在前面。', `MaleText_loc5`='前面就是了。', `MaleText_loc7`='Esta allí adelante.', `FemaleText_loc1`='저 앞이로군요.', `FemaleText_loc4`='镇子就在前面。', `FemaleText_loc5`='前面就是了。', `FemaleText_loc7`='Esta allí adelante.' WHERE `ID`=26004;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='입구에 시체가 매달려 있다니... 뭔가 크게 잘못된 것 같소.', `MaleText_loc4`='门口悬挂着尸体……这里的情况很不对劲。', `MaleText_loc5`='屍體被吊掛在牆門上...這裡有些不對勁。', `MaleText_loc7`='Los cuerpos colgando de la puerta... algo va mal aquí.', `FemaleText_loc1`='입구에 시체가 매달려 있다니... 뭔가 크게 잘못된 것 같군요.', `FemaleText_loc4`='门口悬挂着尸体……这里的情况很不对劲。', `FemaleText_loc5`='屍體被吊掛在牆門上...這裡有些不對勁。', `FemaleText_loc7`='Los cuerpos colgando de la puerta... algo va mal aquí.' WHERE `ID`=26005;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='들으시오! 나는 바리안 린 폐하의 명으로 은빛시내 마을의 주민에게 동맹을 제안하러 왔소.', `MaleText_loc4`='嗨！尊贵的瓦里安·乌瑞恩国王委任我为特使，派我来银溪镇商谈结盟事宜。', `MaleText_loc5`='向您致敬!奉瓦里安·烏瑞恩國王之命，我已經被授權可對銀溪鎮的人民提議。', `MaleText_loc7`='¡Saludos! Por orden del Rey Varian Wrynn tengo autoridad para hacer una oferta a la gente de Arroyoplata.', `FemaleText_loc1`='들으세요! 나는 바리안 린 폐하의 명으로 은빛시내 마을의 주민에게 동맹을 제안하러 왔습니다.', `FemaleText_loc4`='嗨！尊贵的瓦里安·乌瑞恩国王委任我为特使，派我来银溪镇商谈结盟事宜。', `FemaleText_loc5`='向您致敬!奉瓦里安·烏瑞恩國王之命，我已經被授權可對銀溪鎮的人民提議。', `FemaleText_loc7`='¡Saludos! Por orden del Rey Varian Wrynn tengo autoridad para hacer una oferta a la gente de Arroyoplata.' WHERE `ID`=26006;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스의 전쟁을 돕는다면 그대들에게도 이득이 될 것이오. 우린 병력을 보충할 정찰병과 추적자들, 그리고 보급 물자가 필요하오. 보상은 왕의 보물 창고에 있는 금화로 즉시 지급될 거요.', `MaleText_loc4`='帮助联盟对你们有莫大的好处啊。我们正在招募侦察兵，同时为军队筹备给养。军饷将以金币的形式从国库直接调拨。', `MaleText_loc5`='你會發現協助聯盟戰爭的利益。我們需要斥候與追蹤者，當然也包括部隊糧食的供給者。所有的費用都用金幣支付，並且立即由國王的國庫中支付。', `MaleText_loc7`='Creo que te interesará colaborar con el esfuerzo de la Alianza. Necesitamos exploradores y rastreadores, además de provisiones para nuestras tropas. El pago, en oro de la tesorería del rey, será efectuado inmediatamente.', `FemaleText_loc1`='얼라이언스의 전쟁을 돕는다면 그대들에게도 이득이 될 것입니다. 우린 병력을 보충할 정찰병과 추적자들, 그리고 보급 물자가 필요합니다. 보상은 왕의 보물 창고에 있는 금화로 즉시 지급될 겁니다.', `FemaleText_loc4`='帮助联盟对你们有莫大的好处啊。我们正在招募侦察兵，同时为军队筹备给养。军饷将以金币的形式从国库直接调拨。', `FemaleText_loc5`='你會發現協助聯盟戰爭的利益。我們需要斥候與追蹤者，當然也包括部隊糧食的供給者。所有的費用都用金幣支付，並且立即由國王的國庫中支付。', `FemaleText_loc7`='Creo que te interesará colaborar con el esfuerzo de la Alianza. Necesitamos exploradores y rastreadores, además de provisiones para nuestras tropas. El pago, en oro de la tesorería del rey, será efectuado inmediatamente.' WHERE `ID`=26007;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌아가는 게 좋겠소, $n. 이 얼간이들은 자기들이 어떤 실수를 저질렀는지조차 모르고 있군.', `MaleText_loc4`='我们还是回去吧，$n。这帮傻蛋根本就不会意识到他们犯了天大的错误。', `MaleText_loc5`='我們最好回頭，$n。這些笨蛋不知道他們正在進行得是一個多麼大的錯誤。', `MaleText_loc7`='Será mejor que volvamos, $n. Estos inocentones no tienen ni idea del error que están cometiendo.', `FemaleText_loc1`='돌아가는 게 좋겠어요, $n. 이 얼간이들은 자기들이 어떤 실수를 저질렀는지조차 모르고 있군요.', `FemaleText_loc4`='我们还是回去吧，$n。这帮傻蛋根本就不会意识到他们犯了天大的错误。', `FemaleText_loc5`='我們最好回頭，$n。這些笨蛋不知道他們正在進行得是一個多麼大的錯誤。', `FemaleText_loc7`='Será mejor que volvamos, $n. Estos inocentones no tienen ni idea del error que están cometiendo.' WHERE `ID`=26008;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='철창 신세가 되고 싶지 않다면 당신도 어서 여기를 뜨는 게 좋을 거요...', `MaleText_loc4`='你最好滚远点，除非你也想尝尝被关进牢笼的滋味……', `MaleText_loc5`='你最好滾出這裡，除非你想在這些籠子裡找到你自己...', `MaleText_loc7`='Será mejor que te marches de aquí si no quieres acabar dentro de una de esas jaulas...' WHERE `ID`=26009;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐야?! 이럴 수가! 도망쳐!!!!!', `MaleText_loc4`='啊？！怎么可能！跑吧！', `MaleText_loc5`='什麼?!不可能!跑啊!', `MaleText_loc7`='¿Qué? ¡Es imposible! ¡HUID!', `FemaleText_loc1`='뭐지?! 이럴 수가! 도망쳐!!!!!', `FemaleText_loc4`='啊？！怎么可能！跑吧！', `FemaleText_loc5`='什麼?!不可能!跑啊!', `FemaleText_loc7`='¿Qué? ¡Es imposible! ¡HUID!' WHERE `ID`=26010;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살고 싶으면 도망쳐!', `MaleText_loc4`='快逃命吧！', `MaleText_loc5`='逃啊!', `MaleText_loc7`='¡CORRAN POR SUS VIDAS!', `FemaleText_loc1`='살고 싶으면 도망쳐!', `FemaleText_loc4`='快逃命吧！', `FemaleText_loc5`='逃啊!', `FemaleText_loc7`='¡CORRAN POR SUS VIDAS!' WHERE `ID`=26011;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이쪽으로 온다!', `MaleText_loc4`='冲我们来了！', `MaleText_loc5`='它正對著我們過來!', `MaleText_loc7`='¡Viene directo a por nosotros!', `FemaleText_loc1`='이쪽으로 온다!', `FemaleText_loc4`='冲我们来了！', `FemaleText_loc5`='它正對著我們過來!', `FemaleText_loc7`='¡Viene directo a por nosotros!' WHERE `ID`=26012;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='윽... 또야.', `MaleText_loc4`='天哪，又来了。', `MaleText_loc5`='啊喔喔天啊不要又來了。', `MaleText_loc7`='Jo, tío, otra vez no.', `FemaleText_loc1`='윽... 또야.', `FemaleText_loc4`='天哪，又来了。', `FemaleText_loc5`='啊喔喔天啊不要又來了。', `FemaleText_loc7`='Jo, tío, otra vez no.' WHERE `ID`=26013;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불길한 예감이 드오. 내게 무슨 일이 생기거든 호박빛소나무 오두막으로 돌아가 부관 듀몬트에게 보고해 주시오.', `MaleText_loc4`='我隐约觉得事情不妙。如果我有个什么闪失，请你返回琥珀松木营地向杜蒙特中尉汇报情况。', `MaleText_loc5`='我對這件事情有不好的預感。如果我發生了什麼事，你就回去琥珀松小屋回報都蒙特中尉。', `MaleText_loc7`='Tengo un mal presentimiento. Si me ocurre algo, regresa al Refugio Pino Ámbar y preséntate ante el teniente Dumont.', `FemaleText_loc1`='불길한 예감이 드네요. 제게 무슨 일이 생기거든 호박빛소나무 오두막으로 돌아가 부관 듀몬트에게 보고해 주세요.', `FemaleText_loc4`='我隐约觉得事情不妙。如果我有个什么闪失，请你返回琥珀松木营地向杜蒙特中尉汇报情况。', `FemaleText_loc5`='我對這件事情有不好的預感。如果我發生了什麼事，你就回去琥珀松小屋回報都蒙特中尉。', `FemaleText_loc7`='Tengo un mal presentimiento. Si me ocurre algo, regresa al Refugio Pino Ámbar y preséntate ante el teniente Dumont.' WHERE `ID`=26014;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 와서 도와달라고? 우리에게 도움이 필요했을 때 당신들은 뭘 하고 있었지? 우리가 어떤 일을 겪었는지 알기나 하시오?', `MaleText_loc4`='现在你想要寻求帮助了？我们需要帮助的时候，你在哪儿呢？你知道我们是怎么熬过来的吗？', `MaleText_loc5`='現在你就要我們幫忙了?我們需要你的時候你人在哪?你知道我們遇到什麼樣的事嗎?', `MaleText_loc7`='¿Ahora vienes a pedirnos ayuda? ¿Dónde estabas cuando te necesitábamos? ¿Tienes idea de lo que hemos pasado?', `FemaleText_loc1`='이제 와서 도와달라고? 우리에게 도움이 필요했을 때 당신들은 뭘 하고 있었지요? 우리가 어떤 일을 겪었는지 알기나 해요?', `FemaleText_loc4`='现在你想要寻求帮助了？我们需要帮助的时候，你在哪儿呢？你知道我们是怎么熬过来的吗？', `FemaleText_loc5`='現在你就要我們幫忙了?我們需要你的時候你人在哪?你知道我們遇到什麼樣的事嗎?', `FemaleText_loc7`='¿Ahora vienes a pedirnos ayuda? ¿Dónde estabas cuando te necesitábamos? ¿Tienes idea de lo que hemos pasado?' WHERE `ID`=26015;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 저주받았소. 내가 당신이라면 더 늦기 전에 여기서 떠날 거요. 살아서 돌아간다면 행운인 줄 아시오.', `MaleText_loc4`='我们完蛋了。我是你的话，就趁现在赶紧离开这里。如果你还能活着回去，那就是走运了。', `MaleText_loc5`='我們死定了。如果我是你的話，我會在事情變得來不及以前快點離開。如果你可以活著回來的話，算你幸運。', `MaleText_loc7`='Estamos perdidos. Si yo fuese tú, me marcharía antes de que sea demasiado tarde. Tendrás suerte si consigues regresar con vida.', `FemaleText_loc1`='우린 저주받았어요. 내가 당신이라면 더 늦기 전에 여기서 떠날 겁니다. 살아서 돌아간다면 행운인 줄 아세요.', `FemaleText_loc4`='我们完蛋了。我是你的话，就趁现在赶紧离开这里。如果你还能活着回去，那就是走运了。', `FemaleText_loc5`='我們死定了。如果我是你的話，我會在事情變得來不及以前快點離開。如果你可以活著回來的話，算你幸運。', `FemaleText_loc7`='Estamos perdidos. Si yo fuese tú, me marcharía antes de que sea demasiado tarde. Tendrás suerte si consigues regresar con vida.' WHERE `ID`=26016;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 얼라이언스 사전 근처의 바닥에 침을 뱉습니다.', `MaleText_loc4`='%s朝联盟特使的脚边啐了一口。', `MaleText_loc5`='%s把口水吐在聯盟特使的腳邊。', `MaleText_loc7`='%s escupe al suelo cerca del enviado de la Alianza.', `FemaleText_loc1`='%s|1이;가; 얼라이언스 사전 근처의 바닥에 침을 뱉습니다.', `FemaleText_loc4`='%s朝联盟特使的脚边啐了一口。', `FemaleText_loc5`='%s把口水吐在聯盟特使的腳邊。', `FemaleText_loc7`='%s escupe al suelo cerca del enviado de la Alianza.' WHERE `ID`=26017;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 무슨...?', `MaleText_loc4`='怎么会……？', `MaleText_loc5`='這是--?', `MaleText_loc7`='¿Qué demo...?', `FemaleText_loc1`='이게 무슨...?', `FemaleText_loc4`='怎么会……？', `FemaleText_loc5`='這是--?', `FemaleText_loc7`='¿Qué demo...?' WHERE `ID`=26018;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동생의 편지를 받을 수 있게 해 줘서 고맙습니다, $c|1이여;여;.$B$B동생의 죽음이 헛되지 않았으니 안심하세요. 푸른용군단은 반드시 이 대가를 치르게 될 겁니다.$B$B내가 직접 그렇게 만들 테니까요!', `MaleText_loc4`='$c，谢谢你，自从收到兄弟的来信后，我就一直在关注这件事。$B$B他的牺牲总算不是徒劳的，愿他的灵魂安息。蓝龙军团会付出惨痛的代价的。$B$B我等着这一天！', `MaleText_loc5`='感謝你，$c，讓我能收到我兄弟的信。$B$B安息吧，他的死將不會白費。藍龍軍團要為此付出代價。$B$B我將會親眼見證!', `MaleText_loc7`='Gracias por hacerme llegar la carta de mi hermano, $c.$B$BPuedes tener la certeza de que su muerte no habrá sido en vano. El Vuelo Azul pagará por esto$B$B¡Me encargaré de ello personalmente!', `FemaleText_loc1`='동생의 편지를 받을 수 있게 해 줘서 고맙습니다, $c|1이여;여;.$B$B동생의 죽음이 헛되지 않았으니 안심하세요. 푸른용군단은 반드시 이 대가를 치르게 될 겁니다.$B$B내가 직접 그렇게 만들 테니까요!', `FemaleText_loc4`='$c，谢谢你，自从收到兄弟的来信后，我就一直在关注这件事。$B$B他的牺牲总算不是徒劳的，愿他的灵魂安息。蓝龙军团会付出惨痛的代价的。$B$B我等着这一天！', `FemaleText_loc5`='感謝你，$c，讓我能收到我兄弟的信。$B$B安息吧，他的死將不會白費。藍龍軍團要為此付出代價。$B$B我將會親眼見證!', `FemaleText_loc7`='Gracias por hacerme llegar la carta de mi hermano, $c.$B$BPuedes estar seguro de que su muerte no habrá sido en vano. El Vuelo Azul pagará por esto$B$B¡Me encargaré de ello personalmente!' WHERE `ID`=26019;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님, 폭풍 바늘이 정상적으로 작동하고 있습니다.', `MaleText_loc4`='尊贵的女士，湍流之针传送器已准备就绪。', `MaleText_loc5`='女士，極濤磁針已經開始全面運作。', `MaleText_loc7`='Mi señora, la Aguja de Flujo funciona a la perfección.' WHERE `ID`=26020;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘했다, 켈도누스. 말리고스 님께서도 기뻐하실 거다.', `FemaleText_loc4`='你做得很好，凯尔多努斯。玛里苟斯一定会对你赞赏有加的。', `FemaleText_loc5`='你做得很好，克爾多努斯。瑪里苟斯大人一定會對你的進展很滿意。', `FemaleText_loc7`='Lo has hecho bien, Keldonus. Lord Malygos estará muy satisfecho con tu progreso.' WHERE `ID`=26021;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 오직 주인님을 위해 살아갈 뿐입니다.', `MaleText_loc4`='为主人效忠就是我活着的意义。', `MaleText_loc5`='我只為了服侍主人而存在，我的女士。', `MaleText_loc7`='Solo vivo para servir al maestro, mi señora.' WHERE `ID`=26022;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마시고 던져라! 던지고 마셔라!', `MaleText_loc4`='丢酒杯！', `MaleText_loc5`='乾了再砸!乾了再砸!', `MaleText_loc7`='¡Bebe y lanza, bebe y lanza!', `FemaleText_loc1`='신나게 마셔요! 신나게 던져요!', `FemaleText_loc4`='丢酒杯！', `FemaleText_loc5`='乾了再砸!乾了再砸!', `FemaleText_loc7`='¡Bebe y lanza, bebe y lanza!' WHERE `ID`=26023;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 나이트 엘프 사원 밑을 지나는 지맥은 이제 청금석 용제단으로 흘러가게 됩니다. 곧 적들을 물리칠 힘이 형제들에게 전해질 겁니다.', `MaleText_loc4`='这座暗夜精灵神殿下的能量线正在朝碧蓝巨龙圣地涌动。我们的兄弟很快就能掌握强大的力量，利用它击溃敌人了。', `MaleText_loc5`='這座夜精靈神殿底下的地脈現在流往了蒼藍龍殿。我們的兄弟將會擁有足夠的力量來粉碎我們的敵人。', `MaleText_loc7`='La línea Ley bajo este templo de los elfos de la noche fluye ahora hacia el Santuario de Dragones Azur. Nuestros hermanos deberían tener todo el poder necesario para aplastar a nuestros enemigos.' WHERE `ID`=26024;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='침입자들을 처리해라, 켈도누스. 일이 끝나면 $n|1이라;라;는 자가 죽었다는 증거를 가져와라. 그 증거를 내 방의 장식품으로 쓰겠다.', `FemaleText_loc4`='凯尔多努斯，解决这场骚乱。将$n的徽记带回来给我。我要用$g他:她;的徽记装饰我的房间。', `FemaleText_loc5`='解決這項阻礙，克爾多努斯。等你完成之後，把那個叫做$n的傢伙的頭給我帶來。我要拿$g他的:她的;頭骨來裝飾我的房間。', `FemaleText_loc7`='Encárgate de esta interrupción, Keldonus. Cuando hayas terminado, tráeme la cabeza de $gaquel:aquella; a quien llaman $n. Decoraré mis aposentos con su calavera.' WHERE `ID`=26025;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='푸른용군단에 도전하겠다니... 그렇다면 네놈들의 영혼과 육신을 분리하는 일로 지루함을 달래야겠다!', `FemaleText_loc4`='我们已经洞悉了这场针对蓝龙军团的侵犯行动。很快，我就会吸干你体内涌动的生命能量！', `FemaleText_loc5`='這項違逆藍龍軍團的行為已經被發現了。當我把你的生命能量從身體剝離出來的時候，一定很好玩!', `FemaleText_loc7`='Hemos tomado nota de esta infracción en contra del Vuelo Azul. ¡Me resultará muy placentero separar la energía vital de tu cuerpo!' WHERE `ID`=26026;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='걱정하지 마시오. 내 뒤에 숨어 있으면 안전할 거요.', `MaleText_loc4`='好吧，孩子。退到我身后去，免得伤到你。', `MaleText_loc5`='沒問題，小子。站在我身後你就會沒事。', `MaleText_loc7`='Bien, $gchico:chica;. Quédate detrás de mí y estarás a salvo.' WHERE `ID`=26027;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='의식의 방이군. 내가 제물이 될 예정이었던...', `MaleText_loc4`='仪式大厅，他们本打算在那里将我作为祭品的……', `MaleText_loc5`='他們的儀祭室，我就是在這被獻祭的...', `MaleText_loc7`='Su cámara ceremonial, el lugar donde me iban a sacrificar...' WHERE `ID`=26028;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 끝을 볼 때도 됐지!', `MaleText_loc4`='是时候阻止这一切了！', `MaleText_loc5`='該是終結這所有事的時候了!', `MaleText_loc7`='¡Es hora de acabar con todo esto!' WHERE `ID`=26029;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이상하군. 보통 이렇게 하면 되는데.', `MaleText_loc4`='奇怪。怎么不对劲呢。', `MaleText_loc5`='奇怪，通常這會有用。', `MaleText_loc7`='Extraño. Eso normalmente funciona.' WHERE `ID`=26030;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스컬지들의 발을 철저하게 묶어둬야 하네! 수상한 움직임이 보이면 모두 보고하게. 먼저 처치하고, 질문은 나중에 하는 거야!', `MaleText_loc4`='士兵，阻止天灾军团的行动！随时向我汇报情况。一旦你发现可疑的人物，不管是谁，先杀了再说！', `MaleText_loc5`='做好你的工作，將天譴軍團擋在海灣，士兵!回報所有可疑的行為，先開殺，之後再提問!', `MaleText_loc7`='¡Haz lo que puedas para mantener a la Plaga a raya, soldado! Informa de cualquier actividad sospechosa y mata primero, ¡ya preguntarás después!' WHERE `ID`=26031;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 말 명심하시오. 이 포세이큰 멍청이들 때문에 우린 다 죽고 말 거요!', `MaleText_loc4`='记住我说过的话，这帮愚蠢的被遗忘者迟早会毁了我们！', `MaleText_loc5`='記下我的話，這些被遺忘者傻蛋會是我們大家死亡的原因!', `MaleText_loc7`='Recuerda mis palabras, estos insensatos Renegados nos conducirán a la muerte a todos.' WHERE `ID`=26032;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='만약 내 생각을 묻는다면, 이미 물었지만, 난 늦기 전에 저 연금술사 놈들을 몽땅 없애버려야 한다고 생각하오!', `MaleText_loc4`='你问我的意见？我觉得我们应该趁早杀掉所有的药剂师！', `MaleText_loc5`='如果你問我，而且你也真的問了，我想我們應該殺掉所有的鍊金師以免事情變得來不及!', `MaleText_loc7`='Si me preguntas a mí, y lo has hecho, creo que deberíamos matar a todos los boticarios antes de que sea demasiado tarde.' WHERE `ID`=26033;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드는 명예와 전쟁을 중요하게 여기지. 하지만 이 연금술사들이 하는 일에 명예라고는 눈곱만큼도 없소.', `MaleText_loc4`='部落是为荣耀与战斗而生的。这帮药剂师肯定在干什么不光彩的勾当。', `MaleText_loc5`='部落就是榮譽跟戰爭。我很確定這些鍊金師在進行的事沒有一丁點跟榮譽有關。', `MaleText_loc7`='La Horda da mucha importancia al honor y a la guerra. Estoy seguro de que no hay nada de honorable en lo que están haciendo los boticarios.' WHERE `ID`=26034;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 아래에 있는 포세이큰 멍청이들을 감시하고 있소. 저놈들에게는 아무리 주의를 기울여도 모자랄 지경이오!', `MaleText_loc4`='我始终留意着这群白痴的一举一动。真是怎么提防都不为过！', `MaleText_loc5`='我一直在注意下面這些被遺忘者的白癡。你在他們附近時應該要格外小心!', `MaleText_loc7`='Estoy vigilando a esos idiotas Renegados de ahí abajo. ¡Ninguna precaución está de más con esa gente!' WHERE `ID`=26035;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 뭐지?', `MaleText_loc4`='这是什么？', `MaleText_loc5`='這是什麼?', `MaleText_loc7`='¿Qué es esto?' WHERE `ID`=26036;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으으, 뱀은 싫은데!', `MaleText_loc4`='啊！！蛇！', `MaleText_loc5`='噢，拜託不要是蛇!', `MaleText_loc7`='¡Jooo, una culebra no!' WHERE `ID`=26037;
