UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간이 됐군! 어서 목재를 챙겨서 이동하라고. 아무리 호드라도 세상 끝날 때까지 싸우진 않을 거란 말이지. 돈을 벌 때는 바로 지금이라고!', `MaleText_loc4`='趁现在！抬起那根木材就跑吧。部落不会打上一辈子仗，眼下正是赚钱的好机会呀！', `MaleText_loc5`='該是時候了!帶著木材然後出發吧。部落不會永遠都在那邊戰鬥，還有錢等著去賺呢!', `MaleText_loc7`='¡Ya era hora! Coge esa madera y muévete. ¡La Horda no luchará eternamente allí arriba, pero hay dinero que ganar!' WHERE `ID`=26079;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='인상적이야, 안 그런가? 이 거인들은 훌륭한 총알받이... 아니, 동맹이 될 거라고. 저기 있는 친구가 녀석들의 지도자인데, 내 얘기는 들은 척도 않는 게 흠이지.', `MaleText_loc4`='很震撼吧？这些巨人简直是完美的炮灰……呃，是盟友啦。这位就是他们的首领，但他一直拒绝和我谈话。', `MaleText_loc5`='令人驚嘆，不是嗎?這些巨人可以成為完美的飼料...呃，我是說盟友。這位是他們的領袖，但他一直不願和我交談。', `MaleText_loc7`='Impresionantes, ¿verdad? Estos gigantes serían un forra… estoooo... unos aliados perfectos. Este es su líder, pero sigue negándose a hablar conmigo.' WHERE `ID`=26080;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑다, $r|1이여;여;. 용을 피해 여기까지 왔다면 우리와 함께 얼마든지 머물러도 좋다. 저쪽에 있는 고블린 꼬마를 조심해라... 믿을 수 없는 족속이니 말이다.', `MaleText_loc4`='你好，$r。你也是为了躲避巨龙才来到这条峡谷的吧，我们欢迎你啊。但是你要当心那个矮小的家伙……地精就没一个可靠的。', `MaleText_loc5`='哈囉，$r。歡迎你和我們分享這個峽谷，躲避那些飛龍。但要小心那些哥布林矮子...他們不可以信任。', `MaleText_loc7`='Hola, $r. Puedes compartir este cañón con nosotros para refugiarte de los dragones. Pero ten cuidado con el renacuajo goblin... los de su calaña no son de fiar.' WHERE `ID`=26081;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돈만 잔뜩 있으면 세상을 지배할 수도 있을 텐데...', `MaleText_loc4`='只要有足够的钱，我就能征服全世界……', `MaleText_loc5`='只要有夠多的錢，我就可以統治全世界...', `MaleText_loc7`='Si tuviera dinero suficiente, podría conquistar el mundo...' WHERE `ID`=26082;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기계가 있는 뒤쪽으로 파편과 함께 김이 납니다. 그 아래에서 엔진 소리가 들려 옵니다.', `MaleText_loc4`='这个控制台后面是一大堆碎石块。发动机的声音从地下传来。', `MaleText_loc5`='控制臺位在冒煙的碎石堆前面，你可以聽見底下傳來引擎的聲響。', `MaleText_loc7`='Esta consola se encuentra delane de unos escombros envueltos en vapor. Debajo se oye el sonido de un motor.', `FemaleText_loc1`='기계가 있는 뒤쪽으로 파편과 함께 김이 납니다. 그 아래에서 엔진 소리가 들려 옵니다.', `FemaleText_loc4`='这个控制台后面是一大堆碎石块。发动机的声音从地下传来。', `FemaleText_loc5`='控制臺位在冒煙的碎石堆前面，你可以聽見底下傳來引擎的聲響。', `FemaleText_loc7`='Esta consola se encuentra delane de unos escombros envueltos en vapor. Debajo se oye el sonido de un motor.' WHERE `ID`=26083;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제어 장치의 지렛대를 당깁니다.', `MaleText_loc4`='扳动控制台的操纵杆。', `MaleText_loc5`='拉下控制臺的拉桿。', `MaleText_loc7`='Tira de las palancas de la consola.', `FemaleText_loc1`='제어 장치의 지렛대를 당깁니다.', `FemaleText_loc4`='扳动控制台的操纵杆。', `FemaleText_loc5`='拉下控制臺的拉桿。', `FemaleText_loc7`='Tira de las palancas de la consola.' WHERE `ID`=26084;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 심장을 가져가다니, 그렇다면 난 네 것을 가져가마!', `MaleText_loc4`='你夺走了我的东西，我也要来拿你的！', `MaleText_loc5`='你拿走了我的心，現在我要拿走你的!', `MaleText_loc7`='¡Tú te quedas mi corazón y ahora yo me quedo el tuyo!' WHERE `ID`=26085;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 남의 내장을 가지고 장난치는 거냐?', `MaleText_loc4`='干嘛非得把我惹火呢？', `MaleText_loc5`='老兄，為什麼你要亂搞我的內臟?', `MaleText_loc7`='¿Por qué quieres enredar con mis entrañas, colega?' WHERE `ID`=26086;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 손에 그거, 내 간이잖나!', `MaleText_loc4`='你弄疼我了！', `MaleText_loc5`='讓我把你送去壓扁，老兄!', `MaleText_loc7`='¡Eso que estás estrujando es mi hígado, colega!' WHERE `ID`=26087;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 창자 내놔라, 이 $r 녀석!', `MaleText_loc4`='不许拿我的东西，$r！', `MaleText_loc5`='帶著我的內臟一起回來這裡，$r!', `MaleText_loc7`='¡Vuelve aquí con mis tripas, $r!' WHERE `ID`=26088;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 짓이냐?', `MaleText_loc4`='你以为自己在干什么？', `MaleText_loc5`='你以為你在做什麼?', `MaleText_loc7`='¿Qué crees que estás haciendo?' WHERE `ID`=26089;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 짓을 저지른 대가를 치르게 해주마!', `MaleText_loc4`='你会为此付出代价的！', `MaleText_loc5`='你要付出代價!', `MaleText_loc7`='¡Pagarás por esto!' WHERE `ID`=26090;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어리석은 놈! 너는 절대 도망칠 수 없다!', `MaleText_loc4`='蠢货！你永远别想逃脱！', `MaleText_loc5`='傻瓜!你永遠也逃不掉的!', `MaleText_loc7`='¡Insensato! ¡Nunca te saldrás con la tuya!' WHERE `ID`=26091;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 무쇠의 후예에게 덤빈단 말이냐?', `MaleText_loc4`='你竟敢挑衅钢铁的子嗣？', `MaleText_loc5`='你膽敢反抗鐵之子?', `MaleText_loc7`='¿Te atreves a desafiar a los hijos del hierro?' WHERE `ID`=26092;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드미트리! 안톤! 내가 누군지 모르겠나? 걱정하지 말게. 곧 편히 쉬게 해주겠네!', `MaleText_loc4`='迪米特里！安东尼！你们不认识我了吗？别担心，我会让你们的灵魂安息的！', `MaleText_loc5`='迪米特里!安東!你們不認得我了嗎?別擔心，我會讓你們的靈魂安息的!', `MaleText_loc7`='¡Dimitri! ¡Anton! ¿No me reconocen? No se preocupen, ¡otorgaré el descanso eterno a sus almas!' WHERE `ID`=26093;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네들의 가족이 이런 모습을 보게 두진 않겠네! 광부란 모름지기 서로 돌봐야 하는 법이지!', `MaleText_loc4`='我不会让你们的家人看到你们这副模样的！矿工就应该互相照顾啊！', `MaleText_loc5`='我不會讓你的家人看你這樣!我們礦工要彼此照顧!', `MaleText_loc7`='¡No dejaré que sus familias los vean así! ¡Los mineros tenemos que cuidarnos unos a otros!' WHERE `ID`=26094;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 이야기를 반드시 전하겠네! 빈돌 광산의 광부들은 끝까지 굴복하지 않았다고 모든 이에게 전하겠어!', `MaleText_loc4`='朋友们，我会将你们的事迹传播开来的！我要所有人都知道空石矿洞的矿工永远不会说放弃！', `MaleText_loc5`='我會傳頌你的故事，朋友!我會告訴每個人穴石礦工是如何的永不放棄!', `MaleText_loc7`='¡Contaré su historia, amigos! ¡Le contaré a todo el mundo cómo los mineros de Piedrahueca no se rindieron jamás!' WHERE `ID`=26095;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여행자여, 고룡쉼터 사원에 온 것을 환영하오.$B$B이곳은 위대한 선조의 유골 사이에서 용군단이 서로 평화롭게 회담하는 장소라오.$B$B최소한 푸른용군단이 사원을 습격하기 전까지는 평화로운 곳이었소.$B$B들어오시오. 우리의 축복과 함께 들어오되, 여기서는 그 어떤 폭력도 용납되지 않음을 명심하시오.', `MaleText_loc4`='旅行者，欢迎来到龙眠神殿。$B$B这里供奉着巨龙先祖的遗骸，是巨龙们商谈要事的圣地。$B$B但是最近，蓝龙军团突然对神殿发动攻击，打破了持续数千年的宁静。$B$B带着我们的祝福进入神殿吧，但是请谨记，我们绝不允许任何挑衅行为。', `MaleText_loc5`='歡迎來到龍眠神殿，旅人。$B$B這裡是龍群想在他光榮的先祖骸骨中尋找一處平靜的所在。$B$B這一切原本都很平和，直到藍龍軍團對神殿發動了一次突襲。$B$B帶著我們的祝福進去，但要知道我們不容許任何的暴力在其中發生。', `MaleText_loc7`='$gBienvenido:Bienvenida; al Templo del Reposo del Dragón, caminante.$B$BAquí los Vuelos conviven en paz unos con otros entre los huesos de sus honrados ancestros.$B$BAl menos, había paz hasta que el Vuelo Azul inició un ataque sorpresa contra el Templo.$B$BEntra con nuestra bendición, pero ten en cuenta que no toleraremos ninguna agresión en este lugar sagrado.' WHERE `ID`=26096;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 대가도 없이 나를 불러냈단 말이냐!', `MaleText_loc4`='你连祭品都没有准备就敢召唤我！', `MaleText_loc5`='你竟敢沒有祭品就召喚我!', `MaleText_loc7`='¿Cómo te atreves a invocarme sin una ofrenda?' WHERE `ID`=26098;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다시 내려가고 싶으신가요, $c님?$B$B여기 비룡 중 하나가 당신이 가야 할 곳으로 안전하게 데려다 줄 거예요.', `FemaleText_loc4`='$c，你想回去？$B$B我可以派一条幼龙将你安全地送达目的地。', `FemaleText_loc5`='你想要回去嗎，$c?$B$B我可以看看有沒有哪隻飛龍願意載你前往你要去的地方。', `FemaleText_loc7`='¿Quieres volver abajo, $c?$B$BPuedo hacer que uno de estos dracos te lleve a salvo hasta donde quieras ir.' WHERE `ID`=26099;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예, 다시 아래층으로 내려가고 싶습니다.', `MaleText_loc4`='嗯，我想返回神殿底层。', `MaleText_loc5`='喔，謝謝，我想要回到神殿的底層。', `MaleText_loc7`='Sí, por favor, me gustaría regresar a la planta baja del templo.', `FemaleText_loc1`='예, 다시 아래층으로 내려가고 싶어요.', `FemaleText_loc4`='嗯，我想返回神殿底层。', `FemaleText_loc5`='喔，謝謝，我想要回到神殿的底層。', `FemaleText_loc7`='Sí, por favor, me gustaría regresar a la planta baja del templo.' WHERE `ID`=26100;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 내버려두십시오, 어리석은 자여!', `MaleText_loc4`='别来烦我，蠢货！', `MaleText_loc5`='少煩我，蠢蛋!', `MaleText_loc7`='¡Déjame en paz, $ginsensato:insensata;!' WHERE `ID`=26101;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그놈은 여기서 도망갈... 수 있다고 믿었나 보군... 너 역시 살아서 나갈 순 없다.', `MaleText_loc4`='瞧，这孩子以为自己能顺利逃脱呢……你们谁都别想活着离开。', `MaleText_loc5`='那個男孩相信自己可以逃脫...你們任何一個人都不應該讓他活著離去。', `MaleText_loc7`='El chico creía que podía esssscapar... Ninguno de vosssotrosss sssaldrá de aquí con vida.' WHERE `ID`=26102;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우릴 모두 죽여봤자 소용없다... 놈을 찾아 더 많은 자들이 올 것이다...', `MaleText_loc4`='杀了我们吧……会有更多的后来者……', `MaleText_loc5`='把我們全給殺了...只會讓更多人找上他...', `MaleText_loc7`='Matadnossss a todosss... vendrán másss a por él...' WHERE `ID`=26103;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나약해! 이 영혼은 거두어들일 가치조차 없구나...', `MaleText_loc4`='放弃吧！他的灵魂根本不值得救赎……', `MaleText_loc5`='軟弱!這個靈魂不值得拯救...', `MaleText_loc7`='¡Quietossss! No vale la pena ssssalvar esta alma...' WHERE `ID`=26104;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 큰 실수를 했다...', `MaleText_loc4`='你犯了个严重的错误……', `MaleText_loc5`='你犯下了一個嚴重的錯誤...', `MaleText_loc7`='Habéissss cometido un grave error...' WHERE `ID`=26105;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절대 피할 수 없을 거다. 왜냐고? 넌 그냥 꼬마일 뿐이니.', `MaleText_loc4`='你是不可能摆脱宿命的，明白吗？你不过是个孩子。', `MaleText_loc5`='你逃不掉的，你知道嗎?你只是個小鬼。', `MaleText_loc7`='No te saldrás con la tuya, ¿lo sabes? No eres más que una niña.' WHERE `ID`=26106;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나이가 어떻게 되지?', `MaleText_loc4`='小姑娘，你才多大？', `MaleText_loc5`='你多大年紀，小鬼頭?', `MaleText_loc7`='¿Cuántos años tienes, chica?' WHERE `ID`=26107;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='결국은 우리 모두가 리치 왕님을 섬기게 된다, 꼬마야. 시체가 되어 썩어가는 것보단 그게 나을 거다.', `MaleText_loc4`='最终，我们都会成为巫妖王的仆从。孩子，这比变成一具腐烂的尸体好多了。', `MaleText_loc5`='我們最終都會服侍巫妖王，小鬼。這樣總比一具腐爛的屍體好。', `MaleText_loc7`='Todos acabaremos sirviendo al Rey Exánime, chica. Mejor de este modo que acabar siendo un cadáver podrido.' WHERE `ID`=26108;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 아버지는 나약했다, 사샤... 자기가 해야 할 일을 해낼 수 있는 배짱이 없었다.', `MaleText_loc4`='你的父亲是个懦夫，萨莎……他没有勇气完成自己的使命。', `MaleText_loc5`='你的父親是個軟弱的傢伙，莎夏...他沒膽做他應該要做的。', `MaleText_loc7`='Tu padre era débil, Sasha... no tenía valor para hacer lo que había que hacer.' WHERE `ID`=26109;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너 같은 짐승의 미간에 화살을 박아줄 정도의 나이는 먹었다... 지금의 두 배나 되는 거리에서도 말이지.', `FemaleText_loc4`='别小瞧我，我也能一箭射中野兽的眉心……而且是在两倍距离开外。', `FemaleText_loc5`='我已經大到足以把子彈射進你這樣野獸的眉心...在兩倍的距離之外。', `FemaleText_loc7`='Soy lo bastante mayor para disparar a bestias como tú entre los ojos... desde el doble de distancia.' WHERE `ID`=26110;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너처럼 되느니 차라리 죽음을 택하겠다! 아직도 네가 인간인 줄 아는 건가? 이... 짐승 같은 녀석!', `FemaleText_loc4`='我宁愿死也不要变成你们那副模样！你们还是人吗？是……畜生！', `FemaleText_loc5`='我寧可死也不要變得跟你一樣!你以為你還是人類嗎?你根本就是...畜生!', `FemaleText_loc7`='¡Preferiría morir a ser una de ustedes! ¿Créen que aún son humanos? ¡Son... animales!' WHERE `ID`=26112;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그 더러운 입에 내 아버지를 올리지 마라, 괴물아. 네가 아무리 발버둥쳐도 그분의 반도 따라가지 못할 테니까.', `FemaleText_loc4`='你居然敢侮辱我的父亲。他比你勇敢得多。', `FemaleText_loc5`='你再敢說我父親試試看，怪物。他絕對比你還更像個男子漢。', `FemaleText_loc7`='No te atrevas a hablar de mi padre, monstruo. Él era mucho más hombre de lo que tú serás jamás.' WHERE `ID`=26113;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 녀석은 자유를 얻었다고 믿었겠지만, 자유에는 대가가 따르는 법이다. 악마가 녀석을 괴롭히고 있지. 아니, 녀석뿐 아니라 나를 벗어나려 한 모든 죽음의 기사를...', `MaleText_loc4`='这孩子以为他自由了，但自由是要付出代价的。那些曾经受我牵制的恶魔，将为他以及所有企图逃跑的死亡骑士带去厄运……', `MaleText_loc5`='這孩子以為他自由了，但自由是要付出代價的。我所掌握的無數惡魔，將給他，以及所有企圖逃跑的死亡騎士帶去惡運...', `MaleText_loc7`='El chico creyó que era libre, pero la libertad tiene un precio. Los demonios que controlo están sobre él y los caballeros de la muerte que intentan escapar... ' WHERE `ID`=26114;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모그레인의 희생에는 아무 의미도 없었다. 콜티라에게 전해라. 알겠느냐?', `MaleText_loc4`='莫格莱尼的牺牲毫无意义。你会让库尔迪拉明白这一点的，对吧？', `MaleText_loc5`='莫格萊尼的犧牲毫無意義。你會讓寇爾提拉明白這一點的，對吧?', `MaleText_loc7`='El sacrificio de Mograine fue en vano. ¿Le avisarás a Koltira?' WHERE `ID`=26115;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 기억해 둬라. 지금은 너에게 자유를 주겠다. 원하는 곳에 충성을 바쳐라. 하지만 결국엔, 너는 내 차지가 될 것이다. 어떤 식으로든...', `MaleText_loc4`='记住，凡人：现在，我会给你选择的机会，我将允许你选择为谁效忠。但，殊途同归，你终将属于我。', `MaleText_loc5`='記住，凡人:現在，我給你一個選擇的機會，我將允許你選擇為誰效忠。但殊途同歸，你終將屬於我。', `MaleText_loc7`='Y recuerda esto, mortal: por ahora tienes opciones. Te permitiré elegir tu lealtad, pero al final, de una forma u otra, me pertenecerás.' WHERE `ID`=26116;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 호드... 언제나 귀찮게 하는군. 제대로 맞이하는 게 도리겠지. 반갑다, 벌레야. 내 왕국에 온 것을 환영한다.', `MaleText_loc4`='啊，部落……还是这么爱管闲事。我觉得应该好好欢迎一下你们。那么，欢迎，蝼蚁们。欢迎来到我的世界。', `MaleText_loc5`='噢，部落...還是這麼愛管閒事。的確應該好好歡迎你們。那麼，歡迎，螻蟻們。歡迎來到我的世界。', `MaleText_loc7`='Ah, la Horda... entrometiéndose, como siempre. Corresponde una bienvenida. Así que: bienvenidos, insectos, a mi mundo.' WHERE `ID`=26117;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너는 해답을 찾고자 죽음의 세계로 건너왔다. 동료를 돕겠다는 일념 하에 네 사지를, 목숨을 내던졌지. 내가, 널 도와주마.', `MaleText_loc4`='你们来到这个属于死者的世界寻求答案。你们带着拯救盟友的希望，冒着失去生命的危险艰难地爬行到了这里。那么，请允许我帮帮你们吧。', `MaleText_loc5`='你為了尋求答案而踏入亡者的世界。你期望能拯救你的同伴而甘冒生命之險，來到此地。讓我來助你一臂之力。', `MaleText_loc7`='Entraron al mundo de los muertos en busca de respuestas. Quieren salvar a su aliado y arriesgaron la vida para llegar aquí. Permítanme ayudar.' WHERE `ID`=26118;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐요? 내 밑에서 배우고 싶다고? 일할 준비를 먼저 하는 게 좋을 거요.', `MaleText_loc4`='嗯？$c，你想接受我的训练？那你最好做好准备。', `MaleText_loc5`='什麼?你想要在我底下受訓，$c?你最好準備好上工。', `MaleText_loc7`='¿Qué? ¿Quieres entrenar conmigo, $c? Más vale que tengas ganas de trabajar.' WHERE `ID`=26119;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠의 세계로 돌아가야겠습니다, 콜티라. 다시 보내 주십시오.', `MaleText_loc4`='我必须返回阴影世界，库尔迪拉。送我回去吧。', `MaleText_loc5`='我必須要回到暗影的世界，寇爾提拉。送我回去。', `MaleText_loc7`='Debo volver al mundo de las sombras, Koltira. Envíame de vuelta.', `FemaleText_loc1`='어둠의 세계로 돌아가야겠습니다, 콜티라. 다시 보내 주십시오.', `FemaleText_loc4`='我必须返回阴影世界，库尔迪拉。送我回去吧。', `FemaleText_loc5`='我必須要回到暗影的世界，寇爾提拉。送我回去。', `FemaleText_loc7`='Debo volver al mundo de las sombras, Koltira. Envíame de vuelta.' WHERE `ID`=26120;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청한 트롤 같으니. 네놈도 우리의 일원이 될 거다. 좀비들아! 공격해라!', `MaleText_loc4`='愚蠢的巨魔，加入我们的行列吧。僵尸！进攻！', `MaleText_loc5`='愚蠢的食人妖，你將會加入我們。殭屍!攻擊!', `MaleText_loc7`='Insensato trol, te unirás a nuestras filas. ¡Zombi! ¡Ataca!' WHERE `ID`=26121;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좀비들아! 놈을 죽여라!', `MaleText_loc4`='僵尸！杀了他！', `MaleText_loc5`='殭屍!殺死他!', `MaleText_loc7`='¡Zombi! ¡Mátalo!' WHERE `ID`=26122;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스컬지의 힘 앞에 드라카리 따위가 얼마나 오래 버티는지 지켜봐 주마!', `MaleText_loc4`='就让我们瞧瞧达卡莱巨魔要如何应对强大的天灾军团吧！', `MaleText_loc5`='我們要看看德拉克瑞要怎麼對抗天譴軍團的力量!', `MaleText_loc7`='¡Veamos cómo resisten el poder de la Plaga los Drakkari!' WHERE `ID`=26123;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='병영에서 자도 좋네. 하지만 내 부하들을 깨우지 않게 조심하게. 그랬다가는 내가 직접 눈밭에 내던져버릴 테니.', `MaleText_loc4`='如果你愿意的话，就去兵营休息吧。但不要吵醒我的士兵，不然我会亲手将你扔到雪地里。', `MaleText_loc5`='如果你想的話，你可以睡在兵營裡。只是不要吵醒我的人，否則我會親自把你丟到雪裡。', `MaleText_loc7`='Puedes dormir en los barracones, si quieres. Pero no despiertes a mis hombres o te tiraré a la nieve yo mismo.' WHERE `ID`=26124;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예열을 시작합니다.', `MaleText_loc4`='启动预热程序。', `MaleText_loc5`='熱身程序開始。', `MaleText_loc7`='Secuencia de calentamiento iniciada.' WHERE `ID`=26125;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구해줘서 고맙네, $n. 그대의 용기와 결단력을 절대 잊지 않겠네.', `MaleText_loc4`='谢谢你救了我，$n。我永远不会忘记你的勇气和决心。', `MaleText_loc5`='謝謝你解救了我，$n。我永遠都不會忘記你的勇氣和決心。', `MaleText_loc7`='Gracias por rescatarme, $n. Nunca olvidaré tu valor y determinación.' WHERE `ID`=26126;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, 대족장님. 저의 초대를 받아들여 타운카의 지도자로서 정식으로 호드의 일원이 되어주신다면 제게 더없는 명예가 될 것입니다.', `MaleText_loc4`='大酋长，您好。请问您是否愿意接受我的邀请，以牦牛人首领的身份正式加入部落呢？', `MaleText_loc5`='您好，坦卡大酋長。我有榮幸邀請您加入部落，正式成為我們的一員以及坦卡族的領袖嗎?', `MaleText_loc7`='Saludos Gran Jefe. ¿Me harías el honor de aceptar mi invitación para unirte a la Horda como miembro oficial y líder de los taunka?', `FemaleText_loc1`='안녕하세요, 대족장님. 저의 초대를 받아들여 타운카의 지도자로서 정식으로 호드의 일원이 되어주신다면 제게 더없는 명예가 될 것입니다.', `FemaleText_loc4`='大酋长，您好。请问您是否愿意接受我的邀请，以牦牛人首领的身份正式加入部落呢？', `FemaleText_loc5`='您好，坦卡大酋長。我有榮幸邀請您加入部落，正式成為我們的一員以及坦卡族的領袖嗎?', `FemaleText_loc7`='Saludos Gran Jefe. ¿Me harías el honor de aceptar mi invitación para unirte a la Horda como miembro oficial y líder de los taunka?' WHERE `ID`=26127;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드의 형제로서 그대와 함께 싸운다면 우리 또한 명예로울 것일세, $n. 그대의 제안을 받아들이지.', `MaleText_loc4`='$n，能以部落的兄弟的身份与你并肩作战是我的荣幸。我接受你的提议。', `MaleText_loc5`='能夠以部落兄弟的身分與你並肩共戰是我的榮幸，$n。我接受你的提議。', `MaleText_loc7`='Será un honor luchar junto a ti como hermano de la Horda, $n. Acepto tu oferta.' WHERE `ID`=26128;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오히려 제가 영광입니다, 대족장님. 이 두루마리를 읽어 주십시오. 충성의 맹세가 쓰여 있습니다.', `MaleText_loc4`='大酋长，这是我的荣幸才对。喏，这份卷轴就是结盟的誓约，请您过目。', `MaleText_loc5`='這是我莫大的榮幸，大酋長。請看這個卷軸，這是盟約的誓詞。', `MaleText_loc7`='Eres tú quien me honra, Gran Jefe. Por favor, lee este pergamino. Es el juramento de lealtad.', `FemaleText_loc1`='오히려 제가 영광입니다, 대족장님. 이 두루마리를 읽어 주십시오. 충성의 맹세가 쓰여 있습니다.', `FemaleText_loc4`='大酋长，这是我的荣幸才对。喏，这份卷轴就是结盟的誓约，请您过目。', `FemaleText_loc5`='這是我莫大的榮幸，大酋長。請看這個卷軸，這是盟約的誓詞。', `FemaleText_loc7`='Eres tú quien me honra, Gran Jefe. Por favor, lee este pergamino. Es el juramento de lealtad.' WHERE `ID`=26129;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 두루마리를 읽으려 하자 타운카들이 주변에 모여듭니다.', `MaleText_loc4`='%s让其他牦牛人都聚集在他身边，并按照卷轴上的内容诵读了誓言。', `MaleText_loc5`='%s讀著卷軸時，其他的坦卡族聚集在他身邊。', `MaleText_loc7`='%s lee el pergamino mientras los otros taunka se reúnen a su alrededor.' WHERE `ID`=26130;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 그에게 같이 가세나, $n.', `MaleText_loc4`='$n，让我们并肩战斗吧。', `MaleText_loc5`='我們將肩並肩，$n。', `MaleText_loc7`='Caminaremos juntos, $n.' WHERE `ID`=26131;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕! 이 친구들은 승강기를 제시간까지 고칠 자신이 없어서 우리 형제를 여기로 불렀다고. 위로 올라가고 싶어?', `MaleText_loc4`='嗨。他们不确定这台升降梯能否正常运行，因此请了我和我的兄弟来帮忙。你想上去吗？', `MaleText_loc5`='唷。他們不確定升降梯是否會準時作用，所以他們叫我和我的兄弟來。你要上去嗎?', `MaleText_loc7`='Hola. No estaban seguros de que este elevador fuera a estar preparado a tiempo, así que nos llamaron a mí y a mi hermano. ¿Necesitas subir?' WHERE `ID`=26132;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전쟁노래 요새 꼭대기로 올라가고 싶습니다.', `MaleText_loc4`='我要到战歌要塞的顶层。', `MaleText_loc5`='我想要上去戰歌堡的頂端。', `MaleText_loc7`='Me gustaría llegar a lo alto del Bastión Grito de Guerra.', `FemaleText_loc1`='전쟁노래 요새 꼭대기로 올라가고 싶어요.', `FemaleText_loc4`='我要到战歌要塞的顶层。', `FemaleText_loc5`='我想要上去戰歌堡的頂端。', `FemaleText_loc7`='Me gustaría llegar a lo alto del Bastión Grito de Guerra.' WHERE `ID`=26133;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑군! 이 친구들은 승강기를 제시간까지 고칠 자신이 없어서 우리 형제를 여기로 불렀다고. 아래로 내려가고 싶어?', `MaleText_loc4`='嗨。他们不确定这台升降梯能否正常运行，因此请了我和我的兄弟来帮忙。你想下去吗？', `MaleText_loc5`='嘿呀。他們不確定升降梯是否會準時作用，所以他們叫我和我的兄弟來。你要下去嗎?', `MaleText_loc7`='Hola. No estaban seguros de que este elevador fuera a estar preparado a tiempo, así que nos llamaron a mí y a mi hermano. ¿Necesitas bajar?' WHERE `ID`=26134;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전쟁노래 요새 아래쪽으로 내려가고 싶습니다.', `MaleText_loc4`='我要到战歌要塞的底层。', `MaleText_loc5`='我想要下去戰歌堡的底部。', `MaleText_loc7`='Me gustaría llegar a la parte baja del Bastión Grito de Guerra.', `FemaleText_loc1`='전쟁노래 요새 아래쪽으로 내려가고 싶어요.', `FemaleText_loc4`='我要到战歌要塞的底层。', `FemaleText_loc5`='我想要下去戰歌堡的底部。', `FemaleText_loc7`='Me gustaría llegar a la parte baja del Bastión Grito de Guerra.' WHERE `ID`=26135;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모이시오, 형제자매들이여.', `MaleText_loc4`='同胞们，集合。', `MaleText_loc5`='靠過來，兄弟姊妹們。', `MaleText_loc7`='Reuníos, hermanos y hermanas.' WHERE `ID`=26136;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='록타르 오가르! 승리가 아니면 죽음뿐! 바로 우리를 호드로서 묶어주는 말이다. 호드의 모든 용사들에게 있어 가장 신성하고 중요한 믿음이기 때문이다.', `MaleText_loc4`='Lok''tar ogar！不胜利，毋宁死——正是这条被所有的部落成员奉为真理的信条促使我加入部落！', `MaleText_loc5`='(獸人語)Lok''tar ogar!不勝即亡 - 就是這幾個字讓我跟部落連結在一起!對任何一個部落的戰士而言，這幾個字是最神聖且基本的真理。', `MaleText_loc7`='¡Lok''tar ogar! Victoria o muerte: estas son las palabras que me unen a la Horda, ya que son las más sagradas y fundamentales verdades para cualquier guerrero de la Horda.' WHERE `ID`=26137;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 내 피와 육체를 호드에 바칠 것이다. 나는 대족장님의 뜻을 실천하는 도구가 될 것이다. 나는 대족장님의 명령을 따르는 무기가 될 것이다.', `MaleText_loc4`='我发誓终身效忠于萨尔酋长。他的意志就是我的信条。他的指令就是我的使命！', `MaleText_loc5`='我將我的血肉無條件獻給大酋長，我將完成所有大酋長的意志，我就是大酋長命令下的武器!', `MaleText_loc7`='Entrego mi cuerpo y sangre libremente al Jefe de Guerra. Soy el instrumento de los deseos de mi Jefe de Guerra. ¡Soy el arma de las órdenes de mi Jefe de Guerra!' WHERE `ID`=26138;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 이 순간부터 내 최후의 순간까지, 나는 이 목숨을 다 바칠 것이다. 호드를 위하여!', `MaleText_loc4`='从这一刻直到我阖上双眼——为了部落！', `MaleText_loc5`='從此刻開始一直到末日，我的死活都是 - 為了部落!', `MaleText_loc7`='¡Desde este momento y hasta el fin de los días, vivo y muero por la Horda!' WHERE `ID`=26139;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타운카 형제와 자매들을 위하여! 호드를 위하여!', `MaleText_loc4`='为了我们的牦牛人同胞！为了部落！', `MaleText_loc5`='為了我的坦卡族兄弟姐妹們!為了部落!', `MaleText_loc7`='¡Por mis hermanos y hermanas taunka! ¡POR LA HORDA!' WHERE `ID`=26140;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드의 일원이 된 걸 환영하오, 대족장. 록타르 오가르!', `MaleText_loc4`='欢迎加入部落，大酋长。Lok''tar ogar！', `MaleText_loc5`='歡迎加入部落，大酋長。(獸人語)不勝即亡!', `MaleText_loc7`='Bienvenido a la Horda, Gran Jefe. ¡Lok''tar ogar!' WHERE `ID`=26141;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드를 위하여!', `MaleText_loc4`='为了部落！', `MaleText_loc5`='為了部落!', `MaleText_loc7`='¡POR LA HORDA!' WHERE `ID`=26142;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용을 잡아 보기 전까지는 진정한 용사라고 할 수 없지요...', `MaleText_loc4`='除非你亲手杀死一条龙，否则我可不认你这个朋友……', `MaleText_loc5`='除非你殺過龍，否則你不算個真男人...老兄。', `MaleText_loc7`='No serás $gun verdadero:una verdadera; colega hah''ta que hayas mata''o un dragón... colega.' WHERE `ID`=26143;
