UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='반갑습니다, $r|1이여;여;. 그대가 처음으로 보게 된 우리 성지가 하필 이런 상태라 안타깝군요.', `FemaleText_loc4`='你好，$r。这是你首次踏上我们的圣地吧，让你目睹这样的情景真是抱歉。', `FemaleText_loc5`='哈囉，$r。對於你第一次參觀我們神聖的土地是在這樣的情況下令我感到很抱歉。', `FemaleText_loc7`='Hola, $r. Siento que la primera vez que veas nuestra tierra sagrada sea en este estado.' WHERE `ID`=26145;
