UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 녀석들! 드라카리 제국이 너희를 가만 둘 것 같으냐!', `MaleText_loc4`='朋友，达卡莱帝国不会支持天灾军团的！', `MaleText_loc5`='德拉克瑞帝國不能容忍這個傢伙!', `MaleText_loc7`='¡El imperio Drakkari no tolerará esto, colega!' WHERE `ID`=26160;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='버텨라, 형제들아! 놈들에게 굴복해서는 안 돼!', `MaleText_loc4`='兄弟们，坚持住！别加入天灾军团！', `MaleText_loc5`='抗拒它，兄弟們!不要加入他們那一邊!', `MaleText_loc7`='¡Resistidlo, hermanos míos! ¡No os volváis uno de ellos!' WHERE `ID`=26161;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 노예 녀석들이 이번엔 제대로 된 식사를 가져왔군!', `MaleText_loc4`='哈！奴隶们总算带回一顿真正的美餐啦！', `MaleText_loc5`='哈!我的奴隸這次帶回來一份真正的餐點!', `MaleText_loc7`='¡Ja! ¡Esta vez mis esclavos han traído una comida de verdad!' WHERE `ID`=26162;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 죽음은 조금 늦춰졌을 뿐, 피할 수 없도다! 죽음의 군대가 얼음왕관의 심장부에서 일어나 행진할 때 공포의 요새가 동쪽에서 솟아오르리라!', `MaleText_loc4`='你不过是在阻挠命中注定的结局！东方矗立起恐惧之城，而亡者大军将朝着冰冠冰川的中心挺进！', `MaleText_loc5`='你只延後了不可避免之事!驚懼城塞隨著來自寒冰皇冠的死亡大軍一同出現在東邊!', `MaleText_loc7`='¡Solo retrasáis lo inevitable! ¡La temible ciudadela se eleva al este a medida que los ejércitos de muertos caminan desde Corona de Hielo!' WHERE `ID`=26163;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까. 필요한 게 있으면 말씀하십시오.', `MaleText_loc4`='嘿！需要什么东西，直接告诉我就行啦。', `MaleText_loc5`='你好啊。如果你需要什麼，直接告訴我。', `MaleText_loc7`='Hola. Si necesitas algo, házmelo saber.' WHERE `ID`=26164;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스컬지 괴물 녀석들... 머지않아 대가를 치를 거다.', `MaleText_loc4`='可恨的天灾军团……他们很快就会得到报应的。', `MaleText_loc5`='天譴雜碎...他們很快就要得到報應了。', `MaleText_loc7`='Aberraciones de la Plaga... Muy pronto recibirán su merecido.' WHERE `ID`=26165;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싱크의 벌목기가 준비되어 벌목 작업을 시작할 수 있습니다.', `MaleText_loc4`='辛克的伐木机已经就绪，随时摧毁林地。', `MaleText_loc5`='辛克的伐木機已經準備好要摧毀林地了。', `MaleText_loc7`='Trituradora de Xink preparada y disponible para la destrucción del bosque.' WHERE `ID`=26166;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싱크의 벌목기 보안 기능이 활성화되었습니다. 기지로 돌아갑니다.', `MaleText_loc4`='辛克的伐木机的安全功能已经激活。正在返回营地。', `MaleText_loc5`='辛克的伐木機啟動安全機制。返回基地。', `MaleText_loc7`='Programa de seguridad de la trituradora de Xink activado. Regresando a base.' WHERE `ID`=26167;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배가 고프시다면 제게 음식이 있습니다. 쉴 곳이 필요하시다면 제 천막을 쓰시면 되고요.', `MaleText_loc4`='如果你饿了，我这里有食物；如果你需要休息，可以钻进我的帐篷。', `MaleText_loc5`='如果你餓的話，我有食物，你可以使用我的帳篷，你應該會想要休息一下。', `MaleText_loc7`='Si tienes hambre, tengo comida y puedes usar mi tienda si necesitas descansar.', `FemaleText_loc1`='배가 고프시다면 제게 음식이 있습니다. 쉴 곳이 필요하시다면 제 천막을 쓰시면 되고요.', `FemaleText_loc4`='如果你饿了，我这里有食物；如果你需要休息，可以钻进我的帐篷。', `FemaleText_loc5`='如果你餓的話，我有食物，你可以使用我的帳篷，你應該會想要休息一下。', `FemaleText_loc7`='Si tienes hambre, tengo comida y puedes usar mi tienda si necesitas descansar.' WHERE `ID`=26168;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전자기 펄스로 무쇠 영주 퓨리해머의 보호막을 없앱니다!', `MaleText_loc4`='电磁脉冲击碎了铁领主弗雷哈默尔的护盾！', `MaleText_loc5`='電磁脈動干擾了鐵族長怒錘的護盾!', `MaleText_loc7`='¡El PEM perturba el escudo del señor feudal férreo Martillo Furioso!' WHERE `ID`=26169;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 전자기 펄스의 충격에서 회복해 무쇠 영주 퓨리해머의 보호막을 되살립니다.', `MaleText_loc4`='%s从电磁脉冲的攻击中恢复过来，再度开启了铁领主弗雷哈默尔的护盾。', `MaleText_loc5`='%s恢復了電磁脈動並將鐵族長怒錘的護盾復原。', `MaleText_loc7`='%s se recupera del PEM y restaura el escudo del señor feudal férreo Martillo Furioso.' WHERE `ID`=26170;
