UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙다고, 친구! 이제 이 고철 덩어리를 더 빨리 움직이게 해 볼게!', `MaleText_loc4`='谢谢你，伙计！让我瞧瞧要如何让这个笨家伙移动得快一点！', `MaleText_loc5`='謝啦，兄弟!讓我們瞧瞧我是不是沒辦法讓這個大型廢物動得快一點!', `MaleText_loc7`='¡Gracias, colega! ¡A ver si puedo lograr que este pedazo de chatarra se mueva más deprisa!' WHERE `ID`=26172;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 지켜주겠네, 친구!', `MaleText_loc4`='我会保护你的，朋友！', `MaleText_loc5`='我會保護你的，朋友!', `MaleText_loc7`='¡Yo te protegeré, colega!', `FemaleText_loc1`='내가 지켜주지, 친구!', `FemaleText_loc4`='我会保护你的，朋友！', `FemaleText_loc5`='我會保護你的，朋友!', `FemaleText_loc7`='¡Yo te protegeré, colega!' WHERE `ID`=26173;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙소, 친구여. 이제 이 야수들에게 태양샘의 분노를 맛보여 주겠소!', `MaleText_loc4`='谢谢你，朋友。现在该让这群野兽尝尝太阳之井的愤怒了！', `MaleText_loc5`='謝謝你，朋友。現在這些野獸應該感受到太陽之井的憤怒了!', `MaleText_loc7`='Gracias, colega. ¡Ahora estas bestias sentirán la furia de La Fuente del Sol!', `FemaleText_loc1`='고맙습니다, 친구여. 이제 이 야수들은 태양샘의 분노를 맛볼 것입니다!', `FemaleText_loc4`='谢谢你，朋友。现在该让这群野兽尝尝太阳之井的愤怒了！', `FemaleText_loc5`='謝謝你，朋友。現在這些野獸應該感受到太陽之井的憤怒了!', `FemaleText_loc7`='Gracias, colega. ¡Ahora estas bestias sentirán la furia de La Fuente del Sol!' WHERE `ID`=26174;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 무슨 짓이냐? 내게서 떨어져!', `MaleText_loc4`='你以为自己在做什么？离我远点！', `MaleText_loc5`='你以為你在幹什麼?快點滾開!', `MaleText_loc7`='¿Qué crees que estás haciendo? ¡Aléjate de mí!' WHERE `ID`=26175;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지킨다고? 왜? 그건 아무 의미도 없다. 그래, 그래, 그렇지... 사실은 빼앗고 싶지? 이젠 나도 알겠어!', `FemaleText_loc4`='保护？为什么？那绝不是真理所在。不不不……要夺取！我现在终于明白了！', `FemaleText_loc5`='保護生命?為什麼?這沒有道理呀。不不不不...真理在於奪去生命之時!我現在了解了!', `FemaleText_loc7`='¿Preservar? ¿Por qué? No tiene sentido. No, no, no... ¡Sacrificar lo tiene! ¡Ahora lo sé!' WHERE `ID`=26176;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='눈은 별로 내리지 않지만, 이곳의 밤은 대번에 코가 얼어버릴 정도로 춥다네. 침대는 뒤쪽에 있네. 다른 이들을 방해하지만 말게.', `MaleText_loc4`='外面或许没有下雪，不过这里的夜晚能把你的鼻子给冻掉。床铺就在后面——别招惹是非就是了。', `MaleText_loc5`='外頭或許沒有下雪，但這裡的夜晚夠把你的鼻子給凍得掉下來。臥舖就在後頭 - 只要別讓自己惹人嫌就行了。', `MaleText_loc7`='Puede que no esté nevando ahí fuera, pero las noches aquí pueden helarte el alma. Los camastros están en la parte trasera, pero no seas un incordio.' WHERE `ID`=26177;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네한테 나쁜 감정은 없지만, 다른 곳에서 밤을 보내는 게 좋을 것 같네. 그 연약한 피부가 멍들고 싶지 않다면 말일세.', `MaleText_loc4`='嗨。没有谁要故意为难你啦，不过你最好另找地方过夜。瞧你这身细皮嫩肉的，我不忍心让你吃苦。', `MaleText_loc5`='嘿，傻小子，這並不是針對你，但如果你不希望你那光滑的皮膚青一塊紫一塊的話，你最好找個別的地方睡覺。', `MaleText_loc7`='Je. No tengo nada en contra tuyo, pero quizá quieras buscar otro sitio donde dormir esta noche. No me gustaría que esa piel tan delicada acabara llena de moratones.' WHERE `ID`=26178;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도망치자!', `MaleText_loc4`='快跑！', `MaleText_loc5`='逃跑!', `MaleText_loc7`='¡Huye!' WHERE `ID`=26179;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 죽기 싫어!', `MaleText_loc4`='我不想死！', `MaleText_loc5`='我不想死!', `MaleText_loc7`='¡No quiero morir!' WHERE `ID`=26180;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='커다란 친구가 우릴 구해줄 거야!', `MaleText_loc4`='主人会救我们的！', `MaleText_loc5`='大傢伙會救我們!', `MaleText_loc7`='¡El tipo grande nos salvará a todos!' WHERE `ID`=26181;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아!!!', `MaleText_loc4`='啊！！！', `MaleText_loc5`='啊!!', `MaleText_loc7`='¡¡¡Ahh!!!' WHERE `ID`=26182;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사방에 적이야!', `MaleText_loc4`='他们无所不在！', `MaleText_loc5`='他們到處都是!', `MaleText_loc7`='¡Están por todas partes!' WHERE `ID`=26183;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이리 와서 불 좀 쬐세요, $r|1이여;여;. 생선 냄새가 고약하더라도 이해해 주시구려.', `MaleText_loc4`='进来坐在火堆旁休息一下吧，$r。希望你不要介意鱼腥味儿。', `MaleText_loc5`='請進來取暖，休息一下吧，$r。我希望你不會介意魚的味道。', `MaleText_loc7`='Acércate al fuego y descansa, $r. Espero que no te moleste el olor a pescado.', `FemaleText_loc1`='이리 와서 불 좀 쬐세요, $r|1이여;여;. 생선 냄새가 고약하더라도 이해해 주시구려.', `FemaleText_loc4`='进来坐在火堆旁休息一下吧，$r。希望你不要介意鱼腥味儿。', `FemaleText_loc5`='請進來取暖，休息一下吧，$r。我希望你不會介意魚的味道。', `FemaleText_loc7`='Acércate al fuego y descansa, $r. Espero que no te moleste el olor a pescado.' WHERE `ID`=26184;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하이잘 산의 계곡과 봉우리를 넘고, 실리더스의 흐르는 모래를 지나... 우리는 불타는 군단의 무서운 악마와 싸워 왔소. 우리는 이름도 없고 얼굴도 알려지지 않은 얼라이언스의 아들딸이라오. 빛과 얼라이언스의 이름으로, 우리는 최초의 공격을 감행할 것이며, 적들은 최후의 일격 속에 죽어갈 것이오.$B$B우리는 7군단이오.', `MaleText_loc4`='在险峻秀丽的海加尔山，在黄沙滚滚的希利苏斯，我们肩负着与燃烧军团抗衡的重任，血战到底。我们无名无姓，默默无闻，但我们都是联盟的英雄儿女。在圣光的指引下，我们冲锋陷阵，无坚不摧。$B$B我们就是第七军团。', `MaleText_loc5`='翻越了海加爾山的山谷與高峰，越過了希利蘇斯的流沙，對抗燃燒軍團的驚懼大軍 - 我們從不退縮。我們是沒有名字，沒有臉孔的聯盟子民。在聖光與聯盟的力量之下，我們永遠揮出第一擊，而我們的敵人也永遠看到我們的最後一擊。$B$B我們就是第七軍團。', `MaleText_loc7`='Hemos luchado a través de los valles y cimas del Monte Hyjal, a través de las arenas movedizas de Silithus, contra los temibles ejércitos de la Legión. Somos los hijos sin nombre ni rostro de la Alianza. Por la Luz y por el poder de la Alianza, el primer golpe nos pertenece y el último golpe es todo lo que ven nuestros enemigos.$B$BSomos la Séptima Legión.' WHERE `ID`=26185;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지도자가 누군지 궁금하다 이거지... 쥐방울만한 녀석아, 감히 천둥의 인도자 그롬타르가 이끄는 부족과 전쟁을 벌이겠다고? 그렇게 죽고 싶으냐?', `MaleText_loc4`='小家伙，你在寻找他们的首领……你竟然想要挑战雷霆使者戈洛塔尔领导的猛犸人氏族。别急着去送死吧。', `MaleText_loc5`='你在尋找他們的領袖...小東西，你要對抗的可是『雷霆使者』葛羅姆薩爾的氏族。不要這麼急著去送死。', `MaleText_loc7`='Buscas a su líder... mequetrefe, declaras la guerra a los clanes del mismísimo Grom''thar el Portador del Trueno. No estés tan deseoso de correr hacia la muerte.', `FemaleText_loc1`='지도자가 누군지 궁금하다 이거지... 쥐방울만한 녀석아, 감히 천둥의 인도자 그롬타르가 이끄는 부족과 전쟁을 벌이겠다고? 그렇게 죽고 싶으냐?', `FemaleText_loc4`='小家伙，你在寻找他们的首领……你竟然想要挑战雷霆使者戈洛塔尔领导的猛犸人氏族。别急着去送死吧。', `FemaleText_loc5`='你在尋找他們的領袖...小東西，你要對抗的可是『雷霆使者』葛羅姆薩爾的氏族。不要這麼急著去送死。', `FemaleText_loc7`='Buscas a su líder... mequetrefe, declaras la guerra a los clanes del mismísimo Grom''thar el Portador del Trueno. No estés tan deseoso de correr hacia la muerte.' WHERE `ID`=26186;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 그렇게 원한다면야. 청금석 용제단 남쪽으로 가서, 횃불로 이루어진 원 안에 들어가 마그나타우르 대장에게 빼앗은 뿔피리를 불어 보려무나. 명복을 빈다. 그롬타르가 올 게다...', `MaleText_loc4`='哈！好吧。碧蓝巨龙圣地以南有一处火炬环绕之地，在那里吹响猛犸人首领号角。向你信奉的诸神祈祷吧……戈洛塔尔就会出现。', `MaleText_loc5`='哈!就這樣吧。在蒼藍龍殿南方的火圈中吹響猛瑪象人領袖的號角。向你的神祇乞求平靜...葛羅姆薩爾將會出現。', `MaleText_loc7`='¡Ja! ¡Que así sea! Haz sonar el cuerno de un líder magnatauro en el anillo de antorchas al sur del Santuario de Dragones Azul. Haz las paces con tus dioses... Grom''thar vendrá.', `FemaleText_loc1`='하! 그렇게 원한다면야. 청금석 용제단 남쪽으로 가서, 횃불로 이루어진 원 안에 들어가 마그나타우르 대장에게 빼앗은 뿔피리를 불어 보려무나. 명복을 빈다. 그롬타르가 올 게다...', `FemaleText_loc4`='哈！好吧。碧蓝巨龙圣地以南有一处火炬环绕之地，在那里吹响猛犸人首领号角。向你信奉的诸神祈祷吧……戈洛塔尔就会出现。', `FemaleText_loc5`='哈!就這樣吧。在蒼藍龍殿南方的火圈中吹響猛瑪象人領袖的號角。向你的神祇乞求平靜...葛羅姆薩爾將會出現。', `FemaleText_loc7`='¡Ja! ¡Que así sea! Haz sonar el cuerno de un líder magnatauro en el anillo de antorchas al sur del Santuario de Dragones Azul. Haz las paces con tus dioses... Grom''thar vendrá.' WHERE `ID`=26187;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 노예 녀석들이 이번엔 제대로 된 식사를 가져왔군!', `MaleText_loc4`='哈！奴隶们总算带回一顿真正的美餐啦！', `MaleText_loc5`='哈!我的奴隸這次帶回來一份真正的餐點!', `MaleText_loc7`='¡Ja! ¡Esta vez mis esclavos han traído una comida de verdad!' WHERE `ID`=26188;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구해줘서 고맙습니다. 하지만 다른 이들이 아직 저 위쪽에 잡혀 있습니다!', `MaleText_loc4`='谢谢你救了我，我的同胞还被关押在上面几层！', `MaleText_loc5`='感謝你解救了我，不過其他人還在階梯上!', `MaleText_loc7`='Gracias por rescatarme, ¡pero los demás aún están cautivos en los pisos de arriba!' WHERE `ID`=26189;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 고맙네! 놈들이 날 바위 거인들과 싸우도록 강요할까 봐 무척 걱정하고 있었다네.', `MaleText_loc4`='谢天谢地！我正担心他们会不会强迫我去对付石巨人呢！', `MaleText_loc5`='感謝上天!我還擔心他們要把我推上戰場，和那些石巨人作戰!', `MaleText_loc7`='¡Gracias al cielo! ¡Me preocupaba que me fueran a obligar a luchar en su guerra contra los gigantes de piedra!' WHERE `ID`=26190;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이자들은 모두 미쳤어요! 자기들의 주인이라면서 로켄을 섬긴다는 말은 계속 중얼대지만, 정작 직접 명령을 받는 자들은 얼마 되지 않는 것 같아요.', `FemaleText_loc4`='这帮铁矮人疯子！他们反复谈论要为“洛肯大人”效劳，但是据我所知，只有少数人接到他的指令而已。', `FemaleText_loc5`='這些鐵矮人都瘋了!他們不停地再說要服侍他們的主人洛肯，但據我所知，只有極少人真的有收到他的命令。', `FemaleText_loc7`='¡Están locos estos férreos! No hacen más que hablar de servir a su ''maestro Loken'' pero, por lo que yo sé, solo algunos reciben órdenes suyas.' WHERE `ID`=26191;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑습니다! 무엇이 필요하신가요?', `MaleText_loc4`='你好！需要什么吗？', `MaleText_loc5`='你好!需要什麼嗎?', `MaleText_loc7`='¡Saludos! ¿Necesitas algo?' WHERE `ID`=26192;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너도 알지... 이게 다 너 때문이야...', `MaleText_loc4`='这全是你的错……', `MaleText_loc5`='這全是你的錯，你知道嗎...', `MaleText_loc7`='Esto es culpa tuya, ya sabes...' WHERE `ID`=26193;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"진짜야, 브로테. 끝내줄 거라니까... 포세이큰 친구들이 우릴 부자로 만들어줄 거라고!"라더니... 얼마나 어리석고 멍청하고 한심한 생각이었는지 모르겠군.', `MaleText_loc4`='这简直是最最最白痴的主意了……“是啦，布鲁特，这样很好呀……被遗忘者会往我们头上撒金币的！”', `MaleText_loc5`='所有腦袋長毛、白癡、無腦的主意中...「哎呀，老哥，這一定會很棒的啦...被遺忘者會把金幣像下雨一樣地灑在我們身上!」', `MaleText_loc7`='De todas las absurdas, estúpidas y DESCERREBRADAS ideas... "Sí, Brote, será genial... ¡los Renegados nos cubrirán de monedas de oro!"' WHERE `ID`=26194;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제일 열 받는 게 뭔지 알아, 스크로티? 산 채로 뻐꾸기시계가 돼서 저 포세이큰 놈들의 노리개가 된 거? 아니지. 눈 뜨고 있는 동안 내내 얻어맞고 놀림당하는 거? 아니야. 내가 제일 열 받는 건... 이 빌어먹도록 짧은 바지를 입고 있어야 한다는 거야...', `MaleText_loc4`='你知道最让我厌烦的是什么吗，斯克罗提？虽然我们不得不定时报钟，供被遗忘者消遣；虽然我们必须时刻忍受他们的口水和讥笑……但是这些都比不上那些该死的超短裤……穿上这样的玩意儿真是令我抓狂！', `MaleText_loc5`='你知道我火大什麼事，史克羅堤?不，不是那些被遺忘者為了娛樂，就我們被做成活生生的咕咕鐘。也不是我們得在清醒的每分鐘忍受他們的嘲笑與唾罵...讓我最最最火大的就是我得穿這些該死的小短褲...', `MaleText_loc7`='¿Y sabes qué es lo que más me fastidia, Scrote? No es que nos hayan convertido en un reloj de cuco viviente para diversión de los Renegados. Y no es que nos hayan escupido y se hayan burlado de nosotros cada minuto que hemos estado aquí... Lo que más me fastidia es tener que llevar estos malditos pantaloncitos cortos...' WHERE `ID`=26195;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기도해, 스크로티... 종교를 가져봐... 우리가 여기서 나가게 되더라도 넌 분명히 여기로 돌아오고 싶어질 테니까 말이야!', `MaleText_loc4`='祈祷吧，斯克罗提……找回你的信仰……否则就算我们有机会逃走，你也会盼望着回来的！', `MaleText_loc5`='祈禱史克羅堤...找個信仰...因為要是我們如果真能離開這裡，你就會希望你從來沒離開過這個鬼地方!', `MaleText_loc7`='Reza Scrote... Encuentra una religión... ¡Porque si alguna vez salimos de aquí, desearás haber seguido aquí!' WHERE `ID`=26196;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 둘 중 하나는 죽어버렸으면 좋겠어. 죽는 게 너였으면 좋겠어, 스크로티.', `MaleText_loc4`='我希望我们中间死掉一个。我希望那个人是你，斯克罗提。', `MaleText_loc5`='我希望我們其中之一送命，而我希望那個傢伙是你，史克羅堤。', `MaleText_loc7`='Espero que uno de nosotros muera. Y espero que ese seas tú, Scrote.' WHERE `ID`=26197;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 이 말도 안 되는 짓을 해야 되나...', `MaleText_loc4`='别又说废话啊……', `MaleText_loc5`='拜託別又是這個垃圾...', `MaleText_loc7`='Esta basura otra vez no...' WHERE `ID`=26198;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 한 시간이나 지난 거야?', `MaleText_loc4`='真的又过了一个小时吗？', `MaleText_loc5`='真的過了一個小時嗎?', `MaleText_loc7`='¡Saludos! ¿Necesitas algo?' WHERE `ID`=26199;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 나가게 되면 시계라는 시계는 보이는 대로 다 박살 내버릴 거야...', `MaleText_loc4`='如果我能离开这里，我要把看见的每一只钟都砸了……', `MaleText_loc5`='我要是真的能離開這裡，我會把我看見的每個時鐘給徹底砸爛...', `MaleText_loc7`='Si alguna vez escapo de aquí, APLASTARÉ cada reloj con el que entre en contacto...' WHERE `ID`=26200;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 나가게 되면 시계라는 시계는 보이는 대로 다 박살 내버릴 거야...', `MaleText_loc4`='如果我能离开这里，我要把看见的每一只钟都砸了……', `MaleText_loc5`='要是讓我逃出這裡，我會把每個我碰得到的鐘給砸了...', `MaleText_loc7`='Si alguna vez escapo de aquí, APLASTARÉ cada reloj con el que entre en contacto...' WHERE `ID`=26201;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오전 12시를 알립니다. 포세이큰 여러분도 무서워하는 자정입니다! 우우우우...', `MaleText_loc4`='钟声敲响，午夜12点整。可笑的被遗忘者，你们的午夜降临啦！喔喔喔……', `MaleText_loc5`='鐘響凌晨12:00。你們這些嚇人的被遺忘者，午夜了!喔嗚嗚嗚嗚嗚...', `MaleText_loc7`='Cuando suene la campana será medianoche. ¡Bunas noches a todos los temibles Renegados! OOooooooo...' WHERE `ID`=26202;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오전 2시를 알립니다. 절 죽여 이 비참한 인생을 끝내주시려면 지금이 딱 좋은 시간입니다.', `MaleText_loc4`='钟声敲响，凌晨2点整。这正是杀死我的最佳时刻啊，来吧，让我解脱吧！', `MaleText_loc5`='鐘響凌晨2:00。真是巧，一個殺掉我，終結我的不幸的完美時間。', `MaleText_loc7`='Cuando suene la campana serán las dos de la mañana. Curiosamente, un momento ideal para matarme y acabar con mi sufrimiento.' WHERE `ID`=26203;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오전 4시를 알립니다. 도대체 당신네는 잠도 없나요?', `MaleText_loc4`='钟声敲响，凌晨4点整。被遗忘者不用睡觉的吗？', `MaleText_loc5`='鐘響早上4:00。你們都不用睡的嗎?', `MaleText_loc7`='Cuando suene la campana serán las cuatro de la mañana. ¿Es que no dormís nunca?' WHERE `ID`=26204;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오전 6시를 알립니다. *하암* 기상하세요.', `MaleText_loc4`='钟声敲响，凌晨6点整*打哈欠*。起床啦，太阳晒屁股叻。', `MaleText_loc5`='鐘響早上6:00*打呵欠*。起床囉。', `MaleText_loc7`='Cuando suene la campana serán las seis de la mañana *bostezo*. Hora de levantarse.' WHERE `ID`=26205;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오전 8시를 알립니다. 지금쯤 아침 달리기를 마치셨겠군요.', `MaleText_loc4`='钟声敲响，早上8点整。你们都结束晨跑了吧。', `MaleText_loc5`='鐘響早上8:00。我確定你們現在全都剛做完晨跑回來。', `MaleText_loc7`='Cuando suene la campana serán las ocho de la mañana. Estoy seguro de que ya estarán regresando de sus carreras matutinas.' WHERE `ID`=26206;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오전 10시를 알립니다. 오늘 날씨는 지독한 독구름이 가득할 것으로 예상됩니다.', `MaleText_loc4`='钟声敲响，上午10点整。今天的天气预报称，空中可能出现更多绿色的致命毒云团。', `MaleText_loc5`='鐘響早上10:00。今天的氣象預報看起來好像會有更多的綠色死亡毒雲。', `MaleText_loc7`='Cuando suene la campana serán las diez de la mañana. El parte meteorológico advierte de que hoy tendremos nubes venenosas mortales verdes.' WHERE `ID`=26207;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오후 12시를 알립니다. 계산할 줄 모르는 분들은 정오라고도 하죠. 그래요, 당신들 말입니다, 오크 여러분.', `MaleText_loc4`='钟声敲响，正午12点整。瞧你们这帮连数都不会数的家伙，现在是正午时分。说的就是你们，兽人。', `MaleText_loc5`='鐘響早上12:00。那些不會算數的人，中午囉。沒錯，我就是在看著你們，獸人。', `MaleText_loc7`='Cuando suene la campana serán las 12. Mediodía para los que no saben contar. Eso es. Los estoy mirando a ustedes, orcos.' WHERE `ID`=26208;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오후 2시를 알립니다. 이 시간에는 미들턴이 한 개 가격으로 두 개를 드리니 기회를 잡으세요! 세계 최고의 독극물 전문가가 만든 맹독성 생물학 작용제 한 통을 사면 하나를 덤으로 준다 이 말이죠!', `MaleText_loc4`='钟声敲响，下午2点整。请允许我借此机会做做宣传：米德尔顿正在举办买一赠一活动！购买一罐闻名于世的有毒生物制剂就能再免费获赠一罐！', `MaleText_loc5`='鐘響下午2:00。我想要藉此通知你們大家米道頓現在正在舉行買2送1的拍賣活動喔!買1罐他的世界知名有毒生物工程製劑，第二件就免錢喔!', `MaleText_loc7`='Cuando suene la campana serán las dos de la tarde. ¡Quiero aprovechar esta oportunidad para informaros de que Middleton tiene una oferta de 2x1 en este momento! ¡Compra 1 bote de sus famosos agentes biológicos y llévate el segundo gratis!' WHERE `ID`=26209;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오후 4시를 알립니다. 미들턴의 연금술 실험실 가격 할인 시간이로군요! 단돈 35실버만 내시면 독극물에 절거나 가스에 잔뜩 취하게 해 드립니다. 물론 둘 다 해도 됩니다!', `MaleText_loc4`='钟声敲响，下午4点整。现在是米德尔顿炼金房的“欢乐时光”！只需35银币，就能享受到吞食毒药或是吞服毒气的乐趣哦，两种一起来也可以哟！', `MaleText_loc5`='鐘響下午4:00。到了米道頓鍊金房的歡樂時間囉!進來享用中毒或是毒氣或兩種一起只要35銀喔!', `MaleText_loc7`='Cuando suene la campana serán las cuatro de la tarde. ¡Esa es la HORA FELIZ en el Apothecarium de Middleton! ¡Ven a envenenarte, gasearte o las dos cosas por solo 35 monedas de plata!' WHERE `ID`=26210;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오후 6시를 알립니다. 제발 내 동생 좀 없애 주세요!', `MaleText_loc4`='钟声敲响，下午6点整。杀死我的兄弟吧！', `MaleText_loc5`='鐘響下午6:00。請殺了我的兄弟!', `MaleText_loc7`='Cuando suene la campana serán las seis de la tarde. ¡Por favor, matad a mi hermano!' WHERE `ID`=26211;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으아악! 나한테 무슨 일이 일어난 거냐?', `MaleText_loc4`='啊！！发生了什么事？', `MaleText_loc5`='啊啊啊!我身上發生了什麼事，老兄?', `MaleText_loc7`='¡Ahhh! ¿Qué me está pasando, colega?' WHERE `ID`=26212;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 차례야?', `MaleText_loc4`='轮到我了吗？', `MaleText_loc5`='輪到我了嗎?', `MaleText_loc7`='¿Es mi turno?' WHERE `ID`=26213;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='점심때인가?', `MaleText_loc4`='吃午饭的时候到了吗？', `MaleText_loc5`='午餐時間到了嗎?', `MaleText_loc7`='¿Es hora de comer?' WHERE `ID`=26214;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번엔 뛰어내릴 거야, 브로테. 정말이라고!', `MaleText_loc4`='这次我一定会跳的，布鲁特。我发誓！', `MaleText_loc5`='這次我真的會跳了，布羅特。我發誓!', `MaleText_loc7`='Esta vez voy a saltar, Brote. ¡Lo juro!' WHERE `ID`=26215;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오전 1시를 알립니다. 만약 내가 풀려난다면 기필코 이 동네를 엎어버릴 거예요!!!', `MaleText_loc4`='钟声敲响，凌晨1点整。如果我能逃出去的话，我会将这个镇子撕成碎片！！！', `MaleText_loc5`='鐘響早上1:00。要是我自由了，我會毀了這個鎮!!!', `MaleText_loc7`='Cuando suene la campana será la una de la mañana. ¡¡¡Si consigo liberarme, destrozaré esta ciudad!!!' WHERE `ID`=26216;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오전 3시를 알립니다. 잘 시간이라고요!', `MaleText_loc4`='钟声敲响，凌晨3点整。该睡觉了！', `MaleText_loc5`='鐘響早上3:00。該睡覺囉!', `MaleText_loc7`='Cuando suene la campana serán las tres de la mañana. ¡Hora de acostarse!' WHERE `ID`=26217;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오전 5시를 알립니다. 그냥 날 죽여요!', `MaleText_loc4`='钟声敲响，凌晨5点整。杀了我吧！', `MaleText_loc5`='鐘響早上5:00。殺了我吧!', `MaleText_loc7`='Cuando suene la campana serán las cinco de la mañana. ¡Acabad conmigo!' WHERE `ID`=26218;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오전 7시를 알립니다. 좋은 꿈들 꾸셨나요?', `MaleText_loc4`='钟声敲响，早上7点整。早上好，你们都起得很早啊！', `MaleText_loc5`='鐘響早上7:00。早起的鳥兒們，早安啊!', `MaleText_loc7`='Cuando suene la campana serán las siete de la mañana. ¡Buenos días, madrugadores!' WHERE `ID`=26219;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오전 9시를 알립니다. 용의 안식처에 또다시 희망찬 하루가 밝았군요!', `MaleText_loc4`='钟声敲响，上午9点整。龙骨荒野似乎又迎来了美好的一天！', `MaleText_loc5`='鐘響早上9:00。又是龍骨荒野美好的一天!', `MaleText_loc7`='Cuando suene la campana serán las nueve de la mañana. ¡Es otro precioso día en el Cementerio de Dragones!' WHERE `ID`=26220;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오전 11시를 알립니다. 이 기회를 빌려 원한의 초소에 오신 흉악하고 뒤틀린 호드 여러분께 환영 인사를 전해야겠군요. 저와 제 형제 브로테는 여러분을 진심으로 환영하는 바입니다!', `MaleText_loc4`='钟声敲响，上午11点整。让我借此机会欢迎你们这些心理扭曲的部落成员吧，欢迎你们来到怨毒镇！我代表我和我兄弟布鲁特向你们致意。', `MaleText_loc5`='鐘響早上11:00。我想要藉此歡迎所有初到毒怨之地的殘忍，古怪部落!代表我及我的兄弟，布羅特，非常歡迎。', `MaleText_loc7`='Cuando suene la campana serán las once de la mañana. ¡Quiero aprovechar esta oportunidad para dar la bienvenida a Rencor Venenoso a los recién llegados asesinos retorcidos de la Horda! Así que, bienvenidos de mi parte y de la de mi hermano Brote.' WHERE `ID`=26221;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오후 1시를 알립니다. 한창 점심 먹느라 분주하시죠! 독극물, 역병, 독가스를 1분 내로 배달해 드립니다. 1분을 넘기면 무료!', `MaleText_loc4`='钟声敲响，下午1点整。现在是午餐高峰时间！你们预订的货物将在60秒后送到；如果未能准时送达，就免去订单费！', `MaleText_loc5`='鐘響下午1:00。我們正在匆忙吃午餐中!你們的毒藥，瘟疫，以及有毒氣體會於60秒內送達，否則免費!', `MaleText_loc7`='Cuando suene la campana será la una de la tarde. ¡En pleno ajetreo de la hora de la comida! ¡Si no te entregamos tus venenos, pestes y gases nocivos en 60 segundos, tu pedido será gratuito!' WHERE `ID`=26222;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오후 3시를 알립니다. 바지에 좀 지린 것 같군요.', `MaleText_loc4`='钟声敲响，下午3点整。我好像尿裤子了。', `MaleText_loc5`='鐘響下午3:00。我想我弄髒自己了。', `MaleText_loc7`='Cuando suene la campana serán las tres de la tarde. Creo que me he manchado.' WHERE `ID`=26223;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오후 5시를 알립니다. 아까 방송 들으셨던 분들께 말씀드리는 건데, 저, 실제로 좀 지렸습니다.', `MaleText_loc4`='钟声敲响，下午5点整。我知道你们还惦记着刚才的事儿呢，好吧，我确实——尿裤子了。', `MaleText_loc5`='鐘響下午5:00。給那些可能持續得分的人，事實上，我真的弄髒我自己了。', `MaleText_loc7`='Cuando suene la campana serán las cinco de la tarde. Para los que hayáis estado siguiéndome: ¡sí, me he manchado!' WHERE `ID`=26224;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오후 7시를 알립니다. 원한의 초소에서 보내는 보람찬 하루가 또다시 저물어 가는군요.', `MaleText_loc4`='钟声敲响，晚上7点整。夜幕降临，怨毒镇充实的一天结束了。', `MaleText_loc5`='鐘響下午7:00。隨著夜晚的來臨，另一個屬於毒怨之地充滿活力的一天又結束了。', `MaleText_loc7`='Cuando suene la campana serán las siete de la tarde. Otra productiva jornada llega a su fin en Rencor Venenoso mientras la noche se cierne sobre nosotros.' WHERE `ID`=26225;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오후 9시를 알립니다. 나도 좀 쉽시다! 4시간 뒤에 보자고요. 내가 자는 동안 누가 날 죽이지만 않는다면 말이에요.', `MaleText_loc4`='钟声敲响，晚上9点整。我该休息啦！4小时之后我还会来报钟的，除非你们趁我睡觉时杀了我（请一定要这么做）。', `MaleText_loc5`='鐘響下午9:00。我要休息了啦!我們4點時再見。除非你們當中有人趁我睡夢中殺了我(拜託了)。', `MaleText_loc7`='Cuando suene la campana serán las nueve de la noche. ¡Mi hora del descanso! Volveré a verlos dentro de cuatro horas. A menos que uno de ustedes me mate mientras duermo (por favor).' WHERE `ID`=26226;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저 멍청한 트롤이 끝내 나를 실망시켰군. 안디스! 놈의 다리를 분질러 버려라!', `FemaleText_loc4`='那个没用的巨魔再度失败了。我的容忍已经到了极限！安希斯！给我打断他的腿！', `FemaleText_loc5`='這是那個懦弱的食人妖的最後一次失敗了。安希司!斷了他的腿!', `FemaleText_loc7`='Ese estúpido trol me ha fallado por última vez. ¡Anthis! ¡Rómpele las piernas!' WHERE `ID`=26227;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='즉시 시행하겠습니다!', `MaleText_loc4`='我立即去办！', `MaleText_loc5`='馬上做，我的女士!', `MaleText_loc7`='¡Ahora mismo, mi señora!' WHERE `ID`=26228;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네가 다른 사람을 공격하는 일에 이렇게 나서는 건 처음 보는군. 아주 맘에 들어... 좋아, 가라!', `FemaleText_loc4`='我还没见过你如此迫切地想要给他人留下痛苦的回忆呢。这是进步呢……很好，去吧！', `FemaleText_loc5`='我從來沒看過你如此渴望傷害別人，姐妹。真是令人愉快的成長...非常好，上吧!', `FemaleText_loc7`='Nunca te había visto tan deseosa de hacer daño a alguien, hermana. Qué evolución tan satisfactoria… Adelante, ve.' WHERE `ID`=26229;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='군주시여! 저를 대신 보내 주십시오.', `FemaleText_loc4`='殿下！请改派我去吧。', `FemaleText_loc5`='我的王啊!請准許讓我代替你動手。', `FemaleText_loc7`='¡Mi señor! Permítame ir en su lugar.' WHERE `ID`=26230;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이... 멍청한 놈... 무슨 생각을 한 게냐? 잡아뗄 수 있을 줄 알았더냐? 그분께서 모르실 줄 알았느냔 말이다!', `FemaleText_loc4`='你……自作聪明的家伙……你想什么呢？打算夺取属于她的功劳吗？你以为她会被你蒙在鼓里？', `FemaleText_loc5`='你...腦殘...你會什麼?從她身上脫下某種類似的東西嗎?你以為她不會注意到嗎?', `FemaleText_loc7`='Tú... medio idiota... ¿En qué estabas pensando? ¡Hacerle algo así a ella! ¿Creíste que no se daría cuenta?' WHERE `ID`=26231;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='늦었구나, 감독관이여.', `MaleText_loc4`='监工，进展太缓慢了。', `MaleText_loc5`='你遲到了，監督者。', `MaleText_loc7`='Llegas tarde, sobrestante.' WHERE `ID`=26232;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='운명은 기다려주지 않는다. 바위 거인 지도자와 그의 군대가 울두아르에 도착하기 전에 전쟁 골렘을 더 많이 생산해야 한다.', `MaleText_loc4`='命运不会为谁停留。在石巨人大军抵达奥杜尔之前，你必须监督工匠提高作战魔像的产量。', `MaleText_loc5`='命運可不等人。你的工匠一定得趕在石巨人領袖和他的大軍抵達奧杜亞之前，提高戰爭魔像的產量。', `MaleText_loc7`='El destino no esperará. Tus artesanos han de incrementar la producción de gólems de piedra antes de que el anfitrión gigante de piedra llegue a Ulduar.' WHERE `ID`=26233;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='룬대장장이들에게 계속해서 바위 거인들을 변환하라고 일러라. 굴복하지 않는 놈들은 모두 제거해 버려라.', `MaleText_loc4`='告诉你手下的符文铁匠，必须加紧改造石巨人。摧毁那些不服从指令的家伙。', `MaleText_loc5`='告訴你的符文鐵匠，繼續轉化那些可轉化的石巨人。而不服從者一定得摧毀。', `MaleText_loc7`='Di a tus forjadores de runas que continúen transformando a tantos gigantes de piedra como puedan. Los que no se dobleguen deberán ser destruidos.' WHERE `ID`=26234;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='울두아르에서 벌이는 우리 일을 바위 거인들이 방해하면, 너와 네 영주에게 책임을 묻겠다. 필멸의 존재들이 거인을 도우러 오게 놔둬서는 안 된다.', `MaleText_loc4`='如果石巨人胆敢阻挠我们在奥杜尔的工事，我就撤消你和你的领主的权利。绝不允许凡人帮助巨人。', `MaleText_loc5`='要是石巨人干預我們在奧杜亞的工作，我會唯你和你的族長是問。凡人絕對不允許幫助巨人。', `MaleText_loc7`='Si los gigantes de piedra interfieren con nuestro trabajo en Ulduar, os haré responsables a ti y a tu señor feudal. No se debe permitir a los mortales que ayuden a los gigantes.' WHERE `ID`=26235;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌아가서 일을 계속하라, 감독관. 일꾼들을 재촉하는 일을 잊지 말아라.', `MaleText_loc4`='回到你的岗位上去吧，监工。必须让工匠们明白任务的急迫性。', `MaleText_loc5`='回到你的崗位上，監督者。確認你的工人們對於他們的任務緊要性有深刻的認知。', `MaleText_loc7`='Vuelve a tu trabajo, sobrestante. Asegúrate de transmitir a tus trabajadores la urgencia de sus tareas.' WHERE `ID`=26236;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주.정.뱅.이.는 그냥 맥주잔 던지는 표적이 아니에요. 정말 귀중한 훈련 도구이지요. 주.정.뱅.이.를 맞힐 수 있다면 세상에 못 맞힐 게 뭐가 있겠어요!$B$B그렇지만 저한테 시험해 볼 생각은 마세요.', `MaleText_loc4`='我设计的掷杯训练器不只是用来训练扔酒杯的，它还是非常有价值的训练设施。如果你能击中它，就可以击中任何东西！$B$B不要击中我就行了。', `MaleText_loc5`='我的S.T.O.U.T.不只是丟擲啤酒杯的目標，它還是個貴重的訓練資產。如果你能擊中S.T.O.U.T.，你就能擊中所有的東西!$b$b只要別擊到我就好。', `MaleText_loc7`='Mi G.U.A.O. es más que un objetivo al que lanzarle jarras, es un recurso muy valioso para los entrenamientos. ¡Si puedes acertar al G.U.A.O., podrás acertar a cualquier cosa!$B$BPero procura no golpearme a mí.' WHERE `ID`=26237;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='종 울리기', `MaleText_loc4`='鸣响', `MaleText_loc5`='敲鐘', `MaleText_loc7`='Sonando', `FemaleText_loc1`='종 울리기', `FemaleText_loc4`='鸣响', `FemaleText_loc5`='敲鐘', `FemaleText_loc7`='Sonando' WHERE `ID`=26238;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='효과가 있는지 봅시다.', `MaleText_loc4`='让我们瞧瞧这管不管用。', `MaleText_loc5`='讓我們瞧瞧這東西有沒有用。', `MaleText_loc7`='Veamos si esto funciona.' WHERE `ID`=26239;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여... 여기는 어디요?', `MaleText_loc4`='我……我这是在哪儿？', `MaleText_loc5`='我...我在哪?', `MaleText_loc7`='¿Dónde... dónde estoy?' WHERE `ID`=26240;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서둘러라, 일꾼들아! 건물을 복구해야 할 게 아니냐!', `MaleText_loc4`='别一副懒散模样！我们必须将这些建筑物修好！', `MaleText_loc5`='快點，鄉巴佬!我們得要使用這些建築作為支援!', `MaleText_loc7`='¡Date vida, campesino! ¡Tenemos que volver a levantar estas estructuras!' WHERE `ID`=26241;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아서스 왕자께서 돌아오시기 전에 일을 끝내는 게 좋을 거다!', `MaleText_loc4`='最好在阿尔萨斯王子回来之前完工！', `MaleText_loc5`='東西最好會在阿薩斯王子回來時完成!', `MaleText_loc7`='¡Será mejor que eso esté terminado cuando regrese el príncipe Arthas!' WHERE `ID`=26242;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='망치질을 그것밖에 못 하는 거냐, 이 녀석들아! 어서 움직여!', `MaleText_loc4`='伙计们，埋头工作呀！快一点！', `MaleText_loc5`='你以後會擁有比那還要更堅固的錘子，夥伴!快點!', `MaleText_loc7`='¡Vas a tener que usar el martillo con más fuerza, colega! ¡Muévete!' WHERE `ID`=26243;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='집에 가고 싶지 않은 거냐, 농부 녀석아? 이게 저절로 고쳐지는 줄 아느냔 말이다!', `MaleText_loc4`='你是想滚回家吗？你以为这些建筑物能自动复原是不是！', `MaleText_loc5`='你不想回家嗎，鄉巴佬?這些東西可不會自己重新搭建起來!', `MaleText_loc7`='¿No quieres ir a casa, campesino? ¡Estas cosas no van a reconstruirse solas!' WHERE `ID`=26244;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전체 차렷!', `MaleText_loc4`='注意！', `MaleText_loc5`='注意!', `MaleText_loc7`='¡Atención!' WHERE `ID`=26245;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='편히 쉬게, 제군. 곧 아서스 왕자께서 돌아오실 테니, 우린 로데론으로 돌아갈 거다.', `MaleText_loc4`='别紧张。王子很快就要回来啦，到时候我们就能返回洛丹伦了。', `MaleText_loc5`='放輕鬆點，小夥子。王子很快就會回來了，我們就可以回到羅德隆。', `MaleText_loc7`='Tranquilo, chico. El Príncipe volverá pronto e iremos de vuelta a Lordaeron.' WHERE `ID`=26246;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 잘하고 있다, 제군. 아서스 왕자께서 자랑스러워 하실 거다! 계속 열심히 하도록!', `MaleText_loc4`='你做得很好，士兵。阿尔萨斯王子会为你感到骄傲的！继续努力！', `MaleText_loc5`='你做得很好，士兵。阿薩斯王子會覺得很驕傲!持續下去!', `MaleText_loc7`='Estás haciendo un buen trabajo, soldado. ¡El príncipe Arthas estaría orgulloso! ¡Sigue así!' WHERE `ID`=26247;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모든 일이 끝나면 네가 얼라이언스 명예 훈장을 받을 수 있게 추천해 주지.', `MaleText_loc4`='当这一切都结束后，我会建议上头为你颁发一枚联盟荣誉奖章的。', `MaleText_loc5`='當這全部結束後，我會幫你提名聯盟榮譽獎章。', `MaleText_loc7`='Cuando todo esto haya terminado, te recomendaré para que obtengas una Marca de Honor de la Alianza.' WHERE `ID`=26248;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수상한 움직임이 없는지 잘 감시해라, 제군. 어디서 속닥거리는 소리를 들은 것 같으니까.', `MaleText_loc4`='随时任何可疑的动静。我发现有些捣乱分子在蠢蠢欲动了。', `MaleText_loc5`='盯緊任何可疑的行動，士兵。我已經鎖定幾個搗蛋者考慮中。', `MaleText_loc7`='Mantén los ojos bien abiertos en busca de actividad sospechosa, soldado. He descubierto a algunos alborotadores merodeando.' WHERE `ID`=26249;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조금만 더 애써라, 제군. 이 끔찍한 전쟁도 머지않아 끝날 것이다.', `MaleText_loc4`='保持警惕，士兵。这场可怕的战争很快就要结束了。', `MaleText_loc5`='保持警惕，士兵。這場恐怖的戰爭很快就會結束了。', `MaleText_loc7`='Mantente alerta, soldado. Esta terrible Guerra pronto terminará.' WHERE `ID`=26250;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기는 타운카의 원크와 야영지다, 드워프여.', `MaleText_loc4`='矮人，欢迎拜访欧尼瓦营地的牦牛人。', `MaleText_loc5`='你現在身處於坦卡族的歐尼克瓦營地中，矮人。', `MaleText_loc7`='Te encuentras entre los taunka del Campamento Oneqwah, $genano:enana;.' WHERE `ID`=26251;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 공통의 적과 싸우는 것을 도와준다면, 너는 다치지 않을 것이다.', `MaleText_loc4`='如果你愿意帮助我们抵御共同的敌人，我们保证不伤害你。', `MaleText_loc5`='如果你願意幫助我們對抗我們共同的敵人，那麼你在這裡將不會受到任何傷害。', `MaleText_loc7`='Si accedes a ayudarnos a luchar contra nuestro enemigo común, no sufrirás daño alguno aquí.' WHERE `ID`=26252;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생각해 봐라, 발굴조사단장. 하지만 우리도 속히 행동을 취해야 하니 결정을 빨리 내려야 한다.', `MaleText_loc4`='考虑一下吧，勘查员，希望你能尽快做出决定。我们必须立即采取行动。', `MaleText_loc5`='考慮看看吧，勘察員，但是要快點下決定。我們必須即早行動。', `MaleText_loc7`='Piénsalo, prospector, pero toma una decisión deprisa. Debemos actuar pronto.' WHERE `ID`=26253;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자들이 속닥거리는 소리를 들었습니다. 조심하십시오.', `MaleText_loc4`='我听到入侵者在窃窃私语。当心。', `MaleText_loc5`='我聽見入侵者的絮語。當心點。', `MaleText_loc7`='He oído susurros de intrusos. Ten cuidado.', `FemaleText_loc1`='침입자들이 속닥거리는 소리를 들었어요. 조심하세요.', `FemaleText_loc4`='我听到入侵者在窃窃私语。当心。', `FemaleText_loc5`='我聽見入侵者的絮語。當心點。', `FemaleText_loc7`='He oído susurros de intrusos. Ten cuidado.' WHERE `ID`=26254;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보병, 당신에게서 오염된 이 땅의 기운이 느껴집니다. 다음 교대 시간이 오기 전에 주교님께 보고하십시오.', `MaleText_loc4`='步兵，我能闻到你身上的土臭味儿。换班之前，向主教报到吧。', `MaleText_loc5`='我在你身上感覺到這個地方的腐壞，步卒。先去回報給主教，再進行你的下一項工作吧。', `MaleText_loc7`='Siento la corrupción de esta tierra en ti, lacayo. Preséntate ante el Obispo antes de que comience tu siguiente turno.', `FemaleText_loc1`='보병, 당신에게서 오염된 이 땅의 기운이 느껴지네요. 음 교대 시간이 오기 전에 주교님께 보고하세요.', `FemaleText_loc4`='步兵，我能闻到你身上的土臭味儿。换班之前，向主教报到吧。', `FemaleText_loc5`='我在你身上感覺到這個地方的腐壞，步卒。先去回報給主教，再進行你的下一項工作吧。', `FemaleText_loc7`='Siento la corrupción de esta tierra en ti, lacayo. Preséntate ante el Obispo antes de que comience tu siguiente turno.' WHERE `ID`=26256;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='냄새가 지독합니다. 좀 씻으십시오.', `MaleText_loc4`='你真臭。去洗个澡吧。', `MaleText_loc5`='你好臭。去沖個澡吧。', `MaleText_loc7`='Apestas. Dúchate.', `FemaleText_loc1`='냄새가 지독합니다. 좀 씻으세요.', `FemaleText_loc4`='你真臭。去洗个澡吧。', `FemaleText_loc5`='你好臭。去沖個澡吧。', `FemaleText_loc7`='Apestas. Dúchate.' WHERE `ID`=26257;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고위집행관 워로스께서 확인 후 보상 지급 예정.$B$B신중하게 생각한 후 문의할 것.$B$B쓸데없는 방문 사절!', `MaleText_loc4`='高级执行官乌洛斯负责发送悬赏令的奖励。$B$B有诚意者请入内咨询。$B$B谢绝中介！', `MaleText_loc5`='所有的報酬均由高階執行官羅思支付與核銷。$B$B認真人士內洽。$B$B謝絕推銷!', `MaleText_loc7`='Todas las recompensas serán pagadas por el sumo ejecutor Wroth después de realizar las comprobaciones pertinentes.$B$BLas personas interesadas pueden obtener más información dentro.$B$B¡ABSTENERSE ABOGADOS!' WHERE `ID`=26258;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛의 의지를 따르고자 합니다.', `MaleText_loc4`='我将谦卑地服从圣光的意志。', `MaleText_loc5`='我謙卑地將自己奉獻給光明之願。', `MaleText_loc7`='Me ofrezco humildemente a la valuntad de la Luz.', `FemaleText_loc1`='빛의 의지를 따르고자 합니다.', `FemaleText_loc4`='我将谦卑地服从圣光的意志。', `FemaleText_loc5`='我謙卑地將自己奉獻給光明之願。', `FemaleText_loc7`='Me ofrezco humildemente a la valuntad de la Luz.' WHERE `ID`=26259;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살아있는 것들은 모두 파괴할 걸세... 물론, 스컬지들 말이야.', `MaleText_loc4`='摧毁那些行尸走肉……我当然是指天灾军团。', `MaleText_loc5`='我們要向活人復仇...呃，我是說天譴軍，一定的嘛。', `MaleText_loc7`='Acabaremos con los vivos... quiero decir con la Plaga, por supuesto.' WHERE `ID`=26260;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='림피 조, 당신이군. 정말 당신이야!', `MaleText_loc4`='乔伊，是你。真的是你！', `MaleText_loc5`='『瘸子』喬，是你耶。真的是你!', `MaleText_loc7`='Joe el Cojo, ¿eres tú? ¡Eres tú!' WHERE `ID`=26261;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정하십시오. 무쇠 드워프와 로켄에 대해 물어보고 싶은 게 있습니다.', `MaleText_loc4`='冷静。我是想问你关于铁矮人和洛肯的情况。', `MaleText_loc5`='冷靜點。我想問你關於鐵矮人和洛肯的事情。', `MaleText_loc7`='Tranquilízate. Quiero preguntarte acerca de los enanos férreos y Loken.', `FemaleText_loc1`='진정하십시오. 무쇠 드워프와 로켄에 대해 물어보고 싶은 게 있습니다.', `FemaleText_loc4`='冷静。我是想问你关于铁矮人和洛肯的情况。', `FemaleText_loc5`='冷靜點。我想問你關於鐵矮人和洛肯的事情。', `FemaleText_loc7`='Tranquilízate. Quiero preguntarte acerca de los enanos férreos y Loken.' WHERE `ID`=26262;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='작은 자여, 무슨 일로 여기까지 왔나?', `MaleText_loc4`='你来这里干什么，小家伙？', `MaleText_loc5`='什麼風把你吹到這兒來，小傢伙?', `MaleText_loc7`='¿Qué te trae por aquí, $gpequeño:pequeña;?' WHERE `ID`=26263;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로켄과 무쇠 드워프에 대해 알려 주시겠습니까?', `MaleText_loc4`='关于铁矮人和洛肯，你都知道些什么？', `MaleText_loc5`='關於鐵矮人和洛肯的事情你能告訴我些什麼?', `MaleText_loc7`='¿Qué puedes contarme sobre Loken y los enanos férreos?', `FemaleText_loc1`='로켄과 무쇠 드워프에 대해 알려 주시겠어요?', `FemaleText_loc4`='关于铁矮人和洛肯，你都知道些什么？', `FemaleText_loc5`='關於鐵矮人和洛肯的事情你能告訴我些什麼?', `FemaleText_loc7`='¿Qué puedes contarme sobre Loken y los enanos férreos?' WHERE `ID`=26264;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='림피 조가 할 것 같은 질문은 아닌데! 하지만 내가 로켄에 대해 아는 건 확실하지.', `MaleText_loc4`='乔伊怎么会问这样的问题！好吧，我确实知道洛肯的事。', `MaleText_loc5`='這些可不是『瘸子』喬會問的事情!但沒錯，我知道洛肯。', `MaleText_loc7`='¡Joe el Cojo nunca preguntaría algo así! Pero sí, conozco a Loken.' WHERE `ID`=26265;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='녀석도 날 잡으러 온 거요! 나 같으면 좀 더 조심하겠소, 여행자 양반. 녀석이 어느 나무 뒤에 숨어 있을지 모르니까 말이오!', `MaleText_loc4`='他也在找我的麻烦呢！如果我是你的话，我在这一带走动时会额外小心的。你永远都不知道他会躲在哪棵树后面！', `MaleText_loc5`='他也出來抓我了!如果我是你，我在這裡會很小心，旅行者。你永遠都不知道他就躲在哪一顆樹的後面!', `MaleText_loc7`='¡También viene a por mí! Si fuera tú, tendría cuidado por aquí, forastero. ¡Nunca sabes detrás de qué árbol puede estar escondido!' WHERE `ID`=26266;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 그래. 로켄이라면 잘 안다.', `MaleText_loc4`='啊，是的。我对洛肯非常了解。', `MaleText_loc5`='嗯，沒錯。我很清楚洛肯是誰。', `MaleText_loc7`='Ah, sí. Conozco bien a Loken.' WHERE `ID`=26267;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리에 대항해 싸우는 전쟁에서 무쇠의 후예를 지휘하는 존재가 바로 그놈이다.', `MaleText_loc4`='他指挥钢铁的子嗣，对我们发动了战争。', `MaleText_loc5`='就是他在戰爭中指揮鐵之子來對抗我們。', `MaleText_loc7`='Él es quien dirige a los hijos del hierro en su guerra contra nosotros.' WHERE `ID`=26268;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그놈은 바위 거인을 파멸시키려는 목적으로 은신처에 숨어서 전쟁을 준비하고 있다!', `MaleText_loc4`='他藏身在不为人知的角落，监督着战争的准备工作，想要消灭石巨人！', `MaleText_loc5`='他從他的藏身處監控著他們的戰爭準備，一場要滅絕我們石巨人的戰爭!', `MaleText_loc7`='¡Desde su escondite, supervisa sus preparativos de guerra con la meta de exterminar a los gigantes de piedra!' WHERE `ID`=26269;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겸허히 빛을 섬기고자 합니다.', `MaleText_loc4`='我将谦卑地服从圣光。', `MaleText_loc5`='我謙卑地將自己獻給聖光。', `MaleText_loc7`='Me ofrezco humildemente a la Luz.', `FemaleText_loc1`='겸허히 빛을 섬기고자 합니다.', `FemaleText_loc4`='我将谦卑地服从圣光。', `FemaleText_loc5`='我謙卑地將自己獻給聖光。', `FemaleText_loc7`='Me ofrezco humildemente a la Luz.' WHERE `ID`=26270;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 오셨습니다, 어린 양이여. 그대를 둘러싼 빛의 가호가 약해져 있군요.', `MaleText_loc4`='你能来真是太好啦，我的孩子。圣光对你的眷顾正在消退。', `MaleText_loc5`='你能來找我真是太好了，孩子。聖光在你身上的保護越來越薄弱。', `MaleText_loc7`='Es bueno que hayas venido, hijo. La protección de la Luz se ha debilitado en ti.' WHERE `ID`=26271;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다 됐습니다. 계속해서 빛을 섬기십시오.', `MaleText_loc4`='好了。好好为圣光效劳。', `MaleText_loc5`='完成了。好好為聖光服務。', `MaleText_loc7`='Está hecho. Sirve bien a la Luz.' WHERE `ID`=26272;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이봐, 슐레미엘!', `FemaleText_loc4`='笨手笨脚的蠢货！', `FemaleText_loc5`='笨蛋!', `FemaleText_loc7`='¡Schlemiel!' WHERE `ID`=26273;
