UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇긴 하죠. 하지만 강도를 얼마나 높여야 하죠? 어느 시점이 되면 우리가 적과 다름없는 사악한 짓을 하는 게 될지 모르겠어요.', `MaleText_loc4`='没错，可我们能坚持多久呢？这样做，又比我们的敌人好到哪儿去呢？', `MaleText_loc5`='沒錯，但我們應該做到什麼地步?我們何時會變的和我們的敵人毫無區別?', `MaleText_loc7`='Cierto, pero ¿hasta dónde deberíamos presionar? ¿En qué punto dejamos de ser mejores que nuestros enemigos?', `FemaleText_loc1`='그렇긴 하죠. 하지만 강도를 얼마나 높여야 하죠? 어느 시점이 되면 우리가 적과 다름없는 사악한 짓을 하는 게 될지 모르겠어요.', `FemaleText_loc4`='没错，可我们能坚持多久呢？这样做，又比我们的敌人好到哪儿去呢？', `FemaleText_loc5`='沒錯，但我們應該做到什麼地步?我們何時會變的和我們的敵人毫無區別?', `FemaleText_loc7`='Cierto, pero ¿hasta dónde deberíamos presionar? ¿En qué punto dejamos de ser mejores que nuestros enemigos?' WHERE `ID`=26319;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래요. 적도 우리에게 자비를 보이지 않을 테니...', `MaleText_loc4`='敌人是不会对我们手软的。', `MaleText_loc5`='沒錯，我們的敵人並不會手下留情。', `MaleText_loc7`='Cierto, nuestros enemigos no mostrarían piedad.', `FemaleText_loc1`='그래요. 적도 우리에게 자비를 보이지 않을 테니...', `FemaleText_loc4`='敌人是不会对我们手软的。', `FemaleText_loc5`='沒錯，我們的敵人並不會手下留情。', `FemaleText_loc7`='Cierto, nuestros enemigos no mostrarían piedad.' WHERE `ID`=26320;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탈것! 탈것이 더 필요하오!', `MaleText_loc4`='坐骑。我们需要更多的坐骑！', `MaleText_loc5`='坐騎。我們需要更多坐騎!', `MaleText_loc7`='Monturas. ¡Necesitamos más monturas!' WHERE `ID`=26321;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탈것! 탈것이 더 필요하오!$B$B오, 당신은 야수 때문에 오셨소?', `MaleText_loc4`='坐骑。我们需要更多的坐骑！$B$B你大概是来寄放宠物的？', `MaleText_loc5`='坐騎。我們需要更多的坐騎!$B$B嗯，你大概是為了你的寵物而來的吧?', `MaleText_loc7`='¡Monturas! ¡Necesitamos más monturas!$B$BOh, supongo que has venido a por tu mascota.' WHERE `ID`=26322;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 언덕이 보여주는 천연의 아름다움 밑에는 엄청난 어둠이 숨겨져 있습니다. 벗이여, 걸음을 조심해서 옮기세요.', `FemaleText_loc4`='黑暗就蛰伏在这片秀丽的山岭下。朋友，千万当心。', `FemaleText_loc5`='這些山丘的自然之美隱藏了巨大的黑暗力量。小心行走，朋友。', `FemaleText_loc7`='La belleza natural de estas Colinas oculta una gran oscuridad bajo ellas. Ten cuidado, colega.' WHERE `ID`=26323;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누군가 화장실을 사용 중입니다.', `MaleText_loc4`='厕所好像被占用了。', `MaleText_loc5`='廁所似乎有人在用。', `MaleText_loc7`='La letrina parece estar ocupada en este momento.' WHERE `ID`=26324;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하십시오. 리치 왕이 뻗치는 역병의 손길이 점점 다가옵니다.', `MaleText_loc4`='小心，周围可能有那些传播着巫妖王诅咒的爪牙。', `MaleText_loc5`='小心，巫妖王瘟疫的魔爪潛伏靠近了。', `MaleText_loc7`='Ten cuidado ya que los tentáculos apestados del Rey Exánime acechan de cerca.', `FemaleText_loc1`='조심하십시오. 리치 왕이 뻗치는 역병의 손길이 점점 다가옵니다.', `FemaleText_loc4`='小心，周围可能有那些传播着巫妖王诅咒的爪牙。', `FemaleText_loc5`='小心，巫妖王瘟疫的魔爪潛伏靠近了。', `FemaleText_loc7`='Ten cuidado ya que los tentáculos apestados del Rey Exánime acechan de cerca.' WHERE `ID`=26325;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용맹한 $n|1이여;여;, 빛이 당신의 역병을 정화하기를.', `MaleText_loc4`='愿圣光净化你，勇敢的$n。', `MaleText_loc5`='願聖光潔淨你的疫病，勇敢的$n。', `MaleText_loc7`='Que la Luz purgue tu infección, valiente $n.', `FemaleText_loc1`='용맹한 $n|1이여;여;, 빛이 당신의 역병을 정화하기를.', `FemaleText_loc4`='愿圣光净化你，勇敢的$n。', `FemaleText_loc5`='願聖光潔淨你的疫病，勇敢的$n。', `FemaleText_loc7`='Que la Luz purgue tu infección, valiente $n.' WHERE `ID`=26326;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아버지는 내게 전투 갑옷과 도끼를 물려주셨네. 머지않아 이것들을 사용할 때가 올 걸세.', `MaleText_loc4`='我的父亲将他的作战盔甲和斧头都送给我啦。很快我就能好好利用它们了。', `MaleText_loc5`='我從父親那兒繼承了他的戰甲和戰斧，很快的，我就善加利用了它們。', `MaleText_loc7`='Mi padre me ha regalado esta armadura de batalla y esta hacha. Pronto les daré buen uso.' WHERE `ID`=26327;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 일을 돕는 영광을 누리게 해달라고 여기 온 거라면 얼마든지 환영하겠네. 그게 아니라면 딱히 내가 자네 덕을 볼 일은 없을 듯하군.', `MaleText_loc4`='如果你是来这里诚心恳求我赐予你为我效劳的机会，那么我欢迎你。不然的话，你到一边凉快去吧。', `MaleText_loc5`='如果你們是來這請求我恩準你們在我手下做事的話，那麼我很歡迎你們一伙人。要不然，你們對我來說沒什麼用處。', `MaleText_loc7`='Si estás aquí para suplicarme trabajar para mí, entonces tu compañía se agradece bastante. Si no es así, no veo en qué podrías serme de utilidad.' WHERE `ID`=26328;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 자세한 이야기를 들려 주십시오.', `MaleText_loc4`='做个自我介绍吧。', `MaleText_loc5`='說說你自己吧。', `MaleText_loc7`='Háblame de ti.', `FemaleText_loc1`='더 자세한 이야기를 들려 주세요.', `FemaleText_loc4`='做个自我介绍吧。', `FemaleText_loc5`='說說你自己吧。', `FemaleText_loc7`='Háblame de ti.' WHERE `ID`=26330;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='운 좋게도, 지금은 화장실이 비었습니다.', `MaleText_loc4`='真幸运，厕所现在没人。', `MaleText_loc5`='所幸，廁所現在沒人使用。', `MaleText_loc7`='Por suerte, la letrina está vacía.' WHERE `ID`=26331;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='화장실을 사용합니다.', `MaleText_loc4`='上厕所。', `MaleText_loc5`='使用廁所。', `MaleText_loc7`='Usa la letrina.', `FemaleText_loc1`='화장실을 사용합니다.', `FemaleText_loc4`='上厕所。', `FemaleText_loc5`='使用廁所。', `FemaleText_loc7`='Usa la letrina.' WHERE `ID`=26332;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='식량도 마실 물도 너무나 부족해요. 드릴 게 아무것도 없어서 안타깝군요.', `FemaleText_loc4`='我们的食物和饮料储备已经出现短缺。恐怕我没什么能给你的。', `FemaleText_loc5`='我們就快斷糧了，我恐怕拿不出任何一點東西給你。', `FemaleText_loc7`='Tenemos poca comida y bebida. Me temo que no tengo nada que ofrecerte.' WHERE `ID`=26333;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='도와주셔서 감사합니다, $n 님. 이 서리딸기는 그야말로 당신의 노력이 맺은 결실이에요.', `FemaleText_loc4`='谢谢你的帮助，$n。这些冰莓就当作你的劳动果实吧。', `FemaleText_loc5`='謝謝你的幫助，$n。這些霜莓真可說是你的辛勞的成果。', `FemaleText_loc7`='Gracias por tu ayuda, $n. Estos gelifructus son, literalmente, el fruto de tu trabajo.' WHERE `ID`=26334;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 바보가 감히 이 땅에 들어왔지?!', `MaleText_loc4`='蠢货！你们不该踏上这片土地！', `MaleText_loc5`='你們跑來這裡真是愚蠢無比!', `MaleText_loc7`='¡Fuisteis unos insensatos al venir a esta tierra!' WHERE `ID`=26335;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈을 잡아먹고 뼈는 이쑤시개로 써 주마!', `MaleText_loc4`='我要消灭你们！', `MaleText_loc5`='我會吃光你的肉，再用你個骨頭剔牙!', `MaleText_loc7`='¡Consumiré tu carne y me limpiaré los dientes con tus huesos!' WHERE `ID`=26336;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈은 마그나타우르도 아닌데! 그런... 힘을... 대체... 어디서 얻었지?', `MaleText_loc4`='你不是猛犸人！你的……力量……是……怎么来的？', `MaleText_loc5`='你不是猛瑪象人!那...你是...打哪...發現...這力量的?', `MaleText_loc7`='¡No eres un magnatauro! ¿De dónde... has... sacado... tanta fuerza?' WHERE `ID`=26337;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곧 친구들도 네 곁으로 보내 주마. 넌 너의 종족을 구하지 못했어.', `MaleText_loc4`='接下来就该轮到你的女人和孩子了。你要让可怜的猛犸人氏族失望了。', `MaleText_loc5`='你死了之後就輪到你的女人和小孩。你令你可悲的種族失望了。', `MaleText_loc7`='Tus mujeres y niños son los siguientes. Han fallado a su lamentable raza.' WHERE `ID`=26340;
