UPDATE `locales_broadcast_text` SET `MaleText_loc1`='술에 취하기라도 해서 이 악몽을 잊었으면!', `MaleText_loc4`='我真是选了个戒酒的好日子啊！', `MaleText_loc5`='我挑錯日子戒酒了!', `MaleText_loc7`='¡He elegido un mal día para dejar de beber!', `FemaleText_loc1`='술에 취하기라도 해서 이 악몽을 잊었으면!', `FemaleText_loc4`='我真是选了个戒酒的好日子啊！', `FemaleText_loc5`='我挑錯日子戒酒了!', `FemaleText_loc7`='¡He elegido un mal día para dejar de beber!' WHERE `ID`=26345;
