UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이놈들은 다 어디서 나온 거지! 누가 좀 도와줘요!', `MaleText_loc4`='这是怎么搞的！谁来救救我！', `MaleText_loc5`='這到底是從哪來的!來人哪!', `MaleText_loc7`='¿De dónde ha salido todo esto? ¡Que alguien me ayude!', `FemaleText_loc1`='이놈들은 다 어디서 나온 거지! 누가 좀 도와줘요!', `FemaleText_loc4`='这是怎么搞的！谁来救救我！', `FemaleText_loc5`='這到底是從哪來的!來人哪!', `FemaleText_loc7`='¿De dónde ha salido todo esto? ¡Que alguien me ayude!' WHERE `ID`=26348;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구울이 되는 역병이 또 퍼질 줄 누가 알았겠어? 잠깐, 사실은 모두 예상하고 있었지?!', `MaleText_loc4`='谁能想到我们会遇到同样的状况呢？噢，不，大家都想到了！', `MaleText_loc5`='誰曉得我們又碰上這個麻煩了?喔，不對喔，是『大家都知道了』!', `MaleText_loc7`='¿Quién hubiera imaginado que volveríamos a tener este problema? Oh espera, ¡TODO EL MUNDO!', `FemaleText_loc1`='구울이 되는 역병이 또 퍼질 줄 누가 알았겠어? 잠깐, 사실은 모두 예상하고 있었지?!', `FemaleText_loc4`='谁能想到我们会遇到同样的状况呢？噢，不，大家都想到了！', `FemaleText_loc5`='誰曉得我們又碰上這個麻煩了?喔，不對喔，是『大家都知道了』!', `FemaleText_loc7`='¿Quién hubiera imaginado que volveríamos a tener este problema? Oh espera, ¡TODO EL MUNDO!' WHERE `ID`=26349;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 벤자민. 호박색 씨앗을 되찾았네. 어떻게 해야 하는지는 자네도 알고 있겠지.', `MaleText_loc4`='很好。我们已经找到了琥珀种子。你知道该怎么做了吧。', `MaleText_loc5`='好啦，小班，我們把琥珀種子帶回來了。你知道規矩的。', `MaleText_loc7`='Vale, Ben. Hemos recuperado los granos ámbar. Ya sabes qué hacer.' WHERE `ID`=26350;
