UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘들어!!! 더 못 뛴다!!!!', `MaleText_loc4`='别跑！！！别再跑了！！！！', `MaleText_loc5`='別跑!!!別再跑了!!!', `MaleText_loc7`='¡NO CORRER! ¡NO MÁS CORRER!' WHERE `ID`=26356;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와줘서 고맙습니다, 당신은 영웅입니다!', `MaleText_loc4`='谢谢你的帮助，勇士！', `MaleText_loc5`='英雄，多謝相救!', `MaleText_loc7`='Gracias por tu ayuda, héroe.', `FemaleText_loc1`='도와줘서 감사해요, 진정한 영웅이세요!', `FemaleText_loc4`='谢谢你的帮助，勇士！', `FemaleText_loc5`='英雄，多謝相救!', `FemaleText_loc7`='Gracias por tu ayuda, héroe.' WHERE `ID`=26357;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 생명을 구해주셨군요! 감사합니다!', `MaleText_loc4`='你救了我！谢谢！', `MaleText_loc5`='你救了我一命!謝謝你!', `MaleText_loc7`='¡Me has salvado la vida! ¡Gracias!', `FemaleText_loc1`='제 생명을 구해주셨군요! 감사합니다!', `FemaleText_loc4`='你救了我！谢谢！', `FemaleText_loc5`='你救了我一命!謝謝你!', `FemaleText_loc7`='¡Me has salvado la vida! ¡Gracias!' WHERE `ID`=26358;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이걸 어떻게 조종하는지 정말로 아시는 거지요? 조금 불안하군요.', `MaleText_loc4`='你真的懂得如何驾驭狮鹫吗？我怎么觉得有点晃悠悠的？', `MaleText_loc5`='你真的知道該怎麼飛這玩意兒嗎?好像不是很穩。', `MaleText_loc7`='¿Seguro que sabes pilotar esta cosa? Se tambalea un poco.', `FemaleText_loc1`='이걸 어떻게 조종하는지 정말로 아시는 거지요? 조금 불안하군요.', `FemaleText_loc4`='你真的懂得如何驾驭狮鹫吗？我怎么觉得有点晃悠悠的？', `FemaleText_loc5`='你真的知道該怎麼飛這玩意兒嗎?好像不是很穩。', `FemaleText_loc7`='¿Seguro que sabes pilotar esta cosa? Se tambalea un poco.' WHERE `ID`=26359;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은혜도 모르는 놈으로 보이긴 싫지만, 좀 낮게 날아주시지 않겠습니까? 전 고소공포증이 있단 말입니다!', `MaleText_loc4`='我不是忘恩负义的家伙啦，但是你能飞得再低一点吗？我恐高！', `MaleText_loc5`='我不是想講得好像我不知感恩一樣，但是你能不能飛靠近地面一點?我討厭高處!', `MaleText_loc7`='No quiero parecer desagradecido, pero ¿podrías volar un poco más cerca del suelo? ¡Odio las alturas!', `FemaleText_loc1`='은혜도 모르는 여자로 보이긴 싫지만, 좀 낮게 날아주시면 안 될까요? 전 고소공포증이 있단 말이에요!', `FemaleText_loc4`='我不是忘恩负义的家伙啦，但是你能飞得再低一点吗？我恐高！', `FemaleText_loc5`='我不是想講得好像我不知感恩一樣，但是你能不能飛靠近地面一點?我討厭高處!', `FemaleText_loc7`='No quiero parecer desagradecida, pero ¿podrías volar un poco más cerca del suelo? ¡Odio las alturas!' WHERE `ID`=26360;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='북쪽에 동족이 있다는 걸 배우고는, 나는 더 많은 사실을 알아내고자 이곳에 왔소. 하지만 내가 발견한 것은 우리 본성과 반대로 싸움을 일삼는 부족뿐이었소.$B$B이제 희망이 없소. 위대한 우르속마저 이 저주받은 곳에서 타락해 버렸소.$B$B나는 모든 희망을 잃었소.', `MaleText_loc4`='当我得知北方还有宗亲时，就满心欢喜地赶来寻访。可我见到的全是侵略性极强的部族，他们身上完全没有和平的天性。$B$B$c，我很绝望。就连伟大的乌索克都没能逃过堕落的命运。$B$B我已经丧失了所有希望。', `MaleText_loc5`='當我聽說了我北方親戚的事之後，我來這裡打聽更多消息。我只看到違背我們天性打仗的部族。$B$B我已經失去所有希望了，$r。甚至連偉大的厄索克都被這受詛咒的大地給污染了。$B$B我已經失去了所有希望。', `MaleText_loc7`='Cuando descubrí que tenía parientes aquí, en el Norte, vine a averiguar más cosas. Lo que encontré fueron tribus en lucha peleando contra nuestra propia naturaleza.$B$BNo me queda esperanza, $r. Este lugar maldito ha logrado corromper incluso al gran Ursoc.$B$BHe perdido toda la esperanza.' WHERE `ID`=26361;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 제 수호천사입니다! 저 하늘에서 날아와 이 절망의 구덩이에서 저를 구해주신 백기사라고요!', `MaleText_loc4`='你真是我的守护天使！你就像来自天堂的白衣骑士，将我从地狱的深渊中解救出来！', `MaleText_loc5`='你是我的守護天使!你是從天堂飛來的白騎士，把我從詛咒的深淵中救出來!', `MaleText_loc7`='¡Eres mi ángel guardián! Como un blanco caballero, volaste desde el cielo y me sacaste del foso de perdición.', `FemaleText_loc1`='당신은 제 수호천사예요! 저 하늘에서 날아와 이 절망의 구덩이에서 저를 구해주신 백기사라고요!', `FemaleText_loc4`='你真是我的守护天使！你就像来自天堂的白衣骑士，将我从地狱的深渊中解救出来！', `FemaleText_loc5`='你是我的守護天使!你是從天堂飛來的白騎士，把我從詛咒的深淵中救出來!', `FemaleText_loc7`='¡Eres mi ángel guardián! Como un blanco caballero, volaste desde el cielo y me sacaste del foso de perdición.' WHERE `ID`=26362;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 은혜를 어떻게 갚으면 좋을까요?', `MaleText_loc4`='我该怎么报答你呢，朋友？', `MaleText_loc5`='我要怎麼樣才能報答你，朋友?', `MaleText_loc7`='¿Cómo puedo pagarte esto, colega?', `FemaleText_loc1`='이 은혜를 어떻게 갚으면 좋을까요?', `FemaleText_loc4`='我该怎么报答你呢，朋友？', `FemaleText_loc5`='我要怎麼樣才能報答你，朋友?', `FemaleText_loc7`='¿Cómo puedo pagarte esto, colega?' WHERE `ID`=26363;
