UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 그리핀에 타세요!', `MaleText_loc4`='骑到我的狮鹫背上来！', `MaleText_loc5`='快跳上我的獅鷲獸，市民!', `MaleText_loc7`='¡Sube a lomos de mi grifo, ciudadano!', `FemaleText_loc1`='제 그리핀에 타세요!', `FemaleText_loc4`='骑到我的狮鹫背上来！', `FemaleText_loc5`='快跳上我的獅鷲獸，市民!', `FemaleText_loc7`='¡Sube a lomos de mi grifo, ciudadano!' WHERE `ID`=26370;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 올라타십시오!', `MaleText_loc4`='快！上来！', `MaleText_loc5`='快點!爬上來!', `MaleText_loc7`='¡Rápido! ¡Sube a bordo!', `FemaleText_loc1`='어서 올라타세요!', `FemaleText_loc4`='快！上来！', `FemaleText_loc5`='快點!爬上來!', `FemaleText_loc7`='¡Rápido! ¡Sube a bordo!' WHERE `ID`=26371;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='윈터가드나 부패의 벌판으로 돌아가지 않으면 그리핀이 당신을 떨어트릴 겁니다!', `MaleText_loc4`='返回暮冬城或是腐臭平原，否则狮鹫会抛下你！', `MaleText_loc5`='返回溫特加德或腐屍農地，否則你的獅鷲獸會把你拋下!', `MaleText_loc7`='¡Regresa a Hibergarde o a Los Campos de Carroña o tu grifo te tirará!' WHERE `ID`=26372;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 뒤에 있으시오, $r. 온 힘을 다해 그대를 보호하겠소.', `MaleText_loc4`='站到我身后，$r。我会尽力保护你的。', `MaleText_loc5`='待在我身後，$r，我會盡力保護你的。', `MaleText_loc7`='Quédate detrás de mí, $r. Haré lo que pueda para protegerte.' WHERE `ID`=26373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우르속을 구하지 못한다면 내 자유에는 아무 의미도 없소. 서두르시오, $n.', `MaleText_loc4`='如果不能拯救乌索克，那我的自由也就毫无意义了。要快，$n。', `MaleText_loc5`='如果我們無法拯救厄索克，我的自由就沒有任何意義。動作快吧，$n。', `MaleText_loc7`='Mi libertad no significará nada si no logramos salvar a Ursoc. Date prisa, $n.' WHERE `ID`=26374;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대와 그대의 동료를 지키겠소, $r.', `MaleText_loc4`='我会保护你和你的盟友，$r。', `MaleText_loc5`='我會看緊你，和你的同夥，$r。', `MaleText_loc7`='Cuidaré de ti y de tus aliados, $r.' WHERE `ID`=26375;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드루이드의 곰 형상을 취해 주십시오, 투르.', `MaleText_loc4`='图尔，变成熊形态吧。', `MaleText_loc5`='圖爾，變身成熊形態。', `MaleText_loc7`='Adopta tu forma druídica de oso, Tur.', `FemaleText_loc1`='드루이드의 곰 형상을 취해 주세요, 투르.', `FemaleText_loc4`='图尔，变成熊形态吧。', `FemaleText_loc5`='圖爾，變身成熊形態。', `FemaleText_loc7`='Adopta tu forma druídica de oso, Tur.' WHERE `ID`=26376;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그를 쓰러뜨리는 데 힘을 빌려주십시오.', `MaleText_loc4`='帮我们制伏他。', `MaleText_loc5`='幫我們壓制他。', `MaleText_loc7`='Ayúdanos a doblegarlo.', `FemaleText_loc1`='그를 쓰러뜨리는 데 힘을 빌려주세요.', `FemaleText_loc4`='帮我们制伏他。', `FemaleText_loc5`='幫我們壓制他。', `FemaleText_loc7`='Ayúdanos a doblegarlo.' WHERE `ID`=26377;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='치유사로 활약해 주십시오.', `MaleText_loc4`='我们需要一名治疗者。', `MaleText_loc5`='我們需要一位治療者。', `MaleText_loc7`='Nos vendría bien un sanador.', `FemaleText_loc1`='치유사로 활약해 주세요.', `FemaleText_loc4`='我们需要一名治疗者。', `FemaleText_loc5`='我們需要一位治療者。', `FemaleText_loc7`='Nos vendría bien un sanador.' WHERE `ID`=26378;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 볼드랏실의 묘목을 태우고 남은 재를 정화했습니다. 우르속을 쓰러뜨리면 그의 영혼을 치유할 수 있을 겁니다.', `MaleText_loc4`='我们已经净化了沃达希尔的树苗。如果能制伏乌索克，我们或许能治愈他的灵魂。', `MaleText_loc5`='我們有了淨化過的沃達希爾樹苗灰燼。如果我們能夠壓制住厄索克，也許我們就可以治療祂的靈魂。', `MaleText_loc7`='Tenemos las cenizas purificadas del árbol joven de Vordrassil. Si podemos dominar a Ursoc, quizá podamos curar su alma.', `FemaleText_loc1`='우리가 볼드랏실의 묘목을 태우고 남은 재를 정화했어요. 우르속을 쓰러뜨리면 그의 영혼을 치유할 수 있을 겁니다.', `FemaleText_loc4`='我们已经净化了沃达希尔的树苗。如果能制伏乌索克，我们或许能治愈他的灵魂。', `FemaleText_loc5`='我們有了淨化過的沃達希爾樹苗灰燼。如果我們能夠壓制住厄索克，也許我們就可以治療祂的靈魂。', `FemaleText_loc7`='Tenemos las cenizas purificadas del árbol joven de Vordrassil. Si podemos dominar a Ursoc, quizá podamos curar su alma.' WHERE `ID`=26379;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇군... 볼드랏실의 마력을 느낄 수 있소... 타락한 기운은 느껴지지 않는군.$B$B부탁이오! 내가 그대를 돕겠소. 운명이 날 이곳으로 이끌었소. 어쩌면 내가 할 수 있는 일이 아직 남았을지도 모르오!', `MaleText_loc4`='是的……我能感觉到沃达希尔的魔法能量……没有丝毫被污染的迹象。$B$B让我帮助你吧！命运让我来到这里，或许我能帮上忙的！', `MaleText_loc5`='是的...我感覺到沃達希爾的魔法了...沒有任何的污染。$B$B拜託!請務必讓我幫助你。命運把我帶來這裡，也許我能夠幫上忙!', `MaleText_loc7`='Sí... Siento la magia de Vordrassil... y no puedo percibir ningún tipo de corrupción.$B$B¡Por favor! Tienes que permitir que te ayude. El destino me ha traído aquí, ¡quizá aún tenga algún propósito!' WHERE `ID`=26380;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 구원을 받았군요! 고맙습니다, 이방인이여!', `MaleText_loc4`='终于安全了！谢谢你，陌生人！', `MaleText_loc5`='終於安全了!謝謝你，陌生人!', `MaleText_loc7`='¡Al fin a salvo! ¡Gracias, $gforastero:forastera;!', `FemaleText_loc1`='드디어 구원을 받았군요! 정말 고마워요, 이방인이여!', `FemaleText_loc4`='终于安全了！谢谢你，陌生人！', `FemaleText_loc5`='終於安全了!謝謝你，陌生人!', `FemaleText_loc7`='¡Al fin a salvo! ¡Gracias, $gforastero:forastera;!' WHERE `ID`=26381;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야호!', `MaleText_loc4`='万岁！', `MaleText_loc5`='喔耶!', `MaleText_loc7`='¡HURRA!', `FemaleText_loc1`='야호!', `FemaleText_loc4`='万岁！', `FemaleText_loc5`='喔耶!', `FemaleText_loc7`='¡HURRA!' WHERE `ID`=26382;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우릭, 이 세상에 아직 친절한 이가 남아 있군요. 영웅이여, 고맙습니다!', `MaleText_loc4`='乌瑞克，这位勇士真是太善良了。谢谢你，英雄！', `MaleText_loc5`='這個人並沒有失去善良的心，烏里克。謝謝你，英雄!', `MaleText_loc7`='La amabilidad no se ha echado a perder en este, Urik. ¡Gracias, héroe!', `FemaleText_loc1`='우릭, 이 세상에 아직 친절한 이가 남아 있군요. 영웅이여, 고마워요!', `FemaleText_loc4`='乌瑞克，这位勇士真是太善良了。谢谢你，英雄！', `FemaleText_loc5`='這個人並沒有失去善良的心，烏里克。謝謝你，英雄!', `FemaleText_loc7`='La amabilidad no se ha echado a perder en este, Urik. ¡Gracias, héroe!' WHERE `ID`=26383;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 살았군요! 정말로 살았어요!', `MaleText_loc4`='我们成功了！我们真的成功了！', `MaleText_loc5`='我們成功了!我們真的成功了!', `MaleText_loc7`='¡Lo logramos! ¡Lo logramos de verdad!', `FemaleText_loc1`='이제 살았군요! 정말로 살았어요!', `FemaleText_loc4`='我们成功了！我们真的成功了！', `FemaleText_loc5`='我們成功了!我們真的成功了!', `FemaleText_loc7`='¡Lo logramos! ¡Lo logramos de verdad!' WHERE `ID`=26384;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 감사합니다. 나중에 우리 가게에 꼭 들러 주세요!', `MaleText_loc4`='我的店门将永远对你敞开，朋友。', `MaleText_loc5`='我的商店大門將永遠為你敞開，朋友。', `MaleText_loc7`='La puerta de mi tienda siempre estará abierta para ti, colega.', `FemaleText_loc1`='정말 감사합니다. 나중에 우리 가게에 꼭 들러 주세요!', `FemaleText_loc4`='我的店门将永远对你敞开，朋友。', `FemaleText_loc5`='我的商店大門將永遠為你敞開，朋友。', `FemaleText_loc7`='La puerta de mi tienda siempre estará abierta para ti, colega.' WHERE `ID`=26385;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신의 용맹함을 절대 잊지 못할 거예요, $n. 윈터가드는 언제나 당신을 환영할 겁니다.$B$B이 여관을 집처럼 생각해 주시겠어요?', `FemaleText_loc4`='我们不会忘记你的英勇行为，$n。你永远是暮冬城的客人。$B$B你愿意将这座旅馆当作自己的家吗？', `FemaleText_loc5`='我們永遠不會忘記你的勇氣，$n。溫特加德永遠歡迎你。$B$B你想把這個旅館當作你的家嗎?', `FemaleText_loc7`='Nunca olvidaremos tu valor, $n. Siempre serás bienvenido en Hibergarde.$B$B¿Te gustaría establecer tu hogar en esta posada?' WHERE `ID`=26386;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물건을 보고 싶습니다, 일루시아.', `MaleText_loc4`='我想看看你出售的货物，伊露希亚。', `MaleText_loc5`='我想看看你的商品，伊魯希雅。', `MaleText_loc7`='Me gustaría ver tus mercancías, Illusia.', `FemaleText_loc1`='물건을 보고 싶군요, 일루시아.', `FemaleText_loc4`='我想看看你出售的货物，伊露希亚。', `FemaleText_loc5`='我想看看你的商品，伊魯希雅。', `FemaleText_loc7`='Me gustaría ver tus mercancías, Illusia.' WHERE `ID`=26387;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 지바루스는 그대에게 진심으로 감사합니다, 영웅이여. 그대가 아니었다면 전 이미 죽었거나, 아니면 그놈들 중 하나가 되었을지도 모릅니다...', `MaleText_loc4`='塞巴鲁斯打心眼儿里感激你。若不是你，我早就没命啦，说不定还会变成亡灵的一员……', `MaleText_loc5`='賽巴魯思打從心底感謝你，英雄。要是沒有你，賽巴魯思可能會死掉，或者更慘一點，賽巴魯思可能會變成他們之中的一員...', `MaleText_loc7`='Zybarus te da las gracias desde el fondo de su corazón, héroe. Sin ti, Zybarus habría muerto, o peor, se habría convertido en uno de ellos...' WHERE `ID`=26388;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1은;는; 신음하고 있지만, 스컬지의 역병에 영향을 받은 것 같지는 않습니다.', `MaleText_loc4`='%s呻吟着，但是似乎并没有受到感染。', `MaleText_loc5`='%s發出了呻吟，但似乎沒有其他受到荒疫影響的徵兆。', `MaleText_loc7`='El %s gime pero parece no sentirse afectado por el añublo.' WHERE `ID`=26389;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 강한 수호를 받고 있습니다. 일을 계속하십시오.', `MaleText_loc4`='你的信仰很坚定，孩子。继续做事吧。', `MaleText_loc5`='你身上的保護很強，孩子。繼續你的工作。', `MaleText_loc7`='Tu protección es fuerte, hijo. Continúa trabajando.', `FemaleText_loc1`='당신은 강한 수호를 받고 있습니다. 일을 계속하십시오.', `FemaleText_loc4`='你的信仰很坚定，孩子。继续做事吧。', `FemaleText_loc5`='你身上的保護很強，孩子。繼續你的工作。', `FemaleText_loc7`='Tu protección es fuerte, hijo. Continúa trabajando.' WHERE `ID`=26390;
