UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 우리의 신성한 일을 방해한단 말이냐?!', `MaleText_loc4`='你竟敢干扰我们正义的事业？！', `MaleText_loc5`='你膽敢妨礙我們的正義之舉?!', `MaleText_loc7`='¿Cómo te atreves a interrumpir nuestro importantísimo trabajo?' WHERE `ID`=26405;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s의 룬이 밝게 빛나기 시작합니다!', `MaleText_loc4`='%s身上的符文突然散发出明亮的光芒！', `MaleText_loc5`='%s身上的符文開始發出明亮的光芒!', `MaleText_loc7`='¡Una runa sobre %s comienza a brillar!' WHERE `ID`=26406;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 땅을 지배했던 위대한 우르속의 아들로서 나도 한때는 회색 구릉지를 활보했다.$B$B하지만 이제는... 여생을 이 동굴에서 지낼 수밖에 없는 처지가 되었지.', `MaleText_loc4`='我曾经以乌索克之子的身份在灰熊丘陵巡游，统治着这片领地。$B$B如今……我却只能窝在洞穴中苟延残喘，度过悲惨的余生。', `MaleText_loc5`='我曾在灰白之丘遊蕩過，偉大的厄索克之子，統治了那個地方。$B$B但是如今...如今我卻註定在這個洞穴裡面度過餘生了。', `MaleText_loc7`='Hace tiempo caminaba por las Colinas Pardas, pues era hijo del gran Ursoc, quien reinaba en esta tierra.$B$BPero ahora... ahora estoy condenado a pasar el resto de mi vida en esta cueva.' WHERE `ID`=26407;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 자유입니다, 오르손. 하지만 먼저 펄볼그에게 무슨 일이 일어났는지 가르쳐 주십시오.', `MaleText_loc4`='奥索恩，你随时可以离开，但是请先告诉我熊怪们到底出了什么事。', `MaleText_loc5`='你自由了，歐爾嵩，但先告訴我熊怪到底出了什麼問題。', `MaleText_loc7`='Eres libre de irte Orsonn, pero primero dime qué pasa con los fúrbolgs.', `FemaleText_loc1`='당신은 자유입니다, 오르손. 하지만 먼저 펄볼그에게 무슨 일이 일어났는지 가르쳐 주세요.', `FemaleText_loc4`='奥索恩，你随时可以离开，但是请先告诉我熊怪们到底出了什么事。', `FemaleText_loc5`='你自由了，歐爾嵩，但先告訴我熊怪到底出了什麼問題。', `FemaleText_loc7`='Eres libre de irte Orsonn, pero primero dime qué pasa con los fúrbolgs.' WHERE `ID`=26408;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전혀 이해하지 못하는군. 내가 원하기만 했다면, 싸워서 스스로 동굴에서 빠져나갔을 것이다.$B$B내 아버지 우르속이 문제다. 아버지는 죽음에서 되돌아왔지... 하지만 이전과는 다르다.$B$B아버지는 수천 년 전에 일어난 고대의 전쟁에서 목숨을 잃었다. 수세기에 걸쳐 아버지를 숭배한 펄볼그는 아버지를 부활시킬 방법을 찾고자 노력했지.$B$B마침내 그들은 버려진 세계수 볼드랏실을 다시 길러, 그 마법으로 아버지를 되살리려고 했다.', `MaleText_loc4`='你不能理解我的处境。我真想出去的话，早就杀出一条血路离开这个洞穴了。$B$B可我不能丢下父亲乌索克不管啊。他复活了……却不再是从前的心性。$B$B在数千年前的上古之战中，我的父亲就已经阵亡。崇拜他的熊怪部族一直想要复活他。$B$B最终他们决定重新培植那株被德鲁伊砍倒的世界之树——沃达希尔，企图利用它的力量复活我的父亲。', `MaleText_loc5`='你不明白。如果我想的話我可以殺出這個洞窟。$B$B是我的父親，厄索克。他從死亡中回來了...但是不再是以前的他。$B$B他在幾千年前的先祖之戰中犧牲了性命。幾百年來，信仰他的熊怪們試圖找出復活他的方法。$B$B最後他們決定試圖重植世界樹，沃達希爾，並且使用世界樹的魔法將我的父親帶回這世界。', `MaleText_loc7`='No lo entiendes. Si quisiera, podría salir de esta cueva luchando.$B$BEs mi padre, Ursoc. Ha regresado de entre los muertos... pero ya no es el mismo.$B$BDio su vida durante la Guerra de los Ancestros hace miles de años. Durante siglos, los fúrbolgs que le rendían pleitesía intentaron encontrar un modo de resucitarlo.$B$BFinalmente, decidieron que iban a intentar que el fallido Árbol del Mundo, Vordrassil, volviera a crecer y usar su magia para resucitar a mi padre.' WHERE `ID`=26409;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='목소리를 낮추게, $c. 난 지금 돌격대 녀석들 모습으로 위장해서 원한의 초소에 필요한 정보를 수집하는 중일세.', `FemaleText_loc4`='小声点，$c。没瞧见我正穿着伪装为怨毒镇侦察吗？', `FemaleText_loc5`='壓低你的音量，$c。我披著偽裝替毒怨之地進行諜報工作。', `FemaleText_loc7`='Habla en voz baja, $c. Soy una espía de Rencor Venenoso disfrazada.' WHERE `ID`=26410;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그다음엔 어떤 일이 일어났습니까?', `MaleText_loc4`='然后发生了什么？', `MaleText_loc5`='然後發生了什麼事?', `MaleText_loc7`='¿Qué ocurrió entonces?', `FemaleText_loc1`='그다음엔 어떤 일이 일어났나요?', `FemaleText_loc4`='然后发生了什么？', `FemaleText_loc5`='然後發生了什麼事?', `FemaleText_loc7`='¿Qué ocurrió entonces?' WHERE `ID`=26411;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='펄볼그는 묘목을 길러 결실을 보았다. 처음에는 모든 일이 잘되어 가는 줄 알았지. 실제로 아버지는 돌아왔고 나도 잠시나마 기뻐했다.$B$B하지만 회복되어 갈수록 그는 이전과 다른 모습을 보였지. 펄볼그도 마찬가지였다.$B$B고대의 드루이드로 하여금 볼드랏실을 버릴 수밖에 없도록 했던 악의 기운이 새 나무에도 깃들어, 그들을 모두 피에 굶주린 괴물로 만들어 버린 것이다.$B$B지금 회색 구릉지를 걸어다니는 그것은 내 아버지가 아니다. 반드시 잠들게 해야 한다.', `MaleText_loc4`='他们种下的树苗结出了一枚果实。最初一切都进展顺利。乌索克真的复活了，我也完全沉浸在这短暂的喜悦中。$B$B很快我就察觉到，他与生前截然不同。那些熊怪也发生了转变。$B$B当年，德鲁伊们因为不堪世界之树被邪恶力量所腐化，忍痛砍倒了沃达希尔。如今，新生的世界之树再度成为滋生邪恶的温床，令所有的熊怪变成了嗜血的野兽。$B$B出没在灰熊丘陵的怪物不再是我的父亲了，必须让他得到安息。', `MaleText_loc5`='他們種下的樹苗結出了果實。起初似乎很順利，厄索克回來了，有一陣子我心中充滿了喜悅。$B$B但當他復活之後，很顯然跟以前不同了。熊怪也是。$B$B不論是什麼樣的邪惡導致上古德魯伊摧毀了沃達希爾，它顯然寄居在新的樹中，並且把他們全部變成了嗜血的怪獸。$B$B現在在灰白之丘走動的怪物並不是我的父親，我們得讓他安息。', `MaleText_loc7`='El esqueje que crearon tenía un fruto. Al principio pareció funcionar. Ursoc volvió y, durante un breve instante, me llené de alegría.$B$BA medida que se iba recuperando, era evidente que no era el mismo. Tampoco lo eran los fúrbolgs.$B$BEl mal que hizo que los druidas destrozaran a Vordrassil volvió a manifestarse en el nuevo árbol y los convirtió a todos en monstruos sedientos de sangre.$B$BEsa cosa que camina ahora por las Colinas Pardas no es mi padre y ha de ser devuelto a su descanso eterno.' WHERE `ID`=26412;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙습니다, 우르속의 아들이여. 어떤 조치를 취할 수 있을지 알아보겠습니다.', `MaleText_loc4`='谢谢你，乌索克之子。我会力所能及地帮助你。', `MaleText_loc5`='謝謝你，厄索克之子。我會看看我能做些什麼。', `MaleText_loc7`='Gracias, hijo de Ursoc. Veré que puedo hacer.', `FemaleText_loc1`='고맙습니다, 우르속의 아들이여. 어떤 조치를 취할 수 있을지 알아보겠어요.', `FemaleText_loc4`='谢谢你，乌索克之子。我会力所能及地帮助你。', `FemaleText_loc5`='謝謝你，厄索克之子。我會看看我能做些什麼。', `FemaleText_loc7`='Gracias, hijo de Ursoc. Veré que puedo hacer.' WHERE `ID`=26413;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 우르속의 딸, 코디안이다. 한때는 성스러웠던 이 제단을 보살피고 있지.$B$B여기까지 온 이방인은 아주 오랜만에 보는구나.', `MaleText_loc4`='我是科蒂安，乌索克的女儿。我守护着这座曾经被视为圣地的祭坛。$B$B很久以来，都没有陌生人到这里来拜访了。', `MaleText_loc5`='我是寇荻安，厄索克之女。我守護這個一度神聖的祭壇。$B$B我已經很久沒有看過陌生人來此了。', `MaleText_loc7`='Soy Kodian, hija de Ursoc. Vigilo este santuario que en otro tiempo fue sagrado.$B$BNo he visto a ningún extraño venir aquí desde hace mucho tiempo.' WHERE `ID`=26414;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전에 온 이방인은 누구였습니까?', `MaleText_loc4`='这位陌生人是谁？', `MaleText_loc5`='這個陌生人是誰?', `MaleText_loc7`='¿Quién era ese forastero?', `FemaleText_loc1`='전에 온 이방인은 누구였나요?', `FemaleText_loc4`='这位陌生人是谁？', `FemaleText_loc5`='這個陌生人是誰?', `FemaleText_loc7`='¿Quién era ese forastero?' WHERE `ID`=26415;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성난발톱 투르라고 하는 펄볼그였다. 여기 펄볼그가 아니었지.$B$B그는 남쪽 대륙에서 왔었다. 나무구렁 부족에 속한 자였지.$B$B그는 내 아버지, 우르속을 보고 싶어했다. 타락한 볼드랏실을 정화해 아버지를 구해낼 수 있다고 생각하는 것 같더군.$B$B그런 희망을 품다니 어리석기 그지없다. 아버지를 변하게 한 암흑이 어떤 것인지 안다면, 너도 내 말에 동의할 게다.', `MaleText_loc4`='他是一只名叫图尔·怒爪的熊怪。嗯，不属于我们的氏族。$B$B他来自南部的木喉部族。$B$B图尔想见见乌索克。他觉得有希望净化沃达希尔的污染，并借此拯救我的父亲。$B$B抱着这样的希望未免有些天真。等你亲眼目睹我的父亲受到的黑暗污染之后，你就能认同我的看法了。', `MaleText_loc5`='一個名叫圖爾·怒掌的熊怪，不是我們之一。$B$B他來自南邊，屬於木喉部族。$B$B他想要見厄索克。他似乎覺得沃達希爾的腐化可以被淨化，並且用來拯救我父親。$B$B用這樣的希望來戲弄我是很愚蠢的，當你見到他，如同我一樣，被黑暗所折磨，你會同意我說的話的。', `MaleText_loc7`='Un fúrbolg llamado Tur Patafuria. No es uno de los nuestros.$B$BÉl viene de las tierras del sur. Pertenecía a la tribu Fauces de Madera.$B$BQuería ver a Ursoc. Parecía creer que la corrupción de Vordrassil podía ser purificada y utilizada para salvar a mi padre.$B$BEs una locura albergar tales esperanzas. Estarás de acuerdo conmigo cuando veas la oscuridad que le ha afectado.' WHERE `ID`=26416;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙습니다, 코디안. 제가 할 수 있는 일을 하겠습니다.', `MaleText_loc4`='谢谢你，科蒂安。我会尽力的。', `MaleText_loc5`='謝謝你，寇荻安。我會盡我所能。', `MaleText_loc7`='Gracias, Kodian. Haré lo que pueda.', `FemaleText_loc1`='고맙습니다, 코디안. 제가 할 수 있는 일을 하겠어요.', `FemaleText_loc4`='谢谢你，科蒂安。我会尽力的。', `FemaleText_loc5`='謝謝你，寇荻安。我會盡我所能。', `FemaleText_loc7`='Gracias, Kodian. Haré lo que pueda.' WHERE `ID`=26417;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 아름다운 제재소가! 네 이놈! 죽을 줄 알아라!', `MaleText_loc4`='天哪，我漂亮的小磨坊！你！我要你为此付出性命！', `MaleText_loc5`='我美麗的廠房。你!你要為此而死!', `MaleText_loc7`='Mi precioso molino. ¡Tú! ¡Morirás por esto!' WHERE `ID`=26418;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성스러운 빛의 품에 안기길, 악마여.', `MaleText_loc4`='愿圣光与你同行，朋友。', `MaleText_loc5`='願聖光與你同行，朋友。', `MaleText_loc7`='Ve con la Luz, colega.', `FemaleText_loc1`='성스러운 빛의 품에 안기길, 악마여.', `FemaleText_loc4`='愿圣光与你同行，朋友。', `FemaleText_loc5`='願聖光與你同行，朋友。', `FemaleText_loc7`='Ve con la Luz, colega.' WHERE `ID`=26419;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛이 너에게 자비를 베풀기를 바란다, 악마여.', `MaleText_loc4`='让仁慈的圣光救赎你的灵魂吧，恶魔。', `MaleText_loc5`='願聖光憐憫你的靈魂，朋友。', `MaleText_loc7`='Que la Luz tenga piedad de tu alma, demonio.', `FemaleText_loc1`='빛이 너에게 자비를 베풀기를 바란다, 악마여.', `FemaleText_loc4`='让仁慈的圣光救赎你的灵魂吧，恶魔。', `FemaleText_loc5`='願聖光憐憫你的靈魂，朋友。', `FemaleText_loc7`='Que la Luz tenga piedad de tu alma, demonio.' WHERE `ID`=26420;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들도 한때는 사람이었지요... 지금은 뭐냐고요? 고기에 굶주린 언데드 괴물이지요!', `MaleText_loc4`='他们曾经也是人类……可现在呢？不过是一群嗜血的亡灵！', `MaleText_loc5`='他們曾經都是人...現在?現在都是吃人肉的不死怪物!', `MaleText_loc7`='Antes eran gente... ¿Ahora? ¡Monstruos no-muertos con hambre de carne!', `FemaleText_loc1`='저들도 한때는 사람이었지요... 지금은 뭐냐고요? 고기에 굶주린 언데드 괴물이지요!', `FemaleText_loc4`='他们曾经也是人类……可现在呢？不过是一群嗜血的亡灵！', `FemaleText_loc5`='他們曾經都是人...現在?現在都是吃人肉的不死怪物!', `FemaleText_loc7`='Antes eran gente... ¿Ahora? ¡Monstruos no-muertos con hambre de carne!' WHERE `ID`=26421;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우오! 저 녀석 머리가 폭발한 것 같은데!', `MaleText_loc4`='噢噢噢噢！一枪爆头！', `MaleText_loc5`='哦喔喔!我想那個頭炸掉了!', `MaleText_loc7`='¡Oooh! ¡Creo que la cabeza de ese ha explotado!', `FemaleText_loc1`='우오! 저 녀석 머리가 폭발한 것 같은데!', `FemaleText_loc4`='噢噢噢噢！一枪爆头！', `FemaleText_loc5`='哦喔喔!我想那個頭炸掉了!', `FemaleText_loc7`='¡Oooh! ¡Creo que la cabeza de ese ha explotado!' WHERE `ID`=26422;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛이 너를 거둘 것이다!', `MaleText_loc4`='圣光会消灭你！', `MaleText_loc5`='聖光制裁你!', `MaleText_loc7`='¡Que la Luz te lleve!', `FemaleText_loc1`='빛이 너를 거둘 것이다!', `FemaleText_loc4`='圣光会消灭你！', `FemaleText_loc5`='聖光制裁你!', `FemaleText_loc7`='¡Que la Luz te lleve!' WHERE `ID`=26423;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 총알이 걸린 소총을 손봅니다.', `MaleText_loc4`='%s清了清枪管。', `MaleText_loc5`='%s從他的槍裡清出一團堵塞物。', `MaleText_loc7`='%s limpia el atasco de su rifle.', `FemaleText_loc1`='%s|1이;가; 총알이 걸린 소총을 손봅니다.', `FemaleText_loc4`='%s清了清枪管。', `FemaleText_loc5`='%s從他的槍裡清出一團堵塞物。', `FemaleText_loc7`='%s limpia el atasco de su rifle.' WHERE `ID`=26424;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마침내 제대로 된 공물이 도착했군!', `MaleText_loc4`='总算来了一份有价值的祭品！', `MaleText_loc5`='總算有個值得獻祭的祭品!', `MaleText_loc7`='¡Al fin una ofrenda digna!' WHERE `ID`=26425;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더러운 것. 살아갈 가치조차 없는 것들이로구나. 받아라!', `MaleText_loc4`='肮脏的畜生。你们不配活在这世上。我要杀了你们！', `MaleText_loc5`='污穢的蠢貨。你們這種生物沒資格活下去。看劍!', `MaleText_loc7`='Sucio cretino. Los de tu clase no merecen vivir. ¡A por ti!' WHERE `ID`=26426;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우르속, 우르솔의 형제이자 펄볼그 부족의 수호자여... 모습을 보이시오!', `MaleText_loc4`='乌索克，乌索尔的兄弟，熊怪部族的守护者……现身吧！', `MaleText_loc5`='厄索克，厄索的兄弟，熊怪部族的守護神...現身吧!', `MaleText_loc7`='Ursoc, hermano de Ursol y guardián de las tribus fúrbolgs... ¡muéstrate!' WHERE `ID`=26427;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요, 셀리드 누나! 마구간에 데려가야 할 녀석 있나요?', `MaleText_loc4`='嗨，塞莉德！你有宠物要寄放进兽栏吗？', `MaleText_loc5`='嘿，席林德!你有任何寵物要我帶去獸欄的嗎?', `MaleText_loc7`='¡Ey, Celidh! ¿Quieres que lleve alguna mascota al establo?' WHERE `ID`=26428;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 바쁜가 봐요, 셀리드 누나. 제가 마구간에 데려가야 할 녀석이 있나요?', `MaleText_loc4`='我是很忙啦，塞莉德。你有宠物要寄放进兽栏吗？', `MaleText_loc5`='席林德在這裡真的很忙。你有任何寵物要我移到獸欄去的嗎?', `MaleText_loc7`='Hay mucho trabajo por aquí, Celidh. ¿Hay alguna mascota que quieras que lleve al establo?' WHERE `ID`=26429;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='셀리드 누나, 여기 새로 온 사람들 앞에서 장담하건대, 제가 마구간으로 데려가야 할 녀석이 분명히 있을 거예요. 그렇죠?', `MaleText_loc4`='塞莉德，我跟所有新来的人打赌来着，赌你肯定想要在兽栏寄放宠物。', `MaleText_loc5`='我敢打賭，席林德，有這麼多新來的在這裡，你一定有些寵物需要我幫你移到獸欄去對吧。', `MaleText_loc7`='Apuesto a que con toda esta gente nueva por aquí, Celidh, tendrás algunas mascotas que querrás que lleve al establo.' WHERE `ID`=26430;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이리 와, 조용한 곳으로 데려다 줄게.', `MaleText_loc4`='来呀，我带你去个安静的地方。', `MaleText_loc5`='來吧孩子，我們遠離這些噪音。', `MaleText_loc7`='Vamos chico, alejémonos de este jaleo.' WHERE `ID`=26431;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가자, 착한 녀석.', `MaleText_loc4`='走吧。', `MaleText_loc5`='走吧孩子。', `MaleText_loc7`='Vamos, chico.' WHERE `ID`=26432;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이쪽으로 와, 착한 녀석. 내가 뒤쪽에 있는 편안한 마구간에 데려다 줄게.', `MaleText_loc4`='这边走。后面有我们最好的兽栏。', `MaleText_loc5`='這邊，孩子，我會帶你到後面的好獸欄去。', `MaleText_loc7`='Por aquí, chico. Te llevaré a nuestros bonitos establos en la parte de atrás.' WHERE `ID`=26433;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여긴 정말 밝은데다... 아무것도 없다고.', `MaleText_loc4`='这里真是一马平川……阳光充沛……', `MaleText_loc5`='外面當然很晴朗...且溫度適宜。', `MaleText_loc7`='No hay duda de que esto es muy luminoso… y plano.' WHERE `ID`=26434;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 당근을 어떻게 만드는지 얘기해 주십시오!', `MaleText_loc4`='告诉我怎么制作这种胡萝卜！', `MaleText_loc5`='告訴我如何做出那些胡蘿蔔!', `MaleText_loc7`='¡Enséñame a preparar esas zanahorias!', `FemaleText_loc1`='그 당근을 어떻게 만드는지 얘기해 주세요!', `FemaleText_loc4`='告诉我怎么制作这种胡萝卜！', `FemaleText_loc5`='告訴我如何做出那些胡蘿蔔!', `FemaleText_loc7`='¡Enséñame a preparar esas zanahorias!' WHERE `ID`=26435;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대들에게 감사한다. 볼드랏실의 뿌리는 고대 악마의 거처까지 뻗어가 버렸고, 그래서 현명한 드루이드들은 볼드랏실을 파괴하기로 한 것이다.', `MaleText_loc4`='谢谢你们。将沃达希尔砍倒的德鲁伊做出了明智的决定，蛰伏在地底的远古邪灵已经侵淫了那棵世界之树的根须。', `MaleText_loc5`='感謝你所做的一切。古代的德魯伊摧毀沃達希爾是明智的，因為它的根部深深紮入了一個古老的邪惡居所之中。', `MaleText_loc7`='Gracias a todos. Los druidas de antaño fueron sabios al destruir a Vordrassil, pues sus raíces se adentran en la morada de un antiguo mal.' WHERE `ID`=26436;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대들은 그런 악마를 고대 신으로 알고 있다. 요그사론을 조심하라. 그 짐승은 입이 천 개이며, 그 악은 볼드랏실의 뿌리 너머까지 퍼졌다.', `MaleText_loc4`='你们将这种生物称为上古之神。它就是尤格-萨隆，拥有一千张嘴的怪物。它通过沃达希尔的根须散播着邪恶之力。', `MaleText_loc5`='你們稱祂們為古神。小心尤格薩倫，千喉之獸。它的邪惡不僅止於沃達希爾的根部範圍而已。', `MaleText_loc7`='Llamáis a los de su clase dioses antiguos. Ten cuidado con Yogg-Saron, la bestia de las mil fauces. Su maldad se extiende más allá de las raíces de Vordrassil.' WHERE `ID`=26437;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='날 여기서 꺼내줄 수 있겠나?', `FemaleText_loc4`='你能带我离开这里吗，$C？', `FemaleText_loc5`='你覺得你能把我救出去嗎，$c?', `FemaleText_loc7`='¿Crees que podrías sacarme de aquí, $c?' WHERE `ID`=26438;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미안하지만 안 됩니다, 슈나이더. 당신은 여기서 끝입니다!', `MaleText_loc4`='不行，斯克尼德。你的日子到头了！', `MaleText_loc5`='恐怕不能，施耐德。你的死期到了!', `MaleText_loc7`='Me temo que no, Schneider. ¡Ha llegado tu hora!', `FemaleText_loc1`='미안하지만 안 됩니다, 슈나이더. 당신은 여기서 끝입니다!', `FemaleText_loc4`='不行，斯克尼德。你的日子到头了！', `FemaleText_loc5`='恐怕不能，施耐德。你的死期到了!', `FemaleText_loc7`='Me temo que no, Schneider. ¡Ha llegado tu hora!' WHERE `ID`=26439;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오오, 다행이야. 날 구하러 온 모양이군. 어서 날 여기서 꺼내 주게!', `MaleText_loc4`='啊，你是来救我的吧。快带我离开这个鬼地方！', `MaleText_loc5`='噢，真好，你是來救我的。馬上放我出去!', `MaleText_loc7`='Ah bien, has venido a rescatarme. ¡Ahora, sácame de aquí!' WHERE `ID`=26440;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금은 아닙니다, 바리가!', `MaleText_loc4`='今天不行，首席抄写员！', `MaleText_loc5`='沒這回事，資深書記!', `MaleText_loc7`='¡Hoy no, escribano jefe!', `FemaleText_loc1`='지금은 아닙니다, 바리가!', `FemaleText_loc4`='今天不行，首席抄写员！', `FemaleText_loc5`='沒這回事，資深書記!', `FemaleText_loc7`='¡Hoy no, escribano jefe!' WHERE `ID`=26441;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하시오, 친구. 어디선가 본 것 같은데 말이야.$B$B여기서 좀 꺼내 주지 않겠소?', `MaleText_loc4`='嘿！我觉得我好像在哪儿见过你。$B$B不如救我出去，怎么样？', `MaleText_loc5`='嘿，$g老兄:女士;我在這附近見過你。$B$B不介意把我救出去吧?', `MaleText_loc7`='Hey, $gtío:señorita;. Te he visto por aquí.$B$B¿Te importaría sacarme de aquí?' WHERE `ID`=26442;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 됩니다. 위생 기술자로서의 당신 목숨은 오늘로 끝입니다.', `MaleText_loc4`='不行。你担任卫生设备工程师的日子到头了。', `MaleText_loc5`='別怕。你當環境衛生工程師的日子結束了。', `MaleText_loc7`='No temas. Tus días como ingeniero sanitario se acercan a su fin.', `FemaleText_loc1`='안 됩니다. 위생 기술자로서의 당신 목숨은 오늘로 끝입니다.', `FemaleText_loc4`='不行。你担任卫生设备工程师的日子到头了。', `FemaleText_loc5`='別怕。你當環境衛生工程師的日子結束了。', `FemaleText_loc7`='No temas. Tus días como ingeniero sanitario se acercan a su fin.' WHERE `ID`=26443;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공격해라, 나의 아이들아! 너희의 주인이 명한다!', `MaleText_loc4`='进攻吧，我的仆从们！主人命令你们进攻！', `MaleText_loc5`='立刻進攻，爪牙們!你的主人命令你進攻!', `MaleText_loc7`='¡Ataquen ahora, esbirros míos! ¡Su señor lo ordena!' WHERE `ID`=26444;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕께 대항하는 이 나약한 것들을 없애버려라!', `MaleText_loc4`='杀死这名胆敢挑衅巫妖王的凡人！', `MaleText_loc5`='殺死這個膽敢反抗巫妖王的凡人!', `MaleText_loc7`='¡Poned fin a esta afrenta mortal contra el Rey Exánime!' WHERE `ID`=26445;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들의 방어가 무너졌다! 바로 지금이다, 아이들아! 공격해라!', `MaleText_loc4`='他们的防线已经被攻破了！时机到了，奴仆们！进攻！', `MaleText_loc5`='他們的防禦潰散了!就是現在，我的部下!進攻!', `MaleText_loc7`='¡Han bajado sus defensas! ¡Este es el momento, esbirros! ¡ATACAD!' WHERE `ID`=26446;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐가 어떻게 된 건지 모르겠군. 원한의 초소에 도착했다고 생각했는데 막상 깨어나 보니 이 철창에 갇혀 있었지 뭔가!$B$B날 구해주러 왔나?', `MaleText_loc4`='我根本不知道出了什么状况。我刚到怨毒镇没多久，就突然在睡梦中被关进了牢笼！$B$B你是来救我的吗？', `MaleText_loc5`='我搞不清楚怎麼回事。我才剛到毒怨之地，然後當我一覺醒來我就在這牢籠裡了!$B$B你是來救我的嗎?', `MaleText_loc7`='No sé qué pasó. ¡Acababa de llegar a Rencor Venenoso y, de repente, me desperté en esta jaula!$B$B¿Has venido a rescatarme?' WHERE `ID`=26447;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니요, 장관님. 당신을 ''구하러'' 온 것은 아닙니다.', `MaleText_loc4`='不行，司法官。从本质上讲，我并不是来“营救”你的。', `MaleText_loc5`='不，大法官，說真的我不是來『救』你的。', `MaleText_loc7`='No, Canciller, no diría que he venido a "rescatarle" per se.', `FemaleText_loc1`='아니요, 장관님. 당신을 ''구하러'' 온 것은 아닙니다.', `FemaleText_loc4`='不行，司法官。从本质上讲，我并不是来“营救”你的。', `FemaleText_loc5`='不，大法官，說真的我不是來『救』你的。', `FemaleText_loc7`='No, Canciller, no diría que he venido a "rescatarle" per se.' WHERE `ID`=26448;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기서 끝이라니, 그게 무슨 말이지?! 지금 이 자리에서 죽여버리겠어!', `FemaleText_loc4`='什么叫我的日子到头了？！把话说清楚，不然我宰了你！', `FemaleText_loc5`='你說我的死期到了是什麼意思?看我當場殺了你!', `FemaleText_loc7`='¿Qué quieres decir con que ha llegado mi hora? ¡Te mataré ahí mismo!' WHERE `ID`=26449;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럴 수는 없네... 자네를 바보로 만들 내용을 작성해 주지, $c!', `MaleText_loc4`='你不会是想……我要把你的罪行详细记录下来，$C！', `MaleText_loc5`='你該不會是要...我會把你的行為記錄下來，$c!', `MaleText_loc7`='No puedes hablar en serio... ¡Te amonestaré por esto, $c!' WHERE `ID`=26450;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여보게, 여길세!', `FemaleText_loc4`='嗨，我在这儿！', `FemaleText_loc5`='嘿，在這邊!', `FemaleText_loc7`='¡Hey, aquí!' WHERE `ID`=26451;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제발 날 여기서 좀 꺼내주게!', `MaleText_loc4`='你一看就是个大好人，放我出去吧！', `MaleText_loc5`='請你做做好事，把我從這裡放出來!', `MaleText_loc7`='¿Serías tan amable de sacarme de aquí?' WHERE `ID`=26452;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 여기서 꺼내줄 자가 아무도 없는 거요? 원한의 초소로 돌아가서 내 일을 마저 끝내야 한단 말이오.', `MaleText_loc4`='谁放我出去呀？我还要返回怨毒镇换班呢。', `MaleText_loc5`='有人能放我出去嗎?我得回到毒怨之地換班。', `MaleText_loc7`='¿Alguien puede sacarme de aquí? Necesito volver a Rencor Venenoso y acabar mi turno.' WHERE `ID`=26453;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 제발 부탁이오! 날 죽이지 마시오!', `MaleText_loc4`='不！我求求你！千万别杀我！', `MaleText_loc5`='不!我求求你!請不要殺我!', `MaleText_loc7`='¡No! ¡Te lo ruego! ¡Por favor, no me mates!' WHERE `ID`=26454;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='군단, 진격한다!', `MaleText_loc4`='集合，开往前线！', `MaleText_loc5`='軍團，上前線!', `MaleText_loc7`='¡Legión, a las líneas de frente!' WHERE `ID`=26455;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='관문 방어를 강화하라! 스컬지를 들여보내서는 안 된다!', `MaleText_loc4`='增援城门！不要让天灾军团攻破城门！', `MaleText_loc5`='增援大門!不要讓天譴軍團通過!', `MaleText_loc7`='¡Reforzad la puerta! ¡No dejéis que pase la Plaga!' WHERE `ID`=26456;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전선을 유지하라! 군단, 관문을 향해 집중 사격!', `MaleText_loc4`='坚守防线！全军注意，向城门开火！', `MaleText_loc5`='撐住防線!軍團，對大門集中砲火!', `MaleText_loc7`='¡Aguanten! ¡Legión, concentren el fuego en las puertas!' WHERE `ID`=26457;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 무슨 짓인가?! 그만두게! 놈들이 말한 수고비의 두 배를 주겠네!', `MaleText_loc4`='这到底是什么意思？！住手！他们付你多少？？我可以给你两倍的钱！', `MaleText_loc5`='這是什麼意思?!住手!不管他們付你多少，我都付雙倍給你!', `MaleText_loc7`='¿Qué significa esto? ¡Para! ¡Te pagaré el doble!' WHERE `ID`=26458;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 이제 막 원한의 초소에 온 몸이네. 내가 자네에게 무슨 잘못을 했단 말인가?', `MaleText_loc4`='我刚刚到怨毒镇啊，怎么可能招惹到你？', `MaleText_loc5`='我才剛到毒怨之地。我怎麼可能有得罪過你?', `MaleText_loc7`='Acabo de llegar a Rencor Venenoso. ¿Cómo he podido ofenderte?' WHERE `ID`=26459;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요.$B$B무엇을 도와드릴까요?', `FemaleText_loc4`='你好，$c。$B$B我能帮上什么忙吗？', `FemaleText_loc5`='你好，$c。$B$B我能為你效勞嗎?', `FemaleText_loc7`='Saludos, $c.$B$B¿Cómo puedo ayudarte?' WHERE `ID`=26460;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='토르발트 에릭슨 영주의 사나운 원시비룡이 묶여 있습니다.', `MaleText_loc4`='托瓦德·埃里克森领主的始祖龙被锁链拴在这儿，它是一只脾气暴躁、喜怒无常的凶兽。', `MaleText_loc5`='族長特沃德·艾利克森易怒的元龍被拴在這裡。', `MaleText_loc7`='El temperamental protodraco del señor feudal Torvald Eriksson está encadenado aquí arriba.' WHERE `ID`=26461;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사슬을 풀고 불꽃인도자를 조종합니다.', `MaleText_loc4`='解开烈焰使者的锁链并控制它。', `MaleText_loc5`='鬆開並且控制火焰使者。', `MaleText_loc7`='Desencadena y controla a Clamallamas.', `FemaleText_loc1`='사슬을 풀고 불꽃인도자를 조종합니다.', `FemaleText_loc4`='解开烈焰使者的锁链并控制它。', `FemaleText_loc5`='鬆開並且控制火焰使者。', `FemaleText_loc7`='Desencadena y controla a Clamallamas.' WHERE `ID`=26462;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음? 무슨 일이오?', `MaleText_loc4`='嗯？有什么事吗？', `MaleText_loc5`='嗯?你想說什麼?', `MaleText_loc7`='¿Sí? ¿Qué ocurre?' WHERE `ID`=26463;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일어나라, 용사들이여! 너희의 새로운 주인을 위해 싸워라!', `MaleText_loc4`='战士们，站起来为你们的新主子而战吧！', `MaleText_loc5`='甦醒吧我的戰士，為你的新主人而戰!', `MaleText_loc7`='¡Levántense, mis guerreros, y luchad por su nuevo señor!' WHERE `ID`=26464;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='친절한 영혼을 지니셨군요. 고맙습니다.', `MaleText_loc4`='谢谢你，善良的灵魂。', `MaleText_loc5`='謝謝你，善良的靈魂。', `MaleText_loc7`='Gracias, gentil alma.', `FemaleText_loc1`='친절한 영혼을 지니셨군요. 고맙습니다.', `FemaleText_loc4`='谢谢你，善良的灵魂。', `FemaleText_loc5`='謝謝你，善良的靈魂。', `FemaleText_loc7`='Gracias, gentil alma.' WHERE `ID`=26467;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신을 절대 잊지 않겠습니다.', `MaleText_loc4`='我永远不会忘记你的，朋友。', `MaleText_loc5`='朋友，我不會忘記你的。', `MaleText_loc7`='Nunca te olvidaré, colega.', `FemaleText_loc1`='당신을 절대 잊지 않겠어요.', `FemaleText_loc4`='我永远不会忘记你的，朋友。', `FemaleText_loc5`='朋友，我不會忘記你的。', `FemaleText_loc7`='Nunca te olvidaré, colega.' WHERE `ID`=26468;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마침내 영웅이 오셨군요!', `MaleText_loc4`='终于，来了一位英雄！', `MaleText_loc5`='總算!來了個英雄!', `MaleText_loc7`='¡Por fin ha llegado un héroe!', `FemaleText_loc1`='마침내 영웅이 오셨군요!', `FemaleText_loc4`='终于，来了一位英雄！', `FemaleText_loc5`='總算!來了個英雄!', `FemaleText_loc7`='¡Por fin ha llegado un héroe!' WHERE `ID`=26469;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 와 주어 천만다행입니다, 영웅이여! 녀석들한테 당할 찰나였어요!', `MaleText_loc4`='你来得正是时候，英雄！我差点被那畜生给吃了！', `MaleText_loc5`='你來了真好，鬥士!這隻野獸差點就吃掉我了!', `MaleText_loc7`='¡Me alegro de que hayas venido, $gcampeón:campeona;! ¡La bestia casi me había atrapado!', `FemaleText_loc1`='당신이 와 주어 천만다행입니다, 영웅이여! 녀석들한테 당할 찰나였어요!', `FemaleText_loc4`='你来得正是时候，英雄！我差点被那畜生给吃了！', `FemaleText_loc5`='你來了真好，鬥士!這隻野獸差點就吃掉我了!', `FemaleText_loc7`='¡Me alegro de que hayas venido, $gcampeón:campeona;! ¡La bestia casi me había atrapado!' WHERE `ID`=26470;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들을 제거하십시오.', `MaleText_loc4`='消灭他们。', `MaleText_loc5`='毀掉他們。', `MaleText_loc7`='Aniquiladlos.' WHERE `ID`=26471;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놀아보자는 건가?', `MaleText_loc4`='要玩玩吗？', `MaleText_loc5`='想玩嗎?', `MaleText_loc7`='¿Vienes a jugar?' WHERE `ID`=26472;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들을 즐겁게 해 줘라. 리치 왕께서 보고 계신다!', `MaleText_loc4`='让他们陪伴你吧，巫妖王向你致意！', `MaleText_loc5`='好好享受他們的陪伴吧，巫妖王向你致意!', `MaleText_loc7`='Por favor, disfruta de su compañía. ¡El Rey Exánime envía recuerdos!' WHERE `ID`=26473;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇게 기를 쓰고 달아나지 마라! 네놈들에게 줄 작별 선물이 있다...', `MaleText_loc4`='别急着逃走呀！我还有份“饯别”礼物呢……', `MaleText_loc5`='別急著逃嘛!我有個餞別的禮物...', `MaleText_loc7`='¡No te des tanta prisa en escapar! Tengo un regalo de despedida...' WHERE `ID`=26474;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 조각상 보이니? 이분이 바로 스톰윈드의 임금님이신 바리안 린 님이야.', `MaleText_loc4`='你瞧这座雕像。他就是暴风城的国王瓦利安·乌瑞恩。', `MaleText_loc5`='看到雕像了嗎，孩子?這是暴風之王，瓦里安·烏瑞恩。', `MaleText_loc7`='¿Ves esta estatua, chico? Es el rey de Ventormenta, Varian Wrynn.' WHERE `ID`=26475;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그분의 아들인 안두인 린 님도 한동안 왕위에 계셨어. 나이도 내 또래인데 말이야. 내가 임금님이 된다는 게 상상이나 돼?', `MaleText_loc4`='他的儿子安度因·乌瑞恩就是现任国王。年纪和我差不多吧。你能想象我坐上王座的模样吗？', `MaleText_loc5`='他的兒子，安杜因·烏瑞恩，當過一陣子國王。他和我年紀差不多。你能想像我當國王的樣子嗎?', `MaleText_loc7`='Su hijo, Anduin Wrynn, fue el rey durante un tiempo. También es de mi edad. ¿Te imaginas si yo fuera el rey?' WHERE `ID`=26476;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런데 말이야, 내가 안두인 임금님인 줄 착각하는 사람들도 많았어. 우리가 많이 닮았나 봐...', `MaleText_loc4`='有时人们会将我误认成国王陛下。大概是我们的容貌过于相似吧……', `MaleText_loc5`='人們以前會跑來找我，因為他們以為我是國王。我猜我們長的很像...', `MaleText_loc7`='La gente solía acercarse a mí pensando que era el rey. Creo que nos parecemos...' WHERE `ID`=26477;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 임금님이었다면 너 같은 말을 데리고 다녔을 거야. 난 절대 널 잃어버리지 않을 테고, 너도 날 절대 잃어버리지 않겠지.', `MaleText_loc4`='如果我当上了国王，我一定要找到一匹像你这般健壮漂亮的马儿。我会好好保护你，我相信你也会保护我的。', `MaleText_loc5`='假如我是國王，我會養一匹像你一樣的馬。我保證你不會走失，而且我相信你也永遠不會讓我迷路。', `MaleText_loc7`='Si yo fuera rey, tendría un caballo como tú. Me aseguraría de que no te perdieras y seguro que tú te preocuparías de que yo no me perdiera.' WHERE `ID`=26478;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 아마 둘도 없는 친구가 될 거야. 안두인 님도 나랑 좋은 친구가 될 게 틀림없어. 친구란 정말 소중한 거야.', `MaleText_loc4`='我们会成为好朋友的。我敢打赌我和安度因也会成为好朋友的。朋友是最宝贵的财富。', `MaleText_loc5`='我們可以當最要好的朋友。我打賭我和安杜因也可以成為最要好的朋友。朋友是很重要的。', `MaleText_loc7`='Seríamos mejores amigos. Apuesto a que Anduin y yo también seríamos mejores amigos. Los amigos son importantes.' WHERE `ID`=26479;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으윽! 네놈한테는 아무 말도 안 하겠다, 이 더러운 $r 녀석!', `MaleText_loc4`='呸！我什么都不会告诉你，肮脏的$r，！', `MaleText_loc5`='噢!我什麼都不會告訴你，污穢的$r!', `MaleText_loc7`='¡Ay! ¡No te diré NADA, $gsucio:sucia; $r!' WHERE `ID`=26480;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐... 잠깐! 알고 싶은 게 대체 뭔가?! 네놈이 $n|1이라는;라는; $c|1이라는;라는; 건 안다.', `MaleText_loc4`='等等……等等！你到底想知道什么啊？！我知道你是个名叫$n的$C。', `MaleText_loc5`='等...等等!你想要知道些什麼?!我知道你是那個名叫$n的$c。', `MaleText_loc7`='Espera... ¡ESPERA! ¿Qué quieres saber? Sé que eres $gel:la:c; $c $gllamado:llamada; $n.' WHERE `ID`=26481;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으윽... 안 돼! 우리가 아는 거라곤 너희가 우리 방어구와 무기에다 군마까지 훔쳐갔다는 것뿐이야!', `MaleText_loc4`='噢……不！我们知道是你偷了我们的盔甲、武器，还有马匹！', `MaleText_loc5`='噢...別這樣!我知道你一直在偷我們的裝備武器和馬匹!', `MaleText_loc7`='¡OH NO! ¡Sabemos que has estado robando nuestras armaduras, armas y caballos!' WHERE `ID`=26482;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 아는 건... 왜 우리에게 그 파멸의 역병이라는 게... 효과가 없는지... 너희가 모른다는 것뿐이야. 웨스트윈드 님께서 대수도원장님께 그 축복의 기도를 알려줬지. 부탁이니... 제발... 그만?!', `MaleText_loc4`='我们知道……你们无法理解……为什么我们……对所谓的病菌免疫。海军上将巴利·韦斯温似乎向高阶修士传授了什么祷言。啊啊，求你了……住手……好吗？！', `MaleText_loc5`='我懂...你不...清楚為什麼我們免疫...免疫於你所謂的荒疫。韋斯溫上將用某種方法把導言給了高階修士。我求你...別再來了...拜託?!', `MaleText_loc7`='Sabemos... que no sabéis... por qué somos inmunes... a lo que llaman el añublo. De algún modo, el gran almirante Viento Oeste entregó esa oración al sumo abad. ¡Os lo ruego... no más... por favor!' WHERE `ID`=26483;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으아아아아아아! 제발... 우리가... 아는 거라곤... 우리 중에... 우리처럼 분장한... 너희들 첩자가 있다는 사실이야! 그래... 내가 아는 건 그게 다야. 제발... 자비를... 그만!', `MaleText_loc4`='啊啊啊啊啊！求求你……我们……知道……有间谍……混进了……我们中间！我……我……我就知道这么多啦。求求你……发发慈悲吧……停手呀！', `MaleText_loc5`='啊啊啊啊!求求你...我們...知道你...派了間諜...打扮得...和我們一樣!這就是...我所有知道的。求求你...饒了我...不要!', `MaleText_loc7`='¡AHHHHHHHHH! ¡Por favor... sabemos... que tenéis... un espía... disfrazado como... uno de nosotros! Eso... es todo lo que sé. Por favor... ten piedad... ¡PARA!' WHERE `ID`=26484;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 말이 있는 곳으로 데려가 줄게. 친구랑 함께 지내본 지 오래됐지? 아마 너희도 좋은 친구가 될 수 있을 거야.', `MaleText_loc4`='我带你去找其他马儿吧。你呀，肯定是想和它们呆在一起啦。它们也会成为你的新朋友呀。', `MaleText_loc5`='我帶你去見其他馬匹。你大概錯過了其他的馬匹，牠們也能跟你成為好朋友的。', `MaleText_loc7`='Te llevaré junto a otros caballos, supongo que echas de menos estar con otros caballos. Pueden ser tus amigos también.' WHERE `ID`=26486;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방금 거 괜찮아 보이나?', `MaleText_loc4`='看上去还好吧？', `MaleText_loc5`='這樣看起來可以嗎?', `MaleText_loc7`='¿Eso tenía buena pinta?', `FemaleText_loc1`='방금 나 괜찮았어?', `FemaleText_loc4`='看上去还好吧？', `FemaleText_loc5`='這樣看起來可以嗎?', `FemaleText_loc7`='¿Eso tenía buena pinta?' WHERE `ID`=26487;
