UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좀 긴장돼서 그래. 미안해.', `MaleText_loc4`='我只是有些紧张。很抱歉。', `MaleText_loc5`='我只是緊張。抱歉。', `MaleText_loc7`='Solo estoy nervioso. Lo siento.', `FemaleText_loc1`='좀 긴장돼서 그래. 미안.', `FemaleText_loc4`='我只是有些紧张。很抱歉。', `FemaleText_loc5`='我只是緊張。抱歉。', `FemaleText_loc7`='Solo estoy nerviosa. Lo siento.' WHERE `ID`=26493;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 다른 사람들을 실망시키고 싶지 않다고.', `MaleText_loc4`='我只是不想再让别人失望了。', `MaleText_loc5`='我只是不想讓任何人失望。', `MaleText_loc7`='No quiero decepcionar a nadie.', `FemaleText_loc1`='난 다른 사람들을 실망시키기 싫어.', `FemaleText_loc4`='我只是不想再让别人失望了。', `FemaleText_loc5`='我只是不想讓任何人失望。', `FemaleText_loc7`='No quiero decepcionar a nadie.' WHERE `ID`=26494;
