UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제발 잠 좀 자게 해주지 않겠나?', `MaleText_loc4`='你还想不想让我睡觉啊？', `MaleText_loc5`='你不打算讓我睡覺是吧?', `MaleText_loc7`='No me vas a dejar dormir, ¿verdad?', `FemaleText_loc1`='제발 잠 좀 자게 해주지 않을래?', `FemaleText_loc4`='你还想不想让我睡觉啊？', `FemaleText_loc5`='你不打算讓我睡覺是吧?', `FemaleText_loc7`='No me vas a dejar dormir, ¿verdad?' WHERE `ID`=26497;
