UPDATE `locales_broadcast_text` SET `MaleText_loc1`='차라리 날... 죽여라.', `MaleText_loc4`='让一切……结束吧。', `MaleText_loc5`='求你...結束這一切。', `MaleText_loc7`='Solo... acaba con ello.' WHERE `ID`=26499;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좀 조용히 해줄 수 없겠나?', `MaleText_loc4`='你不能稍微安静一点吗？', `MaleText_loc5`='你可不可以試著安靜點?', `MaleText_loc7`='¿Podrías intentar hacer menos ruido?', `FemaleText_loc1`='좀 조용히 해주지 않을래?', `FemaleText_loc4`='你不能稍微安静一点吗？', `FemaleText_loc5`='你可不可以試著安靜點?', `FemaleText_loc7`='¿Podrías intentar hacer menos ruido?' WHERE `ID`=26500;
