UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대체 언제까지 그 짓을 할 작정이야?', `MaleText_loc4`='你打算一直这样是吧？', `MaleText_loc5`='這種事你要一直持續做下去嗎?', `MaleText_loc7`='¿Vas a seguir haciendo esto mucho tiempo más?', `FemaleText_loc1`='대체 언제까지 그 짓을 할 작정이야?', `FemaleText_loc4`='你打算一直这样是吧？', `FemaleText_loc5`='這種事你要一直持續做下去嗎?', `FemaleText_loc7`='¿Vas a seguir haciendo esto mucho tiempo más?' WHERE `ID`=26502;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경쟁의 정신은 2년에 한 번씩 뜨겁게 불타오릅니다... 그리고 올해가 바로 그 해입니다! 얼라이언스나 호드 모두 경쟁의 정신을 기리고자 이 휘장을 차고 전장에 참여합니다. 그러고는 적을 모두 물리치고 경쟁의 정신으로부터 특별한 선물을 받으려고 온 힘을 다해 싸운답니다.', `MaleText_loc4`='每两年竞争之魂就会变得特别狂躁……喏，就是现在！我们要穿上这件战袍进入战场并击败敌人，以此获得竞争之魂的青睐。', `MaleText_loc5`='每隔兩年競賽之靈都會變得特別激動熱情...而現在正是這個時候!我們穿著這身外袍前往戰場榮耀它們，打敗我們的敵人然後贏得它們的眷顧。', `MaleText_loc7`='Cada dos años los espíritus de competición se vuelven especialmente fervientes... ¡y ahora es ese momento! Llevamos este tabardo en los campos de batalla para honrarlos e intentamos derrotar a nuestros enemigos y ganar el favor de los espíritus.', `FemaleText_loc1`='경쟁의 정신은 2년에 한 번씩 뜨겁게 불타오르지요... 그리고 올해가 바로 그 해랍니다! 얼라이언스나 호드 모두 경쟁의 정신을 기리고자 이 휘장을 차고 전장에 참여해요. 그러고는 적을 모두 물리치고 경쟁의 정신으로부터 특별한 선물을 받으려고 온 힘을 다해 싸우지요.', `FemaleText_loc4`='每两年竞争之魂就会变得特别狂躁……喏，就是现在！我们要穿上这件战袍进入战场并击败敌人，以此获得竞争之魂的青睐。', `FemaleText_loc5`='每隔兩年競賽之靈都會變得特別激動熱情...而現在正是這個時候!我們穿著這身外袍前往戰場榮耀它們，打敗我們的敵人然後贏得它們的眷顧。', `FemaleText_loc7`='Cada dos años los espíritus de competición se vuelven especialmente fervientes... ¡y ahora es ese momento! Llevamos este tabardo en los campos de batalla para honrarlos e intentamos derrotar a nuestros enemigos y ganar el favor de los espíritus.' WHERE `ID`=26503;
