UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 바로 고문이야!', `MaleText_loc4`='这简直是非人的折磨！', `MaleText_loc5`='這是酷刑!', `MaleText_loc7`='¡ESTO ES TORTURA!' WHERE `ID`=26505;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈은... 내게서 아무것도... 알아내지 못할 거다!', `MaleText_loc4`='你别想……从我这里……得到……任何东西！', `MaleText_loc5`='你不會再...從我...口中...問出任何事!', `MaleText_loc7`='¡No me... sacarás... nada más!' WHERE `ID`=26506;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우와아아아아아아아!', `MaleText_loc4`='啊啊啊啊啊啊啊啊啊啊！', `MaleText_loc5`='喔喔喔喔喔!', `MaleText_loc7`='¡AAAAYYYYYYYY!' WHERE `ID`=26507;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경쟁의 휘장은 어떻게 구할 수 있습니까?', `MaleText_loc4`='我要怎样才能获得竞争者的战袍？', `MaleText_loc5`='我要如何獲得一件競賽者外袍?', `MaleText_loc7`='¿Cómo puedo conseguir un tabardo de competidor?', `FemaleText_loc1`='경쟁의 휘장은 어떻게 구할 수 있나요?', `FemaleText_loc4`='我要怎样才能获得竞争者的战袍？', `FemaleText_loc5`='我要如何獲得一件競賽者外袍?', `FemaleText_loc7`='¿Cómo puedo conseguir un tabardo de competidor?' WHERE `ID`=26508;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경쟁의 정신은 어떻게 얻을 수 있습니까?', `MaleText_loc4`='我要怎样才能获得竞争之魂的青睐？', `MaleText_loc5`='我要如何獲得競賽之靈的眷顧?', `MaleText_loc7`='¿Cómo puedo ganar el favor de un espíritu de competición?', `FemaleText_loc1`='경쟁의 정신은 어떻게 얻을 수 있나요?', `FemaleText_loc4`='我要怎样才能获得竞争之魂的青睐？', `FemaleText_loc5`='我要如何獲得競賽之靈的眷顧?', `FemaleText_loc7`='¿Cómo puedo ganar el favor de un espíritu de competición?' WHERE `ID`=26509;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 전장에서든 우리 적과 맞서 싸우면 된답니다. 지든 이기든 상관없이 전투에 끝까지 참여했다면, 경쟁의 휘장을 우편으로 받으실 겁니다.', `MaleText_loc4`='你只需要进入任意战场英勇作战就行了。无论胜负，只要你坚持到最后一刻，就能收到我们邮寄给你的竞争者的战袍。', `MaleText_loc5`='你必須在戰場上面對我們的對手。不論是贏或輸，如果你堅持到戰鬥的最後，你就會收到郵寄給你的競賽者外袍。', `MaleText_loc7`='Solo tienes que enfrentarte a nuestros rivales en los campos de batalla. Si te quedas durante toda la batalla, aunque ganes o pierdas, se te enviará un tabardo de competidor por correo.', `FemaleText_loc1`='어떤 전장에서든 우리 적과 맞서 싸우면 되지요. 지든 이기든 상관없이 전투에 끝까지 참여했다면, 경쟁의 휘장을 우편으로 받으실 거예요.', `FemaleText_loc4`='你只需要进入任意战场英勇作战就行了。无论胜负，只要你坚持到最后一刻，就能收到我们邮寄给你的竞争者的战袍。', `FemaleText_loc5`='你必須在戰場上面對我們的對手。不論是贏或輸，如果你堅持到戰鬥的最後，你就會收到郵寄給你的競賽者外袍。', `FemaleText_loc7`='Solo tienes que enfrentarte a nuestros rivales en los campos de batalla. Si te quedas durante toda la batalla, aunque ganes o pierdas, se te enviará un tabardo de competidor por correo.' WHERE `ID`=26510;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 전장이든 가셔서 적을 물리치고 승리를 거두셔야 합니다. 우편으로 황금 메달을 받을 기회는 승리하신 분께만 드립니다.', `MaleText_loc4`='你必须进入任意战场并击败敌人。获胜之后，你就有可能收到我们邮寄给你的金色勋章。', `MaleText_loc5`='你必須在任何一個戰場上擊敗我們的對手。每一場勝利都會讓你有機會收到黃金勳章。', `MaleText_loc7`='Tienes que derrotar a nuestros rivales en cualquier campo de batalla. Con cada victoria, es posible que se te envíe un medallón de oro por correo.', `FemaleText_loc1`='어떤 전장이든 가셔서 적을 물리치고 승리를 거두셔야 해요. 우편으로 황금 메달을 받을 기회는 승리하신 분께만 드린답니다.', `FemaleText_loc4`='你必须进入任意战场并击败敌人。获胜之后，你就有可能收到我们邮寄给你的金色勋章。', `FemaleText_loc5`='你必須在任何一個戰場上擊敗我們的對手。每一場勝利都會讓你有機會收到黃金勳章。', `FemaleText_loc7`='Tienes que derrotar a nuestros rivales en cualquier campo de batalla. Con cada victoria, es posible que se te envíe un medallón de oro por correo.' WHERE `ID`=26511;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경쟁의 정신이라고 들어 보셨습니까?$B$B2년에 한 번씩 이 현세로 내려오지요. 그때는 얼라이언스나 호드 모두 경쟁의 휘장을 차고 전장에 참여하여 경쟁의 정신을 기립니다. 서로 싸우면서 경쟁의 정신으로부터 특별한 선물을 받고자 애쓰면서 말입니다.$B$B그렇게 세상이 험하게 돌아갈 때도 기념품을 잔뜩 비축해 두었답니다. 말만 잘한다면, 하나쯤 줄 수도 있는데 말이지요...', `MaleText_loc4`='你知道竞争之魂吗？$B$B每两年它们就会接近我们的世界。在此期间，联盟或是部落的成员都可以穿着竞争者的战袍进入战场，以此赢得竞争之魂的青睐。$B$B我收集了一些相关的纪念品。如果你知道那段密语的话，我或许可以送你一些……', `MaleText_loc5`='你知道競賽之靈，對吧?$B$B每隔兩年，它們就會靠近凡人的世界。在這段期間，聯盟與部落的成員都會穿著競賽者外袍進入戰場來榮耀它們，試圖擊敗敵人並且贏得眷顧。$B$B我倒是從這類的動盪時期累積了不少紀念品。你要是能學會一些適當的措辭，我倒可以考慮割捨一些...', `MaleText_loc7`='Has oído hablar de los espíritus de competición, ¿verdad?$B$BCada dos años se acercan al reino de los mortales. En esos momentos, miembros tanto de la Alianza como de la Horda llevan tabardos de competidor en los campos de batalla para honrar a los espíritus e intentan derrotarse unos a otros y ganar el favor de los espíritus.$B$BYo acumulo recuerdos para esos momentos turbulentos. Si conoces la palabra adecuada, puede que me convenzas para que me deshaga de uno...', `FemaleText_loc1`='경쟁의 정신이라고 들어 보셨나요?$B$B2년에 한 번씩 이 현세로 내려오거든요. 그때는 얼라이언스나 호드 모두 경쟁의 휘장을 차고 전장에 참여하여 경쟁의 정신을 기리지요. 서로 싸우면서 경쟁의 정신으로부터 특별한 선물을 받고자 애쓰면서 말이지요.$B$B그렇게 세상이 험하게 돌아갈 때도 기념품을 잔뜩 비축해 두었다고요. 말만 잘한다면, 하나쯤 줄 수도 있는데 말이에요...', `FemaleText_loc4`='你知道竞争之魂吗？$B$B每两年它们就会接近我们的世界。在此期间，联盟或是部落的成员都可以穿着竞争者的战袍进入战场，以此赢得竞争之魂的青睐。$B$B我收集了一些相关的纪念品。如果你知道那段密语的话，我或许可以送你一些……', `FemaleText_loc5`='你知道競賽之靈，對吧?$B$B每隔兩年，它們就會靠近凡人的世界。在這段期間，聯盟與部落的成員都會穿著競賽者外袍進入戰場來榮耀它們，試圖擊敗敵人並且贏得眷顧。$B$B我倒是從這類的動盪時期累積了不少紀念品。你要是能學會一些適當的措辭，我倒可以考慮割捨一些...', `FemaleText_loc7`='Has oído hablar de los espíritus de competición, ¿verdad?$B$BCada dos años se acercan al reino de los mortales. En esos momentos, miembros tanto de la Alianza como de la Horda llevan tabardos de competidor en los campos de batalla para honrar a los espíritus e intentan derrotarse unos a otros y ganar el favor de los espíritus.$B$BYo acumulo recuerdos para esos momentos turbulentos. Si conoces la palabra adecuada, puede que me convenzas para que me deshaga de uno...' WHERE `ID`=26512;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비밀 암호를 입력하고 제 경쟁의 기념품을 받고 싶습니다.', `MaleText_loc4`='我要输入神秘兑换码，领取竞争者的纪念品。', `MaleText_loc5`='我想要輸入驗證碼以領取我的競賽者紀念品。', `MaleText_loc7`='Me gustaría introducir el código secreto para recibir mi recuerdo de competidor.', `FemaleText_loc1`='비밀 암호를 입력하고 제 경쟁의 기념품을 받고 싶어요.', `FemaleText_loc4`='我要输入神秘兑换码，领取竞争者的纪念品。', `FemaleText_loc5`='我想要輸入驗證碼以領取我的競賽者紀念品。', `FemaleText_loc7`='Me gustaría introducir el código secreto para recibir mi recuerdo de competidor.' WHERE `ID`=26513;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일어나서 싸워라! 살아있는 것들을 죽여!', `MaleText_loc4`='Rise and fight! Kill the living! [PH]', `MaleText_loc5`='起來作戰吧!殺死活物![PH]', `MaleText_loc7`='Rise and fight! Kill the living! [PH]' WHERE `ID`=26514;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자들을 처치해야만 한다!', `MaleText_loc4`='We must kill these intruders! [PH]', `MaleText_loc5`='我們一定要把入侵者殺光![PH]', `MaleText_loc7`='We must kill these intruders! [PH]' WHERE `ID`=26515;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나의 전사여, 가라! 살아있는 것들을 처치해라!', `MaleText_loc4`='Go my warrior! Slay the living! [PH]', `MaleText_loc5`='去吧我的戰士!殺死活物![PH]', `MaleText_loc7`='Go my warrior! Slay the living! [PH]' WHERE `ID`=26516;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 귀여운 아가야, 가서 저 녀석들을 죽여 만찬을 열어라!', `MaleText_loc4`='Go forth my little pet, kill these mongrels and feast on their flesh! [PH]', `MaleText_loc5`='前進，我的小寵物，殺死這些雜種狗，享用他們的血肉![PH]', `MaleText_loc7`='Go forth my little pet, kill these mongrels and feast on their flesh! [PH]' WHERE `ID`=26517;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 얼어붙은 황무지에서는 죽음이 어떤 결과를 가져오는지 우리는 금방 배웠답니다. 리치 왕의 힘은 노스렌드 전역에 뻗쳐 있고, 심지어 땅속까지도 영향을 미쳐요! 놈은 죽은 우리 동료를 우리의 적으로 만들어요.$B$B하늘에서는 되살아난 그리핀 기수가 원한 서린 폭풍망치를 던져대고, 땅에서는 걸어다니는 시체가 우리를 공격해 오고 있지요.', `FemaleText_loc4`='$n，很快我们就明白了死亡在这片冰封之地意味着什么。诺森德弥漫着巫妖王的邪恶力量，这种力量甚至渗透每一寸土地！他唤醒了那些在战斗牺牲的将士，命令他们与我们为敌。$B$B复活的狮鹫骑士随同地面的亡灵大军对我们发动了枪林弹雨般的猛烈攻击。', `FemaleText_loc5`='我們正在這嚴寒的荒原上學習死亡的代價，$n。巫妖王的力量擴展到北裂境的每一吋土地，甚至滲透進土地裡!他利用我們死去的將士來對付我們。$B$B獅鷲騎士從空中擲下復仇的風暴戰槌，而活死人在地面上襲擊我們。', `FemaleText_loc7`='En este baldío helado, estamos aprendiendo rápidamente el significado de la muerte, $n. El poder del Rey Exánime se extiende por cada centímetro de Rasganorte, penetrando en la propia tierra. Él vuelve a nuestros caídos contra nosotros.$B$BDesde el cielo, jinetes de grifos resucitados nos atacan con sus vengativos martillos de tormenta mientras los muertos andantes nos atacan en tierra.' WHERE `ID`=26518;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크레나 님이 내 능력을 의심하고 있는 게 분명하네. 우리 정예병들이 얼라이언스와 그들의 덫사냥꾼 동맹을 상대하거나 트롤들을 쳐부수는 동안, 난 성가신 용약탈 브리쿨들을 쓸어버리라는 명령을 받았네.$B$B우리가 힘을 합친다면 정복자님께 우리 실력을 증명해 보일 수 있을 걸세.', `MaleText_loc4`='克雷娜对我的能力颇有质疑。她派出最精锐的将士对付联盟以及他们的猎户盟友，让他们执行针对冰霜巨魔的大规模作战计划，却让我与这帮粗俗的掠龙维库人周旋。$B$B或许我们应该联手，共同改变我们在征服者眼中的形象。', `MaleText_loc5`='克蓮娜一定很懷疑我的能力。當我們的菁英戰士出去面對聯盟與他們的陷捕者盟友，或者食人妖造成的大混亂，我被派來清理這些討厭的維酷掠龍者。$B$B也許如果我們結合我們的努力，就可以雙雙在征服者眼中證明自己的實力。', `MaleText_loc7`='Supongo que Krenna duda de mis habilidades. Mientras nuestros guerreros de élite caminan para enfrentarse a la Alianza y sus aliados tramperos, o se dedican a causar estragos entre los trols, a mí me han ordenado eliminar a esos molestos vrykuls Desuelladragones.$B$BQuizá si unimos nuestros esfuerzos, podamos mostrarle lo que valemos a la conquistadora.' WHERE `ID`=26519;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호박빛소나무 오두막에 온 것을 환영합니다, $c님.', `MaleText_loc4`='欢迎来到琥珀松木营地，$C。', `MaleText_loc5`='歡迎來到琥珀松小屋，$c。', `MaleText_loc7`='$gBienvenido:Bienvenida; al Refugio Pino Ámbar, $c.' WHERE `ID`=26520;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='넌 참 착한 애야. 자, 이 말을 마구간으로 데려가 주렴.', `FemaleText_loc4`='你真贴心。喏，将这匹马牵到你的马厩去吧。', `FemaleText_loc5`='你真是個好孩子。來，把這匹馬牽去你的獸欄。', `FemaleText_loc7`='Eres un chico muy dulce. Toma, lleva este caballo a tu establo.' WHERE `ID`=26521;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 사람들 때문에 내가 많이 바쁘거든. 이 말을 너희 마구간으로 좀 데려가 줘.', `FemaleText_loc4`='我整天都忙得不可开交。来，将这匹马牵到你的马厩去吧。', `FemaleText_loc5`='這些人讓我好忙。把這匹馬牽去你的獸欄。', `FemaleText_loc7`='Toda esta gente me está manteniendo ocupada. Lleva este caballo a tus establos.' WHERE `ID`=26522;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그럼 부탁해. 잘 돌봐줘야 한다.', `FemaleText_loc4`='这是一等一的好马呀。你要好好照顾它。', `FemaleText_loc5`='這裡有匹好馬給你。好好照顧他。', `FemaleText_loc7`='Aquí tienes uno bueno. Cuídalo bien.' WHERE `ID`=26523;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자, 이 말을 마구간으로 데려가 줘. 이름은 로날드야. 인사하렴.', `FemaleText_loc4`='来，将这匹马牵到你的马厩去吧。替我向罗纳德问个好。', `FemaleText_loc5`='來，把這匹馬牽去你的獸欄。向羅奈德問好。', `FemaleText_loc7`='Toma, lleva a este caballo a tu establo. Dile "hola" a Ronald.' WHERE `ID`=26524;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상급 서기관 바리가는 어디에 붙잡혀 있습니까?', `MaleText_loc4`='首席抄写员巴里加被关在哪儿？', `MaleText_loc5`='資深書記貝瑞加被困在哪裡?', `MaleText_loc7`='¿Dónde mantienen cautivo al escribano jefe Barriga?', `FemaleText_loc1`='상급 서기관 바리가는 어디에 붙잡혀 있습니까?', `FemaleText_loc4`='首席抄写员巴里加被关在哪儿？', `FemaleText_loc5`='資深書記貝瑞加被困在哪裡?', `FemaleText_loc7`='¿Dónde mantienen cautivo al escribano jefe Barriga?' WHERE `ID`=26525;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제재소 근처에 있는 철창에 같힌 것 같네.', `MaleText_loc4`='他似乎被关在伐木场附近的某个牢笼。', `MaleText_loc5`='我想他們把他關在伐木廠附近的籠子裡。', `MaleText_loc7`='Creo que lo han enjaulado cerca del aserradero.', `FemaleText_loc1`='제재소 근처에 있는 철창에 같힌 것 같네.', `FemaleText_loc4`='他似乎被关在伐木场附近的某个牢笼。', `FemaleText_loc5`='我想他們把他關在伐木廠附近的籠子裡。', `FemaleText_loc7`='Creo que lo han enjaulado cerca del aserradero.' WHERE `ID`=26526;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들이 기술자 버크를 어디로 데려갔는지 봤습니까?', `MaleText_loc4`='你知道他们把卫生设备工程师布尔克带到哪儿去了吗？', `MaleText_loc5`='你知道他們把工程師波奇帶去哪裡了嗎?', `MaleText_loc7`='¿Viste adónde se llevaron al ingeniero sanitario Burke?', `FemaleText_loc1`='그들이 기술자 버크를 어디로 데려갔는지 보셨나요?', `FemaleText_loc4`='你知道他们把卫生设备工程师布尔克带到哪儿去了吗？', `FemaleText_loc5`='你知道他們把工程師波奇帶去哪裡了嗎?', `FemaleText_loc7`='¿Viste adónde se llevaron al ingeniero sanitario Burke?' WHERE `ID`=26527;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 전장이든 가셔서 적을 물리치고 승리를 거두시면 됩니다. 우편으로 황금 메달을 받을 기회는 승리하신 분께만 드립니다.', `MaleText_loc4`='你必须进入任意战场并击败敌人。获胜之后，你就有可能收到我们邮寄给你的金色勋章。', `MaleText_loc5`='你必須在任何一個戰場上擊敗你的對手。每一場勝利都會讓你有機會收到黃金勳章。', `MaleText_loc7`='Tienes que derrotar a nuestros rivales en cualquier campo de batalla. Con cada victoria, es posible que se te envíe un medallón de oro por correo.', `FemaleText_loc1`='어떤 전장이든 가셔서 적을 물리치고 승리를 거두시면 되지요. 우편으로 황금 메달을 받을 기회는 승리하신 분께만 드린답니다.', `FemaleText_loc4`='你必须进入任意战场并击败敌人。获胜之后，你就有可能收到我们邮寄给你的金色勋章。', `FemaleText_loc5`='你必須在任何一個戰場上擊敗你的對手。每一場勝利都會讓你有機會收到黃金勳章。', `FemaleText_loc7`='Tienes que derrotar a nuestros rivales en cualquier campo de batalla. Con cada victoria, es posible que se te envíe un medallón de oro por correo.' WHERE `ID`=26528;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수도원 남쪽에 있는 것 같네.', `MaleText_loc4`='他应该被关押在修道院的南边。', `MaleText_loc5`='我想他就在修道院的南面。', `MaleText_loc7`='Creo que está en el lateral sur de la abadía.', `FemaleText_loc1`='수도원 남쪽에 있는 것 같네.', `FemaleText_loc4`='他应该被关押在修道院的南边。', `FemaleText_loc5`='我想他就在修道院的南面。', `FemaleText_loc7`='Creo que está en el lateral sur de la abadía.' WHERE `ID`=26529;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 전장에서든 우리 적과 맞서 싸우면 된답니다. 지든 이기든 상관없이 전투에 끝까지 참여했다면, 경쟁의 휘장을 우편으로 받으실 겁니다.', `MaleText_loc4`='你只需要进入任意战场英勇作战就行了。无论胜负，只要你坚持到最后一刻，就能收到我们邮寄给你的竞争者的战袍。', `MaleText_loc5`='你必須在戰場上面對你的對手。不論是贏或輸，如果你堅持到戰鬥的最後，你就會收到郵寄給你的競賽者外袍。', `MaleText_loc7`='Solo tienes que enfrentarte a nuestros rivales en los campos de batalla. Si te quedas durante toda la batalla, aunque ganes o pierdas, se te enviará un tabardo de competidor por correo.', `FemaleText_loc1`='어떤 전장에서든 우리 적과 맞서 싸우면 되지요. 지든 이기든 상관없이 전투에 끝까지 참여했다면, 경쟁의 휘장을 우편으로 받으실 거예요.', `FemaleText_loc4`='你只需要进入任意战场英勇作战就行了。无论胜负，只要你坚持到最后一刻，就能收到我们邮寄给你的竞争者的战袍。', `FemaleText_loc5`='你必須在戰場上面對你的對手。不論是贏或輸，如果你堅持到戰鬥的最後，你就會收到郵寄給你的競賽者外袍。', `FemaleText_loc7`='Solo tienes que enfrentarte a nuestros rivales en los campos de batalla. Si te quedas durante toda la batalla, aunque ganes o pierdas, se te enviará un tabardo de competidor por correo.' WHERE `ID`=26530;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경쟁의 정신은 2년에 한 번씩 뜨겁게 불타오릅니다... 그리고 올해가 바로 그 해입니다! 얼라이언스나 호드 모두 경쟁의 정신을 기리고자 이 휘장을 차고 전장에 참여합니다. 그러고는 적을 모두 물리치고 경쟁의 정신으로부터 특별한 선물을 받으려 온 힘을 다해 싸웁니다.', `MaleText_loc4`='每两年竞争之魂就会变得特别狂躁……喏，就是现在！我们要穿上这件战袍进入战场并击败敌人，以此获得竞争之魂的青睐。', `MaleText_loc5`='每隔兩年競賽之靈都會變得特別激動熱情...而現在正是這個時候!我們穿著這身外袍前往戰場榮耀它們，打敗所有的敵人然後贏得它們的眷顧。', `MaleText_loc7`='Cada dos años los espíritus de competición se vuelven especialmente fervientes... ¡y ahora es ese momento! Tanto la Alianza como la Horda llevamos este tabardo en los campos de batalla para honrarlos e intentamos derrotar a nuestros enemigos y ganar el favor de los espíritus.', `FemaleText_loc1`='경쟁의 정신은 2년에 한 번씩 뜨겁게 불타오르지요... 그리고 올해가 바로 그 해랍니다! 얼라이언스나 호드 모두 경쟁의 정신을 기리고자 이 휘장을 차고 전장에 참여해요. 그러고는 적을 모두 물리치고 경쟁의 정신으로부터 특별한 선물을 받으려 온 힘을 다해 싸우지요.', `FemaleText_loc4`='每两年竞争之魂就会变得特别狂躁……喏，就是现在！我们要穿上这件战袍进入战场并击败敌人，以此获得竞争之魂的青睐。', `FemaleText_loc5`='每隔兩年競賽之靈都會變得特別激動熱情...而現在正是這個時候!我們穿著這身外袍前往戰場榮耀它們，打敗所有的敵人然後贏得它們的眷顧。', `FemaleText_loc7`='Cada dos años los espíritus de competición se vuelven especialmente fervientes... ¡y ahora es ese momento! Tanto la Alianza como la Horda llevamos este tabardo en los campos de batalla para honrarlos e intentamos derrotar a nuestros enemigos y ganar el favor de los espíritus.' WHERE `ID`=26531;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음경비병 슈나이더를 어디에 가두었는지 압니까?', `MaleText_loc4`='知道他们把亡灵卫兵斯克尼德关在哪儿了吗？', `MaleText_loc5`='知道他們把亡靈衛兵施耐德關在哪嗎?', `MaleText_loc7`='¿Alguna idea de dónde tienen al guardia de la Muerte Schneider?', `FemaleText_loc1`='그들이 죽음경비병 슈나이더를 어디에 가두었는지 아십니까?', `FemaleText_loc4`='知道他们把亡灵卫兵斯克尼德关在哪儿了吗？', `FemaleText_loc5`='知道他們把亡靈衛兵施耐德關在哪嗎?', `FemaleText_loc7`='¿Alguna idea de dónde tienen al guardia de la Muerte Schneider?' WHERE `ID`=26532;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='교수대 근처에 잡아두고 있는 것 같네.', `MaleText_loc4`='她应该被绑在绞刑架下。', `MaleText_loc5`='我想他們把她關在絞刑架附近。', `MaleText_loc7`='Creo que la tienen cerca de la horca.', `FemaleText_loc1`='교수대 근처에 잡아두고 있는 것 같네.', `FemaleText_loc4`='她应该被绑在绞刑架下。', `FemaleText_loc5`='我想他們把她關在絞刑架附近。', `FemaleText_loc7`='Creo que la tienen cerca de la horca.' WHERE `ID`=26533;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장관 아마이가 어디에 갇혀 있는지 알려줄 수 있습니까?', `MaleText_loc4`='你能告诉我他们把司法官亚麦关在哪里了吗？', `MaleText_loc5`='你能告訴我他們把大法官亞邁關在哪嗎?', `MaleText_loc7`='¿Puedes decirme dónde tienen enjaulado al canciller Amai?', `FemaleText_loc1`='장관 아마이가 어디에 갇혀 있는지 알려줄 수 있습니까?', `FemaleText_loc4`='你能告诉我他们把司法官亚麦关在哪里了吗？', `FemaleText_loc5`='你能告訴我他們把大法官亞邁關在哪嗎?', `FemaleText_loc7`='¿Puedes decirme dónde tienen enjaulado al canciller Amai?' WHERE `ID`=26534;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수도원 북쪽의 궁술 표적 근처로 데려가는 것을 본 것 같군.', `MaleText_loc4`='我看见他被带往修道院北边了，就在箭靶附近。', `MaleText_loc5`='我看到他們把他帶去修道院的北邊，靠近弓箭靶的地方。', `MaleText_loc7`='Creo que los vi llevarlo hacia la parte norte de la abadía, cerca de los objetivos de tiro con arco.', `FemaleText_loc1`='수도원 북쪽의 궁술 표적 근처로 데려가는 것을 본 것 같군.', `FemaleText_loc4`='我看见他被带往修道院北边了，就在箭靶附近。', `FemaleText_loc5`='我看到他們把他帶去修道院的北邊，靠近弓箭靶的地方。', `FemaleText_loc7`='Creo que los vi llevarlo hacia la parte norte de la abadía, cerca de los objetivos de tiro con arco.' WHERE `ID`=26535;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 둥지로 도망갑니다...', `FemaleText_loc4`='%s迅速窜回了自己的洞穴……', `FemaleText_loc5`='%s逃回到它的巢穴中...', `FemaleText_loc7`='%s huye de vuelta a su guarida...' WHERE `ID`=26536;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지원군! 지원군이 필요하다!', `MaleText_loc4`='增援！我们需要增援！', `MaleText_loc5`='支援!我們需要支援!', `MaleText_loc7`='¡Apoyo! ¡Necesitamos apoyo!' WHERE `ID`=26537;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와줘! 저들은 수가 너무 많다!', `MaleText_loc4`='帮帮忙啊！我抗不住了！', `MaleText_loc5`='幫幫我，老兄!他們的數量太多啦!', `MaleText_loc7`='¡Ayuda, tron! ¡Hay demasiados!' WHERE `ID`=26538;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신, 정말 아무것도 모르는 거군? 덫사냥꾼? 그들은 인간이 아니라오... 어서 여기서 나가야 하오! 어서, 이리 오시오!', `MaleText_loc4`='你不知道？猎户？他们已经不是人类了……我们必须离开这里！快走！', `MaleText_loc5`='你不曉得，對吧?陷捕者?他們不是人類...我們得離開這裡!快來!', `MaleText_loc7`='No tienes ni idea, ¿verdad? ¿Los tramperos? No son humanos... ¡Tenemos que salir de aquí! ¡Ven, deprisa!' WHERE `ID`=26539;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='듀칼의 말을 타시오. 그도 지금은 놈들과 한 패거리요!', `MaleText_loc4`='牵走杜卡尔的马吧，他已经彻底沦陷了！', `MaleText_loc5`='騎杜卡的馬，他已經變成他們的一員了!', `MaleText_loc7`='Coge el caballo de Ducal, ¡ahora es uno de ellos!' WHERE `ID`=26540;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 무슨 일이 벌어지는 거지요?', `MaleText_loc4`='这里发生了什么事，长官？', `MaleText_loc5`='這裡發生了什麼事，中士?', `MaleText_loc7`='¿Qué está pasando aquí, sargento?', `FemaleText_loc1`='지금 무슨 일이 벌어지는 거지요?', `FemaleText_loc4`='这里发生了什么事，长官？', `FemaleText_loc5`='這裡發生了什麼事，中士?', `FemaleText_loc7`='¿Qué está pasando aquí, sargento?' WHERE `ID`=26541;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나도 모르겠습니다. 말썽이 일어나지 않게 하려면 둘 다 없애는 게 좋겠군요!', `MaleText_loc4`='我不知道。为了安全起见，最好将他们统统杀掉！', `MaleText_loc5`='我不知道。把他們都殺了最安全!', `MaleText_loc7`='No sé. ¡Mejor los matamos a los dos para estar seguros!', `FemaleText_loc1`='나도 모르겠습니다. 말썽이 일어나지 않게 하려면 둘 다 없애는 게 좋겠군요!', `FemaleText_loc4`='我不知道。为了安全起见，最好将他们统统杀掉！', `FemaleText_loc5`='我不知道。把他們都殺了最安全!', `FemaleText_loc7`='No sé. ¡Mejor los matamos a los dos para estar seguros!' WHERE `ID`=26542;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와주세요! 도와주세요! 이 $g남자:여자;가 내 모습을 훔쳐갔어요!!', `MaleText_loc4`='帮帮我！帮帮我！这家伙偷走了我的影像！', `MaleText_loc5`='救命!快來幫忙!這個$g男人:女人;偷了我的影像!', `MaleText_loc7`='¡SOCORRO! ¡SOCORRO! ¡$gESTE HOMBRE:ESTA MUJER; ME HA ROBADO LA IMAGEN!', `FemaleText_loc1`='도와주세요! 도와주세요! 이 $g남자:여자;가 내 모습을 훔쳐갔어요!', `FemaleText_loc4`='帮帮我！帮帮我！这家伙偷走了我的影像！', `FemaleText_loc5`='救命!快來幫忙!這個$g男人:女人;偷了我的影像!', `FemaleText_loc7`='¡SOCORRO! ¡SOCORRO! ¡$gESTE HOMBRE:ESTA MUJER; ME HA ROBADO LA IMAGEN!' WHERE `ID`=26543;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 왜 왔는지 안다. 저 평원의 멍청한 마그나타우르 하나가 문제를 일으켜서 용을 끌어들이고 만 게지. 그래, 용족의 앞잡이 노릇이 맘에 드느냐?', `MaleText_loc4`='我知道你为什么会来这里——平原上那些愚蠢的猛犸人多管闲事，竟然胆敢与龙族交战。当他们的走狗很有趣吗？', `MaleText_loc5`='我知道你為何而來。有個愚蠢的猛瑪象人在製造混亂，而且還設法牽扯龍族涉入其中。你喜歡像條狗一樣地服侍牠們嗎?', `MaleText_loc7`='Sé por qué has venido: uno de estos estúpidos magnatauros de las llanuras se entrometió y consiguió involucrar a los dragones. ¿Disfrutas sirviéndoles como un perro?', `FemaleText_loc1`='네가 왜 왔는지 안다. 저 평원의 멍청한 마그나타우르 하나가 문제를 일으켜서 용을 끌어들이고 만 게지. 그래, 용족의 앞잡이 노릇이 맘에 드느냐?', `FemaleText_loc4`='我知道你为什么会来这里——平原上那些愚蠢的猛犸人多管闲事，竟然胆敢与龙族交战。当他们的走狗很有趣吗？', `FemaleText_loc5`='我知道你為何而來。有個愚蠢的猛瑪象人在製造混亂，而且還設法牽扯龍族涉入其中。你喜歡像條狗一樣地服侍牠們嗎?', `FemaleText_loc7`='Sé por qué has venido: uno de estos estúpidos magnatauros de las llanuras se entrometió y consiguió involucrar a los dragones. ¿Disfrutas sirviéndoles como un perro?' WHERE `ID`=26544;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='광산이 놈들의 손에 넘어갔네. 방어 부대는 궤멸당했고, 광부들은 스컬지 괴물이 되어버렸어!', `MaleText_loc4`='矿洞已经失守。所有的卫兵都被杀害了，死去的矿工还被复活，成为了天灾怪物！', `MaleText_loc5`='我們丟了礦坑。所有的防守者都死了，而礦工都被復活成畸形的天譴軍!', `MaleText_loc7`='Hemos perdido la mina. ¡Todos nuestros defensores han muerto y los mineros han resucitado como aberraciones de la Plaga!' WHERE `ID`=26545;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불꽃인도자가 당신을 떨어트리려 합니다. 볼드룬으로 돌아가야 합니다!', `MaleText_loc4`='烈焰使者试图将你掀下去。返回沃德伦！', `MaleText_loc5`='烈焰使者試圖把你甩下他的背。返回沃德盧恩!', `MaleText_loc7`='Clamallamas intenta tirarte de su lomo. ¡Regresa a Runavold!' WHERE `ID`=26546;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청한 심부름꾼 같으니... 내 일을 방해했으니 죽어줘야겠다!', `MaleText_loc4`='愚蠢的$g小子:小丫头;……你竟然敢打扰我的工作，受死吧！', `MaleText_loc5`='愚蠢的跑腿$G小鬼:小女孩;...我要因為你打斷我工作而殺了你!', `MaleText_loc7`='$GInsensato chico:Insensata chica; de los recados... ¡morirás por interrumpir mi trabajo!' WHERE `ID`=26547;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상황은 그보다도 더 나빠지고 있답니다, 오랜 친구여. 계산해 봤는데 적당한 재료로 흉벽을 보수하지 않으면 이 성채를 보호하는 성벽은 앞으로 12시간 안에 무너질 거예요.', `MaleText_loc4`='朋友，情况越来越糟糕了。根据我的计算，如果没有足够的材料维修防御墙的话，那么保护这座要塞的城墙就会在12小时内坍塌。', `MaleText_loc5`='情況越來越糟，老友。根據我的計算，如果沒有適當的材料可以修理我們的胸牆，這座要塞的城牆會在十二個小時內垮陷。', `MaleText_loc7`='La cosa empeora, viejo amigo. De acuerdo con mis cálculos, sin los materiales apropiados para reparar nuestras trincheras, las paredes que protegen este bastión se desmoronarán en 12 horas.' WHERE `ID`=26548;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나쁜 소식이군, 내 작은 친구. 우리가 이곳에서 패한다면 이 얼어붙은 땅 전역에 그 영향이 미칠 걸세. 분노의 관문에 있는 폴드라곤 경과 우리 군대는 낙스라마스의 공격에 무방비로 노출되어 버리겠지.', `MaleText_loc4`='同胞们，我要告诉你们一个坏消息。如果我们战败，亡灵大军将肆无忌惮地横扫这片冰封之地。那时，弗塔根公爵以及我们在天谴之门的军队将无力与来自纳克萨玛斯的天灾军团抗衡。', `MaleText_loc5`='壞消息，我的小朋友。要是我們在這裡被打敗，那麼結果就是會是整片冰凍荒地都將失守。憤怒之門的弗塔根大人和我們的軍隊在面對納克薩瑪斯時將毫無招架之力。', `MaleText_loc7`='Malas noticias, mi compañero de tamaño de bolsillo. Si sufrimos una derrota aquí, las ramificaciones se dejarán sentir en este baldío helado. Lord Fordragón y nuestros ejércitos en la Puerta de Cólera estarán indefensos contra un ataque desde Naxxramas.' WHERE `ID`=26549;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 더 힘든 상황에서도 살아남지 않았습니까, 레오릭. 하이잘 산을 잊지 마세요...', `MaleText_loc4`='李奥瑞克，我们经历过更可怕的局面，而且还活了下来。你还记得海加尔峰吗……', `MaleText_loc5`='我們經歷過更慘的狀況，而且我們活下來了，李奧瑞克。別忘了海加爾...', `MaleText_loc7`='Hemos sobrevivido a cosas peores, Leoric. No te olvides de Hyjal...' WHERE `ID`=26550;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 그렇지. 하이잘, 실리더스, 불타는 군단의 행진, 그 외에도 7군단이 마주쳤던 모든 싸움을 나는 잊지 않았네. 하지만 이번에는... 병사들 귀에 이런 소리가 들어가는 것을 바라지는 않지만, 나는 난생처음으로...', `MaleText_loc4`='嗯，是啊，我永远记得第七军团在海加尔峰和希利苏斯的战事，记得我们对抗燃烧军团的远征，记得第七军团曾经面临过的种种挑战。但是……我不想让别的将士听到我这番话：这次是我生命中第一次感到……', `MaleText_loc5`='是，是，我沒忘記海加爾，或是希利蘇斯，甚至是燃燒軍團的進軍，以及第七軍團面對過的每個該死的戰役。我不希望士兵聽到這些，小個兒，但我生平第一次...', `MaleText_loc7`='Sí, sí, no he olvidado Hyjal, ni Silithus, ni la marcha de la Legión, ni ninguna otra confrontación en la que la Séptima Legión se haya visto involucrada. Es... No quiero que los soldados escuchen esto, pequeñajo, pero por primera vez en mi vida...' WHERE `ID`=26551;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더는 말하지 마세요, 레오릭. 우리 모두 뼛속 깊이 한기를 느끼고 있습니다. 하지만 매일같이 머나먼 곳에서 새로운 영웅이 오고 있잖아요.', `MaleText_loc4`='别说了，李奥瑞克。我们都能感受到这刺骨的寒冷。但是，我们并不孤独！每天，都有来自各个位面的英雄加入我们的行列。', `MaleText_loc5`='別再說了，李奧瑞克。我們都感覺的到直透骨髓的寒意。但是，每一天，都有英雄從世界各地，甚至別的世界趕來這裡。', `MaleText_loc7`='No digas más, Leoric. Todos sentimos el frío en nuestros huesos. Pero cada día llegan héroes desde el otro lado del mundo... y más allá.' WHERE `ID`=26552;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동쪽에서 들려오는 소문으로는 존경하는 스카라베 군주가 전쟁에 참여했다는군요. 그리고 아달이 몸소 축복하고 ''아달의 수호자''라는 칭호를 내린 영웅들이 샤트라스에서 여기까지 와 전쟁에 참여할 거래요.', `MaleText_loc4`='我听到东方传来的低语，备受尊敬的甲虫之王已经投身战斗，沙塔斯城也派来了一支精英部队。这支军队接受过阿达尔的赐福，他们都拥有一个响亮的头衔：阿达尔之手！', `MaleText_loc5`='我聽到來自東方的謠言說我們尊貴的聖甲蟲領主已經加入了戰鬥，還有來自撒塔斯的軍隊:受封阿達歐之手，阿達歐親自祝福的英雄，!', `MaleText_loc7`='Desde el Este llegan rumores que afirman que nuestro estimado Señor Escarabajo se ha unido a la batalla, junto con batallones enteros de Shattrath: héroes bendecidos por el propio A''dal y con el rango de Mano de A''dal.' WHERE `ID`=26553;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 자네 말이 맞네, 친구. 그 영웅들이 한시라도 빨리 오기를 기대해 보세.', `MaleText_loc4`='你说得对，我的老朋友。希望那些英雄能快点抵达这里。', `MaleText_loc5`='當然了，我的朋友，你是對的。讓我們懷抱著希望，英雄就快來了。', `MaleText_loc7`='Por supuesto, tienes razón, viejo amigo. Esperemos que los héroes lleguen pronto.' WHERE `ID`=26554;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼... 안 돼! 대체 뭘 한 거냐?! 아까운 고룡 뼈를 망치다니... 대체 무슨 마법이냐?', `MaleText_loc4`='不……天哪！你都做了什么？！竟然杀死了这么多远古巨龙……这是什么魔法？', `MaleText_loc5`='不...不!你做了什麼?!這麼多上古巨龍被殺死...什麼魔法能做到這種事?', `MaleText_loc7`='No... ¡NO! ¿Qué has hecho? Tantas antiguas vermis malgastadas... ¿Qué magia puede haber hecho esto?' WHERE `ID`=26555;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경쟁의 정신이 다시 힘을 되찾았습니다.', `MaleText_loc4`='竞争之魂又一次变得强大了。', `MaleText_loc5`='競賽之靈將會再次茁壯。', `MaleText_loc7`='Los espíritus de competición se han hecho fuertes de nuevo.', `FemaleText_loc1`='경쟁의 정신이 다시 힘을 되찾았어요.', `FemaleText_loc4`='竞争之魂又一次变得强大了。', `FemaleText_loc5`='競賽之靈將會再次茁壯。', `FemaleText_loc7`='Los espíritus de competición se han hecho fuertes de nuevo.' WHERE `ID`=26556;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘은 사람이 많아 전장이 몹시 북적대는군요.', `MaleText_loc4`='今天的战场里充满了斗志昂扬的勇士。', `MaleText_loc5`='戰場今天充滿了渴切的競賽者。', `MaleText_loc7`='Los campos de batalla están llenos de competidores ansiosos hoy.', `FemaleText_loc1`='오늘은 사람이 많아 전장이 몹시 북적대네요,', `FemaleText_loc4`='今天的战场里充满了斗志昂扬的勇士。', `FemaleText_loc5`='戰場今天充滿了渴切的競賽者。', `FemaleText_loc7`='Los campos de batalla están llenos de competidores ansiosos hoy.' WHERE `ID`=26557;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투모병관은 사람들이 경쟁하러 많이 올수록 기뻐한답니다.', `MaleText_loc4`='战场军官很高兴看到这么多人来参与竞赛。', `MaleText_loc5`='戰場軍官一定很高興這麼多人來參與。', `MaleText_loc7`='Los maestros de batalla están satisfechos con la cantidad de gente que está viniendo a competir.', `FemaleText_loc1`='전투모병관은 사람들이 경쟁하러 많이 올수록 기뻐하지요.', `FemaleText_loc4`='战场军官很高兴看到这么多人来参与竞赛。', `FemaleText_loc5`='戰場軍官一定很高興這麼多人來參與。', `FemaleText_loc7`='Los maestros de batalla están satisfechos con la cantidad de gente que está viniendo a competir.' WHERE `ID`=26558;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경쟁의 휘장을 얻다니 너무나 뿌듯합니다. 다음번에는 황금 메달을 노려보겠습니다.', `MaleText_loc4`='我为自己能获得竞争者的战袍而感到骄傲，并且希望能获得一枚金色勋章。', `MaleText_loc5`='我很榮幸地贏得了我的競賽者外袍，下一個目標就是黃金勳章。', `MaleText_loc7`='Estoy orgulloso de haber conseguido mi tabardo de competidor y ahora busco un medallón de oro.', `FemaleText_loc1`='경쟁의 휘장을 얻다니 너무나 뿌듯하네요. 다음번에는 황금 메달을 노려보겠어요.', `FemaleText_loc4`='我为自己能获得竞争者的战袍而感到骄傲，并且希望能获得一枚金色勋章。', `FemaleText_loc5`='我很榮幸地贏得了我的競賽者外袍，下一個目標就是黃金勳章。', `FemaleText_loc7`='Estoy orgullosa de haber conseguido mi tabardo de competidor y ahora busco un medallón de oro.' WHERE `ID`=26559;
