UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너는 이제 검은고룡족이 아니다. 가라... 가서 스컬지를 섬겨라.', `MaleText_loc4`='你已经不是黑龙了。去吧……为天灾军团战斗吧。', `MaleText_loc5`='你不再是個黑龍了。去吧...去服侍天譴軍團。', `MaleText_loc7`='Ya no eres un dragón Negro. Ve... ve y sirve a la Plaga.' WHERE `ID`=26568;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하시오.$b$b투자개발 만으로 가고 싶소?', `MaleText_loc4`='你好，$c。$b$b你想去风险湾吗？', `MaleText_loc5`='你好，$c。$b$b你想讓達洛克送你去風險海灣?', `MaleText_loc7`='Saludos, $c.$B$B¿Quieres que Darrok te envíe a Bahía Ventura?' WHERE `ID`=26569;
