UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐라고요? 지금 바쁜 거 안 보이세요?$B$B이 순간전송기가 저절로 고쳐지기라도 할 것 같아요?', `MaleText_loc4`='什么？没看见我正忙着吗？$B$B难道你觉得这玩意儿能自动恢复正常？！', `MaleText_loc5`='什麼?你看不出來我很忙嗎?$B$B你以為傳輸裝置會自己修好嗎?!', `MaleText_loc7`='¿Qué? ¿No ves que estoy ocupado?$B$B¡¿Crees que esta transmateria va a arreglarse sola?!' WHERE `ID`=26590;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 모두를 위해 볼바르 폴드라곤 대영주님이 싸우고 계세요. 그분이 아니었다면 지금쯤 스톰윈드의 왕좌에는 아서스가 앉아 있을 거라고요.', `MaleText_loc4`='伯瓦尔·弗塔根公爵一直都在为正义的事业奋斗。要不是他，阿尔萨斯没准已经坐上了暴风城的王座。', `MaleText_loc5`='大領主伯瓦爾·弗塔根為我們所有人而戰。要不是有他在，此刻阿薩斯應該會坐在暴風城的王座上。', `MaleText_loc7`='El alto señor Bolvar Fordragón lucha por todos nosotros. Si no fuera por él, Arthas estaría sentado sobre el trono de Ventormenta en este preciso instante.' WHERE `ID`=26594;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='광석 분석을 거의 마쳤어요. 이제 곧 결과가 나올 겁니다!', `MaleText_loc4`='啊，这种矿石，我差一点就能想出眉目来啦！只要灵光一闪，我就能给出答案！', `MaleText_loc5`='我差一點點就能弄懂這些礦了。我隨時會找到答案!', `MaleText_loc7`='Estoy a punto de descifrar esta mena. ¡En cualquier momento tendré la solución!' WHERE `ID`=26595;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너흰 잘못 생각하고 있다! 붉은돌격대는 온갖 거짓으로 가득해! 스컬지와 포세이큰은 우리의 적이 아니다! 눈을 떠!', `MaleText_loc4`='你们被骗了！血色先锋军都是骗子！天灾军团和被遗忘者不是我们的敌人！醒醒吧！', `MaleText_loc5`='你們都被騙了!血色突襲軍全是鬼扯!天譴軍團和被遺忘者不是我們的敵人!醒醒吧!', `MaleText_loc7`='¡Te están engañando! ¡El Embate no son más que mentiras! ¡La Plaga y los Renegados no son nuestros enemigos! ¡Despierta!' WHERE `ID`=26596;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고위사령관 아벤디스가 북으로 온 일은 실수였고, 우리 모두 죽은 목숨이라고 내게 직접 말했다! 모두 무기를 내려놓고 더 늦어지기 전에 떠나라!', `MaleText_loc4`='阿比迪斯将军亲口对我说，北征诺森德是个错误，我们被诅咒了！我奉劝你们赶紧放下武器，趁早离开这里！', `MaleText_loc5`='大將軍阿比迪斯私底下告訴我來北方是錯誤的，我們完蛋了!我要你們通通放下武器，在事情還有轉圜餘地之前快點離開!', `MaleText_loc7`='¡La Alta General Abbendis me dijo en persona que era un error venir al norte y que estábamos condenados! ¡Os insto a todos a que abandonéis las armas y huyáis antes de que sea demasiado tarde!' WHERE `ID`=26597;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='붉은돌격대를 버려라! 더는 고위사령관과 제독의 거짓말에 속아서는 안 된다!', `MaleText_loc4`='与血色先锋军断绝关系！别再听信将军和元帅编造的谎言了！', `MaleText_loc5`='和血色突襲軍斷絕關係吧!不要再聽從大將軍和上將的謊言了!', `MaleText_loc7`='¡Renuncia a El Embate Escarlata! ¡No sigas escuchando las mentiras de la Alta general y del Gran almirante!' WHERE `ID`=26598;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아벤디스는 하찮은 여자일 뿐이고, 제독 바리안 웨스트윈드 제독은 우리를 팔아먹은 것처럼 그 여자를 헐값에 팔아치우고 있어!', `MaleText_loc4`='阿比迪斯就是个臭婊子！海军上将巴利·韦斯温也不过是个皮条客，他以低廉的价格出卖了阿比迪斯，就像出卖我们一样！', `MaleText_loc5`='阿比迪斯只不過是個妓女，而韋斯溫上將還賤賣她，就像他隨便出賣我們一樣!', `MaleText_loc7`='¡Abbendis no es más que una ramera y el gran almirante Viento Oeste la está vendiendo igual de barata que a nosotros!' WHERE `ID`=26599;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로봇은 자신의 이동 속도를 당신 속도와 같게 설정할 거예요. 그러니 일을 빨리 처리하고 싶다면 뭔가에 올라타는 게 좋겠지요. 그건 그렇고, 이 로봇은 아웃랜드에서 보낸 고철 더미에서 찾아낸 부품으로 만든 겁니다. 부작용이 있을 수 있단 말이에요.', `MaleText_loc4`='机器人会根据你的行进速度调整自身的速度。我建议你骑上座骑，提高效率。顺便提一句，这玩意儿是我用一堆从外域送来的破铜烂铁拼凑起来的，可能会产生副作用。', `MaleText_loc5`='這機器人會自動調整他的速度來跟上你，所以我建議你最好騎快一點的交通工具。還有啊，臺機器人的零件，是從外域送過來給我，由一堆廢鐵胡亂拼湊起來的，所以有一些副作用。', `MaleText_loc7`='El robot ajustará su velocidad para equipararla a la tuya. Sugiero que te montes para que todo sea más rápido. Por cierto, el robot fue construido con piezas recuperadas de un montón de chatarra que me llegó desde Terrallende. Hay algunos efectos secundarios.' WHERE `ID`=26600;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파괴의 수호물에 마력이 모입니다.', `MaleText_loc4`='毁灭结界正在充能。', `MaleText_loc5`='毀滅禦符的力量增強了。', `MaleText_loc7`='El resguardo destructivo obtiene potencia.' WHERE `ID`=26601;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파괴의 수호물이 마력으로 충만해졌습니다!', `MaleText_loc4`='毁灭结界充能完毕！', `MaleText_loc5`='毀滅禦符完全充能!', `MaleText_loc7`='¡El resguardo destructivo está totalmente cargado!' WHERE `ID`=26602;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쿼터플래쉬, 유도 로봇이 하나 더 필요합니다.', `MaleText_loc4`='夸特弗拉什，再给我一个导航机器人吧。', `MaleText_loc5`='刻閃，我需要再一台追蹤機器人。', `MaleText_loc7`='Quartoflash, necesito otro buscabot.', `FemaleText_loc1`='쿼터플래쉬, 유도 로봇이 하나 더 필요합니다.', `FemaleText_loc4`='夸特弗拉什，再给我一个导航机器人吧。', `FemaleText_loc5`='刻閃，我需要再一台追蹤機器人。', `FemaleText_loc7`='Quartoflash, necesito otro buscabot.' WHERE `ID`=26603;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하신가!$b$b투자개발 만으로 가서 호드 놈들 머리통을 부숴 놓을 준비는 됐나?', `MaleText_loc4`='嗨，$c！$b$b你打算前往风险湾对付部落吗？', `MaleText_loc5`='哈囉，$c!$b$b你準備好去風險海灣砸爛部落的腦袋了嗎?', `MaleText_loc7`='¡Hola, $c!$B$B¿Estás en condiciones de ir a Bahía Ventura y romper unas cuantas cabezas de la Horda?' WHERE `ID`=26604;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예, 투자개발 만으로 갈 준비를 마쳤습니다!', `MaleText_loc4`='是的，我已经准备好前往风险湾了！', `MaleText_loc5`='是的，我準備好要去風險海灣了!', `MaleText_loc7`='¡Sí, estoy preparado para viajar a Bahía Ventura!', `FemaleText_loc1`='예, 투자개발 만으로 갈 준비를 마쳤습니다!', `FemaleText_loc4`='是的，我已经准备好前往风险湾了！', `FemaleText_loc5`='是的，我準備好要去風險海灣了!', `FemaleText_loc7`='¡Sí, estoy preparada para viajar a Bahía Ventura!' WHERE `ID`=26605;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='완벽하군. 닥치는 대로 베고 쓰러트리며 다니지만 않으면 놈들은 차이를 알아채지 못할 거요.', `MaleText_loc4`='很好。看来不派你去好好地教训他们一下，他们是搞不清楚状况的。', `MaleText_loc5`='完美無瑕。只要你不一路瘋狂砍殺過去的話，他們不會發現任何差異的。', `MaleText_loc7`='Perfecto. Mientras no te abras paso a hachazos ni acuchillando no notarán la diferencia.' WHERE `ID`=26606;
