UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가서 누가 이런 일을 저질렀는지 확인하고 오너라.', `MaleText_loc4`='孩子们，去看看是谁在捣鬼。', `MaleText_loc5`='孩子們，去看看是誰做的。', `MaleText_loc7`='Chicos, id a ver quién está haciendo eso.' WHERE `ID`=26608;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예, 대수도원장님. 가자!', `MaleText_loc4`='遵命。去看看！', `MaleText_loc5`='是的，閣下。來吧!', `MaleText_loc7`='Sí, su eminencia. ¡Adelante!' WHERE `ID`=26609;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 누가 종을 울린 거냐?', `MaleText_loc4`='喂，是谁在鸣钟？', `MaleText_loc5`='喂，是誰敲的鐘?', `MaleText_loc7`='Hey, ¿quién ha tocado la campana?' WHERE `ID`=26610;
