UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일이오, $g형제:자매;여?', `MaleText_loc4`='孩子，有事吗？', `MaleText_loc5`='嗯，我的$g孩子:女孩;?', `MaleText_loc7`='¿Sí, $g hijo mío : hija mía;?' WHERE `ID`=26612;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 지금 바쁘다오, 어린 양이여. 잠시 후에 다시 와 주시오.', `MaleText_loc4`='我正忙着呢。有什么话待会再说好吗。', `MaleText_loc5`='我很忙，孩子。等會再回來，我們到時候再談。', `MaleText_loc7`='Estoy ocupado $ghijo:hija;. Vuelve dentro de un rato y hablaremos.' WHERE `ID`=26613;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대수도원장님, 개인적으로 드릴 말씀이 있는데 괜찮으시겠습니까?', `MaleText_loc4`='请问我能不能与您单独谈一谈？', `MaleText_loc5`='大人，方便跟您借一步說話嗎?', `MaleText_loc7`='Su eminencia, ¿podemos hablar en privado?', `FemaleText_loc1`='대수도원장님, 개인적으로 드릴 말씀이 있는데 괜찮으시겠습니까?', `FemaleText_loc4`='请问我能不能与您单独谈一谈？', `FemaleText_loc5`='大人，方便跟您借一步說話嗎?', `FemaleText_loc7`='Su eminencia, ¿podemos hablar en privado?' WHERE `ID`=26614;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<잠시 살펴본 다음 미소 짓는 대수도원장>$B$B알겠소. 대화를 나누기에 적당한 곳을 알고 있소이다. 준비가 되면 내 반지에 입을 맞춰 알려주시오.', `MaleText_loc4`='<高阶修士打量了你一番，然后露出了笑容。>$B$B孩子，我知道有个地方不错的。如果你准备好了，就亲吻着我的戒指吧。', `MaleText_loc5`='<高階修士端詳了你老半天，才露出微笑。>$B$B很好，我曉得一個地方，孩子。親吻我的戒指好讓我知道你準備好了。', `MaleText_loc7`='<El sumo abad te estudia un instante y sonríe.>$B$BMuy bien, conozco un lugar, $ghijo:hija;. Tú besa mi anillo y avísame cuando te sientas en condiciones.' WHERE `ID`=26615;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비되었습니다, 대수도원장님. <반지에 입을 맞춤>', `MaleText_loc4`='我准备好了。<亲吻戒指>', `MaleText_loc5`='大人，我準備好了。<親吻戒指>', `MaleText_loc7`='Estoy preparado, ilustrísimo. <Besa el anillo.>', `FemaleText_loc1`='준비되었습니다, 대수도원장님. <반지에 입을 맞춤>', `FemaleText_loc4`='我准备好了。<亲吻戒指>', `FemaleText_loc5`='大人，我準備好了。<親吻戒指>', `FemaleText_loc7`='Estoy preparada, ilustrísimo. <Besa el anillo.>' WHERE `ID`=26616;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 수도원 입구에서 만나지. 곧 그리로 가겠소.', `MaleText_loc4`='去修道院门口等我吧。我很快就会过去的。', `MaleText_loc5`='請在修道院的入口見我，我馬上就過去。', `MaleText_loc7`='Entonces, únete a mí en la entrada de la abadía. Estaré allí en seguida.' WHERE `ID`=26617;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사가이, 밖에 네루비안 무리가 가득해. 녀석들은 끝이 없이 밀려오는 것 같아.', `FemaleText_loc4`='萨盖，蛛魔将要塞围得水泄不通啊。它们的数量简直无穷无尽。', `FemaleText_loc5`='沙蓋，外頭奈幽大軍的攻勢令人膽寒，他們似乎永遠也不會停下。', `FemaleText_loc7`='El asedio de nerubianos de ahí fuera es escalofriante, Sagai. Parecen infinitos.' WHERE `ID`=26618;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맞아, 녀석들 구덩이에서 나오는 거야. 그 구덩이 봤어? 전쟁노래 부족에서 그 구덩이를 함몰시키려는 얘기를 나누더군.', `MaleText_loc4`='是啊。它们不断从虫孔中涌出。你见过吧？我觉得我们应该设法炸毁那些虫孔，阻断蛛魔大军的来路。', `MaleText_loc5`='是啦，這就是坑道口，看見了嗎?這就是所謂的洞炸掉、埋起來。', `MaleText_loc7`='Sí. Son los sumideros. ¿Los ves? Están hablando de volarlos, de derrumbarlos.' WHERE `ID`=26619;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='맞아... 그 일 때문에 바로 어제 채석장에서 군수품을 회수했어.', `FemaleText_loc4`='没错……我昨天从采石场回收了一些军事物资，就是打算炸毁虫孔。', `FemaleText_loc5`='你說的沒錯...我昨天從石礦場發現軍品就是為了這個緣故。', `FemaleText_loc7`='Eso es... Recuperé las municiones ayer en la cantera para eso.' WHERE `ID`=26620;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='폭발물이 빨리 설치되었으면 좋겠다. 그럼 모든 이들이 잠시 쉴 수 있을 거야.', `FemaleText_loc4`='希望能尽快埋好炸药。我们已经筋疲力尽了，只有炸毁虫孔，我们才能喘口气。', `FemaleText_loc5`='我希望進攻能快點結束，大家都需要喘息的時間。', `FemaleText_loc7`='Espero que las cargas estén colocadas pronto. A todo el mundo le vendría bien un respiro.' WHERE `ID`=26621;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맞아. 바로 그거지.', `MaleText_loc4`='你说得对。', `MaleText_loc5`='這樣做就對了。', `MaleText_loc7`='Tienes razón.' WHERE `ID`=26622;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사울팽 님이 여기 계시잖아, 사가이! 브록시가르의 형제이신 사울팽님이 우리를 도우러 오셨다니까!', `FemaleText_loc4`='萨盖，你瞧！是萨鲁法尔大王！他是布洛克斯的兄弟啊！他来帮助我们啦！', `FemaleText_loc5`='薩魯法爾來了，沙蓋!是薩魯法爾!布洛克斯的兄弟本人來幫助我們了!', `FemaleText_loc7`='¡Colmillosauro está aquí, Sagai!¡Colmillosauro! El hermano de Broxigar en persona, ¡aquí, para ayudarnos!' WHERE `ID`=26623;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 이미 모든 문명을 파괴하는 걸로 내 할 일을 다했소... 그런데 저주받은 자들의 교단 따위를 상대하려고 몸을 낮추어야 한다니, 정말 역겹소.', `MaleText_loc4`='在摧毁这一文明的战事中，我已经尽到了自己的义务……我不得不屈尊亲自对付诅咒神教，一想到这点就觉得恶心。', `MaleText_loc5`='我已經完成了我分內毀滅整個文明的任務了...為此我必需要拉低我的身段，和詛咒神教打交道，這真是讓我作嘔。', `MaleText_loc7`='He jugado mi papel destruyendo civilizaciones enteras... pero tener que rebajarme a tratar con los desdichados miembros del Culto de los Malditos me repugna.' WHERE `ID`=26624;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스컬리 요원, 제게 밴시의 마법 거울을 다시 사용해 주십시오!', `MaleText_loc4`='斯古莉探员，请再对我使用一次女妖的魔镜！', `MaleText_loc5`='史考莉探員，女妖的魔鏡再對我用一次!', `MaleText_loc7`='¡Agente Skully, necesito que vuelvas a usar el espejo mágico de alma en pena conmigo!', `FemaleText_loc1`='스컬리 요원, 제게 밴시의 마법 거울을 다시 사용해 주세요!', `FemaleText_loc4`='斯古莉探员，请再对我使用一次女妖的魔镜！', `FemaleText_loc5`='史考莉探員，女妖的魔鏡再對我用一次!', `FemaleText_loc7`='¡Agente Skully, necesito que vuelvas a usar el espejo mágico de alma en pena conmigo!' WHERE `ID`=26625;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='알았네. 하지만 이번에는 조심하게!', `FemaleText_loc4`='好吧，不过这次希望你再当心一点！', `FemaleText_loc5`='好吧，但是這回要更小心一點!', `FemaleText_loc7`='Vale, ¡pero ten más cuidado esta vez!' WHERE `ID`=26626;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들은 뽑아낸 마력을 저장하는 데 저 룬을 사용하는 것 같군.', `MaleText_loc4`='很显然，他们利用那些符文来储藏从别处抽取来的能量。', `MaleText_loc5`='看來，他們利用這些符文，把他們抽取出的能量存取進去。', `MaleText_loc7`='Parece que están usando esas runas para depositar parte del poder que han drenado.' WHERE `ID`=26627;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='외눈깨비라니... 역겹군. 교단이 이곳을 오염시킨 것 같소.', `MaleText_loc4`='恶鬼……真讨厌。诅咒教派已经污染了这片土地。', `MaleText_loc5`='魂屍...噁心。神教寄生了這個地方。', `MaleText_loc7`='Geist... asqueroso. El Culto ha infestado este lugar.' WHERE `ID`=26628;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조용히 이야기를 나눌 만한 곳이 근처에 있소. 따라오시오.', `MaleText_loc4`='我知道有个僻静的去处，我们可以去那里单独谈谈。跟我来吧，孩子。', `MaleText_loc5`='我想我們可以去附近某處私下談談，孩子。跟我來。', `MaleText_loc7`='Conozco un lugar cercano en el que podremos hablar en privado, $ghijo mío:hija mía;. Sígueme.' WHERE `ID`=26629;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 예상이 틀렸기를 바랐건만... 놈들은 용암고룡을 되살리고 있소. 즉시 내게 돌아오시오. 이곳에서 교단을 몰아내야 하오.', `MaleText_loc4`='我真希望自己的猜测是错误的……但是他们……他们真的在复活熔岩之龙。快回到我身边，我们必须尽快将诅咒教派驱出这里。', `MaleText_loc5`='我一直希望我的懷疑是錯誤的...他們要將熔岩龍復生。請快回到我這，該是時候把詛咒神教的地盤清理一下了。', `MaleText_loc7`='Tenía la esperanza de que mis sospechas fueran erróneas... Están resucitando magmavermis. Vuelve a verme inmediatamente, es hora de eliminar al Culto de este lugar.' WHERE `ID`=26630;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 너의 그 어설픈 위장술도 간파하지 못할 거로 생각했나, $n?', `MaleText_loc4`='你觉着我看不出你那拙劣的伪装吗，$n？', `MaleText_loc5`='你以為我看不穿你那簡陋的偽裝嗎，$n?', `MaleText_loc7`='¿Pensabas que no podría reconocerte con ese frágil disfraz, $n?' WHERE `ID`=26631;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너 같은 작자가 이해할 수 없는 일은 많다, $r. 주인님은 모든 걸 아신다.', `MaleText_loc4`='$r，世间有许多你无法了解的玄机。只有全知全能的主上才能洞悉一切。', `MaleText_loc5`='你不懂的可多了，$r。主人無所不知。', `MaleText_loc7`='Hay muchas cosas que no puedes comprender, $r. El maestro lo ve todo.' WHERE `ID`=26632;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그분께서 네가 나타날 것이라 말씀하셨다. 하지만 난 네 손에 죽지는 않을 것이야. 난 네가 우리 동족들에게 어떤 짓을 해왔는지 안다.', `MaleText_loc4`='他早就预知你会来对付我。我亲眼目睹了你对我的同胞做过的事。但是，我是不会死在你手上的。', `MaleText_loc5`='他告訴我你會來找我。但我不會死於你之手，我見過你對我的同胞們的所作所為。', `MaleText_loc7`='Me dijo que vendrías a por mí. Pero no me matarás tú. He visto lo que has hecho a mis compatriotas.' WHERE `ID`=26633;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래. 난 내가 원하는 방식으로 이 세계를 떠날 것이다. 그리고 내가 돌아오면 총사령관님도 날 인정하겠지!', `MaleText_loc4`='别妄想了。我将以自己选择的方式离开这个世界。但是，我会遵照主上的意志卷土重来的！', `MaleText_loc5`='不，我會用我自己的方法離開這個世間。只要上將允許，我就會回來!', `MaleText_loc7`='No. Abandonaré este mundo del modo que yo elija. Y regresaré, si la voluntad del Gran almirante me lo permite.' WHERE `ID`=26634;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='목소리 낮추세요. 여기 야수들한테 발각되고 싶진 않으시겠죠?!', `FemaleText_loc4`='小声点。别被那些野兽发现啦！', `FemaleText_loc5`='壓低你的聲音。我們可不想引起這些野獸的注意。', `FemaleText_loc7`='Habla en voz baja. ¡No queremos llamar la atención de estas bestias!' WHERE `ID`=26635;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으아아아아아아아아아아악........................................', `MaleText_loc4`='啊啊啊啊啊啊啊……', `MaleText_loc5`='哎咿咿咿咿...', `MaleText_loc7`='AAAEEEEIIIiiiiiiiiiiiiiiiiiiiiiiiiiiii........................................' WHERE `ID`=26636;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으아! 뭘 하는 거요?', `MaleText_loc4`='哎！你干什么呢？', `MaleText_loc5`='嘿!你在幹嘛?', `MaleText_loc7`='¡Bah! ¿Qué estás haciendo?', `FemaleText_loc1`='이런! 뭘 하는 거요?', `FemaleText_loc4`='哎！你干什么呢？', `FemaleText_loc5`='嘿!你在幹嘛?', `FemaleText_loc7`='¡Bah! ¿Qué estás haciendo?' WHERE `ID`=26637;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 번도 본 적이 없는 사제로군.', `MaleText_loc4`='我从未见过这家伙。', `MaleText_loc5`='教團中我從未見過的成員。', `MaleText_loc7`='Un miembro del sacerdocio al que jamás había visto antes.', `FemaleText_loc1`='한 번도 본 적이 없는 사제로군.', `FemaleText_loc4`='我从未见过这家伙。', `FemaleText_loc5`='教團中我從未見過的成員。', `FemaleText_loc7`='Un miembro del sacerdocio al que jamás había visto antes.' WHERE `ID`=26638;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세상에, 림피 조를 죽이고 고기를 가져오다니! 우리가 여기 있는 줄은 어떻게 알았소?', `MaleText_loc4`='圣光在上！你杀死了乔伊，还抢走了肉！你是怎么找到我们的？', `MaleText_loc5`='以聖光之名，你宰了『瘸子』喬還拿走?他的肉!你怎麼知道我們在哪的?', `MaleText_loc7`='Por la Luz, ¡mataste a Joe el Cojo y cogiste la carne! ¿Cómo supiste dónde encontrarnos?' WHERE `ID`=26639;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물리지 않았소?', `MaleText_loc4`='你被咬了？', `MaleText_loc5`='你被咬了嗎?', `MaleText_loc7`='¿Te han mordido?' WHERE `ID`=26640;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대답하시오! 어디 물리지 않았느냔 말이오!', `MaleText_loc4`='回答我啊！你是不是被咬了？', `MaleText_loc5`='告訴我!你真的被咬了嗎?', `MaleText_loc7`='¡Contéstame! ¿Te han mordido?' WHERE `ID`=26641;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신도 날 죽이러 온 거라면 그리셀다에게 뭔가를 먹일 때까지 좀 기다려 주지 않겠소? 불쌍하게도 벌써 며칠째 아무것도 먹지 못했다오.', `MaleText_loc4`='好吧，就算你要杀我，至少等我喂饱格里西达吧？我可怜的宝贝已经好些日子没吃过东西啦。', `MaleText_loc5`='欸，如果你也是來殺我的話，能不能等我餵飽了葛薩爾妲之後再說?可憐的女孩兒，好多天沒吃東西了。', `MaleText_loc7`='Bueno, si has venido a matarme, ¿puedes, al menos, esperar a que alimente a Griselda? La pobre chica no ha comido desde hace días.' WHERE `ID`=26642;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 먹어라. 마지막으로 주는 식사로구나! 곧 림피 조를 죽인 자가 나 또한 끝장낼 테니 말이다...', `MaleText_loc4`='宝贝，杀死乔伊的凶手很快就要对我们下手了，让我最后再喂你一次吧。', `MaleText_loc5`='女孩兒，拿去。這是準備給妳的最後一餐，殺死『瘸子』喬的兇手要來幹掉我們了!', `MaleText_loc7`='Eh, joven. ¡Tengo una última comida para ti antes de que el asesino de Joe el Cojo acabe con nosotros!' WHERE `ID`=26643;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말 뒷잔등에 등잔 기름이 있소. 그걸 써보시오. 저 망할 녀석들은 불을 싫어하니까!', `MaleText_loc4`='喏，后面有灯油——你知道该怎么做吧。那帮混蛋对火焰又恨又怕！', `MaleText_loc5`='後面有燈油 - 好好利用，那些惡魔怕火!', `MaleText_loc7`='Hay aceite para lámparas en la parte de atrás, úsalo. ¡Esos demonios odian el fuego!' WHERE `ID`=26644;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 그 불쌍하고 힘없는 늙은 조를 죽일 수가 있소? 그리고 그 고기는 대체 왜 가져온 거요?', `MaleText_loc4`='你怎么忍心对乔伊这样手无寸铁的老头下毒手？你把肉带回来又有什么企图？', `MaleText_loc5`='你怎麼可以殺了又老又弱的老喬呢?你為什麼還帶了肉回來?', `MaleText_loc7`='¿Cómo pudiste matar al pobre e indefenso Joe? ¿Y por qué has traído la carne de vuelta?' WHERE `ID`=26645;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알 수 없는 친구로군... 그리고 말해 두지만, 난 알 수 없는 친구와 엮이고 싶지 않소...', `MaleText_loc4`='真是匪夷所思，我完全不明白你是怎么想的……我得说，我很难和你这样的家伙相处……', `MaleText_loc5`='你真是個謎團，而這就是你...告訴你，我向來對謎團沒有什麼好感...', `MaleText_loc7`='Eres un enigma, eso es lo que eres... Y permíteme que te avise: los enigmas y yo no nos llevamos bien...' WHERE `ID`=26646;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리셀다가 후식을 찾기 전에 어서 떠나는 게 좋을 거요.', `MaleText_loc4`='你最好趁格里西达还没有胃口吃餐后甜点之前离开。', `MaleText_loc5`='我覺得你最好在葛薩爾妲想吃甜點之前離開。', `MaleText_loc7`='Será mejor que te vayas antes de que Griselda decida que le apetece un postre.' WHERE `ID`=26647;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수정구를 되찾았으니, 이제 해답을 찾는 여정을 시작합시다!', `MaleText_loc4`='既然已经找回了水晶球，那么我们就着手寻求真相吧！', `MaleText_loc5`='寶珠回來了，開始找尋答案吧!', `MaleText_loc7`='¡Ahora que hemos recuperado el orbe, comienza la búsqueda de respuestas!' WHERE `ID`=26648;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하찮은 일로 날 방해하지 말게!', `MaleText_loc4`='别拿琐碎的小事打扰我！', `MaleText_loc5`='不要拿小事來煩我!', `MaleText_loc7`='¡No me molestes con nimiedades!' WHERE `ID`=26649;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자비를 베푸세요!', `MaleText_loc4`='发发慈悲吧！', `MaleText_loc5`='手下留情!', `MaleText_loc7`='¡Muestra clemencia!', `FemaleText_loc1`='자비를 베푸세요!', `FemaleText_loc4`='发发慈悲吧！', `FemaleText_loc5`='手下留情!', `FemaleText_loc7`='¡Muestra clemencia!' WHERE `ID`=26650;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 하라는 대로 했을 뿐입니다. 제발...', `MaleText_loc4`='我只是奉命行事啊。求求你……', `MaleText_loc5`='我不過是做我被吩咐的事罷了。請...', `MaleText_loc7`='Solo estaba cumpliendo órdenes. Por favor...', `FemaleText_loc1`='난 하라는 대로 했을 뿐입니다. 제발...', `FemaleText_loc4`='我只是奉命行事啊。求求你……', `FemaleText_loc5`='我不過是做我被吩咐的事罷了。請...', `FemaleText_loc7`='Solo estaba cumpliendo órdenes. Por favor...' WHERE `ID`=26651;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 이렇게 죽을 운명이 아니야!', `MaleText_loc4`='我不想就这么死掉啊！', `MaleText_loc5`='我不該是這種死法!', `MaleText_loc7`='¡Así no es como debía morir!', `FemaleText_loc1`='난 이렇게 죽을 운명이 아니야!', `FemaleText_loc4`='我不想就这么死掉啊！', `FemaleText_loc5`='我不該是這種死法!', `FemaleText_loc7`='¡Así no es como debía morir!' WHERE `ID`=26652;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 이겼습니다. 제발 날 보내주세요.', `MaleText_loc4`='你赢了。求求你放我走吧。', `MaleText_loc5`='你贏了。拜託，讓我走吧。', `MaleText_loc7`='Tú ganas. Por favor, deja que me vaya.', `FemaleText_loc1`='당신이 이겼습니다. 제발 날 보내주세요.', `FemaleText_loc4`='你赢了。求求你放我走吧。', `FemaleText_loc5`='你贏了。拜託，讓我走吧。', `FemaleText_loc7`='Tú ganas. Por favor, deja que me vaya.' WHERE `ID`=26653;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부디 자비를...', `MaleText_loc4`='可怜可怜我吧……', `MaleText_loc5`='同情我...', `MaleText_loc7`='Ten piedad...', `FemaleText_loc1`='부디 자비를...', `FemaleText_loc4`='可怜可怜我吧……', `FemaleText_loc5`='同情我...', `FemaleText_loc7`='Ten piedad...' WHERE `ID`=26654;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 헌신적인 모습을 보고자 총사령관께서 직접 오셨다. 그렇게 축 늘어진 모습을 또 보인다면 내 손으로 널 없애버리겠어.', `MaleText_loc4`='韦斯温大人正在这一带巡视呢！如果再让我看见你在岗位上划水，我就把你撕成碎片。', `MaleText_loc5`='上將會來觀禮，要是再讓我看到你怠忽職守，我會親自把你的心挖出來。', `MaleText_loc7`='El Gran almirante en persona ha venido para ver nuestra dedicación. Si te vuelvo a ver escaqueándote en tu puesto, te arrancaré las tripas yo mismo.', `FemaleText_loc1`='우리의 헌신적인 모습을 보고자 총사령관께서 직접 오셨다. 그렇게 축 늘어진 모습을 또 보인다면 내 손으로 널 없애버리겠어.', `FemaleText_loc4`='韦斯温大人正在这一带巡视呢！如果再让我看见你在岗位上划水，我就把你撕成碎片。', `FemaleText_loc5`='上將會來觀禮，要是再讓我看到你怠忽職守，我會親自把你的心挖出來。', `FemaleText_loc7`='El Gran almirante en persona ha venido para ver nuestra dedicación. Si te vuelvo a ver escaqueándote en tu puesto, te arrancaré las tripas yo misma.' WHERE `ID`=26655;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙습니다, $c|1이여;여;.', `MaleText_loc4`='谢谢你，$c。', `MaleText_loc5`='謝謝你，$c。', `MaleText_loc7`='Gracias, $c.' WHERE `ID`=26656;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 좀 낫군요.', `MaleText_loc4`='啊……感觉好多了。', `MaleText_loc5`='啊...好一點了。', `MaleText_loc7`='Ahh... mejor.' WHERE `ID`=26657;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 싸우러 가야겠습니다!', `MaleText_loc4`='我又能重新投入战斗了！', `MaleText_loc5`='重返戰鬥!', `MaleText_loc7`='¡De vuelta a la lucha!' WHERE `ID`=26658;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='후우, 죽는 줄 알았습니다. 고맙습니다!', `MaleText_loc4`='哇咧！我差点死在这里。谢谢你，$r！', `MaleText_loc5`='嚇啊 - 我差點死在這，謝謝你，$r!', `MaleText_loc7`='¡Guau! He estado a punto de morir ahí. ¡Gracias, $r!' WHERE `ID`=26659;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 바쁜 게 안 보이십니까! 이러시면 왕자님이 돌아오시기 전에 공사를 완료하지 못할 겁니다!', `MaleText_loc4`='你没看见我正忙着吗！再这样拖沓，我们是不可能在王子殿下归来之前修好这座基地啦！', `MaleText_loc5`='你沒看到我很忙嗎!我們不可能在王子回來前把基地即時準備好啦!', `MaleText_loc7`='¡No ves que estoy ocupado! ¡Nunca conseguiremos que esta base esté lista cuando regrese el Príncipe!' WHERE `ID`=26660;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 빌어먹을 짐승들이 우리 배를 태워버리지만 않았으면 우린 지금쯤 집에 가 있을 텐데. 이제 일 좀 하게 저리 가세요!', `MaleText_loc4`='要不是那群混蛋烧毁了船只，我们早就到家啦。别来烦我了，我要回去工作啦！', `MaleText_loc5`='要不是那些該死的野獸燒了我們的船，我們早就到家了。不要來煩我，我要去工作了!', `MaleText_loc7`='Si esas bestias salvajes no hubieran quemado nuestros barcos, ya estaríamos en casa. ¡Ahora déjame en paz para que pueda seguir trabajando!' WHERE `ID`=26661;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은빛십자군 부대가 이곳에 왔습니다. 당신 혼자 영광을 독차지하게 두진 않을 겁니다!', `MaleText_loc4`='朋友，银色北伐军的部队已经抵达此地。我们不会让你独占所有荣耀的！', `MaleText_loc5`='朋友，銀白十字軍也參戰了。我們不會讓你搶走所有功勞的!', `MaleText_loc7`='La Cruzada Argenta tiene el control aquí, colega. ¡No íbamos a dejar que te llevaras toda la gloria!' WHERE `ID`=26662;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오리크, 암흑풀 영약이 더 필요합니다.', `MaleText_loc4`='欧瑞克，请再给我一瓶黑暗草药剂。', `MaleText_loc5`='歐利克，我還要一罐陰鬱草藥劑。', `MaleText_loc7`='Orik, necesito otro elixir de hierba tiniebla.', `FemaleText_loc1`='오리크, 암흑풀 영약이 더 필요합니다.', `FemaleText_loc4`='欧瑞克，请再给我一瓶黑暗草药剂。', `FemaleText_loc5`='歐利克，我還要一罐陰鬱草藥劑。', `FemaleText_loc7`='Orik, necesito otro elixir de hierba tiniebla.' WHERE `ID`=26663;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방해해서 미안합니다. 계속하시지요!', `MaleText_loc4`='朋友，很抱歉打扰到你了。你忙你的吧！', `MaleText_loc5`='抱歉打擾你，朋友，繼續吧!', `MaleText_loc7`='Siento haberte molestado, colega. ¡Continúa!', `FemaleText_loc1`='방해해서 미안합니다. 계속하시지요!', `FemaleText_loc4`='朋友，很抱歉打扰到你了。你忙你的吧！', `FemaleText_loc5`='抱歉打擾你，朋友，繼續吧!', `FemaleText_loc7`='Siento haberte molestado, colega. ¡Continúa!' WHERE `ID`=26664;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 마그나타우르의 땅을 침범해? 이 해골도살자가 기꺼이 네놈을 으깨고, 갈비뼈를 전리품으로 간직해 주마!', `MaleText_loc4`='你竟敢闯入猛犸人的领地？裂骨者要把你拍成肉酱！', `MaleText_loc5`='膽敢侵入猛瑪象人的領地?骨裂會開心的打扁你，然後拿你的大腿當獎勵!', `MaleText_loc7`='¿Osas invadir la tierra de los magnatauros? ¡Hiendehuesos estará feliz de aplastarte y quedarse con tus extremidades como pago!' WHERE `ID`=26665;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두려움을 느껴 보아라, 쥐새끼 같은 녀석!', `MaleText_loc4`='颤抖吧，鼠辈！', `MaleText_loc5`='嚇得屁滾尿流吧，畜生!', `MaleText_loc7`='¡Encógete ante mí, renacuajo!' WHERE `ID`=26666;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 됐군! 난 신선하고 펄떡펄떡 뛰는 먹이를 좋아하지.', `MaleText_loc4`='好呀！我喜欢活蹦乱跳的食物。', `MaleText_loc5`='很好!我最愛拿鮮活的肉當食物了。', `MaleText_loc7`='¡Bien! Me gusta que mi comida esté fresca y animada.' WHERE `ID`=26667;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 녀석의 공포가 느껴지는구나.', `MaleText_loc4`='我能感受到你内心的恐惧。', `MaleText_loc5`='我可以嗅到你的恐懼。', `MaleText_loc7`='Puedo oler tu miedo.' WHERE `ID`=26668;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이걸로 끝나지 않는다... 죽음은 우리를... 강하게 할 뿐...', `MaleText_loc4`='事情远没有结束……死亡……会令我……更加强大……', `MaleText_loc5`='這不是結束...死亡只是...使我們更強大...', `MaleText_loc7`='Este no es el final... la muerte solo... fortalece...' WHERE `ID`=26669;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 빌어먹을 일꾼들은 너무 느려터졌어! 빨리 아이언포지로 돌아가고 싶네. 마누라와 자식들이 얼마나 보고 싶은지 몰라.', `MaleText_loc4`='让那群该死的农夫赶紧干活啊！我好想回到铁炉堡。实在是太想念我的老婆和孩子了。', `MaleText_loc5`='那些該死的農民動作得要再快一點!我想回去鐵爐堡。我真的很想念我的妻兒。', `MaleText_loc7`='¡Esos malditos campesinos tienen que trabajar más deprisa! Quiero volver a casa, a Forjaz. Echo de menos a mi mujer e hijos.' WHERE `ID`=26670;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아서스 왕자님만 돌아오시면 우린 바로 로데론으로 돌아갈 거라고 대장님께서 말씀하셨지.', `MaleText_loc4`='船长说，只要阿尔萨斯王子殿下回来，我们就能返回洛丹伦了。', `MaleText_loc5`='隊長說只要阿薩斯王子一回來，我們就啟程回去羅德隆。', `MaleText_loc7`='El Capitán dice que en cuanto el príncipe Arthas regrese, volveremos a Lordaeron.' WHERE `ID`=26671;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왕자님께서 왜 이렇게 늦으시는 건지 모르겠지만, 여기선 더 오래 버티긴 어려울 것 같네. 병사 몇몇은 벌써 추위에 나가떨어지고 있던데.', `MaleText_loc4`='不知道王子殿下究竟是被什么事给耽搁了，但是我们真的坚持不了太久了。许多士兵都无法忍受如此严寒的气候。', `MaleText_loc5`='我不知道小王子為什麼花了那麼多時間，但我覺得我們沒辦法再撐下去了。有些士兵已經無法承受嚴寒了。', `MaleText_loc7`='No sé por qué está tardando tanto el joven Príncipe, pero no creo que podamos aguantar mucho más. Algunos de los soldados están empezando a notar el frío.' WHERE `ID`=26672;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아서스 님은 곧 돌아오실 겁니다. 힘내세요!', `MaleText_loc4`='我相信阿尔萨斯殿下很快就会回来的。千万别气馁！', `MaleText_loc5`='我確定阿薩斯隨時都會回來，士兵。收下巴!', `MaleText_loc7`='Estoy seguro de que Arthas volverá algún día, soldado. ¡Mantén la cabeza erguida!', `FemaleText_loc1`='아서스 님은 곧 돌아오실 겁니다. 힘내세요!', `FemaleText_loc4`='我相信阿尔萨斯殿下很快就会回来的。千万别气馁！', `FemaleText_loc5`='我確定阿薩斯隨時都會回來，士兵。收下巴!', `FemaleText_loc7`='Estoy segura de que Arthas volverá algún día, soldado. ¡Mantén la cabeza erguida!' WHERE `ID`=26673;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 야만적인 짐승들이 우리 배를 불태웠을 때 우리 가슴도 내려앉았소. 그런 절망은 처음이었소...', `MaleText_loc4`='看着那些被野蛮人烧毁的船只，我们的心情仿佛跌到了谷底。说实话，我从来没有觉得如此无助……', `MaleText_loc5`='眼睜睜的看著這些野蠻的怪物焚燒掉我們的船，我們的心也隨著沉入了海底。我從未感到如此無助...', `MaleText_loc7`='Cuando vimos que esas bestias salvajes habían quemado nuestros barcos, nos quedamos con el corazón en un puño. Jamás me había sentido tan indefenso...' WHERE `ID`=26674;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분노. 지금 상황에서 내 감정은 그 단어로밖에 설명할 수 없소. 우리는 죽을 힘을 다해 숲을 헤치고 해변으로 나왔지만, 이미 때는 너무 늦어 있었소. 집으로 돌아갈 수 있는 유일한 수단이 파괴된 것이오.', `MaleText_loc4`='愤怒。看着眼前这堆烂摊子，我实在是压抑不住心中的怒火。我们历尽艰辛，一路披荆斩棘穿越森林才来到海边，却发现还是迟了一步。返回家园的唯一希望已经破灭了。', `MaleText_loc5`='暴怒。面對這一切混亂，這兩個字是唯一能總結我情緒的詞。我們摩頂放踵得通過樹林，來到海岸，卻只發現一切都太晚了。回家唯一的路已經被摧毀了。', `MaleText_loc7`='Rabia. Eso resume mis sentimientos hacia este desastre. Nos dejamos la piel intentando atravesar los bosques y llegar a la orilla, solo para descubrir que era demasiado tarde. Nuestra única forma de volver a casa había sido destruida.' WHERE `ID`=26675;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비록 이 황무지에서 우리가 겪은 시련은 이루 말할 수 없지만, 난 왕자님이 우리를 승리로 이끌어주시리라 믿소. 매일 밤 그분이 무사하시기만을 기도한다오.', `MaleText_loc4`='尽管这片冰霜废土给我们留下了痛苦的回忆，但我相信，年轻的王子殿下终将领导我们走向胜利。我夜夜祈祷，希望他能平安归来。', `MaleText_loc5`='不辭勞苦，我們仍然要通過這片荒原，我相信小王子會看到我們的勝利。我夜夜祈求王子平安。', `MaleText_loc7`='A pesar de todos los apuros a los que hemos tenido que hacer frente en estos baldíos, creo que el joven Príncipe nos guiará hasta la victoria. Rezo cada noche para que esté a salvo.' WHERE `ID`=26676;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이만 가봐야겠습니다. 경계를 늦추지 마십시오!', `MaleText_loc4`='我要出发了，士兵。保持警惕！', `MaleText_loc5`='士兵，我得走了。保持警戒!', `MaleText_loc7`='Debo irme ahora, soldado. ¡Mantente alerta!', `FemaleText_loc1`='이만 가봐야겠습니다. 경계를 늦추지 마십시오!', `FemaleText_loc4`='我要出发了，士兵。保持警惕！', `FemaleText_loc5`='士兵，我得走了。保持警戒!', `FemaleText_loc7`='Debo irme ahora, soldado. ¡Mantente alerta!' WHERE `ID`=26677;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<고개를 젓는 잊혀진 보병>$B$B더는 버틸 수가 없소. 아서스 왕자님이 빨리 돌아오시지 않으면 우린 모두 죽을 거요.', `MaleText_loc4`='<被遗忘的步兵摇了摇头。>$B$B我们快要支撑不下去了。阿尔萨斯王子殿下再不回来的话，我们都会没命的。', `MaleText_loc5`='<遺民步卒搖搖頭。>$B$B我們不會一直存在，朋友。如果阿薩斯王子沒有回來，我們很快就會消失了。', `MaleText_loc7`='<El lacayo olvidado agita la cabeza.>$B$BNo podemos continuar así, colega. Si el príncipe Arthas no regresa pronto, moriremos todos.' WHERE `ID`=26678;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 절대로 이 배들을 제때 고치지 못할 거요. 겨울이 우리의 최후와 함께 다가오고 있소. 왕자님이 우리 모두를 버린 게 아닌가 싶어 두렵다오...', `MaleText_loc4`='我们不可能及时备好船只了。寒冬降临时，就是我们的末日。恐怕我们都被王子殿下遗弃了。', `MaleText_loc5`='我們不可能即時把船隻準備好。冬天襲來，我們的末日也隨著到來。我怕小王子已經在詛咒我們了。', `MaleText_loc7`='Nunca tendremos estos barcos listos a tiempo. El invierno se acerca y con él nuestra perdición. Temo que el joven Príncipe nos ha condenado a todos.' WHERE `ID`=26679;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아서스 님과 무라딘 님은 이미 떠나신 지 오래되었소. 그분들이 무사하셔야 할 텐데...', `MaleText_loc4`='阿尔萨斯殿下和穆拉丁殿下离开这里很长时间了。希望他们平安。', `MaleText_loc5`='阿薩斯和穆拉丁已經去了好一陣子了。我希望他們沒有碰上危險。', `MaleText_loc7`='Hace mucho que Arthas y Muradin se han ido. Espero que no estén en peligro.' WHERE `ID`=26680;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='별일 없을 겁니다.', `MaleText_loc4`='一切都会好起来的。', `MaleText_loc5`='步兵，情況會好轉的。', `MaleText_loc7`='Estoy seguro de que todo saldrá bien, lacayo.', `FemaleText_loc1`='별일 없을 겁니다.', `FemaleText_loc4`='一切都会好起来的。', `FemaleText_loc5`='步兵，情況會好轉的。', `FemaleText_loc7`='Estoy segura de que todo saldrá bien, lacayo.' WHERE `ID`=26681;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대에게 신의 가호가 있기를. 죽을 뻔했소이다...', `MaleText_loc4`='祝福你，朋友。我快……不行了……', `MaleText_loc5`='祝福你，朋友，我要斷氣了...', `MaleText_loc7`='$gBendito:Bendita; seas, colega. Casi muero...' WHERE `ID`=26682;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$r|1이여;여;, 고맙습니다!', `MaleText_loc4`='谢谢你，$r！', `MaleText_loc5`='謝謝你，$r!', `MaleText_loc7`='¡Gracias, $r!' WHERE `ID`=26683;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거의 포기하려던 참이오. 내 목숨을 구해줬구려!', `MaleText_loc4`='就在我近乎绝望的时候，你为我带来了生的希望！', `MaleText_loc5`='我差點就放棄了。你賜給我新生命!', `MaleText_loc7`='Casi me había rendido. ¡Me has dado una nueva vida!' WHERE `ID`=26684;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 도와주지 않았다면 난 지금쯤 죽었을 거요...', `MaleText_loc4`='要不是你，我肯定没命了……', `MaleText_loc5`='要是沒有你的幫助，我早就死了...', `MaleText_loc7`='Sin tu ayuda, habría muerto seguro...' WHERE `ID`=26685;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안돼애애애! 어머니! 반드시 이 원수를 갚겠어요!', `MaleText_loc4`='不！！！妈妈！！！我们会为你报仇的！', `MaleText_loc5`='不!!母親!我們會為你復仇!', `MaleText_loc7`='¡NOOOOOOO! ¡Madre! ¡Te vengaremos!' WHERE `ID`=26686;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스컹크, 토끼, 새끼 사슴이 한 데 어울려 다니고 있군. 이건 흔히 볼 수 있는 모습이 아니라오. 어쨌거나, 오늘 저녁은 사슴 고기요!', `MaleText_loc4`='啧啧，臭鼬、小白兔和小鹿结伴出游。这样的场景还真是少见啊。不过我的晚餐倒是有着落了！难得的野味啊！', `MaleText_loc5`='一隻臭鼬、兔子和小鹿走在一塊兒，這可不是天天都看得到。這不重要，反正今晚有野味吃啦!', `MaleText_loc7`='Una mofeta, un conejo y un cervato viajando juntos. Esto no se ve todos los días. Es igual, ¡hoy cenaré venado!' WHERE `ID`=26687;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래. 그 헬스크림 님. 대단한 분이지. 하지만 내 생각엔 자신을 증명하는 데 너무 열중해 계셔. 사울팽 님이 여기 계시니 다행스럽지.', `MaleText_loc4`='呀。我觉得吧，加尔鲁什倒也算得上是位勇士，可惜他很爱表现，老想着如何证明自己的实力。不过既然萨鲁法尔大王也在这里，我就安心啦。', `MaleText_loc5`='是啊，地獄吼，他很兇猛，可是我認為，他太急於表現自己了。薩魯法爾在這裡，很好，一定的。', `MaleText_loc7`='Sí. Grito Infernal ser implacable, pero yo creer que demasiado ansioso por demostrar su valía. Yo estar seguro de que ser bueno que Colmillosauro estar aquí.' WHERE `ID`=26688;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘은 어디로 보내 드릴까요?', `MaleText_loc4`='今天你想去哪儿呢？', `MaleText_loc5`='我今天要送你去哪裡呢?', `MaleText_loc7`='¿Dónde puedo enviarte?' WHERE `ID`=26689;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사울팽 님이 여기 계시잖아, 사가이! 브록시가르의 형제이신 사울팽님이 우리를 도우러 오셨다니까!', `FemaleText_loc4`='萨盖，快瞧！是萨鲁法尔大王！他是布洛克斯的兄弟，他来帮助我们啦！', `FemaleText_loc5`='薩魯法爾來了，沙蓋!是薩魯法爾!布洛克斯的兄弟本人來幫助我們了!', `FemaleText_loc7`='¡Colmillosauro está aquí, Sagai! El hermano de Broxigar en persona, ¡aquí, para ayudarnos!' WHERE `ID`=26690;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사냥을 시작합시다!', `MaleText_loc4`='狩猎时间！', `MaleText_loc5`='打獵囉!', `MaleText_loc7`='¡Hora de cazar!' WHERE `ID`=26691;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋은 동호회에는 세상을 바꾸는 힘이 있다네.', `MaleText_loc4`='加入上等的俱乐部可以为你的生活增添别样的风采。', `MaleText_loc5`='一個好的俱樂部能夠改變整個世界。', `MaleText_loc7`='Un buen club puede marcar la diferencia en el mundo.', `FemaleText_loc1`='좋은 동호회에는 세상을 바꾸는 힘이 있다네.', `FemaleText_loc4`='加入上等的俱乐部可以为你的生活增添别样的风采。', `FemaleText_loc5`='一個好的俱樂部能夠改變整個世界。', `FemaleText_loc7`='Un buen club puede marcar la diferencia en el mundo.' WHERE `ID`=26692;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맥주 사랑 동호회의 맥주를 사고 싶습니다.', `MaleText_loc4`='我要购买本月美酒。', `MaleText_loc5`='我想購買本月的啤酒。', `MaleText_loc7`='Me gustaría comprar la cerveza de este mes.', `FemaleText_loc1`='맥주 사랑 동호회의 맥주를 사고 싶어요.', `FemaleText_loc4`='我要购买本月美酒。', `FemaleText_loc5`='我想購買本月的啤酒。', `FemaleText_loc7`='Me gustaría comprar la cerveza de este mes.' WHERE `ID`=26693;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여보게, 친구! 아직 가을 축제 동전을 가지고 있는 것 같은데, 마침 나한테도 가을 축제 상품이 남아있다네.', `MaleText_loc4`='嘿，伙计！你手里拿的不是美酒节奖币吗？我恰好有一些美酒节物品要出售。', `MaleText_loc5`='嗨，朋友!我知道你有些啤酒節獎品章。碰巧，我還有些啤酒節商品可以賣你。', `MaleText_loc7`='¡Hola, colega! Veo que tienes algunas fichas de la Fiesta de la Cerveza. Resulta que yo aún tengo algunos objetos de la Fiesta de la Cerveza a la venta.', `FemaleText_loc1`='여보게, 친구! 아직 가을 축제 동전을 가지고 있는 것 같은데, 마침 나한테도 가을 축제 상품이 남아있다네.', `FemaleText_loc4`='嘿，伙计！你手里拿的不是美酒节奖币吗？我恰好有一些美酒节物品要出售。', `FemaleText_loc5`='嗨，朋友!我知道你有些啤酒節獎品章。碰巧，我還有些啤酒節商品可以賣你。', `FemaleText_loc7`='¡Hola, colega! Veo que tienes algunas fichas de la Fiesta de la Cerveza. Resulta que yo aún tengo algunos objetos de la Fiesta de la Cerveza a la venta.' WHERE `ID`=26694;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 물건을 팔고 계십니까?', `MaleText_loc4`='你有什么货物啊？', `MaleText_loc5`='有什麼事嗎?', `MaleText_loc7`='¿Qué tienes para mí?', `FemaleText_loc1`='어떤 물건을 팔고 계신가요?', `FemaleText_loc4`='你有什么货物啊？', `FemaleText_loc5`='有什麼事嗎?', `FemaleText_loc7`='¿Qué tienes para mí?' WHERE `ID`=26695;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요, 딩동. 딩동 친구. 딩동. 요!', `MaleText_loc4`='Yo Ding-Dong.  Ding-Dong man.  Ding-dong.  Yo!', `MaleText_loc5`='喲，叮噹。叮噹啊老兄。叮噹，喲!', `MaleText_loc7`='Eh Ding-Dong. Ding-Dong, tío. Ding-dong. ¡Eh!', `FemaleText_loc1`='요, 딩동. 딩동 친구. 딩동. 요!', `FemaleText_loc4`='Yo Ding-Dong.  Ding-Dong man.  Ding-dong.  Yo!', `FemaleText_loc5`='喲，叮噹。叮噹。叮噹，喲!', `FemaleText_loc7`='Eh Ding-Dong. Ding-Dong, tío. Ding-dong. ¡Eh!' WHERE `ID`=26696;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='윈터가드 성채로 빨리 가야 합니다!', `MaleText_loc4`='我要立刻前往暮冬要塞！', `MaleText_loc5`='我需要盡快回到溫特加德要塞!', `MaleText_loc7`='¡Necesito llegar a la Fortaleza de Hibergarde rápido!', `FemaleText_loc1`='윈터가드 성채로 빨리 가야 해요!', `FemaleText_loc4`='我要立刻前往暮冬要塞！', `FemaleText_loc5`='我需要盡快回到溫特加德要塞!', `FemaleText_loc7`='¡Necesito llegar a la Fortaleza de Hibergarde rápido!' WHERE `ID`=26697;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요!$b$b벌목기를 타고 싶다면 언덕 위로 가야 할 거예요.$b$b이건 작동을 안 한다고요.', `MaleText_loc4`='你好，$r！$b$b想找一台可以乘坐的伐木机？恐怕你得进入山岭啦。$b$b这台坏掉了。', `MaleText_loc5`='你好呀，$r!$b$b如果你要找台伐木機來開，你得爬上山丘去。$b$b那一台現在沒在使用。', `MaleText_loc7`='¿Qué tal, $r?$B$BSi buscas una trituradora que montar, tendrás que subir a las colinas.$B$BEsta está fuera de servicio.' WHERE `ID`=26698;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='열쇠요? 무슨 열쇠요?', `MaleText_loc4`='钥匙？什么钥匙？', `MaleText_loc5`='鑰匙?什麼鑰匙?', `MaleText_loc7`='¿Llave? ¿Qué llave?', `FemaleText_loc1`='열쇠요? 무슨 열쇠요?', `FemaleText_loc4`='钥匙？什么钥匙？', `FemaleText_loc5`='鑰匙?什麼鑰匙?', `FemaleText_loc7`='¿Llave? ¿Qué llave?' WHERE `ID`=26699;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고친 벌목기 열쇠 말입니다!$b$b가지고 있지 않다면 내 형제 시니푸스에게 이야기하세요.', `MaleText_loc4`='翻新过的伐木机的钥匙啊，笨！$b$b如果没有的话，你可以和我的兄弟塞尼普斯谈谈。', `MaleText_loc5`='為什麼，翻新伐木機的鑰匙，傻瓜!$b$b如果你今天還沒拿到一個，你可以和我兄弟辛尼普斯談談。', `MaleText_loc7`='¡La llave de trituradora reformada, zoquete!$B$BSi aún no has conseguido una hoy, puedes hablar con mi hermano, Synipus.' WHERE `ID`=26700;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋은 술이란 바로 독한 술을 말하는 거랍니다.', `MaleText_loc4`='够劲的啤酒才是好啤酒。', `MaleText_loc5`='烈酒，就是好酒。', `MaleText_loc7`='Una buena cerveza es una cerveza fuerte.', `FemaleText_loc1`='좋은 술이란 바로 독한 술을 말하는 거랍니다.', `FemaleText_loc4`='够劲的啤酒才是好啤酒。', `FemaleText_loc5`='烈酒，就是好酒。', `FemaleText_loc7`='Una buena cerveza es una cerveza fuerte.' WHERE `ID`=26701;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 형제는 어디에 있습니까?', `MaleText_loc4`='你的兄弟在哪儿呢？', `MaleText_loc5`='我到哪裡才能找到你們這樣的兄弟?', `MaleText_loc7`='¿Dónde puedo encontrar a ese hermano tuyo?', `FemaleText_loc1`='당신 형제는 어디에 있나요?', `FemaleText_loc4`='你的兄弟在哪儿呢？', `FemaleText_loc5`='我到哪裡才能找到你們這樣的兄弟?', `FemaleText_loc7`='¿Dónde puedo encontrar a ese hermano tuyo?' WHERE `ID`=26702;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 왜 벌목기를 타야 합니까?', `MaleText_loc4`='我干嘛要乘坐伐木机？', `MaleText_loc5`='為什麼我要開一台伐木機?', `MaleText_loc7`='¿Por qué querría montar en una trituradora?', `FemaleText_loc1`='내가 왜 벌목기를 타야 하나요?', `FemaleText_loc4`='我干嘛要乘坐伐木机？', `FemaleText_loc5`='為什麼我要開一台伐木機?', `FemaleText_loc7`='¿Por qué querría montar en una trituradora?' WHERE `ID`=26703;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그게요, 여기서 전투가 벌어지기 전에는 우린 그냥 벌목기를 고쳐서 이 일대에서 벌목 작업을 하는 데 썼지요.$b$b하지만 요즘에는 호드를 상대하는 데 벌목기를 사용해요. 전투 병기로 꽤 쓸만하다는 사실이 입증됐거든요. 열쇠가 있는데도 벌목기를 안 쓴다면 바보 같은 짓이죠!', `MaleText_loc4`='事情是这样。在武装冲突爆发之前，我们利用伐木机来砍伐这里的树木。$B$B战争很快一触即发，我们不得不改装这些机器来对抗部落。要知道，翻新后的伐木机简直是超级厉害的战斗机器呢。如果你有钥匙的话，为什么不好好利用一番呢！', `MaleText_loc5`='嗯，在所有的戰鬥在此爆發之前，我們正在修理它們好收集當地的樹木。$b$b後來，它們不得不用來對抗部落。居然成了很優秀的戰鬥機器。如果你要是有把鑰匙的話，不使用它的人是傻瓜!', `MaleText_loc7`='Bueno, antes de las hostilidades las arreglábamos para cosechar los árboles cercanos.$B$BPero últimamente nos hemos visto obligados a usarlas contra la Horda. Resulta que son buenas como máquinas de lucha. ¡Si tuvieras una llave, no usarla sería una tontería!' WHERE `ID`=26704;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맥주 사랑 동호회 회원이 되는 건 멋진 일이랍니다.', `MaleText_loc4`='能加入“本月美酒俱乐部”真是太棒了。', `MaleText_loc5`='當個「每月啤酒」俱樂部的會員真好。', `MaleText_loc7`='Mola ser miembro del Club de la "Cerveza del Mes".', `FemaleText_loc1`='맥주 사랑 동호회 회원이 되는 건 멋진 일이죠.', `FemaleText_loc4`='能加入“本月美酒俱乐部”真是太棒了。', `FemaleText_loc5`='當個「每月啤酒」俱樂部的會員真好。', `FemaleText_loc7`='Mola ser miembro del Club de la "Cerveza del Mes".' WHERE `ID`=26705;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고친 벌목기 열쇠는 어디서 구할 수 있습니까?', `MaleText_loc4`='我怎么才能弄到翻新过的伐木机的钥匙呢？', `MaleText_loc5`='我從哪裡可以拿到一把翻新伐木機之鑰?', `MaleText_loc7`='¿Dónde puedo conseguir una llave de trituradora reformada?', `FemaleText_loc1`='고친 벌목기 열쇠는 어디서 구할 수 있나요?', `FemaleText_loc4`='我怎么才能弄到翻新过的伐木机的钥匙呢？', `FemaleText_loc5`='我從哪裡可以拿到一把翻新伐木機之鑰?', `FemaleText_loc7`='¿Dónde puedo conseguir una llave de trituradora reformada?' WHERE `ID`=26706;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론 강 상류 쪽이죠!$b$b하하! 강을 따라 올라가면... 알았어요, 알았어, 푸른 하늘 벌목장에 가면 그가 벌목기를 고치고 있을 거예요.$b$b아, 그를 만나거든 이 말을 꼭 전해주세요. 만들다가 만 벌목기를 한 번만 더 보냈다간 내가 당장 거기로 올라갈 거라고요!', `MaleText_loc4`='当然是在河流上游啊！$b$b哈哈！在上游……嗯，你可以在蓝天伐木场找到他，这家伙大概正开着伐木机忙活呢。$b$b哦，顺便告诉他，如果他再送来半成品的伐木机，我就让他好看！', `MaleText_loc5`='為什麼，就抓去關啊!$b$b哈哈!抓去關...好好好，你可以在藍天伐木地的伐木機找到他。$b$b喔，你可以告訴他，如果他再送任何一台半成品的伐木機來，他等著被我抓去關!', `MaleText_loc7`='¡Río arriba, por supuesto!$B$B¡Ja, ja! Río arriba... Vale, vale, puedes encontrarle trabajando en las trituradoras en el Aserradero Cielo Azul.$B$BAh, y puedes decirle que si me envía más trituradoras a medio acabar, ESTARÁ río arriba.' WHERE `ID`=26707;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 형제인 시니푸스가 잔뜩 가지고 있어요. 북쪽의 푸른 하늘 벌목장에 가서 말해보세요.', `MaleText_loc4`='我的兄弟塞尼普斯有很多伐木机。你可以前往北边的蓝天伐木场和他谈谈。', `MaleText_loc5`='我兄弟，辛尼普斯那種東西他有一堆。你應該往北方去藍天伐木地，和他談談。', `MaleText_loc7`='Mi hermano, Synipus, tiene muchas. Deberías ir al norte, al Aserradero Cielo Azul y hablar con él.' WHERE `ID`=26708;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죄송합니다만, 왕자님은 일이 있어 자리를 비우셨습니다. 무슨 일로 여기까지 오셨습니까?', `MaleText_loc4`='抱歉，大使阁下，但王子殿下因故离开了。请问您来这片冰霜废土有什么事吗？', `MaleText_loc5`='我向您致歉，大使，但王子因任務外出。是什麼風把您吹來這個荒涼的地方?', `MaleText_loc7`='Mis disculpas, emisario, pero el príncipe está en una misión. ¿Qué te trae a este desolado lugar?' WHERE `ID`=26709;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='병사를 이끌고 즉각 본국으로 귀환하라는 왕명을 전하러 왔소. 우서 경이 폐하를 설득해 이 원정을 중지하도록 했소.', `MaleText_loc4`='根据皇家敕令，部队立刻返回洛丹伦。乌瑟尔大人已经说服国王陛下召回这支远征军。', `MaleText_loc5`='依據皇家敕令，你的手下要立即返回羅德隆。烏瑟大人已經說服國王取消這一次遠征。', `MaleText_loc7`='Por decreto real, tus hombres deben regresar a Lordaeron inmediatamente. Lord Uther convenció al Rey de cancelar esta expedición.' WHERE `ID`=26710;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그냥 여길 떠나도 된다고요?', `MaleText_loc4`='这么说我们要马上离开这里？', `MaleText_loc5`='這麼說我們要馬上離開這裡?', `MaleText_loc7`='¿Tenemos que recoger todo e irnos?' WHERE `ID`=26711;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇소. 헌데 이곳에서 해안으로 나가는 길을 언데드가 장악했다고 하더군. 배로 돌아가려면 다른 길을 찾아야 할 거요.', `MaleText_loc4`='没错。我的手下也报告说，从这里通向海岸的道路被亡灵占据了。你必须另找一条路回到船上。', `MaleText_loc5`='沒錯。我的手下回報說通往海岸的道路被不死生物所佔據。您需要找到一條安全的路徑回到船上。', `MaleText_loc7`='Correcto. Me comunicaron que los caminos de aquí a la costa están tomados por los no-muertos. Deberán encontrar otro camino para volver a las naves.' WHERE `ID`=26712;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='망할 놈의 언데드... 제군들, 숲을 가로지르자!', `MaleText_loc4`='该死的亡灵！弟兄们，直接从森林中穿过去！', `MaleText_loc5`='不死生物全都該死!我們要穿過樹林，兄弟!', `MaleText_loc7`='¡Al diablo con los no-muertos! ¡Tomaremos un atajo por el bosque!' WHERE `ID`=26713;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부대장, 왜 다들 위치를 벗어났지?', `MaleText_loc4`='上尉，卫兵怎么都不在自己的哨位里？', `MaleText_loc5`='上尉，為什麼守衛不在他們的崗位上?', `MaleText_loc7`='Capitán, ¿por qué los guardias no están en sus puestos?' WHERE `ID`=26714;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왕자님, 폐하께서 우서 경의 청에 따라 회군을 명하셨습니다.', `MaleText_loc4`='呃，殿下，您的父王应乌瑟尔大人的请求召回了全军。', `MaleText_loc5`='呃，殿下，您的父親照烏瑟大人的要求把我們的部隊全叫回去了。', `MaleText_loc7`='Bueno, milord, tu padre retiró nuestras tropas a pedido de Lord Uther.' WHERE `ID`=26715;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우서가 내 부대를 불러들여? 빌어먹을! 병사들이 떠나면 어떻게 말가니스를 잡으란 말인가! 병사들이 해안에 도착하기 전에 배를 불태워야겠어!', `MaleText_loc4`='乌瑟尔要召回我的军队？见鬼！如果战士们离我而去，我要怎么杀死玛尔加尼斯？必须要赶在他们回到海边之前烧毁船只！', `MaleText_loc5`='烏瑟把我的部隊給叫回去了?該死!如果我的戰士棄我而去，我永遠也不可能打贏瑪爾加尼斯。我們一定要在部隊抵達海岸之前把船給燒了!', `MaleText_loc7`='¿Uther hizo retirar mis tropas? ¡Maldición! Si mis guerreros me abandonan, nunca derrotaré a Mal''Ganis. ¡Hay que quemar las naves antes de que los hombres arriben!' WHERE `ID`=26716;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그건 너무 심하지 않나?', `MaleText_loc4`='这是否太过分了，伙计？', `MaleText_loc5`='這樣不會太過份了嗎，小子?', `MaleText_loc7`='¿No es demasiado?' WHERE `ID`=26717;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='완전히 불태울 겁니다! 임무를 마칠 때까지 아무도 돌아갈 수 없습니다!', `MaleText_loc4`='全都烧成灰烬！我们事业未尽，谁也不能提前回家！', `MaleText_loc5`='把它燒到只剩骨架!在我們的任務完成之前，沒人可以回去!', `MaleText_loc7`='¡Carbonizadas! ¡Nadie regresa a casa hasta cumplir nuestra tarea!' WHERE `ID`=26718;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='멈추세요! 칼을 치우세요. 어떤 임무를 받았건 간에 그런 짓을 해서는 안 돼요... 당신은 아직 그들처럼 되진 않았어요!', `FemaleText_loc4`='等等！把刀放下。你为什么……为什么要听他们的呢。你和他们截然不同啊！', `FemaleText_loc5`='住手!把刀放下。你不需要...不管他們派你來做什麼。你都和他們不一樣!', `FemaleText_loc7`='¡Detente! Guarda ese cuchillo. No tienes que hacer... lo que te hayan mandado a hacer. ¡Aún no eres como ellos!' WHERE `ID`=26719;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일이지? 아서스 왕자님이 당장 오늘 돌아오실지도 모르는데!', `MaleText_loc4`='现在要怎么办呢？或许阿尔萨斯王子殿下今天就会回来呢！', `MaleText_loc5`='現在是怎樣?也許阿薩斯王子今天就會回來!', `MaleText_loc7`='¿Y ahora qué? ¡Quizá el príncipe Arthas regrese junto a nosotros hoy!' WHERE `ID`=26720;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제군들, 기운 내라! 어쩌면 바로 오늘, 이 저주받은 땅에서 떠날 수 있을지도 모르지! 아아, 사랑스러운 아이언포지, 보고 싶은 고향이여!', `MaleText_loc4`='振作一点！或许我们今天就能离开这片被诅咒的土地！噢，铁炉堡！我真想家啊！', `MaleText_loc5`='看開點，小夥子!今天我們說不定就能離開這片受詛咒的土地!喔，甜美的鐵爐堡，我多想念你啊!', `MaleText_loc7`='¡Animaos, chicos! ¡Puede que hoy sea el día en que abandonemos esta maldita tierra! ¡Oh dulce Forjaz, cuánto te he echado de menos!' WHERE `ID`=26721;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼애애애애!!!!', `MaleText_loc4`='不！！！！！', `MaleText_loc5`='不不不不不不!!!!', `MaleText_loc7`='¡¡¡¡NOOOOOOO!!!!' WHERE `ID`=26722;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아서스, 이 비열한 사기꾼! 넌 우리 모두를 버렸어!', `MaleText_loc4`='阿尔萨斯！你这个骗子！我们都被你给害了！', `MaleText_loc5`='你這滿嘴謊言的卑鄙傢伙，阿薩斯!你把我們全毀了!', `MaleText_loc7`='¡Maldito mentiroso, Arthas! ¡Nos has condenado a todos!' WHERE `ID`=26723;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왕자가 우리를 버렸다! 이젠 끝이야!', `MaleText_loc4`='王子抛弃了我们！所有的希望都破灭了！', `MaleText_loc5`='我們的王子拋棄了我們!全完了!', `MaleText_loc7`='¡Nuestro Príncipe nos ha traicionado! ¡Todo está perdido!' WHERE `ID`=26724;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='약속하지 않았나, 이 배신자!', `MaleText_loc4`='叛徒，你还记得对我们许下的诺言吗！', `MaleText_loc5`='你答應過我們的，叛徒!', `MaleText_loc7`='¡Nos diste tu palabra, traidor!' WHERE `ID`=26725;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피에 물든 네 싸움이 우리 목숨보다 더 중요하단 말이냐...', `MaleText_loc4`='我们的性命远比你那所谓的血海深仇重要……', `MaleText_loc5`='我們的生命遠比你的血仇重要...', `MaleText_loc7`='Nuestras vidas valían mucho más que tu enemistad mortal...' WHERE `ID`=26726;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어째서 그런 짓을?', `MaleText_loc4`='这一切都是为什么？', `MaleText_loc5`='為什麼?', `MaleText_loc7`='¿Pero por qué?' WHERE `ID`=26727;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 다 거짓말이었어...', `MaleText_loc4`='全是谎言……', `MaleText_loc5`='這一切都是謊言...', `MaleText_loc7`='No eran más que mentiras...' WHERE `ID`=26728;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 가장 증오하는 것이 네 영혼을 갈가리 찢어발기기를 기원하겠다, 왕자여.', `MaleText_loc4`='年轻的王子，愿你最憎恶的敌人撕裂你的灵魂！', `MaleText_loc5`='願你的靈魂被你最憎恨的東西扯成碎片，年輕的王子。', `MaleText_loc7`='Que tu alma sea partida en dos por aquello que más odies, joven Príncipe.' WHERE `ID`=26729;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고마워요. 저... 저는 이만 가봐야겠어요.', `FemaleText_loc4`='谢谢你。我……该离开啦。', `FemaleText_loc5`='謝謝你。我...我應該要走了。', `FemaleText_loc7`='Gracias. Yo... debería irme ahora.' WHERE `ID`=26730;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자넨 부하들에게 거짓말을 했고, 자네를 믿고 싸운 용병들을 배신했네. 대체 왜 그러나? 자네에겐 오직 복수만이 중요한가?', `MaleText_loc4`='你对你的部下说谎，还背叛了为你而战的雇佣兵。你到底怎么了，阿尔萨斯？你就只有复仇这个念头了吗？', `MaleText_loc5`='你對你自己的手下撒謊，背叛那些替你作戰的傭兵。你怎麼了，阿薩斯?難道對你來說復仇才是一切?', `MaleText_loc7`='Mentiste a tus hombres y traicionaste a los mercenarios que lucharon por ti. ¿Qué te sucede, Arthas? ¿Sólo te importa la venganza?' WHERE `ID`=26731;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이해하십시오, 무라딘. 당신은 말가니스가 무슨 짓을 했는지 모릅니다.', `MaleText_loc4`='别管我了，穆拉丁。你没见过玛尔加尼斯对我的家乡做了什么。', `MaleText_loc5`='別說了，穆拉丁。你沒有親眼看到瑪爾加尼斯對我的家鄉做了什麼。', `MaleText_loc7`='Ya basta, Muradin. No presenciaste lo que Mal''Ganis le hizo a mi tierra.' WHERE `ID`=26732;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동전을 충분히 모으면 맥주 사랑 동호회 회원이 될 수 있지요. 맥주 사랑 동호회에 가입하면 일 년 내내 가을 축제를 벌이는 것이나 마찬가지랍니다!$b$b매달 소식지와 함께 시음용 맥주를 보내 드립니다. 맥주가 입맛에 맞으면 아이언포지에 있는 부싯돌 선술집으로 가서 더 사면 되는 거지요.', `MaleText_loc4`='只要集满足够的奖币就能加入“本月美酒俱乐部”。加入了“本月美酒俱乐部”就好象天天都过美酒节！$b$b每个月你都可以通过邮件收到一份新出的酒样。如果你喜欢的话，可以到铁炉堡的石火旅店向商人购买。', `MaleText_loc5`='有了足夠的獎品章你就可以加入「每月啤酒」俱樂部。加入每月啤酒俱樂部就像整年都可以慶祝啤酒節一樣!$b$b每個月你都會收到附有新啤酒的信件讓你試喝。如果你喜歡寄來的啤酒，你可以去鐵爐堡的石火旅店多買一些。', `MaleText_loc7`='Con suficientes fichas puedes unirte al "Club de la Cerveza del Mes". ¡Formar parte del Club de la Cerveza del Mes es como celebrar la Fiesta de la Cerveza durante todo el año!$b$bCada mes recibirás un correo con una nueva cerveza para degustar. Si te gusta esa cerveza, puedes ir a la taberna Roca de Fuego de Forjaz y comprar más a los vendedores de allí.' WHERE `ID`=26733;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맥주 사랑 동호회', `MaleText_loc4`='本月美酒俱乐部', `MaleText_loc5`='每月啤酒俱樂部', `MaleText_loc7`='Club de la Cerveza del Mes', `FemaleText_loc1`='맥주 사랑 동호회', `FemaleText_loc4`='本月美酒俱乐部', `FemaleText_loc5`='每月啤酒俱樂部', `FemaleText_loc7`='Club de la Cerveza del Mes' WHERE `ID`=26734;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들에게 본때를 보여줘라!', `MaleText_loc4`='与敌人开战吧！', `MaleText_loc5`='和敵人一戰，兄弟!', `MaleText_loc7`='¡Llevad la lucha hasta el enemigo, hombres!' WHERE `ID`=26735;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 더러운 오크에게 항구를 넘겨줄 수는 없다!', `MaleText_loc4`='别让那些肮脏的兽人占领港口！', `MaleText_loc5`='別讓那些骯髒的獸人佔領港口!', `MaleText_loc7`='¡No dejéis que esos sucios orcos tomen el puerto!' WHERE `ID`=26736;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자비를 베풀지 마라!', `MaleText_loc4`='不要对敌人心存仁慈！', `MaleText_loc5`='絕不留情!', `MaleText_loc7`='¡No mostréis piedad!' WHERE `ID`=26737;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자비를 베풀지 마라! 이 항구는 우리 것이다!', `FemaleText_loc4`='不要对敌人心存怜悯！港口是我们的！', `FemaleText_loc5`='對敵人絕不手下留情!港口是我們的!', `FemaleText_loc7`='¡No mostréis piedad al enemigo! ¡Este puerto será nuestro!' WHERE `ID`=26738;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='녀석들이 재정비할 틈을 주지 마라! 없애버려!', `FemaleText_loc4`='不要给联盟狗喘息的机会，杀光他们！', `FemaleText_loc5`='在他們重整之前殺光這些聯盟狗!', `FemaleText_loc7`='¡Matad a esos perros de la Alianza antes de que puedan reagruparse!' WHERE `ID`=26739;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='싸워라! 호드의 영광을 위해!', `FemaleText_loc4`='为部落的荣耀而战！', `FemaleText_loc5`='為了部落的榮譽而戰!', `FemaleText_loc7`='¡Luchad por la gloria de la Horda!' WHERE `ID`=26740;
