UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛이 그대를 치유하도록 좀 진정하시오.', `MaleText_loc4`='Take it easy, let the light heal you. [PH]', `MaleText_loc5`='輕一點，讓聖光治癒你。 [PH]', `MaleText_loc7`='Take it easy, let the light heal you. [PH]' WHERE `ID`=26742;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='할 수 있는 한 당신의 상처를 치유해 드리겠소.', `MaleText_loc4`='I will heal your wounds as best as I can. [PH]', `MaleText_loc5`='我會盡全力治療你的傷勢。[PH]', `MaleText_loc7`='I will heal your wounds as best as I can. [PH]' WHERE `ID`=26743;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동전을 충분히 모으면 맥주 사랑 동호회 회원이 될 수 있습니다. 맥주 사랑 동호회에 들어온다는 것은 일 년 내내 가을 축제를 벌이는 것이나 마찬가지지요!$b$b매달 소식지와 함께 시음용 맥주가 배달되거든요. 맥주가 입맛에 맞으면 오그리마 정기의 골짜기에 있는 검은장미 오두막으로 가서 더 사 마시면 되지요.', `MaleText_loc4`='只要集满足够的奖币就能加入“本月美酒俱乐部”。加入了“本月美酒俱乐部”就好象天天都过美酒节！$b$b每个月你都可以通过邮件收到一份新出的酒样。如果你喜欢的话，可以到奥格瑞玛精神谷的黑石南小屋向商人购买。', `MaleText_loc5`='有了足夠的獎品章你就可以加入「每月啤酒」俱樂部。加入每月啤酒俱樂部就像整年都可以慶祝啤酒節一樣!$b$b每個月你都會收到附有新啤酒的信件讓你試喝。如果你喜歡寄來的啤酒，你可以去奧格瑪精神谷的暗木小屋多買一些。', `MaleText_loc7`='Con suficientes fichas puedes unirte al "Club de la Cerveza del Mes". ¡Formar parte del Club de la Cerveza del Mes es como celebrar la Fiesta de la Cerveza durante todo el año!$b$bCada mes recibirás un correo con una nueva cerveza para degustar. Si te gusta esa cerveza, puedes ir a la Cabaña de Brezo de Valle de los Espíritus de Orgrimmar y comprar más a los vendedores de allí.' WHERE `ID`=26744;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 위협하듯 발톱을 치켜듭니다!', `MaleText_loc4`='%s扬起爪子，摆出威胁的架势！', `MaleText_loc5`='%s威嚇性的舉起了他的爪子!', `MaleText_loc7`='¡%s levanta sus garras de forma amenazadora!' WHERE `ID`=26745;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 되어 가는 것 같군.', `MaleText_loc4`='一切似乎都进展得很顺利。', `MaleText_loc5`='事情看來會好轉。', `MaleText_loc7`='Parece que las cosas van bien.', `FemaleText_loc1`='잘 되어 가는 것 같군.', `FemaleText_loc4`='一切似乎都进展得很顺利。', `FemaleText_loc5`='事情看來會好轉。', `FemaleText_loc7`='Parece que las cosas van bien.' WHERE `ID`=26746;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대단하군. 주인님께서는 너와 네 종족이 방해될 것이라 말씀하셨다. 어찌 됐건, 너희의 종말은 머지않았다. 곧 하나 된 낙스라마스의 군대가 이곳에 내려와 너희의 하찮은 존재를 지워버릴 것이다.', `MaleText_loc4`='啧啧。你们真的很讨厌呢，难怪主人警告我说要小心对付。不过，你们的末日很快就会降临了。来自纳克萨玛斯的亡灵大军将席卷这里，彻底抹去你们存在过的痕迹。', `MaleText_loc5`='令人印象深刻。主人說你和你的同胞會變成一個麻煩。不管如何，你的末日要到了。很快地納克薩瑪斯的聯合武力將會來到此地，將你貧弱的存在徹底粉碎。', `MaleText_loc7`='Impresionante. El maestro decía que tú y tu gente seríais una molestia. Da igual, tu final se acerca. Pronto el poder combinado de Naxxramas caerá sobre este lugar y destrozará tu exigua existencia.' WHERE `ID`=26747;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그걸 가지고 어디를 가겠다는 거냐, 하찮은 존재여? 그 고서를 내려놓는다면 너에게 영원의 고통을 내리는 일은 참아 주겠다.', `MaleText_loc4`='你以为自己能逃到哪儿去？老实点，把魔典给我吧，我或许会考虑让你死得痛快一点。', `MaleText_loc5`='你以為你要帶著那個去哪裡，凡人?把書放下，或許我可以讓你死得痛快一點。', `MaleText_loc7`='¿Adónde crees que vas con eso, mortal? Deja el libro y puede que te evite una eternidad de angustia.' WHERE `ID`=26748;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼어붙은 벌판의 병사들아, 일어나 주인의 말에 귀를 기울여라! $n|1이;가; 저 고서를 가지고 나가게 해서는 안 된다!', `MaleText_loc4`='冰霜废土的士兵们，聆听主人的召唤，站起来吧！夺下$n手中的魔典！', `MaleText_loc5`='冰凍荒原的士兵們，甦醒吧，聽從你們主人的呼喚!別讓$n帶著書逃走!', `MaleText_loc7`='¡Soldados de los baldíos helados, alcenze y escuchen la llamada de su maestro! ¡No dejen que $n escape con el libro!' WHERE `ID`=26749;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고서 네 것 아니다...', `MaleText_loc4`='它……不属于你……', `MaleText_loc5`='書不是你的...', `MaleText_loc7`='Libro no tuyo...' WHERE `ID`=26750;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고서... 내놔...', `MaleText_loc4`='把……它……给我……', `MaleText_loc5`='還...給...我...', `MaleText_loc7`='Dar... libro... a mí.' WHERE `ID`=26751;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 모여든 군중을 바라보며 힘주어 고개를 끄덕입니다.', `MaleText_loc4`='%s注视着渐渐聚拢的村民，沉重地点了点头。', `MaleText_loc5`='%s看著聚集的群眾，然後沉重地點了點頭。', `MaleText_loc7`='%s observa a la muchedumbre reunida y asiente de forma pesada.' WHERE `ID`=26752;
