UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파멸만이 기다린다...', `MaleText_loc4`='死亡在等待……', `MaleText_loc5`='只有毀滅在等著...', `MaleText_loc7`='Solo espera la ruina...' WHERE `ID`=26754;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파도가 내게 이야기를 전했으니. 귀 기울이거라. 깨닫거라.', `MaleText_loc4`='潮涨潮落，我来讲个故事吧。看看你们能否有所领悟。', `MaleText_loc5`='潮水帶了一個故事給我。聽著並接受啟發吧。', `MaleText_loc7`='La marea me ha traído una historia. Escuchad e iluminaos.' WHERE `ID`=26755;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='텔잔께서 널 가지신다...', `MaleText_loc4`='塞尔赞……会杀了你……', `MaleText_loc5`='賽爾贊將會逮到你...', `MaleText_loc7`='Thel''zan acabará con ustedes...' WHERE `ID`=26756;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='투스카르는 얼음으로 이루어진 이 땅에서 살았노라. 헤아릴 수 없을 만큼 여러 번 해가 졌노라.', `MaleText_loc4`='海象人氏族自古就居住在这片冰封之地，看过数不尽的日出日落。', `MaleText_loc5`='經歷了無數個日落，牙之民來到了這個冰霜之地。', `MaleText_loc7`='Desde incontables puestas de sol, la gente con colmillos ha vivido en esta tierra de hielo.' WHERE `ID`=26757;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 바다의 은총을 입으며 살았으니. 우리는 사슴뿔이 난 짐승의 고기로 살쪘으니.', `MaleText_loc4`='我们生活在海陆交界处，尽情享受着大海的慷慨和恩赐。', `MaleText_loc5`='我們靠著大海的恩賜而活。我們靠著鹿角一族的肉而變得豐腴。', `MaleText_loc7`='Hemos vivido de las recompensas del mar. Hemos engordado con la carne de los que tienen cornamenta.' WHERE `ID`=26758;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바다와 땅이 우리에게 삶을 주었노라.', `MaleText_loc4`='海洋与陆地赐予了我们生命。', `MaleText_loc5`='大海與土地給了我們生命。', `MaleText_loc7`='El mar y la tierra nos han dado vida.' WHERE `ID`=26759;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런데 우리에게서 바다를 빼앗으려는 자가 있으니, 거대한 약탈자가 바닷가에 있는 우리 성소를 덮쳤구나.', `MaleText_loc4`='敌人打破了我们的宁静生活。他们有的想要夺取海洋的控制权。那些高大的维库人已经侵占了岸边的海象人圣地。', `MaleText_loc5`='有人想把大海從我們這裡奪走。那些巨人劫掠者入侵我們在海岸的聖地。', `MaleText_loc7`='Algunos quieren quitarnos el mar. Los asaltantes gigantes han invadido nuestro lugar sagrado en la orilla.' WHERE `ID`=26760;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맥주 사랑 동호회가 뭡니까?', `MaleText_loc4`='本月美酒俱乐部？', `MaleText_loc5`='每月啤酒俱樂部?', `MaleText_loc7`='¿Club de la Cerveza del Mes?', `FemaleText_loc1`='맥주 사랑 동호회가 뭐죠?', `FemaleText_loc4`='本月美酒俱乐部？', `FemaleText_loc5`='每月啤酒俱樂部?', `FemaleText_loc7`='¿Club de la Cerveza del Mes?' WHERE `ID`=26761;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맥주 사랑 동호회를 모른단 말이야? 여기 아가씨들은 흥청망청 노는 걸 정말 좋아하지. 아마 아가씨들 방식대로 놀았다간 가을 축제가 절대로 끝이 안 났을 거야! 작년부터 가끔 가을 축제답지 않다는 생각이 들더라고.$b$b동호회에서는 가을 축제 정신을 이어가려면 회원을 더 모집해야 한다는 걸 깨달은 거야.$b$b회비 조금하고 상품 교환 동전 몇 개만 있으면 가입할 수 있어! 매달 맥주가 우편으로 배달되고, 그 맥주가 입맛에 맞으면 더 살 수도 있어. 이건 정말 끝내주는 조건이라고. 가을 축제 정신도 계속 이어나가는 방법이고 말이야.', `MaleText_loc4`='你还不知道“本月美酒俱乐部”？那些姑娘最喜欢聚会了。如果她们能想到合适的办法，美酒节将会永不落幕！去年她们就曾希望美酒节不要结束。$b$b但现在她们找到了更好地发扬美酒节精神的方法，那就是让人们加入她们的俱乐部。$b$b你只需要付出很少的费用，只需要几枚美酒节奖币，你就能加入了！会员每个月都会收到俱乐部邮寄来的酒样，还可以购买自己喜欢的啤酒。这个精英俱乐部能永远继承美酒节的精神。', `MaleText_loc5`='你沒聽說過「每月啤酒」俱樂部?那裡的女孩們真的很愛開派對。她們的興趣只要持續下去，啤酒節就永遠不會結束!去年就有些時候，感覺啤酒節好像還沒結束。$b$b如今，她們發現，讓啤酒節的精神繼續下去的最好方法，就是讓大家加入她們的俱樂部。$b$b只要花一點點錢，幾個獎品章，你就能加入了!你每個月都可以從信箱裡收到啤酒，要是你喜歡的話，你可以額外買啤酒。這真是劃時代的東西，還可以確保啤酒節的精神永遠不會消失。', `MaleText_loc7`='¿No has oído hablar del Club "de la Cerveza del Mes?" A esos tipos les encanta estar de fiesta. ¡Si fuera por ellos, la Fiesta de la Cerveza nunca acabaría! A veces, la del año pasado parecía no haber acabado.$B$BPero ahora han llegado a la conclusión de que la mejor manera de mantener vivo el espíritu de la Fiesta de la Cerveza es permitir que la gente se una a su club.$B$B¡Puedes unirte por solo unas fichas! Todos los meses se te enviará cerveza y podrás comprar esa misma cerveza si te gusta. Se trata de material de máxima calidad y es una forma de asegurarse de que el espíritu de la Fiesta de la Cerveza no se vaya nunca.', `FemaleText_loc1`='맥주 사랑 동호회를 모른단 말이에요? 여기 아가씨들은 흥청망청 노는 걸 정말 좋아하네요. 아마 아가씨들 방식대로 놀았다간 가을 축제가 절대로 끝이 안 났을 거예요! 작년부터 가끔 가을 축제답지 않다는 생각이 들더군요.$b$b동호회에서는 가을 축제 정신을 이어가려면 회원을 더 모집해야 한다는 걸 깨달았어요.$b$b회비 조금하고 상품 교환 동전 몇 개만 있으면 가입할 수 있답니다! 매달 맥주가 우편으로 배달되고, 그 맥주가 입맛에 맞으면 더 살 수도 있어요. 이건 정말 끝내주는 조건이지 뭐예요. 가을 축제 정신도 계속 이어나갈 수 있고 말이에요.', `FemaleText_loc4`='你还不知道“本月美酒俱乐部”？那些家伙最喜欢聚会。如果他们能想到合适的办法，美酒节将会永不落幕！去年他们就曾希望美酒节不要结束。$b$b但现在他们找到了更好地发扬美酒节精神的方法，那就是让人们加入他们的俱乐部。$b$b你只需要付出很少的费用，只需要几张美酒节奖币，你就能加入了！会员每个月都会收到俱乐部邮寄来的酒样，还可以购买自己喜欢的啤酒。这个精英俱乐部能永远继承美酒节的精神。', `FemaleText_loc5`='你沒聽說過「每月啤酒」俱樂部?那裡的女孩們真的很愛開派對。她們的興趣只要持續下去，啤酒節就永遠不會結束!去年就有些時候，感覺啤酒節好像還沒結束。$b$b如今，她們發現，讓啤酒節的精神繼續下去的最好方法，就是讓大家加入她們的俱樂部。$b$b只要花一點點錢，幾個獎品章，你就能加入了!你每個月都可以從信箱裡收到啤酒，要是你喜歡的話，你可以額外買啤酒。這真是劃時代的東西，還可以確保啤酒節的精神永遠不會消失。', `FemaleText_loc7`='¿No has oído hablar del Club "de la Cerveza del Mes?" A esos tipos les encanta estar de fiesta. ¡Si fuera por ellos, la Fiesta de la Cerveza nunca acabaría! A veces, la del año pasado parecía no haber acabado.$B$BPero ahora han llegado a la conclusión de que la mejor manera de mantener vivo el espíritu de la Fiesta de la Cerveza es permitir que la gente se una a su club.$B$B¡Puedes unirte por solo unas fichas! Todos los meses se te enviará cerveza y podrás comprar esa misma cerveza si te gusta. Se trata de material de máxima calidad y es una forma de asegurarse de que el espíritu de la Fiesta de la Cerveza no se vaya nunca.' WHERE `ID`=26762;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 누군가는 우리에게서 땅을 빼앗으려 하느니. 지느러미를 가진 사냥꾼이 이 땅에 들어앉아 사슴뿔이 난 짐승을 게걸스럽게 먹어치우는구나.', `MaleText_loc4`='有的想要夺取陆地的控制权。那些盘踞在苔原地带的鳄鱼人大肆掠夺我们赖以为生的猎物。', `MaleText_loc5`='有人想把土地從我們這裡奪走。那些有鰭的獵人盤據了平原，吞噬著鹿角一族。', `MaleText_loc7`='Algunos quieren quitarnos la tierra. Los cazadores con aletas han ocupado las llanuras y devoran a los que tienen cornamenta.' WHERE `ID`=26763;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저주가 풀렸다!', `MaleText_loc4`='诅咒已经解除！', `MaleText_loc5`='詛咒解除了!', `MaleText_loc7`='¡La maldición ha sido levantada!', `FemaleText_loc1`='저주가 풀렸다!', `FemaleText_loc4`='诅咒已经解除！', `FemaleText_loc5`='詛咒解除了!', `FemaleText_loc7`='¡La maldición ha sido levantada!' WHERE `ID`=26764;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='텔잔의 마법이 풀렸다! 이제 안전하다!', `MaleText_loc4`='塞尔赞的魔法失效了！我安全了！', `MaleText_loc5`='賽爾贊的魔法被破解了!我安全了!', `MaleText_loc7`='¡El encantamiento de Thel''zan se ha roto! ¡Estoy a salvo!', `FemaleText_loc1`='텔잔의 마법이 풀렸다! 이제 안전하다!', `FemaleText_loc4`='塞尔赞的魔法失效了！我安全了！', `FemaleText_loc5`='賽爾贊的魔法被破解了!我安全了!', `FemaleText_loc7`='¡El encantamiento de Thel''zan se ha roto! ¡Estoy a salvo!' WHERE `ID`=26765;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 또한 사냥꾼. 우리는 전사. 우리는 바다와 땅을 위해 싸울 수 있노라.', `MaleText_loc4`='我们同样拥有猎手的敏捷和战士的勇气。我们愿意为了保卫家园而战。', `MaleText_loc5`='但我們也是獵人。我們是戰士。我們可以為了大海與土地而戰。', `MaleText_loc7`='Somos cazadores también. Somos luchadores. Podemos luchar por el mar y la tierra.' WHERE `ID`=26766;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 고서엔 무슨 내용이 담겨 있을까?', `MaleText_loc4`='这本魔典到底隐藏着什么秘密？', `MaleText_loc5`='這本書能藏著什麼?', `MaleText_loc7`='¿Qué podría ocultar este libro?', `FemaleText_loc1`='이 고서엔 무슨 내용이 담겨 있을까?', `FemaleText_loc4`='这本魔典到底隐藏着什么秘密？', `FemaleText_loc5`='這本書能藏著什麼?', `FemaleText_loc7`='¿Qué podría ocultar este libro?' WHERE `ID`=26767;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='텔잔은 날 막을 수 없다! 얼라이언스를 위해! 폴드라곤 경을 위해!', `MaleText_loc4`='塞尔赞再也无法阻止我了！为了联盟！为了弗塔根公爵！', `MaleText_loc5`='賽爾贊無法阻止我!為了聯盟!為了弗塔根大人!', `MaleText_loc7`='¡Thel''zan no puede detenerme! ¡Por la Alianza! ¡Por Lord Fordragón!', `FemaleText_loc1`='텔잔은 날 막을 수 없다! 얼라이언스를 위해! 폴드라곤 경을 위해!', `FemaleText_loc4`='塞尔赞再也无法阻止我了！为了联盟！为了弗塔根公爵！', `FemaleText_loc5`='賽爾贊無法阻止我!為了聯盟!為了弗塔根大人!', `FemaleText_loc7`='¡Thel''zan no puede detenerme! ¡Por la Alianza! ¡Por Lord Fordragón!' WHERE `ID`=26768;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='허나 투스카르에게 또 다른 위협이 있느니.', `MaleText_loc4`='但是，海象人氏族即将面临新的威胁。', `MaleText_loc5`='但還有另一種東西威脅著牙之民。', `MaleText_loc7`='Pero hay otra amenaza para la gente con colmillos.' WHERE `ID`=26769;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맥주 사랑 동호회가 무엇인가요?', `MaleText_loc4`='“本月美酒俱乐部”是什么东西？', `MaleText_loc5`='什麼是「每月啤酒」俱樂部?', `MaleText_loc7`='¿Qué es el "Club de la Cerveza del Mes"?', `FemaleText_loc1`='맥주 사랑 동호회가 뭐지요?', `FemaleText_loc4`='“本月美酒俱乐部”是什么东西？', `FemaleText_loc5`='什麼是「每月啤酒」俱樂部?', `FemaleText_loc7`='¿Qué es el "Club de la Cerveza del Mes"?' WHERE `ID`=26770;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맥주 사랑 동호회를 모른단 말이오? 그건 깜찍한 친구들이 일 년 내내 가을 축제를 벌이고 싶어서 만든 모임이지! 이전에도 가을 축제를 되살리려고 했지만, 오래가지는 못했소이다.$b$b동호회에 가입하면 달마다 다른 맥주가 배달된다오! 그 맥주가 입맛에 맞으면 아이언포지에 있는 상인에게 가서 더 살 수도 있소.$b$b당신도 이 동호회에 가입할 만큼 깜찍하군. 상품 교환 동전을 좀 모아오면 가입 신청서를 주겠소. 그러고서 일 년 내내 가을 축제를 함께 즐깁시다!', `MaleText_loc4`='你还不知道“本月美酒俱乐部”？那是一群希望天天都是美酒节的可爱家伙！过去他们一直希望让美酒节回归，但每次持续的时间都不长。$b$b一旦你加入了这个俱乐部，每个月都能收到俱乐部邮寄来的最新酒样！如果你喜欢某种啤酒，可以到铁炉堡向商人购买。$b$b我觉得你也非常可爱，完全有资格加入这个俱乐部。只要给我一些美酒节奖币，我就会给你加入的申请表。然后我们或许就能天天一起庆祝美酒节了！', `MaleText_loc5`='你沒聽說過「每月啤酒」俱樂部?那是一群非常可愛的傢伙為了整年慶祝啤酒節創立的!他們試著重現過去的啤酒節，不過總是持續不久。$b$b一旦你加入了俱樂部，每個月他們都會寄不同的酒給你!如果你喜歡那種酒的話，你可以和鐵爐堡的小販多買一點。$b$b我覺得你也可愛的足以加入俱樂部。給我一些獎品章，我就會給你申請表。然後我們就可以一起整年慶祝啤酒節!', `MaleText_loc7`='¿No has oído hablar del Club "de la Cerveza del Mes?" ¡Son un montón de tipos muy guapos que quieren celebrar la Fiesta de la Cerveza durante todo el año! Intentaron volver a traer la Fiesta de la Cerveza en el pasado, pero nunca duró demasiado.$B$BCuando te hayas unido al Club, se te enviará por correo una cerveza diferente cada mes. Si te gusta esa cerveza, puedes hablar con los vendedores de Forjaz para conseguir más.$B$BCreo que tienes belleza suficiente para unirte al Club. Tú me das unas cuantas fichas y yo te daré los formularios. ¡Quizá podamos celebrar la Fiesta de la Cerveza juntos durante todo el año!', `FemaleText_loc1`='맥주 사랑 동호회를 모른단 말이에요? 그건 깜찍한 친구들이 일 년 내내 가을 축제를 벌이고 싶어서 만든 모임이라고요! 이전에도 가을 축제를 되살리려고 했지만, 오래가지는 못했답니다.$b$b동호회에 가입하면 달마다 다른 맥주가 배달된대요! 그 맥주가 입맛에 맞으면 아이언포지에 있는 상인에게 가서 더 살 수도 있지요.$b$b당신도 이 동호회에 가입할 만큼 깜찍하군요. 상품 교환 동전을 좀 모아오면 가입 신청서를 드리겠어요. 그리고서 일 년 내내 가을 축제를 함께 즐기자고요!', `FemaleText_loc4`='你还不知道“本月美酒俱乐部”？那是一群希望天天都是美酒节的可爱家伙！过去他们一直希望让美酒节回归，但每次持续的时间都不长。$b$b一旦你加入了这个俱乐部，每个月都能收到俱乐部邮寄来的最新酒样！如果你喜欢某种啤酒，可以到铁炉堡向商人购买。$b$b我觉得你也非常可爱，完全有资格加入这个俱乐部。只要给我一些美酒节奖币，我就会给你加入的申请表。然后我们或许就能天天一起庆祝美酒节了！', `FemaleText_loc5`='你沒聽說過「每月啤酒」俱樂部?那是一群非常可愛的傢伙為了整年慶祝啤酒節創立的!他們試著重現過去的啤酒節，不過總是持續不久。$b$b一旦你加入了俱樂部，每個月他們都會寄不同的酒給你!如果你喜歡那種酒的話，你可以和鐵爐堡的小販多買一點。$b$b我覺得你也可愛的足以加入俱樂部。給我一些獎品章，我就會給你申請表。然後我們就可以一起整年慶祝啤酒節!', `FemaleText_loc7`='¿No has oído hablar del Club "de la Cerveza del Mes?" ¡Son un montón de tipos muy guapos que quieren celebrar la Fiesta de la Cerveza durante todo el año! Intentaron volver a traer la Fiesta de la Cerveza en el pasado, pero nunca duró demasiado.$B$BCuando te hayas unido al Club, se te enviará por correo una cerveza diferente cada mes. Si te gusta esa cerveza, puedes hablar con los vendedores de Forjaz para conseguir más.$B$BCreo que tienes belleza suficiente para unirte al Club. Tú me das unas cuantas fichas y yo te daré los formularios. ¡Quizá podamos celebrar la Fiesta de la Cerveza juntos durante todo el año!' WHERE `ID`=26771;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 잠시 고개를 숙이고 생각에 잠깁니다.', `MaleText_loc4`='%s低下头整理着思绪。', `MaleText_loc5`='%s低下頭好一會兒，想整理他的思緒。', `MaleText_loc7`='%s agacha la cabeza un instante para ordenar sus pensamientos.' WHERE `ID`=26772;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살아 있는 모든 존재 사이에 힘이 흘러, 그 힘은 이름이 여러 개라.', `MaleText_loc4`='万物体内都涌动着某种神秘的魔法力量。它有许多不同的称呼。', `MaleText_loc5`='有一種力量在所有的活物之間流動。它有著許多不同的名字。', `MaleText_loc7`='Hay una energía que fluye por todas las cosas que están vivas. Tiene muchos nombres.' WHERE `ID`=26773;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='투스카르는 그것을 실랍 이누아라고 부르니라.', `MaleText_loc4`='海象人氏族称其为“希拉伊努亚”。', `MaleText_loc5`='牙之民稱它為西拉波·印努亞。', `MaleText_loc7`='Los de los colmillos lo llaman Silap Inua.' WHERE `ID`=26774;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생각하는 모든 존재가 이 힘을 끌어내 치유하고 상처입히니, 이는 바로 생명의 힘, 산 자와 죽은 자의 영혼이 지닌 힘이라.', `MaleText_loc4`='所有的智慧生物都能支配这种力量，利用它来医治创伤或是荼毒生灵。它就是生命的源力，是死者与生者的灵魂之力。', `MaleText_loc5`='這種力量被所有的能思考的種族用來治療或造成傷害。這是生命的力量。這是生者與死者靈魂的力量。', `MaleText_loc7`='Esa energía puede ser usada por todas las personas que piensan para curar o dañar. Es la energía de la vida. Es la energía de las almas vivas y muertas.' WHERE `ID`=26775;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실랍 이누아를 위협하는 자들이 있어 그를 가두려 한다 알려졌으니. 이들을 푸른 비늘이라 칭하노라.', `MaleText_loc4`='世间唯有一种生物能束缚“希拉伊努亚”，由此引发了诸多祸端。他们被称为蓝龙一族。', `MaleText_loc5`='西拉波·印努亞的威脅來自於想要限制它的人。他們被稱為藍鱗族。', `MaleText_loc7`='Es sabido que los seres de escamas azules han amenazado con enjaular a Silap Inua.' WHERE `ID`=26776;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='푸른 비늘에 강대한 힘이 있어, 실랍 이누아를 거두어 온 세상 이에게서 빼앗으려 하느니.', `MaleText_loc4`='强大的蓝龙拥有操纵“希拉伊努亚”的能力，他们计划将这种力量从其他生物体内夺走。', `MaleText_loc5`='藍鱗族有著強大的力量。他們致力於控制西拉波·印努亞，並且將它從世界上不同的人們身上奪走。', `MaleText_loc7`='Los seres de escamas azules tienen mucho poder. Intentan controlar a Silap Inua y obtienen su fuerza de las diferentes gentes del mundo.' WHERE `ID`=26777;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이는 투스카르뿐 아니라 숨 쉬는 모든 존재에 대한 위협이니라.', `MaleText_loc4`='这不仅是对海象人氏族的威胁，更是将世间的生灵推上了绝路。', `MaleText_loc5`='他們不只威脅了牙之民，而是這世間所有生命的存在。', `MaleText_loc7`='No solo amenazan a las costumbres de la gente con colmillos, sino a la existencia de todos los que viven.' WHERE `ID`=26778;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 납골당에서 시체들이 일어나고 있습니다!', `MaleText_loc4`='那些亡灵竟然来自我们的墓地！', `MaleText_loc5`='死者從他們自己的墓穴中甦醒!', `MaleText_loc7`='¡Los muertos se levantan de nuestra propia cripta!' WHERE `ID`=26779;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 이 이야기를 전하노라.', `MaleText_loc4`='让我告诉你们。', `MaleText_loc5`='這就是我說的故事。', `MaleText_loc7`='Os ofrezco esta historia.' WHERE `ID`=26780;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무사하셨군요! 죽을 줄로만 알았습니다!', `MaleText_loc4`='你做到啦！我还以为你会赔上性命呢！', `MaleText_loc5`='你辦到了$g小夥子:小姑娘;!我以為你老早就死了!', `MaleText_loc7`='¡Lo lograste, $g chico:chica;! ¡Pensé que estabas en las últimas!' WHERE `ID`=26781;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 혈육을 위협하는 자들과, 우리 새끼를 죽일 자들과 싸워야 하리니. 우리를 스스로 보살펴야 하니라.', `MaleText_loc4`='我们必须勇敢地战斗，否则敌人将会屠杀我们的孩子，彻底抹去海象人氏族存在过的痕迹。我们必须凭借自己的力量拯救整个氏族。', `MaleText_loc5`='我們一定要對抗那些威脅我們的同胞，那些會傷害我們孩童的勢力。我們一定要自立自強。', `MaleText_loc7`='Debemos luchar contra aquellos que amenacen a nuestra carne, aquellos que matarían a nuestros hijos; debemos proteger a los nuestros.' WHERE `ID`=26782;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러나 남쪽에서 온 무리에 도움을 아끼지 말지어다. 이는 실랍 이누아가 보낸 용사들이라...', `MaleText_loc4`='与此同时，我们应该竭尽全力帮助来自南方的人们，因为他们就是“希拉伊努亚”的勇士。', `MaleText_loc5`='但你可以協助南方的人，他們是西拉波·印努亞的勇士。', `MaleText_loc7`='Pero ayudad en lo que podáis a los pueblos del sur, ya que son los campeones de Silap Inua.' WHERE `ID`=26783;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직도 여기 계셨습니까? 어서 마을로 돌아가십시오!', `MaleText_loc4`='你还在这里干什么呢？赶紧回到镇上去！', `MaleText_loc5`='你還在這裡做什麼?快回鎮上去!', `MaleText_loc7`='¿Qué haces aquí todavía? ¡Vuelve a la ciudad!' WHERE `ID`=26784;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형제여, 내가 치료해 주겠다. 곧 다시 싸울 수 있을 게다.', `MaleText_loc4`='让我来治疗你吧。你很快就能重返战场啦。', `MaleText_loc5`='我把你治好了，兄弟。你很快就可以進行下一場戰鬥。', `MaleText_loc7`='Os curaré, colegas. Preparaos para otra batalla pronto.' WHERE `ID`=26785;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 토템이 치유해 줄 게다, 형제들이여.', `MaleText_loc4`='我的图腾能治愈你的创伤。', `MaleText_loc5`='我的圖騰治癒了你，好兄弟。', `MaleText_loc7`='Mi tótem os curará bien, colegas.' WHERE `ID`=26786;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스컬지 놈들은 자신들이 감히 누굴 건드렸는지 모르고 있다!', `MaleText_loc4`='天灾军团竟敢招惹我们！', `MaleText_loc5`='天譴軍團不知道他們惹火了誰!', `MaleText_loc7`='¡La Plaga no sabe a quién se enfrenta!' WHERE `ID`=26787;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='목숨을 바쳐 이곳을 지키자!', `MaleText_loc4`='我们誓死保卫家园！', `MaleText_loc5`='我們用生命守住這個地方，老兄!', `MaleText_loc7`='¡Defendemos este lugar con nuestras vidas!' WHERE `ID`=26788;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황제께서 이곳을 지켜야 한다고 말씀하셨다!', `MaleText_loc4`='皇帝陛下命令我们死也要守住这里！', `MaleText_loc5`='皇帝說我要守住這個位置，老兄!', `MaleText_loc7`='¡El Emperador dice que hay que mantener esta posición!' WHERE `ID`=26789;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 땅을 빼앗을 수 있을 줄 아는 모양이지? 스컬지 놈들은 우리를 잘못 알고 있어!', `MaleText_loc4`='天灾军团想要侵占我们的土地？给他们点颜色瞧瞧！', `MaleText_loc5`='天譴軍團以為可以佔據我們的土地?他們不知道自己在對付誰!', `MaleText_loc7`='¿La Plaga cree que puede quedarse con nuestra tierra? ¡No saben con quién están tratando!' WHERE `ID`=26790;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 곧 반격할 것이다!', `MaleText_loc4`='我们做好了反击的准备！', `MaleText_loc5`='我們很快就會準備好反擊!', `MaleText_loc7`='¡Nosotros estar listos para devolver ataque pronto!' WHERE `ID`=26791;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 곧 반격할 것이다!', `MaleText_loc4`='我们做好了反击的准备！', `MaleText_loc5`='我們很快就會準備好反擊!', `MaleText_loc7`='¡Nosotros estar listos para devolver ataque pronto!' WHERE `ID`=26792;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스컬지를 막아라!', `MaleText_loc4`='阻止天灾军团！', `MaleText_loc5`='阻止天譴軍團!', `MaleText_loc7`='¡Detener a la Plaga!' WHERE `ID`=26793;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 지나갈 수 없다!', `MaleText_loc4`='休想过去！', `MaleText_loc5`='你不能通過，老兄!', `MaleText_loc7`='¡No puedes pasar, colega!' WHERE `ID`=26794;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='청지기님, 비룡을 타고 요새 꼭대기에 있는 여왕님의 방으로 가고 싶습니다.', `MaleText_loc4`='塔里奥斯塔兹，请允许我搭乘龙兽前往神殿顶端女王陛下的王廷。', `MaleText_loc5`='管理者，請讓我騎上一隻飛龍，前往女王在神殿頂端的房間。', `MaleText_loc7`='Administrador, permítame montar uno de los dracos para llegar a la cámara de la reina, en lo alto del templo.', `FemaleText_loc1`='청지기님, 비룡을 타고 요새 꼭대기에 있는 여왕님의 방으로 가고 싶습니다.', `FemaleText_loc4`='塔里奥斯塔兹，请允许我搭乘龙兽前往神殿顶端女王陛下的王廷。', `FemaleText_loc5`='管理者，請讓我騎上一隻飛龍，前往女王在神殿頂端的房間。', `FemaleText_loc7`='Administrador, permítame montar uno de los dracos para llegar a la cámara de la reina, en lo alto del templo.' WHERE `ID`=26795;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코도들의 상태가 놀랄 만큼 좋군.', `MaleText_loc4`='这些科多兽的状况好极了。', `MaleText_loc5`='這些科多獸的狀況絕佳。', `MaleText_loc7`='Los kodos están en unas condiciones increíbles.' WHERE `ID`=26796;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇군. 내가 들은 바로는 노련한 호드의 용사가 죽기 직전이었던 녀석들을 살려냈다고 하오.', `MaleText_loc4`='是啊，听说是位部落老兵将它们从濒死边缘救回来的。', `MaleText_loc5`='的確，我聽說牠們在部落有經驗的老手照料之下，從垂死邊緣恢復過來。', `MaleText_loc7`='Sin duda, he oído que fueron rescatados al borde de la muerte por un experimentado veterano de la Horda.' WHERE `ID`=26797;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알렉스트라자 여왕님께서 내게 고룡쉼터 사원의 방어 임무를 맡기셨소.$B$B당신도 알다시피 말리고스와 그의 부대가 근처에 있는 지맥을 파괴했소. 그러고는 그 힘을 청금석 용제단으로 돌려버렸지.$B$B푸른용군단은 자신의 힘을 늘리는 데 지맥의 힘을 사용하고 있소. 감히 이 요새를 공격하려고 말이오! 전세는 푸른용군단에 유리하오.$B$B우리를 도우러 온 거요, $r?', `MaleText_loc4`='阿莱克丝塔萨女王任命我负责龙眠神殿的防务工作。$B$B但如你所知，玛里苟斯和他的军团摧毁了附近一处魔网能量线的锚点。蓝龙军团将其中的能量导向了碧蓝巨龙圣地。$B$B毫无疑问，他们是想利用这种能量强化自己，伺机向神殿发动攻击！我们已渐渐处于劣势。$B$B$r，你愿意帮助我们吗？', `MaleText_loc5`='龍后雅立史卓莎任命我負責龍眠神殿的防禦工事。$B$B如你所知，瑪里苟斯透過他的部隊摧毀了附近的一個地脈錨點。藍龍軍團將那些能量導向蒼藍龍殿。$B$B藍龍透過那些能量強化他們自己，能量強大到讓他們膽敢攻擊神殿本體!他們已經佔了上風。$B$B你願意協助我們嗎，$r?', `MaleText_loc7`='La reina Alexstrasza me ha encargado la defensa del Templo del Reposo del Dragón.$B$BComo ya sabes, Malygos ordenó a sus tropas que destruyeran el ancla de una línea Ley cercana. Entonces, las fuerzas del Vuelo redirigieron ese poder hacia el Santuario de Dragones Azur.$B$BLos dragones Azules están usando ese poder para fortalecerse; ¡tanto que se atreven a atacar el mismísimo templo! Están empezando a tener ventaja.$B$B¿Estás aquí para ayudarnos, $r?' WHERE `ID`=26798;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 길 잃은 영혼을 위해 기도를 올립니다.', `MaleText_loc4`='%s为迷失的灵魂念诵了一段祷言。', `MaleText_loc5`='%s為迷失的靈魂念了一段禱詞。', `MaleText_loc7`='%s reza una oración por el alma perdida.' WHERE `ID`=26799;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물러나 계십시오, $n. 저 짐승이 달려들어 당신을 해칠지도 모릅니다.', `MaleText_loc4`='退后点，$n。这头野兽可能会突然暴起伤人。', `MaleText_loc5`='退後，$n，那隻野獸或許會突然暴衝，傷害到你。', `MaleText_loc7`='Aléjate, $n, la bestia podría atacar y herirte.' WHERE `ID`=26800;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고드프리! 내 말을 들어라, 악마여! 내 말을 들어라, 내가 빛을 대신하여 너를 악으로부터 구해주겠다!', `MaleText_loc4`='高弗雷！你这恶魔！你听仔细了！我要代表圣光将你从邪恶中拯救出来！', `MaleText_loc5`='高佛雷!聽著，魔鬼!聽我說，我乃是聖光的化身，來此讓你脫離邪惡!', `MaleText_loc7`='¡GODFREY! ¡Escúchame, demonio! ¡Escúchame, pues yo soy la Luz y te liberaré del mal!' WHERE `ID`=26801;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 으르렁거립니다.', `MaleText_loc4`='%s咆哮着。', `MaleText_loc5`='%s發出嚎叫。', `MaleText_loc7`='%s gruñe.' WHERE `ID`=26802;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아. 이제 말을 들을 준비가 되었나, 고드프리?', `MaleText_loc4`='很好。高弗雷，你肯听我说话了。', `MaleText_loc5`='很好。你注意到我了，對吧，高佛雷?', `MaleText_loc7`='Bien. Entonces, ¿me prestarás atención, Godfrey?' WHERE `ID`=26803;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 취할 방법에는 두 가지가 있다, 고드프리. 첫 번째 방법은 네가 이 책에 기록된 부정한 문자를 해독해 달라는 내 요청을 들어주기만 하면 된다. 어떻게 하겠나?', `MaleText_loc4`='高弗雷，这事儿吧有两种解决方式，我更喜欢开门见山的做法。你看，不如你直接告诉我秘典上的邪恶符号是什么含义。怎么样？', `MaleText_loc5`='我們有兩種方法解決這件事，高佛雷。一種呢，我會直接請你告訴我，刻在書頁上的穢惡符號是什麼意思。你覺得如何?', `MaleText_loc7`='Podemos hacer esto de dos maneras, Godfrey. Primero te preguntaré qué significan los impíos símbolos grabados en las páginas de este libro. ¿Qué me dices?' WHERE `ID`=26804;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 위협적인 소리를 냅니다!', `MaleText_loc4`='%s发出嘶嘶声。', `MaleText_loc5`='%s嗤之以鼻!', `MaleText_loc7`='¡%s silba!' WHERE `ID`=26805;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈 따위에게 할 말 없다, 설교자 녀석.', `MaleText_loc4`='我不会告诉你的，你这神棍。', `MaleText_loc5`='什麼也不會告訴你，傳教士。', `MaleText_loc7`='No te diré nada, predicador.' WHERE `ID`=26806;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='켈투자드 님도 하지 못하셨고 리치 왕께서도 하지 못할 일을 네가 어떻게 하겠다는 거냐?', `MaleText_loc4`='你能把我怎么样？你莫非比克尔苏加德更残忍？比巫妖王更厉害？', `MaleText_loc5`='你能對我做什麼是科爾蘇加德做不出來的?或是巫妖王也做不到的?', `MaleText_loc7`='¿Qué puedes hacerme que no me haya hecho Kel''Thuzad? ¿Que no me vaya a hacer el Rey Exánime?' WHERE `ID`=26807;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고서는 널 구원할 수 있겠지. 그래... 하지만 넌 아무것도 알아낼 수 없다! 난 아무것도 말하지 않을 거다! 아무것도!', `MaleText_loc4`='你说得没错，这本秘典是拯救你们的唯一希望……但是你永远无法知道真相了！我什么都不会说！', `MaleText_loc5`='那本書是你的救贖，沒錯...但你什麼也不知道!我什麼也不說!絕不!', `MaleText_loc7`='El libro es tu salvación, sí... ¡pero no sabrás nada! ¡TE DIGO QUE NADA! ¡NADA!' WHERE `ID`=26808;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇다면 두 번째 방법을 써야겠군.', `MaleText_loc4`='好吧，那我就要用第二种解决方式了。', `MaleText_loc5`='還有第二種方法。', `MaleText_loc7`='Entonces que sea la opción dos.' WHERE `ID`=26809;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너를 위한 기도를 올리겠다, 길 잃은 영혼이여. 빛이 너를 거두어 가시길.', `MaleText_loc4`='迷失的灵魂，我会为你念上一段祷言。愿圣光拥你入怀。', `MaleText_loc5`='我為你念一段禱詞，迷失的靈魂。願聖光溫柔地接納你。', `MaleText_loc7`='Ahora rezaré por ti, alma perdida. Que la Luz te acoja con gracia.' WHERE `ID`=26810;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 설교를 시작하지.', `MaleText_loc4`='训诫开始。', `MaleText_loc5`='讓佈道開始吧。', `MaleText_loc7`='Que comience el sermón.' WHERE `ID`=26811;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛이 너를 거두리라, 악마여!', `MaleText_loc4`='让圣光拥抱你吧，野兽！', `MaleText_loc5`='願聖光接納你，野獸!', `MaleText_loc7`='¡QUE LA LUZ TE LLEVE, BESTIA!' WHERE `ID`=26812;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛의 힘으로 널 굴복시키리라!', `MaleText_loc4`='屈服在圣光的力量下吧！', `MaleText_loc5`='願聖光的力量使你折服!', `MaleText_loc7`='¡Que el poder de la Luz te fuerce!' WHERE `ID`=26813;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛을 받아들여라, 고드프리 구다르!', `MaleText_loc4`='让圣光渗入你的灵魂，高弗雷！', `MaleText_loc5`='讓聖光進入你，高佛雷·古達!', `MaleText_loc7`='¡DEJA QUE ENTRE LA LUZ, GODFREY GOODARD!' WHERE `ID`=26814;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저항하지 마라, 악마야! 지금이 바로 속죄할 때다!', `MaleText_loc4`='别抵抗了，恶魔！赎罪的时候到了！', `MaleText_loc5`='不要抗拒我，魔鬼!你贖罪的時候到了!', `MaleText_loc7`='¡No luches contra mí, demonio! ¡Este es el momento de tu expiación!' WHERE `ID`=26815;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성스러운 불꽃으로 타올라라!', `MaleText_loc4`='在圣火中化为灰烬吧！', `MaleText_loc5`='在神聖之火中燃燒!', `MaleText_loc7`='¡ARDE EN EL FUEGO SAGRADO!' WHERE `ID`=26816;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕의 힘이 빛의 영광 앞에서 점차 사그라질 것이니!', `MaleText_loc4`='在辉煌的圣光面前，巫妖王的力量显得苍白无力！', `MaleText_loc5`='巫妖王的力量在聖光的榮耀之前微不足道!', `MaleText_loc7`='¡El poder del Rey Exánime palidece al ser comparado con la gloria de la Luz!' WHERE `ID`=26817;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뜨거워어어어!', `MaleText_loc4`='火焰！！！', `MaleText_loc5`='好燙!', `MaleText_loc7`='¡QUEMA!' WHERE `ID`=26818;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아파서 참을 수가 없어!', `MaleText_loc4`='难以忍受的痛苦！', `MaleText_loc5`='痛死我啦!', `MaleText_loc7`='¡El dolor es insoportable!' WHERE `ID`=26819;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만! 그마아안!', `MaleText_loc4`='住手！快住手！', `MaleText_loc5`='快停止!停下來!', `MaleText_loc7`='¡Haz que pare! ¡HAZ QUE PARE!' WHERE `ID`=26820;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐든지 말해주마!', `MaleText_loc4`='我说，什么都说！', `MaleText_loc5`='你要知道什麼，我全都說!', `MaleText_loc7`='¡Te diré lo que quieras!' WHERE `ID`=26821;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛은 저리 치워! 그만! 부탁이다!', `MaleText_loc4`='圣光！不要！求求你！', `MaleText_loc5`='別再是聖光!拜託不要!我求你!', `MaleText_loc7`='¡No más LUZ! ¡NO MÁS! ¡TE LO RUEGO!' WHERE `ID`=26822;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아파서 못 견디겠어!', `MaleText_loc4`='我从未体验过这样的煎熬！', `MaleText_loc5`='從來沒有這麼痛過!', `MaleText_loc7`='¡Nunca había sentido un dolor así!' WHERE `ID`=26823;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 빛을 볼 수 있을 거로 생각했다, 고드프리... 어서 말해라, 이 악마 같으니. 뭐라고 적혀 있지?', `MaleText_loc4`='高弗雷，你已经见识到圣光的力量了……恶魔，说吧。秘典上都写了些什么？', `MaleText_loc5`='我以為你會看見聖光，高佛雷...現在快說，魔鬼。到底這個在寫什麼?', `MaleText_loc7`='Sabía que verías la Luz, Godfrey... Ahora habla deprisa, demonio. ¿Qué dice?' WHERE `ID`=26824;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앞으로 다가올 종말에 대해 이야기한다. 이 세계가 어떻게 불타 사라지고 어떻게 파멸에서 다시 태어나는지가 적혀 있다.', `MaleText_loc4`='秘典中记载了即将到来的天启。世界将在灰烬中毁灭，然后重获新生。', `MaleText_loc5`='它說這即將到來的啟示。這個世界將如何毀滅，然後再從死亡中重生。', `MaleText_loc7`='Habla sobre la llegada del apocalipsis. Sobre cómo arderá este mundo y renacerá de la muerte.' WHERE `ID`=26825;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말도 안 되는 소리! 고드프리, 내가 무슨 바보인 줄 아는가? 스컬지들의 선전 문구를 빛을 섬기는 자에게 늘어놓다니! 지금 말하지 않으면 하인들을 시켜 이가 들끓는 개처럼 성수로 목욕을 시켜주마!', `MaleText_loc4`='一派胡言！高弗雷，你当我是傻子吗？别拿天灾军团那套邪说来恐吓圣光的战士！你放聪明点，不然我就叫人把你丢进装满圣水的木桶，像给狗除跳蚤那样让你冲个圣水浴！', `MaleText_loc5`='鬼扯!高佛雷你把我當成傻瓜嗎?少對一個聖光之徒散播你那些天譴思想，異教徒!現在就給我說，否則我就讓人準備個聖水浴，像是替狗除跳蚤一樣把你浸下去!', `MaleText_loc7`='¡BASURA! Godfrey, ¿me tomas por tonto? ¡No escupas tu propaganda de la Plaga a un hombre de la Luz, infiel! ¡Habla ahora o haré que los campesinos preparen una bañera de agua sagrada y te remojaré dentro como a un perro pulgoso!' WHERE `ID`=26826;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안돼애애!!! 말한다! 뭐든지 다 말한다!', `MaleText_loc4`='不要啊！！！我说！我什么都说！！！', `MaleText_loc5`='不不不!我告訴你!我什麼都說!', `MaleText_loc7`='¡¡¡NOOOO!!! ¡Te lo contaré! ¡Te lo contaré todo!' WHERE `ID`=26827;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='인간들은... 윈터가드 마을 지하에 묘지를 만들어 놓았지! 낙스라마스가 왜 그곳을 공격했는지 모르겠나? 텔잔 님은 너희의 납골당에 숨은 채로 너희에게 수천 구의 시체를 올려 보내고 계신다! 너희는 패하게 돼 있어...', `MaleText_loc4`='人类……自作孽。纳克萨玛斯为什么会攻击这里？就因为你们在暮冬城地下建起的陵墓！塞尔赞躲在你们的墓穴中，唤醒成千上万的僵尸与你们为敌！你们将被毁灭……', `MaleText_loc5`='人類...你們在溫特加德村之下建立了一個墓塚!你以為為什麼納克薩瑪斯要攻擊這個地方?賽爾贊躲在你們墓穴的深處，派出成千上萬的屍體攻擊你!你等死吧...', `MaleText_loc7`='Humanos... ¡Construyeron un mausoleo bajo Hibergarde! ¿Por qué creen que Naxxramas atacó ese lugar? ¡Thel''zan se esconde en las profundidades de su propia cripta y les envía miles y miles de cadáveres! Morirán...' WHERE `ID`=26828;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐? 그 오래된 마을 지하에 묘지가 있다고? 어리석게도 여태껏 그것도 모르고 있었다니! 반드시 그곳을 찾아서 네 주인을 쓰러트려 주겠다, 고드프리. 이 악몽을 반드시 끝내고야 말겠어.', `MaleText_loc4`='什么！？暮冬城旧址下面有一座陵墓？我们对此事竟然毫不知情！高弗雷，我们会消灭你的主子，结束这场噩梦。', `MaleText_loc5`='什麼?在老村子底下有座陵墓?我們怎麼會笨到沒發現!高佛雷，我們現在就要把你主人找出來，然後消滅他!我們一定會終結這場夢魘。', `MaleText_loc7`='¿Qué? ¿Hay un mausoleo bajo el viejo poblado? ¡Somos unos insensatos por no habernos dado cuenta! Ahora, encontraremos y derrotaremos a tu maestro, Godfrey. Acabaremos con esta pesadilla.' WHERE `ID`=26829;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 우리가 그 빌어먹을 녀석을 어떻게 없애버릴 지나 두고 봐라, 고드프리.', `MaleText_loc4`='高弗雷，我们自会对付塞尔赞。', `MaleText_loc5`='高佛雷，怎樣殺死那頭怪物的事情交給我們來擔心就好。', `MaleText_loc7`='Deja que nosotros nos preocupemos de cómo matar al monstruo, Godfrey.' WHERE `ID`=26830;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게? 인간들은 참으로 어리석군. 안 그런가? 황혼의 인도자 텔잔 님이시란 말이다! 텔잔님은 리치시다! 인간의 뼈와 살에서 태어나 힘을 위해 모든 것을 희생한, 리치 왕의 가호를 받는 분이시란 말이다!', `MaleText_loc4`='你们打算如何对付他？人类真是既天真又愚蠢。居然想打败黄昏使者塞尔赞！为了获得力量，他牺牲了原本的血肉之躯。巫妖王庇佑着如今的巫妖塞尔赞！', `MaleText_loc5`='怎麼殺?人類真的很笨，對吧?『幽暮使者』賽爾贊!『巫妖』賽爾贊!他以人類的骨血而生，卻為了力量犧牲奉獻了一切，受到巫妖王的庇護!', `MaleText_loc7`='¿Cómo? Los humanos son estúpidos, ¿verdad? ¡Thel''zan el Portador del Ocaso! ¡Thel''zan el Exánime! ¡Aquel que nació de carne y hueso humanos, sacrificó todo por el poder y cuenta con la protección del Rey Exánime!' WHERE `ID`=26831;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희는 텔잔 님을 막을 수 없다! 그분은 리치 왕께서 몸소 하사하신 암흑의 힘을 보유하신 분이다!', `MaleText_loc4`='你们不可能阻止塞尔赞！他拥有巫妖王陛下赐予的黑暗之能！', `MaleText_loc5`='你阻止不了賽爾贊的!他擁著黑暗禮讚，由巫妖王親自賜予他!', `MaleText_loc7`='¡No podéis detener a Thel''zan! ¡Posee el don oscuro que le otorgó el propio Rey Exánime!' WHERE `ID`=26832;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='할포드 님께 돌아가 시장이 친절하게도 정보를 제공했다는 소식을 전하십시오, $n. 전 여기 남아 이 녀석이 텔잔에 관해 아는 정보가 뭐가 됐든 짜내 보겠습니다. 그럼 좀처럼 보기 어려운 "세 번째 방법"을 고드프리에게 써봐야겠군요.', `MaleText_loc4`='$n，向哈尔弗汇报这位“坦诚”的市长先生招供的情报吧。剩下的事交给我解决，说不定还能从他口中榨出一些有关塞尔赞的消息呢。现在，我就让高弗雷见识一下罕见的“第三种解决方式”。', `MaleText_loc5`='向海弗德回報這個消息，告訴他鎮長已經好心地合作了，$n。我會留在這裡善後，並且看看這卑鄙的傢伙還有沒有知道任何關於賽爾贊的事情。現在，我要讓高佛雷見識一下少見的「第三種方法」。', `MaleText_loc7`='Vuelve junto a Halford con la información que el buen alcalde ha sido tan amable de proporcionar, $n. Yo terminaré aquí y averiguaré si este desdichado sabe algo más acerca de Thel''zan. Ahora le mostraré a Godfrey la poco habitual "opción tres".' WHERE `ID`=26833;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 우리 단둘이 이야기 좀 해볼까, 고드프리.', `MaleText_loc4`='来吧，我们开诚布公地谈一谈。', `MaleText_loc5`='讓我們好好聊一聊，高佛雷。', `MaleText_loc7`='Tú y yo vamos a hablar sobre algunas cosas, Godfrey.' WHERE `ID`=26834;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽어도 편히 쉴 수 없을 것이다, 고룡들이여!', `MaleText_loc4`='你们在死后也别想得到安宁！', `MaleText_loc5`='你死後也不得安寧，爛蛆!', `MaleText_loc7`='¡No encontraréis paz en la muerte, dragones!', `FemaleText_loc1`='죽어도 편히 쉴 수 없을 것이다, 고룡들이여!', `FemaleText_loc4`='你们在死后也别想得到安宁！', `FemaleText_loc5`='你死後也不得安寧，爛蛆!', `FemaleText_loc7`='¡No encontraréis paz en la muerte, dragones!' WHERE `ID`=26835;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일어나라... 일어나서 저들의 육신으로 배를 채워라!', `MaleText_loc4`='站起来吧……吞噬他们的血肉！', `MaleText_loc5`='起來吧...站起來，吃光他們的血肉!', `MaleText_loc7`='Alzaos... ¡alzaos y disfrutad de su carne!', `FemaleText_loc1`='일어나라... 일어나서 저들의 육신으로 배를 채워라!', `FemaleText_loc4`='站起来吧……吞噬他们的血肉！', `FemaleText_loc5`='起來吧...站起來，吃光他們的血肉!', `FemaleText_loc7`='Alzaos... ¡alzaos y disfrutad de su carne!' WHERE `ID`=26836;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용의 시대는 끝났다...', `MaleText_loc4`='巨龙的时代即将终结……', `MaleText_loc5`='龍族的時代已經過去了...', `MaleText_loc7`='El tiempo de los dragones ha terminado...', `FemaleText_loc1`='용의 시대는 끝났다...', `FemaleText_loc4`='巨龙的时代即将终结……', `FemaleText_loc5`='龍族的時代已經過去了...', `FemaleText_loc7`='El tiempo de los dragones ha terminado...' WHERE `ID`=26837;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저항해도 소용없다. 너희 모두 무한한 스컬지의 힘 앞에 무릎을 꿇게 될 것이야!', `MaleText_loc4`='反抗是毫无意义的。你们终将被浩浩荡荡的亡灵大军践踏在脚底！', `MaleText_loc5`='你的掙扎毫無意義。你們全都會在永無止境的天譴軍團下覆滅!', `MaleText_loc7`='Su esfuerzo no tiene sentido. ¡Todos ustedes caerán ante la interminable Plaga!', `FemaleText_loc1`='저항해도 소용없다. 너희 모두 무한한 스컬지의 힘 앞에 무릎을 꿇게 될 것이다!', `FemaleText_loc4`='反抗是毫无意义的。你们终将被浩浩荡荡的亡灵大军践踏在脚底！', `FemaleText_loc5`='你的掙扎毫無意義。你們全都會在永無止境的天譴軍團下覆滅!', `FemaleText_loc7`='Su esfuerzo no tiene sentido. ¡Todos ustedes caerán ante la interminable Plaga!' WHERE `ID`=26838;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전사 하나가 죽어갈 때마다 우리 군대에는 한 명이 늘어난다. 그 누구도 우리를 이길 수 없다.', `MaleText_loc4`='你们倒下的伙伴将为亡灵大军注入新鲜的血液。你们没有希望获胜。', `MaleText_loc5`='每一位戰士倒下，就表示我們強大的軍隊又多了一員。沒有人能夠戰勝我們。', `MaleText_loc7`='Cada guerrero que cae es un miembro más para nuestro poderoso ejército. La victoria contra nosotros no existe.', `FemaleText_loc1`='전사 하나가 죽어갈 때마다 우리 군대에는 한 명이 늘어난다. 그 누구도 우리를 이길 수 없다.', `FemaleText_loc4`='你们倒下的伙伴将为亡灵大军注入新鲜的血液。你们没有希望获胜。', `FemaleText_loc5`='每一位戰士倒下，就表示我們強大的軍隊又多了一員。沒有人能夠戰勝我們。', `FemaleText_loc7`='Cada guerrero que cae es un miembro más para nuestro poderoso ejército. La victoria contra nosotros no existe.' WHERE `ID`=26839;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='희망이란 없다. 너희는 패배할 것이다.', `MaleText_loc4`='放弃缥缈的希望吧。你们注定会失败！', `MaleText_loc5`='沒有希望。你注定失敗。', `MaleText_loc7`='No hay esperanza. Fracasarán.', `FemaleText_loc1`='희망이란 없다. 너희는 패배할 것이야.', `FemaleText_loc4`='放弃缥缈的希望吧。你们注定会失败！', `FemaleText_loc5`='沒有希望。你注定失敗。', `FemaleText_loc7`='No hay esperanza. Fracasarán.' WHERE `ID`=26840;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스와 폴드라곤 대영주님을 위하여!', `MaleText_loc4`='为了联盟，为了弗塔根公爵！', `MaleText_loc5`='為了聯盟與弗塔根大人!', `MaleText_loc7`='¡Por la Alianza y por Lord Fordragón!', `FemaleText_loc1`='얼라이언스와 폴드라곤 대영주님을 위하여!', `FemaleText_loc4`='为了联盟，为了弗塔根公爵！', `FemaleText_loc5`='為了聯盟與弗塔根大人!', `FemaleText_loc7`='¡Por la Alianza y por Lord Fordragón!' WHERE `ID`=26841;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야호! 여기 기갑 부대가 도착했다!', `MaleText_loc4`='啊！骑兵队到啦！', `MaleText_loc5`='喝哈!騎兵已經抵達了!', `MaleText_loc7`='¡HURRA! ¡La caballería ha llegado!', `FemaleText_loc1`='야호! 여기 기갑 부대가 도착했다!', `FemaleText_loc4`='啊！骑兵队到啦！', `FemaleText_loc5`='喝哈!騎兵已經抵達了!', `FemaleText_loc7`='¡HURRA! ¡La caballería ha llegado!' WHERE `ID`=26842;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='운전 실력이 대단하더군요! 긁힌 자국 하나 없습니다!', `MaleText_loc4`='技术不错啊！我们毫发无损！', `MaleText_loc5`='開得漂亮，士兵!我們一點刮傷都沒有!', `MaleText_loc7`='¡Buena conducción, soldado! ¡No tenemos ni un rasguño!', `FemaleText_loc1`='운전 실력이 대단하더군요! 긁힌 자국 하나 없습니다!', `FemaleText_loc4`='技术不错啊！我们毫发无损！', `FemaleText_loc5`='開得漂亮，士兵!我們一點刮傷都沒有!', `FemaleText_loc7`='¡Buena conducción, soldado! ¡No tenemos ni un rasguño!' WHERE `ID`=26843;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 아니었으면 오지 못했을 거예요. 데려다 줘서 고맙습니다!', `MaleText_loc4`='要不是你，我们就死定了。谢谢你带我们回来！', `MaleText_loc5`='要是沒有你，我們就完了。感謝你送我們一程!', `MaleText_loc7`='Sin ti estaríamos perdidos. ¡Gracias por el viaje!', `FemaleText_loc1`='당신이 아니었으면 오지 못했을 거예요. 데려다 줘서 고맙습니다!', `FemaleText_loc4`='要不是你，我们就死定了。谢谢你带我们回来！', `FemaleText_loc5`='要是沒有你，我們就完了。感謝你送我們一程!', `FemaleText_loc7`='Sin ti estaríamos perdidos. ¡Gracias por el viaje!' WHERE `ID`=26844;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부패의 벌판으로 돌아가지 않으면 차량에서 떨어집니다!', `MaleText_loc4`='返回腐臭平原，否则载具将被摧毁！', `MaleText_loc5`='返回腐屍農地，否則你的飛行器將會被摧毀!', `MaleText_loc7`='¡Vuelve a Los Campos de Carroña o tu vehículo será destruido!' WHERE `ID`=26845;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배로 돌아가야지!', `MaleText_loc4`='回到船上去！', `MaleText_loc5`='回到船上!', `MaleText_loc7`='¡De vuelta al barco!' WHERE `ID`=26846;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 나가야 해!', `MaleText_loc4`='逃出这里！', `MaleText_loc5`='一定要離開這裡!', `MaleText_loc7`='¡Hay que salir de aquí!' WHERE `ID`=26847;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이러다 다 죽겠군!', `MaleText_loc4`='我们会没命的！', `MaleText_loc5`='我們死定了!', `MaleText_loc7`='¡Vamos a morir todos!' WHERE `ID`=26848;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 이런 계약한 적 없다고!', `MaleText_loc4`='我可没有同意做这样的事！', `MaleText_loc5`='工作合約中可沒這條!', `MaleText_loc7`='¡Yo no me apunté a esto!' WHERE `ID`=26849;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='됐어! 집에 갈 거야!', `MaleText_loc4`='我不管啦！我要回家！', `MaleText_loc5`='放棄吧!我要回家!', `MaleText_loc7`='¡Olvídalo! ¡Me voy a casa!' WHERE `ID`=26850;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더는 여기 못 있겠어!', `MaleText_loc4`='我根本不想呆在这里！', `MaleText_loc5`='我絕對不要被困在這裡!', `MaleText_loc7`='¡No pienso quedarme por aquí!' WHERE `ID`=26851;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절 엄호해 주세요!', `MaleText_loc4`='掩护我！', `MaleText_loc5`='掩護我!', `MaleText_loc7`='¡Cubridme!', `FemaleText_loc1`='절 엄호해 주세요!', `FemaleText_loc4`='掩护我！', `FemaleText_loc5`='掩護我!', `FemaleText_loc7`='¡Cubridme!' WHERE `ID`=26852;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나쁜 놈들이 가까이 오지 못하게 해주세요!', `MaleText_loc4`='别让那些坏人靠近我！', `MaleText_loc5`='別讓壞人靠近我!', `MaleText_loc7`='¡Mantened a los tipos malos alejados de mí!', `FemaleText_loc1`='나쁜 놈들이 가까이 오지 못하게 해주세요!', `FemaleText_loc4`='别让那些坏人靠近我！', `FemaleText_loc5`='別讓壞人靠近我!', `FemaleText_loc7`='¡Mantened a los tipos malos alejados de mí!' WHERE `ID`=26853;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들을 15초만 막아주실 수 있다면 일은 끝난 거나 마찬가지라고요.', `MaleText_loc4`='别让他们靠近我！我保证能在15秒内搞定这玩意儿。', `MaleText_loc5`='讓他們遠離我15秒，這個東西就跟死了沒兩樣。', `MaleText_loc7`='Mantenedlos alejados de mí durante 15 segundos y esta cosa estará como muerta.', `FemaleText_loc1`='놈들을 15초만 막아주실 수 있다면 일은 끝난 거나 마찬가지라고요.', `FemaleText_loc4`='别让他们靠近我！我保证能在15秒内搞定这玩意儿。', `FemaleText_loc5`='讓他們遠離我15秒，這個東西就跟死了沒兩樣。', `FemaleText_loc7`='Mantenedlos alejados de mí durante 15 segundos y esta cosa estará como muerta.' WHERE `ID`=26854;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 작업을 마치면 이 역병 수레는 마치 고블린이 만든 물건처럼 엉망이 될 걸요! 절 보호해 주세요!', `MaleText_loc4`='看着吧，我会把这台天灾战车包装得像是地精的工程制品！保护我！', `MaleText_loc5`='當我完成了對這輛瘟疫戰車的破壞後，它看起來會像是哥布林製的!保護我的安全!', `MaleText_loc7`='¡Cuando acabe con este vagón de peste, parecerá que lo haya construido un goblin! ¡Mantenme a salvo!', `FemaleText_loc1`='제가 작업을 마치면 이 역병 수레는 마치 고블린이 만든 물건처럼 엉망이 될 걸요! 절 보호해 주세요!', `FemaleText_loc4`='看着吧，我会把这台天灾战车包装得像是地精的工程制品！保护我！', `FemaleText_loc5`='當我完成了對這輛瘟疫戰車的破壞後，它看起來會像是哥布林製的!保護我的安全!', `FemaleText_loc7`='¡Cuando acabe con este vagón de peste, parecerá que lo haya construido un goblin! ¡Mantenme a salvo!' WHERE `ID`=26855;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 솜씨 좋게 기묘한 기계를 조립합니다.', `MaleText_loc4`='%s娴熟地装配出一台外形奇特的机械。', `MaleText_loc5`='%s熟練地裝配這個奇怪的機械。', `MaleText_loc7`='%s construye hábilmente una extraña máquina.', `FemaleText_loc1`='%s|1이;가; 솜씨 좋게 기묘한 기계를 조립합니다.', `FemaleText_loc4`='%s娴熟地装配出一台外形奇特的机械。', `FemaleText_loc5`='%s熟練地裝配這個奇怪的機械。', `FemaleText_loc7`='%s construye hábilmente una extraña máquina.' WHERE `ID`=26856;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모이거라. 모두 모이거라. 이야기가 시작되느니라.', `MaleText_loc4`='过来吧。我给你们讲个故事。', `MaleText_loc5`='過來，靠過來。要講故事了。', `MaleText_loc7`='Reuníos. Reuníos. Ha llegado una historia.' WHERE `ID`=26857;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='됐어요! 이제 몇 초만 더 기다리면 돼요.', `MaleText_loc4`='就快搞定啦！再给我几秒钟。', `MaleText_loc5`='就該這麼做!還剩幾秒鐘。', `MaleText_loc7`='¡Eso tiene que servir! Solo unos segundos más.', `FemaleText_loc1`='됐어요! 이제 몇 초만 더 기다리면 돼요.', `FemaleText_loc4`='就快搞定啦！再给我几秒钟。', `FemaleText_loc5`='就該這麼做!還剩幾秒鐘。', `FemaleText_loc7`='¡Eso tiene que servir! Solo unos segundos más.' WHERE `ID`=26858;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적의 공격이다! 몸을 낮춰라!', `MaleText_loc4`='敌人来啦！低头！', `MaleText_loc5`='砲火來襲!趴下!', `MaleText_loc7`='¡Ahí viene! ¡Agachad las cabezas!' WHERE `ID`=26859;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위를 봐라! 공습이다!', `MaleText_loc4`='注意头顶！敌人发动了低空袭击！', `MaleText_loc5`='注意上方!砲擊來襲!', `MaleText_loc7`='¡Cuidado! ¡Nos atacan!' WHERE `ID`=26860;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적의 공격이다, 피하라!', `MaleText_loc4`='攻击！肃清敌人！', `MaleText_loc5`='準備開火，場地淨空!', `MaleText_loc7`='¡Fuego, salid del campo!' WHERE `ID`=26861;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불타라, 악마야!', `MaleText_loc4`='燃烧吧，恶魔！', `MaleText_loc5`='燒吧，你們這些魔鬼!', `MaleText_loc7`='¡Arded, demonios!' WHERE `ID`=26862;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='길을 열어라! 고룡이 우릴 도우러 왔다!', `MaleText_loc4`='前进！有条巨龙来帮助我们啦！', `MaleText_loc5`='讓路!巨龍來援!', `MaleText_loc7`='¡Abrid paso! ¡Un dragón viene a ayudarnos!' WHERE `ID`=26863;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='붉은용군단이 온다!', `MaleText_loc4`='红龙来啦！', `MaleText_loc5`='紅龍來了!', `MaleText_loc7`='¡Viene un dragón Rojo!' WHERE `ID`=26864;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일어나라, 아루갈! 리치 왕님의 힘으로 네게 명한다!', `MaleText_loc4`='觉醒吧，阿鲁高！巫妖王的力量命令你觉醒！', `MaleText_loc5`='起來，阿魯高!巫妖王的力量在命令你!', `MaleText_loc7`='¡Levántate, Arugal! ¡El poder del Rey Exánime te lo ordena!' WHERE `ID`=26865;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='', `MaleText_loc4`='', `MaleText_loc5`='', `MaleText_loc7`='' WHERE `ID`=26866;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래... 그라면 우리 목적에 아주 적격이지. 준비되면 이자를 극지 마을로 보내라. 일이 늦어진다면 아서스 님께서 좋아하지 않으실 거다.', `MaleText_loc4`='对……他完全符合我们的要求。请你将他送去冬至村吧。如果我们不能按时完成阿尔萨斯陛下交代的任务，他会不满意的。', `MaleText_loc5`='是...他應該完美地符合我們的要求。等你準備好之後把他送去季至村。要是我們進度落後，阿薩斯可不會高興。', `MaleText_loc7`='Sí... servirá perfectamente para nuestros propósitos. Cuando estés preparado, envíalo al Poblado Solsticio. Arthas no estará satisfecho si nos retrasamos.' WHERE `ID`=26867;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 저거 봤나? 저기 수면에 떠 있는 거 말이야...$b$b자네도 보지 않았나?', `MaleText_loc4`='嗨，$c。你瞧见了吗？水面上那是什么玩意儿……$b$b你到底看清楚没有啊？', `MaleText_loc5`='喂，$c，你看到了嗎?就在那邊，殘留在水面上...$b$b你也看到了，對吧?', `MaleText_loc7`='Hey, $c, ¿has visto eso? Allí, oculto cerca de la superficie del agua...$B$BTú también lo has visto, ¿verdad?' WHERE `ID`=26868;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빙산 말입니까?', `MaleText_loc4`='你是说冰山吗？', `MaleText_loc5`='你是指冰山?', `MaleText_loc7`='¿Te refieres al iceberg?', `FemaleText_loc1`='빙산 말인가요?', `FemaleText_loc4`='你是说冰山吗？', `FemaleText_loc5`='你是指冰山?', `FemaleText_loc7`='¿Te refieres al iceberg?' WHERE `ID`=26869;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빙... 뭐라고?$b$b뭐, 나는 저걸 그냥 ''뭔지 모를 덩어리''라고 부르지. 우리 고향에 있는 자들은 대부분 저런 게 있다는 사실을 부정한다고.$b$b하지만 난 알고 있어! 가까이에서 본 적도 있고! 난 그것들을 탐색, 추적, 분석, 그리고 필요에 따라서는 파괴할 수 있도록 지난 수년 동안 이 배를 만들어 왔지!', `MaleText_loc4`='冰……冰山？？$b$b呃，我是指漂在空中的不明障碍物。在我的家乡，大家都说没有见过此类物体。$B$B我是真的见过！还在近处观察过它们呢！喏，这艘船就是我近几年的创造结晶，为的就是追踪并记录这些不明物体并且在必要的时候摧毁它们！', `MaleText_loc5`='你說什麼?$b$b嗯，我把它們當成是未確認的漂浮障礙物。在我的老家，大部分的人否認它們的存在。$b$b但我知道得更多!我甚至看過它們四處跑!我近幾年都花在建造這台機械，可以鎖定、追蹤與記錄，如果需要的話，它還可以消滅它們!', `MaleText_loc7`='¿El qué?$B$BBueno, yo las llamo obstrucciones flotantes indefinidas. Muchos niegan su existencia completamente.$B$B¡Pero yo soy más listo! ¡Yo las he visto de cerca! He pasado los últimos años construyendo este barco para encontrarlas, seguirlas, documentarlas y, si fuera necesario, erradicarlas.' WHERE `ID`=26870;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 능력을 인정한다, 드워프여. 계획이 성공한 걸 보니 기쁘고도 놀랍군.', `MaleText_loc4`='你的计划竟然成功了，我真是又惊又喜。', `MaleText_loc5`='我得承認，矮人，看到你的計畫成功我又驚又喜。', `MaleText_loc7`='Lo admito, enano, ver que tu plan funcionaba fue una sorpresa agradable.' WHERE `ID`=26871;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 장비가 죄다 얼음을 조사하는 데 쓰인다고요?', `MaleText_loc4`='这艘船……仅仅是为了检查浮冰？', `MaleText_loc5`='這些裝置都只是為了要檢查冰塊?', `MaleText_loc7`='¿Tanto equipo para examinar hielo?', `FemaleText_loc1`='이 장비가 죄다 얼음을 조사하는 데 쓰인다고요?', `FemaleText_loc4`='这艘船……仅仅是为了检查浮冰？', `FemaleText_loc5`='這些裝置都只是為了要檢查冰塊?', `FemaleText_loc7`='¿Tanto equipo para examinar hielo?' WHERE `ID`=26872;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 널 돌려보낼 수도 없고, 그렇다고 계속 데리고 있을 수도 없다...', `MaleText_loc4`='我们不能让你回到同伴身边，也不能让你和我们呆在一起……', `MaleText_loc5`='我們不能就這樣讓你回去你的同伴身邊，但我們也不能帶著你一起...', `MaleText_loc7`='No podemos dejar que vuelvas junto a tus compañeros y tampoco podemos llevarte con nosotros...' WHERE `ID`=26873;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐! 내가 도와주면 목숨만은 살려준다 하지 않았소. 난 약속을 지켰소!', `MaleText_loc4`='等等！你说过如果我帮你的忙，你就放我一条生路的。我可是一直遵照约定帮助你的！', `MaleText_loc5`='等一下!你答應過如果我幫助你，你就會放過我。我拿我的生命來當賭注!', `MaleText_loc7`='¡Espera un minuto! Prometiste perdonarme la vida si os ayudaba. ¡Yo he cumplido mi parte del trato!' WHERE `ID`=26874;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼을 거두십시오, 족장님. 어쩌면 우리에게 도움이 될지도 모릅니다.', `MaleText_loc4`='酋长，刀下留人。他还有利用价值。', `MaleText_loc5`='放下你的刀，酋長。他或許對我們來說還有價值。', `MaleText_loc7`='Detén tu hoja, cabecilla. Puede que aún nos sea útil.' WHERE `ID`=26875;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바보 같은 소리 하지 말라고, $r. 저것들은 여간해선 보기 어려워. 어느 순간 보였다가도 잠깐 눈을 돌리면 금세 사라져 버린단 말이지!$b$b자네에게만 하는 말인데, 난 실제로 한 조각을 이 손에 잡아본 적도 있어! 아쉽게도 그것은 내가 조사를 시작하기도 전에 사라졌지! 그냥 사라져 버렸단 말이야...', `MaleText_loc4`='$r，别被假象蒙蔽了双眼。那些不明物狡猾着呢。前一秒你还能看见它们，转瞬之间就消失得无影无踪——简直是匪夷所思！$b$b我告诉你一个秘密，不许说出去哦。我曾经搞到过一块碎片！可惜在我进行测试实验之前，它就莫名地消失了！就像蒸发了似的……不见了……', `MaleText_loc5`='別被騙了，$r。它們非常難以捉摸。他們一下子在這兒，下一會兒就不見了 - 簡直難以理解!$b$b這秘密只跟你說，我實際上曾經抓到過一隻!很可惜，在我能測量它以前就不見了!憑空消失...', `MaleText_loc7`='No te dejes engañar, $r. Son muy escurridizas. En un momento están aquí y, de repente, han desaparecido. ¡Es virtualmente inexplicable!$B$BEntre tú y yo, una vez tuve un trozo de una de ellas en mis manos. Por desgracia, desapareció antes de que pudiera realizar ninguna medición. Simplemente desapareció...' WHERE `ID`=26876;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그냥 얼음일 뿐인데, 왜 이렇게 야단입니까?', `MaleText_loc4`='只是冰块而已吧。你也太大惊小怪了。', `MaleText_loc5`='這只是冰啊，幹嘛大驚小怪?', `MaleText_loc7`='Solo es hielo. ¿Por qué tanto alboroto?', `FemaleText_loc1`='그냥 얼음일 뿐인데, 왜 이렇게 야단이세요?', `FemaleText_loc4`='只是冰块而已吧。你也太大惊小怪了。', `FemaleText_loc5`='這只是冰啊，幹嘛大驚小怪?', `FemaleText_loc7`='Solo es hielo. ¿Por qué tanto alboroto?' WHERE `ID`=26877;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이전에 발견한 드워프 일지 기억나십니까? 어쩌면 이 드워프는 브란 브론즈비어드를 생포하는 데 반드시 필요한 인물일지도 모릅니다.', `MaleText_loc4`='还记得你找到的那本矮人日记吗？呃，它的主人很可能就是我们追捕布莱恩·铜须的重要线索。', `MaleText_loc5`='記得那本被發現的矮人日誌?嗯，若我們想要找布萊恩·銅鬚並且逮住他，那個矮人可能就正是我們所需要的。', `MaleText_loc7`='¿Recuerdas el diario enano que descubrieron? Bueno, este enano podría ser justamente lo que necesitamos para localizar a Brann Barbabronce y capturarlo.' WHERE `ID`=26878;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 빛이시여, 브란이 살아 있다고? 그를 잡는 일 따위에는 절대 협조하지 않겠소!', `MaleText_loc4`='圣光在上，布莱恩还活着？我死也不会帮你追捕他的！', `MaleText_loc5`='聖光在上，布萊恩還活著?我絕對不會幫你抓住他的!', `MaleText_loc7`='Por la Luz, ¿Brann está vivo? ¡Jamás te ayudaré a capturarlo!' WHERE `ID`=26879;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='험한 꼴을 보고 싶지 않거든 협조하는 게 좋을 거다.', `MaleText_loc4`='我相信你会的，除非你想为难自己。', `MaleText_loc5`='如果你還想讓你的頭連在脖子上，你會乖乖合作。', `MaleText_loc7`='Lo harás si quieres que tu cabeza siga unida a tus hombros.' WHERE `ID`=26880;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 정도면 되겠지요, 족장님?', `MaleText_loc4`='托尔玛克，你对此满意吗？', `MaleText_loc5`='這樣你滿意了嗎，托邁克?', `MaleText_loc7`='¿Eso te satisface, Tormak?' WHERE `ID`=26881;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쓸모가 있는 동안은 살려 두지. 내가 너라면 행동을 조심할 게다, 드워프여.', `MaleText_loc4`='他还有利用价值，就留着他吧。矮人，如果我是你的话，我会更加谨慎的。', `MaleText_loc5`='如果你能證明自己的用處，他就會活久一些。如果我是你的話，我會更謹慎，矮人。', `MaleText_loc7`='Vivirá mientras nos sea de utilidad. Si yo fuera tú, tendría cuidado, enano.' WHERE `ID`=26882;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아는 게 좀 있나 보군...$b$b몇몇은 저것들이 그저 우리를 관찰하고 있을 뿐이라 말하고, 몇몇은 해양 생태계를 교란한다고 생각하지. 심지어는 그들이 아제로스를 정복할 거라고 말하는 이들도 있다고!$b$b언젠가 내가 로켓 추진 탄두로 저것들을 쓰러트린다면 모든 의문이 풀릴 거야. 장담하지!', `MaleText_loc4`='你能听到许多关于不明物体的传说……$b$b有人说它们在观测冰洋，有人说它们试图改变海洋的生态系统，还有人认为它们是来接管艾泽拉斯世界的！$b$b等我用火箭推进弹头将它们打得粉碎，就能找到答案了。相信我！', `MaleText_loc5`='眾說紛紜...$b$b有人說它們只是在觀察，有人認為它們改變了海洋生態，還有人覺得它們是來征服艾澤拉斯的!$b$b只要我拿一發火箭推進彈頭打一隻下來，我就能知道答案了。這你可以相信!', `MaleText_loc7`='Mucho, ya sabes...$B$BHay quien dice que solo están observando, otros creen que están modificando la vida de nuestros mares, ¡y algunos piensan que han venido para conquistar Azeroth!$B$BCuando consiga destruir una con mis cabezas explosivas con propulsión a cohete, obtendré respuestas. ¡Eso es seguro!' WHERE `ID`=26883;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='놀랐겠지, 쓰레기 같은 녀석! 내 동생이 어디 있는지 말하지 않으면 네 아내에게 진은 탄환을 한 통 가득 박아주겠어.', `FemaleText_loc4`='畜生！快说！我的妹妹在哪儿，否则我不会放过你们的。', `FemaleText_loc5`='驚喜嗎，你這人渣!你快說我妹妹在那裡，否則我就把一桶的真銀子彈射穿你老婆的心臟。', `FemaleText_loc7`='¡Sorpresa, escoria! Vas a decirme dónde está mi hermana o atravesaré el corazón de tu mujer con un montón de balas de plata.' WHERE `ID`=26884;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐! 쏘지 마! 타트야나를 해치지 마!', `MaleText_loc4`='等等！别开枪！不要伤害塔特亚娜！', `MaleText_loc5`='停!別開火!別傷害塔迦納!', `MaleText_loc7`='¡Espera! ¡No dispares! ¡No hagas daño a Tatjana!' WHERE `ID`=26885;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 녀석은 산 반대편의 늑대 우리에 잡혀 있다. 아루갈에게 바쳐지기로 되어 있어. 이제 우릴 풀어줄 건가?', `MaleText_loc4`='囚犯们被关押在山脉另一侧的狼穴中。你说的姑娘很快就会被送到阿鲁高那里了。我们可以走了吗？', `MaleText_loc5`='那個小傢伙把犯人都關在山另一邊的狼穴中。她要被帶去給阿魯高。我們現在可以走了嗎?', `MaleText_loc7`='La mocosa está prisionera en la guarida de los lobos al otro lado de la montaña. Se la iban a llevar a Arugal. ¿Podemos irnos ya?' WHERE `ID`=26886;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타트야나... 날 용서하시오.', `MaleText_loc4`='原谅我，塔特亚娜……', `MaleText_loc5`='原諒我，塔迦納...', `MaleText_loc7`='Perdóname, Tatjana...' WHERE `ID`=26887;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 힘 따위는 아루갈 님의 힘과 비교조차 되지 않는다! 내가 직접 너희를 없애버리겠어!', `MaleText_loc4`='和阿鲁高比起来，你对我们的威慑力差得远了！我要将你撕成碎片！', `MaleText_loc5`='你所做的完全不能跟阿魯高相比!我要親自把你撕裂!', `MaleText_loc7`='¡Nada que puedas hacer es comparable a lo que Arugal podría hacer con nosotros! ¡Te destrozaré yo mismo!' WHERE `ID`=26888;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안야는 어디 있지?', `FemaleText_loc4`='安娅在哪儿？', `FemaleText_loc5`='安雅在哪裡?', `FemaleText_loc7`='¿Dónde está Anya?' WHERE `ID`=26889;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마지막으로 하나 더. 아루갈이 어디 있는지 말해.', `FemaleText_loc4`='只剩最后一件事了。我必须知道阿鲁高的下落。', `FemaleText_loc5`='還有最後一件事。我要知道阿魯高在哪裡。', `FemaleText_loc7`='Aún falta una cosa. Necesito saber dónde está Arugal.' WHERE `ID`=26890;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='절 구해주시고 야영지까지 데려다 주셔서 고마워요. 월터 오빠에게 전 무사하다고 전해 주세요!', `FemaleText_loc4`='谢谢你帮我返回营地。请转告瓦尔特，就说我已经平安无事啦！', `FemaleText_loc5`='感謝你幫我回到營地。去告訴渥特我現在沒事了!', `FemaleText_loc7`='Gracias por ayudarme a volver al campamento. ¡Ve y dile a Walter que ya estoy a salvo!' WHERE `ID`=26891;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저 녀석이 깡총 군을 잡아먹을 거예요! 깡총 군을 구해주세요! 제발요!', `FemaleText_loc4`='他会吃掉小毛球的！你得帮帮小毛球！帮帮小毛球呀！', `FemaleText_loc5`='他要吃軟綿綿先生!你一定要幫幫軟綿綿先生!你一定要幫忙!', `FemaleText_loc7`='¡Se va a comer a Floppy! ¡Tienes que ayudar a Floppy! ¡Tienes que hacerlo!' WHERE `ID`=26892;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='커다랗고 나쁜 녀석이 깡총 군을 해치려고 해요! 도와주세요!', `FemaleText_loc4`='小毛球遇到大坏蛋啦！救命啊！', `FemaleText_loc5`='有個大壞蛋在攻擊軟綿綿先生!救命!', `FemaleText_loc7`='¡Hay un malo enorme atacando a Floppy! ¡Socorro!' WHERE `ID`=26893;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='야영지가 보이는 것 같아요! 이제 거의 다 왔어, 깡총 군! 어서 가자!', `FemaleText_loc4`='是营地！小毛球，我们很快就要到家啦！快点！', `FemaleText_loc5`='我想我看到營地了!我們快到家了，軟綿綿先生!我們走!', `FemaleText_loc7`='¡Creo que veo el campamento! ¡Ya casi estamos en casa, Floppy! ¡Vamos!' WHERE `ID`=26894;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, $r|1이여;여;.$B$B기다리고 있었습니다.', `MaleText_loc4`='你好，$r。$B$B我一直在盼着你。', `MaleText_loc5`='歡迎，$r。$B$B我一直在等著你。', `MaleText_loc7`='Saludos, $r.$B$BTe estaba esperando.' WHERE `ID`=26895;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전장으로 날아갈 시간입니다. 준비는 되셨습니까?', `MaleText_loc4`='我们要投身战斗了。准备好了吗？', `MaleText_loc5`='我們需要進入戰鬥。你準備好了嗎?', `MaleText_loc7`='Tenemos que unirnos a la lucha. ¿Estás en condiciones?', `FemaleText_loc1`='전장으로 날아갈 시간이에요. 준비는 되셨나요?', `FemaleText_loc4`='我们要投身战斗了。准备好了吗？', `FemaleText_loc5`='我們需要進入戰鬥。你準備好了嗎?', `FemaleText_loc7`='Tenemos que unirnos a la lucha. ¿Estás en condiciones?' WHERE `ID`=26896;
