UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들을 몰아붙여 처치하라!', `MaleText_loc4`='推进！逼他们撤退，消灭他们！', `MaleText_loc5`='把他們擊退，並且粉碎他們!', `MaleText_loc7`='¡Empujadlos y aplastadlos!' WHERE `ID`=26900;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진격하라! 제단까지 들어가야 한다!', `MaleText_loc4`='推进！杀出一条通往圣地的血路！', `MaleText_loc5`='推!清出一條路通往神殿!', `MaleText_loc7`='¡Empujad! ¡Abrid paso hasta el santuario!' WHERE `ID`=26901;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잿불고룡의 공격이다! 후퇴하라! 후퇴하라!', `MaleText_loc4`='灰烬之龙来了！撤退！撤退！', `MaleText_loc5`='餘燼龍來襲!撤退!撤退!', `MaleText_loc7`='¡Se acerca una vermis de brasas! ¡Retirada! ¡Retirada!' WHERE `ID`=26902;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공격이다! 도로로 후퇴하라!', `MaleText_loc4`='敌袭！撤回通道！', `MaleText_loc5`='來襲!躲回坑道!', `MaleText_loc7`='¡Vienen! ¡Retroceded hasta el paso!' WHERE `ID`=26903;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='후퇴하라! 잿불고룡의 공격이다!', `MaleText_loc4`='撤退！灰烬之龙来了！', `MaleText_loc5`='撤退!餘燼龍來襲!', `MaleText_loc7`='¡Replegaos! ¡Se acerca una vermis de brasas!' WHERE `ID`=26904;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 이곳에서 놈들을 묶어두겠소. 용제단으로 들어가 강령술사들을 막으시오!', `MaleText_loc4`='我们会设法牵制住敌军。你，进入圣地干掉那些通灵师！', `MaleText_loc5`='我們可以把他們擋在這裡一陣子。快去神殿，阻止那些死靈法師!', `MaleText_loc7`='Los retendremos aquí un momento. ¡Entrad en el santuario y detened a esos nigromantes!' WHERE `ID`=26905;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오래는 못 버티오! 안으로 들어가 강령술사들을 교란시키시오!', `MaleText_loc4`='我们坚持不了多久的！快进入圣地，阻止通灵师的仪式！', `MaleText_loc5`='我們擋不了他們太久!快進去阻止那些死靈法師!', `MaleText_loc7`='¡No podremos aguantarlos mucho tiempo! ¡Entrad e interrumpid a sus nigromantes!' WHERE `ID`=26906;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들을 조금 더 이곳에 잡아 두겠소! 할 수 있다면 용제단으로 진입하시오!', `MaleText_loc4`='我们会尽量拖延敌军！你一定要抓紧机会进入圣地！', `MaleText_loc5`='我們還可以擋住他們一陣子!趁著機會快進入神殿!', `MaleText_loc7`='¡Los retendremos un poco más! ¡Entrad en el santuario mientras podáis!' WHERE `ID`=26907;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전장으로 이끌어 주십시오, $n!', `MaleText_loc4`='让我们一起加入战斗吧，$n！', `MaleText_loc5`='帶我們上戰場，$n!', `MaleText_loc7`='¡Llévanos a la batalla, $n!' WHERE `ID`=26908;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자폭 절차를 시작합니다.', `MaleText_loc4`='自毁程序启动。', `MaleText_loc5`='自毀程序已展開。', `MaleText_loc7`='Secuencia de autodestrucción iniciada.' WHERE `ID`=26909;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리핀 중에서도 노스렌드 산봉우리에 사는 녀석들이 가장 활동적이랍니다.', `MaleText_loc4`='栖息在诺森德山峰上的狮鹫是适应性最强的物种。', `MaleText_loc5`='北裂境群山中的獅鷲獸，是牠們種族中最堅毅強韌的。', `MaleText_loc7`='Los grifos de las cimas de Rasganorte son los más fuertes de la especie.' WHERE `ID`=26910;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='총사령관님께서 당신과 이야기해 토르손의 전초기지로 가는 탈것을 받으라고 하셨습니다.', `MaleText_loc4`='高级指挥官说你可以送我前往索尔森的岗哨。', `MaleText_loc5`='高階指揮官有話要跟你講，你要去托爾森崗哨。', `MaleText_loc7`='El Alto comandante quiere hablar contigo cuando vayas al Puesto de Thorson.', `FemaleText_loc1`='총사령관님께서 당신과 이야기해 토르손의 전초기지로 가는 탈것을 받으라고 하셨어요.', `FemaleText_loc4`='高级指挥官说你可以送我前往索尔森的岗哨。', `FemaleText_loc5`='高階指揮官有話要跟你講，你要去托爾森崗哨。', `FemaleText_loc7`='El Alto comandante quiere hablar contigo cuando vayas al Puesto de Thorson.' WHERE `ID`=26911;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리핀 기수들은 10걸음쯤 떨어진 곳에 있습니다. 그들이 토르손의 전초기지까지 태워다 줄 거예요. 그럼 가보십시오!', `MaleText_loc4`='朋友，狮鹫骑士距离我们仅十步之遥。他们会送你前往索尔森的岗哨。准备出发吧！', `MaleText_loc5`='獅鷲騎士站在我們10步之外，朋友。他們會送你前往托爾森崗哨。去吧!', `MaleText_loc7`='Los grifos están a 10 pasos de aquí, colega. Ellos nos llevarán al Puesto de Thorson.' WHERE `ID`=26912;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n의 파괴 공작이 성공했다!', `MaleText_loc4`='我已经将酬劳发给$n了！', `MaleText_loc5`='我剛把擊殺榮譽發給$n!', `MaleText_loc7`='¡Acabo de otorgar crédito por muerte a $n!' WHERE `ID`=26913;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='절 잡아먹진 않으실 거죠?', `FemaleText_loc4`='你不会吃掉我的，对吧？', `FemaleText_loc5`='你不會吃我，對吧?', `FemaleText_loc7`='No me comerás, ¿verdad?' WHERE `ID`=26914;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안야!! 무사했구나!', `FemaleText_loc4`='安娅！！你平安无事！', `FemaleText_loc5`='安雅!!你沒事!', `FemaleText_loc7`='¡Anya! ¡Estás bien!' WHERE `ID`=26915;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='피의 달이라고? 핏빛달이 아니고?', `FemaleText_loc4`='邪月岛？是血月岛吧？', `FemaleText_loc5`='惡月?你是指血月嗎?', `FemaleText_loc7`='¿Luna de Hambre? ¿Quieres decir Luna de Sangre?' WHERE `ID`=26916;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='걱정 마... 이제 아무도 널 해치지 못할 거란다.', `FemaleText_loc4`='别害怕……现在你安全啦。', `FemaleText_loc5`='別擔心，妹妹...現在沒人能傷害你了。', `FemaleText_loc7`='No te preocupes, hermana... Ya nadie puede hacerte daño.' WHERE `ID`=26917;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사샤 언니! 나쁜 아저씨들이 날 핏달 섬으로 데려가려고 했어. 날 그 사람들처럼 만들려고 했어.', `FemaleText_loc4`='姐姐！那些卑鄙的家伙打算将我带去邪月岛，把我变成他们的一员。', `FemaleText_loc5`='姊姊!那個壞人要帶我去惡月島。他們想把我變成他們的一員。', `FemaleText_loc7`='¡Hermana! Los hombres malos querían llevarme a la Isla Luna de Hambre. Querían convertirme en uno de ellos.' WHERE `ID`=26918;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그거라니까, 언니! 핏달! 사샤 언니... 다시는 나 혼자 두고 가지마! 그 사람들은 아빠를 죽였고, 그리고 언니까지... 나 혼자 그 사람들이랑 있기 싫어!', `FemaleText_loc4`='对，就是那个岛屿！邪月岛！萨莎……别再离开我啦！他们抓走了爸爸，然后又抓走了你……我不想和他们单独相处！', `FemaleText_loc5`='那就是我說的!惡月!莎夏...別再離開我!他們先抓走了爸爸，然後他們抓走了你...我不想一個人跟他們在一起!', `FemaleText_loc7`='¡Eso he dicho! ¡Luna de Hambre! Sasha... ¡no me vuelvas a dejar sola nunca! Primero se llevaron a papá, luego a ti... ¡No quiero quedarme sola con ellos!' WHERE `ID`=26919;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='예전에 공을 세웠다고 그걸로 득을 볼 생각은 꿈에서도 하지 마라, $n. 어림도 없어.$B$B내게 인정받고 싶다면 직접 증명해야지. 쓸데없는 소리 하지 말고 내가 시키는 대로 충실히 따르든지 말이다... 예외 따윈 없다.', `FemaleText_loc4`='不要以为过去的成就能为你带来任何权利与荣耀，$n。$B$B想要得到我的尊重，你必须证明自己。也就是说，你要遵循我的指令，并且毫无异议地完成使命。', `FemaleText_loc5`='別以為你過去的成就頭銜能給你什麼好處，$n。他們不能。$B$B如果你想要我的尊敬，你就得自己來贏得它。這也意味著無條件地服從我的命令，並且完成。', `FemaleText_loc7`='No pienses ni por un momento que tus logros pasados te dan derecho a hacer lo que sea, $n. Porque no es así.$B$BSi quieres mi respeto, tendrás que ganártelo. Tendrás que seguir mis órdenes sin cuestionarlas y cumplirlas... sin excepción.' WHERE `ID`=26920;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='토르손의 전초기지로 출발합니다!', `MaleText_loc4`='索尔森的岗哨——就在前面！', `MaleText_loc5`='托爾森崗哨 - 馬上就來!', `MaleText_loc7`='¡Puesto de Thorson, allá vamos!', `FemaleText_loc1`='토르손의 전초기지로 출발합니다!', `FemaleText_loc4`='索尔森的岗哨——就在前面！', `FemaleText_loc5`='托爾森崗哨 - 馬上就來!', `FemaleText_loc7`='¡Puesto de Thorson, allá vamos!' WHERE `ID`=26921;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모자 떨어뜨리지 않게 조심하십시오! 좀 흔들릴 겁니다!', `MaleText_loc4`='坐稳啦！可能会出现颠簸。', `MaleText_loc5`='扶著你的帽子，夥伴!我們接下來旅程會有一點顛簸。', `MaleText_loc7`='Sujétate el sombrero, colega. Va a ser un viaje movidito.', `FemaleText_loc1`='모자 떨어뜨리지 않게 조심하세요! 좀 흔들릴 겁니다!', `FemaleText_loc4`='坐稳啦！可能会出现颠簸。', `FemaleText_loc5`='扶著你的帽子，夥伴!我們接下來旅程會有一點顛簸。', `FemaleText_loc7`='Sujétate el sombrero, colega. Va a ser un viaje movidito.' WHERE `ID`=26922;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고개를 낮추고 서리고룡이 오지 않나 살피십시오! 이야아아!', `MaleText_loc4`='低下头，避开冰霜巨龙！呀～！', `MaleText_loc5`='低下頭，隨時注意冰霜巨龍!呀呼!', `MaleText_loc7`='¡Mantén la cabeza agachada y ten cuidado con las vermis de escarcha! ¡AAYYYY!', `FemaleText_loc1`='고개를 낮추고 서리고룡이 오지 않나 살피십시오! 이야아아!', `FemaleText_loc4`='低下头，避开冰霜巨龙！呀～！', `FemaleText_loc5`='低下頭，隨時注意冰霜巨龍!呀呼!', `FemaleText_loc7`='¡Mantén la cabeza agachada y ten cuidado con las vermis de escarcha! ¡AAYYYY!' WHERE `ID`=26923;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도착했습니다. 조심해서 내리십시오!', `MaleText_loc4`='我们到啦。安全着陆！', `MaleText_loc5`='這是你的目的地，夥伴。降落小心!', `MaleText_loc7`='Esta es tu parada, colega. ¡Que tengas un aterrizaje seguro!', `FemaleText_loc1`='도착했어요. 조심해서 내리세요!', `FemaleText_loc4`='我们到啦。安全着陆！', `FemaleText_loc5`='這是你的目的地，夥伴。降落小心!', `FemaleText_loc7`='Esta es tu parada, colega. ¡Que tengas un aterrizaje seguro!' WHERE `ID`=26924;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투사냥개를 풀어라!', `MaleText_loc4`='放出战犬！', `MaleText_loc5`='把戰爭獵犬放出來!', `MaleText_loc7`='¡Soltad a los canes de guerra!' WHERE `ID`=26925;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 올라탄다!', `MaleText_loc4`='出发！', `MaleText_loc5`='我們上!', `MaleText_loc7`='¡Cabalgamos!' WHERE `ID`=26926;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누더기골렘 발견! 5대대, 올라타라! 놈과 교전에 들어간다!', `MaleText_loc4`='发现憎恶！第5营，让我们去教训教训他们吧！', `MaleText_loc5`='發現憎惡體!第5軍團，上馬，準備迎戰!', `MaleText_loc7`='Abomination', `FemaleText_loc1`='누더기골렘 발견! 5대대, 올라타라! 놈과 교전에 들어간다!', `FemaleText_loc4`='发现憎恶！第5营，让我们去教训教训他们吧！', `FemaleText_loc5`='發現憎惡體!第5軍團，上馬，準備迎戰!', `FemaleText_loc7`='Abomination' WHERE `ID`=26927;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리핀을 불러라!', `MaleText_loc4`='召集狮鹫！', `MaleText_loc5`='呼叫獅鷲獸!', `MaleText_loc7`='¡Llamad a los grifos!', `FemaleText_loc1`='그리핀을 불러라!', `FemaleText_loc4`='召集狮鹫！', `FemaleText_loc5`='呼叫獅鷲獸!', `FemaleText_loc7`='¡Llamad a los grifos!' WHERE `ID`=26928;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부대, 앞으로!', `MaleText_loc4`='冲向前线！', `MaleText_loc5`='到前面來，兄弟!', `MaleText_loc7`='¡Llamad a los grifos!', `FemaleText_loc1`='부대, 앞으로!', `FemaleText_loc4`='冲向前线！', `FemaleText_loc5`='到前面來，兄弟!', `FemaleText_loc7`='¡Llamad a los grifos!' WHERE `ID`=26929;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들에게 폭풍망치의 분노를 맛보여줘라!', `MaleText_loc4`='让他们感受到你手中的战锤之怒吧！', `MaleText_loc5`='讓他們嚐嚐你風暴戰錘的狂怒!', `MaleText_loc7`='¡Que sientan la furia de sus martillos de tormenta!', `FemaleText_loc1`='놈들에게 폭풍망치의 분노를 맛보여줘라!', `FemaleText_loc4`='让他们感受到你手中的战锤之怒吧！', `FemaleText_loc5`='讓他們嚐嚐你風暴戰錘的狂怒!', `FemaleText_loc7`='¡Que sientan la furia de sus martillos de tormenta!' WHERE `ID`=26930;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 모자라다! 놈들에게 5대대의 실력을 보여줘라!', `MaleText_loc4`='还不够！让他们尝尝第5营的厉害！', `MaleText_loc5`='這還不夠!讓他們瞧瞧第5軍團的力量!', `MaleText_loc7`='¡No es suficiente! ¡Mostrémosles el poder del Quinto Batallón de cerca!', `FemaleText_loc1`='아직 모자라다! 놈들에게 5대대의 실력을 보여줘라!', `FemaleText_loc4`='还不够！让他们尝尝第5营的厉害！', `FemaleText_loc5`='這還不夠!讓他們瞧瞧第5軍團的力量!', `FemaleText_loc7`='¡No es suficiente! ¡Mostrémosles el poder del Quinto Batallón de cerca!' WHERE `ID`=26931;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='견딜 수 없는 한기가 죽음을 몰고 오리니.', `MaleText_loc4`='笼罩你的寒气就是厄运的先兆。', `MaleText_loc5`='籠罩你的寒氣就是厄運的先兆。', `MaleText_loc7`='El escalofrío que sientes es el heraldo de tu perdición.' WHERE `ID`=26932;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와서 나를 보호해라! 어서! 망할 놈들아!', `MaleText_loc4`='协助防御！快点，废物们！', `MaleText_loc5`='協助防禦!快點，廢物們!', `MaleText_loc7`='¡Apoya mis defensas! ¡Rápido, maldición!' WHERE `ID`=26933;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요. 월터와 전 다른 말과 함께 이 늙은말 블랑쉬를 돌보고 있어요.', `MaleText_loc4`='你好。侍从瓦尔特和我负责照看老马布兰契和其他马匹。', `MaleText_loc5`='嗨。侍從沃特和我負責在這裡照料老馬布蘭契以及其他坐騎。', `MaleText_loc7`='Hola. El escudero Walter y yo somos responsables del cuidado de la vieja Blanchy y de las demás monturas de aquí.' WHERE `ID`=26934;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마구간을 쓰게 해다오.', `MaleText_loc4`='我想使用马厩。', `MaleText_loc5`='我想要使用獸欄。', `MaleText_loc7`='Me gustaría usar los establos.', `FemaleText_loc1`='마구간을 쓰게 해다오.', `FemaleText_loc4`='我想使用马厩。', `FemaleText_loc5`='我想要使用獸欄。', `FemaleText_loc7`='Me gustaría usar los establos.' WHERE `ID`=26935;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, $r|1이여;여;.$B$B사원 방어를 돕겠다면 안에 계신 아프라사스트라즈 군주님께 이야기해 보십시오.', `MaleText_loc4`='你好，$r。$B$B如果你愿意帮助我们保卫神殿的话，请入内与指挥官阿弗拉沙斯塔兹谈一谈。', `MaleText_loc5`='你好，$r。$B$B如果對協助防衛神殿有興趣的話，請和裡面的艾弗薩斯塔茲領主談談。', `MaleText_loc7`='Saludos, $r.$B$BSi te interesa colaborar en la defensa del templo, habla con Lord Afrasastrasz en el interior.' WHERE `ID`=26936;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절 자유롭게 해주셔서 감사합니다, 필멸의 존재여. 명심하십시오. 푸른용군단은 그대의 존재를 경계하고 있습니다. 지금 이 순간에도 말리고스는 마력의 눈을 보호하려고 바로스 클라우드스트라이더와 고리 수호자들을 보내지요. 이에 맞서려면 저희 도움이 필요하리라 생각합니다.', `MaleText_loc4`='感谢你们，凡人。蓝龙军团已经察觉到你们的动向，你们要当心。眼下，玛里苟斯任命瓦尔洛斯·云击率领碧蓝魔环卫士死守魔环。请接受我们的帮助，这样才有机会击败敌人。', `MaleText_loc5`='感謝你釋放了我們，凡人。當心，藍龍軍團已經注意到你們的存在。現在，瑪里苟斯已派出瓦羅斯·雲行者與他的守護者來守衛奧核之眼。你會需要我們的幫助才有機會擊敗他們。', `MaleText_loc7`='Gracias por liberarnos, mortales. Tengan cuidado, el Vuelo Azul ha sido alertado de su presencia. Incluso ahora, Malygos envía a Varos Zancanubes y a sus guardianes del anillo para defender El Oculus. Necesitarán nuestra ayuda o no tendrán nada que hacer.' WHERE `ID`=26937;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$r|1이여;여;, 미안하지만 난 이미 그대를 위해 파수꾼을 불렀다.$B$B다시 부르려면 조금 더 기다려야 한다.', `MaleText_loc4`='对不起，$r，我刚刚才为你召唤了一名防御者。$B$B你得容我休息一会儿，我才能再次召唤。', `MaleText_loc5`='我很抱歉，$r，但我才剛剛為你召喚過一名防衛者。$B$B在我再次替你召喚之前，你必須稍等一小段時間。', `MaleText_loc7`='Lo siento, $r, acabo de llamar a un defensor para ti.$B$BTendrás que esperar un poco antes de que vuelva a hacerlo.', `FemaleText_loc1`='$r|1이여;여;, 미안하지만 난 이미 그대를 위해 파수꾼을 불렀다.$B$B다시 부르려면 조금 더 기다려야 한다.', `FemaleText_loc4`='对不起，$r，我刚刚才为你召唤了一名防御者。$B$B你得容我休息一会儿，我才能再次召唤。', `FemaleText_loc5`='我很抱歉，$r，但我才剛剛為你召喚過一名防衛者。$B$B在我再次替你召喚之前，你必須稍等一小段時間。', `FemaleText_loc7`='Lo siento, $r, acabo de llamar a un defensor para ti.$B$BTendrás que esperar un poco antes de que vuelva a hacerlo.' WHERE `ID`=26938;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='난 알렉스트라자 님의 가호를 받아 기억도 나지 않을 만큼 기나긴 시간 동안 이 제단을 지켜왔습니다. 어둠이 짙게 드리운 때에 난 실패했지요... 그 저주받은 죽음의 기사... 블러드베인의 발밑에 쓰러졌답니다.', `FemaleText_loc4`='我一直守护着这座被阿莱克丝塔萨女王祝福过的圣地，光阴荏苒……连我都不记得度过了多长时间。在最为黑暗的年代，我未能尽到自己的职守……我倒在了死亡骑士血毒的脚下。', `FemaleText_loc5`='我居住在這裡並以雅立史卓莎的祝福守護這個神殿，時間已經久到我都記不清了。而在最黑暗的時刻，我失敗了...我倒在那個天殺的死亡騎士腳下...血禍。', `FemaleText_loc7`='He vivido aquí y protegido este santuario con la bendición de Alexstrasza durante más tiempo del que puedo recordar. En el momento más oscuro fracasé... Caí ante los pies de ese maldito caballero de la Muerte... Malasangre.' WHERE `ID`=26939;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='리치 왕은 멀리까지 손을 뻗치는 중입니다... 모든 용군단에게 가장 성스러운 땅마저도 짓밟으려 하고 있어요. 우리가 행동에 나서게 유도하고 있습니다.', `FemaleText_loc4`='巫妖王已经伸出魔爪……肆无忌惮地践踏着龙族最神圣的领地。他想逼迫我们采取行动。', `FemaleText_loc5`='巫妖王的魔掌延伸至遠方...大膽染指對所有飛龍來說極為神聖的土地。他打算逼我們先動手。', `FemaleText_loc7`='El Rey Exánime está alargando su mano ahora... adentrándose sin miedo en las más sagradas tierras de todos los Vuelos. Pretende obligarnos a actuar.' WHERE `ID`=26940;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 시간은 끝났어요... 살았을 때는 알렉스트라자 님을 섬겼지만, 목숨을 잃은 지금은 그렇게 할 수가 없군요. 그분께서 제단의 수호자를 새로 찾으셔야 할 겁니다.', `FemaleText_loc4`='我的时日不多了……我为阿莱克丝塔萨女王奉献了一生，可死亡终将阻断我的奉献之意。红玉巨龙圣地需要一名新的守护者。', `FemaleText_loc5`='我的壽命已盡...生時我將自己奉獻給雅立史卓莎，但是死後我已經沒什麼可以奉獻了。她將會需要一個新的神殿看守者。', `FemaleText_loc7`='Mi tiempo ha acabado... Me entregué a Alexstrasza en vida, pero no me queda nada que ofrecerle en la muerte. Ella necesitará un nuevo guardián para su santuario.' WHERE `ID`=26941;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그리고 고맙습니다... 저주받은 자들의 속박에서 날 풀어주신 걸 진심으로 감사드려요. 그대는 영웅이에요... 그대가 위대한 일을 해내리라는 걸 알 수 있답니다.', `FemaleText_loc4`='谢谢你……谢谢你将我从被诅咒的枷锁中解救出来。你是个英雄……我知道你还会干出惊天动地的大事来的。', `FemaleText_loc5`='還有，謝謝你...謝謝你將我從詛咒的桎梏中解放出來。你是個英雄...我相信你將會持續立下了不起的功績。', `FemaleText_loc7`='Y gracias... gracias por liberarme de los grilletes de los malditos. Eres un ser legendario... Sé que llevarás a cabo grandes hazañas.' WHERE `ID`=26942;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이름을 떠올린 달리아가 멸시를 가득 담아 바닥에 침을 뱉습니다.', `FemaleText_loc4`='达莉亚想起那个名字，往地上啐了口口水。', `FemaleText_loc5`='當想到那個名字的時候，妲莉雅一口啐在地上。', `FemaleText_loc7`='Dahlia escupe en el suelo al pensar en el nombre.' WHERE `ID`=26943;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='달리아 선터치의 잔재가 사라집니다...', `FemaleText_loc4`='达莉亚之魂逐渐消失了……', `FemaleText_loc5`='妲莉雅·日觸的殘骸漸漸消逝...', `FemaleText_loc7`='El resto de Dahlia Toque Solar se desvanece...' WHERE `ID`=26944;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원크와 야영지에 온 당신을 환영합니다.', `MaleText_loc4`='欢迎来到欧尼瓦营地。', `MaleText_loc5`='歡迎來到歐尼克瓦營地。', `MaleText_loc7`='Te doy la bienvenida al Campamento Oneqwah.' WHERE `ID`=26945;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마구간을 이용하고 싶습니다.', `MaleText_loc4`='我想使用兽栏。', `MaleText_loc5`='我想要使用獸欄。', `MaleText_loc7`='Me gustaría usar los establos.', `FemaleText_loc1`='마구간을 이용하고 싶어요.', `FemaleText_loc4`='我想使用兽栏。', `FemaleText_loc5`='我想要使用獸欄。', `FemaleText_loc7`='Me gustaría usar los establos.' WHERE `ID`=26946;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주.정.뱅.이.는 그냥 맥주잔 던지는 표적이 아니라 정말 귀중한 훈련 도구라고. 주.정.뱅.이.를 맞힐 수 있다면 세상에 못 맞힐 게 없을걸!$B$B그렇다고 나한테 시험해 볼 생각은 말라고.', `MaleText_loc4`='掷杯训练器不仅仅是用来投掷啤酒杯的靶子，更是宝贵的训练设备。如果你能击中它，那你就能击中任何东西！$b$b可不要砸到我哦。', `MaleText_loc5`='S.T.O.U.T.不只是丟擲啤酒杯的目標，它還是個貴重的訓練資產。如果你能擊中S.T.O.U.T.，你就能擊中所有的東西!$b$b只要別丟我就好。', `MaleText_loc7`='G.U.A.O. es más que un objetivo al que lanzarle jarras, es un recurso muy valioso para los entrenamientos. ¡Si puedes acertar al G.U.A.O., podrás acertar a cualquier cosa!$B$BPero procura no golpearme a mí.' WHERE `ID`=26947;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='녹색용군단의 비룡을 타고 싶습니다.', `MaleText_loc4`='我想坐在绿龙背上飞翔。', `MaleText_loc5`='我想要借綠龍軍團之翼翱翔天際。', `MaleText_loc7`='Quiero volar sobre las alas del Vuelo Verde.', `FemaleText_loc1`='녹색용군단의 비룡을 타고 싶어요.', `FemaleText_loc4`='我想坐在绿龙背上飞翔。', `FemaleText_loc5`='我想要借綠龍軍團之翼翱翔天際。', `FemaleText_loc7`='Quiero volar sobre las alas del Vuelo Verde.' WHERE `ID`=26948;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='벨가리스트라즈의 말이 옳아요. 상황이 매우 심각하답니다. 저는 그대에게 녹색용군단의 비룡을 불러내는 능력을 드릴 수 있지요. 붉은용군단이나 청동용군단의 힘을 원한다면 벨가리스트라즈나 이터노스와 이야기하세요.', `FemaleText_loc4`='贝加里斯塔兹说得没错，这里的局势非常严峻。

我能赐予你召唤绿龙的能力。如果你想要召唤红龙或青铜龙，就得和贝加里斯塔兹或伊特努斯谈谈。', `FemaleText_loc5`='貝加瑞斯塔茲說的是實話，戰況的確很險峻。

我可以賦予你呼喚一頭綠龍軍團飛龍的力量，但如果你屬意借用紅龍軍團或青銅龍的力量，請跟貝加瑞斯塔茲，或是伊特諾斯談談。', `FemaleText_loc7`='Belgaristrasz dice la verdad; es cierto que la situación es grave. 

Puedo otorgarte el poder de invocar un draco del Vuelo Verde. Habla con Belgaristrasz o con Eternos si prefieres aprovechar el poder del Rojo o del Bronce.' WHERE `ID`=26949;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로스 클라우드스트라이더와 그의 고리 수호자들이 두 번째 고리를 지키고 있습니다. 그대가 탄 비룡이라면 고리 수호자를 쉽게 상대할 수 있습니다. 하지만 바로스는 마력의 눈이 품은 힘으로 이루어졌기에 뚫을 수 없는 방어막 뒤에 숨어 있지요. 위의 고리와 단에 있는 원심력 피조물 열 마리가 보호막에 동력을 공급합니다. 이 피조물을 처치하면 바로스를 공격할 수 있지요. 그대에게 붉은용군단의 비룡을 불러내는 권한을 드리겠습니다. 청동용군단이나 녹색용군단의 힘을 원한다면 이터노스나 베르디사와 이야기하십시오.', `MaleText_loc4`='瓦尔洛斯·云击和他率领的碧蓝魔环卫士保卫着第二环。你的幼龙足以制服那些魔环卫士，但是瓦尔洛斯利用魔环的能量撑起了一面难以渗透的魔法护盾。分布在魔枢第二环以及顶部平台的10个离心构造体负责为护盾充能。只有摧毁它们，你才有机会打破瓦尔洛斯的护盾并击败他。

我能赐予你召唤红龙的能力。如果你想要召唤青铜龙或绿龙，就得和伊特努斯或沃尔蒂萨谈谈。', `MaleText_loc5`='瓦羅斯·雲行者與他的守護者保衛著第二道環。你們的飛龍雖然比那些守護者強上許多，但是瓦羅斯·雲行者卻躲在無法擊穿的護盾後面。這護盾是奧核之眼本身的能量所製造的，由位在那一環以及上方平台的十具離心傀儡提供護盾能量。必須先摧毀它們，才能傷害到瓦羅斯。

我可以賦予你呼喚一頭紅龍軍團飛龍的力量。如果你屬意藉助青銅龍軍團或是綠龍的力量，請和伊特諾斯或薇爾迪莎談談。', `MaleText_loc7`='Varos Zancanubes y sus guardianes del anillo protegen el segundo anillo. Tus dracos pueden apañárselas contra los guardianes del anillo, pero Varos se encuentra tras un escudo impenetrable creado con la energía del propio Oculus. Diez ensamblajes de centrifugadora dan potencia al escudo desde el anillo y las plataformas de encima. Destrúyelos y Varos será vulnerable.

Puedo otorgarte el poder de invocar a un draco del Vuelo Rojo. Habla con Eternos o con Verdisa si prefieres aprovechar el poder del Vuelo Bronce o del Vuelo Verde.' WHERE `ID`=26950;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='붉은용군단의 비룡을 타고 싶습니다.', `MaleText_loc4`='我想坐在红龙背上飞翔。', `MaleText_loc5`='我想要借紅龍軍團之翼翱翔天際。', `MaleText_loc7`='Quiero volar sobre las alas del Vuelo Rojo.', `FemaleText_loc1`='붉은용군단의 비룡을 타고 싶어요.', `FemaleText_loc4`='我想坐在红龙背上飞翔。', `FemaleText_loc5`='我想要借紅龍軍團之翼翱翔天際。', `FemaleText_loc7`='Quiero volar sobre las alas del Vuelo Rojo.' WHERE `ID`=26951;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벨가리스트라즈가 하는 말은 사실이지요. 시간이 없어요! 당신에게 청동용군단의 비룡을 불러내는 권한을 허락해 드릴게요. 붉은용군단이나 녹색용군단의 힘을 원한다면 벨가리스트라즈나 베르디사와 이야기하세요.', `MaleText_loc4`='贝加里斯塔兹说得没错，时间紧迫！

我能赐予你召唤青铜龙的能力。如果你想要召唤红龙或绿龙，就得和贝加里斯塔兹或沃尔蒂萨谈谈。', `MaleText_loc5`='貝加瑞斯塔茲說的是實話;時間緊迫!

我可以賦予你呼喚一頭青銅龍軍團飛龍的力量。如果你屬意藉助紅龍或綠龍軍團的力量，請跟貝加瑞斯塔茲，或者是薇爾迪莎談談。', `MaleText_loc7`='Belgaristrasz dice la verdad; ¡el tiempo se agota!

Puedo otorgarte el poder de invocar un draco del Vuelo Bronce. Habla con Belgaristrasz o con Verdisa si prefieres aprovechar el poder del Rojo o del Verde.' WHERE `ID`=26952;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='청동용군단의 비룡을 타고 싶습니다.', `MaleText_loc4`='我想坐在青铜龙背上飞翔。', `MaleText_loc5`='我想要借青銅龍軍團之翼翱翔天際。', `MaleText_loc7`='Quiero volar sobre las alas del Vuelo Bronce.', `FemaleText_loc1`='청동용군단의 비룡을 타고 싶어요.', `FemaleText_loc4`='我想坐在青铜龙背上飞翔。', `FemaleText_loc5`='我想要借青銅龍軍團之翼翱翔天際。', `FemaleText_loc7`='Quiero volar sobre las alas del Vuelo Bronce.' WHERE `ID`=26953;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보고합니다!', `MaleText_loc4`='报告，长官！', `MaleText_loc5`='任務回報，長官!', `MaleText_loc7`='Me presento ante usted, señor.', `FemaleText_loc1`='보고합니다!', `FemaleText_loc4`='报告，长官！', `FemaleText_loc5`='任務回報，長官!', `FemaleText_loc7`='Me presento ante usted, señor.' WHERE `ID`=26954;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 준비가 되었습니다, 주인님.', `MaleText_loc4`='指挥官，我准备好出发了。', `MaleText_loc5`='大人，我準備好出發了。', `MaleText_loc7`='Mi señor, estoy listo.', `FemaleText_loc1`='저는 준비가 되었습니다, 주인님.', `FemaleText_loc4`='指挥官，我准备好出发了。', `FemaleText_loc5`='大人，我準備好出發了。', `FemaleText_loc7`='Mi señor, estoy lista.' WHERE `ID`=26955;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아프라사스트라즈 님, 허락해 주신다면 요새 방어에 힘을 보태고 싶습니다.', `MaleText_loc4`='阿弗拉沙斯塔兹，请让我参与保卫神殿的战斗。', `MaleText_loc5`='艾弗薩斯塔茲領主，只要有你的允許，我希望能護衛神殿。', `MaleText_loc7`='Lord Afrasastrasz, con su permiso, deseo defender el templo.', `FemaleText_loc1`='아프라사스트라즈 님, 허락해 주신다면 요새 방어에 힘을 보태고 싶습니다.', `FemaleText_loc4`='阿弗拉沙斯塔兹，请让我参与保卫神殿的战斗。', `FemaleText_loc5`='艾弗薩斯塔茲領主，只要有你的允許，我希望能護衛神殿。', `FemaleText_loc7`='Lord Afrasastrasz, con su permiso, deseo defender el templo.' WHERE `ID`=26956;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여왕님을 위하여. 고룡쉼터 사원을 위하여!', `MaleText_loc4`='为女王而战！为保卫龙眠神殿而战！', `MaleText_loc5`='為了龍后。為了龍眠神殿!', `MaleText_loc7`='Por la reina. ¡Por el Templo del Reposo del Dragón!', `FemaleText_loc1`='여왕님을 위하여. 고룡쉼터 사원을 위하여!', `FemaleText_loc4`='为女王而战！为保卫龙眠神殿而战！', `FemaleText_loc5`='為了龍后。為了龍眠神殿!', `FemaleText_loc7`='Por la reina. ¡Por el Templo del Reposo del Dragón!' WHERE `ID`=26957;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='푸른용군단이 감히 이 요새를 공격하겠다면, 유언을 남기고 오는 것이 좋을 것입니다.', `MaleText_loc4`='蓝龙军团敢向神殿发动攻击，他们活腻了吧。', `MaleText_loc5`='要是藍龍膽敢進攻神殿，那他們就是許下死亡之願。', `MaleText_loc7`='Si los azules se atreven a atacar el templo, es que desean morir.', `FemaleText_loc1`='푸른용군단이 감히 이 요새를 공격하겠다면, 유언을 남기고 오는 것이 좋을 것입니다.', `FemaleText_loc4`='蓝龙军团敢向神殿发动攻击，他们活腻了吧。', `FemaleText_loc5`='要是藍龍膽敢進攻神殿，那他們就是許下死亡之願。', `FemaleText_loc7`='Si los azules se atreven a atacar el templo, es que desean morir.' WHERE `ID`=26958;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='허락해 주신다면 최선을 다하겠습니다.', `MaleText_loc4`='我会竭尽全力投身战斗！', `MaleText_loc5`='有您的允許，我將盡一切努力。', `MaleText_loc7`='Con tu permiso, haré lo que pueda.', `FemaleText_loc1`='허락해 주신다면 최선을 다하겠습니다.', `FemaleText_loc4`='我会竭尽全力投身战斗！', `FemaleText_loc5`='有您的允許，我將盡一切努力。', `FemaleText_loc7`='Con tu permiso, haré lo que pueda.' WHERE `ID`=26959;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='푸른용군단의 힘이 아무리 강해진들 절대 우리 요새를 빼앗을 수는 없을 것입니다!', `MaleText_loc4`='蓝龙军团从碧蓝巨龙圣地获得了强大的力量，但是我们绝不允许他们攻陷龙眠神殿！', `MaleText_loc5`='他們的龍殿也許強化了他們，但是今天，藍龍不會從我們的手中奪走神殿!', `MaleText_loc7`='¡Puede que su Santuario de Dragones les haya dado poder, pero los azules no nos arrebatarán el templo hoy!', `FemaleText_loc1`='푸른용군단의 힘이 아무리 강해진들 절대 우리 요새를 빼앗을 수는 없을 것입니다!', `FemaleText_loc4`='蓝龙军团从碧蓝巨龙圣地获得了强大的力量，但是我们绝不允许他们攻陷龙眠神殿！', `FemaleText_loc5`='他們的龍殿也許強化了他們，但是今天，藍龍不會從我們的手中奪走神殿!', `FemaleText_loc7`='¡Puede que su Santuario de Dragones les haya dado poder, pero los azules no nos arrebatarán el templo hoy!' WHERE `ID`=26960;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지맥의 힘이 청금석 용제단으로 곧장 흘러든다는 소식을 들었습니다. 저는 온 힘을 다해 요새를 지킬 것입니다.', `MaleText_loc4`='听说蓝龙军团将一条能量线的能量全部引向了碧蓝巨龙圣地。我会竭尽全力守护龙眠神殿的。', `MaleText_loc5`='我聽說蒼藍龍殿注入了地脈導入的能量。我將盡我所能護衛神殿。', `MaleText_loc7`='He oído que el Santuario de Dragones Azur obtiene el poder directo de una línea Ley. Defenderé el templo lo mejor que pueda.', `FemaleText_loc1`='지맥의 힘이 청금석 용제단으로 곧장 흘러든다는 소식을 들었습니다. 저는 온 힘을 다해 요새를 지킬 것입니다.', `FemaleText_loc4`='听说蓝龙军团将一条能量线的能量全部引向了碧蓝巨龙圣地。我会竭尽全力守护龙眠神殿的。', `FemaleText_loc5`='我聽說蒼藍龍殿注入了地脈導入的能量。我將盡我所能護衛神殿。', `FemaleText_loc7`='He oído que el Santuario de Dragones Azur obtiene el poder directo de una línea Ley. Defenderé el templo lo mejor que pueda.' WHERE `ID`=26961;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말리고스가 부하들을 보내 요새를 공격하다니, 어처구니가 없습니다! 허락해 주신다면 목숨을 다해 이곳을 보호하겠습니다.', `MaleText_loc4`='猖狂的玛里苟斯居然让他的部队进攻龙眠神殿！请让我参与保卫神殿的战斗，我愿意为此付出生命的代价。', `MaleText_loc5`='瑪里苟斯派兵攻打神殿真是荒謬到極點!只要你允許，大人，我將以我的生命護衛我們。', `MaleText_loc7`='¡Es inconcebible que Malygos vaya a ordenar a sus tropas que ataquen el templo! Con su permiso, mi señor, nos defenderé con mi vida.', `FemaleText_loc1`='말리고스가 부하들을 보내 요새를 공격하다니, 어처구니가 없습니다! 허락해 주신다면 목숨을 다해 이곳을 보호하겠습니다.', `FemaleText_loc4`='猖狂的玛里苟斯居然让他的部队进攻龙眠神殿！请让我参与保卫神殿的战斗，我愿意为此付出生命的代价。', `FemaleText_loc5`='瑪里苟斯派兵攻打神殿真是荒謬到極點!只要你允許，大人，我將以我的生命護衛我們。', `FemaleText_loc7`='¡Es inconcebible que Malygos vaya a ordenar a sus tropas que ataquen el templo! Con su permiso, mi señor, nos defenderé con mi vida.' WHERE `ID`=26962;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아, 왜 이렇게 되었을꼬?', `MaleText_loc4`='我们来这里做什么？', `MaleText_loc5`='我們達成了些什麼?', `MaleText_loc7`='¿Adónde hemos llegado?' WHERE `ID`=26963;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해야 할 일을 하여라.', `MaleText_loc4`='完成我们应尽的使命。', `MaleText_loc5`='做你必須做的。', `MaleText_loc7`='Haz lo que sea necesario.' WHERE `ID`=26964;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반드시 요새를 보호해야 하오.', `MaleText_loc4`='不惜一切代价，守住神殿！', `MaleText_loc5`='不惜一切代價守護神殿。', `MaleText_loc7`='Defiende el templo cueste lo que cueste.' WHERE `ID`=26965;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙다, 나의 친구여. 가거라.', `MaleText_loc4`='谢谢你，朋友。出发吧。', `MaleText_loc5`='謝謝你，我的朋友。去吧。', `MaleText_loc7`='Gracias, amigo. Ve.' WHERE `ID`=26966;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='유감스럽지만, 꼭 필요한 일이다.', `MaleText_loc4`='很遗憾，我们必须战斗。', `MaleText_loc5`='很遺憾，但非如此不可。', `MaleText_loc7`='Es lamentable, pero necesario.' WHERE `ID`=26967;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠다. 전력을 기울이되 반드시 살아서 돌아오너라.', `MaleText_loc4`='去吧。请你平安归来。', `MaleText_loc5`='是的，你一定要盡可能安然回來。', `MaleText_loc7`='Sí. Haz lo que puedas por volver de una pieza.' WHERE `ID`=26968;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='허락하겠다.', `MaleText_loc4`='去吧，我允许你参与战斗。', `MaleText_loc5`='你有我的許可。', `MaleText_loc7`='Tienes mi permiso.' WHERE `ID`=26969;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수백 년을 살아오면서도 이런 일이 생길 줄은 꿈에도 생각지 못했구나...', `MaleText_loc4`='我不曾料到局势会发展到今天这步田地。', `MaleText_loc5`='在我過去的數個世紀中，我從未夢想過事情會進展到如此地步。', `MaleText_loc7`='En todos mis siglos de vida, jamás soñé que llegaríamos a esto.' WHERE `ID`=26970;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방금 놈들의 역병 수레를 본 것 같은데!', `MaleText_loc4`='我看见了一辆天灾战车！', `MaleText_loc5`='我想我看到他們其中一台瘟疫戰車了!', `MaleText_loc7`='¡Creo que veo uno de sus vagones de peste!', `FemaleText_loc1`='방금 놈들의 역병 수레를 본 것 같은데!', `FemaleText_loc4`='我看见了一辆天灾战车！', `FemaleText_loc5`='我想我看到他們其中一台瘟疫戰車了!', `FemaleText_loc7`='¡Creo que veo uno de sus vagones de peste!' WHERE `ID`=26971;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 탄돌 교각 부순 얘기를 해드린 적이 있던가요? 그래요. 그걸 무너뜨린 건 검은무쇠 부족 따위가 아니라 바로 저였다고요!', `MaleText_loc4`='萨多尔大桥是我炸毁的！我难道没有告诉你们？真的，所谓黑铁矮人破坏了大桥，那都是谣传！我才是真凶！', `MaleText_loc5`='我有沒有跟你們這些士兵提過，我摧毀薩多爾大橋的時光?沒錯，不是黑鐵矮人摧毀的!是我!', `MaleText_loc7`='Soldados, ¿alguna vez os he hablado sobre cuando destruí el Puente Thandol? Sí, no fueron los Hierro Negro. ¡Fui yo!', `FemaleText_loc1`='제가 탄돌 교각 부순 얘기를 해드린 적이 있던가요? 그래요. 그걸 무너뜨린 건 검은무쇠 부족 따위가 아니라 바로 저였다고요!', `FemaleText_loc4`='萨多尔大桥是我炸毁的！我难道没有告诉你们？真的，所谓黑铁矮人破坏了大桥，那都是谣传！我才是真凶！', `FemaleText_loc5`='我有沒有跟你們這些士兵提過，我摧毀薩多爾大橋的時光?沒錯，不是黑鐵矮人摧毀的!是我!', `FemaleText_loc7`='Soldados, ¿alguna vez os he hablado sobre cuando destruí el Puente Thandol? Sí, no fueron los Hierro Negro. ¡Fui yo!' WHERE `ID`=26972;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이해가 안 돼요. 낙스라마스를 윈터가드 성채 위로 보내서 다 날려버리면 될 텐데, 왜 그러지 않는 걸까요? 제가 켈투자드였다면 그렇게 했을 텐데.', `MaleText_loc4`='这样毫无道理啊。为什么天灾军团不将纳克萨玛斯飞到暮冬要塞上空，然后直接炸毁它呢？我是说，如果我是克尔苏加德，肯定这么做啦。', `MaleText_loc5`='這不合理。他們為什麼不乾脆把納克薩瑪斯飛到溫特加德要塞上空，把它炸翻就算了?我是說，如果我是科爾蘇加德的話，我就會這麼做。', `MaleText_loc7`='No tiene sentido. ¿Por qué no sitúan Naxxramas sobre la Fortaleza de Hibergarde y la bombardean desde ahí? Quiero decir que si yo fuera Kel''Thuzad, haría eso.', `FemaleText_loc1`='이해가 안 돼요. 낙스라마스를 윈터가드 성채 위로 보내서 다 날려버리면 될 텐데, 왜 그러지 않는 걸까요? 제가 켈투자드였다면 그렇게 했을 텐데.', `FemaleText_loc4`='这样毫无道理啊。为什么天灾军团不将纳克萨玛斯飞到暮冬要塞上空，然后直接炸毁它呢？我是说，如果我是克尔苏加德，肯定这么做啦。', `FemaleText_loc5`='這不合理。他們為什麼不乾脆把納克薩瑪斯飛到溫特加德要塞上空，把它炸翻就算了?我是說，如果我是科爾蘇加德的話，我就會這麼做。', `FemaleText_loc7`='No tiene sentido. ¿Por qué no sitúan Naxxramas sobre la Fortaleza de Hibergarde y la bombardean desde ahí? Quiero decir que si yo fuera Kel''Thuzad, haría eso.' WHERE `ID`=26973;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 이상한 광석의 비밀을 풀 수 있을지 모르겠네요. 쓸모가 있긴 있을 텐데 말이지요!', `MaleText_loc4`='或许有一天，我们能揭开这种神秘矿石的真面目。那时我们就可以好好利用它啦。', `MaleText_loc5`='我好奇我們能不能把這奇怪礦石之迷解決。這一定能派上用場的!', `MaleText_loc7`='Me pregunto si alguna vez desvelaremos el misterio de la extraña mena. ¡Tiene que servir para algo!', `FemaleText_loc1`='그 이상한 광석의 비밀을 풀 수 있을지 모르겠네요. 쓸모가 있긴 있을 텐데 말이지요!', `FemaleText_loc4`='或许有一天，我们能揭开这种神秘矿石的真面目。那时我们就可以好好利用它啦。', `FemaleText_loc5`='我好奇我們能不能把這奇怪礦石之迷解決。這一定能派上用場的!', `FemaleText_loc7`='Me pregunto si alguna vez desvelaremos el misterio de la extraña mena. ¡Tiene que servir para algo!' WHERE `ID`=26974;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발가드의 맥고이버를 아는 사람 있어요? 제 삼촌이죠. 그분 칭호가 뭔지 알아요? 전문가라고요. 그래요, 그냥 "전문가"요. 저도 전문가가 되고 싶어요.', `MaleText_loc4`='嘿，你们认识瓦加德的米克高维尔吗？他是我的叔叔哦。那你们知道他的头衔吗？“专家。”听听，多帅气啊。我也想成为一名专家。', `MaleText_loc5`='嘿，你知道瓦爾加德的馬概先嗎?他是我叔叔。你知道他的稱號嗎?專家。對，就是『專家』。我也想要當個專家。', `MaleText_loc7`='Oye, ¿alguno de ustedes conoce a McGoyver de Valgarde? Es mi tío. ¿Saben cuál es su título? Pro. Sí, sencillamente "Pro." Yo también quiero ser un pro.', `FemaleText_loc1`='발가드의 맥고이버를 아는 사람 있어요? 제 삼촌이죠. 그분 칭호가 뭔지 알아요? 전문가라고요. 그래요, 그냥 "전문가"요. 저도 전문가가 되고 싶어요.', `FemaleText_loc4`='嘿，你们认识瓦加德的米克高维尔吗？他是我的叔叔哦。那你们知道他的头衔吗？“专家。”听听，多帅气啊。我也想成为一名专家。', `FemaleText_loc5`='嘿，你知道瓦爾加德的馬概先嗎?他是我叔叔。你知道他的稱號嗎?專家。對，就是『專家』。我也想要當個專家。', `FemaleText_loc7`='Oye, ¿alguno de ustedes conoce a McGoyver de Valgarde? Es mi tío. ¿Saben cuál es su título? Pro. Sí, sencillamente "Pro." Yo también quiero ser un pro.' WHERE `ID`=26975;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭔가 이상한 냄새가 나는군요! 제가 아닌 건 분명하다고요. 노움은 모름지기 버터와 햇살 냄새를 풍기니까요. 트로그 겨드랑이에서 태어난 것 같은 냄새를 풍기는 드워프와는 다르다고요! 여기에 드워프가 있는 건 아니겠죠?', `MaleText_loc4`='什么东西这么臭啊！肯定不是我。侏儒散发着黄油和阳光的味道，才不像那些脏兮兮的矮人。他们简直像从穴居人的腋窝里爬出来的一样！这里没有矮人，对吧？', `MaleText_loc5`='某個很嗆的東西在這發臭!那肯定不是我，地精聞起來像奶油，像陽光。不像那些矮人，聞起來就像從穴居怪的胳肢窩出生的一樣!你們沒有人是矮人吧，有嗎?', `MaleText_loc7`='¡Aquí algo apesta! Y no soy yo. Los gnomos huelen a mantequilla y rayos de sol. ¡No como esos enanos que huelen como si hubieran nacido del sobaco de un trogg! Ninguno de ustedes es un enano, ¿verdad?', `FemaleText_loc1`='뭔가 이상한 냄새가 나는군요! 제가 아닌 건 분명하다고요. 노움은 모름지기 버터와 햇살 냄새를 풍기니까요. 트로그 겨드랑이에서 태어난 것 같은 냄새를 풍기는 드워프와는 다르다고요! 여기에 드워프가 있는 건 아니겠죠?', `FemaleText_loc4`='什么东西这么臭啊！肯定不是我。侏儒散发着黄油和阳光的味道，才不像那些脏兮兮的矮人。他们简直像从穴居人的腋窝里爬出来的一样！这里没有矮人，对吧？', `FemaleText_loc5`='某個很嗆的東西在這發臭!那肯定不是我，地精聞起來像奶油，像陽光。不像那些矮人，聞起來就像從穴居怪的胳肢窩出生的一樣!你們沒有人是矮人吧，有嗎?', `FemaleText_loc7`='¡Aquí algo apesta! Y no soy yo. Los gnomos huelen a mantequilla y rayos de sol. ¡No como esos enanos que huelen como si hubieran nacido del sobaco de un trogg! Ninguno de ustedes es un enano, ¿verdad?' WHERE `ID`=26976;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 드워프가 말이지요, 노움은 원래 땅속에서 태어난 존재라고 주장하는 거 있죠. 모든 노움의 시조는 모래 노움이라나? 말이 되는 소리를 해야지요! 모래 노움? 세상에나!', `MaleText_loc4`='我认识一个矮人，这家伙宣称侏儒是从地下进化来的。我们的祖先是沙漠侏儒。简直是一派胡言！还沙漠侏儒呢！我呸！', `MaleText_loc5`='我認識過一個矮人，他聲稱地精是從地底下進化的。我們全都是從沙子地精開始的。哪來那麼多鬼扯!沙子地精?最好是啦!', `MaleText_loc7`='Conocía a un enano que decía que los gnomos habían evolucionado de debajo de la tierra. Que todos comenzamos siendo gnomos de arena. ¡Qué montón de tonterías! ¿Gnomos de arena? ¡POR FAVOR!', `FemaleText_loc1`='어떤 드워프가 말이지요, 노움은 원래 땅속에서 태어난 존재라고 주장하는 거 있죠. 모든 노움의 시조는 모래 노움이라나? 말이 되는 소리를 해야지요! 모래 노움? 세상에나!', `FemaleText_loc4`='我认识一个矮人，这家伙宣称侏儒是从地下进化来的。我们的祖先是沙漠侏儒。简直是一派胡言！还沙漠侏儒呢！我呸！', `FemaleText_loc5`='我認識過一個矮人，他聲稱地精是從地底下進化的。我們全都是從沙子地精開始的。哪來那麼多鬼扯!沙子地精?最好是啦!', `FemaleText_loc7`='Conocía a un enano que decía que los gnomos habían evolucionado de debajo de la tierra. Que todos comenzamos siendo gnomos de arena. ¡Qué montón de tonterías! ¿Gnomos de arena? ¡POR FAVOR!' WHERE `ID`=26977;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 참담한 광경은 본 적이 없어...', `MaleText_loc4`='我从未见过如此严重的破坏程度……', `MaleText_loc5`='我從來沒見過這樣子的破壞...', `MaleText_loc7`='Jamás había visto tanta destrucción...', `FemaleText_loc1`='이렇게 참담한 광경은 본 적이 없어...', `FemaleText_loc4`='我从未见过如此严重的破坏程度……', `FemaleText_loc5`='我從來沒見過這樣子的破壞...', `FemaleText_loc7`='Jamás había visto tanta destrucción...' WHERE `ID`=26978;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조용히들 해. 절대 방심해서는 안 된다고!', `MaleText_loc4`='安静！我们要保持警惕！', `MaleText_loc5`='大家把聊天的音量降低，我們要保持警覺!', `MaleText_loc7`='Parlotead más bajo. ¡Tenemos que mantenernos alerta!', `FemaleText_loc1`='조용히들 해. 절대 방심해서는 안 된다고!', `FemaleText_loc4`='安静！我们要保持警惕！', `FemaleText_loc5`='大家把聊天的音量降低，我們要保持警覺!', `FemaleText_loc7`='Parlotead más bajo. ¡Tenemos que mantenernos alerta!' WHERE `ID`=26979;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여긴 어딜 가든 죽음의 냄새가 진동하는군.', `MaleText_loc4`='死亡的气息覆盖着这里的每一寸土地。', `MaleText_loc5`='死亡的氣味遍佈這每一吋的土地。', `MaleText_loc7`='El olor de la muerte cubre cada centímetro de este lugar.', `FemaleText_loc1`='여긴 어딜 가든 죽음의 냄새가 진동하는군.', `FemaleText_loc4`='死亡的气息覆盖着这里的每一寸土地。', `FemaleText_loc5`='死亡的氣味遍佈這每一吋的土地。', `FemaleText_loc7`='El olor de la muerte cubre cada centímetro de este lugar.' WHERE `ID`=26980;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='운전수 양반, 당신이 이 지옥에서 마을 사람들을 아주 쉽게 구해냈다던데, 그게 사실인가요?', `MaleText_loc4`='听说你独自一人就将村民们空运到安全地带，使他们免受苦难的折磨。是真的吗？', `MaleText_loc5`='司機大哥，我聽說你單槍匹馬把我們的村民從這個鬼洞裡面空運出去。這是真的嗎?', `MaleText_loc7`='Piloto, he oído que tú solo sacaste volando a nuestros ciudadanos de este agujero infernal. ¿Es cierto?', `FemaleText_loc1`='운전수 양반, 당신이 이 지옥에서 마을 사람들을 아주 쉽게 구해냈다던데, 그게 사실인가요?', `FemaleText_loc4`='听说你独自一人就将村民们空运到安全地带，使他们免受苦难的折磨。是真的吗？', `FemaleText_loc5`='司機大哥，我聽說你單槍匹馬把我們的村民從這個鬼洞裡面空運出去。這是真的嗎?', `FemaleText_loc7`='Piloto, he oído que tú solo sacaste volando a nuestros ciudadanos de este agujero infernal. ¿Es cierto?' WHERE `ID`=26981;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='텔잔에 대해 뭔가 아는 사람 없나? 그놈은 정체가 뭐지? 대체 어떻게 스컬지 지상군을 통솔하게 된 걸까?', `MaleText_loc4`='有谁知道塞尔赞吗？他是谁？他是如何成为统领天灾军团地面部队的统帅的？', `MaleText_loc5`='那，有人認識賽爾贊嗎?他老兄是誰?他是怎麼變成天譴軍部隊地面的領導人的?', `MaleText_loc7`='Entonces, ¿alguien sabe algo acerca de Thel''zan? ¿Quién es? ¿Cómo llegó a dirigir a los ejércitos de tierra de la Plaga?', `FemaleText_loc1`='텔잔에 대해 뭔가 아는 사람 없나요? 그놈은 정체가 뭐죠? 대체 어떻게 스컬지 지상군을 통솔하게 된 걸까요?', `FemaleText_loc4`='有谁知道塞尔赞吗？他是谁？他是如何成为统领天灾军团地面部队的统帅的？', `FemaleText_loc5`='那，有人認識賽爾贊嗎?他老兄是誰?他是怎麼變成天譴軍部隊地面的領導人的?', `FemaleText_loc7`='Entonces, ¿alguien sabe algo acerca de Thel''zan? ¿Quién es? ¿Cómo llegó a dirigir a los ejércitos de tierra de la Plaga?' WHERE `ID`=26982;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 참상을 보세요... 스컬지 놈들에게 반드시 되돌려 주겠어요!', `MaleText_loc4`='瞧瞧眼前的惨状……天灾军团会此付出代价的！', `MaleText_loc5`='看看這片狼藉...天譴軍將為此付出代價!', `MaleText_loc7`='Mirad este desastre... ¡La Plaga pagará por esto!', `FemaleText_loc1`='이 참상을 보세요... 스컬지 놈들에게 반드시 되돌려 주겠어요!', `FemaleText_loc4`='瞧瞧眼前的惨状……天灾军团会此付出代价的！', `FemaleText_loc5`='看看這片狼藉...天譴軍將為此付出代價!', `FemaleText_loc7`='Mirad este desastre... ¡La Plaga pagará por esto!' WHERE `ID`=26983;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시체는 다 어디 갔지? 우리 주민들을 대체 어떻게 한 거야?', `MaleText_loc4`='尸体都到哪儿去了？他们对村民们做了什么？', `MaleText_loc5`='屍體去哪裡了?他們對我們的人做了些什麼?', `MaleText_loc7`='¿Dónde están los cadáveres? ¿Qué han hecho con nuestra gente?', `FemaleText_loc1`='시체는 다 어디 갔지? 우리 주민들을 대체 어떻게 한 거야?', `FemaleText_loc4`='尸体都到哪儿去了？他们对村民们做了什么？', `FemaleText_loc5`='屍體去哪裡了?他們對我們的人做了些什麼?', `FemaleText_loc7`='¿Dónde están los cadáveres? ¿Qué han hecho con nuestra gente?' WHERE `ID`=26984;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꼭 살아남아서, 아서스가 대가를 치르는 꼴을 제 두 눈으로 보고 말겠어요.', `MaleText_loc4`='我希望自己能亲眼目睹阿尔萨斯接受命运的审判！', `MaleText_loc5`='我希望我能活到看見阿薩斯的下場。', `MaleText_loc7`='Espero vivir para ver cómo Arthas recibe su merecido.', `FemaleText_loc1`='꼭 살아남아서, 아서스가 대가를 치르는 꼴을 제 두 눈으로 보고 말겠어요.', `FemaleText_loc4`='我希望自己能亲眼目睹阿尔萨斯接受命运的审判！', `FemaleText_loc5`='我希望我能活到看見阿薩斯的下場。', `FemaleText_loc7`='Espero vivir para ver cómo Arthas recibe su merecido.' WHERE `ID`=26985;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불탑니다!', `MaleText_loc4`='烧起来了！', `MaleText_loc5`='燒起來啦!', `MaleText_loc7`='¡Quema!' WHERE `ID`=26986;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제발! 불 좀 꺼주세요!', `MaleText_loc4`='天哪！快灭火！', `MaleText_loc5`='幫幫忙!救救火!', `MaleText_loc7`='¡Por favor! ¡Haz que deje de quemar!' WHERE `ID`=26987;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜일까요!', `MaleText_loc4`='怎么会这样！', `MaleText_loc5`='哎呀!', `MaleText_loc7`='¡Por qué!' WHERE `ID`=26988;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='즐거운 겨울맞이 축제 보내세요!', `MaleText_loc4`='冬幕节快乐！', `MaleText_loc5`='冬幕節快樂!', `MaleText_loc7`='¡Feliz Festival de Invierno!' WHERE `ID`=26989;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 동족 대부분은 호드가 야만적이라며 경멸합니다. 저도 한때 그런 이들 중 하나였지요. 그래서 습기 차고 향기로운 이곳으로 이동하라는 명령을 처음 받았을 때는 제 운명을 얼마나 원망했는지 모릅니다.$b$b그런데, 여기서 연구를 하던 중에 제가 처한 환경에 감사하게 되었지요. 독특한 매력이 있는 곳입니다. 그렇지 않습니까?$b$b아, 제가 어떤 연구를 했는지 궁금하시겠군요. 저는 여기로 순간이동하는 마법을 연구했습니다. 가르쳐 드릴까요?', `MaleText_loc4`='大部分血精灵都对部落的“野蛮习气”嗤之以鼻，我当然也不例外。当我刚刚被派到这又潮湿又……芳香的地方时，我觉得自己实在是太不走运了。$B$B渐渐地，我发现这里的环境还是挺棒的。你觉得呢？$b$b我的研究工作也觉得了不小的进展。嗯，只需一个小法术，法师们就能回到这里哦。你想学习吗？', `MaleText_loc5`='我的兄弟當中大部分的人對於部落的「野蠻」方式很引以為傲，而我曾經也是他們其中的一員。當我第一次指揮這個有點潮濕且...芳香的地方時，我詛咒我的運氣。$b$b然而，在我進行研究的這段期間，我漸漸喜歡上我身處的環境。這地方很迷人，你不覺得嗎?$b$b啊，當然，還有我的研究，可以讓其他的法師使用法術回到這裡。我教你好嗎?', `MaleText_loc7`='La mayoría de mis hermanos desaprueban los medios "bárbaros" de la Horda y hubo un tiempo en el que yo era uno de ellos. Cuando me ordenaron venir a este húmedo y... aromático lugar, maldije mi suerte.$B$BPero, mientras llevaba a cabo mis estudios, he acabado apreciando lo que me rodea. Tiene cierto encanto, ¿no crees?$B$BAh y mis estudios, por supuesto, permitirán que otros magos vuelvan aquí con un hechizo. ¿Te lo enseño?' WHERE `ID`=26990;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 동족 대부분은 호드가 야만적이라며 경멸합니다. 저도 한때 그런 이들 중 하나였지요. 그래서 습기 차고 향기로운 이곳으로 이동하라는 명령을 처음 받았을 때는 제 운명을 얼마나 원망했는지 모릅니다.$b$b그런데, 여기서 연구를 하던 중에 제가 처한 환경에 감사하게 되었지요. 독특한 매력이 있는 곳입니다. 그렇지 않습니까?$b$b...마법사가 아니니 제가 어떤 연구를 했는지 궁금하시지는 않겠죠?', `MaleText_loc4`='大部分血精灵都对部落的“野蛮习气”嗤之以鼻，我当然也不例外。当我刚刚被派到这又潮湿又……芳香的地方时，我觉得自己实在是太不走运了。$B$B渐渐地，我发现这里的环境还是挺棒的。你觉得呢？$b$b我和你废什么话呢……你又不是法师，对我的研究肯定没兴趣。', `MaleText_loc5`='我的兄弟當中大部分的人對於部落的「野蠻」方式很引以為傲，而我曾經也是他們其中的一員。當我第一次指揮這個有點潮濕且...芳香的地方時，我詛咒我的運氣。$b$b然而，在我進行研究的這段期間，我漸漸喜歡上我身處的環境。這地方很迷人，你不覺得嗎?$b$b...當然，你不會對我的研究有興趣，你本身並不是位法師。', `MaleText_loc7`='"La mayoría de mis hermanos desaprueban los medios "bárbaros" de la Horda y hubo un tiempo en el que yo era uno de ellos. Cuando me ordenaron venir a este húmedo y... aromático lugar, maldije mi suerte.$B$BPero, mientras llevaba a cabo mis estudios, he acabado apreciando lo que me rodea. Tiene cierto encanto, ¿no crees?$B$BNo creo que te interesen mis estudios ya que no eres $gun mago:una maga;...' WHERE `ID`=26991;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아, 난 스토나드의 향기를 사랑해! 마치... 오크의 땀 같은 향기야. 썩은 냄새도 좀 나지만, 섞이면 상당히 향기롭게 느껴지지! 익숙해지면 아주 사랑스러운 냄새야.', `MaleText_loc4`='啊，我热爱斯通纳德的气息。就好像……好像……兽人的汗液。还混合着腐烂的味道。你知道，混合的气味总是很好闻的！', `MaleText_loc5`='啊，我愛死了斯通納德的氣味!聞起來就像...就像...獸人的汗水。還有腐敗的氣味。靜滯，混合，結果可以是非常愉悅的!這不是自然生成的氣味。', `MaleText_loc7`='¡Ah, adoro el olor del Rocal! Huele como a... a... sudor orco. Y podrido. ¡Pero, el efecto combinado puede ser bastante agradable! Es un gusto adquirido.' WHERE `ID`=26992;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기를 방문하는 사람들은 공기가 너무 눅눅하다고 불평을 하지만, 사실 그게 내 빛나는 피부의 비결이지! 건조한 피부는 보기에 안 좋다고.', `MaleText_loc4`='很多人抱怨这里的潮湿气候，不过我发现它对皮肤很有好处！没有水分的皮肤可不会吹弹欲破。', `MaleText_loc5`='當到訪者抱怨著有關這裡異常潮濕的空氣時，我卻發現這對我的氣色有所幫助!乾燥的皮膚一點都沒有吸引力。', `MaleText_loc7`='Aunque los visitantes se quejan del exceso de humedad que hay en el aire, yo creo que es bueno para mi tez. La piel seca es poco favorecedora.' WHERE `ID`=26993;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 문화에 자신을 깊숙이 동화시키면 어떤 이득이 있는지 내 동족이 전혀 알아채지 못한다니, 정말 끔찍하게 안타까운 일이야.', `MaleText_loc4`='我的同胞们无法领略这种感觉——当你真正融入某种文化时所感受到的好处，这真是太遗憾了。', `MaleText_loc5`='真是恥辱，可怕的恥辱，我的兄弟無法了解通透沉湎在一個文化中所帶來的好處。', `MaleText_loc7`='Es una lástima, una verdadera lástima, que mis hermanos no puedan ver los beneficios de adentrarse en una cultura.' WHERE `ID`=26994;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 여기 있노라. 작은 날벌레가 구름을 이뤄 문 없는 출입구를 자유로이 드나드는 이곳, 축축한 진흙투성이 땅에 선 투박한 돌탑 안에, 상스럽고 비위생적인 육중한 녹색 생명체 사이에! 내 평생 이보다 더 행복했던 적은 없어.', `MaleText_loc4`='你看，我现在就住在一座简陋不堪的石头哨塔里，望着外面泥泞的沼泽。大堆的苍蝇蚊虫到处乱飞，面如菜色、长满肉瘤的奇怪绿色生物四下游荡。我还能比现在更开心吗？', `MaleText_loc5`='我就在這裡，就位於一座蹲蜷於充滿著沼澤，泥濘土地當中的粗製塔樓，當雲般的蚊子群未經邀請的飛過開啟的門戶，以不合衛生及粗魯的方式停留在縮成一團，綠皮膚的物體上時。我從未如此開心過。', `MaleText_loc7`='Aquí estoy, en una tosca torre de piedra en medio de un barrizal pantanoso mientras nubes de mosquitos vuelan a sus anchas a través de las puertas abiertas, permaneciendo entre encorvadas y verdes figuras de dudosa higiene y bastos modales. Nunca había sido tan feliz.' WHERE `ID`=26995;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기로 발령나기 전에 진흙이 피부 미용에 얼마나 탁월한지 들은 적이 있지. 여기 와서 처음 나무뿌리에 걸려 넘어졌을 때, 그 탁월한 효과를 온몸으로 경험했어! 마력을 한 조각도 빌지 않고 그런 일을 할 수 있다니, 자연은 정말 놀랍기 그지없어.', `MaleText_loc4`='在被指派到这里之前，我只是听说过泥巴浴的保健效果而已。当我被一条树根绊倒在地后，我才真正体会到了它的好处！大自然真是奇妙啊，不借助魔法也可以产生如此奇妙的效果！', `MaleText_loc5`='在我被調派到這裡之前，我只有聽說過有關泥漿澡對於皮膚抗老化的效果。當我第一次被一根樹根絆倒時，我得到了全部的好處!驚訝於大自然的能力，甚至連一丁點的魔法幫助都不需要。', `MaleText_loc7`='Antes de que me destinaran aquí, apenas había oído hablar de los efectos rejuvenecedores de los baños de barro sobre la piel. ¡La primera vez que tropecé con la raíz de un árbol, descubrí todos sus beneficios! Es increíble lo que puede hacer la naturaleza, incluso sin un poco de magia que le ayude.' WHERE `ID`=26996;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 지금까지, 왜 다른 사람이 아닌 내가 이 특별한 장소로 보내졌는지 깊이 생각했어. 추측하건대 내 상관은 여기서 접할 수 있는 기이한 호드 문화에 금방 적응할 수 있는, 이 일에 딱 맞는 인물이 바로 나라고 생각했을 거야. 하지만 아주 악의 넘치는 소문을 들었는데, 내가 너무 말을 많이 해서 그가 날 여기로 보낸 거라더군.', `MaleText_loc4`='一直以来我都在思考一个问题，那就是，我为什么会被选中，来到这个地方。我只能认为是我的上级觉得只有我才能胜任这样的任务，迅速适应部落的独特文化，但是坊间还有一个听起来很伤自尊的说法，那就是因为我说话太多了。', `MaleText_loc5`='時至今日，我深思，為什麼我自己會被挑選前來這個特殊的地方。我只能猜想我的長官覺得我是唯一適合此任務，並且能夠快速適應這裡的部落古怪文化的人，不過我有聽說一個非常氣度狹小的謠傳，說有可能是因為我太多話了。', `MaleText_loc7`='Todavía hoy me pregunto por qué me han elegido a mí para este destino. No puedo más que pensar que mi superior me consideraba el más adecuado para esta tarea y que pronto me acostumbraré a la pintoresca cultura de la Horda en este lugar, pero he oído rumores de que puede ser porque hablo demasiado.' WHERE `ID`=26997;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네? 아, 제가 좀 정신이 없어서 죄송합니다. 북부감시 요새에 계신 분들이 걱정돼서 말입니다. 제자들을 좀 보내 드릴 걸 잘못했어요. 자, 무엇을 도와드릴까요?', `MaleText_loc4`='嗯？哦，请原谅我的心不在焉。我正在为北方城堡的伙计们担心，我应该派些学徒去帮他们的……你有什么事吗？', `MaleText_loc5`='嗯?喔。要是我看起來不太專心的話，請見諒;我正擔心著北方城堡的人。我應該要派遣我的學生前往援助他們。現在，我要怎麼幫助你呢?', `MaleText_loc7`='¿Ehm? Oh. Perdona si parezco distraído; me preocupan los hombres del Fuerte del Norte. Debí haber enviado a algunos de mis estudiantes a ayudarles. Bueno, ¿en qué puedo ayudarte?', `FemaleText_loc1`='네? 아, 제가 좀 정신이 없어서 죄송합니다. 북부감시 요새에 계신 분들이 걱정돼서 말입니다. 제자들을 좀 보내 드릴 걸 잘못했어요. 자, 무엇을 도와드릴까요?', `FemaleText_loc4`='嗯？哦，请原谅我的心不在焉。我正在为北方城堡的伙计们担心，我应该派些学徒去帮他们的……你有什么事吗？', `FemaleText_loc5`='嗯?喔。要是我看起來不太專心的話，請見諒;我正擔心著北方城堡的人。我應該要派遣我的學生前往援助他們。現在，我要怎麼幫助你呢?', `FemaleText_loc7`='¿Ehm? Oh. Perdona si parezco distraído; me preocupan los hombres del Fuerte del Norte. Debí haber enviado a algunos de mis estudiantes a ayudarles. Bueno, ¿en qué puedo ayudarte?' WHERE `ID`=26998;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네? 아, 제가 좀 정신이 없어서 죄송합니다. 북부감시 요새에 계신 분들이 걱정돼서 말입니다. 제자들을 좀 보내 드릴 걸 잘못했어요...', `MaleText_loc4`='嗯？哦，请原谅我的心不在焉。我正在为北方城堡的伙计们担心，我应该派些学徒去帮他们的……', `MaleText_loc5`='嗯?喔。要是我看起來不太專心的話，請見諒;我正擔心著北方城堡的人。我應該要派遣我的學生前往援助他們...', `MaleText_loc7`='¿Ehm? Oh. Perdona si parezco distraído; me preocupan los hombres del Fuerte del Norte. Debí haber enviado a algunos de mis estudiantes a ayudarles...', `FemaleText_loc1`='네? 아, 제가 좀 정신이 없어서 죄송합니다. 북부감시 요새에 계신 분들이 걱정돼서 말입니다. 제자들을 좀 보내 드릴 걸 잘못했어요...', `FemaleText_loc4`='嗯？哦，请原谅我的心不在焉。我正在为北方城堡的伙计们担心，我应该派些学徒去帮他们的……', `FemaleText_loc5`='嗯?喔。要是我看起來不太專心的話，請見諒;我正擔心著北方城堡的人。我應該要派遣我的學生前往援助他們...', `FemaleText_loc7`='¿Ehm? Oh. Perdona si parezco distraído; me preocupan los hombres del Fuerte del Norte. Debí haber enviado a algunos de mis estudiantes a ayudarles...' WHERE `ID`=26999;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거 조용히 좀 하시오.', `MaleText_loc4`='安静。', `MaleText_loc5`='安靜點。', `MaleText_loc7`='Silencio.' WHERE `ID`=27000;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 블러드 엘프들이 오기 전엔 여기가 얼마나 조용했는지 기억하나? 그때가 그립군.', `MaleText_loc4`='还记得精灵们来这里之前的安静日子吗？我真怀念那时候。', `MaleText_loc5`='還記得這裡在精靈們到來之前有多安靜嗎?我真懷念那時候。', `MaleText_loc7`='¿Recuerdas lo tranquilo que era esto antes de que llegaran los elfos? Lo echo de menos.' WHERE `ID`=27001;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='입 좀 다물라고.', `MaleText_loc4`='闭嘴。', `MaleText_loc5`='閉嘴。', `MaleText_loc7`='Cállate.' WHERE `ID`=27002;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='둘 중 누가 더 미친 건지 모르겠군.', `MaleText_loc4`='我不知道到底谁更疯狂一些。', `MaleText_loc5`='我不知道誰比較瘋狂。', `MaleText_loc7`='No estoy seguro de cuál está más loco.' WHERE `ID`=27003;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='귀마개를 하나 구할 수 있다면 내 막자사발이라도 기꺼이 팔겠네.', `MaleText_loc4`='我愿意用我的捣药杵换个耳塞。', `MaleText_loc5`='我願意將我的杵拿來交換一些耳塞。', `MaleText_loc7`='Cambiaría mi mortero por unos tapones para los oídos.' WHERE `ID`=27004;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제 가르침은 마법사에게만 유용하답니다. 그대는 $c|1이라;라; 도와 드릴 수 없겠네요.', `FemaleText_loc4`='我的魔法只传授给法师。很抱歉，$c。', `FemaleText_loc5`='我的知識只適用於法師。我沒辦法幫到你的忙，$c。', `FemaleText_loc7`='Mi enseñanzas solo son útiles para los magos. No puedo ayudarte, $c.' WHERE `ID`=27005;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='시누 아마노레. 테라모어로 차원문을 여는 마법을 배우려 하신다면, 제가 가르쳐 드리지요.', `FemaleText_loc4`='Sinu a''manore。如果你想要学习开启一道通向塞拉摩的传送门的法术，我可以帮你。', `FemaleText_loc5`='(薩拉斯語)很高興見到你。如果你想要學習如何召喚一道通往塞拉摩的傳送門，我可以教你。', `FemaleText_loc7`='Sinu a''manore. Si quieres aprender a invocar un portal a Theramore, puedo enseñarte.' WHERE `ID`=27006;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='케르사이, 주어진 환경에 감사하는 법도 좀 배우라고!', `MaleText_loc4`='你要学会尊重大自然，瑟尔希！', `MaleText_loc5`='你要學著喜歡你身處的環境，瑟賽!', `MaleText_loc7`='¡Tienes que aprender a apreciar lo que te rodea, Cersei!' WHERE `ID`=27007;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가을 축제는 첫해 이후로 조금 달라졌지. 지금은 상품권 대신 가을 축제 상품 교환 동전을 발급하고 있거든. 옛날 상품권을 아직 가지고 있다면 새 동전으로 교환해 주지.', `MaleText_loc4`='与第一届相比，美酒节已经发生了一些变化。今年，我们发行的是美酒节奖币，而不是奖券啦。如果你手里还有旧的奖券，我可以帮你兑换。', `MaleText_loc5`='啤酒節從第一年以來已經做了不少革新。我們現在是用啤酒節獎品章代替獎品卷。如果你還有舊的獎品卷，我可以幫你兌換成獎品章。', `MaleText_loc7`='La Fiesta de la Cerveza ha sufrido algunos cambios desde el primer año. Ahora entregamos fichas de la Fiesta de la Cerveza en vez de vales. Si tienes vales viejos, puedo cambiártelos.', `FemaleText_loc1`='가을 축제는 첫해 이후로 조금 달라졌지. 지금은 상품권 대신 가을 축제 상품 교환 동전을 발급하고 있거든. 옛날 상품권을 아직 가지고 있다면 새 동전으로 교환해 주지.', `FemaleText_loc4`='与第一届相比，美酒节已经发生了一些变化。今年，我们发行的是美酒节奖币，而不是奖券啦。如果你手里还有旧的奖券，我可以帮你兑换。', `FemaleText_loc5`='啤酒節從第一年以來已經做了不少革新。我們現在是用啤酒節獎品章代替獎品卷。如果你還有舊的獎品卷，我可以幫你兌換成獎品章。', `FemaleText_loc7`='La Fiesta de la Cerveza ha sufrido algunos cambios desde el primer año. Ahora entregamos fichas de la Fiesta de la Cerveza en vez de vales. Si tienes vales viejos, puedo cambiártelos.' WHERE `ID`=27008;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 가진 상품권을 새로 나온 동전으로 교환하고 싶습니다.', `MaleText_loc4`='我要把背包里的奖券兑换成新的奖币。', `MaleText_loc5`='我想要把我物品欄裡的獎品卷換成新的獎品章。', `MaleText_loc7`='Me gustaría cambiar los vales de mi inventario por las nuevas fichas.', `FemaleText_loc1`='제가 가진 상품권을 새로 나온 동전으로 교환하고 싶어요.', `FemaleText_loc4`='我要把背包里的奖券兑换成新的奖币。', `FemaleText_loc5`='我想要把我物品欄裡的獎品卷換成新的獎品章。', `FemaleText_loc7`='Me gustaría cambiar los vales de mi inventario por las nuevas fichas.' WHERE `ID`=27009;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도대체 이 우체통을 누가 자꾸 고장 내놓는 거지?', `MaleText_loc4`='谁在不停地搞破坏？', `MaleText_loc5`='誰一直在弄壞這個東西?!', `MaleText_loc7`='¿Quién está venga a romper esta cosa?' WHERE `ID`=27010;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 우체통은 고쳐놓기가 무섭게 누군가 망가뜨리는군. 만 하루도 지나지 않았는데 말이야.', `MaleText_loc4`='每次我修好邮箱之后，不到一天它就又坏掉了。', `MaleText_loc5`='每次我修好這個郵箱，不到一天就又被弄壞了。', `MaleText_loc7`='Cada vez que arreglo este buzón, viene alguien y lo vuelve a destrozar en menos de un día.' WHERE `ID`=27011;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='입체영상 방출장치를 계속 건드리는 자식이 걸리기만 하면...', `MaleText_loc4`='如果让我抓住破坏影像生成器的混账……', `MaleText_loc5`='要是讓我抓到是誰在破壞這個全能發送機...', `MaleText_loc7`='Si atrapo al que se dedica a romper este holo-emisor...' WHERE `ID`=27012;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음. 이제 제대로 돌아가는 것 같군...', `MaleText_loc4`='嗯。似乎邮箱又恢复正常啦……', `MaleText_loc5`='嗯。看來似乎又可以正常運作了...', `MaleText_loc7`='Hmm. Parece que vuelve a funcionar con normalidad...' WHERE `ID`=27013;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신사 숙녀 여러분... 투기장으로 모이십시오!', `MaleText_loc4`='女士们，先生们……欢迎来到斗兽场！', `MaleText_loc5`='先生小姐們...請往場邊移動!', `MaleText_loc7`='Señoras y señores... ¡reúnanse alrededor del foso!' WHERE `ID`=27014;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 있는 선수는... 세계 정상급 $c인 $n입니다. 파충류, 포유류, 기계류, 그리고 용 종류를 해치운 선수입니다. 이 친구 같은 $r|1은;는; 그 어디에서도 보지 못하셨을 겁니다.', `MaleText_loc4`='下面我向大家介绍……$n，闻名于世的$c。$g他:她;是猛兽、机械构造体以及龙……龙族的终结者！你一定不曾见过这样的人物。', `MaleText_loc5`='一邊的角落為您介紹的是...$n，真正的世界級$c。爬蟲類、哺乳類、機器傀儡、奇怪龍...族的剋星。一位你從沒見過的$g男:女;$r。', `MaleText_loc7`='En un rincón tenemos a... $n, $gun:una; $c de fama mundial. $gAsesino:Asesina; de reptiles, mamíferos, ensamblajes mecánicos y algún que otro drago...nante. No habéis visto $gotro:otra:r; $r como $gél:ella;.' WHERE `ID`=27015;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이쪽에 있는 선수는, 연쇄살인범, 대량학살자이자 몇 번이나 교수형을 선고받았던... 호르그렌 헬클리브입니다! 신사 숙녀 여러분... 돈을 걸어 주십시오!', `MaleText_loc4`='接下来，$n的对手。这位令人闻风丧胆的连环杀手曾被判以多种极刑！他就是……霍尔格雷·地狱之斧！女士们，先生们……下注吧！', `MaleText_loc5`='另外一邊的角落，是一位連續殺人魔、大規模毀滅性武器，曾經被絞繩與鈍器處死好幾次!霍葛倫...地獄斬!先生小姐們...趕快下注吧!', `MaleText_loc7`='¡En el otro rincón un asesino en serie, descuartizador de masas, sentenciado a muerte por ahorcamiento y por objeto contundente varias veces! ¡Horgrenn... Garra Infernal! Señoras y señores... ¡hagan sus apuestas!' WHERE `ID`=27016;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신사 숙녀 여러분, 투기장으로 모이십시오! $r|1과;와; 곰의 시합에 돈을 걸고 마음껏 즐겨 보십시오!', `MaleText_loc4`='女士们，先生们，欢迎来到征服斗兽场！见证$r与巨熊的激战！下注吧！', `MaleText_loc5`='先生小姐們，請向征服之淵移動!目睹$r與猛熊之戰，並請踴躍下注!', `MaleText_loc7`='¡Señoras y señores, reúnanse alrededor de El Foso de la Conquista! ¡Sean testigos de la lucha entre $r y oso, y apuesten con confianza!' WHERE `ID`=27017;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여러분이 지금까지 보신 것은 시작에 불과합니다! 지금 투기장에서 $n|1이;가; 회색 구릉지의 토박이인 광포한 펄볼그와 한판 대결을 벌입니다! 자, 어서 돈을 거세요!', `MaleText_loc4`='你未曾见过的激战即将在征服斗兽场中上演！$n将挑战一头来自灰熊丘陵的熊怪！快下注吧！', `MaleText_loc5`='不要以為你什麼都見過!在征服之淵各位的眼前，$n將嚴陣以待對付一頭正牌灰白之丘瘋狂的熊怪!下注吧，朋友們!', `MaleText_loc7`='¡Justo cuando creían haberlo visto todo! $n se medirá con un autentico fúrbolg enloquecido de las Colinas Pardas ante sus ojos, aquí, en El Foso de la Conquista. ¡Hagan sus apuestas!' WHERE `ID`=27018;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모이십시오, 여러분! 잘 보이는 자리에서 따끈한 음료를 즐기면서 $r|1과;와; 기계의 시합을 즐겨 보십시오!', `MaleText_loc4`='来吧！揣上一壶热酒，挑个好位子，观看$r与机械生物之间的决战！', `MaleText_loc5`='大家請靠近點!隨手拿杯飲料，找個好位置，你們將親眼目賭一場$r與機械之間的大戰!', `MaleText_loc7`='¡Reuníos todos alrededor! ¡Coged una bebida caliente y buscad un buen asiento porque estáis a punto de presenciar un enfrentamiento entre $r y máquina!' WHERE `ID`=27019;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='토르 모단 직송! 100퍼센트 순수 금속으로 만든 번개 동력 무쇠 골렘! 피녹빛파괴자를 소개합니다!', `MaleText_loc4`='它就是来自索尔莫丹，由百分百……纯……金属打造而成的闪电动力铁人——锈血！', `MaleText_loc5`='鐸爾莫丹原廠直送，值得人百分之百信賴...金屬打造...讓我為您介紹「鏽血」，閃電動力鐵魔像!', `MaleText_loc7`='Recién salido de Thor Modan y construido con... ¡metal cien por cien auténtico! ¡Aquí está Sangre Oxidada, el gólem férreo energizado por relámpagos!' WHERE `ID`=27020;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내년에 또 오셔서 새로운 즐거움을 누리세요!', `MaleText_loc4`='明年会有更多新惊喜！', `MaleText_loc5`='明年再來，會有驚喜等你!', `MaleText_loc7`='¡Vuelve el año que viene para obtener más sorpresas!' WHERE `ID`=27021;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='굴뚝나무 목장조합에서 폭발을 선물합니다!', `MaleText_loc4`='这是烟林牧场为你带来的惊喜！', `MaleText_loc5`='燻木牧場的爆炸波及到你!', `MaleText_loc7`='¡Los Pastos de Bosquehumeante os han ofrecido esta explosión!' WHERE `ID`=27022;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용서하시오. 나는 마력이 다해서 당신을 테라모어로 다시 돌려보낼 수 없소. 당신에게서 온 세상을 돌아다니는 모험가의 기상이 느껴지오. 당신이라면 제시간에 테라모어에 도달하는 다른 방법을 알고 있으리라 확신하오.', `MaleText_loc4`='很抱歉，我已经筋疲力尽了，不能运用魔法将你送回塞拉摩岛。你是位经验丰富的探险家吧，应该知道如何返回那里。', `MaleText_loc5`='原諒我，不過我精疲力盡了，無法使用我的魔法將你傳送回去塞拉摩。你看起來一臉就是個老練的探險者;我想你當然會知道另一個可以即時抵達塞拉摩的方式。', `MaleText_loc7`='Perdóname, pero estoy agotado y no puedo usar mi magia para enviarte de vuelta a Theramore. Tienes pinta de $gaventurero:aventurera;, seguro que encuentras otro modo de llegar a Theramore a tiempo.' WHERE `ID`=27023;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어딘가로 가고 싶으신가요?$B$B아니면 뭔가 근심거리가 있으신가요?', `FemaleText_loc4`='$r，想要搭乘双足飞龙吗？$B$B或者你有什么烦心事儿想向我倾诉？', `FemaleText_loc5`='搭個便車嗎，$r?$B$B還是說，有其他事情在困擾你?', `FemaleText_loc7`='¿Vienes para viajar, $r?$B$B¿O te preocupa algo más?' WHERE `ID`=27024;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='애완견을 데려왔군...', `FemaleText_loc4`='哟，你连宠物也带来啦。', `FemaleText_loc5`='我看見你帶來了寵物。', `FemaleText_loc7`='Veo que has traído a tus mascotas.' WHERE `ID`=27025;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='꼭 이런 식으로 끝낼 필요는 없잖아. 그렇지 않아?', `FemaleText_loc4`='我们有必要闹得这么僵吗？', `FemaleText_loc5`='事情不必走到這步田地的，你懂嗎?', `FemaleText_loc7`='No es necesario que acabe así, ¿lo sabes?' WHERE `ID`=27026;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='난 늘 현명한 판단을 내렸지만, 언니는 그러지 않았어. 더는 우릴 파멸로 몰고 가게 두지 않겠어!', `FemaleText_loc4`='面对困境，我做出了明智的判断，而你却束手无策。克雷娜，我不愿意眼睁睁地看着你将我们带上绝路！', `FemaleText_loc5`='你既然無法做出正確的判斷，那就我來吧。我可不想看到你帶領我們步入毀滅，克蓮娜!', `FemaleText_loc7`='Yo hice gala de buen juicio cuando tú no mostraste ninguno. ¡No quiero ver cómo nos llevas hacia la ruina, Krenna!' WHERE `ID`=27027;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그건 두고 볼 일이야.', `FemaleText_loc4`='我们走着瞧吧！', `FemaleText_loc5`='那就試試看。', `FemaleText_loc7`='Ya veremos.' WHERE `ID`=27028;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='괜찮은 녀석들이지, 동생아. 네 애완견은 어디 갔지? $n 말이다!', `FemaleText_loc4`='明智的判断？你的宠物呢？$n在哪儿？', `FemaleText_loc5`='還不錯，姊妹。你的寵物呢?$n在哪裡?', `FemaleText_loc7`='Esa ha sido buena, hermana. ¿Qué hay de tu mascota? ¿Dónde está $n?' WHERE `ID`=27029;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='넌 날 거역했다. 내 명령을 따르지 않았어. 이제 그 대가를 치를 때야.', `FemaleText_loc4`='你背着我耍花招，无视我的命令。你会付出代价的。', `FemaleText_loc5`='你偷襲我，你無視我的命令，你將付出代價。', `FemaleText_loc7`='Actuaste a mis espaldas. Ignoraste mis órdenes. Pagarás por ello.' WHERE `ID`=27030;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이야기는 그만두지. 일이 끝나고 나면 검은늑대조차도 네 시체 근처에는 다가가지 않을 게다.', `FemaleText_loc4`='够了。这场战斗结束后，我与你便再无瓜葛。那时，即便是座狼，也不愿意靠近你的尸体。', `FemaleText_loc5`='聊夠了吧。到時候，我解決你，就連座狼也不會想要走近你的屍體。', `FemaleText_loc7`='Basta de charla. Cuando haya acabado contigo, ni siquiera los huargos querrán acercarse a tu cadáver.' WHERE `ID`=27031;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신사 숙녀 여러분! 그... 뭐랄까, 이번 시합은 놓치지 않는 게 좋을 겁니다!', `MaleText_loc4`='女士们，先生们！我说……你们一定不想错过这场战斗吧！', `MaleText_loc5`='先生小姐們!那麼...你們絕對不想錯過這場打鬥的!', `MaleText_loc7`='¡Señoras y señores! Bueno... ¡dejémoslo en que no quieren perderse esto!' WHERE `ID`=27032;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='언니... 왜 그랬어? 왜 여기까지 와야만 했던 거지?', `FemaleText_loc4`='为什么……为什么？我们非要闹到这步田地吗？', `FemaleText_loc5`='為什麼...為什麼，姊妹?為什麼非得走到這一步呢?', `FemaleText_loc7`='¿Por qué... por qué hermana? ¿Por qué teníamos que llegar a esto?' WHERE `ID`=27033;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='루비 정수를 에메랄드 정수로 교환하고 싶습니다.', `MaleText_loc4`='我想用红玉精华换取翡翠精华。', `MaleText_loc5`='我想要將我的紅寶石精華和翡翠精華交換。', `MaleText_loc7`='Quiero cambiar mi esencia de rubí por esencia de esmeralda.', `FemaleText_loc1`='루비 정수를 에메랄드 정수로 교환하고 싶어요.', `FemaleText_loc4`='我想用红玉精华换取翡翠精华。', `FemaleText_loc5`='我想要將我的紅寶石精華和翡翠精華交換。', `FemaleText_loc7`='Quiero cambiar mi esencia de rubí por esencia de esmeralda.' WHERE `ID`=27034;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호박 정수를 에메랄드 정수로 교환하고 싶습니다.', `MaleText_loc4`='我想用琥珀精华换取翡翠精华。', `MaleText_loc5`='我想要將我的琥珀精華和翡翠精華交換。', `MaleText_loc7`='Quiero cambiar mi esencia de ámbar por esencia de esmeralda.', `FemaleText_loc1`='호박 정수를 에메랄드 정수로 교환하고 싶어요.', `FemaleText_loc4`='我想用琥珀精华换取翡翠精华。', `FemaleText_loc5`='我想要將我的琥珀精華和翡翠精華交換。', `FemaleText_loc7`='Quiero cambiar mi esencia de ámbar por esencia de esmeralda.' WHERE `ID`=27035;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로켓 추진 탄두라고요? 그건 너무 심한 거 아닙니까?', `MaleText_loc4`='火箭推进弹头？是不是太夸张啦？', `MaleText_loc5`='火箭推進彈頭?這不會有點太具侵略性了嗎?', `MaleText_loc7`='¿Cabezas explosivas con propulsión a cohete? ¿No es un poco excesivo?', `FemaleText_loc1`='로켓 추진 탄두라고요? 그건 너무 심한 거 아닙니까?', `FemaleText_loc4`='火箭推进弹头？是不是太夸张啦？', `FemaleText_loc5`='火箭推進彈頭?這不會有點太具侵略性了嗎?', `FemaleText_loc7`='¿Cabezas explosivas con propulsión a cohete? ¿No es un poco excesivo?' WHERE `ID`=27036;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 들으라고. 뭔가 막히는 게 있을 때는 깔끔하게 날려버리는 데 제일이야. 화끈할수록 좋지!$b$b하지만 대답은 이 정도로 해 두겠어.$b$b내 탄두는 기밀 사항이니까. 그리고 동력원으로 쓰려고 내가 만든 원료 115는 더 중요한 기밀이지!$b$b뭐, 솔직히 말해 자네는 우리가 만났다는 사실을 잊고 그냥 살던 대로 사는 게 제일 좋을 거라고.', `MaleText_loc4`='听着。想知道不明物的真相，最好是制造一场爆炸——当然是越大越好啦！$b$b不过眼下还有很多问题没有解决，$r。$b$b这些弹头都是由机密材料制成的，而作为推进能量源的115号元素就更加机密啦！$b$b事实上，你最好假装从来没有见过我，继续过你的安稳日子去。', `MaleText_loc5`='聽好嘿，你如果要尋找答案的話，沒有什麼比爆破更有效了 - 爆炸越大越好!$b$b但是那大概就是我們最大的問題了，$r。$b$b我的彈頭是機密材料，而我做出來作為彈頭燃料的「元素115」更是機密中的機密!$b$b事實上，你最好回去過你的日常生活，假裝我們從來沒見過比較好。', `MaleText_loc7`='Escucha. Cuando buscas respuestas, no hay nada mejor que una buena explosión; cuánto más grande, mejor.$B$BPero ya basta de preguntas por ahora, $r.$B$BMis cabezas explosivas son material clasificado y el elemento 115 que creé para darles energía es aún más secreto.$B$BDe hecho, será mejor que regreses a tu rutina habitual y hagas como que no nos hemos conocido.' WHERE `ID`=27037;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에메랄드 정수를 호박 정수로 교환하고 싶습니다.', `MaleText_loc4`='我想用翡翠精华换取琥珀精华。', `MaleText_loc5`='我想要將我的翡翠精華和琥珀精華交換。', `MaleText_loc7`='Quiero cambiar mi esencia de esmeralda por esencia de ámbar.', `FemaleText_loc1`='에메랄드 정수를 호박 정수로 교환하고 싶어요.', `FemaleText_loc4`='我想用翡翠精华换取琥珀精华。', `FemaleText_loc5`='我想要將我的翡翠精華和琥珀精華交換。', `FemaleText_loc7`='Quiero cambiar mi esencia de esmeralda por esencia de ámbar.' WHERE `ID`=27038;
