UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에메랄드 정수를 루비 정수로 교환하고 싶습니다.', `MaleText_loc4`='我想用翡翠精华换取红玉精华。', `MaleText_loc5`='我想要將我的翡翠精華和紅寶石精華交換。', `MaleText_loc7`='Quiero cambiar mi esencia de esmeralda por esencia de rubí.', `FemaleText_loc1`='에메랄드 정수를 루비 정수로 교환하고 싶어요.', `FemaleText_loc4`='我想用翡翠精华换取红玉精华。', `FemaleText_loc5`='我想要將我的翡翠精華和紅寶石精華交換。', `FemaleText_loc7`='Quiero cambiar mi esencia de esmeralda por esencia de rubí.' WHERE `ID`=27041;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요새 중간층의 아프라사스트라즈 군주께 가고 싶습니다.', `MaleText_loc4`='我想去龙眠神殿中层，与阿弗拉沙斯塔兹指挥官谈一谈。', `MaleText_loc5`='我想要到神殿中央，艾弗薩斯塔茲領主之處。', `MaleText_loc7`='Me gustaría llegar hasta Lord Afrasastrasz, en el centro del templo.', `FemaleText_loc1`='요새 중간층의 아프라사스트라즈 군주께 가고 싶어요.', `FemaleText_loc4`='我想去龙眠神殿中层，与阿弗拉沙斯塔兹指挥官谈一谈。', `FemaleText_loc5`='我想要到神殿中央，艾弗薩斯塔茲領主之處。', `FemaleText_loc7`='Me gustaría llegar hasta Lord Afrasastrasz, en el centro del templo.' WHERE `ID`=27042;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='군주님, 요새 꼭대기로 가고 싶습니다.', `MaleText_loc4`='指挥官，我想去龙眠神殿顶层。', `MaleText_loc5`='大人，我需要前往神殿的頂端。', `MaleText_loc7`='Mi señor, necesito llegar a lo alto del templo.', `FemaleText_loc1`='군주님, 요새 꼭대기로 가고 싶습니다.', `FemaleText_loc4`='指挥官，我想去龙眠神殿顶层。', `FemaleText_loc5`='大人，我需要前往神殿的頂端。', `FemaleText_loc7`='Mi señor, necesito llegar a lo alto del templo.' WHERE `ID`=27043;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='반가워요, 여행자여. 꼭 알맞은 때에 와줬군요.', `FemaleText_loc4`='欢迎你，冒险家。你来的正是时候。', `FemaleText_loc5`='冒險者，歡迎你。你的光臨真是太湊巧了。', `FemaleText_loc7`='Te doy la bienvenida, $gaventurero:aventurera;. Llegas justo a tiempo.' WHERE `ID`=27044;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 그칠 새 없는 울부짖음을 멈추려면 텔잔을 죽여야만 합니다!', `MaleText_loc4`='塞尔赞必须死，只有这样才能使怨灵停止那永无止境的哭泣！', `MaleText_loc5`='要讓這無止境的哭號停止，賽爾贊非死不可!', `MaleText_loc7`='Thel''zan debe morir, ¡aunque solo sea para detener el incesante parloteo!' WHERE `ID`=27045;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아프라사스트라즈 군주님, 지상으로 내려가게 해 주시겠습니까?', `MaleText_loc4`='阿弗拉沙斯塔兹，能让我返回神殿底层吗？', `MaleText_loc5`='艾弗薩斯塔茲領主，能順道帶我回底層嗎?', `MaleText_loc7`='¿Puedo viajar de vuelta al nivel bajo, Lord Afrasastrasz?', `FemaleText_loc1`='아프라사스트라즈 군주님, 지상으로 내려갈 수 있게 해 주시겠어요?', `FemaleText_loc4`='阿弗拉沙斯塔兹，能让我返回神殿底层吗？', `FemaleText_loc5`='艾弗薩斯塔茲領主，能順道帶我回底層嗎?', `FemaleText_loc7`='¿Puedo viajar de vuelta al nivel bajo, Lord Afrasastrasz?' WHERE `ID`=27046;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='윈터가드 시민 및 공무원의 공식 게시물', `MaleText_loc4`='暮冬要塞的市民与官员联名发布的官方公告。', `MaleText_loc5`='溫特加德市民與官員的正式公告。', `MaleText_loc7`='Publicaciones oficiales de la ciudadanía y oficiales de Hibergarde.' WHERE `ID`=27047;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요새 중앙의 아프라사스트라즈 군주님께 갈 비룡을 빌려주시겠습니까?', `MaleText_loc4`='能让我搭乘幼龙前往龙眠神殿中层，与阿弗拉沙斯塔兹会面吗？', `MaleText_loc5`='你能借我一頭飛龍，帶我到神殿中央，艾弗薩斯塔茲領主的地方嗎?', `MaleText_loc7`='¿Me puedes dejar un draco para que me lleve junto a Lord Afrasastrasz en el centro del templo?', `FemaleText_loc1`='요새 중앙의 아프라사스트라즈 군주님께 갈 비룡을 빌려주시겠어요?', `FemaleText_loc4`='能让我搭乘幼龙前往龙眠神殿中层，与阿弗拉沙斯塔兹会面吗？', `FemaleText_loc5`='你能借我一頭飛龍，帶我到神殿中央，艾弗薩斯塔茲領主的地方嗎?', `FemaleText_loc7`='¿Me puedes dejar un draco para que me lleve junto a Lord Afrasastrasz en el centro del templo?' WHERE `ID`=27048;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='검은용과 같이 있어 불편한가요?$B$B좋아요. 그래야 정상이지요. 이 용들도 불편해하기는 마찬가지예요. 그러면서도 과거의 미덕에 매달리느라 여기서는 감히 날 공격하지 못하고요.$B$B우둔한 것들.', `FemaleText_loc4`='面对黑龙令你感到不安吗？$B$B很好。的确如此。在黑龙面前，其他龙族也会心生胆怯。这一点倒是继承了他们的祖先的美德——瞧，他们根本不敢攻击我。$B$B一帮蠢货。', `FemaleText_loc5`='黑龍的外表令你緊張嗎?$B$B很好。就是要這樣。這些龍類也感到很緊張。雖然牠們堅守他們先祖的美德 - 不敢在這裡攻擊我。$B$B一群傻蛋。', `FemaleText_loc7`='¿Te inquieta estar ante la presencia de un dragón Negro?$B$BBien. Debería. También inquieta a estos dragones. Pero se aferran a sus ancestrales virtudes, no osarían atacarme aquí.$B$BInsensatos.' WHERE `ID`=27049;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음으로 낙스라마스 역병의 전당에 대해 이야기하겠다. 스컬지는 그곳에서 로데론에 뿌렸던 것보다 더 강한 역병을 만드는 중이다.', `MaleText_loc4`='接下来介绍纳克萨玛斯恐怖的天灾区。天灾军团在这里进行药理研究，企图改良他们在洛丹伦传播的药剂。', `MaleText_loc5`='下一次，我會討論納克薩瑪斯令人害怕的瘟疫區，天譴軍團就是在這裡試圖改善他們散佈於羅德隆的致命荒疫。', `MaleText_loc7`='A continuación, os hablaré de la temida Ala de la Peste de Naxxramas, donde la Plaga intenta mejorar el mortal añublo que extendieron por Lordaeron.' WHERE `ID`=27050;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번에는 낙스라마스에 있는 저주받은 거미의 전당에 대해 이야기하겠다. 스컬지는 그곳에서 더욱 독성이 강하고 위험한 놈들을 만들어내고 있다.', `MaleText_loc4`='接下来介绍纳克萨玛斯被诅咒的蜘蛛区。天灾军团在这里培育蛛怪的变种，以便繁殖出毒性更厉害的危险生物。', `MaleText_loc5`='下一次，我會討論納克薩瑪斯可憎的蜘蛛區。那裡就是天譴軍團孕育更為惡毒，危險的同類之地。', `MaleText_loc7`='A continuación, hablaré sobre la abominable Ala de la Araña de Naxxramas. Ahí es donde la Plaga engendra versiones más peligrosas y venenosas de su gente.' WHERE `ID`=27051;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음 차례는 낙스라마스 골렘의 전당이다. 그곳에서 스컬지는 놈들의 괴물 군단 중에서도 가장 강력하고 끔찍한 돌연변이를 개발한다.', `MaleText_loc4`='接下来介绍纳克萨玛斯毒气缭绕的憎恶区。天灾军团在这里制造大批强壮而丑陋的怪物，以此扩充他们的军事武装力量。', `MaleText_loc5`='下一次，我會討論納克薩瑪斯受荒疫感染的憎惡區。天譴軍團在那裡研發最強大，最駭人聽聞的畸變軍隊。', `MaleText_loc7`='A continuación, hablaré sobre la infectada Ala de la Abominación de Naxxramas. Ahí, la Plaga desarrolla las aberraciones más fuertes y atroces de sus ejércitos.' WHERE `ID`=27052;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음으로 낙스라마스 죽음의 기사단 전당에 대해 설명해 주지. 이 타락한 전당에서는 훌륭한 우리 전사들이 타락하고 변질되어 스컬지의 전사로 다시 태어나, 밤낮으로 그들이 기술을 연마하는 소리가 울려 퍼진다고 한다.', `MaleText_loc4`='接下来介绍纳克萨玛斯的死亡骑士区。在腐化力量的侵蚀下，我们最杰出的战士沦为了天灾军团的走狗。如今，战争的号角日夜在死亡骑士区的大厅中回荡。', `MaleText_loc5`='下一次，我會討論納克薩瑪斯的死亡騎士區。在這個墮落的大廳中，戰鬥的回響持續日日夜夜，同時我們最好的戰士正墮落並扭曲成天譴軍團最強的戰士。', `MaleText_loc7`='A continuación, hablaré sobre el Ala del caballero de la Muerte de Naxxramas. En sus corruptas salas, se escucha el eco de la batalla día y noche, mientras nuestros mejores guerreros se corrompen y distorsionan para convertirse en los mejores guerreros de la Plaga.' WHERE `ID`=27053;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음은 낙스라마스에서 정점에 선 강력한 존재들에 대해 이야기하겠다. 이 두 괴물은 노스렌드에 있는 모든 존재에게 엄청난 위협이지.', `MaleText_loc4`='接下来介绍盘踞在纳克萨玛斯顶端的生物。他们拥有无可思议的强大力量，当之无愧地被冠以诺森德两大威胁的称号。', `MaleText_loc5`='下一次，我會談到納克薩瑪斯頂端最強大的生物。說真的，這是北裂境中兩個最大威脅其中之一。', `MaleText_loc7`='A continuación, hablaré sobre las entidades más poderosas del pináculo de Naxxramas. Sin duda estas son dos de las mayores amenazas para todo Rasganorte.' WHERE `ID`=27054;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 봐라, 역병술사 노스이다. 살아 있는 자의 영혼을 뽑아내어 언데드라는 감옥에 가두는 방법을 창조한 장본인이지. 노스는 지금도 이 과정을 개량하고 있다고 한다.', `MaleText_loc4`='这是药剂师诺斯。天灾军团将人们囚禁在冰冷的死灵牢笼的计划，便是他提出的创意。至今，诺斯仍然负责监督并完善这一流程。', `MaleText_loc5`='瞧啊，『瘟疫使者』諾斯。他負責創造出蒸餾生者靈魂，並將他們置入不死冰冷牢籠的整個過程，即使到現在，還有人觀察到諾斯繼續地改進這個流程。', `MaleText_loc7`='Observad a Noth el Pesteador. Responsable de la creación del proceso que destila las almas de los vivos y las mete dentro de la fría jaula de la no-muerte. Incluso en este momento, Noth continúa refinando este proceso.' WHERE `ID`=27055;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 봐라. 부정의 헤이건이다. 아름다운 아제로스를 역병지대로 바꾸어 버린 역병 가마솥을 배후에서 조종한 인물이지.', `MaleText_loc4`='这是肮脏的希尔盖。他就是指挥天灾军团利用天灾之锅将艾泽拉斯宁静的旷野变成诅咒之地的罪魁祸首。', `MaleText_loc5`='看吶，『不潔者』海根。他是瘟疫大鍋的幕後策劃者，負責將艾澤拉斯的曠野轉變為瘟疫之地。', `MaleText_loc7`='Observad a Heigan el Impuro. La genial mente que se esconde detrás de las calderas de peste que convirtieron la vida salvaje de Azeroth en las Tierras de la Peste.' WHERE `ID`=27056;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헤이건은 낙스라마스의 벽과 바닥에 수많은 함정을 설치해 놓았고, 자신이 원하는 대로 얼마든지 작동시킬 수 있다고 한다.', `MaleText_loc4`='据说希尔盖对纳克萨玛斯的墙壁和地板进行了改造，设置了大量可以随意触发的可控陷阱。', `MaleText_loc5`='傳說海根在納克薩瑪斯的城牆和階梯上裝配了為數不少的陷阱，而他可以隨意觸發這些陷阱。', `MaleText_loc7`='Se dice que Heigan ha llenado los mismísimos muros y suelos de Naxxramas con una amplia gama de trampas que puede activar a su voluntad.' WHERE `ID`=27057;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로데브다. 역병지대의 살아 있는 역병과 아제로스의 수렁 괴물을 결합시킨 끔찍한 괴물이지. 로데브에게는 치유 그 자체를 좌지우지하는 힘이 있다.', `MaleText_loc4`='洛欧塞布。据说这个地方的诅咒与艾泽拉斯的沼泽兽缝合而成的怪物拥有控制治疗能量的本领。', `MaleText_loc5`='憎恨者。傳說憎恨者擁有治療自己的力量，其駭人的成果為將瘟疫之地現存的瘟疫與艾澤拉斯泥沼獸進行溶合。', `MaleText_loc7`='Loatheb. El atroz resultado de fusionar la peste viviente de las Tierras de la Peste con las bestias de marisma de Azeroth. Se dice que Loatheb controla el poder de sanarse a sí mismo.' WHERE `ID`=27058;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='복습할 수 있도록 영상은 계속 켜 두겠다. 상대의 능력을 잘 파악해라. 그 능력이 약점일 수도 있으니 말이다.', `MaleText_loc4`='这尊影像就留给你们观察吧。仔细研究对手的能力，他的优势很可能也是致命的弱点。', `MaleText_loc5`='我會將這個影像留給你仔細觀察。研究你敵人的力量，一個生物的強處同時有可能也就是它的弱點。', `MaleText_loc7`='Dejaré su imagen a la vista para que la observen concienzudamente. Estudien los puntos fuertes de sus oponentes, pues el punto fuerte de una criatura también puede ser su debilidad.' WHERE `ID`=27059;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주목. 이자가 훈련교관 라주비어스이다. 켈투자드는 모든 죽음의 기사를 교육하는 임무를 직접 이자에게 맡겼지. 그의 기술은 워낙 뛰어나서 직접 가르친 수제자 정도만이 겨우 그에게 맞서 싸울 수 있다고 하더군.', `MaleText_loc4`='注意。这是教官拉苏维奥斯，由克尔苏加德亲自指派的死亡骑士训练师。这位威严的教官拥有独特的教学法则，据说只有他的学徒才有可能承受得住他的威力。', `MaleText_loc5`='注意。這就是講師拉祖維斯，科爾蘇加德指派給所有死亡騎士的訓練師。傳說他擁有的技巧十分強大，只有他的學徒才有辦法抵擋他的力量。', `MaleText_loc7`='Prestad atención. Este es el Instructor Razuvious, a quien Kel''Thuzad nombró entrenador de todos los caballeros de la Muerte. Se dice que su propia técnica es tan potente que solo uno de sus discípulos podría resistir a su fuerza.' WHERE `ID`=27060;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼 착취자 고딕이다. 강령술과 주술의 전문가인 고딕은 눈 깜짝할 사이에 언데드 군단을 불러낼 수 있다고 한다. 그가 인도하면 가장 약한 죽음의 기사조차도 시체를 일으킬 수 있지.', `MaleText_loc4`='收割者戈提克。作为巫咒与魔法的大师，据说戈提克能瞬间召唤出亡灵军团为他作战。在他的指导下，即便是能力最弱的死亡骑士也能令亡者复生。', `MaleText_loc5`='『收割者』高希。一位死靈法術和魔法的大師，傳說他可以在瞬間召出不死軍團。只要跟隨他的指導，就算是最弱的死亡騎士都能召喚出亡者。', `MaleText_loc7`='Gothik el Cosechador. Un maestro de la nigromancia y las invocaciones. Se dice que Gothik es capaz de hacer aparecer legiones de no-muertos en solo un instante. Con su orientación, incluso el más débil de los caballeros de la Muerte puede levantar a los muertos.' WHERE `ID`=27061;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='낙스라마스 죽음의 기사 중에서도 4인 기사단이 가장 강력하다. 그들은 켈투자드의 최정예 경비병이기도 하지. 첫 번째인 영주 코스아즈는 불의 힘을 다룬다.', `MaleText_loc4`='天启四骑士是纳克萨玛斯中最强大的死亡骑士，是克尔苏加德麾下最顶尖的防御将领。首先介绍库尔塔兹领主，他能操纵火焰的力量。', `MaleText_loc5`='在納克薩瑪斯中最強大的死亡騎士就是四騎士。他們代表科爾蘇加德守衛中的菁英。第一位，寇斯艾茲族長，掌控著火焰的力量。', `MaleText_loc7`='Los caballeros de la Muerte más poderosos de Naxxramas son los Cuatro Jinetes. Ellos representan el súmmum de la guardia de Kel''Thuzad. El primero, el señor feudal Korth''azz, posee el poder de la llama.' WHERE `ID`=27062;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음은 여군주 블라미우스이다. 암흑의 힘으로 살아있는 자의 영혼을 뽑아 탐욕스럽게 흡수한다고 하지.', `MaleText_loc4`='下一位是女公爵布劳缪克丝。她能召唤暗影的力量，吞噬活人的灵魂。', `MaleText_loc5`='下一位，布洛莫斯女士，號令著暗影之力，吸引生者之靈投入貪婪的懷抱。', `MaleText_loc7`='La siguiente, Lady Blaumeux, puede invocar el poder de las Sombras, arrancando las almas de los vivos con su voraz abrazo.' WHERE `ID`=27063;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생전에 성기사였던 젤리에크 경은 그 엄청난 신앙심 덕에 언데드가 되어서도 빛의 힘을 다루어 적을 물리친다고 한다.', `MaleText_loc4`='瑟里耶克爵士。生前他是一名信仰坚定的圣骑士，虽然他已是死灵之躯，却依然能召唤圣光的力量惩击敌人。', `MaleText_loc5`='札里克爵士，生前是位信念堅定聖騎士，就算成為了不死之軀，聖光之力依舊留意他的呼喚，在戰鬥中痛擊他的敵人。', `MaleText_loc7`='Sir Zeliek, un paladín en vida con una fe tan fuerte, que incluso en la no-muerte el poder de la Luz aún responde a su llamada, golpeando a sus enemigos en la batalla.' WHERE `ID`=27064;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마지막 죽음의 기사인 대영주 모그레인은 죽음의 기사 중에서도 가장 뛰어난 전사였다. 하지만 아제로스에서 일어난 사건 이후로 그는 종적을 감췄지. 켈투자드가 그 자리에 누구를 임명했는지는 아직 밝혀지지 않았다.', `MaleText_loc4`='最后一位死亡骑士是大领主莫格莱尼。他曾经是一名杰出的战士，最优秀的死亡骑士在他面前也会黯然失色。但是，当他在艾泽拉斯经历了一系列的变故后，便消失得无影无踪了。目前还不知道克尔苏加德指派了谁来取代他的位置。', `MaleText_loc5`='最後一位死亡騎士，大領主莫格萊尼，是死亡騎士中有始以來最優秀的戰士。然而，經過艾澤拉斯事件後，他就此失去了蹤跡。還不能證實科爾蘇加德後來委派誰來接替他的位子。', `MaleText_loc7`='El último caballero de la Muerte, Lord Mograine, era el mejor guerrero que los caballeros de la Muerte jamás habían visto. Después de los hechos que acontecieron en Azeroth, desapareció sin dejar rastro. Aún está por ver a quién ha puesto Kel''Thuzad en su lugar.' WHERE `ID`=27065;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아졸네룹의 고위 거미 군주인 아눕레칸은 원래 아눕아락의 휘하에 있었으나, 리치 왕에게 패한 이후로 스컬지의 휘하에 들어갔다. 옛날에는 아눕아락 휘하의 지휘관 중에서도 가장 충성스러웠다고 하더군.', `MaleText_loc4`='阿努布雷坎，艾卓-尼鲁布最杰出的蛛怪领主之一。多年前，他与蛛怪之王阿努巴拉克都惨败在巫妖王手中，此后便被天灾军团控制了。据说他曾是阿努巴拉克麾下最忠诚的领主。', `MaleText_loc5`='阿努比瑞克漢，阿茲歐-奈幽中最優秀的蜘蛛之王，當他和前指揮官阿努巴拉克在許多年前被巫妖王打敗後，他們就受控於天譴軍團之下。傳說他是阿努巴拉克最忠心的指揮官。', `MaleText_loc7`='Anub''Rekhan, uno de los mejores Señores Araña de Azjol''Nerub, cayó bajo el control de la Plaga cuando él y su antiguo comandante, Anub''arak, fueron finalmente derrotados por el Rey Exánime hace muchos años. Se dice que es el más leal de los comandantes de Anub''arak.' WHERE `ID`=27066;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하시오, $r 양반!$b$b벌목기를 타고 싶다면 언덕 위로 가야 할 거요.$b$b이놈은 작동을 안 하니까.', `MaleText_loc4`='听着，$r。$B$B想找一台能驾驶的伐木机，你恐怕得进入北面的山岭。$b$b这台已经坏掉了。', `MaleText_loc5`='聽著，$r。$b$b如果你想要駕駛伐木機，你得到北邊的山丘上。$b$b這一台壞掉了。', `MaleText_loc7`='Escucha, $r.$B$BSi buscas una trituradora que montar, tendrás que dirigirte hacia las colinas al norte.$B$BEsta está fuera de servicio.' WHERE `ID`=27067;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 왜 벌목기를 타야 합니까?', `MaleText_loc4`='我为什么要驾驶伐木机？', `MaleText_loc5`='為什麼我會想要駕駛伐木機?', `MaleText_loc7`='¿Por qué querría montar en una trituradora?', `FemaleText_loc1`='내가 왜 벌목기를 타야 하나요?', `FemaleText_loc4`='我为什么要驾驶伐木机？', `FemaleText_loc5`='為什麼我會想要駕駛伐木機?', `FemaleText_loc7`='¿Por qué querría montar en una trituradora?' WHERE `ID`=27068;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='처음엔 벌목기를 수리해서 벌목 작업을 하는 데 썼지. 하지만 얼라이언스가 도착해서 전투가 벌어진 이래로는 벌목기를 전쟁 무기로 사용한다오.$b$b날 믿으시오, $c. 열쇠가 있는데도 벌목기를 안 쓰는 건 바보 같은 짓이라오!', `MaleText_loc4`='一开始我们只是利用这些机器砍伐森林，但是自从联盟踏上这片土地，战争就愈发频繁起来。我们这才发现，原来翻新过的伐木机也能充当战争机器。$b$b$c，相信我。如果你有伐木机钥匙的话，干嘛不试着驾驶一下呢。', `MaleText_loc5`='起先我們修復它們來收採這裡的森林，不過自從聯盟抵達和戰鬥爆發後，我們就把它們用來做為戰爭機器。$b$b相信我，$c。如果你有鑰匙，你一定是瘋了才不去使用它。', `MaleText_loc7`='Al principio las reparamos para cosechar estos bosques, pero desde que llegó la Alianza y comenzó la lucha las usamos como máquinas de guerra.$B$BCréeme, $c. Estarías $gloco:loca; si tuvieras una llave y no la usaras.' WHERE `ID`=27069;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='귀부인 팰리나는 생전에 식물학자였고, 죽어서는 거미를 키우고 돌본다. 거미 무리를 감독하면서 리치 왕을 위해 강력한 독을 개발하고 있지.', `MaleText_loc4`='黑女巫法琳娜。生前她是一位植物学家，死后她为巫妖王效力，负责管理蜘蛛区的蛛怪培育与毒药研制工作。', `MaleText_loc5`='大寡婦費琳娜，生前是位植物學家，死後成為蛛類生物的飼養者和照顧者。她監督著蜘蛛區，為巫妖王開發最強力的毒藥。', `MaleText_loc7`='La Gran Viuda Faerlina, una botánica en vida, criadora y cuidadora de arácnidos en la muerte. Supervisa el Ala de la Araña, creando los venenos más potentes para el Rey Exánime.' WHERE `ID`=27070;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고친 벌목기 열쇠는 어디서 구할 수 있습니까?', `MaleText_loc4`='我要去哪儿找翻新过的伐木机钥匙？', `MaleText_loc5`='我要去哪取得翻新伐木機之鑰?', `MaleText_loc7`='¿Dónde puedo conseguir una llave de trituradora reformada?', `FemaleText_loc1`='고친 벌목기 열쇠는 어디서 구할 수 있나요?', `FemaleText_loc4`='我要去哪儿找翻新过的伐木机钥匙？', `FemaleText_loc5`='我要去哪取得翻新伐木機之鑰?', `FemaleText_loc7`='¿Dónde puedo conseguir una llave de trituradora reformada?' WHERE `ID`=27071;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그레크가 가지고 있소.$b$b그를 도와준다면 하나쯤 줄지도 모르지. 나중에 푸른 하늘 벌목장에 갈 일이 있으면 꼭 물어보시오.', `MaleText_loc4`='格利克有很多钥匙。$b$b如果你肯帮他的忙，他或许会考虑送你一把。下次你造访蓝天伐木场时，记得找他谈谈。', `MaleText_loc5`='葛列克手中有鑰匙。$b$b如果你幫忙他的話，說不定他會給你一把鑰匙。下次你往北抵達藍天伐木地時，記得要找他談談。', `MaleText_loc7`='Las tiene Grekk.$B$BQuizá te entregue una si le ayudas. Asegúrate de hablar con él la próxima vez que estés en el norte, en el aserradero Cielo Azul.' WHERE `ID`=27072;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맥스나는 오래전에 노스렌드의 깊은 산 속에서 태어났다. 그녀는 공포의 요새 낙스라마스로 잡혀가 거기서 새끼를 낳아 기르고 있다. 무모하게 낙스라마스에 침입한 자들의 시체를 먹이면서 말이지.', `MaleText_loc4`='迈克斯纳。数百年前，这只出生在诺森德冰峰深处的蜘蛛就被天灾军团虏进了纳克萨玛斯。她在这座恐怖之城中繁衍后代，那些胆敢进入纳克萨玛斯的冒险者都沦为了蜘蛛的美餐。', `MaleText_loc5`='梅克絲娜，許多年前在北裂境的群山深處中出生，她被關入驚懼堡壘納克薩瑪斯之中，在這裡她產下了她的孩子，將所有膽敢冒險深入納克薩瑪斯的人們屍體拿來餵養她的孩子們。', `MaleText_loc7`='Maexxna, nacida en las profundidades de las montañas de Rasganorte hace mucho años, fue capturada en la ciudadela del terror, Naxxramas, donde da a luz a sus crías, alimentándolas con los cadáveres de todos lo que se adentran demasiado en Naxxramas.' WHERE `ID`=27073;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='봐라, 패치워크이다. 그의 존재가 처음 빛의 결사단에게 알려졌을 때만 해도 그토록 엄청난 힘과 속도를 지닌 누더기골렘이 정말 있다고 믿는 사람은 아무도 없었다. 그래서 패치워크가 쓰러졌다는 소식 또한 믿는 사람이 드물었지...', `MaleText_loc4`='这是帕奇维克。圣光兄弟会第一次听闻他的传言时，没有谁相信憎恶也能拥有如此迅捷的速度和可怕的力量。当帕奇维克初战告捷后，大家便不再认为那是谣言了……', `MaleText_loc5`='瞧，縫補者。當兄弟會第一次聽到他的存在時，沒有人相信一個憎惡體會有如此巨大的速度和力量。在他第一次死去時，少數人還是抱持著這個想法...', `MaleText_loc7`='Contemplad a Remendejo. Cuando los rumores de su existencia llegaron a oídos de la Hermandad, no creyeron las historias que hablaban de una abominación con semejante fuerza y velocidad. Pocos las creían cuando atacó por primera vez...' WHERE `ID`=27074;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그라불루스는 살덩이 거인 군대의 첫 번째 병사이다. 놈은 낙스라마스의 역병 걸린 진흙괴물을 체내에 넣고 다니며 적의 몸에 그 살아 있는 액체를 주입하지. 이 공격을 당한 이는 두려움에 아군이 있는 곳으로 도망가게 마련이고, 그러면 모두 함께 몰살당하고 만다.', `MaleText_loc4`='格罗布鲁斯，天灾军团制造的血肉巨人。格罗布鲁斯体内蠕动着纳克萨玛斯的软泥怪，能侵蚀给任何敢于靠近它的敌人。被注入软泥怪的受体通常会逃回盟友身边，顷刻之间就能击溃所有人。', `MaleText_loc5`='葛羅巴斯，軍隊中的第一隻血肉巨人。體內夾帶著納克薩瑪斯的瘟疫泥漿怪，將活生生的軟泥注射入敵人的體內。這個注入邪惡的生物通常會跑向他的同類處，將他們納為一體。', `MaleText_loc7`='Grobbulus, el primero de lo que sería un ejército de gigantes de carne. Llevaba el limo de la peste de Naxxramas dentro de su cuerpo, inyectando el líquido viviente en los cuerpos de sus enemigos. La persona que recibía esta fatal inyección a menudo corría hacia sus aliados, llevándoselos por delante.' WHERE `ID`=27075;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일입니까?', `MaleText_loc4`='嗯？', `MaleText_loc5`='嗯?', `MaleText_loc7`='¿Sí?' WHERE `ID`=27076;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='낙스라마스의 언데드 야수 글루스는 식욕이 워낙 왕성해 산 자만으로는 놈의 허기를 달랠 수가 없다고 한다. 그래서 퓨진은 매일같이 놈에게 좀비 한 부대를 먹이로 준다더군. 전투에 내보내도 별 소용이 없는 약한 언데드를 재활용하는 셈으로 말이지.', `MaleText_loc4`='格拉斯，纳克萨玛斯肮脏的天灾犬。据说这只野兽极其贪婪，每天费尔根都会给它送去一批缺乏作战力的亡灵。格拉斯堪称是天灾军团废物利用系统的终端。', `MaleText_loc5`='古魯斯，納克薩瑪斯邪惡的瘟疫犬，聽說有著極其貪婪的胃口，就連生者都無法滿足他的飢餓。伏晨聽說每天都得餵牠一批殭屍大軍，回收這些因為太虛弱而無法使用在戰鬥中的殘餘不死族。', `MaleText_loc7`='Cuentan que Gluth, el perro apestado hediondo de Naxxramas, tenía un apetito tan voraz que incluso los vivos no bastaban para satisfacer su apetito. Dicen que Feugen le daba un ejército de zombis de comer a diario, reciclando así los restos de los no-muertos que eran demasiado débiles para el combate.' WHERE `ID`=27077;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타디우스는 여자와 아이의 육신으로 만들어졌다. 그 가엾은 영혼들은 하나로 융합되어, 더러운 육체의 감옥에 영원토록 갇혀 있다고 한다.', `MaleText_loc4`='塔迪乌斯，用女人与孩子的血肉缝合而成的巨人。据说他们的灵魂也融入塔迪乌斯体内，永远被禁锢在这肮脏的囚牢中。', `MaleText_loc5`='泰迪斯，以女人和小孩的血肉製造而成，聽說他們的靈魂混合在一塊 - 永遠被束縛在那些邪惡的血肉監牢內。', `MaleText_loc7`='Thaddius, construido con la carne de mujeres y niños, se dice que sus almas se han fusionado, unidas eternamente en el interior de esa nauseabunda prisión de carne.' WHERE `ID`=27078;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사피론은 한때 노스렌드의 산악 지대에 살던 고귀한 푸른용이었지. 하지만 얼어붙은 북쪽 땅을 진군하던 아서스에게 살해당했고, 부활하여 그를 섬기게 되었다. 사피론은 영원토록 켈투자드의 둥지를 지키며, 감히 그의 주인에게 다가가려는 자를 기다리고 있지.', `MaleText_loc4`='萨菲隆。它本是高贵的蓝龙，自由地翱翔在诺森德的冰峰间，被征战极寒之地的阿尔萨斯所杀。克尔苏加德复活了萨菲隆，如今这头冰霜巨龙守卫着主子的巢穴，等待那些胆敢挑战克尔苏加德的冒险者。', `MaleText_loc5`='薩菲隆。曾經是北裂境群山中一隻高貴的藍龍，在阿薩斯北征這塊冰霜之地時被他殺了。阿薩斯將薩菲隆復活以服侍他，現在薩菲隆永遠守護著科爾蘇加德的巢穴，等待著那些膽敢打擾他主人的人到來。', `MaleText_loc7`='Sapphiron. En el pasado un noble dragón Azul de las montañas de Rasganorte, Sapphiron fue asesinado por Arthas durante su campaña a través del helado norte. Resucitado para servirle, Sapphiron guarda el cubil de Kel''thuzad eternamente, a la espera de que alguien ose entrar en el territorio de su maestro.' WHERE `ID`=27079;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='켈투자드는 무시무시한 리치다. 리치 왕에게 무조건 복종하는 그는 살아있을 적에도 강력한 강령술사로 이름을 떨쳤지만, 죽어서 다시 태어난 이후로는 강령술에서 그를 따라올 자가 없게 되었지. 켈투자드는 리치 왕의 가장 충성스러운 신하라고 한다.', `MaleText_loc4`='巫妖克尔苏加德。显然他为巫妖王效力。克尔苏加德生前是一名强大的通灵师，死后自然而然地成为了巫术大师。据说他是巫妖王最忠诚的部下。', `MaleText_loc5`='巫妖，科爾蘇加德。他心無旁騖的服侍著巫妖王，生前是一位本領高超的死靈法師，死後轉化為死靈法術的大師。聽說他是巫妖王麾下最忠心的部屬。', `MaleText_loc7`='El exánime, Kel''Thuzad. Sirve al Rey Exánime sin preguntas, era un nigromante de gran destreza en vida que se convirtió en un maestro de la nigromancia tras su muerte. Se dice que el súbdito más leal del Rey Exánime.' WHERE `ID`=27080;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛의 결사단에서 가장 강한 자의 영혼조차 산산이 부서졌을 법한 시련을 켈투자드는 견뎌냈다. 계획에 따라 자신의 목숨을 아서스에게 선뜻 내주고는, 후에 태양샘의 힘으로 다시 태어났지.', `MaleText_loc4`='克尔苏加德通过了最为严酷的试炼。即便是圣光兄弟会的成员，这样的试炼也会撼动他们的灵魂。克尔苏加德将自己的生命完完全全交给了阿尔萨斯，然后借助太阳之井的力量得以复生。', `MaleText_loc5`='科爾蘇加德從長久以來連兄弟會的菁英都無法承受的粉碎靈魂試煉中存活了下來。他欣然的死於阿薩斯之手，後來又被帶回 - 在太陽之井的力量下重生。', `MaleText_loc7`='Kel''thuzad ha sobrevivido a pruebas que habrían destrozado las almas incluso de los mejores miembros de la Hermandad hace tiempo. Entregó su vida a manos de Arthas voluntariamente, para ser devuelto a la vida; para renacer en el poder de La Fuente del Sol.' WHERE `ID`=27081;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='역병지대에서 켈투자드는 은빛 여명회의 요원들에게 또다시 패하고 말았지. 하지만 그의 성물함은 가짜 결사단 요원에게 넘어가 버렸다. 우린 아직도 누가, 무슨 목적으로 그 성물함을 훔쳐갔는지 밝혀내지 못했다.', `MaleText_loc4`='克尔苏加德再次被驻扎在瘟疫之地的银色黎明击败。可是他的护符匣落到了圣光兄弟会某个不忠诚的成员手中。至今我们还不知道是谁偷走了护符匣以及其中的阴谋。', `MaleText_loc5`='在瘟疫之地，科爾蘇加德再度被銀色黎明的成員打敗。然而，他的骨匣卻被送往錯誤的兄弟會成員手中。我們還是得去找出是誰偷了他的骨匣或者為何要這樣做。', `MaleText_loc7`='En las Tierras de la Peste, Kel''thuzad volvió a ser derrotado por los agentes de El Alba Argenta. Sin embargo, su filacteria fue entregada a un falso agente de la Hermandad. Aún tenemos que descubrir quién robó su filacteria y por qué.' WHERE `ID`=27082;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밖으로 나오십시오! 엄호하겠습니다!', `MaleText_loc4`='快出来！我会掩护你的！', `MaleText_loc5`='出來，士兵!我會掩護你!', `MaleText_loc7`='¡Sal, soldado! ¡Yo te cubriré!', `FemaleText_loc1`='밖으로 나오십시오! 엄호하겠습니다!', `FemaleText_loc4`='快出来！我会掩护你的！', `FemaleText_loc5`='出來，士兵!我會掩護你!', `FemaleText_loc7`='¡Sal, soldado! ¡Yo te cubriré!' WHERE `ID`=27083;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 있는 쪽으로 달려오십시오! 대포로 길을 뚫겠습니다!', `MaleText_loc4`='到我身边来！我用枪掩护你！', `MaleText_loc5`='士兵，過來我這!我會用鏈砲清出一條路!', `MaleText_loc7`='¡Soldado, corre hacia mí! ¡Abriré camino con la ametralladora!', `FemaleText_loc1`='내가 있는 쪽으로 달려오십시오! 대포로 길을 뚫겠습니다!', `FemaleText_loc4`='到我身边来！我用枪掩护你！', `FemaleText_loc5`='士兵，過來我這!我會用鏈砲清出一條路!', `FemaleText_loc7`='¡Soldado, corre hacia mí! ¡Abriré camino con la ametralladora!' WHERE `ID`=27084;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 모도루의 드레나이 로브를 자세히 살펴봅니다.', `FemaleText_loc4`='%s凝视着莫度鲁的德莱尼礼袍。', `FemaleText_loc5`='%s盯著莫杜魯的德萊尼長袍瞧。', `FemaleText_loc7`='%s echa un vistazo a las togas draénicas de Modoru.' WHERE `ID`=27085;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='쯧쯧... 이봐요. 나오하인. 왜 모도루는 아직도 저 우스꽝스러운 로브를 입고 있는 걸까요? 이세계에서 암멘 골짜기에 도착해 밖으로 기어나온 지 여섯 시간도 채 안 된 시골뜨기처럼 보이잖아요.', `FemaleText_loc4`='诺哈因，你说莫度鲁为什么还穿着这件可笑的袍子啊。他看上去就像那些刚刚逃出埃门谷的乡巴佬似的。', `FemaleText_loc5`='嘿!納歐海恩。為什麼莫杜魯還穿著那些好笑的長袍?他看起來好像某個剛踏出安曼谷不到6個小時的間次元土包子。', `FemaleText_loc7`='Pssst. Naohain. ¿Por qué continua Modoru llevando esas ridículas togas? Parece un paleto interdimensional que acaba de salir del Valle Ammen hace menos de 6 horas.' WHERE `ID`=27086;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소총수, 가서 우리 병사들을 구하십시오! 어서, 어서요!', `MaleText_loc4`='火枪手，营救那些士兵！速度！', `MaleText_loc5`='步槍兵，讓我們的士兵逃出這裡!就是現在現在現在!', `MaleText_loc7`='¡Fusilero, saca a nuestro soldado de allí! ¡VAMOS, VAMOS, VAMOS!', `FemaleText_loc1`='소총수, 가서 우리 병사들을 구하십시오! 어서, 어서요!', `FemaleText_loc4`='火枪手，营救那些士兵！速度！', `FemaleText_loc5`='步槍兵，讓我們的士兵逃出這裡!就是現在現在現在!', `FemaleText_loc7`='¡Fusilero, saca a nuestro soldado de allí! ¡VAMOS, VAMOS, VAMOS!' WHERE `ID`=27087;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소총수, 부상자가 구할 수 있는 거리까지 왔습니다! 가서 데려오십시오!', `MaleText_loc4`='这是营救他的好时机！快去！', `MaleText_loc5`='步槍兵，他已經近到可以進行救援了!「快去把他帶回來」!', `MaleText_loc7`='¡Fusilero, está lo suficientemente cerca como para rescatarlo! ¡VE A POR ÉL!', `FemaleText_loc1`='소총수, 부상자가 구할 수 있는 거리까지 왔습니다! 가서 데려오십시오!', `FemaleText_loc4`='这是营救他的好时机！快去！', `FemaleText_loc5`='步槍兵，他已經近到可以進行救援了!「快去把他帶回來」!', `FemaleText_loc7`='¡Fusilero, está lo suficientemente cerca como para rescatarlo! ¡VE A POR ÉL!' WHERE `ID`=27088;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소총수, 사격 중지! 아군 병사가 사정거리 내에 있습니다! 그를 구해오십시오!', `MaleText_loc4`='火枪手，停止射击！那名士兵就在射程的安全范围之内！快去救他！', `MaleText_loc5`='步槍兵，停火!我們的士兵進入範圍內了!「快把他救出來!」', `MaleText_loc7`='¡Fusilero, alto el fuego! ¡Nuestro soldado está al alcance! ¡SÁCALO DE AHÍ!', `FemaleText_loc1`='소총수, 사격 중지! 아군 병사가 사정거리 내에 있습니다! 그를 구해오십시오!', `FemaleText_loc4`='火枪手，停止射击！那名士兵就在射程的安全范围之内！快去救他！', `FemaleText_loc5`='步槍兵，停火!我們的士兵進入範圍內了!「快把他救出來!」', `FemaleText_loc7`='¡Fusilero, alto el fuego! ¡Nuestro soldado está al alcance! ¡SÁCALO DE AHÍ!' WHERE `ID`=27089;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 왜 이 시대와 장소로 오게 되었습니까?', `MaleText_loc4`='旧斯坦索姆……为什么送我回到这一时间流？', `MaleText_loc5`='為什麼我會被送回這個特殊的地點和時間?', `MaleText_loc7`='¿Por qué me han enviado de vuelta a este lugar concreto en este momento en particular?', `FemaleText_loc1`='저는 왜 이 시대와 장소로 오게 되었나요?', `FemaleText_loc4`='旧斯坦索姆……为什么送我回到这一时间流？', `FemaleText_loc5`='為什麼我會被送回這個特殊的地點和時間?', `FemaleText_loc7`='¿Por qué me han enviado de vuelta a este lugar concreto en este momento en particular?' WHERE `ID`=27090;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무한의 용군단이 아서스 메네실 왕자의 운명을 뒤바꿔 놓으려 합니다.$B$B당신은 그를 리치 왕으로 알고 있겠지만, 지금 이 시대에 있는 그는 왕국을 구하고자 안간힘을 쓰는 로데론의 왕자랍니다.$B$B아서스는 오늘 자신의 운명을 결정하는 선택을 합니다. 우리 시간의 수호자는 이런 사건이 벌어지는 때를 시간의 길 굴절점이라고 부르지요.', `FemaleText_loc4`='永恒之龙企图改变阿尔萨斯·米奈希尔王子的命运。$B$B你所熟悉的巫妖王在这一时间流里仍然是洛丹伦的王子，而且全心全意地为国效力。$B$B今天，阿尔萨斯做出了一个重大的决定，它所导致的后果，被我们时光守护者们称之为时间流的拐点。', `FemaleText_loc5`='恆龍軍團正企圖修改阿薩斯·米奈希爾王子的命運。$B$B你所知道的他現在是巫妖王，但是在這裡的當下，他還是一個想要為他的王國盡力的羅德隆王子。$B$B阿薩斯今日做出了影響命運的決定，導致時間線中出現某種我們時間看守者稱之為『反曲點』的現象。', `FemaleText_loc7`='El Vuelo Infinito está tratando de alterar el destino del príncipe Arthas Menethil.$B$BAhora lo conoces como el Rey Exánime, pero aquí y en este momento aún era un príncipe de Lordaeron que trataba de hacer lo que era mejor para su reino.$B$BHoy Arthas toma una decisión que marcará el destino, llevando a lo que los Vigilantes del Tiempo llamamos un punto de inflexión en la línea temporal.' WHERE `ID`=27091;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그가 어떤 선택을 합니까?', `MaleText_loc4`='是什么决定？', `MaleText_loc5`='這個決定是什麼呢?', `MaleText_loc7`='¿Qué ha sido esta decisión?', `FemaleText_loc1`='그가 어떤 선택을 하나요?', `FemaleText_loc4`='是什么决定？', `FemaleText_loc5`='這個決定是什麼呢?', `FemaleText_loc7`='¿Qué ha sido esta decisión?' WHERE `ID`=27092;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아서스는 스트라솔름의 주민을 모두 죽이라는 명령을 내립니다. 성벽 안에 있는 모든 이를 말이에요.$B$B그는 스컬지가 이 도시에 치명적인 역병을 퍼뜨렸다는 증거를 발견해 냈어요. 그 질병은 단순히 사람을 죽이는 걸로 끝나지 않습니다.$B$B역병 때문에 죽은 사람들은 영혼을 잃은 좀비로 되살아나 스컬지의 일원이 되고 말지요.', `FemaleText_loc4`='阿尔萨斯下令清洗斯坦索姆，杀死城内所有的居民。$B$B他发现了天灾军团在斯坦索姆传播瘟疫的证据。这种疾病不仅能致人死命。$B$B它还能让死于瘟疫的人复生成为无脑的僵尸，将他们统统改造成天灾军团的战争机器。', `FemaleText_loc5`='阿薩斯下令肅清斯坦索姆，殺光裡頭的所有人。$B$B他發現了天譴軍團使用邪惡的瘟疫感染這座城市的證據，而感染這樣疾病不只會把人們殺死。$B$B那些死於這場瘟疫的人會復活成為無腦的殭屍，更進一步成為天譴軍團戰爭機器的燃料。', `FemaleText_loc7`='Arthas ordenó arrasar Stratholme, matando a todos los humanos que hubiera dentro de sus murallas.$B$BDescubrió pruebas de que la Plaga había infectado la ciudad con su insidiosa peste y la enfermedad no solo mata a la gente.$B$BLos que mueren debido a esta peste se vuelven a despertar convertidos en zombis descerebrados que alimentan la máquina de guerra de la Plaga.' WHERE `ID`=27093;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 무한의 용군단은 어떻게 개입하려 합니까?', `MaleText_loc4`='永恒之龙打算如何破坏这一时间流呢？', `MaleText_loc5`='所以恆龍軍團打算要怎麼介入呢?', `MaleText_loc7`='¿Cómo pretende interferir el Vuelo Infinito?', `FemaleText_loc1`='그럼 무한의 용군단은 어떻게 개입하려 하나요?', `FemaleText_loc4`='永恒之龙打算如何破坏这一时间流呢？', `FemaleText_loc5`='所以恆龍軍團打算要怎麼介入呢?', `FemaleText_loc7`='¿Cómo pretende interferir el Vuelo Infinito?' WHERE `ID`=27094;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엄호해 주셔서 감사합니다! 저 아래는 완전히 지옥이에요!', `MaleText_loc4`='谢谢你掩护我！下面简直就像精神病院！', `MaleText_loc5`='謝謝你的掩護射擊!下面簡直是「瘋人院」!', `MaleText_loc7`='¡Gracias por cubrirme! ¡Aquello de abajo es un MANICOMIO!', `FemaleText_loc1`='엄호해 주셔서 감사합니다! 저 아래는 완전히 지옥이에요!', `FemaleText_loc4`='谢谢你掩护我！下面简直就像精神病院！', `FemaleText_loc5`='謝謝你的掩護射擊!下面簡直是「瘋人院」!', `FemaleText_loc7`='¡Gracias por cubrirme! ¡Aquello de abajo es un MANICOMIO!' WHERE `ID`=27095;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우와, 죽는 줄만 알았는데! 감사합니다!', `MaleText_loc4`='哇，我还以为我死定了呢！谢谢你，朋友！', `MaleText_loc5`='哇喔，我以為我死定了!謝啦，朋友!', `MaleText_loc7`='¡Guau! ¡Creí que no lo contaba! ¡Gracias, colega!', `FemaleText_loc1`='우와, 죽는 줄만 알았는데! 감사합니다!', `FemaleText_loc4`='哇，我还以为我死定了呢！谢谢你，朋友！', `FemaleText_loc5`='哇喔，我以為我死定了!謝啦，朋友!', `FemaleText_loc7`='¡Guau! ¡Creí que no lo contaba! ¡Gracias, colega!' WHERE `ID`=27096;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구울의 먹이가 될 뻔했습니다! 구해 주셔서 감사합니다!', `MaleText_loc4`='我差点被食尸鬼给吃了！谢谢你救了我！', `MaleText_loc5`='我差點就變成食屍鬼的誘餌了!謝謝你的營救!', `MaleText_loc7`='¡Ya casi era comida para necrófagos! ¡Gracias por rescatarme!', `FemaleText_loc1`='구울의 먹이가 될 뻔했어요! 구해 주셔서 감사합니다!', `FemaleText_loc4`='我差点被食尸鬼给吃了！谢谢你救了我！', `FemaleText_loc5`='我差點就變成食屍鬼的誘餌了!謝謝你的營救!', `FemaleText_loc7`='¡Ya casi era comida para necrófagos! ¡Gracias por rescatarme!' WHERE `ID`=27097;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 와 줘서 얼마나 다행인지! 우린 완전히 죽은 목숨이었습니다!', `MaleText_loc4`='谢天谢地，你来救我们啦！我们还以为这次肯定完蛋了呢！', `MaleText_loc5`='有你一起真是太好了，盟友!我們差點死定了!', `MaleText_loc7`='¡Qué bien que has venido, $galiado:aliada;! ¡No teníamos salida!', `FemaleText_loc1`='당신이 와 줘서 얼마나 다행인지! 우린 완전히 죽은 목숨이었다고요!', `FemaleText_loc4`='谢天谢地，你来救我们啦！我们还以为这次肯定完蛋了呢！', `FemaleText_loc5`='有你一起真是太好了，盟友!我們差點死定了!', `FemaleText_loc7`='¡Qué bien que has venido, $galiado:aliada;! ¡No teníamos salida!' WHERE `ID`=27098;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물건을 좀 보여주십시오, 덫사냥꾼님.', `MaleText_loc4`='猎户，让我看看你出售的货物。', `MaleText_loc5`='陷捕者，讓我看看你販賣的東西。', `MaleText_loc7`='Muéstrame qué tienes a la venta, trampero.', `FemaleText_loc1`='물건을 좀 보여주세요, 덫사냥꾼님.', `FemaleText_loc4`='猎户，让我看看你出售的货物。', `FemaleText_loc5`='陷捕者，讓我看看你販賣的東西。', `FemaleText_loc7`='Muéstrame qué tienes a la venta, trampero.' WHERE `ID`=27099;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저더러 뭘 하라고 했다고요?', `MaleText_loc4`='什么？他想让我干嘛？', `MaleText_loc5`='他要我去做「啥」?', `MaleText_loc7`='¿Que quiere que haga EL QUÉ?' WHERE `ID`=27100;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 부하들이 지금 하던 연구를 중단하고 군사 작전을 돕게 하고 싶다면, 밀주를 충분히 공급하는 게 좋을 겁니다!', `MaleText_loc4`='好吧，如果他希望我的属下中断研究工作，为军事目的服务的话，他最好为我们提供月光酒！', `MaleText_loc5`='唔，如果他想要我的人停止調查轉而為軍方的目的服務，他最好準備源源不絕的月光酒!', `MaleText_loc7`='¡Bueno, más vale que él haga fluir el licor si quiere que mis hombres abandonen su investigación para llevar a cabo sus propósitos militares!' WHERE `ID`=27101;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무한의 용군단은 평소와 다르게 치밀한 계획을 꾸몄어요. 그들은 아서스가 스트라솔름을 파괴하게 된 증거들을 숨기려 하고 있어요.$B$B무한의 용군단 요원이 스트라솔름 변두리로 가서, 역병에 오염된 곡식에 환영 마법을 사용해 보통 곡식처럼 보이게 했답니다.$B$B그렇게 숨겨진 곡식을 찾아내 이 마력 분열기를 사용해 주세요. 아서스의 부하들이 역병에 오염된 곡식을 열심히 찾고 있으니, 환영만 사라지면 금방 발견할 거예요.', `FemaleText_loc4`='永恒之龙计划以某种隐秘的手段掩盖天灾军团污染斯坦索姆的证据，以此达到蒙蔽阿尔萨斯王子的目的。$B$B永恒之龙的密探已经潜入附近的农场，对感染瘟疫的谷物施加了幻术，令它们看上去和正常的粮食没有任何区别。$B$B我要你找到这些被藏起来的谷物，然后对它们使用奥术干扰器。阿尔萨斯麾下的士兵正在寻找被污染的粮食，只要你驱除了幻象，他们应该很快就能发现真相了。', `FemaleText_loc5`='恆龍正企圖進行某件對他們來說非常不可思議的事。他們試圖想要隱藏導致阿薩斯做下殲滅斯坦索姆這個決定的證據。他們的成員對臨近鄉村的染疫穀物使用了幻像魔法，使它們看起來像是正常的穀物。$B$B我需要你去找出被藏起來的穀物並使用這個秘法干擾器。阿薩斯的人馬正在找尋染疫的穀物，幻術一消失，他們應該很快就會找到了。', `FemaleText_loc7`='Los Infinitos están intentando algo con una sutileza poco común en ellos. Están tratando de ocultar las pruebas que llevarán a Arthas a tomar la decisión de arrasar Stratholme.$B$BSus agentes han usado magia ilusionista para que los cargamentos de grano de los campos cercanos parezcan normales.$B$BNecesito que encuentres el grano y uses este disruptor Arcano en los envíos. Los hombres de Arthas están buscando grano apestado y lo encontrarán rápidamente cuando desaparezca la ilusión.' WHERE `ID`=27102;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리가 붉은용군단의 환심을 살 만한 기회를 얻을 입장은 아니라고 봐요. 앞으로 있을 전투를 생각하면 그들은 값진 동맹이 되어줄 수 있을 거예요.', `FemaleText_loc4`='我们不能放弃奉承红龙军团的好机会。战争迫在眉睫，与红龙结盟对我们是大有裨益的。', `FemaleText_loc5`='我不覺得我們有本錢能錯失和紅龍軍團交好的機會，只要還有戰事，有他們作為聯軍的價值難以估計。', `FemaleText_loc7`='No creo que podamos permitirnos dejar pasar la oportunidad de congraciarnos con el Vuelo Rojo. Con las batallas que se avecinan, tenerlos como aliados tendrá un valor incalculable.' WHERE `ID`=27103;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오래전, 흑마법사 네크로스 스컬크러셔는 강력한 유물을 사용해 알렉스트라자와 붉은용군단 대부분을 노예로 만들었소. 줄루헤드와 네크로스는 이미 죽었지만, 붉은용군단에게 그 빚을 갚으려면 아직 멀었소.', `MaleText_loc4`='这些年来，耐克鲁斯滥用神器奴役阿莱克丝塔萨女王和其他红龙。虽然祖鲁希德和耐克鲁斯都死了，但是我们亏欠红龙的债远没有还清。', `MaleText_loc5`='多年以前，術士耐克魯斯·碎顱濫用強大的神器奴役雅立史卓莎，以及大多數的紅龍軍團。祖魯希德和耐克魯斯雖死，但我們欠紅龍的仍難以償還。', `MaleText_loc7`='Hace años, el brujo Nekros Aplastacráneos abusó de un poderoso artefacto para encerrar a Alexstrasza y a la mayoría del Vuelo Rojo. Zuluhed y Nekros están muertos, pero la deuda que tenemos con los Rojos aún sigue pendiente.' WHERE `ID`=27104;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='길에서 너무 멀리 떨어져서는 안 됩니다, $n. 대장과 그의 병사들 곁에 있으세요... 그대가 죽어버리면 우리에게 아무 도움도 되지 않으니까요.', `MaleText_loc4`='$n，别和大部队走散了。你最好待在上尉和他手下的士兵身边……你死了的话事情就不好办了。', `MaleText_loc5`='別遠離道路太遠，$n。跟緊隊長跟他手下...你死了就對我們一點用處也沒有。', `MaleText_loc7`='No te alejes demasiado del paso, $n. Quédate con el Capitán y su hombres... Si mueres no nos servirás para nada.' WHERE `ID`=27105;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용제단을 드나들 때는 반드시 남쪽 계곡을 통해 가도록 하십시오, $n. 누더기골렘과의 전투가 벌어지는 곳이니 쉽게 알 수 있을 겁니다... 전투가 벌어지는 곳과는 거리를 두세요.', `MaleText_loc4`='$n，记得从南面的峡谷进出神殿。原本驻守在其他峡谷的憎恶正打得不可开交呢……你最好别自找麻烦。', `MaleText_loc5`='當出入龍殿時，請務必利用峽谷的南方， $n。你會發現在峽谷所進行的戰爭，被一群護衛該處的憎惡所發起...請保持距離。', `MaleText_loc7`='$n, al entrar y salir del santuario asegúrate de atravesar el cañón del sur. Reconocerás los cañones donde están luchando por las abominaciones que los guardan… mantente a distancia.' WHERE `ID`=27106;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스는 이 외딴 오두막을 한동안 지원해 왔소. 우리 사냥꾼과 벌목꾼들이 이용하는 장소였지.$B$B하지만 전쟁이 계속되고 있는 이상, 이제 이곳은 지원 대상이 아니라 군에서 관리하는 곳이라고 생각하는 게 좋소.', `MaleText_loc4`='联盟控制这座偏远的营地有好些日子了。对我们的猎户和伐木工而言，这倒算不上是什么坏事。$B$B不过局势日益恶化，很快这里也要进驻军队了吧。', `MaleText_loc5`='聯盟已經維持這座偏僻的小屋好一陣子，被我方的獵人與護林者使用著。$B$B只要戰事持續，你最好相信軍隊還能掌控這裡。', `MaleText_loc7`='La Alianza ha mantenido este remoto hospedaje durante algún tiempo. Nuestros cazadores y leñadores le han dado algo de uso.$B$BPero, con la guerra en curso, será mejor que te creas que ahora manda el ejército.' WHERE `ID`=27107;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 처리하게 해 주세요, 언니.', `FemaleText_loc4`='交给我来处理吧。', `FemaleText_loc5`='姊妹，交給我吧。', `FemaleText_loc7`='Deja que yo me encargue, hermana.' WHERE `ID`=27108;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대체 무슨 생각이었나? 그녀를 화나게 하지 않았나!', `FemaleText_loc4`='真搞不懂，你为什么要招惹她呢？', `FemaleText_loc5`='你在想什麼，像那樣子挑釁她嗎?', `FemaleText_loc7`='¿En qué estabas pensando, provocándole de esa manera?' WHERE `ID`=27109;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이... 바보 같으니! 이번엔 제대로 실수했네. 정말로 다리가 부러진 것처럼 보여야 해.', `FemaleText_loc4`='你……你这蠢货！你的胆子可不小。别怪我狠心，至少我得让你看起来像是断腿的伤员。', `FemaleText_loc5`='你...真是笨!你這回真的這麼做了。我必須得讓你的腳看起來像是斷了一樣。', `FemaleText_loc7`='Tú... ¡Medio-bobo! Esta vez la has liado. Voy a tener que hacer que parezca que tienes la pierna rota.' WHERE `ID`=27110;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다시 걷고 싶거든 절대로 움직이지 말게!', `FemaleText_loc4`='如果你还想走路的话，就别乱动。', `FemaleText_loc5`='要是你還想走路的話現在就不要亂動!', `FemaleText_loc7`='Ahora, si quieres volver a caminar alguna vez, no te muevas.' WHERE `ID`=27111;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제발, 안 됩니다. 그러지 마세요!', `MaleText_loc4`='啊，不要！住手！', `MaleText_loc5`='不要，拜託!不要啊!', `MaleText_loc7`='¡No, por favor! ¡No!' WHERE `ID`=27112;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<설명을 중단하고 돌아서서 평가하듯 당신을 바라보는 사령관>$B$B당신같은 $c에게 딱 맞는 일이 있소.', `MaleText_loc4`='<指挥官停止授课，转过身来打量着你。>$B$B要不要听听，$c？接纳新知识对你来说是很有好处的。', `MaleText_loc5`='<指揮官課程結束以後轉身，眼睛在你身上打量一遍。>$B$B$c，我需要你這樣的人。', `MaleText_loc7`='<El Comandante detiene la clase y se gira: sus ojos te evalúan, te juzgan.>$B$bCreo que alguien como tú me sería de ayuda, $c.' WHERE `ID`=27113;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 무슨 일로 왔소?$B$B낙스라마스에 대해 더 자세히 알고 싶다면 얼마든지 알려줄 수 있소.', `MaleText_loc4`='$c，我能帮你什么忙吗？$B$B如果你愿意听听关于纳克萨玛斯的课程，不妨挑个位子坐下来。', `MaleText_loc5`='你好，$c，我能為你效勞嗎?$B$B如果你是要來上關於納克薩瑪斯的課程，我們還有很多位置。', `MaleText_loc7`='Sí, $c, ¿en qué puedo ayudarte?$B$bSi lo que quieres es una lección sobre Naxxramas, hay sitio de sobra.' WHERE `ID`=27114;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음? 무슨 일이오?', `MaleText_loc4`='$c，有事吗？', `MaleText_loc5`='你好，$c，有何貴幹?', `MaleText_loc7`='Sí, $c, ¿qué ocurre?' WHERE `ID`=27115;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 만나서 반갑군, $n.$B$B스컬지 녀석들에 대해 더 배우고 싶소?', `MaleText_loc4`='$n，我们又见面啦。$B$B想要复习对付天灾军团的战术吗？', `MaleText_loc5`='$n，很高興再度見到你。$B$B來惡補天譴軍戰略課程嗎?', `MaleText_loc7`='Me alegro de verte de nuevo, $n.$b$b¿Has venido a poner al día tus conocimientos sobre tácticas de la Plaga?' WHERE `ID`=27116;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발밑의 땅이 갈라지기 시작합니다.', `MaleText_loc4`='你的脚下裂开了一道缝隙。', `MaleText_loc5`='你的腳下開啟了一道裂縫。', `MaleText_loc7`='Una grieta comienza a abrirse bajo tus pies.' WHERE `ID`=27117;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐요, 신발을 맞춰 신지 않으면 패션은 절대 완성할 수 없는 법이에요. 그렇게 생각하지 않으세요?', `MaleText_loc4`='亲爱的，没有合适的鞋子来搭配你这身装束，总觉得不顺眼呢。你觉得呢？', `MaleText_loc5`='親愛的，要是沒有對的鞋子，你根本沒辦法讓你的外表出眾，你說對吧?', `MaleText_loc7`='Querida, tu aspecto no será ideal hasta que lo completes con los zapatos adecuados. ¿No crees?', `FemaleText_loc1`='이봐요, 신발을 맞춰 신지 않으면 패션은 절대 완성할 수 없는 법이에요. 그렇게 생각하지 않으세요?', `FemaleText_loc4`='亲爱的，没有合适的鞋子来搭配你这身装束，总觉得不顺眼呢。你觉得呢？', `FemaleText_loc5`='親愛的，要是沒有對的鞋子，你根本沒辦法讓你的外表出眾，你說對吧?', `FemaleText_loc7`='Querida, tu aspecto no será ideal hasta que lo completes con los zapatos adecuados. ¿No crees?' WHERE `ID`=27118;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이야, 그 신발 아주 죽여주는데요! 말 그대로요. 대체 누굴 해치우고 얻으셨어요?', `FemaleText_loc4`='亲爱的，那些漂亮的鞋子简直值得你为它们而死啊！说真的啦。你从谁手中抢来的啊？肯定免不了一场血腥吧。', `FemaleText_loc5`='親愛的，這雙鞋子真是棒到可以為他付出生命!我說的就是字面上的意思，你是殺了誰把鞋子搶過來的?', `FemaleText_loc7`='Querido, ¡moriría por esos zapatos! Literalmente. ¿A quién has matado para conseguirlos?' WHERE `ID`=27119;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 놈을 꾀어오겠습니다, $n! 당신은 놈이 올 때를 대비해 준비하십시오!', `MaleText_loc4`='$n，我会将她赶出藏身之地。你要做好准备，待会她一露面就动手！', `MaleText_loc5`='我要把她趕出來，$n!當她進來的時候準備好對付她!', `MaleText_loc7`='¡Yo la descubriré, $n! ¡Tú prepárate para cuando entre!', `FemaleText_loc1`='제가 놈을 꾀어오겠습니다, $n! 당신은 놈이 올 때를 대비해 준비하십시오!', `FemaleText_loc4`='$n，我会将她赶出藏身之地。你要做好准备，待会她一露面就动手！', `FemaleText_loc5`='我要把她趕出來，$n!當她進來的時候準備好對付她!', `FemaleText_loc7`='¡Yo la descubriré, $n! ¡Tú prepárate para cuando entre!' WHERE `ID`=27120;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상품권 교환', `MaleText_loc4`='奖券兑换', `MaleText_loc5`='獎券兌換', `MaleText_loc7`='Canjeo de vales', `FemaleText_loc1`='상품권 교환', `FemaleText_loc4`='奖券兑换', `FemaleText_loc5`='獎券兌換', `FemaleText_loc7`='Canjeo de vales' WHERE `ID`=27121;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명령만 하십시오!', `MaleText_loc4`='等待命令！', `MaleText_loc5`='待命攻擊!', `MaleText_loc7`='¡Esperando órdenes!' WHERE `ID`=27122;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쏴라! 쏴라! 놈을 떨어트려라!', `MaleText_loc4`='开火！！击中她！', `MaleText_loc5`='開火!開火!把她打下來!', `MaleText_loc7`='¡FUEGO! ¡FUEGO! ¡DERRIBADLA!' WHERE `ID`=27123;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='화강암 웅덩이에 어서 오시오.$b$b얼음 트롤을 생포하거든 내게 꼭 알려주시오. 현상금을 두둑하게 드릴 테니.', `MaleText_loc4`='欢迎来到岩石之泉。$b$b如果你能活捉这些冰霜巨魔的话，记得来找我谈谈。我愿意出高价买他们。', `MaleText_loc5`='歡迎來到花崗岩之泉，朋友。$b$b如果你活逮任何一隻寒冰食人妖，一定要讓我知道，我會給他們出個好價錢的。', `MaleText_loc7`='Te doy la bienvenida al Manantial de Granito, colega.$B$BSi consigues atrapar a alguno de esos trols de hielo vivo, avísame. Pagamos bien por ellos.' WHERE `ID`=27124;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='텔잔의 성물함이 얼음폭풍의 발밑에 떨어집니다.', `MaleText_loc4`='塞尔赞的护符匣滚落到冰雪风暴脚下。', `MaleText_loc5`='賽爾贊的骨匣在冰颶下落到地面上。', `MaleText_loc7`='La filacteria de Thel''zan cae al suelo bajo Tormenta de Hielo.' WHERE `ID`=27125;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"나무가 얼마나 좋은가, 펜릭. 우리에게 은신처를 제공한단 말일세."라고? 나무를 안 베고 어떻게 해결하라는 건지.', `MaleText_loc4`='“我们都喜欢树木，芬里克。它们是很好的遮蔽物。”呸，就是不肯让我砍掉这些讨厌的植物。', `MaleText_loc5`='「我們熱愛林木，芬里克。它們提供了屏障。」它們也不會任由我們砍伐的。', `MaleText_loc7`='''Nos gustan los árboles, Fenrick. Nos ocultan.'' Además, no me dejan cortarlos.' WHERE `ID`=27126;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대체 무슨 근거로 박쥐가 저 각도로 안전히 착지할 거로 생각하는 건지 모르겠단 말이야. 남는 건 부러진 목에 냄새 나는 박쥐 스튜밖에 없을 거라고.', `MaleText_loc4`='他们想让蝙蝠以那种危险的飞行角度降落吗？好呀，就让乘客们摔断脖子吧，他们还能喝到鲜美的蝙蝠汤。', `MaleText_loc5`='他們期待什麼，讓蝙蝠從那個角度飛進來?他們只會得到斷掉的頸子和腥羶蝙蝠燉肉。', `MaleText_loc7`='¿Qué esperan si hacen que los murciélagos entren desde ese ángulo? Todo lo que conseguirán son cuellos rotos y papilla de murciélago.' WHERE `ID`=27127;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대체 앞으로 증원군이 몇 명이나 더 다쳐야 저 나무를 베도록 허락해 줄지 모르겠군. 박쥐 때문에 엄청난 돈을 날리고 있는데 말이야. 여기에 그물이라도 쳐 놔야 하나...', `MaleText_loc4`='援军正陆续赶来，不知道伤亡人数要上升到什么程度，他们才肯同意我砍掉这些讨厌的树木。我们的蝙蝠损失严重。或许我应该给它们配备盔甲……', `MaleText_loc5`='我好奇還要讓多少援軍受傷，他們才肯讓我們砍掉這些大笨樹。這讓我們折損了許多珍貴的蝙蝠。也許我該把一兩隻蝙蝠套上鞍具才對...', `MaleText_loc7`='Me pregunto cuántos refuerzos más han de sufrir heridas antes de que nos dejen cortar esos estúpidos árboles. Nos están costando una fortuna en murciélagos. Quizá me ponga un arnés o dos...' WHERE `ID`=27128;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노움들은 오늘 밤도 박쥐 창자나 먹게 생겼군...', `MaleText_loc4`='侏儒们今晚又有蝙蝠胃囊吃啦……', `MaleText_loc5`='今晚又給地精吃蝙蝠胃了...', `MaleText_loc7`='A los gnomos les vuelven a tocar otra vez mollejas de murciélago esta noche...' WHERE `ID`=27129;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐요, 가을 축제 동전을 갖고 계시군요. 제가 가을 축제 상품을 좀 판매하고 있으니 한번 둘러보시지요.', `MaleText_loc4`='嘿，你手里拿的不是美酒节奖币吗？如果你有兴趣的话，我这里还有一些美酒节物品出售。', `MaleText_loc5`='嘿，我看到你手上的啤酒節獎品章，如果你需要的話，我有些啤酒節禮品可以賣喔。', `MaleText_loc7`='Oye, veo que tienes algunas fichas de la Fiesta de la Cerveza. Si quieres, aún tengo algunos objetos de la Fiesta de la Cerveza a la venta.', `FemaleText_loc1`='이봐요, 가을 축제 동전을 갖고 계시군요. 제가 가을 축제 상품을 좀 판매하고 있으니 한번 둘러보시지요.', `FemaleText_loc4`='嘿，你手里拿的不是美酒节奖币吗？如果你有兴趣的话，我这里还有一些美酒节物品出售。', `FemaleText_loc5`='嘿，我看到你手上的啤酒節獎品章，如果你需要的話，我有些啤酒節禮品可以賣喔。', `FemaleText_loc7`='Oye, veo que tienes algunas fichas de la Fiesta de la Cerveza. Si quieres, aún tengo algunos objetos de la Fiesta de la Cerveza a la venta.' WHERE `ID`=27130;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나가라.', `MaleText_loc4`='滚开。', `MaleText_loc5`='離開那裡。', `MaleText_loc7`='Sal ahí fuera.' WHERE `ID`=27131;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가서 할 일을 해라, 조그만 밥벌레야.', `MaleText_loc4`='做你的事去。', `MaleText_loc5`='無賴，做你的事。', `MaleText_loc7`='Haz tu trabajo, piltrafilla.' WHERE `ID`=27132;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뛰어내려 죽고 싶다면 말리진 않겠다.', `MaleText_loc4`='你想自寻死路的话，我是不会阻拦你的。', `MaleText_loc5`='如果你這次想要跳下去自殺，我不會阻止你的。', `MaleText_loc7`='Esta vez no te detendré si quieres saltar hacia tu muerte.' WHERE `ID`=27133;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 차례다, 쥐새끼 같은 녀석아.', `MaleText_loc4`='你已经无路可退了。', `MaleText_loc5`='該你了，混帳。', `MaleText_loc7`='Adelante, ratas.' WHERE `ID`=27134;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정각이다, 꼬맹이들아. 나가라.', `MaleText_loc4`='整点啦。去吧。', `MaleText_loc5`='大家整點出發，上。', `MaleText_loc7`='Son en punto, chicos. Adelante.' WHERE `ID`=27135;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맞기 싫거든 어서 나가라. 알아들었나?', `MaleText_loc4`='你最好趁我数到3之前滚远点。你懂我的意思吧？', `MaleText_loc5`='當我開始為你測速的時候你就給我馬上離開那，開始。懂了嗎?', `MaleText_loc7`='¡Largo de ahí o te relojeo! Reloj…eo. ¿Lo pillas?' WHERE `ID`=27136;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고룡미끼라고요? 흠, 가서 얼음폭풍을 데려와 주십시오!', `MaleText_loc4`='龙饵，是吧？去吧，引诱冰雪风暴！', `MaleText_loc5`='巨龍引誘者，是嗎?那，把冰颶帶給我們!', `MaleText_loc7`='Cebo de vermis, ¿eh? ¡Ve y tráenos a Tormenta de Hielo!', `FemaleText_loc1`='고룡미끼라고요? 흠, 가서 얼음폭풍을 데려와 주세요!', `FemaleText_loc4`='龙饵，是吧？去吧，引诱冰雪风暴！', `FemaleText_loc5`='巨龍引誘者，是嗎?那，把冰颶帶給我們!', `FemaleText_loc7`='Cebo de vermis, ¿eh? ¡Ve y tráenos a Tormenta de Hielo!' WHERE `ID`=27137;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요새 어떠십니까, $n 님? 동호회 회원들과 어울리려고 여기 들르셨나요?', `MaleText_loc4`='过得怎么样啊，$n？想和俱乐部的会员共度欢乐时光吗？', `MaleText_loc5`='$n，最近過得怎樣呀?來這跟俱樂部的成員聊聊嗎?', `MaleText_loc7`='¿Qué tal te trata la vida, $n? ¿Has venido a pasar un rato con los demás miembros del club?', `FemaleText_loc1`='요새 어떠십니까, $n 님? 동호회 회원들과 어울리려고 여기 들르셨나요?', `FemaleText_loc4`='过得怎么样啊，$n？想和俱乐部的会员共度欢乐时光吗？', `FemaleText_loc5`='$n，最近過得怎樣呀?來這跟俱樂部的成員聊聊嗎?', `FemaleText_loc7`='¿Qué tal te trata la vida, $n? ¿Has venido a pasar un rato con los demás miembros del club?' WHERE `ID`=27138;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 만나서 반갑습니다, $n 님. 우리 동호회에서 즐거우셨으면 좋겠군요.', `MaleText_loc4`='我们又见面啦，$n。希望你能喜欢我们的俱乐部。', `MaleText_loc5`='很高興再次見到你，$n。希望你在俱樂部裡玩的開心。', `MaleText_loc7`='Me alegro de volver a verte, $n. Espero que nuestro club te esté tratando bien.', `FemaleText_loc1`='다시 만나서 반갑습니다, $n 님. 우리 동호회에서 즐거우셨으면 좋겠군요.', `FemaleText_loc4`='我们又见面啦，$n。希望你能喜欢我们的俱乐部。', `FemaleText_loc5`='很高興再次見到你，$n。希望你在俱樂部裡玩的開心。', `FemaleText_loc7`='Me alegro de volver a verte, $n. Espero que nuestro club te esté tratando bien.' WHERE `ID`=27139;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하신가, $n. 요새 사는 건 좀 어떤가? 동호회 회원들과 어울리려고 들른 거겠지?', `MaleText_loc4`='过得怎么样啊，$n？想和俱乐部的会员共度欢乐时光吗？', `MaleText_loc5`='嘿，$n，近來好嗎?來這跟俱樂部的成員聊聊嗎?', `MaleText_loc7`='¿Qué tal te trata la vida, $n? ¿Has venido a pasar un rato con los demás miembros del club?', `FemaleText_loc1`='안녕하신가, $n. 요새 사는 건 좀 어떤가? 동호회 회원들과 어울리려고 들른 거겠지?', `FemaleText_loc4`='过得怎么样啊，$n？想和俱乐部的会员共度欢乐时光吗？', `FemaleText_loc5`='嘿，$n，近來好嗎?來這跟俱樂部的成員聊聊嗎?', `FemaleText_loc7`='¿Qué tal te trata la vida, $n? ¿Has venido a pasar un rato con los demás miembros del club?' WHERE `ID`=27140;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, $n! 우리 동호회에서 즐겁길 바라네!', `MaleText_loc4`='嘿，$n！希望你喜欢我们的俱乐部！', `MaleText_loc5`='嘿，$n!我希望你喜歡我們的俱樂部!', `MaleText_loc7`='¡Hey, $n! ¡Espero que hayas estado disfrutando de nuestro club!', `FemaleText_loc1`='이봐, $n! 우리 동호회에서 즐겁길 바라네!', `FemaleText_loc4`='嘿，$n！希望你喜欢我们的俱乐部！', `FemaleText_loc5`='嘿，$n!我希望你喜歡我們的俱樂部!', `FemaleText_loc7`='¡Hey, $n! ¡Espero que hayas estado disfrutando de nuestro club!' WHERE `ID`=27141;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방금 뭐지?', `MaleText_loc4`='这是什么？', `MaleText_loc5`='這是什麼?', `MaleText_loc7`='¿Qué pasa?', `FemaleText_loc1`='방금 뭐지?', `FemaleText_loc4`='这是什么？', `FemaleText_loc5`='這是什麼?', `FemaleText_loc7`='¿Qué pasa?' WHERE `ID`=27143;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저건 그야말로 지옥의 문 같아!', `MaleText_loc4`='看上去像是通往地狱的大门！', `MaleText_loc5`='這看來是扇通往地獄之門!', `MaleText_loc7`='¡Parece un portal al infierno!', `FemaleText_loc1`='저건 그야말로 지옥의 문 같아!', `FemaleText_loc4`='看上去像是通往地狱的大门！', `FemaleText_loc5`='這看來是扇通往地獄之門!', `FemaleText_loc7`='¡Parece un portal al infierno!' WHERE `ID`=27144;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 살아서 윈터가드에 돌아가지 못하면, 가족들에게 내가 용감히 싸웠다고 전해 줘. 그리고 사랑한다는 말도...', `MaleText_loc4`='如果我不能重返暮冬要塞，请转告我的家人，我从未放弃过与他们团聚的梦想……', `MaleText_loc5`='要是我回不去溫特加德，讓我的家人知道，我盡力了，我愛他們...', `MaleText_loc7`='Si no consigo regresar a Hibergarde, di a mi familia que hice lo que pude y que los quiero...', `FemaleText_loc1`='내가 살아서 윈터가드에 돌아가지 못하면, 가족들에게 내가 용감히 싸웠다고 전해 줘. 그리고 사랑한다는 말도...', `FemaleText_loc4`='如果我不能重返暮冬要塞，请转告我的家人，我从未放弃过与他们团聚的梦想……', `FemaleText_loc5`='要是我回不去溫特加德，讓我的家人知道，我盡力了，我愛他們...', `FemaleText_loc7`='Si no consigo regresar a Hibergarde, di a mi familia que hice lo que pude y que los quiero...' WHERE `ID`=27145;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 끝일까? 지금 이 괴물을 막아내면 분노의 관문에서 승리할 수 있는 걸까?', `MaleText_loc4`='一切都结束了？只要阻止塞尔赞的阴谋，天谴之门的战事就能取得胜利？', `MaleText_loc5`='這樣就結束了嗎?如果我們阻止了這個怪物，憤怒之門真的就能確保勝利了嗎?', `MaleText_loc7`='¿Es el final? Si detenemos a este monstruo ahora, ¿la victoria en la Puerta de Cólera está asegurada?', `FemaleText_loc1`='이게 끝일까? 지금 이 괴물을 막아내면 분노의 관문에서 승리할 수 있는 걸까?', `FemaleText_loc4`='一切都结束了？只要阻止塞尔赞的阴谋，天谴之门的战事就能取得胜利？', `FemaleText_loc5`='這樣就結束了嗎?如果我們阻止了這個怪物，憤怒之門真的就能確保勝利了嗎?', `FemaleText_loc7`='¿Es el final? Si detenemos a este monstruo ahora, ¿la victoria en la Puerta de Cólera está asegurada?' WHERE `ID`=27146;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조금 걱정이 되는걸. 이 전투에서 우리를 이끌기로 한 영웅은 대체 어디 있는 거지?', `MaleText_loc4`='我有些担心。原本应该站出来领导我们的英雄在哪儿？', `MaleText_loc5`='我越來越擔心了。那位曾經帶領我們衝鋒陷陣的英雄去哪兒了?', `MaleText_loc7`='Estoy empezando a preocuparme un poco. ¿Dónde está ese héroe que nos va a guiar en la batalla?', `FemaleText_loc1`='조금 걱정이 되는걸. 이 전투에서 우리를 이끌기로 한 영웅은 대체 어디 있는 거지?', `FemaleText_loc4`='我有些担心。原本应该站出来领导我们的英雄在哪儿？', `FemaleText_loc5`='我越來越擔心了。那位曾經帶領我們衝鋒陷陣的英雄去哪兒了?', `FemaleText_loc7`='Estoy empezando a preocuparme un poco. ¿Dónde está ese héroe que nos va a guiar en la batalla?' WHERE `ID`=27147;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희와 어깨를 나란히 하고 싸운 건 내게 크나큰 영광이자 기쁨이었다는 사실을 알아줘...', `MaleText_loc4`='能与你们并肩作战是我无上的荣耀。', `MaleText_loc5`='讓後人知道，能和你們一道作戰是多麼的尊貴與光榮。', `MaleText_loc7`='Que sepan que ha sido un honor y un privilegio luchar junto a todos ustedes.', `FemaleText_loc1`='너희와 어깨를 나란히 하고 싸운 건 내게 크나큰 영광이자 기쁨이었다는 사실을 알아줘...', `FemaleText_loc4`='能与你们并肩作战是我无上的荣耀。', `FemaleText_loc5`='讓後人知道，能和你們一道作戰是多麼的尊貴與光榮。', `FemaleText_loc7`='Que sepan que ha sido un honor y un privilegio luchar junto a todos ustedes.' WHERE `ID`=27148;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제발... 제발 좀 끝났으면 좋겠군!', `MaleText_loc4`='来吧……结束这场噩梦！', `MaleText_loc5`='來吧...讓我們解決這一切!', `MaleText_loc7`='Vamos... ¡Acabemos con esto!', `FemaleText_loc1`='제발... 제발 좀 끝났으면 좋겠군!', `FemaleText_loc4`='来吧……结束这场噩梦！', `FemaleText_loc5`='來吧...讓我們解決這一切!', `FemaleText_loc7`='Vamos... ¡Acabemos con esto!' WHERE `ID`=27149;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누구든... 언젠가는 죽음을 맞이하게 마련이지만, 때 이른 죽음을 자초하는 사람도 있지. 오늘 우리는 그런 이를 눈먼 영웅이라 부르지만... 내일 누군가는 그를 바보라고 부를지도 몰라.', `MaleText_loc4`='死亡终究会夺走我们的性命，但是有时候它比预想的来得要快。今天，我们将其称之为盲勇……明天，后人或许就将其形容为愚蠢。', `MaleText_loc5`='最終死亡都將找上我們，但是有些時候它比預期的快一點點。今天也許有人會稱它作逞英雄...明天就有人會說它只是愚蠢的行為。', `MaleText_loc7`='La Muerte nos visita a todos al final, pero a algunos les llega algo antes de lo esperado. Hoy los llamamos héroes ciegos. Quizá mañana alguien lo considere estupidez.', `FemaleText_loc1`='누구든... 언젠가는 죽음을 맞이하게 마련이지만, 때 이른 죽음을 자초하는 사람도 있지. 오늘 우리는 그런 이를 눈먼 영웅이라 부르지만... 내일 누군가는 그를 바보라고 부를지도 몰라.', `FemaleText_loc4`='死亡终究会夺走我们的性命，但是有时候它比预想的来得要快。今天，我们将其称之为盲勇……明天，后人或许就将其形容为愚蠢。', `FemaleText_loc5`='最終死亡都將找上我們，但是有些時候它比預期的快一點點。今天也許有人會稱它作逞英雄...明天就有人會說它只是愚蠢的行為。', `FemaleText_loc7`='La Muerte nos visita a todos al final, pero a algunos les llega algo antes de lo esperado. Hoy los llamamos héroes ciegos. Quizá mañana alguien lo considere estupidez.' WHERE `ID`=27150;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; $n에게 서리 무덤을 시전합니다.', `MaleText_loc4`='%s对$n施放冰霜坟墓。', `MaleText_loc5`='%s對$n施展冰霜之墓。', `MaleText_loc7`='%s lanza Tumba de Escarcha a $n.' WHERE `ID`=27152;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 잔인한 괴물들로부터 저를 구해주셨군요. 감사합니다.', `MaleText_loc4`='谢谢你从那些怪物手中救了我。', `MaleText_loc5`='你把我從一群兇惡的怪物手中救了出來，謝謝你。', `MaleText_loc7`='Me has salvado de las garras de esos feroces monstruos. Gracias.' WHERE `ID`=27153;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n, 다시 만나서 반가워요!$B$B아니, 이번이 처음 만나는 거였나요?$B$B워낙 여러 장소와 시간대를 넘나들고 있어 가끔 헷갈릴 때가 있어요.', `FemaleText_loc4`='$n，很高兴见到你！$B$B这是我们初次见面吗？$B$B我游历过许多地方，穿越过数条时间流，很难记住所有的事。', `FemaleText_loc5`='$n，很高興見到你!$B$B還是說，這是我們首度見面呢?$B$B我現在得東奔西跑，有的時候我根本記不得誰是誰。', `FemaleText_loc7`='¡$n, me alegro de verte!$B$B¿O es la primera vez que nos encontramos?$B$BAhora mismo estoy en tantos lugares y momentos que a veces es difícil llevar la cuenta.' WHERE `ID`=27154;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마음을 굳게 먹어라, 제군들. $n|1이;가; 이 모든 일을 끝낼 마지막 조각을 구해줬다. 공포의 대상이던 리치 텔잔은 곧 은신처에서 기어나올 것이다. 그리고 우리는 녀석에게 반드시 승리할 것이야!', `MaleText_loc4`='士兵们，振作起来。$n已经帮我们揭开了最后的谜团。巫妖塞尔赞很快就会显身，让我们一举击败他吧！', `MaleText_loc5`='大兵們，全副武裝。$n帶給我們最後一片的拼圖。恐懼巫妖，賽爾贊，將會從藏身處現身，變得虛弱無力的對抗我們!', `MaleText_loc7`='Armaos de valor, soldados. $n nos ha proporcionado la última pieza del puzle. ¡El aterrador exánime, Thel''zan, saldrá pronto de su escondite y se verá impotente ante nosotros!' WHERE `ID`=27155;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 성물함, 텔잔의 성물함이야말로 승리의 열쇠이다!', `MaleText_loc4`='这就是塞尔赞的护符匣，它是我们取胜的关键！', `MaleText_loc5`='就是這骨匣 - 賽爾贊的骨匣 - 這就是勝利的關鍵!', `MaleText_loc7`='¡Esta filacteria, la filacteria de Thel''zan, es la llave hacia la victoria!' WHERE `ID`=27156;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나도 한때는... 너와 같았다, 필멸의 존재여. 연약했지. 뼈와 살만 가진, 나약하고 소심한 존재였다!', `MaleText_loc4`='凡人，曾经……我和你一样，血肉之躯，不堪一击！', `MaleText_loc5`='我...曾經和你一樣，平凡，柔弱，單純的血肉之軀。既虛弱又膽小!', `MaleText_loc7`='Antes... yo era como tú. Mortal. Blandito. Solo carne y hueso. ¡DÉBIL Y TÍMIDO!' WHERE `ID`=27157;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제군들, 자세를 가다듬어라!', `MaleText_loc4`='士兵们，坚持住！', `MaleText_loc5`='軍團士兵，穩住陣線!', `MaleText_loc7`='¡LEGIÓN! ¡CALMAOS!' WHERE `ID`=27158;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 왕인 아서스 님께서는 내게서 인간의 연약함을 발견하셨다.', `MaleText_loc4`='阿尔萨斯王子从我身上看到了凡人的脆弱。', `MaleText_loc5`='吾王阿薩斯，看見了我人性中的弱點。', `MaleText_loc7`='Nuestro señor, Arthas, vio en mí la fragilidad de los hombres.' WHERE `ID`=27159;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"목숨으로써 날 섬긴다면 네 영혼에 깃든 연약함을 제거해 주겠다. 그 존재 자체를 지워주겠다!" 그분께 선택받고자... 난 그렇게 리치 왕의 축복을 받게 되었다.', `MaleText_loc4`='“终生为我效劳吧。我承诺，我会抹除你灵魂中的弱点。彻底抹除！”我以这样的方式被巫妖王选中……接受了他的赐福。', `MaleText_loc5`='「用生命侍奉我，我就承諾你去除靈魂中的弱點。從存在中抹消!」為了要被挑上...被巫妖王用這種方式祝福。', `MaleText_loc7`='"Sírveme en vida y prometo eliminar la debilidad de tu alma. ¡Eliminarla de la existencia!" Ser elegido... bendecido por el Rey Exánime de semejante manera.' WHERE `ID`=27160;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래서 난 그분을 섬겼다... 내가 아니었으면 이 영광스러운 공포의 요새 낙스라마스는 결코 노스렌드로 돌아오지 못했을 것이야.', `MaleText_loc4`='我成为了巫妖王的仆从……恐怖之城纳克萨玛斯能重返诺森德全都是我的功劳。', `MaleText_loc5`='我就這麼選擇服侍他...若非我在，壯麗的驚懼城塞納克薩瑪斯永遠也不要想返回北裂境。', `MaleText_loc7`='Así que le serví... Si no hubiera sido por mí, la gloriosa ciudadela del terror, Naxxramas, nunca habría regresado a Rasganorte.' WHERE `ID`=27161;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말이 너무 길었군... 너는 이 황혼의 인도자와 맞서 싸우려고 세상 먼 곳에서부터 나를 찾아 여기까지 왔다. 너를 실망시키지는 않으마...', `MaleText_loc4`='到此为止吧……你历经万难，终于站到了黄昏使者面前。我不会令你失望的……', `MaleText_loc5`='不過，話說得夠多了...你從世界遙遠的另一頭艱苦奮戰至此，挑戰幽暮使者。我不會失望的...', `MaleText_loc7`='Pero basta de charlas... Han luchado duro y vienen desde los distantes confines de este mundo para enfrentarse al Portador del Ocaso. No los defraudaré...' WHERE `ID`=27162;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 주인께서 날 구원하셨듯이, 내가 너를 구원해 주겠다!', `MaleText_loc4`='让我拯救你吧，就像阿尔萨斯王子拯救我一样！', `MaleText_loc5`='就像吾王拯救我一般，我也要拯救你!', `MaleText_loc7`='¡Del mismo modo que mi señor me salvó a mí, yo te salvaré a ti!' WHERE `ID`=27163;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일어나라, 나의 아이들아! 너희의 주인이 명한다!', `MaleText_loc4`='复活吧，我的侍从！听从主人的命令！', `MaleText_loc5`='出來吧，我的手下!主人命令你們!', `MaleText_loc7`='¡Levantense, mis esbirros! ¡Su maestro se los ordena!' WHERE `ID`=27164;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='역병, 역병, 역병... 어딜 가나 그 얘기뿐이야. 다양한 맛이 없단 말일세!$b$b그건 그렇고 자네, 애완동물이 있지 않나? 물론 데리고 있겠지. 조그만 녀석들 말일세. 내게 그 애완동물을 위한 특별한 혼합물이 있다네. 그걸 사용하면 녀석들이 끔... 아니, 똘똘하고 힘센 녀석으로 변할 걸세.$b$b한번 실험해 보게!', `MaleText_loc4`='样本……样本……除了样本，就不能谈点别的吗？生活应该丰富多彩才对啊！$B$B我说，你的宠物呢？你肯定带着小宠物的吧。喏，这瓶药剂能让它们变得……呃，变得既聪明又强壮！我不骗你啦！$B$B试试吧！', `MaleText_loc5`='荒疫、荒疫、荒疫...這附近我就只聽見這個。我好懷念多樣性!$b$b這裡，這啦，你有寵物，對吧?你當然有囉，當然，小寵物。我有一劑混合物給牠們。這會讓牠們死...呃，我是說思想敏捷又身強體壯，沒錯，沒錯。沒錯，就是身強體壯。$b$b試一下!', `MaleText_loc7`='Añublo, añublo, añublo... eso es lo único que oigo por aquí. ¡Echo de menos la variedad!$B$BToma, toma. Tienes mascotas, ¿verdad? Claro que sí. Claro. Pequeñas mascotas. Tengo una mezcla para ellas. Las convertirá en salv... oh, criaturas fuertes e inteligentes, sí. Sí. Fuertes.$B$B¡Pruébala!' WHERE `ID`=27165;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋습니다, 혼합물을 하나 주세요.', `MaleText_loc4`='好吧，我试试这瓶药剂。', `MaleText_loc5`='好吧，我拿一些你的混合物走。', `MaleText_loc7`='Está bien, me llevaré esa mezcla tuya.', `FemaleText_loc1`='좋습니다, 혼합물을 하나 주세요.', `FemaleText_loc4`='好吧，我试试这瓶药剂。', `FemaleText_loc5`='好吧，我拿一些你的混合物走。', `FemaleText_loc7`='Está bien, me llevaré esa mezcla tuya.' WHERE `ID`=27166;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하게. 불안정해서 금방 효과가 사라져 버린다네. 바로 사용하게! 그리고... 눈이 닿는 범위에서 사용하는 게 좋을 걸세... 그래...', `MaleText_loc4`='要当心哦。它不是很稳定，药效随时可能消失。动作要快！最好……现在就用……', `MaleText_loc5`='小心使用。這東西不很穩定，又很快就會失效。馬上使用它!還有就是...最好盯著它，沒錯...', `MaleText_loc7`='Ten cuidado con ella. Es inestable y pierde su potencia rápidamente. ¡Úsala pronto! Y... mejor donde puedas verla, sí...' WHERE `ID`=27167;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 고양이가 어딜 갔지?', `MaleText_loc4`='那只猫哪儿去了？', `MaleText_loc5`='那隻貓咪去哪了?', `MaleText_loc7`='¿Dónde se ha metido ese gato?' WHERE `ID`=27168;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너덕아?', `MaleText_loc4`='帕帕？', `MaleText_loc5`='派齊?', `MaleText_loc7`='¿Paxy?' WHERE `ID`=27169;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 있었구나, 이 못된 녀석.', `MaleText_loc4`='小坏蛋，你躲在这儿呀。', `MaleText_loc5`='原來在這兒呀，你這個小壞蛋。', `MaleText_loc7`='Ahí estás, traviesillo.' WHERE `ID`=27170;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 짜증 섞인 한숨을 내쉽니다.', `MaleText_loc4`='%s发出痛苦的哀嚎。', `MaleText_loc5`='%s被激怒的嘶嘶叫。', `MaleText_loc7`='%s suspira exasperado.' WHERE `ID`=27171;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너덕이를 새로 하나 만들 때가 됐군.', `MaleText_loc4`='我得再做一只帕帕。', `MaleText_loc5`='該做另外一隻派齊了。', `MaleText_loc7`='Es hora de hacer otro Paxy.' WHERE `ID`=27172;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명예, 용기, 연민, 그리고 정의! 텔잔, 너도 한때는 은빛 여명회의 사제로서 이런 가치를 위해 싸웠지.', `MaleText_loc4`='荣耀、勇气、怜悯、公正！塞尔赞，当年你也曾发誓恪守这些美德，成为一名合格的银色黎明祭司。', `MaleText_loc5`='榮耀、勇氣、熱情與正義!賽爾贊，那些可是你身為銀色黎明的牧師時所奮戰不懈的美德啊。', `MaleText_loc7`='¡Honor, coraje, compasión y justicia! Estas eran las virtudes por las cuales luchabas cuando eras un clérigo de El Alba Argenta, Thel''zan.' WHERE `ID`=27173;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 목숨을 다해 스컬지와 싸울 것을 다짐했었네. 놈들이 로데론에 무슨 짓을 했는지 똑똑히 봤지 않나. 리치 왕은 자네에게서 모든 것을 앗아갔네!', `MaleText_loc4`='你将全副身心都花在对抗天灾军团的大业上。你曾亲眼目睹他们在洛丹伦犯下的罪行。巫妖王夺走了你的一切！', `MaleText_loc5`='你獻出了全部的生命對抗天譴軍，你目睹他們對吾等摯愛的羅德隆所作的惡行，巫妖王將你的一切都奪走了!', `MaleText_loc7`='Dedicaste toda tu vida a luchar contra la Plaga. Viste lo que hicieron a nuestra amada Lordaeron. ¡El Rey Exánime te lo arrebató todo!' WHERE `ID`=27174;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런데, 은빛 여명회가 자랑하던 미덕의 수호자, 이니고 몬토이 신부가 어째서 자신이 그토록 증오하던 존재로 변해버렸을까?', `MaleText_loc4`='那么英尼戈·蒙托尔神父是如何堕落的呢？身为银色黎明的精神领袖，他为什么会变成自己百般唾弃的魔鬼？', `MaleText_loc5`='神父伊尼哥·蒙托，銀色黎明美德的壁壘，為何到頭來卻變成了他原先所深惡痛絕的化身呢?', `MaleText_loc7`='Entonces, ¿cómo se convirtió el padre Iñigo Montoya, bastión de la virtud de El Alba Argenta, en la personificación de lo que más odiaba?' WHERE `ID`=27175;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성기사여, 두 번 다시 그 이름을 입에 담지 못하게 해 주마! 마지막 숨을 쉴지어다!', `MaleText_loc4`='圣骑士，这将是你最后一次提及那个名字！受死吧！', `MaleText_loc5`='這將是你最後一次說出那個名字，聖騎士!嚥下你最後一口氣吧!', `MaleText_loc7`='¡ESTA SERÁ LA ÚLTIMA VEZ QUE PRONUNCIES ESE NOMBRE, PALADÍN! ¡Disfruta de tu último aliento!' WHERE `ID`=27176;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 살아 있는 것을 보니 기쁘군, $n. 오래전에 스톰윈드에서 자네가 날 위해 해준 일을 아직 기억하고 있네.', `MaleText_loc4`='$n，很高兴看到你还活着。还记得很久之前你在暴风城帮我做的事吗？真是记忆犹新啊。', `MaleText_loc5`='看到你還活蹦亂跳真讓我開心，$n。別以為我會忘記你在暴風城對我做了些什麼，啊，真是遙遠的記憶。', `MaleText_loc7`='Me alegra ver que sigues con vida y coleando, $n. No creas que he olvidado lo que hiciste por mí en Ventormenta hace tanto tiempo.' WHERE `ID`=27177;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대영주님이다!', `MaleText_loc4`='公爵！', `MaleText_loc5`='是大領主!', `MaleText_loc7`='¡Es el Alto Señor!', `FemaleText_loc1`='대영주님이다!', `FemaleText_loc4`='公爵！', `FemaleText_loc5`='是大領主!', `FemaleText_loc7`='¡Es el Alto Señor!' WHERE `ID`=27178;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폴드라곤 대영주님!', `MaleText_loc4`='弗塔根公爵！', `MaleText_loc5`='弗塔根大人!', `MaleText_loc7`='¡Lord Fordragón!', `FemaleText_loc1`='폴드라곤 대영주님!', `FemaleText_loc4`='弗塔根公爵！', `FemaleText_loc5`='弗塔根大人!', `FemaleText_loc7`='¡Lord Fordragón!' WHERE `ID`=27179;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스에 승리를!', `MaleText_loc4`='胜利属于联盟！', `MaleText_loc5`='聯盟的勝利!', `MaleText_loc7`='¡Victoria para la Alianza!' WHERE `ID`=27180;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 윈터가드를 구했네! 텔잔이란 더러운 존재가 사라졌으니 나머지 스컬지는 7군단이 손쉽게 처리할 수 있을 걸세. 여기 일을 마치거든 앙그라타르로 와서 보고하게!', `MaleText_loc4`='你拯救了暮冬要塞！塞尔赞的威胁已经解除，残余的天灾士兵就交给第七军团解决吧。等你处理完这里的事务后，就去天谴之门安加萨报到吧！', `MaleText_loc5`='你拯救了溫特加德!賽爾贊這個妖孽被掃除，第七軍團將能輕鬆剷平殘餘的天譴軍。你這裡的工作結束以後向安格拉薩回報!', `MaleText_loc7`='¡Has salvado Hibergarde! Ahora que la inmundicia de Thel''zan ha sido eliminada, la Séptima Legión podrá acabar fácilmente con lo que queda de la Plaga. ¡Cuando acabes aquí, preséntate en Angrathar!' WHERE `ID`=27181;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제, 모두 일어나 전투에 참가하라! 함께 텔잔에게 최후를 안겨 주자!', `MaleText_loc4`='加入战斗吧！让我们了结这一切！', `MaleText_loc5`='那麼，請自由加入戰局吧!讓我們一同為此作個了結!', `MaleText_loc7`='¡Ahora, ve libre y únete a la batalla! ¡Acabemos con esto juntos!' WHERE `ID`=27182;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우와, 멋진 녀석인데요!', `MaleText_loc4`='哇，这匹马不错！', `MaleText_loc5`='哇，真不賴!', `MaleText_loc7`='Oh, ¡este es de los buenos!' WHERE `ID`=27183;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끝내주게 좋은 야생마네요.', `MaleText_loc4`='啧啧，瞧那匹健壮的野马。', `MaleText_loc5`='你得到的真是一匹好馬呀。', `MaleText_loc7`='Ese caballo mesteño que tienes ahí es estupendo.' WHERE `ID`=27184;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런 녀석으로 계속 데려와 주세요.', `MaleText_loc4`='我想看到更多的好马！', `MaleText_loc5`='多帶一些這樣的馬回來!', `MaleText_loc7`='¡Sigue trayendo ejemplares así!' WHERE `ID`=27185;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저도 언젠가 그런 말을 길들일 거예요.', `MaleText_loc4`='我要亲自调教那匹马。', `MaleText_loc5`='我要親自訓練牠。', `MaleText_loc7`='Ese lo entrenaré yo mismo.' WHERE `ID`=27186;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 말에 딱 어울리는 군인 아저씨를 알아요!', `MaleText_loc4`='我会给那匹马选个合适的好主子！', `MaleText_loc5`='我曉得誰是適合這匹馬的士兵!', `MaleText_loc7`='¡Conozco al soldado perfecto para ese caballo!' WHERE `ID`=27187;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='녀석이 블랑쉬가 맘에 드는 모양이에요.', `MaleText_loc4`='他多半喜欢老马布兰契。', `MaleText_loc5`='我想他喜歡老馬布蘭契。', `MaleText_loc7`='Creo que le gusta la vieja Blanchy.' WHERE `ID`=27188;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고향인 서부 몰락지대에 생긴 문제를 해결하려고 전선을 떠난 적이 있지. 참 아득하게 느껴지는군. 이제 데피아즈단을 걱정할 필요가 없다는 게 얼마나 다행인지 모르겠네.$B$B우린 지금 고향 서부 몰락지대에서 멀리 떨어진 곳까지 와 있네. 하지만 우리가 이 전쟁에서 이기지 못한다면 우리가 돌아갈 고향 따위는 없어질 걸세.', `MaleText_loc4`='当我得知西部荒野发生骚乱时，便毅然告别战友，返回家乡处理当地的事务。算算也是陈年旧事啦。感谢圣光，迪菲亚兄弟会的威胁得以解除。$B$B如今我们再次出征，来到偏远的极寒之地。如果我们嬴不了这场战争，或许就再也没有机会回家了。', `MaleText_loc5`='我曾經離開了戰場，返回西部荒野的老家，就為了處理一些麻煩。那簡直就像是上輩子的事情了。感謝聖光，迪菲亞不再造成威脅。$B$B我們遠離家園，要是我們打不贏這場戰爭，那就沒有西部荒野可以回去了。', `MaleText_loc7`='Una vez abandoné una guerra para ocuparme de los problemas de mi hogar, en los Páramos de Poniente. Parece que fue hace siglos. Gracias a la Luz que los Defias ya no suponen una amenaza.$B$bAhora mismo estamos muy lejos de nuestro hogar, pero si no ganamos esta batalla, no tendremos donde volver.' WHERE `ID`=27189;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='페렐리 씨, 지난 몇 주 동안 검은 로브를 입은 자들이 수상한 행동을 하는 걸 보신 적이 있습니까?', `MaleText_loc4`='皮雷利先生，最近那些穿着暗色袍子的家伙有没有什么可疑的行动？', `MaleText_loc5`='皮雷利先生，這數週之間，你是否有看過任何披著黑色長袍的男子從事著可疑的行為呢?', `MaleText_loc7`='Sr. Perelli, ¿ha visto algún tipo de actividad sospechosa llevada a cabo por hombres vestidos con togas oscuras en las últimas semanas?' WHERE `ID`=27190;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='페렐레 씨, 언데드의 징후를 목격한 적이 있습니까? 뭐든 정보를 제공해 주시면 아서스 왕자님께서 기뻐하실 겁니다.', `MaleText_loc4`='皮雷利先生，你在附近见过亡灵吗？阿尔萨斯王子欢迎你提供任何线索。', `MaleText_loc5`='皮雷利先生，你有看到任何不死族的徵兆嗎?阿薩斯王子將非常感激你所提供的任何線索。', `MaleText_loc7`='Sr. Perelli, ¿ha visto algún rastro de no-muertos? El príncipe Arthas apreciará cualquier información que pueda proporcionar.' WHERE `ID`=27191;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='페렐리 씨, 당신은 물건을 들여오려고 여행을 많이 하시는 걸로 압니다. 스컬지에 대한 소문이나 정보를 들어본 적이 있으십니까?', `MaleText_loc4`='皮雷利先生，象你这样的旅行商人肯定见多识广。你应该对天灾军团的传言有所耳闻吧？', `MaleText_loc5`='皮雷利先生，我知道你遊歷各處兜售你的貨品，相信你也聽了不少關於天譴軍的傳言與消息?', `MaleText_loc7`='Sr. Perelli, sé que viajas bastante y transportas tus bienes en halcones. No hay duda de que habrás oído rumores o información sobre la Plaga.' WHERE `ID`=27192;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가까운 시일 내에 이 지역을 떠날 계획이 있으십니까?', `MaleText_loc4`='如果我继续问下去，你是不是打算扭头就走？', `MaleText_loc5`='如果我們問更多的問題，你是否會計畫離開這個區域了呢?', `MaleText_loc7`='¿Tienes planeado no estar cerca por si tenemos más preguntas?' WHERE `ID`=27193;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='페렐리 씨, 당신 말고도 이 상품을 감독하는 사람이 있습니까?', `MaleText_loc4`='皮雷利先生，你一直负责监管这些货物吗？', `MaleText_loc5`='皮雷利先生，請問這些貨品是否一直在你的監督之下呢?', `MaleText_loc7`='Sr. Perelli, ¿tiene estos bienes bajo vigilancia en todo momento?' WHERE `ID`=27194;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혹시 언덕마루산 거북 수프 통조림 있습니까?', `MaleText_loc4`='你不会还带着希尔斯布莱德丘陵的罐装海龟汤吧？', `MaleText_loc5`='你該不會恰巧有些從希爾斯布萊德運來的罐裝海龜湯吧，有嗎?', `MaleText_loc7`='No habrás enlatado sopa de tortuga de Trabalomas, ¿verdad?' WHERE `ID`=27195;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서리한 동굴의 벽이 심하게 흔들립니다.', `MaleText_loc4`='霜之哀伤洞穴剧烈地摇晃起来。', `MaleText_loc5`='霜之哀傷洞窟的岩壁搖晃震動著。', `MaleText_loc7`='Las paredes de la Caverna Agonía de Escarcha tiemblan y se sacuden.', `FemaleText_loc1`='서리한 동굴의 벽이 심하게 흔들립니다.', `FemaleText_loc4`='霜之哀伤洞穴剧烈地摇晃起来。', `FemaleText_loc5`='霜之哀傷洞窟的岩壁搖晃震動著。', `FemaleText_loc7`='Las paredes de la Caverna Agonía de Escarcha tiemblan y se sacuden.' WHERE `ID`=27196;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='페렐리 씨, 여행을 하다가 스컬지 활동이나 뭔가 은밀한 공작 같은 걸 목격하시면 가장 가까운 로데론 병사에게 알려주시기 바랍니다.', `MaleText_loc4`='皮雷利先生，如果你在旅途中发现天灾军团的活动迹象或是任何可疑的行为，请立即向洛丹伦士兵汇报。', `MaleText_loc5`='皮雷利先生，要是在旅途的過程中，你剛好知道任何天譴軍活動的徵兆，或是可疑的行為，請讓羅德隆最近的士兵知道。', `MaleText_loc7`='Sr. Perelli, si encuentras cualquier indicio de actividad de la Plaga o de asuntos oscuros durante tus viajes, informa enseguida al soldado de Lordaeron más cercano.' WHERE `ID`=27197;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='없습니다, 하사관님.', `MaleText_loc4`='没有，中士。', `MaleText_loc5`='不，中士。', `MaleText_loc7`='No, Sargento.' WHERE `ID`=27198;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='없습니다.', `MaleText_loc4`='没有，长官。', `MaleText_loc5`='不，長官。', `MaleText_loc7`='No, señor.' WHERE `ID`=27199;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='없어요.', `MaleText_loc4`='没有。', `MaleText_loc5`='沒。', `MaleText_loc7`='Nop.' WHERE `ID`=27200;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 하사관님.', `MaleText_loc4`='是，长官。', `MaleText_loc5`='是的，長官。', `MaleText_loc7`='Sí, señor.' WHERE `ID`=27201;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 모르건 하사관님.', `MaleText_loc4`='是，摩利根中士。', `MaleText_loc5`='是的，莫里根中士。', `MaleText_loc7`='Sí, sargento Morigan.' WHERE `ID`=27202;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론입니다.', `MaleText_loc4`='当然。', `MaleText_loc5`='一點也沒錯。', `MaleText_loc7`='Por supuesto.' WHERE `ID`=27203;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싱크의 벌목기가 부서져, 큰 소리를 내면서 멈춥니다.', `MaleText_loc4`='辛克的伐木机发生故障，很快停止了运转。', `MaleText_loc5`='辛克的伐木機四分五裂的停了下來。', `MaleText_loc7`='La trituradora de Xink se colapsa y petardea hasta detenerse.' WHERE `ID`=27204;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 상품을 좀 살펴봐도 상관없으시겠지요?', `MaleText_loc4`='我想检查一下你的货物，看看有没有动过什么手脚，你不介意吧？', `MaleText_loc5`='你不會介意我在你的貨物中檢查被調包的徵兆吧，好嗎?', `MaleText_loc7`='¿No te importa que eche un ojo a tu mercancía por si ha sido manipulada?' WHERE `ID`=27205;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐, 이게 뭐지? 당신 뭔가 숨기고 있었군!', `MaleText_loc4`='嗯？这是怎么回事？皮雷利，你竟敢欺骗我！', `MaleText_loc5`='等等，這是什麼?皮雷利，你一直在隱瞞著我!', `MaleText_loc7`='Un momento, ¿qué es esto? ¡Me has mentido, Perelli!' WHERE `ID`=27206;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보십시오, 무라딘. 우리의 구원, 서리한입니다.', `MaleText_loc4`='看，穆拉丁，我们最后的希望，霜之哀伤。', `MaleText_loc5`='看哪，穆拉丁，我們的救贖，霜之哀傷。', `MaleText_loc7`='Mira, Muradin, nuestra salvación: Agonía de Escarcha.' WHERE `ID`=27207;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 말씀이십니까, 하사관님!', `MaleText_loc4`='我不懂你在说什么，中士！', `MaleText_loc5`='你在說什麼，中士!', `MaleText_loc7`='¡De qué habla, Sargento!' WHERE `ID`=27208;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기다리게. 제단에 뭔가 새겨져 있군. 이건 경고일세. "이 검을 집는 자는 무한한 힘을 얻게 될 것이다. 그러나 검이 육신을 베듯이, 이 힘은 영혼에 상처를 남기리라..." 아아, 왜 몰랐을까! 이 검은 저주받았네! 어서 여기서 나가세!', `MaleText_loc4`='等等，伙计。基座上有一行铭文，好像是警告。上面说，“持此剑者将获永恒之力。此剑喋血以展锋锐，此力噬灵以显威能”。噢，我早该知道的。这把剑被诅咒了。我们快走吧，别管它了！', `MaleText_loc5`='等等，小子。臺子上刻著些東西，這是個警告，上面寫:「凡持此劍者，將掌握永恆之力。此力必將蝕魂，一如切裂血肉。」噢，我早該知道，這把劍被詛咒了!我們快點離開這吧!', `MaleText_loc7`='Espera, muchacho. Hay una inscripción en la tarima. Una advertencia. Dice: “Quien empuñe esta espada ejercerá poder eterno. Tal como la espada desgarra el cuerpo, el poder marcará el espíritu.” ¡Debí saberlo! ¡La espada está maldita! ¡Salgamos de aquí!' WHERE `ID`=27209;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 오염된 식량이 있는지 조사하던 중이었습니다. 이 수상한 곡물을 압수하겠습니다, 페렐리 씨. 아서스 왕자님께서 이걸 확인하시는 동안 얌전히 있는 게 좋을 겁니다.', `MaleText_loc4`='我要没收这批可疑的谷物，皮雷利。我们奉命寻找被动过手脚的粮食，阿尔萨斯王子会亲自介入此事，你最好合作一点，呆在原地哪儿都别去。', `MaleText_loc5`='皮雷利，我要把這些可疑的穀物沒收。我們正在尋找被調包的食物的線索，為了你自己著想，你最好待在這裡，等阿薩斯王子檢查過。', `MaleText_loc7`='Voy a confiscar este grano sospechoso, Perelli. Buscábamos comida manipulada y será mejor que no hagas tonterías mientras el príncipe Arthas comprueba esto.' WHERE `ID`=27210;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왕국을 지킬 수 있다면 저주 따윈 상관없습니다.', `MaleText_loc4`='为了拯救我的祖国，再恶毒的诅咒我也承受。', `MaleText_loc5`='為了拯救我的家園，我樂意承受任何詛咒。', `MaleText_loc7`='Cargaría cualquier maldición a fin de salvar mi tierra.' WHERE `ID`=27211;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오오... 그냥 놔두게, 아서스. 이번 일은 잊고, 부하들과 돌아가게!', `MaleText_loc4`='别去动它，阿尔萨斯。忘了它吧，带你的弟兄们回家。', `MaleText_loc5`='算了吧，阿薩斯。忘了這件事，帶領你的人回家吧。', `MaleText_loc7`='Déjala, Arthas. Olvida este asunto y lleva tus hombres a casa.' WHERE `ID`=27212;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='믿어 주세요, 전 모르는 일입니다!', `MaleText_loc4`='你要相信我，我是无辜的！', `MaleText_loc5`='你一定要相信我，我是無辜的!', `MaleText_loc7`='Tienes que creerme, ¡soy inocente!' WHERE `ID`=27213;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부하들이 무엇이길래요! 그 무엇도 내 복수를 막을 순 없습니다! 오랜 친구인 당신조차도요...', `MaleText_loc4`='该死！无论是谁，都无法阻止我的复仇，老朋友。你，也不行。', `MaleText_loc5`='該死!無論是誰，都不能阻止我的復仇，老朋友。就連你也不行。', `MaleText_loc7`='¡Al diablo con los hombres! Nada evitará mi venganza, viejo amigo. Ni siquiera tú.' WHERE `ID`=27214;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 여기를 떠도는 영혼들을 부르겠습니다. 백성을 구할 수만 있다면, 나는 아무것도 마다하지 않을 겁니다.', `MaleText_loc4`='现在，我召唤镇守此地的魂灵。我愿付出任何代价，做出任何牺牲，只要你能协助我拯救祖国的人民。', `MaleText_loc5`='現在，我呼喚此地的靈魂。只要你能協助我拯救我的人民，我願付出任何事物和代價。', `MaleText_loc7`='Invoco a los espíritus de este lugar. Daré cualquier cosa o pagaré cualquier precio, si tan sólo me ayudan a salvar a los míos.' WHERE `ID`=27215;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그건 우리가 조사할 겁니다, 페렐리 씨. 조사해 보면 알겠지요.', `MaleText_loc4`='皮雷利，我们会继续调查此事的。走着瞧吧。', `MaleText_loc5`='等著瞧吧，皮雷利，等著瞧吧。', `MaleText_loc7`='Ya veremos, Perelli. Ya veremos.' WHERE `ID`=27216;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으으, 머리야... 여... 여기는 어디지?', `MaleText_loc4`='啊……头疼……我……我在哪儿？', `MaleText_loc5`='喔，我的頭...這...這是哪?', `MaleText_loc7`='Ah, mi cabeza... Dó... ¿Dónde estoy?' WHERE `ID`=27217;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나... 나는 누구지?', `MaleText_loc4`='我……我是谁？', `MaleText_loc5`='我...我是誰?', `MaleText_loc7`='¿Quién... quién soy?' WHERE `ID`=27218;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어디 보자, 엊저녁엔 닭고기를 먹었지.', `FemaleText_loc4`='让我想想，昨天晚上我们吃了鸡肉。', `FemaleText_loc5`='我想想，我們昨晚吃了雞肉。', `FemaleText_loc7`='Veamos, anoche tomamos pollo.' WHERE `ID`=27219;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='말린 베이컨도 잔뜩 있어. 그이가 아침에 조금 먹었지...', `FemaleText_loc4`='我还有好些熏肉，不过早上他吃了一些。', `FemaleText_loc5`='我有不少治癒的培根，他吃了一些當早餐。', `FemaleText_loc7`='Tengo bastante panceta curada, pero él ha tomado un poco para desayunar.' WHERE `ID`=27220;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그이가 빨리 나을 수 있게 맛있는 걸 좀 준비해야겠어... 지난주부터 계속 골골거리고 있으니, 원.', `FemaleText_loc4`='我要为他准备一些健康的食物，上周他病得可厉害啦，至今还没有康复呢。', `FemaleText_loc5`='我需要做一些健康的東西給他吃。自從上週開始，他就一直沒法從疾病中康復。', `FemaleText_loc7`='Tengo que hacer algo saludable para él, aún no se ha recuperado de aquella enfermedad de la semana pasada.' WHERE `ID`=27221;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='딸기! 아, 아직 철이 아니지...', `FemaleText_loc4`='草莓！不行，现在不是季节。', `FemaleText_loc5`='草莓!噢，等等，它們過季了。', `FemaleText_loc7`='¡Fresas! Oh, espera, no estamos en temporada.' WHERE `ID`=27222;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 빵이나 새로 구워 줘야겠군! 마사한테 가서 밀가루 좀 얻어와야겠네!', `FemaleText_loc4`='啊，我烤些新鲜的面包吧！我找马尔萨要面粉去。', `FemaleText_loc5`='啊，我做幾塊新鮮的麵包給他吧!我得從瑪莎那兒拿些麵粉!', `FemaleText_loc7`='¡Ah, le haré un poco de pan fresco! ¡Necesito que Martha me dé un poco de harina!' WHERE `ID`=27223;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마사, 빵 구울 밀가루가 다 떨어졌어요. 얼마 전에 들여온 곡식 좀 남았나요?', `FemaleText_loc4`='马尔萨，我的面粉用光啦。最近不是刚运来一批粮食吗，你能借我一些面粉吗？', `FemaleText_loc5`='瑪莎，我做麵包用的麵粉用完了。你該不會剛好有最近運來的穀物吧，有嗎?', `FemaleText_loc7`='Martha, no me queda harina para hacer pan. ¿No tendrás algo de grano de ese envío que ha llegado hace poco?' WHERE `ID`=27224;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만 갑시다!', `MaleText_loc4`='我们出发吧！', `MaleText_loc5`='我們走吧!', `MaleText_loc7`='¡Allá vamos!', `FemaleText_loc1`='그만 갑시다!', `FemaleText_loc4`='我们出发吧！', `FemaleText_loc5`='我們走吧!', `FemaleText_loc7`='¡Allá vamos!' WHERE `ID`=27225;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='집중하십시오! 우린 지금 브리쿨과 호드들이 온 동네 득실거리는 곳으로 들어가는 중이란 말입니다!', `MaleText_loc4`='小心！我们要去的地方非常危险，那里到处都是维库人和部落！', `MaleText_loc5`='朋友，專心點!我們正要進入警戒區域，這裡到處都是維酷人和部落!', `MaleText_loc7`='¡Presta atención, colega! ¡Nos estamos adentrando en territorio hostil lleno de vrykuls y miembros de la Horda por todas partes!', `FemaleText_loc1`='집중하세요! 우린 지금 브리쿨과 호드들이 온 동네 득실거리는 곳으로 들어가는 중이란 말이에요!', `FemaleText_loc4`='小心！我们要去的地方非常危险，那里到处都是维库人和部落！', `FemaleText_loc5`='朋友，專心點!我們正要進入警戒區域，這裡到處都是維酷人和部落!', `FemaleText_loc7`='¡Presta atención, colega! ¡Nos estamos adentrando en territorio hostil lleno de vrykuls y miembros de la Horda por todas partes!' WHERE `ID`=27226;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주위를 잘 살펴 두십시오. 내가 택한 길은 당신이 발가드로 돌아갈 때 따라 수 있는 길이니 말입니다.', `MaleText_loc4`='留意周围的环境。记住这条路线，以后你可以原路返回瓦加德。', `MaleText_loc5`='仔細注意你的周遭環境。我走的這條路線正同樣帶你走回瓦爾加德。', `MaleText_loc7`='Presta atención a los alrededores. La ruta que estoy tomando es la misma ruta que puedes usar para volver a Valgarde.', `FemaleText_loc1`='주위를 잘 살펴 두세요. 내가 택한 길은 당신이 발가드로 돌아갈 때 따라 수 있는 길이니까요.', `FemaleText_loc4`='留意周围的环境。记住这条路线，以后你可以原路返回瓦加德。', `FemaleText_loc5`='仔細注意你的周遭環境。我走的這條路線正同樣帶你走回瓦爾加德。', `FemaleText_loc7`='Presta atención a los alrededores. La ruta que estoy tomando es la misma ruta que puedes usar para volver a Valgarde.' WHERE `ID`=27227;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 있습니다! 아이스해머는 저 브리쿨 건물 내에 있습니다! 본때를 보여주십시오!', `MaleText_loc4`='我们到啦！冰锤就在那座维库人建筑物中！将他们统统送进地狱吧！', `MaleText_loc5`='上吧，朋友!冰錘中尉正在維酷人的建築物裡面!給他們好看!', `MaleText_loc7`='¡Animo, colega! ¡Martillo de Hielo está dentro de ese edificio vrykul! ¡Dales caña!', `FemaleText_loc1`='여기 있습니다! 아이스해머는 저 브리쿨 건물 내에 있습니다! 본때를 보여주십시오!', `FemaleText_loc4`='我们到啦！冰锤就在那座维库人建筑物中！将他们统统送进地狱吧！', `FemaleText_loc5`='上吧，朋友!冰錘中尉正在維酷人的建築物裡面!給他們好看!', `FemaleText_loc7`='¡Animo, colega! ¡Martillo de Hielo está dentro de ese edificio vrykul! ¡Dales caña!' WHERE `ID`=27228;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고마워요, 마사! 신세를 지네요.', `FemaleText_loc4`='马尔萨，谢谢你！我欠你一份情。', `FemaleText_loc5`='謝謝，瑪莎!我欠你一命。', `FemaleText_loc7`='¡Gracias, Martha! Te debo una.' WHERE `ID`=27229;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오, 이런.', `FemaleText_loc4`='啊，天哪。', `FemaleText_loc5`='喔，天吶。', `FemaleText_loc7`='Oh, cielos.' WHERE `ID`=27230;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마사, 곡식이 좀 이상해요! 왕자님의 병사들이 이걸 찾고 있던데요. 가서 누굴 좀 데려와야겠어요.', `FemaleText_loc4`='马尔萨，面粉有问题！王子正在寻找被动过手脚的粮食。我这就向他的士兵汇报。', `FemaleText_loc5`='瑪莎，這些穀物不大對勁!王子的士兵們正在找這些穀物，我要交給他們。', `FemaleText_loc7`='¡Martha, a este grano le pasa algo raro! Algunos de los soldados del Príncipe lo estaban buscando. Voy a buscar a uno.' WHERE `ID`=27231;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, 제나. 물론 빌려 드릴게요. 얼마든지 가져가세요.', `FemaleText_loc4`='嗨，珍娜。没问题。想要多少都可以。', `FemaleText_loc5`='喔，你好哇，潔娜。你當然可以借一點穀物走，自個兒拿吧。', `FemaleText_loc7`='Oh, hola, Jena. Claro que puedes tomar prestado algo de grano. Cógelo.' WHERE `ID`=27232;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전쟁마법사들이 이리로 오는 길이니 곧 도착할 겁니다.$b$b그들이 오면 내게 말해주십시오.', `MaleText_loc4`='我手下的战斗法师很快就会回来。$B$B等他们到了之后再来找我谈谈吧。', `MaleText_loc5`='我的戰爭法師就要回來了，不一會兒就會抵達。$b$b當他們回來之後，再和我交談。', `MaleText_loc7`='Mis magos de guerra están volando de vuelta. Llegarán de un momento a otro.$b$bHabla conmigo de nuevo cuando hayan vuelto.' WHERE `ID`=27233;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미안합니다, $r. 난 지금 공무 집행 중이라 다른 데 신경을 쓸 겨를이 없군요.$b$b그럼 실례하겠습니다.', `MaleText_loc4`='抱歉，$r。我还有正事要办，不能耽搁。$B$B不好意思。', `MaleText_loc5`='抱歉，$r，我有公務在身無法分心。$b$b很抱歉。', `MaleText_loc7`='Perdona, $r, pero estoy de viaje oficial y no puedo distraerme.$b$bDiscúlpame.' WHERE `ID`=27234;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어머나...', `FemaleText_loc4`='天哪。', `FemaleText_loc5`='噢，糟糕。', `FemaleText_loc7`='Oh, no.' WHERE `ID`=27235;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭풍우가 몰아닥칠 것 같구나, 복슬아...', `MaleText_loc4`='暴风雨就要来了，脏脏……', `MaleText_loc5`='史克拉菲，看樣子暴風雨就要來了...', `MaleText_loc7`='Parece que va a haber tormenta, Desaliñado...' WHERE `ID`=27236;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 으르렁댑니다...', `MaleText_loc4`='%s开始嘟囔起来……', `MaleText_loc5`='%s開始嚎叫...', `MaleText_loc7`='%s comienza a gruñir...' WHERE `ID`=27237;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 그러니?', `MaleText_loc4`='怎么啦？', `MaleText_loc5`='怎麼了，狗兒?', `MaleText_loc7`='¿Qué pasa, colega?' WHERE `ID`=27238;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕, $n. 경계할 것 없어. 나야... 미래에서 온... 너라고. 널 도우러 왔지.', `MaleText_loc4`='嗨，$n。别害怕。我……就是来自未来的……你。我是来帮你的。', `MaleText_loc5`='喂喂，$n，別被嚇著了，是我...就是你...來自未來。我來這幫忙的。', `MaleText_loc7`='Hola, $n, no te asustes. Soy yo... tú... del futuro. He venido a ayudar.', `FemaleText_loc1`='안녕, $n. 경계할 것 없어. 나야... 미래에서 온... 너라고. 널 도우러 온 거야.', `FemaleText_loc4`='嗨，$n。别害怕。我……就是来自未来的……你。我是来帮你的。', `FemaleText_loc5`='喂喂，$n，別被嚇著了，是我...就是你...來自未來。我來這幫忙的。', `FemaleText_loc7`='Hola, $n, no te asustes. Soy yo... tú... del futuro. He venido a ayudar.' WHERE `ID`=27239;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 찾은 거냐?', `MaleText_loc4`='你发现了什么？', `MaleText_loc5`='小子，你發現了什麼?', `MaleText_loc7`='¿Qué has encontrado, chico?' WHERE `ID`=27240;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거 큰일이구나, 복슬아. 여기서 집을 지키고 있어라. 난 병사를 찾아볼 테니.', `MaleText_loc4`='事情不妙，脏脏。你乖乖地待在家里，我出去找士兵谈谈。', `MaleText_loc5`='不要這樣，史克拉菲。待這護著房子，我得去找一個士兵。', `MaleText_loc7`='Esto no tiene buena pinta, Desaliñado. Quédate aquí y cuida de la casa, tengo que encontrar a un soldado.' WHERE `ID`=27241;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무한의 용군단이 %s|1을;를; 파괴했습니다!', `MaleText_loc4`='永恒之龙摧毁了%s！', `MaleText_loc5`='恆龍軍團已經摧毀了%s!', `MaleText_loc7`='¡El Vuelo Infinito ha destruido el %s!' WHERE `ID`=27242;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 안개를 어떻게 뚫고 나가죠?', `FemaleText_loc4`='我们要如何穿越迷雾？', `FemaleText_loc5`='我們要怎麼克服這陣大霧?', `FemaleText_loc7`='¿Cómo superaremos la niebla?' WHERE `ID`=27243;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저도 다른 이들처럼 죽는 줄 알았어요!', `FemaleText_loc4`='我还以为我会落得和他们一样的下场！', `FemaleText_loc5`='我真的覺得我會跟其他人一樣死去!', `FemaleText_loc7`='¡Estaba segura de que moriría como todos los demás!' WHERE `ID`=27244;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저게 뭐죠! 지금 보셨어요?', `FemaleText_loc4`='那是什么！你看到了吗？', `FemaleText_loc5`='那是什麼?你看見了嗎?', `FemaleText_loc7`='¿Qué ha sido eso? ¿Lo has visto?' WHERE `ID`=27245;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='타운카라고 들어보셨어요? 타우렌의 친척뻘인 모양이에요. 상상이 가세요?', `FemaleText_loc4`='你听说过牦牛人吗？他们应该和牛头人有亲缘关系吧。你怎么看？', `FemaleText_loc5`='你有聽說過坦卡族嗎?他們好像跟牛頭人有些血緣關係。你能想像這種生物嗎?', `FemaleText_loc7`='¿Has oído hablar de los taunka? Se supone que están relacionados de algún modo con los tauren. ¿Te lo puedes imaginar?' WHERE `ID`=27246;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 일은 할 만큼 했어. 이제 여관에서 쉬면서 수다나 떨어야겠군.', `MaleText_loc4`='事情做得差不多啦。我要回旅店吃点东西，然后好好睡一觉。', `MaleText_loc5`='好，目前的工作夠了。是該在旅店裡面喘口氣稍微聊一聊了。', `MaleText_loc7`='Vale, basta de trabajo por el momento. Es hora de tomar unos refrescos y charlar un rato en la posada.' WHERE `ID`=27247;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐, 이게 무슨 냄새지?', `MaleText_loc4`='嗯，什么气味？', `MaleText_loc5`='等等，這是什麼味道?', `MaleText_loc7`='Espera, ¿qué es ese olor?' WHERE `ID`=27248;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 아닐 거야. 사흘 전에 목욕했는걸!', `MaleText_loc4`='不对呀，我3天前才洗过澡！', `MaleText_loc5`='不可能是我，我3天前才洗過澡!', `MaleText_loc7`='No puedo ser yo. ¡Me bañé hace tres días!' WHERE `ID`=27249;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 다행이군. 여기 있는 곡식에서 나는 냄새잖아.', `MaleText_loc4`='虚惊一场……只是粮食的气味。', `MaleText_loc5`='喔，找到了。是這裡的穀物。', `MaleText_loc7`='Oh, por los pelos. Solo es el grano.' WHERE `ID`=27250;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정신 바짝 차려... 그들이 오고 있으니까. 힘이 닿는 데까지 널 도와주지. 놈들이 모래시계에 가까이 다가오지 못하게 막자고!', `MaleText_loc4`='瞧……他们来了。我会尽全力帮助你。别让他们靠近沙漏！', `MaleText_loc5`='抬起頭...他們來了。我會盡量幫忙。讓我們把他們擋在沙漏之外!', `MaleText_loc7`='Atención... aquí vienen. Ayudaré tanto como pueda. ¡Mantengámoslos alejados del reloj de arena!', `FemaleText_loc1`='정신 바짝 차려... 그들이 오고 있어. 힘이 닿는 데까지 널 도울게. 놈들이 모래시계에 가까이 다가오지 못하게 막아야 해!', `FemaleText_loc4`='瞧……他们来了。我会尽全力帮助你。别让他们靠近沙漏！', `FemaleText_loc5`='抬起頭...他們來了。我會盡量幫忙。讓我們把他們擋在沙漏之外!', `FemaleText_loc7`='Atención... aquí vienen. Ayudaré tanto como pueda. ¡Mantengámoslos alejados del reloj de arena!' WHERE `ID`=27251;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐, 곡식에서 이런 냄새가 나면 안 되지! 경비병을 찾으러 가야겠군.', `MaleText_loc4`='奇怪，粮食不应该有这种气味！我最好找个卫兵来瞧瞧。', `MaleText_loc5`='等一下。穀物不應該會發出這種「味道」!我最好去找守衛。', `MaleText_loc7`='Espera un segundo. ¡Se supone que el grano no debería oler ASÍ! Será mejor que vaya a buscar a un guardia.' WHERE `ID`=27252;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안돌할에 있을 때 마차 자물쇠를 단단히 채웠어야 했는데.', `MaleText_loc4`='在安多哈尔的时候，我就该好好地看着货车，也不至于捅这漏子了。', `MaleText_loc5`='我就知道我應該把馬車鎖得比在安多哈爾更牢一點。', `MaleText_loc7`='Sabía que tenía que haber cerrado mejor la cerradura del vagón cuando estaba en Andorhal.' WHERE `ID`=27253;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 곡식은 정말 골칫거리야!', `MaleText_loc4`='运粮食也能惹上麻烦事！', `MaleText_loc5`='穀物運送根本沒好事!', `MaleText_loc7`='¡Este envío de grano no nos ha dado más que problemas!' WHERE `ID`=27254;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이것 때문에 정시 퇴근이 날아가게 생겼잖아!', `MaleText_loc4`='不知道会因此耽搁多少时间呢！', `MaleText_loc5`='我要為此損失我的準時獎賞了!', `MaleText_loc7`='¡Voy a perder mi bonificación de puntualidad por esto!' WHERE `ID`=27255;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='게다가 원래 오늘은 쉬는 날이었다고!', `MaleText_loc4`='我就不该来这里！', `MaleText_loc5`='我今天甚至不應該在這裡!', `MaleText_loc7`='¡Ni siquiera debería estar aquí hoy!' WHERE `ID`=27256;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐, 할 수 없지. 마차에 다시 실어야지...', `MaleText_loc4`='呃，我应该把粮食重新搬上货车。', `MaleText_loc5`='好吧，我猜我得把所有東西裝回貨車上。', `MaleText_loc7`='Bueno, supongo que debería volver a cargar todo en la vagoneta.' WHERE `ID`=27257;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 젠장! 마차는 망가지고, 말 편자는 사라지고, 이제 짐까지 상하다니!', `MaleText_loc4`='不是吧，我怎么这么倒霉！货车坏了，马蹄铁丢了一只，粮食也出了问题！', `MaleText_loc5`='喔，拜託!我的貨車壞了，我的馬掉了蹄鐵，現在居然貨物也腐敗了!', `MaleText_loc7`='¡Oh, vamos! Se me ha estropeado la vagoneta, mi caballo ha perdido una herradura ¡y ahora la mercancía se me estropea!' WHERE `ID`=27258;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='관리를 찾아가 봐야겠군. 어쩌면, 이건 역병이라서 우린 다 죽은 목숨이니 이 지긋지긋한 세상과도 안녕이라고 말해줄지도 모르지.', `MaleText_loc4`='看来我得找卫生鉴定专家问问。如果我够“幸运”的话，他们就会告诉我说这是强效药剂……那样我们就都完蛋了！', `MaleText_loc5`='我猜我得去找有關當局。如果我走狗運的話，他們會告訴我這是瘟疫，而我們全都得死。', `MaleText_loc7`='Supongo que debería buscar a las autoridades. Con un poco de suerte, me dirán que es la peste y que vamos a morir todos.' WHERE `ID`=27259;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 바닥을 긁습니다.', `MaleText_loc4`='%s抓着地面。', `MaleText_loc5`='%s的爪子著地了。', `MaleText_loc7`='El %s araña la tierra.' WHERE `ID`=27260;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빌어먹을. 너는 우리의 유일한 희망이야. 살아남아!', `MaleText_loc4`='该死！你是我们唯一的希望。别死啊！', `MaleText_loc5`='喔，該死。你是我們唯一的希望。求生存!', `MaleText_loc7`='Oh, cielos. Eres nuestra única esperanza. ¡Sobrevive!', `FemaleText_loc1`='오, 이런. 넌 우리의 유일한 희망이야. 살아남아야 해!', `FemaleText_loc4`='该死！你是我们唯一的希望。别死啊！', `FemaleText_loc5`='喔，該死。你是我們唯一的希望。求生存!', `FemaleText_loc7`='Oh, cielos. Eres nuestra única esperanza. ¡Sobrevive!' WHERE `ID`=27261;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불안정한 멀구울이 폭발하려고 합니다!', `MaleText_loc4`='不稳定的行尸鱼人要爆炸了！', `MaleText_loc5`='不穩定的屍化魚人即將要爆炸!', `MaleText_loc7`='¡El Mur''crófago inestable está a punto de explotar!' WHERE `ID`=27262;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로데론의 모든 병사는 즉시 스트라솔름 입구로 집결하라. 그리고 아서스 왕자님의 명령을 기다려라.', `MaleText_loc4`='洛丹伦的士兵都听着！立即前往斯坦索姆入口处集合，等待阿尔萨斯王子的进一步指示。', `MaleText_loc5`='所有羅德隆的士兵應該立刻往斯坦索姆的入口集合，等待阿薩斯王子的進一步命令。', `MaleText_loc7`='Todos los soldados de Lordaeron deben presentarse inmediatamente en la entrada de Stratholme y esperar las órdenes del príncipe Arthas.' WHERE `ID`=27263;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 한 번 말한다. 로데론의 모든 병사는 즉시 스트라솔름 입구로 집결하라. 그리고 아서스 왕자님의 명령을 기다려라.', `MaleText_loc4`='再次通告！洛丹伦的士兵立即前往斯坦索姆入口处集合，等待阿尔萨斯王子的进一步指示。', `MaleText_loc5`='再一次，所有羅德隆的士兵應該立刻往斯坦索姆的入口集合，等待阿薩斯王子的進一步命令。', `MaleText_loc7`='Una vez más, todos los soldados de Lordaeron deben presentarse inmediatamente en la entrada de Stratholme y esperar las órdenes del príncipe Arthas.' WHERE `ID`=27264;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘했어요! 이제 스트라솔름의 곡식이 오염됐다는 걸 알았으니 아서스는 마을을 파괴할 거예요.$B$B하지만 아직도 뭔가 잘못돼 가고 있어요. 이 시간대에 우리 이외의 다른 존재가 있음이 느껴지는군요. 무한의 용군단이 여기 어딘가 있다는 뜻이겠지요.', `FemaleText_loc4`='很好！阿尔萨斯已经得知斯坦索姆中有被瘟疫污染的粮食，正准备展开清洗行动。$B$B但是我总觉得哪里不对劲，肯定有别的生物侵入了这条时间流，恐怕永恒之龙就在我们附近。', `FemaleText_loc5`='做得漂亮!阿薩斯已經知道斯坦索姆中的染疫穀物，即將要展開肅清行動了。$B$B但還是有些事情不對勁。我感覺得到在這條時間線中還有我們以外的外來存在，這表示恆龍軍團也一定在這裡的某處。', `FemaleText_loc7`='¡Buen trabajo! Ahora Arthas está al corriente del grano apestado de Stratholme y está a punto de comenzar la matanza.$B$BPero algo no va bien. Siento una presencia extraña en esta línea temporal además de nosotros y eso debe de significar que el Vuelo Infinito anda por aquí.' WHERE `ID`=27265;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들의 목적이 뭐라고 생각하십니까?', `MaleText_loc4`='他们想干什么？', `MaleText_loc5`='你認為他們在策劃什麼?', `MaleText_loc7`='¿Qué crees que se traen entre manos?', `FemaleText_loc1`='그들의 목적이 뭐라고 생각하세요?', `FemaleText_loc4`='他们想干什么？', `FemaleText_loc5`='你認為他們在策劃什麼?', `FemaleText_loc7`='¿Qué crees que se traen entre manos?' WHERE `ID`=27266;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='모르겠어요. 그래서 더 걱정되는군요. 난 어떤 수단을 써서든 무한의 용군단을 찾겠어요.$B$B당신은 아서스의 부대에 합류해서 그의 곁에 가까이 있으세요.', `FemaleText_loc4`='不知道，我有些担心。不过我会设法找到永恒之龙的。$B$B与此同时，我希望你能加入阿尔萨斯的部队，尽量待在他身边。', `FemaleText_loc5`='我不知道，這令我十分憂心。我會竭盡所能去找出恆龍。$B$B我現在需要你做的是去加入阿薩斯的軍隊，留在他身邊。', `FemaleText_loc7`='No lo sé y eso me preocupa. Haré todo lo que pueda para encontrar a los Infinitos.$B$BAhora necesito que te unas al ejército de Arthas para mantenerte cerca de él.' WHERE `ID`=27267;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 뭘 해야 합니까?', `MaleText_loc4`='什么？加入王子的军队？', `MaleText_loc5`='你要我做什麼?', `MaleText_loc7`='¿Quieres que haga qué?', `FemaleText_loc1`='제가 뭘 해야 하나요?', `FemaleText_loc4`='什么？加入王子的军队？', `FemaleText_loc5`='你要我做什麼?', `FemaleText_loc7`='¿Quieres que haga qué?' WHERE `ID`=27268;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='입대신청서를 쓰거나 할 필요는 없지만, 어쨌든 그와 함께 싸워야 합니다.$B$B반드시 아서스가 스트라솔름을 파괴하고 말가니스를 처치하게 이끌어야 해요. 우서와 제이나가 곁에 없으니 아마도 손이 모자라겠지요.$B$B아서스에게 말을 걸면 말가니스의 부대를 격파하라는 임무를 줄 거예요. 무한의 용군단에서 꾸미는 수작이 뭔지 내가 알아낼 때까지 계속 그를 따라다니셔야 해요. 더 자세한 정보를 얻으면 다시 연락하겠어요.', `FemaleText_loc4`='这么说吧，你不用去填征兵表格之类的东西，只要和王子并肩战斗就行了。$B$B你必须确保阿尔萨斯成功清洗斯坦索姆并击败玛尔加尼斯。没有了乌瑟尔和吉安娜在身边，他就需要一切可能的帮助。$B$B如果你找阿尔萨斯谈谈的话，他应该会将你编入对抗玛尔加尼斯的部队。我会继续追查永恒之龙的阴谋，一有消息就联络你。', `FemaleText_loc5`='嗯，你不用簽什麼招募文件或是其他的，但你得去跟他並肩作戰。你得去確保阿薩斯肅清斯坦索姆，並打敗瑪爾加尼斯。由於沒有烏瑟跟珍娜在他身邊，他會需要所有能得到的幫助。$B$B如果你跟他說話，他會派你摧毀瑪爾加尼斯的部隊。跟好隊伍，直到我搞清楚恆龍軍團在搞什麼鬼。', `FemaleText_loc7`='Bueno, no vas a firmar papeles de reclutamiento ni nada, pero vas a luchar a su lado.$B$BTienes que asegurarte de que Arthas arrasa Stratholme y vence a Mal''ganis. Sin Uther y Jaina a su lado, necesitará toda la ayuda posible.$B$BSi hablas con Arthas, te dará trabajo destruyendo a las fuerzas de Mal''ganis. Continúa haciéndolo hasta que pueda averiguar qué pasa con los Infinitos.' WHERE `ID`=27269;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 크로미.', `MaleText_loc4`='好吧，克罗米。', `MaleText_loc5`='很好，克羅米。', `MaleText_loc7`='Muy bien, Cromi.', `FemaleText_loc1`='네, 크로미.', `FemaleText_loc4`='好吧，克罗米。', `FemaleText_loc5`='很好，克羅米。', `FemaleText_loc7`='Muy bien, Cromi.' WHERE `ID`=27270;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='행운을 빌어요. 그리고 조심하세요. 우서와 제이나가 이쪽으로 오는군요.', `FemaleText_loc4`='祝你好运，千万当心。瞧，乌瑟尔和吉安娜来了。', `FemaleText_loc5`='祝好運，並且自己小心。烏瑟和珍娜來了。', `FemaleText_loc7`='Buena suerte y mantente a salvo. Aquí vienen Uther y Jaina.' WHERE `ID`=27271;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모자 안 날아가게 꽉 잡으세요, $n 님! 해적 야영지로 갑니다!', `MaleText_loc4`='坐稳啦，$n！向无赖港出发！', `MaleText_loc5`='扶著你的帽子，$n!前往無賴角!', `MaleText_loc7`='¡Agárrate tú el sombrero, $n! ¡Vamos al Cabo Pillastre!' WHERE `ID`=27272;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조오오오았어! 다 왔다고요! 해적 야영집니다!', `MaleText_loc4`='啊！我们到啦！你瞧，无赖港！', `MaleText_loc5`='呀呀啊!我們來啦，好夥伴!無賴角!', `MaleText_loc7`='¡YAAARRRRR! ¡Aquí estamos, grumete! ¡Cabo Pillastre!' WHERE `ID`=27273;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='녹색 피부를 지닌 자여... 네가 왜 여기 왔는지 안다. 우리는 너를 믿지 않으니 동맹 따위는 기대하지 마라.', `MaleText_loc4`='绿皮肤的家伙……我知道你此行的目的。我们不信任你，别妄想说服我们成为你的盟友。', `MaleText_loc5`='綠皮...我知道你為什麼要來。你不可能在我們之中找到盟友的，因為我們不相信你。', `MaleText_loc7`='Piel verde… sé por qué has venido. No encontrarás alidados entre los de mi sangre ya que no confiamos en ustedes.' WHERE `ID`=27274;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저걸 봐, $n, 모래시계에 노즈도르무가 보이잖아!', `MaleText_loc4`='瞧，沙漏显现出诺兹多姆的影像！', `MaleText_loc5`='看，$n，沙漏顯露出了諾茲多姆!', `MaleText_loc7`='Mira, $n, ¡el reloj de arena ha mostrado a Nozdormu!', `FemaleText_loc1`='저걸 봐, $n, 모래시계에 노즈도르무가 보이잖아!', `FemaleText_loc4`='瞧，沙漏显现出诺兹多姆的影像！', `FemaleText_loc5`='看，$n，沙漏顯露出了諾茲多姆!', `FemaleText_loc7`='Mira, $n, ¡el reloj de arena ha mostrado a Nozdormu!' WHERE `ID`=27275;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 경멸하듯 머리를 흔듭니다.', `MaleText_loc4`='%s轻蔑地挥了挥手。', `MaleText_loc5`='%s輕蔑地揮揮手。', `MaleText_loc7`='%s agita la mano con desdeño.' WHERE `ID`=27276;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으아! 정말 돌머리로군! 벌레한테 확 먹혀 버리라지.', `MaleText_loc4`='呸！你这蠢货！我真想把你扔去喂虫子！', `MaleText_loc5`='呸!你和石頭一樣蠢!我希望那些蟲把你全給吃了。', `MaleText_loc7`='¡Vaya! ¡Eres más simple que el mecanismo de un botijo! Espero que los gusanos te coman sin dejar nada.' WHERE `ID`=27277;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우와아아!', `MaleText_loc4`='哇啊啊啊啊！', `MaleText_loc5`='喔哇哇!', `MaleText_loc7`='¡AUUUUUUUU!', `FemaleText_loc1`='우와아아!', `FemaleText_loc4`='哇啊啊啊啊！', `FemaleText_loc5`='喔哇哇!', `FemaleText_loc7`='¡AUUUUUUUU!' WHERE `ID`=27278;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아야야야이에에에!!', `MaleText_loc4`='呀呀呀！！', `MaleText_loc5`='呀咿耶!!', `MaleText_loc7`='¡AYYYYYYYYY!', `FemaleText_loc1`='아야야야이에에에!!', `FemaleText_loc4`='呀呀呀！！', `FemaleText_loc5`='呀咿耶!!', `FemaleText_loc7`='¡AYYYYYYYYY!' WHERE `ID`=27279;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우에에오오와악!', `MaleText_loc4`='耶喔！', `MaleText_loc5`='呀呼呼!', `MaleText_loc7`='¡AYYYYYYYYY!', `FemaleText_loc1`='우에에오오와악!', `FemaleText_loc4`='耶喔！', `FemaleText_loc5`='呀呼呼!', `FemaleText_loc7`='¡AYYYYYYYYY!' WHERE `ID`=27280;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와아아아아악!!', `MaleText_loc4`='啊啊啊啊！！！', `MaleText_loc5`='啊啊啊!!', `MaleText_loc7`='¡AAAAHHH!!', `FemaleText_loc1`='와아아아아악!!', `FemaleText_loc4`='啊啊啊啊！！！', `FemaleText_loc5`='啊啊啊!!', `FemaleText_loc7`='¡AAAAHHH!!' WHERE `ID`=27281;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<드라쿠루가 철창 밖으로 피가 흐르는 손을 뻗으며 기대에 찬 눈으로 바라봅니다.>', `MaleText_loc4`='<达库鲁将滴血的手掌伸出笼子，满怀期待地看着你。>', `MaleText_loc5`='<德拉庫魯把他流著血的手伸出籠子外，期待地看著你。>', `MaleText_loc7`='<Drakuru extiende su ensangrentada mano a través de la jaula y te mira expectante.>' WHERE `ID`=27282;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드라쿠루가 뻗은 손을 맞잡고 악수합니다.', `MaleText_loc4`='与达库鲁握手。', `MaleText_loc5`='握住德拉庫魯伸出來的手。', `MaleText_loc7`='Aprieta la mano estirada de Drakuru.', `FemaleText_loc1`='드라쿠루가 뻗은 손을 맞잡고 악수합니다.', `FemaleText_loc4`='与达库鲁握手。', `FemaleText_loc5`='握住德拉庫魯伸出來的手。', `FemaleText_loc7`='Aprieta la mano estirada de Drakuru.' WHERE `ID`=27283;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='단지 네놈들의 놀란 얼굴을 보려고 참혹한 짓을 저지르던 때가 있었지...', `MaleText_loc4`='换成以前，我会把你打倒，瞧瞧你脸上的表情……', `MaleText_loc5`='看看你那時候的表情，那就是我把你的心臟掏出來的時候啊...', `MaleText_loc7`='Hubo un tiempo en el que podría haberte arrancado el corazón solo por ver la expresión de tu rostro...' WHERE `ID`=27284;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여어!$b$b또 만나서 반갑다... $n 맞나? 그럼. 그렇고 말고.$b$b너와 난 아주 좋은 친구가 될 거다. 이 드라쿠루는 잘 알고 있지.$b$b<분장한 얼굴로 천천히 미소를 짓는 트롤>', `MaleText_loc4`='嗨，朋友！$B$B很高兴再次见到你……$n，对吧？我怎么会忘记你的名字呢。$B$B我有一种强烈的直觉，我们一定会成为真正的好朋友！$B$B<巨魔露出一丝狡黠的笑容。>', `MaleText_loc5`='欸，老兄!$b$b看到你真好...$n，對吧?是，是，當然。$b$b你跟我一定是很好的朋友。德拉庫魯知道這些事情。$b$b<食人妖彩繪的臉上緩緩地露出笑容。>', `MaleText_loc7`='¡Eh, colega!$B$BMe alegro de volver a verte... $n, ¿verdad? Sí, sí, claro.$B$BTú y yo vamos a ser muy buenos amigos. Drakuru sabe de estas cosas.$B$B<Una sonrisa comienza a extenderse por la cara pintada del trol.>' WHERE `ID`=27285;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 비약이 더 필요합니다, 드라쿠루.', `MaleText_loc4`='达库鲁，我还需要一瓶药剂。', `MaleText_loc5`='我需要另一罐你的藥劑，德拉庫魯。', `MaleText_loc7`='Necesito otro de tus elixires, Drakuru.', `FemaleText_loc1`='당신의 비약이 더 필요합니다, 드라쿠루.', `FemaleText_loc4`='达库鲁，我还需要一瓶药剂。', `FemaleText_loc5`='我需要另一罐你的藥劑，德拉庫魯。', `FemaleText_loc7`='Necesito otro de tus elixires, Drakuru.' WHERE `ID`=27286;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='작별할 시간이군, $n. 목숨을 아끼고, 되도록 좋은 장비를 갖춰 줘!', `MaleText_loc4`='再见，$n。好好活着，搞些更好的装备！', `MaleText_loc5`='再會，$n。讓我們活下來並且拿些好一點裝備來!', `MaleText_loc7`='Adiós, $n. ¡Mantennos vivos y consigue un equipo mejor!', `FemaleText_loc1`='작별할 시간이네, $n. 목숨을 아끼고, 되도록 좋은 장비를 갖춰 줘!', `FemaleText_loc4`='再见，$n。好好活着，搞些更好的装备！', `FemaleText_loc5`='再會，$n。讓我們活下來並且拿些好一點裝備來!', `FemaleText_loc7`='Adiós, $n. ¡Mantennos vivas y consigue un equipo mejor!' WHERE `ID`=27287;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 있다, 친구. 이번에는 좀 조심해. 알겠어?$b$b그럼 드락진 폐허로 가서 단상 근처에서 비약을 마셔라!', `MaleText_loc4`='给。千万别大意哦。$B$B等你进入达克辛废墟后，在底座旁喝下它！', `MaleText_loc5`='你在這裡，老兄。試著對這個小心一點，行吧?$b$b現在去德拉克辛遺跡吧，在靠近石臺時喝下它!', `MaleText_loc7`='Ahí tienes. Ten más cuidado esta vez. ¿Quieres?$b$bAhora vete a las Ruinas de Drak''Zin y bébetelo cerca del pedestal.' WHERE `ID`=27288;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헬스크림 님의 명령은 이 왕좌에서 나오네. 그분의 말씀은 삶이자 죽음일세.', `MaleText_loc4`='我负责传达地狱咆哮的命令。他的指令都是生死攸关的决策。', `MaleText_loc5`='從這個王座上，我發出地獄吼的命令。他的話語決定生與死。', `MaleText_loc7`='Desde este trono comunico la voluntad de Grito Infernal. Su palabra es vida y su palabra es muerte.' WHERE `ID`=27289;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수컬지 트롤들이 불타고 있네...', `MaleText_loc4`='堕落的巨魔……', `MaleText_loc5`='烘烤天譴食人妖...', `MaleText_loc7`='Tossshtando trolesssshhh plagadossshh...' WHERE `ID`=27290;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 뜨거운 불 위에...', `MaleText_loc4`='……接受烈焰的惩罚……', `MaleText_loc5`='...開火...', `MaleText_loc7`='... en un fuego abierto...' WHERE `ID`=27291;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끝입니다! 지금까지 쓴 내용이에요... 어떤가요?', `MaleText_loc4`='好啦！扯远了……你觉得呢？', `MaleText_loc5`='成了!做的不錯...你覺得呢?', `MaleText_loc7`='¡Eso es! Todo lo que tengo... ¿Qué te parece?' WHERE `ID`=27292;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='엘룬께서는 그대를 지켜보고 계신답니다, $r|1이여;여;.', `FemaleText_loc4`='愿艾露恩保护你，$r。', `FemaleText_loc5`='伊露恩看照著你，$r。', `FemaleText_loc7`='Que Elune te proteja, $r.' WHERE `ID`=27293;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='켈러 부제독이 보내서 왔습니다, 에밀룬. 서부경비대 성채로 보내주십시오.', `MaleText_loc4`='艾米鲁尔，是凯勒中将派我来的。请送我去西部卫戍要塞！', `MaleText_loc5`='凱勒中將派我來，艾米廬。請送我到鎮西要塞!', `MaleText_loc7`='Me envía el almirante Keller, Emilune. ¡Por favor, envíame a la Fortaleza de la Guardia Oeste!', `FemaleText_loc1`='에밀룬, 켈러 부제독이 보내서 왔어요. 서부경비대 성채로 보내주세요.', `FemaleText_loc4`='艾米鲁尔，是凯勒中将派我来的。请送我去西部卫戍要塞！', `FemaleText_loc5`='凱勒中將派我來，艾米廬。請送我到鎮西要塞!', `FemaleText_loc7`='Me envía el almirante Keller, Emilune. ¡Por favor, envíame a la Fortaleza de la Guardia Oeste!' WHERE `ID`=27294;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 왔습니다. 그럼 일을 시작해 볼까요?', `MaleText_loc4`='我到啦。我们开始吧？', `MaleText_loc5`='我剛到這，馬上就要上工了嗎?', `MaleText_loc7`='Ya he llegado. ¿Nos ponemos manos a la obra?' WHERE `ID`=27295;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무엇을 도와드릴까요?', `MaleText_loc4`='$g先生:女士;，你觉得这个怎么样？', `MaleText_loc5`='鄙人能幫$g先生:女士;什麼忙呢?', `MaleText_loc7`='¿Cómo puedo ayudarte, $gseñor:señora;?' WHERE `ID`=27296;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 식으로 일을 하십니까?', `MaleText_loc4`='这玩意儿要怎么用？', `MaleText_loc5`='如何進行交易?', `MaleText_loc7`='¿Cómo funciona esto?', `FemaleText_loc1`='어떤 식으로 일을 하시나요?', `FemaleText_loc4`='这玩意儿要怎么用？', `FemaleText_loc5`='如何進行交易?', `FemaleText_loc7`='¿Cómo funciona esto?' WHERE `ID`=27298;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물건을 보고 싶습니다.', `MaleText_loc4`='让我看看你出售的货物。', `MaleText_loc5`='給我看你要交易的商品。', `MaleText_loc7`='Muéstrame qué tienes para comerciar.', `FemaleText_loc1`='물건을 보고 싶습니다.', `FemaleText_loc4`='让我看看你出售的货物。', `FemaleText_loc5`='給我看你要交易的商品。', `FemaleText_loc7`='Muéstrame qué tienes para comerciar.' WHERE `ID`=27299;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 동업자는 뭔가를 죽이고, 저는 그들에게서 정수를 일부 흡수합니다... 아주 약간입니다. 정말로요. 별거 아닙니다. 문제가 생기거나 하지 않아요.$B$B대신에 저는 에테리얼 신용 증표를 제공함으로써 계약에서 제 몫을 이행합니다.$B$B이 신용 증표는 언제든지 제가 가진 상품으로 교환할 수 있지요. 당신 마음에 드는 물건이 있을 겁니다...', `MaleText_loc4`='我来告诉你虚灵是怎么做生意的。我让合作伙伴去杀死生物，然后我来抽取它们的精华……只要一点点就够啦，真的。$B$B我会支付虚灵货币，以此履行合同规定的义务。$B$B你可以用货币购买我出售的货物哦。肯定有你感兴趣的东西……', `MaleText_loc5`='我的生意夥伴負責殺;我負責抽取他們一部份的精華...只抽一點點，真的;只是薄薄的一小片而已。他們不會在意的。$B$B不過，為了要完成我的契約，我會用以太信用貨幣付帳。$B$B可以用這些貨幣隨時跟我換我賣的東西。我一定會有你感興趣的商品...', `MaleText_loc7`='Mi socio mata cosas. Yo dreno parte de su esencia... una miseria, de verdad: un pizco de nada. Nadie lo notará.$B$bDe todas formas, pago mi parte del trato con créditos etéreos.$B$bSe pueden canjear por objetos que yo vendo en cualquier momento. Seguro que tengo algo que te pueda interesar...' WHERE `ID`=27300;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 그런 걸 입고 다녔다니, 믿기지 않는군.', `MaleText_loc4`='真不敢相信，我竟然穿过这样的装备。', `MaleText_loc5`='我真不敢不相信我以前還穿它!', `MaleText_loc7`='Me cuesta creer que yo solía llevar eso.', `FemaleText_loc1`='내가 그런 걸 입고 다녔다니, 믿기지가 않아.', `FemaleText_loc4`='真不敢相信，我竟然穿过这样的装备。', `FemaleText_loc5`='我真不敢不相信我以前還穿它!', `FemaleText_loc7`='Me cuesta creer que yo solía llevar eso.' WHERE `ID`=27301;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이게 해리와 얘기를 나눌 수 있는 단 하나의 방법이에요! 항상 이 우스꽝스러운 가면을 쓰고 있어야 한답니다...', `FemaleText_loc4`='只有这样，哈瑞才会和我讲话！我必须一直戴着这个愚蠢的面具……', `FemaleText_loc5`='這是哈利唯一會跟我說話的辦法!我整天都戴著這個蠢面具...', `FemaleText_loc7`='¡Esta es la única manera de que Harry hable conmigo! Tengo que llevar puesta esta estúpida máscara todo el tiempo...' WHERE `ID`=27302;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해리가 바엘군의 발굴현장으로 가는 그의 폭격기를 타도 된다더군요. 전 갈 준비가 됐습니다!', `MaleText_loc4`='哈瑞说我可以搭乘他的小船去巴尔古挖掘场。我准备好出发啦！', `MaleText_loc5`='哈利說我可以開他的轟炸機去巴爾古恩的地方。我已經準備好了!', `MaleText_loc7`='Harry dijo que podría coger su bombardero para ir a Bael''gun. ¡Vamos!', `FemaleText_loc1`='해리가 바엘군의 발굴현장으로 가는 그의 폭격기를 타도 된다더군요. 전 준비 됐습니다!', `FemaleText_loc4`='哈瑞说我可以搭乘他的小船去巴尔古挖掘场。我准备好出发啦！', `FemaleText_loc5`='哈利說我可以開他的轟炸機去巴爾古恩的地方。我已經準備好了!', `FemaleText_loc7`='Harry dijo que podría coger su bombardero para ir a Bael''gun. ¡Vamos!' WHERE `ID`=27303;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싸우는 모습을 보고 있자니 답답하군... 내가 왜 주정뱅이가 됐는지 알겠어.', `MaleText_loc4`='瞧瞧你在战斗中的表现，难怪我会染上酒瘾。', `MaleText_loc5`='看著你戰鬥，難怪我會跑去喝酒。', `MaleText_loc7`='Mírate, no es de extrañar que me diera a la bebida.', `FemaleText_loc1`='싸우는 모습을 보고 있자니 답답하네... 내가 왜 주정뱅이가 됐는지 알겠어.', `FemaleText_loc4`='瞧瞧你在战斗中的表现，难怪我会染上酒瘾。', `FemaleText_loc5`='看著你戰鬥，難怪我會跑去喝酒。', `FemaleText_loc7`='Mírate, no es de extrañar que me diera a la bebida.' WHERE `ID`=27304;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐 하는 거지? 나 혼자 싸우게 둘 참이냐? 우리 둘 다 이 일에 목숨이 달렸다고!', `MaleText_loc4`='什么？你应该很清楚吧，我们的命运是休戚相关的！', `MaleText_loc5`='什麼?我一個人在這裡。我們都在這件事情上冒了風險，你知道的!', `MaleText_loc7`='¿Qué? Estoy aquí solo. Los dos arriesgamos algo con esto, ¡lo sabes!', `FemaleText_loc1`='뭐 하는 거지? 나 혼자 싸우게 둘 참이야? 우리 둘 다 이 일에 목숨이 달렸다고!', `FemaleText_loc4`='什么？你应该很清楚吧，我们的命运是休戚相关的！', `FemaleText_loc5`='什麼?我一個人在這裡。我們都在這件事情上冒了風險，你知道的!', `FemaleText_loc7`='¿Qué? Estoy aquí sola. Las dos arriesgamos algo con esto, ¡lo sabes!' WHERE `ID`=27305;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어찌 됐든, 네가 죽어서는 안 되지. 그렇게 되면 나까지 사라져버릴 테니까. 그렇지? 하지만, 내가 너였을 때는 이 자리에 내가 있었는데... 아아, 헷갈려!', `MaleText_loc4`='你可千万别出事啊。你若是死了，我也就不存在了，对吧？但是如果你真的死了的话，我又是如何能从未来返回呢。我被绕糊涂了！', `MaleText_loc5`='不管如何，你不能死，因為這樣會表示我的存在也會消失，對吧?但，當我還是你的時候，我來過這裡。喔，我真的快搞混了!', `MaleText_loc7`='Pase lo que pase no puedes morir, porque eso significaría que yo dejaría de existir, ¿verdad? Pero yo estaba antes aquí cuando era tú. ¡Estoy muy confuso!', `FemaleText_loc1`='어찌 됐든, 네가 죽어서는 안 되지. 그렇게 되면 나까지 사라져버릴 테니까. 그렇지? 하지만, 내가 너였을 때는 이 자리에 내가 있었는데... 아아, 헷갈려!', `FemaleText_loc4`='你可千万别出事啊。你若是死了，我也就不存在了，对吧？但是如果你真的死了的话，我又是如何能从未来返回呢。我被绕糊涂了！', `FemaleText_loc5`='不管如何，你不能死，因為這樣會表示我的存在也會消失，對吧?但，當我還是你的時候，我來過這裡。喔，我真的快搞混了!', `FemaleText_loc7`='Pase lo que pase no puedes morir, porque eso significaría que yo dejaría de existir, ¿verdad? Pero yo estaba antes aquí cuando era tú. ¡Estoy muy confusa!' WHERE `ID`=27306;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세상에, 내가 이 정도로 미숙했었나?', `MaleText_loc4`='啊，我差点忘记啦，原来以前我是这么缺乏经验啊。', `MaleText_loc5`='哇喔，我差點都忘了我以前有多菜。', `MaleText_loc7`='Guau, había olvidado lo inexperto que era.', `FemaleText_loc1`='세상에, 내가 이 정도로 미숙했었나?', `FemaleText_loc4`='啊，我差点忘记啦，原来以前我是这么缺乏经验啊。', `FemaleText_loc5`='哇喔，我差點都忘了我以前有多菜。', `FemaleText_loc7`='Guau, había olvidado lo inexperta que era.' WHERE `ID`=27307;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맥이 큰 소리로 트림을 합니다...', `MaleText_loc4`='马克大声地打嗝……', `MaleText_loc5`='麥客打了一個超大聲的嗝...', `MaleText_loc7`='Mack eructa en alto...' WHERE `ID`=27308;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여보세요!$b$b지금 상황은 보이는 것과 다릅니다. 아마 그럴 겁니다...$b$b설명하자면 복잡합니다.', `MaleText_loc4`='朋友！$B$B事实上并不是这样的。呃……$B$B情况太复杂了。', `MaleText_loc5`='喔，老兄!$b$b這不是你想得那樣。呃，也許啦...$b$b這件事有點複雜。', `MaleText_loc7`='¡Uy, colega!$B$BEsto no es lo que parece. Bueno, igual...$B$BEs complicado.' WHERE `ID`=27309;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여보세요! 내가 당신을 알던가요?$b$b아, 맞아요. 프리그몬은 얼굴을 잊지 않는답니다.$b$b당신... 날 쫓아오는 건가요? 뭔지 모르지만, 이 프리그몬은 하지 않았어요!', `MaleText_loc4`='朋友！我认识你？$B$B哦，是你啊，普雷蒙有过目不忘的本事。$B$B你……跟踪我？不关我的事！我什么都没做过！', `MaleText_loc5`='喔，老兄!我認識你嗎?$b$b哎呀，皮格蒙不會忘記別人長相的。$b$b你...跟著我，老兄?因為不管那是什麼，皮格蒙都不幹!', `MaleText_loc7`='¡Ehh! ¿Nos conocemos?$b$b¡Sí, sí! Prigmon no olvida una cara.$b$b¿Acaso me estás siguiendo...? Sea lo que sea… ¡No es culpa de Prigmon!' WHERE `ID`=27310;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미안해. 하지만 크로미가 말하길, 미래에 대한 그 어떤 정보도 너에게 알려줘서는 안 된대. 만약 그랬다가는 내 존재 자체가 사라져버리는 모양이야.', `MaleText_loc4`='不好意思，克罗米禁止我透露任何未来的事情。她警告说，如果我告诉了你，那我有可能就不会存在了。', `MaleText_loc5`='抱歉，克羅米說我不能告訴任何關於你未來的事情。她說要是我講出來，我的存在就會消失。', `MaleText_loc7`='Lo siento, pero Cromi dijo que no podía contarte nada sobre tu futuro. Dijo que si lo hacía, dejaría de existir.', `FemaleText_loc1`='미안해. 하지만 크로미가 말하길, 미래에 대한 그 어떤 정보도 너에게 알려줘서는 안 된대. 만약 그랬다가는 내 존재 자체가 사라져버리는 모양이야.', `FemaleText_loc4`='不好意思，克罗米禁止我透露任何未来的事情。她警告说，如果我告诉了你，那我有可能就不会存在了。', `FemaleText_loc5`='抱歉，克羅米說我不能告訴任何關於你未來的事情。她說要是我講出來，我的存在就會消失。', `FemaleText_loc7`='Lo siento, pero Cromi dijo que no podía contarte nada sobre tu futuro. Dijo que si lo hacía, dejaría de existir.' WHERE `ID`=27311;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 상대해야 할 무한의 용군단이 얼마나 되는지 기억이 나면 좋을 텐데. 나한테는 하도 오래전 일이라...', `MaleText_loc4`='我真希望能想起来到底有多少永恒之龙想阻止你。这场战斗实在是太久远啦。', `MaleText_loc5`='真希望我記得到底有多少恆龍軍團出來阻止你。這場戰鬥真的是好久以前的事了。', `MaleText_loc7`='Ojalá recordara cuántos del Vuelo Infinito iban a intentar detenerte. Esta batalla fue hace tanto tiempo.', `FemaleText_loc1`='네가 상대해야 할 무한의 용군단이 얼마나 되는지 기억이 나면 좋을 텐데. 나한테는 하도 오래전 일이라...', `FemaleText_loc4`='我真希望能想起来到底有多少永恒之龙想阻止你。这场战斗实在是太久远啦。', `FemaleText_loc5`='真希望我記得到底有多少恆龍軍團出來阻止你。這場戰鬥真的是好久以前的事了。', `FemaleText_loc7`='Ojalá recordara cuántos del Vuelo Infinito iban a intentar detenerte. Esta batalla fue hace tanto tiempo.' WHERE `ID`=27312;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 말 잘 들어. 원래 이런 얘길 해서는 안 되지만... 어쨌거나 넌 말이지, 나중에 어떤 잔치에 초대받을 거야. 거기 가거든, 무슨 일이 있어도 절대 음료수는 마시지 마!', `MaleText_loc4`='听着。我本来不打算告诉你的，很快你就会接到聚会的邀请。总之，千万别喝宴会上的饮料！', `MaleText_loc5`='聽著。我不應該告訴你這個，但未來你會被邀請參加一場舞會。不管你做什麼，就是別亂喝調酒!', `MaleText_loc7`='Escucha. No debería decirte esto, pero va a haber una fiesta a la que te van a invitar. Hagas lo que hagas, ¡NO BEBAS EL PONCHE!', `FemaleText_loc1`='내 말 잘 들어. 원래 이런 얘기는 해서는 안 되지만... 어쨌거나 넌 말이지, 나중에 어떤 잔치에 초대받을 거야. 거기 가거든, 무슨 일이 있어도 절대 음료수는 마시지 마!', `FemaleText_loc4`='听着。我本来不打算告诉你的，很快你就会接到聚会的邀请。总之，千万别喝宴会上的饮料！', `FemaleText_loc5`='聽著。我不應該告訴你這個，但未來你會被邀請參加一場舞會。不管你做什麼，就是別亂喝調酒!', `FemaleText_loc7`='Escucha. No debería decirte esto, pero va a haber una fiesta a la que te van a invitar. Hagas lo que hagas, ¡NO BEBAS EL PONCHE!' WHERE `ID`=27313;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 나타나셨군, 우서.', `MaleText_loc4`='乌瑟尔，你总算及时赶到了。', `MaleText_loc5`='真高興你趕到了，烏瑟。', `MaleText_loc7`='Me alegra que vinieras, Uther.' WHERE `ID`=27314;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말조심하게, 젊은이. 자네가 왕자일지언정, 나는 성기사로서 자네 상관일세!', `MaleText_loc4`='注意你讲话的态度。没错，你贵为王子，但我仍然是你的导师。', `MaleText_loc5`='注意你講話的態度。沒錯，你貴為王子，但我仍然是你的導師!', `MaleText_loc7`='Modera el tono, chico. Serás el Príncipe, pero yo sigo siendo tu superior como paladín.' WHERE `ID`=27315;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어찌 그걸 잊겠습니까. 잘 들으세요, 우서. 역병에 대해 얘기할 게 있습니다.', `MaleText_loc4`='我自然不会忘记这一点。听着，乌瑟尔，现在我来告诉你关于天灾的事……', `MaleText_loc5`='我不會忘記的。聽著，烏瑟，有些關於瘟疫的事情你應該要知道...', `MaleText_loc7`='Como si pudiera olvidarlo. Escucha, Uther, hay algo sobre la peste que debes saber…' WHERE `ID`=27316;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼... 너무 늦었어. 사람들이 모두 감염돼 버렸군! 지금은 괜찮아 보일지 모르지만, 언데드로 변하는 것은 시간문제입니다!', `MaleText_loc4`='糟糕。我们太迟了。他们已经被感染了！虽然他们现在表面上还正常，但是迟早会变成亡灵！', `MaleText_loc5`='噢，不。我們太遲了。那些居民全被感染了!他們現在或許看來很正常，但他們變成不死生物只是遲早的事!', `MaleText_loc7`='Oh, no. Es demasiado tarde. ¡Están todos infectados! Ahora aparentan estar bien, ¡pero es cuestión de tiempo para que se conviertan en no-muertos!' WHERE `ID`=27317;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐라고?', `MaleText_loc4`='什么？', `MaleText_loc5`='什麼?', `MaleText_loc7`='¿Qué?' WHERE `ID`=27318;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도시 전체를 쓸어버려야 합니다.', `MaleText_loc4`='必须净化整座城市。', `MaleText_loc5`='必須淨化整座城市。', `MaleText_loc7`='Hay que desinfectar toda esta ciudad.' WHERE `ID`=27319;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 그런 말을 할 수 있나? 다른 방법이 있을 걸세.', `MaleText_loc4`='你怎么会产生这种想法？肯定有别的解决方式。', `MaleText_loc5`='你怎麼會產生這種想法?肯定有別的解決方式。', `MaleText_loc7`='¡Ni lo pienses! ¡Tiene que haber alguna otra manera!' WHERE `ID`=27320;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='닥치시오, 우서! 미래의 왕인 내 명에 따라, 이 도시를 정화하시오!', `MaleText_loc4`='乌瑟尔，大胆！我是你未来的国君，我命令你清理这座城市！', `MaleText_loc5`='該死，烏瑟!我以未來國王的名義命令你，淨化這座城市!', `MaleText_loc7`='¡Maldición, Uther! ¡Como tu futuro rey, te ordeno desinfectar esta ciudad!' WHERE `ID`=27321;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자넨 아직 내 왕이 아닐세! 설령 왕이었다 한들 그런 명령은 따를 수 없네!', `MaleText_loc4`='孩子，你还不是我的王上！况且就算你是，我也不会遵从这样的命令！', `MaleText_loc5`='你還不是我的國王，孩子。就算你是，我也不會遵從這樣的命令!', `MaleText_loc7`='Aún no eres mi rey, muchacho. ¡Y tampoco acataría esa orden si lo fueras!' WHERE `ID`=27322;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명을 따르지 않는다면 반역으로 받아들이겠소.', `MaleText_loc4`='那么，我只能将你的决定视为叛国了。', `MaleText_loc5`='那麼，我只能將你的決定視為叛國了。', `MaleText_loc7`='Entonces debo estimar este acto una traición.' WHERE `ID`=27323;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반역이라고? 자네 미쳤나, 아서스?', `MaleText_loc4`='叛国？你疯了吗，阿尔萨斯？', `MaleText_loc5`='叛國?你瘋了嗎，阿薩斯?', `MaleText_loc7`='¿Traición? ¿Te has vuelto loco, Arthas?' WHERE `ID`=27324;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가? 우서 경, 정당하고도 확고한 내 왕위 계승권에 따라 명한다. 지금부터 그대의 지휘권을 박탈하고 그대의 성기사들에게 근신 조치를 내리노라.', `MaleText_loc4`='是这样吗？我以王储的身份在此宣布，解除乌瑟尔勋爵在白银之手骑士团的所有权力与职务。', `MaleText_loc5`='我瘋了嗎?烏瑟大人，我以王儲的權力，在此解除你的指揮權，並且暫停你的聖騎士職務。', `MaleText_loc7`='¿Eso crees? Lord Uther, por mi derecho de sucesión y la soberanía de mi corona, te relevo de tu mando y suspendo a tus paladines del servicio.' WHERE `ID`=27325;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아서스! 그렇게 멋대로...', `FemaleText_loc4`='阿尔萨斯！你怎么能……', `FemaleText_loc5`='阿薩斯!你不能就這樣...', `FemaleText_loc7`='¡Arthas! No puedes...' WHERE `ID`=27326;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만! 이 땅을 구할 의지와 용기가 있는 자는 나를 따르라! 그렇지 않다면... 내 눈앞에서 사라져라!', `MaleText_loc4`='就这样吧！有谁希望拯救这片土地的，就跟我来！其他人……给我滚远点！', `MaleText_loc5`='這已經決定!想要拯救這塊土地的人，跟著我!至於其他的人...滾出我的視線!', `MaleText_loc7`='¡Listo! ¡Quienes tengan la fuerza para salvar esta tierra, síganme! Los demás... ¡desaparezcan de mi vista!' WHERE `ID`=27327;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 넘지 말아야 할 선을 넘었네, 아서스.', `MaleText_loc4`='阿尔萨斯，你做出了一个非常可怕的决定。', `MaleText_loc5`='你剛剛越過了一條可怕的界線，阿薩斯。', `MaleText_loc7`='Acabas de atravesar un umbral atroz, Arthas.' WHERE `ID`=27328;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제이나?', `MaleText_loc4`='吉安娜？', `MaleText_loc5`='珍娜?', `MaleText_loc7`='¿Jaina?' WHERE `ID`=27329;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='미안해요, 아서스. 차마 볼 수가 없어요.', `FemaleText_loc4`='对不起，阿尔萨斯。我不能眼睁睁地看着你走上歧途。', `FemaleText_loc5`='抱歉，阿薩斯。我無法看著你做出這種事。', `FemaleText_loc7`='Lo siento, Arthas. No puedo verte hacerlo.' WHERE `ID`=27330;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드락타론을 위하여!', `MaleText_loc4`='为达克萨隆要塞而战！', `MaleText_loc5`='為了德拉克薩隆!', `MaleText_loc7`='¡Por Drak''Tharon!' WHERE `ID`=27331;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 짐보는 살아서 배신자를 죽여야 한다!', `MaleText_loc4`='希姆波不能死，他还要对付叛徒呢！', `MaleText_loc5`='辛波必須要活下來殺死背叛我們的人!', `MaleText_loc7`='¡Zim''bo debe vivir para matar a nuestro traidor!' WHERE `ID`=27332;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무도 이 짐보를 막을 수 없다! 성채는 해방되어야 한다!', `MaleText_loc4`='谁也不能阻挡希姆波！我们要解放要塞！', `MaleText_loc5`='辛波是抵擋不了的!要塞必須被解放!', `MaleText_loc7`='¡No se puede detener a Zim''bo! ¡Hay que liberar la fortaleza!' WHERE `ID`=27333;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 스컬지 녀석들처럼 너도 죽게 될 거다!', `MaleText_loc4`='和天灾士兵一起去死吧！', `MaleText_loc5`='你要和那些天譴軍一起死去!', `MaleText_loc7`='¡Morirás junto a todos estos miembros de la Plaga!' WHERE `ID`=27334;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동족에게 배신당하다니. 수치스러운 일이다...', `MaleText_loc4`='被我们的族人背叛。真是莫大的耻辱……', `MaleText_loc5`='被我們的同胞所背叛。恥辱...', `MaleText_loc7`='Hemos sido traicionados por uno de los nuestros. Qué desgracia…' WHERE `ID`=27335;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 정수를 더 흡수할 수 있겠군요...', `MaleText_loc4`='啊，我要吸取更多的精华……', `MaleText_loc5`='啊，又可以捕獲更多的精華了...', `MaleText_loc7`='Ah, más esencia que capturar.' WHERE `ID`=27336;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='즐거운 편도 항해 여행 되세요!', `FemaleText_loc4`='旅途愉快！这是单程航线！', `FemaleText_loc5`='旅途愉快!這可是單程唷!', `FemaleText_loc7`='¡Disfruta del paseo! ¡Es un viaje solo de ida!' WHERE `ID`=27337;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 있다, 친구. 이번에는 좀 조심해. 알겠어?$b$b그럼 북쪽의 제브할락에 있는 단상 근처에서 비약을 마셔라!$b$b아, 먼저 지구라트에 있는 석상에서 예언가의 눈을 구하는 걸 잊지 말고...', `MaleText_loc4`='给。这次要格外当心啦。$B$B前往北边的塞布哈拉克，在底座旁边饮下它吧！$B$B哦，你要先去通灵塔顶端取下预言者之眼才行……', `MaleText_loc5`='你在這裡，老兄。試著對這個小心一點，行吧?$b$b現在去北邊的札布哈拉克吧，在靠近石臺時喝下它!$b$b喔，記得要先從通靈塔取得預言者之眼...', `MaleText_loc7`='Ahí tienes, colega. Intenta tener más cuidao eh''ta vez, ¿quieres?$b$bAhora dirígete al noh''te, a Zeb''Halak y bébelo cerca del pedeh''tal.$b$bAh, y asegúrate d''obtené el ojo de los profetas de la cabeza en el zigurat primero...' WHERE `ID`=27338;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 있다, 친구. 이번에는 좀 조심해. 알겠어?$b$b그럼 북쪽의 제브할락에 있는 단상 근처에서 비약을 마셔!$b$b그다음은 거기서 설명해 주지.', `MaleText_loc4`='给。这次要格外当心啦。$B$B前往北边的塞布哈拉克，在底座旁边饮下它吧！$B$B然后我会给你进一步指示的。', `MaleText_loc5`='你在這裡，老兄。試著對這個小心一點，行吧?$b$b現在去北邊的札布哈拉克吧，在靠近石臺時喝下它!$b$b我會從這裡繼續指引你。', `MaleText_loc7`='Ahí tienes. Intenta tener más cuidado esta vez, ¿quieres?$b$bAhora dirígete al norte, a Zeb''Halak y bébelo cerca del pedestal.$b$bDespués te daré más información.' WHERE `ID`=27339;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 있다, 친구. 이번에는 좀 조심해, 알겠어?$b$b그럼 북서쪽의 드라카탈 통로로 간 다음 그곳의 대좌에서 비약을 마셔. $b$b그 뒤는 다시 만났을 때 설명해 주지.', `MaleText_loc4`='给。这次要格外当心啦。$B$B前往西北边的达克阿塔小径，在底座旁饮下药剂吧。$B$B然后我会给你进一步指示的。', `MaleText_loc5`='你在這裡，老兄。試著對這個小心一點，行吧?$b$b現在前往西北邊的德拉克托通道吧，在靠近石臺時喝下藥劑!$b$b等我再見到你，我會從繼續指引你。', `MaleText_loc7`='Ahí tienes. Intenta tener más cuidado esta vez, ¿quieres?$b$bAhora dirígete al Paso de Drak''Atal al noroeste y bebe el elixir en el pedestal que allí encontrarás. $b$bDespués te daré más información.' WHERE `ID`=27340;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 몫은 여기 있습니다.', `MaleText_loc4`='这是你的那份。', `MaleText_loc5`='這是你的份。', `MaleText_loc7`='Aquí tienes tu parte.' WHERE `ID`=27341;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당장 돌아가서 전투를 계속하지 않는다면 그대를 떨어뜨려 버리겠습니다!', `MaleText_loc4`='调转方向！重新投入战斗！否则我就将你甩下去！', `MaleText_loc5`='轉身重新加入戰局，要不然我要把你丟下去!', `MaleText_loc7`='¡Da la vuelta y vuelve a la lucha o te dejaré caer!' WHERE `ID`=27342;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 야영지에 온 것을 환영하네.$b$b별로 대단한 것은 없지만, 그래도 내겐 집이나 다름없는 곳이라네.', `MaleText_loc4`='欢迎来到我的营地，$r。$B$B好吧，她或许算不上一座营地，但至少我把她看作自己的家园。', `MaleText_loc5`='歡迎來到我的營地，$r。$b$b雖然不大，但起碼是個家。', `MaleText_loc7`='Te doy la bienvenida a mi campamento, $r.$B$BNo parece gran cosa, pero por ahora es un hogar.' WHERE `ID`=27343;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='울팡, 다시 한 번 독수리의 눈을 통해 세상을 보고 싶습니다.', `MaleText_loc4`='乌尔芬，我想再次透过巨鹰之眼洞悉真相。', `MaleText_loc5`='巫牙，我需要再次透過雌鷹之眼來觀看。', `MaleText_loc7`='Ulkang, necesito ver a través de los Ojos del Águila de nuevo.', `FemaleText_loc1`='울팡, 다시 한 번 독수리의 눈을 통해 세상을 보고 싶어요.', `FemaleText_loc4`='乌尔芬，我想再次透过巨鹰之眼洞悉真相。', `FemaleText_loc5`='巫牙，我需要再次透過雌鷹之眼來觀看。', `FemaleText_loc7`='Ulkang, necesito ver a través de los Ojos del Águila de nuevo.' WHERE `ID`=27344;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋네. 그녀의 날카로운 시력을 다시 한번 쓸 게 되었군.', `MaleText_loc4`='好吧。我允许你再次借用巨鹰之眼那敏锐的视力。', `MaleText_loc5`='很好。你再次獲得她銳利的視覺。', `MaleText_loc7`='Muy bien. Te otorga su aguda vista de nuevo.' WHERE `ID`=27345;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호박석 절벽으로 순간이동시켜 주십시오.', `MaleText_loc4`='请将我传送到琥珀崖。', `MaleText_loc5`='麻煩你把我傳送至琥珀岩臺。', `MaleText_loc7`='Por favor, teletranspórtame a El Saliente Ámbar.', `FemaleText_loc1`='호박석 절벽으로 순간이동시켜 주세요.', `FemaleText_loc4`='请将我传送到琥珀崖。', `FemaleText_loc5`='麻煩你把我傳送至琥珀岩臺。', `FemaleText_loc7`='Por favor, teletranspórtame a El Saliente Ámbar.' WHERE `ID`=27346;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전 깡총 군이랑 산책하러 나왔는데 중간에 길을 잃어버렸어요. 게다가 늑대들이 막 쫓아와서 너무 무서웠어요. 다행히 이 탑이 보여서 저랑 깡총 군이랑 이 안에 숨은 거예요. 늑대들은 결국 다 사라졌는데, 정말 무서웠고요, 우린 이제 집에 돌아가는 길도 몰라요.', `FemaleText_loc4`='本来呢我是带小毛球出来散步的走着走着就迷了路，你也知道这附近有狼群出没呀没想到真被我们给撞上啦，我抱起小毛球撒开脚丫没命地逃就在我近乎绝望的时候眼前出现了一座哨塔！我们迅速躲进塔内惊魂未定地熬了许久直到外面的狼群悻悻地离开才松了一口气……这段经历真是太可怕啦而且我们还不知道回家的路。', `FemaleText_loc5`='軟綿綿先生和我出來散步，但我們卻迷了路。我真的好害怕，你知道的，這裡有狼，它們一直追著我們，但我看見了這座塔。我和軟綿綿先生就躲在這裡，直到那些狼離去。那真的好恐怖，而且我現在不知道該怎麼回家。', `FemaleText_loc7`='Floppy y yo salimos a dar un paseo, pero nos perdimos y yo tenía mucho miedo porque había lobos, ya sabes... y nos perseguían, pero entonces vimos esta torre y Floppy y yo nos escondimos aquí y después de un rato los lobos se marcharon y ha sido terrible y no sabemos volver a casa.' WHERE `ID`=27347;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다른 데로 가주시면 안 될까요? 깡총 군이 무서워하고 있어요.', `FemaleText_loc4`='你最好马上离开。你吓到小毛球啦！', `FemaleText_loc5`='我認為你應該離開，$g先生:小姐;。你嚇到軟綿綿先生了。', `FemaleText_loc7`='Creo que debería marcharse, $gseñor:señorita;. Está asustando a Floppy.' WHERE `ID`=27348;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 곳으로 날아가게 비룡을 태워 주실 수 있을까요?', `MaleText_loc4`='我能飞去其他地方吗？', `MaleText_loc5`='我可以借用一隻飛龍飛到別的地方去嗎?', `MaleText_loc7`='¿Puedo usar un draco para volar a otro lugar?', `FemaleText_loc1`='다른 곳으로 날아가게 비룡을 태워 주실 수 있을까요?', `FemaleText_loc4`='我能飞去其他地方吗？', `FemaleText_loc5`='我可以借用一隻飛龍飛到別的地方去嗎?', `FemaleText_loc7`='¿Puedo usar un draco para volar a otro lugar?' WHERE `ID`=27349;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무엇을 도와드릴까요?', `MaleText_loc4`='有什么能帮忙的吗？', `MaleText_loc5`='有什麼我能幫忙的嗎，孩子?', `MaleText_loc7`='¿Cómo puedo ayudarte, $gniño:niña;?', `FemaleText_loc1`='무엇을 도와드릴까요?', `FemaleText_loc4`='有什么能帮忙的吗？', `FemaleText_loc5`='有什麼我能幫忙的嗎，孩子?', `FemaleText_loc7`='¿Cómo puedo ayudarte, $gniño:niña;?' WHERE `ID`=27350;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고집이냐, 어리석음이냐? 상관없다. 이 일을 교훈으로 삼아라, 필멸자여.', `MaleText_loc4`='这是毅力还是愚蠢？无所谓了。铭记这个教训吧，凡人！', `MaleText_loc5`='是堅持或是愚蠢?都無所謂。好好記住這個教訓，凡人!', `MaleText_loc7`='¿Persistencia o estupidez? No importa. Que te sirva de lección, mortal.' WHERE `ID`=27351;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고룡쉼터 사원에 온 것을 환영합니다, $r|1이여;여;. 바깥이 소란스러운 것에 미리 양해를 구하는 바입니다. 말리고스의 군대에 지금 포위당한 상황이거든요. 그러나 우리가 이곳을 잘 보호하고 있으니 원한다면 쉬어 가셔도 됩니다.', `MaleText_loc4`='欢迎来到龙眠神殿，$r。希望神殿外的骚乱没有为你带来任何困扰；最近玛里苟斯展开了一系列的行动，龙眠神殿已经被包围了。不过你还是可以安心地待在这儿，我们会确保你的安全。', `MaleText_loc5`='歡迎你來龍眠神殿，$r。請原諒外頭的騷動;最近瑪里苟斯的舉動，我們發現被團團包圍了。你若是需要的話，你可以在我們的戒護之下進行休息。', `MaleText_loc7`='Te doy la bienvenida al Templo del Reposo del Dragón, $r. Disculpa la conmoción de fuera. Con los recientes actos de Malygos, nos hemos visto asediados. De todas formas, podrás descansar aquí bajo nuestra protección si te hace falta.' WHERE `ID`=27352;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쯧쯧, 별것도 아니지 않은가!', `MaleText_loc4`='肃清敌军！', `MaleText_loc5`='嘖嘖，那個會一點都不留!', `MaleText_loc7`='Psé, psé, ¡no pasará nada así!' WHERE `ID`=27353;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해치워, 아벤디스! 날 실망시키지 마라!', `MaleText_loc4`='阿比迪斯，杀光他们！别让我失望！', `MaleText_loc5`='阿比迪斯，殺光他們!別讓我失望!', `MaleText_loc7`='¡Mátalos, Abbendis! ¡No me falles!' WHERE `ID`=27354;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제독이 눈을 가늘게 뜨고 잠시 당신을 관찰합니다.', `MaleText_loc4`='海军上将眯起眼睛，仔细地打量着你。', `MaleText_loc5`='上將瞇著眼睛打量著你好一會兒。', `MaleText_loc7`='El Gran almirante te escrudiña por un momento minuciosamente.' WHERE `ID`=27355;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='목적은 이뤘구나.', `MaleText_loc4`='你已经体现了自己的价值。', `MaleText_loc5`='你已經充分發揮功用了。', `MaleText_loc7`='Cumpliste tu objetivo.' WHERE `ID`=27357;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼음왕관에서 보자... 네놈들이 그때까지 산다면 말이다!', `MaleText_loc4`='到冰冠冰川来找我吧，懦夫……如果你们还能活着到那里的话！', `MaleText_loc5`='寒冰皇冠見...如果你們這些廢物活的夠久的話!', `MaleText_loc7`='Te veré en Corona de Hielo, debilucho... ¡si vives lo suficiente!' WHERE `ID`=27358;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스컬지의 군대가 우리를 무너트리려 합니다. 마음을 다잡고 싸워나가야 합니다!', `MaleText_loc4`='天灾军团如潮水般向我们涌来。战斗吧！', `MaleText_loc5`='天譴軍的勢力逐漸進逼。鼓起勇氣，準備迎戰!', `MaleText_loc7`='Las fuerzas de la Plaga intentan aniquilarnos. ¡No desesperéis y seguid luchando!', `FemaleText_loc1`='스컬지의 군대가 우리를 무너트리려 합니다. 마음을 다잡고 싸워나가야 합니다!', `FemaleText_loc4`='天灾军团如潮水般向我们涌来。战斗吧！', `FemaleText_loc5`='天譴軍的勢力逐漸進逼。鼓起勇氣，準備迎戰!', `FemaleText_loc7`='Las fuerzas de la Plaga intentan aniquilarnos. ¡No desesperéis y seguid luchando!' WHERE `ID`=27359;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='희망을 버리지 마십시오. 신념이 있다면 이 어둠을 헤치고 언젠가 다가오는 여명을 볼 수 있을 겁니다.', `MaleText_loc4`='不要放弃希望。只要我们心怀坚定的信仰，就能走出这片黑暗，迎接黎明的曙光。', `MaleText_loc5`='不要氣餒，$g孩子:女孩;。只要有信念，我們會度過這片黑暗，再次見到黎明。', `MaleText_loc7`='No pierdas la esperanza, $ghijo mío:hija mía;. Con fe lograremos caminar a través de esta oscuridad y ver otro amanecer.', `FemaleText_loc1`='희망을 버리지 마십시오. 신념이 있다면 이 어둠을 헤치고 언젠가 다가오는 여명을 볼 수 있을 겁니다.', `FemaleText_loc4`='不要放弃希望。只要我们心怀坚定的信仰，就能走出这片黑暗，迎接黎明的曙光。', `FemaleText_loc5`='不要氣餒，$g孩子:女孩;。只要有信念，我們會度過這片黑暗，再次見到黎明。', `FemaleText_loc7`='No pierdas la esperanza, $ghijo mío:hija mía;. Con fe lograremos caminar a través de esta oscuridad y ver otro amanecer.' WHERE `ID`=27360;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 반드시 저항해야 합니다! 마음을 굳게 먹으십시오! 더러운 역병은 눈에 보이는 대로 불태워 버리십시오!', `MaleText_loc4`='坚持！做好准备！一旦发现污秽，立即烧毁它！', `MaleText_loc5`='我們必須撐住!振奮起你們的精神!燒掉所有被發現的惡毒瘟疫!', `MaleText_loc7`='¡Debemos resistir! ¡No perdáis la esperanza! ¡Quemad la hedionda peste allí donde la encontréis!', `FemaleText_loc1`='우리는 반드시 저항해야 합니다! 마음을 굳게 먹으십시오! 더러운 역병은 눈에 보이는 대로 불태워 버리십시오!', `FemaleText_loc4`='坚持！做好准备！一旦发现污秽，立即烧毁它！', `FemaleText_loc5`='我們必須撐住!振奮起你們的精神!燒掉所有被發現的惡毒瘟疫!', `FemaleText_loc7`='¡Debemos resistir! ¡No perdáis la esperanza! ¡Quemad la hedionda peste allí donde la encontréis!' WHERE `ID`=27361;
