UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명상을 한다고 날 떨쳐버릴 수 있을 것 같으냐?', `MaleText_loc4`='你以为冥想能帮助你洗涤内心的杂念吗？', `MaleText_loc5`='你想要以冥想擺脫我?', `MaleText_loc7`='¿Crees que te podrás librar de mí con meditación?', `FemaleText_loc1`='명상을 한다고 날 떨쳐버릴 수 있을 것 같으냐?', `FemaleText_loc4`='你以为冥想能帮助你洗涤内心的杂念吗？', `FemaleText_loc5`='你想要以冥想擺脫我?', `FemaleText_loc7`='¿Crees que te podrás librar de mí con meditación?' WHERE `ID`=27368;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어리석도다! 너를 파멸시키고 지난 세월동안 네 안에서 쌓아올린 존재가 되어주마!', `MaleText_loc4`='蠢货！我要彻底摧毁你，成为你内心世界真正的主宰！', `MaleText_loc5`='愚蠢!我會毀掉你，最終成為多年以來一直潛伏在你身體裡的那一位!', `MaleText_loc7`='¡Idiota! ¡Acabaré contigo y me convertiré en lo que lleva creciendo dentro de ti todos estos años!', `FemaleText_loc1`='어리석도다! 너를 파멸시키고 지난 세월동안 네 안에서 쌓아올린 존재가 되어주마!', `FemaleText_loc4`='蠢货！我要彻底摧毁你，成为你内心世界真正的主宰！', `FemaleText_loc5`='愚蠢!我會毀掉你，最終將成為多年以來一直潛伏在你身體裡的那一位!', `FemaleText_loc7`='¡Idiota! ¡Acabaré contigo y me convertiré en lo que lleva creciendo dentro de ti todos estos años!' WHERE `ID`=27369;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 나를 꺾을 수 없다. 난 절대로 떼어놓을 수 없는 너의 일부니까!', `MaleText_loc4`='别想打败我。我是你身体不可分割的一部分！', `MaleText_loc5`='你不可能打敗我的。我是你無可分割的一部分!', `MaleText_loc7`='No puedes derrotarme. ¡Soy una parte inseparable de ti!', `FemaleText_loc1`='넌 나를 꺾을 수 없다. 난 절대로 떼어놓을 수 없는 너의 일부니까!', `FemaleText_loc4`='别想打败我。我是你身体不可分割的一部分！', `FemaleText_loc5`='你不可能打敗我的。我是你無可分割的一部分!', `FemaleText_loc7`='No puedes derrotarme. ¡Soy una parte inseparable de ti!' WHERE `ID`=27370;
