UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘하셨습니다.', `MaleText_loc4`='干得不错。', `MaleText_loc5`='孩子，幹得好。', `MaleText_loc7`='Bien, peque.' WHERE `ID`=27373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='푸른용 하나를 또 잡았군요. 그대와 나는 좋은 짝인 것 같습니다!', `MaleText_loc4`='又一只蓝龙倒下啦。我们的配合真是天衣无缝！', `MaleText_loc5`='殺死另一頭藍龍啦。我們合作無間!', `MaleText_loc7`='Otro azul menos. ¡Formamos un buen equipo!' WHERE `ID`=27374;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대와 내가 함께라면 이 전투도 금방 끝날 겁니다.', `MaleText_loc4`='只要我们通力合作，这场战争很快就能分出胜负。', `MaleText_loc5`='只要我和你合作，這場戰爭馬上就結束了。', `MaleText_loc7`='Uniendo fuerzas tú y yo, esta batalla no durará mucho.' WHERE `ID`=27375;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$r|1을;를; 태우고 전투를 치르리라고는 생각도 못 해봤습니다.', `MaleText_loc4`='我从来没有想过自己会载着一名$r投身战斗。', `MaleText_loc5`='我從來沒想過會有一隻$r坐在我背上衝鋒陷陣。', `MaleText_loc7`='Nunca pensé que cabalgaría hacia la batalla con $gun:una; $r sobre el lomo.' WHERE `ID`=27376;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 녀석을 쓰러뜨려 주셔서 기쁘군요!', `MaleText_loc4`='还好你留意到那只蓝龙啦！', `MaleText_loc5`='很高興你看到那招!', `MaleText_loc7`='¡Menos mal que lo viste!' WHERE `ID`=27377;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꽉 붙잡으십시오. 재빠르게 임무를 완수해야지요.', `MaleText_loc4`='抓紧。让我们勇敢地迎接挑战吧。', `MaleText_loc5`='撐著點，我們會熬過這些攻擊的。', `MaleText_loc7`='Aguanta. Saldremos de esta.' WHERE `ID`=27378;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 건 본 적이 없습니다. 그대와 함께 있어 다행입니다.', `MaleText_loc4`='我从未见过这样的场面。有你陪同真是太好了。', `MaleText_loc5`='我以前從來沒有看過類似的事情。我很開心你在這裡。', `MaleText_loc7`='Nunca había visto algo así. Me alegro de que estés aquí.' WHERE `ID`=27379;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말리고스는 미친 것이 분명합니다.', `MaleText_loc4`='玛里苟斯显然是疯了。', `MaleText_loc5`='瑪里苟斯真的已經發瘋了。', `MaleText_loc7`='No hay duda de que Malygos ha perdido la cabeza.' WHERE `ID`=27380;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 눈을 멀게 하는 벌레무리를 바로 앞으로 불러들입니다.', `MaleText_loc4`='%s指挥着前方遮天蔽日的虫群大军。', `MaleText_loc5`='%s引導著它前方的眩目蟲群。', `MaleText_loc7`='El %s dirige el enjambre cegador justo ante él.' WHERE `ID`=27381;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 공포가 닥쳐올지 모르는군. 지금까진 아무것도 아니다. 기다리고 있노라. 낙스라마스의 얼어붙은 심장이!', `MaleText_loc4`='看来你们还不知道自己将面临怎样的恐怖？看来你们根本一无所知！纳克萨玛斯的霜寒之心正等待着你们！', `MaleText_loc5`='看來你們還不知道自己將面臨怎樣的恐怖?看來你們根本一無所知!納克薩瑪斯的霜寒之心正等待著你們!', `MaleText_loc7`='No tienen idea de los espantos que acechan. ¡No han visto nada! ¡El corazón gélido de Naxxramas los espera!' WHERE `ID`=27382;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까!$b$b당신이 궂은 일이라도 마다하지 않으셨으면 좋겠군요. 일손이 절실히 필요합니다.', `MaleText_loc4`='你好，$c！$b$b希望你能胜任艰苦的工作。我们的人手紧张，非常需要帮助。', `MaleText_loc5`='你好，$c!$b$b我希望你不要介意做些粗重的工作。我們真的需要一些協助。', `MaleText_loc7`='¡Saludos, $c!$b$bEspero que no te moleste el trabajo duro. Nos vendría bien un poco de ayuda.' WHERE `ID`=27383;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='바람과 나무가 보이지 않는 위험을 알려주는군요. 이 대지는 겉으로는 건강해 보이지만, 눈이 닿지 않는 곳에서는 다른 일이 일어나고 있어요.', `FemaleText_loc4`='凛风与森林低声诉说着隐忧。这片看似生机勃勃的土地其实隐藏着莫大的危机。', `FemaleText_loc5`='風和樹低語著無形的煩擾。大地看起來健康，但許多眼睛所看不見的正悄悄發生著。', `FemaleText_loc7`='Los vientos y los árboles hablan en susurros de nuevos problemas. La tierra parece saludable, pero está sucediendo algo que no se ve a primera vista.' WHERE `ID`=27384;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='<타이렌이 멍한 눈동자로 바라봅니다. 타락한 볼드랏실을 정화하는 작업은 이 드루이드에게서 그에 상응하는 무언가를 빼앗아 갔습니다.>', `FemaleText_loc4`='<塞瑞恩的眼神异常空洞。为了净化沃达希尔，她似乎耗尽了全部精力。>', `FemaleText_loc5`='<賽苓雙眼無神。淨化沃達希爾的腐化對這位德魯伊造成了不好的影響。>', `FemaleText_loc7`='<La mirada de Thayreen está vacía. La eliminación de la corrupción de Vordrassil no ha sido gratuita.>' WHERE `ID`=27385;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드를 위한 가죽일세, 친구! 우리 병사들에게는 오직 최고만을 쓰지!', `MaleText_loc4`='朋友，我们会为部落提供最优质的皮革！', `MaleText_loc5`='給部落最好的皮革，老兄!只有最好的才能提供給我軍!', `MaleText_loc7`='¡Pellejos de la Horda! ¡Para nuestras tropas, solo lo mejor!' WHERE `ID`=27386;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여행용 보급품은 어떤가? 전투를 구경하면서 먹을 수 있는 간식은?', `MaleText_loc4`='买点干粮在路上吃？或者观战的时候也可以喝上一杯？', `MaleText_loc5`='需要帶點補給品上路嘛?當你觀賞拳賽的時候，要不要來點提神的?', `MaleText_loc7`='¿Suministros para el camino? ¿Quizá algo para tomar mientras observas las luchas?' WHERE `ID`=27387;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적들이 사방에서 몰려오고, 장로들은 야영지를 떠나자는 이야기만 하고 있소. 하지만 난 우리의 본래 모습인 전사답게 녀석들과 맞서 싸워야 한다고 생각하오.', `MaleText_loc4`='敌人从四面八方向我们逼近，长老们都认为应该放弃这座岗哨。但是我认为我们应该留下来，勇敢地与敌人抗衡。', `MaleText_loc5`='敵人從四面八方逼近，所有的長者談論著放棄崗哨的問題。我說，我們應該挺身而出，如同我們戰士的身分奮戰到底。', `MaleText_loc7`='Los enemigos se acercan por todos los flancos y todos los ancestros hablan de abandonar este puesto. Yo digo que deberíamos quedarnos y luchar como los guerreros que somos.' WHERE `ID`=27388;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가장 큰 도전이 눈앞에 있습니다. 지맥 수호자 에레고스는 엄청난 힘을 지닌 푸른용입니다. 에레고스는 꼭대기 고리 위를 선회하고 있을 것입니다.', `MaleText_loc4`='你即将面临新一轮的挑战。魔网守护者埃雷苟斯拥有可怕的力量。他就在魔枢顶层盘旋。', `MaleText_loc5`='你的最大挑戰正等著你。地脈守護者伊瑞茍斯是一頭力大無窮的藍龍。你會在最上環的上方飛行遇到牠。', `MaleText_loc7`='El mayor de tus desafíos aún está por llegar. El Guardián-Ley Eregos es un dragón Azul de inmenso poder. Lo encontrarás sobrevolando el anillo superior.' WHERE `ID`=27389;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼음안개 마을 안에서만 비행할 수 있습니다.', `MaleText_loc4`='你只能在冰雾村上空飞翔。', `MaleText_loc5`='你只能在冰霧村上空飛行。', `MaleText_loc7`='Solo puedes volar en el Poblado Bruma de Hielo.' WHERE `ID`=27390;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$r|1이여;여;, 당신은 여기 있어서는 안 돼요.', `FemaleText_loc4`='$r，你不应该来这里的。', `FemaleText_loc5`='你實在不該在這的，$r。', `FemaleText_loc7`='De verdad que no deberías estar aquí, $r.' WHERE `ID`=27391;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$r|1이여;여;, 그대는 여기 있어서는 안 되오. 목숨이 아깝거든 바로 떠나시오.', `MaleText_loc4`='$r，你不应该来这里的。想活命的话，赶紧离开吧。', `MaleText_loc5`='你實在不該在這的，$r。如果你珍惜你的生命，馬上離開。', `MaleText_loc7`='De verdad que no deberías estar aquí, $r. Márchate si aprecias la vida.' WHERE `ID`=27392;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전장으로 돌아가지 않으면 용이 당신을 떨어트릴 겁니다!', `MaleText_loc4`='返回战场，否则巨龙会将你甩下去！', `MaleText_loc5`='重返戰場，否則你的龍會丟下你!', `MaleText_loc7`='¡Vuelve al campo de batalla o tu dragón te dejará caer!' WHERE `ID`=27393;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 넓은 지역 곳곳에는 조상님들의 뼈가 잠들어 있습니다. 그 영혼은 승천해서 위상의 방에 거하지요.', `MaleText_loc4`='这片广袤的土地便是巨龙先祖的埋骨地。他们的灵魂已经升华，在龙神之厅中享受着永恒的宁静。', `MaleText_loc5`='放眼望去一片廣袤無垠的地方長眠著我的先祖的骸骨。他們的靈魂早已超脫飛向守護巨龍之間。', `MaleText_loc7`='Los huesos de mis ancestros se encuentran repartidos por esta vasta extensión de tierra. Sus espíritus han ascendido a la Cámara de los Aspectos.' WHERE `ID`=27394;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스컬지가 이곳에서 저지른 일은 곧 세계 모든 곳에 영향을 미칠 겁니다. 놈들을 반드시 막아야 합니다!', `MaleText_loc4`='天灾军团的行径将会世界造成不可挽回的恶劣影响。必须阻止他们！', `MaleText_loc5`='天譴軍在此所做的一切將影響整個世界。這些畸形生物一定要被阻止!', `MaleText_loc7`='Lo que la Plaga ha hecho aquí reverberará a través del mundo. ¡Debemos detener a las aberraciones!' WHERE `ID`=27395;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갈라크론드는 용족의 선조입니다. 티탄은 갈라크론드에게서 다섯 위상을 만들어 냈지요.', `MaleText_loc4`='迦拉克隆是龙族的祖先。泰坦以它为雏形，甄选了五条巨龙来守护艾泽拉斯世界。', `MaleText_loc5`='葛拉克朗是龍族的初祖。泰坦在葛拉克朗塑造出了五頭守護巨龍。', `MaleText_loc7`='Galakrond era el progenitor de la especie de los dragones. Los titanes dieron forma a los cinco Aspectos gracias a Galakrond.' WHERE `ID`=27396;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 아직 성숙한 고룡이 아니라는 사실을 잊지 마십시오. 힘을 보충하려면 뭔가 먹어야 합니다!', `MaleText_loc4`='我还没有完全成熟，必须依赖进食来强化自身的力量。', `MaleText_loc5`='你一定要記住，我還未長成為一頭年長巨龍。我必須吃更多來恢復我的力量!', `MaleText_loc7`='Debes recordar que aún tengo que madurar y convertirme en una vermis adulta. Debo comer para recuperar fuerzas.' WHERE `ID`=27397;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘은 좋은 날이군요, 친구여. 고룡쉼터 사원을 떠나 용의 안식처를 자유롭게 날아다니는 것은 참으로 오랜만입니다.', `MaleText_loc4`='朋友，今天真是个美好的日子。我一直待在龙眠神殿，已经很久没有在龙骨荒野上空自由飞翔了。', `MaleText_loc5`='朋友，今天是個好日子。我已經離開龍眠神殿好一陣子了，你可以隨意飛越巨大的龍骨荒野。', `MaleText_loc7`='Hoy es un gran día. Hace mucho que salí del Templo del Reposo del Dragón, libre para sobrevolar el gran Cementerio de Dragones.' WHERE `ID`=27398;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여왕님과 의회는 최근 들어 울두아르에서 벌어진 재앙에 대해 논의하고 계십니다. 폭풍우 봉우리에서 무슨 일인가 벌어진 게 분명합니다!', `MaleText_loc4`='最近，女王陛下召集议会谈论了奥杜尔遭遇的一场灾难。风暴峭壁似乎出了什么大事！', `MaleText_loc5`='皇后和她的議會最近討論著奧杜亞發生的災難。某些事情已經發生在風暴群山中了!', `MaleText_loc7`='La reina y su consejo últimamente hablan de un desastre en Ulduar. ¡Algo ha ocurrido en Las Cumbres Tormentosas!' WHERE `ID`=27399;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='푸른용군단이 그토록 무자비하고 냉혹한 길을 택한 것은 참으로 유감입니다. 말리고스의 자식들과 싸워야 한다니 가슴이 아프군요.', `MaleText_loc4`='蓝龙军团竟然选择了如此残酷而冷血的道路，整个龙族都因此蒙羞。我却不得不与玛里苟斯的子嗣交战，做出这样的决定真令我痛心。', `MaleText_loc5`='藍龍軍團選擇了如此一條冷酷無心的道路，真是一件羞恥的事情。必需要和瑪里苟斯的子嗣作戰讓我萬分煎熬。', `MaleText_loc7`='Realmente es una vergüenza que el Vuelo Azul haya elegido un camino tan cruel y frío. Me duele muchísimo luchar contra los hijos de Malygos.' WHERE `ID`=27400;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드라쿠루가 드락타론 성채를 바라봅니다...', `MaleText_loc4`='达库鲁将目光投向达克萨隆要塞……', `MaleText_loc5`='德拉庫魯將他的目光投向了德拉克薩隆要塞...', `MaleText_loc7`='Drakuru lanza una mirada hacia la Fortaleza de Drak''Tharon…' WHERE `ID`=27402;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘했네, 친구.', `MaleText_loc4`='你做得很好。', `MaleText_loc5`='做的好，老兄。', `MaleText_loc7`='Bien hecho.' WHERE `ID`=27403;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고룡쉼터 사원으로 돌아오라는 명령을 받았습니다. 안녕히 가십시오!', `MaleText_loc4`='朋友，我必须返回龙眠神殿了。再见！', `MaleText_loc5`='盟友，我已被喚回龍眠神殿。再會!', `MaleText_loc7`='Me han pedido que vuelva al Reposo del Dragón. ¡Adiós!' WHERE `ID`=27404;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 빨리 파내라! 침입자 녀석들에게 숨 돌릴 틈을 줘서는 안 되지!', `MaleText_loc4`='奴仆们，快！绝不能给敌人任何喘息的机会！', `MaleText_loc5`='動作快，畜生!我們不能減弱對入侵者的攻勢!', `MaleText_loc7`='¡Más rápido, perros! ¡No debemos cesar en nuestro acoso a los intrusos!' WHERE `ID`=27405;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곧 갈라크론드의 뼈가 영원의 잠에서 깨어나 온 세상에 재앙을 내릴 것이다!', `MaleText_loc4`='迦拉克隆的骸骨很快就要从永恒的长眠中觉醒，为世界带来一场残酷的浩劫！', `MaleText_loc5`='很快的，葛拉克朗的骨骸將會從他們的永恆沉睡中喚醒，肆虐這個世界!', `MaleText_loc7`='¡Pronto los huesos de Galakrond se elevarán de su sueño eterno y sembrarán el caos en este mundo!' WHERE `ID`=27406;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 말을 들어라! 너희 주인 안티오크의 말을 들어라! 두 배로 일해라. 그렇지 않으면 패배로써 대가를 치르게 될 것이다!', `MaleText_loc4`='奴仆们！听从我的号令吧！通灵主宰命令你们：肃清敌人，否则你们要为失败付出惨痛的代价！', `MaleText_loc5`='聽我說，我的手下!聽從你的主人，安提歐克!加倍你們的努力，否則就為失敗的結果付出代價。', `MaleText_loc7`='¡Escúchenme, esbirros! ¡Escuchen a su señor, Antiok! ¡Redoblen sus esfuerzos o pagarán las consecuencias del fracaso!' WHERE `ID`=27407;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕께서는 더 많은 서리고룡을 앙그라타르로 보내길 원하신다! 그분의 기대에 보답하지 않는 놈은 내 분노와 대면하게 되리라!', `MaleText_loc4`='巫妖王下令继续向天谴之门安加萨调派冰霜巨龙！服从指令，否则就尝尝我的厉害！', `MaleText_loc5`='巫妖王命令更多的冰霜巨龍送往安格拉薩!完成他的命令不然就吃我的怒火吧!', `MaleText_loc7`='¡El Rey Exánime desea se envíen más vermis de escarcha a Angrathar! ¡Haz realidad sus deseos o te enfrentarás a mi cólera!' WHERE `ID`=27408;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 우리를 공격하고 있다! 한 놈도 이 고대 묘지에 들이지 마라!', `MaleText_loc4`='敌人发动了攻击！禁止任何人穿越这座古老的陵墓！', `MaleText_loc5`='進攻者就在我們頭上!不要讓任何人通過這座古老墓地!', `MaleText_loc7`='¡Los agresores atacan! ¡Que ninguno llegue a esta antigua tumba!' WHERE `ID`=27409;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안티오크의 낫이 땅에 떨어집니다!', `MaleText_loc4`='安提沃克的镰刀跌落在地！', `MaleText_loc5`='安提歐克的鐮刀落到了地上!', `MaleText_loc7`='¡La guadaña de Antiok cae al suelo!' WHERE `ID`=27410;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디 보자... 마법의 지배자께 반항하는 자들인가? 이해력도, 통찰력도 없는 것들... 어떻게 해야 알겠느냐? 말리고스 님은 세상을 근본적으로 구하고 계신단 말이다! 하! 말해 봐야 입만 아프지!', `MaleText_loc4`='看看是谁来了？一群公然蔑视并挑战织法者的狂徒？一群完全缺乏理解与远见的蠢货。我怎样才能让你们看清这真相呢？玛里苟斯是在拯救这个世界！咳，我为什么要跟你们废话？', `MaleText_loc5`='看看是誰來了?一群公然蔑視並挑戰織法者的狂徒?一群完全缺乏理解與遠見的蠢貨。我怎樣才能讓你們看清真相呢?瑪里苟斯是在拯救這個世界!咳，我為什麼要跟你們廢話?', `MaleText_loc7`='¿Qué tenemos aquí... los que desafían al Tejehechizos? Aquellos sin previsión ni comprensión. ¿Cómo puedo hacerlos comprender? ¡Malygos está salvando al mundo de sí mismo! ¡Bah! ¡Ustedes no merecen mi tiempo!' WHERE `ID`=27411;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어리석은 족속들!', `MaleText_loc4`='可怜而无知的蠢货！', `MaleText_loc5`='可憐而無知的蠢貨!', `MaleText_loc7`='¡Pobres necios!' WHERE `ID`=27412;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 부하들이 쓰러졌구나. 하지만 또 다른 녀석들이 등장할 게다.', `MaleText_loc4`='显然，我的宠物们失败了。看来还得另外安排一次示范。', `MaleText_loc5`='顯然，我的寵物們失敗了。看來還得另外安排一次示範。', `MaleText_loc7`='Mis mascotas fracasaron. Quizás haga falta otra demostración.' WHERE `ID`=27413;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여전히 반항이냐. 여전히 잘못된 신념에 매달리느냐. 이번에도 살아남는다면, 중심원에서 날 찾을 수 있을 게다.', `MaleText_loc4`='你们还要打下去吗？你们仍然遵守着被扭曲的教条吗？如果你们能活下来，就到中央的圆环中找我吧。', `MaleText_loc5`='你們還在繼續頑抗。你們還是遵守著被扭曲的原則。要是你們能活下來的話。你們會在中央之環找到我。', `MaleText_loc7`='Aún luchan. Aún se aferran a principios equivocados. Si sobreviven, me encontrarán en el círculo central.' WHERE `ID`=27414;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필멸자여, 네놈이 이길 수 있다고 생각하나? 굴레를 벗은 안티오크의 힘을 보여주마!', `MaleText_loc4`='你以为自己嬴了，是吗？尝尝安提沃克的怒火吧！', `MaleText_loc5`='你以為贏得了我嗎，凡人?面對安提歐克脫韁的力量吧!', `MaleText_loc7`='¿Crees que has ganado, mortal? ¡Haz frente al poder desenfrenado de Antiok!' WHERE `ID`=27415;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보아라! 안티오크의 낫이다!', `MaleText_loc4`='瞧！安提沃克的镰刀！', `MaleText_loc5`='看吶!安提歐克的鐮刀!', `MaleText_loc7`='¡Contempla la guadaña de Antiok!' WHERE `ID`=27416;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 비행기는 놈리건의 정신호라고 해요. 멋지지 않나요? 당신이 도와주지 않았다면 고치지 못했을 거예요.', `MaleText_loc4`='我将她称作诺莫瑞根之魂。她很漂亮，不是吗？要不是你帮忙，她也不可能恢复原貌。', `MaleText_loc5`='我稱她作『諾姆瑞根之靈』。她不是很漂亮嗎?要是沒有你的幫忙，她永遠也不用想被復原了。', `MaleText_loc7`='La llamaré el espíritu de Gnomeregan. ¿No es hermosa?' WHERE `ID`=27417;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아요! 그럼 어디 독한 맥주를 마셔 볼까요...', `MaleText_loc4`='好！让我们来尝尝这个所谓的烈酒……', `MaleText_loc5`='好吧!讓我們來試試這所謂的恐酒...', `MaleText_loc7`='¡Bien! Probemos la famosa cerveza temible...' WHERE `ID`=27418;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='브론즈비어드의 수염이여! 이거 정말 끝내주는데요!', `MaleText_loc4`='天啊！真是好酒！', `MaleText_loc5`='銅鬚的鬍子啊!這酒太棒啦!', `MaleText_loc7`='¡Por las barbas de Barbabronce! ¡Qué bebida!' WHERE `ID`=27419;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모든 사람이 코렌의 독한 맥주를 맛볼 수 없다는 게 아쉽군요! 불경스러운 말인 줄은 알지만, 검은무쇠 드워프 녀석들이 부러울 정도라고요!', `MaleText_loc4`='真可惜，科林的烈酒不能在广大啤酒爱好者中推广开来！我知道这么说可能不合适，但我真的很嫉妒那些黑铁矮人！', `MaleText_loc5`='真是可惜，寇仁的恐酒沒辦法滿足每一條酒蟲的嘴!我知道這聽起來褻瀆我的族人，但是我超羨慕黑鐵矮人的!', `MaleText_loc7`='¡Es una pena que la cerveza temible de Coren no pueda saciar más gargantas secas! ¡Es una blasfemia, pero envidio a esos enanos Hierro Negro!' WHERE `ID`=27420;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 이 맥주는... 가을 축제에 나온 맥주 중에서 최고일지도 몰라요!', `MaleText_loc4`='$n，这啤酒……好吧，它可能是美酒节上最好的酒了！', `MaleText_loc5`='$n，這啤酒...這麼說吧，這應該是啤酒節最好的酒!', `MaleText_loc7`='$n, esta cerveza... Bueno, puede que sea la mejor de la Fiesta.' WHERE `ID`=27421;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은빛십자군 격전지에 오신 것을 환영합니다.$b$b편하게 지내시되, 너무 해이해지진 마십시오. 숲을 벗어나려면 아직 멀었으니까 말입니다.$b$b이곳에서 무사히 나가려면 각자 맡은 일을 잘해줘야 합니다. 물론 당신도 마찬가지고요.', `MaleText_loc4`='欢迎来到银色前沿，$c。$b$b你可以将这里当作自己的家，不过别太放松啦。我们仍处于危险的丛林深处。$b$b要想所有人都安全地走出这片森林，就必须同心协力……你也一样。', `MaleText_loc5`='歡迎來到銀白看臺，$c。$b$b請把這裡當自己家，但是別安逸過了頭。我們還沒穿過樹林 - 還差得遠了。$b$b如果我們要能全身而退，每個人都要盡自己的本分...你也不例外。', `MaleText_loc7`='$gBienvenido:Bienvenida; a El Confín Argenta, $c.$b$bEstás en tu casa, pero no te acomodes demasiado. Aún no estamos a salvo... y lo que nos queda.$b$bSi queremos salir de aquí de una pieza, tendremos que ayudar todos... tú también.' WHERE `ID`=27422;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공포의 선장 드메자 님께서 무법항으로 들어와 해적의 날을 선포했습니다!$B$B드메자 선장님과 한 잔 나눌 용기가 있다면 누구나 명예 선원으로 임명됩니다.', `MaleText_loc4`='恐怖船长德梅萨已经进驻藏宝海湾并宣布这一天为海盗节！$B$B她邀请所有敢于前往的人与船员们一起开怀畅饮。', `MaleText_loc5`='驚懼船長狄米撒駛進了藏寶海灣，宣布今天是海賊日!$B$B任何有勇氣跟她喝一杯酒的人都可以當她的榮譽船員。', `MaleText_loc7`='¡La aterradora capitana DeMeza ha amarrado en Bahía Botín y ha declarado que hoy es el Día de los Piratas!$b$bCualquiera que se atreva a compartir un trago con ella, será nombrado tripulante honorífico.', `FemaleText_loc1`='공포의 선장 드메자 님께서 무법항으로 들어와 해적의 날을 선포했어요!$B$B드메자 선장님과 한 잔 나눌 용기가 있다면 누구나 명예 선원으로 임명될 거예요.', `FemaleText_loc4`='恐怖船长德梅萨已经进驻藏宝海湾并宣布这一天为海盗节！$B$B她邀请所有敢于前往的人与船员们一起开怀畅饮。', `FemaleText_loc5`='驚懼船長狄米撒駛進了藏寶海灣，宣布今天是海賊日!$B$B任何有勇氣跟她喝一杯酒的人都可以當她的榮譽船員。', `FemaleText_loc7`='¡La aterradora capitana DeMeza ha amarrado en Bahía Botín y ha declarado que hoy es el Día de los Piratas!$b$bCualquiera que se atreva a compartir un trago con ella, será nombrado tripulante honorífico.' WHERE `ID`=27423;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여긴 아주 엉망이랍니다.', `MaleText_loc4`='我们的处境非常狼狈。', `MaleText_loc5`='這裡真是一團糟。', `MaleText_loc7`='Tenemos un serio problema.' WHERE `ID`=27424;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스컬지와 드라카리의 의식 때문에 이 땅은 오염되고 말았다네.$B$B그럼에도 우린 굳게 버티고 있지.', `MaleText_loc4`='天灾军团的邪恶气息与达卡莱巨魔的黑暗仪式亵渎了这片土地。$B$B我们必须将他们彻底铲除。', `MaleText_loc5`='一邊是天譴軍的出現，另一邊是德拉克瑞的儀式，這都使得這片大地遭受污染。$B$B在這兩者之間，我們立場堅定。', `MaleText_loc7`='La tierra ha sido profanada por la presencia de la Plaga por un lado y por los rituales de los Drakkari por el otro.$b$bNosotros nos mantenemos firmes entre ambos.' WHERE `ID`=27425;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛의 축복이 있기를!', `MaleText_loc4`='感谢圣光！', `MaleText_loc5`='替你感謝聖光!', `MaleText_loc7`='¡Demos gracias a la Luz!', `FemaleText_loc1`='빛의 축복이 있기를!', `FemaleText_loc4`='感谢圣光！', `FemaleText_loc5`='替你感謝聖光!', `FemaleText_loc7`='¡Demos gracias a la Luz!' WHERE `ID`=27426;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까. 우린 지금 전쟁터 한가운데 있습니다.', `MaleText_loc4`='嗨，$C。我们正忙着打仗呢。', `MaleText_loc5`='你好，$c，我們正戰得不可開交。', `MaleText_loc7`='Eh, tú, $c. Estamos en plena batalla.', `FemaleText_loc1`='안녕하세요. 우린 지금 전쟁터 한가운데 있습니다.', `FemaleText_loc4`='嗨，$C。我们正忙着打仗呢。', `FemaleText_loc5`='你好，$c，我們正戰得不可開交。', `FemaleText_loc7`='Eh, tú, $c. Estamos en plena batalla.' WHERE `ID`=27427;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 뭘 하시는 겁니까?', `MaleText_loc4`='你来这儿做什么？', `MaleText_loc5`='你在這外頭做什麼?', `MaleText_loc7`='¿Qué haces aquí?', `FemaleText_loc1`='여기서 뭘 하시는 거죠?', `FemaleText_loc4`='你来这儿做什么？', `FemaleText_loc5`='你在這外頭做什麼?', `FemaleText_loc7`='¿Qué haces aquí?' WHERE `ID`=27428;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 아닙니까? 당신은 죽었다고 들었는데.', `MaleText_loc4`='你是$n？我听说你已经死了啊。', `MaleText_loc5`='你不就是$n嗎?我聽說你掛了。', `MaleText_loc7`='¿Tú no eres $n? Había oído que habías muerto.', `FemaleText_loc1`='$n 아니세요? 당신은 죽었다고 들었는데.', `FemaleText_loc4`='你是$n？我听说你已经死了啊。', `FemaleText_loc5`='你不就是$n嗎?我聽說你掛了。', `FemaleText_loc7`='¿Tú no eres $n? Había oído que habías muerto.' WHERE `ID`=27429;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빨리 말하십시오... 이곳 전투는 험악합니다. 정신 똑바로 차려야 해요.', `MaleText_loc4`='麻烦你快一点……局势每况愈下，我必须做好战斗准备。', `MaleText_loc5`='動作快一點...戰鬥越發險惡，我得保持警戒。', `MaleText_loc7`='Que sea rápido... Luchar aquí es macabro y necesito mantenerme fuerte.', `FemaleText_loc1`='빨리 말하세요... 이곳 전투는 험악하답니다. 정신 똑바로 차려야 해요.', `FemaleText_loc4`='麻烦你快一点……局势每况愈下，我必须做好战斗准备。', `FemaleText_loc5`='動作快一點...戰鬥越發險惡，我得保持警戒。', `FemaleText_loc7`='Que sea rápido... Luchar aquí es macabro y necesito mantenerme fuerte.' WHERE `ID`=27430;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신병이십니까? 그 갑옷은 기본적으로 지급되는 물건은 아닌 것 같은데요.', `MaleText_loc4`='你是新兵？瞧你这身行头，不像是正规的军装啊。', `MaleText_loc5`='你是菜鳥?那可不是正常配發的護甲。', `MaleText_loc7`='¿Eres un nuevo recluta? No llevas la armadura estándar.', `FemaleText_loc1`='신병이신가요? 그 갑옷은 기본적으로 지급되는 물건은 아닌 것 같은데요.', `FemaleText_loc4`='你是新兵？瞧你这身行头，不像是正规的军装啊。', `FemaleText_loc5`='你是菜鳥?那可不是正常配發的護甲。', `FemaleText_loc7`='¿Eres un nuevo recluta? No llevas la armadura estándar.' WHERE `ID`=27431;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 좋아. 증원군이로군!', `MaleText_loc4`='哎呀，是援军啊！', `MaleText_loc5`='喔，太好了，是援軍!', `MaleText_loc7`='¡Oh, bien! ¡Refuerzos!', `FemaleText_loc1`='오, 좋아. 증원군이로군!', `FemaleText_loc4`='哎呀，是援军啊！', `FemaleText_loc5`='喔，太好了，是援軍!', `FemaleText_loc7`='¡Oh, bien! ¡Refuerzos!' WHERE `ID`=27432;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저에게 전할 소식이 있습니까?', `MaleText_loc4`='有口信要捎给我吗？', `MaleText_loc5`='你有什麼話要對我說嗎?', `MaleText_loc7`='¿Tienes un mensaje para mí?', `FemaleText_loc1`='제게 전할 소식이 있나요?', `FemaleText_loc4`='有口信要捎给我吗？', `FemaleText_loc5`='你有什麼話要對我說嗎?', `FemaleText_loc7`='¿Tienes un mensaje para mí?' WHERE `ID`=27433;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새 명령이 내려왔습니다. 후방으로 가서 하사관에게 보고하십시오!', `MaleText_loc4`='士兵，听令！立即撤退，向中士报到！', `MaleText_loc5`='士兵們，你們有新任務了。你們馬上撤退，向中士報到!', `MaleText_loc7`='Soldado, tienes nuevas órdenes. ¡Debes retirarte e informar al Sargento!', `FemaleText_loc1`='새 명령이 내려왔습니다. 후방으로 가서 하사관에게 보고하세요!', `FemaleText_loc4`='士兵，听令！立即撤退，向中士报到！', `FemaleText_loc5`='士兵們，你們有新任務了。你們馬上撤退，向中士報到!', `FemaleText_loc7`='Soldado, tienes nuevas órdenes. ¡Debes retirarte e informar al Sargento!' WHERE `ID`=27434;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간은 돈인데, 이렇게 시간을 낭비할 수는 없죠! 그럼 마셔 볼까요...', `MaleText_loc4`='好吧，时间就是金钱，光阴飞逝！我们来喝一杯吧……', `MaleText_loc5`='時間就是金錢，那我們來浪費時間吧!喝酒...', `MaleText_loc7`='¡El tiempo es oro! ¡Y estamos perdiendo tiempo! Bebamos...' WHERE `ID`=27435;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우와! 정말 목구멍이 뻥 뚫리는데요!', `MaleText_loc4`='哇！它真的可以润滑蒸汽阀门！', `MaleText_loc5`='哇!這真的潤滑了蒸氣栓!', `MaleText_loc7`='¡Guao! ¡Esto sí que engrasa las bocas de vapor!' WHERE `ID`=27436;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 정직한 고블린이었다면, 이 맥주가 축제 최고의 맥주라고 말했을 겁니다...', `MaleText_loc4`='如果我是一个诚实的地精，我要说这是节日上最好的啤酒……', `MaleText_loc5`='要是我是個誠實的哥布林，那麼我會說這是啤酒節最棒的啤酒...', `MaleText_loc7`='Si fuese un goblin honesto, diría que esta es la mejor cerveza de la Fiesta...' WHERE `ID`=27437;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코렌이 죽었다니 유감이군요. 그 친구한테 맥주를 사들여서 물 좀 섞고 제 상표를 붙여 팔았으면 꽤 짭짤했을 텐데 말이에요!', `MaleText_loc4`='科林已经死了，这可真糟糕。如果我能从他手中买下这些酒再转卖出去的话——当然要兑上水，重新装瓶，再贴上自己的商标——那我肯定发财了！', `MaleText_loc5`='寇仁死掉真是太可惜了。要是我可以從他那把酒買下來轉賣出去 - 當然啦，還得摻水換瓶貼上我的標籤才行 - 我就發了!', `MaleText_loc7`='Es una pena que Coren esté muerto. Si pudiese comprarle la cerveza y luego revenderla... Aguada y vuelta a embotellar con mi propia etiqueta, está claro... ¡Me forraría!' WHERE `ID`=27438;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생각하던 것보다 더 섬뜩한 곳이지 않습니까, $r님?$b$b그렇다 해도 놀랄 일은 아니지요. 여기까지 온 이들은 거의 다 그렇게 말했으니까요.', `MaleText_loc4`='$r，是不是觉得这里比想象中更加毛骨悚然啊？$b$b如果你真有这种感觉，我一点也不吃惊。几乎所有来过这里的人都这么说，我已经习惯了。', `MaleText_loc5`='外面比你想的還刺激對吧，$r?$b$b我一點也不訝異，每個捱到這裡的人都這麼說。', `MaleText_loc7`='¿Tengo más pelo del que esperabas, $r?$b$bNo puedo decir que me sorprenda. Me lo dicen a menudo todos los que llegan tan lejos...' WHERE `ID`=27439;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당장 호박빛소나무 오두막으로 데려다 드리겠습니다! 한데, 그전에 어디 한 군데 잠시 들러야 하는데...', `MaleText_loc4`='朋友，我这就送你去琥珀松木营地！不过我们需要稍作停留……', `MaleText_loc5`='我要你即刻動身前往琥珀松小屋，盟友!讓我們先稍事休息片刻...', `MaleText_loc7`='¡Te llevaré hasta el Refugio Pino Ámbar enseguida! Pero antes tenemos que hacer una breve pausa...', `FemaleText_loc1`='당장 호박빛소나무 오두막으로 데려다 드리겠습니다! 한데, 그전에 어디 한 군데 잠시 들러야 하는데...', `FemaleText_loc4`='朋友，我这就送你去琥珀松木营地！不过我们需要稍作停留……', `FemaleText_loc5`='我要你即刻動身前往琥珀松小屋，盟友!讓我們先稍事休息片刻...', `FemaleText_loc7`='¡Te llevaré hasta el Refugio Pino Ámbar enseguida! Pero antes tenemos que hacer una breve pausa...' WHERE `ID`=27440;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 우분고라 하네. 잔달라 부족을 대표하고 있지.$B$B나쁜 일들이 일어나고 있다네, $r. 드라카리는 지금 파멸을 자초하고 있어.$B$B트롤 중에는 머리가 안 돌아가는 놈들도 있다네.', `MaleText_loc4`='我是赞达拉部族的乌布戈。$B$B$r，眼前的情形非常糟糕。达卡莱巨魔将自己送上了绝路。$B$B为什么要重蹈覆辙呢？', `MaleText_loc5`='我是烏邦茍，我代表贊達拉部族。$B$B壞事情正悄悄進行著，$r。德拉克瑞將會因為他們的所作所為而大難臨頭。$B$B總是有食人妖學不乖。', `MaleText_loc7`='Soy Ubungo. Represento a la tribu Zandalari.$B$bSe han puesto en marcha cosas malas, $r. Los Drakkari van a cavar su propia tumba con lo que planean.$B$bAlgunos trols no aprenden nunca.' WHERE `ID`=27441;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정복의 요새로 잽싸게 날아가 그 추잡하고 아무짝에도 쓸모없는 호드 놈들이 뭘 하고 있는지 알아봐야겠습니다. 놈들의 와이번이 나타나지 않나 잘 살피세요. 물론 그놈들에게 당할 내가 아니지만 말입니다!', `MaleText_loc4`='我们很快就会对征服堡展开空中侦察，看看那些肮脏的部落到底有什么阴谋。留神那些双足飞龙，倒不是说它们能追上我！', `MaleText_loc5`='我們要快速飛向征服堡，瞧瞧骯髒、糟糕透頂的部落在搞什麼鬼。睜大雙眼注意他們的雙足飛龍。他們別想要逮到我!', `MaleText_loc7`='Vamos a hacer una pasada rápida por el Bastión de la Conquista para ver qué hacen esos roñosos de la Horda. Abre bien los ojos por si aparecen sus Jinetes del Viento. ¡Di que no me pillarían en la vida!', `FemaleText_loc1`='정복의 요새로 잽싸게 날아가 그 추잡하고 아무짝에도 쓸모없는 호드 놈들이 뭘 하고 있는지 알아봐야겠어요. 놈들의 와이번이 나타나지 않나 잘 살피세요. 물론 그놈들에게 당할 내가 아니지만 말이에요!', `FemaleText_loc4`='我们很快就会对征服堡展开空中侦察，看看那些肮脏的部落到底有什么阴谋。留神那些双足飞龙，倒不是说它们能追上我！', `FemaleText_loc5`='我們要快速飛向征服堡，瞧瞧骯髒、糟糕透頂的部落在搞什麼鬼。睜大雙眼注意他們的雙足飛龍。他們別想要逮到我!', `FemaleText_loc7`='Vamos a hacer una pasada rápida por el Bastión de la Conquista para ver qué hacen esos roñosos de la Horda. Abre bien los ojos por si aparecen sus Jinetes del Viento. ¡Di que no me pillarían en la vida!' WHERE `ID`=27442;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='브론즈비어드의 이름으로, 대체 여기서 무슨 일이 벌어지는 건가요? 여길 좀 보십시오! 내 생각엔...', `MaleText_loc4`='以铜须之名，这里到底发生了什么事？瞧瞧这堆烂摊子！我说……', `MaleText_loc5`='到底以銅鬚之名這裡發生了什麼鬼事?看看這個地方!我想...', `MaleText_loc7`='¡Por la barba de Barbabronce! ¿Qué ocurre aquí? ¡Mirad todo esto! Me parece que...', `FemaleText_loc1`='브론즈비어드의 이름으로, 대체 여기서 무슨 일이 벌어지는 건가요? 여길 좀 보세요! 내 생각엔...', `FemaleText_loc4`='以铜须之名，这里到底发生了什么事？瞧瞧这堆烂摊子！我说……', `FemaleText_loc5`='到底以銅鬚之名這裡發生了什麼鬼事?看看這個地方!我想...', `FemaleText_loc7`='¡Por la barba de Barbabronce! ¿Qué ocurre aquí? ¡Mirad todo esto! Me parece que...' WHERE `ID`=27443;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런, 불청객이군! 꽉 잡으십시오! 놈들을 떨쳐버릴 테니!', `MaleText_loc4`='哎呀，我们被盯上啦！抓紧啦！我打算甩掉它们！', `MaleText_loc5`='哦喔，有敵人和我們作伴了!撐下去!我要試著甩開他們!', `MaleText_loc7`='Oh, oh. ¡Tenemos visita! ¡AGÁRRATE BIEN! ¡Intentaré perderlos!', `FemaleText_loc1`='이런, 불청객이군! 꽉 잡으세요! 놈들을 떨쳐버릴 테니!', `FemaleText_loc4`='哎呀，我们被盯上啦！抓紧啦！我打算甩掉它们！', `FemaleText_loc5`='哦喔，有敵人和我們作伴了!撐下去!我要試著甩開他們!', `FemaleText_loc7`='Oh, oh. ¡Tenemos visita! ¡AGÁRRATE BIEN! ¡Intentaré perderlos!' WHERE `ID`=27444;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙습니다. $c|1이여;여;.', `MaleText_loc4`='谢谢你，$c。', `MaleText_loc5`='謝了，$c。', `MaleText_loc7`='Gracias, $c.', `FemaleText_loc1`='고맙습니다. $c님.', `FemaleText_loc4`='谢谢你，$c。', `FemaleText_loc5`='謝了，$c。', `FemaleText_loc7`='Gracias, $c.' WHERE `ID`=27445;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네. 하사관님께 돌아가겠습니다.', `MaleText_loc4`='好吧。我还是返回中士身边吧。', `MaleText_loc5`='沒錯，我最好馬上回去中士那裡。', `MaleText_loc7`='De acuerdo. Entonces será mejor que me presente ante el Sargento.', `FemaleText_loc1`='네. 하사관님께 돌아가겠습니다.', `FemaleText_loc4`='好吧。我还是返回中士身边吧。', `FemaleText_loc5`='沒錯，我最好馬上回去中士那裡。', `FemaleText_loc7`='De acuerdo. Entonces será mejor que me presente ante el Sargento.' WHERE `ID`=27446;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나중에 봅시다.', `MaleText_loc4`='再见。', `MaleText_loc5`='回頭見。', `MaleText_loc7`='Nos vemos.', `FemaleText_loc1`='나중에 봐요.', `FemaleText_loc4`='再见。', `FemaleText_loc5`='回頭見。', `FemaleText_loc7`='Nos vemos.' WHERE `ID`=27447;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하십시오. 드라카리 녀석들은 아주 비열합니다.', `MaleText_loc4`='保持警惕。达卡莱巨魔生性卑鄙。', `MaleText_loc5`='注意你身後。德拉克瑞狡猾的緊。', `MaleText_loc7`='Vigila tu espalda. Estos Drakkari son unos asquerosos.', `FemaleText_loc1`='조심하세요. 드라카리 녀석들은 아주 비열하답니다.', `FemaleText_loc4`='保持警惕。达卡莱巨魔生性卑鄙。', `FemaleText_loc5`='注意你身後。德拉克瑞狡猾的緊。', `FemaleText_loc7`='Vigila tu espalda. Estos Drakkari son unos asquerosos.' WHERE `ID`=27448;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하십시오, $c|1이여;여;. 이 트롤 녀석들은 자기네가 섬기던 뱀 신마저 죽였습니다!', `MaleText_loc4`='千万小心，$c。那些巨魔连他们崇拜的蛇神都敢杀！', `MaleText_loc5`='小心點，$c。這些食人妖宰掉了自己的蛇神!', `MaleText_loc7`='Ten cuidado, $c. ¡Estos trols mataron a su propio dios serpiente!', `FemaleText_loc1`='조심하세요, $c님. 이 트롤 녀석들은 자기네가 섬기던 뱀 신마저 죽였답니다!', `FemaleText_loc4`='千万小心，$c。那些巨魔连他们崇拜的蛇神都敢杀！', `FemaleText_loc5`='小心點，$c。這些食人妖宰掉了自己的蛇神!', `FemaleText_loc7`='Ten cuidado, $c. ¡Estos trols mataron a su propio dios serpiente!' WHERE `ID`=27449;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 너무 오래 머물지 않는 게 좋을 겁니다.', `MaleText_loc4`='别在野外逗留太久。', `MaleText_loc5`='別在外頭待太久。', `MaleText_loc7`='No te quedes mucho tiempo aquí.', `FemaleText_loc1`='여기 너무 오래 머물지 않는 게 좋을 거예요.', `FemaleText_loc4`='别在野外逗留太久。', `FemaleText_loc5`='別在外頭待太久。', `FemaleText_loc7`='No te quedes mucho tiempo aquí.' WHERE `ID`=27450;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대체 어디로 간다는 건지 모르겠군요. 그리고, 우리가 떠나면 누가 이놈들을 상대합니까?', `MaleText_loc4`='我想知道我们这是去哪儿，以及谁会来对付这些家伙？', `MaleText_loc5`='我很好奇我們要去哪裡。還有，誰要來對付這些傢伙?', `MaleText_loc7`='Me pregunto hacia dónde nos dirigimos... Y quién va a encargarse de estos...', `FemaleText_loc1`='대체 어디로 간다는 건지 모르겠군요. 그리고, 우리가 떠나면 누가 이놈들을 상대하는 거죠?', `FemaleText_loc4`='我想知道我们这是去哪儿，以及谁会来对付这些家伙？', `FemaleText_loc5`='我很好奇我們要去哪裡。還有，誰要來對付這些傢伙?', `FemaleText_loc7`='Me pregunto hacia dónde nos dirigimos... Y quién va a encargarse de estos...' WHERE `ID`=27451;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드라카리란 족속은 그저 사소한 골칫덩이일 뿐입니다. 우린 이곳을 떠나 정의를 행하러 가야 합니다!', `MaleText_loc4`='达卡莱巨魔真是麻烦。我们必须继续前进！', `MaleText_loc5`='這些德拉克瑞正是壞消息。我們得馬上離開前往正義要塞!', `MaleText_loc7`='Estos Drakkari no traen más que malas noticias. ¡Debemos marcharnos y dirigirnos a la Fortaleza Justicia!', `FemaleText_loc1`='드라카리란 족속은 그저 사소한 골칫덩이일 뿐이에요. 우린 이곳을 떠나 정의를 행하러 가야 한다고요!', `FemaleText_loc4`='达卡莱巨魔真是麻烦。我们必须继续前进！', `FemaleText_loc5`='這些德拉克瑞正是壞消息。我們得馬上離開前往正義要塞!', `FemaleText_loc7`='Estos Drakkari no traen más que malas noticias. ¡Debemos marcharnos y dirigirnos a la Fortaleza Justicia!' WHERE `ID`=27452;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='유후, 사랑스러운 당신!$B$B오늘은 우리 날이야, 알겠지만... 해적의 날이라고!$B$B노장 첨버킷이랑 내가 생각해낸 건데, 공포의 선장이 그걸 듣더니... 진짜 이렇게 만들어버렸지 뭐야!', `MaleText_loc4`='喂，伙计！$B$B今天是我们的节日，你知道啦……是海盗节！$B$B我和查姆巴克想出了这个主意，而恐怖船长立即同意了……所以，我们就来啦！', `MaleText_loc5`='啊呵，甜心!$B$B今天是我們的日子，你知道...海賊日!$B$B老餌斗跟我想出了這個點子，然後驚懼船長一聽到...就辦了這個活動!', `MaleText_loc7`='¡Qué bolá, asere!$B$bHoy é NUESTRO día, tú sabe... ¡EL DÍA DE LOS PIRATAS!$b$bAl viejo Compibalde y a mí se nos ocurrió la idea, y cuando la aterradora capitana l''oyó... ¡ay, compadre! ¡Así qu''aquí estamos!' WHERE `ID`=27453;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내일이면 남작에게 마을을 돌려줘야 하지만... 오늘 해적의 날만큼은 공포의 선장 드메자와 그 선원들의 것이오. 이예에!$B$B명심하시오. 보고만 있으면 축제를 반밖에 못 즐기니까 말이오. 해적처럼 말해 보시오, 친구!', `MaleText_loc4`='明天我们就把海湾还给大财主里维加兹……可在今天——海盗节——这地方归恐怖船长德梅萨和她的船员了。耶！$B$B记住：可不能光做做样子哦。在海盗节上，你还要讲些道上的黑话才行！', `MaleText_loc5`='明天，大財主就可以拿回他的城市...但今天 - 海賊日 - 是屬於驚懼船長狄米撒和她的船員的。呀哈哈!$B$B記住:看起來像個海賊只是慶典內容的一部分。你得像個海賊一樣說話，$g小子:小妞;!', `MaleText_loc7`='Mañana, el barón recuperará su ciudad... Pero hoy es el Día de los Piratas y la ciudad pertenece a la aterradora capitana DeMeza y su tripulación. ¡Yarr!$b$bY recuerda: parecer un pirata no es más que la MITAD de la celebración. ¡Tienes que hablar como un pirata, $gmarinero:marinera; de agua dulce!' WHERE `ID`=27454;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하파나가 살짝 툴툴거리면서 공포의 선장 드메자에게 가보라고 손짓합니다.$B$B"마가타"라는 단어와 화살에 찔린 하트 모양 문신이 그의 커다란 팔에 새겨져 있습니다.', `MaleText_loc4`='哈帕纳咕哝着，挥挥手让你去找恐怖船长德梅萨。$B$B你发现他那条毛发浓密的粗壮胳膊上刺着一箭穿心的纹身，上面写着“玛加萨”。', `MaleText_loc5`='哈帕那咕噥著揮手趕你去找驚懼船長狄米撒。$B$B在一隻粗壯手臂的毛底下你看見一顆被箭穿過的心上刺著「瑪加薩」的字樣。', `MaleText_loc7`='Hapana simplemente gruñe y hace un gesto para que te acerques a la aterradora capitana DeMeza.$B$bBajo el pelo de un enorme brazo se puede ver un tatuaje que lee "MAGATHA" en un corazón atravesado por una flecha.' WHERE `ID`=27455;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꽤액! 그 녀석 배 밑으로! 배 밑으로!', `MaleText_loc4`='呱呱！龙骨拖！龙骨拖！', `MaleText_loc5`='嘎!把那個小子抓去浸龍骨!浸龍骨!', `MaleText_loc7`='¡KRUAAAAC! ¡Pasen al chamo por la quilla! ¡Por la quilla!' WHERE `ID`=27456;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꽤액! 널빤지로 보내! 보내!', `MaleText_loc4`='呱呱！让他走跳板！走跳板！', `MaleText_loc5`='嘎!走跳板!走啊!', `MaleText_loc7`='¡KRUAAAAC! ¡A caminar por la plancha! ¡A caminar!' WHERE `ID`=27457;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꽤액! 널빤지 흔들어! 흔들어!', `MaleText_loc4`='呱呱！见鬼！真见鬼！', `MaleText_loc5`='嘎!老天爺啊!老天!', `MaleText_loc7`='¡KRUAAAAC! ¡Por todos los temporales! ¡Criadillas!' WHERE `ID`=27458;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꽤액! 그만해, 더러운 해적놈! 그만해!', `MaleText_loc4`='呱呱！住手，你这条下贱的狗！住手！', `MaleText_loc5`='嘎!停船，你這海賊!停啊!', `MaleText_loc7`='¡KRUAAAAC! ¡Alto, berracos con escorbuto! ¡Alto!' WHERE `ID`=27459;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기까지 오다니, 배짱이 대단하군. 알다시피 오늘은 해적의 날이야... 그리고 내일 해가 뜰 때까지 무법항은 바로 내 거거든.$B$B그러니까! 어때? 나와 선원들에게 한 잔씩 돌리고 같이 즐기지 않겠어?', `FemaleText_loc4`='你要到这里来是需要一些勇气的，$g小伙子:小姑娘;。今天是海盗节，你知道啦……直到明天的太阳升起之前，藏宝海湾是属于我的。$B$B那么！你觉得怎样？为我和我的船员举杯，一起来参加庆祝吗？', `FemaleText_loc5`='你還挺有種到這裡來的，$g小子:小妞;。今天是海賊日，知道吧...直到早晨陽光升起以前，藏寶海灣都是屬於我的。$B$B所以你要怎麼做呢?弄杯飲料給我和我的船員喝，然後加入我們的慶典如何?', `FemaleText_loc7`='Aquí vienen uno''h bueno''h trago''h, $gasere:mami;. E''h el Día de los Piratas, tú saaabe''h... Y ha''ta qu''el sol se levante el día de mañana, la Bahía del Botín e''h MÍA.$b$b¡''Tonses! ¿Qué dises tú? ¿Te toma''h algo co''migo y la tripulasión y te une''h a la fieh''ta?' WHERE `ID`=27460;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으으... 속이 거북한데요...', `MaleText_loc4`='噢……我有点头晕……', `MaleText_loc5`='唔...我覺得醉醺醺的...', `MaleText_loc7`='Oh... Me siento grogui...' WHERE `ID`=27461;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='귀찮게 굴지 마십쇼, $c 친구! 여기 맥주가 두 솥이나 있는데, 다 제맛을 내게 해야 한단 말입니다!$B$B안 그랬다가는 코렌 다이어브루 님이 내 가죽을 벗겨서 끓여버릴 거라고요!', `MaleText_loc4`='别来烦我，$c！我要照看整整两大锅起泡酒呢，不能让它们变味儿！$B$B要是这些酒出了一点差子，科林·烈酒大人会把我剥来煮了！', `MaleText_loc5`='別煩我，$c!我得確保這兩大鍋冒泡的啤酒嚐起來風味絕佳才行!$B$B否則的話，主人寇仁·恐酒會把我宰來吃掉!', `MaleText_loc7`='¡No me molestes, $c! ¡Tengo dos calderos enteros de brebaje burbujeante aquí y debo asegurarme de que sepa bien!$b$b¡Si no es así, el maestro Coren Cerveza Temible me despellejará y escaldará!' WHERE `ID`=27462;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 잔 받으시죠, 공포의 선장님! 오늘은 저도 해적이 되게 해주십시오.', `MaleText_loc4`='祝你健康，恐怖船长！今天让我也尝尝当海盗的滋味吧！', `MaleText_loc5`='敬妳，驚懼船長!讓我當一天海賊吧。', `MaleText_loc7`='¡Por la capitana aterradora! Quiero ser pirata por un día.', `FemaleText_loc1`='한 잔 받으세요, 공포의 선장님! 오늘은 저도 해적이 되게 해주세요.', `FemaleText_loc4`='祝你健康，恐怖船长！今天让我也尝尝当海盗的滋味吧！', `FemaleText_loc5`='敬妳，驚懼船長!讓我當一天海賊吧。', `FemaleText_loc7`='¡Por la capitana aterradora! Quiero ser pirata por un día.' WHERE `ID`=27463;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맛이 괜찮은지 봐 드릴까요?', `MaleText_loc4`='要我帮你尝一尝吗？', `MaleText_loc5`='你要喝點什麼?', `MaleText_loc7`='¿Quieres que pruebe un poco?', `FemaleText_loc1`='맛이 괜찮은지 봐 드릴까요?', `FemaleText_loc4`='要我帮你尝一尝吗？', `FemaleText_loc5`='你要喝點什麼?', `FemaleText_loc7`='¿Quieres que pruebe un poco?' WHERE `ID`=27464;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 대기하라. 내가 먼저 소규모 부대를 이끌고 스트라솔름에 들어가겠다. 로데론의 모든 이를 위해, 감염자를 격리하고 처치해야 한다!', `MaleText_loc4`='部队在这里待命，我会亲自率领一支小分队进入斯坦索姆，开始清理行动。为了洛丹伦，我们必须除掉所有被感染的城民！', `MaleText_loc5`='在這裡待命，我會帶一小批人到斯坦索姆進行肅整。為了羅德隆，我們必須遏止並肅清感染者!', `MaleText_loc7`='Colóquense aquí, yo guiaré un pequeño grupo al interior de Stratholme para comenzar el sacrificio. ¡Tenemos que contener y purificar a los infectados por el bien de Lordaeron! ¡Nadie debe escapar o la peste se esparcirá por estas tierras!' WHERE `ID`=27466;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무법항에 온 것을 환영하네, 친구. 드메자와 선원들은 너무 신경 쓰지 말게... 일 년에 한 번 있는 해적의 날만큼은 저 무법자들 마음대로 하게 놔둘 걸세. 그래야 우릴 귀찮게 하지 않고 남쪽 바다에서 노략질이나 하지 않겠나.$B$B그건 그렇고... 스팀휘들 무역회사의 충복인 이 몸께서 뭘 도와주면 되겠나? 아, 이렇게 말하는 게 더 낫겠군. 날 위해 자네는 뭘 해 줄 수 있나?', `MaleText_loc4`='欢迎来到藏宝海湾，伙计。别担心德梅萨和她的船员……每年我们允许他们来这里发泄一次，就在海盗节这一天，然后她就会回到南海去，让我们继续平静地生活。$B$B那么……作为热砂集团谦卑的仆人，我能为你做点什么呢？或者我更愿意说——你能为我做点什么呢，嗯？', `MaleText_loc5`='歡迎來到藏寶海灣，夥伴。請不要在意狄米撒和她的船員...我們讓這個壞人一年選一天放縱一次，就在海賊日，接著她就得平靜的離開，回到南海上繼續劫掠。$B$B現在呢...這個謙遜的熱砂企業小員工能為你做些什麼呢?更棒的是 - 你為能為我做什麼，對吧?', `MaleText_loc7`='$gBienvenido:Bienvenida; a Bahía del Botín, $gsocio:socia;. No te preocupes por DeMeza y su tripulación... Dejamos que el demonio se lo pase bien un día al año: el Día de los Piratas. Después nos deja tranquilos y se marcha a surcar los Mares del Sur de nuevo.$b$bBueno, ¿en qué te puede servir este humilde siervo del Cártel Bonvapor? Aún mejor, ¿qué puedes hacer tú por mí?' WHERE `ID`=27467;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='점점 맛이 좋아지는군요! 속이 아주 뜨뜻해지는데요! 그런데 $n, 지금 보니 당신 옷맵시가 아주 예술입니다!', `MaleText_loc4`='感觉太棒啦！真是暖胃的美酒呀！$n，你真是个时髦的$g家伙:姑娘;！', `MaleText_loc5`='後勁出來了!整個肚子都暖了起來!還有，$n，我不得不說，你真是個打扮入時的$g小鬼:小妞;!', `MaleText_loc7`='¡Está cada vez mejor! ¡Calienta el estómago! ¡Y $n, debo decir que tienes mucho estilo vistiendo!' WHERE `ID`=27468;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='괜찮군요! 하지만 좀 약해요. 마늘향을 조금 더 넣어봐야지...', `MaleText_loc4`='好酒！可惜不够劲。我觉得可以在里面多加一点大蒜……', `MaleText_loc5`='這可是好東西呀!只可惜有點淡。我想我可以加一點大蒜味道進去...', `MaleText_loc7`='¡Está bueno! Pero es un poco flojo. Yo le añadiría algo más de aliento de ajo...' WHERE `ID`=27469;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어이! 오늘은 해적의 날이라는 것, 알고 있겠지... 내일 해가 뜰 때까지 무법항은 바로 내 것이라고.', `FemaleText_loc4`='嘿！今天是海盗节，你知道的……在明天的太阳升起之前，藏宝海湾是我的。', `FemaleText_loc5`='啊呵!今天是海賊日，你懂吧...直到早晨陽光升起之前，藏寶海灣都是屬於我的。', `FemaleText_loc7`='¡Asere! E''h el Día de los Piratas, ¿tú sabe''?... Y ha''ta qu''el sol no salga mañana, la Bahía del Botín e''h MÍA.' WHERE `ID`=27471;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들을 떼 놓은 것 같군요! 정말 아슬아슬했습니다! 흠, 약속했던 대로 호박빛소나무 오두막에 편안히 내려 드리지요! 내려갈 때 조심하십시오!', `MaleText_loc4`='我们已经摆脱它们啦！真险呀！好啦，我这就送你去琥珀松木营地！朋友，坐稳！', `MaleText_loc5`='我想應該甩掉他們了!那真是好險啊!唔，就像我說過的，琥珀松小屋安然無恙吧!記得腳踏實地啊，朋友!', `MaleText_loc7`='¡Creo que nos los hemos quitado de encima! ¡Ha sido peligroso! Bueno, tal y como te prometí, ¡has llegado el Refugio Pino Ámbar sin un rasguño! ¡Suerte!', `FemaleText_loc1`='놈들을 떼 놓은 것 같군요! 정말 아슬아슬했어요! 흠, 약속했던 대로 호박빛소나무 오두막에 편안히 내려 드리지요! 내려갈 때 조심하세요!', `FemaleText_loc4`='我们已经摆脱它们啦！真险呀！好啦，我这就送你去琥珀松木营地！朋友，坐稳！', `FemaleText_loc5`='我想應該甩掉他們了!那真是好險啊!唔，就像我說過的，琥珀松小屋安然無恙吧!記得腳踏實地啊，朋友!', `FemaleText_loc7`='¡Creo que nos los hemos quitado de encima! ¡Ha sido peligroso! Bueno, tal y como te prometí, ¡has llegado el Refugio Pino Ámbar sin un rasguño! ¡Suerte!' WHERE `ID`=27472;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자들이다! 죽여라!', `MaleText_loc4`='入侵者！杀了他们！', `MaleText_loc5`='入侵者!殺掉他們!', `MaleText_loc7`='¡INTRUSOS! ¡ACABEN CON ELLOS!' WHERE `ID`=27473;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스 쓰레기들아! 끝장 내 주마!', `MaleText_loc4`='联盟狗！死！死吧！', `MaleText_loc5`='聯盟骯髒的傢伙!殺!殺!', `MaleText_loc7`='¡BASURA DE LA ALIANZA! ¡QUE MUERAN!' WHERE `ID`=27474;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들을 해치워라! 호드를 위하여!', `MaleText_loc4`='消灭他们！为了部落！', `MaleText_loc5`='砍掉他們的頭顱!為了部落!', `MaleText_loc7`='¡Cortadles la cabeza! ¡Por la Horda!' WHERE `ID`=27475;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='솔직히, 이곳에는 우리가 역병지대에서 경험했던 것보다 훨씬 끔찍한 공포가 떠돌고 있지.$b$b게다가 스컬지는 그 어느 때보다도 강력한 상태라네.', `MaleText_loc4`='我们的处境远比在东西瘟疫之地时狼狈得多。$b$b天灾军团变得更加强大了。', `MaleText_loc5`='的確，此處的恐懼遠勝過瘟疫之地我們所經歷過的一切。$b$b天譴軍如今前所未有的強大。', `MaleText_loc7`='Es verdad que los horrores aquí presentes superan a los que hemos soportado en las Tierras de la Peste.$b$bAhora la Plaga es más poderosa que nunca.' WHERE `ID`=27476;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더는 못 참겠군...$b$b놈들이 당신을 죽여서 먹어버릴 거란 말입니다! 그것도 그나마 운이 좋을 때 얘기라고요!', `MaleText_loc4`='我受不了啦……$b$b他们会杀了你，然后吃掉你的尸体！据说这样还算幸运的！你能想象比这更倒霉的遭遇吗！', `MaleText_loc5`='我受不了了...$b$b他們殺掉你，然後吃掉你!這樣還算是比較幸運的!', `MaleText_loc7`='No lo soporto más...$b$b¡Te matan y luego te comen! ¡Eso si tienes suerte!', `FemaleText_loc1`='더는 못 참겠군...$b$b놈들이 당신을 죽여서 먹어버릴 거란 말입니다! 그것도 그나마 운이 좋을 때 얘기라고요!', `FemaleText_loc4`='我受不了啦……$b$b他们会杀了你，然后吃掉你的尸体！据说这样还算幸运的！你能想象比这更倒霉的遭遇吗！', `FemaleText_loc5`='我受不了了...$b$b他們殺掉你，然後吃掉你!這樣還算是比較幸運的!', `FemaleText_loc7`='No lo soporto más...$b$b¡Te matan y luego te comen! ¡Eso si tienes suerte!' WHERE `ID`=27477;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 나갈 수 있게 좀 도와주세요!$b$b난 저놈들처럼 되기 싫다고요!', `MaleText_loc4`='你一定要救我出去，$r！$b$b我可不想落得他们那样悲惨的下场！', `MaleText_loc5`='你一定要幫幫我離開這裡，$r!$b$b我不要變得跟他們一樣!', `MaleText_loc7`='¡Tienes que ayudarme a salir de aquí, $r!$b$b¡No quiero convertirme en uno de ellos!', `FemaleText_loc1`='여기서 나갈 수 있게 좀 도와주세요!$b$b난 저놈들처럼 되기 싫다고요!', `FemaleText_loc4`='你一定要救我出去，$r！$b$b我可不想落得他们那样悲惨的下场！', `FemaleText_loc5`='你一定要幫幫我離開這裡，$r!$b$b我不要變得跟他們一樣!', `FemaleText_loc7`='¡Tienes que ayudarme a salir de aquí, $r!$b$b¡No quiero convertirme en uno de ellos!' WHERE `ID`=27478;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에 온 뒤로 먹지도 자지도 못했습니다.$b$b난 십자군에 어울리지 않아요...', `MaleText_loc4`='自打我来到这里，就一直吃不下睡不着。$b$b我根本不该加入银色北伐军……', `MaleText_loc5`='來到這裡以後，我便一直寢食難安。$b$b我真不是當十字軍的料...', `MaleText_loc7`='Desde que llegué aquí no he logrado pegar ojo ni comer.$b$bNo estoy hecho para la Cruzada...', `FemaleText_loc1`='이곳에 온 뒤로 먹지도 자지도 못했습니다.$b$b난 십자군에 어울리지 않아요...', `FemaleText_loc4`='自打我来到这里，就一直吃不下睡不着。$b$b我根本不该加入银色北伐军……', `FemaleText_loc5`='來到這裡以後，我便一直寢食難安。$b$b我真不是當十字軍的料...', `FemaleText_loc7`='Desde que llegué aquí no he logrado pegar ojo ni comer.$b$bNo estoy hecha para la Cruzada...' WHERE `ID`=27479;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<훌쩍> 삼촌이 은빛 여명회의 일원이셨어요.$b$b그분은 이 악마들을 어떻게 상대하신 걸까요?', `MaleText_loc4`='<呜咽>我叔叔是银色黎明的成员。$b$b他怎么有勇气面对这些肮脏的怪物啊？', `MaleText_loc5`='<啜泣>我的叔叔在銀色黎明中服役。$b$b他要怎麼面對這些可怕的東西?', `MaleText_loc7`='<sollozo> Mi tío sirvió en El Alba Argenta.$b$b¿Cómo logró enfrentarse a estos seres inmundos?', `FemaleText_loc1`='<훌쩍> 삼촌이 은빛 여명회의 일원이셨어요.$b$b그분은 이 악마들을 어떻게 상대하신 걸까요?', `FemaleText_loc4`='<呜咽>我叔叔是银色黎明的成员。$b$b他怎么有勇气面对这些肮脏的怪物啊？', `FemaleText_loc5`='<啜泣>我的叔叔在銀色黎明中服役。$b$b他要怎麼面對這些可怕的東西?', `FemaleText_loc7`='<sollozo> Mi tío sirvió en El Alba Argenta.$b$b¿Cómo logró enfrentarse a estos seres inmundos?' WHERE `ID`=27480;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='눈을 감기만 하면 사방에 스컬지들이 보인답니다!$b$b어서 여기서 나가야 하는데...', `MaleText_loc4`='一闭上眼睛，就浮现出我被天灾士兵包围的景象！$b$b我要离开这个鬼地方……', `MaleText_loc5`='每當閉上眼睛，我就可以看見天譴軍到處包圍著我!$b$b我得逃離這裡...', `MaleText_loc7`='¡Cada vez que cierro los ojos veo a los miembros de la Plaga rodeándome!$b$bTengo que salir de aquí...', `FemaleText_loc1`='눈을 감기만 하면 사방에 스컬지들이 보인답니다!$b$b어서 여기서 나가야 하는데...', `FemaleText_loc4`='一闭上眼睛，就浮现出我被天灾士兵包围的景象！$b$b我要离开这个鬼地方……', `FemaleText_loc5`='每當閉上眼睛，我就可以看見天譴軍到處包圍著我!$b$b我得逃離這裡...', `FemaleText_loc7`='¡Cada vez que cierro los ojos veo a los miembros de la Plaga rodeándome!$b$bTengo que salir de aquí...' WHERE `ID`=27481;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 여기서 생을 마감할 겁니다... 알 수 있어요.', `MaleText_loc4`='我一定会死在这里的……我心里很清楚。', `MaleText_loc5`='我要死在這裡了...我就知道。', `MaleText_loc7`='Voy a morir aquí... Lo sé.', `FemaleText_loc1`='난 여기서 생을 마감할 겁니다... 알 수 있어요.', `FemaleText_loc4`='我一定会死在这里的……我心里很清楚。', `FemaleText_loc5`='我要死在這裡了...我就知道。', `FemaleText_loc7`='Voy a morir aquí... Lo sé.' WHERE `ID`=27482;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 끝장났어요!', `MaleText_loc4`='我们死定了！！！', `MaleText_loc5`='我們死定啦!!', `MaleText_loc7`='¡¡Estamos condenados!!', `FemaleText_loc1`='우린 끝장났어요!', `FemaleText_loc4`='我们死定了！！！', `FemaleText_loc5`='我們死定啦!!', `FemaleText_loc7`='¡¡Estamos condenados!!' WHERE `ID`=27483;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도망칠 수 있을 때 도망치세요!$b$b우린 어차피 못 이길 게 뻔합니다...', `MaleText_loc4`='趁早逃命去吧，$c！$b$b我们不可能获胜……', `MaleText_loc5`='$c，在你還能逃的時候快逃!$b$b我們一點贏的機會也沒有...', `MaleText_loc7`='¡Sal de ahí mientras puedas, $c!$b$bNo podemos ganar...', `FemaleText_loc1`='도망칠 수 있을 때 도망치세요!$b$b우린 어차피 못 이길 게 뻔합니다...', `FemaleText_loc4`='趁早逃命去吧，$c！$b$b我们不可能获胜……', `FemaleText_loc5`='$c，在你還能逃的時候快逃!$b$b我們一點贏的機會也沒有...', `FemaleText_loc7`='¡Sal de ahí mientras puedas, $c!$b$bNo podemos ganar...' WHERE `ID`=27484;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여긴 아주 엉망이라네.', `FemaleText_loc4`='这下麻烦大了。', `FemaleText_loc5`='這真是一片狼籍。', `FemaleText_loc7`='Menudo desastre.' WHERE `ID`=27485;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나가서 저 스컬지 녀석들이 태어난 것을 후회하게 해 주십시오!', `MaleText_loc4`='去吧，让天灾军团尝尝厉害！', `MaleText_loc5`='馬上出發，讓天譴軍寧願自己沒有被喚醒!', `MaleText_loc7`='¡Sal ahí y haz que esos miembros de la Plaga deseen no haber nacido!', `FemaleText_loc1`='나가서 저 스컬지 녀석들이 태어난 것을 후회하게 해 주세요!', `FemaleText_loc4`='去吧，让天灾军团尝尝厉害！', `FemaleText_loc5`='馬上出發，讓天譴軍寧願自己沒有被喚醒!', `FemaleText_loc7`='¡Sal ahí y haz que esos miembros de la Plaga deseen no haber nacido!' WHERE `ID`=27486;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거 괜찮은데요! 하지만, 왠지 좀 밋밋하군요. 트롤 발가락 때를 넣고 맛을 좀 살려볼까...', `MaleText_loc4`='好酒！但我觉着还不够刺激。要不我们用滑腻的蜥蜴眼来提提味道……', `MaleText_loc5`='這可是好東西呀!但是好像有點走味。加幾顆黏糊糊的蜥蜴眼珠應該就好了...', `MaleText_loc7`='¡Está bueno! Pero me parece un poco soso. Vamos a añadirle unos ojos pochos de basilisco para mejorarlo...' WHERE `ID`=27487;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나쁘지 않아. 나쁘지는 않은데... 뭔가 부족해! 전갈 독이라도 좀 섞어 볼까요? 그래, 그거야! 그거면 딱 맞겠어!', `MaleText_loc4`='呃，还不错吧……总觉得少了点什么！不如加点蝎毒？对呀！那样就很完美啦！', `MaleText_loc5`='還不賴，還不賴...但是不夠嗆!加點蠍毒怎麼樣?沒錯!這樣味道就正了!', `MaleText_loc7`='No está mal... ¡Pero le falta picante! ¿Qué te parece si añadimos veneno de escórpido? ¡Sí! ¡Quedará perfecto!' WHERE `ID`=27488;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거의 다 됐군! 하지만 아직 좀 부족한데요. 그래, 맞아... 어제 신은 양말을 빨아 볼까요... 으으음, 맛 좋군!', `MaleText_loc4`='差不多啦！不过还需要加点料。嘿嘿，你猜对啦……把昨天的袜子丢进锅里吧……哎哟，那种味道……真是美呀！', `MaleText_loc5`='快要好了!但是還差了些什麼。對啦，你猜對了...丟幾條昨天的襪子進鍋子裡...呣，味道真棒!', `MaleText_loc7`='¡Empieza a tomar forma! Aunque aún necesita más fuerza. Sí, lo has adivinado... ¡Lavemos los calcetines de ayer en la caldera! Mmmm, delicioso.' WHERE `ID`=27489;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아요, 좋아! 이거 아주 괜찮지요? 정말 끝내주는데!', `MaleText_loc4`='$g先生:女士;，这可真是好酒呀！不骗你！', `MaleText_loc5`='是啊，$g先生:女士;，真是好酒!真是好酒!', `MaleText_loc7`='Sí, $gseñor:señora;... ¡Menuda bebida! ¡MENUDA bebida!' WHERE `ID`=27490;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노래나 부릅시다!$B$B부어라, 마셔라!$B부어라, 마셔라!$B나는야 검은무쇠 부족!$B$B하하하! $n, 당신 정말 맘에 드는군요!', `MaleText_loc4`='我们来唱歌吧！$B$B啤酒，吵闹，$B啤酒，吵闹！$B黑铁矮人的生活！$B$B哈哈！$n，我喜欢你！', `MaleText_loc5`='讓我們來唱歌!$B$B喝酒，打架，$B$B喝酒，打架!$B$B黑鐵矮人的生存之道!$B$B哈哈!$n，我喜歡你的調調!', `MaleText_loc7`='¡Cantemos algo!$b$b¡Birra, birra!$b¡Birra, birra!$b¡La vida de Hierro Negro!$b$b¡Ja, ja! $n, ¡qué bien me caes!' WHERE `ID`=27491;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디까지 얘기했더라... 아, 그래! 그래서 제가 그랬죠. "하지만 난 네가 필요해! 네가 필요하다고!"... 그런데 그녀는 그냥 픽 웃고는 가버리더라니까요! 전부 사실입니다, $n. 나가라는 것들은 매정하기 그지없다고요!', `MaleText_loc4`='我说到哪儿啦？对啦……于是我对她说：“可是我需要你！我需要你啊！”……她却哈哈大笑，扭着尾巴爬走了！我说的都是真心话啊，$n。纳迦真是残酷的种族！', `MaleText_loc5`='我說到哪了?喔對，我...於是我跟他說:「可是，我需要你!我需要你啊!」...但是她就笑著溜走了!$n，這可是至理名言，納迦也是很殘酷的!', `MaleText_loc7`='¿Por dónde iba...? Ah, sí... Así que le dije "¡Pero te necesito! ¡Te necesito!" ¡... Y ella simplemente se rió y se alejó deslizándose! Es la verdad, $n. ¡Los nagas pueden resultar tan crueles!' WHERE `ID`=27492;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맛을 더 봐야겠는데요!', `MaleText_loc4`='让我们再尝尝看！', `MaleText_loc5`='喝多一點!', `MaleText_loc7`='¡Probemos más!', `FemaleText_loc1`='맛을 더 봐야겠는데요!', `FemaleText_loc4`='让我们再尝尝看！', `FemaleText_loc5`='喝多一點!', `FemaleText_loc7`='¡Probemos más!' WHERE `ID`=27493;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 잔 더!', `MaleText_loc4`='再来一杯！', `MaleText_loc5`='再來一杯!', `MaleText_loc7`='¡Otro trago!', `FemaleText_loc1`='한 잔 더!', `FemaleText_loc4`='再来一杯！', `FemaleText_loc5`='再來一杯!', `FemaleText_loc7`='¡Otro trago!' WHERE `ID`=27494;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더!', `MaleText_loc4`='还要一杯！', `MaleText_loc5`='再來!', `MaleText_loc7`='¡Otra!', `FemaleText_loc1`='더!', `FemaleText_loc4`='还要一杯！', `FemaleText_loc5`='再來!', `FemaleText_loc7`='¡Otra!' WHERE `ID`=27495;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 말이 맞습니다! 전 대체 무슨 생각을 하고 있었던 거죠? 나와라, 스컬지 놈들아!', `MaleText_loc4`='你说得对！我在想什么呢！天灾军团，放马过来吧！', `MaleText_loc5`='你說得對!我到底在想些什麼?放馬過來吧，天譴軍!', `MaleText_loc7`='¡Tienes razón! ¿En qué estaba pensando? ¡A por la Plaga!', `FemaleText_loc1`='당신 말이 맞습니다! 전 대체 무슨 생각을 하고 있었던 거죠? 나와라, 스컬지 놈들아!', `FemaleText_loc4`='你说得对！我在想什么呢！天灾军团，放马过来吧！', `FemaleText_loc5`='你說得對!我到底在想些什麼?放馬過來吧，天譴軍!', `FemaleText_loc7`='¡Tienes razón! ¿En qué estaba pensando? ¡A por la Plaga!' WHERE `ID`=27496;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 말이 맞습니다! 우린 해낼 수 있어요!', `MaleText_loc4`='你说得对！我们能做到！', `MaleText_loc5`='你說得對!我們做得到!', `MaleText_loc7`='¡Tienes razón! ¡Podemos hacerlo!', `FemaleText_loc1`='당신 말이 맞습니다! 우린 해낼 수 있어요!', `FemaleText_loc4`='你说得对！我们能做到！', `FemaleText_loc5`='你說得對!我們做得到!', `FemaleText_loc7`='¡Tienes razón! ¡Podemos hacerlo!' WHERE `ID`=27497;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 이 전쟁에서 이길 수 있습니다!', `MaleText_loc4`='我们会取得这场战争的胜利！', `MaleText_loc5`='我們能贏得這場戰爭!', `MaleText_loc7`='¡Podemos ganar esta guerra!', `FemaleText_loc1`='우린 이 전쟁에서 이길 수 있습니다!', `FemaleText_loc4`='我们会取得这场战争的胜利！', `FemaleText_loc5`='我們能贏得這場戰爭!', `FemaleText_loc7`='¡Podemos ganar esta guerra!' WHERE `ID`=27498;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은빛십자군을 위하여! 스컬지들은 반드시 멸망할 겁니다!', `MaleText_loc4`='为银色北伐军而战！天灾军团注定会失败！', `MaleText_loc5`='為了銀白十字軍!天譴軍必敗!', `MaleText_loc7`='¡Por la Cruzada Argenta! ¡La Plaga perderá!', `FemaleText_loc1`='은빛십자군을 위하여! 스컬지들은 반드시 멸망할 겁니다!', `FemaleText_loc4`='为银色北伐军而战！天灾军团注定会失败！', `FemaleText_loc5`='為了銀白十字軍!天譴軍必敗!', `FemaleText_loc7`='¡Por la Cruzada Argenta! ¡La Plaga perderá!' WHERE `ID`=27499;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 이 땅을 정화하겠습니다! 들리느냐, 아서스!', `MaleText_loc4`='我们会净化这片土地！阿尔萨斯，等着瞧吧！', `MaleText_loc5`='我們會淨化這個地方!阿薩斯小心!', `MaleText_loc7`='¡Limpiaremos este lugar! ¡Te lo advierto, Arthas!', `FemaleText_loc1`='우리가 이 땅을 정화하겠습니다! 들리느냐, 아서스!', `FemaleText_loc4`='我们会净化这片土地！阿尔萨斯，等着瞧吧！', `FemaleText_loc5`='我們會淨化這個地方!阿薩斯小心!', `FemaleText_loc7`='¡Limpiaremos este lugar! ¡Te lo advierto, Arthas!' WHERE `ID`=27500;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 날 불러내다니!', `MaleText_loc4`='你竟敢召唤我？！', `MaleText_loc5`='吃了熊心豹子膽召喚我?!', `MaleText_loc7`='¡¿Te atreves a invocarme?!' WHERE `ID`=27501;
