UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세라투스의 모조는 우리 것이다. 곧 모든 것이 드라카리의 힘 앞에 산산이 부서지리라!', `MaleText_loc4`='西莱图斯的魔精属于我们啦。世间万物都将臣服于达卡莱的力量！', `MaleText_loc5`='司瑟拉圖斯的魔精現在是我們的啦。現在，所有人都將被德拉克瑞的力量給擊碎!', `MaleText_loc7`='El mojo de Sseratus es nuestro. ¡Ahora todos caerán ante el poder de los Drakkari!' WHERE `ID`=27508;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 우리를 공격해? 어리석은 놈들! 우리가 신의 힘을 얻었다는 걸 모르는 게냐?!', `MaleText_loc4`='他们竟敢发动攻击？这帮蠢货！他们难道不清楚我们有多强大吗？！', `MaleText_loc5`='他們膽敢攻擊我們?那些蠢貨!難道他們不知道我們現在無所不能了嗎?!', `MaleText_loc7`='¿Se atreven a atacarnos? ¡Qué idiotas! ¿Acaso no saben que ahora somos todopoderosos?' WHERE `ID`=27509;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 우리 제단을 더럽히는 저 침입자들을 죽여라!', `MaleText_loc4`='杀死入侵者！看看谁敢来亵渎我们神圣的祭坛！', `MaleText_loc5`='把這些膽敢污染我們祭壇的入侵者殺掉!', `MaleText_loc7`='¡Mata a los invasores que osan profanar nuestro altar!' WHERE `ID`=27510;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들을 모두 죽이고 나면 남쪽에 있는 놈들의 동족을 죽이러 간다!', `MaleText_loc4`='杀死他们，然后我们去南边对付他们的同胞！', `MaleText_loc5`='解決他，接著我們就能向南挺進殺掉他們的同胞了!', `MaleText_loc7`='¡Acaba con ellos y luego iremos al sur para matar a sus hermanos!' WHERE `ID`=27511;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야생 신의 힘이 우리 핏줄을 타고 흐르는 이상, 그 누구도, 리치 왕이라 하더라도 우리를 막을 수는 없다!', `MaleText_loc4`='狂野诸神的力量在我们的血脉中燃烧，即便是巫妖王，也无法阻挡我们前进的道路！', `MaleText_loc5`='我們的血管中燃燒著野性諸神的力量，沒有人，即使是巫妖王，也不能擋住我的去路!', `MaleText_loc7`='¡Con la fuerza de los dioses salvajes ardiendo en nuestras venas, nadie, ni siquiera el Rey Exánime, podrá interponerse en nuestro camino!' WHERE `ID`=27512;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 벌레 같은 녀석아! 가까이 와라.', `MaleText_loc4`='我看见你了，蝼蚁！过来吧。', `MaleText_loc5`='我看到你了，害蟲!靠近一點。', `MaleText_loc7`='¡Te veo, insecto! ¡Acércate!' WHERE `ID`=27513;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은빛십자군을 쳐부술 테다! 스컬지를 뭉개버릴 테다!', `MaleText_loc4`='我要消灭银色北伐军！我要消灭天灾军团！', `MaleText_loc5`='我會消滅銀白十字軍!我會擊碎天譴軍!', `MaleText_loc7`='¡Acabaré con la Cruzada Argenta! ¡Aplastaré a la Plaga!' WHERE `ID`=27514;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 날이었으면 이러지 않았겠지만... 오늘은 목도 마르고, 혼자 마시고 싶지도 않군요.$B$B건배!', `MaleText_loc4`='若是在别的日子，我才不会这么做。不过……我很口渴，而且我讨厌独自饮酒。$B$B干杯！', `MaleText_loc5`='這種事我平常是不做的，但...我渴得半死，而且討厭一個人喝酒。$B$B乾杯!', `MaleText_loc7`='Cualquier otro día no haría esto, pero... ¡tengo sed y odio beber a solas!$b$b¡Al centro!' WHERE `ID`=27515;
