UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로데론을 위해 무엇이든 할 각오가 되어 있는가?', `MaleText_loc4`='你愿意不惜一切代价保卫洛丹伦吗？', `MaleText_loc5`='你準備好無所不用其極，就為了保護羅德隆嗎?', `MaleText_loc7`='¿Estás $gdispuesto:dispuesta; a hacer lo que haga falta para proteger Lordaeron?' WHERE `ID`=27518;
