UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 왕자님. 저흰 준비됐습니다.', `MaleText_loc4`='遵命，王子殿下。我们准备好了。', `MaleText_loc5`='是，王子，我們準備就緒。', `MaleText_loc7`='Sí, mi Príncipe, estamos listos.', `FemaleText_loc1`='네, 왕자님. 저흰 준비됐습니다.', `FemaleText_loc4`='遵命，王子殿下。我们准备好了。', `FemaleText_loc5`='是，王子，我們已準備就緒。', `FemaleText_loc7`='Sí, mi Príncipe, estamos listos.' WHERE `ID`=27524;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게 신경 쓸 것 없소. 난 그저 평범한 늙은이라오. 뭐랄까... ''옛 친구''를 기다리는 중이지.', `MaleText_loc4`='不用管我。我只是个糟老头，让我静静地等待那位老……朋友。', `MaleText_loc5`='別理我，我只是個老頭，在等一個老...朋友。', `MaleText_loc7`='No me hagas caso. No soy más que un viejo que espera a un viejo... amigo.' WHERE `ID`=27525;
