UPDATE `locales_broadcast_text` SET `MaleText_loc1`='같이 나갈 수 있을 것 같아요? <한숨>$b$b난 출혈이 심각하단 말이에요!', `MaleText_loc4`='<叹气>……你觉着我们能逃出去吗，$C？$b$b我的血快流干了！', `MaleText_loc5`='<嘆氣>...你認為我們逃得出去嗎，$c?$b$b我的血流失的太快了!', `MaleText_loc7`='<suspiro>... ¿Crees que podríamos irnos, $c?$b$b¡Pierdo fluido con rapidez!' WHERE `ID`=27533;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불이라고! 빌어먹을 비룡들이 온 게 분명하군. 어서 가자!', `MaleText_loc4`='开火！又是那群该死的龙！来吧！', `MaleText_loc5`='開火!一定又是那些該死的飛龍。快點!', `MaleText_loc7`='¡Fuego! Deben de ser los malditos dracos de nuevo. ¡Adelante!', `FemaleText_loc1`='불이라고! 빌어먹을 비룡들이 온 게 분명하군. 어서 가자!', `FemaleText_loc4`='开火！又是那群该死的龙！来吧！', `FemaleText_loc5`='開火!一定又是那些該死的飛龍。快點!', `FemaleText_loc7`='¡Fuego! Deben de ser los malditos dracos de nuevo. ¡Adelante!' WHERE `ID`=27534;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비가 된 것 같군. 명심해라. 이들은 끔찍한 역병에 걸렸고, 어차피 죽을 것이다. 스컬지의 손아귀에서 로데론을 지키려면 스트라솔름을 정화해야 한다. 가자.', `MaleText_loc4`='大家都做好准备了吧。记住，斯坦索姆的城民已经受到感染，很快就会丧命。我们必须清洗斯坦索姆，确保洛丹伦的其它地区免受天灾军团的侵蚀。出发吧。', `MaleText_loc5`='大家看來都準備好了。記得，這些人受到恐怖瘟疫所感染，不久人世。我們得淨化斯坦索姆以保護其他百姓免受天譴軍的威脅。出發吧。', `MaleText_loc7`='Todos parecen estar listos. Recuerden, esta gente está infectada con la peste y morirá pronto. Precisamos desinfectar Stratholme para proteger de la Plaga al resto de Lordaeron. Vamos.' WHERE `ID`=27535;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우물로! 어서!', `MaleText_loc4`='到井边去！快！', `MaleText_loc5`='快到井邊!快點!', `MaleText_loc7`='¡Al pozo! ¡RÁPIDO!', `FemaleText_loc1`='우물로! 어서!', `FemaleText_loc4`='到井边去！快！', `FemaleText_loc5`='快到井邊!快點!', `FemaleText_loc7`='¡Al pozo! ¡RÁPIDO!' WHERE `ID`=27536;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가라, 버러지들아! 이제 이 땅은 리치 왕께 속한다!', `MaleText_loc4`='前进！这片土地属于巫妖王陛下！', `MaleText_loc5`='前進，你們這些蛆蟲!這片大地現在是巫妖王的了!', `MaleText_loc7`='¡Avanzad, gusanos! ¡Esta tierra es ahora del Rey Exánime!' WHERE `ID`=27537;
