UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거치적거리는 놈들은 모두 없애라! 리치 왕을 위하여!', `MaleText_loc4`='毁灭所有阻挡你们前进的生物！为巫妖王而战！', `MaleText_loc5`='擊碎所有擋住去路的人!為了巫妖王!', `MaleText_loc7`='¡Aplasten cualquier cosa que encontren en su camino! ¡Por el Rey Exánime!' WHERE `ID`=27539;
