UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아서스 왕자님, 빛의 가호가 있기를! 마을 사람 여럿이 심각한 병에 걸렸습니다. 저희를 도와주시겠지요?', `MaleText_loc4`='赞美圣光！是阿尔萨斯王子！殿下，我们都被感染了，现在该怎么办？', `MaleText_loc5`='阿薩斯王子，讚美聖光!城市中許多的人民開始患有嚴重的疾病，你能幫幫我們嗎?', `MaleText_loc7`='¡Príncipe Arthas, bendita sea la Luz! Muchos ciudadanos han comenzado a enfermar gravemente, ¿nos puedes ayudar?', `FemaleText_loc1`='아서스 왕자님이시다! 빛이여 감사합니다. 왕자님, 마을 사람 여럿이 심각하게 아픕니다. 저흴 도와주세요!', `FemaleText_loc4`='赞美圣光！是阿尔萨斯王子！殿下，我们都被感染了，现在该怎么办？', `FemaleText_loc5`='阿薩斯王子，讚美聖光!城市中許多的人民開始患有嚴重的疾病，你能幫幫我們嗎?', `FemaleText_loc7`='¡Príncipe Arthas, bendita sea la Luz! Muchos ciudadanos han comenzado a enfermar gravemente, ¿nos puedes ayudar?' WHERE `ID`=27547;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대를 도울 길은 이것뿐이라네.', `MaleText_loc4`='你已经感染得太深了，我能做的只有让你毫无痛苦地安息。', `MaleText_loc5`='我只能讓你毫無痛苦地死去。', `MaleText_loc7`='Sólo puedo ayudarte con una muerte limpia.' WHERE `ID`=27548;
