UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성채에 불이 붙었다! 폭격수는 다 어디 간 거지?!', `MaleText_loc4`='要塞着火了！炮兵呢！都死哪儿去了！', `MaleText_loc5`='要塞燒起來啦!投彈手，你們到底在哪裡?!', `MaleText_loc7`='¡La fortaleza está en llamas! Bombarderos, ¿dónde demonios estáis?', `FemaleText_loc1`='성채에 불이 붙었다! 폭격수는 다 어디 간 거지?!', `FemaleText_loc4`='要塞着火了！炮兵呢！都死哪儿去了！', `FemaleText_loc5`='要塞燒起來啦!投彈手，你們到底在哪裡?!', `FemaleText_loc7`='¡La fortaleza está en llamas! Bombarderos, ¿dónde demonios estáis?' WHERE `ID`=27558;
