UPDATE `locales_broadcast_text` SET `MaleText_loc1`='광신도 하나가 제 손에 죽었습니다... 다시 위장시켜 주시겠습니까? 이번에는 반드시 조심하겠습니다.', `MaleText_loc4`='有个教徒不小心撞上了我的剑刃，然后就死了……我能再要一套伪装吗？我发誓这次会更加谨慎的。', `MaleText_loc5`='其中一位教徒好像是自己跌到我的刀刃上死掉的...我可以有新的偽裝嗎?我發誓我這次會更加小心。', `MaleText_loc7`='Parece que uno de los cultores se ha tropezado con mi hoja y ha muerto... ¿Me puedes dar otro disfraz? Prometo que esta vez tendré más cuidado.', `FemaleText_loc1`='광신도 하나가 제 손에 죽었어요... 다시 위장시켜 주시겠어요? 이번에는 반드시 조심하겠어요.', `FemaleText_loc4`='有个教徒不小心撞上了我的剑刃，然后就死了……我能再要一套伪装吗？我发誓这次会更加谨慎的。', `FemaleText_loc5`='其中一位教徒好像是自己跌到我的刀刃上死掉的...我可以有新的偽裝嗎?我發誓我這次會更加小心。', `FemaleText_loc7`='Parece que uno de los cultores se ha tropezado con mi hoja y ha muerto... ¿Me puedes dar otro disfraz? Prometo que esta vez tendré más cuidado.' WHERE `ID`=27571;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='단계 4 돌입 <PH>', `MaleText_loc4`='Entering Phase 4 <PH>', `MaleText_loc5`='進入階段4 <PH>', `MaleText_loc7`='Entering Phase 4 <PH>' WHERE `ID`=27572;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 소중한 용암고룡... 모두 불타버린 건 아니겠지... 아직 살려낼 수 있는 녀석이 남았을 거야.', `MaleText_loc4`='啊，我的熔岩之龙……事情并非无可挽回……或许我还能让它们复生。', `MaleText_loc5`='我寶貝的熔岩龍...或許不是全部都死了...或許還有剩下什麼可以復活。', `MaleText_loc7`='Mis preciados magmavermis... quizá no esté todo perdido... quizá aún quede algo que levantar.' WHERE `ID`=27573;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇다. 이건 시작일 뿐이지. 널 기다리고 있었다, 젊은 왕자여. 나는 말가니스다.', `MaleText_loc4`='对，这只是个开始。年轻的王子，我等你很久了。我就是玛尔加尼斯。', `MaleText_loc5`='沒錯，這只是個開始。我一直都在等著你，年輕的王子。我是瑪爾加尼斯。', `MaleText_loc7`='Sí, este es el principio. Te he estado esperando, joven Príncipe. Soy Mal''Ganis.' WHERE `ID`=27574;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보다시피 네 백성은 이제 내 손에 들어왔다. 이 도시의 모든 집을 하나씩 하나씩 찾아가 주마. 생명의 불씨가 영원히 꺼질 때까지...', `MaleText_loc4`='如你所见，你的子民现在已经属于我了。我已经将城中的居民统统变成了我的奴仆，让斯坦索姆的生命之火……永远熄灭了。', `MaleText_loc5`='如你所見，你的子民現在已經屬於我了。我要將他們統統變成我的奴僕，讓斯坦索姆的生命之火...永遠熄滅。', `MaleText_loc7`='Como verás, los tuyos ahora me pertenecen. Convertiré esta ciudad casa por casa, hasta que la llama de la vida se haya extinguido... eternamente.' WHERE `ID`=27575;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신비의 휘장', `MaleText_loc4`='奥法徽章', `MaleText_loc5`='秘法外袍', `MaleText_loc7`='Tabardo de lo arcano', `FemaleText_loc1`='신비의 휘장', `FemaleText_loc4`='奥法徽章', `FemaleText_loc5`='秘法外袍', `FemaleText_loc7`='Tabardo de lo arcano' WHERE `ID`=27576;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇게 둘 것 같으냐! 죽어서 네놈의 노예가 되게 하느니 차라리 내 손으로 죽일 것이다!', `MaleText_loc4`='我不会让你得逞的，玛尔加尼斯！我绝对不会眼睁睁地看着他们成为你的奴仆！', `MaleText_loc5`='我不會讓你得逞的，瑪爾加尼斯!我寧可親手結束他們的性命，也不願意看著他們成為你的奴僕!', `MaleText_loc7`='¡No lo permitiré, Mal''Ganis! ¡Mejor que esta gente muera a mano mía, que servir como tus esclavos en la muerte!' WHERE `ID`=27577;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='광휘의 휘장', `MaleText_loc4`='辉煌徽章', `MaleText_loc5`='光輝外袍', `MaleText_loc7`='Tabardo de resplandor', `FemaleText_loc1`='광휘의 휘장', `FemaleText_loc4`='辉煌徽章', `FemaleText_loc5`='光輝外袍', `FemaleText_loc7`='Tabardo de resplandor' WHERE `ID`=27578;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수호의 휘장', `MaleText_loc4`='防御者徽章', `MaleText_loc5`='防衛者外袍', `MaleText_loc7`='Tabardo del defensor', `FemaleText_loc1`='수호의 휘장', `FemaleText_loc4`='防御者徽章', `FemaleText_loc5`='防衛者外袍', `FemaleText_loc7`='Tabardo del defensor' WHERE `ID`=27579;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분노의 휘장', `MaleText_loc4`='愤怒徽章', `MaleText_loc5`='烈怒外袍', `MaleText_loc7`='Tabardo de furia', `FemaleText_loc1`='분노의 휘장', `FemaleText_loc4`='愤怒徽章', `FemaleText_loc5`='烈怒外袍', `FemaleText_loc7`='Tabardo de furia' WHERE `ID`=27580;
