UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공허의 휘장', `MaleText_loc4`='虚空徽章', `MaleText_loc5`='虛空外袍', `MaleText_loc7`='Tabardo del Vacío', `FemaleText_loc1`='공허의 휘장', `FemaleText_loc4`='虚空徽章', `FemaleText_loc5`='虛空外袍', `FemaleText_loc7`='Tabardo del Vacío' WHERE `ID`=27582;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭔가? 지금 바쁜 게 안 보이나?', `MaleText_loc4`='什么事？没看见我正忙着吗？', `MaleText_loc5`='這是啥?你沒看到我正在忙嗎?', `MaleText_loc7`='¿Qué pasa? ¿No ves que estoy ocupado?' WHERE `ID`=27583;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말가니스는 우리를 방해하려고 스컬지 부하들을 보낼 것이다. 너희 중 강한 힘과 마력을 지닌 이가 나서서 상대해야 한다. 나는 나머지 병력을 이끌고 감염자를 처리하겠다.', `MaleText_loc4`='玛尔加尼斯肯定会派出天灾部队阻挠我们。我希望能有些精通剑术或魔法的勇士对抗天灾士兵。而我，会率领剩余的军队清理斯坦索姆中的亡灵，将全城拯救出来。', `MaleText_loc5`='瑪爾加尼斯一定會派出天譴爪牙前來阻撓。你們中手握利刃與魔法者理當肩負消滅它們的責任。我會率領著其它部隊去淨化斯坦索姆。', `MaleText_loc7`='Mal''Ganis enviará algunos de sus lacayos de la Plaga para detenernos. Quienes tengan el acero y la magia más poderosos vayan a destruirlos. Yo guiaré al resto de mis fuerzas para purificar Stratholme de los infectados.' WHERE `ID`=27584;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련하러 왔나요?', `MaleText_loc4`='你是来接受训练的吗？', `MaleText_loc5`='你是來接受訓練的，是吧?', `MaleText_loc7`='Vienes a entrenar, ¿verdad?', `FemaleText_loc1`='훈련하러 왔나요?', `FemaleText_loc4`='你是来接受训练的吗？', `FemaleText_loc5`='你是來接受訓練的，是吧?', `FemaleText_loc7`='Vienes a entrenar, ¿verdad?' WHERE `ID`=27585;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 죽음의 기사가 아니지 않나요. 돌아가세요.', `MaleText_loc4`='你不是死亡骑士。离我远点。', `MaleText_loc5`='你不是死亡騎士。滾開。', `MaleText_loc7`='No eres un caballero de la Muerte. Fuera de aquí.', `FemaleText_loc1`='당신은 죽음의 기사가 아니지 않나요. 돌아가세요.', `FemaleText_loc4`='你不是死亡骑士。离我远点。', `FemaleText_loc5`='你不是死亡騎士。滾開。', `FemaleText_loc7`='No eres un caballero de la Muerte. Fuera de aquí.' WHERE `ID`=27586;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음의 기사 훈련을 하러 왔습니다.', `MaleText_loc4`='我想学习死亡骑士的技能。', `MaleText_loc5`='我對死亡騎士的訓練很感興趣。', `MaleText_loc7`='Me interesa la instrucción de caballero de la Muerte.', `FemaleText_loc1`='죽음의 기사 훈련을 하러 왔습니다.', `FemaleText_loc4`='我想学习死亡骑士的技能。', `FemaleText_loc5`='我對死亡騎士的訓練很感興趣。', `FemaleText_loc7`='Me interesa la instrucción de caballero de la Muerte.' WHERE `ID`=27587;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여어, 친구들! 그놈을 맡아 주세요. 전 이 기계를 고칠게요!', `MaleText_loc4`='Hey guys! Take care of that guy, I''ll fix the machine thing! [PH]', `MaleText_loc5`='嗨大家!照顧一下那個傢伙，我會修裡這機器的! [PH]', `MaleText_loc7`='Hey guys! Take care of that guy, I''ll fix the machine thing! [PH]' WHERE `ID`=27588;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거 전보다 더 까다로운데? 젠장, 온다!', `MaleText_loc4`='嗯……它的确比之前碰见过的所有机器都诡秘复杂……啊，见鬼……敌人来了！', `MaleText_loc5`='比之前複雜了點...噢，糟糕--敵人來襲!', `MaleText_loc7`='Es un poco más complicado que antes... ¡Ay!, ¡demonios!' WHERE `ID`=27589;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마도란이시여! 저건 또 뭐야? 오! 잠깐! 알 것 같은데...', `MaleText_loc4`='玛多兰在上，这玩意到底干了些什么？哦！等等，我马上就搞定它了……', `MaleText_loc5`='以瑪多蘭之名，它到底做了什麼?喔!等等:我好像知道了...', `MaleText_loc7`='En el nombre de Madoran, ¿qué rayos hizo ESO? ¡Ah! Espera: ya casi lo tengo…' WHERE `ID`=27590;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하, 됐어요! 지원군이 갑니다! 이거나 받아라! 무쇠 괴물아!', `MaleText_loc4`='哈，终于搞定了！援军来了！接招吧，你们这群白痴铁疙瘩！', `MaleText_loc5`='哈!成功了!幫手來啦!接招吧，你這閃閃發亮的鐵畜生!', `MaleText_loc7`='¡Listo, ya está! ¡Ayuda en camino! ¡Toma, bestia de hierro reluciente!' WHERE `ID`=27591;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 내려다보는 거죠?$B$B우리 페스텔포트 가문으로 말할 것 같으면, 갈고 빻기로 오랜 세월 이름을 떨친 뼈대 있는 집안이란 말입니다.$B$B그래요, 세계 제일이라 이 말이죠!$B$B그 방면에서는 아제로스, 아니 세상 어디를 뒤져도 우리 식구들보다 훌륭한 연금술사는 못 찾을 겁니다. 장담하지요!$B$B내 비록 지금 수습생 딱지를 달고 있기는 하지만, 기술만큼은 누구에게도 뒤지지 않아요! 인생에서 성공하려면 이러한 굴욕은 누구나 겪게 되는 법이에요.$B$B그런데, 날 도와주러 온 것 아닌가요??$B$B<오만하게 웃는 작은 노움>', `MaleText_loc4`='你摆出这种鄙视的面孔算什么意思？$B$B说到匹斯波特家族，名气可是响当当的！我的祖辈世代以炼金师为业，享有很高的声誉。$B$B不骗你！$B$B我敢说，无论是艾泽拉斯世界还是别的异位面，你找不出比匹斯波特家族更有才的炼金师啦！$B$B虽说我目前还挂着学徒的头衔，但我的技术是顶呱呱的！你要明白，在学术界，只有保持低调才能博得上位。$B$B我说，你是来帮我的吧？$B$B<小侏儒傲慢地笑了笑。>', `MaleText_loc5`='你在輕視個什麼勁?$B$B我會讓你知道搗盆家族在搗碎方面可是赫赫有名。$B$B沒錯，那是一個字!$B$B我可以跟你保證，在全艾澤拉斯或是任何地方都找不到更好的鍊金師了!$B$B我現在可能領著學徒的頭銜，但我的技術可不比任何人差!一個人必須承受如此謙卑的想法才能在人生中有所成就。$B$B當然，或許你只是到這來幫忙我的?$B$B<這個小地精傲慢得笑了。>', `MaleText_loc7`='¿Qué miras?$B$BTe informo de que los Mortero somos una familia con mucha historia y una gran tradición trabajando con morteros.$B$B¡Sí, eso es!$B$BNo encontrarás mejores alquimistas en todo Azeroth, ni en ningún otro lugar, ¡te lo aseguro!$B$B¡Puede que yo aún tenga el título de aprendiz, pero mis habilidades no tienen par! Uno tiene que ser humilde para llegar a ser algo en la vida.$B$BClaro que quizá estés aquí para ayudarme.$B$B<El diminuto gnomo sonríe de forma arrogante.>' WHERE `ID`=27592;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='붉은돌격대의 진정한 힘을 보여주마!', `FemaleText_loc4`='我会让你们见识见识先锋军的真正实力！', `FemaleText_loc5`='現在，我要讓你見識突襲軍真正的力量!', `FemaleText_loc7`='¡Ahora te mostraré el VERDADERO poder del Ataque!' WHERE `ID`=27593;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이봐요, 슈바이처랑 로이타우한테 여기 일이 다 잘 돌아가고 있다고 전해 주세요. 굳이 여기까지 와서 확인할 필요가... 뭐라고요?$B$B그들이 보낸 게 아니라고요? 그럼 왜 절 귀찮게 하는 거죠?$B$B전 할 일이 많다고요!', `FemaleText_loc4`='听着，你去告诉舒维瑟尔和洛伊塔，就说我们已经控制住了这里的局势。他们不需要……什么？$B$B他们没派你来？那你干嘛还来浪费我的时间？$B$B我还有工作要做呢！', `FemaleText_loc5`='聽著，告訴史懷哲和羅伊陶，這裡一切都在我們的掌控之下。他們不能...什麼?$B$B不是他們派你來的?那你幹嘛浪費我的時間?$B$B我還有活要幹!', `FemaleText_loc7`='Mira, les dices a Schweitzer y a Roitau que aquí lo tenemos todo bajo control. No tienen que... ¿qué?$b$b¿No te envían ellos? ¿Entonces para qué me haces perder el tiempo?$b$b¡Tengo trabajo que hacer!' WHERE `ID`=27594;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 나 바쁜 거 안 보여?!$B$B공연을 보고 싶은 거야? 공연은 매일 저녁 8시라고.', `MaleText_loc4`='嗨，没看见我正忙着吗？！$B$B你想看演出？乐队每晚8点开演。', `MaleText_loc5`='嘿，沒看到我正在忙嘛?!$B$B你想看節目?樂團每天晚上八點演出。', `MaleText_loc7`='Oye, ¿no ves que estoy ocupado?$B$B¿Quieres ver el espectáculo? El grupo toca todas las tardes a las ocho.' WHERE `ID`=27595;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='붉은돌격대의 힘을 맛보러 왔느냐?', `FemaleText_loc4`='想见识见识先锋军的实力吗？', `FemaleText_loc5`='你是來測試突襲軍的力量嗎?', `FemaleText_loc7`='¿Has venido a poner a prueba el poder del Ataque?' WHERE `ID`=27596;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어서 놈들을 끝장내라. 신경 쓰이게 하지 말고!', `FemaleText_loc4`='快点干掉闯入者！我可没时间亲自动手。', `FemaleText_loc5`='快點解決入侵者，我沒有時間可浪費!', `FemaleText_loc7`='Encárgense de esta intrusión rápido. No tengo tiempo para estas cosas.' WHERE `ID`=27597;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이게 잘하는 짓인지 다시 생각해 보는 게 좋을 거다!', `FemaleText_loc4`='你们应该在动手之前就考虑到后果，蠢货。', `FemaleText_loc5`='蠢蛋，你該重新考慮一下。', `FemaleText_loc7`='Quizás deban reconsiderar sus acciones, tontos.' WHERE `ID`=27598;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이딴 일에 내가 몸소 나서야만 하겠나!', `FemaleText_loc4`='难道要我亲自解决这些入侵者？', `FemaleText_loc5`='難道要我親自解決這些入侵者?', `FemaleText_loc7`='¿Tengo que encargarme personalmente de esta intromisión?' WHERE `ID`=27599;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만... 그들을 보러 굴착기를 몰고 여기까지 왔는데요...', `MaleText_loc4`='你瞧，我都把挖掘机器开到这里来了……', `MaleText_loc5`='但是，我一路開著我的鑽地機來到這耶...', `MaleText_loc7`='Pero si he venido hasta aquí con mi máquina topo...', `FemaleText_loc1`='하지만... 그들을 보러 굴착기를 몰고 여기까지 왔는데요...', `FemaleText_loc4`='你瞧，我都把挖掘机器开到这里来了……', `FemaleText_loc5`='但是，我一路開著我的鑽地機來到這耶...', `FemaleText_loc7`='Pero si he venido hasta aquí con mi máquina topo...' WHERE `ID`=27600;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음... 좋아, 좋다고. 그 장비, 어차피 좀 시험해 봐야 하는 거였으니까.$B$B조금만 기다리라고. 연습하러 나오라고 할 테니까.$B$B준비된 거야?', `MaleText_loc4`='呃……好吧，好吧。我们需要测试一下设备。$B$B稍等。我来安排一场“排练”。$B$B你准备好了吗？', `MaleText_loc5`='喔...好啦，好啦，不管怎樣，我們得測試一下裝備才行。$B$B給我幾秒鐘，我會叫它們出來「排練」一下。$B$B準備好了嗎?', `MaleText_loc7`='Bueno... bien, bien. Tenemos que probar el equipo de algún modo.$B$BDame un par de segundos. Haré que vengan a "ensayar".$B$B¿Empezamos?' WHERE `ID`=27601;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비됐습니다.', `MaleText_loc4`='我准备好了。', `MaleText_loc5`='我準備好了。', `MaleText_loc7`='Estoy listo.', `FemaleText_loc1`='준비됐어요.', `FemaleText_loc4`='我准备好了。', `FemaleText_loc5`='我準備好了。', `FemaleText_loc7`='Estoy lista.' WHERE `ID`=27602;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정리하자고, 미즐리. 그들이 곧 도착할 거야.', `MaleText_loc4`='米兹利，我们最好快点弄好。他们很快就要到了。', `MaleText_loc5`='全神貫注，米茲，他們很快就要來了。', `MaleText_loc7`='Terminemos con esto, Miz, llegarán enseguida.' WHERE `ID`=27603;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<고통 속에서 상처입은 구름몰이골록 점쟁이>', `MaleText_loc4`='<受伤的雨声神谕者痛苦地呻吟着。>', `MaleText_loc5`='<受傷的雨頌神諭者痛苦的呻吟著。>', `MaleText_loc7`='<El Oráculo Hablalluvia herido gime por el dolor.>' WHERE `ID`=27604;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 내가 찍어놓은 놈을 훔쳤어! 너 게크게크한테 빚졌다!', `MaleText_loc4`='啊！你竟然抢走属于我的猎物！基克吉克要干掉你！', `MaleText_loc5`='不!你偷殺!你欠了杰克傑克!', `MaleText_loc7`='¡No! ¡Tú robar muerte! ¡Ahora tener deuda con Gekgek!' WHERE `ID`=27605;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑군, $r.$b$b미안하지만 지금은 너무 바빠 실례하겠네.', `MaleText_loc4`='你好，$r。$b$b非常抱歉，你得体谅我一下，我现在实在是太忙了。', `MaleText_loc5`='歡迎，$r。$b$b恐怕你得原諒我，因為我此刻異常的忙碌。', `MaleText_loc7`='Saludos, $r.$B$BMe temo que tendrás que disculparme, pero estoy terriblemente ocupado en este momento.' WHERE `ID`=27606;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 분노에 찬 포효를 내지르며 자신의 새끼를 도우려 달려갑니다.', `MaleText_loc4`='%s愤怒地尖啸着，冲过来帮助她的孩子。', `MaleText_loc5`='%s憤怒的尖叫，衝上前去救她的寶寶。', `MaleText_loc7`='La %s chilla con rabia y corre a ayudar a sus crías.' WHERE `ID`=27607;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가장 중요한 것은 시간일세, $n. 시험받을 준비는 되었나?', `MaleText_loc4`='$n，时间很紧迫。你准备好了吗？', `MaleText_loc5`='在這，時間是非常重要的，$n。你準備好接受考驗了嗎?', `MaleText_loc7`='El tiempo es esencial aquí, $n. ¿Empezamos con la prueba?' WHERE `ID`=27608;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시작할 준비가 되었습니다. 첫 번째로 필요한 재료가 무엇인가요?', `MaleText_loc4`='我准备好啦。你要的第一种材料是什么？', `MaleText_loc5`='我準備好要動手了。你需要的第一種材料是什麼?', `MaleText_loc7`='Estoy preparado para empezar. ¿Cuál es el primer ingrediente que necesitas?', `FemaleText_loc1`='시작할 준비가 되었습니다. 첫 번째로 필요한 재료가 무엇인가요?', `FemaleText_loc4`='我准备好啦。你要的第一种材料是什么？', `FemaleText_loc5`='我準備好要動手了。你需要的第一種材料是什麼?', `FemaleText_loc7`='Estoy preparada para empezar. ¿Cuál es el primer ingrediente que necesitas?' WHERE `ID`=27609;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기, 남동쪽입니다. 당신도 놈들에게 당하고 말았군요...', `MaleText_loc4`='在这里，东南方。啊，你也落到他们手里了……', `MaleText_loc5`='就在這，朝東南方。我也看到他們抓了你...', `MaleText_loc7`='Aquí, al sudeste. Veo que a ti también te han atrapado...' WHERE `ID`=27610;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 웬 녀석이지? 투자개발회사를 상대로 장난치면 어떻게 되는지 가르쳐 주마!', `MaleText_loc4`='又有入侵者？我倒要看看谁敢和风险投资公司过不去！', `MaleText_loc5`='更多的入侵者?你很快就會知道，沒人可以跟風險投資公司作對!', `MaleText_loc7`='¿Más intrusos? ¡Pronto aprenderán que nadie se mete con Ventura y Cía!', `FemaleText_loc1`='또 웬 녀석이지? 투자개발회사를 상대로 장난치면 어떻게 되는지 가르쳐 주지!', `FemaleText_loc4`='又有入侵者？我倒要看看谁敢和风险投资公司过不去！', `FemaleText_loc5`='更多的入侵者?你很快就會知道，沒人可以跟風險投資公司作對!', `FemaleText_loc7`='¿Más intrusos? ¡Pronto aprenderán que nadie se mete con Ventura y Cía!' WHERE `ID`=27611;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번엔 잡고 말 테다!', `MaleText_loc4`='这次一定要干掉你！', `MaleText_loc5`='這次我一定會抓到你!', `MaleText_loc7`='¡Esta vez te atraparé!' WHERE `ID`=27612;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야, 이런 곳에서 다른 모험가를 만나리라고는 상상도 못 했군요!$B$B여기 계신 여러분은 제가 심판장에 가는 걸 도와주시겠지요? 이 장소에 대한 제 연구가 옳다면, 드워프 창조와 관련된 정보가 여기 있을 겁니다!', `MaleText_loc4`='呃，居然能在这种地方遇到别的冒险者，这还真让我吃惊！$B$B既然你们在这里，就帮助我进入前面的大厅吧！如果我的研究理论没错的话，我们一定能在这里找到矮人一族起源的秘密！', `MaleText_loc5`='嗯，我很驚訝在這樣的地方還會看到其他的冒險者!$b$b既然現在你人都在這裡了，幫我進入議庭吧。如果我對此地的研究正確無誤，那關於創造整個矮人種族的資料就在這裡!', `MaleText_loc7`='¡Bueno, me sorprende ver a otros aventureros en un lugar como éste!$B$B¡Ahora que están aquí, pueden ayudarme a llegar al Tribunal! Si mis teorías e investigaciones sobre estos salones son correctas, ¡aquí yace la información sobre la creación de toda la raza enana!' WHERE `ID`=27613;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론이지요. 영광입니다, 브란!', `MaleText_loc4`='布莱恩，能帮助你是我们的荣幸！', `MaleText_loc5`='布萊恩，這是我們的榮幸!', `MaleText_loc7`='¡Brann, será un honor!', `FemaleText_loc1`='물론이죠. 영광입니다, 브란!', `FemaleText_loc4`='布莱恩，能帮助你是我们的荣幸！', `FemaleText_loc5`='布萊恩，這是我們的榮幸!', `FemaleText_loc7`='¡Brann, será un honor!' WHERE `ID`=27614;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 움직입시다, 브란. 역사 얘기는 그만하면 됐어요!', `MaleText_loc4`='布莱恩，别再卖弄你的历史知识啦！我们行动吧。', `MaleText_loc5`='布萊恩，我們出發吧，歷史課上夠囉!', `MaleText_loc7`='¡Vamos Brann! ¡Basta de lecciones de historia!', `FemaleText_loc1`='어서 움직입시다, 브란. 역사 얘기는 그만하면 됐어요!', `FemaleText_loc4`='布莱恩，别再卖弄你的历史知识啦！我们行动吧。', `FemaleText_loc5`='布萊恩，我們出發吧，歷史課上夠囉!', `FemaleText_loc7`='¡Vamos Brann! ¡Basta de lecciones de historia!' WHERE `ID`=27616;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사랑하는 내 형제들이 여기서 이 순간을 저와 함께한다면 정말 좋으련만. 이 엄청난 발견을 그들은 상상도 못 할 겁니다!$B$B심판관은 바로 이 방에 가득 찬 티탄의 자료를 관리하는 사서라고요!$B$B보십시오! 바닥 아래 자료가 가득합니다! 서둘러야 합니다. 드워프의 가장 위대한 발견이 눈앞에 있어요.', `MaleText_loc4`='要是我的兄弟现在也在这里就好了。他们肯定不会相信这项发现有多么惊人！$B$B这座大厅是储存泰坦圆盘的档案馆；而这里，就是存储圆盘的地方。$B$B瞧！地板下就散落着泰坦圆盘！我们必须赶快行动，矮人一族有史以来最伟大的发现在等着我们呢。', `MaleText_loc5`='但願我親愛的兄弟們可以此刻出現在這兒。他們肯定不會相信這是多麼了不起的發現!$B$B議庭是泰坦圓盤的保管者，而圓盤就存放在這間房間裡。$B$B看!你可以看到地底下的圓盤!我們動作要快，矮人族的偉大發現就在眼前了!', `MaleText_loc7`='Ojalá mis hermanos pudieran estar conmigo en estos momentos. ¡No se creerían el descubrimiento que esto supondrá!$B$BEl Tribunal son los bibliotecarios de los discos de los titanes, que están guardados en esta sala.$B$B¡Mirad! ¡Se pueden ver los discos bajo el suelo! Debemos apresurarnos, ¡el mayor descubrimiento de la raza enana está justo ahí!' WHERE `ID`=27617;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='먼저 솜엉겅퀴 뿌리를 솥에 넣어야 하네. 꾸물거리지 말고...', `MaleText_loc4`='首先我们需要加入一棵结根草。别拖拖拉拉的，现在就去搞……', `MaleText_loc5`='首先我們會需要放根瘤根在鍋中。別慢吞吞的，現在呢...', `MaleText_loc7`='Primero necesitaremos echar una nudorraíz a la olla. No pierdas el tiempo, vamos...' WHERE `ID`=27618;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가엾구나... 아주 가여워.', `MaleText_loc4`='可惜……真是可惜。', `MaleText_loc5`='太可憐了...真是太可憐了。', `MaleText_loc7`='Lamentable... simplemente lamentable.' WHERE `ID`=27619;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 비행기로 분지에 보내드리겠습니다. 헤멧에게 무슨 일이 일어났는지에 대한 단서를 잘 찾아보십시오!', `MaleText_loc4`='我会让你搭乘我的飞行器的。睁大你的眼睛，给我调查清楚赫米特的情况！', `MaleText_loc5`='我會讓你搭上我的飛行器。張大眼睛注意看赫米特身上會發生什麼事!', `MaleText_loc7`='Te enviaré allí en mi máquina voladora. ¡Mantén los ojos bien abiertos en busca de pistas sobre qué le ha podido ocurrir a Hemet!' WHERE `ID`=27620;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경고: 투사체 조준 감지. 회피 모드 진입.', `MaleText_loc4`='警报：飞行器已被导弹锁定。启动闪避机动功能。', `MaleText_loc5`='警告:飛彈鎖定已偵測，進入迴避動作。', `MaleText_loc7`='ALERTA: detectada fijación de misil. Iniciando maniobras evasivas.' WHERE `ID`=27621;
