UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 두 번 다시 콜라마스를 격추할 수는 없을 것이다.', `MaleText_loc4`='除非你能击落科尔拉玛斯，否则不可能阻挡天灾军团的攻势。', `MaleText_loc5`='現在你要開始進行把科爾拉瑪斯打下來的計畫。', `MaleText_loc7`='Ahora pagarás por haber derribado Kolramas durante toda la eternidad.' WHERE `ID`=27623;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음에서 벗어날 순 없다.', `MaleText_loc4`='别想逃出死神的魔爪。', `MaleText_loc5`='死亡並非解脫之道。', `MaleText_loc7`='La muerte no es una escapatoria.' WHERE `ID`=27624;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕의 이름으로.', `MaleText_loc4`='以巫妖王的名义。', `MaleText_loc5`='以巫妖王之名。', `MaleText_loc7`='En el nombre del Rey Exánime' WHERE `ID`=27625;
