UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 군대가 힘을 기를 수 있도록, 전진하여 적들을 죽여라.', `MaleText_loc4`='每杀死一名敌人，我们就多一员炮灰。', `MaleText_loc5`='上前去，殺死我們的敵人，好讓我們的軍隊得以壯大。', `MaleText_loc7`='Avanzad y matad a nuestros enemigos para que nuestro ejército continúe creciendo.' WHERE `ID`=27628;
