UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='노스렌드의 모든 지역은 마녀의 심장보다도 냉혹한 곳이에요. 그런데 이곳은... 이유를 알아내야 해요! 어쩌면 수정 기둥과 관계가 있는지도 몰라요!', `FemaleText_loc4`='诺森德的大部分区域比女妖的心还要寒冷。不过，这里却……嗯，一定有什么特殊的原因！很有可能跟这些水晶柱有关！', `FemaleText_loc5`='整個北裂境比女巫的心還冷，但我們這裡...這一定有些解釋!很可能就是和那些水晶柱有關!', `FemaleText_loc7`='Todo Rasganorte es más frío que el corazón de una bruja, pero aquí estamos... ¡Tiene que haber una explicación! ¡Es posible que tenga que ver con las columnas de cristal!' WHERE `ID`=27638;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 지역에 티탄의 건축물들이 있다니... 흥미로워요.', `FemaleText_loc4`='这里竟然有泰坦的建筑物，真是……有趣。', `FemaleText_loc5`='這個地區有著那些泰坦建築真的很...有趣。', `FemaleText_loc7`='La presencia de arquitectura de los titanes en esta región es bastante... interesante.' WHERE `ID`=27639;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='운고로 분화구와 비슷하다니 이상한 일이군요. 어쩌면 두 장소를 잇는 연결고리가 있는지도 몰라요.', `FemaleText_loc4`='这里的地貌与安戈洛环形山极其相似。或者两者有些关联吧。', `FemaleText_loc5`='這個地方與安戈洛的相似程度真的很不可思議。或許這兩者在某些方面有所關連。', `FemaleText_loc7`='Las similitudes entre este lugar y Un''goro son intrigantes. Quizá exista algún tipo de conexión entre ambos...' WHERE `ID`=27640;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='비행기 조종사는 대체 언제 오는 거죠? 연구를 하려면 공중에서 찍은 이 지역 사진이 필요하단 말이에요.', `FemaleText_loc4`='我们什么时候能再盼来一名飞行员啊？研究工作毫无进展，必须进行空中侦测才行。', `FemaleText_loc5`='我們還要多久才會有另一個飛行員?我的研究需要有空中支援。', `FemaleText_loc7`='¿Cuánto queda para que podamos tener a otro piloto en el aire? Para que mi investigación llegue a algo, necesito fotografías aéreas.' WHERE `ID`=27641;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스컬지 군대가 왕의 광장 분수대 근처에서 목격되었습니다!', `MaleText_loc4`='国王广场的喷泉附近发现天灾军团踪迹！', `MaleText_loc5`='發現天譴軍部隊正在靠近國王廣場噴泉!', `MaleText_loc7`='¡Se han avistado tropas de la Plaga cerca de la fuente de la Plaza del Rey!' WHERE `ID`=27642;
