UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드라카리를 쳐부숴라! 은빛십자군을 쳐부숴라! 놈들을 모두 스컬지로 만들어버려라!', `MaleText_loc4`='消灭达卡莱巨魔！消灭银色北伐军！将他们统统变成天灾军团的爪牙！', `MaleText_loc5`='摧毀德拉克瑞!摧毀銀白十字軍!把他們全變成天譴軍!', `MaleText_loc7`='¡Destruid a los Drakkari! ¡Destruid a la Cruzada Argenta! ¡Convertidlos a todos en plaga!' WHERE `ID`=27669;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 아름다운 콜라마스가! 네놈들은 이 무도한 행위에 대한 대가를 반드시 치를 것이다.', `MaleText_loc4`='我美丽的科尔拉玛斯！你们要为此付出惨痛的代价！', `MaleText_loc5`='我美麗的科爾拉瑪斯!你要為此暴行付出嚴重的代價!', `MaleText_loc7`='¡Mi querido Kolramas! ¡Pagaréis con creces por esta afrenta!' WHERE `ID`=27670;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와라, 어리석은 것들. 운명을 맞이해라! 내가 기다리고 있다.', `MaleText_loc4`='蠢货，死神的脚步已经临近！我等你很久了。', `MaleText_loc5`='來吧傻瓜，面對你的末日吧!我在等著呢。', `MaleText_loc7`='¡Vengan insensatos! ¡Enfréntense a su perdición! Estoy esperando.' WHERE `ID`=27671;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드라카리여, 이런다고 우리가 너희 신들의 힘을 훔치지 못할 것 같으냐? 너희가 이미 신을 죽였다면 너희에게서 그 힘을 빼앗을 것이다. 전혀 문제가 되지 않아.', `MaleText_loc4`='达卡莱巨魔，别以为这样就能阻挠我们攫取狂野之神的力量。除非你们早已杀掉了这些所谓的神灵，否则他们的力量终将归我们所有。', `MaleText_loc5`='德拉克瑞，這無法阻止我們繼續從你們的野性諸神身上盜走力量。我們要直接從他們身上抽取，若如果你已經殺死他們，那就從你身上抽取，這並不重要。', `MaleText_loc7`='Drakkari, esto no evitará que robemos el poder de sus dioses salvajes. Lo obtendremos directamente de ellos o se lo arrebataremos a ustedes si ya los han matado. Es lo mismo.' WHERE `ID`=27672;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이미 수많은 은빛 여명회 얼간이 녀석들이 내게 무릎을 꿇었다. 은빛십자군도 다르지 않을 것이다.', `MaleText_loc4`='我的双手沾满了银色黎明成员的鲜血。银色北伐军也会落得同样的下场。', `MaleText_loc5`='許多銀色黎明都是倒在我腳下的蠢蛋。銀白十字軍也不會有什麼差別。', `MaleText_loc7`='Entre los inocentones que han caído ante mí se encontraban muchos miembros de El Alba Argenta. Con la Cruzada Argenta no será diferente.' WHERE `ID`=27673;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들을 죽인다면, 시체를 다시 살려내면 되지. 너희가 죽는대도 똑같은 짓을 해 주마.', `MaleText_loc4`='无论你砍翻多少天灾士兵，我都能令他们重新站起来。如果你不幸丧命的话，我也能让你复生，成为我的仆从。', `MaleText_loc5`='就算你殺死他們，我也只需要重新操控他們的屍體。等你死去，我可以對你做一樣的事。', `MaleText_loc7`='Si los matas, simplemente reanimaré sus cadáveres. Y cuando tú mueras, haré lo mismo contigo.' WHERE `ID`=27674;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희는 리치 왕의 힘 앞에 무력할 뿐이다, 하찮은 벌레 녀석들아!', `MaleText_loc4`='凡人，你们无法与巫妖王的力量抗衡！', `MaleText_loc5`='你無法對抗巫妖王的力量，凡人!', `MaleText_loc7`='¡No podéis enfrentaros al poder del Rey Exánime, mortales!' WHERE `ID`=27675;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언데드를 피할 수는 없다!', `MaleText_loc4`='你们注定会沦为天灾军团的爪牙！', `MaleText_loc5`='你勢必要變成不死生物!', `MaleText_loc7`='¡La no-muerte es inevitable!' WHERE `ID`=27676;
