UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자넨 너무 느리군. 처음부터 다시 시작해야 하나...', `MaleText_loc4`='太晚了。我不得不重新开始……', `MaleText_loc5`='你太遲了。我得重頭開始...', `MaleText_loc7`='Llegas demasiado tarde. Tengo que volver a empezar...', `FemaleText_loc1`='안 돼! 물약을 망쳐버렸잖아!', `FemaleText_loc4`='太晚了。我不得不重新开始……', `FemaleText_loc5`='你太遲了。我得重頭開始...', `FemaleText_loc7`='Llegas demasiado tarde. Tengo que volver a empezar...' WHERE `ID`=27688;
