UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쓸모없는 뼈무더기여...', `MaleText_loc4`='一堆没用的骨头……', `MaleText_loc5`='無用的骨頭堆...', `MaleText_loc7`='Inútil montón de huesos...' WHERE `ID`=27691;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언데드로 되살려냈는데도 넌 쓸모가 없군.', `MaleText_loc4`='没想到就算变身亡灵，你也这么没用。', `MaleText_loc5`='就算變成不死生物，你還是個沒用的傢伙。', `MaleText_loc7`='Incluso en la no-muerte, eres un inútil.' WHERE `ID`=27693;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영원한 고통의 세계로 돌아가라.', `MaleText_loc4`='享受永恒的折磨吧。', `MaleText_loc5`='去面對你永恆的折磨吧。', `MaleText_loc7`='Acude a tu tormento eterno.' WHERE `ID`=27694;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 식으로 해방되는 건 마음에 들지 않을 게다.', `MaleText_loc4`='所谓自由，意味着更多的痛苦。', `MaleText_loc5`='你不會喜歡這樣的釋放。', `MaleText_loc7`='No disfrutarás de esta liberación.' WHERE `ID`=27695;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만.', `MaleText_loc4`='够了。', `MaleText_loc5`='夠了。', `MaleText_loc7`='Basta.' WHERE `ID`=27696;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 점쟁이가 너를 돕기로 했다는 말이구나, 이방인. 좋다, 내가 아는 걸 말해 주마.', `MaleText_loc4`='这么说，神谕者决定帮助你了。好吧，我会把我所知的一切都告诉你。', `MaleText_loc5`='所以神諭者決定要幫助你，外地人。很好，我將會提供我所知道的。', `MaleText_loc7`='Así que el Oráculo ha decidido ayudarte, $gforastero:forastera;. Muy bien, te ofreceré mi conocimiento.' WHERE `ID`=27697;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 동료는 우두머리 수정뿔 코뿔소인 파룬을 찾고 있다. 녀석은 자기 형제들에게서 멀리 떨어져 있지.', `MaleText_loc4`='碎角犀牛的族长法鲁恩就是你的同伴寻找的目标。他很少和族群的其他成员待在一起。', `MaleText_loc5`='你的同伴在尋找碎角族王法魯恩，牠和牠的兄弟們十分疏遠。', `MaleText_loc7`='Tu compañero busca al patriarca de los trozocuerno, Farunn, quien se mantiene apartado de sus hermanos.' WHERE `ID`=27698;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파룬은 너희가 거센물결 호수라 부르는 곳의 북쪽에 있다. 녀석은 언제나 혼자 다니지만, 일단 마주쳐 보면 녀석에겐 보호자 따윈 필요 없다는 걸 알게 될 것이다.', `MaleText_loc4`='法鲁恩喜欢独自在苦潮瀑布以北的林地游荡。你可以在那里找到他；不过你很快就会明白，他并不需要族群其他成员的保护。', `MaleText_loc5`='法魯恩在你同胞稱做惡潮瀑布的北方活動。你會發現在牠獨自一人，但你也會瞭解到牠並不需要護衛。', `MaleText_loc7`='Farunn recorre las tierras al norte de lo que tu gente llama Cataratas Olamarga. Cuando lo encuentres, estará solo, pero descubrirás que no necesita que lo defiendan.' WHERE `ID`=27699;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='활성화 중', `MaleText_loc4`='启动', `MaleText_loc5`='啟動', `MaleText_loc7`='Activando', `FemaleText_loc1`='활성화 중', `FemaleText_loc4`='启动', `FemaleText_loc5`='啟動', `FemaleText_loc7`='Activando' WHERE `ID`=27700;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 동료에게 돌아가라. 계속 나아가서 파룬을 처치하고 전리품을 취하라고 일러라.', `MaleText_loc4`='告诉你的同伴，让他去那里猎杀法鲁恩，然后领取奖赏吧。', `MaleText_loc5`='回去找你的同伴。告訴他往前去，打倒法魯恩做為他的獎賞。', `MaleText_loc7`='Vuelve con tu compañero. Dile que continúe y reclame su premio con Farunn.' WHERE `ID`=27701;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일을 마치거든 조용히 이 땅을 떠나라고 전해라. 그는 이 땅에 속한 자가 아니다.', `MaleText_loc4`='事情办完之后，就让他趁早离开。他并不属于这里。', `MaleText_loc5`='一旦他完成，告訴他安靜地離開這塊土地。他並不屬於這裡。', `MaleText_loc7`='Cuando haya hecho eso, dile que deje esta tierra en paz. No pinta nada aquí.' WHERE `ID`=27702;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 과일 상인이나 데려온 오우거나 이해할 수가 없소. 하는 짓으로는 전쟁이 금방이라도 일어날 것 같은데... 아직 아무런 일도 없잖소.', `MaleText_loc4`='我真搞不懂这个水果贩子和那些食人魔佣兵。我们之间似乎要爆发战争……但什么都没有发生。', `MaleText_loc5`='我搞不懂水果小販和他們的巨魔。看起來好像發動了一場對我們的戰爭...但是什麼事也沒發生。', `MaleText_loc7`='No comprendo a este frutero ni a su ogro. Parecía que estuviéramos en guerra... Pero no ha pasado nada.', `FemaleText_loc1`='저 과일 상인이나 데려온 오우거나 이해할 수가 없어요. 하는 짓으로는 전쟁이 금방이라도 일어날 것 같은데... 아직 아무런 일도 없잖아요.', `FemaleText_loc4`='我真搞不懂这个水果贩子和那些食人魔佣兵。我们之间似乎要爆发战争……但什么都没有发生。', `FemaleText_loc5`='我搞不懂水果小販和他們的巨魔。看起來好像發動了一場對我們的戰爭...但是什麼事也沒發生。', `FemaleText_loc7`='No comprendo a este frutero ni a su ogro. Parecía que estuviéramos en guerra... Pero no ha pasado nada.' WHERE `ID`=27703;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='과일 상인은 한 판 붙자는 데도 무시하고, 과일 수레를 옮기라는 말도 듣지 않았소. 데려온 오우거는 그저 앉아서 아무것도 안하고... 도대체 저 과일 상인 꿍꿍이가 뭐일 것 같소?', `MaleText_loc4`='水果贩子拒绝接受我的挑战，还不肯把他的马车挪开。而那些食人魔佣兵只是在一旁干坐着……他到底想干什么？', `MaleText_loc5`='水果小販拒絕接受我的挑戰然後移開他的貨車。他們的巨魔保鏢坐在那兒啥也沒做...他到底在計畫什麼呢?', `MaleText_loc7`='El frutero ha rechazado mi desafío y no quiere quitar su vagoneta. Su protector ogro se pasa el rato sentado sin hacer nada... ¿Qué estará tramando?', `FemaleText_loc1`='과일 상인은 한 번 해보자는 말도 무시하고, 과일 수레를 옮기라는 말도 듣지 않았어요. 데려온 오우거는 그저 앉아서 아무것도 안하고... 도대체 저 과일 상인 꿍꿍이가 뭐일 것 같나요?', `FemaleText_loc4`='水果贩子拒绝接受我的挑战，还不肯把他的马车挪开。而那些食人魔佣兵只是在一旁干坐着……他到底想干什么？', `FemaleText_loc5`='水果小販拒絕接受我的挑戰然後移開他的貨車。他們的巨魔保鏢坐在那兒啥也沒做...他到底在計畫什麼呢?', `FemaleText_loc7`='El frutero ha rechazado mi desafío y no quiere quitar su vagoneta. Su protector ogro se pasa el rato sentado sin hacer nada... ¿Qué estará tramando?' WHERE `ID`=27704;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 이 사과를 팔아야 하지만, 사람들이 먹도록 허락할 수는 없소. 이건 아니오! 사과를 친구들에게 팔면, 친구들이 나 대신 과일 상인과 싸움이 붙을 것이란 말이오!', `MaleText_loc4`='我们要买掉这些苹果，但是不能让人们吃下它们。啊，不！我们要把苹果卖给我们的朋友，这样他们就会替我教训那个水果贩子了！', `MaleText_loc5`='我們應該把這些蘋果賣掉，但是我們不能讓人吃它們。噢不!我們把蘋果賣給我們的朋友，然後他們就會替我攻擊水果小販!', `MaleText_loc7`='Deberíamos vender estas manzanas, pero no permitiremos que la gente las coma. ¡Oh no! ¡Venderemos estas manzanas a nuestros amigos y ellos llevarán la lucha hasta el frutero por mí!', `FemaleText_loc1`='저희는 이 사과를 팔아야 하지만, 사람들이 먹도록 허락할 수는 없어요. 이건 아니에요! 저희가 사과를 친구들에게 팔면, 친구들이 저 대신 과일 상인과 싸움이 붙을 것이란 말이에요!', `FemaleText_loc4`='我们要买掉这些苹果，但是不能让人们吃下它们。啊，不！我们要把苹果卖给我们的朋友，这样他们就会替我教训那个水果贩子了！', `FemaleText_loc5`='我們應該把這些蘋果賣掉，但是我們不能讓人吃它們。噢不!我們把蘋果賣給我們的朋友，然後他們就會替我攻擊水果小販!', `FemaleText_loc7`='Deberíamos vender estas manzanas, pero no permitiremos que la gente las coma. ¡Oh no! ¡Venderemos estas manzanas a nuestros amigos y ellos llevarán la lucha hasta el frutero por mí!' WHERE `ID`=27705;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 편 부대가 아직 오지 않았소. 내가 고용한 사람들은 믿음직하지 않다는 것을 아오. 새로운 용병을 다시 고용할 것이오. 우리는 이 사과를 팔고, 새로 오는 부대는 저들을 박살 낼 것이오!', `MaleText_loc4`='我请来的雇佣兵还没有到。我就知道他们不可靠。我们要招募新的人手。卖掉这些苹果，然后让新的部队去踩烂它们！', `MaleText_loc5`='我的大軍還沒有來。我就知道不能信任我雇用的那些傢伙。我們要招募新的人。我們把這些蘋果賣掉，然後新的軍隊就會把他們碾碎!', `MaleText_loc7`='Mi ejército no ha llegado. Sabía que no podía confiar en la gente que contraté. Reclutaremos gente nueva. ¡Venderemos estas manzanas y nuestro nuevo ejército las aplastará!', `FemaleText_loc1`='우리 편 부대가 아직 오지 않았어요. 제가 고용한 사람들은 믿음직하지 않다는 것을 알아요. 새로운 용병을 다시 고용할 거예요. 우리는 이 사과를 팔고, 새로 오는 부대는 저들을 박살 내겠죠!', `FemaleText_loc4`='我请来的雇佣兵还没有到。我就知道他们不可靠。我们要招募新的人手。卖掉这些苹果，然后让新的部队去踩烂它们！', `FemaleText_loc5`='我的大軍還沒有來。我就知道不能信任我雇用的那些傢伙。我們要招募新的人。我們把這些蘋果賣掉，然後新的軍隊就會把他們碾碎!', `FemaleText_loc7`='Mi ejército no ha llegado. Sabía que no podía confiar en la gente que contraté. Reclutaremos gente nueva. ¡Venderemos estas manzanas y nuestro nuevo ejército las aplastará!' WHERE `ID`=27706;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 과일과 얽힌 이 상황을 우리 뜻대로 처리해야겠소. 그동안 저 과일 상인을 너무 봐줬소. 이제 우린 그냥 과일을 팔 거요. 하지만, 이 과일은 사람이 먹을 만한 게 못 되오. 사람들이 먹게 하진 않겠소! 아무도 우리 과일은 먹지 않을 거요!', `MaleText_loc4`='现在就来解决水果的问题。我们对水果贩子实在是太过迁就啦。现在我们要开始卖水果。但这些水果不是给人吃的。我不允许！谁也不准吃我们的水果！', `MaleText_loc5`='是時候用我們的方法來處理這水果危機了。我們過去對水果小販實在太過寬容。現在，我們乾脆也來賣水果。但是這些水果不是給人吃的。我禁止這樣的事!沒有人可以吃我們的水果!', `MaleText_loc7`='Es hora de que nos encarguemos del problema de la fruta a nuestra manera. Hemos sido demasiado complacientes con el frutero. Ahora, simplemente venderemos la fruta. Pero no será para que la gente la coma. ¡Lo prohíbo! ¡Nadie comerá nuestra fruta!', `FemaleText_loc1`='이제 과일과 얽힌 이 상황을 우리 뜻대로 처리해야겠어요. 그동안 저 과일 상인을 너무 봐줬어요. 이제 우린 그냥 과일을 팔 거예요. 하지만, 이 과일은 사람이 먹을 만한 게 못 돼요. 사람들이 먹게 하진 않겠어요! 우리 과일은 아무도 못 먹을 거예요!', `FemaleText_loc4`='现在就来解决水果的问题。我们对水果贩子实在是太过迁就啦。现在我们要开始卖水果。但这些水果不是给人吃的。我不允许！谁也不准吃我们的水果！', `FemaleText_loc5`='是時候用我們的方法來處理這水果危機了。我們過去對水果小販實在太過寬容。現在，我們乾脆也來賣水果。但是這些水果不是給人吃的。我禁止這樣的事!沒有人可以吃我們的水果!', `FemaleText_loc7`='Es hora de que nos encarguemos del problema de la fruta a nuestra manera. Hemos sido demasiado complacientes con el frutero. Ahora, simplemente venderemos la fruta. Pero no será para que la gente la coma. ¡Lo prohíbo! ¡Nadie comerá nuestra fruta!' WHERE `ID`=27707;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='과일 상인!!! 네 마차가 아직도 우리 앞을 가로막고 있다! 봐주는 것도 여기까지다! 새로운 도전을 하겠다! 누가 과일을 더 잘 파는지 겨뤄보자!', `MaleText_loc4`='水果贩子！！！你的马车还挡着我们的路！我叫你猖狂！现在你要面对新的竞争对手了！', `MaleText_loc5`='水果小販!你的貨車還是擋到我們的路了!你的時間到了!我們現在要跟你競賣水果!', `MaleText_loc7`='¡¡¡VENDEDOR DE FRUTA!!! ¡Tu carro sigue en nuestro camino! ¡Ahora tienes competencia en la venta de fruta!', `FemaleText_loc1`='과일 상인!!! 당신 마차가 아직도 우리 앞을 가로막고 있어요! 봐주는 것도 여기까지예요! 새로운 도전을 하겠어요! 누가 과일을 더 잘 파는지 겨뤄보자고요!', `FemaleText_loc4`='水果贩子！！！你的马车还挡着我们的路！我叫你猖狂！现在你要面对新的竞争对手了！', `FemaleText_loc5`='水果小販!你的貨車還是擋到我們的路了!你的時間到了!我們現在要跟你競賣水果!', `FemaleText_loc7`='¡¡¡VENDEDOR DE FRUTA!!! ¡Tu carro sigue en nuestro camino! ¡Ahora tienes competencia en la venta de fruta!' WHERE `ID`=27708;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간 다 됐다, 과일 상인! 이제 썩어빠진 네 과일은 내가 팔아주겠다!', `MaleText_loc4`='你的好日子到头了，水果贩子！！现在我要开始卖你的烂水果了！', `MaleText_loc5`='你已經沒時間了水果小販!現在我要賣你那些爛掉的水果!', `MaleText_loc7`='¡¡SE TE ACABÓ EL TIEMPO, FRUTERO!! ¡AHORA VENDERÉ TU PODRIDA FRUTA!', `FemaleText_loc1`='시간 다 됐어요, 과일 상인! 이제 썩어빠진 당신 과일은 내가 팔아주겠어요!', `FemaleText_loc4`='你的好日子到头了，水果贩子！！现在我要开始卖你的烂水果了！', `FemaleText_loc5`='你已經沒時間了水果小販!現在我要賣你那些爛掉的水果!', `FemaleText_loc7`='¡¡SE TE ACABÓ EL TIEMPO, FRUTERO!! ¡AHORA VENDERÉ TU PODRIDA FRUTA!' WHERE `ID`=27709;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='봐라, 과일 상인! 방금 사과 하나를 으깨 버렸다! 이제, 네놈 사과도 누군가가 사서 뭉개버릴 것이다!', `MaleText_loc4`='哈！我踩烂了一只苹果，水果贩子！现在开始，你卖给其他人的苹果也会被他们踩烂的！', `MaleText_loc5`='哈!我壓碎了一顆蘋果，水果小販!現在，你的蘋果也只會賣給別人拿去壓!', `MaleText_loc7`='¡JA! ¡HE APLASTADO UNA MANZANA, FRUTERO! ¡AHORA VENDEREMOS TUS MANZANAS PARA QUE LOS DEMÁS TAMBIÉN PUEDAN APLASTARLAS!', `FemaleText_loc1`='봐요, 과일 상인! 방금 사과 하나를 으깨 버렸죠! 이제, 당신 사과도 누군가가 사서 뭉개버릴 거예요!', `FemaleText_loc4`='哈！我踩烂了一只苹果，水果贩子！现在开始，你卖给其他人的苹果也会被他们踩烂的！', `FemaleText_loc5`='哈!我壓碎了一顆蘋果，水果小販!現在，你的蘋果也只會賣給別人拿去壓!', `FemaleText_loc7`='¡JA! ¡HE APLASTADO UNA MANZANA, FRUTERO! ¡AHORA VENDEREMOS TUS MANZANAS PARA QUE LOS DEMÁS TAMBIÉN PUEDAN APLASTARLAS!' WHERE `ID`=27710;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전쟁을 원한다면 하게 해 주지, 과일 상인! 네놈 과일을 누가 더 많이 파는지 두고 보자!', `MaleText_loc4`='如果你想要战争，那我就给你战争，水果贩子！我们来看看谁卖掉的苹果多！', `MaleText_loc5`='如果你想要戰爭，那我就給你一場戰爭，水果販子!我們來看看誰賣的蘋果比較多!', `MaleText_loc7`='¡FRUTERO! ¡SI QUIERES GUERRA, TENDRÁS GUERRA! ¡VEAMOS QUIÉN VENDE MÁS MANZANAS DE LAS TUYAS!', `FemaleText_loc1`='전쟁을 원한다면 하게 해 주겠어, 과일 상인! 당신 과일을 누가 더 많이 파는지 두고 보자고요!', `FemaleText_loc4`='如果你想要战争，那我就给你战争，水果贩子！我们来看看谁卖掉的苹果多！', `FemaleText_loc5`='如果你想要戰爭，那我就給你一場戰爭，水果販子!我們來看看誰賣的蘋果比較多!', `FemaleText_loc7`='¡FRUTERO! ¡SI QUIERES GUERRA, TENDRÁS GUERRA! ¡VEAMOS QUIÉN VENDE MÁS MANZANAS DE LAS TUYAS!' WHERE `ID`=27711;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마셔라, 필멸의 존재여! 내 피를 맛봐라! 죽음을 맛봐라!', `MaleText_loc4`='喝吧！尝尝我的鲜血！尝尝死亡的滋味！', `MaleText_loc5`='喝，凡人!嚐嚐我的血!嚐嚐你的死亡!', `MaleText_loc7`='¡Beban, mortales! ¡Saboreen mi sangre! ¡Saboreen su muerte!', `FemaleText_loc1`='마셔라, 필멸의 존재여! 내 피를 맛봐라! 죽음을 맛봐라!', `FemaleText_loc4`='喝吧！尝尝我的鲜血！尝尝死亡的滋味！', `FemaleText_loc5`='喝，凡人!嚐嚐我的血!嚐嚐你的死亡!', `FemaleText_loc7`='¡Beban, mortales! ¡Saboreen mi sangre! ¡Saboreen su muerte!' WHERE `ID`=27712;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 존재를 더는 참을 수가 없구나. 떠나라. 다른 자를 알아보란 말이다.', `MaleText_loc4`='我真是受不了你。滚吧，别在我身上白费力气了。', `MaleText_loc5`='我不會再苦於你的存在了。滾吧。去勒索別人吧。', `MaleText_loc7`='No te aguantaré más. Lárgate. Busca a otro al que extorsionar.' WHERE `ID`=27713;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미친 드라카리 트롤들이 우리 뒷마당에 스컬지 죽음의 요새를 떨어트릴 줄은 꿈도 못 꿨습니다.$B$B대체 어떻게 한 걸까요?!', `MaleText_loc4`='那些疯狂的达卡莱巨魔竟然击落了一座浮空城！$B$B他们是如何做到的？！', `MaleText_loc5`='我們最不需要的事情就是讓瘋狂的德拉克瑞食人妖在我們的後院把天譴亡域打下來。$B$B他們是怎麼做到的?!', `MaleText_loc7`='Lo último que necesitábamos era que esos locos trols Drakkari derribaran una necrópolis de la Plaga en nuestro patio trasero.$B$B¿Cómo han conseguido hacer eso?' WHERE `ID`=27714;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='으으, 전문가라고 말하는 게 아니었는데. 저한테는 늘 불가능한 일만 맡긴다고요!', `FemaleText_loc4`='啊，当初真不该抢着要专家的名头。他们老是让我做一些根本就不可能的事！', `FemaleText_loc5`='呃，我實在不應該自願當個專家。他們老是要求一些不可能的事情!', `FemaleText_loc7`='Agh, no debí haberme ofrecido como especialista. ¡Siempre nos piden que hagamos lo imposible!' WHERE `ID`=27715;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놀 시간이다!', `MaleText_loc4`='来玩玩吧！', `MaleText_loc5`='遊戲時間!', `MaleText_loc7`='¡A jugar!' WHERE `ID`=27716;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 늦었군, 로데론의 용사여. 오늘은 죽은 자의 잔칫날이다.', `MaleText_loc4`='你们来的太迟了，洛丹伦的勇士们，现在已经是亡灵的时代了。', `MaleText_loc5`='太晚了，羅德隆的勇士。死亡已然降臨。', `MaleText_loc7`='Demasiado tarde, campeón de Lordaeron. Los muertos tendrán su día.' WHERE `ID`=27717;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서두르게!$b$b재료를 바로 솥에 넣으라고. 시간이 무엇보다 중요해!', `MaleText_loc4`='快，$c！$b$b把材料都扔进去。时间紧迫！', `MaleText_loc5`='快一點，$c!$b$b把材料放進鍋裡。時間才是關鍵!', `MaleText_loc7`='¡Rápido, $c!$B$BEcha los ingredientes directamente a la olla. ¡No nos sobra tiempo!' WHERE `ID`=27718;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런, 경보를 누른 것 같군! 고칠 수 있으니 내 뒤나 좀 봐주게!', `MaleText_loc4`='Oops I tripped some sort of alarm! I can fix this, just cover my back! [PH]', `MaleText_loc5`='哎啊，我誤觸了某種警報器了!我可以收拾這個東西，只要掩護我就好了![PH]', `MaleText_loc7`='Oops I tripped some sort of alarm! I can fix this, just cover my back! [PH]' WHERE `ID`=27719;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 안 돼. 경보 단계가 올라갔군!', `MaleText_loc4`='Oh no, another face activated! [PH]', `MaleText_loc5`='喔不，另一面啟動了![PH]', `MaleText_loc7`='Oh no, another face activated! [PH]' WHERE `ID`=27720;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마지막 단계가 되었군, 조심하게! 거의 끝나가네, 저들을 떨어트려 주게!', `MaleText_loc4`='The last face is active, be careful! I am almost done, keep them back! [PH]', `MaleText_loc5`='最後一面啟動了，當心!我快要完成了，別讓他們靠近![PH]', `MaleText_loc7`='The last face is active, be careful! I am almost done, keep them back! [PH]' WHERE `ID`=27721;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠네. 그걸 처리하게!', `MaleText_loc4`='I got it! That should take care of it! [PH]', `MaleText_loc5`='成功了!應該解決了! [PH]', `MaleText_loc7`='I got it! That should take care of it! [PH]' WHERE `ID`=27722;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<당신이 접근하자 낮게 으르렁거리는 사로잡힌 악어>', `MaleText_loc4`='<当你靠近时，被俘虏的鳄鱼发出一声低吼。>', `MaleText_loc5`='<被俘虜的鱷魚在你靠近時發出了一聲低吼。>', `MaleText_loc7`='<El crocolisco cautivo emite un gruñido grave cuando te acercas.>' WHERE `ID`=27723;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 해치지는 않을 것 같구나... 이제 시작하자.', `MaleText_loc4`='看来不会有什么危险……来吧。', `MaleText_loc5`='你看起來夠安全了...我們上吧。', `MaleText_loc7`='Pareces bastante seguro... hagámoslo.', `FemaleText_loc1`='날 해치지는 않을 것 같구나... 이제 시작하자.', `FemaleText_loc4`='看来不会有什么危险……来吧。', `FemaleText_loc5`='你看起來夠安全了...我們上吧。', `FemaleText_loc7`='Pareces bastante seguro... hagámoslo.' WHERE `ID`=27724;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전장으로 뛰쳐나가기에 정말 좋은 날씨군요. 그렇지 않습니까?', `FemaleText_loc4`='今天特别适合出门劫掠一番，不是吗？', `FemaleText_loc5`='不覺得又是一個突襲原野的好日子嗎，$g先生:女士;?', `FemaleText_loc7`='Un día excelente para una incursión en el campo, ¿no le parece, $gseñor:señora;?' WHERE `ID`=27725;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 그래. 어떻게든 저들을 도울 수 있는 건 무엇이든 해야 하네.', `MaleText_loc4`='嗯，我们必须竭尽所能地帮助他们。', `MaleText_loc5`='是，是，我們應該要盡全力去幫助他們。', `MaleText_loc7`='Sí, sí, deberíamos hacer todo lo que podamos para ayudarles.' WHERE `ID`=27726;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수색꾼, 자네 사료... 아니, 사람들은 브리쿨에 대항하는 소중한 자원이 될 거야. 내가 자원이라고 했나? 내 말은... ''동맹''이란 소릴세.', `MaleText_loc4`='远行者，那些炮火……呃，我是说那些人……他们是对抗维库人的重要资源。啊，我说的是“资源”？好吧，我的意思是“盟友”。', `MaleText_loc5`='遠偵斥候，你的飼料...呃，人類將會是用來對抗維酷族的可用資源。我是說資源嗎?我的意思是說，「盟友」。', `MaleText_loc7`='Enviado, tu forraje...estooo, gente será un recurso muy valioso para luchar contra los vrykuls. ¿He dicho recurso? Quería decir ''aliado''.' WHERE `ID`=27727;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 저게 내 비행선에 접근하지 못하게 하라고!', `MaleText_loc4`='天哪！别让它靠近我的飞艇！', `MaleText_loc5`='不!別讓那個東西靠近我的飛艇!', `MaleText_loc7`='¡No! ¡Aleja esa cosa de mi zepelín!' WHERE `ID`=27729;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 대장님!', `MaleText_loc4`='遵命，长官！', `MaleText_loc5`='遵命，長官!', `MaleText_loc7`='¡Señor, sí, señor!' WHERE `ID`=27730;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 코를 벌름거리더니 어딘가 수상한 냄새를 감지해 냅니다.', `MaleText_loc4`='%s从空气中嗅出某种异样的味道。', `MaleText_loc5`='%s往空中嗅了嗅，聞到一股不尋常的味道。', `MaleText_loc7`='%s olisquea el aire, detectando el aroma de algo poco común.' WHERE `ID`=27731;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<몸을 기울여 상처입은 구름몰이골록 점쟁이를 일으켜 세웁니다.>', `MaleText_loc4`='<俯下身去扶起受伤的雨声神谕者。>', `MaleText_loc5`='<伸下手去拉受傷的雨頌神諭者的腳。>', `MaleText_loc7`='<Agáchate y ayuda al Oráculo Hablalluvia herido a levantarse.>', `FemaleText_loc1`='<몸을 기울여 상처입은 구름몰이골록 점쟁이를 일으켜 세웁니다.>', `FemaleText_loc4`='<俯下身去扶起受伤的雨声神谕者。>', `FemaleText_loc5`='<伸下手去拉受傷的雨頌神諭者的腳。>', `FemaleText_loc7`='<Agáchate y ayuda al Oráculo Hablalluvia herido a levantarse.>' WHERE `ID`=27732;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성전사! 이 땔감을 가져가서 병사들에게 불을 피워주게.', `MaleText_loc4`='北伐军！点燃这截木头，为军队提供照明。', `MaleText_loc5`='十字軍!拿著這塊木頭，替部隊點亮一線火光吧。', `MaleText_loc7`='¡Cruzado! Coge esta madera y enciende un fuego para las tropas.' WHERE `ID`=27733;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오, 끈적끈적하군요! 이걸 대체 어떻게 발사했을까요?', `FemaleText_loc4`='哎呀，好粘啊！它们是怎么结网的啊？', `FemaleText_loc5`='喔，這些東西真黏!我懷疑他們要如何破壞這些蛛網?', `FemaleText_loc7`='¡Oh, son pegajosas! ¿Cómo dispararán la tela?' WHERE `ID`=27734;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아악! 안 돼... 몸에 거미줄이 붙어버렸어요! 정말 끈적거려요. 내 머리!', `FemaleText_loc4`='啊！见鬼，我把自己给网住了！粘死啦。哎呀，我的发型！', `FemaleText_loc5`='哎唷!喔不，我纏到我自己了!超黏的。我的頭髮!', `FemaleText_loc7`='¡AGH! ¡Vaya, me he atrapado yo sola! Es pegajoso. ¡MI PELO!' WHERE `ID`=27735;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋아요! 그럼 이 역겨운 부품들로 뭔가 쓸만한 걸 만들어 보죠.', `FemaleText_loc4`='好吧！让我看看能不能将这堆破铜烂铁改造成有用的装置。', `FemaleText_loc5`='好了!咱們來瞧瞧我是不是可以把這些噁心的部分塑造成有用的東西。', `FemaleText_loc7`='¡Genial! Déjame ver si puedo convertir estos desagradables trozos en algo útil.' WHERE `ID`=27736;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='됐어!', `FemaleText_loc4`='我知道了！', `FemaleText_loc5`='我想到了!', `FemaleText_loc7`='¡Eureka!' WHERE `ID`=27737;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주술사 베크지크가 근처의 덤불 사이로 모습을 드러냅니다.', `MaleText_loc4`='萨满祭司维克伊克从旁边的灌木丛中走了出来。', `MaleText_loc5`='薩滿維克吉克從附近的矮木叢中冒出來。', `MaleText_loc7`='El chamán Vekjik sale del arbusto cercano.' WHERE `ID`=27738;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구름몰이골록을 돕다니! 네놈이 구름몰이골록 돕는 걸 봤어! 배신이야!', `MaleText_loc4`='你竟然帮助雨声鳄鱼人！我都看见了！你这个叛徒！', `MaleText_loc5`='你幫助雨頌者!我看到你幫助雨頌者了!你這個背叛者!', `MaleText_loc7`='¡Tu ayudar a Hablalluvia! ¡Yo verte ayudar a Hablalluvia! ¡Cosa traidora!' WHERE `ID`=27739;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날름이들 친구 되겠다면 더는 광란심장 일족 친구 아니야! 마을에 말하겠어! 이제 너 믿지 않아!', `MaleText_loc4`='如果你要和大舌头怪交朋友，那你就不是狂心狼獾人的朋友啦！我要告诉全村人！我们再也不会相信你了！', `MaleText_loc5`='如果你想要當大舌頭的朋友，那你就不是狂心部族的朋友了!我要告訴村民!我們再也不會相信你了!', `MaleText_loc7`='¡Si querer ser amigo de lenguas-grandes, no amigo de Corazón Frenético! ¡Yo decir poblado! ¡Nosotros no confiar más en ti!' WHERE `ID`=27740;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주술사 베크지크가 광란심장 언덕을 향해 달려갑니다.', `MaleText_loc4`='萨满祭司维克伊克朝狂心岭的方向奔去。', `MaleText_loc5`='薩滿維克吉克急匆匆地跑向狂心之丘。', `MaleText_loc7`='El chamán Vekjik corre a toda prisa hacia la Colina Corazón Frenético.' WHERE `ID`=27741;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='귀관은 말가니스의 스컬지 군대와 맞서 싸워 준 용감한 병사 중 하나겠군. 잘해줬네.', `MaleText_loc4`='勇敢的士兵，你从未放弃过对抗玛尔加尼斯统帅的天灾军团。继续努力吧。', `MaleText_loc5`='你一定是擊敗瑪爾加尼斯麾下天譴軍隊的勇敢士兵之一。幹得好。', `MaleText_loc7`='Tú debes de ser uno de los valientes soldados que han estado luchando contra los ejércitos de la Plaga de Mal''ganis. Bien hecho.' WHERE `ID`=27742;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇지. 말가니스는 십자군 광장에서 스컬지들을 지휘하고 있는데, 도시 입구에서 그곳으로 가는 성문은 닫혀 있다.$B$B하지만 놈은 소규모 부대가 마을회관을 지나 광장에 들어갈 수 있다는 사실은 모를 게다. 귀관도 이 공격에 참여하겠나?', `MaleText_loc4`='没错。玛尔加尼斯就在十字军广场指挥天灾军团，但是从斯坦索姆入口通往广场的大门都被关闭了。$B$B如果我率领一支小分队穿过市政厅的话，也能抵达十字军广场。所幸的是，玛尔加尼斯并不知道这一点。你愿意加入我们的突袭行动吗？', `MaleText_loc5`='的確是這樣。瑪爾加尼斯指揮著十字軍廣場的天譴軍團，不過與城市入口連接的門戶還是關閉的。$B$B他想不到一小隊人馬還可以經由市政廳來進入廣場。你願意加入我參與這場攻擊嗎?', `MaleText_loc7`='Sin duda. Mal''ganis está dirigiendo a la Plaga desde la Plaza de los Cruzados, pero las verjas que llevan allí desde la entrada de la ciudad están cerradas.$B$BLo que no sabe es que un pequeño grupo todavía puede llegar a la Plaza pasando por el Ayuntamiento. ¿Te unirás a mí en este ataque?' WHERE `ID`=27743;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희는 그저 로데론을 위해 최선을 다할 뿐입니다, 전하.', `MaleText_loc4`='殿下，我们的所作所为都是为了洛丹伦的利益。', `MaleText_loc5`='我們只會做對羅德隆有利的事，殿下。', `MaleText_loc7`='Solo hacemos lo que es mejor para Lordaeron, su alteza.', `FemaleText_loc1`='저희는 그저 로데론을 위해 최선을 다할 뿐입니다, 전하.', `FemaleText_loc4`='殿下，我们的所作所为都是为了洛丹伦的利益。', `FemaleText_loc5`='我們只會做對羅德隆有利的事，殿下。', `FemaleText_loc7`='Solo hacemos lo que es mejor para Lordaeron, su alteza.' WHERE `ID`=27744;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네. 이끌어 주십시오, 아서스 왕자님.', `MaleText_loc4`='带路吧，阿尔萨斯王子。', `MaleText_loc5`='帶路吧，阿薩斯王子。', `MaleText_loc7`='Guíanos, príncipe Arthas.', `FemaleText_loc1`='네. 이끌어 주세요, 아서스 왕자님.', `FemaleText_loc4`='带路吧，阿尔萨斯王子。', `FemaleText_loc5`='帶路吧，阿薩斯王子。', `FemaleText_loc7`='Guíanos, príncipe Arthas.' WHERE `ID`=27745;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 이제 이 광석이 스컬지에게 왜 그렇게 중요한지 알아보세나.', `MaleText_loc4`='我们得搞清楚，为什么天灾军团如此看重这种矿石。', `MaleText_loc5`='現在我們將會發現為何這塊礦石對天譴軍團來說那麼重要。', `MaleText_loc7`='Ahora veremos por qué esta mena es tan importante para la Plaga.' WHERE `ID`=27746;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코팩스, 이 사로나이트라는 광석에 대해 아는 게 있나?', `MaleText_loc4`='科尔法克斯，你知道萨隆邪铁吗？', `MaleText_loc5`='柯菲斯，你從這塊薩鋼上看出了什麼?', `MaleText_loc7`='Korfax, ¿qué puedes decir de este saronita?' WHERE `ID`=27747;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='들어본 적도 없네. 그야말로 악의 정수로 보이는군.', `MaleText_loc4`='没听说过。它似乎散发着邪恶的气息。', `MaleText_loc5`='聽都沒聽過。看起來十分的邪惡。', `MaleText_loc7`='Jamás he oído hablar de ella. Parece maldad en estado puro.' WHERE `ID`=27748;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 도끼에 맞으면 어떻게 되는지 보지!', `MaleText_loc4`='我倒要看看它能不能挡住我的斧子！', `MaleText_loc5`='讓我們來瞧瞧它是怎麼攔截住我斧頭的力量!', `MaleText_loc7`='¡Veamos cómo aguanta el poder de mi hacha!' WHERE `ID`=27749;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이럴 수가? 내 도끼를 맞고도 흠집조차 나지 않는다니! 이토록 강한 광석은 지금까지 본 적이 없어!', `MaleText_loc4`='见鬼！连一丝裂痕都没留下！这是我见过的最硬的矿石！', `MaleText_loc5`='什麼?連我的斧頭都無法傷它分毫!這是我見過最強硬的礦石了!', `MaleText_loc7`='¿Qué demonios? ¡Mi segadora no le ha hecho ni un arañazo! ¡Esa es la mena más dura que jamás haya visto!' WHERE `ID`=27750;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='집에 갈 시간이다!', `MaleText_loc4`='终于可以回家啦！', `MaleText_loc5`='回家時間!', `MaleText_loc7`='¡Hora de ir a casa!', `FemaleText_loc1`='집에 갈 시간이야!', `FemaleText_loc4`='终于可以回家啦！', `FemaleText_loc5`='回家時間!', `FemaleText_loc7`='¡Hora de ir a casa!' WHERE `ID`=27751;
