UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수염은 안 돼! 균형이 안 맞게 돼 버렸잖아!', `MaleText_loc4`='我的胡子！两边不对称了！', `MaleText_loc5`='別射我的鬍子!現在兩邊不對稱了!', `MaleText_loc7`='¡El bigote no! ¡Ahora soy asimétrico!' WHERE `ID`=27755;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 귀! 내 귀를 쏘다니!', `MaleText_loc4`='耳朵！你弄伤了我的耳朵！', `MaleText_loc5`='我的耳朵!你弄傷我的耳朵了!', `MaleText_loc7`='¡Mi oreja! ¡Me has arañado la oreja!' WHERE `ID`=27756;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악! 좋아, 이제 표적 신세는 사양하겠어!', `MaleText_loc4`='痛！我不干了，我不要当靶子！', `MaleText_loc5`='痛!夠了，我不要當目標了!', `MaleText_loc7`='¡Ay! ¡Ya basta! ¡Dejo el negocio de los objetivos!' WHERE `ID`=27757;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 내가 자신 있는 곳이라고!', `MaleText_loc4`='天哪！这边的胡须本来是完好的！', `MaleText_loc5`='不!那邊是我的長處!', `MaleText_loc7`='¡No! ¡Ese era mi lado bueno!' WHERE `ID`=27758;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='레인, 림블랫, 자연과 정령의 힘을 써 보는 건 어때?', `MaleText_loc4`='莱茵，雷布拉特，试试自然与元素的力量？', `MaleText_loc5`='瑞恩，林布拉特，你們覺得元素和自然之力如何呢?', `MaleText_loc7`='Rayne, Rimblat ¿qué hay del poder de la naturaleza y los elementos?' WHERE `ID`=27759;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='복수자 메츠가 가소롭다는 듯이 콧방귀를 뀝니다.', `MaleText_loc4`='梅兹哼了一声，摆出心不在焉的模样。', `MaleText_loc5`='復仇者輕蔑的哼了一聲，很明顯的無動於衷。', `MaleText_loc7`='El vengador resopla, en absoluto impresionado.' WHERE `ID`=27760;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조용히 해, 친구. 그냥 새총일 뿐이라니까!', `MaleText_loc4`='冷静点，伙计。这只是小号铅弹啊！', `MaleText_loc5`='冷靜點，小夥子，只是隻鳥飛過去而已!', `MaleText_loc7`='¡Calma, $gmuchacho:muchacha;, es solo un tiro de salva!' WHERE `ID`=27761;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠, 좀 나아졌군.', `MaleText_loc4`='呸，还是有进步的。', `MaleText_loc5`='呸，這叫進步。', `MaleText_loc7`='Bah, es una mejora.' WHERE `ID`=27762;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='세상에. 자연의 힘이 아무 영향도 미치지 못하는 것 같아요!', `FemaleText_loc4`='女神在上。自然的力量也无法撼动它！', `FemaleText_loc5`='以女神之名。就算是大自然也不可進犯!', `FemaleText_loc7`='Por la diosa. ¡Es como si la naturaleza no pudiera tocarlo!' WHERE `ID`=27763;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='징징거리지 말라고. 그래도 아직은 운이 좋군.', `MaleText_loc4`='别抱怨了。你的运气还不错啊。', `MaleText_loc5`='別再發牢騷了。你還是很幸運啦。', `MaleText_loc7`='Deja de quejarte. Aún conservas tu suerte.' WHERE `ID`=27764;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자존심 말고는 멀쩡하잖아, 친구. 입 좀 다물어!', `MaleText_loc4`='只是有点伤自尊嘛，伙计。振作一点啦！', `MaleText_loc5`='唯一受到傷害的是你的自尊，小夥子。忘了吧!', `MaleText_loc7`='Lo único herido aquí es tu orgullo, chico. ¡Date prisa!' WHERE `ID`=27765;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소용없군.', `MaleText_loc4`='没有用。', `MaleText_loc5`='沒事。', `MaleText_loc7`='Nada.' WHERE `ID`=27766;
