UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 불렀는지 알잖나.', `MaleText_loc4`='你会什么力量啊。', `MaleText_loc5`='你知道原因。', `MaleText_loc7`='Ya sabes el qué.' WHERE `ID`=27768;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놀랍지도 않군.', `MaleText_loc4`='有什么值得大惊小怪的。', `MaleText_loc5`='一點都不驚訝。', `MaleText_loc7`='No me sorprende.' WHERE `ID`=27769;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜?', `MaleText_loc4`='什么？', `MaleText_loc5`='什麼?', `MaleText_loc7`='¿Qué?' WHERE `ID`=27770;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아. 하지만 기억해 두게, 형제여. 성스러운 빛의 힘은 손쉽게 일으킬 수 있는 게 아니라네.', `MaleText_loc4`='好吧。不过你记住，圣光的力量是不能随便运用的。', `MaleText_loc5`='很好。不過記住，聖光的力量不是隨隨便便就可以祈求的，兄弟。', `MaleText_loc7`='Vale. Pero tan solo recuerda que el poder de la Luz Sagrada no es algo que se pueda invocar con indiferencia, hermano.' WHERE `ID`=27771;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='광석이 왜 저러지?', `MaleText_loc4`='怎么回事？！', `MaleText_loc5`='這是在做什麼?!', `MaleText_loc7`='¿Qué está haciendo?' WHERE `ID`=27772;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속해 봤자 소용없겠어. 이 사로나이트를 폴드링 대영주님께 보내 더 자세히 연구하도록 해야겠네.', `MaleText_loc4`='好吧，事情毫无进展。我们还是将这块萨隆邪铁交给大领主弗丁研究吧。', `MaleText_loc5`='顯然這對我們毫無用處。我們得將這塊薩鋼帶給大領主弗丁進行進一步的研究。', `MaleText_loc7`='Es evidente que así no vamos a ninguna parte. Tenemos que llevarle esta saronita al alto señor Vadín para continuar estudiándola.' WHERE `ID`=27774;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘써줘서 고맙네, 친구여. 우리는 비밀을 밝혀내고 말 거야. 바라건대, 너무 늦기 전에 말이지.', `MaleText_loc4`='朋友们，谢谢你们的尝试。我们一定会揭开其中秘密，只希望一切不会太迟。', `MaleText_loc5`='謝謝你的嘗試，我的朋友。我們會解開其中的秘密。希望能趕在一切都變得太遲之前。', `MaleText_loc7`='Gracias por intentarlo, amigos míos. Desvelaremos sus secretos. Espero que antes de que sea demasiado tarde.' WHERE `ID`=27775;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 툴툴거립니다.', `MaleText_loc4`='%s嘟囔着。', `MaleText_loc5`='%s咕噥著。', `MaleText_loc7`='%s gruñe.' WHERE `ID`=27776;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부질없는 짓인 줄 잘 알고 있겠지!', `MaleText_loc4`='很快你们就会发现一切都是徒劳无功。', `MaleText_loc5`='你一定看得出來，這一切都只是徒勞無功罷了!', `MaleText_loc7`='¡Seguramente ves lo inútil de todo esto! ' WHERE `ID`=27777;
