UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날름이와 한 패가 되다니 어리석어! 너는 이제 광란심장 일족 친구 아니다. 광란심장 일족이 손 좀 봐줄 거야.', `MaleText_loc4`='你竟然和大舌头怪搅和在一起！你不再是狂心氏族的朋友了。狂心狼獾人要让你尝尝厉害！', `MaleText_loc5`='愚笨的大舌頭愛人!你再也不是狂心部族的朋友了。狂心部族不會放過你的。', `MaleText_loc7`='¡Estúpido amante de lenguas-grandes! Tú ya no amigo de Corazón Frenético. Corazón frenético se encargará de ti.' WHERE `ID`=27798;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 하룻강아지들이 쫓아온다!', `MaleText_loc4`='不妙！我们被狗狗人跟踪了！', `MaleText_loc5`='喔不!有小狗人跟著你!', `MaleText_loc7`='¡Oh no! ¡Nos han seguido algunos hombres cachorro!', `FemaleText_loc1`='안 돼! 하룻강아지들이 쫓아온다!', `FemaleText_loc4`='不妙！我们被狗狗人跟踪了！', `FemaleText_loc5`='喔不!有小狗人跟著你!', `FemaleText_loc7`='¡Oh no! ¡Nos han seguido algunos hombres cachorro!' WHERE `ID`=27799;
