UPDATE `locales_broadcast_text` SET `MaleText_loc1`='점장님. 우리 맹독에 여신의 고뇌가 부족하다고 손님들이 항의하시는데요.', `MaleText_loc4`='先生，有客户投诉说我们出售的致命药膏中，魔女之毒的含量不足。', `MaleText_loc5`='先生，我們的客戶在抱怨我們的致命毒藥中魔女的痛苦不夠多。', `MaleText_loc7`='Señor, nuestros clientes se están quejando de que no hay suficiente tormento de doncella en nuestros venenos mortales.' WHERE `ID`=27801;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='점장님, 우리 정신 마취 독에 죽음의 풀이 부족하다고 손님들이 항의하시는데요.', `MaleText_loc4`='先生，有客户投诉说我们出售的麻醉药膏中，丧命草的含量过高。', `MaleText_loc5`='先生，我們的客戶在抱怨我們的麻醉裡太多喪命草了。', `MaleText_loc7`='Señor, nuestros clientes se están quejando de que hay demasiada Muerteflor en nuestros anestésicos.' WHERE `ID`=27802;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='점장님, 지난번에 독을 제조할 때 무기력의 뿌리를 빠트린 것 같습니다.', `MaleText_loc4`='先生，我认为上一张配方中死亡根须的用量已经很接近合适剂量了。', `MaleText_loc5`='先生，我想我們那個最新的毒藥配方中死草根用得差不多了。', `MaleText_loc7`='Señor, creo que estuvimos a punto de acertar con la raíz de letargo en la última receta del veneno.' WHERE `ID`=27803;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라이트, 자네가 만든다던 새 혼합물은 다 만들었나? 가게에 포자가 잔뜩 널려 있는 꼴은 그만 보고 싶단 말일세!', `MaleText_loc4`='乌雷特，你调配出新的混合药剂了吗？店里堆满了该死的孢子，我快被烦死了！', `MaleText_loc5`='萊特，你一直在弄的那個新配方到底搞定了沒?我不想要我的店裡滿是這些孢子!', `MaleText_loc7`='Wright, ¿has acabado el nuevo brebaje en el que estabas trabajando? ¡Estoy cansado de que mi tienda esté llena de esporas!' WHERE `ID`=27804;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 다음에는 두 배로 넣어!', `MaleText_loc4`='下次放双倍的剂量好了！', `MaleText_loc5`='那麼下次放兩倍的量下去!', `MaleText_loc7`='¡La próxima vez echa el doble!' WHERE `ID`=27805;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음에는 반만 집어넣게.', `MaleText_loc4`='下次就放一半的剂量吧。', `MaleText_loc5`='下次放一半就好了。', `MaleText_loc7`='La próxima vez echa solo la mitad.' WHERE `ID`=27806;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 말 잘 듣게, 젊은이. 자넨 항상 자네 생각보다 더 형편없어. 제대로 하게!', `MaleText_loc4`='记住：你犯下的错误永远比你想象的要严重得多。给我加双倍的剂量！', `MaleText_loc5`='小子，記住:你總是比你自認為的還要更糟。放兩倍下去!', `MaleText_loc7`='Recuerda, chico: Siempre estás más equivocado de lo que crees. ¡El doble de equivocado!' WHERE `ID`=27807;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 만들고 있습니다. 만족스러운 품질이 나올 때까지는 손님들에게 내놓지 않으려는 것뿐이에요. 금방 끝날 겁니다.', `MaleText_loc4`='我还在调制啊，我可不想随便出售连我自己都不满意的半成品。用不了多久啦。', `MaleText_loc5`='我正在努力，我只是想要到我覺得滿意了才進行販售。那應該不會花太久時間的。', `MaleText_loc7`='Estoy en ello, pero no quiero venderlo hasta que esté satisfecho. No debería tardar mucho.' WHERE `ID`=27808;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='학살자 스카디가 작살 발사대의 사정거리 안에 들어왔습니다!', `MaleText_loc4`='残忍的斯卡迪已经进入鱼枪的射程！', `MaleText_loc5`='無情的斯卡迪進入魚叉發射器範圍內!', `MaleText_loc7`='¡Skadi el Despiadado está dentro del alcance de los Lanzaarpones!' WHERE `ID`=27809;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='입만 열면 그 소리군. 죽을 때까지 못 끝내는 건 아닌지 모르겠구먼.', `MaleText_loc4`='你每次都这么说。有时候，我甚至怀疑你永远也配制不出那玩意儿。', `MaleText_loc5`='你永遠都是這樣說。有時候我都覺得你永遠都不會把那東西完成。', `MaleText_loc7`='Eso es lo que dices siempre. A veces creo que nunca vas a acabar esa cosa.' WHERE `ID`=27810;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아, 마침내 오셨군요, 아서스 왕자님. 딱 적절한 때에 와주셔서 기쁩니다.', `MaleText_loc4`='啊，是阿尔萨斯王子。您来的正是时候。', `MaleText_loc5`='啊，你終於抵達了，阿薩斯王子。你來的正是時候。', `MaleText_loc7`='Ah, por fin has llegado príncipe Arthas. Llegas justo a tiempo.', `FemaleText_loc1`='아아, 마침내 오셨군요, 아서스 왕자님. 딱 적절한 때에 와주셔서 기쁩니다.', `FemaleText_loc4`='啊，是阿尔萨斯王子。您来的正是时候。', `FemaleText_loc5`='啊，你終於抵達了，阿薩斯王子。你來的正是時候。', `FemaleText_loc7`='Ah, por fin has llegado príncipe Arthas. Llegas justo a tiempo.' WHERE `ID`=27811;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래. 나도 자네를 구할 수 있어 기쁘네.', `MaleText_loc4`='是的，我很高兴能在灾难大爆发之前找到你。', `MaleText_loc5`='是的，我很高興能在瘟疫大爆發之前找到你。', `MaleText_loc7`='Sí, me alegra haber podido alcanzarlos antes que la peste.' WHERE `ID`=27812;
