UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 무슨 조화지?', `MaleText_loc4`='这是什么巫术？', `MaleText_loc5`='這是什麼巫術?', `MaleText_loc7`='¿Qué es esta brujería?' WHERE `ID`=27814;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이해하려고 애쓸 것 없다, 아서스. 너는 그저 죽어주면 그만이야.', `MaleText_loc4`='阿尔萨斯，你不需要弄明白这是什么。你唯一要做的，就是等死。', `MaleText_loc5`='你不需要了解，阿薩斯。你只需要去死。', `MaleText_loc7`='No es necesario que lo entiendas, Arthas. Tan solo tienes que morir.', `FemaleText_loc1`='이해하려고 애쓸 것 없다, 아서스. 너는 그저 죽어주면 그만이야.', `FemaleText_loc4`='阿尔萨斯，你不需要弄明白这是什么。你唯一要做的，就是等死。', `FemaleText_loc5`='你不需要了解，阿薩斯。你只需要去死。', `FemaleText_loc7`='No es necesario que lo entiendas, Arthas. Tan solo tienes que morir.' WHERE `ID`=27815;
