UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어딘가로 가야 하신다면, 제가 보내드릴 수 있답니다.', `FemaleText_loc4`='你要去哪儿吗？我可以送你一程。', `FemaleText_loc5`='如果你想去什麼地方，我可以送你去。', `FemaleText_loc7`='Si tienes que ir a algún sitio, puedo llevarte hasta allí.' WHERE `ID`=27818;
