UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주변 어딘가에서 낮게 으르렁거리는 소리가 들립니다.', `MaleText_loc4`='你听到附近传来一声低沉的咆哮。', `MaleText_loc5`='你聽到附近有一陣發自喉嚨的低沉咆哮。', `MaleText_loc7`='Oyes un grave gruñido gutural que proviene de cerca.' WHERE `ID`=27831;
