UPDATE `locales_broadcast_text` SET `MaleText_loc1`='베크지크를 귀찮게 하지 마라.', `MaleText_loc4`='别打扰维克伊克。', `MaleText_loc5`='別來煩維克吉克。', `MaleText_loc7`='Vekjik no querer ser molestado.' WHERE `ID`=27833;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='베크지크 주술사님, 날름이들과 이야기를 해봤는데 평화를 바라고 있었습니다. 그들을 대신해 이 선물을 가져왔습니다.', `MaleText_loc4`='维克伊克，我诚恳地和大舌头怪们谈过了，他们渴望和平。这是他们赠送的求和礼物。', `MaleText_loc5`='薩滿維克吉克，我和大舌頭談過了，他們想要和平。我替他們帶來了這個提案。', `MaleText_loc7`='Chamán Vekjik, he hablado con los lenguas-grandes y desean la paz. Traigo esta ofrenda de su parte.', `FemaleText_loc1`='베크지크 주술사님, 날름이들과 이야기를 해봤는데 평화를 바라고 있었어요. 그들을 대신해 이 선물을 가져왔어요.', `FemaleText_loc4`='维克伊克，我诚恳地和大舌头怪们谈过了，他们渴望和平。这是他们赠送的求和礼物。', `FemaleText_loc5`='薩滿維克吉克，我和大舌頭談過了，他們想要和平。我替他們帶來了這個提案。', `FemaleText_loc7`='Chamán Vekjik, he hablado con los lenguas-grandes y desean la paz. Traigo esta ofrenda de su parte.' WHERE `ID`=27834;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더러운 날름이 친구 같으니. 너는 여기 있을 자격 없다. 광란심장 일족 땅에서 사라지지 않으면 마법이라도 써서 없애버리겠다!', `MaleText_loc4`='你居然和大舌头怪交朋友，真恶心！你不属于这里。赶紧滚出狂心氏族的土地，不然我就召唤魔法生物干掉你！', `MaleText_loc5`='噁心的大舌頭朋友，你不屬於這裡。離開狂心的土地，否則我將用法術殺死你!', `MaleText_loc7`='Asqueroso amigo de lenguas-grandes, este no ser tu lugar. ¡Irte de tierra Corazón Frenético o yo llamar cosas mágicas para matarte!' WHERE `ID`=27835;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='광란심장 일족은 절대 날름이와 친구 되지 않는다. 이곳에 돌아오다니 멍청한 놈이로구나, 배신자야!', `MaleText_loc4`='狂心氏族永远不会和大舌头怪做朋友。你这个叛徒，竟然还有脸回来！', `MaleText_loc5`='狂心部族才不會跟大舌頭交朋友。你還敢回來這裡，背叛的傢伙!', `MaleText_loc7`='Corazón Frenético nunca ser amigos de lenguas-grandes. ¡Tú $gtonto:tonta; por volver aquí, cosa traidora!' WHERE `ID`=27836;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 돌아온다면 광란심장 일족 손에 죽을 것이다. 우리는 이제 너 환영하지 않는다!', `MaleText_loc4`='你要是敢回来，狂心狼獾人就要你的命。从现在开始，你是我们的敌人！', `MaleText_loc5`='如果你回去狂心就殺你。你不再受歡迎了!', `MaleText_loc7`='Corazón Frenético matarte si tú volver. ¡Tú ya no $gbienvenido:bienvenida; aquí!' WHERE `ID`=27837;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아닙니다... 당신들을 배신할 생각은 없습니다. 나는 자신을 보호했을 뿐입니다. 이건 오해입니다.', `MaleText_loc4`='没有……我没有背叛狂心氏族的意思。我当时只是……正当防卫啊。完全是个误会。', `MaleText_loc5`='不不...我沒有打算要背叛你的同胞。我只是自我防衛。這全是誤會。', `MaleText_loc7`='No, no... Yo no pretendía traicionar a tu gente. Solo me estaba defendiendo. Ha sido un malentendido.', `FemaleText_loc1`='아니요... 당신들을 배신할 생각은 없습니다. 나는 자신을 보호했을 뿐입니다. 이건 오해예요.', `FemaleText_loc4`='没有……我没有背叛狂心氏族的意思。我当时只是……正当防卫啊。完全是个误会。', `FemaleText_loc5`='不不...我沒有打算要背叛你的同胞。我只是自我防衛。這全是誤會。', `FemaleText_loc7`='No, no... Yo no pretendía traicionar a tu gente. Solo me estaba defendiendo. Ha sido un malentendido.' WHERE `ID`=27838;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하늘을 나는 $r|1이;가; 온다! 맞춰서 떨어트려!', `MaleText_loc4`='$r飞行员来啦！击落$g他:她;！', `MaleText_loc5`='$r飛行物靠近!把$g他:她;射下來!', `MaleText_loc7`='¡Viene $gun:una; $r $gvolador:voladora;! ¡Debe caer!' WHERE `ID`=27839;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 스컬지가 아닌데... 대체 무슨 수작이지? 어쨌든 서두르자!', `MaleText_loc4`='看来玛尔加尼斯除了天灾军团的亡灵大军外，还另有秘密武器。我们得抓紧时间了。', `MaleText_loc5`='瑪爾加尼斯的軍隊中似乎並非只有天譴軍團。我們得加快腳步。', `MaleText_loc7`='Mal''Ganis parece tener algo más que la Plaga en su arsenal. Tenemos que apresurarnos.' WHERE `ID`=27840;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='걸작이로군! 트롤에게 먹이게, 호르둠. 그럼 물어보는 대로 술술 불 테니까...', `MaleText_loc4`='大功告成！霍杜姆，让巨魔饮下这贴药剂。他会老老实实地回答所有问题的……', `MaleText_loc5`='真是傑作!把它餵給食人妖，荷頓。他就會老實地回任何問題...', `MaleText_loc7`='¡Una obra maestra! Échasela de comer al trol, Hordum. Responderá con la verdad a cualquier pregunta...' WHERE `ID`=27841;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='때가 됐군요, 핑클스타인. 그럼 이걸 한번 써 보죠!', `MaleText_loc4`='是时候啦，菲肯斯坦。我们来做个试验吧！', `MaleText_loc5`='也該是時候了，芬克斯坦。現在，現在拿這個東西去測試!', `MaleText_loc7`='Ya era hora, Finklestein. ¡Ahora, probemos todo esto!' WHERE `ID`=27842;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 트롤. 쭉 들이키라고!', `MaleText_loc4`='来吧，巨魔。喝下它！', `MaleText_loc5`='好啦，食人妖。全部吞下去!', `MaleText_loc7`='Vale, trol. ¡Por el gaznate!' WHERE `ID`=27843;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일을 험하게 만들지 마라, 트롤.', `MaleText_loc4`='别逼我对你动粗啊，放乖点。', `MaleText_loc5`='不要逼我用粗魯的手段，食人妖。', `MaleText_loc7`='No me hagas recurrir a la fuerza, trol.' WHERE `ID`=27844;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠, 그래 좋아, 트롤. 이동네 그로그주보다 나쁘지는 않겠지...', `MaleText_loc4`='嗯，听我说。它不会比这里出售的掺水烈酒更难喝……', `MaleText_loc5`='嗯，夠了，食人妖。反正也不可能比他們這邊提供的烈酒更難喝...', `MaleText_loc7`='Hmmm, me parece justo, trol. No puede haber nada peor que el grog que sirven por aquí...' WHERE `ID`=27845;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='봤지? 이제 마셔!', `MaleText_loc4`='嘿！一口气喝光吧！', `MaleText_loc5`='吶，快喝!', `MaleText_loc7`='Ahora. ¡Bebed!' WHERE `ID`=27846;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은빛십자군의 일원으로서, 나는 해묵은 감정 따위 버리겠다고 굳게 맹세했지... 하지만...', `MaleText_loc4`='作为银色北伐军的成员，我曾以……嗯……那什么……的名义起誓，绝不计较他人的言行过失……', `MaleText_loc5`='身為銀白十字軍的一員，我立下誓言要將過去的仇恨放到一邊，以...嗝...之名...', `MaleText_loc7`='Como miembro de la Cruzada Argenta he jurado dejar de lado rencillas pasadas en el nombre de... argh, uuugggh...' WHERE `ID`=27847;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 시퍼런 짐승하고는 도저히 함께 못 있겠다니까!', `MaleText_loc4`='我打心眼儿里不想看见这些绿皮肤的野蛮人！', `MaleText_loc5`='我實在很難忍受那些綠皮膚傢伙的目光!', `MaleText_loc7`='¡Apenas puedo soportar la vision de esos salvajes de piel verde!' WHERE `ID`=27848;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='못생긴 데다 냄새나고, 먹을 때는 입을 연 채로 씹어대고, 그리고... 우욱!', `MaleText_loc4`='他们相貌丑陋，还有难闻的体臭！吃东西的时候狼吞虎咽的……哎哟，想起来就恶心！', `MaleText_loc5`='他們又醜，又臭，他們張著嘴吃東西，還有...噁!', `MaleText_loc7`='Son feos, huelen mal, comen con la boca abierta y... ¡buff!' WHERE `ID`=27849;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그대가 날 구원할 것이다.$B$B하지만 날 죽게 할 수도 있다.', `FemaleText_loc4`='你可能为我带来救赎的希望。$B$B你也可能将我送入死亡的深渊。', `FemaleText_loc5`='你是我的救星。$B$B但也可能是我報喪使者。', `FemaleText_loc7`='Tú serás mi salvación.$B$BAunque también puedes ser mi perdición.' WHERE `ID`=27850;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='설마, 농담이겠지, 친구! 내가 왜 그 오물 같은 걸 마시겠어...', `MaleText_loc4`='朋友，开什么玩笑！这是什么鬼东西啊，我可不要喝……', `MaleText_loc5`='你一定在開我玩笑，老兄!我才不要喝這個大便咧...', `MaleText_loc7`='¡Tienes que estar de broma, tron! No pienso beberme esa mugre...' WHERE `ID`=27851;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 이렇게 하지, 친구. 자네가 조금 마셔서 날 독살할 게 아니라는 걸 증명해 봐. 그럼 마실 테니.', `MaleText_loc4`='朋友，你是不是先喝上一口，证明这不是毒药？那样我才会喝的。', `MaleText_loc5`='這樣好了，老兄。你喝一小口，讓我知道你們沒有下毒。這樣我就喝。', `MaleText_loc7`='¿Sabes qué, tron? Pruébalo tú para que vea que no intentas envenenarme. Entonces beberé.' WHERE `ID`=27852;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알았어, 친구. 거래는 거래지. 하지만 먼저 질문이 있는데...', `MaleText_loc4`='好吧。我同意。但首先，我有个问题……', `MaleText_loc5`='好吧，老兄。一言既出，死馬難追。但我有個小問題先...', `MaleText_loc7`='Vale, tron. Un trato es un trato. Pero primero, una preguntita...' WHERE `ID`=27853;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오크랑 그렇게 가까이 붙어서 일해보니 어떤가?', `MaleText_loc4`='你整天和这帮兽人混在一起，感觉怎么样啊？', `MaleText_loc5`='你對於整天跟跟獸人近距離工作有什麼感覺?', `MaleText_loc7`='¿Cómo te sentirías trabajando tan estrechamente con orcos?' WHERE `ID`=27854;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭐라고!?', `FemaleText_loc4`='什么！？', `FemaleText_loc5`='什麼!?', `FemaleText_loc7`='¿¡Qué!?' WHERE `ID`=27855;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여긴 어딥니까? 무얼 하는 곳이죠?', `MaleText_loc4`='接受十字军之力的审判吧！', `MaleText_loc5`='我在哪裡?這是什麼地方?', `MaleText_loc7`='¿Dónde estoy? ¿Qué es este lugar?', `FemaleText_loc1`='여긴 어디죠? 무얼 하는 곳이에요?', `FemaleText_loc4`='接受十字军之力的审判吧！', `FemaleText_loc5`='我在哪裡?這是什麼地方?', `FemaleText_loc7`='¿Dónde estoy? ¿Qué es este lugar?' WHERE `ID`=27856;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내... 내가 악몽을 꾸는 건가?', `MaleText_loc4`='我要代表圣光消灭你们！', `MaleText_loc5`='我...我在夢魘中醒來?', `MaleText_loc7`='¿Me... me he despertado en una pesadilla?', `FemaleText_loc1`='내... 내가 악몽을 꾸는 건가?', `FemaleText_loc4`='我要代表圣光消灭你们！', `FemaleText_loc5`='我...我在夢魘中醒來?', `FemaleText_loc7`='¿Me... me he despertado en una pesadilla?' WHERE `ID`=27857;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다... 당신은 누굽니까? 난 누구... 아니, 난 뭡니까?', `MaleText_loc4`='十字军的审判已经降临了，死亡骑士！', `MaleText_loc5`='誰...你是誰?我...我又是誰?', `MaleText_loc7`='¿Quién... quién eres tú? ¿Quién... qué soy yo?', `FemaleText_loc1`='다... 당신은 누구죠? 난 누구... 아니, 난 뭐죠?', `FemaleText_loc4`='十字军的审判已经降临了，死亡骑士！', `FemaleText_loc5`='誰...你是誰?我...我又是誰?', `FemaleText_loc7`='¿Quién... quién eres tú? ¿Quién... qué soy yo?' WHERE `ID`=27858;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아픕니다... 참을 수 없을 정도로... 이 고통을 끝내 주십시오... 제발요!', `MaleText_loc4`='卑鄙的死亡骑士，你们的末日就要到了！', `MaleText_loc5`='我好痛...無法承受的痛楚...終結我的痛苦...求求你!', `MaleText_loc7`='Me duele... no soporto el sufrimiento... acaba con mi miseria... ¡Te lo ruego!', `FemaleText_loc1`='아파요... 참을 수 없을 정도로... 이 고통을 끝내 주세요... 제발요!', `FemaleText_loc4`='卑鄙的死亡骑士，你们的末日就要到了！', `FemaleText_loc5`='我好痛...無法承受的痛楚...終結我的痛苦...求求你!', `FemaleText_loc7`='Me duele... no soporto el sufrimiento... acaba con mi miseria... ¡Te lo ruego!' WHERE `ID`=27859;
