UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공포에 떠는 게 느껴지는군...', `MaleText_loc4`='你竟然混进了黑锋要塞，十字军！', `MaleText_loc5`='我嗅到了恐懼...', `MaleText_loc7`='Huelo su miedo...' WHERE `ID`=27863;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 녀석은 너무 일찍 깨어났다. 아직 감정과 기억이 남았어...', `MaleText_loc4`='说的好，但这毫无意义……', `MaleText_loc5`='這個醒得太快了。它還保有情緒與記憶...', `MaleText_loc7`='Este se ha despertado demasiado pronto. Aún conserva emociones y recuerdos...' WHERE `ID`=27864;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='애처롭군...', `MaleText_loc4`='可怜虫……', `MaleText_loc5`='可悲...', `MaleText_loc7`='Patético...' WHERE `ID`=27865;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쓸모없다는 녀석임이 판명되었으니 널 기다리는 거라곤 하나뿐이군.', `MaleText_loc4`='这些十字军伪装成新兵潜入了黑锋要塞。', `MaleText_loc5`='經過了估量，你還不夠格...', `MaleText_loc7`='Te hemos evaluado y no das la talla.' WHERE `ID`=27866;
