UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 놀라운 끈기와 생명력을 보라! 용사를 발견했군!', `MaleText_loc4`='令人钦佩的坚韧与魄力！一位新的勇士诞生啦！', `MaleText_loc5`='它的韌性與活力真是太驚人了!勇士已經找到了!', `MaleText_loc7`='¡Maravíllate ante su tenacidad y vigor! ¡Hemos encontrado un campeón!' WHERE `ID`=27868;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕께서 이 수습 기사를 마음에 들어 하실 것이다.', `MaleText_loc4`='巫妖王一定会对这位死亡骑士新兵感到满意的。', `MaleText_loc5`='巫妖王將會對這樣的入信者感到滿意。', `MaleText_loc7`='El Rey Exánime estará satisfecho con este iniciado.' WHERE `ID`=27869;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쓰레기더미 속에서 용사를 찾아냈구나.', `MaleText_loc4`='在这样一群可怜虫里，总算有位勇士脱颖而出。', `MaleText_loc5`='在這些可鄙的傢伙之中，找到了一位勇士。', `MaleText_loc7`='Entre los miserables, se ha encontrado a un campeón.' WHERE `ID`=27870;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혼돈! 절망! 파괴! 이자는 그 모든 것을 손에 넣을 것이다!', `MaleText_loc4`='混乱！厄运！毁灭！它将拥有一切破坏性的力量！', `MaleText_loc5`='混沌!死亡!摧毀!這個會擁有它們全部!', `MaleText_loc7`='¡CAOS! ¡PERDICIÓN! ¡DESTRUCCIÓN! ¡Este los reivindicará todos!' WHERE `ID`=27871;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음의 선구자가 새로 태어났군...', `MaleText_loc4`='死亡的预言者已经重生……', `MaleText_loc5`='一位死亡的先驅者已獲重生...', `MaleText_loc7`='Un presagista de la muerte ha vuelto a nacer...' WHERE `ID`=27872;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='녀석에게 아서스 님의 사자에 어울리는 예복을 갖추어 줘라.', `MaleText_loc4`='让它穿上阿尔萨斯传令官的服饰。', `MaleText_loc5`='替他賦予一道屬於阿薩斯信使的印記。', `MaleText_loc7`='Colocad sobre él la parafernalia digna de un heraldo de Arthas.' WHERE `ID`=27873;
