UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠의 힘이 내 몸을 타고 흐른다... 놀라운 힘이! 난 더 많은 힘을 원해!', `MaleText_loc4`='黑暗的能量在我体内涌动……强大的力量！我渴求更多的力量！', `MaleText_loc5`='黑暗的能量在我身上流動...多麼強大的力量!我還要更多!', `MaleText_loc7`='La energía oscura fluye dentro de mí... ¡Cuánto poder! ¡Deseo más!', `FemaleText_loc1`='어둠의 힘이 내 몸을 타고 흐른다... 놀라운 힘이! 난 더 많은 힘을 원해!', `FemaleText_loc4`='黑暗的能量在我体内涌动……强大的力量！我渴求更多的力量！', `FemaleText_loc5`='黑暗的能量在我身上流動...多麼強大的力量!我還要更多!', `FemaleText_loc7`='La energía oscura fluye dentro de mí... ¡Cuánto poder! ¡Deseo más!' WHERE `ID`=27877;
