UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 이 당당한 목소리는... 아서스 님... 나의 왕이시여...', `MaleText_loc4`='这声音……多么高贵……阿尔萨斯陛下……我的王……', `MaleText_loc5`='那個聲音...多麼莊嚴...阿薩斯...吾王...', `MaleText_loc7`='La voz... qué esplendor... Arthas... Mi rey...', `FemaleText_loc1`='아... 이 당당한 목소리는... 아서스 님... 나의 왕이시여...', `FemaleText_loc4`='这声音……多么高贵……阿尔萨斯陛下……我的王……', `FemaleText_loc5`='那個聲音...多麼莊嚴...阿薩斯...吾王...', `FemaleText_loc7`='La voz... qué esplendor... Arthas... Mi rey...' WHERE `ID`=27879;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 주인님의 명령을 따르고자 죽음에서 돌아왔다.', `MaleText_loc4`='为了执行主人的命令，我从坟墓中醒来。', `MaleText_loc5`='我死而復生以完成吾主的命令。', `MaleText_loc7`='Regreso de la tumba para obedecer la voluntad de mi maestro.', `FemaleText_loc1`='나는 주인님의 명령을 따르고자 죽음에서 돌아왔다.', `FemaleText_loc4`='为了执行主人的命令，我从坟墓中醒来。', `FemaleText_loc5`='我死而復生以完成吾主的命令。', `FemaleText_loc7`='Regreso de la tumba para obedecer la voluntad de mi maestro.' WHERE `ID`=27880;
