UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고개를 들고 일어나라! 일어나라. 너의 주인님께서 너를 기다리고 계신다. 어서 가라!', `MaleText_loc4`='站起来吧！主人在等待着你们。去吧！', `MaleText_loc5`='起身並接受檢驗!甦醒，你的主人正等待著你。去吧!', `MaleText_loc7`='¡Levántense para ser medidos! Alcen, pues tu maestro espera tu llegada. ¡Ve ahora!|n' WHERE `ID`=27883;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='들어라, 죽음의 기사여... 네 주인님의 목소리를 들어라. 그분께서 너를 부르신다.', `MaleText_loc4`='听，死亡骑士……是主人的声音。他在召唤你。', `MaleText_loc5`='聽著，死亡騎士...聽著你主人的聲音。他現在正呼喚著你。', `MaleText_loc7`='Escucha, caballero de la Muerte... Escucha la voz de tu maestro. Te está llamando ahora.', `FemaleText_loc1`='들어라, 죽음의 기사여... 네 주인님의 목소리를 들어라. 그분께서 너를 부르신다.', `FemaleText_loc4`='听，死亡骑士……是主人的声音。他在召唤你。', `FemaleText_loc5`='聽著，死亡騎士...聽著你主人的聲音。他現在正呼喚著你。', `FemaleText_loc7`='Escucha, caballero de la Muerte... Escucha la voz de tu maestro. Te está llamando ahora.' WHERE `ID`=27884;
