UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신에게 빚을 졌군요.', `MaleText_loc4`='朋友，我欠你一份情。', `MaleText_loc5`='我欠你一份情，朋友。', `MaleText_loc7`='Estoy en deuda contigo, colega.', `FemaleText_loc1`='당신에게 빚을 졌군요.', `FemaleText_loc4`='朋友，我欠你一份情。', `FemaleText_loc5`='我欠你一份情，朋友。', `FemaleText_loc7`='Estoy en deuda contigo, colega.' WHERE `ID`=27899;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 주변에 서식하는 놈들처럼 근사한 비룡을 본 적 있소? 사냥감으로 아주 그만이라오.', `MaleText_loc4`='你没见过始祖龙吗？喏，这周围到处都是啊。祝你狩猎愉快。', `MaleText_loc5`='你在附近見過這樣的飛龍嗎?似乎是個完美的獵物。', `MaleText_loc7`='¿Alguna vez has visto dracos como los de aquí? Son perfectos para cazar.' WHERE `ID`=27900;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뒤를 조심해라. 놈들은 우릴 포위하고 있어.', `MaleText_loc4`='小心背后，我们被包围了。', `MaleText_loc5`='小心背後，我們被包圍在大廳了。', `MaleText_loc7`='Cuiden la retaguardia: nos tienen rodeados en este recinto.' WHERE `ID`=27901;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말가니스가 잔꾀를 부리는군.', `MaleText_loc4`='玛尔加尼斯不会让我们好过的。', `MaleText_loc5`='瑪爾加尼斯不會輕易放過我們。', `MaleText_loc7`='Mal''Ganis no nos facilitará nada.' WHERE `ID`=27902;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 강화된 신비한 폭발을 시전합니다!', `MaleText_loc4`='%s开始施放强化魔爆术！', `MaleText_loc5`='%s開始施展強力魔爆術!', `MaleText_loc7`='¡%s comienza a lanzar Deflagración arcana potenciada!' WHERE `ID`=27903;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바퀴벌레 같은 놈들...', `MaleText_loc4`='它们还真是够顽强的。', `MaleText_loc5`='它們還真是夠頑強的。', `MaleText_loc7`='Son muy perseverantes.' WHERE `ID`=27904;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이젠 어떻게 방해할 작정이지?', `MaleText_loc4`='他还会派些什么东西来阻挡我们？', `MaleText_loc5`='他還有什麼辦法阻擋我?', `MaleText_loc7`='¿Qué más puede interponer en mi camino?' WHERE `ID`=27905;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 책장 뒤에, 말가니스에게 가는 지름길이 있다.', `MaleText_loc4`='通向玛尔加尼斯的最短路线就在前面那个书架之后。', `MaleText_loc5`='通往瑪爾加尼斯的捷徑就藏在書架後頭。', `MaleText_loc7`='El camino más rápido a Mal''Ganis está detrás de esa estantería.' WHERE `ID`=27906;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='녀석의 힘을 계속 빼 놔라!', `MaleText_loc4`='不要给他喘息的机会！', `MaleText_loc5`='讓他保持衰弱!', `MaleText_loc7`='¡Mantenedlo debilitado!', `FemaleText_loc1`='녀석의 힘을 계속 빼 놔라!', `FemaleText_loc4`='不要给他喘息的机会！', `FemaleText_loc5`='讓他保持衰弱!', `FemaleText_loc7`='¡Mantenedlo debilitado!' WHERE `ID`=27907;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='루노크가 힘을 되찾으면 우린 모두 죽는다!', `MaleText_loc4`='如果伦诺克恢复力量，那我们就死定了！', `MaleText_loc5`='如果魯諾克恢復了他的力量，我們就死定了!', `MaleText_loc7`='¡Si Rhunok recupera las fuerzas, moriremos todos!', `FemaleText_loc1`='루노크가 힘을 되찾으면 우린 모두 죽는다!', `FemaleText_loc4`='如果伦诺克恢复力量，那我们就死定了！', `FemaleText_loc5`='如果魯諾克恢復了他的力量，我們就死定了!', `FemaleText_loc7`='¡Si Rhunok recupera las fuerzas, moriremos todos!' WHERE `ID`=27908;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곰 신이 쇠약한 상태여야 예언자가 의식을 마칠 수 있다.', `MaleText_loc4`='必须让巨熊之神处于虚弱状态，这样先知才能完成仪式。', `MaleText_loc5`='熊神一定要維持衰弱無力，否則預言者無法完成儀式。', `MaleText_loc7`='Hay que mantener al dios oso debilitado para que el profeta pueda completar el ritual.', `FemaleText_loc1`='곰 신이 쇠약한 상태여야 예언자가 의식을 마칠 수 있다.', `FemaleText_loc4`='必须让巨熊之神处于虚弱状态，这样先知才能完成仪式。', `FemaleText_loc5`='熊神一定要維持衰弱無力，否則預言者無法完成儀式。', `FemaleText_loc7`='Hay que mantener al dios oso debilitado para que el profeta pueda completar el ritual.' WHERE `ID`=27909;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주위에 침입자가 있군. 놈들이 일을 망치기 전에 없애라!', `MaleText_loc4`='入侵者！杀死他们，不然他们会毁了一切！', `MaleText_loc5`='入侵者靠近了。殺死他們免得他們毀了一切!', `MaleText_loc7`='Hay intrusos por aquí. ¡Matadlos antes de que lo arruinen todo!', `FemaleText_loc1`='주위에 침입자가 있군. 놈들이 일을 망치기 전에 없애라!', `FemaleText_loc4`='入侵者！杀死他们，不然他们会毁了一切！', `FemaleText_loc5`='入侵者靠近了。殺死他們免得他們毀了一切!', `FemaleText_loc7`='Hay intrusos por aquí. ¡Matadlos antes de que lo arruinen todo!' WHERE `ID`=27910;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아서스 메네실 왕자, 오늘 엄청난 암흑이 네 영혼을 사로잡았다. 네가 다른 이에게 안겨주려고 했던 죽음은, 오늘 널 찾아올 것이다.', `MaleText_loc4`='阿尔萨斯·米奈希尔王子殿下，今天，你的灵魂已经被某种强大的黑暗力量侵蚀。你想要以死亡净化这座城市，现在你也要面对毁灭的命运了。', `MaleText_loc5`='阿薩斯·米奈希爾王子，就在這一天，你的靈魂被一股巨大的黑暗所竊佔。你註定要散播給他人的死亡，將在今日早一步來拜訪你。', `MaleText_loc7`='Príncipe Arthas Menethil: en este día, una oscuridad inmensa se ha apoderado de tu alma. La muerte que siempre has infligido a otros, hoy viene a ti.' WHERE `ID`=27911;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 끝이군. 그냥 그런 감이 와...', `MaleText_loc4`='我就知道会这样……', `MaleText_loc5`='就是它，我就是知道...', `MaleText_loc7`='Es este, lo sé...' WHERE `ID`=27912;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 배는 분명히 날 덮칠 거야...', `MaleText_loc4`='那艘船肯定会撞上我……', `MaleText_loc5`='那艘船一定會撞上我...', `MaleText_loc7`='Ese barco va a golpearme seguro...' WHERE `ID`=27913;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='볼 수가 없...', `MaleText_loc4`='我不敢睁眼……', `MaleText_loc5`='我不敢看...', `MaleText_loc7`='No puedo mirar...' WHERE `ID`=27914;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좀 천천히 다닐 수는 없나?', `MaleText_loc4`='他们就不能放慢速度吗？', `MaleText_loc5`='他們不能慢一點嗎?', `MaleText_loc7`='¿No pueden ir un poquito más despacio?' WHERE `ID`=27915;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 로데론을 지킬 뿐이다. 네가 무슨 짓을 해도 날 막을 수는 없어.', `MaleText_loc4`='为了洛丹伦，我会竭尽所能，无论是你的言论还是行为，都无法阻止我。', `MaleText_loc5`='我的一切決定都是為了羅德隆，你的言詞或行動都無法阻止我。', `MaleText_loc7`='Cumplo mi deber para Lordaeron, y ni tus palabras ni tus acciones podrán detenerme.' WHERE `ID`=27916;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 날 향해 오잖아!', `MaleText_loc4`='它冲我来了！', `MaleText_loc5`='它正朝我衝過來!', `MaleText_loc7`='¡Viene directo a por mí!' WHERE `ID`=27917;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='속도가 너무 빨라!', `MaleText_loc4`='居然还不减速！', `MaleText_loc5`='它沒有慢下來!', `MaleText_loc7`='¡No está frenando!' WHERE `ID`=27918;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으악, 안 돼!', `MaleText_loc4`='噢……天哪！', `MaleText_loc5`='喔不!!!', `MaleText_loc7`='¡OH NO!' WHERE `ID`=27919;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두고 보면 알겠지, 젊은 왕자여.', `MaleText_loc4`='那就来吧，年轻的王子。', `MaleText_loc5`='我們走著瞧，年輕的王子。', `MaleText_loc7`='Nos ocuparemos de ello, joven príncipe.' WHERE `ID`=27920;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심해!', `MaleText_loc4`='当心！', `MaleText_loc5`='小心!', `MaleText_loc7`='¡Cuidado!' WHERE `ID`=27921;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 다 끝났어...', `MaleText_loc4`='完蛋了……', `MaleText_loc5`='全完了...', `MaleText_loc7`='Se acabó todo...' WHERE `ID`=27922;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아들놈에게 나는 네가 자랑스럽다고 말해주지 못했는데...', `MaleText_loc4`='我还没有告诉儿子，他是我的骄傲……再也没有机会了……', `MaleText_loc5`='我永遠也沒機會告訴我兒子，我有多以他為傲...', `MaleText_loc7`='Jamás podré decirle a mi hijo lo orgulloso que estoy de él...' WHERE `ID`=27923;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 아직 죽을 때가 아니라고...', `MaleText_loc4`='我还不想死……', `MaleText_loc5`='我還沒準備好要死...', `MaleText_loc7`='No estoy preparado para morir...' WHERE `ID`=27924;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직도 하고 싶은 게 너무 많아...', `MaleText_loc4`='我还有很多梦想没有实现……', `MaleText_loc5`='還有好多事情我想做...', `MaleText_loc7`='Me quedan tantas cosas que quiero hacer...' WHERE `ID`=27925;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 소리 들었나?', `MaleText_loc4`='你听见什么了吗？', `MaleText_loc5`='你有聽到什麼嗎?', `MaleText_loc7`='¿Has oído algo?' WHERE `ID`=27926;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 소리는 대체 뭔가?', `MaleText_loc4`='那是什么声音？', `MaleText_loc5`='那是什麼聲音?', `MaleText_loc7`='¿Qué es ese ruido?' WHERE `ID`=27927;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 망할 칼 좀 닥치게 하게, 모그레인. 쉴 새 없이 떠드는 게 아주 지긋지긋하군.', `MaleText_loc4`='莫格莱尼，让那把该死的剑闭嘴。它发出的哀鸣令我难以忍受。', `MaleText_loc5`='把那柄該死的劍上個套子，莫格萊尼。我實在受夠了它不停地唉唉叫。', `MaleText_loc7`='Ponle un bozal a la maldita espada, Mograine. Estoy harto y cansando de su incesante lloriqueo.' WHERE `ID`=27928;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좀 닥치게 하라니까! 그렇게 계속 주절대고 있으니 아무 생각도 못 하겠단 말일세!', `MaleText_loc4`='让它闭嘴！什么破玩意儿！吵个不停，我简直没法思考！', `MaleText_loc5`='叫那個東西閉嘴!那把劍在那邊沒完沒了的碎碎念，讓我沒辦法思考!', `MaleText_loc7`='¡Haz que se calle esa cosa! ¡No puedo pensar con esa espada charlando sin parar!' WHERE `ID`=27929;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죄송합니다. 저희 맥주는 맥주 사랑 동호회 회원 분들께만 판매합니다.', `MaleText_loc4`='很抱歉，我们的啤酒只对“本月美酒俱乐部”的会员出售。', `MaleText_loc5`='很抱歉，我們的啤酒專屬「每月啤酒俱樂部」會員獨享。', `MaleText_loc7`='Lo siento, pero nuestras cervezas son exclusivamente para los miembros de "El Club de la Cerveza del Mes."', `FemaleText_loc1`='죄송해요. 저희 맥주는 맥주 사랑 동호회 회원 분들께만 판매한답니다.', `FemaleText_loc4`='很抱歉，我们的啤酒只对“本月美酒俱乐部”的会员出售。', `FemaleText_loc5`='很抱歉，我們的啤酒專屬「每月啤酒俱樂部」會員獨享。', `FemaleText_loc7`='Lo siento, pero nuestras cervezas son exclusivamente para los miembros de "El Club de la Cerveza del Mes."' WHERE `ID`=27930;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 초소는 안전하다오, $r|1이여;여;.$b$b한동안은 적이 여기 얼씬거리지 않을 거요.', `MaleText_loc4`='这座岗哨目前是安全的，$r。$b$b敌人暂时不敢再次来犯。', `MaleText_loc5`='這個崗哨是安全的，$r。$b$b敵人已經掃出這個區域一段時間了。', `MaleText_loc7`='Este puesto es seguro, $r.$B$BHace ya algún tiempo que se eliminaron a los enemigos de esta zona.' WHERE `ID`=27931;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='스컬지는 엄청난 속도로 세력을 확장하고 있어요. 가끔 왜 놈들이 아직도 이 전쟁에서 승리하지 못했는지 이상할 지경이라니까요.', `FemaleText_loc4`='天灾军团扩张如此迅速，我有时都忍不住会想，他们怎么还没赢得这场战争呢。', `FemaleText_loc5`='天譴軍團擴張的速度如此驚人，我覺得他們早就該在這場戰爭中大獲全勝才對。', `FemaleText_loc7`='La plaga se extendió tan rápidamente que a menudo me pregunto cómo es posible que no hayan ganado ya esta guerra.' WHERE `ID`=27932;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 드디어 드락타론 성채에 돌아왔군!', `MaleText_loc4`='啊，终于回到了达克萨隆要塞！', `MaleText_loc5`='啊，終於回到德拉克薩隆了!', `MaleText_loc7`='¡Ah, nuevamente en Drak''Tharon!' WHERE `ID`=27933;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드라쿠루가 드락타론 성채를 내려다봅니다.', `MaleText_loc4`='达库鲁凝视着达克萨隆要塞。', `MaleText_loc5`='德拉庫魯將他的目光投向了德拉克薩隆要塞。', `MaleText_loc7`='Drakuru posa la vista sobre la Fortaleza de Drak''Tharon.' WHERE `ID`=27934;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘했네, 친구...', `MaleText_loc4`='朋友，干得好……', `MaleText_loc5`='做的好，老兄...', `MaleText_loc7`='Bien hecho, colega.' WHERE `ID`=27935;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하! 제피크의 말이 맞았군. 날름이들은 정말 멋진 사냥감이야!', `MaleText_loc4`='哈！瑟匹克没说错，猎杀大舌头怪是挺好玩的！', `MaleText_loc5`='哈!賽匹克是對的，大舌頭是好獵物!', `MaleText_loc7`='¡Ja! ¡Zepik en lo cierto, lenguas-grandes ser la mejor caza!' WHERE `ID`=27942;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날름이 사냥은 정말 재미있군! 종종 노예를 데리고 와야겠어!', `MaleText_loc4`='狩猎大舌头怪真有趣啊！格利基克以后要常带奴隶来玩！', `MaleText_loc5`='殺大舌頭真有趣!茍瑞格克應該常跟奴隸傢伙一起去!', `MaleText_loc7`='¡Matar lenguas-grandes es divertido! ¡Goregek debería ir con cosa esclava más a menudo!' WHERE `ID`=27943;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='머지않아 카르탁이 와서 마을을 몽땅 삼켜버릴지도 모르겠군! 하하!', `MaleText_loc4`='没准卡塔克待会就出现，然后吞下整个村子！哈！', `MaleText_loc5`='或許卡爾塔克很快就來，然後把全村給吃光光!哈!', `MaleText_loc7`='¡Quizá Kartak volver pronto y comer poblado entero! ¡Ja!' WHERE `ID`=27944;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가시털멧돼지 사냥이 이것보단 힘들지! 한심한 날름이들 같으니.', `MaleText_loc4`='猎杀钢刺野猪的难度大得多！愚蠢的大舌头怪。', `MaleText_loc5`='鬃松還比這個難狩獵!愚蠢的大舌頭。', `MaleText_loc7`='¡Pinocerdas es más difícil de cazar que esto! Estúpidos lenguas-grandes.' WHERE `ID`=27945;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 고어게크는 최고의 사냥꾼이다. 알겠나, 노예?', `MaleText_loc4`='格利基克是最棒的猎人，是不是啊？', `MaleText_loc5`='茍瑞格克最棒的獵人，對吧，奴隸傢伙?', `MaleText_loc7`='Goregek mejor cazador, ¿verdad, cosa esclava?' WHERE `ID`=27946;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 좀 해봐, 번개뭐시기 놈들아! 하하! 정말 재밌군.', `MaleText_loc4`='尝尝长矛的滋味！哈哈！格利基克挺爱开玩笑的。', `MaleText_loc5`='試試看矛觸!哈!苟瑞格克真幽默。', `MaleText_loc7`='¡Prueba la lanza! ¡Ja! Goregek ser muy gracioso.' WHERE `ID`=27947;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 바랄 수 없을 만큼 훌륭했어.', `MaleText_loc4`='你远远超出了我的期望。', `MaleText_loc5`='你遠遠超出了我的期望。', `MaleText_loc7`='Superaste todas mis expectativas.' WHERE `ID`=27954;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말벌 놈들, 고어게크의 손이 닿지 않는 곳에서 날아다니는군.', `MaleText_loc4`='那些嗡嗡叫的蓝蜂都躲在格利基克打不到的地方。', `MaleText_loc5`='黃蜂傢伙飛到了茍瑞格克打不到的地方。', `MaleText_loc7`='Cosas avispa volar a donde Goregek no poder pegarles.' WHERE `ID`=27955;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 다지크의 사냥감이야. 가자, 노예.', `MaleText_loc4`='交给达伊克来办吧。奴隶，我们走。', `MaleText_loc5`='這是達吉克的狩獵。走吧，奴隸傢伙。', `MaleText_loc7`='Esta ser la caza de Dajik. Vamos, cosa esclava.' WHERE `ID`=27956;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기는 가시털멧돼지가 없군. 다른 곳으로 가자.', `MaleText_loc4`='这里没有钢刺野猪，我们去别的地方吧。', `MaleText_loc5`='這裡沒有鬃松，去別處吧。', `MaleText_loc7`='No pinocerdas aquí, ir a otro sitio.' WHERE `ID`=27957;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 노예... 고어게크는 예전에 거대하고 못된 여왕 말벌에게 쏘인 적이 있다. 벌레라면 아주 지긋지긋하다.', `MaleText_loc4`='听着，奴隶……格利基克被那只坏心肠的蜂后蜇过。所以啊，格利基克才不要招惹它们。', `MaleText_loc5`='看，奴隸傢伙...茍瑞格克給又大又壞得黃蜂女王螫過一次。茍瑞格克跟黃蜂不玩了。', `MaleText_loc7`='Mirar, cosa esclava... Reina avispa grande y mala picar a Goregek una vez. Goregek no querer saber nada de avispas.' WHERE `ID`=27958;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 고어게크가 날름이 사냥 좋아하긴 하지만, 여긴 수가 너무 많다, 노예.', `MaleText_loc4`='格利基克喜欢猎杀大舌头怪，但他们的数量似乎太多了点。', `MaleText_loc5`='苟瑞格克喜歡殺大舌頭，但他們實在太多了，奴隸傢伙。', `MaleText_loc7`='A Goregek gustar matar lenguas-grandes, pero haber demasiadas aquí, cosa esclava.' WHERE `ID`=27961;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳은 위험하다, 노예. 여긴 날름이들 고향이라고.', `MaleText_loc4`='奴隶，这里很不安全。这里是大舌头怪的老窝。', `MaleText_loc5`='這裡不安全，奴隸傢伙。這是大舌頭的家。', `MaleText_loc7`='No ser seguro aquí, cosa esclava. Esto ser hogar de lenguas-grandes.' WHERE `ID`=27962;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='광란심장 일족은 혼자 이곳에 오지 않는다. 노예라도 마찬가지다.', `MaleText_loc4`='狂心狼獾人不会独自闯入这里。奴隶也不该。', `MaleText_loc5`='狂心不會自己到這來。奴隸傢伙也不應該來。', `MaleText_loc7`='Corazón Frenético no venir aquí solos. Cosa esclava no deber tampoco.' WHERE `ID`=27963;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들을 꾀어내라, 노예. 난 여기서 지켜본다. 재미있겠군.', `MaleText_loc4`='你去将他们引出来。我待在这里监视情况。去吧，好戏即将上演。', `MaleText_loc5`='你把他們引出來，奴隸傢伙。我站在這邊看。好好表演。', `MaleText_loc7`='Tu hacerlos salir, cosa esclava. Yo quedar aquí y mirar. Buen espectáculo.' WHERE `ID`=27964;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장로가 뭐라 말하든 간에 넌 영원히 고어게크의 노예다.', `MaleText_loc4`='我可不管长者怎么说，反正你永远都是格利基克的奴隶。', `MaleText_loc5`='長者也許會說別的，但你永遠都是苟瑞格克的奴隸傢伙。', `MaleText_loc7`='A lo mejor anciano decir otra cosa, pero tú siempre ser cosa esclava de Goregek.' WHERE `ID`=27965;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 멍청하게 앉아 있지? 움직여라, 노예!', `MaleText_loc4`='别想偷懒。奴隶，赶紧做事！', `MaleText_loc5`='為什麼你在這邊發呆?去工作，奴隸傢伙!', `MaleText_loc7`='¿Por qué estar sentado? ¡Ponerte a trabajar, cosa esclava!' WHERE `ID`=27966;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 절대 이 고어게크처럼 잘할 수 없다.', `MaleText_loc4`='你永远无法达到格利基克的境界。', `MaleText_loc5`='你永遠也不可能跟苟瑞格克一樣好。', `MaleText_loc7`='Nunca serás tan bueno como Goregek.' WHERE `ID`=27967;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진짜 훌륭한 가시털멧돼지 사냥꾼은 이 고어게크 뿐이다!', `MaleText_loc4`='格利基克是最最优秀的钢刺野猪猎手！', `MaleText_loc5`='苟瑞格克是唯一的好鬃松獵人!', `MaleText_loc7`='¡Goregek ser el único buen cazador de pinocerdas!' WHERE `ID`=27968;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은 갈기는 어차피 약해빠졌어... 아니면 이 고어게크가 왜 그놈을 그냥 놔두겠어?', `MaleText_loc4`='匹奇根本构不成威胁嘛……要不然格利基克肯定不会放过他。', `MaleText_loc5`='總之匹奇已經衰弱了...不然你以為苟瑞格克幹嘛招惹他?', `MaleText_loc7`='Brea era débil de todas formas... ¿por qué creer que Goregek no molestarse con él?' WHERE `ID`=27969;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쓸모없는 놈 같으니. 왜 고어게크가 네놈 따위를 신경 써야 하는지 모르겠다.', `MaleText_loc4`='你真没用。格利基克干嘛要为你心烦啊。', `MaleText_loc5`='你沒用的東西。苟瑞格克不知道為什麼你要煩他。', `MaleText_loc7`='Tú inútil. Goregek no saber por qué molestarse contigo.' WHERE `ID`=27970;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 고어게크는 강의 심장부를 가득 메울 정도로 많은 가시털멧돼지들을 해치웠다!', `MaleText_loc4`='死在格利基克手里的钢刺野猪可以填满河流之心！', `MaleText_loc5`='苟瑞格克殺死了這麼多鬃松，都可以把大河之心填滿了!', `MaleText_loc7`='¡Goregek haber matado tantos pinocerda que poder llenar el Corazón del Río!' WHERE `ID`=27971;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 고어게크가 생각하기에 산을 넘어가면 가시털멧돼지들이 더 있을 것 같다. 나중에 꼭 확인해 봐야겠군.', `MaleText_loc4`='不知道山那边有没有钢刺野猪。格利基克要找时间去瞧瞧。', `MaleText_loc5`='苟瑞格克在想如果山另一頭還有更多鬃松。有一天，苟瑞格克會去瞧瞧。', `MaleText_loc7`='Goregek preguntarse si haber más pinocerdas más allá de montañas. Algún día, Goregek ir a ver.' WHERE `ID`=27972;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무너진 기둥에는 가시털멧돼지가 없다. 온통 시체뿐이다. 고어게크는 떠날 거다, 노예.', `MaleText_loc4`='破柱子附近根本没有钢刺野猪，只看见一堆死尸。奴隶，跟格利基克走吧。', `MaleText_loc5`='斷掉的柱子那邊沒有鬃松，只有死的東西。茍瑞格克要走了，奴隸傢伙。', `MaleText_loc7`='No pinocerdas en Pilar Partido. Goregek marcharse, cosa esclava.' WHERE `ID`=27973;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽고 싶다면 무너진 기둥으로 계속 가봐라, 노예. 고어게크는 가까이 안 가고 안 죽을 거다.', `MaleText_loc4`='蠢奴隶，你要是想死，就径直朝那根破柱子走过去吧。格利基克还想活命呢，我先撤了。', `MaleText_loc5`='如果奴隸傢伙想死，奴隸傢伙就去斷掉的柱子。苟瑞格克要走掉，不想死。', `MaleText_loc7`='Si cosa esclava querer morir, cosa esclava seguir yendo a Pilar Partido. Goregek marcharse y no morir.' WHERE `ID`=27974;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 무너진 기둥으로 가는 거지? 멍청한 노예. 고어게크는 떠난다.', `MaleText_loc4`='为什么要去破柱子那里啊？你这个蠢奴隶。格利基克要走了。', `MaleText_loc5`='為什麼要去斷掉的柱子?你傻啦，奴隸傢伙。苟瑞格克去。', `MaleText_loc7`='¿Por qué ir a Pilar Partido? Tú cosa esclava estúpida. Goregek ir.' WHERE `ID`=27975;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여긴 시체들밖에 없다. 고어게크는 떠난다.', `MaleText_loc4`='这里只有一堆死尸。格利基克要走了。', `MaleText_loc5`='那裡只有死的東西。苟瑞格克要走了。', `MaleText_loc7`='Aquí solo cosas muertas. Goregek se va.' WHERE `ID`=27976;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고어게크는 카르탁을 본 적이 없다. 다른 자들이 얘기했던 것처럼 지독한 놈은 아닐 것 같다.', `MaleText_loc4`='格利基克没有见过卡塔克。格利基克猜想，他或许没有别人说的那么坏吧。', `MaleText_loc5`='苟瑞格克還沒見過卡爾塔克。苟瑞格克不覺得他像別人說得那麼壞。', `MaleText_loc7`='Goregek aún no ha visto a Kartak. Goregek no cree que sea tan malo como dicen otros.' WHERE `ID`=27977;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라크자크는 카르탁이 날름이들 마을 하나를 완전히 먹어버린 적이 있다고 했다. 분명히 맛있었을 거다.', `MaleText_loc4`='拉克亚克说卡塔克曾经一口吞下整座村子的大舌头怪。他们的味道想必美极了。', `MaleText_loc5`='拉克杰克說卡爾塔克一次吃掉一整個村子的大舌頭。他們一定很好吃。', `MaleText_loc7`='Rakjak decir que Kartak comerse poblado entero de lenguas-grandes una vez. Tener que estar ricos.' WHERE `ID`=27978;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카르탁의 주둥이 근처에서 얼씬거리지 마라, 노예. 너도 먹어버릴지 모르니까.', `MaleText_loc4`='奴隶，离卡塔克远点。他可能会一口吃掉你。', `MaleText_loc5`='離卡爾塔克的嘴巴遠一點，奴隸傢伙。他可能也會把你給吃了。', `MaleText_loc7`='Aléjate de la boca de Kartak, cosa esclava. Puede que te coma a ti también.' WHERE `ID`=27979;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오래전에 카르탁은 산에서 내려와 광란심장 일족에게 왔다. 라크자크는 카르탁에게 날름이 노예들을 먹였고 이제 카르탁은 광란심장 일족은 안 먹는다.', `MaleText_loc4`='很久很久以前，卡塔克翻越群山来到狂心氏族的领地。那时候，拉克亚克用大舌头怪奴隶来喂他，所以现在卡塔克不会找狂心狼獾人的麻烦。', `MaleText_loc5`='很久以前，卡爾塔克從山上來到狂心部族。拉克杰克拿大舌頭奴隸餵卡爾塔克，所以卡爾塔克不吃狂心部族。', `MaleText_loc7`='Hace mucho, Kartak venir a Corazón Frenético desde montañas. Rakjak dar de comer esclavos lenguas-grandes a Kartak, así que ahora Kartak no comer Corazón Frenético.' WHERE `ID`=27980;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='광란심장 일족이 카르탁에게 날름이들을 먹이로 주었기 때문에 카르탁이 우리를 먹지 않는다. 그래서 우리가 너희보다 똑똑하다는 거다, 노예.', `MaleText_loc4`='狂心狼獾人用大舌头怪喂养卡塔克，保证自己不会沦为他的食物。奴隶，这就是我们比你聪明的证据。', `MaleText_loc5`='狂心餵卡爾塔克大舌頭，卡爾塔克不吃我們。這是為什麼我們比較聰明的理由，奴隸傢伙。', `MaleText_loc7`='Corazón Frenético dan de comer lenguas-grandes a Kartak para que Kartak no comer a nosotros. Por eso nosotros más listos que tú, cosa esclava.' WHERE `ID`=27981;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='광란심장 일족이 너까지 카르탁에게 먹일지도 모르지, 노예.', `MaleText_loc4`='或许狂心氏族该把你送去喂卡塔克，奴隶。', `MaleText_loc5`='或許狂心應該要拿你餵卡爾塔克，奴隸傢伙。', `MaleText_loc7`='Quizá Corazón Frenético deber darte de comer a Kartak, cosa esclava.' WHERE `ID`=27982;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='광란심장 일족이 제일 강하다!', `MaleText_loc4`='狂心狼獾人最厉害！', `MaleText_loc5`='狂心是最強的!', `MaleText_loc7`='¡Corazón Frenético los más fuertes!' WHERE `ID`=27983;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='집에 왔군! 고어게크가 먹을 고기를 가져 와라, 노예.', `MaleText_loc4`='到家啦！奴隶，你最好为格利基克带回了足够的肉。', `MaleText_loc5`='回家!你最好有替苟瑞格克帶肉回來，奴隸。', `MaleText_loc7`='¡Casa! Será mejor que traigas carne para Goregek, escoria.' WHERE `ID`=27984;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고어게크 술 마실 거다. 고어게크가 준비될 때까지 구석에 처박혀 있어라.', `MaleText_loc4`='格利基克去搞点酒喝。你乖乖地待在角落里等我。', `MaleText_loc5`='苟瑞格克去喝一杯。你坐在那邊等到苟瑞格克準備好。', `MaleText_loc7`='Goregek ir a por bebida. Tú sentar en rincón hasta que Goregek listo.' WHERE `ID`=27985;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고어게크 배고프다. 모닥불 위에 올라가라, 노예. 다 구워지면 말해라.', `MaleText_loc4`='格利基克饿死了。奴隶，快趴到火堆上去。等你烤熟之后告诉格利基克一声。', `MaleText_loc5`='苟瑞格克餓了。去生火，奴隸傢伙。等你烤好了再叫苟瑞格克。', `MaleText_loc7`='Goregek hambriento. Colocarte en foso de fuego, cosa esclava. Avisar a Goregek cuando estés bien asado.' WHERE `ID`=27986;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고어게크 준비될 때까지 기다려라.', `MaleText_loc4`='你最好耐心地等着格利基克。', `MaleText_loc5`='你要等到苟瑞格克準備好了。', `MaleText_loc7`='Espera hasta que Goregek esté preparado.' WHERE `ID`=27987;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고어게크 자러 간다. 먹을 거 구해 놔라, 노예.', `MaleText_loc4`='格利基克要去睡一会儿。奴隶，你去给我搞点吃的回来。', `MaleText_loc5`='苟瑞格克要睡一下。去找吃的東西回來，奴隸傢伙。', `MaleText_loc7`='Goregek dormir un poco. Traer cosas de comida de vuelta, cosa esclava.' WHERE `ID`=27988;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 고어게크는 바위돌기고릴라를 수백 번이나 상대했다.', `MaleText_loc4`='格利基克的主要工作之一就是猎捕硬皮猩猩。', `MaleText_loc5`='些硬拳擋在苟瑞格克面前好幾百次了。', `MaleText_loc7`='Antes de Goregek había cientos de estos callonudillos.' WHERE `ID`=27990;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바위돌기고릴라는 아직도 네 발로 기어다닌다... 고어게크 생각엔 좀 바보 같다.', `MaleText_loc4`='猎杀硬皮猩猩对格利基克来说容易极了……它们很愚蠢的。', `MaleText_loc5`='硬拳還四腳著地走路...苟瑞格克覺得他們有點蠢。', `MaleText_loc7`='Callonudillos todavía caminar con las manos... Parecer un poco tonto a Goregek.' WHERE `ID`=27991;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구경이나 해라, 노예. 고어게크가 바위돌기고릴라 다 해치운다!', `MaleText_loc4`='奴隶，你待在一旁看着就是了。让格利基克来对付这些硬皮猩猩！', `MaleText_loc5`='你就看著，奴隸傢伙。苟瑞格克對付這些硬拳!', `MaleText_loc7`='¡Tú solo mirar, cosa esclava. Goregek ocuparse de estos callonudillos!' WHERE `ID`=27992;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고어게크 가는 길을 막지 않는 게 좋을 거다!', `MaleText_loc4`='别挡格利基克的道！', `MaleText_loc5`='最好不要檔著苟瑞格克!', `MaleText_loc7`='¡Mejor no interponerse en el camino de Goregek!' WHERE `ID`=27993;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자기가 자기를 때리다니! 하하! 정말 바보다, 노예.', `MaleText_loc4`='吃到苦头了吧！哈哈！你这蠢奴隶。', `MaleText_loc5`='你害你自己被戳了!哈!你真蠢，奴隸傢伙。', `MaleText_loc7`='¡Te acabas de pegar tú sola, cosa esclava! ¡Ja! ¡Tú cosa esclava muy tonta!' WHERE `ID`=27994;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심해라, 노예. 커다랗고 나쁜 비단돌기고릴라가 널 먹어치울지도 모른다! 하하!', `MaleText_loc4`='当心点，坏心肠的软皮猩猩能一口吃掉你！哈哈！', `MaleText_loc5`='小心點，奴隸傢伙，又大又壞的鬃松可能會吃了你!哈哈!', `MaleText_loc7`='¡Cuidado cosa esclava, los grandes bebés con púas malos podrían comerte! ¡Ja!' WHERE `ID`=27995;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='역겨운 날름이들 같으니! 여기서 뭐 하는 거지?!', `MaleText_loc4`='恶心的大舌头怪！它在这里干什么？！', `MaleText_loc5`='噁心的大舌頭傢伙!它在這裡做什麼?!', `MaleText_loc7`='¡Asquerosa cosa lengua-grande! ¿Qué hacer aquí?' WHERE `ID`=28002;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날름이를 처치해라, 노예!', `MaleText_loc4`='奴隶，杀死大舌头怪！', `MaleText_loc5`='殺死大舌頭，奴隸傢伙!', `MaleText_loc7`='¡Matar lengua-grande, cosa esclava!' WHERE `ID`=28003;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고어게크 말려라, 노예! 내가 날름이들을 마구 마구 때릴 거다! 고어게크 말리라고!', `MaleText_loc4`='奴隶，看好格利基克身后！我要好好地惩罚一下大舌头怪！要帮格利基克留神背后！', `MaleText_loc5`='把茍瑞格克拉開，奴隸傢伙!我要揍大舌頭壞蛋!把茍瑞格克拉開!', `MaleText_loc7`='¡Sujetar a Goregek, cosa esclava! ¡Yo patear culo a lengua-grande! ¡Sujetar a Goregek!' WHERE `ID`=28004;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='근처에서 날름이 냄새 난다.', `MaleText_loc4`='空气中散发着大舌头怪的臭味！', `MaleText_loc5`='大舌頭的臭味到處都是。', `MaleText_loc7`='Por aquí apesta a lengua-grande.' WHERE `ID`=28005;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 이것 봐라! 고어게크 날름이로 목걸이 만들 수 있겠다!', `MaleText_loc4`='啊！快看！格利基克可以将大舌头怪串起来做项链！', `MaleText_loc5`='喔!看!茍瑞格克可以扯開大舌頭的喉嚨!', `MaleText_loc7`='¡Oh! ¡Mira! ¡Goregek puede comenzar el collar de lengua-grande!' WHERE `ID`=28006;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음, 노예... 구운 날름이 맛은 어떨지 궁금하다.', `MaleText_loc4`='嘿，奴隶……不知道烧烤大舌头怪吃起来怎么样。', `MaleText_loc5`='嗯，奴隸傢伙...不知道烤大舌頭嘗起來是什麼味道。', `MaleText_loc7`='Mmm, cosa esclava... Me pregunto a qué saben los lenguas-grandes asados.' WHERE `ID`=28007;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; $n의 시체에 점유의 깃발을 꽂습니다.', `MaleText_loc4`='%s把一面强者的旗帜插在了$n的尸体上。', `MaleText_loc5`='%s在$n的屍體上插了一根所有權旗幟。', `MaleText_loc7`='%s coloca una bandera de potestad en el cadáver de $n.', `FemaleText_loc1`='%s|1이;가; $n의 시체에 점유의 깃발을 꽂습니다.', `FemaleText_loc4`='%s把一面强者的旗帜插在了$n的尸体上。', `FemaleText_loc5`='%s在$n的屍體上插了一根所有權旗幟。', `FemaleText_loc7`='%s coloca una bandera de potestad en el cadáver de $n.' WHERE `ID`=28008;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하! 고어게크가 잡았다!', `MaleText_loc4`='哈！是格利基克杀的！', `MaleText_loc5`='哈!苟瑞格克殺的!', `MaleText_loc7`='¡Ja! ¡La caza de Goregek!' WHERE `ID`=28009;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음에는 좀 도움이 돼 봐라, 노예. 고어게크가 죄다 처리하게 하지 말란 말이다.', `MaleText_loc4`='下次你也要帮忙啊，奴隶。不能把所有的活儿都丢给格利基克。', `MaleText_loc5`='你下次應該要幫忙，奴隸傢伙。不要讓苟瑞格克做所有的工作。', `MaleText_loc7`='Tú deber ayudar próxima vez, cosa esclava. No dejar todo el trabajo a Goregek.' WHERE `ID`=28010;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고어게크는 최고의 사냥꾼이다...', `MaleText_loc4`='格利基克是最好的猎人……永远是。', `MaleText_loc5`='苟瑞格克，最棒的獵人...永遠都是。', `MaleText_loc7`='Goregek mejor cazador... de todos los tiempos.' WHERE `ID`=28011;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='급소를 정확히 찔렀어! 고어게크 참 잘한다.', `MaleText_loc4`='一击必中！格利基克真厉害。', `MaleText_loc5`='我就戳在它的臉上!苟瑞格克真棒。', `MaleText_loc7`='¡Le he apuñalado en la cara! Goregek muy bueno.' WHERE `ID`=28012;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이놈은 고어게크 보지도 못했다.', `MaleText_loc4`='它甚至没有发现格利基克。', `MaleText_loc5`='它甚至沒看到苟瑞格克靠近。', `MaleText_loc7`='No esperarse a Goregek.' WHERE `ID`=28013;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싸움을 거들 거냐, 아니면 그냥 앉아 있을 거냐, 노예?', `MaleText_loc4`='你是要帮我一把呢，还是就坐在一旁偷懒？', `MaleText_loc5`='你要嘛幫忙戰鬥，不然就坐在那邊，懂嗎，奴隸傢伙?', `MaleText_loc7`='¿Tú ir a ayudar a luchar también o solo sentarte ahí, cosa esclava?' WHERE `ID`=28014;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고어게크 왜 네놈을 데려왔지. 아무짝에도 쓸모가 없는데.', `MaleText_loc4`='格利基克为什么要带上你啊。你这废物。', `MaleText_loc5`='為什麼苟瑞格克要帶著你。你這沒用的東西。', `MaleText_loc7`='Por qué Goregek traerte. Tú inútil.' WHERE `ID`=28015;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음번엔 고어게크가 너한테 시켜봐야겠다.', `MaleText_loc4`='下次格利基克让你试试。', `MaleText_loc5`='下次，或許苟瑞格克會讓你試試。', `MaleText_loc7`='Igual próxima vez, Goregek dejar que pruebes.' WHERE `ID`=28016;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스 경비탑이 파괴되었습니다!', `MaleText_loc4`='联盟哨塔被摧毁了！', `MaleText_loc5`='聯盟哨塔被摧毀了!', `MaleText_loc7`='¡La torre de la Alianza fue destruida!' WHERE `ID`=28017;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드 경비탑이 파괴되었습니다!', `MaleText_loc4`='部落哨塔被摧毁了！', `MaleText_loc5`='部落哨塔被摧毀了!', `MaleText_loc7`='¡La torre de la Horda fue destruida!' WHERE `ID`=28018;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리는 부정의 힘을 휘둘러 죽음 자체를 조종합니다!', `FemaleText_loc4`='凭借邪恶的力量，我们才能统御亡者！', `FemaleText_loc5`='透過穢邪之力，我們得以操控死亡!', `FemaleText_loc7`='¡El poder de los impíos nos permite mandar sobre la propia muerte!' WHERE `ID`=28019;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련을 받고 싶습니다, 알리스트라 님.', `MaleText_loc4`='奥莉丝塔夫人，我想接受训练。', `MaleText_loc5`='我想接受訓練，雅莉絲翠女士。', `MaleText_loc7`='Busco instrucción, Lady Alistra.', `FemaleText_loc1`='훈련을 받고 싶습니다, 알리스트라 님.', `FemaleText_loc4`='奥莉丝塔夫人，我想接受训练。', `FemaleText_loc5`='我想接受訓練，雅莉絲翠女士。', `FemaleText_loc7`='Busco instrucción, Lady Alistra.' WHERE `ID`=28020;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피는 생명이라오... 피의 흐름을 조종하는 데 익숙해질수록, 우리 적의 생명력 또한 쉽게 다룰 수 있지.', `MaleText_loc4`='鲜血就是生命……如果能随意掌控鲜血的奔涌，那么敌人的性命也就如同掌中玩物了。', `MaleText_loc5`='鮮血就是生命...操控鮮血的起伏是如此的簡單，一如玩弄敵人的生命。', `MaleText_loc7`='La sangre es vida... Y la vida de nuestros enemigos es tan fácil de controlar como el flujo y reflujo de la sangre.' WHERE `ID`=28021;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련을 받고 싶습니다, 토르발 경.', `MaleText_loc4`='索瓦尔勋爵，我想接受训练。', `MaleText_loc5`='我想接受訓練，索瓦爾領主。', `MaleText_loc7`='Busco instrucción, Lord Thorval.', `FemaleText_loc1`='훈련을 받고 싶습니다, 토르발 경.', `FemaleText_loc4`='索瓦尔勋爵，我想接受训练。', `FemaleText_loc5`='我想接受訓練，索瓦爾領主。', `FemaleText_loc7`='Busco instrucción, Lord Thorval.' WHERE `ID`=28022;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 차가운 바람에 실려 다니는 존재입니다. 절망의 차디찬 손길... 죽음의 차가운 포옹...', `MaleText_loc4`='凛冽的北风承载着我们散发出的不祥气息。我们就像绝望的寒冬……接受死亡的冰封之拥吧……', `MaleText_loc5`='我們伴著寒風降臨。冰霜般凜冽的絕望...死亡的冰冷擁抱...', `MaleText_loc7`='Nosotros somos lo que viaja en el frío viento. El gélido escalofrío de la desesperación... El helado abrazo de la muerte...' WHERE `ID`=28023;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련을 받고 싶습니다, 아말타자드.', `MaleText_loc4`='阿曼萨加德，我想接受训练。', `MaleText_loc5`='我想接受訓練，艾默薩札德。', `MaleText_loc7`='Busco instrucción, Amal''thazad.', `FemaleText_loc1`='훈련을 받고 싶습니다, 아말타자드.', `FemaleText_loc4`='阿曼萨加德，我想接受训练。', `FemaleText_loc5`='我想接受訓練，艾默薩札德。', `FemaleText_loc7`='Busco instrucción, Amal''thazad.' WHERE `ID`=28024;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='육신을 벗어나 유령 상태가 되었습니다!', `MaleText_loc4`='将你的肉体抛诸脑后吧！', `MaleText_loc5`='棄絕你的實質肉體!', `MaleText_loc7`='¡Dejas tu cuerpo material atrás!', `FemaleText_loc1`='육신을 벗어나 유령 상태가 되었습니다!', `FemaleText_loc4`='将你的肉体抛诸脑后吧！', `FemaleText_loc5`='棄絕你的實質肉體!', `FemaleText_loc7`='¡Dejas tu cuerpo material atrás!' WHERE `ID`=28025;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자넨 끝내주는 구경거리를 놓쳤다네, 도리안! 수십 년에 한 번 볼까 말까 한 광경이었는데!', `MaleText_loc4`='多里安，你错过了一场惊心动魄的战斗！真是难忘的经历啊！', `MaleText_loc5`='你錯過了一場大戰，多里安!百年難得一見啊!', `MaleText_loc7`='¡Qué pelea te has perdido, Dorian! ¡La mejor desde hace mucho!' WHERE `ID`=28026;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 쿵쿵이 등에 타고 전속력으로 놈을 향해 달려갔지...', `MaleText_loc4`='我们骑在斯塔比背上，全速开战……', `MaleText_loc5`='我們那時在那兒，騎在史坦皮的背上全速衝進戰場...', `MaleText_loc7`='Allí estábamos, cabalgando hacia la batalla a toda velocidad a lomos de Estampi...' WHERE `ID`=28027;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사방 천지가 흔들리고 있었소. 총을 제대로 겨눌 수조차 없었지.', `MaleText_loc4`='我感觉周围的景象在颤抖，差点抓不住手中的枪。', `MaleText_loc5`='每樣東西都在拼命晃動，我差點握不住我的槍。', `MaleText_loc7`='Todo temblaba en aquel lugar. Casi no podía estabilizar mi pistola.' WHERE `ID`=28028;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 놈을 본 거야. 그 끔찍한 짐승을!', `MaleText_loc4`='接着，那只恐怖的野兽进入了我们的视线！', `MaleText_loc5`='接著我們看到她，令人驚駭的野獸!', `MaleText_loc7`='¡Y entonces vimos a la temible bestia!' WHERE `ID`=28029;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 가진 기술을 모두 동원해야 겨우 쿵쿵이를 다룰 수 있었지.', `MaleText_loc4`='$n全神贯注地控制斯塔比战斗。', `MaleText_loc5`='全靠$n的技術才能維持駕馭著史坦皮。', `MaleText_loc7`='$n tuvo que usar toda su habilidad para controlar a Estampi.' WHERE `ID`=28030;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드라카리들이 자신들을 이렇게 파괴하는 걸 보면 안타까울 따름이네.$B$B이 땅에 깃든 자연의 신을 죽여 얻은 힘은 일시적인 것에 불과하지.$B$B그렇게 짧은 시간에 얻은 것은 결국 영원히 사라지고 말 걸세.', `MaleText_loc4`='达卡莱帝国走上了自我毁灭的道路，我们为此感到悲哀。$B$B他们通过弑神夺来的力量只能维持一段很短的时间。$B$B这短暂的收益将葬送达卡莱帝国的未来。', `MaleText_loc5`='突然間我們全都看見德拉克瑞用這種方式毀滅自己。$B$B他們殺死這片土地的自然諸神時所獲得的力量是短暫的。$B$B他們的短暫獲得，將永遠不復得。', `MaleText_loc7`='A todos nos apena ver a los Drakkari destruyéndose a sí mismos de esta forma.$B$BEl poder que obtienen matando a los dioses naturales del territorio es transitorio.$B$BLo que ganen a corto plazo lo perderán para toda la eternidad.' WHERE `ID`=28031;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피와 총알과 땀이 뒤범벅된 싸움이었지. 여왕은 점점 더 빠르게 공격해왔어!', `MaleText_loc4`='这场战斗真是腥风血雨啊。母龙的攻击速度越来越快了！', `MaleText_loc5`='戰鬥是一片的血霧，重要而甜美。而育母的攻擊越來越快!', `MaleText_loc7`='La batalla fue una nube de sangre, plomo y sudor. ¡Los ataques de la madre de linaje se volvieron más y más rápidos!' WHERE `ID`=28032;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만, 결국 $n|1과;와; 나는 지혜와 협동심으로 놈을 해치웠지. 그리고 이제 우리에게는 승리했다는 기념으로 이 영광스러운 전리품이 남았다네.', `MaleText_loc4`='但是，我，还有$n凭借卓越的智慧和完美的合作，最终取得了胜利。喏，这就是我们的战利品。', `MaleText_loc5`='但最後，$n和我靠著我們的機智與團隊合作而獲勝。於是現在我們才有如此光輝的戰利品，以紀念我們的勝利。', `MaleText_loc7`='Pero, al final, $n y yo prevalecimos gracias a nuestro ingenio y trabajo en equipo. Y ahora tenemos este glorioso trofeo como recuerdo de nuestra victoria.' WHERE `ID`=28033;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이래 봤자... 아무 소용없다.', `MaleText_loc4`='这一切……都是毫无意义的。', `MaleText_loc5`='你的努力...全是白費。', `MaleText_loc7`='Sus esfuerzos... son en vano.' WHERE `ID`=28034;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕께 맞서는 자는 이런 운명을 맞게 되지!', `MaleText_loc4`='这就是反抗巫妖王的下场！', `MaleText_loc5`='這就是反抗巫妖王的下場!', `MaleText_loc7`='¡Ese es el destino de todo aquel que se opone al Rey Exánime!' WHERE `ID`=28035;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좀 부러워하는 것 같은데, 도리안?', `MaleText_loc4`='多里安，怎么你看上去有点嫉妒啊？', `MaleText_loc5`='我是不是感覺到一點嫉妒，多里安?', `MaleText_loc7`='¿Detecto celos, Dorian?' WHERE `ID`=28036;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='글쎄요, 모르겠습니다. 전 여기서 모닥불을 지키면서 주트피즐과 톱니바퀴 고장에 대해 얘기를 나눴지요. 그것도 나름대로 아주 근사한 일이랍니다.', `MaleText_loc4`='呃，才没有。我是来照料篝火堆的，顺便找苏特菲兹谈谈机械零件的缺陷问题。我承认，这件战利品看上去是挺不错的。', `MaleText_loc5`='嗯，我不知道。我那時候在看火並且和狹嘶討論榫的缺點。那真的很經典，嗯，在它那方面啦。', `MaleText_loc7`='Bueno, no sé. Yo estaba ocupándome del fuego y hablando sobre los inconvenientes de los piñones con Zootsilbo. Eso también es bastante épico, a su manera.' WHERE `ID`=28037;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 정신 차려라, 우리는 계속 나아가야 한다.', `MaleText_loc4`='集中精神，我们必须继续前进。', `MaleText_loc5`='快點集中你的注意力，我們一定要加把勁。', `MaleText_loc7`='Recupérate deprisa, debemos seguir adelante.' WHERE `ID`=28038;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비됐습니다.', `MaleText_loc4`='我准备好了。', `MaleText_loc5`='我準備好了。', `MaleText_loc7`='Estoy preparado', `FemaleText_loc1`='준비됐어요.', `FemaleText_loc4`='我准备好了。', `FemaleText_loc5`='我準備好了。', `FemaleText_loc7`='Estoy preparada.' WHERE `ID`=28039;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오래 걸리진 않을 것이다.', `MaleText_loc4`='这只需要一小会儿。', `MaleText_loc5`='這只會花上一點點時間。', `MaleText_loc7`='Esto sólo tomará un instante.' WHERE `ID`=28040;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비밀 통로가 남아 있어 다행이군.', `MaleText_loc4`='我确信这条秘道还通着。', `MaleText_loc5`='這個秘密通道還能用真教我鬆了一口氣。', `MaleText_loc7`='Qué alivio que este pasadizo secreto aún sirva.' WHERE `ID`=28041;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쉽게 끝나지는 않을 것 같군. 스트라솔름이 불타고 있다. 말가니스와 마주하려면 불길과 스컬지를 뚫어야만 해. 준비해라.', `MaleText_loc4`='局势严峻。斯坦索姆正在燃烧。我们必须穿越着火带，击杀沿途的天灾军团，设法抵达玛尔加尼斯所在的十字军广场。做好准备吧。', `MaleText_loc5`='情況並沒有簡單多少。斯坦索姆正在燃燒。我們必須要面對天譴軍團與火焰才能靠近瑪爾加尼斯。做好準備。', `MaleText_loc7`='Esto no se está volviendo más fácil. Stratholme está ardiendo. Debemos enfrentarnos a la Plaga y a las llamas para llegar hasta Mal''Ganis. Preparaos.' WHERE `ID`=28043;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로데론을 위하여!', `MaleText_loc4`='为洛丹伦而战！', `MaleText_loc5`='為了羅德隆!', `MaleText_loc7`='¡Por Lordaeron!', `FemaleText_loc1`='로데론을 위하여!', `FemaleText_loc4`='为洛丹伦而战！', `FemaleText_loc5`='為了羅德隆!', `FemaleText_loc7`='¡Por Lordaeron!' WHERE `ID`=28044;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠시 쉬며 숨을 돌려라. 하지만 곧 이동해야 한다.', `MaleText_loc4`='休息一会，你们抓紧时间喘口气，我们马上就得重新上路。', `MaleText_loc5`='休息一會，你們抓緊時間喘口氣，我們馬上就得重新上路。', `MaleText_loc7`='Descansen un momento y recupérense, pero debemos continuar enseguida.' WHERE `ID`=28045;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리는 어느 정도 짐토르가에서 보호받을 수 있지만, 스컬지가 있고 드라카리는 각종 만행을 저지르기 때문에 크게 약해졌네.$B$B이제 나와 아훈네가 그 몫을 해내야만 하지.', `FemaleText_loc4`='希姆托加倒是能为我们提供一定的保护，但是天灾军团的势力不断扩张，再加上达卡莱帝国的弑神举动，她的力量已经被严重削弱了。$B$B因此防御的重任就落在我和埃霍奈的肩上了。', `FemaleText_loc5`='辛托加可以提供我們某些程度的保護，但是因為天譴軍的出現與德拉克瑞的行動，辛托加已經被大幅弱化了。$B$B剩餘的防禦行動就落到我和艾胡奈的肩膀上了。', `FemaleText_loc7`='Zim''Torga puede proporcionarnos cierto nivel de protección, pero la presencia de la Plaga y las acciones de los Drakkari la han debilitado mucho.$B$BAhunae y yo nos ocuparemos del resto de nuestras defensas.' WHERE `ID`=28046;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만! 이제 움직이자. 말가니스가 기다리고 있다.', `MaleText_loc4`='就这样吧，我们必须继续上路了。玛尔加尼斯在等着我们呢。', `MaleText_loc5`='休息夠了，我們得動身了，瑪爾加尼斯在等著我們。', `MaleText_loc7`='Suficiente, debemos seguir adelante. Mal''Ganis espera.' WHERE `ID`=28047;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그나마 낫군. 상가에는 아직 불길이 번지지 않았다. 말가니스는 저 너머 십자군 광장에 있을 것이다. 이동할 준비가 되면 내게 보고해라.', `MaleText_loc4`='圣光在上。市场小径还没有着火。玛尔加尼斯应该就躲藏在前面的十字军广场。你们准备好继续前进的话，就告诉我。', `MaleText_loc5`='運氣不錯。市場區尚未起火。瑪爾加尼斯應該就在前方的十字軍廣場。準備好要繼續行動的話就告訴我。', `MaleText_loc7`='Por fin la suerte nos acompaña. La Fila del Mercado aún no se ha incendiado. Mal''Ganis debe estar en la Plaza de los Cruzados aquí adelante. Avísenme cuando puedan continuar.' WHERE `ID`=28048;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 가라, 벗이여. 고맙다.', `FemaleText_loc4`='走吧，朋友。谢谢你。', `FemaleText_loc5`='快走，我的朋友，謝謝你。', `FemaleText_loc7`='Ahora márchate. Gracias.' WHERE `ID`=28049;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='짐토르가를 지켜내고, 드라카리들이 그 힘을 빼앗지 못하게 막아야 하네.', `FemaleText_loc4`='必须保护希姆托加，不能让那些愚蠢的达卡莱巨魔偷走她的力量。', `FemaleText_loc5`='必須死守辛托加，以免德拉克瑞又愚蠢的把辛托加的力量偷走。', `FemaleText_loc7`='También hay que defender Zim''Torga para evitar que los necios Drakkari roben su poder.' WHERE `ID`=28050;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그대는 대지에서 일어났도다. 그러니 대지로 돌아가리라.', `FemaleText_loc4`='你从大地中来，就该回到大地中去。', `FemaleText_loc5`='你從大地生，你回歸大地。', `FemaleText_loc7`='De la tierra viniste y a la tierra volverás.' WHERE `ID`=28051;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자네가 희생한 덕택에 우리는 명예를 지켰네.', `FemaleText_loc4`='你甘愿奉献生命，我们以你为荣。', `FemaleText_loc5`='你的犧牲讓我們感到榮幸。', `FemaleText_loc7`='Tu sacrificio nos honra.' WHERE `ID`=28052;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='덫으로 몰아넣으시오!', `MaleText_loc4`='诱使它踩进陷阱！', `MaleText_loc5`='引誘它掉進陷阱!', `MaleText_loc7`='¡Haz que entre en la trampa!' WHERE `ID`=28053;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='드라카리들이 방어를 뚫게 놔둬서는 안 되네.', `FemaleText_loc4`='绝不能让达卡莱巨魔突破防御线。', `FemaleText_loc5`='絕對不能讓德拉克瑞攻破防線。', `FemaleText_loc7`='Los Drakkari no deben atravesar nuestras defensas.' WHERE `ID`=28054;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내가 할 수 있는 최대한으로 그대를 강하게 만들었도다. 잘 싸우고 오너라, 나의 벗인 대지 정령이여.', `FemaleText_loc4`='这是我能赋予你的全部力量了。全力战斗吧，我的地灵朋友。', `FemaleText_loc5`='這和我所能做的一樣強大。奮戰吧，我的地族朋友。', `FemaleText_loc7`='Esto es lo máximo que te puedo fortalecer. Lucha bien, camarada terrestre.' WHERE `ID`=28055;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비켜라, 멍청한 노예같으니! 고어게크가 잡을 거다!', `MaleText_loc4`='愚蠢的奴隶，别挡道！这是格利基克的猎物！', `MaleText_loc5`='別擋路，笨奴隸傢伙!茍瑞格克要大開殺戒!', `MaleText_loc7`='¡Apartar de camino estúpida cosa esclava! ¡Goregek matar!' WHERE `ID`=28056;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아하! 고어게크는 최고 사냥꾼이다! 제일 큰 바위돌기고릴라 고어게크가 잡았다!!', `MaleText_loc4`='哈哈！格利基克是最最厉害的猎手！格利基克杀死了个头最大的硬皮猩猩！', `MaleText_loc5`='哈!茍瑞格克天下第一獵手!茍瑞格克抓到最大一隻的硬拳!', `MaleText_loc7`='¡Ja! ¡Goregek mejor cazador que haber! ¡Goregek cazar al callonudillo más grande!' WHERE `ID`=28057;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇게 하는 거다, 노예. 언젠가는 너도 알게 될 거다.', `MaleText_loc4`='奴隶，看清楚了吧。或许有一天你也能领悟这一招。', `MaleText_loc5`='事情就是這樣啦，奴隸傢伙。也許哪天你會搞懂也說不定。', `MaleText_loc7`='Así se hace, cosa esclava. Igual tú descubrirlo algún día.' WHERE `ID`=28058;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='복수는 고어게크가 한다! 멍청한 바위돌기고릴라한테 뒤에서 고어게크 공격하라고 가르쳐줘라.', `MaleText_loc4`='来找格利基克报仇啊！让那些愚蠢的硬皮猩猩从背后攻击我啊。', `MaleText_loc5`='復仇是茍瑞格克的事情!教教你們愚笨的硬拳，想要擊敗我最好從後面來。', `MaleText_loc7`='¡La venganza es de Goregek! Enseñar a tonto callonudillo a derribar a Goregek desde detrás.' WHERE `ID`=28059;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='식사 시간이다!', `MaleText_loc4`='吃饭时?！', `MaleText_loc5`='放飯囉!', `MaleText_loc7`='¡Hora de comer!' WHERE `ID`=28060;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고어게크 배고프다.', `MaleText_loc4`='格利基克饿了。', `MaleText_loc5`='茍瑞格克餓了。', `MaleText_loc7`='Goregek hambriento.' WHERE `ID`=28061;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기다려라, 노예. 고어게크 식사 중이다.', `MaleText_loc4`='你一边呆着去，奴隶。格利基克正在吃饭呢。', `MaleText_loc5`='你等著，奴隸傢伙，然後茍瑞格克吃。', `MaleText_loc7`='Tú esperar, cosa esclava. Goregek estar comiendo.' WHERE `ID`=28062;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고어게크가 먹는 동안 가서 고릴라 좀 더 잡아라.', `MaleText_loc4`='趁格利基克吃饭的时候，你去多杀些猎物吧。', `MaleText_loc5`='茍瑞格克吃的時候，去多殺一點。', `MaleText_loc7`='Ir a matar más cosas mientras Goregek comer.' WHERE `ID`=28063;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='닭이군! 맛난 놈들이다!', `MaleText_loc4`='鸡！好吃！', `MaleText_loc5`='雞!好吃!', `MaleText_loc7`='¡Pollo! ¡Tan delicioso!' WHERE `ID`=28064;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고어게크가 닭 전부 잡을 거다!', `MaleText_loc4`='格利基克要去抓鸡！', `MaleText_loc5`='茍瑞格克會好好抓雞的!', `MaleText_loc7`='¡Goregek ir a atrapar pollos bien!' WHERE `ID`=28065;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노예! 가서 닭을 잡아 와라!', `MaleText_loc4`='奴隶！快来帮格利基克抓鸡啊！', `MaleText_loc5`='奴隸傢伙!給茍瑞格克把雞抓來!', `MaleText_loc7`='¡Cosa esclava! ¡Ve a por pollo para Goregek!' WHERE `ID`=28066;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='걱정 마라. 고어게크 너 불에 넣지 않는다. 고어게크는 착한 울바르다.', `MaleText_loc4`='别害怕呀。格利基克不会把你丢进火里烤的。格利基克是个好心肠的狼獾人。', `MaleText_loc5`='雞啊雞，別擔心，茍瑞格克不會把你丟進火裡的，茍瑞格克是好心的獾狼怪。', `MaleText_loc7`='No preocupar, pollo. Goregek no ir a ponerte en fuego. Goregek buen wolvar.' WHERE `ID`=28067;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끼익! 깨액! 끝내주는군!', `MaleText_loc4`='它们可真灵活！', `MaleText_loc5`='尖叫吧!尖叫吧!太好了!', `MaleText_loc7`='¡Chillido! ¡Chillido! ¡Qué bien!' WHERE `ID`=28068;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도망가라, 비단돌기고릴라들아! 고어게크가 잡으러 나가신다!', `MaleText_loc4`='快跑呀，软皮猩猩！格利基克来抓你们啦！', `MaleText_loc5`='快跑喔鬃松寶寶!茍瑞格克要來抓你們哩!', `MaleText_loc7`='¡Huir badanudillos! ¡Goregek ir a por ti!' WHERE `ID`=28069;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아우우! 무섭기도 하지!', `MaleText_loc4`='啊！吓坏了吧！', `MaleText_loc5`='哎喲!好怕喔!', `MaleText_loc7`='¡Oooh! ¡Tan aterrorizado!' WHERE `ID`=28070;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도망쳐라, 멍청한 비단돌기고릴라야! 꼬챙이로 푹푹 찔러버릴 거다!', `MaleText_loc4`='软皮猩猩是我们重要的生活来源。', `MaleText_loc5`='快跑呀，鬃松寶寶小呆瓜!我們要來找你們玩囉!', `MaleText_loc7`='¡Huye estúpido badanudillos! ¡Nosotros ir a pincharte más!' WHERE `ID`=28071;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아훈네의 도끼가 드라카리에 최후를 안겨줄 걸세.$B$B내 도끼를 피한 놈이 있다면 자네가 처리해주게!', `MaleText_loc4`='埃霍奈的斧头就是达卡莱巨魔的末日。$B$B即便有一些漏网之鱼从我的斧下逃脱，你也会干掉他们！', `MaleText_loc5`='艾胡奈的巨斧會解決那些德拉克瑞人。$B$B就算逃過我的斧頭，你也會料理他們!', `MaleText_loc7`='El hacha de Ahunae acabará con los Drakkari.$B$B¡Y tú te encargarás de todo lo que escape a mi hacha!' WHERE `ID`=28072;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 정도 높이면 괜찮겠군. 여왕을 발견하고 공격할 준비가 되면, 목표로 잡은 다음 내게 신호하시오.', `MaleText_loc4`='这个位置似乎不错。锁定目标，当你发现母龙后，迅速做好准备，然后向我发出信号。', `MaleText_loc5`='這看來是個不錯的棲身之所。當你看見育母而準備攻擊前，標記目標並且用訊號通知我。', `MaleText_loc7`='Esta parece una buena percha. Marca el objetivo y hazme una señal cuando hayas visto a la madre de linaje y estés $glisto:lista; para atacar.' WHERE `ID`=28073;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이쪽이다, 짐승아! 헤멧에게 덤벼 봐라!', `MaleText_loc4`='来吧，野兽！来跟赫米特玩玩！', `MaleText_loc5`='這兒，野獸。來赫米特這!', `MaleText_loc7`='Aquí, bestia. ¡Ven con Hemet!' WHERE `ID`=28074;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='받아라, 짐승아!', `MaleText_loc4`='尝尝厉害吧，野兽！', `MaleText_loc5`='接招吧，野獸!', `MaleText_loc7`='¡Toma eso, bestia!' WHERE `ID`=28075;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맛이 어떠냐, 이놈아?', `MaleText_loc4`='这招怎么样啊，嗯？', `MaleText_loc5`='這一招怎麼樣啊，嗯?', `MaleText_loc7`='¿Qué te ha parecido eso? ¿Eh?' WHERE `ID`=28076;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='총알을 먹여 주마!', `MaleText_loc4`='看枪！', `MaleText_loc5`='吃鉛彈吧!', `MaleText_loc7`='¡Toma plomo!' WHERE `ID`=28077;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='큰 놈일수록 잡기가 어려운 법.', `MaleText_loc4`='它们的体型越大，摔得就越惨。', `MaleText_loc5`='體型越大，摔得越重。', `MaleText_loc7`='Cuánto más grandes son, más ruido hacen al caer.' WHERE `ID`=28078;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='교활한 마법사 군주 우롬이 세 번째 고리를 보호하고 있습니다. 놈은 무방비 상태로 혼자 있는 것처럼 보이지만, 겉모습에 속아서는 안 됩니다! 우롬은 실체 없는 생물 군단을 지휘하는 강력한 요술사입니다. 위쪽에서 그를 찾아보십시오.', `MaleText_loc4`='狡猾的法师领主伊洛姆守护着第三道环。表面上他显得孤立无援，但那不过是欺骗敌人的假象！伊洛姆是位强大的咒术师，能召唤各种幽灵生物为他作战。去上面找他吧。', `MaleText_loc5`='欺詐者法師領主厄隆保護著第三道環。他看起來單獨一人並且毫無戒備，但是別被他的外貌給欺騙了!厄隆是位強大的咒術師，控制一整群的幻魅生物。到上面把他找出來。', `MaleText_loc7`='El tramposo Señor de la magia Urom protege el tercer anillo. Aparecerá solo e indefenso, ¡pero que no te engañen las apariencias! Urom es un poderoso conjurador que dirige un grupo de criaturas fantasmales. Búscale arriba.' WHERE `ID`=28079;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='교활한 마법사 군주 우롬이 세 번째 고리를 보호하고 있습니다. 놈은 무방비 상태로 홀로 있는 것처럼 보이지만, 겉모습에 속아서는 안 됩니다! 우롬은 실체 없는 생물 군단을 지휘하는 강력한 요술사입니다. 위쪽에서 그를 찾아보십시오. 난 그대에게 붉은용군단 비룡을 소환할 수 있는 능력을 줄 수 있습니다. 청동용군단이나 녹색용군단의 힘을 빌리고 싶다면 이터노스나 베르디사와 이야기하십시오.', `MaleText_loc4`='狡猾的法师领主伊洛姆守护着第三道环。表面上他显得孤立无援，但那不过是欺骗敌人的假象！伊洛姆是位强大的咒术师，能召唤各种幽灵生物为他作战。去上面找他吧。

我能赋予你召唤红玉幼龙协同作战的能力。当然，如果你希望借助青铜龙或是绿龙的力量，就去找伊特努斯或是沃尔蒂萨谈谈。', `MaleText_loc5`='欺詐者法師領主厄隆保護著第三道環。他看起來單獨一人並且毫無戒備，但是別被他的外貌給欺騙了!厄隆是位強大的咒術師，控制一整群的幻魅生物。在上面把他找出來。

我可以賦予你呼喚一頭紅龍軍團飛龍的力量。如果你屬意藉助青銅龍軍團或是綠龍的力量，請和伊特諾斯或薇爾迪莎談談。', `MaleText_loc7`='El tramposo Señor de la magia Urom protege el tercer anillo. Aparecerá solo e indefenso, ¡pero que no te engañen las apariencias! Urom es un poderoso conjurador que dirige un grupo de criaturas fantasmales. Búscale arriba.
Puedo otorgarte el poder de invocar a un draco del Vuelo Rojo. Habla con Eternos o con Verdisa si prefieres aprovechar el poder del Bronce o del Verde.' WHERE `ID`=28080;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엄청난 도전이 눈앞에 닥쳐왔습니다. 지맥 수호자 에레고스는 막대한 힘을 가진 푸른용입니다. 가장 높이 있는 고리 위를 보면 그가 날아다니고 있을 겁니다. 그대의 비룡은 이제 최고의 힘을 사용할 수 있습니다. 그 힘을 사용해 에레고스를 격파하십시오!', `MaleText_loc4`='你即将面临迄今为止最大的挑战。魔网守护者埃雷苟斯，这只蓝龙拥有超乎想象的可怕力量。埃雷苟斯在魔枢的最高环飞翔。

现在，幼龙的终极力量已经解封。利用它们的力量击败埃雷苟斯吧！', `MaleText_loc5`='你的最大挑戰正等著你。地脈守護者伊瑞茍斯是一頭力大無窮的藍龍。你會在最上環的上方飛行遇到牠。

你的飛龍力量已全部開啟，利用他們的能力擊敗伊瑞茍斯!', `MaleText_loc7`='El mayor de tus desafíos aún está por llegar. El Guardián-Ley Eregos es un dragón Azul de inmenso poder. Lo encontrarás sobrevolando el anillo superior.

Se ha desbloqueado el poder total de tus dracos. ¡Usa su poder para derrotar a Eregos!' WHERE `ID`=28081;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대가 마력의 눈을 말리고스의 세력으로부터 빼앗으셨군요. 붉은용군단에서 그대에게 큰 빚을 졌습니다.', `MaleText_loc4`='你从玛里苟斯的部队手中夺得了魔环的控制权。红龙军团欠你一个人情。', `MaleText_loc5`='你從瑪里苟斯軍隊的手上奪走了奧核之眼的控制權。紅龍軍團欠你一次人情。', `MaleText_loc7`='Has arrebatado el control del Oculus a las fuerzas de Malygos. El Vuelo Rojo está en deuda contigo.' WHERE `ID`=28082;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='청동용군단이 빚을 잔뜩 져버렸네요.', `MaleText_loc4`='青铜龙军团欠你一个人情。', `MaleText_loc5`='青銅龍軍團欠你一份人情。', `MaleText_loc7`='El Vuelo Bronce está en deuda contigo.' WHERE `ID`=28083;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='녹색용군단이 그대에게 빚을 졌군요.', `FemaleText_loc4`='绿龙军团欠你一个人情。', `FemaleText_loc5`='綠龍軍團欠你一份人情。', `FemaleText_loc7`='El Vuelo Verde está en deuda contigo.' WHERE `ID`=28084;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='루비 비룡이 가진 능력은 무엇입니까?', `MaleText_loc4`='红玉幼龙有什么能力？', `MaleText_loc5`='晶紅龍有什麼能力?', `MaleText_loc7`='¿Qué habilidades poseen los dracos rubí?', `FemaleText_loc1`='루비 비룡이 가진 능력은 무엇인가요?', `FemaleText_loc4`='红玉幼龙有什么能力？', `FemaleText_loc5`='晶紅龍有什麼能力?', `FemaleText_loc7`='¿Qué habilidades poseen los dracos rubí?' WHERE `ID`=28085;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호박색 비룡이 가진 능력은 무엇입니까?', `MaleText_loc4`='琥珀幼龙有什么能力？', `MaleText_loc5`='琥珀龍有什麼能力?', `MaleText_loc7`='¿Qué habilidades poseen los dracos ámbar?', `FemaleText_loc1`='호박색 비룡이 가진 능력은 무엇인가요?', `FemaleText_loc4`='琥珀幼龙有什么能力？', `FemaleText_loc5`='琥珀龍有什麼能力?', `FemaleText_loc7`='¿Qué habilidades poseen los dracos ámbar?' WHERE `ID`=28086;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에메랄드 비룡이 가진 능력은 무엇입니까?', `MaleText_loc4`='翡翠幼龙有什么能力？', `MaleText_loc5`='翡翠龍有什麼能力?', `MaleText_loc7`='¿Qué habilidades poseen los dracos esmeralda?', `FemaleText_loc1`='에메랄드 비룡이 가진 능력은 무엇인가요?', `FemaleText_loc4`='翡翠幼龙有什么能力？', `FemaleText_loc5`='翡翠龍有什麼能力?', `FemaleText_loc7`='¿Qué habilidades poseen los dracos esmeralda?' WHERE `ID`=28087;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='루비 비룡이 지닌 궁극적으로 지닌 능력은 무엇입니까?', `MaleText_loc4`='红玉幼龙的终极技能是什么？', `MaleText_loc5`='晶紅龍的究極能力是什麼?', `MaleText_loc7`='¿Cuál es la habilidad definitiva del draco rubí?', `FemaleText_loc1`='루비 비룡이 지닌 궁극적으로 지닌 능력은 무엇인가요?', `FemaleText_loc4`='红玉幼龙的终极技能是什么？', `FemaleText_loc5`='晶紅龍的究極能力是什麼?', `FemaleText_loc7`='¿Cuál es la habilidad definitiva del draco rubí?' WHERE `ID`=28088;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호박색 비룡이 궁극적으로 지닌 능력은 무엇입니까?', `MaleText_loc4`='琥珀幼龙的终极技能是什么？', `MaleText_loc5`='琥珀龍的究極能力是什麼?', `MaleText_loc7`='¿Cuál es la habilidad definitiva del draco ámbar?', `FemaleText_loc1`='호박색 비룡이 궁극적으로 지닌 능력은 무엇인가요?', `FemaleText_loc4`='琥珀幼龙的终极技能是什么？', `FemaleText_loc5`='琥珀龍的究極能力是什麼?', `FemaleText_loc7`='¿Cuál es la habilidad definitiva del draco ámbar?' WHERE `ID`=28089;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에메랄드 비룡이 지닌 궁극적으로 지닌 능력은 무엇입니까?', `MaleText_loc4`='翡翠幼龙的终极技能是什么？', `MaleText_loc5`='翡翠龍的究極能力是什麼?', `MaleText_loc7`='¿Cuál es la habilidad definitiva del draco esmeralda?', `FemaleText_loc1`='에메랄드 비룡이 지닌 궁극적으로 지닌 능력은 무엇인가요?', `FemaleText_loc4`='翡翠幼龙的终极技能是什么？', `FemaleText_loc5`='翡翠龍的究極能力是什麼?', `FemaleText_loc7`='¿Cuál es la habilidad definitiva del draco esmeralda?' WHERE `ID`=28090;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='루비 비룡은 피해량을 줄여 아군을 보호하는 능력이 뛰어납니다. 불타는 격노로, 이 대상 저 대상으로 옮겨 다닐 때마다 피해가 점점 더 증가하는 액화 불길을 내뿜을 수 있습니다. 비룡이 적의 공격을 받을 때마다 회피력이 충전됩니다. 이 회피력으로 교묘한 회피를 시전하여 날아드는 공격이나 마법을 피할 수 있습니다.', `MaleText_loc4`='红玉幼龙擅长降低伤害以及保护盟友。

它们使用灼热之怒喷出液体火焰，在敌对目标之间跳跃，每次跳跃都能增加对目标的伤害。

当红玉幼龙受到攻击时，它将获得可叠加的闪避能量，由此触发的闪避机动可使幼龙暂时躲过接下来的攻击与法术伤害。', `MaleText_loc5`='晶紅龍擅長減輕傷害，以及保護他們的同伴。

他們能使用「灼熱之怒」，噴吐出一道道的液態火焰，在多個目標之間跳躍，每增加一次跳躍都能造成更大的傷害。

每當晶紅龍遭受敵人攻擊時，他還能獲得一發「迴避能量」。這些能量可以用來施展一系列的迴避動作，使飛龍在一段時間中閃躲來襲的攻擊與法術。', `MaleText_loc7`='Los dracos rubí destacan en aguantar daño y proteger a sus aliados.

Al utilizar Cólera abrasadora pueden lanzar fuego líquido que salta de objetivo en objetivo, haciendo cada vez más daño.

Cada vez que un draco rubí es alcanzado por un ataque enemigo, gana una Carga evasiva. Estas cargas sirven para realizar una serie de maniobras evasivas, que permiten al draco esquivar los ataques y hechizos durante un tiempo.' WHERE `ID`=28091;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호박색 비룡은 시간을 마음대로 조절해 피해를 주는 능력이 뛰어나지요. 충격의 창 기술을 사용하면, 적 주변에 흐르는 시간을 교란시킨 다음 즉시 피해를 줄 수 있어요. 충격 충전을 시전하면 그 위력을 극대화할 수도 있지요. 호박색 비룡은 위험에 처했을 때 잠시나마 적들의 시간을 멈출 수 있어요. 이런 시간 교란으로 효과를 받는 상대의 충격 에너지를 충격 충전의 형태로 축적하지요.', `MaleText_loc4`='琥珀幼龙擅长操控时间来制造伤害。

它们使用震击之枪扰乱敌对目标附近的时间流，立即对目标造成伤害。震击能量将在目标身上叠加，叠加次数越多，目标受到的伤害就越高。

危急时，琥珀幼龙还能停止敌对目标的时间流。在这种情况下，目标身上将储存大量的震击能量。', `MaleText_loc5`='琥珀龍擅長於利用操縱時間來造成傷害。

「震擊之槍」可以擾亂敵方目標的時間流，造成立即傷害，而且效果會隨著目標身上震擊能量的累積而大幅強化。

當受到威脅時，琥珀龍可以短暫停止敵人的時間流。「暫停時間」還蘊含了大量的震能，能在受影響的目標身上聚集數道震擊能量。', `MaleText_loc7`='Los dracos ámbar destacan en causar daño gracias a que pueden manipular el tiempo a su favor.

Al utilizar la Lanza de choque pueden interrumpir el flujo del tiempo alrededor de un enemigo, haciéndole daño instantáneamente. El poder de este efecto aumenta enormemente dependiendo de las Cargas de choque en el objetivo.

Cuando se ve amenazado, un draco de ámbar puede detener brevemente el flujo del tiempo de sus enemigos. Esta interrupción del tiempo almacena una gran cantidad de Energía de choque en los objetivos afectados en la forma de Cargas de choque.' WHERE `ID`=28092;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='에메랄드 비룡은 적을 중독시키는 동시에 스스로 치유하는 능력이 뛰어나지요. 착취 독을 사용하여 적의 체력을 빨아들인답니다. 이 독을 반복해서 사용할수록 그 효과가 높아지지요. 악몽 접근 기술을 사용하여 상대의 꿈속에 접근하면, 에메랄드 비룡은 생명의 기운 일부를 강력한 공격으로 전환하여 대상을 약하게 하고 대상의 공격력을 일시적으로 낮출 수 있답니다.', `FemaleText_loc4`='翡翠幼龙擅长在毒伤敌人的同时治疗自己。

它们使用吸血之毒从敌对目标身上偷取生命。毒药可以叠加，每次叠加都能增加生命偷取的效果。

翡翠幼龙还能使用噩梦之触进入梦境，将一部分自身的生命能量转化成高伤害的攻击，令敌对目标虚弱并在短时间内降低目标造成的伤害。', `FemaleText_loc5`='翡翠龍擅長毒害敵人同時治療自己。

他們能使用「吸血之毒」從敵人身上偷取生命，而且重複施放這毒素還可以提高其效果。

利用「夢魘之觸」，翡翠龍可以探入翡翠夢境，轉化他們一部分的生命能量成為威力強大的的攻擊，並且使對手虛弱，短時間內降低他們的傷害能力。', `FemaleText_loc7`='Los dracos esmeralda destacan en curarse a sí mismos mientras envenenan a sus enemigos.

Al usar el Veneno parasitante, pueden robarle salud a sus enemigos. Varias aplicaciones de este veneno pueden aumentar el efecto.

Con Tocar la pesadilla los dracos esmeralda pueden alcanzar el Sueño, convirtiendo una parte de su energía vital en un ataque muy dañino que deja debilitado al objetivo, reduciendo su daño durante poco tiempo.' WHERE `ID`=28093;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘이 최고조에 달한 루비 비룡은 희생을 사용하여 잠시 동안 적의 모든 마법을 자신에게 향하도록 하여 아군을 보호할 수 있습니다. 교묘한 회피는 희생을 사용하는 중에도 계속 사용할 수 있지요..', `MaleText_loc4`='拥有终极力量的红玉幼龙可以使用殉难，撑起护盾保护友方目标，短时间内对友方目标的所有魔法伤害将由红玉幼龙承担。使用该技能的同时仍可触发闪避机动。', `MaleText_loc5`='晶紅龍處於能量全滿的狀態下可以施展殉節，可以保護友善目標，短時間內將所有敵對的魔法導引到晶紅龍身上。殉節施展的過程中依然可以使用迴避動作。', `MaleText_loc7`='Un draco rubí, con todo su poder, puede llevar a cabo Mártir, que protege a los objetivos amistosos redirigiendo toda la magia hostil hacia el draco rubí durante un breve periodo de tiempo. Maniobras evasivas se puede realizar mientras Mártir está activo.' WHERE `ID`=28094;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘이 최고조에 달한 호박색 비룡은 시간의 균열을 사용하여 압축된 시간의 기포를 적 주변에 형성합니다. 이 기포를 통과한 마법은 대상에게 2배의 피해를 주고, 충격 충전까지 일으키지요.', `MaleText_loc4`='全盛状态的琥珀幼龙可以使用时间裂隙，制造出压缩时间结界包围敌对目标。穿过结界的法术将对该目标造成双倍的伤害，还能在目标身上叠加震击能量。', `MaleText_loc5`='琥珀龍處於能量全滿的狀態下可以施展時光裂隙，在敵人身邊製造出一顆壓縮的時間泡泡。通過泡泡的法術會造成雙倍的傷害，並且在目標上產生震擊能量。', `MaleText_loc7`='Un draco ámbar con todo su poder puede llevar a cabo Falla temporal, que crea una burbuja de tiempo comprimido alrededor de un enemigo. Los hechizos que pasan a través de la burbuja infligen el doble de daño y pueden generar Cargas de choque sobre el enemigo.' WHERE `ID`=28095;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='힘이 최고조에 달한 에메랄드 비룡은 꿈의 집중을 사용하여 비룡의 생명 에너지를 아군 대상에게 보내 치유할 수 있지요. 착취 독을 사용하면 잃은 체력을 회복할 수 있답니다.', `FemaleText_loc4`='全盛状态的翡翠幼龙可以使用梦境通道，将自身的生命能量转移到友方目标身上，以此进行治疗。使用该技能的同时仍可利用吸血之毒恢复生命值。', `FemaleText_loc5`='翡翠龍處於能量全滿的狀態下可以施展「夢境通道」，傳送飛龍本身的生命能量到一名友方目標身上，進行治療。施展「吸血之毒」可以恢復因為使用這個能力而損失的生命力。', `FemaleText_loc7`='Un draco esmeralda con todo su poder puede realizar Cauce de sueño, que transfiere la propia energía vital del draco a un objetivo amistoso y lo sana. Veneno parasitante se puede usar para restaurar la salud que se pierde al usar esta facultad.' WHERE `ID`=28096;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주, 주인님... 가, 갑옷을 닦아드릴까요...?', `MaleText_loc4`='小……小姐，您的盔甲需要抛……抛光吗？', `MaleText_loc5`='夫、夫人...我可以擦、擦亮您的鎧甲嗎...?', `MaleText_loc7`='Se...señora... ¿puedo sacar brillo a su armadura?' WHERE `ID`=28097;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주, 주인님... 주인님 마, 말을 솔질할까요...?', `MaleText_loc4`='小……小姐，您的战马需要梳……梳洗吗？', `MaleText_loc5`='夫、夫人...我可以刷、刷洗您的強大坐騎嗎...?', `MaleText_loc7`='Se...señora... ¿puedo cepillar a su poderoso corcel?' WHERE `ID`=28098;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주, 주인님... 도끼를 가, 갈아야 하지 않을까요...?', `MaleText_loc4`='小……小姐，您的战斧需要打……打磨吗？', `MaleText_loc5`='夫、夫人...請問您的巨斧需、需要磨利嗎...?', `MaleText_loc7`='Se...señora... ¿necesita que afile su hacha?' WHERE `ID`=28099;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주, 주인님... 시, 시체 가루를 더 가, 가져다 드릴까요...?', `MaleText_loc4`='小……小姐，您需……需要更多的尸尘吗？', `MaleText_loc5`='夫、夫人...也、也許，您需、需要更多的屍塵...?', `MaleText_loc7`='Se...señora... ¿quizá necesita más polvo de cadáver?' WHERE `ID`=28100;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예, 주, 주인님...', `MaleText_loc4`='遵命，尊贵的小……小姐……', `MaleText_loc5`='是的，夫、夫人...', `MaleText_loc7`='Sí, M-maestra…' WHERE `ID`=28101;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='물러나라, 에드워드, 안그러면 네 목을 치겠다.', `FemaleText_loc4`='离我远点，爱德华。否则我要你好看。', `FemaleText_loc5`='滾開我身邊，愛德華斯，免得我把你的頭砍下來。', `FemaleText_loc7`='Aléjate de mí, Edwards, o te decapitaré.' WHERE `ID`=28102;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='필요 없다, 더러운 자식. 꺼져버려라.', `FemaleText_loc4`='不需要。可怜虫，给我滚开。', `FemaleText_loc5`='不要，你這流鼻涕的小鬼，馬上消失。', `FemaleText_loc7`='No, llorón desgraciado. Ahora lárgate.' WHERE `ID`=28103;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 눈앞에서 사라져라. 아니면 널 죽여줄 테다. 한 번 더.', `FemaleText_loc4`='别出现在我面前，不然我杀了你。我再说一次。', `FemaleText_loc5`='在我宰了你以前，侍從，你可以離開我的視線。我再次強調。', `FemaleText_loc7`='Puedes desaparecer de mi vista, escudero, antes de que te mate. De nuevo.' WHERE `ID`=28104;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='필요 없다. 사라져라. 버러지 같은 놈.', `FemaleText_loc4`='不要。滚远点。', `FemaleText_loc5`='不，遠離我，蛆蟲。', `FemaleText_loc7`='No. Lárgate, gusano.' WHERE `ID`=28105;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이단자들! 심판의 날이 곧 온다!', `MaleText_loc4`='异端！清算之日即将来临！', `MaleText_loc5`='異教徒!清算之日來了!', `MaleText_loc7`='¡Infieles! ¡El día del Juicio Final se acerca!', `FemaleText_loc1`='이단자들! 심판의 날이 곧 올 거야!', `FemaleText_loc4`='异端！清算之日即将来临！', `FemaleText_loc5`='異教徒!清算之日來了!', `FemaleText_loc7`='¡Infieles! ¡El día del Juicio Final se acerca!' WHERE `ID`=28106;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛이 너희를 이 세상에서 몰아낼 것이다!', `MaleText_loc4`='圣光会将你从这个世界上抹除！', `MaleText_loc5`='聖光將汝等驅離這個世界!', `MaleText_loc7`='¡Que la Luz te purgue de este mundo!', `FemaleText_loc1`='빛이 너희를 이 세상에서 몰아낼 거야!', `FemaleText_loc4`='圣光会将你从这个世界上抹除！', `FemaleText_loc5`='聖光將汝等驅離這個世界!', `FemaleText_loc7`='¡Que la Luz te purgue de este mundo!' WHERE `ID`=28107;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희는 붉은십자군을 막을 수 없다!', `MaleText_loc4`='你无法阻止血色十字军前进的脚步！', `MaleText_loc5`='你們阻止不了血色十字軍的!', `MaleText_loc7`='¡No puedes detener a la Cruzada Escarlata!', `FemaleText_loc1`='너희는 붉은십자군을 막을 수 없어!', `FemaleText_loc4`='你无法阻止血色十字军前进的脚步！', `FemaleText_loc5`='你們阻止不了血色十字軍的!', `FemaleText_loc7`='¡No puedes detener a la Cruzada Escarlata!' WHERE `ID`=28108;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희는 이미 십자군의 적으로 낙인 찍혔다, 이교도들!', `MaleText_loc4`='你们是十字军不共戴天的仇敌！', `MaleText_loc5`='異教徒，你們已經被烙上十字軍之敵的印記了!', `MaleText_loc7`='¡Habéis sido marcados como enemigos de la Cruzada, infieles!', `FemaleText_loc1`='너희는 이미 십자군의 적으로 낙인 찍혔어, 이교도들!', `FemaleText_loc4`='你们是十字军不共戴天的仇敌！', `FemaleText_loc5`='異教徒，你們已經被烙上十字軍之敵的印記了!', `FemaleText_loc7`='¡Habéis sido marcados como enemigos de la Cruzada, infieles!' WHERE `ID`=28109;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희는 붉은십자군의 힘 앞에 무릎 꿇을 것이다!', `MaleText_loc4`='所有人都将屈服于血色十字军的力量！', `MaleText_loc5`='任何人都將臣服於血色十字軍之力下!', `MaleText_loc7`='¡Todos caerán ante el poder de la Cruzada Escarlata!', `FemaleText_loc1`='너희는 붉은십자군의 힘 앞에 무릎 꿇고 말 거야!', `FemaleText_loc4`='所有人都将屈服于血色十字军的力量！', `FemaleText_loc5`='任何人都將臣服於血色十字軍之力下!', `FemaleText_loc7`='¡Todos caerán ante el poder de la Cruzada Escarlata!' WHERE `ID`=28110;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='붉은십자군이 나를 찾아내어 풀어줄 것이다... 이 한심한 철창 안에 언제까지 가둬놓을 수 있을 것 같으냐!', `MaleText_loc4`='他们会来救我的……别以为这些可笑的牢笼能永远禁锢我！', `MaleText_loc5`='他們會找到我並放了我...你那可悲的牢籠關不了我多久的!', `MaleText_loc7`='Me encontrarán y me liberarán... ¡Sus patéticas jaulas no me retendrán mucho tiempo!', `FemaleText_loc1`='붉은십자군이 나를 찾아내어 풀어줄 거야... 이 한심한 철창 안에 언제까지 가둬놓을 수 있을 것 같아!', `FemaleText_loc4`='他们会来救我的……别以为这些可笑的牢笼能永远禁锢我！', `FemaleText_loc5`='他們會找到我並放了我...你那可悲的牢籠關不了我多久的!', `FemaleText_loc7`='Me encontrarán y me liberarán... ¡Sus patéticas jaulas no me retendrán mucho tiempo!' WHERE `ID`=28111;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희들이 저지른 악행을 빛이 용서하기를.', `MaleText_loc4`='愿圣光原谅你犯下的一切过错。', `MaleText_loc5`='願聖光原諒你的惡行。', `MaleText_loc7`='Que la Luz te perdone por el mal que haces.', `FemaleText_loc1`='너희들이 저지른 악행을 빛이 용서하기를.', `FemaleText_loc4`='愿圣光原谅你犯下的一切过错。', `FemaleText_loc5`='願聖光原諒你的惡行。', `FemaleText_loc7`='Que la Luz te perdone por el mal que haces.' WHERE `ID`=28112;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 왜 계속 맞서는지 아직도 모르겠나?', `MaleText_loc4`='你还不明白我们为什么要反抗十字军吗？', `MaleText_loc5`='你難道還不明白為何我們背水一戰嗎?', `MaleText_loc7`='¿No te has dado cuenta de por qué permanecemos desafiantes?', `FemaleText_loc1`='우리가 왜 계속 맞서는지 아직도 모르는 거야?', `FemaleText_loc4`='你还不明白我们为什么要反抗十字军吗？', `FemaleText_loc5`='你難道還不明白為何我們背水一戰嗎?', `FemaleText_loc7`='¿Aún no te has dado cuenta de por qué permanecemos desafiantes?' WHERE `ID`=28113;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은빛 여명회는 끝까지 싸울 것이다!', `MaleText_loc4`='银色黎明将战斗到底！', `MaleText_loc5`='銀色黎明將戰到最後一刻!', `MaleText_loc7`='¡El Alba Argenta luchará hasta el final!', `FemaleText_loc1`='은빛 여명회는 끝까지 싸울 거야!', `FemaleText_loc4`='银色黎明将战斗到底！', `FemaleText_loc5`='銀色黎明將戰到最後一刻!', `FemaleText_loc7`='¡El Alba Argenta luchará hasta el final!' WHERE `ID`=28114;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 늦지 않았다, 형제자매들이여. 회개하라! 회개하면 구원받을 수 있다!', `MaleText_loc4`='兄弟姐妹们，一切还来得及。忏悔吧！你们会得到救赎的。', `MaleText_loc5`='兄弟姊妹們，時間還不算太晚。悔悟吧!悔悟你們方能得救。', `MaleText_loc7`='No es demasiado tarde, hermanos y hermanas. ¡Arrepentíos! ¡Arrepentíos y seréis salvados!', `FemaleText_loc1`='아직 늦지 않았어요, 형제자매들이여. 회개하세요! 회개하면 구원받을 수 있어요!', `FemaleText_loc4`='兄弟姐妹们，一切还来得及。忏悔吧！你们会得到救赎的。', `FemaleText_loc5`='兄弟姊妹們，時間還不算太晚。悔悟吧!悔悟你們方能得救。', `FemaleText_loc7`='No es demasiado tarde, hermanos y hermanas. ¡Arrepentíos! ¡Arrepentíos y puede que seáis salvados!' WHERE `ID`=28115;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나를 죽여봤자 우리 동지들의 결단력이 더 굳건해질 뿐이다. 애쓰지 마라!', `MaleText_loc4`='我的死只会令同胞们坚定必胜的决心。有胆你就动手吧！', `MaleText_loc5`='殺了我只會讓我的同胞們心意更堅定。放馬過來吧!', `MaleText_loc7`='Matándome solo reforzaréis la determinación de mis hermanos. ¡A ver qué podéis hacer!', `FemaleText_loc1`='나를 죽여봤자 우리 동지들의 결단력이 더 굳건해질 뿐이야. 애쓰지 마!', `FemaleText_loc4`='我的死只会令同胞们坚定必胜的决心。有胆你就动手吧！', `FemaleText_loc5`='殺了我只會讓我的同胞們心意更堅定。放馬過來吧!', `FemaleText_loc7`='Matándome solo reforzaréis la determinación de mis hermanos. ¡A ver qué podéis hacer!' WHERE `ID`=28116;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 그 대가로 엄청난 보상을 얻게 될 거야.', `MaleText_loc4`='对于你付出的努力，我一定要给你丰厚的报酬……', `MaleText_loc5`='對於你所付出的努力，你可以獲得最豐厚的報酬...', `MaleText_loc7`='Por tu esfuerzo, tú recibir las mayores recompensas…' WHERE `ID`=28118;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 깨달음을!', `MaleText_loc4`='真相！', `MaleText_loc5`='顯現真相!', `MaleText_loc7`='¡Revelación!' WHERE `ID`=28119;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='숨을 죽이게, 친구. 진실을 똑똑히 목격하게!', `MaleText_loc4`='朋友，现在来安静地领悟真相吧！', `MaleText_loc5`='朋友，別動，見識真相吧!', `MaleText_loc7`='¡Tranquilo, amigo, y contemplar la verdad de las cosas!' WHERE `ID`=28120;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='온몸이 만신창입니다... 더 버틸 수가...', `MaleText_loc4`='我……我就要挂了……要坚持……不住了……', `MaleText_loc5`='我快不行了...也許撐...撐不下去了。', `MaleText_loc7`='Estoy estropeado... Quizás no... lo logre.' WHERE `ID`=28121;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더는 참아주기가 어렵구나. 이제 진정한 푸른용군단의 힘을 보아라.', `MaleText_loc4`='你在考验我的耐心，现在就让你见识一下蓝龙的真正力量。', `MaleText_loc5`='你考驗我的耐性，就讓你瞧瞧藍龍的真正力量。', `MaleText_loc7`='Pones a prueba mi paciencia, ahora verás el verdadero poder del Azul.' WHERE `ID`=28122;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하! 순순히 내 보물을 가져가게 둘 것 같나!', `MaleText_loc4`='哈！别想夺走我的财宝！', `MaleText_loc5`='哈!你不能拿走我的寶藏!', `MaleText_loc7`='¡Ja! ¡Tú no conseguir mi tesoro!' WHERE `ID`=28123;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽여라! 놈들을 모두 죽이고 짐토르가를 되찾아라!', `MaleText_loc4`='杀光他们！杀光他们，夺回希姆托加！', `MaleText_loc5`='殺了他們!殺光他們帶回辛托加!', `MaleText_loc7`='¡Mátalos! ¡Mátalos y recupera Zim''Torga!' WHERE `ID`=28124;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님, 저는 임무를 완수했습니다.', `MaleText_loc4`='主人，我的任务完成了。', `MaleText_loc5`='主人，我的任務完成了。', `MaleText_loc7`='Amo, mi misión estar cumplida.' WHERE `ID`=28125;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잔달라 부족과 그 허수아비들에게 죽음을! 이제 그 무엇도 우리를 막을 수 없다!', `MaleText_loc4`='杀死赞达拉巨魔和他们的傀儡！谁也别想阻止我们！', `MaleText_loc5`='死亡降臨贊達拉和他們的傀儡!現在沒人能阻止得了我們!', `MaleText_loc7`='¡Muerte a los Zandalari y a sus marionetas! ¡Ahora nada puede detenernos!' WHERE `ID`=28126;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필멸의 존재에게 도움을 받아, 이 지역의 적을 박살 냈습니다.', `MaleText_loc4`='在这些凡人的帮助下，所有胆敢反抗我们的家伙都已经被清除了。', `MaleText_loc5`='在這些凡人的幫助下，所有膽敢反抗我們的傢伙都已經被清除了。', `MaleText_loc7`='Con la ayuda de estos mortales, esta región ser libre de todos nuestros enemigos.' WHERE `ID`=28127;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='볼리안 양... 저와...', `MaleText_loc4`='波利安小姐……你愿意……', `MaleText_loc5`='寶莉安小姐...你願意...', `MaleText_loc7`='Señorita Boulian... Hará...' WHERE `ID`=28128;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 반지를 받아 주시겠습니까?', `MaleText_loc4`='你愿意收下这枚戒指吗？', `MaleText_loc5`='你願意收下我的戒指嗎?', `MaleText_loc7`='¿Aceptarás mi anillo?' WHERE `ID`=28129;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘해 줬다, 드라쿠루.', `MaleText_loc4`='你做得很好，达库鲁。', `MaleText_loc5`='你做的很好，德拉庫魯。', `MaleText_loc7`='Hiciste bien, Drakuru.' WHERE `ID`=28130;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 드라카리 제국을 배신해 준 덕분에 내게는 새로운 군대가 생겼지.', `MaleText_loc4`='你对达卡莱帝国的背叛为我制造出了一支新的军团。', `MaleText_loc5`='你對德拉克瑞帝國的背叛，為我創造了一支新軍團。', `MaleText_loc7`='Tu traición al Imperio Drakkari me ha granjeado un nuevo ejército.' WHERE `ID`=28131;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어머나, 채드... 그러겠어요!', `FemaleText_loc4`='噢，查德……我当然愿意！', `FemaleText_loc5`='噢，查德...我當然願意!', `FemaleText_loc7`='Oh, Chad... ¡claro que sí!' WHERE `ID`=28132;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너의 군대가...', `MaleText_loc4`='你的军团……', `MaleText_loc5`='屬於你的軍團...', `MaleText_loc7`='Tu ejército...' WHERE `ID`=28133;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일어나라. 내 너에게 상을 주겠다.', `MaleText_loc4`='平身，接受我的赏赐吧。', `MaleText_loc5`='平身，接受我的賞賜吧。', `MaleText_loc7`='Levántate, y acepta mi obsequio.' WHERE `ID`=28134;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대의 비룡은 이제 최고의 힘을 사용할 수 있습니다. 그 힘을 사용해 에레고스를 격파하십시오!', `MaleText_loc4`='幼龙的终极力量已经解封。利用它们的力量击败埃雷苟斯吧！', `MaleText_loc5`='你的飛龍力量已全部開啟，利用他們的能力擊敗伊瑞茍斯!', `MaleText_loc7`='Se ha desbloqueado el poder total de tus dracos. ¡Usa su poder para derrotar a Eregos!' WHERE `ID`=28135;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='환영하노라, 친구여. 고개를 낮추고 꼭 잡으라!', `MaleText_loc4`='朋友，欢迎你。在这里记得随时保持警惕！', `MaleText_loc5`='歡迎你，朋友。低下頭手抓緊!', `MaleText_loc7`='Te doy la bienvenida, colega. ¡Mantén la cabeza agachada y agárrate bien!' WHERE `ID`=28136;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바위돌기고릴라는 따분하다. 왜 또 여기 온 거지?', `MaleText_loc4`='硬皮猩猩很烦呀。我们为什么还来这里？', `MaleText_loc5`='硬拳很無趣。我們為什麼還在這裡?', `MaleText_loc7`='Callonudillos aburrir. ¿Por qué estamos aquí otra vez?' WHERE `ID`=28137;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바위돌기고릴라를 계속 사냥하다 보면 고어게크처럼 될 거다. 고어게크처럼 되고 싶나?', `MaleText_loc4`='要是你不停地杀硬皮猩猩，就会成为格利基克那样的家伙。你想变成他那样吗？', `MaleText_loc5`='如果你一直殺硬拳，你長大就會像茍瑞格克。你想要和茍瑞格克一樣嗎?', `MaleText_loc7`='Si seguir matando callonudillos, tú de mayor ser como Goregek. ¿Tú querer ser como Goregek?' WHERE `ID`=28138;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 비단돌기고릴라를 더 찌르려 한다면 이 다지크가 너까지 찔러버릴 거다. 그건 고어게크 나쁜 습관이다.', `MaleText_loc4`='如果你是来戳软皮猩猩的话，达伊克就要戳你了。别学格利基克的坏习惯。', `MaleText_loc5`='如果你在這戳死更多的鬃松，達吉克也要來戳你了。那是茍瑞格克的壞習慣。', `MaleText_loc7`='Si estar aquí para pinchar a más badanudillos, Dajik pincharte a ti también. Ser una mala costumbre de Goregek.' WHERE `ID`=28139;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음... 여긴 어디지? 이상하다. 바위돌기고릴라를 찾으라는 얘기 내가 하지 않았나? 했었나?', `MaleText_loc4`='哈……我们在哪儿？不对呀。我们不是来找硬皮猩猩的吧？', `MaleText_loc5`='哼...這是哪?這不對。我沒有告訴你去找硬拳吧，有嗎?', `MaleText_loc7`='Eh... ¿dónde estamos? Algo no ir bien. No decir que encontraras callonudillos, ¿verdad?' WHERE `ID`=28140;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='광란심장 일족이 새로운 보금자리를 찾아 이곳으로 온 것도 그리 오래전은 아니다... 날름이 보금자리가 꽤 좋은 곳이어서 우린 그곳도 차지하려 한다. 어쨌든 좋은 놈들은 아니니까.', `MaleText_loc4`='不久前，狂心氏族在这里安了新家……大舌头怪的屋子看上去很漂亮啊，我们其实可以抢来自己住。它们那么丑，才不配住这么好看的地方。', `MaleText_loc5`='狂心不久前來這找新家...大舌頭的家很不錯，所以我們也許就接收了。反正他們很醜。', `MaleText_loc7`='Corazón Frenético vinieron aquí no hace mucho buscando nuevo hogar... hogares de lenguas-grandes bastante bonitos, así que igual apoderarse. De todas formas, ellos feos.' WHERE `ID`=28141;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠시 내 얘기 좀 들어봐라.', `MaleText_loc4`='等等，听我说。', `MaleText_loc5`='等一下，仔細聽。', `MaleText_loc7`='Quédate un momento y escucha.' WHERE `ID`=28142;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무것도 잊어버리지 마라. 난 가끔씩 그런다.', `MaleText_loc4`='看看你有没有忘记什么东西啊。我以前就老忘事儿。', `MaleText_loc5`='確定你沒有遺忘任何東西。我就忘記過一次。', `MaleText_loc7`='Asegurarte de no olvidar nada. Yo olvidé cosas una vez.' WHERE `ID`=28143;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말뚝 대부분을 내가 박아놓았다. 뾰족뾰족하게 딱 좋은 정도지. 맘에 드나?', `MaleText_loc4`='我在栅栏上安了许多尖刺。它们看上去挺锋利的。你觉得呢？', `MaleText_loc5`='我把大部分的矛都放好了。我想夠多尖尖的東西了。你喜歡嗎?', `MaleText_loc7`='He colocado la mayoría de las puntas. Creo que es bastante puntiagudo. ¿Te gusta?' WHERE `ID`=28144;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강한 광란심장 일족 여기 많다. 다지크가 대부분 가르쳤지. 처음에는 너 같은 것도 가르쳤지. 알겠지만 너는 광란심장 일족이 아니다.', `MaleText_loc4`='这里有许多优秀的猎手，大部分都是达伊克调教出来的。不过教你这样的家伙还是头一次。要知道，你并不是狂心氏族的成员。', `MaleText_loc5`='一堆健壯的狂心在這裡。達吉克教導過他們大部分的人，第一次教到和你一樣厲害的。你知道，你不是狂心。', `MaleText_loc7`='Muchos Corazón Frenético por aquí. Dajik enseñó a la mayoría. Aunque primera vez que enseño a algo como tú. Tú no Corazón Frenético, ¿sabes?' WHERE `ID`=28145;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어린 녀석들을 조심해라. 광란심장 일족은 어릴 때 꽤 사납다.', `MaleText_loc4`='当心那些幼崽。狂心狼獾人从小就很阴险。', `MaleText_loc5`='盯緊這些小狗，狂心小時候就很邪惡。', `MaleText_loc7`='Cuidado con los cachorros. Los Corazón Frenético son despiadados de pequeños.' WHERE `ID`=28146;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 배우는 중이라는 건 알지만, 날름이들은 나쁜 놈들이다. 광란심장 일족은 좋고 날름이들은 나쁘다. 알았나?', `MaleText_loc4`='我知道你还在不断地学习，但是大舌头怪很坏。狂心狼獾人是好人，大舌头怪是坏人，明白吗？', `MaleText_loc5`='我知道你還在學習，但是大舌頭很壞。狂心好，大舌頭壞，懂嗎?', `MaleText_loc7`='Sé que aún estás aprendiendo, pero los lenguas-grandes son malos. Corazón Frenético buenos, lenguas-grandes malos, ¿vale?' WHERE `ID`=28147;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='눈을 찔러라. 날름이들은 그걸 아주 싫어한다.', `MaleText_loc4`='戳它的眼睛，大舌头怪最讨厌这一招了。', `MaleText_loc5`='戳眼睛，大舌頭最討厭這樣了。', `MaleText_loc7`='Pínchale en el ojo, los lenguas-grandes odian eso.' WHERE `ID`=28148;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 놀이는 끝이다. 이제 처리해야지.', `MaleText_loc4`='嗯，玩够啦。杀死它算了。', `MaleText_loc5`='好啦，玩的時間結束，該殺掉它了。', `MaleText_loc7`='Vale, basta de juegos. Hora de matarlo.' WHERE `ID`=28149;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우스워 보이는 놈들이지만, 늦게 시작할수록 처리해야 할 숫자가 늘어난다.', `MaleText_loc4`='我知道它们长得很滑稽，但是你也别老盯着看啊，多杀些吧。', `MaleText_loc5`='我知道他們長得很好笑，但是少一點驚訝，多殺一些。', `MaleText_loc7`='Sé que tienen un aspecto peculiar, pero menos sorprenderse y más matar.' WHERE `ID`=28150;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 둘이 친구가 되겠다고? 늪지에 적당한 장소를 찾아서 중간날름이라도 기르겠다는 말인가? 감동적이군... 이제 헛소리 그만하지.', `MaleText_loc4`='啧啧，你们俩要做朋友吗？要不要在沼泽里安个窝再生一堆不大不小的中舌头怪啊？真浪漫啊……省省吧，别犯傻了。', `MaleText_loc5`='啊，你們兩個是朋友?也許到沼澤裡面找個好地方，吃自己的中舌頭?真溫馨...不要再裝笨了。', `MaleText_loc7`='Ooooh, ¿van a haceros amiguitos? ¿A lo mejor pueden encontrar un lugar bonito en la ciénaga y tener sus propias lenguas-medianas? Qué dulce... ahora dejen de hacer el tonto.' WHERE `ID`=28151;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='널 좋아하는 것 같다. 언덕으로 데리고 돌아가서 "요리 냄비로 들어가, 날름아."라고 부드럽게 물어보면 좋겠어. 안 그래?', `MaleText_loc4`='我觉着它挺喜欢你的。要不我们把它带回去，然后温柔地说：“大舌头乖乖，跳进锅里去吧。”你觉得怎么样？', `MaleText_loc5`='我想它喜歡你。也許我們可以把他帶回山上，好聲問他，「自己走進鍋子裡，大舌頭。」不錯吧?', `MaleText_loc7`='Creo que le gustas. A lo mejor podemos llevarlo de vuelta a la colina y pedírselo educadamente: "Metete en la olla, lengua-grande." ¿Te parece?' WHERE `ID`=28152;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다지크가 쓸모 있는 걸 또 알려주지! 카르탁을 타보려 하지 마라.', `MaleText_loc4`='听听达伊克的小建议吧！别想骑上卡塔克。', `MaleText_loc5`='達吉克的小秘訣!不要試著去騎卡爾塔克。', `MaleText_loc7`='¡Hora de recibir otro consejo inteligente de Dajik! No intentar montar sobre Kartak.' WHERE `ID`=28153;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카르탁은 날름이를 즐겨 먹는다. 그래도 배가 고프다면 광란심장 일족까지 먹어치울 거다. 그러니 카르탁이 배고프게 해서는 안 돼.', `MaleText_loc4`='卡塔克喜欢吃大舌头怪。但是它饿极了的话，也会吃狂心狼獾人。所以，千万别饿着卡塔克。', `MaleText_loc5`='卡爾塔克喜歡吃大舌頭。不過，卡爾塔克如果餓了，他也不介意吃狂心。所以一定要確定卡爾塔克不餓。', `MaleText_loc7`='A Kartak gustar sabor de lenguas-grandes. Pero si Kartak hambriento, no hacer asco a Corazón Frenético, así que asegurar que Kartak no hambriento.' WHERE `ID`=28154;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다지크밖에 없지만, 한동안은 계속 싸워야 할 것 같다. 그렇지?', `MaleText_loc4`='这场战斗似乎持续好一阵子了，怎么没瞧见别的狼獾人？', `MaleText_loc5`='也許只有達吉克，但是看起來這場戰鬥持續了好一段時間，對吧?', `MaleText_loc7`='Igual ser cosa de Dajik, pero parecer que está pelea durar ya un rato, ¿no?' WHERE `ID`=28155;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여긴 광란심장 언덕이 아니잖아. 여긴 또 어디지?', `MaleText_loc4`='这里不是狂心岭！我们又迷路了？', `MaleText_loc5`='這裡不是狂心之丘，我們到底在哪?', `MaleText_loc7`='Esto no ser Colina Corazón Frenético, ¿dónde estar nosotros de nuevo?' WHERE `ID`=28156;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빨리 배우는 편은 아니군. 말하자면 말이다.', `MaleText_loc4`='你学得可真够慢的。我只是说说而已。', `MaleText_loc5`='你學的不是很快，說說而已。', `MaleText_loc7`='Tú no aprender muy rápido. Solo comentar.' WHERE `ID`=28157;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요리에 쓸 커다란 새를 어디서 잡는지 궁금하겠지. 안 됐지만 비밀이다.', `MaleText_loc4`='你肯定特想知道我们烧烤的肉是打哪儿来的吧。就不告诉你，哈哈，这是秘密。', `MaleText_loc5`='我賭你很想知道我們怎麼把大鳥打下來烤。太可惜了，這是秘密。', `MaleText_loc7`='Apuesto a que te preguntas de dónde sacamos pájaros altos para asar. Qué pena, es un secreto.' WHERE `ID`=28158;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 드디어 뭘 좀 배운 모양이군!', `MaleText_loc4`='哈！或许你能学到点什么！', `MaleText_loc5`='哈!再怎麼說你多少也學了一點!', `MaleText_loc7`='¡Ja! ¡Quizá tú haber aprendido algo después de todo!' WHERE `ID`=28159;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='광란심장 일족이 사냥한 여왕이 이게 처음은 아니다. 언제나 여왕 더 있었던 것 같다.', `MaleText_loc4`='蜂后是杀不绝的。很快就会产生新的蜂后。', `MaleText_loc5`='這不是第一位狂心殺掉的女王。看起來一直會有新的。', `MaleText_loc7`='Esta no ser primera reina asesinada por Corazón Frenético. Parecer que siempre haber más.' WHERE `ID`=28160;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 여왕을 죽여버리다니! 무슨 짓을... 잠깐, 신경 쓰지 마라. 미안하다. 괜찮다.', `MaleText_loc4`='什么！你杀死了蜂后！怎么可能……呃，没什么。好吧，没什么。', `MaleText_loc5`='不!你殺掉了女王!你做了什...等等，算了。抱歉，那沒什麼。', `MaleText_loc7`='¡No! ¡Tú haber matado cosa reina! ¿Qué haber...? Espera, no importar. Perdón, estar bien.' WHERE `ID`=28161;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래! 혹시 모르니까 몇 번 더 찔러! 막 찌르라고!', `MaleText_loc4`='对！多捅几下，以防万一！捅得好！捅得好！', `MaleText_loc5`='沒錯!以防萬一，多刺幾刀!刺人好!', `MaleText_loc7`='¡Sí! ¡Apuñálalo unas cuantas veces más para asegurarte! ¡Apuñálalo bien!' WHERE `ID`=28162;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 여기 왔는지 모르겠다. 죽었으니 상관없지만.', `MaleText_loc4`='真不明白它怎么能捕杀那些多生物。不过反正它已经死了，威胁解除啦。', `MaleText_loc5`='不知道東西怎麼弄到這的。雖然不論死活就是。', `MaleText_loc7`='No saber cómo llegar aquí cosa. Pero dar igual si estar muerta.' WHERE `ID`=28163;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지난번에 다지크에게 배웠던 놈은 모래 괴물에게 먹혀 버렸다. 하지만 이번엔 그렇게 안 될걸!', `MaleText_loc4`='达伊克的上一个学徒就是被躲在沙里的怪物给吃掉的。我们最好别落得同样的下场！', `MaleText_loc5`='達吉克最後的學生被沙子傢伙吃了。我們這次做的比那還厲害!', `MaleText_loc7`='El último aprendiz de Dajik ser engullido por cosa de arena. ¡Pero esta vez hacerlo mejor!' WHERE `ID`=28164;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보통은 모래 밑에서 도망 다니는 녀석이지. 이번엔 도망쳐봤자 좋을 게 없다.', `MaleText_loc4`='危急时候，它通常会钻进沙里逃走的。看来这次它逃得不够快啊。', `MaleText_loc5`='通常它會逃跑到沙子裡面。但是這次逃得沒那麼好。', `MaleText_loc7`='Normalmente huir en la arena. No huir muy bien esta vez.' WHERE `ID`=28165;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 건 많이 보지는 못했다. 차라리 잘된 일이다. 보기 좋은 놈은 아니니까.', `MaleText_loc4`='我都没怎么见过。虽然不够漂亮，但是还将就吧。', `MaleText_loc5`='這可不常見。那還好，不是很漂亮。', `MaleText_loc7`='No ver muchos de estos. Pero ser bueno, no ser muy bonitos.' WHERE `ID`=28166;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다지크가 쓸모 있는 걸 또 알려주지! 시체가 널렸다는 건 시체가 될 가능성도 크다는 거다. 다지크는 지금 여기서 나간다.', `MaleText_loc4`='再来听听达伊克的小建议！好多亡灵啊，这意味着我们有很大的几率被变成亡灵。达伊克要逃命去了。', `MaleText_loc5`='達吉克的小秘訣!一堆死掉的東西意味著有很高的機會變成死掉的東西。達吉克要走了。', `MaleText_loc7`='¡Hora de recibir otro consejo inteligente de Dajik! Muchas cosas muertas significar muchas posibilidades de ser una cosa muerta. Dajik marcharse ahora.' WHERE `ID`=28167;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 배울 것은 다 배웠군! 모두 배웠어! 이제 너와 끔찍한 피 봉우리와도 작별이다.', `MaleText_loc4`='好吧！你什么都学会啦！没错！达伊克不管你了，你去研究那根邪恶的红柱子吧。', `MaleText_loc5`='你學完了!對!都完了!達吉克要留你和邪惡紅色柱子一起了。', `MaleText_loc7`='¡Ya has acabado de aprender! ¡Sí! ¡Todo listo! Ahora Dajik abandonar a ti y a maligna cosa pilar rojo.' WHERE `ID`=28168;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무너진 기둥은 위험한 곳이다. 다지크는 간다. 너도 그래야 한다.', `MaleText_loc4`='这根倒塌的柱子看上去很不安全。达伊克要走了，你也赶紧跟上吧。', `MaleText_loc5`='斷掉的柱子不是個安全地方。達吉克現在走，你也要跟著走。', `MaleText_loc7`='Pilar partido no es un lugar seguro. Dajik se va ahora, tú también tienes que irte.' WHERE `ID`=28169;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽은 놈들은 이미 무너진 기둥이 주는 교훈을 깨달았을 테지. 교훈은 죽은 얼간이들이나 곱씹게 내버려 둬라. 이제 집으로 돌아간다.', `MaleText_loc4`='你看那堆死尸，这就是靠近破柱子的下场。它们已经得到教训了。我们回家吧。', `MaleText_loc5`='死掉的傢伙已經在斷掉的柱子那邊上了一課。把這一課留給愚蠢、死掉的傢伙吧。回家去。', `MaleText_loc7`='Cosa muerta de allí ya haber aprendido lección de Pilar Partido. Dejar esa lección para estúpidas cosas muertas. Ir a casa ahora.' WHERE `ID`=28170;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다지크가 쓸모 있는 걸 또 알려주지! 고어게크가 또 닭을 풀어놓거든 직접 잡으라고 해.', `MaleText_loc4`='再来听听达伊克的小建议！如果格利基克又把鸡给放跑了，就让他把鸡们都捉回去。', `MaleText_loc5`='達吉克的小秘訣!如果茍瑞格克又把雞放出來，叫茍瑞格克再把雞抓回去。', `MaleText_loc7`='¡Hora de recibir otro consejo inteligente de Dajik! Si Goregek soltar pollos de nuevo, hacer que Goregek recoger pollos.' WHERE `ID`=28171;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아는지 모르겠지만, 닭은 꽤 잽싸게 움직인다.', `MaleText_loc4`='你可能没注意到，鸡……跑得有点快。', `MaleText_loc5`='也許你沒發現，雞跑起來快的跟什麼一樣。', `MaleText_loc7`='Quizá tú no darte cuenta de que pollos moverse bastante rápido.' WHERE `ID`=28172;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='광란심장 일족이 닭을 쫓아가지 않는 이유가 있다. 닭을 잃어버리면 얼간이로 보이기 때문이지.', `MaleText_loc4`='狂心狼獾人不去追鸡是有原因的。因为如果追不上的话，就太丢脸了。', `MaleText_loc5`='這就是狂心追不回雞的原因。看這些笨蛋跑輸雞。', `MaleText_loc7`='Haber razón para que Corazón Frenético no perseguir pollos. Parecer un poco tonto perder con los pollos.' WHERE `ID`=28173;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아! 다지크에게 좋은 생각이 있다. 닭 울음소리를 내면 닭이 너한테 몰려올지도 모른다!', `MaleText_loc4`='噢！达伊克想到个办法！我们来学鸡叫，它们或许会循声而来！', `MaleText_loc5`='噢!達吉克有好點子!你學雞叫，也許牠們會靠近你!', `MaleText_loc7`='¡Oh! ¡Dajik tener idea! ¡Hacer sonidos de pollo e igual ellos acercarse a ti!' WHERE `ID`=28174;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='닭이 이렇게 도망 다니는 꼴을 보니 통닭 먹고 싶은 생각이 사라진다.', `MaleText_loc4`='跑来跑去的……弄得达伊克再也不想吃鸡肉了。', `MaleText_loc5`='跑了這麼久，讓達吉克一點都不想吃這些雞了。', `MaleText_loc7`='Tanto correr hace que a Dajik se le quiten las ganas de comer pollo.' WHERE `ID`=28175;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가시털멧돼지나 먹는 게 어때? 쫓아다니는 것도 지겹다.', `MaleText_loc4`='我们改吃钢刺野猪怎么样？我不要再跑来跑去的。', `MaleText_loc5`='我們改吃鬃松，好嗎?追夠了。', `MaleText_loc7`='Comamos pinocerdas a cambio, ¿vale? Estar harto de perseguir.' WHERE `ID`=28176;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다지크가 쓸모 있는 걸 또 알려주지! 뭔가 꺼내려 입을 열어 보기 전에 죽었는지 반드시 확인해라!', `MaleText_loc4`='再来听听达伊克的小建议！在你搜刮战利品之前，要确保敌人已经死翘翘了。', `MaleText_loc5`='達吉克的小秘訣!在你準備洗劫之前確保那傢伙死了。', `MaleText_loc7`='¡Hora de recibir otro consejo inteligente de Dajik! Asegurar que cosa bien muerta antes de buscar botín en boca.' WHERE `ID`=28177;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그거면 됐다. 충분해.', `MaleText_loc4`='这次干得还算不错。仅仅是不错而已。', `MaleText_loc5`='那個你做得還不錯，只是還不錯而已。', `MaleText_loc7`='Tu hacerlo bastante bien con ese. Solo bien.' WHERE `ID`=28178;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런거 치워 버려! 다지크는 그런 거치적거리는 것들 딱 질색이야. 짜증난다.', `MaleText_loc4`='把尸体清理干净！达伊克最讨厌剥皮的时候被什么东西给挡着了。很烦人的。', `MaleText_loc5`='把那東西從屍體上拿下來!達吉克最討厭要剝皮的時候還有東西擋住你。真煩。', `MaleText_loc7`='¡Quitar cosas del cuerpo! Dajik odiar que haya cosas en medio cuando va a despellejar algo. Muy molesto.' WHERE `ID`=28179;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 다지크는 너보다 빨리 사냥하는 녀석들을 훈련시키지. 넌 아직도 배울 것이 많다.', `MaleText_loc4`='达伊克训练出来的幼崽杀得都比你快。你要学的东西还很多啊。', `MaleText_loc5`='達吉克訓練小狗殺人殺得比你還快。你還有很多要學呢。', `MaleText_loc7`='Dajik entrena cachorros que matan cosas más rápido que tú. Tú tener que aprender mucho más.' WHERE `ID`=28180;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 얼굴 봤나? 완전히 겁에 질렸더군. "아, 난 이제 죽었구나!"하는. 하하.', `MaleText_loc4`='你瞧见它的脸了吗？一副惶恐的表情，“啊，我要被那个大家伙砸扁啦！”哈哈哈。', `MaleText_loc5`='你看到臉了嗎?看起來好害怕。「啊，大傢伙要打扁我了!」哈。', `MaleText_loc7`='¿Has visto su cara? Parecía tan asustado, "¡Ah, la cosa grande va a aplastarme!" Ja.' WHERE `ID`=28181;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아프겠는데...', `MaleText_loc4`='看上去很痛苦的样子。', `MaleText_loc5`='看起來很痛。', `MaleText_loc7`='Eso parece doloroso.' WHERE `ID`=28182;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다지크는 네가 뭔가 먹는 걸 못 본 것 같다. 뭔가 먹긴 하나?', `MaleText_loc4`='达伊克从来没有见你吃过东西。你也要吃东西的，对吧？', `MaleText_loc5`='達吉克不覺得你有吃什麼東西。你有吃過東西，對吧?', `MaleText_loc7`='Dajik cree que no te ha visto comer nada. Tú comer a veces, ¿no?' WHERE `ID`=28183;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 우리 또 뭐 하는 거지? 다지크 기억이 나지 않는다.', `MaleText_loc4`='我们是来干什么？达伊克又忘记啦。', `MaleText_loc5`='我們在這做什麼來著?達吉克記不得了。', `MaleText_loc7`='¿Qué estabamos haciendo aquí? Dajik no lo recuerda.' WHERE `ID`=28184;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다지크가 쓸모 있는 걸 또 알려주지! 독침 달린 놈들을 정면으로 잡으려 하지 마라. 별로 좋은 방법이 아니다.', `MaleText_loc4`='再来听听达伊克的小建议！尽量别用脸去挡刺。没什么用的。', `MaleText_loc5`='達吉克的小秘訣!不要用臉去抓釘刺者。不是很有用。', `MaleText_loc7`='¡Hora de recibir otro consejo inteligente de Dajik! No intentar atrapar aguijonero con la cara. No funcionar bien.' WHERE `ID`=28185;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끝내주는 공격 계획을 짜던 중이었는데... 내 분필이 너한테 있다.', `MaleText_loc4`='我本来想写一份详细的攻击计划的……但是你拿走了我的笔。', `MaleText_loc5`='我正準備把最棒的進攻計畫描繪出來...但是你把我的粉筆拿走了。', `MaleText_loc7`='Iba a hacer un dibujo con el mejor plan de ataque... pero tú tienes mi tiza.' WHERE `ID`=28186;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일꾼은 보이는 것만큼 세지 않다. 말벌은 좀 껄끄럽지만.', `MaleText_loc4`='雄蜂只是外表凶悍而已，其实很容易对付的。巨蜂就比较麻烦一点。', `MaleText_loc5`='雄蜂沒有看起來得那麼厲害，黃蜂比較麻煩。', `MaleText_loc7`='Cosas zángano no tan duras como parecer. Cosas avispa un poco más terribles.' WHERE `ID`=28187;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 뭔가를 하러 오지 않았나? 기억이 안 난다.', `MaleText_loc4`='我们来这里是有目的的，对吧？我想不起来了。', `MaleText_loc5`='我們是要來幹嘛的，對吧?記不得了。', `MaleText_loc7`='Nosotros venir por algo, ¿sí? No recordar.' WHERE `ID`=28188;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다지크가 돌아올 때마다 벌레들이 늘어나는 것 같다. 왜 줄어들지를 않는 거지?', `MaleText_loc4`='每次来虫巢，达伊克都觉得这里的巨蜂又变多了。它们的数量怎么就不见少呢？', `MaleText_loc5`='看起來每次達吉克回來就有更多的黃蜂在等我。為什麼他們不會死光?', `MaleText_loc7`='Parecer que haber más avispas cada vez que Dajik volver. ¿Por qué no acabarse?' WHERE `ID`=28189;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='궁금할까 봐 말해주겠는데, 벌레들한테 쏘이면 별로 기분이 좋지 않다. 괜히 시험해볼 생각 마라.', `MaleText_loc4`='我告诉你，被蜇的滋味可不好受。你最好别去尝试。', `MaleText_loc5`='以防你會想知道，黃蜂刺的感覺很糟。不需要去試。', `MaleText_loc7`='Si tienes alguna duda, la picadura de avispa no es una sensación agradable. No hace falta que pruebes.' WHERE `ID`=28190;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다지크가 쓸모 있는 걸 또 알려주지! 등 긁는 데 수정을 써봤자 별 쓸모가 없다. 해보지 마라.', `MaleText_loc4`='再来听听达伊克的小建议！水晶不适合用来挠背。你最好别去尝试。', `MaleText_loc5`='達吉克的小秘訣!用水晶抓背不太好。不要試。', `MaleText_loc7`='¡Hora de recibir otro consejo inteligente de Dajik! Cristales rascar espalda demasiado bien. No intentar.' WHERE `ID`=28191;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날름이들이 가끔 수정을 캐러 오곤 한다. 우리가 놈들을 사냥하니까 지금은 오지 않는다.', `MaleText_loc4`='有时候大舌头怪会来这里采集水晶。当然，它们现在敢来的话，就是找死。', `MaleText_loc5`='有時候大舌頭會試著來拿水晶。現在不會了，因為他們不喜歡我們都會殺他們。', `MaleText_loc7`='A veces, lenguas-grandes venir a coger cristales. Ahora no porque no gustar que les matemos.' WHERE `ID`=28192;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벌레 놈들은 푸른 수정을 좋아한다. 왜 그런지는 모른다..', `MaleText_loc4`='巨峰喜欢蓝色水晶。不过达伊克不明白这是为什么。', `MaleText_loc5`='黃蜂喜歡藍水晶。達吉克不清楚為什麼。', `MaleText_loc7`='A avispas gustar cristales azules. Dajik no estar seguro de por qué.' WHERE `ID`=28193;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭔가 거대한 것이 기둥을 만들고 수정을 만들고 모든 걸 만들었다. 하지만 더는 이곳에 없으니 광란심장 일족은 별로 신경 쓰지 않는다.', `MaleText_loc4`='某个强大的存在制造了柱子、水晶以及别的东西。不过它已经不在这里了，所以我们不用害怕。', `MaleText_loc5`='有種大東西做了柱子，做了水晶，做了所有東西。狂心不太在意，因為它再也沒出現過。', `MaleText_loc7`='Algo grande hacer pilares y cristales y todo. A corazón Frenético no importar mucho porque ya no estar aquí.' WHERE `ID`=28194;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다지크가 쓸모 있는 걸 또 알려주지! 날름이의 제단을 망가트리는 게 재미있기는 하지만 놈들이 떼거리로 지켜보지는 않는지 먼저 확인해야 한다.', `MaleText_loc4`='再来听听达伊克的小建议！去大舌头怪的祭坛搅乱虽然很好玩，但是你最好别贸然冲进舌头堆。', `MaleText_loc5`='達吉克的小秘訣!惡搞大舌頭神殿很有趣，但是要先確定沒有很多大舌頭在看你。', `MaleText_loc7`='¡Hora de recibir otro consejo inteligente de Dajik! Fastidiar santuario de lenguas-grandes ser divertido, pero primero asegurar que no haber muchos lenguas-grandes mirando.' WHERE `ID`=28195;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제피크는 날름이를 아주 잘 사냥한다. 제피크 어릴 때 다지크가 가르쳐보려 했지만, 별로 효과가 없었다.', `MaleText_loc4`='瑟匹克是狩猎大舌头怪的高手。达伊克本来打算将他训练成蓝蜂猎手的，但他却选择了别的道路。', `MaleText_loc5`='賽匹克是獵大舌頭的高手，達吉克在他小的時候懶得教他，但是他現在很受教。', `MaleText_loc7`='A Zepik se le da muy bien cazar lenguas-grandes. Dajik se cansó de enseñarle cuando era pequeño, pero no era buen alumno.' WHERE `ID`=28196;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날름이는 제단에 사용할 수정을 무척 좋아한다. 우리가 그것들을 부숴버리면 싫어할 거다.', `MaleText_loc4`='大舌头怪非常宝贝那些用来供奉祭坛的水晶。我们砸碎水晶的话，它们就会发火。', `MaleText_loc5`='大舌頭很喜歡水晶拿來裝飾神殿。他們不喜歡我們敲碎水晶。', `MaleText_loc7`='A los lenguas-grandes les gustan mucho los cristales para santuario. No les gusta cuando rompemos.' WHERE `ID`=28197;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다지크는 너처럼 털 없는 자를 많이 보아 왔다. 광란심장 일족은 땅을 포기하지 않으니 조심하는 게 좋을 것이다.', `MaleText_loc4`='达伊克见过很多象你这样不长毛的家伙。狂心氏族不会放弃自己的领地，你还是小心点比较好。', `MaleText_loc5`='達吉克已經看過很多你們這種沒毛怪。狂心不喜歡放棄土地，所以你們這些傢伙最好小心點。', `MaleText_loc7`='Dajik ha estado viendo más cosas sin pelo como ustedes. Corazón Frenético no gusta entregar tierra, así que cosas como ustedes mejor tener cuidado.' WHERE `ID`=28198;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일부 털 없는 자는 날름이와 친해지기도 하더군... 다지크가 보기에는 아주 바보 같은 짓이다.', `MaleText_loc4`='有些没毛的家伙和大舌头怪成了好朋友……达伊克觉着这太傻了。', `MaleText_loc5`='有些沒毛怪已經跟大舌頭交朋友...對達吉克來說這蠢翻了。', `MaleText_loc7`='Algunas cosas sin pelaje estar haciéndose amigos de los lenguas-grandes... parece absurdo a Dajik.' WHERE `ID`=28199;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='번쩍거리는 놈들이 더 미끌댄다! 그놈들부터 잡아라!', `MaleText_loc4`='这些家伙很容易对付！先杀它们！', `MaleText_loc5`='這些活蹦亂跳的很滑溜!先抓住他們!', `MaleText_loc7`='¡Los brillantes son más fangosos! ¡Atrápalos primero!' WHERE `ID`=28200;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다지크는 내게 사냥하는 법을 가르치려 했는데, 난 내 식대로 할 때 더 잘해.', `MaleText_loc4`='达伊克一直想教我狩猎的技巧，事实上，我按自己的方式来做，效果反而更好。', `MaleText_loc5`='達吉克試著要告訴我打獵的方法，但是當我用我自己的方式做事情時，我做得比較好。', `MaleText_loc7`='Dajik intentar enseñarme a cazar, pero yo trabajar mejor a mi manera.' WHERE `ID`=28201;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋은 고기를 가져오면 그날은 야영지에서 대주술사님처럼 대접 받을 거다. 괜찮은 거래잖아.', `MaleText_loc4`='只要你能带回上等的肉，我们就把你当作高阶萨满祭司那样伺候一天。很不错的交易吧。', `MaleText_loc5`='帶回好的肉回來，營地會對待你像高階薩滿一樣，維持一天。好交易。', `MaleText_loc7`='Trae buena carne y el campamento te tratará como a un alto chamán durante un día. Buen trato.' WHERE `ID`=28202;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='닭들을 다시 풀어준 다음 고어게크가 했다고 말해. 유치하다고 생각할 거 없어.', `MaleText_loc4`='你应该把鸡们都放出来，然后说是格利基克干的。这招屡试不爽。', `MaleText_loc5`='你應該讓雞再跑出來，然後說是茍瑞格克幹的。這把戲永遠有效。', `MaleText_loc7`='Deberías dejar sueltos a los pollos otra vez y decir que lo hizo Goregek. Nunca se pasa de moda.' WHERE `ID`=28203;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇게 서두를 건 없어. 쉬고 싶으면 여기서 좀 쉬어도 괜찮아.', `MaleText_loc4`='我又不急着办什么事。我们甚至可以在这里休息一阵子。', `MaleText_loc5`='我不是很急啦，如果需要的話，我們可以在這休息一會兒。', `MaleText_loc7`='No tener demasiada prisa, poder descansar aquí un poco si querer.' WHERE `ID`=28204;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 항상 여기 머물지는 않아. 얼마 전까지도 세계 곳곳을 혼자 여행했지. 난 야수와 용족, 신과 보물 이야기를 좋아해.', `MaleText_loc4`='我很少呆在营地……不久前，我还独自游历了不少地方呢。嗯，我喜欢那些关于野兽、巨龙和神灵的传说。', `MaleText_loc5`='我並不一直住這裡...不久前，我才獨自周遊世界。我喜歡所有野獸的故事，還有龍的，神的，其他的。', `MaleText_loc7`='Yo no vivir aquí siempre... Yo viajar mucho solo no hace tanto. A mí gustar todas las historias de bestias y dragones y dioses y esas cosas...' WHERE `ID`=28205;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하르케크 장로님은 좋은 광란심장 일족이다. 내가 어릴 때 여러모로 도와주셨다. 다지크는 좋아하지 않아.', `MaleText_loc4`='长者哈尔卡克是个大好人。在我年幼的时候，他帮过我很多忙，一点也不像达伊克。', `MaleText_loc5`='長者哈爾凱克是個還不錯的狂心。在我還小、又不喜歡達吉克的時候，他幫了我很多。', `MaleText_loc7`='Anciano Harkek bastante buen Corazón Frenético. Me ayudar mucho cuando era más pequeño y no me gustaba Dajik.' WHERE `ID`=28206;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='골록은 사악한 놈들이야. 그렇게만 알고 있어.', `MaleText_loc4`='如你所知，鳄鱼人都是大坏蛋。', `MaleText_loc5`='戈洛克是壞人，你現在知道了。', `MaleText_loc7`='Los górlocs son los malos, para que lo sepas.' WHERE `ID`=28207;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네게 저 날름이들을 없애버릴 비밀스러운 계획이 있는 거라면 좋겠어.', `MaleText_loc4`='希望你正在计划消灭大舌头怪的秘密方案。', `MaleText_loc5`='我希望你正在策劃什麼秘密，包括了要怎麼讓大舌頭以死掉收場。', `MaleText_loc7`='Espero que estés tramando algún plan secreto que implique que ese lengua-grande acabe muerto.' WHERE `ID`=28208;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='만약 내가 꼬리를 밟는다면 그건 사고야.', `MaleText_loc4`='如果我踩到它的尾巴，那绝对是个意外。', `MaleText_loc5`='如果我踩到牠的尾巴，那一定是意外。', `MaleText_loc7`='Si le piso la cola, habrá sido un accidente.' WHERE `ID`=28209;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보통은 난 이놈들 끝장내버려. 너도 알잖아, 안 그래?', `MaleText_loc4`='通常我都是直接杀掉这些家伙的。你知道的，对吧？', `MaleText_loc5`='一般來說，我會殺掉那些傢伙。你曉得的，對吧?', `MaleText_loc7`='Normalmente mato estas cosas. Lo sabes, ¿verdad?' WHERE `ID`=28210;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날름이들이랑 여행하는 거 정말 싫어.', `MaleText_loc4`='我讨厌和大舌头怪同行。', `MaleText_loc5`='要我跟大舌頭一道旅行讓我不是很開心。', `MaleText_loc7`='No gustarme mucho eso de viajar con lenguas-grandes.' WHERE `ID`=28211;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 어떻게 하는지 봤어... 그 녀석 잘 다룬다면 날름이들이 더 많이 있는 곳으로 안내해줄지도 몰라.', `MaleText_loc4`='我知道你想干什么……如果我们好好待它，说不定它会带我们去找更多的大舌头怪。', `MaleText_loc5`='我看到你做了什麼...如果我們對它好，它會帶我們去找更多的大舌頭。', `MaleText_loc7`='Veo lo que estás haciendo... si somos amables, quizá nos guíe hasta más lenguas-grandes.' WHERE `ID`=28212;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카르탁에게 접근하지 않는 게 좋아. 녀석은 배가 부른 동안은 광란심장 일족들하고만 친구하니까... 게다가 녀석의 배는 엄청나게 크지.', `MaleText_loc4`='最好离卡塔克远点。他只会在吃饱喝足的时候将狂心狼獾人视为朋友……你要明白，他的胃口简直像个无底洞。', `MaleText_loc5`='和卡爾塔克保持距離比較好。只有我們讓他填飽肚子的情況下，他才是狂心的朋友...他有個很大的肚子。', `MaleText_loc7`='Bueno mantenerse alejado de Kartak. Él solo amigo de Corazón Frenético mientras panza estar llena... y tener panza muy grande.' WHERE `ID`=28213;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 이곳에서 날름이들을 사냥하는 법을 스스로 터득했어. 사냥할 놈들이 많아.', `MaleText_loc4`='我在这里掌握了许多狩猎大舌头怪的技巧。它们的数量很多，完全可以用来练习。', `MaleText_loc5`='我親自在這教導過許多大舌頭的狩獵。殺了一堆。', `MaleText_loc7`='Yo aprender la gran parte de mi caza de lenguas-grandes aquí. Mucho que matar.' WHERE `ID`=28214;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투에서 나는 소리 때문에 난 언덕보다 이곳이 더 편안하게 느껴져.', `MaleText_loc4`='听着激烈的厮杀搏斗声，远比待在营地舒畅啊。', `MaleText_loc5`='這些戰場的聲響讓這個地方比主要山丘還要更讓人放鬆。', `MaleText_loc7`='El sonido de la batalla tiene algo que hace que este lugar sea más relajante que la colina principal.' WHERE `ID`=28215;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='길게 얘기할 것도 없이, 카르탁은 "친구"가 되기 전에 광란심장 일족을 많이 잡아먹었지.', `MaleText_loc4`='在卡塔克成为我们的“朋友”之前，他吃掉了很多狂心狼獾人。这件事很少有人提及。', `MaleText_loc5`='雖然沒有多提到這點，不過卡爾塔克是先吃掉了好幾打的狂心之後才變成「朋友」的。', `MaleText_loc7`='No muy mencionado, pero Kartak comió doce Corazones Frenéticos antes de volverse "amigo".' WHERE `ID`=28216;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타르텍 만난 적 있어? 그는 북쪽으로 떠난... 우리 최고 전사 중 하나야. 소문을 듣자하니 그가 용 무언가를 한 마리 잡은 모양이더군. 솔직히 말해 조금 질투가 나.', `MaleText_loc4`='你见过塔尔特克吗？他是氏族最优秀的战士之一……他统领着西北部的土地。我听说他还捕获过龙。说实话，我有点嫉妒他。', `MaleText_loc5`='見過塔提克了嗎?他是我們最厲害的戰士...在西北邊領導我們。我聽說他逮到了一頭龍什麼的。沒騙你，害我好羨慕。', `MaleText_loc7`='¿Has conocido a Tartek? Él uno de nuestros mejores luchadores... líderes en el noroeste. He oído que capturó a una de las cosas dragones. No miento, yo un poco celoso.' WHERE `ID`=28217;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주술사 자크제크는 광란심장 일족치고 과묵한 편이지만 그래도 매우 강해. 카르탁이 우리를 더는 공격하지 않는 유일한 이유라고도 할 수 있지.', `MaleText_loc4`='就狂心狼獾人来说，萨满祭司亚克耶克显得安静了些，但是他拥有强大的力量。这或许是卡塔克不敢肆意妄为的唯一禁忌。', `MaleText_loc5`='薩滿賈克杰克對狂心來說很安靜，但是他還是很強大。他大概就是為什麼卡爾塔克不會回頭對付我們的原因。', `MaleText_loc7`='Chamán Jakjek ser bastante tranquilo para ser un Corazón Frenético, pero aun así muy fuerte. Probablemente ser la única razón por la que Kartak no atacar a más de nosotros.' WHERE `ID`=28218;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 종족은 무너진 기둥에서 환영하지 않아. 언덕으로 돌아가겠어. 일을 마치면 나를 찾아줘.', `MaleText_loc4`='破柱子不欢迎狼獾人。我要回去了，你把事情办完之后再来找我吧。', `MaleText_loc5`='我的族人在斷掉的柱子那邊不受歡迎。我會回去山丘那 - 你完成以後回來找我。', `MaleText_loc7`='Mi gente no es bienvenida en Pilar Partido. Vuelvo a la colina, búscame cuando hayas acabado.' WHERE `ID`=28219;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무너진 기둥에서 광란심장 일족을 많이 잃었어. 이 제피크가 그렇게 될 날은 오늘이 아니야.', `MaleText_loc4`='许多狂心狼獾人都在破柱子附近失踪了。今天不会轮到瑟匹克吧。', `MaleText_loc5`='許多狂心在斷掉的柱子那邊失蹤了。今天可不是賽匹克失蹤的日子。', `MaleText_loc7`='Muchos Corazón Frenético perdidos en Pilar Partido. Hoy no ser el día en que Zepik perderse también.' WHERE `ID`=28220;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날름이를 이쪽으로 유인하는 방법을 생각해 봤는데 나한테는 너무 위험해. 넌 운이 좋은 놈이니 언덕에서 만나겠어.', `MaleText_loc4`='我想过设局把大舌头怪骗来这里，但对我来说这太危险了。那么，祝你好运，我们营地见。', `MaleText_loc5`='我想過戲弄大舌頭來這裡，但是對我來說太危險了。你的運氣比較好，我們在山丘見。', `MaleText_loc7`='Pensé engañar a lenguas-grandes para venir aquí, pero demasiado peligroso para mí. Tú tener buena suerte y yo verte después en colina.' WHERE `ID`=28221;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 오는 건 좋은 생각이 아니야... 이 곳에서 닥칠 위험을 감수하기 전에 모험을 더 겪어봐야 했는데. 조심해... 나중에 다시 만나.', `MaleText_loc4`='真不该来这里……我还有很多冒险计划呢，干嘛要来这个鬼地方玩命。小心点……我们待会见。', `MaleText_loc5`='來這可不是什麼好主意...我冒險來這個地方以前，還有很多冒險等著我呢。保險起見...我們晚點見。', `MaleText_loc7`='Mala idea venir aquí... tengo que correr muchas más aventuras antes de atreverme con este lugar. Mantente a salvo... te veré luego.' WHERE `ID`=28222;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하! 저거 봤어? 벼락이 머리에 정통으로 꽂혔어!', `MaleText_loc4`='哈哈哈！你看见没有？闪电直接击中了他！', `MaleText_loc5`='哈哈!你看到了沒?閃電箭打到他腦門!', `MaleText_loc7`='¡Jajaja! ¿Tú ver eso? ¡Rayo golpear justo en cabeza!' WHERE `ID`=28223;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꽝! 아주 좋아! 좀 더! 좀 더!', `MaleText_loc4`='砰！真棒！再来！再来！', `MaleText_loc5`='碰!好棒呀!再來!再來!', `MaleText_loc7`='¡BOOM! ¡Qué bien! ¡Más! ¡Más!' WHERE `ID`=28224;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해치워!', `MaleText_loc4`='咝！', `MaleText_loc5`='唰!', `MaleText_loc7`='¡Zap!' WHERE `ID`=28225;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거 좀 더 자주 해야겠어! 번개가 사방에서 날름이들을 때리다니... 너무 재미있잖아!', `MaleText_loc4`='我们以后还要来玩这个！太有趣啦……闪电把大舌头怪打得抱头鼠窜！', `MaleText_loc5`='我們得更頻繁做這事!這很好玩...閃電打在大舌頭身上到處都是!', `MaleText_loc7`='¡Tenemos que hacer esto más a menudo! Es tan divertido...' WHERE `ID`=28226;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 주변 호수에는 바다 생물이 잔뜩 살고 있어. 어떻게 흘러든 건지 모르겠네... 물살에 떠밀려 온 건가?', `MaleText_loc4`='附近的湖里全是海洋生物。不知道是怎么来的……莫非是洪水？', `MaleText_loc5`='這附近的那座湖滿滿都是海裡的東西。我不清楚牠們是怎麼進去的啦...也許是因為淹水?', `MaleText_loc7`='Ese lago de aquí cerca está lleno de cosas marinas. No estoy seguro de cómo llegan... ¿igual con las inundaciones?' WHERE `ID`=28227;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 왜 날름이 사냥을 좋아하는지 곰곰이 생각해 봤지... 다른 사냥감처럼 멍청하지 않아. 제대로 싸울 수 있거든.', `MaleText_loc4`='我喜欢狩猎大舌头怪的原因之一……就是它们不像其他猎物那样愚蠢。懂得耍花招的猎物才是真正的挑战。', `MaleText_loc5`='我想只有一個原因為什麼我那麼喜歡獵殺大舌頭...他們跟跟其他的獵物比起來沒那麼笨。他們讓我們全力以赴。', `MaleText_loc7`='Creo que un motivo por el que gustarme tanto matar lenguas-grandes... no ser tan tontas como otras presas. Pelean de verdad.' WHERE `ID`=28228;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안개 날름이들은 가끔 제단인지 무엇인지 옆에 있으면 똑똑해져... 사방이 안개로 뒤덮이면 놈들을 찾기가 쉽지 않아.', `MaleText_loc4`='雾语大舌头怪很会利用那些祭坛捣鬼……它们能让迷雾覆盖整片区域，令我们难以发现它们的行踪。', `MaleText_loc5`='迷霧大舌頭常常很會力用它們的神殿...把整個地方都布滿了霧，很難找到他們。', `MaleText_loc7`='Lenguas-grandes de la niebla ser inteligentes con su santuario a veces... cubrir toda la zona con niebla y ser difícil encontrarlos.' WHERE `ID`=28229;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='덩치 큰 안개부름이 녀석을 조심해... 제피크는 놈과 싸운 적이 있는데 거의 죽을 뻔했어. 놈은 여기 있는 다른 날름이들보다 훨씬 강해.', `MaleText_loc4`='小心那只大个子的唤雾者……瑟匹克曾和他打过一次，根本不是他的对手，只能狼狈地逃掉了。他远比其他的大舌头怪厉害。', `MaleText_loc5`='小心大喚霧者傢伙...賽匹克和他打鬥差點逃不走。他比這裡剩下的大舌頭強得多。', `MaleText_loc7`='Cuidado con el gran clamaneblina ese... Zepik luchó contra él una vez y casi no lo cuenta. Mucho más fuerte que resto de lenguas-grandes aquí.' WHERE `ID`=28230;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대단한 사냥감은 아닐지 몰라도, 몇 번 하다 보면 재미있을 거야.', `MaleText_loc4`='这算不上什么伟大的狩猎，但是玩过很多次之后我仍然觉得非常有趣。', `MaleText_loc5`='也許不是什麼偉大狩獵，但是經過這麼多次之後，也還滿好玩的。', `MaleText_loc7`='Quizá no ser gran caza, pero aún ser divertido después de tanto tiempo.' WHERE `ID`=28231;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고어게크를 닭 근처에 못가게 하는 방법을 그들이 배웠다고 생각하는 거야?', `MaleText_loc4`='你觉得他们会吸取教训，不许格利基克靠近鸡舍？', `MaleText_loc5`='你覺得他們學到了該讓茍瑞格克離雞遠點。', `MaleText_loc7`='Tu pensar que ellos haber aprendido a mantener a Goregek alejado de los pollos.' WHERE `ID`=28232;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고어게크는 절대로 닭장에 "걸려 넘어지는" 게 아니야. 그놈은 항상 멍청한 배를 채우려 들어. 닭을 다 잡고 보면 꼭 한 마리가 빈단 말이지.', `MaleText_loc4`='格利基克才不会错过抓鸡活动呢……格利基克得填饱他的肚子。每次抓完鸡，我们都会发现有一只鸡不见了。', `MaleText_loc5`='茍瑞格克從來沒有「搞錯」走進雞籠裡...茍瑞格克總是得填飽他的笨肚子。當我們把所有的雞抓起來之後，就會發現少一隻。', `MaleText_loc7`='Goregek nunca "tropezar" con caseta de pollos... Goregek tiene que alimentar su estúpida barriga. Siempre falta un pollo cuando los atrapamos.' WHERE `ID`=28233;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='닭이 생각했던 것보다 고분고분하지 않잖아! 무언가 대책을 마련해야겠어!', `MaleText_loc4`='这些鸡比我想象中难对付！我不该掉以轻心的！', `MaleText_loc5`='你們這些雞比我想像的還厲害!我必須隨機應變!', `MaleText_loc7`='¡Tus pollos ser más duros de los que yo pensar! ¡Tendré que improvisar!' WHERE `ID`=28234;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쓸만하군! 타고난 사냥꾼이야. 나처럼 말이지.', `MaleText_loc4`='技术不错嘛！狩猎手法和我一样纯熟自然。', `MaleText_loc5`='你棒透了!天生就會打獵，跟我一樣。', `MaleText_loc7`='¡Tú bastante bueno! Caza ser lo tuyo, como yo.' WHERE `ID`=28235;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고어게크는 자기가 대장이라고 생각하지만... 엄청나게 먹기만 할 뿐, 사냥은 쥐꼬리만큼 해와.', `MaleText_loc4`='格利基克总是摆出一副高高在上的模样，但这家伙每天吃那么多，打回来的猎物却少得可怜。', `MaleText_loc5`='茍瑞格克覺得他是大家的頭頭，但是他吃得太多，卻沒怎麼在打獵。', `MaleText_loc7`='Goregek creer que ser el jefe de todos, pero comer demasiado y cazar muy poco.' WHERE `ID`=28236;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다지크는 자기가 뭘 하는지, 어디 있는지 잊어버려... 자기 이름도 기억 못 할걸. 그러니 별로 좋은 스승은 못 되지.', `MaleText_loc4`='达伊克经常会忘记他在做什么，忘记他在哪儿……甚至会忘记自己的名字。有时候，他还真算不上是个好老师。', `MaleText_loc5`='達吉克忘了他在幹什麼，在哪裡...有時候連他的名字都忘了。這讓他有時候不是個稱職的老師。', `MaleText_loc7`='Dajik olvidado qué hace, dónde... a veces olvida hasta su nombre. Eso hacer que no sea buen profesor en ocasiones...' WHERE `ID`=28237;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용이나 신이나 뭐 그런 것들이랑 싸워본 적 있어? 제피크는 이야기 듣는 거 좋아해.', `MaleText_loc4`='你有没有跟巨龙、神灵或者别的什么打过架啊？瑟匹克最喜欢听故事啦。', `MaleText_loc5`='你有跟大龍或是神或是什麼的打過架嗎?賽匹克喜歡聽故事。', `MaleText_loc7`='¿Alguna vez haber luchado contra gran dragón, o dios, o algo? A Zepik gustar oír historias.' WHERE `ID`=28238;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 한 놈 잡았어! 그놈은 무슨 일이 일어났는지도 모르나봐.', `MaleText_loc4`='干得好！它一点也没有察觉。', `MaleText_loc5`='做的好!他連靠近都沒辦法。', `MaleText_loc7`='¡Muy Buena! Ni verla venir.' WHERE `ID`=28239;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런! 이 제피크가 할 일도 좀 남겨 달라고.', `MaleText_loc4`='哈哈！给瑟匹克留点猎物吧。', `MaleText_loc5`='哈!留一點給賽匹克。', `MaleText_loc7`='¡Ja! Deja algo para Zepik también.' WHERE `ID`=28240;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 그만 놀아?', `MaleText_loc4`='不玩了？', `MaleText_loc5`='不玩了嗎?', `MaleText_loc7`='¿No jugamos más?' WHERE `ID`=28241;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불! 파괴! 죽음! 내 가슴 속에 검은 불길이 끓고 있다! ...내뿜어야만 해! 우하하!', `MaleText_loc4`='烈焰！死亡！毁灭！黑色的火焰在我心中燃烧！我必须……释放它！哈哈哈！', `MaleText_loc5`='火焰!死亡!毀滅!黑色的火焰在我的內心翻滾!我可得...釋放出來!哈哈!', `MaleText_loc7`='¡Llama! ¡Muerte! ¡Destrucción! ¡El fuego negro arde en mi corazón! ¡Debo... liberarlo! ¡Jajaja!' WHERE `ID`=28242;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알아챘는지 모르겠지만, 커다란 구덩이에 고인 물에서 뭔가 튀어오르네. 저 아래에 뭔가 있는 게 틀림없어.', `MaleText_loc4`='你有没有发现，洞穴中有时会传来隆隆声。一定有什么生物潜伏在里面。', `MaleText_loc5`='不曉得你有沒有注意到，但是大洞裡的水底有時候會發出轟隆隆的聲音。我想那下面應該有什麼東西在。', `MaleText_loc7`='No estar seguro si darte cuenta, pero, a veces, escuchar ruido del agua en el gran agujero. Yo creer que haber algo allí abajo.' WHERE `ID`=28243;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날름이들은 이제 이곳에 내려오지 않아... 난 큰 싸움을 치렀고 많이 죽였거든.', `MaleText_loc4`='大舌头怪通常不敢来这里……我曾在这里和它们交过手，杀死了很多大舌头怪。', `MaleText_loc5`='大舌頭不再下來...我曾大戰一場殺掉好多。', `MaleText_loc7`='Los lenguas-grandes ya no suelen bajar aquí... Tuve una gran bronca y maté a muchos.' WHERE `ID`=28244;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 물이 전부 어디로 흘러가는지 항상 궁금했는데... 말도 안 되잖아.', `MaleText_loc4`='我很想知道水都流到哪儿去了……真搞不明白。', `MaleText_loc5`='我總是疑惑水跑哪裡去了...一點也不合理。', `MaleText_loc7`='Siempre preguntarme dónde ir toda el agua... no tener sentido.' WHERE `ID`=28245;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='베크지크는 멀리까지 헤매다 분지에 들어간 날름이 찾아내는 걸 좋아해. 덫을 놓아 멍청한 놈들을 잡는 법을 가르쳐 줬어. 나중에 어떻게 하는지 꼭 봐... 사실 정말 재미있거든.', `MaleText_loc4`='维克伊克最喜欢找那些在盆地里迷路的大舌头怪的麻烦。他帮我用陷阱抓过好几只愚蠢的家伙。你可以去瞧瞧他是怎么做的……很有趣。', `MaleText_loc5`='維克吉克喜歡找出遊蕩太遠沒辦法丟進盆地裡的大舌頭。他幫我用陷阱補到這些笨傢伙。你應該親眼去看...這事實上還滿有趣的。', `MaleText_loc7`='A Vekjik gustar buscar lenguas-grandes que alejarse demasiado para echar a la cuenca. Me ayuda a atrapar a algunos de los tontos. Deberías observarle alguna vez... ser bastante divertido.' WHERE `ID`=28246;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싸움이 제법 오래가네... 이 번개 날름이들은 다른 놈들보다 노련해.', `MaleText_loc4`='冲突已经持续好一阵子了……这里的大舌头怪似乎很有斗志。', `MaleText_loc5`='這場戰爭在這發生一段時間了...這些火光大舌頭比其他的更能打。', `MaleText_loc7`='La batalla aquí dura ya un tiempo... estos lenguas-grandes pavesa son más duros que los demás.' WHERE `ID`=28247;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳의 날름이들은 다른 데 있는 놈들처럼 제단을 섬기는데, 이 제단은 가끔 지키는 수호자가 있기도 해. 수호자가 보이면 조심해.', `MaleText_loc4`='这里的大舌头怪也供奉祭坛，但这座祭坛有一个守护者。如果它出现的话，你就要当心。', `MaleText_loc5`='這裡的大舌頭祭拜神殿，就像在其他地方一樣，但是這些神殿有時候有守護者。要是出現的話，小心點。', `MaleText_loc7`='Los lenguas-grandes aquí rendir culto en santuario, como en otros lugares, pero este santuario a veces tiene guardián. Cuidado si aparece.' WHERE `ID`=28248;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청하지 않은 사냥꾼과 함께 사냥하면 기분 좋아. 너는 소질이 있어.', `MaleText_loc4`='跟一个聪明的猎手一起狩猎，感觉真是不错。你很擅长狩猎嘛。', `MaleText_loc5`='跟一個不笨的獵人一起打獵真好。你真行。', `MaleText_loc7`='Es agradable cazar con un cazador no tonto. Dársete bien esto.' WHERE `ID`=28249;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 날름이들이 두려워하는 게 나만은 아닐 듯해. 싸울 때 너는 무시무시하거든.', `MaleText_loc4`='或许我不再是大舌头怪唯一害怕的强者了。你打斗的样子也很吓人。', `MaleText_loc5`='也許我不再是唯一一個大舌頭害怕的人。你打架的時候也很嚇人。', `MaleText_loc7`='Igual, dentro de poco, no ser yo el único al que temer lenguas-grandes. Tu dar miedo cuando luchar.' WHERE `ID`=28250;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야영지에 온 걸 환영하네, $c|1이여;여;.', `MaleText_loc4`='欢迎来到营地，$c。', `MaleText_loc5`='歡迎來到崗哨，$c。', `MaleText_loc7`='Te doy la bienvenida al campamento, $c.' WHERE `ID`=28251;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코르부스에게 무슨 볼일이오?', `MaleText_loc4`='科弗斯能为你提供什么服务？', `MaleText_loc5`='你需要從寇孚斯那兒拿些什麼?', `MaleText_loc7`='¿Qué necesitas de Corvus?' WHERE `ID`=28252;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수리와 보급이 필요합니다, 코르부스.', `MaleText_loc4`='我需要修理装备和购买物资，科弗斯。', `MaleText_loc5`='我需要修理裝備和補給品供給，寇孚斯。', `MaleText_loc7`='Necesito reparaciones y suministros, Corvus.', `FemaleText_loc1`='수리와 보급이 필요해요, 코르부스.', `FemaleText_loc4`='我需要修理装备和购买物资，科弗斯。', `FemaleText_loc5`='我需要修理裝備和補給品供給，寇孚斯。', `FemaleText_loc7`='Necesito reparaciones y suministros, Corvus.' WHERE `ID`=28253;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한번에 여러 적을 상대할 때는 불타는 격노를 사용하고, 내가 공격을 받기 시작하면 교묘한 회피를 사용하라. 단, 교묘한 회피를 사용하려면 먼저 공격을 받아 회피력을 충전해야 한다는 것을 기억해 두어라!', `MaleText_loc4`='使用灼热之怒对敌人造成伤害；如果我开始承受伤害，就使用闪避机动。记住，我必须以承受伤害的方式积攒闪避能量，才能使用闪避机动！', `MaleText_loc5`='如果我受到傷害，使用灼熱之怒去傷害敵人和迴避動作。記得我需要藉由受到傷害累積迴避能量，才能使用迴避動作!', `MaleText_loc7`='Para dañar a los enemigos utiliza Cólera abrasadora y si empiezo a recibir daño, usa Maniobras evasivas. ¡Recuerda que para poder usar las Maniobras evasivas debo acumular Cargas evasivas al recibir daño!' WHERE `ID`=28254;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적에 피해를 주면서 동시에 날 지속적으로 회복시키려면 착취 독을 사용하라. 악몽 접근 기술은 매우 강력하지만, 나에게까지 피해가 오니 내 체력이 많을 때만 사용해야 한다!', `MaleText_loc4`='使用吸血之毒对敌人造成伤害，同时保持对我的治疗。噩梦之触非常强大，但会对我造成伤害，所以只能在我的生命值较高的情况下使用！', `MaleText_loc5`='使用吸血之毒傷害敵人以維持我的治療。夢魘之觸非常強大，但是會傷害我，因此只在我還有很多生命力的時候使用!', `MaleText_loc7`='Usa el Veneno parasitante para dañar a los enemigos y mantenerme sano. Tocar la pesadilla es muy poderoso, pero me hace daño, ¡así que úsalo solo cuando tenga mucha salud!' WHERE `ID`=28255;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적에 피해를 주려면 충격의 창을 사용하라. 위험에 처하면 시간 정지를 사용해 모든 적을 그 자리에 멈추게 하여 충격의 창으로 어마어마한 피해를 주어라!', `MaleText_loc4`='使用震击之枪对敌人造成伤害。如果我们遇到麻烦，就使用停止时间将敌人冻结，然后使用震击之枪对他们造成大量伤害！', `MaleText_loc5`='使用震擊之槍傷害敵人，如果我們陷入危機，暫停時間將所有敵人凍結在原地，接著用震擊之槍攻擊他們造成大量傷害!', `MaleText_loc7`='Usa la Lanza de choque para dañar a los enemigos. Si nos metemos en problemas, Parar tiempo congelará en su sitio a todos los enemigos, ¡entonces dales con la Lanza de choque para hacer mucho daño!' WHERE `ID`=28256;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부상이 심각하다! 더는 버티지 못하겠노라!', `MaleText_loc4`='我伤得很重！我无法承受更多的伤害了！', `MaleText_loc5`='我受了重傷!我撐不下去了!', `MaleText_loc7`='¡Estoy malherido! ¡No podré soportarlo mucho más!' WHERE `ID`=28257;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 힘이 최고조에 달한 지금이라면 시간의 균열을 사용할 수 있도다. 그걸 사용해 적들에게 더 큰 피해를 주고 충격 충전을 얻을 수 있으리라. 충격 충전을 모아 충격의 창을 사용하면 큰 피해를 줄 수 있노라!', `MaleText_loc4`='我已经具备全部力量，可以使用时间裂隙了。你能利用它对敌人造成额外的伤害并获得震击能量。积攒足够的能量后，再使用震击之枪造成大量伤害！', `MaleText_loc5`='既然我處於能量全滿的狀態，我可以施展時光裂隙。你可以使用它來對敵人造成額外的傷害，並且獲得震擊能量。存蓄震擊能量並接著使用震擊之槍來造成巨大傷害!', `MaleText_loc7`='Ahora que tengo todo mi poder, puedo utilizar Falla temporal. Puedes usarlo para hacer que los enemigos sufran daño adicional y conseguir Cargas de choque. ¡Guárdalas y después usa la Lanza de choque para hacer un daño enorme!' WHERE `ID`=28258;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 힘이 최고조에 달한 지금이라면 꿈의 집중을 사용할 수 있도다. 그걸로 다른 비룡들을 치료할 수 있지만, 내 체력도 닳게 되므로 착취 독과 함께 사용하는 것을 잊지 말아라!', `MaleText_loc4`='我已经具备全部力量，可以使用梦境通道了。你能利用它治疗其他幼龙，但这个技能会消耗我的生命值，因此必须与吸血之毒配合使用！', `MaleText_loc5`='既然我處於能量全滿的狀態，我可以施展夢境通道。你可以使用它來治療其他飛龍，但是吸取我的生命力，所以確保同樣要使用吸血之毒!', `MaleText_loc7`='Ahora que tengo todo mi poder, puedo utilizar Cauce de sueño. Puedes emplearlo para sanar a otros dracos, pero drena mi salud, ¡así que asegúrate de que también usas el Veneno parasitante!' WHERE `ID`=28259;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 힘이 최고조에 달한 지금이라면 희생을 사용할 수 있도다. 이것을 사용해 다른 비룡들을 보호할 수 있지만, 내가 집중 공격을 받게 될 테니 꼭 교묘한 회피와 함께 사용하여라.', `MaleText_loc4`='我已经具备全部力量，可以使用殉难了。你能利用它保护其他幼龙，但这会让我承受大量伤害，因此必须与闪避机动配合使用！', `MaleText_loc5`='既然我處於能量全滿的狀態，我可以施展殉節。你可以使用它來保護其他飛龍，但是會讓我受到大量傷害，所以確保同樣要使用迴避動作!', `MaleText_loc7`='Ahora que tengo todo mi poder puedo realizar Mártir. Puedes usarlo para proteger a otros dracos, pero yo recibiré mucho daño, ¡así que asegúrate de usar Maniobras evasivas también!' WHERE `ID`=28260;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오! 반짝이 발견!', `MaleText_loc4`='噢！闪闪发亮的宝贝！', `MaleText_loc5`='唔!亮閃閃的東西!', `MaleText_loc7`='¡Ooh! ¡Cositas brillantes!' WHERE `ID`=28261;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라푸 보물이다! 제단에 바칠 보물이다!', `MaleText_loc4`='拉弗乌的宝藏！祭坛的宝藏！', `MaleText_loc5`='拉富的寶藏!神殿的寶藏!', `MaleText_loc7`='¡Tesoro para Lafoo! ¡Tesoro para santuario!' WHERE `ID`=28265;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파자, 파자, 파자...', `MaleText_loc4`='我挖，我挖，我挖……', `MaleText_loc5`='挖呀，挖呀，挖呀...', `MaleText_loc7`='Cavar, cavar, cavar...' WHERE `ID`=28266;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛나는 반짝이 더 있을 거야! 우리는 반짝이 좋아해!', `MaleText_loc4`='没准还有更多闪闪发亮的虫虫！我们爱虫虫！', `MaleText_loc5`='也許會有更多閃亮蟲!我們喜歡蟲!', `MaleText_loc7`='¡Igual más bichos brillantes! ¡A nosotros gustar bichos!' WHERE `ID`=28267;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크고 무서운 짐승 조심해! 그놈 우리를 잡아먹으려 해!', `MaleText_loc4`='当心那只大怪兽！它会吃掉我们！', `MaleText_loc5`='小心又大又恐怖的怪獸!牠要吃掉我們!', `MaleText_loc7`='¡Cuidado con temible cosa bestia grande! ¡Intentar comernos!' WHERE `ID`=28268;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여긴 하룻강아지가 많네. 저놈들 지금 친구가 되고 싶은 가봐?', `MaleText_loc4`='这里好多狗狗人啊。或许他们想和我们交朋友？', `MaleText_loc5`='這裡好多小狗人。我想他們說不定想要當朋友了?', `MaleText_loc7`='Tantos hombres cachorro aquí. ¿Creer que igual quieren ser amigos?' WHERE `ID`=28269;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 저기, 지금 가면 안 돼? 좀 무서워.', `MaleText_loc4`='我们离开这里好不好啊？我有点害怕。', `MaleText_loc5`='我們可以，也許，走了嗎?有點恐怖。', `MaleText_loc7`='¿Podríamos, quizá, irnos ya? Un poco de miedo.' WHERE `ID`=28270;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여긴 벌레 없네... 전부 어디로 가는 거지?', `MaleText_loc4`='这里没有虫虫……虫虫都到哪里去了呢？', `MaleText_loc5`='這裡沒有蟲...蟲都哪去了呢?', `MaleText_loc7`='No bichos aquí... ¿adónde ir todos bichos?' WHERE `ID`=28271;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나빠. 여기 좋지 않아. 나빠 나빠 나빠.', `MaleText_loc4`='不好玩。这里不好玩。', `MaleText_loc5`='不，這裡不好，不，不，不。', `MaleText_loc7`='No. Aquí no bueno. No, no, no.' WHERE `ID`=28272;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='목소리... 목소리가 사방에 있는데 살아 있지 않아! 여기 있지 말자.', `MaleText_loc4`='声音……到处都能听见，是幽灵！快跑呀！', `MaleText_loc5`='聲音...到處都是聲音，可是都不是活著的!不要待這裡。', `MaleText_loc7`='Voces... ¡voces por todas partes y no vivas! No quedarse.' WHERE `ID`=28273;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벌레들이 전부 사라졌어. 여기는 나쁨 그 자체야... 우리는 나쁜 것들이랑 안 놀아.', `MaleText_loc4`='虫虫都不见了。这里是个坏地方……我们不要呆在这里。', `MaleText_loc5`='所有的蟲都不見了。這裡的壞事...我們不該發生壞事的。', `MaleText_loc7`='Todos los bichos se han ido. Maldad aquí... nosotros no estar con maldad.' WHERE `ID`=28274;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 진짜 싫어. 너 일 다하고 우리 찾으러 와.', `MaleText_loc4`='我们不喜欢这里。要不你办完事之后再来找我们。', `MaleText_loc5`='我們真不喜歡這裡。也許等你完成以後再來找我們好了。', `MaleText_loc7`='Este sitio no gustarnos de verdad. Igual venir a buscarnos cuando tú acabar.' WHERE `ID`=28275;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 끔찍한 뱀 자식아, 새끼들을 먹지 마!', `MaleText_loc4`='大坏蛇，你再也别想吃掉幼体了！', `MaleText_loc5`='恐怖蛇東西，不准再吃寶寶了!', `MaleText_loc7`='¡No comer más crías, cosa serpiente que da miedo!' WHERE `ID`=28276;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번엔 절대로 돌아오지 마!', `MaleText_loc4`='它再也不能来捣乱啦！', `MaleText_loc5`='不要在這時候回來!', `MaleText_loc7`='¡No habrá piedad esta vez!' WHERE `ID`=28277;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너 좀 세구나! 야호... 네가 우리 지켜줬어!', `MaleText_loc4`='你很强！呀……你能保护我们！', `MaleText_loc5`='你真強!耶...你讓我們安然無恙!', `MaleText_loc7`='¡Tú fuerte! Sí... ¡tú mantenernos a salvo!' WHERE `ID`=28278;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쉿... 쉿... 죽었어. 완전히 죽었어.', `MaleText_loc4`='嘶嘶……嘶嘶……死了。都死了。', `MaleText_loc5`='他...他...死了，全死了。', `MaleText_loc7`='Essstá... esssstá... muerto. Muerto del todo.' WHERE `ID`=28279;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벌레 먹이다!', `MaleText_loc4`='有东西喂虫虫吃啦！', `MaleText_loc5`='蟲飼料來囉!', `MaleText_loc7`='¡Comida para bichos!' WHERE `ID`=28280;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그거 아프겠다. 우린 그렇게 때리지 마. 응?', `MaleText_loc4`='它好像受了重伤。别像那样对待我们，好不好？', `MaleText_loc5`='那看起來很痛。不要像那樣打我們，行嗎?', `MaleText_loc7`='Eso tener pinta de doler. No pegar a nosotros así, ¿vale?' WHERE `ID`=28281;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보니까... 그거 죽은 거 같아.', `MaleText_loc4`='我想……它大概是死了。', `MaleText_loc5`='我想...它大概死了。', `MaleText_loc7`='Creo que... igual muerto.' WHERE `ID`=28282;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아! 이제 진짜 안 위험해?', `MaleText_loc4`='啊啊！看来安全了？', `MaleText_loc5`='啊!它們都獲救了嗎?', `MaleText_loc7`='¡Aah! ¿Todo a salvo ahora?' WHERE `ID`=28283;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어라, 안녕. 너 누구? 친구 할래?', `MaleText_loc4`='嗨。你是谁？我们来做好朋友吧？', `MaleText_loc5`='喔，嗨，你誰啊?想要交朋友嗎?', `MaleText_loc7`='Oh, hola. ¿Quién tú? ¿Querer ser amigos?' WHERE `ID`=28284;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여긴 눈이 안 와서 좋아. 눈은 나빠.', `MaleText_loc4`='这里不下雪真是太好啦。我讨厌下雪！', `MaleText_loc5`='幸好這裡不下雪。下雪不好。', `MaleText_loc7`='Está bien que no nevar aquí. Nieve no buena.' WHERE `ID`=28285;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 눈알 진짜 웃겨.', `MaleText_loc4`='你的眼珠看起来好有趣。', `MaleText_loc5`='你的眼球看起來很好笑。', `MaleText_loc7`='Tú tener ojos raros.' WHERE `ID`=28286;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽은 것들은 아주 슬퍼 보여.', `MaleText_loc4`='这些死了的家伙似乎……不太高兴。', `MaleText_loc5`='死掉的東西看起來不太開心。', `MaleText_loc7`='Las cosas muertas no parecen muy felices.' WHERE `ID`=28287;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아! 불쌍한 척 하는 네 표정 싫어! 너무 야비해!', `MaleText_loc4`='啊啊啊！我讨厌狗狗人！太坏了！', `MaleText_loc5`='啊!我討厭你們這些小狗臉!好壞喔!', `MaleText_loc7`='¡Aah! ¡Yo odiar a ti, cara de perro! ¡Muy malo!' WHERE `ID`=28288;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위대한 자들 만나본 적 없어. 없다고. 그냥 제단만 봤어.', `MaleText_loc4`='我没有见过造物主。真的，只见过他们留下的祭坛。', `MaleText_loc5`='從沒見過諸神。沒，只有見過他們的神殿。', `MaleText_loc7`='Nunca he conocido a los Magnos. No, solo conozco sus santuarios.' WHERE `ID`=28289;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크고 편한 나무야. 좋은 집이지.', `MaleText_loc4`='大树。温暖的家。', `MaleText_loc5`='又大又舒服的樹，好棒的家。', `MaleText_loc7`='Árbol grande y cómodo. Buen hogar.' WHERE `ID`=28290;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바삭바삭 벌레는 너무 맛나. 좀 줄까?', `MaleText_loc4`='这些虫虫又脆又美味。要不要来点？', `MaleText_loc5`='脆脆的蟲子真好吃。要嘛?', `MaleText_loc7`='Bichos crujientes deliciosos. ¿Querer?' WHERE `ID`=28291;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수세이 우리한테 잘 해줘. 우리 수세이 좋아.', `MaleText_loc4`='索乌塞对我们很和善。我们都很喜欢他。', `MaleText_loc5`='蘇-楔對我們很好，我們喜歡蘇-楔。', `MaleText_loc7`='Soo-pinstán es muy bueno con nosotros. Nos gusta Soo-pinstán.' WHERE `ID`=28292;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언젠가는 너도 수뽀송피부 될 수도 있어. 좋지?', `MaleText_loc4`='没准你能成为索干皮。你喜欢吗？', `MaleText_loc5`='或許有天你也能當蘇-乾皮喔。喜歡嘛?', `MaleText_loc7`='Quizá un día puedas ser Soo-pielseca. ¿Te gusta?' WHERE `ID`=28293;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕, 반가워.', `MaleText_loc4`='嗨。', `MaleText_loc5`='嗨。', `MaleText_loc7`='Hola.' WHERE `ID`=28294;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물에 뜨는 불꽃이라니! 저놈들이 내게도 하나 줄거 같아?', `MaleText_loc4`='漂浮的火花！他们会给我一个吗？', `MaleText_loc5`='飄飄在亮!你覺得他們會送我一顆嘛?', `MaleText_loc7`='¡Chispas flotantes! ¿Crees que me darán una?' WHERE `ID`=28295;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하룻강아지들이 이곳을 자주 공격해와. 그 때문에 벌레들이 전부 겁 먹었어... 그래서 우리는 안 그래.', `MaleText_loc4`='狗狗人经常攻击这里。他们吓跑了虫虫……因此我们不常来这里了。', `MaleText_loc5`='小狗人打這個地方打很兇。他把所有的蟲都嚇跑了...這就是為什麼我們來不多的原因。', `MaleText_loc7`='Hombres cachorro atacar este lugar a menudo. Asustan a todos los bichos... por eso nosotros no venir mucho.' WHERE `ID`=28296;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위대한 자들이 커다란 고양이 수호자인가 뭔가를 남겨 놓았어. 우리를 지키라는 건 아닌 듯하나, 좋은 친구야... 가끔씩 치사한 하룻강아지들이 오지 못하도록 해 줘.', `MaleText_loc4`='造物主在祭坛留下了守护者。虽然不是为我们留下的，但它是我们的好朋友……帮助我们抵御过好几次狗狗人的袭击。', `MaleText_loc5`='諸神留下了大貓咪保護東西。我想喔，不是留給我們的，但是牠是好朋友...有時候可以把壞小狗人趕走。', `MaleText_loc7`='Los Magnos dejar al gatito grande protector. Yo creer que no ser para nosotros, pero ser buen amigo... A veces, mantener alejados a los hombres cachorro malos.' WHERE `ID`=28297;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너 반짝이 많이 가져왔네. 운이 좋았나 봐.', `MaleText_loc4`='你有好多闪闪发亮的东西。运气真好。', `MaleText_loc5`='你有好多的亮晶晶，運氣真好。', `MaleText_loc7`='Tú tener muchas cositas brillantes. Tener suerte.' WHERE `ID`=28298;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 쿨쿨할 시간 아니야?', `MaleText_loc4`='睡觉时间到了？', `MaleText_loc5`='睡覺時間還沒到嗎?', `MaleText_loc7`='¿Hora de dormir ya?' WHERE `ID`=28299;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='착한 일을 해 주어 고마워.', `MaleText_loc4`='谢谢你，你是个好人。', `MaleText_loc5`='謝謝你對我好。', `MaleText_loc7`='Gracias por ser agradable.' WHERE `ID`=28300;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 근처 냄새 고약해. 왜 이리 고약한 거야.', `MaleText_loc4`='这里好臭啊。为什么这么臭呢？', `MaleText_loc5`='這附近好臭喔。為什麼這麼臭。', `MaleText_loc7`='Apestar por aquí. ¿Por qué apestar tanto?' WHERE `ID`=28301;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하룻강아지, 얌전하게 굴어. 우리 착해, 그러니 너도 착하게 굴어야지.', `MaleText_loc4`='别乱来，狗狗人。我们不会乱来的，你也不要乱来啊。', `MaleText_loc5`='乖乖喔，小狗人。我們乖，你也要乖。', `MaleText_loc7`='Ser simpático hombre cachorro. Nosotros ser simpáticos, así que tú también.' WHERE `ID`=28302;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진짜 이상해. 누가 우리 벌레를 다 가져갔어. 네가 그랬어?', `MaleText_loc4`='太古怪了。有人把虫虫都抢走了。不会是你干的吧？', `MaleText_loc5`='這好怪，有人把我們的蟲拿走了。也許你拿的?', `MaleText_loc7`='Eso ser raro. Alguien llevarse nuestros bichos. ¿Igual tú?' WHERE `ID`=28303;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하룻강아지들은 털이 너무 많아! 보기만 해도 간지러워.', `MaleText_loc4`='狗狗人浑身都是毛！真可怕。', `MaleText_loc5`='小狗人毛毛的!看起來癢癢。', `MaleText_loc7`='¡Hombres cachorro tener demasiado pelo! Tener que picar.' WHERE `ID`=28304;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어라! 그거 누구야? 너 친구야? 아니면 우리가 친구던가?', `MaleText_loc4`='噢！他是谁？你的朋友？我和他也能做好朋友吗？', `MaleText_loc5`='喔!他是誰?他是你的朋友嗎?所以我們也能當朋友嗎?', `MaleText_loc7`='¡Ooh! ¿Quién? ¿Él? ¿Él amigo tuyo? ¿A lo mejor nosotros también amigos?' WHERE `ID`=28305;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파이 있어? 몇 년 전에 누가 우리한테 파이 준 적 있어. 정말 맛있었는데.', `MaleText_loc4`='有馅饼吗？以前有人给过我一块馅饼。好吃极了！', `MaleText_loc5`='你有派?去年有人給我們派。好好吃。', `MaleText_loc7`='¿Tú tener tarta? Alguien darnos tarta hace un año. Riquísima.' WHERE `ID`=28306;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보물 더 나와라! 가지가지 나와라! 야호 보물이다!', `MaleText_loc4`='更多的宝藏！各种各样的宝藏！宝藏！', `MaleText_loc5`='更多的寶藏!各種的寶藏!寶藏好棒!', `MaleText_loc7`='¡Más tesoros! ¡Toda clase de tesoros! ¡Sí, tesoros!' WHERE `ID`=28307;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반짝이! 반짝이! 내 수정만큼 반짝거리지는 않지만, 그래도 반짝이는 반짝이!', `MaleText_loc4`='亮闪闪！亮闪闪！虽然不如我的水晶闪亮，但依然很闪亮！', `MaleText_loc5`='亮晶晶的東西!亮晶晶的東西!雖然沒有我的水晶亮，但是還是亮晶晶!', `MaleText_loc7`='¡Cosas brillantes! ¡Cosas brillantes! ¡No tan brillantes como mi cristal, pero también brillantes!' WHERE `ID`=28308;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 땅 진짜 빨리 파지! 봐봐... 벌써 다 했어! 빠르지, 그렇지?', `MaleText_loc4`='我们挖地的速度可快啦！真的哦！你瞧……完成啦！是不是很快呀？', `MaleText_loc5`='我們是動作很快的挖掘工!真的很快!你看...都好了!很快吧，對不對?', `MaleText_loc7`='¡Cavamos rápido! ¡Muy rápido! Mira... ¡ya está! Ha sido rápido, ¿no?' WHERE `ID`=28309;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반짝이는 수정은 가져도 가져도 또 가지고 싶어! 아무렴!', `MaleText_loc4`='亮闪闪的水晶怎么都不嫌多啊！不嫌多！', `MaleText_loc5`='亮晶晶水晶不嫌多!不嫌多!', `MaleText_loc7`='¡Nunca se tienen demasiados cristales brillantes! ¡Nop!' WHERE `ID`=28310;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바보 같은 하룻강아지 주위를 빙글빙글! 이얏호!', `MaleText_loc4`='让我们击败这群笨蛋狗狗人吧！来吧！', `MaleText_loc5`='我們來圍著呆呆小狗人繞圈圈!耶!', `MaleText_loc7`='¡Corramos en círculos alrededor de los estúpidos hombres cachorro! ¡Yupiii!' WHERE `ID`=28311;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='커다란 설인 녀석은 우리 못 잡아! 우리가 훨씬 빠르거든.', `MaleText_loc4`='大雪怪抓不到我们！我们跑得快如飞！', `MaleText_loc5`='大雪人怪獸抓不到我們!我們超快。', `MaleText_loc7`='¡Gran bestia yeti no puede atraparnos! Somos demasiado rápidos.' WHERE `ID`=28312;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빵빵! 쾅쾅! 하룻강아지 잡아라!', `MaleText_loc4`='砰！啪！击中那只狗狗人！', `MaleText_loc5`='砰!鏘!抓住那個小狗人!', `MaleText_loc7`='¡Pum! ¡Pam! ¡Chupaos esa, hombres cachorro!' WHERE `ID`=28313;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수홀루가 너 잡을 거다! 멍청한 하룻강아지, 메롱!', `MaleText_loc4`='索乌霍鲁来抓你们啦！愚蠢的狗狗人。哈哈哈！', `MaleText_loc5`='蘇-侯魯要來抓你囉!傻瓜小狗人，哈哈!', `MaleText_loc7`='¡Soo-brada os atrapará! Estúpidos hombres cachorro. ¡Jajaja!' WHERE `ID`=28314;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타르텍도 너 못 이겨! 너 기술 있잖아. 앗싸!', `MaleText_loc4`='塔尔特克比不上你！你真够厉害的。呀！', `MaleText_loc5`='塔提克不是你的對手!你深懷絕技，真的!', `MaleText_loc7`='¡Tartek no ser rival para ti! Tú tener las habilidades. ¡Sí!' WHERE `ID`=28315;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 용 따위로 겁먹을 줄 알았어? 어림 반푼어치도 없지!', `MaleText_loc4`='你以为我们会害怕龙吗？不会！', `MaleText_loc5`='你覺得我們會怕那些龍傢伙?才沒那麼怕呢!', `MaleText_loc7`='¿Tú creer que nosotros asustados de cosa dragón? ¡No tanto!' WHERE `ID`=28316;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 보물 훔쳐오는 법 가르쳐줄게! 우리 보물은... 우리 거니까, 그렇지?', `MaleText_loc4`='让你偷我们的财宝！财宝属于……我们，明白吗？！', `MaleText_loc5`='教你偷我們的寶藏!我們的寶藏是...我們的，好嗎?!', `MaleText_loc7`='¡Enseñarte a robar nuestros tesoros! Nuestros tesoros ser... nuestros, ¿vale?' WHERE `ID`=28317;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이전에 용 타고 다니는 하룻강아지 본 적 없겠지? 풉! 다시 볼 일도 없을걸.', `MaleText_loc4`='我打赌你没有见过狗狗人骑在龙背上的情景吧？哈哈！你以后也不会见到。', `MaleText_loc5`='打賭你以前從沒看過小狗狗騎大飛龍吧?哈!以後也看不到啦。', `MaleText_loc7`='¿Apuesto a que nunca habías visto un cachorro montado en un dragón? ¡Ja! Y no creo que vuelvas a verlo.' WHERE `ID`=28318;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이이런! 너 여기 왜 왔어? 바보, 바보야! 여기 오지 마!', `MaleText_loc4`='哇！你来这里干什么啊？傻，傻瓜！不要来这里！', `MaleText_loc5`='嗚哇!你為什麼來這裡?傻瓜，傻瓜!不可以來這!', `MaleText_loc7`='¡Guau! ¿Por qué gente venir aquí? ¡Tontos, tontos! ¡No venir aquí!' WHERE `ID`=28319;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만! 난 그만이야. 이제 여기 네가 다 해. 안녕!', `MaleText_loc4`='不！别来找我的麻烦！这地方归你们啦。再见！', `MaleText_loc5`='沒!不是我的。這地方都給你，拜拜!', `MaleText_loc7`='¡Nop! Yo no más. Este sitio ser todo tuyo. ¡Adiós!' WHERE `ID`=28320;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래... 아니야.', `MaleText_loc4`='嗯……别来找我的麻烦。', `MaleText_loc5`='對啊...啊不。', `MaleText_loc7`='Sí... no.' WHERE `ID`=28321;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='휘릭!', `MaleText_loc4`='呼！', `MaleText_loc5`='呼!', `MaleText_loc7`='¡Puf!' WHERE `ID`=28322;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우! 아하하.. 어라, 이건 좋지 않은데.', `MaleText_loc4`='哦！哈哈……滋味不好受吧。', `MaleText_loc5`='噢!哈哈...啊，那不好。', `MaleText_loc7`='¡Au! Jajaja... ehm, eso no ser bueno.' WHERE `ID`=28323;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와아! 여기저기 전부 번개친다! 우리도 번개 어떻게 만드는지 배워서 하룻강아지들에게 써먹어야 해!', `MaleText_loc4`='哇噻！到处都是闪电！我们应该学了这招去对付狗狗人！', `MaleText_loc5`='哇嗚!到處都是閃電!我們得學著把這些東西打在小狗人身上!', `MaleText_loc7`='¡Guau! ¡Rayos por todas partes! ¡Tener que aprender a hacer esto a los hombres cachorro!' WHERE `ID`=28324;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바보 같은 하룻강아지들이 제단을 망쳤대요! 메롱! 어서 막아!', `MaleText_loc4`='狗狗人把祭坛搞得一团糟！讨厌！快阻止他们！', `MaleText_loc5`='笨笨小狗人把神殿弄得一團亂!哼!要阻止這件事!', `MaleText_loc7`='¡Los estúpidos hombres cachorro han fastidiado el santuario! ¡Buaa! ¡Haz que paren!' WHERE `ID`=28325;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아! 맞을 뻔했는데! 어서, 빨리 쇠막대 아래 서봐! 그 밑에 서면 우리 안전한 거지, 그렇지?', `MaleText_loc4`='啊！差一点！快，快站到金属柱子下！它能保证我们的安全，对吧？', `MaleText_loc5`='啊!好危險喔!快，快，躲到金屬柱子底下!這會比較安全，對吧?', `MaleText_loc7`='¡Ah! ¡Eso ha estado cerca! ¡Deprisa, deprisa, colocarse bajo cosa poste de metal! Eso mantenernos a salvo, ¿verdad?' WHERE `ID`=28326;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안개야. 아주 자욱해. 너한테도 안개같이 보여? 그렇게 짙은 안개는 아닐지도 모르지.', `MaleText_loc4`='雾气。好重的雾气啊。对你来说，这或许算不上浓雾吧？', `MaleText_loc5`='霧濛濛。超級霧濛濛。對你來說是不是也很霧濛濛?也許沒那麼嚴重喔。', `MaleText_loc7`='Niebla. Mucha niebla. ¿Parecerte que hay niebla? Igual no tanta.' WHERE `ID`=28327;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안개속삭임골록은 우리랑 달라. 걔들은 우리가 "평온을 깨뜨린다."라고 해.', `MaleText_loc4`='雾语鳄鱼人有时候也会讨厌我们。他们认为我们“毁了他们的宁静”。', `MaleText_loc5`='霧語不太喜歡我們。他們說我們「弄壞了他們的蚌」。', `MaleText_loc7`='No siempre gustar a Susurraneblina. Ellos decir que nosotros "dañar su calma".' WHERE `ID`=28328;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안개속삭임골록은 좀 따분해. 맞아, 따분해... 조금.', `MaleText_loc4`='雾语鳄鱼人都很无聊。对，真的有点……无聊。', `MaleText_loc5`='霧語有點無聊。對啊，無聊...一點點啦。', `MaleText_loc7`='Susurraneblina bastante aburridos. Sí, aburridos... un poco.' WHERE `ID`=28329;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안개부름이는 제단의 힘으로 날씨를 참 잘 다스려. 어떤 수정을 사용하는지 그냥 안다니까! 정말 잘해!', `MaleText_loc4`='唤雾者擅长利用祭坛来控制气候。他们知道各种水晶的用途！对，他们知道得一清二楚！', `MaleText_loc5`='喚霧者真的很會運用神殿控制天氣。他們就是曉得要用哪顆水晶!超強的!', `MaleText_loc7`='A clamaneblina dársele muy bien controlar el tiempo con santuario. ¡Saber qué cristales usar! ¡Muy bueno!' WHERE `ID`=28330;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꽝! 아핫! 한놈 잡았다!', `MaleText_loc4`='啪！哈哈！击中啦！', `MaleText_loc5`='鏘!哈!打得好!', `MaleText_loc7`='¡Pum! ¡Ja! ¡Toma esa!' WHERE `ID`=28331;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맘에 들어? 안 드는 거 같아! 네가 왜 맘에 안 들어하는지 알아. 왜냐면 넌 죽었으니까! 우하하하!', `MaleText_loc4`='你喜欢吗？我打赌你不会喜欢的！因为你已经死啦！哈哈哈！', `MaleText_loc5`='你喜歡嗎?我賭你不喜歡!我賭你不會死!哈哈!', `MaleText_loc7`='¿Gustarte eso? ¡Seguro que no! ¡Seguro que no porque tú estar muerto! ¡Jajaja!' WHERE `ID`=28332;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='막을 테면 막아봐!', `MaleText_loc4`='无坚不摧！', `MaleText_loc5`='戰無不勝!', `MaleText_loc7`='¡Imparable!' WHERE `ID`=28333;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신나게 쓸어보자!', `MaleText_loc4`='杀戮盛宴！', `MaleText_loc5`='獵殺狂歡!', `MaleText_loc7`='¡A matar!' WHERE `ID`=28334;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너 졌어! 졌으니까 바보야!', `MaleText_loc4`='你输了！输得真难看呀！', `MaleText_loc5`='你輸了!輸得慘兮兮!', `MaleText_loc7`='¡Tú perder! ¡Perder malo!' WHERE `ID`=28335;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 네 주위 빙글빙글 돌 테다! 우린 멋지니까!', `MaleText_loc4`='我们打败你啦！我们真了不起！', `MaleText_loc5`='我們圍著你繞圈圈!我們超厲害!', `MaleText_loc7`='¡Nosotros correr en círculos alrededor de ti! ¡Nosotros muy buenos!' WHERE `ID`=28336;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽지 않기를 바랄 테지만! 너무 늦었어. 죽었으면 바라는 것도 못하는 거야! 으하하!', `MaleText_loc4`='你肯定不想死吧！太迟啦，死人是不能许愿的！哈哈哈！', `MaleText_loc5`='我打賭你但願還沒死!可是已經太遲了，死了就不能許願了!哈!', `MaleText_loc7`='¡Apuesto a que desear no estar muerto! ¡Ser tarde, no poder desear cosas cuando estar muerto! ¡Ja!' WHERE `ID`=28337;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='승...리...를! 띠리리 리리리!', `MaleText_loc4`='胜……利……啦！啾啾啾！', `MaleText_loc5`='打...勝...仗!啦啦啦啦啦啦!', `MaleText_loc7`='¡Ven... ce... do... res! ¡Dun nun nun dun da da!' WHERE `ID`=28338;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='집으로 집으로 집으로... 반짝이들이 가득한 곳이야!', `MaleText_loc4`='家！家！家……闪闪发亮的地方！', `MaleText_loc5`='老家、老家、老家...閃亮的地方!', `MaleText_loc7`='Hogar, hogar, hogar... ¡lugar de las cositas brillantes!' WHERE `ID`=28339;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='집 좋아. 그래도 오래 있으면 안 돼! 모험을 더 해야지!', `MaleText_loc4`='家里真好，可惜呆不长！我们要更多的冒险！', `MaleText_loc5`='家裡很好，可是別待太久!還有冒險呢!', `MaleText_loc7`='¡Hogar bueno, pero no quedarse mucho! ¡Más aventuras!' WHERE `ID`=28340;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나무에서 뛰어 보자! 폴짝! 재밌다!', `MaleText_loc4`='来来，一起从树上跳下去吧！超级好玩！', `MaleText_loc5`='讓我們從樹上跳下去!好玩好玩!', `MaleText_loc7`='¡Ir a saltar desde árbol! ¡Divertido, divertido!' WHERE `ID`=28341;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 조그만 녀석들 잡아! 그 녀석들 잡으라고! 그런데 너무 빠르잖아!', `MaleText_loc4`='追赶幼体！追赶幼体！快跑！', `MaleText_loc5`='追寶寶!追寶寶!跑真快!', `MaleText_loc7`='¡Perseguir a las crías! ¡Perseguir a las crías! ¡Muy rápidas!' WHERE `ID`=28342;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋은 집이야. 오래됐는데, 아직 괜찮아.', `MaleText_loc4`='美好的家。住了很长时间，依然不会厌倦。', `MaleText_loc5`='還是回家好，就算過了這麼久，還是很舒適。', `MaleText_loc7`='Buen hogar. Tenerlo hace tiempo y aún estar bien.' WHERE `ID`=28343;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위대한 자들이 안전하게 집 지켜줬어. 점쟁이 조합을 좋아하기 때문이라고 생각해! 우리가 착하고 괜찮다는 걸 아니까.', `MaleText_loc4`='造物主能够保证家的安全，因为他们喜欢先知！他们知道鳄鱼人都是好人。', `MaleText_loc5`='諸神之所以會保護家園安全，我想是因為他們喜歡神諭者的關係!他們知道我們人很好。', `MaleText_loc7`='¡Yo creer que los Magnos mantener el hogar a salvo porque gustarles Oráculos! Ellos saber que nosotros ser buenos y simpáticos.' WHERE `ID`=28344;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 진짜 우리 집이야! 예전엔 우리도 작았을 거로 생각해? 맞아 우리도 쪼끄맸어!', `MaleText_loc4`='这是我真正的家！你相信我们以前也是鳄鱼人幼体吗？真的是这样哦！', `MaleText_loc5`='這是我真正的住所!你相信我很久以前是小寶寶?我們是啊!', `MaleText_loc7`='¡Este ser mi verdadero hogar! ¿Tú creer que hace tiempo nosotros ser crías? ¡Nosotros serlo!' WHERE `ID`=28345;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='번개불꽃골록은 싸움 제일 잘해! 빠르게 슉슉. 아주 잘해!', `MaleText_loc4`='灵鳍鳄鱼人最厉害！嚓！嚓！拯救世界！', `MaleText_loc5`='真是炫觸最厲害的戰士!轟轟，真厲害!', `MaleText_loc7`='¡Pavesa ser los mejores luchadores sin duda! Plas plas. ¡Hacer las cosas bien!' WHERE `ID`=28346;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하룻강아지들은 얼씬도 하지 마! 와서 한 방 맞고 뻗던가!', `MaleText_loc4`='不欢迎狗狗人！我们要好好地揍他们一顿！', `MaleText_loc5`='小狗人不受歡迎!把我們的東西偷走!', `MaleText_loc7`='¡Hombres cachorro no bienvenidos! ¡Venid a ser aniquilados!' WHERE `ID`=28347;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수홀루는 다른 어떤 점쟁이 조합보다도 번개불꽃골록인 것 같아. 맞아!', `MaleText_loc4`='索乌霍鲁是最聪明的灵鳍神谕者。不骗你！', `MaleText_loc5`='蘇-侯魯比起其他部族神諭者更常在炫觸出現。真的!', `MaleText_loc7`='Soo-brada aparecerse a los Pavesa más que a cualquier otra tribu Oráculo. ¡Ser cierto!' WHERE `ID`=28348;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지난번에 하룻강아지들이 공격했을 때, 수홀루가 걔들 야영지까지 쫓아갔어! 엄청나게 멋졌다고!', `MaleText_loc4`='上次狗狗人打过来，结果索乌霍鲁将他们统统赶回了狗狗人的营地！真是氏族的荣耀啊！', `MaleText_loc5`='上次小狗人攻擊，蘇-侯魯追蹤他們一路跑到他們的營地還什麼的!那真光榮!', `MaleText_loc7`='¡La última vez que hombres cachorro atacar, Soo-brada perseguirlos hasta su cosa campamento! ¡Ser glorioso!' WHERE `ID`=28349;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너 진짜 강해! 네가 그 커다란 설인 녀석 처치할 줄 알았어! 정말 멋지게 해냈다고!', `MaleText_loc4`='你很强大！我打赌你能干掉那只大雪怪！肯定没问题！', `MaleText_loc5`='你真強!我打賭你可以殺死大雪人怪物之類的!你可以痛扁他!', `MaleText_loc7`='¡Tú bastante poderoso! ¡Yo apostar que poder matar gran cosa bestia yeti! ¡Tú poder con él!' WHERE `ID`=28350;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청한 하룻강아지들! 친절하게 대하려 했는데! 이제 뜨거운 맛을 보여줄게!', `MaleText_loc4`='愚蠢的狗狗人！我们不想打架的！你们却偏偏跑来送死！', `MaleText_loc5`='呆呆小狗人!我們試著對他們好!這是你自找的!', `MaleText_loc7`='¡Estúpidos hombres cachorro! ¡Nosotros intentar se agradables! ¡Ir a enteraros ahora!' WHERE `ID`=28351;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너한테 그 용 뭐인가가 있다는 거 다 알아! 너랑 그 용인지 뭐인지 다 잡아 버릴 거야!', `MaleText_loc4`='我们知道你们有龙！但我们不怕！我们要将你们统统打扁！', `MaleText_loc5`='我們知道你有龍傢伙!我們不怕!我們要逮到你和龍傢伙!', `MaleText_loc7`='¡Nosotros saber que ustedes tener cosa dragón! ¡No tener miedo! ¡Nosotros iremos por ustedes y a por cosa dragón!' WHERE `ID`=28352;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하룻강아지가 숨을 차례다! 꼭꼭 숨어라... 머리카락 보일라!', `MaleText_loc4`='逃命去吧，狗狗人！我们来抓你们啦……最好滚回自己的山上去！', `MaleText_loc5`='趕快躲好喔小狗人!我們來找你了...最好能在山丘之類的裡面抓到你們。', `MaleText_loc7`='¡Hora de esconderse hombres cachorro! Nosotros ir a por ustedes... ¡mejor marchénse a sus cosas colina!' WHERE `ID`=28353;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거대한 바위는 만지면 안 돼! 나빠! 나쁜 짓이야!', `MaleText_loc4`='大石柱不能随便摸的！讨厌！不许摸！', `MaleText_loc5`='大石頭不可以摸!壞壞!壞壞!', `MaleText_loc7`='¡No tocar Piedras Grandes! ¡Mal hecho! ¡Mal hecho!' WHERE `ID`=28354;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타르텍은 바보야! 하룻강아지들은 바보나 쫓아다니지. 정말 멍청해!', `MaleText_loc4`='塔尔特克是个笨蛋！狗狗人都听这个笨蛋的话。狗狗人都很愚蠢！', `MaleText_loc5`='塔提克真笨!所有的小狗人都追隨這個笨蛋。一點也不聰明!', `MaleText_loc7`='¡Tartek ser tonto! Todos los hombres cachorro seguir a los tontos. ¡No ser inteligente!' WHERE `ID`=28355;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 창을 부러뜨릴 테야! 창 때문에 울지는 마, 하룻강아지들아... 창이 부러졌다고 찔찔 짜지는 말라고!', `MaleText_loc4`='我们会拧断你们的长矛！别为它们哭泣啊……别为断裂的长矛哭泣！', `MaleText_loc5`='我們要折斷你們的長矛!不要為了你們的長矛掉眼淚，小狗人...不要為了長矛折斷掉眼淚!', `MaleText_loc7`='¡Nosotros ir a romper todas tus lanzas! No llorar por tus lanzas, hombres cachorro... ¡no llorar porque estar rotas!' WHERE `ID`=28356;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕, 하룻강아지 씨? 땟물이 줄줄 흐르잖아? 한 번도 씻은 적 없구나! 하하하.', `MaleText_loc4`='嗨，狗狗人，你这辈子洗过澡吗？肯定没有！哈哈哈。', `MaleText_loc5`='嘿，小狗人傢伙，你們洗過澡嗎?打賭沒有!哈哈。', `MaleText_loc7`='Oye, cosa hombre cachorro, ¿tú bañarte alguna vez? ¡Seguro que no! Jajaja.' WHERE `ID`=28357;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 편 뽀송피부가 너희 편 뽀송피부한테 이길 거야. 당연하지. 그렇고말고.', `MaleText_loc4`='我的干皮人肯定比你厉害。别不信。', `MaleText_loc5`='我的乾皮可以打敗你的乾皮。對，絕對。', `MaleText_loc7`='Mi pielseca puede vencer a tu pielseca. Sí, sin duda.' WHERE `ID`=28358;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너 절대 안 세 보여. 약해빠진 강아지 주제에.', `MaleText_loc4`='你看上去不是很强壮啊。没用的狗狗人。', `MaleText_loc5`='你看起來不太厲害，弱弱的小狗傢伙。', `MaleText_loc7`='Tú no parecer tan duro. Débil cosa cachorro.' WHERE `ID`=28359;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 뭐 싫어하는지 알아? 강아지 같은 거야! 바로 저기 하나 있네! 봤어? 우리 정말 싫어해.', `MaleText_loc4`='知道我们不喜欢什么吗？狗狗人！比如那边的狗狗人！看见了吗？我们不喜欢它。', `MaleText_loc5`='知道我們討厭什麼嗎?小狗傢伙!就像那邊那一位!看到了嗎?我們不喜歡它。', `MaleText_loc7`='¿Saber que no gustarnos? ¡Cosas cachorro! ¡Como esa de ahí! ¿Ver? No gustarnos.' WHERE `ID`=28360;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 뭐해, 강아지? 저리 가! 가서 막대기나 뭐 다른 거나 가지고 놀아.', `MaleText_loc4`='这里为什么会有狗狗人？滚开！去拣骨头玩吧。', `MaleText_loc5`='小狗傢伙，你在這裡幹嘛?滾啦!去做追棍子之類的事情。', `MaleText_loc7`='¿Qué estar haciendo aquí, cosa cachorro? ¡Marcharte! Ir a buscar palito o algo.' WHERE `ID`=28361;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐... 잠깐... 강아지. 부모님은 어떻게 지내신대? 우리 뽀송피부가 전부 처리한 것 같은데 말이야. 아하하! 고소하다!', `MaleText_loc4`='嗨……我说……狗狗人。你的亲人都还好吧？我的干皮人将他们统统杀掉了。哈哈哈！很爽吧！', `MaleText_loc5`='嘿...喂喂...小狗傢伙。你的家人好嗎?我想我的乾皮人把他們都殺了。啊哈哈!嚇到你了吧!', `MaleText_loc7`='Hey... psst... cosa cachorro. ¿Qué tal tu familia? Creo que mi pielseca los ha matado a todos. ¡Jajajaja! ¡Toma esa!' WHERE `ID`=28362;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='만세... 또 흙이야.', `MaleText_loc4`='唉……又是泥土。', `MaleText_loc5`='耶...更多土。', `MaleText_loc7`='Sí... más suciedad.' WHERE `ID`=28363;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 일로 수세이 고마워 할 거야.', `MaleText_loc4`='索乌塞应该会喜欢这些玩意儿吧。', `MaleText_loc5`='蘇-楔應該會喜歡這些東西。', `MaleText_loc7`='Soo-pinstán apreciar mejor estos.' WHERE `ID`=28364;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기... 쓸데없는 벌레만 더 나올 거 같은데.', `MaleText_loc4`='嗨……或许我们会找到更多没用的虫虫。', `MaleText_loc5`='嘿...我們說不定可以找到更多沒用的蟲子。', `MaleText_loc7`='Oye... quizá encontremos más bichos inútiles.' WHERE `ID`=28365;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도대체 반짝거리는 토끼가 여기 왜 있는 거지?', `MaleText_loc4`='这里怎么会有亮闪闪的兔子啊？', `MaleText_loc5`='這些閃亮兔子到底為什麼在這裡?', `MaleText_loc7`='¿Qué diablos hacer conejos brillantes aquí?' WHERE `ID`=28366;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 안 끝났어?', `MaleText_loc4`='挖够了没有啊？', `MaleText_loc5`='我們完成了嗎?', `MaleText_loc7`='¿Hemos acabado ya?' WHERE `ID`=28367;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 여기서 뭐 하냐면, 얼마 전에 만난 어떤 분의 뜻을 따라 땅에서 쓸모없는 쓰레기들을 파낸다고... 이게 말이 된다고 생각해?', `MaleText_loc4`='你瞧，我刚刚认识那家伙，他就派我来这里挖掘没用的小玩意儿……你觉得这件事正常吗？', `MaleText_loc5`='我在這裡，順從我最近遇到的某人之意，從地上挖掘一些無用的小珠子...你覺得這對嗎?', `MaleText_loc7`='Aquí estoy, desenterrando algunos inútiles adornos para cumplir la voluntad de alguien a quien acabo de conocer... ¿te parece que eso está bien?' WHERE `ID`=28368;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='덤벼라, 울바르! 죽음이 널 부르고 있어!', `MaleText_loc4`='来吧，狼獾人！你的末日到了！', `MaleText_loc5`='來吧獾狼怪!你的死亡正向你招手!', `MaleText_loc7`='¡Ven wolvar! ¡La muerte te llama!' WHERE `ID`=28369;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 전투 끝까지 수홀루와 지켜볼 거야...', `MaleText_loc4`='索乌霍鲁会终止这场战斗……', `MaleText_loc5`='與蘇-侯魯看著這場戰爭結束...', `MaleText_loc7`='Soo-brada pondrá fin a esta batalla...' WHERE `ID`=28370;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카르탁, 너 따위 절대 안 무서워!', `MaleText_loc4`='卡塔克，我不怕你！', `MaleText_loc5`='卡爾塔克，我一點也不怕你!', `MaleText_loc7`='¡Kartak, no te temo!' WHERE `ID`=28371;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 하룻강아지들은 우리를 아주 많이 죽였지만, 그래도 우리는 아직도 아직도 평화를 제의한다고... 이게 말이 된다고 생각해?', `MaleText_loc4`='狗狗人杀害了我们的同胞，我们却要向他们示好……你觉得这件事正常吗？', `MaleText_loc5`='小狗人已經殺掉不少我們的同胞，而我們仍然對他們保持和平...你覺得這對嗎?', `MaleText_loc7`='Estos hombres cachorro han matado a montones de nosotros, pero aun así les ofrecemos la paz... ¿Te parece que eso está bien?' WHERE `ID`=28372;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무너진 기둥에서 빨리 죽어 버리고 싶은가 봐? 거기 남은 건 너 하나뿐인데.', `MaleText_loc4`='你想去破柱子送死啊？那你自己去吧。', `MaleText_loc5`='你就這麼急著到斷掉的柱子找死嗎?你在那只有一個人。', `MaleText_loc7`='¿Quieres acelerar tu muerte yendo a Pilar Partido? Estás solo en eso.' WHERE `ID`=28373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아마 나는, 군대를 소집해서 다시 돌아올 거야. 무너진 기둥은 별로 반기지 않겠지만.', `MaleText_loc4`='如果能集合起一支军队，我或许会考虑与你同去。去破柱子可不是闹着玩儿的。', `MaleText_loc5`='也許，我會在募得一批軍隊以後回來這裡。斷掉的柱子不怎麼受歡迎。', `MaleText_loc7`='Volveré cuando haya reunido un ejército, a lo mejor. Pilar Partido no es acogedor.' WHERE `ID`=28374;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너 정말 용감하구나. 그렇지만, 여기에서는 혼자일 뿐이야, 뽀송피부.', `MaleText_loc4`='干皮人，你很勇敢。如果你坚持要去破柱子的话，那么再见。', `MaleText_loc5`='你的確很勇敢，但當它降臨此處時，你只能獨自面對，乾皮人。', `MaleText_loc7`='No caber duda de que ser valiente, pero en este lugar estar solo, pielseca.' WHERE `ID`=28375;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더는 너를 쫓아가지 않겠어, 뽀송피부. 무너진 기둥에서 너무 많이 죽었으니. 똑같은 신세가 되고 싶지는 않아.', `MaleText_loc4`='干皮人，我不会再跟着你了。很多鳄鱼人都死在破柱子了，我不想去陪他们。', `MaleText_loc5`='我不會再跟隨你向前走了，乾皮人，太多人死在斷掉的柱子那邊，而我不要當他們之一。', `MaleText_loc7`='No te seguiré más allá, pielseca. Muchos haber muerto en Pilar Partido y yo no tener intención de ser uno de ellos.' WHERE `ID`=28376;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='믿을 수가 없어... 전부 다... 죽었어.', `MaleText_loc4`='我不敢相信……他们全都……死了。', `MaleText_loc5`='我不敢相信...他們全都...死了。', `MaleText_loc7`='No puedo creer... que estén... todos muertos.' WHERE `ID`=28377;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 땅은 언데드한테서 안전할 줄 알았거든?', `MaleText_loc4`='我以为我们的家园不会遭受亡灵的侵袭。', `MaleText_loc5`='我還以為我們的土地已經遠離不死生物的威脅了?', `MaleText_loc7`='¡Creía que nuestra tierra estaba a salvo de los no-muertos!' WHERE `ID`=28378;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='게다가 아서스 군대는 노스렌드에서 마지막 남은 미개척지까지 쳐들어왔어.', `MaleText_loc4`='阿尔萨斯的军队已经侵入诺森德的最后一片净土……', `MaleText_loc5`='所以，阿薩斯的部隊攻破了北裂境最後一塊未被染指的地方...', `MaleText_loc7`='Y así entraron los ejércitos de Arthas en la última tierra inexplorada de Rasganorte...' WHERE `ID`=28379;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 여기 있었어야 했어... 이런 일이 일어나지 않도록 미리 막았어야 했어.', `MaleText_loc4`='我们应该保卫家园……应该阻止这一切的发生。', `MaleText_loc5`='我們早該來這裡了...我們早該在一開始就阻止這件事的。', `MaleText_loc7`='Deberíamos haber estado aquí… deberíamos haber prevenido esto.' WHERE `ID`=28380;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 일은 그냥 두고 볼 수 없어. 언데드는 대가를 치러야만 해!', `MaleText_loc4`='我们不能任凭天灾军团胡来。他们必须付出代价！', `MaleText_loc5`='我們不能讓這種事情持續。不死生物一定要付出代價!', `MaleText_loc7`='No podemos pasar esto por alto. ¡Los no-muertos deben pagar!' WHERE `ID`=28381;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수세이는 이끼걸음골록들이 이상한 날씨 얘기했을 때 자세히 알아보지 않았고, 그래서 지금 다 죽었어... 이게 말이 된다고 생각해?', `MaleText_loc4`='整个苔行村都在谈论异常的气候时，索乌塞没有采取任何措施，现在他们都死了……你觉得这件事正常吗？', `MaleText_loc5`='當苔行者提起怪異的天氣時，蘇-楔才開始調查，如今他們全都死了...你覺得這對嗎?', `MaleText_loc7`='Soo-pinstán no investigó nada cuando los Caminamoho mencionaron clima extraño, ahora estar todos muertos... ¿Te parece que eso está bien?' WHERE `ID`=28382;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이래야지.', `MaleText_loc4`='必然的结局。', `MaleText_loc5`='該怎樣就怎樣。', `MaleText_loc7`='Como debe ser.' WHERE `ID`=28383;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 공격에 또 하나 쓰러졌어.', `MaleText_loc4`='又倒下一个。', `MaleText_loc5`='又一個在我們的突襲中倒下了。', `MaleText_loc7`='Otro más cae bajo nuestro embate.' WHERE `ID`=28384;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 당장 우리를 말려 달란 말이야!', `MaleText_loc4`='来阻挡我们啊！', `MaleText_loc5`='有種現在就來阻止我們!', `MaleText_loc7`='¡Intenta detenernos ahora!' WHERE `ID`=28385;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뽀송피부치고는 나쁘지 않네.', `MaleText_loc4`='对干皮人来说很不错了。', `MaleText_loc5`='對乾皮人來說還不錯。', `MaleText_loc7`='No estar mal para un pielseca.' WHERE `ID`=28386;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 우리 편이 될 만한 모험가를 만난 걸지도 몰라... 아마 네가 우리 골록을 구해 주겠지.', `MaleText_loc4`='或许你就是值得我陪伴左右的冒险家……或许你能拯救我的同胞。', `MaleText_loc5`='也許，我已經遇到值得我同行的冒險者...也許，你是我族的救贖。', `MaleText_loc7`='Quizá haya conocido a un aventurero digno de mi compañía... quizá tú redimas a mi gente.' WHERE `ID`=28387;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 잘루트를 견뎌냈어? 잘루트가 입만 열면, 나는 광란심장 언덕에 갖다 버리고 싶던데.', `MaleText_loc4`='你怎么能忍受亚鲁乌特？他一开口，我就想把他踹到狂心岭去。', `MaleText_loc5`='你是怎麼忍受得了賈露特?他只要一說話，我會想要把他丟進狂心之丘裡。', `MaleText_loc7`='¿Cómo soportas a Jaloot? Cada vez que habla, me entran ganas de lanzarlo a la Colina Corazón Frenético.' WHERE `ID`=28388;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라푸는 수세이가 진짜 아끼는 골록이야. 내가 본 중에 제일 쓸모없는 골록인데도... 그 정도면 말 다한 거지 뭐.', `MaleText_loc4`='拉弗乌是索乌塞的小宠物。他大概是我见过的最无能的鳄鱼人……这多少能说明点问题。', `MaleText_loc5`='拉富是蘇-楔的小寵物。大概是我所見過的戈洛克中最軟弱的一隻...真的不騙你。', `MaleText_loc7`='Lafoo es la pequeña mascota de Soo-pinstán. Probablemente sea el górloc más incompetente que jamás me he echado a la cara... y eso es mucho decir.' WHERE `ID`=28389;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='골록 연합 전체에서 싸움을 제일 많이 한 난데, 아직도 시간을 따로 내서 너희 말 제대로 하는 법 배우지... 이게 말이 된다고 생각해?', `MaleText_loc4`='我经历过的战斗比其他鳄鱼人加起来的还要多，就这样，我还能找出时间来学习你的语言……你觉得这件事正常吗？', `MaleText_loc5`='我打過的仗比其他戈洛克加起來還要多，而我仍然抽時間學你們正確的語言...你覺得這對嗎?', `MaleText_loc7`='Lucho más que todos los demás górlocs juntos y, aun así, saco tiempo para aprender tu idioma correctamente... ¿Te parece que eso está bien?' WHERE `ID`=28390;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아. 지금 가자고.', `MaleText_loc4`='呀，我们出发吧。', `MaleText_loc5`='是呀，我們走吧。', `MaleText_loc7`='Sí, vamos ahora.' WHERE `ID`=28391;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기선 볼 일 끝났어.', `MaleText_loc4`='事情办好啦。', `MaleText_loc5`='我這裡的事完成了。', `MaleText_loc7`='Ya he acabado aquí.' WHERE `ID`=28392;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 여기 남아 있는 이유라도 있어? 있으면 말해봐.', `MaleText_loc4`='为什么我们还留在这里？给我个说得过去的理由啊。', `MaleText_loc5`='我們還在這的理由是什麼?我洗耳恭聽。', `MaleText_loc7`='¿Hay alguna razón por la que aún seguimos aquí? Me encantaría escucharla.' WHERE `ID`=28393;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그냥 그렇게 계속 뭉개고 있을 참이야, 아니면 좀 영양가 있는 일을 해볼 셈이야?', `MaleText_loc4`='你是打算继续无所事事地坐着，还是和我一起做些有用的事？', `MaleText_loc5`='你是打算讓你的屁股貼在地上呢，還是做一些真正有用的事情?', `MaleText_loc7`='¿Tienes intenciones de seguir apoyando tus posaderas un rato más o vamos a hacer algo útil?' WHERE `ID`=28394;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='낮잠 자러 갈 거야? 자는 동안 네 얼굴을 밟을지도 모르니까 미리 사과할게.', `MaleText_loc4`='你要打个盹？那我先给你倒个歉吧，待会你睡着之后，我可能会不小心踩到你的脸。', `MaleText_loc5`='想要打個盹嗎?那我要事先道歉，因為當你睡覺的時候我會一不小心踩到你的臉上。', `MaleText_loc7`='¿Vas a echar una cabezadita? Me disculpo por adelantado por pisarte accidentalmente la cara mientras duermes.' WHERE `ID`=28395;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 내가 제일 똑똑하고, 강하고, 문화적인 골록이라고. 하지만, 감독은 전부 수세이가 하지... 이게 말이 된다고 생각해?', `MaleText_loc4`='我是最聪明、最强壮、最有修养的鳄鱼人，但是索乌塞却拥有氏族的统治权……你觉得这件事正常吗？', `MaleText_loc5`='我是這裡最聰明、最強壯、最有教養的戈洛克，但是蘇-楔卻掌握一切...你覺得這對嗎?', `MaleText_loc7`='Yo soy el górloc más inteligente, fuerte y culto del lugar, pero aun así es Soo-pinstán el que manda... ¿Te parece que eso está bien?' WHERE `ID`=28396;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 살아 있는 게 더 있을지도 몰라! 계속 움직여야 해.', `MaleText_loc4`='可能还有更多的幸存者！我们必须继续前进。', `MaleText_loc5`='一定還有更多生還者!我們得繼續前進。', `MaleText_loc7`='¡Quedan más que pueden estar vivos! Tenemos que seguir moviéndonos.' WHERE `ID`=28397;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 희생자를 끌고 어디로 가는 거야? 희생자한테 무슨 짓을 하는 거야?', `MaleText_loc4`='他们把尸体都拖到哪儿去了？他们会对尸体做什么？', `MaleText_loc5`='他們要把屍體拖到哪裡去?他們要對屍體做什麼?', `MaleText_loc7`='¿Adónde arrastran esos cuerpos? ¿Qué les están haciendo?' WHERE `ID`=28398;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 살아남은 누군가가 있다니 믿기지 않아.', `MaleText_loc4`='很难相信在这样一场劫难后，还会有幸存者。', `MaleText_loc5`='很難相信他們任何一個可以熬過這一切。', `MaleText_loc7`='Cuesta creer que alguno haya sobrevivido a esto.' WHERE `ID`=28399;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언데드가 되어 돌아온 골록이 아무도 없어서 그나마 다행스러워.', `MaleText_loc4`='唯一值得欣慰的是，他们没有变成亡灵。', `MaleText_loc5`='看見他們沒有變成不死生物重生，算是一點小小的安慰。', `MaleText_loc7`='Es un ligero alivio ver que no han resucitado a ninguno como un no-muerto.' WHERE `ID`=28400;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 그놈들을 좀 얕잡아보고 말하는 거 알아. 하지만, 우리 골록 하나라도 죽는 건 보고 싶지 않거든.', `MaleText_loc4`='我知道我的态度有些傲慢，但是我不希望我的同胞受到牵连。', `MaleText_loc5`='我知道我對他們兇了一點，但是我從來沒想過要看到我的人民死掉啊。', `MaleText_loc7`='Sé que les hablo con tono condescendiente, pero no quiero ver a ninguno de los míos morir.' WHERE `ID`=28401;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이끼걸음골록이 생각보다 빨리 기운을 회복하는 걸 보니 좋아.', `MaleText_loc4`='有的苔行鳄鱼人比我想象的更有活力，真是令人宽慰啊。', `MaleText_loc5`='很高興看見某些苔行者，比我想的還要強韌。', `MaleText_loc7`='Me alegra ver que algunos de los Caminamohos son más fuertes de los que pensaba.' WHERE `ID`=28402;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='번개불꽃골록은 우리 중에서 싸움을 제일 잘해... 울바르와 했던 싸움도 대부분 번개불꽃골록이 했어.', `MaleText_loc4`='灵鳍鳄鱼人是最强大的战士……他们参与了大多数对抗狼獾人的战斗。', `MaleText_loc5`='炫觸是我們之中最優秀的戰士...他們扛下了大部分面對獾狼怪的戰爭。', `MaleText_loc7`='Los Pavesa son algunos de los mejores luchadores de entre nosotros... Llevaron a cabo la mayor parte de la batalla contra los wolvar.' WHERE `ID`=28403;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='점쟁이 조합 중에서 번개불꽃골록을 제일 존경해... 감탄할 만큼 자기네 땅을 잘 지켜내거든.', `MaleText_loc4`='灵鳍神谕者是我最敬重的神谕者……他们勇敢地守护了自己的家园，令人钦佩啊。', `MaleText_loc5`='在所有神諭者中我是對炫觸最尊敬的...他們為了自己的土地挺身而出。', `MaleText_loc7`='De todos los Oráculos, siento mayor respeto por los Pavesa... Han defendido su tierra de forma admirable.' WHERE `ID`=28404;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수홀루는 위대한 자들이 남겨 놓았어... 네가 티탄이라 아는 존재 말이야.', `MaleText_loc4`='造物主将索乌霍鲁留在这里……我们口中的造物主，就是你熟知的泰坦。', `MaleText_loc5`='蘇-侯魯被諸神給遺棄了...你也許知道他們叫做泰坦。', `MaleText_loc7`='Los Magnos dejaron atrás a Soo-brada... puede que los conozcas como titanes.' WHERE `ID`=28405;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수홀루가 제단을 지키려 여기 남았다고 은 거라는 믿음이 들었어. 하지만, 알맞은 수정이 없으면 제단과 마찬가지로 수홀루는 아무 힘을 못써.', `MaleText_loc4`='我相信，造物主将索乌霍鲁留在这里保护祭坛。但是和祭坛一样，没有合适的水晶，他就没法发挥能力。', `MaleText_loc5`='我後來相信蘇-侯魯被遺棄至此是要保護神殿。但是就像這些神殿，沒有正確的水晶，他就毫無力量。', `MaleText_loc7`='He llegado a creer que dejaron a Soo-brada aquí para que cuidara de los santuarios, pero al igual que los santuarios, no tiene ningún poder sin los cristales adecuados.' WHERE `ID`=28406;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='울바르에 패배를 선사하자... 이 전투는 너무 오래 끌었어. 울바르가 대가를 치러야 해.', `MaleText_loc4`='让我们向狼獾人宣战吧……他们逍遥得太久了，应该付出代价。', `MaleText_loc5`='讓我們對獾狼怪作戰吧...這已經拖太久了。他們一定要付出代價。', `MaleText_loc7`='Llevemos la batalla ante los wolvar... Esto se ha alargado demasiado. Deben pagar.' WHERE `ID`=28407;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 번개불꽃골록은 울바르와 몇 날 며칠이나 싸웠어. 그런데 다른 점쟁이는 아무도 도와주러 오지 않아... 이게 말이 된다고 생각해?', `MaleText_loc4`='灵鳍鳄鱼人和狼獾人交战已经有段日子了，但至今没有其他神谕者前来帮忙……你觉得这件事正常吗？', `MaleText_loc5`='炫觸在這裡與獾狼怪連日交戰，可是沒有其他的神諭者前來伸出援手...你覺得這對嗎?', `MaleText_loc7`='Los Pavesa han estado luchando contra los wolvar aquí durante días, pero los demás Oráculos no han venido en su ayuda... ¿Te parece que eso está bien?' WHERE `ID`=28408;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지저분한 울바르 같으니. 뽀송피부들이 보증해도 더는 네놈을 참아줄 수 없어.', `MaleText_loc4`='卑鄙的狼獾人。我不管干皮人是不是会为你担保，但今天就是你的死期。', `MaleText_loc5`='可惡的獾狼怪。我不管這些乾皮人是否為你們作保，我不會忍耐你們的出現太久的。', `MaleText_loc7`='Sucio wolvar. No me importa si pielseca responde por ti, no soportaré tu presencia mucho tiempo más.' WHERE `ID`=28409;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 울바르가 계속 목숨을 부지하는 이유를 제대로 설명하는 게 좋을 텐데.', `MaleText_loc4`='你最好给我个说得过去的理由，不然我不会让这只狼獾人活命的。', `MaleText_loc5`='你最好給我一個好理由讓這頭獾狼怪繼續呼吸。', `MaleText_loc7`='Más vale que tengas una buena razón para dejar que este wolvar continúe respirando.' WHERE `ID`=28410;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직도 울바르와 친하게 지낸단 말이지? 그렇다면, 네가 우리한테 등 돌리고 다시 울바르 편에 서더라도 놀라지 않겠어.', `MaleText_loc4`='你对狼獾人还是很友好嘛？如果有一天你背叛我们，重新站在狼獾人那一边，我一点都不会吃惊！', `MaleText_loc5`='和獾狼怪仍然保持友善，嗯?當你背叛我們、再度支持他們，那我也一點也不會感到奇怪了。', `MaleText_loc7`='Aún eres amigo de los wolvar, ¿eh? Entonces no me sorprenderé cuando nos traiciones y te vuelvas a poner de su parte.' WHERE `ID`=28411;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='울바르와 계속 같은 편이라 이거지? 좋은 의도로 그러는 건 아니겠지.', `MaleText_loc4`='你和狼獾人是一伙的吧？你大概本来就心怀不轨。', `MaleText_loc5`='你有獾狼怪的朋友?也許你終究不懷好意。', `MaleText_loc7`='¿Te juntas con los wolvar? Quizá, después de todo, no tuvieras buenas intenciones.' WHERE `ID`=28412;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 한 포효 해.', `MaleText_loc4`='我咆哮起来是很可怕。', `MaleText_loc5`='我有強大的怒吼。', `MaleText_loc7`='Mi gruñido es poderoso.' WHERE `ID`=28413;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 여기, 철천지 원수 바로 옆에 서 있기는 한데. 아직 안 죽이고 있어. 이게 말이 된다고 생각해?', `MaleText_loc4`='敌人就站在我身旁，我却没有动手杀它……你觉得这件事正常吗？', `MaleText_loc5`='我在這裡，站在我的死敵身邊，而我尚未殺了它...你覺得這對嗎?', `MaleText_loc7`='Aquí estoy, de pie junto a mi enemigo mortal y aún no lo he matado... ¿te parece que eso está bien?' WHERE `ID`=28414;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐요, 이봐! 이건 절 소환한 분만 볼 수 있다고요.', `MaleText_loc4`='Hey, hey!  Only my summoner should be able to see this.', `MaleText_loc5`='欸，欸!只有召喚我的人可以看。', `MaleText_loc7`='¡Oye, oye! Solo mi invocador debería ser capaz de ver esto.', `FemaleText_loc1`='저기요, 저기! 이건 절 소환한 분만 볼 수 있거든요.', `FemaleText_loc4`='Hey, hey!  Only my summoner should be able to see this.', `FemaleText_loc5`='欸，欸!只有召喚我的人可以看。', `FemaleText_loc7`='¡Oye, oye! Solo mi invocador debería ser capaz de ver esto.' WHERE `ID`=28415;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 너에게 줄드락을 깨끗이 쓸어내는 임무를 맡기겠다.', `MaleText_loc4`='现在，我命令你去净化祖达克，达库鲁。', `MaleText_loc5`='我現在賦予你淨化祖爾德拉克的責任，德拉庫魯。', `MaleText_loc7`='Te encomiendo la limpieza de Zul’Drak, Drakuru.' WHERE `ID`=28416;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 실망시키면 너는 파멸하리라...', `MaleText_loc4`='令我失望，你就将迎来末日……', `MaleText_loc5`='令我失望的話，那你就等死吧...', `MaleText_loc7`='Decepcióname y será tu perdición.' WHERE `ID`=28417;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성공하면 더욱더 강력한 힘을 맛보게 될 것이다!', `MaleText_loc4`='获得成功，更加强大的力量就唾手可得！', `MaleText_loc5`='成功了，你就會得到更加強大的力量!', `MaleText_loc7`='Ten éxito, y tendrás un poder aún mayor.' WHERE `ID`=28418;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님의 뜻대로...', `MaleText_loc4`='遵命，我的主人。', `MaleText_loc5`='如你所願，主人。', `MaleText_loc7`='Como desee, amo.' WHERE `ID`=28419;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='속여서 미안하네, 친구. 다 자네를 생각해서 그런 게야.', `MaleText_loc4`='朋友，请原谅，我欺骗了你。这样是为了你好。', `MaleText_loc5`='老兄，原諒我的欺瞞。這全都是為了你好。', `MaleText_loc7`='Perdonar mi engaño. Todo ser por tu propio bien.' WHERE `ID`=28420;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='괜찮은 녀석이란 확신이 필요했거든...', `MaleText_loc4`='那时，你要证明自己的价值……', `MaleText_loc5`='你得證明你自己的價值...', `MaleText_loc7`='Necesitabas demostrar tu valor…' WHERE `ID`=28421;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='줄드락을 공략하려면 유능한 부하가 필요해, 친구. 진정한 힘을 다룰 줄 아는 자가 말일세.', `MaleText_loc4`='而我，则急需优秀的下属，能支配强大力量的下属，在祖达克为我效劳。', `MaleText_loc5`='我在祖爾德拉克需要有能力的手下，老兄。一個有資格掌握真正力量的手下。', `MaleText_loc7`='Mi necesitar subalternos dignos en Zul’Drak. Listos para ejercer verdadero poder.' WHERE `ID`=28422;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 알았겠지? 리치 왕께서는 복종하는 자에게 너그러우시다네.', `MaleText_loc4`='自己权衡一番吧。要知道，巫妖王陛下对于所有忠诚的仆从都非常慷慨。', `MaleText_loc5`='你現在親眼看到了。巫妖王對聽話的人都很大方來著。', `MaleText_loc7`='Encargate solo. El Rey Exánime ser generoso con los que obedecen. ' WHERE `ID`=28423;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 길을 따르게, 친구. 그러면 자네는 불멸을 맛보게 될 게야!', `MaleText_loc4`='朋友，只要踏上这条路，很快你也能成为不朽的存在！', `MaleText_loc5`='順著這條路走下去，老兄，很快你也會嚐到不朽的滋味!', `MaleText_loc7`='¡Seguir este camino, y pronto saborear la inmortalidad!' WHERE `ID`=28424;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 오늘 목격한 일을 잘 생각해 보게, $n.$b$b미래는 이미 기록되어 있네. 그걸 결정하는 것은 자네 몫이야, 친구.', `MaleText_loc4`='仔细回想今天你目睹的一切，$n。$B$B未来已经注定，你唯一需要考虑的只是你想在其中扮演怎样的角色。', `MaleText_loc5`='仔細考慮一下你今天見証的事情，$n。$b$b未來已經註定了。唯一尚待決定的，則是你要加入哪一邊了，老兄。', `MaleText_loc7`='Medita sobre lo que has visto hoy, $n.$B$BEl futuro ya está escrito. Solo te queda decidir qué papel vas a jugar en él, tron.' WHERE `ID`=28425;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가장 강력한 말리고스 정예 요원들이 저 위의 고리를 보호하고 있습니다. 그대 혼자 힘으로는 그들을 처리할 수 없지요. 그대에게 우리 용군단의 비룡을 부를 권한을 드리겠습니다. 비룡의 등에 올라타면 이곳 마력의 눈을 날아다니며 용의 강력한 마법을 사용할 수 있을 것입니다.', `MaleText_loc4`='玛里苟斯最强大的仆从守卫着上层的环。单凭你的力量，根本不可能战胜他们。我们将赋予你召唤幼龙的能力。你可以骑着幼龙在魔环飞翔并使用强大的龙族魔法。', `MaleText_loc5`='瑪里苟斯手下最強大的成員保護著上方的環。你一個人沒辦法打敗他們。我們可以給予你得以召喚我方軍團飛龍的力量。騎上一條飛龍，你就可以在奧核之眼中飛翔並且指揮強大的龍族魔法。', `MaleText_loc7`='Los agentes más poderosos de Malygos protegen los anillos superiores. En solitario, no tienes posibilidades de derrotarlos. Podemos otorgarte el poder de invocar a los dracos de nuestros Vuelos. Montado a lomos de un draco, podrás volar dentro de El Oculus y controlar la poderosa magia de los dragones.' WHERE `ID`=28426;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기에서 어디로 가는 겁니까?', `MaleText_loc4`='接下来，我们要去哪儿？', `MaleText_loc5`='所以我們要從這出發到哪裡呢?', `MaleText_loc7`='Bueno... ¿y ahora qué?', `FemaleText_loc1`='여기에서 어디로 가는 건가요?', `FemaleText_loc4`='接下来，我们要去哪儿？', `FemaleText_loc5`='所以我們要從這出發到哪裡呢?', `FemaleText_loc7`='Bueno... ¿y ahora qué?' WHERE `ID`=28427;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벨가리스트라즈 말이 맞아요. 시간이 부족해요! 당신 비룡은 이제 최고의 힘을 사용할 수 있어요. 그 힘을 사용해 에레고스를 물리쳐 줘요!', `MaleText_loc4`='贝加里斯塔兹说得没错，时间不多了！

幼龙的终极力量已经解封。使用它们的力量击败埃雷苟斯吧！', `MaleText_loc5`='貝加瑞斯塔茲說的是實話;時間緊迫!

你的飛龍力量已全部開啟。使用他們的力量來打敗伊瑞茍斯。', `MaleText_loc7`='Belgaristrasz dice la verdad; ¡el tiempo se agota!

El poder completo de tus dracos ha sido desbloqueado. ¡Usa su poder para derrotar a Eregos!' WHERE `ID`=28428;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='벨가리스트라즈 말이 옳습니다. 상황이 매우 심각해요. 그대의 비룡은 이제 최고의 힘을 사용할 수 있습니다. 그 힘을 사용해 에레고스를 격파하세요!', `FemaleText_loc4`='贝加里斯塔兹说得没错，情况非常危急。

幼龙的终极力量已经解封。使用它们的力量击败埃雷苟斯吧！', `FemaleText_loc5`='貝加瑞斯塔茲說的是實話;情況的確很嚴重。

你的飛龍力量已全部開啟。使用他們的力量來打敗伊瑞茍斯。', `FemaleText_loc7`='Belgaristrasz dice la verdad, la situación es en efecto grave. 

Se ha desbloqueado todo el poder de tus dracos. ¡Úsalo para derrotar a Eregos!' WHERE `ID`=28429;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 이겼다!', `MaleText_loc4`='Yay we win! [PH]', `MaleText_loc5`='耶我們贏了! [PH]', `MaleText_loc7`='Yay we win! [PH]' WHERE `ID`=28430;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고대의 신이시여, 간청합니다. 저희는 어떻게 해야 합니까? 이 땅의 신들을 구하려면 어떻게 해야 하겠습니까?', `MaleText_loc4`='上古之神，我们乞求你的帮助。我们应该怎么做，才能拯救这片土地的神灵？', `MaleText_loc5`='上古神祇，我們懇求你。我們到底要怎麼做?我們要如何才能拯救這片土地的神祇?', `MaleText_loc7`='Dioses antiguos, os suplicamos. ¿Qué debemos hacer? ¿Cómo podemos salvar a los dioses de esta tierra?' WHERE `ID`=28431;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='점박이 무늬를 찾아야 한다. 그들의 운명은 서로 엉켜 있다.', `MaleText_loc4`='必须找到雪豹女神。他们的命运与此休戚相关。', `MaleText_loc5`='一定得找到那個滿身斑點的人。他們之間的命運緊密的糾纏在一起。', `MaleText_loc7`='Hay que buscar al moteado. Sus destinos están entrelazados.' WHERE `ID`=28432;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 그녀는 구속되어 있다. 그녀를 해방해 줄 방법을 찾아야 한다.', `MaleText_loc4`='不过她被锁住了。必须设法搭救她。', `MaleText_loc5`='但是她被束縛住了。一定得找到方法來釋放她。', `MaleText_loc7`='Pero está encadenada. Hay que encontrar un modo de liberarla.' WHERE `ID`=28433;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 필멸의 존재가 그녀의 제단까지 가야 한다. 쉽지 않겠지. 어쩌면 불가능한 일일 수도 있다.', `MaleText_loc4`='这名凡人必须前往她的祭坛。他们必将肩负起艰难的使命，甚至可能面临失败的惨境。', `MaleText_loc5`='如果要前往她的祭壇，這個凡人一定得遠行。他們得做的事一點都不輕鬆。結果可能會是失敗。', `MaleText_loc7`='Este mortal debe viajar hasta su altar. Lo que deben hacer no será fácil. Al final puede que resulte imposible.' WHERE `ID`=28434;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 시도조차 하지 않으면 모든 것을 잃을 게다. 드라카리는 그들의 신과 자신을 모두 죽이게 될 것이다!', `MaleText_loc4`='但是他们必须尝试，否则一切都完了。达卡莱巨魔很可能将自己和他们崇拜的神灵送上绝路！', `MaleText_loc5`='但是他們一定要試試看，否則所有的東西都會消失。德拉克瑞本身及他們的神祇都會死去!', `MaleText_loc7`='Pero deben intentarlo o todo estará perdido. ¡Los Drakkari acabarán con ellos y con sus dioses!' WHERE `ID`=28435;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신들께서 말씀하셨네, $n. 자네가 무엇을 해야 하는지 알겠군.', `MaleText_loc4`='神灵做出了指示，$n。你必须承担起这项艰难的使命。', `MaleText_loc5`='神祇說話了，$n。我們現在知道你們必須做的事了。', `MaleText_loc7`='Los dioses han hablado, $n. Ahora sabemos qué debes hacer.' WHERE `ID`=28436;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 죽음의 기사보다 스컬지에 대해 잘 아는 자들은 없소.$b$b나를 믿으시오, $r|1이여;여;. 불을 끌 때는 불로써 상대하는 게 제일이니까...', `MaleText_loc4`='没有谁比死亡骑士更了解天灾军团。$B$B相信我，$r。全力火拼，以牙还牙才是最奏效的战争策略。', `MaleText_loc5`='沒人比我們死亡騎士更了解天譴軍團了。$b$b相信我，$r，沒有什麼比以毒攻毒來的更加有用...', `MaleText_loc7`='Nadie conoce a la Plaga mejor que nosotros, los caballeros de la Muerte.$B$BCréeme, $r, no hay nada más eficaz que usar el fuego contra el fuego.' WHERE `ID`=28437;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='늙은 나스를 잘 대해주시오. 그는 당신만큼 젊지도, 예전만큼 강하지도 않소이다.', `MaleText_loc4`='对老纳斯宽容点。他年纪大了，体力早已不如从前。', `MaleText_loc5`='別急著處理納斯。他已經不再年輕，也不再像從前一樣強韌了。', `MaleText_loc7`='No le pidas demasiado al viejo Nass. Ya no es tan joven y fuerte como antaño.' WHERE `ID`=28438;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나스를 놓쳤습니다...', `MaleText_loc4`='我找不到纳斯了……', `MaleText_loc5`='我找不到納斯了...', `MaleText_loc7`='He perdido a Nass...', `FemaleText_loc1`='나스를 놓쳐버렸어요...', `FemaleText_loc4`='我找不到纳斯了……', `FemaleText_loc5`='我找不到納斯了...', `FemaleText_loc7`='He perdido a Nass...' WHERE `ID`=28439;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='늙은 나스가 어떻게 길을 찾아 돌아올지 모르겠군. 아마도 냄새를 맡고 찾아오겠지...', `MaleText_loc4`='老纳斯每次都能找到回来的路，真是奇怪。肯定是靠闻的吧……', `MaleText_loc5`='不確定老納斯為何總是找得到回來這裡的路。一定是用聞的吧...', `MaleText_loc7`='No sé cómo encuentra el viejo Nass el camino de vuelta a aquí. Debe de ser por el olor...' WHERE `ID`=28440;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='', `MaleText_loc4`='', `MaleText_loc5`='', `MaleText_loc7`='' WHERE `ID`=28441;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 생각엔...! 되도록 빨리 다른 일거리를 찾아야 할 것 같아요!', `MaleText_loc4`='我说！我必须另找一份谋生的活儿。', `MaleText_loc5`='我說啊!我只不過替自己找到另一種工作的方式。', `MaleText_loc7`='¡Lo digo! Solo tengo que buscarme otra línea de trabajo.' WHERE `ID`=28442;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 식으로 협조를 요청해 보시는 건 어떨까요? 어깨를 가볍게 두드린다든가...', `MaleText_loc4`='或许换个方式也能奏效啊。比如，只是拍拍肩膀？', `MaleText_loc5`='或許其他種方式在這裡可以成功。也許，只是拍拍肩膀?', `MaleText_loc7`='A lo mejor podemos llegar a otro tipo de acuerdo. Quizá una simple palmadita en el hombro...' WHERE `ID`=28443;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='', `MaleText_loc4`='', `MaleText_loc5`='', `MaleText_loc7`='' WHERE `ID`=28444;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='솔직히 말해 당신이 언제 날 걷어찰지 몰라서 신경이 곤두선다고요...', `MaleText_loc4`='真的，期望令人心烦意乱……', `MaleText_loc5`='真的，這是種讓人很不安的預感...', `MaleText_loc7`='En serio, es la expectación lo que me pone tan nervioso...' WHERE `ID`=28445;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아, 제발 이런 식으로 기억되지는 않았으면 좋겠는데...', `MaleText_loc4`='希望他们不是因为这点才记得我……', `MaleText_loc5`='我衷心希望這不是我所記得的那個...', `MaleText_loc7`='Espero que no se me recuerde por esto...' WHERE `ID`=28446;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 얼마나 부당한 취급을 당하고 있는지 잠깐 생각해 보실 수는 없나요?', `MaleText_loc4`='能不能将你的注意力转移到别人的臀部去？', `MaleText_loc5`='可以請你把注意力集中在另外那面屁股一會兒嗎?', `MaleText_loc7`='¿Podrías centrar tu atención en el otro carrillo un ratito?' WHERE `ID`=28447;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 상태를 치료할 방법을 찾아내는 날에는 스테판에게도 장화 맛을 보여 주겠어요.', `MaleText_loc4`='如果有机会治好我的毛病，我一定要让斯特凡尝尝这靴子的滋味。', `MaleText_loc5`='要是有人發現了治療我的方式，我會引介史戴芬去跟他的鞋子認識認識。', `MaleText_loc7`='Si alguna vez encuentran una cura para mi dolencia, me gustaría presentarle esta bota a Stefan.' WHERE `ID`=28448;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우욱! 설마 당신, 날 가지고 노는 건 아니겠지요...', `MaleText_loc4`='噢！我开始觉得，你在享受这一切……', `MaleText_loc5`='唔!我開始覺得你把我的損失當成一種趣味...', `MaleText_loc7`='¡Uf! Estoy empezando a pensar que te estás divirtiendo a mi costa...' WHERE `ID`=28449;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으윽! 방금 건 대단했어요...', `MaleText_loc4`='哎哟！你这一脚踢得真重……', `MaleText_loc5`='喔唔!你倒是很輕鬆啊你...', `MaleText_loc7`='¡Ayy! Tienes un buen golpe...' WHERE `ID`=28450;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으음! 방금 그건 힘을 좀 낭비하는 것 같은데요...', `MaleText_loc4`='啊！这一脚恐怕是白挨了。', `MaleText_loc5`='嗚唔!我很遺憾那個東西沒什麼用處。', `MaleText_loc7`='¡Uff! Me temo que hayamos malgastado esa.' WHERE `ID`=28451;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으어! 주변에서 트롤 냄새는 안 나는데요...', `MaleText_loc4`='呃！这附近好像没有巨魔，我闻不出他们的气味……', `MaleText_loc5`='哦!我沒聞到有食人妖在附近...', `MaleText_loc7`='¡Argh! No huelo a ningún trol por aquí...' WHERE `ID`=28452;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐요! 방금 그건 전혀 필요 없는 거잖아요!', `MaleText_loc4`='听着！你根本没理由踹我这一脚！', `MaleText_loc5`='給我聽好!那個完全不是我們要的!', `MaleText_loc7`='¡Ahora escucha! ¡Eso ha estado fuera de lugar!' WHERE `ID`=28453;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으윽! 당신... 이걸 즐기는 거지요?', `MaleText_loc4`='啊！你很享受是吧？', `MaleText_loc5`='好痛!你覺得很好玩，是嗎?', `MaleText_loc7`='¡Au! Disfrutas con esto, ¿verdad?' WHERE `ID`=28454;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오우! 아주 정확하게 걷어차시는군요. 조준은 정말 대단해요...', `MaleText_loc4`='哎哟！好吧，至少你的用意是好的。对你来说已经很难得了……', `MaleText_loc5`='噢!好吧，至少你的目標是正確的。我認為那是某種東西...', `MaleText_loc7`='¡Ooh! Bueno, al menos tu objetivo es real. Supongo que ya es algo...' WHERE `ID`=28455;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으악! 이런 꼴을 당할 줄 알았다면 스컬지를 떠나지 않았을 텐데!', `MaleText_loc4`='啊！每次你踹我的时候，我就怀疑自己离开天灾军团的决定是不是做错了。', `MaleText_loc5`='啊啊!像這種時候，我就會懷疑我幹嘛離開天譴軍團啊。', `MaleText_loc7`='¡Aahh! En momentos como estos, cuestiono mi decisión de dejar la Plaga.' WHERE `ID`=28456;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다 모으려면 아직 멀었나요?', `MaleText_loc4`='事情到底有完没完啊？', `MaleText_loc5`='到底結束了沒啊?', `MaleText_loc7`='¿Hemos acabado ya?' WHERE `ID`=28457;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스컬지 머리털을 한 뭉치 모을 때마다 내 존엄성도 조금씩 사라져 가는군요...', `MaleText_loc4`='每收集一束毛发，就损失一份尊严……', `MaleText_loc5`='多取得一綹天譴軍團的毛髮，就多失去了一點尊嚴...', `MaleText_loc7`='Otro mechón de pelo de la Plaga conseguido, otra pizca de dignidad perdida...' WHERE `ID`=28458;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어머니께서 이 꼴을 보셨다면...', `MaleText_loc4`='如果让妈妈看见我现在的模样……', `MaleText_loc5`='要是媽媽現在看到我的話...', `MaleText_loc7`='Si mi madre me viera ahora...' WHERE `ID`=28459;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 녀석이 마지막 놈이라면 정말 좋겠군요!', `MaleText_loc4`='我希望那是最后一个！', `MaleText_loc5`='我誠心的希望那一個是最後一個!', `MaleText_loc7`='¡Sinceramente espero que ese fuera el último!' WHERE `ID`=28460;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방금 녀석으로 끝난 것 같은데요.', `MaleText_loc4`='我们好像把什么东西给撞松了。', `MaleText_loc5`='我們用那最後一個把什麼給敲鬆了。', `MaleText_loc7`='Creo que has aflojado algo con ese último.' WHERE `ID`=28461;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘은 이 정도로 그만둔다고 하셔도 전 섭섭하지 않을 것 같은데요...', `MaleText_loc4`='如果你决定就此结束的话，我一点都不会失望……', `MaleText_loc5`='如果你決定今天到這就好了，我至少會開心點...', `MaleText_loc7`='No me molestará lo más mínimo si decides que hemos acabado por hoy...' WHERE `ID`=28462;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그가 줄드락으로 가자더군요. 이 난장판의 최고봉이라나요...', `MaleText_loc4`='他说，我们去祖达克。他说，这样我们才能查明真相……', `MaleText_loc5`='我們去他說的那個祖爾德拉克吧。他說，我們就可以知道這場混亂的原因...', `MaleText_loc7`='Vamos a Zul''Drak dice. Podemos llegar al fondo de este desastre dice...' WHERE `ID`=28463;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 때가 아닌데 나를 너무 일찍 깨웠다! 왜 이런 불경한 짓을 저지른 거냐?', `MaleText_loc4`='还早着呢，你居然这么早就吵醒我！到底有什么紧要事啊？', `MaleText_loc5`='太早了，你太早叫醒我了!這樣打擾我是什麼意思?', `MaleText_loc7`='Demasiado pronto, ¡me has despertado demasiado pronto! ¿Qué significa esta intromisión?' WHERE `ID`=28464;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아케루스의 눈을 사용할 수 있습니다.', `MaleText_loc4`='你控制了阿彻鲁斯之眼。', `MaleText_loc5`='你控制著亞榭洛之眼。', `MaleText_loc7`='El ojo de Acherus está bajo tu poder.' WHERE `ID`=28465;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐, 이 정도면 충분해! 난 갈게.', `MaleText_loc4`='我受够了！我要走了。', `MaleText_loc5`='好啦，夠了!現在就去。', `MaleText_loc7`='Bueno, ¡ya basta! Vamos.' WHERE `ID`=28466;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='윽! 아프네. 쩔뚝거리게 생겼어.', `MaleText_loc4`='啊！好痛。我只能一瘸一拐地挪动了。', `MaleText_loc5`='噢!痛耶。我得跛著腳走過這裡了。', `MaleText_loc7`='¡Au! Eso me ha dolido. Voy a cojear hasta allí.' WHERE `ID`=28467;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='골칫거리가 사라지면 다시 올게.', `MaleText_loc4`='等我们的处境安全之后我再回来。', `MaleText_loc5`='等我們不會被修理時我再回來。', `MaleText_loc7`='Volveré cuando no nos estén pateando el trasero.' WHERE `ID`=28468;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='썩 좋지 않네. 나중에 다시 와서 널 찾겠어.', `MaleText_loc4`='情况很糟糕啊。我待会再回来找你。', `MaleText_loc5`='做得不太好。我先回去，晚點再找你。', `MaleText_loc7`='No va tan bien la cosa. Volver a buscarte más tarde.' WHERE `ID`=28469;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청한 노예가 저놈들을 죽여야지, 저놈들이 고어게크를 죽이게 하면 안 된다!', `MaleText_loc4`='愚蠢的奴隶应该消灭敌人，确保格利基克的生命安全！', `MaleText_loc5`='蠢奴隸傢伙想要殺東西，不讓東西殺茍瑞格克!', `MaleText_loc7`='¡Se supone que estúpida cosa esclava tener que matar cosa, no dejar que las cosas maten a Goregek!' WHERE `ID`=28470;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다지크가 쓸모 있는 걸 또 알려주지! 스승이 얻어맞게 하지 마라. 이제 집으로 간다.', `MaleText_loc4`='再来听听达伊克的小建议！别让敌人伤害到你的老师。我得回家去了。', `MaleText_loc5`='達吉克的小秘訣!不要讓人痛打你的老師，現在可以回家了。', `MaleText_loc7`='¡Hora de recibir otro consejo inteligente de Dajik! No dejar que cosas peguen una paliza a tu profesor. Ahora ir a casa.' WHERE `ID`=28471;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오... 이제 돌아가도 되나? 너무 아프다... 우리가 미안하다.', `MaleText_loc4`='哎哟……我们现在回去没问题吧？痛死我了……我们真惨啊。', `MaleText_loc5`='呃...我們可以現在回去嗎?傷害了這麼多...我們很抱歉。', `MaleText_loc7`='Ay... ¿Poder volver ya? Doler mucho... nosotros sentirlo.' WHERE `ID`=28472;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알았어, 그거 아프잖아! 우리 여기는 빨리 넘어가자! 금방 돌아오자!', `MaleText_loc4`='好痛啊！我们要赶紧撤离这里！很快就会回来！', `MaleText_loc5`='好啦，真痛!我們要盡快經過這裡!快點回去!', `MaleText_loc7`='¡Vale, eso ha dolido! ¡Nosotros ir allí deprisa! ¡Volver pronto!' WHERE `ID`=28473;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 널 위해 죽을 리가 없지.', `MaleText_loc4`='要我为你搭上性命，没门。', `MaleText_loc5`='我絕對不會為你而死。', `MaleText_loc7`='No pienso morir por ti.' WHERE `ID`=28474;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 이거 재미있군!', `MaleText_loc4`='哈！真有趣！', `MaleText_loc5`='哈!這個部份最好玩了!', `MaleText_loc7`='¡Ja! ¡Esta ser parte divertida!' WHERE `ID`=28475;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 할 수 있기를 오랫동안 기다려왔지!', `MaleText_loc4`='我早就盼着再来祭坛捣蛋了！', `MaleText_loc5`='我等了超久才可以再做一次!', `MaleText_loc7`='¡He esperado tanto para volver a hacerlo!' WHERE `ID`=28476;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나를 믿어봐. 마음에 들 거다!', `MaleText_loc4`='相信我——你会喜欢的！', `MaleText_loc5`='相信我 - 你會愛死這個的!', `MaleText_loc7`='Confía en mí: ¡esto te va a encantar!' WHERE `ID`=28477;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날름이들아, 이거나 먹어라!', `MaleText_loc4`='尝尝厉害吧，大舌头怪！', `MaleText_loc5`='嚐嚐這個!大舌頭!', `MaleText_loc7`='¡Coméoslo lenguas-grandes!' WHERE `ID`=28478;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 동료가 지금 줄드락에서 일어나는 문제에 당신을 끌어들이기는 했지만, 근본적으로 우리 잔달라 부족이 여기 있는 주된 이유는 어떤 일이 일어나는지 관찰하고 제국의 멸망을 기록하고자 함입니다.', `MaleText_loc4`='我的同胞或许会让你探索祖达克的秘密，但是赞达拉氏族始终肩负着见证历史的使命，并将如实地记载巨魔帝国毁灭的篇章。', `MaleText_loc5`='雖然我的同胞讓你在祖爾德拉克事件中採取主動的角色，但我們贊達拉食人妖本來就是為了見證所有發生的事，並紀錄一個帝國的滅亡才來到此處。', `MaleText_loc7`='Aunque a mis compatriotas les gustaría que jugaras un papel activo en lo que está pasando en Zul''Drak, nosotros, los Zandalari, estamos aquí principalmente para ser testigos de lo que ocurre y redactar la crónica del final de un imperio.' WHERE `ID`=28480;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금, 샤트라스에 타우렌 족장들을 모셨습니다! 그들이 매시간 정각에 세상의 끝 선술집에서 펼치는 멋진 공연에 여러분 모두를 초대합니다!', `MaleText_loc4`='牛头人酋长乐队来到了沙塔斯城！就在天涯旅店，整点开始演出！', `MaleText_loc5`='現在，牛頭大佬出現在撒塔斯城!每小時整點，在世界的盡頭小酒館，現場演出!', `MaleText_loc7`='Ahora en la Ciudad de Shattrath: ¡los Tauren Chieftains! ¡Actuarán en la Taberna del Fin del Mundo en solo unos minutos!' WHERE `ID`=28481;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 배울 게 많다... 제일 중요한 건, 다지크를 보호하는 거다!', `MaleText_loc4`='你还有很多东西要学……最重要的一点，就是保护达伊克！', `MaleText_loc5`='你要學習的東西還很多...最重要的是，保護達吉克!', `MaleText_loc7`='Aún te queda mucho por aprender... lo más importante, ¡proteger a Dajik!' WHERE `ID`=28482;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다지크는 잠시 쉬어야겠다... 온몸이 상처투성이로군.', `MaleText_loc4`='达伊克要休息一会儿……全身都是伤。', `MaleText_loc5`='達吉克要去休息一下...渾身酸痛。', `MaleText_loc7`='Dajik va a descansar un poco... duele todo.' WHERE `ID`=28483;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부상이 심각할 때는 휴식을 취하고 힘을 되찾아라. 어떻게 하는 건지 다지크가 지금 보여주겠다...', `MaleText_loc4`='如果你受了重伤，一定要好好休息，恢复精力。达伊克现在就教你该怎么做……', `MaleText_loc5`='當你覺得非常疼痛時，記得休息一下，就會再變強壯了。達吉克現在就表演給你看...', `MaleText_loc7`='Cuando hacerte mucho daño, recordar descansar y recuperar fuerzas. Dajik enseñarte cómo ahora mismo...' WHERE `ID`=28484;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노예, 너는 실패 그 자체다.', `MaleText_loc4`='奴隶，你太令我失望了。', `MaleText_loc5`='奴隸東西，你真的很失敗。', `MaleText_loc7`='Cosa esclava, eres un fracaso con patas.' WHERE `ID`=28485;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오. 안 된다, 노예. 정말... 으엇!', `MaleText_loc4`='哎哟。没用的奴隶……哎哟！', `MaleText_loc5`='噢。不奴隸東西。真的...噢!', `MaleText_loc7`='Ay. No cosa esclava, en serio... ¡Ay!' WHERE `ID`=28486;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청한 노예가 계속 싸우는군... 이제 고어게크가 엉덩이 걷어차일 일은 없겠다.', `MaleText_loc4`='愚蠢的奴隶，继续战斗……格利基克不想再挨打了。', `MaleText_loc5`='蠢奴隸東西還在戰鬥...茍瑞格克現在不想再被踢屁股了。', `MaleText_loc7`='Estúpida cosa esclava continuar luchando... Goregek ir a no seguir recibiendo patadas en trasero.' WHERE `ID`=28487;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음이 다가온다! 파괴하라!', `MaleText_loc4`='我们被天灾盯上了！消灭它！', `MaleText_loc5`='死亡正在接近我們!消滅它!', `MaleText_loc7`='¡La muerte nos acecha a todos! ¡Destruidla!', `FemaleText_loc1`='죽음이 다가온다! 파괴하라!', `FemaleText_loc4`='我们被天灾盯上了！消灭它！', `FemaleText_loc5`='死亡正在接近我們!消滅它!', `FemaleText_loc7`='¡La muerte nos acecha a todos! ¡Destruidla!' WHERE `ID`=28488;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사라져라, 사악한 악마야!', `MaleText_loc4`='滚开，肮脏的恶魔！', `MaleText_loc5`='走開，邪惡的惡魔!', `MaleText_loc7`='¡Márchate, apestoso demonio!', `FemaleText_loc1`='사라져라, 사악한 악마야!', `FemaleText_loc4`='滚开，肮脏的恶魔！', `FemaleText_loc5`='走開，邪惡的惡魔!', `FemaleText_loc7`='¡Márchate, apestoso demonio!' WHERE `ID`=28489;
