UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스컬지다! 도망가게 두지 마라!', `MaleText_loc4`='天灾！别让它逃走！', `MaleText_loc5`='天譴軍團!別讓它逃了!', `MaleText_loc7`='¡Plaga! ¡No dejéis que escape!', `FemaleText_loc1`='스컬지다! 도망가게 두지 마라!', `FemaleText_loc4`='天灾！别让它逃走！', `FemaleText_loc5`='天譴軍團!別讓它逃了!', `FemaleText_loc7`='¡Plaga! ¡No dejéis que escape!' WHERE `ID`=28491;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청아! 쏘지 마! 게크게크가 저놈 멀쩡한 상태로 잡을 거다!', `MaleText_loc4`='笨蛋！停止射击！格利基克想要完整的战利品！', `MaleText_loc5`='蠢啊!別射它!茍瑞格克想要全屍啊!', `MaleText_loc7`='¡Estúpido! ¡No dispararle! ¡Gekgek querer trofeo de una pieza!' WHERE `ID`=28492;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도망치게 두면 안 돼! 이번에 꼭 잡는다.', `MaleText_loc4`='别让它逃走！这次一定要抓住它。', `MaleText_loc5`='別讓它逃走!這次我們逮到它了。', `MaleText_loc7`='¡No dejar que escape! Esta vez lo tenemos.' WHERE `ID`=28493;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='게크게크가 드디어 멍청한 고양이를 몰아넣었다. 넌 이제 내 거야!', `MaleText_loc4`='格利基克总算抓到你啦！你是格利基克的！', `MaleText_loc5`='杰克傑克終於抓到笨鬃松。你現在是杰克傑克的了!', `MaleText_loc7`='Gekgek por fin atrapar estúpido gato. ¡Tú ser de Gekgek ahora!' WHERE `ID`=28494;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심해! 그놈이 지난번처럼 할퀴지 못하게 해.', `MaleText_loc4`='当心！别像上次那样被它抓伤了。', `MaleText_loc5`='小心!別像上次一樣被它戳到。', `MaleText_loc7`='¡Cuidado! No dejes que te arañe como la última vez.' WHERE `ID`=28495;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신나는 박자에 맞춰 마음껏 흔들고 싶으십니까? 지금 세상의 끝 선술집으로 오십시오! 타우렌 족장들이 정시마다 멋진 무대를 선보입니다.', `MaleText_loc4`='你准备好进行一场狂欢了吗？那么就去天涯旅店吧！牛头人酋长乐队将在整点之后的十分钟开始演出！', `MaleText_loc5`='準備好搖滾了嗎?那就快去世界的盡頭小酒館吧!牛頭大佬每小時整點都有演出。', `MaleText_loc7`='¿Tienes ganas de rock? ¡Entonces dirígete a la Taberna del Fin del Mundo! El concierto de los Tauren Chieftains empieza al comenzar la hora.' WHERE `ID`=28496;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='용사여, 아직 눈을 감을 때가 아니다. 일어나라! 일어나 다시 한 번 싸워라!', `FemaleText_loc4`='勇士，今天不应该是你的死期。复活吧！站起来，再次投身战斗！', `FemaleText_loc5`='你命還不該絕，勇士。站起來!起來再戰一場!', `FemaleText_loc7`='Aún no es tu momento, $gcampeón:campeona;. ¡Levántate! ¡Levántate y lucha una vez más!' WHERE `ID`=28497;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런... 닭이 또 풀려났다.', `MaleText_loc4`='糟糕……不是吧。', `MaleText_loc5`='噢...別又來了。', `MaleText_loc7`='Ups... otra vez no.' WHERE `ID`=28498;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고어게크 또 닭장에 걸려 넘어졌나보다...', `MaleText_loc4`='格利基克好像又闯进鸡舍了……', `MaleText_loc5`='茍瑞格克好像又誤入雞籠了...', `MaleText_loc7`='A lo mejor Goregek ha tropezado con caseta de pollos otra vez...' WHERE `ID`=28499;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고어게크 닭들 풀어놓을 생각 없었다! 도와줘라!', `MaleText_loc4`='格利基克不是故意把鸡放走的！来帮帮忙啊！', `MaleText_loc5`='茍瑞格克不是故意要讓雞逃走的!幫幫忙喔!', `MaleText_loc7`='¡Goregek no querer dejar escapar a pollos! ¡Ayudar!' WHERE `ID`=28500;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고어게크 배고프... 어, 미안. 고어게크 사과한다.', `MaleText_loc4`='格利基克饿……哎呀，没有啦。格利基克错了。', `MaleText_loc5`='茍瑞格克餓...呃，對不起。茍瑞格克對不起。', `MaleText_loc7`='Goregek hambrien... esto, perdón. Goregek lo siente.' WHERE `ID`=28501;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가? 타우렌 족장들이! 무엇을? 실황 공연을! 어디에서? 세상의 끝 선술집에서! 언제? 매시간 정각에! 놓치면? 후회합니다!', `MaleText_loc4`='谁？牛头人酋长乐队！什么？现场演出？哪里？天涯旅店！时间？整点之后的十分钟！快去啊！', `MaleText_loc5`='誰?牛頭大佬!什麼?現場演出!哪裡?世界的盡頭小酒館!什麼時候?每小時整點!我要去!', `MaleText_loc7`='¿Quién? ¡Los Tauren Chieftains! ¿Qué? ¡En directo! ¿Dónde? ¡En la taberna del Fin del Mundo! ¿Cuándo? ¡Al comenzar la hora! ¡NO TE LO PIERDAS!' WHERE `ID`=28502;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불 켜는 중', `MaleText_loc4`='点火', `MaleText_loc5`='點火', `MaleText_loc7`='Relámpago', `FemaleText_loc1`='불 켜는 중', `FemaleText_loc4`='点火', `FemaleText_loc5`='點火', `FemaleText_loc7`='Relámpago' WHERE `ID`=28503;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타우렌 족장들! 그들의 숨 막히는 실황 공연이 세상의 끝 선술집에서 펼쳐집니다! 놓치지 마십시오, 매시간 정각입니다! 샤트라스에서 쫓겨나신 분이라고요? 어딘가 몰래 들어올 구멍이 있을 겁니다! 그 대신 걸려도 저는 책임 못 집니다!', `MaleText_loc4`='牛头人酋长乐队！在天涯旅店现场演出！整点之后十分钟就开始啦！千万不要错过！你被沙塔斯城放逐了？还不快潜回去！', `MaleText_loc5`='牛頭大佬!現場演出，就在世界的盡頭小酒館!立刻前往，每小時整點放送!要是被撒塔斯城放逐怎麼辦?給我溜進來!', `MaleText_loc7`='¡TAUREN CHIEFTAINS! ¡En DIRECTO, en la TABERNA DEL FIN DEL MUNDO! ¡No te lo pierdas, al comenzar la hora! ¿Desterrado de Shattrath? ¡INFÍLTRATE!' WHERE `ID`=28504;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이걸 봐라, 트롤... 선물이다!', `FemaleText_loc4`='嗨，巨魔……这是给你的礼物！', `FemaleText_loc5`='這裡，食人妖...一份禮物!', `FemaleText_loc7`='Toma, trol... ¡un regalo!' WHERE `ID`=28505;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나와 함께 말가니스를 상대할 준비가 되었는가?', `MaleText_loc4`='你准备好和我一起挑战玛尔加尼斯了吗？', `MaleText_loc5`='你準備好和我一同面對瑪爾加尼斯了嗎?', `MaleText_loc7`='¿Estás $gpreparado:preparada; para enfrentarte a Mal''Ganis junto a mí?' WHERE `ID`=28506;
