UPDATE `locales_broadcast_text` SET `MaleText_loc1`='증류기에 파파야를 넣게나!', `MaleText_loc4`='往蒸馏器里扔颗木瓜！', `MaleText_loc5`='在蒸餾器裡放一顆木瓜!', `MaleText_loc7`='¡Pon una papaya en el alambique!' WHERE `ID`=28517;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='증류기에 열이 부족하네! 화로를 켜게!', `MaleText_loc4`='蒸馏器温度过低！点燃火盆！', `MaleText_loc5`='需要加熱蒸餾器!把火盆點燃!', `MaleText_loc7`='¡El alambique necesita calor! ¡Enciende el blandón!' WHERE `ID`=28518;
