UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 결판을 낼 때다, 말가니스! 너와, 내가 말이다...', `MaleText_loc4`='让我们来做个了断吧，玛尔加尼斯。', `MaleText_loc5`='讓我們作個了斷吧，瑪爾加尼斯，就你跟我兩個。', `MaleText_loc7`='Acabaremos con esto ahora mismo, Mal''Ganis. Sólo tú y yo.' WHERE `ID`=28520;
