UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 가세요. 더는 보여드릴 게 없답니다.', `FemaleText_loc4`='走开。这里没什么好看的。', `FemaleText_loc5`='往前走。這裡沒什麼好看的。', `FemaleText_loc7`='Muévete. No hay nada que ver aquí.' WHERE `ID`=28525;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='<호기심 가득한 눈으로 쳐다보는 핏빛장미>$b$b놈들이 왜 그토록 당신에게 관심을 두는지 궁금하군요.$b$b나쁜 뜻은 없어요...', `FemaleText_loc4`='<血玫瑰好奇地打量着你。>$B$B你这样的家伙也能吸引大家的目光，真是奇怪。$b$b我没有侮辱你的意思……', `FemaleText_loc5`='<血玫好奇的看著你。>$b$b我無法不去懷疑你到底哪裡值得注意。$b$b無冒犯之意...', `FemaleText_loc7`='<Rosangre te observa con curiosidad.>$B$BNo puedo evitar preguntarme por qué te mereces tanta atención.$B$BNo te ofendas...' WHERE `ID`=28526;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스테판이 말하길, 당신이 이 목걸이의 용도를 알려줄 거라더군요.', `MaleText_loc4`='斯特凡说你可以示范要如何使用这东西。', `MaleText_loc5`='史戴芬跟我說你會示範這個東西的用途。', `MaleText_loc7`='Stefan me ha dicho que me mostrarías el propósito de este objeto.', `FemaleText_loc1`='스테판이 말하길, 당신이 이 목걸이의 용도를 알려줄 거라더군요.', `FemaleText_loc4`='斯特凡说你可以示范要如何使用这东西。', `FemaleText_loc5`='史戴芬跟我說你會示範這個東西的用途。', `FemaleText_loc7`='Stefan me ha dicho que me mostrarías el propósito de este objeto.' WHERE `ID`=28527;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너의 여정은 이제 막 시작이다, 젊은 왕자여. 병사들을 모아 극한의 땅, 노스렌드로 나를 찾아와라. 그곳에서 모든 일이 결판날 것이다. 네 진정한 운명도 그곳에서 시작되지.', `MaleText_loc4`='你的旅程才刚开始，年轻的王子。集合你的部队，到诺森德再次挑战我。在那里，我们将了结彼此之间的恩怨，你将了解到你真正的命运。', `MaleText_loc5`='你的旅途才剛開始，年輕的王子。召集你的軍隊，到北裂境的嚴寒之地來見我。在那裡，我們可以算算我們之間的新仇舊恨。你將在那裡理解你真正的命運。', `MaleText_loc7`='Recién comienza tu viaje, joven príncipe. Reúne a tus fuerzas y encuéntrame en las tierras árticas de Rasganorte. Allí será donde saldaremos nuestras cuentas pendientes, y donde se revelará tu verdadero destino.' WHERE `ID`=28528;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세상 끝까지라도 널 쫓아갈 것이다! 들리나? 끝까지 말이다!', `MaleText_loc4`='就算你跑到天涯海角，我也一定要抓到你！听到了吗？天涯海角！', `MaleText_loc5`='就算你跑到天涯海角，我也一定要抓到你!聽到了嗎?天涯海角!', `MaleText_loc7`='¡Te perseguiré hasta los confines de la tierra si es necesario! ¿Me oyes? ¡Hasta los confines de la tierra!' WHERE `ID`=28529;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 큰 공을 세웠군. 말가니스가 남긴 건 모두 너희 것이다. 보상으로 받아 둬라. 난 이제 노스렌드 원정 준비를 시작해야겠다.', `MaleText_loc4`='你们表现得很出色。玛尔加尼斯留下的一切都是你们的了，把它们收下作为奖励吧。现在我要马上开始计划远征诺森德了。', `MaleText_loc5`='你今天表現的很好。所有瑪爾加尼斯留下的東西都是你的。把這當成給你的獎勵吧。我現在必須開始進行遠征北裂境的計畫了。', `MaleText_loc7`='Lo hiciste bien hoy. Lo que Mal''Ganis haya dejado es tuyo. Tómalo como recompensa. Ahora debo planificar una expedición a Rasganorte.' WHERE `ID`=28530;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드라카리들은 죽기 직전 상태인 내 육신을 제단 건물에 가둬놓았다. 하지만, 놈들은 내 영혼을 볼 수 없지.$B$B우리가 힘을 합쳐야 놈들이 내 힘을 악용하는 것을 막을 수 있다.', `MaleText_loc4`='达卡莱巨魔将我囚禁在祭坛，令我的肉身处于濒死状况。但是他们无法看见我的灵魂。$B$B我们必须协同作战，阻止他们夺取我的力量。', `MaleText_loc5`='德拉克瑞一直將我的屍身在祭壇上保持半亡狀態。不過他們看不到我的靈魂。$B$B我們一定得聯手阻止他們得到我的力量。', `MaleText_loc7`='Los Drakkari están manteniendo mi cuerpo próximo a la muerte en el altar. Pero no pueden ver mi espíritu.$B$BDebemos trabajar juntos para evitar que consigan mi poder.' WHERE `ID`=28531;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='증류기를 돌릴 준비가 됐습니다... 어... 얼근이 씨.', `MaleText_loc4`='醉鬼，我准备好啦，可以开始蒸馏了。', `MaleText_loc5`='我準備好開始蒸餾了，嗯，醺醉。', `MaleText_loc7`='Estoy listo para empezar la destilación, eh, Chispa.', `FemaleText_loc1`='증류기를 돌릴 준비가 됐습니다... 어... 얼근이 씨.', `FemaleText_loc4`='醉鬼，我准备好啦，可以开始蒸馏了。', `FemaleText_loc5`='我準備好開始蒸餾了，嗯，醺醉。', `FemaleText_loc7`='Estoy lista para empezar la destilación, eh, Chispa.' WHERE `ID`=28532;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아! 정신 바짝 차리게나!', `MaleText_loc4`='很好！不要大意！', `MaleText_loc5`='做得好!繼續弄下去!', `MaleText_loc7`='¡Bien manejado! ¡Mantente alerta!' WHERE `ID`=28533;
