UPDATE `locales_broadcast_text` SET `MaleText_loc1`='됐네. 다음엔 뭐가 필요해질지 모르겠군...', `MaleText_loc4`='也行吧。不知道接下来应该加点什么……', `MaleText_loc5`='快完成了。永遠都不知道下一步會需要什麼...', `MaleText_loc7`='Eso servirá. Nunca se sabe qué necesitaré a continuación...' WHERE `ID`=28535;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위에 있는 구조물이 에너지와 공명하기 시작합니다.', `MaleText_loc4`='能量在水晶柱中涌动，发出低沉的嗡嗡声。', `MaleText_loc5`='上面的構造受到能量的影響，開始發出嗡嗡聲。', `MaleText_loc7`='La estructura de arriba comienza a zumbar con energía.' WHERE `ID`=28536;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='루노크, 당신의 마력으로 다시 힘을 얻고 싶습니다.', `MaleText_loc4`='伦诺克，我需要再次吸取你的精魄。', `MaleText_loc5`='魯諾克，我需要重新注入你的魔精。', `MaleText_loc7`='Rhunok, necesito que vuelvas a imbuirme con tu mojo.', `FemaleText_loc1`='루노크, 당신의 마력으로 다시 힘을 얻고 싶어요.', `FemaleText_loc4`='伦诺克，我需要再次吸取你的精魄。', `FemaleText_loc5`='魯諾克，我需要重新注入你的魔精。', `FemaleText_loc7`='Rhunok, necesito que vuelvas a imbuirme con tu mojo.' WHERE `ID`=28537;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서둘러라, $n. 나는 지금 엄청난 고통을 겪고 있는데 시간은 계속 흘러만 간다.', `MaleText_loc4`='请你快一点，$n。我承受着莫大的痛苦，时间已经不多了。', `MaleText_loc5`='請快點，$n。我非常的痛苦，時間也快沒了。', `MaleText_loc7`='Por favor, date prisa, $n. Me duele mucho y se nos agota el tiempo.' WHERE `ID`=28538;
