UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에 가만히 누운 채로 네놈의 손에 죽지는 않을 것이다! 날 죽이고 싶거든 숨 쉴 자격부터 구해봐라!', `MaleText_loc4`='我不会躺在这里等死的！凡人，想杀我的话，也得看看你有没有那个本事！', `MaleText_loc5`='我不會乖乖躺著讓你來宰了我!如果你想要殺我，你就得先得到活下去的權利，凡人!', `MaleText_loc7`='¡No me quedaré aquí tumbado para permitir que me mates! ¡Tendrás que ganarte el derecho de seguir respirando si quieres matarme, mortal!' WHERE `ID`=28544;
