UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마음에 쏙 드는군! 이걸 마시면 누구보다도 용감해질 수 있을 것이오.', `MaleText_loc4`='酿造得很成功啊！这酒的后劲还挺大的。', `MaleText_loc5`='我也同意!沒有別的東西比那對你的身體更好了。', `MaleText_loc7`='¡Tiene mi voto! ¡Eso pondrá pelo en tu pecho como ninguna otra cosa lo hará!' WHERE `ID`=28551;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스컬지 위장이 풀립니다. 안전한 곳을 찾으십시오!', `MaleText_loc4`='天灾伪装失效了！快找个安全的地方！', `MaleText_loc5`='天譴偽裝消失了!找個安全的地方!', `MaleText_loc7`='¡El disfraz de la Plaga está fallando! ¡Encuentra un lugar seguro!', `FemaleText_loc1`='스컬지 위장이 풀립니다. 안전한 곳을 찾으십시오!', `FemaleText_loc4`='天灾伪装失效了！快找个安全的地方！', `FemaleText_loc5`='天譴偽裝消失了!找個安全的地方!', `FemaleText_loc7`='¡El disfraz de la Plaga está fallando! ¡Encuentra un lugar seguro!' WHERE `ID`=28552;
