UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 항상 그림부즈가 만든 술에 관심이 많답니다.', `MaleText_loc4`='我对葛瑞姆酿造的酒总是充满兴趣的。', `MaleText_loc5`='我一直都對葛林布茲的東西很感興趣。', `MaleText_loc7`='Siempre me apetece un poco del de Tragoamargo.' WHERE `ID`=28554;
