UPDATE `locales_broadcast_text` SET `MaleText_loc1`='글쎄요, 지금까지는 우리 집사람이 마시던 거랑 비슷한 거 같은데...', `MaleText_loc4`='呃，我的妻子应该会喜欢这种果味酒……', `MaleText_loc5`='好吧，到目前為止，這嚐起來就像某種我老婆會喝的東西一樣...', `MaleText_loc7`='Bueno, por ahora, sabe como algo que bebería mi mujer...' WHERE `ID`=28556;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 바로 그림부즈의 술 맛이죠! 맘에 드는군요!', `MaleText_loc4`='哇，仔细品味后才发现口感一流啊！葛瑞姆总是能为我带来惊喜！我喜欢！', `MaleText_loc5`='現在，這就是我所期待的葛林布茲飲料所帶來的勁道!我喜歡!', `MaleText_loc7`='¡Sí, ese es el golpe que espero de una bebida de Tragoamargo! ¡Me gusta!' WHERE `ID`=28557;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그림부즈 썬더브루의 새 정글 펀치를 한 번 맛보시겠습니까?', `MaleText_loc4`='想尝尝葛瑞姆·雷酒新酿的丛林果酒吗？', `MaleText_loc5`='想要試看看葛林布茲·雷酒的新叢林潘趣酒嗎?', `MaleText_loc7`='¿Quieres probar el nuevo ponche salvaje de Tragoamargo Cebatruenos?', `FemaleText_loc1`='그림부즈 썬더브루의 새 정글 펀치를 한 번 맛보시겠어요?', `FemaleText_loc4`='想尝尝葛瑞姆·雷酒新酿的丛林果酒吗？', `FemaleText_loc5`='想要試看看葛林布茲·雷酒的新叢林潘趣酒嗎?', `FemaleText_loc7`='¿Quieres probar el nuevo ponche salvaje de Tragoamargo Cebatruenos?' WHERE `ID`=28558;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너 술 마시고 싶지?! 우리한테 술 있다!', `MaleText_loc4`='你想喝酒？我们有酒！', `MaleText_loc5`='你要喝酒?!那就給你酒喝!', `MaleText_loc7`='¡QUIERES BEBIDA! ¡TENEMOS BEBIDA!' WHERE `ID`=28559;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐 너! 오우거 맥주 마셔라! 크고 힘 세진다!', `MaleText_loc4`='嘿！喝食人魔的酒，变得更大更强！', `MaleText_loc5`='喂，就是你!喝巨魔酒!讓你又大又壯!', `MaleText_loc7`='¡OYE TÚ! ¡BEBE CERVEZAS DE OGROS! ¡TE HARÁN GRANDE Y FUERTE!' WHERE `ID`=28560;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맛을 봤으면 전부 마셔야지! 오우거 맥주!!', `MaleText_loc4`='食人魔美酒！值得品尝！', `MaleText_loc5`='你試過最好的了，現在試試其它的!巨魔酒!!', `MaleText_loc7`='¡HAS PROBADO LA MEJOR, AHORA PRUEBA LAS DEL MONTÓN! ¡CERVEZA OGRA!' WHERE `ID`=28561;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='되도록 빨리 빠져나가야겠군. 언데드에게 죽지 않아도 불에 타 죽게 생겼어.', `MaleText_loc4`='我们尽快离开这里。否则，就算不被亡灵杀死，也要被火烧死。', `MaleText_loc5`='我們盡快通過這裡吧。就否則就算那些不死生物沒殺了我們，我們也會葬身火海。', `MaleText_loc7`='Pasemos por aquí lo más rápido posible. Si sobrevivimos a los no-muertos, podríamos sucumbir al fuego.' WHERE `ID`=28562;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정의는 실현될 것이다.', `MaleText_loc4`='正义必将得到伸张。', `MaleText_loc5`='正義必將得到伸張。', `MaleText_loc7`='Se hará justicia.' WHERE `ID`=28563;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으어어... 저 조그만 구울 봐라.$b$b뛰어라, 작은 구울! 뛰어!$b$b하하하... 착한 작은 구울이군.', `MaleText_loc4`='嗷嗷……瞧那只食尸鬼。$b$b跳一下呀！跳一下！$b$b哈哈哈……真是一只可爱的食尸鬼。', `MaleText_loc5`='哇噢...看看那隻漂亮的小食屍鬼。$b$b跳啊，小食屍鬼!跳!$b$b哈，哈，哈...真是隻很棒的小食屍鬼。', `MaleText_loc7`='Oooh... midda al pequeño necrófago.$b$b¡Zalta, pequeñño! ¡Zalta!$b$bJua, jua jua... Buen pequeñño necrófago.' WHERE `ID`=28564;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우린 윅과 일꾼들이 저 벽 너머에 새로운 항구를 지을 수 있게 벽을 무너뜨리려고 해요. 그런데 우둔한 윅 녀석이 폭약을 너무 많이 쓰는 게 아니냐며 징징대잖아요!$B$B쳇. 난 녀석이 기저귀 차고 겨우 기어다닐 때부터 이 일을 해왔어요. 녀석이 계속 시끄럽게 굴면, 운하에 내던져버리고 작업을 전부 내 손으로 해버리겠어요!', `FemaleText_loc4`='我们打算将这面墙炸掉，让维克的人可以修建新的港口和道路，但是这个蠢货居然嫌我用了太多的炸药！$B$B哼。我玩爆破的时候，他小子还裹着尿布呢。大不了我一脚把他踹进运河，然后自己把这该死的活儿干完！', `FemaleText_loc5`='我們打算把這堵牆炸掉，這樣威克的人才能蓋新的海港警衛站跟後面的道路，但是那個無知的蠢蛋嫌我用掉太多火藥了!$B$B呿。當我在挖通道的時候他還包著尿布呢。我要把他踢進運河然後自己一個人把剩下的爆破工作完成，這還會花比較多的時間!', `FemaleText_loc7`='Etamos intentado volar este muro para que los hombres de Wick puedan trabajar en la nueva casa del guarda del puerto. ¡Sin embargo, el pesado este no tiene ni idea y cree que uso demasiada dinamita!$b$bPsé. Yo volaba cosas cuando él aún llevaba pañales. Como siga así voy a tirarlo al canal de una patada y terminar el maldito trabajo yo misma.' WHERE `ID`=28565;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 벽만 무너지면 스톰윈드 항구로 통하는 또 다른 길을 닦을 겁니다... 그런데 이 정신 나간 드워프가 마법사 지구 전체를 날릴 만한 폭약을 가져왔다고요!$B$B알렉스턴 씨가 무슨 생각으로 이 여자를 고용한 건지 도저히 모르겠습니다... 입버릇도 고약한 데다가 심술궂고, 게다가 완전히 황소고집이라니까요!', `MaleText_loc4`='我们计划等拆了这面墙之后开始修建另一条通往暴风城港口的路……但是这个疯狂的矮人带来的炸药足以把这整个区域都给炸上天！$B$B我不知道阿历克斯顿大人是怎么想的，居然会雇佣她……这个满嘴脏话、刁钻刻薄、像头牛一样固执的矮人！', `MaleText_loc5`='只要這堵牆拆掉，我們就要舖另外一條通往暴風港的路...但是那個瘋矮人用了足以移平整座廣場的火藥啦!$B$B我不曉得當初艾力克斯頓大人僱用她的時候腦袋在想什麼...她是個滿口髒話、刻薄成性、剛愎自用的人!', `MaleText_loc7`='Vamos a construir otra carretera hacia el Puerto de Ventormenta en cuanto quitemos esta pared... ¡Pero esta enana loca ha traído dinamita suficiente para nivelar todo el barrio!$B$BNo sé en qué estaba pensando el maestro Alexston cuando la contrató... ¡es malhablada, egoísta y terca como una mula!' WHERE `ID`=28566;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 어떻게 하지? 모든 걸 다 잃었는데!', `MaleText_loc4`='还能做些什么？我们已经失去了一切！', `MaleText_loc5`='我們能做什麼?我們什麼都沒有了啊!', `MaleText_loc7`='¿Qué vamos a hacer? ¡Lo hemos perdido todo!', `FemaleText_loc1`='이제 어떻게 하죠? 모든 걸 다 잃었는데!', `FemaleText_loc4`='还能做些什么？我们已经失去了一切！', `FemaleText_loc5`='我們能做什麼?我們什麼都沒有了啊!', `FemaleText_loc7`='¿Qué vamos a hacer? ¡Lo hemos perdido todo!' WHERE `ID`=28567;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리는 싸운다! 언제나 그랬듯이 놈들을 밀어붙여라!', `FemaleText_loc4`='勇敢地战斗！和以前一样，将天灾军团赶出我们的家园！', `FemaleText_loc5`='我們戰鬥!我們擊退他們，就跟我們一直以來做的一樣!', `FemaleText_loc7`='¡Luchamos! ¡Les hacemos retroceder, como hemos hecho siempre!' WHERE `ID`=28568;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='스컬지는 이 순수한 대지에 존재하는 한 점 흠이다. 내 창조주들의 힘으로 놈들의 묵은 뼛조각 하나까지 짓밟아 뭉개 버리겠다.', `FemaleText_loc4`='天灾军团玷污了这片古朴的土地。以伟大的造物主之名，我会将他们污朽的躯壳踩得粉碎。', `FemaleText_loc5`='天譴軍團是這片原始大地的污點。藉由我造物主的力量，我會連它們最後一丁點脆弱的骨頭都壓碎在我的腳下。', `FemaleText_loc7`='La Plaga es una mancha en estas prístinas tierras. Por el poder de los creadores, aplastaré hasta el último de sus decrépitos huesos bajo mi talón.' WHERE `ID`=28569;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 빛이 당신에게 뭐라고 말씀하십니까, 아벤디스!', `MaleText_loc4`='阿比迪斯，圣光给了什么新的指示！', `MaleText_loc5`='阿比迪斯，現在聖光跟你說了什麼!', `MaleText_loc7`='¿Qué te dice la Luz ahora, Abbendis?', `FemaleText_loc1`='지금 빛이 당신에게 뭐라고 말씀하시나요, 아벤디스!', `FemaleText_loc4`='阿比迪斯，圣光给了什么新的指示！', `FemaleText_loc5`='阿比迪斯，現在聖光跟你說了什麼!', `FemaleText_loc7`='¿Qué te dice la Luz ahora, Abbendis?' WHERE `ID`=28570;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛은 우리 아내와 자식을 구하러 나서주지 않았습니다!', `MaleText_loc4`='圣光没能拯救我的妻子和孩子！', `MaleText_loc5`='我可沒看到聖光出面來拯救我的老婆和孩子!', `MaleText_loc7`='¡No vi a la Luz intervenir para salvar a mi mujer e hijos!', `FemaleText_loc1`='빛은 우리 아내와 자식을 구하러 나서주지 않았어요!', `FemaleText_loc4`='圣光没能拯救我的妻子和孩子！', `FemaleText_loc5`='我可沒看到聖光出面來拯救我的老婆和孩子!', `FemaleText_loc7`='¡No vi a la Luz intervenir para salvar a mi mujer e hijos!' WHERE `ID`=28571;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 남편과 형제들도요!', `MaleText_loc4`='也没能拯救我的丈夫和兄弟！', `MaleText_loc5`='我的丈夫和兄弟也沒有!', `MaleText_loc7`='¡Ni mi marido ni hermanos!', `FemaleText_loc1`='우리 남편과 형제들도요!', `FemaleText_loc4`='也没能拯救我的丈夫和兄弟！', `FemaleText_loc5`='我的丈夫和兄弟也沒有!', `FemaleText_loc7`='¡Ni mi marido ni hermanos!' WHERE `ID`=28572;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛은 우리를 버렸습니다!', `MaleText_loc4`='圣光抛弃了我们！', `MaleText_loc5`='聖光遺棄我們了!', `MaleText_loc7`='¡La Luz nos ha abandonado!', `FemaleText_loc1`='빛은 우리를 버렸어요!', `FemaleText_loc4`='圣光抛弃了我们！', `FemaleText_loc5`='聖光遺棄我們了!', `FemaleText_loc7`='¡La Luz nos ha abandonado!' WHERE `ID`=28574;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='조용! 빛은 우리를 버리지 않았다! 빛은 순수한 자들 사이에서 그 어느 때보다도 더 강해진다!', `FemaleText_loc4`='肃静！圣光没有抛弃我们！只要你们保持内心的纯洁，它就能展现出比过去更加强大的力量！', `FemaleText_loc5`='安靜!聖光沒有遺棄我們!聖光在純潔的人心中前所未有的強大!', `FemaleText_loc7`='¡SILENCIO! ¡La Luz no nos ha abandonado! ¡La Luz es más fuerte que nunca entre los puros!' WHERE `ID`=28575;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안식골은 끝장이에요!', `MaleText_loc4`='海文郡沦陷了！', `MaleText_loc5`='避風郡失守了!', `MaleText_loc7`='¡Villa Refugio está perdida!', `FemaleText_loc1`='안식골은 끝장이에요!', `FemaleText_loc4`='海文郡沦陷了！', `FemaleText_loc5`='避風郡失守了!', `FemaleText_loc7`='¡Villa Refugio está perdida!' WHERE `ID`=28576;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마구간과 제재소는 포기했어요! 우리 말은 이제 어떻게 될까요?', `MaleText_loc4`='马厩和伐木场被遗弃了！我们的马匹怎么办？', `MaleText_loc5`='獸欄和磨坊都被棄守了!我們的馬下場會怎樣呢?', `MaleText_loc7`='¡Han abandonado los establos y el molino! ¿Qué pasará con nuestros caballos?', `FemaleText_loc1`='마구간과 제재소는 포기했어요! 우리 말은 이제 어떻게 될까요?', `FemaleText_loc4`='马厩和伐木场被遗弃了！我们的马匹怎么办？', `FemaleText_loc5`='獸欄和磨坊都被棄守了!我們的馬下場會怎樣呢?', `FemaleText_loc7`='¡Han abandonado los establos y el molino! ¿Qué pasará con nuestros caballos?' WHERE `ID`=28577;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마땅히 우리 소유인 것을 되찾고자 십자군을 보내는 중이다! 우리 길을 가로막는 스컬지는 모두 재가 되리라.', `FemaleText_loc4`='我们已经派出十字军部队，他们会夺回本属于我们的领地！天灾军团如果胆敢阻挠，定要将他们挫骨扬灰。', `FemaleText_loc5`='我們派出了十字軍去收復應當屬於我們的東西!任何擋住我們的天譴軍團都會屍骨無存。', `FemaleText_loc7`='¡Vamos a enviar cruzados a reclamar lo que es nuestro por derecho! ¡Convertiremos en cenizas a cualquier miembro de la Plaga que se interponga en nuestro camino!' WHERE `ID`=28578;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디에 머무르라는 말입니까? 신 아발론에 우리 전부가 있을 수는 없단 말입니다!', `MaleText_loc4`='你觉得我们能去哪儿？新阿瓦隆容不下这么多人！', `MaleText_loc5`='你打算要我們待在哪?新亞法隆沒辦法容納下我們所有的人!', `MaleText_loc7`='¿Dónde esperas que nos quedemos? ¡Nuevo Avalon no podrá cobijarnos a todos!', `FemaleText_loc1`='어디에 머무르라는 말인가요? 신 아발론에 우리 전부가 있을 수는 없단 말이에요!', `FemaleText_loc4`='你觉得我们能去哪儿？新阿瓦隆容不下这么多人！', `FemaleText_loc5`='你打算要我們待在哪?新亞法隆沒辦法容納下我們所有的人!', `FemaleText_loc7`='¿Dónde esperas que nos quedemos? ¡Nuevo Avalon no podrá cobijarnos a todos!' WHERE `ID`=28579;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='순결한 마음을 가진 자들은 신 아발론에 남을 수 있다. 성스러운 빛을 버렸다고 심문관이 판단한 이들은 추방당할 것이다.', `FemaleText_loc4`='所有人都必须接受审讯官的调查。内心纯洁的平民可以留在新阿瓦隆，被圣光摒弃的人则必须离开。', `FemaleText_loc5`='擁有純潔心靈的人將可以留在新亞法隆。而那些被審判官發現放棄聖光的人則會被驅逐。', `FemaleText_loc7`='Los de corazón puro podrán quedarse en Nuevo Avalon. Aquellos a quienes los inquisidores consideren privados del beneficio de la Luz sagrada serán rechazados.' WHERE `ID`=28580;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='군중들이 기가 막혀 말을 잇지 못합니다.', `MaleText_loc4`='人群骚动起来。', `MaleText_loc5`='群眾驚訝的倒抽了一口氣。', `MaleText_loc7`='La multitud queda boquiabierta.', `FemaleText_loc1`='군중들이 기가 막혀 말을 잇지 못합니다.', `FemaleText_loc4`='人群骚动起来。', `FemaleText_loc5`='群眾驚訝的倒抽了一口氣。', `FemaleText_loc7`='La multitud queda boquiabierta.' WHERE `ID`=28581;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만, 그대들이 걱정할 일은 일어나지 않을 것이오. 안 그렇소?', `MaleText_loc4`='但是你们并没有什么值得担心的啊，对吧？', `MaleText_loc5`='不過你們當中沒有人得去擔心這種事，對吧?', `MaleText_loc7`='Pero ninguno de ustedes tiene nada de que preocuparse, ¿verdad?' WHERE `ID`=28582;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저도 당신만큼이나 스컬지를 저지하고 싶습니다. 뭘 도와드리면 됩니까?', `MaleText_loc4`='我和你一样，希望能阻止天灾军团的入侵。我能帮上什么忙吗？', `MaleText_loc5`='我想要像你一樣去阻止天譴軍團。我可以幫忙什麼嗎?', `MaleText_loc7`='Tengo tantas ganas como tú de detener a la Plaga. ¿Cómo puedo ayudar?', `FemaleText_loc1`='저도 당신만큼이나 스컬지를 저지하고 싶어요. 뭘 도와드리면 되나요?', `FemaleText_loc4`='我和你一样，希望能阻止天灾军团的入侵。我能帮上什么忙吗？', `FemaleText_loc5`='我想要像你一樣去阻止天譴軍團。我可以幫忙什麼嗎?', `FemaleText_loc7`='Tengo tantas ganas como tú de detener a la Plaga. ¿Cómo puedo ayudar?' WHERE `ID`=28583;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='티탄들이 하룻밤 만에 갑자기 생명을 창조해내지는 않았다. 창조 작업은 서서히 진행됐으며 수도 없이 실험하고 되풀이해야 했지.$B$B그래서 숄라자르 분지처럼 철저하게 안전한 장소가 생겨난 것이다.$B$B실험했던 장소를 안전하게 지키고자, 티탄들은 수호 장치를 만들었다. 그 파괴력은 비할 데 없을 정도로 강력하지만, 여기서 내 뜻을 성실하게 따르겠다고 맹세하지 않으면 더는 밝히지 않겠다.', `FemaleText_loc4`='泰坦并非在一夜之间就创造出了所有生命。整个过程相当漫长，其中涉及大量的试验与叠代。$B$B因此，造物主看中了索拉查盆地，并将它改造成戒备森严的实验场所。$B$B为了确保安全，泰坦还制造出一台机械防御装置，它拥有无可匹敌的破坏力。除非你发誓对我效忠，否则我拒绝透露更多的机密。', `FemaleText_loc5`='泰坦並不是一夜之間就創造出生命體。這是個漸進，並需要大量實驗和重複的過程。$B$B因為那樣，才有像休拉薩盆地這種高度防護的地方存在。$B$B為了確保實驗地點的安全，泰坦們創造了一個防禦機器。不過，它所擁有的破壞性力量卻是前所未見，而我什麼都不會說，除非你發誓你會效忠於我的理念。', `FemaleText_loc7`='Los titanes no crearon la vida de la noche a la mañana. El proceso fue gradual y necesitó muchos experimentos e iteración.$B$BPor eso existen lugares tan protegidos como la Cuenca de Sholazar.$B$BPara mantener la seguridad de sus lugares de experimentación, los titanes crearon un mecanismo de defensa. Su fuerza destructiva no tiene igual y no te contaré nada más salvo que jures lealtad a mi causa.' WHERE `ID`=28584;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런 비밀을 너 같은 필멸의 존재에게 밝히는 일은 신성 모독에 가깝지만, 선택의 여지가 없구나.$B$B티탄들의 딸인 프레이야가 나를 이곳에 남겨 놓았을 때부터, 나는 절대 실패해서는 안 되는 임무를 하나 맡았다. 생명은 어떤 대가를 치르더라도 보호받아야 한다.$B$B이곳과 매우 흡사한 장소를 연결하는 차원문이 있다. 우리가 찾는 무기를 발견할 수 있는 곳이 바로 거기이다.', `FemaleText_loc4`='将造物主的秘密告知你这样的凡人，简直是对神灵的亵渎，但是我别无选择。$B$B泰坦的女儿弗蕾亚要我不惜一切代价保卫索拉查盆地的安全，这就是我留守此地的唯一目的。$B$B盆地内有一座大门，连接着另一块与这里的环境极其相似的土地。穿越那座大门，就能找到我们所说的秘密武器。', `FemaleText_loc5`='把這些秘密告訴像你這樣的凡人簡直是褻瀆，不過我也沒有多少選擇了。$B$B自從泰坦之女，芙蕾雅把我留在這裡進行唯一的任務，我不能失敗。必須不惜代價保護生命體。$B$B有一個甬道之門連結本地與另一處極為相似之地。在那，我們可以找到我們在找的武器。', `FemaleText_loc7`='Revelar estos secretos a un mortal como tú roza el sacrilegio, pero no tengo elección.$B$BDesde que Freya, hija de los titanes, me dejó aquí, solo he tenido una tarea en la que no puedo fracasar. La vida ha de ser protegida cueste lo que cueste.$B$BHay una puerta que une este lugar con otro muy parecido. Allí es donde se encuentra el arma que buscamos.' WHERE `ID`=28585;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='믿으셔도 됩니다. 전 리치 왕의 수하가 아닙니다.', `MaleText_loc4`='相信我。我不是巫妖王的朋友。', `MaleText_loc5`='你可以信任我。我不是巫妖王的朋友。', `MaleText_loc7`='Puedes confiar en mí. No soy amigo del Rey Exánime.', `FemaleText_loc1`='믿으셔도 괜찮아요. 전 리치 왕의 수하가 아니에요.', `FemaleText_loc4`='相信我。我不是巫妖王的朋友。', `FemaleText_loc5`='你可以信任我。我不是巫妖王的朋友。', `FemaleText_loc7`='Puedes confiar en mí. No soy amiga del Rey Exánime.' WHERE `ID`=28586;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실패하지 않을 겁니다.', `MaleText_loc4`='我不会令你失望的。', `MaleText_loc5`='我不會失敗。', `MaleText_loc7`='¡No fracasaré!', `FemaleText_loc1`='실패하지 않을 거예요.', `FemaleText_loc4`='我不会令你失望的。', `FemaleText_loc5`='我不會失敗。', `FemaleText_loc7`='¡No fracasaré!' WHERE `ID`=28587;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 살덩어리 밑에 뭘 숨겼지?', `MaleText_loc4`='你手里藏着什么？', `MaleText_loc5`='為什麼你要躲在那堆血肉之後?', `MaleText_loc7`='¿Qué escondes bajo ese pliegue de piel?', `FemaleText_loc1`='그 살덩어리 밑에 뭘 숨겼지?', `FemaleText_loc4`='你手里藏着什么？', `FemaleText_loc5`='為什麼你要躲在那堆血肉之後?', `FemaleText_loc7`='¿Qué escondes bajo ese pliegue de piel?' WHERE `ID`=28588;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 기지는 기어를 쓰지 않는 곳이지요. 기계 장치를 만들 때 기어를 사용하는 이는 계속 놀림거리가 될 걸요.', `MaleText_loc4`='哨站属于无齿轮区域。如果有谁在制造机械装置时使用齿轮，就会遭到无情的嘲笑。', `MaleText_loc5`='這個前哨是個無齒輪地區。在機器裝置建造上使用齒輪的人都會受到無情的嘲笑。', `MaleText_loc7`='Esta avanzada es una zona libre de engranajes. Las personas que usen engranajes en la construcción de dispositivos mecánicos serán ridiculizadas constantemente.' WHERE `ID`=28589;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저랑 같은 생각을 했나 보군요. 과일을 찾으시나 보죠?', `MaleText_loc4`='看来你和我的想法一样啊。你想找些水果，对吧？', `MaleText_loc5`='看來我和你有同樣的想法。你也是來採水果的，對吧?', `MaleText_loc7`='Parece que has tenido la misma idea que yo. Cazando fruta, ¿no?', `FemaleText_loc1`='저랑 같은 생각을 했나 보군요. 과일을 찾으시나 보죠?', `FemaleText_loc4`='看来你和我的想法一样啊。你想找些水果，对吧？', `FemaleText_loc5`='看來我和你有同樣的想法。你也是來採水果的，對吧?', `FemaleText_loc7`='Parece que has tenido la misma idea que yo. Cazando fruta, ¿no?' WHERE `ID`=28590;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로켄?! 이거 정말 귀찮아졌군... 무쇠 드워프는 무찌른 것 같습니다만, 아직 저 어딘가에 무쇠 브리쿨을 대량으로 뽑아내는 기계가 있나 봅니다!', `MaleText_loc4`='洛肯？！这下我们碰到大麻烦了……虽然铁矮人已经被全部摆平了，但我敢打赌不知道什么鬼地方还有台机器，正不停向外吐着铁维库人！', `MaleText_loc5`='洛肯?!這下麻煩了...我們雖然擺平了鐵矮人，但我敢說還有一台機器還在某個鬼地方不停生產出一票又一票的鐵維酷人!', `MaleText_loc7`='¡¿Loken?! Qué fastidio... Podríamos haber neutralizado a los enanos de hierro, ¡pero apuesto a qué hay otra máquina por ahí haciendo estragos con estos vrykul de hierro!' WHERE `ID`=28591;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아야! 어딜 당기십니까!', `MaleText_loc4`='哎哟！你拉哪儿呢！', `MaleText_loc5`='哎唷!小心你拉的位置!', `MaleText_loc7`='¡Ay! ¡Ten cuidado de dónde tiras!', `FemaleText_loc1`='아야! 어딜 당기세요!', `FemaleText_loc4`='哎哟！你拉哪儿呢！', `FemaleText_loc5`='哎唷!小心你拉的位置!', `FemaleText_loc7`='¡Ay! ¡Ten cuidado de dónde tiras!' WHERE `ID`=28592;
