UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 얼어붙은 시체 병사들을 불러냅니다.', `MaleText_loc4`='%s召唤出一支冰冻僵尸大军。', `MaleText_loc5`='%s喚來一批冰凍屍骸大軍。', `MaleText_loc7`='%s invoca un ejército de cadáveres congelados.' WHERE `ID`=28604;
