UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오그리마 외곽에는 두 개의 비행선 탑이 있네. 동쪽 탑은 티리스팔 숲과 가시덤불 골짜기로 가고, 서쪽 탑은 노스렌드와 썬더 블러프로 가지.', `MaleText_loc4`='奥格瑞玛城外有两座飞艇塔。东侧的飞艇塔开通了前往提瑞斯法林地和荆棘谷的航线，西侧的飞艇塔则用于飞往诺森德和雷霆崖。', `MaleText_loc5`='奧格瑪外有兩座飛艇塔。東部飛艇塔負責往來提里斯法林地與荊棘谷，而西部飛艇塔則負責往來北裂境和雷霆崖。', `MaleText_loc7`='Hay dos torres del zepelín a las afueras de Orgrimmar. La del este da servicio a los Claros de Tirisfal y a la Vega de Tuercespina, mientras que la del oeste da servicio a Rasganorte y a Cima del trueno.', `FemaleText_loc1`='오그리마 외곽에는 두 개의 비행선 탑이 있네. 동쪽 탑은 티리스팔 숲과 가시덤불 골짜기로 가고, 서쪽 탑은 노스렌드와 썬더 블러프로 가지.', `FemaleText_loc4`='奥格瑞玛城外有两座飞艇塔。东侧的飞艇塔开通了前往提瑞斯法林地和荆棘谷的航线，西侧的飞艇塔则用于飞往诺森德和雷霆崖。', `FemaleText_loc5`='奧格瑪外有兩座飛艇塔。東部飛艇塔負責往來提里斯法林地與荊棘谷，而西部飛艇塔則負責往來北裂境和雷霆崖。', `FemaleText_loc7`='Hay dos torres del zepelín a las afueras de Orgrimmar. La del este da servicio a los Claros de Tirisfal y a la Vega de Tuercespina, mientras que la del oeste da servicio a Rasganorte y a Cima del trueno.' WHERE `ID`=28606;
