UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서둘러라, 형제여! 우리가 언제까지 이 스컬지 괴물들을 막아낼 수 있을지 장담할 수 없다!', `MaleText_loc4`='兄弟们，快！天灾军团的攻势强劲，我不知道我们还能支撑多久！', `MaleText_loc5`='快點，兄弟!我不清楚還能抵擋這些天譴怪物多久的時間!', `MaleText_loc7`='¡Más rápido! ¡No sé durante cuánto tiempo más podremos retener a estos monstruos de la Plaga!', `FemaleText_loc1`='서두르십시오, 형제여! 우리가 언제까지 이 스컬지 괴물들을 막아낼 수 있을지 장담할 수 없습니다!', `FemaleText_loc4`='兄弟们，快！天灾军团的攻势强劲，我不知道我们还能支撑多久！', `FemaleText_loc5`='快點，兄弟!我不清楚還能抵擋這些天譴怪物多久的時間!', `FemaleText_loc7`='¡Más rápido! ¡No sé durante cuánto tiempo más podremos retener a estos monstruos de la Plaga!' WHERE `ID`=28609;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 빨리 일하라! 목재를 쌓아 신 아발론으로 보낼 준비를 마쳐야 한다!', `MaleText_loc4`='加把劲儿！将木材堆放入舱，准备运往新阿瓦隆！', `MaleText_loc5`='加倍你們的進度!我要你們把木材堆像山一樣高，準備妥運往新亞法隆的貨物!', `MaleText_loc7`='¡Dupliquen sus esfuerzos! ¡Apilen esta madera y prepárenla para enviarla a Nuevo Avalon!', `FemaleText_loc1`='더 빨리 일하라! 목재를 쌓아 신 아발론으로 보낼 준비를 마쳐야 한다!', `FemaleText_loc4`='加把劲儿！将木材堆放入舱，准备运往新阿瓦隆！', `FemaleText_loc5`='加倍你們的進度!我要你們把木材堆像山一樣高，準備妥運往新亞法隆的貨物!', `FemaleText_loc7`='¡Dupliquen sus esfuerzos! ¡Apilen esta madera y prepárenla para enviarla a Nuevo Avalon!' WHERE `ID`=28610;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 최선을 다하고 있습니다!', `MaleText_loc4`='我已经够快的了，上尉！', `MaleText_loc5`='我們已經盡可能的快了，隊長!', `MaleText_loc7`='¡Trabajo tan rápido como puedo, Capitán!' WHERE `ID`=28611;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 이 상태로는 일할 수 없습니다! 스컬지 손에 죽지 않는다면 전 피로로 죽을 겁니다!', `MaleText_loc4`='长官，我快吃不消了！就算我没死在天灾兵手里，也会活活累死啊！', `MaleText_loc5`='長官，我趕不上這速度!就算天譴軍沒殺了我，疲勞也不會放過我!', `MaleText_loc7`='¡No puedo seguir a este ritmo, señor! ¡Si la Plaga no acaba conmigo, el cansancio lo hará!' WHERE `ID`=28612;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠습니다!', `MaleText_loc4`='装载完毕！', `MaleText_loc5`='我這就去!', `MaleText_loc7`='¡Estoy en ello!' WHERE `ID`=28613;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 한 더미 있소! 비키시오!', `MaleText_loc4`='木材装载完毕！别挡道！', `MaleText_loc5`='準備好另外一堆出發!不要擋路!', `MaleText_loc7`='¡Otro montón preparado! ¡Apartad de mi camino!' WHERE `ID`=28614;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전쟁의 나팔이 울렸다! 시간이 없다! 서둘러라!', `MaleText_loc4`='战争的号角已经吹响！时间紧迫！加快速度！', `MaleText_loc5`='戰爭的號角已經響起!我們的時間不多了!加快你們的腳步!', `MaleText_loc7`='¡Han sonado los cuernos de guerra! ¡No tenemos mucho tiempo! ¡Acelerad el paso!', `FemaleText_loc1`='전쟁의 나팔이 울렸다! 시간이 없다! 서둘러라!', `FemaleText_loc4`='战争的号角已经吹响！时间紧迫！加快速度！', `FemaleText_loc5`='戰爭的號角已經響起!我們的時間不多了!加快你們的腳步!', `FemaleText_loc7`='¡Han sonado los cuernos de guerra! ¡No tenemos mucho tiempo! ¡Acelerad el paso!' WHERE `ID`=28615;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안식골이 언제 스컬지에게 정복당할지 모른다. 서둘러야 한다!', `MaleText_loc4`='天灾军团即将攻陷海文郡。我们必须加快速度！', `MaleText_loc5`='避風郡遲早會被天譴軍踏平，我們得快一點!', `MaleText_loc7`='Villa Refugio pronto será tomada por la Plaga. ¡Debemos darnos prisa!', `FemaleText_loc1`='안식골이 언제 스컬지에게 정복당할지 모른다. 서둘러야 한다!', `FemaleText_loc4`='天灾军团即将攻陷海文郡。我们必须加快速度！', `FemaleText_loc5`='避風郡遲早會被天譴軍踏平，我們得快一點!', `FemaleText_loc7`='Villa Refugio pronto será tomada por la Plaga. ¡Debemos darnos prisa!' WHERE `ID`=28616;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 다 죽이겠다!', `MaleText_loc4`='杀光他们！', `MaleText_loc5`='我們要殺光他們!', `MaleText_loc7`='¡Vamos a matarlos a todos!' WHERE `ID`=28617;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 하찮은 잔달라 부족을 쳐부숴 버려라!', `MaleText_loc4`='渺小的赞达拉巨魔将被碾得粉碎！', `MaleText_loc5`='渺小的贊達拉等這被粉碎吧!', `MaleText_loc7`='¡Los lamentable Zandalari serán aplastados!' WHERE `ID`=28618;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가라, 전사들아. 가서 짐토르가를 되찾아 오너라!', `MaleText_loc4`='骑兵连，出发！夺回希姆托加！', `MaleText_loc5`='上吧，我的打手，出發拿下辛托加!', `MaleText_loc7`='Adelante, mis asediadores. ¡Cabalgad y recuperad Zim''Torga!' WHERE `ID`=28619;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들 머리 열 개를 따오면 네가 간신히 옮길 수 있을 정도로 많은 금은보화를 내리겠다!', `MaleText_loc4`='如果你上缴10颗敌人的徽记，我就赏你满袋子的金币和宝石。', `MaleText_loc5`='如果你帶給我十顆他們的頭顱，我會給你拿都拿不動的金子和珠寶!', `MaleText_loc7`='¡Te daré todo el oro y las gemas que puedas llevar si me traes diez de sus cabezas!' WHERE `ID`=28620;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='눈이 멀었느냐? 놈들이 저기 있다. 죽여라!', `MaleText_loc4`='你瞎了吗？他们就在那儿。杀光他们！', `MaleText_loc5`='你瞎了嗎?他們就在那。殺了他們!', `MaleText_loc7`='¿Estás ciego? Están justo ahí. ¡Mátalos!' WHERE `ID`=28621;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 네놈이 보인다. 이리 올라와 이 드라카리를 벌레처럼 짓밟아 보거라.', `MaleText_loc4`='我看到你了。过来啊，让我们干掉这只达卡莱巨魔。', `MaleText_loc5`='我懂你的意思了。何不快點上來，我們一起把這個德拉克瑞交給蛆蟲處理。', `MaleText_loc7`='Te veo. ¿Por qué no subes y arreglamos esto como Drakkari y gusano?' WHERE `ID`=28622;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 짐토르가에서 나오지 않겠다면 모조리 불태워 버려라!', `MaleText_loc4`='如果他们不肯离开希姆托加，就将那里夷为平地！', `MaleText_loc5`='要是他們不願意離開辛托加，那就把它燒得一點不剩!', `MaleText_loc7`='Si no quieren salir de Zim''Torga, ¡reducidla a cenizas!' WHERE `ID`=28623;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잔달라, 은빛십자군, 스컬지... 네놈이 어느 편이든 상관없다. 벌레처럼 짓이겨 놓을 테니!', `MaleText_loc4`='我管你是赞达拉，银色北伐军，还是天灾兵……在我眼里，你就像只小虫子。我要捏碎你！', `MaleText_loc5`='贊達拉、銀白十字軍、天譴軍...我不管你是誰，我要把你像隻小蟲般捏死!', `MaleText_loc7`='Zandalari, Cruzada Argenta, Plaga... No me importa quién seas. ¡Voy a aplastarte como a un gusano!' WHERE `ID`=28624;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛의 수호자...', `MaleText_loc4`='光明使者……', `MaleText_loc5`='光明使者...', `MaleText_loc7`='El Iluminado...' WHERE `ID`=28625;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우서 경...', `MaleText_loc4`='乌瑟尔大人……', `MaleText_loc5`='烏瑟大人...', `MaleText_loc7`='Lord Uther...' WHERE `ID`=28626;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 북을 두드리는 놈이 누구냐?', `MaleText_loc4`='谁在敲我的鼓？', `MaleText_loc5`='到底是誰在敲我的鼓?', `MaleText_loc7`='¿Quién está golpeando mi tambor?' WHERE `ID`=28627;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내려가서 네놈을 끝장내 주마, $r!', `MaleText_loc4`='我要杀了你，$r！', `MaleText_loc5`='我要下去那裡好好殺你一頓，$r!', `MaleText_loc7`='¡Voy a bajar allí a matarte, $r!' WHERE `ID`=28628;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 넌 죽는다!', `MaleText_loc4`='受死吧！', `MaleText_loc5`='你死定了!', `MaleText_loc7`='¡Ahora vas a morir!' WHERE `ID`=28629;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 반짝이... 가져가. 이젠 다 끝이야...', `MaleText_loc4`='请收下……我亮闪闪的财宝。结束了……', `MaleText_loc5`='請收下...我的閃亮東西。都好了...', `MaleText_loc7`='Por favor coge... mis cositas brillantes. Todo acabado...' WHERE `ID`=28630;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살았다. 너 착해, 뽀송피부.', `MaleText_loc4`='我们得救啦。你真好，干皮人。', `MaleText_loc5`='我們得救了。你真好，乾皮。', `MaleText_loc7`='Nosotros salvados. Tú simpático, pielseca.' WHERE `ID`=28631;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이끼걸음골록의 부상이 심각한 것 같습니다.', `MaleText_loc4`='苔行鳄鱼人似乎受了重伤。', `MaleText_loc5`='這個苔行者看起來傷得很重。', `MaleText_loc7`='El Caminamoho parece gravemente herido.' WHERE `ID`=28632;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<맥박을 확인합니다.>', `MaleText_loc4`='<检测脉搏……>', `MaleText_loc5`='<探了他的脈搏...>', `MaleText_loc7`='<Comprueba el pulso...>', `FemaleText_loc1`='<맥박을 확인합니다.>', `FemaleText_loc4`='<检测脉搏……>', `FemaleText_loc5`='<探了他的脈搏...>', `FemaleText_loc7`='<Comprueba el pulso...>' WHERE `ID`=28633;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 발자국은 샨고의 것이 분명합니다.', `MaleText_loc4`='这些足迹一定是杉苟留下的。', `MaleText_loc5`='這些痕跡一定是屬於尚戈的。', `MaleText_loc7`='Este rastro debe de pertenecer a Shango.', `FemaleText_loc1`='이 발자국은 샨고의 것이 분명합니다.', `FemaleText_loc4`='这些足迹一定是杉苟留下的。', `FemaleText_loc5`='這些痕跡一定是屬於尚戈的。', `FemaleText_loc7`='Este rastro debe de pertenecer a Shango.' WHERE `ID`=28634;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 발자국은 샨고의 것이 아닙니다.', `MaleText_loc4`='这些不是杉苟的足迹。', `MaleText_loc5`='這些不是尚戈的痕跡。', `MaleText_loc7`='Este no es el rastro de Shango.', `FemaleText_loc1`='이 발자국은 샨고의 것이 아닙니다.', `FemaleText_loc4`='这些不是杉苟的足迹。', `FemaleText_loc5`='這些不是尚戈的痕跡。', `FemaleText_loc7`='Este no es el rastro de Shango.' WHERE `ID`=28635;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='용사들은 이 항구에서 스톰윈드와 루테란 마을을 오간답니다.', `FemaleText_loc4`='勇敢的旅者经由这座港口在暴风城和鲁瑟兰村之间往返。', `FemaleText_loc5`='從這個港口，勇氣號往返暴風城與魯瑟蘭村兩地。', `FemaleText_loc7`='Desde este muelle, El Valentía hace el viaje de ida y vuelta entre Ventormenta y Aldea Rut''theran.' WHERE `ID`=28636;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼음파괴자가 고동치는 파편을 시전합니다.', `MaleText_loc4`='破冰者开始施放跃动碎片。', `MaleText_loc5`='冰碎開始施展脈動裂片。', `MaleText_loc7`='Trizahielo comienza a lanzar Fragmentos pulsantes.' WHERE `ID`=28637;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이끼걸음골록 희생자가 고통 속에서 신음합니다.', `MaleText_loc4`='苔行村受害者发出痛苦的呻吟。', `MaleText_loc5`='苔行者受害者正痛苦的哀號著。', `MaleText_loc7`='La víctima Caminamoho gime de dolor.' WHERE `ID`=28638;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s의 가스 탱크가 절반쯤 채워졌습니다.', `MaleText_loc4`='%s的油量只剩下一半了。', `MaleText_loc5`='%s的燃料槽還有一半。', `MaleText_loc7`='El tanque de gas de %s está medio lleno.' WHERE `ID`=28639;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s의 연료가 거의 바닥났습니다.', `MaleText_loc4`='%s的油快耗光了。', `MaleText_loc5`='%s快要沒有燃料了。', `MaleText_loc7`='%s está casi lleno de combustible.' WHERE `ID`=28640;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 불쌍한 비행기. 예비 부품도 없는데 추락하면서 망가져 버렸어요. 다신 고쳐서 날 순 없을 거예요!', `MaleText_loc4`='我可怜的飞行器。她在坠机事故中遭到严重损坏，我偏偏没有备用零件。看样子她是没法恢复原貌了！', `MaleText_loc5`='我可憐的飛行器。她沒能撐過這場墜機，又沒有額外的零件。我永遠沒辦法修好她讓她運轉了!', `MaleText_loc7`='Mi pobre máquina voladora. ¡No sobrevivió al golpe y sin piezas de repuesto nunca podré arreglarla!' WHERE `ID`=28641;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피발굽이 자신을 돕도록 핏빛 구더기를 소환합니다!', `MaleText_loc4`='食血者召唤出血蛆帮忙！', `MaleText_loc5`='血饗召喚血蛆蟲來幫助他!', `MaleText_loc7`='¡Sangría invoca cresas de sangre para que lo ayuden!' WHERE `ID`=28642;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여보게, 친구.$b$b바쁘게 움직이게. 여긴 할 일이 아주 많으니 말일세.', `MaleText_loc4`='嗨，朋友。$B$B别站在那儿发呆。这里有很多事要做呢。', `MaleText_loc5`='欸，就你，老兄。$b$b別閒下來，這裡還有很多活好幹。', `MaleText_loc7`='Hola, tron.$B$BMantente ocupado. Hay mucho que hacer por aquí.' WHERE `ID`=28643;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조금만 기다리게, $n!$b$b곧 진정한 힘을 맛볼 걸세. 자네의 충성과 임무 수행에 대한 보상을 곧 받을 거라고.', `MaleText_loc4`='很快，$n！$B$B很快，你就能拥有真正的力量。很快，你的付出就能得到回报。', `MaleText_loc5`='很快，$n!$b$b很快你就會嚐到真正的力量。很快你也馬上就會因為你的貢獻與付出獲得獎賞。', `MaleText_loc7`='¡Pronto, $n!$B$BPronto probarás el auténtico poder. Pronto recibirás la recompensa por tu dedicación y servicio.' WHERE `ID`=28644;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='궤도에 올랐군, 필멸자여...$b$b견디게. 그럼 엄청난 힘을 얻을 테니!', `MaleText_loc4`='来吧，凡人……$B$B忍耐！你将拥有真正的力量！', `MaleText_loc5`='你正在這條道路上，凡人...$b$b忍耐，你就會得到無與倫比的力量!', `MaleText_loc7`='Estás en camino, mortal... $B$B¡Aguanta y conseguirás gran poder!' WHERE `ID`=28645;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 네가 그 영웅이로군. 네 꼬마 친구가 너희가 올 거라고 하더구나. 몸소 잡으러 나서는 수고를 덜어주었구나.', `MaleText_loc4`='啊，英雄。我听你的小伙伴说，你会来的。这样挺好的，省去了我亲自搜寻你的麻烦。', `MaleText_loc5`='啊，英雄們。你們的小朋友說過你們會來的。這可免去了我親自獵殺你們的麻煩。', `MaleText_loc7`='Oh, el héroe. Tus pequeños amigos dijeron que vendrías. Esto me ahorra el problema de tener que cazarte yo mismo.' WHERE `ID`=28646;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전쟁과 고통을 백 년이나 견디어 왔다. 진정 필멸의 존재가 불멸의 존재에 맞서는 일이 현명하다고 생각하는가? 감히 말하건대 네 쪽이 잃을 것이 더 많으리라.', `MaleText_loc4`='我经历了一百年的战争与痛苦。你真的觉得，凭着血肉之躯与不死生物作对是明智的选择吗？我敢说，你很可能会失败。', `MaleText_loc5`='我歷經了近百年的戰火與折磨，你真的覺得用你那平凡的軀體對抗一個不會死亡的生物是明智的抉擇嗎?我敢打賭你一定輸不起。', `MaleText_loc7`='He capeado cien años de guerra y sufrimiento. ¿Realmente crees que es sensato machacar tu cuerpo mortal contra un ser que no puede morir? Yo pronostico que tú tienes más que perder.' WHERE `ID`=28647;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='산산조각이 났어도, 사방에 있는 수정은 나를 약하게 한다... 티탄들을 그렇게 얕잡아보지 말았어야 했다...', `MaleText_loc4`='即便是碎裂成粉末，这些水晶依然在削弱我的力量……或许我不该低估泰坦的强大……', `MaleText_loc5`='即使附近的水晶裂成了數不盡的碎片，仍然使我越來越虛弱...也許我不該如此低估了泰坦...', `MaleText_loc7`='Incluso hechos añicos, los cristales que hay por todas partes me debilitan... quizá no debí haber subestimado a los titanes...' WHERE `ID`=28648;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용감하지만, 무지하기 짝이 없는 이 바보 둘은 서로 경멸하면서도, 너는 영웅이라고 말했다. 너희에게는 어느 한편에 설 의지가 없는 듯한데... 선택할 기회를 더 주어 보겠다.', `MaleText_loc4`='这两个有勇无谋的蠢货彼此厌恶，却异口同声地称你为英雄。你或许还不愿意做出选择……那么，就让我多给你一点时间吧。', `MaleText_loc5`='這兩個既勇敢又無知的蠢蛋都很討厭對方，但是，不知為何，他們異口同聲稱呼你是英雄。也許你只是缺乏選邊站的決心...讓我來給你這個機會吧。', `MaleText_loc7`='Estos dos valientes e ignorantes insensatos se odian, pero ambos se refirieron a ti como héroe. Quizá solo te falte la voluntad de elegir un lado... permíteme que te ofrezca esa oportunidad.' WHERE `ID`=28649;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아서스 님께서 힘... 같은 힘을 다시 찾으시면... 너는 그분과 같은 길을 따라가게 될 것이다.', `MaleText_loc4`='阿尔萨斯也曾拥有……同样的力量……或许你应该沿着他的足迹追寻力量。', `MaleText_loc5`='阿薩斯曾經匯集了力量...非常相近的力量...也許他的道路就是你該追隨的。', `MaleText_loc7`='Hace tiempo, Arthas mostró fuerza... del mismo tipo... quizá tú sigas su camino.' WHERE `ID`=28650;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위대하고 강력한 하르코아시여, 제가 들키지 않고 쿠에츠룬의 제단에 갈 수 있도록 여신님의 자손을 불러 주십시오.', `MaleText_loc4`='伟大的哈克娅，请召唤一名子嗣，让它将我悄悄地带进奎丝鲁恩祭坛。', `MaleText_loc5`='無所不能的哈寇亞，請呼喚你的子嗣之一，隱蔽的帶我進奎茲倫祭壇吧。', `MaleText_loc7`='Gran y poderosa Har''koa, por favor, llama a uno de tus hijos para que me lleve sigilosamente al Altar de Quetz''lun.', `FemaleText_loc1`='위대하고 강력한 하르코아시여, 제가 들키지 않고 쿠에츠룬의 제단에 갈 수 있도록 여신님의 자손을 불러 주십시오.', `FemaleText_loc4`='伟大的哈克娅，请召唤一名子嗣，让它将我悄悄地带进奎丝鲁恩祭坛。', `FemaleText_loc5`='無所不能的哈寇亞，請呼喚你的子嗣之一，隱蔽的帶我進奎茲倫祭壇吧。', `FemaleText_loc7`='Gran y poderosa Har''koa, por favor, llama a uno de tus hijos para que me lleve sigilosamente al Altar de Quetz''lun.' WHERE `ID`=28651;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구해 주셔서 감사합니다, $n 님. 보답으로 해드릴 수 있는 게 이 정도뿐이군요. 꼭 잡으세요. 출발합니다.', `MaleText_loc4`='谢谢你救了我，$n。这是我唯一能为你做的。握紧了，我们出发吧。', `MaleText_loc5`='$n，謝謝你救了我。我只能盡我微薄之力回報你的大恩。抓緊了。我們出發吧。', `MaleText_loc7`='Gracias por salvarme, $n. Esto es lo mínimo que puedo hacer para devolver el favor. Agárrate bien, allá vamos.' WHERE `ID`=28652;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꽉 붙잡으세요. 갑니다!', `MaleText_loc4`='握紧了，我们出发吧！', `MaleText_loc5`='抓緊啦，出發囉!', `MaleText_loc7`='Sujétate bien. ¡Allá vamos!' WHERE `ID`=28653;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상황이 좋아 보이진 않는군요. 뭘 하시든 간에 떨어지지는 마세요. 저기엔 역겨운 것들이 가득합니다!', `MaleText_loc4`='事情似乎不太顺利。千万别跌下去。那里满是肮脏的东西！', `MaleText_loc5`='這看起來一點也不好。不論你做了些什麼，別摔下去。那下面有一大堆壞東西在裡頭!', `MaleText_loc7`='Esto no tiene buena pinta. Hagas lo que hagas, no te caigas. ¡Hay montones de cosas horribles ahí!' WHERE `ID`=28654;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='므프흐므므 르므프흐히므므 르르후므그흐프흐?', `MaleText_loc4`='Mphmm rmphhimm rrhumghph？', `MaleText_loc5`='嗯呼嗯嗯嗯呼呼?', `MaleText_loc7`='¿Mphmm rmphhimm rrhumghph?' WHERE `ID`=28655;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이럴 수가... 쿠에츠룬 님께서 돌아가셨군요! 숨을 죽이세요. 예언자를 몰래 지나쳐 갈 겁니다.', `MaleText_loc4`='天哪……奎丝鲁恩死了！别动。我们偷偷绕过先知。', `MaleText_loc5`='噢，不會吧...奎茲倫死了!別動，我們偷偷溜過預言者。', `MaleText_loc7`='Oh no... ¡Quetz''lun está muerta! No te muevas. Pasaremos a escondidas junto al profeta.' WHERE `ID`=28656;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='르므무르프후므 므므프 흐므르프후므!', `MaleText_loc4`='Rmmurphum mmph hmrphum！', `MaleText_loc5`='嚕呣嚕呼呣呣呼呼嚕呼嗚!', `MaleText_loc7`='¡Rmmurphum mmph hmrphum!' WHERE `ID`=28657;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우므프흐루므 므므프후르, 무르루프흐루...', `MaleText_loc4`='Umphrum mmphur, murruphru……', `MaleText_loc5`='嗯呼呣呣呼，呣嚕呼嚕...', `MaleText_loc7`='Umphrum mmphur, murruphru...' WHERE `ID`=28658;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어, 저기... 줄드락 구경을 시켜주시겠습니까?', `MaleText_loc4`='呃，能带我在祖达克逛一圈吗？', `MaleText_loc5`='呃，你能送我一程前往祖爾德拉克嗎?', `MaleText_loc7`='Ehm, ¿puedes enviarme a dar una vuelta por Zul''Drak?', `FemaleText_loc1`='어, 저기... 줄드락 구경을 시켜주시겠어요?', `FemaleText_loc4`='呃，能带我在祖达克逛一圈吗？', `FemaleText_loc5`='呃，你能送我一程前往祖爾德拉克嗎?', `FemaleText_loc7`='Ehm, ¿puedes enviarme a dar una vuelta por Zul''Drak?' WHERE `ID`=28659;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='들켰습니다! 꽉 잡으세요. 여길 벗어나야 합니다!', `MaleText_loc4`='我们被发现了！别慌张。我们得离开这里！', `MaleText_loc5`='我們被發現了!撐住，我們得離開這裡!', `MaleText_loc7`='¡Nos han visto! Aguanta. ¡Tenemos que escapar de aquí!' WHERE `ID`=28660;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 해냈어요! 몸조심하세요, $n 님. 그리고 다시 한 번 감사합니다!', `MaleText_loc4`='成功啦！保重，$n。再次对你表示感谢！', `MaleText_loc5`='我們成功了!多保重，$n，再次感謝!', `MaleText_loc7`='¡Lo hemos conseguido! Cuídate, $n, ¡y gracias de nuevo!' WHERE `ID`=28661;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 사람 죽었어... 우리 자유야! 하룻강아지들 대신 우리 선택해서 기뻐. 아주 기뻐! 정말이지. 진짜 기뻐!', `MaleText_loc4`='他死了……我们自由啦！很高兴你能站在我们这一边，而不是与狗狗人为伍。我们很高兴！真的！非常高兴！', `MaleText_loc5`='他死了...我們自由了!我們很開心你選的是我們，不是小狗人。非常開心!真的，非常開心!', `MaleText_loc7`='¡Él muerto... nosotros libres! Nosotros contentos de que elegirnos en vez de hombres cachorros. ¡Muy contentos! Definitivamente. ¡Muy contentos!' WHERE `ID`=28662;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방금 뭐지? 침입자를 본 것 같은데. 녀석들을 찾아내서 죽여라!', `MaleText_loc4`='那是什么？我能感受到入侵者的气息。将他们揪出来杀掉！', `MaleText_loc5`='那是什麼?我感覺到入侵者。找出他們殺掉!', `MaleText_loc7`='¿Qué ha sido eso? Presiento que hay intrusos. ¡Encontradlos y matadlos!' WHERE `ID`=28663;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이미 비행은 시작되었소! 거기 덩굴 조심하시오!', `MaleText_loc4`='启航！当心那些藤蔓植物！', `MaleText_loc5`='我們下來了!注意那些藤蔓!', `MaleText_loc7`='¡Nos vamos! Cuidado con esas enredaderas!' WHERE `ID`=28664;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 전방 지역은 스컬지가 아주 심하게 공격한 것 같소...', `MaleText_loc4`='看来前面的区域已经被天灾军团清扫过了……', `MaleText_loc5`='看來，天譴軍已經對這個地方造成嚴重的傷害了...', `MaleText_loc7`='Parece que la Plaga ha causado estragos en esa zona de ahí delante...' WHERE `ID`=28665;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저거 봤소? 정말... 어마어마하게 크군!', `MaleText_loc4`='看见了吗？她……真大啊！', `MaleText_loc5`='你看到了嗎?她...很大!', `MaleText_loc7`='¿Ves...eso? ¡Es... enorme!' WHERE `ID`=28666;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 갑시다! 꽉 잡으시오. 전방에 풍향이 고르지 않소!', `MaleText_loc4`='来吧！坐稳啦——前面有强气流！', `MaleText_loc5`='出發吧!抓緊 - 前方的風正大著呢!', `MaleText_loc7`='¡Allá vamos! ¡Sujétate bien, el viento sopla fuerte ahí adelante!' WHERE `ID`=28667;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리에게 오고 있소! 그 로켓을 빨리 쏘시오!', `MaleText_loc4`='他们发动攻击了！当心那些火箭！', `MaleText_loc5`='他們直朝著我們過來!快閃開那些火箭!', `MaleText_loc7`='¡Vienen a por nosotros! ¡Date prisa con esos cohetes!' WHERE `ID`=28668;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아아아아악! 당했소! 이제 당신이 비행기를 조종해서 돌아가야 하오! 서두르시오. 비행기가 곧 폭발할지도 모르오!', `MaleText_loc4`='啊啊啊！被击中了！你得帮帮忙！快，趁飞行器还没有爆炸！', `MaleText_loc5`='啊啊啊!我被擊中了!你一定要把我們帶回去!快，飛機要爆炸了!', `MaleText_loc7`='¡Aggggh! ¡Me han dado! ¡Vas a tener que llevarnos de vuelta! ¡Rápido, antes de que el avión explote!' WHERE `ID`=28669;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이리 와라, 누더기골렘. 시킬 일이 있다!', `MaleText_loc4`='憎恶，我需要你的帮助！', `MaleText_loc5`='憎惡體，我需要你的協助!', `MaleText_loc7`='¡Abominación, necesito tu ayuda!', `FemaleText_loc1`='이리 와라, 누더기골렘. 시킬 일이 있다!', `FemaleText_loc4`='憎恶，我需要你的帮助！', `FemaleText_loc5`='憎惡體，我需要你的協助!', `FemaleText_loc7`='¡Abominación, necesito tu ayuda!' WHERE `ID`=28670;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 안전한 것 같습니다. 돌아갑시다!', `MaleText_loc4`='我想我们现在安全了。回去吧！', `MaleText_loc5`='我想，我們現在應該安全了。我們回去吧!', `MaleText_loc7`='Creo que ahora estamos a salvo. ¡Volvamos!' WHERE `ID`=28671;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이걸 언더시티에 있는 연금술사들에게 전달해라. 이번엔 소중한 표본이 소화돼 버리지 않게 해다오!', `MaleText_loc4`='将这些试验结果报告带去幽暗城，交给我们的药剂师。还有，别再把信吃了行不行？', `MaleText_loc5`='把這些結果帶到幽暗城給我們的藥劑師。拜託，這次不要再想要了解內容了?', `MaleText_loc7`='Llévales estos resultados a nuestros apotecarios en Entrañas. Y, por favor, esta vez procura no digerir el mensaje.', `FemaleText_loc1`='이걸 언더시티에 있는 연금술사들에게 전달해라. 이번엔 소중한 표본이 소화돼 버리지 않게 해다오!', `FemaleText_loc4`='将这些试验结果报告带去幽暗城，交给我们的药剂师。还有，别再把信吃了行不行？', `FemaleText_loc5`='把這些結果帶到幽暗城給我們的藥劑師。拜託，這次不要再想要了解內容了?', `FemaleText_loc7`='Llévales estos resultados a nuestros apotecarios en Entrañas. Y por favor, esta vez procura no digerir el mensaje.' WHERE `ID`=28672;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑습니다. 쉴 곳이 필요하신지요?', `MaleText_loc4`='欢迎光临。请问你想休息还是进餐？', `MaleText_loc5`='歡迎光臨。需要我提供休憩場所，還是糧食呢?', `MaleText_loc7`='Te doy la bienvenida. ¿Puedo ofrecerte descanso o sustento?', `FemaleText_loc1`='반갑습니다. 쉴 곳이 필요하신지요?', `FemaleText_loc4`='欢迎光临。请问你想休息还是进餐？', `FemaleText_loc5`='歡迎光臨。需要我提供休憩場所，還是糧食呢?', `FemaleText_loc7`='Te doy la bienvenida. ¿Puedo ofrecerte descanso o sustento?' WHERE `ID`=28673;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시키는... 대로... 한다... <트림>', `MaleText_loc4`='保证……完成……任务……<嗝>', `MaleText_loc5`='你的...就...快...做好...<嗝>', `MaleText_loc7`='Que... se cumpla... tu... voluntad...<eructo>', `FemaleText_loc1`='시키는... 대로... 한다... <트림>', `FemaleText_loc4`='保证……完成……任务……<嗝>', `FemaleText_loc5`='你的...就...快...做好...<嗝>', `FemaleText_loc7`='Que... se cumpla... tu... voluntad...<eructo>' WHERE `ID`=28674;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더럽고 냄새 나는 말 도둑 같으니!', `MaleText_loc4`='肮脏的偷马贼！', `MaleText_loc5`='骯髒發臭的偷馬賊!', `MaleText_loc7`='¡Sucio y apestoso ladrón de caballos!' WHERE `ID`=28675;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누구도 키트릭의 말을 훔칠 수 없어!', `MaleText_loc4`='没人能偷走基特里克的马！', `MaleText_loc5`='沒有人可以偷走基崔克的馬!', `MaleText_loc7`='¡Nadie le roba los caballos a Kitrik!' WHERE `ID`=28676;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 녀석은 곧 교수대에 매달릴 거다...', `MaleText_loc4`='你很快就会被绞死……', `MaleText_loc5`='你馬上就會被吊死在絞刑場上...', `MaleText_loc7`='Pronto estarás colgado en la horca...' WHERE `ID`=28677;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='몇 놈이나 더 뭉개서 리치 왕에게 돌려보내야 도둑질을 그만두려나...?', `MaleText_loc4`='我到底还要将多少具尸体送到巫妖王面前，他才肯罢休？', `MaleText_loc5`='在他停手前，我還得再將多少你們的碎片送還給巫妖王呢?', `MaleText_loc7`='¿A cuántos más de ustedes tengo que enviar hechos pedazos al Rey Exánime antes de que pare?' WHERE `ID`=28678;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 표본은 가망이 있어 보이는데. 어디서 났지?', `MaleText_loc4`='这份血样不错。是从哪儿弄来的？', `MaleText_loc5`='這份樣本很有希望成功。我們哪弄來的?', `MaleText_loc7`='Este espécimen parece prometedor. ¿De dónde lo hemos sacado?', `FemaleText_loc1`='이 표본은 가망이 있어 보이는데. 어디서 났지?', `FemaleText_loc4`='这份血样不错。是从哪儿弄来的？', `FemaleText_loc5`='這份樣本很有希望成功。我們哪弄來的?', `FemaleText_loc7`='Este espécimen parece prometedor. ¿De dónde lo hemos sacado?' WHERE `ID`=28679;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 표본은 인간 남자 걸세. 농부지. 자기 가족을 해치우고는 스톰윈드로 흘러들어왔다네.', `MaleText_loc4`='这份血样取自一位男性人类农民。他杀死家人后闯入了暴风城。', `MaleText_loc5`='這份樣本是一位男性人類。他殺害了他的家人，隨後遊蕩至暴風城。', `MaleText_loc7`='El espécimen era un humano. Un granjero. Mató a su familia y después vagó hasta Ventormenta.', `FemaleText_loc1`='그 표본은 인간 남자 걸세. 농부지. 자기 가족을 해치우고는 스톰윈드로 흘러들어왔다네.', `FemaleText_loc4`='这份血样取自一位男性人类农民。他杀死家人后闯入了暴风城。', `FemaleText_loc5`='這份樣本是一位男性人類。他殺害了他的家人，隨後遊蕩至暴風城。', `FemaleText_loc7`='El espécimen era un humano. Un granjero. Mató a su familia y después vagó hasta Ventormenta.' WHERE `ID`=28680;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 표본은 노움 여자한테서 난 걸세. 감염됐을 때조차 그 깜찍함 때문에 아무도 그녀를 멀리하지 않았지. 결국 다른 사람도 여럿 감염됐다네.', `MaleText_loc4`='这份血样取自一位女性侏儒。她的神情举止流露出难以抗拒的萌属性，人们在她面前总是会失去戒心。因此，她受感染轻易地又害了数十人。', `MaleText_loc5`='這個樣本是一位女性地精。即使被感染，在她被阻止以前，她那討人厭的可愛臉龐讓她親近並且感染了許多其他地精。', `MaleText_loc7`='El espécimen es una gnoma. Incluso estando infectada, es tan insufriblemente mona que ha conseguido acercarse e infectar a docenas de especímenes antes de ser detenida.', `FemaleText_loc1`='그 표본은 노움 여자한테서 난 걸세. 감염됐을 때조차 그 깜찍함 때문에 아무도 그녀를 멀리하지 않았지. 결국 다른 사람도 여럿 감염됐다네.', `FemaleText_loc4`='这份血样取自一位女性侏儒。她的神情举止流露出难以抗拒的萌属性，人们在她面前总是会失去戒心。因此，她受感染轻易地又害了数十人。', `FemaleText_loc5`='這個樣本是一位女性地精。即使被感染，在她被阻止以前，她那討人厭的可愛臉龐讓她親近並且感染了許多其他地精。', `FemaleText_loc7`='El espécimen es una gnoma. Incluso estando infectada, es tan insufriblemente mona que ha conseguido acercarse e infectar a docenas de especímenes antes de ser detenida.' WHERE `ID`=28681;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='소위 나를 숭배한다는 녀석들을 위해 만든 새로운 집이 마음에 드느냐?$B$B죽음의 모진 고통 속에서, 나는 그 모두를 저주했고 내가 만든 저승에 함께 끌고 왔지.$B$B녀석들이 영겁의 고통을 겪는 걸 보니 즐겁긴 하지만, 내가 진정 원하는 것은 내 옛 예언자 녀석에 대한 처절한 복수다!', `FemaleText_loc4`='你喜欢我为那些所谓的崇拜者创造的新家吗？$B$B临死前，我强忍着莫大的痛楚诅咒了他们，并将他们一同拖进了我所创造的异界。$B$B我可以随心所欲，这固然不错；但我真正希望的，是向先知寻仇！', `FemaleText_loc5`='你喜歡這個為了我所謂的信徒所刻出來的新居嗎?$B$B藉著我死亡的掙扎，我詛咒每一個人，把他們和我一道拖進這親手創出來的幽暗世界。$B$B我認為我會在他們無盡的折磨之中找到樂子，但是我真正的希望是對我之前的預言者進行復仇!', `FemaleText_loc7`='¿Te gusta el nuevo hogar que he tallado para mis llamados adoradores?$B$BEn mi lecho de muerte, los maldije a todos y los arrastré junto a mí a este inframundo especial que yo misma creé.$B$BCreo que me deleitaré con su tormento eterno, ¡pero lo que realmente ansío es vengarme de mi anterior profeta!' WHERE `ID`=28682;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 막강한 스컬지 군대를 소집합니다!', `MaleText_loc4`='%s召唤出天灾军团的大军！', `MaleText_loc5`='%s召喚出天譴軍強大的部隊!', `MaleText_loc7`='¡%s invoca a los poderosos ejércitos de la Plaga!' WHERE `ID`=28683;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스컬지 군대여, 내 말을 들어라! 붉은십자군 대참사가 시작됐다! 이 땅을 갈가리 찢어발기고, 너희가 지나간 자리에 죽음만을 남겨라!', `MaleText_loc4`='天灾军团，听我的号令！血色十字军的末日已经降临！攻占这片土地吧！', `MaleText_loc5`='天譴大軍，聽我的命令!血色天啟已經開始了!將大地撕成碎片，僅餘死亡作為結束!', `MaleText_loc7`='¡Ejércitos de la Plaga, escuchen mi llamada! ¡El apocalipsis escarlata ha comenzado! ¡Destrocen esta tierra y no dejen más que muerte a su paso!' WHERE `ID`=28684;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 그건 남자 오크의 피일세. 병균이 퍼지는 걸 막으려고 스스로 분신했지.', `MaleText_loc4`='男性兽人的血样。为了避免传染，他选择了自焚。', `MaleText_loc5`='這是一份男性獸人的血液。他企圖自焚以阻止感染的情況。', `MaleText_loc7`='Esa es la sangre de un orco. Se prendió fuego para detener su infección.', `FemaleText_loc1`='아, 그건 남자 오크의 피일세. 병균이 퍼지는 걸 막으려고 스스로 분신했지.', `FemaleText_loc4`='男性兽人的血样。为了避免传染，他选择了自焚。', `FemaleText_loc5`='這是一份男性獸人的血液。他企圖自焚以阻止感染的情況。', `FemaleText_loc7`='Esa es la sangre de un orco. Se prendió fuego para detener su infección.' WHERE `ID`=28685;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그건 타우렌 여자 걸세. 좀비가 들이닥쳤을 때 그녀는 마을 아이들을 돌보는 중이었지. 공격은 막아냈지만 좀비에게 물어뜯겨서 결국 쓰러지고 말았다네.', `MaleText_loc4`='女性牛头人的血样。僵尸入侵时，她正在照看村里的孩子。她成功地击退了敌人，却在混乱中被咬伤。很不幸，没等治愈她就一命呜呼了。', `MaleText_loc5`='那是一位女性牛頭人。當殭屍入侵的時候，她正看顧著村中的孩童。她阻止了攻擊，卻被咬了一口，屈服於瘟疫之前未能獲得治療。', `MaleText_loc7`='Esa es una tauren hembra. Estaba cuidando de los niños de su poblado cuando llegaron los zombis. Detuvo el ataque, pero le mordieron y no pudo curarse antes de sucumbir.', `FemaleText_loc1`='그건 타우렌 여자 걸세. 좀비가 들이닥쳤을 때 그녀는 마을 아이들을 돌보는 중이었지. 공격은 막아냈지만 좀비에게 물어뜯겨서 결국 쓰러지고 말았다네.', `FemaleText_loc4`='女性牛头人的血样。僵尸入侵时，她正在照看村里的孩子。她成功地击退了敌人，却在混乱中被咬伤。很不幸，没等治愈她就一命呜呼了。', `FemaleText_loc5`='那是一位女性牛頭人。當殭屍入侵的時候，她正看顧著村中的孩童。她阻止了攻擊，卻被咬了一口，屈服於瘟疫之前未能獲得治療。', `FemaleText_loc7`='Esa es una tauren hembra. Estaba cuidando de los niños de su poblado cuando llegaron los zombis. Detuvo el ataque, pero le mordieron y no pudo curarse antes de sucumbir.' WHERE `ID`=28686;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이상하군. 기록이 미완성이라서 표본의 유래를 알 수가 없네. 기록에는 그냥 "내가 죽였다!"라고 휘갈겨 써져 있는데... 피로 말이지.', `MaleText_loc4`='奇怪，这份血样的记录并不完整。标签上潦草地用血写着“我杀了它！”。', `MaleText_loc5`='怪了，這個人身上的紀錄並不完整，只寫道:「我殺了它!」用血液潦草地刮出這些字。', `MaleText_loc7`='Extraño, las anotaciones en este están incompletas. Solo dice "¡Lo maté!" con unos garabatos escritos con sangre.', `FemaleText_loc1`='이상하군. 기록이 미완성이라서 표본의 유래를 알 수가 없네. 기록에는 그냥 "내가 죽였다!"라고 휘갈겨 써져 있는데... 피로 말이지.', `FemaleText_loc4`='奇怪，这份血样的记录并不完整。标签上潦草地用血写着“我杀了它！”。', `FemaleText_loc5`='怪了，這個人身上的紀錄並不完整，只寫道:「我殺了它!」用血液潦草地刮出這些字。', `FemaleText_loc7`='Extraño, las anotaciones en este están incompletas. Solo dice "¡Lo maté!" con unos garabatos escritos con sangre.' WHERE `ID`=28687;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 우리 형제일세. 포세이큰 말이지. 경의를 갖고 다루게.', `MaleText_loc4`='它取自我们的同胞。被遗忘者。对他尊重些。', `MaleText_loc5`='那位是弟兄，一名被遺忘者。尊重的對待他。', `MaleText_loc7`='Ese es un hermano. Un Renegado. Trátalo con respeto.', `FemaleText_loc1`='이건 우리 형제일세. 포세이큰 말이지. 경의를 갖고 다루게.', `FemaleText_loc4`='它取自我们的同胞。被遗忘者。对他尊重些。', `FemaleText_loc5`='那位是弟兄，一名被遺忘者。尊重的對待他。', `FemaleText_loc7`='Ese es un hermano. Un Renegado. Trátalo con respeto.' WHERE `ID`=28688;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 그건 타우렌 남자의 표본일세. 주술사였지. 감염돼서 스스로 치료하기도 전에 죽고 말았어.', `MaleText_loc4`='男性牛头人的血样。这位萨满祭司被感染后，还没来得及治愈自己就被杀掉了。', `MaleText_loc5`='那位是個男性牛頭人。一位薩滿。他遭到感染，並且在治癒自己以前被殺害。', `MaleText_loc7`='Ese es un tauren macho. Un chamán. Fue infectado y lo mataron antes de que pudiera curarse.', `FemaleText_loc1`='아, 그건 타우렌 남자의 표본일세. 주술사였지. 감염돼서 스스로 치료하기도 전에 죽고 말았어.', `FemaleText_loc4`='男性牛头人的血样。这位萨满祭司被感染后，还没来得及治愈自己就被杀掉了。', `FemaleText_loc5`='那位是個男性牛頭人。一位薩滿。他遭到感染，並且在治癒自己以前被殺害。', `FemaleText_loc7`='Ese es un tauren macho. Un chamán. Fue infectado y lo mataron antes de que pudiera curarse.' WHERE `ID`=28689;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드워프 여성의 것일세. 성기사였지. 마지막 남은 마나를 쥐어짜 자기 대신 동료를 치료했다네.', `MaleText_loc4`='女性矮人的血样。这位圣骑士在临死前，用她仅剩的法力治疗了自己的同伴。', `MaleText_loc5`='她是一位女矮人。一位聖騎士。她在感染倒下前，用盡了最後的法力治療了她的同袍。', `MaleText_loc7`='Era una enana. Un paladín. Usó el maná que le quedaba curando a sus compañeros antes de sucumbir a su propia infección.', `FemaleText_loc1`='드워프 여성의 것일세. 성기사였지. 마지막 남은 마나를 쥐어짜 자기 대신 동료를 치료했다네.', `FemaleText_loc4`='女性矮人的血样。这位圣骑士在临死前，用她仅剩的法力治疗了自己的同伴。', `FemaleText_loc5`='她是一位女矮人。一位聖騎士。她在感染倒下前，用盡了最後的法力治療了她的同袍。', `FemaleText_loc7`='Era una enana. Un paladín. Usó el maná que le quedaba curando a sus compañeros antes de sucumbir a su propia infección.' WHERE `ID`=28690;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 땅 일부는 이미 나의 것일세, 친구. 하지만 그건 시작에 불과해!', `MaleText_loc4`='朋友，我已经占领了这里的部分土地，但这仅仅是个开始！', `MaleText_loc5`='這塊土地有一部份已經屬於我的了，老兄，但這只是個開始!', `MaleText_loc7`='¡Una parte de esta tierra ya es mía, tron, pero solo es el comienzo!' WHERE `ID`=28691;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 표본은 집중적으로 괴사했군. 유래가 어떻게 되나?', `MaleText_loc4`='这份血样完全坏死了。它是从哪儿来的？', `MaleText_loc5`='這份樣本顯示了高濃度的死亡之疽。它的病歷是?', `MaleText_loc7`='Este espécimen muestra necrosis concentrada. ¿Cuál es su historial?', `FemaleText_loc1`='이 표본은 집중적으로 괴사했군. 유래가 어떻게 되나?', `FemaleText_loc4`='这份血样完全坏死了。它是从哪儿来的？', `FemaleText_loc5`='這份樣本顯示了高濃度的死亡之疽。它的病歷是?', `FemaleText_loc7`='Este espécimen muestra necrosis concentrada. ¿Cuál es su historial?' WHERE `ID`=28692;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='특이한 혈액이로군... 이건 어디서 난 거지?', `MaleText_loc4`='这份血样非常奇特。从哪儿弄来的？', `MaleText_loc5`='這份血液中含有獨特的特性。他是從哪裡獲得的?', `MaleText_loc7`='Esta sangre tiene propiedades únicas. ¿Dónde fue obtenida?', `FemaleText_loc1`='특이한 혈액이로군... 이건 어디서 난 거지?', `FemaleText_loc4`='这份血样非常奇特。从哪儿弄来的？', `FemaleText_loc5`='這份血液中含有獨特的特性。他是從哪裡獲得的?', `FemaleText_loc7`='Esta sangre tiene propiedades únicas. ¿Dónde fue obtenida?' WHERE `ID`=28693;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 표본은 연구할 거리가 많군...', `MaleText_loc4`='我们能从这份血样中学到很多东西……', `MaleText_loc5`='我們可以從這份樣本中學到很多...', `MaleText_loc7`='Podríamos aprender mucho de este espécimen...', `FemaleText_loc1`='이 표본은 연구할 거리가 많군...', `FemaleText_loc4`='我们能从这份血样中学到很多东西……', `FemaleText_loc5`='我們可以從這份樣本中學到很多...', `FemaleText_loc7`='Podríamos aprender mucho de este espécimen...' WHERE `ID`=28694;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='심각하게 오염된 표본이로군! 도대체 어떻게 얻었나?', `MaleText_loc4`='这份血样被严重污染了！怎么会这样？', `MaleText_loc5`='這份樣本被高度感染了!這是怎麼拿到的?', `MaleText_loc7`='¡Esta muestra está muy infectada! ¿Cómo ha sido adquirida?', `FemaleText_loc1`='심각하게 오염된 표본이로군! 도대체 어떻게 얻었나?', `FemaleText_loc4`='这份血样被严重污染了！怎么会这样？', `FemaleText_loc5`='這份樣本被高度感染了!這是怎麼拿到的?', `FemaleText_loc7`='¡Esta muestra está muy infectada! ¿Cómo ha sido adquirida?' WHERE `ID`=28695;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 표본이 더 필요해. 누구 건가?', `MaleText_loc4`='我需要更多类似的样本。它取自何种生物？', `MaleText_loc5`='我需要更多這樣的樣本。它是誰?', `MaleText_loc7`='Necesito más muestras como esta. ¿Quién era?', `FemaleText_loc1`='이런 표본이 더 필요해. 누구 건가?', `FemaleText_loc4`='我需要更多类似的样本。它取自何种生物？', `FemaleText_loc5`='我需要更多這樣的樣本。它是誰?', `FemaleText_loc7`='Necesito más muestras como esta. ¿Quién era?' WHERE `ID`=28696;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최근 표본은 특이하군. 유래가 어떻게 되나?', `MaleText_loc4`='这份新鲜的血样很独特。有什么来历吗？', `MaleText_loc5`='最近的那個樣本很獨特。它的病歷是?', `MaleText_loc7`='Esta última muestra es única. ¿Cuál es su historial?', `FemaleText_loc1`='최근 표본은 특이하군. 유래가 어떻게 되나?', `FemaleText_loc4`='这份新鲜的血样很独特。有什么来历吗？', `FemaleText_loc5`='最近的那個樣本很獨特。它的病歷是?', `FemaleText_loc7`='Esta última muestra es única. ¿Cuál es su historial?' WHERE `ID`=28697;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 실험을 통해 많은 걸 알아낼 수 있을 거야...', `MaleText_loc4`='我们可以从试验中学到很多知识……', `MaleText_loc5`='我們可以從這些實驗裡面學到很多...', `MaleText_loc7`='Podemos aprender mucho con estos experimentos.', `FemaleText_loc1`='이 실험을 통해 많은 걸 알아낼 수 있을 거야...', `FemaleText_loc4`='我们可以从试验中学到很多知识……', `FemaleText_loc5`='我們可以從這些實驗裡面學到很多...', `FemaleText_loc7`='Podemos aprender mucho con estos experimentos.' WHERE `ID`=28698;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 빙하는 얼음왕관에서부터 흘러나오고 있군... 게다가 언데드까지 사방에 있다니! 여기는 학자께서 보실 때까지 그냥 두는 게 좋겠소!', `MaleText_loc4`='冰川正在逐渐扩展……到处都是亡灵！先等教授控制这里的局势吧！', `MaleText_loc5`='這條冰川一路從寒冰皇冠滲進來...不死生物到處都是!在教授控制住以前不要輕舉妄動!', `MaleText_loc7`='El glaciar se está filtrando desde Corona de Hielo... ¡y hay no-muertos por todas partes! ¡Espera hasta que la profesora se entere de esto!' WHERE `ID`=28699;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기, 독선적인 십자군 녀석들이 우리를 방해하고 있네. 녀석들은 파멸할 것이야!', `MaleText_loc4`='自以为是的北伐军挡住了我们前进的道路。他们注定会失败！', `MaleText_loc5`='這裡，自以為是的十字軍擋住了我們的目標。他們非死不可!', `MaleText_loc7`='Aquí esos cruzados justicieros se interponen en el camino de nuestro objetivo. ¡Deben caer!' WHERE `ID`=28700;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곧 이 모두가 리치 왕께 속할 걸세!', `MaleText_loc4`='很快，一切都将属于巫妖王！', `MaleText_loc5`='這些馬上都會成為巫妖王的囊中物!', `MaleText_loc7`='¡Todo esto pronto pertenecerá al Rey Exánime!' WHERE `ID`=28701;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잔돈은 필요 없다. 이 냄새 나는 짐승아!', `MaleText_loc4`='卑鄙的家伙，你这是自作自受！', `MaleText_loc5`='不用找錢了，你這污穢的禽獸!', `MaleText_loc7`='¡Y quédate con el cambio, sucio animal!' WHERE `ID`=28702;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음에 키트릭의 말을 훔치러 올 때는 과연 이게 잘하는 짓인가 싶겠지?', `MaleText_loc4`='下次偷基特里克的马之前，你最好考虑清楚，嗯？', `MaleText_loc5`='也許下次你打算偷基崔克的馬兒之前，會三思了吧，嗯?', `MaleText_loc7`='Quizás la próxima vez te lo pienses dos veces antes de robarle a Kitrik uno de sus caballos, ¿no crees?' WHERE `ID`=28703;
