UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 쓰러뜨리고 내가 탄 죽음의 군마를 빼앗아 봐라. 그게 산 자의 세계로 돌아가는 유일한 방법이지. 자, 죽음의 기사여, 준비됐나?', `MaleText_loc4`='死亡骑士，除非你能打败我并夺走死亡战马，否则你永远无法返回生者的世界。你准备好了吗？', `MaleText_loc5`='擊敗我，拿走我騎乘的死亡戰騎。死亡騎士，這是你想要贏得返回人世的唯一方法。你準備好了嗎?', `MaleText_loc7`='Vénceme y arrebátame el destrero de la muerte que cabalgo. Esa es la única manera de vencer y regresar al mundo de los vivos, caballero de la Muerte. ¿Estás $gpreparado:preparada;?' WHERE `ID`=28795;
