UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕의 은총을 바라는 놈이 또 있군?$b$b자격이 있는 자만이 암흑의 선물을 받을 것이다...', `MaleText_loc4`='想要赢得巫妖王的宠爱？$B$B有充分价值的人才能获得黑暗的礼物……', `MaleText_loc5`='又一個搖尾乞憐的人期望巫妖王饒他一命?$b$b只有值得的人才能獲得黑暗的禮物...', `MaleText_loc7`='¿Otra persona suplicando los favores del Rey Exánime?$B$BSolo los dignos obtienen los dones oscuros...' WHERE `ID`=28801;
