UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오십시오. 달라란 길드 사무소입니다. 무엇을 도와드릴까요?', `MaleText_loc4`='欢迎来到达拉然公会注册办事处。请问你需要什么帮助？', `MaleText_loc5`='歡迎來到達拉然公會註冊辦公室。有什麼需要我幫忙的嗎?', `MaleText_loc7`='Te doy la bienvenida a las oficinas del Registro de hermandades de Dalaran. ¿En qué puedo ayudarte hoy?', `FemaleText_loc1`='어서 오세요. 달라란 길드 사무소입니다. 무엇을 도와드릴까요?', `FemaleText_loc4`='欢迎来到达拉然公会注册办事处。请问你需要什么帮助？', `FemaleText_loc5`='歡迎來到達拉然公會註冊辦公室。有什麼需要我幫忙的嗎?', `FemaleText_loc7`='Te doy la bienvenida a las oficinas del Registro de hermandades de Dalaran. ¿En qué puedo ayudarte hoy?' WHERE `ID`=28804;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알았네. 분쟁 지역으로 돌아가게. 남는 인력은 좀비 역병의 희생자를 찾아내는 걸 최우선으로 하라고.', `MaleText_loc4`='知道了。立即返回战争区域。我们的战略目标是尽可能多地搭救那些感染的受害者。', `MaleText_loc5`='注意，返回衝突區，把我們的專注擺在邊境的努力上，把殭屍瘟疫的受害者帶回來。', `MaleText_loc7`='Entendido. Vuelve a las zonas conflictivas. Concentra nuestros esfuerzos en campo abierto en proporcionar más víctimas a la plaga de zombis.' WHERE `ID`=28805;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='목표는 단순하다. 날 죽이고 죽음의 군마를 빼앗아 가라.', `MaleText_loc4`='目标很简单：杀死我，夺走死亡战马。', `MaleText_loc5`='目標非常簡單:殺死我，並且拿走我的死亡戰騎。', `MaleText_loc7`='El objetivo es simple: mátame y coge mi destrero de la muerte.' WHERE `ID`=28806;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 위업을 달성하면 내 죽음의 군마를 데리고 여기 죽음의 틈으로 돌아와라. 그리고 기사의 부름을 사용해 산 자의 세상에서 살라나르를 불러내라.', `MaleText_loc4`='等你成功地完成这项创举后，就带着我的死亡战马返回死亡裂口，用骑手的召唤将萨拉纳尔从生者的世界召唤出来。', `MaleText_loc5`='若你真的完成了這項值得紀念的功績，回到死亡止境這裡來。帶著我的死亡戰騎，並且使用騎士的呼喚將撒拉納從生者的世界召喚過來。', `MaleText_loc7`='Si logras tener éxito en esta gesta monumental, vuelve aquí a Brecha de la Muerte, con mi Destrero de la muerte y usa la Llamada del jinete para invocar un Salanar del reino de los vivos.' WHERE `ID`=28807;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='퓨트리스 대연금술사님! 최전선에서 보고서를 가져왔습니다...', `MaleText_loc4`='大药剂师普特雷斯！我有来自前线的报告……', `MaleText_loc5`='大藥劑師普崔司!我把戰線的消息帶來了...', `MaleText_loc7`='¡Gran Boticario Putress! Vengo con un informe de los frentes de batalla...', `FemaleText_loc1`='퓨트리스 대연금술사님! 최전선에서 보고서를 가져왔습니다...', `FemaleText_loc4`='大药剂师普特雷斯！我有来自前线的报告……', `FemaleText_loc5`='大藥劑師普崔司!我把戰線的消息帶來了...', `FemaleText_loc7`='¡Gran Boticario Putress! Vengo con un informe de los frentes de batalla...' WHERE `ID`=28808;
