UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 아는 사람 모두 뭔가 나쁜 병에 걸린 것 같습니다.', `MaleText_loc4`='我身边的人似乎都染上了重病。', `MaleText_loc5`='我認識的每個人似乎都染上重症。', `MaleText_loc7`='A todo el mundo que conozco parece estar pasándole algo realmente malo.', `FemaleText_loc1`='주위 사람 모두가 병에 단단히 걸린 것 같아요.', `FemaleText_loc4`='我身边的人似乎都染上了重病。', `FemaleText_loc5`='我認識的每個人似乎都染上重症。', `FemaleText_loc7`='A todo el mundo que conozco parece estar pasándole algo realmente malo.' WHERE `ID`=28821;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 심지어 용숨결 칠리를 먹었을 때보다도 몸이 안 좋습니다.', `MaleText_loc4`='自从上次尝过龙息红椒后，我还从来没有这么难受过。', `MaleText_loc5`='自從我嘗過龍息紅椒之後，我就沒有感覺這麼糟過。', `MaleText_loc7`='No me había sentido tan mal desde que traté de comer ají aliento de dragón.', `FemaleText_loc1`='이렇게 몸이 안 좋은 건 처음이에요.', `FemaleText_loc4`='自从上次尝过龙息红椒后，我还从来没有这么难受过。', `FemaleText_loc5`='自從我嘗過龍息紅椒之後，我就沒有感覺這麼糟過。', `FemaleText_loc7`='No me había sentido tan mal desde que traté de comer ají aliento de dragón.' WHERE `ID`=28822;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당장에라도 침대에 가서 눕고 싶군요.', `MaleText_loc4`='我的床看上去很漂亮啊。', `MaleText_loc5`='我的床現在看來好棒唷。', `MaleText_loc7`='Mi cama tiene muy buena pinta ahora.', `FemaleText_loc1`='침대가 그리워요.', `FemaleText_loc4`='我的床看上去很漂亮啊。', `FemaleText_loc5`='我的床現在看來好棒唷。', `FemaleText_loc7`='Mi cama tiene muy buena pinta ahora.' WHERE `ID`=28823;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번 달에 또 아프다고 자리를 비우면 상사가 저를 죽이려고 들 겁니다.', `MaleText_loc4`='本月我要是再多请一天病假的话，老板就会杀了我。', `MaleText_loc5`='要是我這個月又生病待在家裡一天的話，我老闆一定會殺了我。', `MaleText_loc7`='Mi jefe me matará si me quedo enfermo en casa otro día más este mes.', `FemaleText_loc1`='또 아프다고 휴가를 내면 상사가 화를 낼 것 같아요.', `FemaleText_loc4`='本月我要是再多请一天病假的话，老板就会杀了我。', `FemaleText_loc5`='要是我這個月又生病待在家裡一天的話，我老闆一定會殺了我。', `FemaleText_loc7`='Mi jefe me matará si me quedo enfermo en casa otro día más este mes.' WHERE `ID`=28824;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요새 횡행하는 질병의 정체에 대해서 뭐 들은 소식 없으신가요?', `MaleText_loc4`='镇长有没有提到疫情扩展的消息？', `MaleText_loc5`='你有聽鎮上的領導人提起過最近流行的疾病嗎?', `MaleText_loc7`='¿Has oído alguna noticia por parte de los líderes de la ciudad sobre la enfermedad que circula por aquí?', `FemaleText_loc1`='왜 도시의 지도자들은 요새 유행하는 질병에 대해 아무 말도 없는 걸까요?', `FemaleText_loc4`='镇长有没有提到疫情扩展的消息？', `FemaleText_loc5`='你有聽鎮上的領導人提起過最近流行的疾病嗎?', `FemaleText_loc7`='¿Has oído alguna noticia por parte de los líderes de la ciudad sobre la enfermedad que circula por aquí?' WHERE `ID`=28825;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하나도 안 아픈 사람하고 마지막으로 이야기해 본 게 언제입니까?', `MaleText_loc4`='你和那些尚未染病的人交谈过吗？', `MaleText_loc5`='你有跟任何一個還沒生病的人談過嗎?', `MaleText_loc7`='¿Has hablado con alguien que no haya empezado a sentirse enfermo?', `FemaleText_loc1`='요새 안 아픈 사람 본 적 있어요?', `FemaleText_loc4`='你和那些尚未染病的人交谈过吗？', `FemaleText_loc5`='你有跟任何一個還沒生病的人談過嗎?', `FemaleText_loc7`='¿Has hablado con alguien que no haya empezado a sentirse enfermo?' WHERE `ID`=28826;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물이 어딘가 잘못된 게 분명해요.', `MaleText_loc4`='我敢打赌，是饮用水的问题。', `MaleText_loc5`='我告訴你，一定是水裡有什麼。', `MaleText_loc7`='Tiene que ser algo del agua, te lo digo.', `FemaleText_loc1`='제 생각엔 식수에 문제가 있는 것 같아요.', `FemaleText_loc4`='我敢打赌，是饮用水的问题。', `FemaleText_loc5`='我告訴你，一定是水裡有什麼。', `FemaleText_loc7`='Tiene que ser algo del agua, te lo digo.' WHERE `ID`=28827;
