UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니? 어떻게 이런 일이?', `MaleText_loc4`='什么？怎么可能？', `MaleText_loc5`='什麼?這怎麼可能?', `MaleText_loc7`='¿Qué? ¿Cómo es posible?' WHERE `ID`=28833;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헤멧과 한 약속을 지키느라 제가 겪은 일을 대마법사님께서 조금이라도 고마워하셨으면 좋겠습니다.', `MaleText_loc4`='我费了很多功夫，才迫使赫米特遵守协议。只希望大法师能赏识我的才能。', `MaleText_loc5`='我希望大法師會感激我為了讓赫米特停止討價還價所經歷的一切。', `MaleText_loc7`='Espero que el archimago se dé cuenta de lo que he tenido que hacer para cumplir la parte del trato de Hemet.' WHERE `ID`=28834;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='인상적이구나, 죽음의 기사여. 보상을 줄 테니 산 자의 세상에서 나를 찾아오너라.', `MaleText_loc4`='很不错啊，死亡骑士。返回生者的世界，领取你应得的奖励吧。', `MaleText_loc5`='令人印象深刻，死亡騎士。回到生者的世界領取獎賞吧。', `MaleText_loc7`='Impresionante, caballero de la Muerte. Vuelve a verme en el mundo de los vivos para obtener tu recompensa.' WHERE `ID`=28835;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아서스 곁에서 떨어지면 안 됩니다. 어서 가세요!', `FemaleText_loc4`='你应该紧跟着阿尔萨斯！', `FemaleText_loc5`='你現在應該緊緊跟在阿薩斯身邊!', `FemaleText_loc7`='¡Deberías pegarte a Arthas ahora mismo!' WHERE `ID`=28836;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 애처롭고 작은 벌레는 뭐지? 죽으러 왔나?', `MaleText_loc4`='你来做什么，可悲的家伙？送死吗？', `MaleText_loc5`='你這可悲的東西到底是什麼，小蟲嗎?來受死了嗎?', `MaleText_loc7`='¿Qué significa esto, patético gusanito? ¿Vienes para morir?' WHERE `ID`=28837;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 불쾌한 냄새는 맡아본 적이 있는데... 새끼 눈표범 등에 타고는 숨어서 내 뒤를 지나간 게 바로 네 녀석이구나!', `MaleText_loc4`='我很熟悉你身上的臭味。捕杀雪豹时，你一路潜行尾随在我身后！', `MaleText_loc5`='我認得你的臭味。你就是騎著那頭雪豹小畜生躲到我背後的傢伙!', `MaleText_loc7`='Reconozco tu hedor. ¡Eres $gel que:la que; me espió $gmontado:montada; sobre ese leopardo de las nieves enano!' WHERE `ID`=28838;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기분 안 좋아... 나중에 다시 와서 우릴 찾아줄 테야?', `MaleText_loc4`='情况不妙……要不你待会再来找我们？', `MaleText_loc5`='感覺不太好...也許晚點再回來找我們?', `MaleText_loc7`='No encontrarnos muy bien... ¿venir a buscarnos más tarde?' WHERE `ID`=28839;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 죽기 싫어. 그래도 우린 돕고 싶어! 우리한테 와, 알았지?', `MaleText_loc4`='我们是很想帮忙啊。但我们不想搭上性命！你待会再来找我们吧！', `MaleText_loc5`='我們不想死。但我們還是想幫忙!回來找我們，好嗎?', `MaleText_loc7`='Nosotros no querer morir. ¡Pero querer ayudar! Volver a buscarnos, ¿vale?' WHERE `ID`=28840;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 미안해... 집에 가서, 지금 죽지 않아서. 우리 너무 미안해!', `MaleText_loc4`='抱歉……我们要回家去，我们不想死。很抱歉！', `MaleText_loc5`='我們很抱歉...回家去，不想現在死。我們真的很抱歉!', `MaleText_loc7`='Nosotros sentirlo... Ahora ir a casa para no morir. ¡Nosotros sentirlo mucho!' WHERE `ID`=28841;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저승에서 열리는 집들이에 네 녀석을 초대하러 돌아왔다!', `FemaleText_loc4`='我邀请你去地底世界参加我的乔迁庆宴！', `FemaleText_loc5`='我回來邀請你參加我在冥界的喬遷之宴!', `FemaleText_loc7`='¡He regresado para invitarte a la fiesta de inauguración de mi casa en el inframundo!' WHERE `ID`=28842;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='얌전히 따라와 줬으면 좋겠다만, 우리 둘 다 그런 일은 일어나지 않으리란 걸 알지. 여기 있는 작은 친구가 네가 내세에 편안하게 발을 들이게 도와줄 게다.', `FemaleText_loc4`='我也想静静地陪伴你，但我们都知道，这是不可能的。就让我的小伙伴送你去地狱吧。', `FemaleText_loc5`='我想說安靜地跟來，但我們都知道那是不可能的。我在這兒的小朋友們正在替你鋪好通往死後世界的大道。', `FemaleText_loc7`='Te diría que vinieses de forma tranquila, pero ambos sabemos que eso no va a pasar. Mi $gpequeño amigo:pequeña amiga; de aquí va a abrirte el camino a la otra vida.' WHERE `ID`=28843;
