UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐야? 살라나르가 보낼 수 있는 놈 중에 제일 괜찮은 녀석이 겨우 이거냐?', `MaleText_loc4`='就这点能耐？这就是萨拉纳尔所能派出的最强大的骑士？', `MaleText_loc5`='就是這個?這就是撒拉納派得出來最強的人?', `MaleText_loc7`='¿Esto es todo? ¿Esto es lo mejor que Salanar ha logrado enviar contra mí?' WHERE `ID`=28848;
