UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 끔찍한 곳에서 어서 나가요.', `FemaleText_loc4`='我们赶紧离开这里吧。', `FemaleText_loc5`='快點離開這個鬼地方。', `FemaleText_loc7`='Salgamos de aquí.' WHERE `ID`=28856;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘 들어요, 투자개발회사 바보 씨! 첫 번째 규칙은 절대 폭발물 근처에 죄수를 두지 말라는 거예요.', `FemaleText_loc4`='听着，风险投资公司的蠢货！准则第一条：永远不要把囚犯关押在爆炸物附近。', `FemaleText_loc5`='聽著，風險投資公司的呆子!第1條規則:不要把囚犯放在靠近炸藥的地方。', `FemaleText_loc7`='¡Escuchad, matones de Ventura y Cía.! Regla n.º 1: jamás dejéis a un prisionero cerca de explosivos.' WHERE `ID`=28857;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 분장으로 나를 속일 수는 없다, 살덩어리야! 널 쓰러뜨리면 드라쿠루 님께서 기뻐하시겠지!', `MaleText_loc4`='你的伪装骗不了我！我要杀了你，达库鲁一定会很满意的！', `MaleText_loc5`='你的偽裝騙不了我，血肉之軀!打敗你，德拉庫魯一定會很高興!', `MaleText_loc7`='¡Tu disfraz no me engaña, criatura de carne! ¡Tu derrota agradará a Drakuru!' WHERE `ID`=28858;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아니면 이걸 받게 될 거예요.', `FemaleText_loc4`='否则，这就是后果。', `FemaleText_loc5`='否則，『這』就是你會得到的。', `FemaleText_loc7`='O ESTO es lo que tendréis.' WHERE `ID`=28859;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기 좀 후끈하군요. 이동할까요?', `FemaleText_loc4`='这里越来越热了。我们继续前进吧？', `FemaleText_loc5`='這裡變得有點熱了。我們繼續前進吧?', `FemaleText_loc7`='Empieza a hacer calor aquí. ¿Seguimos?' WHERE `ID`=28860;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음의 기사여, 우리는 그들에게서 모든 것을 앗아가리라.', `MaleText_loc4`='我们将夺走他们的一切，死亡骑士。', `MaleText_loc5`='我們會把他們的一切都奪走，死亡騎士。', `MaleText_loc7`='Se lo arrebataremos todo, caballero de la Muerte.' WHERE `ID`=28861;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어머, 봐요. 폭발물이 담긴 짐마차가 또 있어요! 저들이 잘 처리하게 도와주자고요.', `FemaleText_loc4`='瞧，又是一车炸弹！让我们引爆它吧。', `FemaleText_loc5`='喔，看，又另一大車的炸藥!讓我們來幫忙處理它。', `FemaleText_loc7`='¡Oh, mira es otro montón de explosivos! Ayudémoslos a librarse de ellos.' WHERE `ID`=28862;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살라나르 님, 저는 어둠의 영역으로 돌아가야 합니다.', `MaleText_loc4`='萨拉纳尔，我必须返回暗影界。', `MaleText_loc5`='撒拉納，我要回到陰影之境。', `MaleText_loc7`='Salanar, debo volver al Reino de las Sombras.', `FemaleText_loc1`='살라나르 님, 저는 어둠의 영역으로 돌아가야 합니다.', `FemaleText_loc4`='萨拉纳尔，我必须返回暗影界。', `FemaleText_loc5`='撒拉納，我要回到陰影之境。', `FemaleText_loc7`='Salanar, debo volver al Reino de las Sombras.' WHERE `ID`=28863;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런 걸로 장난치면 절대 안 돼요. 누군가가 다칠 수도 있다고요.', `FemaleText_loc4`='你不该随意摆弄这些东西。会弄伤人的。', `FemaleText_loc5`='你真的不應該玩這些東西。有人可能會受傷。', `FemaleText_loc7`='No deberían jugar con esto. Alguien podría salir herido.' WHERE `ID`=28864;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리가 해냈어요! 저 지옥 같은 구덩이에서 저를 구해주셔서 정말 고마워요. 헤멧에게 제가 간다고 전해주세요.', `FemaleText_loc4`='成功啦！谢谢你带我逃离那个地狱般的洞穴。告诉赫米特，让他等着我！', `FemaleText_loc5`='我們辦到了!感謝你幫我逃出那個該死的洞穴。告訴赫米特要等著我!', `FemaleText_loc7`='¡Lo logramos! Gracias por sacarme de ese agujero infernal. ¡Dile a Hemet que me espere!' WHERE `ID`=28865;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이해가 안 돼...', `MaleText_loc4`='我不明白……', `MaleText_loc5`='我不懂...', `MaleText_loc7`='No entiendo...', `FemaleText_loc1`='이해할 수가 없어...', `FemaleText_loc4`='我不明白……', `FemaleText_loc5`='我不懂...', `FemaleText_loc7`='No entiendo...' WHERE `ID`=28866;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 무슨 짓을 했다고 이러는 겁니까?', `MaleText_loc4`='我做错了什么吗？', `MaleText_loc5`='我做了什麼?', `MaleText_loc7`='¿Qué he hecho?', `FemaleText_loc1`='내가 무슨 짓을 했다고 이러는 건가요?', `FemaleText_loc4`='我做错了什么吗？', `FemaleText_loc5`='我做了什麼?', `FemaleText_loc7`='¿Qué he hecho?' WHERE `ID`=28867;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜... 이러는 거요...', `MaleText_loc4`='为什么会落得……这样的结局……', `MaleText_loc5`='我不應該...遭受這些...', `MaleText_loc7`='Yo no... merecía esto...', `FemaleText_loc1`='난... 아무 짓도 하지 않았는데...', `FemaleText_loc4`='为什么会落得……这样的结局……', `FemaleText_loc5`='我不應該...遭受這些...', `FemaleText_loc7`='Yo no... merecía esto...' WHERE `ID`=28868;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜입니까?', `MaleText_loc4`='为什么？', `MaleText_loc5`='為什麼?', `MaleText_loc7`='¿Por qué?', `FemaleText_loc1`='왜인가요?', `FemaleText_loc4`='为什么？', `FemaleText_loc5`='為什麼?', `FemaleText_loc7`='¿Por qué?' WHERE `ID`=28869;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와, 와와. 좋아... 와!', `MaleText_loc4`='哎哟。嗯……哎哟！', `MaleText_loc5`='噢，噢，噢。好吧...噢!', `MaleText_loc7`='Ay, ay, ay. Vale... ¡ay!' WHERE `ID`=28870;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너한테는 너무 빠르지! 우리 절대 못 잡을걸!', `MaleText_loc4`='太慢啦！你追不上我们！', `MaleText_loc5`='我們太快啦!你追不上我們!', `MaleText_loc7`='¡Demasiado rápidos para ustedes! ¡No pueden atraparnos!' WHERE `ID`=28871;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어이! 잘루트 어디로 가? 휘릭!', `MaleText_loc4`='嗨！亚鲁乌特到哪儿去了？噗！', `MaleText_loc5`='嘿!賈露特去哪了?呼!', `MaleText_loc7`='¡Oye! ¿Dónde se ha metido Jaloot? ¡Puf!' WHERE `ID`=28872;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 싸움은 전부 너한테 맡길게!', `MaleText_loc4`='这次就靠你自己了！', `MaleText_loc5`='這場戰鬥全是你的!', `MaleText_loc7`='¡Esta lucha es toda tuya!' WHERE `ID`=28873;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음, 그만하면 충분하고도 남겠어.', `MaleText_loc4`='我受够了。', `MaleText_loc5`='嗯，那個真的很夠了。', `MaleText_loc7`='Bueno, ya basta de eso.' WHERE `ID`=28874;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나를 더 죽이고 싶으면 마을로 찾으러 와.', `MaleText_loc4`='如果你还想让我来送死的话，就去营地找我吧。', `MaleText_loc5`='如果你想要進一步地把我丟向死亡，你可以在鎮上找到我。', `MaleText_loc7`='Búscame por la ciudad si quieres intentar echarme a las garras de la muerte un rato más.' WHERE `ID`=28875;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘했다. 난 예언자 녀석이 영원히 내 곁에 머물게 되어 얼마나 행복해하는지 보러 가야겠군.', `FemaleText_loc4`='很好。我会让先知永远待在我身边的。', `FemaleText_loc5`='幹得好。我保證我的預言者在與我永恆共處的時間裡會過得很愉快的。', `FemaleText_loc7`='Bien hecho. Me encargaré de que mi profeta disfrute de su estancia eterna conmigo.' WHERE `ID`=28876;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐... 멈춰! 힘을 되찾아서는 안 돼!!!', `MaleText_loc4`='等等……住手！你不能夺走力量！！', `MaleText_loc5`='等等...停下來!你不能把力量收回去!!!', `MaleText_loc7`='Espera... ¡PARA! ¡No puedes arrebatar el poder!' WHERE `ID`=28877;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='치유가 필요합니다!', `MaleText_loc4`='我需要治疗！', `MaleText_loc5`='我需要治療!', `MaleText_loc7`='¡Necesito curarme!' WHERE `ID`=28878;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 여기서 벗어납시다. 소생이 필요합니다!', `MaleText_loc4`='我们应该离开这里。我需要恢复！', `MaleText_loc5`='我們需要離開這裡。我需要恢復!', `MaleText_loc7`='Deberíamos salir de aquí. Necesito Renovar.' WHERE `ID`=28879;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소생을 시전할 때인 것 같습니다!', `MaleText_loc4`='我觉得应该施放恢复了！', `MaleText_loc5`='我想現在是時候施展我的恢復法術了!', `MaleText_loc7`='Creo que es hora de que lance mi Renovar.' WHERE `ID`=28880;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심해서 타고 가! 그리고 도착하면 날 불러.', `MaleText_loc4`='旅途愉快！等你抵达目的地后再召唤我吧。', `MaleText_loc5`='一路順風!等你到那邊之後再通知我。', `MaleText_loc7`='¡Disfrutar viaje! Llamarme cuando tú llegar.' WHERE `ID`=28881;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 얼마나 더 버틸 수 있을지 모르겠습니다!', `MaleText_loc4`='我不知道自己还能撑多久！', `MaleText_loc5`='我不知道我還能支撐多久!', `MaleText_loc7`='¡No sé cuánto tiempo más podré aguantar!' WHERE `ID`=28882;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='광란심장 일족이 이 땅을 접수하겠다. 날름이들은 떠나든지 우리 손에 죽어라.', `MaleText_loc4`='狂心氏族将夺得这块土地的控制权。大舌头怪最好滚得远远的，不然我们就将他们统统杀掉。', `MaleText_loc5`='狂心會自己奪回土地。大舌頭得離開，或是我們痛宰他們。', `MaleText_loc7`='Corazón Frenético se quedará la tierra. Leguas-grandes marcharse o nosotros matar del todo.' WHERE `ID`=28883;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다르무크는 죽어야 한다!', `MaleText_loc4`='达穆克必须死！', `MaleText_loc5`='達穆克一定得死，老兄!', `MaleText_loc7`='¡Darmuk debe morir, tron!' WHERE `ID`=28884;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='광란심장 일족은 광포할지 모르나, 우리는 좋은 자들이다. 오래 머문다면 우리가 현명하고 강인한 이들과 사이좋게 지내는 것을 볼 수 있다.$B$B우린 그저 멍청이들이 싫을 뿐이다.', `MaleText_loc4`='狂心狼獾人很看起来凶猛，但其实我们是好人呀。时间长了，你就会发现，我们和聪明强壮的朋友相处得很好。$B$B我们只是不善于和笨蛋打交道而已。', `MaleText_loc5`='狂心很壞很惡毒，但我們是好人。你只要待著就會看見，我們有強大聰明的朋友。$B$B我們不喜歡呆呆。', `MaleText_loc7`='Corazón Frenético pueden ser despiadados, pero nosotros buena gente. Tú verlo si quedarte un tiempo, nosotros amigos con inteligentes y fuertes.$B$BNo gustarnos los tontos.' WHERE `ID`=28885;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이것이 거대한 비 바위다. 안전하게 지키고 반짝이들을 가져다주면, 우리를 보살펴준다.$B$B혹시 바위에 바칠 반짝이 더 있나?', `MaleText_loc4`='这就是雨水巨石。我们保护它，向它供奉闪闪发亮的宝贝；它就会庇护我们。$B$B你有亮闪闪的宝贝吗？', `MaleText_loc5`='這是偉大雨石。我們確保它的安全，帶亮晶晶給它，而它保護我們。$B$B或許你還有更多亮晶晶可以給石頭?', `MaleText_loc7`='Esta ser la Gran Piedra de Lluvia. La mantenemos a salvo y le traemos cositas brillantes y ella cuidarnos.$B$B¿Igual tener más cositas brillantes para piedra?' WHERE `ID`=28886;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게 없는 건 키인데 마법으로 높였다. 나는 위대한 안개 바위 잘 관리한다... 대부분 말이다.$B$B바보같은 하룻강아지들 같으니.', `MaleText_loc4`='我的个子不高，但是我会很厉害的魔法。我负责保护迷雾巨石……嗯，大多数时候我还是相当称职的。$B$B愚蠢的狗狗人。', `MaleText_loc5`='高度不夠的部分，我用魔法來補足。我把偉大霧石照顧得很好...大多數的時候。$B$B呆呆小狗人。', `MaleText_loc7`='Lo que faltarme en altura compensarlo con magia. Yo cuidar bien de la Gran Piedra de Niebla... la mayoría del tiempo.$B$BEstúpidos hombres cachorro.' WHERE `ID`=28887;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하룻강아지들 만날 우리 공격한다. 그래도 거대한 번개 바위 아직 안전해.$B$B수홀루 전에 그랬던 것처럼 우리 도와주러 온다... 하룻강아지들은 큰일 났다.', `MaleText_loc4`='狗狗人的攻击已经持续好几天了。但是闪电巨石还很安全。$B$B跟往常一样，索乌霍鲁向我们伸出了援手……狗狗人不会有获胜的机会。', `MaleText_loc5`='小狗人已經攻擊我們好幾天了。但偉大閃電石還是安全的。$B$B蘇-侯魯像之前幾次一樣來幫我們...小狗人是贏不了的。', `MaleText_loc7`='Los hombres cachorro llevan días atacándonos. Pero la Gran Piedra de Rayos aún ser segura.$B$BSoo-brada haber venido a ayudarnos muchas veces... Hombres cachorro no tener ninguna posibilidad.' WHERE `ID`=28888;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카르탁이 날름이 고기 먹으러 온다. 광란심장 일족은 많이 갖다 놔야 한다.', `MaleText_loc4`='卡塔克是来吃大舌头怪的。我们要为他准备一顿大餐。', `MaleText_loc5`='卡爾塔克為了大舌頭肉而來。狂心要確保數量充足。', `MaleText_loc7`='Kartak venir a por carne de lenguas-grandes. Corazón Frenético asegurarse de que haya bastante preparada.' WHERE `ID`=28889;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용사들이여, 당장 마을회관으로 집결해라. 말가니스를 상대해야 한다.', `MaleText_loc4`='立即与我在市政厅会合，勇士。我们必须直接挑战玛尔加尼斯。', `MaleText_loc5`='勇士們，立刻到市政廳集合。我們一定要跟瑪爾加尼斯一戰。', `MaleText_loc7`='Campeones, reúnanse conmigo en el consejo. ¡Debemos llevar la lucha a Mal''Ganis!', `FemaleText_loc1`='용사들이여, 당장 마을회관으로 집결해라. 말가니스를 상대해야 한다.', `FemaleText_loc4`='立即与我在市政厅会合，勇士。我们必须直接挑战玛尔加尼斯。', `FemaleText_loc5`='勇士們，立刻到市政廳集合。我們一定要跟瑪爾加尼斯一戰。', `FemaleText_loc7`='Campeones, reúnanse conmigo en el consejo. ¡Debemos llevar la lucha a Mal''Ganis!' WHERE `ID`=28890;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스컬지 위장이 풀립니다! 스컬지를 피하십시오!', `MaleText_loc4`='伪装失效了！避开天灾兵！', `MaleText_loc5`='偽裝失敗!避免跟天譴軍接觸!', `MaleText_loc7`='¡Disfraz fallando! ¡Evita el contacto con la Plaga!', `FemaleText_loc1`='스컬지 위장이 풀립니다! 스컬지를 피하십시오!', `FemaleText_loc4`='伪装失效了！避开天灾兵！', `FemaleText_loc5`='偽裝失敗!避免跟天譴軍接觸!', `FemaleText_loc7`='¡Disfraz fallando! ¡Evita el contacto con la Plaga!' WHERE `ID`=28891;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 운 좋은 줄 알아, 주트피즐. $n|1이;가; 당신에게 줄 새끼를 더 가져왔어.', `MaleText_loc4`='苏特菲兹，今天是你的幸运日。$n为你带回了更多的龙崽。', `MaleText_loc5`='這是你的幸運日，狹嘶。$n帶了很多小雛龍給你。', `MaleText_loc7`='Hoy es tu día de suerte, Zootsilbo. $n ha traído más crías para ti.' WHERE `ID`=28892;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 네 새끼만 돌보는 건 아니야, 도리안. 내 연구도 하는 중이라고.', `MaleText_loc4`='我凭什么要替你照顾龙崽啊，多里安。我还要搞研究工作呢。', `MaleText_loc5`='我不是來這裡看顧你的小雛龍，多里安。我也在做自己的研究。', `MaleText_loc7`='No estoy aquí para cuidar de tus crías, Dorian. Yo también estoy investigando.' WHERE `ID`=28893;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러면, 야영지로 돌아가 웨슬렉스와 톱니바퀴나 가지고 씨름하든가.', `MaleText_loc4`='好吧，你随时可以返回营地，帮助维斯雷摆弄那堆齿轮……', `MaleText_loc5`='嗯，你隨時都可以回到營地，幫威斯雷克斯處理他的齒輪...', `MaleText_loc7`='Bueno, siempre puedes volver al campamento y ayudar a Weslex con todos sus engranajes...' WHERE `ID`=28894;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안돼, 기어는 안돼! 기어만 아니면 뭐든지 괜찮아!', `MaleText_loc4`='不要，我讨厌齿轮！别让我碰那玩意儿！', `MaleText_loc5`='不，拜託不要是齒輪!什麼都好就不要是齒輪!', `MaleText_loc7`='¡No, los engranajes no! ¡Lo que sea menos los engranajes!' WHERE `ID`=28895;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생각보다 강하구나... 모두 공격해라!', `MaleText_loc4`='朋友，他们比我想象的更强壮。进攻！', `MaleText_loc5`='他們比我想像得還強，老兄，攻擊他們!', `MaleText_loc7`='Son más fuertes de lo que esperaba, tron, ¡atacadlos!' WHERE `ID`=28896;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대기해라. 이 녀석은 내가 직접 처리하지!', `MaleText_loc4`='听我指挥，这个交给我来处理！', `MaleText_loc5`='等我的命令，我要親自處理他!', `MaleText_loc7`='¡Esperad mis órdenes, yo me puedo encargar de esto!' WHERE `ID`=28897;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 왜 여기 있는 거야? 감독한테 혼나기 전에 어서 배로 가져가야겠군!', `MaleText_loc4`='这东西是从哪儿来的？趁工头还没发现，我最好赶紧把它拖到船上去！', `MaleText_loc5`='這從哪兒來的?我最好在工頭看到之前把這個弄上船!', `MaleText_loc7`='¿De dónde ha salido esto? ¡Será mejor que lo lleve a los barcos antes de que el supervisor lo vea!' WHERE `ID`=28898;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그냥 여기 남겨 둬야지. 그게 현명한 행동일 거라고!', `MaleText_loc4`='管它做什么呢。放在这里就是了，不会有人发现的！', `MaleText_loc5`='我就把它留在這裡，誰也別自作聰明!', `MaleText_loc7`='¡Lo dejaré aquí y nadie se dará cuenta!' WHERE `ID`=28899;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 제단에 반짝이 바쳤어... 우리 욕심쟁이 아냐... 그런데 왜 이런 일 일어나?', `MaleText_loc4`='我们把闪闪发光的宝贝都供奉给了神殿……我们一点也不贪心啊……为什么会这样？', `MaleText_loc5`='我們把亮晶晶給了神殿...我們不貪心...為什麼會發生這種事?', `MaleText_loc7`='Nosotros entregar cositas brillantes a santuario... nosotros no egoístas... ¿por qué pasar esto?' WHERE `ID`=28900;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 반짝이 가져가... 다시 날씨 좋게 해줘... 언데드 같은 거 가버리게 해.', `MaleText_loc4`='把我的宝藏拿去吧……这样天气就会好转……亡灵也会离开。', `MaleText_loc5`='用我的亮晶晶...讓天氣再次變好...讓不死東西滾遠遠。', `MaleText_loc7`='Usar mis cositas brillantes... hacer tiempo bueno otra vez... hacer que cosas no-muertas marchar.' WHERE `ID`=28901;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고마...워.', `MaleText_loc4`='谢谢……你。', `MaleText_loc5`='感謝...你。', `MaleText_loc7`='Gra...cias.' WHERE `ID`=28902;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 아무 짓도 안했어... 저놈들한테... 나 이해 안 가.', `MaleText_loc4`='我们……什么都没做啊……我搞不明白。', `MaleText_loc5`='我們沒有...對他們...做什麼...我不明白。', `MaleText_loc7`='Nosotros no hacerles nada... a ellos... Yo no entender.' WHERE `ID`=28903;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 나쁜 짓 한 거야? 나 미안해...', `MaleText_loc4`='我做错事了？对不起……', `MaleText_loc5`='我做錯了什麼嗎?我很抱歉...', `MaleText_loc7`='¿Yo hacer algo mal? Sentirlo...' WHERE `ID`=28904;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고마워! 너 착해!', `MaleText_loc4`='谢谢你！你是个好人！', `MaleText_loc5`='感謝你!你好棒!', `MaleText_loc7`='¡Gracias! ¡Tú bueno!' WHERE `ID`=28905;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너도 날씨 좋게 할 수 있어?', `MaleText_loc4`='或许你也能让天气好转？', `MaleText_loc5`='或許你也能讓天氣變好?', `MaleText_loc7`='¿A lo mejor tú también poder mejorar el tiempo?' WHERE `ID`=28906;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제단에 반짝이 더 바칠 게! 나 약속해! 나 미안해!', `MaleText_loc4`='我会为神殿供奉更多闪闪发光的宝贝！我发誓！对不起！', `MaleText_loc5`='我會給神殿更多的亮晶晶!我保證!我很抱歉!', `MaleText_loc7`='¡Yo dar más cositas brillantes a santuarios! ¡Yo prometerlo! ¡Yo sentirlo!' WHERE `ID`=28907;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이끼걸음골록 더 도와줘, 응?', `MaleText_loc4`='继续搭救苔行鳄鱼人，好吗？', `MaleText_loc5`='幫助更多的苔行者，好嗎?', `MaleText_loc7`='Ayuda a más Caminamohos, ¿vale?' WHERE `ID`=28908;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너 우리 구해줬어! 너 만세야!', `MaleText_loc4`='你救了我们！谢谢你！', `MaleText_loc5`='你拯救了我們!為你歡呼!', `MaleText_loc7`='¡Tú salvarnos! ¡Bien por ti!' WHERE `ID`=28909;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕, 뽀송피부.', `MaleText_loc4`='干皮人，你好。', `MaleText_loc5`='哈囉，乾皮。', `MaleText_loc7`='Hola, piel seca.' WHERE `ID`=28910;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경비병을 모두 해치웠나 보구나. 상관없다. 어차피 별 도움도 안 되는 녀석들이었어. 이제 죽을 때다! [PH]', `MaleText_loc4`='You seem to have bested my guards. No matter, they were of little use anyway. Time to die! [PH]', `MaleText_loc5`='看來，你打敗了我的護衛。沒關係，他們反正本來就沒什麼用處。受死吧![PH]', `MaleText_loc7`='Parece que has derrotado a mis guardias. Da igual, no me eran muy útiles. ¡Hora de morir!' WHERE `ID`=28911;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='별일 없지?', `MaleText_loc4`='一切顺利吗？', `MaleText_loc5`='沒事吧?', `MaleText_loc7`='¿Todo bien?' WHERE `ID`=28912;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='응?', `MaleText_loc4`='嗯？', `MaleText_loc5`='嗯?', `MaleText_loc7`='¿Sí?' WHERE `ID`=28913;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멋진 사냥 친구가 생겨서 좋아.', `MaleText_loc4`='有你这样优秀的猎手陪同，感觉真好。', `MaleText_loc5`='有個好狩獵夥伴真不錯。', `MaleText_loc7`='Es agradable tener un buen compañero de caza.' WHERE `ID`=28914;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐 잘못됐어?', `MaleText_loc4`='怎么啦？', `MaleText_loc5`='有問題嗎?', `MaleText_loc7`='¿Ocurre algo?' WHERE `ID`=28915;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕! 잘 지내? 우린 잘 지내... 그럼. 잘 지내고말고. 안녕!', `MaleText_loc4`='嗨！你还好吧？我们很好……嗯，很好很好。嗨！', `MaleText_loc5`='嗨!你好嗎?我們好...呃，好，好。嗨!', `MaleText_loc7`='¡Hola! ¿Cómo estar? Nosotros bien... sí, bien bien. ¡Hola!' WHERE `ID`=28919;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='걸어서 여행한 적 있어? 우린 있어. 좀 힘들지. 하지 마, 재미없어. 절대로.', `MaleText_loc4`='你被自己绊倒过吗？我们有过这样的经历诶。有点痛。不好玩，我们不要再绊倒了。', `MaleText_loc5`='從來沒有用自己徒步旅行?我們可是常幹。有一點痛啦。不過，不這樣就沒有樂趣了。一點都沒有。', `MaleText_loc7`='¿Alguna vez tropezar con tus pies? Nosotros sí. Doler un poco. Si no hacer, no divertido. Nop.' WHERE `ID`=28920;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕! 너 정말 튼튼하고 착하고 멋져. 나 너 좋아. 우리 친구 하자, 응?', `MaleText_loc4`='你好！你看上去又强壮又和善。我喜欢你。我们做朋友好不好啊？', `MaleText_loc5`='哈囉!你真強壯、善良又有用。我喜歡你。我們繼續當朋友，好吧?', `MaleText_loc7`='¡Hola! Eres fuerte y $gguapo:guapa; y esas cosas. Me gustas. Seamos amigos, ¿vale?' WHERE `ID`=28921;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 도움 필요해? 뭐 도와줄까? 우리 도와주기 잘해.', `MaleText_loc4`='要帮忙吗？要帮忙吗？我们是很乐于助人的。', `MaleText_loc5`='要我們幫一些忙?幫什麼忙?我們可是很擅長幫忙。', `MaleText_loc7`='¿Quieres que ayudemos en algo? ¿Con qué ayudar? Nosotros buenos ayudando.' WHERE `ID`=28922;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐 보고 있어?', `MaleText_loc4`='你在看什么？', `MaleText_loc5`='你在看什麼?', `MaleText_loc7`='¿Qué miras?' WHERE `ID`=28923;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 아직도 여기 서 있는 이유가 뭐야?', `MaleText_loc4`='为什么我们还待在这里？', `MaleText_loc5`='有任何理由我們還站在這裡?', `MaleText_loc7`='¿Hay alguna razón para que aún estemos aquí?' WHERE `ID`=28924;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너 뭔가 바라는 게 있다고 생각해.', `MaleText_loc4`='你想要什么东西吗？', `MaleText_loc5`='我假設你想要一些東西。', `MaleText_loc7`='Supongo que quieres algo.' WHERE `ID`=28925;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나는 그대에게 영겁의 빚을 졌다, $n.', `FemaleText_loc4`='我永远欠你一份情，$n。', `FemaleText_loc5`='我永遠都欠你一份恩情，$n。', `FemaleText_loc7`='Estaré en deuda contigo eternamente, $n.' WHERE `ID`=28926;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n, 맘토스의 피 덕분에 나는 오히려 더 강해진 기분이 드는구나.', `FemaleText_loc4`='$n，犸托斯的鲜血让我变得强壮起来。', `FemaleText_loc5`='$n，因為瑪姆托司之血，我感到覺自己更強大了。', `FemaleText_loc7`='$n, por algún motivo me siento más fuerte gracias a la sangre de Mam''toth.' WHERE `ID`=28927;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='풀려났어! 서둘러라. 쿠에츠룬의 복수를 수행하거라. 나중에 짐토르가에서 보자꾸나.', `FemaleText_loc4`='我自由了！快，为奎丝鲁恩复仇。我稍后会和你在希姆托加碰面。', `FemaleText_loc5`='我自由了!快，上演奎茲倫的復仇吧。我之後跟你在辛托加碰面。', `FemaleText_loc7`='¡Soy libre! Rápido, cumple la venganza de Quetz''lun. Te veré después en Zim''Torga.' WHERE `ID`=28928;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='숨을... 못 쉬겠어...', `MaleText_loc4`='喘……喘不过气来……', `MaleText_loc5`='不能...呼吸...', `MaleText_loc7`='No puedo... respirar...' WHERE `ID`=28929;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살갗이... 너무... 아파...', `MaleText_loc4`='皮肤……滚烫……好痛……', `MaleText_loc5`='皮膚...燒起來...好...痛...', `MaleText_loc7`='Piel... quema... el... dolor...' WHERE `ID`=28930;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세상이... 흐릿해... 볼 수가... 없어...', `MaleText_loc4`='视线……越来越模糊……看……看不见了……', `MaleText_loc5`='視線...模糊...看...不見...', `MaleText_loc7`='Visión... borrosa... no puedo... ver...' WHERE `ID`=28931;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도... 도와줘... 누구든... 아무라도...', `MaleText_loc4`='救……救命……来人……', `MaleText_loc5`='救救我...誰...誰來...', `MaleText_loc7`='A... ayuda... Alguien... Quien sea...' WHERE `ID`=28932;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽을 것 같아...', `MaleText_loc4`='我快死了……', `MaleText_loc5`='我要死了...', `MaleText_loc7`='Me muero...' WHERE `ID`=28933;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공격하는 편이 수비하는 편을 제한 시간 안에 무찌르지 못했습니다! 보너스를 받을 수 없습니다!', `MaleText_loc4`='进攻方未能在规定时间内击败防守方！不能获得奖励！', `MaleText_loc5`='進攻隊伍無法勝過防守隊伍的佔領時間!沒有額外獎勵!', `MaleText_loc7`='¡El equipo atacante no ha conseguido superar el tiempo de captura del equipo defensor! ¡Te quedas sin bonificación!' WHERE `ID`=28934;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 녀석들도 처리할 수 있는지 한번 보자! [PH]', `MaleText_loc4`='Lets see you try that again! [PH]', `MaleText_loc5`='看你還能嘗試什麼把戲![PH]', `MaleText_loc7`='¡Veamos si intentas eso otra vez!' WHERE `ID`=28935;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 이제 우리 못 잡아! 이젠 우리가 너 혼내 준다. 나쁜 언데드야! 나빠!', `MaleText_loc4`='我们躲在你身后，这次你休想抓到我们！现在要好好教训你！哼！', `MaleText_loc5`='現在你無法偷偷抓住我們了!現在我們傷害你們這些壞不死生物。壞蛋!', `MaleText_loc7`='¡No pillarnos por la espalda! Ahora nosotros hacer daño a no-muertos malos. ¡MALOS!' WHERE `ID`=28936;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크고 나쁜 언데드 녀석아! 넌 이제 죽었다! 잠자는 제피크를 건드렸겠다!', `MaleText_loc4`='坏东西，你很快就要死了！你再也不能打扰瑟匹克睡觉啦！', `MaleText_loc5`='你們這些又大又壞的不死生物都得死!這回你不會逮到賽匹克在睡覺了!', `MaleText_loc7`='¡Tú ir a morir, cosa grande no-muerta mala! ¡Tú no pillar a Zepik dormido esta vez!' WHERE `ID`=28937;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구덩이에 들어가라! 이 쓰레기들!', `MaleText_loc4`='没用的废物，滚到坑里去！', `MaleText_loc5`='滾進洞裡去吧，你們這些沒用的垃圾!', `MaleText_loc7`='¡Métete en el foso, inútil montón de basura!' WHERE `ID`=28938;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구덩이 밖에 있는 구울에겐 채찍 맛을 보여주겠다!', `MaleText_loc4`='要么滚到坑里去，要么就吃鞭子！', `MaleText_loc5`='把食屍鬼丟進洞裡頭去，否則就得挨打!', `MaleText_loc7`='¡O mete al necrófago en el foso o se enfrenta a la correa!' WHERE `ID`=28939;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구울! 구덩이로! 당장!', `MaleText_loc4`='食尸鬼！进坑！快点！', `MaleText_loc5`='食屍鬼!洞穴!現在!', `MaleText_loc7`='¡NECRÓFAGO! ¡FOSO! ¡AHORA!' WHERE `ID`=28940;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='재로 만들어 날려 버리기 전에 어서 구덩이로 돌아가라!', `MaleText_loc4`='滚进坑里去，否则我就将你轰成渣！', `MaleText_loc5`='在我把你變成一堆塵土與大便之前，滾進那個洞裡去!', `MaleText_loc7`='¡Métete en ese foso antes de que te convierta en un montón de ceniza y heces!' WHERE `ID`=28941;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='의지도 없는 쓰레기들! 어서 구덩이로 돌아가라!', `MaleText_loc4`='没脑子的蠢货！滚到坑里去！', `MaleText_loc5`='滾開你們這些沒有大腦的廢物!滾回洞裡去!', `MaleText_loc7`='¡Vuelve desgraciado sin cerebro! ¡Vuelve al foso!' WHERE `ID`=28942;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구덩이가 널 부른다, 졸개 녀석아. 들어가라. 당장!', `MaleText_loc4`='我命令你们，立刻进坑！就是现在！', `MaleText_loc5`='洞穴在召喚你們了，雜魚。快去。現在!', `MaleText_loc7`='El foso te llama, esbirro. Entra en él. ¡AHORA!' WHERE `ID`=28943;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스가 티탄의 차원문을 점령했습니다!', `MaleText_loc4`='联盟占领了泰坦的传送门！', `MaleText_loc5`='聯盟佔領了泰坦傳送門!', `MaleText_loc7`='¡La Alianza ha capturado el portal de los titanes!' WHERE `ID`=28944;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드가 티탄의 차원문을 점령했습니다!', `MaleText_loc4`='部落占领了泰坦的传送门！', `MaleText_loc5`='部落佔領了泰坦傳送門!', `MaleText_loc7`='¡La Horda ha capturado el portal de los titanes!' WHERE `ID`=28945;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고대의 해안 전투가 끝났습니다!', `MaleText_loc4`='远古海滩之战结束了！', `MaleText_loc5`='遠祖灘頭的戰鬥結束!', `MaleText_loc7`='¡La batalla por la Playa de los Ancestros ha terminado!' WHERE `ID`=28946;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n, 내게 오너라. 난 여기 짐토르가에 있다.', `FemaleText_loc4`='$n，到我这里来。我就在希姆托加。', `FemaleText_loc5`='$n，請到我這兒來。我現在人在辛托加。', `FemaleText_loc7`='Por favor, $n, ven aquí. Ahora estoy en Zim''Torga.' WHERE `ID`=28947;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예언자가 어떻게 하면 여신에게서 힘을 가장 잘 빼앗을 수 있을지 고심합니다.', `MaleText_loc4`='先知陷入了沉思，盘算着如何才能巧妙地偷取女神的力量。', `MaleText_loc5`='預言者思考著要如何控制從他的女神身上偷來的力量。', `MaleText_loc7`='El profeta medita buscando la mejor manera de robar el poder de su diosa.' WHERE `ID`=28948;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 하르코아에게 조언을 구하는 기도를 올리려다가 곧 마음을 바꿉니다.', `MaleText_loc4`='%s打算祈祷一番，希望哈克娅能给出建议，但最终决定不这么做。', `MaleText_loc5`='%s開始向哈寇亞祈求指引，但卻想得更多。', `MaleText_loc7`='El %s empieza a rezar a Har''koa en busca de consejo, pero después se lo piensa mejor.' WHERE `ID`=28949;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 계획의 진행이 느린 것에 대해 중얼거리며 불평을 하다가 다시 의식을 시작합니다.', `MaleText_loc4`='%s暗自嘀咕，一边抱怨自己的计划进展缓慢，一边继续进行仪式。', `MaleText_loc5`='%s一邊繼續儀式，一邊喃喃自語地抱怨計畫進展速度的緩慢。', `MaleText_loc7`='Farfullando algo acerca de lo lentamente que se desarrollan sus planes, el %s continúa con sus rituales.' WHERE `ID`=28950;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭔가 잘못된 것을 발견한 듯 예언자가 고개를 갸우뚱합니다.', `MaleText_loc4`='先知扭了扭脖子，似乎察觉到出了什么差错。', `MaleText_loc5`='預言者輕微地彎過頭，發現到有些事情不對勁。', `MaleText_loc7`='El profeta inclina ligeramente su cabeza, como si se hubiera dado cuenta de que algo va mal.' WHERE `ID`=28951;
