UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놀랍군, 놀라워! 또 구울이라니!', `MaleText_loc4`='啧啧！又一个食尸鬼！', `MaleText_loc5`='驚喜，驚喜!另一隻食屍鬼', `MaleText_loc7`='¡Sorpresa, sorpresa! ¡Otro necrófago!' WHERE `ID`=29038;
