UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 뭘 좀 먹을 시간이다, 야수여. 일어나라!', `MaleText_loc4`='开饭的时间到了。醒来吧！', `MaleText_loc5`='進食的時候到了，爪牙。醒來吧!', `MaleText_loc7`='Es hora de alimentarse, esbirro. ¡Despierta!' WHERE `ID`=29046;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='눈을 떠라, 형제자매들이여! 대참사를 주시하라!', `MaleText_loc4`='兄弟姐妹们，睁开双眼！凝视命运的启示吧！', `MaleText_loc5`='睜開你的眼睛，兄弟姊妹!看看毀天滅地的力量!', `MaleText_loc7`='¡Abrid los ojos, hermanos y hermanas! ¡OBSERVAD EL APOCALIPSIS!' WHERE `ID`=29047;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정복당한 자들의 고통이 하늘을 찌를 것이다!', `MaleText_loc4`='天空吞噬着被征服者的痛苦！', `MaleText_loc5`='天空也以被征服的弱者為食!', `MaleText_loc7`='¡El propio cielo se alimenta del sufrimiento de los conquistados!' WHERE `ID`=29048;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='허약한 붉은십자군 따위가 우릴 막을 수는 없다!', `MaleText_loc4`='血色十字军休想阻止我们！', `MaleText_loc5`='血色十字軍是無力阻擋我們的!', `MaleText_loc7`='¡La Cruzada Escarlata no tiene poder para detenernos!' WHERE `ID`=29049;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저항하는 자는 시체가 되어 우리의 일원이 될 뿐이다!', `MaleText_loc4`='那些尸体只会令我们的军队日益壮大！', `MaleText_loc5`='那些屍體只不過是用來餵養我們持續增長的大軍!', `MaleText_loc7`='¡Los cadáveres de aquellos que lo intentan solo sirven para alimentar a nuestra creciente multitud!' WHERE `ID`=29050;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='붉은십자군 함대가 갈라진 해안에 있는 폐허에 자리를 잡았다!', `MaleText_loc4`='停泊在破碎海岸的十字军舰队已成残骸！', `MaleText_loc5`='血色艦隊在破碎的海岸邊毀滅!', `MaleText_loc7`='¡La flota Escarlata yace en ruinas sobre la costa destruida!' WHERE `ID`=29051;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적 하나를 죽일 때마다 우리 힘이 커진다! 놈들을 가엾게 여기지 마라!', `MaleText_loc4`='天灾军团的战士一定会击败敌人！', `MaleText_loc5`='每殺死一個敵人，我們的力量就會增加一分!絕對不能心生憐憫!', `MaleText_loc7`='¡Nuestra fuerza crece con cada enemigo que matamos! ¡No debemos ceder!' WHERE `ID`=29052;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕께서 너희 모두에게 말씀하셨다! 그분의 말씀이 너희 사이에서 다시 한번 울려 퍼지게 하라!', `MaleText_loc4`='巫妖王和你们都谈过！让他的教诲再次引起你们的共鸣吧！', `MaleText_loc5`='巫妖王對你們每一個都說過話!讓他的言語再次在你們心中迴響吧!', `MaleText_loc7`='¡El Rey Exánime ha hablado con cada uno de ustedes! ¡Dejen que sus palabras resuenen en su interior una vez más!' WHERE `ID`=29053;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 죽여라', `MaleText_loc4`='是伟大的巫妖王将你们重新唤醒。', `MaleText_loc5`='全。都。得。死。', `MaleText_loc7`='TODOS. DEBEN. MORIR.' WHERE `ID`=29054;
