UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠이 다가오면 붉은십자군에 종지부를 찍으리라. 너희는 다시 한번 싸울 것이다! 스컬지를 위하여! 리치 왕을 위하여!', `MaleText_loc4`='血色十字军的末日即将来临。我的骑士们，用你们手中的长剑，让他们瞧瞧究竟什么是真正的血色！', `MaleText_loc5`='黑暗將至，隨之而來的就是血色十字軍的末日。你將要再次作戰!為了天譴軍團!為了巫妖王!', `MaleText_loc7`='Con la oscuridad que se acerca llega el final de la Cruzada Escarlata. ¡Lucharéis una vez más! ¡Por la Plaga! ¡Por el Rey Exánime!' WHERE `ID`=29060;
