UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그냥 일반적인 호박 조각도 역병 가마솥에 들어가면 부패와 역병의 원천이 되지!', `MaleText_loc4`='一旦放置天灾锅，这块看似普通的南瓜田就会成为诅咒的源头！', `MaleText_loc5`='這看起來不過是一小塊普通的南瓜田，但等到瘟疫大鍋就位，它將會變成疾病、老鼠與瘟疫的源頭!', `MaleText_loc7`='Ahora puede parecer una plantación de calabazas normal, ¡pero cuando coloquemos la caldera de peste, se convertirá en una fuente de enfermedad, podredumbre y peste!' WHERE `ID`=29062;
