UPDATE `locales_broadcast_text` SET `MaleText_loc1`='낙스라마스가 사라졌다고? 그게 무슨 상관이야! 아케루스가 여기 있고 죽음의 기사들이 모두를 죽이는 이 상황에!', `MaleText_loc4`='纳克萨玛斯飞走了？我们才不关心呢！来自阿彻鲁斯的死亡骑士正在大肆屠杀我们的同胞！', `MaleText_loc5`='納克薩瑪斯不見了?誰理他啊!現在是亞榭洛在這裡，死亡騎士大開殺戒!', `MaleText_loc7`='¿Naxxramas ha desaparecido? ¡A quién le importa! ¡Acherus está aquí y los caballeros de la Muerte están matando a todo el mundo!', `FemaleText_loc1`='낙스라마스가 사라졌다고? 그게 무슨 상관이야! 아케루스가 여기 있고 죽음의 기사들이 모두를 죽이는 이 상황에!', `FemaleText_loc4`='纳克萨玛斯飞走了？我们才不关心呢！来自阿彻鲁斯的死亡骑士正在大肆屠杀我们的同胞！', `FemaleText_loc5`='納克薩瑪斯不見了?誰理他啊!現在是亞榭洛在這裡，死亡騎士大開殺戒!', `FemaleText_loc7`='¿Naxxramas ha desaparecido? ¡A quién le importa! ¡Acherus está aquí y los caballeros de la Muerte están matando a todo el mundo!' WHERE `ID`=29108;
