UPDATE `locales_broadcast_text` SET `MaleText_loc1`='41번째 녀석을 해치웠다오! 내 실력이 어떻소?', `MaleText_loc4`='第41个！我的技术不错吧？', `MaleText_loc5`='剛殺了41!我的技巧如何啊?', `MaleText_loc7`='¡Acabo de llegar al número 41! ¿Qué te parece mi habilidad?' WHERE `ID`=29116;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='41번째! 삼분의 이라오. 어서 따라오시오!', `MaleText_loc4`='41！已经完成2/3啦。再加把劲儿！', `MaleText_loc5`='41!還差三分之二。最好加緊腳步!', `MaleText_loc7`='¡41! Dos tercios del total. ¡Será mejor te esfuerces más!' WHERE `ID`=29117;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이보시오! 방금 그 녀석을 쏘려던 참인데! 반칙!', `MaleText_loc4`='嘿！我分明已经瞄准了那只猎物。你偷了我的猎物！', `MaleText_loc5`='嘿!我才剛把牠排好的。把小偷殺掉!', `MaleText_loc7`='¡Oye! Estaba apuntando a ese. ¡Ladrón de muertes!' WHERE `ID`=29118;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으으, 방금 48번째를 잡았다오. 이거 힘들어지는데.', `MaleText_loc4`='啊，才到48。越来越困难了。', `MaleText_loc5`='啊，我才殺了48，越來越困難了。', `MaleText_loc7`='Argh, acabo de llegar al número 48. Esto empieza a ponerse difícil.' WHERE `ID`=29119;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누군가 한 번도 나보다 앞서지 못하는 것 같소만. 꽤 힘들긴 했지만 난 48마리째 잡았다오.', `MaleText_loc4`='有人将那些从我手中逃掉的猎物都杀了。能有48个的成绩已经很不容易了。', `MaleText_loc5`='有人在我之後把所有的獵物都殺光了。艱困的勝利數字48，拿去。', `MaleText_loc7`='Alguien ha estado matando a todas las presas por debajo de mí. Me ha costado llegar al número 48.' WHERE `ID`=29120;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='48. 이제 약간 속도를 늦추지요.', `MaleText_loc4`='48。速度逐渐慢下来了。', `MaleText_loc5`='第48。開始有點慢下來了。', `MaleText_loc7`='Número 48. Empiezo a tomármelo con más calma.' WHERE `ID`=29121;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 놀이를 찾아야겠군. 지금쯤은 48마리는 넘게 잡으셨길 바랐는데 말이오.', `MaleText_loc4`='我要去别的地方找些猎物了。按照原定计划，应该不止48个啊。', `MaleText_loc5`='得去其他地方找獵物了，希望到現在為止能超過48頭。', `MaleText_loc7`='Tengo que ir a otro lugar a buscar más animales. Esperaba haber pasado de 48 ya.' WHERE `ID`=29122;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하, 54! 목표가 눈앞이라오!', `MaleText_loc4`='哈，54！进入最后冲刺阶段！', `MaleText_loc5`='哈，54!現在就是最後階段囉!', `MaleText_loc7`='¡Ja! ¡54! ¡En la recta final!' WHERE `ID`=29123;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='54! 당신은 날 이길 수 없소!', `MaleText_loc4`='54！我不会输给你的！', `MaleText_loc5`='第54!怎麼可能讓你打敗我!', `MaleText_loc7`='¡Número 54! ¡No pienso dejar que me ganes!' WHERE `ID`=29124;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='54번째! 이기기 어렵겠죠?', `MaleText_loc4`='54！压倒性的优势啊！', `MaleText_loc5`='54!這領先真難以超越!', `MaleText_loc7`='¡54! ¡Seguro que es una ventaja irrecuperable!' WHERE `ID`=29125;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='54번째 녀석이었다오! 곧 내게 축하의 인사를 건네게 될 거요!', `MaleText_loc4`='54了！准备祝贺我吧！', `MaleText_loc5`='那可是第54!你馬上就得恭喜我啦!', `MaleText_loc7`='¡Con ese eran 54! ¡Pronto estarás dándome la enhorabuena!' WHERE `ID`=29126;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 오셨군요. 주인님께서 당신이 곧 오실 거라고 말씀하셨습니다.', `MaleText_loc4`='啊……你来了。主人说过，你很快就会到的。', `MaleText_loc5`='啊...你在這。主人告訴我們你不久就會到了。', `MaleText_loc7`='Ahh... Aquí estás... El maestro nos dijo que llegarías pronto.' WHERE `ID`=29127;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절 따라오시지요, $n 님. 보셔야 할 게 많습니다...', `MaleText_loc4`='请跟我来，$n。有很多东西要给你看……', `MaleText_loc5`='請跟著我，$n。還有很多要讓你看看...', `MaleText_loc7`='Por favor, sígueme, $n. Tienes que ver muchas cosas...' WHERE `ID`=29128;
