UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나를 칠흑의 요새로 보내 다오.', `MaleText_loc4`='带我去黑锋要塞吧。', `MaleText_loc5`='載我去黯黑堡，馬兒。', `MaleText_loc7`='Caballo, llévame a El Bastión de Ébano.', `FemaleText_loc1`='나를 칠흑의 요새로 보내 다오.', `FemaleText_loc4`='带我去黑锋要塞吧。', `FemaleText_loc5`='載我去黯黑堡，馬兒。', `FemaleText_loc7`='Caballo, llévame a El Bastión de Ébano.' WHERE `ID`=29130;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저를 동부 역병지대로 보내 주십시오!', `MaleText_loc4`='带我去东瘟疫之地！', `MaleText_loc5`='送我去東瘟疫之地!', `MaleText_loc7`='¡Llévame a las Tierras de la Peste del Este!', `FemaleText_loc1`='저를 동부 역병지대로 보내 주십시오!', `FemaleText_loc4`='带我去东瘟疫之地！', `FemaleText_loc5`='送我去東瘟疫之地!', `FemaleText_loc7`='¡Llévame a las Tierras de la Peste del Este!' WHERE `ID`=29131;
