UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"진홍빛 서광"이 뭐지?', `MaleText_loc4`='“血色的黎明”是什么？', `MaleText_loc5`='「赤紅黎明」是什麼東西?', `MaleText_loc7`='¿Qué es el "Alba Carmesí"?', `FemaleText_loc1`='"진홍빛 서광"이 뭐지?', `FemaleText_loc4`='“血色的黎明”是什么？', `FemaleText_loc5`='「赤紅黎明」是什麼東西?', `FemaleText_loc7`='¿Qué es el "Alba Carmesí"?' WHERE `ID`=29133;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"진홍빛 서광"의 정체가 뭔지 말하지 않으면 매질이 계속될 것이다!', `MaleText_loc4`='关于“血色的黎明”，你都知道些什么？快说，不然就等着吃鞭子吧！', `MaleText_loc5`='告訴我你對「赤紅黎明」知道多少，否則你只是繼續討打!', `MaleText_loc7`='¡Cuéntame lo que sepas sobre el "Alba Carmesí" o las palizas continuarán!', `FemaleText_loc1`='"진홍빛 서광"의 정체가 뭔지 말하지 않으면 매질이 계속될 것이다!', `FemaleText_loc4`='关于“血色的黎明”，你都知道些什么？快说，不然就等着吃鞭子吧！', `FemaleText_loc5`='告訴我你對「赤紅黎明」知道多少，否則你只是繼續討打!', `FemaleText_loc7`='¡Cuéntame lo que sepas sobre el "Alba Carmesí" o las palizas continuarán!' WHERE `ID`=29134;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='인간이여, 난 지금까지 예의 바르게 대했다! "진홍빛 서광"이 뭐냐?', `MaleText_loc4`='我对你已经够客气的了！“血色的黎明”到底是什么？', `MaleText_loc5`='我不會再對你們這些人好聲好氣了，人類!什麼是「赤紅黎明」?', `MaleText_loc7`='¡Me he cansado de ser cortés con los de tu calaña, humano! ¿Qué es el "Alba Carmesí"?', `FemaleText_loc1`='인간이여, 난 지금까지 예의 바르게 대했다! "진홍빛 서광"이 뭐냐?', `FemaleText_loc4`='我对你已经够客气的了！“血色的黎明”到底是什么？', `FemaleText_loc5`='我不會再對你們這些人好聲好氣了，人類!什麼是「赤紅黎明」?', `FemaleText_loc7`='¡Me he cansado de ser cortés con los de tu calaña, humano! ¿Qué es el "Alba Carmesí"?' WHERE `ID`=29135;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"진홍빛 서광"이 도대체 뭐냐! 말해라!', `MaleText_loc4`='“血色的黎明”究竟是什么！说！', `MaleText_loc5`='「赤紅黎明」!那是什麼!說!', `MaleText_loc7`='"¡Alba Carmesí!" ¿Qué es? ¡Habla!', `FemaleText_loc1`='"진홍빛 서광"이 도대체 뭐냐! 말해라!', `FemaleText_loc4`='“血色的黎明”究竟是什么！说！', `FemaleText_loc5`='「赤紅黎明」!那是什麼!說!', `FemaleText_loc7`='"¡Alba Carmesí!" ¿Qué es? ¡Habla!' WHERE `ID`=29136;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='붉은십자군의 개야, 내가 지치기라도 할 것 같으냐?! "진홍빛 서광"이 뭔지 말해라!', `MaleText_loc4`='我有的是精力对付你！说吧，“血色的黎明”是什么！', `MaleText_loc5`='我可以一直這樣下去，血色畜生!告訴我什麼是「赤紅黎明」!', `MaleText_loc7`='¡Puedo seguir haciendo esto durante mucho tiempo, perro Escarlata! Háblame acerca del "Alba Carmesí"!', `FemaleText_loc1`='붉은십자군의 개야, 내가 지치기라도 할 것 같으냐?! "진홍빛 서광"이 뭔지 말해라!', `FemaleText_loc4`='我有的是精力对付你！说吧，“血色的黎明”是什么！', `FemaleText_loc5`='我可以一直這樣下去，血色畜生!告訴我什麼是「赤紅黎明」!', `FemaleText_loc7`='¡Puedo seguir haciendo esto durante mucho tiempo, perro Escarlata! Háblame acerca del "Alba Carmesí"!' WHERE `ID`=29137;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언젠가는 이야기하게 될 것이다! "진홍빛 서광"이 무엇인지 말해라. 그러면 목숨은 살려주겠다!', `MaleText_loc4`='我迟早会掏出埋在你心里的所有秘密！只要你肯开口，我就饶你一命！', `MaleText_loc5`='我會把秘密從你的靈魂中撕下來!告訴我什麼是「赤紅黎明」，你就能保住你的小命!', `MaleText_loc7`='¡Arrancaré los secretos de tu alma! ¡Háblame sobre el "Alba Carmesí" y quizá te perdone la vida!', `FemaleText_loc1`='언젠가는 이야기하게 될 것이다! "진홍빛 서광"이 무엇인지 말해라. 그러면 목숨은 살려주겠다!', `FemaleText_loc4`='我迟早会掏出埋在你心里的所有秘密！只要你肯开口，我就饶你一命！', `FemaleText_loc5`='我會把秘密從你的靈魂中撕下來!告訴我什麼是「赤紅黎明」，你就能保住你的小命!', `FemaleText_loc7`='¡Arrancaré los secretos de tu alma! ¡Háblame sobre el "Alba Carmesí" y quizá te perdone la vida!' WHERE `ID`=29138;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 생명이 소중하지 않단 말이냐? "진홍빛 서광"에 대해서 말해라. 그러면 네 고통을 끝내주마.', `MaleText_loc4`='你的性命就这么不值钱吗？只要你告诉我关于“血色的黎明”的资料，我就立即结束你的痛苦。', `MaleText_loc5`='你的生命就這麼一點價值嗎?只要告訴我所需要知道的「赤紅黎明」，我會很快的結束你的折磨。', `MaleText_loc7`='¿Tan poco aprecias tu vida? Solo cuéntame lo que necesito saber sobre el "Alba Carmesí" y acabaré rápidamente con tu sufrimiento.', `FemaleText_loc1`='네 생명이 소중하지 않단 말이냐? "진홍빛 서광"에 대해서 말해라. 그러면 네 고통을 끝내주마.', `FemaleText_loc4`='你的性命就这么不值钱吗？只要你告诉我关于“血色的黎明”的资料，我就立即结束你的痛苦。', `FemaleText_loc5`='你的生命就這麼一點價值嗎?只要告訴我所需要知道的「赤紅黎明」，我會很快的結束你的折磨。', `FemaleText_loc7`='¿Tan poco aprecias tu vida? Solo cuéntame lo que necesito saber sobre el "Alba Carmesí" y acabaré rápidamente con tu sufrimiento.' WHERE `ID`=29139;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='인간아, 슬슬 지치는구나. "진홍빛 서광"에 대해서 말하지 않으면 맨손으로 널 박살 내겠다!', `MaleText_loc4`='我不想再费唇舌了。把“血色的黎明”的秘密告诉我，否则我就要你好看！', `MaleText_loc5`='人類，我已經厭煩這些遊戲了。告訴我「赤色黎明」的事情，否則我會徒手把你的脊椎扯出來!', `MaleText_loc7`='Me estoy cansando de estos juegos, humano. ¡Háblame sobre el "Alba Carmesí" o te arrancaré la columna con mis manos desnudas!', `FemaleText_loc1`='인간아, 슬슬 지치는구나. "진홍빛 서광"에 대해서 말하지 않으면 맨손으로 널 박살 내겠다!', `FemaleText_loc4`='我不想再费唇舌了。把“血色的黎明”的秘密告诉我，否则我就要你好看！', `FemaleText_loc5`='人類，我已經厭煩這些遊戲了。告訴我「赤色黎明」的事情，否則我會徒手把你的脊椎扯出來!', `FemaleText_loc7`='Me estoy cansando de estos juegos, humano. ¡Háblame sobre el "Alba Carmesí" o te arrancaré la columna con mis manos desnudas!' WHERE `ID`=29140;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구역질나는 스컬지 같으니! 난 아무것도 말하지 않을 거다!', `MaleText_loc4`='呸，我不会告诉你的！', `MaleText_loc5`='我什麼都不會說的，天譴軍雜碎!', `MaleText_loc7`='¡No te diré nada, escoria de la Plaga!', `FemaleText_loc1`='구역질나는 스컬지 같으니! 난 아무것도 말하지 않을 거다!', `FemaleText_loc4`='呸，我不会告诉你的！', `FemaleText_loc5`='我什麼都不會說的，天譴軍雜碎!', `FemaleText_loc7`='¡No te diré nada, escoria de la Plaga!' WHERE `ID`=29141;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 죽여야 할 거다, 이 괴물아. 난 아무것도 말하지 않을 테니까!', `MaleText_loc4`='你杀了我吧，怪物。我什么都不会说！', `MaleText_loc5`='殺了我吧，怪物。我什麼都不會告訴你的!', `MaleText_loc7`='Tendrás que matarme, monstruo. ¡No te diré NADA!', `FemaleText_loc1`='날 죽여야 할 거다, 이 괴물아. 난 아무것도 말하지 않을 테니까!', `FemaleText_loc4`='你杀了我吧，怪物。我什么都不会说！', `FemaleText_loc5`='殺了我吧，怪物。我什麼都不會告訴你的!', `FemaleText_loc7`='Tendrás que matarme, monstruo. ¡No te diré NADA!' WHERE `ID`=29142;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아윽... 이 고통... 내가 어린애였을 때 학교에서 받은 매질이 이렇게 아팠지...', `MaleText_loc4`='啊……痛……差点就赶上我小时候在学校里受过的鞭刑了。', `MaleText_loc5`='啊...這痛苦...這痛苦幾乎像我小時候在文法學校被藤條抽一樣難以忍受。', `MaleText_loc7`='Argh... El dolor... El dolor es casi tan insoportable como los azotes que recibía en el colegio cuando no era más que un niño.', `FemaleText_loc1`='아윽... 이 고통... 내가 어린애였을 때 학교에서 받은 매질이 이렇게 아팠지...', `FemaleText_loc4`='啊……痛……差点就赶上我小时候在学校里受过的鞭刑了。', `FemaleText_loc5`='啊...這痛苦...這痛苦幾乎像我小時候在文法學校被藤條抽一樣難以忍受。', `FemaleText_loc7`='Argh... El dolor... El dolor es casi tan insoportable como los azotes que recibía en el colegio cuando no era más que una niña.' WHERE `ID`=29143;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네... 네놈은... 아무것도 얻지 못한다...', `MaleText_loc4`='你……你什么都别想……别想知道……', `MaleText_loc5`='你...你什麼都得不到...就像它...', `MaleText_loc7`='Tú... no conseguirás nada... Y acéptalo...', `FemaleText_loc1`='네... 네놈은... 아무것도 얻지 못한다...', `FemaleText_loc4`='你……你什么都别想……别想知道……', `FemaleText_loc5`='你...你什麼都得不到...就像它...', `FemaleText_loc7`='Tú... no conseguirás nada... Y acéptalo...' WHERE `ID`=29144;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겨우 이걸 고통이라고 부르느냐? 하! 썩어 없어질 이 껍데기 따위 얼마든지 파괴해라. 나는 천상으로 갈 테니!', `MaleText_loc4`='你以为自己下手很重？我难以忍受这痛苦？哈哈！摧毁这凡人的躯壳，我就能升入天堂！', `MaleText_loc5`='你認為這就是痛苦?這就是折磨?哈!摧毀這具凡人的軀體我才能超脫凡界啊!', `MaleText_loc7`='¿Crees que esto es dolor? ¿Sufrimiento? ¡JA! ¡Destruye esta cáscara mortal para que pueda subir al cielo!', `FemaleText_loc1`='겨우 이걸 고통이라고 부르느냐? 하! 썩어 없어질 이 껍데기 따위 얼마든지 파괴해라. 나는 천상으로 갈 테니!', `FemaleText_loc4`='你以为自己下手很重？我难以忍受这痛苦？哈哈！摧毁这凡人的躯壳，我就能升入天堂！', `FemaleText_loc5`='你認為這就是痛苦?這就是折磨?哈!摧毀這具凡人的軀體我才能超脫凡界啊!', `FemaleText_loc7`='¿Crees que esto es dolor? ¿Sufrimiento? ¡JA! ¡Destruye esta cáscara mortal para que pueda subir al cielo!' WHERE `ID`=29145;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='매질이 꼭 계집애처럼 약하구나. 겨우 그 정도로 되겠느냐?', `MaleText_loc4`='我说，你挥舞鞭子的力道像个小姑娘。你就这点能耐？', `MaleText_loc5`='老實說，你出拳像個娘們似的，你就這麼點能耐嗎?', `MaleText_loc7`='Pegas como una chica. En serio. ¿No puedes hacerlo mejor?', `FemaleText_loc1`='매질이 꼭 계집애처럼 약하구나. 겨우 그 정도로 되겠느냐?', `FemaleText_loc4`='我说，你挥舞鞭子的力道像个小姑娘。你就这点能耐？', `FemaleText_loc5`='老實說，你出拳像個娘們似的，你就這麼點能耐嗎?', `FemaleText_loc7`='Pegas como una chica. En serio. ¿No puedes hacerlo mejor?' WHERE `ID`=29146;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진홍빛 뭐라고? 들어본 적도 없다...', `MaleText_loc4`='什么血色啊？我从来没有听说过……', `MaleText_loc5`='你說赤紅什麼?從沒聽過...', `MaleText_loc7`='¿El qué carmesí? No lo he oído nunca...', `FemaleText_loc1`='진홍빛 뭐라고? 들어본 적도 없다...', `FemaleText_loc4`='什么血色啊？我从来没有听说过……', `FemaleText_loc5`='你說赤紅什麼?從沒聽過...', `FemaleText_loc7`='¿El qué carmesí? No lo he oído nunca...' WHERE `ID`=29147;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고통이 지나가는 건 순식간이다. 고위사령관님께서 내리실 벌에 비하면 시시하지.', `MaleText_loc4`='这样的痛苦只是暂时的。如果我泄漏了机密，阿比迪斯将军肯定会令我生不如死……', `MaleText_loc5`='痛苦是短暫的，和大將軍對我所作的一切相比，這算不了什麼...', `MaleText_loc7`='Este dolor es temporal. No tiene ni punto de comparación con lo que me haría la Alta General...', `FemaleText_loc1`='고통이 지나가는 건 순식간이다. 고위사령관님께서 내리실 벌에 비하면 시시하지.', `FemaleText_loc4`='这样的痛苦只是暂时的。如果我泄漏了机密，阿比迪斯将军肯定会令我生不如死……', `FemaleText_loc5`='痛苦是短暫的，和大將軍對我所作的一切相比，這算不了什麼...', `FemaleText_loc7`='Este dolor es temporal. No tiene ni punto de comparación con lo que me haría la Alta General...' WHERE `ID`=29148;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐든 말하겠다! 그만해라! 제발!', `MaleText_loc4`='我说！住手！求你了！', `MaleText_loc5`='我什麼都告訴你!停手!求求你!', `MaleText_loc7`='¡Te lo contaré todo! ¡PARA! ¡POR FAVOR!', `FemaleText_loc1`='뭐든 말하겠다! 그만해라! 제발!', `FemaleText_loc4`='我说！住手！求你了！', `FemaleText_loc5`='我什麼都告訴你!停手!求求你!', `FemaleText_loc7`='¡Te lo contaré todo! ¡PARA! ¡POR FAVOR!' WHERE `ID`=29149;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리... 우린 "진홍빛 서광"은 깨어남이라고만 들었다. 너... 너도 알겠지만 빛은 고위사령관님께 말한다. 빛이...', `MaleText_loc4`='我们……我们只知道“血色的黎明”象征着觉醒。你……你瞧，圣光给了阿比迪斯将军新的启示。是圣光……', `MaleText_loc5`='我們...我們只知道「赤紅黎明」是一次覺醒。你...你知道，聖光對大將軍諭示。這是聖光...', `MaleText_loc7`='Solo... Solo nos han dicho que el "Alba Carmesí" es un despertar. Verás... la Luz le habla a la Alta General. Es la Luz...', `FemaleText_loc1`='우리... 우린 "진홍빛 서광"은 깨어남이라고만 들었다. 너... 너도 알겠지만 빛은 고위사령관님께 말한다. 빛이...', `FemaleText_loc4`='我们……我们只知道“血色的黎明”象征着觉醒。你……你瞧，圣光给了阿比迪斯将军新的启示。是圣光……', `FemaleText_loc5`='我們...我們只知道「赤紅黎明」是一次覺醒。你...你知道，聖光對大將軍諭示。這是聖光...', `FemaleText_loc7`='Solo... Solo nos han dicho que el "Alba Carmesí" es un despertar. Verás... la Luz le habla a la Alta General. Es la Luz...' WHERE `ID`=29150;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛이 우리를 인도한다. 이번 일은 너희가 오기 전부터 추진되었다. 우... 우린 우리가 들은 대로 한다. 반드시 해야 하는 일이다.', `MaleText_loc4`='是圣光在指引我们。天灾军团抵达之前，这次行动就已经开始了……我们……只是简单地奉命行事。我们必须服从军令。', `MaleText_loc5`='指引我們的聖光，這個行動早在你來以前就已然進行了...我們...我們只是依命行事，非完成不可。', `MaleText_loc7`='La Luz que nos guía. Esto se puso en marcha antes de que llegarais... Nosotros... hacemos lo que nos mandan. Es lo que hay que hacer.', `FemaleText_loc1`='빛이 우리를 인도한다. 이번 일은 너희가 오기 전부터 추진되었다. 우... 우린 우리가 들은 대로 한다. 반드시 해야 하는 일이다.', `FemaleText_loc4`='是圣光在指引我们。天灾军团抵达之前，这次行动就已经开始了……我们……只是简单地奉命行事。我们必须服从军令。', `FemaleText_loc5`='指引我們的聖光，這個行動早在你來以前就已然進行了...我們...我們只是依命行事，非完成不可。', `FemaleText_loc7`='La Luz que nos guía. Esto se puso en marcha antes de que llegarais... Nosotros... hacemos lo que nos mandan. Es lo que hay que hacer.' WHERE `ID`=29151;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그밖에는 아는 게 없다... 고위사령관님은 갈 자와 남을 자를 결정하신다. 더는 아는 게 없다... 제발 믿어다오!', `MaleText_loc4`='其他的我就不清楚了……阿比迪斯将军决定谁走谁留。我只知道这些……你要相信我啊！', `MaleText_loc5`='其餘的我所知甚少...大將軍選定了誰該走、誰該留下。我沒有保留任何事...你一定要相信我!', `MaleText_loc7`='Sé muy poco más... La Alta General elige quién va y quién se queda atrás. No hay nada más... ¡Tienes que creerme!', `FemaleText_loc1`='그밖에는 아는 게 없다... 고위사령관님은 갈 자와 남을 자를 결정하신다. 더는 아는 게 없다... 제발 믿어다오!', `FemaleText_loc4`='其他的我就不清楚了……阿比迪斯将军决定谁走谁留。我只知道这些……你要相信我啊！', `FemaleText_loc5`='其餘的我所知甚少...大將軍選定了誰該走、誰該留下。我沒有保留任何事...你一定要相信我!', `FemaleText_loc7`='Sé muy poco más... La Alta General elige quién va y quién se queda atrás. No hay nada más... ¡Tienes que creerme!' WHERE `ID`=29152;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만! 제발! 하나 잊고 말하지 않은 게 있다... 하스글렌에서... 곧 급사가 온다...', `MaleText_loc4`='啊！住手！还有一件事我忘记说了……很快就会有信差……从壁炉谷赶来。嗯……', `MaleText_loc5`='不!求你!我忘了講一件事...一個信差很快...要從壁爐谷出發。他...', `MaleText_loc7`='¡NO! ¡POR FAVOR! Se me olvidaba mencionar algo... Pronto vendrá un mensajero... Desde la Vega del Amparo. Él...', `FemaleText_loc1`='그만! 제발! 하나 잊고 말하지 않은 게 있다... 하스글렌에서... 곧 급사가 온다...', `FemaleText_loc4`='啊！住手！还有一件事我忘记说了……很快就会有信差……从壁炉谷赶来。嗯……', `FemaleText_loc5`='不!求你!我忘了講一件事...一個信差很快...要從壁爐谷出發。他...', `FemaleText_loc7`='¡NO! ¡POR FAVOR! Se me olvidaba mencionar algo... Pronto vendrá un mensajero... Desde la Vega del Amparo. Él...' WHERE `ID`=29153;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 숨을 거둡니다.', `MaleText_loc4`='%s终于屈服了。', `MaleText_loc5`='%s在折磨中死去。', `MaleText_loc7`='%s muere por la tortura.', `FemaleText_loc1`='%s|1이;가; 숨을 거둡니다.', `FemaleText_loc4`='%s终于屈服了。', `FemaleText_loc5`='%s在折磨中死去。', `FemaleText_loc7`='%s muere por la tortura.' WHERE `ID`=29154;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 고통이 뭔지 모른다, 괴물아!', `MaleText_loc4`='怪物，你根本不了解什么才是真正的痛苦！', `MaleText_loc5`='你根本不知道什麼是痛苦，怪物!', `MaleText_loc7`='¡No sabes nada acerca del dolor, monstruo!', `FemaleText_loc1`='넌 고통이 뭔지 모른다, 괴물아!', `FemaleText_loc4`='怪物，你根本不了解什么才是真正的痛苦！', `FemaleText_loc5`='你根本不知道什麼是痛苦，怪物!', `FemaleText_loc7`='¡No sabes nada acerca del dolor, monstruo!' WHERE `ID`=29155;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 난 세 번의 단독 심문에서도 살아남았다! 그에 비교하면 이건 아무것도 아니다!', `MaleText_loc4`='哈！我经历过三次严酷的拷问！这根本不算什么！', `MaleText_loc5`='哈!我已經熬過了三次不同的審訊!這根本不算什麼!', `MaleText_loc7`='¡JA! ¡He sobrevivido a tres inquisiciones distintas! ¡Esto no es nada en comparación!', `FemaleText_loc1`='하! 난 세 번의 단독 심문에서도 살아남았다! 그에 비교하면 이건 아무것도 아니다!', `FemaleText_loc4`='哈！我经历过三次严酷的拷问！这根本不算什么！', `FemaleText_loc5`='哈!我已經熬過了三次不同的審訊!這根本不算什麼!', `FemaleText_loc7`='¡JA! ¡He sobrevivido a tres inquisiciones distintas! ¡Esto no es nada en comparación!' WHERE `ID`=29156;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흥! 벌떼가 풀려나서는 쏘아대는 정도지!', `MaleText_loc4`='当心！有只蜜蜂飞出去啦，它气得想到处蛰人呐！', `MaleText_loc5`='小心!蜜蜂正在發狂釘人呢!', `MaleText_loc7`='¡Cuidado! ¡Hay una abeja por ahí suelta y está picando a todo lo que pilla!', `FemaleText_loc1`='흥! 벌떼가 풀려나서는 쏘아대는 정도지!', `FemaleText_loc4`='当心！有只蜜蜂飞出去啦，它气得想到处蛰人呐！', `FemaleText_loc5`='小心!蜜蜂正在發狂釘人呢!', `FemaleText_loc7`='¡Cuidado! ¡Hay una abeja por ahí suelta y está picando a todo lo que pilla!' WHERE `ID`=29157;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조금 간지러웠군...', `MaleText_loc4`='这一鞭就跟挠痒似的……', `MaleText_loc5`='這只是搔癢嘛...', `MaleText_loc7`='Eso me ha hecho cosquillas...', `FemaleText_loc1`='조금 간지러웠군...', `FemaleText_loc4`='这一鞭就跟挠痒似的……', `FemaleText_loc5`='這只是搔癢嘛...', `FemaleText_loc7`='Eso me ha hecho cosquillas...' WHERE `ID`=29158;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='널 조각조각 내서 리치 왕에게 보내주마!', `MaleText_loc4`='我要把你切得粉碎，送还给巫妖王！', `MaleText_loc5`='我要把你撕成碎片送回給巫妖王!', `MaleText_loc7`='¡Te voy a enviar de vuelta con el Rey Exánime hecho trocitos!', `FemaleText_loc1`='널 조각조각 내서 리치 왕에게 보내주마!', `FemaleText_loc4`='我要把你切得粉碎，送还给巫妖王！', `FemaleText_loc5`='我要把你撕成碎片送回給巫妖王!', `FemaleText_loc7`='¡Te voy a enviar de vuelta con el Rey Exánime hecho trocitos!' WHERE `ID`=29159;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곧 교수대에 매달릴 거다, 스컬지 괴물 녀석!', `MaleText_loc4`='你很快就要被押上绞刑架了，魔鬼！', `MaleText_loc5`='你等著被掛上絞刑台吧，天譴魔鬼!', `MaleText_loc7`='¡Pronto estarás colgado en la horca, demonio de la Plaga!', `FemaleText_loc1`='곧 교수대에 매달릴 거다, 스컬지 괴물 녀석!', `FemaleText_loc4`='你很快就要被押上绞刑架了，魔鬼！', `FemaleText_loc5`='你等著被掛上絞刑台吧，天譴魔鬼!', `FemaleText_loc7`='¡Pronto estarás colgado en la horca, demonio de la Plaga!' WHERE `ID`=29160;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 종교재판장 이실리엔 님을 위해 일해왔다! 매일 오후면 고통을 즐겼지!', `MaleText_loc4`='我曾是大检察官伊森利恩的部下！你的鞭刑就像午后茶点一般！', `MaleText_loc5`='我曾效命於大審判官伊森利恩手下!你折磨人的手段對我來說不過就是小菜一碟!', `MaleText_loc7`='¡Yo solía trabajar para el Gran Inquisidor Isillien! ¡Tu concepto del dolor es una tarde cualquiera para mí!', `FemaleText_loc1`='난 종교재판장 이실리엔 님을 위해 일해왔다! 매일 오후면 고통을 즐겼지!', `FemaleText_loc4`='我曾是大检察官伊森利恩的部下！你的鞭刑就像午后茶点一般！', `FemaleText_loc5`='我曾效命於大審判官伊森利恩手下!你折磨人的手段對我來說不過就是小菜一碟!', `FemaleText_loc7`='¡Yo solía trabajar para el Gran Inquisidor Isillien! ¡Tu concepto del dolor es una tarde cualquiera para mí!' WHERE `ID`=29161;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아악! 마지막 남은 내 질 좋은 휘장을 태우다니!', `MaleText_loc4`='啊！你烧坏了我的战袍！那是我唯一保存完好的战袍！', `MaleText_loc5`='啊!你燒了我最後一個完好的外袍!', `MaleText_loc7`='¡ARGH! ¡Acabas de quemar el último tabardo bueno que me quedaba!', `FemaleText_loc1`='아악! 마지막 남은 내 질 좋은 휘장을 태우다니!', `FemaleText_loc4`='啊！你烧坏了我的战袍！那是我唯一保存完好的战袍！', `FemaleText_loc5`='啊!你燒了我最後一個完好的外袍!', `FemaleText_loc7`='¡ARGH! ¡Acabas de quemar el último tabardo bueno que me quedaba!' WHERE `ID`=29162;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헛소리! 네가 앞으로 느낄 고통은 몇 년 동안 얘깃거리가 될 게다!', `MaleText_loc4`='撒谎！接下来你要承受的痛苦足够你谈论好几年！', `MaleText_loc5`='滿口謊話!你即將要承受的痛苦，會讓你許多年也無法忘卻!', `MaleText_loc7`='¡MENTIRAS! ¡Se hablará durante años del dolor que estás a punto de experimentar!', `FemaleText_loc1`='헛소리! 네가 앞으로 느낄 고통은 몇 년 동안 얘깃거리가 될 게다!', `FemaleText_loc4`='撒谎！接下来你要承受的痛苦足够你谈论好几年！', `FemaleText_loc5`='滿口謊話!你即將要承受的痛苦，會讓你許多年也無法忘卻!', `FemaleText_loc7`='¡MENTIRAS! ¡Se hablará durante años del dolor que estás a punto de experimentar!' WHERE `ID`=29163;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벌벌 떨어라, 이교도 녀석들아! 붉은십자군 군주가 전투에 뛰어들었다!', `MaleText_loc4`='颤抖吧，异教徒！一名十字军领主加入了战斗！', `MaleText_loc5`='畏縮吧，異教徒，血色領主加入戰局了!', `MaleText_loc7`='¡Acobardaos, pecadores, pues el Señor Escarlata se ha unido a la batalla!' WHERE `ID`=29164;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신 아발론은 정화될 것이다! 스컬지는 모두 끝장나리라!', `MaleText_loc4`='净化新阿瓦隆！铲除天灾军团！', `MaleText_loc5`='新亞法隆就要被淨化!所有的天譴軍都要被斬草除根!', `MaleText_loc7`='¡Purgaremos Nuevo Avalon! ¡Erradicaremos a toda la Plaga!' WHERE `ID`=29165;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='십자군이라...$B$B<고개를 젓는 리븐데어>$B$B녀석들은 확실히 인간 중에서도 독특한 놈들이지. 내 생각엔 녀석들의 뇌는 상황을 논리적으로 파악하고 결과를 낸다는 고등한 기능은 수행하지 못하는 것 같다. 빛을 들먹거리기만 하면 녀석들은 잔뜩 바람이 들어서 전투 준비를 하지. 그러고는 자신의 안위는 완전히 무시하고 망설임도 없이 전투에 뛰어든단 말이야.', `MaleText_loc4`='十字军……$B$B<瑞文戴尔男爵摇了摇头。>$B$B他们是一群特殊的人类。在我看来，十字军似乎不具备高等智慧，他们无法理智地评估局势并计算得失。只要提到圣光，就能让他们群情激昂——接着，这帮家伙会完全无视自己的利益，盲目地投身战斗。', `MaleText_loc5`='十字軍...$b$b<瑞文戴爾搖搖頭。>$B$B我相信他們是某個特別的人種。我的推論是他們的大腦無法進行較高級的運作，無法理性地思考情勢並且計算出結果。只要有人提到聖光就能讓他們口吐白沫並且準備好戰鬥 - 但同時他們也也能毫不在意自己性命第一頭衝進任何戰鬥。', `MaleText_loc7`='Cruzados...$B$B<Osahendido agita la cabeza.>$B$BEstoy convencido de que son un grupo único entre los humanos. Mi teoría es que no poseen las funciones cerebrales superiores, por lo que no pueden sopesar una situación y calcular un resultado de forma lógica. Uno solo tiene que mencionar la Luz para conseguir que echen espumarajos y se preparen para la batalla. Llegados a ese punto, irán de cabeza hacia su compromiso sin preocupación alguna por su propio bienestar.' WHERE `ID`=29166;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이리 오세요, 시간 여행자여. 할 이야기가 있어요!', `FemaleText_loc4`='时间的旅者，过来。我有话和你说！', `FemaleText_loc5`='快來這，時空旅人，我們得談談!', `FemaleText_loc7`='Ven aquí, viajero del tiempo, ¡tenemos que hablar!' WHERE `ID`=29167;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다시 만났군요, 시간 여행자여!', `FemaleText_loc4`='我们又见面了，时间的旅者！', `FemaleText_loc5`='又見面了，時空旅人!', `FemaleText_loc7`='¡Volvemos a encontrarnos, viajero del tiempo!' WHERE `ID`=29168;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어서요! 이리 오세요!', `FemaleText_loc4`='快过来吧！', `FemaleText_loc5`='快，在這!', `FemaleText_loc7`='¡Deprisa, aquí!' WHERE `ID`=29169;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자랑스러워하셔도 좋습니다. 주인님께서 작전을 공개하시는 건 당신이 처음이니까요.', `MaleText_loc4`='你应该感到荣幸。主人要我们向你展示沃尔塔鲁斯的工事，这还是头一遭。', `MaleText_loc5`='你要感到榮幸。你是主人的候選人中第一位被允許瞭解計畫的。', `MaleText_loc7`='Deberías sentirte honrado. Eres el primer posible candidato del maestro al que mostramos nuestra operación.' WHERE `ID`=29171;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신께서 드락타론에 오신 이래, 주인님께서는 언젠가는 당신이 여기 올라와 주인님과 함께할 거라고 종종 말씀하셨죠.', `MaleText_loc4`='主人从达克萨隆来到这里时，就预言了你到此造访的时间。', `MaleText_loc5`='自從他抵達德拉克薩隆之後，主人開始提到你加入他的時間。', `MaleText_loc7`='Desde que llegó de Drak''Tharon, el maestro ha estado hablando del momento en el que te unirías a él aquí.' WHERE `ID`=29172;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 제가 보여 드리는 것을 볼타루스 밖에서는 절대로 발설해선 안 됩니다. 머지않아 온 세상이 우리 비밀을 알게 될 겁니다!', `MaleText_loc4`='我向你展示的东西绝对不能在沃尔塔鲁斯以外提起。我们的秘密很快就能揭晓了！', `MaleText_loc5`='現在我要給你看的，是不能在沃塔魯斯外談論的東西。這世界很快就會知道我們的秘密了!', `MaleText_loc7`='Las cosas que te enseño no deben ser comentadas fuera de Voltarus. ¡El mundo conocerá nuestro secreto muy pronto!' WHERE `ID`=29173;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='역병 결정이 여기 저장되어 있습니다. 이 결정 덕에 작전을 진행할 수 있었지요.', `MaleText_loc4`='这些是我们储藏的荒芜水晶。没有水晶，我们的计划就不可能成功。', `MaleText_loc5`='這是我們儲存的荒疫水晶，要是沒有這些我們的計畫一定不可能完成。', `MaleText_loc7`='Aquí se encuentran nuestras reservas de cristales de añublo... sin las cuales nuestro proyecto sería imposible.' WHERE `ID`=29174;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신께서 힘써주신 덕에 수정을 이만큼 비축할 수 있었다는 걸 압니다.', `MaleText_loc4`='我知道，你会为我们做好了充足的储备而感到庆幸。', `MaleText_loc5`='我知道你是要感謝我們那些補給品。', `MaleText_loc7`='Tengo entendido que a ti es a quien hay que agradecer el volumen de nuestras provisiones.' WHERE `ID`=29175;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신께서 전장에 모습을 드러내게 했던 트롤 족장들도 이 중에 있습니다. 실로 대가의 솜씨를 보여주셨죠...', `MaleText_loc4`='这些是你在战场上俘虏的巨魔。你的身手确实不错……', `MaleText_loc5`='這些食人妖就是你在戰場上發掘出來的。真的幹得非常漂亮...', `MaleText_loc7`='Estos trols son algunos de los que hiciste salir en el campo de batalla. Una obra maestra, sin duda...' WHERE `ID`=29176;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 풀려났다, 조그만 드라카리 녀석들아. 이제 너희가 저지른 수많은 불경에 대한 대가를 치를 때다!', `MaleText_loc4`='我自由了，达卡莱巨魔。为你们的罪行付出代价吧！', `MaleText_loc5`='小小德拉克瑞，我自由了，為你的不請自來付出代價吧!', `MaleText_loc7`='SOY LIBRE, PEQUEÑO DRAKKARI. ¡HORA DE PAGAR TUS MÚLTIPLES ALLANAMIENTOS!' WHERE `ID`=29177;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 위쪽이오, $n. 미행을 당한 건 아니겠지요?', `MaleText_loc4`='我在这儿，$n。你没被跟踪吧？', `MaleText_loc5`='嘿，$n，在上面，你沒有被跟蹤，對吧?', `MaleText_loc7`='Aquí arriba, $n. No te han seguido, ¿verdad?' WHERE `ID`=29178;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만!', `MaleText_loc4`='够了！', `MaleText_loc5`='夠了!', `MaleText_loc7`='¡BASTA!' WHERE `ID`=29179;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아칼리, 이제 주인님께 네 피를 바치고 네 힘은 내가 취하리라!', `MaleText_loc4`='阿卡里，我的主人需要你的鲜血，我也要夺取你的一部分力量！', `MaleText_loc5`='那麼現在，阿卡利，我的主人將擁有你的血液，而我也會拿走你的一些力量!', `MaleText_loc7`='¡Y ahora, Akali, mi maestro, se quedará con tu sangre y yo me apoderaré de parte de tu poder!' WHERE `ID`=29180;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n! 자네가 돌아오길 기다렸다네. 왜 이렇게 오래 걸렸나, 친구?$b$b역병피 트롤 군대가 완성될 때가 왔네.$b$b이제 나와 함께 가서 우리 군대의 탄생을 지켜보자고!', `MaleText_loc4`='$n！我一直在等你。你怎么去了那么久？$b$b我们可以对荒芜之血进行转换了。$b$b让我们共同见证军队的诞生吧！', `MaleText_loc5`='$n!我正等著你回來。怎麼花了那麼久的時間，老兄?$b$b該結束和荒疫之血食人妖聊天時間了。$b$b加入我，一同目睹我們大軍的成立!', `MaleText_loc7`='¡$n! He estado esperando tu vuelta. ¿Qué te ha retenido tanto tiempo, tron?$b$bEs hora de completar la conversión de los Sangreañublo.$b$b¡Únete a mí y contempla la creación de nuestro ejército!' WHERE `ID`=29181;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='함께 갈 준비가 되었습니다, 드라쿠루.', `MaleText_loc4`='我准备好了，达库鲁。', `MaleText_loc5`='我準備好加入你了，德拉庫魯。', `MaleText_loc7`='Estoy listo para acompañarte, Drakuru.', `FemaleText_loc1`='함께 갈 준비가 되었습니다, 드라쿠루.', `FemaleText_loc4`='我准备好了，达库鲁。', `FemaleText_loc5`='我準備好加入你了，德拉庫魯。', `FemaleText_loc7`='Estoy lista para acompañarte, Drakuru.' WHERE `ID`=29182;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 끝났다. 네 주인에게 돌아가라. 하르코아에게 돌아가란 말이다. 내가 찾아간다고 전해라!', `MaleText_loc4`='好了。滚回你的主人身边吧。告诉哈克娅，我来了！', `MaleText_loc5`='事情結束了。逃回你的主人身邊吧。逃回哈寇亞，告訴她，我來了!', `MaleText_loc7`='Ya está. Regresa junto a tus maestros. Vuelve junto a Har''koa. ¡Dile que voy!' WHERE `ID`=29183;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배 너무 고파...', `MaleText_loc4`='好饿……', `MaleText_loc5`='真餓...', `MaleText_loc7`='Tan hambriento...' WHERE `ID`=29184;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밥 줘...', `MaleText_loc4`='我要吃东西……', `MaleText_loc5`='得餵我了...', `MaleText_loc7`='Deber alimentar...' WHERE `ID`=29185;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그걸 달란 말이다!', `MaleText_loc4`='我饿啊！！！', `MaleText_loc5`='給我腦子!', `MaleText_loc7`='¡DAME CEREBROS!' WHERE `ID`=29186;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신선한 고기 냄새... 가까워...', `MaleText_loc4`='肉的味道……就在附近……', `MaleText_loc5`='聞到肉味...很接近...', `MaleText_loc7`='Huelo carne... Cerca...' WHERE `ID`=29187;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벌목기 조작 장치를 어디 놔뒀는지 모르겠습니다... 하나 더 받을 수 있을까요?', `MaleText_loc4`='我好像弄丢了你的伐木机控制器……还有吗？', `MaleText_loc5`='我弄丟了你的伐木機控制裝置...也許你還有一個?', `MaleText_loc7`='Creo que he perdido tu dispositivo de control de la trituradora... ¿No tendrás otro?', `FemaleText_loc1`='벌목기 조작 장치를 어디 놔뒀는지 모르겠어요... 하나 더 받을 수 있을까요?', `FemaleText_loc4`='我好像弄丢了你的伐木机控制器……还有吗？', `FemaleText_loc5`='我弄丟了你的伐木機控制裝置...也許你還有一個?', `FemaleText_loc7`='Creo que he perdido tu dispositivo de control de la trituradora... ¿No tendrás otro?' WHERE `ID`=29188;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 그런 녀석에게 신경을 쓰나, 타사리안?', `MaleText_loc4`='萨萨里安，你为什么这么在意？', `MaleText_loc5`='為什麼你會在意，薩沙理安?', `MaleText_loc7`='¿Y a ti qué te importa, Thassarian?' WHERE `ID`=29189;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='약했으니 잡힌 걸세.', `MaleText_loc4`='他过于孱弱，所以被俘虏了。', `MaleText_loc5`='他的軟弱讓他被抓。', `MaleText_loc7`='Su debilidad condujo a su captura.' WHERE `ID`=29190;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강한 자만이 살아남지. 말할 필요도 없지만...', `MaleText_loc4`='唯有强者才能生存。更别说是……', `MaleText_loc5`='唯有強者才得以生存。更別提...', `MaleText_loc7`='Solo los fuertes deberían sobrevivir. Por no mencionar...' WHERE `ID`=29191;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐라고, 오르바즈? 그가 블러드 엘프여서 그런 소리를 하는 건가?', `MaleText_loc4`='更别说什么，奥尔巴兹？就因为他是血精灵？', `MaleText_loc5`='什麼，歐貝茲?他是個血精靈?', `MaleText_loc7`='¿Qué, Orbaz? ¿Que él es un elfo de sangre?' WHERE `ID`=29192;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생전에 그는 내가 증오해 마지않는 적이었지. 사실이야...', `MaleText_loc4`='活着的时候，我们是不共戴天的仇敌……', `MaleText_loc5`='活著的時候，我們是仇敵 - 這倒是真的...', `MaleText_loc7`='En vida éramos enemigos; es cierto...' WHERE `ID`=29193;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 죽은 후에는... 우리는 저주받은 자의 자식이 되었네. 스컬지의 버림받은 아들딸 말일세.', `MaleText_loc4`='但在死后……诅咒的种子在我们心中扎根，我们都沦为了天灾军团的孤儿。', `MaleText_loc5`='但死後...我們都是被詛咒的子民，天譴軍團的孤兒。', `MaleText_loc7`='Pero en la muerte... somos los hijos de los malditos. Los hijos e hijas huérfanos de la Plaga.' WHERE `ID`=29194;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽어서는, 우리 모두 형제일세.', `MaleText_loc4`='死后我们成为了兄弟。', `MaleText_loc5`='死後我們都是兄弟。', `MaleText_loc7`='En la muerte somos hermanos.' WHERE `ID`=29195;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='집어치워, 타사리안.', `MaleText_loc4`='见鬼去吧，萨萨里安。', `MaleText_loc5`='你下地獄去吧，薩沙理安。', `MaleText_loc7`='Vete al infierno, Thassarian.' WHERE `ID`=29196;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='망할 붉은십자군 녀석들! 난 갈비뼈가 부러져 내상을 입은 것 같습니다.', `MaleText_loc4`='该死的十字军！我的肋骨折断了，似乎有内出血的症状。', `MaleText_loc5`='該死的十字軍!我想我的肋骨大概斷了，大概還有內出血吧。', `MaleText_loc7`='¡Maldita sea la Cruzada! Creo que tengo las costillas rotas y puede que hemorragia interna.' WHERE `ID`=29197;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 찾고 계십니까?', `MaleText_loc4`='你在找什么？', `MaleText_loc5`='你在看哪裡?', `MaleText_loc7`='¿Qué estás mirando?' WHERE `ID`=29198;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 좀 마시려던 참인데요.', `MaleText_loc4`='我只想好好地喝一杯。', `MaleText_loc5`='我只是想要好好喝一杯。', `MaleText_loc7`='Solo intento disfrutar de mi bebida.' WHERE `ID`=29199;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무엇을 원하십니까?', `MaleText_loc4`='你想干什么？', `MaleText_loc5`='你要什麼?', `MaleText_loc7`='¿Qué quieres?' WHERE `ID`=29200;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 룬검과 방어구를 찾아야 합니다... 잠깐만 기다리십시오.', `MaleText_loc4`='我要找回符文剑和盔甲……很快就好。', `MaleText_loc5`='我要拿回我的符文刃和護甲...還要一點時間。', `MaleText_loc7`='Tengo que coger mi hojarruna y mi armadura... Solo necesito un poco más de tiempo.' WHERE `ID`=29201;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수행사제여, 저들을 구속하라! 심문할 준비를 해라!', `MaleText_loc4`='侍僧，将他们锁起来！准备审讯！', `MaleText_loc5`='侍僧們，把他們拴起來!準備對他們進行質問!', `MaleText_loc7`='¡Acólitos, encadenadlos a todos! ¡Preparadlos para el interrogatorio!' WHERE `ID`=29202;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 아직 약하지만, 아마도 대마법 보호막 정도는 만들 수 있을 것 같습니다. 보호막을 벗어나면 저들의 주문에 크게 당할 테니 조심하십시오.', `MaleText_loc4`='我很虚弱，但是我应该能撑起一个反魔法屏障。你最好别走出屏障，否则就会被他们的法术杀死。', `MaleText_loc5`='我仍然很虛弱，但我想我可以維持反魔法屏障。躲在裡頭，要不你會被他們的法術殺死的。', `MaleText_loc7`='Aún estoy débil, pero creo que puedo levantar una barrera antimagia. Quédate en su interior o sus hechizos te destruirán.' WHERE `ID`=29203;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='심하게 부상을 당했지만, 나도 할 수 있는 데까지 해보겠습니다. 대마법 보호막 안에 있으십시오. 안 그러면 저 수행사제들의 마법이 그대를 갈가리 찢고 말 테니까요.', `MaleText_loc4`='我伤得很重，但是我会尽量帮忙的。你最好待在我撑起的反魔法屏障中，否则侍僧的魔法会将你撕成碎片。', `MaleText_loc5`='我傷得不輕，但我會盡一切力量幫忙。試著躲在我的反魔法屏障裡面，否則這些侍僧的魔法會把你撕裂的。', `MaleText_loc7`='Estoy malherido, pero haré lo que pueda para ayudar. Intenta mantenerte dentro de mi barrera antimagia o la magia de los acólitos te destruirá.' WHERE `ID`=29204;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 보호막을 유지하는 것만 해도 엄청난 집중력이 필요합니다. 저들을 해치우십시오!', `MaleText_loc4`='我必须集中精神维持这个屏障。去消灭他们！', `MaleText_loc5`='維持屏障需要我全神貫注。殺光他們!', `MaleText_loc7`='Mantener esta barrerá requerirá toda mi concentración. ¡Mátalos a todos!' WHERE `ID`=29205;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어정어정 뭐 하는 거야? 가서 일해!', `MaleText_loc4`='你瞎转悠什么呢，快回去工作！', `MaleText_loc5`='你還杵在這幹嘛，回去工作!', `MaleText_loc7`='¡A qué esperas, vuelve al trabajo!' WHERE `ID`=29206;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 세게 공격해올 겁니다. 자신을 지키십시오! 대마법 보호막을 벗어나지 마십시오! 보호막의 도움을 받지 못하면 저들이 그대를 조각낼 겁니다!', `MaleText_loc4`='敌人再次发动了攻击。注意安全！别离开反魔法区域！没有屏障的保护，他们轻易就能将你撕成碎片！', `MaleText_loc5`='他們前仆後繼，保護你自己!別跑出反魔法力場之外!沒有它的保護你會被撕成碎片的!', `MaleText_loc7`='Vienen más. ¡Defiéndete! ¡No te salgas del campo antimagia! ¡Sin su protección, te destrozarán!' WHERE `ID`=29207;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더는 보호막을 유지할 수 없을 것 같습니다... 그 겁쟁이는 어디 갔습니까?', `MaleText_loc4`='屏障支撑不了多久了……那个胆小鬼在哪儿呢？', `MaleText_loc5`='我沒辦法維持這屏障多久...那個懦夫在哪裡?', `MaleText_loc7`='No podré mantener esta barrera mucho más... ¿Dónde está ese cobarde?' WHERE `ID`=29208;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 도와드릴까요, $r님?', `MaleText_loc4`='我能帮你什么忙吗，$r？', `MaleText_loc5`='我能為你效勞嗎，$r?', `MaleText_loc7`='¿Qué puedo hacer por ti, $r?' WHERE `ID`=29209;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='종교재판관이군! 준비하십시오, 죽음의 기사여! 녀석이 그대를 대마법 보호막 밖으로 끌어내게 두지 마십시오! 그를 처치하세요!', `MaleText_loc4`='大检察官来了！准备迎战，死亡骑士！别离开反魔法屏障的安全区域！击败他，拿到他的徽记！', `MaleText_loc5`='高階審判官來了!隨時就緒，死亡騎士!不要任憑他把你從我的反魔法力場的防護範圍內拖走!殺掉他，並拿下他的頭顱!', `MaleText_loc7`='¡Viene el Alto Inquisidor! ¡Prepárate, caballero de la Muerte! ¡No dejes que te saque de los límites protectores de mi campo antimagia! ¡Mátalo y coge su cabeza!' WHERE `ID`=29210;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알았어, 알았다고! 그렇게 때릴 것까진 없잖아!', `MaleText_loc4`='知道了！别打我！', `MaleText_loc5`='好啦好啦!那也用不著打我啊!', `MaleText_loc7`='¡Vale, vale! ¡No hacía falta que me pegaras!', `FemaleText_loc1`='알았어요, 알았다고요! 그렇게 때릴 것까진 없잖아요!', `FemaleText_loc4`='知道了！别打我！', `FemaleText_loc5`='好啦好啦!那也用不著打我啊!', `FemaleText_loc7`='¡Vale, vale! ¡No hacía falta que me pegaras!' WHERE `ID`=29211;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수중 호흡 마법을 걸어 주십시오, 가렌.', `MaleText_loc4`='我需要水下呼吸效果，盖伦。', `MaleText_loc5`='我需要水下呼吸，加倫。', `MaleText_loc7`='Necesito respiración acuática, Garren.', `FemaleText_loc1`='수중 호흡 마법을 걸어 주세요, 가렌.', `FemaleText_loc4`='我需要水下呼吸效果，盖伦。', `FemaleText_loc5`='我需要水下呼吸，加倫。', `FemaleText_loc7`='Necesito respiración acuática, Garren.' WHERE `ID`=29212;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하, 멍청한 오우거 녀석. 내가 일하러 갈 줄 알고?', `MaleText_loc4`='嘿嘿，食人魔笨蛋。你以为我会乖乖地回去工作吗？', `MaleText_loc5`='嘿嘿，笨巨魔。最好是我會回去工作。', `MaleText_loc7`='Je, je, estúpido ogro. Como que voy a volver a trabajar.', `FemaleText_loc1`='하하, 멍청한 오우거 녀석. 내가 일하러 갈 줄 알고?', `FemaleText_loc4`='嘿嘿，食人魔笨蛋。你以为我会乖乖地回去工作吗？', `FemaleText_loc5`='嘿嘿，笨巨魔。最好是我會回去工作。', `FemaleText_loc7`='Je, je, estúpido ogro. Como que voy a volver a trabajar.' WHERE `ID`=29213;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구역질 나는 스컬지 같으니! 빛의 정화를 받아라!', `MaleText_loc4`='肮脏的天灾兵！接受圣光的净化吧！', `MaleText_loc5`='天譴雜碎!以聖光之名淨化你們!', `MaleText_loc7`='¡Escoria de la Plaga! ¡Que la Luz te purifique!' WHERE `ID`=29214;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='붉은십자군이 너희를 정화해 이 세상에서 몰아내리라!', `MaleText_loc4`='十字军会从这个世界上抹去你们的存在！', `MaleText_loc5`='十字軍將會把你們族類從這世界中淨化!', `MaleText_loc7`='¡La Cruzada purgará a los de tu calaña de este mundo!' WHERE `ID`=29215;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 직접 너희를 상대해야겠구나. 스컬지여, 종교재판관의 무서움을 느껴 보아라!', `MaleText_loc4`='看样子我得亲自对付你了。尝尝大检查官的厉害吧，天灾军团！', `MaleText_loc5`='看來，我得親自對付你。高階審判官來會會你，天譴軍!', `MaleText_loc7`='Parece que tendré que encargarme de ti yo mismo. ¡El Alto Inquisidor viene a por ti, miembro de la Plaga!' WHERE `ID`=29216;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수정구 깊숙한 곳에서 희미한 빛이 흘러나오고, 푸른 안개가 표면을 휘돕니다.', `MaleText_loc4`='宝珠中散发出一道微弱的光芒，表面笼罩着一层蓝色的雾气。', `MaleText_loc5`='寶珠的深處散射出昏暗的光芒，一陣藍色的霧氣在寶珠的表面環繞著。', `MaleText_loc7`='Una pálida luz emana de las profundidades del orbe y una niebla azul se arremolina alrededor de su superficie.' WHERE `ID`=29217;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어두운 스컬지의 마법 따위가 빛을 막을 수 있을 것 같으냐!', `MaleText_loc4`='别以为天灾军团的黑暗魔法能让你们免受圣光的惩罚！', `MaleText_loc5`='你的天譴軍黑暗魔法不會防護你免於聖光的淨化!', `MaleText_loc7`='¡Tu oscura magia de la Plaga no te protegerá de la Luz!' WHERE `ID`=29218;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겁쟁이 녀석!', `MaleText_loc4`='懦夫！', `MaleText_loc5`='懦夫!', `MaleText_loc7`='¡Cobarde!' WHERE `ID`=29219;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이리 와서 재주를 부려 봐라.', `MaleText_loc4`='出来玩玩吧。', `MaleText_loc5`='出來享點樂子吧。', `MaleText_loc7`='Sal a jugar.' WHERE `ID`=29220;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛이 너를 정화하리라!', `MaleText_loc4`='接受圣光的净化吧！', `MaleText_loc5`='讓聖光淨化你!', `MaleText_loc7`='¡QUE LA LUZ TE PURGUE!' WHERE `ID`=29221;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동료를 해방하러 왔나? 난 너희를 해방하러 왔다!', `MaleText_loc4`='你想要寻求救赎？我就是你的救星！', `MaleText_loc5`='你需要解救嗎?我來解救你!', `MaleText_loc7`='¿Vienes buscando la liberación? ¡Yo he venido aquí a liberar!' WHERE `ID`=29222;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 땅바닥에 쓰러집니다.', `MaleText_loc4`='%s的尸体跌落在地。', `MaleText_loc5`='%s的殘骸散落一地。', `MaleText_loc7`='Los restos de %s caen al suelo.' WHERE `ID`=29223;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자리를 잘 잡으십시오! 내 대마법 보호막으로 저들의 주문에서 자신을 방어하십시오!', `MaleText_loc4`='坚守阵地！利用反魔法屏障抵挡他们的法术！', `MaleText_loc5`='堅守陣地!利用我的反魔法屏障抑制他們的法術!', `MaleText_loc7`='¡No cedas! ¡Usa mi barrera antimagia para atenuar sus hechizos!' WHERE `ID`=29224;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대마법 보호막 안에 머무르십시오! 저들이 그대에게 다가오게 하십시오!', `MaleText_loc4`='别离开反魔法屏障！将他们引过来！', `MaleText_loc5`='待在反魔法力場裡!讓他們迎向你!', `MaleText_loc7`='¡Mantente dentro del campo antimagia! ¡Haz que vayan a por ti!' WHERE `ID`=29225;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음의 손아귀를 사용하세요, 죽음의 기사여! 그대의 능력 말입니다! 저들을 안으로 끌어들이십시오!', `MaleText_loc4`='死亡骑士，快用死亡之握！将他们拖进来！', `MaleText_loc5`='死亡之握!快用你的能力，死亡騎士!把他們拉進來!', `MaleText_loc7`='¡Atracción letal! ¡Usa tus poderes, caballero de la Muerte! ¡Atráelos!' WHERE `ID`=29226;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꺾이지 마십시오, 죽음의 기사여! 집중하십시오!', `MaleText_loc4`='别和他们打持久战！集中注意力！', `MaleText_loc5`='不要讓他們打倒你!集中注意!', `MaleText_loc7`='¡No dejes que te agoten! ¡Céntrate!' WHERE `ID`=29227;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나라고 이 망할 대마법 보호막을 영원히 유지할 수 있는 게 아닙니다. 서두르십시오!', `MaleText_loc4`='我不可能一直维持反魔法屏障。动作快点，消灭他们！', `MaleText_loc5`='我沒辦法永遠維持這個該死的屏障啊。殺快點!', `MaleText_loc7`='No puedo mantener esta barrera eternamente. ¡Mata más rápido!' WHERE `ID`=29228;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='초라하게 패배를 맞겠군요...', `MaleText_loc4`='一旦战败，圣光将因此蒙羞。', `MaleText_loc5`='這會是個丟臉的失敗。', `MaleText_loc7`='Esta va a ser una derrota humilladora.' WHERE `ID`=29229;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 땅바닥에 쓰러집니다.', `MaleText_loc4`='%s瘫倒在地。', `MaleText_loc5`='%s倒在地上。', `MaleText_loc7`='%s se cae al el suelo.' WHERE `ID`=29230;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너는 이제 틀렸다, 죽음의 기사여!', `MaleText_loc4`='你完蛋了，死亡骑士！', `MaleText_loc5`='你死定了，死亡騎士!', `MaleText_loc7`='¡Estás acabado, caballero de la Muerte!' WHERE `ID`=29231;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라푸가 진흙을 뒤져 벌레를 몇 마리 파냅니다.', `MaleText_loc4`='拉弗乌从土堆里挖出几只虫子。', `MaleText_loc5`='拉富從土壤中挖出許多蟲子。', `MaleText_loc7`='Lafoo desentierra algunos bichos de entre la suciedad.' WHERE `ID`=29232;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 번 더 우리가 네 부름에 응해 주겠다, 쿠푸. 너와 $n|1이;가; 소망하는 지혜가 우리에게 있지. 너희는 큰 위험에 처했고 빨리 행동을 취해야 한다. 그렇지 않으면 너희 모두 하르코아와 함께 죽으리라.', `MaleText_loc4`='库弗，我们再次听到你的召唤。请允许我们给你和$n几句忠告。你们即将面临巨大的威胁，如果不赶紧行动的话，你们和哈克娅都会丧命。', `MaleText_loc5`='庫弗，我們再度聽見了你的呼喚，我們將分享智慧給你和$n。你們面對了深沉的苦難，如果不迅速反應的話，你們所有的人，以及哈寇亞都將死於非命。', `MaleText_loc7`='Escuchamos tu llamada una vez más, Khufu. Tenemos sabiduría para compartir contigo y con $n. Te enfrentas a un gran peligro y deben actuar con presteza o moriran ustedes y Har''koa.' WHERE `ID`=29233;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수호자의 흠집 없는 심장을 얻어 도전 정신과 힘을 보여라. 질투심 많은 짐루크가 거느리는 자들이 그것을 숨기고 있다.', `MaleText_loc4`='唯有完美的守卫者徽记能传达挑衅的意图。拥有这颗徽记的守卫者就在戒备森严的希姆鲁克。', `MaleText_loc5`='無瑕疵的守護者之心一定要被拯救，才能展現反抗與力量。嫉妒的辛茹克私藏這些握有它的人。', `MaleText_loc7`='El inmaculado corazón del guardián ha de ser protegido para mostrar resistencia y fuerza. El celoso Zim''Rhuk retiene a aquellos que lo esconden.' WHERE `ID`=29234;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='망자 쿠에츠룬의 감시자가 지닌 돌풍 정수를 얻어야 예언자를 이 세계로 끌어당길 수 있으리라. 이 두 가지 희귀한 물건을 하르코아에게 가져다주어라.', `MaleText_loc4`='只有杀死奎丝鲁恩祭坛典狱官，获得充满活力的典狱官精华，才能引出阿卡里先知。你必须将这两件稀罕物交给哈克娅。', `MaleText_loc5`='一定要收集陣亡的奎茲倫守望者陣風精華，才能接近他。一定要把這兩件珍貴的東西送到哈寇亞才行。', `MaleText_loc7`='La ventosa esencia de los fallecidos celadores de Quetz''lun ha de ser recogida para atraerlo. Ambas rarezas han de ser llevadas a Har''koa.' WHERE `ID`=29235;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여전히 우리는 네 미래가 어둡다고 본다. 그러나 이 임무는 네 운명이다, $n. 예언자가 너무 강력해 너와 네 동료가 이겨낼 수 없을지도 모른다. 그래도, 너는 이 일을 해야 한다.', `MaleText_loc4`='未来仍然笼罩着阴霾。$n，这是你的命运。虽然你和你的伙伴或许不是先知的对手，但是，你必须尝试。', `MaleText_loc5`='到目前為止，你的未來我只看見了厄運。你的命運就是要完成這件事，$n，但是我們擔心預言對你和你的朋友來說太強大了。可是，你必須嘗試。', `MaleText_loc7`='Y aun así, solo vemos perdición en tu futuro. Tu destino es hacer esto, $n, pero tememos que el profeta sea demasiado fuerte para ti y tus amigos. A pesar de ello, has de intentarlo.' WHERE `ID`=29236;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안 돼! 아칼리마저!', `FemaleText_loc4`='不，也不是哈克娅！', `FemaleText_loc5`='不，不要連阿卡利也是!', `FemaleText_loc7`='¡No, Akali también no!' WHERE `ID`=29237;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하르코아가 의술사가 있는 방향을 쳐다보며 생각에 잠깁니다.', `FemaleText_loc4`='若有所思地向巫医所在的方向看去。', `FemaleText_loc5`='朝巫醫的方向仔細檢查並陷入長考。', `FemaleText_loc7`='Mira en la dirección del médico brujo de forma pensativa.' WHERE `ID`=29238;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신 아발론 종교재판관의 죽음은 얼마 안 있어 알려질 겁니다. 당장 여길 떠나십시오! 놈들이 더 몰려오기 전에 어서 가십시오. 난 혼자서 빠져나갈 수 있습니다.', `MaleText_loc4`='新阿瓦隆大检查官的死亡必然会引起敌人的注意。你最好立刻离开！快跑吧，趁敌人还没有涌上来。我会照顾好自己的。', `MaleText_loc5`='新亞法隆的高階審判官之死不會無聲無息。你得馬上離開這裡!快走，不要等到他們的人出現。我自己一個人會很好的。', `MaleText_loc7`='La muerte del Alto Inquisidor de Nuevo Avalon no pasará desapercibida. ¡Tienes que salir de aquí inmediatamente! Vete antes de que aparezcan más. Yo me las apañaré solo.' WHERE `ID`=29239;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 저들의 눈길을 끌겠습니다. 내가 나간 후에 빠져나가십시오.', `MaleText_loc4`='我来吸引火力，掩护你逃走。', `MaleText_loc5`='我會吸引他們的攻擊，你躲在我後面逃走。', `MaleText_loc7`='Yo atraeré su fuego, tú escapa detrás de mí.' WHERE `ID`=29240;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 종교재판관은 아무것도 아니다. 붉은십자군 녀석들아! 아무도 스컬지의 손아귀를 벗어날 수 없다!', `MaleText_loc4`='十字军，你们的大检查官已经死了！没有人能逃出天灾军团的控制！', `MaleText_loc5`='十字軍，你們的高階審判官不過就是一塊肉!天譴軍的魔爪之下將什麼都不剩!', `MaleText_loc7`='¡Su Alto Inquisidor no es más que un montón de carne, cruzados! ¡Nadie está al margen del abrazo de la Plaga!' WHERE `ID`=29241;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<신음하는 콜티라>', `MaleText_loc4`='<库尔迪拉呻吟着。>', `MaleText_loc5`='<寇爾提拉呻吟著。>', `MaleText_loc7`='<Koltira gruñe.>' WHERE `ID`=29242;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='콜티라, 어서 여기서 나갑시다!', `MaleText_loc4`='库尔迪拉，我们快离开这儿！', `MaleText_loc5`='寇爾提拉，我們快逃出去!', `MaleText_loc7`='¡Koltira, salgamos de aquí!', `FemaleText_loc1`='콜티라, 어서 여기서 나갑시다!', `FemaleText_loc4`='库尔迪拉，我们快离开这儿！', `FemaleText_loc5`='寇爾提拉，我們快逃出去!', `FemaleText_loc7`='¡Koltira, salgamos de aquí!' WHERE `ID`=29243;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전 이런 곳을 상상하고 여기 오기로 한 건 아니랍니다. 하지만... 적어도 여긴 따뜻하군요.', `FemaleText_loc4`='旅店的设施并不符合我的要求，不过……这里至少还算暖和。', `FemaleText_loc5`='我簽下去可不是為了這而來的，不過，嘿...至少這兒很溫暖。', `FemaleText_loc7`='Yo no me alisté para esto, pero oye... al menos aquí hace calor.' WHERE `ID`=29244;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 업적을 달성했습니다! $a!', `MaleText_loc4`='%s获得了成就$a！', `MaleText_loc5`='%s獲得了$a的成就!', `MaleText_loc7`='¡%s ha ganado el logro $a!', `FemaleText_loc1`='%s|1이;가; 업적을 달성했습니다! $a!', `FemaleText_loc4`='%s获得了成就$a！', `FemaleText_loc5`='%s獲得了$a的成就!', `FemaleText_loc7`='¡%s ha ganado el logro $a!' WHERE `ID`=29245;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='붉은십자군은 새로운 주인을 섬길 것이다. 죽어서 말이지...', `MaleText_loc4`='血色十字军将迎来一名新主子——我是说，在他们死后……', `MaleText_loc5`='血色十字軍將侍奉他們的新主人 - 在他們死後...', `MaleText_loc7`='La Cruzada Escarlata servirá a un nuevo maestro... en la muerte...' WHERE `ID`=29246;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 따뜻하군. 레이제크는 이런 걸 좋아하지.', `MaleText_loc4`='剑刃残留着鲜血的余温，雷耶克很喜欢。', `MaleText_loc5`='還溫溫的，就跟瑞傑克喜歡的一樣。', `MaleText_loc7`='Aún caliente, como le gusta a Rejek.' WHERE `ID`=29247;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='레이제크 강해지는 게 느껴진다! 레이제크의 두 손으로 날름이들 부숴놓겠다!', `MaleText_loc4`='雷耶克感觉自己变强壮了！雷耶克能徒手击败大舌头怪！', `MaleText_loc5`='瑞傑克感到變強了!瑞傑克用雙手壓碎了大舌頭的腦袋!', `MaleText_loc7`='¡Rejek sentirse fuerte! ¡Rejek aplastar calaveras de lenguas-grandes entre sus manos!' WHERE `ID`=29248;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='레이제크와 $n|1이;가; 광란심장 일족의 적들에게 두려움을 가르칠 거다!', `MaleText_loc4`='雷耶克和$n要让狂心氏族的敌人吓得簌簌发抖！', `MaleText_loc5`='瑞傑克和$n會教教狂心的敵人畏懼我們!', `MaleText_loc7`='¡Rejek y $n enseñarán a los enemigos de los Corazón Frenético a temernos!' WHERE `ID`=29249;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 뭐지? 아칼리를 죽였을 때 너를 느꼈다. 모두가 두려워하는 $n 녀석이로구나.', `MaleText_loc4`='这是什么？我杀死阿卡里时就认出你了。你是$n，他们都很惧怕你。', `MaleText_loc5`='這是什麼?我在殺了阿卡利的時候認得你的。你一定是那個令眾人驚懼的$n。', `MaleText_loc7`='¿Qué es esto? Te reconozco de cuando maté a Akali. Tú debes ser ese tal $n a quien todo el mundo teme.' WHERE `ID`=29250;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 두렵지 않다, 애송이 녀석. 오히려 그 반대지. 너를 해치울 날을 내가 얼마나 기다렸는지 아느냐? 이제 아무도 내가 짐토르가로 가는 걸 방해할 수 없겠군!', `MaleText_loc4`='你根本不足为患，$g小子:小丫头;。相反，我正想杀了你。谁也别想阻止我进入希姆托加！', `MaleText_loc5`='不要擔心我，$g男孩:女孩;。正好相反 - 我期待能殺掉你們。我和辛托加之間就不會有人礙事了。', `MaleText_loc7`='No me preocupas, $gchico:chica;. Al contrario: estoy deseando matarte. ¡Ahora, nada se interpondrá entre Zim''Torga y yo!' WHERE `ID`=29251;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바보 녀석들! 이제 누구도 우릴 막을 수 없다!', `MaleText_loc4`='蠢货！谁都无法阻止我们！', `MaleText_loc5`='笨蛋!還有誰能阻擋我們!', `MaleText_loc7`='¡Insensatos! ¡Ya nada puede detenernos!' WHERE `ID`=29252;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제야 진실을 알게 되다니, 가엾기 그지없구나. 나는 신의 힘을 휘두른다! 너는 필멸의 존재일 뿐이지. 날 쓰러뜨리겠다고? 꿈도 꾸지 마라!', `MaleText_loc4`='直到现在你才明白——我拥有神灵的力量，这真是遗憾。你不过是个凡人，怎可能击败我！', `MaleText_loc5`='如今只有你握有真相是個多麼哀傷的事情 - 我掌控了神的力量。你只是個凡人。你不要想擊敗我!', `MaleText_loc7`='Qué triste que sea ahora cuando descubres la verdad: yo poseo el poder de un dios. Tú solo eres mortal. ¡No tienes posibilidades de derrotarme!' WHERE `ID`=29253;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게 도전하는 것인가, $g 형제여:자매여;?', `MaleText_loc4`='你这是挑衅吗？', `MaleText_loc5`='你在挑戰我嗎，$g兄弟:姊妹;?', `MaleText_loc7`='¿Me estás retando, $ghermano:hermana;?', `FemaleText_loc1`='내게 도전하는 것인가요, $g 형제여:자매여;?', `FemaleText_loc4`='你这是挑衅吗？', `FemaleText_loc5`='你在挑戰我嗎，$g兄弟:姊妹;?', `FemaleText_loc7`='¿Me estás retando, $ghermano:hermana;?' WHERE `ID`=29254;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너에게 결투를 신청한다, 죽음의 기사여!', `MaleText_loc4`='我要挑战你，死亡骑士！', `MaleText_loc5`='我挑戰你，死亡騎士!', `MaleText_loc7`='¡Te reto, caballero de la Muerte!', `FemaleText_loc1`='너에게 결투를 신청한다, 죽음의 기사여!', `FemaleText_loc4`='我要挑战你，死亡骑士！', `FemaleText_loc5`='我挑戰你，死亡騎士!', `FemaleText_loc7`='¡Te reto, caballero de la Muerte!' WHERE `ID`=29255;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너와 상관없는 일에 사사건건 간섭해 왔겠다. 너는 이방인이자 침입자일 뿐이다. 죽을 준비나 해라!', `MaleText_loc4`='多管闲事。你只是闯入巨魔帝国的外来者。去死吧！', `MaleText_loc5`='你插手一件你管不著的事情。你不過就是個異國的入侵者罷了，準備受死吧!', `MaleText_loc7`='Te has metido en donde nadie te llamaba. No eres más que un invasor extranjero. ¡Prepárate para morir!' WHERE `ID`=29256;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예언자가 파멸의 의식을 시작합니다.', `MaleText_loc4`='先知开始施放歼灭仪式。', `MaleText_loc5`='預言者開始施放毀滅的儀式。', `MaleText_loc7`='El profeta comienza a lanzar un ritual de aniquilación.' WHERE `ID`=29257;
