UPDATE `locales_broadcast_text` SET `MaleText_loc1`='확실히 발라 주마, 애송이!', `MaleText_loc4`='看我怎么把你揍趴下，菜鸟！', `MaleText_loc5`='我要把你的心臟挖出來，親愛的!', `MaleText_loc7`='¡Voy a arrancarte el corazón, gusano!', `FemaleText_loc1`='웃기지도 않네.', `FemaleText_loc4`='别逗我笑了。', `FemaleText_loc5`='我要把你的心臟挖出來，親愛的!', `FemaleText_loc7`='No me hagas reír.' WHERE `ID`=29263;
