UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너는 가망이 없다, $n.', `MaleText_loc4`='你赢不了的，$n。', `MaleText_loc5`='門兒都沒有，$n。', `MaleText_loc7`='No tienes ninguna posibilidad, $n.', `FemaleText_loc1`='당신한테는 가망이 없군요, $n.', `FemaleText_loc4`='你赢不了的，$n。', `FemaleText_loc5`='門兒都沒有，$n。', `FemaleText_loc7`='No tienes ninguna posibilidad, $n.' WHERE `ID`=29267;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕께서 오늘의 진정한 우승자를 친히 만나실 것이다!', `MaleText_loc4`='看看谁才是巫妖王麾下真正的勇士！', `MaleText_loc5`='就在今天，巫妖王會看到他真正的勇士!', `MaleText_loc7`='¡El Rey Exánime verá a su campeón hoy!', `FemaleText_loc1`='리치 왕께서 오늘의 진정한 우승자를 친히 만나주실 거예요!', `FemaleText_loc4`='看看谁才是巫妖王麾下真正的勇士！', `FemaleText_loc5`='就在今天，巫妖王會看到他真正的勇士!', `FemaleText_loc7`='¡El Rey Exánime verá a su campeona hoy!' WHERE `ID`=29268;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='예언자여!', `FemaleText_loc4`='先知！', `FemaleText_loc5`='預言者!', `FemaleText_loc7`='¡PROFETA!' WHERE `ID`=29269;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘을 기억하라, $n. 아주 망신스러운 날이 될 테니.', `MaleText_loc4`='$n，你给我记好了，今天将是你彻底溃败的日子。', `MaleText_loc5`='記住這一天，$n，因為這一天你將會徹底被佔有。', `MaleText_loc7`='Recuerda este día, $n pues es el día que vas a ser $gmachacado:machacada; a fondo.', `FemaleText_loc1`='오늘을 기억하세요, $n. 망신살이 제대로 뻗친 날이 될 거예요.', `FemaleText_loc4`='$n，你给我记好了，今天将是你被彻底击败的日子。', `FemaleText_loc5`='記住這一天，$n，因為這一天你將會徹底被佔有。', `FemaleText_loc7`='Recuerda este día, $n pues es el día que vas a ser $gmachacado:machacada; a fondo.' WHERE `ID`=29270;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐지? 하르코아?!', `MaleText_loc4`='什么？哈克娅？！', `MaleText_loc5`='什麼?哈寇亞?!', `MaleText_loc7`='¿Qué? ¡¿HAR''KOA?!' WHERE `ID`=29271;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='드라카리의 더러운 손을 그들에게서 당장 치우지 못할까!', `FemaleText_loc4`='把你的脏手拿开！', `FemaleText_loc5`='把你那污穢的德拉克瑞髒手拿開它們!', `FemaleText_loc7`='¡APARTA TUS SUCIAS MANOS DE DRAKKARI DE ELLOS!' WHERE `ID`=29272;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋다, 고양이야. 어차피 언젠가는 닥칠 네 죽음을 더는 미룰 필요가 없겠다. 이 얼간이부터 처리하고 나서 바로 너를 상대해 주마.', `MaleText_loc4`='很好，小东西。看来我也不必对你手下留情了。等我解决掉这个蠢货，再来对付你！', `MaleText_loc5`='非常好，小貓咪。我看不出任何需要延緩你無法避免的死亡。我一把這些呆子的性命結束以後，馬上就來對付你!', `MaleText_loc7`='Muy bien, gatito. No veo necesario retrasar más tu inevitable muerte. ¡Me encargaré con gusto de ti en cuanto acabe con este insensato!' WHERE `ID`=29273;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그렇게 하지 못할걸. 네 보호막은 없어지리라. 당장 의식을 멈추고 그들을 풀어주어라!', `FemaleText_loc4`='是吗？我命令你立即终止仪式，放了他们！', `FemaleText_loc5`='我可不這麼認為。你要放下你的免疫能力，立刻終止儀式放了他們!', `FemaleText_loc7`='NO LO CREO. ¡ABANDONARÁS TU INMUNIDAD, DETENDRÁS TU RITUAL AHORA Y LOS LIBERARÁS!' WHERE `ID`=29274;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 난 지지 않아!', `MaleText_loc4`='不！我是不会被打败的！', `MaleText_loc5`='不!我不會被擊敗!', `MaleText_loc7`='¡NO! ¡No podréis conmigo!' WHERE `ID`=29275;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고맙다. 그대가 다시 한 번 우리 모두를 구했다. 짐토르가에서 만나자꾸나.', `FemaleText_loc4`='谢谢你。你再次拯救了我们。我会在希姆托加等你。', `FemaleText_loc5`='謝謝你。你又再一次拯救了我們。回辛托加見。', `FemaleText_loc7`='Gracias. Una vez más nos habéis salvado a todos. Volveré a veros en Zim''Torga.' WHERE `ID`=29276;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='별로 효과가 없었군.', `MaleText_loc4`='呃，似乎没用。', `MaleText_loc5`='好吧，沒成功。', `MaleText_loc7`='Bueno, eso no ha funcionado.', `FemaleText_loc1`='효과가 별로 없었군요.', `FemaleText_loc4`='呃，似乎没用。', `FemaleText_loc5`='好吧，沒成功。', `FemaleText_loc7`='Bueno, eso no ha funcionado.' WHERE `ID`=29277;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파란색과 초록색을 혼동하지 않도록 조심하시오.', `MaleText_loc4`='记住，别把蓝色的和绿色的混起来。', `MaleText_loc5`='特別提醒，不要把藍色的跟綠色的搞混了。', `MaleText_loc7`='Nota mental: no mezclar el azul con el verde.', `FemaleText_loc1`='조심하세요, 파란색은 건드리지도 마세요.', `FemaleText_loc4`='记住，别把蓝色的和绿色的混起来。', `FemaleText_loc5`='特別提醒，不要把藍色的跟綠色的搞混了。', `FemaleText_loc7`='Nota mental: no mezclar el azul con el verde.' WHERE `ID`=29278;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맞소. 빨간색으로 해야 하오!', `MaleText_loc4`='啊，应该试试红色的！', `MaleText_loc5`='對，那就該試試紅色的!', `MaleText_loc7`='¡Síp, debería haber probado el rojo!', `FemaleText_loc1`='맞아요. 빨간색을 골라야 해요!', `FemaleText_loc4`='啊，应该试试红色的！', `FemaleText_loc5`='對，那就該試試紅色的!', `FemaleText_loc7`='¡Síp, debería haber probado el rojo!' WHERE `ID`=29279;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='딱 꼬집어 내가 바라던 결과는 아니오.', `MaleText_loc4`='这不是我想要的结果。', `MaleText_loc5`='那肯定不是我想要的反應。', `MaleText_loc7`='Estoy seguro de que esa no era la reacción que quería.', `FemaleText_loc1`='제가 바라던 결과는 아니로군요.', `FemaleText_loc4`='这不是我想要的结果。', `FemaleText_loc5`='那肯定不是我想要的反應。', `FemaleText_loc7`='Estoy segura de que esa no era la reacción que quería.' WHERE `ID`=29280;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여길 잘 파악해 둬. 내가 여기를 정복할 때 날 도와줘야 할 테니까!', `MaleText_loc4`='朋友，好好瞧瞧这里。你要帮我征服它！', `MaleText_loc5`='老兄，好好研究研究這塊地方。你要幫忙我征服這裡!', `MaleText_loc7`='Estudia bien este lugar, tron. ¡Me vas a ayudar a conquistarlo!' WHERE `ID`=29281;
