UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 눈을 똑바로 보시오. 일을 처리...', `MaleText_loc4`='看着我的眼睛……', `MaleText_loc5`='你將直視我的雙眼，直到...', `MaleText_loc7`='Me mirarás a los ojos cuando...' WHERE `ID`=29287;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n?', `MaleText_loc4`='$n？', `MaleText_loc5`='$n?', `MaleText_loc7`='¿$n?' WHERE `ID`=29288;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 어디서든 그 뿔은 알아볼 수 있소... 도대체... 저들이 당신에게 무슨 짓을 한 거요, $n?', `MaleText_loc4`='$n，我认得你的犄角……他们……他们对你做了些什么，$n？', `MaleText_loc5`='$n，就算化成灰我也能認得那一對角...他們...他們對你做了什麼，$n?', `MaleText_loc7`='$n, reconocería esos cuernos en cualquier lugar... Qué... ¿Qué te han hecho, $n?' WHERE `ID`=29289;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 기억하지 못하는군, 아니오? 망할 스컬지 같으니... 그놈들은 당신이라는 존재를 말하던 정의로운 힘은 물론 마지막 선의까지도 모두 빨아들이려고 했소. 당신이 타우렌이었던 그 이유 자체를 말이오!', `MaleText_loc4`='你不记得我了？该死的天灾军团……他们挫败了你的正义之气、泯灭了你最后一丝良知……还有你身为牛头人的天性！', `MaleText_loc5`='你不記得我了，對吧?該死的天譴軍...他們把塑造你成為一名懲戒的正義之力全都耗盡。每一分毫的良善...每一分毫牛頭人的本性!', `MaleText_loc7`='No me recuerdas, ¿verdad? Maldita Plaga... Han intentado drenar de ti todo lo que te convertía en alguien digno y admirable. Hasta el último gramo de bondad... ¡Todo lo que te hacía ser $gun:una; tauren!' WHERE `ID`=29290;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 그렇지! 이곳에 있었던 위대한 영광이 재현될 거야!', `MaleText_loc4`='朋友！瞧瞧，这片土地承载了多少荣耀！', `MaleText_loc5`='啊，對啦，老兄!光榮馬上就會降臨這裡!', `MaleText_loc7`='¡Ah, sí, tron! ¡Hay gran gloria que obtener aquí!' WHERE `ID`=29291;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕은 자기 힘을 섬기는 사람들에게 나눠준다네.', `MaleText_loc4`='巫妖王愿意与忠于他的仆从分享力量。', `MaleText_loc5`='巫妖王會將力量分享給好好服侍他的人，老兄。', `MaleText_loc7`='¡El Rey Exánime comparte su poder con aquellos que le sirven bien!' WHERE `ID`=29292;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나한테 와봐, $n. 너한테 할 말이 있어.', `MaleText_loc4`='来见我吧，$n。我必须和你谈谈。', `MaleText_loc5`='來我身邊，$n。我得跟你聊聊。', `MaleText_loc7`='Ven a mí ahora, $n. Debo hablar contigo.' WHERE `ID`=29293;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생각해 보시오, $n. 회상해 보란 말이오. 당신이 태어난 멀고어의 그 넘실거리는 초원을 기억해 보시오. 빛나던 삶을 기억해보란 말이오. 당신은 한때 타우렌 용사였소! 지금의 모습은 진정한 당신의 모습이 아니오.', `MaleText_loc4`='$n，仔细回忆。想想莫高雷起伏的草原，那是你的家乡。想想生命的壮丽画卷。你，曾是牛头人氏族的勇士！眼前的你，不是真正的你。', `MaleText_loc5`='回想，$n。快想起來。試著回想莫高雷起伏的平原，你出生的地方。回想起生命的光彩，$g兄弟:姊妹;，你曾是牛頭人的勇士!你不是這樣的!', `MaleText_loc7`='Piensa, $n. Recuerda. Intenta recordar las extensas llanuras de Mulgore, el lugar donde naciste. Recuerda el esplendor de la vida, $ghermano:hermana;. ¡Una vez fuiste $gun campeón:una campeona; de los tauren! $gEste:Esta; no eres tú.' WHERE `ID`=29294;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 말을 들으시오, $n. 리치 왕의 제어에서 벗어나야 하오. 그는 이 세상을... 폐허로 된 우리의 세계를 보고자 하는 악마라오. 당신이 그의 목적을 이루는 도구로 이용당해서는 안 되오. 당신은 영웅이었으며 다시 영웅이 될 수 있소. 싸우란 말이오, 제기랄! 그의 제어에서 벗어나시오!', `MaleText_loc4`='听我说，$n。你必须摆脱巫妖王的控制。他一心盘算着毁掉这个世界，毁掉我们的家园。你不该沦为任由他摆布的棋子！过去，你曾是一名伟大的英雄；现在，我相信你能为新的英雄。反抗吧！摆脱巫妖王的控制！', `MaleText_loc5`='聽我說，$n。你一定要反抗巫妖王的控制。他是個只想看到這個世界 - 我們的世界 - 毀滅的怪物。別讓他利用你達成他的目標。你曾經是個英雄，你一定還能再成為英雄的。反抗呀，該死的!反抗他的控制!', `MaleText_loc7`='Escúchame, $n. Debes luchar contra el control del Rey Exánime. Es un monstruo que quiere ver este mundo, nuestro mundo, convertido en ruinas. No dejes que te utilice para lograr sus metas. Una vez fuiste $gun héroe:una heroína; y puedes volver a serlo. ¡Lucha, maldita sea! ¡Lucha contra su control!' WHERE `ID`=29295;
