UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노란 달 관문이 공격받고 있습니다!', `MaleText_loc4`='金月之门遭到攻击！', `MaleText_loc5`='黃月之門遭到攻擊!', `MaleText_loc7`='¡Están atacando la Puerta de la Luna Amarilla!' WHERE `ID`=29300;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이젠... 내게 더 남은 시간이 없소. 난 이제 틀렸소이다. 날 죽여 주시오. 그러지 않으면 저들이 우리 둘 다 죽일 거요. $n... 멀고어를 기억하시오. 이 세상은 지켜낼 가치가 있는 곳이라오.', `MaleText_loc4`='我……我支撑不住了。这是注定的命运。杀了我吧，$n，否则我们俩都难逃一死。$n……想想莫高雷。这个世界值得你去拯救。', `MaleText_loc5`='我的...我的時間不夠了。我沒救了，結束我的性命，$n。快動手，要不然他們會殺了我們兩個。$n...毋忘莫高雷，這世界是值得拯救的。', `MaleText_loc7`='Ya... ya no me queda tiempo. Estoy acabado. Acaba conmigo, $n. Hazlo o nos matarán a los dos. $n... Recuerda Mulgore. Vale la pena salvar este mundo.' WHERE `ID`=29301;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 날 죽이시오, $n! 비참한 내 생명을 끊어달란 말이오!', `MaleText_loc4`='动手吧，$n！让我解脱吧！', `MaleText_loc5`='動手，$n!讓我從苦難中解脫!', `MaleText_loc7`='¡Hazlo, $n! ¡Líbrame de mi miseria!' WHERE `ID`=29302;
