UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 무슨 일이오? 왜 이렇게 오래 걸리지, $n?', `MaleText_loc4`='出了什么状况吗？你怎么去了那么久，$n？', `MaleText_loc5`='那裡發生了什麼事?怎麼花了那麼長的時間，$n?', `MaleText_loc7`='¿Qué está pasando aquí? ¿Por qué estás tardando tanto, $n?' WHERE `ID`=29309;
