UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 어디서든 그 얼굴은 알아볼 수 있습니다... 도대체... 저들이 당신에게 무슨 짓을 한 겁니까, $n?', `MaleText_loc4`='$n，我认得你的脸庞……他们……他们对你做了些什么，$n？', `MaleText_loc5`='$n，就算化成灰我也能認得那張臉...他們...他們對你做了什麼，$n?', `MaleText_loc7`='$n, reconocería ese rostro en cualquier lugar... Qué... ¿Qué te han hecho, $n?', `FemaleText_loc1`='$n, 어디서든 그 얼굴은 알아볼 수 있습니다... 도대체... 저들이 당신에게 무슨 짓을 한 겁니까, $n?', `FemaleText_loc4`='$n，我认得你的脸庞……他们……他们对你做了些什么，$n？', `FemaleText_loc5`='$n，就算化成灰我也能認得那張臉...他們...他們對你做了什麼，$n?', `FemaleText_loc7`='$n, reconocería ese rostro en cualquier lugar... Qué... ¿Qué te han hecho, $n?' WHERE `ID`=29313;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절 기억하지 못하시는군요, 아닌가요? 망할 스컬지 같으니... 그놈들은 당신이라는 존재를 말하던 정의로운 힘은 물론 마지막 선의까지도 모두 빨아들이려고 했어요. 당신이 인간이었던 그 이유 자체를 말이에요!', `MaleText_loc4`='你不记得我了？该死的天灾军团……他们挫败了你的正义之气、泯灭了你最后一丝良知……还有你身为人类的天性！', `MaleText_loc5`='你不記得我了，是嗎?可恨的天譴軍...他們奪去了你的一切，身為復仇正義之師的一切。你每一分的良善...每一分人類的本性!', `MaleText_loc7`='No me recuerdas, ¿verdad? Maldita Plaga... Han intentado drenar de ti todo lo que te convertía en alguien digno y admirable. Hasta el último gramo de bondad... ¡Todo lo que te hacía ser $gun humano:una humana;!', `FemaleText_loc1`='절 기억하지 못하시는군요, 아닌가요? 망할 스컬지 같으니... 그놈들은 당신이라는 존재를 말하던 정의로운 힘은 물론 마지막 선의까지도 모두 빨아들이려고 했어요. 당신이 인간이었던 그 이유 자체를 말이에요!', `FemaleText_loc4`='你不记得我了？该死的天灾军团……他们挫败了你的正义之气、泯灭了你最后一丝良知……还有你身为人类的天性！', `FemaleText_loc5`='你不記得我了，是嗎?可恨的天譴軍...他們奪去了你的一切，身為復仇正義之師的一切。你每一分的良善...每一分人類的本性!', `FemaleText_loc7`='No me recuerdas, ¿verdad? Maldita Plaga... Han intentado drenar de ti todo lo que te convertía en alguien digno y admirable. Hasta el último gramo de bondad... ¡Todo lo que te hacía ser $gun humano:una humana;!' WHERE `ID`=29314;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생각해 보십시오, $n. 회상해 보란 말입니다. 당신이 태어난 엘윈의 계곡과 언덕을 기억해 보십시오. 빛나던 삶을 기억해보란 말입니다. 당신은 한때 얼라이언스의 용사였습니다! 지금의 모습은 진정한 당신의 모습이 아닙니다.', `MaleText_loc4`='$n，仔细回忆。想想艾尔文森林静谧的山谷，那是你的家乡。想想生命的壮丽画卷。你，曾是联盟的勇士！眼前的你，不是真正的你。', `MaleText_loc5`='回想一下，$n。快想起來。試著回想艾爾文的丘陵與山谷，你出生的地方。回想起生命的光彩，$g兄弟:姊妹;，你曾是聯盟的勇士!你不是這樣的!', `MaleText_loc7`='Piensa, $n. Recuerda. Intenta recordar las colinas y los valles de Elwynn, el lugar donde naciste. Recuerda el esplendor de la vida, $ghermano:hermana;. ¡Una vez fuiste $gun campeón:una campeona; de la Alianza! $gEste:Esta; no eres tú.', `FemaleText_loc1`='생각해 보십시오, $n. 회상해 보란 말입니다. 당신이 태어난 엘윈의 계곡과 언덕을 기억해 보십시오. 빛나던 삶을 기억해보란 말입니다. 당신은 한때 얼라이언스의 용사였습니다! 지금의 모습은 진정한 당신의 모습이 아닙니다.', `FemaleText_loc4`='$n，仔细回忆。想想艾尔文森林静谧的山谷，那是你的家乡。想想生命的壮丽画卷。你，曾是联盟的勇士！眼前的你，不是真正的你。', `FemaleText_loc5`='回想一下，$n。快想起來。試著回想艾爾文的丘陵與山谷，你出生的地方。回想起生命的光彩，$g兄弟:姊妹;，你曾是聯盟的勇士!你不是這樣的!', `FemaleText_loc7`='Piensa, $n. Recuerda. Intenta recordar las colinas y los valles de Elwynn, el lugar donde naciste. Recuerda el esplendor de la vida, $ghermano:hermana;. ¡Una vez fuiste $gun campeón:una campeona; de la Alianza! $gEste:Esta; no eres tú.' WHERE `ID`=29315;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 말을 들으세요, $n. 리치 왕의 제어에서 벗어나야 합니다. 그는 이 세상을... 폐허로 된 우리의 세계를 보고자 하는 악마입니다. 당신이 그의 목적을 이루는 도구로 이용당해서는 안 됩니다. 당신은 영웅이었으며 다시 영웅이 될 수 있습니다. 싸우란 말입니다, 제기랄! 그의 제어에서 벗어나세요!', `MaleText_loc4`='听我说，$n。你必须摆脱巫妖王的控制。他一心盘算着毁掉这个世界，毁掉我们的家园。你不该沦为任由他摆布的棋子！过去，你曾是一名伟大的英雄；现在，我相信你能为新的英雄。反抗吧！摆脱巫妖王的控制！', `MaleText_loc5`='聽我說，$n。你一定要反抗巫妖王的控制。他是個只想看到這個世界 - 我們的世界 - 毀滅的怪物。別讓他利用你達成他的目標。你曾經是個英雄，你一定還能再成為英雄的。反抗呀，該死的!反抗他的控制!', `MaleText_loc7`='Escúchame, $n. Debes luchar contra el control del Rey Exánime. Es un monstruo que quiere ver este mundo, nuestro mundo, convertido en ruinas. No dejes que te utilice para lograr sus metas. Una vez fuiste $gun héroe:una heroína; y puedes volver a serlo. ¡Lucha, maldita sea! ¡Lucha contra su control!', `FemaleText_loc1`='내 말을 들으세요, $n. 리치 왕의 제어에서 벗어나야 합니다. 그는 이 세상을... 폐허로 된 우리의 세계를 보고자 하는 악마입니다. 당신이 그의 목적을 이루는 도구로 이용당해서는 안 됩니다. 당신은 영웅이었으며 다시 영웅이 될 수 있습니다. 싸우란 말입니다, 제기랄! 그의 제어에서 벗어나세요!', `FemaleText_loc4`='听我说，$n。你必须摆脱巫妖王的控制。他一心盘算着毁掉这个世界，毁掉我们的家园。你不该沦为任由他摆布的棋子！过去，你曾是一名伟大的英雄；现在，我相信你能为新的英雄。反抗吧！摆脱巫妖王的控制！', `FemaleText_loc5`='聽我說，$n。你一定要反抗巫妖王的控制。他是個只想看到這個世界 - 我們的世界 - 毀滅的怪物。別讓他利用你達成他的目標。你曾經是個英雄，你一定還能再成為英雄的。反抗呀，該死的!反抗他的控制!', `FemaleText_loc7`='Escúchame, $n. Debes luchar contra el control del Rey Exánime. Es un monstruo que quiere ver este mundo, nuestro mundo, convertido en ruinas. No dejes que te utilice para lograr sus metas. Una vez fuiste $gun héroe:una heroína; y puedes volver a serlo. ¡Lucha, maldita sea! ¡Lucha contra su control!' WHERE `ID`=29316;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이젠... 내게 더 남은 시간이 없습니다. 난 이제 틀렸습니다. 날 죽여 주십시오. 그러지 않으면 저들이 우리 둘 다 죽일 겁니다. $n... 엘윈을 기억하십시오. 이 세상은 지켜낼 가치가 있는 곳입니다.', `MaleText_loc4`='我……我支撑不住了。这是注定的命运。杀了我吧，$n，否则我们俩都难逃一死。$n……想想艾尔文森林。这个世界值得你去拯救。', `MaleText_loc5`='我的...我的時間不夠了。我沒救了，結束我的性命，$n。快動手，要不然他們會殺了我們兩個。$n...毋忘艾爾文，這世界是值得拯救的。', `MaleText_loc7`='Ya... ya no me queda tiempo. Estoy acabado. Acaba conmigo, $n. Hazlo o nos matarán a los dos. $n... Recuerda Elwynn. Vale la pena salvar este mundo.', `FemaleText_loc1`='이젠... 내게 더 남은 시간이 없습니다. 난 이제 틀렸습니다. 날 죽여 주십시오. 그러지 않으면 저들이 우리 둘 다 죽일 겁니다. $n... 엘윈을 기억하십시오. 이 세상은 지켜낼 가치가 있는 곳입니다.', `FemaleText_loc4`='我……我支撑不住了。这是注定的命运。杀了我吧，$n，否则我们俩都难逃一死。$n……想想艾尔文森林。这个世界值得你去拯救。', `FemaleText_loc5`='我的...我的時間不夠了。我沒救了，結束我的性命，$n。快動手，要不然他們會殺了我們兩個。$n...毋忘艾爾文，這世界是值得拯救的。', `FemaleText_loc7`='Ya... ya no me queda tiempo. Estoy acabada. Acaba conmigo, $n. Hazlo o nos matarán a los dos. $n... Recuerda Elwynn. Vale la pena salvar este mundo.' WHERE `ID`=29317;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 날 죽이세요, $n! 비참한 내 생명을 끊어달란 말입니다!', `MaleText_loc4`='动手吧，$n！让我解脱吧！', `MaleText_loc5`='動手，$n!讓我從苦難中解脫!', `MaleText_loc7`='¡Hazlo, $n! ¡Líbrame de mi miseria!', `FemaleText_loc1`='어서 날 죽이세요, $n! 비참한 내 생명을 끊어달란 말입니다!', `FemaleText_loc4`='动手吧，$n！让我解脱吧！', `FemaleText_loc5`='動手，$n!讓我從苦難中解脫!', `FemaleText_loc7`='¡Hazlo, $n! ¡Líbrame de mi miseria!' WHERE `ID`=29318;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 심한 부상으로 목숨을 잃습니다.', `MaleText_loc4`='%s因为伤势过重而死掉了。', `MaleText_loc5`='%s傷重不治。', `MaleText_loc7`='%s muere a causa de sus heridas.', `FemaleText_loc1`='%s|1이;가; 심한 부상으로 목숨을 잃습니다.', `FemaleText_loc4`='%s因为伤势过重而死掉了。', `FemaleText_loc5`='%s傷重不治。', `FemaleText_loc7`='%s muere a causa de sus heridas.' WHERE `ID`=29319;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 무슨 일이오? 왜 이렇게 오래 걸리지, $n?', `MaleText_loc4`='出了什么状况吗？你怎么去了那么久，$n？', `MaleText_loc5`='那裡發生了什麼事?怎麼花了那麼長的時間，$n?', `MaleText_loc7`='¿Qué está pasando aquí? ¿Por qué estás tardando tanto, $n?' WHERE `ID`=29320;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사방이 늑대인간 천지에요! 아직 포기하지 마세요. 제가 바로 여기 있으니까요!', `FemaleText_loc4`='到处都是狼人！不要轻言放弃，我就在你身后！', `FemaleText_loc5`='到處都是狼人!先別放棄，我支援你!', `FemaleText_loc7`='¡Huargen por doquier! ¡No te rindas todavía, estoy justo detrás de ti!' WHERE `ID`=29321;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일을 마무리하러 왔군요, 그렇죠?', `MaleText_loc4`='你是来执行任务的吧？', `MaleText_loc5`='你是來完成工作的，對吧?', `MaleText_loc7`='¿Has venido a acabar el trabajo?', `FemaleText_loc1`='일을 마무리하러 왔군요, 그렇죠?', `FemaleText_loc4`='你是来执行任务的吧？', `FemaleText_loc5`='你是來完成工作的，對吧?', `FemaleText_loc7`='¿Has venido a acabar el trabajo?' WHERE `ID`=29322;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 믿음은 오직...', `MaleText_loc4`='我是来……', `MaleText_loc5`='我支持...', `MaleText_loc7`='Me gustaría ponerme en pie por...', `FemaleText_loc1`='내 믿음은 오직...', `FemaleText_loc4`='我是来……', `FemaleText_loc5`='我支持...', `FemaleText_loc7`='Me gustaría ponerme en pie por...' WHERE `ID`=29323;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n?', `MaleText_loc4`='$n？', `MaleText_loc5`='$n?', `MaleText_loc7`='¿$n?', `FemaleText_loc1`='$n?', `FemaleText_loc4`='$n？', `FemaleText_loc5`='$n?', `FemaleText_loc7`='¿$n?' WHERE `ID`=29324;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 어디서든 그 얼굴은 알아볼 수 있습니다... 도대체... 저들이 그대에게 무슨 짓을 한 겁니까, $n?', `MaleText_loc4`='$n，我认得你的脸庞……他们……他们对你做了些什么，$n？', `MaleText_loc5`='$n，就算化成灰我也能認得那張臉...他們...他們對你做了什麼，$n?', `MaleText_loc7`='$n, reconocería ese rostro en cualquier lugar... Qué... ¿Qué te han hecho, $n?', `FemaleText_loc1`='$n, 어디서든 그 얼굴은 알아볼 수 있습니다... 도대체... 저들이 그대에게 무슨 짓을 한 겁니까, $n?', `FemaleText_loc4`='$n，我认得你的脸庞……他们……他们对你做了些什么，$n？', `FemaleText_loc5`='$n，就算化成灰我也能認得那張臉...他們...他們對你做了什麼，$n?', `FemaleText_loc7`='$n, reconocería ese rostro en cualquier lugar... Qué... ¿Qué te han hecho, $n?' WHERE `ID`=29325;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절 기억하지 못하는군요? 그대의 어머니는 달의 신을 섬기는 동안 어린 그대를 제게 맡겼었습니다. 그분이 돌아오실 때까지 나는 그대를 이 팔에 안고 꿀과 양 젖을 먹이면서 달랬었습니다. 천사 같은 아이였지요. 망할 스컬지 같으니... 저들이 그대에게 무슨 짓을 한 건가요, $n?', `MaleText_loc4`='你不记得我了？那时候，你还是襁褓中的婴儿。你的母亲每次去月神殿当值时，就会把你托付给我。我抱着你，喂你蜂蜜和羊奶。我耐心地哄你睡觉，直到你的母亲回家。你就像我的小天使。该死的天灾军团……他们对你做了什么，$n？', `MaleText_loc5`='你不記得我了嗎?當你的母親任職於月神殿時，總是將還是孩子的你交給我照顧呀。我把你挽在懷裡，用蜜與羊奶餵你，讓你乖乖的等她回來，你是我的小天使。該死的天譴軍...他們對你做了什麼，$n?', `MaleText_loc7`='¿No me recuerdas? Cuando eras $gun niño:una niña; yo solía cuidarte mientras tu madre prestaba servicio en el Templo de la Luna. Te sostenía en mis brazos y te daba de comer miel y leche de oveja para calmarte hasta que ella regresara. Eras mi angelito. Maldita Plaga... ¿Qué te han hecho, $n?', `FemaleText_loc1`='절 기억하지 못하는군요? 그대의 어머니는 달의 신을 섬기는 동안 어린 그대를 제게 맡겼었습니다. 그분이 돌아오실 때까지 나는 그대를 이 팔에 안고 꿀과 양 젖을 먹이면서 달랬었습니다. 천사 같은 아이였지요. 망할 스컬지 같으니... 저들이 그대에게 무슨 짓을 한 건가요, $n?', `FemaleText_loc4`='你不记得我了？那时候，你还是襁褓中的婴儿。你的母亲每次去月神殿当值时，就会把你托付给我。我抱着你，喂你蜂蜜和羊奶。我耐心地哄你睡觉，直到你的母亲回家。你就像我的小天使。该死的天灾军团……他们对你做了什么，$n？', `FemaleText_loc5`='你不記得我了嗎?當你的母親任職於月神殿時，總是將還是孩子的你交給我照顧呀。我把你挽在懷裡，用蜜與羊奶餵你，讓你乖乖的等她回來，你是我的小天使。該死的天譴軍...他們對你做了什麼，$n?', `FemaleText_loc7`='¿No me recuerdas? Cuando eras un $gun niño:una niña; yo solía cuidarte mientras tu madre prestaba servicio en el Templo de la Luna. Te sostenía en mis brazos y te daba de comer miel y leche de oveja para calmarte hasta que ella regresara. Eras mi angelito. Maldita Plaga... ¿Qué te han hecho, $n?' WHERE `ID`=29326;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아직 아루갈의 최후를 보지 못해서 두려워요.', `FemaleText_loc4`='恐怕我们还没有见识到阿鲁高的恐怖……', `FemaleText_loc5`='我擔心我們見不到阿魯高的最後一面...', `FemaleText_loc7`='Me temo que no hemos visto a Arugal por última vez...' WHERE `ID`=29327;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛나던 삶을 기억해보란 말입니다. 당신은 한때 칼도레이의 용사였습니다! 이건 진정한 당신 모습이 아닙니다.', `MaleText_loc4`='想想生命的壮丽画卷。你，曾是卡多雷的勇士！眼前的你，不是真正的你。', `MaleText_loc5`='你一定還記得生命的光彩的，$g兄弟:姊妹;，你曾經是卡多雷的勇士呀!這不是你!', `MaleText_loc7`='Debes recordar el esplendor de la vida, $ghermano:hermana;. ¡Una vez fuiste $gun campeón:una campeona; de los kaldorei! ¡$gEste:Esta; no eres tú!', `FemaleText_loc1`='빛나던 삶을 기억해보란 말이에요. 당신은 한때 칼도레이의 용사였어요! 이건 진정한 당신 모습이 아니에요.', `FemaleText_loc4`='想想生命的壮丽画卷。你，曾是卡多雷的勇士！眼前的你，不是真正的你。', `FemaleText_loc5`='你一定還記得生命的光彩的，$g兄弟:姊妹;，你曾經是卡多雷的勇士呀!這不是你!', `FemaleText_loc7`='Debes recordar el esplendor de la vida, $ghermano:hermana;. ¡Una vez fuiste $gun campeón:una campeona; de los kaldorei! ¡$gEste:Esta; no eres tú!' WHERE `ID`=29328;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 말 좀 들어보십시오, $n. 리치 왕의 지배에서 벗어나야 합니다. 그는 이 세상을... 폐허로 된 우리의 세계를 보고자 하는 악마입니다. 당신이 그의 목적을 이루는 도구로 이용당해서는 안 됩니다. 당신은 영웅이었으며 다시 영웅이 될 수 있습니다. 싸우란 말입니다, 제기랄! 그의 조종에서 벗어나세요!', `MaleText_loc4`='听我说，$n。你必须摆脱巫妖王的控制。他一心盘算着毁掉这个世界，毁掉我们的家园。你不该沦为任由他摆布的棋子！过去，你曾是一名伟大的英雄；现在，我相信你能为新的英雄。反抗吧！摆脱巫妖王的控制！', `MaleText_loc5`='聽我說，$n。你一定要反抗巫妖王的控制。他是個只想看到這個世界 - 我們的世界 - 毀滅的怪物。別讓他利用你達成他的目標。你曾經是個英雄，你一定還能再成為英雄的。反抗呀，該死的!反抗他的控制!', `MaleText_loc7`='Escúchame, $n. Debes luchar contra el control del Rey Exánime. Es un monstruo que quiere ver este mundo, nuestro mundo, convertido en ruinas. No dejes que te utilice para lograr sus metas. Una vez fuiste $gun héroe:una heroína; y puedes volver a serlo. ¡Lucha, maldita sea! ¡Lucha contra su control!', `FemaleText_loc1`='내 말 좀 들어보십시오, $n. 리치 왕의 지배에서 벗어나야 합니다. 그는 이 세상을... 폐허로 된 우리의 세계를 보고자 하는 악마입니다. 당신이 그의 목적을 이루는 도구로 이용당해서는 안 됩니다. 당신은 영웅이었으며 다시 영웅이 될 수 있습니다. 싸우란 말입니다, 제기랄! 그의 조종에서 벗어나세요!', `FemaleText_loc4`='听我说，$n。你必须摆脱巫妖王的控制。他一心盘算着毁掉这个世界，毁掉我们的家园。你不该沦为任由他摆布的棋子！过去，你曾是一名伟大的英雄；现在，我相信你能为新的英雄。反抗吧！摆脱巫妖王的控制！', `FemaleText_loc5`='聽我說，$n。你一定要反抗巫妖王的控制。他是個只想看到這個世界 - 我們的世界 - 毀滅的怪物。別讓他利用你達成他的目標。你曾經是個英雄，你一定還能再成為英雄的。反抗呀，該死的!反抗他的控制!', `FemaleText_loc7`='Escúchame, $n. Debes luchar contra el control del Rey Exánime. Es un monstruo que quiere ver este mundo, nuestro mundo, convertido en ruinas. No dejes que te utilice para lograr sus metas. Una vez fuiste $gun héroe:una heroína; y puedes volver a serlo. ¡Lucha, maldita sea! ¡Lucha contra su control!' WHERE `ID`=29329;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이젠... 내게 더 남은 시간이 없습니다. 이제 틀렸어요. 날 죽여 주십시오. 그러지 않으면 저들이 우리 둘 다 죽일 겁니다. $n... 텔드랏실을 기억하십시오. 이 세상은 지켜낼 가치가 있는 곳입니다.', `MaleText_loc4`='我……我支撑不住了。这是注定的命运。杀了我吧，$n，否则我们俩都难逃一死。$n……想想泰达希尔，我们挚爱的家园。这个世界值得你去拯救。', `MaleText_loc5`='我的...我的時間不夠了。我沒救了，結束我的性命，$n。快動手，要不然他們會殺了我們兩個。$n...毋忘泰達希爾，我們摯愛的家園，這世界是值得拯救的。', `MaleText_loc7`='Ya... ya no me queda tiempo. Estoy acabado. Acaba conmigo, $n. Hazlo o nos matarán a los dos. $n... Recuerda Teldrassil, nuestro amado hogar. Vale la pena salvar este mundo.', `FemaleText_loc1`='이젠... 내게 더 남은 시간이 없습니다. 이제 틀렸어요. 날 죽여 주십시오. 그러지 않으면 저들이 우리 둘 다 죽일 겁니다. $n... 텔드랏실을 기억하십시오. 이 세상은 지켜낼 가치가 있는 곳입니다.', `FemaleText_loc4`='我……我支撑不住了。这是注定的命运。杀了我吧，$n，否则我们俩都难逃一死。$n……想想泰达希尔，我们挚爱的家园。这个世界值得你去拯救。', `FemaleText_loc5`='我的...我的時間不夠了。我沒救了，結束我的性命，$n。快動手，要不然他們會殺了我們兩個。$n...毋忘泰達希爾，我們摯愛的家園，這世界是值得拯救的。', `FemaleText_loc7`='Ya... ya no me queda tiempo. Estoy acabada. Acaba conmigo, $n. Hazlo o nos matarán a los dos. $n... Recuerda Teldrassil, nuestro amado hogar. Vale la pena salvar este mundo.' WHERE `ID`=29330;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 날 죽이세요, $n! 비참한 내 생명을 끊어달란 말입니다!', `MaleText_loc4`='动手吧，$n！让我解脱吧！', `MaleText_loc5`='動手，$n!讓我從苦難中解脫!', `MaleText_loc7`='¡Hazlo, $n! ¡Líbrame de mi miseria!', `FemaleText_loc1`='어서 날 죽이세요, $n! 비참한 내 생명을 끊어달란 말입니다!', `FemaleText_loc4`='动手吧，$n！让我解脱吧！', `FemaleText_loc5`='動手，$n!讓我從苦難中解脫!', `FemaleText_loc7`='¡Hazlo, $n! ¡Líbrame de mi miseria!' WHERE `ID`=29331;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 무슨 일이오? 왜 이렇게 오래 걸리지, $n?', `MaleText_loc4`='出了什么状况吗？你怎么去了那么久，$n？', `MaleText_loc5`='那裡發生了什麼事?怎麼花了那麼長的時間，$n?', `MaleText_loc7`='¿Qué está pasando aquí? ¿Por qué estás tardando tanto, $n?' WHERE `ID`=29332;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 심한 부상으로 목숨을 잃습니다.', `MaleText_loc4`='%s因为伤势过重而死掉了。', `MaleText_loc5`='%s傷重不治。', `MaleText_loc7`='%s muere a causa de sus heridas.', `FemaleText_loc1`='%s|1이;가; 심한 부상으로 목숨을 잃습니다.', `FemaleText_loc4`='%s因为伤势过重而死掉了。', `FemaleText_loc5`='%s傷重不治。', `FemaleText_loc7`='%s muere a causa de sus heridas.' WHERE `ID`=29333;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 무슨 일이오? 왜 이렇게 오래 걸리지, $n?', `MaleText_loc4`='出了什么状况吗？你怎么去了那么久，$n？', `MaleText_loc5`='那裡發生了什麼事?怎麼花了那麼長的時間，$n?', `MaleText_loc7`='¿Qué está pasando aquí? ¿Por qué estás tardando tanto, $n?' WHERE `ID`=29334;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일을 마무리하러 왔군, 그렇지?', `MaleText_loc4`='你是来执行任务的吧？', `MaleText_loc5`='你是來完成工作的，對吧?', `MaleText_loc7`='¿Has venido a acabar el trabajo?', `FemaleText_loc1`='일을 마무리하러 왔군, 그렇지?', `FemaleText_loc4`='你是来执行任务的吧？', `FemaleText_loc5`='你是來完成工作的，對吧?', `FemaleText_loc7`='¿Has venido a acabar el trabajo?' WHERE `ID`=29335;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 아이언포지의 후예는...', `MaleText_loc4`='啊，来自铁炉堡的孩子，你想做什么……', `MaleText_loc5`='嗯，我這鐵爐堡之子想要...', `MaleText_loc7`='Bueno, a este hijo de Forjaz le gustaría...', `FemaleText_loc1`='이 아이언포지의 후예는...', `FemaleText_loc4`='啊，来自铁炉堡的孩子，你想做什么……', `FemaleText_loc5`='嗯，我這鐵爐堡之子想要...', `FemaleText_loc7`='Bueno, a este hijo de Forjaz le gustaría...' WHERE `ID`=29336;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n?', `MaleText_loc4`='$n？', `MaleText_loc5`='$n?', `MaleText_loc7`='¿$n?', `FemaleText_loc1`='$n?', `FemaleText_loc4`='$n？', `FemaleText_loc5`='$n?', `FemaleText_loc7`='¿$n?' WHERE `ID`=29337;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 어디서든 그 얼굴은 알아볼 수 있소... 도대체... 저들이 당신에게 무슨 짓을 한 거요, $n?', `MaleText_loc4`='$n，我认得你的脸庞……他们……他们对你做了些什么，$g小伙子:小姑娘;？', `MaleText_loc5`='$n，就算化成灰我也能認得那張臉...他們...他們對你做了些什麼，$g小鬼:小妞;?', `MaleText_loc7`='$n, reconocería ese rostro en cualquier lugar... Qué... ¿Qué te han hecho, $gchico:chica;?', `FemaleText_loc1`='$n, 어디서든 그 얼굴은 알아볼 수 있소... 도대체... 저들이 당신에게 무슨 짓을 한 거요, $n?', `FemaleText_loc4`='$n，我认得你的脸庞……他们……他们对你做了些什么，$g小伙子:小姑娘;？', `FemaleText_loc5`='$n，就算化成灰我也能認得那張臉...他們...他們對你做了些什麼，$g小鬼:小妞;?', `FemaleText_loc7`='$n, reconocería ese rostro en cualquier lugar... Qué... ¿Qué te han hecho, $gchico:chica;?' WHERE `ID`=29338;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 기억하지 못하는군, 그런 거요? 망할 스컬지 같으니... 그놈들은 당신이라는 존재를 말하던 정의로운 힘은 물론 마지막 선의까지도 모두 빨아들이려고 했소이다. 당신이 아이언포지의 후예였던 그 이유 자체를 말이오!', `MaleText_loc4`='你不记得我了？该死的天灾军团……他们挫败了你的正义之气、泯灭了你最后一丝良知……还有你身为铁炉堡的孩子的天性！', `MaleText_loc5`='你不記得我了，對吧?該死的天譴軍...他們奪去了你的一切，身為復仇正義之師的一切。你每一分的良善...你之所以是鐵爐堡之$g子:女;的每一件事!', `MaleText_loc7`='No me recuerdas, ¿verdad? Maldita Plaga... Han intentado drenar de ti todo lo que te convertía en alguien digno y admirable. Hasta el último gramo de bondad... ¡Todo lo que te hacía ser un $ghijo:hija; de Forjaz!', `FemaleText_loc1`='날 기억하지 못하는군, 그런 거요? 망할 스컬지 같으니... 그놈들은 당신이라는 존재를 말하던 정의로운 힘은 물론 마지막 선의까지도 모두 빨아들이려고 했소이다. 당신이 아이언포지의 후예였던 그 이유 자체를 말이오!', `FemaleText_loc4`='你不记得我了？该死的天灾军团……他们挫败了你的正义之气、泯灭了你最后一丝良知……还有你身为铁炉堡的孩子的天性！', `FemaleText_loc5`='你不記得我了，對吧?該死的天譴軍...他們奪去了你的一切，身為復仇正義之師的一切。你每一分的良善...你之所以是鐵爐堡之$g子:女;的每一件事!', `FemaleText_loc7`='No me recuerdas, ¿verdad? Maldita Plaga... Han intentado drenar de ti todo lo que te convertía en alguien digno y admirable. Hasta el último gramo de bondad... ¡Todo lo que te hacía ser un $ghijo:hija; de Forjaz!' WHERE `ID`=29339;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생각해 보시오, $n. 회상해 보란 말이오. 당신이 태어난 눈 덮인 던 모로의 산을 기억해 보시오. 빛나던 삶을 떠올려 보란 말이오. 당신은 한때 드워프의 용사였소! 지금의 모습은 진정한 당신 모습이 아니오!', `MaleText_loc4`='$n，仔细回忆。想想丹莫罗被白雪覆盖的山脊，那是你的家乡。想想生命的壮丽画卷。你，曾是矮人氏族的勇士！眼前的你，不是真正的你。', `MaleText_loc5`='回想，$n，快想起來。試著回憶白雪靄靄的丹莫洛!你在那出生的，$g小鬼:小妞;。回憶那段精采的生活，$n!你曾經是矮人的勇士!這可不是你!', `MaleText_loc7`='Piensa, $n. Recuerda. ¡Intenta recordar las nevadas montañas de Dun Morogh! Tú naciste allí, $gchico:chica;. ¡Recuerda el esplendor de la vida, $n! ¡Una vez fuiste $gun campeón:una campeona; de los enanos! $gEste:Esta; no eres tú.', `FemaleText_loc1`='생각해 보시오, $n. 회상해 보란 말이오. 당신이 태어난 눈 덮인 던 모로의 산을 기억해 보시오. 빛나던 삶을 떠올려 보란 말이오. 당신은 한때 드워프의 용사였소! 지금의 모습은 진정한 당신 모습이 아니오!', `FemaleText_loc4`='$n，仔细回忆。想想丹莫罗被白雪覆盖的山脊，那是你的家乡。想想生命的壮丽画卷。你，曾是矮人氏族的勇士！眼前的你，不是真正的你。', `FemaleText_loc5`='回想，$n，快想起來。試著回憶白雪靄靄的丹莫洛!你在那出生的，$g小鬼:小妞;。回憶那段精采的生活，$n!你曾經是矮人的勇士!這可不是你!', `FemaleText_loc7`='Piensa, $n. Recuerda. ¡Intenta recordar las nevadas montañas de Dun Morogh! Tú naciste allí, $gchico:chica;. ¡Recuerda el esplendor de la vida, $n! ¡Una vez fuiste $gun campeón:una campeona; de los enanos! $gEste:Esta; no eres tú.' WHERE `ID`=29340;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 말을 들으시오, $n. 리치 왕의 지배에서 벗어나야 하오. 그는 이 세상을... 폐허로 된 우리의 세계를 보고자 하는 악마라오. 당신이 그의 목적을 이루는 도구로 이용당해서는 안 되오. 당신은 영웅이었으며 다시 영웅이 될 수 있소. 싸우란 말이오, 제기랄! 그의 조종에서 벗어나시오!', `MaleText_loc4`='听我说，$n。你必须摆脱巫妖王的控制。他一心盘算着毁掉这个世界，毁掉我们的家园。你不该沦为任由他摆布的棋子！过去，你曾是一名伟大的英雄；现在，我相信你能为新的英雄。反抗吧！摆脱巫妖王的控制！', `MaleText_loc5`='聽我說，$n。你一定要反抗巫妖王的控制。他是個只想看到這個世界 - 我們的世界 - 毀滅的怪物。別讓他利用你達成他的目標。你曾經是個英雄，你一定還能再成為英雄的。反抗呀，該死的!反抗他的控制!', `MaleText_loc7`='Escúchame, $n. Debes luchar contra el control del Rey Exánime. Es un monstruo que quiere ver este mundo, nuestro mundo, convertido en ruinas. No dejes que te utilice para lograr sus metas. Una vez fuiste $gun héroe:una heroína; y puedes volver a serlo. ¡Lucha, maldita sea! ¡Lucha contra su control!', `FemaleText_loc1`='내 말을 들으시오, $n. 리치 왕의 지배에서 벗어나야 하오. 그는 이 세상을... 폐허로 된 우리의 세계를 보고자 하는 악마라오. 당신이 그의 목적을 이루는 도구로 이용당해서는 안 되오. 당신은 영웅이었으며 다시 영웅이 될 수 있소. 싸우란 말이오, 제기랄! 그의 조종에서 벗어나시오!', `FemaleText_loc4`='听我说，$n。你必须摆脱巫妖王的控制。他一心盘算着毁掉这个世界，毁掉我们的家园。你不该沦为任由他摆布的棋子！过去，你曾是一名伟大的英雄；现在，我相信你能为新的英雄。反抗吧！摆脱巫妖王的控制！', `FemaleText_loc5`='聽我說，$n。你一定要反抗巫妖王的控制。他是個只想看到這個世界 - 我們的世界 - 毀滅的怪物。別讓他利用你達成他的目標。你曾經是個英雄，你一定還能再成為英雄的。反抗呀，該死的!反抗他的控制!', `FemaleText_loc7`='Escúchame, $n. Debes luchar contra el control del Rey Exánime. Es un monstruo que quiere ver este mundo, nuestro mundo, convertido en ruinas. No dejes que te utilice para lograr sus metas. Una vez fuiste $gun héroe:una heroína; y puedes volver a serlo. ¡Lucha, maldita sea! ¡Lucha contra su control!' WHERE `ID`=29341;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이젠... 내게 더 남은 시간이 없소. 이제 틀렸소이다. 날 죽여 주시오. 그러지 않으면 저들이 우리 둘 다 죽일 거요. $n... 카아아아아아아즈으모오오오오오오다아안 만세!', `MaleText_loc4`='我……我支撑不住了。这是注定的命运。杀了我吧，$n，否则我们俩都难逃一死。$n……为了卡兹莫丹！！！', `MaleText_loc5`='我的...我的時間不夠了。我沒救了，結束我的性命，$n。快動手，要不然他們會殺了我們兩個。$n...為了卡～～茲莫丹～～～～～～!!!', `MaleText_loc7`='Ya... ya no me queda tiempo. Estoy acabado. Acaba conmigo, $n. Hazlo o nos matarán a los dos. $n... ¡Por KHAAAAAAAAZZZ MODAAAAAANNNNNN!', `FemaleText_loc1`='이젠... 내게 더 남은 시간이 없소. 이제 틀렸소이다. 날 죽여 주시오. 그러지 않으면 저들이 우리 둘 다 죽일 거요. $n... 카아아아아아아즈으모오오오오오오다아안 만세!', `FemaleText_loc4`='我……我支撑不住了。这是注定的命运。杀了我吧，$n，否则我们俩都难逃一死。$n……为了卡兹莫丹！！！', `FemaleText_loc5`='我的...我的時間不夠了。我沒救了，結束我的性命，$n。快動手，要不然他們會殺了我們兩個。$n...為了卡～～茲莫丹～～～～～～!!!', `FemaleText_loc7`='Ya... ya no me queda tiempo. Estoy acabado. Acaba conmigo, $n. Hazlo o nos matarán a los dos. $n... ¡Por KHAAAAAAAAZZZ MODAAAAAANNNNNN!' WHERE `ID`=29342;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 날 죽이시오, $n! 비참한 내 생명을 끊어달란 말이오!', `MaleText_loc4`='动手吧，$n！让我解脱吧！', `MaleText_loc5`='動手，$n!讓我從苦難中解脫!', `MaleText_loc7`='¡Hazlo, $n! ¡Líbrame de mi miseria!', `FemaleText_loc1`='어서 날 죽이시오, $n! 비참한 내 생명을 끊어달란 말이오!', `FemaleText_loc4`='动手吧，$n！让我解脱吧！', `FemaleText_loc5`='動手，$n!讓我從苦難中解脫!', `FemaleText_loc7`='¡Hazlo, $n! ¡Líbrame de mi miseria!' WHERE `ID`=29343;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 심한 부상으로 목숨을 잃습니다.', `MaleText_loc4`='%s因为伤势过重而死掉了。', `MaleText_loc5`='%s傷重不治。', `MaleText_loc7`='%s muere a causa de sus heridas.', `FemaleText_loc1`='%s|1이;가; 심한 부상으로 목숨을 잃습니다.', `FemaleText_loc4`='%s因为伤势过重而死掉了。', `FemaleText_loc5`='%s傷重不治。', `FemaleText_loc7`='%s muere a causa de sus heridas.' WHERE `ID`=29344;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저놈들을 잡아라!', `MaleText_loc4`='抓住他们！', `MaleText_loc5`='抓住他們!', `MaleText_loc7`='¡Cogedlos!' WHERE `ID`=29345;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 무슨 일이오? 왜 이렇게 오래 걸리지, $n?', `MaleText_loc4`='出了什么状况吗？你怎么去了那么久，$n？', `MaleText_loc5`='那裡發生了什麼事?怎麼花了那麼長的時間，$n?', `MaleText_loc7`='¿Qué está pasando aquí? ¿Por qué estás tardando tanto, $n?' WHERE `ID`=29346;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일을 마무리하러 왔군요, 그렇죠?', `MaleText_loc4`='你是来执行任务的吧？', `MaleText_loc5`='你是來完成工作的，對吧?', `MaleText_loc7`='¿Has venido a acabar el trabajo?', `FemaleText_loc1`='일을 마무리하러 왔군요, 그렇죠?', `FemaleText_loc4`='你是来执行任务的吧？', `FemaleText_loc5`='你是來完成工作的，對吧?', `FemaleText_loc7`='¿Has venido a acabar el trabajo?' WHERE `ID`=29347;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게 한 가지만 허락해 준다면...', `MaleText_loc4`='能不能让我……', `MaleText_loc5`='如果你允許我一個...', `MaleText_loc7`='Si tan solo me permitieras un...', `FemaleText_loc1`='내게 한 가지만 허락해 준다면...', `FemaleText_loc4`='能不能让我……', `FemaleText_loc5`='如果你允許我一個...', `FemaleText_loc7`='Si tan solo me permitieras un...' WHERE `ID`=29348;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n?', `MaleText_loc4`='$n？', `MaleText_loc5`='$n?', `MaleText_loc7`='¿$n?', `FemaleText_loc1`='$n?', `FemaleText_loc4`='$n？', `FemaleText_loc5`='$n?', `FemaleText_loc7`='¿$n?' WHERE `ID`=29349;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 어디서든 그 얼굴은 알아볼 수 있습니다... 도대체... 저들이 당신에게 무슨 짓을 한 겁니까, $n?', `MaleText_loc4`='$n，我认得你的脸庞……他们……他们对你做了些什么，$n？', `MaleText_loc5`='$n，就算化成灰我也能認得那張臉...他們...他們對你做了什麼，$n?', `MaleText_loc7`='$n, reconocería ese rostro en cualquier lugar... Qué... ¿Qué te han hecho, $n?', `FemaleText_loc1`='$n, 어디서든 그 얼굴은 알아볼 수 있습니다... 도대체... 저들이 당신에게 무슨 짓을 한 겁니까, $n?', `FemaleText_loc4`='$n，我认得你的脸庞……他们……他们对你做了些什么，$n？', `FemaleText_loc5`='$n，就算化成灰我也能認得那張臉...他們...他們對你做了什麼，$n?', `FemaleText_loc7`='$n, reconocería ese rostro en cualquier lugar... Qué... ¿Qué te han hecho, $n?' WHERE `ID`=29350;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절 기억하지 못하시는군요, 그렇죠? 망할 스컬지 같으니... 그놈들은 당신이라는 존재를 이루는 정의로운 힘은 노움 만큼이라도 모두 빨아들이려고 했습니다. 선의라면 마지막 한 방울까지도요... 당신이 노움이었던 그 이유 자체를 말입니다!', `MaleText_loc4`='你不记得我了？该死的天灾军团……他们挫败了你的正义之气、泯灭了你最后一丝良知……还有你身为侏儒的天性！', `MaleText_loc5`='你不記得我了，是嗎?可恨的天譴軍...他們奪去了你的一切，身為矮小的復仇之師的一切。你每一分的良善...每一分地精的本性!', `MaleText_loc7`='No me recuerdas, ¿verdad? Maldita Plaga... Han intentado drenar de ti todo lo que te convertía en alguien digno y admirable. Hasta el último gramo de bondad... ¡Todo lo que te hacía ser $gun gnomo:una gnoma;!', `FemaleText_loc1`='절 기억하지 못하시는군요, 그렇죠? 망할 스컬지 같으니... 그놈들은 당신이라는 존재를 이루는 정의로운 힘은 노움 만큼이라도 모두 빨아들이려고 했습니다. 선의라면 마지막 한 방울까지도요... 당신이 노움이었던 그 이유 자체를 말입니다!', `FemaleText_loc4`='你不记得我了？该死的天灾军团……他们挫败了你的正义之气、泯灭了你最后一丝良知……还有你身为侏儒的天性！', `FemaleText_loc5`='你不記得我了，是嗎?可恨的天譴軍...他們奪去了你的一切，身為矮小的復仇之師的一切。你每一分的良善...每一分地精的本性!', `FemaleText_loc7`='No me recuerdas, ¿verdad? Maldita Plaga... Han intentado drenar de ti todo lo que te convertía en alguien digno y admirable. Hasta el último gramo de bondad... ¡Todo lo que te hacía ser $gun gnomo:una gnoma;!' WHERE `ID`=29351;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생각해 보십시오, $n. 회상해 보란 말입니다. 빌어먹을 트로그가 점령하기 전의 놈리건을 기억해 보십시오. 만능 스패너의 감촉을 떠올려 보란 말입니다. 당신은 한때 노움의 용사였습니다! 지금의 모습은 진정한 당신의 모습이 아닙니다!', `MaleText_loc4`='$n，仔细回忆。想想穴居人入侵前的诺莫瑞根！想想手握弧光扳手的感觉。你，曾是侏儒氏族的勇士！眼前的你，不是真正的你。', `MaleText_loc5`='回想一下，$n。快想起來。試著回想在那些該死穴居怪出現前的諾姆瑞根!，回想起握著扳手的感覺，$g兄弟:姊妹;，你曾是地精一族的勇士!你不是這樣的!', `MaleText_loc7`='Piensa, $n. Recuerda. ¡Intenta recordar Gnomeregan antes de que llegaran aquellos malditos troggs! Recuerda la sensación de sostener una llave de tuerca arcoluz, $ghermano:hermana;. ¡Una vez fuiste $gun campeón:una campeona; de los gnomos! $gEste:Esta; no eres tú.', `FemaleText_loc1`='생각해 보십시오, $n. 회상해 보란 말입니다. 빌어먹을 트로그가 점령하기 전의 놈리건을 기억해 보십시오. 만능 스패너의 감촉을 떠올려 보란 말입니다. 당신은 한때 노움의 용사였습니다! 지금의 모습은 진정한 당신의 모습이 아닙니다!', `FemaleText_loc4`='$n，仔细回忆。想想穴居人入侵前的诺莫瑞根！想想手握弧光扳手的感觉。你，曾是侏儒氏族的勇士！眼前的你，不是真正的你。', `FemaleText_loc5`='回想一下，$n。快想起來。試著回想在那些該死穴居怪出現前的諾姆瑞根!，回想起握著扳手的感覺，$g兄弟:姊妹;，你曾是地精一族的勇士!你不是這樣的!', `FemaleText_loc7`='Piensa, $n. Recuerda. ¡Intenta recordar Gnomeregan antes de que llegaran aquellos malditos troggs! Recuerda la sensación de sostener una llave de tuerca arcoluz, $ghermano:hermana;. ¡Una vez fuiste $gun campeón:una campeona; de los gnomos! $gEste:Esta; no eres tú.' WHERE `ID`=29352;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 말 좀 들어보십시오, $n. 리치 왕의 지배에서 벗어나야 합니다. 그는 이 세상을... 우리 세계가 폐허가 되는 것을 보려는 악마입니다. 리치 왕이 당신을 이용해서 자기 목적을 달성하도록 내버려두지 마세요. 당신은 영웅이었으며 다시 영웅이 될 수 있습니다. 싸우란 말입니다, 제기랄! 그의 조종에서 벗어나세요', `MaleText_loc4`='听我说，$n。你必须摆脱巫妖王的控制。他一心盘算着毁掉这个世界，毁掉我们的家园。你不该沦为任由他摆布的棋子！过去，你曾是一名伟大的英雄；现在，我相信你能为新的英雄。反抗吧！摆脱巫妖王的控制！', `MaleText_loc5`='聽我說，$n。你一定要反抗巫妖王的控制。他是個只想看到這個世界 - 我們的世界 - 毀滅的怪物。別讓他利用你達成他的目標。你曾經是個英雄，你一定還能再成為英雄的。反抗呀，該死的!反抗他的控制!', `MaleText_loc7`='Escúchame, $n. Debes luchar contra el control del Rey Exánime. Es un monstruo que quiere ver este mundo, nuestro mundo, convertido en ruinas. No dejes que te utilice para lograr sus metas. Una vez fuiste $gun héroe:una heroína; y puedes volver a serlo. ¡Lucha, maldita sea! ¡Lucha contra su control!', `FemaleText_loc1`='내 말 좀 들어보십시오, $n. 리치 왕의 지배에서 벗어나야 합니다. 그는 이 세상을... 우리 세계가 폐허가 되는 것을 보려는 악마입니다. 리치 왕이 당신을 이용해서 자기 목적을 달성하도록 내버려두지 마세요. 당신은 영웅이었으며 다시 영웅이 될 수 있습니다. 싸우란 말입니다, 제기랄! 그의 조종에서 벗어나세요', `FemaleText_loc4`='听我说，$n。你必须摆脱巫妖王的控制。他一心盘算着毁掉这个世界，毁掉我们的家园。你不该沦为任由他摆布的棋子！过去，你曾是一名伟大的英雄；现在，我相信你能为新的英雄。反抗吧！摆脱巫妖王的控制！', `FemaleText_loc5`='聽我說，$n。你一定要反抗巫妖王的控制。他是個只想看到這個世界 - 我們的世界 - 毀滅的怪物。別讓他利用你達成他的目標。你曾經是個英雄，你一定還能再成為英雄的。反抗呀，該死的!反抗他的控制!', `FemaleText_loc7`='Escúchame, $n. Debes luchar contra el control del Rey Exánime. Es un monstruo que quiere ver este mundo, nuestro mundo, convertido en ruinas. No dejes que te utilice para lograr sus metas. Una vez fuiste $gun héroe:una heroína; y puedes volver a serlo. ¡Lucha, maldita sea! ¡Lucha contra su control!' WHERE `ID`=29353;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이젠... 내게 더 남은 시간이 없습니다. 이제 틀렸어요. 날 죽여 주십시오. 그러지 않으면 저들이 우리 둘 다 죽일 겁니다. $n... 놈리건을 기억하십시오. 이 세상은 지켜낼 가치가 있는 곳입니다.', `MaleText_loc4`='我……我支撑不住了。这是注定的命运。杀了我吧，$n，否则我们俩都难逃一死。$n……想想诺莫瑞根。这个世界值得你去拯救。', `MaleText_loc5`='我的...我的時間不夠了。我沒救了，結束我的性命，$n。快動手，要不然他們會殺了我們兩個。$n...毋忘諾姆瑞根!這世界是值得拯救的。', `MaleText_loc7`='Ya... ya no me queda tiempo. Estoy acabado. Acaba conmigo, $n. Hazlo o nos matarán a los dos. $n... ¡Recuerda Gnomeregan! Vale la pena salvar este mundo.', `FemaleText_loc1`='이젠... 내게 더 남은 시간이 없습니다. 이제 틀렸어요. 날 죽여 주십시오. 그러지 않으면 저들이 우리 둘 다 죽일 겁니다. $n... 놈리건을 기억하십시오. 이 세상은 지켜낼 가치가 있는 곳입니다.', `FemaleText_loc4`='我……我支撑不住了。这是注定的命运。杀了我吧，$n，否则我们俩都难逃一死。$n……想想诺莫瑞根。这个世界值得你去拯救。', `FemaleText_loc5`='我的...我的時間不夠了。我沒救了，結束我的性命，$n。快動手，要不然他們會殺了我們兩個。$n...毋忘諾姆瑞根!這世界是值得拯救的。', `FemaleText_loc7`='Ya... ya no me queda tiempo. Estoy acabado. Acaba conmigo, $n. Hazlo o nos matarán a los dos. $n... ¡Recuerda Gnomeregan! Vale la pena salvar este mundo.' WHERE `ID`=29354;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 날 죽이세요, $n! 비참한 내 생명을 끊어달란 말입니다!', `MaleText_loc4`='动手吧，$n！让我解脱吧！', `MaleText_loc5`='動手，$n!讓我從苦難中解脫!', `MaleText_loc7`='¡Hazlo, $n! ¡Líbrame de mi miseria!', `FemaleText_loc1`='어서 날 죽이세요, $n! 비참한 내 생명을 끊어달란 말입니다!', `FemaleText_loc4`='动手吧，$n！让我解脱吧！', `FemaleText_loc5`='動手，$n!讓我從苦難中解脫!', `FemaleText_loc7`='¡Hazlo, $n! ¡Líbrame de mi miseria!' WHERE `ID`=29355;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 심한 부상으로 목숨을 잃습니다.', `MaleText_loc4`='%s因为伤势过重而死掉了。', `MaleText_loc5`='%s傷重不治。', `MaleText_loc7`='%s muere a causa de sus heridas.', `FemaleText_loc1`='%s|1이;가; 심한 부상으로 목숨을 잃습니다.', `FemaleText_loc4`='%s因为伤势过重而死掉了。', `FemaleText_loc5`='%s傷重不治。', `FemaleText_loc7`='%s muere a causa de sus heridas.' WHERE `ID`=29356;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일을 마무리하러 오셨군요, 그렇죠?', `MaleText_loc4`='你是来执行任务的吧？', `MaleText_loc5`='你是來完成工作的，對吧?', `MaleText_loc7`='¿Has venido a acabar el trabajo?' WHERE `ID`=29357;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 눈을 똑바로 바라보세요. 일을 처리...', `MaleText_loc4`='看着我的眼睛……', `MaleText_loc5`='你將直視我的雙眼，直到...', `MaleText_loc7`='Me mirarás a los ojos cuando...' WHERE `ID`=29358;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n?', `MaleText_loc4`='$n？', `MaleText_loc5`='$n?', `MaleText_loc7`='¿$n?' WHERE `ID`=29359;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 어디서든 그 촉수를 알아볼 수 있습니다... 도대체... 저들이 당신에게 무슨 짓을 한 건가요, $n?', `MaleText_loc4`='$n，我认得你的面须……他们……他们对你做了些什么，$n？', `MaleText_loc5`='$n，就算化成灰我也能認得那些觸鬚...他們...他們對你做了什麼，$n?', `MaleText_loc7`='$n, reconocería esos tentáculos en cualquier lugar... Qué... ¿Qué te han hecho, $n?' WHERE `ID`=29360;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절 기억하지 못하시는군요, 그렇죠? 망할 스컬지 같으니... 그놈들은 당신이라는 존재를 말하던 정의로운 힘은 물론 마지막 선의까지도 모두 빨아들이려고 했습니다. 당신이 드레나이였던 그 이유 자체를 말입니다!', `MaleText_loc4`='你不记得我了？该死的天灾军团……他们挫败了你的正义之气、泯灭了你最后一丝良知……还有你身为德莱尼人的天性！', `MaleText_loc5`='你不記得我了，對吧?該死的天譴軍...他們把塑造你成為一名懲戒的正義之力全都耗盡。每一分毫的良善...每一分毫德萊尼的本性!', `MaleText_loc7`='No me recuerdas, ¿verdad? Maldita Plaga... Han intentado drenar de ti todo lo que te convertía en alguien digno y admirable. Hasta el último gramo de bondad... ¡Todo lo que te hacía ser un draenei!' WHERE `ID`=29361;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생각해 보십시오, $n. 회상해 보란 말입니다. 당신이 태어난 아르거스의 훌륭한 산세를 떠올려 보십시오. $g형제:자매;여, 화려했던 삶을 떠올려 보란 말입니다. 당신은 한때 드레나이의 용사였습니다! 지금의 이 모습은 진정한 당신의 모습이 아닙니다!', `MaleText_loc4`='$n，仔细回忆。想想阿古斯高耸的山脊，那是你的家乡。想想生命的壮丽画卷。你，曾是德莱尼氏族的勇士！眼前的你，不是真正的你。', `MaleText_loc5`='回想，$n。快想起來。試著回想阿古斯的雄偉山脈，你出生的地方。回想起生命的光彩，$g兄弟:姊妹;，你曾是德萊尼的勇士!你不是這樣的!', `MaleText_loc7`='Piensa, $n. Recuerda. ¡Intenta recordar las orgullosas montañas de Argus, el lugar donde naciste. Recuerda el esplendor de la vida, $ghermano:hermana;. ¡Una vez fuiste $gun campeón:una campeona; de los draenei! $gEste:Esta; no eres tú.' WHERE `ID`=29362;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 말을 들으세요, $n. 리치 왕의 제어에서 벗어나야 합니다. 그는 이 세상을... 폐허로 된 우리의 세계를 보고자 하는 악마입니다. 당신이 그의 목적을 이루는 도구로 이용당해서는 안 됩니다. 당신은 영웅이었으며 다시 영웅이 될 수 있습니다. 싸우란 말입니다, 제기랄! 그의 제어에서 벗어나세요!', `MaleText_loc4`='听我说，$n。你必须摆脱巫妖王的控制。他一心盘算着毁掉这个世界，毁掉我们的家园。你不该沦为任由他摆布的棋子！过去，你曾是一名伟大的英雄；现在，我相信你能为新的英雄。反抗吧！摆脱巫妖王的控制！', `MaleText_loc5`='聽我說，$n。你一定要反抗巫妖王的控制。他是個只想看到這個世界 - 我們的世界 - 毀滅的怪物。別讓他利用你達成他的目標。你曾經是個英雄，你一定還能再成為英雄的。反抗呀，該死的!反抗他的控制!', `MaleText_loc7`='Escúchame, $n. Debes luchar contra el control del Rey Exánime. Es un monstruo que quiere ver este mundo, nuestro mundo, convertido en ruinas. No dejes que te utilice para lograr sus metas. Una vez fuiste $gun héroe:una heroína; y puedes volver a serlo. ¡Lucha, maldita sea! ¡Lucha contra su control!' WHERE `ID`=29363;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이젠... 내게 더 남은 시간이 없습니다. 난 이제 틀렸어요. 날 죽여 주십시오. 그러지 않으면 저들이 우리 둘 다 죽일 겁니다. $n... 아르거스를 기억하십시오. 이 세계에도 같은 일이 벌어지게 두지 마십시오.', `MaleText_loc4`='我……我支撑不住了。这是注定的命运。杀了我吧，$n，否则我们俩都难逃一死。$n……想想阿古斯。这个世界值得你去拯救。', `MaleText_loc5`='我的...我的時間不夠了。我沒救了，結束我的性命，$n。快動手，要不然他們會殺了我們兩個。$n...毋忘阿古斯!別讓那降臨到世上。', `MaleText_loc7`='Ya... ya no me queda tiempo. Estoy acabado. Acaba conmigo, $n. Hazlo o nos matarán a los dos. $n... Recuerda Argus. No dejes que le ocurra esto a este mundo.' WHERE `ID`=29364;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 날 죽이세요, $n! 비참한 내 생명을 끊어달란 말입니다!', `MaleText_loc4`='动手吧，$n！让我解脱吧！', `MaleText_loc5`='動手，$n!讓我從苦難中解脫!', `MaleText_loc7`='¡Hazlo, $n! ¡Líbrame de mi miseria!' WHERE `ID`=29365;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 부상으로 목숨을 잃습니다.', `MaleText_loc4`='%s因为伤势过重而死掉了。', `MaleText_loc5`='%s傷重不治。', `MaleText_loc7`='%s muere a causa de sus heridas.' WHERE `ID`=29366;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 무슨 일이오? 왜 이렇게 오래 걸리지, $n?', `MaleText_loc4`='出了什么状况吗？你怎么去了那么久，$n？', `MaleText_loc5`='那裡發生了什麼事?怎麼花了那麼長的時間，$n?', `MaleText_loc7`='¿Qué está pasando aquí? ¿Por qué estás tardando tanto, $n?' WHERE `ID`=29367;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일을 마무리하러 왔군요, 그렇죠?', `MaleText_loc4`='你是来执行任务的吧？', `MaleText_loc5`='你是來完成工作的，對吧?', `MaleText_loc7`='¿Has venido a acabar el trabajo?', `FemaleText_loc1`='일을 마무리하러 왔군요, 그렇죠?', `FemaleText_loc4`='你是来执行任务的吧？', `FemaleText_loc5`='你是來完成工作的，對吧?', `FemaleText_loc7`='¿Has venido a acabar el trabajo?' WHERE `ID`=29368;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 눈을 똑바로 바라보세요. 일을 처리...', `MaleText_loc4`='看着我的眼睛……', `MaleText_loc5`='你將直視我的雙眼，直到...', `MaleText_loc7`='Me mirarás a los ojos cuando...', `FemaleText_loc1`='내 눈을 똑바로 바라보세요. 일을 처리...', `FemaleText_loc4`='看着我的眼睛……', `FemaleText_loc5`='你將直視我的雙眼，直到...', `FemaleText_loc7`='Me mirarás a los ojos cuando...' WHERE `ID`=29369;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 어디서든 그 얼굴은 알아볼 수 있습니다... 도대체... 저들이 당신에게 무슨 짓을 한 건가요, $n?', `MaleText_loc4`='$n，我认得你的脸庞……他们……他们对你做了些什么，$n？', `MaleText_loc5`='$n，就算化成灰我也能認得那張臉...他們...他們對你做了什麼，$n?', `MaleText_loc7`='$n, reconocería ese rostro en cualquier lugar... Qué... ¿Qué te han hecho, $n?', `FemaleText_loc1`='$n, 어디서든 그 얼굴은 알아볼 수 있습니다... 도대체... 저들이 당신에게 무슨 짓을 한 건가요, $n?', `FemaleText_loc4`='$n，我认得你的脸庞……他们……他们对你做了些什么，$n？', `FemaleText_loc5`='$n，就算化成灰我也能認得那張臉...他們...他們對你做了什麼，$n?', `FemaleText_loc7`='$n, reconocería ese rostro en cualquier lugar... Qué... ¿Qué te han hecho, $n?' WHERE `ID`=29370;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n?', `MaleText_loc4`='$n？', `MaleText_loc5`='$n?', `MaleText_loc7`='¿$n?', `FemaleText_loc1`='$n?', `FemaleText_loc4`='$n？', `FemaleText_loc5`='$n?', `FemaleText_loc7`='¿$n?' WHERE `ID`=29372;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절 기억하지 못하시는군요, 그렇죠? 망할 스컬지 같으니... 그놈들은 당신이라는 존재를 말하던 정의로운 힘은 물론 마지막 선의까지도 모두 빨아들이려고 했습니다. 당신이 블러드 엘프였던 그 이유 자체를 말입니다!', `MaleText_loc4`='你不记得我了？该死的天灾军团……他们挫败了你的正义之气、泯灭了你最后一丝良知……还有你身为血精灵的天性！', `MaleText_loc5`='你不記得我了，是嗎?可恨的天譴軍...他們奪去了你的一切，身為復仇正義之師的一切。你每一分的良善...每一分血精靈的本性!', `MaleText_loc7`='No me recuerdas, ¿verdad? Maldita Plaga... Han intentado drenar de ti todo lo que te convertía en alguien digno y admirable. Hasta el último gramo de bondad... ¡Todo lo que te hacía ser $gun elfo:una elfa; de sangre!', `FemaleText_loc1`='절 기억하지 못하시는군요, 그렇죠? 망할 스컬지 같으니... 그놈들은 당신이라는 존재를 말하던 정의로운 힘은 물론 마지막 선의까지도 모두 빨아들이려고 했습니다. 당신이 블러드 엘프였던 그 이유 자체를 말입니다!', `FemaleText_loc4`='你不记得我了？该死的天灾军团……他们挫败了你的正义之气、泯灭了你最后一丝良知……还有你身为血精灵的天性！', `FemaleText_loc5`='你不記得我了，是嗎?可恨的天譴軍...他們奪去了你的一切，身為復仇正義之師的一切。你每一分的良善...每一分血精靈的本性!', `FemaleText_loc7`='No me recuerdas, ¿verdad? Maldita Plaga... Han intentado drenar de ti todo lo que te convertía en alguien digno y admirable. Hasta el último gramo de bondad... ¡Todo lo que te hacía ser $gun elfo:una elfa; de sangre!' WHERE `ID`=29373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생각해 보세요, $n. 회상해 보란 말이에요. 당신이 태어난 실버문의 웅장한 전당을 떠올려 보세요. $g형제:자매;여, 화려했던 삶을 떠올려 보란 말이에요. 당신은 한때 신도레이의 용사였어요! 지금의 이 모습은 진정한 당신의 모습이 아니에요.', `MaleText_loc4`='$n，仔细回忆。想想银月城宏伟的殿堂，那是你的家乡。想想生命的壮丽画卷。你，曾是辛多雷氏族的勇士！眼前的你，不是真正的你。', `MaleText_loc5`='回想一下，$n。快想起來。試著回想銀月城的雄偉殿堂，你出生的地方。回想起生命的光彩，$g兄弟:姊妹;，你曾是辛多雷的勇士!你不是這樣的!', `MaleText_loc7`='Piensa, $n. Recuerda. ¡Intenta recordar las majestuosas salas de la Ciudad de Lunargenta, el lugar donde naciste. Recuerda el esplendor de la vida, $ghermano:hermana;. ¡Una vez fuiste $gun campeón:una campeona; de los sin''dorei! $gEste:Esta; no eres tú.', `FemaleText_loc1`='생각해 보세요, $n. 회상해 보란 말이에요. 당신이 태어난 실버문의 웅장한 전당을 떠올려 보세요. $g형제:자매;여, 화려했던 삶을 떠올려 보란 말이에요. 당신은 한때 신도레이의 용사였어요! 지금의 이 모습은 진정한 당신의 모습이 아니에요.', `FemaleText_loc4`='$n，仔细回忆。想想银月城宏伟的殿堂，那是你的家乡。想想生命的壮丽画卷。你，曾是辛多雷氏族的勇士！眼前的你，不是真正的你。', `FemaleText_loc5`='回想一下，$n。快想起來。試著回想銀月城的雄偉殿堂，你出生的地方。回想起生命的光彩，$g兄弟:姊妹;，你曾是辛多雷的勇士!你不是這樣的!', `FemaleText_loc7`='Piensa, $n. Recuerda. ¡Intenta recordar las majestuosas salas de la Ciudad de Lunargenta, el lugar donde naciste. Recuerda el esplendor de la vida, $ghermano:hermana;. ¡Una vez fuiste $gun campeón:una campeona; de los sin''dorei! $gEste:Esta; no eres tú.' WHERE `ID`=29374;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 말을 들으세요, $n. 리치 왕의 제어에서 벗어나야 합니다. 그는 이 세상을... 폐허로 된 우리의 세계를 보고자 하는 악마입니다. 당신이 그의 목적을 이루는 도구로 이용당해서는 안 돼요. 당신은 영웅이었으며 다시 영웅이 될 수 있습니다. 싸우란 말입니다, 제기랄! 그의 제어에서 벗어나세요!', `MaleText_loc4`='听我说，$n。你必须摆脱巫妖王的控制。他一心盘算着毁掉这个世界，毁掉我们的家园。你不该沦为任由他摆布的棋子！过去，你曾是一名伟大的英雄；现在，我相信你能为新的英雄。反抗吧！摆脱巫妖王的控制！', `MaleText_loc5`='聽我說，$n。你一定要反抗巫妖王的控制。他是個只想看到這個世界 - 我們的世界 - 毀滅的怪物。別讓他利用你達成他的目標。你曾經是個英雄，你一定還能再成為英雄的。反抗呀，該死的!反抗他的控制!', `MaleText_loc7`='Escúchame, $n. Debes luchar contra el control del Rey Exánime. Es un monstruo que quiere ver este mundo, nuestro mundo, convertido en ruinas. No dejes que te utilice para lograr sus metas. Una vez fuiste $gun héroe:una heroína; y puedes volver a serlo. ¡Lucha, maldita sea! ¡Lucha contra su control!', `FemaleText_loc1`='내 말을 들으세요, $n. 리치 왕의 제어에서 벗어나야 합니다. 그는 이 세상을... 폐허로 된 우리의 세계를 보고자 하는 악마입니다. 당신이 그의 목적을 이루는 도구로 이용당해서는 안 돼요. 당신은 영웅이었으며 다시 영웅이 될 수 있습니다. 싸우란 말입니다, 제기랄! 그의 제어에서 벗어나세요!', `FemaleText_loc4`='听我说，$n。你必须摆脱巫妖王的控制。他一心盘算着毁掉这个世界，毁掉我们的家园。你不该沦为任由他摆布的棋子！过去，你曾是一名伟大的英雄；现在，我相信你能为新的英雄。反抗吧！摆脱巫妖王的控制！', `FemaleText_loc5`='聽我說，$n。你一定要反抗巫妖王的控制。他是個只想看到這個世界 - 我們的世界 - 毀滅的怪物。別讓他利用你達成他的目標。你曾經是個英雄，你一定還能再成為英雄的。反抗呀，該死的!反抗他的控制!', `FemaleText_loc7`='Escúchame, $n. Debes luchar contra el control del Rey Exánime. Es un monstruo que quiere ver este mundo, nuestro mundo, convertido en ruinas. No dejes que te utilice para lograr sus metas. Una vez fuiste $gun héroe:una heroína; y puedes volver a serlo. ¡Lucha, maldita sea! ¡Lucha contra su control!' WHERE `ID`=29375;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이젠... 내게 더 남은 시간이 없습니다. 이제 틀렸어요. 날 죽여 주십시오. 그러지 않으면 저들이 우리 둘 다 죽일 겁니다. $n... 실버문을 기억하십시오. 이 세상은 구할 가치가 있는 곳입니다.', `MaleText_loc4`='我……我支撑不住了。这是注定的命运。杀了我吧，$n，否则我们俩都难逃一死。$n……想想银月城。这个世界值得你去拯救。', `MaleText_loc5`='我的...我的時間不夠了。我沒救了，結束我的性命，$n。快動手，要不然他們會殺了我們兩個。$n...毋忘銀月城。這世界是值得拯救的。', `MaleText_loc7`='Ya... ya no me queda tiempo. Estoy acabada. Acaba conmigo, $n. Hazlo o nos matarán a los dos. $n... Recuerda Lunargenta. Vale la pena salvar este mundo.', `FemaleText_loc1`='이젠... 내게 더 남은 시간이 없습니다. 이제 틀렸어요. 날 죽여 주십시오. 그러지 않으면 저들이 우리 둘 다 죽일 겁니다. $n... 실버문을 기억하십시오. 이 세상은 구할 가치가 있는 곳입니다.', `FemaleText_loc4`='我……我支撑不住了。这是注定的命运。杀了我吧，$n，否则我们俩都难逃一死。$n……想想银月城。这个世界值得你去拯救。', `FemaleText_loc5`='我的...我的時間不夠了。我沒救了，結束我的性命，$n。快動手，要不然他們會殺了我們兩個。$n...毋忘銀月城。這世界是值得拯救的。', `FemaleText_loc7`='Ya... ya no me queda tiempo. Estoy acabada. Acaba conmigo, $n. Hazlo o nos matarán a los dos. $n... Recuerda Lunargenta. Vale la pena salvar este mundo.' WHERE `ID`=29376;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 날 죽이세요, $n! 비참한 내 생명을 끊어달란 말입니다!', `MaleText_loc4`='动手吧，$n！让我解脱吧！', `MaleText_loc5`='動手，$n!讓我從苦難中解脫!', `MaleText_loc7`='¡Hazlo, $n! ¡Líbrame de mi miseria!', `FemaleText_loc1`='어서 날 죽이세요, $n! 비참한 내 생명을 끊어달란 말입니다!', `FemaleText_loc4`='动手吧，$n！让我解脱吧！', `FemaleText_loc5`='動手，$n!讓我從苦難中解脫!', `FemaleText_loc7`='¡Hazlo, $n! ¡Líbrame de mi miseria!' WHERE `ID`=29377;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 부상으로 목숨을 잃습니다.', `MaleText_loc4`='%s因为伤势过重而死掉了。', `MaleText_loc5`='%s傷重不治。', `MaleText_loc7`='%s muere a causa de sus heridas.' WHERE `ID`=29378;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 무슨 일이오? 왜 이렇게 오래 걸리지, $n?', `MaleText_loc4`='出了什么状况吗？你怎么去了那么久，$n？', `MaleText_loc5`='那裡發生了什麼事?怎麼花了那麼長的時間，$n?', `MaleText_loc7`='¿Qué está pasando aquí? ¿Por qué estás tardando tanto, $n?' WHERE `ID`=29379;
