UPDATE `locales_broadcast_text` SET `MaleText_loc1`='역병 결정!', `MaleText_loc4`='荒芜水晶！', `MaleText_loc5`='荒疫水晶!', `MaleText_loc7`='¡Cristal de añublo!', `FemaleText_loc1`='역병 결정!', `FemaleText_loc4`='荒芜水晶！', `FemaleText_loc5`='荒疫水晶!', `FemaleText_loc7`='¡Cristal de añublo!' WHERE `ID`=29453;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들의 고통을 한껏 즐겨라, 죽음의 기사여! 네 영혼이 힘을 얻으리라!', `MaleText_loc4`='死亡骑士，好好欣赏他们的痛苦吧！这样的场景足以让你们振奋起来！', `MaleText_loc5`='沉淪在他們的痛苦之中，死亡騎士!讓它鼓舞你的靈魂吧!', `MaleText_loc7`='¡Deléitense en su sufrimiento, caballeros de la Muerte! ¡Dejen que anime sus espíritus!' WHERE `ID`=29454;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='약한 곳을 집중적으로 공격해라!', `MaleText_loc4`='集中攻击弱者！', `MaleText_loc5`='集中攻擊弱點!', `MaleText_loc7`='¡Concentren sus ataques en los débiles!' WHERE `ID`=29455;
