UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도살장에 끌려가는 어린 양이로다...', `MaleText_loc4`='一群待宰的羔羊……', `MaleText_loc5`='待宰的羊們...', `MaleText_loc7`='Corderos al matadero...' WHERE `ID`=29457;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스컬지가 너를 삼키리로다!', `MaleText_loc4`='你注定要死在天灾军团手中！', `MaleText_loc5`='天譴軍團會消滅你們!', `MaleText_loc7`='¡La Plaga te consumirá!' WHERE `ID`=29458;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 버티는가? 포기해라, 기생충아!', `MaleText_loc4`='为什么还要垂死挣扎？投降吧！', `MaleText_loc5`='為什麼要反抗?讓步吧，蛆蟲!', `MaleText_loc7`='¿Por qué luchar contra ello? ¡Ríndete, gusano!' WHERE `ID`=29459;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='레이제크의 새 보호모 보고 싶은 울바르 없어?', `MaleText_loc4`='谁要看雷耶克的新头盔？', `MaleText_loc5`='誰想要看瑞傑克的新頭盔?', `MaleText_loc7`='¿Quién quiere ver el nuevo casco de Rejek?' WHERE `ID`=29460;
