UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나도 보여 줘요!', `MaleText_loc4`='我也想看！', `MaleText_loc5`='也給我看!', `MaleText_loc7`='¡Enseñar a mí también!' WHERE `ID`=29462;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 레이제크가 보여준다!', `MaleText_loc4`='好吧，雷耶克让你们瞧瞧！', `MaleText_loc5`='好，瑞傑克表演!', `MaleText_loc7`='¡Vale, Rejek enseñar!' WHERE `ID`=29463;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어때?', `MaleText_loc4`='怎么样？', `MaleText_loc5`='你覺得如何?', `MaleText_loc7`='¿Qué os parece?' WHERE `ID`=29464;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='금속머리가 레이제크 먹었다! 도망가자!', `MaleText_loc4`='啊，钢盔把雷耶克吃掉了！快跑啊！', `MaleText_loc5`='金屬頭吃了瑞傑克!走開!', `MaleText_loc7`='¡Cabeza de metal comer Rejek! ¡Correr!' WHERE `ID`=29465;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='레이제크 맘에 들어! 보호모 때문에 우리 아가들도 겁먹는다면, 겁쟁이 날름이들은 어떻게 나올지 보고 싶어 못 견디겠어!', `MaleText_loc4`='哦耶！连狗崽子们都害怕这头盔，肯定能把那些胆小的大舌头怪吓得屁滚尿流啊！', `MaleText_loc5`='瑞傑克喜歡!如果頭盔可以嚇跑小狗人，瑞傑克等不及要看看它對大舌頭膽小鬼會有什麼效果了!', `MaleText_loc7`='¡A Rejek gustar! Si casco asustar cachorros, ¡Rejek no poder esperar a ver que hacer a cobardes lenguas-grandes!' WHERE `ID`=29466;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고통받아라, 벌레들아!', `MaleText_loc4`='在痛苦中煎熬吧！', `MaleText_loc5`='受苦吧，害蟲!', `MaleText_loc7`='¡Sufran, insectos!' WHERE `ID`=29467;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 일을 도와주러 나선다니 고맙군, $n. 비록 자네가 우리 실험에 자발적으로 참여하지 않아서 약간 서운하기는 하지만...', `MaleText_loc4`='$n，感谢你给予我们的帮助。但是你拒绝参与我们的实验项目，着实令我感到遗憾。', `MaleText_loc5`='感謝你在這件事中的援助，$n，雖然我還是得承認，你不願意參與我們的實驗稍微有些遺憾...', `MaleText_loc7`='Te agradezco la ayuda en este asunto, $n, aunque debo expresar que lamento un poco que no te presentes $gvoluntario:voluntaria; para nuestros experimentos...' WHERE `ID`=29468;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='퓨트리스 대연금술사님, 전령이 옵니다!', `MaleText_loc4`='普特雷斯大人，是蝙蝠骑士！', `MaleText_loc5`='普崔司大師，有一位蝠騎兵接近!', `MaleText_loc7`='¡Amo Putress, se aproxima un jinete de murciélago!', `FemaleText_loc1`='퓨트리스 대연금술사님, 전령이 와요!', `FemaleText_loc4`='普特雷斯大人，是蝙蝠骑士！', `FemaleText_loc5`='普崔司大師，有一位蝠騎兵接近!', `FemaleText_loc7`='¡Amo Putress, se aproxima un jinete de murciélago!' WHERE `ID`=29469;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전장에서 소식을 가져왔을 것입니다.', `MaleText_loc4`='他一定带来了前线的消息。', `MaleText_loc5`='他一定帶來了原野上的消息。', `MaleText_loc7`='Debe tener noticias del frente.', `FemaleText_loc1`='전장에서 소식을 가져왔을 거예요.', `FemaleText_loc4`='他一定带来了前线的消息。', `FemaleText_loc5`='他一定帶來了原野上的消息。', `FemaleText_loc7`='Debe tener noticias del frente.' WHERE `ID`=29470;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자신이 변하는 것을 느껴봐라!', `MaleText_loc4`='感觉到自己的变化了吧！', `MaleText_loc5`='感受你自身的變化吧!', `MaleText_loc7`='¡Siéntete cambiar!' WHERE `ID`=29471;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 시간이 없다! 남은 병력은 모두 침입자를 공격하라!', `MaleText_loc4`='没有时间了！所有残余部队立刻向入侵者发动攻击！', `MaleText_loc5`='沒有時間了!所有殘餘部隊立刻向入侵者發動攻擊!', `MaleText_loc7`='¡No queda tiempo! Todas las fuerzas en pie: ¡ataquen a los invasores!' WHERE `ID`=29472;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='문이 파괴됐다! 서둘러라! 부대를 편성해, 침입자를 막아라!', `MaleText_loc4`='大门已经被攻破了！快，派兵去挡住那些入侵者！', `MaleText_loc5`='大門已經被攻破了!快，派兵去擋住那些入侵者!', `MaleText_loc7`='¡Han traspasado la compuerta! ¡Rápido, despliega las fuerzas para enfrentar a estos invasores!' WHERE `ID`=29473;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여행자님, 반가워요.', `FemaleText_loc4`='欢迎你，旅行者。', `FemaleText_loc5`='歡迎，旅行者。', `FemaleText_loc7`='Saludos, caminante.' WHERE `ID`=29474;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛의 틈으로 가고 싶습니다.', `MaleText_loc4`='我要去圣光据点。', `MaleText_loc5`='我想要前往聖光止境。', `MaleText_loc7`='Deseo viajar a la Brecha de la Luz.', `FemaleText_loc1`='빛의 틈으로 가고 싶어요.', `FemaleText_loc4`='我要去圣光据点。', `FemaleText_loc5`='我想要前往聖光止境。', `FemaleText_loc7`='Deseo viajar a la Brecha de la Luz.' WHERE `ID`=29475;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이토록 절박한 시기에 도와주신다니 정말 감사해요. 어둠이 위세를 떨치더라도 성스러운 빛이 $n 님을 비추시길 빕니다.', `FemaleText_loc4`='$n，感谢你在危急关头伸出援手。当你面对黑暗时，愿圣光赐予你速度与力量。', `FemaleText_loc5`='在這絕望無助的時刻，多虧了你伸出援手，$n。願聖光賜予你迅捷與力量以面對黑暗。', `FemaleText_loc7`='Gracias por tu ayuda en estos tiempos desesperados, $n. Que la Luz te conceda fuerza y velocidad ante la oscuridad.' WHERE `ID`=29476;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저기, 명예로운 성기사님. 이리 와 보세요.', `FemaleText_loc4`='尊贵的圣骑士，请你过来……', `FemaleText_loc5`='你，受人敬重的聖騎士，請來這裡...', `FemaleText_loc7`='Tú, honorable paladin. Por favor, ven aquí...' WHERE `ID`=29477;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 주교님.', `MaleText_loc4`='是，主教大人。', `MaleText_loc5`='遵命，主教。', `MaleText_loc7`='Sí, Obispo.' WHERE `ID`=29478;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다른 유물도 곧 우리 수비대에게 전달되리라는 소문을 퍼뜨려 주세요.', `FemaleText_loc4`='防御者们很快就能获得另一件古器，我要你将这个消息传播开来。', `FemaleText_loc5`='把消息傳出去，另外一個神器馬上就會帶到我們護衛者的手上。', `FemaleText_loc7`='Extiende la noticia de que pronto le llegará otro artefacto a nuestros defensores.' WHERE `ID`=29479;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그리고 $g형제:자매;님, 매복한 스컬지를 조심하세요.', `FemaleText_loc4`='当心天灾军团的袭击。', `FemaleText_loc5`='還有，$g兄弟:姐妹;，小心天譴軍團的埋伏。', `FemaleText_loc7`='Y $ghermano:hermana;, ten cuidado con las emboscadas de la Plaga.' WHERE `ID`=29480;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 주교님. 그리하겠습니다, 주교님.', `MaleText_loc4`='遵命，大人。', `MaleText_loc5`='遵命，領主。我會的，領主。', `MaleText_loc7`='Sí, señor. Lo hare, señor.' WHERE `ID`=29481;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제 주방에 잘 오셨어요! 저희는 여기 달라란에서 제일가는 음식을 만든답니다.', `FemaleText_loc4`='欢迎来到我的厨房！我们在这里为达拉然的居民烹制最美味的食物。', `FemaleText_loc5`='歡迎光臨我的廚房!我們準備了不少達拉然最棒的食物在這裡。', `FemaleText_loc7`='¡$gBienvenido:Bienvenida; a mi cocina! Aquí preparamos algunos de los mejores platos de Dalaran.' WHERE `ID`=29482;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요리를 배우러 왔습니다.', `MaleText_loc4`='我是来学习烹饪的。', `MaleText_loc5`='我是來接受烹飪訓練的。', `MaleText_loc7`='Estoy aquí para recibir instrucción en cocina.', `FemaleText_loc1`='요리를 배우러 왔어요.', `FemaleText_loc4`='我是来学习烹饪的。', `FemaleText_loc5`='我是來接受烹飪訓練的。', `FemaleText_loc7`='Estoy aquí para recibir instrucción en cocina.' WHERE `ID`=29483;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하신가, 친구.', `MaleText_loc4`='你好啊，朋友。', `MaleText_loc5`='你好，朋友。', `MaleText_loc7`='Buenos días, colega.' WHERE `ID`=29484;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 저를 빛의 틈으로 데려다 주실 수 있다고 들었습니다만...', `MaleText_loc4`='听说你能送我去圣光据点……', `MaleText_loc5`='我聽說你可以帶我前往聖光止境...', `MaleText_loc7`='Me han dicho que tú me puedes llevar a la Brecha de la Luz...', `FemaleText_loc1`='당신이 저를 빛의 틈으로 데려다 주실 수 있다고 들었는데요...', `FemaleText_loc4`='听说你能送我去圣光据点……', `FemaleText_loc5`='我聽說你可以帶我前往聖光止境...', `FemaleText_loc7`='Me han dicho que tú me puedes llevar a la Brecha de la Luz...' WHERE `ID`=29485;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날름이들을 잘 처리하길 바랄게. 날름이들 좀 사라질 때도 됐어.', `MaleText_loc4`='希望你好好地教训一下大舌头怪。他们该滚蛋了！', `MaleText_loc5`='希望你跟大舌頭相處愉快。該是他們離開的時候了。', `MaleText_loc7`='Espero que les des su merecido a los lenguas-grandes. Ser hora de que ellos irse.' WHERE `ID`=29486;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='번개불꽃 안식처에서 아직도 엄청나게 싸워.$B$B너 시간 좀 내어 도와줄 수 있을 것 같은데?', `MaleText_loc4`='灵鳍湾的战斗仍在继续。$B$B你能抽空去那里帮帮忙吗？', `MaleText_loc5`='大戰依舊在炫觸避風港持續著。$B$B或許你可以找時間去幫忙?', `MaleText_loc7`='Gran batalla tener aún lugar en Retiro Pavesa.$B$B¿Quizá tú sacar tiempo para ayudar en algún momento?' WHERE `ID`=29487;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요, $c님! 스톰윈드 항구는 꽤 볼만한 곳이죠. 하늘에서 보면 더 장관이랍니다. 스톰윈드 항구를 하늘에서 내려다보실 생각 없으십니까?', `MaleText_loc4`='你好，$c！暴风城港口的景色别具风格。从空中俯瞰的效果更佳。你要鸟瞰一下整座港口吗？', `MaleText_loc5`='你好，$c!暴風港是一處很顯著的地方。即使從空中都看得一清二楚。你想像隻鳥一樣來俯瞰這個海港嗎?', `MaleText_loc7`='¡Saludos, $c! El Puerto de Ventormenta es digno de ver. Es incluso mejor verlo desde el aire. ¿Te gustaría obtener una vista de pájaro del puerto?' WHERE `ID`=29488;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드 항구 주변을 한 바퀴 돌면서 구경했으면 좋겠습니다.', `MaleText_loc4`='我要绕暴风城港口游览一圈。', `MaleText_loc5`='我想要繞著暴風港飛一趟。', `MaleText_loc7`='Me gustaría volar alrededor del Puerto de Ventormenta.', `FemaleText_loc1`='스톰윈드 항구 주변을 한 바퀴 돌면서 구경했으면 좋겠네요.', `FemaleText_loc4`='我要绕暴风城港口游览一圈。', `FemaleText_loc5`='我想要繞著暴風港飛一趟。', `FemaleText_loc7`='Me gustaría volar alrededor del Puerto de Ventormenta.' WHERE `ID`=29489;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신에게 차원문을 이해할만한 정신적 능력이 있는 것 같지는 않군요.$B$B그래도 제 뒤에 있는 수정을 사용하면 수정노래 숲의 달라란 아래에 있는 폐허로 순간이동할 수 있으니 알아두세요.', `FemaleText_loc4`='凭你的智慧，恐怕无法掌握传送魔法的奥秘。$B$B但是你可以使用我身后的水晶，它能将你传送到达拉然下方，位于晶歌森林的废墟。', `FemaleText_loc5`='我不相信你的心智敏銳到可以理解傳送魔法的本質。$B$B不過，你可以使用我前面的水晶來傳送至水晶之歌森林中，位於達拉然底下的廢墟。', `FemaleText_loc7`='No creo que poseas la agudeza mental necesaria para comprender la naturaleza de la magia de portales.$B$BSin embargo, puedes usar el cristal tras de mí para teletransportarte a las ruinas que se encuentran bajo Dalaran en el Bosque Canto de Cristal.' WHERE `ID`=29490;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마법사인 당신은 바로 이곳으로 돌아오는 차원문을 열 수 있도록 선택받은 존재에요. 준비가 됐다면 가르쳐 드리지요.$B$B그리고 제 뒤에 있는 수정을 사용하면 언제라도 달라란 아래에 있는 수정노래 숲의 폐허로 순간이동할 수 있음을 기억해 두세요.', `FemaleText_loc4`='身为一名法师，你拥有开启传送门，将自己传送回这里的能力。如果你愿意的话，我可以将传送法术传送给你。$B$B你也可以使用我身后的水晶，传送到达拉然下方的晶歌森林。', `FemaleText_loc5`='身為一位法師，你屬於卓越團體中的一員，能夠召喚一道傳送門將你傳回這個特別的地方。如果你準備好了，我就可以教導你。$B$B記住，你永遠都可以使用我前方的水晶來傳送至水晶之歌森林中，位於達拉然下方的廢墟。', `FemaleText_loc7`='Como mago, formas parte de un selecto grupo que puede invocar un portal para transportarte de vuelta a este lugar. Puedo enseñarte a hacerlo, si estas $gpreparado:preparada;.$B$BY recuerda que siempre puedes usar el cristal que se encuentra detrás de mí para teletransportarte a las ruinas que hay bajo Dalaran, en el Bosque Canto de Cristal.' WHERE `ID`=29491;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간 있나? 수네가 좋은 노래를 가르쳐 주겠다!', `MaleText_loc4`='你有空吗？索乌尼可以教你好听的曲子！', `MaleText_loc5`='你有時間?蘇-睨教你好聽的歌!', `MaleText_loc7`='¿Tienes un momento? ¡Soo-nata enseñarte bonita canción!' WHERE `ID`=29492;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, $c님.', `MaleText_loc4`='你好，$c。', `MaleText_loc5`='你好，$c。', `MaleText_loc7`='Saludos, $c.', `FemaleText_loc1`='안녕하세요, $c님.', `FemaleText_loc4`='你好，$c。', `FemaleText_loc5`='你好，$c。', `FemaleText_loc7`='Saludos, $c.' WHERE `ID`=29493;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달라란으로 순간이동할 준비가 되었습니다.', `MaleText_loc4`='我要传送到达拉然。', `MaleText_loc5`='我準備好要被傳送至達拉然了。', `MaleText_loc7`='Estoy preparado para teletransportarme a Dalaran.', `FemaleText_loc1`='달라란으로 순간이동할 준비가 되었어요.', `FemaleText_loc4`='我要传送到达拉然。', `FemaleText_loc5`='我準備好要被傳送至達拉然了。', `FemaleText_loc7`='Estoy preparada para teletransportarme a Dalaran.' WHERE `ID`=29494;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 미용실에 어서 와, $r. 머리 자르러 왔어? 염색? 그게 아니면, 뭘까? $B$B수염도 다듬어 줄 수 있고, 귀도 뚫고 나이트 엘프 문신에 색도 넣고 드레나이 뿔이나 촉수 모양도 바꿔줄 수 있다고!$B$B여기 앉으면 바로 전문가의 손길을 느끼게 해 주지. 동전 몇 개만 내 봐. 완전히 딴 사람이 되어 매력이 흐르다 못해 철철 넘칠 테니까...', `MaleText_loc4`='朋友，欢迎来到我的理发店！你是想理发？还是染发啊？要不试试别的项目？$B$B我们提供各种修面、打洞、绘制暗夜精灵纹身等服务，甚至能为德莱尼人修整犄角和卷须！$B$B请坐吧，我们这就为你服务！只要花上几个子儿，你就能变得魅力四射……', `MaleText_loc5`='朋友，歡迎來到美容沙龍!想要剪頭髮嗎?還是染髮?或者是來點其它的呢?$B$B我們有修剪鬍鬚，刺環顯示，夜精靈刺青染印，甚至還能重塑德萊尼牴角和觸鬚呢!$B$B找個位置坐下來，我們馬上就可以開始了。只要花一些錢，你就可以擁有一個嶄新，更具吸引力的自己...', `MaleText_loc7`='¡$gBienvenido:Bienvenida; a la barbería, colega! ¿Has venido a cortarte el pelo? ¿A teñirte? ¿Quizá algo distinto?$B$BPodemos cepillar el vello facial, poner pendientes, hacer tatuajes de elfo de la noche e incluso dar forma a los cuernos y zarcillos de los draenei.$B$BSiéntate y nos pondremos manos a la obra. Solo unas pocas monedas y pronto encontrarás al nuevo y más atractivo tú...', `FemaleText_loc1`='저희 미용실을 찾아주셔서 감사합니다, $n 님. 머리 자르러 오셨나요? 염색? 그게 아니면, 뭘까요? $B$B수염도 다듬어 드릴 수 있고, 귀도 뚫고 나이트 엘프 문신에 색도 넣고 드레나이 뿔이나 촉수 모양도 바꿔 드릴 수 있어요!$B$B여기 앉으시면 바로 전문가의 손길을 느끼게 해 드릴 게요. 동전 몇 개면 충분해요. 완전히 딴 사람이 되어 매력이 흐르다 못해 넘칠 거예요...', `FemaleText_loc4`='朋友，欢迎来到我的理发店！你是想理发？还是染发啊？要不试试别的项目？$B$B我们提供各种修面、打洞、绘制暗夜精灵纹身等服务，甚至能为德莱尼人修整犄角和卷须！$B$B请坐吧，我们这就为你服务！只要花上几个子儿，你就能变得魅力四射……', `FemaleText_loc5`='朋友，歡迎來到美容沙龍!想要剪頭髮嗎?還是染髮?或者是來點其它的呢?$B$B我們有修剪鬍鬚，刺環顯示，夜精靈刺青染印，甚至還能重塑德萊尼牴角和觸鬚呢!$B$B找個位置坐下來，我們馬上就可以開始了。只要花一些錢，你就可以擁有一個嶄新，更具吸引力的自己...', `FemaleText_loc7`='¡$gBienvenido:Bienvenida; a la barbería, colega! ¿Has venido a cortarte el pelo? ¿A teñirte? ¿Quizá algo distinto?$B$BPodemos cepillar el vello facial, poner pendientes, hacer tatuajes de elfo de la noche e incluso dar forma a los cuernos y zarcillos de los draenei.$B$BSiéntate y nos pondremos manos a la obra. Solo unas pocas monedas y pronto encontrarás al nuevo y más atractivo tú...' WHERE `ID`=29495;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 미용실에 어서 와, $r. 머리 자르러 왔어? 염색? 그게 아니면, 뭘까? $B$B수염도 다듬어 줄 수 있고, 귀도 뚫고 나이트 엘프 문신에 색도 넣고 언데드 뼈대도 손볼 수 있다고!$B$B여기 앉으면 바로 전문가의 손길을 느끼게 해 주지. 동전 몇 개만 내 봐. 완전히 딴 사람이 되어 매력이 흐르다 못해 철철 넘칠 테니까...', `MaleText_loc4`='朋友，欢迎来到我的理发店！你是想理发？还是染发啊？要不试试别的项目？$B$B我们提供各种修面、打洞、獠牙和犄角整形等服务，甚至能为亡灵整容！$B$B请坐吧，我们这就为你服务！只要花上几个子儿，你就能变得魅力四射……', `MaleText_loc5`='朋友，歡迎來到美容沙龍!想要剪頭髮嗎?還是染髮?或者是來點其它的呢?$B$B我們有修剪鬍鬚，刺環顯示，重塑獠牙和牴角，甚至還能修改不死族的特徵呢!$B$B找個位置坐下來，我們馬上就可以開始了。只要花一些錢，你就可以擁有一個嶄新，更具吸引力的自己...', `MaleText_loc7`='¡$gBienvenido:Bienvenida; a la barbería, colega! ¿Has venido a cortarte el pelo? ¿A teñirte? ¿Quizá algo distinto?$B$BPodemos cepillar el vello facial, poner pendientes, dar forma a colmillos y cuernos, ¡e incluso modificar las características de los no-muertos!$B$BSiéntate y nos pondremos manos a la obra. Solo unas pocas monedas y pronto encontrarás al nuevo y más atractivo tú...', `FemaleText_loc1`='저희 미용실을 찾아주셔서 감사합니다, $r님. 머리 자르러 오셨나요? 염색? 그게 아니면, 뭘까요? $B$B수염도 다듬어 드릴 수 있고, 귀도 뚫고 나이트 엘프 문신에 색도 넣고 언데드 뼈대도 손봐 드릴 수 있어요!$B$B여기 앉으시면 바로 전문가의 손길을 느끼게 해 드릴 게요. 동전 몇 개면 충분해요. 완전히 딴 사람이 되어 매력이 흐르다 못해 넘칠 거예요...', `FemaleText_loc4`='朋友，欢迎来到我的理发店！你是想理发？还是染发啊？要不试试别的项目？$B$B我们提供各种修面、打洞、獠牙和犄角整形等服务，甚至能为亡灵整容！$B$B请坐吧，我们这就为你服务！只要花上几个子儿，你就能变得魅力四射……', `FemaleText_loc5`='朋友，歡迎來到美容沙龍!想要剪頭髮嗎?還是染髮?或者是來點其它的呢?$B$B我們有修剪鬍鬚，刺環顯示，重塑獠牙和牴角，甚至還能修改不死族的特徵呢!$B$B找個位置坐下來，我們馬上就可以開始了。只要花一些錢，你就可以擁有一個嶄新，更具吸引力的自己...', `FemaleText_loc7`='¡$gBienvenido:Bienvenida; a la barbería, colega! ¿Has venido a cortarte el pelo? ¿A teñirte? ¿Quizá algo distinto?$B$BPodemos cepillar el vello facial, poner pendientes, dar forma a colmillos y cuernos, ¡e incluso modificar las características de los no-muertos!$B$BSiéntate y nos pondremos manos a la obra. Solo unas pocas monedas y pronto encontrarás al nuevo y más atractivo tú...' WHERE `ID`=29498;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 잔 걸치자고!', `MaleText_loc4`='来喝一杯！', `MaleText_loc5`='來個一品脫吧!', `MaleText_loc7`='¡Coge una pinta!' WHERE `ID`=29499;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 유명하다는 독한 맥주를 가지러 왔습니다. 좀 얻을 수 있겠습니까?', `MaleText_loc4`='我是来买那种有名的烈酒的。还有存货吗？', `MaleText_loc5`='我是來帶幾杯你享負盛名的烈啤酒。還有多的嗎?', `MaleText_loc7`='Me han mandado que consiga un poco de tu famosa cerveza fuerte. ¿Te sobra algo?', `FemaleText_loc1`='그 유명하다는 독한 맥주를 가지러 왔어요. 주실 수 있으세요?', `FemaleText_loc4`='我是来买那种有名的烈酒的。还有存货吗？', `FemaleText_loc5`='我是來帶幾杯你享負盛名的烈啤酒。還有多的嗎?', `FemaleText_loc7`='Me han mandado que consiga un poco de tu famosa cerveza fuerte. ¿Te sobra algo?' WHERE `ID`=29500;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나한테 맥주가 남았단 얘기를 누가 했는지는 몰라도, 아무튼 이거 받고 입 다물라고. 알았지? 야영지 전체에 뿌릴 만큼은 없으니까 말이야.', `MaleText_loc4`='不管是谁告诉你我这里还有存货，请你务必替我保密。我可没法满足整座营地的需求。', `MaleText_loc5`='不知道是誰跟你說我這還有多餘的啤酒，不過你不要跟別人說好嗎?我手上擁有的數量不足以提供整個營地。', `MaleText_loc7`='No sé quién te ha dicho que me queda algo de cerveza, pero no se lo cuentes a nadie, ¿vale? No tengo suficiente para todo el campamento.' WHERE `ID`=29501;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살아있는 것들은 모두 없애라!', `MaleText_loc4`='消灭所有活人，仆从们！', `MaleText_loc5`='毀掉所有活物，爪牙們!', `MaleText_loc7`='¡Aniquilad a los vivos, esbirros!' WHERE `ID`=29502;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제, 끝이다!', `MaleText_loc4`='一切都结束了！', `MaleText_loc5`='這就是末日!', `MaleText_loc7`='¡Este es el fin!' WHERE `ID`=29503;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='붉은십자군의 짓밟힌 땅은 역사에 본보기로 남으리라!', `MaleText_loc4`='血色领地的沦陷将成为一个血淋淋的教训！', `MaleText_loc5`='血色領區的屠戮將會成為血淋淋的教訓!', `MaleText_loc7`='¡El saqueo del Enclave Escarlata quedará para la historia!' WHERE `ID`=29504;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달아날 곳은 없다...', `MaleText_loc4`='你们无路可逃……', `MaleText_loc5`='你們無路可逃...', `MaleText_loc7`='No hay escapatoria…' WHERE `ID`=29505;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳을 쑥대밭으로 만들어라. 감히 스컬지에 맞서는 무엄한 놈들에게, 뼈저린 교훈을 안겨 줘라!', `MaleText_loc4`='彻底摧毁这里，给那些胆敢反抗天灾军团的人留下一个教训！', `MaleText_loc5`='就讓這個地方的毀滅來昭告天下，這就是和天譴軍作對的下場!', `MaleText_loc7`='¡Que la destrucción de este lugar sirva de lección para los que osan oponerse a la Plaga!' WHERE `ID`=29506;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 땅에서 언데드를 쓸어버릴 수 있으리라 생각했느냐? 스컬지의 진정한 힘을 뼈저리게 느껴보아라!', `MaleText_loc4`='就凭你们，也想将亡灵逐出这片土地？见识天灾军团真正的力量，绝望吧！', `MaleText_loc5`='你以為真能把不死族從世上上根除嗎?見識一下天譴軍真正的力量，見識一下什麼是絕望!', `MaleText_loc7`='¿Pensabas que podías borrar a los no-muertos de estas tierras? ¡Prueba el verdadero poder de la Plaga y desespera!' WHERE `ID`=29507;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 놈도 살려두지 마라!', `MaleText_loc4`='不留活口！', `MaleText_loc5`='不留活口!', `MaleText_loc7`='¡No dejéis supervivientes!' WHERE `ID`=29508;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='머지않아, 너희도 스컬지의 일원이 되리라.', `MaleText_loc4`='很快，你就会成为天灾军团的一员。', `MaleText_loc5`='你馬上就會加入天譴軍團了。', `MaleText_loc7`='Pronto pertenecerán a la Plaga.' WHERE `ID`=29509;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='붉은십자군이여, 너희의 빛은 어디 있느냐?', `MaleText_loc4`='十字军，你们所信仰的圣光在哪儿呢？', `MaleText_loc5`='你們的聖光在哪裡，十字軍?', `MaleText_loc7`='¿Pues dónde está su Luz, Cruzados?' WHERE `ID`=29510;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왕 앞에 무릎을 꿇어라!', `MaleText_loc4`='向你们的王致敬！', `MaleText_loc5`='快對你們的王行禮!', `MaleText_loc7`='¡Inclínense ante su rey!' WHERE `ID`=29511;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛은 너희를 버렸다!', `MaleText_loc4`='你被圣光抛弃了！', `MaleText_loc5`='聖光已經遺棄了你們!', `MaleText_loc7`='¡La Luz los ha abandonado!' WHERE `ID`=29512;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛이란 없다. 오직 어둠뿐이다!', `MaleText_loc4`='圣光根本就不存在。只有黑暗长存！', `MaleText_loc5`='聖光不再。只有黑暗長存!', `MaleText_loc7`='No existe la Luz. ¡Sólo la oscuridad!' WHERE `ID`=29513;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게 오라, 십자군이여. 새로운 삶을 주겠다!', `MaleText_loc4`='来呀，十字军。接受改造吧！', `MaleText_loc5`='過來，十字軍。我會讓你們獲得新生!', `MaleText_loc7`='Vengan a mí, Cruzados. ¡Los haré de nuevo!' WHERE `ID`=29514;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 끔찍한 피조물 앞에서 몸서리쳐라!', `MaleText_loc4`='在我的恐怖造物面前颤抖吧！', `MaleText_loc5`='在我恐怖的作品面前畏縮顫抖吧!', `MaleText_loc7`='¡Escóndanse de mis horribles creaciones!' WHERE `ID`=29515;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잔치를 벌여라! 저놈들을 마음껏 가지고 놀아라!', `MaleText_loc4`='我的孩子，尽情地享受吧！', `MaleText_loc5`='我的孩子，盡情地享受新鮮的血肉大餐吧!', `MaleText_loc7`='¡Festejen, hijos míos! ¡Devoren la carne de los vivos!' WHERE `ID`=29516;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무의미한 저항은 그만두고, 내게 영혼을 바쳐라!', `MaleText_loc4`='放下武器，奉上你们的灵魂！', `MaleText_loc5`='放下武器，奉上你們的靈魂!', `MaleText_loc7`='¡Depongan las armas y entreguen sus almas!' WHERE `ID`=29517;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원심력 피조물이 $3486W개 남았도다. 그 피조물을 찾아내어 파괴해야 바로스 클라우드스트라이더의 보호막을 못 쓰게 할 수 있노라. 피조물은 마력의 눈 중간쯤에 있는 가속의 고리에서 찾을 수 있으리라.', `MaleText_loc4`='还有$3486W个离心构造体。我们必须摧毁它们，才能破除瓦尔洛斯·云击的护盾。你可以在位于魔环中层的加速之环找到那些构造体。', `MaleText_loc5`='還剩下$3486W具離心傀儡。我們一定得找到並摧毀它們，好讓瓦羅斯·雲行者的保護護盾失去作用。傀儡應該就位於前往奧核之眼的半路上，就在加速之環上。', `MaleText_loc7`='Quedan $3486W ensamblajes de centrifugadora. Debemos encontrar el modo de destruirlos para desactivar el escudo protector de Varos Zancanubes. Los ensamblajes deberían estar a medio camino hacia la cima de El Oculus, en el Anillo de Aceleración.' WHERE `ID`=29518;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 원심력 피조물이 하나 남았도다. 그 피조물을 찾아내어 파괴해야 바로스 클라우드스트라이더의 보호막을 못 쓰게 할 수 있노라. 피조물은 마력의 눈 중간쯤에 있는 가속의 고리에서 찾을 수 있으리라.', `MaleText_loc4`='只剩1个离心构造体了。我们必须摧毁它们，才能破除瓦尔洛斯·云击的护盾。你可以在位于魔环中层的加速之环找到那些构造体。', `MaleText_loc5`='還剩下一具離心傀儡。我們一定得找到並摧毀它，好讓瓦羅斯·雲行者的保護護盾失去作用。傀儡應該就位於前往奧核之眼的途中，就在加速之環上。', `MaleText_loc7`='Queda un ensamblaje de centrifugadora. Debemos encontrar el modo de destruirlo para desactivar el escudo protector de Varos Zancanubes. El ensamblaje debería estar a medio camino hacia la cima de El Oculus, en el Anillo de Aceleración.' WHERE `ID`=29519;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보호막이 사라졌구나. 이제 바로스는 약해졌으리라! 바로스를 처치하고 하늘빛 고리 수호자들을 도망가게 하면 상층 고리에 접근할 수 있도다. 바로스는 떠다니는 단 위에 있는데, 그 장소는 마력의 눈 중간쯤에 있는 가속의 고리에서 찾을 수 있으리라.', `MaleText_loc4`='破除护盾，削弱瓦尔洛斯的防御力量！击败他，碧蓝魔环卫士就会消失，这样我们就能继续往上层前进了。前往位于魔环中层的加速之环，在浮动平台上找到瓦尔洛斯。', `MaleText_loc5`='護盾已經關閉了;瓦羅斯無所遁形了!打敗他應該就可以解散蒼藍之環守護者，並讓我們進入上面一帶。瓦羅斯就位於通往奧核之眼途中，加速之環裡的一座飄浮平臺上。', `MaleText_loc7`='¡El escudo está desconectado, Varos es vulnerable! Al vencerle, los guardianes del anillo azur deberían dispersarse y permitirnos acceder a los anillos superiores. Varos se encuentra sobre una plataforma flotante a medio camino hacia la cima del Oculus, en el Anillo de Aceleración.' WHERE `ID`=29520;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법사 군주 우롬이 다음 목표이다. 우롬은 변환의 고리에 있는 떠다니는 단 어딘가에 숨어 있는데, 아마 마력의 눈 꼭대기에 가까이 있을 것이로다. 조심하라, 우롬은 강력한 요술사인데다 혼자 있지는 않으리라.', `MaleText_loc4`='下一个目标是法师领主伊洛姆。前往靠近魔环顶层的转化之环，在浮动平台上找到伊洛姆。他正在引导蓝色的魔枢能量旋。当心，这位强大的咒术师能召唤仆从帮他作战。', `MaleText_loc5`='法師領主厄隆是我們下一個目標。他就躲藏在轉化之環的飄浮平臺上，接近奧核之眼的頂端。當心，厄隆是一個強大的咒術師，他可能不是獨自一人。', `MaleText_loc7`='El Señor de la magia Urom es nuestro siguiente objetivo. Se esconde en una de las plataformas flotantes del Anillo de Transmutación, cerca de la cima del Oculus. Mucho ojo: Urom es un conjurador muy poderoso y puede que no esté solo.' WHERE `ID`=29521;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 마력의 눈을 조종하면서 우리를 방해하는 것은 지맥 수호자 에레고스뿐이리라. 에레고스는 마력의 눈 가장 꼭대기에 있는 정렬의 고리 위를 날아다닌다. 에레고스는 믿을 수 없을 만큼 강한 놈이니, 싸움은 내게 맡기고 뒤에 숨어 있거라.', `MaleText_loc4`='只要除掉魔网守护者埃雷苟斯，我们就能控制魔环。他就在位于魔环顶层的校准之环上方盘旋。埃雷苟斯拥有难以想象的力量。开战之后你待在我背上吧，让我来对付他。', `MaleText_loc5`='地脈守護者伊瑞茍斯是如今擋在我們和掌控奧核之眼之間的唯一因素了。他就飛翔在位於奧核之眼最頂端的化合之環上。伊瑞茍斯的力量驚人的強大;當我們與他交戰時，待在我的背後，讓我跟他戰鬥就好了。', `MaleText_loc7`='El Guardián-Ley Eregos es lo único que se interpone entre nosotros y el control del Oculus. Él sobrevuela el Anillo de Alineación, en lo más alto del Oculus. El poder de Eregos es increíble, quédate sobre mí cuando nos enfrentemos a él y deja que luche yo.' WHERE `ID`=29522;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 마력의 눈을 말리고스의 세력에서 빼내어 우리가 지배할 수 있게 되었다. 작은 존재여, 그대가 더 가벼워진 것이 아닐 터인데, 저 창공을 날고 싶어 날개가 근질거릴 지경이로다.', `MaleText_loc4`='我们终于从玛里苟斯手中夺得了魔环的控制权。小家伙，你还不能松懈。我渴望在广阔的天空舒展双翼。', `MaleText_loc5`='我們從瑪里苟斯的軍隊手中奪得了奧核之眼的掌控權了。你並沒有變得比較輕鬆，小東西。我的翅膀渴望展翅飛翔。', `MaleText_loc7`='Hemos arrebatado el control del Oculus a los ejércitos de Malygos. No estás perdiendo peso, $gpequeño:pequeña;. Mis alas ansían el cielo abierto.' WHERE `ID`=29523;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='', `MaleText_loc4`='', `MaleText_loc5`='', `MaleText_loc7`='' WHERE `ID`=29524;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛의 틈으로 가고 싶습니다.', `MaleText_loc4`='我要去圣光据点。', `MaleText_loc5`='我想要前往聖光止境。', `MaleText_loc7`='Deseo viajar a la Brecha de la Luz.', `FemaleText_loc1`='빛의 틈으로 가고 싶어요.', `FemaleText_loc4`='我要去圣光据点。', `FemaleText_loc5`='我想要前往聖光止境。', `FemaleText_loc7`='Deseo viajar a la Brecha de la Luz.' WHERE `ID`=29525;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 섬길 때가 되었구나.', `MaleText_loc4`='你或许也可以为我效劳。', `MaleText_loc5`='你還不夠資格服侍我。', `MaleText_loc7`='Puede que aún me sirvas.' WHERE `ID`=29526;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시끄럽구나... 물에 빠져 죽으면 입만 동동 뜰 녀석 같으니! 가서 싸우기나 해!', `MaleText_loc4`='行了，别再估计什么形势不形势的了，蠢货！赶紧给我加入战斗！', `MaleText_loc5`='夠了，別再估計什麼形勢了，你這蠢貨!趕緊給我加入戰鬥!', `MaleText_loc7`='¿Necesitas evaluar un poco más la situación? ¡Idiota! ¡Sólo muévete y pelea! ' WHERE `ID`=29527;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스카발드, 이 무능한 놈 같으니! 돌아와라. 도움이 좀 돼 보란 말이다!', `MaleText_loc4`='斯卡瓦尔德，你这无能的废物！滚回来，让我把你变得更有用一点！', `MaleText_loc5`='史卡沃，你這個無能的懶蟲!滾回去做好你的本份!', `MaleText_loc7`='¡Skarvald, holgazán incompetente! ¡Vuelve y haz algo útil!' WHERE `ID`=29528;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곧... 다시... 보자.', `MaleText_loc4`='再……见……', `MaleText_loc5`='再...見...', `MaleText_loc7`='Nos... vemos... pronto.' WHERE `ID`=29529;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이보다... 더한 명예는... 없으리라...', `MaleText_loc4`='真是……无上的……荣耀。', `MaleText_loc5`='真是...無上的...榮耀。', `MaleText_loc7`='No hay... mayor... gloria.' WHERE `ID`=29530;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달론! 네 솜씨가 얼마나 좋은지 한번 보자!', `MaleText_loc4`='达尔隆！你有没有勇气和我一起上啊！', `MaleText_loc5`='達隆恩!鼓起勇氣跟我一起攻擊!', `MaleText_loc7`='¡Dalronn! ¡Ármate de coraje y ataca conmigo!' WHERE `ID`=29531;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얄겐 올트!', `MaleText_loc4`='Jarggn olkt！', `MaleText_loc5`='(維酷語)可悲的蛆蟲!', `MaleText_loc7`='¡Jarggn olkt!' WHERE `ID`=29532;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 무슨 놈의 강령술사가 죽음 앞에 무릎을 꿇느냐? 무능한 녀석 같으니!', `MaleText_loc4`='呸！通灵师岂有死了就放弃的道理？你这没用的东西！', `MaleText_loc5`='哼!哪門子的死靈法師會讓死亡擋在他的面前?我就知道你是個沒用的傢伙!', `MaleText_loc7`='¡Ah! ¿Pero qué clase de Nigromante deja que la muerte lo detenga? ¡Yo sabía que eras inútil!' WHERE `ID`=29533;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직... 끝나지... 않았다.', `MaleText_loc4`='没……完……呢。', `MaleText_loc5`='沒...完...呢。', `MaleText_loc7`='No... es... el fin.' WHERE `ID`=29534;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전사다운... 죽음을.', `MaleText_loc4`='一个战士的……死。', `MaleText_loc5`='一個戰士的死亡。', `MaleText_loc7`='Una muerte de un guerrero.' WHERE `ID`=29535;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로스 클라우드스트라이더와 그 고리 수호자들은 두 번째 고리를 보호하지요. 당신이 탄 비룡은 고리 수호자들을 쉽게 상대할 수 있지만, 바로스는 마력의 눈 그 자체의 힘으로 만들어져 깨뜨릴 수 없는 방어막 뒤에 숨어 있거든요. 원심력 피조물 10개가 고리에서 나오는 보호막과 위에 떠다니는 단에서부터 동력을 공급해요. 그 원심력 피조물을 파괴해야 바로스를 공격할 수 있어요.', `MaleText_loc4`='瓦尔洛斯·云击和魔环卫士守护着第二环。你召唤的幼龙足以对付魔环卫士，但是瓦尔洛斯利用魔环自身的能量，撑起了一面难以穿透的护盾。10个离心构造体不断地为护盾提供能量，它们就分布在我们头顶的环面和平台上。只有摧毁它们，才有可能伤害到瓦尔洛斯。', `MaleText_loc5`='瓦羅斯·雲行者與他的守護者保衛著第二道環。你們的飛龍雖然比那些守護者強上許多，但是瓦羅斯·雲行者卻躲在無法擊穿的護盾後面。這護盾是奧核之眼本身的能量所製造的，由位在那一環以及上方平台的十具離心傀儡提供護盾能量。必須先摧毀它們，才能傷害到瓦羅斯。', `MaleText_loc7`='Varos Zancanubes y sus guardianes del anillo protegen el segundo anillo. Tus dracos pueden apañárselas contra los guardianes del anillo, pero Varos se encuentra tras un escudo impenetrable creado con la energía del propio Oculus. Diez ensamblajes de centrifugadora dan potencia al escudo desde el anillo y las plataformas de encima. Destrúyelos y Varos será vulnerable.', `FemaleText_loc1`='바로스 클라우드스트라이더와 그 고리 수호자들은 두 번째 고리를 보호하지요. 그대의 비룡은 고리 수호자들을 쉽게 상대할 수 있지만, 바로스는 마력의 눈 그 자체의 힘으로 만들어져 깨뜨릴 수 없는 방어막 뒤에 숨어 있어요. 원심력 피조물 10개가 고리에서 나오는 보호막과 위에 떠다니는 단에 동력을 공급해요. 그 원심력 피조물들을 파괴해야 바로스를 공격할 수 있어요.', `FemaleText_loc4`='瓦尔洛斯·云击和魔环卫士守护着第二环。你召唤的幼龙足以对付魔环卫士，但是瓦尔洛斯利用魔环自身的能量，撑起了一面难以穿透的护盾。10个离心构造体不断地为护盾提供能量，它们就分布在我们头顶的环面和平台上。只有摧毁它们，才有可能伤害到瓦尔洛斯。', `FemaleText_loc5`='瓦羅斯·雲行者與他的守護者保衛著第二道環。你們的飛龍雖然比那些守護者強上許多，但是瓦羅斯·雲行者卻躲在無法擊穿的護盾後面。這護盾是奧核之眼本身的能量所製造的，由位在那一環以及上方平台的十具離心傀儡提供護盾能量。必須先摧毀它們，才能傷害到瓦羅斯。', `FemaleText_loc7`='Varos Zancanubes y sus guardianes del anillo protegen el segundo anillo. Tus dracos pueden apañárselas contra los guardianes del anillo, pero Varos se encuentra tras un escudo impenetrable creado con la energía del propio Oculus. Diez ensamblajes de centrifugadora dan potencia al escudo desde el anillo y las plataformas de encima. Destrúyelos y Varos será vulnerable.' WHERE `ID`=29536;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='교활한 마법사 군주 우롬이 세 번째 고리를 보호하고 있습니다. 놈은 무방비 상태로 혼자 있는 것처럼 보이지만, 겉보기만으로 속아 넘어가서는 안 됩니다! 우롬은 실체 없는 생물 군단을 지휘하는 강력한 요술사입니다. 저 위에서 그를 찾아보십시오.', `MaleText_loc4`='法师领主伊洛姆守护着第三环。他独自在平台上踱步，一副毫无防备的模样，你千万别被假象蒙骗了！伊洛姆是一名强大的咒术师，能召唤大量的幻影生物。去我们头顶的环面找他吧。', `MaleText_loc5`='欺詐者法師領主厄隆保護著第三道環。他看起來單獨一人並且毫無戒備，但是別被他的外貌給欺騙了!厄隆是位強大的咒術師，控制一整群的幻魅生物。到上面把他找出來。', `MaleText_loc7`='El tramposo Señor de la magia Urom protege el tercer anillo. Aparecerá solo e indefenso, ¡pero que no te engañen las apariencias! Urom es un poderoso conjurador que dirige un grupo de criaturas fantasmales. Búscale arriba.', `FemaleText_loc1`='교활한 마법사 군주 우롬이 세 번째 고리를 보호하고 있어요. 놈은 무방비 상태로 혼자 있는 것처럼 보이지만, 겉보기만으로 속아 넘어가서는 안 돼요! 우롬은 실체 없는 생물 군단을 지휘하는 강력한 요술사예요. 저 위에서 그를 찾아보세요.', `FemaleText_loc4`='法师领主伊洛姆守护着第三环。他独自在平台上踱步，一副毫无防备的模样，你千万别被假象蒙骗了！伊洛姆是一名强大的咒术师，能召唤大量的幻影生物。去我们头顶的环面找他吧。', `FemaleText_loc5`='欺詐者法師領主厄隆保護著第三道環。他看起來單獨一人並且毫無戒備，但是別被他的外貌給欺騙了!厄隆是位強大的咒術師，控制一整群的幻魅生物。到上面把他找出來。', `FemaleText_loc7`='El tramposo Señor de la magia Urom protege el tercer anillo. Aparecerá solo e indefenso, ¡pero que no te engañen las apariencias! Urom es un poderoso conjurador que dirige un grupo de criaturas fantasmales. Búscale arriba.' WHERE `ID`=29537;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가장 까다로운 도전이 눈앞에 놓였습니다. 지맥 수호자 에레고스는 엄청난 힘을 지닌 푸른용이지요. 에레고스는 가장 높이 있는 고리 위를 선회하고 있을 겁니다.', `MaleText_loc4`='接下来，你将迎接最艰难的挑战。魔网守护者埃雷苟斯，一条拥有无穷力量的蓝龙。他就在最顶层的环面上空盘旋。', `MaleText_loc5`='最大挑戰正等著你。地脈守護者伊瑞茍斯是一隻擁有強大力量的藍龍。你會在最上環上方找到飛行中的牠。', `MaleText_loc7`='El mayor de tus desafíos aún está por llegar. El Guardián-Ley Eregos es un dragón Azul de inmenso poder. Lo encontrarás sobrevolando el anillo superior.', `FemaleText_loc1`='가장 까다로운 도전이 눈앞에 놓였어요. 지맥 수호자 에레고스는 엄청난 힘을 지닌 푸른용이에요. 에레고스는 가장 높이 있는 고리 위를 선회하고 있을 거예요.', `FemaleText_loc4`='接下来，你将迎接最艰难的挑战。魔网守护者埃雷苟斯，一条拥有无穷力量的蓝龙。他就在最顶层的环面上空盘旋。', `FemaleText_loc5`='最大挑戰正等著你。地脈守護者伊瑞茍斯是一隻擁有強大力量的藍龍。你會在最上環上方找到飛行中的牠。', `FemaleText_loc7`='El mayor de tus desafíos aún está por llegar. El Guardián-Ley Eregos es un dragón Azul de inmenso poder. Lo encontrarás sobrevolando el anillo superior.' WHERE `ID`=29538;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 무엇을 해야 합니까?', `MaleText_loc4`='接下来我们该怎么办？', `MaleText_loc5`='下一步我們要做什麼?', `MaleText_loc7`='¿Qué deberíamos hacer ahora?', `FemaleText_loc1`='이제 무엇을 해야 하나요?', `FemaleText_loc4`='接下来我们该怎么办？', `FemaleText_loc5`='下一步我們要做什麼?', `FemaleText_loc7`='¿Qué deberíamos hacer ahora?' WHERE `ID`=29539;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='복수의 상륙지로 가는 비행선이 방금 도착했습니다! 울부짖는 협만으로 가시는 분들은 모두 타세요!', `MaleText_loc4`='前往复仇港的飞艇已经抵达！要去嚎风峡湾的旅客请登机！', `MaleText_loc5`='前往復仇臺地的飛艇剛剛抵達!要到凜風峽灣的乘客請上船!', `MaleText_loc7`='¡El zepelín hacia Campo Venganza acaba de llegar! ¡Todos a bordo para ir a Fiordo Aquilonal!', `FemaleText_loc1`='복수의 상륙지로 가는 비행선이 방금 도착했습니다! 울부짖는 협만으로 가시는 분들은 모두 타세요!', `FemaleText_loc4`='前往复仇港的飞艇已经抵达！要去嚎风峡湾的旅客请登机！', `FemaleText_loc5`='前往復仇臺地的飛艇剛剛抵達!要到凜風峽灣的乘客請上船!', `FemaleText_loc7`='¡El zepelín hacia Campo Venganza acaba de llegar! ¡Todos a bordo para ir a Fiordo Aquilonal!' WHERE `ID`=29540;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭풍우 봉우리 안에 있는 돌의 전당은 77에서 79 레벨의 플레이어가 공략할 수 있는 던전으로 지금 시험해볼 수 있습니다. 던전 안으로 순간이동하기 전에 파티를 맺은 상태여야 합니다. 만남의 돌은 아직 사용할 수 없습니다. 돌의 전당에서 나오려면, 던전 안에 있는 입구로 빠져나오면 됩니다. 그러면 바로 여기로 돌아오게 되지요. 죽어서 영혼이 빠져나갔다면 다시 NPC와 대화하여 순간이동해야 합니다.', `MaleText_loc4`='位于风暴峭壁的岩石大厅已开放测试，该地下城适合77至79级的玩家。请组满队伍后再传送至岩石大厅。该地下城的集合石尚未开放。

穿过地下城内的常规出口，即可离开岩石大厅并返回这里。如果角色死亡并选择释放灵魂，请从该NPC处传送回去。', `MaleText_loc5`='石之大廳，在風暴群山中一座77-79級的地城，如今可供測試。請於傳送進地城之前之前處於一個完整的小隊中。尚未有對應這個地城的集合石可供使用。

想要離開石之大廳，只需要從地城內一般的出口離開即可，你便能返回這裡。如果你不幸死亡並釋放靈魂，你可以從這位NPC處傳送回去。', `MaleText_loc7`='Las Cámaras de Piedra, una mazmorra de nivel 77-79 en Las Cumbres Tormentosas ya está disponible para probarla. Por favor, forma un grupo completo antes de teletransportarte a la mazmorra. Las Rocas de Encuentro todavía no están disponibles para esta mazmorra.

Para salir de Las Cámaras de Piedra, basta con salir por la salida normal de la mazmorra y volverás aquí. Si mueres y te liberas, deberás volver a teleportarte con este PNJ.' WHERE `ID`=29541;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저와 파티원 모두 준비되었습니다. 돌의 전당으로 순간이동시켜 주십시오!', `MaleText_loc4`='我已经组满队伍，准备前往岩石大厅！', `MaleText_loc5`='我位於團體當中，並準備好傳送至石之大廳!', `MaleText_loc7`='¡Estoy con mi grupo y quiero teletransportarme a las Cámaras de Piedra!', `FemaleText_loc1`='저와 파티원 모두 준비되었어요. 돌의 전당으로 순간이동시켜 주세요!', `FemaleText_loc4`='我已经组满队伍，准备前往岩石大厅！', `FemaleText_loc5`='我位於團體當中，並準備好傳送至石之大廳!', `FemaleText_loc7`='¡Estoy con mi grupo y quiero teletransportarme a las Cámaras de Piedra!' WHERE `ID`=29542;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 돌의 전당으로 돌아가고 싶습니다!', `MaleText_loc4`='将我送回岩石大厅！', `MaleText_loc5`='帶我回去石之大廳!', `MaleText_loc7`='¡Llévame de vuelta a las Cámaras de Piedra!', `FemaleText_loc1`='다시 돌의 전당으로 돌아가게 해주세요!', `FemaleText_loc4`='将我送回岩石大厅！', `FemaleText_loc5`='帶我回去石之大廳!', `FemaleText_loc7`='¡Llévame de vuelta a las Cámaras de Piedra!' WHERE `ID`=29543;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저... 저는 잘 모릅니다.', `MaleText_loc4`='我……我不知道。', `MaleText_loc5`='我...我不清楚。', `MaleText_loc7`='No... No lo sé.' WHERE `ID`=29544;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언더시티행 비행선이 지금 막 도착했습니다! 티리스팔 숲으로 가시는 분들은 어서 승선하십시오!', `MaleText_loc4`='前往幽暗城的飞艇已经抵达！要去提瑞斯法林地的旅客请登机！', `MaleText_loc5`='前往幽暗城的飛艇剛剛抵達!要到提里斯法林地的乘客請上船!', `MaleText_loc7`='¡El zepelín hacia Entrañas acaba de llegar! ¡Todos a bordo para ir a los Claros de Tirisfal!', `FemaleText_loc1`='언더시티행 비행선이 지금 막 도착했어요! 티리스팔 숲으로 가시는 분들은 어서 승선하세요!', `FemaleText_loc4`='前往幽暗城的飞艇已经抵达！要去提瑞斯法林地的旅客请登机！', `FemaleText_loc5`='前往幽暗城的飛艇剛剛抵達!要到提里斯法林地的乘客請上船!', `FemaleText_loc7`='¡El zepelín hacia Entrañas acaba de llegar! ¡Todos a bordo para ir a los Claros de Tirisfal!' WHERE `ID`=29545;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='말씀해 보세요, 모도루. 어디서 그... 그렇게... "근사한" 로브를 구하셨나요?', `FemaleText_loc4`='我说，莫度鲁，你从哪儿弄到这件……呃……“漂亮”的长袍的啊？', `FemaleText_loc5`='我說，莫杜魯，你是打哪弄來那些...呃...你那些「好極了」的袍子呢，嗯?', `FemaleText_loc7`='Dime, Modoru. ¿Dónde conseguiste esas... eh... "maravillosas" togas tuyas, mmmm?' WHERE `ID`=29546;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 거기... 알아요. 정말 멋지네요!', `FemaleText_loc4`='噢。噢……原来如此。不错呀！', `FemaleText_loc5`='噢，噢...我懂了，真棒!', `FemaleText_loc7`='Oh. Oh... ya veo. ¡Qué bien!' WHERE `ID`=29547;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 입술을 깨물며 웃음을 참습니다.', `FemaleText_loc4`='%s强忍着笑。', `FemaleText_loc5`='%s把笑意吞了回去。', `FemaleText_loc7`='%s reprime una carcajada.' WHERE `ID`=29548;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전쟁노래 요새로 가는 비행선이 방금 도착했습니다! 북풍의 땅으로 가시는 분들은 모두 타세요!', `MaleText_loc4`='前往战歌要塞的飞艇已经抵达！要去北风苔原的旅客请登机！', `MaleText_loc5`='前往戰歌堡的飛艇剛剛抵達!要到北風凍原的乘客請上船!', `MaleText_loc7`='¡El zepelín al Bastión Grito de Guerra acaba de llegar! ¡Suban todos para ir a la Tundra Boreal!', `FemaleText_loc1`='전쟁노래 요새로 가는 비행선이 방금 도착했어요! 북풍의 땅으로 가시는 분들은 모두 타세요!', `FemaleText_loc4`='前往战歌要塞的飞艇已经抵达！要去北风苔原的旅客请登机！', `FemaleText_loc5`='前往戰歌堡的飛艇剛剛抵達!要到北風凍原的乘客請上船!', `FemaleText_loc7`='¡El zepelín al Bastión Grito de Guerra acaba de llegar! ¡Suban todos para ir a la Tundra Boreal!' WHERE `ID`=29549;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놀림 받는다는 생각도 못한 채, %s|1은;는; 강한 억양으로 미사 통상문을 읽으며 밝게 미소 짓습니다.', `MaleText_loc4`='%s完全没有意识到她在嘲笑自己，竟然露出了笑容，用带有重口音的通用语回答了她的问题。', `MaleText_loc5`='%s燦爛得笑著，沒有意會到甘泉的捉弄，而以他那沙啞的通用語回答甘泉。', `MaleText_loc7`='%s brilla, sin saber que lo está poniendo nervioso, contestando en su común de fuerte acento.' WHERE `ID`=29550;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오그리마행 비행선이 지금 막 도착했습니다! 듀로타로 가시는 분들은 어서 승선하십시오!', `MaleText_loc4`='前往奥格瑞玛的飞艇已经抵达！要去杜隆塔尔的旅客请登机！', `MaleText_loc5`='前往奧格瑪的飛艇剛剛抵達!要到杜洛塔的乘客請上船!', `MaleText_loc7`='¡El zepelín hacia Orgrimmar acaba de llegar! ¡Todos a bordo para ir a Durotar!', `FemaleText_loc1`='오그리마행 비행선이 지금 막 도착했어요! 듀로타로 가시는 분들은 어서 승선하세요!', `FemaleText_loc4`='前往奥格瑞玛的飞艇已经抵达！要去杜隆塔尔的旅客请登机！', `FemaleText_loc5`='前往奧格瑪的飛艇剛剛抵達!要到杜洛塔的乘客請上船!', `FemaleText_loc7`='¡El zepelín hacia Orgrimmar acaba de llegar! ¡Todos a bordo para ir a Durotar!' WHERE `ID`=29551;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알았네! 보다시피 이건 올루바 할머니께서 주신 선물일세. 할머니께서 드레노어 산 최고급 비단으로 직접 만드신 것이지! 내 자랑거리일세. 그렇고말고.', `MaleText_loc4`='哈！这是我的祖母送给我的礼物呀。这件长袍是她用德拉诺最上等的丝绸亲手缝制的！穿上它令我倍感自豪呢！', `MaleText_loc5`='哇!你瞧，這是祖母歐魯芭的禮物。她用德拉諾上好的絲綢親手織的。我為此感到驕傲，真的。', `MaleText_loc7`='¡Bueno! Verás, fue un regalo de la abuela Oluba. ¡Ella teje a mano la mejor seda de Draenor! Y me llena de orgullo.' WHERE `ID`=29552;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 끙끙대며 파수꾼 스위트스프링의 발목에 코를 비벼댑니다.', `MaleText_loc4`='%s窃笑着，用鼻子摩挲着哨兵琪珊·清泉的脚踝。', `MaleText_loc5`='%s一邊竊笑著，一邊用鼻子磨蹭著哨兵甘泉的腳踝。', `MaleText_loc7`='%s se ríe, acariciando con la nariz los tobillos del Centinela Fuente Dulce.' WHERE `ID`=29553;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 파수꾼 스위트스프링에 몸을 비비며 가르랑거립니다.', `MaleText_loc4`='%s朝哨兵琪珊·清泉发出呼噜声。', `MaleText_loc5`='%s對著哨兵甘泉嗚嗚叫著。', `MaleText_loc7`='%s ronronea al Centinela Fuente Dulce.' WHERE `ID`=29554;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 야영지 건너편에 있는 파수꾼 앰버라인을 보고 미소 지으며 넌지시 긴 눈썹을 깜빡입니다.', `FemaleText_loc4`='%s冲营地那头的哨兵蓝塔娜·琥珀咧嘴一笑，意味深长地挑动着她长长的眉毛。', `FemaleText_loc5`='%s對著營地對面的哨兵哨兵安珀琳齜牙咧嘴，暗示性的對她挑著眉毛。', `FemaleText_loc7`='%s sonríe al Centinela Lineámbar al otro lado del campamento, meneando sus largas cejas de forma sugerente.' WHERE `ID`=29555;
