UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기까지 와서 뭐하시는 거죠? 스트라솔름으로 당장 돌아가셔야 해요!$B$B제가 스트라솔름으로 순간이동시켜 드릴까요?', `FemaleText_loc4`='你回来做什么？立即返回斯坦索姆！$B$B要我把你传送过去吗？', `FemaleText_loc5`='你大老遠跑回來這裡做什麼?你得馬上回到斯坦索姆!要我把你傳送回斯坦索姆嗎?', `FemaleText_loc7`='¿Qué haces aquí? ¡Tienes que volver a Stratholme inmediatamente!$B$B¿Te teletransporto a Stratholme?' WHERE `ID`=29562;
