UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='보안 경보를 발령합니다. 출처 불명의 역사 자료 분석은 하위 등급 대기열로 이전됩니다. 방어 작업을 시작합니다.', `FemaleText_loc4`='安全系统发现不明入侵。历史文档的分析工作优先级转为低。对策程序立即启动。', `FemaleText_loc5`='安全機制突破中，史實資料分析已調至低優先佇列，啟動反制程序。', `FemaleText_loc7`='Vulneración de seguridad en curso. Análisis de archivos históricos transferido a cola de baja prioridad. Contramedidas adoptadas. ' WHERE `ID`=29575;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='위협 지수가 임계점을 돌파했습니다. 천체 기록을 중단합니다. 보안 수준이 상승했습니다.', `FemaleText_loc4`='已超出威胁指数标准。天界文档中断。提高安全级别。', `FemaleText_loc5`='已超出威脅指數標準。天界資料庫已中止。安全等級已提升。', `FemaleText_loc7`='Umbral de índice de riesgo superado. Archivo celestial abortado. Nivel de seguridad incrementado. ' WHERE `ID`=29576;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위협 지수가 높습니다. 공허 분석을 종료합니다. 안전성 검증을 시작합니다.', `MaleText_loc4`='威胁指数过高。虚空分析程序关闭。启动清理协议。', `MaleText_loc5`='威脅指數過高。已轉移無效的分析。啟動清潔處理協定。', `MaleText_loc7`='Nivel crítico de riesgo. Análisis de fallos desviado. Iniciando protocolo de desinfección.' WHERE `ID`=29577;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가서 역병에 오염된 곡식을 발견해 마력 분열기를 사용하세요!$B$B그래야만 아서스가 증거를 발견하고 스트라솔름을 칠 테니까요.', `FemaleText_loc4`='找出那些携带了病毒的谷物箱，对它们使用奥术干扰器！$B$B这样阿尔萨斯就有充分的证据对斯坦索姆动手了。', `FemaleText_loc5`='去找到那些被藏起來的染疫穀物箱，對它們使用你的秘法干擾器!$B$B阿薩斯就會找到讓他動手肅清斯坦索姆所需要的證據。', `FemaleText_loc7`='¡Busca esas cajas con grano plagado y usa tu disruptor arcano en ellas!$B$BEntonces Arthas tendrá las pruebas que necesita para comenzar la purga de Stratholme.' WHERE `ID`=29578;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경고. 보안 잠금장치가 비활성화되었습니다. 기억 장치 소거를 시작합...', `MaleText_loc4`='警告：安全系统自动修复装置已被关闭。立刻消除化全部存储器内容并……', `MaleText_loc5`='警告:安全性系統自動修復裝置已被關閉。開始記憶體內容消除與...', `MaleText_loc7`='Alerta: sistema de seguridad antifallos desactivado. Depurando memoria y…' WHERE `ID`=29579;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정상 작동 중입니다. 생명체가 식별되었습니다. 환영합니다, 브란브론짱 님. 질문은?', `MaleText_loc4`='系统已上线。生命形态模式已确认。您好，铜须先生。是否需要问询？', `MaleText_loc5`='系統登入。生命體樣式已確認。歡迎，布萊恩布朗贊。是否查詢?', `MaleText_loc7`='Sistema conectado. Forma de vida reconocida. Bienvenido, Branbronzan. ¿Pregunta?' WHERE `ID`=29580;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기서 뭐 하는 건가요?$B$B아서스는 지금 스트라솔름 입구에 있다고요. 그와 함께 있어야 해요! 가세요!', `FemaleText_loc4`='你还待在这里做什么？$B$B阿尔萨斯就在斯坦索姆的入口处，你应该跟紧他！快去！', `FemaleText_loc5`='你在這做什麼?$B$B阿薩斯現在正在斯坦索姆的入口，你該在他身邊!去吧!', `FemaleText_loc7`='¿Qué haces aquí?$B$B¡Arthas está en la entrada de Stratholme ahora mismo y tú deberías estar con él! ¡Vamos!' WHERE `ID`=29581;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='허약하고 물렁물렁한 육신. 짧고 덧없는 생명. 너희는 육체의 저주를 피할 수 없다!', `MaleText_loc4`='看看你们那软弱的躯壳和短暂的生命。你们永远也无法逃避血肉的诅咒！', `MaleText_loc5`='脆弱的軀殼。短暫易碎的生命。你們逃不過血肉詛咒的!', `MaleText_loc7`='Envases blandos y vulnerables. Vidas efímeras y frágiles. ¡No puedes escapar de la maldición de la carne!' WHERE `ID`=29582;
