UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말이십니까?$B$B당신이 습득한 특성 지식을 제가 일단 지우고 나면, 되돌릴 수는 없다는 점을 명심하십시오.', `MaleText_loc4`='你确定要这样做吗？$B$B一旦我抹去你已经学会的天赋，就不能反悔啦。', `MaleText_loc5`='你確定嗎?$B$B一旦我消除了你學會的天賦知識，就沒有挽回的餘地了。', `MaleText_loc7`='¿Estás $gseguro:segura;?$B$BUna vez que haya eliminado el conocimiento de los talentos de tu mente, no habrá vuelta atrás.', `FemaleText_loc1`='정말이세요?$B$B당신이 습득한 특성 지식을 제가 일단 지우고 나면, 되돌릴 수는 없다는 점을 명심하세요.', `FemaleText_loc4`='你确定要这样做吗？$B$B一旦我抹去你已经学会的天赋，就不能反悔啦。', `FemaleText_loc5`='你確定嗎?$B$B一旦我消除了你學會的天賦知識，就沒有挽回的餘地了。', `FemaleText_loc7`='¿Estás $gseguro:segura;?$B$BUna vez que haya eliminado el conocimiento de los talentos de tu mente, no habrá vuelta atrás.' WHERE `ID`=29631;
