UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은빛 여명회의 개들은 스컬지의 어둠 앞에 스러지리라!', `MaleText_loc4`='天灾军团的阴影将吞噬整个银色黎明！', `MaleText_loc5`='銀色黎明的走狗將會被天譴軍團的暗影給消滅!', `MaleText_loc7`='¡La sombra de la Plaga consumirá a los chuchos de El Alba Argenta!' WHERE `ID`=29637;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일어나라, 졸개들아! 스컬지 최전선으로 가라!', `MaleText_loc4`='站起来吧！到天灾军团的前线去战斗吧！', `MaleText_loc5`='起來吧，爪牙們!到天譴軍團的前線去!', `MaleText_loc7`='¡Levantaos, esbirros! ¡Al frente de la Plaga!' WHERE `ID`=29638;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 애써라! 마지막 공격이 눈앞이다!', `MaleText_loc4`='再加把劲儿！总攻就要开始了！', `MaleText_loc5`='加倍努力!最後的襲擊接近了!', `MaleText_loc7`='¡Dupliquen sus esfuerzos! ¡Se acerca el ataque final!' WHERE `ID`=29639;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래! 그래! 주인님께 영혼을 더 바쳐라!', `MaleText_loc4`='对！就是这样！更多的灵魂！', `MaleText_loc5`='好耶!好耶!主人有更多的靈魂了!', `MaleText_loc7`='¡Sí! ¡SÍ! ¡Más almas para el maestro!' WHERE `ID`=29640;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저... 그거 아플까요?', `MaleText_loc4`='会……会痛吗？', `MaleText_loc5`='會...會痛嗎?', `MaleText_loc7`='¿Me... me dolerá?', `FemaleText_loc1`='저... 그거 아플까요?', `FemaleText_loc4`='会……会痛吗？', `FemaleText_loc5`='會...會痛嗎?', `FemaleText_loc7`='¿Me... me dolerá?' WHERE `ID`=29641;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='따끔하군요...', `MaleText_loc4`='有点刺痛……', `MaleText_loc5`='刺痛...', `MaleText_loc7`='Siento un hormigueo…', `FemaleText_loc1`='따끔하군요...', `FemaleText_loc4`='有点刺痛……', `FemaleText_loc5`='刺痛...', `FemaleText_loc7`='Siento un hormigueo…' WHERE `ID`=29642;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마음을 바꾸기엔 너무 늦었나요? 그냥 절 죽이시면 안 될까요?', `MaleText_loc4`='我现在改变注意的话，还来得及吗？要不你直接杀了我吧？', `MaleText_loc5`='現在改變心意會不會太慢了?你何不乾脆殺了我算了?', `MaleText_loc7`='¿Es demasiado tarde para cambiar de opinión? ¿Y si en vez de eso me matas?', `FemaleText_loc1`='마음을 바꾸기엔 너무 늦었나요? 그냥 절 죽이시면 안 될까요?', `FemaleText_loc4`='我现在改变注意的话，还来得及吗？要不你直接杀了我吧？', `FemaleText_loc5`='現在改變心意會不會太慢了?你何不乾脆殺了我算了?', `FemaleText_loc7`='¿Es demasiado tarde para cambiar de opinión? ¿Y si en vez de eso me matas?' WHERE `ID`=29643;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 괴물!', `MaleText_loc4`='你这怪物！', `MaleText_loc5`='你是怪物!', `MaleText_loc7`='¡Eres un monstruo!', `FemaleText_loc1`='이 괴물!', `FemaleText_loc4`='你这怪物！', `FemaleText_loc5`='你是怪物!', `FemaleText_loc7`='¡Eres un monstruo!' WHERE `ID`=29644;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제발요! 살려 주세요! 저는...', `MaleText_loc4`='求你饶命！我……', `MaleText_loc5`='拜託!饒了我吧!我...', `MaleText_loc7`='¡Por favor! ¡Perdóname! Yo...', `FemaleText_loc1`='제발요! 살려 주세요! 저는...', `FemaleText_loc4`='求你饶命！我……', `FemaleText_loc5`='拜託!饒了我吧!我...', `FemaleText_loc7`='¡Por favor! ¡Perdóname! Yo...' WHERE `ID`=29645;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무서워! 무서워!', `MaleText_loc4`='天哪！天哪！！', `MaleText_loc5`='恐獸!恐獸!!', `MaleText_loc7`='¡El horror! ¡EL HORROR!', `FemaleText_loc1`='무서워! 무서워!', `FemaleText_loc4`='天哪！天哪！！', `FemaleText_loc5`='恐獸!恐獸!!', `FemaleText_loc7`='¡El horror! ¡EL HORROR!' WHERE `ID`=29646;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 물론이지. 아마 고통 때문에 의식을 잃을 것이다. 그래서 널 그 녹색 액체 안에 둥둥 띄운 거지!', `MaleText_loc4`='嗯。强烈的痛感可能会令你昏迷，因此你最好待在这只装满软泥怪的大桶里！', `MaleText_loc5`='噢，是的，非常強大。這痛苦將會使你失去意識 - 就是因此你才會漂著的軟泥缸裡。', `MaleText_loc7`='Oh, sí. Muchísimo. Es probable que pierdas el conocimiento por el dolor, por eso estás flotando en una cuba de baba.' WHERE `ID`=29647;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제대로 되고 있다는 증거지.', `MaleText_loc4`='生效了，等着瞧吧。', `MaleText_loc5`='就是要那樣你才會知道這是有用的。', `MaleText_loc7`='Así sabrás si está funcionando.' WHERE `ID`=29648;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론 나는 너를 죽일 것이다. 왜 그렇게 서두르느냐?', `MaleText_loc4`='我本来就会杀死你啊。着什么急呢？', `MaleText_loc5`='我「正要」去殺你。急什麼急?', `MaleText_loc7`='VOY a matarte. ¿A qué viene tanta prisa?' WHERE `ID`=29649;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='떠들어봤자 바뀌는 건 없어.', `MaleText_loc4`='谄媚对你没有好处。', `MaleText_loc5`='諂媚是沒有用的。', `MaleText_loc7`='Los cumplidos no te servirán de nada.' WHERE `ID`=29650;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우습구나. 내가 널 살려준들 네가 어디로 가겠느냐? 우리가 방금 너희 씨를 말렸는데 말이다. 기억하겠지?', `MaleText_loc4`='别可笑啦。就算我饶了你，你又能去哪里呢？我们已经灭绝了你们的文明。你忘了吗？', `MaleText_loc5`='別傻了，要是我沒有饒了你一命，你以為你能上哪去?我們才剛剛滅絕你的人民，還記得嗎?', `MaleText_loc7`='No seas absurdo. ¿Adónde irás si te perdono? Acabamos de erradicar a tu civilización, ¿recuerdas?' WHERE `ID`=29651;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만!', `MaleText_loc4`='住手！', `MaleText_loc5`='住手!', `MaleText_loc7`='¡Para!' WHERE `ID`=29652;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 그만!', `MaleText_loc4`='够了！', `MaleText_loc5`='夠了!', `MaleText_loc7`='¡Basta!' WHERE `ID`=29653;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물러서!', `MaleText_loc4`='后退！', `MaleText_loc5`='撤退!', `MaleText_loc7`='¡Atrás!' WHERE `ID`=29654;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싸움 끝! 내 말 들어!', `MaleText_loc4`='别打了！听我说！', `MaleText_loc5`='進攻!你們聽好了!', `MaleText_loc7`='¡Se acabó la pelea! ¡Ahora escucha!' WHERE `ID`=29655;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비명을 질러라, 인간이여. 내 귀엔 그게 음악이나 마찬가지지.', `MaleText_loc4`='尖叫吧，人类。我喜欢这美妙的乐曲。', `MaleText_loc5`='就像聽音樂一般。尖叫吧，人類。', `MaleText_loc7`='Música para mis oídos. Grita para mí, humano.' WHERE `ID`=29656;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 말 들어라. 자르트의 아들이자 광란심장 일족 최고의 싸움꾼이 하는 말을 들어.', `MaleText_loc4`='安静！听扎特森说，我可是狂心氏族最厉害的拳击手！', `MaleText_loc5`='聽話的時間到了。你聽從的是札特之子，狂心當中前所未見，最優秀的拳擊家!', `MaleText_loc7`='Hora de escuchar. ¡Escuchas al hijo de Zart, el mejor contendiente Corazón Frenético que jamás ha existido!' WHERE `ID`=29657;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라카트, 이 멍청이야. 발톱이 날아오는 곳에 코를 계속 갖다대면 코 맞아. 코 맞으면, 냄새 못 맡아. 냄새 못 맡으면, 사냥 못 해. 너 바보야.', `MaleText_loc4`='拉卡特，你这蠢货。如果你再用鼻子嗅猎物的行踪，那你的鼻子就废了。你没有了鼻子，还怎么闻气味呢。闻不到气味，我看你还怎么打猎，你就成废物了！', `MaleText_loc5`='銳卡特，你這笨蛋。要是你繼續黏著爪子抓過的地方，你的鼻子就不保。你的鼻子不保，你就不能嗅。你不能嗅，你狩獵就很糟糕，你這沒用的東西。', `MaleText_loc7`='Rakat, estúpido. Perderás la nariz si sigues metiéndola donde hay garras. Si pierdes la nariz, no podrás olfatear. Si no puedes olfatear, cazas mal y eres inútil.' WHERE `ID`=29658;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아자르크, 너 돌처럼 서 있는다. 라카트가 더 많이 움직여. 안 움직이면 말벌한테 쏘이고 가시털멧돼지 엄니에 다친다. 알지? 움직여!', `MaleText_loc4`='阿亚克，别像块石头似的矗在那儿啊。拉卡特就比你活跃。跑动起来啊，不然你就会被巨蜂蛰到，要不就是被钢刺野猪的獠牙戳伤。跑动起来！', `MaleText_loc5`='阿迦爾克，你像石頭一樣站好。銳卡特，再多移動一點。你要嘛就移動，不然你就會被黃蜂刺或是鬃松獠牙弄傷，你看吧。再多移動一點!', `MaleText_loc7`='Ajark, quieto como roca. Rakat muévete más. O te mueves o te hará daño el aguijón de avispa o el colmillo de pinocerda, verás. ¡Muévete más!' WHERE `ID`=29659;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빨리, 더 빨리 움직여야지! 너희 둘 다 날름이처럼 느리다. 나 너희 물속에 처넣고 날름이처럼 진흙투성이로 만들어서, 날름이들이 너희 데려가게 할까 보다.', `MaleText_loc4`='快。加快攻击速度啊！你们俩慢得跟大舌头怪似的。我应该将你们丢进河里，让你们全身裹满泥巴，这样大舌头怪就能收留你们了。', `MaleText_loc5`='加速，攻擊加速!你們兩個慢得跟大舌頭一樣。也許我把你們丟進水裡，也讓你們像大舌頭一樣黏答答的就好了，讓他們把你們帶進去。', `MaleText_loc7`='Más rápido. ¡Lucha más rápido! Los dos sois tan lentos como un lenguagrande. Quizás os tire al agua, para haceros babosos como lenguagrandes, hacer que os acojan.' WHERE `ID`=29660;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배를 가리지 않으면 배 때리기 쉬운데! 너희 높은 곳만 때리지, 낮은 곳 안 봐.', `MaleText_loc4`='保护好腹部啊，不然会被开膛破肚的！你要将注意力放在对方的上半身，别老盯着下面啊。', `MaleText_loc5`='守住腹部，否則腹部會毫無防備!攻擊高一點的部位，不要看下面。', `MaleText_loc7`='¡Protege la barriga o te abrirán la barriga! Golpeas cuerpo superior, no miras al inferior.' WHERE `ID`=29661;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아. 다시 싸워. 바보같이 굴면 안 돼.', `MaleText_loc4`='很好。再打一次。别再犯傻了。', `MaleText_loc5`='很好。再打一次。別再那麼笨了。', `MaleText_loc7`='Vale. Lucha otra vez. No más estupideces.' WHERE `ID`=29662;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시작!', `MaleText_loc4`='上！', `MaleText_loc5`='上!', `MaleText_loc7`='¡VAMOS!' WHERE `ID`=29663;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앞으로 나오라, 사도야. 네가 뭘 배웠는지 보여다오.', `MaleText_loc4`='来吧，让我瞧瞧你都学了些什么。', `MaleText_loc5`='站上前來，侍徒。讓我見識一下你學到了什麼。', `MaleText_loc7`='Avanza, discípulo. Muéstrame qué has aprendido.' WHERE `ID`=29664;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 얼음 손길 공격으로 상대가 시전하는 게 늦어졌다면 그놈의 주문이 별로 위협적이지 못하다는 뜻이지...', `MaleText_loc4`='如果你使用冰冷触摸降低它的施法速度，那么咒语的威胁性就会降低很多……', `MaleText_loc5`='如果它的魔法因為你的冰結之觸而減緩，那也就沒什麼威脅性了...', `MaleText_loc7`='Sus hechizos serían menos peligrosos si sus encantamientos fueran frenados por tu toque helado...' WHERE `ID`=29665;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 녀석이 다음 주문을 쉽게 생각해 내도록 하지 마라, 사도야... 마음까지 꼼짝 못하게 얼려버리란 말이다.', `MaleText_loc4`='别让它轻易地放出下一个法术……冻结它的思维。', `MaleText_loc5`='別讓它覺得它能輕易施放下一個法術，侍徒...凍結它的心靈。', `MaleText_loc7`='No dejes que piense en su próximo hechizo libremente, discípulo... congela su mente.' WHERE `ID`=29666;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배운 것을 시험해볼 시간이다. 앞으로 나오라.', `MaleText_loc4`='让我瞧瞧你都学到了什么。来吧。', `MaleText_loc5`='該是你的學習接受測試的時候了。往前。', `MaleText_loc7`='Es hora de poner a prueba lo que sabes. Avanza.' WHERE `ID`=29667;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼음이 혈관 안까지 침투했다고 걸음이 느려지지는 마라. 네 용기를 증명해 보여라, 사도야.', `MaleText_loc4`='不要因为血液被冻结就放慢了攻击速度。来吧，鼓起勇气。', `MaleText_loc5`='別讓你血液裡的寒冰放慢你的腳步。證明你的能力吧，侍徒。', `MaleText_loc7`='No dejes que el hielo de tu sangre detenga tu paso. Muestra tu destreza, discípulo.' WHERE `ID`=29668;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 정도면 충분할 만큼 견디고 훈련을 받은 셈이다. 앞으로 나오라.', `MaleText_loc4`='别老站着不动。上前一步吧。', `MaleText_loc5`='你已經站了夠久也聽了夠久了。前進。', `MaleText_loc7`='Te has alzado y escuchado lo bastante. Avanza.' WHERE `ID`=29669;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 가르친 것을 제대로 이해했는지 증명해 보아라, 사도야.', `MaleText_loc4`='让我瞧瞧你有没有掌握我交给你的诀窍。', `MaleText_loc5`='證明你了解我所傳授的事物，侍徒。', `MaleText_loc7`='Demuestra que comprendes mis enseñanzas, discípulo.' WHERE `ID`=29670;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 도전해 볼 차례다, 사도야. 내 가르침을 제대로 활용해 보도록.', `MaleText_loc4`='准备接受挑战吧。好好利用我教给你的诀窍。', `MaleText_loc5`='侍徒，該是你接受挑戰的時候了。好好運用我所傳授給你的事物。', `MaleText_loc7`='Es hora de que te enfrentes al reto, discípulo. Aprovecha mis enseñanzas.' WHERE `ID`=29671;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너희의 영혼까지 짓밟아주마!', `FemaleText_loc4`='我要征服你们的灵魂！', `FemaleText_loc5`='我要征服你的靈魂!', `FemaleText_loc7`='¡Conquistaré tu alma!' WHERE `ID`=29672;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 끝나지 않았다, 사도야... 죽음을 부르는 갈망의 한기로 이 맹렬한 공격을 멈추게 하라.', `MaleText_loc4`='你还没有落败……利用饥饿之寒阻止这次攻击！', `MaleText_loc5`='你還沒有被徹底擊敗，侍徒...讓死亡饑寒終止這場突襲吧。', `MaleText_loc7`='Aún no estás sobrecogido, discípulo... deja que el hambriento frío de la muerte ponga fin a este ataque.' WHERE `ID`=29673;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='단단하게 얼어붙었으니, 처치하기 딱 좋구나. 작렬하는 분노를 폭발시켜 저들을 산산조각 내어라, 사도야.', `MaleText_loc4`='它们被冻僵了，正是下手的好机会。利用凛风冲击将它们撕成碎片吧！', `MaleText_loc5`='冰凍凝固是完美的殺戮對象。放出一道凜風衝擊，將他們擊成碎片吧，侍徒。', `MaleText_loc7`='Totalmente congelados, listos para la masacre. Lanza una Explosión aullante y rómpelos en mil pedazos, discípulo.' WHERE `ID`=29674;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='멍청한 놈... 리치 왕의 힘에 도전하다니...', `FemaleText_loc4`='妄图挑战巫妖王的力量？你太愚蠢了！', `FemaleText_loc5`='你竟蠢到膽敢挑戰巫妖王的力量!', `FemaleText_loc7`='¡Fuiste un tonto al desafiar el poder del Rey Exánime!' WHERE `ID`=29675;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신의 뜻을 행했나이다!', `FemaleText_loc4`='陛下，我已执行了您的意志！', `FemaleText_loc5`='我已貫徹您的旨意，吾王!', `FemaleText_loc7`='¡Se ha hecho su voluntad, mi Rey!' WHERE `ID`=29676;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='또 다른 영혼을 바칩니다...', `FemaleText_loc4`='让我再为主人奉上一个灵魂吧！', `FemaleText_loc5`='讓我再為主人奉上一個靈魂吧!', `FemaleText_loc7`='¡Otra alma para mi amo!' WHERE `ID`=29677;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='죽음이 다가온다...', `FemaleText_loc4`='你的死亡临近了……', `FemaleText_loc5`='你的死期快到了...', `FemaleText_loc7`='Tu muerte se aproxima…' WHERE `ID`=29678;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 주인님께 가거라!', `FemaleText_loc4`='你的灵魂可以去主人那里了！', `FemaleText_loc5`='去見我的主人吧!', `FemaleText_loc7`='¡Ve con mi amo!' WHERE `ID`=29679;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='죽음을 피할 순 없다.', `FemaleText_loc4`='你的末日已经不可避免。', `FemaleText_loc5`='你無法逃避你的末日。', `FemaleText_loc7`='Tu fin es inevitable.' WHERE `ID`=29680;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='요르구울 막!', `FemaleText_loc4`='Yor-guul mak！', `FemaleText_loc5`='(維酷語)嚥下最後一口氣吧!', `FemaleText_loc7`='¡Yor-guul mak!' WHERE `ID`=29681;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='남길 말이라도?', `FemaleText_loc4`='还有什么遗言吗？', `FemaleText_loc5`='還有什麼遺言嗎?', `FemaleText_loc7`='¿Alguna última palabra?' WHERE `ID`=29682;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내가 어떻게... 여기까지.. 왔는데...', `FemaleText_loc4`='不！我历尽千辛万苦，不是为了……', `FemaleText_loc5`='不!我歷盡千辛萬苦，不是為了...', `FemaleText_loc7`='No llegué tan lejos... para...' WHERE `ID`=29683;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='주인님! 당신께서 주신 일을 행했습니다. 이제, 축복을 내려 주소서!', `FemaleText_loc4`='尊敬的陛下！我已经完成您的全部要求，希望您能不吝赐下伟大的祝福！', `FemaleText_loc5`='陛下!我已完成您的要求，如今懇求您的祝福!', `FemaleText_loc7`='¡Mi Señor! ¡Hice lo que me pidió, y ahora imploro su bendición!' WHERE `ID`=29684;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신께서 오라버니를 위해 해주신 일을 절대로 잊지 않겠어요. 평생 갚지 못할 은혜를 입었습니다.', `FemaleText_loc4`='我不会忘记你为萨萨里安所做的一切。不胜感激。', `FemaleText_loc5`='我絕對不會忘記你為薩沙理安所做的事。我永遠都欠你人情。', `FemaleText_loc7`='Jamás olvidaré lo que hiciste por Thassarian. Siempre estaré en deuda contigo.' WHERE `ID`=29685;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 감각은... 상상을 초월합니다. 저는 당신의 것입니다, 왕이시여.', `FemaleText_loc4`='这感觉……真是超乎想象。我将永远听命于您，陛下。', `FemaleText_loc5`='這感覺...真是超乎想像。我將永遠聽命於您，吾王。', `FemaleText_loc7`='La sensación es... indescriptible. Estoy a sus órdenes, mi Señor.' WHERE `ID`=29686;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신의 이름으로 저들에게 죽음을 선사하겠습니다! 오라, 스컬지의 적이여! 내 너희에게 리치 왕의 강대함을 보여주겠다!', `FemaleText_loc4`='能以您的名义杀死这些蝼蚁令我十分荣幸，来吧，天灾军团的敌人们！我让你们看看巫妖王的真正力量！', `FemaleText_loc5`='我很樂意以你的名義來屠殺他們!來吧，天譴軍的敵人!我會讓你們瞧瞧巫妖王的力量 !', `FemaleText_loc7`='¡Me complacerá exterminarlos en tu nombre! ¡Vengan, enemigos de la Plaga! ¡Les mostraré el poder del Rey Exánime!' WHERE `ID`=29687;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너의 희생이 네 충성심을 증명하는구나. 그래. 넌 자격이 있다. 일어나라. 이제부터 네 이름은 스발라 소로우그레이브다!', `MaleText_loc4`='这次献祭只是对你恭顺与服从的考验。现在你已证明自己确实可以胜任我的嘱托。平身吧，席瓦拉·索格蕾！', `MaleText_loc5`='你的犧牲正是對你的服從所進行的考驗，而你證明了你能夠勝任我的囑託。起身吧，從此你將以絲瓦拉·悲傷亡墓之名為人所知!', `MaleText_loc7`='Tu sacrificio es un testimonio de tu obediencia. En verdad eres digno de este cargo. ¡Levántate, y hazte llamar por siempre Svala Sorrowgrave!' WHERE `ID`=29688;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='첫 번째 시험이 기다린다. 초대받지 않은 손님들을 처치해라.', `MaleText_loc4`='你的第一个试炼正在等待着你。消灭那些不速之客。', `MaleText_loc5`='你的第一個試煉正在等待著你。消滅那些不速之客。', `MaleText_loc7`='Tendrás tu primera prueba. Destruye a los indeseables invitados.' WHERE `ID`=29689;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아버님을 자유롭게 해드리고자 모든 것을 희생했던 곳이 바로 여기이다. 이제 이곳을 파괴하려 한다...', `MaleText_loc4`='就在这里，我放弃了一切，只为换取父亲的自由。如今，我要亲手摧毁它……', `MaleText_loc5`='這兒就是我犧牲一切救出我父親的地方。而如今我是來摧毀它的...', `MaleText_loc7`='Aquí es donde lo sacrifiqué todo para liberar a mi padre. Ahora vengo a destruirlo...' WHERE `ID`=29690;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 준비되었습니다, 대영주님. 바로 희망의 빛 예배당을 포위 공격합시다!', `MaleText_loc4`='大领主，我准备好了。向圣光之愿礼拜堂发起进攻吧！', `MaleText_loc5`='我準備好了，大領主。讓聖光之願的圍攻發動吧!', `MaleText_loc7`='Estoy preparado, Alto Señor. ¡Que comience el asedio a Esperanza de la Luz!', `FemaleText_loc1`='전 준비되었어요, 대영주님. 바로 희망의 빛 예배당을 포위 공격해요!', `FemaleText_loc4`='大领主，我准备好了。向圣光之愿礼拜堂发起进攻吧！', `FemaleText_loc5`='我準備好了，大領主。讓聖光之願的圍攻發動吧!', `FemaleText_loc7`='Estoy preparada, Alto Señor. ¡Que comience el asedio a Esperanza de la Luz!' WHERE `ID`=29691;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언젠가 아버지께서 삶은 다 부질없다는 말씀을 하셨다... 우리가 진정으로 시험받는 것은 죽었을 때라고. 희망의 빛 예배당을 포위 공격함으로써 그 말씀을 입증할 수 있다고 생각한다. 곧 공격을 감행할 것이다, $n. 대기하고 있어라.', `MaleText_loc4`='我的父亲曾经说过，生命本身毫无意义……只有死亡，才能让你了解人性的真谛。圣光之愿礼拜堂的沦陷将完美地诠释他这番话的含义。$n，我们很快就要进攻了。做好准备吧。', `MaleText_loc5`='我的父親曾經告訴我生命毫無意義...唯有死亡才是會讓我們受到真正的試煉。我感到聖光之願的圍攻將會驗證這句話的意義。我們馬上進攻，$n，準備就緒。', `MaleText_loc7`='Mi padre me dijo una vez que la vida no tiene sentido... Que es en la muerte donde realmente se te pone a prueba. Creo que el asedio a Esperanza de la Luz dotará de sentido a sus palabras. Atacaremos pronto, $n. Prepárate.' WHERE `ID`=29692;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아케루스 죽음의 기사들이여, 네 주인의 부름에 응답하라! 희망의 빛 예배당에 포위 공격을 시작했다! 우리는 제재소에 집합한다!', `MaleText_loc4`='阿彻鲁斯的死亡骑士，聆听主人的召唤吧！向圣光之愿礼拜堂发动攻击！我们在布洛米尔汇合！', `MaleText_loc5`='亞榭洛的死亡騎士，傾聽你的主人的呼喚!聖光之願的圍攻就在途中!在磨坊集結!', `MaleText_loc7`='Caballeros de la Muerte de Acherus, ¡escuchen la llamada de su señor! ¡El asedio de Esperanza de la Luz está en marcha! ¡Nos reuniremos en el molino!' WHERE `ID`=29693;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스컬지 군대여! 준비하라! 은빛 여명회 놈들에게 우리의 분노를 보여줄 때다!', `MaleText_loc4`='天灾军团的士兵们，做好准备！你们马上就可以向银色黎明倾泻怒火了！', `MaleText_loc5`='天譴軍團的士兵，做好準備!你們即將對銀色黎明釋放你們的憤怒!', `MaleText_loc7`='¡Soldados de la Plaga, prepárense! Listos para descargar la furia contra el Alba Plateada!' WHERE `ID`=29694;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 어둠의 영역에서 이번에는 어떤 분노를 끌어낼 수 있는지 볼까요...', `FemaleText_loc4`='让我们瞧瞧来自阴影界的残暴怪物……', `FemaleText_loc5`='讓我們瞧瞧這次能從暗影國度裡拉回什麼殘忍的東西...', `FemaleText_loc7`='Veamos qué atrocidad podemos sacar esta vez del reino de las sombras...' WHERE `ID`=29695;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='짓밟힌 대지를 보며 하늘도 눈물을 흘리는구나. 머지않아, 온 아제로스가 우리 앞에 피눈물을 흘리리라!', `MaleText_loc4`='大地即将崩裂，天空也要为之哭泣！很快，艾泽拉斯那悲戚的血泪就会降下！', `MaleText_loc5`='天空為了這塊大地的蹂躪而落淚!很快地，艾澤拉斯悲戚的淚水就會落在我們身上!', `MaleText_loc7`='¡El cielo llora por la gloriosa devastación de estas tierras! ¡Pronto las fútiles lágrimas de Azeroth lloverán sobre nosotros!', `FemaleText_loc1`='짓밟힌 대지를 보며 하늘도 눈물을 흘리는구나. 머지않아, 온 아제로스가 우리 앞에 피눈물을 흘리리라!', `FemaleText_loc4`='大地即将崩裂，天空也要为之哭泣！很快，艾泽拉斯那悲戚的血泪就会降下！', `FemaleText_loc5`='天空為了這塊大地的蹂躪而落淚!很快地，艾澤拉斯悲戚的淚水就會落在我們身上!', `FemaleText_loc7`='¡El cielo llora por la gloriosa devastación de estas tierras! ¡Pronto las fútiles lágrimas de Azeroth lloverán sobre nosotros!' WHERE `ID`=29696;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아케루스 죽음의 기사여, 죽음의 행진을 시작하자!', `MaleText_loc4`='阿彻鲁斯的死亡骑士们，死亡的远征现在开始！', `MaleText_loc5`='亞榭洛的死亡騎士們，死亡遠征現在展開!', `MaleText_loc7`='Caballeros de la Muerte de Acherus: ¡que comience la marcha de la muerte!', `FemaleText_loc1`='아케루스 죽음의 기사여, 죽음의 행진을 시작하자!', `FemaleText_loc4`='阿彻鲁斯的死亡骑士们，死亡的远征现在开始！', `FemaleText_loc5`='亞榭洛的死亡騎士們，死亡遠征現在展開!', `FemaleText_loc7`='Caballeros de la Muerte de Acherus: ¡que comience la marcha de la muerte!' WHERE `ID`=29697;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='5단계 이벤트 외침! 으악!', `MaleText_loc4`='EVENT STEP 005 YELL! RAWR!', `MaleText_loc5`='任務步驟005呼喊!嚇啊!', `MaleText_loc7`='EVENT STEP 005 YELL! RAWR!', `FemaleText_loc1`='5단계 이벤트 외침! 으악!', `FemaleText_loc4`='EVENT STEP 005 YELL! RAWR!', `FemaleText_loc5`='任務步驟005呼喊!嚇啊!', `FemaleText_loc7`='EVENT STEP 005 YELL! RAWR!' WHERE `ID`=29698;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스컬지 병사여, 아케루스 죽음의 기사여, 어둠의 추종자여! 대영주의 부름에 응답하라!', `MaleText_loc4`='天灾军团的士兵们，阿彻鲁斯的死亡骑士们，黑暗的仆从们：听从大领主的召唤！', `MaleText_loc5`='天譴軍團的士兵，亞榭洛的死亡騎士，黑暗的爪牙:聽從大領主的召喚!', `MaleText_loc7`='Soldados de la Plaga, caballeros de la muerte de Acherus, lacayos de la oscuridad: ¡oigan el llamado del Alto Señor!', `FemaleText_loc1`='스컬지 병사여, 아케루스 죽음의 기사여, 어둠의 추종자여! 대영주의 부름에 응답하라!', `FemaleText_loc4`='天灾军团的士兵们，阿彻鲁斯的死亡骑士们，黑暗的仆从们：听从大领主的召唤！', `FemaleText_loc5`='天譴軍團的士兵，亞榭洛的死亡騎士，黑暗的爪牙:聽從大領主的召喚!', `FemaleText_loc7`='Soldados de la Plaga, caballeros de la muerte de Acherus, lacayos de la oscuridad: ¡oigan el llamado del Alto Señor!' WHERE `ID`=29699;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일어나라!', `MaleText_loc4`='苏醒吧！', `MaleText_loc5`='甦醒吧!', `MaleText_loc7`='¡LEVÁNTENSE!', `FemaleText_loc1`='일어나라!', `FemaleText_loc4`='苏醒吧！', `FemaleText_loc5`='甦醒吧!', `FemaleText_loc7`='¡LEVÁNTENSE!' WHERE `ID`=29700;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='드루이드군요! 정말 궁금하네요... 어떻게 저 안에 들어갔을까요.', `FemaleText_loc4`='德鲁伊！真奇怪……阴影世界中怎么会有德鲁伊的精神投影呢？', `FemaleText_loc5`='一個德魯伊!真是奇怪...我想知道它是怎麼進去裡面的。', `FemaleText_loc7`='¡Un druida! Qué curioso... me pregunto cómo habrá llegado aquí.' WHERE `ID`=29701;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='구울요? 아주 넉넉히 준비해 놨으니 걱정하지 말아요.', `FemaleText_loc4`='食尸鬼？这里的食尸鬼已经够多的了。', `FemaleText_loc5`='食屍鬼?我們還會嫌不夠嗎。', `FemaleText_loc7`='¿Necrófagos? Ya tenemos más que de sobra de estos.' WHERE `ID`=29702;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예전에 난 아버지를 자유롭게 하려고 여기서 모든 것을 바쳤지. 이제 난 여기를 파괴하러 왔다...', `MaleText_loc4`='就在这里，我放弃了一切，只为换取父亲的自由。如今，我要亲手摧毁它……', `MaleText_loc5`='這兒就是我犧牲一切救出我父親的地方。而如今我是來摧毀它的...', `MaleText_loc7`='Aquí es donde lo sacrifiqué todo para liberar a mi padre. Ahora vengo a destruirlo...' WHERE `ID`=29703;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무슨... 여기가 어디죠?', `FemaleText_loc4`='谁打扰了我的梦境？', `FemaleText_loc5`='什...我在哪?', `FemaleText_loc7`='¿Qué... dónde estoy?' WHERE `ID`=29704;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비글스워스 씨라는 고양이가 있지. 낙스라마스에 마지막으로 살아남은 존재인 이 고양이는 켈투자드와 그의 유한한 생명을 연결하는 마지막 목숨줄이라고 한다. 그 고양이 털끝 하나라도 손대면 바로 끝장이라는 말이 있는데... 잠깐, 저 사람 저기서 뭐 하는 거지?', `MaleText_loc4`='比格沃斯先生。这只猫是纳克萨玛斯中唯一有生命的物体，据说它是克尔苏加德与生者世界的最后一丝联系。谣传胆敢碰它一根毛发的人都难逃……等等，它在做什么？！', `MaleText_loc5`='畢勾沃斯先生。納克薩瑪斯中最後一個活著的生物，傳說這隻貓是連結科爾蘇加德與他凡人生活的最後一點關係。聽說任何敢傷到他一根汗毛的人都是自找死路...等等，他在幹嘛?!', `MaleText_loc7`='Baldomero. La última criatura viva dentro de Naxxramas. Se dice que este gato es la última conexión que queda entre Kel''thuzad y su vida mortal. Dicen que aquel que se atreva a hacerle algo se condenará a sí mismo a... espera un segundo, ¿qué está haciendo ahí?' WHERE `ID`=29705;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 전시된 영상을 몇 번 두드립니다.', `MaleText_loc4`='%s敲了敲显示屏。', `MaleText_loc5`='%s用力敲打了幾次展覽品。', `MaleText_loc7`='%s golpea la imagen varias veces.' WHERE `ID`=29706;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐, 신경 쓰지 마라. 켈투자드가 아끼는 고양이한테 손을 대려고 하는 바보가 있으리라고는 절대로 생각하지 않으니 말이다.', `MaleText_loc4`='呃，别理它。我相信没有人敢伤害克尔苏加德最宝贝的宠物。', `MaleText_loc5`='好吧，別在意。我相信沒有人會笨到敢對科爾蘇加德心愛的寵物動手。', `MaleText_loc7`='Bueno, no importa. Estoy seguro de que nadie será tan insensato como para ponerle una mano encima a la preciada mascota de Kel''thuzad.' WHERE `ID`=29707;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서두르시오! 우르속의 시체에 재를 뿌리시오. 타락을 정화해야 하오!', `MaleText_loc4`='快！对乌索克的尸体使用灰烬。我们必须净化它！', `MaleText_loc5`='快點!在厄索克的屍體上使用這些灰燼。我們必須淨化它的腐化!', `MaleText_loc7`='¡Rápido! Usa las cenizas sobre el cadáver de Ursoc. ¡Debemos erradicar su corrupción!' WHERE `ID`=29708;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='슈르납... 슈르납... 요그사론!', `MaleText_loc4`='Shur''nab……shur''nab……尤格-萨隆！', `MaleText_loc5`='修那布...修那布...尤格薩倫!', `MaleText_loc7`='¡Shur''nab... shur''nab... Yogg-Saron!' WHERE `ID`=29709;
