UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하늘이 희생자의 피로 붉게 물들었다! 리치 왕께서 우리를 굽어보고 계신다! 너희가 휩쓸고 간 자리에는 재와 비탄만을 남겨라!', `MaleText_loc4`='天空变得血红！巫妖王在注视着我们。前进！苏醒的你们将带来毁灭，身后只留下灰烬和痛苦。', `MaleText_loc5`='死者的鮮血染紅了天空!巫妖王正注視著我們，爪牙們!讓你們的復甦，只留下灰燼與痛苦!', `MaleText_loc7`='¡Los cielos se tiñen de rojo con la sangre de los caídos! ¡El Rey Exánime nos protege! ¡Lacayos sólo destruyan y dejen un reguero de cenizas y tristeza!', `FemaleText_loc1`='하늘이 희생자의 피로 붉게 물들었다! 리치 왕께서 우리를 굽어보고 계신다! 너희가 휩쓸고 간 자리에는 재와 비탄만을 남겨라!', `FemaleText_loc4`='天空变得血红！巫妖王在注视着我们。前进！苏醒的你们将带来毁灭，身后只留下灰烬和痛苦。', `FemaleText_loc5`='死者的鮮血染紅了天空!巫妖王正注視著我們，爪牙們!讓你們的復甦，只留下灰燼與痛苦!', `FemaleText_loc7`='¡Los cielos se tiñen de rojo con la sangre de los caídos! ¡El Rey Exánime nos protege! ¡Lacayos sólo destruyan y dejen un reguero de cenizas y tristeza!' WHERE `ID`=29722;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='버텨라, 형제자매여! 빛은 승리할 것이다!', `MaleText_loc4`='兄弟姐妹们，坚持住！圣光必胜！', `MaleText_loc5`='兄弟姐妹們，絕不退後!聖光會戰勝一切!', `MaleText_loc7`='¡Firmes, hermanos y hermanas! ¡La Luz predominará!' WHERE `ID`=29723;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스컬지 군대가 다가온다!', `MaleText_loc4`='天灾军团来了！', `MaleText_loc5`='天譴軍接近了!', `MaleText_loc7`='¡Se aproximan los ejércitos de la Plaga!' WHERE `ID`=29724;
