UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일어나라, 나의 군대여! 저들을 처치해라!', `MaleText_loc4`='奴仆们，站起来吧！摧毁他们！', `MaleText_loc5`='甦醒吧，爪牙們!摧毀他們!', `MaleText_loc7`='¡Levántense, lacayos! ¡Destrúyanlos!' WHERE `ID`=29726;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대영주에게 무릎을 꿇어라!', `MaleText_loc4`='臣服于大领主的力量吧！', `MaleText_loc5`='向大領主屈膝吧!', `MaleText_loc7`='¡De rodillas ante el Alto Señor!' WHERE `ID`=29727;
