UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스컬지가 여기를 휩쓸 것이다!', `MaleText_loc4`='天灾军团将要毁灭这里！', `MaleText_loc5`='天譴軍團將毀滅此地!', `MaleText_loc7`='¡La Plaga destruirá este lugar!' WHERE `ID`=29729;
