UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고통 없는 삶이란 무의미하다!', `MaleText_loc4`='没有痛苦，生命就毫无意义！', `MaleText_loc5`='沒有痛苦，生命就毫無意義!', `MaleText_loc7`='¡La vida no vale nada sin el sufrimiento!' WHERE `ID`=29731;
