UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 이러지? 검을... 휘두를 수가...', `MaleText_loc4`='这是什么？！我的……我不能攻击了……', `MaleText_loc5`='這是什麼?!我的...我不能攻擊了...', `MaleText_loc7`='¡¿Qué es esto?! Mi... No puedo atacar…' WHERE `ID`=29735;
