UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제군들! 와서 나를 도와라!', `MaleText_loc4`='仆从们，快来帮我！', `MaleText_loc5`='手下們，過來幫助我!', `MaleText_loc7`='¡Lacayos, vengan a ayudarme!' WHERE `ID`=29742;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너는 졌다, 다리온!', `MaleText_loc4`='你赢不了的，达里安！', `MaleText_loc5`='你贏不了的，達瑞安!', `MaleText_loc7`='¡No tienes las de ganar, Darion!' WHERE `ID`=29743;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직도 모르겠나, 젊은이? 넌 네 아버지가 맞서 싸우던 적이 되었다! 저 겁쟁이 아서스처럼, 너도 어둠에, 분노에 무릎 꿇고 말았구나. 고문당하고 죽임당한 사람들의 고통을 먹고 사는 괴물이 되었어!', `MaleText_loc4`='你难道还不明白吗，孩子？你已经沦为了你父亲毕生都在对抗的存在！你已经和阿尔萨斯那个懦夫一样，甘心堕入黑暗……堕入仇恨……以害人为生！', `MaleText_loc5`='孩子，你難道還不明白嗎?你已經淪為你父親畢生所對抗的東西了!就像阿薩斯那個懦夫一樣，你任憑你自己被黑暗所吞噬...墜入仇恨...靠著折磨和殺害他人為生!', `MaleText_loc7`='¿No aprendiste nada, muchacho? ¡Eres todo contra lo que tu padre luchaba! Como ese cobarde, Arthas, te dejaste consumir por la oscuridad... el odio... ¡Alimentándote del sufrimiento de quienes torturaste y asesinaste!' WHERE `ID`=29744;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예배당 아래 뭐가 있는지 네 주인은 안다. 그래서 나타나지 않는 게지! 너와 죽음의 기사들만 사지로 보낸 것이다.', `MaleText_loc4`='你的主子知道礼拜堂下面埋藏着什么。所以他才不敢露面！你和你的死亡骑士就是他派来送死的，达里安。', `MaleText_loc5`='你的主子知道禮拜堂下面埋藏著什麼。所以他才不敢露面!你和你的死亡騎士就是他派來送死的，達瑞安。', `MaleText_loc7`='Tu amo sabe qué acecha debajo de la capilla. ¡Por eso no osa dar la cara! Te ha enviado a ti y a tus caballeros de la muerte para encontrar el fin, Darion.' WHERE `ID`=29745;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수천의 영혼이 느끼는 고통을 지금 너도 느낄 것이다! 너와 네 주인이 데려온 영혼의 괴로움을! 빛이 너를 갈기갈기 찢을 것이다...', `MaleText_loc4`='你现在感受到的，是上千个迷失灵魂的痛苦！他们都是牺牲在你和你的主人剑下的英灵！圣光会把你撕碎的，达里安！', `MaleText_loc5`='你現在感受到的，是上千個迷失靈魂的痛苦!他們都是犧牲在你和你的主人劍下的英靈!聖光會把你撕碎的，達瑞安!', `MaleText_loc7`='¡Lo que ahora sientes es la agonía de miles de almas perdidas! ¡Almas que tú y tu amo trajeron hacia aquí! ¡La Luz te despedazará, Darion!' WHERE `ID`=29746;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 힘이 약해집니다, 대영주님!', `MaleText_loc4`='我的力量正在减弱，大领主！', `MaleText_loc5`='大領主，我的力量在減弱!', `MaleText_loc7`='¡Mis poderes se desvanecen, Alto Señor!' WHERE `ID`=29747;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일이 일어나는 겁니까? 이게 무엇입니까?', `MaleText_loc4`='怎么回事？这是什么？', `MaleText_loc5`='發生了什麼事?這是什麼?', `MaleText_loc7`='¿Qué está ocurriendo? ¿Qué está pasando?' WHERE `ID`=29749;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛이 우리를 삼킵니다!', `MaleText_loc4`='圣光正在吞噬我们！', `MaleText_loc5`='我們被聖光給吞噬了!', `MaleText_loc7`='¡La Luz nos está consumiendo!' WHERE `ID`=29750;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 병사들이 죽어 나가고 있습니다!', `MaleText_loc4`='兵力骤减，部队即将崩溃！', `MaleText_loc5`='它正在消滅我們的部隊!', `MaleText_loc7`='¡Está diezmando nuestros ejércitos!' WHERE `ID`=29751;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 해야 합니까, 대영주님?', `MaleText_loc4`='大领主，我们该怎么办？', `MaleText_loc5`='我們該怎麼辦，大領主?', `MaleText_loc7`='¿Qué debemos hacer, Alto Señor?' WHERE `ID`=29752;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='집중할... 수가... 없...', `MaleText_loc4`='没法……集中精神……', `MaleText_loc5`='不能...集中...', `MaleText_loc7`='No puedo... concentrarme...' WHERE `ID`=29753;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 압도적이... 싸울 수 없...', `MaleText_loc4`='势不可挡……难以抵抗……', `MaleText_loc5`='它太強大...無法抵抗...', `MaleText_loc7`='Es sobrecogedor... no puedo luchar...' WHERE `ID`=29754;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='틀... 틀렸...', `MaleText_loc4`='快……快死了……', `MaleText_loc5`='死...死定了...', `MaleText_loc7`='M... Muero.' WHERE `ID`=29755;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예배당 앞으로 데려가라!', `MaleText_loc4`='带到礼拜堂前！', `MaleText_loc5`='把他們帶到禮拜堂前!', `MaleText_loc7`='¡Tráiganlos ante la capilla!' WHERE `ID`=29756;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바보 같으니! 너 때문에 우리가 함정에 걸렸다! 여기서 죽을 수는 없다, 모그레인!', `MaleText_loc4`='蠢货！你让我们落入了圈套！我可不想死在这里，莫格莱尼！', `MaleText_loc5`='蠢貨!你帶我們走進了陷阱!我才不會死在這裡，莫格萊尼!', `MaleText_loc7`='¡Insensato! ¡Nos has guiado a una trampa! ¡No moriré aquí, Mograine!' WHERE `ID`=29757;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 도망칩니다.', `MaleText_loc4`='%s逃跑了。', `MaleText_loc5`='%s落荒而逃。', `MaleText_loc7`='%s huye.' WHERE `ID`=29758;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='패배한 %s|1이;가; 티리온 폴드링 앞에 무릎을 꿇습니다.', `MaleText_loc4`='%s被提里奥·弗丁击败，跪倒在地。', `MaleText_loc5`='%s敗倒在提里奧·弗丁面前。', `MaleText_loc7`='%s se arrodilla derrotado ante Tirion Vadín.' WHERE `ID`=29759;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='포기해라, 죽음의 기사여. 우리는 졌다. 이곳엔... 빛이 가득해... 희망이 없다...', `MaleText_loc4`='死亡骑士们，撤退。我们战败了……这里的……圣光之力…………我们输定了……', `MaleText_loc5`='死亡騎士們，撤退。我們戰敗了...這裡的...聖光之力...我們輸定了...', `MaleText_loc7`='Retírense, caballeros de la muerte. Perdimos. La Luz... este lugar... sin esperanzas…' WHERE `ID`=29760;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='닥쳐라, 늙은이. 그 말이 마지막이 될지도 모르니...', `MaleText_loc4`='省点力气吧，老家伙。这将是你的最后一口气息了。', `MaleText_loc5`='省點力氣，老傢伙。留著說遺言吧!', `MaleText_loc7`='Conserva el aliento, anciano. Podría ser el último que exhales.' WHERE `ID`=29761;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다리온! 사랑하는 내 아들아!', `MaleText_loc4`='我的儿子！最让我自豪的孩子！', `MaleText_loc5`='吾兒!我親愛的孩子!', `MaleText_loc7`='¡Hijo mío! ¡Mi precioso niño!' WHERE `ID`=29762;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파멸의 인도자다!', `MaleText_loc4`='灰烬使者！', `MaleText_loc5`='灰燼使者!', `MaleText_loc7`='¡Crematoria!', `FemaleText_loc1`='파멸의 인도자다!', `FemaleText_loc4`='灰烬使者！', `FemaleText_loc5`='灰燼使者!', `FemaleText_loc7`='¡Crematoria!' WHERE `ID`=29763;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이... 이런 일이...', `MaleText_loc4`='不……不可能……', `MaleText_loc5`='不...不可能...', `MaleText_loc7`='No... No puede ser...', `FemaleText_loc1`='꿈... 꿈이 아닐까...', `FemaleText_loc4`='不……不可能……', `FemaleText_loc5`='不...不可能...', `FemaleText_loc7`='No... No puede ser...' WHERE `ID`=29764;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경례하라!', `MaleText_loc4`='低下你们的头！', `MaleText_loc5`='低下頭!', `MaleText_loc7`='¡Agachad la cabeza!', `FemaleText_loc1`='경례하라!', `FemaleText_loc4`='低下你们的头！', `FemaleText_loc5`='低下頭!', `FemaleText_loc7`='¡Agachad la cabeza!' WHERE `ID`=29765;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경의를 표해라!', `MaleText_loc4`='低下你们的头！', `MaleText_loc5`='低下頭!', `MaleText_loc7`='¡Agachad la cabeza!', `FemaleText_loc1`='경의를 표해라!', `FemaleText_loc4`='低下你们的头！', `FemaleText_loc5`='低下頭!', `FemaleText_loc7`='¡Agachad la cabeza!' WHERE `ID`=29766;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아버지!', `MaleText_loc4`='父亲！', `MaleText_loc5`='父親!', `MaleText_loc7`='¡Padre!' WHERE `ID`=29767;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으아! 이게... 대체...', `MaleText_loc4`='啊……这……这是……', `MaleText_loc5`='啊...這...這是...', `MaleText_loc7`='Argh... qué... está…' WHERE `ID`=29768;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아버지! 돌아오셨군요!', `MaleText_loc4`='父亲，您回来了！', `MaleText_loc5`='父親，你回來了!', `MaleText_loc7`='¡Padre, has regresado!' WHERE `ID`=29769;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 오래 떠나 계셨어요. 전 그만...', `MaleText_loc4`='您去了好久啊，父亲。我还以为……', `MaleText_loc5`='你離開了好久，父親。我以為...', `MaleText_loc7`='Ha pasado tanto tiempo, Padre. Pensé que…' WHERE `ID`=29770;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 아버지를 끌어안습니다.', `MaleText_loc4`='%s拥抱了他的父亲。', `MaleText_loc5`='%s擁抱他的父親。', `MaleText_loc7`='%s abraza a su padre.' WHERE `ID`=29771;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 엉엉 웁니다.', `MaleText_loc4`='%s哭了。', `MaleText_loc5`='%s哭了出來。', `MaleText_loc7`='%s llora.' WHERE `ID`=29772;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌아오는 게 당연하잖니, 다리온. 내 집이, 가족이 여기 있는데.', `MaleText_loc4`='没有什么能够阻止我回家，达里安。我绝不会离开自己的家乡和亲人。', `MaleText_loc5`='沒什麼能阻止我回來，阻止我回到自己的家和家人身邊，達瑞安。', `MaleText_loc7`='Nada podría apartarme de aquí, Darion. Ni de mi hogar ni de mi familia.' WHERE `ID`=29773;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아버지, 함께 전장에 나가서 싸우고 싶어요. 저도 싸우겠어요! 가만히 있긴 싫어요!', `MaleText_loc4`='父亲，我也想加入部队，和您一起抵抗亡灵。我也要战斗，不能再袖手旁观了！', `MaleText_loc5`='父親，我想和你一同加入對抗不死族的戰爭。我想戰鬥!我無法坐視不管了!', `MaleText_loc7`='Padre, quiero luchar en la guerra contra los no-muertos. ¡Ya no puedo quedarme de brazos cruzados!' WHERE `ID`=29774;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다리온 모그레인, 넌 이제 겨우 칼을 들 수 있는 나이란다. 로데론의 언데드 군대와 전투라니? 네가 죽으면 어쩌란 말이냐. 생각만 해도 난...', `MaleText_loc4`='达里安·莫格莱尼，你还没有到可以握剑的年龄呢，更不用说去跟肆虐洛丹伦的亡灵作战了！我不能失去你，想都不敢想……', `MaleText_loc5`='達瑞安·莫格萊尼，你還不到持劍的年紀，遑論與羅德隆的不死大軍一戰!我不能夠失去你，連想都不敢想...', `MaleText_loc7`='Darion Mograine, ¡apenas tienes edad para blandir una espada, y menos luchar contra las hordas de no-muertos de Lordaeron! Jamás soportaría perderte.' WHERE `ID`=29775;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 죽는다면, 제 의지에 따라 죽겠어요! 언데드 무리와 싸우다가 말입니다! 죽는다면, 아버지와 함께 죽겠어요!', `MaleText_loc4`='父亲，就算死，我也要在和亡灵军团的战斗中光荣地战死！就算死，我也要和您死在一起！', `MaleText_loc5`='如果我要死，父親，我寧願起身反抗不死軍團而死!如果要死，我寧願和你同生共死!', `MaleText_loc7`='¡Si muero, Padre, prefiero que sea de pie, enfrentando las legiones de no-muertos! ¡Si muero, déjame morir contigo!' WHERE `ID`=29776;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얘야... 언젠가 네가 파멸의 인도자를 휘두를 날이 올 게다. 검을 들고, 너는 온 세상을 누비며 정의를 수호하겠지. 난 믿어 의심치 않는단다. 그날이 오면, 너는 우리 모두의 자랑이 되고 로데론은 내 아들 덕에 더 살기 좋은 땅이 될 테지. 하지만 아들아, 아직은 때가 아니다.', `MaleText_loc4`='我的儿子啊，你总有一天会举起灰烬使者，凭借它的力量在这片土地上匡扶正义。我坚信，当那一天终于到来的时候，你会为我们的人民带来荣光，洛丹伦将因你而变得更加美好。但，我的孩子，不是今天。', `MaleText_loc5`='吾兒啊，有一天，你將能駕馭灰燼使者，以它在這片大地上弘揚正義。我深信當這天到來的時候，我們的人民將以你為榮。也因為你，羅德隆會成為更美好的地方。但是，吾兒，你持劍之日尚未到來。', `MaleText_loc7`='Hijo mío, llegará el día en que empuñarás la Portadora de Cenizas y, con ella, repartirás justicia en toda esta tierra. No dudo de que entonces enorgullecerás a nuestro pueblo y que Lordaeron será un lugar mejor gracias a ti. Pero, hijo mío, hoy no es ese día.' WHERE `ID`=29777;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잊지 말거라...', `MaleText_loc4`='不要忘记……', `MaleText_loc5`='不要忘記...', `MaleText_loc7`='No… olvides…' WHERE `ID`=29778;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감동적이군...', `MaleText_loc4`='真感人……', `MaleText_loc5`='真感人...', `MaleText_loc7`='Conmovedor…' WHERE `ID`=29779;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그는 내 것이지...', `MaleText_loc4`='他现在归我了……', `MaleText_loc5`='他是我的了...', `MaleText_loc7`='Ahora es mío…' WHERE `ID`=29780;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌... 나를 배신했다! 우리 모두를 배신했다! 모그레인의 분노에 맞서 보아라!', `MaleText_loc4`='你……背叛了我。你背叛了我们所有人，怪物！感受莫格莱尼的力量吧。', `MaleText_loc5`='你...背叛了我。你背叛了我們所有人，怪物!感受莫格萊尼的力量吧。', `MaleText_loc7`='Me... traicionaste. ¡Nos traicionaste a todos, monstruo! ¡Enfrenta el poder de Mograine!' WHERE `ID`=29781;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='애처롭구나...', `MaleText_loc4`='真可怜……', `MaleText_loc5`='真可悲...', `MaleText_loc7`='Patético...' WHERE `ID`=29782;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 지독한 괴물이다, 아서스!', `MaleText_loc4`='阿尔萨斯，你这该死的怪物！', `MaleText_loc5`='你這受天譴的怪物，阿薩斯!', `MaleText_loc7`='¡Eres un monstruo maldito, Arthas!' WHERE `ID`=29783;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 폴드링. 내가 그들을 사지에 내보냈지. 가치 없는 목숨들이다. 하지만 네 목숨은...', `MaleText_loc4`='你说对了，弗丁。我就是派他们去送死的。他们的生命毫无意义，但你的不同……', `MaleText_loc5`='你說對了，弗丁。我就是派他們去送死的。他們的生命毫無意義，但你的不同...', `MaleText_loc7`='Tenías razón, Fordring. Sí los envié a morir. Sus vidas no importan, pero la tuya…' WHERE `ID`=29784;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위대한 티리온 폴드링을 쥐구멍에서 끌어내는 게 이렇게 쉬울 줄이야. 성기사여, 넌 이제 허허벌판에 섰다. 무엇도 널 지켜줄 순 없어...', `MaleText_loc4`='把伟大的提里奥·弗丁揪出来还真是容易啊。你已经暴露了，圣骑士。谁也救不了你了……', `MaleText_loc5`='把偉大的提里奧·弗丁從藏身之處給引出來可真容易啊。你讓自己暴露了出來，聖騎士。誰也救不了你...', `MaleText_loc7`='Qué sencillo fue sacar al gran Tirion Fordring de su escondite. Quedaste al descubierto, paladín. Nada te salvará…' WHERE `ID`=29785;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 숨 막히는 소리를 냅니다.', `MaleText_loc4`='%s喘着气。', `MaleText_loc5`='%s氣喘吁吁。', `MaleText_loc7`='%s intenta coger aire.' WHERE `ID`=29786;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공격!!', `MaleText_loc4`='进攻！！！', `MaleText_loc5`='進攻!!', `MaleText_loc7`='¡ATAQUEN!' WHERE `ID`=29787;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최후의 날이다!', `MaleText_loc4`='世界末日！', `MaleText_loc5`='毀天滅地!', `MaleText_loc7`='¡APOCALIPSIS!' WHERE `ID`=29788;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기억하거라... 항상...', `MaleText_loc4`='永远……记住……', `MaleText_loc5`='記得...永遠...', `MaleText_loc7`='Recuerda... siempre...' WHERE `ID`=29789;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너무나 존귀한 어둠의 영역이여, 우리에게 은총을 내려주사 그 백성 한 사람을 나타나게 하소서.', `FemaleText_loc4`='来自阴影世界的居民，请在我们面前现身吧。', `FemaleText_loc5`='最親愛的暗影國度，你們居民之一的出現讓我們倍感光榮。', `FemaleText_loc7`='Querido reino de las sombras, bendícenos con la presencia de uno de tus muchos ciudadanos.' WHERE `ID`=29790;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어둠의 영역에서 온 또 다른 존재를 따뜻하게 맞이할 필요는 없겠죠...', `FemaleText_loc4`='欢迎来自阴影世界的另一位居民……', `FemaleText_loc5`='讓我們冷酷的歡迎另一位暗影國度的居民...', `FemaleText_loc7`='Demos una fría bienvenida a otro habitante del reino de la sombras...' WHERE `ID`=29791;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='앞으로 또 어떤 짐승 같은 존재가 우리를 기다리고 있을지...', `FemaleText_loc4`='让我们瞧瞧接下来是什么野兽……', `FemaleText_loc5`='還有什麼野獸沒現身呢...', `FemaleText_loc7`='¿Qué bestias nos esperan...?' WHERE `ID`=29792;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아직 배울 것이 많이 남았어요. 다음 주제로 넘어가 보지요...', `FemaleText_loc4`='你们对阴影世界的了解还远远不够……', `FemaleText_loc5`='還有許多的課程等著我們，朝下一個目標邁進吧...', `FemaleText_loc7`='Aún quedan muchas lecciones que aprender, pasemos a la siguiente asignatura...' WHERE `ID`=29793;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다음 주제는...', `FemaleText_loc4`='继续……', `FemaleText_loc5`='繼續...', `FemaleText_loc7`='Avanzando...' WHERE `ID`=29794;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='해골이에요. 단순한 노리갯감이죠. 하지만, 해골로도 배울 수 있는 것이 있어요.', `FemaleText_loc4`='骷髅。即便是骨头架子这样的玩物，我们也能从中学到新的知识。', `FemaleText_loc5`='骷髏。只不過是玩物，但也有許多東西值得學習。', `FemaleText_loc7`='Esqueletos. Simples juguetes, pero, incluso ahí, hay lecciones que aprender.' WHERE `ID`=29795;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='해골 마법사예요. 우리 힘을 시험해보기에 알맞은 상대로군요.', `FemaleText_loc4`='骷髅法师。这是展示某些技能的绝好机会。', `FemaleText_loc5`='骷髏法師。展現我們力量用途的絕佳機會。', `FemaleText_loc7`='Magos esqueletos. Una oportunidad perfecta para probar la utilidad de algunos de nuestros poderes.' WHERE `ID`=29796;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이상하군요, 어둠의 영역에 이들이 남아 있으리라고는 생각하지 않았거든요. 사도 여러분 조심하세요, 이 녀석은 조금 위험하니까요.', `FemaleText_loc4`='奇怪，我还以为它们在阴影世界已经绝迹了呢。当心点，它不容易对付的。', `FemaleText_loc5`='怪了，我沒想過暗影國度中還有這些生物留下來。小心，侍徒，這個可危險得多。', `FemaleText_loc7`='Extraño, pensé que no quedaba ninguno de esos en el Reino de las Sombras. Cuidado, discípulos, este es un poco más peligroso.' WHERE `ID`=29797;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사도 여러분... 시간을 들여서 연구하다 보면 많은 치유 주문이 우리 공격이 퇴행하여 만들어진 결과임을 파악할 거예요.', `FemaleText_loc4`='不过正好……看清楚，这就是我们的敌人，这就是死亡骑士的敌人。我们是孤独的死亡骑士，我们必须战斗。', `FemaleText_loc5`='侍徒啊...時間久了，你會發現許多治療法術敵不過我們的衰亡攻擊。', `FemaleText_loc7`='Discípulos... con el tiempo os daréis cuenta de que muchos hechizos de sanación sucumben ante la degeneración de nuestros ataques.' WHERE `ID`=29798;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어떤 치유사들은 우리가 이미 터득한 질병에 맞서는 지식조차 갖추지 못했어요.', `FemaleText_loc4`='我们能够使用暗影的能量封印住这些治疗者的能力。', `FemaleText_loc5`='有些醫者缺乏相關知識來反制我們所精通的疾病。', `FemaleText_loc7`='Algunos sanadores no poseen el conocimiento para enfrentarse a las enfermedades que dominamos.' WHERE `ID`=29799;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지식이 부족하다는 것도 그저 여러 약점 중 하나일 뿐이지요. 죽음 그 자체가 지닌 힘에 맞설 수 있는 가망성은 거의 없어요.', `FemaleText_loc4`='暗影的能量会反噬他们的能力，就这样将这个投影赶回翡翠梦境里去。', `FemaleText_loc5`='這些知識的缺乏只是眾人中的弱點之一。當面對死亡本身時是幾乎毫無希望。', `FemaleText_loc7`='Esta falta de conocimiento solo es una debilidad más entre otras muchas. Hay poca esperanza contra el poder de la propia muerte.' WHERE `ID`=29800;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='티리온!', `MaleText_loc4`='提里奥！', `MaleText_loc5`='提里奧!', `MaleText_loc7`='¡Tirion!' WHERE `ID`=29801;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 쓰러집니다.', `MaleText_loc4`='%s倒下了。', `MaleText_loc5`='%s倒下。', `MaleText_loc7`='%s se desploma.' WHERE `ID`=29802;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아서스!', `MaleText_loc4`='阿尔萨斯！！！', `MaleText_loc5`='阿薩斯!!!!', `MaleText_loc7`='¡¡ARTHAS!!' WHERE `ID`=29803;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 뭐지?', `MaleText_loc4`='这是什么？', `MaleText_loc5`='這是什麼?', `MaleText_loc7`='¿Qué es esto?' WHERE `ID`=29804;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 미친 듯이 웃습니다.', `MaleText_loc4`='%s狂笑起来。', `MaleText_loc5`='%s發了瘋似的狂笑。', `MaleText_loc7`='%s ríe de forma maníaca.' WHERE `ID`=29805;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한심하기 짝이 없는 솜씨로구나. 구울도 이런 무기는 거부할 게다.', `MaleText_loc4`='锻造手艺也太差劲了吧。连食尸鬼都不屑使用这件武器。', `MaleText_loc5`='這個東西的手藝真糟糕。就算食屍鬼也不會想用它。', `MaleText_loc7`='La calidad de este trabajo es patética. No sirve ni para que lo use un necrófago.' WHERE `ID`=29806;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이걸 무기라고 할 수 있나? 제대로 쥐고 휘둘러도 제 모양을 유지하는지 한번 해 봐라. 그러고 나면 일을 어떻게 하는지 깨달을지도 모르지.', `MaleText_loc4`='你管这玩意儿叫武器？再让我看见这样的货色，我就把你扔进锅炉和金属锭一块儿熔了。或许那时你才会明白该如何努力。', `MaleText_loc5`='這也可以叫武器?把它收起來，小鬼。我等著看你跟他們一樣被抬回來。也許到時候你才會知道該怎麼努力工作。', `MaleText_loc7`='¿A esto llamas un arma? Sigue así, canalla y me ocuparé de que vuelvas como uno de ellos. Quizás entonces aprendas a esforzarte en ello.' WHERE `ID`=29807;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은빛 여명회가 쓰는 무기가 이딴 식이었음 좋겠군. 그러면 녀석들은 순식간에 무너질 텐데.', `MaleText_loc4`='如果银色黎明的武器都是这种品质的话，那他们迟早会完蛋。', `MaleText_loc5`='如果銀色黎明武器的品質只有這樣，那麼他們的潰敗只是時間的問題罷了。', `MaleText_loc7`='Si esta es la calidad que uno puede esperar de un arma de El Alba Argenta, entonces solo es cuestión de tiempo el que caigan.' WHERE `ID`=29808;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이걸 무기로 쓰느니 포크를 쥐겠다. 다시 만들어!', `MaleText_loc4`='餐叉都比这玩意儿坚硬。重新铸造！', `MaleText_loc5`='我看過的叉子都比這東西堅固，給我重鑄一次!', `MaleText_loc7`='He visto tenedores más fuertes que esto. ¡Vuelve a forjarlo!' WHERE `ID`=29809;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혼란스러운가 보군, 필멸자야. 칼은 깊숙이 찌르라고 있는 거지 따끔하라고 있는 게 아니다! 더 날카롭게 갈아!', `MaleText_loc4`='你是不是没搞清楚？这把武器是用来捅人的，不是挠痒痒的！重新打磨！', `MaleText_loc5`='你是不是昏頭了，凡人?金屬那端是拿來殺人的，不是拿來搔癢的!重新磨利它!', `MaleText_loc7`='¿Acaso estás confuso, mortal? ¡La parte de metal es para apuñalar, no pinchar! ¡Afílalo otra vez!' WHERE `ID`=29810;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 언데드가 되어도 리치 왕을 섬길 자격이 안 되는구나. 제대로 일하지 않으면 이 세계를 영원히 떠나게 해 주마. 또 나를 실망시키면, 연료 삼아 저 안에 처넣을 테다.', `MaleText_loc4`='你就算变成亡灵，也没那个能耐为巫妖王效力。手脚再勤快点，我或许会考虑让你彻底摆脱这个世界。否则，你就等着进熔炉吧。', `MaleText_loc5`='就算變成了不死生物，你還是不配服侍巫妖王。努力工作，我也許到時候會把你從這個世界中永遠釋放出去。讓我失望，我就用你的血肉來當燃料!', `MaleText_loc7`='No eres adecuado para servir al Rey Exánime ni siquiera en la no-muerte. Trabaja duro y puede que te libere de este mundo. Fállame y avivarás las llamas con tu carne.' WHERE `ID`=29811;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어... 집에...', `MaleText_loc4`='终于……回家了……', `MaleText_loc5`='終於...回家了...', `MaleText_loc7`='Al fin... en casa...' WHERE `ID`=29812;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가... 돌아왔습니다... 주인님...', `MaleText_loc4`='我……回来了……主人……', `MaleText_loc5`='我...回來了...主人...', `MaleText_loc7`='Yo... he vuelto... amo...' WHERE `ID`=29813;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 돌아왔습니다... 주인님. 당신의 충실한 종이...', `MaleText_loc4`='我回来了……主人。我是您……忠实的仆从。', `MaleText_loc5`='我回來了...主人。我是您...最忠心的僕人。', `MaleText_loc7`='Yo volver... amo. Yo... sirviente leal.' WHERE `ID`=29814;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님... 너무 오랫동안... 자리를 비워... 죄송합니다...', `MaleText_loc4`='对不起……主人……我离开了……这么久。', `MaleText_loc5`='抱歉...我去了...那麼久...主人。', `MaleText_loc7`='Perdón... yo fuera... mucho... amo.' WHERE `ID`=29815;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='구울은 너무 빨리 쓸모가 없어져서 종종 곤란한 상황이 되곤 하죠. 죽음과 부패로 구울을 처리합시다.', `FemaleText_loc4`='食尸鬼的问题在于，他们很快就会丧失利用价值。让我们用死亡和腐烂解决他们吧。', `FemaleText_loc5`='我常常遇到食屍鬼的問題，他們太沒用了。讓我們用死亡和腐化讓他們恢復原貌吧。', `FemaleText_loc7`='El problema que le encuentro a los necrófagos es que dejan de ser útiles demasiado rápido. Dejemos que la muerte y la descomposición reclame a estos.' WHERE `ID`=29816;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가끔, 구울 시체가 구울 그 자체보다 더 유용하기도 해요.', `FemaleText_loc4`='有时候，食尸鬼的尸体比他们本身更有用。', `FemaleText_loc5`='有時候，食屍鬼的屍體比他們自己還要有用。', `FemaleText_loc7`='A veces sus cadáveres pueden ser más útiles que cuando eran necrófagos.' WHERE `ID`=29817;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='음...', `FemaleText_loc4`='嗯……', `FemaleText_loc5`='嗯...', `FemaleText_loc7`='Mmm...' WHERE `ID`=29818;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='딱하네요.', `FemaleText_loc4`='真是不幸。', `FemaleText_loc5`='很不幸。', `FemaleText_loc7`='Desafortunado.' WHERE `ID`=29819;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아픕니다...', `MaleText_loc4`='痛……', `MaleText_loc5`='真痛啊...', `MaleText_loc7`='Duele...' WHERE `ID`=29820;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저... 잘못했나요?', `MaleText_loc4`='我……不好？', `MaleText_loc5`='是我...不對嗎?', `MaleText_loc7`='¿Yo... mal?' WHERE `ID`=29821;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님?', `MaleText_loc4`='主人？', `MaleText_loc5`='主人?', `MaleText_loc7`='¿Amo?' WHERE `ID`=29822;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 빛바랜 골렘을 무너뜨리려고 합니다!', `MaleText_loc4`='%s击碎了脆弱的魔像！', `MaleText_loc5`='%s準備粉碎他的易碎的魔像!', `MaleText_loc7`='¡%s se prepara para destrozar sus gólems frágiles!' WHERE `ID`=29823;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그날이 오늘은 아니다...', `MaleText_loc4`='但，不是今天……', `MaleText_loc5`='我持劍之日未到...', `MaleText_loc7`='Eso será otro día…' WHERE `ID`=29824;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이럴 수가...', `MaleText_loc4`='这不可能...', `MaleText_loc5`='不可能...', `MaleText_loc7`='Imposible...' WHERE `ID`=29825;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이걸로... 끝난 건... 아니다!', `MaleText_loc4`='还……没有完呢！', `MaleText_loc5`='還...沒有完呢!', `MaleText_loc7`='Esto... no ha... acabado…' WHERE `ID`=29826;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음번엔 성스러운 땅의 도움은 받지 못할 게다...', `MaleText_loc4`='下一次，我们就不会在这片圣地上决战了，圣骑士。', `MaleText_loc5`='下一次，我們就不會在這片聖地上決戰了，聖騎士。', `MaleText_loc7`='Cuando nos reencontremos no será en suelo sagrado, paladín.' WHERE `ID`=29827;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여러분의 대마법 보호막은 제 것만큼 강력하진 않지만, 어쨌거나 수많은 적에게서 마법 공격을 받을 때 대단히 귀중한 보호 수단이지요.', `FemaleText_loc4`='和我相比，你们施放的法术还不够强大，但是在密集的魔法攻击下，反魔法护罩依然能起到完美的保护作用。', `FemaleText_loc5`='你的法術也許不若在我這來的那麼有效，但是你仍可發覺反魔法護罩在對抗大量魔法攻擊時是非常有價值的。', `FemaleText_loc7`='Tus hechizos no serán tan poderosos como los míos, pero descubrirás que los caparazones antimagia no tienen precio contra un gran número de ataques mágicos.' WHERE `ID`=29828;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대마법 보호막으로 흡수한 마력으로 여러분의 기술을 사용해 적을 공격할 수도 있습니다.', `FemaleText_loc4`='你们可以利用护罩吸收的法术能量展开反击。', `FemaleText_loc5`='你用護罩所吸收的法術力量可以利用你其他的能力進行攻擊。', `FemaleText_loc7`='La energía que absorbes de los hechizos con tu caparazón puede usarse para responder con otros de tus ataques.' WHERE `ID`=29829;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그러니... 마법사들이 우리를 두려워하는 게 당연하지요. 그 공포를 이용하세요, 사도 여러분.', `FemaleText_loc4`='法师害怕我们……这是有原因的。你们要学会利用这种恐惧。', `FemaleText_loc5`='法師懼怕我們...是有原因的。玩弄這份恐懼吧，侍徒。', `FemaleText_loc7`='Los magos temen a los de nuestra clase... con razón. Jugad con este miedo, discípulos.' WHERE `ID`=29830;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법의 목장식을 잃어버렸습니다!', `MaleText_loc4`='我的迷惑项圈不见了！', `MaleText_loc5`='我把我的蠱惑頸飾搞丟了!', `MaleText_loc7`='¡He perdido mi gargantilla embrujada!', `FemaleText_loc1`='마법의 목장식을 잃어버렸어요!', `FemaleText_loc4`='我的迷惑项圈不见了！', `FemaleText_loc5`='我把我的蠱惑頸飾搞丟了!', `FemaleText_loc7`='¡He perdido mi gargantilla embrujada!' WHERE `ID`=29831;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 전투 태세로 전환합니다!', `MaleText_loc4`='%s切换到战斗姿态！', `MaleText_loc5`='%s切換至戰鬥姿態!', `MaleText_loc7`='¡%s cambia a Actitud de batalla!' WHERE `ID`=29832;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 광폭 태세로 전환합니다!', `MaleText_loc4`='%s切换到狂暴姿态！', `MaleText_loc5`='%s切換至狂暴姿態!', `MaleText_loc7`='¡%s cambia a Actitud rabiosa!' WHERE `ID`=29833;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 방어 태세로 전환합니다!', `MaleText_loc4`='%s切换到防御姿态！', `MaleText_loc5`='%s切換至防禦姿態!', `MaleText_loc7`='¡%s cambia a Actitud Defensiva!' WHERE `ID`=29834;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일어나라, 다리온. 내 말을 들어라...', `MaleText_loc4`='站起来，达里安，你听着……', `MaleText_loc5`='起身吧，達瑞安，仔細聽好...', `MaleText_loc7`='Levántate, Darion, y escucha.' WHERE `ID`=29835;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두려워하지 마라, 아가야... 차가운 죽음의 포옹을 받아들여라...', `MaleText_loc4`='别害怕……接受死亡的冰冷拥抱吧……', `MaleText_loc5`='不要害怕，孩子...迎向死亡的冰冷擁抱吧...', `MaleText_loc7`='No te asustes, pequeño... da la bienvenida al frío abrazo de la muerte...' WHERE `ID`=29836;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실패의 대가란 그런 것이다.', `MaleText_loc4`='这就是失败的代价。', `MaleText_loc5`='這就是失敗的代價。', `MaleText_loc7`='Tal es el precio del fracaso.' WHERE `ID`=29837;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나약함이란 죽음으로 보상받는 법이다.', `MaleText_loc4`='懦弱的后果就是死亡。', `MaleText_loc5`='死亡正是你無能的最好賞賜。', `MaleText_loc7`='La muerte es la recompensa a tu debilidad.' WHERE `ID`=29838;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 기억력이 나쁘군.', `MaleText_loc4`='你的记性太差劲了。', `MaleText_loc5`='你的記憶力差勁透了。', `MaleText_loc7`='Tu retentiva ha sido pobre.' WHERE `ID`=29839;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘했다.', `MaleText_loc4`='很好。', `MaleText_loc5`='做得好。', `MaleText_loc7`='Buen trabajo.' WHERE `ID`=29840;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 배울 게 많이 남았다. 사도여, 연구를 계속해라.', `MaleText_loc4`='要学习的知识还有很多。继续努力吧。', `MaleText_loc5`='侍徒，你要學的還有很多，回去好好用功吧。', `MaleText_loc7`='Todavía has de aprender más, discípulo. Vuelve a tus estudios.' WHERE `ID`=29841;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가르친 걸 잘 익혔군. 계속 정진하라, 사도여.', `MaleText_loc4`='你掌握得不错。继续努力吧。', `MaleText_loc5`='你學得很好。繼續修行吧，侍徒。', `MaleText_loc7`='Has aprendido bien. Continúa tu senda, discípulo.' WHERE `ID`=29842;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 끔찍한 비극을 목격했다. 선한 이의 피가 이 땅을 적셨다! 명예로운 기사들이 죽어갔다. 자신을, 우리를 지키기 위해...', `MaleText_loc4`='我们见证了一场可怕的悲剧。善良人的鲜血早已将这整片土地染红！无数高贵而英勇的骑士，为了保卫我们而牺牲在这里！', `MaleText_loc5`='我們親眼目睹一齣可怕的悲劇。善良人們的鮮血染紅了這片土地!無數高貴的騎士，為了保護我們性命而犧牲!', `MaleText_loc7`='Hemos presenciado una horrenda tragedia. En este suelo se ha derramado sangre de hombres buenos! ¡Honorables caballeros, caídos en defensa de sus vidas... y las nuestras!' WHERE `ID`=29843;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시작이 좋군. 자리로 돌아가라, 사도여.', `MaleText_loc4`='这是一个好的开始。继续努力吧。', `MaleText_loc5`='好的開始。回去吧，侍徒。', `MaleText_loc7`='Un buen comienzo. Vuelve, discípulo.' WHERE `ID`=29844;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 비극을 되새겨, 우리는 목적을 위해 더욱 정진해야 한다!', `MaleText_loc4`='我们永远不会忘记这一幕，我们仍然需要保持警惕！', `MaleText_loc5`='這樣的事情不可以被遺忘，我們必須時時警惕自己。', `MaleText_loc7`='¡Y aunque eso jamás se podrá olvidar, debemos estar alertas en favor de nuestra causa!' WHERE `ID`=29845;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕은 죗값을 치러야 한다. 리치 왕이 우리 세계를 파괴하지 못하게 해야 한다.', `MaleText_loc4`='巫妖王必须为他的所作所为付出代价，我们绝不能再让他继续破坏这个世界。', `MaleText_loc5`='巫妖王必須為他的所作所為付出代價，我們決不能再讓他繼續破壞這個世界。', `MaleText_loc7`='El Rey Exánime debe pagar por sus actos y no se debe permitir que provoque más destrucción en nuestro mundo.' WHERE `ID`=29846;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 자리에서 약속한다, 형제자매여. 리치 왕은 패배할 것이다! 오늘 여기서, 나는 연합을 선언한다.', `MaleText_loc4`='兄弟们，姐妹们，我向你们发誓：巫妖王一定会被消灭！今天，我们大家要重新团结起来。', `MaleText_loc5`='兄弟姊妹們，我在此向你們承諾:巫妖王一定會被擊敗!今天，我們要團結一心。', `MaleText_loc7`='Les prometo esto, hermanos y hermanas: ¡El Rey Exánime será derrotado! En este día, convoco una unión.' WHERE `ID`=29847;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은빛 여명회와 은빛 성기사단이 하나가 될 것이다! 수많은 이가 실패했어도, 우리는 승리하리라!', `MaleText_loc4`='银色黎明和白银之手骑士团将在此合二为一！我们一定可以完成前人未尽的事业！', `MaleText_loc5`='銀色黎明和白銀之手騎士團將合而為一!我們將能完成前人未盡的事業!', `MaleText_loc7`='¡El Alba Plateada y la Orden de Mano Plateada se unirán! ¡Triunfaremos en lo que muchos, anteriormente, han fracasado!' WHERE `ID`=29848;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 아서스와 싸우고, 얼음왕관의 벽을 무너뜨릴 것이다!', `MaleText_loc4`='我们要继续抗争阿尔萨斯，我们终将推倒冰冠冰川的城墙！', `MaleText_loc5`='我們將向阿薩斯宣戰，我們將撕裂寒冰皇冠的高牆!', `MaleText_loc7`='¡Lucharemos contra Arthas y derribaremos las murallas de la Corona de Hielo!' WHERE `ID`=29849;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은빛십자군이 간다. 기다려라, 아서스!', `MaleText_loc4`='阿尔萨斯，银色北伐军向你宣战！', `MaleText_loc5`='阿薩斯，銀白十字軍向你宣戰!', `MaleText_loc7`='¡La Cruzada Plateada viene por ti, Arthas!' WHERE `ID`=29850;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칠흑의 기사단도 함께할 것이다. 비록 너희 사이에 우리 자리는 없겠지만, 리치 왕을 끝장낼 때까지 싸울 것이다! 맹세한다!', `MaleText_loc4`='这也是黑锋骑士们的心愿……尽管在你们的世界中已没有立足之地，但我们仍要为打倒巫妖王而战斗。我在此立誓！', `MaleText_loc5`='黯刃騎士團也是一樣...雖然我們族類在你的世界無處容身，我們還是會誓死消滅巫妖王。我以此為誓!', `MaleText_loc7`='Lo mismo para los Caballeros de la Espada de Ébano. Aunque nuestra casta no quepa en tu mundo, lucharemos para darle fin al Rey Exánime. ¡Lo juro!' WHERE `ID`=29851;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 동굴 위로 올라갑니다!', `MaleText_loc4`='%s沿着隧道爬了过来！', `MaleText_loc5`='%s自隧道中竄出!', `MaleText_loc7`='¡%s avanza por el túnel!' WHERE `ID`=29852;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 있습니다, $n.$B$B자, 부탁이니 지금 눈앞에 닥친 일에 집중 좀 해주십시오.', `MaleText_loc4`='给，$n。$b$b麻烦你集中精神，完成任务……', `MaleText_loc5`='拿去吧，$n。$b$b現在，拜託你，馬上將你的注意力放回手上的任務吧...', `MaleText_loc7`='Aquí estás, $n.$b$bAhora vuelve a concentrarte en tu tarea...' WHERE `ID`=29853;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구울! 이리로 잠시 와 봐!', `MaleText_loc4`='食尸鬼！过来！', `MaleText_loc5`='食屍鬼!來這待一會兒!', `MaleText_loc7`='¡Necrófago! ¡Ven aquí un momento!', `FemaleText_loc1`='구울아! 이리로 잠시 와 보렴!', `FemaleText_loc4`='食尸鬼！过来！', `FemaleText_loc5`='食屍鬼!來這不動一陣子!', `FemaleText_loc7`='¡Necrófago! ¡Ven aquí un momento!' WHERE `ID`=29854;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이리 와, 이거 먹어. 적들이 기뻐할 테지.', `MaleText_loc4`='吃吧，我们的敌人会很高兴的。', `MaleText_loc5`='拿去，吃掉這個，我們的敵人應該會很開心。', `MaleText_loc7`='Toma, come esto, a nuestros enemigos les encantará.', `FemaleText_loc1`='이리 와, 이거 먹으렴. 적들이 기뻐할 거야.', `FemaleText_loc4`='吃吧，我们的敌人会很高兴的。', `FemaleText_loc5`='拿去，吃掉這個，我們的敵人應該會很開心。', `FemaleText_loc7`='Toma, come esto, a nuestros enemigos les encantará.' WHERE `ID`=29855;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 다이너마이트를 땅에 놓습니다.', `MaleText_loc4`='%s将一根雷管放在地上。', `MaleText_loc5`='%s將一根火藥放在地上。', `MaleText_loc7`='%s coloca una carga de dinamita en el suelo.', `FemaleText_loc1`='%s|1이;가; 다이너마이트를 땅에 놓습니다.', `FemaleText_loc4`='%s将一根雷管放在地上。', `FemaleText_loc5`='%s將一根火藥放在地上。', `FemaleText_loc7`='%s coloca una carga de dinamita en el suelo.' WHERE `ID`=29856;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 비뚤어졌군요! 우리가 당신과 뭘 해야 하겠습니까?', `MaleText_loc4`='你这个狡猾的家伙！我该怎么对付你呢？', `MaleText_loc5`='你真是個卑鄙的傢伙!我們該拿你怎麼辦?', `MaleText_loc7`='¡Eres muy $gtaimado:taimada;! ¿Qué deberíamos hacer contigo?', `FemaleText_loc1`='정말 비뚤어진 녀석이잖아! 우리가 당신과 뭘 해야 할까요?', `FemaleText_loc4`='你这个狡猾的家伙！我该怎么对付你呢？', `FemaleText_loc5`='你真是個卑鄙的傢伙!我們該拿你怎麼辦?', `FemaleText_loc7`='¡Eres muy $gtaimado:taimada;! ¿Qué deberíamos hacer contigo?' WHERE `ID`=29857;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니, 감사드립니다. 몇 시간씩 마법 연구를 하는 대신 기름 약간만으로도 같은 효과를 얻는 때를 알아낸 저 자신이 너무나 자랑스럽습니다.', `MaleText_loc4`='哎呀，谢谢你。有时候，小恩小惠远胜于数小时的巫术研究。', `MaleText_loc5`='哇，謝謝你。這真的讓我感到了不起，一塊小小的油脂就打敗了長年埋頭的巫術研究，竟有相同的效果呢。', `MaleText_loc7`='Vaya, gracias. Me enorgullezco de saber cuando un poco de grasa es mejor que pasarse horas estudiando conjuros para lograr el mismo efecto.', `FemaleText_loc1`='아니, 감사드리죠. 몇 시간씩 마법 연구를 하는 대신 기름 약간만으로도 같은 효과를 얻는 때를 알아낸 저 자신이 너무나 자랑스러워요.', `FemaleText_loc4`='哎呀，谢谢你。有时候，小恩小惠远胜于数小时的巫术研究。', `FemaleText_loc5`='哇，謝謝你。這真的讓我感到了不起，一塊小小的油脂就打敗了長年埋頭的巫術研究，竟有相同的效果呢。', `FemaleText_loc7`='Vaya, gracias. Me enorgullezco de saber cuando un poco de grasa es mejor que pasarse horas estudiando conjuros para lograr el mismo efecto.' WHERE `ID`=29858;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 허둥지둥 서두릅니다.', `MaleText_loc4`='%s连忙走过来。', `MaleText_loc5`='%s匆忙解決。', `MaleText_loc7`='%s se apresura.', `FemaleText_loc1`='%s|1이;가; 허둥지둥 서두릅니다.', `FemaleText_loc4`='%s连忙走过来。', `FemaleText_loc5`='%s匆忙解決。', `FemaleText_loc7`='%s se apresura.' WHERE `ID`=29859;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 게걸스럽게 먹습니다.', `MaleText_loc4`='%s将雷管吞了下去。', `MaleText_loc5`='%s狼吞虎嚥得吃個精光。', `MaleText_loc7`='%s mastica muerto de hambre.', `FemaleText_loc1`='%s|1이;가; 게걸스럽게 먹습니다.', `FemaleText_loc4`='%s将雷管吞了下去。', `FemaleText_loc5`='%s狼吞虎嚥得吃個精光。', `FemaleText_loc7`='%s mastica muerto de hambre.' WHERE `ID`=29860;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너의 패배다.', `MaleText_loc4`='你完了。', `MaleText_loc5`='你完了。', `MaleText_loc7`='Tu fin.' WHERE `ID`=29861;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희 창고는 바닥난 상태입니다. 물건이 더 들어오기 전까지는 팔 게 하나도 없습니다.', `MaleText_loc4`='我们的库房已经空了。在补给物资送来之前，我没东西可卖。', `MaleText_loc5`='我們的倉庫已經見底了。除非我們能弄到更多的補給品，要不然我什麼都沒得賣。', `MaleText_loc7`='Nuestros almacenes están vacíos. Hasta que no lleguen más suministros, no puedo vender nada.' WHERE `ID`=29862;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 용케 물건을 좀 구해다 놓은 덕에 다시 요리하러 갈 수 있겠군요. 자, 제가 해드릴 일이 있습니까?', `MaleText_loc4`='谢谢你送来了一些补给物资，这样我又能拿起厨具啦。我能为你做什么呢？', `MaleText_loc5`='因為你補足了我們部份的補給品，我又能回去煮東西了。那麼，我能為你做些什麼嗎?', `MaleText_loc7`='Gracias a que has logrado reponer algunos de nuestros suministros, puedo volver a cocinar. ¿Qué puedo hacer por ti?' WHERE `ID`=29863;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 기절한 것 같습니다. 어떻게 할까요, 티리온?', `MaleText_loc4`='$n好像晕过去了。我们该怎么办呢，提里奥？', `MaleText_loc5`='看來$n暈過去了。提里奧，我們該怎麼辦?', `MaleText_loc7`='Parece que $n se ha desmayado. ¿Qué deberíamos hacer, Tirion?' WHERE `ID`=29864;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 번개 회오리를 시전합니다!', `MaleText_loc4`='%s开始施放闪电新星！', `MaleText_loc5`='%s開始施展閃電新星!', `MaleText_loc7`='¡%s comienza a lanzar Nova de relámpagos!' WHERE `ID`=29865;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='눈 똑바로 뜨세요, $r.$B$B여긴 사느냐 아니면 죽느냐에요!', `FemaleText_loc4`='保持警惕，$r。$b$b生命在这里显得尤其脆弱！', `FemaleText_loc5`='保持警覺，$r。$b$b外頭生死一瞬!', `FemaleText_loc7`='Cuidado, $r.$b$b¡Ahí fuera es a vida o muerte!' WHERE `ID`=29866;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피의 사도로서, 자네들은 적의 생명력을 지배할 수 있도록 노력해야 한다.', `MaleText_loc4`='作为鲜血学徒，你们必须懂得如何掌控敌人的生命。', `MaleText_loc5`='身為血魄之徒，你要致力於掌控敵人生命能量的本質。', `MaleText_loc7`='Como discípulos de la sangre, se esfuerzan para dominar la misma fuerza vital de sus enemigos.' WHERE `ID`=29867;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼로든 마법으로든 피를 흘리면, 공격은 강해지고 적은 약해지리라.', `MaleText_loc4`='借助武器或咒术，鲜血能提高我们的攻击力，同时削弱敌人的力量。', `MaleText_loc5`='不論是靠著劍刃或魔法，鮮血滋養我們的攻擊，弱化我們的對手。', `MaleText_loc7`='Ya sea mediante la hoja o encantamientos, la sangre da fuerzas a nuestros ataques y debilita a nuestros enemigos.' WHERE `ID`=29868;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정한 대가라면 전투에서 피가 가진 원래 힘보다 더 많은 것을 끌어낼 줄 알아야 한다.', `MaleText_loc4`='真正的大师能利用鲜血在战斗中爆发出超越自身的强大力量。', `MaleText_loc5`='真正的大師不僅僅只會利用鮮血在戰鬥中的力量。', `MaleText_loc7`='Los verdaderos maestros aprenden a hacer que la sangre les sirva para algo más que fortalecerlos en la batalla.' WHERE `ID`=29869;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싸우는 놈이나 쓰러진 놈 가리지 않고, 적의 기운을 빼앗아버리면 더 작은 존재들이 나가떨어지는 곳에서도 우리가 버틸 수 있다.', `MaleText_loc4`='无论对手是一息尚存还是已然毙命，我们都能汲取他们的能量，以此获得远胜于低等生物的生存力。', `MaleText_loc5`='從我們的對手身上剝奪能量，不論是還在戰鬥的抑或是早已倒下的，讓我們能在低等生物筋疲力竭時依舊屹立不搖。', `MaleText_loc7`='Arrancarles la energía a nuestros enemigos, tanto los que han caído como los que siguen luchando, nos permite perseverar allá donde seres menores caerían agotados.' WHERE `ID`=29870;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 적은 기운이 흡수되고 빼앗긴 채 모두 쓰러져, 우리 공격에 힘을 더하리라.', `MaleText_loc4`='敌人倒下后，我们能窃取并利用他们残余的所有能量继续展开攻击。', `MaleText_loc5`='而每個倒下敵人的能量都會奪走吸收，用來強化我們的攻勢。', `MaleText_loc7`='Con cada enemigo que cae, la energía que le robamos alimenta nuestro asalto.' WHERE `ID`=29871;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피의 대가가 된 우리는, 영원히 싸우리라...', `MaleText_loc4`='对鲜血大师来说，战斗是永无止境的……', `MaleText_loc5`='身為血魄大師，我們知曉永無止境的戰鬥...', `MaleText_loc7`='Como señores de la sangre, conocemos la batalla sin fin...' WHERE `ID`=29872;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='굶주림이 영원히 가시지 않으리라는 것을 안다...', `MaleText_loc4`='我们渴望着鲜血的洗礼……', `MaleText_loc5`='我們熟知永不靨足的飢渴...', `MaleText_loc7`='Conocemos un hambre que jamás será saciada...' WHERE `ID`=29873;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘을 영원히 정복하지 못하리라는 것을 안다...', `MaleText_loc4`='我们拥有敌人永远无法战胜的力量……', `MaleText_loc5`='我們通曉無法抵擋的力量...', `MaleText_loc7`='Conocemos un poder que jamás será vencido...' WHERE `ID`=29874;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피의 대가로서, 우리는 모두 삶과 죽음 그 자체를 다스리는 대가이다. 우리에게 대항하는 자는, 희망조차 말라버리고 사라질 것이다.', `MaleText_loc4`='鲜血大师掌控着生命与死亡。胆敢与我们为敌的家伙，会被抽干所有的能量，沦为毫无生气的死尸。', `MaleText_loc5`='身為血魄大師，我們是生與死的主宰。在我們面前，希望也會枯竭，了無生氣。', `MaleText_loc7`='Al ser amos de la sangre dominamos la vida y la muerte. Contra nosotros, hasta la esperanza cae vacía y sin vida.' WHERE `ID`=29875;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전장으로 돌아오지 않으면 네 녀석은 탈락이다!', `MaleText_loc4`='返回战场，否则我就将你摔下去！', `MaleText_loc5`='回去戰場，否則就丟下你!', `MaleText_loc7`='¡Vuelve al campo de batalla o serás arrojado!' WHERE `ID`=29876;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아니 왜 다들 제가 배를 조난이라도 시켰다는 듯이 쳐다보는 거죠?', `FemaleText_loc4`='飞船又不是因为我才坠毁的，为什么大家都朝我瞪眼？', `FemaleText_loc5`='為什麼大家一副就是我把船弄沉的一樣?', `FemaleText_loc7`='¿Por qué me miran todos como si hubiera estrellado la nave?' WHERE `ID`=29877;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어, 놈리건의 정신호를 수리할 부품이 우리 손에 들어왔어요.', `MaleText_loc4`='我们总算找到零件，可以修理诺莫瑞根之魂了。', `MaleText_loc5`='總算，我們有零件可以修理諾姆瑞根之靈了。', `MaleText_loc7`='Al fin tenemos las piezas para reparar el Espíritu de Gnomeregan.' WHERE `ID`=29878;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디 볼까요. 여기를 조정하고, 저기를 조절하면...', `MaleText_loc4`='让我瞧瞧，拧一拧，再调整一下……', `MaleText_loc5`='讓我看看，只要這裡扭一下，那裡調整一下...', `MaleText_loc7`='Veamos, solo un ajuste aquí y afinar eso...' WHERE `ID`=29879;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자 다 됐어요. 이게 바로 놈리건의 정신호예요!', `MaleText_loc4`='你看，诺莫瑞根之魂！修好啦！', `MaleText_loc5`='瞧瞧，諾姆瑞根之靈!', `MaleText_loc7`='¡Ahí está, el Espíritu de Gnomeregan!' WHERE `ID`=29880;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 비행기를 타도 좋지만, 좌석에 톱날이 있다고 투덜거리지는 마세요. 구할 수 있는 부품이 그게 다였으니까요.', `MaleText_loc4`='你可以开着她去兜风，不过万一你在座椅上发现了刀片，可别来跟我抱怨。你要知道，我好不容易才凑齐了零件修理她，就别那么讲究啦。', `MaleText_loc5`='你可以使用她，但是我可不想聽到有人抱怨看見刀子插在你的座位上。我只能用我們找得到的東西來修好她。', `MaleText_loc7`='Puedes utilizarla, pero no quiero escuchar quejas sobre cuchillas en tu asiento. He tenido que arreglarla con lo que he podido encontrar.' WHERE `ID`=29881;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕, 친구! 내가 여기 공장 안에 가게를 차렸다고. 번쩍거리는 새 탈것을 타고 싶지 않나? 비용은 공격이 끝나고 나면 당신네 대장이 알아서 치를 거라고. 이런 좋은 거래는 드물지!', `MaleText_loc4`='你好，朋友！我在车间里设立了店面。我很乐意为你组装一辆亮闪闪的载具啊——我甚至可以在攻击结束后再将帐单寄给你的头儿。这可是相当划算的买卖呀！', `MaleText_loc5`='嗨，朋友!我在工廠中開了一間店舖，我很樂意送你進一台全新交通工具裡頭 - 我甚至會在襲擊之後把帳單送給你老闆。哪能找到這麼好的買賣!', `MaleText_loc7`='¡Hola, amig$go:a;! He puesto una tienda en esta fábrica. Estaré encantado de proporcionarte un nuevo vehículo último modelo, hasta le mandaré la factura a tus líderes tras el asalto. ¡El mejor trato que hay!', `FemaleText_loc1`='안녕, 친구! 내가 여기 공장 안에 가게를 차렸다고. 번쩍거리는 새 탈것을 타고 싶지 않나? 비용은 공격이 끝나고 나면 당신네 대장이 알아서 치를 거라고. 이런 좋은 거래는 드물지!', `FemaleText_loc4`='你好，朋友！我在车间里设立了店面。我很乐意为你组装一辆亮闪闪的载具啊——我甚至可以在攻击结束后再将帐单寄给你的头儿。这可是相当划算的买卖呀！', `FemaleText_loc5`='嗨，朋友!我在工廠中開了一間店舖，我很樂意送你進一台全新交通工具裡頭 - 我甚至會在襲擊之後把帳單送給你老闆。哪能找到這麼好的買賣!', `FemaleText_loc7`='¡Hola, amig$go:a;! He puesto una tienda en esta fábrica. Estaré encantado de proporcionarte un nuevo vehículo último modelo, hasta le mandaré la factura a tus líderes tras el asalto. ¡El mejor trato que hay!' WHERE `ID`=29882;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파괴전차를 몰고 싶습니다.', `MaleText_loc4`='我要一辆攻城车。', `MaleText_loc5`='我想要駕駛石毀車。', `MaleText_loc7`='Me gustaría conducir un demoledor.', `FemaleText_loc1`='파괴전차를 몰고 싶어요.', `FemaleText_loc4`='我要一辆攻城车。', `FemaleText_loc5`='我想要駕駛石毀車。', `FemaleText_loc7`='Me gustaría conducir un demoledor.' WHERE `ID`=29883;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕, 친구! 파괴전차를 내주고 싶지만, 안타깝게도 지금은 부품이 하나 모자란다고.', `MaleText_loc4`='你好，朋友！我倒是很乐意为你组装一辆攻城车，但是我手头的零件用光啦。', `MaleText_loc5`='嗨，朋友!我很樂意給你一台石毀車，但是目前我沒有零件了。', `MaleText_loc7`='¡Hola, $gamigo:amiga;! Me encantaría darte un demoledor, pero ahora no me quedan piezas.', `FemaleText_loc1`='안녕, 친구! 파괴전차를 내주고 싶지만, 안타깝게도 지금은 부품이 하나 모자란다고.', `FemaleText_loc4`='你好，朋友！我倒是很乐意为你组装一辆攻城车，但是我手头的零件用光啦。', `FemaleText_loc5`='嗨，朋友!我很樂意給你一台石毀車，但是目前我沒有零件了。', `FemaleText_loc7`='¡Hola, $gamigo:amiga;! Me encantaría darte un demoledor, pero ahora no me quedan piezas.' WHERE `ID`=29884;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 식으로 날 배신하다니! 이 죄는 네 목숨으로 갚아야 될 게다!', `MaleText_loc4`='这是背叛！你将为这场骗局付出生命的代价！', `MaleText_loc5`='這是什麼詭計!你會因為你欺騙我而賠上性命的，老兄!', `MaleText_loc7`='¡¿Qué traición ser ésta?! ¡Estar pagando este engaño con tu vida!' WHERE `ID`=29885;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지배의 홀이 밝게 빛납니다! 지금 사용하십시오!', `MaleText_loc4`='支配节杖散发着明亮的光芒！快使用它！', `MaleText_loc5`='支配權杖發出耀眼的光芒!現在使用它!', `MaleText_loc7`='¡El Cetro de Dominación brilla con fuerza! ¡Úsalo ahora!' WHERE `ID`=29886;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지하마귀 수호병도 싸움에 뛰어들었습니다!', `MaleText_loc4`='一名地穴卫士加入了战斗！', `MaleText_loc5`='一名墓穴守衛加入戰鬥!', `MaleText_loc7`='¡Un guardia de la cripta se une al combate!' WHERE `ID`=29887;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='붉은십자군 사선에서 벗어나 날아드는 화살과 창을 피하라!', `MaleText_loc4`='避开与血色十字军的正面火力冲突，不要被他们的箭和标枪伤到！', `MaleText_loc5`='撤出血色十字軍的火線，避開接連發射的箭雨和投槍!', `MaleText_loc7`='¡Evita las flechas y jabalinas de la Cruzada Escarlata apartándote de su línea de tiro!' WHERE `ID`=29888;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='붉은십자군 놈들을 삼켜 기운을 회복하라!', `MaleText_loc4`='吞噬血色十字军，补充你的能量！', `MaleText_loc5`='消滅血色十字軍以補充你的能量!', `MaleText_loc7`='¡Devora a los Cruzados Escarlata para recuperar tu energía!' WHERE `ID`=29889;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='존스가 별 탈 없었으면 해요.', `MaleText_loc4`='但愿琼斯没事。', `MaleText_loc5`='我希望瓊斯沒事。', `MaleText_loc7`='Espero que Jones esté bien.' WHERE `ID`=29890;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='존스가 제 말을 들었다면, 목숨을 부지할 수 있었겠지요.', `MaleText_loc4`='如果琼斯肯听我的，他或许会活得久一点。', `MaleText_loc5`='如果瓊斯聽我的話，他可以再活久一點。', `MaleText_loc7`='Si Jones me hubiera escuchado, habría vivido más.' WHERE `ID`=29891;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 존스 말이에요...', `MaleText_loc4`='这个琼斯……', `MaleText_loc5`='那個瓊斯啊...', `MaleText_loc7`='Ese Jones...' WHERE `ID`=29892;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='존스는 그냥 별난 정도가 아니에요. 미쳤어요! 항상 일확천금을 찾아 헤매고 다녔어요!', `MaleText_loc4`='他不是蠢蛋，是疯子！整天就想着追求财富与荣耀……', `MaleText_loc5`='他不是白痴，他是瘋子!總是為了財寶與榮耀橫衝直撞...', `MaleText_loc7`='¡No está loco, está chalado! Siempre buscando la fama y la gloria...' WHERE `ID`=29893;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세상에나 존스와 같이 모험한 적도 있는데...', `MaleText_loc4`='以前，我和琼斯总是一起外出探险……', `MaleText_loc5`='噢老天，瓊斯和我的冒險可精采了...', `MaleText_loc7`='Chico, Jones y yo hemos vivido algunas aventuras...' WHERE `ID`=29894;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='존스가 가면 저도 갔죠. 존스가 나서면, 저도 나서고요. 하지만, 이번엔 저보고 물러나 있으랬어요.', `MaleText_loc4`='他上哪儿，我就上哪儿。我一直跟着他，可这次他却叫我留下来。', `MaleText_loc5`='瓊斯走到哪，我就跟到哪。他爬到哪，我跟到哪。但是這一回，他要我待著別跟上去。', `MaleText_loc7`='Allá donde vaya Jones, voy yo. Allá donde él pise, yo piso. Pero esta vez me dijo que me quedase atrás.' WHERE `ID`=29895;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='존스가 무사히 돌아오기를 바라요.', `MaleText_loc4`='但愿琼斯能平安回来。', `MaleText_loc5`='我希望瓊斯能平安回來。', `MaleText_loc7`='Espero que Jones vuelva sano y salvo.' WHERE `ID`=29896;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마지막으로 했던 카드 게임에서 존스가 저한테 빚을 진 게 있거든요. 저한테 속임수를 쓰려 했다니 믿어지세요? 저도 뭐 약간 속임수를 썼을지도 모르지만, 그에 비하면 존스는 엄청난 속임수를 썼다고요.', `MaleText_loc4`='上次玩牌，琼斯还欠我一笔赌债呢。这家伙居然想抽我老千！他这骗子，胃口比我个子还大！', `MaleText_loc5`='瓊斯在我們最後一次打牌的時候還欠我錢，你能相信他竟然會出老千嗎!我也許個子很小，但是他作弊作很大。', `MaleText_loc7`='Jones todavía me debe dinero de nuestra última partida de cartas. ¡Te puedes creer que intentó hacerme trampas! Puede que yo sea pequeño, pero él hace trampas enormes.' WHERE `ID`=29897;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이고... 그 생각이 이제야 났다니 믿기지가 않네...', `MaleText_loc4`='天哪……我居然还记得这些往事，真不敢相信……', `MaleText_loc5`='噢，老天...我不敢相信我還記得...', `MaleText_loc7`='Jo tío, no puedo creer que haya acabado de recordar eso...' WHERE `ID`=29898;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='...그래서 존스가 감자를 떨어뜨리더라고요. 제가 잘 들고 있으라고까지 했는데도 말이에요.', `MaleText_loc4`='……于是他将土豆都扔掉了，我分明让他留下来的。', `MaleText_loc5`='...儘管我叫他抓緊一點，他還是把馬鈴薯掉了一地。', `MaleText_loc7`='... y él tiró las patatas, a pesar de que le dije que las sostuviera.' WHERE `ID`=29899;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 불안한 듯 주위를 둘러봅니다.', `MaleText_loc4`='%s紧张地朝四周张望着。', `MaleText_loc5`='%s緊張的四處張望。', `MaleText_loc7`='%s mira a su alrededor nerviosamente.' WHERE `ID`=29900;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 한숨을 쉽니다.', `MaleText_loc4`='%s叹了口气。', `MaleText_loc5`='%s嘆了一口氣。', `MaleText_loc7`='%s suspira.' WHERE `ID`=29901;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 심호흡을 하고 가슴을 폅니다.', `MaleText_loc4`='%s深深地吸了一口气，挺起胸膛。', `MaleText_loc5`='%s深呼吸，然後用力吐了一口氣。', `MaleText_loc7`='%s coge aire y saca pecho.' WHERE `ID`=29902;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 불쾌하다는 듯이 먼 곳을 바라봅니다.', `MaleText_loc4`='%s朝远处眺望，显得十分烦躁。', `MaleText_loc5`='%s望向遠方，看起來很煩惱。', `MaleText_loc7`='%s mira a la distancia, molesto.' WHERE `ID`=29903;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 웃음을 참지 못합니다. 웃음 때문에 이야기가 계속 이어지지 않습니다.', `MaleText_loc4`='%s忍不住笑了起来。他的笑声一次次地打断了自己的话语。', `MaleText_loc5`='%s幾乎控制不住他的笑聲。他的故事常常被他自己的笑聲打斷。', `MaleText_loc7`='%s apenas puede controlar la risa. Sus carcajadas interrumpen constantemente su propia historia.' WHERE `ID`=29904;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 한숨을 쉽니다.', `MaleText_loc4`='%s叹了口气。', `MaleText_loc5`='%s嘆了一口氣。', `MaleText_loc7`='%s suspira.' WHERE `ID`=29905;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음.. 귀관은 어딘가 낯이 익네... 잠시만...$B$B그렇지! 서부 몰락지대. 거기서 왔다는 걸 알아보겠네. 귀관은 $n|1이로군;로군;! 다시 만나서 정말 반갑네. 이번에는 자네가 우리를 도와 그 일을 끝내주길 바라네.$B$B저기 서부 몰락지대에서부터 멀리 떨어진 이곳까지 왔으나, 이 싸움에서 이기지 못한다면 돌아갈 곳은 없을 걸세.', `MaleText_loc4`='嗯……你有点面熟……让我想想……$B$B哈哈！西部荒野！我在西部荒野见过你。你是$n！咱们又见面啦，希望你能再次伸出援手。$B$B这里离西部荒野非常遥远，但是如果我们打不赢这一战，恐怕就要无家可归了。', `MaleText_loc5`='嗯...你的臉怎麼看怎麼眼熟，$r...給我幾秒鐘...$b$b啊哈!西部荒野，我就是在那兒見過你的。你是$n!很高興再次見到你。不過，這回希望你能幫助我們完成這工作才行。$B$B既然我們離開西部荒野來到這麼遠的地方，如果打不了勝仗，我們可就無家可歸了。', `MaleText_loc7`='Mmm... tu cara me resulta familiar, $r. Dame un momento...$B$B¡Ajá! Te recuerdo de los Páramos de Poniente. ¡Eres $n! Me alegro de volver a verte. Pero esperemos que esta vez nos ayudes a terminar el trabajo.$B$BAhora estamos muy lejos de los Páramos de Poniente, pero si no ganamos esta batalla, puede que no haya un hogar al que volver.' WHERE `ID`=29906;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n! 모습이 달라져서 못 알아봤네. 아직 그 튜닉을 입고 있군... 아니 그 다리보호구를 입었었던가... 예전에도 그 지팡이를 들었었나? 기억이 안 나는군. 너무 오래전이니 말이야..$B$B어쨌든 우리를 도와주러 여기까지 오다니 기쁘네. 어떤 도움이라도 가리지 않고 환영일세. $n, 귀관이 백성의 민병대와 함께 서부 몰락지대에서처럼만 해준다면 우리에게도 기회가 있네.$B$B상황이 그리 좋지 않네. 이 싸움에서 이기지 못한다면, 돌아갈 서부 몰락지대는 없을 걸세.', `MaleText_loc4`='$n！你换了新衣服，差点认不出你啦。你还留着那件外套吗……或者你选了马裤……还是法杖？我不记得了，那已经是很久之前的事情了吧……$B$B嗯，很高兴你能来这里帮忙。我们需要一切可以动用的力量。$n，如果你的表现能像在西部荒野帮助人民军时一样好，那我们就有希望了。$B$B眼前的局势非常严峻，赢不了这一战，我们就休想回到西部荒野了。', `MaleText_loc5`='$n!穿了新衣服以後差點認不出你來了。還是穿著那件外套...或者你穿的重腿甲...也許是那根手杖呢?我記不得啦，年代太久遠了...$b$b嗯，我很高興你又能在這兒幫忙了，只要願意，誰都可以來幫忙。$n，如果你還是能像當初幫忙西部荒野人民軍的時候一樣的身手，我們就有機會了。$B$B這是個艱困的時刻，如果我們打不贏勝仗，我們就回不去西部荒野了。', `MaleText_loc7`='¡$n! Apenas te reconozco con esas ropas nuevas. ¿Todavía tienes esa túnica... o escogiste las albarcas... o fue el bastón? No lo recuerdo, fue hace tanto tiempo...$B$BBueno, me alegro de que estés aquí para ayudar de nuevo. Necesitamos toda la ayuda posible. $n, si actúas tal y como lo hiciste allá en los Páramos de Poniente con La Milicia Popular, tendremos una oportunidad.$B$BEstos son tiempos duros y si no ganamos esta batalla, puede que no haya unos Páramos de Poniente a los que volver.' WHERE `ID`=29908;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛의 가호와 귀관의 도움으로, 데피아즈단은 이제 별 위협이 되지 않네.$B$B저기 서부 몰락지대에서부터 멀리 떨어진 이곳까지 왔으나, 이 싸움에서 이기지 못한다면 돌아갈 곳조차 남지 않을 걸세.', `MaleText_loc4`='$n，有了圣光的祝福和你的帮助，迪菲亚已经不再构成威胁。$B$B但是我们距离西部荒野非常遥远，而且如果我们打不赢这一战，恐怕就要无家可归了。', `MaleText_loc5`='有著聖光的祝福和你的協助，$n，迪菲亞不再造成威脅。$B$B但是我們離開西部荒野來到這麼遠的地方，如果打不了勝仗，我們可就無家可歸了。', `MaleText_loc7`='Con la bendición de la Luz y tu ayuda, $n, los Defias dejaron de ser una amenaza.$B$BPero ahora estamos muy lejos de los Páramos de Poniente y si no ganamos esta batalla, puede que no tengamos un hogar al que volver.' WHERE `ID`=29909;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c님, 큰 놈으로 잡아오십시오!', `MaleText_loc4`='祝你狩猎愉快，$c！', `MaleText_loc5`='$c，祝你狩獵順利!', `MaleText_loc7`='¡Buena caza ahí fuera, $c!' WHERE `ID`=29910;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='행운을 빕니다. $r!', `MaleText_loc4`='祝你好运，$r！', `MaleText_loc5`='祝你好運，$r!', `MaleText_loc7`='¡Buena suerte, $r!' WHERE `ID`=29911;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뒤를 조심하십시오, $r님!', `MaleText_loc4`='保持警惕，$r！', `MaleText_loc5`='小心身後，$r!', `MaleText_loc7`='¡Vigila tu espalda, $r!' WHERE `ID`=29912;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c님께서 도착하십니다!', `MaleText_loc4`='$c顺利抵达啦！', `MaleText_loc5`='回來的$c!', `MaleText_loc7`='¡Llega $gun:una; $c!' WHERE `ID`=29913;
