UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 $c님께서 돌아오십니다!', `MaleText_loc4`='$c已经安然着陆！', `MaleText_loc5`='我們有個$c回歸了!', `MaleText_loc7`='¡Se aproxima $gun:una; $c!' WHERE `ID`=29915;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바보야! 넌 엄청난 힘을 가질 수도 있었는데!', `MaleText_loc4`='蠢货！你本来可以获得强大的力量！', `MaleText_loc5`='笨蛋!你本來能擁有無比力量的，老兄!', `MaleText_loc7`='¡Tonto! ¡Podrías tener gran poder!' WHERE `ID`=29916;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 이럴 수가! 리치 왕께서 널 위한 멋진 계획이 있다고 하셨는데...', `MaleText_loc4`='怎么可能？巫妖王陛下说过，他已经为你规划好了未来……', `MaleText_loc5`='這怎麼可能呢?巫妖王說過他對你有著更遠大的計畫，老兄...', `MaleText_loc7`='¿Cómo es posible? El Rey Exánime decir que tener grandes planes para ti…' WHERE `ID`=29917;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세상에 정말 믿을 놈이 하나도 없군!', `MaleText_loc4`='我就知道任何人都不能相信！', `MaleText_loc5`='我就知道任何人都不能相信!', `MaleText_loc7`='¡Mi debí saber de no confiar en nadie!' WHERE `ID`=29918;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='숙명을 거부하다니, 바보 같은 녀석... 넌 이제 끝이다!', `MaleText_loc4`='你拒绝了远大的前程。现在，去死吧！', `MaleText_loc5`='你拒絕了遠大的前途啊，老兄，你準備受死吧!', `MaleText_loc7`='Haber dado tu espalda al destino. ¡Ahora tú morir!' WHERE `ID`=29919;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈이 배신했다고 내가 눈 하나 깜짝할 것 같으냐!', `MaleText_loc4`='而且，即使是你的背叛，也已经阻止不了我了。', `MaleText_loc5`='你的背叛不會減緩我的腳步的，老兄。', `MaleText_loc7`='Tu traición no frenarme en absoluto.' WHERE `ID`=29920;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈 따윈 필요하지도 않았다. 너 없이도 줄드락쯤은 뭉개버릴 수 있어!', `MaleText_loc4`='我用不着再依靠你了。没有你，我一样可以毁灭祖达克！', `MaleText_loc5`='我一點也不需要你，老兄。沒有你我也能毀滅祖爾德拉克!', `MaleText_loc7`='Nunca te necesité. ¡Mi puedo aplastar Zul''Drak sin ti!' WHERE `ID`=29921;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만!', `MaleText_loc4`='够了！', `MaleText_loc5`='夠了!', `MaleText_loc7`='¡BAH''TA!' WHERE `ID`=29922;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 배신이 네 운명을 결정했다...', `MaleText_loc4`='你会为这场愚蠢的背叛而丢掉性命的！', `MaleText_loc5`='你會為這場愚蠢的背叛而丟掉性命的!', `MaleText_loc7`='¡Esta absurda traición haber costado tu vida! ' WHERE `ID`=29923;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기억하시오, $n. 이건 단거리 경주가 아니오. 사냥꾼 하나를 제대로 확인하려면 오랜 기간 탐험하는 동안 인내심을 시험해봐야 하오.', `MaleText_loc4`='记住，$n，这不是短期的考验。对猎人而言，真正的考验是在长途跋涉中锻炼自己的耐性。', `MaleText_loc5`='記得，$n，這可不是短跑，獵人試煉的真正考驗，是度過長途遠征的過程。', `MaleText_loc7`='Recuerda, $n, esto no es un sprint. La verdadera prueba del cazador pone a prueba su resistencia a lo largo de una gran expedición.' WHERE `ID`=29924;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스가 동부 무덤을 차지했습니다!', `MaleText_loc4`='联盟夺取了东部墓地！', `MaleText_loc5`='東部墓地已經被聯盟給佔據了!', `MaleText_loc7`='¡La Alianza ha tomado el Cementerio del Este!' WHERE `ID`=29925;
