UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공기 중에 숨은 에너지가 상당한데? 훌륭한 수확이야.', `MaleText_loc4`='空气中有潜藏着的能量在涌动……丰收的时候到啦！', `MaleText_loc5`='空氣中充滿著潛伏的能量...大收穫!', `MaleText_loc7`='El aire está cargado de energía latente... ¡qué cosecha!' WHERE `ID`=29931;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우르그레스가 강력한 어둠의 기운을 내뿜기 시작합니다!', `MaleText_loc4`='乌格雷斯开始施放强大的黑暗力量！', `MaleText_loc5`='烏格雷希開始散發出一股強大的黑暗能量!', `MaleText_loc7`='¡Urgreth empieza a emitir una poderosa energía oscura!' WHERE `ID`=29932;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='온 가족이 총출동한 모양이로구나! 여기 무슨 일로 왔나?', `MaleText_loc4`='你把全家人都带来了吗！那么，你来这里做什么？', `MaleText_loc5`='看來你把整個家族都帶過來了!那麼，有何貴幹啊?', `MaleText_loc7`='¡Parece que te has traído a toda la familia! ¿Qué asuntos tienes aquí?' WHERE `ID`=29933;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공사라고? 여기가 전쟁 지역이라는 건 알고나 있나, 민간인? 하는 일이 뭔가?', `MaleText_loc4`='找事儿做？这里是战场，你明白吗？你是干什么的？', `MaleText_loc5`='找工作?你知道這裡是戰區吧，死老百姓?你的專業是什麼?', `MaleText_loc7`='¿Trabajar? ¿Eres consciente de que esto es una zona de guerra, civil? ¿A qué te dedicas?' WHERE `ID`=29934;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇군. 그럼 가보게.', `MaleText_loc4`='好吧。继续。', `MaleText_loc5`='是的，往前走。', `MaleText_loc7`='Vale. Adelante.' WHERE `ID`=29935;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여왕님께서 어둠 순찰자를 보내셨다! 물러나라, 제군들!', `MaleText_loc4`='女王陛下派来了黑暗游侠！退后！', `MaleText_loc5`='女王陛下派出了黑暗遊俠!閃開，小鬼!', `MaleText_loc7`='¡Su majestad envía a las Forestales Oscuras! ¡A un lado, muchachos!' WHERE `ID`=29936;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 내가 받아들인 놈 중에 제일 한심한 떨거지로군! 대열로 물러나서 고위집행관 안셀름 님께 보고하게!', `MaleText_loc4`='你们是我今天见到的最差劲的一批新兵！列队，向高级执行官安希尔姆报到！', `MaleText_loc5`='你一定是今天的菜鳥中最爛的一個!滾回隊伍裡面，向高階執行官安賽姆報到!', `MaleText_loc7`='¡Debéis ser la panda más patética de reclutas que he visto en todo el día! ¡Poneos en formación y presentaos ante el sumo ejecutor Anselm!' WHERE `ID`=29938;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 제일 한심한 떨거지 아닌가! 어제 왔던 녀석들보다는 조금 나은 듯하군. 바로 대열을 갖춰라! 지금 시작하도록!', `MaleText_loc4`='瞧瞧你们这蓬头垢面的模样！我还以为你们会比昨天那批新兵好一点呢。列队！去报到！', `MaleText_loc5`='少臭著一張臉!我猜你應該比昨天那堆垃圾好一些。立刻集合!回報任務!', `MaleText_loc7`='¡Da pena veros! Al menos creo que sois algo mejores que la chusma de ayer. ¡En formación, ya! ¡Presentaos para el servicio!' WHERE `ID`=29939;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 실없이 흘리는 웃음은 당장 거두도록! 고위집행관님께서 보셨다면 친히 네놈들을 끝장내셨을 것이다!', `MaleText_loc4`='把你们脸上的谷粒抹掉！要是让高级执行官看见你们这副模样，他会亲手宰了你们！', `MaleText_loc5`='菜鳥，你們最好不要被我發現在偷笑!要是給高階執行官發現，他會親手把你們全都宰了!', `MaleText_loc7`='¡Reclutas, borren esa estúpida sonrisa de su cara! ¡Si el Sumo Ejecutor los ve así, los matará él mismo!' WHERE `ID`=29940;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건... 재미 없다...', `MaleText_loc4`='一点都不好玩……', `MaleText_loc5`='不好玩...', `MaleText_loc7`='No es divertido…' WHERE `ID`=29941;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새 장난감이다!', `MaleText_loc4`='新的玩具！', `MaleText_loc5`='新玩具!', `MaleText_loc7`='¡Juguetes!' WHERE `ID`=29942;
