UPDATE `locales_broadcast_text` SET `MaleText_loc1`='푸른용군단이 우리를 공격하다니, 믿을 수가 없습니다. 놈들에게 받은 대로 돌려주겠습니다!', `MaleText_loc4`='真不敢相信，蓝龙军团居然会攻击我们。我们要发动反击！', `MaleText_loc5`='我不敢相信藍龍會來攻擊我們。讓我們還以顏色!', `MaleText_loc7`='No puedo creerme que nos ataquen los azules. ¡Vamos a darles para el pelo!' WHERE `ID`=29961;
