UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명성이 아주 자자하더군요, $n. 오늘이 기대됩니다.', `MaleText_loc4`='$n，久仰大名啊。这场战斗一定会非常有趣。', `MaleText_loc5`='久仰大名，$n。事情會變得很有趣。', `MaleText_loc7`='$n, tu reputación te precede. Esto se pone interesante.' WHERE `ID`=29963;
