UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청한 녀석! 넌 우리에게 위협이 되는 유일한 존재에게 우릴 안내해 줬을 뿐이다! 에티미디안을 노스렌드에 데려갈 수는 없어!', `MaleText_loc4`='蠢货！你想唤醒那个可怕的造物，让它与我们的军队为敌吗？别想把源生石像带回诺森德！', `MaleText_loc5`='蠢貨!你把我們帶到那唯一能對抗我們大軍的事物面前!你休想把伊提米迪安帶回北裂境!', `MaleText_loc7`='¡$gNecio:Necia;! ¡Nos has traído ante el único ser que puede enfrentarse a nuestros ejércitos! ¡Jamás llevarás a El Etimidiano de vuelta a Rasganorte!' WHERE `ID`=29968;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님, 비열한 필멸의 존재가 우리를 속였습니다. 녀석은 고통받아 마땅합니다!', `MaleText_loc4`='主人，就是这个无耻的凡人出卖了我们。我们一定要好好教训他！', `MaleText_loc5`='主人，這個平凡人混帳竟然欺騙我們。他們必須受盡折磨!', `MaleText_loc7`='Amo, esta escoria perecedera estar engañándonos. ¡Deben sufrir! ' WHERE `ID`=29969;
