UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잉그바르! 한심한 놈 같으니, 다른 녀석들에게 본보기로 삼아야겠군! 네놈에게 벌을 주겠다... 일어나라! 주인님의 뜻에 따라 저들을 처단하라!', `FemaleText_loc4`='因格瓦尔！你这可耻的失败将警示所有巫妖王的仆从！你被诅咒了！站起来，重新执行主人的意志！', `FemaleText_loc5`='因格瓦!你可恥的失敗成為所有人的警告!你被詛咒了!站起來，重新執行主人的意志!', `FemaleText_loc7`='¡Ingvar! ¡Tu lamentable fracaso servirá de advertencia a todos! ¡Estás condenado! ¡Levantate y cumple la voluntad del amo!' WHERE `ID`=29980;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흥미롭군... 근처에 비전 에너지가 꽤 많은데? 작업을 시작해 볼까...', `MaleText_loc4`='真有意思……这附近储存着高纯度的奥术能量。我要去探察一番……', `MaleText_loc5`='真有趣...附近充斥著一股高純度的秘法能量。該是進行勘探的時候了...', `MaleText_loc7`='Intrigante... hay una gran cantidad de energía arcana cerca. Vamos a explorar…' WHERE `ID`=29981;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고통받을 자는 바로 너다. 순식간에 죽여 주는 걸 감사해라...', `MaleText_loc4`='这是你应受的惩罚。值得庆幸的是，你会死得很痛快。', `MaleText_loc5`='你才是該受折磨的人。能痛快一死應該要感到滿足...', `MaleText_loc7`='Tú eres quien debe sufrir. Confórmate con que tu muerte sea rápida. ' WHERE `ID`=29982;
