UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 깜찍한 배신을 칭찬하는 의미로 이번엔 네 하찮은 목숨을 보전해 주마. 어쩌면 너에겐 가능성이 조금 있을지도 모르니.', `MaleText_loc4`='出演了一次如此令人愉悦的背叛，你那卑微的生命，我就留给你作为奖赏吧。或许你身上还大有潜力呢。', `MaleText_loc5`='我饒了你那卑微的小命，當作是這有趣背叛行為的獎賞吧。你或許還有一絲絲的價值。', `MaleText_loc7`='Te perdono tu insignificante vida en recompensa de esta divertida traición. Quizás aún contengas algo de potencial. ' WHERE `ID`=29984;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음에 만날 때도 살고 싶다면, 더 그럴듯한 이유를 준비해야 할 게다.', `MaleText_loc4`='下次见面时，你的性命可就没法如此轻易地保住了！', `MaleText_loc5`='等我們再見面時，你得要證明自己有活下來的價值!', `MaleText_loc7`='¡Al reencontrarnos exigiré mucho más para que justifiques tu vida!' WHERE `ID`=29985;
