UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발견! $n|1이;가; 영원의 물을 영원의 불로 변환하는 방법을 발견했습니다.', `MaleText_loc4`='太棒了！$n领悟了将永恒之水转化为永恒火焰的配方。', `MaleText_loc5`='大發現!$n發現了如何將永恆之水轉化為火。', `MaleText_loc7`='¡DESCUBRIMIENTO! $n ha aprendido cómo transmutar agua eterna en fuego.', `FemaleText_loc1`='발견! $n|1이;가; 영원의 물을 영원의 불로 변환하는 방법을 발견했습니다.', `FemaleText_loc4`='太棒了！$n领悟了将永恒之水转化为永恒火焰的配方。', `FemaleText_loc5`='大發現!$n發現了如何將永恆之水轉化為火。', `FemaleText_loc7`='¡DESCUBRIMIENTO! $n ha aprendido cómo transmutar agua eterna en fuego.' WHERE `ID`=29999;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발견! $n|1이;가; 새로운 변환식을 발견했습니다!', `MaleText_loc4`='太棒了！$n领悟了新的转化配方！', `MaleText_loc5`='大發現!$n發現了新的轉化!', `MaleText_loc7`='¡DESCUBRIMIENTO! $n ha descubierto una nueva trasmutación!', `FemaleText_loc1`='발견! $n|1이;가; 새로운 변환식을 발견했습니다!', `FemaleText_loc4`='太棒了！$n领悟了新的转换配方！', `FemaleText_loc5`='大發現!$n發現了新的轉化配方!', `FemaleText_loc7`='¡DESCUBRIMIENTO! $n ha descubierto una nueva trasmutación!' WHERE `ID`=30000;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 가지고 다니는 그 물건은 뭐지?', `MaleText_loc4`='你拿的是什么玩意儿？', `MaleText_loc5`='你拿的那顆小珠是什麼?', `MaleText_loc7`='¿Qué es ese adorno que llevas?' WHERE `ID`=30001;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그까짓 장난감으로 목숨을 부지할 것 같으냐?', `MaleText_loc4`='这样的小玩具是救不了你的！', `MaleText_loc5`='你的小玩具救不了你的!', `MaleText_loc7`='¡Tu juguetito no te salvará!' WHERE `ID`=30002;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕의 권능 앞에 빛은 상대도 되지 않는다!', `MaleText_loc4`='圣光的力量也难以战胜巫妖王的强大！', `MaleText_loc5`='聖光根本不是巫妖王力量的對手!', `MaleText_loc7`='¡La Luz no es rival para el poder del Rey Exánime!' WHERE `ID`=30003;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사랑하던 사람들에게 작별 인사나 해라, $c...', `MaleText_loc4`='和你心爱的人说再见吧，$c……', `MaleText_loc5`='和你所愛的人道別吧，$c...', `MaleText_loc7`='Despídete de aquellos que amas, $c...' WHERE `ID`=30004;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$r, 너희의 왕국은 무너지고 말리라!', `MaleText_loc4`='你的王国终将沦陷，$r！', `MaleText_loc5`='你的王國即將陷落，$r!', `MaleText_loc7`='¡Tus reinos caerán, $r!' WHERE `ID`=30005;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강대한 성채들은 산산이 부서지고 네가 사랑하는 사람들은 리치 왕의 수하에 들리라!', `MaleText_loc4`='你们的城堡必将倒塌，而你挚爱的人也会沦为巫妖王的奴仆！', `MaleText_loc5`='你固若金湯的城堡即將粉碎，你摯愛的人也將加入巫妖王的一方!', `MaleText_loc7`='¡Tus poderosos castillos se derrumbarán y tus seres queridos se unirán a las filas del Rey Exánime!' WHERE `ID`=30006;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 지닌 그 신성하다는 물건에서 나는 악취가 역겹기 짝이 없구나...', `MaleText_loc4`='你佩戴的圣物散发着臭味，真恶心……', `MaleText_loc5`='你手裡拿著的那個神聖飾品發出的臭味讓我噁心...', `MaleText_loc7`='El hedor de ese abalorio sagrado que portas me asquea...' WHERE `ID`=30007;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그걸 포기하는 게 어떤가...', `MaleText_loc4`='你干嘛不扔掉它……', `MaleText_loc5`='你何不丟掉它呢...', `MaleText_loc7`='Por qué no lo desechas...' WHERE `ID`=30008;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리와 함께하라, $n. 리치 왕께 충성을 맹세하라. 리치 왕께 자신을 바치고 진정한 평화를 맛보라... 네가 울부짖으며 두려움에 떨면서 태어나던 그 순간부터 네게 허락되지 않았던 그 평화 말이다.', `MaleText_loc4`='加入我们吧，$n。起誓效忠巫妖王。全心全意地侍奉他，就能享受永恒的宁静……享受你降生以来从未体验过的宁静。', `MaleText_loc5`='加入我們，$n。臣服於巫妖王之下吧，將你奉獻給他，才能體會到平靜...那個從你那哭號、驚恐的誕生以來，一直拒絕的平靜。', `MaleText_loc7`='Únete a nosotros, $n. Jura lealtad al Rey Exánime. Entrégate a él y conocerás la paz... la paz que te ha sido negada desde tu aterrador y aullante nacimiento.' WHERE `ID`=30009;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이미 끝은 예정되어 있으니 우리와 싸워봤자 아무런 명예도 얻을 수 없다. 아제로스는... 쓰러질... 것이다.', `MaleText_loc4`='结局早已注定，何必再做徒劳的抗衡。艾泽拉斯世界……必将消亡。', `MaleText_loc5`='若是結局都已經註定，那麼和我們對抗則毫無榮耀可言。艾澤拉斯...已經...沒救了。', `MaleText_loc7`='No hay honor en luchar contra nosotros cuando el final ya ha sido escrito. Azeroth... morirá.' WHERE `ID`=30010;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래도 싸우겠다면, 죽기 전에 고통과 공포와 사랑하던 이들을 모두 잃는 아픔을 맛볼 것이다.', `MaleText_loc4`='如果你打算反抗，那么在死之前，你会体验到无尽的痛苦与恐惧，并眼睁睁地看着你挚爱的人撒手而去。', `MaleText_loc5`='如果你選擇作困獸之鬥，在你死以前，你將面對痛苦、恐懼，並且失去你所愛的一切。', `MaleText_loc7`='Si luchas, antes de morir te enfrentarás al dolor, el horror y a la pérdida de todos los que amas.' WHERE `ID`=30011;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑구나...', `MaleText_loc4`='欢迎……', `MaleText_loc5`='你好...', `MaleText_loc7`='Saludos...' WHERE `ID`=30012;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 네가 보이는구나...', `MaleText_loc4`='我看见你了……', `MaleText_loc5`='找到你了...', `MaleText_loc7`='Te veo...' WHERE `ID`=30013;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 거기 있구나...', `MaleText_loc4`='啊，你在那儿……', `MaleText_loc5`='啊，你在這...', `MaleText_loc7`='Ah, ahí estás...' WHERE `ID`=30014;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 있구나. 널 찾았다...', `MaleText_loc4`='瞧。我发现你了……', `MaleText_loc5`='就在這，我找到你了...', `MaleText_loc7`='Ahí. Te encontré...' WHERE `ID`=30016;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='투기장 전투가 60초 안에 종료됩니다.', `MaleText_loc4`='竞技场战斗将在60秒后结束。', `MaleText_loc5`='競技場戰鬥將於60秒內結束。', `MaleText_loc7`='La batalla de arena acaba en 60 segundos.' WHERE `ID`=30017;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='믿음을 잃지 마십시오. 총사령관님께서 리치 왕과 싸우는 우리를 승리로 이끌어주실 것입니다.', `MaleText_loc4`='坚守你的信仰。元帅会带领我们战胜巫妖王的。', `MaleText_loc5`='堅守你的信仰，上將會帶領我們打贏巫妖王。', `MaleText_loc7`='Conserva la fe. El Gran almirante nos llevará hasta la victoria contra el Rey Exánime.', `FemaleText_loc1`='믿음을 잃지 마세요. 총사령관님께서 리치 왕과 싸우는 우리를 승리로 이끌어주실 거예요.', `FemaleText_loc4`='坚守你的信仰。元帅会带领我们战胜巫妖王的。', `FemaleText_loc5`='堅守你的信仰，上將會帶領我們打贏巫妖王。', `FemaleText_loc7`='Conserva la fe. El Gran almirante nos llevará hasta la victoria contra el Rey Exánime.' WHERE `ID`=30018;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성스러운 빛의 이름으로 축복을 드립니다.', `MaleText_loc4`='接受圣光的祝福吧。', `MaleText_loc5`='以聖光之名接受這份祝福。', `MaleText_loc7`='Acepta esta bendición en el nombre de la Luz Sagrada.', `FemaleText_loc1`='성스러운 빛의 이름으로 축복을 드립니다.', `FemaleText_loc4`='接受圣光的祝福吧。', `FemaleText_loc5`='以聖光之名接受這份祝福。', `FemaleText_loc7`='Acepta esta bendición en el nombre de la Luz Sagrada.' WHERE `ID`=30019;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흔들리지 마십시오. 우리는 곧 빛의 신성한 보살핌 아래 거할 것입니다.', `MaleText_loc4`='不要动摇。我们很快就会沐浴在圣光中。', `MaleText_loc5`='切莫動搖，我們馬上就能沉浸在神聖的聖光之中。', `MaleText_loc7`='No desfallezcas. Pronto nos sentaremos ante la sagrada presencia de la Luz.', `FemaleText_loc1`='흔들리지 마세요. 우리는 곧 빛의 신성한 보살핌 아래 거할 거예요.', `FemaleText_loc4`='不要动摇。我们很快就会沐浴在圣光中。', `FemaleText_loc5`='切莫動搖，我們馬上就能沉浸在神聖的聖光之中。', `FemaleText_loc7`='No desfallezcas. Pronto nos sentaremos ante la sagrada presencia de la Luz.' WHERE `ID`=30020;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 중에 첩자가 있으니 경계를 늦추지 마십시오. 칠흑의 기사단은 그들의 진정한 지도자인 리치 왕을 멸하지 못하도록 우리를 막으려 하니 말입니다.', `MaleText_loc4`='我们中间混进了一些反叛份子，最好保持警惕。黑锋骑士团企图阻止我们消灭他们真正的主子——巫妖王。', `MaleText_loc5`='我們之中有惡徒 - 保持警覺。黯刃騎士團處心積慮阻止我們消滅他們的真正主人，巫妖王。', `MaleText_loc7`='Entre nosotros hay villanos, permanece alerta. La Espada de Ébano quiere evitar que destruyamos a su verdadero señor, el Rey Exánime.', `FemaleText_loc1`='우리 중에 첩자가 있으니 경계를 늦추지 마세요. 칠흑의 기사단은 그들의 진정한 지도자인 리치 왕을 멸하지 못하도록 우리를 막으려 하니 말이에요.', `FemaleText_loc4`='我们中间混进了一些反叛份子，最好保持警惕。黑锋骑士团企图阻止我们消灭他们真正的主子——巫妖王。', `FemaleText_loc5`='我們之中有惡徒 - 保持警覺。黯刃騎士團處心積慮阻止我們消滅他們的真正主人，巫妖王。', `FemaleText_loc7`='Entre nosotros hay villanos, permanece alerta. La Espada de Ébano quiere evitar que destruyamos a su verdadero señor, el Rey Exánime.' WHERE `ID`=30021;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성스러운 빛이 주시는 시련에 의문을 품지 마십시오. 전부를 희생하는 사람만이 빛으로 나아갈 수 있습니다.', `MaleText_loc4`='不要怀疑圣光所给予的指示。只有甘愿奉献一切的人才能感受到它的存在。', `MaleText_loc5`='切莫質疑聖光在你面前顯現的模樣。唯有犧牲一切者，方能帶往祂的面前。', `MaleText_loc7`='No cuestiones lo que la Luz Sagrada ha puesto ante ti. Solo los que lo sacrifiquen todo podrán alcanzar su presencia.', `FemaleText_loc1`='성스러운 빛이 주시는 시련에 의문을 품지 마세요. 전부를 희생하는 사람만이 빛으로 나아갈 수 있답니다.', `FemaleText_loc4`='不要怀疑圣光所给予的指示。只有甘愿奉献一切的人才能感受到它的存在。', `FemaleText_loc5`='切莫質疑聖光在你面前顯現的模樣。唯有犧牲一切者，方能帶往祂的面前。', `FemaleText_loc7`='No cuestiones lo que la Luz Sagrada ha puesto ante ti. Solo los que lo sacrifiquen todo podrán alcanzar su presencia.' WHERE `ID`=30022;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='웨스트윈드 총사령관님께서 따로 계획을 세워두셨습니다... 앞을 내다보십니다. 우리도 믿음을 잃지 말고 흔들림 없이 이 세상을 위해 할 일을 해야 합니다.', `MaleText_loc4`='巴利·韦斯温元帅有一项计划……这也是他多年的愿望。为了拯救世界，我们在执行这项计划的过程中必须保持坚定和虔诚的态度。', `MaleText_loc5`='韋斯溫上將有個計畫...有個願景。我們必須保持信念，堅信這一切的都是為了這個世界而執行的。', `MaleText_loc7`='El gran almirante Viento Oeste tiene un plan... una visión. Debemos ser leales y firmes, de su ejecución depende el destino del mundo.', `FemaleText_loc1`='웨스트윈드 총사령관님께서 따로 계획을 세워두셨어요... 앞을 내다보시지요. 우리도 믿음을 잃지 말고 흔들림 없이 이 세상을 위해 할 일을 해야 해요.', `FemaleText_loc4`='巴利·韦斯温元帅有一项计划……这也是他多年的愿望。为了拯救世界，我们在执行这项计划的过程中必须保持坚定和虔诚的态度。', `FemaleText_loc5`='韋斯溫上將有個計畫...有個願景。我們必須保持信念，堅信這一切的都是為了這個世界而執行的。', `FemaleText_loc7`='El gran almirante Viento Oeste tiene un plan... una visión. Debemos ser leales y firmes, de su ejecución depende el destino del mundo.' WHERE `ID`=30023;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳은 살을 에는 듯하지만, 저는 춥지 않습니다. 성스러운 빛의 영광에 싸여 있으니까요. 부디 용기를 잃지 마십시오.', `MaleText_loc4`='虽然这里天寒地冻，但是沐浴在圣光中，我却倍感温暖。不要气馁。', `MaleText_loc5`='這片土地即使冰天雪地，我依舊溫暖，正因為我被覆在聖光的光輝之下。切莫氣餒。', `MaleText_loc7`='La tierra se está congelando, pero yo siento calor, pues estoy cubierto con el manto de la Luz Sagrada. No te rindas.', `FemaleText_loc1`='이곳은 살을 에는 듯하지만, 저는 춥지 않아요. 성스러운 빛의 영광에 싸여 있기 때문이죠. 부디 용기를 잃지 마세요.', `FemaleText_loc4`='虽然这里天寒地冻，但是沐浴在圣光中，我却倍感温暖。不要气馁。', `FemaleText_loc5`='這片土地即使冰天雪地，我依舊溫暖，正因為我被覆在聖光的光輝之下。切莫氣餒。', `FemaleText_loc7`='La tierra se está congelando, pero yo siento calor, pues estoy cubierto con el manto de la Luz Sagrada. No te rindas.' WHERE `ID`=30024;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제독님의 명령입니다. 죽음의 고통이 도사린 섬의 남쪽 부근에는 가까이 가지 마십시오. 그리고 이 소식을 널리 퍼뜨려 주십시오.', `MaleText_loc4`='元帅有令，禁止进入岛屿南端，违者处死。把这个命令传下去。', `MaleText_loc5`='奉上將的旨意，遠離島嶼的南方避免苦痛與死亡，把這句話傳下去。', `MaleText_loc7`='Por orden del Gran almirante, mantente lejos del lado sur de la isla bajo pena de muerte. Extiende la noticia.', `FemaleText_loc1`='제독님의 명령이에요. 죽음의 고통이 도사린 섬의 남쪽 부근에는 가까이 가지 마세요. 그리고 이 소식을 널리 퍼뜨려 주세요.', `FemaleText_loc4`='元帅有令，禁止进入岛屿南端，违者处死。把这个命令传下去。', `FemaleText_loc5`='奉上將的旨意，遠離島嶼的南方避免苦痛與死亡，把這句話傳下去。', `FemaleText_loc7`='Por orden del Gran almirante, mantente lejos del lado sur de la isla bajo pena de muerte. Extiende la noticia.' WHERE `ID`=30025;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드는 아직 포위된 상태입니다. 죽음의 요새는 그 윤곽을 흐릿하게 드러냈으며, 스컬지가 가끔 출몰한다는 나타난다는 보고가 있었습니다.', `MaleText_loc4`='暴风城的危机尚未解除——有报告称城外飘来了一座浮空城，天灾兵进攻的事件也时有发生。', `MaleText_loc5`='暴風城仍然四面楚歌 -- 亡域隱約得出現在城牆之上，零星傳來天譴軍團攻擊的消息。', `MaleText_loc7`='Ventormenta sigue bajo asedio: una necrópolis sobrevuela sus muros y hay informes de ataques aleatorios de la Plaga.', `FemaleText_loc1`='스톰윈드는 아직 포위된 상태에요. 죽음의 요새는 그 윤곽을 흐릿하게 드러냈으며, 스컬지가 가끔 출몰한다는 나타난다는 보고가 있어요.', `FemaleText_loc4`='暴风城的危机尚未解除——有报告称城外飘来了一座浮空城，天灾兵进攻的事件也时有发生。', `FemaleText_loc5`='暴風城仍然四面楚歌 -- 亡域隱約得出現在城牆之上，零星傳來天譴軍團攻擊的消息。', `FemaleText_loc7`='Ventormenta sigue bajo asedio: una necrópolis sobrevuela sus muros y hay informes de ataques aleatorios de la Plaga.' WHERE `ID`=30026;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갓 죽은 좀비가 시체 마차에 실려 속속들이 도착하고 있습니다. 들어오는 숫자는 점점 줄지만 말입니다.', `MaleText_loc4`='尽管敌人的数量在不断减少，但是天灾军团的绞肉车源源不断地送来了新鲜的僵尸。', `MaleText_loc5`='剛被殺死的殭屍被血屍戰車運來，但是它們的數量正逐漸減少中。', `MaleText_loc7`='Los zombis recién muertos van llegando en carros de despojos, pero su número va descendiendo.', `FemaleText_loc1`='갓 죽은 좀비가 시체 마차에 실려 속속들이 도착하고 있어요. 들어오는 숫자는 점점 줄지만요.', `FemaleText_loc4`='尽管敌人的数量在不断减少，但是天灾军团的绞肉车源源不断地送来了新鲜的僵尸。', `FemaleText_loc5`='剛被殺死的殭屍被血屍戰車運來，但是它們的數量正逐漸減少中。', `FemaleText_loc7`='Los zombis recién muertos van llegando en carros de despojos, pero su número va descendiendo.' WHERE `ID`=30027;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마지막으로 동부 역병지대를 공격했을 때 사망자가 양쪽 모두에서 엄청나게 나왔습니다.', `MaleText_loc4`='最近一次在东瘟疫之地爆发的冲突中，双方都伤亡惨重。', `MaleText_loc5`='東瘟疫之地最後一次的大戰產生了大量的死者，雙方都死傷慘重。', `MaleText_loc7`='El último ataque en las Tierras de la Peste del Este proporcionó una gran cosecha de muertos, de ambos bandos.', `FemaleText_loc1`='마지막으로 동부 역병지대를 공격했을 때 사망자가 양쪽 모두에서 엄청나게 나왔지요.', `FemaleText_loc4`='最近一次在东瘟疫之地爆发的冲突中，双方都伤亡惨重。', `FemaleText_loc5`='東瘟疫之地最後一次的大戰產生了大量的死者，雙方都死傷慘重。', `FemaleText_loc7`='El último ataque en las Tierras de la Peste del Este proporcionó una gran cosecha de muertos, de ambos bandos.' WHERE `ID`=30028;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타나리스 사막에서 은빛 여명회 대원들이 중대한 승리를 거두었습니다.', `MaleText_loc4`='银色黎明在塔纳利斯的荒漠中赢得了决定性的胜利。', `MaleText_loc5`='銀色黎明的密探在塔納利斯的沙漠中獲得了決定性的勝利。', `MaleText_loc7`='Los agentes de El Alba Argenta han conseguido una victoria decisiva en el Desierto de Tanaris.', `FemaleText_loc1`='타나리스 사막에서 은빛 여명회 대원들이 중대한 승리를 거두었답니다.', `FemaleText_loc4`='银色黎明在塔纳利斯的荒漠中赢得了决定性的胜利。', `FemaleText_loc5`='銀色黎明的密探在塔納利斯的沙漠中獲得了決定性的勝利。', `FemaleText_loc7`='Los agentes de El Alba Argenta han conseguido una victoria decisiva en el Desierto de Tanaris.' WHERE `ID`=30029;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='희망의 빛 예배당은 역병지대에서 마지막 보루로 남아 있습니다. 그곳을 본거지로 삼은 은빛 여명회가 그 지역을 지키는 결정적인 역할을 맡았습니다.', `MaleText_loc4`='圣光之愿礼拜堂是瘟疫之地仅存的据点。银色黎明必须在那里站稳脚跟，才能确保整个地区的安全。', `MaleText_loc5`='聖光之願禮拜堂巍然成為了瘟疫之地的壁壘。這座銀色黎明的堡壘是拯救這個區域的關鍵。', `MaleText_loc7`='La Capilla de la Esperanza de la Luz sigue siendo un bastión en las Tierras de la Peste. La posición allí establecida por El Alba Argenta es clave para asegurar la zona.', `FemaleText_loc1`='희망의 빛 예배당은 역병지대에서 마지막 보루로 남아 있어요. 그곳을 본거지로 삼은 은빛 여명회가 그 지역을 지키는 결정적인 역할을 맡았지요.', `FemaleText_loc4`='圣光之愿礼拜堂是瘟疫之地仅存的据点。银色黎明必须在那里站稳脚跟，才能确保整个地区的安全。', `FemaleText_loc5`='聖光之願禮拜堂巍然成為了瘟疫之地的壁壘。這座銀色黎明的堡壘是拯救這個區域的關鍵。', `FemaleText_loc7`='La Capilla de la Esperanza de la Luz sigue siendo un bastión en las Tierras de la Peste. La posición allí establecida por El Alba Argenta es clave para asegurar la zona.' WHERE `ID`=30030;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일어나라, 너 말이다!', `MaleText_loc4`='打起精神来！', `MaleText_loc5`='飯桶，就是你!', `MaleText_loc7`='¡Ríndete, tú!' WHERE `ID`=30031;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇다네, 리치 왕은 우리 앞에 무릎 꿇을 것이야. 우린 마지막 복수를 해낼 걸세.$B$B그전에, 붉은돌격대라 알려진 골칫거리를 반드시 끝장내고 말겠네!', `MaleText_loc4`='我相信，巫妖王会败在我们手下。我们的复仇大业一定会取得成功。$B$B但首先，我们必须将血色先锋军这个祸端彻底解决掉！', `MaleText_loc5`='是的，巫妖王將不敵我們的力量。我們會完成最後的復仇。$B$B但首先，我們得將那些像瘟疫般的血色突襲軍一勞永逸地解決掉!', `MaleText_loc7`='Sí, el Rey Exánime caerá ante nuestro poder. Obtendremos nuestra venganza final.$B$B¡Pero primero nos aseguraremos de que la peste conocida como El Embate Escarlata conozca su final de una vez por todas!' WHERE `ID`=30032;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사령관님, 이야기를 듣고 싶습니다.', `MaleText_loc4`='高级指挥官，我要听你的故事。', `MaleText_loc5`='指揮統領，我要聆聽你的故事。', `MaleText_loc7`='Lord comandante, quisiera escuchar tu historia.', `FemaleText_loc1`='사령관님, 이야기를 듣고 싶어요.', `FemaleText_loc4`='高级指挥官，我要听你的故事。', `FemaleText_loc5`='指揮統領，我要聆聽你的故事。', `FemaleText_loc7`='Lord comandante, quisiera escuchar tu historia.' WHERE `ID`=30033;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 생각했네. 내가 자네라면 이야기를 들으면서 그저 머리만 끄덕이는 대신 진정으로 귀를 기울여 볼 걸세.$B$B괜찮은 이야기가 다 그렇듯이, 배신에서 시작되는 이야기일세. 아, 우리가 배신당했다는 얘기가 아니네... 전혀 아니야. 리치 왕이 우리 죽음의 기사를 어떤 존재보다 우월하도록 세웠지.$B$B오히려 대영주 다리온 모그레인의 도움을 받아 리치 왕을 배신한 건 우리였네.$B$B역병지대에 있는 희망의 빛 예배당에서 마지막 전투를 벌일 때, 티리온 폴드링이 모그레인과 남아 있던 우리 전부가 리치 왕의 지배에서 벗어날 수 있도록 도와주었지.', `MaleText_loc4`='好吧，但如果我是你的话，我会集中精神仔细聆听，而不是盲目地点点头表示回应。$B$B和所有精彩的故事一样，这个故事也是以背叛开场的。不过，并非是别人背叛了我们……事情并非如此。在巫妖王的众多仆从中，他最看重的就是我们——死亡骑士。$B$B但是，在大领主达里安·莫格莱尼的帮助下，我们背叛了他。$B$B瘟疫之地圣光之愿礼拜堂的那场决战中，就在我们几乎全军覆没的紧要关头，提里奥·弗丁帮助莫格莱尼以及幸存的死亡骑士摆脱了巫妖王的束缚。', `MaleText_loc5`='非常好，但如果我是你，我會仔細聽著，不只是隨便聽聽，點點頭而已。$B$B故事的開始，就像所有的故事一樣，開始於背叛。噢，不是我們被背叛...差得遠了。巫妖王除了我們這些死亡騎士之外，誰也沒復活。$B$B然而，我們卻藉著大領主達瑞安·莫格萊尼的協助，背叛了他。$B$B在聖光之願禮拜堂的最終的決戰中，當這些笨蛋就要被毀滅之時，提里奧·弗丁幫助莫格萊尼打破了巫妖王對他的束縛，還有我們在場的所有人。', `MaleText_loc7`='Muy bien, pero si yo fuera tú, prestaría atención y no asentiría ciegamente a todo lo que escuchase.$B$BEmpieza, tal y como empiezan todas las buenas historias, con una traición. No es que fuésemos traicionados... en absoluto. El Rey Exánime nos ascendió a los caballeros de la Muerte por encima de los demás.$B$BMás bien fuimos nosotros los que le traicionamos con la ayuda del alto señor Darion Mograine.$B$BEn la batalla final en la Capilla de la Esperanza de la Luz, cuando esos infelices estaban a punto de ser aniquilados, Tirion Vadín ayudó a Mograine a romper el control que el Rey Exánime tenía sobre él y de todos los que estábamos allí presentes.' WHERE `ID`=30034;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<당신은 가볍게 고개를 끄덕이다가, 말을 이으려다가 눈살을 찌푸리는 사령관을 보고 동작을 멈춥니다.>', `MaleText_loc4`='<你微微地点了点头，高级指挥官顿时眯起了眼睛。于是你赶紧停止动作，他这才开口继续说起了故事。>', `MaleText_loc5`='<你正準備點頭，指揮統領瞇起眼睛準備繼續說下去的舉動，讓你暫停了動作。>', `MaleText_loc7`='<Asientes levemente con la cabeza, pero no completas el movimiento ya que el Lord comandante entrecierra sus ojos antes de continuar.>', `FemaleText_loc1`='<당신은 가볍게 고개를 끄덕이다가, 말을 이으려다가 눈살을 찌푸리는 사령관을 보고 동작을 멈춥니다.>', `FemaleText_loc4`='<你微微地点了点头，高级指挥官顿时眯起了眼睛。于是你赶紧停止动作，他这才开口继续说起了故事。>', `FemaleText_loc5`='<你正準備點頭，指揮統領瞇起眼睛準備繼續說下去的舉動，讓你暫停了動作。>', `FemaleText_loc7`='<Asientes levemente con la cabeza, pero no completas el movimiento ya que el Lord comandante entrecierra sus ojos antes de continuar.>' WHERE `ID`=30035;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그냥 단념하고 목숨을 바쳐라!', `MaleText_loc4`='放弃吧，老老实实地受死吧。', `MaleText_loc5`='放棄吧，老老實實地受死吧。', `MaleText_loc7`='Ríndete y muere de una vez.' WHERE `ID`=30036;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕은 파멸의 인도자를 든 폴드링을 두려워하며 달아났고, 우리는 남아 있던 스컬지 병력을 처치하고 칠흑의 요새를 쉽게 차지할 수 있었네.$B$B그래도 우리와 붉은십자군 사이에는 앙금이 가라앉지 않았네.$B$B포세이큰은 쓰라린 경험에서 배웠지만, 붉은십자군 놈들은 우리와 스컬지를 구별하지 못하는 것 같더군.$B$B우리는 자주적으로 생각하고, 우리만의 동기에 따라 움직이며 거의 모든 부분에서 훌륭한 생활양식도 갖추었네. 그러나 그놈들에게는 우리나 리치 왕을 맹목적으로 따르는 노예 놈들이나 매한가지였나 보더군.$B$B그놈들은 우리가 리치 왕이 시키면 죽은 척이라도 할 거라는 그릇된 생각을 한다네.', `MaleText_loc4`='弗丁举起了灰烬使者，巫妖王见势不妙，便迅速逃走了。于是，我们轻而易举地从残余的天灾兵手中夺取了黑锋要塞的控制权。$B$B但是我们与血色十字军的隔阂并没有消除。$B$B就像被遗忘者当初的境遇一样，血色十字军总是将我们与天灾军团混为一谈。$B$B我们拥有独立的思想和目标，我们拥有生者的一切特质。但是对他们来说，我们和巫妖王麾下那些没脑子的奴隶没什么两样。$B$B他们居然误认为我们会再次臣服于巫妖王的淫威。', `MaleText_loc5`='巫妖王因為弗丁握有灰燼使者而害怕得逃之夭夭，我們才能輕易地從殘存的天譴軍手中拿下黯黑堡。$B$B但這並未解決我們與血色十字軍之間的糾紛。$B$B被遺忘者經歷了一番艱辛才獲得認同，然而那些血色傢伙似乎分辨不出我們與天譴軍之間的差異。$B$B我們有自己的想法，我們有自己的信念，我們有活人的大部分特質，但是對他們來說，我們與巫妖王無腦的奴隸之間並無二致。$B$B他們認為我們隨時會翻臉不認人。', `MaleText_loc7`='Con el Rey Exánime huyendo aterrado de Vadín, que estaba armado con la Crematoria, pudimos arrebatarle El Bastión de Ébano al resto de fuerzas de la Plaga.$B$BPero eso no arregló las cosas entre nosotros y la Cruzada Escarlata.$B$BTal y como los Renegados aprendieron de la forma más difícil, los Escarlatas no parecían hacer diferencias entre nosotros y la Plaga.$B$BPensamos por nosotros mismos, tenemos nuestras propias motivaciones, tenemos casi todas las cualidades de los vivos y aun así, para ellos no somos distintos de los esclavos sin mente del Rey Exánime.$B$BPiensan erróneamente que nos tumbaremos y nos haremos los muertos.' WHERE `ID`=30037;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들이 지금은 스스로 붉은돌격대라 칭하는 그들 아닙니까?', `MaleText_loc4`='他们现在自称血色先锋军了吧？', `MaleText_loc5`='我以為，他們現在應該自稱是「血色突襲軍」，對吧?', `MaleText_loc7`='Pensaba que ahora se hacían llamar El Embate Escarlata.', `FemaleText_loc1`='그들이 지금은 스스로 붉은돌격대라 칭하는 그들 아닌가요?', `FemaleText_loc4`='他们现在自称血色先锋军了吧？', `FemaleText_loc5`='我以為，他們現在應該自稱是「血色突襲軍」，對吧?', `FemaleText_loc7`='Pensaba que ahora se hacían llamar El Embate Escarlata.' WHERE `ID`=30038;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사령관님, 이전 얘기를 다시 들려주시겠습니까?', `MaleText_loc4`='高级指挥官，能再讲一遍刚才的故事吗？', `MaleText_loc5`='指揮統領，你願意將之前說過的話重複一遍嗎?', `MaleText_loc7`='Lord comandante, ¿podría repetirme lo que ha dicho antes?', `FemaleText_loc1`='사령관님, 이전 얘기를 다시 들려주시면 안 될까요?', `FemaleText_loc4`='高级指挥官，能再讲一遍刚才的故事吗？', `FemaleText_loc5`='指揮統領，你願意將之前說過的話重複一遍嗎?', `FemaleText_loc7`='Lord comandante, ¿podría repetirme lo que ha dicho antes?' WHERE `ID`=30039;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<이야기를 계속하려다가 당신을 쏘아보는 사령관>$B$B안 그래도, 그 얘기를 하려던 참이었네. 맞네. 아벤디스 고위사령관이 노스렌드에 병력을 주둔시켰을 때, 붉은돌격대로 이름을 바꾸었지.$B$B얼마 후에 바리안 웨스트윈드 제독이 용의 안식처에 있는 신 하스글렌에 모습을 드러냈네. 아벤디스 고위사령관은 제독이 오리라고는 전혀 예상도 못했지. 제독이 자기 권위를 깎아내리고 명령권을 가져가리라고는 더더욱 생각 못했고 말이네.$B$B아벤디스 고위사령관의 죽음에는 자네도 연관이 있는 것 같더군. 하지만, 상관없네. 고위사령관이 죽은 다음, 제독은 기묘하게 종적을 감추어서 더는 행방을 추적할 수 없었네.', `MaleText_loc4`='<高级指挥官瞪了你一眼，继续说道。>$B$B我马上就会讲到了。没错，阿比迪斯将军率领部队抵达诺森德后，就将血色十字军更名为血色先锋军了。$B$B先锋军驻扎龙骨荒野的新壁炉谷后不久，海军上将巴利·韦斯温前来拜访。据说，阿比迪斯将军完全没有料到他会来。她更没有料到韦斯温上将动摇了她在军中的地位，并最终夺得了兵权。$B$B你一定要问，她怎么能心甘情愿地让位呢，但这已经不重要了。阿比迪斯将军死后，韦斯温也神秘失踪了，我们一直没有找到他。', `MaleText_loc5`='<指揮統領繼續說下去之前，瞪得你一動也不敢動。>$B$B我馬上就要說到了。的確，當大將軍阿比迪斯率領她的大軍登陸北裂境之後，便將血色十字軍的名稱改為了血色突襲軍。$B$B這件事就在海軍上將巴瑞恩·西風與她在龍骨荒野的新壁爐谷會面前不久。各方揣測，阿比迪斯並不期待他會有什麼表現。同時阿比迪斯也不認為自己對血色突襲軍的統帥與權威會被他暗中削弱。$B$B就如同你被牽扯進阿比迪斯的權力鬥爭之中，但這無所謂。當她一死，上將就神秘地潛逃，連我們也跟丟了。', `MaleText_loc7`='<El lord comandante te clava la mirada antes de continuar.>$B$BA eso iba. Cuando la Alta General Abbendis trajo a sus fuerzas a Rasganorte, cambió su nombre por el de El Embate Escarlata.$B$BEl almirante Barean Viento Oeste no tardó mucho en presentarse ante ella en Nueva Vega del Amparo en el Cementerio de Dragones. Por lo que parece, ella no le esperaba. Y tampoco se esperaba que minase su autoridad y le arrebatase las riendas de mando.$B$BProbablemente estuviste $ginvolucrado:involucrada; en su caída, pero da igual. Una vez que ella murió, el almirante se fue de forma misteriosa y le hemos perdido el rastro.' WHERE `ID`=30040;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배고프다! 목마르다! 밥 내놔!', `MaleText_loc4`='我要内脏！要鲜血！要食物！', `MaleText_loc5`='更多內臟!更多鮮血!更多食物!', `MaleText_loc7`='¡Mis entrañas! ¡Mi sangre! ¡Mi comida!' WHERE `ID`=30041;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좀 이따 슥슥 해서 꿀꺽!', `MaleText_loc4`='把你剁碎，再吃掉！', `MaleText_loc5`='把你剁碎，再吃掉!', `MaleText_loc7`='¡Yo cortarte y comerte!' WHERE `ID`=30042;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 배고파! 밥 줘!', `MaleText_loc4`='好饿啊！必须吃饭！', `MaleText_loc5`='好餓啊!必須吃飯!', `MaleText_loc7`='¡Hambre! ¡Comer!' WHERE `ID`=30043;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='터져라, 뻥!', `MaleText_loc4`='要爆炸啦！', `MaleText_loc5`='屍體要爆炸啦!', `MaleText_loc7`='¡Cadáver hacer BUM!' WHERE `ID`=30044;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제독은 어디로 갔습니까?', `MaleText_loc4`='韦斯温元帅去哪儿了？', `MaleText_loc5`='上將去哪裡了?', `MaleText_loc7`='¿Adónde ha ido el Gran almirante?', `FemaleText_loc1`='제독은 어디로 갔나요?', `FemaleText_loc4`='韦斯温元帅去哪儿了？', `FemaleText_loc5`='上將去哪裡了?', `FemaleText_loc7`='¿Adónde ha ido el Gran almirante?' WHERE `ID`=30045;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말했잖나. 그를 놓쳤다고. 자네가 밝혀내 주리라 믿는 일이 바로 그것일세. 저 아래쪽 어딘가로 갔으리라고 의심은 하네만, 내가 보낸 첩자들은 섬 어느 곳에서도 그를 찾아내지 못했네.$B$B신 하스글렌은 원한의 초소에서 온 포세이큰이 제대로 파괴해 버렸지만, 아래에 있는 돌격대 병력은 그 자리에서 전투로 잔뼈가 굵은 놈들일세. 어딘가에 있는 바보들에게서 그리핀뿐만 아니라 장비도 빼앗아 단단히 무장했다네.$B$B내 말은 이 전투를 설렁설렁할 수는 없을 거라는 얘기네. $n, 자네라 해도 말일세.', `MaleText_loc4`='我说过，我们失去了他的行踪，但我相信你能帮我们找到他。我怀疑他就躲在岛上，可是我派出的探子始终搜不到他的藏身之所。$B$B虽然怨毒镇的被遗忘者对新壁炉谷展开了一系列的攻击行动，但如今残余在那里的先锋军都是身经百战的强者。不幸的是，他们设法获得了更精良的装备，还从某些白痴手里弄到了狮鹫。$B$B我想说，$n，不管你有多厉害，这项任务绝非是去乡间散步那么简单。', `MaleText_loc5`='我說過，我們跟丟他了。但是我相信你能替我把他揪出來的。我懷疑他應該在下面某處，但是我的間諜無法在島上找到他。$B$B毒怨之地的被遺忘者幹得很好，成功的破壞了新壁爐谷，但是那兒的突襲軍只是善戰部隊的殘餘。不幸的是，他們沿途獲得了精良的裝備，還有獅鷲獸可以載著那些笨蛋東奔西走。$B$B我想要強調的是，$n，即使對你來說，這也不是鄉間遠足。', `MaleText_loc7`='Como he dicho, le perdimos el rastro, pero sin duda es algo de lo que podrás encargarte por mí. Sospecho que está ahí abajo, en alguna parte, pero los espías que han vuelto no han sido capaces de localizarlo en la isla.$B$BLos Renegados en Rencor Venenoso hicieron un buen trabajo saboteando la Nueva Vega del Amparo, pero las fuerzas del Embate que están presentes ahí abajo son los veteranos de ese lugar. Por desgracia han conseguido mejor equipo por el camino y unos grifos que les habrán quitado a algunos idiotas.$B$BLo que intento decir es que esto no va a ser un paseo por el campo, $n, ni siquiera para ti.' WHERE `ID`=30046;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상관없습니다. 언제 출발하면 되겠습니까?', `MaleText_loc4`='没问题。什么时候可以开始行动？', `MaleText_loc5`='沒問題，我什麼時候出發?', `MaleText_loc7`='Está bien. ¿Cuándo empiezo?', `FemaleText_loc1`='상관없어요. 언제 출발할까요?', `FemaleText_loc4`='没问题。什么时候可以开始行动？', `FemaleText_loc5`='沒問題，我什麼時候出發?', `FemaleText_loc7`='Está bien. ¿Cuándo empiezo?' WHERE `ID`=30047;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 모두 곧 출발할 걸세.$B$B확실히 하고 싶은 것이 하나 있네. 우리는 그놈들 세력을 누그러뜨릴 요량으로 여기 온 것이 아니네. 흠집이나 내러 온 것이 아니라는 소릴세. 스스로 붉은돌격대라 칭하는 병균 같은 존재를 완전히 끝장내러 온 것이네.$B$B이 일을 하고 싶지 않다면, 그럴 배짱이 없다면 당장 날아가 버리게. 이 일을 완전히 끝낼 때까지 매일 우리와 함께할 사람이 필요하네.$B$B그럴 자신이 있나?', `MaleText_loc4`='我们很快就要展开行动了。$B$B但是我必须说明——我们不是来削弱他们的士气的，也不是来吸引敌人的火力的。我们的目标是，彻底消灭血色先锋军。$B$B如果你对此不感兴趣，就趁早滚远点。我需要的是每天都能来帮忙，直到使命达成的伙伴。$B$B你觉得自己能胜任吗，$n？', `MaleText_loc5`='我們馬上就會出發。$B$B我醜話說在前頭 -- 我們不光是要削弱他們，我們不只是騷擾他們，我們要把這種被叫做血色突襲軍的疾病一勞永逸的解決。$B$B如果你不想受牽連，如果你沒有興趣，現在就滾。我要一個願意日以繼夜的跟著我們、直到事情完成的人。$B$B你是那個我們要找的人嗎，$n?', `MaleText_loc7`='Empezaremos en un momento.$B$BSolo quiero ser muy claro: no estamos aquí para ablandarlos. No estamos aquí para hacerles mella. Estamos aquí para poner fin a esa enfermedad que se autodenomina El Embate Escarlata.$B$BSi no quieres formar parte de esto, si no tienes las agallas necesarias, vete volando ya. Quiero a alguien que esté con nosotros todos los días hasta terminar el trabajo.$B$B¿Eres tú esa persona, $n?' WHERE `ID`=30048;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끝장내러 갑시다!', `MaleText_loc4`='来吧，消灭先锋军！', `MaleText_loc5`='讓我們解決這件事吧!', `MaleText_loc7`='¡Acabemos con esto!', `FemaleText_loc1`='끝장내러 가요!', `FemaleText_loc4`='来吧，消灭先锋军！', `FemaleText_loc5`='讓我們解決這件事吧!', `FemaleText_loc7`='¡Acabemos con esto!' WHERE `ID`=30049;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<당신을 위아래로 재듯이 바라보며 입을 벌린 채 슬쩍 미소 짓는 사령관>$B$B듣고 싶던 대답이군.', `MaleText_loc4`='<高级指挥官咧嘴一笑，从头到脚地打量了你一番。>$B$B这正是我想听的。', `MaleText_loc5`='<指揮統領笑得咧起嘴巴，目光銳利的上下端詳著你。>$B$B這才是我想聽的。', `MaleText_loc7`='<El lord comandante hace una mueca, mirándote de arriba abajo con respeto.>$B$BEso es lo que quería oír.' WHERE `ID`=30050;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왕이시여! 폐하의 목소리가 들리지 않습니다! 저를 떠나시면 안 됩니다!', `MaleText_loc4`='王！我听不见你的声音！别扔下我！', `MaleText_loc5`='吾王!我聽不見您的聲音!不要拋下我!', `MaleText_loc7`='¡Mi rey! ¡No puedo escuchar tu voz! ¡No me abandones!' WHERE `ID`=30051;
