UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼은 희망에 취하기 쉽지. 그리고 네 영혼은 리치 왕께서 입맛을 달래는 안줏거리로 삼으시면 딱 맞겠어!', `MaleText_loc4`='希望让灵魂变得甜蜜起来，巫妖王会喜欢你这道甜品的！', `MaleText_loc5`='希望讓靈魂更甜美，而你的靈魂將會是巫妖王最可口的點心!', `MaleText_loc7`='¡La esperanza endulza el alma y la tuya será un gran postre para el Rey Exánime!' WHERE `ID`=30059;
