UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 안돼! $n|1이;가; 아파 보이잖아!', `MaleText_loc4`='哎呀！$n好像受伤了！', `MaleText_loc5`='噢，不!$n看起來受傷了!', `MaleText_loc7`='¡Oh, no! ¡$n parece $gherido:herida;!', `FemaleText_loc1`='아, 안돼! $n|1이;가; 아파 보이잖아!', `FemaleText_loc4`='哎呀！$n好像受伤了！', `FemaleText_loc5`='噢，不!$n看起來受傷了!', `FemaleText_loc7`='¡Oh, no! ¡$n parece $gherido:herida;!' WHERE `ID`=30077;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서, $n! 너를 타고 가려고 돈을 잔뜩 준비해놨어!', `MaleText_loc4`='加油，$n！我靠你才赚了大钱啊！', `MaleText_loc5`='快啊，$n!我在你身上下了一大筆錢!', `MaleText_loc7`='¡Vamos, $n! ¡Tengo mucho dinero invertido en ti!', `FemaleText_loc1`='어서요, $n! 당신을 타고 가려고 돈을 잔뜩 준비해놨어요!', `FemaleText_loc4`='加油，$n！我靠你才赚了大钱啊！', `FemaleText_loc5`='快啊，$n!我在你身上下了一大筆錢!', `FemaleText_loc7`='¡Vamos, $n! ¡Tengo mucho dinero invertido en ti!' WHERE `ID`=30078;
