UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서, $n! 날 실망시키지 마!', `MaleText_loc4`='加油，$n！别让我失望！', `MaleText_loc5`='加油啊，$n!別讓我失望!', `MaleText_loc7`='¡Vamos, $n! ¡No me falles!', `FemaleText_loc1`='어서요, $n! 절 실망시키지 말아요!', `FemaleText_loc4`='加油，$n！别让我失望！', `FemaleText_loc5`='加油啊，$n!別讓我失望!', `FemaleText_loc7`='¡Vamos, $n! ¡No me falles!' WHERE `ID`=30085;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1을;를; 둘러싼 거품 보호막이 터집니다!', `MaleText_loc4`='%s的防御气泡破裂了！', `MaleText_loc5`='%s的保護泡泡破碎了!', `MaleText_loc7`='¡La Burbuja protectora de %s se rompe!' WHERE `ID`=30086;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 소환을 시작합니다!', `MaleText_loc4`='%s开始召唤！', `MaleText_loc5`='%s開始召喚!', `MaleText_loc7`='¡%s comienza a invocar!' WHERE `ID`=30087;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕이 얼어붙은 황무지 북쪽을 휘젓고 있다는 얘기를 들었습니다. 리치 왕은 얼음왕관이라는 요새를 세웠고 우리에게 파멸을 안겨줄 계획도 세웠다더군요.', `MaleText_loc4`='听说巫妖王在北方的冰冻废土兴风作浪。他建起了一座名叫冰冠堡垒的城堡，想要消灭我们。', `MaleText_loc5`='我聽說巫妖王在北方，把冰凍荒原搞得天翻地覆。他建築了一座堡壘，寒冰皇冠，正計畫著我們的末日。', `MaleText_loc7`='He oído que el Rey Exánime está preparándose en el norte en los Baldíos Helados. Ha construido una fortaleza, Corona de Hielo y planea nuestra perdición.', `FemaleText_loc1`='리치 왕이 얼어붙은 황무지 북쪽을 휘젓고 있다는 얘기를 들었어요. 리치 왕은 얼음왕관이라는 요새를 세웠고 우리에게 파멸을 안겨줄 계획도 세웠다더군요.', `FemaleText_loc4`='听说巫妖王在北方的冰冻废土兴风作浪。他建起了一座名叫冰冠堡垒的城堡，想要消灭我们。', `FemaleText_loc5`='我聽說巫妖王在北方，把冰凍荒原搞得天翻地覆。他建築了一座堡壘，寒冰皇冠，正計畫著我們的末日。', `FemaleText_loc7`='He oído que el Rey Exánime está preparándose en el norte en los Baldíos Helados. Ha construido una fortaleza, Corona de Hielo y planea nuestra perdición.' WHERE `ID`=30088;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노스렌드에는 거인이 산다는 소문이 있습니다. 턱수염에 단검을 매달고 죽음처럼 차가운 눈빛만으로도 불을 꺼뜨린다고 하더군요.', `MaleText_loc4`='传说诺森德生活着可怕的巨人。他们的胡须像匕首一样锋利，冰冷的目光甚至能熄灭熊熊烈火。', `MaleText_loc5`='謠傳巨人住在北裂境，他們有著用匕首串成的鬍鬚，而他們只要用死氣沉沉的冰冷眼光一瞪，多大的火都會被撲滅。', `MaleText_loc7`='Se rumorea que en Rasganorte viven hombres gigantes. Tienen barbas hechas de dagas y pueden apagar llamas con su mirada helada y muerta.', `FemaleText_loc1`='노스렌드에는 거인이 산다는 소문이 있어요. 턱수염에 단검을 매달고 죽음처럼 차가운 눈빛만으로도 불을 꺼뜨린다고 하더라고요.', `FemaleText_loc4`='传说诺森德生活着可怕的巨人。他们的胡须像匕首一样锋利，冰冷的目光甚至能熄灭熊熊烈火。', `FemaleText_loc5`='謠傳巨人住在北裂境，他們有著用匕首串成的鬍鬚，而他們只要用死氣沉沉的冰冷眼光一瞪，多大的火都會被撲滅。', `FemaleText_loc7`='Se rumorea que en Rasganorte viven hombres gigantes. Tienen barbas hechas de dagas y pueden apagar llamas con su mirada helada y muerta.' WHERE `ID`=30089;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='북쪽에서 추위가 슬그머니 다가와 뼛속까지 아리게 하는군요.', `MaleText_loc4`='来自北方的寒风呼啸而过，冰冷刺骨。', `MaleText_loc5`='從北方而來的寒冷凍得我的骨頭發痛。', `MaleText_loc7`='El frío que llega desde el norte hace que me duelan mucho los huesos.', `FemaleText_loc1`='북쪽에서 추위가 슬그머니 다가와 뼛속까지 아리게 하는군요.', `FemaleText_loc4`='来自北方的寒风呼啸而过，冰冷刺骨。', `FemaleText_loc5`='從北方而來的寒冷凍得我的骨頭發痛。', `FemaleText_loc7`='El frío que llega desde el norte hace que me piquen mucho los huesos.' WHERE `ID`=30090;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드 항구는 정말 시끌벅적하네요. 새 배는 어디서 출항하는지 궁금합니다...', `MaleText_loc4`='暴风城港口一片繁忙的景象。不知道那些新造的船只会开往哪儿去……', `MaleText_loc5`='暴風港真是被擠得水洩不通，我好奇新進港的船隻要停哪...', `MaleText_loc7`='El Puerto de Ventormenta es muy bullicioso. Me pregunto adónde irán los nuevos barcos...', `FemaleText_loc1`='스톰윈드 항구는 정말 시끌벅적하네요. 새 배는 어디서 출항하는지 궁금합니다...', `FemaleText_loc4`='暴风城港口一片繁忙的景象。不知道那些新造的船只会开往哪儿去……', `FemaleText_loc5`='暴風港真是被擠得水洩不通，我好奇新進港的船隻要停哪...', `FemaleText_loc7`='El Puerto de Ventormenta es muy bullicioso. Me pregunto adónde irán los nuevos barcos...' WHERE `ID`=30091;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타우렌 친척이 노스렌드에 있다고 들었습니다. 그들이 사냥을 잘했으면 좋겠군요... 언데드를 사냥하는 족속이었으면 좋겠네요.', `MaleText_loc4`='听说牛头人的远亲住在诺森德。希望他们都是优秀的猎手……专门猎杀亡灵。', `MaleText_loc5`='我聽說北裂境有牛頭人的親戚。我希望他們是好獵人...我希望他們狩獵不死族。', `MaleText_loc7`='He oído que los Tauren tienen primos en Rasganorte. Espero que sean buenos cazadores... y que cacen no-muertos.', `FemaleText_loc1`='타우렌 친척이 노스렌드에 있다고 들었습니다. 그들이 사냥을 잘했으면 좋겠군요... 언데드를 사냥하는 족속이었으면 좋겠네요.', `FemaleText_loc4`='听说牛头人的远亲住在诺森德。希望他们都是优秀的猎手……专门猎杀亡灵。', `FemaleText_loc5`='我聽說北裂境有牛頭人的親戚。我希望他們是好獵人...我希望他們狩獵不死族。', `FemaleText_loc7`='He oído que los Tauren tienen primos en Rasganorte. Espero que sean buenos cazadores... y que cacen no-muertos.' WHERE `ID`=30092;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='블러드 엘프가 노스렌드로 간다면, 마침내 우리도 복수할 기회를 얻는 겁니다! 리치 왕이 우리가 사랑하는 실버문으로 진군해왔던 사실을 후회하게 될 겁니다!', `MaleText_loc4`='要是血精灵也远征诺森德的话，那么我们一定能实现复仇大业！巫妖王肯定会为当初进攻银月城而后悔！', `MaleText_loc5`='如果血精靈前往北裂境，那我們將終於有了報仇的機會!巫妖王將會為他進攻我們摯愛的銀月城而感到後悔!', `MaleText_loc7`='¡Si los elfos de sangre van a Rasganorte, entonces al fin la venganza será nuestra! ¡El Rey Exánime se arrepentirá de haber marchado sobre nuestra amada Ciudad de Lunargenta!', `FemaleText_loc1`='블러드 엘프가 노스렌드로 간다면, 마침내 우리도 복수할 기회를 얻는 겁니다! 리치 왕이 우리가 사랑하는 실버문으로 진군해왔던 사실을 후회하게 될 겁니다!', `FemaleText_loc4`='要是血精灵也远征诺森德的话，那么我们一定能实现复仇大业！巫妖王肯定会为当初进攻银月城而后悔！', `FemaleText_loc5`='如果血精靈前往北裂境，那我們將終於有了報仇的機會!巫妖王將會為他進攻我們摯愛的銀月城而感到後悔!', `FemaleText_loc7`='¡Si los elfos de sangre van a Rasganorte, entonces al fin la venganza será nuestra! ¡El Rey Exánime se arrepentirá de haber marchado sobre nuestra amada Ciudad de Lunargenta!' WHERE `ID`=30093;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='붉은돌격대 놈들 때문에 몇 년 동안이나 겪어야 했던 고충을 모두 생각해 보십시오. 고문, 광기, 심지어 살인까지.$B$B그런 일을 계속 두고 볼 수는 없습니다. 당신은 어떻게 생각하십니까?', `FemaleText_loc4`='多年来，血色十字军酿造的惨剧简直不尽其数。他们沦为了痛苦、狂热与谋杀的代名词。$B$B我不能再让这样的悲剧继续重演。你觉得呢？', `FemaleText_loc5`='想想這些年以來，血色大軍所造成的折磨。折磨、狂熱、謀殺。$B$B我不允許這些惡行繼續。你呢?', `FemaleText_loc7`='Piensa en todo el sufrimiento que han causado los Escarlatas a lo largo de los años. Las torturas, los asesinatos, el fanatismo.$B$BNo permitiré que eso continúe. ¿Y tú?' WHERE `ID`=30094;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희가 빛을 섬기는 거라면, 북쪽으로 가서 거기 도사린 어둠과 맞서야 합니다.', `MaleText_loc4`='如果我们信仰圣光，就应该挥师北上，直面诺森德的黑暗势力。', `MaleText_loc5`='如果我們服侍聖光，我們就必須前往北方，面對潛伏在那的黑暗。', `MaleText_loc7`='Si de verdad servimos a la Luz, debemos partir hacia el norte y enfrentarnos a la oscuridad que allí mora.', `FemaleText_loc1`='저희가 빛을 섬기는 거라면, 북쪽으로 가서 거기 도사린 어둠과 맞서야 합니다.', `FemaleText_loc4`='如果我们信仰圣光，就应该挥师北上，直面诺森德的黑暗势力。', `FemaleText_loc5`='如果我們服侍聖光，我們就必須前往北方，面對潛伏在那的黑暗。', `FemaleText_loc7`='Si de verdad servimos a la Luz, debemos partir hacia el norte y enfrentarnos a la oscuridad que allí mora.' WHERE `ID`=30095;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노스렌드 대륙 곳곳에는 역사적인 유물이 가득합니다! 얼어붙은 얼음을 다 파헤쳐서 우리 조상께서 남기신 흔적을 찾아봐야 합니다.', `MaleText_loc4`='诺森德大陆遍布历史遗迹！我们要凿开坚硬的冰层，寻找祖先的足迹。', `MaleText_loc5`='北裂境大陸是個充滿歷史的地方!我們必須挖掘深入凍結的冰層，找出我們的先祖。', `MaleText_loc7`='¡El continente de Rasganorte está repleto de historia! Debemos excavar más profundamente en el hielo helado y encontrar a nuestros antepasados.', `FemaleText_loc1`='노스렌드 대륙 곳곳에는 역사적인 유물이 가득해요! 얼어붙은 얼음을 다 파헤쳐서 우리 조상님들께서 남기신 흔적을 찾아봐야 해요.', `FemaleText_loc4`='诺森德大陆遍布历史遗迹！我们要凿开坚硬的冰层，寻找祖先的足迹。', `FemaleText_loc5`='北裂境大陸是個充滿歷史的地方!我們必須挖掘深入凍結的冰層，找出我們的先祖。', `FemaleText_loc7`='¡El continente de Rasgnorte está repleto de historia! Debemos excavar más profundamente en el hielo helado y encontrar a nuestros antepasados.' WHERE `ID`=30096;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='극 지방에 있는 독특한 자기장은 연구할 거리가 무궁무진하답니다!', `MaleText_loc4`='极地独特的磁场区拥有难以估量的研究价值！', `MaleText_loc5`='這位在北極一帶獨特而迷人的原野蘊藏著數以百萬計的可能性等著我們去探索!', `MaleText_loc7`='¡Los campos magnéticos únicos de las regiones polares presentan millones de posibilidades de investigación!', `FemaleText_loc1`='극 지방에 있는 독특한 자기장은 연구할 거리가 무궁무진해요!', `FemaleText_loc4`='极地独特的磁场区拥有难以估量的研究价值！', `FemaleText_loc5`='這位在北極一帶獨特而迷人的原野蘊藏著數以百萬計的可能性等著我們去探索!', `FemaleText_loc7`='¡Los campos magnéticos únicos de las regiones polares presentan millones de posibilidades de investigación!' WHERE `ID`=30097;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드의 국왕 폐하를 찾았다고 합니다! 스톰윈드로 돌아오고 계신다는군요!', `MaleText_loc4`='听说他们找到了国王！他就要返回暴风城了！', `MaleText_loc5`='我聽說國王被找到了!他正要返回暴風城!', `MaleText_loc7`='¡He oído que han encontrado al rey! ¡Vuelve a Ventormenta!', `FemaleText_loc1`='스톰윈드의 국왕 폐하를 찾았다고 해요! 스톰윈드로 돌아오고 계신대요!', `FemaleText_loc4`='听说他们找到了国王！他就要返回暴风城了！', `FemaleText_loc5`='我聽說國王被找到了!他正要返回暴風城!', `FemaleText_loc7`='¡He oído que han encontrado al rey! ¡Vuelve a Ventormenta!' WHERE `ID`=30098;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='북쪽에서 돈 냄새가 나... 물건들 챙기고 옷 단단히 입어야겠군!', `MaleText_loc4`='北方大陆商机暗藏啊……赶紧打点货物，穿上厚厚的外套，我们出发吧！', `MaleText_loc5`='我可以聞到北邊賺錢的味道...是該打包貨物穿上厚重外套了!', `MaleText_loc7`='Puedo oler un mercado al norte... ¡hora de empaquetar las cosas y ponerse un abrigo grueso!', `FemaleText_loc1`='북쪽에서 돈벌이 냄새가 나네요... 물건들 챙기고 옷 단단히 입으셔야겠어요.', `FemaleText_loc4`='北方大陆商机暗藏啊……赶紧打点货物，穿上厚厚的外套，我们出发吧！', `FemaleText_loc5`='我可以聞到北邊賺錢的味道...是該打包貨物穿上厚重外套了!', `FemaleText_loc7`='Puedo oler un mercado al norte... ¡hora de empaquetar las cosas y ponerse un abrigo grueso!' WHERE `ID`=30099;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='북쪽에서 돈 냄새가 나... 물건들 챙기고 옷 단단히 입어야겠군!', `MaleText_loc4`='北方大陆商机暗藏啊……赶紧打点货物，穿上厚厚的外套，我们出发吧！', `MaleText_loc5`='我可以聞到北邊賺錢的味道...是該打包貨物穿上我的厚重外套了!', `MaleText_loc7`='Huelo un mercado en el norte... ¡hora de empaquetar las cosas y ponerme mi abrigo grueso!', `FemaleText_loc1`='북쪽에서 돈 냄새가 나요... 물건들 챙기고 옷 단단히 입어야겠어요!', `FemaleText_loc4`='北方大陆商机暗藏啊……赶紧打点货物，穿上厚厚的外套，我们出发吧！', `FemaleText_loc5`='我可以聞到北邊賺錢的味道...是該打包貨物穿上我的厚重外套了!', `FemaleText_loc7`='Huelo un mercado en el norte... ¡hora de empaquetar las cosas y ponerme mi abrigo grueso!' WHERE `ID`=30100;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하! 늙은 줌자가 그리워지는군. 꽤 질긴 놈이었지. 하지만, 무쇠가죽은 그놈을 편하게 씹어줄 수 있었어.', `MaleText_loc4`='哈！我有点想念老祝玛伽了。他很强壮，但是铁皮轻而易举就将他干掉了。', `MaleText_loc5`='哈!我差點懷念起老強賈了。他很猛，但鐵皮一臉輕鬆地把他給生吞了。', `MaleText_loc7`='¡Ja! Casi añoro al viejo Jum''ja. Era duro. Pero parece que Pielférrea lo masticó bastante bien.' WHERE `ID`=30101;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소문은 바람결에 떠도는 나뭇잎처럼 돌고 도는 법이지요. 명가의 일원들이 북쪽에 산다는 말이 있더군요.', `MaleText_loc4`='小道消息传得跟风中的落叶一样快。他们说北方大陆生活着高等精灵！', `MaleText_loc5`='謠言就像風中之葉漫天飛舞。有人說精靈貴族居住在北方!', `MaleText_loc7`='Los rumores vuelan como hojas al viento. ¡Dicen que los Altonato viven al norte!', `FemaleText_loc1`='소문은 바람결에 떠도는 나뭇잎처럼 돌고 도는 법이지요. 명가의 일원들이 북쪽에 산다는 말이 있더군요.', `FemaleText_loc4`='小道消息传得跟风中的落叶一样快。他们说北方大陆生活着高等精灵！', `FemaleText_loc5`='謠言就像風中之葉漫天飛舞。有人說精靈貴族居住在北方!', `FemaleText_loc7`='Los rumores vuelan como hojas al viento. ¡Dicen que los Altonato viven al norte!' WHERE `ID`=30102;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 하나가 비어 있지. 트롤 하나는 구덩이에 빠졌고 말이야. 그게 무슨 뜻인지 더 자세한 설명이 필요한 트롤 있나?', `MaleText_loc4`='瞧，笼子空了。一只可怜的巨魔倒在斗兽场的血泊中。你们还是坚持不肯屈服是吧？', `MaleText_loc5`='一個空蕩蕩的牢籠。一個消失在洞穴裡的食人妖。你們這些食人妖還需要什麼證據讓你們心服口服?', `MaleText_loc7`='Una celda vacía. Un trol se ha ido por el agujero. ¿Alguno de los otros trols necesita que lo convenzan algo más?' WHERE `ID`=30103;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너는 어떤가? 무쇠가죽이 씹고 놀 개 껌이 되겠나? 아니면 대화를 하겠나? 시간을 좀 줄 테니 생각해봐라.', `MaleText_loc4`='轮到你了。你愿意被铁皮一口吞掉呢？还是打算开口说点什么？我让你考虑一会儿吧。', `MaleText_loc5`='你呢?你要當鐵皮下一個滿足嚼食慾望的玩具，或是準備好跟我聊聊?我會讓你考慮一會兒的。', `MaleText_loc7`='¿Qué pasa contigo? ¿Estás listo para ser el siguiente juguete de morder de Pielférrea o vas a hablar? Voy a dejar que te lo pienses un rato.' WHERE `ID`=30104;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빈 우리에 있던 친구가 그리운가 보군. 금방 만날 수 있을지도 몰라.', `MaleText_loc4`='你很思念你的邻居吧。让我看看能不能快点让你去陪他。', `MaleText_loc5`='我打賭你很想念你的鄰居，我也許能讓你立刻加入他也說不定。', `MaleText_loc7`='Apuesto a que añoras a tu vecino. Veré si puedes unirte pronto a él.' WHERE `ID`=30105;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간은 째깍째깍 흘러가지, 트롤. 드락타론 얘기가 하고 싶어지면 언제든지 말하라고.', `MaleText_loc4`='你没有多少时间啦。如果你愿意谈谈达克萨隆的情况，尽管开口吧。', `MaleText_loc5`='時間不夠了，食人妖。當你準備好想要聊聊德拉克薩隆，告訴我。', `MaleText_loc7`='El tiempo se agota, trol. Cuando quieras hablar sobre Drak''Tharon, házmelo saber.' WHERE `ID`=30106;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드라카리 전사라 이말이지? 무쇠가죽하고 싸울 때 얼마나 전사다운지 보겠네.', `MaleText_loc4`='达卡莱战士，嗯？让我们瞧瞧你在面对铁皮时，能展现出怎样的英勇气概。', `MaleText_loc5`='德拉克瑞戰士，哼?那就讓我們來看看當你與鐵皮戰鬥的時候，究竟有多少能耐。', `MaleText_loc7`='Guerrero Drakkari, ¿eh? Veremos lo buen guerrero que eres cuando luches contra Pielférrea.' WHERE `ID`=30107;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋은 생각이 났어, 트롤. 나에게 드락타론 얘기를 해주면 어떨까? 그러면 내가 늙은 무쇠가죽한테 먹을거리를 좀 주지.', `MaleText_loc4`='我有个主意。不如你告诉我达克萨隆的情况，然后我就给老铁皮送些点心？', `MaleText_loc5`='我有個好主意，食人妖，你告訴我關於德拉克薩隆的事情，我讓老鐵皮嚐點甜頭，怎樣啊?', `MaleText_loc7`='Trol, tengo una idea. ¿Qué tal si me hablas de Drak''Tharon y yo luego dejo que el viejo Pielférrea coma algo?' WHERE `ID`=30108;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러니까 트롤, 내 제안은 생각 좀 해봤나? 어느 쪽으로 결정하든, 무쇠가죽은 좋아할 테니 상관은 없지만.', `MaleText_loc4`='那么，我的建议你考虑得怎么样了？不论你做什么决定，我想铁皮都会很高兴的。', `MaleText_loc5`='那麼，食人妖，你考慮過我的建議了嗎?無論你的決定如何，我相信都會讓鐵皮很高興。', `MaleText_loc7`='Bueno, trol, ¿has pensado en mi sugerencia? Decidas lo que decidas, seguro que hará feliz a Pielférrea.' WHERE `ID`=30109;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가로쉬 님께서는 이 기세를 몰아 북쪽으로 가서 싸우고 싶어하시지. 스랄 님께서 주의하라 당부하시는데도...', `MaleText_loc4`='加尔鲁什急于远征北方，但萨尔主张谨慎行事……', `MaleText_loc5`='卡爾洛斯急著前往北方作戰，然而索爾極力主張小心為上...', `MaleText_loc7`='Garrosh ansía llevar la lucha al norte, aunque Thrall recomienda precaución...', `FemaleText_loc1`='가로쉬 님께서는 이 기세를 몰아 북쪽으로 가서 싸우고 싶어하시지. 스랄 님께서 주의하라 당부하시는데도...', `FemaleText_loc4`='加尔鲁什急于远征北方，但萨尔主张谨慎行事……', `FemaleText_loc5`='卡爾洛斯急著前往北方作戰，然而索爾極力主張小心為上...', `FemaleText_loc7`='Garrosh ansía llevar la lucha al norte, aunque Thrall recomienda precaución...' WHERE `ID`=30110;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노스렌드에 사냥할 거리가 있는지 궁금하군. 장담하건대 사나운 짐승들이 있을 거요.', `MaleText_loc4`='我很想知道诺森德有什么猎物。我敢打赌，一定有凶猛的野兽。', `MaleText_loc5`='我在想北裂境能獵到什麼東西。我打賭有更兇猛的野獸。', `MaleText_loc7`='Me pregunto qué se puede cazar en Rasganorte. Supongo que bestias fieras.', `FemaleText_loc1`='노스렌드에 사냥할 거리가 있는지 궁금하군요. 장담하건대 사나운 짐승들이 있을 겁니다.', `FemaleText_loc4`='我很想知道诺森德有什么猎物。我敢打赌，一定有凶猛的野兽。', `FemaleText_loc5`='我在想北裂境能獵到什麼東西。我打賭有更兇猛的野獸。', `FemaleText_loc7`='Me pregunto qué se puede cazar en Rasganorte. Supongo que bestias fieras.' WHERE `ID`=30111;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언데드 영혼은 저주를 받고 뒤틀려 버렸지. 혹시 내가 감염된다면, 언데드로 변하기 전에 불태운다고 약속해 주게나.', `MaleText_loc4`='亡灵的灵魂饱受诅咒和痛苦的折磨。如果我被感染了，你一定要在我彻底堕落前结束我的性命……', `MaleText_loc5`='不死族的靈魂受盡詛咒與折磨。如果我被感染的話，你一定要保證在我開始轉變以前燒死我...', `MaleText_loc7`='Las almas de los no-muertos están malditas y torturadas. Si me infecto, prométeme que me quemarás antes de que cambie...', `FemaleText_loc1`='언데드 영혼은 저주를 받고 뒤틀려 버렸습니다. 혹시 제가 감염된다면, 언데드로 변하기 전에 불태운다고 약속해 주십시오.', `FemaleText_loc4`='亡灵的灵魂饱受诅咒和痛苦的折磨。如果我被感染了，你一定要在我彻底堕落前结束我的性命……', `FemaleText_loc5`='不死族的靈魂受盡詛咒與折磨。如果我被感染的話，你一定要保證在我開始轉變以前燒死我...', `FemaleText_loc7`='Las almas de los no-muertos están malditas y torturadas. Si me infecto, prométeme que me quemarás antes de que cambie...' WHERE `ID`=30112;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연금술사들이 밤낮으로 리치 왕의 역병을 치료할 방법을 찾으려 애쓴다오. 연금술사들이 없었다면 호드나 얼라이언스나 끝장이 났을 겁니다.', `MaleText_loc4`='药剂师们夜以继日地工作，研究治疗巫妖王诅咒的方法。没有他们，联盟和部落将丧失获胜的机会。', `MaleText_loc5`='藥劑師們日以繼夜辛苦得尋找巫妖王瘟疫的解藥。沒有他們，部落與聯盟雙方都將一敗塗地。', `MaleText_loc7`='Los boticarios trabajan día y noche en una cura para la plaga del Rey Exánime. Sin ellos, tanto la Horda como la Alianza estarían perdidas.', `FemaleText_loc1`='연금술사들이 밤낮으로 리치 왕의 역병을 치료할 방법을 찾으려 애쓰지요. 연금술사들이 없었다면 호드나 얼라이언스나 끝장이 났을 겁니다.', `FemaleText_loc4`='药剂师们夜以继日地工作，研究治疗巫妖王诅咒的方法。没有他们，联盟和部落将丧失获胜的机会。', `FemaleText_loc5`='藥劑師們日以繼夜辛苦得尋找巫妖王瘟疫的解藥。沒有他們，部落與聯盟雙方都將一敗塗地。', `FemaleText_loc7`='Los boticarios trabajan día y noche en una cura para la plaga del Rey Exánime. Sin ellos, tanto la Horda como la Alianza estarían perdidas.' WHERE `ID`=30113;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼음왕관으로 돌아가든지 그 붉은돌격대 그리핀을 포기하라!', `MaleText_loc4`='返回冰冠冰川，不然先锋军狮鹫会将你抛下去的！', `MaleText_loc5`='返回寒冰皇冠，否則會失去突襲軍獅鷲獸!', `MaleText_loc7`='¡Vuelve a Corona de Hielo o perderás el Grifo del Embate!' WHERE `ID`=30114;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='붉은돌격대 항구로 돌아가지 않으면 해골 그리핀을 빼앗길 것이다!', `MaleText_loc4`='返回先锋军港口，不然白骨狮鹫会将你抛下去的！', `MaleText_loc5`='返回突襲軍港口，否則會失去你的骸骨獅鷲獸!', `MaleText_loc7`='¡Vuelve al Puerto del Embate o perderás tu Grifo osario!' WHERE `ID`=30115;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 있군, 자네. 자네만 타는 해골 그리핀 말일세. 붉은돌격대 놈들한테서 어떻게 빼올지 얘기해보자고.', `MaleText_loc4`='给，朋友。这是你的白骨狮鹫。不如骑上它和先锋军作战！', `MaleText_loc5`='拿去吧，老兄，你個人專屬的骸骨獅鷲獸。讓我們來聊聊你駕駛牠和突襲軍戰鬥的事情吧!', `MaleText_loc7`='Ahí lo tienes, tron. Tu propio grifo osario. ¡Ahora hablemos sobre ti usándolo para luchar contra el Embate!' WHERE `ID`=30116;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 대단한 이야기였습니다, 사령관님.', `MaleText_loc4`='高级指挥官，这真是个精彩的故事。', `MaleText_loc5`='真是個精采故事，指揮統領。', `MaleText_loc7`='Esa sí que es una historia, Lord comandante.', `FemaleText_loc1`='정말 대단한 이야기였어요, 사령관님.', `FemaleText_loc4`='高级指挥官，这真是个精彩的故事。', `FemaleText_loc5`='真是個精采故事，指揮統領。', `FemaleText_loc7`='Esa sí que es una historia, Lord comandante.' WHERE `ID`=30117;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희는 토목 공사를 하러 온 것뿐입니다.', `MaleText_loc4`='我们是来找活儿干的，长官。', `MaleText_loc5`='我們是來找工作的，長官。', `MaleText_loc7`='Estamos aquí para hacer trabajo civil, señor.' WHERE `ID`=30118;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='글쎄요... 저희는 그냥 하청받은 일꾼일 뿐입니다, 나으리.', `MaleText_loc4`='呃……我们受理殡仪事务，长官。', `MaleText_loc5`='嗯...長官，我們是殯葬業者。', `MaleText_loc7`='Bueno... somos enterradores, señor.' WHERE `ID`=30119;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알았습니다!', `MaleText_loc4`='遵命，长官！', `MaleText_loc5`='是的，長官!', `MaleText_loc7`='¡Sí, señor!', `FemaleText_loc1`='알았습니다!', `FemaleText_loc4`='遵命，长官！', `FemaleText_loc5`='是的，長官!', `FemaleText_loc7`='¡Sí, señor!' WHERE `ID`=30120;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 무식한 맥고이버에게 채찍을 휘두릅니다.', `FemaleText_loc4`='%s朝米克高维尔扑闪着大眼睛。', `FemaleText_loc5`='%s對著不理不睬的馬概先拋媚眼。', `FemaleText_loc7`='%s pestañea al desprevenido McGoyver.' WHERE `ID`=30121;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 무언가 바라는 듯이 맥고이버를 보며 한숨짓습니다... 아니면 비행기를 보고 짓는 것일까요?', `FemaleText_loc4`='%s哀怨地对米克高维尔叹了口气……又或者是对飞行器叹气？', `FemaleText_loc5`='%s渴求得對馬概先嘆氣...還是對著飛行器呢?', `FemaleText_loc7`='%s suspira tristemente a McGoyver... ¿o es la máquina voladora?' WHERE `ID`=30122;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 갈망하는 눈빛으로 비행기를 뚫어지게 바라봅니다... 아니면 맥고이버를 바라보는 것일까요?', `FemaleText_loc4`='%s满怀希望地盯着飞行器……又或者她是在看米克高维尔？', `FemaleText_loc5`='%s熱切得盯著這台飛行器...還是她盯著的其實是馬概先?', `FemaleText_loc7`='%s mira anhelante a la máquina volador... ¿o está mirando a McGoyver?' WHERE `ID`=30123;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나쁜 놈들... 죽어! 그래... 죽어!', `MaleText_loc4`='可恶的……哇哇！杀！对，杀了你！', `MaleText_loc5`='討厭的小...啊，嘎!殺!對!殺了你!', `MaleText_loc7`='Asqueroso pequeño... ¡A-ak, koh! ¡Matar! ¡Sí, matarte!' WHERE `ID`=30124;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='힐드스미트는 신성하지요. 누가 이기든 간에 토림 옆에서 일생을 보내게 될 거예요.', `FemaleText_loc4`='海德比武会是神圣的。获胜者将赢得终身陪伴托里姆的殊荣。', `FemaleText_loc5`='海茲競技是神聖的。誰要是能贏得勝利就能確保能永伴在索林姆身旁。', `FemaleText_loc7`='El encuentro Hyldnir es sagrado. Quien obtiene una victoria se asegura toda una vida junto a Thorim.' WHERE `ID`=30125;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='덤벼 봐, 화끈하게!', `MaleText_loc4`='来吧，宝贝儿！', `MaleText_loc5`='放馬過來吧，寶貝!', `MaleText_loc7`='¡Desenfunda, calentón!', `FemaleText_loc1`='덤벼 보세요, 시원하게!', `FemaleText_loc4`='来吧，宝贝儿！', `FemaleText_loc5`='放馬過來吧，寶貝!', `FemaleText_loc7`='¡Desenfunda, calentón!' WHERE `ID`=30126;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 해봅시다...', `MaleText_loc4`='动手吧……', `MaleText_loc5`='解決它吧...', `MaleText_loc7`='Hagamos esto...', `FemaleText_loc1`='이렇게 해봐요...', `FemaleText_loc4`='动手吧……', `FemaleText_loc5`='解決它吧...', `FemaleText_loc7`='Hagamos esto...' WHERE `ID`=30127;
