UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무언가 날려보내면 속이 다 시원해집니다!', `MaleText_loc4`='我喜欢把东西炸上天！', `MaleText_loc5`='我就愛把東西炸翻天!', `MaleText_loc7`='¡Me encanta hacer volar cosas!', `FemaleText_loc1`='날려보내는 일은 너무너무 좋아요!', `FemaleText_loc4`='我喜欢把东西炸上天！', `FemaleText_loc5`='我就愛把東西炸翻天!', `FemaleText_loc7`='¡Me encanta hacer volar cosas!' WHERE `ID`=30130;
