UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고블린 잘못 보셨군요.', `MaleText_loc4`='你不该招惹地精的。', `MaleText_loc5`='你惹錯哥布林了。', `MaleText_loc7`='Te has metido con el goblin equivocado.', `FemaleText_loc1`='고블린 잘못 보셨네요.', `FemaleText_loc4`='你不该招惹地精的。', `FemaleText_loc5`='你惹錯哥布林了。', `FemaleText_loc7`='Te has metido con la goblin equivocada.' WHERE `ID`=30132;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거나 먹어라, 나쁜 놈아!', `MaleText_loc4`='尝尝炸弹的厉害吧！', `MaleText_loc5`='吃我一發吧，壞蛋!', `MaleText_loc7`='¡Chúpate esta, villano!', `FemaleText_loc1`='이거나 드세요, 나쁜 놈아!', `FemaleText_loc4`='尝尝炸弹的厉害吧！', `FemaleText_loc5`='吃我一發吧，壞蛋!', `FemaleText_loc7`='¡Chúpate esta, villano!' WHERE `ID`=30133;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드워프... 참 신기한 생물이다...', `MaleText_loc4`='矮人……奇怪的生物……', `MaleText_loc5`='矮人...奇怪的生物...', `MaleText_loc7`='Enano... extraña criatura...' WHERE `ID`=30134;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아프냐?? 난 안 아프다!', `MaleText_loc4`='它们会觉得痛吗？？', `MaleText_loc5`='它會覺得痛嗎??', `MaleText_loc7`='¿¿Sufre dolor??' WHERE `ID`=30135;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곧 우리와 똑같이 될 거야...', `MaleText_loc4`='你很快就会和我们一样了……', `MaleText_loc5`='你馬上就會跟我們一樣...', `MaleText_loc7`='Pronto serás como nosotros...' WHERE `ID`=30136;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='긴장해라, 드워프놈아아아아!', `MaleText_loc4`='颤抖吧，矮人！！', `MaleText_loc5`='害怕吧，矮人!!', `MaleText_loc7`='¡¡TEMBLAD, ENANOSSSSS!' WHERE `ID`=30137;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바르굴이 먹어버릴지도 몰라!', `MaleText_loc4`='瓦古会吃掉你！', `MaleText_loc5`='瓦苟也許會吃了你!', `MaleText_loc7`='¡Puede que vargul os devore!' WHERE `ID`=30138;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 해방인가? 나 풀려났다!', `MaleText_loc4`='我自由了？我自由了！', `MaleText_loc5`='我自由了?我自由了!', `MaleText_loc7`='¿Soy libre? ¡Soy libre!' WHERE `ID`=30139;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='믿을 수가 없군! 이제 집에 갈 수 있다니!', `MaleText_loc4`='真不敢相信！我可以走了！', `MaleText_loc5`='我不敢相信!我可以走了!', `MaleText_loc7`='¡No me lo puedo creer! ¡Puedo irme!' WHERE `ID`=30140;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전속력으로 달려가자고! 고마워, 친구!', `MaleText_loc4`='我该离开啦！谢谢你，朋友！', `MaleText_loc5`='得快溜了!謝啦，朋友!', `MaleText_loc7`='¡Hora de largarse! ¡Gracias, $gamigo:amiga;!' WHERE `ID`=30141;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성스러운 빛이 당신과 함께하기를.', `MaleText_loc4`='朋友，愿圣光与你同在。', `MaleText_loc5`='聖光與你同在，我的朋友。', `MaleText_loc7`='Que la Luz esté contigo, $gamigo mío:amiga mía;.' WHERE `ID`=30143;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠시만요. 지금은 집중해야 합니다. 정신을 완전히 하나로 모아야 하는 과정이랍니다. 저희만 바라보는 무고한 생명이 많으니까요.', `MaleText_loc4`='我必须集中精神，许多无辜的生命要靠我们去挽救。', `MaleText_loc5`='拜託，我必須專心。這個過程非常繁重，而許多無辜生靈的性命就靠我們了。', `MaleText_loc7`='Por favor, he de concentrarme. Este proceso es muy intenso y muchas vidas inocentes dependen de nosotros.', `FemaleText_loc1`='잠시만요. 지금은 집중해야 합니다. 정신을 완전히 하나로 모아야 하는 과정이랍니다. 저희만 바라보는 무고한 생명이 많으니까요.', `FemaleText_loc4`='我必须集中精神，许多无辜的生命要靠我们去挽救。', `FemaleText_loc5`='拜託，我必須專心。這個過程非常繁重，而許多無辜生靈的性命就靠我們了。', `FemaleText_loc7`='Por favor, he de concentrarme. Este proceso es muy intenso y muchas vidas inocentes dependen de nosotros.' WHERE `ID`=30144;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성스러운 빛에 헌신한 저 자신이 자랑스럽습니다. 우리 고향땅을 짓밟은 스컬지 녀석들이 저지르는 학살 행위는 저희가 막아야 합니다.', `MaleText_loc4`='能为圣光奉献力量是我的荣耀。天灾军团妄图摧毁我们的家园，对我们的同胞进行有计划的屠杀，我们绝不会让他们得逞。', `MaleText_loc5`='我很驕傲以這樣的形式獻身於聖光。天譴軍對我們家園的攻擊是一場大屠殺，而我們必須反擊。', `MaleText_loc7`='Me llena de orgullo que mi dedicación a la Luz se use de esta forma. El asalto de la Plaga a nuestra tierra natal es un acto de genocidio al que hay que enfrentarse.', `FemaleText_loc1`='성스러운 빛에 헌신한 저 자신이 자랑스럽답니다. 우리 고향땅을 짓밟은 스컬지 녀석들이 저지르는 학살 행위는 저희가 막아야 해요.', `FemaleText_loc4`='能为圣光奉献力量是我的荣耀。天灾军团妄图摧毁我们的家园，对我们的同胞进行有计划的屠杀，我们绝不会让他们得逞。', `FemaleText_loc5`='我很驕傲以這樣的形式獻身於聖光。天譴軍對我們家園的攻擊是一場大屠殺，而我們必須反擊。', `FemaleText_loc7`='Me llena de orgullo que mi dedicación a la Luz se use de esta forma. El asalto de la Plaga a nuestra tierra natal es un acto de genocidio al que hay que enfrentarse.' WHERE `ID`=30145;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='총사령관님께서 어디 계신지 나는 모른다. 너 스스로 찾아봐라!', `FemaleText_loc4`='我不知道元帅的下落。你去死吧！', `FemaleText_loc5`='我才不知道上將在哪。下地獄吧!', `FemaleText_loc7`='No sé dónde está el Gran almirante. ¡Vete al infierno!' WHERE `ID`=30146;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하시오, $n.', `MaleText_loc4`='欢迎你，$n。', `MaleText_loc5`='你好，$n。', `MaleText_loc7`='Saludos, $n.' WHERE `ID`=30147;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나한테서 뭐라도 건질 수 있을까 보냐!', `FemaleText_loc4`='你休想从我口中问出什么！', `FemaleText_loc5`='你不用想從我身上得到任何東西!', `FemaleText_loc7`='¡No me sacarás nada!' WHERE `ID`=30148;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네놈으로 내일 아침 식사를 해야겠다!', `FemaleText_loc4`='我要用你的内脏当早餐！', `FemaleText_loc5`='我要把你的胃袋當早餐!', `FemaleText_loc7`='¡Desayunaré tus mollejas!' WHERE `ID`=30149;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='릴라크, 꼬마날개를 잃어버렸습니다! 도와주십시오. 부탁 드립니다!', `MaleText_loc4`='瑞拉克，我把迷你鹦鹉弄丢了！求你帮帮我！', `MaleText_loc5`='里拉克，我的迷你鸚鵡不見了!拜託，幫幫我!', `MaleText_loc7`='¡Rilak, he perdido a Cotorrilla! ¡AYÚDAME, POR FAVOR!', `FemaleText_loc1`='릴라크, 꼬마날개를 잃어버렸어요! 도와주세요. 부탁 드려요!', `FemaleText_loc4`='瑞拉克，我把迷你鹦鹉弄丢了！求你帮帮我！', `FemaleText_loc5`='里拉克，我的迷你鸚鵡不見了!拜託，幫幫我!', `FemaleText_loc7`='¡Rilak, he perdido a Cotorrilla! ¡AYÚDAME, POR FAVOR!' WHERE `ID`=30150;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지금 건 그나마 봐줄 만하구나!', `FemaleText_loc4`='我要让你输得心服口服！', `FemaleText_loc5`='你可以再試試看!', `FemaleText_loc7`='¡Habría sido mejor que lo hubieras intentado!' WHERE `ID`=30151;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네 손에 죽을 수도 있겠지. 하지만, 내가 입을 열까 보냐!', `FemaleText_loc4`='你可以杀了我，但是我绝对不会告诉你！', `FemaleText_loc5`='你也許能殺了我，但我永遠也不會供出你要的消息!', `FemaleText_loc7`='¡Puedes matarme, pero jamás te diré lo que quieres!' WHERE `ID`=30152;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나는 붉은돌격대다. 우리는 쥐새끼처럼 지도자를 배신하지는 않는다!', `FemaleText_loc4`='我是血色先锋军的一员！绝不会出卖自己的领袖！', `FemaleText_loc5`='我是血色突襲軍的一員，我們不會洩漏領導者的位置的!', `FemaleText_loc7`='Soy de El Embate Escarlata. ¡No vendemos a nuestros líderes!' WHERE `ID`=30153;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그냥 칠흑의 기사단에서 보낸 조무래기에 불과한 녀석이군. 죽어라!', `FemaleText_loc4`='你不过是黑锋骑士团的走狗。去死吧！', `FemaleText_loc5`='你不過就是個黯刃的走狗，死吧!', `FemaleText_loc7`='No eres más que un sucio peón de la Espada de Ébano. ¡Muere!' WHERE `ID`=30154;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='모른다. 총사령관님께서 어디 계신지 모른단 말이다. 설사 안다 하더라도, 너한테 알려줄까 보냐. 목숨을 바치는 한이 있더라도 말이다!', `FemaleText_loc4`='我不知道他的下落。就算我知道，也不会告诉你——哪怕你杀了我！', `FemaleText_loc5`='不，我不知道他在哪，就算我知道，我也不會告訴你 -- 即使我要因此送命!', `FemaleText_loc7`='No, no sé dónde está y si lo supiera, no te lo diría, ¡aunque mi vida dependiera de ello!' WHERE `ID`=30155;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지친 여행자여, 어서 오게. 먼 길을 걸어왔군. 여기 원크와 야영지에서 편히 쉬었으면 하네.', `MaleText_loc4`='欢迎你，疲惫的旅行者。历经长途跋涉后，希望你能在欧尼瓦营地好好休息。', `MaleText_loc5`='歡迎你，疲憊的旅人，遠道而來，我們都希望你能在歐尼克瓦營地中得到充足的休息。', `MaleText_loc7`='Saludos, caminante. Has recorrido un largo camino. Esperamos que puedas descansar aquí, en el Campamento Oneqwah.' WHERE `ID`=30156;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네 몸뚱이를 돛대에 장식으로 달아 주마!', `FemaleText_loc4`='我要用你的尸体装饰桅杆！', `FemaleText_loc5`='我會把你的屍體當作旗幟當成裝飾品!', `FemaleText_loc7`='¡Tu cadáver adornará mi mastil!' WHERE `ID`=30157;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원크와 야영지에 잘 왔네. 잠시 휴식을 취하게. 우리가 자네 코도를 돌볼 테니.', `MaleText_loc4`='欢迎来到欧尼瓦营地。休息一会儿，科多兽交给我们来照料吧。', `MaleText_loc5`='歡迎來到歐尼克瓦營地。休息片刻，我們會好好照料您的科多獸。', `MaleText_loc7`='Te doy la bienvenida al Campamento Oneqwah. Descansa un momento mientras nos ocupamos de tu kodo.' WHERE `ID`=30158;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='포세이큰이 호드와 얼라이언스 양쪽에서 역병을 치유하려고 애쓰는 동안 저희는 도시를 둘러싼 채 공격하는 스컬지 죽음의 요새를 처리하기로 맹세했습니다.$B$B응축된 성스러운 빛의 기운으로, 리치 왕의 건물에 반격을 가할 수 있습니다. 운이 좋다면, 파괴할 수도 있겠지요.', `FemaleText_loc4`='被遗忘者在努力地研制治愈瘟疫的方法，希望以此拯救倍受侵害的联盟和部落成员；而我们则起誓消灭那些包围着各大主城的天灾军团浮空城。$B$B利用圣光的力量，我们能对巫妖王的造物造成重创，运气好的话，还能直接摧毁它们。', `FemaleText_loc5`='當被遺忘者忙著治療聯盟跟部落所受到的瘟疫感染時，我們發誓要擊落攻打我們城市的亡域。$B$B在使用集中的聖光能量下，我們可以反擊巫妖王的那些建築，幸運一點，也許還能擊落他們。', `FemaleText_loc7`='Mientras los Renegados se encargan de curar la plaga para ambos bandos, Horda y Alianza, nosotros hemos decidido ocuparnos de la necrópolis de la Plaga que asedia a nuestras ciudades.$B$BUsando energía de la Luz concentrada, podemos golpear las estructuras del Rey Exánime y con suerte, destruirlas.' WHERE `ID`=30159;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='만나서 반갑네, 여행자여. 멀리 겨울발굽 야영지에서부터 이 누추한 야영지까지 여행하는 동안 너무 힘들지 않았기를 바라네.', `MaleText_loc4`='你好啊，旅行者。但愿从冬蹄营地到这座破落岗哨的路不是太难走。', `MaleText_loc5`='很高興見到你，旅人。但願冬蹄營地到我們這個簡陋的崗哨，這段旅程不是太辛苦。', `MaleText_loc7`='Te doy la bienvenida. Espero que el viaje desde el Campamento Pezuña Invernal hasta nuestra humilde avanzada no haya sido demasiado agotador.' WHERE `ID`=30160;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='랜드그렌 대주교님이라면 아실 것이다! 아아아아아아아아아악...!', `MaleText_loc4`='我要告诉大主教兰德雷！啊……', `MaleText_loc5`='大主教蘭格瑞一定知道!呃啊～～～～～～!', `MaleText_loc7`='¡El Arzobispo Landgren debe saberlo! ¡Aaaaaaaggghhh!' WHERE `ID`=30161;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오게, 여행자여. 겨울발굽 야영지에서 안전하게 여기까지 온 자네를 보니 기쁘네.', `MaleText_loc4`='欢迎你，旅行者。你从冬蹄营地来的吧，很高兴你能平安抵达这里。', `MaleText_loc5`='你好，旅人。很高興見到你安全得從冬蹄營地跋涉至此。', `MaleText_loc7`='Saludos, viajero. Es bueno ver que has llegado hasta aquí sano y salvo desde el Campamento Pezuña Invernal.' WHERE `ID`=30162;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경비병, 도움이 필요하다!', `MaleText_loc4`='卫兵！快来帮帮我！', `MaleText_loc5`='守衛，來人吶!', `MaleText_loc7`='¡Guardias, ayuda!' WHERE `ID`=30163;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니... 잠깐... 멈춰봐라! 총사령관님께서 어디 계신지 나는 모르지만, 너와 내가 함께 알아낼 수 있으리라 확신한다.', `MaleText_loc4`='等等……住手！我不知道元帅的下落，但是我或许能帮忙找到他。', `MaleText_loc5`='拜託...等等...住手!我不知道上將在哪裡，但是我知道我們可以一起把他找出來。', `MaleText_loc7`='¡Por favor... espera... alto! No sé dónde está el Gran almirante, pero seguro que podemos solucionarlo.' WHERE `ID`=30164;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나한테 돈과 보석이 좀 있다는 얘기를 했었나? 목숨만 살려다오!', `MaleText_loc4`='我给你钱，还有珠宝！别杀我！', `MaleText_loc5`='我有跟你提過我有很多錢和珠寶嗎?別殺我!', `MaleText_loc7`='¿He mencionado que tengo dinero y joyas? ¡No me mates!' WHERE `ID`=30165;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='총사령관님께서 어디 계신지 정말 모른다. 상륙한 뒤로는 한 번도 뵙지 못했다!', `MaleText_loc4`='我真的不知道他在哪儿。抵达这里之后，我就再也没有见过他了！', `MaleText_loc5`='我不曉得他在哪裡。自從我們上岸以後就沒再看過他了!', `MaleText_loc7`='No tengo ni idea de dónde está. ¡No le he visto desde que ha aterrizado!' WHERE `ID`=30166;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무도 없나? 지금 공격을 받고 있다!', `MaleText_loc4`='来人啊！我被袭击了！', `MaleText_loc5`='有人聽得到我說話嗎?我被攻擊了!', `MaleText_loc7`='¿Alguien puede oírme? ¡Me están atacando!' WHERE `ID`=30167;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐! 말만 잘하면 네 편으로 넘어갈 수도 있단 말이다!', `MaleText_loc4`='住手！我愿意加入你们！', `MaleText_loc5`='住手!我可以被說服加入你喔!', `MaleText_loc7`='¡Alto! ¡Se me podría convencer para unirme a ti!' WHERE `ID`=30168;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼굴만은 제발! 때린 데 또 때리지는 마라!', `MaleText_loc4`='别打脸！别打脸啊！', `MaleText_loc5`='別打臉!別打臉!', `MaleText_loc7`='¡En la cara no! ¡En la cara no!' WHERE `ID`=30169;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 내게 덤비다니! 내가 누군지 알기나 하나?', `MaleText_loc4`='你竟敢招惹我！你知道我是谁吗？', `MaleText_loc5`='大膽!你知道我是誰嗎?', `MaleText_loc7`='¡Cómo te atreves! ¿Tienes alguna idea de quién soy?' WHERE `ID`=30170;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까 $c. 소환수를 잃어버리셨습니까?', `MaleText_loc4`='你好，$C。你弄丢了宠物吗？', `MaleText_loc5`='你好，$C。你的寵物走丟了嗎?', `MaleText_loc7`='Saludos, $c. ¿Has perdido alguna de tus mascotas?' WHERE `ID`=30171;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왕이시여, 천 번에 천 번씩이라도 제 목숨을 당신에게 바치겠습니다.', `MaleText_loc4`='主人，我会为你献上成千上万的生命。', `MaleText_loc5`='吾王，我會為您獻祭成千上萬條生命的。', `MaleText_loc7`='Por ti, mi señor, sacrificaría mil veces mil vidas.', `FemaleText_loc1`='왕이시여, 천 번에 천 번씩이라도 제 목숨을 당신에게 바치겠어요.', `FemaleText_loc4`='主人，我会为你献上成千上万的生命。', `FemaleText_loc5`='吾王，我會為您獻祭成千上萬條生命的。', `FemaleText_loc7`='Por ti, mi señor, sacrificaría mil veces mil vidas.' WHERE `ID`=30172;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명령만 내리십시오, 왕이시여!', `MaleText_loc4`='陛下，我会服从你的一切指令！', `MaleText_loc5`='吾王，聽候您的差遣!', `MaleText_loc7`='Estoy a tu entera disposición, mi rey.', `FemaleText_loc1`='명령만 내려주세요, 왕이시여!', `FemaleText_loc4`='陛下，我会服从你的一切指令！', `FemaleText_loc5`='吾王，聽候您的差遣!', `FemaleText_loc7`='Estoy a tu entera disposición, mi rey.' WHERE `ID`=30173;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왕이시여, 온 세계가 경외심으로 진동할 것입니다...', `MaleText_loc4`='陛下，整个世界将因你而颤抖……', `MaleText_loc5`='吾王，這個世界將會敬畏得撼動...', `MaleText_loc7`='Mi rey, el mundo temblará de adoración...', `FemaleText_loc1`='왕이시여, 온 세계가 경외심으로 진동할 거예요...', `FemaleText_loc4`='陛下，整个世界将因你而颤抖……', `FemaleText_loc5`='吾王，這個世界將會敬畏得撼動...', `FemaleText_loc7`='Mi rey, el mundo temblará de adoración...' WHERE `ID`=30174;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 폐하의 분부대로만 움직이는 도구일 뿐입니다. 왕이시여! 명령을 내려 주십시오!', `MaleText_loc4`='我愿意成为毁灭一切的工具！陛下，请下令吧！', `MaleText_loc5`='吾王，我是您毀滅的利器!聽候您的命令!', `MaleText_loc7`='¡Soy un instrumento de tu destrucción, mi rey! ¡Dame órdenes!', `FemaleText_loc1`='저는 폐하의 분부대로만 움직이는 도구일 뿐이에요. 왕이시여! 명령을 내려 주세요!', `FemaleText_loc4`='我愿意成为毁灭一切的工具！陛下，请下令吧！', `FemaleText_loc5`='吾王，我是您毀滅的利器!聽候您的命令!', `FemaleText_loc7`='¡Soy un instrumento de tu destrucción, mi rey! ¡Dame órdenes!' WHERE `ID`=30175;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 스컬지에 대항한다면 화를 입을 것이다!', `MaleText_loc4`='胆敢与天灾军团抗衡的家伙，必将落得悲惨的下场！', `MaleText_loc5`='給那些膽敢與天譴軍作對的人降下災痛吧!', `MaleText_loc7`='¡Que caiga la desgracia sobre los que osan oponerse a la Plaga!', `FemaleText_loc1`='감히 스컬지에 대항한다면 화를 입을 것이에요!', `FemaleText_loc4`='胆敢与天灾军团抗衡的家伙，必将落得悲惨的下场！', `FemaleText_loc5`='給那些膽敢與天譴軍作對的人降下災痛吧!', `FemaleText_loc7`='¡Que caiga la desgracia sobre los que osan oponerse a la Plaga!' WHERE `ID`=30176;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 적은 완전히 스러질 것입니다!', `MaleText_loc4`='我们的敌人只有死路一条！', `MaleText_loc5`='我們的敵人將會被毀滅!', `MaleText_loc7`='¡Nuestros enemigos serán aniquilados!', `FemaleText_loc1`='우리 적은 완전히 스러질 거예요!', `FemaleText_loc4`='我们的敌人只有死路一条！', `FemaleText_loc5`='我們的敵人將會被毀滅!', `FemaleText_loc7`='¡Nuestros enemigos serán aniquilados!' WHERE `ID`=30177;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오십시오, $c. 그대 소환수를 우리에 넣거나 동료를 잃은 슬픔에서 헤어나실 수 있도록 제가 도와드릴 수 있습니다.', `MaleText_loc4`='你好，$c。我可以帮你看管宠物，或者帮你找回走失的伙伴。', `MaleText_loc5`='您好，$c，我能幫助您將寵物帶入獸欄，或找回失去的夥伴。', `MaleText_loc7`='Saludos, $c. Puedo ayudarte a guardar a tus mascotas o recuperar a compañeros perdidos.', `FemaleText_loc1`='어서 오세요, $c. 그대 소환수를 우리에 넣거나 동료를 잃은 슬픔에서 헤어나실 수 있도록 제가 도와드릴 수 있어요.', `FemaleText_loc4`='你好，$c。我可以帮你看管宠物，或者帮你找回走失的伙伴。', `FemaleText_loc5`='您好，$c，我能幫助您將寵物帶入獸欄，或找回失去的夥伴。', `FemaleText_loc7`='Saludos, $c. Puedo ayudarte a guardar a tus mascotas o recuperar a compañeros perdidos.' WHERE `ID`=30178;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 다시 태어났습니다, 왕이시여. 오직 왕께만 충성을 다하고자 말입니다.', `MaleText_loc4`='陛下，我已重获新生，从此终身臣服于你。', `MaleText_loc5`='吾王，我重生了，只為您效勞。', `MaleText_loc7`='He renacido solo para serviros, mi rey.', `FemaleText_loc1`='저는 다시 태어났어요, 왕이시여. 오직 왕께만 충성을 다하고자 말이에요.', `FemaleText_loc4`='陛下，我已重获新生，从此终身臣服于你。', `FemaleText_loc5`='吾王，我重生了，只為您效勞。', `FemaleText_loc7`='He renacido solo para serviros, mi rey.' WHERE `ID`=30179;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무도 살아남지 못할 것입니다, 왕이시여.', `MaleText_loc4`='我不会心慈手软的。', `MaleText_loc5`='吾王，我們將殺得他們一個不留。', `MaleText_loc7`='No habrá supervivientes, mi señor.', `FemaleText_loc1`='아무도 살아남지 못할 것이에요, 왕이시여.', `FemaleText_loc4`='我不会心慈手软的。', `FemaleText_loc5`='吾王，我們將殺得他們一個不留。', `FemaleText_loc7`='No habrá supervivientes, mi señor.' WHERE `ID`=30180;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기에 제 소환수를 맡기고 싶습니다.', `MaleText_loc4`='我想寄养宠物。', `MaleText_loc5`='我想將我的寵物存放在這裡。', `MaleText_loc7`='Me gustaría dejar aquí a mi mascota.', `FemaleText_loc1`='여기에 제 소환수를 맡기고 싶어요.', `FemaleText_loc4`='我想寄养宠物。', `FemaleText_loc5`='我想將我的寵物存放在這裡。', `FemaleText_loc7`='Me gustaría dejar aquí a mi mascota.' WHERE `ID`=30181;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꼬마날개를 잃어버렸습니다.', `MaleText_loc4`='我的迷你鹦鹉不见了。', `MaleText_loc5`='我把迷你鸚鵡搞丟了。', `MaleText_loc7`='He perdido a Cotorrilla.', `FemaleText_loc1`='꼬마날개를 잃어버렸어요.', `FemaleText_loc4`='我的迷你鹦鹉不见了。', `FemaleText_loc5`='我把迷你鸚鵡搞丟了。', `FemaleText_loc7`='He perdido a Cotorrilla.' WHERE `ID`=30182;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쥬블링을 잃어버렸습니다.', `MaleText_loc4`='我的加布林不见了。', `MaleText_loc5`='我把我的小啾啾搞丟了。', `MaleText_loc7`='He perdido mi Jubling.', `FemaleText_loc1`='쥬블링을 잃어버렸어요.', `FemaleText_loc4`='我的加布林不见了。', `FemaleText_loc5`='我把我的小啾啾搞丟了。', `FemaleText_loc7`='He perdido mi Jubling.' WHERE `ID`=30183;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='처음에는 모그레인이 무기를 달라고 하더니, 이제는 내 하인들을 데려간다고? 쓰레기 같은 자식!', `MaleText_loc4`='莫格莱尼先是伸手要军队，接着又要带走我的仆从？什么玩意儿！', `MaleText_loc5`='先是莫格萊尼要求武裝，再來他們又把我的僕人都帶走了?真是雜碎!', `MaleText_loc7`='¿Primero Mograine pide armas y después se lleva a mis sirvientes? ¡Basura!' WHERE `ID`=30184;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛이 뭐 어쩌고 저째? 시시껄렁한 소리 지껄이지 마시오. 만들 방어구와 무기가 산더미오!', `MaleText_loc4`='别再跟我扯什么圣光了！我还要铸造武器和护甲呢！', `MaleText_loc5`='這是什麼關於聖光的鬼扯話?我還有武器和裝甲要做呢!', `MaleText_loc7`='¿Qué son estas sandeces sobre la Luz? ¡Tengo que hacer armas y armaduras!' WHERE `ID`=30185;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='처음에는 내 소중한 사로나이트 대부분을 그냥 줘버리더니, 더 강한 룬검을 만들어 내라고 요청하지 뭐요. 세상에!', `MaleText_loc4`='他先是将那些宝贵的萨隆邪铁随意派送出去，然后又命令我锻造更强大的符文剑。我呸！', `MaleText_loc5`='首先，他把我珍貴的薩鋼送走大半，然後，他又命令我開始製造威力更強大的符文劍。呿!', `MaleText_loc7`='Primero regala la mayor parte de mi preciosa saronita y después me exige que empiece a crear Hojas rúnicas de aún más poder. ¡Bah!' WHERE `ID`=30186;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나한테는 그런 생각 없는 하인은 없소. 하지만, 가끔 괜찮은 칼날이 만들어지기도 한다오.', `MaleText_loc4`='我没有傻头傻脑的奴仆，但是我至少能亲眼目睹利刃的诞生。', `MaleText_loc5`='我也許沒有任何笨僕人，但是我至少偶爾能看見一兩把品質好的符文劍出產。', `MaleText_loc7`='Puede que no tenga sirvientes sin mente, pero al menos puedo hacer una hoja de calidad de vez en cuando.' WHERE `ID`=30187;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노스렌드에서 원자재만 다시 공급받을 수만 있다면, 죽은 자들 심장까지 얼어붙게 하는 무기를 만들 수도 있소.', `MaleText_loc4`='如果能从诺森德搞到原料，我或许能锻造出可以冻结亡灵心脏的武器。', `MaleText_loc5`='唯有從北裂境重新補充我的貨品，我才有辦法製造凍結不死生物之心的武器。', `MaleText_loc7`='Si pudiera reabastecerme de los materiales de Rasganorte, podría crear un arma que helaría el alma de los no-muertos.' WHERE `ID`=30188;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요즘 죽음의 기사들은 존경심이라고는 눈곱만치도 없는 듯하오. 처음에는 내가 심혈을 기울여, 리치 왕의 축복으로 벼려낸 무기와 방어구 중에서 제일 좋은 것을 가져갔소. 그다음에는 어딘가로 사라지더니 고블린처럼 차려입고 돌아왔지 뭐요. 자기네 갑옷을 동전 몇 개에 전당 잡혔다는 말을 중얼대면서 말이오! 한심하기 그지없었소!', `MaleText_loc4`='这些死亡骑士真是不知羞耻啊。他们拿走了我精心锻造的武器和盔甲，那些都是接受过巫妖王赐福的好东西呀。接着他们不知道去哪儿逛了一圈，回来的时候一个个都穿得跟地精似的，嗫嚅着说他们为了几个铜板不得不卖掉了盔甲！真是可耻！', `MaleText_loc5`='這些死亡騎士一點也不懂何謂榮譽。首先，他們搶走了我最精良的武器和裝甲，那些東西可是我細心製作、受到巫妖王祝福而鍛造出來的。然後他們閒逛到誰知道是哪兒的地方，回來之後穿得跟哥布林一樣，嘀咕著什麼他們的裝甲只典當了幾枚銅幣!真可悲!', `MaleText_loc7`='Estos caballeros de la Muerte no conocen el honor. Primero se llevan mis mejores armas y armaduras, creadas con cariño y forjadas con la bendición del Rey Exánime. ¡Después se van vete a saber tú donde y vuelven vestidos como goblins, murmurando algo sobre empeñar su armadura por unas monedas de cobre! ¡Patético!' WHERE `ID`=30189;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 해야 할 일이 있소. 하지만, 나를 좀 도와주려는 사람 어디 못 봤소? 아니! 몹쓸 놈들이오, 그놈들 전부는!', `MaleText_loc4`='我忙得不可开交，可是有谁来帮过我呢？一个都没有！这帮混蛋！', `MaleText_loc5`='我這還有很多工作要做，可是你有看見任何人來幫忙嗎?沒有!廢物，他們全都是廢物!', `MaleText_loc7`='Aquí hay trabajo pendiente, ¿pero ves a alguien saltando para ayudarme? ¡No! ¡Escoria, todos ellos!' WHERE `ID`=30190;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방어구 고쳐줘요, 코르부스! 칼이 녹슬었어요, 코르부스! ... 이 한심한 놈들은 언제쯤이나 자기 앞가림을 하게 될는지?', `MaleText_loc4`='帮我修理一下盔甲，科弗斯！我的剑生锈了，科弗斯！……这些该死的家伙什么时候才能学会照顾自己？', `MaleText_loc5`='寇孚斯，修好我的裝甲!寇孚斯，我的劍生鏽了!...這些該死的凡人什麼時候才學得會照顧他們自己?', `MaleText_loc7`='¡Corvus, arregla mi armadura! ¡Corvus, mi armadura está oxidada!... ¿Cuándo aprenderán a cuidar de sí mismos estos malditos mortales?' WHERE `ID`=30191;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새끼 화살요정용을 잃어버렸습니다.', `MaleText_loc4`='我的精龙宝宝不见了。', `MaleText_loc5`='我把我的精龍寶寶搞丟了。', `MaleText_loc7`='He perdido mi Prole de duende dardo.', `FemaleText_loc1`='새끼 화살요정용을 잃어버렸어요.', `FemaleText_loc4`='我的精龙宝宝不见了。', `FemaleText_loc5`='我把我的精龍寶寶搞丟了。', `FemaleText_loc7`='He perdido mi Prole de duende dardo.' WHERE `ID`=30192;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신호탄을 한 번 더 쏘아 올려야겠네. 어쩌면 칠흑의 감시초소에서 원군을 더 보내줄 지도 모르네.', `MaleText_loc4`='我们应该再发一枚信号弹。这样或许能从黑锋哨站请求到更多的支援。', `MaleText_loc5`='我們應該再發射一枚信號煙火。也許這樣就能得到黯黑守望更多的幫助。', `MaleText_loc7`='Deberíamos disparar otra bengala de aviso. Quizás nos llegue más ayuda desde el Puesto de Vigilancia de Ébano.' WHERE `ID`=30193;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신호탄을 하나 더 쏘겠네. 칠흑의 감시초소에서 보기를 기도나 하게.', `MaleText_loc4`='我打算再发一枚信号弹。但愿黑锋哨站能看见。', `MaleText_loc5`='我要發射另外一枚煙火。祈禱黯黑守望看得見吧。', `MaleText_loc7`='Lanzaré otra bengala. Reza para que el Puesto de Vigilancia de Ébano esté atento.' WHERE `ID`=30194;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칠흑의 감시초소에서 원군을 보낼지도 모르네. 신호탄을 하나 더 쏘아 올리게.', `MaleText_loc4`='黑锋哨站或许还能再派一些援军来。再发一枚信号弹吧。', `MaleText_loc5`='也許黯黑守望可以騰出援軍給我們。發射另外一枚信號煙火吧。', `MaleText_loc7`='Quizás el Puesto de Vigilancia de Ébano pueda mandar algunos refuerzos. Dispara otra bengala de señales.' WHERE `ID`=30195;
