UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 꿈이야 생시야?! 드디어 누군가 날 구해 주러 왔군!', `MaleText_loc4`='我不是在做梦吧？！真的有人来救我了？', `MaleText_loc5`='這是真的嗎?總算有人要把我從這兒弄走了嗎?', `MaleText_loc7`='¡¿Es cierto?! ¿Al fin ha venido alguien para sacarme de este lugar?' WHERE `ID`=30198;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니... 아니야... 그게 아닐 거야. 내 말이 맞지? 피도 눈물도 없는 그 시골뜨기 녀석이 도구를 되찾아 오라고 자넬 보낸 게지. 그렇지?', `MaleText_loc4`='什么……不……不是吧？那个没心肝的蠢货让你先帮他找工具，然后再来找我？', `MaleText_loc5`='不...不...不是這樣的嗎，對吧?那個狼心狗肺的笨蛋也許在這些工具之後才送你來，是吧?', `MaleText_loc7`='No... no... no es eso, ¿lo es? Probablemente ese patán desalmado te ha enviado a por las herramientas, ¿verdad?' WHERE `ID`=30199;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래... 어쩌겠어... 가엾은 나는 그냥 포탑이나 멍하니 쳐다봐야지...', `MaleText_loc4`='呃……我会留意那些炮塔的……', `MaleText_loc5`='嗯，我猜我會注意那些砲塔的...或是別的東西。', `MaleText_loc7`='Bueno... supongo que le echaré un ojo a las torretas... o algo.' WHERE `ID`=30200;
