UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가름에서 나쁜 녀석들이 더 몰려오고 있어요. 들판에 지뢰를 설치하세요!', `FemaleText_loc4`='越来越多的攻击者从加姆涌来。迅速埋设地雷！', `FemaleText_loc5`='來自迦姆的攻擊者越來越多。在原野上布滿地雷!', `FemaleText_loc7`='De Garm llegan más atacantes. ¡Pon algunas minas en ese campo!' WHERE `ID`=30225;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마그나타우르 패거리가 여기 점점 가까워지고 있어요...', `FemaleText_loc4`='猛犸人越来越近了……', `FemaleText_loc5`='猛瑪象人的攻擊者逐漸接近...', `FemaleText_loc7`='Se acercan más magnatauros enemigos...' WHERE `ID`=30226;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 녀석들이 보이기 시작하는군요! 빨리 지뢰를 설치하세요!', `FemaleText_loc4`='已经能看见他们啦——停止埋设地雷！', `FemaleText_loc5`='他們幾乎來到目視範圍內了! 快完成原野上的佈雷行動!', `FemaleText_loc7`='¡Ya casi se les ve! ¡Termina de colocar las minas en ese campo!' WHERE `ID`=30227;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='녀석들이 다 왔어요! 이제 녀석들에게 지옥을 보여주세요!', `FemaleText_loc4`='他们来了！炸死他们！', `FemaleText_loc5`='他們來了!給他們死!', `FemaleText_loc7`='¡Están aquí! ¡Dales caña!' WHERE `ID`=30228;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리그스파크가 탈것 상점을 열었습니다!', `MaleText_loc4`='利斯巴克的载具商店开始营业啦！', `MaleText_loc5`='鑽炫的載具工坊隆重開幕!', `MaleText_loc7`='¡La tienda de vehículos de Chispacrack abre sus puertas!', `FemaleText_loc1`='리그스파크가 탈것 상점을 열었어요!', `FemaleText_loc4`='利斯巴克的载具商店开始营业啦！', `FemaleText_loc5`='鑽炫的載具工坊隆重開幕!', `FemaleText_loc7`='¡La tienda de vehículos de Chispacrack abre sus puertas!' WHERE `ID`=30229;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스파크라이트의 탈것 상점이 영업을 개시했다고, 친구!', `MaleText_loc4`='斯巴克莱特的战车商店开始营业啦！', `MaleText_loc5`='炫光的載具百貨隆重開幕!', `MaleText_loc7`='¡El emporio de vehículos de Chispaluz abre sus puertas!', `FemaleText_loc1`='스파크라이트의 탈것 상점이 영업을 개시했어요!', `FemaleText_loc4`='斯巴克莱特的战车商店开始营业啦！', `FemaleText_loc5`='炫光的載具百貨隆重開幕!', `FemaleText_loc7`='¡El emporio de vehículos de Chispaluz abre sus puertas!' WHERE `ID`=30230;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 랜드그렌. 아주 중요한 질문을 해야 하니 그 영혼을 드러내라.', `MaleText_loc4`='过来，兰德雷。我有很重要的事情要问你，你最好老实交代。', `MaleText_loc5`='來吧，蘭格瑞，交出你的靈魂，我才能問你一個非常重要的問題。', `MaleText_loc7`='¡Vamos, Landgren, escupe tu alma para que pueda hacerte una pregunta muy importante!' WHERE `ID`=30231;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나쁘진 않네요. 좀 더 연습한다고 죽지는 않아요! 자요, 제 엉덩이 흔드는 걸 보세요... 그렇죠!', `FemaleText_loc4`='还不错吧，但是多掌握点技巧总是没错的！你瞧，看我摆臀的动作……像这样！', `FemaleText_loc5`='還不賴，不過多學一些舞步對你不會有害處的!喏，看著我的臀部...就像這樣!', `FemaleText_loc7`='¡No está mal, aunque algo más de estudio no te haría daño! Mira mis caderas... ¡así!' WHERE `ID`=30232;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기계 다람쥐를 불러와도 너희보단 일을 잘 하겠다!', `MaleText_loc4`='机械松鼠都比你挖得快！', `MaleText_loc5`='一群機械松鼠挖礦挖得都能比你快!', `MaleText_loc7`='¡Un grupo de ardillas mecánicas minaría más rápido que tú!' WHERE `ID`=30233;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 빨리 캐! 너희 부품에 녹이 슬었건 어쨌건 나는 봐주지 않는다고!', `MaleText_loc4`='挖快点！我可不管你的传动装置是不是生锈了！', `MaleText_loc5`='挖礦的動作加快!我可不管你們的促動器是不是生鏽了!', `MaleText_loc7`='¡Mina más rápido! ¡Me da igual si tus accionadores están oxidados!' WHERE `ID`=30234;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 너흴 만들었는지 몰라도 정말 형편없는 솜씨군. 게으르고 멍청한 녀석들 같으니!', `MaleText_loc4`='你一定是用锡锭造出来的，懒骨头！', `MaleText_loc5`='你一定是被技工用白鐵糊成的，你這頭懶豬!', `MaleText_loc7`='¡Tu calderero te debe haber hecho de hojalata, patético montón de chatarra!' WHERE `ID`=30235;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='할당량을 채우지 못하는 녀석은 오늘이 가기 전에 용광로에 들어갈 줄 알라고!', `MaleText_loc4`='没有完成当日额定工作量的工人将被扔进熔炉！', `MaleText_loc5`='任何沒有完成分內工作的工人，今天結束以前會被熔成金屬錠!', `MaleText_loc7`='¡Cualquier trabajador que no cumpla su cuota será hecho lingotes antes de que acabe el día!' WHERE `ID`=30236;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폐품으로 만들어진 주제에, 폐품보다도 가치가 없다니! 형편없는 놈들!', `MaleText_loc4`='你连一堆破铜烂铁都比不上！', `MaleText_loc5`='就連製造你出來所剩下的殘渣，都還要比你有價值得多了!', `MaleText_loc7`='¡No vales ni la chatarra de la que estás hecho!' WHERE `ID`=30237;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 누난 렌치고, 너희 형은 시포리움이지?', `MaleText_loc4`='你的母亲是一只扳手，你的父亲则散发着爆盐炸弹的气味！', `MaleText_loc5`='你媽難道是扳手嗎，還是你老爸聞起來像是硝煙!', `MaleText_loc7`='¡Tú madre era una llave inglesa y tu padre apestaba a seforio!' WHERE `ID`=30238;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너! 넌 만능 스패너로 동판 두드리는 일도 못 할 멍청이로군. 썩 꺼져!', `MaleText_loc4`='你！我看你连冲制扳手这种简单的活儿都做不了。给我滚！', `MaleText_loc5`='你!你還不夠資格拿扳手敲銅板。滾到我的視線外!', `MaleText_loc7`='¡Tú! No vales ni para hacer llaves de tuerca arcoluz con placas de cobre. ¡Fuera de mi vista!' WHERE `ID`=30239;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='표적 허수아비도 너희보단 낫겠다! 속도를 높여!', `MaleText_loc4`='假人都比你干得快！加快速度！', `MaleText_loc5`='就連活動假人的動作都比你還要快!趕上進度!', `MaleText_loc7`='¡Hasta un muñeco-diana trabajaría más rápido que tú! ¡Ponte al día!' WHERE `ID`=30240;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='웨스트윈드가 어디 있는지 당장 털어놓지 않으면 네 영혼을 박살 내 버리겠다!', `MaleText_loc4`='告诉我韦斯温的下落，不然我就摧毁你的灵魂！', `MaleText_loc5`='告訴我韋斯溫的下落，不然我會毀掉你的靈魂!', `MaleText_loc7`='¡ME DIRAS DÓNDE ESTÁ VIENTO OESTE O DESTRUIRÉ TU ALMA!' WHERE `ID`=30241;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나에게서 아무것도 알아내지 못할 것이다, 비열한 놈. 나는 네 능력으로는 감당할 수 없는 존재이다.', `MaleText_loc4`='你休想从我嘴里问出元帅的下落。我还不至于受你摆布。', `MaleText_loc5`='怪物，你是無法從我這兒拿到一丁點消息的。就憑你的能力不用想要影響我。', `MaleText_loc7`='No me sacarás nada, monstruo. Estoy más allá de tu esfera de influencia.' WHERE `ID`=30242;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말하지 않겠다.', `MaleText_loc4`='不。', `MaleText_loc5`='不。', `MaleText_loc7`='No.' WHERE `ID`=30243;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇다면, 별수 없군. 이런 일이 또 나름대로 재미가 없는 것도 아니니.', `MaleText_loc4`='看来我别无选择了。好吧，其实我很乐意这样对付你的。', `MaleText_loc5`='你讓我無從選擇，不過，我可是樂在其中。', `MaleText_loc7`='Entonces no me dejas elección. No negaré que voy a disfrutar con esto.' WHERE `ID`=30244;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멈춰! 그렇게까지 중요한 일도 아니니. 웨스트윈드가 어디 있는지 말해 주겠다.', `MaleText_loc4`='住手！用不着这样。我告诉你他的下落。', `MaleText_loc5`='住手!這不值得，我會告訴你他的下落。', `MaleText_loc7`='¡ALTO! No vale la pena. Te diré donde está.' WHERE `ID`=30245;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 생각했다. 어서 말해라!', `MaleText_loc4`='很好。快说！', `MaleText_loc5`='很好。快說!', `MaleText_loc7`='Muy bien. ¡Dímelo!' WHERE `ID`=30246;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 섬 남쪽 끝 무렵에 동굴이 하나 있다. 숨겨진 동굴이라는 곳이지. 총사령관은 그 안에 숨어 리치 왕과 마지막 결전을 벌일 준비를 하고 있다.', `MaleText_loc4`='这座岛屿的南端有一处极端隐蔽的洞穴。元帅就躲在那儿，策划着对巫妖王的最后决战。', `MaleText_loc5`='島的南端有一座洞穴 -- 一座隱匿的山谷。上將藏身在那裡，準備與巫妖王決一死戰。', `MaleText_loc7`='En el lado sur de la isla hay una cueva, una caverna oculta. El Gran almirante se ha escondido ahí, preparándose para la batalla final contra el Rey Exánime.' WHERE `ID`=30247;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='숨겨진 동굴이라고? 흥미로운 사실이군. 네 할 바를 다 해주어서 고맙다, 랜드그렌. 안타깝지만, 이번에는 다시 살아나지 못할 것이다!', `MaleText_loc4`='隐蔽的洞穴？真有意思。兰德雷，你没有利用价值了。恐怕这次你就没有复活的机会了！', `MaleText_loc5`='一座隱匿的山谷?真是有趣。你貫徹了你的決心，蘭格瑞，但恐怕這回誰也不用想復活你了。', `MaleText_loc7`='¿Una caverna oculta? Que interesante. Landgren, has cumplido tu propósito, ¡pero me temo que esta vez no habrá resurrección para ti!' WHERE `ID`=30248;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으으으아아아아악..................................', `MaleText_loc4`='啊啊啊啊……', `MaleText_loc5`='啊咿呀呀呀呀～～～～～～～～', `MaleText_loc7`='AAAEEEEIIIiiiiiiiiiiiiiiiiiiiiiiiiiiii........................................' WHERE `ID`=30250;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마무리가 좀 유쾌하지는 않았군. 이제 네가 웨스트윈드 총사령관을 어떻게 처리할지나 얘기해보지.', `MaleText_loc4`='事情总算有了眉目，那么就让我们谈谈要如何对付巴利·韦斯温元帅吧。', `MaleText_loc5`='既然令人不快的事情解決了，我們來談談如何料理掉韋斯溫上將吧。', `MaleText_loc7`='Ahora que hemos terminado con lo desagradable, vamos a hablar sobre ti y tus tratos con el gran almirante Viento Oeste.' WHERE `ID`=30251;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 울부짖습니다!', `MaleText_loc4`='%s大声咆哮！', `MaleText_loc5`='%s咆哮著!', `MaleText_loc7`='¡%s ruge!' WHERE `ID`=30252;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='후퇴!', `MaleText_loc4`='撤退！', `MaleText_loc5`='撤退!', `MaleText_loc7`='¡Atrás!', `FemaleText_loc1`='후퇴!', `FemaleText_loc4`='撤退！', `FemaleText_loc5`='撤退!', `FemaleText_loc7`='¡Atrás!' WHERE `ID`=30253;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 움직여라! 우리가 엄호하겠다!', `MaleText_loc4`='士兵们，行动！我们负责掩护！', `MaleText_loc5`='移動吧，士兵!我們會掩護你們!', `MaleText_loc7`='¡Moveos soldados! ¡Os cubriremos!', `FemaleText_loc1`='모두 움직여라! 우리가 엄호하겠다!', `FemaleText_loc4`='士兵们，行动！我们负责掩护！', `FemaleText_loc5`='移動吧，士兵!我們會掩護你們!', `FemaleText_loc7`='¡Moveos soldados! ¡Os cubriremos!' WHERE `ID`=30254;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 엄호하고 있다! 후퇴!', `MaleText_loc4`='我们掩护你们！撤退！', `MaleText_loc5`='你們被掩護了，士兵!撤退!', `MaleText_loc7`='¡Soldados, estáis cubiertos! ¡Atrás!', `FemaleText_loc1`='우리가 엄호하고 있다! 후퇴!', `FemaleText_loc4`='我们掩护你们！撤退！', `FemaleText_loc5`='你們被掩護了，士兵!撤退!', `FemaleText_loc7`='¡Soldados, estáis cubiertos! ¡Atrás!' WHERE `ID`=30255;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='후퇴하라!', `MaleText_loc4`='快撤退！', `MaleText_loc5`='我們快撤退!', `MaleText_loc7`='¡Retrocedamos!', `FemaleText_loc1`='후퇴하라!', `FemaleText_loc4`='快撤退！', `FemaleText_loc5`='我們快撤退!', `FemaleText_loc7`='¡Retrocedamos!' WHERE `ID`=30256;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 엄호할 테니 어서 후퇴하라!', `MaleText_loc4`='我们负责掩护，立刻撤退！', `MaleText_loc5`='我們來掩護你們，現在就撤退!', `MaleText_loc7`='¡Os tenemos cubiertos, ahora retroceded!', `FemaleText_loc1`='우리가 엄호할 테니 어서 후퇴하라!', `FemaleText_loc4`='我们负责掩护，立刻撤退！', `FemaleText_loc5`='我們來掩護你們，現在就撤退!', `FemaleText_loc7`='¡Os tenemos cubiertos, ahora retroceded!' WHERE `ID`=30257;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동료와 함께 총사령관을 처리하고, 죽음의 마루로 돌아와 내게 보고해라.', `MaleText_loc4`='等你们解决掉元帅之后，再来死亡高地见我吧。', `MaleText_loc5`='當你與你的朋友解決了上將以後，回去死亡高崗找我。', `MaleText_loc7`='Reúnete conmigo en Ascenso de la Muerte cuando tú y tus amigos os hayáis ocupado del Gran almirante.' WHERE `ID`=30258;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='얼음송곳니는 수많은 전장을 나와 함께 누볐지.$b$b갑옷이 없다고 얼음송곳니를 과소평가하지 마라. 내가 아는 가장 강한 곰이니까.', `FemaleText_loc4`='冰牙已经陪伴我经历过无数次战役。$b$b不要被她不穿护甲的表象迷惑了。她是我见过的最聪明的熊。', `FemaleText_loc5`='冰牙已經載著我歷經了無數的戰鬥。$b$b別因為她沒穿上戰甲就被欺騙了，她可是我所知道最勇猛的熊了。', `FemaleText_loc7`='Colmillo de Hielo me ha llevado en incontables batallas.$b$bNo dejes que su falta de armadura te engañe. Es la osa más dura que conozco.' WHERE `ID`=30259;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기서 늑장 부리지 마라, 계집애야!$b$b싸움을 할 때란 말이다!', `FemaleText_loc4`='别再耽搁时间了！$b$b激烈的战斗在等待！', `FemaleText_loc5`='別在這逗留，丫頭!$b$b這兒還會發生戰鬥!', `FemaleText_loc7`='¡No te retrases, moza!$b$b¡Hay que luchar!' WHERE `ID`=30260;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='브룬힐다르의 영광을 위해!', `FemaleText_loc4`='为布伦希尔达村的荣耀而战！', `FemaleText_loc5`='我們為了布倫希爾達的榮耀而戰!', `FemaleText_loc7`='¡Luchamos por la gloria de Brunnhildar!' WHERE `ID`=30261;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흑마술사가 뭔가 무시무시하고 사악한 형상으로 탈태합니다.', `MaleText_loc4`='黑暗编织者变成了恐怖的恶魔生物。', `MaleText_loc5`='暗織者惡魔化身成為既恐怖又邪惡的樣貌。', `MaleText_loc7`='El tejeoscuro se transforma en algo terrible y demoníaco.', `FemaleText_loc1`='흑마술사가 뭔가 무시무시하고 사악한 형상으로 탈태합니다.', `FemaleText_loc4`='黑暗编织者变成了恐怖的恶魔生物。', `FemaleText_loc5`='暗織者惡魔化身成為既恐怖又邪惡的樣貌。', `FemaleText_loc7`='El tejeoscuro se transforma en algo terrible y demoníaco.' WHERE `ID`=30262;
