UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끔찍한 울부짖음과 함께, %s|1이;가; 악마 같은 형상으로 변합니다.', `MaleText_loc4`='%s发出恐怖的嚎叫声，变成了可怕的恶魔。', `MaleText_loc5`='一聲駭人的尖嘯之後，%s變成了惡魔般的夢魘。', `MaleText_loc7`='Con un grito horrible, el %s se transforma en una pesadilla demoníaca.', `FemaleText_loc1`='끔찍한 울부짖음과 함께, %s|1이;가; 악마 같은 형상으로 변합니다.', `FemaleText_loc4`='%s发出恐怖的嚎叫声，变成了可怕的恶魔。', `FemaleText_loc5`='一聲駭人的尖嘯之後，%s變成了惡魔般的夢魘。', `FemaleText_loc7`='Con un grito horrible, el %s se transforma en una pesadilla demoníaca.' WHERE `ID`=30264;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흑마술사가 완전히 다른 모습으로 변하며 사악한 미소를 흘립니다.', `MaleText_loc4`='黑暗编织者冲你露出邪恶的笑容，他的身体紧接着变成了完全不同的形态。', `MaleText_loc5`='當暗織者變成了一副全然不同樣貌的時候，他那邪惡的竊笑像是刺穿了你一樣。', `MaleText_loc7`='El tejeoscuro te atraviesa con una sonrisa malvada mientras adopta una forma totalmente distinta.', `FemaleText_loc1`='흑마술사가 완전히 다른 모습으로 변하며 사악한 미소를 흘립니다.', `FemaleText_loc4`='黑暗编织者冲你露出邪恶的笑容，他的身体紧接着变成了完全不同的形态。', `FemaleText_loc5`='當暗織者變成了一副全然不同樣貌的時候，她那邪惡的竊笑像是刺穿了你一樣。', `FemaleText_loc7`='El tejeoscuro te atraviesa con una sonrisa malvada mientras adopta una forma totalmente distinta.' WHERE `ID`=30265;
