UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐지?! 상관없다. 보호의 구슬이 없어도, 네놈들쯤이야! 내 진정한 모습을 보여주마! 각오해라!', `MaleText_loc4`='什么？！没关系。就算没有魔法屏障，我仍然可以轻易消灭你们！在绝望中感受我真正的力量吧！', `MaleText_loc5`='什麼?!沒關係，就算我沒有防護罩，我還是可以消滅你們!見識我的真面目，嚐嚐絕望的滋味!', `MaleText_loc7`='¡¿QUÉ?! No importa. Aun sin mi esfera, ¡te aplastaré! ¡Contempla mi verdadera identidad y desespera!' WHERE `ID`=30273;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 엄호한다! 어서 후퇴!', `MaleText_loc4`='我们负责掩护，立刻撤退！', `MaleText_loc5`='我們來掩護你們，現在就撤退!', `MaleText_loc7`='¡Os tenemos cubiertos, ahora retroceded!', `FemaleText_loc1`='우리가 엄호한다! 어서 후퇴!', `FemaleText_loc4`='我们负责掩护，立刻撤退！', `FemaleText_loc5`='我們來掩護你們，現在就撤退!', `FemaleText_loc7`='¡Os tenemos cubiertos, ahora retroceded!' WHERE `ID`=30274;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으으으으아! 저 약한 몸뚱이 안에 너무 오래 있었어!', `MaleText_loc4`='啊！我在那具虚弱的躯壳中待得太久了！', `MaleText_loc5`='呃，我花太多時間在韋斯溫的身體裡面，才讓我變得那麼虛弱!', `MaleText_loc7`='¡Gah! Pasé mucho tiempo en esa frágil y pequeña cáscara.' WHERE `ID`=30275;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='키렐 나라크! 나는 말가니스다. 나는 불멸이다!', `MaleText_loc4`='Kirel narak！我是玛尔加尼斯！我是不朽的！', `MaleText_loc5`='你怎麼可能擊敗我，(惡魔語)可憐的凡人!我是瑪爾加尼斯。我是永恆不朽的!', `MaleText_loc7`='¡Kirel narak! ¡Yo soy Mal''Ganis! ¡SOY ETERNO!' WHERE `ID`=30276;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만! 시간 낭비만 했군. 돌아가서 힘을 다시 모아야겠다.', `MaleText_loc4`='够了！我在这里浪费了不少时间，必须回到家乡去回复体力。', `MaleText_loc5`='夠了!我在這裡只是浪費我的時間，我得回去我的國度蓄積力量。', `MaleText_loc7`='¡BASTA! Malgasto mi tiempo. Debo reunir mis fuerzas en el mundo natal.' WHERE `ID`=30277;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 도움 없이 리치 왕을 물리칠 수 있을 것 같으냐? 나는 복수할 것이다... 녀석에게도, 너희에게도!', `MaleText_loc4`='没有我的部队，你们永远也别想击败巫妖王。我会向他复仇的……还有你们！', `MaleText_loc5`='沒有我的力量，你休想擊敗巫妖王。我會復仇...不只是他，還有你!', `MaleText_loc7`='Nunca derrotarás al Rey Exánime sin mis fuerzas. Me vengaré... ¡de él Y de ti!' WHERE `ID`=30278;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 날 쓰러뜨릴 수 있다고 생각했나?', `MaleText_loc4`='你们觉得我会甘心等死吗？', `MaleText_loc5`='你以為我會讓你就這樣殺了我嗎?', `MaleText_loc7`='¿Creíste que te dejaría matarme tan fácilmente?' WHERE `ID`=30279;
