UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스컬지가 북쪽 장벽을 돌파하고 있습니다!', `MaleText_loc4`='天灾军团攻破了北面的城墙！', `MaleText_loc5`='天譴軍正在破壞北方城牆!', `MaleText_loc7`='¡La Plaga está entrando por el muro norte!', `FemaleText_loc1`='스컬지가 북쪽 장벽을 돌파하고 있어요!', `FemaleText_loc4`='天灾军团攻破了北面的城墙！', `FemaleText_loc5`='天譴軍正在破壞北方城牆!', `FemaleText_loc7`='¡La Plaga está entrando por el muro norte!' WHERE `ID`=30284;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무장도 하지 않은 채 전장에 뛰어들다니, 얼음송곳니가 대단한 용기를 보여주었다.$B$B아마 $n, 너도 얼음송곳니를 보고 용기가 무엇인지 조금은 배웠겠지.', `FemaleText_loc4`='冰牙非常勇敢，不穿盔甲也敢上战场。$b$b$n，或许她能让你鼓起勇气，面对即将到来的挑战。', `FemaleText_loc5`='冰牙展現了無比的勇氣，身上不穿一件裝甲就殺進戰場。$b$b也許她這個榜樣可以為你灌注許多的勇氣，$n。', `FemaleText_loc7`='Colmillo de Hielo demuestra un gran valor al entrar en el campo de batalla sin armadura.$b$bQuizás su ejemplo pueda infundirte algo de valor, $n.' WHERE `ID`=30285;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 안 좋은 생각 같아, 친구.', `MaleText_loc4`='我说，情况似乎不妙啊。', `MaleText_loc5`='小子，這看起來不大妙。', `MaleText_loc7`='Esto no tiene buena pinta, muchacho.' WHERE `ID`=30286;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아닌 것 같은데, 베일리... 그렇게 나쁘진 않아. 여기에서 돌을 던져서 저기 있는 연장을 맞출 수 있었잖아.', `MaleText_loc4`='我觉得，拜雷……似乎没有那么糟糕吧。你瞧，从我们现在的位置扔石头，是能砸到工具的。', `MaleText_loc5`='不知道耶，貝利...還不算太糟啦。石頭還丟得到那些工具。', `MaleText_loc7`='No lo sé, Bailey... no está tan mal. Desde aquí podríamos tirarle una piedra a las herramientas.' WHERE `ID`=30287;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그거 이상하네... 저기서 잠깐이지만, 맹세코 네가 나를 땅딸보라고 하는 걸 들었단 말이지.', `MaleText_loc4`='真奇怪……等等，刚才我分明听见你说我矮。', `MaleText_loc5`='這可怪了...你給我等一下，我發誓你說過我很矮。', `MaleText_loc7`='Es extraño... ha habido un momento en el que habría jurado que me has llamado bajito.' WHERE `ID`=30288;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그게 사실이야? 어디 그 신체 3분의 1씩이나 차지하는 다리로 깡총거리면서 저기까지 가서 직접 가져오시지그래?', `MaleText_loc4`='是吗？既然如此，你为什么不自己跳过去取回工具呢？', `MaleText_loc5`='是這樣嗎?那你為什麼不用你那小小的身體，一邊雀躍著一邊把它們拿過來，嗯?', `MaleText_loc7`='¿Eso está bien? ¿Bueno, entonces por qué no vas y haces unas cabriolas con tu alegre cuerpecillo y las coges?' WHERE `ID`=30289;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 던진다고?! 좋아, 바로 그거야.', `MaleText_loc4`='把我扔过去？！你能不能别出这种馊主意？', `MaleText_loc5`='把我扔過去?!好哇，我受夠了，你這傢伙。', `MaleText_loc7`='¡¿Lanzarme?! Vale, se acabó, macarra.' WHERE `ID`=30290;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그냥 너 혼자서나 좋아하고 있어.', `MaleText_loc4`='我不想听。', `MaleText_loc5`='你自己留著吧。', `MaleText_loc7`='Guárdatela.' WHERE `ID`=30291;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모험가들이 살아남지 않기를 바라는 게 좋아, 친구.', `MaleText_loc4`='你最好祈祷他们直接被炸死。', `MaleText_loc5`='小子，你最好希望他們就死在那。', `MaleText_loc7`='Más te vale que no sobrevivan, chico.' WHERE `ID`=30292;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 널 던져 넣는 광경을 지켜보면서 웃기나 할 테니까.', `MaleText_loc4`='如果他们还活着的话，肯定会将你扔进雷区。到时候我只会在一旁偷笑。', `MaleText_loc5`='因為啊，我會邊笑邊看你被扔進去。', `MaleText_loc7`='Porque solo voy a mirar y a reírme cuando te tiren a ti.' WHERE `ID`=30293;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='찾아보면 어딘가에 다 길이 있는 법이지.', `MaleText_loc4`='一定有办法过去的。', `MaleText_loc5`='一定有辦法過去的。', `MaleText_loc7`='Tiene que haber un camino en alguna parte.' WHERE `ID`=30294;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러니까 거기에 고블린에 자기 연장을 놔뒀단 말이야?', `MaleText_loc4`='不然地精怎么能将他的工具留在那里呢？', `MaleText_loc5`='到底為什麼哥布林會把他的工具留在那兒?', `MaleText_loc7`='Si no, ¿cómo es que el goblin se ha dejado aquí las herramientas?' WHERE `ID`=30295;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='됐어, 친구! 완전히 안전해. 네가 가봐. 내가 바로 뒤에 있을 테니까!', `MaleText_loc4`='对啦！看上去绝对安全啊。你走前面，我会跟着你的！', `MaleText_loc5`='就是它了，小子!那看起來一點也不危險。上吧，我就跟在你後面!', `MaleText_loc7`='¡Eso es, $gmuchacho:muchacha;! Parece completamente seguro. Adelante, ¡estaré justo detrás de ti!' WHERE `ID`=30296;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='글쎄... 그냥 내 생각인데... 네가 조금 더 짧은 것 같아. 그러니까 그 지뢰를 터뜨릴 확률이 더 낮다는 거지.', `MaleText_loc4`='呃……我刚才在想……你的个子比较矮，所以不可能让你来引爆地雷。', `MaleText_loc5`='嗯...我在想...你稍微小了那麼一些，所以你應該比較不容易引爆那些地雷。', `MaleText_loc7`='Bueno... estaba pensando... tú eres un poco más pequeño, así que es más difícil que actives alguna de las minas.' WHERE `ID`=30297;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니야, 아니야, 아니라고! 안 짧아... 이건 그냥... 그러니까... 내가 널 던져줄 수도 있을 것 같은데?', `MaleText_loc4`='没有！没有！我不是说你矮啦……呃……这么说吧……或许我可以将你扔过去，直接穿越这片雷区？', `MaleText_loc5`='不不不!不是矮啦...只是...欸...也許我可以把你扔過大部分的地雷也說不定?', `MaleText_loc7`='¡No, no, no! Bajito no... es que... bueno... ¿quizás yo podría lanzarte para que cruces la mayor parte?' WHERE `ID`=30298;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나한테 좋은 생각이 있는데 말이야, 베일리...', `MaleText_loc4`='拜雷，我想到一个办法……', `MaleText_loc5`='貝利，我有個主意...', `MaleText_loc7`='Bailey, tengo una idea...' WHERE `ID`=30299;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니, 들어봐! 이번 건 진짜로 좋은 생각이라니까!', `MaleText_loc4`='听我说——这个法子说不定管用！', `MaleText_loc5`='不，不 - 這一定會成功的!', `MaleText_loc7`='No, no. ¡Esto podría funcionar!' WHERE `ID`=30300;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 저기 길이 있어... 우리와 저 연장 사이에는 끝 부분에 지뢰 몇 개만 있을 뿐이라고.', `MaleText_loc4`='你瞧，沿着这条道走，我们和工具之间……其实只有几枚地雷。', `MaleText_loc5`='那兒就有一條路徑...路徑的末端，我們和工具之間，只有一點點的地雷而已。', `MaleText_loc7`='Ahí mismo hay un camino... entre nosotros y las herramientas solo hay algunas minas al final.' WHERE `ID`=30301;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그냥 다음 모험가가 지나가기를 기다렸다가 저 길로 가라고 말해주자... 그 모험가가 지뢰를 터뜨리고 나면, 우리는 그냥 걸어가서 연장을 집어 오는 거지!', `MaleText_loc4`='我们就在这里等待下一拨冒险者，然后告诉他们该往哪儿走……等他们引爆地雷后，我们就可以直接走过去拿工具了！', `MaleText_loc5`='我們就只要等著下個冒險者走過來，我們告訴他那條路可以走...然後當他們引爆那些地雷，我們就大剌剌走過去拿走工具!', `MaleText_loc7`='Esperamos a que llegue el siguiente aventurero y le decimos que se sale por ahí... ¡y después de que activen las minas, vamos y cogemos las herramientas!' WHERE `ID`=30302;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇게는 안 될 것 같아, 베일리.', `MaleText_loc4`='拜雷，我实在想不出有什么办法可以过去。', `MaleText_loc5`='真的跟你所看起來的不同啦，貝利。', `MaleText_loc7`='Bailey, no parece que vaya a ser así.' WHERE `ID`=30303;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아.. 맞는 말이야. 저기는 어때? 저기는 좀 안전해 보이는데... 보기에는 말이야.', `MaleText_loc4`='噢……有道理。是那里吗？那条道似乎……没有障碍。', `MaleText_loc5`='噢...這個見解不錯。那裡如何?那裡看起來乾淨得多...也許吧。', `MaleText_loc7`='Oh... buena idea. ¿Qué tal ahí mismo? Eso parece despejado... o algo.' WHERE `ID`=30304;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 알았어. 하지만, 지난번에 다친 데가 아직 좀 아프단 말이지.', `MaleText_loc4`='嗯……好吧。上次的伤还在隐隐作痛呢。', `MaleText_loc5`='呃...那算了。從上次到現在還是很痛。', `MaleText_loc7`='Eh... eso está bien. Todavía me duele lo de la última vez.' WHERE `ID`=30305;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아!', `MaleText_loc4`='啊！', `MaleText_loc5`='啊～～!', `MaleText_loc7`='¡Aaah!' WHERE `ID`=30306;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니 이런...', `MaleText_loc4`='天啊……', `MaleText_loc5`='噢老天...', `MaleText_loc7`='Oh, vaya...' WHERE `ID`=30307;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽기 싫어!', `MaleText_loc4`='我还不想死！', `MaleText_loc5`='我不想死!', `MaleText_loc7`='¡No quiero morir!' WHERE `ID`=30308;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안돼, 안돼... 안돼!', `MaleText_loc4`='天哪……不！', `MaleText_loc5`='不，不...不!', `MaleText_loc7`='¡No, no... no!' WHERE `ID`=30309;
