UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 가까웠어! 너 때문에 놀랐잖아.', `MaleText_loc4`='就差一点！你吓死我了！', `MaleText_loc5`='就差那麼一點!你嚇死我了。', `MaleText_loc7`='¡Eso ha estado cerca! Me has asustado.' WHERE `ID`=30311;
