UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, $c. 열쇠를 잃어버렸다면 내가 도와줄 수 있어.', `MaleText_loc4`='嘿，$c。如果你弄丢了钥匙，我或许能帮上忙。', `MaleText_loc5`='嘿，$c，要是你掉了鑰匙，或許我能幫忙。', `MaleText_loc7`='Hola, $c, si has perdido una llave puede que yo pueda ayudarte.', `FemaleText_loc1`='이봐요, $c. 열쇠를 잃어버렸다면 내가 도와줄 수 있어요.', `FemaleText_loc4`='嘿，$c。如果你弄丢了钥匙，我或许能帮上忙。', `FemaleText_loc5`='嘿，$c，要是你掉了鑰匙，或許我能幫忙。', `FemaleText_loc7`='Hola, $c, si has perdido una llave puede que yo pueda ayudarte.' WHERE `ID`=30314;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스칼로맨스 열쇠를 잃어버렸습니다.', `MaleText_loc4`='我把通灵学院的钥匙弄丢了。', `MaleText_loc5`='我把通靈學院的鑰匙搞丟了。', `MaleText_loc7`='He perdido mi llave de Scholomance.', `FemaleText_loc1`='스칼로맨스 열쇠를 잃어버렸어요.', `FemaleText_loc4`='我把通灵学院的钥匙弄丢了。', `FemaleText_loc5`='我把通靈學院的鑰匙搞丟了。', `FemaleText_loc7`='He perdido mi llave de Scholomance.' WHERE `ID`=30315;
