UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이글거리는 협곡 열쇠를 잃어버렸습니다.', `MaleText_loc4`='我把灼热峡谷的钥匙弄丢了。', `MaleText_loc5`='我把灼熱峽谷的鑰匙搞丟了。', `MaleText_loc7`='He perdido mi llave de la Garganta de Fuego.', `FemaleText_loc1`='이글거리는 협곡 열쇠를 잃어버렸어요.', `FemaleText_loc4`='我把灼热峡谷的钥匙弄丢了。', `FemaleText_loc5`='我把灼熱峽谷的鑰匙搞丟了。', `FemaleText_loc7`='He perdido mi llave de la Garganta de Fuego.' WHERE `ID`=30318;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠괴철로 열쇠를 잃어버렸습니다.', `MaleText_loc4`='我把暗炉钥匙弄丢了。', `MaleText_loc5`='我把我的影爐鑰匙搞丟了。', `MaleText_loc7`='He perdido mi llave Forjatiniebla.', `FemaleText_loc1`='어둠괴철로 열쇠를 잃어버렸어요.', `FemaleText_loc4`='我把暗炉钥匙弄丢了。', `FemaleText_loc5`='我把我的影爐鑰匙搞丟了。', `FemaleText_loc7`='He perdido mi llave Forjatiniebla.' WHERE `ID`=30319;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하라매드의 눈 열쇠를 잃어버렸습니다.', `MaleText_loc4`='我把哈拉迈德之眼弄丢了。', `MaleText_loc5`='我把哈拉瑪德之眼搞丟了。', `MaleText_loc7`='He perdido el Ojo de Haramad.', `FemaleText_loc1`='하라매드의 눈 열쇠를 잃어버렸어요.', `FemaleText_loc4`='我把哈拉迈德之眼弄丢了。', `FemaleText_loc5`='我把哈拉瑪德之眼搞丟了。', `FemaleText_loc7`='He perdido el Ojo de Haramad.' WHERE `ID`=30320;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카라잔 열쇠를 잃어버렸습니다.', `MaleText_loc4`='我把卡拉赞的钥匙弄丢了。', `MaleText_loc5`='我把卡拉贊的鑰匙搞丟了。', `MaleText_loc7`='He perdido mi llave de Karazhan.', `FemaleText_loc1`='카라잔 열쇠를 잃어버렸어요.', `FemaleText_loc4`='我把卡拉赞的钥匙弄丢了。', `FemaleText_loc5`='我把卡拉贊的鑰匙搞丟了。', `FemaleText_loc7`='He perdido mi llave de Karazhan.' WHERE `ID`=30321;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='망할 무쇠 드워프놈들이 다시 나타났군요! 아무래도 우리보다 앞서 그를 발견한 모양입니다.', `MaleText_loc4`='又是那些该死的铁矮人！他们居然抢在我们前面找到了他。', `MaleText_loc5`='又是那些該死的鐵矮人!他們用了某種辦法，趕在我們之前找到了他。', `MaleText_loc7`='¡Son esos malditos enanos de hierro de nuevo! Lo han encontrado, de alguna forma, antes que nosotros.' WHERE `ID`=30322;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그를 찾기 전에는 절대 포기하지 않을 놈들입니다. 그런 일이 일어나게 놔둬서는 안 됩니다, $n. 브란도 이 사실을 잘 알지요.', `MaleText_loc4`='他们不找到他是不会放弃的。我们不能让这种事发生，$n，布莱恩也明白这一点。', `MaleText_loc5`='他們找到他以前是不會善罷甘休的。我們不能讓這件事發生，$n，布萊恩也會這麼認為的。', `MaleText_loc7`='No se van a rendir hasta que lo encuentren. No podemos permitir que eso suceda, $n y Brann lo sabe.' WHERE `ID`=30323;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 쪽지에 적힌 지시 사항은 거의 암호나 다름없습니다. 브란에게 분명히 다른 계획이 있을 테지만, 그렇다 하더라도 영원히 잡히지 않고 피해 다닐 수는 없을 겁니다...', `MaleText_loc4`='日记中记载着一些晦涩难懂的信息。布莱恩一定有后备计划，但他不可能永远不被抓到……', `MaleText_loc5`='在筆記中有些隱藏的指示，布萊恩一定有一些備用計畫，但是他不可能永遠躲避這些追捕...', `MaleText_loc7`='En esta nota hay unas instrucciones bastante crípticas. Brann debe tener algún otro plan, pero no puede seguir evitando la captura eternamente...' WHERE `ID`=30324;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무쇠 드워프보다 빨리 브란을 찾는 일은 당신에게 달렸습니다!', `MaleText_loc4`='现在就指望你了，一定要抢在铁矮人前面找到他！', `MaleText_loc5`='搶在鐵矮人之前找到他，這任務就交給你了!', `MaleText_loc7`='¡Es cosa tuya encontrarlo antes de que lo hagan los hierros!' WHERE `ID`=30325;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 지금 비전 마법의 대가와 마주한 걸세. 나에게 도전한다면 현명하지 못한 자겠지. 내가 지나온 자리는 불길에 휩싸인 시체만이 남을 뿐이니 말일세.', `MaleText_loc4`='站在你面前的是一位奥术魔法的大师。只有蠢货才会不自量力地向我宣战。他们无一例外地变成了烧焦的尸体。', `MaleText_loc5`='你站在一位秘法大師的面前，任何挑戰我的人都是不智的，我醒來之後只會留下一具具燃燒的屍體。', `MaleText_loc7`='Ante ti se alza un señor de lo Arcano. Desafiarme sería una necedad. A mi paso he dejado muchos cadáveres en llamas.' WHERE `ID`=30326;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제 육신과 영혼에는 역겨운 저 호드 놈들에 얽힌 기억이 가득하지요. 슬픔, 좌절, 희생만이 가득하던 시간은 지나갔어요. 분노가 제 마음에서 떠나지 않은 채 싸움을 갈망하고 있어요!', `FemaleText_loc4`='我的生命与灵魂中充斥着部落留给我的痛苦回忆。悲伤、绝望和牺牲已经成为历史。战争的怒火永远在我内心深处燃烧！', `FemaleText_loc5`='我的生活與靈魂充滿著令人不耐的部落回憶。這悲傷的時刻，消沉與犧牲都已成過往。戰爭的怒火卻未曾遠離我的心中!', `FemaleText_loc7`='Mi vida y mi alma han estado llenas con recuerdos de la insufrible Horda. Tiempos de dolor, desesperación y sacrificio. ¡La furia de la batalla jamás podría abandonar mi corazón!' WHERE `ID`=30327;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 일하면서 휘파람을 붑니다.', `FemaleText_loc4`='%s一边做事，一边吹着口哨。', `FemaleText_loc5`='%s一邊工作一邊吹口哨。', `FemaleText_loc7`='%s silba mientras trabaja.' WHERE `ID`=30328;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 왕자와 머나먼 왕국을 꿈꾸며 몽상에 잠깁니다.', `FemaleText_loc4`='%s幻想着王子与遥远的国度。', `FemaleText_loc5`='%s做著關於王子的白日夢，魂不守舍。', `FemaleText_loc7`='%s sueña despierta con príncipes y reinos muy lejanos.' WHERE `ID`=30329;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아라시 분지 전장으로 가는 차원문입니다.', `MaleText_loc4`='该传送门通往阿拉希盆地战场。', `MaleText_loc5`='這是通往阿拉希盆地戰場的傳送門。', `MaleText_loc7`='Este es un portal para el campo de batalla de la Cuenca de Arathi.' WHERE `ID`=30330;
