UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요! 낚시용품을 사러 오셨나요? 낚시법 한 두 가지 배우러 오셨나요?', `FemaleText_loc4`='你好啊！你想要购买渔具，还是学习垂钓的艺术？', `FemaleText_loc5`='嗨!要來買點釣魚用具嗎，還是想加減上一下課?', `FemaleText_loc7`='¡Qué hay! ¿Quieres comprar suministros de pesca o recibir una lección o dos?' WHERE `ID`=30372;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자료 무결성 확인 중...', `MaleText_loc4`='评估数据库的完整性……', `MaleText_loc5`='評量資料完整性中...', `MaleText_loc7`='Valorando la integridad de la base de datos...' WHERE `ID`=30373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='3등급 진단 실행 중...', `MaleText_loc4`='运行三级诊断……', `MaleText_loc5`='啟動三級診斷...', `MaleText_loc7`='Ejecutando un diagnóstico de nivel tres...' WHERE `ID`=30374;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조각모음 실행 중...', `MaleText_loc4`='整理交换文件……', `MaleText_loc5`='重新整理交換資料...', `MaleText_loc7`='Desfragmentando archivo de intercambio...' WHERE `ID`=30375;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='암호 키 확인 중...', `MaleText_loc4`='校验密钥……', `MaleText_loc5`='驗證密碼...', `MaleText_loc7`='Verificando clave de encriptación...' WHERE `ID`=30376;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='데이터 복원 중...', `MaleText_loc4`='尝试修复丢失的数据……', `MaleText_loc5`='嘗試恢復遺失資料...', `MaleText_loc7`='Intentando recuperar datos perdidos...' WHERE `ID`=30377;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새로운 보안 프로토콜 설정 중...', `MaleText_loc4`='执行新的安全协议……', `MaleText_loc5`='加入新的安全措施...', `MaleText_loc7`='Implementando nuevos protocolos de seguridad...' WHERE `ID`=30378;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잃었던 과거와 권좌를 되찾고자 아제로스 전역을 누비며 싸우느라 너무 오래 자리를 비운 듯하구나. 내가 없는 동안 얼라이언스를 시험에 빠뜨렸던 그 모든 일들을 생각해보면, 우리 연합을 지켜내는 그대와 같은 영웅이 있어서 내 마음이 얼마나 훈훈해지는지 모른다.', `MaleText_loc4`='我踏遍了艾泽拉斯的每一寸土地，想要寻找失落的荣耀并收复属于我的王国。在我离开暴风城的这段日子里，联盟经历了种种考验。有你这样的英雄保卫我们脆弱的盟国，我真是倍感欣慰。', `MaleText_loc5`='我離開太久了，在艾澤拉斯上尋找我的過去跟重新奪回王座。在我離開時，聯盟承受了許多挑戰，而你們這些英雄還能為我們的聯軍奮鬥讓我很溫暖。', `MaleText_loc7`='He estado ausente durante demasiado tiempo, luchando por Azeroth para redescubrir mi pasado y reclamar mi trono. Con todos los desafíos que ha tenido que superar la Alianza en mi ausencia, ver que hay héroes como tú defendiendo nuestra coalición llena de gozo mi corazón.' WHERE `ID`=30379;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투 준비! 항구를 지켜야 한다. 그렇지 않으면 우리 얼라이언스는 노스렌드를 공격하기도 전에 저지당하고 말리라!', `MaleText_loc4`='拿起武器！我们必须守住港口，否则联盟远征诺森德的计划就会提前流产！', `MaleText_loc5`='武裝!我們一定要防衛港口!不然聯盟對北裂境的進攻在開始前就要結束了!', `MaleText_loc7`='¡A las armas! ¡Defended el puerto o el asalto de la Alianza a Rasganorte terminará incluso antes de empezar!' WHERE `ID`=30380;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번에 리치 왕이 우리를 욕보였던 일은 반드시 되갚아 주어야만 한다. 스톰윈드도 할 수 있는 만큼 노력하고 있지만, 승리를 거두려면 모두가 함께 해야 한다. 우리 본거지에 닥친 위협을 처리하고 난 뒤에라야 외부에 있는 스컬지를 처리할 수 있으리라.$B$B반역자인 아서스 왕자는 노스렌드에서 권좌에 올라 우리를 여러 가지로 시험하고 있다. 그렇다고 얼라이언스가 굽히는 일은 없을 터이니 안심하라. 이미 전쟁 준비는 시작되었으니...$B$B리치 왕과 그 군대와 싸우는 일은 기나긴 도전과 시련이 될 것이다. 죽음 그 자체를 이겨내야 한다. 수많은 목숨이 희생되겠지만, 아제로스의 미래가 우리 승리에 달렸다.$B$B나는 그대가 노스렌드에서 펼쳐질 싸움에 뛰어들어 용기와 그동안 갈고 닦아온 실력을 발휘하기만을 바랄 뿐이다.', `MaleText_loc4`='我们必须对巫妖王的挑衅做出回应。暴风城的子民将尽力而为，但是想要克服眼前的危机，我希望你们所有人都能贡献出自己的力量。只有首先解除家园的威胁，我们才有可能粉碎天灾军团在诺森德的阴谋。$B$B叛离的王子阿尔萨斯从远在诺森德的王座上向我们发起了挑战。联盟不能束手待毙。战争……一触即发。$B$B击败巫妖王和他的部队将是一个漫长而艰难的过程。我们必须征服死亡本身。许多人可能会因此牺牲，但艾泽拉斯的未来就看我们能否取胜了。$B$B我希望你能参与诺森德的战斗，为这一崇高的事业奉献自己的价值。', `MaleText_loc5`='對於巫妖王近期的侮辱，我們一定要做出回應。暴風城已經在努力的動員了，但是這需要每個人的幫助才能克服這個難關。只有在這次難關過去，我們才能對付遠方的天譴軍威脅。$B$B叛徒阿薩斯王子在他的北裂境的王座上試試我們。他確信聯盟不會坐以待斃。戰爭...的準備已經在進行中了。$B$B擊敗巫妖王與他的軍隊將會是漫長而艱辛的道路。我們一定要征服死亡。許多人會死，但是艾澤拉斯的未來依靠著我們的勝利。$B$B我只希望你能夠加入北裂境的戰鬥，貢獻你的技巧與力量。', `MaleText_loc7`='El Rey Exánime debe pagar por su última afrenta. Ventormenta hace lo que puede, pero para vencer todos deberemos esforzarnos. Solo después de que la amenaza en casa haya terminado, podremos empezar a ocuparnos de la Plaga al otro lado del mar.$B$BArthas, el príncipe traidor, nos pone a prueba desde su trono en Rasganorte. Ten por seguro que la Alianza no se quedará de brazos cruzados. Ya han comenzado los preparativos... para la guerra.$B$BDerrotar al Rey Exánime y a sus ejércitos será una larga y peligrosa experiencia. Se perderán muchas vidas, pero el futuro de Azeroth depende de nuestra victoria.$B$BSolo espero que puedas unirte a la batalla en Rasganorte y contribuir con tu fuerza y habilidad a la causa.' WHERE `ID`=30381;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='린 국왕께서 우리에게 돌아오시자마자 또 다른 왕이 자신의 존재를 드러냈네. 5년 동안, 스컬지는 점령했던 땅에 처박혀 있었고 용감한 영웅들이 안팎으로 닥친 위협에 대처해 주는 호사를 누렸지.', `MaleText_loc4`='乌瑞恩国王很快就会回归。五年来，天灾军团按兵不动地驻守在原有的领地上，并未向外扩展他们的势力范围。世界各地偶尔出现的危机，也被勇敢的英雄们逐一化解。这样和平的日子已经结束了。', `MaleText_loc5`='烏瑞恩王回來不久，另外一位王也為眾人所知。在這五年之中，勇敢的英雄們到處奮戰，我們卻放任天譴軍在他們攻佔來的地盤上享樂。', `MaleText_loc7`='Tan pronto el rey Wrynn vuelva con nosotros, otro rey da a conocer su presencia. Durante cinco años hemos tenido la suerte de que la Plaga ha permanecido en sus tierras conquistadas mientras valerosos héroes se encargaban de las amenazas de este mundo y el otro.' WHERE `ID`=30382;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제길! 지금은 얘기나 할 때가 아닐세! 스컬지 병력이 우리 군함을 압박하고 있단 말일세. 무기를 집어들고 군함을 사수하게! 군함을 잃는다면 우리가 몇 달 동안 해온 노력이 수포로 돌아가고 말 걸세!', `MaleText_loc4`='现在不是聊天的时候！天灾军团正在攻击我们的战舰。拿起武器，保护那些船只！如果它们被毁了，那我们数月的心血就会付诸流水！', `MaleText_loc5`='快去，現在不是講話的時候!天譴軍的部隊已經逼近了我們的戰艦。挑選好你的武器就去保衛船隻!要是船被擊沉的話，我們這幾個月的努力就白費了!', `MaleText_loc7`='¡Maldición, no es hora de hablar! Las fuerzas de la Plaga atacan nuestros barcos de guerra. ¡Coge el arma que más te guste y protege esos barcos! ¡Si los destruyen, nuestros esfuerzos bélicos se retrasarán varios meses!' WHERE `ID`=30383;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 로데론에서 했던 노력은 모두 부질없는 일이 되었네. 스컬지를 여러 번 퇴각시켰음에도 녀석들은 미동도 하지 않았지. 녀석들의 뿌리를 쳐 내야 하네.$B$B이제 노스렌드로 배를 띄울 시간이 다가왔네. 우리 앞에 무엇이 있을지는 모르네만, 셀 수도 없이 많은 적이 우리를 노리는 것만은 사실이네.$B$B우린 반드시 이 길을 가야 하네. 아제로스가 우리에게 달렸으니 말일세.', `MaleText_loc4`='我们在洛丹伦的努力已化为泡影。军队遭到重创，而天灾军团的势力并未损减。我们必须从源头上消灭他们。$B$B我们要去诺森德。我并不知道前方隐藏着怎样的危机，只知道那里有无数急于杀死我们的敌人。$B$B但是我们别无选择，艾泽拉斯的未来已经落在了我们的肩膀上。', `MaleText_loc5`='我們在羅德隆所做的努力早已白費。除了數不盡的挫折外，天譴軍一點都不擔心我們。我們必須從源頭切斷他們的支援。$B$B航向北裂境的時間已然來臨。我不知道前方等著我們的是什麼;但我知道敵人眾多，渴望屠殺我們。$B$B良心在上，我們沒有第二條路可選。艾澤拉斯需要我們的警戒。', `MaleText_loc7`='Nuestros esfuerzos en Lordaeron han sido en vano. A pesar de los numerosos contratiempos, la Plaga sigue invicta. Debemos acabar con ellos de raíz.$B$BSe acerca la hora de navegar hacia Rasganorte. No sé lo que nos aguarda, solo que nuestros enemigos son muchos y ansían nuestra muerte.$B$BPero si tenemos conciencia, no podemos seguir otro camino. Azeroth depende de nuestra vigilia.' WHERE `ID`=30384;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 모습을 바꾸기 시작합니다!', `MaleText_loc4`='%s开始变形！', `MaleText_loc5`='%s開始變形!', `MaleText_loc7`='¡%s comienza a transformarse!' WHERE `ID`=30385;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='3차 대전쟁 때 내가 마지막으로 함께한 이래로, 얼라이언스는 극적인 변화를 겪었소. 좋은 변화도 있었지만, 또 어떤 변화는...$B$B<발리라를 쓸쓸한 눈빛으로 바라보는 브롤>$B$B...유감스럽지만 피할 수도 있었소.$B$B불타는 군단과 그들이 아제로스를 공격해온 일에 모든 초점이 집중되었기에 스컬지는 엄청난 규모로 불어났소. 아제로스를 불타는 군단이 타락시킨 일이나 스컬지가 짓밟은 일 모두 마찬가지라 할 수 있소. 자연의 질서를 벗어난 것이니 반드시 끝을 내야 하오.', `MaleText_loc4`='自从第三次战争中我最后一次和盟友并肩作战以来，联盟发生了翻天覆地的变化。某些变化固然是好的，但是另一些……$B$B<布罗尔绝望地看着瓦莉拉。>$B$B……本来是可以避免的。$B$B在我们集中精神抵御燃烧军团对艾泽拉斯的攻击时，天灾军团逐渐发展壮大，形成了一股可怕的势力。燃烧军团的堕落力量和天灾军团的污染力量在本质上是相同的：它们都是违反自然法则的存在。我们必须扼杀它们。', `MaleText_loc5`='自從我在第三次戰爭時行走於人民之中，聯盟已經有了很大的改變。有些是好的，有些...$b$b<布洛可憐地看著瓦麗拉。>$B$B...本來是可以避免的。$B$B我們全心全意投入與燃燒軍團與他們對艾澤拉斯的攻擊時，天譴軍已經成長為一股可怕的力量。軍團的對於大地的腐化，與天譴軍隊大地的污染都是一樣的:是一種必須終結的自然異變。', `MaleText_loc7`='La Alianza ha sufrido varios cambios importantes desde la época de la Tercera Guerra. Algunos son buenos y otros...$B$B<Broll mira con tristeza a Valeera.>$B$B... podrían haberse evitado.$B$BCon toda la atención sobre la Legión Ardiente y sus ataques contra Azeroth, la Plaga se ha convertido en una fuerza temible. La corrupción de la Legión y el saqueo de la tierra de la Plaga son lo mismo: una aberración del orden natural que ha de terminar.' WHERE `ID`=30386;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말을 삼가시오! 스컬지가 이곳을 함락한다면, 리치 왕에게 반격하고자 하는 얼라이언스의 희망에 찬물을 끼얹는 일이나 다름없소!', `MaleText_loc4`='别说废话！如果天灾军团攻陷了我们的城市，那么联盟击败巫妖王的希望就破灭了！', `MaleText_loc5`='省省你的口水吧!要是天譴軍在這裡獲勝的話，聯盟反攻巫妖王的希望就會毀滅!', `MaleText_loc7`='¡Ahórrate las palabras! Si la Plaga vence aquí, ¡las esperanzas de la Alianza de golpear al Rey Exánime quedarán destruidas!' WHERE `ID`=30387;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 매머드로 모습을 바꿉니다!', `MaleText_loc4`='%s变成了一头猛犸象！', `MaleText_loc5`='%s變成了一隻長毛象!', `MaleText_loc7`='¡%s se transforma en un mamut!' WHERE `ID`=30388;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='3차 대전쟁 이후로 이렇게 많은 병력이 집결한 걸 본 적이 없소이다! 바리안 왕께서는 스컬지의 위협에 맞서 정면 대처하고 계시오. 과연 국왕다운 인물이시지...$B$B노스렌드로 떠나려 하시오? 나는 가본 적이 없소만, 아름다우면서도 한 치 앞을 예상할 수 없는 곳이라 하더군. 안타깝지만, 나는 본국에서 폴드라곤 대영주께서 이끄는 군대와 함께 더 급한 일을 처리해야 해서 노스렌드로 떠날 수가 없소.', `MaleText_loc4`='自从第三次战争后，我再也没有见过如此整齐的部队了！瓦里安已经决心直面天灾军团的威胁。这才像他……$B$B你要去诺森德吗？我没有去过那里，不过我听说诺森德是一片美丽丰饶的土地。遗憾的是，我必须留下来处理各种紧急事件，因此无法随弗塔根公爵的部队一同出发。', `MaleText_loc5`='從第三次戰爭以後，我就沒有看過這樣的軍容了。瓦里安一心想要直接對付天譴軍，這就像他會做的事情...$b$b你要前往北裂境嗎?我從來沒去過那裡，但是我聽說那裡是個美麗又變化莫測的地方。不過，家鄉有些急事需要我處理，所以我不能加入大領主弗塔根的旅程。', `MaleText_loc7`='¡No había visto tal reunión de tropas desde la Tercera Guerra! Varian está empeñado en enfrentarse a la amenaza de la Plaga de forma directa. Fiel a su estilo...$B$B¿Te diriges a Rasganorte? Yo nunca he estado allí, pero he oído que es una tierra hermosa a la par que peligrosa. Por desgracia, asuntos urgentes en casa exigen mi atención, así que no podré unirme al alto señor Fordragón y a su ejército en su viaje.' WHERE `ID`=30389;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신 눈빛에서 그런 눈치를 챘습니다. 당신네가 무슨 생각인지 내가 모를 거라고는 생각하지 마십시오. 경비병이나 시민이나 마찬가지로 의심의 눈초리를 보내는 것이 영 불편할 따름입니다.$B$B바리안 왕께 지켜야 할 의무가 있기에 있는 것뿐입니다. 그분은 나를 똑같이 대해주시니까 말이지요... 바로 그런 식으로 얼라이언스는 우리 종족을 대해야 합니다.$B$B이제 스컬지가 스톰윈드에서 난리를 피우니 말입니다. 넋 놓고 볼만큼 다 봤다면, 가서 무언가 손을 좀 써보는 건 어떻겠습니까?', `FemaleText_loc4`='别用那种眼神打量我。我理解你们的感受。但是卫兵还有平民始终向我投来怀疑的目光，这点令我难以忍受。$B$B为了履行对瓦里安的承诺，我却打算继续留在这里。他能以平等的态度看待我……联盟也应该用这种态度对待我的族人。$B$B天灾军团正在破坏暴风城的宁静，如果你看够了的话，不如去帮帮忙？', `FemaleText_loc5`='我看見你眼中的神情。別覺得我對你人民的感覺很傲慢。我只是對於那些從人民或守衛眼中投射出的不信任感到不舒服而已。$B$B我待在這是為了我對瓦里安的職責。他也是這樣對待我...就向聯盟對待我的人民的方式。$B$B現在，要是你可以停止目瞪口呆，也許你會察覺到天譴軍把暴風城弄得一團亂。你為什麼不去做些什麼?', `FemaleText_loc7`='Reconozco esa mirada en tus ojos. No creas que ignoro los sentimientos de tu pueblo. Me sientan igual de mal las miradas de desconfianza de los guardias que las de los ciudadanos.$B$BSolo me quedo por aquí por mis obligaciones hacia Varian. Él me trata como a una igual... igual que la Alianza debería haber tratado a mi pueblo.$B$BAhora, si ya has terminado de mirar, la Plaga está liando una buena en Ventormenta. ¿Por qué no vas a hacer algo al respecto?' WHERE `ID`=30390;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지금은 얘기나 할 때가 아닙니다! 저 군함이 파괴된다면, 얼라이언스는 리치 왕과 싸우는 대신에 본국으로 돌아가서 스컬지를 상대해야 합니다! 조금이라도 도움이 되도록, 가서 언데드나 좀 처리하십시오!', `FemaleText_loc4`='没时间闲聊了！如果船只被摧毁，联盟就只能在自己的家园与天灾军团作战，还怎么攻陷巫妖王的老巢！快去帮忙吧，杀掉那些亡灵！', `FemaleText_loc5`='沒時間說話了!要是船沉了，聯盟就得在自己的家園對抗巫妖王，而不是巫妖王的領地!快去讓你自己當個有用的人，殺點不死生物!', `FemaleText_loc7`='¡No es momento de hablar! ¡Si se destruyen esos barcos, la Alianza tendrá que luchar contra la Plaga en su hogar y no en el del Rey Exánime! ¡Así que se útil y mata a algunos no-muertos!' WHERE `ID`=30391;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='호드가 자체적으로 병력을 모아 노스렌드로 향하고 있다는 소식을 들었습니다. 당신네 얼라이언스와 호드는 진짜 위협이 되는 대상에 초점을 맞추어 공격했으면 합니다. 제 말이 무슨 말인지 다 아시겠지만, 서로 치고받는 대신에 말입니다.$B$B경험에 비추어 본다면, 그런 일은 없으리라 생각합니다. 당신네가 나를 그렇게나 반겨주었으니 말이지요.$B$B<화를 내며 혼자서 중얼거리는 발리라>', `FemaleText_loc4`='我听说部落也在招募征战诺森德的军队。希望联盟和部落可以将矛头一致指向真正的威胁。你懂我的意思吧，我是说不要窝里斗。$B$B虽然以我的经验来看，实现真正的同盟不太可能。你们对我真是太“热情”了。$B$B<瓦莉拉生气地咕哝着。>', `FemaleText_loc5`='我聽聞部落也正集結軍隊，前往北裂境。希望你的聯盟跟部落可以把注意力放在真正的威脅上。你知道，而不是彼此?$B$B不過我覺得這不太會發生，要是我在這裡的經驗可以提供些什麼建議的話。妳們這些人實在對我太好了。$B$B<瓦麗拉憤怒地自言自語。>', `FemaleText_loc7`='He oído que la Horda está reuniendo a su propio ejército para dirigirse a Rasganorte. CON SUERTE tu Alianza y la Horda podrán concentrar toda su agresividad en la amenaza real. Ya sabes, en lugar de unos contra otros.$B$BPero si mi experiencia me ha enseñado algo, es que eso es casi imposible que suceda. Los tuyos han sido TAN amables conmigo.$B$B<Valeera murmura enfadada para sí misma.>' WHERE `ID`=30392;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드의 머저리들아! 들어라! 한심한 얼라이언스 녀석들아! 몸서리쳐라! 종말이 다가왔음을 느껴라! 리치 왕이 너희를 응시하고 있음을 알아라!', `MaleText_loc4`='暴风城的蠢货们！无知的联盟臣民们！聆听我的审判吧！在恐惧中颤抖吧。巫妖王的双眼已经在凝视着你们。', `MaleText_loc5`='暴風城的蠢蛋!聯盟天真的孩子們，聆聽我的審判!顫抖著迎接你們的末日吧，因為巫妖王的凝視將降臨在你們身上!', `MaleText_loc7`='¡TONTOS DE VENTORMENTA!  ¡ÓIGANME, NIÑOS INGENUOS DE LA ALIANZA! ¡TIEMBLEN Y ENFRENTEN LA MUERTE, PUES LA MIRADA DEL REY EXÁNIME POSA SOBRE USTEDES!' WHERE `ID`=30393;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으아! 이 보잘것없는 승리엔 아무 의미도 없다! 오너라! 노스렌드로 오너라! 굶주린 내 부하들이 기꺼이 너희를 맞아 줄 것이다!', `MaleText_loc4`='啊！这个渺小的胜利不会改变你们的境地！来吧！到诺森德来吧！我的仆从们在等着你们，他们已经饥不可耐了……', `MaleText_loc5`='啊!這小小的勝利不能讓你們躲過什麼!來吧!來北裂境。我的爪牙等著你們，而且他們飢餓萬分...', `MaleText_loc7`='¡ARGH!  ¡ESTA INSIGNIFICANTE VICTORIA LES SERÁ EN VANO! ¡VENGAN!  ¡VENGAN A RASGANORTE!  MIS LACAYOS ESTÁN ESPERANDO, Y CON HAMBRE…' WHERE `ID`=30394;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투 준비! 항구를 지켜야 한다. 그렇지 않으면 우리 얼라이언스는 노스렌드를 공격하기도 전에 저지당하고 말 것이다!', `MaleText_loc4`='拿起武器！我们必须守住港口，否则联盟远征诺森德的计划就会提前流产！', `MaleText_loc5`='武裝!我們一定要防衛港口!不然聯盟對北裂境的進攻在開始前就要結束了!', `MaleText_loc7`='¡A las armas! ¡Defended el puerto o el asalto de la Alianza a Rasganorte terminará incluso antes de empezar!' WHERE `ID`=30395;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성난발톱 일족 자유다! 트롤은 다 죽었어!', `MaleText_loc4`='怒爪自由了！巨魔去死吧！', `MaleText_loc5`='釋放怒爪!食人妖去死!', `MaleText_loc7`='¡Garrafuria libre! ¡Trol morir ahora!' WHERE `ID`=30396;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='착한 울바르 씨는 이제 안녕이다!', `MaleText_loc4`='再也不会有狼獾人好好先生了！', `MaleText_loc5`='再也沒什麼好好獾狼怪了!', `MaleText_loc7`='¡Se acabo ser el lobo bueno!' WHERE `ID`=30397;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='풉, 트롤따윈 가소롭다!', `MaleText_loc4`='去死吧，巨魔！', `MaleText_loc5`='我要拉屎在你頭上，食人妖垃圾!', `MaleText_loc7`='¡Me hago caca sobre ustedes, trols!' WHERE `ID`=30398;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성난발톱 일족의 복수를 하겠다!', `MaleText_loc4`='为怒爪复仇！', `MaleText_loc5`='為怒爪復仇!', `MaleText_loc7`='¡Venganza para Garrafuria!' WHERE `ID`=30399;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아아으으으으으윽!', `MaleText_loc4`='啊啊啊啊！！！', `MaleText_loc5`='啊啊啊虜虜虜嘎嘎嘎!!!', `MaleText_loc7`='¡¡ARRRROOOOOGGGGAAAA!!' WHERE `ID`=30400;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전쟁이다!', `MaleText_loc4`='我要宣战！', `MaleText_loc5`='這意味戰爭!', `MaleText_loc7`='¡Esto es la guerra!' WHERE `ID`=30401;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발명가의 원반 사용 감지. 비상 체제 감마 작동 개시.', `MaleText_loc4`='检测到创世者的圆盘的用途。激活紧急协议。', `MaleText_loc5`='偵測到有人使用發明者圓盤。緊急伽瑪射線措施啟動。', `MaleText_loc7`='Detectado el uso del Disco del Inventor. Activado el protocolo de emergencia gamma.' WHERE `ID`=30402;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노르간논의 껍질 상태 확인 중...', `MaleText_loc4`='检验诺甘农之壳的状态。', `MaleText_loc5`='諾甘農之殼驗證中。', `MaleText_loc7`='Verificando el estado del caparazón de Norgannon.' WHERE `ID`=30403;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노르간논의 껍질 확인 및 검증. 사용자 신분이 확인되면 즉시 이전 작업을 진행할 수 있습니다.', `MaleText_loc4`='诺甘农之壳处于安全状态。核实用户身份后即可进行数据传输。', `MaleText_loc5`='諾甘農之殼設置完成並鎖定。當使用者身分確認時，就能立即傳送。', `MaleText_loc7`='Caparazón de Norgannon revisado y asegurado. Estará disponible para la transferencia una vez se haya verificado la identidad del usuario.' WHERE `ID`=30404;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='관리인 미미르, 신분 확인 준비 완료.', `MaleText_loc4`='准备核实守护者米米尔的身份。', `MaleText_loc5`='稍等，確認使用者是否是守護者彌米爾。', `MaleText_loc7`='Espere para verificar identidad del vigilante Mimir.' WHERE `ID`=30405;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신분 확인 실패. 이 사용자는 관리인 미미르가 아닙니다.', `MaleText_loc4`='身份核实失败。用户非守护者米米尔。', `MaleText_loc5`='身分驗證失敗。使用者不是守護者彌米爾。', `MaleText_loc7`='Verificación de identidad fallida. El usuario no es el vigilante Mimir.' WHERE `ID`=30406;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발명가의 원반이 권한 없는 사용자의 손에 들어갔습니다. 방어 체제 프로토콜 작동 개시.', `MaleText_loc4`='创世者的圆盘已落入非法用户手中。激活防御协议。', `MaleText_loc5`='發明者圓盤落入了未授權使用者的手中。啟動防衛機制。', `MaleText_loc7`='El Disco del Inventor ha caído en manos de un usuario no autorizado. Activando protocolo de defensa.' WHERE `ID`=30407;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사기꾼은 반드시 처리해야 합니다. 발명가의 원반도 되찾아야 합니다.', `MaleText_loc4`='消灭冒名顶替者。夺回创世者的圆盘。', `MaleText_loc5`='一定得處理盜用者。取回發明者圓盤。', `MaleText_loc7`='Hay que ocuparse del impostor. El Disco del Inventor debe ser recuperado.' WHERE `ID`=30408;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 쉽게 무릎 꿇는군!', `MaleText_loc4`='你们屈服得也太快了！', `MaleText_loc5`='你們也屈服得太快了!', `MaleText_loc7`='¡Abandonaste demasiado pronto!' WHERE `ID`=30409;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저런... 섭섭하겠구만...', `MaleText_loc4`='你们是否很失望呢？', `MaleText_loc5`='你們是否很失望呢?', `MaleText_loc7`='Qué desilusión.' WHERE `ID`=30410;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='운이 없구나. 이제부터 시작인데.', `MaleText_loc4`='真不幸。好戏还没开始呢。', `MaleText_loc5`='真不幸。好戲還沒開始呢。', `MaleText_loc7`='Mala suerte. Aún faltaba lo mejor.' WHERE `ID`=30411;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아나크 키리!', `MaleText_loc4`='Anakh kyree！', `MaleText_loc5`='(惡魔語)可悲的小蟲!', `MaleText_loc7`='¡Anakh kyree!' WHERE `ID`=30412;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='붉은돌격대가 리치 왕의 군대를 쓸어버릴 것이다!', `MaleText_loc4`='我的先锋军，将会荡平巫妖王的部队！', `MaleText_loc5`='我的突襲軍將會血洗巫妖王的部隊!', `MaleText_loc7`='¡Mi Ataque arrasará las fuerzas del Rey Exánime!' WHERE `ID`=30413;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헛된 죽음이로다, 필멸의 존재여.', `MaleText_loc4`='你的牺牲是徒劳的，渺小的凡人。', `MaleText_loc5`='你的死亡是無意義的，微弱的凡人。', `MaleText_loc7`='Tu muerte es en vano, diminuto mortal.' WHERE `ID`=30414;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너에게 주어진 시간은 끝났다.', `MaleText_loc4`='你的生命结束了。', `MaleText_loc5`='你的時間到了。', `MaleText_loc7`='Se te ha acabado el tiempo.' WHERE `ID`=30415;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간을 낭비하고 있군요. 가서 리치 왕의 부하를 하나라도 더 처치하십시오, $c님!', `MaleText_loc4`='别再浪费时间了。$c，消灭巫妖王的爪牙！', `MaleText_loc5`='你只是在浪費時間而已。去殺巫妖王的小兵，$c!', `MaleText_loc7`='Estás perdiendo el tiempo. ¡Ve a matar a los lacayos del Rey Exánime, $c!' WHERE `ID`=30416;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕을 상대로 싸우느라 얼마나 수고가 많으시오, $c?', `MaleText_loc4`='对抗巫妖王的战事有何进展，$c？', `MaleText_loc5`='你多努力對抗巫妖王，$c?', `MaleText_loc7`='¿Cómo te van las cosas contra el Rey Exánime, $c?' WHERE `ID`=30417;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 만나서 반갑소, $n. 내 여동생을 구해주신 분을 내가 어찌 잊을 수 있었겠소?', `MaleText_loc4`='先锋军将彻底消灭巫妖王的部队！', `MaleText_loc5`='真高興再見到你,$n。我怎麼會忘了救我妹妹一命的$g先生:小姐;呢?', `MaleText_loc7`='Me alegro de volver a verte, $n. ¿Cómo podría olvidar a la persona que salvó la vida de mi hermana?' WHERE `ID`=30418;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 다시 만나다니 너무 기쁘구려, $n.', `MaleText_loc4`='很高兴再见到你，$n。', `MaleText_loc5`='真高興再見到你,$n。', `MaleText_loc7`='Es estupendo volver a verte, $n.' WHERE `ID`=30419;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='괜찮으십니까? 당신을 서리요새로 데려가려고 왔습니다. 걸으실 수 있겠지요?', `MaleText_loc4`='你还好吧？如果你能站起来的话，我会送你返回冰霜堡。', `MaleText_loc5`='你還好吧?如果你還站得起來的話，我是來帶你回霜堡的。', `MaleText_loc7`='¿Estás bien? He venido a llevarte de vuelta a Fuerte Escarcha, si puedes aguantarlo.', `FemaleText_loc1`='괜찮으세요? 당신을 서리요새로 데려가려고 왔습니다. 걸으실 수 있겠지요?', `FemaleText_loc4`='你还好吧？如果你能站起来的话，我会送你返回冰霜堡。', `FemaleText_loc5`='你還好吧?如果你還站得起來的話，我是來帶你回霜堡的。', `FemaleText_loc7`='¿Estás bien? He venido a llevarte de vuelta a Fuerte Escarcha, si puedes aguantarlo.' WHERE `ID`=30420;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시스템 복구가 완료되었습니다. 정상 작동 중입니다!', `MaleText_loc4`='所有系统已上线，可以使用！', `MaleText_loc5`='所有系統皆上線，正常運作中。', `MaleText_loc7`='¡Todos los sistemas en línea y en funcionamiento!' WHERE `ID`=30421;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지령. 모형 조작대 수리.', `MaleText_loc4`='指令：修复原型机控制台。', `MaleText_loc5`='目標:修復原型控制臺。', `MaleText_loc7`='Directiva: reparar la consola prototipo.' WHERE `ID`=30422;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지령을 실행 중입니다!', `MaleText_loc4`='执行指令！', `MaleText_loc5`='下達目標!', `MaleText_loc7`='¡Implementando directiva!' WHERE `ID`=30423;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모형 조작대가 정상 작동 중입니다.', `MaleText_loc4`='原型机控制台已修复，恢复可用状态。', `MaleText_loc5`='原型控制臺已修復，正常運作中。', `MaleText_loc7`='Consola prototipo reparada y devuelta a estado funcional.' WHERE `ID`=30424;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='관리인 미미르의 지시를 기다립니다.', `MaleText_loc4`='等待守护者米米尔的下一步指令。', `MaleText_loc5`='等待守護者彌米爾下一步指示。', `MaleText_loc7`='Esperando más instrucciones del vigilante Mimir.' WHERE `ID`=30425;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전원이 공급되었습니다!', `MaleText_loc4`='充电！', `MaleText_loc5`='能量蓄集!', `MaleText_loc7`='¡Arrancando!' WHERE `ID`=30426;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<당신이 다가가자 일어나려고 애쓰다가, 심하게 다친 듯한 옆구리를 움켜쥐고 비틀거리며 땅에 다시 주저앉는 서릿결 정찰병>', `MaleText_loc4`='<当你靠近时，霜脉斥候试图站起来；但是他很快就跌倒在地，紧紧地捂住身体上那条明显的伤口。>', `MaleText_loc5`='<當你靠近時，霜誕斥候嘗試著站起來，但又跌回地面，緊抓著他明顯受傷的那一邊。>', `MaleText_loc7`='<El explorador Natoescarcha intenta ponerse en pie mientras te acercas, pero vuelve a caer al suelo mientras se agarra una herida sin duda dolorosa en el costado.>' WHERE `ID`=30427;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='못 갈 것 같네, 젊은이. 피를 너무 많이 흘렸어... 이미 돌아가긴 틀렸네.', `MaleText_loc4`='来不及了。我失血过多……坚持不了多久了。', `MaleText_loc5`='我不覺得我能辦得到，$G小夥子:小姑娘;。我失了太多的血...我沒辦法回去的。', `MaleText_loc7`='No pensaba que esto fuera a suceder, $gzagal:zagala;. He perdido mucha sangre... es imposible que pueda volver.' WHERE `ID`=30428;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 빨리 오지 못해 죄송합니다. 무슨 일을 당하신 겁니까?', `MaleText_loc4`='很抱歉，我来晚了。发生了什么事？', `MaleText_loc5`='我很抱歉來的太慢了。發生什麼事情?', `MaleText_loc7`='Lamento no haber llegado antes. ¿Qué ha pasado?', `FemaleText_loc1`='더 빨리 오지 못해 죄송합니다. 무슨 일을 당하신 거죠?', `FemaleText_loc4`='很抱歉，我来晚了。发生了什么事？', `FemaleText_loc5`='我很抱歉來的太慢了。發生什麼事情?', `FemaleText_loc7`='Lamento no haber llegado antes. ¿Qué ha pasado?' WHERE `ID`=30429;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계곡에서 하피 무리가 내려왔다네. 시라나라는 큰 하피 하나가 무리를 이끌고 있었지... 도망갈 곳이 없었다네. 하피 무리가 이렇게까지 공격적인 건 오랫동안 본 적이 없어... 그래서 방심했네... 제대로 몸을 지키지 않았어... 내가 잘못한 걸세.', `MaleText_loc4`='一群鹰身人突然冲出山谷。带领她们的是一只名叫希尔拉娜的鹰身人……我无路可逃。我不明白……她们为何变得如此具有攻击性……我放松了警惕……是我的失误。', `MaleText_loc5`='一群鷹身人從山谷裡出現。有一個叫做西拉納的大傢伙領著他們...我沒有地方可逃。他們很久都不這麼有侵略性了...我沒料到...我讓我的防衛鬆懈了...是我的錯。', `MaleText_loc7`='Una manada de arpías llegó desde el valle. Las lideraba una grande llamada Sirana... No tenía ningún lugar al que escapar. Hacía mucho tiempo que no eran agresivas... No me lo esperaba... Bajé la guardia... Ha sido culpa mía.' WHERE `ID`=30430;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누구든 더 데려오겠습니다. 잠시만 참으세요.', `MaleText_loc4`='我去求援。你待在原地别动。', `MaleText_loc5`='我去求救。撐著。', `MaleText_loc7`='Conseguiré ayuda. Aguanta.', `FemaleText_loc1`='누구든 더 데려올게요. 잠시만 참으세요.', `FemaleText_loc4`='我去求援。你待在原地别动。', `FemaleText_loc5`='我去求救。撐著。', `FemaleText_loc7`='Conseguiré algo de ayuda. Aguanta.' WHERE `ID`=30431;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='틀렸어... 이미 늦었다네... 젊은이.$B$B<기침을 하며 눈 위에 피를 토하는 서릿결 정찰병>$B$B무리를 이끄는... 그 큰 하피를... 없애 주게.$B$B<마지막으로 한 번 숨을 내쉬고는 푹 쓰러지는 서릿결 정찰병>', `MaleText_loc4`='没……没有用……太晚了。$B$B<霜脉斥候往雪地上咳出几口鲜血。>$B$B替我……报仇……$B$B<霜脉斥候咽下最后一口气，摊倒在地。>', `MaleText_loc5`='太...遲了...$G小夥子:小姑娘;。$B$B<霜誕斥候在雪上咳出一些血。>$B$B去...幫我把那個蕩婦抓來。$B$B<霜誕斥候斷了氣，頹然傾倒。>', `MaleText_loc7`='Es un poco tarde... para eso... $gmuchacho:muchacha;.$B$B<El explorador Natoescarcha tose algo de sangre sobre la nieve.>$B$BCoge... al joven que está al mando por mí.$B$B<El explorador Natoescarcha se desploma mientras exhala su último aliento.>' WHERE `ID`=30432;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주위를 둘러보고 그 황폐함을 가슴에 새겨라, $c. 여기 살던 트롤은 죄다 죽거나 저 위로 도망갔지.$B$B상황은 더 나빠지고 있어.$B$B절망에 빠진 드라카리 트롤 녀석들은 자신들이 섬기던 동물 신을 희생했지. 그 피를 마시고 신의 힘을 얻으려고 말이다. 그렇게 얻은 힘으로 녀석들은 스컬지의 진격을 가까스로 막아냈지만, 그 대가는 참담했다. 고대 제국 줄드락은 폐허로 변해 버리고 말았다.', `MaleText_loc4`='$c，环顾四周，将这破败的景象印在你的脑海中吧。居住在这里的巨魔不是死了就是逃到上层去了。$B$B局势越来越严峻了。$B$B陷入绝望的达卡莱巨魔杀害了氏族崇拜的动物之神，并饮下它们的鲜血来攫取难以言喻的力量。虽然他们凭借新的力量成功地牵制了天灾军团的攻势，却由此引发了灾难性的后果。沦为废墟的远古帝国祖达克就是最好的例证。', `MaleText_loc5`='看看周圍那些毀滅的痕跡，$c。住在這裡的每一隻食人妖不是死了，就是逃到更高的地方了。$B$B這讓情況變得更糟。$B$B出於絕望，這些活著的德拉克瑞食人妖獻祭了他們自己的動物神，讓他們能夠吮飲神的血液，獲得不知名的力量。當他們成功的以新力量在灣岸擊退天譴軍時，下場也非常災難。看看古老的祖爾德拉克帝國成了廢墟就知道了。', `MaleText_loc7`='Mira a tu alrededor y deja que la devastación cause su efecto, $c. Hasta el último trol que vivía aquí está muerto o ha huido a los niveles superiores.$B$BY solo empeora.$B$BEn un acto de desesperación, los trols Drakkari vivos sacrificaron a sus propios dioses animales para poder beber la sangre de los dioses y conseguir un poder increíble. Aunque tuvieron éxito al mantener a raya a la Plaga con su nueva fuerza, los resultados fueron catastróficos. La prueba es que el antiguo imperio de Zul''Drak yace en ruinas.' WHERE `ID`=30433;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='눈에 띄지 않게 조심하십시오. 알았습니까? 난 아직 리치 왕의 수하인 척하고 있단 말입니다!', `MaleText_loc4`='你千万不能败露自己的行踪。我要继续装出臣服于巫妖王的模样！', `MaleText_loc5`='離開我的視線，好嗎?我正在假裝我在巫妖王的控制之下!', `MaleText_loc7`='Aléjate un poco, ¿quieres? ¡Estoy intentando simular que sigo bajo el control del Rey Exánime!' WHERE `ID`=30434;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거의 다 된 건가?', `MaleText_loc4`='你好了吗？', `MaleText_loc5`='朋友，你好了吧?', `MaleText_loc7`='¿Ya has terminado, Dan?' WHERE `ID`=30435;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 돌아가서 란틴가 님께 이 장소에 대해 이야기해야 한다고. 서두르게!', `MaleText_loc4`='我们要回去找兰迪加，把这里的情况告诉他。快！', `MaleText_loc5`='我們得去回報蘭迪加，告訴他這個地方。快!', `MaleText_loc7`='Tenemos que volver con Lantinga y hablarle de este lugar. ¡Date prisa!' WHERE `ID`=30436;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 운전했더라면 이런 지경에 처하지는 않았을 텐데!', `MaleText_loc4`='如果让我来开坦克，事情就不会搞成现在这样了！', `MaleText_loc5`='你要是讓我開車，我們就不會弄得一團糟了!', `MaleText_loc7`='¡Si me hubieras dejado conducir a mí, no nos habríamos metido en este lío!' WHERE `ID`=30437;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 공격을 받으면 당해낼 수 없을 거라고. 여기서 빠져나가야 해!', `MaleText_loc4`='我们经不起再一轮的攻击了。快带我们离开这里！', `MaleText_loc5`='朋友，我們沒辦法撐過下一次攻擊了。你得把我們弄出去。', `MaleText_loc7`='Dan, no sobreviviremos a otro ataque. ¡Tienes que sacarnos de aquí!' WHERE `ID`=30438;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서둘러, 리드!', `MaleText_loc4`='快，里德！', `MaleText_loc5`='快點，雜魚!', `MaleText_loc7`='¡Date prisa, Carrizo!' WHERE `ID`=30439;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 바깥에서 우릴 노리는 놈들에 대해 생각해 보긴 했나? 그 수가 얼마나 많은지 알면 그렇게 굼뜨게 행동하지는 못할걸.', `MaleText_loc4`='你能数清楚这里有多少怪物想杀我们吗？我敢打赌，统计数字会让你大吃一惊。', `MaleText_loc5`='你自己想想，你能算出外面有多少東西想殺了我們嗎?我賭你一定會對結果驚訝的。', `MaleText_loc7`='¿Crees que podrías calcular cuántas cosas ahí fuera quieren matarnos? Apuesto a que te sorprenderías del resultado.' WHERE `ID`=30440;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 한 인간이 할 수 있는 한계까지 열심히 일하고 있다고. 방해나 하지 말게!', `MaleText_loc4`='我的速度已经达到极限了。别干扰我！', `MaleText_loc5`='我正在用人類的最大極限工作了，夥伴。別打擾我了!', `MaleText_loc7`='Estoy trabajando tan rápido como es humanamente posible, Pat. ¡Deja de interrumpirme!' WHERE `ID`=30441;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 운전했다면 상황이 좀 나았을 텐데. 여기 있는 대신 천국에 가 있을 테니까. 그리고 "은빛십자군의 영웅들, 증기 전차 사고로 사망"이란 신문기사가 났을 거라고.', `MaleText_loc4`='是啊，我相信如果让你来开坦克的话情况会好得多。比如我们直接就死在来这里的路上。我甚至能想象我们因此获得的头衔：“死于严重蒸汽坦克事故的银色北伐军英雄”。', `MaleText_loc5`='「我很確定要是你開車的話會比較好。因為我們可能在半路上就死於非命。我都能看到頭條了:『銀白十字軍的英雄死於致命的蒸氣坦克車禍。』」', `MaleText_loc7`='Estoy seguro de que las cosas habrían ido mucho mejor si hubieras conducido tú. Habríamos muerto de camino aquí. Ya puedo ver los titulares: "Héroes de la Cruzada Argenta mueren en un accidente fatal de tanque de vapor".' WHERE `ID`=30442;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이럴 때면 자네랑 내가 가장 친한 친구인 이유를 알 것 같다고. 어찌나 날 잘 격려해 주는지, 나 원!', `MaleText_loc4`='很多时候我都在想，为什么我们会成为好朋友呢。你总是在我的身边积极地鼓励我。', `MaleText_loc5`='就是這種時候我才會想起我們為啥是好朋友，夥伴。你總是充滿了正向光明的能量。', `MaleText_loc7`='En momentos como este es cuando recuerdo por qué somos tan amigos, Pat. Siempre estás lleno de ánimos y energía positiva.' WHERE `ID`=30443;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 그래. 최대한 느리게 작업해야겠군. 무시무시한 스컬지 녀석이 우릴 어떻게 죽이고, 시체는 어떻게 요리할지 맘 편히 고민할 수 있게 해 주려고 말이야. 그게 자네가 원하는 거 맞지?', `MaleText_loc4`='我就是打算尽可能地拖延时间，让那些不怀好意的天灾军团杀掉我们，然后对我们的尸体做一些可怕的事。我这样说你满意了吧？', `MaleText_loc5`='我的目標是工作的越慢越好，讓在這個地區有敵意的天譴軍有個大櫥窗，讓他們可以好好挑要殺哪個，然後對我們的屍體作可怕的事情。不就是這樣嗎?', `MaleText_loc7`='Mi objetivo es trabajar lo más despacio posible, dándoles a los numerosos Plaga de la zona tiempo suficiente para que se decidan a matarnos y hacerles cosas terribles a nuestros cadáveres. ¿No es ese el plan?' WHERE `ID`=30444;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐 나 대신 렌치를 들고 이 고물을 두들겨 보는 게 어때? 엉? 그럼 내가 지금 어떤 기분인지 알지도 모르지. 내 말 잘 들으라고. 이게 쉬운 줄 알아?!', `MaleText_loc4`='不如你用扳手来试试？这样你就会明白敲打这玩意儿是什么感觉！我告诉你，这件事不是那么容易的！', `MaleText_loc5`='也許你可以來用我的扳手，弄這該死的東西，嗯?那你就知道身為我這樣的人是怎樣的感覺了!我跟你說，不簡單呀!', `MaleText_loc7`='¡Quizás deberías venir a golpear a esta cosa con mi llave durante un rato! ¡Entonces sabrías lo que se siente al ser yo! ¡Déjame decirte que no es fácil!' WHERE `ID`=30445;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 또 입을 열어 날 도와주는구먼...', `MaleText_loc4`='如果你再罗嗦一句，我就……', `MaleText_loc5`='幫幫我，別再跟我講話啦...', `MaleText_loc7`='Cómo digas una palabra más sobre ayudarme...' WHERE `ID`=30446;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 다르가스 대신 널 잡아가지 않을 걸까? 왜? 왜? 도대체 왜?!', `MaleText_loc4`='为什么死的是达加斯而不是你？这是为什么！为什么！！', `MaleText_loc5`='為什麼他們不抓走你?為什麼他們抓走了達加希!為什麼!為什麼!為什麼!', `MaleText_loc7`='¿Por qué no se te han llevado a ti en lugar de a Dargath? ¡POR QUÉ! ¡POR QUÉ! ¡¿POR QUÉ?!' WHERE `ID`=30447;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 나 진짜 미칠 것 같다고. 제발 좀 그만해!', `MaleText_loc4`='你快把我避疯了！闭嘴！', `MaleText_loc5`='該弄點熱鬧了，夥伴。別阻止我!', `MaleText_loc7`='Pat, aquí arriba todo se va a volver loco. ¡No digas otra palabra!' WHERE `ID`=30448;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='게르크, 부르, 다르가스... 모두 가버렸어요. 멕켈라르와 저만 여기 남았지요. 당신이 뭔가 좋은 소식을 가져오신 거라면 좋겠군요.', `MaleText_loc4`='戈尔克、布尔和达加斯都死了……只有我和马克拉尔活了下来。希望你为我们带来了好消息。', `MaleText_loc5`='介爾克，孛爾，達加希都走了...這裡只剩我跟麥克凱拉。我希望你帶來的是好消息。', `MaleText_loc7`='Gerk, Burr, Dargath: todos se han ido... Solo quedamos MacKellar y yo. Espero que hayas traído algunas buenas noticias.' WHERE `ID`=30449;
