UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일을 망치던 게 네놈이었나? 이거 너무 쉽겠는걸.', `MaleText_loc4`='你就是那个捣乱的家伙？要对付你，真是易如反掌。', `MaleText_loc5`='你就是那個在搗亂的人?小事一樁嘛。', `MaleText_loc7`='¿Tú eres quien ha estado interrumpiendo todo? Esto debería ser fácil.' WHERE `ID`=30465;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈의 하찮은 졸개도 하나하나 남김없이 죽여 없애리라, 리치 왕이여!', `MaleText_loc4`='巫妖王，我要铲除你所有的走狗！', `MaleText_loc5`='我將會把你每個爪牙都殺掉，巫妖王!', `MaleText_loc7`='¡Mataré a todos tus peones, Rey Exánime!' WHERE `ID`=30466;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 떠다니는 요새나 타고 노스렌드로 꺼져라! 내가 맨손으로 박살 내 버리기 전에!', `MaleText_loc4`='带上你的飞行堡垒滚回诺德森去，否则我就徒手碾碎它们！', `MaleText_loc5`='在我空手把它們打爛以前，把你的飛行堡壘帶回北裂境去!', `MaleText_loc7`='¡Trae de vuelta a tu fortaleza volante a Rasganorte antes de que los aplaste con mis manos desnudas!' WHERE `ID`=30467;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정지. 수중에 핵이 있다면 조심스럽게 땅에 내려놓도록. 너를 제거할 때 손상을 입으면 안 되니 말이다.', `MaleText_loc4`='等等。如果你身上带着核心的话，请把它放在地上，避免在战斗过程中造成损伤。', `MaleText_loc5`='等等。要是核心在你們手上的話，請把它小心的放在地面上，以防在殲滅過程受到任何傷害。', `MaleText_loc7`='Alto. Si el núcleo está en tu poder, colócalo en el suelo con cuidado para evitar cualquier daño que pudiera sufrir durante tu eliminación.' WHERE `ID`=30468;
