UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='상자를 잘 처리하셨어요! 다음 임무를 알려 드릴 테니 스트라솔름 입구로 와서 제게 말을 거세요!', `FemaleText_loc4`='干得漂亮！到斯坦索姆的大门去，我会交给你下一项任务！', `FemaleText_loc5`='穀箱的事情幹得好!來斯坦索姆前面找我談談下個任務!', `FemaleText_loc7`='¡Buen trabajo con las cajas! ¡Ven a hablar conmigo delante de Stratholme para tu siguiente encargo!' WHERE `ID`=30509;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 가거라, 친구여. 더 좋은 상황에서 다시 만나길. 네가 날 위해 해준 일을 잊지 않겠다!', `MaleText_loc4`='再见。希望下次见面时，局势能好一些。我永远不会忘记你为我们所做的一切！', `MaleText_loc5`='珍重再見，朋友。希望我們能在更好的情況下再見。我不會忘記你幫了我什麼的。', `MaleText_loc7`='Hasta siempre, $gamigo mío:amiga mía;. Ojalá nos volvamos a ver en mejores circunstancias. ¡Jamás olvidaré lo que has hecho por mí!' WHERE `ID`=30510;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선택받은 알가르는 여기서 북동쪽으로 가면 나오는 고통의 성물함에 있다. 나바리우스 왕자가 있는 곳은 동쪽에 있는 죽음의 들판 반대쪽이다.', `MaleText_loc4`='天选者奥贾尔就在东北方的痛苦之匣。

纳瓦留斯王子在东边死亡旷野的远端。', `MaleText_loc5`='『天選』奧嘉爾在東北方的痛苦聖匣。

納法勒斯王子在東方的亡者原野上。', `MaleText_loc7`='Algar el Elegido está en el Relicario de Dolor al noreste.

El príncipe Navarius está al otro lado de los Campos Muertos al este.' WHERE `ID`=30511;
