UPDATE `locales_broadcast_text` SET `MaleText_loc1`='딤은 돌아가고만 싶다... 딤이 일을 끝내게 해줘, 멍청한 놀아.', `MaleText_loc4`='迪姆想回家……别再捣乱了，让迪姆做完手里的活。', `MaleText_loc5`='迪米只是想回去...讓迪米做完，笨豺狼人。', `MaleText_loc7`='Pazguato solo quiere volver... deja acabar a Pazguato, gnoll tonto.' WHERE `ID`=30519;
