UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠시 저와 함께 이 순간을 즐깁시다. 이제, 모든 게 밝혀질 거예요. 좋아요. 시작합시다!', `MaleText_loc4`='休息一会，然后和我一起来启动这个东西。一切……马上就要真相大白了。好了，我们开始吧！', `MaleText_loc5`='和我一起享受這時刻。一切...馬上就要真相大白了。好了，我們開始吧!', `MaleText_loc7`='Detente un momento y disfruta de esto conmigo. Pronto... todo será revelado. ¡De acuerdo, hagámoslo!' WHERE `ID`=30523;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해답을 찾을 시간입니다! 이제 가보자고요!', `MaleText_loc4`='是该收获答案了！让我们一路杀过去吧！', `MaleText_loc5`='是找出答案的時候了!讓好戲開演吧!', `MaleText_loc7`='¡Hora de conseguir respuestas! ¡Que empiece el espectáculo!' WHERE `ID`=30524;
