UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아요! 바로 그겁니다!', `MaleText_loc4`='抓紧，这边走这边走！', `MaleText_loc5`='加把勁;這樣才對嘛!', `MaleText_loc7`='¡Sigue adelante; así se hace!' WHERE `ID`=30526;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밀어붙이세요! 모두를 위해 잘하고 계십니다!', `MaleText_loc4`='抓紧，这边走这边走！', `MaleText_loc5`='加把勁;這樣才對嘛!', `MaleText_loc7`='¡Sigue adelante; así se hace!' WHERE `ID`=30527;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님과 마주하고 싶은 게냐? 그럼 먼저 폭풍을 이겨내라!', `MaleText_loc4`='你们想要挑战主人？先平息我的风暴吧！', `MaleText_loc5`='你們想要挑戰主人?先平息我的風暴吧!', `MaleText_loc7`='¿Deseas enfrentar al amo? ¡Primero debes salir con vida!' WHERE `ID`=30528;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파멸은 아주 자그만 불꽃에서 시작되지.', `MaleText_loc4`='这点轻微的花火，将带来你们的灭亡！', `MaleText_loc5`='這點輕微的花火，將帶來你們的滅亡!', `MaleText_loc7`='La mínima chispa causará tu perdición.' WHERE `ID`=30529;
