UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 충격이겠지.', `MaleText_loc4`='很震惊？我可以理解。', `MaleText_loc5`='很震驚?我可以理解。', `MaleText_loc7`='Espantoso, lo sé.' WHERE `ID`=30531;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불가능에 도전하는구나.', `MaleText_loc4`='你在尝试不可能做到的事！', `MaleText_loc5`='你在嘗試不可能做到的事。', `MaleText_loc7`='Intentas lo imposible.' WHERE `ID`=30532;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생명의 불꽃이... 사그라들었다.', `MaleText_loc4`='你的生命之火……就此熄灭了。', `MaleText_loc5`='你的生命之火...就此熄滅了。', `MaleText_loc7`='Tu chispa de vida... se ha apagado.' WHERE `ID`=30533;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님... 손님이 왔습니다.', `MaleText_loc4`='主人……您有客人了。', `MaleText_loc5`='主人...你有客人了。', `MaleText_loc7`='Amo... tienes invitados' WHERE `ID`=30534;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='희망이 있는 줄 아느냐? 꿈 깨라!', `MaleText_loc4`='你们还有什么希望可言？完全没有！', `MaleText_loc5`='你有希望嗎?沒有!', `MaleText_loc7`='¿Qué esperanzas tienes? ¡Ninguna!' WHERE `ID`=30535;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 수많은 제국의 흥망을 지켜보았다... 모든 종의 발생과 멸종을 목격했다... 아무리 강산이 바뀌어도, 필멸의 존재들은 항상 멍청했지. 너희가 여기 나타난 게 그 증거다.', `MaleText_loc4`='我曾见证过无数帝国的崛起与衰落……也见证过无数物种的诞生与灭绝……千百年来，凡人种族的愚蠢都不曾改变过。你们出现在这里，更是印证了这一点。', `MaleText_loc5`='我曾經見證過帝國的興亡衰落...物種的誕生與滅亡...在數不盡的千年之下，只有凡人的愚蠢是永恆的。你的出現驗證了此事。', `MaleText_loc7`='He visto surgir y caer imperios... nacer y extinguirse especies completas... Durante incontables milenios la insensatez de los mortales fue la única constante. Tu presencia aquí lo confirma.' WHERE `ID`=30536;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님께서 미래를 보여주셨다. 하지만 너희는 거기 없어! 아제로스는 어둠 속에서 다시 태어날 것이다. 요그사론이 풀려날 것이다! 판테온은 무너지리라!', `MaleText_loc4`='在主人为我展示的未来图景中，没有你们的位置。艾泽拉斯将在黑暗中获得新生。尤格-萨隆将获得自由，而万神殿，必将毁灭！', `MaleText_loc5`='我的主人曾經讓我看見未來，而裡面沒有你們的位置。艾澤拉斯將在黑暗中重生。尤格薩倫將被釋放。萬神殿終將隕落。', `MaleText_loc7`='Mi amo me ha mostrado el futuro, y tú no figuras en él. Azeroth renacerá en tinieblas. ¡Yogg-Saron será liberado! ¡Caerá el Panteón!' WHERE `ID`=30537;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='운명을 거부할 순 없다!', `MaleText_loc4`='你们无法逃避命运！', `MaleText_loc5`='你們無法逃避命運!', `MaleText_loc7`='¡No puedes evadir el destino!' WHERE `ID`=30538;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가까이 와라. 빨리 끝내주지.', `MaleText_loc4`='靠近点。我立刻送你们归天。', `MaleText_loc5`='靠近點。我立刻送你們歸天。', `MaleText_loc7`='Acércate. Lo haré rápido.' WHERE `ID`=30539;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연약한 몸뚱이로 얼마나 버틸까?', `MaleText_loc4`='你们的血肉之躯无法长存于世。', `MaleText_loc5`='你們這些血肉之軀終究撐不久。', `MaleText_loc7`='Tu cuerpo no puede resistir mucho más.' WHERE `ID`=30540;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미약한 존재여...', `MaleText_loc4`='区区凡人……', `MaleText_loc5`='區區凡人...', `MaleText_loc7`='Mero mortal…' WHERE `ID`=30541;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는... 불멸이다!', `MaleText_loc4`='我……就是永恒！', `MaleText_loc5`='我...就是永恆!', `MaleText_loc7`='Yo... soy... ¡ETERNO!' WHERE `ID`=30542;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살 날이 얼마나 남았다고 낭비하느냐!', `MaleText_loc4`='你们把短暂的生命全部浪费掉了！', `MaleText_loc5`='你們把短暫的生命全部浪費掉了!', `MaleText_loc7`='El poco tiempo que tenías, ¡lo desperdiciaste!' WHERE `ID`=30543;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나의 죽음은... 세상의 종말을 예고할 뿐이다.', `MaleText_loc4`='我的死亡……预示着世界的终结。', `MaleText_loc5`='我的死亡...預示了世界末日。', `MaleText_loc7`='Mi muerte... anuncia el fin de este mundo.' WHERE `ID`=30544;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나락을 향해 달리는 눈먼 자들이여!', `MaleText_loc4`='你们还不知道自己正在注视着无尽的深渊吗！', `MaleText_loc5`='你盲目地望向深淵!', `MaleText_loc7`='¡Contemplas el abismo a ciegas!' WHERE `ID`=30545;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무지함이 하늘을 찌르는구나. 이 길이 어디로 향하는지 모르겠느냐?', `MaleText_loc4`='你们太无知了。竟然看不清这条路通向何方吗？', `MaleText_loc5`='你太無知了。難道你看不出來這條路通往何方嗎?', `MaleText_loc7`='Eres demasiado ignorante. ¿No ves adónde conduce este camino?' WHERE `ID`=30546;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='결국은 파멸을 향해 치닫는구나!', `MaleText_loc4`='这条道路的尽头就是湮灭！', `MaleText_loc5`='你已經超越能夠赦免的極限了!', `MaleText_loc7`='¡Cruzas el precipicio del olvido!' WHERE `ID`=30547;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무쇠 드워프가 당신을 쫓아옵니다! 그물과 미끄러운 얼음을 사용해 달아나세요!', `MaleText_loc4`='铁矮人在追你！快使用结网和地面速冻逃跑！', `MaleText_loc5`='鐵矮人跟著你們!用網子跟結冰的地面逃走!', `MaleText_loc7`='¡Los enanos férreos te han seguido! Usa la red y la marea de hielo para escapar!' WHERE `ID`=30548;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼음이빨이 냄새의 근원지를 찾아냈습니다. 동굴을 수색하세요!', `MaleText_loc4`='霜齿已经追踪到了气味的源头。进入洞穴仔细搜查！', `MaleText_loc5`='霜齧聞到了氣味的來源。調查洞窟!', `MaleText_loc7`='Mordisquielo ha rastreado el olor hasta su fuente. ¡Investiga la cueva!' WHERE `ID`=30549;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 킁킁거리며 냄새의 흔적을 추적합니다.', `MaleText_loc4`='%s嗅着气味，寻找踪迹。', `MaleText_loc5`='%s到處聞聞，找到了蹤跡。', `MaleText_loc7`='%s olfatea y encuentra el rastro.' WHERE `ID`=30550;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 동굴 안에 냄새의 근원이 있음을 찾아냈습니다.', `MaleText_loc4`='%s循着气味找到了洞穴中的气味源头。', `MaleText_loc5`='%s找到了氣味的來源，就在洞窟裡。', `MaleText_loc7`='%s ha rastreado el olor hasta su fuente, dentro de la cueva.' WHERE `ID`=30551;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 잘 보시라고요! 제가 눈 깜짝할 사이에 정보를...', `MaleText_loc4`='嗯，你们帮我看着点外面。我这样的强者只要锤两下就能搞定这破烂……', `MaleText_loc5`='幫我看著外頭!我只要三兩下就可以搞定這玩意--', `MaleText_loc7`='¡Ahora ten cuidado! Me encargaré de esto en un abrir y cerrar de…' WHERE `ID`=30552;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이고, 좋은 소리 같진 않네요. 에... 문제가 한두 개 생길지도...', `MaleText_loc4`='噢，见鬼，好像有点不太妙，看来我们遇到点小麻烦啦……', `MaleText_loc5`='噢，聽起來真不妙。咱們可能碰上了一兩個小麻煩...', `MaleText_loc7`='Ah, eso no suena bien. Quizás tengamos un obstáculo o dos…' WHERE `ID`=30553;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='허허, 해보겠다는 거냐, 엉? 이쪽도 방법이 있지!', `MaleText_loc4`='嘿，破机器，怎么样？你想跟我来硬的？太可惜了，这是属于我的游戏！', `MaleText_loc5`='啊，你想玩硬的是嗎?嗯?這我可是太擅長了!', `MaleText_loc7`='¿Qué? ¿Deseas jugar duro? ¡Ese es mi estilo de juego!' WHERE `ID`=30554;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조금만 있으면 제가... 어, 어라?', `MaleText_loc4`='再给我几分钟，马上就能……啊噢……', `MaleText_loc5`='再幾分鐘我就--', `MaleText_loc7`='Un par de minutos más y te... Oh, oh…' WHERE `ID`=30555;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상승했다고? 좀 좋은 소식은 없나?', `MaleText_loc4`='提高？这算是好消息吗？', `MaleText_loc5`='提升?這算好消息嗎?', `MaleText_loc7`='¿Contento? ¿Cuáles son las buenas noticias? ' WHERE `ID`=30556;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 이게 문제였군! 이제 방법을 알았으니...', `MaleText_loc4`='哈！终于找到问题出在哪儿了！我马上就能搞定了……', `MaleText_loc5`='所以說問題在這囉!這下可有進展了...', `MaleText_loc7`='¡Así que ese era el problema! Ahora estoy mejorando…' WHERE `ID`=30557;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐! 내가 권한을 쥐고 있는데, 검증 따위 받을 것 같으냐!', `MaleText_loc4`='等等！你想清理谁啊！有我在，没门！', `MaleText_loc5`='等一下!只要我不准，你就別想清理掉任何人!', `MaleText_loc7`='¡Resiste! ¡Nadie saldrá limpio si puedo intervenir yo!' WHERE `ID`=30558;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 늙은이의 노련한 손길이 마침내 통하는군! 이제 이걸...', `MaleText_loc4`='哈！看来还是我这把老骨头厉害呀！然后再看看这里……', `MaleText_loc5`='哈!看來我的金手指還是寶刀未老!現在讓咱們繼續--', `MaleText_loc7`='¡Ah! ¡Los viejos dedos mágicos por fin triunfaron! Ahora pasemos a…' WHERE `ID`=30559;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소거? 안 돼, 안 돼, 안 돼... 어째서 이게... 아하, 이러면 되겠군!', `MaleText_loc4`='消除？不不不不……呀，我刚才搞到哪来着？啊哈！应该是这样！', `MaleText_loc5`='消除?不不不不...我剛剛--啊哈，這招應該行的通...', `MaleText_loc7`='¿Purga? No, no, no, no, no... dónde... ¡Ajá!, esto debería servir…' WHERE `ID`=30560;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해답을 찾을 시간입니다! 이제 가보자고요!', `MaleText_loc4`='是该收获答案了！让我们一路杀过去吧！', `MaleText_loc5`='是時候找出答案了!讓咱們上路表演吧!', `MaleText_loc7`='¡Es hora de buscar respuestas! ¡Pongámonos en marcha!' WHERE `ID`=30561;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='할 수 있는 건 다 하고 있습니다!', `MaleText_loc4`='我已经竭尽全力了！', `MaleText_loc5`='我已經竭盡全力了!', `MaleText_loc7`='¡Hago todo lo que puedo!' WHERE `ID`=30562;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛이 돌봐줄 겁니다!', `MaleText_loc4`='圣光会保佑你的！', `MaleText_loc5`='聖光會保佑你的!', `MaleText_loc7`='¡Que la Luz te guarde!' WHERE `ID`=30563;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무의미한 희생이 아니길 빕니다!', `MaleText_loc4`='希望这牺牲是值得的！', `MaleText_loc5`='希望這犧牲是值得的!', `MaleText_loc7`='¡Espero que esto valga la pena!' WHERE `ID`=30564;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='질문? 내가 여기 왜 왔겠나, 엉? 척 하면 딱 해야지!', `MaleText_loc4`='问询？要不你以为我来这干嘛？喝下午茶吗？少废话！', `MaleText_loc5`='查詢?不然你以為我來幹嘛，喝下午茶?快把秘密吐出來吧!', `MaleText_loc7`='¿Pregunta? ¿Para qué crees si no que estoy aquí? ¡Ya no queda ningún secreto!' WHERE `ID`=30565;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드워프가 어떻게 창조됐는지 얘기해 봐라! 처음부터 낱낱이!', `MaleText_loc4`='告诉我矮人是怎样演化出来的！从最初开始！', `MaleText_loc5`='告訴我矮人是怎麼來的，從頭開始講!', `MaleText_loc7`='Cuéntame cómo surgieron los enanos, ¡y que sea desde el principio!' WHERE `ID`=30566;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='됐어, 됐어. 세상 깊숙한 곳을 다듬게 하려고 창조주가 돌로 토석인을 만들었지? 그런데 부작용은 왜 생겼나? 모형 불안정화 어쩌고 하는 얘기 있잖나.', `MaleText_loc4`='对，对。我已经知道土灵是用石头创造出来，用以改造地下世界的。但变异是怎么发生的？我听说过什么母体扰动？', `MaleText_loc5`='對，對...我知道土靈是用石頭做的，用來塑造世界的地下深處。但是那個異常是怎麼回事?基質失序是什麼玩意的?', `MaleText_loc7`='Bien... Sé que los Earthen fueron creados de la piedra para formar las regiones profundas del mundo. Pero, ¿qué hay de las anomalías? ¿La desestabilización de la matriz y todo eso?' WHERE `ID`=30567;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기생성 뭐 어째? 공용어로 얘기해라! 엉?!', `MaleText_loc4`='寄生性噬主……什么来着？讲通用语会死吗？', `MaleText_loc5`='噬命什麼鬼呀--天殺的能不能講人話?', `MaleText_loc7`='¡Qué cosa! Habla en español, ¿sí?' WHERE `ID`=30568;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그게 싸우는 거냐? 인형은 이리 내라. 어쩌면 그게 네 녀석에게 칼 휘두르는 법을 가르쳐 줄지도 모르겠지만 말이다.', `MaleText_loc4`='你管这叫做战斗？我还是把你的布娃娃拿来吧。或许她能教会你怎么挥剑。', `MaleText_loc5`='你把那個當作戰鬥?讓我去找你的洋娃娃，說不定她可以教你如何扭屁屁。', `MaleText_loc7`='¿A eso lo llamas luchar? Déjame que vaya a por tus muñecas. Quizás ellas te puedan enseñar a golpear.' WHERE `ID`=30569;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌아가신 내 할머니.. 편안히 잠드신 그분의 영혼마저도 널 때려눕힐 수 있겠다!', `MaleText_loc4`='就连我去世的祖母……都能打倒你！噢，愿她的灵魂安息吧。', `MaleText_loc5`='我死掉的大師，願她安息，連她現在都可以打敗你!', `MaleText_loc7`='Mi abuela fallecida, descanse en paz, podría ganarte... ¡incluso ahora!' WHERE `ID`=30570;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 둘 다 지금 당장 처치해 버릴까 고민 중이다! 아니, 고민할 필요도 없겠군!', `MaleText_loc4`='我的左边脑袋劝我把你们俩就地解决了！我的右边脑袋对此毫无异议！', `MaleText_loc5`='我內心有一半想要把你們兩個當場砍死!另一半可是一點意見都沒有!', `MaleText_loc7`='¡La mitad de mi mente me dice que te parta en dos ahí mismo! ¡La otra no se opone!' WHERE `ID`=30571;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 아가씨들. 여기가 어디라고 생각하는 거지? 스코른?', `MaleText_loc4`='嗨，女士们。你们觉得……斯克恩代表着什么？', `MaleText_loc5`='嗯，你好，小姐們。你覺得這是...史考恩?', `MaleText_loc7`='Vaya, hola, señoritas. ¿Qué os creéis que es esto... Skorn?' WHERE `ID`=30572;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폐가 터질 것 같고 팔이 아려올 때까지 연습해라. 그러고 나면 진짜로 시작할 수 있겠지!', `MaleText_loc4`='我要你们一直练到腰酸背疼为止，然后才开始真正的训练！', `MaleText_loc5`='你得練習到你的肺像是要爆開，你的手臂像是被砍傷。這樣我們才算開始了。', `MaleText_loc7`='¡Practicarás hasta que te ardan los pulmones y te duelan los brazos y entonces empezaremos de verdad!' WHERE `ID`=30573;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발할라스에서 최고 중의 최고만이 이미르하임으로 가게 된다. 나머지는 전부 죽거나... 혹은 더 심한 꼴을 겪게 되지!', `MaleText_loc4`='只有精英中的精英才能进入瓦哈拉斯，前往伊米海姆。剩下的人都得死……甚至落得更加悲惨的结局！', `MaleText_loc5`='只有最好的人可以在英靈殿上得到去依米海姆的試驗。其他人都得死...或是更糟。', `MaleText_loc7`='Solo los mejores entre los mejores consiguen un intento en Valhalas para ir a Ymirheim. Todos los demás mueren... ¡o peor!' WHERE `ID`=30574;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='때리려고만 하지 말고 때리란 말이다!', `MaleText_loc4`='别光摆架势啊，上去给他一拳！', `MaleText_loc5`='別再嘗試打他，趕快打到他!', `MaleText_loc7`='¡Deja de intentar darle y DALE ya!' WHERE `ID`=30575;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 기분 나쁘게 하고 싶나 보군? 네 녀석이 오늘 잘하는 짓은 그것뿐인 듯한데!', `MaleText_loc4`='你想让我丢脸是吗？这就是你唯一的能耐！', `MaleText_loc5`='你是要讓我顏面無光嗎?這是你今天唯一成功的一件事!', `MaleText_loc7`='¿Intentas hacerme quedar mal? ¡Es lo único en lo que vas a tener éxito hoy!' WHERE `ID`=30576;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고대 신이라... 그들이 토석인에게 육체의 저주를 걸었단 말이지... 에... 그래서?', `MaleText_loc4`='上古之神是吧，也就是说他们给土灵施加了什么血肉的诅咒，然后怎么样了？', `MaleText_loc5`='上古之神，嗯?所以他們對土靈下了這什麼血肉詛咒...然後呢?', `MaleText_loc7`='Dioses Antiguos, ¿verdad? Con que eliminaron a los Earthen con esta Maldición de la Carne... ¿y después?' WHERE `ID`=30577;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고대 신들을 없앴다면, 아제로스는 산산조각났을 게야...', `MaleText_loc4`='如果他们真的杀光上古之神，那艾泽拉斯也就毁灭了……', `MaleText_loc5`='假如他們殺死上古之神，艾澤拉斯也會跟著毀滅...', `MaleText_loc7`='Si mataron a los Dioses Antiguos, Azeroth habría sido destruido…' WHERE `ID`=30578;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 수호자?', `MaleText_loc4`='什么守护者？', `MaleText_loc5`='什麼守衛者?', `MaleText_loc7`='¿Qué protectores?' WHERE `ID`=30579;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에시르와 바니르... 그래... 그래서 의지의 용광로로 새 토석인을 만들기 시작했다는 거군... 그럼 옛 토석인은 어찌 됐지?', `MaleText_loc4`='艾塞尔与瓦尼尔……好吧，这么说意志熔炉又从头开始创造了新的土灵……那老的怎么样了？', `MaleText_loc5`='華納神族和阿薩神族...很好，所以，意志熔爐開始製造新的土靈...那舊的呢?', `MaleText_loc7`='Aesir y Vanir... De acuerdo, entonces la Fábrica de Voluntades comenzó a crear nuevos Earthen... ¿pero qué fue de los anteriores?' WHERE `ID`=30580;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐, 잠깐! 에시르와 바니르가 전쟁을 했다고? 왜?', `MaleText_loc4`='等等！等等！你是说艾塞尔与瓦尼尔之间爆发了战争？为什么？', `MaleText_loc5`='暫停一下!華納神族和阿薩神族爆發了戰爭?為什麼?', `MaleText_loc7`='¡Espera! ¿Aesir y Vanir entraron en guerra? ¿Por qué?' WHERE `ID`=30581;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으으... 이 "로켄"이란 녀석, 아주 나쁜 놈 같군. 이제 내 이 녀석한테 신경 쓸 필요가 없어서 다행이야. 그래서... 내가 바로 이해했다면, 어떤 이유에서인지 원조 토석인이 이 정체 상태에서 벗어났고, 그때 그... 불안정환지 뭔지 때문에, 결국 지금의 드워프가 된 거지. 아니면, 드워프의 조상이 됐거나. 응?', `MaleText_loc4`='这个“洛肯”听起来真是阴险狡诈。还好不用再理会他了。那么……如果我的理解没有错，最初的原始土灵是否因为某种原因从休眠仓里苏醒了过来，还受了这个什么母体扰动的影响，最终演化成现代的矮人？至少……是现代矮人的祖先。', `MaleText_loc5`='這個「洛肯」聽起來可真像個壞蛋。幸好咱們不用再擔心這傢伙了。所以說...如果我沒搞錯的話，原始的土靈最終從封存中醒了過來，那時候這失序什麼玩意的已經將他們轉變成了矮人。或者說...是矮人的祖先。', `MaleText_loc7`='Este "Loken" parece un personaje feo. ¡Qué suerte que ya no tenemos que preocuparnos por tipos así! Entonces... si te entiendo bien, los Earthen originales finalmente despertaron de este letargo, y para entonces la desestab... bueno eso...  los había convertido en auténticos enanos. O al menos... sus antepasados.' WHERE `ID`=30582;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으음... 그래... 정말 대단한 얘기였어. 곰곰이 생각 좀 해봐야겠군. 고맙네.', `MaleText_loc4`='啊，现在我得花上很长时间来好好消化这些知识。我要在这里再待一会儿。谢谢你们。', `MaleText_loc5`='好吧...我得消化一下。我需要很多時間來把這些資訊通通整理好。謝謝你啊。', `MaleText_loc7`='Bueno... es mucho para digerir. Preciso algo de tiempo para asimilarlo todo. Gracias.' WHERE `ID`=30583;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용광로로 토석인을 한 무리 만들어내서 경비를 세우겠습니다. 하지만 가장 힘든 일이 남았어요. 로켄을 찾아서 저지하세요!', `MaleText_loc4`='我会用熔炉来制造一些土灵，让他们保卫这里……但现在最大的挑战是：找到并阻止洛肯！', `MaleText_loc5`='我會用熔爐製造一批土靈來防守...但咱們最大的挑戰依舊存在:找到洛肯並且阻止他!', `MaleText_loc7`='Con la fábrica crearé grupos de Earthen para hacer guardia... Pero nos queda nuestro mayor desafío: ¡encontrar y detener a Loken! ' WHERE `ID`=30584;
