UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맛있는 간식거리가 제 발로 찾아왔구나! 네 폭탄으로 널 구워줄까?', `MaleText_loc4`='美味的点心自己送上门来了呀！我能用炸弹把你烤熟吗？', `MaleText_loc5`='美味的小吃來我家!我可以用你的炸彈煮你嗎?', `MaleText_loc7`='¡Han venido a visitarme deliciosos bocaditos! ¿Uso tus bombas para cocinarte?' WHERE `ID`=30593;
