UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자유다!!! 이제 폭풍의 왕의 분노를 보여주마!', `MaleText_loc4`='我自由了！！！你很快就会感受到暴风之王的怒火！', `MaleText_loc5`='自由了!!!很快你就會嚐到風暴之王的憤怒!', `MaleText_loc7`='¡¡LIBRE!! ¡Pronto sentiréis la ira del rey de la tormenta!' WHERE `ID`=30599;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와우! 저런... 저런 건 한 번도 본 적이 없습니다! 스컬지에게 지옥을 보여 주세요, $n 님!', `MaleText_loc4`='哇！我……我从来没见过这样的家伙！让他们去死吧，$n！', `MaleText_loc5`='哇喔!我...我從來沒有看過像他這樣的東西!給他死，$n!', `MaleText_loc7`='¡GUAU! Yo... ¡yo nunca había visto algo como él! ¡Dale caña, $n!' WHERE `ID`=30600;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스컬지는 이제 끝장이 났군요!', `MaleText_loc4`='天灾军团没有机会获胜！', `MaleText_loc5`='天譴軍沒機會的!', `MaleText_loc7`='¡La plaga no tiene ninguna oportunidad!' WHERE `ID`=30601;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불태우기', `MaleText_loc4`='燃烧', `MaleText_loc5`='燃燒中', `MaleText_loc7`='Quemando', `FemaleText_loc1`='불태우기', `FemaleText_loc4`='燃烧', `FemaleText_loc5`='燃燒中', `FemaleText_loc7`='Quemando' WHERE `ID`=30602;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='검색 중... 창조주들은 기생 감염체를 적출하기로 했습니다. 그러나 검사 결과, 고대 신 증후군이 악성으로 진전했음이 밝혀졌습니다. 기생체를 제거하면 숙주의 생명 활동도,', `FemaleText_loc4`='正在检索……造物主曾经亲自回来清除噬主共体生物所造成的感染。根据当时的评估，上古之神滋生所造成的危害非常严重。强行分离被感染部分将导致宿主损毁——', `FemaleText_loc5`='檢索中...創造者抵達以滅絕共生感染。測量結果顯示上古諸神感染已轉變為惡性。消滅寄生體將導致宿主死亡--', `FemaleText_loc7`='Accediendo... Los Creadores llegaron para destruir la infección simbiótica. Se ha descubierto que la infección de los Dioses Antiguos se había vuelto maligna. Eliminar los parásitos haría perder el portador…' WHERE `ID`=30603;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그렇습니다. 창조주들은 기생체를 제압한 다음, 숙주 안에 그대로 남겨 두었습니다. 또한 의지의 용광로를 비롯한 여러 시스템으로 새 토석인을 만드는 작업을 시작했습니다. 보호 대책이 마련되었으며, 수호자가 지정되었습니다.', `FemaleText_loc4`='正确。造物主决定中和寄生体的威胁，并将其封锁在宿主内部。之后，包括意志熔炉在内的各系统受命开始创造新的土灵。植入了新的安全机制，并任命了守护者。', `FemaleText_loc5`='正確。創造者消滅寄生威脅，將其限制於寄主身上。意志熔爐與其他系統受命創造新土靈。設置警衛，指派守衛者。', `FemaleText_loc7`='Correcto. Los Creadores neutralizaron la amenaza parasitaria y la contuvieron en el portador. La Fábrica de Voluntades y otros sistemas nacieron para crear nuevos Earthen. Se aplicaron medidas de seguridad y se nombraron protectores. ' WHERE `ID`=30604;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지시어. 에시르와 바니르. 일반적인 용어로 폭풍과 대지의 거인이라고 합니다. 로켄이 제1관리자로 지정되었으며, 용의 위상들은 아제로스의 진화를 주시하는 역할을 맡았습니다.', `FemaleText_loc4`='名称：艾塞尔与瓦尼尔。如果用通用语命名，则是风暴巨人与岩石巨人，最高领袖为哨兵洛肯。守护巨龙受命监管艾泽拉斯世界的进化过程。', `FemaleText_loc5`='稱謂:華納神族和阿薩神族。通用名稱為風暴巨人和大地巨人。監控者洛肯設定為至高者。守護巨龍被指派負責監控艾澤拉斯的演化情況。', `FemaleText_loc7`='Denominaciones: Aesir y Vanir. O, en términos comunes, los gigantes de la tormenta y de la tierra. Centinela Loken elegido supremo. Aspectos Dragones encomendados a seguir la evolución de Azeroth.' WHERE `ID`=30605;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그에 대한 대답에는 추가적인 배경 지식이 필요합니다. 에시르와 바니르의 대대적인 전쟁은,', `FemaleText_loc4`='另有后台信息与你的问询关联：在艾塞尔和瓦尼尔的全面战争之后——', `FemaleText_loc5`='查詢額外關連背景:隨著華納神族跟阿薩神族間的全面戰鬥--', `FemaleText_loc7`='La pregunta requiere más información complementaria: tras el combate global entre Aesir y Vanir…' WHERE `ID`=30606;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='원인 불명. 자료에 따르면 전쟁은 제1관리자인 로켄이 유발했다고 추정됩니다. 이 분쟁은, 남아 있던 에시르와 바니르를 로켄이 모두 제압함으로써 끝이 났습니다. 그 후 제1관리자 로켄은 지정된 관리 시설을 조작해, 토석인, 거인, 브리쿨 등 여러 원시 종족이 정체되도록 했습니다.', `FemaleText_loc4`='不详。数据显示，全面战争是由首席管理官洛肯发起的，他在此之后中和了所有残余的艾塞尔与瓦尼尔，结束了冲突。接着，他停止了包括土灵、巨人和维库人在内的数个源种生物的演化进程，并将他们全部封存在指定的封存仓内。', `FemaleText_loc5`='不詳。數據顯示，全面戰爭是由首席管理官洛肯發起，他消滅了所有殘餘的華納神族和阿薩神族，並結束了衝突。接著，首席管理官洛肯終止了土靈、巨人和維酷人等數個原種生物的演化，並將他們封存在指定設施中。', `FemaleText_loc7`='Desconocido. Se sabe que el impulso por el combate global se inició con Loken, el primer elegido, que neutralizó a todos los Aesir y Vanir sobrevivientes, afectando el final del conflicto. Luego inicio el letargo de varias razas simientes como los Earthen, los Gigantes y los Vrykul en depósitos para tal fin.' WHERE `ID`=30607;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그렇다고 할 수 있습니다.', `FemaleText_loc4`='本质上的确如此。', `FemaleText_loc5`='本質上的確如此。', `FemaleText_loc7`='Básicamente, es correcto.' WHERE `ID`=30608;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자유를 찾으면 폭풍의 복수가 어떤 건지 보여 주겠다!', `MaleText_loc4`='我自由了，暴风的复仇将随之而来！', `MaleText_loc5`='伴隨我自由而來的是復仇的狂風!', `MaleText_loc7`='¡Con mi libertad llega una tormenta de venganza!' WHERE `ID`=30609;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시작하기 전에 적에 대해 이야기를 들어라. 저기 나가서 스컬지를 밟아줄 때 정신없는 상태로 있고 싶진 않겠지?', `MaleText_loc4`='开战之前，我会向你介绍敌人的情况。听仔细了，要对付天灾军团，必须做好充分的准备。', `MaleText_loc5`='在我們開始以前，我得先告訴你敵人的資訊。當我們在外頭打擊天譴軍時，你不想毫無準備吧。', `MaleText_loc7`='Escucha lo que tengo que contarte sobre nuestro enemigo antes de que empecemos. Querrás estar $gpreparado:preparada; cuando estemos machacando a la Plaga, ¿verdad?' WHERE `ID`=30610;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선사 자료 검색 중... 완료. 최초에 토석인이 창조된 이유는,', `MaleText_loc4`='正在检索史前数据……文档定位完毕。创世之初，土灵的使命是——', `MaleText_loc5`='檢索上古資料...已取得。初始時，土靈被創造出來是為了--', `MaleText_loc7`='Búsqueda de datos prehistóricos... encontrados. Al principio los Earthen fueron creados para…' WHERE `ID`=30611;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검색 중... 아제로스는 초기 발전 단계에서 기생성 숙주 잠식 공생체에 감염되어 질환을 앓았습니다.', `MaleText_loc4`='正在检索……在其发展周期的初始阶段，艾泽拉斯世界遭受到了寄生性噬主共体生物的感染。', `MaleText_loc5`='檢索中...在初始創造階段的演化循環中，艾澤拉斯遭受寄生性死靈宿體的侵擾。', `MaleText_loc7`='Accediendo... A comienzos de su ciclo de desarrollo, Azeroth fue infectado por simbiontes necrofóticos parasitarios.' WHERE `ID`=30612;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지시어. 고대 신. 고대 신들은 동화 작업을 용이하게 할 목적으로, 토석인을 포함한 모든 생명체에 무력화 작업을 수행했습니다. 이 모형 불안정화 작업을 "육체의 저주"라고 부릅니다. 불안정화 작업의 효과는 시간이 지날수록 증대되었습니다.', `MaleText_loc4`='名称：上古之神。上古之神感染了包括土灵在内的整个毫无防备的系统，意图将所有事物向他们自身同化。这种扰动母体结构的行为与现象被定义为“血肉诅咒”。扰动的效果与日俱增。', `MaleText_loc5`='「稱號:上古諸神。上古諸神感染了土靈在內整個毫無防禦的系統。這種母體結構失序的情況被稱為『血肉詛咒』。而這失序的情形與日俱增。」', `MaleText_loc7`='Denominación: Dioses Antiguos. Estos dejaron indefensos a todos los grupos, hasta los Earthen, para facilitar la asimilación. Esta desestabilización de la matriz se denominó "la Maldición de la Carne". Sus efectos empeoraron con el tiempo.' WHERE `ID`=30613;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠습니다, 브란브론짱 님. 열람을 종료합니다.', `MaleText_loc4`='收到，布莱恩布隆赞。进程终止。', `MaleText_loc5`='確認，布萊恩布朗贊。程序終結。', `MaleText_loc7`='Comprendido, Branbronzan. Sesión finalizada.' WHERE `ID`=30614;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자이머, 알가르와 나바리우스, 스림은 어디에 있습니까?', `MaleText_loc4`='盖米尔，奥贾尔、纳瓦留斯和塞穆在哪儿？', `MaleText_loc5`='基默，奧嘉爾、納法勒斯、瑟瑞姆在何處?', `MaleText_loc7`='Gymer, ¿dónde están Algar, Navarius y Thrym?', `FemaleText_loc1`='자이머, 알가르와 나바리우스, 스림은 어디에 있나요?', `FemaleText_loc4`='盖米尔，奥贾尔、纳瓦留斯和塞穆在哪儿？', `FemaleText_loc5`='基默，奧嘉爾、納法勒斯、瑟瑞姆在何處?', `FemaleText_loc7`='Gymer, ¿dónde están Algar, Navarius y Thrym?' WHERE `ID`=30615;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자이머, 뭔가 조언해 줄 건 없습니까? 거인을 타는 건 처음이라서요.', `MaleText_loc4`='盖米尔，我要注意些什么？我从来没有骑过巨人。', `MaleText_loc5`='基默，我還需要知道些什麼?我從來沒支配過巨人。', `MaleText_loc7`='Gymer, ¿qué necesito saber? Nunca he montado en un gigante.', `FemaleText_loc1`='자이머, 뭔가 조언해 줄 건 없나요? 거인을 타는 건 처음이라서요.', `FemaleText_loc4`='盖米尔，我要注意些什么？我从来没有骑过巨人。', `FemaleText_loc5`='基默，我還需要知道些什麼?我從來沒支配過巨人。', `FemaleText_loc7`='Gymer, ¿qué necesito saber? Nunca he montado en un gigante.' WHERE `ID`=30616;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비됐습니다, 자이머. 갑시다!', `MaleText_loc4`='我准备好了，盖米尔。我们走吧！', `MaleText_loc5`='我準備好了，基默，出發吧!', `MaleText_loc7`='Estoy listo, Gymer. ¡Vamos!', `FemaleText_loc1`='준비됐어요, 자이머. 갑시다!', `FemaleText_loc4`='我准备好了，盖米尔。我们走吧！', `FemaleText_loc5`='我準備好了，基默，出發吧!', `FemaleText_loc7`='Estoy lista, Gymer. ¡Vamos!' WHERE `ID`=30617;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<기대에 찬 눈빛으로 당신을 쳐다보는 브란>', `MaleText_loc4`='<布莱恩满怀期待地看着你。>', `MaleText_loc5`='<布萊恩殷切的看著你。>', `MaleText_loc7`='<Brann te mira expectante.>' WHERE `ID`=30618;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='울두아르 안에 숨겨진 그 모든 지혜와 지식을 생각해 보십시오. 생명의 비밀이 바로 그 안에 있습니다!', `MaleText_loc4`='你能想象吗？奥杜尔中埋藏着所有的智慧与知识，甚至还有生命本身的秘密！', `MaleText_loc5`='想像看看，那些鎖在奧杜亞裡的知識與智慧。生命的最終秘密可能就藏在那裡!', `MaleText_loc7`='Imagina todo el conocimiento y sabiduría que hay encerrados en Ulduar. ¡Allí podrían estar los mismos secretos de la vida!' WHERE `ID`=30619;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하신가요.', `MaleText_loc4`='你好。', `MaleText_loc5`='日安。', `MaleText_loc7`='Saludos.' WHERE `ID`=30620;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 말을 이해하시겠습니까? 이젠 서로 알아들을 수 있을 것 같습니다만.', `MaleText_loc4`='你能听懂我的话吗？现在，我们应该能沟通了吧。', `MaleText_loc5`='你懂我在說什麼嗎?我們現在應該可以瞭解彼此在說什麼了。', `MaleText_loc7`='¿Me entiendes? Ahora deberíamos poder entendernos.', `FemaleText_loc1`='제 말을 이해하시겠어요? 이젠 서로 알아들을 수 있을 것 같습니다만.', `FemaleText_loc4`='你能听懂我的话吗？现在，我们应该能沟通了吧。', `FemaleText_loc5`='你懂我在說什麼嗎?我們現在應該可以瞭解彼此在說什麼了。', `FemaleText_loc7`='¿Me entiendes? Ahora deberíamos poder entendernos.' WHERE `ID`=30621;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탐험가 연맹에서 사람을 보냈는지 어떤지는 모르겠습니다. 저는 단지 무쇠 드워프가 점령한 야영지에서 당신의 쪽지를 발견했을 뿐입니다.', `MaleText_loc4`='探险者协会真的派出了其他探员？我一个也没见着。我在一座被铁矮人攻占的营地里发现了你的日记。', `MaleText_loc5`='要是探險者協會有派人來的話，我可沒有看到他們的蹤跡。我在被鐵矮人蹂躪過的營地裡發現你埋的字條。', `MaleText_loc7`='Si la Liga de Expedicionarios mandó hombres, no he visto rastro alguno de ellos. Encontré tu nota enterrada en un campamento arrasado por enanos férreos.', `FemaleText_loc1`='탐험가 연맹에서 사람을 보냈는지 어떤지는 모르겠습니다. 저는 단지 무쇠 드워프가 점령한 야영지에서 당신의 쪽지를 발견했을 뿐입니다.', `FemaleText_loc4`='探险者协会真的派出了其他探员？我一个也没见着。我在一座被铁矮人攻占的营地里发现了你的日记。', `FemaleText_loc5`='要是探險者協會有派人來的話，我可沒有看到他們的蹤跡。我在被鐵矮人蹂躪過的營地裡發現你埋的字條。', `FemaleText_loc7`='Si la Liga de Expedicionarios mandó hombres, no he visto rastro alguno de ellos. Encontré tu nota enterrada en un campamento arrasado por enanos férreos.' WHERE `ID`=30622;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 척후병이 토르 모단에서 당신의 일지를 발견했습니다. 이후로 호드는 계속 당신을 찾고 있었지요.', `MaleText_loc4`='有个斥候在索尔莫丹发现了这本日记的剩余部分。从那时起，我们就开始寻找你的下落了。', `MaleText_loc5`='一個斥候在鐸爾莫丹發現你日記的殘篇，自從那時我們就在找你了。', `MaleText_loc7`='Un explorador encontró los restos de tu diario en Thor Modan. Te llevamos buscando desde entonces.', `FemaleText_loc1`='한 척후병이 토르 모단에서 당신의 일지를 발견했습니다. 이후로 호드는 계속 당신을 찾고 있었지요.', `FemaleText_loc4`='有个斥候在索尔莫丹发现了这本日记的剩余部分。从那时起，我们就开始寻找你的下落了。', `FemaleText_loc5`='一個斥候在鐸爾莫丹發現你日記的殘篇，自從那時我們就在找你了。', `FemaleText_loc7`='Un explorador encontró los restos de tu diario en Thor Modan. Te llevamos buscando desde entonces.' WHERE `ID`=30623;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오... 무슨 말인지 이해하겠습니다! 이제 정말 대화를 나눌 수 있겠군요. 제게 설명해 주셔야 할 일이 있습니다!', `MaleText_loc4`='我……我能听懂！呃，既然我们能够对话，那么我想听听你的解释！', `MaleText_loc5`='我...我聽的懂了!嗯，現在我們終於可以跟彼此講話了，你得解釋一些事情。', `MaleText_loc7`='Yo... ¡ahora puedo entenderte! Bueno, ahora que podemos hablar, ¡tienes que explicar algunas cosas!' WHERE `ID`=30624;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 탐험가 연맹에서 제 통신기를 구한 거지요?', `MaleText_loc4`='你是怎么从探险者协会那里拿到我的联络器的？', `MaleText_loc5`='你怎麼從探險者協會拿到我的通訊器的?', `MaleText_loc7`='¿Cómo encontraste mi comunicador de la Liga de Expedicionarios?' WHERE `ID`=30625;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무쇠 드워프를 손봐 주셨나 보군요. 감사합니다. 하지만, 왜 호드가 제게 관심을 두는 거지요?', `MaleText_loc4`='你解决了铁矮人，我很感谢你。但是部落为什么会对我感兴趣？', `MaleText_loc5`='對於驅退鐵矮人這件事情，我衷心的感謝你。但部落對我有什麼興趣?', `MaleText_loc7`='Te agradezco que te hayas encargado de los enanos férreos. Pero, ¿por qué tiene interés la Horda en mí?' WHERE `ID`=30626;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 척후병이 설마 보르타크는 아니겠지요? 그가 무자비하다는 소문은 저 같은 사람도 들어 봤다고요. 그가 저를 붙잡으려고 하나요?', `MaleText_loc4`='该不会是斥候沃塔肯吧？连我都听说过他冷酷无情的名头。所以他是打算绑架我的吧？', `MaleText_loc5`='不會是斥候沃塔克吧，是嗎?即使我知道他惡名昭彰。他要來綁架我，對吧?', `MaleText_loc7`='Ese no sería el explorador Vor''takh, ¿verdad? Incluso yo conozco su reputación de despiadado. ¿Entonces quiere secuestrarme?' WHERE `ID`=30627;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일지를 보셨다면, 제가 어떤 작업에 매달려 왔는지 아실 텐데요. 우리는 서로 칼을 겨누고 있지만, 둘 다 티탄의 창조물입니다!', `MaleText_loc4`='如果你看过日记，就该知道我发现了什么。泰坦的造物正在自相残杀！', `MaleText_loc5`='要是你看過我的日記，那你應該知道我在找什麼。泰坦所造的東西正在互相征戰呢!', `MaleText_loc7`='Si has visto el diario, ya sabes lo que he descubierto. ¡Las creaciones de los titanes están en guerra unas contra otras!' WHERE `ID`=30628;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로켄과 무쇠 드워프들이 토석인을 내쫓고 울두아르를 차지했습니다.', `MaleText_loc4`='洛肯和他的铁矮人已经将土灵逐出了奥杜尔，并占领了这座城市。', `MaleText_loc5`='洛肯與他的鐵矮人驅逐了奧杜亞的土靈，接管了城市。', `MaleText_loc7`='Loken y sus esbirros enanos férreos han expulsado a los terráneos de Ulduar y han tomado la ciudad.' WHERE `ID`=30629;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 계속 서로 싸우는 데 힘을 소비하면, 로켄이 울두아르의 자원을 이용해 호드와 얼라이언스 둘 다를 무너뜨릴 겁니다.', `MaleText_loc4`='如果我们继续厮杀，洛肯就会利用奥杜尔的资源将联盟和部落一起摧毁。', `MaleText_loc5`='要是我們把時間跟精力都花在對抗彼此身上。洛肯會利用奧杜亞的資源一舉毀滅部落與聯盟。', `MaleText_loc7`='Si perdemos el tiempo y nuestra fuerza luchando uno contra el otro, Loken usará los recursos de Ulduar para destruir a la Horda y la Alianza.' WHERE `ID`=30630;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신네 기지로 돌아가 사령관에게 이야기하세요. 보르타크의 멍청한 계획은 잊으라고 설득하시라고요.', `MaleText_loc4`='去和指挥官谈谈，劝他放弃沃塔肯的愚蠢计划吧。', `MaleText_loc5`='去跟你哨站的指揮官談話， $g小子:女孩;，然後說服他放棄沃塔克的愚蠢計畫。', `MaleText_loc7`='$GMuchacho:Muchacha;, habla con el comandante de tu puesto, y convéncelo para que abandone el estúpido plan de Vor''takh.' WHERE `ID`=30631;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='복타르는 이 추락이 불운한 사건이라고 생각하지만, 저는 이 사건으로 우리가 무언가 배우게 될 거라고 믿습니다.', `MaleText_loc4`='伯克塔认为坠机事故只是一次倒霉的经历，但是我相信我们可以从中学到点什么。', `MaleText_loc5`='博克塔覺得這次墜毀是個不幸的意外，但我相信我們應該可以從中學到些什麼。', `MaleText_loc7`='Boktar cree que este accidente ha sido mala suerte, pero yo creo que se supone que debemos aprender algo de ello.' WHERE `ID`=30632;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투대장 이미야르, 선택받은 알가르가 이 감옥 북동쪽에 있는 고통의 성물함에서 바르굴 군대를 이끌고 봉기했다.$B$B나바리우스 왕자는 여기서 동쪽에 있는 죽음의 들판 건너편에 있다. 줄드락 2층으로 올라가는 커다란 계단 근처이다.$B$B스림이 있는 곳은 아직은 파악되지 않았다. 그 덩치를 고려한다면 의아한 일이지.$B$B이 모두 다 처리해야 할 일이다!', `MaleText_loc4`='伊米亚的战争领主，天选者奥贾尔就在东北方的痛苦之匣，准备唤醒他的瓦古大军。$B$B跨越东边的死亡旷野，你可以在通往祖达克第二层的阶梯附近找到纳瓦留斯王子。$B$B塞穆不知所踪，从体型来看，他是很难藏匿的。$B$B必须将他们统统解决！', `MaleText_loc5`='依米亞的戰鬥統帥，『天選』奧嘉爾，帶領著他的瓦苟軍團在痛苦聖匣揮軍起義，就在這個牢籠的東北方。$B$B納法勒斯王子穿越了方的亡者原野，就在通往祖爾德拉克第二層的巨大階梯旁。瑟瑞姆的位置還不知道，但是以他的體型來說蠻奇怪的。$B$B你得處理掉他們三個。', `MaleText_loc7`='El Señor de batalla Ymirjar, Algar el Elegido reúne a sus ejércitos de vargul en el Relicario de Dolor, al noreste de esta jaula.$B$BEl príncipe Navarius está al otro lado de los Campos Muertos, al este de aquí, cerca de los grandes escalones que llevan al segundo nivel de Zul''Drak.$B$BNo se conoce la posición actual de Thrym, algo curioso teniendo en cuenta su tamaño.$B$B¡Hay que ocuparse de todos!' WHERE `ID`=30633;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='질문이 몇 개 더 있습니다, 자이머.', `MaleText_loc4`='我还有几个问题，盖米尔。', `MaleText_loc5`='我還有幾個問題，基默。', `MaleText_loc7`='Tengo algunas preguntas más, Gymer.', `FemaleText_loc1`='질문이 몇 개 더 있어요, 자이머.', `FemaleText_loc4`='我还有几个问题，盖米尔。', `FemaleText_loc5`='我還有幾個問題，基默。', `FemaleText_loc7`='Tengo algunas preguntas más, Gymer.' WHERE `ID`=30634;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='약해! 할머니 같구나!', `MaleText_loc4`='你像老太婆一样虚弱！', `MaleText_loc5`='你太虛弱了，老妖婆!', `MaleText_loc7`='¡Eres débil, anciana!' WHERE `ID`=30635;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음의 여신이 널 데려갈 걸!', `MaleText_loc4`='见鬼去吧！', `MaleText_loc5`='抓到你了!', `MaleText_loc7`='¡Hela te lleve!' WHERE `ID`=30636;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 밤 내가 이미르하임에서 신나게 먹고 마시는 동안, 넌 내게 벌꿀술을 따라 주고 있을 게다!', `MaleText_loc4`='今晚我要出席伊米海姆的宴会，而你只配为我倒酒。', `MaleText_loc5`='有朝一日，我將在依米海姆的殿堂上盛宴，而你，將為我斟酒。', `MaleText_loc7`='Hoy tendré un festín en los salones de Ymirheim y tú llenarás mi copa de aguamiel, canalla.' WHERE `ID`=30637;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='룬으로 미래를 점쳐보니, 오늘 나는 승리한다는군!', `MaleText_loc4`='符文预示了我今日的胜利！', `MaleText_loc5`='符文預言了我今日的勝利!', `MaleText_loc7`='¡Las runas predijeron mi victoria hoy!' WHERE `ID`=30638;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘든가 보지? 하하하하하!', `MaleText_loc4`='累了吧？哈哈哈哈！', `MaleText_loc5`='累了嗎?哈哈哈哈哈!', `MaleText_loc7`='¿Te cansas? ¡Jajajaja!' WHERE `ID`=30639;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 오늘 저승에서 잠들 게다!', `MaleText_loc4`='今晚你就要在地狱里长眠了！', `MaleText_loc5`='你今夜將沉眠於黃泉!', `MaleText_loc7`='¡Esta noche dormirás en el inframundo!' WHERE `ID`=30640;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아예 깨어나지 않았기를 바라게 될 거다, 애송아.', `MaleText_loc4`='你会希望自己从未觉醒。', `MaleText_loc5`='你會希望你從來未被喚醒，小子。', `MaleText_loc7`='Chico, desearás no haber despertado.' WHERE `ID`=30641;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방패 여전사 마냥 불평이 많구나!', `MaleText_loc4`='你就知道抱怨，像女人似的！', `MaleText_loc5`='你太愛抱怨了，像個帶盾的女人一樣!', `MaleText_loc7`='¡Te quejas demasiado, como una doncella guerrera!' WHERE `ID`=30642;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='독이... 속이 아파 죽겠어요...', `MaleText_loc4`='毒药……胃部在剧烈翻腾……', `MaleText_loc5`='毒...我的體內在翻攪...', `MaleText_loc7`='Veneno... me arden las entrañas...', `FemaleText_loc1`='독이... 속이 아파 죽겠어요...', `FemaleText_loc4`='毒药……胃部在剧烈翻腾……', `FemaleText_loc5`='毒...我的體內在翻攪...', `FemaleText_loc7`='Veneno... me arden las entrañas...' WHERE `ID`=30643;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 준비됐습니다. 여기서 나갑시다.', `MaleText_loc4`='我准备好了——我们离开这里吧。', `MaleText_loc5`='我準備好了 - 讓我帶你出去。', `MaleText_loc7`='Estoy listo, vamos a sacarte de aquí.', `FemaleText_loc1`='전 준비됐습니다. 여기서 나가요.', `FemaleText_loc4`='我准备好了——我们离开这里吧。', `FemaleText_loc5`='我準備好了 - 讓我帶你出去。', `FemaleText_loc7`='Estoy lista, vamos a sacarte de aquí.' WHERE `ID`=30644;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비가 되면 알려주세요. 좀 빨리 갔으면 좋겠군요. 독이다 뭐다 해서 서서히 죽어 가고 있으니까 말이에요...', `MaleText_loc4`='你准备好了就告诉我一声。我希望越快越好……因为毒药正在慢慢发作。', `MaleText_loc5`='準備好跟我說一聲。快一點比慢一點好...像是慢慢地中毒死去。', `MaleText_loc7`='Cuando quieras ponerte en marcha, házmelo saber. Preferiría que fuera más pronto que tarde... por eso de que el veneno mata lentamente y tal.', `FemaleText_loc1`='준비가 되면 알려주세요. 좀 빨리 갔으면 좋겠군요. 독이다 뭐다 해서 서서히 죽어 가고 있으니까 말이에요...', `FemaleText_loc4`='你准备好了就告诉我一声。我希望越快越好……因为毒药正在慢慢发作。', `FemaleText_loc5`='準備好跟我說一聲。快一點比慢一點好...像是慢慢地中毒死去。', `FemaleText_loc7`='Cuando quieras ponerte en marcha, házmelo saber. Preferiría que fuera más pronto que tarde... por eso de que el veneno mata lentamente y tal.' WHERE `ID`=30645;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리켓에게 독주머니를 가져가겠습니다... 그런 후에는.. 예상하시겠지만... 쓰러지겠지요. 도와줘서 고맙습니다!', `MaleText_loc4`='我本来想把毒囊交给莉吉特的……接着……你也知道了……我倒下了。谢谢你帮我！', `MaleText_loc5`='我準備帶著毒囊給瑞基特...接著...你知道的...毀滅。謝謝你幫助我!', `MaleText_loc7`='Voy a llevarle el saco de veneno a Ricket... y después... ya sabes... a desmayarme. ¡Gracias por la ayuda!', `FemaleText_loc1`='리켓에게 독주머니를 가져갈게요... 그런 후에는.. 예상하시겠지만... 쓰러지겠죠. 도와줘서 고마워요!', `FemaleText_loc4`='我本来想把毒囊交给莉吉特的……接着……你也知道了……我倒下了。谢谢你帮我！', `FemaleText_loc5`='我準備帶著毒囊給瑞基特...接著...你知道的...毀滅。謝謝你幫助我!', `FemaleText_loc7`='Voy a llevarle el saco de veneno a Ricket... y después... ya sabes... a desmayarme. ¡Gracias por la ayuda!' WHERE `ID`=30646;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 계속해서 요툰하임을 공격해야 합니다. 녀석들에게 숨 쉴 틈도, 눈 붙일 틈도 줘서는 안 돼요. 무엇보다, 절대로 항복을 받아들여선 안 됩니다!$B$B강력한 파멸의 인도자를 손에 쥔 티리온 폴드링 경이나, 그를 뒷받침하는 은빛십자군이 당신의 임무를 대신할 수 없습니다!$B$B자, 이제 어서 할 일을 하십시오, $n. 한가하게 잡담을 나누기엔 너무 많은 일이 일어나고 있으니까.', `MaleText_loc4`='我们必须继续攻打尤顿海姆。不能给他们丝毫喘息的机会！让他们不眠不休地疲劳作战！拒绝纳降！$B$B即便是灰烬使者的持有者提里奥·弗丁和他麾下的银色北伐军，都不可能取得你如今的成就！$B$B$n，开战吧！就在我们闲聊的时候，说不定局势已经发生了巨大的逆转。', `MaleText_loc5`='我們必須要持續攻擊卓頓海姆。絕對不能給他們喘息的機會，不能讓他們休息，而且絕不接受投降!$B$B握有強大灰燼使者的提里奧·弗丁，和他身後的銀白十字軍根本無法企及你所做的一切!$B$B現在，有正事快說，$n。我們可沒空閒聊。', `MaleText_loc7`='Debemos atacar Jotunheim continuamente. ¡No darles ninguna oportunidad de recobrar el aliento, ni de dormir, ni de aceptar la derrota!$B$BTirion Vadín no podrá conseguir lo que estás haciendo ni con todo el poder de la Crematoria, ni con todo el apoyo de la Cruzada Argenta.$B$BAhora, date prisa con lo tuyo, $n. Están ocurriendo demasiadas cosas como para pararse a charlar.' WHERE `ID`=30647;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비가 되면 내게 이야기하면 된다. 그럼 널 내 머리 꼭대기에 앉혀 주지. 그러곤 줄드락의 스컬지를 향해 진군하는 거다. 어떤 놈을 해치워야 하는지는 네가 알려 줘야 한다.', `MaleText_loc4`='等你准备好，我就将你放在我的头顶，然后我们一起消灭祖达克的天灾军团。你要指挥我对付敌人！', `MaleText_loc5`='當你準備好時，我會把你放在我的頭上。我們將前往天譴軍在祖爾德拉克的核心。你得導引我摧毀我們的敵人。', `MaleText_loc7`='Cuando estés $glisto:lista; te colocaré sobre mi cabeza y marcharemos hacia el corazón de la Plaga en Zul''Drak. ¡Deberás dirigirme para aplastar y destruir a nuestros enemigos!' WHERE `ID`=30648;
