UPDATE `locales_broadcast_text` SET `MaleText_loc1`='2번째 계급 달성: 부관', `MaleText_loc4`='你达到了2级军衔：中尉', `MaleText_loc5`='你達到了階級2:中尉', `MaleText_loc7`='Has alcanzado el Rango 2: Teniente primero.', `FemaleText_loc1`='2번째 계급 달성: 부관', `FemaleText_loc4`='你达到了2级军衔：中尉', `FemaleText_loc5`='你達到了階級2:中尉', `FemaleText_loc7`='Has alcanzado el Rango 2: Teniente primero.' WHERE `ID`=30651;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자이머에게 폭풍 구름이 필요합니다!', `MaleText_loc4`='盖米尔急需雷云！', `MaleText_loc5`='基默急需風暴雷雲!', `MaleText_loc7`='¡Gymer necesita mucho una nube tormentosa!' WHERE `ID`=30652;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자이머가 위험합니다! 폭풍 구름을 찾으세요!', `MaleText_loc4`='盖米尔快要死了！赶快去找雷云！', `MaleText_loc5`='基默要死了!快找風暴雷雲!', `MaleText_loc7`='¡Gymer va a morir! ¡Encuentra una nube tormentosa!' WHERE `ID`=30653;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='울두아르에 있는 자료에는 로켄이 우리를 대적하는 데 이 도시 자원을 쓰지 못하도록 막을 수 있는 지식이 담겨 있지요. 문제는 그 자료를 볼 수 있는 열쇠가 둘로 나뉘어 감춰졌다는 겁니다.$B$B그 한쪽은 어디 있는지 제가 알아냈지요. 발명가의 도서관인데 당신이 있는 곳에서 북동쪽 산맥의 북쪽 끝에 있는 곳이지요. 당신이 가장 먼저 해야 할 일은 도서관 문지기로부터 접속 원반 조각을 되찾아 오는 일이지요.', `MaleText_loc4`='保存在奥杜尔的文献中可能记载着阻止洛肯滥用城市资源来对付我们的办法。但是解封档案的钥匙被泰坦分成了两截，并分别藏了起来。$B$B我已经发现了其中一半的下落，它就藏在创世者的图书馆里。图书馆位于东北方群山的北麓。首先，你必须从图书馆守卫者那里取得圆盘的碎片。', `MaleText_loc5`='奧杜亞的檔案庫裡也許有我們要的東西，就是能夠阻擋洛肯使用城市的資源對抗我們的知識。問題就是打開檔案庫的鑰匙被分割而且藏起來了。$B$B我想我知道其中一個在哪，就在發明者圖書館，在東北方山脈的北緣。你第一件要做的是就是從圖書館的守衛身上拿回通行圓盤的碎片。', `MaleText_loc7`='Puede que los archivos de Ulduar contengan el conocimiento que necesitamos para evitar que Loken utilice los recursos de la ciudad en nuestra contra. El problema es que la llave para esos archivos se dividió en varias partes que se escondieron.$B$BYo creo que sé dónde está una de las piezas, en la Biblioteca del Inventor, que está en la frontera norte de las montañas al noreste de tu posición. Lo primero que tienes que recuperar son los fragmentos de un disco de acceso de los guardianes de la biblioteca.' WHERE `ID`=30654;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희 몸 지키기도 벅찬 상황입니다! 알아서 조심하십시오!', `MaleText_loc4`='我们遇到麻烦了，$r！当心身后！', `MaleText_loc5`='我們過頭了，$r!小心你背後!', `MaleText_loc7`='¡Estamos desbordados, $r! ¡Estate $gatento:atenta;!' WHERE `ID`=30655;
