UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스림이 밟아줄 테다!', `MaleText_loc4`='塞穆来了！', `MaleText_loc5`='瑟瑞姆碾壓!', `MaleText_loc7`='¡THRYM APLASTAR!' WHERE `ID`=30657;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스림... 복수를... 해 다오...', `MaleText_loc4`='塞穆……为……为我报仇……', `MaleText_loc5`='瑟瑞姆...幫...幫我復仇...', `MaleText_loc7`='Thrym... Veng... Véngame' WHERE `ID`=30658;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 네가 그를 풀어주었구나. 맞나? 상관없다. 그를 죽였다가 재조립하는 일이 잠시 늦춰졌을 뿐이니.', `MaleText_loc4`='哦，是你放了他？无所谓，不过是将他的死期和重生稍微往后推了一点而已。', `MaleText_loc5`='喔，你釋放了他?是嗎?不過，他的死亡與重建只不過被稍稍延遲了。', `MaleText_loc7`='Oh, lo has liberado, ¿verdad? Da igual, su muerte y reconstrucción solo sufrirá un leve retraso.' WHERE `ID`=30659;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠의 무기고를 장악하도록 도와 주셨으니 칠흑의 기사단에서 큰 빚을 진 셈이로군요. 그대를 만날 수 있어서 다행입니다.$B$B얼라이언스와 호드가 서로 싸우면서 리치 왕이 준 임무에 충실한 동안, 저희는 눈앞에 닥친 문제에 초점을 맞추어야 합니다.$B$B은빛십자군이라면 잠시 주춤한 채 어떻게 해야 적을 좋게 물리칠지 심사숙고하겠지만, 저희에게는 그런 도덕적인 거리낌 따윈 없으니 괜찮습니다.$B$B저희를 대신하여 복수해 주실 수 있습니까, $n 님?', `MaleText_loc4`='感谢你帮助黑锋骑士团夺取了暗影拱顶。能得到你的支持真是我们的荣幸。$B$B联盟和部落仍在互相厮杀，殊不知这只会让巫妖王获益。我们必须集中精力，处理好眼前的要事。$B$B对银色北伐军来说，他们总是在制定作战计划时犹豫不决，一心想着如何完美地击败敌人，我们就没有这些乱七八糟的担忧。$B$B$n，你就是我们执行复仇大业的工具。', `MaleText_loc5`='黯刃騎士團在拿下暗影穹殿這件事上欠你一份人情。我們很幸運能有你的幫助。$B$B當聯盟與部落彼此征戰，替巫妖王省下力氣時，我們依舊會全力處理眼前的任務。$B$B銀白十字軍還要猶豫、反覆思考要如何漂亮地戰勝敵人，我們可沒有那麼多道德限制。$B$B你能夠成為我們復仇的手段之一，$n。', `MaleText_loc7`='La Espada de Ébano está en deuda contigo por tu ayuda en la toma de La Cámara de las Sombras. Tenemos suerte de tenerte entre nosotros.$B$BMientras la Alianza y la Horda luchan entre ellos, haciendo el trabajo del Rey Exánime, nosotros nos mantendremos centrados en la tarea que nos ocupa.$B$BDonde la Cruzada Argenta puede dudar y pensar dos veces en la mejor manera de aplastar al enemigo, nosotros no tendremos dificultades morales.$B$BTú serás nuestro instrumento de venganza, $n.' WHERE `ID`=30660;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='갈기갈기 찢어 주마!', `FemaleText_loc4`='我要把你撕成碎片。', `FemaleText_loc5`='我會把你撕碎。', `FemaleText_loc7`='Te arrancaré todas las extremidades.' WHERE `ID`=30661;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='도전하겠다는 거냐?', `FemaleText_loc4`='你想挑战？', `FemaleText_loc5`='你要挑戰?', `FemaleText_loc7`='¿Me desafías?' WHERE `ID`=30662;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그리 강해 보이진 않는군.', `FemaleText_loc4`='你看上去并不强壮。', `FemaleText_loc5`='你看起來沒有這麼壯。', `FemaleText_loc7`='No pareces tan duro.' WHERE `ID`=30663;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='날 쓰러뜨릴 만한 자질이 있다고 생각하나?', `FemaleText_loc4`='你觉得自己够格吗？', `FemaleText_loc5`='你覺得你有他們要的東西?', `FemaleText_loc7`='¿Crees que tienes lo que hace falta?' WHERE `ID`=30664;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해 보자고, 아가씨.', `MaleText_loc4`='动手吧，我的姐妹。', `MaleText_loc5`='姊妹，上吧。', `MaleText_loc7`='Manos a la obra, hermana.', `FemaleText_loc1`='해 보자고, 아가씨.', `FemaleText_loc4`='动手吧，我的姐妹。', `FemaleText_loc5`='姊妹，上吧。', `FemaleText_loc7`='Manos a la obra, hermana.' WHERE `ID`=30665;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='만나서 반갑습니다, 전우여. 제가 잃었던 동지들을 되찾도록 도와드리겠습니다.', `FemaleText_loc4`='欢迎你，我的姐妹。我能帮你找回失散的伙伴。', `FemaleText_loc5`='你好，戰鬥姊妹。我可以幫你復活寵物。', `FemaleText_loc7`='Bienvenida, compañera de batallas. Puedo ayudarte a recuperar compañeros perdidos.' WHERE `ID`=30666;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='만나서 반갑습니다, 전우여. 제가 잃었던 동지들을 되찾거나 소환수를 우리에 넣도록 도와드리겠습니다.', `FemaleText_loc4`='欢迎你，我的姐妹。我能帮你看管宠物或是找回失散的伙伴。', `FemaleText_loc5`='你好，戰鬥姊妹。我可以存放你的寵物，或是幫你復活寵物。', `FemaleText_loc7`='Bienvenida, compañera de batallas. Puedo ayudarte a recuperar amigos perdidos o guardar a tus mascotas.' WHERE `ID`=30667;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음의 기사여... 당장 이리 와라!', `MaleText_loc4`='死亡骑士们……到这儿来！', `MaleText_loc5`='死亡騎士們...來這。', `MaleText_loc7`='¡Caballeros de la Muerte... venid aquí!' WHERE `ID`=30668;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어서 오십시오, 전우여.$B$B배불리 먹고, 편히 쉬십시오. 그래야, 또 온 힘을 다해 싸울 수 있을 테니까요!', `FemaleText_loc4`='进来吧，我的姐妹。$B$B好好地吃上一顿，再睡个安稳觉，这样才能养足精力，全力备战！', `FemaleText_loc5`='來吧，戰鬥姊妹們。$B$B狂歡，沉眠，如此你們才能使盡全力的戰鬥!', `FemaleText_loc7`='Vamos, compañera de batallas.$B$B¡Come y duerme para que puedas luchar con toda tu fuerza!' WHERE `ID`=30669;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='목숨을 걸고 신전을 지켜라!', `MaleText_loc4`='誓死保卫神殿！', `MaleText_loc5`='誓死守護神殿!', `MaleText_loc7`='¡Defiende el templo con tu vida!' WHERE `ID`=30670;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적에게 반격해라!', `MaleText_loc4`='击退敌人！', `MaleText_loc5`='擊退敵人!', `MaleText_loc7`='¡Lucha contra el enemigo!' WHERE `ID`=30671;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적이 땅 밑에 있다. 땅 밑에 있다!', `MaleText_loc4`='他们在地下！他们在地下！', `MaleText_loc5`='他們在地下。他們在地面下!', `MaleText_loc7`='Están bajo el suelo. ¡Están bajo el suelo!' WHERE `ID`=30672;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기는 우리 고향이다!', `MaleText_loc4`='这里是我们的家园！', `MaleText_loc5`='這是我們的家園!', `MaleText_loc7`='¡Este es nuestro hogar!' WHERE `ID`=30673;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도전자가 패배했습니다!', `MaleText_loc4`='挑战者被打败了！', `MaleText_loc5`='挑戰者已被擊退!', `MaleText_loc7`='¡El retador ha sido derrotado!' WHERE `ID`=30674;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도전자는 와르르 무너지고 말았습니다!', `MaleText_loc4`='他们还真是不堪一击啊！', `MaleText_loc5`='他們像是一袋獸人骷髏一樣的倒下!', `MaleText_loc7`='¡Han caído como un saco de cráneos orcos!' WHERE `ID`=30675;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바닥에 떨어진 핏방울 말고는 도전자의 흔적이란 찾아볼 수도 없군요!', `MaleText_loc4`='挑战者只留下了一滩血迹！', `MaleText_loc5`='挑戰者留下的只有在地板上的血跡!', `MaleText_loc7`='¡Todo lo que queda del retador es una mancha roja en el suelo!' WHERE `ID`=30676;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='광대를 내보내는 게 낫겠군요! 텅 빈 투기장에서 곡예라도 부리게 말입니다!', `MaleText_loc4`='不如叫些小丑来！神圣的斗兽场已经沦为马戏团了！', `MaleText_loc5`='把小丑叫進來!那裡變成一個馬戲團了!', `MaleText_loc7`='¡Llamad a los payasos! ¡Esto se ha convertido en un circo!' WHERE `ID`=30677;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우왓! 저분은 완전히 곤죽이 되셨는데요.', `MaleText_loc4`='哇！那家伙需要好好地“刮一刮”！', `MaleText_loc5`='「嗚嗚咈! 那個需要『鏟土機』。」', `MaleText_loc7`='¡UUUF! Ese va a necesitar el "raspador".' WHERE `ID`=30678;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 이런 일이! 저런! 차라리 그냥 없어져 버리라고!', `MaleText_loc4`='我还没回过神来——就听见“砰”的一声！挑战者就死了！', `MaleText_loc5`='逃都別想逃 -- 你們!死!', `MaleText_loc7`='Y DE LA NADA, ¡ZAS! ¡MUERTO!' WHERE `ID`=30679;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어이쿠! 눈을 가리십시오, 신사 숙녀 여러분! 참혹합니다!', `MaleText_loc4`='女士们先生们，请闭上双眼！这简直是大屠杀！', `MaleText_loc5`='先生小姐們，轉開你們的視線!場上有血腥畫面!', `MaleText_loc7`='¡Cúbranse los ojos, damas y caballeros! ¡Es un baño de sangre!' WHERE `ID`=30680;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='웅장한 고뇌의 투기장이 자네를 기다리는군, $n. 기억하라고. 일단 전투가 시작되면 투기장에서 나가면 안 돼. 죽이 되든 밥이 되든 말이지!', `MaleText_loc4`='进入痛苦斗兽场吧，$n。战斗开始后，你就必须留在竞技场里。要么获胜，要么死亡！', `MaleText_loc5`='苦痛露天競技場等著你，$n。記著，一旦戰鬥開始，你就得待在競技場內。勝利，不然就是死亡。', `MaleText_loc7`='El gran Anfiteatro de la Angustia aguarda, $n. Recuerda, cuando comience el combate debes quedarte en la arena. ¡GANAR O MORIR!' WHERE `ID`=30681;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신사 숙녀 여러분, 새로운 이야기가 시작됩니다. 고뇌의 투기장에서 펼쳐지는 삶과 죽음의 드라마를 지켜보십시오! 이번에 $n의 상대는 덩치 큰 요르문가르, 이그... 이그드? 이그도즈? 이거 뭐라고 읽는 거야? 아, 하여튼... $n|1과;와; 커다란 벌레의 대결입니다!', `MaleText_loc4`='女士们先生们，我们又见面啦。痛苦斗兽场的生死大战即将拉开帷幕！这一轮，将由$n对阵庞大的冰虫伊戈……伊戈达？伊戈杜斯？这名字是谁起的？！好吧，由$n对阵大虫子！', `MaleText_loc5`='尊貴的先生小姐們，今天我們又聚集在這裡。史詩級的對戰，生與死的爭鬥，就在苦痛露天競技場!這一場，我們有$n，對抗的是笨重的蟄猛巨蟲，伊格...伊格德?伊格多滋?誰想出來這名字的?!反正就是$n對一隻大蟲!', `MaleText_loc7`='Aquí estamos una vez más, damas y caballeros. ¡La lucha épica entre la vida y la muerte en el Anfiteatro de la Angustia! En esta ronda tenemos a $n contra el enorme jormungar, Yg... ¿Yggd? ¿Yggdoze? ¿A quién se le ocurren estos nombres? ¡$n contra un gusano gigante!' WHERE `ID`=30682;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 모습을 드러냅니다!', `MaleText_loc4`='%s出场了！', `MaleText_loc5`='%s登場了!', `MaleText_loc7`='¡%s aparece!' WHERE `ID`=30683;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 이그... 이그 어쩌고 하는 큰 벌레를 물리쳤습니다!', `MaleText_loc4`='$n击败了伊戈……伊戈这只大虫子！', `MaleText_loc5`='$n打敗了...伊格...伊格格超級大蟲!', `MaleText_loc7`='¡$n ha derrotado a Yg... Yggg gusano enorme!' WHERE `ID`=30684;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투 준비를 하라고, $n! 고뇌의 투기장에 내려가서 대기해야 해! 기억하라고. 자네든 적이든 투기장을 벗어나면 실격이야!', `MaleText_loc4`='做好准备，$n！进入斗兽场，准备战斗！记住，你和你的对手都不能离开竞技场，否则你会被取消资格！', `MaleText_loc5`='準備你的武器，$n!進入露天競技場，站穩!記得，你跟你的對手隨時隨地都得待在競技場裡，不然就失去資格!', `MaleText_loc7`='¡Prepárate para la pelea, $n! ¡Entra en el anfiteatro y mantente alerta! Recuerda, tu oponente y tú debéis estar en la arena en todo momento, ¡o seréis descalificados!' WHERE `ID`=30685;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투가 곧 시작됩니다! 헉, 제 눈이 잘못된 걸까요?! 이번... 이번 상대는 무시무시한 마그나타우르 군주, 노린내수염입니다! 그렇습니다, 여러분! 무려 노린내수염이라고요! $n|1은;는; 이제 끝장입니다!', `MaleText_loc4`='战斗即将开始！我没念错吧？这……这是邪恶的猛犸人领主，恶臭之须！是的，各位，是恶臭之须！$n毫无取胜的希望！', `MaleText_loc5`='戰鬥即將開始!我讀的小抄對嗎?是...是惡毒的猛瑪象人，臭鬚!是的，大家，就是臭鬚!$n一點機會也沒有!', `MaleText_loc7`='¡La batalla está a punto de empezar! ¿Estoy leyendo bien esta tarjeta? Es... Es el terrible señor magnatauro, ¡Barbahedionda! Sí, amigos, ¡Barbahedionda! ¡$n no tiene ni una oportunidad!' WHERE `ID`=30686;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 마그나타우르 군주를 압도했습니다! 용의 안식처에 있는 노린내수염의 가족들이 슬퍼하겠군요!', `MaleText_loc4`='$n以绝对优势战胜了猛犸人领主！龙骨荒野的猛犸人氏族会怀念恶臭之须的！', `MaleText_loc5`='在我公正的裁定之下，$n打敗了猛瑪象人領主!龍骨荒野的臭鬚部族等不到他回家了!', `MaleText_loc7`='Y con AUTORIDAD, ¡$n domina al señor magnatauro! ¡El clan de Barbahedionda le va a echar de menos en el Cementerio de Dragones!' WHERE `ID`=30687;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노린내수염이 간다, 쥐방울만한 녀석들아!', `MaleText_loc4`='一群小不点，恶臭之须来了！', `MaleText_loc5`='臭鬚來找你了，小個子。', `MaleText_loc7`='¡Barbahedionda va por ustedes, pequeñines!' WHERE `ID`=30688;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흐물흐물 녹여 주마!', `MaleText_loc4`='我要熔化你们的血肉！', `MaleText_loc5`='我會把你的肉從骨頭上拆下來!', `MaleText_loc7`='¡Fundiré la carne de sus huesos!' WHERE `ID`=30689;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 내게 도전하느냐, 조그만 $r|1아;야;?', `MaleText_loc4`='$r，你觉得有把握战胜我吗？', `MaleText_loc5`='你覺得你可以挑戰我，小$r?', `MaleText_loc7`='¿Crees que puedes desafiarme, $gpequeño:pequeña; $r?' WHERE `ID`=30690;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네깟 종족에게 무슨 명예가 있다고... 어쨌든 와라. 다른 놈과 마찬가지로 해치워 주마!', `MaleText_loc4`='你的种族毫无荣耀可言。尽管放马过来吧……反正你会像其他人一样死去！', `MaleText_loc5`='你的血統毫無榮譽感可言。不過來吧...你會死的像其他人一樣!', `MaleText_loc7`='Tu raza no tiene honor. Pero ven de todas formas... ¡morirás como todos los demás!' WHERE `ID`=30691;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='토림의 수염이여! 이거 나름 재미있겠군!', `MaleText_loc4`='以托里姆胡须的名义，这将是一场精彩的比赛！', `MaleText_loc5`='索林姆的鬍子在上，這可真是個好運動。', `MaleText_loc7`='¡Por la barba de Thorim, esto es deporte!' WHERE `ID`=30692;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 와라, $r $c|1아;야;. 난 바쁜 몸이다!', `MaleText_loc4`='动手吧，$r$c，我没时间跟你干耗！', `MaleText_loc5`='來吧，$r $c，我可沒一整天的時間陪你。', `MaleText_loc7`='Ven, $c $r, ¡no tengo todo el día!' WHERE `ID`=30693;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네깟 놈을 해치워 봤자 발할라스에서 내 실력을 증명하는 데는 별 도움이 안 되겠지만... 즐겁긴 하겠군!', `MaleText_loc4`='就算杀了你，也不能证明我在瓦哈拉斯的地位，就当是消遣好了！', `MaleText_loc5`='殺了你並不能讓我在英靈殿證明我的實力，不過應該蠻愉快的!', `MaleText_loc7`='¡Matarte no me ayudará a mostrar mi valía en Valhalas, pero será muy divertido!' WHERE `ID`=30694;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽을 곳을 찾는다면, 제대로 찾은 줄 알아라!', `MaleText_loc4`='如果你想死，我就成全你！', `MaleText_loc5`='要是你一意求死，就快了!', `MaleText_loc7`='¡Si buscas a la muerte, la has encontrado!' WHERE `ID`=30695;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='순식간에 저승으로 보내고 비웃어 주마! 공평하지?', `MaleText_loc4`='我送你一条通往地狱的捷径，而你让我消遣一番。听上去挺公平的！', `MaleText_loc5`='你搭上黃泉特快車，我對你哈哈大笑。聽起來蠻公平的。', `MaleText_loc7`='Un viaje rápido al inframundo para ti y un rato divertido para mí. ¡Me parece un trato justo!' WHERE `ID`=30696;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드라카리, 붉은돌격대인가 뭔가 하는 녀석, 노움 하나, 힐드니르 방패 여전사, 그다음엔 너냐? 어린애 장난 같군!', `MaleText_loc4`='达卡莱巨魔，然后是所谓的血色先锋军，接着是侏儒和海德尼尔持盾女武士，现在轮到你了？这是在跟我开玩笑吧？', `MaleText_loc5`='一個德拉克瑞人，一名眾人皆知的血色突襲軍成員，一隻地精，一位海迪尼爾的女盾侍，現在又來一個$r?這是個笑話嗎?', `MaleText_loc7`='Un Drakkari, uno de los del llamado Embate Escarlata, un gnomo, una doncella guerrera Hyldnir, ¿y ahora tú? ¿Acaso se trata de una broma?' WHERE `ID`=30697;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여러분, 느껴지십니까? 관중석이 후끈 달아올랐습니다! 곧 전투가 시작되겠군요!', `MaleText_loc4`='你们感觉到了吗？能量在空气中沸腾！这只能说明……', `MaleText_loc5`='你感受到觀眾的激昂了嗎?空氣中充滿了熱烈的氣氛!這只說明了一件事情...', `MaleText_loc7`='¿Lo notáis, amigos? ¡El aire crepita con energía! Eso solo puede significar una cosa...' WHERE `ID`=30698;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겁쟁이 같으니!', `MaleText_loc4`='懦夫！', `MaleText_loc5`='懦夫!', `MaleText_loc7`='¡Cobarde!' WHERE `ID`=30699;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일어나라, 대지의 형제들아! 필멸의 존재들이 에라시우스 손에 쓰러지는 것을 지켜보아라!', `MaleText_loc4`='站起来吧，大地的兄弟们。伊拉修斯要消灭这群凡人！', `MaleText_loc5`='奮起吧，大地的弟兄們!看伊拉修斯毀滅這些凡人!', `MaleText_loc7`='¡Alzaos, hermanos de la tierra! ¡Contemplad como Erathius acaba con los mortales!' WHERE `ID`=30700;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넵튤론 님을 위하여! 바다와 폭풍이여, 적을 뭉개버려라!', `MaleText_loc4`='为猎潮者而战！海洋与风暴的力量，摧毁我的敌人吧！', `MaleText_loc5`='為了奈普圖隆而戰!風暴與海洋的力量，摧毀我敵!', `MaleText_loc7`='¡Por Neptulon! ¡Fuerza del mar y la tormenta, aplastad a mis enemigos!' WHERE `ID`=30701;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알아키르 님께서 곧바로 적들에 냉혹한 죽음을 안기시리라!', `MaleText_loc4`='风之领主，让我的敌人迅速死去吧！', `MaleText_loc5`='奧拉基爾將賜予我面前的敵人一個冰冷、迅速的死亡!', `MaleText_loc7`='¡Que Al''Akir les otorgue a mis enemigos una muerte rápida y fría!' WHERE `ID`=30702;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='직접 보지 못하면 믿을 수도 없을 전투! 한 상냥한 투스카르 어부가, 잔인한 바다사자 무리와 열받은 펭귄에게 온 가족을 잃고 무정한 용병으로 돌변하고 말았습니다! 이제 그를 움직이는 논리는 오로지 돈입니다! 신사 숙녀 여러분, 오리노코 터스크브레이커를 소개합니다!!', `MaleText_loc4`='除非亲眼目睹，否则接下来的战斗将令人难以置信！这位即将出场的战士原本是个脾气温和的海象人渔夫，但是他的全家被恶毒的海狮和暴躁的企鹅杀死了，从此他就变成了一个行尸走肉般的雇佣兵。现在，他只为金币而战！女士们先生们，他就是奥里努克·碎牙！！', `MaleText_loc5`='這場戰鬥，你一定要看到才會相信!我們下一個戰士曾經是一名彬彬有禮的巨牙海民，但他現在變成了一個無情的傭兵，因為他的家人被一群可怕的海獅豹跟暴虐的企鵝所抹殺。現在，他只要錢!先生小姐們，讓我們歡迎，歐令諾寇·碎牙者!!', `MaleText_loc7`='¡Esta batalla hay que verla para creerla! Nuestro siguiente luchador era un pescador colmillarr amable, que se convirtió en un mercenario desalmado cuando toda su familia fue asesinada por una manada terrible de leones marinos y pingüinos cabreados! ¡Ahora solo le interesa el oro! Damas y caballeros, ¡ORINOKO ROMPECOLMILLOS!' WHERE `ID`=30703;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오너라, 땅에 사는 자여! 엄니와 수염의 분노에 맞서 보아라!', `MaleText_loc4`='来吧，旱鸭子。面对我的怒火吧！', `MaleText_loc5`='來吧，地表的居民，挑戰巨牙與鬍鬚的怒火!', `MaleText_loc7`='¡Vamos, ratas de tierra, enfrentaos a la furia del colmillo y el bigote!' WHERE `ID`=30704;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='콜라크가 왔노라, 나약한 존재들이여! 눈사태 무덤은 겨울도끼 부족의 것이다! 아, 그게 아니라... 고뇌의 투기장은 겨울도끼 부족 거다!', `MaleText_loc4`='科尔拉克来了！雪落墓地属于冰斧的勇士！呃，科尔拉克是想要说，斗兽场属于冰斧的勇士！', `MaleText_loc5`='科爾拉克來了，弱小的人們!落雪墓地是屬於冰斧的!呃，我是說露天競技場是屬於冰斧的!', `MaleText_loc7`='¡Korrak ha llegado, debiluchos! ¡Avalancha pertenece a Hacha Invernal! Eeh... ¡Korrak quiere decir que anfiteatro pertenece a Hacha Invernal!' WHERE `ID`=30705;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여긴 무덤이 없으니 콜라크를 상대로 사악한 장난을 칠 수 없을걸! 죽어라!', `MaleText_loc4`='别想对科尔拉克耍花招，斗兽场可没有墓地！去死吧！', `MaleText_loc5`='這裡沒有墓地讓你對科爾拉克使出下流的招式!死吧!', `MaleText_loc7`='¡Aquí no hay un cementerio para que juegues a tus juegos retorcidos con Korrak! ¡MUERE!' WHERE `ID`=30706;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼음왕관에 있는 야만전사의 절벽 출신, 도살자 블라도프와 그의 매머드 왕발굽을 소개합니다! 우리의 도전자에게는 희망이 없군요! 피와 눈물이 강을 이루는 한판을 기대하십시오!', `MaleText_loc4`='来自冰冠冰川野蛮之台的屠夫乌拉多弗以及他的猛犸象恩诺姆斯！各位，这次我们的挑战者恐怕会被轰得连渣都不剩！让我们共同期待一场腥风血雨的大战吧！', `MaleText_loc5`='『屠夫』伏雷多弗跟他的長毛象，依諾摩斯從寒冰皇冠的蠻荒岩臺來到此地。各位，我們的挑戰者即將要屍骨無存了!準備體驗鮮血、內臟與淚水四濺的快感吧!', `MaleText_loc7`='¡Desde la Cornisa Salvaje de Corona de Hielo, Vladof el Carnicero y su mamut, Enormos! ¡Amigos, no va a quedar nada de nuestros contendientes! ¡Preparaos para una lluvia de sangre, sudor y tripas!' WHERE `ID`=30707;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 귀여운 것. 우리가 저들을 밟아주자! 단 하나의, 진정한 왕을 위하여!', `MaleText_loc4`='嗨，宝贝儿，将他们统统撕碎！我们才是真正的王者！', `MaleText_loc5`='是的，這是我的榮幸，我們會把他們分成好幾塊!為了唯一的真王!', `MaleText_loc7`='¡Sí, mi precioso, los partiremos en pedazos! ¡Por el verdadero rey!' WHERE `ID`=30708;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쓸모없는 짐승 같으니! 내가 직접 상대하겠다!', `MaleText_loc4`='没用的家伙！看来我得亲自动手了！', `MaleText_loc5`='無用的雜種!我自個解決他們!', `MaleText_loc7`='¡Mestizo inútil! ¡Los mataré yo mismo!' WHERE `ID`=30709;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='블라도프가 매머드에서 내립니다!', `MaleText_loc4`='乌拉多弗跃下了猛犸象！', `MaleText_loc5`='伏雷多弗掉下長毛象了!', `MaleText_loc7`='¡Vladof desmonta!' WHERE `ID`=30710;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 뭐지?!', `MaleText_loc4`='这是什么？！', `MaleText_loc5`='這是?!', `MaleText_loc7`='¡¿Qué es esto?!' WHERE `ID`=30711;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칠흑의 기사단 사령관이자 스컬지 제압자, 어둠의 무기고에서 승리를 거두신 란크랄 공작님의 명령에 따라, 즉각 사퇴를 선고하는 바이다. 어떤 의견이 있는가?', `MaleText_loc4`='黑锋骑士团指挥官、天灾军团征服者以及暗影拱顶征服者——兰克拉尔公爵命令你束手就擒。你接不接受这份裁决？', `MaleText_loc5`='奉蘭克洛公爵、黯刃騎士團指揮官、天譴軍鎮壓者、暗影穹殿征服者之令，爾等將即刻投降。爾等的答覆為何?', `MaleText_loc7`='Por orden del Duque Lankral, Comandante de los Caballeros de la Espada de Ébano, Vencedor de la Plaga y Conquistador de La Cámara de las Sombras, tienes que retirarte. ¿Cuál es tu decisión?', `FemaleText_loc1`='칠흑의 기사단 사령관이자 스컬지 제압자, 어둠의 무기고에서 승리를 거두신 란크랄 공작님의 명령에 따라, 즉각 사퇴를 선고하는 바이다. 어떤 의견이 있는가?', `FemaleText_loc4`='黑锋骑士团指挥官、天灾军团征服者以及暗影拱顶征服者——兰克拉尔公爵命令你束手就擒。你接不接受这份裁决？', `FemaleText_loc5`='奉蘭克洛公爵、黯刃騎士團指揮官、天譴軍鎮壓者、暗影穹殿征服者之令，爾等將即刻投降。爾等的答覆為何?', `FemaleText_loc7`='Por orden del Duque Lankral, Comandante de los Caballeros de la Espada de Ébano, Vencedor de la Plaga y Conquistador de La Cámara de las Sombras, tienes que retirarte. ¿Cuál es tu decisión?' WHERE `ID`=30712;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 결정 말이냐? 이게 내 결정이다, 하찮은 심부름꾼아!', `MaleText_loc4`='接不接受？这就是我的回答，小信差！', `MaleText_loc5`='我的回覆?這就是我的回覆，小信差!', `MaleText_loc7`='¿Mi decisión? ¡Aquí está mi decisión, $gpequeño:pequeña; $gmensajero:mensajera;!' WHERE `ID`=30713;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겨울도끼 트롤 최고의 전사가 자네에게 도전했네, $n! 마음의 준비를 하라고!', `MaleText_loc4`='冰斧巨魔的勇士向你发起了挑战，$n！希望你已经做好了准备！', `MaleText_loc5`='冰斧的食人妖勇士來挑戰你了，$n!我希望你準備好了!', `MaleText_loc7`='¡El campeón de los trols Hacha Invernal te ha desafiado, $n! ¡Espero que estés $glisto:lista;!' WHERE `ID`=30714;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='머나먼 알터랙 산맥에서 왔습니다! 지금껏 이 투기장에 모습을 드러낸 이 중 가장 강력한 전사, 피의 광전사 콜라크입니다!!!', `MaleText_loc4`='奥特兰克山谷的访客，斗兽场中迄今为止最为凶猛的斗士：血怒者科尔拉克！！！', `MaleText_loc5`='從遙遠的奧特蘭克山谷前來，這個競技場上出現過最兇猛的挑戰者:『血怒者』科爾拉克!!!', `MaleText_loc7`='Desde las lejanas Montañas de Alterac llega uno de los competidores más fieros que hayamos visto en esta arena: ¡¡KORRAK EL SANGUINARIO!!' WHERE `ID`=30715;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='믿을 수가 없군요! 새로운 용사가 고뇌의 투기장을 접수했습니다!!! 어중이떠중이로 이루어진 어설픈 무리에게 도살자 블라도프가 지고 말았군요! 참으로 극적입니다!', `MaleText_loc4`='难以置信！新的痛苦斗兽场勇士诞生了！！！一群无名小卒击败了屠夫乌拉多弗！真是个奇迹！', `MaleText_loc5`='我不相信!我們的苦痛競技場有了新的勇士!『屠夫』伏雷多弗被一個下層社會的無名小卒所打敗!這是難以置信的結局!', `MaleText_loc7`='¡NO ME LO PUEDO CREER! ¡TENEMOS A UN NUEVO CAMPEÓN DE LA ANGUSTIA! ¡Vladof el Carnicero ha sido derrotado por un grupo de don nadies! ¡Un final increíble!' WHERE `ID`=30716;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 모조로 물보라를 일으키며 정면으로 돌진합니다!', `MaleText_loc4`='%s聚集了魔精，向前冲去！', `MaleText_loc5`='%s集中他的魔精然後向前猛衝!', `MaleText_loc7`='¡%s reúne su mojo y carga hacia adelante!' WHERE `ID`=30717;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 관통당했습니다!', `MaleText_loc4`='$n被逼到了绝路！', `MaleText_loc5`='$n被釘住了!', `MaleText_loc7`='¡$n es empalado!' WHERE `ID`=30718;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='할 일이 정 없거든, 이것들을 처치해라!', `MaleText_loc4`='如果你没别的事可做，就去杀掉这些家伙吧！', `MaleText_loc5`='要是你沒其他事可以作的話，就殺光這些小東西!', `MaleText_loc7`='¡Si no puedes ayudar de otro modo, mata a estas cosas!' WHERE `ID`=30719;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다. 전 이제 끝이라고 생각했어요.', `MaleText_loc4`='谢谢你。我还以为自己死定了呢。', `MaleText_loc5`='謝謝你。我還想我死定了。', `MaleText_loc7`='Gracias. Creía que estaba acabado.' WHERE `ID`=30720;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 죽는 줄만 알았지 뭡니까.', `MaleText_loc4`='我还以为这里将成为我的坟墓呢。', `MaleText_loc5`='我本來想我鐵定得死在這裡。', `MaleText_loc7`='Estaba seguro de que iba a morir ahí fuera.' WHERE `ID`=30721;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신과 함께 싸우게 해 주세요.', `MaleText_loc4`='让我和你一起战斗吧。', `MaleText_loc5`='讓我與你一同作戰。', `MaleText_loc7`='Déjame luchar a tu lado.' WHERE `ID`=30722;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='함께 무쇠 드워프와 싸웁시다!', `MaleText_loc4`='我们一起对抗铁矮人吧！', `MaleText_loc5`='讓我們一起擊退鐵矮人!', `MaleText_loc7`='¡Luchemos juntos contra los férreos!' WHERE `ID`=30723;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 이제 혼자서도 괜찮다, $n.', `MaleText_loc4`='我能照顾自己的，$n。', `MaleText_loc5`='我可以照顧好自己，$n。', `MaleText_loc7`='Puedo ocuparme de mí mismo, $n.' WHERE `ID`=30724;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일단 경기가 시작되면 나오는 방법은 단 두 가지 뿐입니다. 이기거나 죽거나! 도망치는 행위는 허용되지 않습니다.', `MaleText_loc4`='一旦比赛开始，就是不死不休的局面！逃跑是不可能的！', `MaleText_loc5`='一旦比賽開始，只有兩種下場:獲勝，不然就是死亡!逃跑是不可能的!', `MaleText_loc7`='Una vez empieza un combate hay dos salidas: ¡GANAR O MORIR! ¡Huir no es una opción!' WHERE `ID`=30725;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 광폭해집니다!', `MaleText_loc4`='%s进入狂暴状态！', `MaleText_loc5`='%s狂暴了!', `MaleText_loc7`='¡%s se pone rabioso!' WHERE `ID`=30726;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 광기에 찹니다!', `MaleText_loc4`='%s越来越疯狂了！', `MaleText_loc5`='%s變得越來越瘋狂!', `MaleText_loc7`='¡%s enloquece coada vez más!' WHERE `ID`=30727;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스랄... 대족장이시여... 그대의 군대가 명령을 기다리고 있소. 그대의 노스렌드로 이끌어 언데드의 위협을 없애버리게 해 주시오!', `MaleText_loc4`='萨尔……酋长……部队在等待你的命令。请允许我带领他们前往诺森德，彻底铲除亡灵的威胁！', `MaleText_loc5`='索爾...大酋長...軍隊正等著你的命令。讓我帶領他們前往北裂境，清除那些威脅我們的不死生物。', `MaleText_loc7`='Thrall... Jefe de Guerra... tus ejércitos aguardan tu orden. ¡Déjame llevarlos a Rasganorte para eliminar esta amenaza no-muerta!' WHERE `ID`=30728;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런! 참을 수가 없군! 그대가 대화를 나누며 심사숙고하는 동안, 우리 적은 더 강해지고 있소! 내가 선택할 수 있었다면, 호드를 위하여 동원 가능한 모든 군대를 이끌어 얼어붙은 곳으로 가 정복해냈을 것이오!', `MaleText_loc4`='啊！我受不了了！在你们反复权衡利弊的时候，我们的敌人正在逐渐壮大！如果让我来决定，我会召集一切力量登上那座冰山，为部落征服它！', `MaleText_loc5`='啊!我沒辦法忍受了!在你說話考慮的同時，敵人正變的越來越強大!要是我來做決定的話，我就把所有可用的軍隊都調去那塊冰凍的石頭上，為了部落征服它!', `MaleText_loc7`='¡Agh! ¡No aguanto esto! ¡Mientras habláis y deliberáis, nuestros enemigos se hacen más fuertes! ¡Si fuera cosa mía, llevaría todas nuestras fuerzas disponibles a esa roca helada y la conquistaría para la Horda!' WHERE `ID`=30729;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕이 그대와 그대의 백성을 다 처리한 후에 말이오? 막고라!', `MaleText_loc4`='他犯下了这么多罪孽，你还在犹豫？MAK''GORA！', `MaleText_loc5`='在他為你和你的人民做了那些事情以後?MAK''GORA!', `MaleText_loc7`='¿Después de todo lo que hizo por TI y TU pueblo? ¡MAK''GORA!' WHERE `ID`=30730;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래서 거절하는 것이오? 듀로탄의 아드님께서 비겁자셨던가?', `MaleText_loc4`='这么说你打算拒绝我的请求？杜隆坦之子原来是个懦夫！', `MaleText_loc5`='所以你拒絕?原來杜洛坦的兒子是個懦夫?', `MaleText_loc7`='¿Te niegas? ¿Es el hijo de Durotan un cobarde?' WHERE `ID`=30731;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대의 생각은 어떻소, 사울팽?', `MaleText_loc4`='萨鲁法尔，你的看法是什么？', `MaleText_loc5`='薩魯法爾，你怎麼說?', `MaleText_loc7`='¿Tú qué dices, Colmillosauro?' WHERE `ID`=30732;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 영혼은 복수에 대한 열망으로 불타고 있지만 정령들이 내게 분명하게 생각하고 행동하라 말하고 있소이다. 리치 왕은 냉혹하기 이를 데 없는 적이오... 신중의 신중을 기해서 상대해야만 하는 자란 말이오.', `MaleText_loc4`='复仇的烈焰煎熬着我的灵魂，但眼前的局势迫使我们必须仔细权衡。巫妖王是个残忍的对手……我们要小心应付。', `MaleText_loc5`='我的靈魂燃燒著復仇的憤怒，但是元素們叫我再想清楚點。巫妖王是個無情的對手...我們一定得小心對付他。', `MaleText_loc7`='Mi alma arde con venganza, pero los elementos me dicen que piense con claridad. El Rey Exánime es un enemigo despiadado... uno al que hay que manejar con cuidado.' WHERE `ID`=30733;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상황 점검 차원에서 정찰병들을 보낼 것이오. 또한 프라우드무어 양과 회합을 가져 얼라이언스 연합에서는 어떤 계획을 세우고 있는지도 알아보겠소이다.', `MaleText_loc4`='我们要派斥候去查探敌情。我还要和普罗德摩尔女士会晤，看看联盟有什么打算。', `MaleText_loc5`='我們先派斥候探探情況。我也將與普勞德摩爾女士召集會議，看看聯盟那邊的動靜。', `MaleText_loc7`='Enviaremos exploradores para valorar la situación. También me reuniré con Lady Valiente y veré qué planes tiene la Alianza.' WHERE `ID`=30734;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 함정이라면, 무턱대고 부딪히지 않을 것이오! 가로쉬, 그대의 아버지와 똑같은 실수를 하지 마시오!', `MaleText_loc4`='如果这是个陷阱，我是不会盲目踩进去的！不要犯和你父亲同样的错误，加尔鲁什！', `MaleText_loc5`='要是這是陷阱，那我不會盲目踩進。卡爾洛斯，別跟你父親犯一樣的錯誤!', `MaleText_loc7`='¡Si esto es una trampa, no será una en la que entre a ciegas! ¡Garrosh, no cometas los mismos errores que tu padre!' WHERE `ID`=30735;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장이시여, 노스렌드는 우리 백성에게 가장 심각한 위협이며, 이에 맞서 행동을 취해야 하는 게 사실입니다. 하지만 이번 적은 다른 적과는 다릅니다. 신중하게 행동해야만 합니다.', `MaleText_loc4`='酋长，诺森德已经成为我们最大的威胁了，我们必须反击。但是巫妖王的实力不容小觑，我们绝对不能掉以轻心。', `MaleText_loc5`='大酋長，顯然北裂境代表著我們最大的威脅，我們一定得採取行動。問題是，這個敵人與其他的敵人不同，一定得小心對付。', `MaleText_loc7`='Jefe de Guerra, está claro que Rasganorte representa la mayor amenaza para nuestro pueblo y debemos actuar contra ella. Pero este enemigo no es como los demás. Aconsejo precaución.' WHERE `ID`=30736;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장이시여! 스컬지 군대가 오그리마를 공격하고 있습니다!', `MaleText_loc4`='酋长！天灾军团正在攻打奥格瑞玛！', `MaleText_loc5`='大酋長!天譴軍的軍隊似乎在攻擊奧格瑪!', `MaleText_loc7`='¡Jefe de Guerra! ¡Fuerzas de la Plaga atacan Orgrimmar!' WHERE `ID`=30737;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사울팽 여기 있습니다, 대족장이시여.', `MaleText_loc4`='酋长，有何吩咐？', `MaleText_loc5`='是的，大酋長?', `MaleText_loc7`='¿Sí, Jefe de Guerra?' WHERE `ID`=30738;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장님께서 명하신 대로 따르겠습니다!', `MaleText_loc4`='遵命，酋长！', `MaleText_loc5`='如您所令，大酋長!', `MaleText_loc7`='¡A tus órdenes, Jefe de Guerra!' WHERE `ID`=30739;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모조 웅덩이 속에서 무언가 움직입니다...', `MaleText_loc4`='魔精池里似乎有什么生物在骚动……', `MaleText_loc5`='好像有什麼東西在魔精池裡翻攪著...', `MaleText_loc7`='Algo se mueve en la charca de mojo...' WHERE `ID`=30740;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 대체 여기서 뭘 하는 거요?$B$B내게 거치적거리지 않도록 조심하시오. 당신 같은 사람한테 방해나 받으려고 붉은돌격대를 떠난 게 아니니까!', `MaleText_loc4`='你在这儿干什么？$B$B别挡我的路。我不会让你这种人干扰血色先锋军的！', `MaleText_loc5`='你在這裡幹嘛?$B$B不要擋我的路，我可不能讓你把我的注意力從血色突襲軍身上移開!', `MaleText_loc7`='¿Qué haces TÚ aquí?$B$BAsegúrate de mantenerte fuera de mi camino. ¡No abandoné El Embate Escarlata para que me distrajeran cosas como tú!' WHERE `ID`=30741;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='결투를 신청합니다, 붉은돌격대 나으리!', `MaleText_loc4`='我要和你决斗，先锋军的混蛋！', `MaleText_loc5`='我要跟你決鬥，血色混帳!', `MaleText_loc7`='¡Te desafío a un duelo, escoria Escarlata!', `FemaleText_loc1`='결투를 신청합니다, 붉은돌격대 나으리!', `FemaleText_loc4`='我要和你决斗，先锋军的混蛋！', `FemaleText_loc5`='我要跟你決鬥，血色混帳!', `FemaleText_loc7`='¡Te desafío a duelo, escoria Escarlata!' WHERE `ID`=30742;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐, 잠깐... 항복이오! 제발 그만! 난 떠나겠소!', `MaleText_loc4`='等等，等等……我投降！求求你，别打了！我这就走！', `MaleText_loc5`='等下...我投降了!不要再打他了!他會走!', `MaleText_loc7`='Espera... ¡Me rindo! ¡Ya basta, por favor! ¡Me voy!' WHERE `ID`=30743;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 성기사 에프렘이 또 이겼군! 당연하지!', `MaleText_loc4`='哈！虔诚者埃弗雷姆又胜利了。毫无悬念！', `MaleText_loc5`='哈!忠誠的埃弗睿又贏了!這是當然的!', `MaleText_loc7`='¡Ja! Efrem el Leal gana de nuevo. ¡Por supuesto!' WHERE `ID`=30744;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와라, 브리쿨 자식아. 내가 상대해 주지!', `MaleText_loc4`='来啊，维库人的走狗。我要把你们统统打趴下！', `MaleText_loc5`='來吧，維酷狗兒。我跟你打!', `MaleText_loc7`='Vengan, perros vrykul. ¡Lucharé contra ustedes!' WHERE `ID`=30745;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 날 건드리다니?! 네가 무슨 짓을 하든 나는 반드시 리치 왕께 내 가치를 증명할 것이다!', `MaleText_loc4`='你竟敢挑战我？！别以为这样就能阻止我向巫妖王效忠！', `MaleText_loc5`='你敢碰我?!你阻止不了我攻擊維酷人，他要證明他對巫妖王的忠誠!', `MaleText_loc7`='¡¿Te atreves a TOCARME?! ¡No impedirás que le demuestre mi valía al Rey Exánime!' WHERE `ID`=30746;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 내게 덤비지 않지? 성기사 에프렘이 무서운 거로군!', `MaleText_loc4`='你为什么不敢面对我？你害怕虔诚者埃弗雷姆吗？', `MaleText_loc5`='為什麼不打我?你怕忠誠的埃弗睿?', `MaleText_loc7`='¿Por qué no te enfrentas a mí? ¿Tienes miedo de Efrem el Leal?' WHERE `ID`=30747;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나라고 인내심이 무한한 건 아니다! 어서 덤벼라! 난 내 능력을 보이러 여기 왔단 말이다!', `MaleText_loc4`='我的耐心是有限的！我是来证明自己的，这就是我的目的！', `MaleText_loc5`='我可沒有無止境的耐心!我來這裡證明我自己，而這就是我要做的啦!', `MaleText_loc7`='¡Mi paciencia no es infinita! ¡He venido aquí para probarme a mí mismo y es exactamente lo que pretendo hacer!' WHERE `ID`=30748;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 나와라, 브리쿨 놈들아! 겁쟁이로 낙인찍히고 싶으냐!', `MaleText_loc4`='战斗吧，维库人，莫非你是个胆小鬼！', `MaleText_loc5`='維酷狗兒來這裡跟我打!不然就是個懦夫!', `MaleText_loc7`='¡Lucha contra mí ahora, vrykul, o se te marcará como como un cobarde!' WHERE `ID`=30749;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 검 맛을 보아라, 꼬맹아!', `FemaleText_loc4`='尝尝我的铁拳吧，小鬼！', `FemaleText_loc5`='嚐嚐我的剛刃，小$g男孩:女孩;!', `FemaleText_loc7`='¡Prueba mi acero, $gpequeño:pequeña;!' WHERE `ID`=30750;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지는 게 당연하지. 다른 결과를 예상했느냐?', `FemaleText_loc4`='显然你输了。你还指望能怎么样呢？', `FemaleText_loc5`='你當然會輸。不然你以為?', `FemaleText_loc7`='Pues claro que has perdido. ¿Qué te esperabas?' WHERE `ID`=30751;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='날 귀찮게 하지 마라, 성가신 녀석아. 소위 전투원이라는 녀석들의 서투른 솜씨를 연구해 보는 중이니 말이다.$B$B나는 놈들을 능가할 것이고, 그러면 리치 왕께서 날 뽑아 주시겠지.', `FemaleText_loc4`='别来打扰我。我正在研究那些“格斗者”的笨拙动作。$B$B我要将他们统统击败，然后我就会被提拔为巫妖王的部属了。', `FemaleText_loc5`='別煩我，小蟲。我正在研究這些所謂的戰士的笨拙招式。$B$B我當然會勝過他們全部，接著我就可以榮升服侍巫妖王了。', `FemaleText_loc7`='No me molestes, estorbo. Estoy estudiando el combate de ineptos de estos llamados luchadores.$B$BYo les ganaré a todos y después ascenderé para servir al Rey Exánime.' WHERE `ID`=30752;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='브리쿨 여자는 싸움을 전혀 못 한다고 들었습니다. 반박하고 싶거든, 증명해 보시죠.', `MaleText_loc4`='我听说女性维库人根本不擅长战斗。如果你想证明我是错的，可以自己试试。', `MaleText_loc5`='我聽說維酷女人都不會打架。要是你想證明我錯了，可以嘗試一下。', `MaleText_loc7`='He oído que las mujeres vrykul no pueden luchar. Si quieres demostrarme lo contrario, puedes intentarlo.', `FemaleText_loc1`='브리쿨 여자는 싸움을 전혀 못 한다던데요. 반박하고 싶거든, 증명해 보시죠.', `FemaleText_loc4`='我听说女性维库人根本不擅长战斗。如果你想证明我是错的，可以自己试试。', `FemaleText_loc5`='我聽說維酷女人都不會打架。要是你想證明我錯了，可以嘗試一下。', `FemaleText_loc7`='He oído que las mujeres vrykul no pueden luchar. Si quieres demostrarme lo contrario, puedes intentarlo.' WHERE `ID`=30753;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 관상을 보아하니 돈이 좀 되겠는데. 고뇌의 투기장에서 한판 해 보는 게 어때?', `MaleText_loc4`='你似乎能帮我赚点钱。来痛苦斗兽场转转怎么样，伙计？', `MaleText_loc5`='你看起來可以幫我們賺些錢。有沒有考慮來苦痛露天競技場打一場，夥伴?', `MaleText_loc7`='Parece que podrías hacernos ganar algo de dinero. ¿Qué tal una vuelta por dentro del Anfiteatro de la Angustia, colega?' WHERE `ID`=30754;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오그리마의 하룻강아지들아! 들어라! 건방진 호드 녀석들아! 몸서리쳐라! 종말이 다가왔음을 느껴라! 리치 왕이 너희를 응시하고 있음을 알아라!', `MaleText_loc4`='奥格瑞玛的狗崽子们！部落的蠢材们！聆听我的审判吧！在恐惧中颤抖吧。巫妖王的双眼已经在凝视着你们。', `MaleText_loc5`='奧格瑪的傻小子們!聆聽我的怒吼，倉促成軍的部落!顫抖著，迎接你們的末日吧，因為巫妖王的凝視將降臨在你們身上!', `MaleText_loc7`='¡CRÍAS DE ORGRIMMAR!  ¡ESCÚCHENME,  DESCARADOS DE LA HORDA! ¡TIEMBLEN Y ENFRENTEN LA MUERTE!' WHERE `ID`=30755;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 이제 투기장을 접수한 고뇌의 용사라고, 친구! 그 칭호에 걸맞은 실력은 있겠지?', `MaleText_loc4`='现在你是斗兽场的勇士啦！你觉得自己能保住这个头衔吗？', `MaleText_loc5`='你現在是勇士了，老兄!你覺得你要花多少精力才能保住這個位置?', `MaleText_loc7`='¡Ahora eres $gel campeón:la campeona;, colega! ¿Crees que tienes lo que hay que tener para defender tu título?' WHERE `ID`=30756;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 독 회오리를 시전합니다!', `MaleText_loc4`='%s开始施放毒性新星！', `MaleText_loc5`='%s開始施展劇毒新星!', `MaleText_loc7`='¡%s comienza a lanzar Nova de veneno!' WHERE `ID`=30757;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 바쁩니다. 대화는 나중에 요청해 주세요.', `MaleText_loc4`='本单元正在忙碌。请稍后查询。', `MaleText_loc5`='這個單位正忙碌中。請稍後再洽詢。', `MaleText_loc7`='Esta unidad está ocupada. Pregunta más tarde.' WHERE `ID`=30758;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감독관에게 들키기 전에 어서 제자리로 돌아가세요.', `MaleText_loc4`='在监工看见我们之前，快回去工作吧。', `MaleText_loc5`='在監督者看到我們前回去工作。', `MaleText_loc7`='Vuelve al trabajo antes de que el capataz nos vea.' WHERE `ID`=30759;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 여기 인부가 아닙니다. 당신을 이 광산에서 해방하러 왔어요.', `MaleText_loc4`='我不是工人。我是来解救你的，你不用再在矿井里干苦力了。', `MaleText_loc5`='我不是這裡的勞工。我是來讓你們從奴役中解放的，從礦穴中解放。', `MaleText_loc7`='No soy un trabajador. Estoy aquí para liberarte de la servidumbre en las minas.', `FemaleText_loc1`='저는 여기 인부가 아닙니다. 당신을 이 광산에서 해방하러 왔어요.', `FemaleText_loc4`='我不是工人。我是来解救你的，你不用再在矿井里干苦力了。', `FemaleText_loc5`='我不是這裡的勞工。我是來讓你們從奴役中解放的，從礦穴中解放。', `FemaleText_loc7`='No soy una trabajadora. Estoy aquí para liberarte de la servidumbre en las minas.' WHERE `ID`=30760;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 폭발하면서 역병 웅덩이가 됩니다!', `MaleText_loc4`='%s炸出了一个天灾池。', `MaleText_loc5`='%s爆炸，釋放出一池的瘟疫雲!', `MaleText_loc7`='¡%s explota en una charca de plaga!' WHERE `ID`=30761;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자유라고요? 미미르 님께서 시키신 일을 마저 해야겠군요.', `MaleText_loc4`='又自由了？守护者米米尔的工作还没有做完。', `MaleText_loc5`='有空了?守護者彌米爾的工作等著你。', `MaleText_loc7`='¿Libre de nuevo? El trabajo del guardián Mimir aguarda.' WHERE `ID`=30762;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다. 저도 무쇠 드워프를 상대하는 데 힘을 보태겠습니다.', `MaleText_loc4`='谢谢你，$r。我要和你一起反抗雷铸铁矮人。', `MaleText_loc5`='感謝你，$r。我會加入你對抗風暴冶煉的行列。', `MaleText_loc7`='Gracias, $r. Me uniré a tu lucha contra los Tronaforjado.' WHERE `ID`=30763;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새 지령. 광산을 떠나 발명가의 도서관으로 갑니다.', `MaleText_loc4`='新指令：离开矿井并返回创世者的图书馆。', `MaleText_loc5`='新目標:離開礦脈，回到發明者圖書館。', `MaleText_loc7`='Nueva directiva: abandonar la mina y volver a la Biblioteca del Inventor.' WHERE `ID`=30764;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새 지령. 무쇠 드워프를 쓰러뜨립니다.', `MaleText_loc4`='新指令：帮忙击败铁矮人。', `MaleText_loc5`='新目標:協助擊退鐵矮人。', `MaleText_loc7`='Nueva directiva: ayudar a derrotar a los enanos férreos.' WHERE `ID`=30765;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계산할 수 없습니다. 기능에 문제가 있습니다. 지령. 작동 중지.', `MaleText_loc4`='无法计算。单元发生故障。指令：关闭。', `MaleText_loc5`='無法計算。系統不正常運作。目標:關機。', `MaleText_loc7`='Imposible calcular. Fallo en la unidad. Directiva: apagar.' WHERE `ID`=30766;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 세상에서 가장 위대한 진흙왕이다! 부하들아, 너희의 왕인 나를 도와라!', `MaleText_loc4`='我是至高无上的土灵之王！仆从们，现身吧——快来帮助你们的君王！', `MaleText_loc5`='我是塵土之王，沒人比我更厲害!我的爪牙聽令 - 協助你的主人!', `MaleText_loc7`='¡Soy el rey de la suciedad, no hay nadie que me supere! ¡Esbirros, ayudenme, ayuden a su señor!' WHERE `ID`=30767;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나의 왕국을 불태우려는 건 소용없는 짓이다! 오너라 노예들아, 나는 아직 건재하다!', `MaleText_loc4`='你无法用火焰烧毁我的王国！来吧，仆从们，我还不打算退位呢！', `MaleText_loc5`='我的王國可不能用火燒!來吧，我的僕人，我還沒準備要休息!', `MaleText_loc7`='¡Para quemar mi reino no puedes usar fuego! ¡Venid, mis sirvientes, no estoy preparado para retirarme!' WHERE `ID`=30768;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나의 힘센 바람은 나무들도 쓰러뜨린다! 부하들아, 날 도와 저들이 멋대로 굴지 못하도록 해라!', `MaleText_loc4`='我带起一阵足以吹倒大树的狂风！仆从们，快来帮我，他们不会得逞的！', `MaleText_loc5`='我召來了可以吹倒大樹的狂風!爪牙們，幫助你的主人，讓他們不再心想事成!', `MaleText_loc7`='¡Traigo un viento tan fuerte que puede derribar árboles! ¡Esbirros, ayudadme, no deben hacer su voluntad!' WHERE `ID`=30769;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 세상에서 가장 무섭고 차가운 존재이다! 정령들아, 나를 따라 모든 것을 얼리고 지배하자!', `MaleText_loc4`='我是万恶之恶，冷血之王！过来吧，元素仆从们，让我们冰封一切，统治世界！', `MaleText_loc5`='我是最壞、最酷的!元素們，幫助我，讓我們駕馭、冰凍這個戰場!', `MaleText_loc7`='¡Soy el más malo de los malos, el más molón de los molones! Venid, mis elementos, ¡vamos a congelar y gobernar!' WHERE `ID`=30770;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭풍우 봉우리로 돌아가십시오.', `MaleText_loc4`='返回风暴峭壁。', `MaleText_loc5`='回到風暴群山。', `MaleText_loc7`='Volver a las Cumbres Tormentosas.' WHERE `ID`=30771;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헬스크림의 아들이여, 내게 도전하겠다는 건가? 난 이런 일에 허비할 시간이 없다만...', `MaleText_loc4`='孩子，你想挑战我？我可没时间陪你玩……', `MaleText_loc5`='孩子，你挑戰我?我可沒時間跟你...', `MaleText_loc7`='¿Me desafías? No tengo tiempo para esto...' WHERE `ID`=30772;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='따라 들어오시오!', `MaleText_loc4`='进来！', `MaleText_loc5`='進去!', `MaleText_loc7`='¡Adentro!' WHERE `ID`=30773;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빨리 끝내지.', `MaleText_loc4`='让我们尽快结束这一切吧。', `MaleText_loc5`='讓我們速戰速決。', `MaleText_loc7`='Acabemos con esto rápido.' WHERE `ID`=30774;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그아아!', `MaleText_loc4`='啊！', `MaleText_loc5`='嘎啊!', `MaleText_loc7`='¡GYAH!' WHERE `ID`=30775;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 일은 다음번에 마무리 짓도록 하겠소... 헬스크림의 아들이여.', `MaleText_loc4`='格罗姆之子……我们还是另找时间吧。', `MaleText_loc5`='我們下次再來算帳...葛羅之子。', `MaleText_loc7`='Terminaremos esto en otro momento... hijo de Grom.' WHERE `ID`=30776;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사울팽이여...', `MaleText_loc4`='萨鲁法尔……', `MaleText_loc5`='薩魯法爾...', `MaleText_loc7`='Colmillosauro...' WHERE `ID`=30777;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장으로서의 의무는 나중에 해도 되오. 지금은... 싸워야 할 때란 말이오!', `MaleText_loc4`='别在我面前摆酋长的架子。现在……来战吧！', `MaleText_loc5`='你大酋長的職責可以等等。現在，我們來打一場!', `MaleText_loc7`='Tus deberes como Jefe de Guerra pueden esperar. Ahora... ¡lucharemos!' WHERE `ID`=30778;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='허! 그러니까 듀로탄의 아들이여, 뭐지...?', `MaleText_loc4`='哈！杜隆坦之子，你——', `MaleText_loc5`='哈!所以，杜洛坦之子，你要--', `MaleText_loc7`='¡Ja! Bueno, hijo de Durotan, qué...' WHERE `ID`=30779;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러니까 대족장이시여? 지금 뭐라 하시었소? 이 몸을 노스렌드로 보내시겠다는 거요?', `MaleText_loc4`='酋长？怎么说？能派我去诺森德吗？', `MaleText_loc5`='嗯，大酋長?你怎麼說?你要送我去北裂境嗎?', `MaleText_loc7`='¿Y bien, Jefe de Guerra? ¿Qué dices ahora? ¿Me enviarás a Rasganorte?' WHERE `ID`=30780;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디 있느냐, 왕수염? 날 도와라!', `MaleText_loc4`='冻须！你在哪儿？！快来帮我！', `MaleText_loc5`='腮鬚!你在哪?!快來幫我!', `MaleText_loc7`='¡Bigotes! ¿Dónde estás? ¡Ayúdame!' WHERE `ID`=30784;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='군대를 집결시키시오. 고블린 조선공에게 연락하시오. 호드는 이제 전쟁 준비에 돌입하오!', `MaleText_loc4`='召集军队，联络地精造船商！部落要开战了！', `MaleText_loc5`='引領我們的軍隊。聯絡我們的哥布林造船工人。部落準備好開戰了!', `MaleText_loc7`='Reúne a nuestras fuerzas. Contacta con nuestros carpinteros goblin. ¡La Horda se prepara para la guerra!' WHERE `ID`=30785;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그렇소, 스랄. 아서스를 처치해야 할 순간이 왔소. 내 휘하에 있는 대연금술사를 데리고 가도 좋소이다. 이자가 지닌 지식은 스컬지가 그대에게 무엇을 퍼붓든지 간에 방어 전략 수행에 막대한 도움을 줄 테니 말이오.', `FemaleText_loc4`='是的，萨尔。时机已经成熟，我们要杀死阿尔萨斯。带上我的大药剂师同行吧。他的知识能帮助你解决天灾军团的麻烦。', `FemaleText_loc5`='是的，索爾。擊倒阿薩斯的時間來臨了。你可以帶上我的大藥劑師。他的知識，對付天譴軍用在你們身上的招數，是無價的。', `FemaleText_loc7`='Sí, Thrall. Ha llegado la hora de matar a Arthas. Puedes llevarte a mi gran boticario contigo. Su conocimiento te será muy valioso contra cualquier cosa que la Plaga te lance.' WHERE `ID`=30786;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대단하군... 아주 대단해.', `FemaleText_loc4`='太好了……真是太好了。', `FemaleText_loc5`='太好了...這是最理想的。', `FemaleText_loc7`='Excelente... completamente excelente.' WHERE `ID`=30787;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리할 수 있다면 영광이 아닐 수 없겠군요, 어둠의 여왕님.', `MaleText_loc4`='这是我的荣幸，黑暗女王。', `MaleText_loc5`='這會是我的榮幸，黑暗女王。', `MaleText_loc7`='Sería un honor, Dama Oscura.' WHERE `ID`=30788;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기는 성스러운 곳이다! 침입자는 죽음을 맞으리라!', `FemaleText_loc4`='这里是神圣的献祭之厅！你们这些入侵者的结局只有死亡！', `FemaleText_loc5`='這是神聖的獻祭之廳!你們的入侵只能以死亡作結。', `FemaleText_loc7`='¡Estos recintos son sagrados! ¡Pagarás tu intromisión con tu vida!' WHERE `ID`=30789;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 마법 보호막 안에서 회전하기 시작합니다!', `MaleText_loc4`='%s开始旋转，一个魔法护盾包围了他！', `MaleText_loc5`='%s開始旋轉，接著被關在魔法護盾裡!', `MaleText_loc7`='¡%s comienza a girar, encerrado en un escudo mágico!' WHERE `ID`=30791;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 호디르의 뿔피리를 닮은 기념비는 천둥 골짜기 전투에서 전사한 아른그림 왕과 다른 모든 병사들을 추모하기 위해 세워졌습니다.', `MaleText_loc4`='这件霍迪尔号角的仿制品是为了纪念安格里姆国王以及所有在落雷谷之战中牺牲的巨人而造的。', `MaleText_loc5`='霍迪爾號角的外觀象徵了我們對安格林王的緬懷與其他在雷殞之地大戰中死去的人們。', `MaleText_loc7`='Esta copia del Cuerno de Hodir se alza en memoria del Rey Arngrim y todos los demás que perecieron en la batalla de Truenotoño.' WHERE `ID`=30792;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 짐승처럼 대하다니, 저주를 받아라!', `MaleText_loc4`='该死的！你不能把我当牲口一样对待！', `MaleText_loc5`='去你的! 你別想把我當成怪獸用!', `MaleText_loc7`='¡Malditas! ¡No me trataréis como a una bestia!' WHERE `ID`=30793;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 그만! 네 녀석의 버르장머리를 고쳐주마!', `MaleText_loc4`='够了！我要教你学会懂礼貌！', `MaleText_loc5`='夠了!我會教你這個混蛋一點禮貌!', `MaleText_loc7`='¡Basta! ¡Te enseñaré modales, $gmozo:moza;!' WHERE `ID`=30794;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노예처럼 사느니 죽을 때까지 싸우겠다!', `MaleText_loc4`='我宁愿战死，也不会为了苟活而去做奴隶！', `MaleText_loc5`='我寧願活著戰死也不要當俘虜!', `MaleText_loc7`='¡Prefiero morir luchando que vivir como un esclavo!' WHERE `ID`=30795;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일터로... 돌아가야...', `MaleText_loc4`='回去……工作……', `MaleText_loc5`='回...去工作...', `MaleText_loc7`='Volved... al trabajo...' WHERE `ID`=30796;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우릴 짐승보다 더 심하게 취급하다니!', `MaleText_loc4`='在你眼里，我们连牲口都不如！', `MaleText_loc5`='你對我們比對畜生還糟!', `MaleText_loc7`='¡Nos tratas peor que a animales!' WHERE `ID`=30797;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언젠가는...복수해줄 테다.', `MaleText_loc4`='总有一天……我们要复仇。', `MaleText_loc5`='有一天...我們會報仇的。', `MaleText_loc7`='Algún día obtendremos venganza... algún día.' WHERE `ID`=30798;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='문제를 일으킬 생각은 없지만, 이곳에 아무런 변화가 없다면 직접 반란을 일으키는 수밖에 없다.', `MaleText_loc4`='我不想惹麻烦，但是如果这里的情况还得不到改善，很快就会发生暴动的。', `MaleText_loc5`='我不想製造麻煩，但要是這裡情況沒改變的話，你很快就得處理一場暴動了。', `MaleText_loc7`='No quiero causar problemas, pero si las cosas no cambian por aquí, vas a tener una insurrección entre manos.' WHERE `ID`=30799;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 같으면 좀 더 조심했을 것이다, 힐드니르여. 네 푸른 낯짝을 두들겨줄 수 있다면 몇 명쯤은 희생되어도 좋다.', `MaleText_loc4`='海德尼尔，你们最好小心一点。只要能打扁你们那漂亮的蓝色脸蛋儿，搭上几条性命也无所谓。', `MaleText_loc5`='我要是你的話，我會小心點，海迪尼爾。要是能打爛你漂亮的藍臉，我可不怕多死幾個人。', `MaleText_loc7`='Hyldnir, yo en tu lugar tendría cuidado. No nos preocupa perder algunos hombres si con ello logramos machacar sus bonitas caras azules.' WHERE `ID`=30800;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 네 녀석을 향한 경고일 뿐이다. 한 번만 더 동료를 공격하는 날엔 쥐도 새도 모르게 처치해주마.', `MaleText_loc4`='我警告你，如果你继续殴打我们，我们会趁你睡觉的时候杀死你。', `MaleText_loc5`='這只是個警告，混蛋。你要是再攻擊我們，我就會在睡夢中殺了你。', `MaleText_loc7`='Esto es solo una advertencia, muchacha. Si volvéis a atacar a uno de los nuestros, os mataremos mientras dormís.' WHERE `ID`=30801;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들을 잡아라!', `MaleText_loc4`='抓住他们！', `MaleText_loc5`='抓住他們!', `MaleText_loc7`='¡Cogedlos!' WHERE `ID`=30802;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙네, 고마워! 이 시퍼런 미치광이 여인들로부터 이제 벗어날 수 있겠군!', `MaleText_loc4`='谢谢，谢谢你！总算能摆脱这些蓝皮肤的疯女人了！', `MaleText_loc5`='謝謝你，謝謝你!擺脫那些瘋狂藍婆子的時刻終於到了!', `MaleText_loc7`='¡Gracias, gracias! ¡Es hora de alejarse de estas locas mujeres azules!' WHERE `ID`=30803;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 도와드릴까요?', `MaleText_loc4`='我能帮你什么忙吗？', `MaleText_loc5`='我能幫你做什麼?', `MaleText_loc7`='¿Qué puedo hacer por ti?' WHERE `ID`=30804;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 작은 녹색 녀석은 광산에서 쓸모가 없었다. 어쨌거나 이 녀석은 전투 전 준비 운동에 적절하게 사용할 수 있을 거다.', `FemaleText_loc4`='这个绿皮肤的小鬼根本派不上用处。不过没关系，他可以在作战前充当热身的对象。', `FemaleText_loc5`='這隻小綠狗在礦坑裡幫不上什麼忙。沒關係，牠可以用在戰爭前的暖身。', `FemaleText_loc7`='Este patético cachorro verde era inútil en las minas. Da igual, servirá de calentamiento para la batalla.' WHERE `ID`=30805;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비 운동은 넘어가지... 너와 같은 자와 싸우는 게 너무 무서운 거 아닌가?', `MaleText_loc4`='你还需要热身吗……莫非你害怕面对与你同等体型的对手？', `MaleText_loc5`='跳過暖身吧，姊妹...還是你很害怕面對體型跟你一樣大的敵人?', `MaleText_loc7`='Sáltate el calentamiento, hermana... ¿o te da demasiado miedo enfrentarte a alguien de tu tamaño?', `FemaleText_loc1`='준비 운동은 넘어가지... 너와 같은 자와 싸우는 게 너무 무서운 거 아닌가?', `FemaleText_loc4`='你还需要热身吗……莫非你害怕面对与你同等体型的对手？', `FemaleText_loc5`='跳過暖身吧，姊妹...還是你很害怕面對體型跟你一樣大的敵人?', `FemaleText_loc7`='Sáltate el calentamiento, hermana... ¿o te da demasiado miedo enfrentarte a alguien de tu tamaño?' WHERE `ID`=30806;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='난 아무것도 두렵지 않다. 어디 해 보자!', `FemaleText_loc4`='我什么都不怕——来吧！', `FemaleText_loc5`='我不怕任何東西 -- 開始吧!', `FemaleText_loc7`='No le tengo miedo a nada, ¡vamos!' WHERE `ID`=30807;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가장 강한 자가 승리할 것이다!', `FemaleText_loc4`='强者将获得胜利！', `FemaleText_loc5`='願最傑出的人能夠獲勝!', `FemaleText_loc7`='¡Que gane la mejor!' WHERE `ID`=30808;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='행운을 빈다... 그거라도 있어야 할 테니 말이다!', `FemaleText_loc4`='祝你好运……你需要的就是运气了！', `FemaleText_loc5`='祝你好運...你會需要的!', `FemaleText_loc7`='Buena suerte... ¡la necesitarás!' WHERE `ID`=30809;
