UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서, $n! 실망시키지 말라고!', `MaleText_loc4`='挺住，$n！别让我失望！', `MaleText_loc5`='快上，$n!別讓我失望!', `MaleText_loc7`='¡Vamos, $n! ¡No me falles!', `FemaleText_loc1`='$n! 우릴 실망시키지 마!', `FemaleText_loc4`='挺住，$n！别让我失望！', `FemaleText_loc5`='快上，$n!別讓我失望!', `FemaleText_loc7`='¡Vamos, $n! ¡No me falles!' WHERE `ID`=30820;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘 싸우는구나, 작은 이여. 지금은 내가 졌다. 장담하건대 우리는 다시 만나리라. 그때는 내가 좀 더 나은 모습을 보여주리라!', `FemaleText_loc4`='打得不错啊，小家伙。我输了。我们还会再见面的。下次我一定会做好充分的准备。', `FemaleText_loc5`='你打的很好，小個子。我現在被擊敗了。我跟你保證，我們將會重逢。到那個時候，我會有更完善的準備!', `FemaleText_loc7`='Luchas bien para alguien tan pequeño. He sido derrotada, por ahora. Te aseguro que pronto volveremos a encontrarnos. ¡Y cuando eso suceda, estaré mejor preparada!' WHERE `ID`=30821;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='크으으으으윽! 사지를 못 쓰게 해 주겠어!', `FemaleText_loc4`='啊！！！！我要宰了你！', `FemaleText_loc5`='嘎啊啊啊!我打斷你的腿!', `FemaleText_loc7`='¡Grrrrr! ¡Haré que te arrodilles!' WHERE `ID`=30822;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신도 리치 왕에게 자신을 증명이라 하러 오셨나요?$B$B이건 참 옛날 방식이잖아요. 안 그래요? 싸우고 살아남으라니 말이에요.', `FemaleText_loc4`='你也想向巫妖王证明自己的实力吗？$B$B你不觉得这样的方式有点过时吗？非要争个你死我活吗？', `FemaleText_loc5`='你也來向巫妖王證明自己?$B$B你不覺得這樣做太過時了嗎?得拼個你死我活?', `FemaleText_loc7`='¿Tú también estás aquí para demostrarle tu valía al Rey Exánime?$B$BEs algo arcaico, ¿no crees? ¿Tener que luchar y sobrevivir?' WHERE `ID`=30823;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이봐요, 당신 알아보겠어요! 제가 여기 왔으니 감사해야 할 거예요. 그 순간이동 사고가 제 일생 중 가장 멋진 일이었어요. $B$B북풍의 땅으로 다시 돌아간다면 제 고집쟁이 바른 생활 짝꿍에게 나는 더 높은 세상으로 올라왔다고 전해주세요!', `FemaleText_loc4`='嘿，我认识你！我要感谢你把我送到这里。那次传送事故是我最美好的体验。$B$B如果你有机会回到北风苔原的话，告诉那个自以为是的复制品，我已经取得了相当大的成就！', `FemaleText_loc5`='嘿，是你!我想你應該很感激我在這裡。那個傳送意外可是我這輩子發生過最好的事情。$B$B要是你都能在北風凍原找到路，讓那個偽善的複製笨蛋知道我在這個世界上可還是有做事的!', `FemaleText_loc7`='¡Oye, yo te conozco! Supongo que debo agradecerte que yo esté aquí. Ese accidente en el teletransporte ha sido lo mejor que me ha pasado.$B$BSi vuelves a la Tundra Boreal, dile a mi copia tonta y santurrona que he ascendido un poco en la vida.' WHERE `ID`=30824;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미안합니다, 팅키. 하지만, 저는 여기서 해야 할 일이 있는 데 당신 때문에 정신이 너무 사납군요.', `MaleText_loc4`='抱歉，丁奇。我有事要办，不能陪你。', `MaleText_loc5`='抱歉，汀基，我不能讓你打攪我，我在作正事。', `MaleText_loc7`='Lo siento, Mañosa, pero no puedo permitir que me distraigas mientras hago lo que debe hacerse.', `FemaleText_loc1`='미안해요, 팅키. 하지만, 저는 여기서 해야 할 일이 있는 데 당신 때문에 정신이 너무 사납네요.', `FemaleText_loc4`='抱歉，丁奇。我有事要办，不能陪你。', `FemaleText_loc5`='抱歉，汀基，我不能讓你打攪我，我在作正事。', `FemaleText_loc7`='Lo siento, Mañosa, pero no puedo permitir que me distraigas mientras hago lo que debe hacerse.' WHERE `ID`=30825;
