UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쓰디 쓴 에일 맥주 있어요! 쓰디 쓴 에일 맥주 있습니다!', `MaleText_loc4`='痛苦啤酒！来买点冰镇的痛苦啤酒吧！', `MaleText_loc5`='苦痛麥酒!冰涼的苦痛麥酒在這買!', `MaleText_loc7`='¡Cerveza de angustia! ¡Aquí hay cerveza de angustia fría!', `FemaleText_loc1`='쓰디 쓴 에일 맥주 있어요! 쓰디 쓴 에일 맥주 있습니다!', `FemaleText_loc4`='痛苦啤酒！来买点冰镇的痛苦啤酒吧！', `FemaleText_loc5`='苦痛麥酒!冰涼的苦痛麥酒在這買!', `FemaleText_loc7`='¡Cerveza de angustia! ¡Aquí hay cerveza de angustia fría!' WHERE `ID`=30835;
