UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피요른의 모루가 던 니펠렘에서 피요른과 그의 군대가 이뤄낸 승리의 상징으로서 두드러진 모습으로 서 있습니다.$b$b당신의 행동이 이 세계에 영속적인 효과가 있었다는 사실에 미소가 지어지는 걸 어쩔 수 없습니다.', `MaleText_loc4`='弗约恩的铁砧被摆放在丹尼芬雷最显然的位置，象征着他们击败弗约恩以及冰霜巨人大军的战绩。$b$b你忍不住笑了起来，你的举动竟然对世界产生了如此深远的影响。', `MaleText_loc5`='在丹尼弗蘭聳立的斐雍之砧現在是斐雍與他的軍隊的勝利象徵。$b$b你無法克制自己的微笑，沒想到自己的行動對世界有這麼大的影響。', `MaleText_loc7`='El Yunque de Fjorn se alza de forma prominente en Dun Niffelem como un símbolo de su victoria sobre Fjorn y sus ejércitos.$B$BNo puedes evitar sonreír al saber que tus acciones han tenido este efecto duradero en el mundo.' WHERE `ID`=30837;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주군과 함께 전장에 참여하게 되어 영광입니다.', `MaleText_loc4`='能与您并肩作战是我的荣幸，国王陛下。', `MaleText_loc5`='跟你一起作戰是我的榮幸，陛下。', `MaleText_loc7`='Es un honor compartir el campo de batalla contigo, mi señor.' WHERE `ID`=30838;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰하트 왕 만세!', `MaleText_loc4`='向雷心国王致敬！', `MaleText_loc5`='風暴之心國王萬歲!', `MaleText_loc7`='¡Larga vida al rey Cuoretormenta!' WHERE `ID`=30839;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서리 거인과의 싸움 이후로 이 같은 전투는 처음입니다!', `MaleText_loc4`='自从冰霜巨人一战后，很久没有经历过这样激烈的战事了！', `MaleText_loc5`='從霜巨人以後就沒看過這樣的戰爭了!', `MaleText_loc7`='¡No había visto una batalla así desde los gigantes de escarcha!' WHERE `ID`=30840;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들을 가만두지 않겠습니다!', `MaleText_loc4`='我们不会让敌人轻易得手的，陛下！', `MaleText_loc5`='我們會讓他們很忙的，長官!', `MaleText_loc7`='¡Les mantendremos ocupados, señor!' WHERE `ID`=30841;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 저들도 폭풍기수를 두려워하게 될 겁니다!', `MaleText_loc4`='就在今天，风暴骑士会让他们尝到恐惧的滋味！', `MaleText_loc5`='今天讓他們學會害怕風暴騎兵!', `MaleText_loc7`='¡Hoy aprenderán a temer a los jinetes de la tormenta!' WHERE `ID`=30842;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왕께서 저희를 직접 훈련하신 보람이 있습니다!', `MaleText_loc4`='你对我们的训练是卓有成效的，陛下！', `MaleText_loc5`='你給我們的訓練的成果展現了，長官!', `MaleText_loc7`='¡El entrenamiento que nos diste funciona, señor!' WHERE `ID`=30843;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전장에 다시 돌아오니 기분이 좋습니다.', `MaleText_loc4`='再次投身激烈的战斗，这种感觉真好。', `MaleText_loc5`='重新回到激戰現場的感覺真不錯。', `MaleText_loc7`='Es bueno volver a estar donde se encuentra toda la acción.' WHERE `ID`=30844;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강력한 왕이시여, 저들에게 한 수 가르쳐 주십시오!', `MaleText_loc4`='国王陛下，您拥有最强大的力量——让他们见识一下吧！', `MaleText_loc5`='你是我們之中最強大的 - 給他們看看這是怎麼辦到的，國王陛下!', `MaleText_loc7`='Eres el más fuerte de nosotros, ¡muéstrales cómo se hace, mi rey!' WHERE `ID`=30845;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 죽음의 기사는 훈련하지 않습니다. 어리석은 수습생들의 끝없는 질문 공세에 지쳤습니다.$B$B그만 가보세요.', `FemaleText_loc4`='我不再训练死亡骑士了，我受够了那些愚蠢的新兵和他们无穷无尽的提问。$B$B现在，请你走开。', `FemaleText_loc5`='我不再訓練死亡騎士了，我厭倦那些癡呆的新生跟他們無止境的問題了。$B$B現在滾吧。', `FemaleText_loc7`='Ya no entreno a caballeros de la Muerte, me cansé de iniciados cretinos y de sus constantes preguntas.$B$BAhora, largo.' WHERE `ID`=30846;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='외래종 금속 견본이 감지되었습니다.', `MaleText_loc4`='检测到不明金属样本。', `MaleText_loc5`='偵測到不明金屬物體來源。', `MaleText_loc7`='Detectado espécimen metálico de origen extraño.' WHERE `ID`=30847;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분석을 시작합니다...', `MaleText_loc4`='开始分析……', `MaleText_loc5`='開始分析...', `MaleText_loc7`='Comenzando análisis...' WHERE `ID`=30848;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 금속 견본은 사로나이트와 무쇠 합금 물질임이 확인되었습니다.', `MaleText_loc4`='确认样本为萨隆邪铁与铁的合金。', `MaleText_loc5`='物體確認為薩鋼與鐵的合金。', `MaleText_loc7`='Espécimen identificado como una aleación de saronita y hierro.' WHERE `ID`=30849;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 견본에 사용된 광석은 아제로스의 지각 깊은 곳에서 생겨났으며 최근에 발굴되었습니다.', `MaleText_loc4`='该样品中的矿石成分来自艾泽拉斯的地壳深处，这种矿石是最近才被挖掘出来的。', `MaleText_loc5`='這個樣本裡所含的礦石原本深藏於艾澤拉斯的地底裡，是最近才出土的。', `MaleText_loc7`='El mineral utilizado en esta muestra surgió en las profundidades de la corteza de Azeroth y ha sido desenterrado recientemente.' WHERE `ID`=30850;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 견본에 들어 있는 사로나이트는 거의 순수한 광석 자체입니다. 이와 같은 광석은 본래 아제로스의 지면에서 발견되지 않습니다.', `MaleText_loc4`='该样品中萨隆邪铁的纯度非常高。在自然状态下，这种矿石是不会出现在艾泽拉斯表面的。', `MaleText_loc5`='這個樣本裡的薩鋼幾乎沒有雜質。艾澤拉斯地表上不會自然地產生這種礦石。', `MaleText_loc7`='La saronita de esta muestra es casi pura. Minerales como este no aparecen de forma natural en la superficie de Azeroth.' WHERE `ID`=30851;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오누준이 이렇게 허접스러운 존재한테 지다니!', `MaleText_loc4`='奥努森被迄今为止最丑陋的人打败了！', `MaleText_loc5`='奧努祖被有史以來最醜的人打敗了!', `MaleText_loc7`='¡Onu''zun es derrotado por la persona más fea que existe!' WHERE `ID`=30852;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오누준 지금 떠난다. 보고 싶다고 징징 짜지는 마라.', `MaleText_loc4`='奥努森该离开了。你会想念我的。', `MaleText_loc5`='奧努祖要走了。你會想我的。', `MaleText_loc7`='Ono''zun irse ya. Tú echarme de menos.' WHERE `ID`=30853;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 광석은 강력하고 악의에 찬 힘으로만 생성할 수 있습니다. 더 자세한 정보를 얻고자 정보 저장고에 접속을 시도합니다...', `MaleText_loc4`='只有强大而邪恶的力量才能创造出这种矿石。尝试访问数据库，搜索更多信息……', `MaleText_loc5`='這種礦石一定是受到了強大、惡毒的外力才能變成這樣。嘗試連線資料庫以獲得更多資訊...', `MaleText_loc7`='Este mineral solo lo puede haber creado una fuerza malévola y poderosa. Intentando acceder a los bancos de datos para obtener más información...' WHERE `ID`=30854;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오누준이 최고다! 누가 삼인자라고 했나! 너는 이인자다!', `MaleText_loc4`='奥努森第一！你第二！', `MaleText_loc5`='奧努祖第一名!你第二!', `MaleText_loc7`='¡Onu''zun ser número uno! ¡Tú ser número dos!' WHERE `ID`=30855;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오누준이 곧 송장으로 만들어주마!', `MaleText_loc4`='奥努森要宰了你！', `MaleText_loc5`='奧努祖要殺死你!', `MaleText_loc7`='¡Onu''zun te va a matar hasta que mueras!' WHERE `ID`=30856;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오누준 브리쿨에 도전하고 용사 명단에 이름을 올리려 오누준 여기 왔다.$B$B오누준이 발할라스에서 싸워 이기면, 오누준 리치 왕께 충성하게 된다!', `MaleText_loc4`='奥努森来这里挑战维库人，以此提升自己的地位。$B$B然后，奥努森要在瓦哈拉斯战斗并赢得胜利，奥努森要为巫妖王效力！', `MaleText_loc5`='奧努祖要挑戰維酷人，讓自己的排名往上升。$B$B之後當奧努祖在英靈殿上贏的時候，奧努祖就可以侍奉巫妖王了!', `MaleText_loc7`='Ono''zun aquí para desafiar a los vrykul y subir en el escalafón.$B$BDespués de que Ono''zun luche en Valhalas y gane, Ono''zun trabajar para el Rey Exánime' WHERE `ID`=30857;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오누준한테는 안됐지만 그 꿈에서 이제 깨워주겠습니다!', `MaleText_loc4`='奥努森，我要告诉你一个坏消息。那就是，我将粉碎你的梦想！', `MaleText_loc5`='奧努祖，我有個壞消息:你的夢想到此為止了。', `MaleText_loc7`='Tengo malas noticias para ti, Onu''zun: ¡voy a tener que acabar con tus sueños!', `FemaleText_loc1`='오누준한테는 안됐지만 그 꿈에서 이제 깨워주겠어요!', `FemaleText_loc4`='奥努森，我要告诉你一个坏消息。那就是，我将粉碎你的梦想！', `FemaleText_loc5`='奧努祖，我有個壞消息:你的夢想到此為止了。', `FemaleText_loc7`='Tengo malas noticias para ti, Onu''zun: ¡voy a tener que acabar con tus sueños!' WHERE `ID`=30858;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='접근이 거부되었습니다?!', `MaleText_loc4`='拒绝访问？！', `MaleText_loc5`='拒絕連線?!', `MaleText_loc7`='¡¿Acceso denegado?!' WHERE `ID`=30859;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='추가적인 정보는 관리자 로켄의 명령에 의해서만 울두아르 내에 있는 저장고에서 접근할 수 있습니다.', `MaleText_loc4`='要了解更多信息，必须获取守护者洛肯的指令，然后访问奥杜尔的档案。', `MaleText_loc5`='在洛肯守望者的命令之下，請到奧杜亞的檔案庫裡才能連線檢索進一步的資訊。', `MaleText_loc7`='Solo se puede obtener más información desde los archivos de Ulduar y con órdenes del guardián Loken.' WHERE `ID`=30860;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명령을 완료했습니다. 대기 상태로 전환합니다.', `MaleText_loc4`='指令完成。返回待机模式。', `MaleText_loc5`='目標完成。回復成待機狀態。', `MaleText_loc7`='Directiva completada. Volviendo al modo de espera.' WHERE `ID`=30861;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='누가 그분께 목숨을 바치겠느냐?', `FemaleText_loc4`='你们当中有谁愿意献身？', `FemaleText_loc5`='你們當中有誰願意獻身?', `FemaleText_loc7`='¿Quién de ustedes es leal?' WHERE `ID`=30862;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 생명을 주군께 바칩니다!', `MaleText_loc4`='我将自己献给主人！', `MaleText_loc5`='我獻身於主上!', `MaleText_loc7`='Me entrego al maestro', `FemaleText_loc1`='제 생명을 주군께 바치겠어요!', `FemaleText_loc4`='我将自己献给主人！', `FemaleText_loc5`='我獻身於主上!', `FemaleText_loc7`='Me entrego al maestro' WHERE `ID`=30863;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 도와 드릴까요?', `MaleText_loc4`='我能帮什么忙吗？', `MaleText_loc5`='有什麼需要我幫忙的嗎?', `MaleText_loc7`='¿Cómo puedo ayudarte?', `FemaleText_loc1`='어떻게 도와 드릴까요?', `FemaleText_loc4`='我能帮什么忙吗？', `FemaleText_loc5`='有什麼需要我幫忙的嗎?', `FemaleText_loc7`='¿Cómo puedo ayudarte?' WHERE `ID`=30864;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, $n 님. 이곳은 관리인 미미르 님의 작업장입니다.', `MaleText_loc4`='你好，$n。这里是守护者米米尔的工作室。', `MaleText_loc5`='日安，$n。這是守護者彌米爾的工坊。', `MaleText_loc7`='Saludos, $n. Este es el taller del guardián Mimir.' WHERE `ID`=30865;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이상한 갑옷 조각을 발견했습니다. 이게 뭔지 알려줄 수 있습니까?', `MaleText_loc4`='我发现了这块奇怪的护甲板。你知道这玩意儿的来历吗？', `MaleText_loc5`='我找到這塊奇怪護甲板。你可以給我一些它的資訊嗎?', `MaleText_loc7`='He encontrado esta extraña placa de armadura. ¿Puedes contarme más sobre ella?', `FemaleText_loc1`='이상한 갑옷 조각을 발견했습니다. 이게 뭔지 알려줄 수 있나요?', `FemaleText_loc4`='我发现了这块奇怪的护甲板。你知道这玩意儿的来历吗？', `FemaleText_loc5`='我找到這塊奇怪護甲板。你可以給我一些它的資訊嗎?', `FemaleText_loc7`='He encontrado esta extraña placa de armadura. ¿Puedes contarme más sobre ella?' WHERE `ID`=30866;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 가지 확실한 점은 이 금속의 크기, 두께, 볼트 구멍이 거대한 구조물을 위한 갑옷에 사용된다는 겁니다.', `MaleText_loc4`='我敢肯定的是：从护甲板的尺寸、厚度以及螺丝孔的位置来看，它肯定是某个巨型装置的护甲。', `MaleText_loc5`='只有一件事情是確定的:這個裝甲的尺寸、厚度跟彈痕點都指向了這是超巨型生物在用的物品。', `MaleText_loc7`='Una cosa es segura: el tamaño, el grosor y los agujeros para los clavos de esta placa apuntan a que formaba parte de la armadura de una estructura colosal.' WHERE `ID`=30867;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네에게 줄 에일 맥주는 없어, $n.', `MaleText_loc4`='我不能再卖啤酒给你了，$n。', `MaleText_loc5`='你不能再喝麥酒了，$n。', `MaleText_loc7`='Ya no hay más alcohol para ti, $n.', `FemaleText_loc1`='당신에게 줄 에일 맥주는 없어요, $n.', `FemaleText_loc4`='我不能再卖啤酒给你了，$n。', `FemaleText_loc5`='你不能再喝麥酒了，$n。', `FemaleText_loc7`='Ya no hay más alcohol para ti, $n.' WHERE `ID`=30868;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='패배했군, $n. 자네에게 줄 에일 맥주는 없어.', `MaleText_loc4`='你已经喝得够多了，$n。我不能再卖啤酒给你了。', `MaleText_loc5`='你被列為拒絕往來戶，$n。沒有麥酒。', `MaleText_loc7`='Te han cerrado el grifo, $n. No hay más cerveza para ti.', `FemaleText_loc1`='졌군요, $n. 당신에게 줄 에일 맥주는 없어요.', `FemaleText_loc4`='你已经喝得够多了，$n。我不能再卖啤酒给你了。', `FemaleText_loc5`='你被列為拒絕往來戶，$n。沒有麥酒。', `FemaleText_loc7`='Te han cerrado el grifo, $n. No hay más cerveza para ti.' WHERE `ID`=30869;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벌써 많이 마신 것 같은데, $n.', `MaleText_loc4`='我觉得你已经喝得够多了，$n。', `MaleText_loc5`='我覺得你喝夠多麥酒了，$n。', `MaleText_loc7`='$n, creo que ya has bebido bastante.', `FemaleText_loc1`='이미 충분히 마신 것 같네요, $n.', `FemaleText_loc4`='我觉得你已经喝得够多了，$n。', `FemaleText_loc5`='我覺得你喝夠多麥酒了，$n。', `FemaleText_loc7`='$n, creo que ya has bebido bastante.' WHERE `ID`=30870;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미안하네, $n. 벌써 많이 마신 것 같은데.', `MaleText_loc4`='对不起，$n，你已经喝得够多了。', `MaleText_loc5`='抱歉，$n。你暫時不能再喝麥酒了。', `MaleText_loc7`='Lo siento, $n, ya has bebido más que de sobra.', `FemaleText_loc1`='미안해요, $n. 이미 충분히 마신 것 같네요.', `FemaleText_loc4`='对不起，$n，你已经喝得够多了。', `FemaleText_loc5`='抱歉，$n。你暫時不能再喝麥酒了。', `FemaleText_loc7`='Lo siento, $n, ya has bebido más que de sobra.' WHERE `ID`=30871;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미안하네, $n. 에일 맥주는 더 줄 수 없어.', `MaleText_loc4`='对不起，$n，我们不能再卖啤酒给你了。', `MaleText_loc5`='抱歉，$n，我們不能再給你麥酒了。', `MaleText_loc7`='Lo siento, $n, no podemos servirte más alcohol.', `FemaleText_loc1`='미안해요, $n. 에일 맥주는 더 드릴 수 없어요.', `FemaleText_loc4`='对不起，$n，我们不能再卖啤酒给你了。', `FemaleText_loc5`='抱歉，$n，我們不能再給你麥酒了。', `FemaleText_loc7`='Lo siento, $n, no podemos servirte más alcohol.' WHERE `ID`=30872;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='셀레브라스의 홀을 잃어버렸습니다.', `MaleText_loc4`='我把塞雷布拉斯节杖弄丢了。', `MaleText_loc5`='我的塞雷布拉斯權杖掉了。', `MaleText_loc7`='He perdido mi cetro de Celebras.', `FemaleText_loc1`='셀레브라스의 홀을 잃어버렸어요.', `FemaleText_loc4`='我把塞雷布拉斯节杖弄丢了。', `FemaleText_loc5`='我的塞雷布拉斯權杖掉了。', `FemaleText_loc7`='He perdido mi cetro de Celebras.' WHERE `ID`=30873;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사를 드립니다. 이제 어둠의 무기고로 돌아가겠습니다.', `MaleText_loc4`='谢谢你。我准备返回暗影拱顶了。', `MaleText_loc5`='我誠摯的感謝你。現在我要回暗影穹殿了。', `MaleText_loc7`='Te estoy agradecido. Ahora voy a volver a La Cámara de las Sombras.', `FemaleText_loc1`='감사를 드려요. 이제 어둠의 무기고로 돌아가겠어요.', `FemaleText_loc4`='谢谢你。我准备返回暗影拱顶了。', `FemaleText_loc5`='我誠摯的感謝你。現在我要回暗影穹殿了。', `FemaleText_loc7`='Tienes mi agradecimiento. Ahora voy a volver a La Cámara de las Sombras.' WHERE `ID`=30874;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 너무 오래 있었습니다. 어둠의 무기고로 돌아가야만 합니다. 안녕히 계십시오.', `MaleText_loc4`='我耽搁了太多的时间，必须返回暗影拱顶了。再见。', `MaleText_loc5`='我在這耽擱太久了。我一定得回暗影穹殿了，再見。', `MaleText_loc7`='He pasado aquí demasiado tiempo. Debo volver a La Cámara de las Sombras. Hasta luego.', `FemaleText_loc1`='여기서 너무 오래 있었어요. 어둠의 무기고로 돌아가야만 해요. 안녕히 계세요.', `FemaleText_loc4`='我耽搁了太多的时间，必须返回暗影拱顶了。再见。', `FemaleText_loc5`='我在這耽擱太久了。我一定得回暗影穹殿了，再見。', `FemaleText_loc7`='He pasado aquí demasiado tiempo. Debo volver a La Cámara de las Sombras. Hasta luego.' WHERE `ID`=30875;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠의 무기고에서 다시 만납시다.', `MaleText_loc4`='我们还会在暗影拱顶见面的。', `MaleText_loc5`='我們暗影穹殿見。', `MaleText_loc7`='Te veré en La Cámara de las Sombras.', `FemaleText_loc1`='어둠의 무기고에서 다시 만나요.', `FemaleText_loc4`='我们还会在暗影拱顶见面的。', `FemaleText_loc5`='我們暗影穹殿見。', `FemaleText_loc7`='Te veré en La Cámara de las Sombras.' WHERE `ID`=30876;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 정도면 됐습니다. 저는 이제 돌아가겠습니다.', `MaleText_loc4`='我受够了。我要回去了。', `MaleText_loc5`='我已經夠了。我要回去了。', `MaleText_loc7`='Yo ya tengo bastante. Me vuelvo ya.', `FemaleText_loc1`='그 정도면 됐어요. 저는 이제 돌아가겠어요.', `FemaleText_loc4`='我受够了。我要回去了。', `FemaleText_loc5`='我已經夠了。我要回去了。', `FemaleText_loc7`='Yo ya tengo bastante. Vuelvo ya.' WHERE `ID`=30877;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저도 여기 머무르면서 당신과 온 종일 브리쿨 처치 놀이나 하고 싶지만, 남작님께서 제가 어디 갔나 찾으실 겁니다.', `MaleText_loc4`='我很想留下来和你一起对抗维库人，但是我不能让男爵大人担心啊。', `MaleText_loc5`='我也想跟你在這裡殺一天的維酷人，但我確定男爵一定會好奇我跑到哪去了。', `MaleText_loc7`='Me gustaría quedarme y matar contigo vrykuls todo el día, pero estoy seguro de que el barón se preguntará dónde estoy.', `FemaleText_loc1`='저도 여기 머무르면서 당신과 온 종일 브리쿨 처치 놀이나 하고 싶지만, 남작님께서 제가 어디갔나 찾으실 거예요.', `FemaleText_loc4`='我很想留下来和你一起对抗维库人，但是我不能让男爵大人担心啊。', `FemaleText_loc5`='我也想跟你在這裡殺一天的維酷人，但我確定男爵一定會好奇我跑到哪去了。', `FemaleText_loc7`='Me gustaría quedarme y matar contigo vrykuls todo el día, pero estoy segura de que el barón se pregunta dónde estoy.' WHERE `ID`=30878;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 가야만 합니다. 당신은 남아서 저 흉한 잡종 괴물을 더 처치해 주십시오.', `MaleText_loc4`='我必须离开了。你就留在这里多杀几个丑陋的杂种吧。', `MaleText_loc5`='我得走了。待著，幫我多殺點那些狗雜種。', `MaleText_loc7`='He de irme. Tú quédate aquí y mata a más de estos feos idiotas.', `FemaleText_loc1`='정말 가야만 해요.. 당신은 남아서 저 흉한 잡종 괴물을 더 처치해 주세요.', `FemaleText_loc4`='我必须离开了。你就留在这里多杀几个丑陋的杂种吧。', `FemaleText_loc5`='我得走了。待著，幫我多殺點那些狗雜種。', `FemaleText_loc7`='He de irme. Tú quédate aquí y mata a más de estos feos idiotas.' WHERE `ID`=30879;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 갑니다. 저놈들한테 잡히지 않도록 조심하십시오. 그렇지 않으면 당신을 국 끓여먹을 테니까 말입니다!', `MaleText_loc4`='我该走了。别被他们抓住了，不然他们会把你煮了的！', `MaleText_loc5`='該走了。別讓他們抓到你，不然你就要變成燉肉了!', `MaleText_loc7`='Hora de irse. ¡No les dejes que te capturen o te echarán al cocido!', `FemaleText_loc1`='정말 가요. 저놈들한테 잡히지 않도록 조심하세요. 그렇지 않으면 당신을 국 끓여먹을 테니까 말이에요!', `FemaleText_loc4`='我该走了。别被他们抓住了，不然他们会把你煮了的！', `FemaleText_loc5`='該走了。別讓他們抓到你，不然你就要變成燉肉了!', `FemaleText_loc7`='Hora de irse. ¡No les dejes que te capturen o te echarán al cocido!' WHERE `ID`=30880;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 떠납니다. 당신이 저를 구해준 사실을 남작님께 알려 드리겠습니다.', `MaleText_loc4`='我要回去了。我会告诉男爵大人，是你救了我的性命。', `MaleText_loc5`='我要回頭了。我會讓男爵知道是你放了我。', `MaleText_loc7`='Me vuelvo ya. Le diré al barón que me has liberado.', `FemaleText_loc1`='지금 떠나요. 당신이 저를 구해준 사실을 남작님께 알려 드리겠어요.', `FemaleText_loc4`='我要回去了。我会告诉男爵大人，是你救了我的性命。', `FemaleText_loc5`='我要回頭了。我會讓男爵知道是你放了我。', `FemaleText_loc7`='Me vuelvo ya. Le diré al barón que me has liberado.' WHERE `ID`=30881;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기, 당신 말입니다! 브리쿨에게 열쇠가 있습니다. 그들을 처치하고 열쇠를 구해서 좀 와주십시오. 이렇게 지독한 우리 안에서 나가게 해달란 말입니다!', `MaleText_loc4`='嘿！维库人身上有钥匙。杀了他们，拿到钥匙，把我从笼子里放出去！', `MaleText_loc5`='嘿，就是你。那些維酷人身上有鑰匙。殺了他們，把鑰匙拿過來，把我放出這個該死的監獄去。', `MaleText_loc7`='¡Oye tú! Los vrykul tienen llaves. Mátalos, consigue una llave, ven aquí, ¡y sácame de esta maldita jaula!', `FemaleText_loc1`='저기요, 당신 말이에요! 브리쿨에게 열쇠가 있어요. 그들을 처치하고 열쇠를 좀 구해와 주세요. 이 빌어먹을 우리 안에서 나가게 해달란 말입니다!', `FemaleText_loc4`='嘿！维库人身上有钥匙。杀了他们，拿到钥匙，把我从笼子里放出去！', `FemaleText_loc5`='嘿，就是你。那些維酷人身上有鑰匙。殺了他們，把鑰匙拿過來，把我放出這個該死的監獄去。', `FemaleText_loc7`='¡Oye tú! Los vrykul tienen llaves. Mátalos, consigue una llave, ven aquí, ¡y sácame de esta maldita jaula!' WHERE `ID`=30882;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='열쇠를 손에 넣으면 이리 오십시오. 이 자물쇠를 여는 열쇠입니다.', `MaleText_loc4`='拿到钥匙，来到笼子面前，打开锁。', `MaleText_loc5`='它有鑰匙。它過來。它開了鎖。', `MaleText_loc7`='Consigue la llave. Viene aquí. Abre la cerradura.', `FemaleText_loc1`='열쇠를 손에 넣으면 이리 오세요. 이 자물쇠를 여는 열쇠거든요.', `FemaleText_loc4`='拿到钥匙，来到笼子面前，打开锁。', `FemaleText_loc5`='它有鑰匙。它過來。它開了鎖。', `FemaleText_loc7`='Consigue la llave. Viene aquí. Abre la cerradura.' WHERE `ID`=30883;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 이 빌어먹을 우리에서 나갈 수 있게 폭파시킬 수 있다고 생각하십니까?', `MaleText_loc4`='你能打开笼子，放我出去吗？', `MaleText_loc5`='你快想想要怎麼救我出去?', `MaleText_loc7`='¿Crees que puedes sacarme de esta jaula?', `FemaleText_loc1`='제가 이 빌어먹을 우리에서 나갈 수 있게 폭파시킬 수 있다고 생각하세요?', `FemaleText_loc4`='你能打开笼子，放我出去吗？', `FemaleText_loc5`='你快想想要怎麼救我出去?', `FemaleText_loc7`='¿Crees que puedes sacarme de esta jaula?' WHERE `ID`=30884;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다행인 것은 제가 추위를 잘 안 탄다는 점입니다.', `MaleText_loc4`='幸运的是，冰冷的死亡还没有真正降临。', `MaleText_loc5`='好處是我不覺得冷。', `MaleText_loc7`='Menos mal que no siento el frío.', `FemaleText_loc1`='다행인 것은 제가 추위를 잘 안 탄다는 점이에요.', `FemaleText_loc4`='幸运的是，冰冷的死亡还没有真正降临。', `FemaleText_loc5`='好處是我不覺得冷。', `FemaleText_loc7`='Menos mal que no siento el frío.' WHERE `ID`=30885;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 여기 우리 안에 있습니다. 안 보려고 해도 안 볼 수 없습니다!', `MaleText_loc4`='我被关在这里啊。你不会看不见的！', `MaleText_loc5`='我就在這裡的牢籠裡。你不會看不到吧!', `MaleText_loc7`='Estoy aquí arriba, en esta jaula. ¡No tiene pérdida!', `FemaleText_loc1`='전 여기 우리 안에 있어요! 안 보려고 해도 안 볼 수 없잖아요!', `FemaleText_loc4`='我被关在这里啊。你不会看不见的！', `FemaleText_loc5`='我就在這裡的牢籠裡。你不會看不到吧!', `FemaleText_loc7`='Estoy aquí arriba, en esta jaula. ¡Tienes que verla!' WHERE `ID`=30886;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저를 나가게 해주십시오. 그러면 서로 좋은 상대가 될 것 같습니다. 이번 살상 전투는 영광스러운 순간이 될 것입니다!', `MaleText_loc4`='放我出去，我们可以并肩作战啊。那将是一场光荣的杀戮！', `MaleText_loc5`='快讓我出去，我們一起作戰。光榮的屠殺!', `MaleText_loc7`='Sácame y lucharemos juntos. ¡La matanza será gloriosa!', `FemaleText_loc1`='저를 나가게 해주세요. 그러면 서로 좋은 상대가 될 것 같군요. 이번 살상 전투는 영광스러운 순간이 될 것이에요!', `FemaleText_loc4`='放我出去，我们可以并肩作战啊。那将是一场光荣的杀戮！', `FemaleText_loc5`='快讓我出去，我們一起作戰。光榮的屠殺!', `FemaleText_loc7`='Sácame y lucharemos juntos. ¡La matanza será gloriosa!' WHERE `ID`=30887;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='슬리버 남작님께서 저를 꺼내주라고 보내신 분입니까? 마침내 와주셨군요. 그럼 서둘러 주십시오!', `MaleText_loc4`='是斯利文男爵派你来救我的吗？总算盼来了救兵。快！', `MaleText_loc5`='你是史力弗男爵派來救我的嗎?終於來了，快點!', `MaleText_loc7`='¿Te ha mandado el Barón Tajada para que me saques de esta jaula? Al fin. ¡Date prisa!', `FemaleText_loc1`='슬리버 남작님께서 저를 꺼내주라고 보내신 분인가요? 마침내 와주셨군요. 그럼 서둘러 주세요!', `FemaleText_loc4`='是斯利文男爵派你来救我的吗？总算盼来了救兵。快！', `FemaleText_loc5`='你是史力弗男爵派來救我的嗎?終於來了，快點!', `FemaleText_loc7`='¿Te ha mandado el Barón Tajada para que me saques de esta jaula? Al fin. ¡Date prisa!' WHERE `ID`=30888;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 우리에서 꺼내주십시오. 그리고 함께 저놈들이 깨어난 것을 후회하게 해 줍시다.', `MaleText_loc4`='等我离开这个牢笼，我们就要让这帮维库人尝尝厉害，让他们后悔苏醒过来！', `MaleText_loc5`='當你把我救出牢籠之後，我們要讓他們覺得自己沒有被喚醒比較好!', `MaleText_loc7`='Cuando me saques de esta jaula, ¡vamos a hacer que deseen no haber despertado nunca!', `FemaleText_loc1`='이 우리에서 꺼내주세요. 그리고 함께 저놈들이 깨어난 것을 후회하게 해 주자고요!', `FemaleText_loc4`='等我离开这个牢笼，我们就要让这帮维库人尝尝厉害，让他们后悔苏醒过来！', `FemaleText_loc5`='當你把我救出牢籠之後，我們要讓他們覺得自己沒有被喚醒比較好!', `FemaleText_loc7`='Cuando me saques de esta jaula, ¡vamos a hacer que deseen no haber despertado nunca!' WHERE `ID`=30889;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 걱정하지 마세요. 오랫동안 믿어온 사실이... 틀렸다는 게 오히려 다행이지요. 무쇠 드워프들이 원하는 것을 찾게 놔두어서는 안 돼요.', `MaleText_loc4`='别为我担心，孩子。我一直以为岁月会侵蚀我……很高兴我想错了。别让铁矮人找到那件东西。', `MaleText_loc5`='別擔心我，$G小夥子:小姑娘;。我一直以來都以為我必須服老...我很高興我是錯的。別讓那些鐵矮人找到他們想要的東西。', `MaleText_loc7`='No te preocupes por mi $gmuchacho:muchacha;. Siempre he pensado que la edad acabaría conmigo... me alegro de haberme equivocado. No dejes que estos enanos férreos encuentren lo que están buscando.' WHERE `ID`=30890;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어, 폭풍으로 벼려낸 무쇠 드워프의 횡포가 끝이 나는구나!', `MaleText_loc4`='雷铸铁矮人的暴政终于走到头了！', `MaleText_loc5`='最後，風暴冶煉的暴政將會終結!', `MaleText_loc7`='¡Al fin la tiranía de los Tronaforjado llega a su conclusión!' WHERE `ID`=30891;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뒤틀린 시체에서 무쇠 드워프가 튀어나옵니다!', `MaleText_loc4`='雷铸铁矮人从残破的尸体中涌了出来！', `MaleText_loc5`='風暴冶煉矮人從破碎的屍體傾瀉而出!', `MaleText_loc7`='¡Enanos Tronaforjado salen del cadáver destrozado!' WHERE `ID`=30892;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 졸개들이 더는 돌의 생명체들과 동맹들을 공격하지 못할 것이다.', `MaleText_loc4`='你的奴仆将再也不能攻击岩石的子嗣和他们的盟友了。', `MaleText_loc5`='你的爪牙將無法再攻擊石之生物與他們的同盟。', `MaleText_loc7`='Nunca más tus esbirros atacarán a las criaturas de piedra y a sus aliados.' WHERE `ID`=30893;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발두란, 네 운명은 내 손에 있다!', `MaleText_loc4`='我要终结你的性命，瓦杜兰！', `MaleText_loc5`='我就是你的末日，瓦杜然!', `MaleText_loc7`='¡Valduran, soy tu perdición!' WHERE `ID`=30894;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뻔한 놈들! 하긴, 돌 따위가 그보다 낫기를 기대한다는 게 무리지!', `MaleText_loc4`='自以为是的预言家！不过谁能想到，一块岩石也能思考？', `MaleText_loc5`='正如我所料!不過，誰會期待一顆石頭的思考方式像是別的東西呢?', `MaleText_loc7`='¡Qué previsible! Pero, ¿quién espera que una roca no piense como una?' WHERE `ID`=30895;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈이 정 그렇게 싸우고 싶다면, 그 소원을 들어주마. 하지만 네놈이 여기서 하는 짓은 아무것도 무쇠 거대괴수의 완성을 막을 순 없을 것이야!', `MaleText_loc4`='如果你急于开战，我可以满足你。但是，无论你做什么，都无法阻止铁巨人的完成！', `MaleText_loc5`='如果你這麼渴望戰鬥，那我就順從你吧。不過，你得知道你在這做的事情無法阻止鐵巨像的完成!', `MaleText_loc7`='Si tantas ganas tienes de luchar, te daré ese placer. ¡Pero que sepas que nada de lo que hagas impedirá la finalización del coloso de hierro!' WHERE `ID`=30896;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한때 난 모든 걸 가졌었소. 부와 명성, 그리고 최고의 검투사 장비까지... 그리고 어느 날 모든 걸 잃었소.$B$B전투에서 부정행위를 하고 승부를 조작하다 무역회사에 들켜 그만... 끝장나고 말았소.$B$B이제 남은 건, 이 허름한 옷과 상한 간뿐이오.', `MaleText_loc4`='我曾经拥有一切。名望、财富、一整套最棒的角斗士套装……我却亲手毁了这一切。$B$B他们发现我有舞弊行为……进行胜负交易……一切全完蛋了。$B$B如今我一无所有，只剩下这身破烂的衣衫，还有一只坏掉的肝脏。', `MaleText_loc5`='曾經，我擁有一切，名聲、財富、一套最好的鬥士裝備...然而我失去了這一切。$B$B熱砂企業逮到我在比賽中作弊...收賄放水...這都結束了。現在我只剩些破布跟一顆糟糕的肝。', `MaleText_loc7`='Una vez lo tuve todo. Fama, fortuna, el mejor equipo completo de gladiador... y lo eché todo a perder.$B$BCuando el Cártel me descubrió amañando peleas... comerciando con victorias... todo se acabó.$B$BAhora no tengo nada aparte de estos harapos y un hígado enfermo.' WHERE `ID`=30897;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해 봅시다.', `MaleText_loc4`='动手吧。', `MaleText_loc5`='上吧。', `MaleText_loc7`='Hagámoslo.', `FemaleText_loc1`='해 봅시다.', `FemaleText_loc4`='动手吧。', `FemaleText_loc5`='上吧。', `FemaleText_loc7`='Hagámoslo.' WHERE `ID`=30898;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다. 무엇을 도와드릴까요?', `MaleText_loc4`='谢谢。我能帮什么忙吗？', `MaleText_loc5`='謝了，我可以怎麼幫你?', `MaleText_loc7`='Gracias. ¿En qué puedo ayudar?', `FemaleText_loc1`='감사해요. 무엇을 도와드릴까요?', `FemaleText_loc4`='谢谢。我能帮什么忙吗？', `FemaleText_loc5`='謝了，我可以怎麼幫你?', `FemaleText_loc7`='Gracias. ¿Cómo puedo ayudar?' WHERE `ID`=30899;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠의 무기고로 돌아가기 전에 몇 분 동안은 당신 편에서 싸워 드릴 수 있습니다.', `MaleText_loc4`='在返回暗影拱顶之前，我可以协助你作战。', `MaleText_loc5`='在回暗影穹殿之前，我可以跟你一起作戰幾分鐘。', `MaleText_loc7`='Puedo luchar a tu lado durante unos minutos antes de que tenga que volver a La Cámara de las Sombras.', `FemaleText_loc1`='어둠의 무기고로 돌아가기 전에 몇 분 동안은 당신 편에서 싸워 드릴 수 있어요.', `FemaleText_loc4`='在返回暗影拱顶之前，我可以协助你作战。', `FemaleText_loc5`='在回暗影穹殿之前，我可以跟你一起作戰幾分鐘。', `FemaleText_loc7`='Puedo luchar a tu lado durante unos minutos antes de que tenga que volver a La Cámara de las Sombras.' WHERE `ID`=30900;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 고맙소. 당신에게 빚을 졌군.', `MaleText_loc4`='谢谢你，$c。我欠你一份情。', `MaleText_loc5`='謝謝你，$c。我欠你一命。', `MaleText_loc7`='Gracias, $c. Te debo una.', `FemaleText_loc1`='$c|1이여;여;, 고맙소. 당신에게 빚을 졌군.', `FemaleText_loc4`='谢谢你，$c。我欠你一份情。', `FemaleText_loc5`='謝謝你，$c。我欠你一命。', `FemaleText_loc7`='Gracias, $c. Te debo una.' WHERE `ID`=30901;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋았어. 이제 브리쿨 녀석을 좀 쓸어보자고!', `MaleText_loc4`='好极了。我们来杀几个维库人吧！', `MaleText_loc5`='太好了。讓我們一起殺些維酷人!', `MaleText_loc7`='Excelente. ¡Vamos a matar a algunos vrykul!', `FemaleText_loc1`='좋았어. 이제 브리쿨 녀석을 좀 쓸어보자고!', `FemaleText_loc4`='好极了。我们来杀几个维库人吧！', `FemaleText_loc5`='太好了。讓我們一起殺些維酷人!', `FemaleText_loc7`='Excelente. ¡Vamos a matar a algunos vrykul!' WHERE `ID`=30902;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='복수할 시간이다!', `MaleText_loc4`='复仇的时刻到了！', `MaleText_loc5`='復仇的時刻來臨了!', `MaleText_loc7`='¡Es la hora de la venganza!', `FemaleText_loc1`='복수할 시간이다!', `FemaleText_loc4`='复仇的时刻到了！', `FemaleText_loc5`='復仇的時刻來臨了!', `FemaleText_loc7`='¡Es la hora de la venganza!' WHERE `ID`=30903;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이놈의 보호모는 어디에 있는 거지? 그래도 칼은 여기 놔뒀군. 멍청이들.', `MaleText_loc4`='我的头盔呢？呃，至少他们没带走我的剑。这帮蠢货。', `MaleText_loc5`='我那該死的頭盔在哪?嗯，至少他們把我的劍留下了。白癡。', `MaleText_loc7`='¿Dónde está mi condenado yelmo? Bueno, al menos se dejaron aquí mi espada. Idiotas.', `FemaleText_loc1`='이놈의 보호모는 어디에 있는 거지? 그래도 칼은 여기 놔뒀네. 멍청이들.', `FemaleText_loc4`='我的头盔呢？呃，至少他们没带走我的剑。这帮蠢货。', `FemaleText_loc5`='我那該死的頭盔在哪?嗯，至少他們把我的劍留下了。白癡。', `FemaleText_loc7`='¿Dónde está mi condenado yelmo? Bueno, al menos se dejaron aquí mi espada. Idiotas.' WHERE `ID`=30904;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽여라!', `MaleText_loc4`='杀呀！', `MaleText_loc5`='殺!', `MaleText_loc7`='¡Mata!', `FemaleText_loc1`='죽여라!', `FemaleText_loc4`='杀呀！', `FemaleText_loc5`='殺!', `FemaleText_loc7`='¡Mata!' WHERE `ID`=30905;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호디르의 후예여! 당신에게 드리노니...', `MaleText_loc4`='霍迪尔之子！在此，我谦卑地奉上……', `MaleText_loc5`='霍迪爾之子!我恭敬地向您獻上...', `MaleText_loc7`='¡Hijos de Hodir! Humildemente os presento...', `FemaleText_loc1`='호디르의 후예여! 당신에게 드리노니...', `FemaleText_loc4`='霍迪尔之子！在此，我谦卑地奉上……', `FemaleText_loc5`='霍迪爾之子!我恭敬地向您獻上...', `FemaleText_loc7`='¡Hijos de Hodir! Humildemente os presento...' WHERE `ID`=30906;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호디르의 투구!', `MaleText_loc4`='霍迪尔之盔！', `MaleText_loc5`='霍迪爾之盔!', `MaleText_loc7`='¡El Yelmo de Hodir!', `FemaleText_loc1`='호디르의 투구!', `FemaleText_loc4`='霍迪尔之盔！', `FemaleText_loc5`='霍迪爾之盔!', `FemaleText_loc7`='¡El Yelmo de Hodir!' WHERE `ID`=30907;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누구 시죠?$B$B저리 가십시오... 항구에서 일을 너무 많이 했더니 지쳐버렸습니다. 드워프 맥주를 마시면서 신세 한탄 좀 하다가, 낮잠이나 자야겠습니다.', `MaleText_loc4`='你是谁？$B$B走开……港口的建设工作非常繁重，我已经累得筋疲力尽了。现在我要喝上两口矮人啤酒，痛痛快快地哭一场再美美地打个盹儿。', `MaleText_loc5`='你是誰?$B$B走開...我為了港口路的工程精疲力盡。現在是時候喝點矮人麥酒，叫囂一下，然後睡個好覺。', `MaleText_loc7`='¿Quién eres?$B$BLargo... estoy agotado de tanto trabajar en la carretera del puerto. Es hora de beber cerveza enana, dar gritos y echarse la siesta.' WHERE `ID`=30908;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은늑대가 적들을 찾아 뛰쳐나갑니다.', `MaleText_loc4`='座狼一路飞奔，搜索着敌人的踪迹。', `MaleText_loc5`='座狼開始奔馳，四處搜索敵人。', `MaleText_loc7`='El huargo corre en busca de enemigos.' WHERE `ID`=30909;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실체없는 서리 검은늑대가 망설임 없이 계곡으로 향합니다.', `MaleText_loc4`='灵体座狼毫不犹豫地冲进了山谷。', `MaleText_loc5`='以太座狼毫不遲疑的往山谷出發。', `MaleText_loc7`='Sin dudarlo, el huargo etéreo entra al valle.' WHERE `ID`=30910;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은늑대가 잠시 망설이더니 이내 방향을 바꿉니다.', `MaleText_loc4`='座狼在原地转悠了一会儿，然后改变了方向。', `MaleText_loc5`='座狼遲疑了一下，接著換了個方向。', `MaleText_loc7`='El huargo duda un momento y después cambia de dirección.' WHERE `ID`=30911;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은늑대가 잠시 멈추더니 곧 사냥을 계속합니다.', `MaleText_loc4`='在短暂的停留后，座狼继续往前追踪目标。', `MaleText_loc5`='停了一下之後，座狼繼續狩獵。', `MaleText_loc7`='Tras un momento de pausa, el huargo continúa la caza.' WHERE `ID`=30912;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사냥감을 포착한 듯, 검은늑대가 날카로운 이빨을 드러내며 냄새를 쫓습니다.', `MaleText_loc4`='座狼显然有所发现。它露出獠牙，循着气味前进。', `MaleText_loc5`='似乎找到了一點蛛絲馬跡，座狼張牙舞爪地隨著氣味追去。', `MaleText_loc7`='Tras haber encontrado algo, el huargo muestra los colmillos y sigue el rastro.' WHERE `ID`=30913;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사냥감에 접근하자 검은늑대가 으르렁거립니다.', `MaleText_loc4`='接近猎物时，座狼咆哮起来。', `MaleText_loc5`='座狼鎖定了牠的獵物，發出一聲咆哮。', `MaleText_loc7`='El huargo gruñe mientras se aproxima a su presa.' WHERE `ID`=30914;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서리 검은늑대가 길게 짖자 사냥감이 뛰쳐나옵니다!', `MaleText_loc4`='冰霜座狼嗥叫着，它发现了猎物！', `MaleText_loc5`='霜座狼發出一聲嗥叫，使獵物暴露了行蹤!', `MaleText_loc7`='El huargo de escarcha aúlla y descubre a su presa.' WHERE `ID`=30915;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나를 발견했다 이건가? 이제 죽어 줘야겠어!', `MaleText_loc4`='好吧，你找到我了。那么，你去死吧！', `MaleText_loc5`='找到我了，是吧?現在你得去死!', `MaleText_loc7`='Me has encontrado, ¿verdad? ¡Ahora tienes que morir!' WHERE `ID`=30916;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽어라, 서리 친구!', `MaleText_loc4`='死吧，冰霜巨人的朋友！', `MaleText_loc5`='死吧，霜之友人!', `MaleText_loc7`='¡Muere, amigo de la escarcha!' WHERE `ID`=30917;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살아 돌아갈 생각 마라!', `MaleText_loc4`='你没有机会开口说话了！', `MaleText_loc5`='你無法活著把這件事說出去的!', `MaleText_loc7`='¡No vivirás para contarlo, $r!' WHERE `ID`=30918;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='한때는, 숲이 우거진 쿠엘탈라스에 집이 있었지요. 한때는, 가족과 남편과... 아이들이 있었지요. 한때는, 생명이 있는 존재였고 세상 속에 살고 있었지요. 리치 왕이 눈 깜짝할 사이에 그 모든 것을 제게서 앗아가 버렸어요.$B$B비록 내가 직접 그를 칠 힘은 없지만, 반드시 세 배로 복수해 주고 말 거예요!', `FemaleText_loc4`='我曾经拥有一个温暖的家，它就坐落在奎尔萨拉斯苍翠的森林中。我还记得我的丈夫……还有孩子们的笑容。我曾经生活在这个美好的世界。眨眼之间，巫妖王夺走了这一切。$B$B虽然单凭我的力量根本不足以与他抗衡，但是总有一天，我要让他付出三倍的代价！', `FemaleText_loc5`='曾經，我在奎爾薩拉斯的翠綠森林裡有個家。曾經，我有家人，丈夫...孩子。曾經，我存活於這個世界上。巫妖王在一眨眼把這一切都毀了。$B$B雖然我沒有力量能直接攻擊他，但我會要三倍的奉還給他!', `FemaleText_loc7`='Una vez tuve una casa en los frondosos bosques de Quel''Thalas. Una vez tuve una familia, un marido... hijos. Una vez, estaba viva y era una con el mundo. El Rey Exánime me arrebató todo eso en un instante.$B$B¡Aunque no tengo poder para atacarle directamente, haré que pague tres veces por ello!' WHERE `ID`=30919;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드가 그대를 청한다! 리치 왕의 군대를 물리쳐라!', `MaleText_loc4`='部落需要你！击退巫妖王的军队！', `MaleText_loc5`='部落需要你!擊退巫妖王的軍隊!', `MaleText_loc7`='¡La Horda te necesita! ¡Haz retroceder a las fuerzas del Rey Exánime!' WHERE `ID`=30920;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕을 처리하는 일은 시간문제일 뿐이다. 리치 왕은 인간뿐 아니라 아제로스 전체에 위협을 가하고 있도다.$B$B그러나 전쟁을 가벼이 결정해서는 안 된다. 노스렌드로 바로 치고 들어가는 일은 어리석기 짝이 없는 짓이로다. 리치 왕은 분명히 그런 상황을 예상할 테니...$B$B우리가 선택할 수 있는 여러 가지 상황을 신중히 저울질해봐야 한다. 우리 군대는 그 어느 때보다 강력해졌지만, 전술적으로 확실한 결정이 아니라면 무너질 수 있도다.$B$B가로쉬가 상황을 이해한다면 말이지...', `MaleText_loc4`='我们迟早要面对巫妖王的大军。他已经威胁到了整个艾泽拉斯的安全。$B$B但是，远征诺森德的事千万不能草率。贸然闯入极寒之地是愚蠢的行径。巫妖王想必早已做好了战争的准备。$B$B我们必须谨慎行事。没错，我们的军队实力雄厚；但是如果缺乏成熟的战略计划，那么我们终将落败。$B$B要是加尔鲁什明白这一点就好了……', `MaleText_loc5`='對付巫妖王這件事只是時間上的問題。他是對全艾澤拉斯的威脅，不是只是人類。$B$B但，發動戰爭的決定不能輕率。我們會像白癡一樣衝近北裂境。巫妖王期待我們這樣做。$B$B我們的抉擇必須謹慎考量。我們的軍隊比以往都還要強大，但是一個戰術上的錯誤就有可能毀了我們。$B$B要是卡爾洛斯可以了解...', `MaleText_loc7`='Solo era cuestión de tiempo que tuviéramos que ocuparnos del Rey Exánime. Representa una amenaza para todo Azeroth, no solo para los humanos.$B$BPero la decisión de ir a la guerra no debe tomarse a la ligera. Si corriéramos hacia Rasganorte seríamos unos locos. Sin duda, el Rey Exánime ha previsto una acción así.$B$BHay que sopesar bien nuestras opciones. Nuestros ejércitos son más poderosos que nunca, pero un error táctico podría acabar con nosotros.$B$BOjalá Garrosh pudiera entenderlo...' WHERE `ID`=30921;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오그리마를 세운 이래, 호드를 뒤흔들 만한 일은 수도 없이 있었지만, 그때마다 함께 일어나 호드를 무너뜨리려는 그 어떤 세력이든 물리쳐왔다!$B$B하지만 이번은... 이번은 내 힘으로도 어찌할 수 없는 상황이다. 우리 종족이 이 역병으로 고통받는 모습을 지켜보자니 너무나 가슴이 아프구나. 포세이큰에 원조를 구해야겠도다.$B$B호드가 울리는 전쟁의 북소리가 리치 왕의 귓가에 울릴 때가 오겠지만, 아직은 아니다. 스컬지에 복수하기 전에 우리 종족을 돕는 일이 우선이로다.', `MaleText_loc4`='奥格瑞玛建立以来，部落历经磨难，我们一次次地奋起抵抗，击退了那些妄图消灭我们的敌人！$B$B但是，面对眼前的危机……我却无能为力。部落的子民饱受折磨，这惨不忍睹的场景令我痛苦难安。我们必须寻求被遗忘者的帮助。$B$B总有一天，巫妖王会听见震天的战鼓声，不过现在还不是时候。在向天灾军团复仇前，我们要搭救部落的子民。', `MaleText_loc5`='自從奧格瑪建立以來，部落曾經有過許多難關，但是我們總是能起身反擊那些想要毀滅我們的人!$B$B但是現在...這是連我的力量都沒辦法打敗的人。看著我的人民為瘟疫所苦讓我心痛。我必須依賴被遺忘者，尋求他們的幫忙。$B$B巫妖王會聽到部落的戰鼓聲向他靠近，不過時機未到。首先，我們必須幫助人民，再去對天譴軍實行我們的復仇。', `MaleText_loc7`='Desde la fundación de Orgrimmar, la Horda se ha enfrentado a muchas pruebas, ¡pero nos hemos alzado y acabado con cualquiera que quisiera matarnos!$B$BPero esto... esto es algo que ni siquiera mi poder puede derrotar. Me duele profundamente ver a mi gente sufrir por esta plaga. Debo confiar en la ayuda de los Renegados.$B$BEl Rey Exánime oirá acercarse los tambores de guerra de la Horda, pero todavía no. Primero debemos ayudar a nuestro pueblo, después nos vengaremos de la Plaga.' WHERE `ID`=30922;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정한 전사라면 동맹들과 이야기나 하느라 전투를 멈추지 않는 법이오! 이 괴물들을 당장 원래 있던 무덤으로 돌려보냅시다!', `MaleText_loc4`='真正的战士不会停止杀戮！我没功夫和你闲聊！将这些怪物送回坟墓去吧！', `MaleText_loc5`='一個真正的戰士不會在戰鬥中停下來跟他的盟友聊天!把這些巨怪送回他們的墳墓裡!', `MaleText_loc7`='¡Un verdadero guerrero no se detiene en la batalla para hablar con sus aliados! ¡Mandad a esas monstruosidades de vuelta a sus tumbas!' WHERE `ID`=30923;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕을 이 도끼로 처리하고 싶어서 팔이 근질근질하네. 스랄께서는 우리더러 대기하라면서 스컬지가 점점 힘을 키워나가도록 놔두고 계시네. 이런 상황, 더는 참지 않겠네!$B$B리치 왕이 우리를 위협하는 이 상황을 끝내려면 노스렌드로 가서 호드의 힘을 확실히 보여줘야 하네! 우리 병사들은 역병과 스컬지 침략으로 죽어간 이들을 대신하여 기꺼이 복수할 준비가 되었네.$B$B바로 지금이 공격할 때일세!', `MaleText_loc4`='我难以平息心中的怒火，迫不及待地想用手中的利斧劈开巫妖王的脑袋。萨尔只会说什么时机尚未成熟，让我们眼睁睁地看着天灾军团日益壮大。我不会让这种事发生的！$B$B想要解除巫妖王的威胁，就必须集结部落的全部军力，远征诺森德彻底击败他！我们的军队已经整装待发，期盼着为死于侵略的同胞复仇。$B$B反击的时刻已经到了！', `MaleText_loc5`='我的手臂變得煩燥，焦急地等待著能把斧頭劈進巫妖王腦袋的那天。索爾讓我們在這裡枯等，讓天譴軍不斷地成長。我不能接受!$B$B要是我們要中止巫妖王的威脅，我們必須航向北裂境，給他看看部落的力量!我們的軍隊已經準備好了，樂意地為了那些死於瘟疫與戰事之中的人民復仇。$B$B出擊的時候到了!', `MaleText_loc7`='Mis brazos se impacientan, están ansiosos por llevar a mis hachas al cráneo del Rey Exánime. Thrall nos habría hecho esperar y habría permitido que la Plaga se siguiera fortaleciendo. ¡No lo permitiré!$B$BSi queremos acabar con la amenaza del Rey Exánime, ¡debemos navegar hacia Rasganorte y golpearlo con todo el poder de la Horda! Nuestras fuerzas están preparadas y buscan venganza por las muertes que han traído la Plaga y la invasión.$B$B¡El momento de atacar es ahora!' WHERE `ID`=30924;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 두 눈으로 직접 확인하기 전까지는 스랄께서 하는 말을 믿지 않았었소. 오크... 악마의 타락에서 벗어난 존재! 자긍심 넘치는 명예로운 전사들이 이 온전한 땅 위에 머물 곳을 만들었소.$B$B대족장님과 호드에 내 진가를 증명하고 싶소. 아버지께서는 당신이 리치 왕이라 부르는 언데드 골칫거리를 상대하신 적이 없지만, 일러주신 바를 보니 호드에게 무시무시한 위협을 가할 자요. $B$B스랄께 가서 정예 전사들을 이끌고 노스렌드로 가 리치 왕을 물리치도록 해달라고 요청할 생각이오! 하지만 이 역병은 지금도 진행 중이라오.', `MaleText_loc4`='我原本是不信任萨尔的，直到我目睹了真相。兽人……从恶魔的堕落血液中解放出来了！他们在这片土地上站稳了脚跟，重铸氏族的荣耀。$B$B我渴望向萨尔和部落证明自己的实力。虽然我的父亲不曾与巫妖王交手，但是他已经对部落构成了致命的威胁，那就让我来面对他吧！$B$B我会请求萨尔，让我率领最优秀的战士前往诺森德，消灭巫妖王！不过眼前最重要的事情，就是根除亡灵天灾。', `MaleText_loc5`='直到我親眼看到之前，我都不相信索爾。獸人...脫離了惡魔的腐化。驕傲和榮耀的戰士在這塊未馴化的土地上奮鬥。$B$B我渴望像部落跟索爾證明我自己。我的父親從未見過你們稱之為巫妖王的不死威脅，但是他用了所有字彙來形容他們對部落是多麼強大的威脅。$B$B我會懇求索爾讓我帶領他最強的戰士前往北裂境，毀滅巫妖王。但是我們需要先處理這場瘟疫。', `MaleText_loc7`='Jamás creí en Thrall hasta que le vi con mis propios ojos. Orcos... ¡libres de corrupción demoníaca! Guerreros orgullosos y honorables que buscan su lugar en este planeta.$B$BAnsío demostrarle mi valor a Thrall y a la Horda. Mi padre jamás tuvo que ocuparse de esta amenaza no-muerta a la que llamáis el Rey Exánime, pero por lo que parece representa un gran peligro para la Horda.$B$B¡Le rogaré a Thrall que me permita liderar a sus mejores guerreros hacia Rasganorte para acabar con el Rey Exánime! Pero antes hay que solventar esta plaga.' WHERE `ID`=30925;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 보게! 왜 그대는 전투에 참여하지 않나? 저 스컬지 망나니들이 오그리마를 더 망가뜨리기 전에 어서 처치하게!', `MaleText_loc4`='你！为什么不参与战斗？杀死那些天灾士兵，否则他们会给奥格瑞玛带来更大的损失！', `MaleText_loc5`='就是你!你為什麼沒加入戰鬥?在他們對奧格瑪造成更大傷害之前，殺死這些天譴軍團!', `MaleText_loc7`='¡Oye tú! ¿Por qué no estás luchando? ¡Mata a estos horrores de la Plaga antes de que hagan más daño a Orgrimmar!' WHERE `ID`=30926;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가로쉬가 바라는 바가 이해는 되네. 오크라면 싸우고자 하는 강렬한 열망이 핏속에 흐르는 법이니 말이야. 특히 우리 종족을 죽였던 그 적을 상대로라면 더더욱 말일세. 그러나 대족장께서는 전투에서는 힘도 중요하지만, 그만큼 시간과 전략도 중요함을 확인시켜 주셨네.$B$B적절한 때가 왔을 때 우리는 일어설 것일세. 우리 오크는 이제 생각 없이, 악마의 지배를 받는 야만적인 종족이 아닐세. 새로운 호드로 다시 태어났단 말일세.', `MaleText_loc4`='我能理解加尔鲁什的心情。面对这不共戴天的仇敌，所有兽人的心中都燃起了战斗的怒火。但是，酋长反复地强调，战略计划和军队实力都是胜负的决定性因素。$B$B时机成熟时，我们一定会远征诺森德。我们不再是头脑简单，任由恶魔驱使的奴隶。这就是新生的部落。', `MaleText_loc5`='我懂卡爾洛斯要的是什麼。戰鬥的慾望深藏於每個獸人心中，尤其是對那些曾經殺害過我們人民的敵人。但是，大酋長已經證明了時機跟戰略與力量一樣重要。$B$B我們會在時機對的時候出發。我們已經不是一群無心、被惡魔操控的野人了。我們是新的部落。', `MaleText_loc7`='Comprendo los deseos de Garrosh. Todo orco siente una fuerte sed de batalla, especialmente contra un enemigo que ha matado a nuestro pueblo. Pero el Jefe de Guerra ha demostrado una y otra vez que en una batalla, la estrategia es tan importante como la fuerza.$B$BPartiremos cuando sea el momento. Ya no somos una banda de descerebrados salvajes manipulados por demonios. Esta es la nueva Horda.' WHERE `ID`=30927;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 우리가 상대하는 적은 예전 방법으로는 처치할 수 없네. 리치 왕의 역병은 우리 호드의 치유사가 막을 수 있는 수준이 아닐세. 혐오스럽지만, 포세이큰과 그들의 연금술사들만이 유일한 희망이라네.$B$B이 상황을 극복하면 호드는 노스렌드로 진격하여 리치 왕과 그 군대를 무릎 꿇릴 것이라 약속하네!', `MaleText_loc4`='面对亡灵大军，我们无法用传统的手段“杀死”他们。我们也无法治愈巫妖王的诅咒，只能阻止其传播。被遗忘者和他们的炼金师是我们唯一的希望，尽管我很讨厌他们。$B$B如果我们能熬过这一关，我向你保证，部落一定会挥师诺森德，歼灭巫妖王和他的部队！', `MaleText_loc5`='我們面對的敵人沒有辦法以傳統方式殺害。巫妖王的瘟疫是一股我們的醫者沒有辦法阻擋的力量。被遺忘者跟他們的鍊金術師是我們僅存的希望，這也讓我噁心。$B$B要是我們可以撐過的話，我像你保證部落會航向北裂境，讓巫妖王與他的軍隊臣服在我們的腳下!', `MaleText_loc7`='Nos enfrentamos a un enemigo al que no podemos matar con medios tradicionales. La plaga del Rey Exánime es una fuerza que ningún sanador de nuestras filas ha podido detener. Los Renegados y sus alquimistas son nuestra única esperanza, muy a mi pesar.$B$BSi sobrevivimos a esto, prometo que la Horda irá a Rasganorte y doblegará al Rey Exánime y a sus ejércitos.' WHERE `ID`=30928;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네 목숨이 소중하다면, 다음 말은 신중하게 선택하는 게 좋을 거다.$B$B아예 입을 다물겠다? 똑똑하기도 하군. 이제 스컬지를 멸하라!', `FemaleText_loc4`='还想活命的话，你最好小心说话。$B$B沉默？你真明智。去消灭天灾军团吧！', `FemaleText_loc5`='要是你愛惜你的生命的話，我建議你好好想想怎麼說下一句話。$B$B沉默?非常明智。現在去殺光天譴軍吧!', `FemaleText_loc7`='Si valoras tu vida, escoge tus próximas palabras con cuidado.$B$B¿Silencio? Muy inteligente. ¡Ahora destruye a la Plaga!' WHERE `ID`=30929;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='스랄이 아서스에게 얼마나 분노하는지 느낄 수 있지만, 내가 느끼는 분노에 비하면 아무것도 아니지. 우리 포세이큰 만큼 분노했다면, 호드 군대는 벌써 노스렌드를 휩쓸고 그 저주스럽고 얼어붙은 황무지에서 스컬지를 전부 뿌리째 뽑아냈을 거다.$B$B하지만 내가 호드를 이끄는 게 아니니 전쟁 명령을 내릴 수가 없군. 스랄은 상황을 신중하게 따져보고 싶어하지. 지금처럼 직접 행동으로 옮겨야 할 시기에 말이야. 어쨌거나, 우리에게도 때가 올 테니까... 아주 가까운 시일 내에 말이지.', `FemaleText_loc4`='萨尔想必对阿尔萨斯的行径倍感愤怒，但是比起我心中的怨恨来就微不足道了。如果他能体会被遗忘者的心情，我相信部落的大军会把怒火倾泻到诺森德，歼灭那片冰封荒野上的天灾军团。$B$B可惜我不是部落的领导者，不能下令开战。局势紧迫，萨尔却还在权衡利弊得失。不过，战争……已经到了一触即发的关头。', `FemaleText_loc5`='我可以感受到索爾的憤怒，但是與我的相比就遜色了。他就如同被遺忘者的任何一個人一樣地憤怒，部落的軍隊將會在北裂境釋放他們的憤怒，將天譴軍從那詛咒、冰凍的荒地中根絕。$B$B但是我不是領導部落的人，我也不能下達戰爭的指令。索爾希望能夠多考慮一下，不過這只是時間的問題而已。仍然，我們的時機...就要來臨。', `FemaleText_loc7`='Puedo sentir la ira de Thrall contra Arthas, pero no es nada comparada con la mía. Si sintiera la furia de cualquiera de los Renegados, los ejércitos de la Horda desatarían su ira contra Rasganorte y erradicarían a toda la Plaga de ese helado y maldito erial.$B$BPero yo no dirijo la Horda y no puedo ordenar una guerra. Thrall desea sopesar sus opciones, a pesar de que es la hora de actuar. Pero nuestro momento llegará... muy pronto.' WHERE `ID`=30930;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지금의 나를 만든 자는 아서스인 셈이다. 이런 괴로움을 되갚아줄 수 있을 그 날, 그 일 분 일 초를 즐기리라.$B$B포세이큰이 노스렌드에서 스컬지와 맞서 싸우는 순간을 오랫동안 고대해 왔다. 하지만, 호드 연합의 지원이 필요하다. 호드 연합에 속한 다른 종족들이 뒷받침해주지 않는다면 우리는 수적으로 열세임이 틀림없으니 말이다.$B$B최근 아서스가 호드를 공격한 일로 스랄이 얼음왕관에 전쟁을 선포할 결심을 해 주었으면 좋겠구나. 그런 상황이 오면 대족장은 확실히 나의 지원을 받을 수 있으리라.', `FemaleText_loc4`='我的遭遇全拜阿尔萨斯所赐。我要让他尝到被折磨的痛苦滋味。$B$B一直以来，我都盼望着被遗忘者能在诺森德与天灾军团决一死战，但是我们需要部落的支持。我们的军队数量严重不足，必须得到盟友的援助。$B$B阿尔萨斯对部落的这次进攻或许能让萨尔认清局势，最终决定对冰冠冰川宣战。那时，我会毫不犹豫地支持他。', `FemaleText_loc5`='我現在的人生都要歸功於阿薩斯。我將會細細品嚐我還給他的折磨。$B$B我已經期待被遺忘者對天譴軍的戰爭帶到北裂境去很久了，但是我們還是需要部落其他的支援。我們的數量還不太夠，足非我們能夠使其他種族也加入我們的聯軍。$B$B阿薩斯最近對部落的攻擊有希望能夠說服索爾對寒冰皇冠宣戰。要是這一刻真的來臨，我會支持他。', `FemaleText_loc7`='Todo lo que soy se lo debo a Arthas. Saboreo el momento en el que pueda recompensarle todo este tormento.$B$BHe ansiado el momento en el que los Renegados lucharían contra la Plaga de Rasganorte, pero necesitamos la ayuda del resto de la Horda. Nuestro número no es muy grande a menos que lo aumenten las otras razas en nuestra alianza.$B$BEl último ataque de Arthas contra la Horda es probable que termine de convencer a Thrall de que le declare la guerra a Corona de Hielo. Cuando eso suceda, tendrá todo mi apoyo.' WHERE `ID`=30931;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 누군지 아나?! 정말 중요한 인물이시란 말이네! 자네가 나를 스컬지로부터 보호해주어야 하지 않나? 룰루랄라 의미 없이 수다나 떨지 말고 말이야!$B$B나는 용사가 아닐세. 하지만, 자네는 맞지 않나. 그러니 어서 나가보게!', `MaleText_loc4`='你知道我是谁吗？！我是个大人物！你应该保护我免遭天灾军团的袭击，而不是扯一些无意义的鬼话！$B$B我不是战士，而你是。出去迎敌吧！', `MaleText_loc5`='你知道我是誰嗎?!我是個非常重要的人!你應該要保護我遠離天譴軍，而不是嘰嘰喳喳講些沒有意義的廢話!$B$B我不是戰士，但是你是。所以現在給我滾出去!', `MaleText_loc7`='¿Sabes quién soy? ¡Soy una persona muy importante! Se supone que tienes que protegerme de la Plaga, ¡no perder el tiempo con charlas inútiles!$B$BNo soy un luchador, pero tú sí. ¡Así que sal ahí fuera!' WHERE `ID`=30932;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<불안정한 눈빛으로 당신을 훑어보는 퓨트리스>$B$B자네는 보기 드문 $r|1이;가; 아닌가...$B$B대의를 위해 작은 희생을 할 생각은 없나?', `MaleText_loc4`='<普特雷斯用令人不安的眼神打量着你。>$B$B你不是英雄的楷模吗……$B$B你是否愿意为伟大的正义事业而献身？', `MaleText_loc5`='<普崔司用一種使人不安的姿勢打量著你。>$B$B你不就是個很好的樣本嗎...$b$b你有沒有考慮過為更大的目標而奉獻?', `MaleText_loc7`='<Putress te mira de una forma muy perturbadora.>$B$BEres un espécimen muy interesante...$B$B¿Has considerado hacer un sacrificio por el bien mayor?' WHERE `ID`=30933;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 얼마나 놀라운 발견이란 말인가! 왕립 연금술 학회는 리치 왕의 역병에 감춰진 비밀을 풀어내고자 몇 년 동안 씨름을 해왔는데, 마침내 내가 성공했지!$B$B역사에 길이 남을 전환점을 맞이했지만, 아직도 밝혀내야 할 비밀이 많네. 아직 해야 할 실험이 많아... 실험할 주제도 더 있지...$B$B적어도 스컬지 죽음의 요새는 걱정하지 않아도 되네. 얼라이언스가 그 문제를 처리해주고 있으니 말일세. 덕분에 시간을 넉넉히 벌어 이 역병에 감춰진 비밀을 밝혀내고 내가 할 수 있는 일이 무엇인지 찾아볼 수 있었지.', `MaleText_loc4`='这简直是里程碑式的胜利！皇家炼金师协会花费了数年时间来破解巫妖王诅咒的秘密，现在总算取得了突破！$B$B虽然实验的成功堪称历史的转折点，但是还有很多东西有待研究。我要做更多的实验……挑选更多的样本……$B$B至少我不用担心浮空城。联盟会解决那个玩意儿的。这样我就有足够的时间来研究，揭示其中的奥妙。', `MaleText_loc5`='真是驚人的發現!皇家藥劑師學會花了好幾年破解巫妖王瘟疫的秘密，我終於完成他了!$B$B除了這是歷史上的轉折點以外，還有更多的東西等著我們發現。我還有更多實驗可以做...達成實驗目標...$b$b至少我不用擔心天譴軍的亡域。聯盟在處理那個問題了。這讓我有許多時間探索瘟疫的秘密，揭開這個秘密。', `MaleText_loc7`='¡Vaya descubrimiento histórico! La Sociedad Real de Boticarios ha dedicado años a aprender los secretos de la plaga del Rey Exánime, ¡y al fin lo ha logrado!$B$BA pesar de este giro en la historia, aún queda mucho por descubrir. Tengo que realizar más experimentos, conseguir más sujetos para usarlos en pruebas...$B$BAl menos no tengo que preocuparme por la necrópolis de la Plaga. La Alianza se ocupa de ese problema. Esto me deja tiempo suficiente para profundizar en los secretos de la plaga y descubrir lo que pueda.' WHERE `ID`=30934;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='퓨트리스 대연금술사님 곁에서 일할 수 있는 것은 커다란 영예일세. 대연금술사님의 연구 덕분에 이 세상을 리치 왕의 역병에서 구해내고 우리는 새로운 희망을 품을 수 있었으니 말이야.', `MaleText_loc4`='能成为大药剂师普特雷斯的助手是我的荣幸。他的研究工作让整个世界摆脱了巫妖王的阴影，令我们的事业有了新的希望。', `MaleText_loc5`='在大藥劑師普崔司身旁工作是我的榮幸。他的工作從巫妖王的瘟疫中拯救了這個世界，給了我們新的希望。', `MaleText_loc7`='Es un gran honor trabajar junto al Gran Boticario Putress. Su trabajo ha salvado al mundo de la plaga del Rey Exánime y le ha dado a la gente fe en nuestra causa.', `FemaleText_loc1`='퓨트리스 대연금술사님 곁에서 일할 수 있는 것은 커다란 영예이지. 대연금술사님의 연구 덕분에 이 세상을 리치 왕의 역병에서 구해내고 우리는 새로운 희망을 품을 수 있었다네.', `FemaleText_loc4`='能成为大药剂师普特雷斯的助手是我的荣幸。他的研究工作让整个世界摆脱了巫妖王瘟疫的阴影，令我们的事业有了新的希望。', `FemaleText_loc5`='在大藥劑師普崔司身旁工作是我的榮幸。他的工作從巫妖王的瘟疫中拯救了這個世界，給了我們新的希望。', `FemaleText_loc7`='Es un honor trabajar junto al gran boticario Putress. Su trabajo ha estado al servicio del mundo tras la peste del Rey Exánime y ha ofrecido esperanzas renovadas a nuestra causa.' WHERE `ID`=30935;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서릿결 부족이 있는 곳에, 독수리들이 있소. 독수리들은 내가 이 땅을 누비던 것보다 훨씬 더 오래 우리의 동지였소이다. 그리고 친구, 난 이제 엄밀히 말해 더는 젊지가 않다오.', `MaleText_loc4`='有霜脉矮人的地方就有雄鹰。在我降生之前，它们就是氏族的盟友了……如今我已不再年轻了。', `MaleText_loc5`='哪有霜誕矮人，哪裡就有老鷹。他們從我在地上行走之前就是我們的盟友了...而且我也不年輕了，$G小子:小妞;。', `MaleText_loc7`='Allá donde están los Natoescarcha hay águilas. Han sido nuestras aliadas durante más tiempo del que llevo caminando por la tierra... y ya no soy lo que se dice joven, $Gzagal:zagala;.' WHERE `ID`=30936;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰하트 왕께서 서릿결 부족원이 하는 시험을 거치라고 이리로 보내셨습니다. 피욜린, 시험에 임할 준비가 되었습니다.', `MaleText_loc4`='雷心国王派我来接受霜脉矮人的试炼。我准备好了，弗亚林。', `MaleText_loc5`='風暴之心國王派我來接受霜誕矮人應有的考驗。我已經準備好接受試煉了，弗尤林。', `MaleText_loc7`='El rey Cuoretormenta me ha mandado para que se me ponga a prueba como si fuera un Natoescarcha. Fjorlin, estoy listo para mi prueba.', `FemaleText_loc1`='스톰하트 왕께서 서릿결 부족원이 하는 시험을 거치라고 이리로 보내셨어요. 피욜린, 시험에 임할 준비가 되었어요.', `FemaleText_loc4`='雷心国王派我来接受霜脉矮人的试炼。我准备好了，弗亚林。', `FemaleText_loc5`='風暴之心國王派我來接受霜誕矮人應有的考驗。我已經準備好接受試煉了，弗尤林。', `FemaleText_loc7`='El rey Cuoretormenta me ha mandado para que se me ponga a prueba como si fuera un Natoescarcha. Fjorlin, estoy lista para mi prueba.' WHERE `ID`=30937;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스가 가라앉은 경기장 공성 작업장을 장악했습니다!', `MaleText_loc4`='联盟占领了沉降之环攻城车间！', `MaleText_loc5`='沉沒之環的攻城工坊被聯盟拿下了!', `MaleText_loc7`='¡El Taller de Asedio del Anillo Sumergido ha sido tomado por la Alianza!' WHERE `ID`=30938;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스가 파괴된 신전 공성 작업장을 장악했습니다!', `MaleText_loc4`='联盟占领了破碎神殿攻城车间！', `MaleText_loc5`='破碎神殿的攻城工坊被聯盟拿下了!', `MaleText_loc7`='¡El Taller de Asedio del Templo Quebrado ha sido tomado por la Alianza!' WHERE `ID`=30939;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드가 가라앉은 경기장 공성 작업장을 장악했습니다!', `MaleText_loc4`='部落占领了沉降之环攻城车间！', `MaleText_loc5`='沉沒之環的攻城工坊被部落拿下了!', `MaleText_loc7`='¡El Taller de Asedio del Anillo Sumergido ha sido tomado por la Horda!' WHERE `ID`=30940;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드가 파괴된 신전 공성 작업장을 장악했습니다!', `MaleText_loc4`='部落占领了破碎神殿攻城车间！', `MaleText_loc5`='破碎神殿的攻城工坊被部落拿下了!', `MaleText_loc7`='¡El Taller de Asedio del Templo Quebrado ha sido tomado por la Horda!' WHERE `ID`=30941;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰하트 왕께서 당신을 시험에 임하게 하셨다고요? 그분께서 무엇보다도 먼저 당신의 가능성을 보고 싶으신 게 분명하군요. 아니라면 이런 신성한 의식을 치르게 하지 않으셨을 겁니다.', `MaleText_loc4`='国王派你来接受试炼？他一定在你身上发现了某种潜质，不然也不会让你参加如此神圣的仪式。', `MaleText_loc5`='風暴之心國王讓你來接受測試，嗯?他一定在你身上看出某種特質，不然我懷疑他怎麼會讓你接受如此神聖的儀式。', `MaleText_loc7`='El rey Cuoretormenta te está poniendo a prueba, ¿no? Debe haber visto algo en ti o no te haría pasar un ritual tan sagrado.' WHERE `ID`=30942;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 관습이 익숙지 않을 테지요. 그러니 의식을 치르는 장소로 이동하는 동안 몇 가지 알려 드리겠습니다.', `MaleText_loc4`='我知道你对霜脉矮人还缺乏了解，因此我会在路上为你做一些简单的介绍。', `MaleText_loc5`='我知道你是新來的，所以我會在路上讓你了解些事情。', `MaleText_loc7`='Sé que acabas de llegar a nuestra raza, así que te pondré un poco al día mientras viajamos.' WHERE `ID`=30943;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='몇 년 전, 제 아버님과 여러 서릿결 부족원들은 용의 안식처를 통과하여 길고 힘든 여행에서 돌아오셨었지요. 엄청난 눈보라가 닥쳤습니다... 전에 겪었던 것보다 훨씬 대단했지요.', `MaleText_loc4`='很多年前，我的父亲和一些霜脉矮人行走在穿越龙骨荒野的艰难归程中。他们遇到了暴风雪……比我们见过的任何一场暴风雪都厉害。', `MaleText_loc5`='許多年前，我父親與其他一些霜誕矮人從龍骨荒野長途跋涉而來。當時有著嚴重的暴風雪肆虐...比我們現在能看到的還糟多了。', `MaleText_loc7`='Hace años, mi padre y otros Natoescarcha volvían de un paseo por el Cementerio de Dragones. Había una fuerte ventisca... mucho peor de las que hemos tenido desde entonces.' WHERE `ID`=30944;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들은 피로 얼룩진 눈밭을 헤치며, 그들이 이해할 수 없는 방언으로 얘기하며 방랑하는 한 드워프를 찾고자 흔적을 따라갔습니다. 그 드워프는 당신네 종족을 싫어하는 우리 같은 드워프가 아닌, 우리 동족이 전에는 보지 못한 산악 드워프였지요.', `MaleText_loc4`='沿着雪地上的血迹，他们遇见了一位流浪的矮人。他操着一口难以理解的方言……嗯，因为他不是一般的矮人啊。这个神秘的流浪者自称是高山矮人——我们从未听说过这个氏族。', `MaleText_loc5`='他們跟著一條被血浸濕的雪路，發現一個矮人遊蕩著，說著他們聽不懂的方言...不是我們這一族的，但是是隻山脈矮人 - 一種我們從沒看過的族類。', `MaleText_loc7`='Se encontraron con un rastro de nieve ensangrentada y lo siguieron hasta dar con un enano errante que hablaba un dialecto que no conocían... y no un enano de nuestra raza, un enano de montaña, algo que jamás habíamos visto antes.' WHERE `ID`=30945;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 드워프는 자기가 어디서 왔는지 이름이 뭔지조차 기억하지 못하는 듯 정신이 나간 것 같았습니다. 눈밭에서 같은 드워프가 죽도록 내버려둘 수 없었던 우리 아버님의 부대는 그 드워프를 데려와 서리요새로 발길을 돌렸습니다.', `MaleText_loc4`='高山矮人似乎迷了路，不记得自己是从哪儿来的，甚至不记得自己的名字。他们不忍心将这位表亲丢在冰天雪地里，于是收留了他，然后踏上了返回冰霜堡的旅途。', `MaleText_loc5`='矮人看起來迷失了，他沒有記憶是從哪裡來的，甚至忘了他的名字。為了不讓他的矮人表親死在雪地哩，他們讓他加入我父親的隊伍，繼續啟程回到霜堡。', `MaleText_loc7`='El enano parecía perdido, no recordaba de dónde había venido, ni siquiera recordaba su propio nombre. Mi padre y su grupo no son de los que dejan morir a un pariente enano en la nieve, así que lo cogieron y continuaron hacia Fuerte Escarcha.' WHERE `ID`=30946;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼마 지나지 않아, 갑자기 그들 앞에 눈이 쏟아지더니 요르문가르 크기만한 베라누스가 그들 앞에 나타났습니다... 그들이 반항하기도 전에 그들 중 한 명을 꿀꺽 삼켜 버렸습니다.', `MaleText_loc4`='走着走着，他们面前的雪地突然裂开了，一只像维拉努斯那么大的冰虫袭击了他们……其中一位伙伴还来不及反应，就被整个吞了下去。', `MaleText_loc5`='不久過後，不知道從哪來的，大雪從他們前方崩落。一隻像是維拉努斯那麼大的蟄猛巨蟲突然出現在隊伍中...他們其中一人在反應過來之前就被吞了下去。', `MaleText_loc7`='Poco después, salido de la nada, la nieve estalló ante ellos y un jormungar del tamaño de Veranus cayó sobre su grupo... Se tragó entero a uno de ellos antes de que tuvieran tiempo de reaccionar.' WHERE `ID`=30947;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 아버님께서는 부대 모두 운이 다했다고 생각하셨지요... 그런데 제 아버님 뒤에서 격렬한 고함이 눈밭 전체에 걸쳐 들리더니 돌과 같은 조직으로 자신의 피부를 바꾸고는 손에 일어난 번개가 뜨겁게 타오르며 몸 크기가 커진 산악 드워프의 모습을 보게 되셨답니다.', `MaleText_loc4`='我的父亲以为大家都难逃此劫……但听背后的雪地里传来一声怒吼，他扭头看见高山矮人的体型正在增大，他的皮肤上浮现出岩石般的纹理，他的手上冒出嘶嘶作响的闪电。', `MaleText_loc5`='我的父親當時覺得他們死定了...但是在他身後，突然傳來一聲怒吼響徹雪地，他轉過頭來看到山脈矮人的體型正在變大，皮膚變成石頭似地紋路，手上發出閃電的啪激聲。', `MaleText_loc7`='Mi padre pensaba que estaban todos perdidos... pero, detrás de él, un furioso gruñido retumbó en la nieve y al volverse vio al enano de montaña aumentar de tamaño, mientras su piel adquiria una textura pétrea y unos rayos crepitaban en sus manos.' WHERE `ID`=30948;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 드워프는 콰르릉거리는 굉음을 내며 앞으로 나갔고, 번쩍이는 금속 망치를 휘두르며 그 빛으로 길을 밝혔습니다. 그러면서 요르문가르의 창자 속으로 들어갔지요.', `MaleText_loc4`='高山矮人带着闷雷般的吼声向前冲去，将一把闪亮的金属锤直接掷进了冰虫的喉咙，我的父亲还看见金属锤的表面环绕着闪电。', `MaleText_loc5`='矮人帶著雷霆般的巨響向前衝鋒，旋轉著一把閃耀的金屬戰錘，閃電穿梭在戰錘的表面，直接往蟄猛巨蟲的喉嚨丟去。', `MaleText_loc7`='El enano se lanzó hacia adelante con un sonido atronador y arrojó directamente a la garganta del jormungar un martillo de metal brillante, con relámpagos en toda su superficie.' WHERE `ID`=30949;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요르문가르는 즉시 무너졌고, 녀석의 머리는 경련을 일으키는 몸뚱어리에 간신히 붙어 있었습니다. 제 아버님께서는 경외에 차 그 드워프에게 돌아서시고는 찬사를 보내면서 주먹을 치켜 드셨습니다...', `MaleText_loc4`='那只冰虫立即倒下了，它的脑袋勉强挂在不断抽搐的躯体上。我的父亲敬畏地注视着高山矮人，举起拳头表示赞美……', `MaleText_loc5`='蟄猛巨蟲立刻就倒下了，它的頭與身體幾乎分開。我父親敬畏地轉向那位矮人，舉起拳頭喝采...', `MaleText_loc7`='El jormungar se derrumbó de inmediato, con la cabeza apenas unida al cuerpo que se convulsionaba. Mi padre miró asombrado al enano y levantó su puño en muestra de alabanza...' WHERE `ID`=30950;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 도와드릴까요?', `MaleText_loc4`='我能帮你做什么吗？', `MaleText_loc5`='我能幫你做什麼?', `MaleText_loc7`='¿Qué puedo hacer por ti?' WHERE `ID`=30951;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 이방인은 이름이 없어, 제 아버님께서 전설의 영웅에게 줄 이름으로 남겨둔 "요르그"라고 정하셨습니다. 몇 년이 지난 지금 그분은 서릿결 부족의 왕이신 요르그 스톰하트로서 우리를 이끌고 계십니다.', `MaleText_loc4`='这位神秘的高山矮人没有名字，于是我的父亲尊称他为“约尔格”，这是传说中的勇士才能享受的称呼。很多年以后，他成为了霜脉矮人熟知的国王——约尔格·雷心。', `MaleText_loc5`='這個異鄉人沒有自己的名字，我父親尊稱他為「約格」，一個傳說勇士該有的名字。幾十年後，他以約格·風暴之心，霜誕之王的身分站在我們面前。', `MaleText_loc7`='Mi padre llamó al extranjero que no tenía nombre "Yorg", un nombre reservado a los campeones legendarios. Años después, él se alza ante nosotros como Yorg Cuoretormenta, Rey de los Natoescarcha.' WHERE `ID`=30952;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰하트 왕께서는 우리를 잘 지도해 주셨습니다... 서리 거인들과 싸우며 용맹을 떨치던 과거의 우리보다 더 대단한 전사로 우릴 탈바꿈시켜 주셨습니다.', `MaleText_loc4`='国王对我们进行了严格的训练……让我们成长为可怕的战士。如今的我们，远比当年与冰霜巨人交战时吹嘘的还要厉害。', `MaleText_loc5`='風暴之心國王把我們訓練的很好...把我們變成更兇猛的戰士，甚至超越我們與霜巨人之戰的時候。', `MaleText_loc7`='El rey Cuoretormenta nos ha entrenado bien... nos convirtió en guerreros aún más temibles de lo que habíamos sido durante la época de nuestra guerra con los gigantes de escarcha.' WHERE `ID`=30953;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑습니다. 잘 지내고 계십니까?', `MaleText_loc4`='朋友，你最近还好吗？', `MaleText_loc5`='你最近過的好嗎，老兄?', `MaleText_loc7`='¿Cómo lo llevas, tron?' WHERE `ID`=30954;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서릿결 부족의 전사를 임명하는 가장 치열한 시험의 하나처럼, 우리는 우리 자신보다도 더 거대한 생명체와 맞서도록 만들어졌습니다. 바로 거인, 용, 요르문가르와 같은 생명체지요. 크기 따위는 절대 우리의 약점이 되지 않을 거란 사실을 입증하는 거랍니다.', `MaleText_loc4`='作为霜脉战士最严厉的试炼之一，就是战胜比自己高大许多的敌人，比如巨人、龙或是冰虫——由此证明体型并不是我们的弱点。', `MaleText_loc5`='身為霜誕戰士所受到最兇猛的試煉之一，我們被迫面對體型比我們更大的生物--巨人、龍、蟄猛巨蟲--證明體型永遠都不是我們的弱點。', `MaleText_loc7`='Y una de las pruebas más intensas que tenemos que pasar los guerreros Natoescarcha es que tenemos que enfrentarnos a una criatura mucho mayor que nosotros... gigantes, dragones, jormungar... como prueba de que el tamaño nunca será nuestro punto débil.' WHERE `ID`=30955;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 이 일은 당신 앞에 놓인 시험입니다. 무쇠 감시자가 죽었을 때에만 우리에게 돌아올 수 있습니다. 그러면 서릿결 부족의 전사로서 숭배받을 것입니다.', `MaleText_loc4`='接受今天的试炼吧。杀死钢铁观察者，再回来见我们，然后你就能成为倍受尊敬的霜脉战士了。', `MaleText_loc5`='這就是今日你將受到的試煉。只有當鐵之看守者死去之時，你才能回到我們身旁，被我們尊為一位霜誕的戰士。', `MaleText_loc7`='Esta es la prueba que se te encomienda hoy. Vuelve junto a nosotros únicamente cuando el Vigía de Hierro esté muerto y entonces se te reverenciará como combatiente de los Natoescarcha.' WHERE `ID`=30956;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보석의 완벽함을 다시 가르쳐 주십시오.', `MaleText_loc4`='重新教我切割完美宝石', `MaleText_loc5`='重新教我寶石完美工法', `MaleText_loc7`='Vuelve a entrenarme en Perfección de gemas', `FemaleText_loc1`='보석의 완벽함을 다시 가르쳐 주십시오.', `FemaleText_loc4`='重新教我切割完美宝石', `FemaleText_loc5`='重新教我寶石完美工法', `FemaleText_loc7`='Vuelve a entrenarme en Perfección de gemas' WHERE `ID`=30957;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무엇을 도와주면 되겠나?', `MaleText_loc4`='我能帮你什么忙吗？', `MaleText_loc5`='我能怎麼服務你?', `MaleText_loc7`='¿En qué puedo servirte?' WHERE `ID`=30958;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 원하나?', `MaleText_loc4`='你想要什么？', `MaleText_loc5`='你要什麼?', `MaleText_loc7`='¿Qué quieres?' WHERE `ID`=30959;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겨울손아귀 호수 전투가 곧 시작됩니다!', `MaleText_loc4`='冬拥湖之战即将开始！', `MaleText_loc5`='冬握湖之戰即將展開!', `MaleText_loc7`='¡La batalla por el lago Conquista del Invierno va a comenzar!' WHERE `ID`=30960;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투를 시작합니다!', `MaleText_loc4`='战斗开始！', `MaleText_loc5`='開戰吧!', `MaleText_loc7`='¡Que comience la batalla!' WHERE `ID`=30961;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드 항구 선장', `MaleText_loc4`='WotLK - Stormwind Harbor Captain', `MaleText_loc5`='WotLK - Stormwind Harbor Captain', `MaleText_loc7`='WotLK - Stormwind Harbor Captain', `FemaleText_loc1`='스톰윈드 항구 선장', `FemaleText_loc4`='WotLK - Stormwind Harbor Captain', `FemaleText_loc5`='WotLK - Stormwind Harbor Captain', `FemaleText_loc7`='WotLK - Stormwind Harbor Captain' WHERE `ID`=30962;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수호자 요청', `MaleText_loc4`='WotLK - Request Defender', `MaleText_loc5`='WotLK - Request Defender', `MaleText_loc7`='WotLK - Request Defender', `FemaleText_loc1`='수호자 요청', `FemaleText_loc4`='WotLK - Request Defender', `FemaleText_loc5`='WotLK - Request Defender', `FemaleText_loc7`='WotLK - Request Defender' WHERE `ID`=30963;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무쇠 감시자가 소생하자 삐걱거리는 소리가 주위 건물에 메아리칩니다.', `MaleText_loc4`='钢铁观察者苏醒时，附近的建筑物嘎吱作响。', `MaleText_loc5`='當鐵之看守者復生時，周圍的生物發出咯吱咯吱的回聲。', `MaleText_loc7`='Resuenan crujidos en las estructuras cercanas cuando el Vigía de Hierro vuelve a la vida.' WHERE `ID`=30964;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='망치로 치자, 무쇠 감시자를 둘러싼 틀에서 녹이 더 많이 떨어지면서 진행 속도가 빨라집니다.', `MaleText_loc4`='钢铁观察者一锤砸下，身上的铁锈纷纷散落，它的步伐也越来越快了。', `MaleText_loc5`='當鐵錘落地時，更多的鐵鏽從鐵之看守者的身軀上掉下，他的速度也更加快速。', `MaleText_loc7`='Cuando el martillo golpea, más óxido cae de la armadura del Vigía de Hierro y su ritmo crece.' WHERE `ID`=30965;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무쇠 거인이 살짝 몸서리를 칩니다.', `MaleText_loc4`='铁巨人略微有些颤抖。', `MaleText_loc5`='鐵巨人微微地發抖。', `MaleText_loc7`='El Gigante de Hierro tiembla levemente.' WHERE `ID`=30966;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무쇠 감시자가 사납게 울부짖으며, 오래된 몸에서 녹을 떨어냅니다.', `MaleText_loc4`='钢铁观察者咆哮起来，更多的铁锈从古老的躯干上滑落下来。', `MaleText_loc5`='鐵之看守者憤怒地咆哮，從他古老的身軀上抖下了更多鐵鏽。', `MaleText_loc7`='El Vigía de Hierro ruge con furia, y cae más óxido de su antiguo cuerpo.' WHERE `ID`=30967;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무쇠 거인이 살짝 몸서리를 칩니다.', `MaleText_loc4`='铁巨人略微有些颤抖。', `MaleText_loc5`='鐵巨人微微地發抖。', `MaleText_loc7`='El Gigante de Hierro tiembla levemente.' WHERE `ID`=30968;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무쇠 감시자가 이제는 볼 수 없게 된 눈을 부여잡으며 비틀거리더니, 무작정 돌진합니다.', `MaleText_loc4`='钢铁观察者捂着受伤的双眼，盲目地横冲直撞。', `MaleText_loc5`='鐵之看守者轉動著他如今已失去作用的雙眼，盲目地衝鋒。', `MaleText_loc7`='El Vigía de Hierro se tambalea, se toca sus ahora inservibles ojos y carga a ciegas.' WHERE `ID`=30969;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분노의 일격에 무쇠 감시자가 휘청거립니다.', `MaleText_loc4`='钢铁观察者发出一声怒吼，摔倒在地。', `MaleText_loc5`='在憤怒的一擊下，鐵之看守者失去了他的立足點。', `MaleText_loc7`='El Vigía de Hierro cae tras el furioso golpe.' WHERE `ID`=30970;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 네 놈에게 아무런 제재도 하지 않고 터벅터벅 걸어와서 폭풍의 심장을 넙죽 내 줄 거라 생각하진 않겠지?', `MaleText_loc4`='你以为我会放你进来，让你拿走风暴之心吗？', `MaleText_loc5`='你不會覺得我會讓你走進去，拿走風暴之芯吧?', `MaleText_loc7`='No pensarías que iba a dejar que entrases aquí y te llevases el Corazón de la Tormenta, ¿verdad?' WHERE `ID`=30972;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈이 발두란을 쓰러뜨렸다고 해서 내가 거대괴수를 완성하지 못할 거란 생각은 마라.', `MaleText_loc4`='哪怕你杀死了瓦杜兰，也无法阻止我铸造巨人。', `MaleText_loc5`='你也許殺了瓦杜然，但是那不能阻止我完成巨像。', `MaleText_loc7`='Puede que hayas matado a Valduran, pero eso no impedirá que complete el coloso.' WHERE `ID`=30973;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='토석인의 친구이자 동맹인 당신을 환영합니다.', `MaleText_loc4`='欢迎你，土灵的朋友和盟友。', `MaleText_loc5`='身為土靈的朋友跟盟友，這裡任何時候都歡迎你。', `MaleText_loc7`='Sé $gbienvenido:bienvenida; aquí, como $gamigo:amiga; y $galiado:aliada; de los terráneos.' WHERE `ID`=30974;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이리로 오시오. 손을 빌렸으면 하는 일이 좀 있소.', `MaleText_loc4`='瞧，这里有一些我能用得着的东西。', `MaleText_loc5`='在這，$G小夥子:小妞;，我需要點幫忙。', `MaleText_loc7`='Por aquí, $gmuchacho:muchacha;, necesito que me eches una mano.' WHERE `ID`=30975;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c님께 신의 은총이 있기를. 스러져간 영혼 수백만의 분노를 스컬지가 느끼도록 해 줍시다!', `MaleText_loc4`='愿力量与你同在，$c。让天灾军团感受到百万灵魂的愤怒吧！', `MaleText_loc5`='力量眷顧你，$c。讓天譴軍看看萬千逝者的憤怒!', `MaleText_loc7`='Que tu brazo sea fuerte, $c. ¡Que la Plaga sienta la furia de un millón de almas perdidas!', `FemaleText_loc1`='$c님께 신의 은총이 있기를. 스러져간 영혼 수백만의 분노를 스컬지가 느끼도록 해 주자고요!', `FemaleText_loc4`='愿力量与你同在，$c。让天灾军团感受到百万灵魂的愤怒吧！', `FemaleText_loc5`='力量眷顧你，$c。讓天譴軍看看萬千逝者的憤怒!', `FemaleText_loc7`='Que tu brazo sea fuerte, $c. ¡Que la Plaga sienta la furia de un millón de almas perdidas!' WHERE `ID`=30976;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c님께 힘과 명예가 함께하기를. 제가 남은 모든 힘을 다해 축복을 드립니다. 이 악몽이 빨리 끝나기만을 기원합니다!', `MaleText_loc4`='愿荣耀与力量与你同在，$c。我以仅存的力量祝福你，愿这场噩梦早日结束！', `MaleText_loc5`='力量與榮耀將歸與你，$c。我以我僅存的力量祝福你。希望這場夢魘趕快結束!', `MaleText_loc7`='Que tengas gloria y fuerza, $c. Te bendigo con toda la fuerza que me queda. ¡Que esta pesadilla termine pronto!', `FemaleText_loc1`='$c님께 힘과 명예가 함께하기를. 제가 남은 모든 힘을 다해 축복을 드려요. 이 악몽이 빨리 끝나기만을 기원해요!', `FemaleText_loc4`='愿荣耀与力量与你同在，$c。我以仅存的力量祝福你，愿这场噩梦早日结束！', `FemaleText_loc5`='力量與榮耀將歸與你，$c。我以我僅存的力量祝福你。希望這場夢魘趕快結束!', `FemaleText_loc7`='Que tengas gloria y fuerza, $c. Te bendigo con toda la fuerza que me queda. ¡Que esta pesadilla termine pronto!' WHERE `ID`=30977;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고귀한 $c님께 무한한 지혜가 있기를.', `MaleText_loc4`='愿古老的智慧与你同在，高贵的$c。', `MaleText_loc5`='願千百年的智慧照耀著你，高貴的$c。', `MaleText_loc7`='Que sobre ti caiga la sabiduría de las eras, noble $c.', `FemaleText_loc1`='고귀한 $c님께 무한한 지혜가 있기를.', `FemaleText_loc4`='愿古老的智慧与你同在，高贵的$c。', `FemaleText_loc5`='願千百年的智慧照耀著你，高貴的$c。', `FemaleText_loc7`='Que sobre ti caiga la sabiduría de las eras, noble $c.' WHERE `ID`=30978;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다. 안녕히 가십시오, $c님. 저는 은빛십자군 선봉기지로 돌아가야 합니다.', `MaleText_loc4`='朋友，谢谢你。再见，我必须回到银色前线基地。', `MaleText_loc5`='謝謝你，再會了，朋友。我得回到銀白先鋒駐地了。', `MaleText_loc7`='Gracias y adiós, $gamigo:amiga;. He de volver a La Vanguardia Argenta.', `FemaleText_loc1`='고마워요. 안녕히 가세요, $c님. 저는 은빛십자군 선봉기지로 돌아가야 해요.', `FemaleText_loc4`='朋友，谢谢你。再见，我必须回到银色前线基地。', `FemaleText_loc5`='謝謝你，再會了，朋友。我得回到銀白先鋒駐地了。', `FemaleText_loc7`='Gracias y adiós, $gamigo:amiga;. He de volver a La Vanguardia Argenta.' WHERE `ID`=30980;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 요새를 찾아올 수 있도록 허가받았다, 작은 $r|1이여;여;.$b$b우릴 불명예스럽게 하지 마라!', `MaleText_loc4`='$r，我允许你进入我们的城堡。$b$b但是，别让我们蒙羞！', `MaleText_loc5`='你可以參觀我們的堡壘了，小$r。$b$b別讓我們丟臉了!', `MaleText_loc7`='Se te permite visitar nuestra fortaleza, $gpequeño:pequeña; $r.$B$B¡No nos deshonres!' WHERE `ID`=30981;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제왕 요쿰 님, 부탁합니다만 크롤미르가 어떻게 되었는지 알 수 있을까요?', `MaleText_loc4`='约库姆国王，如果您不介意的话，能不能告诉我科洛米尔的消息？', `MaleText_loc5`='如果您願意的話，裘庫姆王，可以讓我知道克洛米爾的狀況嗎?', `MaleText_loc7`='Rey Jokkum, si es de tu agrado, ¿podría saber que ha sido de Krolmir?', `FemaleText_loc1`='제왕 요쿰 님, 부탁합니다만 크롤미르가 어떻게 되었는지 알 수 있을까요?', `FemaleText_loc4`='约库姆国王，如果您不介意的话，能不能告诉我科洛米尔的消息？', `FemaleText_loc5`='如果您願意的話，裘庫姆王，可以讓我知道克洛米爾的狀況嗎?', `FemaleText_loc7`='Rey Jokkum, si es de tu agrado, ¿podría saber que ha sido de Krolmir?' WHERE `ID`=30982;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 그런 내용을 말해줄 만큼 널 믿지 않는다.$b$b넌 우리 백성이 겪었던 시련과 우리가 지녀온 괴로움을 존중해야만 한다.$b$b네가 던 니펠렘에 거대한 영광을 가져온다면, 우리 백성의 지식을 네게 공유해 주도록 고려해 줄 수 있을 거다.', `MaleText_loc4`='我对你的信任还不够，抱歉不能将如此重要的信息透露给你。$b$b你必须尊重我们接受的考验以及我们背负的重担……$b$b如果你能为丹尼芬雷带来荣耀的话，我或许会考虑与你分享我们的知识。', `MaleText_loc5`='我還沒有信任你到可以跟你講這種事。$b$b你必須尊重我們人民所受過的試煉，我們所背負的重擔...$b$b或許，若你是來給丹尼弗蘭帶來榮耀的話，我願意跟你分享一些我們的知識。', `MaleText_loc7`='No confío en ti lo suficiente como para hablar de tales cosas.$B$BDeberás respetar las pruebas que ha soportado nuestro pueblo, las cargas que hemos aguantado...$B$BQuizá si acabas siendo un gran honor para Dun Niffelem estaría dispuesto a compartir contigo el saber de nuestro pueblo.' WHERE `ID`=30983;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋다, 작은 $c|1이여;여;.$b$b토림과 우리의 관계를 개선하도록 네가 할 수 있는 일이 많이 남아 있긴 하지만, 이 비밀을 너와 공유해 줄 수 밖에 없겠구나.$b$b네가 찾아내고자 하는 걸 알 준비가 되면 내게 다시 얘기하거라.', `MaleText_loc4`='很好，$c。$b$b虽然你还需要付出更多努力，才能缓解我们与托里姆的关系，但是我决定将这个秘密告诉你。$b$b等你做好了解真相的准备后，再来与我谈话吧。', `MaleText_loc5`='非常好，小$c。$b$b雖然你在我們跟索林姆的關係上還有很多得做，不過我被迫要跟你分享這個小秘密。$b$b當你準備好要看時，再來找我。', `MaleText_loc7`='Muy bien, $gpequeño:pequeña; $c.$B$BAunque aún te queda mucho por pulir en nuestra relación con Thorim, me veo obligado a compartir contigo este secreto.$B$BVuelve a hablar conmigo cuando estés $glisto:lista; para conocer lo que buscas.' WHERE `ID`=30984;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크롤미르의 행방을 알 준비가 되었습니다.', `MaleText_loc4`='我想知道科洛米尔的命运。', `MaleText_loc5`='我準備好知曉克洛米爾的命運了。', `MaleText_loc7`='Estoy listo para conocer el destino de Krolmir,', `FemaleText_loc1`='크롤미르의 행방을 알 준비가 되었습니다.', `FemaleText_loc4`='我想知道科洛米尔的命运。', `FemaleText_loc5`='我準備好知曉克洛米爾的命運了。', `FemaleText_loc7`='Estoy lista para conocer el destino de Krolmir,' WHERE `ID`=30985;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 곰은 옆구리가 딱딱하게 얼었습니다... 다시 시도해 보십시오.', `MaleText_loc4`='这块熊腰肉都冻得发硬了……再试试吧。', `MaleText_loc5`='這熊肉凍得跟冰塊一樣...再試試看。', `MaleText_loc7`='El costillar de oso está completamente congelado... vuelve a intentarlo.', `FemaleText_loc1`='이 곰은 옆구리가 딱딱하게 얼었습니다... 다시 시도해 보십시오.', `FemaleText_loc4`='这块熊腰肉都冻得发硬了……再试试吧。', `FemaleText_loc5`='這熊肉凍得跟冰塊一樣...再試試看。', `FemaleText_loc7`='El costillar de oso está completamente congelado... vuelve a intentarlo.' WHERE `ID`=30986;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요! 저도 서두르는 건 질색이지만, 여기 지금 무쇠 드워프 부대가 쫙 깔렸어요. 크레테우스랑 당신을 잡으려고 안달이라고요... 여길 빠져나가야 해요.', `MaleText_loc4`='嗨！我不想催你的，但是铁矮人已经察觉了你和克莱特乌斯的行动……我们赶紧离开这儿吧。', `MaleText_loc5`='向您致敬!我不喜歡匆匆忙忙地來找你，但是有一隻鐵矮人軍隊來阻止你跟克里圖思想要做的事情了...我們得離開這裡。', `MaleText_loc7`='¡Saludos! No me gusta meterte prisa, pero ha llegado un ejército de enanos férreos para detener lo que sea que tú y Creteus estáis intentando hacer... Tenemos que salir de aquí.' WHERE `ID`=30987;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰하트 왕께서 무쇠 드워프들이 이쪽으로 진군한다는 소문을 들으시고, 그 짧은 시간에 최정예 전사들을 최대한 모으셨어요.', `MaleText_loc4`='雷心国王听说铁矮人正朝这里挺进，于是他将眼下能召集到的最好的战士都带来了。', `MaleText_loc5`='風暴之心國王聽到鐵矮人朝這個方向進攻的風聲，已經帶著在短時間能找到的最好士兵前去迎擊了。', `MaleText_loc7`='El rey Cuoretormenta se enteró de que los enanos férreos se dirigían hacia aquí y llevó a los mejores guerreros que pudo reunir en tan poco tiempo.' WHERE `ID`=30988;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서두르세요. 크레테우스는 서쪽에 있어요. 스톰하트 왕께서 지금 놈들을 상대하고 계시긴 한데, 녀석들 수가 너무 많아요.', `MaleText_loc4`='快，克莱特乌斯在西边。雷心国王会尽量阻止铁矮人大军，但是他们在数量上占据了绝对优势。', `MaleText_loc5`='快，克里圖思往西方去了，風暴之心國王暫時擋住他們，但是對方有數量優勢。', `MaleText_loc7`='Deprisa, Creteus está al oeste. El rey Cuoretormenta los está reteniendo, pero ellos tienen la ventaja de que son más.' WHERE `ID`=30989;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저분이 싸우시는 걸 보세요. 내 평생 저렇게 끝내주는 전사는 처음이에요... 저분이 우리 왕이라는 게 자랑스럽네요.', `MaleText_loc4`='天啊，看看他战斗时的英姿。我从未见过比他更凶狠的战士……能有这样一位国王真是我的荣幸。', `MaleText_loc5`='你們這些旁觀的人，看看他是怎麼戰鬥的。我從未見過比他更兇狠的戰士...我很高興能叫他國王。', `MaleText_loc7`='¡Por los vigías! ¡Mírale luchar! Jamás he visto un guerrero más despiadado... Me alegra que sea mi rey.' WHERE `ID`=30990;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 녀석들을 최대한 막아 볼게요. 당신도 서둘러서 할 일을 하세요!', `MaleText_loc4`='我们会尽量阻止铁矮人大军。趁现在执行你的使命吧！', `MaleText_loc5`='我們會盡全力拖住他們。不管你們要做什麼，快點就對了!', `MaleText_loc7`='Los retendremos tanto como podamos. ¡Haz lo que tengas que hacer rápido!' WHERE `ID`=30991;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 계신 $C님! 여기 이 사람들이 죽어갑니다! 좀 도와주십시오!', `MaleText_loc4`='嗨！$C！这些人快死啦！我需要你的帮助！', `MaleText_loc5`='在那邊的!$C!這些人要死了!我需要你的幫忙!', `MaleText_loc7`='¡Tú! ¡$C! ¡Estos hombres están muriendo! ¡Necesito tu ayuda!' WHERE `ID`=30992;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇게 멍하니 서 있을 때가 아닙니다! 은빛십자군은 그대의 도움이 필요합니다!', `MaleText_loc4`='别傻站着啊！北伐军需要你的帮助！', `MaleText_loc5`='別站在那邊，$g孩子:女孩;!十字軍需要你們的幫忙!', `MaleText_loc7`='No te quedes mirando, $gchico:chica;. ¡La Cruzada necesita tu ayuda!' WHERE `ID`=30993;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도대체 무얼 하고 있습니까? 사방에 죽어가는 사람들이 가득한데 말입니다!', `MaleText_loc4`='你到底在干什么？没看见你周围的人危在旦夕吗！', `MaleText_loc5`='你到底在搞什麼?這些在你身旁的人都要死了!', `MaleText_loc7`='¿Qué demonios estás haciendo? ¡La gente está muriendo alrededor tuyo!' WHERE `ID`=30994;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 침 좀 닦고 와서 절 좀 도와주십시오!', `MaleText_loc4`='朋友，快把你下巴上的口水擦一擦，来帮我个忙！', `MaleText_loc5`='朋友，把你臉上的口水擦一擦，過來幫我。', `MaleText_loc7`='¡Colega, límpiate la baba de la barbilla y échame una mano!' WHERE `ID`=30995;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛의 축복이 있기를! 모두 죽어간단 말입니다!', `MaleText_loc4`='圣光啊！他们快死了！', `MaleText_loc5`='聖光保佑!他們都要死了!', `MaleText_loc7`='¡Bendita Luz! ¡Están muriendo todos!' WHERE `ID`=30996;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 와서 뭘 파려는지 몰라도 관심 없습니다! 다른데나 가서 알아보십시오!', `MaleText_loc4`='我对你卖的货物完全不感兴趣，朋友！', `MaleText_loc5`='我沒有興趣買任何你想要賣給我的東西，朋友。', `MaleText_loc7`='¡No me interesa nada de lo que hayas venido a venderme, colega!' WHERE `ID`=30997;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 공포와 유혈이 낭자한 참상을 겪지 않고 넘어갈 수 있다고 생각했습니까?', `MaleText_loc4`='你觉得自己能避开血腥与恐怖的场景吗？！', `MaleText_loc5`='你曾經想過你可以脫離浴血與恐懼的生活嗎?', `MaleText_loc7`='¿Creías que te librarías de ver el derrame de sangre y el terror?' WHERE `ID`=30998;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 나사가 빠진 채 멍하니 서 있는 동지여, 이제 움직여야 할 시간입니다! 정신을 좀 추스르고 손 좀 빌려주십시오!', `MaleText_loc4`='别发呆了，拿出行动来！赶紧打起精神，帮我一把啊！', `MaleText_loc5`='我鬆懈的同胞們，行動的時刻到了!振作起來，伸出你的援手!', `MaleText_loc7`='Mi bobo compatriota, ¡este es el momento de actuar! ¡Recomponte y échame una mano!' WHERE `ID`=30999;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐 기다려라, 작은 $r|1이여;여;.', `MaleText_loc4`='等等，$r。', `MaleText_loc5`='等下，小$r。', `MaleText_loc7`='Aguanta, $gpequeño:pequeña; $r.' WHERE `ID`=31000;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제왕 요쿰, 날 소환한 것인가?', `MaleText_loc4`='约库姆国王，是你在召唤我吗？', `MaleText_loc5`='裘庫姆王，您召喚我前來嗎?', `MaleText_loc7`='Rey Jokkum, ¿me has llamado?' WHERE `ID`=31001;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대의 $r $c의 공헌이 그의 수준을 넘어섰다, 폭풍군주여. $g그:그녀;의 공헌은 우리 백성의 마음을 누그러트리는 데 일조했다.', `MaleText_loc4`='风暴之王，这位$r$c做出了超乎寻常的高尚行为。通过努力，$g他:她;已经成功地软化了我的子民的心。', `MaleText_loc5`='風暴之王，您$r$c僕人的高貴義舉遠遠超過了$g他的:她的;身材高度。$g他的:她的;作為成功地軟化我們的心。', `MaleText_loc7`='Los nobles actos de tu sirviente $r $c desafían su tamaño, Señor de la Tormenta. Sus esfuerzos han conseguido ablandar los corazones de mi gente.' WHERE `ID`=31002;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요쿰, 아른그림의 아들이여. 이곳에서 내가 행한 일들에 대해서 항상 후회했었다. 비탄에 잠긴 채 나는 나와 가장 가까운 자들에게 막대한 피해를 불러왔지.', `MaleText_loc4`='约库姆国王，安格里姆之子，我一直对自己的行为感到后悔。我压抑不住内心的伤痛，深深地伤害了身边的亲人。', `MaleText_loc5`='裘庫姆，安格林之子。我對於我在這裡的所作所為感到很抱歉。我很哀慟我竟對我最親近的人們造成最深的傷害。', `MaleText_loc7`='Jokkum, hijo de Arngrim, siempre me he arrepentido de las acciones que realicé aquí. En mi dolor, he hecho daño a aquellos que más cerca están de mí.' WHERE `ID`=31003;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕은 신속하게 그 틈으로 반격해왔네. 예견했던 것보다도 더 빨리 말일세.', `MaleText_loc4`='巫妖王对此次反击迅速做出了反应，竟然比我预想中的还要快。', `MaleText_loc5`='巫妖王對他的漏洞反應的很快。比我預期的還快。', `MaleText_loc7`='El Rey Exánime reaccionó con rapidez ante la brecha. Más deprisa de lo que yo pensaba.' WHERE `ID`=31004;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대영주님께서 상대하시는 자는 가장 교활하고 지능적이며 무자비한 마음을 지닌 존재입니다.', `MaleText_loc4`='你要对付的有史以来最狡猾、最聪明、最凶狠的生物。', `MaleText_loc5`='你所對付的生物有著最奸險、聰明和大膽的心靈，遠超於世界上任何人。', `MaleText_loc7`='Te enfrentas a un ser que se encuentra dentro de la conciencia de los individuos más astutos, inteligentes y despiadados que jamás han existido.' WHERE `ID`=31005;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕은 여태까지 상대하셨던 적과 다릅니다, 대영주님. 비록 희망의 빛 예배당의 신성한 땅에서는 물리치셨지만, 지금은 리치 왕의 영지 안이란 말입니다.', `MaleText_loc4`='巫妖王不同于已往的任何敌人，大领主。虽然你曾在圣光之愿礼拜堂打败过他，但如今，你却身处巫妖王统御下的邪恶王国中。', `MaleText_loc5`='巫妖王不像是你曾經對付過的敵人，大領主。雖然你曾經在聖光之願禮拜堂的聖地上擊敗他，但是你現在進入了他的領域。', `MaleText_loc7`='El Rey Exánime no se parece a nada a lo que te hayas enfrentado antes, Alto Señor. Aunque fuiste superior a él en las sagradas tierras de la Capilla de la Esperanza de la Luz, ahora caminas por sus dominios.' WHERE `ID`=31006;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이기지 못할 겁니다. 이런 식으로는요...', `MaleText_loc4`='你不可能获胜。照目前的情形，是毫无希望的……', `MaleText_loc5`='你贏不了的。這樣無法...', `MaleText_loc7`='No puedes ganar. Así no...' WHERE `ID`=31007;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나더러 뭘 하란 말인가?', `MaleText_loc4`='达里安，你觉得我应该怎么做？', `MaleText_loc5`='你要我做什麼，達瑞安?', `MaleText_loc7`='¿Qué quieres que haga, Darion?' WHERE `ID`=31008;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무것도요. 빛에 구속된 이상 대영주님께서 하실 수 있는 일은 없습니다. 성스러운 빛이 완전히 조종하고 있기 때문에, 그 고결함으로 꼼짝할 수 없으실 겁니다.', `MaleText_loc4`='什么也不能。你的能力受到圣光的局限，在这种情况下你什么都做不了。圣光完全控制了你，将你牢牢地束缚在它所能触及的范围之内。', `MaleText_loc5`='不用。當聖光拘束著你時，你什麼都做不了。聖光完全地控制著你，用著它的美德將你束縛於地面。', `MaleText_loc7`='Nada. No hay nada que puedas hacer mientras estés atado a la Luz. Te controla, encadenándote al suelo con sus virtudes.' WHERE `ID`=31009;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언사를 조심하라, 죽음의 기사여. 지금 헌신한 자들에 둘러싸여 있으니.', `MaleText_loc4`='说话小心点，死亡骑士。你身边的人都是圣光虔诚的信徒。', `MaleText_loc5`='死亡騎士，注意你的言詞。你站在對彼此忠心耿耿的夥伴之中。', `MaleText_loc7`='Elige tus palabras sabiamente, caballero de la Muerte. Te encuentras en compañía de los devotos.' WHERE `ID`=31010;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 고개를 젓습니다.', `MaleText_loc4`='%s摇了摇头。', `MaleText_loc5`='%s搖了搖頭。', `MaleText_loc7`='%s agita la cabeza.' WHERE `ID`=31011;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 들판을 보십시오, 대영주님. 리치 왕은 대영주님께서 전진하지 못하도록 막아선 데다가 우위까지 점하지 않았습니까!', `MaleText_loc4`='大领主，认清眼前的局势吧。巫妖王已经彻底封锁了你的前路，占据了上风。', `MaleText_loc5`='看這塊大地，大領主。巫妖王已經阻止你的進攻，並贏了第一手!', `MaleText_loc7`='Mira hacia el campo, Alto Señor. El Rey Exánime ha detenido tu avance por completo y ahora tiene ventaja.' WHERE `ID`=31012;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대영주님께서 만들어낸 그 틈은 열리자마자 네루비안 거미줄로 막혀버렸고 말입니다.', `MaleText_loc4`='蛛魔的巨网将迅速封印你打开的突破口。', `MaleText_loc5`='你所創造的裂縫被奈幽蟲族封起來的速度就像開啟的速度一樣快。', `MaleText_loc7`='La brecha que creaste fue sellada con telarañas nerubianas en menos tiempo del que tardaste en abrirla.' WHERE `ID`=31013;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대영주님의 병사들을 메아리 골짜기에서 포격을 막아내는 인간 방패로 이용하기에 리치 왕의 군대는 아무런 방해도 받지 않고 기지로 공격해 오는 상황입니다.', `MaleText_loc4`='在回音谷，你的士兵成为了阻挡炮火的肉盾，帮助巫妖王的军队顺利地攻陷了你的营地。', `MaleText_loc5`='你的士兵被用來當作活盾牌來擊退回聲山谷的砲火，讓巫妖王免於任何阻礙便可輕鬆攻擊你的基地。', `MaleText_loc7`='Tus soldados están siendo utilizados como escudos vivientes para evitar el fuego de los artilleros en el Valle de los Ecos, permitiendo que las fuerzas del Rey Exánime asalten tu base sin impedimentos.' WHERE `ID`=31014;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕은 대영주님의 한도가 무엇인지 압니다. 부하를 향해 발포할 수 없는 분임을 알지요. 이해가 안 가십니까? 리치 왕에게는 한도가 없습니다. 어떤 것에도 구속받지 않는단 말입니다.', `MaleText_loc4`='巫妖王清楚你心中的底线，大领主。他知道你是不会对自己人开火的。你还不明白吗？对他来说，不谈底线，不讲原则。', `MaleText_loc5`='巫妖王知道你的極限，大領主。他知道你不會對自己人開火。你不懂嗎?他沒有極限。不需要遵守規則。', `MaleText_loc7`='El Rey Exánime conoce tus límites, Alto Señor. Sabe que no dispararás a tus propios hombres. ¿No lo entiendes? Él no tiene límites. Ninguna regla que cumplir.' WHERE `ID`=31015;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 명예롭게 이 일을 해낼 걸세. 승리를 거둔다는 일념으로 스컬지와 같은 수준으로 추락하지는 않을 걸세. 그렇게 한다면 우리가 싸워 물리치려는 저들과 다를 바가 없지 않겠나!', `MaleText_loc4`='我们要光明正大地战斗，达里安。不能为了胜利，做出和天灾军团一样的行径。如果我们那么做了，和怪物又有什么差别！', `MaleText_loc5`='我們會帶著榮耀完成的，達瑞安。我們不會沉淪到天譴軍的程度以獲得勝利。這樣做只會讓我們跟那些我們要打敗的怪獸落到相同水平!', `MaleText_loc7`='Haremos esto con honor, Darion. No nos rebajaremos al nivel de la Plaga para ganar. ¡Eso no nos haría mejores que el monstruo al que intentamos destruir!' WHERE `ID`=31016;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런 생각 때문에 패하신 겁니다, 대영주님.', `MaleText_loc4`='那你就输定了，大领主。', `MaleText_loc5`='那你已經輸了，大領主。', `MaleText_loc7`='Entonces has perdido, Alto Señor.' WHERE `ID`=31017;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='토림! 나와라, 모습을 드러내란 말이다!', `MaleText_loc4`='托里姆！快出来吧！', `MaleText_loc5`='索林姆!快，現身吧!', `MaleText_loc7`='¡Thorim! ¡Ven, déjate ver!' WHERE `ID`=31018;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 귀부인의 은총에 영향을 받습니다!', `FemaleText_loc4`='%s受到了黑女巫的拥抱的影响！', `FemaleText_loc5`='%s受到寡婦之擁的影響!', `FemaleText_loc7`='¡El abrazo de la viuda afecta a %s!' WHERE `ID`=31019;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오래전 북풍이 홀로 이 봉우리들을 지배하던 시절, 강력한 타운카 족장의 형제가 이 땅을 탐하여 자신의 것으로 삼고자 했다.', `MaleText_loc4`='很久很久以前，北风独自统治着这片险峻的群山。这里还生活着一支强大的牦牛人氏族，酋长的兄弟企图争夺北风的控制权。', `MaleText_loc5`='許久以前，當只有北風精靈統治群山時，一個強大坦卡族酋長的兄弟試圖將這些土地據為己有。', `MaleText_loc7`='Hace mucho tiempo, cuando solo el Viento del Norte reinaba en estas cumbres, el hermano de un poderoso cabecilla taunka codiciaba estas tierras para sí.' WHERE `ID`=31020;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='족장의 형제인 스톰후프는 폭풍우 봉우리의 원래 지배자인 북풍을 몰아내고 봉우리를 차지하고자 병력을 모아 원정에 나섰다.', `MaleText_loc4`='他的名字叫做雷蹄。雷蹄纠集了一支军队，踏上了征服风暴峭壁，推翻其合法统治者——北风的征程。', `MaleText_loc5`='酋長的兄弟風暴之蹄，聚集了一切的力量想要征服風暴群山，打倒正統的支配者，北風精靈。', `MaleText_loc7`='El hermano del cabecilla, Pezuña Tempestuosa, reunió todas sus fuerzas y se propuso arrebatar Las Cumbres Tormentosas a su legítimo dueño, el Viento del Norte.' WHERE `ID`=31021;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰후프는 북풍의 영토 한가운데에서 북풍을 매복 공격하였다. 그의 간계는 거의 성공하는 듯했으나 북풍은 스톰후프의 비열한 공격을 이겨냈고, 스톰후프의 반역에 대한 응징으로 타운카들을 처형했다.', `MaleText_loc4`='雷蹄在北风的王国中心策划了一场伏击战，他的阴谋差一点就得逞了。但是北风侥幸逃生，最终处死了这个牦牛人，以此惩罚他的背叛。', `MaleText_loc5`='風暴之蹄在北風精靈的領域中心突襲他，他差點就要成功。但是北風精靈撐過風暴之蹄的詭計，並且處決了他作為入侵的懲罰。', `MaleText_loc7`='Pezuña Tempestuosa tendió una emboscada al Viento del Norte en el corazón de su territorio y estuvo a punto de lograr su plan. Pero el Viento del Norte sobrevivió a la traición de Pezuña Tempestuosa y ejecutó al taunka como castigo por su invasión.' WHERE `ID`=31022;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쐐기돌을 합칠 수 있도록 도와준 당신에게 어떻게 감사해야 할지 모르겠군요. 장담하건대 이 쐐기돌로 인해 대단한 일이 벌어질 겁니다.', `MaleText_loc4`='你修复了钥匙，我对此感激不尽。我保证，你的努力将成就伟大的事业。', `MaleText_loc5`='再多的言語也無法表達我對你組成拱心石的感謝。我跟你保證，這絕對關係重大。', `MaleText_loc7`='No puedo agradecerte suficiente toda la ayuda que has proporcionado para juntar la piedra angular. De aquí saldrán grandes cosas, te lo aseguro.' WHERE `ID`=31023;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무쇠 드워프들이... 사방에 깔렸군요... 저들은 지금 아래로 점점 내려오고 있습니다. 정말 악착같은 존재들입니다.', `MaleText_loc4`='铁矮人……到处都是……他们冲我们来了。这帮固执的家伙看来是不会放过我们的。', `MaleText_loc5`='鐵矮人...到處都是...他們從上頭攻下來。他們真的很頑強。', `MaleText_loc7`='Enanos férreos... por todas partes... Están bajando desde la cima. Son muy persistentes.' WHERE `ID`=31024;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들은 우리 비행기를 추락시킬 속셈이에요! 최대한 빨리 여길 벗어나야겠어요... 녀석들을 비행기에서 떼어 놓으세요!', `MaleText_loc4`='他们想要击落飞机！我没法往上攀升……别让他们靠近我们！', `MaleText_loc5`='他們想把飛機擊墜!我沒有辦法把機身拉得更高了...你得把他們從我們身旁弄走!', `MaleText_loc7`='¡Están intentando derribar el avión! No puedo inclinarlo más... ¡tienes que mantenerlos alejados de nosotros!' WHERE `ID`=31025;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위쪽에 더 있어요. 처치해 버려요!', `MaleText_loc4`='前面还有更多的铁矮人——坚持！', `MaleText_loc5`='上面還有更多 - 注意點!', `MaleText_loc7`='Hay más allí delante... ¡Sigue así!' WHERE `ID`=31026;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거의 다 빠져 나왔어요... 조금만 더 가면 됩니다.', `MaleText_loc4`='我们就快脱险啦……还差一点。', `MaleText_loc5`='我們差點就要出去了...只要再遠一點。', `MaleText_loc7`='Ya casi hemos salido, solo un poquito más lejos.' WHERE `ID`=31027;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 거수들이 돌만 던지지 않는다면 이제 좀 안전할 겁니다... 그나저나 저 아래는 난장판이네요.', `MaleText_loc4`='只要别被巨人扔下的石块砸到，我们就很安全……虽然下面已经被砸得一团糟了。', `MaleText_loc5`='除了那些巨人的零星巨石之外，我們應該很安全...不過底下看來是一團混亂。', `MaleText_loc7`='Salvo por las rocas desviadas de esos gigantes, debería estar despejado... aunque aquello de abajo parece un desastre.' WHERE `ID`=31028;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 숫자 좀 봐요. 어마어마하네요... 스톰하트 왕께서 도와주러 오셨다니 다행입니다. 그분에 관해서라면 좋은 얘기만 들었거든요. 드디어 만나뵐 수 있겠네요.', `MaleText_loc4`='他们的数量多得难以置信……好在雷心国王伸出了援手。我听说过他的许多事迹——是时候见见他了。', `MaleText_loc5`='他們的數量簡直不可置信...我很高興聽見風暴之心國王願意協助你。我聽過不少關於他的好事 - 我想這正是我們該見面的時候。', `MaleText_loc7`='Sus números son increíbles... Me alegra oír que el rey Cuoretormenta vino a ayudaros. Solo oigo cosas buenas sobre él, creo que es hora de que nos conozcamos.' WHERE `ID`=31029;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불쌍한 크레테우스. 훌륭한 감시자였죠... 그래도 자신의 임무를 완수하고 가서 다행입니다. 크레테우스에겐 그게 삶의 전부였을 테니까요.', `MaleText_loc4`='可怜的克莱特乌斯。他是个优秀的守护者……至少他完成了自己的使命。我相信，这件事的重要性对他来说是不言而喻的。', `MaleText_loc5`='可憐的克里圖思。他是個很不錯的看守者...我很高興起碼他有看著自己的任務圓滿完成，我想這對他來說是唯一的重要大事。', `MaleText_loc7`='Pobre Creteus. Era un buen vigilante... Me alegro de que al menos pudiera acabar su cometido, supongo que eso era lo único que le importaba.' WHERE `ID`=31030;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서리요새에 거의 다 왔어요. 떠나시기 전에 스톰하트 왕께 저를 좀 소개해 주시면 정말 고맙겠습니다. 우리 모두 그분께 큰 빚을 졌으니까요.', `MaleText_loc4`='我们就快抵达冰霜堡了。如果你能在离开前把我介绍给雷心国王，我会非常感激你的。我们俩都欠他一份情。', `MaleText_loc5`='我們即將抵達霜堡。如果你願意在走之前將我引介給風暴之心國王的話，我一定會非常感激。我相信我們都欠了他不少恩情。', `MaleText_loc7`='Estamos llegando al Fuerte Escarcha. Apreciaría mucho que me presentaras al rey Cuoretormenta antes de irte. Creo que ambos estamos en deuda con él.' WHERE `ID`=31031;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 모든 신과 여신의 이름으로... 이럴 수가... 무라딘 형님?!', `MaleText_loc4`='天啊……这不是……穆拉丁吗？！', `MaleText_loc5`='諸神在上...這不可能...穆拉丁?!', `MaleText_loc7`='Por todos los dioses... no puede ser... ¿Muradin?' WHERE `ID`=31032;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 형님, 틀릴 리가 없죠. 분명 무라딘 형님이 분명해요. 이 어린 동생을 알아보지 못하시겠어요?!', `MaleText_loc4`='哥们儿，我怎么会搞错啊——肯定是你。你不认识自己的弟弟了吗？！', `MaleText_loc5`='別開玩笑了，不可能弄錯的 - 這一定是你。你不認得你自己的弟弟了嗎?!', `MaleText_loc7`='Vamos, chico, es imposible equivocarse... eres tú. ¡¿No reconoces a tu hermano pequeño?!' WHERE `ID`=31033;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거 믿을 수가 없군요! 형님은 돌아가시지 않으셨나요! 들려오는 모든 이야기들이 형님이 돌아가셨다는 얘기였단 말입니다... 무라딘 형님, 무슨 일이 있었던 겁니까? 여긴 어떻게 오셨어요?', `MaleText_loc4`='我真不敢相信自己的眼睛！你不是死了吗？大家都这么认为……到底发生了什么事，穆拉丁。你怎么会在这里？', `MaleText_loc5`='我不相信!你已經死了!所有的證據都...到底發生了什麼事，穆拉丁。你怎麼來到這兒的?', `MaleText_loc7`='¡No puedo creerlo! ¡Estabas muerto! Todos los informes lo decían así que... ¿qué ocurrió, Muradin? ¿Cómo llegaste aquí?' WHERE `ID`=31034;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼요! 마그니 형님도 형님을 보면 매우 기뻐하실 겁니다! 지금까지 오랫동안 나쁜 소식 말고는 아무것도 듣지 못하셨으니 말이죠. 하지만 형님께서 나타나셨으니 모든 게 바뀔 겁니다!', `MaleText_loc4`='天哪！如果麦格尼见到你，不知道他会高兴成什么样子呢！他已经很久没有听到过好消息了，这次一定能令他欣喜若狂！', `MaleText_loc5`='的確!麥格尼見到你一定也會欣喜若狂!一直以來都只有壞消息傳進他耳中，但現在可不同了!', `MaleText_loc7`='¡Claro! ¡Magni se alegrará mucho de verte! Últimamente no ha recibido más que malas noticias, ¡pero esto lo cambia todo!' WHERE `ID`=31035;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마그니 형님께서 이곳 노스렌드에 와 계십니다. 형님을 찾으려고 말이죠. 윈터가드에 있는 현자가 말하길 형님께서 돌아가지 않으셨다고 했다더군요. 그래서 마그니 형님께서는 즉시 아이언포지를 떠나 형님을 찾으러 오셨답니다.', `MaleText_loc4`='眼下麦格尼就在诺森德，他是来寻找你的下落的。暮冬城的先知传来消息，说你还活着。于是麦格尼立即离开铁炉堡，来这里找你了。', `MaleText_loc5`='他也在北裂境，兄弟，為了要找你。一個溫特加德的先知說你還活著，接著他就丟下了鐵爐堡立刻趕來尋找你。', `MaleText_loc7`='Él está en Rasganorte, hermano. Buscándote. Un vidente de Hibergarde dijo que no estabas muerto y partió de Forjaz inmediatamente para venir a buscarte.' WHERE `ID`=31036;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누구지? 나한테 얘기하는 건가?', `MaleText_loc4`='什么？你是在和我说话吗？', `MaleText_loc5`='什麼?你在跟我說話，小夥子?', `MaleText_loc7`='¿Qué es eso? ¿Me estás hablando, chico?' WHERE `ID`=31037;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 형제라... 그래... 내게 형제가 있지...', `MaleText_loc4`='我的弟弟？呃……我倒是有几个兄弟……', `MaleText_loc5`='我的兄弟...是...我確實有兄弟...', `MaleText_loc7`='Mi hermano... sí... tengo hermanos...' WHERE `ID`=31038;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무라딘의 머릿속에 지난 기억들이 밀려드는 듯 머리를 부여잡고 잠시 비틀댑니다.', `MaleText_loc4`='穆拉丁抓着脑袋，使劲地晃了晃，一幕幕的往事渐渐涌入他的脑海。', `MaleText_loc5`='隨著回憶衝擊著他，穆拉丁抓著自己的頭搖晃了好一陣子。', `MaleText_loc7`='Muradin se agarra la cabeza y se tambalea un instante mientras los recuerdos vuelven a él.' WHERE `ID`=31039;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 브란?', `MaleText_loc4`='……布莱恩？', `MaleText_loc5`='...布萊恩?', `MaleText_loc7`='¿...Brann?' WHERE `ID`=31040;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전혀 옳지 않아, $n. 바람의 조련사 바라가 해준 이야기에 따르면 스톰후프는 악당이 아닌 영웅이었네.', `MaleText_loc4`='完全不对，$n。在驯风者巴兰告诉我的传说里，雷蹄是个英雄，不是暴徒。', `MaleText_loc5`='這整個也不對勁，$n。馴風者巴拉告訴我，風暴之蹄是個英雄，不是個惡棍。', `MaleText_loc7`='Esto no está nada bien, $n. Es la historia que me contó la domadora del viento Barah, Pezuña Tempestuosa era un héroe, no un villano.' WHERE `ID`=31041;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난... 잘 모르겠다, 브란. 여기 너무 오랫동안 있었어... 이전의 삶에서 기억나는 것이라곤 섬뜩한 순간들과 악몽뿐이야.', `MaleText_loc4`='我……我不知道，布莱恩。我在这里待了很长时间……但是在此之前的记忆，只剩下支离破碎的噩梦。', `MaleText_loc5`='我...我不知道，布萊恩。我在這裡很久了...我在來到此地之前的生命都像是閃光和夢魘。', `MaleText_loc7`='No... no sé, Brann. Llevo mucho tiempo aquí... todo lo que recuerdo de mi vida antes de venir aquí son fragmentos y pesadillas.' WHERE `ID`=31042;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 만나게 되어 정말 기쁘구나. 말로는 다 표현할 수 없을 정도야.', `MaleText_loc4`='见到你我还是很高兴的。我真是激动得不知道说什么好了。', `MaleText_loc5`='但我還是很高興見到你，兄弟。千言萬語也說不盡我的喜悅。', `MaleText_loc7`='Me alegro de verte, hermano. Más de lo que puedo expresar con palabras.' WHERE `ID`=31043;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='북풍은 예로부터 타운카의 적이었네. 그는 정령의 군주이자 부족민의 목숨을 오랫동안 앗아간 존재라네.', `MaleText_loc4`='北风是牦牛人的夙敌。它统治着元素生物，肆意践踏着牦牛人的性命。', `MaleText_loc5`='北風精靈是坦卡族的宿敵，眾多元素的統治者，長期以來傷害這支古老民族的禍首。', `MaleText_loc7`='El Viento del Norte es el ancestral enemigo de los taunka, un soberano entre los elementos y la fuerza que arrebata la vida a este antiguo pueblo.' WHERE `ID`=31044;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마그니 형님! 기억이 서서히 돌아오는 중이니 이해해 주시기 바랍니다.', `MaleText_loc4`='麦格尼！很抱歉啊，我的记忆恢复得很慢。', `MaleText_loc5`='麥格尼!原諒我，我的回憶恢復得很慢，兄弟。', `MaleText_loc7`='¡Magni! Perdóname, estoy recuperando los recuerdos poco a poco, hermano.' WHERE `ID`=31045;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들은 북풍에 굴하기는커녕 죽음을 택했을 걸세. 뭔가 잘못되었어.', `MaleText_loc4`='他们宁愿死，也不愿意臣服于北风。这里出了差错。', `MaleText_loc5`='他們寧願去死也不可能向北風精靈屈膝。這其中一定有問題。', `MaleText_loc7`='Preferirían morir antes que inclinarse ante el Viento del Norte. Algo va mal aquí.' WHERE `ID`=31046;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서릿결 부족은 저에게 잘 해주었습니다. 매우 강한 친구들이지요.', `MaleText_loc4`='霜脉矮人对我很好。他们非常强壮。', `MaleText_loc5`='霜誕矮人對我非常友善。他們是一群堅強的民族。', `MaleText_loc7`='Los Natoescarcha han sido muy buenos conmigo. Son gente fuerte.' WHERE `ID`=31048;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가르침의 망치라...', `MaleText_loc4`='知识之锤……', `MaleText_loc5`='博識之錘...', `MaleText_loc7`='El martillo de conocimiento...' WHERE `ID`=31049;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더욱 의심스러워지는군. 시간의 실마리가 꼬이며 잘못된 무늬를 만들어내 버렸어. 하지만 어떻게 말인가?', `MaleText_loc4`='这证实了我们的怀疑。时间流的进程被切断了，历史也被篡改了。这是怎么做到的呢？', `MaleText_loc5`='這證實了我們的疑慮。時間線被剝離，然後重寫成錯誤的模樣。但這怎麼辦到的?', `MaleText_loc7`='Esto confirma nuestras sospechas. Los hilos del tiempo han sido cortados y vueltos a tejer con un patrón incorrecto. Pero... ¿cómo?' WHERE `ID`=31050;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대의 $r의 공헌이 수준을 넘어섰다, 폭풍군주여. $g그:그녀;의 공헌은 우리 백성의 마음을 누그러트리는 데 일조했다.', `MaleText_loc4`='风暴之王，您的$r仆人做出了超乎寻常的高尚行为。通过努力，$g他:她;已经成功地软化了我的子民的心。', `MaleText_loc5`='風暴之王，您$r僕人的高貴義舉遠遠超過了$g他的:她的;身材高度。$g他的:她的;作為成功地軟化我們的心。', `MaleText_loc7`='Los actos de tu sirviente $r desafían su naturaleza, Señor de la Tormenta. Sus esfuerzos han conseguido ablandar los corazones de mi gente.' WHERE `ID`=31051;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강대한 토림에게서 이런 겸허한 말을 들어본 적이 없군. 그대가 한 말을 던 니펠렘에 전하겠다.', `MaleText_loc4`='托里姆竟然说出过如此谦卑的言辞。我会将你的这番话转达给丹尼芬雷的。', `MaleText_loc5`='從未聽過偉大的索林姆說出如此謙卑的言語。我將會把您的話傳達到丹尼弗蘭。', `MaleText_loc7`='Thorim jamás había pronunciado unas palabras tan humildes. Llevaré tu mensaje a Dun Niffelem.' WHERE `ID`=31052;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이로써 내 백성이 그 어두운 나날에 벌어진 일들을 용서하였다. 그들은 다시 그 일에 대해서 언급하지 않을 거다.', `MaleText_loc4`='我们决定宽恕你在黑暗时代的所作所为。不会再有谁提起那些往事了。', `MaleText_loc5`='我的族人將會寬恕在黑暗之日所發生的事情，永遠不再提起。', `MaleText_loc7`='Por la presente, mi gente perdona los actos acaecidos en aquel oscuro día. Nunca se volverá a hablar de ellos.' WHERE `ID`=31053;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 다져진 우리 친선을 알리는 의미로 그대의 물건인 것을 돌려 주겠다...', `MaleText_loc4`='作为我们重铸友谊的见证，我就把这东西物归原主吧……', `MaleText_loc5`='為了表示我們友誼的重鑄，我有一樣東西原本是屬於您的...', `MaleText_loc7`='Para honrar nuestra renovada amistad, tengo algo que te pertenece...' WHERE `ID`=31054;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파괴전차를 만들고 싶습니다.', `MaleText_loc4`='我要造一辆攻城车。', `MaleText_loc5`='我想要製造一台石毀車。', `MaleText_loc7`='Me gustaría construir un demoledor.', `FemaleText_loc1`='파괴전차를 만들고 싶습니다.', `FemaleText_loc4`='我要造一辆攻城车。', `FemaleText_loc5`='我想要製造一台石毀車。', `FemaleText_loc7`='Me gustaría construir un demoledor.' WHERE `ID`=31055;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하신가, $r. 뭘 도와줄까?', `MaleText_loc4`='你好，$r。我能帮你什么忙吗？', `MaleText_loc5`='嗨，$r。有什麼我能幫忙的嗎?', `MaleText_loc7`='Hola, $r. ¿En qué puedo ayudarte hoy?', `FemaleText_loc1`='안녕하세요, $r. 뭘 도와드릴까요?', `FemaleText_loc4`='你好，$r。我能帮你什么忙吗？', `FemaleText_loc5`='嗨，$r。有什麼我能幫忙的嗎?', `FemaleText_loc7`='Hola, $r. ¿En qué puedo ayudarte hoy?' WHERE `ID`=31056;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거대한 폭발이 그 지역을 뒤덮었을 때, 내 아버지께서는 우리 적의 손에 넘어가지 않도록 그 거대한 망치에 룬 마법을 시전하셨다. 그분이 행하신 마지막 일이셨지...', `MaleText_loc4`='大爆炸来临时，我的父亲对锤子施放了符文，绝不能让它落入敌人之手。这是他做的最后一件事……', `MaleText_loc5`='當強烈的爆炸充斥在這個區域時，我父親在一柄偉大的戰錘上銘刻了一個符文，讓它不會被我們的敵人所佔有。這是他所做的最後一件事...', `MaleText_loc7`='Cuando la gran explosión cubrió la región, mi padre lanzó una runa sobre el gran martillo para que no pudieran poseerlo nuestros enemigos. Fue lo último que hizo...' WHERE `ID`=31057;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='투석기를 만들고 싶습니다.', `MaleText_loc4`='我要造一辆投石车。', `MaleText_loc5`='我想製造一台投石車。', `MaleText_loc7`='Me gustaría construir una catapulta.', `FemaleText_loc1`='투석기를 만들고 싶습니다.', `FemaleText_loc4`='我要造一辆投石车。', `FemaleText_loc5`='我想製造一台投石車。', `FemaleText_loc7`='Me gustaría construir una catapulta.' WHERE `ID`=31058;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강대한 토림이여, 우린 그대의 곁에서 싸울 기회를 기꺼이 받아들이는 바이다.', `MaleText_loc4`='托里姆，希望今后还能与你并肩作战。', `MaleText_loc5`='我們歡迎再次與您並肩作戰的機會，偉大的索林姆。', `MaleText_loc7`='Damos la bienvenida a la oportunidad de volver a luchar a tu lado, poderoso Thorim.' WHERE `ID`=31059;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='던 니펠렘으로 돌아가야만 한다. 폭풍군주여, 우린 곧 다시 만날 것이다.', `MaleText_loc4`='我必须返回丹尼芬雷了。风暴之王，我相信我们还会见面的。', `MaleText_loc5`='我得要回去丹尼弗蘭。我們很快就能再次談談，風暴之王。', `MaleText_loc7`='Debo regresar a Dun Niffilem. Volveremos a hablar pronto, Señor de la Tormenta.' WHERE `ID`=31060;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공성 차량을 생산하고 싶습니다.', `MaleText_loc4`='我要造一辆攻城坦克。', `MaleText_loc5`='我想要製造一台攻城機具。', `MaleText_loc7`='Me gustaría construir una máquina de asedio.', `FemaleText_loc1`='공성 차량을 생산하고 싶습니다.', `FemaleText_loc4`='我要造一辆攻城坦克。', `FemaleText_loc5`='我想要製造一台攻城機具。', `FemaleText_loc7`='Me gustaría construir una máquina de asedio.' WHERE `ID`=31061;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 그대와 그대의 백성에게 불러들인 고통을 용서해 주기를 청하고 싶도다.', `MaleText_loc4`='请求您宽恕我为您和您的子民带来的痛苦和伤害。', `MaleText_loc5`='我想向你和你的同胞尋求原諒，寬恕我對你們所造成的苦難。', `MaleText_loc7`='Quiero disculparme por el sufrimiento que os he causado a ti y a tu pueblo.' WHERE `ID`=31062;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크롤미르로군... 요쿰, 고맙도다. 이 망치가 아직도 남아 있으리라 감히 기대하지 않았다. 다시 한번 영광스러운 전투에 나서게 되리라!', `MaleText_loc4`='科洛米尔……谢谢你，约库姆。我都不敢奢望它还完好无损。很快，它将再次见证光辉的战役！', `MaleText_loc5`='克洛米爾...我感謝你，裘庫姆。我甚至不敢期待它依舊存在。很快地它又能再次見到光榮的戰鬥!', `MaleText_loc7`='Krolmir... Gracias Jokkum. No me atrevía a soñar con que aún existiera. ¡Pronto volverá a ser testigo de una gloriosa batalla!' WHERE `ID`=31063;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제트 비행기를 만들고 싶습니다.', `MaleText_loc4`='我要造一架战斗机。', `MaleText_loc5`='我想製造一台戰鬥機。', `MaleText_loc7`='Me gustaría construir un caza aéreo.', `FemaleText_loc1`='제트 비행기를 만들고 싶습니다.', `FemaleText_loc4`='我要造一架战斗机。', `FemaleText_loc5`='我想製造一台戰鬥機。', `FemaleText_loc7`='Me gustaría construir un caza aéreo.' WHERE `ID`=31064;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 생각하나?', `MaleText_loc4`='你在想什么，孩子？', `MaleText_loc5`='你在想什麼，小夥子?', `MaleText_loc7`='¿Qué tienes en mente, chico?' WHERE `ID`=31065;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미안하지만, 허가받은 호드의 장교만 탈것을 살 수 있다네.', `MaleText_loc4`='对不起，朋友。只有部落的正式军官才有权购买载具。', `MaleText_loc5`='抱歉，朋友。只有被認可的部落軍官才有權購買一台載具。', `MaleText_loc7`='Lo siento, colega. Solo oficiales certificados de la Horda pueden autorizar la compra de un vehículo.', `FemaleText_loc1`='미안하지만, 허가받은 호드의 장교만 탈것을 살 수 있어요.', `FemaleText_loc4`='对不起，朋友。只有部落的正式军官才有权购买载具。', `FemaleText_loc5`='抱歉，朋友。只有被認可的部落軍官才有權購買一台載具。', `FemaleText_loc7`='Lo siento, colega. Solo oficiales certificados de la Horda pueden autorizar la compra de un vehículo.' WHERE `ID`=31066;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭격기를 만들고 싶습니다.', `MaleText_loc4`='我要造一架轰炸机。', `MaleText_loc5`='我想要製造一台轟炸機。', `MaleText_loc7`='Me gustaría construir un bombardero.', `FemaleText_loc1`='폭격기를 만들고 싶습니다.', `FemaleText_loc4`='我要造一架轰炸机。', `FemaleText_loc5`='我想要製造一台轟炸機。', `FemaleText_loc7`='Me gustaría construir un bombardero.' WHERE `ID`=31067;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벌목기를 만들고 싶습니다.', `MaleText_loc4`='我要造一架伐木机。', `MaleText_loc5`='我想要製造一台伐木機。', `MaleText_loc7`='Me gustaría construir una trituradora.', `FemaleText_loc1`='벌목기를 만들고 싶습니다.', `FemaleText_loc4`='我要造一架伐木机。', `FemaleText_loc5`='我想要製造一台伐木機。', `FemaleText_loc7`='Me gustaría construir una trituradora.' WHERE `ID`=31068;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘도 좋은 벗들을 많이 잃었지. 리치 왕은 자기가 앗아간 생명 하나하나마다 그 대가를 치러야 할 것이야!', `MaleText_loc4`='今天，我们失去了一批优秀的战士。巫妖王要为这场血腥的杀戮付出代价！', `MaleText_loc5`='我們今天失去了許多善良的人們，小夥子。巫妖王一定要為他所毀滅的生命付出代價!', `MaleText_loc7`='Hemos perdido a mucha gente Buena hoy, tío. ¡El Rey Exánime pagará por todas las vidas que ha arruinado!' WHERE `ID`=31069;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영원노래 숲 말입니다, 달포르스 님. 저는 아서스가 죽음의 낫을 휘두르기 전에 영원노래 숲이 얼마나 아름다웠는지를 생각하고 있습니다...', `MaleText_loc4`='永歌森林，达尔弗斯。我至今仍然记得，在阿尔萨斯将死亡的气息散播到那片森林之前，她是多么的美丽……', `MaleText_loc5`='永歌森林，達佛斯。在阿薩斯劃下一道死亡地帶之前，這裡曾有多美麗...', `MaleText_loc7`='El Bosque Canción Eterna, Dalfors. Estaba pensando en lo bonito que era antes de que Arthas lo cubriera de muerte...' WHERE `ID`=31070;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 끝입니다, 달포르스 님. 스컬지가 끝장나는 꼴을 보는 순간이 얼마나 가까이 다가왔는지를 생각하고 있습니다.', `MaleText_loc4`='末日，达尔弗斯。我们还要多久才能看到天灾军团的末日呢。', `MaleText_loc5`='終結，達佛斯。我在想我們到底有多靠近天譴軍團的終結?', `MaleText_loc7`='El final, Dalfors. Pensaba en lo cerca que estamos de ver el final de la Plaga.' WHERE `ID`=31071;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 저놈들은 그토록 빨리 대응할 수 있습니까, 달포르스 님? 저희 계획은 완벽했는데 말이지요. 이해가 안 갑니다.', `MaleText_loc4`='他们的反应为何如此之快，达尔弗斯？我们的计划几乎是天衣无缝啊。我真是想不通。', `MaleText_loc5`='他們怎麼會反應得這麼快，達佛斯?我們的計畫這麼完美。我不懂。', `MaleText_loc7`='¿Cómo han podido reaccionar tan deprisa, Dalfors? Nuestro plan era perfecto. No lo entiendo.' WHERE `ID`=31072;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 상처는 곧 나을 걸세.', `MaleText_loc4`='伤口会愈合的，孩子。', `MaleText_loc5`='傷痛終究會痊癒，孩子。', `MaleText_loc7`='Las heridas se curarán, chico.' WHERE `ID`=31073;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러게나 말입니다, 달포르스 님...', `MaleText_loc4`='他会的，达尔弗斯……', `MaleText_loc5`='誠然，達佛斯...', `MaleText_loc7`='Él es eso, Dalfors...' WHERE `ID`=31074;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그건 전혀 의심하지 않습니다, 달포르스 님. 하지만, 그런 일을 볼 때까지 살아남을 수 있을까요?', `MaleText_loc4`='我毫不怀疑这一点，但是我们真的能活着见到那一天吗？', `MaleText_loc5`='我一點也不懷疑，達佛斯，只是我們能活到那一天嗎?', `MaleText_loc7`='No lo dudo, Dalfors, pero ¿seguiremos con vida para verlo?' WHERE `ID`=31075;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그는 모든 생명을 앗아갔습니다... 죄 없는 사람들에게 그토록 가혹한 고통과 고난이 닥치다니. 도대체 무엇 때문에 말입니까?', `MaleText_loc4`='他夺走了多少鲜活的生命……给无辜的民众带来了多少痛苦。为了什么？', `MaleText_loc5`='所有他奪走的生命...那些加諸在無辜人們身上的痛苦與不幸。然而是為了什麼?', `MaleText_loc7`='Todas las vidas que ha arrebatado... Tanta miseria y dolor infligidos a los inocentes. ¿Y para qué?' WHERE `ID`=31076;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='치유할 수 없는 상처도 있습니다. 상처받은 영혼은 고칠 수 없는 법이지요.', `MaleText_loc4`='高贵的矮人，有的伤口是难以愈合的。破碎的灵魂要如何复原。', `MaleText_loc5`='有些創傷永遠也不會痊癒，高貴的矮人。一個破碎的靈魂永遠也無法拼湊回來。', `MaleText_loc7`='Algunas heridas nunca se curan, noble enano. Un alma rota no se puede arreglar.' WHERE `ID`=31077;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 형제의 광기를 끝낼 때가 되었다.', `MaleText_loc4`='是时候阻止洛肯的愚蠢行径了。', `MaleText_loc5`='該是時候終結我兄長的瘋狂了。', `MaleText_loc7`='Ya es hora de que ponga punto final a la locura de mi hermano.' WHERE `ID`=31078;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로켄!!', `MaleText_loc4`='洛肯！！！', `MaleText_loc5`='洛肯!!', `MaleText_loc7`='¡Loken!' WHERE `ID`=31079;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일어나서 나와 싸워라, 보잘것없는 배신자여!', `MaleText_loc4`='来吧，和我交战！你这没用的叛徒！', `MaleText_loc5`='站起來和我一戰，你這沒用的叛徒!', `MaleText_loc7`='¡Levántate y lucha contra mí, despreciable traidor!' WHERE `ID`=31080;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 만나게 돼서 반갑네!$B$B스톰하트 왕께서는 잠시 휴가를 떠나시겠다고 말씀하셨네... 아마도 불쾌한 기억 때문에 풀어야 할 일이 있으신 모양일세. 혼자 지내겠다고 완강히 주장하시기에, 언제나 그렇듯 그분의 뜻을 존중하기로 했네.$B$B하지만 그동안은 내가 부족을 지키는 일을 맡게 되었다네. 물론 우리 부족은 언제든지 자네를 환영하네.', `MaleText_loc4`='很高兴再次见到你！$B$B雷心国王告诉我，说他会离开一段日子……他回忆起一些可怕的往事，决定算清这笔旧账。他坚持不让我们随行，按照惯例，我们也尊重他的决定。$B$B同时，我负责接管整个氏族。当然，你仍然是我们的贵客。', `MaleText_loc5`='很高興再次見到你!$B$B風暴之心國王已經離去一陣子了...他回想起一個悲傷的記憶，需要好好冷靜。他很堅持要我們不用跟著他，所以我們如往常尊重他的意願。$B$B而現在我負責領導我們氏族。當然，我們還是一樣歡迎你。', `MaleText_loc7`='¡Me alegro de volver a verte!$B$BEl rey Cuoretomenta ha informado de que estará fuera una temporada... Parece ser que tiene cuentas que saldar relacionadas con un amargo recuerdo. Insistió en que no fuéramos con él, así que hemos respetado su voluntad, como siempre.$B$BYo soy el responsable de nuestro clan mientras tanto. Aún te damos la bienvenida entre nosotros, por supuesto.' WHERE `ID`=31081;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형제여, 네가 사랑하는 시프에게 가고 싶어 안달이 난 게로구나.', `MaleText_loc4`='托里姆，急着和你心爱的西芙做伴吗？', `MaleText_loc5`='你看來急著想去陪伴你摯愛的希芙，兄弟。', `MaleText_loc7`='Pareces deseoso de unirte a tu amada Sif, hermano.' WHERE `ID`=31082;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히...', `MaleText_loc4`='你竟敢……', `MaleText_loc5`='你不配...', `MaleText_loc7`='Ni se te ocurra...' WHERE `ID`=31083;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여보게, 라그누스. 난 자네가 능력 있는 친구라 생각하네만 난 인내심이 많지 않다네. 무라딘이 이곳에 있는 걸 아네. 내 형제에게 날 인도해 주지 않을 텐가?!', `MaleText_loc4`='拉格努斯，我一直觉得你是个人材，不过我的耐心正在逐渐消失。我知道穆拉丁在这里，但是你到底能不能带我找到他？！', `MaleText_loc5`='聽著，拉格努斯，我認為你是個有能力的人，但我的耐心越來越薄弱。我知道穆拉丁在這裡，你到底能不能告訴我他的確切位置?!', `MaleText_loc7`='Mira Lagnus, creo que eres un hombre muy capaz, pero se me está agotando la paciencia. Sé que Muradin está aquí, ¿puedes decirme dónde o no?' WHERE `ID`=31084;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동생아! 여기 있었구나! 지금 내 눈에 보이는 게 현실인지 믿기가 어렵구나... 네가 살아 있다니!', `MaleText_loc4`='我的兄弟！真的是你！我几乎不敢相信自己的眼睛……你还活着！', `MaleText_loc5`='兄弟!你在這裡!我幾乎不敢相信我的眼睛...你還活著!', `MaleText_loc7`='¡Hermano! ¡Ahí estás! Apenas puedo creer lo que veo... ¡estás vivo!' WHERE `ID`=31085;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무라딘아, 너를 다시 보게 되다니 정말 기쁘구나. 그리고 네가 거느린 무리의 왕이 되었다는 게 무슨 소리냐? 브론즈비어드 가문은 항상 왕가의 혈통이 될 운명을 타고 났지 않니.', `MaleText_loc4`='能再见到你真是太好了，穆拉丁。我听说你现在登上了王座，真的吗？铜须家族的人注定是要成为大人物的！', `MaleText_loc5`='能再看見你真好，穆拉丁。我聽說你靠著自己的力量成為了一位國王?我們銅鬚家族注定就是要成就偉大的事業。', `MaleText_loc7`='Me alegro de volver a verte, Muradin. ¿Y qué es eso que he oído de que ahora eres todo un Rey? Los Barbabronce siempre estuvieron destinados a la grandeza.' WHERE `ID`=31086;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 이야기라면...', `MaleText_loc4`='说起来……', `MaleText_loc5`='說到這個...', `MaleText_loc7`='A propósito de eso...' WHERE `ID`=31087;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래! 네 몸은 여전히 단단하구나. 무슨 일이 있었는지 기억하느냐, 무라딘? 네가 없는 동안 심술궂은 운명 탓에 일어난 일을 말이야.', `MaleText_loc4`='似乎的确如此！你看上去还是那么强壮。你还记得发生了什么事吗，穆拉丁？在你离开的日子里，命运愈发糟糕了。', `MaleText_loc5`='看來正是如此!而且你跟以前一樣強壯。你記得到底發生什麼事嗎，穆拉丁?你不在的時候命運對我們十分嚴苛。', `MaleText_loc7`='¡Eso parece! Tú no has perdido ni una pizca de músculo. ¿Recuerdas algo de lo que ocurrió, Muradin? Todo han sido infortunios en tu ausencia.' WHERE `ID`=31088;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기억나는 것은 많지 않습니다, 마그니 형님. 전 악몽을 꾸었습니다... 키가 큰... 밝은 색 머리의... 죽음의 검은 갑옷을 입은 자가 나타났지요. 그의 이름이 혀끝에서 맴돌기는 하지만...', `MaleText_loc4`='我不太记得了，麦格尼。我经常做噩梦，梦见一个人类……很高……浅色的头发……死黑色的盔甲。他的名字……话在嘴边却说不出口……', `MaleText_loc5`='不太多，麥格尼。我有時會做關於一個人類的惡夢...高大...金髮...黑色的死亡鎧甲。他的名字就停在我的舌尖，但我...', `MaleText_loc7`='No mucho, Magni. He tenido pesadillas con un humano... alto... con el pelo claro... armadura de color negro muerte. Tengo su nombre en la punta de la lengua, pero...' WHERE `ID`=31089;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='박사님께서는 전신이 거의 다 바르굴인 살덩이 거인 네르겔드를 만드는 계획을 내게 맡기셨다! 네르겔드는 네 한심한 병력을 끝장내도록 만들어질 피조물 군단과 살덩이 거인 무리 전체를 통틀어 가장 강력한 존재일 것이다!', `MaleText_loc4`='博士委托我执行关于尼尔盖德的计划，那可是完全由瓦古制成的血肉巨人！它将成为最强大的血肉巨人，只要有一整支这样的巨人组成的部队，你们就全都玩完了！', `MaleText_loc5`='博士把奈傑德的計畫書託付給我，我們的血肉巨人全是由維酷人所融合!他們是血肉巨人中最強大的，整個軍團的血肉巨人將會摧毀你們可悲的部隊!', `MaleText_loc7`='¡El doctor me confió los planos de Nergeld, nuestra amalgama gigante hecha de vargul! ¡Será la creación más poderosa de su especie y se creará una legión entera de ellos para acabar con tu penoso ejército!' WHERE `ID`=31090;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 아서스.', `MaleText_loc4`='……阿尔萨斯。', `MaleText_loc5`='...阿薩斯。', `MaleText_loc7`='...Arthas.' WHERE `ID`=31091;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마그니가 고개를 끄덕입니다.', `MaleText_loc4`='麦格尼点了点头。', `MaleText_loc5`='麥格尼點點頭。', `MaleText_loc7`='Magni asiente.' WHERE `ID`=31092;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그는 이제 네가 알던 이가 아니다, 무라딘. 완전히 다른 사람이 되었단다.', `MaleText_loc4`='他不再是你记忆中的男孩了，穆拉丁。他已经完全变了。', `MaleText_loc5`='他已經不再是你記憶中的那個小夥子了，穆拉丁。他完全變成了另一種東西。', `MaleText_loc7`='Ya no es el chico que recordamos, Muradin. Se ha convertido en algo totalmente distinto.' WHERE `ID`=31093;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 압니다. 그가 돌아서는 걸 보았지요... 올바른 길을 모두 포기하는 걸 지켜봤지만 저는 아무것도 하지 않았습니다... 최후의 순간까지도 말이죠.', `MaleText_loc4`='嗯，我知道。我亲眼目睹了他的转变……我看着他抛弃正义，而我却没有伸出援手……等我意识到事情的严重性时，一切都晚了。', `MaleText_loc5`='唉，我知道。我親眼看著他轉變...我看著他放棄正道卻沒有伸出援手...我甚至想都沒想過，直到這一切都太遲了。', `MaleText_loc7`='Sí, lo sé. Yo le vi convertirse... Le vi abandonar todo lo que era bueno y no moví un dedo... Ni siquiera pensé en ello hasta que fue demasiado tarde.' WHERE `ID`=31094;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 찾는 정보를 넘겨주는 일은 절대 없다!', `MaleText_loc4`='我不会告诉你的！', `MaleText_loc5`='我絕對不會把你要的消息交給你!', `MaleText_loc7`='¡Nunca te daré la información que buscas!' WHERE `ID`=31095;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 지난 일입니다, 무라딘 형님. 후회해봤자 달라지는 일은 없어요.', `MaleText_loc4`='那已经是陈年旧事了，穆拉丁。后悔是没有用的。', `MaleText_loc5`='這都過去了，穆拉丁。後悔改變不了任何事。', `MaleText_loc7`='Eso forma parte del pasado, Muradin. Arrepentirse no cambiará nada.' WHERE `ID`=31096;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래... 달라질 건 없지. 하지만 제대로 되돌려놓을 수는 있어... 그렇게 해야만 한다. 그를 뒤쫓아 그가 한 모든 일에 대한 해답을 들어야겠다.', `MaleText_loc4`='是的……后悔是没用的。但是我能纠正这一切……我必须这么做。我要找到那个孩子，让他为自己的所作所为负责。', `MaleText_loc5`='不...它們不會。但我可以改變它...我有...是我跟著那個小夥子。我要他為了他所做的一切做出解釋。', `MaleText_loc7`='No... no lo harán. Pero puedo arreglarlo... tengo que hacerlo. Voy a por el chico. Le haré pagar por todo lo que ha hecho.' WHERE `ID`=31097;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='귀중한 내 시간을 허비하게 하지 마라! 아무것도 말하지 않겠다!', `MaleText_loc4`='别浪费时间了。我什么都不会说的！', `MaleText_loc5`='你在浪費我的時間。我什麼都不會告訴你!', `MaleText_loc7`='Malgastas mi tiempo. ¡No te contaré nada!' WHERE `ID`=31098;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말인가, 무라딘? 네가 죽었다고 생각하며 지낸 지 수년 만에 다시 만났는데... 너를 다시 잃고 싶지 않다.', `MaleText_loc4`='你是认真的吗，穆拉丁？这些年来，我一直以为你已经死了，现在好不容易才找到你，我不想再失去你。', `MaleText_loc5`='你確定，穆拉丁?這麼多年來我一直以為你已經死了，如今你回來。我可不要再次失去你。', `MaleText_loc7`='¿Estás seguro, Muradin? Acabo de reencontrarte después de pasar muchos años pensando que estabas muerto. No quiero volver a perderte.' WHERE `ID`=31099;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진심입니다, 마그니 형님. 잘해낼 테니 걱정하지 마십시오.', `MaleText_loc4`='我是认真的，麦格尼。我会小心处理的，别担心。', `MaleText_loc5`='我很確定，麥格尼。我都經歷過了，別替我擔心。', `MaleText_loc7`='Estoy seguro, Magni. Saldré de esta, no te preocupes.' WHERE `ID`=31100;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 그렇게 해라. 난 백성에게 돌아가야만 한다. 살아서 돌아와야 한다.', `MaleText_loc4`='那就这样吧。我要回去了。祝你平安。', `MaleText_loc5`='那就這樣吧。我得回到我的人民身邊，兄弟。活著回來找我。', `MaleText_loc7`='Que así sea. Tengo que volver junto a mi pueblo, hermanos. Regresad de una sola pieza.' WHERE `ID`=31101;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 조심하십시오, 무라딘 형님. 함께하고 싶지만 세상에서 아직 보지 못한 가장 대단한 발견 직전이라서 말입니다. 지금은 이 일을 단념할 수가 없답니다.', `MaleText_loc4`='穆拉丁，保重。我很想与你同行，但是我正在发掘一个足以震惊世界的秘密。我不能半途而废。', `MaleText_loc5`='唉，自己保重，穆拉丁。我應該要加入你的，但我正在進行這世界從所未有的驚人發現。我實在沒辦法現在放棄。', `MaleText_loc7`='Sí, mantente a salvo. Muradin. Me uniría a ti, pero estoy a punto de realizar el descubrimiento más impresionante que haya visto el mundo. No puedo abandonarlo ahora.' WHERE `ID`=31102;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가거라, 브란. 우리가 다시 만날 땐 내게 멋진 이야기를 들려줘야 한다. 당분간 안녕히...', `MaleText_loc4`='去吧，布莱恩。下次见面时，你再告诉我这个惊天动地的故事吧。再见，兄弟们。', `MaleText_loc5`='去吧，布萊恩。等我們再次見面的時候，你欠我一個精采的史詩故事。保重了，兄弟們。', `MaleText_loc7`='Vete, Brann. Tráeme una historia épica cuando volvamos a vernos. Adiós por el momento, hermanos.' WHERE `ID`=31103;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하찮은 네 녀석 따윈 한방에 날려버리고 그몸은 우리가 무언가 만들 때 재료로 써 주지!', `MaleText_loc4`='我要杀了你，再把你跺碎了加入我们正在制造的巨人里！', `MaleText_loc5`='我會殺了你，小傢伙。然後我會把你的屍體加入我們的創造物之中!', `MaleText_loc7`='Te mataré, criatura insignificante, ¡y añadire las extremidades de tu cuerpo a lo que estamos creando!' WHERE `ID`=31104;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 열심히 일한 것을 망가뜨리게 두지는 않겠다! 너희 모두는 네르겔드가 되는 최후를 맞이할 것이다!', `MaleText_loc4`='我不会让你毁了我们的劳动成果的！尼尔盖德会把你们都干掉的！', `MaleText_loc5`='我不會讓你摧毀我們辛苦工作的成果!奈傑德會毀滅你們全部!', `MaleText_loc7`='¡No dejaré que destruyáis nuestro trabajo! ¡Nergeld acabará con todos nosotros!' WHERE `ID`=31105;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='박사님께서 돌아오시면, 그 한심한 어둠의 무기고 따위는 가루가 될 테지.', `MaleText_loc4`='等博士回来，暗影拱顶就会变成一片废墟。', `MaleText_loc5`='等博士回來，你們可笑的暗影穹殿就等著變成破爛堆吧。', `MaleText_loc7`='Cuando el doctor vuelva, tu lamentable Cámara de las Sombras quedará arrasada.' WHERE `ID`=31106;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네르겔드는 바르굴이 생명을 불어 넣은 첫 번째 살덩이 거인 군대다. 진정한 공포는 이제부터 시작이다!', `MaleText_loc4`='尼尔盖德不过是第一个瓦古血肉巨人，我们会造出一支大军来的。到那时，你就会明白什么是真正的恐怖！', `MaleText_loc5`='奈傑德只是維酷強化的血肉巨人大軍中的第一個。你們準備嚇到屁滾尿流吧!', `MaleText_loc7`='Nergeld solo es el primer miembro de un nuevo ejército de gigantes de carne vargul. ¡Hasta ahora no has sabido lo que es el miedo!' WHERE `ID`=31107;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 거나 할 시간이 없다!', `MaleText_loc4`='别浪费我的时间！', `MaleText_loc5`='我沒時間浪費了!', `MaleText_loc7`='¡No tengo tiempo para esto!' WHERE `ID`=31108;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 늦었다, 하찮은 것.', `MaleText_loc4`='太晚了，小鬼。', `MaleText_loc5`='你太遲了，弱小的傢伙。', `MaleText_loc7`='Llegas demasiado tarde, enclenque.' WHERE `ID`=31109;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형제여, 너와 내가 정정당당하게 싸운다면 아직 네가 나를 능가할 수 있겠구나.', `MaleText_loc4`='在公平对决的情况下，你似乎有机会战胜我。', `MaleText_loc5`='看來你依舊可以在公平的決鬥中勝過我，弟弟。', `MaleText_loc7`='Parece que todavía puedes ganarme en una batalla justa, hermanito.' WHERE `ID`=31110;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네게는 안 됐다만... 우리 결투는 절대 정정당당하지 않다!', `MaleText_loc4`='不幸的是……这场战斗并不公平！', `MaleText_loc5`='但算你倒楣...這場決鬥一點也不公平!', `MaleText_loc7`='Por desgracia para ti... ¡esta pelea es de todo menos justa!' WHERE `ID`=31111;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 가장 강력했던 폭풍의 신전을 떠나게 된 걸 네 조그마한 친구에게 감사해야겠구나. 그 덕분에 주인님의 힘에 더 가깝게 싸우지 않느냐.', `MaleText_loc4`='这就要感谢你的小朋友了。你离开了风暴神殿，在那里你才能发挥出全部的力量。而现在，我们战斗的地方更靠近主人的力量。', `MaleText_loc5`='多謝你的小朋友，你離開了能讓你最強大的風暴神殿。而我卻很靠近我主人的力量泉源。', `MaleText_loc7`='Gracias a tu pequeño amigo, has abandonado el Templo de las Tormentas, donde eras más fuerte. En cambio, luchamos más cerca del poder de mi maestro.' WHERE `ID`=31112;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 친구! 날 여기서 나가게 해줘!', `MaleText_loc4`='救我出去，朋友！', `MaleText_loc5`='救我出去，朋友!', `MaleText_loc7`='¡Sácame de aquí, colega!', `FemaleText_loc1`='이봐, 친구! 날 여기서 나가게 해줘!', `FemaleText_loc4`='救我出去，朋友！', `FemaleText_loc5`='救我出去，朋友!', `FemaleText_loc7`='¡Sácame de aquí, colega!' WHERE `ID`=31113;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다. 하지만, 이 곤란한 상황을 완전히 벗어난 것은 아닙니다!', `MaleText_loc4`='谢谢你，朋友。但是我们还没有彻底摆脱危险！', `MaleText_loc5`='感謝你，朋友，但我們還沒有脫離險境呢!', `MaleText_loc7`='Gracias, colega, pero aún estamos en peligro.', `FemaleText_loc1`='감사해요. 하지만, 이 곤란한 상황을 완전히 벗어난 것은 아니에요!', `FemaleText_loc4`='谢谢你，朋友。但是我们还没有彻底摆脱危险！', `FemaleText_loc5`='感謝你，朋友，但我們還沒有脫離險境呢!', `FemaleText_loc7`='Gracias, colega, pero aún estamos en peligro.' WHERE `ID`=31114;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 빨리 나갑시다! 서두르십시오!', `MaleText_loc4`='我们快离开这儿吧！赶快！', `MaleText_loc5`='讓我們離開這兒吧!盡快!', `MaleText_loc7`='¡Salgamos de aquí! ¡Deprisa!', `FemaleText_loc1`='여기서 빨리 나가요! 어서요!', `FemaleText_loc4`='我们快离开这儿吧！赶快！', `FemaleText_loc5`='讓我們離開這兒吧!盡快!', `FemaleText_loc7`='¡Salgamos de aquí! ¡Deprisa!' WHERE `ID`=31115;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그녀의 이름을...', `MaleText_loc4`='直呼……', `MaleText_loc5`='說出...', `MaleText_loc7`='Pronunciar...' WHERE `ID`=31116;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='입에 담지 마라!!', `MaleText_loc4`='她的名讳！！', `MaleText_loc5`='她的名字!!', `MaleText_loc7`='¡Su nombre!' WHERE `ID`=31117;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여깁니다! 파괴된 역병 살포기 위에 있습니다! 도와주십시오!', `MaleText_loc4`='在这儿！我在被摧毁的天灾车上面！救命！', `MaleText_loc5`='在這兒!我在受損的瘟疫散佈者上頭!救我!', `MaleText_loc7`='¡Aquí arriba! ¡Estoy en lo alto del propagador de peste averiado! ¡Socorro!', `FemaleText_loc1`='여기에요! 파괴된 역병 살포기 위에 있어요! 도와주세요!', `FemaleText_loc4`='在这儿！我在被摧毁的天灾车上面！救命！', `FemaleText_loc5`='在這兒!我在受損的瘟疫散佈者上頭!救我!', `FemaleText_loc7`='¡Aquí arriba! ¡Estoy en lo alto del propagador de peste averiado! ¡Socorro!' WHERE `ID`=31118;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='박사님의 계획을 캐내러 왔구나! 죽음이나 캐내 가거라!', `MaleText_loc4`='你是冲着博士的计划来的！你只有死路一条！', `MaleText_loc5`='你想要博士的計畫書!你唯一能找到的只有死亡!', `MaleText_loc7`='¡Vienes a por los planos del doctor! ¡Solo encontrarás la muerte!' WHERE `ID`=31119;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일단 네르겔드가 되면, 썩어가는 살덩이는 생명을 얻는다.', `MaleText_loc4`='当你跳上尼尔盖德时，构造体上腐烂的血肉突然活了起来。', `MaleText_loc5`='當你跳進奈傑德時，傀儡的腐爛血肉也隨之復甦。', `MaleText_loc7`='Al saltar sobre Nergeld, la carne podrida del ensamblaje cobra vida.' WHERE `ID`=31120;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들은 엄청난 공격을 하려고 계획하고 있습니다! 폴드링 대영주님께 경고해야 합니다!', `MaleText_loc4`='他们正在策划一场大袭击！我们必须去警告大领主弗丁！', `MaleText_loc5`='他們正在計畫一場大規模攻擊!我們得警告大領主弗丁!', `MaleText_loc7`='¡Están planeando un ataque a gran escala! ¡Tenemos que avisar al alto señor Vadín!', `FemaleText_loc1`='저들은 엄청난 공격을 하려고 계획하고 있어요! 폴드링 대영주님께 경고해야 해요!', `FemaleText_loc4`='他们正在策划一场大袭击！我们必须去警告大领主弗丁！', `FemaleText_loc5`='他們正在計畫一場大規模攻擊!我們得警告大領主弗丁!', `FemaleText_loc7`='¡Están planeando un ataque a gran escala! ¡Tenemos que avisar al alto señor Vadín!' WHERE `ID`=31121;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좀 더 서두르십시오, 영웅이여! 우리는 은빛십자군 선봉기지로 돌아가서 공격이 임박했다고 경고해야 합니다!', `MaleText_loc4`='快一点，勇士！我们必须赶回银色前线基地，把进攻的事告诉他们！', `MaleText_loc5`='快一點，英雄!我們一定得回到銀白先鋒駐地，警告他們即將到來的攻擊!', `MaleText_loc7`='¡Más deprisa, héroe! ¡Tenemos que regresar a La Vanguardia Argenta y avisarles del inminente ataque!', `FemaleText_loc1`='좀 더 서두르세요, 영웅이여! 우리는 은빛십자군 선봉기지로 돌아가서 공격이 임박했다고 경고해야 해요!', `FemaleText_loc4`='快一点，勇士！我们必须赶回银色前线基地，把进攻的事告诉他们！', `FemaleText_loc5`='快一點，英雄!我們一定得回到銀白先鋒駐地，警告他們即將到來的攻擊!', `FemaleText_loc7`='¡Más deprisa, héroe! ¡Tenemos que regresar a La Vanguardia Argenta y avisarles del inminente ataque!' WHERE `ID`=31122;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적군이 수백 명은 있습니다! 어쩌면 수천 명일 수도 있습니다! 당장에라도 공격해올지 모릅니다! 확실합니다!', `MaleText_loc4`='他们有几百人！甚至可能有几千人！他们随时可能发动进攻！我敢肯定！', `MaleText_loc5`='他們有好幾百個!甚至可能有上千個!他們隨時都可能會發動攻擊!我很肯定!', `MaleText_loc7`='¡Hay cientos de ellos! ¡Quizá miles! ¡Atacarán en cualquier momento! ¡Estoy seguro!', `FemaleText_loc1`='적군이 수백 명은 있어요! 어쩌면 수천 명일 수도 있고요! 당장에라도 공격해올지 몰라요! 확실해요!', `FemaleText_loc4`='他们有几百人！甚至可能有几千人！他们随时可能发动进攻！我敢肯定！', `FemaleText_loc5`='他們有好幾百個!甚至可能有上千個!他們隨時都可能會發動攻擊!我很肯定!', `FemaleText_loc7`='¡Hay cientos de ellos! ¡Quizá miles! ¡Atacarán en cualquier momento! ¡Estoy seguro!' WHERE `ID`=31123;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 함께 와주시지 않았다면 전 분명히 죽은 목숨이었을 겁니다!', `MaleText_loc4`='如果你不来的话，我就死定了！', `MaleText_loc5`='要是沒有你來，我就死定了!', `MaleText_loc7`='¡Si no hubieras venido, habría muerto seguro!', `FemaleText_loc1`='당신이 함께 와주시지 않았다면 전 분명히 죽은 목숨이었을 거예요!', `FemaleText_loc4`='如果你不来的话，我就死定了！', `FemaleText_loc5`='要是沒有你來，我就死定了!', `FemaleText_loc7`='¡Si no hubieras venido, habría muerto seguro!' WHERE `ID`=31124;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리... 리치 왕을 보았습니다. 아주 잠깐이었지만, 여기에 왔었습니다... 그리고 모든 것이 너무나 차갑게 변해버렸습니다. 너무나, 너무나 차갑게...', `MaleText_loc4`='我……我看见巫妖王了。他很快就消失了，但是他确实来过这里……接着温度骤降，变得非常……非常寒冷。', `MaleText_loc5`='我...我想我看到巫妖王了。雖然只有一下下，但他就在那裡...然後就變得好冷，朋友。好冷好冷...', `MaleText_loc7`='Creo... creo que vi al Rey Exánime. Solo fue un momento, pero estaba aquí... Y se volvió tan frío, colega. Tan, tan frío...', `FemaleText_loc1`='리... 리치 왕을 보았어요. 아주 잠깐이었지만, 여기에 왔었죠... 그리고 모든 것이 너무나 차갑게 변해버렸어요. 너무나, 너무나 차갑게...', `FemaleText_loc4`='我……我看见巫妖王了。他很快就消失了，但是他确实来过这里……接着温度骤降，变得非常……非常寒冷。', `FemaleText_loc5`='我...我想我看到巫妖王了。雖然只有一下下，但他就在那裡...然後就變得好冷，朋友。好冷好冷...', `FemaleText_loc7`='Creo... creo que vi al Rey Exánime. Solo fue un momento, pero estaba aquí... Y se volvió tan frío, colega. Tan, tan frío...' WHERE `ID`=31125;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만!', `MaleText_loc4`='够了！', `MaleText_loc5`='夠了!', `MaleText_loc7`='¡BASTA!' WHERE `ID`=31126;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필멸의 존재여, 네 목숨 줄을 끊어버리지 않고 관대하게 보내주마. 어쨌든... 내가 왜 가장 쓸모 있는 하인을 없애버리겠느냐? 난 그 힐드니르 광산에서 몇 주간 널 기다렸다.', `MaleText_loc4`='凡人，我会考虑饶恕你的性命的。毕竟……我为什么要杀掉最得力的仆从啊？我在海德尼尔矿洞里等了你好几周呢。', `MaleText_loc5`='至於你的小命，凡人。我會很慷慨的。畢竟...為什麼我要摧毀我最有用的僕人?我在海迪尼爾礦坑中等了你好幾個禮拜。', `MaleText_loc7`='Respecto a tu vida, mortal, seré generoso. Después de todo... ¿por qué iba a destruir a mi más útil sirviente? Llevo semanas esperándote dentro de esa mina Hyldnir.' WHERE `ID`=31127;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하수인들아! 내 형제와 비룡을 새로운 보금자리로 모시거라. 저 비룡을 살아 있는 채로 데려가야 한다. 여왕을 써먹을 특별한 계획이 있으니 말이다.', `MaleText_loc4`='奴隶们！把我的兄弟和他的飞龙送去他们的新家吧。别伤了那头畜生的性命。我还有个针对她的特别计划呢。', `MaleText_loc5`='手下們!把我弟弟和他的龍送去他們的新家。別弄死那隻野獸。我對育母另有特別的計畫。', `MaleText_loc7`='¡Esbirros! Llevad a mi hermano y a su draco a sus nuevos aposentos. Aseguraos de que la bestia siga con vida. Tengo planes especiales para la madre de linaje.' WHERE `ID`=31128;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 잘 가거라, 형제여.', `MaleText_loc4`='……再见，我的兄弟。', `MaleText_loc5`='...再會了，兄弟。', `MaleText_loc7`='... adiós hermano.' WHERE `ID`=31129;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙습니다, 영웅이여.', `MaleText_loc4`='谢谢你，勇士。', `MaleText_loc5`='感謝你，英雄。', `MaleText_loc7`='Gracias por tu heroicidad.', `FemaleText_loc1`='고맙습니다, 영웅이여.', `FemaleText_loc4`='谢谢你，勇士。', `FemaleText_loc5`='感謝你，英雄。', `FemaleText_loc7`='Gracias por tu heroicidad.' WHERE `ID`=31130;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날아가실 수 있는 곳은 은빛십자군 선봉기지나 메아리 골짜기, 아니면 스컬지홀름 뿐입니다.', `MaleText_loc4`='你只能在银色前线基地、回音谷和天灾城飞翔。', `MaleText_loc5`='你只能在銀白先鋒駐地、回聲山谷和天譴岸地飛行。', `MaleText_loc7`='Solo puedes volar dentro de La Vanguardia Argenta, el Valle de los Ecos y la Ciudad de la Plaga.' WHERE `ID`=31131;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 산산조각이 납니다.', `MaleText_loc4`='%s碎裂开来。', `MaleText_loc5`='%s散落成碎片。', `MaleText_loc7`='%s se cae a pedazos.' WHERE `ID`=31132;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론 그 형상은 내가 아니었다. 네가 앞뒤를 재보고 다녔다면 과거의 내 환영을 봤을 게다. 하지만 네 녀석이 그 일과... 날 위해 잘 해내 주었으니 감사해야겠구나!', `MaleText_loc4`='这当然不是我的真实相貌。如果你不是那么卤莽的话，你早就看见我过去的幻影了。但是你毕竟帮助我渡过了难关……我必须谢谢你！', `MaleText_loc5`='當然，那個外型並不是我。如果你沒有那麼魯莽的話，你或許能看穿我的幻影。但你卻為我做了這麼多，為此...我要好好感謝你!', `MaleText_loc7`='La forma no era mía, por supuesto. Y si no hubieras sido tan temerario, habrías visto más allá de mi ilusión. Pero viniste a por mí, y por eso debo darte las gracias.' WHERE `ID`=31133;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 어떤 녀석이냐?! 가만두지 않을 테다. 네 녀석을 잡으러 가는 데 네르겔드를 파괴해야 한다고 해도 말이야!', `MaleText_loc4`='谁敢？！就算要牺牲尼尔盖德，我也会抓到你，将你的肉一片片地割下来！', `MaleText_loc5`='誰這麼大膽?!就算我得把奈傑德給毀了，我也要逮到你，把你的皮肉從骨頭上全剝下來!', `MaleText_loc7`='¿QUIÉN SE ATREVE? ¡VOY A DESPELLEJARTE AUNQUE TENGA QUE DESTRUIR A NERGELD PARA LLEGAR HASTA TI!' WHERE `ID`=31134;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와주십시오! 여기 거미줄로 싸여 있어서 움직일 수 없습니다!', `MaleText_loc4`='救命！我被网裹住了，动弹不得！', `MaleText_loc5`='幫幫我!我被困在網子裡動彈不得!', `MaleText_loc7`='¡SOCORRO! ¡Estoy cubierto de telarañas y no me puedo mover!', `FemaleText_loc1`='도와주세요! 여기 거미줄로 싸여 있어서 움직일 수 없어요!', `FemaleText_loc4`='救命！我被网裹住了，动弹不得！', `FemaleText_loc5`='幫幫我!我被困在網子裡動彈不得!', `FemaleText_loc7`='¡SOCORRO! ¡Estoy cubierta de telarañas y no me puedo mover!' WHERE `ID`=31135;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이쪽입니다! 아래쪽으로 말입니다! 도와주십시오!', `MaleText_loc4`='我在这儿！躺在地上！救命！', `MaleText_loc5`='在這兒!在地下!救救我!', `MaleText_loc7`='¡Aquí abajo! ¡En el suelo! ¡Ayuda!', `FemaleText_loc1`='이쪽이에요! 아래쪽이에요! 도와주세요!', `FemaleText_loc4`='我在这儿！躺在地上！救命！', `FemaleText_loc5`='在這兒!在地下!救救我!', `FemaleText_loc7`='¡Aquí abajo! ¡En el suelo! ¡Ayuda!' WHERE `ID`=31136;
