UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하세요! 리치 왕이 근처에 있어요!', `MaleText_loc4`='小心！巫妖王就在附近！', `MaleText_loc5`='小心!巫妖王就在附近!', `MaleText_loc7`='¡Cuidado! ¡El Rey Exánime está cerca!', `FemaleText_loc1`='조심하세요! 리치 왕이 근처에 있어요!', `FemaleText_loc4`='小心！巫妖王就在附近！', `FemaleText_loc5`='小心!巫妖王就在附近!', `FemaleText_loc7`='¡Cuidado! ¡El Rey Exánime está cerca!' WHERE `ID`=31139;
