UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠, 뭐지?', `MaleText_loc4`='嗯，那是什么？', `MaleText_loc5`='嘻，怎樣?', `MaleText_loc7`='¡Eh! ¿Qué es eso?' WHERE `ID`=31143;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='눈에 뭐가 들어갔군...', `MaleText_loc4`='雪花落到我的眼睛里了……', `MaleText_loc5`='只是有點雪片飄進我的眼睛，這裡...', `MaleText_loc7`='Tenía un poquito de nieve en el ojo, ahí...' WHERE `ID`=31144;
