UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 안녕하신가. 작은 $r 친구.', `MaleText_loc4`='哦，你好，小$r。', `MaleText_loc5`='喔，你好啊，小$r。', `MaleText_loc7`='Ah, hola, $gpequeño:pequeña; $r.' WHERE `ID`=31148;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 타운카가 아니군. 우리 전사들의 신성한 묘지에 무슨 일로 찾아왔는가?', `MaleText_loc4`='你不是牦牛人。你为什么闯入我族战士的埋骨圣地？', `MaleText_loc5`='你不是坦卡族人。你為什麼來到我們族中戰士的神聖墓地?', `MaleText_loc7`='No eres un taunka. ¿Por qué has venido al sagrado cementerio de nuestros guerreros?' WHERE `ID`=31149;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='휴식을 방해하게 되어 죄송합니다, 족장님. 다름 아니라 족장님의 형제가 위험에 처한 것 같습니다. 그에 대해 기억나는 게 있다면 알려주시겠습니까?', `MaleText_loc4`='很抱歉打扰到你，酋长。但是，你的兄弟的灵魂可能遇到了危险。你能把关于他的回忆告诉我吗？', `MaleText_loc5`='我很抱歉打擾了你的安眠，酋長，但你兄弟的靈魂可能正陷入危機。你能告訴我你還記得他什麼事情嗎?', `MaleText_loc7`='Siento interrumpir tu descanso, cabecilla, pero puede que el espíritu de tu hermano esté en peligro. ¿Puedes decirme que recuerdas de él?', `FemaleText_loc1`='휴식을 방해하게 되어 죄송합니다, 족장님. 다름 아니라 족장님의 형제가 위험에 처한 것 같습니다. 그에 대해 기억나는 게 있다면 알려주시겠습니까?', `FemaleText_loc4`='很抱歉打扰到你，酋长。但是，你的兄弟的灵魂可能遇到了危险。你能把关于他的回忆告诉我吗？', `FemaleText_loc5`='我很抱歉打擾了你的安眠，酋長，但你兄弟的靈魂可能正陷入危機。你能告訴我你還記得他什麼事情嗎?', `FemaleText_loc7`='Siento interrumpir tu descanso, cabecilla, pero puede que el espíritu de tu hermano esté en peligro. ¿Puedes decirme que recuerdas de él?' WHERE `ID`=31150;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나의 형제 스톰후프는 나보다 훨씬 위대한 전사였네. 내가 부족장이 되기 위한 훈련을 받는 동안 그는 더욱 중대한 임무를 준비했지.', `MaleText_loc4`='我的兄弟雷蹄，是一位比我更出色的战士。在我接受继任氏族酋长的训练时，他正在为一项重要的任务做准备。', `MaleText_loc5`='我的兄弟，風暴之蹄，是個遠比我更偉大的戰士。當我接受訓練已成為我們氏族的酋長時，他則為了更遠大的任務而準備。', `MaleText_loc7`='Mi hermano, Pezuña Tempestuosa, era mucho mejor guerrero que yo. Mientras yo estudiaba para ser cabecilla de nuestro clan, él se preparaba para una misión mucho mayor.' WHERE `ID`=31151;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런데 어째서 위험에 빠지게 된 거지? 그는 그저 부족의 골칫거리인 정령을 지배할 힘을 얻으려 한 것뿐이라네.', `MaleText_loc4`='他怎么会有危险呢？他只是想让我们获得力量，控制那些令我们难以安生的元素生物。', `MaleText_loc5`='他怎麼可能會有危險?他所要做的只不過是給我們力量，好對抗那些為難我們族人的元素生物。', `MaleText_loc7`='¿Cómo puede estar él en peligro? Lo único que quería era darnos poder sobre los elementos que hacen que la vida sea dura para nosotros aquí.' WHERE `ID`=31152;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그는 어떤 뿔피리를 찾으려 했던 것 같네. 오랜 기간 마을을 떠나 그 유물을 찾으러 다녔지.', `MaleText_loc4`='他要去找一件神器……一只号角。他离开了村子，踏上了寻找它的漫漫长途。', `MaleText_loc5`='我想他在尋找一個神器...一支號角。他離開村子進行了一場漫長的追尋。', `MaleText_loc7`='Buscaba un artefacto... un cuerno, creo. Dejó el pueblo para realizar un largo viaje en su busca.' WHERE `ID`=31153;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그가 뿔피리를 손에 얻자 무서운 적이 그를 추격하기 시작했는데... 기억이 나질 않는군... 그다음에... 무슨 일이 일어났는지 말이야.', `MaleText_loc4`='在他夺得号角之后，有个可怕的敌人追上了他……但是，我不记得……后来发生了什么。', `MaleText_loc5`='我知道一個可怕的敵人在他贏得號角之後糾纏著他，但我...我想不起來...後來...發生了什麼事。', `MaleText_loc7`='Sé que un temible enemigo le persiguió después de que consiguiera el cuerno, pero... no recuerdo qué pasó... después.' WHERE `ID`=31154;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마치 내 기억이 안갯속에 가려진 것 같다네. 그에게 무슨 일이 있었는지조차 생각나질 않아. 이것이 혹시 그가 위험에 처한 이유인가?', `MaleText_loc4`='我的记忆似乎被一层迷雾笼罩了。我甚至不记得我的兄弟后来出了什么事。这就是你所说的危险吗？', `MaleText_loc5`='或許我的記憶也籠罩在迷霧之中了。我甚至想不起來後來我兄弟怎麼了。這就是為什麼你說他陷入危險嗎?', `MaleText_loc7`='Es como si mis recuerdos estuvieran cubiertos de niebla. Ni siquiera puedo recordar qué le pasó a mi hermano. ¿Por esto dices que está en peligro?' WHERE `ID`=31155;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아마도 묘지에서 일어난 문제와 관련이 있는 게 틀림없네. 주위를 둘러보게, $n. 저들이 보이는가?', `MaleText_loc4`='坟墓在骚动，他们一定被卷进来了。看看你的四周，$n。你看见他们了吗？', `MaleText_loc5`='陵墓中充滿了騷動，這一定有所關連。看看你四周，$n。你看見它們了嗎?', `MaleText_loc7`='Las alteraciones en la tumba... ellos tienen que estar involucrados. Mira alrededor, $n. ¿Los ves?' WHERE `ID`=31156;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 잘못은 그들에게 있지만 나에겐 그를 막을 힘이 없다네. 툰카로 주민에게 경고해주겠나, 이방인이여? 그들의 선조와 과거가 위험에 처했다고 말이야.', `MaleText_loc4`='是的，情况不妙，但是我无力阻止他们。你能向唐卡洛营地发出警告吗，陌生人？告诉他们，历史和他们的祖先正在危险之中。', `MaleText_loc5`='是，它們全都犯下過錯，但我沒有力量阻止它們。你願意幫我警告坦卡羅的人民嗎，陌生人?告訴他們，他們的祖先與過去陷入了危機?', `MaleText_loc7`='Sí, es culpa suya, pero no tengo poder para detenerlos. ¿Avisarás a la gente de Tunka''lo de que su pasado y sus ancestros están en peligro, $gforastero:forastera;?' WHERE `ID`=31157;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 둥지 위로 내려앉으며 큰 소리로 울부짖습니다.', `MaleText_loc4`='%s落到巢中，发出一声怒吼。', `MaleText_loc5`='當%s降到巢穴時，發出一聲怒吼咆哮。', `MaleText_loc7`='%s deja escapar un bramido mientras baja del nido.' WHERE `ID`=31158;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아래를 조심하게!', `MaleText_loc4`='小心下面！', `MaleText_loc5`='注意底下!', `MaleText_loc7`='¡Cuidado! ¡Abajo!' WHERE `ID`=31159;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정하거라, 아가야! 네 예전 주인을 알아보지 못하겠느냐?', `MaleText_loc4`='放松点！不认识你的旧主子了吗？', `MaleText_loc5`='放鬆點，女孩!你不認得你的老主人了嗎?', `MaleText_loc7`='¡Tranquila, chica! ¿No reconoces a tu antiguo maestro?' WHERE `ID`=31160;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭풍의 신전에서 다시 보자꾸나. 베라누스를 다시 길들여야 할 것 같구나.', `MaleText_loc4`='我会在风暴神殿等你。看来我得再降服她一次了。', `MaleText_loc5`='我會在風暴神殿和你碰面。看來我得重新馴服她一次。', `MaleText_loc7`='Te veré en el Templo de las Tormentas. Parece que voy a tener que volver a domarla.' WHERE `ID`=31161;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엔진이 고장 났습니다! 자크의 비행기를 K3로 되돌려야 합니다!', `MaleText_loc4`='引擎发动了！扎克的飞行器即将返回K3！', `MaleText_loc5`='引擎爆炸了!把札克的飛行器飛回K3!', `MaleText_loc7`='¡El motor ha explotado! ¡Lleva la máquina voladora de Zak de vuelta a K3!' WHERE `ID`=31162;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저들을 봐라... 저들이 신경 쓰는 거라곤 서로 능가하는 것뿐이야.', `FemaleText_loc4`='看看他们……他们一心只想超过别人。', `FemaleText_loc5`='看看他們...他們只在乎勝過彼此。', `FemaleText_loc7`='Míralos... todo lo que les importa es ser mejor que el otro.' WHERE `ID`=31163;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제안에 대해서 말해 보시죠.', `MaleText_loc4`='让我听听你的提议。', `MaleText_loc5`='告訴我關於提案的事情。', `MaleText_loc7`='Háblame acerca de esta propuesta.', `FemaleText_loc1`='제안에 대해서 말해 보시죠.', `FemaleText_loc4`='让我听听你的提议。', `FemaleText_loc5`='告訴我關於提案的事情。', `FemaleText_loc7`='Háblame acerca de esta propuesta.' WHERE `ID`=31164;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='알다시피 토림은 저자들과는 다르다. 그분은 신과 같은 존재에 걸맞다.$B$B그는 창조주의 거처와 울두아르의 수호자로서 티탄을 위해 일했었다. 토림의 아내인 시프가 그의 형제에게 비겁하게 살해당하기 전까지 말이지.', `FemaleText_loc4`='你看，托里姆和这些鹰身人不同。他是近乎神的存在。$B$B他为泰坦们守护着奥杜尔和造物者圣台。$B$B直到他的妻子西芙被他的兄弟可鄙地杀害了。', `FemaleText_loc5`='你知道的，索林姆跟這群殘忍貪婪的潑婦不一樣。他是個像神一般的尊貴生物。$B$B他替泰坦服務，擔任奧杜亞和造物者殿堂的守護者。$B$B直到他的妻子希芙被他的哥哥卑鄙地殺害。', `FemaleText_loc7`='Verás, Thorim no es como esas arpías. Es un ser digno de estatura parecida a la de los dioses.$B$BSirvió a los titanes como guardián de Ulduar y el Templo de los Creadores.$B$BEso fue hasta que su hermano asesinó a su mujer, Sif, en un acto de cobardía.' WHERE `ID`=31165;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 후엔 무슨 일이 벌어졌습니까?', `MaleText_loc4`='那后来呢？', `MaleText_loc5`='之後發生了什麼事?', `MaleText_loc7`='¿Qué ocurrió entonces?', `FemaleText_loc1`='그 후엔 무슨 일이 벌어졌나요?', `FemaleText_loc4`='那后来呢？', `FemaleText_loc5`='之後發生了什麼事?', `FemaleText_loc7`='¿Qué ocurrió entonces?' WHERE `ID`=31166;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='토림은 자제력을 잃었다. 그는 가장 사랑하던 동료인 서리 거인들을 거세게 공격했지.$B$B오늘날, 이 땅이 호디르의 후예들과 힐드니르 사이의 전쟁으로 분열된 이유이다. 그리고 토림이 폭풍의 신전에 자신을 유배한 이유지.', `FemaleText_loc4`='托里姆失去了理智。他将矛头指向了他的亲密战友，冰霜巨人。$B$B这导致了海德尼尔和霍迪尔之子至今仍在这片土地上互相攻伐……托里姆也因此离开了风暴神殿。', `FemaleText_loc5`='索林姆失去了控制。他猛烈地攻擊他最堅強的盟友，冰霜巨人。$B$B這也是為什麼那天，這塊土地被海迪尼爾與霍迪爾之子間的戰爭徹底撕裂...也因此索林姆將自己放逐到風暴神殿。', `FemaleText_loc7`='Thorim se volvió loco. Arremetió contra sus más amados aliados, los gigantes de escarcha.$B$BEsa es una de las razones por las que hoy, esta tierra está dividida por la guerra entre los Hyldnir y Los Hijos de Hodir... y por la que Thorim se ha exiliado al Templo de las Tormentas.' WHERE `ID`=31167;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 전쟁을 끝내고자 제가 힐드스미트에 참여하길 원하는 겁니까?', `MaleText_loc4`='你想让我参加海德比武会并结束战争吗？', `MaleText_loc5`='你要我參與海茲競技好結束這場戰爭?', `MaleText_loc7`='¿Quieres que tome parte en el Encuentro Hyldnir para acabar con la guerra?', `FemaleText_loc1`='이 전쟁을 끝내고자 제가 힐드스미트에 참여하길 원하는 건가요?', `FemaleText_loc4`='你想让我参加海德比武会并结束战争吗？', `FemaleText_loc5`='你要我參與海茲競技好結束這場戰爭?', `FemaleText_loc7`='¿Quieres que tome parte en el Encuentro Hyldnir para acabar con la guerra?' WHERE `ID`=31168;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내가 걱정하는 게 뭐냐고? 저 여자 늑대들과 서리 거인이 매일 서로를 죽인다면 어떨까?$B$B아니, 아니다... 난 토림께서 망연자실한 마음에서 벗어나와 울두아르를 다시 손에 넣는 일에 그의 동료들 모두를 규합해 주셨으면 한다.$B$B그분께서 이번 일을 해내지 못하시면 세상은 갈기갈기 찢어질 것이다.$B$B물론 이 일을 돕는다면 합당한 보상을 하겠다.', `FemaleText_loc4`='就算这些母狼和冰霜巨人天天对砍，那也不关我的事。$B$B不，不……我是想让托里姆振作起来，召集起所有的盟友夺回奥杜尔。$B$B如果他失败了，这个世界就会破碎的！$B$B当然了，我会支付给你足够的报酬的。', `FemaleText_loc5`='為什麼我要在意那些母狼和冰霜巨人每天殺得你死我活?$B$B不，不...我要索林姆不再恍惚度日，召集他的所有盟友重新奪回奧杜亞。$B$B如果他失敗了，這個世界將會就此分裂!$B$B當然，我也會適當地獎勵你。', `FemaleText_loc7`='¿Y a mí qué me importa si estas lobas y los gigantes de escarcha se matan entre ellos cada día?$B$BNo, no... Quiero que Thorim salga de su estupor y reúna a sus aliados para retomar Ulduar.$B$B¡El mundo se partirá en dos si fracasa!$B$BY por supuesto, te recompensaré apropiadamente.' WHERE `ID`=31169;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋습니다. 대전에 참여하지요.', `MaleText_loc4`='很好。我愿意参加这个比赛。', `MaleText_loc5`='很好。我要參與這場競爭。', `MaleText_loc7`='Muy bien. Tomaré parte en esta competición.', `FemaleText_loc1`='좋습니다. 대전에 참여하지요.', `FemaleText_loc4`='很好。我愿意参加这个比赛。', `FemaleText_loc5`='很好。我要參與這場競爭。', `FemaleText_loc7`='Muy bien. Tomaré parte en esta competición.' WHERE `ID`=31170;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가르침의 망치가 반응합니다. 이것은 스톰후프의 시대에서 온 것이 확실합니다.', `MaleText_loc4`='知识之锤有反应。这件古器肯定来自雷蹄的时代。', `MaleText_loc5`='博識之錘有反映了。這一定是來自風暴之蹄的時間。', `MaleText_loc7`='El martillo de conocimiento está reaccionando. Esto debe ser de la época de Pezuña Tempestuosa.', `FemaleText_loc1`='가르침의 망치가 반응합니다. 이것은 스톰후프의 시대에서 온 것이 확실합니다.', `FemaleText_loc4`='知识之锤有反应。这件古器肯定来自雷蹄的时代。', `FemaleText_loc5`='博識之錘有反映了。這一定是來自風暴之蹄的時間。', `FemaleText_loc7`='El martillo de conocimiento está reaccionando. Esto debe ser de la época de Pezuña Tempestuosa.' WHERE `ID`=31171;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가르침의 망치가 반응하지 않습니다. 이것은 스톰후프의 시대에서 온 것이 아닙니다.', `MaleText_loc4`='知识之锤没有反应。这件古器不属于雷蹄的时代。', `MaleText_loc5`='博識之錘保持沉默。這一定不是來自風暴之蹄的時間。', `MaleText_loc7`='El martillo de conocimiento está callado. Esto no es de la época de Pezuña Tempestuosa.', `FemaleText_loc1`='가르침의 망치가 반응하지 않습니다. 이것은 스톰후프의 시대에서 온 것이 아닙니다.', `FemaleText_loc4`='知识之锤没有反应。这件古器不属于雷蹄的时代。', `FemaleText_loc5`='博識之錘保持沉默。這一定不是來自風暴之蹄的時間。', `FemaleText_loc7`='El martillo de conocimiento está callado. Esto no es de la época de Pezuña Tempestuosa.' WHERE `ID`=31172;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 다시 일어날 것이며, 그때 모든 것을 복수하리라!', `MaleText_loc4`='我会东山再起的，到时候我会报仇的！', `MaleText_loc5`='我會再次復甦，到時候我一定會復仇!', `MaleText_loc7`='¡VOLVERÉ A LEVANTARME Y, CUANDO LO HAGA, ME VENGARÉ!' WHERE `ID`=31173;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 그냥 수치심에 빠져 있게 두시오, $r님.', `MaleText_loc4`='让我独自反省吧，$r。', `MaleText_loc5`='讓我留在我的恥辱中，$r。', `MaleText_loc7`='Déjame con mi vergüenza, $r.' WHERE `ID`=31174;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='남자들... 있어도 살 수 없고, 없어도 살 수 없죠. 음, 당신은 할 수 있겠네요... 하지만 정말 지루하답니다.', `FemaleText_loc4`='男人——很难与他们相处，但是又离不开他们。好吧，也不是离不了……不过那样真的很无聊。', `FemaleText_loc5`='人 -- 沒辦法不靠著它們活下去，沒辦法離開它們。嗯，你可以...但那真的很無聊。', `FemaleText_loc7`='Hombres... no puedes vivir con ellos y no puedes vivir sin ellos. Bueno, sí que puedes... pero es muy aburrido.' WHERE `ID`=31175;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 광산은 무시무시한 곳이다. 여기서 오래 있을 계획이 아니라 다행이지.', `FemaleText_loc4`='这些矿洞真是太可怕了。幸好我不打算在这里待很长时间。', `FemaleText_loc5`='這些礦坑是個令人害怕的地方。幸運的是，我不打算久留。', `FemaleText_loc7`='Estas minas son un lugar terrorífico. Por suerte, no tengo intención de quedarme mucho tiempo.' WHERE `ID`=31176;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='곰은 아름다운 생물이다. 우리와 마찬가지로 전투에서 거칠고 강하며 사나운 모습을 보여주지.', `FemaleText_loc4`='熊是美丽的生物。野性、强壮、凶猛……就像我们一样。', `FemaleText_loc5`='熊是美麗的生物。狂野、強壯而在戰鬥中十分勇猛...跟我們很像，姊妹。', `FemaleText_loc7`='Los osos son criaturas hermosas. Salvajes, fuertes y feroces en la batalla... muy parecidos a nosotras, hermana.' WHERE `ID`=31177;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미안해, 친구. 지금은 부품이 다 떨어졌어.', `MaleText_loc4`='对不起，朋友。我们手头的零件好象都用完了。', `MaleText_loc5`='抱歉，朋友。我怕我們已經把所有可用的零件給用光了。', `MaleText_loc7`='Lo siento, colega. Me temo que hemos usado todas las piezas de las que podíamos prescindir por el momento.', `FemaleText_loc1`='미안해요, 친구. 지금은 부품이 다 떨어졌어요.', `FemaleText_loc4`='对不起，朋友。我们手头的零件好象都用完了。', `FemaleText_loc5`='抱歉，朋友。我怕我們已經把所有可用的零件給用光了。', `FemaleText_loc7`='Lo siento, colega. Me temo que hemos usado todas las piezas de las que podíamos prescindir por el momento.' WHERE `ID`=31178;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 선택받은 자다!', `MaleText_loc4`='我是被主人选中的！', `MaleText_loc5`='我被選上了!', `MaleText_loc7`='¡He sido elegido!', `FemaleText_loc1`='나는 선택받은 자다!', `FemaleText_loc4`='我是被主人选中的！', `FemaleText_loc5`='我被選上了!', `FemaleText_loc7`='¡He sido elegida!' WHERE `ID`=31179;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어리석기는! 네놈은 절대로 나를 이길 수 없다!', `MaleText_loc4`='蠢货！你赢不了我的！', `MaleText_loc5`='蠢貨!你無法打敗我的!', `MaleText_loc7`='¡Insensato! ¡Jamás me derrotarás!' WHERE `ID`=31180;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈이 우리에게 자연 격노의 뿔피리를 사용하도록 놔두지 않겠다! 죽어라, 애송이!', `MaleText_loc4`='我不会让你用元素愤怒号角来对付我们的！去死吧，懦夫！', `MaleText_loc5`='我不會讓你拿元素之怒號角對付我們的!死吧，弱者!', `MaleText_loc7`='¡Jamás permitiré que uses el Cuerno de Furia Elemental contra nosotros! ¡Muere, debilucho!' WHERE `ID`=31181;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영주님, 흐뢰가르 조교가 전사 준비가 끝났다는 소식을 전합니다. 전사들은 외곽 절벽 위에서 명령을 기다리며 훈련을 합니다.', `MaleText_loc4`='大人，教官霍加尔禀告说战士们都准备好了。他们正在外面的平台上等候您的命令。', `MaleText_loc5`='大人，講師賀洛迦傳令說您的戰士們準備好了。他們在岩架上爭吵著等您的指令。', `MaleText_loc7`='Mi señor, el instructor Hroegar ha informado de que tus guerreros están preparados. Esperan tus órdenes entrenando en el saliente a las afueras.' WHERE `ID`=31182;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 뿔! 그놈이 약해졌을 때 그 뿔을 사용하시오!', `MaleText_loc4`='号角！趁它进入虚弱状态吹响号角！', `MaleText_loc5`='號角!趁他虛弱的時候使用號角!', `MaleText_loc7`='¡El cuerno! ¡Usa el cuerno mientras está debilitado!' WHERE `ID`=31183;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강력한 영주 우프랑 님, 나쁜 소식을 가져 왔습니다. 동쪽 산 위에 있는 어둠의 무기고가 무너졌답니다.', `MaleText_loc4`='强大的乌弗朗领主，有个坏消息要告诉你。东边的暗影拱顶沦陷了。', `MaleText_loc5`='『強者』烏弗蘭族長，我帶來壞消息。飄浮在山上的暗影穹殿在往東邊的路上墜毀了。', `MaleText_loc7`='Señor feudal Ufrang el Poderoso, traigo malas noticias. La Cámara de las Sombras de la montaña del este ha caído.' WHERE `ID`=31184;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우프랑 영주님, 영주님의 전사들에게 결투를 받아들이라고 졸라대는 이방인들이 절벽 위에 있습니다. 브리쿨은 아닙니다.', `MaleText_loc4`='乌弗朗领主，平台上来了一些陌生人，要求与您的战士进行公平决斗。他们都不是维库人。', `MaleText_loc5`='烏弗蘭大人，有些陌生人在岩架上與您的戰士請求榮譽決鬥。他們不是維酷人。', `MaleText_loc7`='Señor Ufrang, hay forasteros en el saliente pidiendo a tus guerreros que se enfrenten a ellos en duelo. No son vrukuls.' WHERE `ID`=31185;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영주님, 이 드레나이는 어둠의 무기고에서 온 죽음의 기사 파견단 한 부대와 함께 잡혔습니다. 그들은 칠흑의 기사단이라고 합니다!', `MaleText_loc4`='大人，这个德莱尼人是和一整队来自暗影拱顶的死亡骑士一起被抓的。他们来自黑锋骑士团！', `MaleText_loc5`='大人，這個德萊尼是被暗影穹殿來的一隊死亡騎士抓住的。他們是黯刃騎士團!', `MaleText_loc7`='Mi señor, hemos atrapado a este draenei junto a un contingente completo de caballeros de la Muerte de La Cámara de las Sombras. ¡Son Caballeros de la Espada de Ébano!' WHERE `ID`=31186;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영주님, 다른 영주들이 저희를 공격하려고 군대를 준비한다는 보고가 있습니다. 저희도 빨리 손을 써야 합니다.', `MaleText_loc4`='大人，有消息说，其他领主准备发兵进攻我们。我们必须赶快行动了。', `MaleText_loc5`='閣下，有報告傳來其他的族長也正準備軍隊反攻我們。我們的動作得快一點了。', `MaleText_loc7`='Milord, han llegado informes de que otros señores feudales están preparando sus ejércitos para atacarnos. Debemos actuar deprisa.' WHERE `ID`=31187;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영주님, 갑작스러운 소식을 전해 드립니다. 영주님의 용사인 베소드가 발할라스 투기장에서 패했다고 합니다. 베소드는 바르굴이 되어 지하 전당으로 추방되었습니다.', `MaleText_loc4`='领主大人，我带来了最终的消息。您的勇士贝索德，已经在瓦哈拉斯阵亡了。作为一名瓦古，他已经被放逐到地下大厅去了。', `MaleText_loc5`='我的族長，我帶來不合時宜的消息。你的勇士，貝索德在英靈殿的競技場中落敗了。身為一名瓦苟，他已經被流放到地下大廳了。', `MaleText_loc7`='Señor feudal, traigo malas noticias. Tu campeón, Bethod, ha caído en el anillo de Valhalas. Como vargul, ha sido exiliado a Las Cámaras Subterráneas.' WHERE `ID`=31188;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흐뢰가르에게 가서 내가 공격 명령을 내리면 내 군대를 이끌라고 전하라.', `MaleText_loc4`='告诉霍加尔，当我发出进攻的命令时，他要充当我的先锋。', `MaleText_loc5`='告訴賀洛迦，當我下令時，我要他當軍隊的前鋒。', `MaleText_loc7`='Dile a Hroegar que estará en la carreta con mis tropas cuando dé la orden de atacar.' WHERE `ID`=31189;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='누가 저를 찾으셨습니까...?', `FemaleText_loc4`='谁在叫我……？', `FemaleText_loc5`='是誰找我...?', `FemaleText_loc7`='¿Me ha llamado alguien...?' WHERE `ID`=31190;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러면 리치 왕께 전령을 보내라. 우리 군대는 명령만 내리시면 바로 공격할 준비가 되었다고.', `MaleText_loc4`='那你必须派人给巫妖王送个消息。就说我的军队已经整装待发，就等他一声令下了。', `MaleText_loc5`='那你一定要送信給巫妖王。軍隊已經待命，在等他的進攻指令。', `MaleText_loc7`='Entonces debes enviar un mensajero al Rey Exánime. Que mis tropas estén preparadas para atacar a su señal.' WHERE `ID`=31191;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들끼리 싸우게 하라. 그들이 더 열등한 종족에 무릎을 꿇는다면, 그 또한 운명이며 그들이 가치 없다는 증거이다.', `MaleText_loc4`='让他们打吧。如果他们败给低等种族，那也是注定的，说明他们毫无价值。', `MaleText_loc5`='讓他們戰鬥吧。要是他們輸給那些次等種族，那也只證明了他們毫無用處。', `MaleText_loc7`='Deja que luchen. Si caen ante una de las razas inferiores, es que estaba predestinado y no son dignos.' WHERE `ID`=31192;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그놈을 여기에 묶어 두어라. 상황을 봐서 내가 처리하마. 다른 놈들은... 도망갈 꿈도 못 꾸게 하라!', `MaleText_loc4`='把他锁在那里。等我有空的时候自然会去处理他的。至于其他人……别让他们跑了！', `MaleText_loc5`='就讓他被綁在那裡吧。我會花時間好好對待他的。至於其他人...確保他們逃不出去!', `MaleText_loc7`='Dejadle ahí encadenado. Me encargaré de él a su debido tiempo. En cuanto a los demás... ¡Aseguraos de que no escapen!' WHERE `ID`=31193;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇다면, 우리가 얼마나 친절한지 보여주자꾸나. 저들이 무얼 하려는지는 몰라도, 그 일이 일어나기 전에 무엇인지 확실히 알아내라. 그리고서 누가 먼저 공격을 감행하는지 두고 보자!', `MaleText_loc4`='那就把我们的人都召集起来。一定要保证我们能在他们行动前得到消息。我倒要看看到底是谁先发动进攻！', `MaleText_loc5`='把我們能用的資源都用上。看看他們到底在搞什麼，我們一定要在發生前就明瞭情況。然後我們就可以先出擊致勝!', `MaleText_loc7`='Pidamos algunos favores, entonces. Asegúrate de que nos enteramos de lo que traman antes de que ocurra. ¡Veremos quién ataca primero!' WHERE `ID`=31194;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 그 뿔피리는 내 것이다!', `MaleText_loc4`='不！那个号角是我的！', `MaleText_loc5`='不!號角是我的!', `MaleText_loc7`='¡No! ¡Ese cuerno es MÍO!' WHERE `ID`=31195;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='베소드는 위대한 전사였지만, 확실히 부족했던 것 같구나. 새로운 용사를 찾아 와라. 이런 불명예를 참고 있을 수는 없다!', `MaleText_loc4`='贝索德是个伟大的战士，但显然他还不够强大。为我找一个新勇士吧。我们不能忍受这种耻辱！', `MaleText_loc5`='貝索德曾經是一名強大的戰士，但顯然還不夠強大。幫我找一位新的勇士。我們現在不能承受這種恥辱!', `MaleText_loc7`='Bethod era una gran guerrero, pero parece que no lo suficiente. Búscame un nuevo campeón. ¡No podemos permitirnos una deshonra ahora!' WHERE `ID`=31196;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈이 스컬지를 습격하는 것도 이것이 마지막이 되리라!', `MaleText_loc4`='这将是你最后一次和天灾军团作对了！', `MaleText_loc5`='這是你最後一次對天譴軍進攻了!', `MaleText_loc7`='¡Esta será tu última incursión contra la Plaga!' WHERE `ID`=31197;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일어나라!', `MaleText_loc4`='起来吧！', `MaleText_loc5`='起來吧!', `MaleText_loc7`='¡LEVÁNTATE!' WHERE `ID`=31198;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 쓰러지면서 그의 발코니 바닥에 설치된 제단에서 희미하게 빛이 나기 시작합니다.', `MaleText_loc4`='当%s倒下时，平台上的祭坛开始发出微弱的光芒。', `MaleText_loc5`='當%s倒下時，陽台地板上的祭壇開始發出微弱的光芒。', `MaleText_loc7`='Cuando %s cae, el altar situado en el suelo de su balcón comienza a brillar débilmente.' WHERE `ID`=31199;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살아있는 것들은 모두 없애라!', `MaleText_loc4`='去杀死那些活人，奴隶们！', `MaleText_loc5`='毀掉所有活物，爪牙們!', `MaleText_loc7`='¡Destruyan a los vivos, lacayos!' WHERE `ID`=31200;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕, 안녕하신가!', `MaleText_loc4`='喂，喂！', `MaleText_loc5`='嗨，哈囉!', `MaleText_loc7`='¡Hola, hola!' WHERE `ID`=31201;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, 멋진 분. 같이 일하게 되어 좋군요!', `FemaleText_loc4`='你好，伙计——很高兴有你陪在我身边！', `FemaleText_loc5`='哈囉，小甜心 - 很高興有你的陪伴!', `FemaleText_loc7`='Hola, encanto. ¡Me alegra tener compañía!' WHERE `ID`=31202;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, 멋진 분. 같이 일하게 되어 좋군요!', `FemaleText_loc4`='你好，伙计——很高兴有你陪在我身边！', `FemaleText_loc5`='哈囉，小甜心 - 很高興有你的陪伴!', `FemaleText_loc7`='Hola, encanto. ¡Me alegra tener compañía!' WHERE `ID`=31203;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='만나서 반갑습니다, $c|1이여;여;.', `MaleText_loc4`='很高兴见到你，$c。', `MaleText_loc5`='很高興見到你，$c。', `MaleText_loc7`='Encantado de conocerte, $c.' WHERE `ID`=31204;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='산들은 역사의 발자취로 가득하다네... $c|1이여;여;, 멈춰서 그 발자취를 즐기는 걸 잊지 말게.', `MaleText_loc4`='这片山脉的历史非常悠久……你要随时停下脚步来倾听，$c。', `MaleText_loc5`='這些山脈富含著歷史...別忘了停下腳步，多看看，$c。', `MaleText_loc7`='Las montañas tienen mucha historia... No olvides pararte a aprenderla, $c.' WHERE `ID`=31205;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='7500의 명예 점수와 150의 투기장 점수를 얻었습니다.', `MaleText_loc4`='你获得了7500点荣誉和150点竞技场点数。', `MaleText_loc5`='你獲得7500點榮譽與150點競技場點數。', `MaleText_loc7`='Recibes 7500 puntos de honor y 150 puntos de arena.' WHERE `ID`=31206;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<서릿결 정찰병이 숨을 거둔 것 같습니다.>', `MaleText_loc4`='<霜脉斥候咽下了最后一口气。>', `MaleText_loc5`='<霜誕斥候看來剛剛嚥下了他最後一口氣。>', `MaleText_loc7`='<El explorador Natoescarcha parece haber agotado su último aliento.>' WHERE `ID`=31207;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용의 안식처에 있는 청동 용제단에서 이 원시비룡을 발견했습니다. 단번에 일족임을 알아챘습니다. 수세기 전 같은 혈통이었음을 말입니다.$B$B제 사과를 받아 주십시오, $c님. 형편상 이런 모습을 취하고 있으니 말입니다. 전 청동용군단의 페넘브리우스라고 합니다. 유한한 존재의 모습을 하고 있으면 필멸의 존재들과 함께 살면서 의사소통하기가 훨씬 쉽기 때문이지요.$B$B자, 그럼 무엇을 도와드릴까요?', `MaleText_loc4`='我们在龙骨荒野的青铜巨龙圣地发现了这些始祖幼龙。我们立即意识到这是我们的同胞——他们是我们的远古血亲。$B$B很抱歉，$c。我把你说糊涂了吧。我是青铜巨龙圣地的本诺比奥斯。为了方便行事，我变化成了现在的形态。用凡人的形态可以更好地和凡人进行交流，共同生活。$B$B我能帮你什么忙吗？', `MaleText_loc5`='我們發現那些在龍骨荒野的青銅龍殿的元龍。我們知道他們曾是我們的族類 - 留著我們遠古的血液。$B$B我向你致歉，$c。你或許有些迷惑。我是青銅龍軍團的潘農布理斯。我為了方便活動而使用目前的外型。使用凡人的外型比較容易在凡人之中生活和溝通。$B$B有什麼我能幫忙的嗎?', `MaleText_loc7`='Hemos encontrado estos protodracos en el Santuario de Dragones Bronce, en el Cementerio de Dragones. Desde el principio supimos que eran de nuestro linaje, nuestra sangre en el pasado.$B$BDiscúlpame, $c. supongo que estás $gconfuso:confusa;. Soy Penumbrius, del Vuelo Bronce. He adoptado esta forma por conveniencia. Es mucho más fácil convivir y comunicarse con los mortales cuando tienes aspecto de mortal.$B$B¿Cómo puedo ayudarte?' WHERE `ID`=31208;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='베소드의 검이라고?!! 아주 잘했다, $r. 네 도전을 받아들이겠노라. 그전에 먼저, 내 용사와 싸워 이겨야 한다. 볼구르! 와서 이 벌레를 뭉개버려라!', `MaleText_loc4`='贝索德的剑？！！太好了，$r，我接受你的挑战。但首先，你必须打败我的勇士们。沃尔格！给我碾碎这只爬虫！', `MaleText_loc5`='貝索德之劍?!!太棒了，$r，我接受你的挑戰。但首先你得擊敗我最強的勇士。沃加爾!碾碎這個小蟲!', `MaleText_loc7`='¿La espada de Bethod? Muy bien, $r, acepto tu desafío. Pero primero, debes derrotar a mis campeones. ¡Volgur! Aplasta a este insecto.' WHERE `ID`=31209;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='첫 번째 용사가 쓰러질 때 영주가 침을 뱉습니다.', `MaleText_loc4`='当第一个勇士倒下时，领主吐了口唾沫。', `MaleText_loc5`='在他第一個勇士倒下時，族長吐了一口口水。', `MaleText_loc7`='El señor feudal escupe cuando cae el primero de sus campeones.' WHERE `ID`=31210;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='브리타, 이 빈약한 $c|1을;를; 벌집으로 만들어 줘라!', `MaleText_loc4`='布莉塔，去把这个卑微的$c打成筛子！', `MaleText_loc5`='布莉塔，把這弱小的$c做成一塊針墊!', `MaleText_loc7`='¡Brita! ¡Haz un acerico de $geste:esta:c; endeble $c!' WHERE `ID`=31211;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 용사들은 꺾었는지도 모르겠다. 그러나 나는 완전히 다르다.', `MaleText_loc4`='你或许可以打败我的勇士们，$c。但我和他们是完全不同的。', `MaleText_loc5`='你或許擊敗了我的勇士，$c。但我可是跟他們完全不一樣。', `MaleText_loc7`='Puede que hayas derrotado a mis campeones, $c. Pero yo soy algo totalmente distinto.' WHERE `ID`=31212;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빨리 죽게 해달라고 빌기나 해라.', `MaleText_loc4`='赶快向你们的诸神祈祷，企求速死吧。', `MaleText_loc5`='向你的神祇祈禱你能夠死得痛快一點吧。', `MaleText_loc7`='Reza a tus dioses para que te proporcionen una muerte rápida.' WHERE `ID`=31213;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요, $n 님! 오늘은 무슨 일을 도와드릴까요?', `MaleText_loc4`='你好，$n！今天你想要点什么？', `MaleText_loc5`='你好，$n!有什麼我能幫忙的嗎?', `MaleText_loc7`='¡Hola, $n! ¿Cómo puedo ayudarte hoy?', `FemaleText_loc1`='안녕하세요, $n 님! 오늘은 무슨 일을 도와드릴까요?', `FemaleText_loc4`='你好，$n！今天你想要点什么？', `FemaleText_loc5`='你好，$n!有什麼我能幫忙的嗎?', `FemaleText_loc7`='¡Hola, $n! ¿Cómo puedo ayudarte hoy?' WHERE `ID`=31214;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='일스카르 영주여, 그대는 명예로운 전투에 도전했지만 실패했도다.', `FemaleText_loc4`='伊尔斯卡领主，你接受了公平决斗的挑战，并且输了。', `FemaleText_loc5`='伊爾斯卡族長，你在光榮的戰鬥中受到挑戰並且落敗。', `FemaleText_loc7`='Señor feudal Maleskara, te han retado a un duelo honorable y has fracasado.' WHERE `ID`=31215;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그에 미치지 못하였으므로 이에 따라 판결하노라. 이제 일어나라, 저주받은 영주 일스카르여!', `FemaleText_loc4`='你显然还有所欠缺，并将受到制裁。站起来吧，被诅咒的伊尔斯卡领主！', `FemaleText_loc5`='你已被懸賞並且獲得適當的判決。現在起來，被詛咒的伊爾斯卡族長!', `FemaleText_loc7`='No has dado la talla y se te ha juzgado de forma acorde. ¡Ahora levántate, señor feudal Maleskara el Maldito!' WHERE `ID`=31216;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말하라, $c|1이여;여;.', `MaleText_loc4`='说吧，$c。', `MaleText_loc5`='說吧，$c。', `MaleText_loc7`='Habla, $c.' WHERE `ID`=31217;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 오랜 세월 동안 내 운명을 외면해 왔다. 내가 해야만 하는 일이 명백하지 못했다.$B$B로켄은 내 손으로 없애버리리라.', `MaleText_loc4`='长久以来，我一直不明白自己的命运。我的使命从未像现在这样清晰过。$B$B我必须亲手解决洛肯。', `MaleText_loc5`='我已經逃避我的命運夠久了。我的使命從未如此清楚。$B$B洛肯必須要被我親手毀滅。', `MaleText_loc7`='Ya he evitado mi destino durante bastante tiempo. Nunca he visto tan claro lo que debo hacer.$B$BDebo destruir a Loken yo mismo.' WHERE `ID`=31218;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시프가 어떻게 됐는지 말씀해 주시겠습니까?', `MaleText_loc4`='你能把西芙的事告诉我吗？', `MaleText_loc5`='你能告訴我希芙發生了什麼事嗎?', `MaleText_loc7`='¿Puedes contarme qué fue de Sif?', `FemaleText_loc1`='시프가 어떻게 됐는지 말씀해 주시겠어요?', `FemaleText_loc4`='你能把西芙的事告诉我吗？', `FemaleText_loc5`='你能告訴我希芙發生了什麼事嗎?', `FemaleText_loc7`='¿Puedes contarme qué fue de Sif?' WHERE `ID`=31219;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐 네가 내 사랑하는 시프인지 알았다... 그 머리카락 한올... 하지만 아니지 않은가! 이럴 수는 없다... 시프는 죽었어...$B$B내... 내 형제가... 그녀를 죽였단 말이다!', `MaleText_loc4`='刚才那一瞬间，我把你当成了我亲爱的西芙……那一缕头发……不！那不可能……西芙已经死了……$B$B我……我的兄弟……杀了她！', `MaleText_loc5`='有一瞬間我還以為你是我摯愛的希芙...那樣一綹綹的秀髮...但卻不是!這是不可能的...希芙已經死了!$B$B我的...我的哥哥...殺死了她!', `MaleText_loc7`='Por un instante he creído que eras mi amada Sif... Ese mechón de pelo... ¡pero no! No puede ser... Sif está muerta...$B$B¡Mi hermano... la mató!' WHERE `ID`=31220;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그는 그보다 더한 짓을 했습니다, 토림. 지금 그가 울두아르를 관할하고 있습니다.', `MaleText_loc4`='他罪行还不止于此，托里姆。他现在控制了奥杜尔。', `MaleText_loc5`='他做得不只那樣，索林姆。他現在控制了奧杜亞。', `MaleText_loc7`='Hizo más que eso, Thorim. Él controla Ulduar ahora.', `FemaleText_loc1`='그는 그보다 더한 짓을 했어요, 토림. 지금 그가 울두아르를 관할하고 있어요.', `FemaleText_loc4`='他罪行还不止于此，托里姆。他现在控制了奥杜尔。', `FemaleText_loc5`='他做得不只那樣，索林姆。他現在控制了奧杜亞。', `FemaleText_loc7`='Hizo más que eso, Thorim. Él controla Ulduar ahora.' WHERE `ID`=31221;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='울두아르... 난 울두아르를 지켜내겠다고 맹세했었다.$B$B창조주의 거처를 지켜내겠다고 맹세했었지.$B$B서릿결 부족과 한 계약을 지켜내겠다고 맹세했었다.$B$B하지만 난 실패했다! 내 형제가 날 속이게 내버려뒀다. 내 형제가 내 동맹과 등을 돌리도록 내버려뒀다. 내 형제는 나를 속여 시프의 죽음을 내 절친한 친구이자 서리 거인의 왕인 아른그림의 탓으로 돌리도록 했다.$B$B내가 무슨 짓을 했는지 깨달은 후... 난... 자포자기했다.', `MaleText_loc4`='奥杜尔……我曾经发誓要守护奥杜尔。$B$B发誓要守护造物者圣台。$B$B发誓要守护与冰霜巨人之间的盟誓。$B$B可是我都没有做到！我被我的兄弟欺骗了。他诱使我将矛头指向我的朋友。他骗我说是我亲密的朋友，冰霜巨人之王安格里姆害死了西芙。$B$B当我意识到自己做了什么时……我……陷入了绝望。', `MaleText_loc5`='奧杜亞...我曾立誓要保護奧杜亞。$B$B立誓要保護造物者殿堂。$B$B立誓要保護冰霜種族之間的盟約。$B$B但我失敗了!我任由我的兄長設計陷害我。我任由他設計我和我們盟友反目成仇。他設計我讓我把希芙的死怪罪在最親愛的朋友，安格林，冰霜巨人之王。$B$B等我發現我做了什麼之後...我...我任由自己沈浸在絕望之中。', `MaleText_loc7`='Ulduar... juré proteger Ulduar.$B$BJuré proteger el Templo de los Creadores.$B$BJuré proteger los pactos entre las razas de escarcha.$B$B¡Pero fracasé! Dejé que mi hermano me engañara. Dejé que me pusiera en contra de mis aliados. Me engañó para que culpara de la muerte de Sif a un estimado amigo, Arngrim, el rey de los gigantes de escarcha.$B$BCuando me di cuenta de lo que había hecho... caí en la desesperación.' WHERE `ID`=31222;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 방식으로 끝을 낼 필요는 없습니다.', `MaleText_loc4`='事情或许还有挽回的余地啊。', `MaleText_loc5`='這不需要這樣結束。', `MaleText_loc7`='No es necesario que acabe de este modo.', `FemaleText_loc1`='이런 방식으로 끝을 낼 필요는 없어요.', `FemaleText_loc4`='事情或许还有挽回的余地啊。', `FemaleText_loc5`='這不需要這樣結束。', `FemaleText_loc7`='No es necesario que acabe de este modo.' WHERE `ID`=31223;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조그마한 자여, 넌 누구지? 강대한 나 토림에게 와서 이런 말을 하다니...$B$B널... 박살내 버리겠다!$B$B하지만 넌 망연자실한 내 마음에 구원을 주었다. 이곳에 네가 나타난 게 바로 그 신호다!$B$B내가 널 시프와 혼동했던 건 우연이 아니었다. 그녀가 날 기억해 낼까? 전투를 준비해야겠구나.$B$B내 형제의 광기에서 티탄들의 성스러운 땅을 해방하고 시프의 죽음에 대한 복수를 해야겠다!', `MaleText_loc4`='你是谁，小家伙！竟然对强大的托里姆说这些话……$B$B我应该……撕碎你！$B$B但是你将我从昏迷中唤醒了。你的来到是一个预兆！$B$B我把你错当成西芙，这并不是巧合。她会怎么看我呢？我必须准备战斗了。$B$B我一定要为她报仇，把泰坦的圣地从我那个疯狂的兄弟手中解放出来！', `MaleText_loc5`='你是誰，小傢伙?來跟偉大的索林姆講這些話...$b$b我應該要...碾碎你!$B$B但是，你將我從迷惘中喚醒。你在此出現就是個徵兆!$B$B我把你誤認為希芙並不是個意外。她會怎麼想我?我一定要開始準備戰鬥。$B$B我一定要替她復仇，並且從我兄長的瘋狂中解放泰坦的聖地!', `MaleText_loc7`='¿Quién eres para venir a decir esto al poderoso Thorim, $gpequeño:pequeña;?$B$B¡Debería... aplastarte!$B$BPero me has sacado de mi estupor. ¡Tu presencia aquí es una señal!$B$BNo ha sido un accidente que te confundiera con Sif. ¿Qué pensaría ella de mí? Debo prepararme para la batalla.$B$B¡Debo vengar su muerte y liberar la tierra sagrada de los titanes de la locura de mi hermano!' WHERE `ID`=31224;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 당신과 함께하겠습니다, 토림.', `MaleText_loc4`='我会帮助你的，托里姆。', `MaleText_loc5`='我會跟隨你，索林姆。', `MaleText_loc7`='Estoy contigo, Thorim.', `FemaleText_loc1`='제가 당신과 함께하겠어요, 토림.', `FemaleText_loc4`='我会帮助你的，托里姆。', `FemaleText_loc5`='我會跟隨你，索林姆。', `FemaleText_loc7`='Estoy contigo, Thorim.' WHERE `ID`=31225;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s의 마지막 잔여물이 바닥으로 스며들면서 근처 바닥에 설치된 제단에서 희미하게 빛이 나기 시작합니다.', `MaleText_loc4`='随着%s最后的残骸渗入地下，附近的祭坛开始散发出微弱的光芒。', `MaleText_loc5`='%s剩餘的殘骸流滲到地上，嵌在地板上的祭壇也開始微弱地發著光芒。', `MaleText_loc7`='Cuando los últimos restos de %s se filtran en la tierra, el altar cercano situado en el suelo comienza a brillar débilmente.' WHERE `ID`=31226;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안돼애애애애애애애애애애애애!', `MaleText_loc4`='不！！！！', `MaleText_loc5`='不不不不不不不不不不不不不!', `MaleText_loc7`='¡NOOOOOOOOOOOOOOOOOO!' WHERE `ID`=31227;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭풍우 봉우리에 오신 걸 환영합니다, $r|1이여;여;.', `MaleText_loc4`='欢迎来到风暴峭壁，$r。', `MaleText_loc5`='歡迎來到風暴群山，$r。', `MaleText_loc7`='Te doy la bienvenida a Las Cumbres Tormentosas, $r.' WHERE `ID`=31228;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='브란의 통신기를 잃어버렸습니다. 새로 하나 받았으면 합니다.', `MaleText_loc4`='我把布莱恩的通讯器弄丢了，我想要一个新的。', `MaleText_loc5`='我弄丟了布萊恩的通訊器，需要一個備用的。', `MaleText_loc7`='He perdido el comunicador de Brann y necesito uno de repuesto.', `FemaleText_loc1`='브란의 통신기를 잃어버렸습니다. 새로 하나 받았으면 합니다.', `FemaleText_loc4`='我把布莱恩的通讯器弄丢了，我想要一个新的。', `FemaleText_loc5`='我弄丟了布萊恩的通訊器，需要一個備用的。', `FemaleText_loc7`='He perdido el comunicador de Brann y necesito uno de repuesto.' WHERE `ID`=31229;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='...음냐음냐... ...드르렁... 이리 와라... 무서운 맛... 말로운 님께서 무서운 맛을... 쩝쩝...', `MaleText_loc4`='……zzz……过来……马龙……zzz……', `MaleText_loc5`='...zzz...鼾...來吧...一定...一定瑪羅恩的...zzz...', `MaleText_loc7`='...zzz... ...snrk... ven aquí... te... Gassol te va a machacar... zzz...' WHERE `ID`=31230;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 흠냐... 애들이 장난치는군... 우편물로... 드르렁... 따끔한 맛을... 보여줘야...', `MaleText_loc4`='……呃……谁敢……捣蛋……zzzz……教训……他们……', `MaleText_loc5`='...呣...小鬼弄亂...箱子...zzz...得教訓...他們...', `MaleText_loc7`='...mrf... niños enredar... con cajas... zzzz... enseñar... lección...' WHERE `ID`=31231;
