UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장로 아르프는 어디에 있습니까?', `MaleText_loc4`='雷吼长者在哪里？', `MaleText_loc5`='阿爾普長者在哪裡?', `MaleText_loc7`='¿Dónde está el ancestro Arp?', `FemaleText_loc1`='장로 아르프는 어디에 있나요?', `FemaleText_loc4`='雷吼长者在哪里？', `FemaleText_loc5`='阿爾普長者在哪裡?', `FemaleText_loc7`='¿Dónde está el ancestro Arp?' WHERE `ID`=31252;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장로 아르프는 북풍의 땅에 있는 동물보호협회 야영지에서 시간을 보내고 있다네.', `MaleText_loc4`='雷吼长者在北风苔原的仁德会营地。', `MaleText_loc5`='阿爾普長者花了很多時間在北風凍原的D.E.H.T.A.駐營。', `MaleText_loc7`='El ancestro Arp pasa su tiempo en el campamento de D.E.H.T.A en la Tundra Boreal.', `FemaleText_loc1`='장로 아르프는 북풍의 땅에 있는 동물보호협회 야영지에서 시간을 보내고 있다네.', `FemaleText_loc4`='雷吼长者在北风苔原的仁德会营地。', `FemaleText_loc5`='阿爾普長者花了很多時間在北風凍原的D.E.H.T.A.駐營。', `FemaleText_loc7`='El ancestro Arp pasa su tiempo en el campamento de D.E.H.T.A en la Tundra Boreal.' WHERE `ID`=31253;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장로 파무야는 전쟁노래 요새 바로 바깥쪽에 있다네.', `MaleText_loc4`='长者帕姆亚就在战歌要塞外面。', `MaleText_loc5`='帕姆亞長者就在戰歌堡外。', `MaleText_loc7`='El ancestro Pamuya está justo a las afueras del Bastión Grito de Guerra.', `FemaleText_loc1`='장로 파무야는 전쟁노래 요새 바로 바깥쪽에 있다네.', `FemaleText_loc4`='长者帕姆亚就在战歌要塞外面。', `FemaleText_loc5`='帕姆亞長者就在戰歌堡外。', `FemaleText_loc7`='El ancestro Pamuya está justo a las afueras del Bastión Grito de Guerra.' WHERE `ID`=31254;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장로 파무야는 어디에 있습니까?', `MaleText_loc4`='长者帕姆亚在哪里？', `MaleText_loc5`='帕姆亞長者在哪裡?', `MaleText_loc7`='¿Dónde está el ancestro Pamuya?', `FemaleText_loc1`='장로 파무야는 어디에 있나요?', `FemaleText_loc4`='长者帕姆亚在哪里？', `FemaleText_loc5`='帕姆亞長者在哪裡?', `FemaleText_loc7`='¿Dónde está el ancestro Pamuya?' WHERE `ID`=31255;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누군가가 스톰후프와 툰카로 야영지 전사들의 실제 역사를 왜곡한 것이 틀림없네. 하지만 대체 누가 그런 짓을?', `MaleText_loc4`='毫无疑问，有东西在干扰雷蹄和唐卡洛战士的真实历史。这究竟是怎么回事呢？', `MaleText_loc5`='毫無疑問有某種東西正在扭曲著歷史，那些關於風暴之蹄和坦卡羅營地的戰士的真實歷史。但，是什麼呢?', `MaleText_loc7`='No cabe duda de que algo ha distorsionado la verdadera historia de Pezuña Tempestuosa y los guerreros del Campamento Tunka''lo. Pero, ¿el qué?' WHERE `ID`=31259;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='괜한 애쓰지 마라, 타우렌 애송이. 스톰후프도 네놈도, 그리고 네 친구 어느 누구도 나를 가로막을 수 없다.', `MaleText_loc4`='别自找麻烦了。无论是雷蹄，还是你和你的盟友，谁都不能阻止我。', `MaleText_loc5`='別自找麻煩，小牛頭人。不管是風暴之蹄或你與你的同伴都無法阻礙我。', `MaleText_loc7`='No te preocupes, pequeño tauren. Ni Pezuña Tempestuosa, ni tú, ni tu aliado os interpondréis en mi camino.' WHERE `ID`=31260;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금도 내 힘은 강해지고 있다. 오랫동안 복수를 완성할 날만을 기다려 왔다.', `MaleText_loc4`='我的力量在不断增长。我期待已久的复仇之日总算来临了。', `MaleText_loc5`='就算是現在，我的力量也在持續增長。我一直期盼著有天我長久的復仇會完成。', `MaleText_loc7`='Incluso ahora, mi poder crece. Llevo mucho tiempo esperando el día en el que mi venganza se complete.' WHERE `ID`=31261;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰후프와 그의 일족들은 역사에서 완전히 사라지고, 이 땅은 원래 주인에게 되돌아갈 것이다!', `MaleText_loc4`='雷蹄和他的同胞的历史将被抹去，这片土地将回到真正的主人手中！', `MaleText_loc5`='風暴之蹄和他的族人將會從歷史中被抹除，這片土地將會回歸到它們正統的所有者之手!', `MaleText_loc7`='Pezuña Tempestuosa y sus hermanos serán borrados de la historia y estás tierras volverán a pertenecer a su dueño legítimo.' WHERE `ID`=31262;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니다! 역사 속에 울리는 진정한 외침이 승리하리라. 우리는 네놈이 파괴한 것을 모두 원래대로 되돌릴 것이다!', `MaleText_loc4`='不！真实的历史不容亵渎。我们将恢复被你摧毁的一切！', `MaleText_loc5`='不!歷史真正的聲音將會響徹雲霄。我們會回復你所破壞的一切!', `MaleText_loc7`='¡No! La auténtica voz de la historia triunfará. ¡Restauraremos todo lo que habéis destruido!' WHERE `ID`=31263;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이여;여;, 북풍이 시간을 왜곡하기 시작한 시간대를 서둘러 찾아야 하네. 그래야만 북풍을 물리치고 시간을 바로잡을 수 있네.', `MaleText_loc4`='$n，我们必须尽快确定北风是从什么时候开始篡改时间流的。然后我们才有可能打败他并纠正历史。', `MaleText_loc5`='$n，我們一定要快，趕在北風精靈開始扭曲時間線之前。唯有這樣我們才能擊敗他，並且修正這一切。', `MaleText_loc7`='$n, debemos apresurarnos y descubrir el momento en el que el Viento del Norte comenzó a distorsionar la línea temporal. Solo entonces podremos derrotarle y corregirla.' WHERE `ID`=31264;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장로 이가쇼는 어디에 있습니까?', `MaleText_loc4`='长者伊加苏在哪里？', `MaleText_loc5`='伊加修長者在哪裡?', `MaleText_loc7`='¿Dónde está el ancestro Igasho?', `FemaleText_loc1`='장로 이가쇼는 어디에 있나요?', `FemaleText_loc4`='长者伊加苏在哪里？', `FemaleText_loc5`='伊加修長者在哪裡?', `FemaleText_loc7`='¿Dónde está el ancestro Igasho?' WHERE `ID`=31266;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장로 이가쇼가 최근에 목격된 건 마력의 탑 내를 탐험하던 때였다네.', `MaleText_loc4`='人们最后一次看见长者伊加苏时，他正在探索魔枢。', `MaleText_loc5`='我們最後一次看見伊加修長者時，他正在奧核之心探險。', `MaleText_loc7`='La última vez que se le vio, el ancestro Igasho estaba explorando El Nexo.', `FemaleText_loc1`='장로 이가쇼가 최근에 목격된 건 마력의 탑 내를 탐험하던 때였다네.', `FemaleText_loc4`='人们最后一次看见长者伊加苏时，他正在探索魔枢。', `FemaleText_loc5`='我們最後一次看見伊加修長者時，他正在奧核之心探險。', `FemaleText_loc7`='La última vez que se le vio, el ancestro Igasho estaba explorando El Nexo.' WHERE `ID`=31267;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장로 노르탈은 어디에 있습니까?', `MaleText_loc4`='长者诺塔尔在哪里？', `MaleText_loc5`='諾爾索長者在哪裡?', `MaleText_loc7`='¿Dónde está el ancestro Northal?', `FemaleText_loc1`='장로 노르탈은 어디에 있나요?', `FemaleText_loc4`='长者诺塔尔在哪里？', `FemaleText_loc5`='諾爾索長者在哪裡?', `FemaleText_loc7`='¿Dónde está el ancestro Northal?' WHERE `ID`=31268;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='콜다라에 있는 변위의 보호막 안에서 장로 노르탈을 찾을 수 있네.', `MaleText_loc4`='你可以到考达拉的永生之盾去找长者诺塔尔。', `MaleText_loc5`='你可以在凜懼島的隘境之盾找到諾爾索長者。', `MaleText_loc7`='Encontrarás al ancestro Northal dentro del Escudo de Tránsito en Gelidar.', `FemaleText_loc1`='콜다라에 있는 변위의 보호막 안에서 장로 노르탈을 찾을 수 있네.', `FemaleText_loc4`='你可以到考达拉的永生之盾去找长者诺塔尔。', `FemaleText_loc5`='你可以在凜懼島的隘境之盾找到諾爾索長者。', `FemaleText_loc7`='Encontrarás al ancestro Northal dentro del Escudo de Tránsito en Gelidar.' WHERE `ID`=31269;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장로 살디스는 어디에 있습니까?', `MaleText_loc4`='长者萨迪斯在哪里？', `MaleText_loc5`='沙迪斯長者在哪裡?', `MaleText_loc7`='¿Dónde está el ancestro Sardis?', `FemaleText_loc1`='장로 살디스는 어디에 있나요?', `FemaleText_loc4`='长者萨迪斯在哪里？', `FemaleText_loc5`='沙迪斯長者在哪裡?', `FemaleText_loc7`='¿Dónde está el ancestro Sardis?' WHERE `ID`=31270;
