UPDATE `locales_broadcast_text` SET `MaleText_loc1`='믎프륾륾프륾를!$B$B<목을 가다듬는 외눈깨비>$B$B응?', `MaleText_loc4`='Mrfrrmrfrmrrr！$B$B<恶鬼清了清喉咙。>$B$B嗯？', `MaleText_loc5`='咳咳咳咳!$B$B<魂屍清了清他的喉嚨。>$B$B有事嗎?', `MaleText_loc7`='¡Mrfrrmrfrmrrr!$B$B<El geist se aclara la garganta.>$B$B¿Sí?' WHERE `ID`=31312;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직은 고대의 해안에서 싸울 만큼 강하지 못한 분이군요. 가서 경험을 더 쌓고 오십시오.', `MaleText_loc4`='你还不够强壮，不足以参加远古海滩的战斗。等你经验更丰富一些的时候再来找我吧。', `MaleText_loc5`='你的等級還不足以參加遠祖灘頭的戰鬥。等你獲得更多經驗的時候再回來。', `MaleText_loc7`='Aún no posees fuerza suficiente para luchar en la Playa de los Ancestros. Vuelve cuando hayas obtenido más experiencia.', `FemaleText_loc1`='아직은 고대의 해안에서 싸울 만큼 강하지 못한 분이네요. 가서 경험을 더 쌓고 오세요.', `FemaleText_loc4`='你还不够强壮，不足以参加远古海滩的战斗。等你经验更丰富一些的时候再来找我吧。', `FemaleText_loc5`='你的等級還不足以參加遠祖灘頭的戰鬥。等你獲得更多經驗的時候再回來。', `FemaleText_loc7`='Aún no posees fuerza suficiente para luchar en la Playa de los Ancestros. Vuelve cuando hayas obtenido más experiencia.' WHERE `ID`=31313;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드가 고대의 해안에 숨겨진 비밀을 우리에게 적대적으로 이용하게 둘 수는 없습니다. 그대도 저기 있는 용감한 병사들과 함께하시겠습니까?', `MaleText_loc4`='我们不能让部落利用远古海滩的秘密来对付我们。你愿意帮助我们在那里战斗的勇士吗？', `MaleText_loc5`='我們不能任由部落將遠祖灘頭所隱藏的秘密用來對付我們。你願意加入我們英勇士兵的行列嗎?', `MaleText_loc7`='No podemos permitir que la Horda utilice los secretos ocultos de la Playa de los Ancestros contra nosotros. ¿Te unirás a nuestros valientes soldados allí?', `FemaleText_loc1`='호드가 고대의 해안에 숨겨진 비밀을 우리에게 적대적으로 이용하게 둘 수는 없어요. 그대도 저기 있는 용감한 병사들과 함께하시겠어요?', `FemaleText_loc4`='我们不能让部落利用远古海滩的秘密来对付我们。你愿意帮助我们在那里战斗的勇士吗？', `FemaleText_loc5`='我們不能任由部落將遠祖灘頭所隱藏的秘密用來對付我們。你願意加入我們英勇士兵的行列嗎?', `FemaleText_loc7`='No podemos permitir que la Horda utilice los secretos ocultos de la Playa de los Ancestros contra nosotros. ¿Te unirás a nuestros valientes soldados allí?' WHERE `ID`=31315;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스가 고대의 해안에 숨겨진 비밀을 우리에게 적대적으로 이용하게 둘 수는 없습니다. 그대도 저기 있는 용감한 병사들과 함께하시겠습니까?', `MaleText_loc4`='我们不能让联盟利用远古海滩的秘密来对付我们。你愿意帮助我们在那里战斗的勇士吗？', `MaleText_loc5`='我們不能任由聯盟將遠祖灘頭所隱藏的秘密用來對付我們。你願意加入我們英勇戰士的行列嗎?', `MaleText_loc7`='No podemos permitir que la Alianza utilice los secretos ocultos de la Playa de los Ancestros contra nosotros. ¿Te unirás a nuestros valientes guerreros allí?', `FemaleText_loc1`='얼라이언스가 고대의 해안에 숨겨진 비밀을 우리에게 적대적으로 이용하게 둘 수는 없어요. 그대도 저기 있는 용감한 병사들과 함께하시겠어요?', `FemaleText_loc4`='我们不能让联盟利用远古海滩的秘密来对付我们。你愿意帮助我们在那里战斗的勇士吗？', `FemaleText_loc5`='我們不能任由聯盟將遠祖灘頭所隱藏的秘密用來對付我們。你願意加入我們英勇戰士的行列嗎?', `FemaleText_loc7`='No podemos permitir que la Alianza utilice los secretos ocultos de la Playa de los Ancestros contra nosotros. ¿Te unirás a nuestros valientes guerreros allí?' WHERE `ID`=31316;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너는 지금 광범위 요툰하임 지역에서 벗어나고 있다. 되돌리지 않으면 원시비룡을 잃고 말리라.', `MaleText_loc4`='你即将离开尤顿海姆区域。立即返回，否则始祖幼龙会将你掀下背。', `MaleText_loc5`='你正在離開偉大的卓頓海姆領域。回來否則就是會失去元龍。', `MaleText_loc7`='Estás abandonando la gran región Jotunheim. Vuelve o perderás el protodraco.' WHERE `ID`=31317;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샤드론! 이리 와라! 위험한 상황이다!', `MaleText_loc4`='沙德隆，帮帮我！一切都危在旦夕！', `MaleText_loc5`='夏德朗!快過來!事態危急!', `MaleText_loc7`='¡Shadron! ¡Ven hacia mí! ¡Todo corre peligro!' WHERE `ID`=31318;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='테네브론! 너도 알을 지킬 책임이 있어!', `MaleText_loc4`='塔尼布隆！你也有保护龙卵的责任！', `MaleText_loc5`='坦納伯朗!你也應該要保護龍蛋!', `MaleText_loc7`='¡Tenebron! ¡También debes cuidar de los huevos!' WHERE `ID`=31319;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='베스페론! 알이 위험하다! 날 도와라!', `MaleText_loc4`='维斯匹隆，情况危急！快来帮助我！', `MaleText_loc5`='維斯佩朗，龍巢有危險了!快來幫我!', `MaleText_loc7`='¡Vesperon, la nidada está en peligro! ¡Ayúdame!' WHERE `ID`=31320;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 당신을 주시합니다!', `MaleText_loc4`='%s在注视你！', `MaleText_loc5`='%s將他的目光鎖在你身上!', `MaleText_loc7`='¡%s fija su mirada en ti!', `FemaleText_loc1`='%s|1이;가; 당신을 주시합니다!', `FemaleText_loc4`='%s在注视你！', `FemaleText_loc5`='%s將他的目光鎖在你身上!', `FemaleText_loc7`='¡%s fija su mirada en ti!' WHERE `ID`=31321;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐요! 제 저장고에서 그만 알짱거리십시오! 당장 나가란 말입니다!', `MaleText_loc4`='嘿！别在我的酒窖里捣乱！走开！', `MaleText_loc5`='嘿!不要在我的地窖裡面晃來晃去!快滾!', `MaleText_loc7`='¡Oye! ¡Deja de merodear por mi sótano! ¡Lárgate!' WHERE `ID`=31322;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 저장고에서 뭘 하고 있었습니까? 요즘은 음식을 안심하고 먹을 수 없는 때입니다. 내 물건을 샅샅이 뒤지는 낯선 이는 정말이지 보고 싶지 않습니다! 저리 꺼지십시오!', `MaleText_loc4`='你在我的酒窖里干了什么？之前发生了食物中毒事件，我最讨厌陌生人乱翻我的货物！滚开！', `MaleText_loc5`='你們在我的地窖裡做什麼?外頭有個食物恐怖事件，我最不需要的就是有一群陌生人靠近我的貨物!滾!', `MaleText_loc7`='¿Qué estabas haciendo en mi sótano? ¡Hay problemas con la comida y lo último que necesito son extraños enredando en mis bienes! ¡Fuera!' WHERE `ID`=31323;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 전부 공황 상태로 가는 것 같은데. 그렇게 생각하지 않나?', `MaleText_loc4`='这件事太可疑了，你觉得呢？', `MaleText_loc5`='這整個情況都有點瘋狂，你不覺得嗎?', `MaleText_loc7`='Toda esta situación resulta un poco paranoica, ¿no te parece?' WHERE `ID`=31324;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명령은 명령입니다. 왕자님께서 뛰어들라 하시면...', `MaleText_loc4`='命令就是命令。如果王子要我跳……', `MaleText_loc5`='命令就是命令。如果王子說跳...', `MaleText_loc7`='Las órdenes son las órdenes. Si el Príncipe dice salta...' WHERE `ID`=31325;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그건 말도 안 되는 명령이니 거부할 수 있소. 의심 가는 음식이라고? 그 말대로라면 벨패스트부터 체포해야 할 것이오!', `MaleText_loc4`='奇怪的命令，你无法否认这一点。可疑食物？凭这一点，你就应该逮捕贝法斯！', `MaleText_loc5`='你不能否認，這是個奇怪的命令。可疑的食物?根據這樣的定義，你應該要逮捕貝爾法斯特!', `MaleText_loc7`='No puedes negar que es una orden rara. ¿Comida sospechosa? ¡Basándote en esa definición, deberías arrestar a Belfast!' WHERE `ID`=31326;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방금 뭐라 했는지 들었습니다! 앞으로 여기서 맥주 먹을 꿈도 꾸지 마십시오. 단 한 방울도 말입니다!', `MaleText_loc4`='我听见了！我不卖啤酒给你了！一滴也不卖！', `MaleText_loc5`='我聽到了!你們沒有麥酒喝了!一滴都沒有!', `MaleText_loc7`='¡TE HE OÍDO! ¡Se acabó la cerveza para ti! ¡Ni una gota más!' WHERE `ID`=31327;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제... 날 수 있다. 못 찾을걸! 탈출!', `MaleText_loc4`='自由啦……呱呱。呱呱……没有找到……我们！逃跑！', `MaleText_loc5`='現在可以--嗯嗯--自由飛翔。嘎嘎...找不到我們--哎咯-哎咯!逃跑!', `MaleText_loc7`='Libre para... mmmhh... volar ahora. Ra-aak... No encontrarnos... ekh-ekh ¡Escapar!' WHERE `ID`=31328;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='깨어남의 세계에 다시 온 걸 환영한다, 필멸의 존재여.', `MaleText_loc4`='欢迎醒来，孩子。', `MaleText_loc5`='歡迎回到清醒的世界，孩子。', `MaleText_loc7`='$gBienvenido:Bienvenida; de nuevo al mundo consciente, $ghijo:hija;.' WHERE `ID`=31329;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 주체할 수 없는 분노다!', `MaleText_loc4`='我……就是……无尽的愤怒！', `MaleText_loc5`='我...就是不可抑制的...狂怒!', `MaleText_loc7`='¡Soy... furia... descontrolada!' WHERE `ID`=31330;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='믿음을 잃지 말도록.', `MaleText_loc4`='不要丧失信仰。', `MaleText_loc5`='不要失去信心。', `MaleText_loc7`='No pierdas la fe.' WHERE `ID`=31331;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스컬지의 종말이 가까웠다.', `MaleText_loc4`='天灾军团的末日即将降临。', `MaleText_loc5`='天譴軍團的末日就要來了。', `MaleText_loc7`='El final de la Plaga se acerca.' WHERE `ID`=31333;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은빛십자군의 시대가 도래했다!', `MaleText_loc4`='银色北伐军的时代已经来临！', `MaleText_loc5`='銀白十字軍的時代...來臨了。', `MaleText_loc7`='Este es el momento de la Cruzada Argenta.' WHERE `ID`=31334;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 승리하리라!', `MaleText_loc4`='胜利属于我们！', `MaleText_loc5`='我們必將凱旋。', `MaleText_loc7`='¡Triunfaremos!' WHERE `ID`=31335;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛을 믿고 의지하면 못할 일이 없으리라!', `MaleText_loc4`='信仰圣光吧，一切都可能实现！', `MaleText_loc5`='相信聖光，你將無所不能。', `MaleText_loc7`='¡Ten fe en la Luz y todo será posible!' WHERE `ID`=31336;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영업시간이다. 이제, 탈출 계획을 실행에 옮겨야겠지?', `MaleText_loc4`='快去干活！现在是时候实施我们的越狱计划了。', `MaleText_loc5`='快去幹活!現在是時候實施我們的越獄計畫了。', `MaleText_loc7`='¡De vuelta a trabajar! Bien, a planificar una estrategia de salida.' WHERE `ID`=31337;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='할 테면 해봐라! 파멸의 인도자가 내뿜는 분노를 아무도 피하지 못하리라!', `MaleText_loc4`='魔鬼，接招！你休想逃过灰烬使者的怒火！', `MaleText_loc5`='我已經盯上你了，惡魔!你逃不過灰燼使者的憤怒!', `MaleText_loc7`='¡Estáis acabados, enemigos! ¡No escaparéis a la furia de la Crematoria!' WHERE `ID`=31338;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나... 소생했다.', `MaleText_loc4`='我获得了……新生。', `MaleText_loc5`='我獲得了...新生。', `MaleText_loc7`='Estoy... renovado.' WHERE `ID`=31339;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미용실', `MaleText_loc4`='理发师', `MaleText_loc5`='美容師', `MaleText_loc7`='Peluquero', `FemaleText_loc1`='미용실', `FemaleText_loc4`='理发师', `FemaleText_loc5`='美容師', `FemaleText_loc7`='Peluquero' WHERE `ID`=31340;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='패배의 대가가... 이것인가...', `MaleText_loc4`='这……就是失败的……代价……', `MaleText_loc5`='這就是失敗的...代價...', `MaleText_loc7`='Ese es el precio... del fracaso…' WHERE `ID`=31341;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='살덩이작업장은 스컬지가 구울, 누더기골렘, 살덩이 구울을 만들어내는 본거지지요. 우리가 살덩이작업장을 처리한다면, 리치 왕은 크게 약해질 거예요.', `FemaleText_loc4`='缝合场是天灾军团制造食尸鬼、憎恶和血肉巨人的中心。如果我们能摧毁这座工厂，巫妖王的力量就会被大大削弱。', `FemaleText_loc5`='血肉作坊是天譴軍團的食屍鬼、憎惡體和血肉巨人生產的核心。要是我們能奪下該地，那巫妖王將會大受打擊。', `FemaleText_loc7`='La Factoría de Carne es el corazón de la producción de necrófagos, abominaciones y gigantes de carne de la Plaga. Si podemos destruirla, debilitaremos al Rey Exánime de forma significativa.' WHERE `ID`=31342;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무쇠 감시자는 세월이 감에 따라 늘어난 부식으로 행동이 둔해졌습니다. 발을 재빨리 놀리면 그가 당신을 능가하지 못할겁니다. 당신은 스톰하트 왕의 총애를 얻은 분입니다. 실망시키지 마십시오.', `MaleText_loc4`='岁月的侵蚀令他变得行动迟缓……你只要保持身手敏捷，他是不可能战胜你的。雷心国王在默默地支持你——别让他失望。', `MaleText_loc5`='他因為陳年的鏽蝕而行動遲緩...只要你的動作夠快，他就無法贏過你。你有風暴之心國王的眷顧 - 不要讓他失望。', `MaleText_loc7`='El paso de los años lo ha vuelto lento... si eres ágil no te vencerá. Cuentas con el favor del rey Cuoretormenta, no le decepciones.' WHERE `ID`=31343;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실력이 얼마나 되는지 보자, 아서스 왕자.', `MaleText_loc4`='这真是最好的试炼，阿尔萨斯王子殿下。', `MaleText_loc5`='這是個很不錯的測驗，阿薩斯王子。', `MaleText_loc7`='Será una excelente prueba, Príncipe Arthas.' WHERE `ID`=31344;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쉴 때다.', `MaleText_loc4`='时间到。', `MaleText_loc5`='時間到了。', `MaleText_loc7`='Detente un momento.' WHERE `ID`=31345;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피곤해 보이는데?', `MaleText_loc4`='你似乎很累了。', `MaleText_loc5`='你看起來似乎很累。', `MaleText_loc7`='Te ves cansado.' WHERE `ID`=31346;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠, 이거 실망인데...', `MaleText_loc4`='太简单了。', `MaleText_loc5`='太簡單了。', `MaleText_loc7`='Facilísimo.' WHERE `ID`=31347;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠의 군주는 귀찮게 구는 녀석을 싫어하지.', `MaleText_loc4`='黑暗之王对你的介入很不高兴。', `MaleText_loc5`='黑暗領主不喜歡你的打擾。', `MaleText_loc7`='El Señor Oscuro está disgustado con tu intromisión.' WHERE `ID`=31348;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 아서스 왕자를 원한다. 네가 아니라...', `MaleText_loc4`='我要的是阿尔萨斯王子，不是你！', `MaleText_loc5`='我要找的是阿薩斯王子，不是你!', `MaleText_loc7`='¡Quiero al Príncipe Arthas, no a ti!' WHERE `ID`=31349;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탑과 벽을 수리하라! 나쁜 놈들이 가까이 오지 못하게 하라!', `MaleText_loc4`='快把塔楼和城墙修好！别让敌人冲进来了！', `MaleText_loc5`='修補哨塔與城牆!別讓壞人靠近我們!', `MaleText_loc7`='¡Estamos arreglando la torre y el muro! ¡Mantén a los malos alejados!' WHERE `ID`=31350;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으아! 빌어먹을 말가니스! 아버지... 제이나... 로데론을 지키지 못했습니다...', `MaleText_loc4`='啊！诅咒你，玛尔加尼斯！父王……吉安娜……我令洛丹伦失望了……', `MaleText_loc5`='啊!詛咒你，瑪爾加尼斯!父王...珍娜...我令羅德隆失望了...', `MaleText_loc7`='¡Agh! ¡Maldito seas, Mal''Ganis! Padre... Jaina... Le fallé a Lordaeron…' WHERE `ID`=31351;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이리 와라, 로데론의 병사여! 도움이 필요하다!', `MaleText_loc4`='保护你们的王子，洛丹伦的士兵们，我需要帮助！', `MaleText_loc5`='羅德隆的士兵們，保護你們的王子!我需要支援!', `MaleText_loc7`='¡Protejan a su príncipe, soldados de Lordaeron! ¡Necesito ayuda!' WHERE `ID`=31352;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 버티기 어렵다! 날 도와라!', `MaleText_loc4`='我要顶不住了！帮帮我！', `MaleText_loc5`='我快要被壓制住了!援護我!', `MaleText_loc7`='¡No puedo más! ¡Ayúdenme!' WHERE `ID`=31353;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말가니스는 이 대가를 치를 것이다.', `MaleText_loc4`='玛尔加尼斯必将为此付出代价。', `MaleText_loc5`='瑪爾加尼斯必將為此付出代價。', `MaleText_loc7`='Mal''Ganis pagará por esto.' WHERE `ID`=31354;
