UPDATE `locales_broadcast_text` SET `MaleText_loc1`='북극 스튜를 만드는 법을 다시 알려 주십시오.', `MaleText_loc4`='我要温习诺森德炖肉的做法。', `MaleText_loc5`='提醒我怎麼做北地燉肉。', `MaleText_loc7`='Recuérdame cómo se prepara el Estofado del Norte.', `FemaleText_loc1`='북극 스튜를 만드는 법을 다시 알려 주세요.', `FemaleText_loc4`='我要温习诺森德炖肉的做法。', `FemaleText_loc5`='提醒我怎麼做北地燉肉。', `FemaleText_loc7`='Recuérdame cómo se prepara el Estofado del Norte.' WHERE `ID`=31361;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1을;를; 둘러싼 용암이 끓어오릅니다!', `MaleText_loc4`='%s周围的岩浆沸腾了起来！', `MaleText_loc5`='圍繞著%s的熔岩開始劇烈地翻騰!', `MaleText_loc7`='¡La lava se arremolina alrededor de %s!' WHERE `ID`=31362;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 불에 아주 잘 타겠군!', `MaleText_loc4`='这些小虫太容易燃烧起来了……', `MaleText_loc5`='真是一群容易著火的小蟲子...', `MaleText_loc7`='Qué bichitos tan combustibles…' WHERE `ID`=31363;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='즉시 요툰하임으로 돌아가십시오. 해골 마녀가 지닌 마법이 약해짐을 느낄 수 있을 것입니다!', `MaleText_loc4`='立刻返回尤顿海姆。你感到白骨女巫的法术正在减弱！', `MaleText_loc5`='立刻回到卓頓海姆。你可以感覺到骸骨女巫的佔據法術正在失效!', `MaleText_loc7`='Vuelve a Jotunheim de inmediato. ¡El conjuro de posesión de las Brujas Osarias está fallando! ¡Puedes percibirlo!' WHERE `ID`=31364;
