UPDATE `locales_broadcast_text` SET `MaleText_loc1`='징벌의 폭탄이 준비되었다! 악마를 이 땅에서 깨끗이 몰아내라!', `MaleText_loc4`='银色火炮准备就绪！净化这片土地上的罪恶吧！', `MaleText_loc5`='報應炸彈已經準備好了!清除這片土地上的邪惡吧!', `MaleText_loc7`='¡Bomba de expiación LISTA! ¡Purga el mal de este territorio!' WHERE `ID`=31367;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시시한 장난도 여기서 끝이다!', `MaleText_loc4`='你们这可笑的骚扰到此为止了！', `MaleText_loc5`='這場可悲的攻擊到此為止!', `MaleText_loc7`='¡Que termine AHORA este lastimoso asedio!' WHERE `ID`=31368;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런 버림받은 땅에서 그대 같은 영웅을 만나면 언제나 기쁘답니다. 제가 어떤 식으로라도 도와드릴 일이 있나요?', `FemaleText_loc4`='能在这片被遗弃的土地上见到你这样的英雄，真是令人愉快。我能帮你什么忙吗？', `FemaleText_loc5`='很高興能在這片被遺棄的土地上遇見你這樣的英雄。我能提供你什麼樣的協助嗎?', `FemaleText_loc7`='Siempre es un placer conocer a personajes de tu talla en esta tierra abandonada. ¿Puedo ofrecerte algún tipo de ayuda?' WHERE `ID`=31369;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까. 당신을 심오한 마법의 세계 좀 더 깊은 곳으로 안내해 드리겠습니다.', `MaleText_loc4`='你好，法师。你愿意领略高深莫测的魔法世界吗？', `MaleText_loc5`='歡迎，法師。我應該提供你關於魔法世界更深的見解嗎?', `MaleText_loc7`='Saludos, $gmago:maga;. ¿Quieres que te informe más a fondo sobre el mundo de la magia?', `FemaleText_loc1`='안녕하십니까. 당신을 심오한 마법의 세계 좀 더 깊은 곳으로 안내해 드리겠습니다.', `FemaleText_loc4`='你好，法师。你愿意领略高深莫测的魔法世界吗？', `FemaleText_loc5`='歡迎，法師。我應該提供你關於魔法世界更深的見解嗎?', `FemaleText_loc7`='Saludos, $gmago:maga;. ¿Quieres que te informe más a fondo sobre el mundo de la magia?' WHERE `ID`=31370;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑습니다, $c님. 제가 조언 하나만 하지요. 세상을 여행할 때 부디 마법을 조심하시기 바랍니다. 마법에 서투른 자들은 새카맣게 타버릴 수 있으니까요.', `MaleText_loc4`='你好，$c。给你一个建议：当你在世界各地旅行的时候，要当心魔法，未经训练的外行人很容易被魔法灼伤。', `MaleText_loc5`='很高興見到你，$c。我給你的建議是:當你在世界旅行的時候，要當心魔法可能會傷害那些未受訓練的人。', `MaleText_loc7`='Hola, $c. Mi consejo para ti es este: cuando viajes por el mundo, ten cuidado con la magia porque puede acabar con el profano.', `FemaleText_loc1`='반갑습니다, $c님. 제가 조언 하나만 하지요. 세상을 여행할 때 부디 마법을 조심하시기 바랍니다. 마법에 서투른 자들은 새카맣게 타버릴 수 있으니까요.', `FemaleText_loc4`='你好，$c。给你一个建议：当你在世界各地旅行时，要小心应付魔法。未经训练的外行人很容易被魔法灼伤。', `FemaleText_loc5`='很高興見到你，$c。我給你的建議是:當你在世界旅行的時候，要當心魔法可能會傷害那些未受訓練的人。', `FemaleText_loc7`='Hola, $c. Mi consejo para ti es este: cuando viajes por el mundo, ten cuidado con la magia porque puede acabar con el profano.' WHERE `ID`=31371;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='만나뵈어서 영광입니다, 대드루이드님. 저는 티리온 경이 준 임무를 수행 중입니다만, 시간이 넉넉지 않습니다. 달숲으로 가는 차원문을 열어주실 수 있으십니까?', `MaleText_loc4`='很高兴见到你，大德鲁伊。我奉提里奥之命执行一项重要的使命，时间紧迫，你能送我去月光林地吗？', `MaleText_loc5`='我也很高興見到你，大德魯伊。我肩負著提里奧所賦予的任務而時間有限，能麻煩你將我傳送至月光林地嗎?', `MaleText_loc7`='Un placer conocerte a ti también, archidruida. Estoy cumpliendo un encargo de Tirion y no dispongo de mucho tiempo. ¿Te importaría mostrarme un portal a Claro de la Luna?', `FemaleText_loc1`='만나뵈어서 영광이에요, 대드루이드님. 저는 티리온 경이 준 임무를 수행 중이지만, 시간이 넉넉지 않아요. 달숲으로 가는 차원문을 열어주실 수 있으세요?', `FemaleText_loc4`='很高兴见到你，大德鲁伊。我奉提里奥之命执行一项重要的使命，时间紧迫，你能送我去月光林地吗？', `FemaleText_loc5`='我也很高興見到你，大德魯伊。我肩負著提里奧所賦予的任務而時間有限，能麻煩你將我傳送至月光林地嗎?', `FemaleText_loc7`='Un placer conocerte a ti también, archidruida. Estoy cumpliendo un encargo de Tirion y no dispongo de mucho tiempo. ¿Te importaría mostrarme un portal a Claro de la Luna?' WHERE `ID`=31372;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='물론이지요! 엘룬의 축복이 그대의 여행에 깃들기를 빕니다.', `FemaleText_loc4`='当然可以！愿艾露恩祝福你。', `FemaleText_loc5`='當然!帶著伊露恩的祝福出發吧。', `FemaleText_loc7`='¡Por supuesto! Ve con la bendición de Elune.' WHERE `ID`=31373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일제 사격!', `MaleText_loc4`='单炮连射！', `MaleText_loc5`='發射箭雨!', `MaleText_loc7`='¡Disparad una salva!', `FemaleText_loc1`='일제 사격!', `FemaleText_loc4`='单炮连射！', `FemaleText_loc5`='發射箭雨!', `FemaleText_loc7`='¡Disparad una salva!' WHERE `ID`=31374;
