UPDATE `locales_broadcast_text` SET `MaleText_loc1`='홀수 번 대포 발사!', `MaleText_loc4`='奇数号的大炮开火！', `MaleText_loc5`='單數火砲發射!', `MaleText_loc7`='¡Fuego los cañones impares!', `FemaleText_loc1`='홀수 번 대포 발사!', `FemaleText_loc4`='奇数号的大炮开火！', `FemaleText_loc5`='單數火砲發射!', `FemaleText_loc7`='¡Fuego los cañones impares!' WHERE `ID`=31376;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전체 대포 발사!', `MaleText_loc4`='全体开火！', `MaleText_loc5`='火砲齊射!', `MaleText_loc7`='¡Fuego todos los cañones!', `FemaleText_loc1`='전체 대포 발사!', `FemaleText_loc4`='全体开火！', `FemaleText_loc5`='火砲齊射!', `FemaleText_loc7`='¡Fuego todos los cañones!' WHERE `ID`=31377;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='집중 사격!', `MaleText_loc4`='弹幕齐射！', `MaleText_loc5`='彈幕發射!', `MaleText_loc7`='¡Bombardead!', `FemaleText_loc1`='집중 사격!', `FemaleText_loc4`='弹幕齐射！', `FemaleText_loc5`='彈幕發射!', `FemaleText_loc7`='¡Bombardead!' WHERE `ID`=31378;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자유 사격!', `MaleText_loc4`='自由射击！', `MaleText_loc5`='自由開火!', `MaleText_loc7`='¡Fuego a discreción!', `FemaleText_loc1`='자유 사격!', `FemaleText_loc4`='自由射击！', `FemaleText_loc5`='自由開火!', `FemaleText_loc7`='¡Fuego a discreción!' WHERE `ID`=31379;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하십니까. 일부러 대화를 엿들으려고 한 것은 아닙니다. 제가 조금 도와드리도록 허락해 주십시오.', `FemaleText_loc4`='嗨。我无意中听到了你们的谈话。请让我出一份力吧。', `FemaleText_loc5`='太棒了。我忍不住聽見了你們的對話。請務必讓我提供一些協助。', `FemaleText_loc7`='Saludos. No he podido evitar oír la conversación. Permitidme ofrecer mi ayuda.' WHERE `ID`=31380;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 달라란을 거쳐 은빛십자군 선봉기지로 돌아가니 저와 함께 돌아가고 싶으시다면 그렇게 하십시오.', `FemaleText_loc4`='我正打算从达拉然返回银色前线基地。英雄，你愿意与我同行吗？', `FemaleText_loc5`='我要經過達拉然回到銀白先鋒駐地，如果你願意的話，可以與我同行，英雄。', `FemaleText_loc7`='Me dirijo a La Vanguardia Argenta por Dalaran, si quieres acompañarme.' WHERE `ID`=31381;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='트롤의 역사에 있어서 어둠으로 가득한 나날이 아닐 수 없네.', `MaleText_loc4`='朋友，今天是巨魔历史上黑暗的一天。', `MaleText_loc5`='這真是食人妖歷史上黑暗的一日，老兄。', `MaleText_loc7`='Es un día aciago en la historia de los trols, colega.' WHERE `ID`=31382;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 지독하군. 보고 있을 수가 없네.', `MaleText_loc4`='太可怕了。我连看都不敢看。', `MaleText_loc5`='真是太可怕了，老兄。我簡直不敢看。', `MaleText_loc7`='Es horrible, colega. No puedo ni mirar.' WHERE `ID`=31383;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 없었더라면 저희는 해내지 못했을 겁니다.', `MaleText_loc4`='没有你的帮助，我们很难取得胜利。', `MaleText_loc5`='要是沒有你，我一定無法完成，$g先生:女士;。', `MaleText_loc7`='No lo hubiéramos conseguido sin ti, camarada.', `FemaleText_loc1`='$n|1이;가; 없었더라면 저희는 해내지 못했을 거예요.', `FemaleText_loc4`='没有你的帮助，我们很难取得胜利。', `FemaleText_loc5`='要是沒有你，我一定無法完成，$g先生:女士;。', `FemaleText_loc7`='No lo hubiéramos conseguido sin ti, camarada.' WHERE `ID`=31384;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='십자군의 영웅이 나가신다!', `MaleText_loc4`='瞧，前线基地的英雄！', `MaleText_loc5`='先鋒駐地的英雄來了!', `MaleText_loc7`='¡Allá va la estrella de la Vanguardia!', `FemaleText_loc1`='십자군의 영웅이 여기 가십니다!', `FemaleText_loc4`='瞧，前线基地的英雄！', `FemaleText_loc5`='先鋒駐地的英雄來了!', `FemaleText_loc7`='¡Allá va la estrella de la Vanguardia!' WHERE `ID`=31385;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희와 함께 해주셔서 감사합니다, $n 님.', `MaleText_loc4`='你是我们的荣耀，$n。', `MaleText_loc5`='你的到來讓我們倍感光榮，$n。', `MaleText_loc7`='Nos honras con tu presencia, $n.', `FemaleText_loc1`='저희와 함께 해주셔서 감사해요, $n 님.', `FemaleText_loc4`='你是我们的荣耀，$n。', `FemaleText_loc5`='你的到來讓我們倍感光榮，$n。', `FemaleText_loc7`='Nos honras con tu presencia, $n.' WHERE `ID`=31386;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='결심이 흔들리지 않는 한, 우리는 절대 패배하지 않습니다!', `MaleText_loc4`='有了你的坚定与果断，我们一定能取得胜利！', `MaleText_loc5`='有你堅定的決心，我們一定不會失敗!', `MaleText_loc7`='¡Con tu implacable determinación, no podemos fracasar!', `FemaleText_loc1`='결심이 흔들리지 않는 한, 우리는 절대 패배하지 않을 거예요!', `FemaleText_loc4`='有了你的坚定与果断，我们一定能取得胜利！', `FemaleText_loc5`='有你堅定的決心，我們一定不會失敗!', `FemaleText_loc7`='¡Con tu implacable determinación, no podemos fracasar!' WHERE `ID`=31387;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다, $n 님. 마음 깊숙이에서 우러나오는 진심으로 감사를 드립니다.', `MaleText_loc4`='谢谢，$n。衷心地感谢你。', `MaleText_loc5`='感謝你，$n。發自我的內心，感謝你。', `MaleText_loc7`='Gracias, $n. Te lo digo de corazón. Muchas gracias.', `FemaleText_loc1`='감사해요, $n 님. 마음 깊숙이에서 우러나오는 진심으로 감사를 드려요.', `FemaleText_loc4`='谢谢，$n。衷心地感谢你。', `FemaleText_loc5`='感謝你，$n。發自我的內心，感謝你。', `FemaleText_loc7`='Gracias, $n. Te lo digo de corazón. Muchas gracias.' WHERE `ID`=31388;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언제라도 저를 불러 주십시오, $n 님.', `MaleText_loc4`='随时为你效劳，$n。', `MaleText_loc5`='隨時聽你號令，$n。', `MaleText_loc7`='Ven a verme cuando quieras, $n.', `FemaleText_loc1`='언제라도 저를 불러 주세요, $n 님.', `FemaleText_loc4`='随时为你效劳，$n。', `FemaleText_loc5`='隨時聽你號令，$n。', `FemaleText_loc7`='Ven a verme cuando quieras, $n.' WHERE `ID`=31389;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희는 목숨이 다할 때까지 그대의 편에서 싸우겠습니다.', `MaleText_loc4`='我愿与你并肩作战，直到最后一刻！', `MaleText_loc5`='我們將會與你並肩作戰，直到苦澀的終點，$g先生:女士;。', `MaleText_loc7`='¡Lucharemos a tu lado hasta el amargo final, camarada!', `FemaleText_loc1`='저희는 목숨이 다할 때까지 그대의 편에서 싸울 거예요.', `FemaleText_loc4`='我愿与你并肩作战，直到最后一刻！', `FemaleText_loc5`='我們將會與你並肩作戰，直到苦澀的終點，$g先生:女士;。', `FemaleText_loc7`='¡Lucharemos a tu lado hasta el amargo final, camarada!' WHERE `ID`=31390;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영웅이여, 너무나 영광스럽습니다.', `MaleText_loc4`='尊贵的英雄。', `MaleText_loc5`='英雄，我倍感榮幸。', `MaleText_loc7`='Es todo un honor.', `FemaleText_loc1`='영웅이여, 너무나 영광스러워요.', `FemaleText_loc4`='尊贵的英雄。', `FemaleText_loc5`='英雄，我倍感榮幸。', `FemaleText_loc7`='Es todo un honor.' WHERE `ID`=31391;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이러한 비극적인 사건들을 다음 세대들을 위해 기록해두는 것이 제 의무이지요.', `FemaleText_loc4`='为了后世的幸福，我有责任记录下这些悲剧。', `FemaleText_loc5`='我的職責就是要為了未來的世代記錄這些悲劇。', `FemaleText_loc7`='Mi deber es recoger estos trágicos eventos para el bien de las generaciones venideras.' WHERE `ID`=31392;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정신을 똑똑히 차려야만 하네. 정신을 놓는 순간 우리가 모두 위험에 빠질 수 있네. 아아, 병사들은 리치 왕의 광기에서 벗어나 쉴 수 있는 시간이 필요하다네.$B$B승리를 가져다주게, $n. 자네가 아니라면 우리는 선봉기지를 빼앗겼을 걸세.', `MaleText_loc4`='我们不能放松警惕。在这种时候，一次小小的失利就可能令我们置身于危险中。唉，这种高度紧张的气氛下，士兵们真的需要喘口气了。$B$B享受胜利吧，$n。如果没有你，我们可能已经失去前线基地了。', `MaleText_loc5`='我們絕不能掉以輕心。隨著時間增長的內部危機可能讓我們所有人都身陷險境。唉，士兵們需要暫時從這場瘋狂中清醒一下。$B$B從勝利中獲取一些溫暖，$n。要不是有你，我們可能已經失去先鋒駐地了。', `MaleText_loc7`='No debemos descentrarnos. Si dejamos que la situación nos confunda, podríamos ponernos en peligro. Los soldados necesitan descansar de toda esta locura.$B$BDisfruta de la victoria, $n. De no ser por ti, hubiéramos perdido la Vanguardia.' WHERE `ID`=31393;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='길을 잃으셨다면 제가 당신을 돕겠습니다. 뭘 도와 드릴까요?', `MaleText_loc4`='朋友，如果你迷了路，我或许能帮上忙。你要去哪儿？', `MaleText_loc5`='如果你迷路了，我的朋友，或許我能提供一些幫忙。你需要什麼?', `MaleText_loc7`='Si te has perdido, camarada, a lo mejor puedo ayudarte. ¿Qué necesitas?', `FemaleText_loc1`='길을 잃으셨다면 제가 당신을 돕겠습니다. 뭘 도와 드릴까요?', `FemaleText_loc4`='朋友，如果你迷了路，我或许能帮上忙。你要去哪儿？', `FemaleText_loc5`='如果你迷路了，我的朋友，或許我能提供一些幫忙。你需要什麼?', `FemaleText_loc7`='Si te has perdido, camarada, a lo mejor puedo ayudarte. ¿Qué necesitas?' WHERE `ID`=31394;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 도시는 참 이상한 곳입니다. 그렇지 않습니까? 제가 도와 드릴 일이라도 있습니까?', `MaleText_loc4`='这座城市的确有些古怪。我能帮你什么忙吗？', `MaleText_loc5`='這座城市可能有點奇怪。我能幫你什麼忙嗎?', `MaleText_loc7`='Esta ciudad puede resultar extraña. ¿Puedo hacer algo por ti?', `FemaleText_loc1`='이 도시는 참 이상한 곳입니다. 그렇지 않습니까? 제가 도와 드릴 일이라도 있습니까?', `FemaleText_loc4`='这座城市的确有些古怪。我能帮你什么忙吗？', `FemaleText_loc5`='這座城市可能有點奇怪。我能幫你什麼忙嗎?', `FemaleText_loc7`='Esta ciudad puede resultar extraña. ¿Puedo hacer algo por ti?' WHERE `ID`=31395;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경고: 겨울손아귀 밖에서 작동하도록 허가되지 않은 차량입니다. 즉시 돌아가십시오.', `MaleText_loc4`='警告：禁止将载具开出冬拥湖。请立即返回。', `MaleText_loc5`='警告:這台載具並未獲得在冬握湖以外地區的操作許可。請立刻返回。', `MaleText_loc7`='Advertencia: este vehículo no puede operar fuera de Conquista del Invierno. Vuelve de inmediato.' WHERE `ID`=31396;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고룡족 경비병이 보고합니다!', `MaleText_loc4`='龙群卫士报告！', `MaleText_loc5`='孵育守護者回報了!', `MaleText_loc7`='¡Los Guardias del Linaje van para allá!' WHERE `ID`=31397;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칠흑의 성소 수호자들이 보고합니다!', `MaleText_loc4`='圣殿卫士报告！', `MaleText_loc5`='聖所守護者回報了!', `MaleText_loc7`='¡Los Guardias del Santuario van para allá!' WHERE `ID`=31398;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='드디어 증원군이 왔군요! 경비병들로는 푸른용군단의 침입을 그리 오래 버티지 못합니다! 제 경비병들을 도와 당신이 할 수 있는 한 오래 방어선을 지켜 주셔야겠습니다. 방어 체계에 사용할 수 있는 마력이 좀 남아 있습니다. 상황이 악화되면 요새 주위에 있는 활성화 수정을 사용하여 마력을 유포하십시오.', `FemaleText_loc4`='总算盼来了援军！面对如此大规模的入侵，监狱守卫是坚持不了多久的！请你前去增援我的士兵，尽量为我们争取时间吧。防御系统的能量尚未用尽。如果情况危急的话，务必要激活监狱周围的水晶发射能量波。', `FemaleText_loc5`='援軍終於來了!監獄守衛無法繼續對抗這場入侵太久!你要接替我的手下，並且盡可能地擋住他們。防禦系統中還有一些能量可以使用。如果狀況太惡劣的話，可以使用監獄周圍的啟動水晶來發出一次釋能。', `FemaleText_loc7`='¡Al fin, refuerzos! ¡Los guardias de la prisión no podrán plantar cara a esta invasión mucho más tiempo! Tendrán que relevar a mis hombres e intentar aguantar todo lo que puedan. Aún queda algo de energía disponible en el sistema de defensa. Usen los cristales de activación situados alrededor de la prisión para lanzar una descarga si la situación empeora.' WHERE `ID`=31399;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 임무는 알을 보호하는 것. 알에 손대지 못하게 모두 불태워 주마.', `MaleText_loc4`='我的职责是保护这些龙卵。在伤害到它们之前，你们就会被我的龙息烧成灰烬！', `MaleText_loc5`='我的職責就是要看守這些龍蛋。在他們受到任何傷害之前，我將會看著你陷入火焰之中!', `MaleText_loc7`='Mi tarea es cuidar de estos huevos. ¡Te carbonizaré antes que le causes algún daño!' WHERE `ID`=31400;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='문제가 생기면 바로 수정을 활성화하겠습니다.', `MaleText_loc4`='遇到麻烦时就激活水晶。', `MaleText_loc5`='當情況不妙的時候啟動水晶，沒問題。', `MaleText_loc7`='Activen los cristales cuando nos metamos en líos.', `FemaleText_loc1`='문제가 생기면 바로 수정을 활성화하겠습니다.', `FemaleText_loc4`='遇到麻烦时就激活水晶。', `FemaleText_loc5`='當情況不妙的時候啟動水晶，沒問題。', `FemaleText_loc7`='Activen los cristales cuando nos metamos en líos.' WHERE `ID`=31401;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 황혼의 차원문을 엽니다!', `FemaleText_loc4`='%s开始召唤暮光传送门！', `FemaleText_loc5`='%s開始打開暮光傳送門!', `FemaleText_loc7`='%s comienza a abrir un Portal Crepuscular.' WHERE `ID`=31402;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스가 겨울손아귀 요새를 방어했습니다!', `MaleText_loc4`='联盟守住了冬拥堡垒！', `MaleText_loc5`='聯盟守住了冬握堡壘!', `MaleText_loc7`='¡La Alianza ha defendido la Fortaleza de Conquista del Invierno!' WHERE `ID`=31403;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽고 나면 간단한 셈도 못할 만큼 아무런 능력도 남지 않나 봐요. 당신이 그 구조 배치 작업을 할 수 없다는 사실이 안 보여요? 그렇게 했다간 무너지겠잖아요!', `MaleText_loc4`='你是不是衰老得连基本的算术都不会了。你难道没看出来，建筑物的设计思路根本就有问题吗？照你的方案，它肯定会倒塌！', `MaleText_loc5`='垂死一定完全摧毀了你簡單計算的能力。你難道看不出來無論如何都沒辦法讓這建築繼續運作?它整個塌了!', `MaleText_loc7`='Lo de morir debe de haberte privado de comprender la aritmética más sencilla. ¿No ves que es imposible que funcione ese plano de la estructura? ¡Se vendrá abajo!' WHERE `ID`=31404;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드가 겨울손아귀 요새를 방어했습니다!', `MaleText_loc4`='部落守住了冬拥堡垒！', `MaleText_loc5`='部落守住了冬握堡壘!', `MaleText_loc7`='¡La Horda ha defendido la Fortaleza de Conquista del Invierno!' WHERE `ID`=31405;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 감히! 제가 여기 수석 건축가이고 배치는 제가 마지막으로 결정해요! 제 계획에 이의가 있다면, 폴드링 대영주님께 불만을 제소하세요. 이제 좀 비켜주겠어요? 전 할 일이 있단 말이에요!', `MaleText_loc4`='你说什么！我是这里的总设计师，设计图由我来最终拍板！如果你对此有所置疑的话，尽管向弗丁大领主投诉好了。我要去工作了，恕不奉陪！', `MaleText_loc5`='你好大的膽子!我是這裡的首席建築師，只有我才能決定是否運行!如果你對我的計畫有意見的話，就去找大領主弗丁抱怨。現在如果你沒事的話，我要開始工作了!', `MaleText_loc7`='¡Cómo te atreves! ¡Yo soy aquí el arquitecto jefe y tengo la última palabra sobre los planos! Si tienes algún problema, preséntale una queja al alto señor Vadín. ¡Y ahora, si no te importa, tengo trabajo!' WHERE `ID`=31406;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 아버지 자식 중에 내가 제일 세! 넌 이제 큰일 났다!', `MaleText_loc4`='我是父亲最优秀的儿子！你们的末日来临了！', `MaleText_loc5`='我是父親最優秀的兒子!你們的末日來臨了!', `MaleText_loc7`='¡Soy el mayor de los hijos de mi padre! ¡Te ha llegado el fin!' WHERE `ID`=31407;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='있는 힘껏 쳐 봐라!', `MaleText_loc4`='来呀！出招吧！', `MaleText_loc5`='讓我瞧瞧你可以有多爛!', `MaleText_loc7`='¡Demuestra tu poderío!' WHERE `ID`=31408;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='막아 봐라! 그럴 수 있다면 말이다!', `MaleText_loc4`='接招吧，让你看看我的厉害！', `MaleText_loc5`='乖乖防守吧，這是你唯一能做的!', `MaleText_loc7`='¡Defiéndete, de mucho que te valdrá!' WHERE `ID`=31409;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으아아아! 무쇠와 강철의 분노를 맛보아라!', `MaleText_loc4`='啊啊啊啊啊！见识见识钢与铁的愤怒吧！', `MaleText_loc5`='嘎啊啊啊!見識鐵與鋼的怒火吧!', `MaleText_loc7`='¡GRAAAAAH! ¡Observa la furia de hierro y acero!' WHERE `ID`=31410;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이걸로 저주가 풀렸구나.', `MaleText_loc4`='让我结束你的诅咒吧。', `MaleText_loc5`='讓我結束你的詛咒吧。', `MaleText_loc7`='Así concluye tu maldición.' WHERE `ID`=31411;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살덩이 따위는 약해!', `MaleText_loc4`='血肉……是……脆弱的！', `MaleText_loc5`='血肉...是脆弱的!', `MaleText_loc7`='¡La carne... es... débil!' WHERE `ID`=31412;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='볼빈 움욜 말냐르.', `MaleText_loc4`='Bolvin umyol marnjar。', `MaleText_loc5`='(維酷語)父親會很高興的。', `MaleText_loc7`='Bolvin umyol marnjar.' WHERE `ID`=31413;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭔가 잘못됐어... 살덩이 따위가... 강할 리가...', `MaleText_loc4`='怎么可能……？血肉之躯竟强过了……钢铁！', `MaleText_loc5`='怎麼可能...?血肉之軀竟強過了...鋼鐵!', `MaleText_loc7`='¿Cómo es... posible? ¡La carne no es más... fuerte!' WHERE `ID`=31414;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희가... 내 자식들을 건드렸냐? 가만두지 않겠다!', `MaleText_loc4`='就是你们杀死了我那么的多孩子吗？你们……要付出代价！', `MaleText_loc5`='就是你殺了我的孩子嗎?你要...付出...代價!', `MaleText_loc7`='¿Eres tú quien ha destruido a mis hijos? ¡Me... las... pagarás!' WHERE `ID`=31415;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무에서 생명을... 너희에겐 죽음을!', `MaleText_loc4`='腐化而成的血肉生物……死吧。', `MaleText_loc5`='從無生命中誕生的生命，死吧。', `MaleText_loc7`='Vida surgida de la nada... recibe la muerte.' WHERE `ID`=31416;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 작업에 군더더기란 없다. 보면 알게 되겠지...', `MaleText_loc4`='一切都不会被浪费的。看着吧……', `MaleText_loc5`='一切都不會被浪費的。看著吧...', `MaleText_loc7`='De paso nada se desperdicia. Ya verás…' WHERE `ID`=31417;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 한번 제대로 밟아주마!', `MaleText_loc4`='我要把你们踩在脚下，彻底碾碎！', `MaleText_loc5`='我要把你們踩在腳下，徹底碾碎!', `MaleText_loc7`='¡Te aplastaré como a un gusano!' WHERE `ID`=31418;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='작품이... 덜 됐어!', `MaleText_loc4`='我的工作……还没结束！', `MaleText_loc5`='我的工作...還沒結束!', `MaleText_loc7`='Toda mi labor... ¡arruinada!' WHERE `ID`=31419;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무쇠로 만든 군대가 세상을 정복할 것이다!', `MaleText_loc4`='钢铁的大军将征服一切！', `MaleText_loc5`='鋼鐵大軍將征服一切!', `MaleText_loc7`='¡Los ejércitos de hierro conquistarán todo!' WHERE `ID`=31420;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흥! 형편없구나!', `MaleText_loc4`='呸！可怜虫！', `MaleText_loc5`='呸!可憐蟲!', `MaleText_loc7`='¡Haa! ¡Qué lástima!' WHERE `ID`=31421;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈 때문에... 일이 밀려 버렸다!', `MaleText_loc4`='你们的确让我费了不少力气！', `MaleText_loc5`='你們的確讓我費了不少力氣!', `MaleText_loc7`='¡Me has costado mucho trabajo!' WHERE `ID`=31422;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님이... 걱정했던 대로군...', `MaleText_loc4`='主人……果然……深谋远虑。', `MaleText_loc5`='主人是對的...應該要注意你們的。', `MaleText_loc7`='El amo tenía razón... en preocuparse.' WHERE `ID`=31423;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신과 모험가 친구들은 계속할 준비가 되었나요? 여기 활성화 수정의 마력을 발포하여 제 경비병들의 후퇴 길을 엄호하겠습니다.', `FemaleText_loc4`='你和你的伙伴们都准备好了吗？我会激活水晶，发射能量波，让我的守卫趁机撤退。', `FemaleText_loc5`='你整個隊伍都準備好要繼續了嗎?我會用啟動水晶發出一次釋能，好掩護守衛的撤退。', `FemaleText_loc7`='¿Ya están listos para continuar todos los miembros de tu grupo? Lanzaré una descarga con este cristal de activación para cubrir la retirada de mis guardias.' WHERE `ID`=31424;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋습니다. 여러분이 준비되었다면 이곳을 계속 방어하시도록 물러나겠습니다. 저희가 여기를 떠나 문을 닫을 시간을 벌도록 방어막을 과부하 하여 감옥을 정리하겠습니다. 그 후에 이 문을 지켜내는 일은 전적으로 당신 손에 달렸습니다!', `FemaleText_loc4`='如果你们都准备好了，那么我就开始组织撤退，让你们接手这里的防务。我会采取激进的防御措施，让守卫们安全离开监狱并关上大门。此后，你们要不惜一切代价守住大门！', `FemaleText_loc5`='嗯，如果你的隊伍已經準備好了，那我就要開始撤退讓你們接手這裡的防禦。我會讓防禦超載好讓監獄能夠淨空足夠的時間，好讓我們能夠離開並且關上大門。之後，就得靠你們盡一切的努力來守住這扇大門!', `FemaleText_loc7`='Bien; si tu unidad está lista, yo voy a retirarme y a dejaros al cargo de las defensas. Sobrecargaré las defensas para despejar la prisión el tiempo suficiente con el fin de irnos y cerrar la puerta. ¡Después, en tus manos queda proteger esta puerta a toda costa!' WHERE `ID`=31425;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들을 안전하게 데려오십시오. 우리가 푸른용군단의 군대를 계속 몰아넣겠습니다.', `MaleText_loc4`='让他们放心撤离吧，我们会竭尽全力牵制蓝龙军团的入侵。', `MaleText_loc5`='帶你的人撤到安全的地方去吧，我們不會讓藍龍軍團突破防線的。', `MaleText_loc7`='Pon a salvo a tu gente; nosotros mantendremos a raya a los ejércitos del Vuelo Azul.', `FemaleText_loc1`='저들을 안전하게 데려오십시오. 우리가 푸른용군단의 군대를 계속 몰아넣겠습니다.', `FemaleText_loc4`='让他们放心撤离吧，我们会竭尽全力牵制蓝龙军团的入侵。', `FemaleText_loc5`='帶你的人撤到安全的地方去吧，我們不會讓藍龍軍團突破防線的。', `FemaleText_loc7`='Pon a salvo a tu gente; nosotros mantendremos a raya a los ejércitos del Vuelo Azul.' WHERE `ID`=31426;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 스컬지와 싸웠다. 네깟 것들은 아무것도 아니지!', `MaleText_loc4`='连天灾军团都被我们击败了，你们以为自己能有几分胜算？', `MaleText_loc5`='我們擊退過天譴軍。你覺得你有機會嗎?', `MaleText_loc7`='Combatimos la Plaga. ¿Crees que TÚ tienes algún chance?' WHERE `ID`=31427;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진짜... 커다란 걸... 보여주겠다!', `MaleText_loc4`='来应付更“大”的挑战吧！', `MaleText_loc5`='準備好看看...更...「大」的東西!', `MaleText_loc7`='Prepárate para algo... mucho... ¡MÁS GRANDE!' WHERE `ID`=31428;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='땅이 너희를 삼켜버릴 것이다!', `MaleText_loc4`='大地要将你们吞噬！', `MaleText_loc5`='大地要將你們吞噬!', `MaleText_loc7`='¡Te tragará la tierra!' WHERE `ID`=31429;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바퀴 같은 놈들... 밟아주마!', `MaleText_loc4`='看我踩碎你们这些蟑螂！', `MaleText_loc5`='看我踩碎你們這些蟑螂!', `MaleText_loc7`='¡Los aplasto como cucarachas!' WHERE `ID`=31430;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 날 막겠다고? 네가?', `MaleText_loc4`='谁能阻止我？就凭你？', `MaleText_loc5`='誰能阻止我?就憑你?', `MaleText_loc7`='¿Quién me detendrá? ¿Tú?' WHERE `ID`=31431;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='별것도 아니구나!', `MaleText_loc4`='怎么，这就不行了？', `MaleText_loc5`='怎麼，這就不行了?', `MaleText_loc7`='¡Menos duro ahora!' WHERE `ID`=31432;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신께서도 죽는데... 우리라고 다르겠나...', `MaleText_loc4`='神都会死去……何况我们自身……', `MaleText_loc5`='要是我們的神會死...那我們也會...', `MaleText_loc7`='Si nuestros dioses pueden morir... nosotros también...' WHERE `ID`=31433;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='젊은이, 두려워하지 마라. 이 성전사는 죽음에 처하지 않으리라.', `MaleText_loc4`='年轻人，别害怕，死亡的阴霾不会降临到这位北伐军勇士的头上。', `MaleText_loc5`='不要畏懼，年輕人，這位十字軍將不會嚐到死亡的滋味。', `MaleText_loc7`='No temas, joven, pues este cruzado no probará la muerte.' WHERE `ID`=31434;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='브라이든브래드는 살아서 훌륭한 일을 많이 했노라. 이제, 죽었으니, 오직 안락함만을 누리리라.', `MaleText_loc4`='活着的时候，布雷登布莱德拥有显赫的战绩。死后他的灵魂将升入天堂。', `MaleText_loc5`='活著的時候，布理登布萊特肩負著重大的使命。而今，在死去時，他只會嘗到無盡的喜樂。', `MaleText_loc7`='En vida, Bridenbrad fue artífice de grandes hazañas. Y ahora, al morir, saboreará el único paraíso.' WHERE `ID`=31435;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성스러운 빛은 그 용사를 저버리지 않으리라.', `MaleText_loc4`='圣光不会抛弃它的勇士。', `MaleText_loc5`='聖光並沒有拋棄這位勇士。', `MaleText_loc7`='La luz no abandona a sus campeones.' WHERE `ID`=31436;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 은빛십자군을 위해 하는 일이 그저 의무를 다하는 것으로만 보일 수도 있다. 생각하기에 따라서는 대가를 치른다고도 볼 수 있지. 대영주님께서는 나를 리치 왕의 손아귀에서 구해내고 우리에게 구원의 길을 열어 주셨다. 그렇기에 우리 방식은 다르다는 사실을 인정해야만 한다. 아주 많이 다르지. 나와 칠흑의 기사단은 얼음왕관에서 은빛십자군이 기초를 튼튼히 닦도록 도운 다음, 다른 길로 갈 것이야. 대가는 이미 충분히 치렀다.$B$B다른 운명이 우리를 기다리고 있지.', `MaleText_loc4`='我为银色北伐军所做的一切只是为了履行义务。当然，也算是报恩吧。大领主让我摆脱了巫妖王的控制并为我们指明了救赎之路。我说过，我们做事的方式是有差异的——你必须明白这一点。我和黑锋骑士团会竭尽全力，帮助银色北伐军在冰冠冰川站稳脚跟。在那之后，我们就会离开。我希望能以这样的方式报答大领主的恩情。$B$B等待我们的，将是截然不同的命运。', `MaleText_loc5`='我今天為銀白十字軍所做的事情只不過是完成我應盡的義務。一個報答。大領主將我從巫妖王的掌握中釋放出來，給了我們救贖之道。但要知道我們的行事方法有很大的...不同。我和黯刃騎士團會協助銀白十字軍在寒冰皇冠設立據點，然後我們就會離開。我們的報答完成了。$B$B另一個不同的使命在等著我們。', `MaleText_loc7`='Lo que hago por la Cruzada Argenta no debería considerarse el cumplimiento de una obligación. Más bien un pago, si lo prefieres. El Alto Señor me liberó del Rey Exánime y puso ante nosotros el sendero a la salvación. Dicho esto, hay que reconocer que nuestros métodos difieren... enormemente. Los Caballeros de la Espada de Ébano y yo ayudaremos a la Cruzada Argenta a sentar las bases en Corona de Hielo y luego separaremos nuestros caminos. Así, el pago quedará satisfecho.$B$BA nosotros nos aguarda otro destino.' WHERE `ID`=31437;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 성전사들 때문에 여러 가지로 곤란한 일을 겪는다는 것이야 말할 필요도 없다. 하지만, 고통이 따르지 않는 희생이 있을까? 너는 희망의 빛 예배당에서 나와 함께했었지. 그곳에서 어마어마한 희생이 치러지는 것을 보았겠지. 우리는 이제 여기서 대영주님께 빚을 갚으려 한다. 대영주님께서 치르신 희생에 대한 대가를 말이다.$B$B은빛십자군이 얼음왕관의 벽 안에 확고한 근거지를 세우고 나면, 우리는 떠나리라. 다른 운명이 우리 앞에 놓여 있으니 말이다.', `MaleText_loc4`='毫无疑问，和这些北伐军将士相处起来别提有多别扭了。但是不承担痛苦的话，算什么牺牲呢？你曾经与我共同经历了圣光之愿礼拜堂一战，目睹过许多伟大的牺牲。我们是来这里报答大领主的，报答他所做出的牺牲。$B$B一旦银色北伐军在冰冠冰川的高墙内站稳脚跟，我们就会离开。等待我们的，将是截然不同的命运。', `MaleText_loc5`='毫無疑問那些十字軍是巨大不安的來源，$g兄弟:姊妹;。但有犧牲是沒有痛苦嗎?我們當時都在聖光之願禮拜堂。你親眼目睹許多偉大的犧牲。我們在此是要償還大領主的恩情。報答他的犧牲。$B$B一旦銀白十字軍在寒冰皇冠的高牆內建立了他們的堡壘，我們就會離開。另一個不同的使命在等著我們。', `MaleText_loc7`='No cabe duda de que esos cruzados están causando muchos quebraderos de cabeza, $g hermano:hermana;. Pero ¿qué es el sacrificio sin dolor? Tú estuviste conmigo en la Capilla de la Esperanza de la Luz. Viste muchos sacrificios. Y ahora, tenemos que pagar nuestra deuda con el Alto Señor. Pagarle por su sacrificio.$B$BCuando la Cruzada Argenta haya establecido un punto de apoyo dentro de las murallas de Corona de Hielo, partiremos. A nosotros nos aguarda otro destino.' WHERE `ID`=31438;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='번개의 전당은 폭풍우 봉우리 안에 있는 80 레벨 던전으로 지금 시험해볼 수 있습니다. 던전 안으로 순간이동하기 전에 파티를 맺은 상태여야 합니다. 만남의 돌은 아직 사용할 수 없습니다. 번개의 전당에서 나오려면, 던전 안에 있는 입구로 빠져나오면 됩니다. 그러면 바로 여기로 돌아오지요. 죽어서 영혼이 빠져나갔다면 다시 NPC와 얘기하여 순간이동해야 합니다.', `MaleText_loc4`='位于风暴峭壁的80级地下城闪电大厅已开放测试。请在进入地下城之前组满队伍。该地下城的集合石尚未开放。

您只要通过从地下城的常规出口，就能离开闪电大厅，返回这里。如果您的角色死亡并选择了释放，您可从该NPC处传送回去。', `MaleText_loc5`='The Halls of Lightning, a level 80 dungeon within Storm Peaks, is now available for testing. Please be in your full group before teleporting to the dungeon. Meeting Stones are not available for this dungeon yet.

To leave the Halls of Lightning, simply exit through the normal exit inside the dungeon and you will be returned here. If you die and release, you should teleport back from this NPC.', `MaleText_loc7`='Las Cámaras de los Relámpagos, una mazmorra de nivel 80 en las Cumbres Tormentosas, ya está disponible para pruebas. El grupo tiene que estar completo para el teletransporte a la mazmorra. Aún no hay rocas de encuentro disponibles para esta mazmorra.
Para salir de las Cámaras de los Relámpagos, basta con salir por la salida normal que hay dentro de la mazmorra y volverás a este lugar. Si mueres y liberas tu espíritu, tienes que volver a teletransportarte desde este PNJ.' WHERE `ID`=31439;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저와 파티원 모두 준비되었습니다. 번개의 전당으로 순간이동시켜 주십시오!', `MaleText_loc4`='我已经组好队伍，准备进入闪电大厅了！', `MaleText_loc5`='我在隊伍之中並且準備好傳送至雷光大廳!', `MaleText_loc7`='¡Estoy con mi grupo y quiero teletransportarme a las Cámaras de los Relámpagos!', `FemaleText_loc1`='저와 파티원 모두 준비되었습니다. 번개의 전당으로 순간이동시켜 주십시오!', `FemaleText_loc4`='我已经组好队伍，准备进入闪电大厅了！', `FemaleText_loc5`='我在隊伍之中並且準備好傳送至雷光大廳!', `FemaleText_loc7`='¡Estoy con mi grupo y quiero teletransportarme a las Cámaras de los Relámpagos!' WHERE `ID`=31440;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='번개의 전당으로 저를 다시 데려다 주십시오!', `MaleText_loc4`='我要返回闪电大厅！', `MaleText_loc5`='讓我回到雷光大廳!', `MaleText_loc7`='¡Quiero volver a las Cámaras de los Relámpagos!', `FemaleText_loc1`='번개의 전당으로 저를 다시 데려다 주십시오!', `FemaleText_loc4`='我要返回闪电大厅！', `FemaleText_loc5`='讓我回到雷光大廳!', `FemaleText_loc7`='¡Quiero volver a las Cámaras de los Relámpagos!' WHERE `ID`=31441;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시험 중', `MaleText_loc4`='测试', `MaleText_loc5`='Test', `MaleText_loc7`='Prueba' WHERE `ID`=31442;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='첫 페이지', `MaleText_loc4`='第1篇', `MaleText_loc5`='條目1', `MaleText_loc7`='Entrada 1', `FemaleText_loc1`='첫 페이지', `FemaleText_loc4`='第1篇', `FemaleText_loc5`='條目1', `FemaleText_loc7`='Entrada 1' WHERE `ID`=31443;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='먼저 내 이름은 대마법사 바르고스이며, 키린 토의 1차 드레노어 원정을 이끌고 있음을 밝힌다. 우리는 얼라이언스 부대와 함께 어둠의 문을 지나, 선대 웃는 해골 부족의 고향 근처에 있는 파랄론의 키린바르 마을에 주둔지를 마련했다. 이곳은 정말 훌륭한 장소이다.', `MaleText_loc4`='先做个自我介绍吧。我名叫大法师瓦格斯，是首批进驻德拉诺的肯瑞托远征队的队长。我们和联盟的军队一起跨越了黑暗之门，如今，我们在法兰伦建立起了一座名叫肯瑞瓦村的营地，就在嘲颅兽人氏族的家乡附近。真是个美好的地方！', `MaleText_loc5`='首先自我介紹。我是大法師瓦戈斯，祈倫托派往德拉諾的第一支探險隊領隊。我們跟著聯盟部隊一起穿過黑暗之門，然後將營地設立在法拉隆的肯瑞瓦村莊，靠近獸人獰笑骷髏氏族的故鄉。多麼美好的一個地方!', `MaleText_loc7`='Antes de nada, me presento. Soy el archimago Vargoth, líder de la primera expedición a Draenor del Kirin Tor. Hemos atravesado con las fuerzas de la Alianza el Portal Oscuro y, ahora, hemos establecido el campamento base en el pueblo de Kirin’Var. Está en Farahlon, cerca del ancestral hogar del clan orco de los Riecráneos. ¡Un lugar maravilloso!', `FemaleText_loc1`='먼저 내 이름은 대마법사 바르고스이며, 키린 토의 1차 드레노어 원정을 이끌고 있음을 밝힌다. 우리는 얼라이언스 부대와 함께 어둠의 문을 지나, 선대 웃는 해골 부족의 고향 근처에 있는 파랄론의 키린바르 마을에 주둔지를 마련했다. 이곳은 정말 훌륭한 장소이다.', `FemaleText_loc4`='先做个自我介绍吧。我名叫大法师瓦格斯，是首批进驻德拉诺的肯瑞托远征队的队长。我们和联盟的军队一起跨越了黑暗之门，如今，我们在法兰伦建立起了一座名叫肯瑞瓦村的营地，就在嘲颅兽人氏族的家乡附近。真是个美好的地方！', `FemaleText_loc5`='首先自我介紹。我是大法師瓦戈斯，祈倫托派往德拉諾的第一支探險隊領隊。我們跟著聯盟部隊一起穿過黑暗之門，然後將營地設立在法拉隆的肯瑞瓦村莊，靠近獸人獰笑骷髏氏族的故鄉。多麼美好的一個地方!', `FemaleText_loc7`='Antes de nada, me presento. Soy el archimago Vargoth, líder de la primera expedición a Draenor del Kirin Tor. Hemos atravesado con las fuerzas de la Alianza el Portal Oscuro y, ahora, hemos establecido el campamento base en el pueblo de Kirin’Var. Está en Farahlon, cerca del ancestral hogar del clan orco de los Riecráneos. ¡Un lugar maravilloso!' WHERE `ID`=31444;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<이 먼지투성이 일지엔 여러 페이지가 사라지고 없습니다.>', `MaleText_loc4`='<这本布满灰尘的日记缺了好几篇>', `MaleText_loc5`='<這本沾滿灰塵的日誌中間漏失了許多條>', `MaleText_loc7`='<Al diario polvoriento le faltan varias entradas>', `FemaleText_loc1`='<이 먼지투성이 일지엔 여러 페이지가 사라지고 없습니다.>', `FemaleText_loc4`='<这本布满灰尘的日记缺了好几篇>', `FemaleText_loc5`='<這本沾滿灰塵的日誌中間漏失了許多條>', `FemaleText_loc7`='<Al diario polvoriento le faltan varias entradas>' WHERE `ID`=31445;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님.', `MaleText_loc4`='尊贵的主人。', `MaleText_loc5`='我的女士。', `MaleText_loc7`='Mi señora.' WHERE `ID`=31446;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기가 어디지? 나... 너희... 밟아주마!', `MaleText_loc4`='这……是哪里？我……我要……消灭你们！', `MaleText_loc5`='這是什麼地方?我要摧毀你!', `MaleText_loc7`='¿Qué... este lugar? ¡Los... destruiré!' WHERE `ID`=31447;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='42 페이지', `MaleText_loc4`='第42篇', `MaleText_loc5`='條目42', `MaleText_loc7`='Entrada 42', `FemaleText_loc1`='42 페이지', `FemaleText_loc4`='第42篇', `FemaleText_loc5`='條目42', `FemaleText_loc7`='Entrada 42' WHERE `ID`=31448;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지맥 발굴을 계속하면서 만족스러운 결과를 얻었다. 아제로스와 드레노어의 지맥이 일부 유사한 구조를 보인다는 사실에 매우 놀라지 않을 수 없었다. 설마 태초의 기원 역시 유사한 것은 아닐까?
절친한 동료 나베리우스는 웃는 해골 부족이 여기서 얼라이언스 부대와 휴전 협정을 맺었다고 한다. 오크 녀석들은 믿을 수 없다. 이곳은 천국이 될 수도, 지옥이 될 수도 있다는 생각이 들었다.', `MaleText_loc4`='能量线的挖掘工作仍在继续，成果喜人。我们惊讶地发现，艾泽拉斯和德拉诺的能量线在结构上存在相似之处，会不会是因为两者有着相似的起源呢？
我的挚友纳比留斯报告说，嘲颅氏族已经与联盟达成了休战协议。我向来是不信任兽人的，这消息真不知道是喜是忧啊。', `MaleText_loc5`='地脈的挖掘在持續進行，成果相當令人振奮。我們發覺艾澤拉斯與德拉諾的地脈結構有許多相似之處，說不定還有著類似的起源?
我的助手納伯瑞厄斯回報說獰笑骷髏與聯盟部隊定下了停戰協議。獸人總是讓人無法信任，我這麼想，「這裡不是天堂就會是地獄。」', `MaleText_loc7`='"Las excavaciones de las líneas-Ley continúan, con resultados satisfactorios. Nos sorprendió encontrar varias similitudes en las estructuras de la línea-Ley entre Azeroth y Draenor; posiblemente indiquen una génesis similar.
Mi socio Naberius me ha informado de que los Riecráneos han pactado una tregua con las fuerzas de la Alianza en la zona. "No hay que fiarse de los orcos", pensé yo. "Esto podría ser el paraíso o el infierno."', `FemaleText_loc1`='지맥 발굴을 계속하면서 만족스러운 결과를 얻었다. 아제로스와 드레노어의 지맥이 일부 유사한 구조를 보인다는 사실에 매우 놀라지 않을 수 없었다. 설마 태초의 기원 역시 유사한 것은 아닐까?
절친한 동료 나베리우스는 웃는 해골 부족이 여기서 얼라이언스 부대와 휴전 협정을 맺었다고 한다. 오크 녀석들은 믿을 수 없다. 이곳은 천국이 될 수도, 지옥이 될 수도 있다는 생각이 들었다.', `FemaleText_loc4`='能量线的挖掘工作仍在继续，成果喜人。我们惊讶地发现，艾泽拉斯和德拉诺的能量线在结构上存在相似之处，会不会是因为两者有着相似的起源呢？
我的挚友纳比留斯报告说，嘲颅氏族已经与联盟达成了休战协议。我向来是不信任兽人的，这消息真不知道是喜是忧啊。', `FemaleText_loc5`='地脈的挖掘在持續進行，成果相當令人振奮。我們發覺艾澤拉斯與德拉諾的地脈結構有許多相似之處，說不定還有著類似的起源?
我的助手納伯瑞厄斯回報說獰笑骷髏與聯盟部隊定下了停戰協議。獸人總是讓人無法信任，我這麼想，「這裡不是天堂就會是地獄。」', `FemaleText_loc7`='"Las excavaciones de las líneas-Ley continúan, con resultados satisfactorios. Nos sorprendió encontrar varias similitudes en las estructuras de la línea-Ley entre Azeroth y Draenor; posiblemente indiquen una génesis similar.
Mi socio Naberius me ha informado de que los Riecráneos han pactado una tregua con las fuerzas de la Alianza en la zona. "No hay que fiarse de los orcos", pensé yo. "Esto podría ser el paraíso o el infierno."' WHERE `ID`=31449;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='205 페이지', `MaleText_loc4`='第205篇', `MaleText_loc5`='條目205', `MaleText_loc7`='Entrada 205', `FemaleText_loc1`='205 페이지', `FemaleText_loc4`='第205篇', `FemaleText_loc5`='條目205', `FemaleText_loc7`='Entrada 205' WHERE `ID`=31450;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스 부대는 대부분 아제로스로 떠났다. 다행히도 정성스럽게 보고서를 정리하여 투랄리온 장군 편에 보냈으니, 달라란에 안전하게 도착할 수 있을 것이다.
파랄론은 넬쥴이 무모하게 생성한 차원문으로 인해 분열되었고, 뒤틀린 황천이 대지를 어지럽히자 푸른 언덕이 순식간에 무너져내렸다. 다시 예전으로 돌아갈 방법을 찾아야 한다!', `MaleText_loc4`='联盟的军队大多已经启程前往艾泽拉斯。希望图拉扬将军能将我们仔细撰写的报告安全地送回达拉然。
耐奥祖不计后果地开启了传送门，强大的能量撕碎了法兰伦。在扭曲虚空的侵蚀下，这片青翠的山岭迅速沦为了废墟。我必须想办法回去！', `MaleText_loc5`='大多數的聯盟部隊都留在艾澤拉斯。希望我們仔細收集的報告能透過圖拉揚將軍安全地送抵達拉然。
耐祖奧魯莽的傳送門正在把法拉隆的土地扯裂，綠色的小丘現在很快地毀滅，扭曲虛空一點一點地腐化著大地。我得找到一條路回到我原本的地方!', `MaleText_loc7`='Casi todas las fuerzas de la Alianza han abandonado Azeroth. Esperemos que los minuciosos informes que enviamos al general Turalyon vuelvan a Dalaran sanos y salvos.
Los peligrosos portales de Ner’zhul han dividido Farahlon; sus verdes colinas se vienen abajo con la misma rapidez que El Vacío Abisal corrompe la tierra. ¡Tengo que encontrar un camino al lugar donde estaba antes!', `FemaleText_loc1`='얼라이언스 부대는 대부분 아제로스로 떠났다. 다행히도 정성스럽게 보고서를 정리하여 투랄리온 장군 편에 보냈으니, 달라란에 안전하게 도착할 수 있을 것이다.
파랄론은 넬쥴이 무모하게 생성한 차원문으로 인해 분열되었고, 뒤틀린 황천이 대지를 어지럽히자 푸른 언덕이 순식간에 무너져내렸다. 다시 예전으로 돌아갈 방법을 찾아야 한다!', `FemaleText_loc4`='联盟的军队大多已经启程前往艾泽拉斯。希望图拉扬将军能将我们仔细撰写的报告安全地送回达拉然。
耐奥祖不计后果地开启了传送门，强大的能量撕碎了法兰伦。在扭曲虚空的侵蚀下，这片青翠的山岭迅速沦为了废墟。我必须想办法回去！', `FemaleText_loc5`='大多數的聯盟部隊都留在艾澤拉斯。希望我們仔細收集的報告能透過圖拉揚將軍安全地送抵達拉然。
耐祖奧魯莽的傳送門正在把法拉隆的土地扯裂，綠色的小丘現在很快地毀滅，扭曲虛空一點一點地腐化著大地。我得找到一條路回到我原本的地方!', `FemaleText_loc7`='Casi todas las fuerzas de la Alianza han abandonado Azeroth. Esperemos que los minuciosos informes que enviamos al general Turalyon vuelvan a Dalaran sanos y salvos.
Los peligrosos portales de Ner’zhul han dividido Farahlon; sus verdes colinas se vienen abajo con la misma rapidez que El Vacío Abisal corrompe la tierra. ¡Tengo que encontrar un camino al lugar donde estaba antes!' WHERE `ID`=31451;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너 죽어라! 주인님께서 원하신다.', `MaleText_loc4`='你去死吧！这是主人的命令。', `MaleText_loc5`='死吧!這是主人的旨意。', `MaleText_loc7`='¡Muere! Eso quiere el amo.' WHERE `ID`=31452;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쉬운 일이지!', `MaleText_loc4`='真是简单的工作！', `MaleText_loc5`='輕鬆的任務!', `MaleText_loc7`='¡Pan comido!' WHERE `ID`=31453;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='웬 놈들이 감히 여길? 정신 차려라, 형제들아! 녀석들을 처치하면 거하게 한 상 차려 주마!', `MaleText_loc4`='什么样的狗杂种竟然胆敢入侵这里？快点，弟兄们！谁要是能把他们的头提来，就赏他吃肉！', `MaleText_loc5`='哪來的蠢狗敢入侵此地?打起精神來，我的兄弟們!誰能把他們的頭顱帶來，我會好好的犒賞一番!', `MaleText_loc7`='¿Qué bastardos se atreven a entrar? ¡Adelante, hermanos! ¡Un banquete para el que me traiga sus cabezas!' WHERE `ID`=31454;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음 그 자체에 도전하겠다는 건가! 그렇다면 와라. 모그레인의 힘을 보여주마!', `MaleText_loc4`='你想要挑战死亡本身吗？来吧，“王”。面对莫格莱尼的怒火！', `MaleText_loc5`='你在挑戰死神!來吧，『王』。面對莫格萊尼的力量!', `MaleText_loc7`='¡Desafías a la propia muerte! Si así lo quieres, acércate, "rey". ¡Enfréntate al poder de Mograine!' WHERE `ID`=31455;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='메아리 골짜기에서 보자. 고생해라, 동지.', `MaleText_loc4`='我会在回音谷等你。朋友，坚持住。', `MaleText_loc5`='到回聲山谷再見。苦難與你同在，盟友。', `MaleText_loc7`='Volveremos a vernos en el Valle de los Ecos. Sobreponte al sufrimiento, aliado.' WHERE `ID`=31456;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='브리쿨 전사를 불렀는데, 웬 코흘리개들만 싸우러 오느냐! 이미론의 이름으로, 저들을 처치해라!', `MaleText_loc4`='我命令维库人去杀掉他们，结果却只能依靠这条没用的龙！以伊米隆的名义，干掉他们！', `MaleText_loc5`='我要維酷人殺死他們，但我卻只得到這些衰弱的小龍!以依米倫之名，殺光他們!', `MaleText_loc7`='¡Pido vrykuls para matarlos, y sólo consigo alfeñiques! ¡Por Ymiron, MÁTENLOS!' WHERE `ID`=31457;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 번만 더 내 비룡에게 작살을 던졌다간 뼈도 못 추릴 줄 알아라!', `MaleText_loc4`='要是再让我的飞龙被鱼叉碰到一下，我就亲自跳下来剥了你们的皮！', `MaleText_loc5`='如果再有一支魚叉碰到我的龍，我會把你們可悲的皮全給扒下來!', `MaleText_loc7`='¡Si un arpón más toca mi draco, azotaré sus miserables pellejos!' WHERE `ID`=31458;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피도 눈물도 없는 것들아! 불쌍한 비룡을 괴롭히다니, 가만두지 않겠다!', `MaleText_loc4`='你这只无能的蠢龙！你的尸体干脆给我的新飞龙拿去当点心算了！', `MaleText_loc5`='你們這些沒教養的垃圾!你們的屍體剛好拿來當龍的點心!', `MaleText_loc7`='¡Miserables granujas! ¡Alimentaré a mi nuevo draco con sus cadáveres!' WHERE `ID`=31459;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뮬 나 울 크발!', `MaleText_loc4`='Mjor na uul kval！', `MaleText_loc5`='(維酷語)這一下是為了我的龍!', `MaleText_loc7`='¡Mjor na uul kval!' WHERE `ID`=31460;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이젠 겁이 좀 나나 보군...', `MaleText_loc4`='你现在怎么不那么嚣张了啊？', `MaleText_loc5`='現在沒這麼無禮了，對吧?', `MaleText_loc7`='¿Ya no eres tan osado, eh?' WHERE `ID`=31461;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='첨탑 꼭대기에 매달아 주마!', `MaleText_loc4`='我要让你尝尝我的厉害！', `MaleText_loc5`='我要把你的頭骨擺到最高的塔頂!', `MaleText_loc7`='¡Colgaré tu cráneo de la torre más alta!' WHERE `ID`=31462;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으아아! 그딴 걸... 공격이라고... 내가 제대로... 으아아아...', `MaleText_loc4`='啊啊！这也能叫……攻击？我要……让你们……见识见识……啊啊啊……', `MaleText_loc5`='啊啊!你把這叫做...攻擊?我會讓你...瞧瞧...啊...', `MaleText_loc7`='¡ARGH! ¿A eso le llamas… un ataque? Te…  mostraré… aghhhh…' WHERE `ID`=31463;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 내 문간을 더럽히고, 내게 도전을 했겠다? 네놈들의 몸뚱이를 손아귀에 넣어, 죽음의 신께 제물로 바칠 것이다! 루알 냐 가볼!', `MaleText_loc4`='你们不仅侵入我的家园，还有胆来挑战我？我要把你们的徽记拿来作为礼物献祭给伟大的死神！Rualg nja gaborr！', `MaleText_loc5`='你們不僅入侵我的家園，還膽敢挑戰我?我要把你們的心臟從胸膛挖出來獻給死亡之神!(維酷語)站好受死吧!', `MaleText_loc7`='¿Invaden mi hogar y encima osan desafiarme? ¡Les arrancaré los corazones y los ofrendaré al dios de la Muerte! ¡Rualg nja gaborr!' WHERE `ID`=31464;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은 폭풍의 비요른이여! 그대의 존재로 저를 축복하소서!', `MaleText_loc4`='黑色风暴之王布约恩！应我的召唤前来协助我！', `MaleText_loc5`='黑色風暴之王畢雍!賜我榮耀!降臨吧!', `MaleText_loc7`='¡Bjorn de la Tormenta Negra! ¡Hónrame con tu presencia!' WHERE `ID`=31465;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바위투성이 절벽의 할도르여! 제게 힘을 내려 주소서!', `MaleText_loc4`='岩石峭壁之王赫尔多！把你的力量借给我！', `MaleText_loc5`='巨岩絕壁之王海多爾!賜給我你的力量!', `MaleText_loc7`='¡Haldor del Acantilado Rocoso! ¡Concédeme tu fuerza!' WHERE `ID`=31466;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='울부짖는 심연의 라눌프여! 칠흑 같은 어둠으로 적을 덮으소서!', `MaleText_loc4`='恐怖深渊之王拉努夫！以漆黑的深夜吞噬这群蝼蚁！', `MaleText_loc5`='尖嘯淵獄之王拉努夫!以最深幽的暗夜扼殺這些蛆蟲吧!', `MaleText_loc7`='¡Ranulf del Abismo del Grito! ¡Envuelve estos gusanos en oscuridad!' WHERE `ID`=31467;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잔혹한 전쟁터의 토르여! 당신의 권능을 보여 주소서!', `MaleText_loc4`='野蛮杀戮之王托尔，将你的威能赐予我！', `MaleText_loc5`='殘暴屠殺之王托爾，賜予我你的神力!', `MaleText_loc7`='¡Tor del Asedio Brutal! ¡Confiéreme tu poder!' WHERE `ID`=31468;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 죽음은 시작에 불과하다.', `MaleText_loc4`='你的死亡仅仅是个开始！', `MaleText_loc5`='你的死亡不過是個開端。', `MaleText_loc7`='Tu muerte es sólo el comienzo.' WHERE `ID`=31469;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동료를 실망시키고 말았구나!', `MaleText_loc4`='你让你的人民失望了！', `MaleText_loc5`='你讓你的人民失望了!', `MaleText_loc7`='¡Le fallaste a tu gente!' WHERE `ID`=31470;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 왕인 데는, 그만한 이유가 있지!', `MaleText_loc4`='这就是我能加冕为王的理由！', `MaleText_loc5`='我這個王不是當假的!', `MaleText_loc7`='¡Por algo soy el rey!' WHERE `ID`=31471;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='숨을 멈춰라!', `MaleText_loc4`='就此咽气吧！', `MaleText_loc5`='停止呼吸吧!', `MaleText_loc7`='¡Muere!' WHERE `ID`=31472;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 무엇이... 날... 기다릴꼬...', `MaleText_loc4`='又……又有什么……在等着我呢？', `MaleText_loc5`='又...又有什麼...在等著我呢?', `MaleText_loc7`='¿Qué... me espera... ahora?' WHERE `ID`=31473;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='요새 경비병들이여, 이제 이곳을 떠난다! 여기 모험가들이 맡아 줄 테니 어서 후퇴하라!', `FemaleText_loc4`='监狱守卫们，准备撤退了！这些冒险者将接管这里的防御事务！迅速撤离！', `FemaleText_loc5`='監獄守衛，我們要離開了!這些冒險者會接手!動作快!', `FemaleText_loc7`='¡Guardias de la prisión, nos largamos! ¡Esos aventureros están dominando el cotarro! ¡Vamos, vamos!' WHERE `ID`=31474;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='문을 잠그겠습니다. 행운을 빌지요. 그리고 고맙습니다.', `FemaleText_loc4`='我要锁上大门了。祝你们好运，感谢你们的帮助。', `FemaleText_loc5`='我要把大門鎖上了。祝你們好運，感謝你們所做的。', `FemaleText_loc7`='Ahora voy a cerrar la puerta. Buena suerte y gracias por hacer esto.' WHERE `ID`=31475;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요툰하임에서 소식이 들어왔습니다. 수면의 감시자들이 상당히 중요한 인물을 발견한 모양입니다.', `MaleText_loc4`='尤顿海姆传来消息，据说那里的沉睡卫士发现了一位重要人物。', `MaleText_loc5`='從卓頓海姆來了一些消息。他們似乎發現了一位重要的沉睡看守者。', `MaleText_loc7`='Hay noticias de Jotunheim. Los vigías del sueño de esa zona creen que han encontrado algo importante.' WHERE `ID`=31476;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이교도가 정신없이 말을 쏟아냅니다.', `MaleText_loc4`='教徒激动得语无伦次。', `MaleText_loc5`='教徒顯得有些結巴。', `MaleText_loc7`='El cultor está que echa chispas.' WHERE `ID`=31477;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생김새요? 글쎄요, 브리쿨처럼 보이던데요. 저도 아직 본 적은 없어서요. 어둠의 무기고 때 이후로 통...', `MaleText_loc4`='模样？他就是个维库人。呃，其实我并没有见过他本人。自从暗影拱顶……', `MaleText_loc5`='看來，我的女士?我猜是一個維酷人。他們並沒有讓我看見。自從暗影穹殿...', `MaleText_loc7`='¿Cómo, mi señora? Un vrykul, supongo. A mí no me lo mostraron. Desde La Cámara de las Sombras...' WHERE `ID`=31478;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이름이요? 아, 맞다. 그 이름이... 이스칼더였던 것 같은데요.', `MaleText_loc4`='名字？对，他的名字！我记得是叫伊斯卡德尔。', `MaleText_loc5`='名字?喔，是，名字!我相信是叫伊斯卡德。', `MaleText_loc7`='¿Un nombre? ¡Ah, claro, su nombre! Creo que se llamaba Iskalder.' WHERE `ID`=31479;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쏜살처럼 다녀오겠습니다, 주인님.', `MaleText_loc4`='遵命，主人。', `MaleText_loc5`='馬上辦，我的女士。', `MaleText_loc7`='Enseguida, mi señora.' WHERE `ID`=31480;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='보고하거라.', `FemaleText_loc4`='汇报情况吧。', `FemaleText_loc5`='說。', `FemaleText_loc7`='Informa.' WHERE `ID`=31481;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좀 더 자세히 설명해 보아라. 어떻게 생겼지?', `FemaleText_loc4`='描述一下这名维库人吧。他长什么模样？', `FemaleText_loc5`='描述這個維酷人。他看起來什麼模樣?', `FemaleText_loc7`='Describe a ese vrykul. ¿Qué aspecto tenía?' WHERE `ID`=31482;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='변명은 여전하구나. 그나저나 이름은 알아 왔겠지?', `FemaleText_loc4`='我没兴趣听你找借口。他们总该告诉过你他的名字吧。', `FemaleText_loc5`='我沒興趣聽藉口。他們有告訴你名字嗎?', `FemaleText_loc7`='No me interesan las excusas. ¿Te dieron un nombre?' WHERE `ID`=31483;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이스칼더?! 이 멍청한 녀석! 그분이 누구신지 모른단 말이냐? 이스칼더 님은 브리쿨을 통틀어 가장 위대한 전사가 아니시더냐!', `FemaleText_loc4`='伊斯卡德尔？！蠢货！你没听过他的名头吗？他是有史以来最伟大的维库人战士！', `FemaleText_loc5`='伊斯卡德?!你這個蠢貨!你不知道他是誰嗎?他是史上最強大的維酷戰士!', `FemaleText_loc7`='¡¿Iskalder?! ¡Necio! ¿Es que no sabes quién es? ¡Es el guerrero vrykul más ilustre de la historia!' WHERE `ID`=31484;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='요툰하임으로 돌아가 전해라. 내가 도착할 때까지 그분을 깨우지 말라고.내 눈으로 직접 확인해 봐야겠다.', `FemaleText_loc4`='立即返回尤顿海姆，告诉他们，在我抵达之前不准让他苏醒过来。我要亲眼看看这个维库人。', `FemaleText_loc5`='回去卓頓海姆，告訴他們讓他持續沉睡直到我回來。我要親自看看這個維酷人。', `FemaleText_loc7`='Vuelve a Jotunheim y diles que lo mantengan dormido hasta que yo llegue. Juzgaré a ese vrykul con mis propios ojos.' WHERE `ID`=31485;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 작은 친구에게 인사해라!', `MaleText_loc4`='来，和我的小伙伴打声招呼吧！', `MaleText_loc5`='向我的小朋友問聲好!', `MaleText_loc7`='¡Di hola a mi camarada!' WHERE `ID`=31486;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일어나라, 말랑아!', `MaleText_loc4`='现身吧，熔尸！', `MaleText_loc5`='起來，邁爾特!', `MaleText_loc7`='¡En pie y largo!' WHERE `ID`=31487;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 일은 다 끝났으니, 가보겠다.', `MaleText_loc4`='这里没我们的事了。我走了。', `MaleText_loc5`='我們結束了。我要離開了。', `MaleText_loc7`='Hemos acabado aquí. Me voy.' WHERE `ID`=31488;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그까짓 전투 하나 제대로 해결 못 하십니까? 좋습니다. 그렇다면...', `FemaleText_loc4`='连这样的场面都应付不了，你还真够弱的。好吧……', `FemaleText_loc5`='虛弱到無法結束自己的戰鬥?很好...', `FemaleText_loc7`='¿Te faltan fuerzas para acabar tus propias batallas? Pues muy bien...' WHERE `ID`=31489;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='떠나기 전에 뭐 도와드릴 일 있습니까? 그렇죠, 없을 줄 알았습니다...', `FemaleText_loc4`='在我离开之前，你还需要什么帮助吗？好吧，我不认为……', `FemaleText_loc5`='在我走之前你還需要任何協助嗎?對，我想不...', `FemaleText_loc7`='¿Puedo ayudarte en algo más antes de irme? Ya, eso pensaba yo...' WHERE `ID`=31490;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='눈 속 깊은 곳에 고대의 마법이 소용돌이치고 있습니다. 마치 그 눈 속으로 한없이 빠져드는 듯 현기증을 느낍니다.', `MaleText_loc4`='远古的魔法在眼睛深处旋转，令你感到一阵眩晕，仿佛自己被吸入了虹膜之中并永远地陷落了。', `MaleText_loc5`='遠古魔法在永恆之眼深處盤繞。給你一種暈眩的感覺，彷彿你會不小心跌進它的虹膜，然後永遠墜落。', `MaleText_loc7`='En el interior del ojo se agita una magia ancestral. Da sensación de vértigo, como si pudieras caerte en el iris por accidente para no regresar.' WHERE `ID`=31491;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕의 눈을 잡고, 정신을 그 눈에 집중하여 중요한 정보를 점치십시오.', `MaleText_loc4`='紧握巫妖王之眼并集中你的意志，以此获取重要的信息。', `MaleText_loc5`='掌握巫妖王之眼，將你的意志集中在上頭，搜尋重要的資訊。', `MaleText_loc7`='Coge el ojo del Rey Exánime y centra tu voluntad en él para averiguar información importante.', `FemaleText_loc1`='리치 왕의 눈을 잡고, 정신을 그 눈에 집중하여 중요한 정보를 점치십시오.', `FemaleText_loc4`='紧握巫妖王之眼并集中你的意志，以此获取重要的信息。', `FemaleText_loc5`='掌握巫妖王之眼，將你的意志集中在上頭，搜尋重要的資訊。', `FemaleText_loc7`='Coge el ojo del Rey Exánime y centra tu voluntad en él para averiguar información importante.' WHERE `ID`=31492;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼음왕관에서 벌어지는 여러 대수롭지 않은 일들을 점치던 중, 무언가 흥미로운 것을 발견합니다...', `MaleText_loc4`='你观察着貌似平静的冰冠冰川，突然发现了有趣的景象……', `MaleText_loc5`='在觀察了寒冰皇冠內許多不重要的情報之後，你突然注意到一件有趣的事情...', `MaleText_loc7`='Vislumbrando muchas situaciones insignificantes en Corona de Hielo, te topas con algo interesante...', `FemaleText_loc1`='얼음왕관에서 벌어지는 여러 대수롭지 않은 일들을 점치던 중, 무언가 흥미로운 것을 발견합니다...', `FemaleText_loc4`='你观察着貌似平静的冰冠冰川，突然发现了有趣的景象……', `FemaleText_loc5`='在觀察了寒冰皇冠內許多不重要的情報之後，你突然注意到一件有趣的事情...', `FemaleText_loc7`='Vislumbrando muchas situaciones insignificantes en Corona de Hielo, te topas con algo interesante...' WHERE `ID`=31493;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 영혼의 차원으로 전환하자 변형물이 생성됩니다!', `MaleText_loc4`='%s进入了星界位面！', `MaleText_loc5`='當%s轉移至星界時形體異變!', `MaleText_loc7`='¡Cuando %s pasa al plano astral se forman anomalías!' WHERE `ID`=31497;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발명의 신전 분석을 시작합니다.', `MaleText_loc4`='开始对创世神殿进行分析。', `MaleText_loc5`='發明神殿分析開始。', `MaleText_loc7`='Comenzando análisis del Templo de la Invención.' WHERE `ID`=31498;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발명의 신전은 손상되지 않은 것으로 확인되었습니다.', `MaleText_loc4`='创世神殿完好无损。', `MaleText_loc5`='發明神殿確認完好。', `MaleText_loc7`='Se ha verificado que el Templo de la Invención está intacto.' WHERE `ID`=31499;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기계노움 수행원들 사이에 싸움이 있었던 것으로 보입니다. 수행원들이 한구석에 어지러이 쌓여 있습니다.', `MaleText_loc4`='机械仆人之间似乎发生了内讧。部分机械侏儒随从被随意地堆放在一起。', `MaleText_loc5`='機械僕人開始彼此攻擊。幾個侍者也聚集起來構成一個鬆散的團體。', `MaleText_loc7`='Parece que los sirvientes mecánicos se han vuelto unos contra otros. Varios guardas han sido apilados sin ningún orden.' WHERE `ID`=31500;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='남아 있는 기계노움 수호자들은 알 수 없는 성분에 오염되었습니다.', `MaleText_loc4`='某种未知的力量摧毁了剩余的机械侏儒守卫。', `MaleText_loc5`='剩餘的機械地精守護者因不明原因而墮落。', `MaleText_loc7`='Los guardianes mecagnomos restantes han sido corrompidos por una fuente desconocida.' WHERE `ID`=31501;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감시자 미미르는 더는 존재하지 않는 것으로 확인되었습니다. 분석을 종료합니다.', `MaleText_loc4`='未发现守护者米米尔。分析完毕。', `MaleText_loc5`='看守者彌米爾確認已不存在。分析完成。', `MaleText_loc7`='Se ha verificado que el vigía Mimir ya no está presente. Análisis completado.' WHERE `ID`=31502;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='브리쿨이 곤히 마법 잠을 자고 있습니다.', `MaleText_loc4`='维库人安详地沉睡着。', `MaleText_loc5`='維酷人安穩地進入魔法休眠。', `MaleText_loc7`='El vrykul descansa pacíficamente en su sueño mágico.' WHERE `ID`=31503;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겨울의 신전 분석을 시작합니다.', `MaleText_loc4`='开始对寒冬神殿进行分析。', `MaleText_loc5`='凜冬神殿分析開始。', `MaleText_loc7`='Comenzando análisis del Templo del Invierno.' WHERE `ID`=31504;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠든 미요르딘을 깨워 진짜 고대 영웅 이스칼더인지 확인합니다.', `MaleText_loc4`='叫醒休眠的尤尔丁人，确认他是不是远古英雄伊斯卡德尔。', `MaleText_loc5`='喚醒休眠的默約丁以確認是否為遠古英雄，伊斯卡德。', `MaleText_loc7`='Despierta al mjordin dormido para ver si realmente es el antiguo héroe, Iskalder.', `FemaleText_loc1`='잠든 미요르딘을 깨워 진짜 고대 영웅 이스칼더인지 확인합니다.', `FemaleText_loc4`='叫醒休眠的尤尔丁人，确认他是不是远古英雄伊斯卡德尔。', `FemaleText_loc5`='喚醒休眠的默約丁來確認是否為遠古英雄，伊斯卡德。', `FemaleText_loc7`='Despierta al mjordin dormido para ver si realmente es el antiguo héroe, Iskalder.' WHERE `ID`=31505;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겨울의 신전은 손상되지 않은 것으로 확인되었습니다.', `MaleText_loc4`='寒冬神殿完好无损。', `MaleText_loc5`='凜冬神殿確認完好。', `MaleText_loc7`='Se ha verificado que el Templo del Invierno está intacto.' WHERE `ID`=31506;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신전의 수호자들이 사망한 것으로 확인되었습니다. 유황 냄새가 나는 것으로 보아 불 속성을 지닌 상대에게 당한 것으로 판단됩니다.', `MaleText_loc4`='神殿守卫者已经死亡。弥漫神殿的硫磺气味表明他是被某种火焰生物杀死的。', `MaleText_loc5`='神殿守護者確認已死亡。殘留的硫磺氣味顯示死亡可能與火焰存在體有關。', `MaleText_loc7`='Se ha verificado que los vigías del templo han fallecido. El olor a sulfuro sugiere que la muerte se produjo a manos de una entidad basada en fuego.' WHERE `ID`=31507;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기존에 신전에서 관찰되던 추위 변화는 사라졌습니다.', `MaleText_loc4`='神殿之前设定的寒冷气候模式已终止。', `MaleText_loc5`='先前建立於神殿中的寒冷天候模組已終止。', `MaleText_loc7`='Los patrones de clima frío previamente establecidos en el templo han cesado.' WHERE `ID`=31508;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감시자 호디르가 더는 존재하지 않는 것으로 확인되었습니다. 분석을 종료합니다.', `MaleText_loc4`='未发现守护者霍迪尔。分析完毕。', `MaleText_loc5`='看守者霍迪爾確認已不存在。分析完成。', `MaleText_loc7`='Se ha verificado que el vigía Hodir ya no está presente. Análisis completado.' WHERE `ID`=31509;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감시자 프레이야가 더는 존재하지 않는 것으로 확인되었습니다. 분석을 종료합니다.', `MaleText_loc4`='未发现守护者弗蕾亚。分析完毕。', `MaleText_loc5`='看守者芙蕾雅確認已不存在。分析完成。', `MaleText_loc7`='Se ha verificado que la vigía Freya ya no está presente. Análisis completado.' WHERE `ID`=31510;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생명의 신전은 심하게 파손되어 복구 불능으로 확인되었습니다.', `MaleText_loc4`='生命神殿遭到破坏，无法修复。', `MaleText_loc5`='生命神殿確認遭受無法修復的破壞。', `MaleText_loc7`='Se ha verificado que el Templo de la Vida ha sufrido daños irreparables.' WHERE `ID`=31512;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='치열한 전투가 벌어졌음을 보여주는 증거가 발견되었습니다. 감시자 프레이야의 상대는 프레이야와 비슷한 몸집과 힘을 지녔던 것으로 추정됩니다.', `MaleText_loc4`='种种迹象表明神殿曾发生过激战。估计守护者弗蕾亚的对手在体型和力量上都与她不相上下。', `MaleText_loc5`='證據顯示發生過一場激烈戰鬥。看守者芙蕾雅的敵人估計與看守者芙蕾雅有相近的體型與力量。', `MaleText_loc7`='Las pruebas indican que hubo una batalla considerable. Se estima que el oponente de la vigía Freya es de tamaño y fuerza similares a los de la vigía Freya.' WHERE `ID`=31513;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신전의 수호자들이 더는 존재하지 않습니다. 신전에서 자라던 식물들은 죽었습니다.', `MaleText_loc4`='未发现神殿守护者。与神殿伴生的植物形态已经死亡。', `MaleText_loc5`='神殿守護者已不存在。與神殿連結的植物物種已死亡。', `MaleText_loc7`='Los vigías del templo ya no están presentes. Los elementos vegetales asociados al templo han fallecido.' WHERE `ID`=31514;
