UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 브라보. 이 형편없는 실패작을 풀어주고 나니 좀 뿌듯하신가?', `MaleText_loc4`='啧啧。你犯下了如此可怕的错误，是不是感觉很自豪啊？', `MaleText_loc5`='喔，太好了。你現在不是覺得很驕傲自己鑄下這個恐怖的錯誤?', `MaleText_loc7`='Oh, bravo. ¿Te sientes orgulloso ahora que has dejado suelta a esta terrible equivocación?' WHERE `ID`=31550;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 녀석 원래 폐기처분할 예정이었다. 덕분에 좀 더 빨리 처리할 수 있겠군.', `MaleText_loc4`='我本来就打算销毁他，看来可以提前完成了。', `MaleText_loc5`='我早就定下了處理的日程，但我想我們得加快腳步了。', `MaleText_loc7`='Ya había previsto cómo deshacerme de él, pero supongo que podemos acelerar un poco el proceso.' WHERE `ID`=31551;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='페이든 다르킨을 만나시려면 장인의 정원 중앙에서 2층으로 가십시오.', `MaleText_loc4`='芬迪·达金就在工匠区中央的第二层。', `MaleText_loc5`='菲丹·達金位於工匠區中間的二樓。', `MaleText_loc7`='Feyden Oscuro está en el segundo piso, en el centro del Bancal del Artesano.', `FemaleText_loc1`='페이든 다르킨을 만나시려면 장인의 정원 중앙에서 2층으로 가세요.', `FemaleText_loc4`='芬迪·达金就在工匠区中央的第二层。', `FemaleText_loc5`='菲丹·達金位於工匠區中間的二樓。', `FemaleText_loc7`='Feyden Oscuro está en el segundo piso, en el centro del Bancal del Artesano.' WHERE `ID`=31552;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 질 좋고 쓸 만한 부위들을 버려야 한다니 안타깝군...', `MaleText_loc4`='哎呀，这些质量上等，可以重复利用的零件都要报废啦……真是可惜……', `MaleText_loc5`='可惜很多精緻又可以反覆利用的材料全都浪費了...', `MaleText_loc7`='Es una pena malgastar tantas partes reutilizables de semejante calidad...' WHERE `ID`=31553;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누더기 이제 자르거나 꿰매지 않아도 된다!', `MaleText_loc4`='补丁再也不想被随意地切开或是缝合了！', `MaleText_loc5`='補釘不要再被切開又重新縫起來!', `MaleText_loc7`='¡A Parches no van a cortarlo ni coserlo más!' WHERE `ID`=31554;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='괜찮아요! 늙은 브란이 있잖습니까! 무쇠 괴물 좀 맡아주세요. 그동안 저는 이 기계가 도움이 될지 만져보죠.', `MaleText_loc4`='嘿！别担心！老布莱恩在后面给你们加油呢！把这些该死的金属疙瘩给我挡住，让我来好好跟这台可爱的大机器谈谈，让它帮帮你们！', `MaleText_loc5`='別擔心!老布萊恩替你守著背後!你們去擋著那些金屬怪物，我看能不能說動這台機器幫助你!', `MaleText_loc7`='¡Descuida! ¡El viejo Brann te cubrirá! ¡Entretén a ese monstruo metálico, que yo trataré de convencer a esta máquina de ayudarte!' WHERE `ID`=31555;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누더기는 의술사 사브녹한테 복수할 거다!', `MaleText_loc4`='补丁要向萨布诺克博士复仇！', `MaleText_loc5`='補釘要向賽伯諾克博士復仇!', `MaleText_loc7`='¡Parches vengarse de doctor Sabnok!' WHERE `ID`=31556;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='토스가 수정 전당에서 주문각인을 가르쳐 줄 겁니다.', `MaleText_loc4`='水晶大厅的索斯能教你铭文技能。', `MaleText_loc5`='水晶大廳的索司可以傳授你銘文學的奧秘。', `MaleText_loc7`='Thoth puede enseñarte inscripción en La Sala de Cristal.', `FemaleText_loc1`='토스가 수정 전당에서 주문각인을 가르쳐 줄 거예요.', `FemaleText_loc4`='水晶大厅的索斯能教你铭文技能。', `FemaleText_loc5`='水晶大廳的索司可以傳授你銘文學的奧秘。', `FemaleText_loc7`='Thoth puede enseñarte inscripción en La Sala de Cristal.' WHERE `ID`=31557;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조마를 만나려면 골목길 위층에 있는 건물 안으로 가보게.', `MaleText_loc4`='犹尔曼就在暗巷区二层的某座建筑物内。', `MaleText_loc5`='裘瑪就在暗巷區一棟建築物的二樓。', `MaleText_loc7`='Jo''mah está en el segundo piso de La Calle Mayor.', `FemaleText_loc1`='조마를 만나려면 골목길 위층에 있는 건물 안으로 가보게.', `FemaleText_loc4`='犹尔曼就在暗巷区二层的某座建筑物内。', `FemaleText_loc5`='裘瑪就在暗巷區一棟建築物的二樓。', `FemaleText_loc7`='Jo''mah está en el segundo piso de La Calle Mayor.' WHERE `ID`=31558;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미용사 말인가? 어둠의 틈에서 힘의 골짜기로 가게를 옮겼지. 예전에 과일 상인이 있던 자리라네.', `MaleText_loc4`='理发师？她已经把理发店搬出暗影裂口，挪到力量谷上方的悬崖中去了。就是原来开水果店的那个地方。', `MaleText_loc5`='美容師?她的店搬遷了，從暗影裂口搬到力量谷上方的山崖處，就是以前水果商那裡。', `MaleText_loc7`='¿La peluquera? Se ha ido del Circo de las Sombras y se ha trasladado a los riscos que hay sobre el Valle de la Fuerza, donde solía estar el vendedor de fruta.', `FemaleText_loc1`='미용사 말인가? 어둠의 틈에서 힘의 골짜기로 가게를 옮겼지. 예전에 과일 상인이 있던 자리라네.', `FemaleText_loc4`='理发师？她已经把理发店搬出暗影裂口，挪到力量谷上方的悬崖中去了。就是原来开水果店的那个地方。', `FemaleText_loc5`='美容師?她的店搬遷了，從暗影裂口搬到力量谷上方的山崖處，就是以前水果商那裡。', `FemaleText_loc7`='¿La peluquera? Se ha ido del Circo de las Sombras y se ha trasladado a los riscos que hay sobre el Valle de la Fuerza, donde solía estar el vendedor de fruta.' WHERE `ID`=31559;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛이시여! 이 저주 받은 괴물들! 놈들이 우리 형제들에게 한 짓을 보게!', `MaleText_loc4`='天啊！该死的怪物！看看它们对我们的人民做了些什么！', `MaleText_loc5`='以聖光之名!這些該死的怪物!看看你對我們的人民做了什麼!', `MaleText_loc7`='¡POR LA LUZ! ¡Esos malditos monstruos! ¡Mirad lo que han hecho a nuestra gente!' WHERE `ID`=31560;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다 불태워라, 형제들이여. 모조리 다.', `MaleText_loc4`='烧死它们。烧毁这一切。', `MaleText_loc5`='把它們燒了，孩子。把它們全燒了。', `MaleText_loc7`='Quemadlo, chicos. Reducidlo a cenizas.' WHERE `ID`=31561;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='올 테면 와 보라지. 죗값을 단단히 치르게 해줄 테니!', `MaleText_loc4`='来吧。让它们为此付出代价！', `MaleText_loc5`='讓它們來。讓它們付出代價!', `MaleText_loc7`='Dejad que vengan. ¡Pagarán por lo que han hecho!' WHERE `ID`=31562;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가서 마고 파슐리를 만나보십시오. 연금술 실험실에 있는 어여쁜 아가씨 말입니다.', `MaleText_loc4`='玛尔迦丝·帕克雷就在炼金房，她是一位漂亮的女士。', `MaleText_loc5`='你去找瑪苟·帕切里。她就是鍊金房的那位漂亮女士。', `MaleText_loc7`='Puedes encontrar a Margaux Pastoseco, esa hermosa dama en El Apothecarium.', `FemaleText_loc1`='가서 마고 파슐리를 만나보세요. 연금술 실험실에 있는 어여쁜 아가씨 말이에요.', `FemaleText_loc4`='玛尔迦丝·帕克雷就在炼金房，她是一位漂亮的女士。', `FemaleText_loc5`='你去找瑪苟·帕切里。她就是鍊金房的那位漂亮女士。', `FemaleText_loc7`='Puedes encontrar a Margaux Pastoseco, esa hermosa dama en El Apothecarium.' WHERE `ID`=31563;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미용사 말이야? 나즈니크 말이구먼! 상업 지구 위층에 있지. 은행 근처 말이야.', `MaleText_loc4`='理发师纳兹尼克在贸易区的上层，紧邻银行。', `MaleText_loc5`='美容師?那茲尼克啊!他就在貿易區的樓上，在銀行附近。', `MaleText_loc7`='¿Peluquero? ¡Ese es Naznik! Se encuentra en el piso superior del Barrio del Comercio, cerca del banco.', `FemaleText_loc1`='미용사 말인가요? 나즈니크 말이군요! 상업 지구 위층에 있지요. 은행 근처에요.', `FemaleText_loc4`='理发师纳兹尼克在贸易区的上层，紧邻银行。', `FemaleText_loc5`='美容師?那茲尼克啊!他就在貿易區的樓上，在銀行附近。', `FemaleText_loc7`='¿Peluquero? ¡Ese es Naznik! Se encuentra en el piso superior del Barrio del Comercio, cerca del banco.' WHERE `ID`=31564;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='포쉬켄 할바인더를 찾으려면 정기의 봉우리 아래쪽에 있는 예언의 웅덩이로 가보십시오.', `MaleText_loc4`='波什金·哈比德尔在灵魂高地下的预见之池。', `MaleText_loc5`='你可以在靈魂高地下方的預見之池找到波西坎·堅縛。', `MaleText_loc7`='Busca a Poshken Legajos en las Pozas de las Visiones, bajo el Alto de los Espíritus.', `FemaleText_loc1`='포쉬켄 할바인더를 찾으려면 정기의 봉우리 아래쪽에 있는 예언의 웅덩이로 가보세요.', `FemaleText_loc4`='波什金·哈比德尔在灵魂高地下的预见之池。', `FemaleText_loc5`='你可以在靈魂高地下方的預見之池找到波西坎·堅縛。', `FemaleText_loc7`='Busca a Poshken Legajos en las Pozas de las Visiones, bajo el Alto de los Espíritus.' WHERE `ID`=31565;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='각인사 잔타시아는 태양 궁정에서 찾으실 수 있습니다.', `MaleText_loc4`='赞塔希娅在逐日王庭。', `MaleText_loc5`='你可以在陽光庭院找到雕銘師贊塔西亞。', `MaleText_loc7`='Puedes encontrar a la escriba Zantasia en la Corte del Sol.', `FemaleText_loc1`='각인사 잔타시아는 태양 궁정에서 찾으실 수 있어요.', `FemaleText_loc4`='赞塔希娅在逐日王庭。', `FemaleText_loc5`='你可以在陽光庭院找到雕銘師贊塔西亞。', `FemaleText_loc7`='Puedes encontrar a la escriba Zantasia en la Corte del Sol.' WHERE `ID`=31566;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 놈도 살려두지 마라!', `MaleText_loc4`='不留活口！', `MaleText_loc5`='不留活口!', `MaleText_loc7`='¡No dejéis supervivientes!' WHERE `ID`=31567;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 끔찍한 피조물 앞에서 몸서리쳐라!', `MaleText_loc4`='面对我的恐怖造物，颤抖吧！', `MaleText_loc5`='在我恐怖的作品面前畏縮顫抖吧!', `MaleText_loc7`='¡Escóndanse de mis horribles creaciones!' WHERE `ID`=31568;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맘껏 즐겨라, 나의 자식들아! 산 자의 육신을 맘껏 즐겨라!', `MaleText_loc4`='仆从们，把他们都消灭！', `MaleText_loc5`='我的孩子，盡情地享受新鮮的血肉大餐吧!', `MaleText_loc7`='¡Regocijaos, hijos míos! ¡Regocijaos con la carne de los vivos!' WHERE `ID`=31569;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무의미한 저항은 그만두고, 내게 영혼을 바쳐라!', `MaleText_loc4`='放下武器，交出你们的灵魂！', `MaleText_loc5`='放下武器，奉上你們的靈魂!', `MaleText_loc7`='¡Depongan las armas y entreguen sus almas!' WHERE `ID`=31570;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왕 앞에 무릎을 꿇어라!', `MaleText_loc4`='向你们的王低头吧！', `MaleText_loc5`='快對你們的王行禮!', `MaleText_loc7`='¡Arrodíllense ante su rey!' WHERE `ID`=31571;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='박멸한다.', `MaleText_loc4`='毁灭。', `MaleText_loc5`='毀滅。', `MaleText_loc7`='Desaparece.' WHERE `ID`=31572;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 해냈네, 친구들! 봉우리에서 스컬지를 몰아냈다고! 서둘러 구스타프 신부에게 가서 이 좋은 소식을 전해 주게! 우린 여기서 정비를 하겠네. 어서 떠나게!', `MaleText_loc4`='成功啦！我们从天灾军团手中夺得了北伐军之峰！立刻向古斯塔夫神父汇报这一好消息！我们要立即展开建设工事！快！', `MaleText_loc5`='我們成功了，兄弟們!我們從天譴軍手中奪下了巔峰!立刻向賈斯塔夫神父回報這個好消息!我們要開始建築和紮營!快!', `MaleText_loc7`='¡Lo hemos logrado, chicos! ¡Hemos arrebatado el pináculo a la Plaga! ¡Presentaos ante el padre Gustav inmediatamente y dadle las buenas noticias! ¡Vamos a construir y montar cosas! ¡Venga!' WHERE `ID`=31573;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내... 고통을... 맛보라.', `MaleText_loc4`='了解……我的……痛苦。', `MaleText_loc5`='嚐嚐...我的...痛苦。', `MaleText_loc7`='Siente... mi... dolor.' WHERE `ID`=31574;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공허를... 주시하라.', `MaleText_loc4`='凝视……虚空。', `MaleText_loc5`='凝視...虛無。', `MaleText_loc7`='Contempla... el vacío.' WHERE `ID`=31575;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직... 부족하다.', `MaleText_loc4`='更多的……能量。', `MaleText_loc5`='更多的...能量。', `MaleText_loc7`='Más... energía.' WHERE `ID`=31576;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='포기하라.', `MaleText_loc4`='放弃吧。', `MaleText_loc5`='放棄吧。', `MaleText_loc7`='Ríndete.' WHERE `ID`=31577;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='암흑에... 굴복하라.', `MaleText_loc4`='坠入……黑暗。', `MaleText_loc5`='墬入...黑暗。', `MaleText_loc7`='Cae... en la sombras.' WHERE `ID`=31578;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흩어진다...', `MaleText_loc4`='消散。', `MaleText_loc5`='灰飛煙滅。', `MaleText_loc7`='Disípate.' WHERE `ID`=31579;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흐물거리는 추적자가 공격을 받고 약해졌습니다.', `MaleText_loc4`='轻盈追迹者遭到攻击，变得虚弱了。', `MaleText_loc5`='輕盈潛獵者因攻擊而虛弱。', `MaleText_loc7`='El asalto ha debilitado al acechador ágil.' WHERE `ID`=31580;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전체적으로 이런 위기 상황에 빠진 도시를 제가 어떻게든 도울 방법이 없을까요?', `MaleText_loc4`='面对如此大规模的危机，我要如何应对？', `MaleText_loc5`='我要怎麼幫助一個陷入如此危機中的城市?', `MaleText_loc7`='¿Cómo puedo ayudar a la ciudad cuando se encuentra sumergida en una crisis tan extendida?' WHERE `ID`=31581;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하나둘씩 모두 앓아눕고 있습니다. 이건 전염병입니다!', `MaleText_loc4`='所有人都病倒了——这是天灾！', `MaleText_loc5`='每個人都生病倒下了 - 這根本是疾病大流行!', `MaleText_loc7`='Todo el mundo se está poniendo enfermo. ¡Es una epidemia!' WHERE `ID`=31582;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 처방도 듣지 않습니다. 도시 전체가 병들었어요...', `MaleText_loc4`='药物根本不起作用——整座城市在痛苦中呻吟。', `MaleText_loc5`='沒有一種療法有效 - 整座城市都病了...', `MaleText_loc7`='Ningún remedio parece funcionar. Toda la ciudad ha enfermado.' WHERE `ID`=31583;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음식이 잘못되었다는 소문 때문에 공황에 빠진 병사들이 늘어갑니다. 이웃들은 음식에 독을 넣었다며 서로 고발하고 있습니다. 도시 전체가 혼란에 빠질 것입니다!', `MaleText_loc4`='关于变质粮食的传闻在士兵之间流传，恐慌正在蔓延。市民们互相指责邻居就是投毒者。城市已经陷入骚乱。', `MaleText_loc5`='士兵們因為腐壞食物的謠言而四處引起慌亂。鄰居彼此指控對方下毒。整個城市都要陷入混亂了!', `MaleText_loc7`='Los soldados están infundiendo el pánico con rumores de comida en malas condiciones. Los vecinos se acusan unos a otros de envenenamiento. ¡Se va a armar el rosario de la aurora!' WHERE `ID`=31584;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='몸져눕는 사람들이 점점 더 늘어나기 때문에 이 도시는 서서히 죽어 가고 있습니다...', `MaleText_loc4`='越来越多的劳工卧床不起，城市系统正在趋于瘫痪……', `MaleText_loc5`='隨著越來越多工人病倒，整個城市也彷彿停滯下來...', `MaleText_loc7`='La ciudad se está paralizando a medida que más y más trabajadores enferman...' WHERE `ID`=31585;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 어찌할 바를 모르겠습니다. 평범한 사람이 이런 재난 상황에서 무엇을 할 수 있겠습니까?', `MaleText_loc4`='我完全不知所措。面对这样的灾难，我又能做些什么呢？', `MaleText_loc5`='我實在不知所措。就只有一個人要怎麼面對這場災難?', `MaleText_loc7`='No sé cómo actuar. ¿Qué puede hacer un solo hombre ante tal desastre?' WHERE `ID`=31586;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 저도 몸이 안 좋은데, 스트레스성 위궤양이기를 기도합니다...', `MaleText_loc4`='我发誓，我的不适感源于焦虑……', `MaleText_loc5`='我希望我感覺到的不適，只是因為壓力導致的胃潰瘍...', `MaleText_loc7`='Espero que el malestar que siento se deba a una úlcera por estrés...' WHERE `ID`=31587;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘못된 방법으로 잠에서 깬 브리쿨이 죽습니다.', `MaleText_loc4`='由于唤醒的方式不当，维库人死亡了。', `MaleText_loc5`='維酷人因為不適當的喚醒過程而死亡。', `MaleText_loc7`='El vrykul muere al ser despertado de forma poco apropiada.' WHERE `ID`=31588;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='깨우는 의식이 방해를 받아 브리쿨이 죽습니다.', `MaleText_loc4`='由于唤醒仪式受到了干扰，维库人死亡了。', `MaleText_loc5`='對虛弱儀式的干擾導致維酷人的死亡。', `MaleText_loc7`='Una interferencia con el ritual de despertar hace que el vrykul muera.' WHERE `ID`=31589;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='각성의 지팡이를 잘못 사용하자 잠들어 있는 브리쿨이 죽습니다.', `MaleText_loc4`='由于唤醒魔棒的使用不当，沉睡中的维库人死亡了。', `MaleText_loc5`='喚醒權杖的不當使用造成冬眠維酷人的死亡。', `MaleText_loc7`='El uso incorrecto de la vara del despertar hace que el vrykul en hibernación fallezca.' WHERE `ID`=31590;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠들어 있는 브리쿨이 쓰러집니다.', `MaleText_loc4`='沉睡中的维库人摔倒在地。', `MaleText_loc5`='冬眠的維酷人昏厥過去。', `MaleText_loc7`='El vrykul en hibernación se cae.' WHERE `ID`=31591;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='십자군 봉우리를 되찾은 건 앞으로 헤쳐나가야 할 길고 험한 여정의 시작일 뿐이네. 얼음왕관 성채를 공격하려면 앞으로도 극복해야 할 장애물이 한둘이 아닐 터.$B$B자네나 자네 같은 영웅의 도움이 반드시 필요하네.', `MaleText_loc4`='占领北伐军之峰只是第一步，我们的事业漫长而危险。要攻陷冰冠冰川，要做的事情还有很多。$B$B只有在像你这样的勇士的帮助下，我们才有可能取得胜利。', `MaleText_loc5`='奪下十字軍之巔只是這漫長而危險旅程的第一步。在我們能夠進攻冰冠城塞之前，還有很長的路。$B$B這一切都得靠你和其他像你一樣的英雄。', `MaleText_loc7`='Tomar el Pináculo de los Cruzados solo es el primer paso de un viaje largo y peligroso. Aún queda mucho por hacer antes de que podamos asaltar la Ciudadela de la Corona de Hielo.$B$BSolo será posible con tu ayuda y la de otros como tú, $ghéroe:heroína;.' WHERE `ID`=31592;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달라란에 온 걸 환영합니다, $c|1이여;여;.', `MaleText_loc4`='欢迎来到达拉然，$c。', `MaleText_loc5`='歡迎來到達拉然，$c。', `MaleText_loc7`='$gBienvenido:Bienvenida:c;, $c.' WHERE `ID`=31593;
