UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발드마드라?! 리치 왕께서 친히 널 보내셨나?', `MaleText_loc4`='瓦尔德玛达？！巫妖王亲自派你来的？', `MaleText_loc5`='瓦德瑪卓?!巫妖王親自派你來的?', `MaleText_loc7`='¡¿Vardmadra?! ¿El Rey Exánime te envió personalmente?' WHERE `ID`=31599;
