UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나에겐 아직 전사의 자부심이 남아 있다. 나 갖고 장난치지 마라, 이 해골 놈아.', `MaleText_loc4`='我是个伟大的战士，别来惹我，骷髅。', `MaleText_loc5`='我是個偉大的戰士，不要耍我，骷髏。', `MaleText_loc7`='Yo soy un gran guerrero, no juegues conmigo, esqueleto.' WHERE `ID`=31617;
