UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 한 번 쳐다보기만 해 봐, 해골. 뼈를 다 뽑아 버릴 테니까!', `MaleText_loc4`='看着我，骷髅。我要把你的头从脆弱的骨架上拧下来！', `MaleText_loc5`='看著我骷髏。我要把你的頭骨從你脆弱的骨架上給扯下來!', `MaleText_loc7`='Vuelve a mirarme, esqueleto. ¡Arrancaré tu cráneo de tu endeble estructura!' WHERE `ID`=31621;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 달그락거리는 뼈 안 치워, 이 무개념 꼭두각시 녀석아.', `MaleText_loc4`='给我滚远点，你这没脑子的傀儡。', `MaleText_loc5`='別拿你脆巴巴的骨頭擋著我，沒大腦的寵物。', `MaleText_loc7`='Aparten sus quebradizos huesos de mi camino, marionetas descerebradas.' WHERE `ID`=31623;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하늘파괴자호가 얼음왕관을 순찰하고 있습니다. 전 지역에서 더 좋은 비행선은 찾아볼 수 없을 겁니다.', `MaleText_loc4`='破天号将开往冰冠冰川。世界上找不到比它更好的飞船啦。', `MaleText_loc5`='破天者號在寒冰皇冠巡弋。在這個區域你找不到比這更棒的船了。', `MaleText_loc7`='El Rompecielos patrulla por Corona de Hielo. No encontrarás un barco mejor en ningún reino.' WHERE `ID`=31624;
