UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐! 꿇어라, 멍청한 놈들아. 저분은 리치 왕이시다!', `MaleText_loc4`='住手！快跪下！蠢货，这可是巫妖王！', `MaleText_loc5`='停!跪下，愚蠢的東西，這是巫妖王陛下!', `MaleText_loc7`='¡BASTA! ¡Arrodíllense, tontos, es el Rey Exánime!' WHERE `ID`=31627;
