UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발드마드라. 어디로 사라졌는지 궁금하던 참이었다. 이스칼더는 어떠냐?', `MaleText_loc4`='瓦尔德玛达。我还以为你失踪了呢。伊斯卡德尔呢？', `MaleText_loc5`='瓦德瑪卓。我正好奇你消失到哪兒去了。伊斯卡德怎麼樣了?', `MaleText_loc7`='Vardmadra, me preguntaba a dónde habrías ido. ¿Cómo está Iskalder?' WHERE `ID`=31629;
