UPDATE `locales_broadcast_text` SET `MaleText_loc1`='변장해도 소용없다, 여군주 나이츠우드. 설마 나를 속일 수 있을 줄 알았나?!', `MaleText_loc4`='奈丝伍德夫人，我能看穿你的伪装。你以为这点小把戏就能愚弄我吗？！', `MaleText_loc5`='我看穿了你的偽裝，夜林女士。你以為你能愚弄我?!', `MaleText_loc7`='Sé que traes un disfraz, Lady Bosqueténebro. ¡¿CREES QUE PUEDES ENGAÑARME?!' WHERE `ID`=31632;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어떻게...!', `FemaleText_loc4`='但是……！', `FemaleText_loc5`='但...!', `FemaleText_loc7`='¡Pero...!' WHERE `ID`=31633;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하던 전투 계속해도 좋다, 대영주.', `MaleText_loc4`='你可以继续战斗了，领主。', `MaleText_loc5`='你可以繼續你的戰鬥，共主。', `MaleText_loc7`='Siga combatiendo, señor feudal supremo.' WHERE `ID`=31634;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만, 왕이시여?!', `MaleText_loc4`='陛下，但是……？', `MaleText_loc5`='可是，陛下...?', `MaleText_loc7`='Pero, ¿señor...?' WHERE `ID`=31635;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시끄럽다! 놈들을 처치해라! 날 실망시키지 마라, 발라르가드!', `MaleText_loc4`='但是什么！杀了他们！别让我失望，BALARGARDE！', `MaleText_loc5`='沒有可是!了結他們!不要讓我失望，巴拉加德!', `MaleText_loc7`='¡Pero nada! ¡Acábalo! ¡NO ME FALLES, BALARGARDE!' WHERE `ID`=31636;
