UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<고개를 끄덕이는 대영주 다리온 모그레인>', `MaleText_loc4`='<大领主达里安·莫格莱尼点了点头。>', `MaleText_loc5`='<大領主達瑞安·莫格萊尼點點頭。>', `MaleText_loc7`='<El alto señor Darion Mograine asiente.>' WHERE `ID`=31638;
