UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음의 기사, 나랑 놀래?', `MaleText_loc4`='死亡骑士也来玩了？', `MaleText_loc5`='死亡騎士也來玩?', `MaleText_loc7`='¿Caballero de la Muerte venir a jugar?' WHERE `ID`=31640;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 패치워크 때리려는 거야?', `MaleText_loc4`='为什么要伤害帕奇维克？', `MaleText_loc5`='你為什麼要傷害縫補者?', `MaleText_loc7`='¿Por qué hacer pupa a Remendejo?' WHERE `ID`=31641;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕이 낙스라마스에서 패치워크 빌려간다고 했다. 패치워크 빌려가는 거 화난다!', `MaleText_loc4`='巫妖王说帕奇维克是从纳克萨玛斯“暂借”来的。这让帕奇维克很生气！', `MaleText_loc5`='巫妖王說縫補者是從納克薩瑪斯外借的。借這個字讓縫補者不爽!', `MaleText_loc7`='Rey Exánime decir que Remendejo "prestado" de Naxxramas. ¡Préstamo ENFADAR a Remendejo!' WHERE `ID`=31642;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='패치워크랑 놀아줘! 패치워크 외롭다!', `MaleText_loc4`='帕奇维克跟你玩！帕奇维克很孤单！', `MaleText_loc5`='要來跟縫補者玩嗎!縫補者很無聊!', `MaleText_loc7`='¡Venir a jugar con Remendejo! ¡Remendejo solito!' WHERE `ID`=31643;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='패치워크는 낙스라마스 다시 가고 싶다. 너희들 다 죽이면 집으로 갈 수 있는 거야?', `MaleText_loc4`='帕奇维克想念纳克萨玛斯。杀死你们，帕奇维克或许就能早点回家啦。', `MaleText_loc5`='縫補者想念納克薩瑪斯。也許快點把你們殺光就可以讓縫補者回家?', `MaleText_loc7`='Remendejo echar Naxxramas de menos. ¿Tú poder matar a todos rápido para que Remendejo poder ir a casa?' WHERE `ID`=31644;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대가 살아 있는 단 한가지 이유는 바로 내 호기심 때문이다.', `MaleText_loc4`='你还活着只是因为我比较好奇。', `MaleText_loc5`='你還活著的唯一理由就是因為我的好奇心。', `MaleText_loc7`='La única razón por la que sigues con vida es porque tengo curiosidad.' WHERE `ID`=31645;
