UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 죽는다고 이 침공이 멈추지는 않으리라!', `MaleText_loc4`='就算我死了，这次入侵行动也不会停止！', `MaleText_loc5`='我的死亡是無法讓入侵停止的!', `MaleText_loc7`='¡Mi muerte no detendrá esta invasión!', `FemaleText_loc1`='내가 죽는다고 이 침공이 멈추지는 않으리라!', `FemaleText_loc4`='就算我死了，这次入侵行动也不会停止！', `FemaleText_loc5`='我的死亡是無法讓入侵停止的!', `FemaleText_loc7`='¡Mi muerte no detendrá esta invasión!' WHERE `ID`=31655;
