UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무슨 용건인진 모르겠지만, 빨리해 주세요.', `FemaleText_loc4`='你有什么需要，尽快开口吧。', `FemaleText_loc5`='不管你想要來要求什麼，動作快一點。', `FemaleText_loc7`='Sea lo que sea lo que vas a pedir, hazlo deprisa.' WHERE `ID`=31674;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드의 백성이여! 얼라이언스의 시민이여! 국왕으로서 너희들 앞에 고한다!', `MaleText_loc4`='暴风城的市民！联盟的公民！你们的国王有话要说！', `MaleText_loc5`='暴風王國的百姓!聯盟的人民!你們的國王在此宣告!', `MaleText_loc7`='¡Gente de Ventormenta! ¡Ciudadanos de la Alianza! ¡Su rey habla!' WHERE `ID`=31675;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘은 앞으로 계속될 스컬지와의 싸움에서 첫 승리를 거둔 날이로다! 리치 왕의 수하에 있던 죽음의 기사들이 그의 손아귀에서 벗어나 동맹을 결성하고 그의 왕국에 반기를 들었도다!', `MaleText_loc4`='今天，是天灾军团首次战败的日子！巫妖王昔日的奴仆——死亡骑士已经摆脱了他的控制，并结成了反抗其暴政的新同盟！', `MaleText_loc5`='今天我們見證了天譴軍團失敗的開端!曾經服侍巫妖王的死亡騎士，如今掙脫了他的掌控並組成了一個新的團體來反抗巫妖王的暴政!', `MaleText_loc7`='¡Hoy marca la primera de muchas derrotas de la Plaga! Los caballeros de la Muerte, antiguamente servidores del Rey Exánime, se han liberado de su control y han formado una nueva alianza contra su tiranía.' WHERE `ID`=31676;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한때 얼라이언스의 영웅이었던 이들을 환영해주고 스톰윈드의 동맹과 마찬가지로 존경으로써 대하기 바란다!', `MaleText_loc4`='死亡骑士曾是联盟的英雄，如今他们再次成为暴风城的盟友！你们应该欢迎他们，并给予他们应有的尊重！', `MaleText_loc5`='你們理應歡迎這些曾是聯盟英雄的人們，懷著尊敬之心，如同對待所有暴風王國的盟友一般對待他們!', `MaleText_loc7`='¡Daréis la bienvenida a estos antiguos héroes de la Alianza y los trataréis con el mismo respeto que a cualquier aliado de Ventormenta!' WHERE `ID`=31677;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스에게 영광을!', `MaleText_loc4`='荣耀属于联盟！', `MaleText_loc5`='榮耀歸於聯盟!', `MaleText_loc7`='¡Gloria a la Alianza!' WHERE `ID`=31678;
