UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드여, 대족장으로서 여러분께 고하오!', `MaleText_loc4`='部落的同胞，你们的酋长有话要说！', `MaleText_loc5`='部落，聆聽你們大酋長的宣告!', `MaleText_loc7`='¡Horda! ¡Escuchen la llamada de su Jefe de Guerra!' WHERE `ID`=31687;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘은 앞으로 계속될 스컬지와의 싸움에서 첫 승리를 거둔 날이오! 리치 왕의 수하에 있던 죽음의 기사들이 그의 손아귀에서 벗어나 동맹을 결성하고 그의 왕국에 반기를 들었소!', `MaleText_loc4`='今天，是天灾军团首次战败的日子！巫妖王昔日的奴仆——死亡骑士已经摆脱了他的控制，并结成了反抗其暴政的新同盟！', `MaleText_loc5`='今天我們見證了天譴軍團失敗的開端!曾經服侍巫妖王的死亡騎士，如今掙脫了他的掌控並組成了一個新的團體來反抗巫妖王的暴政!', `MaleText_loc7`='¡Hoy marca la primera de muchas derrotas de la Plaga! Los caballeros de la Muerte, antiguamente servidores del Rey Exánime, se han liberado de su control y han formado una nueva alianza contra su tiranía.' WHERE `ID`=31688;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한때 호드의 영웅이었던 이들을 환영해주고 오그리마의 동맹과 마찬가지로 존경으로써 대하기 바라오!', `MaleText_loc4`='死亡骑士曾是部落的英雄，如今他们再次成为奥格瑞玛的盟友！你们应该欢迎他们，并给予他们应有的尊重！', `MaleText_loc5`='你們應該歡迎這些曾是部落英雄的人們，懷著尊敬之心，如同對待所有奧格瑪的盟友一般對待他們!', `MaleText_loc7`='¡Daréis la bienvenida a estos antiguos héroes de la Horda y los trataréis con el mismo respeto que a cualquier aliado de Orgrimmar!' WHERE `ID`=31689;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드를 위하여!', `MaleText_loc4`='为了部落！', `MaleText_loc5`='為了部落!', `MaleText_loc7`='¡Por la Horda!' WHERE `ID`=31690;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스컬지다!!!! 물러나시오! 가몬이 모두를 구할 거요!', `MaleText_loc4`='天灾军团！！！退后！加摩尔会保护你们的！', `MaleText_loc5`='天譴軍!!!!退後!加摩爾會保護大家的!', `MaleText_loc7`='¡PLAGA! ¡No os acerquéis! ¡Gamon nos salvará a todos!' WHERE `ID`=31691;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='문을 부쉈다! 달라란으로 가는 길이 열렸다! 이제 마력 전쟁의 끝을 내자!', `MaleText_loc4`='我们冲破了监狱的大门！进入达拉然的道路被清理干净了！魔枢之战终于可以结束了！', `MaleText_loc5`='我們攻破了監獄大門!通往達拉然的通道已經暢通了!現在我們終於可以終結奧核戰爭了!', `MaleText_loc7`='¡Hemos atravesado la puerta de la prisión! ¡El camino hacia Dalaran está despejado! ¡Por fin hemos puesto punto y final a la guerra de El Nexo!' WHERE `ID`=31692;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가장 훌륭한 부하를 하나 쓰러뜨렸군. 하지만 아무 소용없다.', `MaleText_loc4`='你击败了我忠诚的奴仆，但是你付出的努力是徒劳的。', `MaleText_loc5`='你擊敗我最好的手下之一，但你的努力是毫無用處的。', `MaleText_loc7`='Venciste a uno de mis mejores guerreros, pero tu esfuerzo será inútil.' WHERE `ID`=31693;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='해냈군요! 푸른용군단을 몰아내고 그들의 사령관을 없애셨습니다! 대단하군요!', `FemaleText_loc4`='你成功啦！你击退了蓝龙军团，并杀死了他们的指挥官。这真是个奇迹！', `FemaleText_loc5`='你們辦到了!你們阻擋了藍龍軍團並且擊敗了他們的指揮官。幹得太好了!', `FemaleText_loc7`='¡Lo lograron! ¡Contuvieron al Vuelo Azul y derrotaron a su Comandante! ¡Un trabajo impresionante!' WHERE `ID`=31694;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼음왕관의 얼어붙은 심장이 기다리고 있다...', `MaleText_loc4`='冰冠冰川的霜寒之心在等待……', `MaleText_loc5`='寒冰皇冠的冰凍之心在等待著...', `MaleText_loc7`='El centro de Corona de Hielo espera…' WHERE `ID`=31695;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기서부터는 저희가 맡겠습니다. 그런 싸움을 치르셨으니 좀 쉬십시오.', `FemaleText_loc4`='这里就交给我们吧。在那场战斗之后，你已经赢得了大家的尊重。', `FemaleText_loc5`='我們從這邊接手，你們可以在戰鬥後好好休息。', `FemaleText_loc7`='A partir de ahora nos encargaremos nosotros. Se han ganado un respiro después de esa batalla.' WHERE `ID`=31696;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 웃음을 짓더니 해골 마녀를 조종하러 되돌아갑니다.', `FemaleText_loc4`='%s笑了笑，重新附到了白骨女巫身上。', `FemaleText_loc5`='%s微笑並且飛回到正施展佔據法術的骸骨女巫身邊。', `FemaleText_loc7`='%s sonríe y se va volando para volver a poseer a la Bruja Osaria.' WHERE `ID`=31697;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경고: 날 수 없는 지역에 진입했으며, 탈것에서 떨어지기 직전입니다!', `MaleText_loc4`='警告：你已经进入了禁飞区域，骑乘状态即将解除！', `MaleText_loc5`='警告:你進入了禁航區，即將解除坐騎!', `MaleText_loc7`='Alerta: ¡Has entrado en una zona en la que no se puede volar y vas a caer de la montura!', `FemaleText_loc1`='경고: 날 수 없는 지역에 진입했으며, 탈것에서 떨어지기 직전입니다!', `FemaleText_loc4`='警告：你已经进入了禁飞区域，骑乘状态即将解除！', `FemaleText_loc5`='警告:你進入了禁航區，即將解除坐騎!', `FemaleText_loc7`='Alerta: ¡Has entrado en una zona en la que no se puede volar y vas a caer de la montura!' WHERE `ID`=31698;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='거기 너! 앞으로 나와!', `FemaleText_loc4`='你！到前面来！', `FemaleText_loc5`='你!站上前來!', `FemaleText_loc7`='¡Oye, tú! ¡Adelántate!' WHERE `ID`=31699;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='요그사론 님! 힘을 주소서!', `FemaleText_loc4`='尤格-萨隆！赐予我力量吧！', `FemaleText_loc5`='尤格薩倫!把你的力量賜給我!', `FemaleText_loc7`='¡Yogg-Saron! ¡Concédeme tu poder!' WHERE `ID`=31700;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='주인님, 선물을 드립니다!', `FemaleText_loc4`='主人，这是奉献给您的礼物！', `FemaleText_loc5`='主人，這是奉獻給您的禮物!', `FemaleText_loc7`='¡Amo, un obsequio para usted!' WHERE `ID`=31701;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='요그사론께 영광을!', `FemaleText_loc4`='荣耀归于尤格-萨隆！', `FemaleText_loc5`='榮耀歸於尤格薩倫!', `FemaleText_loc7`='¡Gloria a Yogg-Saron!' WHERE `ID`=31702;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='쓸모없는 놈!', `FemaleText_loc4`='你毫无价值。', `FemaleText_loc5`='你一文不值。', `FemaleText_loc7`='Eres indigno.' WHERE `ID`=31703;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='일어나! 아직 멀었단 말이다!', `FemaleText_loc4`='起来！你受的痛苦还远远不够呢。', `FemaleText_loc5`='起來!你受的苦還不夠多。', `FemaleText_loc7`='¡Levántate! No has sufrido lo suficiente.' WHERE `ID`=31704;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='신성모독은 반드시... 벌을 받게 되어 있다...', `FemaleText_loc4`='别以为你们亵渎了这里……还能安然无恙。', `FemaleText_loc5`='別以為你們褻瀆了這裡...還能安然無恙。', `FemaleText_loc7`='No esperes que tu sacrilegio... quede impune.' WHERE `ID`=31705;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='문명 세계에 대항해, 정령들이 직접 봉기할 것이다! 믿음이 충만한 자만이 살아남으리라!', `FemaleText_loc4`='元素之力必将崛起，夺回这个被文明玷污的世界！只有最虔诚的信徒才能幸免于难！', `FemaleText_loc5`='元素們將會起而對抗這個文明世界!唯有信仰堅定的人才能存活!', `FemaleText_loc7`='¡La furia de los elementos se desatará contra el mundo civilizado! ¡Sólo los fieles serán salvados!' WHERE `ID`=31706;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='요그사론 님께 충성을 맹세하는 자는 불멸을 얻게 될 것이다!', `FemaleText_loc4`='只要将全部身心都献给伟大的尤格-萨隆，就连你们也可以获得不朽的生命！', `FemaleText_loc5`='你也能獲得永生，但你必須要將自己完完全全獻給尤格薩倫。', `FemaleText_loc7`='¡La inmortalidad puede ser tuya, pero sólo si te consagras plenamente a Yogg-Saron!' WHERE `ID`=31707;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기 그분의 영역에서, 너희는 상상조차 못했던 힘을 경험하게 될 것이다!', `FemaleText_loc4`='在这里，在最靠近他领地的地方，你可以亲身体会到这强大得无以复加的力量！', `FemaleText_loc5`='在這裡，在最靠近他領地的地方，你可以親身體會到這強大得無以復加的力量!', `FemaleText_loc7`='¡Aquí, en las mismísimas fronteras de su territorio, experimentarás poderes que jamás habrías imaginado!' WHERE `ID`=31708;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너희는 수많은 위험을 무릅쓰고 이 먼 곳까지 왔다. 너희의 헌신은 보상받을 것이다!', `FemaleText_loc4`='你经历了长途跋涉和艰难险阻来到这里！你应为你的执着而得到奖励。', `FemaleText_loc5`='為了來到這裡，你們長途跋涉，歷經艱險。你們的虔誠必將得到獎賞。', `FemaleText_loc7`='¡Has viajado mucho y arriesgado mucho para estar aquí! Se recompensará tu devoción.' WHERE `ID`=31709;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='믿음이 충만한 자는 높임을 받으리라! 하지만 아직 할 일이 많다. 우리는 온 아제로스가 그분의 그늘에 놓일 때까지 진군할 것이다!', `FemaleText_loc4`='信徒们，你们有理由高兴与欢呼，但我们仍有许多未尽的事业。在整个艾泽拉斯都被他的阴影笼罩之前，我们还要继续努力！', `FemaleText_loc5`='信徒們，你們有理由高興與歡呼，但我們仍有許多未盡的事業。在整個艾澤拉斯都被他的陰影籠罩之前，我們還要繼續努力!', `FemaleText_loc7`='Los fieles serán exaltados, pero aún hay trabajo que hacer. ¡Seguiremos adelante hasta que todo Azeroth yazca bajo su sombra!' WHERE `ID`=31710;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 땅을 침입하는 놈은... 드라카리 손에 죄다 죽는다!', `MaleText_loc4`='一切胆敢践踏这片土地的入侵者都将被达卡莱巨魔消灭！', `MaleText_loc5`='德拉克瑞會殺死膽敢穿越這片土地的人!', `MaleText_loc7`='¡Drakkari matará a todoss los que invadan estas tierrass!' WHERE `ID`=31711;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='숨이 멎었나? 좋아...', `MaleText_loc4`='你没气了？很好！', `MaleText_loc5`='沒呼吸了?很好。', `MaleText_loc7`='¿No repirassss? Bien.' WHERE `ID`=31712;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='슬슬 겁이 나나?', `MaleText_loc4`='害怕了吧？', `MaleText_loc5`='你怕了?', `MaleText_loc7`='¿Tieness miedo?' WHERE `ID`=31713;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='몸은 따로... 쓸 데가 있지.', `MaleText_loc4`='我下一个就要吃你！', `MaleText_loc5`='老兄，下一個就吃你。', `MaleText_loc7`='Luego te como a ti.' WHERE `ID`=31714;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가장 무서운 적은... 스컬지가 아니었구나...', `MaleText_loc4`='我明白了……天灾军团……并不是我们最大的敌人……', `MaleText_loc5`='我現在...知道天譴軍團...不是我們...最大的敵人...', `MaleText_loc7`='Ya veo... La Plaga no fue... nuesstro peor enemigo…' WHERE `ID`=31715;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까. 프라스 샤비 주인님께서는 출타 중이십니다. 샤비의 최고급 담배를 맛보시려면 내일 다시 와주시기 바랍니다! 삐빅!', `MaleText_loc4`='你好。弗拉斯·希亚比现在不在。明天再来光顾希亚比的烟草店吧！哔哔！', `MaleText_loc5`='你好。弗拉斯·希亞比主人這時候不在。明天請再來弗拉斯·希亞比的煙草店!嗶!', `MaleText_loc7`='Hola. El maestro Fras Siabi no se encuentra aquí en este momento. ¡Por favor, vuelve mañana a Tabaco de calidad de Fras Siabi! ¡Piii!', `FemaleText_loc1`='안녕하십니까. 프라스 샤비 주인님께서는 출타 중이십니다. 샤비의 최고급 담배를 맛보시려면 내일 다시 와주시기 바랍니다! 삐빅!', `FemaleText_loc4`='你好。弗拉斯·希亚比现在不在。明天再来光顾希亚比的烟草店吧！哔哔！', `FemaleText_loc5`='你好。弗拉斯·希亞比主人這時候不在。明天請再來弗拉斯·希亞比的煙草店!嗶!', `FemaleText_loc7`='Hola. El maestro Fras Siabi no se encuentra aquí en este momento. ¡Por favor, vuelve mañana a Tabaco de calidad de Fras Siabi! ¡Piii!' WHERE `ID`=31716;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일입니까?', `MaleText_loc4`='这是什么？', `MaleText_loc5`='那是什麼?', `MaleText_loc7`='¿Qué pasa?' WHERE `ID`=31717;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='훌륭한 방어였다만, 도시를 지키게 둘 수는 없지! 내 직접 말리고스 님의 의지를 실현하리라!', `FemaleText_loc4`='真是一群英勇的卫兵，但这座城市必须被夷平。我要亲自执行玛里苟斯大人的指令！', `FemaleText_loc5`='真是一群英勇的衛兵，但這座城市必須被夷平。我必須親自執行瑪里苟斯大人的指令!', `FemaleText_loc7`='Una digna defensa, pero es preciso arrasar esta ciudad. ¡Cumpliré los deseos de Malygos personalmente!' WHERE `ID`=31718;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<눈을 이용해 허깨비 감시자를 조종하십시오.>', `MaleText_loc4`='<利用眼睛控制一只幻象观察者。>', `MaleText_loc5`='<透過眼睛控制一名幻象看守者。>', `MaleText_loc7`='<Consigue controlar a un vigía de Eidolon a través del ojo.>', `FemaleText_loc1`='<눈을 이용해 허깨비 감시자를 조종하십시오.>', `FemaleText_loc4`='<利用眼睛控制一只幻象观察者。>', `FemaleText_loc5`='<透過眼睛控制一名幻象看守者。>', `FemaleText_loc7`='<Consigue controlar a un vigía de Eidolon a través del ojo.>' WHERE `ID`=31719;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='손님께서는 여기에 싸우러 오신 게 아니었으면 해요. 오늘은 거리에 분노한 사람들이 너무나 많더군요.', `FemaleText_loc4`='希望你不是来这里打架的。街上到处都是愤怒的市民。', `FemaleText_loc5`='我希望你不是來惹是生非的。今天街上實在有太多憤怒的民眾了。', `FemaleText_loc7`='Espero que no vengas buscando pelea. A día de hoy se ve demasiada gente cabreada por ahí.' WHERE `ID`=31720;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저기요, 오늘은 방패를 팔지만, 철퇴는 없답니다. 멍청한 누군가가 제가 판 무기로 정신을 좀 차리기만을 바랄 뿐이에요.', `FemaleText_loc4`='今天我只出售盾牌，不卖锤子。我不希望看到无辜的市民被我出售的武器所伤。', `FemaleText_loc5`='聽著，我今天可以賣給你盾牌，但不會賣給你釘錘。我可不想看見有無辜的人被我的武器打得頭破血流。', `FemaleText_loc7`='Mira, hoy te venderé escudos, pero no mazas. Lo último que quiero es que le abran la cabeza a algún inocente con una de mis armas.' WHERE `ID`=31721;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='밖이 저렇게 소란스러우니 오늘 언제까지 장사할지 기약할 수가 없네요. 수리해야 할 물건이 있으시다면, 제가 얼른 봐 드리지요.', `FemaleText_loc4`='整座城市都陷入了骚乱，我不知道今天还能营业多久。如果你要修理东西的话，我可以尽快帮你处理。', `FemaleText_loc5`='外頭鬧成這樣，我不知道我今天還會開張多久。如果你有東西要修理，我可以很快地看一下。', `FemaleText_loc7`='No sé cuánto tiempo más tendré el negocio abierto hoy con la conmoción que hay ahí fuera. Si necesitas que te repare algo, le echare un vistazo rápido.' WHERE `ID`=31722;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 끝을 내자! 키린 토의 용사들이여!', `FemaleText_loc4`='让我们来做个了断吧，肯瑞托的勇士们！', `FemaleText_loc5`='讓我們來做個了斷吧，祈倫托的勇士!', `FemaleText_loc7`='¡Acabemos esto ahora, campeones de los Kirin Tor!' WHERE `ID`=31723;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죄송합니다만 오늘 돌까마귀 선술집은 영업하지 않습니다. 위생 문제가 좀 많아서 말입니다. 에드가 사람들을 병에 걸리게 한다는 비난을 듣게 하지는 않으려 합니다.', `MaleText_loc4`='很抱歉，石鸦旅店今天暂停营业。最近饮食卫生问题闹得很严重，我可不想别人跳出来指责我们的厨师传播疾病。', `MaleText_loc5`='石鴉今天不營業，抱歉。我們得要考慮健康問題，我可不想背上讓人生病的黑鍋。', `MaleText_loc7`='El Cuervo de Piedra está cerrado hoy, lo siento. Hay demasiados problemas de salud y no pienso dejar que sospechen que Ed está haciendo que la gente enferme.' WHERE `ID`=31724;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='키린 토를 끝장내 버리겠다!', `FemaleText_loc4`='我要终结肯瑞托！', `FemaleText_loc5`='我會毀滅祈倫托!', `FemaleText_loc7`='¡Acabaré con los Kirin Tor!' WHERE `ID`=31725;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='달라란은 반드시 무너진다!', `FemaleText_loc4`='达拉然即将沦陷！', `FemaleText_loc5`='達拉然將會陷落!', `FemaleText_loc7`='¡Dalaran SUCUMBIRÁ!' WHERE `ID`=31726;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마법의 지배자께 반항하는 것도 이걸로 끝이다!', `FemaleText_loc4`='你对织法者的冒犯到此为止了。', `FemaleText_loc5`='你對織法者的反抗到此為止。', `FemaleText_loc7`='Así termina tu desafío al Tejehechizos.' WHERE `ID`=31727;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너희를... 과소평가했구나...', `FemaleText_loc4`='或许……我们……低估了……你们。', `FemaleText_loc5`='或許...我們...低估了...你們。', `FemaleText_loc7`='Quizás... te hemos... subestimado.' WHERE `ID`=31728;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사람들을 실망시켜 드리고 싶지는 않지만, 돌까마귀 선술집은 문을 닫았습니다. 보육원 아이들이 대피까지 한 이 마당에, 계속 영업해야 하는 이유를 모르겠거든요.', `MaleText_loc4`='我不喜欢让别人失望呢，但是石鸦旅店已经暂停营业了。孤儿院的孩子们都撤离了，我们为什么还要开门做生意。', `MaleText_loc5`='我討厭讓別人失望，但石鴉今天不營業。如果孤兒院的孩子都撤離了，我不知道為什麼我得開門營業。', `MaleText_loc7`='Siento decepcionar a la gente, pero el Cuervo de Piedra está cerrado. Si han evacuado a los niños del orfanato no entiendo por qué esto debería estar abierto.' WHERE `ID`=31729;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저 밖에 웬 소란이죠?', `FemaleText_loc4`='外面怎么乱哄哄的？', `FemaleText_loc5`='外頭的騷動是怎麼回事?', `FemaleText_loc7`='¿A qué viene tanto jaleo ahí fuera?' WHERE `ID`=31730;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무슨 일인가요? 사람들이 화내는 소리가 들리는데요.', `FemaleText_loc4`='出了什么事？我听到愤怒的喊叫声。', `FemaleText_loc5`='有什麼事情發生了嗎?我聽到生氣的聲音。', `FemaleText_loc7`='¿Ocurre algo? Oígo voces enojadas.' WHERE `ID`=31731;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='요즘은 세상이 아주 이상하게 돌아가요...', `FemaleText_loc4`='最近发生的事情都很奇怪……', `FemaleText_loc5`='最近每件事都變得好奇怪···', `FemaleText_loc7`='Todo ha sido tan raro últimamente...' WHERE `ID`=31732;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동부 역병지대에 있는 희망의 빛 예배당에서 은빛 여명회가 스컬지의 저항에 맞서고 있소. 그리로 가서 지시를 따르시오.', `MaleText_loc4`='在东瘟疫之地的圣光之愿礼拜堂，银色黎明指挥着对抗天灾军团的战斗。去那里接受命令吧。', `MaleText_loc5`='銀色黎明正在東瘟疫之地的聖光之願禮拜堂召集反抗天譴軍團的生力軍。請前往接受下一步的指示。', `MaleText_loc7`='El Alba Argenta coordina la oposición contra la Plaga en la Capilla de la Esperanza de la Luz en las Tierras de la Peste del Este. Ve allí para recibir instrucciones.', `FemaleText_loc1`='동부 역병지대에 있는 희망의 빛 예배당에서 은빛 여명회가 스컬지의 저항에 맞서고 있소. 그리로 가서 지시를 따르시오.', `FemaleText_loc4`='在东瘟疫之地的圣光之愿礼拜堂，银色黎明指挥着对抗天灾军团的战斗。去那里接受命令吧。', `FemaleText_loc5`='銀色黎明正在東瘟疫之地的聖光之願禮拜堂召集反抗天譴軍團的生力軍。請前往接受下一步的指示。', `FemaleText_loc7`='El Alba Argenta coordina la oposición contra la Plaga en la Capilla de la Esperanza de la Luz en las Tierras de la Peste del Este. Ve allí para recibir instrucciones.' WHERE `ID`=31733;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 룬을 쓰겠습니다.', `MaleText_loc4`='我要使用符文。', `MaleText_loc5`='我想要拿符文來交換一些東西。', `MaleText_loc7`='Me gustaría gastar mis runas.', `FemaleText_loc1`='제 룬을 쓰겠어요.', `FemaleText_loc4`='我要使用符文。', `FemaleText_loc5`='我想要拿符文來交換一些東西。', `FemaleText_loc7`='Me gustaría gastar mis runas.' WHERE `ID`=31735;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직은 겨울손아귀 호수에서 싸울 만큼 강하지 못한 분이군요. 가서 경험을 더 쌓고 오십시오.', `MaleText_loc4`='你的能力还不足以参加冬拥湖的战斗。等你的经验更丰富一些后，再回来吧。', `MaleText_loc5`='你的等級還不足以參加冬握湖的戰鬥。等你獲得更多經驗的時候再回來。', `MaleText_loc7`='Todavía no eres lo suficientemente $gpoderoso:poderosa; como para luchar en lago Conquista del Invierno. Vuelve cuando tengas más experiencia.', `FemaleText_loc1`='아직은 겨울손아귀 호수에서 싸울 만큼 강하지 못한 분이네요. 가서 경험을 더 쌓고 오세요.', `FemaleText_loc4`='你的能力还不足以参加冬拥湖的战斗。等你的经验更丰富一些后，再回来吧。', `FemaleText_loc5`='你的等級還不足以參加冬握湖的戰鬥。等你獲得更多經驗的時候再回來。', `FemaleText_loc7`='Todavía no eres lo suficientemente $gpoderoso:poderosa; como para luchar en lago Conquista del Invierno. Vuelve cuando tengas más experiencia.' WHERE `ID`=31736;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겨울손아귀 호수로 가는 차원문입니다.', `MaleText_loc4`='该传送门通往冬拥湖。', `MaleText_loc5`='這個傳送門通往冬握湖。', `MaleText_loc7`='Este portal lleva al Lago Conquista del Invierno.', `FemaleText_loc1`='겨울손아귀 호수로 가는 차원문입니다.', `FemaleText_loc4`='该传送门通往冬拥湖。', `FemaleText_loc5`='這個傳送門通往冬握湖。', `FemaleText_loc7`='Este portal lleva al Lago Conquista del Invierno.' WHERE `ID`=31737;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='차원문으로 들어갑니다.', `MaleText_loc4`='进入传送门。', `MaleText_loc5`='進入傳送門。', `MaleText_loc7`='Atraviesa el portal.', `FemaleText_loc1`='차원문으로 들어갑니다.', `FemaleText_loc4`='进入传送门。', `FemaleText_loc5`='進入傳送門。', `FemaleText_loc7`='Atraviesa el portal.' WHERE `ID`=31738;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너희 중에 누가 내 힘에 도전할 수 있겠느냐!', `FemaleText_loc4`='有谁能在我的力量面前屹立不倒？', `FemaleText_loc5`='你們當中有誰能夠承受我的力量呢?', `FemaleText_loc7`='¿Quién de ustedes puede resistir mi poder?' WHERE `ID`=31740;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절 부관 아이스해머에게 데려다 주십시오, 조렉!', `MaleText_loc4`='带我去见冰锤中尉，索雷克！', `MaleText_loc5`='帶我去找冰錘中尉，索芮克!', `MaleText_loc7`='¡Zorek, llévame junto al teniente Martillo de Hielo!', `FemaleText_loc1`='절 부관 아이스해머에게 데려다 주십시오, 조렉!', `FemaleText_loc4`='带我去见冰锤中尉，索雷克！', `FemaleText_loc5`='帶我去找冰錘中尉，索芮克!', `FemaleText_loc7`='¡Zorek, llévame junto al teniente Martillo de Hielo!' WHERE `ID`=31741;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='많은 이들이 발할라스에서 죽었다. 그 시체들은 우리 방식이 어떤지 잘 보여주는 증거라 할 수 있지.$B$B네 뼈도 명예와 전투의 상좌에 흩뿌리려 하는가?', `FemaleText_loc4`='许多人都死在了瓦哈拉斯，他们的尸体见证了比武场的残酷。$B$B$n，你的骸骨是否也会留在荣耀与血腥的战场呢？', `FemaleText_loc5`='許多人在英靈殿中逝去，他們的屍體成為我們力量考驗的一部份。$B$B你也願意將骸骨留在這個力量與戰鬥的殿堂嗎，$n?', `FemaleText_loc7`='Muchos han caído dentro de Valhalas y sus cadáveres son el testamento de la fuerza de nuestros métodos.$B$B¿Quedarán también tus huesos esparcidos en este lugar de honor y batalla, $n?' WHERE `ID`=31742;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$r|1이여;여;, 당신이 선 그 자리에서 죽였어야 했소!$B$B생각없이 내뱉는 쓸데없는 말은 그만두고 썩 물러가시오!', `MaleText_loc4`='我很可能会在眨眼之间把你劈成两半，$r！$B$B如果你说完了废话，最好趁早滚开！', `MaleText_loc5`='我應該就地殺了你，$r!$B$B講完你愚蠢的廢話然後給我消失!', `MaleText_loc7`='¡Debería matarte aquí mismo, $r!$B$B¡Continúa con tu estúpido balbuceo y acabaré contigo!' WHERE `ID`=31743;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='발할라스에서는 살아남거나 죽거나 둘 중 하나다, $n. 어떤 일이 생겨도 투기장을 벗어나지 마라. 도망치는 건 패배와 굴욕을 의미한다.', `FemaleText_loc4`='瓦哈拉斯是你抉择生死之地，$n。在任何情况下，你都不能擅自退出比武场。如果你选择逃跑，就意味着你可耻地输掉了比赛。', `FemaleText_loc5`='你能在英靈殿內獲勝或長眠，$n。但無論你怎麼做，都要在競技場的界限內。逃走就是失敗，並且會被視為恥辱者。', `FemaleText_loc7`='Valhalas es el lugar donde ganarás o morirás, $n. Pero hagas lo que hagas, quédate dentro de los límites de la arena. Huir es como perder y quedar deshonrado.' WHERE `ID`=31744;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 그리고 $g그의:그녀의; 전우들은 발할라스의 신성한 영역 안에서 명예롭게 싸우기로 하였다.', `FemaleText_loc4`='$n和$g他:她;的战友被选中，将在神圣的瓦哈拉斯进行光荣的战斗。', `FemaleText_loc5`='$n以及$g他的:她的;戰友們已經選擇接受在英靈殿的神聖領域內進行光榮的戰鬥。', `FemaleText_loc7`='$n y sus compañeros en la lucha han decidido aceptar un combate honorable dentro de los sagrados confines de Valhalas.' WHERE `ID`=31745;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='발할라스에서의 전투는 어느 한 쪽이 죽어야만 끝이 난다. 살아남는 자가 될지, 죽는 자가 될지, $n|1은;는; 발할라스에서 전사한 이방인들의 뼈 위에서 자신을 시험하게 될 것이다.', `FemaleText_loc4`='瓦哈拉斯的战斗只有一个结果：必须有一方倒下。$n，如果你想要证明自己的力量，就必须将对手的尸体踩在脚下！', `FemaleText_loc5`='只有一種方法可以結束這場戰鬥:其中一方的死亡。讓$n從那些外來死者的骸骨中證明$g他:她;自己!', `FemaleText_loc7`='Una batalla así solo puede acabar de una manera: con la muerte de uno u otro. ¡Deja que $n demuestre lo que vale sobre los huesos de los forasteros que fracasaron antes!' WHERE `ID`=31746;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='도전은 실패했다. 브리쿨도 아니었는데, 어찌 보면 당연한 일이다.', `FemaleText_loc4`='挑战者失败了。他们不是维库人，落得败局也是可以预见的。', `FemaleText_loc5`='挑戰者失敗了。維酷人從不預期這種事。', `FemaleText_loc7`='Los contendientes han fracasado. Era de esperar, pues no son vrykuls.' WHERE `ID`=31747;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전투 패배의 치욕은 평생을 함께할 것이다.', `FemaleText_loc4`='比武场上的败者将带着羞耻离开尘世。', `FemaleText_loc5`='戰鬥失敗的恥辱是永恆的。', `FemaleText_loc7`='La deshonra por fracasar en el combate es eterna.' WHERE `ID`=31748;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='발할라스의 힘에 감히 도전할 자는 더 없는가?', `FemaleText_loc4`='还有谁想要在瓦哈拉斯一展实力？', `FemaleText_loc5`='有其他人膽敢挑戰英靈殿的力量嗎?', `FemaleText_loc7`='¿Quién más se atrevería a desafiar el poder de Valhalas?' WHERE `ID`=31749;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='발할라스는 풋내기와 어리석은 자들이 올 곳이 아니다.', `FemaleText_loc4`='瓦哈拉斯不是消遣玩乐的地方。', `FemaleText_loc5`='英靈殿不是供人玩耍的地方。', `FemaleText_loc7`='Valhalas no es lugar para juegos, ni para insensatos.' WHERE `ID`=31750;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='실패한 자들에게 한 번의 기회를 더 주겠다. 너희는 브리쿨이 아닌데, 어떻게 최강의 브리쿨 전사와 같은 기준을 적용할 수 있겠는가.', `FemaleText_loc4`='我们会再给战败者一次机会的。你们不是维库人，不能用比武场严格的标准要求你们。', `FemaleText_loc5`='我們會給你這些失敗者另一次機會。你不是維酷人，不需要接受這麼高的標準。', `FemaleText_loc7`='Os daremos otra oportunidad a los que habéis fracasado. No sois vrykuls, así que no se os puede medir por el mismo rasero.' WHERE `ID`=31751;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='발할라스의 바닥을 장식할 뼈가 늘었군. 다음 도전자를 데려와라!', `FemaleText_loc4`='瓦哈拉斯的荣耀源于这满地的尸骨。让下一组挑战者进来吧！', `FemaleText_loc5`='更多的屍骨來崇敬英靈殿的廳堂。帶上下一批隊伍!', `FemaleText_loc7`='Más huesos para honrar el suelo de Valhalas. ¡Traed al siguiente grupo!' WHERE `ID`=31752;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='넌 준비가 안 됐다!', `FemaleText_loc4`='你们这是自寻死路！', `FemaleText_loc5`='你還沒準備好!', `FemaleText_loc7`='¡No estabais preparados!' WHERE `ID`=31753;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='발할라스가 너무 버겁다면 요툰하임에 풋내기를 위한 싸움이 준비되어 있다.', `FemaleText_loc4`='如果你目前的实力还不足以参加瓦哈拉斯的战斗，那么在尤顿海姆地区还有其他类型的比赛。', `FemaleText_loc5`='如果你的技巧還不足以挑戰英靈殿，卓頓海姆還有其他的戰鬥。', `FemaleText_loc7`='Puedes participar en otras luchas dentro de Jotunheim si no tienes eres suficientemente habilidoso para Valhalas.' WHERE `ID`=31754;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n|1이;가; 과거 발할라스 전투에서 전사한 영웅들을 물리쳤다. 이제 겨우 시작이지만, 이 정도면 나쁘지 않다.', `FemaleText_loc4`='$n战胜了瓦哈拉斯的英雄之魂。虽然这仅仅是一场热身赛，但是也算是精彩的对决吧。', `FemaleText_loc5`='$n擊敗了英靈殿的逝往英雄。這只是個開始，但令人滿意。', `FemaleText_loc7`='$n ha derrotado a los héroes caídos en batallas pasadas de Valhalas. Esto solo es el comienzo, pero será suficiente.' WHERE `ID`=31755;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발할라스의 전사한 영웅들이 땅속에서 일어나 다시 전투를 벌이려고 합니다!', `MaleText_loc4`='瓦哈拉斯的英雄之魂现身了，准备再次投入战斗！', `MaleText_loc5`='英靈殿的逝往英雄從地上浮現，再次開始戰鬥!', `MaleText_loc7`='¡Los héroes caídos de Valhalas emergen de la tierra para luchar una vez más!' WHERE `ID`=31756;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너는 발할라스의 전투에 도전할 자격을 갖추지 못했다, $n.$B$B도전에 걸맞은 명성을 쌓고 다시 오너라.', `FemaleText_loc4`='你还没有获得参与瓦哈拉斯比武赛的资格，$n。$B$B等你小有名气之后再到这里来吧。', `FemaleText_loc5`='你還沒辦法證明自己足以進行英靈殿的挑戰，$n。$B$B等你替自己掙得更多名聲之後再回來。', `FemaleText_loc7`='Todavía no has demostrado ser $gdigno:digna; de participar en un desafío dentro de Valhalas, $n.$B$BRegresa cuando te hayas labrado un nombre.' WHERE `ID`=31757;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='많은 이들이 발할라스에서 죽었다. 그 시체들은 우리 방식이 어떤지 잘 보여주는 증거라 할 수 있지.$B$B네 뼈도 명예와 전투의 상좌에 흩뿌리려 하는가?', `FemaleText_loc4`='许多人都死在了瓦哈拉斯，他们的尸体见证了比武场的残酷。$B$B$n，你的骸骨是否也会留在荣耀与血腥的战场呢？', `FemaleText_loc5`='許多人在英靈殿中逝去，他們的屍體成為我們力量考驗的一部份。$B$B你也願意將骸骨留在這個力量與戰鬥的殿堂嗎，$n?', `FemaleText_loc7`='Muchos han caído dentro de Valhalas y sus cadáveres son el testamento de la fuerza de nuestros métodos.$B$B¿Quedarán también tus huesos esparcidos en este lugar de honor y batalla, $n?' WHERE `ID`=31758;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기가 어디라고, 하등한 것들이! 한심하구나... 용기가 넘친들 우둔함을 극복할 수 있을 것 같으냐?', `MaleText_loc4`='低等生物，竟敢入侵这里！可惜你们过度膨胀的勇气，无法挽救愚蠢所导致的悲惨结局！', `MaleText_loc5`='低等生物，竟敢入侵這裡!只可惜你們過度膨脹的勇氣，無法挽救愚蠢帶來的悲慘結局!', `MaleText_loc7`='¡Nos invaden seres inferiores! ¡Qué pena que tu exceso de valor no compense tu estupidez!' WHERE `ID`=31759;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='푸른용군단의 일원만이 여기서 환영받는다. 이건 알렉스트라자가 꾸민 짓이겠지? 그렇다면, 그녀는 너희를 사지로 밀어 넣은 셈이다!', `MaleText_loc4`='这里除了蓝龙军团，没有人可以进来。看来是阿莱克丝塔萨在搞鬼？很好，她实际上是派你们来送死的！', `MaleText_loc5`='這裡除了藍龍軍團，沒有人可以進來。看來是雅立史卓莎在搞鬼?很好，她實際上是派你們來送死的!', `MaleText_loc7`='Nadie es bienvenido aquí excepto Vuelo del Dragón Azul. ¿Quizás esto sea obra de Alexstrasza? Bien, entonces, ¡los ha enviado a morir!' WHERE `ID`=31760;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무엇을 이룰 수 있겠느냐? 뻔뻔하게도 내 영토에 난입해서, 마법을 쓰겠다고? 나를 상대로?', `MaleText_loc4`='你们以为自己能做些什么呢？自大地在我的领域横冲直撞，用毁灭性的魔法来对付……我？', `MaleText_loc5`='你期待完成什麼?厚顏無恥地闖進我的領域...用魔法來...對付我?', `MaleText_loc7`='¿Qué pretendían lograr? ¿Asaltar descaradamente mi territorio?... ¿Utilizar magia?... ¿Contra MÍ?' WHERE `ID`=31761;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에서 내 힘은 무한하다. 현실 법칙 따위 여기선 통하지 않아! 이 영역은, 내가 지배한다!', `MaleText_loc4`='我在这里不受任何约束。那些你们必须遵循的法则对我无效。在这个领域之中，我就是一切！', `MaleText_loc5`='我在這裡的力量是無限的。你們所遵從的法則對我無效。在這個領域中，我就是主宰!', `MaleText_loc7`='Aquí no tengo límites. Las normas de tu preciada realidad no tienen vigor. En este reino, ¡mando yo!' WHERE `ID`=31762;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마지막 기회를 주마. 충성을 맹세해라. 그러면 목숨은 살려줄지도 모르니.', `MaleText_loc4`='我给你们一次机会吧。向我宣誓效忠，这是让我原谅你们的傲慢与无礼的唯一机会。', `MaleText_loc5`='我給你們一次機會。向我效忠，或許我可以原諒你們的傲慢，饒你們一命。', `MaleText_loc7`='Te doy una oportunidad. Prométeme lealtad, y tal vez no te sacrificaré por tu insolencia.' WHERE `ID`=31763;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더는 참을 수가 없구나. 다 없애 버리겠다!', `MaleText_loc4`='我的耐心到此为止了。我要亲自消灭你们！', `MaleText_loc5`='我的耐心到此為止了。我要親自消滅你們!', `MaleText_loc7`='Me has colmado la paciencia. ¡Me desharé de ti!' WHERE `ID`=31764;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금부터 너희가 겪을 고통을 맛본 자는 거의 없었지...', `MaleText_loc4`='没有人体验过你们将要承受的痛苦！', `MaleText_loc5`='沒有人體驗過你們將要承受的痛苦!', `MaleText_loc7`='¡Pocos han sufrido el dolor que ahora te infligiré!' WHERE `ID`=31765;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우둔함이 결국은 죽음을 낳는구나!', `MaleText_loc4`='你们的愚蠢必将葬送自己！', `MaleText_loc5`='你們的愚昧終將導致自己的末日!', `MaleText_loc7`='¡Finalmente tu insensatez ha podido contigo!' WHERE `ID`=31767;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거두어들일 마력이 늘어났군.', `MaleText_loc4`='又有更多的神器可以没收了。', `MaleText_loc5`='又有更多的神器可以沒收了。', `MaleText_loc7`='Más objetos para confiscar.' WHERE `ID`=31768;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미숙한 것들 같으니...', `MaleText_loc4`='太天真了！', `MaleText_loc5`='真的是太天真了。', `MaleText_loc7`='Qué ingenuidad.' WHERE `ID`=31769;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n|1이;가; 어둠의 지배자 키트릭스의 도전을 받아들였다. 신들의 자비가 함께하길. 키트릭스는 자비라는 말조차 모르는 자이리라.', `FemaleText_loc4`='$n接受了黑暗主宰西塔利克斯的挑战。西塔利克斯绝不会手下留情的，愿诸神保佑$g他:她;吧。', `FemaleText_loc5`='$n接受了『黑暗大師』齊特瑞司的挑戰。願諸神憐憫$g他:她;，因為齊特瑞司肯定不會。', `FemaleText_loc7`='$n ha aceptado el desafío de Khit''rix el Cosechador Lóbrego. Ojala los dioses se apiaden de $g él:ella; porque Khit''rix no lo hará.' WHERE `ID`=31770;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='준비하라. 키트릭스가 남동쪽에서 발할라스로 들어올 것이다. 명심하라. 투기장을 벗어나는 순간, 전투에서 패하는 것이다.', `FemaleText_loc4`='做好准备吧。西塔利克斯将从东南方进入瓦哈拉斯。记住，不要离开比武场，否则你就会输掉比赛。', `FemaleText_loc5`='做好準備。齊特瑞司會從英靈殿的東南方進場。記得，不要離開競技場，否則你就會輸掉這場戰鬥。', `FemaleText_loc7`='Prepárate. Khit''rix entrará en Valhalas desde el sudeste. Recuerda, no salgas del anillo o perderás la batalla.' WHERE `ID`=31771;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='되도록 빨리 끝내 주고 싶었다만, 너희는 생각보다... 완강하구나. 어쨌거나 의미 없는 짓거리다. 이 전쟁의 책임은 무모하고 부주의한 필멸의 존재들에게 있다. 나는 할 일을 할 뿐이다. 너희를 멸종시켜야만 한다면, 그리할 수밖에!', `MaleText_loc4`='我原本只是想尽快结束你们的生命……可你们竟然远比我想象得要坚韧。虽然如此，你们的努力仍将付诸东流。事实上，这场战争本身就是因为你们凡人不计后果的行为而起，我只是在尽自己的责任罢了。如果这责任意味着要灭绝你们……那就这样吧！', `MaleText_loc5`='我原本只是想盡快結束你們的生命...可是你們竟然比我想像的還要堅韌。雖然如此，你們的努力仍將付諸東流。事實上，這場戰爭本身就是因為你們凡人不計後果的行為而起，我只是在盡自己的責任罷了。如果這責任意味著要滅絕你們...那就這樣吧!', `MaleText_loc7`='Esperaba acabar rápido con sus vidas, pero han resultado más... resistentes de lo previsto. Sin embargo, sus esfuerzos son en vano. Ustedes, imprudentes e incautos mortales, son los causantes de esta guerra. Cumplo mi deber, y si éste implica aniquilarlos... ¡PUES LO HARÉ!' WHERE `ID`=31772;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법에 대한 너희 지식이 얼마나 보잘것없는지 똑똑히 보여주마!', `MaleText_loc4`='我要让你们这些无知的孩子重新了解魔法的概念。', `MaleText_loc5`='我會讓你們這些無知的小鬼明白，你們對魔法的認知有多淺薄。', `MaleText_loc7`='Les enseñaré, niños ignorantes, lo poco que saben de magia.' WHERE `ID`=31773;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마지막 남은 희망마저 휩쓸려 가는 걸 지켜보아라!', `MaleText_loc4`='就这样无助地看着希望破灭吧！', `MaleText_loc5`='就這樣無助地看著希望破滅吧!', `MaleText_loc7`='¡Mira en vano mientras se desvanecen tus esperanzas!' WHERE `ID`=31774;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 마력은 좋은 일에 쓰일 게다.', `MaleText_loc4`='我会妥善利用你们留下的魔法能量。', `MaleText_loc5`='我會利用你們留下的能量。', `MaleText_loc7`='Tu energía será bien aprovechada.' WHERE `ID`=31775;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 마법의 지배자다! 내 힘은 무한하다!', `MaleText_loc4`='我是织法者！我的力量是无穷无尽的！', `MaleText_loc5`='我是織法者!我的力量是無窮無盡的!', `MaleText_loc7`='¡Soy el Tejehechizos! ¡Tengo poder inagotable!' WHERE `ID`=31776;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 영혼은 영원히 이곳을 헤매리라!', `MaleText_loc4`='你们的灵魂将永远在这里游荡！', `MaleText_loc5`='你們的靈魂將永遠在這裡遊蕩!', `MaleText_loc7`='¡Tu espíritu vagará por aquí eternamente!' WHERE `ID`=31777;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만! 아제로스의 마력을 되찾고 싶으냐? 어디 가져가 봐라...', `MaleText_loc4`='够了！既然你们这么想夺回艾泽拉斯的魔法，我就给你们！', `MaleText_loc5`='夠了!既然你們這麼想奪回艾澤拉斯的魔法，我就給你們!', `MaleText_loc7`='¡BASTA! ¡Si pretendes reclamar la magia Azeroth, entonces la tendrás!' WHERE `ID`=31778;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈들의 후원자가 나타났구나. 하지만 너무 늦었어! 이곳에 흘러넘치는 마력은 세계를 수십 번은 파괴하고도 남는다. 녀석들이 무슨 도움이 될 것 같으냐?', `MaleText_loc4`='现在你们幕后的主使终于出现了，但已经太迟了！这里弥漫着的能量已经足以将世界毁灭十次。你们觉得他们会对你们做些什么呢？', `MaleText_loc5`='現在你們幕後的主使終於出現，不過太遲了。這裡所蘊含的力量足以毀滅這個世界十次。你覺得他們又能幫上什麼忙呢?', `MaleText_loc7`='Ahora aparecen tus benefactores, ¡pero llegan demasiado tarde! Los poderes contenidos aquí alcanzan para destruir el mundo diez veces.  ¿Qué crees que harán contigo?' WHERE `ID`=31779;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='항복해라!', `MaleText_loc4`='投降吧！', `MaleText_loc5`='投降吧!', `MaleText_loc7`='¡Ríndete!' WHERE `ID`=31780;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 숨 쉬는 한, 너희는 이길 수 없다!', `MaleText_loc4`='在我的龙息之下，一切都将荡然无存！', `MaleText_loc5`='只要我龍息尚存，你們就沒機會!', `MaleText_loc7`='¡No triunfarás mientras yo esté vivo!' WHERE `ID`=31781;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에 흐르는 마력은 네놈들이 상상할 수 있는 수준이 아니다!', `MaleText_loc4`='在这里涌动的力量早已超越了你们的理解与想象！', `MaleText_loc5`='這裡運行的力量超越你們所能想像!', `MaleText_loc7`='¡Los poderes que aquí se emplean superan todo lo que podrías imaginar!' WHERE `ID`=31782;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 멈출 순 없다!', `MaleText_loc4`='我无坚不摧！', `MaleText_loc5`='沒有人能阻止我!', `MaleText_loc7`='¡Soy imparable!' WHERE `ID`=31783;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알렉스트라자, 네 아이가 또 하나 쓰러졌다!', `MaleText_loc4`='阿莱克丝塔萨，又有一个你的孩子倒下了！', `MaleText_loc5`='雅立史卓莎，又有一個你的孩子倒下了!', `MaleText_loc7`='¡Alexstrasza, sucumbe otra de tus crías!' WHERE `ID`=31784;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모기보단 좀 세군!', `MaleText_loc4`='就比小虫子强了一点点！', `MaleText_loc5`='只比小蟲強上一點!', `MaleText_loc7`='¡Poco más que mosquitos!' WHERE `ID`=31785;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시뻘건 네놈의 동료와 운명을 같이해라!', `MaleText_loc4`='红龙军团也将步你们的后尘！', `MaleText_loc5`='你的紅龍盟友也將步上你們的後塵!', `MaleText_loc7`='¡Tus rojos aliados perecerán igual que tú!' WHERE `ID`=31786;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직도 버텨? 오래가진 못할 게다.', `MaleText_loc4`='竟然还没倒下？不会太久了。', `MaleText_loc5`='還沒倒下?你也撐不多久了!', `MaleText_loc7`='¿Aún resistes? No por mucho.' WHERE `ID`=31787;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헛수고만 하고 있구나!', `MaleText_loc4`='你们的妄想破灭了！', `MaleText_loc5`='你的妄想已經破滅!', `MaleText_loc7`='¡Tu causa está perdida!' WHERE `ID`=31788;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나약한 정신을 산산조각 내주지!', `MaleText_loc4`='你们脆弱的精神即将崩溃！', `MaleText_loc5`='你們脆弱的心靈將粉碎!', `MaleText_loc7`='¡Tu frágil mente se hará trizas!' WHERE `ID`=31789;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 일이! 필멸의 존재들은... 모든 걸 파괴할 텐데! 누이여, 무슨 짓을...', `MaleText_loc4`='不可思议！这群凡人……竟然毁灭了一切！我的妹妹，你都做了些……什么？', `MaleText_loc5`='不可思議!凡人終將毀滅...所有事物!姐姐，你做了什麼...', `MaleText_loc7`='¡Inconcebible! Los mortales destruirán... ¡todo! Hermana mía, qué has…' WHERE `ID`=31790;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어제 여기에서 음식을 사갔는데 온 식구가 병에 걸렸단 말이야!', `MaleText_loc4`='昨天我就是这个摊位买的食物，现在我的家人都病倒了！', `MaleText_loc5`='我昨天才從這個攤販買的食物，今天我全家都生病了!', `MaleText_loc7`='¡Justo ayer compré comida en este puesto y ahora mi familia ha enfermado!', `FemaleText_loc1`='어제 여기에서 음식을 사갔는데 온 식구가 병에 걸렸단 말이에요!', `FemaleText_loc4`='昨天我就是这个摊位买的食物，现在我的家人都病倒了！', `FemaleText_loc5`='我昨天才從這個攤販買的食物，今天我全家都生病了!', `FemaleText_loc7`='¡Justo ayer compré comida en este puesto y ahora mi familia ha enfermado!' WHERE `ID`=31791;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저기요, 죄송하게 생각해요. 정말이에요. 하지만, 저희 음식은 전부 신선하다고요!', `FemaleText_loc4`='呃，听到这样的消息真让我难过呀，但是我出售的食物都是新鲜的！', `FemaleText_loc5`='聽著，我很抱歉，我真的很抱歉，但我所有的食物都是新鮮的!', `FemaleText_loc7`='Mira, lo siento de verdad, ¡pero toda mi comida es fresca!' WHERE `ID`=31792;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죄수들을 풀어줄 순 없다! 말리고스 님의 말씀은 법이다!', `MaleText_loc4`='绝不能释放这些囚犯！玛里苟斯的话就是律法！', `MaleText_loc5`='絕不能釋放這些囚犯!瑪里苟斯的話就是律法!', `MaleText_loc7`='¡Los prisioneros no saldrán en libertad! ¡La palabra de Malygos es ley!' WHERE `ID`=31793;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벌벌 떨어라!', `MaleText_loc4`='颤抖吧，蠕虫！', `MaleText_loc5`='顫抖吧，蛆蟲!', `MaleText_loc7`='¡Tiemblen, gusanos!' WHERE `ID`=31794;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 뭉개버리겠다!', `MaleText_loc4`='我要消灭你们！', `MaleText_loc5`='我要壓扁你們!', `MaleText_loc7`='¡Los aplastaré!' WHERE `ID`=31795;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날아볼 테냐?', `MaleText_loc4`='会飞么？', `MaleText_loc5`='你會飛嗎?', `MaleText_loc7`='¿Saben volar?' WHERE `ID`=31796;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달아나기엔 너무 늦었어.', `MaleText_loc4`='现在逃跑已经太晚了！', `MaleText_loc5`='現在逃跑已經太晚了!', `MaleText_loc7`='¡Es muy tarde para correr!' WHERE `ID`=31797;
