UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무도 못 도망간다!', `MaleText_loc4`='谁也别想逃跑！', `MaleText_loc5`='誰也別想逃跑!', `MaleText_loc7`='¡Nadie escapará!' WHERE `ID`=31799;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈들에게... 사형을 선고한다!', `MaleText_loc4`='我判处你们死刑！', `MaleText_loc5`='我判你們死刑!', `MaleText_loc7`='¡Te condeno a muerte!' WHERE `ID`=31800;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='응당한 처벌이다.', `MaleText_loc4`='多么恰当的惩罚。', `MaleText_loc5`='適當的懲罰。', `MaleText_loc7`='Un castigo justo.' WHERE `ID`=31801;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='집행 완료!', `MaleText_loc4`='行刑！', `MaleText_loc5`='行刑!', `MaleText_loc7`='¡Sentencia ejecutada!' WHERE `ID`=31802;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전사자 추가...', `MaleText_loc4`='又一个战争的牺牲品。', `MaleText_loc5`='又一個戰爭的犧牲品。', `MaleText_loc7`='¡Otra víctima!' WHERE `ID`=31803;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전쟁은.. 계속된다...', `MaleText_loc4`='战争……还会继续的。', `MaleText_loc5`='戰爭...還會繼續的。', `MaleText_loc7`='La guerra... continúa.' WHERE `ID`=31804;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무래도 내 자유는 피로 사야 하나 보군.', `MaleText_loc4`='看来我的自由必须用鲜血去换取了！', `MaleText_loc5`='看來我的自由必須用鮮血去換取了!', `MaleText_loc7`='¡Parece que debo pagar mi libertad con sangre!' WHERE `ID`=31805;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='손 닿는 곳에 넘쳐나는 자원이라... 이런 건 써먹어 줘야지!', `MaleText_loc4`='采之不尽，用之不竭的资源……我必须要得到它！', `MaleText_loc5`='採之不盡，用之不竭的資源...我必須要得到它!', `MaleText_loc7`='Abundantes recursos explotables... ¡listos para adquirir!' WHERE `ID`=31806;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='재협상의 시간이 온 것 같군.', `MaleText_loc4`='看来我们有必要重新交涉一次。', `MaleText_loc5`='看來我們有必要重新交涉一次。', `MaleText_loc7`='Parecería ser pertinente una renegociación.' WHERE `ID`=31807;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='개인적 원한은 없다.', `MaleText_loc4`='我们其实没有个人恩怨。', `MaleText_loc5`='我們其實沒有個人恩怨。', `MaleText_loc7`='Nada personal.' WHERE `ID`=31808;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영업 종료.', `MaleText_loc4`='纯粹是为利益而已。', `MaleText_loc5`='純粹公事公辦。', `MaleText_loc7`='Asunto terminado.' WHERE `ID`=31809;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수익 달성!', `MaleText_loc4`='利益！', `MaleText_loc5`='利益!', `MaleText_loc7`='¡Beneficio!' WHERE `ID`=31810;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건... 복구할 수 없는... 손실이군.', `MaleText_loc4`='这真是个……不可挽回的……损失。', `MaleText_loc5`='這真是個...不可挽回的...損失。', `MaleText_loc7`='Es una pérdida... irrecuperable.' WHERE `ID`=31811;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자들아, 너희 승리는 덧없는 것이다. 나는 사령관인 바로스 클라우드스트라이더다. 내 비룡들이 하늘을 지키고, 이 마력의 통로를 보호하지. 분명히 말하건대, 마력의 눈을 너희에게 내주지는 않을 것이다.', `MaleText_loc4`='入侵者，你们一路的胜势到此为止了。我是指挥官瓦尔洛斯。我和飞龙们制御着这里的天空，保护着这里的管线，也将保证魔枢之眼不会落入你们的手中！', `MaleText_loc5`='入侵者，你的勝利到此為止。我是指揮官，瓦羅斯·雲行者。我的飛龍們宰制天空，保衛這條通道，我會親自確保奧核之眼不會落入你們的手中!', `MaleText_loc7`='Intrusos: su victoria será efímera. Soy el Comandante Varos Cloudstrider. Mis dracos controlan los cielos y protegen este conducto. ¡Me encargaré personalmente de que el Óculo no caiga en sus manos!' WHERE `ID`=31812;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 사전엔 자비란 없다!', `MaleText_loc4`='我是不会心慈手软的！', `MaleText_loc5`='絕不留情!', `MaleText_loc7`='¡No habrá piedad!' WHERE `ID`=31813;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적을 없애라! 날려 버려!', `MaleText_loc4`='炸死他们！摧毁他们！', `MaleText_loc5`='炸爛他們!摧毀他們!', `MaleText_loc7`='¡Dispárenles! ¡Destrúyanlos!' WHERE `ID`=31814;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타협은 없다! 공격!', `MaleText_loc4`='不留俘虏！进攻！', `MaleText_loc5`='不留活口!殺!', `MaleText_loc7`='¡Nada de prisioneros! ¡Al ataque!' WHERE `ID`=31815;
