UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들은... 너무 강하다! 그들의 힘을... 과소평가했어...', `MaleText_loc4`='他们……咳……太强大！我低估了……他们的顽强。', `MaleText_loc5`='他們...咳...太強了!低估了他們的...頑強。', `MaleText_loc7`='Son... ¡muy fuertes! Subestimé su... poderío.' WHERE `ID`=31819;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n|1과;와; 그 전우들이 어둠의 지배자 키트릭스를 물리쳤다. 다음 상대를 대기시켜라!', `FemaleText_loc4`='$n和$g他:她;的战友击败了黑暗主宰西塔利克斯。下一场挑战马上开始！', `FemaleText_loc5`='『黑暗大師』齊特瑞司被$n和$g他:她;的勇敢同伴所擊敗。讓下一場挑戰開始吧!', `FemaleText_loc7`='Khit''rix el Maestro Lóbrego ha sido derrotado por $n y sus compañeros. ¡Que comience el próximo desafío!' WHERE `ID`=31820;
