UPDATE `locales_broadcast_text` SET `MaleText_loc1`='귀한 생명을... 낭비했구나!', `MaleText_loc4`='宝贵的生命……呱呱……浪费了！', `MaleText_loc5`='珍貴的生命--喇--啊--浪費!', `MaleText_loc7`='¡Preciosa vida —ra-aak— malgastada!' WHERE `ID`=31823;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강한 놈만... 살아남는다!', `MaleText_loc4`='强大的人……呱呱……才能活下去！', `MaleText_loc5`='只有強者--嘎-喇啊--可以活下來!', `MaleText_loc7`='¡Sólo los fuertes —ka-raaak— sobrevivir!' WHERE `ID`=31824;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼... 도망갈래...', `MaleText_loc4`='没……呱……逃掉……', `MaleText_loc5`='逃--嘎，嘎--不掉...', `MaleText_loc7`='No... kaw, kaw... huir...' WHERE `ID`=31825;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛이여, 다시 한 번 기회를 허락해 주심에 감사합니다. 감사합니다, $n|1이여;여;.', `MaleText_loc4`='感谢圣光再次赐予我机会。同样谢谢你，$n。', `MaleText_loc5`='感謝聖光又給了我一次機會。感謝你，$n。', `MaleText_loc7`='Gracias a la Luz por darme otra oportunidad. Y gracias a ti, $n.' WHERE `ID`=31826;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대의 도움이 없었다면 리치 왕이 만들어 낸 끔찍한 괴물들 틈에서 영원히 죽지 못하는 저주받은 삶을 살았을 것입니다.', `MaleText_loc4`='要不是你，我早就沦为巫妖王的奴仆，成为天灾军团中的一员了。', `MaleText_loc5`='如果沒有你的幫助，我早就完蛋，淪為巫妖王的可怕不死造物。', `MaleText_loc7`='Sin tu ayuda, estaría condenado a una vida de no-muerte entre las horripilantes creaciones del Rey Exánime.' WHERE `ID`=31827;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나중에 다시 정식으로 감사드리겠습니다. 지금은 전투에 집중하십시오!', `MaleText_loc4`='稍后我会正式地感谢你，但是现在我们还有一场仗要打！', `MaleText_loc5`='晚點在進行適當的感謝，現在還有一場硬仗要打!', `MaleText_loc7`='Ya habrá tiempo para dar las gracias como es debido después, ¡pero aún tenemos una batalla que luchar!' WHERE `ID`=31828;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법의 지배자의 힘을... 약간... 아주 약간 느껴봐라!', `MaleText_loc4`='稍微见识见识吧……见识一下织法者的真正力量！', `MaleText_loc5`='稍微見識見識吧...見識一下織法者的真正力量!', `MaleText_loc7`='¡Una muestra... sólo una pequeña muestra... del poder del Tejehechizos!' WHERE `ID`=31829;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불안정한 에너지라... 하지만 네놈들을 처치하려면 위험을 감수해야지!', `MaleText_loc4`='这么多不稳定的能量……但为了消灭你们，这点风险不算什么！', `MaleText_loc5`='這麼多不穩定的能量...但為了消滅你們，這點風險不算什麼!', `MaleText_loc7`='Demasiada energía inestable... ¡pero destruirte vale el riesgo!' WHERE `ID`=31830;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 누차 얘기했건만!', `MaleText_loc4`='如果你能早点理解就好了！', `MaleText_loc5`='如果你能早點理解就好了!', `MaleText_loc7`='¡Si tan solo comprendieras!' WHERE `ID`=31831;
