UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 행한 모든 일은... 아제로스를 위한 것...', `MaleText_loc4`='我所做的一切……都是为了艾泽拉斯……', `MaleText_loc5`='我所做的一切...都是為了艾澤拉斯...', `MaleText_loc7`='Todo lo que hice... fue por Azeroth…' WHERE `ID`=31834;
