UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투가 끝나면, 너희를 아졸네룹의 성벽에 줄줄이 걸어 놓겠다!', `MaleText_loc4`='战斗结束后，我就要把你们的徽记挂在艾卓-尼鲁布的城墙上！', `MaleText_loc5`='等我解決你，我會把你們的頭顱高掛在阿茲歐-奈幽的牆上!', `MaleText_loc7`='¡Cuando acabe aquí, voy a colgar sus cabezas en las paredes de Azjol-Nerub!' WHERE `ID`=31836;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 판 유독한 음식 때문에 아내와 아이들이 아파서 누워있단 말이야!', `MaleText_loc4`='你卖的食物有毒！我的妻子和孩子都病倒了！', `MaleText_loc5`='我的妻子和小孩都因為你賣給我的毒藥而病倒在床上!', `MaleText_loc7`='¡Mi mujer y mis hijos se han puesto enfermos por el veneno que me vendiste!', `FemaleText_loc1`='당신이 판 유독한 음식 때문에 남편과 아이들이 아파서 누워있단 말이에요!', `FemaleText_loc4`='你卖的食物有毒！我的丈夫和孩子都病倒了！', `FemaleText_loc5`='我的丈夫和小孩都因為你賣給我的毒藥而病倒在床上!', `FemaleText_loc7`='¡Mi marido y mis hijos se han puesto enfermos por el veneno que me vendiste!' WHERE `ID`=31837;
