UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말 돌리며 빠져나갈 생각은 하지 않는 게 좋아!', `MaleText_loc4`='别狡辩！你脱不了干系的！', `MaleText_loc5`='別想要推託責任!', `MaleText_loc7`='¡No intentes escaquearte!', `FemaleText_loc1`='말 돌리며 빠져나갈 생각은 하지 않는 게 좋아요!', `FemaleText_loc4`='别狡辩！你脱不了干系的！', `FemaleText_loc5`='別想要推託責任!', `FemaleText_loc7`='¡No intentes escaquearte!' WHERE `ID`=31839;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저기요, 그건 제 잘못이 아니에요! 저기... 그러니까 돈을 돌려 드릴테니, 치유사에게 가보시면 되지 않겠어요? 제게서 뭘 바라시는지 모르겠네요!', `FemaleText_loc4`='根本不关我的事啊！要不……要不我赔偿啊，就诊的钱我来出？你们到底要我怎么样！', `FemaleText_loc5`='拜託，這不是我的錯!如果...如果我把錢退還給你，或許你可以去找一位醫生?我不知道你還期待我做什麼!', `FemaleText_loc7`='Por favor, ¡no es culpa mía! Si... Si te devuelvo el dinero, ¿quizá puedas hablar con un sanador? ¡No sé qué quieres que haga!' WHERE `ID`=31840;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼간이 같은 놈들! 너희가 지금 무슨 짓을 하고 있는지, 전혀 모르는구나. 지맥의 흐름을 방해하게 놔둘 것 같으냐? 내 너희를 완전히 끝장내 주마!', `MaleText_loc4`='蠢货！你们根本无法理解这种你们正在对抗着的伟大力量。魔网能量的传输是不会被你们干扰的！而你们，唯一的结局只有失败与死亡！', `MaleText_loc5`='蠢貨!你們根本無法理解甚至對抗這種偉大力量。地脈能量的傳輸是不會被干擾的!你們的結局只有失敗!', `MaleText_loc7`='¡Tontos! No comprenden las fuerzas que pusieron en movimiento. ¡El conducto de líneas ley no será afectado! ¡Su derrota será total!' WHERE `ID`=31841;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런... 됐다. 더러운 돈, 많이 챙겨둬! 그 돈 받는다고 우리 식구에겐 아무런 도움이 되지 않을 테니!', `MaleText_loc4`='呸……省省吧！不收你的钱，这也救不了我的家人！', `MaleText_loc5`='什麼...不，留著你那些髒錢吧!它幫不了我的家人!', `MaleText_loc7`='Eso...no, ¡quédate tu asqueroso dinero! ¡Eso no ayudará a mi familia!', `FemaleText_loc1`='그런... 됐어요. 더러운 돈, 많이 챙겨둬요! 그 돈 받는다고 우리 식구에겐 아무런 도움이 되지 않을 테니까요!', `FemaleText_loc4`='呸……省省吧！不收你的钱，这也救不了我的家人！', `FemaleText_loc5`='什麼...不，留著你那些髒錢吧!它幫不了我的家人!', `FemaleText_loc7`='Eso...no, ¡quédate tu asqueroso dinero! ¡Eso no ayudará a mi familia!' WHERE `ID`=31842;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 연회용 통구이를 준비합니다!', `MaleText_loc4`='%s烹制了大型筵席！', `MaleText_loc5`='%s準備了一餐盛宴!', `MaleText_loc7`='¡%s prepara un gran festín!', `FemaleText_loc1`='%s|1이;가; 연회용 통구이를 준비합니다!', `FemaleText_loc4`='%s烹制了大型筵席！', `FemaleText_loc5`='%s準備了一餐盛宴!', `FemaleText_loc7`='¡%s prepara un gran festín!' WHERE `ID`=31843;
