UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기도 열심히 해라, 이 얼라이언스 쓰레기 녀석아. 내가 너보다 빨리 일어나지 않게 해달라고 말이다.', `MaleText_loc4`='狗联盟，仰天长泣吧。你最好祈祷我的伤口没有那么快就愈合。', `MaleText_loc5`='向天國哭喊吧，聯盟雜碎。祈禱我的傷勢不要痊癒得比你快。', `MaleText_loc7`='Clama al cielo, escoria de la Alianza. Reza para que mis heridas no sanen antes que las tuyas.' WHERE `ID`=31848;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 녹색 괴물 녀석아! 그놈의 주둥아리는 지치지도 않냐. 그만 나불대라.', `MaleText_loc4`='绿皮怪！闭嘴，不然我就割下你的舌头，去喂你那群猪崽子。', `MaleText_loc5`='綠皮狗!閉嘴，否則我就把你的舌頭給割下來，拿去餵你那些像豬一樣的小孩。', `MaleText_loc7`='¡Perro de piel verde! Cállate o te cortaré la lengua y se la daré de comer a tus puercos hijos.' WHERE `ID`=31849;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 그 말 잘했다. 넌 이제 죽은 목숨이야, 이 더러운 잡종 놈아!', `MaleText_loc4`='你找死啊，杂种！', `MaleText_loc5`='你自己找死，雜種!', `MaleText_loc7`='¡ACABAS DE FIRMAR TU SENTENCIA DE MUERTE, CHUCHO!' WHERE `ID`=31850;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 볼바르를 살해했을 때 이미 죽은 목숨이었어! 이 망할 놈의 자식아!', `MaleText_loc4`='从你谋杀伯瓦尔的那天起，你就该死了！诅咒你！', `MaleText_loc5`='在你謀殺伯瓦爾的時候，你就死定了!該死的東西!', `MaleText_loc7`='¡TU FIRMASTE LA TUYA CUANDO ASESINASTE A BOLVAR! ¡MALDITO SEAS!' WHERE `ID`=31851;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제법이시군요. 솔직히 좀 놀랐습니다.', `FemaleText_loc4`='刚才的战斗给我留下了深刻的印象。', `FemaleText_loc5`='你有幾場戰鬥令人印象深刻。', `FemaleText_loc7`='Tienes sangre en las venas. Estoy impresionada.' WHERE `ID`=31852;
