UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이번 건 조금 아프셨죠?', `FemaleText_loc4`='尝到痛苦的滋味了吧。', `FemaleText_loc5`='看起來有點痛。', `FemaleText_loc7`='Eso parece un poco doloroso.' WHERE `ID`=31856;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='차라리 언데드였으면 하는 마음이 굴뚝 같죠?', `FemaleText_loc4`='现在，你肯定希望自己是个亡灵吧。', `FemaleText_loc5`='我打賭你現在一定寧願自己是不死生物。', `FemaleText_loc7`='Apuesto a que ahora desearías ser un no-muerto.' WHERE `ID`=31857;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='죽지 못하는 자들의 세계에 온 걸 환영합니다.', `FemaleText_loc4`='欢迎来到亡者的世界。', `FemaleText_loc5`='歡迎來到無生命的世界。', `FemaleText_loc7`='Te doy la bienvenida al mundo de la no-vida.' WHERE `ID`=31858;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='눈물겨워 못 보겠네요.', `FemaleText_loc4`='真是可贵的努力。', `FemaleText_loc5`='高貴的努力。', `FemaleText_loc7`='Un noble esfuerzo.' WHERE `ID`=31859;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벌써 끝낼 생각 마라. 난 아직 몸도 안 풀렸다.', `MaleText_loc4`='别停手啊，我就快出汗啦。', `MaleText_loc5`='別停下來，我差點打斷這個苦差事。', `MaleText_loc7`='No se detengan ahora, casi he empezado a sudar.' WHERE `ID`=31860;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 죽음을 모른다. 난... 다시 돌아올... 것이다...', `MaleText_loc4`='我不怕死。我会回来……找你……', `MaleText_loc5`='我不知道什麼是死亡。我會...回來...找你...', `MaleText_loc7`='No conozco la muerte. Volveré... por... ustedes…' WHERE `ID`=31861;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='승리의 맛은 언제나 달콤하군.', `MaleText_loc4`='你的血真甜。', `MaleText_loc5`='你的鮮血嚐起來好甜美。', `MaleText_loc7`='Tu sangre sabe dulce.' WHERE `ID`=31862;
