UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈의 피는 이제 나의 것이다.', `MaleText_loc4`='你的鲜血归我啦。', `MaleText_loc5`='你的鮮血現在是我的了。', `MaleText_loc7`='Tu sangre es mía ahora.' WHERE `ID`=31864;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연약한 것.', `MaleText_loc4`='脆弱的生物。', `MaleText_loc5`='脆弱的東西。', `MaleText_loc7`='Frágil cosita.' WHERE `ID`=31865;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛나는 군대도 없고, 정의로운 말도 없으니, 네 녀석의 "명예"란 것도 이제 볼 장 다 봤군.', `MaleText_loc4`='就凭你们几个？连慷慨陈词都没有？你们的“荣耀”不过如此。', `MaleText_loc5`='沒有閃亮亮的軍隊?沒有正義的言詞?看起來你的榮譽不再適合你了。', `MaleText_loc7`='¿Sin ejercito resplandeciente? ¿Sin palabras de rectitud? Parece que tu "honor" ya no va contigo.' WHERE `ID`=31866;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너의 용기는 가상하다만, 이제는 현실을 직시해야 할 때다.', `MaleText_loc4`='真是动听的豪言壮语啊，但是你们必须面对现实。', `MaleText_loc5`='多麼高貴的自吹自擂，但到最後，我們還是會把你拉回現實來。', `MaleText_loc7`='Una fanfarronada muy noble, pero al final te hemos devuelto a la realidad.' WHERE `ID`=31867;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너 역시 리치 왕을 모시게 될 것이니... 그날이 머지않았다.', `MaleText_loc4`='你终将臣服于巫妖王的意志……很快。', `MaleText_loc5`='你也會服侍巫妖王的...你的時候要到了。', `MaleText_loc7`='Tú también servirás al Rey Exánime... se acerca tu hora.' WHERE `ID`=31868;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 친구들 손보고 나면, 넌 우리의 새 수습생이 될 것이다.', `MaleText_loc4`='等我解决了你的朋友，你就会成为天灾军团的新兵了。', `MaleText_loc5`='等我解決你的朋友，你會成為我們最新的成員。', `MaleText_loc7`='Cuando acabe con tus amigos, tú serás nuestro nuevo iniciado.' WHERE `ID`=31869;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽은 뒤의 평안은 기대하지 마라. 그건 내가 보장하지.', `MaleText_loc4`='你在死后也不会得到安息的。', `MaleText_loc5`='你死後也不得安寧，我保證。', `MaleText_loc7`='No hallarás paz en la muerte, te lo prometo.' WHERE `ID`=31870;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영원한 고통이 곧 시작될 것이다.', `MaleText_loc4`='永恒的痛苦才刚刚开始。', `MaleText_loc5`='你的永恆苦難即將展開。', `MaleText_loc7`='Tu sufrimiento eterno está a punto de comenzar.' WHERE `ID`=31871;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너의 영혼은 이제 나의 것이다.', `MaleText_loc4`='你的灵魂属于我了。', `MaleText_loc5`='你的靈魂現在屬於我了。', `MaleText_loc7`='Tu alma me pertenece ahora.' WHERE `ID`=31872;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무례한 침입자 놈들, 정신이 나갔구나! 저 아래 내던져 주마!', `MaleText_loc4`='你们这些莽撞的入侵者已经无计可施了！我要亲自把你们碾碎！', `MaleText_loc5`='你們這些莽撞的入侵者已經無計可施了!我要親自把你們碾碎!', `MaleText_loc7`='¡Este no es su lugar, insolentes intrusos! ¡Los devolveré a tierra!' WHERE `ID`=31873;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무례하고, 오만한 것들... 가만두지 않겠다!', `MaleText_loc4`='如此肆意妄为，如此骄纵轻狂……必须惩罚你们！', `MaleText_loc5`='如此肆意妄為!如此驕縱輕狂...必須懲罰你們!', `MaleText_loc7`='Esa insolencia... esa arrogancia... ¡debe ser CASTIGADA!' WHERE `ID`=31874;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자연의 마법은 이제 너희 편이 아니다.', `MaleText_loc4`='自然魔法现在帮不了你们啦！', `MaleText_loc5`='沒有任何魔法能幫得了你們啦!', `MaleText_loc7`='¡No hay magia de la naturaleza que te ayude!' WHERE `ID`=31875;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비전 마력은 우리의 것! 우리에게 해를 끼치지 않는다.', `MaleText_loc4`='奥术魔法归我们号令！休想用它来对付我们！', `MaleText_loc5`='秘法歸我們號令!休想用它來對付我們!', `MaleText_loc7`='¡Nosotros controlamos lo arcano! ¡No se empleará en nuestra contra!' WHERE `ID`=31876;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불길을 잡는 건 식은 죽 먹기지.', `MaleText_loc4`='熄灭你们的小火苗，完全没有难度！', `MaleText_loc5`='熄滅你們的小火苗，完全沒有難度!', `MaleText_loc7`='¡Qué sencillo es extinguir tu fuego!' WHERE `ID`=31877;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한참을 추락할 것이다...', `MaleText_loc4`='这可要很久才能落地的……', `MaleText_loc5`='往下的距離還遠著呢...', `MaleText_loc7`='Es una gran caída…' WHERE `ID`=31878;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기 땅에서나 놀아라!', `MaleText_loc4`='回到尘土中去！', `MaleText_loc5`='下去啃泥吧!', `MaleText_loc7`='¡Vuelve a la tierra!' WHERE `ID`=31879;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='떨어지니 즐거우냐?', `MaleText_loc4`='好好享受坠落的快感！', `MaleText_loc5`='好好享受墜落的快感!', `MaleText_loc7`='¡Disfruta la caída!' WHERE `ID`=31880;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하찮은 승리에 도취할 것 없다, 어리석은 생명체여. 너희와 다른 용군단이 여기선 이겼을지 모르나, 우리는... 마력 전쟁에서... 승리할 것이다.', `MaleText_loc4`='好好珍惜这场胜利吧，愚蠢的低等动物。你们和你们的龙类盟友或许赢得了这次战役，但我们……才是整个魔枢战争的胜利者。', `MaleText_loc5`='好好珍惜這場勝利吧，愚蠢的低等動物。你們和你們的龍類盟友或許贏得了這次戰役，但我們將會獲得...奧核之戰的最後勝利。', `MaleText_loc7`='Disfruten esta victoria menor, ridículas criaturas. Ustedes y sus aliados dragones ganaron esta batalla, pero nosotros ganaremos... la Guerra de Nexus.' WHERE `ID`=31881;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이놈, 거기 있었구나! 나를 기억하나? 당연히 기억해야지! 기다려라, 내가 그쪽으로 가마.', `FemaleText_loc4`='啊，是你！还记得我吗？我相信你记得！等着吧，我这就下来。', `FemaleText_loc5`='喔，你在這裡!記得我嗎?你當然記得!在那邊等一下，我馬上下來。', `FemaleText_loc7`='Ah, ahí estás. ¿Te acuerdas de mí? ¡Claro que sí! Espera, que bajo.' WHERE `ID`=31882;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다음번에 만날 땐 단단히 준비해야 할 거라고 내가 말하지 않았는가? 난 내 힘으로 힐드스미트를 통과했고, 발키리온에서 훈련을 받았지. 그리고 지금 이 자리에 왔다. 자, 덤벼라!', `FemaleText_loc4`='我说过，下次见面时，我会做好充分的准备。我取得了海德比武会的胜利，在瓦基里安接受了严酷的训练。今非昔比，尝尝我的厉害吧！', `FemaleText_loc5`='我告訴過你，在我們下次見面的時候要做好準備。我參與了海茲競技並且獲得了勝利，我還在華爾基倫接受訓練，而現在我在這兒。來吧!', `FemaleText_loc7`='Te dije que estaría mejor preparada cuando volviéramos a encontrarnos. He luchado y he vencido en El Encuentro Hyldnir, he entrenado en Valkyrion y aquí estoy. ¡Ven a recibir!' WHERE `ID`=31883;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='심연의 비밀은 계속 비밀로 남을 것이다.', `MaleText_loc4`='深渊的秘密，就永远留在深渊之中吧。', `MaleText_loc5`='深埋的秘密應該要繼續隱藏。', `MaleText_loc7`='Los secretos de lo profundo permanecerán ocultos.' WHERE `ID`=31884;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='살육자가 다가오고 있다! 명심하라. 어떤 경우에도 절대 투기장을 떠나서는 안 된다. 투기장을 떠나면 너와 네 전우는 실격될 것이다.', `FemaleText_loc4`='卡纳基来啦！记住，在任何情况下，都不能离开比武场，否则就取消你们的参赛资格。', `FemaleText_loc5`='卡納基要來了!記得，不管如何都不要離開競技場，否則我就得判你和你的隊伍出局。', `FemaleText_loc7`='¡Se acerca Carnicería! Recuerda, pase lo que pase, NO salgas del anillo de batalla u os descalificaré a ti y a tu grupo.' WHERE `ID`=31885;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어린애가 배를 곯아선 안 되지...', `MaleText_loc4`='幼体可千万不能饿着了……', `MaleText_loc5`='別讓幼蟲給餓著了...', `MaleText_loc7`='Los jóvenes no deben pasar hambre.' WHERE `ID`=31886;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샤드 아크 케리쉬... 샤칵칵칵칵!', `MaleText_loc4`='Shhhad ak kereeesshh chak-k-k！', `MaleText_loc5`='(蟲族語)你可是一頓大餐!', `MaleText_loc7`='¡Shhhad ak kereeesshh chak-k-k!' WHERE `ID`=31887;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='차가운 어둠 속에 잠들거라...', `MaleText_loc4`='在寒冷的黑暗中长眠吧……', `MaleText_loc5`='在寒冷的黑暗中長眠吧...', `MaleText_loc7`='Ahora duerme en la fría noche…' WHERE `ID`=31888;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕을 위하여!', `MaleText_loc4`='为了巫妖王！', `MaleText_loc5`='為了巫妖王!', `MaleText_loc7`='¡Por el Rey Exánime!' WHERE `ID`=31889;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 곧 같은 편이 될지도 모른다.', `MaleText_loc4`='或许你很快就要成为我的盟友啦。', `MaleText_loc5`='或許我們很快就能變成盟友。', `MaleText_loc7`='Tal vez pronto seamos aliados.' WHERE `ID`=31890;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님... 제 임무는 이제... 끝입니까?', `MaleText_loc4`='主人……我的使命……结束了吗？', `MaleText_loc5`='主人...我的使命...結束了嗎?', `MaleText_loc7`='¿Amo... mi tarea está... cumplida?' WHERE `ID`=31891;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='시그리드 아이스본이 $n|1을;를; 상대로 자신의 힘을 시험하고자 요툰하임의 고원에서 돌아왔다. 이들이 마지막으로 전투에서 만났을 땐 $n|1이;가; 승리를 거두었다. 이번에는 어떤 결과가 나올지 지켜보자.', `FemaleText_loc4`='齐格莉德·冰魂已经重返尤顿海姆，她将与$n展开对决。他们上次交手时，$n战胜了她。这场比赛的胜负如何呢？让我们拭目以待吧！', `FemaleText_loc5`='席格芮·冰誕回到了卓頓海姆高地來對抗$n。上次相見時，$n在個人戰鬥中擊敗了她。讓我們來瞧瞧這次戰鬥的結果是什麼。', `FemaleText_loc7`='Sigrid Hielonato ha regresado desde lo alto de Jotunheim para mostrar lo que vale contra $n. La última vez que se enfrentaron, $n venció en un combate personal. Veamos cómo acaba este encuentro.' WHERE `ID`=31892;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가... 좋아하는 녀석! 악 악 아악!', `MaleText_loc4`='我……呱呱……最喜欢的！哇哇哇！呱呱！', `MaleText_loc5`='我--喇啊--的最愛!嘎嘎嘎!喇嘎!', `MaleText_loc7`='¡Mi —raaak— favorito! ¡Ohk ohk oohk! ¡Raa-kaa!' WHERE `ID`=31893;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안카하르 수호자가 깨어납니다!', `MaleText_loc4`='一只安卡哈守护者孵化了！', `MaleText_loc5`='一個安卡哈守護者孵化了!', `MaleText_loc7`='¡Surge un guardián Ahn''kahar!' WHERE `ID`=31894;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희의 종말에 축배를 들겠노라!', `MaleText_loc4`='我要吞噬你们的尸体！', `MaleText_loc5`='我將會享用你們的屍體!', `MaleText_loc7`='¡Devoraré tus restos!' WHERE `ID`=31895;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 심장 소리가... 나에겐 음악과도 같구나.', `MaleText_loc4`='你的心跳在我耳中就是最美妙的音乐。', `MaleText_loc5`='你的心跳在我耳中就是最美妙的音樂。', `MaleText_loc7`='Tus latidos son... música para mis oídos.' WHERE `ID`=31896;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 어디에도 없다. 나는 어디에든 있다. 난 보이지 않는 감시자다...', `MaleText_loc4`='我在，我亦不在。我就是那无形无迹的监视者。', `MaleText_loc5`='我既不存在...又無所不在。我是無形無跡的監視者。', `MaleText_loc7`='Estoy en ninguna parte... Estoy en todas partes. Soy el vigilante oculto.' WHERE `ID`=31897;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주... 감미롭군.', `MaleText_loc4`='不错的开胃菜。', `MaleText_loc5`='多...美味。', `MaleText_loc7`='Tan... apetitoso.' WHERE `ID`=31898;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신선하고 따뜻한 피... 아, 너무 오랜만이야.', `MaleText_loc4`='新鲜的肉，温暖的血……好久没有尝到了。', `MaleText_loc5`='新鮮而溫熱的血...好久沒有嚐到了。', `MaleText_loc7`='Sangre fresca y tibia... hacía tanto tiempo.' WHERE `ID`=31899;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빈 도레이 암오벨!', `MaleText_loc4`='Bin dorei am''ovel！', `MaleText_loc5`='(薩拉斯語)你的血液是屬於我的!', `MaleText_loc7`='¡Bin dorei am''ovel!' WHERE `ID`=31900;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='축배는 일을 끝내고 나서 들겠다.', `MaleText_loc4`='我已经很久没有痛饮过鲜血了。', `MaleText_loc5`='時候到了我才會暢飲鮮血。', `MaleText_loc7`='No beberé sangre antes de tiempo.' WHERE `ID`=31901;
