UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여전히... 배고프다. 여전히... 목마르다.', `MaleText_loc4`='我依然这么饿。我依然……这么……渴。', `MaleText_loc5`='我依舊飢餓。依舊...乾渴。', `MaleText_loc7`='Aún tengo hambre. Aún... tengo... sed.' WHERE `ID`=31903;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새카맣게 타버릴 줄 알아라!', `MaleText_loc4`='你们烧焦的骨头正好可以用来装饰地板！', `MaleText_loc5`='你焦黑的骨頭將會鋪滿整個房間!', `MaleText_loc7`='¡Los huesos carbonizados se desparramarán por el suelo!' WHERE `ID`=31904;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뜨거운 맛 좀 보여줄까...', `MaleText_loc4`='你们能承受多高的温度呢？', `MaleText_loc5`='你們能承受多高的溫度呢?', `MaleText_loc7`='¿Qué temperatura pueden soportar?' WHERE `ID`=31905;
