UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 아이들에게 좋은 먹잇감이 되겠어.', `MaleText_loc4`='你或许会是孩子们最好的晚餐。', `MaleText_loc5`='你可以成為雛龍的一餐點心。', `MaleText_loc7`='Servirás de buen alimento para las crías.' WHERE `ID`=31908;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어차피 너흰 상대가 안 돼.', `MaleText_loc4`='你们真是占尽了下风。', `MaleText_loc5`='你們已陷入絕境。', `MaleText_loc7`='Tienes todas las de perder.' WHERE `ID`=31909;
