UPDATE `locales_broadcast_text` SET `MaleText_loc1`='결국엔 너 혼자 남을 텐데.', `MaleText_loc4`='你将孤独地走向生命的终点。', `MaleText_loc5`='你終將孤獨一人。', `MaleText_loc7`='Al final estarás solo.' WHERE `ID`=31911;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='믿음이란 너의 약점이지.', `MaleText_loc4`='信任他人是你最大的弱点。', `MaleText_loc5`='信任是你的弱點。', `MaleText_loc7`='La confianza es tu debilidad.' WHERE `ID`=31912;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소망은 환상일 뿐.', `MaleText_loc4`='希望是无谓的幻象。', `MaleText_loc5`='希望是無謂的幻象。', `MaleText_loc7`='La esperanza es una ilusión.' WHERE `ID`=31913;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 아는 모든 것이 사라지리라.', `MaleText_loc4`='你所知的一切都将消逝。', `MaleText_loc5`='你所知的一切都將消逝。', `MaleText_loc7`='Todo tu conocimiento se perderá.' WHERE `ID`=31914;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 미친 짓입니다! 이 어리석은 전투를 중단하십시오!', `MaleText_loc4`='你们疯了吗？停止这愚蠢的战斗！', `MaleText_loc5`='這太瘋狂了!結束這愚蠢的戰鬥!', `MaleText_loc7`='¡Esto es una locura! ¡Detened esta estúpida batalla!' WHERE `ID`=31915;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형제자매여, 우리는 하나로 뭉쳐야 합니다! 서로 분열된 상황에서는 절대 리치 왕을 물리칠 수 없습니다!', `MaleText_loc4`='兄弟姐妹们，我们必须保持团结！如果我们闹起了内部分裂，还怎么战胜巫妖王！', `MaleText_loc5`='兄弟姊妹們，我們必須要保持團結!分裂是絕對無法打倒巫妖王的!', `MaleText_loc7`='¡Hermanos y hermanas, debemos permanecer unidos! ¡El Rey Exánime nunca caerá a manos de un mundo dividido!' WHERE `ID`=31916;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대들이 지금 리치 왕의 손에 놀아나고 있다는 걸 모르시겠습니까? 그가 노리는 건 서로가 서로를 죽이는 것입니다!', `MaleText_loc4`='难道你们没有发现自己中了巫妖王的圈套？他就是希望你们自相残杀啊！', `MaleText_loc5`='你們難道看不出來你們被巫妖王玩弄於掌心?他要你們自相殘殺!', `MaleText_loc7`='¿No ven que están haciendo justo lo que el Rey Exánime quiere? ¡Quiere que se maten entre ustedes!' WHERE `ID`=31917;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은빛십자군에 합류하십시오! 하나가 되어, 우린 리치 왕을 쓰러뜨릴 것입니다!', `MaleText_loc4`='加入银色北伐军吧！只要我们团结起来，就一定能消灭巫妖王！', `MaleText_loc5`='加入銀白十字軍!只要團結，我們就能消滅巫妖王!', `MaleText_loc7`='¡Uníos a la Cruzada Argenta! ¡Unidos destruiremos al Rey Exánime!' WHERE `ID`=31918;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형제자매여, 심판의 날이 다가오고 있습니다! 그날을 맞을 준비가 되었습니까?', `MaleText_loc4`='审判之日已经来临，兄弟姐妹们！你们准备好了吗？', `MaleText_loc5`='審判日將臨，兄弟姊妹們!你們準備好了嗎?', `MaleText_loc7`='¡El día del Juicio se acerca, hermanos y hermanas! ¿Estaréis preparados?' WHERE `ID`=31919;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스를 공격하는 데 우리가 얼마나 많은 힘을 허비하고 있습니까?', `MaleText_loc4`='为了攻击联盟，我们浪费了多少力气？', `MaleText_loc5`='我們有多少的力氣是浪費在攻擊聯盟之上?', `MaleText_loc7`='¿Cuántos esfuerzos estamos malgastando al atacar a la Alianza?' WHERE `ID`=31920;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n|1이;가; 이번에도 시그리드 아이스본을 물리쳤다. 비록 전우들의 도움을 받았다고는 하나, 어쨌든 승리는 승리다.', `FemaleText_loc4`='$n再次击败了齐格莉德·冰魂。好吧，虽然$g他:她;是在队友的帮助下获胜的，但是胜利就是胜利！', `FemaleText_loc5`='$n再次擊敗了席格芮·冰誕。很好，這次$g他:她;靠著$g他:她;的朋友，但勝利就是勝利!', `FemaleText_loc7`='$n ha derrotado a Sigrid Hielonato por segunda vez. Bueno, esta vez lo ha conseguido con la ayuda de sus amigos, ¡pero ha ganado de todas formas!' WHERE `ID`=31921;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 하나가 되어 진정한 위협에 대비해야 합니다. 그 위협이 무엇이겠습니까? 바로 리치 왕입니다!', `MaleText_loc4`='我们必须团结起来，一致对抗真正的威胁：巫妖王！', `MaleText_loc5`='我們必須要團結，集中所有的注意力在真正的威脅:巫妖王之上!', `MaleText_loc7`='Debemos unirnos y concentrarnos en la verdadera amenaza: ¡EL REY EXÁNIME!' WHERE `ID`=31922;
