UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지하 전당 깊숙한 곳에서 살육자가 다가오고 있다. 용맹하고 어리석은 $n|1이;가; 도전을 받아들였구나. $g그:그녀;와 그 전우들은 이 괴물을 상대할 준비를 해라.', `FemaleText_loc4`='卡纳基来自曲径幽深的地下大厅。勇敢又愚蠢的$n已经接受了这个挑战。$G他:她;将率领自己的队伍面对这个怪物。', `FemaleText_loc5`='卡納基來自地下大廳的深處。勇敢而愚蠢的$n已經接受了挑戰。$g他:她;的隊伍已經準備好面對這醜陋的怪物。', `FemaleText_loc7`='Carnicería llega desde las entrañas de Las Cámaras Subterráneas. $gEl insensato:La insensata; y valiente $n ha aceptado el desafío. $gÉl:Ella; y su grupo están preparados para enfrentarse a la monstruosidad.' WHERE `ID`=31930;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='살육자로 불렸던 공포의 대상은 이제 사라졌다. 어쩌면 $n|1이;가; 발할라스의 전투에 진정으로 걸맞은 전사인지도 모르지 않겠는가? 좀 더 지켜보겠다.', `FemaleText_loc4`='可怕的卡纳基已经不复存在啦。$n真的配得上瓦哈拉斯的战斗吗？让我们拭目以待吧。', `FemaleText_loc5`='我們只知道這恐怖的生物叫做卡納基，其他一無所知。或許這是$n在英靈殿中面臨最有挑戰性的戰鬥?我們很快就會知道。', `FemaleText_loc7`='El horror conocido como Carnicería ya no existe. ¿Es posible que $n realmente sea $gdigno:digna; de luchar en Valhalas? Ya veremos.' WHERE `ID`=31931;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으윽... 날 두고... 가시오.$b$b난 이미... 틀렸소...', `MaleText_loc4`='呃……别……别管我。$b$b我……没救了……', `MaleText_loc5`='呃啊啊...別...理我。$b$b我...快...死了...', `MaleText_loc7`='Uhnhh... No te preocupes por mí.$B$BEs... el final...', `FemaleText_loc1`='으윽... 날 두고... 가세요.$b$b난 이미... 틀렸어요...', `FemaleText_loc4`='呃……别……别管我。$b$b我……没救了……', `FemaleText_loc5`='呃啊啊...別...煩我。$b$b我...已經...要結束了...', `FemaleText_loc7`='Uhnhh... No te preocupes por mí.$B$BEs... el final...' WHERE `ID`=31932;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스컬지에 대한... 정보를... 수집 중이었소.$b$b얼라이언스 병력이 나타났...$b$b우린 몸을 숨기고... 그들이 관문을 공격하기를 기다리다가... 뒤에서 그들을 쳤소.$b$b우리와... 스컬지가... 앞뒤로 밀어붙이니 당해낼 재간이 있겠소...$B$B$g 형제:자매;여... 정말... 영광스러운 순간이었소.', `MaleText_loc4`='收集……天灾军团的……情报。$b$b联盟的军队出现了……$b$b我们躲了起来，接着他们开始攻打大门……然后我们从背后发动了袭击。$b$b三方展开了混战……但是天灾军团……数量太多了……$b$b我的$g兄弟:姐妹;……那真是一场……荣耀的战斗。', `MaleText_loc5`='收集...天譴軍團的...情報。$b$b聯盟部隊出現...$b$b我們尋找掩護 - 等待他們攻擊大門...之後，我們從後面偷襲他們。$b$b被夾在我...和天譴軍中間...讓他們無法承受...$b$b$g兄弟:姊妹;...這很...壯觀。', `MaleText_loc7`='Reuniendo... información... sobre la Plaga.$B$BLlegaron tropas de la Alianza... $B$BNos escondimos... esperamos hasta que atacaron la puerta... entonces, atacamos por detrás.$B$BAtrapados entre nosotros... y la Plaga... demasiado para ellos...$B$B$gHermano:Hermana;... ha sido glorioso.', `FemaleText_loc1`='스컬지에 대한... 정보를... 수집 중이어요.$b$b얼라이언스 병력이 나타났...$b$b우린 몸을 숨기고... 그들이 관문을 공격하기를 기다리다가... 뒤에서 그들을 쳤어요.$b$b우리와... 스컬지가... 앞뒤로 밀어붙이니 당해낼 재간가 있겠어요...$B$B$g 형제:자매;여... 정말... 영광스러운 순간이었어요.', `FemaleText_loc4`='收集……天灾军团的……情报。$b$b联盟的军队出现了……$b$b我们躲了起来，接着他们开始攻打大门……然后我们从背后发动了袭击。$b$b三方展开了混战……但是天灾军团……数量太多了……$b$b我的$g兄弟:姐妹;……那真是一场……荣耀的战斗。', `FemaleText_loc5`='收集...天譴軍團的...情報。$b$b聯盟部隊出現...$b$b我們尋找掩護 - 等待他們攻擊大門...之後，我們從後面偷襲他們。$b$b被夾在我...和天譴軍中間...讓他們無法承受...$b$b$g兄弟:姊妹;...這很...壯觀。', `FemaleText_loc7`='Reuniendo... información... sobre la Plaga.$B$BLlegaron tropas de la Alianza... $B$BNos escondimos... esperamos hasta que atacaron la puerta... entonces, atacamos por detrás.$B$BAtrapados entre nosotros... y la Plaga... demasiado para ellos...$B$B$gHermano:Hermana;... ha sido glorioso.' WHERE `ID`=31933;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조금만 참으십시오, 친구여. 여기서 무슨 일이 있었던 겁니까?', `MaleText_loc4`='坚持住，朋友。告诉我究竟发生了什么事。', `MaleText_loc5`='等等，朋友。告訴我到底發生什麼事。', `MaleText_loc7`='Aguanta, colega. Cuéntame qué ha pasado aquí.', `FemaleText_loc1`='조금만 참으십시오, 친구여. 여기서 무슨 일이 있었던 겁니까?', `FemaleText_loc4`='坚持住，朋友。告诉我究竟发生了什么事。', `FemaleText_loc5`='等等，朋友。告訴我到底發生什麼事。', `FemaleText_loc7`='Aguanta, colega. Cuéntame qué ha pasado aquí.' WHERE `ID`=31934;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만! 너희 같은 버러지는 이 신성한 장소에 들어올 자격조차 없다! 명예는 내팽개쳐 버렸군! 나아지는 모습도 없어!', `MaleText_loc4`='够了！你们这些爬虫也配在这片圣地上战斗！你们的战斗有何荣誉可言！别想战胜我！', `MaleText_loc5`='夠了!你這卑微的小蟲根本不配在這神聖的地方戰鬥!你根本不是憑著榮譽在戰鬥!你甚至不會飛升!', `MaleText_loc7`='¡BASTA! ¡Pequeños insectos, no sois dignos de luchar en este sagrado lugar! ¡No lucháis con honor! ¡Ni siquiera ascendéis!' WHERE `ID`=31935;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 공격을 받고 죽어라, 이 겁쟁이들아!', `MaleText_loc4`='来受死吧，懦夫！', `MaleText_loc5`='和我一戰然後死吧，懦夫!', `MaleText_loc7`='¡Luchad contra mí y morid, cobardes!' WHERE `ID`=31936;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='북서쪽에서 시그리드 아이스본이 다가오는 소리가 들린다. 그녀에게는 전투에서 원시비룡을 사용할 수 없다고 말해 두었다. 투기장을 벗어나지 마라!', `FemaleText_loc4`='我听见齐格莉德·冰魂的声音从西北方传来。我们已经告知她不得在比武场中使用始祖龙。不要离开竞技场！', `FemaleText_loc5`='我可以聽到席格芮·冰誕從西北方靠近。她被告知不能在這場戰鬥中使用她的元龍。不要離開競技場!', `FemaleText_loc7`='Puedo oír a Sigrid Hielonato acercándose por el noroeste. Le han avisado de que no puede usar su protodraco durante la batalla. ¡No abandones el anillo de batalla!' WHERE `ID`=31937;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='남동쪽을 보면 무자비한 요너 근처에서 영주가 곧 모습을 드러낼 것이다. 그가 내려오도록 놔두어라. 발할라스의 투기장을 벗어나선 안 된다.', `FemaleText_loc4`='往东南方看，领主很快就会出现在残忍的亚纳尔附近的平台上。等他自己下来。不要离开瓦哈拉斯的竞技场。', `FemaleText_loc5`='看向東南方，等他出現的時候你可以看到他會在『殘酷』吉雍納附近的平臺上。等他下來。並且待在英靈殿的戰鬥競技場中。', `FemaleText_loc7`='Mira al sureste y verás al señor feudal sobre la plataforma cerca de Gjonner el Desalmado cuando se muestre. Deja que baje. Quédate dentro del anillo de Valhalas.' WHERE `ID`=31938;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 투기장이 브리쿨의 것임을 증명하려고 영주 바나호그가 오랜만에 발할라스로 돌아왔다. $n|1은;는; 바나호그가 틀렸음을 보여줄 것인가?', `FemaleText_loc4`='数个世纪后，巴纳霍格领主首次重返瓦哈拉斯。他要证明，只有维库人才有资格在这片圣地上战斗。$n能证明他错了吗？', `FemaleText_loc5`='許多年來巴納霍格族長又一次回到英靈殿，要證明維酷人才是唯一配在這個神聖的競技場中戰鬥的生物。$n能證明他是錯的嗎?', `FemaleText_loc7`='El señor feudal Banahogg regresa a Valhalas por primera vez desde hace años para demostrar que solo los vrykuls son dignos de luchar en este sagrado anillo. ¿Le demostrará $n que se equivoca?' WHERE `ID`=31939;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n|1과;와; 그 전우들이 죽음의 손 바나호그를 쓰러뜨렸다. 이제 남은 도전자는 단 하나. 마지막 상대는 과연 누가 될 것인가?', `FemaleText_loc4`='巴纳霍格领主败在了$n和$g他:她;的战友手下。挑战者即将迎来最后一场对决。他们的对手是谁呢？', `FemaleText_loc5`='『死擊』巴納霍格族長敗給了$n和和$g他的:她的;戰友。$G他:她;還剩下一場挑戰。到底會是誰呢?', `FemaleText_loc7`='El señor feudal Banahogg, la "Arremetida mortal", ha caído ante $n y sus compañeros de lucha. Ya solo le queda un desafío por delante. ¿Quién será?' WHERE `ID`=31940;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어려울 때 도와주셔서 감사합니다, $n. 빛의 가호가 함께하길.', `MaleText_loc4`='$n，在我最需要帮助的时候，是圣光的赐福让你找到了我。', `MaleText_loc5`='聖光祝福你，在我需要的時候給我幫助，$n。', `MaleText_loc7`='Que la Luz te bendiga por ayudarme cuando estaba necesitado, $n.' WHERE `ID`=31941;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳은 이제 지긋지긋합니다. 어서 출발합시다.', `MaleText_loc4`='我受够这个鬼地方了。我们走吧。', `MaleText_loc5`='我已經完成在此地的任務。讓我們離開吧。', `MaleText_loc7`='Me he hartado de este lugar. Vámonos.' WHERE `ID`=31942;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 목숨을 구해주셔서 감사합니다. 동료들에게 돌아가 당신의 용맹함을 널리 알리겠습니다. 온 힘을 다해 스컬지와 맞서 주십시오. 우리들이 곁에서 응원하겠습니다.', `MaleText_loc4`='谢谢你救了我。回去之后，我一定会向大家宣扬你的勇敢。请你竭尽所能，与天灾军团抗衡吧。我们会帮助你的。', `MaleText_loc5`='我感謝你救了我一命。我會回去告訴我的夥伴關於你的英勇事蹟。全力和天譴軍團戰鬥吧，我們會與你並肩作戰。', `MaleText_loc7`='Te debo la vida. Regresaré junto a mis compañeros y haré que todos oigan hablar de tu valor. Lucha contra la Plaga con toda la fuerza que puedas reunir y nosotros estaremos junto a ti.' WHERE `ID`=31943;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 형제들에게 제가 살아있음을 알려야 합니다.', `MaleText_loc4`='请转告我的兄弟，我还活着。', `MaleText_loc5`='你一定要告訴我的兄弟們，我還活著。', `MaleText_loc7`='Debes decir a mis hermanos que sigo vivo.' WHERE `ID`=31944;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='생각지도 못했던 일이 벌어졌다... $n|1이;가; 산도발 공작을 물리쳤다!', `FemaleText_loc4`='难以置信啊……$n杀死了萨杜瓦尔王子！', `FemaleText_loc5`='不可置信的事情發生了...$n殺死了薩杜瓦爾親王!', `FemaleText_loc7`='Ha sucedido lo impensable... ¡$n ha matado al príncipe Sandoval!' WHERE `ID`=31945;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n|1과;와; 그 전우들은 공작을 쓰러뜨렸다. 브리쿨의 가장 명예스럽고 신성한 장소에서 전투를 벌일 자격이 있음을 입증한 것이다.', `FemaleText_loc4`='挑战者击败了王子，这证明$g他:她;及其战友完全有资格在维库人的圣地上战斗！', `FemaleText_loc5`='在打倒王子後，$g他:她;和$g他:她;的戰鬥夥伴證明了自己有十足的資格能在維酷榮譽中最神聖的地方戰鬥。', `FemaleText_loc7`='Al derrotarlo, $gél:ella; y sus compañeros en la lucha han demostrado ser dignos de pelear en este lugar sagrado de honor vrykul.' WHERE `ID`=31946;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='심판의 날이 머지않았습니다. 마음을 들여다보십시오. 오직 정의를 통해서만 진리에 이를 수 있음을 그대는 알고 있습니다.', `MaleText_loc4`='审判之日即将来临。你深知正义才是唯一正确的道路。', `MaleText_loc5`='審判的時候近了。在你的心中，你很清楚正義是唯一真正的道路。', `MaleText_loc7`='El día del juicio se acerca. En el fondo de tu corazón, sabes que la justicia es el único camino verdadero.' WHERE `ID`=31947;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='발할라스의 용사 $n에게 모두 경의를!', `FemaleText_loc4`='向$n，瓦哈拉斯的勇士欢呼吧！', `FemaleText_loc5`='替$n歡呼，英靈殿的勇士!', `FemaleText_loc7`='¡TODOS SALUDAD A $n, CAMPEÓN DE VALHALAS!' WHERE `ID`=31948;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='도망치기엔 이미 늦었다. 투기장을 벗어나지 마라. 전사답게 죽어라, $n!', `FemaleText_loc4`='现在逃跑已经太迟啦。不要离开比武场。慷慨地赴死吧，$n！', `FemaleText_loc5`='現在才想逃跑已經太遲了。別離開競技場。勇敢地死去吧，$n!', `FemaleText_loc7`='Ya es demasiado tarde para huir. No abandones el anillo. ¡Muere valientemente, $n!' WHERE `ID`=31949;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛의 심판을 받을지어다!', `MaleText_loc4`='接受圣光的审判吧！', `MaleText_loc5`='面對聖光的審判!', `MaleText_loc7`='¡Enfréntate al juicio de la Luz!' WHERE `ID`=31950;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='리치 왕의 선택을 받은 자가 $n|1과;와; 그 전우들을 처리하기 위해 얼음왕관 성채 깊은 곳에서 이곳으로 다가오고 있다.', `FemaleText_loc4`='挑战者的对手来自冰冠堡垒，这位被巫妖王选中的勇士是来终结$n及其战友的生命的。', `FemaleText_loc5`='來自冰冠城塞的深處，巫妖王欽選的戰士將要抹殺$n與$g他:她;朋友的存在。', `FemaleText_loc7`='Desde las profundidades de Ciudadela de la Corona de Hielo, uno de los elegidos del Rey Exánime viene para poner fin a la existencia de $n y sus amigos.' WHERE `ID`=31951;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 죽는 한이 있어도, 절대 네놈들에게 잡혀가진 않을 것이다!', `MaleText_loc4`='休想活捉我！', `MaleText_loc5`='你休想活捉我!', `MaleText_loc7`='¡No me cogerás con vida!' WHERE `ID`=31952;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은빛십자군에게 항복은 없다!', `MaleText_loc4`='银色北伐军决不投降！', `MaleText_loc5`='銀白十字軍絕不投降!', `MaleText_loc7`='¡La Cruzada Argenta nunca se rinde!' WHERE `ID`=31953;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형제들이여, 나를 용서해 주게. 내가 일을 그르쳐 버렸구려...', `MaleText_loc4`='原谅我，兄弟们，我让你们失望了……', `MaleText_loc5`='原諒我，兄弟們，我讓你們失望了...', `MaleText_loc7`='Perdonadme, hermanos, pues os he fallado...' WHERE `ID`=31954;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='요툰하임의 전사들이여, 너희에게 소개하노니, 피의 공작 산도발이다!', `FemaleText_loc4`='尤顿海姆的战士们，他就是血精灵王子萨杜瓦尔！', `FemaleText_loc5`='卓頓海姆的戰士們，我向你們介紹，薩杜瓦爾親王!', `FemaleText_loc7`='¡Guerreros de Jotunheim, os presento al príncipe de sangre Sandoval!' WHERE `ID`=31955;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 소개가 그 정도밖에 안 되오, 가이르 부인? 자, 사람들 입에 그렇게 오르내리던 이방인이 대체 누굽니까?', `MaleText_loc4`='亲爱的，你的介绍可不怎么得体。那么，这位声名大噪的挑战者是谁呢？', `MaleText_loc5`='很難有個適當的介紹，矛妻。現在，誰是那個我一直有所耳聞的外來者?', `MaleText_loc7`='No se puede decir que haya sido una introducción digna, mujer de la lanza. Veamos, ¿quién es $gese forastero:esa forastera; de quien tanto he oído hablar?' WHERE `ID`=31956;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최대한 짧고 간결하게 이야기 하마. 이리 와서 그냥 죽어라. 네가 한 짓에 대해 내가 해줄 수 있는 건 그것뿐이다. 이 신성한 전투의 장을 더럽힌 대가다.', `MaleText_loc4`='我会尽量让你死个痛快的。过来受死吧。你侵犯并玷污了这座神圣的比武场，而我只要求你用性命赎罪罢了。', `MaleText_loc5`='我會讓這件事情盡可能地簡單一點。你只要過來然後受死就行了。這就是我對你所造成一切干擾的唯一要求。為你玷污這崇高的戰鬥聖地付出一點代價。', `MaleText_loc7`='Haré que esto te resulte lo más fácil posible. Solo ven aquí y muere. Eso es todo lo que pido por tus múltiples allanamientos. Por mancillar este exaltado lugar de batalla.' WHERE `ID`=31957;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 명예롭게 싸웠습니다.. 당신의 승리를 모든 호드 동지들에게 전하겠습니다.', `MaleText_loc4`='你光荣地完成了任务……我会让整个部落都知道你获胜的消息的。', `MaleText_loc5`='你光榮地服役。我應該讓部落所有人都知道你的勝利。', `MaleText_loc7`='Has servido con honor. Haré que toda la Horda se entere de tu victoria.', `FemaleText_loc1`='당신은 명예롭게 싸웠습니다.. 당신의 승리를 모든 호드 동지들에게 전하겠습니다.', `FemaleText_loc4`='你光荣地完成了任务……我会让整个部落都知道你获胜的消息的。', `FemaleText_loc5`='你光榮地服役。我應該讓部落所有人都知道你的勝利。', `FemaleText_loc7`='Has servido con honor. Haré que toda la Horda se entere de tu victoria.' WHERE `ID`=31958;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어이쿠, 칠흑의 기사단께서 날 잡으러 드디어 왕림하셨구만. 이거 무서워서 어쩌나.', `MaleText_loc4`='哎呀，黑锋骑士团派人来杀我了。我害怕得发抖啊。', `MaleText_loc5`='噢，黯刃之手終於找上我。我怕得發抖了。', `MaleText_loc7`='Ah, la mano de la Espada de Ébano al fin ha venido a por mí. Tiemblo de miedo.' WHERE `ID`=31959;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드를 위해... 모든 걸 바쳤소...', `MaleText_loc4`='我为部落……奉献了一切……', `MaleText_loc5`='我將我的一切...都獻給了部落...', `MaleText_loc7`='Lo he dado todo... por la Horda...', `FemaleText_loc1`='호드를 위해... 모든 걸 바쳤어요...', `FemaleText_loc4`='我为部落……奉献了一切……', `FemaleText_loc5`='我將我的一切...都獻給了部落...', `FemaleText_loc7`='Lo he dado todo... por la Horda...' WHERE `ID`=31960;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 그 정도밖에 안 되나? 그따위 힘으로 도대체 어떻게 성채까지 들어왔느냐?', `MaleText_loc4`='哈！你们就这点本事啊？就凭这点实力，你们也敢闯进城堡啊。', `MaleText_loc5`='哈!你就只有這點本事?我真驚訝你居然到得了城塞。', `MaleText_loc7`='¡Ja! ¿Es eso todo lo que saben hacer? Me sorprende que hayan llegado hasta la ciudadela.' WHERE `ID`=31961;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕께서는 너희는 감히 상상도 못할 힘을 내게 주셨다. 보아라!', `MaleText_loc4`='巫妖王赐予我的力量远远超过了你们的想象。看招！', `MaleText_loc5`='巫妖王賜予我的力量，就算在你最狂野的惡夢中也無法想像。看著吧!', `MaleText_loc7`='El Rey Exánime me ha otorgado poder más allá de tus peores pesadillas. ¡Mira!' WHERE `ID`=31962;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기가 네놈들 무덤이다.', `MaleText_loc4`='该结束了。', `MaleText_loc5`='在此全部結束。', `MaleText_loc7`='Todo acaba aquí.' WHERE `ID`=31963;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어이, 이거 다리온 아니신가! 언제쯤 기어나오려나 궁금하던 참이었다.', `MaleText_loc4`='你总算来了，达里安！我正在猜想你什么时候会露面呢。', `MaleText_loc5`='你在這兒，達瑞安!我還在想你龜縮到哪去了。', `MaleText_loc7`='¡Ahí estás Darion! Me preguntaba cuándo te arrastrarías hacia delante.' WHERE `ID`=31964;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성스러운 땅에서 티리온의 허풍에 속아 뒤도 안 보고 투항하던 꼴이란. 그가 승리할 줄 알았나 보지? 다리온, 네놈은 언제나 겁쟁이였어. 네 아비처럼 말이야.', `MaleText_loc4`='泰里恩随口吹嘘了几句，你竟然就被蛊惑了，以为他会赢得最终的胜利。达里安，你终究是个胆小鬼啊。就跟你的父亲一样。', `MaleText_loc5`='你這麼容易就被提里奧在聖地的吹噓所騙，你魯莽地投靠他，以為他會獲勝。你一直都是個懦夫，達瑞安。就跟你父親一樣。', `MaleText_loc7`='Engañado por las fanfarronerías que Tirion decía sobre suelo sagrado, fuiste corriendo junto a él pensando que saldría victorioso. Siempre fuiste un cobarde, Darion, igual que tu padre.' WHERE `ID`=31965;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 의미심장한 웃음을 짓습니다.', `MaleText_loc4`='%s狡黠地笑了笑。', `MaleText_loc5`='%s故意地竊笑。', `MaleText_loc7`='%s ríe con complicidad.' WHERE `ID`=31966;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕께서는 너희를 모조리... 다... 없애버리실... 것이다.', `MaleText_loc4`='巫妖王会将……你们……统统……干掉。', `MaleText_loc5`='巫妖王消滅...你們...每...一個...人。', `MaleText_loc7`='El Rey Exánime extinguirá... hasta... al último... de ustedes.' WHERE `ID`=31967;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='약해. 약해.', `MaleText_loc4`='脆弱的家伙。', `MaleText_loc5`='弱者。', `MaleText_loc7`='Debilucho.' WHERE `ID`=31968;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕의 노예가 하나 늘었군.', `MaleText_loc4`='巫妖王又多了一名仆从。', `MaleText_loc5`='又多了一個奴隸獻給巫妖王。', `MaleText_loc7`='Otro esclavo más para el Rey Exánime.' WHERE `ID`=31969;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그것도 도전이라고 한 거냐?', `MaleText_loc4`='这算什么挑战。', `MaleText_loc5`='一點挑戰性也沒有。', `MaleText_loc7`='Eso ni siquiera ha sido un reto.' WHERE `ID`=31970;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼씨구... 죽었네.', `MaleText_loc4`='哎呀……你这就死了啊。', `MaleText_loc5`='瞧一瞧...你已經死了。', `MaleText_loc7`='Anda mira eso... has fallecido.' WHERE `ID`=31971;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕의 이름을 더럽힌 대가다!', `MaleText_loc4`='藐视巫妖王的权威是要付出代价的！', `MaleText_loc5`='為你對巫妖王的放肆付出代價!', `MaleText_loc7`='¡POR TU INSOLENCIA HACIA EL REY EXÁNIME!' WHERE `ID`=31972;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 물러날 거라 감히 생각한 건가? 내 계획을 무너뜨렸다고?', `MaleText_loc4`='就凭你，也想反抗我的意志，破坏我的计划吗？', `MaleText_loc5`='你膽敢認為你能阻撓我的意志?以為你能破壞我的計畫?', `MaleText_loc7`='¿Te atreves a pensar que has frustrado mis ambiciones? ¿Que has estropeado mis planes?' WHERE `ID`=31973;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래 봐야 아무 소용없는 일이다!', `MaleText_loc4`='你将一事无成！', `MaleText_loc5`='你什麼也沒達成!', `MaleText_loc7`='¡No has conseguido nada!' WHERE `ID`=31974;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오르바즈 블러드베인, 자칭 리치 왕의 심복.', `MaleText_loc4`='奥尔巴兹·血毒，就凭你也敢自称是巫妖王的左膀右臂。', `MaleText_loc5`='歐貝茲·血禍，自稱為巫妖王的左右手。', `MaleText_loc7`='Orbaz Malasangre, autoproclamado mano del Rey Exánime.' WHERE `ID`=31975;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너의 부질없는 저항은 파멸을 앞당겼을 뿐이다.', `MaleText_loc4`='停止无力的抵抗吧，这仅仅能延缓你的毁灭罢了。', `MaleText_loc5`='你愚蠢虛弱的抵抗只會加快你們的滅亡。', `MaleText_loc7`='Tu débil resistencia solo ha acelerado tu perdición.' WHERE `ID`=31976;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 사라져서 대장 노릇 해 보니 그렇게 좋더냐?', `MaleText_loc4`='你迫不及待地想要除掉我，然后独揽大权是吗？', `MaleText_loc5`='等不及想做點不尋常的事情，好獲得控制權?', `MaleText_loc7`='¿No podías esperar a que me apartara para que pudieras recuperar el control?' WHERE `ID`=31977;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꼴 좋군.', `MaleText_loc4`='终于除掉了祸根。', `MaleText_loc5`='清理得好。', `MaleText_loc7`='Buen viaje.' WHERE `ID`=31978;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇게 아등바등 지칠 때까지 지껄여 봐라. 그래 봐야 넌 내 것이다. 모르비두스가 네 죽음의 전령이 될 것이다!', `MaleText_loc4`='趁你还活着，只管宣扬这些陈词滥调吧。你终究会落到我的手里，摩比乌斯将宣告你的死讯！', `MaleText_loc5`='你可以大放厥詞也可以盡情抵抗直到你死去。到最後，你終究是屬於我的，莫比達斯將會是帶給你死亡的信使!', `MaleText_loc7`='Farfulla tus perogrulladas y menéate sin sentido hasta que estés agotado. ¡Al final serás mío y Morbidus será el heraldo de tu muerte!' WHERE `ID`=31979;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='복수해주시오, $g 형제:자매;여...', `MaleText_loc4`='为我报仇，$g兄弟:姐妹;……', `MaleText_loc5`='替我報仇，$g兄弟:姊妹;...', `MaleText_loc7`='Véngame, $ghermano:hermana;...', `FemaleText_loc1`='복수를 부탁합니다, $g 형제:자매;여...', `FemaleText_loc4`='为我报仇，$g兄弟:姐妹;……', `FemaleText_loc5`='替我報仇，$g兄弟:姊妹;...', `FemaleText_loc7`='Véngame, $ghermano:hermana;...' WHERE `ID`=31980;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모르비두스, 왕의 말을 거역하는 자의 최후가 어떤 것인지 보여줘라.', `MaleText_loc4`='摩比乌斯，让他们知道，敢于违抗国王的旨意是什么下场！', `MaleText_loc5`='莫比達斯，讓他們瞧瞧違抗巫妖王意願的下場!', `MaleText_loc7`='¡Morbidus, enséñales que les pasa a los que desafían la voluntad de su rey!' WHERE `ID`=31981;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐, $c|1이여;여;...$b$b마지막... 부탁이 있소...', `MaleText_loc4`='等等，$c……$b$b我还有最后……一个请求……', `MaleText_loc5`='等等，$c...$b$b最後...一個...請求...', `MaleText_loc7`='Espera, $c...', `FemaleText_loc1`='잠시만요, $c|1이여;여;...$b$b마지막... 부탁이 있습니다...', `FemaleText_loc4`='等等，$c……$b$b我还有最后……一个请求……', `FemaleText_loc5`='等等，$c...$b$b最後...一個...請求', `FemaleText_loc7`='Espera, $c...' WHERE `ID`=31982;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너는 대장이 될 재목이 아니다, 오르바즈. 멍청한 해골 군단 하나 지휘하는 것도 네놈에겐 벅차다.', `MaleText_loc4`='奥尔巴兹，你根本就不具备领袖的天赋，你连一队没脑子的骷髅都指挥不了！', `MaleText_loc5`='你永遠也沒辦法指揮或控制什麼東西，歐貝茲，連一團沒大腦的骷髏也不行。', `MaleText_loc7`='Nunca tendrás lo que hace falta para dirigir nada, Orbaz, ni siquiera una legión de esqueletos descerebrados.' WHERE `ID`=31983;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나처럼 고귀한 몸이... 어떻게... 이렇게...', `MaleText_loc4`='我们……是无比强大的龙族！怎……怎么会这样……？', `MaleText_loc5`='我們...是強大無比的龍族!這怎麼...可能?', `MaleText_loc7`='Nosotros... ¡somos superiores! ¿Cómo es... posible?' WHERE `ID`=31984;
