UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보잘것없는 저항이로군...', `MaleText_loc4`='真是微弱的抵抗……', `MaleText_loc5`='這種二流的抵抗。', `MaleText_loc7`='Qué resistencia tan mediocre...' WHERE `ID`=31987;
