UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불쌍히 여겨주마, 살타리온. 이번 한 번만이다.', `MaleText_loc4`='我真是同情你，萨塔里奥，仅此一次。', `MaleText_loc5`='我真是同情你，撒爾薩里安，就這麼一次。', `MaleText_loc7`='Te tendré piedad, Saltharion, sólo por esta vez.' WHERE `ID`=31991;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으으윽... 난 이미 늦었소.$b$b난... 끝났소이다...', `MaleText_loc4`='啊……太晚了，$g兄弟:姐妹;。$b$b我……快死了……', `MaleText_loc5`='喔...太遲了，$g兄弟:姊妹;。$b$b我...要死了...', `MaleText_loc7`='Aarrgh... Es demasiado tarde para mí, $ghermano:hermana;.$B$BEstoy... acabado...', `FemaleText_loc1`='으으윽... 난 이미 늦었소.$b$b난... 끝났소이다...', `FemaleText_loc4`='啊……太晚了，$g兄弟:姐妹;。$b$b我……快死了……', `FemaleText_loc5`='喔...太遲了，$g兄弟:姊妹;。$b$b我...要死了...', `FemaleText_loc7`='Aarrgh... Es demasiado tarde para mí, $ghermano:hermana;.$B$BEstoy... acabada...' WHERE `ID`=31992;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기에 너희 자리는 없다! 네놈들이 가야 할 곳은... 바로 저승이다!', `FemaleText_loc4`='你们没资格来这里！你们的归宿……在死者的国度！', `FemaleText_loc5`='你們沒資格來這裡!你們的歸宿...在死者的國度!', `FemaleText_loc7`='¡No tienes cabida aquí! ¡Sino entre... los difuntos!' WHERE `ID`=31993;
