UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='시시하군. 어린애 장난 같아...', `FemaleText_loc4`='轻松。就像我平常的娱乐一样……', `FemaleText_loc5`='真輕鬆。感覺好像我在玩耍一樣...', `FemaleText_loc7`='Era de esperar. Justo cuando me estaba divirtiendo…' WHERE `ID`=31995;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='암흑 속으로 보내주마.', `FemaleText_loc4`='我要将你们投入黑暗中。', `FemaleText_loc5`='我將對你處以黑暗之刑。', `FemaleText_loc7`='A la oscuridad te condeno.' WHERE `ID`=31996;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='조막만 한 것들이 오만하구나... 감히 넘보지도 못할 힘에 도전해?', `FemaleText_loc4`='一群自大的低等生物。来挑战一下你们永远也无法理解的强大力量吧。', `FemaleText_loc5`='傲慢的小東西，竟挑戰你所不了解的力量。', `FemaleText_loc7`='Criaturitas arrogantes, desafiar poderes que aún no comprenden.' WHERE `ID`=31997;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나는 단순한 용이 아니다. 훨씬 더 위대한 존재다!', `FemaleText_loc4`='我不仅仅是一条龙。你们还可以在我身上发现更多的秘密。', `FemaleText_loc5`='我不僅僅是一條龍。你們還可以在我身上發現更多的秘密。', `FemaleText_loc7`='No soy un simple dragón. Descubrirás que soy muchísimo más.' WHERE `ID`=31998;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='노는 꼴을 보고 있자니 우습군... 좋았어. 어떻게 하는 건지 잘 봐라!', `FemaleText_loc4`='欣赏你的挣扎真是令人愉悦。好吧，现在让你见识见识该怎么了结这一切！', `FemaleText_loc5`='看你們掙扎真的很有趣。好吧，你就見識見識該怎麼終結這一切!', `FemaleText_loc7`='Qué divertido es mirarte luchar. Muy bien, ¡mira cómo se hace!' WHERE `ID`=31999;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='방심하지 말았어야 했어...', `FemaleText_loc4`='我不该……犹……犹豫的……', `FemaleText_loc5`='我不應該...留手...', `FemaleText_loc7`='No debería haber... vacilado…' WHERE `ID`=32000;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='', `MaleText_loc4`='', `MaleText_loc5`='', `MaleText_loc7`='' WHERE `ID`=32001;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈들 따위 겁낼 줄 아느냐... 비천한 것들! 어디 한번 덤벼봐라!', `MaleText_loc4`='你们这些下等生物根本无法对我构成任何威胁！使出全力战斗吧！', `MaleText_loc5`='你們這些下等生物根本無法對我構成任何威脅!使出全力戰鬥吧!', `MaleText_loc7`='¡No representan ninguna amenaza, seres inferiores! ¡Demuestren su poderío!' WHERE `ID`=32002;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싸움을 걸 줄만 알고 싸울 줄은 모르는군!', `MaleText_loc4`='你唯一可以做到的事情，就是体面地战死！', `MaleText_loc5`='你唯一可以做到的事情就是體面的戰死!', `MaleText_loc7`='¡Enfrentarme en combate es lo menos que podrías hacer!' WHERE `ID`=32003;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하... 그 정도밖에 못 하겠나?', `MaleText_loc4`='这就是你的全部实力了吗？', `MaleText_loc5`='這就是你的全部實力了嗎?', `MaleText_loc7`='¿Eso fue lo máximo que puedes hacer?' WHERE `ID`=32004;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈들 무기로 이빨이나 쑤셔야겠다.', `MaleText_loc4`='我要用你们的骨头来剔牙！', `MaleText_loc5`='我要用你們的骨頭來剔牙!', `MaleText_loc7`='¡Recogeré tus huesos con los dientes!' WHERE `ID`=32005;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='교활한 녀석들 같으니! 나라고 계략이 없는 줄 아느냐...', `MaleText_loc4`='你们好像有两下子啊，那么就让你们看看我的招数吧……', `MaleText_loc5`='你們好像有兩下子，那麼就讓你們看看我的招數吧!', `MaleText_loc7`='Con que tienes truquillos. Yo también tengo los míos…' WHERE `ID`=32006;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희와 달리 나는 다재다능하다!', `MaleText_loc4`='与你们不同的是，我有无数的绝技！', `MaleText_loc5`='與你們不同的是，我有無數的絕技!', `MaleText_loc7`='¡A diferencia de ti, tengo muchas habilidades!' WHERE `ID`=32007;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아버지 말씀 틀린 게 하나도 없어, 살타리온. 넌 약해빠졌어!', `MaleText_loc4`='父亲大人对你的评价一点都没错，萨塔里奥。你就是个废物。', `MaleText_loc5`='父親大人對你的評價一點都沒錯，撒爾薩里安。你就是個廢物。', `MaleText_loc7`='Padre tenía razón en cuanto a ti, Saltharion. Sí, eres un alfeñique.' WHERE `ID`=32008;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난... 더 싸울 수... 있는데...', `MaleText_loc4`='我还能……继续……战……', `MaleText_loc5`='我還能...繼續...戰...', `MaleText_loc7`='Aún... puedo... luchar…' WHERE `ID`=32009;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와줘서 고맙다. 난 은빛십자군 선봉기지에 있을 테니 필요한 게 있으면 그쪽으로 와라.', `MaleText_loc4`='谢谢你。如果你还有其他需要，可以到银色前线基地来找我。', `MaleText_loc5`='感謝你的協助。如果你之後需要什麼東西，可以在銀白先鋒駐地找到我。', `MaleText_loc7`='Gracias por tu ayuda. Puedes encontrarme en La Vanguardia Argenta si necesitas algo más.' WHERE `ID`=32010;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='산도발 공작을 물리쳐야 한다. 그를 쓰러뜨리지 않으면 네가 죽는다, $c|1이여;여;.', `FemaleText_loc4`='你必须打败萨杜瓦尔王子。这是你活下来的唯一希望，$c。', `FemaleText_loc5`='你一定要擊敗薩杜瓦爾親王。這是你存活的唯一希望，$c。', `FemaleText_loc7`='Debes derrotar al príncipe Sandoval. Es tu única espranza de sobrevivir, $c.' WHERE `ID`=32011;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정신 차리세요. 이곳에서 무슨 일이 일어났는지 알아야 합니다.', `MaleText_loc4`='朋友，坚持住。告诉我究竟出了什么事。', `MaleText_loc5`='留在我身邊，朋友。我一定要知道這裡發生什麼事。', `MaleText_loc7`='Quédate conmigo, colega. Tengo que saber qué ha pasado aquí.', `FemaleText_loc1`='정신 차리세요. 이곳에서 무슨 일이 일어났는지 알아야 합니다.', `FemaleText_loc4`='朋友，坚持住。告诉我究竟出了什么事。', `FemaleText_loc5`='留在我身邊，朋友。我一定要知道這裡發生什麼事。', `FemaleText_loc7`='Quédate conmigo, colega. Tengo que saber qué ha pasado aquí.' WHERE `ID`=32012;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='용사 $n, 이렇게 다시 만나서 반갑다.$B$B발할라스에는 무슨 일인가? 전우의 도전을 돕기 위함인가?', `FemaleText_loc4`='$n，瓦哈拉斯的勇士，很高兴再次见到你。$B$B你是回来帮助朋友作战的吗？', `FemaleText_loc5`='勇士$n，很高興再次見到你。$B$B你回到英靈殿來協助你的朋友接受挑戰嗎?', `FemaleText_loc7`='$gCampeón:Campeona; $n, me alegro de volver a verte,$B$B¿Has regresado a Valhalas para ayudar a algún amigo en sus desafíos?' WHERE `ID`=32013;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 눈보라에 몸을 숨기고 공격을 개시했소...$b$b스컬지 녀석들은 무방비 상태였소... 승리가 바로 눈앞이었는데...$B$B그런데... 갑자기 우리 뒤에서... 호드 놈들이 튀어나왔소.$b$b녀석들은... 모든 것을 앗아갔소...', `MaleText_loc4`='我们在暴风雪的掩护下发动了进攻……$b$b天灾军团被打了个措手不及……眼看就要取得胜利……$b$b突然……我们遭遇了……部落大军的偷袭。$b$b他们毁了……一切……', `MaleText_loc5`='我們在暴風雪的掩護下展開攻擊...$b$b天譴軍毫無防備...我們勝券在握...$b$b然後...就從我們的後方...部落突然出現。$b$b他們害死我們...所有人...', `MaleText_loc7`='Atacamos cubiertos por una ventisca...$B$BLa Plaga no estaba en estado de alerta... nuestra victoria estaba asegurada...$B$BEntonces... por detrás... la Horda salió de la nada.$B$BNos costaron... todo...', `FemaleText_loc1`='우린 눈보라에 몸을 숨기고 공격을 개시했어요...$b$b스컬지 녀석들은 무방비 상태였죠... 승리가 바로 눈앞이었는데...$B$B그런데... 갑자기 우리 뒤에서... 호드 놈들이 튀어나왔어요.$b$b녀석들은... 모든 것을 앗아갔어요...', `FemaleText_loc4`='我们在暴风雪的掩护下发动了进攻……$b$b天灾军团被打了个措手不及……眼看就要取得胜利……$b$b突然……我们遭遇了……部落大军的偷袭。$b$b他们毁了……一切……', `FemaleText_loc5`='我們在暴風雪的掩護下展開攻擊...$b$b天譴軍毫無防備...我們勝券在握...$b$b然後...就從我們的後方...部落突然出現。$b$b他們害死我們...所有人...', `FemaleText_loc7`='Atacamos cubiertos por una ventisca...$B$BLa Plaga no estaba en estado de alerta... nuestra victoria estaba asegurada...$B$BEntonces... por detrás... la Horda salió de la nada.$B$BNos costaron... todo...' WHERE `ID`=32014;
