UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안토니다스 기념지는 달라란 북쪽에 있습니다.', `MaleText_loc4`='安东尼达斯的纪念碑位于达拉然北部。', `MaleText_loc5`='安東尼達斯的紀念公園就在達拉然北區。', `MaleText_loc7`='El parquet conmemorativo a Antonidas se encuentra en la zona norte de Dalaran.', `FemaleText_loc1`='안토니다스 기념지는 달라란 북쪽에 있습니다.', `FemaleText_loc4`='安东尼达斯的纪念碑位于达拉然北部。', `FemaleText_loc5`='安東尼達斯的紀念公園就在達拉然北區。', `FemaleText_loc7`='El parquet conmemorativo a Antonidas se encuentra en la zona norte de Dalaran.' WHERE `ID`=32088;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달라란 북쪽에 이 도시에 약간의... 모험을 더해주는 우물이 있답니다. 달라란을 방문하는 분들이 이 우물을 통해 하수도로 가신답니다.', `MaleText_loc4`='在达拉然城北有一口井，某些……富有冒险精神的游客能通过那口井进入下水道。', `MaleText_loc5`='達拉然北邊有一座井，城市裡一些更...喜好冒險...的訪客會用它來進入下水道。', `MaleText_loc7`='Hay un pozo en la zona norte de Dalaran que algunos de los más... intrépidos... visitantes usan para adentrarse en las cloacas.', `FemaleText_loc1`='달라란 북쪽에 이 도시에 약간의... 모험을 더해주는 우물이 있답니다. 달라란을 방문하는 분들이 이 우물을 통해 하수도로 가신답니다.', `FemaleText_loc4`='在达拉然城北有一口井，某些……富有冒险精神的游客能通过那口井进入下水道。', `FemaleText_loc5`='達拉然北邊有一座井，城市裡一些更...喜好冒險...的訪客會用它來進入下水道。', `FemaleText_loc7`='Hay un pozo en la zona norte de Dalaran que algunos de los más... intrépidos... visitantes usan para adentrarse en las cloacas.' WHERE `ID`=32089;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 빨리 못 해, 이 멍청한 것들아. 리치 왕께서는 너희들 늑장 받아줄 여유가 없으시다!', `MaleText_loc4`='动作快点，蠢货！巫妖王可没有耐心来容忍你们这些懒骨头！', `MaleText_loc5`='工作努力點，蠢貨，巫妖王可沒空容忍你們的懶惰!', `MaleText_loc7`='Trabajen más duro, insensatos. El Rey Exánime no tiene tiempo para su holgazanería.' WHERE `ID`=32090;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='작업반장들, 맡은 일 똑바로 못 하나? 생산량을 늘리란 말이야!', `MaleText_loc4`='瓦格里工头，给我盯紧点。我们必须提高产量！', `MaleText_loc5`='女監工，做好你們的工作。生產必須要增加!', `MaleText_loc7`='¡Opresoras, hagan su trabajo! ¡La producción ha de aumentar!' WHERE `ID`=32091;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='작업반장들, 내가 직접 나서서 너희 일이나 대신 해줘야겠나?', `MaleText_loc4`='难道一定要我亲自监督吗，啊？！', `MaleText_loc5`='難道非得要我親自出面，你們才能替女監工完成工作?!', `MaleText_loc7`='¿Es que tengo que salir a hacer su trabajo, opresoras?' WHERE `ID`=32092;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='키린 토의 적들을 가둔 감옥인 보랏빛 요새는 달라란의 남동쪽에 있습니다.', `MaleText_loc4`='紫罗兰监狱位于达拉然东南部，用于关押肯瑞托法师议会的敌人。', `MaleText_loc5`='紫羅蘭堡，囚禁著祈倫托之敵的監獄，就在達拉然東南邊。', `MaleText_loc7`='La Ciudadela Violeta, la prisión para los enemigos del Kirin Tor, está en la zona sudeste de Dalaran.', `FemaleText_loc1`='키린 토의 적들을 가둔 감옥인 보랏빛 요새는 달라란의 남동쪽에 있습니다.', `FemaleText_loc4`='紫罗兰监狱位于达拉然东南部，用于关押肯瑞托法师议会的敌人。', `FemaleText_loc5`='紫羅蘭堡，囚禁著祈倫托之敵的監獄，就在達拉然東南邊。', `FemaleText_loc7`='La Ciudadela Violeta, la prisión para los enemigos del Kirin Tor, está en la zona sudeste de Dalaran.' WHERE `ID`=32093;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 새 노예들이 도착했군. 작업반장들은 이 녀석들 옷 입혀서 탄광으로 보내!', `MaleText_loc4`='啊，新的奴隶来啦。瓦格里工头们，给他们分配工作，让他们马上开工！', `MaleText_loc5`='喔，新的奴隸到了。女監工，確認他們的裝備，讓他們分配下去工作!', `MaleText_loc7`='Ah, han llegado nuevos esclavos. ¡Opresoras, aseguraos de que estén bien equipados y ponedlos a trabajar!' WHERE `ID`=32094;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달라란의 서쪽에 있는 거대한 첨탑을 보셨나요? 그 탑이 바로 웅장한 보랏빛 성채랍니다.', `MaleText_loc4`='看见达拉然东部的巨塔了吗？那就是宏伟的紫罗兰城堡。', `MaleText_loc5`='你看到達拉然東邊的眾多尖塔嗎?那就是雄偉的紫羅蘭城塞。', `MaleText_loc7`='¿Ves la enorme torre con capiteles en la zona este de Dalaran? Es la majestuosa Ciudadela Violeta.', `FemaleText_loc1`='달라란의 서쪽에 있는 거대한 첨탑을 보셨나요? 그 탑이 바로 웅장한 보랏빛 성채랍니다.', `FemaleText_loc4`='看见达拉然东部的巨塔了吗？那就是宏伟的紫罗兰城堡。', `FemaleText_loc5`='你看到達拉然東邊的眾多尖塔嗎?那就是雄偉的紫羅蘭城塞。', `FemaleText_loc7`='¿Ves la enorme torre con capiteles en la zona este de Dalaran? Es la majestuosa Ciudadela Violeta.' WHERE `ID`=32095;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달라란을 방문한 호드들은 달라란의 북동쪽에 있는 선리버 성소에서 주로 지내고 있습니다.$B$B성소에는 여관도 있고 오그리마와 여러 전장으로 갈 수 있는 차원문이 있답니다.', `MaleText_loc4`='部落旅客主要集中在达拉然东北部的夺日者圣殿。$B$B那里设有旅店，还有通往各大战场和奥格瑞玛的传送门。', `MaleText_loc5`='來訪的部落主要都待在達拉然東北的奪日者聖堂。$B$B那裡有一間旅店，還有傳送門可以通往奧格瑪與各個戰場。', `MaleText_loc7`='Los miembros de la Horda que nos visitan suelen quedarse en el Santuario Atracasol, en la zona noreste de Dalaran.$B$BAllí hay una posada, además de portales a los diversos campos de batalla y a Orgrimmar.', `FemaleText_loc1`='달라란을 방문한 호드들은 달라란의 북동쪽에 있는 선리버 성소에서 주로 지내고 있습니다.$B$B성소에는 여관도 있고 오그리마와 여러 전장으로 갈 수 있는 차원문이 있답니다.', `FemaleText_loc4`='部落旅客主要集中在达拉然东北部的夺日者圣殿。$B$B那里设有旅店，还有通往各大战场和奥格瑞玛的传送门。', `FemaleText_loc5`='來訪的部落主要都待在達拉然東北的奪日者聖堂。$B$B那裡有一間旅店，還有傳送門可以通往奧格瑪與各個戰場。', `FemaleText_loc7`='Los miembros de la Horda que nos visitan suelen quedarse en el Santuario Atracasol, en la zona noreste de Dalaran.$B$BAllí hay una posada, además de portales a los diversos campos de batalla y a Orgrimmar.' WHERE `ID`=32096;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달라란을 방문한 얼라이언스들은 달라란의 남동쪽에 있는 은빛 자치구에서 주로 지내고 있습니다.$B$B자치구에는 여관도 있고 스톰윈드와 여러 전장으로 갈 수 있는 차원문이 있답니다.', `MaleText_loc4`='联盟旅客主要集中在达拉然西南部的银色领地。$B$B那里设有旅店，还有通往各大战场和暴风城的传送门。', `MaleText_loc5`='來訪的聯盟主要都待在達拉然西南的白銀領區。$B$B那裡有一間旅店，還有傳送門可以通往暴風城與各個戰場。', `MaleText_loc7`='Los miembros de la Alianza que nos visitan suelen quedarse en El Enclave de Plata, en la zona sudoeste de Dalaran.$B$BAllí hay una posada, además de portales a los diversos campos de batalla y a Ventormenta.', `FemaleText_loc1`='달라란을 방문한 얼라이언스들은 달라란의 남동쪽에 있는 은빛 자치구에서 주로 지내고 있습니다.$B$B자치구에는 여관도 있고 스톰윈드와 여러 전장으로 갈 수 있는 차원문이 있답니다.', `FemaleText_loc4`='联盟旅客主要集中在达拉然西南部的银色领地。$B$B那里设有旅店，还有通往各大战场和暴风城的传送门。', `FemaleText_loc5`='來訪的聯盟主要都待在達拉然西南的白銀領區。$B$B那裡有一間旅店，還有傳送門可以通往暴風城與各個戰場。', `FemaleText_loc7`='Los miembros de la Alianza que nos visitan suelen quedarse en El Enclave de Plata, en la zona sudoeste de Dalaran.$B$BAllí hay una posada, además de portales a los diversos campos de batalla y a Ventormenta.' WHERE `ID`=32097;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달라란 하수도 아래로 가는 방법엔 최소 3가지가 있답니다. 바로 동쪽, 서쪽, 북쪽에 있는 우물을 통해 하수도로 가는 방법이랍니다.', `MaleText_loc4`='达拉然至少有三条地下通道：东部和西部各有一个下水道入口，北部还有一口井。', `MaleText_loc5`='至少有三條路可以通往達拉然的底層。在東邊和西邊的下水道入口，和北邊的一口井。', `MaleText_loc7`='Hay al menos tres maneras de llegar bajo Dalaran: las entradas a las cloacas al este y al oeste, y un pozo en el norte.', `FemaleText_loc1`='달라란 하수도 아래로 가는 방법엔 최소 3가지가 있답니다. 바로 동쪽, 서쪽, 북쪽에 있는 우물을 통해 하수도로 가는 방법이랍니다.', `FemaleText_loc4`='达拉然至少有三条地下通道：东部和西部各有一个下水道入口，北部还有一口井。', `FemaleText_loc5`='至少有三條路可以通往達拉然的底層。在東邊和西邊的下水道入口，和北邊的一口井。', `FemaleText_loc7`='Hay al menos tres maneras de llegar bajo Dalaran: las entradas a las cloacas al este y al oeste, y un pozo en el norte.' WHERE `ID`=32098;
