UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달라란의 투기장과 투기장 관련 인물들은 달라란의 아래쪽 하수도에서 찾을 수 있습니다.$B$B투기장으로 가는 길은 적어도 3가지가 있답니다. 바로 동쪽, 서쪽 입구와 북쪽에 있는 우물입니다.', `MaleText_loc4`='达拉然的竞技场和管理员都在这座城市的下水道里。$B$B至少有三条地下通道可以抵达那里：东部和西部下水道的入口，还有北部的水井。', `MaleText_loc5`='你可以在城市之下找到達拉然的競技場與相關的服務人員，就在下水道中。$B$B至少有三條路可以通往達拉然的底層。在東邊和西邊的下水道入口，和北邊的一口井。', `MaleText_loc7`='La arena de Dalaran y quienes se encargan de ella se encuentran bajo la ciudad, en las cloacas.$B$BHay al menos tres formas de entrar: cloacas en el este y el oeste, y un pozo al norte.', `FemaleText_loc1`='달라란의 투기장과 투기장 관련 인물들은 달라란의 아래쪽 하수도에서 찾을 수 있습니다.$B$B투기장으로 가는 길은 적어도 3가지가 있답니다. 바로 동쪽, 서쪽 입구와 북쪽에 있는 우물입니다.', `FemaleText_loc4`='达拉然的竞技场和管理员都在这座城市的下水道里。$B$B至少有三条地下通道可以抵达那里：东部和西部下水道的入口，还有北部的水井。', `FemaleText_loc5`='你可以在城市之下找到達拉然的競技場與相關的服務人員，就在下水道中。$B$B至少有三條路可以通往達拉然的底層。在東邊和西邊的下水道入口，和北邊的一口井。', `FemaleText_loc7`='La arena de Dalaran y quienes se encargan de ella se encuentran bajo la ciudad, en las cloacas.$B$BHay al menos tres formas de entrar: cloacas en el este y el oeste, y un pozo al norte.' WHERE `ID`=32112;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달라란의 얼라이언스와 호드 지구인 은빛 자치구와 선리버 성소에서 스톰윈드와 오그리마, 그리고 여러 전장으로 갈 수 있는 차원문을 찾을 수 있답니다.', `MaleText_loc4`='在达拉然的联盟区银色领地和部落区夺日者圣殿都设有通往暴风城、奥格瑞玛和各大战场的传送门。', `MaleText_loc5`='通往暴風城、奧格瑪與各地戰場的傳送門就位在達拉然的聯盟區與部落區:白銀領區與奪日者聖堂。', `MaleText_loc7`='Puedes encontrar portales a Ventormenta y Orgrimmar y a los diversos campos de batalla en los cuarteles de la Alianza y la Horda de Dalaran: El Enclave de Plata y el Santuario Atracasol.', `FemaleText_loc1`='달라란의 얼라이언스와 호드 지구인 은빛 자치구와 선리버 성소에서 스톰윈드와 오그리마, 그리고 여러 전장으로 갈 수 있는 차원문을 찾을 수 있답니다.', `FemaleText_loc4`='在达拉然的联盟区银色领地和部落区夺日者圣殿都设有通往暴风城、奥格瑞玛和各大战场的传送门。', `FemaleText_loc5`='通往暴風城、奧格瑪與各地戰場的傳送門就位在達拉然的聯盟區與部落區:白銀領區與奪日者聖堂。', `FemaleText_loc7`='Puedes encontrar portales a Ventormenta y Orgrimmar y a los diversos campos de batalla en los cuarteles de la Alianza y la Horda de Dalaran: El Enclave de Plata y el Santuario Atracasol.' WHERE `ID`=32113;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='더 열심히 일하지 못해! 꾸물대면 목을 비틀어버릴 테다.', `FemaleText_loc4`='快点干活，别找麻烦！', `FemaleText_loc5`='努力工作，奴隸!否則我就把你頭給扭下來!', `FemaleText_loc7`='¡Trabaja más duro, esclavo, o te arrancaré la cabeza!' WHERE `ID`=32115;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 예... 예, 작업반장님. 뭐든 분부만 내리십시오.', `MaleText_loc4`='遵……遵命……一定遵照您的吩咐。', `MaleText_loc5`='是是是，女士，全都聽您的，女士。', `MaleText_loc7`='Ss..s..ssí, Señora. Lo que digas, señora.' WHERE `ID`=32116;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 다시는 살덩이작업장에서 리치 왕의 병력이 생산되지 않을 것이오.', `MaleText_loc4`='缝合场再也不能为巫妖王制造血肉大军了。', `MaleText_loc5`='血肉作坊再也不會替巫妖王的大軍製造士兵了。', `MaleText_loc7`='La Factoría de Carne no volverá a producir soldados para los ejércitos del Rey Exánime.' WHERE `ID`=32117;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빨리 이... 이 괴물 녀석을 처치하고 끝냅시다.', `MaleText_loc4`='让我们杀了这个……东西……了结这里的麻烦。', `MaleText_loc5`='讓我們宰了這個...東西...，克服這個難關。', `MaleText_loc7`='Matemos a esta... cosa... y acabemos con esto.', `FemaleText_loc1`='빨리 이... 이 괴물 녀석을 처치하고 끝냅시다.', `FemaleText_loc4`='让我们杀了这个……东西……了结这里的麻烦。', `FemaleText_loc5`='讓我們宰了這個...東西...，克服這個難關。', `FemaleText_loc7`='Matemos a esta... cosa... y acabemos con esto.' WHERE `ID`=32118;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='키린 토에서 마법 정치에 대한 전략적 관심을 주의 깊게 살피는 것이 제 임무입니다.$B$B이번 주엔 할 일이 아직 많이 남아 있군요. 제 일을 좀 도와주시겠습니까, $n 님?', `MaleText_loc4`='在肯瑞托议会中，我的职责是保障法师议会的战略利益。$B$B本周要做的事情还有很多，$n。你愿意帮忙吗？', `MaleText_loc5`='我在祈倫托中負責關於魔法社會的戰略事務。$B$B這個禮拜還有很多事情等著完成呢。$n，你願意協助我嗎?', `MaleText_loc7`='Dentro del Kirin Tor, es mi labor asegurar los intereses estratégicos de la magocracia.$B$BAún queda mucho por hacer esta semana, $n. ¿Quieres ayudarme?' WHERE `ID`=32119;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법사 교역소는 달라란 북서쪽에 있습니다. 달라란의 기술 전문가들 대부분이 그곳에 있답니다.', `MaleText_loc4`='魔法商业区位于达拉然西北部，那里汇集了大部分专业技能训练师。', `MaleText_loc5`='魔導師貿易區在達拉然的西北邊，城中大多數的專業訓練師都在那邊。', `MaleText_loc7`='El Mercado de Magos está en la zona noroeste de Dalaran y cobija a la mayoría de los instructores de profesión de la ciudad.', `FemaleText_loc1`='마법사 교역소는 달라란 북서쪽에 있습니다. 달라란의 기술 전문가들 대부분이 그곳에 있답니다.', `FemaleText_loc4`='魔法商业区位于达拉然西北部，那里汇集了大部分专业技能训练师。', `FemaleText_loc5`='魔導師貿易區在達拉然的西北邊，城中大多數的專業訓練師都在那邊。', `FemaleText_loc7`='El Mercado de Magos está en la zona noroeste de Dalaran y cobija a la mayoría de los instructores de profesión de la ciudad.' WHERE `ID`=32120;
