UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달라란 북서쪽, 마법사 교역소에서 농업공학 연금술점 부속 온실이 있습니다. 그곳에서 달라란 최고의 약초채집사들을 만나실 수 있습니다.', `MaleText_loc4`='在达拉然西北部的魔法商业区，农艺炼金房的旁边坐落着一间温室。你可以在那里找到全城最好的草药师。', `MaleText_loc5`='西北邊魔導師貿易區的農藝藥材行還有一間溫室。你可以在那邊找到全城最好的草藥師。', `MaleText_loc7`='Hay un invernadero junto a La Botica Agronómica en el Mercado de Magos, en la zona noroeste de Dalaran. Allí encontrarás a los mejores herboristas de la ciudad.', `FemaleText_loc1`='달라란 북서쪽, 마법사 교역소에서 농업공학 연금술점 부속 온실이 있습니다. 그곳에서 달라란 최고의 약초채집사들을 만나실 수 있습니다.', `FemaleText_loc4`='在达拉然西北部的魔法商业区，农艺炼金房的旁边坐落着一间温室。你可以在那里找到全城最好的草药师。', `FemaleText_loc5`='西北邊魔導師貿易區的農藝藥材行還有一間溫室。你可以在那邊找到全城最好的草藥師。', `FemaleText_loc7`='Hay un invernadero junto a La Botica Agronómica en el Mercado de Magos, en la zona noroeste de Dalaran. Allí encontrarás a los mejores herboristas de la ciudad.' WHERE `ID`=32127;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달라란 남쪽에 있는 광장인 어스름 거리의 마법의 샘 낚시터에서 낚시를 배울 수 있습니다.', `MaleText_loc4`='在达拉然南部的日暮广场内有一座魔法喷泉，你可以在那附近找到钓鱼训练师。', `MaleText_loc5`='一般人可以在達拉然南邊日暮區的魔法噴泉釣魚。', `MaleText_loc7`='Se puede aprender a pescar cerca de la fuente encantada en El Manto de la Noche, una plaza en la zona sur de Dalaran.', `FemaleText_loc1`='달라란 남쪽에 있는 광장인 어스름 거리의 마법의 샘 낚시터에서 낚시를 배울 수 있습니다.', `FemaleText_loc4`='在达拉然南部的日暮广场内有一座魔法喷泉，你可以在那附近找到钓鱼训练师。', `FemaleText_loc5`='一般人可以在達拉然南邊日暮區的魔法噴泉釣魚。', `FemaleText_loc7`='Se puede aprender a pescar cerca de la fuente encantada en El Manto de la Noche, una plaza en la zona sur de Dalaran.' WHERE `ID`=32128;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달라란 북서쪽, 마법사 교역소에 달라란 최고의 긴급 치료 중심지인 응급치료의 모든 것이 있습니다.', `MaleText_loc4`='在达拉然西北部的魔法商业区设有全城最高级的急救中心——急你所急。', `MaleText_loc5`='城市的急救中心，急救你優先，就在西北邊的魔導師貿易區。', `MaleText_loc7`='El centro de atención urgente de la ciudad, Te Auxiliamos los Primeros, se encuentra en el Mercado de Magos, en la zona noroeste de Dalaran.', `FemaleText_loc1`='달라란 북서쪽, 마법사 교역소에 달라란 최고의 긴급 치료 중심지인 응급치료의 모든 것이 있습니다.', `FemaleText_loc4`='在达拉然西北部的魔法商业区设有全城最高级的急救中心——急你所急。', `FemaleText_loc5`='城市的急救中心，急救你優先，就在西北邊的魔導師貿易區。', `FemaleText_loc7`='El centro de atención urgente de la ciudad, Te Auxiliamos los Primeros, se encuentra en el Mercado de Magos, en la zona noroeste de Dalaran.' WHERE `ID`=32129;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달라란 북서쪽, 마법사 교역소에 있는 나사 풀린 태엽에서 기계공학 전문가들을 만나 기술을 배우실 수 있습니다.', `MaleText_loc4`='工程师可以前往达拉然西北部的魔法商业区，在精密仪器接受训练。', `MaleText_loc5`='工程師通常都會在西北邊魔導師貿易區的精準如錶發條舖，進行訓練。', `MaleText_loc7`='Los ingenieros suelen ofrecer instrucción en Como un reloj, en el Mercado de Magos, en la zona noroeste de Dalaran.', `FemaleText_loc1`='달라란 북서쪽, 마법사 교역소에 있는 나사 풀린 태엽에서 기계공학 전문가들을 만나 기술을 배우실 수 있습니다.', `FemaleText_loc4`='工程师可以前往达拉然西北部的魔法商业区，在精密仪器接受训练。', `FemaleText_loc5`='工程師通常都會在西北邊魔導師貿易區的精準如錶發條舖，進行訓練。', `FemaleText_loc7`='Los ingenieros suelen ofrecer instrucción en Como un reloj, en Mercado de Magos, en la zona noroeste de Dalaran.' WHERE `ID`=32130;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법부여라면 달라란 북서쪽, 마법사 교역소의 바로 외곽에 있는 마법부여 전문점에 가 보시기 바랍니다.', `MaleText_loc4`='你可以去简单附魔瞧一瞧，就在达拉然西北部的魔法商业区外面。', `MaleText_loc5`='你一定會想去瞧瞧完全附魔商店，就在西北邊的魔導師貿易區。', `MaleText_loc7`='Te interesará visitar Simplemente encantador, justo a las afueras del Mercado de Magos, en la zona noroeste de Dalaran.', `FemaleText_loc1`='마법부여라면 달라란 북서쪽, 마법사 교역소의 바로 외곽에 있는 마법부여 전문점에 가 보시기 바랍니다.', `FemaleText_loc4`='你可以去简单附魔瞧一瞧，就在达拉然西北部的魔法商业区外面。', `FemaleText_loc5`='你一定會想去瞧瞧完全附魔商店，就在西北邊的魔導師貿易區。', `FemaleText_loc7`='Te interesará visitar Simplemente encantador, justo a las afueras del Mercado de Magos, en la zona noroeste de Dalaran.' WHERE `ID`=32131;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전문 요리사는 얼라이언스와 호드 지구에 있는 여관 부엌에서 만나실 수 있습니다.', `MaleText_loc4`='你可以在联盟区和部落区旅店的厨房里找到烹饪训练师。', `MaleText_loc5`='烹飪訓練師位在聯盟與部落兩區的旅店廚房。', `MaleText_loc7`='Los instructores de cocina se encuentran en las cocinas de la Alianza y la Horda en sus barrios respectivos.', `FemaleText_loc1`='전문 요리사는 얼라이언스와 호드 지구에 있는 여관 부엌에서 만나실 수 있습니다.', `FemaleText_loc4`='你可以在联盟区和部落区旅店的厨房里找到烹饪训练师。', `FemaleText_loc5`='烹飪訓練師位在聯盟與部落兩區的旅店廚房。', `FemaleText_loc7`='Los instructores de cocina se encuentran en las cocinas de la Alianza y la Horda en sus barrios respectivos.' WHERE `ID`=32132;
