UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하이 엘프인 히라 스노우돈이 극지 비행 기술을 가르쳐 줄 겁니다.$B$B달라란 동쪽에 있는 크라서스 착륙장에서 용매를 탄 그녀를 만날 수 있을 겁니다.', `MaleText_loc4`='高等精灵希拉·雪晨能教你学会寒冷天气飞行。$B$B她骑着龙鹰，就在达拉然东部的克拉苏斯平台上。', `MaleText_loc5`='高等精靈席拉·雪曦可以教導你寒冷氣候飛行。$B$B你可以在達拉然東邊的卡薩斯平臺找到她，就騎在她的龍鷹上。', `MaleText_loc7`='La elfa noble Hira Albanieve enseña vuelo en clima frío.$B$BPuedes encontrarla a lomos de su dracohalcón en el Alto de Krasus, en la zona este de Dalaran.', `FemaleText_loc1`='하이 엘프인 히라 스노우돈이 극지 비행 기술을 가르쳐 줄 겁니다.$B$B달라란 동쪽에 있는 크라서스 착륙장에서 용매를 탄 그녀를 만날 수 있을 겁니다.', `FemaleText_loc4`='高等精灵希拉·雪晨能教你学会寒冷天气飞行。$B$B她骑着龙鹰，就在达拉然东部的克拉苏斯平台上。', `FemaleText_loc5`='高等精靈席拉·雪曦可以教導你寒冷氣候飛行。$B$B你可以在達拉然東邊的卡薩斯平臺找到她，就騎在她的龍鷹上。', `FemaleText_loc7`='La elfa noble Hira Albanieve enseña vuelo en clima frío.$B$BPuedes encontrarla a lomos de su dracohalcón en el Alto de Krasus, en la zona este de Dalaran.' WHERE `ID`=32149;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달라란 동쪽에 있는 큰 건물에서 달라란의 마법사들과 순간이동 전문가들을 만날 수 있습니다. 바로 크라서스 착륙장과 달라란의 심장부에 있는 룬위버 광장 사이랍니다.', `MaleText_loc4`='达拉然的法师训练师和传送门训练师聚集在东部的一幢大型建筑物内，就在城市中心的鲁因广场和克拉苏斯平台之间。', `MaleText_loc5`='本城的法師與傳送門訓練師就在達拉然東邊的大建築物中，在織符者廣場和卡薩斯平臺之間。', `MaleText_loc7`='Los instructores de magos y de portal se encuentran en un gran edificio en la zona este de Dalaran, entre la Plaza Tejerruna en el centro de la ciudad y el Alto de Krasus.', `FemaleText_loc1`='달라란 동쪽에 있는 큰 건물에서 달라란의 마법사들과 순간이동 전문가들을 만날 수 있습니다. 바로 크라서스 착륙장과 달라란의 심장부에 있는 룬위버 광장 사이랍니다.', `FemaleText_loc4`='达拉然的法师训练师和传送门训练师聚集在东部的一幢大型建筑物内，就在城市中心的鲁因广场和克拉苏斯平台之间。', `FemaleText_loc5`='本城的法師與傳送門訓練師就在達拉然東邊的大建築物中，在織符者廣場和卡薩斯平臺之間。', `FemaleText_loc7`='Los instructores de magos y de portal se encuentran en un gran edificio en la zona este de Dalaran, entre la Plaza Tejerruna en el centro de la ciudad y el Alto de Krasus.' WHERE `ID`=32150;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 상급자나 전문가를 찾으셨나요?', `MaleText_loc4`='你要找哪一种训练师？', `MaleText_loc5`='你要找哪一個專業訓練師?', `MaleText_loc7`='¿Qué tipo de instructor estabas tratando de encontrar?', `FemaleText_loc1`='어떤 상급자나 전문가를 찾으셨나요?', `FemaleText_loc4`='你要找哪一种训练师？', `FemaleText_loc5`='你要找哪一個專業訓練師?', `FemaleText_loc7`='¿Qué tipo de instructor estabas tratando de encontrar?' WHERE `ID`=32151;
