UPDATE `locales_broadcast_text` SET `MaleText_loc1`='극지 비행 교관', `MaleText_loc4`='寒冷天气飞行训练师', `MaleText_loc5`='寒冷氣候飛行訓練師', `MaleText_loc7`='Instructor de vuelo en clima frío', `FemaleText_loc1`='극지 비행 교관', `FemaleText_loc4`='寒冷天气飞行训练师', `FemaleText_loc5`='寒冷氣候飛行訓練師', `FemaleText_loc7`='Instructora de vuelo en clima frío' WHERE `ID`=32154;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달라란의 야수 관리인은 달라란 북동쪽에 있는 마법 동물원 내에 있습니다.', `MaleText_loc4`='你可以在达拉然东北部的魔法动物店找到兽栏管理员。', `MaleText_loc5`='達拉然的獸欄管理員就在達拉然東北的魔法動物園中。', `MaleText_loc7`='El maestro de establos de Dalaran se encuentra dentro del Arca Mágica en el noreste de Dalaran.', `FemaleText_loc1`='달라란의 야수 관리인은 달라란 북동쪽에 있는 마법 동물원 내에 있습니다.', `FemaleText_loc4`='你可以在达拉然东北部的魔法动物店找到兽栏管理员。', `FemaleText_loc5`='達拉然的獸欄管理員就在達拉然東北的魔法動物園中。', `FemaleText_loc7`='El maestro de establos de Dalaran se encuentra dentro del Arca Mágica en el noreste de Dalaran.' WHERE `ID`=32155;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달라란 중앙의 북쪽, 요술쟁이 휴게실이라는 달라란에서 가장 유명한 여관이 있습니다.$B$B얼라이언스와 호드 지구에도 여행자들이 이용할 수 있는 여관이 있지요. 또한 달라란 아래 하수도에 다른 여관이 있다고 들었습니다.', `MaleText_loc4`='魔术旅馆是达拉然最受欢迎的旅店，就在市中心以北。$B$B联盟区和部落区均设有旅店。听说达拉然下水道里也有一家旅店。', `MaleText_loc5`='達拉然最受歡迎的旅舍就是戲法旅舍，就在城市中央偏北的地方。$B$B聯盟與部落區都有各自的旅舍，我聽說還城市底下的下水道裡還有一間。', `MaleText_loc7`='La posada más conocida de Dalaran es el Salón Juego de Manos, justo al norte del centro de la ciudad.$B$BLos cuarteles de la Alianza y la Horda tienen sus propias posadas también y me han dicho que hay otra más bajo la ciudad en las cloacas.', `FemaleText_loc1`='달라란 중앙의 북쪽, 요술쟁이 휴게실이라는 달라란에서 가장 유명한 여관이 있습니다.$B$B얼라이언스와 호드 지구에도 여행자들이 이용할 수 있는 여관이 있지요. 또한 달라란 아래 하수도에 다른 여관이 있다고 들었습니다.', `FemaleText_loc4`='魔术旅馆是达拉然最受欢迎的旅店，就在市中心以北。$B$B联盟区和部落区均设有旅店。听说达拉然下水道里也有一家旅店。', `FemaleText_loc5`='達拉然最受歡迎的旅舍就是戲法旅舍，就在城市中央偏北的地方。$B$B聯盟與部落區都有各自的旅舍，我聽說還城市底下的下水道裡還有一間。', `FemaleText_loc7`='La posada más conocida de Dalaran es el Salón Juego de Manos, justo al norte del centro de la ciudad.$B$BLos cuarteles de la Alianza y la Horda tienen sus propias posadas también y me han dicho que hay otra más bajo la ciudad en las cloacas.' WHERE `ID`=32156;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달라란에서 제일 유명한 미용실은 달라란 북쪽에 있습니다.', `MaleText_loc4`='达拉然著名的理发店就坐落在城市北部。', `MaleText_loc5`='本地最有名的美容沙龍位在達拉然的東北邊。', `MaleText_loc7`='La peluquería más conocida de la ciudad se encuentra en la zona norte de Dalaran.', `FemaleText_loc1`='달라란에서 제일 유명한 미용실은 달라란 북쪽에 있습니다.', `FemaleText_loc4`='达拉然著名的理发店就坐落在城市北部。', `FemaleText_loc5`='本地最有名的美容沙龍位在達拉然的東北邊。', `FemaleText_loc7`='La peluquería más conocida de la ciudad se encuentra en la zona norte de Dalaran.' WHERE `ID`=32157;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달라란 동쪽에 있는 크라서스 착륙장에서 비행 조련사를 만날 수 있을 겁니다.', `MaleText_loc4`='你可以在达拉然东部的克拉苏斯平台找到飞行管理员。', `MaleText_loc5`='你可以在達拉然東邊的卡薩斯平臺找到本城的飛行管理員。', `MaleText_loc7`='Encontrarás al maestro de vuelo de la ciudad en el Alto de Krasus, en la zona este de Dalaran.', `FemaleText_loc1`='달라란 동쪽에 있는 크라서스 착륙장에서 비행 조련사를 만날 수 있을 겁니다.', `FemaleText_loc4`='你可以在达拉然东部的克拉苏斯平台找到飞行管理员。', `FemaleText_loc5`='你可以在達拉然東邊的卡薩斯平臺找到本城的飛行管理員。', `FemaleText_loc7`='Encontrarás al maestro de vuelo de la ciudad en el Alto de Krasus, en la zona este de Dalaran.' WHERE `ID`=32158;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달라란 은행은 달라란의 북쪽 지역에 있습니다.', `MaleText_loc4`='达拉然银行位于城市北部。', `MaleText_loc5`='達拉然銀行就在城市的北邊。', `MaleText_loc7`='El Banco de Dalaran está en la parte norte de la ciudad.', `FemaleText_loc1`='달라란 은행은 달라란의 북쪽 지역에 있습니다.', `FemaleText_loc4`='达拉然银行位于城市北部。', `FemaleText_loc5`='達拉然銀行就在城市的北邊。', `FemaleText_loc7`='El Banco de Dalaran está en la parte norte de la ciudad.' WHERE `ID`=32159;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어스름 거리 외곽, 달라란 남쪽에 달라란 상업 은행이 있습니다.', `MaleText_loc4`='达拉然商业银行位于城市南部，毗邻日暮广场。', `MaleText_loc5`='達拉然商業銀行就在城市南邊，日暮區附近。', `MaleText_loc7`='El Banco de mercaderes de Dalaran está en la parte sur de la ciudad, a la salida de El Manto de la Noche.', `FemaleText_loc1`='어스름 거리 외곽, 달라란 남쪽에 달라란 상업 은행이 있습니다.', `FemaleText_loc4`='达拉然商业银行位于城市南部，毗邻日暮广场。', `FemaleText_loc5`='達拉然商業銀行就在城市南邊，日暮區附近。', `FemaleText_loc7`='El Banco de mercaderes de Dalaran está en la parte sur de la ciudad, a la salida de El Manto de la Noche.' WHERE `ID`=32160;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 작업장이 폭발하려고 합니다, 어서!', `MaleText_loc4`='糟糕！车间要爆炸啦！快离开这里，快！', `MaleText_loc5`='不!工坊快要爆炸了!撤離，快!', `MaleText_loc7`='¡No! ¡El taller va a explotar! ¡Evacuadlo, deprisa!', `FemaleText_loc1`='안 돼! 작업장이 폭발하려고 해요, 어서!', `FemaleText_loc4`='糟糕！车间要爆炸啦！快离开这里，快！', `FemaleText_loc5`='不!工坊快要爆炸了!撤離，快!', `FemaleText_loc7`='¡No! ¡El taller va a explotar! ¡Evacuadlo, deprisa!' WHERE `ID`=32161;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달라란에는 3개의 은행이 있습니다. 달라란 북쪽에 있는 달라란 은행, 남쪽에 있는 달라란 상업 은행, 달라란 지하 하수도에도 있습니다.', `MaleText_loc4`='达拉然内设有三座银行：北部的达拉然银行，南部的达拉然商业银行以及位于下水道的银行。', `MaleText_loc5`='城中一共有三間銀行:北邊的達拉然銀行，南邊的達拉然商業銀行，城市底下還有一間，在下水道裡。', `MaleText_loc7`='Hay tres bancos en la ciudad: el Banco de Dalaran al norte, el Banco de mercaderes de Dalaran al sur y otro más bajo la ciudad, en las cloacas.', `FemaleText_loc1`='달라란에는 3개의 은행이 있습니다. 달라란 북쪽에 있는 달라란 은행, 남쪽에 있는 달라란 상업 은행, 달라란 지하 하수도에도 있습니다.', `FemaleText_loc4`='达拉然内设有三座银行：北部的达拉然银行，南部的达拉然商业银行以及位于下水道的银行。', `FemaleText_loc5`='城中一共有三間銀行:北邊的達拉然銀行，南邊的達拉然商業銀行，城市底下還有一間，在下水道裡。', `FemaleText_loc7`='Hay tres bancos en la ciudad: el Banco de Dalaran al norte, el Banco de mercaderes de Dalaran al sur y otro más bajo la ciudad, en las cloacas.' WHERE `ID`=32162;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='북쪽 은행', `MaleText_loc4`='北部银行', `MaleText_loc5`='北區銀行', `MaleText_loc7`='Banco del norte', `FemaleText_loc1`='북쪽 은행', `FemaleText_loc4`='北部银行', `FemaleText_loc5`='北區銀行', `FemaleText_loc7`='Banco del norte' WHERE `ID`=32163;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='남쪽 은행', `MaleText_loc4`='南部银行', `MaleText_loc5`='南區銀行', `MaleText_loc7`='Banco del sur', `FemaleText_loc1`='남쪽 은행', `FemaleText_loc4`='南部银行', `FemaleText_loc5`='南區銀行', `FemaleText_loc7`='Banco del sur' WHERE `ID`=32164;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달라란에는 여러 개의 우체통이 있습니다. 여관과 은행 근처 외곽과 여러 구석진 곳, 심지어는 크라서스 착륙장에도 우체통이 있답니다.', `MaleText_loc4`='达拉然设有许多信箱：你可以在各个街道转角，旅店和银行外以及克拉苏斯平台找到它们。', `MaleText_loc5`='達拉然中有許多郵箱:各個街角、旅店與銀行外頭，甚至在卡薩斯平臺也有。', `MaleText_loc7`='Hay muchos buzones en Dalaran: en muchas esquinas, fuera de cada posada y banco, incluso en el Alto de Krasus.', `FemaleText_loc1`='달라란에는 여러 개의 우체통이 있습니다. 여관과 은행 근처 외곽과 여러 구석진 곳, 심지어는 크라서스 착륙장에도 우체통이 있답니다.', `FemaleText_loc4`='达拉然设有许多信箱：你可以在各个街道转角，旅店和银行外以及克拉苏斯平台找到它们。', `FemaleText_loc5`='達拉然中有許多郵箱:各個街角、旅店與銀行外頭，甚至在卡薩斯平臺也有。', `FemaleText_loc7`='Hay muchos buzones en Dalaran: en muchas esquinas, fuera de cada posada y banco, incluso en el Alto de Krasus.' WHERE `ID`=32165;
