UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크라서스 착륙장은 달라란의 가장 동쪽에 있습니다.$B$B달라란 비행 조련사와 극지 비행 교관도 착륙장에서 만날 수 있답니다.', `MaleText_loc4`='克拉苏斯平台位于达拉然的最东端。$B$B本城的飞行管理员和寒冷天气飞行训练师都在那里。', `MaleText_loc5`='卡薩斯平臺就在達拉然的最東邊。$B$B本城的飛行管理員就在此，還有寒冷氣候飛行訓練師。', `MaleText_loc7`='El Alto de Krasus se encuentra en la parte más al este de Dalaran.$B$BEl maestro de vuelo de la ciudad se encuentra allí, al igual que la instructora de vuelo en clima frío.', `FemaleText_loc1`='크라서스 착륙장은 달라란의 가장 동쪽에 있습니다.$B$B달라란 비행 조련사와 극지 비행 교관도 착륙장에서 만날 수 있답니다.', `FemaleText_loc4`='克拉苏斯平台位于达拉然的最东端。$B$B本城的飞行管理员和寒冷天气飞行训练师都在那里。', `FemaleText_loc5`='卡薩斯平臺就在達拉然的最東邊。$B$B本城的飛行管理員就在此，還有寒冷氣候飛行訓練師。', `FemaleText_loc7`='El Alto de Krasus se encuentra en la parte más al este de Dalaran.$B$BEl maestro de vuelo de la ciudad se encuentra allí, al igual que la instructora de vuelo en clima frío.' WHERE `ID`=32169;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달라란에는 경매장이 없답니다. 그러니 다른 대도시로 가는 차원문을 타셔야 한답니다.$B$B달라란에 있는 얼라이언스와 호드 지구인 은빛 자치구와 선리버 성소에서 차원문을 찾을 수 있을 겁니다.', `MaleText_loc4`='达拉然没有拍卖行。你必须通过传送门返回各大主城才能使用拍卖行。$B$B传送门位于达拉然的联盟和部落区：银色领地和夺日者圣殿。', `MaleText_loc5`='達拉然並沒有拍賣場。你必須經由傳送門回到你的主城。$B$B傳送門就在達拉然的聯盟區與部落區:白銀領區和奪日者聖堂。', `MaleText_loc7`='Dalaran no posee su propia casa de subastas. Tienes que atravesar un portal que te lleve a una de tus capitales.$B$BPuedes encontrarlos en los cuarteles de la Alianza y de la Horda: El Enclave de Plata y el Santuario de los Atracasol.', `FemaleText_loc1`='달라란에는 경매장이 없답니다. 그러니 다른 대도시로 가는 차원문을 타셔야 한답니다.$B$B달라란에 있는 얼라이언스와 호드 지구인 은빛 자치구와 선리버 성소에서 차원문을 찾을 수 있을 겁니다.', `FemaleText_loc4`='达拉然没有拍卖行。你必须通过传送门返回各大主城才能使用拍卖行。$B$B传送门位于达拉然的联盟和部落区：银色领地和夺日者圣殿。', `FemaleText_loc5`='達拉然並沒有拍賣場。你必須經由傳送門回到你的主城。$B$B傳送門就在達拉然的聯盟區與部落區:白銀領區和奪日者聖堂。', `FemaleText_loc7`='Dalaran no posee su propia casa de subastas. Tienes que atravesar un portal que te lleve a una de tus capitales.$B$BPuedes encontrarlos en los barrios de la Alianza y de la Horda: El Enclave de Plata y el Santuario Atracasol.' WHERE `ID`=32170;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 원료를 파괴해주겠는가? 주인님께서는 너를 위해 특별한 계획을 준비하고 계시다...', `MaleText_loc4`='你想销毁我们的原料是吧？呃，主人已经想到了一项特殊的计划……', `MaleText_loc5`='你毀掉了我們的稀有原料嗎?嗯，主人對你另有計畫...', `MaleText_loc7`='Así que vas a destruir nuestra materia prima, ¿no? Bueno, el maestro tiene un plan especial para ti en mente...' WHERE `ID`=32171;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 시설을 찾고 계신가요?', `MaleText_loc4`='你需要什么服务？', `MaleText_loc5`='你在尋找哪一種服務?', `MaleText_loc7`='¿Qué servicio estás buscando?', `FemaleText_loc1`='어떤 시설을 찾고 계신가요?', `FemaleText_loc4`='你需要什么服务？', `FemaleText_loc5`='你在尋找哪一種服務?', `FemaleText_loc7`='¿Qué servicio estás buscando?' WHERE `ID`=32172;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저길 보십시오! 서리고룡이 여기서 대체 뭐 하고 있는 걸까요? 우리 쪽으로 곧장 다가옵니다.', `MaleText_loc4`='瞧！冰霜巨龙！它冲我们来了！', `MaleText_loc5`='快看!那裡為什麼會有一隻冰霜巨龍?它正朝我們過來。', `MaleText_loc7`='¡Mira! ¿Qué hace una vermis de escarcha aquí? Viene directa a por nosotros.' WHERE `ID`=32173;
