UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달라란을 방문한 얼라이언스들은 달라란의 남동쪽에 있는 은빛 자치구에서 주로 지내고 있습니다.$B$B자치구에는 여관도 있고 여러 얼라이언스 주요 도시와 전장으로 갈 수 있는 차원문이 있답니다.', `MaleText_loc4`='联盟旅客主要集中在达拉然西南部的银色领地。$B$B那里设有旅店，还有通往各大联盟主城和战场的传送门。', `MaleText_loc5`='聯盟的訪客主要都在西南邊的白銀領區。$B$B那邊有一間旅店還有通往聯盟各大主城與戰場的傳送門。', `MaleText_loc7`='Los miembros de la Alianza que nos visitan suelen quedarse en El Enclave de Plata, en la zona sudoeste de Dalaran.$B$BAllí hay una posada, además de portales a las diversas ciudades de la Alianza y a los campos de batalla.', `FemaleText_loc1`='달라란을 방문한 얼라이언스들은 달라란의 남동쪽에 있는 은빛 자치구에서 주로 지내고 있습니다.$B$B자치구에는 여관도 있고 여러 얼라이언스 주요 도시와 전장으로 갈 수 있는 차원문이 있답니다.', `FemaleText_loc4`='联盟旅客主要集中在达拉然西南部的银色领地。$B$B那里设有旅店，还有通往各大联盟主城和战场的传送门。', `FemaleText_loc5`='聯盟的訪客主要都在西南邊的白銀領區。$B$B那邊有一間旅店還有通往聯盟各大主城與戰場的傳送門。', `FemaleText_loc7`='Los miembros de la Alianza que nos visitan suelen quedarse en El Enclave de Plata, en la zona sudoeste de Dalaran.$B$BAllí hay una posada, además de portales a las diversas ciudades de la Alianza y a los campos de batalla.' WHERE `ID`=32181;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여행자 분, 달라란에 오신 걸 환영합니다.$B$B제가 도와드릴 일이 있을까요?', `MaleText_loc4`='欢迎来到达拉然，旅行者。$B$B我能帮你什么忙吗？', `MaleText_loc5`='歡迎來到達拉然，旅人。$B$B你想要找什麼地方呢?', `MaleText_loc7`='$gBievenido:Bienvenida; a Dalaran, $gviajero:viajera;.$B$B¿Puedo ayudarte a encontrar algo?', `FemaleText_loc1`='여행자 분, 달라란에 오신 걸 환영합니다.$B$B제가 도와드릴 일이 있을까요?', `FemaleText_loc4`='欢迎来到达拉然，旅行者。$B$B我能帮你什么忙吗？', `FemaleText_loc5`='歡迎來到達拉然，旅人。$B$B你想要找什麼地方呢?', `FemaleText_loc7`='$gBievenido:Bienvenida; a Dalaran, $gviajero:viajera;.$B$B¿Puedo ayudarte a encontrar algo?' WHERE `ID`=32183;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이방인이여, 달라란에서는 달라란의 법을 존중해 주시기 바랍니다.$B$B길을 잃으셨나요? 제가 도와드릴 일이 있을까요?', `MaleText_loc4`='陌生人，在达拉然逗留期间，请您遵守此地的法律。$B$B您迷路吗？我能帮上什么忙吗？', `MaleText_loc5`='請尊重達拉然的律法，陌生人。$B$B你迷路了?你想要找什麼地方呢?', `MaleText_loc7`='Por favor, respeta las leyes de Dalaran mientras estés aquí, $gforastero:forastera;.$B$B¿Te has perdido? ¿Puedo ayudarte a encontrar algo?', `FemaleText_loc1`='이방인이여, 달라란에서는 달라란의 법을 존중해 주시기 바랍니다.$B$B길을 잃으셨나요? 제가 도와드릴 일이 있을까요?', `FemaleText_loc4`='陌生人，在达拉然逗留期间，请您遵守此地的法律。$B$B您迷路吗？我能帮上什么忙吗？', `FemaleText_loc5`='請尊重達拉然的律法，陌生人。$B$B你迷路了?你想要找什麼地方呢?', `FemaleText_loc7`='Por favor, respeta las leyes de Dalaran mientras estés aquí, $gforastero:forastera;.$B$B¿Te has perdido? ¿Puedo ayudarte a encontrar algo?' WHERE `ID`=32184;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공격대 인스턴스가 초기화되기 직전입니다. 잠시 후에 해당 인스턴스로부터 귀환 지역으로 강제 이동됩니다.', `MaleText_loc4`='副本即将重置。你即将被移出副本。', `MaleText_loc5`='副本即將重置。你稍後將被強制移出副本。', `MaleText_loc7`='Esta estancia está a punto de reiniciarse. En breve se te sacará de la estancia.', `FemaleText_loc1`='공격대 인스턴스가 초기화되기 직전입니다. 잠시 후에 해당 인스턴스로부터 귀환 지역으로 강제 이동됩니다.', `FemaleText_loc4`='副本即将重置。你即将被移出副本。', `FemaleText_loc5`='副本即將重置。你稍後將被強制移出副本。', `FemaleText_loc7`='Esta estancia está a punto de reiniciarse. En breve se te sacará de la estancia.' WHERE `ID`=32185;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달라란의 길드 사무관은 달라란 중심의 남쪽에 있는 관광 안내소에서 만날 수 있습니다.', `MaleText_loc4`='达拉然的公会注册员就在市中心以南的旅客中心。', `MaleText_loc5`='你能在達拉然的旅客中心找到公會註冊員，就在城市中心偏南。', `MaleText_loc7`='Encontrarás al maestro de hermandad de Dalaran en el centro de visitantes, al sur del centro de la ciudad.', `FemaleText_loc1`='달라란의 길드 사무관은 달라란 중심의 남쪽에 있는 관광 안내소에서 만날 수 있습니다.', `FemaleText_loc4`='达拉然的公会注册员就在市中心以南的旅客中心。', `FemaleText_loc5`='你能在達拉然的旅客中心找到公會註冊員，就在城市中心偏南。', `FemaleText_loc7`='Encontrarás al maestro de hermandad de Dalaran en el centro de visitantes, al sur del centro de la ciudad.' WHERE `ID`=32186;
