UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언젠가 네 행동을 후회할 날이 올 것이다! 은빛십자군을 위하여!', `MaleText_loc4`='你会为自己的行径付出代价的！为银色北伐军而战！', `MaleText_loc5`='你要為你所做的一切付出代價!為了銀白十字軍!', `MaleText_loc7`='¡Pagarás por lo que has hecho! ¡Por la Cruzada Argenta!' WHERE `ID`=32198;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하찮은 해골 놈이! 참는 데도 한계가 있다!', `MaleText_loc4`='骷髅废物。我的耐心已经到头了！', `MaleText_loc5`='弱小的骷髏。我的耐心用完了!', `MaleText_loc7`='Endeble esqueleto. ¡Mi paciencia se ha agotado!' WHERE `ID`=32199;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님, 당신이 대마법사 랜달록과 얘기하는 미래가 보입니다.', `MaleText_loc4`='$n，根据我的预见，你将同大法师兰达洛克谈话。', `MaleText_loc5`='余嘗洞見未來，$n，汝將造訪大法師朗達拉克。', `MaleText_loc7`='Preveo que hablarás con el archimago Lan''dalock, $n.' WHERE `ID`=32200;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달라란에 있는 직업 상급자는 마법사들 뿐입니다. 다른 직업 상급자를 찾으신다면 차원문을 통해서 대도시나 다른 곳으로 가야만 한답니다.$B$B차원문은 얼라이언스 지구의 은빛 자치구나 호드 지구인 선리버 성소에서 찾을 수 있습니다.', `MaleText_loc4`='达拉然只有法师训练师。如果你要找其他职业的训练师，就必须通过传送门返回各大主城。$B$B$B$B传送门位于达拉然的联盟和部落区：银色领地和夺日者圣殿。', `MaleText_loc5`='達拉然唯一的職業訓練師就是法師。你得穿過傳送門回到你的主城才能找到其他訓練師。$B$B傳送門就在達拉然的聯盟區與部落區:白銀領區和奪日者聖堂。', `MaleText_loc7`='Los únicos instructores de clase de Dalaran son magos. Tienes que atravesar un portal que te lleve a una de tus capitales si buscas otro.$B$BLos puedes encontrar en los cuarteles de la Alianza y la Horda: El Enclave de Plata y el Santuario de los Atracasol.', `FemaleText_loc1`='달라란에 있는 직업 상급자는 마법사들 뿐입니다. 다른 직업 상급자를 찾으신다면 차원문을 통해서 대도시나 다른 곳으로 가야만 한답니다.$B$B차원문은 얼라이언스 지구의 은빛 자치구나 호드 지구인 선리버 성소에서 찾을 수 있습니다.', `FemaleText_loc4`='达拉然只有法师训练师。如果你要找其他职业的训练师，就必须通过传送门返回各大主城。$B$B$B$B传送门位于达拉然的联盟和部落区：银色领地和夺日者圣殿。', `FemaleText_loc5`='達拉然唯一的職業訓練師就是法師。你得穿過傳送門回到你的主城才能找到其他訓練師。$B$B傳送門就在達拉然的聯盟區與部落區:白銀領區和奪日者聖堂。', `FemaleText_loc7`='Los únicos entrenadores de clase de Dalaran son magos. Tienes que atravesar un portal que te lleve a una de tus capitales si buscas otro.$B$BLos puedes encontrar en los cuarteles de la Alianza y la Horda: El Enclave de Plata y el Santuario de los Atracasol.' WHERE `ID`=32201;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='직업 상급자', `MaleText_loc4`='职业训练师', `MaleText_loc5`='職業訓練師', `MaleText_loc7`='Instructor de clase', `FemaleText_loc1`='직업 상급자', `FemaleText_loc4`='职业训练师', `FemaleText_loc5`='職業訓練師', `FemaleText_loc7`='Instructor de clase' WHERE `ID`=32202;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하수도의 북동쪽 지역에 일종의 암시장이 있습니다.', `MaleText_loc4`='下水道的东北部有一个黑市。', `MaleText_loc5`='有一個黑市就在下水道東北的某處。', `MaleText_loc7`='En la parte noreste de las cloacas hay una especie de mercado negro.', `FemaleText_loc1`='하수도의 북동쪽 지역에 일종의 암시장이 있습니다.', `FemaleText_loc4`='下水道的东北部有一个黑市。', `FemaleText_loc5`='有一個黑市就在下水道東北的某處。', `FemaleText_loc7`='En la parte noreste de las cloacas hay una especie de mercado negro.' WHERE `ID`=32203;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='굴은 마법과 까마귀 선술집의 바로 북쪽, 하수도 서쪽에 있는 달라란의 아래쪽으로 이어집니다.$B$B약간의 모험을 더하는 방법으로는 날아서 달라란을 오가는 방법이 있지요.', `MaleText_loc4`='西部下水道设有通往城市底层的隧道，就在咒语和乌鸦旅店以北。$B$B有些喜欢冒险的旅客会从隧道进出达拉然。', `MaleText_loc5`='在西邊下水道有一條通道能通往城市的底部，就在咒語與烏鴉酒店的北邊。$B$B有些冒險者利用那邊出入達拉然。', `MaleText_loc7`='Un túnel sale de la parte de abajo de la ciudad en las cloacas occidentales, justo al norte de la Taberna de los Cuervos.$B$BLos más aventureros lo usan para entrar y salir volando de Dalaran.', `FemaleText_loc1`='굴은 마법과 까마귀 선술집의 바로 북쪽, 하수도 서쪽에 있는 달라란의 아래쪽으로 이어집니다.$B$B약간의 모험을 더하는 방법으로는 날아서 달라란을 오가는 방법이 있지요.', `FemaleText_loc4`='西部下水道设有通往城市底层的隧道，就在咒语和乌鸦旅店以北。$B$B有些喜欢冒险的旅客会从隧道进出达拉然。', `FemaleText_loc5`='在西邊下水道有一條通道能通往城市的底部，就在咒語與烏鴉酒店的北邊。$B$B有些冒險者利用那邊出入達拉然。', `FemaleText_loc7`='Un túnel sale de la parte de abajo de la ciudad en las cloacas occidentales, justo al norte de la Taberna de los Cuervos.$B$BLos más aventureros lo usan para entrar y salir volando de Dalaran.' WHERE `ID`=32204;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서쪽 하수도에서 마법과 까마귀 선술집을 찾아보시기 바랍니다.', `MaleText_loc4`='你要找的是咒语和乌鸦旅店吧，就在西部下水道。', `MaleText_loc5`='你可以在下水道西邊找到咒語與烏鴉酒店。', `MaleText_loc7`='Buscas la Taberna de los Cuervos, en las cloacas occidentales.', `FemaleText_loc1`='서쪽 하수도에서 마법과 까마귀 선술집을 찾아보시기 바랍니다.', `FemaleText_loc4`='你要找的是咒语和乌鸦旅店吧，就在西部下水道。', `FemaleText_loc5`='你可以在下水道西邊找到咒語與烏鴉酒店。', `FemaleText_loc7`='Buscas la Taberna de los Cuervos, en las cloacas occidentales.' WHERE `ID`=32205;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서쪽 하수도에 있는 마법과 까마귀 선술집 바로 북쪽으로 아래에는 고블린이 운영하는 은행이 있습니다.', `MaleText_loc4`='西部下水道有一座地精开设的银行，就在咒语和乌鸦旅店以北。', `MaleText_loc5`='那邊有一個哥布林經營的銀行，就在下水道西區，咒語與烏鴉酒店的北邊。', `MaleText_loc7`='Aquí abajo hay un banco dirigido por goblins, justo al norte de la Taberna de los Cuervos, en las cloacas occidentales.', `FemaleText_loc1`='서쪽 하수도에 있는 마법과 까마귀 선술집 바로 북쪽으로 아래에는 고블린이 운영하는 은행이 있습니다.', `FemaleText_loc4`='西部下水道有一座地精开设的银行，就在咒语和乌鸦旅店以北。', `FemaleText_loc5`='那邊有一個哥布林經營的銀行，就在下水道西區，咒語與烏鴉酒店的北邊。', `FemaleText_loc7`='Aquí abajo hay un banco dirigido por goblins, justo al norte de la Taberna de los Cuervos, en las cloacas occidentales.' WHERE `ID`=32206;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스팀휘들 무역회사는 달라란의 중앙 하수도에서 전 투기장 협회를 주관하고 있습니다.$B$B그곳에서 의지의 투기장이라는 결투장도 찾으실 수 있답니다.', `MaleText_loc4`='热砂港在达拉然的中心下水道里举办竞技场循环赛。$B$B你还可以参与意志竞技场的比赛。', `MaleText_loc5`='熱砂企業在達拉然下水道的中部舉行競技場巡迴。$B$B你還可以在意志之環找到決鬥場。', `MaleText_loc7`='El Cártel Bonvapor dirige todo un circuito de arenas en las cloacas centrales de Dalaran.$B$BAllí encontrarás anillos de duelos, también, en el Círculo de Voluntades.', `FemaleText_loc1`='스팀휘들 무역회사는 달라란의 중앙 하수도에서 전 투기장 협회를 주관하고 있습니다.$B$B그곳에서 의지의 투기장이라는 결투장도 찾으실 수 있답니다.', `FemaleText_loc4`='热砂港在达拉然的中心下水道里举办竞技场循环赛。$B$B你还可以参与意志竞技场的比赛。', `FemaleText_loc5`='熱砂企業在達拉然下水道的中部舉行競技場巡迴。$B$B你還可以在意志之環找到決鬥場。', `FemaleText_loc7`='El Cártel Bonvapor dirige todo un circuito de arenas en las cloacas centrales de Dalaran.$B$BAllí encontrarás anillos de duelos, también, en el Círculo de Voluntades.' WHERE `ID`=32207;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진입로는 하수도 동쪽에 있는 크라서스 착륙장 바로 외곽으로 이어집니다.', `MaleText_loc4`='东部下水道有一条直通克拉苏斯平台的斜道。', `MaleText_loc5`='下水道東邊有一個坡道通到卡薩斯平臺外。', `MaleText_loc7`='Una rampa lleva a las afueras del Alto de Krasus en las cloacas occidentales.', `FemaleText_loc1`='진입로는 하수도 동쪽에 있는 크라서스 착륙장 바로 외곽으로 이어집니다.', `FemaleText_loc4`='东部下水道有一条直通克拉苏斯平台的斜道。', `FemaleText_loc5`='下水道東邊有一個坡道通到卡薩斯平臺外。', `FemaleText_loc7`='Una rampa lleva a las afueras del Alto de Krasus en las cloacas occidentales.' WHERE `ID`=32208;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진입로는 하수도 서쪽에 있는 보랏빛 성채 근처로 이어집니다.', `MaleText_loc4`='西部下水道有一条通往紫罗兰城堡附近的斜道。', `MaleText_loc5`='下水道西邊有一個坡道通到紫羅蘭城塞附近。', `MaleText_loc7`='Una rampa lleva a las cercanías de La Ciudadela Violeta, en las cloacas occidentales.', `FemaleText_loc1`='진입로는 하수도 서쪽에 있는 보랏빛 성채 근처로 이어집니다.', `FemaleText_loc4`='西部下水道有一条通往紫罗兰城堡附近的斜道。', `FemaleText_loc5`='下水道西邊有一個坡道通到紫羅蘭城塞附近。', `FemaleText_loc7`='Una rampa lleva a las cercanías de La Ciudadela Violeta, en las cloacas occidentales.' WHERE `ID`=32209;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법의 뒤안길에서 나가는 방법은 세 가지가 있답니다. 동쪽과 서쪽 위로 이어지는 경사로로 올라가거나, 달라란의 아래쪽에서 벗어나는 굴로 가는 방법입니다.$B$B물론 굴로 가기 전에 날아가도 된답니다.', `MaleText_loc4`='达拉然下水道共有三条出路：通往东城和西城的斜道，以及通往达拉然底层的隧道。$B$B当然，你可以乘坐飞行坐骑穿越那条隧道。', `MaleText_loc5`='有三條路離開城底區:坡道可以往上通往西區或東區，通道可以往下跳出達拉然。$B$B不過，你最好要會飛才去使用那個通道。', `MaleText_loc7`='Hay tres maneras de salir de Los Bajos Fondos: rampas que suben hacia el este y el oeste y el túnel que sale desde la parte de debajo de Dalaran.$B$BAsegúrate de que sabes volar antes de meterte por el túnel.', `FemaleText_loc1`='마법의 뒤안길에서 나가는 방법은 세 가지가 있답니다. 동쪽과 서쪽 위로 이어지는 경사로로 올라가거나, 달라란의 아래쪽에서 벗어나는 굴로 가는 방법입니다.$B$B물론 굴로 가기 전에 날아가도 된답니다.', `FemaleText_loc4`='达拉然下水道共有三条出路：通往东城和西城的斜道，以及通往达拉然底层的隧道。$B$B当然，你可以乘坐飞行坐骑穿越那条隧道。', `FemaleText_loc5`='有三條路離開城底區:坡道可以往上通往西區或東區，通道可以往下跳出達拉然。$B$B不過，你最好要會飛才去使用那個通道。', `FemaleText_loc7`='Hay tres maneras de salir de Los Bajos Fondos: rampas que suben hacia el este y el oeste y el túnel que sale desde la parte de debajo de Dalaran.$B$BAsegúrate de que sabes volar antes de meterte por el túnel.' WHERE `ID`=32210;
