UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법의 뒤안길에 오신 걸 환영합니다. 뭔가 찾고 계신 것 같은데, 도와 드릴까요?', `MaleText_loc4`='欢迎来到达拉然下水道。我能帮你什么忙吗？', `MaleText_loc5`='歡迎來到城底區。你想要找什麼地方呢?', `MaleText_loc7`='Te doy la bienvenida a Los Bajos Fondos. ¿Hay algo que pueda ayudarte a encontrar?', `FemaleText_loc1`='마법의 뒤안길에 오신 걸 환영합니다. 뭔가 찾고 계신 것 같은데, 도와 드릴까요?', `FemaleText_loc4`='欢迎来到达拉然下水道。我能帮你什么忙吗？', `FemaleText_loc5`='歡迎來到城底區。你想要找什麼地方呢?', `FemaleText_loc7`='Te doy la bienvenida a Los Bajos Fondos. ¿Hay algo que pueda ayudarte a encontrar?' WHERE `ID`=32212;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 희생을 감수하더라도 스컬지를 막아야 합니다. 놈들이 이곳에서 조직 중인 군대가 공격하도록 놔두어서는 안 됩니다.', `MaleText_loc4`='必须不惜一切代价阻止天灾军团。绝不能让他们在这里组建的大军进入战场。', `MaleText_loc5`='不計一切代價都要阻止天譴軍。我們不能讓他們把在這裡製造的軍隊派上戰場。', `MaleText_loc7`='Hay que detener a la Plaga cueste lo que cueste. No podemos permitir que saquen al campo de batalla el ejército que están construyendo aquí.' WHERE `ID`=32213;
