UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언데드들이 수백 명을 죽였어요! 우린 간신히 목숨을 부지하고 살아나왔단 말입니다! 도와주세요!', `MaleText_loc4`='他们杀了好几百人！我们好不容易才捡回性命！帮帮我们！', `MaleText_loc5`='他們殺死了好幾百人!我們勉強才逃過一劫!幫幫我們!', `MaleText_loc7`='¡Mataron a cientos! ¡Apenas logramos escapar con vida! ¡Ayuda!', `FemaleText_loc1`='언데드들이 수백 명을 죽였어요! 우린 간신히 목숨을 부지하고 살아나왔단 말입니다! 도와주세요!', `FemaleText_loc4`='他们杀了好几百人！我们好不容易才捡回性命！帮帮我们！', `FemaleText_loc5`='他們殺死了好幾百人!我們勉強才逃過一劫!幫幫我們!', `FemaleText_loc7`='¡Mataron a cientos! ¡Apenas logramos escapar con vida! ¡Ayuda!' WHERE `ID`=32229;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠의 여왕께선 온 힘을 다하여 싸우셨습니다만... 결국엔... 여왕님께서 살아남으셨길 바랍니다. 제발 도와주세요!', `MaleText_loc4`='黑暗女王竭尽全力迎战，但最终……希望她能活下来。请你帮帮我们！', `MaleText_loc5`='黑暗女王奮力抵抗，但最後...我希望她逃出來了。拜託幫幫忙!', `MaleText_loc7`='La Dama Oscura luchó contra todos los que pudo, pero al final... Espero que haya sobrevivido. ¡Por favor, ayúdanos!', `FemaleText_loc1`='어둠의 여왕께선 온 힘을 다하여 싸우셨습니다만... 결국엔... 여왕님께서 살아남으셨길 바랍니다. 제발 도와주세요!', `FemaleText_loc4`='黑暗女王竭尽全力迎战，但最终……希望她能活下来。请你帮帮我们！', `FemaleText_loc5`='黑暗女王奮力抵抗，但最後...我希望她逃出來了。拜託幫幫忙!', `FemaleText_loc7`='La Dama Oscura luchó contra todos los que pudo, pero al final... Espero que haya sobrevivido. ¡Por favor, ayúdanos!' WHERE `ID`=32230;
