UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언제 우리 가게를 다시 열 수 있나요? 돈이 떨어지고 있단 말입니다!', `MaleText_loc4`='商店什么时候才能重新开业啊？我一直在亏损！', `MaleText_loc5`='我們什麼時候可以重新開張?我損失不少!', `MaleText_loc7`='¿Cuándo podremos volver a abrir nuestras tiendas? ¡Estoy perdiendo oro!', `FemaleText_loc1`='언제 우리 가게를 다시 열 수 있나요? 돈이 떨어지고 있단 말입니다!', `FemaleText_loc4`='商店什么时候才能重新开业啊？我一直在亏损！', `FemaleText_loc5`='我們什麼時候可以重新開張?我損失不少!', `FemaleText_loc7`='¿Cuándo podremos volver a abrir nuestras tiendas? ¡Estoy perdiendo oro!' WHERE `ID`=32237;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 불법이란 말입니다!', `MaleText_loc4`='这是暴政！', `MaleText_loc5`='這實在太過份了!', `MaleText_loc7`='¡Esto es una atrocidad!', `FemaleText_loc1`='이건 불법이란 말입니다!', `FemaleText_loc4`='这是暴政！', `FemaleText_loc5`='這實在太過份了!', `FemaleText_loc7`='¡Esto es una atrocidad!' WHERE `ID`=32238;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어째서 스랄 님께선 우리 도시에 이런 일이 일어나게 두신 거죠?', `MaleText_loc4`='萨尔怎么能听任我们的城市发生这种事？', `MaleText_loc5`='為什麼索爾會讓這種事情發生在我們的城市?', `MaleText_loc7`='¿Por qué está permitiendo Thrall que ocurra esto a nuestra ciudad?', `FemaleText_loc1`='어째서 스랄 님께선 우리 도시에 이런 일이 일어나게 두신 거죠?', `FemaleText_loc4`='萨尔怎么能听任我们的城市发生这种事？', `FemaleText_loc5`='為什麼索爾會讓這種事情發生在我們的城市?', `FemaleText_loc7`='¿Por qué está permitiendo Thrall que ocurra esto a nuestra ciudad?' WHERE `ID`=32239;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조용히!', `MaleText_loc4`='安静！', `MaleText_loc5`='安靜!!!', `MaleText_loc7`='¡SILENCIO!' WHERE `ID`=32240;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 얼라이언스와 함께 모두 전쟁에 나가기 직전일세!', `MaleText_loc4`='我们正处在与联盟爆发全面战争的边缘！', `MaleText_loc5`='我們和聯盟正在全面開戰的邊緣!', `MaleText_loc7`='¡Estamos al borde de una encarnizada Guerra contra la Alianza!' WHERE `ID`=32241;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비극적인 일이 노스렌드에서 펼쳐지고 있네. 대족장께서는 우리를 안전하게 지키고자 온 힘을 다하고 계시네.', `MaleText_loc4`='诺森德发生了许多悲剧事件。酋长正在尽力保障我们的安全。', `MaleText_loc5`='北裂境發生了一連串的悲劇。大酋長正在盡一切的努力保護我們的安全。', `MaleText_loc7`='En Rasganorte han tenido lugar eventos trágicos. El Jefe de Guerra hace todo lo que puede para mantenernos a salvo.' WHERE `ID`=32242;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모든 업무와 가게는 추후 통보가 있기 전까지 문을 닫을 걸세! 내 얘긴 끝났네!', `MaleText_loc4`='在没有进一步的通告前，所有的服务设施和商店都不得开业！就是这样！', `MaleText_loc5`='所有的服務與商店都維持關閉直到進一步通知!就是這樣!', `MaleText_loc7`='¡Todos los servicios y tiendas deberán permanecer cerrados hasta nueva orden! ¡Y punto!' WHERE `ID`=32243;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 지루한 듯 크라서스 착륙장을 둘러봅니다.', `FemaleText_loc4`='%s百无聊赖地在克拉苏斯平台上转悠。', `FemaleText_loc5`='%s看看卡薩斯平臺四周，有點無聊。', `FemaleText_loc7`='%s mira aburrida alrededor del Alto de Krasus.' WHERE `ID`=32244;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 손으로 입을 가리고 조용히 하품을 합니다.', `FemaleText_loc4`='%s抬起手掌，轻轻地打了个哈欠。', `FemaleText_loc5`='%s默默地掩著嘴打了個呵欠。', `FemaleText_loc7`='%s bosteza silenciosamente tapándose la boca con la palma de su mano.' WHERE `ID`=32245;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지뢰에 맞았습니다!', `MaleText_loc4`='我被地雷炸到了！', `MaleText_loc5`='我被地雷擊中!', `MaleText_loc7`='¡Mina pegarme!', `FemaleText_loc1`='지뢰에 맞았습니다!', `FemaleText_loc4`='我被地雷炸到了！', `FemaleText_loc5`='我被地雷擊中!', `FemaleText_loc7`='¡Mina pegarme!' WHERE `ID`=32246;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자, 구름날개야. 한 바퀴 돌아보자꾸나.', `FemaleText_loc4`='来吧，云翼。我们来飞一圈。', `FemaleText_loc5`='來，雲翼。讓我們去繞一圈。', `FemaleText_loc7`='Ven, Alanube. Demos una vuelta.' WHERE `ID`=32247;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드 명중!', `MaleText_loc4`='我被部落击中了！', `MaleText_loc5`='部落命中!', `MaleText_loc7`='¡Golpe a la Horda!', `FemaleText_loc1`='호드 명중!', `FemaleText_loc4`='我被部落击中了！', `FemaleText_loc5`='部落命中!', `FemaleText_loc7`='¡Golpe a la Horda!' WHERE `ID`=32248;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 가볍게 한숨지으며 어깨를 으쓱해 보입니다.', `FemaleText_loc4`='%s轻轻地叹了口气，耸了耸肩。', `FemaleText_loc5`='%s輕輕地嘆了一口氣，並且活動了一下肩膀。', `FemaleText_loc7`='%s suspira suavemente y mueve los hombros.' WHERE `ID`=32249;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스 명중!', `MaleText_loc4`='我被联盟击中了！', `MaleText_loc5`='聯盟命中!', `MaleText_loc7`='¡Golpe a la Alianza!', `FemaleText_loc1`='얼라이언스 명중!', `FemaleText_loc4`='我被联盟击中了！', `FemaleText_loc5`='聯盟命中!', `FemaleText_loc7`='¡Golpe a la Alianza!' WHERE `ID`=32250;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좀 따분한 걸, 구름날개야. 자 가자!', `FemaleText_loc4`='好无聊啊，云翼。走吧！', `FemaleText_loc5`='我好無聊，雲翼。飛吧，飛吧!', `FemaleText_loc7`='Estoy aburrida, Alanube. ¡Vamos, vamos!' WHERE `ID`=32251;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='구름날개야, 나만큼이나 들떠 있구나? 그럼 함께 날아올라 보자!', `FemaleText_loc4`='你也像我一样安静不下来吧，云翼？那我们去飞一会儿吧！', `FemaleText_loc5`='和我一樣靜不下來嗎，雲翼?那讓我們一同飛上天吧!', `FemaleText_loc7`='¿Estás igual de impaciente que yo, Alanube? ¡Entonces volemos!' WHERE `ID`=32252;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리가 가는 길은 신성하다. 토림을 저버리고 리치 왕과 같은 부류가 되느니 차라리 죽음을 선택하리라.', `FemaleText_loc4`='我们的道路是神圣的。我们宁愿死去，也不会背弃托里姆，与巫妖王同流合污。', `FemaleText_loc5`='我們的道路是神聖的。在我們拋棄索林姆之前，我們將會選擇死亡，加入巫妖王的一方。', `FemaleText_loc7`='Nuestra senda es sagrada. Elegiremos la muerte antes de abandonar a Thorim y unirnos a las huestes del Rey Exánime.' WHERE `ID`=32253;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무나도 오래 난 내 형제를 묵인했다. 이제 모든 걸 제자리로 돌려놓을 때이다. 내 형제와 그의 추종자들을 처단할 때란 말이다.', `MaleText_loc4`='我不能再纵容我的兄弟了。是时候纠正他犯下的过错了。我们要消灭他和他的追随者。', `MaleText_loc5`='我已經容忍我兄弟太久了。現在該是時候導正了。該是毀滅他和他手下的時候了。', `MaleText_loc7`='He soportado a mi hermano durante mucho tiempo. Es hora de dejar las cosas claras. Es hora de destruirlos a él y a sus seguidores.' WHERE `ID`=32254;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발견! $n|1이;가; 새로운 주문각인술을 발견했습니다!', `MaleText_loc4`='重大发现！ $n发现了一种新的铭文！', `MaleText_loc5`='大發現!$n發現了新的銘文!', `MaleText_loc7`='¡DESCUBRIMIENTO! ¡$n ha descubierto una nueva inscripción!', `FemaleText_loc1`='발견! $n|1이;가; 새로운 주문각인술을 발견했습니다!', `FemaleText_loc4`='重大发现！ $n发现了一种新的铭文！', `FemaleText_loc5`='大發現!$n發現了新的銘文!', `FemaleText_loc7`='¡DESCUBRIMIENTO! ¡$n ha descubierto una nueva inscripción!' WHERE `ID`=32255;
