UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 가족들에게 전해주시오...$b$b마지막까지 가족을 생각했노라고...', `MaleText_loc4`='请转告我的家人……$b$b我临死前还记挂着他们……', `MaleText_loc5`='告訴我的家人...$b$b我最後想的都是他們...', `MaleText_loc7`='Di a mi familia... $B$BQue en los últimos instantes pensé en ellos...', `FemaleText_loc1`='내 가족들에게 전해주세요...$b$b마지막까지 가족을 생각했다고...', `FemaleText_loc4`='请转告我的家人……$b$b我临死前还记挂着他们……', `FemaleText_loc5`='告訴我的家人...$b$b我最後想的都是他們...', `FemaleText_loc7`='Di a mi familia... $B$BQue en los últimos instantes pensé en ellos...' WHERE `ID`=32258;
