UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부탁이오, $r 동지여...$B$B스컬지의 살아있는 시체가 되긴 싫소!', `MaleText_loc4`='求求你，$r……$b$b我不想被天灾军团复活！', `MaleText_loc5`='拜託，$r...$b$b別留下任何東西可以讓天譴軍喚醒!', `MaleText_loc7`='Por favor, $r...$b$b¡No dejes nada que la Plaga pueda resucitar!', `FemaleText_loc1`='부탁입니다, $r 동지여...$B$B스컬지의 살아있는 시체가 되긴 싫습니다!', `FemaleText_loc4`='求求你，$r……$b$b我不想被天灾军团复活！', `FemaleText_loc5`='拜託，$r...$b$b別留下任何東西可以讓天譴軍喚醒!', `FemaleText_loc7`='Por favor, $r...$b$b¡No dejes nada que la Plaga pueda resucitar!' WHERE `ID`=32261;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='편히 가십시오, 얼라이언스의 영웅이여!', `MaleText_loc4`='一路走好，联盟的英雄！', `MaleText_loc5`='一路好走，聯盟的英雄!', `MaleText_loc7`='¡Que tengas buen viaje, héroe de la Alianza!', `FemaleText_loc1`='편히 가십시오, 얼라이언스의 영웅이여!', `FemaleText_loc4`='一路走好，联盟的英雄！', `FemaleText_loc5`='一路好走，聯盟的英雄!', `FemaleText_loc7`='¡Que tengas buen viaje, héroe de la Alianza!' WHERE `ID`=32262;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오크들이여, 그대들의 칼을 조심하라!', `MaleText_loc4`='握紧你们的武器，兽人！', `MaleText_loc5`='注意你的刀鋒，獸人!', `MaleText_loc7`='¡Preparen sus hojas, orcos!', `FemaleText_loc1`='오크들이여, 그대들의 칼을 조심하라!', `FemaleText_loc4`='握紧你们的武器，兽人！', `FemaleText_loc5`='注意你的刀鋒，獸人!', `FemaleText_loc7`='¡Preparen sus hojas, orcos!' WHERE `ID`=32263;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투를 준비하라, 연금술 실험실에 있는 자들의 입구에 파멸의 역병을 이미 뿌려놓은 듯하다!', `MaleText_loc4`='准备战斗，炼金区的叛徒们似乎把城门当作了目标地点！', `MaleText_loc5`='準備戰鬥，看來鍊金房已經有他們的荒疫瞄準著入口!', `MaleText_loc7`='¡Preparaos para la batalla! ¡Parece que El Apothecarium ya apunta hacia la entrada con su añublo!', `FemaleText_loc1`='전투를 준비하라, 연금술 실험실에 있는 자들의 입구에 파멸의 역병을 이미 뿌려놓은 듯하다!', `FemaleText_loc4`='准备战斗，炼金区的叛徒们似乎把城门当作了目标地点！', `FemaleText_loc5`='準備戰鬥，看來鍊金房已經有他們的荒疫瞄準著入口!', `FemaleText_loc7`='¡Preparaos para la batalla! ¡Parece que El Apothecarium ya apunta hacia la entrada con su añublo!' WHERE `ID`=32264;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='승리를 향해 전진하라, 오크들이여!', `MaleText_loc4`='朝着荣耀之路前进吧，兽人！', `MaleText_loc5`='衝向榮耀，獸人們!', `MaleText_loc7`='¡Seguid hacia la gloria, orcos!', `FemaleText_loc1`='승리를 향해 전진하라, 오크들이여!', `FemaleText_loc4`='朝着荣耀之路前进吧，兽人！', `FemaleText_loc5`='衝向榮耀，獸人們!', `FemaleText_loc7`='¡Seguid hacia la gloria, orcos!' WHERE `ID`=32265;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 비열한 퓨트리스는 벗어나지 못할 것이다!', `MaleText_loc4`='普特雷斯那个恶棍是不会得逞的！', `MaleText_loc5`='該死的普崔司是逃不掉的!', `MaleText_loc7`='¡Ese desgraciado de Putress no se saldrá con la suya!', `FemaleText_loc1`='저 비열한 퓨트리스는 벗어나지 못할 것이다!', `FemaleText_loc4`='普特雷斯那个恶棍是不会得逞的！', `FemaleText_loc5`='該死的普崔司是逃不掉的!', `FemaleText_loc7`='¡Ese desgraciado de Putress no se saldrá con la suya!' WHERE `ID`=32266;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어째서 예상치 못했는가, 공포의 군주를 믿을 수 있다고 생각하다니!', `MaleText_loc4`='我们竟然没有料到这样的后果，竟然相信了恐惧魔王！', `MaleText_loc5`='我們怎麼會沒想到會發生這種事，居然以為一個驚懼領主是可以相信的!', `MaleText_loc7`='¿Cómo no hemos imaginado que esto ocurriría? ¡Mira que confiar en un Señor del Terror!', `FemaleText_loc1`='어째서 예상치 못했는가, 공포의 군주를 믿을 수 있다고 생각하다니!', `FemaleText_loc4`='我们竟然没有料到这样的后果，竟然相信了恐惧魔王！', `FemaleText_loc5`='我們怎麼會沒想到會發生這種事，居然以為一個驚懼領主是可以相信的!', `FemaleText_loc7`='¿Cómo no hemos imaginado que esto ocurriría? ¡Mira que confiar en un Señor del Terror!' WHERE `ID`=32267;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저주받은 자들의 교단이 이것들을 남기는 실수를 하다니 믿을 수가 없소.', `MaleText_loc4`='真不敢相信，诅咒教派竟然如此粗心，把这些东西都落下了。', `MaleText_loc5`='我很難相信詛咒神教居然會這麼不小心，留下這個。', `MaleText_loc7`='Apenas puedo creer que el Culto fuera tan descuidado como para dejarse esto.' WHERE `ID`=32268;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 공격에 합류할 준비를 마쳤습니다, 케리토스. 해골 그리핀은 준비되었습니까?', `MaleText_loc4`='我准备好发起进攻了，克里托斯。给我一匹骷髅狮鹫吧？', `MaleText_loc5`='我已經準備好加入突襲了，凱力多斯。你有替我準備骷髏獅鷲獸嗎?', `MaleText_loc7`='Estoy listo para unirme al ataque, Keritose. ¿Tienes un grifo esquelético preparado para mí?', `FemaleText_loc1`='전 공격에 합류할 준비를 마쳤습니다, 케리토스. 해골 그리핀은 준비되었습니까?', `FemaleText_loc4`='我准备好发起进攻了，克里托斯。给我一匹骷髅狮鹫吧？', `FemaleText_loc5`='我已經準備好加入突襲了，凱力多斯。你有替我準備骷髏獅鷲獸嗎?', `FemaleText_loc7`='Estoy lista para unirme al ataque, Keritose. ¿Tienes un grifo esquelético preparado para mí?' WHERE `ID`=32269;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<지배의 눈으로 흐물거리는 추적자를 조종합니다.>', `MaleText_loc4`='<通过眼睛控制一只轻盈追迹者。>', `MaleText_loc5`='<透過眼睛控制一個輕盈潛獵者。>', `MaleText_loc7`='<Controla a un acechador ágil a través del ojo.>', `FemaleText_loc1`='<지배의 눈으로 흐물거리는 추적자를 조종합니다.>', `FemaleText_loc4`='<通过眼睛控制一只轻盈追迹者。>', `FemaleText_loc5`='<透過眼睛控制一個輕盈潛獵者。>', `FemaleText_loc7`='<Controla a un acechador ágil a través del ojo.>' WHERE `ID`=32270;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 왕국은 스컬지의 것... 오직 죽은 자만 들어올 수 있다!', `MaleText_loc4`='这个王国已经属于天灾军团了。只有亡者才能通行！', `MaleText_loc5`='這個王國屬於天譴軍團。只有亡者才能進入!', `MaleText_loc7`='Este reino pertenece a la Plaga. ¡Sólo pueden entrar los muertos!' WHERE `ID`=32271;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하시 타크 히이 타아아!', `MaleText_loc4`='Hassh tak heeeek ta！', `MaleText_loc5`='(蟲族語)亡者永存!', `MaleText_loc7`='¡Hassh tak heeeek ta!' WHERE `ID`=32272;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 여기엘 오다니...', `MaleText_loc4`='你们的到来体现了自身的愚蠢。', `MaleText_loc5`='你的到來說明了你的愚蠢。', `MaleText_loc7`='Fuiste insensato al venir.' WHERE `ID`=32273;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아눕아락 님의 뜻이다!', `MaleText_loc4`='遵照阿努巴拉克的命令！', `MaleText_loc5`='以阿努巴拉克之令!', `MaleText_loc7`='¡Como ordene Anub''arak!' WHERE `ID`=32274;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자가 몰려온다! 가라! 놈들을 해치우고 시체를 가져와!', `MaleText_loc4`='我们被攻击了！立刻出击，把敌人的尸体给我带回来！', `MaleText_loc5`='我們被圍攻了!出擊!並且把他們的屍體給帶回來!', `MaleText_loc7`='¡Estamos rodeados! ¡Ataquen y traigan sus cadáveres!' WHERE `ID`=32275;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='문을 보호해야 한다. 공격! 모두 박살을 내버려라!', `MaleText_loc4`='我们必须守住大门。进攻！将他们撕成碎片！', `MaleText_loc5`='我們必須守住大門。進攻!將他們撕成碎片!', `MaleText_loc7`='Debemos defender la compuerta. ¡Ataquen! ¡Despedácenlos!' WHERE `ID`=32276;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 수를 써서라도 문을 지켜야 한다! 가서 놈들을 쓸어버려!', `MaleText_loc4`='不惜一切代价保卫城门！把他们全都撕碎！', `MaleText_loc5`='不惜一切代價保衛城門!把他們全都撕碎!', `MaleText_loc7`='Debemos proteger la compuerta a cualquier precio. ¡Destrócenlos!' WHERE `ID`=32277;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='통로를 주시해라. 아무도 들여보내선 안 돼!', `MaleText_loc4`='小心守着隧道。我们不能让任何人通过！', `MaleText_loc5`='注意隧道。絕不能讓任何人通過!', `MaleText_loc7`='Vigilen ese túnel. ¡No debe pasar nadie!' WHERE `ID`=32278;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발소리가 들리는데... 경계 태세를 취해라.', `MaleText_loc4`='我听到了脚步声。提高警惕。', `MaleText_loc5`='我聽見腳步聲。戒備。', `MaleText_loc7`='Siento pasos. Monten guardia.' WHERE `ID`=32279;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='산 자가 왔나 보군. 준비해라.', `MaleText_loc4`='活人的气息。准备战斗。', `MaleText_loc5`='我感覺到活物。做好準備。', `MaleText_loc7`='Percibo a los vivos. Prepárense.' WHERE `ID`=32280;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들은 굶주렸지...', `MaleText_loc4`='它们很饿了……', `MaleText_loc5`='它們很餓了...', `MaleText_loc7`='Tienen hambre…' WHERE `ID`=32281;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얘들아, 밥 시간이다!', `MaleText_loc4`='宠物们，该吃晚饭了！', `MaleText_loc5`='寵物們，該吃晚飯了!', `MaleText_loc7`='¡Hora de comer, mis mascotas!' WHERE `ID`=32282;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고마워할 자격 따위... 잃은 지... 오래다...', `MaleText_loc4`='我本该感谢你们的……但我已经没有那个资格了……', `MaleText_loc5`='我本該感謝你們的...但我已經沒有那個資格了...', `MaleText_loc7`='Debería dar las gracias... pero perdí la costumbre hace mucho tiempo…' WHERE `ID`=32283;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진흙탕 채석장으로 돌아가십시오!', `MaleText_loc4`='返回哭泣采掘场！', `MaleText_loc5`='回到哀泣礦場!', `MaleText_loc7`='¡Regresa a la Cantera Llorosa!' WHERE `ID`=32284;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아서스의 약점은 오만함이다. 놈의 힘이 강해질수록 약점도 커지지. 칠흑의 기사단이 그 반역자 왕자 놈을 공격할 기회가 분명히 있을 것이다. 내 장담하지.', `MaleText_loc4`='阿尔萨斯的弱点就是骄傲。随着他的力量日益强大，这个弱点也越来越明显。我相信，黑锋骑士团一定能找到机会击败这位前王子。', `MaleText_loc5`='阿薩斯的弱點就在於他的驕傲。那個弱點只會隨著他的力量而增長。黯刃會有機會擊敗這個昔日的王子 - 這一點我從不懷疑。', `MaleText_loc7`='El orgullo es la debilidad de Arthas. Esa debilidad crece al mismo ritmo que su poder. La Espada de Ébano tendrá la oportunidad de atacar al que otrora fue su Príncipe... no me cabe duda de ello.' WHERE `ID`=32285;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코르크론, 멈춰라!', `MaleText_loc4`='库卡隆，退下！', `MaleText_loc5`='柯爾克隆，退下!', `MaleText_loc7`='¡Kor''kron, detente!' WHERE `ID`=32286;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제이나...', `MaleText_loc4`='吉安娜……', `MaleText_loc5`='珍娜...', `MaleText_loc7`='Jaina...' WHERE `ID`=32287;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='스랄, 무슨 일이 있었나요? 폐하께서 전쟁을 준비하십니다...', `FemaleText_loc4`='萨尔，出了什么事？国王正在备战……', `FemaleText_loc5`='索爾，發生了什麼事?國王正在準備開戰...', `FemaleText_loc7`='Thrall, ¿qué ocurrió? El Rey se prepara para la guerra…' WHERE `ID`=32288;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제이나, 분노의 관문 사건은 내부의 배신자가 벌인 짓이오...', `MaleText_loc4`='吉安娜，天谴之门的事，是因为我们中间出了叛徒……', `MaleText_loc5`='珍娜，憤怒之門所發生的事情。是來自我們內部的叛亂...', `MaleText_loc7`='Jaina, ¿qué ocurrió en la Puerta de Cólera? Fue una traición desde adentro...' WHERE `ID`=32289;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='프라우드무어여, 대족장께선 진실을 말하고 계시다. 이번 일은 바리마트라스와 퓨트리스의 얕은 꾀로 일어난 일이지. 호드가 한 일이 아니다.', `FemaleText_loc4`='普罗德摩尔女士，酋长说的是实话。这是瓦里玛萨斯和大药剂师普特雷斯安排的诡计，并非部落的本意。', `FemaleText_loc5`='普勞德摩爾女士，大酋長所言無虛。這是由瓦里瑪薩斯和大藥劑師普崔司所發動的。這並非部落的陰謀。', `FemaleText_loc7`='Lady Valiente, el Jefe de Guerra dice la verdad. Este subterfugio fue iniciado por Varimathras y el Gran boticario Putress. No es obra de la Horda. ' WHERE `ID`=32290;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='얼라이언스와 호드 군대가 연합하여 분노의 관문을 공격하자마자, 언더시티에서 반란이 일어났다. 바리마트라스와 그의 악마 종자들이 공격한 것이었지. 수많은 백성이 불시에 살해당했고 나도 간신히 도망쳤다.', `FemaleText_loc4`='自从联盟和部落进军天谴之门以来，幽暗城就发生了暴乱。瓦里玛萨斯和他的恶魔同党叛变了，残忍地杀害了数百名无辜的平民。我是好不容易才逃出来的。', `FemaleText_loc5`='當部落與聯盟的聯合部隊開始圍攻憤怒之門時，幽暗城卻發生了一場叛亂。瓦里瑪薩斯與一大群他的惡魔同伴發動攻擊。我們數以百計的同胞在動亂中被殺死，我只能勉強地自己逃出來。', `FemaleText_loc7`='Al comenzar el asalto de las fuerzas combinadas de la Horda y la Alianza sobre la Puerta de Cólera, en las Entrañas estalló una revolución. Varimathras y las hordas de sus demoníacos hermanos atacaron. Mi gente murió de a centenares durante el golpe. Yo apenas logré escapar con vida.' WHERE `ID`=32291;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드 연합은 언더시티를 잃었소.', `MaleText_loc4`='部落已经失去了幽暗城。', `MaleText_loc5`='部落失去了幽暗城。', `MaleText_loc7`='La Horda ha perdido las Entrañas.' WHERE `ID`=32292;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 우리는 언더시티를 되찾으러 갈 거요. 용서할 수 없는 범죄자들에게 정의의 심판을 내릴 것이오.', `MaleText_loc4`='我们正准备围攻那座城市，将这群不可饶恕的罪魁祸首绳之以法。', `MaleText_loc5`='我們現在正準備要反攻那座城市，讓那些兇手替他們不可饒恕的罪行付出代價。', `MaleText_loc7`='Ahora nos preparamos para asediar la ciudad y llevar ante la justicia a los perpetradores de este crimen imperdonable.' WHERE `ID`=32293;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 싸운다면, 노스렌드에 둘로 나뉘어진 병력을 리치 왕이 손쉽게 무너뜨릴 것이오.', `MaleText_loc4`='如果闹起内讧，巫妖王就会摧毁我们在诺森德的驻军。', `MaleText_loc5`='如果我們被迫開戰，那巫妖王會在北裂境將我們各個擊破。', `MaleText_loc7`='Si nos vemos obligados a pelear, el Rey Exánime destruirá a nuestras fuerzas divididas en Rasganorte.' WHERE `ID`=32294;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모든 일을 바로잡겠소, 제이나. 그대의 왕에게 내 뜻을 잘 전해 주시오.', `MaleText_loc4`='我们会妥善处理的，吉安娜。请你把这里的情况转告国王吧。', `MaleText_loc5`='我們不能讓這件事情發生，珍娜。告訴你的國王你在這裡聽見的每一件事。', `MaleText_loc7`='Haremos lo correcto, Jaina. Cuéntale a tu rey todo lo que has aprendido aquí.' WHERE `ID`=32295;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='폐하께 반드시 전하도록 하지요, 스랄. 그런데...', `FemaleText_loc4`='我会转告国王的，萨尔，但是……', `FemaleText_loc5`='我會把消息帶給烏瑞恩王，索爾，但是...', `FemaleText_loc7`='Yo le llevaré esta información al Rey Wrynn, Thrall, pero…' WHERE `ID`=32296;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='볼바르 님은 폐하께 형제나 다름없었죠. 폐하가 안 계실 때, 얼라이언스를 단결시키고, 가장 어두웠던 시기에 저희에게 힘을 주셨어요. 안두인 님을 아들처럼 키우기도 했죠.', `FemaleText_loc4`='伯瓦尔与他情同手足。国王离开期间，是他维系着联盟的团结。在最艰难的日子里，他是人民的支柱。他监护着安度因，将其视如己出。', `FemaleText_loc5`='伯瓦爾就像是他的手足。在國王不在的時候，伯瓦爾讓聯盟不至分裂。在最黑暗的時候給了人民支持下去的力量。他照顧安杜因如同自己的孩子。', `FemaleText_loc7`='Bolvar era como un hermano para mí. En la ausencia del Rey, Bolvar mantuvo a la Alianza unida. Supo darle fuerza a nuestro pueblo en las horas más oscuras. Él cuidó de Anduin, criándolo como si fuera suyo.' WHERE `ID`=32297;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='분노가 폐하를 삼켜버릴까 두려워요, 스랄. 이성을 찾으시길 바라지만, 최악의 상황도 준비해야 합니다... 전쟁 말이에요.', `FemaleText_loc4`='我担心国王克制不了心中的怒火，萨尔。希望我能说服他吧，但是我们必须做好最坏的打算……比如战争。', `FemaleText_loc5`='我深怕憤怒將會淹沒他的理智，索爾。我依舊希望他能維持理性，但我們得做最壞的打算...迎接戰爭的到來。', `FemaleText_loc7`='Me temo que la ira lo consumirá, Thrall. Aún tengo esperanzas de que la razón prevalecerá, pero debemos prepararnos para lo peor... la guerra.' WHERE `ID`=32298;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대족장이여, 안녕히. 다음에는 동지로 만날 수 있기를 빕니다.', `FemaleText_loc4`='再见，酋长。希望下次见面时，我们能够成为盟友。', `FemaleText_loc5`='再會，大酋長。我期待下次見面時，我們將會是盟友。', `FemaleText_loc7`='Adiós, Jefe de Guerra. Ruego por que nuestro próximo encuentro sea como aliados.' WHERE `ID`=32299;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코르크론, 언더시티로 순간이동할 준비를 하라.', `MaleText_loc4`='库卡隆，准备传送到幽暗城。', `MaleText_loc5`='柯爾克隆，準備傳送至幽暗城。', `MaleText_loc7`='Kor''kron, prepara un transporte a las Entrañas.' WHERE `ID`=32300;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='첫 번째 페이지를 봅니다.', `MaleText_loc4`='字填在此', `MaleText_loc5`='文章到此為止。', `MaleText_loc7`='TEXT GOES HERE' WHERE `ID`=32301;
