UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 그러셨어요! 그가 싫어할 거예요.', `MaleText_loc4`='你不该那么做的！他不喜欢那样。', `MaleText_loc5`='你不應該這麼做的!他不會喜歡的!', `MaleText_loc7`='¡No debiste haber hecho eso! No le va a gustar.' WHERE `ID`=32338;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드의 영웅들이여, 대족장의 부름을 받들라!', `MaleText_loc4`='部落的英雄，酋长在召唤你们！', `MaleText_loc5`='部落的英雄們，聆聽你們的大酋長!!!', `MaleText_loc7`='¡HÉROES DE LA HORDA, SU JEFE DE GUERRA LOS LLAMA!' WHERE `ID`=32339;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피바람을 불러 일으키자! 호드의 용사들이여! 쓰러진 형제자매를 위해 싸우리라! 슬퍼할 필요는 없다! 그들은 모두 명예롭게 죽었노라!', `MaleText_loc4`='鲜血与雷鸣，部落的勇士们！今天，我们要为死去的兄弟姐妹而战！不要悲伤，因为他们都是心怀荣耀的勇者！', `MaleText_loc5`='鮮血與雷霆!部落的勇士們!我們今天要為死去的兄弟姊妹而戰!我們不需要替他們哀悼，因為他們全都是光榮地死去!', `MaleText_loc7`='¡Sangre y trueno, campeones de la Horda! ¡Hoy luchamos por nuestros hermanos y hermanas caídos! ¡No sufran sus muertes, pues todos cayeron con honor en sus corazones!' WHERE `ID`=32340;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='큰 전투가 눈앞에 닥쳤지만, 함께라면 우리는 적을 흔적도 없이 날려 버릴 것이다! 감히 호드에 맞서 이런 중한 범죄를 저지른 놈들은 처절한 응징을 받으리라!', `MaleText_loc4`='虽然我们面临着巨大的分歧，但只要我们齐心协力，就一定能消灭敌人！所有对部落的不公正都将被势不可挡的力量碾碎！', `MaleText_loc5`='儘管我們面對艱困的挑戰，但我們團結的力量將會殲滅所有阻礙我們的人!這些對部落的不義之舉將會面對無法抵抗的復仇之師!', `MaleText_loc7`='Aunque hoy enfrentamos un conflicto colosal, ¡nuestro poder combinado arrasará con quienes se nos opongan! ¡Las injusticias tan severas cometidas contra la Horda se encontrarán con la fuerza indetenible del juicio!' WHERE `ID`=32341;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위대한 정령에게 도움을 청하노라! 호드에 그대의 축복을 베풀라! 오늘 우리는 정당하고 명예롭게 싸우리라!', `MaleText_loc4`='四方之灵，将你们的祝福赐予部落吧！今天，我们的事业是正义而高尚的！', `MaleText_loc5`='我呼喚你們，偉大的精靈!給予部落你們的祝福!因為今天我們為了公理與正義而戰!', `MaleText_loc7`='¡Llamo a sus grandes espíritus! ¡Brinden su bendición a la Horda! ¡Ya que hoy nuestra causa es justa y honrada!' WHERE `ID`=32342;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='공중전이 점점 치열해지고 있어요, $n. 호드도 우리도 폭격지와 잃어버린 희망의 계곡으로 폭격기를 내보내고 있어요. 출격하시겠어요?', `FemaleText_loc4`='战争的阴云已经迫近，$n。我们和部落都派了轰炸机进入轰炸船和失落希望之谷。你愿意参加这次行动吗？', `FemaleText_loc5`='空中戰鬥正在熱烈進行，$n。我們和部落都派出了轟炸機前往轟炸地和逝望山谷。你願意加入嗎?', `FemaleText_loc7`='La batalla aérea ha estallado cerca, $n. Tanto nosotros como la Horda enviamos bombarderos a El Bombardeo y a El Valle de la Esperanza Perdida. ¿Participarás en la batalla?' WHERE `ID`=32343;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭격기를 준비해 주십시오!', `MaleText_loc4`='给我一架轰炸机！', `MaleText_loc5`='給我一架轟炸機!', `MaleText_loc7`='¡Dame un bombardero!', `FemaleText_loc1`='폭격기를 준비해 주십시오!', `FemaleText_loc4`='给我一架轰炸机！', `FemaleText_loc5`='給我一架轟炸機!', `FemaleText_loc7`='¡Dame un bombardero!' WHERE `ID`=32344;
