UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좀 바쁜데요.', `MaleText_loc4`='我有点忙。', `MaleText_loc5`='有點忙。', `MaleText_loc7`='Un poco ocupado.', `FemaleText_loc1`='좀 바쁜데요.', `FemaleText_loc4`='我有点忙。', `FemaleText_loc5`='有點忙。', `FemaleText_loc7`='Un poco ocupada.' WHERE `ID`=32346;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐라고요? 전 바쁘다니까요.', `MaleText_loc4`='什么事？我正忙着呢。', `MaleText_loc5`='什麼?我現在很忙。', `MaleText_loc7`='¿Qué? Estoy ocupado.', `FemaleText_loc1`='뭐라고요? 전 바쁘다니까요.', `FemaleText_loc4`='什么事？我正忙着呢。', `FemaleText_loc5`='什麼?我現在很忙。', `FemaleText_loc7`='¿Qué? Estoy ocupada.' WHERE `ID`=32347;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일 하는 중이니 좀 가세요. 가란 말입니다.', `MaleText_loc4`='我在工作呢。走开。', `MaleText_loc5`='值勤中。滾。開。', `MaleText_loc7`='Estoy de servicio. VETE. DE. AQUÍ.', `FemaleText_loc1`='일 하는 중이니 좀 가세요. 가란 말입니다.', `FemaleText_loc4`='我在工作呢。走开。', `FemaleText_loc5`='值勤中。滾。開。', `FemaleText_loc7`='Estoy de servicio. VETE. DE. AQUÍ.' WHERE `ID`=32348;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자들! 누가 감히 고대 왕국을 침범하는가?', `MaleText_loc4`='入侵者！是谁闯入了古代王国？', `MaleText_loc5`='入侵者!誰擅自闖入古王國?', `MaleText_loc7`='¡Intrusos! ¿Quién se atreve a entrar en El Antiguo Reino sin permiso?' WHERE `ID`=32350;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 제군들. 본때를 보여주자고!', `MaleText_loc4`='小伙子们，咱们动手吧！', `MaleText_loc5`='好，小夥子們，上吧!', `MaleText_loc7`='¡Vale, chicos, hagamos esto!' WHERE `ID`=32351;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘했어! 한숨 돌리고 바로 출발한다.', `MaleText_loc4`='干得好！我们只能休息一会儿。', `MaleText_loc5`='幹得好!我們只能休息一下。', `MaleText_loc7`='¡Buen trabajo! Solo podemos descansar un instante.' WHERE `ID`=32352;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엄호해 줘서 고맙소! 우린 지원 병력이 도착할 때까지 관문에서 대기하겠소.', `MaleText_loc4`='谢谢你掩护我们回来！我们会一边等待援军，一边守住大门。', `MaleText_loc5`='感謝你替我們掩護!我們會一邊等待增援，一邊守住大門。', `MaleText_loc7`='¡Gracias por cubrirnos las espaldas allí! Aguantaremos en la puerta mientras esperamos refuerzos.' WHERE `ID`=32353;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n의 신종 전투 기술이 비룡기수의 균형을 흔들리게 합니다.', `FemaleText_loc4`='$n超乎寻常的作战技巧令龙骑士手忙脚乱起来。', `FemaleText_loc5`='$n的奇特戰鬥技巧讓飛龍騎兵失去了平衡。', `FemaleText_loc7`='La exótica técnica de lucha de $n hace que el jinete de dracos pierda el equilibrio.' WHERE `ID`=32354;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아니, 뭐... 지?!', `FemaleText_loc4`='怎么回事？！', `FemaleText_loc5`='什麼--?!', `FemaleText_loc7`='¿Qué demo...?' WHERE `ID`=32355;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='야수 같이 싸우는군!', `FemaleText_loc4`='你战斗起来就像只野兽！', `FemaleText_loc5`='你的戰鬥有如野獸!', `FemaleText_loc7`='¡Luchas como una bestia!' WHERE `ID`=32356;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그걸 어디서 배웠지?', `FemaleText_loc4`='这一招你是从哪儿学来的？', `FemaleText_loc5`='你怎麼學會那招的?', `FemaleText_loc7`='¿Dónde aprendiste eso?' WHERE `ID`=32357;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드를 위해 언더시티를 되찾을 공격을 시작할 준비가 되었나?', `MaleText_loc4`='你准备好参与夺回幽暗城一战了吗，$n？', `MaleText_loc5`='你準備好展開攻擊，並且替部落奪回幽暗城嗎，$n?', `MaleText_loc7`='¿Estás $gpreparado:preparada; para comenzar el asalto y recuperar Entrañas para la Horda, $n?' WHERE `ID`=32358;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장님, 전 준비되었습니다.', `MaleText_loc4`='我准备好了，酋长。', `MaleText_loc5`='我準備好了，大酋長。', `MaleText_loc7`='Estoy preparado, Jefe de Guerra.', `FemaleText_loc1`='대족장님, 전 준비되었습니다.', `FemaleText_loc4`='我准备好了，酋长。', `FemaleText_loc5`='我準備好了，大酋長。', `FemaleText_loc7`='Estoy preparada, Jefe de Guerra.' WHERE `ID`=32359;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정령들도 우리와 함께다, $n. 그들의 도움에 힘입어 바리마트라스와 퓨트리스를 막아내는 일을 우리 힘으로 해 낼 것이다! 록타르 오가르!', `MaleText_loc4`='元素之灵与我们同在，$n。在它们的帮助下，我们可以竭尽全力阻止瓦里玛萨斯和普特雷斯的阴谋得逞！LOK''TAR OGAR！', `MaleText_loc5`='元素與我們同在，$n。有著他們的幫助，我們可以全力阻止瓦里瑪薩斯和普崔司!為了部落!', `MaleText_loc7`='La fuerza de los elementos está con nosotros, $n. Con su ayuda, haremos todo lo que esté en nuestras manos para detener a Varimathras y a Putress. ¡LOK''TAR OGAR!' WHERE `ID`=32360;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언더시티 성문 앞에서 내 뒤로 집결하라! 잃어버린 도시를 되찾으러 진군하리라! 호드를 위하여!', `MaleText_loc4`='随我到幽暗城门口集合！我们要夺回这座沦陷的城市——为了部落！', `MaleText_loc5`='在我身後的幽暗城大門集結!我們很快就要攻入這淪陷的城市並且奪回它 - 為了部落!', `MaleText_loc7`='¡Pónganse detrás de mí en las puertas de las Entrañas! Pronto marcharemos por la ciudad caída y la reclamaremos... ¡PARA LA HORDA!' WHERE `ID`=32361;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바람의 정령이여, 사울팽의 아들에게 전쟁의 노래를 들려주어라! 쓰러진 우리의 동족이 이 전투로 명예를 회복하길 바라노라!', `MaleText_loc4`='风之灵，将这曲战歌送到小萨鲁法尔耳畔吧！为所有阵亡的同胞们报仇雪恨！', `MaleText_loc5`='風之靈，傳頌小薩魯法爾的戰歌吧!願我們所有死去的同胞能在這場戰役中獲得復仇!', `MaleText_loc7`='¡Espíritus del viento, lleven a Colmillosaurio el Joven la canción de guerra! ¡Que TODOS los hermanos caídos sean vengados en esta batalla!
' WHERE `ID`=32362;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언더시티 수복 작전을 시작한다! 전쟁의 뿔피리를 불어라! 호드의 용사들이여, 대족장의 힘을 내리노라!', `MaleText_loc4`='幽暗城的战斗即将打响！吹响战争的号角！部落的勇士们，接受酋长赋予你们的力量吧！', `MaleText_loc5`='幽暗城戰役即將展開!吹響戰爭的號角!部落的勇士們，分享你們大酋長的力量!', `MaleText_loc7`='¡La batalla por las Entrañas comienza ahora! ¡Hagan sonar los cuernos de guerra! Campeones de la Horda, ¡reciban el poder de la fuerza de su Jefe de guerra!' WHERE `ID`=32363;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='세상에나! 목소리 낮추세요, $n! 뭐예요? 우릴 모두 죽일 셈이에요?!$B$B당신이 누군지 말 안 해도 알고 있다고요! 얼라이언스에서 $n 모르는 사람이 어디 있어요?!$B$B제 도약로봇 어때요? 기계노움 설계를 바탕으로 만들었어요. 미끈하게 설계해서 공기저항을 최소화한 녀석이죠.', `FemaleText_loc4`='哎呀！小声点，$n！怎么？你想把我们害死吗？！$B$B我当然知道你是谁！你的大名早就在联盟中传遍了！$B$B你觉得我的跳跃机器人怎么样啊？她是根据机械侏儒的原理设计的，运行起来非常流畅，是以空气为动力的！', `FemaleText_loc5`='喔天啊!小聲一點，$n!什麼?你想害我們被殺死嗎?!$B$B我當然知道你是誰!聯盟之中誰沒聽過你的名字，$n?!$B$B說說看，你覺得我的彈跳機器人怎麼樣?她是根據機械地精的設計而做。光滑而符合空氣動力學!', `FemaleText_loc7`='¡Cielos! ¡Baja la voz, $n! ¿Qué? ¿Quieres que nos maten?$B$BClaro, ¡ya sé quién eres! ¿Hay alguien en la Alianza que no conozca tu nombre, $n?$B$BDime, ¿Qué te parece mi saltarrobot? Está basado en el diseño de los mecagnomos. ¡Elegante y aerodinámico!' WHERE `ID`=32364;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='워, 워, 워! 목소리 낮춰, $n! 쉿!$B$B<주위를 살피는 블라스트>$B$B서리 브리쿨 놈들이 알아채기라도 하면 어쩌려고?$B$B내 도약로봇 어때? 기계노움을 기반으로 만든 놈이야. 잘 빠졌지, 응?', `MaleText_loc4`='哇，哇，哇！小声点，$n。小声点！$B$B<布拉斯朝四周看了看。>$B$B你也不想我们被那些冰棍儿维库人发现吧？$B$B你觉得我的跳跃机器人怎么样啊？这是根据机械侏儒的原理设计的哦。很棒吧，对吗？', `MaleText_loc5`='哇，哇，哇!小聲點，$n。小聲點!$B$B<轟擊四處張望著。>$B$B我可不想被那些冰霜維酷人注意到我們，懂嗎?$B$B你覺得我的彈跳機器人怎麼樣?我跟根據機械地精的設計而製。很光滑，對吧?', `MaleText_loc7`='¡Ey, ey, ey! Baja el tono, $n. ¡Bájalo!$B$B<Bombatrueno mira alrededor.>$B$BNo queremos que esos vrykul de escarcha se den cuenta de que estamos aquí, ¿verdad?$B$B¿Qué te parece mi saltarrobot? Me he basado en el diseño de los mecagnomos. Ingenioso, ¿eh?' WHERE `ID`=32365;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전진!', `MaleText_loc4`='前进！', `MaleText_loc5`='前進!', `MaleText_loc7`='¡EN GUARDIA!' WHERE `ID`=32366;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위대한 바람이여, 길을 열어라!', `MaleText_loc4`='风之灵，扫清前进的道路！', `MaleText_loc5`='偉大的風之兄弟，替我們清出道路!', `MaleText_loc7`='¡Gran viento hermano, despeja nuestro camino!' WHERE `ID`=32367;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악마야, 정령에 맞서봐라!', `MaleText_loc4`='尝尝元素之灵的厉害，恶魔！', `MaleText_loc5`='你得面對元素之怒，惡魔!', `MaleText_loc7`='¡Responderás a los elementos, demonio!' WHERE `ID`=32368;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위대한 물의 정령이여, 이 타락을 씻어내라!', `MaleText_loc4`='水之灵，冲走这一切堕落吧！', `MaleText_loc5`='偉大的水靈，洗淨這些腐化!', `MaleText_loc7`='¡Gran espíritu del agua, lava esta corrupción!' WHERE `ID`=32369;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이미르하임으로 돌아가십시오. 그렇지 않으면 도약로봇이 산산조각날 것입니다!', `MaleText_loc4`='返回伊米海姆，不然跳跃机器人就会散架！', `MaleText_loc5`='回到依米海姆否則你的彈跳機器人就會摔成碎片!', `MaleText_loc7`='¡Regresa a Ymirheim o tu saltarrobot se hará añicos!' WHERE `ID`=32370;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비되었습니다, 브란. 쐐기돌을 만드시죠.', `MaleText_loc4`='我准备好了，布莱恩。我们把钥石拼起来吧。', `MaleText_loc5`='我準備好了，布萊恩。來完成拱心石吧。', `MaleText_loc7`='Estoy listo, Brann. Hagamos la piedra angular.', `FemaleText_loc1`='준비되었습니다, 브란. 쐐기돌을 만드시죠.', `FemaleText_loc4`='我准备好了，布莱恩。我们把钥石拼起来吧。', `FemaleText_loc5`='我準備好了，布萊恩。來完成拱心石吧。', `FemaleText_loc7`='Estoy lista, Brann. Hagamos la piedra angular.' WHERE `ID`=32371;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 각자 작업 위치로!', `MaleText_loc4`='教徒们，回去工作！', `MaleText_loc5`='回去工作，教徒!', `MaleText_loc7`='¡Volved al trabajo, cultores!' WHERE `ID`=32372;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무장 완료하고 출발 준비 끝냈소!', `MaleText_loc4`='报告长官！装配完毕，随时可以出发！', `MaleText_loc5`='整裝完成，準備出發，長官!', `MaleText_loc7`='¡Dispuestos y listos, señor!' WHERE `ID`=32373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부하들이 출동 준비 마쳤소. 명령만 내리시오!', `MaleText_loc4`='我的士兵已经准备好了——请下命令吧！', `MaleText_loc5`='我的手下已經做好準備 - 只等你的命令!', `MaleText_loc7`='Mis hombres están preparados y dispuestos... ¡solo da la orden!' WHERE `ID`=32374;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 다스리는 어둠의 왕국에 어서 오너라!', `MaleText_loc4`='欢迎来到我的黑暗王国！', `MaleText_loc5`='歡迎來到我的黑暗王國!', `MaleText_loc7`='¡Bienvenidos a mi reino de oscuridad!' WHERE `ID`=32375;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 부하들이 만든 소름끼치는 것들은 어떤가? 강력하지, 안 그런가?', `MaleText_loc4`='你喜欢我的那些恐怖的造物吗？很厉害，不是吗？', `MaleText_loc5`='我的爪牙造出的恐怖怪物還合你的胃口嗎?滋味還不錯，是嗎?', `MaleText_loc7`='¿Te has deleitado con la terrible creación de mi lacayo? Potente, ¿no?' WHERE `ID`=32376;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='출발 준비 완료했소.', `MaleText_loc4`='我们准备好了，长官。', `MaleText_loc5`='我們準備好了，長官!', `MaleText_loc7`='Estamos preparados, señor.' WHERE `ID`=32377;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='출발 준비 끝나면 말씀해 주시오.', `MaleText_loc4`='指挥官，我们随时可以发动攻击，只等你下达命令！', `MaleText_loc5`='讓我們知道何時出發，指揮官!', `MaleText_loc7`='¡Avísanos cuando quieras que dirijamos la carga, comandante!' WHERE `ID`=32378;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 준비 다 끝났소.', `MaleText_loc4`='我们准备好了，长官。', `MaleText_loc5`='我們準備好了，指揮官。', `MaleText_loc7`='¡Estamos preparados, comandante!' WHERE `ID`=32379;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='출발 준비 이상 없소.', `MaleText_loc4`='武装完毕，随时待命。', `MaleText_loc5`='整裝待發。', `MaleText_loc7`='Armados y preparados.' WHERE `ID`=32380;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적에게 따끔한 맛을 보여줄 준비 끝났습니다.', `MaleText_loc4`='我们准备好发动进攻了，长官。', `MaleText_loc5`='我們準備好要給敵人迎頭痛擊，長官。', `MaleText_loc7`='Estamos preparados para infligir dolor, señor.' WHERE `ID`=32381;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명령만 내리시오.', `MaleText_loc4`='请下令吧，长官。', `MaleText_loc5`='下達命令吧，長官。', `MaleText_loc7`='Da la orden, señor.' WHERE `ID`=32382;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쓸데없는 얘기는 그만하지! 네 도시를 되찾고 싶다고? 오너라, 영웅들아! 네놈들 영혼으로 주인님은 힘을 얻으시리라! 이 도시는 산산조각 난 채로 되돌려주마!', `MaleText_loc4`='真是天真！你们想夺回这座城市？那就来吧，英雄们！你们的灵魂会让我更强大！而你们只能夺回一片废墟！', `MaleText_loc5`='閒話說夠了!想奪回你的城市?來吧，英雄們!你們的靈魂將成為宿主的糧秣!而這裡，將變成一座廢墟!', `MaleText_loc7`='¡Bueno, basta de parloteo! ¿Quieren reclamar su ciudad? ¡Pues vengan, héroes! ¡Sus almas alimentarán al anfitrión! ¡Recuperarán este lugar en pedazos!' WHERE `ID`=32383;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 앞에 놓인 길은 그리 쉽지 않소. 팔이 튼튼하다고 자신한다면 우리 부대원 하나가 이미르하임으로 오를 준비가 될 때까지 좀 기다려 보시오. 부대원들은 어떤 도움이라도 환영할 테니까 말이오.', `MaleText_loc4`='形势严峻，没有捷径可走。如果你的战斗力够强，请掩护我的小队，直到他们做好爬上伊米海姆的准备。他们需要一切可利用的帮助。', `MaleText_loc5`='我們眼前的道路可不輕鬆。如果你自認夠強悍，那就四處看看直到我的其中一個小隊準備前往依米海姆。他們用得上任何幫手。', `MaleText_loc7`='El camino que tenemos ante nosotros no es sencillo. Si tienes algo de fuerza, quédate por aquí hasta que uno de mis escuadrones esté preparado para subir a Ymirheim. Les vendrá bien toda la ayuda que puedan conseguir.' WHERE `ID`=32384;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋습니다. 이 쐐기돌을 완성할 수 있을지 보죠.', `MaleText_loc4`='嗯。我们试试能不能拼好钥石。', `MaleText_loc5`='對，讓我們來瞧瞧是不是能完成這個拱心石。', `MaleText_loc7`='De acuerdo. Veamos si podemos terminar la piedra angular.' WHERE `ID`=32385;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='브란 브론즈비어드, 환영한다. 난 이 신전의 수호자가 남긴 잔재이다.', `MaleText_loc4`='你好，布莱恩·铜须。我是这座神殿的最后一名守卫者。', `MaleText_loc5`='歡迎，布萊恩·銅鬚。我是這座神殿僅存的守護者。', `MaleText_loc7`='Bienvenido, Brann Barbabronce. Soy lo que queda del guardián de este templo.' WHERE `ID`=32386;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대는 탐험가로서나 지식의 탐구자로서의 자질을 증명했다.', `MaleText_loc4`='你当之无愧是一名优秀的探险家，你的心中充满了对知识的渴求。', `MaleText_loc5`='你已經證實自己是個探險家與知識追尋者。', `MaleText_loc7`='Has demostrado ser un explorador y un buscador de conocimiento.' WHERE `ID`=32387;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또한 토석인들에게 확고한 동맹으로서의 위치를 계속 지켜주었다.', `MaleText_loc4`='土灵已经将你视为忠实的盟友。', `MaleText_loc5`='你已經成為我們土靈的堅定盟友。', `MaleText_loc7`='Has sido un aliado inquebrantable para los terráneos.' WHERE `ID`=32388;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대와 그대의 친구는 전투 기술에서나 쐐기돌을 얻고자 하는 목적에서 그 자질을 증명해 보였다.', `MaleText_loc4`='在战斗以及寻找钥石的过程中，你和你的同伴都证明了自己。', `MaleText_loc5`='你和你的同伴在戰鬥以及尋找拱心石的過程中證明了自己的價值。', `MaleText_loc7`='Tú y tu compañero habéis demostrado lo que valéis durante el combate y en la búsqueda de la piedra angular.' WHERE `ID`=32389;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대의 동기는 순수하다. 쐐기돌 조각은 합쳐지리라. 울두아르로 가서 그대의 질문에 대한 해답을 구하라, 브란 브론즈비어드.', `MaleText_loc4`='你们的动机是纯洁的。钥石的碎片将得以重新拼合。前往奥杜尔寻找你想要的答案吧，布莱恩·铜须。', `MaleText_loc5`='你們的動機純正。拱心石應該要被重組。前往奧杜亞去得到你們疑問的解答，布萊恩·銅鬚。', `MaleText_loc7`='Tus intenciones son puras. Los trozos de la piedra angular serán reunidos. Ve a Ulduar y encuentra las respuestas a tus preguntas, Brann Barbabronce.' WHERE `ID`=32390;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쐐기돌이 완성되었습니다! 우리가 해냈군요, $n!', `MaleText_loc4`='钥石拼好了！我们成功啦，$n！', `MaleText_loc5`='拱心石完成了!我們辦到了，$n!', `MaleText_loc7`='¡La piedra angular está completa! ¡Lo logramos, $n!' WHERE `ID`=32391;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='품질보증연합은 넘쳐나는 문제들로 바빠져서 노스렌드로 돛을 올려 출항할 수가 없습니다.', `MaleText_loc4`='自信号上虫灾泛滥，我们没法开往诺森德了。', `MaleText_loc5`='保險號似乎出了一點問題，我們沒辦法出發航向北裂境。', `MaleText_loc7`='Por algún motivo, La Garantía está infestada de bichos y no podemos partir hacia Rasganorte.' WHERE `ID`=32392;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='울두아르의 저장고에 어떤 비밀이 숨겨져 있을지 누가 알겠습니까? 전 이제 그 비밀을 파헤치러 출발합니다. 다시 한번 도와줘서 고맙다고 말하고 싶군요. 당신의 도움이 없었다면 쐐기돌을 찾는 일만 계속하고 있었을 겁니다.', `MaleText_loc4`='谁也不知道存放在奥杜尔的档案中隐藏了什么秘密。我要去那里揭开真相。再次感谢你的帮助，$n。没有你的帮助，我现在还在找那把钥匙呢。', `MaleText_loc5`='誰知道奧杜亞有著什麼秘密在等著我們去探索?我等不及要發現它們了。再次感謝你的幫忙，$n。要是沒有你，我可能還在到處找鑰匙呢。', `MaleText_loc7`='¿Quién sabe qué secretos esperan en los archivos de Ulduar? Voy a descubrirlos. Gracias de nuevo por tu ayuda, $n. Sin ella, aún estaría buscando esa llave.' WHERE `ID`=32393;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 연합원들은 돛을 올려 노스렌드로 항해하려고 했었지요. 그런데 여러 가지 성가신 것들이 배에 퍼졌다는 걸 알게 됐지 뭡니까.', `MaleText_loc4`='我们已经做好了扬帆诺森德的准备，突然发现船上出现了大批害虫。', `MaleText_loc5`='我們已經準備好航向北裂境了，但我們發現有些麻煩的東西跑上了船。', `MaleText_loc7`='Ya estábamos preparados para partir hacia Rasganorte, pero me di cuenta de que había un gran número de bichos a bordo de nuestro barco.' WHERE `ID`=32394;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노스렌드로 돛을 올려 항해하기 전에, 품질보증연합에 퍼진 성가신 문제를 처리해야만 합니다.', `MaleText_loc4`='在开往诺森德之前，我们必须解决自信号上的虫害问题。', `MaleText_loc5`='在我們航向北裂境之前，我們得要解決保險號上的這些麻煩問題。', `MaleText_loc7`='Antes de poder partir hacia Rasganorte, tenemos que eliminar el problema de la plaga que hay a bordo de La Garantía.' WHERE `ID`=32395;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공격!!!!', `MaleText_loc4`='进攻！！！！', `MaleText_loc5`='攻擊!!!!', `MaleText_loc7`='¡¡¡ATAQUEN!!!' WHERE `ID`=32396;
