UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엄폐물을 찾아!', `MaleText_loc4`='寻找掩体！', `MaleText_loc5`='尋找掩護!', `MaleText_loc7`='¡Buscad refugio!' WHERE `ID`=32402;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분대 모여!', `MaleText_loc4`='集合！', `MaleText_loc5`='聚集往上!', `MaleText_loc7`='¡Agrupaos!' WHERE `ID`=32403;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='브리쿨 공격이다!', `MaleText_loc4`='维库人进攻了！', `MaleText_loc5`='維酷人攻擊!', `MaleText_loc7`='¡Ataque vrykul!' WHERE `ID`=32404;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빨리 움직여! 빨리, 빨리, 서둘러!', `MaleText_loc4`='站起来，小伙子们！前进！前进！', `MaleText_loc5`='前進，小夥子!快，快，快!', `MaleText_loc7`='¡En pie, chicos! ¡Vamos, vamos, vamos!' WHERE `ID`=32405;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='복창하게! 나는 못났다. 못났어도 싸움에는 소질이 있을 거라 믿네.$B$B내 분대 하나가 곧 행군을 떠날 걸세. 그 굼뜬 엉덩이 바짝 잡아 들고 그 행군에 합류하게!', `MaleText_loc4`='哎呀，你长得真难看！不过这并不表示你不会战斗。$B$B我麾下的一支小队很快就要出发啦——加入他们的行列，一起爬上伊米海姆吧！', `MaleText_loc5`='你長得可真醜!倒不是說你不懂得戰鬥啦。$B$B我們其中一個中隊已經整裝完成，即將出發 - 你這傢伙快去給我排隊準備!', `MaleText_loc7`='Vaya, ¡tú sí que eres feo! Aunque eso no quiere decir que no sepas luchar.$B$BUno de mis escuadrones estará equipado y listo para marchar dentro de poco... ¡Mete tu sucio trasero en la fila y escala con ellos!' WHERE `ID`=32406;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적 공격이다!', `MaleText_loc4`='敌人来了！', `MaleText_loc5`='來襲!', `MaleText_loc7`='¡Vienen!' WHERE `ID`=32407;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비 끝났소, 대장.', `MaleText_loc4`='我们已经整装待发，长官。', `MaleText_loc5`='整裝完成，準備出發，指揮官!', `MaleText_loc7`='Equipados y preparados, comandante.' WHERE `ID`=32408;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분대, 이동!', `MaleText_loc4`='继续前进！', `MaleText_loc5`='動作快，老兄!', `MaleText_loc7`='¡En marcha, hombres!' WHERE `ID`=32409;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서둘러. 잠깐 숨 돌리고 바로 관문으로 진격한다!', `MaleText_loc4`='快，在我们冲到大门之前，摒住呼吸迅速前进！', `MaleText_loc5`='快吧，在我們離開艙門前深吸一口氣!', `MaleText_loc7`='¡Deprisa, recuperad el aliento antes de que presionemos en la puerta!' WHERE `ID`=32410;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빨리 움직여! 빨리, 빨리, 서둘러!', `MaleText_loc4`='站起来，小伙子们！前进！前进！', `MaleText_loc5`='動作快，老兄!快，快，快!', `MaleText_loc7`='¡En pie, hombres! ¡Vamos, vamos, vamos!' WHERE `ID`=32411;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 몸에도 전사의 피가 흐르는군! 피와 명예를, 친구여!', `MaleText_loc4`='你很有斗志！愿鲜血与荣耀与你同在，朋友！', `MaleText_loc5`='你看來經歷過一番激戰!鮮血與榮耀，朋友!', `MaleText_loc7`='¡Tienes agallas! ¡Sangre y honor, colega!' WHERE `ID`=32412;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='매복이다!', `MaleText_loc4`='有埋伏！', `MaleText_loc5`='突襲!', `MaleText_loc7`='¡Emboscada!' WHERE `ID`=32413;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='브리쿨이다!', `MaleText_loc4`='维库人！', `MaleText_loc5`='維酷人!', `MaleText_loc7`='¡Vrykuls!' WHERE `ID`=32414;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무기를 들어라!', `MaleText_loc4`='拔出武器！', `MaleText_loc5`='拿出武器!', `MaleText_loc7`='¡Sacad las armas!' WHERE `ID`=32415;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피를 볼 시간이다, 제군들!', `MaleText_loc4`='浴血奋战的时刻到了！', `MaleText_loc5`='來點鮮血的時候到啦，老兄!', `MaleText_loc7`='¡Hora de ver un poco de sangre, chicos!' WHERE `ID`=32416;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 놈도 살려 보내지 마라!', `MaleText_loc4`='不留活口！', `MaleText_loc5`='不留活口!', `MaleText_loc7`='¡No dejéis a nadie con vida!' WHERE `ID`=32417;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드를 위하여!', `MaleText_loc4`='为了部落！', `MaleText_loc5`='為了部落!', `MaleText_loc7`='¡Por la Horda!' WHERE `ID`=32418;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='인정사정 볼 것 없다!', `MaleText_loc4`='不要手软！', `MaleText_loc5`='絕不留情!', `MaleText_loc7`='¡No mostréis piedad!' WHERE `ID`=32419;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 부하들은 피를 볼 준비가 되었소, 대장.', `MaleText_loc4`='指挥官，士兵们渴望杀戮的快感。', `MaleText_loc5`='我的手下渴望鮮血，指揮官。', `MaleText_loc7`='Mis hombres están ansiosos por ver algo de sangre, comandante.' WHERE `ID`=32420;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='승리를 가져올 준비가 되었소.', `MaleText_loc4`='我们准备好为荣誉而战了，长官。', `MaleText_loc5`='我們準備爭取榮譽，長官。', `MaleText_loc7`='Estamos listos para la gloria, señor.' WHERE `ID`=32421;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공격 준비가 끝났소.', `MaleText_loc4`='我们做好了战斗的准备。', `MaleText_loc5`='我們準備好出發了。', `MaleText_loc7`='Estamos preparados para el ataque.' WHERE `ID`=32422;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='목숨 바칠 준비가 됐소. 명령만 내리시오, 대장.', `MaleText_loc4`='我们已经整装待发，准备浴血沙场了。长官，请下达命令吧。', `MaleText_loc5`='全副武裝，準備赴死。你的命令是什麼，長官?', `MaleText_loc7`='Equipados y listos para morir. ¿Qué quiere que hagamos, señor?' WHERE `ID`=32423;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지옥이 우리를 기다리고 있소. 명령만 내리시오!', `MaleText_loc4`='我们随时准备牺牲。请下令吧！', `MaleText_loc5`='地獄在等著我們。下達命令吧!', `MaleText_loc7`='El infierno nos espera. ¡Da la orden!' WHERE `ID`=32424;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='브리쿨을 짓밟아버릴 준비 끝났소. 명령만 내리시오.', `MaleText_loc4`='我们准备好与维库人展开激战了。请下令吧，长官。', `MaleText_loc5`='準備好去把維酷給殺得遍甲不留，下達命令吧，長官。', `MaleText_loc7`='Listos para masacrar a los vrykuls, solo danos la orden, señor.' WHERE `ID`=32425;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명령만 내리시오, 대장.', `MaleText_loc4`='请下令，指挥官。', `MaleText_loc5`='等候你的命令，指揮官。', `MaleText_loc7`='Cuando ordenes, comandante.' WHERE `ID`=32426;
