UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드 주둔지로 인도해 주십시오.', `MaleText_loc4`='请指引我返回部落营地。', `MaleText_loc5`='帶我回到部落登陸營地。', `MaleText_loc7`='Guíame de vuelta al Campo de Aterrizaje de la Horda.', `FemaleText_loc1`='호드 주둔지로 인도해 주십시오.', `FemaleText_loc4`='请指引我返回部落营地。', `FemaleText_loc5`='帶我回到部落登陸營地。', `FemaleText_loc7`='Guíame de vuelta al Campo de Aterrizaje de la Horda.' WHERE `ID`=32436;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으아아아아아아아아아악!!!', `MaleText_loc4`='呀啊啊啊啊！！！！！', `MaleText_loc5`='吼啊啊啊啊啊啊啊!!!!', `MaleText_loc7`='¡YAAAAAAAARGGGGHHHHH!' WHERE `ID`=32437;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 우리의 행동 하나하나에 전우들의 생명이 달렸습니다. 무슨 용건인지 빨리 말씀하십시오, $c|1이여;여;.', `MaleText_loc4`='我们在这里的行动关系到许多人的性命。你想说什么就快说吧，$c。', `MaleText_loc5`='許多生命仰賴我們的行動。有話快說吧，$c。', `MaleText_loc7`='Hay vidas que dependen de las decisiones que tomemos aquí. Deprisa, $c, di lo que tengas que decir.' WHERE `ID`=32438;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투 소식을 가져온 겁니까, $r?', `MaleText_loc4`='你带来了最新的战况情报吗，$r？', `MaleText_loc5`='你帶來了戰爭的新消息，$r?', `MaleText_loc7`='¿Traes noticias de la batalla, $r?' WHERE `ID`=32439;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전쟁에서 제일 좋은 건 속전속결입니다. 대화도 짧은 게 좋겠죠. 무슨 일이십니까, $r|1이여;여;?', `MaleText_loc4`='最好的战术是速战速决。谈话也是一样。你想说什么，$r？', `MaleText_loc5`='最好的戰爭就是一場快速的戰爭。而對話也是一樣。你覺得呢，$r?', `MaleText_loc7`='Una guerra, cuanto más corta, mejor. Igual que una conversación.' WHERE `ID`=32440;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 차원문은 머나먼 타나리스 땅 아래 깊숙이 있는 시간의 동굴로 이어지지요.$B$B바라신다면, 제가 그곳으로 보내드릴 수 있어요.', `FemaleText_loc4`='该传送门通往时光之穴，它位于遥远的塔纳利斯沙漠地底。$B$B如果你要去那里的话，我可以将你传送过去。', `FemaleText_loc5`='這個傳送門通往時光之穴，在遙遠的塔納利斯地底深處。$B$B如果你想要的話，我可以送你去那邊。', `FemaleText_loc7`='Este portal lleva a las Cavernas del Tiempo, en las profundidades de la tierra bajo el lejano Tanaris.$B$BYo poseo el poder necesario para enviarte allí si eso es lo que deseas.' WHERE `ID`=32441;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 차원문은 머나먼 타나리스 땅 아래 깊숙이 있는 시간의 동굴로 이어지지요.$B$B힘을 충분히 키우기 전에는 그곳으로 갈 생각도 하지 말라고 말씀 드려야겠네요.', `FemaleText_loc4`='该传送门通往时光之穴，它位于遥远的塔纳利斯沙漠地底。$B$B但是你的力量还不够强大，我建议你不要去那里。', `FemaleText_loc5`='這個傳送門通往時光之穴，在遙遠的塔納利斯地底深處。$B$B但在你變得更強之前，我必須請你別前去該地。', `FemaleText_loc7`='Este portal lleva a las Cavernas del Tiempo, en las profundidades de la tierra bajo el lejano Tanaris.$B$BPero tengo que pedirte que no viajes allí hasta que seas más fuerte.' WHERE `ID`=32442;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='폭탄이랑 로켓 화약 냄새가 여기까지 나요! 출격해서 재미 좀 보시려고요?', `FemaleText_loc4`='我能闻到炸弹和火箭里的火药味儿！你也要出去找些乐子吗？', `FemaleText_loc5`='我可以從那些炸彈和火箭上聞到火藥味!你想去外頭找點樂子嗎?', `FemaleText_loc7`='¡Puedo oler la pólvora de todas las bombas y cohetes! ¿Quieres salir y unirte a la fiesta?' WHERE `ID`=32443;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 목소리가 내게 말을 걸어와.', `MaleText_loc4`='有很多声音在对我讲话。', `MaleText_loc5`='那個聲音在跟我說話。', `MaleText_loc7`='Las voces me están hablando a mí.' WHERE `ID`=32444;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 복종해야 해.', `MaleText_loc4`='我必须服从。', `MaleText_loc5`='我一定要遵從。', `MaleText_loc7`='Debo obedecer.' WHERE `ID`=32445;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신도 사로잡히기 전에 여기서 도망치라고!', `MaleText_loc4`='你最好赶紧离开，不然你也会被它影响！', `MaleText_loc5`='你一定要離開這裡，免得他也影響你!', `MaleText_loc7`='¡Tienes que salir de aquí antes de que llegue hasta ti también!' WHERE `ID`=32446;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위습망토 만드는 법에 대해서 얘기해 주십시오.', `MaleText_loc4`='跟我说说精魂披风图样的事儿吧。', `MaleText_loc5`='告訴我關於幽光披風圖樣的事情。', `MaleText_loc7`='Háblame sobre el patrón de la capa de fuego fatuo.', `FemaleText_loc1`='위습망토 만드는 법에 대해서 얘기해 주세요.', `FemaleText_loc4`='跟我说说精魂披风图样的事儿吧。', `FemaleText_loc5`='告訴我關於幽光披風圖樣的事情。', `FemaleText_loc7`='Háblame sobre el patrón de la capa de fuego fatuo.' WHERE `ID`=32447;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='출발 준비가 거의 끝났소. 마무리 지을 시간을 조금만 더 주시오.', `MaleText_loc4`='我们就快准备好啦。再给我们一点时间，很快就能出发了。', `MaleText_loc5`='我們差不多要走了。再給我們一點時間完成準備。', `MaleText_loc7`='Ya casi estamos preparados para partir. Solo déjanos un poco más de tiempo para acabar nuestros preparativos.' WHERE `ID`=32448;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 준비가 안 끝났소. 시간이 좀 더 필요하오.', `MaleText_loc4`='准备工作尚未完成。我们暂时还不会离开。', `MaleText_loc5`='我還在準備中。還需要一陣子才能出發。', `MaleText_loc7`='Aún estamos con los preparativos. No estaremos listos para partir hasta dentro de un rato.' WHERE `ID`=32449;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그게 우리 주위를 맴돌아. 아니 내 머릿속에 있어!', `MaleText_loc4`='它就在我们身边。就在我的脑海里！', `MaleText_loc5`='它無所不再。它在腦袋裡!', `MaleText_loc7`='¡Está por todas partes! ¡Está en mi cabeza!' WHERE `ID`=32450;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부하들이 준비를 마쳤소. 오늘 브리쿨 놈들 피 좀 봅시다!', `MaleText_loc4`='士兵们都准备好了。我们要让那些维库人流血！', `MaleText_loc5`='我的手下已經準備好了。去嘗點維酷人的鮮血吧!', `MaleText_loc7`='Mis hombres están preparados. ¡Derramemos sangre de vrykul!' WHERE `ID`=32451;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사로나이트... 이 안엔 무언가 있어!', `MaleText_loc4`='萨隆邪铁……里面藏有什么东西！', `MaleText_loc5`='薩鋼...有某種東西在裡頭!', `MaleText_loc7`='La saronita... ¡hay algo en ella!' WHERE `ID`=32452;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기엔 무언가 있어. 이 흙과 돌 안에 말이야!', `MaleText_loc4`='邪铁里藏有东西！就在岩石和泥土里！', `MaleText_loc5`='那裡有某種東西。就在岩石和土地裡頭!', `MaleText_loc7`='Aquí hay algo. ¡Está en las rocas y en la tierra!' WHERE `ID`=32453;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 여러 곳을 여행하면서 위습망토 만드는 법을 익힐 수 있었습니다.$B$B이 망토는 체력과 주문력, 지능과 마나 회복률을 높이는 주문 시전자용 영웅급 망토로서 제작할 수 있습니다. 이 도안을 가르쳐 주어도 좋을 만한 이를 찾고 있었지요.$B$B노스렌드에 있는 모든 일반 던전을 섭렵하고 "노스렌드 던전 전문가" 업적을 달성한 사람이라면 위습망토 만드는 법을 배울 자격이 있다고 생각합니다.', `MaleText_loc4`='我在旅途中学会了精魂披风的图样。$B$B图样可交易，是史诗级的施法者披风，装备后可获得耐力、法术强度、智力以及法力回复速度的加成。我一直在寻找有资格学习这张图样的人。$B$B打通诺森德所有的普通难度地下城，并获得“诺森德地下城大师”成就的人才有资格学习精魂披风的图纸。', `MaleText_loc5`='在我的旅途中，我學會了幽光披風的圖樣。$B$B這是一件可交易的史詩級施法系披風，提供耐力、法術能量、智力與法力回復。我在尋找一個值得傳授圖樣的人。$B$B完成北裂境所有一般地城和達成「北裂境地城大師」成就，就有資格學會幽光披風的圖樣。', `MaleText_loc7`='En mis viajes he aprendido el patrón de la capa de fuego fatuo.$B$BEsta capa es una capa épica de lanzamiento de hechizos con la que se puede comerciar que otorga aguante, intelecto y regeneración de maná. Estoy buscando a alguien digno a quien enseñar este patrón.$B$BAlguien que hubiera completado todas las mazmorras normales de Rasganorte y tuviera el logro "Maestro de mazmorra de Rasganorte" sería digno de aprender el patrón de la capa de fuego fatuo.' WHERE `ID`=32454;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위습망토 만드는 법을 배울 준비가 되었습니다.', `MaleText_loc4`='我准备好学习精魂披风了。', `MaleText_loc5`='我準備好學習幽光披風圖樣。', `MaleText_loc7`='Estoy preparado para aprender el patrón de la capa de fuego fatuo.', `FemaleText_loc1`='위습망토 만드는 법을 배울 준비가 되었어요.', `FemaleText_loc4`='我准备好学习精魂披风了。', `FemaleText_loc5`='我準備好學習幽光披風圖樣。', `FemaleText_loc7`='Estoy preparada para aprender el patrón de la capa de fuego fatuo.' WHERE `ID`=32455;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 여길 빠져나가야 해! 나 좀 빠져나가게 도와주겠소?', `MaleText_loc4`='我要离开这里！你能放我出去吗？', `MaleText_loc5`='我要離開這裡!你能救我出去嗎?', `MaleText_loc7`='¡Tengo que salir de aquí! ¿Puedes liberarme?' WHERE `ID`=32456;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='머릿속에 누군가 이야기하는 게 안 들려?', `MaleText_loc4`='你听见了吗？它正在你的脑海中低语。', `MaleText_loc5`='你聽見它在你心中說話嗎?', `MaleText_loc7`='¿Puedes oírla en tu mente?' WHERE `ID`=32457;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 이제 자유입니다. 여기에서 나가십시오!', `MaleText_loc4`='走吧，你自由了。快离开这儿！', `MaleText_loc5`='去吧，你自由了。離開這裡!', `MaleText_loc7`='Venga, eres libre. ¡Sal de aquí!', `FemaleText_loc1`='자, 이제 자유입니다. 여기에서 나가십시오!', `FemaleText_loc4`='走吧，你自由了。快离开这儿！', `FemaleText_loc5`='去吧，你自由了。離開這裡!', `FemaleText_loc7`='Venga, eres libre. ¡Sal de aquí!' WHERE `ID`=32458;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이미르하임으로 향하는 분대에 합류할 준비 끝났습니다. 어서 출발합시다.', `MaleText_loc4`='我准备好加入前往伊米海姆的队列了。我们出发吧。', `MaleText_loc5`='我準備好加入你的小隊前往依米海姆。出發吧。', `MaleText_loc7`='Estoy preparado para unirme a tu escuadrón en la ruta hacia Ymirheim. Pongámonos en marcha.', `FemaleText_loc1`='이미르하임으로 향하는 분대에 합류할 준비 끝났습니다. 어서 출발합시다.', `FemaleText_loc4`='我准备好加入前往伊米海姆的队列了。我们出发吧。', `FemaleText_loc5`='我準備好加入你的小隊前往依米海姆。出發吧。', `FemaleText_loc7`='Estoy preparada para unirme a tu escuadrón en la ruta hacia Ymirheim. Pongámonos en marcha.' WHERE `ID`=32459;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안마당을 장악했다! 내부 성소로 진군하라!', `MaleText_loc4`='我们已经攻占了庭院！朝内部圣殿前进！', `MaleText_loc5`='中庭是我們的了!前進聖所!', `MaleText_loc7`='¡El claustro es nuestro! ¡Avancen al sagrario interior!' WHERE `ID`=32460;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멈춰라! 저들이 승강기를 파괴했다!', `MaleText_loc4`='停下，他们摧毁了升降梯！', `MaleText_loc5`='停!他們破壞了升降梯!', `MaleText_loc7`='¡ALTO! ¡Han destruido el elevador!' WHERE `ID`=32461;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대족장, 그 아래는 함정이오. 떨어지면 뼈도 못 추릴 거요.', `FemaleText_loc4`='升降梯有问题，酋长。摔下去的人都难逃一死。', `FemaleText_loc5`='升降梯井被設下了陷阱，大酋長。掉下去肯定是死路一條。', `FemaleText_loc7`='El eje está atrapado, Jefe de guerra. Caerse sería una muerte segura.' WHERE `ID`=32462;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 어두운 곳곳을 탐험하면서 죽음의 한기 망토 만드는 법을 익혔습니다.$B$B이 망토는 주문력과 주문 가속력, 그리고 치명타율을 높이는 주문 시전자용 영웅급 망토로서 제작할 수 있습니다. 이 도안을 가르쳐 주어도 좋을 만한 사람을 찾고 있었지요.$B$B노스렌드에 있는 퀘스트 대부분을 섭렵하여 "노스렌드의 현자" 업적을 달성한 사람이라면 죽음의 한기 망토 만드는 법을 배울 자격이 있습니다.', `MaleText_loc4`='我曾去过许多黑暗的地方，学会了死寒披风的图样。$B$B图样可交易，是史诗级的施法者披风，装备后可获得法术强度、急速以及爆击的加成。我一直在寻找有资格学习这张图样的人。$B$B完成诺森德的大部分任务，并获得“诺森德的博学者”成就的人才有资格学习死寒披风的图纸。', `MaleText_loc5`='我曾冒險進入黑暗之地，學會了亡寒披風的裁縫圖樣。$B$B這件可交易的史詩級施法系披風提供法術能力、加速和致命一擊。我在尋找值得傳授這圖樣的人。$B$B完成北裂境的大多數任務並達成「北裂境博學大師」的成就，就有資格學習亡寒披風的圖樣。', `MaleText_loc7`='Me he aventurado en oscuros lugares y he aprendido el patrón de la capa Fríomortal.$B$BEsta capa es una capa épica para taumaturgos con la que se puede comerciar que otorga poder de hechizos, celeridad y golpe crítico. Estoy buscando a alguien digno a quien enseñar este patrón.$B$BAlguien que haya completado la mayoría de las misiones de Rasganorte y que tenga el logro "Maestro cultural de Rasganorte" sería digno de aprender el patrón de la capa Fríomortal.' WHERE `ID`=32463;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음의 한기 망토 만드는 법에 대해서 얘기해 주십시오.', `MaleText_loc4`='跟我说说死寒披风图样的事儿吧。', `MaleText_loc5`='告訴我關於亡寒披風圖樣的事情。', `MaleText_loc7`='Háblame sobre el patrón de la capa Fríomortal.', `FemaleText_loc1`='죽음의 한기 망토 만드는 법에 대해서 얘기해 주세요.', `FemaleText_loc4`='跟我说说死寒披风图样的事儿吧。', `FemaleText_loc5`='告訴我關於亡寒披風圖樣的事情。', `FemaleText_loc7`='Háblame sobre el patrón de la capa Fríomortal.' WHERE `ID`=32464;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발견! $n|1이;가; 새로운 주문각인 기술을 발견했습니다!', `MaleText_loc4`='重大发现！$n发现了一种新的配方！', `MaleText_loc5`='大發現!$n發現了新的配方!', `MaleText_loc7`='¡DESCUBRIMIENTO! ¡$n ha descubierto una nueva receta!', `FemaleText_loc1`='발견! $n|1이;가; 새로운 주문각인 기술을 발견했습니다!', `FemaleText_loc4`='重大发现！$n发现了一种新的配方！', `FemaleText_loc5`='大發現!$n發現了新的配方!', `FemaleText_loc7`='¡DESCUBRIMIENTO! ¡$n ha descubierto una nueva receta!' WHERE `ID`=32465;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 가고 있습니다, 주인님!', `MaleText_loc4`='我来了，主人！', `MaleText_loc5`='我來了，主人!', `MaleText_loc7`='¡Ya vengo, maestro!' WHERE `ID`=32466;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 생명은 당신의 것입니다!', `MaleText_loc4`='我的生命属于你！', `MaleText_loc5`='我的生命獻給你!', `MaleText_loc7`='¡Mi vida por ti!' WHERE `ID`=32467;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음의 한기 망토 만드는 법을 배울 준비가 되었습니다.', `MaleText_loc4`='我准备好学习死寒披风了。', `MaleText_loc5`='我準備好學習亡寒披風圖樣。', `MaleText_loc7`='Estoy preparado para aprender el patrón de la capa Fríomortal.', `FemaleText_loc1`='죽음의 한기 망토 만드는 법을 배울 준비가 되었어요.', `FemaleText_loc4`='我准备好学习死寒披风了。', `FemaleText_loc5`='我準備好學習亡寒披風圖樣。', `FemaleText_loc7`='Estoy preparada para aprender el patrón de la capa Fríomortal.' WHERE `ID`=32468;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 떠나지 않을 거야!', `MaleText_loc4`='我是不会离开的！', `MaleText_loc5`='我不走!', `MaleText_loc7`='¡No me iré!' WHERE `ID`=32469;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니! 그렇지 않아! 내 머릿속의 목소리는 아름답다고!', `MaleText_loc4`='不！你错了！我脑海中的声音非常美妙！', `MaleText_loc5`='不!你錯了!我腦袋中的聲音最美好了!', `MaleText_loc7`='¡NO! ¡Te equivocas! ¡Las voces que hay en mi cabeza son bonitas!' WHERE `ID`=32470;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 떠나기 싫어! 여기 있을 거야!', `MaleText_loc4`='我不想走！我要留在这里！', `MaleText_loc5`='我不想走!我要留在這裡!', `MaleText_loc7`='¡No quiero irme! ¡Quiero quedarme aquí!' WHERE `ID`=32471;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 돌아가지 않을 거야. 내 존재 이유가 바로 저 아래에서 날 기다린다고!', `MaleText_loc4`='我不要回去。我要去地底找寻我存在的意义！', `MaleText_loc5`='我永遠也不回去。我一切存在的意義都在下頭等著!', `MaleText_loc7`='Jamás regresaré. ¡El motivo de mi existencia me espera abajo!' WHERE `ID`=32472;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아하하하하... 당신도 곧 우리 일원이 될 거야!', `MaleText_loc4`='啊哈哈哈哈……你很快就会加入我们的！', `MaleText_loc5`='啊啊啊啊...你很快也會加入我們!', `MaleText_loc7`='JAJAJAAJAAAA... ¡Pronto te unirás a nosotros!' WHERE `ID`=32473;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 그분이 있는 지하로 더 내려가야 해. 난 뛰어내릴 거야!', `MaleText_loc4`='我要到地底深处去，到主人身边去。我一定要跳下去！', `MaleText_loc5`='我一定要去，他就在那裡，更深的地方。我一定要跳下去!', `MaleText_loc7`='Debo llegar más abajo, hasta donde está él. ¡Debo saltar!' WHERE `ID`=32474;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신도 웬만한 기술을 지닌 재봉사이므로, 제가 아는 특별한 재봉 도안 몇 가지를 알려 드릴 수 있습니다. 저는 위습망토와 죽음의 한기 망토 만드는 법 둘 다를 압니다.', `MaleText_loc4`='你是一位颇为出色的裁缝，因此我可以教你一些特别的图样，比如精魂披风和死寒披风。', `MaleText_loc5`='既然你是個有點才能的裁縫，我可以告訴你我知道一些獨特的圖樣。我知道幽光披風與亡寒披風的圖樣。', `MaleText_loc7`='Ya que eres un sastre de cierta habilidad, puedo decirte que conozco algunos patrones especiales. Conozco los patrones de las capas de fuego fatuo y Fríomortal.' WHERE `ID`=32475;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바리마트라스가 상처 감염 독을 풀어놓습니다!', `MaleText_loc4`='瓦里玛萨斯召唤出了凋零畸体！', `MaleText_loc5`='瓦里瑪薩斯釋放了荒疫畸形者!', `MaleText_loc7`='Aberración de añublo' WHERE `ID`=32476;
