UPDATE `locales_broadcast_text` SET `MaleText_loc1`='중화제가 효력을 잃고 있습니다!$b늦기 전에 더 집어넣어야 합니다!', `MaleText_loc4`='中和剂失效了！$b赶紧倒入液体！', `MaleText_loc5`='中和劑失效!$b快點加水進去!', `MaleText_loc7`='¡El agente neutralizador está fallando!$b¡Hay que añadir el fluido pronto!' WHERE `ID`=32484;
