UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아름다운 내 도시에 무슨 짓을 한 거지!', `FemaleText_loc4`='他们对我美丽的城市都做了些什么？', `FemaleText_loc5`='他們對我那美麗的城市做了什麼好事!', `FemaleText_loc7`='¡¿Qué le han hecho a mi hermosa ciudad?!' WHERE `ID`=32489;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위대한 바람의 정령이여, 내 부름에 다시 한번 응하라!', `MaleText_loc4`='伟大的空气之灵，请再次倾听我的呼唤！', `MaleText_loc5`='偉大的風之靈，再次聆聽我的呼喚吧!', `MaleText_loc7`='¡Gran espíritu del aire, vuelve a oír mi llamada!' WHERE `ID`=32490;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바람의 정령들이 내 부름에 응했다. 회오리바람이 우리를 무사히 내려다 주리라. 이제 뛰어라!', `MaleText_loc4`='空气之灵已经听到了我的呼唤。飓风会送我们返回地面。现在，跳吧！', `MaleText_loc5`='風之靈已經聽到我的呼喚。颶風會讓我們降落在安全的地方。現在，跳!', `MaleText_loc7`='Los espíritus del aire oyeron mi llamada. Los ciclones nos bajarán a un lugar seguro. ¡Saltemos!' WHERE `ID`=32491;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방어 체제 가동', `MaleText_loc4`='激活防御设施', `MaleText_loc5`='防禦措施啟動中', `MaleText_loc7`='Activando defensas', `FemaleText_loc1`='방어 체제 가동', `FemaleText_loc4`='激活防御设施', `FemaleText_loc5`='防禦措施啟動中', `FemaleText_loc7`='Activando defensas' WHERE `ID`=32492;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 자네, 이리 오게! 먹고, 마시고, 다음 전투를 위해 좀 쉬게나.$B$B하지만, 싸움은 금물일세! 그랬다가는 우리 늑대 먹이로 던져버릴 테니까 말이야.', `MaleText_loc4`='你！快过来！尽情吃喝一顿吧，为下一次的战斗做好准备。$B$B不许在这里打架！不然我就送你去喂狼。', `MaleText_loc5`='你!過來!吃吧，喝吧，為了下一場戰役好好休息。$B$B不過別在店裡鬧事!否則我就拿你餵我的狼。', `MaleText_loc7`='¡Tú! ¡VEN! Bebe, aliméntate y descansa para la próxima batalla.$B$B¡Pero no luches! O te echaré como alimento para mis lobos.', `FemaleText_loc1`='거기 자네, 이리 오게! 먹고, 마시고, 다음 전투를 위해 좀 쉬게나.$B$B하지만, 싸움은 금물일세! 그랬다가는 우리 늑대 먹이로 던져버릴 테니까 말이야.', `FemaleText_loc4`='你！快过来！尽情吃喝一顿吧，为下一次的战斗做好准备。$B$B不许在这里打架！不然我就送你去喂狼。', `FemaleText_loc5`='你!過來!吃吧，喝吧，為了下一場戰役好好休息。$B$B不過別在店裡鬧事!否則我就拿你餵我的狼。', `FemaleText_loc7`='¡Tú! ¡VEN! Bebe, aliméntate y descansa para la próxima batalla.$B$B¡Pero no luches! O te echaré como alimento para mis lobos.' WHERE `ID`=32493;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내부 성소 방어선을 돌파했다! 계속 나아가라!', `MaleText_loc4`='我们攻占了内部圣殿，勇士们！继续前进！', `MaleText_loc5`='我們突破了聖所，英雄們!我們要向前推進!', `MaleText_loc7`='¡Hemos penetrado el sagrario interior, héroes! ¡Sigamos presionando!' WHERE `ID`=32494;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 반란을 주동한 배반자들에게는 고통스러운 죽음만이 구원일 것이오. 내 복수엔 자비도 주저함도 없소.', `FemaleText_loc4`='参与暴乱的叛徒们唯一的救赎就是痛苦的死去。我的复仇将迅速而决不留情。', `FemaleText_loc5`='那些叛徒唯一的贖罪方式就是極度痛苦的死亡。我的復仇快速而絕不留情。', `FemaleText_loc7`='La única redención para los traidores responsables de esto será una muerte agonizante. Mi venganza será pronta y sin misericordia.' WHERE `ID`=32495;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앞장서시오, 어둠의 여왕이여. 뒤를 따르겠소.', `MaleText_loc4`='带路吧，黑暗女王。我们会跟着你的。', `MaleText_loc5`='帶路吧，黑暗女王。我們會跟著你前進。', `MaleText_loc7`='Guíanos, Dama Oscura. Te seguiremos.' WHERE `ID`=32496;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋소, 대족장이여. 이리로 가면 왕실이오. 경계를 늦추지 마시오. 바리마트라스와 퓨트리스가 무엇을 꾸미는지 모르니 말이오.', `FemaleText_loc4`='很好，酋长。皇家区在这边。保持警惕，谁也不知道瓦里玛萨斯和普特雷斯会有什么圈套。', `FemaleText_loc5`='很好，大酋長。皇家區往這裡走。小心戒備。誰也不知道瓦里瑪薩斯和普崔司準備了什麼好戲。', `FemaleText_loc7`='Muy bien, Jefe de Guerra. El Barrio Real está en esta dirección. Mantengan la guardia. No hay forma de saber lo que Varimathras y Putress tienen para nosotros.' WHERE `ID`=32497;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='반역의 대가는 죽음뿐이다!', `FemaleText_loc4`='背叛的下场就是死亡！', `FemaleText_loc5`='背叛的唯一懲罰就是死!', `FemaleText_loc7`='¡El castigo por traición es la muerte!' WHERE `ID`=32498;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='감히 내 성소를 더럽혀 놓다니! 네 피로 갚아라!', `FemaleText_loc4`='你竟敢玷污我的圣殿！用鲜血偿还吧！', `FemaleText_loc5`='你膽敢玷污我的聖所!用鮮血來贖罪吧!', `FemaleText_loc7`='¡¿Te atreves a contaminar mi santuario?! ¡Pagarás con tu sangre!' WHERE `ID`=32499;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='호드가 승리할 것이다!', `FemaleText_loc4`='部落必将赢得胜利！', `FemaleText_loc5`='部落終將獲勝!', `FemaleText_loc7`='¡La victoria será de la Horda!' WHERE `ID`=32500;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네 주인과 곧 다시 만날 거다... 죽은 뒤에 말이지.', `FemaleText_loc4`='你很快就会和你的主子碰面了——在死了以后。', `FemaleText_loc5`='你很快就會和你的主人重聚 - 在冥界重逢。', `FemaleText_loc7`='Pronto te reunirás con tu amo... en la otra vida.' WHERE `ID`=32501;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='역겹구나.', `FemaleText_loc4`='恶心的家伙。', `FemaleText_loc5`='你真叫人噁心。', `FemaleText_loc7`='Me das asco.' WHERE `ID`=32502;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 밴시 여왕이 준비한 계획이 있다!', `FemaleText_loc4`='女妖之王对你早有安排！', `FemaleText_loc5`='女妖之王對你另有計畫!', `FemaleText_loc7`='¡La Reina alma en pena tiene planes para ti!' WHERE `ID`=32503;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='비참한 목숨을 구걸해보아라!', `FemaleText_loc4`='为你可悲的性命乞求吧！', `FemaleText_loc5`='為你可悲的生命求饒吧!', `FemaleText_loc7`='¡Ruega por tu miserable vida!' WHERE `ID`=32504;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무릎을 꿇어라!', `FemaleText_loc4`='给我跪下！', `FemaleText_loc5`='給我跪下!', `FemaleText_loc7`='¡DE RODILLAS!' WHERE `ID`=32505;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제발, 그만하세요.', `MaleText_loc4`='求求你，住手。', `MaleText_loc5`='喔不，別再打了。', `MaleText_loc7`='Por favor, basta.' WHERE `ID`=32506;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 번만 더 때려 봐. 나도 더는 못 참아!', `MaleText_loc4`='再打我一下试试，你会后悔的！', `MaleText_loc5`='再打我一次，你一定會後悔!', `MaleText_loc7`='¡Vuelve a golpearme y lo lamentarás!' WHERE `ID`=32507;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아오!', `MaleText_loc4`='哎哟！', `MaleText_loc5`='噢!', `MaleText_loc7`='¡Ay!' WHERE `ID`=32508;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘못했습니다. 더 열심히 일하겠습니다.', `MaleText_loc4`='对不起。我会努力干活的。', `MaleText_loc5`='我很抱歉。我會更努力工作的。', `MaleText_loc7`='Lo siento. Me esforzaré más.' WHERE `ID`=32509;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님께서 나를 다시 받아주실 거야!', `MaleText_loc4`='主人很快就会召我回去的！', `MaleText_loc5`='很快主人就會讓我悔改!', `MaleText_loc7`='¡El maestro pronto me reclamará!' WHERE `ID`=32510;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가죽을 벗겨 버리겠어!', `FemaleText_loc4`='我要把你的肉一片片地割下来！', `FemaleText_loc5`='我要把你給扒皮拆骨!', `FemaleText_loc7`='¡Arrancaré la carne de tus huesos!' WHERE `ID`=32511;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너희 버러지들 이야기도 이제 질렸다. 일이나 해!', `FemaleText_loc4`='我受够你们的胡言乱语了。快干活！', `FemaleText_loc5`='你們這些蛆的廢話實在太多了，快點工作!', `FemaleText_loc7`='Se acabo su estúpida charlatanería, gusanos. ¡Trabajen más!' WHERE `ID`=32512;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='머릿속에 속삭이는 소리가 들린다고? 다 네놈들이 만들어낸 소리야. 가서 일이나 해!', `FemaleText_loc4`='根本没有什么低语声。都是你自己想象出来的。回去干活！', `FemaleText_loc5`='沒有人對你腦袋講話。你在幻想。回去工作!', `FemaleText_loc7`='No hay susurros en tu cabeza. Te los estás imaginando. ¡Vuelve al trabajo!' WHERE `ID`=32513;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='리치 왕께서 더 많은 사로나이트를 원하신다. 열심히 일해! 어리바리 농땡이 부렸다가는 괴물 밥이 될 줄 알아!', `FemaleText_loc4`='巫妖王需要更多的萨隆邪铁。快点干活，蠢货。不然就送你们去喂怪物！', `FemaleText_loc5`='巫妖王要更多的薩鋼。蠢蛋快點工作，否則我就拿你去餵那個東西!', `FemaleText_loc7`='El Rey Exánime exige más saronita. ¡Trabajad más duro, insensatos, o seréis alimento para la criatura!' WHERE `ID`=32514;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='배식을 반으로 줄인다고 하면 일하는 속도가 좀 빨라지려나?', `FemaleText_loc4`='把你们的口粮减半或许能刺激你们挖得快点儿？', `FemaleText_loc5`='也許把你的口糧減半你就會讓你的動作快一點?', `FemaleText_loc7`='¡Quizá reducir tu rancho a la mitad sea un incentivo para conseguir que piques más deprisa!' WHERE `ID`=32515;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='작업반장, 이번에 농땡이 부리는 노예는 괴물 밥으로 넘겨!', `MaleText_loc4`='瓦格里工头，如果再有奴隶偷懒，就送他去喂怪物！', `MaleText_loc5`='女監工，要是再有奴隸不肯挖礦，就拿他去餵那個東西!', `MaleText_loc7`='¡Opresoras, el próximo esclavo que deje de picar será comida para la criatura!' WHERE `ID`=32516;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='광산에 침입자가 있다! 당장 처리해!', `MaleText_loc4`='矿井里出现了入侵者！解决他们！', `MaleText_loc5`='有人入侵礦坑!對付他們!', `MaleText_loc7`='¡Intrusos en las minas! ¡Encargaos de ellos!' WHERE `ID`=32517;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어이, 거기 조그만 놈. 딱 걸렸어. 이리 와서 현장감독님이랑 얘기 좀 할까.', `MaleText_loc4`='我看见你了，小家伙。到这儿来，我要和你谈谈。', `MaleText_loc5`='我看見你了，小東西。到這兒來，我有話對你說。', `MaleText_loc7`='Te veo, pequeña criatura. Ven aquí, quiero hablar contigo.' WHERE `ID`=32518;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='괴물 말 따윈 듣지 마, 다 거짓말이야. 네 자리로 돌아가!', `MaleText_loc4`='别相信这怪物的谎言。快回去干活！', `MaleText_loc5`='別聽那個東西的謊言。回去工作!', `MaleText_loc7`='No escuches las mentiras de la criatura. ¡Vuelve al trabajo!' WHERE `ID`=32519;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='멈추시오! 어둠의 마법이 느껴지오. 악마의 마법이군... 준비를 하시오!', `FemaleText_loc4`='停！我感觉到了黑暗的魔法。是恶魔的法术……准备战斗！', `FemaleText_loc5`='停!我感應到黑暗魔法。惡魔法術...做好準備!', `FemaleText_loc7`='¡ALTO! Siento magia negra. Magia demoníaca... ¡Prepárense!' WHERE `ID`=32520;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영리하구나...', `MaleText_loc4`='你真聪明……', `MaleText_loc5`='聰明的女孩...', `MaleText_loc7`='Chica lista...' WHERE `ID`=32521;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 여기에서 낙하하겠습니다!', `MaleText_loc4`='我在这里下吧！', `MaleText_loc5`='這是我的終點!', `MaleText_loc7`='¡Esta es mi parada!' WHERE `ID`=32522;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='키린 토의 고향에 온 것을 환영하오.', `MaleText_loc4`='欢迎来到肯瑞托议会的故乡。', `MaleText_loc5`='歡迎來到祈倫托。', `MaleText_loc7`='Te doy la bienvenida al hogar del Kirin Tor.' WHERE `ID`=32523;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 형제들은 잔뜩 굶주렸다. 네놈들 영혼으로 배를 채우리라.', `MaleText_loc4`='我的兄弟们都饿了。你们的灵魂一定很合他们的胃口。', `MaleText_loc5`='我的兄弟們忍飢已久。他們將飽食你們的靈魂。', `MaleText_loc7`='Mis hermanos tienen hambre. Sus almas satisfarán su apetito.' WHERE `ID`=32524;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비전 마법의 갈래 - 통달 책을 잃어버렸습니다. 다시 한 권 주실 수 있으십니까?', `MaleText_loc4`='我把《奥术魔法的学派 - 精通》弄丢了。你能再给我一本吗？', `MaleText_loc5`='我弄丟了秘法系別 - 奧義書卷。你可以再給我一個嗎?', `MaleText_loc7`='He perdido mi volumen de Las Escuelas de la Magia Arcana: Maestría. ¿Puedes proporcionarme otro?', `FemaleText_loc1`='비전 마법의 갈래 - 통달 책을 잃어버렸습니다. 다시 한 권 주실 수 있으세요?', `FemaleText_loc4`='我把《奥术魔法的学派 - 精通》弄丢了。你能再给我一本吗？', `FemaleText_loc5`='我弄丟了秘法系別 - 奧義書卷。你可以再給我一個嗎?', `FemaleText_loc7`='He perdido mi volumen de Las Escuelas de la Magia Arcana: Maestría. ¿Puedes proporcionarme otro?' WHERE `ID`=32525;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강하! 전우들이여, 행운이 함께하길!', `MaleText_loc4`='我下去啦。祝你们好运！', `MaleText_loc5`='掉落中。祝好運，男孩們!', `MaleText_loc7`='Yo abandono. ¡Suerte, chicos!' WHERE `ID`=32526;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엄호 감사합니다!', `MaleText_loc4`='谢谢你掩护我们！', `MaleText_loc5`='感謝你的掩護!', `MaleText_loc7`='¡Gracias por cubrirme!' WHERE `ID`=32527;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='낙하지점에 도착했습니다. 정찰 임무 개시!', `MaleText_loc4`='顺利抵达目的地——这里就是本次侦察任务的目标地点。', `MaleText_loc5`='抵達目的地 - 進行偵查任務。', `MaleText_loc7`='Destino alcanzado... iniciando misión de exploración.' WHERE `ID`=32528;
