UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전장에서 또 뵙겠습니다.', `MaleText_loc4`='我们战场上见吧。', `MaleText_loc5`='戰場上見。', `MaleText_loc7`='Nos vemos en el campo de batalla.' WHERE `ID`=32531;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 몫으로 꼭 한 놈 처치하겠습니다.', `MaleText_loc4`='我会为你杀死一名敌人的。', `MaleText_loc5`='我可以為你殺一個人。', `MaleText_loc7`='Mataré a uno solo para ti.' WHERE `ID`=32532;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 내는 기묘한 소리가 당신 마음속에서 웃음소리로 느껴집니다.', `MaleText_loc4`='%s发出奇怪的声音，你觉得那是笑声。', `MaleText_loc5`='%s發出一股怪聲音，你認為那是嘲笑。', `MaleText_loc7`='%s hace un extraño ruido que se traduce como risa en tu mente.' WHERE `ID`=32533;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘이 네놈들 제삿날인 줄 알아라!', `MaleText_loc4`='我要把你碎尸万断！', `MaleText_loc5`='老兄，我要讓你血肉橫飛!', `MaleText_loc7`='¡Mi destriparte!' WHERE `ID`=32534;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 이 순간부터 아무것도 남지 않을 것이다!', `MaleText_loc4`='这之后，一切都将灭亡！', `MaleText_loc5`='在這之後什麼都不會剩下來!', `MaleText_loc7`='¡Después de esto no quedar nada!' WHERE `ID`=32535;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘이 뭔지 알고 싶나? 진짜 힘을 보여주지!', `MaleText_loc4`='你们想见识真正的力量？那我就让你们如愿以偿！', `MaleText_loc5`='你們想見識真正的力量?那我就讓你們如願以償!', `MaleText_loc7`='¿Tú querer ver poder? ¡TE MOSTRARÉ PODER!' WHERE `ID`=32536;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='들이받아라! 꿰뚫어 버려라!', `MaleText_loc4`='剁碎他们！刺穿他们！', `MaleText_loc5`='剁碎他們!刺穿他們!', `MaleText_loc7`='¡Destrípalos! ¡Ensártalos!' WHERE `ID`=32537;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전부 없애버려라!', `MaleText_loc4`='杀了他们！', `MaleText_loc5`='殺了他們!', `MaleText_loc7`='¡MÁTALOS A TODOS!' WHERE `ID`=32538;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='커다란 내 친구를 소개하지!', `MaleText_loc4`='来跟我的大朋友问声好吧！', `MaleText_loc5`='跟我的大朋友說聲嗨!', `MaleText_loc7`='¡Saluda a mi GRAN amigo!' WHERE `ID`=32539;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 빠른 거 아니냐?', `MaleText_loc4`='真快呀！', `MaleText_loc5`='真快呀!', `MaleText_loc7`='¡Qué prisa!' WHERE `ID`=32540;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 바로 신인데, 신이 왜 필요하지?', `MaleText_loc4`='谁需要神？我们自己就是神！', `MaleText_loc5`='誰需要神?我們自己就是神!', `MaleText_loc7`='¿Quién necesita dioses si NOSOTROS lo somos?' WHERE `ID`=32541;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 말하지 않았나!', `MaleText_loc4`='我提醒过你了！', `MaleText_loc5`='我早就跟你說過了!', `MaleText_loc7`='¡Te lo dije!' WHERE `ID`=32542;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강하다고... 불멸은 아니지...', `MaleText_loc4`='再强大的力量……也有衰落的一天。', `MaleText_loc5`='即使是強大的人...也會隕落。', `MaleText_loc7`='Hasta los poderosos... sucumben.' WHERE `ID`=32543;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주위에서 바람 소리가 나더니 철벽의 카노크가 나타납니다!', `MaleText_loc4`='当阻挡者卡诺克出现时，你周围的空气发出了爆裂声！', `MaleText_loc5`='鐵面無私的卡諾克出現時，你身邊的空氣都爆裂了!', `MaleText_loc7`='¡El aire que te rodea crepita cuando aparece Khanok el Infranqueable!' WHERE `ID`=32544;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈들에겐 희망이란 없다!', `MaleText_loc4`='你没有获胜的希望！', `MaleText_loc5`='你絕望吧!', `MaleText_loc7`='¡No hay esperanza para ti!' WHERE `ID`=32545;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나에게서 이 성채를 빼앗을 수 있을 거로 생각했나?', `MaleText_loc4`='你以为自己能从我手里夺得这座壁垒的控制权吗？', `MaleText_loc5`='你以為你有辦法從我的手中奪走這座壁壘嗎?', `MaleText_loc7`='¿Crees que puedes luchar para arrebatarme el control de esta muralla?' WHERE `ID`=32546;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='설마 아니겠지. 네놈의 건방진 코를 납작하게 만들고 나서, 네 시체를 성벽에 매달아 다른 ''영웅''들의 본보기로 삼겠다!', `MaleText_loc4`='我觉得你做不到。傲慢的家伙，你战败之后，我会将你的尸体用尖刺钉起来，为其他“英雄”做个示范！', `MaleText_loc5`='我不這麼想。等我將你打到自信全失後，我就會將你的屍體穿在矛上，讓其他的「英雄」引以為誡!', `MaleText_loc7`='Creo que no. ¡Cuando te haya sacado la arrogancia a palos, empalaré tu cadáver en las púas como ejemplo para otros "héroes"!' WHERE `ID`=32547;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하신가요, $c님.$B$B얼라이언스가 장악했을 때 겨울손아귀 요새로 가시고 싶은 분께는 제가 차원문을 열어 드립니다. 다음 전투가 시작될 때까지 남은 시간은 $4354k입니다.', `MaleText_loc4`='你好，$c。$B$B一旦联盟取得冬拥堡垒的控制权，我就将为想要前往那里的旅行者开启一道传送门。$B$B下一场战斗将在$4354k内开始。', `MaleText_loc5`='你好，$c。$B$B當聯盟控制了冬握堡壘，我就會開啟一道傳送門，提供那些想要前往那邊的人使用。$B$B下一場戰鬥將在$4354k後開始。', `MaleText_loc7`='Saludos, $c.$B$BCuando la Alianza controle la Fortaleza de Conquista del Invierno, abriré un portal para aquellos que deseen viajar hasta allí.$B$BLa próxima batalla comenzará en $4354k..', `FemaleText_loc1`='안녕하신가요, $c님.$B$B얼라이언스가 장악했을 때 겨울손아귀 요새로 가시고 싶은 분께는 제가 차원문을 열어 드리지요. 다음 전투가 시작될 때까지 남은 시간은 $4354k이에요.', `FemaleText_loc4`='你好，$c。$B$B一旦联盟取得冬拥堡垒的控制权，我就将为想要前往那里的旅行者开启一道传送门。$B$B下一场战斗将在$4354k内开始。', `FemaleText_loc5`='你好，$c。$B$B當聯盟控制了冬握堡壘，我就會開啟一道傳送門，提供那些想要前往那邊的人使用。$B$B下一場戰鬥將在$4354k後開始。', `FemaleText_loc7`='Saludos, $c.$B$BCuando la Alianza controle la Fortaleza de Conquista del Invierno, abriré un portal para aquellos que deseen viajar hasta allí.$B$BLa próxima batalla comenzará en $4354k..' WHERE `ID`=32548;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겨울손아귀 호수로 저를 순간이동시켜 주십시오.', `MaleText_loc4`='请送我去冬拥湖。', `MaleText_loc5`='將我傳送至冬握湖。', `MaleText_loc7`='Teletranspórtame al Lago Conquista del Invierno.', `FemaleText_loc1`='겨울손아귀 호수로 저를 순간이동시켜 주십시오.', `FemaleText_loc4`='请送我去冬拥湖。', `FemaleText_loc5`='將我傳送至冬握湖。', `FemaleText_loc7`='Teletranspórtame al Lago Conquista del Invierno.' WHERE `ID`=32549;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하신가요, $c님.$B$B호드가 장악했을 때 겨울손아귀 요새로 가시고 싶은 분이 있다면 제가 차원문을 열어 드리겠습니다. 다음 전투가 시작될 때까지 남은 시간은 $4354k입니다.', `MaleText_loc4`='你好，$c。$B$B一旦部落取得冬拥堡垒的控制权，我就将为想要前往那里的旅行者开启一道传送门。$B$B下一场战斗将在$4354k内开始。', `MaleText_loc5`='你好，$c。$B$B當部落控制了冬握堡壘，我就會開啟一道傳送門，提供那些想要前往那邊的人使用。$B$B下一場戰鬥將在$4354k後開始。', `MaleText_loc7`='Saludos, $c.$B$BCuando la Horda controle la Fortaleza de Conquista del Invierno, abriré un portal para aquellos que deseen viajar hasta allí.$B$BLa próxima batalla comenzará en $4354k.', `FemaleText_loc1`='안녕하신가요, $c님.$B$B호드가 장악했을 때 겨울손아귀 요새로 가시고 싶은 분이 있다면 제가 차원문을 열어 드리겠어요. 다음 전투가 시작될 때까지 남은 시간은 $4354k이에요.', `FemaleText_loc4`='你好，$c。$B$B一旦部落取得冬拥堡垒的控制权，我就将为想要前往那里的旅行者开启一道传送门。$B$B下一场战斗将在$4354k内开始。', `FemaleText_loc5`='你好，$c。$B$B當部落控制了冬握堡壘，我就會開啟一道傳送門，提供那些想要前往那邊的人使用。$B$B下一場戰鬥將在$4354k後開始。', `FemaleText_loc7`='Saludos, $c.$B$BCuando la Horda controle la Fortaleza de Conquista del Invierno, abriré un portal para aquellos que deseen viajar hasta allí.$B$BLa próxima batalla comenzará en $4354k.' WHERE `ID`=32550;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, $c님.$B$B겨울손아귀 요새를 얼라이언스가 장악했습니다. 필요하시다면, 이 차원문을 이용하십시오. 다음 전투는 $4354k 후에 시작됩니다.', `MaleText_loc4`='你好，$c。$B$B联盟已经控制了冬拥堡垒。如果你想去那里的话，就穿过这道传送门吧。$B$B下一场战斗将在$4354k内开始。', `MaleText_loc5`='你好，$c。$B$B聯盟現在已經控制了冬握堡壘。請自行使用傳送門。$B$B下一場戰鬥將在$4354k後開始。', `MaleText_loc7`='Saludos, $c.$B$BLa Alianza controla ahora la Fortaleza de Conquista del Invierno. Usa el portal si quieres.$B$BLa siguiente batalla comenzará en $4354k..', `FemaleText_loc1`='안녕하세요, $c님.$B$B겨울손아귀 요새를 얼라이언스가 장악했어요. 필요하시다면, 이 차원문을 이용하세요. 다음 전투는 $4354k 후에 시작된답니다.', `FemaleText_loc4`='你好，$c。$B$B联盟已经控制了冬拥堡垒。如果你想去那里的话，就穿过这道传送门吧。$B$B下一场战斗将在$4354k内开始。', `FemaleText_loc5`='你好，$c。$B$B聯盟現在已經控制了冬握堡壘。請自行使用傳送門。$B$B下一場戰鬥將在$4354k後開始。', `FemaleText_loc7`='Saludos, $c.$B$BLa Alianza controla ahora la Fortaleza de Conquista del Invierno. Usa el portal si quieres.$B$BLa siguiente batalla comenzará en $4354k..' WHERE `ID`=32551;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, $c님.$B$B호드가 겨울손아귀 요새를 손에 넣었습니다. 원하신다면, 이 차원문을 이용하십시오.$B$B다음 전투가 시작될 때까지 남은 시간은 $4354k입니다.', `MaleText_loc4`='你好，$c。$B$B部落已经控制了冬拥堡垒。如果你想去那里的话，就穿过这道传送门吧。$B$B下一场战斗将在$4354k内开始。', `MaleText_loc5`='你好，$c。$B$B部落現在已經控制了冬握堡壘。請自行使用傳送門。$B$B下一場戰鬥將在$4354k後開始。', `MaleText_loc7`='Saludos, $c.$B$BLa Horda controla ahora la Fortaleza de Conquista del Invierno. Usa el portal si quieres.$B$BLa siguiente batalla comenzará en $4354k..', `FemaleText_loc1`='안녕하신가요, $c님.$B$B호드가 겨울손아귀 요새를 손에 넣었군요. 원하신다면, 이 차원문을 이용하세요.$B$B다음 전투가 시작될 때까지 남은 시간은 $4354k이에요.', `FemaleText_loc4`='你好，$c。$B$B部落已经控制了冬拥堡垒。如果你想去那里的话，就穿过这道传送门吧。$B$B下一场战斗将在$4354k内开始。', `FemaleText_loc5`='你好，$c。$B$B部落現在已經控制了冬握堡壘。請自行使用傳送門。$B$B下一場戰鬥將在$4354k後開始。', `FemaleText_loc7`='Saludos, $c.$B$BLa Horda controla ahora la Fortaleza de Conquista del Invierno. Usa el portal si quieres.$B$BLa siguiente batalla comenzará en $4354k..' WHERE `ID`=32552;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겨우 이 정도냐, 악마야? 이게 전부란 말이냐?', `MaleText_loc4`='仅此而已？恶魔，你没有别的东西可扔了吗？', `MaleText_loc5`='只有這樣嗎，惡魔?沒東西可以砸我們了嗎?', `MaleText_loc7`='¿Eso es todo, demonio? ¿No te queda nada con qué atacarnos?' WHERE `ID`=32553;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 황혼의 차원문을 엽니다!', `MaleText_loc4`='%s开始召唤暮光传送门！', `MaleText_loc5`='%s開始開啟暮光傳送門!', `MaleText_loc7`='¡%s comienza a abrir Portales Crepuscular!' WHERE `ID`=32554;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼음왕관, 숄라자르 분지, 폭풍우 봉우리에서만 날 수 있습니다.', `MaleText_loc4`='你只能在冰冠冰川、索拉查盆地和风暴峭壁的上空飞行。', `MaleText_loc5`='你只能在寒冰皇冠，休拉薩盆地和風暴群山裡飛行。', `MaleText_loc7`='Solo puedes volar en Corona de Hielo, Cuenca de Sholazar y Las Cumbres Tormentosas.', `FemaleText_loc1`='얼음왕관, 숄라자르 분지, 폭풍우 봉우리에서만 날 수 있습니다.', `FemaleText_loc4`='你只能在冰冠冰川、索拉查盆地和风暴峭壁的上空飞行。', `FemaleText_loc5`='你只能在寒冰皇冠，休拉薩盆地和風暴群山裡飛行。', `FemaleText_loc7`='Solo puedes volar en Corona de Hielo, Cuenca de Sholazar y Las Cumbres Tormentosas.' WHERE `ID`=32556;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='모험가 여러분, 문이 힘을 잃어가기 시작했습니다!', `FemaleText_loc4`='冒险者们，牢门的力量开始减弱了！', `FemaleText_loc5`='大門開始動搖了，冒險者們!', `FemaleText_loc7`='¡Aventureros, la puerta comienza a ceder!' WHERE `ID`=32557;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='문을 봉인하는 힘이 반밖에 남지 않았습니다! 계속 싸워 주십시오!', `FemaleText_loc4`='牢门的封印力量只剩一半了！你们必须坚持住！', `FemaleText_loc5`='大門封印的力量只剩下一半了!你們必須繼續攻擊!', `FemaleText_loc7`='¡La puerta resiste la mitad que antes! ¡Debéis seguir luchando!' WHERE `ID`=32558;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='문 봉인이 무너지기 일보 직전입니다! 모든 힘이 사라지고 나면 푸른용군단이 그 문으로 몰려 올 것입니다!', `FemaleText_loc4`='牢门的封印即将崩溃！如果蓝龙军团攻破大门，一切都完了！', `FemaleText_loc5`='大門封印快要崩塌了!要是藍龍軍團衝破大門，所有的東西都會被毀了!', `FemaleText_loc7`='¡La puerta está a punto de derrumbarse! ¡Todo estará perdido si el Vuelo Azul la atraviesa!' WHERE `ID`=32559;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만두십시오, 마이클. 지금의 무서운 상황만으로도 장사가 충분히 타격을 받고 있습니다. 한 푼이라도 아끼면 됩니다.', `MaleText_loc4`='够了，麦克尔。城里的气氛越来越恐慌，我们的生意已经够惨淡的了。就算是一个铜板的小买卖也不应该错过。', `MaleText_loc5`='夠了，麥可。生意嚴重受到這次恐慌影響。我們', `MaleText_loc7`='Ya basta, Michael. El negocio ya está sufriendo bastante con este susto. Podemos usar hasta la última moneda de cobre.' WHERE `ID`=32560;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드를 위하여!', `MaleText_loc4`='为了部落！', `MaleText_loc5`='為了部落!', `MaleText_loc7`='¡Por la Horda!' WHERE `ID`=32561;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반가워, 친구. 내가 도와줄 일이라도 있어?', `MaleText_loc4`='你好，朋友。我能为你做什么吗？', `MaleText_loc5`='你好，朋友。我可以為你做些什麼嗎?', `MaleText_loc7`='Saludos, $gamigo:amiga;. ¿Puedo hacer algo por ti?' WHERE `ID`=32562;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐 거기, 잠깐만 있어봐. 보니까 지금 탄 나는 탈것은 자네 전용이 아니잖아.$B$B계속 이 주변을 돌아다닐 수 없다면 다른 고블린들에게 그리 쓸모있는 존재는 못 될 텐데 말이야. 다른 친구들이 자네 같은 사람한테 내가 타던 나는 탈것을 빌려주라고 돈을 좀 내놨는데 말이야. 자네는 돈 한 푼 안 내도 괜찮고 말이지.$B$B어때, 관심 있어?', `MaleText_loc4`='嘿，等一等。你没有属于自己的飞行坐骑诶。$B$B如果出行不便的话，恐怕你没有办法帮助其他的地精了。他们付钱给我，让我将旧坐骑借给你这样的人使用——免费使用哦。$B$B怎么样？', `MaleText_loc5`='嗨你好，等一會兒。我看到你沒有騎乘自己的飛行坐騎。$B$B如果你沒辦法到處去的話，那你可能對這裡的哥布林來說沒有多大的用處。他們聘用我，要我免費出租我的二手坐騎給像你這樣的人。$B$B有興趣嗎?', `MaleText_loc7`='¡Hola! Espera un segundo. Veo que no llevas una montura propia.$b$bProbablemente no serás de mucha ayuda a otros goblins si no puedes moverte a tus anchas. Me han pagado para que preste mis monturas a gente como tú... y sin coste alguno.$b$b¿Te interesa?' WHERE `ID`=32563;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 간다! 마음의 준비나 해라!', `MaleText_loc4`='我们来了！做好准备吧！', `MaleText_loc5`='我們為你而來!做好準備!', `MaleText_loc7`='¡Venimos por ti! ¡Prepárate!' WHERE `ID`=32564;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겁쟁이 같으니! 호드의 대족장을 그깟 돌멩이 몇 개로 막으려 드느냐? 진정한 정령의 힘을 보여주마!', `MaleText_loc4`='懦夫！你以为投掷小石块就能阻止部落的酋长吗？我会让你见识到元素的真正力量！', `MaleText_loc5`='懦夫!你以為用這些小石子就能夠阻止部落的大酋長嗎?我會讓你見識元素的力量!', `MaleText_loc7`='¡COBARDE! ¿Piensas detener al Jefe de Guerra de la Horda con piedritas? ¡Te mostraré el verdadero poder de los elementos!' WHERE `ID`=32565;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='관심이 있습니다.', `MaleText_loc4`='好吧。', `MaleText_loc5`='我很感興趣。', `MaleText_loc7`='Me interesa.', `FemaleText_loc1`='관심이야 있고말고요.', `FemaleText_loc4`='好吧。', `FemaleText_loc5`='我很感興趣。', `FemaleText_loc7`='Me interesa.' WHERE `ID`=32566;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대족장, 조금만 더 가면 왕실이오.', `FemaleText_loc4`='前面不远就是皇家区了，酋长。', `FemaleText_loc5`='皇家區就在前面，大酋長。', `FemaleText_loc7`='El Barrio real está allí delante, Jefe de Guerra.' WHERE `ID`=32567;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='통로를 무너뜨려라! 당장!', `MaleText_loc4`='摧毁大厅！快！', `MaleText_loc5`='攻陷大廳!快!', `MaleText_loc7`='¡Derriben los salones! ¡AHORA!' WHERE `ID`=32568;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 마지못해 고개를 끄덕입니다.', `MaleText_loc4`='%s不情愿地点了点头。', `MaleText_loc5`='%s不情不願的點頭。', `MaleText_loc7`='%s asiente a regañadientes.' WHERE `ID`=32569;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그에 대해 이야기하고 싶지 않습니다.', `MaleText_loc4`='好吧，你说得对。', `MaleText_loc5`='我無法反駁。', `MaleText_loc7`='Eso no lo puedo discutir.' WHERE `ID`=32570;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='병사들은 중요한 일을 하고 있습니다. 사람들의 안전은 더욱 중요하죠, 말. 당신에게는 고객이 하루라도 돈을 쓰는 게 중요하니 말입니다.', `MaleText_loc4`='士兵的工作非常重要。人民的安全更加重要，马尔，如果你还想让顾客们多活一天的话。', `MaleText_loc5`='士兵們正在進行重要的工作。不過，瑪爾，如果你想要你的客戶好好活著，改天再度光臨的話，那人民的安全會更重要。', `MaleText_loc7`='Los soldados están realizando un gran trabajo. Mal, si lo que te interesa es que tus clientes vivan otro día más, la seguridad del pueblo es lo más importante.' WHERE `ID`=32571;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 걱정하지 마십시오. 제가 쉬던 날까지 여기서 더럽혀진 곡식이 발견된 적은 한 번도 없습니다.', `MaleText_loc4`='别太担心。直到我下班的时候，这里还没有发现一颗被污染的谷物。', `MaleText_loc5`='別擔憂太多。在我下班前，我們在這連一點污染的穀物都沒找到過。', `MaleText_loc7`='No te preocupes demasiado. Para cuando terminé la guardia no habíamos encontrado ni un poquito de ese grano.' WHERE `ID`=32572;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오오, 신이여, 다행이군요.', `MaleText_loc4`='感谢圣光。', `MaleText_loc5`='真是感謝聖光。', `MaleText_loc7`='Gracias a la Luz.' WHERE `ID`=32573;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 고개를 끄덕입니다.', `MaleText_loc4`='%s点了点头。', `MaleText_loc5`='%s點頭。', `MaleText_loc7`='%s asiente con la cabeza.' WHERE `ID`=32574;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위대한 대지의 정령이여, 지금 그대의 도움이 필요하다!', `MaleText_loc4`='伟大的大地之灵，请在紧急关头帮助我们吧！', `MaleText_loc5`='偉大的大地之靈，請在我們需要的時刻幫助我們!', `MaleText_loc7`='¡Grandes espíritus de la tierra, necesitamos su ayuda!' WHERE `ID`=32575;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 도와드리면 될까요?', `MaleText_loc4`='你需要什么帮助？', `MaleText_loc5`='你需要哪方面的幫助?', `MaleText_loc7`='¿Qué tipo de ayuda necesitas?', `FemaleText_loc1`='어떻게 도와드리면 될까요?', `FemaleText_loc4`='你需要什么帮助？', `FemaleText_loc5`='你需要哪方面的幫助?', `FemaleText_loc7`='¿Qué tipo de ayuda necesitas?' WHERE `ID`=32576;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노르간논의 쐐기돌에 대한 단서를 찾았습니다. 그 쐐기돌은 울두아르 기록에 접근 여부를 관리하는 역할을 하지만, 티탄들이 둘로 나누어 비밀리에 숨겼지요.$B$B그중 한 조각은 쐐기돌의 껍질인데 북쪽 해안에 있는 발명가의 도서관 안에 보관되어 있어요. 바로 울두아르에서는 남쪽이죠. 당신이 가장 먼저 해야 할 일은 도서관 수호병에게서 접속 원반 조각을 되찾아 오는 일입니다.', `MaleText_loc4`='我已经找到了诺甘农钥石的线索，有了它就能进入奥杜尔的档案室；但是泰坦将钥石分成了两块并分别藏了起来。$B$B钥石的外壳藏在北部海滩的创世者图书馆里，就在奥杜尔以南。首先，你要从图书馆守护者那里获得访问磁盘的碎片。', `MaleText_loc5`='我有獲得諾甘農拱心石的線索。諾甘農拱心石是守護奧杜亞檔案庫的鑰匙，但是泰坦將它分成兩半，藏起來。$B$B其中一塊，拱心石的殼，藏在北海岸的發明者圖書館，就在奧杜亞南方。所以你要做的第一件事情就是從圖書館守衛者身上拿回通行圓盤的碎片。', `MaleText_loc7`='Tengo una pista sobre la piedra angular de Norgannon, que guarda la entrada a los archivos de Ulduar, pero los titanes la dividieron en dos partes y las ocultaron.$B$BUna de esas partes, el esqueleto de la piedra angular, está en la Biblioteca del Inventor en la costa norte, al sur de Ulduar. Lo primero que tienes que hacer es recuperar los fragmentos de un disco de acceso de manos de los guardianes de la biblioteca.' WHERE `ID`=32577;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='때가 되었네. 빛이여, 우리에게 힘을 주소서.', `MaleText_loc4`='时间到了。愿圣光赐予我们力量吧。', `MaleText_loc5`='時候到了。願聖光賜給我們力量。', `MaleText_loc7`='Es la hora. Que la Luz nos otorgue la fuerza.' WHERE `ID`=32578;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거듭거듭 사죄드립니다, 주인님! 제가 침입자들을 직접 처리하겠습니다!', `MaleText_loc4`='我乞求您的宽恕，主人！我一定会亲手解决入侵者的！', `MaleText_loc5`='真是萬分的抱歉，主上!我將親自解決這些入侵者!', `MaleText_loc7`='¡Miles de miles de perdones, mi Amo! ¡Yo mismo me encargaré de estos intrusos!' WHERE `ID`=32579;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이것이 네놈들의 미래다. 아무것도 남은 건 없지...', `MaleText_loc4`='接受你的未来吧——命运什么都没给你留下……', `MaleText_loc5`='歡迎來到你的未來 -- 毫無展望的未來...', `MaleText_loc7`='Bienvenidos a su futuro... A lo poco que queda de él…' WHERE `ID`=32580;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='보물 얘기를 해보자면, 다른 사람이 쓰레기 같은 물건을 줍는 모습을 곁눈질하지 마십시오. 훔친 물건이 훨씬 짜릿합니다. 그죠? 어떻게 손에 넣었든 간에 공짜는 공짜인 법입니다!', `FemaleText_loc4`='说到财宝，永远不要轻视翻捡别人的垃圾的行为。偷来的财宝更加珍贵，是吗？但是免费的东西就是好的，无论你采用什么方式！', `FemaleText_loc5`='提到財寶，千萬別在拾取別人的垃圾時東張西望。偷來的都比較珍貴，是吧?不用錢的就是不用錢，不管是怎麼到手的都一樣!', `FemaleText_loc7`='Con los tesoros, nunca se mira la basura de''l de al lao. Lo robao siempre es mejor, ¿ve''dad? Pero gratis es gratis, ¡lo demás no importa!' WHERE `ID`=32581;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불청객들이로군! 내 영역에 슬그머니 들어오면 모를 줄 알았나?', `MaleText_loc4`='不速之客！你们以为自己能偷偷地溜进我的王国吗？', `MaleText_loc5`='意外的訪客!你們以為你們可以踏入我的領地而不被發現嗎?', `MaleText_loc7`='¡Invitados indeseados! ¿Pensasteis que pasaríais desapercibidos en mi dominio?' WHERE `ID`=32582;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서! 서둘러라!', `MaleText_loc4`='走吧！快！', `MaleText_loc5`='出發吧!快!', `MaleText_loc7`='¡VAMOS! ¡RÁPIDO!' WHERE `ID`=32583;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 뭐지?', `MaleText_loc4`='怎么回事？', `MaleText_loc5`='這是什麼?', `MaleText_loc7`='¿Qué es esto?' WHERE `ID`=32584;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='솔직히 말하지... 네 녀석들이 나타나리라 어느 정도 예상하고 있었다. 이곳이 마음에 들길 바란다. 너희가 영원히 잠들 곳이니...', `MaleText_loc4`='我必须承认……我早已预知你们的到来。希望你们能找到安息地……适合你们的安息地。', `MaleText_loc5`='我必須承認...你們不全然是出乎意料之外。我希望你們可以找到...合意的最後棲息之地。', `MaleText_loc7`='Debo confesar que... no es que no te esperáramos. Espero que tu lugar de descanso sea de tu agrado.' WHERE `ID`=32585;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저야 언제나 슬쩍한 괜찮은 물건에 관심이 많지요. 훔치는 일은 전부 손목에 달렸습니다... 그렇게 실패하면 갈비뼈 사이에 무언가 날카로운 걸 밀어 넣으십시오. 그것도 다 손목에 달린 일이지만요.$B$B능숙한 손재주가 있다면 매달 받는 월급봉투보다 훨씬 수입이 좋기 마련이지요. 듣고 계십니까?', `FemaleText_loc4`='人们经常置疑我身为三指大盗的本事。其实我靠的是手腕的灵活性……一旦失手，你应该立即制服他们，这同样要依赖手腕的力量。$B$B灵巧的双手比稳定的收入更加宝贵，你明白吗？', `FemaleText_loc5`='我總是讓他們三根手指。偷竊的關鍵在於手腕...甚至是遇到失敗，你將某種銳利物插近對方胸膛時，關鍵也還是在手腕。$B$B技術熟練的雙手遠比穩定的收入更加有用，懂了嗎?', `FemaleText_loc7`='Siempre ''toy lih''ta pa'' un buen descuento de un tré'' dedos. Roba'' ehtá todo en la muñeca... y cuando falla, entonces clavas algo afilao entre las costillas, y todo en la muñeca también.$B$BLas manos asesinas valen más que un pago forá'', ¿me oyes?' WHERE `ID`=32586;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='리치 왕 따위는 별로 신경 쓰지 않습니다. 수많은 거물이 오고 가는 걸 보아왔는데, 항상 무언가 엉망으로 만들어 놓더군요. 그리고 얼마 지나지 않아 다른 무리가 들고일어나 그들을 역사의 저편으로 보내버렸습니다. 리치 왕이라고 별다를 바가 없지요.', `FemaleText_loc4`='我一点都不担心巫妖王。我见过无数的大人物沉沉浮浮，他们喜欢把事情搞得一团糟。但是每当人民站起来反抗时，他们很快就会偃旗息鼓，沦为历史课本上的教程。巫妖王也不会例外。', `FemaleText_loc5`='我不是很擔心這個巫妖王。我看過太多大人物的來來去去，他們總是把事情搞砸。然後要不了多久，就會又來一批大人物，把先前的傢伙通通送進歷史課本裡頭去。這個傢伙也不例外。', `FemaleText_loc7`='No me preocupa el Rey Exánime. He visto muchos como él ir y venir, siempre eh''tropean algo. Poco tardan después en envíahlos a su lugar en los libros de historia. Este no será diferente.' WHERE `ID`=32587;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 마지막으로 보았을 땐, 네 녀석이 유리했다. 성스러운 땅에서 싸웠기 때문이지. 하지만 이번엔 상황이 뒤바뀌었다는 걸 곧 알게 될 것이다...', `MaleText_loc4`='我们上次交手时，你占尽了圣地的优势。但如今，你会发现我们的境遇已经发生了……逆转。', `MaleText_loc5`='上次我們碰面的時候，你佔著聖地的地利優勢。你將會發現...情況恰恰相反。', `MaleText_loc7`='La última vez que nos vimos tenías la ventaja de luchar sobre suelo sagrado. Comprobarás que la situación ha... dado un giro.' WHERE `ID`=32588;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럴지도 모르지. 하지만 성스러운 땅이 아니더라도 이 파멸의 인도자로 네놈의 그 주인 잃은 심장은 충분히 찌를 수 있다.', `MaleText_loc4`='或许吧。就算我的双脚没有踏在圣地上，也能用灰烬使者摧毁你的徽记。', `MaleText_loc5`='或許吧，不過我不需要在聖地上也能用灰燼使者驅動你那離體的心。', `MaleText_loc7`='Podría ser, pero no necesito estar en suelo sagrado para atravesarte ese corazón abstracto que tienes con la Crematoria.' WHERE `ID`=32589;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='심장... 네가 인간이었음을 알려 주는 마지막 흔적이지. 난 그 심장이 파괴되는 걸 막으려 했다. 내 눈으로 직접 확인하고 싶었지. 하지만 이젠 알겠다...', `MaleText_loc4`='徽记……那是你残存的最后一丝人性。我要在你彻底丧失人性之前亲自摧毁它。我相信……', `MaleText_loc5`='心...是你所殘餘的最後一點人性。我必須阻止它被消滅。我必須親眼看看，我才夠確信...', `MaleText_loc7`='El corazón... último vestigio de tu humanidad. Debía impedir que lo destruyeran. Debo velar por mí mismo. Y al menos estoy seguro...' WHERE `ID`=32590;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 자신만만한 것 아닌가? 지난번에 우리 만났을 때를 생각하면 그런 말 하기 쉽지 않을 텐데.', `MaleText_loc4`='你似乎过于自信了。你不如想想上次我们交手的结果。', `MaleText_loc5`='你聽起來有點太過自信了。尤其是考慮到我們最後一次交手的結果。', `MaleText_loc7`='Pareces estar muy seguro de ti mismo, sobre todo teniendo en cuenta la forma de la que terminó nuestro último enfrentamiento.' WHERE `ID`=32592;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해볼 테면 한번 해 봐라. 너는 어쩔 수 없는 성기사다. 너의 그 구원에의 집착은 어리석다 못해 애처로울 지경이다.', `MaleText_loc4`='别虚张声势了，你毕竟是一名圣骑士。你对于救赎的痴迷已经到了不可救药的地步。', `MaleText_loc5`='你不過是在唬人。你終究是個聖騎士。你對於救贖的執迷早已近乎瘋狂。', `MaleText_loc7`='Demuéstralo. Después de todo, eres un paladín. Tu obsesión por la salvación sobrepasa la necedad.' WHERE `ID`=32593;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타락의 나락에 떨어진 인간의 아들을 구원할 유일한 기회다. 네놈이 과연 그걸 포기할 수 있을까? 네 목숨을 바쳐서라도 그 기회를 잡겠지!', `MaleText_loc4`='你想要“挽救”我这个任性的孩子，不愿意放弃人道救赎的唯一机会，因此你只会死得更快！', `MaleText_loc5`='你肯定不會把人性的最後一絲希望，這個救贖一個最無可救藥之人的唯一機會給毀去。你寧願死也不會這麼做!', `MaleText_loc7`='Probablemente no destruirías la única oportunidad de la humanidad de salvar a su más porfiado hijo. ¡Antes morirías!' WHERE `ID`=32594;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네게 남아있는 건 단지 과거의 그림자일 뿐. 네놈에게 구원은 없다!', `MaleText_loc4`='你心中只剩下往昔的阴影，无可救赎了！', `MaleText_loc5`='過去只剩暗影殘存。早已沒有東西可以救贖了!', `MaleText_loc7`='Solo quedan sombras del pasado. No hay nada que rescatar.' WHERE `ID`=32595;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샤글라요스 플라프 음흐나우스.', `MaleText_loc4`='Shgla''yos plahf mh''naus。', `MaleText_loc5`='Shgla''yos plahf mh''naus.', `MaleText_loc7`='Shgla''yos plahf mh''naus.' WHERE `ID`=32596;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='길 잃은 영혼을 맛본 자는 영원히 굶주림에 시달리게 되지.', `MaleText_loc4`='饥饿驱使着那些以失落灵魂为食的阴影。', `MaleText_loc5`='(上古語)以迷失靈魂為食者，只瞭解飢渴。', `MaleText_loc7`='Solo aquellos que se alimentan de almas perdidas conocen el hambre.' WHERE `ID`=32597;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이와크 마 프와쿨 낙푸.', `MaleText_loc4`='Ywaq ma phgwa''cul hnakf。', `MaleText_loc5`='Ywaq ma phgwa''cul hnakf.', `MaleText_loc7`='Ywaq ma phgwa''cul hnakf.' WHERE `ID`=32598;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우울비 각 어훈그 우.', `MaleText_loc4`='Uulwi gag erh''ongg w''ssh。', `MaleText_loc5`='Uulwi gag erh''ongg w''ssh.', `MaleText_loc7`='Uulwi gag erh''ongg w''ssh.' WHERE `ID`=32599;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이와크 풀 크스근 온마 예글루 주.', `MaleText_loc4`='Ywaq puul skshgn: on''ma yeh''glu zuq。', `MaleText_loc5`='Ywaq puul skshgn: on''ma yeh''glu zuq.', `MaleText_loc7`='Ywaq puul skshgn: on''ma yeh''glu zuq.' WHERE `ID`=32600;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='릴스 브와, 우나트 프쉬 자.', `MaleText_loc4`='Iilth vwah, uhn''agth fhssh za。', `MaleText_loc5`='Iilth vwah, uhn''agth fhssh za.', `MaleText_loc7`='Lilth vwah, uhn''agth fhssh za.' WHERE `ID`=32601;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이와크 마크 오우, 이와크 막 싸아크. 이와크 마 쉬픈.', `MaleText_loc4`='Ywaq maq oou; ywaq maq ssaggh. Ywaq ma shg''fhn。', `MaleText_loc5`='Ywaq maq oou; ywaq maq ssaggh. Ywaq ma shg''fhn.', `MaleText_loc7`='Ywaq maq oou; ywaq maq ssaggh. Ywaq ma shg''fhn.' WHERE `ID`=32602;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='굴카프 안셸 율. 요칼 쉰키 이와크 눌.', `MaleText_loc4`='Gul''kafh an''shel。Yoq''al shn ky ywaq nuul。', `MaleText_loc5`='Gul''kafh an''shel. Yoq''al shn ky ywaq nuul.', `MaleText_loc7`='Gul''kafh an''shel. Yoq''al shn ky ywaq nuul.' WHERE `ID`=32603;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공허를 들여다보아라. 그들이 속한 불멸의 영역이지.', `MaleText_loc4`='凝视虚空吧。它们就居住在其中。', `MaleText_loc5`='(上古語)凝視虛無。他們就存在於永恆不滅之中。', `MaleText_loc7`='Contempla el vacío. Esa es la perpetuidad en la que moran.' WHERE `ID`=32604;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들은 매서운 바람의 속삭임이다.', `MaleText_loc4`='它们是寒风中的低语。', `MaleText_loc5`='(上古語)他們是在顫抖風中的低語。', `MaleText_loc7`='Son el susurro del escalofriante viento.' WHERE `ID`=32605;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들의 그림자가 영원토록 이 땅을 옥죄리라.', `MaleText_loc4`='它们的阴影将永远地笼罩着大地。', `MaleText_loc5`='(上古語)他們的陰影將會永遠地纏繞著大地。', `MaleText_loc7`='La sombra ahogará al mundo para toda la eternidad.' WHERE `ID`=32606;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들은 공포를 마신다. 그것은 생명이다.', `MaleText_loc4`='它们畅饮着你们的恐惧：这是生命的鲜血。', `MaleText_loc5`='(上古語)他們暢飲你的恐懼，那是生命的血液。', `MaleText_loc7`='Se beben tu temor: es la sangre de la vida.' WHERE `ID`=32607;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하나가 죽으면, 수많은 이가 그 자리를 대신하지.', `MaleText_loc4`='每倒下一个，会有更多的阴影接替它的位置。', `MaleText_loc5`='(上古語)當一個逝去，無數的將會取代其位。', `MaleText_loc7`='Donde uno cae, muchos podrán ocupar su puesto.' WHERE `ID`=32608;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들은 죽지 않는다. 그들은 살지 않는다. 그들은 생명의 순환을 벗어난 존재다.', `MaleText_loc4`='它们无所谓死，亦无所谓生。它们游离于生命的循环之外。', `MaleText_loc5`='(上古語)他們不會死去，他們也不曾活著。他們立於生命的循環之外。', `MaleText_loc7`='No mueren, no viven. Están fuera del ciclo.' WHERE `ID`=32609;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 오래... 쉬지 않고 계획해온 일이... 이렇게 끝나서는 안 돼...', `MaleText_loc4`='长久以来……我们不知疲倦地谋划……不应该落得这样的结局……', `MaleText_loc5`='一直以來...不眠不休，永無止境的計畫...結局不應該是這樣的...', `MaleText_loc7`='Tanto tiempo... Tanto planear interminablemente, inagotablemente... No terminará así…' WHERE `ID`=32610;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간이 더 필요해... 주인님이 오셨어...', `MaleText_loc4`='再给我一点时间……主人就在附近……', `MaleText_loc5`='需要更多時間...主人就快到了...', `MaleText_loc7`='Necesito más tiempo... El Amo se acerca…' WHERE `ID`=32611;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강력한 힘! 느껴지는가, 필멸의 존재여? 어리석은 짓은 그만두고 내 편에 서라!', `MaleText_loc4`='强大的力量！凡人们，你们感受不到吗？别愚蠢啦，加入我们吧！', `MaleText_loc5`='多強大的力量!感受到了嗎，凡人?停止你們的愚蠢行為，加入我吧!', `MaleText_loc7`='¡Cuánto poder! ¿No lo sienten, mortales? ¡Desistan esta insensatez y únanse a mí!' WHERE `ID`=32612;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실패하지 않는다! 두 번 다시는!', `MaleText_loc4`='我不会失败！再也不会！', `MaleText_loc5`='我不會失敗的!永遠不會!', `MaleText_loc7`='¡No fallaré! ¡Otra vez no!' WHERE `ID`=32613;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='견딜 수가 없다... 힘이 불안정하다...', `MaleText_loc4`='我快要……坚持不住了……', `MaleText_loc5`='我控制不了...局勢...', `MaleText_loc7`='No puedo... Me desestabilizo…' WHERE `ID`=32614;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼굴 없는 자들에게 우리 형제들을 많이 잃었지만, 나즈아낙에서 무사히 심장을 가져왔습니다.', `MaleText_loc4`='大人，虽然我们在与无面者战斗的过程中损失了不少人手，但是我们成功地从纳扎纳克夺回了徽记。', `MaleText_loc5`='我們在對抗無面者時損失了許多兵力，大人。但我們成功取回了納茲安納克的心臟。', `MaleText_loc7`='Hemos perdido a muchos de mano de los ignotos, mi señor. Pero hemos logrado recuperar el corazón de Naz''anak.', `FemaleText_loc1`='얼굴 없는 자들에게 우리 형제들을 많이 잃었지만, 나즈아낙에서 무사히 심장을 가져왔습니다.', `FemaleText_loc4`='大人，虽然我们在与无面者战斗的过程中损失了不少人手，但是我们成功地从纳扎纳克夺回了徽记。', `FemaleText_loc5`='我們在對抗無面者時損失了許多兵力，大人。但我們成功取回了納茲安納克的心臟。', `FemaleText_loc7`='Hemos perdido a muchos de mano de los ignotos, mi señor. Pero hemos logrado recuperar el corazón de Naz''anak.' WHERE `ID`=32615;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고개 숙이고 조심해서 날 따라오게.', `MaleText_loc4`='保持冷静，听我的指挥。', `MaleText_loc5`='把頭低著，然後跟隨我。', `MaleText_loc7`='Mantened la cabeza agachada y seguidme.' WHERE `ID`=32616;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헛된... 시간이었나...', `MaleText_loc4`='心血……付诸一旦……', `MaleText_loc5`='多年的努力...就此白廢...', `MaleText_loc7`='Años... desperdiciados…' WHERE `ID`=32617;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 실망시켰구나, 바리마트라스!', `MaleText_loc4`='你真让我失望，瓦里玛萨斯！', `MaleText_loc5`='你令我失望，瓦里瑪薩斯!', `MaleText_loc7`='¡ME HAS FALLADO, VARIMATHRAS!' WHERE `ID`=32618;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='점점 가까워지네. 준비하게.', `MaleText_loc4`='它来了。做好准备。', `MaleText_loc5`='來囉。準備好。', `MaleText_loc7`='Ahí viene. ¡Prepárate!' WHERE `ID`=32619;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭔가 이상해... 어둠의 존재가 느껴지네.', `MaleText_loc4`='不对劲……我感觉到黑暗的气息。', `MaleText_loc5`='哪裡不太對勁...我感覺到一股黑暗的存在。', `MaleText_loc7`='Algo va mal... Siento una presencia oscura.' WHERE `ID`=32620;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕이 이곳에 있네. 빛이여, 우리의 검을 인도하소서.', `MaleText_loc4`='巫妖王就在这里。愿圣光指引我们的剑刃吧。', `MaleText_loc5`='巫妖王就在這裡。願聖光引導我們的劍刃。', `MaleText_loc7`='El Rey Exánime está aquí. Que la Luz guíe nuestras espadas.' WHERE `ID`=32621;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='포로가 서럽게 흐느끼며 죽음을 기다리고 있습니다.', `MaleText_loc4`='囚犯们绝望地啜泣着，等待末日的来临。', `MaleText_loc5`='這個囚犯絕望地啜泣著，等待死亡的降臨。', `MaleText_loc7`='El prisionero solloza desesperado, esperando a que llegue el fin.', `FemaleText_loc1`='포로가 서럽게 흐느끼며 죽음을 기다리고 있습니다.', `FemaleText_loc4`='囚犯们绝望地啜泣着，等待末日的来临。', `FemaleText_loc5`='這個囚犯絕望地啜泣著，等待死亡的降臨。', `FemaleText_loc7`='La prisionera solloza desesperada, esperando a que llegue el fin.' WHERE `ID`=32622;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바보나 내 전투 복장을 보고 비웃겠지.$B$B낡은 강철로 만든 이 의복은 지식을 배우던 고대 장소에서 난 것일세!', `MaleText_loc4`='那些嘲笑我的战袍的人都是蠢货。$B$B这件衣服所用的旧钢都来自一个远古的学习之地！', `MaleText_loc5`='只有傻子才會仿造我的戰鬥裝束外觀。$B$B這套破舊的鋼鐵外衣是出自於遠古知識之地!', `MaleText_loc7`='Solo un necio se burlaría del aspecto de mi atuendo de batalla.$b$b¡Estas vestiduras de acero desgastado provienen de un inmemorial lugar de aprendizaje!' WHERE `ID`=32623;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번에는 그렇게 쉽게 죽지 않을 것이다!', `MaleText_loc4`='这次我不会死那么快了！', `MaleText_loc5`='這次我可不會死那麼快了!', `MaleText_loc7`='¡Esta vez no moriré tan rápido!' WHERE `ID`=32624;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='용사들이여! 내 친히 축복한 비룡들을 보내, 이 전투를 돕겠노라!', `FemaleText_loc4`='勇士们！我将派出得到我祝福的孩子，帮助你们进行战斗！', `FemaleText_loc5`='勇士!我將派出受我祝福的孩子，幫助你們進行戰鬥!', `FemaleText_loc7`='¡Campeones! ¡Mis hijos, bendecidos con mi poder, te ayudarán en tu lucha!' WHERE `ID`=32625;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='해야 할 일을 했을 뿐이야. 선택의 여지가 없었지...', `FemaleText_loc4`='我只是尽了我应尽的义务，兄长。你让我别无选择。', `FemaleText_loc5`='我只是盡忠職守，兄長。你讓我別無選擇。', `FemaleText_loc7`='Hice lo que debía hacer, hermano. No me diste alternativa.' WHERE `ID`=32626;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마력 전쟁은, 끝났다.', `FemaleText_loc4`='魔枢战争就此结束了。', `FemaleText_loc5`='奧核戰爭就此結束。', `FemaleText_loc7`='Así termina la Guerra de Nexus. ' WHERE `ID`=32627;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너무나도 가슴 아픈 결정이었지만... 그 모든 파괴, 터무니없는 학살은 끝이 나야만 했다. 그러나 말리고스의 죄악과 상관없이 나는 그의 죽음을 애도할 것이다. 그도 한때는 이 세계의 수호자였지. 오늘, 한 강력한 존재가 떠났다.', `FemaleText_loc4`='这个决定令我的心灵深处痛楚不已，但这生灵涂炭与天地崩裂的局面也终于得到了休止。无论玛里苟斯犯过什么大错，我都会为他的死默哀。他曾是一位高贵的守护者。今天，世界上最强大的守护者之一，就这样逝去了。', `FemaleText_loc5`='這個決定令我痛苦不已，然而這些破壞與生靈塗炭的局面非得被阻止不可。無論瑪里苟斯晚近的罪衍多重，我還是會哀悼他的逝亡。他曾是一位高貴的守護者。今天，世界上最強大的存在之一，就這麼消逝了。', `FemaleText_loc7`='Esta decisión me apesadumbra, pero la destrucción, la pérdida colosal de vidas debía terminar. Pese a las transgresiones recientes de Malygos, lloraré su muerte. Una vez fue un guardián, un protector. Hoy, ha caído uno de los más poderosos del mundo.' WHERE `ID`=32628;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='붉은용군단은 아제로스를 할퀴고 지나간 파괴의 흔적을 치유할 것이다. 동료와 함께 고향으로 돌아가 쉬어라. 내일은 새로운 도전이 기다리고, 그대들은 그에 맞서야만 하노라. 삶은... 계속된다.', `FemaleText_loc4`='红龙军团将会担负起修复世界创伤的责任与义务。回去吧，和你的同伴们一起回去，好好休息。明天，你们还要应对新的挑战，你们必须时刻为此做好准备。生命……仍要继续。', `FemaleText_loc5`='紅龍軍團將會擔負起修復世界創傷的責任與義務。回去吧，和你的同伴們一起回去，好好休息。明天，你們還要應對新的挑戰，你們必須時刻為此做好準備。生命...仍要繼續。', `FemaleText_loc7`='Vuelo del Dragón Rojo asumirá la tarea de remediar la devastación causada en Azeroth. Regresa a casa con los tuyos y descansa. Mañana te surgirán nuevos retos, y debes estar listo para enfrentarlos. La vida... continúa.' WHERE `ID`=32629;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐야?!', `MaleText_loc4`='什么？！', `MaleText_loc5`='什麼?!', `MaleText_loc7`='¿¡Qué!?', `FemaleText_loc1`='뭐지?!', `FemaleText_loc4`='什么？！', `FemaleText_loc5`='什麼?!', `FemaleText_loc7`='¿¡Qué!?' WHERE `ID`=32630;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐만, 나 아무것도 안 했는데...?', `MaleText_loc4`='等等，我没有激活宝珠啊……？', `MaleText_loc5`='等等，我還沒啟動我的...?', `MaleText_loc7`='Espera un momento... ¿No he activado mi...?', `FemaleText_loc1`='잠깐만, 나 아무것도 안 했는데...?', `FemaleText_loc4`='等等，我没有激活宝珠啊……？', `FemaleText_loc5`='等等，我還沒啟動我的...?', `FemaleText_loc7`='Espera un momento... ¿No he activado mi...?' WHERE `ID`=32631;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 야릇한 느낌은 뭐지. 으잉?!', `MaleText_loc4`='我突然觉得很好笑。呃？！', `MaleText_loc5`='我突然覺得很有趣。呃?!', `MaleText_loc7`='De repente me siento raro... ¿Eeing?', `FemaleText_loc1`='이 묘한 느낌은 뭐지. 으잉?!', `FemaleText_loc4`='我突然觉得很好笑。呃？！', `FemaleText_loc5`='我突然覺得很有趣。呃?!', `FemaleText_loc7`='De repente me siento rara... ¿Eeing?' WHERE `ID`=32632;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누구야, 어떤 겁 없는 녀석이 나한테 수정구를 던져?', `MaleText_loc4`='好吧，谁朝我扔了宝珠？', `MaleText_loc5`='好吧，誰是那個丟我寶珠的小丑?', `MaleText_loc7`='Vale, ¿quién ha sido el gracioso que me ha tirado un orbe?', `FemaleText_loc1`='누구야, 어떤 겁 없는 녀석이 나한테 수정구를 던졌지?', `FemaleText_loc4`='好吧，谁朝我扔了宝珠？', `FemaleText_loc5`='好吧，誰是那個丟我寶珠的小丑?', `FemaleText_loc7`='Vale, ¿quién ha sido el gracioso que me ha tirado un orbe?' WHERE `ID`=32633;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼애애애애!', `MaleText_loc4`='不！！！', `MaleText_loc5`='不!!', `MaleText_loc7`='¡NOOOOOO!', `FemaleText_loc1`='안 돼애애애애!', `FemaleText_loc4`='不！！！', `FemaleText_loc5`='不!!', `FemaleText_loc7`='¡NOOOOOO!' WHERE `ID`=32634;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='봐주세요, 보초병님!', `MaleText_loc4`='我不是哨兵！', `MaleText_loc5`='不要是哨衛!', `MaleText_loc7`='¡Un centinela no!', `FemaleText_loc1`='봐주세요, 보초병님!', `FemaleText_loc4`='我不是哨兵！', `FemaleText_loc5`='不要是哨衛!', `FemaleText_loc7`='¡Un centinela no!' WHERE `ID`=32635;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오해야. 나야, 나. 정복자!', `MaleText_loc4`='你搞错了。我是黑暗压制者！', `MaleText_loc5`='你全猜錯了。我是征服者!', `MaleText_loc7`='Te has equivocado por completo. ¡Soy un subyugador!', `FemaleText_loc1`='오해야. 나야, 나. 정복자!', `FemaleText_loc4`='你搞错了。我是黑暗压制者！', `FemaleText_loc5`='你全猜錯了。我是征服者!', `FemaleText_loc7`='Te has equivocado por completo. ¡Soy una subyugadora!' WHERE `ID`=32636;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 한 게 아니야. 이건 모함이라고. 제발 절 놓지 마세요!', `MaleText_loc4`='是误会啊。我是被陷害的。别把我扔下去！', `MaleText_loc5`='這是個意外。我是被陷害的。別丟下我!', `MaleText_loc7`='Fue un accidente. Me tendieron una trampa. ¡No me sueltes!', `FemaleText_loc1`='내가 한 게 아니야. 이건 모함이라고. 제발 절 놓지 마세요!', `FemaleText_loc4`='是误会啊。我是被陷害的。别把我扔下去！', `FemaleText_loc5`='這是個意外。我是被陷害的。別丟下我!', `FemaleText_loc7`='Fue un accidente. Me tendieron una trampa. ¡No me sueltes!' WHERE `ID`=32637;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|Hitem:44430|h|cff0070dd[달라란 티타늄 동전]|r|h을 가볍게 던집니다.', `MaleText_loc4`='随意抛出了|Hitem:44430|h|cff0070dd[达拉然泰坦神铁徽记]|r|h。', `MaleText_loc5`='輕鬆地擲出他的|Hitem:44430|h|cff0070dd[達拉然泰坦鋼徽印]|r|h。', `MaleText_loc7`='tira su |Hitem:44430|h|cff0070dd[Sello de titanio de Dalaran]|r|h con indiferencia.', `FemaleText_loc1`='|Hitem:44430|h|cff0070dd[달라란 티타늄 동전]|r|h을 가볍게 던집니다.', `FemaleText_loc4`='随意抛出了|Hitem:44430|h|cff0070dd[达拉然泰坦神铁徽记]|r|h。', `FemaleText_loc5`='輕鬆地擲出她的|Hitem:44430|h|cff0070dd[達拉然泰坦鋼徽印]|r|h。', `FemaleText_loc7`='tira su |Hitem:44430|h|cff0070dd[Sello de titanio de Dalaran]|r|h con indiferencia.' WHERE `ID`=32638;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 우리 일을 방해하다니!', `MaleText_loc4`='你竟敢干预我们的事！', `MaleText_loc5`='你竟敢干擾我們的工作!', `MaleText_loc7`='¡Cómo osas entrometerte en nuestra labor!' WHERE `ID`=32639;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하찮군.', `MaleText_loc4`='没用的东西。', `MaleText_loc5`='無足輕重的東西。', `MaleText_loc7`='Insignificante.' WHERE `ID`=32640;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 끝장을 내주마!', `MaleText_loc4`='你的时间流被彻底摧毁了！', `MaleText_loc5`='你的時間線已經終結了!', `MaleText_loc7`='¡Tu línea temporal ha desaparecido!' WHERE `ID`=32641;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제... 모두 끝났다...', `MaleText_loc4`='我的生命……结束了……', `MaleText_loc5`='我的時間...用完了...', `MaleText_loc7`='Mi tiempo…se ha agotado…' WHERE `ID`=32642;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 승리했다!', `MaleText_loc4`='我们胜利了！', `MaleText_loc5`='我們獲勝了!', `MaleText_loc7`='¡HEMOS VENCIDO!' WHERE `ID`=32643;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언더시티는, 다시 호드의 것이다! 록타르!', `MaleText_loc4`='部落夺回了幽暗城！LOK''TAR！', `MaleText_loc5`='幽暗城再次回歸部落了!為了部落!', `MaleText_loc7`='¡Las Entrañas vuelven a pertenecerle a la Horda! ¡LOK''TAR!' WHERE `ID`=32644;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 시간대에서 내 존재를 지켜주어서 고맙도다. 이제 나는 돌아가서 나보다 높은 이들에게 보고해야 하노라. 그들도 내가 어떤 일을 겪었는지 즉시 알아야 하기 때문이로다.', `MaleText_loc4`='你救了我的性命，请接收我的谢意。我必须立即向长官汇报这里发生的事件。', `MaleText_loc5`='我感謝你拯救了我在這條時間線的存在。我得回去向我的上級回報。他們一定得立刻知道我所經歷的事情。', `MaleText_loc7`='Te agradezco que me hayas salvado en esta línea del tiempo. Ahora, tengo que informar a mis superiores. Tienen que saber de inmediato lo que me ha pasado.' WHERE `ID`=32645;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠의 여왕이여, 나와 함께합시다! 이곳을 되찾고자 힘들게 싸우는 동안 너무나 많은 피가 흘렀소. 왕실은 그대의 것이오!', `MaleText_loc4`='黑暗女王，来吧！你曾为登上王座倾尽心力、浴血奋战。现在，皇家区属于你了！', `MaleText_loc5`='黑暗女王，加入我!你已盡全力奮戰並灑下鮮血獲此殊榮。皇家區是屬於你的!', `MaleText_loc7`='¡Dama Oscura, únete a mí! Has peleado duro y derramado mucha sangre por este derecho. ¡El Barrio Real te pertenece!' WHERE `ID`=32646;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그것이 호드의 적에게 주어진 운명이오, 대족장. 이제 비열한 퓨트리스 녀석을 상대해야 하오.', `FemaleText_loc4`='酋长，这就是与部落为敌的下场。现在，该去对付普特雷斯那个恶棍了。', `FemaleText_loc5`='這將會是所有部落之敵的下場，大酋長。現在我們要對付那個卑鄙的東西，普崔司。', `FemaleText_loc7`='Ése será el destino de todos los enemigos de la Horda, Jefe de Guerra.  Ahora debemos lidiar con el canalla, Putress.' WHERE `ID`=32647;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맞는 말이오, 실바나스...', `MaleText_loc4`='我们会的，希尔瓦娜斯……', `MaleText_loc5`='沒錯，希瓦娜斯...', `MaleText_loc7`='Así se hará, Sylvanas…' WHERE `ID`=32648;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스인가? 경계를 늦추지 마라!', `MaleText_loc4`='联盟的号角声？保持警惕！', `MaleText_loc5`='聯盟的號角聲?提高戒備!', `MaleText_loc7`='¿Cuernos de la Alianza? ¡Mantengan la guardia!' WHERE `ID`=32649;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달라란 북쪽에 있는 한 잔 더 상점에서 원하는 물건을 찾을 수 있을 겁니다.', `MaleText_loc4`='达拉然北部的再来一杯应该能满足你的需求。', `MaleText_loc5`='你可以在達拉然北區的「勸君更進一杯酒」找到你要的東西。', `MaleText_loc7`='Encontrarás lo que buscas en Una Copa Más en la zona norte de Dalaran.', `FemaleText_loc1`='달라란 북쪽에 있는 한 잔 더 상점에서 원하는 물건을 찾을 수 있을 겁니다.', `FemaleText_loc4`='达拉然北部的再来一杯应该能满足你的需求。', `FemaleText_loc5`='你可以在達拉然北區的「勸君更進一杯酒」找到你要的東西。', `FemaleText_loc7`='Encontrarás lo que buscas en Una Copa Más en la zona norte de Dalaran.' WHERE `ID`=32650;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달라란 남쪽, 신비스러운 투사의 무기점에서 원하는 물건을 구입하실 수 있을 겁니다.', `MaleText_loc4`='达拉然南部的好战的秘法师应该能满足你的需求。', `MaleText_loc5`='達拉然南區的軍事狂秘術店應該有你想要的東西。', `MaleText_loc7`='En El Místico Militante en la zona sureste de Dalaran puede que tengan lo que deseas.', `FemaleText_loc1`='달라란 남쪽, 신비스러운 투사의 무기점에서 원하는 물건을 구입하실 수 있을 겁니다.', `FemaleText_loc4`='达拉然南部的好战的秘法师应该能满足你的需求。', `FemaleText_loc5`='達拉然南區的軍事狂秘術店應該有你想要的東西。', `FemaleText_loc7`='En El Místico Militante en la zona sureste de Dalaran puede que tengan lo que deseas.' WHERE `ID`=32651;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달라란 동쪽, 사냥꾼의 활시위에서 총, 활, 탄약과 같은 물건들을 구입할 수 있습니다.', `MaleText_loc4`='达拉然东部的猎人用品店出售枪支、弓弩、弹药等商品。', `MaleText_loc5`='達拉然東區的獵人地帶販賣各種槍械、弓箭、彈藥和其他相關商品。', `MaleText_loc7`='En el Tramo del Cazador en la zona este de Dalaran venden armas de fuego, arcos, municiones y cosas del estilo.', `FemaleText_loc1`='달라란 동쪽, 사냥꾼의 활시위에서 총, 활, 탄약과 같은 물건들을 구입할 수 있습니다.', `FemaleText_loc4`='达拉然东部的猎人用品店出售枪支、弓弩、弹药等商品。', `FemaleText_loc5`='達拉然東區的獵人地帶販賣各種槍械、弓箭、彈藥和其他相關商品。', `FemaleText_loc7`='En el Tramo del Cazador en la zona este de Dalaran venden armas de fuego, arcos, municiones y cosas del estilo.' WHERE `ID`=32652;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달라란 남동쪽, 절대무기에서 모든 종류의 근접 무기를 보실 수 있습니다.', `MaleText_loc4`='达拉然东南部的神兵利器出售各类近战武器。', `MaleText_loc5`='達拉然東南的完全軍械庫有著各式各樣的近戰武器。', `MaleText_loc7`='En el Arsenal Absoluto en la zona sureste de Dalaran encontrarás todo tipo de armas de combate cuerpo a cuerpo.', `FemaleText_loc1`='달라란 남동쪽, 절대무기에서 모든 종류의 근접 무기를 보실 수 있습니다.', `FemaleText_loc4`='达拉然东南部的神兵利器出售各类近战武器。', `FemaleText_loc5`='達拉然東南的完全軍械庫有著各式各樣的近戰武器。', `FemaleText_loc7`='En el Arsenal Absoluto en la zona sureste de Dalaran encontrarás todo tipo de armas de combate cuerpo a cuerpo.' WHERE `ID`=32653;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 이 사슬에서 자유로워지면, 언젠가 돌아와서 내 손으로 널 죽이겠다.', `MaleText_loc4`='如果能挣脱这些锁链，总有一天我会回来亲手杀了你。', `MaleText_loc5`='如果有天我能掙脫這些枷鎖，我會回來並且親手殺了你。', `MaleText_loc7`='Si llego a liberarme de estas cadenas algún día, volveré y te mataré con mis propias manos.' WHERE `ID`=32654;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 녀석의 머리를 내 발 뒤꿈치로 박살냈을 때 내가 느낄 만족감에 비길만한 건 없을 거다.', `MaleText_loc4`='击败你是我莫大的享受。', `MaleText_loc5`='什麼也比不上等我踩碎你頭顱所帶來的滿足感。', `MaleText_loc7`='Esto no será nada comparado con la satisfacción que sentiré cuando aplaste tu cráneo con mi tacón.' WHERE `ID`=32655;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달라란 서쪽에 있는 제페토 조이버즈의 신기한 장난감 상점에서 장난감류를 확인할 수 있습니다.', `MaleText_loc4`='达拉然西部的耶比托·乔巴斯的奇妙玩具店会出售这类物品。', `MaleText_loc5`='杰佩托·樂吱在達拉然西區的神奇玩具屋應該有這些東西。', `MaleText_loc7`='Las Obras Asombrosas de Jepetto Jugarreta en la zona oeste de Dalaran tiene este tipo de objetos.', `FemaleText_loc1`='달라란 서쪽에 있는 제페토 조이버즈의 신기한 장난감 상점에서 장난감류를 확인할 수 있습니다.', `FemaleText_loc4`='达拉然西部的耶比托·乔巴斯的奇妙玩具店会出售这类物品。', `FemaleText_loc5`='杰佩托·樂吱在達拉然西區的神奇玩具屋應該有這些東西。', `FemaleText_loc7`='Las Obras Asombrosas de Jepetto Jugarreta en la zona oeste de Dalaran tiene este tipo de objetos.' WHERE `ID`=32656;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 처량한 소환수가 되느니 어둠의 제왕 알렉산더를 모시겠다.', `MaleText_loc4`='我宁愿为黑暗领主亚历山大效劳，也不要待在你身边做只可怜的宠物。', `MaleText_loc5`='我寧願去服侍黑暗領主亞歷山大，而不是當你的可悲寵物。', `MaleText_loc7`='Antes serviría al siniestro Lord Alexander que ser tu lamentable mascota.' WHERE `ID`=32657;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지옥사냥개가 불 위에서 산 체로 구워질 때처럼 네 비명을 들으리라.', `MaleText_loc4`='我听说，如果将你这样的家伙扔进火里，你就会发出地狱犬一般的尖叫声。', `MaleText_loc5`='我覺得你的同類尖叫起來很像是活烤惡魔獵犬。', `MaleText_loc7`='He oído a tu gente chillar como un manáfago quemado vido en una hoguera.' WHERE `ID`=32658;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 암흑 마법을 너무 깊숙이 파고들었다. 내 영혼을 내 것으로 삼으리라!', `MaleText_loc4`='你过于沉迷我们的魔法。我要亲手夺走你的灵魂！', `MaleText_loc5`='你對我們的魔法鑽研過深了。我會親自取走你的靈魂!', `MaleText_loc7`='Ha descubierto tanto sobre nuestras magias… ¡Yo reclamaré tu alma!' WHERE `ID`=32659;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 음악은 무조건 거꾸로 듣지. 애로우스미트 건 빼고 말이야.', `MaleText_loc4`='所有的录音带，我都倒着放。除了“箭头小子”乐队的。', `MaleText_loc5`='我把我所有的唱片都倒著聽。除了史密斯箭頭的唱片之外。', `MaleText_loc7`='Pongo todos mis temas al revés. Excepto los de Bufasmante.' WHERE `ID`=32660;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 뒤틀린 황천의 가장 차가운 곳에 숨어도 네 복수의 손길을 벗어나지 못할 거다.', `MaleText_loc4`='就算你逃到扭曲虚空最寒冷的边缘，也躲不过我复仇的怒火。', `MaleText_loc5`='扭曲虛空最寒冷的地方也沒辦法讓你逃過我的復仇。', `MaleText_loc7`='Los tramos más fríos de El Vacío Abisal no te esconderán de mi venganza.' WHERE `ID`=32661;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 살게라스 님만을 위해 일한다! 필멸의 존재여, 너도 언젠가 그분의 수하에 들어야 할 것이다.', `MaleText_loc4`='我只为萨格拉斯效劳！总有一天你也会臣服在他的权威之下，凡人……', `MaleText_loc5`='我只服侍薩格拉斯!有天你也會加入他，凡人...', `MaleText_loc7`='¡Solo sirvo a Sargeras! Deberías unirte a él un día, mortal…' WHERE `ID`=32662;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동전의 앞면이 나오게 잡았습니다!', `MaleText_loc4`='硬币正面朝上！', `MaleText_loc5`='人頭!', `MaleText_loc7`='atrapa la moneda cara arriba.', `FemaleText_loc1`='동전의 앞면이 나오게 잡았습니다!', `FemaleText_loc4`='硬币正面朝上！', `FemaleText_loc5`='人頭!', `FemaleText_loc7`='atrapa la moneda cara arriba.' WHERE `ID`=32663;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동전을 잡으니 뒷면이 나왔습니다!', `MaleText_loc4`='硬币反面朝上！', `MaleText_loc5`='字!', `MaleText_loc7`='encuentra la moneda por el lado de la cruz.', `FemaleText_loc1`='동전을 잡으니 뒷면이 나왔습니다!', `FemaleText_loc4`='硬币反面朝上！', `FemaleText_loc5`='字!', `FemaleText_loc7`='encuentra la moneda por el lado de la cruz.' WHERE `ID`=32664;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달라란 남동쪽, 영광의 일용품점에 있는 빨간머리가 대부분의 직업용품을 제공합니다.$B$B좀 더 특수한 물건을 찾으신다면, 마법사 교역소로 가보시는 게 좋습니다. 그곳에 있는 보급품 상인들을 만나 보십시오.', `MaleText_loc4`='达拉然东南部的荣耀杂货店中，“红发”杰克·芬德出售各种杂货。$B$B如果你想购买特殊物品，就去魔法商业区吧。那里的店铺都设有供给商贩。', `MaleText_loc5`='達拉然東南的輝煌商品提供大多數的一般交易補給品。$B$B如果你要找更特殊一點，可以去魔導師貿易區試試。那邊的每家店鋪都有自己的供應商。', `MaleText_loc7`='En Objetos Gloriosos de Red en la zona sureste de Dalaran podrás conseguir la mayoría de los suministros comerciales generales.$B$BSi necesitas algo más especializado, prueba en el Mercado de Magos. Allí cada tienda tiene su propio vendedor.', `FemaleText_loc1`='달라란 남동쪽, 영광의 일용품점에 있는 빨간머리가 대부분의 직업용품을 제공합니다.$B$B좀 더 특수한 물건을 찾으신다면, 마법사 교역소로 가보시는 게 좋습니다. 그곳에 있는 보급품 상인들을 만나 보십시오.', `FemaleText_loc4`='达拉然东南部的荣耀杂货店中，“红发”杰克·芬德出售各种杂货。$B$B如果你想购买特殊物品，就去魔法商业区吧。那里的店铺都设有供给商贩。', `FemaleText_loc5`='達拉然東南的輝煌商品提供大多數的一般交易補給品。$B$B如果你要找更特殊一點，可以去魔導師貿易區試試。那邊的每家店鋪都有自己的供應商。', `FemaleText_loc7`='En Objetos Gloriosos de Red en la zona sureste de Dalaran podrás conseguir la mayoría de los suministros comerciales generales.$B$BSi necesitas algo más especializado, prueba en el Mercado de Magos. Allí cada tienda tiene su propio vendedor.' WHERE `ID`=32665;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모든 과정이 끝났다! 내 일은 여기서 끝이다.', `MaleText_loc4`='任务完成！我在这里的工作结束了。', `MaleText_loc5`='終於完成!我在此的工作完結了!', `MaleText_loc7`='¡El proceso se ha completado al fin! Mi trabajo aquí está hecho.' WHERE `ID`=32666;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달라란 북쪽, 달라란 은행 근처에서 에이미의 가게를 찾을 수 있습니다.', `MaleText_loc4`='艾美的货车通常停在达拉然北部，就在达拉然银行附近。', `MaleText_loc5`='你通常可以在達拉然北區找到安咪的手推車，靠近達拉然銀行那邊。', `MaleText_loc7`='La vagoneta de Aimee suele estar en la zona norte de Dalaran, cerca de El Banco de Dalaran.', `FemaleText_loc1`='달라란 북쪽, 달라란 은행 근처에서 에이미의 가게를 찾을 수 있습니다.', `FemaleText_loc4`='艾美的货车通常停在达拉然北部，就在达拉然银行附近。', `FemaleText_loc5`='你通常可以在達拉然北區找到安咪的手推車，靠近達拉然銀行那邊。', `FemaleText_loc7`='La vagoneta de Aimee suele estar en la zona norte de Dalaran, cerca de El Banco de Dalaran.' WHERE `ID`=32667;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달라란 북동쪽에 마법 동물원이 있습니다. 소환수용품, 희귀 탈것과 야수 관리인이 모두 그곳에 있답니다.', `MaleText_loc4`='魔法动物店位于达拉然东北部。那里出售宠物用品和珍稀坐骑，并提供兽栏服务。', `MaleText_loc5`='魔法動物園就在達拉然東北。寵物商人，奇特坐騎還有獸欄，應有盡有。', `MaleText_loc7`='El Arca Mágica está en la zona noreste de Dalaran. Tienen suministros para mascotas, monturas exóticas y establos.', `FemaleText_loc1`='달라란 북동쪽에 마법 동물원이 있습니다. 소환수용품, 희귀 탈것과 야수 관리인이 모두 그곳에 있답니다.', `FemaleText_loc4`='魔法动物店位于达拉然东北部。那里出售宠物用品和珍稀坐骑，并提供兽栏服务。', `FemaleText_loc5`='魔法動物園就在達拉然東北。寵物商人，奇特坐騎還有獸欄，應有盡有。', `FemaleText_loc7`='El Arca Mágica está en la zona noreste de Dalaran. Tienen suministros para mascotas, monturas exóticas y establos.' WHERE `ID`=32668;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달라란 서쪽, 자매 마술사에서 마법 재료와 다른 물건들을 구입할 수 있습니다.$B$B무어헤드의 검은 고양이만 조심하세요...', `MaleText_loc4`='达拉然西部的巫术姐妹出售各种魔法材料。$B$B不过你要小心莫尔海德的那只黑猫……', `MaleText_loc5`='你可以在巫術姊妹找到試劑與材料，就在達拉然的西區。$B$B只是要留意莫爾海德姊妹的黑貓...', `MaleText_loc7`='Encontrarás componentes y más cosas en Hermanas hechiceras en la zona oeste de Dalaran.$B$BSolo fíjate en el gato negro de Cadabra…', `FemaleText_loc1`='달라란 서쪽, 자매 마술사에서 마법 재료와 다른 물건들을 구입할 수 있습니다.$B$B무어헤드의 검은 고양이만 조심하세요...', `FemaleText_loc4`='达拉然西部的巫术姐妹出售各种魔法材料。$B$B不过你要小心莫尔海德的那只黑猫……', `FemaleText_loc5`='你可以在巫術姊妹找到試劑與材料，就在達拉然的西區。$B$B只是要留意莫爾海德姊妹的黑貓...', `FemaleText_loc7`='Encontrarás componentes y más cosas en Hermanas hechiceras en la zona oeste de Dalaran.$B$BSolo fíjate en el gato negro de Cadabra…' WHERE `ID`=32669;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안 돼! 뭔가 무서운 일이 벌어졌어요! 무한의 용군단이 제 동료 하나를 사로잡아 끔찍한 짓을 하려고 해요!$B$B아서스와 함께하는 게 당신이 해야 할 가장 중요한 일이지만, 재빠르게 행동할 수 있다면 시간의 수호자도 구할 수 있어요!', `FemaleText_loc4`='噢，不！冒险者们，刚刚发生了一件可怕的事！永恒之龙抓走了我的一位同伴，他们正在对他做一些可怕的事！$B$B保护阿尔萨斯还是你们的首要任务。但是如果你们行动够快的话，或许还有机会挽救一位时光守护者！', `FemaleText_loc5`='喔，不!冒險者們，發生了一件糟糕的事情!我的一位同僚被恆龍軍團抓住了，他們正對他進行可怕的事情!$B$B保護阿薩斯的安全依舊是你們的首要目標，但如果你們動作夠快，或許能拯救一位時光守護者!', `FemaleText_loc7`='¡Oh, no! ¡Aventureros, algo terrible ha sucedido! ¡El Vuelo Infinito ha capturado a un compañero mío y le están haciendo algo horrible!$B$BTu prioridad sigue siendo ocuparte de Arthas pero si sois rápidos podríais salvar a un Guardián del Tiempo.' WHERE `ID`=32670;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달라란 남쪽, 영광의 일용품점에서 당신에게 필요한 일용품 상인을 만날 수 있습니다.', `MaleText_loc4`='达拉然南部的荣耀杂货店出售各种杂货。', `MaleText_loc5`='達拉然南區的輝煌商品應該可以提供你所需要的一般雜貨。', `MaleText_loc7`='Objetos Gloriosos en la zona sur de Dalaran debería tener todos los víveres que necesitas.', `FemaleText_loc1`='달라란 남쪽, 영광의 일용품점에서 당신에게 필요한 일용품 상인을 만날 수 있습니다.', `FemaleText_loc4`='达拉然南部的荣耀杂货店出售各种杂货。', `FemaleText_loc5`='達拉然南區的輝煌商品應該可以提供你所需要的一般雜貨。', `FemaleText_loc7`='Objetos Gloriosos en la zona sur de Dalaran debería tener todos los víveres que necesitas.' WHERE `ID`=32671;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달라란 남서쪽, 은빛 자치구 근처에서 왕사과라는 과일 상인을 만날 수 있습니다.', `MaleText_loc4`='苹果树的水果货车通常停在达拉然的西南部，就在银色领地附近。', `MaleText_loc5`='蘋果樹枝的水果推車通常會在達拉然西南，靠近白銀領區。', `MaleText_loc7`='La vagoneta de fruta de Ramanzano suele estar en la zona suroeste de Dalaran, cerca del Enclave de Plata.', `FemaleText_loc1`='달라란 남서쪽, 은빛 자치구 근처에서 왕사과라는 과일 상인을 만날 수 있습니다.', `FemaleText_loc4`='苹果树的水果货车通常都停在达拉然的西南部，靠近Silver Enclave的地方。', `FemaleText_loc5`='蘋果樹枝的水果推車通常會在達拉然西南，靠近白銀領區。', `FemaleText_loc7`='La vagoneta de fruta de Ramanzano suele estar en la zona suroeste de Dalaran, cerca del Enclave de Plata.' WHERE `ID`=32672;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달라란 남동쪽에 있는 프림로즈 양의 꽃 상점에서 꽃을 찾을 수 있을 겁니다.', `MaleText_loc4`='你可以在达拉然东南部找到爱丽丝·普里洛斯小姐的花摊。', `MaleText_loc5`='你通常可以在達拉然東南找到櫻草小姐的花攤。', `MaleText_loc7`='Normalmente puedes encontrar a el puesto de flores de la señorita Prímula en la zona sureste de Dalaran.', `FemaleText_loc1`='달라란 남동쪽에 있는 프림로즈 양의 꽃 상점에서 꽃을 찾을 수 있을 겁니다.', `FemaleText_loc4`='你可以在达拉然东南部找到爱丽丝·普里洛斯小姐的花摊。', `FemaleText_loc5`='你通常可以在達拉然東南找到櫻草小姐的花攤。', `FemaleText_loc7`='Normalmente puedes encontrar a el puesto de flores de la señorita Prímula en la zona sureste de Dalaran.' WHERE `ID`=32673;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모험가들은 은빛 자치구나 선리버 성소에서 정의로운 업적을 보상받을 수 있습니다.', `MaleText_loc4`='冒险者可以在银色领地或者夺日者圣殿为自己立下的功绩领取公正的奖励。', `MaleText_loc5`='冒險者可以在白銀領區或奪日者聖堂為他們的功績領取獎勵。', `MaleText_loc7`='Los aventureros pueden recibir recompensas por sus justas hazañas en El Enclave de Plata o en el Santuario Atracasol.', `FemaleText_loc1`='모험가들은 은빛 자치구나 선리버 성소에서 정의로운 업적을 보상받을 수 있답니다.', `FemaleText_loc4`='冒险者可以在银色领地或者夺日者圣殿为自己立下的功绩领取公正的奖励。', `FemaleText_loc5`='冒險者可以在白銀領區或奪日者聖堂為他們的功績領取獎勵。', `FemaleText_loc7`='Los aventureros pueden recibir recompensas por sus justas hazañas en El Enclave de Plata o en el Santuario Atracasol.' WHERE `ID`=32674;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='북부 달라란에 있는 무적의 방어구 상점은 이 도시에서 가장 유명한 판금 방어구와 방패 상점입니다.', `MaleText_loc4`='达拉然北部的坦克用品店是城里最受欢迎的板甲和盾牌商店。', `MaleText_loc5`='萬物皆可坦就在達拉然北區，是城中最受歡迎的鎧甲與盾牌商。', `MaleText_loc7`='¡En Tanques para todo en la zona norte de Dalaran está el mercader de escudos y armaduras de placas más famoso de la ciudad!', `FemaleText_loc1`='북부 달라란에 있는 무적의 방어구 상점은 이 도시에서 가장 유명한 판금 방어구와 방패 상점이지요.', `FemaleText_loc4`='达拉然北部的坦克用品店是城里最受欢迎的板甲和盾牌商店。', `FemaleText_loc5`='萬物皆可坦就在達拉然北區，是城中最受歡迎的鎧甲與盾牌商。', `FemaleText_loc7`='¡En Tanques para todo en la zona norte de Dalaran está el mercader de escudos y armaduras de placas más famoso de la ciudad!' WHERE `ID`=32675;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달라란 남쪽, 무어의 골동품점에 있는 여러 상인들이 모든 종류의 장신구, 유물, 계승품, 보조무기를 팝니다.', `MaleText_loc4`='达拉然南部的摩尔珍品店有好几位商贩，他们出售各类饰品、圣物、家传宝物和副手武器。', `MaleText_loc5`='在達拉然南區的「不只是配件」有許多商人販賣飾品、聖物、家傳物品或副手物品。', `MaleText_loc7`='Los diferentes mercaderes de Curiosidades y Más de la zona sur de Dalaran venden abalorios, reliquias y todo tipo de objetos de mano izquierda.', `FemaleText_loc1`='달라란 남쪽, 무어의 골동품점에 있는 여러 상인들이 모든 종류의 장신구, 유물, 계승품, 보조무기를 팝니다.', `FemaleText_loc4`='达拉然南部的摩尔珍品店有好几位商贩，他们出售各类饰品、圣物、家传宝物和副手武器。', `FemaleText_loc5`='在達拉然南區的「不只是配件」有許多商人販賣飾品、聖物、家傳物品或副手物品。', `FemaleText_loc7`='Los diferentes mercaderes de Curiosidades y Más de la zona sur de Dalaran venden abalorios, reliquias y todo tipo de objetos de mano izquierda.' WHERE `ID`=32676;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달라란 남쪽에 있는 랭롬의 가죽 및 사슬 방어구 상점이 찾으시는 곳이랍니다.', `MaleText_loc4`='达拉然南部的兰格鲁的皮加锁应该能满足你的需求。', `MaleText_loc5`='朗格姆的皮甲與鍊甲就在達拉然南區，應該會有你要的東西。', `MaleText_loc7`='En Cuero y Eslabones de Langrom en la zona sur de Dalaran deberías tener lo que buscas.', `FemaleText_loc1`='달라란 남쪽에 있는 랭롬의 가죽 및 사슬 방어구 상점이 찾으시는 곳이랍니다.', `FemaleText_loc4`='达拉然南部的兰格鲁的皮加锁应该能满足你的需求。', `FemaleText_loc5`='朗格姆的皮甲與鍊甲就在達拉然南區，應該會有你要的東西。', `FemaleText_loc7`='En Cuero y Eslabones de Langrom en la zona sur de Dalaran deberías tener lo que buscas.' WHERE `ID`=32677;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='모험가들이여, 서두르세요! 시간의 수호자가 버틸 수 있는 시간이 얼마 남지 않았어요!', `FemaleText_loc4`='冒险者，快！时间的守护者坚持不了多久的！', `FemaleText_loc5`='冒險者們，你們動作要快!時光守護者撐不了多久了!', `FemaleText_loc7`='¡Aventureros, aprisa! El Guardián del Tiempo no aguantará mucho más.' WHERE `ID`=32678;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='시간의 수호자의 존재가 희미하게 느껴져요. 그의 생명이 빠르게 빛을 잃고 있어요!', `FemaleText_loc4`='我几乎感受不到时间的守护者的讯息！他的时间流正在急速消逝！', `FemaleText_loc5`='我快要感應不到時光守護者了!他的時間線正在快速消逝!', `FemaleText_loc7`='¡A penas puedo sentir al Guardián del Tiempo! ¡Su línea del tiempo se desvanece rápidamente!' WHERE `ID`=32679;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달라란 서쪽에 있는 운명의 실타래에는 달라란에서 가장 유명한 재봉용품 상인과 천 방어구 상인이 있습니다.', `MaleText_loc4`='达拉然西部的命运丝线是城里最受欢迎的裁缝物品和布甲商店。', `MaleText_loc5`='達拉然西區的命運織坊是城中最受歡迎的服裝與布甲商。', `MaleText_loc7`='Los Hilos del Destino en la zona oeste de Dalaran es el suministrador más famoso de ropa y armaduras de tela.', `FemaleText_loc1`='달라란 서쪽에 있는 운명의 실타래에는 달라란에서 가장 유명한 재봉용품 상인과 천 방어구 상인이 있습니다.', `FemaleText_loc4`='达拉然西部的命运丝线是城里最受欢迎的裁缝物品和布甲商店。', `FemaleText_loc5`='達拉然西區的命運織坊是城中最受歡迎的服裝與布甲商。', `FemaleText_loc7`='Los Hilos del Destino en la zona oeste de Dalaran es el suministrador más famoso de ropa y armaduras de tela.' WHERE `ID`=32680;
