UPDATE `locales_broadcast_text` SET `MaleText_loc1`='티리온 님이 쓰러지셨다! 목숨을 걸고 보호하라!', `MaleText_loc4`='提里奥倒下了！用你们的生命保护他！', `MaleText_loc5`='提里奧倒下了!用你們的生命保護他!', `MaleText_loc7`='¡Tirion ha caído! ¡Defiéndanlo con sus vidas!', `FemaleText_loc1`='티리온 님이 쓰러지셨다! 목숨을 걸고 보호하라!', `FemaleText_loc4`='提里奥倒下了！用你们的生命保护他！', `FemaleText_loc5`='提里奧倒下了!用你們的生命保護他!', `FemaleText_loc7`='¡Tirion ha caído! ¡Defiéndanlo con sus vidas!' WHERE `ID`=32687;
