UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 오랫동안 자리를 비운 모양이군... 내가 없는 동안 위대한 영웅들이 목숨을 잃었다. 네놈이나 이 사악한 마녀같은 쓰레기가 아무런 제재도 없이 활개를 치고 다니다니...', `MaleText_loc4`='我离开得太久了。好几位伟大的英雄为此付出了生命的代价。而你这种人渣，还有这个邪恶的巫女却还在世上，为所欲为。', `MaleText_loc5`='我離開太久了。我的缺席造成了我們許多偉大英雄的喪生，並且放任像你這樣的廢物還有那個惡毒女巫四處橫行。', `MaleText_loc7`='Estuve ausente demasiado tiempo. Mi ausencia se pagó con la vida de algunos de nuestros más grandes héroes. Basuras como tú y esta bruja maldita anduvieron libres... Sin control.' WHERE `ID`=32691;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방패 상인', `MaleText_loc4`='盾牌', `MaleText_loc5`='盾牌', `MaleText_loc7`='Escudos', `FemaleText_loc1`='방패 상인', `FemaleText_loc4`='盾牌', `FemaleText_loc5`='盾牌', `FemaleText_loc7`='Escudos' WHERE `ID`=32692;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모든 것을 바로잡을 시간이 왔다. 살인자와 도둑이 득실거리는 너희 배신의 왕국을 무너뜨리고 말겠다. 퓨트리스는 시작일 뿐이었다. 그런 놈들이 더 많이 올 테지.', `MaleText_loc4`='匡扶正义的时刻到了。我要摧毁这个满是凶手和窃贼的王国！普特雷斯只是个开始。好戏刚刚开始！', `MaleText_loc5`='該是撥亂反正的時候了。解散你那由兇手與竊賊所組成的卑劣王國吧。普崔司的突襲只是個開端，其他的制裁將接踵而來。', `MaleText_loc7`='Pero llegó el momento de arreglar las cosas. Desbandar su pérfido reino de asesinos y ladrones. Putress fue el primer ataque. Muchos más vendrán.' WHERE `ID`=32693;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아아아아아아아악!!!!', `MaleText_loc4`='啊啊啊！！！', `MaleText_loc5`='哦啊啊啊啊啊啊啊啊啊!!!', `MaleText_loc7`='¡¡¡Arrrrggggggggggh!!!' WHERE `ID`=32694;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실력 발휘하러 왔는가?', `MaleText_loc4`='你是来帮忙的吗？', `MaleText_loc5`='來讓你自己有點用處?', `MaleText_loc7`='¿Vienes para ayudarnos en algo?' WHERE `ID`=32695;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실력 발휘하러 왔는가?', `MaleText_loc4`='你是来帮忙的吗？', `MaleText_loc5`='來讓你自己有點用處?', `MaleText_loc7`='¿Vienes para ayudarnos en algo?' WHERE `ID`=32696;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 순간을 오랫동안 기다렸다, 스랄. 그 저주받은 투기장에 내던져질 때마다... 너 같은 녹색 피부의 괴물을 해치울 때마다... 오로지 한 가지 생각밖에 없었다.', `MaleText_loc4`='这一刻我等了很久，萨尔。每当我被扔进你那该死的兽人竞技场……每当我杀死一只和你一样可憎的绿皮怪物……我都只有一个念头。', `MaleText_loc5`='我等了很久，索爾。每當我被丟入你們那該死的競技場...每當我殺死像你那樣的綠皮怪物時...我只想著一件事。', `MaleText_loc7`='He esperado mucho tiempo por esto, Thrall. Cada vez que fui arrojado en una de tus malditas arenas... Cada vez que maté a una aberración de piel verde como tú... Sólo pensaba en una cosa.' WHERE `ID`=32697;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 늙은이가 감히... 반드시 이 대가를 치르게 해 주마. 모조리 없애 버려!', `MaleText_loc4`='你……会为此付出代价！杀光他们！', `MaleText_loc5`='你...你會付出代價的，老鬼。殺光他們所有人!', `MaleText_loc7`='Tú… pagarás por eso, viejo. ¡Matadlos a todos!' WHERE `ID`=32698;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너와, 그 비뚤어진 호드만 없다면 이 세상이 얼마나 좋아질까... 이제 끝이다, 대족장.', `MaleText_loc4`='如果没有你和你那扭曲的部落，世界将多么美好……酋长，你们要完蛋了。', `MaleText_loc5`='要是我們的世界沒有你和你那心智扭曲的部落...讓我們了斷這一切，大酋長。', `MaleText_loc7`='Lo que podría ser nuestro mundo sin ti y tu malévola Horda... Esto se termina ahora, Jefe de guerra.' WHERE `ID`=32699;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공격! 스톰윈드를 위해! 볼바르를 위해! 얼라이언스를 위해!', `MaleText_loc4`='进攻！为了暴风城！为了伯瓦尔！为了联盟！', `MaleText_loc5`='進攻!為了暴風城!為了伯瓦爾!為了聯盟!', `MaleText_loc7`='¡ATAQUEN! ¡POR VENTORMENTA! ¡POR BOLVAR! ¡POR LA ALIANZA!' WHERE `ID`=32700;
