UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서둘러! 차원문으로 들어가라! 리치 왕은 금방 다시 일어날 것이다.', `MaleText_loc4`='快穿过传送门！他坚持不了多久的。', `MaleText_loc5`='快，穿過傳送門!他不會停留太久。', `MaleText_loc7`='¡Rápido, hacia el portal! ¡No tardará en levantarse!' WHERE `ID`=32707;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='십자군이여 용기를 가지십시오. 우리가 왔습니다!', `MaleText_loc4`='振作起来，北伐军战士。你们并非孤军奋战！', `MaleText_loc5`='鼓起勇氣，十字軍。你們並非孤身奮戰!', `MaleText_loc7`='¡Ánimo, cruzados! ¡No lucháis solos!' WHERE `ID`=32708;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='폐하, 안 돼요! 멈추세요!', `FemaleText_loc4`='不，瓦里安！住手！', `FemaleText_loc5`='瓦里安，不!住手!', `FemaleText_loc7`='¡VARIAN, NO! ¡DETENTE!' WHERE `ID`=32709;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희가 여기 끼어들어도 괜찮은지 모르겠군요. 오랜 친구들을 몇 명 데려왔습니다!', `MaleText_loc4`='我们打扰了你们的聚会，请不要介意。我还带来了一些老朋友！', `MaleText_loc5`='希望你們不會介意我們闖入了這場派對。我帶了些老朋友一起來!', `MaleText_loc7`='Hermanos, espero que no os importe que nos colemos en esta fiesta. Tengo conmigo a viejos amigos.' WHERE `ID`=32710;
