UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정확히는 모르겠지만 티리온이 리치 왕에게 상당한 상처를 입힌 것 같소. 리치 왕을 끝장내지 못한 게 너무 안타까울 뿐이오...', `MaleText_loc4`='看来提里奥的确对巫妖王造成了一定伤害。可惜我们不能杀死他……', `MaleText_loc5`='看來提里奧真的對巫妖王造成了一些傷害。可惜我們被辦法解決他...', `MaleText_loc7`='Parece que cualquier cosa que hiciese Tirion heriría al Rey Exánime. Es tan malo que no podemos acabar con él.' WHERE `ID`=32722;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='식료품점', `MaleText_loc4`='美酒和奶酪', `MaleText_loc5`='葡萄酒與起司', `MaleText_loc7`='Vinos y quesos', `FemaleText_loc1`='식료품점', `FemaleText_loc4`='美酒和奶酪', `FemaleText_loc5`='葡萄酒與起司', `FemaleText_loc7`='Vinos y quesos' WHERE `ID`=32723;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상인', `MaleText_loc4`='商人', `MaleText_loc5`='商人', `MaleText_loc7`='Vendedor', `FemaleText_loc1`='상인', `FemaleText_loc4`='商人', `FemaleText_loc5`='商人', `FemaleText_loc7`='Vendedor' WHERE `ID`=32724;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕이 큰 부상을 입었습니다. 남아서 그를 확실히 제거해야 합니다.', `MaleText_loc4`='巫妖王受了重伤。我们应该留下来杀死他。', `MaleText_loc5`='巫妖王受到了重創。我們應該追上去並且終結他。', `MaleText_loc7`='El Rey Exánime está mal herido.' WHERE `ID`=32725;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='참아라... 곧 좋은 기회가 다시 있을 것이다. 이번에는 티리온이 우리에게 갚을 빚이 생겼다는 것으로 만족하자.', `MaleText_loc4`='耐心点……我们会有机会干掉巫妖王的。这次，提里奥欠我们一份情。对此我已经很满足了。', `MaleText_loc5`='耐心...我們很快就會有機會的。這次我們應該要心滿意足了，我們又欠了提里奧一份情。', `MaleText_loc7`='Paciencia… pronto tendremos nuestra oportunidad. Alégrate de que por una vez es Tirion el que está en deuda con nosotros.' WHERE `ID`=32726;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고블린 기계공학의 핵심은 무조건 터뜨리고 보는 거야. 원하는 곳에서 펑펑 터지도록 하는 게 바로 우리의 장기라고.', `MaleText_loc4`='地精工程学的奥秘是，教你学会如何让爆炸物在指定的地点按时引爆，而不是确保产品不会爆炸。', `MaleText_loc5`='哥布林工程學的奧秘可不是防止物體爆炸，而是將爆炸正確地導向你所要的位置。', `MaleText_loc7`='El secreto de la ingeniería goblin no tiene nada que ver con hacer explotar cosas. Tiene que ver con que las cosas exploten exactamente donde uno quiere.' WHERE `ID`=32727;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시작했을 때처럼 끝이 나는군...', `MaleText_loc4`='结局仿佛只是开始……', `MaleText_loc5`='到頭來又回到原點...', `MaleText_loc7`='Termina como empezó…' WHERE `ID`=32728;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금껏 이 세계에서 싸워 온 모든 이유를 잃었다. 아버지와 어머니... 그리고 둠해머가 품었던... 희망과 꿈이... 사라졌구나...', `MaleText_loc4`='我们追寻的梦想破灭了。我的双亲……还有奥格瑞姆……他们的期望和梦想……破灭了……', `MaleText_loc5`='我們為這個世界所做的一切努力都白費了。我父親與母親所抱持的希望與夢想...末日錘的夢想...全沒了...', `MaleText_loc7`='Todo por lo que hemos peleado en este mundo se perdió. Las esperanzas y sueños de mi padre y mi madre... Por Martillo Maldito... Perdido…' WHERE `ID`=32729;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오랜 친구여, 그대가 있었다면 내가 어찌해야 하는지 알려 줬을 텐데.', `MaleText_loc4`='老朋友，如果你在这里就好了。你该知道要怎么做。', `MaleText_loc5`='如果你現在在這兒，老朋友。你一定知道該怎麼辦。', `MaleText_loc7`='Si tan sólo estuvieras aquí, viejo amigo. Tú sabrías qué hacer.' WHERE `ID`=32730;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그분이 뭐라고 하셨을진 압니다.', `MaleText_loc4`='我知道他会干什么。', `MaleText_loc5`='我知道他會怎麼做。', `MaleText_loc7`='Sé lo que él haría.' WHERE `ID`=32731;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일어나 백성을 이끌라 그렇게 말씀하셨겠죠.', `MaleText_loc4`='他会对你说：萨尔，领导你的人民。', `MaleText_loc5`='他會對你說:索爾，領導你的人民。', `MaleText_loc7`='Te diría: Thrall. Tu gente necesita un líder.' WHERE `ID`=32732;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 돌아갑시다, 오랜 친구여.', `MaleText_loc4`='让我们回家吧，老朋友。', `MaleText_loc5`='我們回家去吧，老朋友。', `MaleText_loc7`='Vamos a casa, viejo amigo.' WHERE `ID`=32733;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 고개를 끄덕입니다.', `MaleText_loc4`='%s点了点头。', `MaleText_loc5`='%s點點頭。', `MaleText_loc7`='%s asiente con la cabeza.' WHERE `ID`=32734;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로크, 오랜 친구여, 돌아온 걸 보니 반갑군. 아들 일은 유감이오.', `MaleText_loc4`='老朋友，见到你真高兴。对小萨鲁法尔的遭遇，我很抱歉。', `MaleText_loc5`='真高興你能回來，瓦洛克老友。你兒子的事情我很遺憾。', `MaleText_loc7`='Qué bueno tenerte de vuelta, Varok, viejo amigo. Lamento lo de tu hijo.' WHERE `ID`=32735;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 함께 주워 먹습니다.', `MaleText_loc4`='%s过来抓起一些东西送进嘴里。', `MaleText_loc5`='%s也來咬一口。', `MaleText_loc7`='%s se une y coge un trozo de comida.' WHERE `ID`=32736;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 목격자, 자란타우르일세.', `MaleText_loc4`='我是见证者夏拉托尔。', `MaleText_loc5`='我是札倫陶，見證者。', `MaleText_loc7`='Yo soy Xarantaur, el Testigo' WHERE `ID`=32737;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='옛날 얘기 하나 들어 보겠나?', `MaleText_loc4`='你愿意听我讲个故事吗？', `MaleText_loc5`='你想要聽個故事嗎?', `MaleText_loc7`='¿Quieres oír una historia?' WHERE `ID`=32738;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게 들려줄 이야기가 있는가?', `MaleText_loc4`='故事？', `MaleText_loc5`='你有故事要告訴我?', `MaleText_loc7`='¿Tienes una historia para mí?' WHERE `ID`=32739;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 그렇지, 자네에 대한 글을 읽은 적이 있네, $n.', `MaleText_loc4`='嗯，我读到过你的故事，$n。', `MaleText_loc5`='喔，對，我讀到過你，$n。', `MaleText_loc7`='Ah, sí, he leído sobre ti por ahí, $n.' WHERE `ID`=32740;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 이야기를 해주십시오, 자란타우르 님. 왜 목격자라고 불리시는지요?', `MaleText_loc4`='做个自我介绍吧，夏拉托尔。你为什么被称为见证者？', `MaleText_loc5`='可以告訴我關於你的事嗎，札倫陶。為什麼你叫做見證者?', `MaleText_loc7`='Háblame de ti, Xarantaur. ¿Por qué te llaman el Testigo?', `FemaleText_loc1`='당신 이야기를 해주세요, 자란타우르 님. 왜 목격자라고 불리시지요?', `FemaleText_loc4`='做个自我介绍吧，夏拉托尔。你为什么被称为见证者？', `FemaleText_loc5`='可以告訴我關於你的事嗎，札倫陶。為什麼你叫做見證者?', `FemaleText_loc7`='Háblame de ti, Xarantaur. ¿Por qué te llaman el Testigo?' WHERE `ID`=32741;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 최초로 타우렌 드루이드가 되었던 이들 중 하나였네. 이 세계가 아직 오래되지 않았을 무렵, 불타는 군단이 나타나기 전에, 세계의 분리가 일어나기도 전에 샨도 세나리우스가 가르쳤던 마지막 세대였지. 모든 것이 변하기 이전 일일세.$B$B우리 동지들은 대단한 짐승들을 사냥했고, 나는 이야기를 사냥했네. 지식에 대한 이런 갈급함과 열망으로 드루이드 예술에 이끌렸지. 잠시, 나무와 바위와 짐승들과 대화하고 그들의 이야기를 듣는 법을 배우는 동안은 그런 목마름을 잠재울 수 있었네.$B$B하지만 그때, 세나리우스가 우리에게 오는 것을 중단하자 동지들은 그가 무엇을 가르쳤는지 잊어버렸다네. 그러나 나는 잊어버리지 않았네. 아직 우리 세상을 더 알아가야 하지.$B$B그래서 우리 종족을 멀리 떠나 여행을 했다네.', `MaleText_loc4`='我是最早一批，也是最后一代接受过塞纳留斯教诲的牛头人德鲁伊之一。那时候世界还很年轻，没有燃烧军团，大灾变也还没有发生。一切都是那么宁静。$B$B当我的同胞学习猎杀巨兽时，我却在搜寻历史故事。对知识的渴求令我沉湎于德鲁伊的魔法。有段时间，我满足于与树木、岩石和野兽交谈，倾听它们的故事。$B$B后来，塞纳留斯不再露面，我的同胞渐渐遗忘了他的教诲，但是我忘不了，我还想了解更多关于这个世界的知识。$B$B于是我告别族人，离开家乡去远方流浪。', `MaleText_loc5`='早在燃燒軍團與大爆炸之前，當這個世界依舊年輕，世事未逢劇變時，我曾是我族首批牛頭人德魯伊的一份子，塞納留斯尊師的最後一代弟子。$B$B當我的族人在追尋更大更強的獵物時，我追尋著故事與傳說。在這樣的飢渴與對知識的渴望驅使下讓我走向了德魯伊之道。有一段時間，這些渴望在我學習如何與樹木、岩石還有野獸交談時獲得滿足，我聆聽他們的故事。$B$B但是當塞納留斯不再行走於我們之間的時候，我的族人也開始忘記他所教導的事物。然而我無法忘卻，我依舊渴望能從這個世界學習到更多事物。$B$B於是我揮別同族，踏上前往未知之地的旅程。', `MaleText_loc7`='Yo fui uno de los primeros tauren druidas, de la última generación de aprendices de Shan''do Cenarius, antes de la Legión y del Cataclismo, cuando el mundo aún era joven, antes de que todo cambiase.$B$BMientras mis hermanos cazaban bestias, yo cazaba historias. Me sentí atraído por las artes druidas por esta sed, este deseo de conocimiento. Durante un tiempo, saciaba mi sed contando a los árboles, a las rocas y a las bestias sus historias.$B$BPero después, cuando Cenarius no estaba entre nosotros, mis hermanos comenzaron a olvidar lo que nos había enseñado. Mas yo no lo olvidé y aún necesito aprender más sobre nuestro mundo.$B$BAsí que me despedí y viajé a través de las tierras de mi gente.' WHERE `ID`=32742;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 이야기해 주십시오.', `MaleText_loc4`='请继续。', `MaleText_loc5`='請繼續。', `MaleText_loc7`='Por favor, continúa.', `FemaleText_loc1`='계속 이야기해 주세요.', `FemaleText_loc4`='请继续。', `FemaleText_loc5`='請繼續。', `FemaleText_loc7`='Por favor, continúa.' WHERE `ID`=32743;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지식을 찾아가면서 자연생활을 좇아 방랑하는 과정에서 더욱 놀라운 일들을 보며 우리 종족의 그 어떤 이보다 더 이상하고 신기한 종족을 만났네. 나는 고대 칼림도어를 좌우로, 남북으로 가로질러 더 볼 것이 없을 때까지, 지평선 너머로 새로운 땅이 더 나오지 않을 때까지 여행해 다녔네.$B$B그러나... 여행이 끝나감을 느꼈지만 아직도 알지 못하는 것이 많이 있었기에 눈물을 흘렸지.$B$B땅에 쓰러지고, 내 삶이 끝난 그때, 저들이 날 발견했다네.', `MaleText_loc4`='我穷尽一生寻找知识，目睹了许多奇迹，遇见了各种各样神秘的种族，这些经历远远超越了所有的先辈。我的足迹遍布远古的卡利姆多大陆，直到再也找不到新鲜的事物，直到地平线看不见新的陆地。$B$B但是……就在这次旅途即将划上句号时，我觉得自己还是对很多东西缺乏了解。我深知这将成为永远的遗憾，禁不住放声痛哭。$B$B自然生命总有消亡的一天，我跌到在地。这时，他们找到了我。', `MaleText_loc5`='我在我剩餘的自然壽命中繼續搜尋知識，比起我的任何一位族人，我看過更多的奇景也遭遇過更多奇怪與神秘的種族。我在遠古的卡林多四處旅行，直到我走遍諸地，看遍諸事。$B$B然而...我還想要知道更多的事情，但我感覺到我最終的旅程即將到來，我為了那些我永遠也無法知道的事情而落淚。$B$B當我死去，我的生命終結，他們找上了我。', `MaleText_loc7`='Deambulé por el resto de mi vida natural en busca de conocimiento, viendo más maravillas y encontrando más razas extrañas y misteriosas que mi gente nunca había visto. Viajé a lo largo y ancho del antiguo Kalimdor hasta no tener nada más que ver, sin tierras nuevas en el horizonte.$B$BPero... aún hay mucho que desconozco, ahora que siento que se acerca el final de mi viaje y lloro por las cosas que nunca podré conocer.$B$BAhora siento, al final de mi vida, que me han encontrado.' WHERE `ID`=32744;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들이라뇨?', `MaleText_loc4`='他们？', `MaleText_loc5`='他們?', `MaleText_loc7`='¿Ellos?', `FemaleText_loc1`='저들이라뇨?', `FemaleText_loc4`='他们？', `FemaleText_loc5`='他們?', `FemaleText_loc7`='¿Ellos?' WHERE `ID`=32745;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='청동용군단 말일세. 그들이 죽음의 가장자리에서 나를 잡아 올려 그들의 주인인 노즈도르무에게 데려갔네. 노즈도르무 말로는 청동용군단이 나를 지켜보고 있었다면서 내가 하던 여행을 계속하길 원한다더군. 노즈도르무는 내게 감시자로서 영원한 생명을 주고 그의 부하로서 아제로스의 역사를 지켜보라는 임무를 부여했네.$B$B그래서 나는 목격자 자란타우르라네. 그리고 아제로스의 진짜 역사가 잊히지 않도록 보존하는 것이 내 임무일세.', `MaleText_loc4`='青铜龙族。他们将我从死亡的边缘拯救回来，并带我去见时光之王诺兹多姆。诺兹多姆说，他们一直在关注我的动向，并希望我能够继续追寻知识。他赐我永生并任命我为观察者，担当起艾泽拉斯历史见证者的角色。$B$B我是见证者夏拉托尔，我的任务是维系艾泽拉斯的真实历史，避免它被遗忘。', `MaleText_loc5`='青銅龍軍團。他們把我從死亡的邊緣給叼回來，將我帶到他們的主人，諾茲多姆的面前。他說他們一直觀察我，希望我繼續我的追尋。他賦予我觀察者的永生，成為他的使者，肩負起見證艾澤拉斯歷史的使命。$B$B我是『見證者』札倫陶，我的職責就是要見證艾澤拉斯的真實歷史，以防它被遺忘。', `MaleText_loc7`='El Vuelo Bronce. Me arrancó del borde de la muerte y me llevó con su maestro, Nozdormu. Dijo que habían estado observándome y querían que siguiese mi caza. Me otorgó inmortalidad como vigía, encargado de correr como testigo de la historia de Azeroth como uno de sus agentes.$B$BYo soy Xarantaur, el Testigo y mi deber es preservar la verdadera historia de Azeroth para que no se olvide.' WHERE `ID`=32746;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기는 툰카로 야영지군요. 우리 형제가 다스리는 마을이지만, 당... 당신은 기억에 없습니다.', `MaleText_loc4`='这里是唐卡洛营地，我的兄弟掌管着这个村落，但是……我不记得你。', `MaleText_loc5`='這是坦卡羅營地，這是由我兄弟所統治的村莊，但我...我不記得你了。', `MaleText_loc7`='Este es el Campamento Tunka''lo, el poblado dirigido por mi hermano, pero yo a ti… no te recuerdo.' WHERE `ID`=32747;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런데 자네를 거의 기억하지 못하는군. $n|1은;는; 북풍에 맞서 용감하게 싸워 자네를 지켰었네.', `MaleText_loc4`='你的存在差点就被抹杀了。$n勇敢地与北风作战，保护了关于你的历史。', `MaleText_loc5`='而我差點就要記不得你了。$n要很努力地對抗北風精靈才得以保護你的故事。', `MaleText_loc7`='Y casi no se acordaban de ti. $n luchó firmemente contra el Viento del norte para proteger tu historia.' WHERE `ID`=32748;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='북풍 말입니까? 그것이 우리 종족을 아직도 괴롭힙니까?', `MaleText_loc4`='北风？它还在祸害我的族人？', `MaleText_loc5`='北風精靈?它還在騷擾我的族人?', `MaleText_loc7`='¿El Viento del Norte? ¿Aún molesta a mi gente?' WHERE `ID`=32749;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 바람과 맞서 싸웠던 일은 벌써 수백 년도 더 된 일일세, 스톰후프. 자네가 그 바람을 약하게 한 덕분에 내내 잠잠했었지.', `MaleText_loc4`='雷蹄，你与北风的战斗已经过去了数百年。你重创了它，这些年来它一直都很沉寂。', `MaleText_loc5`='你和北風的戰鬥已經是幾百年前的事了，風暴之蹄。你將它傷得如此之重，以致於它這些年來都保持沉默。', `MaleText_loc7`='Tu batalla con el viento fue hace siglos, Pezuña Tempestuosa. Le debilitaste tanto que ha estado en silencio todos estos años.' WHERE `ID`=32750;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만, 북풍은 그리 호락호락 패배를 인정하지 않았다네. 그 대신에 자네 기억을, 고향을 파괴하는 것이 최고의 복수라 생각하고 때를 기다리며 힘을 모았지.', `MaleText_loc4`='但是北风不甘心就此落败。相反，它一直在积聚力量，等待时机，意图摧毁你的历史和这座村庄。', `MaleText_loc5`='但北風精靈並不是默默地吞下敗仗，它積蓄力量並且等待時機，決定最成功的復仇莫過於毀掉關於你的記憶，以及你的村莊。', `MaleText_loc7`='Pero el Viento del norte no aceptó la derrota en silencio. En cambio, adquirió poder y esperó el momento oportuno mientras decidía que la mejor venganza era destruir tu memoria y con ella la de tu pueblo.' WHERE `ID`=32751;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 바람은 하수인들을 보내 자네 종족에 전해 내려오는 이야기를 바꿔버리고 명예롭게 죽어간 자들의 영혼까지 파괴하면서 이곳의 역사를 왜곡했다네.', `MaleText_loc4`='北风让它的爪牙扭曲了这个地区的历史，意图改变牦牛人口口相传的故事并消灭先祖的亡魂。', `MaleText_loc5`='北風運用它的手下扭曲此地的歷史，竄改你族人所傳頌的故事，毀去那些光榮逝者的精神。', `MaleText_loc7`='El viento usó sus esbirros para distorsionar la historia de este lugar, cambiando las historias que contaba tu gente, destruyendo los espíritus de los muertos honorables.' WHERE `ID`=32752;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠의 지배자 키트릭스가 남동쪽으로부터 발할라스로 오고 있습니다!', `MaleText_loc4`='黑暗主宰西塔利克斯从东南方冲进了瓦哈拉斯！', `MaleText_loc5`='『黑暗大師』齊特瑞司從東南方飛快掠過英靈殿!', `MaleText_loc7`='Khit''rix el Maestro Lóbrego se apresura hacia Valhalas desde el sureste.' WHERE `ID`=32753;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='만약 $n|1과;와; 북풍이 역사적으로 그 근원을 어떻게 타락시켰는지 즉, 자네가 예전에 치러냈던 그 전투를 추적하지 않았더라면 바람이 계획한 대로 되었을 걸세.', `MaleText_loc4`='要不是$n和我循着北风扭曲历史的线索，找到了破坏的源头：你与北风的那场远古之战，它们的阴谋已经得逞了。', `MaleText_loc5`='如果不是$n 和我追查北風精靈的歷史腐化直到它的源頭:你的遠古戰役，它或許早已成功。', `MaleText_loc7`='Habría salido bien si $n y yo no hubiésemos rastreado las corrupciones históricas del Viento del norte hasta la fuente: tu antigua batalla.' WHERE `ID`=32754;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 도움을 받아, $n|1은;는; 자네가 싸웠던 그때로 시간 여행을 떠나서 역사가 올바르게 놓이도록 했다네. 북풍은 운명을 봉인 당했고, 자네의 이야기는 원래대로 되살려졌지.', `MaleText_loc4`='在我的帮助下，$n及时返回了那场战斗的时间流，维护了历史的真相。北风的命运已经被封印起来，你的故事也得以恢复正常。', `MaleText_loc5`='透過我的協助，$n回到了你戰鬥的時候，確定歷史重新回到正軌。北風精靈再次被封印，而你的故事也恢復原貌。', `MaleText_loc7`='Con mi ayuda, $n viajó en el tiempo de vuelta a tu batalla y aseguró que la historia transcurría correctamente. El destino de El Viento del Norte estaba escrito y tu historia restaurada.' WHERE `ID`=32755;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저와 저희 마을을 대신해서 두 분께 감사를 드려야겠습니다. 두 분께서 어떤 일을 해내셨는지 많은 이들이 모를 테지만 말입니다.', `MaleText_loc4`='我代表村民谢谢你们，虽然你们的事迹不会为大多数人所知。', `MaleText_loc5`='我和我的村莊感謝你們兩位，雖然很多人永遠也不會知道你的義行。', `MaleText_loc7`='Tanto yo como el poblado les estamos agradecidos, aunque algunos nunca sabrán de sus actos.' WHERE `ID`=32756;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발할라스를 맴돌던 시그리드 아이스본이 복수의 대상을 찾아 접근합니다!', `MaleText_loc4`='齐格莉德·冰魂在瓦哈拉斯上空盘旋，她是来复仇的！', `MaleText_loc5`='在英靈殿四周盤旋著，席格芮·冰誕逼近場中尋求復仇!', `MaleText_loc7`='¡Rodeando Valhalas, Sigrid Hielonato se acerca en busca de venganza!' WHERE `ID`=32757;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='남쪽에서 육중한 소리가 들리고, 살육자의 냄새가 점점 진해집니다!', `MaleText_loc4`='南方飘来的气味预示了卡纳基的到来！', `MaleText_loc5`='沉重腳步聲從南方傳來，卡納基人還沒到，就先聞到氣味了!', `MaleText_loc7`='¡Avanzando desde el sur, el olor a Carnicería le precede!' WHERE `ID`=32758;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 여기에 남을 수 없습니다. 제가 속한 무덤으로 돌아가야 하지만, 조상님들을 다시 뵌다면, 그대의 이야기를 꼭 전하겠습니다.', `MaleText_loc4`='我不能待在这里。我必须返回自己的陵墓。当我与长者的灵魂重聚时，会向大家讲诉你的故事。', `MaleText_loc5`='我不能繼續待在這裡。我得回到屬於我的石堆去了，但當我再次看到先祖們，我會告訴他們你的故事。', `MaleText_loc7`='No puedo quedarme aquí. Tengo que volver al hito al que pertenezco pero cuando vuelva a ver a los ancestros, yo seré quién les contará tu historia.' WHERE `ID`=32759;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='남동쪽을 바라보자 바나호그 영주가 모습을 드러냅니다.', `MaleText_loc4`='巴纳霍格领主出现在东南方的高台上！', `MaleText_loc5`='巴納霍格族長靠近了東南方的看臺!', `MaleText_loc7`='¡El señor feudal Banahogg aparece en el mirador del sureste!' WHERE `ID`=32760;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마치 마법처럼, 산도발 공작이 발할라스에 홀연히 나타납니다!', `MaleText_loc4`='萨杜瓦尔王子在毫无征兆的情况下，如幻影般出现在瓦哈拉斯！', `MaleText_loc5`='毫無預警地，薩杜瓦爾親王變法術般地出現在英靈殿中!', `MaleText_loc7`='¡Sin previo aviso, el príncipe Sandoval aparece por arte de magia en Valhalas!' WHERE `ID`=32761;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='편히 쉬게나, 영웅이여.', `MaleText_loc4`='安息吧，勇士。', `MaleText_loc5`='好好休息，英雄。', `MaleText_loc7`='Descansa bien, héroe.' WHERE `ID`=32762;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 발톱으로 당신을 할큅니다!', `MaleText_loc4`='%s扬起利爪，朝你挥来！', `MaleText_loc5`='%s以他的爪子猛力揮擊你!', `MaleText_loc7`='¡%s te golpea con sus garras!' WHERE `ID`=32763;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런! 당신은 나잖아, 그것도 미래에서 온! 아니 내 장비가 이렇게나 좋아졌다니. 정말 멋진걸!', `MaleText_loc4`='哇！你是来自未来的我！嘿嘿，装备强力了不少嘛。真是酷毙了！', `MaleText_loc5`='哇!你是我，但是從未來來的!哈，看來我的裝備又獲得提升了。酷!', `MaleText_loc7`='¡Guau! ¡Tú eres yo pero del futuro! ¡Eh, mi equipo ha mejorado! ¡Genial!', `FemaleText_loc1`='이런! 당신은 나잖아, 그것도 미래에서 온! 아니 내 장비가 이렇게나 좋아졌다니. 정말 멋져!', `FemaleText_loc4`='哇！你是来自未来的我！嘿嘿，装备强力了不少嘛。真是酷毙了！', `FemaleText_loc5`='哇!你是我，但是從未來來的!哈，看來我的裝備又獲得提升了。酷!', `FemaleText_loc7`='¡Guau! ¡Tú eres yo pero del futuro! ¡Eh, mi equipo ha mejorado! ¡Genial!' WHERE `ID`=32764;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='시간만이 알려줄 것이다...', `FemaleText_loc4`='只有时间能证明一切……', `FemaleText_loc5`='唯有時間知道...', `FemaleText_loc7`='Solo el tiempo dirá...' WHERE `ID`=32765;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알렉스트라자여, 여기서 무슨 일이 있었는지 보여주시겠습니까?', `MaleText_loc4`='这里发生了什么事，阿莱克丝塔萨？', `MaleText_loc5`='雅立史卓莎，你能告訴我這裡發生什麼事了嗎?', `MaleText_loc7`='Alexstrasza, ¿puedes mostrarme qué ha pasado aquí?', `FemaleText_loc1`='알렉스트라자여, 여기서 무슨 일이 있었는지 보여주시겠습니까?', `FemaleText_loc4`='这里发生了什么事，阿莱克丝塔萨？', `FemaleText_loc5`='雅立史卓莎，你能告訴我這裡發生什麼事了嗎?', `FemaleText_loc7`='Alexstrasza, ¿puedes mostrarme qué ha pasado aquí?' WHERE `ID`=32766;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오세요, 신기한 장난감 상점입니다!$B$B천천히 둘러보셔도 좋아요. 남녀노소를 불문하고 재미있게 놀 수 있는 장난감이 가득하답니다!', `MaleText_loc4`='欢迎来到奇妙玩具店！$B$B请随意看看。我们出售许多奇妙的玩具，老少咸宜！', `MaleText_loc5`='歡迎來到神奇玩具屋!$B$B慢慢來、慢慢挑。我們神奇的玩具老少咸宜!', `MaleText_loc7`='¡$gBienvenido:Bienvenida; a Obras Asombrosas!$B$BÉchale un ojo a la tienda un rato. Tenemos juguetes maravillosos para gente joven y mayor.' WHERE `ID`=32767;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달라란 티타늄 동전을 잃어버렸습니다. 하나 다시 얻을 수 있을까요?', `MaleText_loc4`='我弄丢了达拉然泰坦神铁徽记。能再给我一枚吗？', `MaleText_loc5`='我弄丟了我的達拉然泰坦鋼徽印。你可以再給我一個嗎?', `MaleText_loc7`='He perdido mi sello de titanio de Dalaran. ¿Podrías conseguirme otro nuevo?', `FemaleText_loc1`='달라란 티타늄 동전을 잃어버렸어요. 하나 다시 얻을 수 있을까요?', `FemaleText_loc4`='我弄丢了达拉然泰坦神铁徽记。能再给我一枚吗？', `FemaleText_loc5`='我弄丟了我的達拉然泰坦鋼徽印。你可以再給我一個嗎?', `FemaleText_loc7`='He perdido mi sello de titanio de Dalaran. ¿Podrías conseguirme otro nuevo?' WHERE `ID`=32768;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무한한 존재가 나타났잖아! 이 모래시계를 안전하게 지켜야 해. 좀 도와주겠어?', `MaleText_loc4`='永恒之龙来了！我必须确保沙漏的安全。你能帮帮我吗？', `MaleText_loc5`='恆龍來襲!我一定要確保沙漏的安全。你能幫忙嗎?', `MaleText_loc7`='¡Aquí vienen los Infinitos! Tengo que proteger el reloj de arena. ¿Puedes ayudarme?', `FemaleText_loc1`='무한한 존재가 나타났잖아! 이 모래시계를 안전하게 지켜야 해. 좀 도와주겠어?', `FemaleText_loc4`='永恒之龙来了！我必须确保沙漏的安全。你能帮帮我吗？', `FemaleText_loc5`='恆龍來襲!我一定要確保沙漏的安全。你能幫忙嗎?', `FemaleText_loc7`='¡Aquí vienen los Infinitos! Tengo que proteger el reloj de arena. ¿Puedes ayudarme?' WHERE `ID`=32769;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 장비도 멋져 보이긴 한데, 좀 더 나은 걸 구할 수는 없었어? 공격대로 뛰기는 하는 거야?', `MaleText_loc4`='这件装备看上去不错啊，但是你就不能穿得更好一点吗？难道你都不去团队副本的么？', `MaleText_loc5`='這些裝備看起來很酷很炫，不過難道我們沒辦法更強一點嗎?你有沒有在出團啊?', `MaleText_loc7`='Este equipo tiene buena pinta y todo eso, pero ¿no podríamos haberlo hecho mejor? ¿Estás participando en bandas siquiera?', `FemaleText_loc1`='이 장비도 멋져 보이긴 한데, 좀 더 나은 걸 구할 수는 없었어? 공격대로 뛰기는 하는 거야?', `FemaleText_loc4`='这件装备看上去不错啊，但是你就不能穿得更好一点吗？难道你都不去团队副本的么？', `FemaleText_loc5`='這些裝備看起來很酷很炫，不過難道我們沒辦法更強一點嗎?你有沒有在出團啊?', `FemaleText_loc7`='Este equipo tiene buena pinta y todo eso, pero ¿no podríamos haberlo hecho mejor? ¿Estás participando en bandas siquiera?' WHERE `ID`=32770;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러니까, 얼음왕관에서 전부 어떻게 되었는데?', `MaleText_loc4`='嗯，冰冠冰川的局势怎么样啦？', `MaleText_loc5`='所以寒冰皇冠到底怎麼樣?', `MaleText_loc7`='¿Cómo ha acabado todo en Corona de Hielo?', `FemaleText_loc1`='그러니까, 얼음왕관에서 전부 어떻게 되었어?', `FemaleText_loc4`='嗯，冰冠冰川的局势怎么样啦？', `FemaleText_loc5`='所以寒冰皇冠到底怎麼樣?', `FemaleText_loc7`='¿Cómo ha acabado todo en Corona de Hielo?' WHERE `ID`=32771;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크로미가 그러는데 이 일을 제대로 해내지 못한다면, 난 그냥 순식간에 사라져버린다더군. 내가 끝이면, 너도 끝이지!', `MaleText_loc4`='克罗米说如果我不能完成任务，我就会从历史上消失。如果我消失了，那么你也就不存在了！', `MaleText_loc5`='克羅米說如果我沒辦法搞定這件事情，我的存在可能眨眨眼就沒了。如果我消失的話，你也會消失!', `MaleText_loc7`='Cromi dijo que si no lo hago ahora mismo, será el fin de mi existencia. ¡Si yo voy, tú vienes!', `FemaleText_loc1`='크로미가 그러는데 이 일을 제대로 해내지 못한다면, 난 그냥 순식간에 사라져버린다더군. 내가 끝이면, 너도 끝이야!', `FemaleText_loc4`='克罗米说如果我不能完成任务，我就会从历史上消失。如果我消失了，那么你也就不存在了！', `FemaleText_loc5`='克羅米說如果我沒辦法搞定這件事情，我的存在可能眨眨眼就沒了。如果我消失的話，你也會消失!', `FemaleText_loc7`='Cromi dijo que si no lo hago ahora mismo, será el fin de mi existencia. ¡Si yo voy, tú vienes!' WHERE `ID`=32772;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보니까 업적은 별로 못 쌓은 것 같군.', `MaleText_loc4`='我似乎不够强力啊。', `MaleText_loc5`='看來我表現不太理想。', `MaleText_loc7`='Parece que soy un seudotriunfador.', `FemaleText_loc1`='보니까 업적은 별로 못 쌓은 것 같네.', `FemaleText_loc4`='我似乎不够强力啊。', `FemaleText_loc5`='看來我表現不太理想。', `FemaleText_loc7`='Parece que soy una seudotriunfadora.' WHERE `ID`=32773;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 일이 끝나면 좀 마시러 갈 생각이야.', `MaleText_loc4`='这事儿完了之后我很可能会借酒消愁。', `MaleText_loc5`='我想這件事情結束之後，我一定要好好喝一杯。', `MaleText_loc7`='Creo que voy a empezar a beber después de esto.', `FemaleText_loc1`='이 일이 끝나면 좀 마시러 갈 생각이야.', `FemaleText_loc4`='这事儿完了之后我很可能会借酒消愁。', `FemaleText_loc5`='我想這件事情結束之後，我一定要好好喝一杯。', `FemaleText_loc7`='Creo que voy a empezar a beber después de esto.' WHERE `ID`=32774;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 싸워야 할 상대가 몇 놈이나 되는지 말해줄 수 있다면 도움이 될 텐데. 기억 안 나, 할아버지?', `MaleText_loc4`='你最好告诉我，我们总共需要面对多少个敌人。你还记得吧？', `MaleText_loc5`='我想如果你能告訴我，我們得打多少隻這種傢伙應該會有點幫助。老爹，你還記得，對吧?', `MaleText_loc7`='Sería de ayuda si pudieses decir con cuántos de estos tíos vamos a luchar. ¿No lo recuerdas, no, abuelo?', `FemaleText_loc1`='우리가 싸워야 할 상대가 몇 놈이나 되는지 말해줄 수 있다면 도움이 될 텐데. 기억 안 나, 할머니?', `FemaleText_loc4`='你最好告诉我，我们总共需要面对多少个敌人。你还记得吧？', `FemaleText_loc5`='我想如果你能告訴我，我們得打多少隻這種傢伙應該會有點幫助。老爹，你還記得，對吧?', `FemaleText_loc7`='Sería de ayuda si pudieses decir con cuántos de estos tíos vamos a luchar. ¿No lo recuerdas, no, abuela?' WHERE `ID`=32775;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 살아서 여길 나갈 수 있다면, 확실히 지금보다는 더 나은 모습이 되리라는 걸 알아줬으면 좋겠어. 지금 네가 별로라는 뜻은 아니야.', `MaleText_loc4`='我想说的是，如果我们能活下来，我一定能比你做得更好。我说这话可没有冒犯的意思。', `MaleText_loc5`='我只是要讓你知道，如果我們能活著撐過這件事，我肯定要讓我們變得比你更好。我沒有惡意你知道的。', `MaleText_loc7`='Solo quiero saber si saldremos de aquí con vida. Estoy seguro de que acabaremos mejor que tú. No te ofendas.', `FemaleText_loc1`='우리가 살아서 여길 나갈 수 있다면, 확실히 지금보다는 더 나은 모습이 되리라는 걸 알아줬으면 좋겠어. 지금 네가 별로라는 뜻은 아니야.', `FemaleText_loc4`='我想说的是，如果我们能活下来，我一定能比你做得更好。我说这话可没有冒犯的意思。', `FemaleText_loc5`='我只是要讓你知道，如果我們能活著撐過這件事，我肯定要讓我們變得比你更好。我沒有惡意你知道的。', `FemaleText_loc7`='Solo quiero saber si saldremos de aquí con vida. Estoy segura de que acabaremos mejor que tú. No te ofendas.' WHERE `ID`=32776;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠시만! 만약 네가 여기 있다면, 그리 머지 않은 미래에 내가 나를 돕는 네가 된다는 얘기잖아? 지금 우리 시간의 굴레에 갇힌 거야?', `MaleText_loc4`='等等！既然你来到这里，那就是说将来我也会扮演你现在的角色，再回来这里来帮助我自己？天哪，这分明是一个死循环啊？！', `MaleText_loc5`='等一等!如果你在這裡，那不就表示未來不遠的某時，我就得成為你來幫助我?我們不會陷入某種時間循環嗎?', `MaleText_loc7`='¡Espera un minuto! Si estás aquí, entonces ¿eso quiere decir que en un futuro no tan lejano voy a ser tú ayudándome a mí? ¿Estamos en una espiral en el ciclo del tiempo?', `FemaleText_loc1`='잠시만! 만약 네가 여기 있다면, 그리 머지 않은 미래에 내가 나를 돕는 네가 된다는 얘기잖아? 지금 우리 시간의 굴레에 갇힌 거야?', `FemaleText_loc4`='等等！既然你来到这里，那就是说将来我也会扮演你现在的角色，再回来这里来帮助我自己？天哪，这分明是一个死循环啊？！', `FemaleText_loc5`='等一等!如果你在這裡，那不就表示未來不遠的某時，我就得成為你來幫助我?我們不會陷入某種時間循環嗎?', `FemaleText_loc7`='¡Espera un minuto! Si estás aquí, entonces ¿eso quiere decir que en un futuro no tan lejano voy a ser tú ayudándome a mí? ¿Estamos en una espiral en el ciclo del tiempo?' WHERE `ID`=32777;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 도와드릴까요?', `MaleText_loc4`='我能帮你什么忙吗？', `MaleText_loc5`='有什麼需要我幫忙的嗎?', `MaleText_loc7`='¿Cómo puedo ayudarte?', `FemaleText_loc1`='어떻게 도와드릴까요?', `FemaleText_loc4`='我能帮你什么忙吗？', `FemaleText_loc5`='有什麼需要我幫忙的嗎?', `FemaleText_loc7`='¿Cómo puedo ayudarte?' WHERE `ID`=32778;
