UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 무슨 일이지? 노즈도르무가 저 위에 있어!', `MaleText_loc4`='见鬼！诺兹多姆就在那里！', `MaleText_loc5`='真見鬼了?諾茲多姆就在那邊!', `MaleText_loc7`='¿Qué diablos? ¡Nozdormu está ahí!', `FemaleText_loc1`='이게 무슨 일이지? 노즈도르무가 저 위에 있어!', `FemaleText_loc4`='见鬼！诺兹多姆就在那里！', `FemaleText_loc5`='真見鬼了?諾茲多姆就在那邊!', `FemaleText_loc7`='¿Qué diablos? ¡Nozdormu está ahí!' WHERE `ID`=32781;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간을 지나 다시 끌려가는 기분이 들어. 도와줘서 고마워...', `MaleText_loc4`='我感觉自己正在脱离时间流。谢谢你……', `MaleText_loc5`='我感覺到我正在被拉出這個時間。感謝你的幫忙啦...', `MaleText_loc7`='Me siento como si me hubiesen soltado por el tiempo. Gracias por la ayuda…', `FemaleText_loc1`='시간을 지나 다시 끌려가는 기분이 들어. 도와줘서 고마워...', `FemaleText_loc4`='我感觉自己正在脱离时间流。谢谢你……', `FemaleText_loc5`='我感覺到我正在被拉出這個時間。感謝你的幫忙啦...', `FemaleText_loc7`='Me siento como si me hubiesen soltado por el tiempo. Gracias por la ayuda…' WHERE `ID`=32782;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미안해, 더 버틸 수가 없어. 그렇다고 존재하려는 노력을 그만둬서는 안 돼...', `MaleText_loc4`='对不起，我坚持不住了。希望你不会就此消失……', `MaleText_loc5`='抱歉，我沒辦法控制。我希望這不是表示你的存在正在消失...', `MaleText_loc7`='Lo siento, no pude aguantar más. Espero que no signifique que tu exitencia está a punto de llegar a su fin…', `FemaleText_loc1`='미안해, 더 버틸 수가 없어. 그렇다고 존재하려는 노력을 그만둬서는 안 돼...', `FemaleText_loc4`='对不起，我坚持不住了。希望你不会就此消失……', `FemaleText_loc5`='抱歉，我沒辦法控制。我希望這不是表示你的存在正在消失...', `FemaleText_loc7`='Lo siento, no pude aguantar más. Espero que no signifique que tu exitencia está a punto de llegar a su fin…' WHERE `ID`=32783;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='붙드는 힘이 약해집니다!', `MaleText_loc4`='你快抓不住了！', `MaleText_loc5`='你的控制正在衰退!', `MaleText_loc7`='¡Tu Agarre está fallando!' WHERE `ID`=32784;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 감히 나를 깨워 활력술을 방해하느냐?!', `MaleText_loc4`='复苏的时刻还没有到来，谁敢提前惊醒我？！', `MaleText_loc5`='誰膽敢在我復甦之前就喚醒我?!', `MaleText_loc7`='¿Quién osa despertarme antes de la resurrección?' WHERE `ID`=32785;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈은 내 상대가 아니야!', `MaleText_loc4`='你们无法与我匹敌！', `MaleText_loc5`='你根本不是我的對手!', `MaleText_loc7`='¡No estás a mi altura!' WHERE `ID`=32786;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='처음부터 끼어들지 말았어야지...', `MaleText_loc4`='你们不应该插手的……', `MaleText_loc5`='你不應該介入...', `MaleText_loc7`='no deberías haber interferido…' WHERE `ID`=32787;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕을 모시는 게 나의 숙명이다!', `MaleText_loc4`='我注定要为巫妖王效劳！', `MaleText_loc5`='我的宿命就要是服侍巫妖王!', `MaleText_loc7`='¡Mi destino es servir al Rey Exánime!' WHERE `ID`=32788;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누구도 나를 막을 수 없다!', `MaleText_loc4`='谁也别想阻止我！', `MaleText_loc5`='我不能被阻礙!', `MaleText_loc7`='¡No me pararán!' WHERE `ID`=32789;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어리석은 것, 무기를 내려놓아라... 이젠 돌이킬 수 없다!', `MaleText_loc4`='蠢货，放下武器……已经太迟了！', `MaleText_loc5`='放下你的武器，蠢貨...你太遲了!', `MaleText_loc7`='¡Dejad las armas, insensatos… llegáis es demasiado tarde!' WHERE `ID`=32790;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이리 와서 내 부하가 되어라. 내가 리치 왕을 모시듯 너도 나를 모셔라!', `MaleText_loc4`='来吧，成为我的仆从吧。向我效忠，如同我对巫妖王效忠一样！', `MaleText_loc5`='來吧，成為我的部下。服侍我，如同我服侍巫妖王!', `MaleText_loc7`='¡Venid, uníos a mis esbirros. Servidme como yo sirvo al Rey Exánime!' WHERE `ID`=32791;
