UPDATE `locales_broadcast_text` SET `MaleText_loc1`='프라우드무어 님, 오그리마로 갈 준비가 되었습니다. 차원문을 열어 주십시오.', `MaleText_loc4`='普罗德摩尔女士，我准备好前往奥格瑞玛了。请开启传送门。', `MaleText_loc5`='普勞德摩爾女士，我已經準備好前往奧格瑪。請打開傳送門。', `MaleText_loc7`='Lady Valiente, estoy $glisto:lista; para ir a Orgrimmar. Abre el portal.', `FemaleText_loc1`='프라우드무어 님, 오그리마로 갈 준비가 되었어요. 차원문을 열어 주세요.', `FemaleText_loc4`='普罗德摩尔女士，我准备好前往奥格瑞玛了。请开启传送门。', `FemaleText_loc5`='普勞德摩爾女士，我已經準備好前往奧格瑪。請打開傳送門。', `FemaleText_loc7`='Lady Valiente, estoy $glisto:lista; para ir a Orgrimmar. Abre el portal.' WHERE `ID`=32798;
