UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기서 좋은 이들을 벌써 몇 명이나 잃었네. 이곳이 그럴 가치가 있는지 의심이 들기 시작하는군.', `FemaleText_loc4`='我们已经损失了好几名优秀的同胞。我开始怀疑，这里是否值得我们如此关注。', `FemaleText_loc5`='我們在這裡已經損失了不少好人。我開始懷疑這個地方是不是值得我們的注意。', `FemaleText_loc7`='Hemos perdido a algunas buenas personas ya. Empiezo a dudar si este lugar merece nuestra atención.' WHERE `ID`=32819;
