UPDATE `locales_broadcast_text` SET `MaleText_loc1`='콜티라... 조금 이상하게 들릴지는 모르겠지만, 어떤 아이의 유령이 계속 보입니다. 마시어스 레넷... 혹시 짚이는 게 있으신지요?', `MaleText_loc4`='库尔迪拉……这听上去有些诡异，但是我最近经常看见一个孩子的魂魄。米斯希尔萨·阿奈尔……你听过这个名字吗？', `MaleText_loc5`='寇爾提拉...這或許聽起來很奇怪，我一直看到一個小孩的鬼魂。米希阿斯·薩爾奈...你聽過這個名字嗎?', `MaleText_loc7`='Koltira… igual suena raro pero sigo viendo niños fantasmas. Matthias Lehner… ¿ese nombre te dice algo?', `FemaleText_loc1`='콜티라... 조금 이상하게 들릴지는 모르겠지만, 어떤 아이의 유령이 계속 보입니다. 마시어스 레넷... 혹시 짚이는 게 있으신지요?', `FemaleText_loc4`='库尔迪拉……这听上去有些诡异，但是我最近经常看见一个孩子的魂魄。米斯希尔萨·阿奈尔……你听过这个名字吗？', `FemaleText_loc5`='寇爾提拉...這或許聽起來很奇怪，我一直看到一個小孩的鬼魂。米希阿斯·薩爾奈...你聽過這個名字嗎?', `FemaleText_loc7`='Koltira… igual suena raro pero sigo viendo niños fantasmas. Matthias Lehner… ¿ese nombre te dice algo?' WHERE `ID`=32828;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비 태세를 갖추라, $n. 모든 병력이 도착하는 대로 공격을 시작한다!', `MaleText_loc4`='做好战斗的准备，$n。等部队全部就位之后，我们就要开始进攻了！', `MaleText_loc5`='做好準備，$n。等我們所有的部隊都到齊就展開攻擊!', `MaleText_loc7`='¡Prepárate, $n! Atacaremos cuando todas nuestras fuerzas hayan llegado.' WHERE `ID`=32829;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속되는 전투에 신경이 쇠약해지셨나 봅니다, $n|1이여;여;. 걱정하지 마십시오, 방금 들은 얘기는 아무에게도 말하지 않겠습니다. 혹시 다른 사람이 이 얘길 들으면 그대를 미친 사람 취급할 테니까요.$B$B좀 쉬면 괜찮아질 겁니다.', `MaleText_loc4`='看来这场高强度的战斗终于让你体力不支了，$n。放心吧，我不会泄漏你的小秘密的——省得别人认为你疯了。$B$B休息一下吧。这对你有好处。', `MaleText_loc5`='連番的血戰終究還是對你造成影響了，$n。別擔心，我不會洩漏你的小秘密 -- 免得其他人以為你瘋了。$B$B去休息一下吧，會對你有幫助的。', `MaleText_loc7`='Tanta batalla está acabando contigo, $n. No te preocupes, no divulgaré tu secretito… no sea que el resto piense que estás $gloco:loca;.$B$BDescansa un poco. Te vendrá bien.' WHERE `ID`=32830;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겨울손아귀 통제권을 놓고 벌이는 전투가 15분 후에 시작됩니다!', `MaleText_loc4`='冬拥湖争夺战将在15分钟后开始！', `MaleText_loc5`='控制冬握湖的戰鬥即將於15分鐘內開始!', `MaleText_loc7`='¡La batalla por el control de Conquista del Invierno comenzará en 15 minutos!' WHERE `ID`=32831;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 위대하신 용의 여왕이시여, 집중의 눈동자로 가는 열쇠를 어디다 두었는지 모르겠습니다. 열쇠를 찾아주실 수 있으십니까?', `MaleText_loc4`='伟大的红龙女王，我弄丢了聚焦之虹的钥匙。能帮我找回来吗？', `MaleText_loc5`='喔，偉大的群龍之后，我弄丟了我的聚源虹膜之鑰。您能替我找到它嗎?', `MaleText_loc7`='Oh, gran reina de los dragones, no sé cómo pero he perdido mi llave del Iris de enfoque. ¿Puedes encontrarla?', `FemaleText_loc1`='오, 위대하신 용의 여왕이시여, 집중의 눈동자로 가는 열쇠를 어디다 두었는지 모르겠어요. 열쇠를 찾아주실 수 있나요?', `FemaleText_loc4`='伟大的红龙女王，我弄丢了聚焦之虹的钥匙。能帮我找回来吗？', `FemaleText_loc5`='喔，偉大的群龍之后，我弄丟了我的聚源虹膜之鑰。您能替我找到它嗎?', `FemaleText_loc7`='Oh, gran reina de los dragones, no sé cómo pero he perdido mi llave del Iris de enfoque. ¿Puedes encontrarla?' WHERE `ID`=32832;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겨울손아귀 통제권을 놓고 벌이는 전투가 5분 후에 시작됩니다!', `MaleText_loc4`='冬拥湖争夺战将在5分钟后开始！', `MaleText_loc5`='控制冬握湖的戰鬥即將於5分鐘內開始!', `MaleText_loc7`='¡La batalla por el control de Conquista del Invierno comenzará en 5 minutos!' WHERE `ID`=32833;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='임무를 보고합니다, 폐하! 공격을 시작하도록 명령을 내려 주십시오!', `MaleText_loc4`='报告，陛下！可以开始进攻了！', `MaleText_loc5`='向您回報，陛下!讓進攻展開吧!', `MaleText_loc7`='¡A sus ordenes, Su Majestad! ¡Que comience el asalto!', `FemaleText_loc1`='임무를 보고합니다, 폐하! 공격을 시작하도록 명령을 내려 주세요!', `FemaleText_loc4`='报告，陛下！可以开始进攻了！', `FemaleText_loc5`='向您回報，陛下!讓進攻展開吧!', `FemaleText_loc7`='¡A sus ordenes, Su Majestad! ¡Que comience el asalto!' WHERE `ID`=32834;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 위대하신 용들의 여왕이시여, 집중의 눈동자 영웅 열쇠를 어디다 두었는지 모르겠습니다. 열쇠를 찾아줄 수 있으십니까?', `MaleText_loc4`='伟大的红龙女王，我弄丢了英雄聚焦之虹的钥匙。能帮我找回来吗？', `MaleText_loc5`='喔，偉大的群龍之后，我弄丟了我的聚源虹膜英雄之鑰。您能替我找到它嗎?', `MaleText_loc7`='Oh, gran reina de los dragones, no sé cómo pero he perdido mi llave heroica del Iris de enfoque. ¿Puedes encontarla?', `FemaleText_loc1`='오, 위대하신 용들의 여왕이시여, 집중의 눈동자 영웅 열쇠를 어디다 두었는지 모르겠어요. 열쇠를 찾아주실 수 있나요?', `FemaleText_loc4`='伟大的红龙女王，我弄丢了英雄聚焦之虹的钥匙。能帮我找回来吗？', `FemaleText_loc5`='喔，偉大的群龍之后，我弄丟了我的聚源虹膜英雄之鑰。您能替我找到它嗎?', `FemaleText_loc7`='Oh, gran reina de los dragones, no sé cómo pero he perdido mi llave heroica del Iris de enfoque. ¿Puedes encontarla?' WHERE `ID`=32836;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마지막 전투가 곧 시작된다, $n. 정렬하라!', `MaleText_loc4`='最后的决战即将开始，$n。保持警惕！', `MaleText_loc5`='最終的戰鬥即將展開，$n。集中精神!', `MaleText_loc7`='La batalla final comenzará pronto, $n. ¡Estate atento!' WHERE `ID`=32837;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겨울손아귀 전장에 증원군이 필요합니다! 빠르게 전장으로 이동할 수 있는 차원문을 은빛 자치구에 열어두었습니다.', `MaleText_loc4`='冬拥湖战场需要援军！我已经在银色领地开启了一道通往冬拥湖的传送门。', `MaleText_loc5`='冬握湖戰場需要增援!我打開了一道傳送門讓人可以迅速地從白銀領區前往戰場。', `MaleText_loc7`='¡Se necesitan refuerzos en el campo de batalla de Conquista del Invierno! He abierto un portal para viajar rápidamente a la batalla de El Enclave de Plata.' WHERE `ID`=32838;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='물론이지. 그러나 다음에는 좀 더 조심하거라.', `FemaleText_loc4`='当然可以，不过以后请小心一些。', `FemaleText_loc5`='當然可以，但之後請更加小心。', `FemaleText_loc7`='Sí, claro. Pero ten más cuidado de ahora en adelante.' WHERE `ID`=32839;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겨울손아귀 전장에 증원군이 필요합니다! 빠르게 전장으로 이동할 수 있는 차원 문을 선리버 성소에 열어두었습니다.', `MaleText_loc4`='冬拥湖战场需要援军！我已经在夺日者圣殿开启了一道通往冬拥湖的传送门。', `MaleText_loc5`='冬握湖戰場需要增援!我打開了一道傳送門讓人可以迅速地從奪日者聖堂前往戰場。', `MaleText_loc7`='¡Se necesitan refuerzos en el campo de batalla de Conquista del Invierno! He abierto un portal para viajar rápidamente a la batalla del Santuario Atracasol.' WHERE `ID`=32840;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스가 겨울손아귀 전장에서 승리를 거두었습니다! 요새가 우리 손에 들어왔습니다!', `MaleText_loc4`='我们取得了冬拥湖战场的胜利！要塞归我们了！', `MaleText_loc5`='我們在冬握湖戰場獲得了勝利!堡壘是我們的!', `MaleText_loc7`='¡Hemos vencido en el campo de batalla de Conquista del Invierno! ¡La fortaleza es nuestra!' WHERE `ID`=32841;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드가 겨울손아귀 전장에서 승리를 거두었습니다! 요새가 우리 손에 들어왔습니다!', `MaleText_loc4`='我们取得了冬拥湖战场的胜利！要塞归我们了！', `MaleText_loc5`='我們在冬握湖戰場獲得了勝利!堡壘是我們的!', `MaleText_loc7`='¡Hemos vencido en el campo de batalla de Conquista del Invierno! ¡La fortaleza es nuestra!' WHERE `ID`=32842;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스의 영웅들이여, 그대의 왕이 부르노라! 하수구 입구에서 내 뒤로 집합하라!', `MaleText_loc4`='联盟的英雄们，国王在召唤！随我攻入下水道的入口吧！', `MaleText_loc5`='聯盟的英雄，你們的國王在此召喚!在我身後幽暗城的下水道入口集結!', `MaleText_loc7`='¡Héroes de la Alianza, su Rey los llama! ¡Pónganse detrás de mí en la entrada de las cloacas!' WHERE `ID`=32843;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠시 후에 우리는 이 저주받은 곳으로 진군하여 악을 몰아내리라!', `MaleText_loc4`='很快我们就会进入这个被诅咒的地方，清除一切邪恶！', `MaleText_loc5`='很快地我們將要進入這個詛咒之地並且掃除其中的污穢!', `MaleText_loc7`='¡Pronto marcharemos sobre este lugar maldito y lo purificaremos del mal!' WHERE `ID`=32844;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='집중의 눈동자가 상상할 수도 없는 어마어마한 양의 억제된 힘을 누르며 진동합니다!', `MaleText_loc4`='聚焦之虹发出低沉的嗡嗡声，积蓄着不可思议的强大力量！', `MaleText_loc5`='聚源虹膜顫動著，阻擋著一股令人無法置信卻又受到抑制的強大力量!', `MaleText_loc7`='El Iris de enfoque rasgea, reprimiendo una suma inconcebible de poder contenido.' WHERE `ID`=32845;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='집중의 눈동자를 여는 데 열쇠를 사용합니다.', `MaleText_loc4`='用钥匙打开聚焦之虹。', `MaleText_loc5`='使用鑰匙開啟聚源虹膜。', `MaleText_loc7`='Usa la llave para abrir el Iris de enfoque.', `FemaleText_loc1`='집중의 눈동자를 여는 데 열쇠를 사용합니다.', `FemaleText_loc4`='用钥匙打开聚焦之虹。', `FemaleText_loc5`='使用鑰匙開啟聚源虹膜。', `FemaleText_loc7`='Usa la llave para abrir el Iris de enfoque.' WHERE `ID`=32846;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구원의 시간이 눈앞에 다가왔다! 모두 준비하라!', `MaleText_loc4`='救赎的时刻即将来临！做好准备！', `MaleText_loc5`='肅清罪孽的時刻就在眼前!做好準備!', `MaleText_loc7`='¡La hora de la redención está al alcance! ¡Prepárense!' WHERE `ID`=32847;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다치지 않도록 조심하라, 필멸의 존재여. 소중한 동맹인 그대를 잃고 싶지 않도다.', `MaleText_loc4`='凡人，好好保护自己；我们不想失去你这样宝贵的盟友。', `MaleText_loc5`='請小心保重，凡人;你是我們的寶貴盟友，我們不想失去你。', `MaleText_loc7`='Ten cuidado y ponte a salvo,mortal. Eres un aliado valioso que no quisieramos perder.', `FemaleText_loc1`='다치지 않도록 조심하라, 필멸의 존재여. 소중한 동맹인 그대를 잃고 싶지 않도다.', `FemaleText_loc4`='凡人，好好保护自己；我们不想失去你这样宝贵的盟友。', `FemaleText_loc5`='請小心保重，凡人;你是我們的寶貴盟友，我們不想失去你。', `FemaleText_loc7`='Ten cuidado y ponte a salvo,mortal. Eres un aliado valioso que no quisieramos perder.' WHERE `ID`=32848;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 언더시티로 진군한다! 왕의 권능으로 그대들에게 힘을 주노라! 나를 따르라, 영웅들이여! 얼라이언스의 영광을 위하여!', `MaleText_loc4`='前进！攻打幽暗城！英雄们，接受国王的祝福吧！跟着我！为联盟的荣耀而战！', `MaleText_loc5`='現在前進幽暗城!分享你們國王的力量!跟著我，英雄們!為了聯盟的榮耀!', `MaleText_loc7`='¡La marcha a las Entrañas comienza ahora! ¡Reciban el poder de la fuerza de su Rey! ¡Síganme, héroes! ¡POR LA GLORIA DE LA ALIANZA!' WHERE `ID`=32849;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='몸조심 하기를, $n.', `MaleText_loc4`='保护好自己，$n。', `MaleText_loc5`='請保重，$n。', `MaleText_loc7`='Cuídate, $n.', `FemaleText_loc1`='몸조심 하기를, $n.', `FemaleText_loc4`='保护好自己，$n。', `FemaleText_loc5`='請保重，$n。', `FemaleText_loc7`='Cuídate, $n.' WHERE `ID`=32850;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳은 우리가 지키겠다. $n, 안전하게 돌아가기를 빈다.', `MaleText_loc4`='我们会继续守护这片土地，$n，希望你能平安归来。', `MaleText_loc5`='我們會守護此地，$n，並期待你平安歸來。', `MaleText_loc7`='Protegeremos este lugar, $n y esperamos que regreses a salvo.', `FemaleText_loc1`='이곳은 우리가 지키겠다. $n, 안전하게 돌아가기를 빈다.', `FemaleText_loc4`='我们会继续守护这片土地，$n，希望你能平安归来。', `FemaleText_loc5`='我們會守護此地，$n，並期待你平安歸來。', `FemaleText_loc7`='Protegeremos este lugar, $n y esperamos que regreses a salvo.' WHERE `ID`=32851;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='몸조심하십시오, $n. 그대의 언데드 몸을 전장에서 본다면 단 한 순간도 주저하지 않을 것입니다.', `MaleText_loc4`='好好保护自己，$n。如果让我看见你曝尸荒野，我大概会停留片刻向你致哀的。', `MaleText_loc5`='自己保重，$n。如果我在戰場上看到你的不死軀殼，我可能真的會遲疑一下。', `MaleText_loc7`='¡Ten cuidado contigo mismo, $n! Es posible que dudara por un momento si viese tu cuerpo no-muerto en el campo.', `FemaleText_loc1`='몸조심하세요, $n. 그대의 언데드 몸을 전장에서 본다면 단 한 순간도 주저하지 않을 테니까요.', `FemaleText_loc4`='好好保护自己，$n。如果让我看见你曝尸荒野，我大概会停留片刻向你致哀的。', `FemaleText_loc5`='自己保重，$n。如果我在戰場上看到你的不死軀殼，我可能真的會遲疑一下。', `FemaleText_loc7`='¡Ten cuidado contigo mismo, $n! Es posible que dudara por un momento si viese tu cuerpo no-muerto en el campo.' WHERE `ID`=32852;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽지 말고 살아남으십시오, $n.', `MaleText_loc4`='好好活着，$n。', `MaleText_loc5`='別玩掉自己的小命，$n。', `MaleText_loc7`='¡Intenta seguir con vida, $n!', `FemaleText_loc1`='죽지 말고 살아남기를, $n.', `FemaleText_loc4`='好好活着，$n。', `FemaleText_loc5`='別玩掉自己的小命，$n。', `FemaleText_loc7`='¡Intenta seguir con vida, $n!' WHERE `ID`=32853;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 굉장한 힘을 지니셨군요.', `MaleText_loc4`='$n，你拥有振奋人心的力量。', `MaleText_loc5`='$n，你的力量總是令人振奮。', `MaleText_loc7`='$n, tu fuerza es una fuente de inspiración.', `FemaleText_loc1`='$n, 굉장한 힘을 지니셨네요.', `FemaleText_loc4`='$n，你拥有振奋人心的力量。', `FemaleText_loc5`='$n，你的力量總是令人振奮。', `FemaleText_loc7`='$n, tu fuerza es una fuente de inspiración.' WHERE `ID`=32854;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='역병에 걸리지 않도록 조심하십시오, $n. 당신은 소중한 존재입니다.', `MaleText_loc4`='保重自己，$n。你值得拥有更美好的结局。', `MaleText_loc5`='別染上瘟疫了，$n。你應該要有更好的歸宿。', `MaleText_loc7`='Intenta no apestarte, $n. Te mereces algo mejor.', `FemaleText_loc1`='역병에 걸리지 않도록 조심하세요, $n. 당신은 소중한 존재에요.', `FemaleText_loc4`='保重自己，$n。你值得拥有更美好的结局。', `FemaleText_loc5`='別染上瘟疫了，$n。你應該要有更好的歸宿。', `FemaleText_loc7`='Intenta no apestarte, $n. Te mereces algo mejor.' WHERE `ID`=32855;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전진하라! 형제자매여! 운명이 기다린다!', `MaleText_loc4`='前进，兄弟姐妹们！命运在等待！', `MaleText_loc5`='前進，兄弟姊妹們!命運正在等待我們!', `MaleText_loc7`='¡Avancen, hermanos y hermanas! ¡El destino nos espera!' WHERE `ID`=32856;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 아직 숨 쉬는 모습을 보니 기쁘군요, $n.', `MaleText_loc4`='很高兴看到你还活着，$n。', `MaleText_loc5`='看到你還在呼吸真好，$n。', `MaleText_loc7`='Me alegra ver que aún respiras, $n.', `FemaleText_loc1`='당신이 아직 숨 쉬는 모습을 보니 기쁘네요, $n.', `FemaleText_loc4`='很高兴看到你还活着，$n。', `FemaleText_loc5`='看到你還在呼吸真好，$n。', `FemaleText_loc7`='Me alegra ver que aún respiras, $n.' WHERE `ID`=32857;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 타락의 소굴로 내려가겠다! 주위를 경계하라! 제이나, 그대의 힘을 빌려 주시오.', `MaleText_loc4`='我们即将进入这邪恶的深渊！保持警惕！吉安娜，赐予我们力量！', `MaleText_loc5`='我們即將攻入墮落與邪惡的淵藪!準備應戰!珍娜，將你的力量借給我們!', `MaleText_loc7`='¡Nuestro descenso a las profundidades de la depravación comienza! ¡Mantengan la guardia! ¡Jaina, danos tu fuerza!' WHERE `ID`=32858;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 뭐지? 제자리를 지켜라! 한 뼘도 물러나지 마라!', `MaleText_loc4`='怎么回事？！稳住阵脚！别让敌人得逞！', `MaleText_loc5`='這是什麼?!嚴陣以待!不要退縮半步!', `MaleText_loc7`='¡¿Qué es esto?! ¡Mantengan su posición! ¡No les den ni un centímetro!' WHERE `ID`=32859;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 여기 있습니다!', `MaleText_loc4`='$n！是你！', `MaleText_loc5`='$n大駕光臨!', `MaleText_loc7`='¡$n está aquí!', `FemaleText_loc1`='$n|1이;가; 여기 있어요!', `FemaleText_loc4`='$n！是你！', `FemaleText_loc5`='$n大駕光臨!', `FemaleText_loc7`='¡ $n está aquí!' WHERE `ID`=32860;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 온전한 모습을 보니 마음이 놓입니다, $n.', `MaleText_loc4`='你没事我们就放心啦，$n。', `MaleText_loc5`='看到你還完整無恙真叫人鬆了一口氣，$n。', `MaleText_loc7`='¡Qué alivio verte de una pieza, $n!', `FemaleText_loc1`='당신이 온전한 모습을 보니 마음이 놓이네요, $n.', `FemaleText_loc4`='你没事我们就放心啦，$n。', `FemaleText_loc5`='看到你還完整無恙真叫人鬆了一口氣，$n。', `FemaleText_loc7`='¡Qué alivio verte de una pieza, $n!' WHERE `ID`=32861;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 십자군을 위해 자랑스러운 일을 해주었습니다, $n!', `MaleText_loc4`='你是北伐军的骄傲，$n！', `MaleText_loc5`='你真的是十字軍的驕傲，$n!', `MaleText_loc7`='¡Eres el orgullo de la Cruzada, $n!', `FemaleText_loc1`='당신은 십자군을 위해 자랑스러운 일을 해주었어요, $n!', `FemaleText_loc4`='你是北伐军的骄傲，$n！', `FemaleText_loc5`='你真的是十字軍的驕傲，$n!', `FemaleText_loc7`='¡Eres el orgullo de la Cruzada, $n!' WHERE `ID`=32862;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n! 여전히 좋은 편에 서서 싸우고 있습니까?', `MaleText_loc4`='$n！你依然是称霸沙场的勇者吗？', `MaleText_loc5`='$n!又贏了一場漂亮的勝仗對吧?', `MaleText_loc7`='¡$n! ¿Sigues al pie del cañón?', `FemaleText_loc1`='$n! 여전히 좋은 편에 서서 싸우고 있나요?', `FemaleText_loc4`='$n！你依然是称霸沙场的勇者吗？', `FemaleText_loc5`='$n!又贏了一場漂亮的勝仗對吧?', `FemaleText_loc7`='¡$n! ¿Sigues al pie del cañón?' WHERE `ID`=32863;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 우리가 여기서 작전을 펼치는 데 있어서 없어서는 안 될 존재입니다, $n.', `MaleText_loc4`='我们在这里的军事行动少不了你的帮助，$n。', `MaleText_loc5`='你對我們這邊的運作真是不可或缺，$n。', `MaleText_loc7`='Eres un integrante de nuestra operación aquí, $n.', `FemaleText_loc1`='당신은 우리가 여기서 작전을 펼치는 데 있어서 없어서는 안 될 존재에요, $n.', `FemaleText_loc4`='我们在这里的军事行动少不了你的帮助，$n。', `FemaleText_loc5`='你對我們這邊的運作真是不可或缺，$n。', `FemaleText_loc7`='Eres un integrante de nuestra operación aquí, $n.' WHERE `ID`=32864;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그리하지요, 폐하!', `FemaleText_loc4`='遵命，陛下！', `FemaleText_loc5`='遵命，陛下!', `FemaleText_loc7`='¡Inmediatamente, su majestad!' WHERE `ID`=32865;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기 가시는 최고의 $c|1과;와; 알고 지내는 영광을 누리고 싶군요.', `MaleText_loc4`='能认识你这样杰出的$c，真是我的荣幸。', `MaleText_loc5`='我有幸認識的最強$c來了。', `MaleText_loc7`='Ahí va $gel mejor:la mejor:c;$c que he tenido el honor de conocer.', `FemaleText_loc1`='저기 가시는 최고의 $c|1과;와; 알고 지내는 영광을 누리고 싶네요.', `FemaleText_loc4`='能认识你这样杰出的$c，真是我的荣幸。', `FemaleText_loc5`='我有幸認識的最強$c來了。', `FemaleText_loc7`='Ahí va $gel mejor:la mejor:c;$c que he tenido el honor de conocer.' WHERE `ID`=32866;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 당신은 정말 근사한 분이군요.', `MaleText_loc4`='$n，你的精神鼓舞着我们。', `MaleText_loc5`='$n，你可真是振奮人心。', `MaleText_loc7`='$n, eres una fuente de inspiración.', `FemaleText_loc1`='$n, 당신은 정말 근사한 분이네요.', `FemaleText_loc4`='$n，你的精神鼓舞着我们。', `FemaleText_loc5`='$n，你可真是振奮人心。', `FemaleText_loc7`='$n, eres una fuente de inspiración.' WHERE `ID`=32867;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='완벽한 $g청년:아가씨;의 표상이 바로 저 $n 님이십니다.', `MaleText_loc4`='$n是一个好榜样。', `MaleText_loc5`='一個$g男子漢:女豪傑;的最佳榜樣，$n。', `MaleText_loc7`='$n es un claro ejemplo de humanidad.', `FemaleText_loc1`='완벽한 $g청년:아가씨;의 표상이 바로 저 $n 님이시죠.', `FemaleText_loc4`='$n是一个好榜样。', `FemaleText_loc5`='一個$g男子漢:女豪傑;的最佳榜樣，$n。', `FemaleText_loc7`='$n es un claro ejemplo de humanidad.' WHERE `ID`=32868;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님보다 더 멋진 분은 아무리 눈을 씻고 찾아봐도 찾을 수 없을 겁니다, 그럼요.', `MaleText_loc4`='我敢说，再也找不到比$n更出色的人了。', `MaleText_loc5`='我說，你不可能認識比$n更棒的人了。', `MaleText_loc7`='Te digo que no podrías encontrar a nadie mejor que $n.', `FemaleText_loc1`='$n 님보다 더 멋진 분은 아무리 눈을 씻고 찾아봐도 찾을 수 없을 거예요, 그렇고 말고요.', `FemaleText_loc4`='我敢说，再也找不到比$n更出色的人了。', `FemaleText_loc5`='我說，你不可能認識比$n更棒的人了。', `FemaleText_loc7`='Te digo que no podrías encontrar a nadie mejor que $n.' WHERE `ID`=32869;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님, 당신을 만나보다니 너무나 멋진 일입니다. 정말 멋져요.', `MaleText_loc4`='$n，见到你真是太好啦。真的。', `MaleText_loc5`='$n，看到你真是太好了。太好了。', `MaleText_loc7`='$n, es estupendo volver a verte. ¡Estupendo!', `FemaleText_loc1`='$n 님, 당신을 만나보다니 너무나 멋진 일이군요. 정말 멋져요.', `FemaleText_loc4`='$n，见到你真是太好啦。真的。', `FemaleText_loc5`='$n，看到你真是太好了。太好了。', `FemaleText_loc7`='$n, es estupendo volver a verte. ¡Estupendo!' WHERE `ID`=32870;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님! 건강하신 모습을 뵈니 너무나 좋습니다. 변함없이 바쁘시군요?', `MaleText_loc4`='$n！啊，见到你真是太好啦。你还是很忙吗？', `MaleText_loc5`='$n!噢，看到你在外頭走動真是太棒了。還是跟往常一樣忙碌?', `MaleText_loc7`='¡$n! Ah, es fantástico verte por aquí. Como siempre, tendrás mucho que hacer, ¿eh?', `FemaleText_loc1`='$n 님! 건강하신 모습을 뵈니 너무나 좋네요. 변함없이 바쁘시지요?', `FemaleText_loc4`='$n！啊，见到你真是太好啦。你还是很忙吗？', `FemaleText_loc5`='$n!噢，看到你在外頭走動真是太棒了。還是跟往常一樣忙碌?', `FemaleText_loc7`='¡$n! Ah, es fantástico verte por aquí. Como siempre, tendrás mucho que hacer, ¿eh?' WHERE `ID`=32871;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용군단의 친구이자 동맹이신 분이시여, 그대는 언제나 환영입니다. 여기에서 편히 쉬시기를.', `MaleText_loc4`='欢迎你，龙族的朋友和盟友。请在大厅好好休息吧。', `MaleText_loc5`='歡迎，龍族軍團的盟友。在我們的廳堂休息吧。', `MaleText_loc7`='Sé $gbienvenido:bienvenida; aquí, $gamigo:amiga; y $galiado:aliada; de los Vuelos. Descansa en nuestras salas.' WHERE `ID`=32872;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아 그대였군요, $n! 저희 성소에 오시다니 반갑습니다. 쉬시면서 기운을 회복하시지요. 생각보다 훨씬 편하실 겁니다.', `MaleText_loc4`='啊，是你，$n！欢迎来到我们的圣殿。在这里好好休息一下，这是你应得的权利。', `MaleText_loc5`='喔，是你，$n!歡迎來到我們的聖堂。在這裡好好休息放鬆，你對我們的貢獻無以為報。', `MaleText_loc7`='¡Ah, eres tú, $n! $gBienvenido:Bienvenida; a nuestro santuario. Descansa y recupera fuerzas, te lo has ganado.' WHERE `ID`=32873;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일어나라, 신드라고사! 일어나 서리고룡족을 이끌고 전쟁터로 향하라!', `MaleText_loc4`='复活吧，辛达苟萨！带领霜巢巨龙投入战斗！', `MaleText_loc5`='甦醒，辛德拉苟莎!甦醒並且率領霜育龍群出征!', `MaleText_loc7`='¡Álzate, Sindragosa! ¡Álzate y guía a los Razaescarcha a la guerra!' WHERE `ID`=32874;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법의 뒤안길 악어가 입맛을 다시며 굶주린 눈빛으로 당신을 응시합니다.', `MaleText_loc4`='下水道巨鳄垂涎欲滴地盯着你。', `MaleText_loc5`='城底鱷魚飢餓地盯著你並且舔著牠的嘴唇。', `MaleText_loc7`='El crocolisco de Los Bajos Fondos te mira hambriento y se relame.', `FemaleText_loc1`='마법의 뒤안길 악어가 입맛을 다시며 굶주린 눈빛으로 당신을 응시합니다.', `FemaleText_loc4`='下水道巨鳄垂涎欲滴地盯着你。', `FemaleText_loc5`='城底鱷魚飢餓地盯著你並且舔著牠的嘴唇。', `FemaleText_loc7`='El crocolisco de Los Bajos Fondos te mira hambriento y se relame.' WHERE `ID`=32875;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리를 보라고, 엘프. 지금 우리 모습을 보란 말이야. 직업도 없고, 가난한데다 청소부 독수리 이름이 붙은 하수도 시설에서 구정물이나 마시고 있잖아.', `MaleText_loc4`='你瞧瞧我们俩，瞧瞧。失业，穷困潦倒，整天躲在下水道这家以食腐鸟命名的破旅店借酒浇愁！', `MaleText_loc5`='看看我們，精靈。看看我們。沒有工作，窮得要死。然後只能在下水道裡一間用以食腐鳥為名的破房子喝酒!', `MaleText_loc7`='Fíjate en nosotros, elfo. Fíjate bien. Sin trabajo, sin hogar y ahogándonos en la bebida de un establecimiento en las cloacas con nombre de carroñero.' WHERE `ID`=32877;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구역질 나는 일이지, 동감이야.', `MaleText_loc4`='是啊，我也很厌倦目前的生活。', `MaleText_loc5`='確實很噁心，我同意。', `MaleText_loc7`='Asqueroso, estoy de acuerdo.' WHERE `ID`=32878;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 무엇보다도, 내가 너한테 얹혀 있다는 걸 깨달았어. 내가 하던 일을 잃게 한 바로 그 당사자에게 말이야!', `MaleText_loc4`='更要命的是，我居然还和你搅和在一起！就是你害我丢了沙塔斯城的工作！', `MaleText_loc5`='而最糟糕的是，我居然跟你坐在一起，就是你一開始讓我丟了工作!', `MaleText_loc7`='Y sobre todo, no sé cómo te estoy endilgando, a ti, el hombre que hizo que perdiera mi trabajo primero.' WHERE `ID`=32879;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그거야 네 사정이지, 내 사정이 아니라고, 이 입만 산 놈아. 네가 잘못하는 바람에 나도 직업을 잃었단 말이다.', `MaleText_loc4`='你这该死的酒鬼！分明是你的错，别怪到我头上。我只所以会失业，还不是因为你把事情搞砸了！我真是倒霉！', `MaleText_loc5`='那是你的問題，與我無關，只會說大話的傢伙。我會丟掉工作都是因為我不幸地被你的失敗所牽連。', `MaleText_loc7`='Eso es cosa tuya, no mía, charlatán. No tengo trabajo por mi desafortunada relación con tu error.' WHERE `ID`=32880;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 잘못이라고?! 내 잘못?! 네가 무능하니 우리가 여기 착륙한 거잖아, 이 해삼, 멍게, 말미잘 같은 놈아!', `MaleText_loc4`='是我把事情搞砸的？！是我吗？！是因为你无能！我们之所以这么落魄，都是拜你所赐！', `MaleText_loc5`='我的失敗?!我的失敗?!還不是因為你的無能導致我們兩個淪落到這兒來，你這無能的智障!', `MaleText_loc7`='¿Culpa mía? ¿CULPA MÍA? ¡Hemos aterrizado aquí por tu incompetencia, imbécil insoportable!' WHERE `ID`=32881;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 못 들은 척 눈을 굴립니다.', `MaleText_loc4`='%s转了转眼珠。', `MaleText_loc5`='%s翻了翻白眼。', `MaleText_loc7`='%s pone los ojos en blanco.' WHERE `ID`=32882;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만해, 자다르. 몇 달 동안 네 입에서 같은 소리 듣고 또 들었어. 무슨 일이 있었든 간에, 요점은 우리가 자유라는 거야! 쓸데없는 정책이나 임무에 묶일 필요도 없고, 어디든지 우리 마음대로 돌아다닐 수 있다고!', `MaleText_loc4`='你给我闭嘴，亚达尔。你已经抱怨了好几个月，烦不烦啊。不管怎么样，我们现在自由啦！你想想，我们再也不用当差，不用面对政治纷争，乐得消遥自在！', `MaleText_loc5`='少來了，賈達。我已經聽你這樣的抱怨好幾個月了。不管到底發生了什麼事，現在我們都是自由工作者了!不用再受制於官方或職責，可以隨心所欲!', `MaleText_loc7`='Anda ya, Jadaar. Es lo único que he escuchado de ti en meses. No importa lo que pasó, el tema es que ahora somos agentes libres. Ya no estamos sometidos a la política ni a los deberes, podemos ir por donde queramos.' WHERE `ID`=32883;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='땡전 한 푼 없고 아는 거라고는 하나도 없는 데다 얼어붙고 언데드가 득시글거리는 북쪽 땅 한복판에서 돌아다닐 자유가 퍽 좋기도 하겠다.', `MaleText_loc4`='是啊，我们背井离乡，身无分文，孤零零地呆在这片亡灵肆虐的极北荒地。', `MaleText_loc5`='身無分文然後遠離家園，在這個冰天雪地、不死生物橫行的北方大陸之中。', `MaleText_loc7`='Sin una moneda y lejos de lo que conocemos en el medio de las tierras heladas e infestadas de no-muertos del norte.' WHERE `ID`=32884;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어쩌면, 우리 이름을 드날릴 기회가 올지도 몰라! 네가 아제로스의 구세주이자 스컬지 해결사로 샤트라스에서 영접받는 광경을 생각해봐!', `MaleText_loc4`='或许吧，但是我们很有机会出名啊！你想想，我们在沙塔斯城的时候是多么受欢迎啊，我们是艾泽拉斯的救星，是天灾军团的克星！', `MaleText_loc5`='或許，這是我們自己揚名立萬的機會!想想如果成為艾澤拉斯的救星，天譴殺手!你會在撒塔斯受到怎樣的歡迎!', `MaleText_loc7`='Quizás, pero con la oportunidad de hacernos notar. ¡Piensa en el recibimiento que tendrías en Shattrath como el salvador de Azeroth, asesino de la Plaga!' WHERE `ID`=32885;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음... 어쩌면 말이지. 일단 한 잔 더 마시고.', `MaleText_loc4`='呃……你说的也有一定道理。再来一杯吧。', `MaleText_loc5`='呃...或許吧，等我再喝一杯。', `MaleText_loc7`='Eh… tal vez, tras otra bebida.' WHERE `ID`=32886;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 왜 꾹꾹 참으면서까지 너와 지내야 하는지 다시 한번 얘기해봐, 아스릭.', `MaleText_loc4`='艾斯瑞克，我又想起了为什么我至今还能容忍你的原因。', `MaleText_loc5`='記得提醒我為什麼要容忍你這個傢伙，亞斯里克。', `MaleText_loc7`='Vuelve a recordarme por qué tolero tu compañía, Asric.' WHERE `ID`=32887;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 썩은 미소를 짓습니다.', `MaleText_loc4`='%s冷笑了一声。', `MaleText_loc5`='%s挖苦地冷笑。', `MaleText_loc7`='%s sonríe con ironía.' WHERE `ID`=32888;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈 같은 허풍선이를 다루는 연습을 몇십 년은 했거든. 그리고 이 더럽게 추운 땅에서 네가 아는 유일한 존재가 나잖아.', `MaleText_loc4`='我和你打了几十年的交道，听够了你天花乱坠的大话。而在这片萧条的冰原上，我是你唯一认识的人。', `MaleText_loc5`='因為應付像你這種吹牛鬼我有幾十年的經驗，而且我是你在這個糟糕透頂的冰冷鬼地方唯一認識的人。', `MaleText_loc7`='Tengo siglos de práctica tratando con fanfarrones como tú y soy el único al que conoces en esta abominable tierra helada.' WHERE `ID`=32889;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭풍우 봉우리로 갈 준비가 되었습니다.', `MaleText_loc4`='我准备好进入风暴峭壁了。', `MaleText_loc5`='我已經準備好前往風暴群山。', `MaleText_loc7`='Estoy listo para dirigirme más allá de Las Cumbre Tormentosas.', `FemaleText_loc1`='폭풍우 봉우리로 갈 준비가 되었어요.', `FemaleText_loc4`='我准备好进入风暴峭壁了。', `FemaleText_loc5`='我已經準備好前往風暴群山。', `FemaleText_loc7`='Estoy lista para dirigirme más allá de Las Cumbre Tormentosas.' WHERE `ID`=32890;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너를 이 시궁창에서 쓰레기와 함께 썩어가도록 내버려두고 떠나야겠어.', `MaleText_loc4`='我真应该让你烂死在这个下水道里。', `MaleText_loc5`='我應該任由你在下水道的污泥中腐爛。', `MaleText_loc7`='Debería dejar que te pudrieses en esta cloaca con la mugre.' WHERE `ID`=32891;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러시든지.', `MaleText_loc4`='嗯，我知道你会这么想。', `MaleText_loc5`='我一點也不懷疑。', `MaleText_loc7`='Sin duda.' WHERE `ID`=32892;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너와 함께 있다는 그 자체만으로도 내가 지닌 믿음에 금이 간다고.', `MaleText_loc4`='容许你的存在简直侮辱了我的信仰。', `MaleText_loc5`='光是待在你附近就污衊了我的信仰。', `MaleText_loc7`='Tan solo estar en tu presencia es una afrenta a mis creencias.' WHERE `ID`=32893;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 물론 그러시겠지.', `MaleText_loc4`='嗯，是啊。', `MaleText_loc5`='喔，當然。', `MaleText_loc7`='Oh, claro.' WHERE `ID`=32894;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 나보다 한 수 아래야.', `MaleText_loc4`='你比我差劲多了。', `MaleText_loc5`='你比我低劣得多。', `MaleText_loc7`='No eres digno de mí.' WHERE `ID`=32895;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미천한 벌레일 뿐이지. 그렇고말고.', `MaleText_loc4`='是啊，我是一只低级的爬虫。', `MaleText_loc5`='一隻低劣的蠕蟲，我懂。', `MaleText_loc7`='Un humilde gusano, seguro.' WHERE `ID`=32896;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뱀 같은 자식.', `MaleText_loc4`='你是一条蛇。', `MaleText_loc5`='毒蛇。', `MaleText_loc7`='Serpiente.' WHERE `ID`=32897;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러면, 뱀이라고 하지 뭐. 그렇게 부르고 싶다면 말이야.', `MaleText_loc4`='好吧，如果你更喜欢蛇的话，那我就是一条蛇。', `MaleText_loc5`='毒蛇，好，你喜歡就好。', `MaleText_loc7`='Serpiente, entonces, si prefieres.' WHERE `ID`=32898;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 말에 맞장구 그만 쳐!', `MaleText_loc4`='别再附和我说的话！', `MaleText_loc5`='不准再附和我!', `MaleText_loc7`='Ya basta de darme la razón.' WHERE `ID`=32899;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 네 말이 맞아. 맞장구는 정말 끔찍해.', `MaleText_loc4`='嗯嗯，你说得对。这是一种可怕的行为。', `MaleText_loc5`='你是對的，當然，這真是個糟糕的練習。', `MaleText_loc7`='Tienes razón, por supuesto. Es una práctica horrible.' WHERE `ID`=32900;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으악!', `MaleText_loc4`='啊！', `MaleText_loc5`='噢!', `MaleText_loc7`='¡AGH!' WHERE `ID`=32901;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가증스러운 놈.', `MaleText_loc4`='獐头鼠目。', `MaleText_loc5`='傲慢的傢伙。', `MaleText_loc7`='Arrogante.' WHERE `ID`=32902;
