UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다중인격인 놈.', `MaleText_loc4`='人穷志短。', `MaleText_loc5`='懦夫。', `MaleText_loc7`='Cobarde.' WHERE `ID`=32904;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다중인격이라고? 그건 절대 아니야! 그때 우리 같이 그 전투 한복판에서... 이런.', `MaleText_loc4`='你才人穷志短呢？！玩文字接龙的时候干嘛提这个……啊。', `MaleText_loc5`='懦夫?!我絕對不是1我們難道不是在身在一場戰爭中...啐。', `MaleText_loc7`='¡¿Cobarde?! Te aseguro que no. Acaso no estamos en el medio de una guerra… ah.' WHERE `ID`=32905;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 엿 먹으라는 시늉을 합니다.', `MaleText_loc4`='%s竖起一根手指。', `MaleText_loc5`='%s舉起一根手指。', `MaleText_loc7`='%s levanta un dedo.' WHERE `ID`=32906;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디까지 했더라? ''마''로 시작할 차례던가?', `MaleText_loc4`='呃……到哪个字了？“短”？', `MaleText_loc5`='我們講到哪裡了?啊?', `MaleText_loc7`='¿Por dónde íbamos? ¿''D''?' WHERE `ID`=32907;
