UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마귀 같은 놈.', `MaleText_loc4`='短……短吃少穿。', `MaleText_loc5`='傻瓜。', `MaleText_loc7`='Estúpido.' WHERE `ID`=32909;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이여;여;, 여왕과 볼일을 마치는 대로 그대와 이야기하기를 원하노라.', `MaleText_loc4`='$n，等女王的事情完结之后，你必须和我谈一谈。', `MaleText_loc5`='$n，等龍后見完你，我們一定得談談。', `MaleText_loc7`='$n, debemos hablar cuando la reina haya terminado contigo.' WHERE `ID`=32910;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='끝났도다. 이제 집중의 눈동자를 열 수 있으리라.', `FemaleText_loc4`='好啦。现在，你可以打开聚焦之虹了。', `FemaleText_loc5`='完成了。你現在可以開啟聚源虹膜了。', `FemaleText_loc7`='Listo. Ahora puedes abrir el Iris de enfoque.' WHERE `ID`=32911;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽을 준비해라!', `MaleText_loc4`='去死吧！', `MaleText_loc5`='準備受死吧!', `MaleText_loc7`='¡Prepárate para morir!' WHERE `ID`=32912;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는.로봇.입니다.', `MaleText_loc4`='我·是·机器人。', `MaleText_loc5`='我 是 個 機 器 人。', `MaleText_loc7`='Soy.un.robot.' WHERE `ID`=32913;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이상 작동. 오류 코드: .-.-.-', `MaleText_loc4`='操作错误。密码错误：.- .- .-', `MaleText_loc5`='故障。錯誤代碼: .- .- .-', `MaleText_loc7`='Disfunción. Código erróneo: .- .- .-' WHERE `ID`=32914;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<당신이 있음을 알아차리고 고개를 끄덕여 인사하는 여왕의 배우자>', `MaleText_loc4`='<女王的伴侣对你点了点头。>', `MaleText_loc5`='<龍后的伴侶點點頭，認可了你的出現。>', `MaleText_loc7`='<El consorte de la Reina baja la cabeza consciente de tu presencia.>' WHERE `ID`=32915;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='추후 공지가 있을 때까진 당신의 요청을 들어 드릴 수 없어요. 폭격기도 좀 식혀야죠. 다음 출격 때는 더 조심하세요!', `FemaleText_loc4`='你的请求已被驳回，请等候下次通知。关掉引擎，下次行动最好当心点！', `FemaleText_loc5`='你的任務已經取消了，需要等候進一步通知。讓你的噴射引擎冷卻一下，在外頭要更小心!', `FemaleText_loc7`='Han revocado tus ordenes hasta nuevo aviso. ¡Apaga tus cazas e intenta tener más cuidado ahí fuera!' WHERE `ID`=32916;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='폭격기를 끌고 여러 번 전장에 나가셨는데 이렇다 할 실적은 없네요. 더 조심해서 작전에 임하세요. 그렇지 않으면 저희도 폭격기를 내어 드릴 수 없어요...', `FemaleText_loc4`='你执行过很多次轰炸任务了，但是表现得非常一般啊。你最好当心点，不然我就吊销你的飞行执照……', `FemaleText_loc5`='你已經開了太多次轟炸機了，不要太得意。小心一點否則你的飛行權限就等著取消吧...', `FemaleText_loc7`='Has alcanzado muchos bombarderos y no tienes casi nada. Ten más cuidado o se revocarán tus privilegios de vuelo.' WHERE `ID`=32917;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너의 심장과 인간으로서의 본성이 네 발목을 잡고 있다, 아서스.', `MaleText_loc4`='阿尔萨斯，残存在你心中的人性令你止步不前。', `MaleText_loc5`='你的心與你的人性侷限了你，阿薩斯。', `MaleText_loc7`='Tu corazón y tu humanidad te reprimen, Arthas.' WHERE `ID`=32918;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오늘도 비행하느라 정신없으셨겠어요, 안 그래요, $n? 다음번 출격 때까지 휴식을 좀 취하는 게 좋겠어요.', `FemaleText_loc4`='$n，繁忙的航程是吧？在返回战场之前，你最好先喘口气。', `FemaleText_loc5`='今天的天空想必很忙碌，對吧，$n?也許你應該要休息一下，等會兒再出發。', `FemaleText_loc7`='Ha sido un día muy ocupado en el aire, ¿eh, $n? Quizás deberías descansar un rato antes de volver.' WHERE `ID`=32919;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 인간 본성을 버려라. 그러면 다시는 피 흘리지 않을 것이다!', `MaleText_loc4`='摒弃你的人性吧，这样你就再也不会流血了！', `MaleText_loc5`='拋下你的人性，你將會永遠不再受創!', `MaleText_loc7`='¡Líbrate de tu humanidad y nunca volverás a sangrar!' WHERE `ID`=32920;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='걱정하지 마라, 아서스. 곧 심장 따윈 필요 없을 테니까.', `MaleText_loc4`='阿尔萨斯，别担心。很快你就不再需要那颗心了。', `MaleText_loc5`='別擔心，阿薩斯。很快地，你將不再需要你的心。', `MaleText_loc7`='No te preocupes, Arthas. Pronto no necesitarás tu corazón.' WHERE `ID`=32921;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신에게 폭격기를 내주지 말라는 명령을 막 받았어요, $n. 다음에 다시 오세요. 그땐 출격할 수 있을 거예요.', `FemaleText_loc4`='我刚得到命令，决定撤消你的飞行资格，$n。稍后再来找我吧，我们会让你重返轰炸机的。', `FemaleText_loc5`='我接到命令要暫時撤銷你的飛行權限，$n。晚點再回來，我們會讓你回到轟炸機上。', `FemaleText_loc7`='Tengo órdenes de ignorar tu prioridad de vuelo, $n. Vuelve más tarde y dejaremos que te hagas con un bombardero.' WHERE `ID`=32922;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 몸속의 피는 너에게 방해만 될 뿐이다. 모든 감정을 버려라!', `MaleText_loc4`='你的体内流淌着人类的鲜血，这只会令你受伤。摈弃所有凡人的情感吧！', `MaleText_loc5`='你血脈中的人類鮮血只不過是一種損害。捨棄你一切的情緒!', `MaleText_loc7`='La sangre humana que corre por tus venas no es más que un perjuicio. ¡Líbrate de todas las emociones!' WHERE `ID`=32923;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 가슴의 통증은 곧 사라지고... 다시는 돌아오지 않을 것이다!', `MaleText_loc4`='折磨你的痛苦很快就会消失了……你再也不会因此困扰了！', `MaleText_loc5`='你胸膛中的痛楚很快就會消失...永遠不再回來!', `MaleText_loc7`='¡El dolor de tu pecho pronto se desvanecerá… nunca regresará!' WHERE `ID`=32924;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='폭격기 날려 먹기를 밥 먹듯이 하셨네요. 날려 먹는 게 재미있을지는 모르겠지만, 조심하지 않으시면 폭격기를 더 내어 드릴 수 없어요...', `FemaleText_loc4`='你轰炸起敌人来还真厉害，但是你自己也被炸得够呛啊。这听上去很好笑，不过你最好当心点，不然我就不给你轰炸机了……', `FemaleText_loc5`='你一邊把敵人炸飛，也一邊忙著把自己炸飛。聽起來很有趣，但是要小心，否則我就不會再給你炸彈了...', `FemaleText_loc7`='Has estado tan $gocupado:ocupada; volando por los aires que has hecho volar por los aires a los adversarios. Suena divertido pero ten cuidado o dejaré de darte bombarderos..' WHERE `ID`=32925;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신 작전 수행하는 거 보면 정말 재미있어요! 이제까지 몰아 본 폭격기만 해도 꽤 되죠?', `FemaleText_loc4`='老实说，看你轰炸真是有趣！你肯定开过不少轰炸机吧！', `FemaleText_loc5`='我告訴你，看你工作真的很有趣!你一定開過很多次轟炸機!', `FemaleText_loc7`='¡Lo que yo te diga, seguro que es divertido verte trabajando!¡ Y seguro que vas a por un montón de bombarderos!' WHERE `ID`=32926;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 찾았군, 아서스.', `MaleText_loc4`='我终于追上你了，阿尔萨斯。', `MaleText_loc5`='我終於逮到你了，阿薩斯。', `MaleText_loc7`='Al fin te he alcanzado, Arthas.' WHERE `ID`=32927;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대연금술사 퓨트리스가 게걸스러운 파멸의 역병충을 풀어놓습니다!', `MaleText_loc4`='大药剂师普特雷斯释放了充血的凋零虫！', `MaleText_loc5`='大藥劑師普崔司釋放了腫脹的荒疫蟲!', `MaleText_loc7`='¡El Gran Boticario Putress desata el gusano de añublo atiborrado!' WHERE `ID`=32928;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰하트 왕께서 서릿결 부족원이 하는 시험을 거치라고 이리로 보내셨습니다. 피욜린, 시험에 임할 준비가 되었습니다.', `MaleText_loc4`='雷心国王派我来参加霜脉矮人的试炼。我已经准备好了，弗亚林。', `MaleText_loc5`='風暴之心國王派我來接受霜誕矮人應有的考驗。我已經準備好接受試煉了，弗尤林。', `MaleText_loc7`='El rey Cuoretormenta me ha mandado para que se me ponga a prueba como si fuera un Natoescarcha. Fjorlin, estoy listo para mi prueba.', `FemaleText_loc1`='스톰하트 왕께서 서릿결 부족원이 하는 시험을 거치라고 이리로 보내셨어요. 피욜린, 시험에 임할 준비가 되었어요.', `FemaleText_loc4`='雷心国王派我来参加霜脉矮人的试炼。我已经准备好了，弗亚林。', `FemaleText_loc5`='風暴之心國王派我來接受霜誕矮人應有的考驗。我已經準備好接受試煉了，弗尤林。', `FemaleText_loc7`='El rey Cuoretormenta me ha mandado para que se me ponga a prueba como si fuera un Natoescarcha. Fjorlin, estoy lista para mi prueba.' WHERE `ID`=32929;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고룡과 맞서 싸울 준비가 되었습니다. 제가 타고 갈 독수리를 마련해 두셨습니까, 피욜린?', `MaleText_loc4`='我要参加对抗巨龙的战斗。能给我一只雄鹰吗，弗亚林？', `MaleText_loc5`='我已經加入過對抗巨龍的戰鬥。你已經準備好雄鷹了嗎，弗尤林?', `MaleText_loc7`='Estoy listo para unirme a la batalla contra las vermis. ¿Tienes un águila lista para mí, Fjorlin?', `FemaleText_loc1`='고룡과 맞서 싸울 준비가 되었어요. 제가 타고 갈 독수리를 마련해 두셨나요, 피욜린?', `FemaleText_loc4`='我要参加对抗巨龙的战斗。能给我一只雄鹰吗，弗亚林？', `FemaleText_loc5`='我已經加入過對抗巨龍的戰鬥。你已經準備好雄鷹了嗎，弗尤林?', `FemaleText_loc7`='Estoy lista para unirme a la batalla contra las vermis. ¿Tienes un águila lista para mí, Fjorlin?' WHERE `ID`=32930;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하게, $n. 이교도 로브는 어디 있나?', `MaleText_loc4`='当心，$n。你的教徒长袍呢？', `MaleText_loc5`='自己當心，$n。你的教徒長袍呢?', `MaleText_loc7`='Cuidado, $n. ¿Dónde están tus togas de cultor?' WHERE `ID`=32931;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 있었군. 준비 다 끝났나? 일단 출발하면 되돌아올 수 없다네.', `MaleText_loc4`='给。准备好了吗？一旦我们开始行动，就不能回头了。', `MaleText_loc5`='嗯。你準備好了嗎?一旦我們開始，就沒有回頭的機會了。', `MaleText_loc7`='Aquí estás. Entonces, ¿estás $glisto:lista;? Una vez hayamos empezado, no habrá vuelta atrás.' WHERE `ID`=32932;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 준비됐습니다. 대영주님.', `MaleText_loc4`='我准备好了，大领主。', `MaleText_loc5`='我準備好了，大領主。', `MaleText_loc7`='Estoy listo, alto señor.', `FemaleText_loc1`='전 준비됐습니다. 대영주님.', `FemaleText_loc4`='我准备好了，大领主。', `FemaleText_loc5`='我準備好了，大領主。', `FemaleText_loc7`='Estoy lista, alto señor.' WHERE `ID`=32933;
