UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오십시오.', `MaleText_loc4`='欢迎。', `MaleText_loc5`='歡迎。', `MaleText_loc7`='$gBienvenido:Bienvenida;.', `FemaleText_loc1`='어서 오세요.', `FemaleText_loc4`='欢迎。', `FemaleText_loc5`='歡迎。', `FemaleText_loc7`='$gBienvenido:Bienvenida;.' WHERE `ID`=32936;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이따위 돌연변이로는 얼라이언스에 상대도 안 된다. 우리가 간다, 퓨트리스!', `MaleText_loc4`='这些畸形的野兽挡不住联盟！普特雷斯，等着瞧吧！', `MaleText_loc5`='你的變種怪物根本不是聯盟的對手，普崔司!我們來找你了!', `MaleText_loc7`='¡Tus aberraciones son inferiores a la Alianza, Putress! ¡Vamos por ti!' WHERE `ID`=32937;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='병사들, 집합! 통로를 경계하라!', `MaleText_loc4`='士兵们，集合！保卫大厅！', `MaleText_loc5`='士兵們，集合!守住大廳!', `MaleText_loc7`='¡Soldados, ya! ¡Protejan los salones!' WHERE `ID`=32938;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무슨 일이었을까요? 시체가 사방에 널려있고... 끔찍한 냄새에... 엄청나군요.', `FemaleText_loc4`='究竟发生了什么事？到处都是尸体……恶臭熏天……', `FemaleText_loc5`='發生了什麼事?到處都是屍體...那股味道...令人難以忍受...', `FemaleText_loc7`='¿Qué ocurrió aquí? Hay cadáveres por todos lados... la peste... abrumadora…' WHERE `ID`=32939;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드로군. 전투 흔적을 보니 여기 대규모 부대가 온 모양이다. 어딘가에 말이지.', `MaleText_loc4`='是部落。看这种情形，他们的军队应该，就在附近。', `MaleText_loc5`='是部落。從這衝突的態勢看來他們也在這裡的...某處。', `MaleText_loc7`='Horda. Por la apariencia de la pelea, están por aquí... En alguna parte.' WHERE `ID`=32940;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경계를 늦추지 마라. 어떤 끔찍한 일이 기다리고 있을지 모른다.', `MaleText_loc4`='保持警惕。我们不知道前面会有怎样的恐怖。', `MaleText_loc5`='保持警戒。誰也不知道這裡有什麼恐怖的東西等著我們。', `MaleText_loc7`='Manténganse alerta y en guardia. Quién sabe qué horrores nos esperan.' WHERE `ID`=32941;
