UPDATE `locales_broadcast_text` SET `MaleText_loc1`='처치하라! 저들이 방해하지 못하게 하라!', `MaleText_loc4`='杀死他们！不能让他们干扰我的行动！', `MaleText_loc5`='殺光他們!!!我的工作不能被干擾!', `MaleText_loc7`='¡MÁTENLOS! ¡Mi trabajo no debe ser interrumpido!' WHERE `ID`=32944;
