UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 끝날 수는 없어! 얼마나 애를 썼는데! 더... 더 많은 기운을 삼키겠다!', `MaleText_loc4`='我不会束手就擒！我做了这么多的努力！这些年来……我……我需要更多的能量！', `MaleText_loc5`='不會就這樣結束的!我所有的努力!這麼多年...我...我會吸收更多的能量!', `MaleText_loc7`='¡No terminará así! ¡He trabajado demasiado! Tantos años... Yo... ¡Consumiré más energía!' WHERE `ID`=32948;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='심연과 마주하고 물들어가는 네 영혼을 봐라!', `MaleText_loc4`='凝视深渊吧，它将吞噬你们的灵魂！', `MaleText_loc5`='凝視深淵並且看著它污染你的靈魂!', `MaleText_loc7`='¡Contemplen el abismo y vean cómo ennegrece sus almas!' WHERE `ID`=32949;
