UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요술쟁이 휴게실에 오신 걸 환영합니다. 이곳에서 머무시면서 즐겁게 지내시길 바랍니다.', `MaleText_loc4`='欢迎来到魔术旅馆，$c。祝你愉快。', `MaleText_loc5`='歡迎來到戲法旅舍，$c。希望你一切滿意。', `MaleText_loc7`='$gBienvenido:Bienvenida; al Salón de Juego de Manos, $c. Espero que disfrutes de tu estancia.', `FemaleText_loc1`='요술쟁이 휴게실에 오신 걸 환영합니다. 이곳에서 머무시면서 즐겁게 지내시길 바랍니다.', `FemaleText_loc4`='欢迎来到魔术旅馆，$c。祝你愉快。', `FemaleText_loc5`='歡迎來到戲法旅舍，$c。希望你一切滿意。', `FemaleText_loc7`='$gBienvenido:Bienvenida; al Salón de Juego de Manos, $c. Espero que disfrutes de tu estancia.' WHERE `ID`=32954;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법과 까마귀 선술집에 오신 걸 환영합니다.$B$B이곳에 있는 동안 뒤를 조심하셔야 할 겁니다. 나리사는 바닥에 튄 혈흔을 문질러 닦는 걸 좋아하지 않거든요.', `MaleText_loc4`='欢迎来到咒语和乌鸦旅店，$r。$B$B你最好当心点。纳莉萨不喜欢擦拭地板上的血迹。', `MaleText_loc5`='歡迎來到咒語與烏鴉酒店，$r。$B$B在這裡的時候自己當心，懂吧?娜莉莎不喜歡擦地板上的血跡。', `MaleText_loc7`='$gBienvenido:Bienvenida; a la Taberna de los Cuervos, $r.$B$BVigila tus espaldas mientras estás aquí, eh. A Narisa no le gusta fregar sangre del suelo.', `FemaleText_loc1`='마법과 까마귀 선술집에 오신 걸 환영합니다.$B$B이곳에 있는 동안 뒤를 조심하셔야 할 겁니다. 나리사는 바닥에 튄 혈흔을 문질러 닦는 걸 좋아하지 않거든요.', `FemaleText_loc4`='欢迎来到咒语和乌鸦旅店，$r。$B$B你最好当心点。纳莉萨不喜欢擦拭地板上的血迹。', `FemaleText_loc5`='歡迎來到咒語與烏鴉酒店，$r。$B$B在這裡的時候自己當心，懂吧?娜莉莎不喜歡擦地板上的血跡。', `FemaleText_loc7`='$gBienvenido:Bienvenida; a la Taberna de los Cuervos, $r.$B$BVigila tus espaldas mientras estás aquí, eh. A Narisa no le gusta fregar sangre del suelo.' WHERE `ID`=32955;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원시비룡이 자유의 냄새를 맡고는 고향으로 날아갑니다!', `MaleText_loc4`='重获自由的始祖龙振翅飞走了！', `MaleText_loc5`='元龍嗅到了自由的氣息，立刻展翅飛回家!', `MaleText_loc7`='¡El protodraco huele la libertad y vuela hacia el hogar!' WHERE `ID`=32956;
