UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정의가 승리했다!', `MaleText_loc4`='正义得以伸张！', `MaleText_loc5`='正義終於得到伸張!', `MaleText_loc7`='¡Y la justicia está servida!' WHERE `ID`=32961;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 어쩔 테냐, 퓨트리스?', `MaleText_loc4`='没话可说了吧，普特雷斯？', `MaleText_loc5`='你還有什麼話說，普崔司?', `MaleText_loc7`='¿Qué dices ahora, Putress?' WHERE `ID`=32962;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주위를 둘러봐라, 형제자매여. 똑똑히 보아라! 저들이 우리 왕국에 무슨 짓을 했는지 보아라!', `MaleText_loc4`='看看周围，兄弟姐妹们，睁开眼睛！看看王国被践踏成了什么样子！', `MaleText_loc5`='看看你四周，兄弟姊妹們。睜大你們的雙眼!看看他們對我們的王國做了什麼!', `MaleText_loc7`='¡Miren a su alrededor, hermanos y hermanas! ¡Abran sus ojos! ¡Miren lo que le han hecho a nuestro reino!' WHERE `ID`=32963;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언제까지 이 제멋대로 구는 야만 종자들을 그냥 보고만 있겠는가?', `MaleText_loc4`='你们还要对这种野蛮的践踏容忍多久？', `MaleText_loc5`='我們還要放任這些野蠻人統治我們的世界多久?', `MaleText_loc7`='¿Cuánto más dejaremos que estos salvajes anden a rienda suelta por nuestro mundo?' WHERE `ID`=32964;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 호드의 세상을 본 적이 있다. 그들의 도시에, 그들의 마음속에 들어가 보았지...', `MaleText_loc4`='我对部落了如指掌。无论是他们的城市，还是他们的思维……', `MaleText_loc5`='我看過部落的世界。我曾在他們的城市之中。在他們的心中...', `MaleText_loc7`='Yo he visto el mundo de la Horda. He estado dentro de sus ciudades. Dentro de sus mentes…' WHERE `ID`=32965;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는, 오크의 마음속에 도사린 악마를 안다.', `MaleText_loc4`='我深知，兽人的内心是多么邪恶。', `MaleText_loc5`='我知道獸人心中潛藏的邪惡。', `MaleText_loc7`='Conozco el mal que vive en los corazones de los orcos.' WHERE `ID`=32966;
