UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 알겠지만, 오크는"록타르 오가르!"라는 전투 함성을 내지른다. "승리가 아니면 죽음을."이란 뜻이지. 지금 딱 맞는군.', `MaleText_loc4`='众所周知，兽人有一句口号：LOK''TAR OGAR！意思是“非胜即死”。真合适……', `MaleText_loc5`='獸人有一句戰吼:LOK''TAR OGAR!意思是「不勝即亡」。正好適合...', `MaleText_loc7`='Como sabrán, los orcos tienen un grito de batalla: ¡LOK''TAR OGAR! "Victoria o muerte". Qué propicio…' WHERE `ID`=32970;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왕실로 진입!', `MaleText_loc4`='向王座前进！', `MaleText_loc5`='前往王座廳!', `MaleText_loc7`='¡A la sala del trono!' WHERE `ID`=32971;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='폐하, 그만두세요! 이건 돕지 않겠습니다!', `FemaleText_loc4`='瓦里安，停下！我不会帮你这么做的！', `FemaleText_loc5`='瓦里安，住手!我不會幫你這麼做!', `FemaleText_loc7`='¡Varian, detente! ¡No te ayudaré con esto!' WHERE `ID`=32972;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혹시 격추 당해서 포로가 되더라도, 놈들에게 진짜 당신 이름을 말하지 마십시오. 암호명을 사용하십시오.', `MaleText_loc4`='如果轰炸机被击落，而你被敌人俘虏的话，一定不要讲出自己的真名。要用代号噢。', `MaleText_loc5`='如果你被擊落並且被逮到，別告訴他們你真正的名字。使用這個代號。', `MaleText_loc7`='Si te abaten y te capturan, no les digas tu verdadero nombre. Usa un nombre en clave.' WHERE `ID`=32973;
