UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분노의 관문에서 형제자매를 처참하게 살해한 철면피가 이 더러운 도시에 숨어 있다! 놈에게 정의의 심판을 내리자!', `MaleText_loc4`='那个在天谴之门屠杀我们同胞的凶手，就龟缩在这座肮脏的城市里！他必须受到正义的裁决！', `MaleText_loc5`='那個卑劣的兇手就躲在這座敗壞的城市之下，他得為我們在憤怒之門被謀殺的兄弟姊妹負責!他必須接受制裁!', `MaleText_loc7`='¡Oculto en de esta ciudad corrompida está el canalla responsable del asesinato de nuestros hermanos y hermanas en la Puerta de Cólera! ¡Debe ser llevado ante la justicia!' WHERE `ID`=32979;
