UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$r|1이여;여;, 이곳은 용족조차 대부분 오기를 꺼리는 곳입니다.$b$b무슨 일로 필멸의 존재가 이런 불안정한 곳에 온 거죠?', `FemaleText_loc4`='大多数巨龙都不敢来到此地，$r。$b$b你这样的凡人为何要以身犯险？', `FemaleText_loc5`='許多龍族都懼怕踏上此地，$r。$b$b什麼樣的理由能把一個凡人帶到如此險惡之地?', `FemaleText_loc7`='Casi todos los dragones temerían pasar por aquí, $r.$b$b¿Qué podría traer a un mortal a un lugar tan traicionero?' WHERE `ID`=32986;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='말리고스의 정예 비룡들이 관할하는 영역에서 그들에게 맞설 용기가 있습니까, $r|1이여;여;?', `FemaleText_loc4`='你敢于进入玛里苟斯的王国，面对他手下的精英侍卫吗，$r？', `FemaleText_loc5`='你有勇氣在他們的領域中面對瑪里苟斯的精英飛龍，$r?', `FemaleText_loc7`='¿Tienes las agallas de enfrentarte a los dragones élites de Malygos en su propio reino, $r?' WHERE `ID`=32987;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그... 그런 것 같습니다...', `MaleText_loc4`='我……我想是的……', `MaleText_loc5`='我...應該有吧...', `MaleText_loc7`='Eso… eso creo…', `FemaleText_loc1`='그... 그런 것 같습니다...', `FemaleText_loc4`='我……我想是的……', `FemaleText_loc5`='我...應該有吧...', `FemaleText_loc7`='Eso… eso creo…' WHERE `ID`=32988;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$c|1이여;여;, 내 비룡들이 당신이 오기를 간절히 기다렸습니다.$b$b날아갈 준비가 되었나요?', `FemaleText_loc4`='幼龙一直在盼望你回来呢，$c。$b$b你准备好起飞了吗？', `FemaleText_loc5`='我的飛龍正等著你的歸來。$c。$b$b你準備好乘風飛行了嗎?', `FemaleText_loc7`='Mis dragones han aguardado tu regreso ansiosos, $c.$b$b¿Estás $glisto:lista; para alzar el vuelo?' WHERE `ID`=32989;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코라스트라자여, 전 준비되었습니다.', `MaleText_loc4`='我准备好了，科拉丝塔萨。', `MaleText_loc5`='我準備好了，寇菈史卓莎女士。', `MaleText_loc7`='Estoy preparado, Lady Corastrasza.', `FemaleText_loc1`='코라스트라자여, 전 준비되었습니다.', `FemaleText_loc4`='我准备好了，科拉丝塔萨。', `FemaleText_loc5`='我準備好了，寇菈史卓莎女士。', `FemaleText_loc7`='Estoy preparada, Lady Corastrasza.' WHERE `ID`=32990;
