UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='푸른용군단 정예 부대가 차원문에서 모습을 드러냅니다!', `FemaleText_loc4`='一队精英蓝龙冲出了传送门！', `FemaleText_loc5`='一批藍龍軍團精英小隊從傳送門中出現!', `FemaleText_loc7`='¡Un pelotón de Vuelo Azul élite aparece por el portal!' WHERE `ID`=32994;
