UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미안해요, 친구. 허가 받은 얼라이언스 장교만 탈것을 구입할 수 있어요.', `MaleText_loc4`='对不起，朋友。只有联盟的军官才有权购买载具。', `MaleText_loc5`='抱歉，朋友。只有被認可的聯盟軍官才有權購買一台載具。', `MaleText_loc7`='Lo siento, colega. Solo oficiales certificados de la Alianza pueden autorizar la compra de un vehículo.', `FemaleText_loc1`='미안하네요, 친구. 허가 받은 얼라이언스 장교만 탈것을 구입할 수 있거든요.', `FemaleText_loc4`='对不起，朋友。只有联盟的军官才有权购买载具。', `FemaleText_loc5`='抱歉，朋友。只有被認可的聯盟軍官才有權購買一台載具。', `FemaleText_loc7`='Lo siento, colega. Solo oficiales certificados de la Alianza pueden autorizar la compra de un vehículo.' WHERE `ID`=32997;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마력의 사전', `MaleText_loc4`='魔法力量宝典', `MaleText_loc5`='力量詞典', `MaleText_loc7`='Lexicón de poder', `FemaleText_loc1`='마력의 사전', `FemaleText_loc4`='魔法力量宝典', `FemaleText_loc5`='力量詞典', `FemaleText_loc7`='Lexicón de poder' WHERE `ID`=32998;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마력의 사전은 주문각인사 근처에서 항상 찾을 수 있습니다.', `MaleText_loc4`='你可以在铭文训练师附近找到这种古老的书册。', `MaleText_loc5`='你總是可以在銘文訓練師附近發現這種遠古典籍。', `MaleText_loc7`='Los escritos antiguos siempre se encuentran cerca de los instructores de inscripción.', `FemaleText_loc1`='마력의 사전은 주문각인사 근처에서 항상 찾을 수 있습니다.', `FemaleText_loc4`='你可以在铭文训练师附近找到这种古老的书册。', `FemaleText_loc5`='你總是可以在銘文訓練師附近發現這種遠古典籍。', `FemaleText_loc7`='Los escritos antiguos siempre se encuentran cerca de los instructores de inscripción.' WHERE `ID`=32999;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 폭격기에 불이 붙었습니다.', `MaleText_loc4`='载具起火了！', `MaleText_loc5`='你的載具正在起火燃燒!', `MaleText_loc7`='¡Tu vehículo está ardiendo!', `FemaleText_loc1`='당신의 폭격기에 불이 붙었습니다.', `FemaleText_loc4`='载具起火了！', `FemaleText_loc5`='你的載具正在起火燃燒!', `FemaleText_loc7`='¡Tu vehículo está ardiendo!' WHERE `ID`=33000;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 해냈습니다! 지금 들리는 소리가 믿어지나요? 정말 대단하군요!', `MaleText_loc4`='成功啦！你听到了吗？真是难以置信！', `MaleText_loc5`='我們成功了!你相信我們剛剛聽到的嗎?太不可思議了!', `MaleText_loc7`='¡Lo logramos! ¿Puedes creerte lo que estamos oyendo? ¡Es increíble!' WHERE `ID`=33001;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 일은 나중에 해도 충분할 겁니다, 브란. 우리는 계속 나아가야 합니다!', `MaleText_loc4`='以后有的是时间啊，布莱恩。我们必须立即转移！', `MaleText_loc5`='拜託之後再慢慢爽吧，布萊恩，我們得繼續前進!', `MaleText_loc7`='Ya tendremos tiempo de sobra para eso más tarde, Brann. ¡Tenemos que irnos!', `FemaleText_loc1`='이 일은 나중에 해도 충분할 거예요, 브란. 우리는 계속 나아가야 해요!', `FemaleText_loc4`='以后有的是时间啊，布莱恩。我们必须立即转移！', `FemaleText_loc5`='拜託之後再慢慢爽吧，布萊恩，我們得繼續前進!', `FemaleText_loc7`='Ya tendremos tiempo de sobra para eso más tarde, Brann. ¡Tenemos que irnos!' WHERE `ID`=33002;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 말이 맞아요. 나중에 다시 올 수도 있죠. 지금은 저 입구 근처에 있는 문 뒤에 뭐가 있는지 확인해볼 시간이에요. 제가 저리로 슬그머니 숨어들어 갈게요. 문으로 오시면 제가 우리 모두 들어가도록 하겠어요.', `MaleText_loc4`='好吧，以后再来这里。我觉得我们应该瞧瞧入口附近的门后面到底隐藏着什么秘密。我会悄悄地潜行过去。到门口找我吧，我能带你们进去。', `MaleText_loc5`='喔對，我可以晚點再回來。我想該瞧瞧靠近入口那扇門後面是什麼了。我要偷偷潛入那邊，安靜而完美。到門那邊跟我會合，我會把我們都給弄進去。', `MaleText_loc7`='Tienes razón, puedo hacerlo más tarde. Creo que es hora de ver qué hay detrás de la puerta cercana a la entrada. Voy a infiltrarme por allí, con cuidado y en silencio. Reúnete conmigo en la puerta y haré que entremos.' WHERE `ID`=33003;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최후의 룬이 배치되었습니다. 성공적으로 활성화되었습니다.', `MaleText_loc4`='放置欧米伽符文。成功激活。', `MaleText_loc5`='終末符文部署完成。啟動成功。', `MaleText_loc7`='Runa omega lista. Activación exitosa.' WHERE `ID`=33004;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무나 아름답지 않소? 앞으로 어마어마한 돈벌이가 될 것이 보이오?', `MaleText_loc4`='这里的风景是不是很漂亮啊？你能看到潜在的利益吗？', `MaleText_loc5`='是不是很漂亮呀?你看到潛在利益了嗎?', `MaleText_loc7`='¿Acaso no es solo bonito? ¿Puede verle el beneficio en potencia?' WHERE `ID`=33005;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 끝내주는 날 아닙니까? 이날이 가기 전에 불꽃놀이를 더 볼 수 있었으면 정말 좋겠습니다.', `MaleText_loc4`='今天是个好日子，不是吗？希望今天结束的时候我们能欣赏到焰火表演。', `MaleText_loc5`='多棒的一天啊，不是嗎?希望這天結束前我能看見一些煙火。', `MaleText_loc7`='Hace un día magnífico, ¿verdad? Espero que podamos ver unos cuantos fuegos artificiales antes de que se acabe.' WHERE `ID`=33006;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하신가, 작은 $r|1이여;여;.', `MaleText_loc4`='你好，小$r。', `MaleText_loc5`='哈囉，小$r。', `MaleText_loc7`='Hola, $gpequeño:pequeña; $r.' WHERE `ID`=33007;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어딘가 고장 나지 않았다는 말이 고칠 수 없다는 뜻은 아니죠. 뭐 찾으세요, $g멋쟁이:예쁜이;?', `FemaleText_loc4`='即使东西没有损坏，也不代表你不能鼓捣它。你想要什么，亲爱的？', `FemaleText_loc5`='東西沒壞不代表不能修理。你在找什麼呢，甜心?', `FemaleText_loc7`='Solo porque algo no esté roto no quiere decir que no puedas arreglarlo. ¿Buscas algo más, cariño?' WHERE `ID`=33008;
