UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s의 신체가 $n의 손에서 튀깁니다.', `MaleText_loc4`='$n打伤了%s。', `MaleText_loc5`='%s被$n打到腦漿四溢。', `MaleText_loc7`='$n salpica los cerebros de %s.', `FemaleText_loc1`='%s의 신체가 $n의 손에서 튀깁니다.', `FemaleText_loc4`='$n打伤了%s。', `FemaleText_loc5`='%s被$n打到腦漿四溢。', `FemaleText_loc7`='$n salpica los cerebros de %s.' WHERE `ID`=33037;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 누추한 곳까지 찾아와주다니 반갑소, $c. 이곳은 아주 편안한데다 난 언제나 달라란 집에 머무는 것을 좋아했소. 그래도 가끔은 아주 외로워지기도 하오... 너무나 쓸쓸해진다는 말이오.', `MaleText_loc4`='欢迎造访，$c。达拉然让我感觉身心舒畅，我喜欢待在家里。但是有时候，也会有孤单……冷清的感觉。', `MaleText_loc5`='歡迎，$c，來到我簡陋的避居地。我覺得這個地方相當令人放鬆，我總是喜歡待在達拉然的家中。雖然有時候這是個孤寂的地方...一個很孤寂的地方。', `MaleText_loc7`='$gBienvenido:Bienvenida; $c a mi humilde refugio. Creo que este lugar es realmente relajante y siempre me ha gustado sentirme en casa en Dalaran. A veces pienso que puede ser un lugar solitario... un lugar tan solitario...' WHERE `ID`=33038;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 관심을 둘만한 책이 한 권 있소. 한 번 보겠소?', `MaleText_loc4`='我有一本书，你或许会感兴趣的。想看看吗？', `MaleText_loc5`='我那有一本書你可能會有興趣。你想要看一看嗎?', `MaleText_loc7`='Tengo un libro que podría interesarte. ¿Quieres echarle un vistazo?', `FemaleText_loc1`='당신이 관심을 둘만한 책이 한 권 있어요. 한 번 보시겠어요?', `FemaleText_loc4`='我有一本书，你或许会感兴趣的。想看看吗？', `FemaleText_loc5`='我那有一本書你可能會有興趣。你想要看一看嗎?', `FemaleText_loc7`='Tengo un libro que podría interesarte. ¿Quieres echarle un vistazo?' WHERE `ID`=33039;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놀랍소! 이전에 보지 못하던 길이 이 안에 있다니. 당신이 이 길을 따라가 보려면 시간이 좀 걸릴 것이오. 이런 책을 더 찾으면, 즉시 알려주었으면 하오. 내가 데리고 있던 키린 토 지식의 전령 하나를 데려가시오. 우연히 뭐라도 발견할 때를 대비해서 말이오.', `MaleText_loc4`='这真是太奇妙了！书里记载的很多内容都是我闻所未闻的。你肯定费了一番功夫才找到的吧？如果你再发现这样的书，一定要立即通知我。

我将肯瑞托魔仆交给你，这样你可以随时向我汇报最新的进展。', `MaleText_loc5`='太驚人了，這裡有許多我從未見過的文件。追查這些東西一定花了你不少時間吧。如果你再找到任何像這樣的東西，請馬上通知我。

請隨身帶著我這隻祈倫托魔寵，以備你突然發現任何東西之需。', `MaleText_loc7`='¡Fascinante! Hay pasajes que nunca antes había visto. Ha debido llevarte un rato localizarlo. Si vuelves a encontrar un libro como este, me encantaría que me notificases inmediatamente.

Lleva contigo uno de mis familiares del Kirin Tor por si te topas con algo.' WHERE `ID`=33040;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명령서 읽기', `MaleText_loc4`='阅读指令', `MaleText_loc5`='宣讀命令', `MaleText_loc7`='Leyendo órdenes.', `FemaleText_loc1`='명령서 읽기', `FemaleText_loc4`='阅读指令', `FemaleText_loc5`='宣讀命令', `FemaleText_loc7`='Leyendo órdenes.' WHERE `ID`=33041;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보물 사냥과 기운을 돋구는 맥주만 있다면 더 바랄 게 없지요, $g젊은이:아가씨;.', `MaleText_loc4`='带上麦酒，踏上寻宝之旅——还有什么比这更美好的事情呢。', `MaleText_loc5`='尋寶和一些豐沛的麥酒 - 一點也不遜於這些，$G小夥子:小姑娘;。', `MaleText_loc7`='Cazar tesoros y cerveza suculenta... no hay nada mejor, $Gmuchacho:muchacha;.' WHERE `ID`=33042;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다! 무언가 발견하면 반드시 알려드리겠습니다.', `MaleText_loc4`='谢谢你！如果有所发现，我一定会及时通知你的。', `MaleText_loc5`='謝謝你!如果我有找到其它東西，我一定會通知你。', `MaleText_loc7`='¡Gracias! Me encargaré de avisarte si descubro algo más.', `FemaleText_loc1`='감사해요! 무언가 발견하면 반드시 알려드리겠어요.', `FemaleText_loc4`='谢谢你！如果有所发现，我一定会及时通知你的。', `FemaleText_loc5`='謝謝你!如果我有找到其它東西，我一定會通知你。', `FemaleText_loc7`='¡Gracias! Me encargaré de avisarte si descubro algo más.' WHERE `ID`=33043;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에메랄드의 꿈은 위험한 곳이 되었다. 에메랄드의 꿈을 구할 수 있다는 희망 때문에 아제로스에서 누릴 수 있던 평범한 삶을 희생하고 에메랄드의 꿈에서 잠든 이들에 대한 걱정이 날로 불어나고 있도다.', `MaleText_loc4`='翡翠梦境已然危机四伏。许多勇士放弃了艾泽拉斯的生活，试图拯救翡翠梦境。我越来越担心他们的安危了。', `MaleText_loc5`='翡翠夢境變成了一個危險的所在。我對那些犧牲清醒時光來試圖拯救翡翠夢境的英雄們感到愈發憂心。', `MaleText_loc7`='El Sueño Esmeralda se ha vuelto un lugar peligroso. Crecí preocupándome cada vez más por aquellos que habían sacrificado su vida en Azeroth con la esperanza de salvarlo.' WHERE `ID`=33044;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도토리를 회수할 수 있도록 에메랄드의 꿈으로 절 보내주십시오. 위험한 상황에 대해선 알고 있지만 두렵지 않습니다.', `MaleText_loc4`='请送我去翡翠梦境寻找橡果。我知道这很危险，但是我不怕。', `MaleText_loc5`='請送我進入翡翠夢境讓我去尋找橡實。我知道這很危險但我無所畏懼。', `MaleText_loc7`='Envíame a mí al Sueño Esmeralda para recuperar las bellotas. Conozco el riesgo y no tengo miedo.', `FemaleText_loc1`='도토리를 회수할 수 있도록 에메랄드의 꿈으로 절 보내주십시오. 위험한 상황에 대해선 알고 있지만 두렵지 않습니다.', `FemaleText_loc4`='请送我去翡翠梦境寻找橡果。我知道这很危险，但是我不怕。', `FemaleText_loc5`='請送我進入翡翠夢境讓我去尋找橡實。我知道這很危險但我無所畏懼。', `FemaleText_loc7`='Envíame a mí al Sueño Esmeralda para recuperar las bellotas. Conozco el riesgo y no tengo miedo.' WHERE `ID`=33045;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 방법을 써 봅시다...', `MaleText_loc4`='好吧，我们换个法子……', `MaleText_loc5`='我們來試試這個方法...', `MaleText_loc7`='Vuelve a intentarlo de otra forma.', `FemaleText_loc1`='다른 방법을 써 봐요...', `FemaleText_loc4`='好吧，我们换个法子……', `FemaleText_loc5`='我們來試試這個方法...', `FemaleText_loc7`='Vuelve a intentarlo de otra forma.' WHERE `ID`=33046;
