UPDATE `locales_broadcast_text` SET `MaleText_loc1`='볼더크랙의 뒤에는 단결한 토석인의 망치가 버티고 있소. 우리는 로켄의 부하들과 끝까지 싸울 것이오.', `MaleText_loc4`='土灵愿意握紧铁锤，成为布德克拉格坚强的后盾。我们要和洛肯的爪牙斗争到底。', `MaleText_loc5`='土靈之錘們集結在石崖之後。我們將會對抗洛肯的爪牙直到最後。', `MaleText_loc7`='Los martillos de los terráneos se mantienen unidos tras Pedruscón. Nos opondremos a los esbirros de Loken hasta el final.' WHERE `ID`=33051;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 발두란을 물리치고 그 휘하에 있는 거대괴수를 쓰러뜨릴 것입니다.', `MaleText_loc4`='我们击败了瓦杜兰！还将推倒他的塑像。', `MaleText_loc5`='我們已經擊敗了瓦杜然，我們也會打倒他的巨像。', `MaleText_loc7`='Hemos derrotado a Valduran y acabaremos con su coloso.' WHERE `ID`=33052;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 싸웠소! 오늘은 우리가 이겼지만, 전쟁은 계속될 것이오!', `MaleText_loc4`='干得好！今天我们取得了胜利，但是战争还在继续！', `MaleText_loc5`='漂亮的一戰!今天值得歡慶，但戰爭還在延續。', `MaleText_loc7`='¡Bien luchado! ¡El día es nuestro pero la guerra continúa!' WHERE `ID`=33053;
