UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 그리울 겁니다, 안토니다스.', `MaleText_loc4`='我们会想你的，安东尼达斯。', `MaleText_loc5`='我們永遠懷念你，安東尼達斯。', `MaleText_loc7`='Te echaremos de menos, Antonidas.', `FemaleText_loc1`='당신이 그리울 거예요, 안토니다스.', `FemaleText_loc4`='我们会想你的，安东尼达斯。', `FemaleText_loc5`='我們永遠懷念你，安東尼達斯。', `FemaleText_loc7`='Te echaremos de menos, Antonidas.' WHERE `ID`=33063;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리를 위해 애써주신 그 모든 노고에 감사드립니다. 평안히 쉬십시오.', `MaleText_loc4`='谢谢你为我们所做的一切。愿你安息。', `MaleText_loc5`='感謝你為我們所做的所有事情。願你能安穩地休息。', `MaleText_loc7`='Gracias por todo lo que has hecho por nosotros. Que descanses en paz.', `FemaleText_loc1`='우리를 위해 애써주신 그 모든 노고에 감사드려요. 평안히 쉬세요.', `FemaleText_loc4`='谢谢你为我们所做的一切。愿你安息。', `FemaleText_loc5`='感謝你為我們所做的所有事情。願你能安穩地休息。', `FemaleText_loc7`='Gracias por todo lo que has hecho por nosotros. Que descanses en paz.' WHERE `ID`=33064;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제단에 아브루의 구슬을 놓습니다.', `MaleText_loc4`='将亚维鲁的宝珠放到祭坛上。', `MaleText_loc5`='將艾芙魯的寶珠放上祭壇。', `MaleText_loc7`='Coloca el orbe de Avruu en el altar.', `FemaleText_loc1`='제단에 아브루의 구슬을 놓습니다.', `FemaleText_loc4`='将亚维鲁的宝珠放到祭坛上。', `FemaleText_loc5`='將艾芙魯的寶珠放上祭壇。', `FemaleText_loc7`='Coloca el orbe de Avruu en el altar.' WHERE `ID`=33065;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제단 주위에 돌풍이 붑니다. 한때 작은 수정구가 있었을만한 장소가 있습니다.', `MaleText_loc4`='狂风环绕着祭坛。你发现祭坛的凹槽处刚好可以放进一颗宝珠。', `MaleText_loc5`='一陣陣的風在祭壇邊旋繞。有一個凹槽看來剛好適合放下這個寶珠。', `MaleText_loc7`='Fuertes vientos rodean el altar. Hay una ranura que parece haber albergado alguna vez un pequeño orbe.' WHERE `ID`=33066;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가끔 성소를 벗어나 신선한 바람을 쐬면 좋더군요.', `MaleText_loc4`='偶尔离开圣殿，呼吸一下新鲜空气也是很不错的。', `MaleText_loc5`='有時候離開聖所到外面透透氣也挺好的。', `MaleText_loc7`='A veces está bien salir del sagrario y tomar un poco de aire fresco.', `FemaleText_loc1`='가끔은 성소를 벗어나 신선한 바람을 쐬는 것도 좋지요.', `FemaleText_loc4`='偶尔离开圣殿，呼吸一下新鲜空气也是很不错的。', `FemaleText_loc5`='有時候離開聖所到外面透透氣也挺好的。', `FemaleText_loc7`='A veces está bien salir del sagrario y tomar un poco de aire fresco.' WHERE `ID`=33067;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='운 좋게도, 리치 왕의 손길은 아직 달라란까지 뻗어오지 않았군요.', `MaleText_loc4`='好在巫妖王的魔爪还没有伸到达拉然来。', `MaleText_loc5`='很幸運的，巫妖王的魔掌尚未觸及達拉然。', `MaleText_loc7`='Afortunadamente, las garras del Rey Exánime no han alcanzado Dalaran aún.', `FemaleText_loc1`='운 좋게도, 리치 왕의 손길은 아직 달라란까지 뻗어오지 않았네요.', `FemaleText_loc4`='好在巫妖王的魔爪还没有伸到达拉然来。', `FemaleText_loc5`='很幸運的，巫妖王的魔掌尚未觸及達拉然。', `FemaleText_loc7`='Afortunadamente, las garras del Rey Exánime no han alcanzado Dalaran aún.' WHERE `ID`=33068;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그녀가 여기서 만나자고 했는데... 여기가 아닌가?', `MaleText_loc4`='她约我在这里碰面的……难道我找错地方了？', `MaleText_loc5`='她說在這裡和她見面...也許我跑錯地方了?', `MaleText_loc7`='Dijo que la encontraría justo aquí… ¿estaré en el lugar equivocado?', `FemaleText_loc1`='그가 여기서 만나자고 했는데... 여기가 아닌가?', `FemaleText_loc4`='她约我在这里碰面的……难道我找错地方了？', `FemaleText_loc5`='她說在這裡和她見面...也許我跑錯地方了?', `FemaleText_loc7`='Dijo que la encontraría justo aquí… ¿estaré en el lugar equivocado?' WHERE `ID`=33069;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어!$b$b그 예언에서 말하던 $r $c|1이;가; 도착했다!', `MaleText_loc4`='终于！$b$b预言中提到的$r$c终于出现了！', `MaleText_loc5`='終於!$b$b$r $c預告的那則預言實現了!', `MaleText_loc7`='¡Por fin!$b$b¡Ha llegado $gel:la; $r $c que anunciaban las profecías!' WHERE `ID`=33070;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='산 자의 세상으로 돌아갈 준비가 되었습니다.', `MaleText_loc4`='我准备好返回生者的世界了。', `MaleText_loc5`='我準備好回到生者的國度了。', `MaleText_loc7`='Estoy listo para regresar al reino de los vivos.', `FemaleText_loc1`='산 자의 세상으로 돌아갈 준비가 되었어요.', `FemaleText_loc4`='我准备好返回生者的世界了。', `FemaleText_loc5`='我準備好回到生者的國度了。', `FemaleText_loc7`='Estoy lista para regresar al reino de los vivos.' WHERE `ID`=33071;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='유물의 방이 공격받고 있습니다!', `MaleText_loc4`='宝库遭到了攻击！', `MaleText_loc5`='聖物間遭受攻擊!', `MaleText_loc7`='¡Están atacando la Cámara de las Reliquias!' WHERE `ID`=33072;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='유물의 방 방어선이 깨졌습니다! 티탄 유물이 위험합니다!', `MaleText_loc4`='宝库被攻破了！泰坦圣物失去了保护！', `MaleText_loc5`='聖物間已經被攻破了!泰坦聖物十分危急!', `MaleText_loc7`='¡Han atravesado la fortaleza! ¡La reliquia de titán es vulnerable!' WHERE `ID`=33073;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형제여, 뭘 도와드릴까요?', `MaleText_loc4`='我能帮你什么忙吗？', `MaleText_loc5`='有什麼我能幫忙的嗎，兄弟?', `MaleText_loc7`='¿Cómo puedo ayudarte, hermano?', `FemaleText_loc1`='형제여, 뭘 도와드릴까요?', `FemaleText_loc4`='我能帮你什么忙吗？', `FemaleText_loc5`='有什麼我能幫忙的嗎，兄弟?', `FemaleText_loc7`='¿Cómo puedo ayudarte, hermano?' WHERE `ID`=33074;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전사여, 뭘 도와드릴까요?', `MaleText_loc4`='我能帮你什么忙吗，战士？', `MaleText_loc5`='有什麼我能幫忙的嗎，戰士?', `MaleText_loc7`='¿Cómo puedo ayudarte, $gguerrero:guerrera;?', `FemaleText_loc1`='전사여, 뭘 도와드릴까요?', `FemaleText_loc4`='我能帮你什么忙吗，战士？', `FemaleText_loc5`='有什麼我能幫忙的嗎，戰士?', `FemaleText_loc7`='¿Cómo puedo ayudarte, $gguerrero:guerrera;?' WHERE `ID`=33075;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자그마한 존재여, 무슨 일인가?', `MaleText_loc4`='有事吗，小家伙？', `MaleText_loc5`='有事嗎，小傢伙?', `MaleText_loc7`='¿Sí, $gpequeño:pequeña;?' WHERE `ID`=33076;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 하늘빛 고리 경비대장을 부릅니다!', `MaleText_loc4`='%s召唤出一名碧蓝魔环上尉！', `MaleText_loc5`='%s呼喚了蒼藍之環隊長!', `MaleText_loc7`='¡%s llama a un capitán del anillo azur!' WHERE `ID`=33077;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크고 번쩍이는 마법책이 주문과 능력을 위한 문양을 만드는 데 도움이 될 거다. 연금술 실험실에 주문각인사 근처에서 마법책 볼 수 있을 거다.', `MaleText_loc4`='炼金房的铭文训练师身旁有一本巨大的，闪闪发光的魔法书，能够帮助你制作强化法术和技能的铭文。', `MaleText_loc5`='閃爍的大本魔法書可以幫助製造法術與技能的雕紋。你可以在銘文學訓練師附近找到它，就在鍊金房。', `MaleText_loc7`='Este gran y brillante libro de magia ayuda a hacer glifos para hechizos y habilidades. Siempre tendrás a un insctructor de inscripción cerca, en el Apothecarium.', `FemaleText_loc1`='크고 번쩍이는 마법책이 주문과 능력을 위한 문양을 만드는 데 도움이 될 거다. 연금술 실험실에 주문각인사 근처에서 마법책 볼 수 있을 거다.', `FemaleText_loc4`='炼金房的铭文训练师身旁有一本巨大的，闪闪发光的魔法书，能够帮助你制作强化法术和技能的铭文。', `FemaleText_loc5`='閃爍的大本魔法書可以幫助製造法術與技能的雕紋。你可以在銘文學訓練師附近找到它，就在鍊金房。', `FemaleText_loc7`='Este gran y brillante libro de magia ayuda a hacer glifos para hechizos y habilidades. Siempre tendrás a un insctructor de inscripción cerca, en el Apothecarium.' WHERE `ID`=33078;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크고 번쩍이는 마법책이 주문과 능력을 위한 문양을 만드는 데 도움이 될 거다. 연금술 실험실에 주문각인사 근처에서 마법책 볼 수 있을 거다.', `MaleText_loc4`='炼金房的铭文训练师身旁有一本巨大的，闪闪发光的魔法书，能够帮助你制作强化法术和技能的铭文。', `MaleText_loc5`='閃爍的大本魔法書可以幫助製造法術與技能的雕紋。你可以在銘文學訓練師附近找到它，就在鍊金房。', `MaleText_loc7`='Este gran y brillante libro de magia ayuda a hacer glifos para hechizos y habilidades. Siempre tendrás a un insctructor de inscripción cerca, en el Apothecarium.', `FemaleText_loc1`='크고 번쩍이는 마법책이 주문과 능력을 위한 문양을 만드는 데 도움이 될 거다. 연금술 실험실에 주문각인사 근처에서 마법책 볼 수 있을 거다.', `FemaleText_loc4`='炼金房的铭文训练师身旁有一本巨大的，闪闪发光的魔法书，能够帮助你制作强化法术和技能的铭文。', `FemaleText_loc5`='閃爍的大本魔法書可以幫助製造法術與技能的雕紋。你可以在銘文學訓練師附近找到它，就在鍊金房。', `FemaleText_loc7`='Este gran y brillante libro de magia ayuda a hacer glifos para hechizos y habilidades. Siempre tendrás a un insctructor de inscripción cerca, en el Apothecarium.' WHERE `ID`=33081;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='서두르세요, $r님. 전 지쳤고 농담할 시간도 없답니다.', `FemaleText_loc4`='快一点，$r。我很疲倦，没功夫开玩笑……', `FemaleText_loc5`='快一點，$r。我又累又倦，沒時間聽笑話。', `FemaleText_loc7`='Rápido, $r. Estoy cansada y no tengo tiempo para galanterías…' WHERE `ID`=33082;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정신 바짝 차려라, $r.$b$b순해 빠져서는 여기서 살아남을 수 없으니까.', `MaleText_loc4`='保持警惕，$r。$b$b这里不是弱者的游乐场。', `MaleText_loc5`='當心點，$r。$b$b這裡可不是給軟弱的人來的。', `MaleText_loc7`='Cuidado, $r.$b$bEste lugar no está hecho para los enclenques.' WHERE `ID`=33083;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='브란의 통신기를 잃어버렸습니다. 새로 하나 받았으면 합니다.', `MaleText_loc4`='我把布莱恩的通讯器弄丢了，请再给我一个。', `MaleText_loc5`='我弄丟了布萊恩的通訊器，需要一個備用的。', `MaleText_loc7`='He perdido el comunicador de Brann y necesito uno de repuesto.', `FemaleText_loc1`='브란의 통신기를 잃어버렸습니다. 새로 하나 받았으면 합니다.', `FemaleText_loc4`='我把布莱恩的通讯器弄丢了，请再给我一个。', `FemaleText_loc5`='我弄丟了布萊恩的通訊器，需要一個備用的。', `FemaleText_loc7`='He perdido el comunicador de Brann y necesito uno de repuesto.' WHERE `ID`=33084;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; $n에게 돌진합니다!', `MaleText_loc4`='%s向$n冲来！', `MaleText_loc5`='%s撲向$n!', `MaleText_loc7`='%s se abalanza sobre $n.' WHERE `ID`=33085;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 자신 앞에 있는 땅을 내려치려 합니다!', `MaleText_loc4`='%s准备猛击他面前的地面！', `MaleText_loc5`='%s準備猛擊他面前的地面!', `MaleText_loc7`='El %s se prepara para golpear el terreno frente a él.' WHERE `ID`=33086;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 모두에게 거부할 수 없는 고통을 시전합니다!', `FemaleText_loc4`='%s对所有人施放了不灭痛楚！', `FemaleText_loc5`='%s對所有人施展不屈之痛!', `FemaleText_loc7`='%s lanza Dolor implacable sobre todos.' WHERE `ID`=33087;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 모두에게 빛의 선고를 시전합니다!', `MaleText_loc4`='%s对所有人施放了谴责！', `MaleText_loc5`='%s對所有人施展譴責!', `MaleText_loc7`='¡%s lanza Condenación sobre todos!' WHERE `ID`=33088;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 있었군요!', `MaleText_loc4`='你来了！', `MaleText_loc5`='原來你在這!', `MaleText_loc7`='¡Ahí estás!' WHERE `ID`=33089;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게 다시 한 번 보여줬으면 해, 마시어스.', `MaleText_loc4`='请你再展示一次，米斯希尔萨。', `MaleText_loc5`='我想再看一次，瑪西亞斯。', `MaleText_loc7`='Necesito que me lo vuelvas a enseñar, Matthias.', `FemaleText_loc1`='내게 다시 한 번 보여주렴, 마시어스.', `FemaleText_loc4`='请你再展示一次，米斯希尔萨。', `FemaleText_loc5`='我想再看一次，瑪西亞斯。', `FemaleText_loc7`='Necesito que me lo vuelvas a enseñar, Matthias.' WHERE `ID`=33090;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피요른의 모루로 돌아갑니다!', `MaleText_loc4`='返回弗约恩之砧！', `MaleText_loc5`='回到斐雍之砧!', `MaleText_loc7`='¡Regresa a Yunque de Fjorn!' WHERE `ID`=33091;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='설명을 해야겠군요...', `FemaleText_loc4`='也许我应该解释一下……', `FemaleText_loc5`='或許我可以解釋...', `FemaleText_loc7`='Tal vez debería explicar…' WHERE `ID`=33092;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전 이곳 테라모어에서 스랄 대족장과 바리안 국왕 간의 비밀 회담을 준비했습니다.', `FemaleText_loc4`='我为萨尔酋长和乌瑞恩国王安排了一次秘密峰会，举办地点就在塞拉摩。', `FemaleText_loc5`='我安排了一場大酋長索爾和烏瑞恩王之間的秘密會面，就在塞拉摩這兒。', `FemaleText_loc7`='Convoqué una cumbre secreta entre el Jefe de Guerra Thrall y el rey Wrynn, aquí en Theramore.' WHERE `ID`=33093;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='바리안 국왕은 비밀리에 수로를 통해 이곳으로 오려 하셨는데 배가 도착하지 않았습니다. 그다음에 바리안 국왕은 종적을 감췄지요.', `FemaleText_loc4`='国王本来要秘密乘船来到这里，但是那艘船从未来过，国王也从此杳无音讯。', `FemaleText_loc5`='國王本來預定秘密搭船前來這裡。但船從來都沒有抵達，烏瑞恩王就這樣消失了。', `FemaleText_loc7`='El rey debía llegar aquí en barco, en secreto. Pero el barco nunca llegó y el rey Wrynn desapareció.' WHERE `ID`=33094;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그대의 도움으로 데피아즈단과 이번 납치의 주모자이자 왕궁의 일원으로 변장했던 오닉시아를 연결할 수 있었습니다.', `FemaleText_loc4`='在你的帮助下，我们找出了迪菲亚盗贼的幕后主使者——奥妮克希亚。她伪装成一名皇家议会的成员，潜藏在暴风城。', `FemaleText_loc5`='由於你的協助讓我們得以找出迪菲亞的幕後主使，偽裝成宮廷成員的奧妮克希亞。', `FemaleText_loc7`='Tu ayuda nos permitió relacionar a los Defias con la cabeza pensante que estaba detrás de la abducción, Onyxia, quien se hacía pasar por un miembro de la corte real.' WHERE `ID`=33095;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='한편 국왕은 납치범에게서 도망쳐 나와 오닉시아와 담판을 짓고자 스톰윈드로 돌아갔습니다.', `FemaleText_loc4`='与此同时，国王设法逃了出来，并返回暴风城去挑战奥妮克希亚。', `FemaleText_loc5`='在這同時，國王設法逃了出來並且回到暴風城解決奧妮克希亞的事情。', `FemaleText_loc7`='Mientras tanto, el rey logró escapar de sus captores y regresó a Ventormenta para encargarse de Onyxia.' WHERE `ID`=33096;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그대가 데피아즈단과의 연결 고리를 찾았다는 말을 전하겠습니다. 에드윈 밴 클리프의 패배로 그들이 와해됐다고 생각한 제가 바보였군요. 그리고 바리안 국왕은 남은 백성 모두에게 본보기로 삼고자 하실 겁니다.', `FemaleText_loc4`='我会告诉乌瑞恩国王，是你找到了迪菲亚盗贼的幕后主使。之前我曾经以为在艾德温·范克里夫死后，迪菲亚盗贼已经土崩瓦解，看来我大错特错了。乌瑞恩国王正好借此机会向其他蠢蠢欲动的家伙发出警告。', `FemaleText_loc5`='我會告訴大家你已經發現與迪菲亞相關的聯繫。我太傻了，以為打敗艾德溫·范克里夫就可以一舉擊破他們，烏瑞恩王應該會想要肅清餘黨以儆效尤。', `FemaleText_loc7`='Enviaré el mensaje de que has descubierto la relación con los Defias. Fui una insensata al creer que estaban acabados con la derrota de Edwin VanCleef, y el rey Wrynn querrá usar como ejemplo a todos los que queden.' WHERE `ID`=33097;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='록타르! 호드의 편에서 전투를 치르고자 왔나?', `MaleText_loc4`='Lok''tar！你是来协助部落作战的吗？', `MaleText_loc5`='為了部落!你是來協助部落戰鬥的嗎?', `MaleText_loc7`='¡Lok''tar! ¿Has venido para servir a la Horda en la batalla?' WHERE `ID`=33098;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='감사합니다, $n 님. 우리 병사들의 건강은 당신의 성공 여부에 달렸습니다.', `FemaleText_loc4`='谢谢你，$n。士兵们的健康就全靠你了。', `FemaleText_loc5`='感謝你，$n。我們士兵的健康仰賴你的成功。', `FemaleText_loc7`='Gracias, $n. La salud de tus soldados depende de tu éxito' WHERE `ID`=33099;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하십시오. 호드 또한 용뼈를 찾고 있다는 걸 잊지 마십시오. 정령들을 처치하는 게 호드를 처치하는 것보단 쉬울지도 모릅니다.', `MaleText_loc4`='当心，$n。记住，部落也在搜集龙骨。杀死他们或许比杀死幽灵容易一些。', `MaleText_loc5`='保重，$n。記得，部落總是在尋找龍骨。他們應該比那些陰影容易對付。', `MaleText_loc7`='Cuídate, $n. Recuerda, la Horda también está en busca de los huesos de dragón. Debería ser más fácil matarlos a ellos que a las sombras.' WHERE `ID`=33100;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동물 같은 호드 녀석들에게 자비를 베풀지 마시오, $n!', `MaleText_loc4`='别对那些禽兽心软，$n！', `MaleText_loc5`='不必對那些畜生留情，$n!', `MaleText_loc7`='¡No muestres piedad a esos animales, $n!' WHERE `ID`=33101;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영원의 불씨를 회수하는 호드를 저지하세요, $n. 전투가 다시 재개되었을 때 그들이 우위를 선점하는 걸 감당할 순 없습니다.', `MaleText_loc4`='你要阻止部落收集灰烬，$n。我们不能让他们在以后的战斗中占据优势！', `MaleText_loc5`='別讓部落取得餘燼，$n。我們無法冒險讓他們戰鬥回收上佔到優勢!', `MaleText_loc7`='Detén a la Horda, que no recupere las ascuas, $n. ¡No podemos arriesgarnos a que tengan ventaja cuando se reanude la batalla!' WHERE `ID`=33102;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들의 더러운 전쟁 기계를 파괴하세요, $n!', `MaleText_loc4`='毁掉那些邪恶的战争机器，$n！', `MaleText_loc5`='摧毀他們邪惡的戰爭機器，$n!', `MaleText_loc7`='¡Destruye sus apestosas máquinas de guerra, $n!' WHERE `ID`=33103;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='빙하 폭포는 위험한 곳입니다, $n. 호드가 사악한 부두술에 사용할 당신의 갑옷을 차지하면 기뻐하는 광경을 볼 수 있는 곳이 바로 그곳이니까요.', `FemaleText_loc4`='冰川瀑布非常危险，$n。为了施放邪恶的巫毒魔法，部落会毫不犹豫地杀死你，夺走你的护甲。', `FemaleText_loc5`='冰川瀑布是個危險的地方，$n。部落會很高興拿你的護甲去製作他們的邪惡咒毒魔法。', `FemaleText_loc7`='Las Cascadas Glaciales son un lugar peligroso, $n. La Horda estará encantada de reclamar tu armadura para su vil magia hudú.' WHERE `ID`=33104;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리에게 승리의 기쁨을 안겨 주세요, $n. 그럼 당신이 받아야만 하는 명예를 안겨 드리겠습니다. 얼라이언스를 위해 싸우세요!', `MaleText_loc4`='帮助我们取得胜利吧，$n。你会得到应得的荣耀！为联盟而战！', `MaleText_loc5`='為我們帶來勝利，$n，我們會給你應得的榮譽!為聯盟而戰!', `MaleText_loc7`='¡Llévanos a la victoria, $n, y te otorgaremos el honor que mereces!¡Lucha por la Alianza!' WHERE `ID`=33105;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 숲은 겨울손아귀 서쪽에 있습니다. 영혼이 빠져나간 불쌍한 망령들을 찾아보십시오. 동료가 생기면 그들이 기뻐할 겁니...', `MaleText_loc4`='森林就在冬拥湖的西部边缘。你只要找那些吸食灵魂的幽灵就行了，它们肯定会很高兴有人来做伴的……', `MaleText_loc5`='冬握湖西側的森林。去找一些吸取靈魂的陰影，我想他們一定很高興有人陪伴...', `MaleText_loc7`='El bosque está en el extremo occidental de Conquista del Invierno. Busca a las sombras chupaalmas, estoy seguro que estarán encantadas de tener algo de compañía...' WHERE `ID`=33106;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스는 극악무도한 침입으로 이 땅을 욕보였습니다. 그들에게서 약초를 회수하는 일을 망설이지 마십시오!', `MaleText_loc4`='无耻的联盟也跑来这里抢夺资源，他们糟蹋了这片土地！你要毫不犹豫地杀死他们，从他们的尸体上拿走草药！', `MaleText_loc5`='聯盟靠他們下流的盜獵行徑污衊了這塊土地。直接從他們的屍體上收集草藥，不需要在意!', `MaleText_loc7`='La Alianza deshonra esta tierra con sus malvados actos furtivos. ¡No dudes en reclamar las hierbas de sus cuerpos!' WHERE `ID`=33107;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빙하 폭포는 동쪽에 있습니다. 찾아내는 갑옷은 제게 가져오세요. 얼라이언스 녀석들은 뭐가 때리는지도 모를 겁니다.', `MaleText_loc4`='冰川瀑布就在东边，朋友。带回你能找到的最好的护甲。联盟不会知道是谁在攻击他们。', `MaleText_loc5`='冰川瀑布的東邊，老兄。去那邊把你能找到最好的護甲給帶回來。那些聯盟根本不會知道誰在攻擊他們。', `MaleText_loc7`='Las Cascadas Glaciales están al este, colega. Trae la mejor armadura que encuentres. La Alianza no sabrá ni qué le golpeó.' WHERE `ID`=33108;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들을 모두 처치하게, $n!', `MaleText_loc4`='杀光他们，$n！', `MaleText_loc5`='殺光他們，$n!', `MaleText_loc7`='¡Mátalos a todos, $n!' WHERE `ID`=33109;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불꽃 축제 동안에 정령의 불씨는 듀로타에서보다 더 활활 타오른답니다. 얼라이언스는 정령의 불씨를 손에 넣지 못할 겁니다!', `MaleText_loc4`='元素灰烬在燃烧时释放出的热量，比杜隆塔尔在火焰节期间燃起的烈焰还要强烈。绝对不能让联盟得到它们！', `MaleText_loc5`='永恆餘燼燒得比杜洛塔火焰慶典時更熾熱。可不能容許聯盟取得它!', `MaleText_loc7`='Las ascuas de elemental arden con más fuerza que Durotar en el Festival de Fuego. ¡No se puede permitir que la Alianza las reclame!' WHERE `ID`=33110;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 공성 전차를 부숴버려, $n! 머프가 알 거야.', `MaleText_loc4`='毁掉那些攻城器械，$n！莫普会知道的。', `MaleText_loc5`='摧毀攻城器，$n!莫普會知道的。', `MaleText_loc7`='¡Destroza el asedio, $n! Murp se enterará.' WHERE `ID`=33111;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='승리가 아니면 죽음을, $n!', `MaleText_loc4`='非胜即死，$n！', `MaleText_loc5`='不勝即亡，$n!', `MaleText_loc7`='¡Victoria o muerte, $n!' WHERE `ID`=33112;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전쟁 무기를 보호해 주세요, $n! 얼라이언스의 승리를 위해 싸우세요!', `MaleText_loc4`='保护我们的战争机器，$n！为联盟的荣誉而战！', `MaleText_loc5`='保護我們的戰爭機器，$n!為了聯盟的光榮而戰!', `MaleText_loc7`='¡Protege nuestras máquinas de guerra, $n! ¡Lucha por la gloria de la Alianza!' WHERE `ID`=33113;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빙하 폭포는 동쪽에 있습니다. 찾아내는 갑옷은 제게 가져오십시오. 얼라이언스 녀석들은 뭐가 때리는지도 모를 겁니다.', `MaleText_loc4`='冰川瀑布就在东边，朋友。把你能找到的最好的护甲带回来。联盟的家伙们马上就要完蛋啦。', `MaleText_loc5`='冰川瀑布的東邊，老兄。去那邊把你能找到最好的護甲給帶回來。那些聯盟根本不會知道誰在攻擊他們。', `MaleText_loc7`='Las Cascadas Glaciales están al este, colega. Trae la mejor armadura que encuentres. La Alianza no sabrá ni qué le golpeó.' WHERE `ID`=33114;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공성 무기를 보호해, $n! 성벽을 부숴버려!', `MaleText_loc4`='保护我们的攻城器械，$n！摧毁他们的城墙！', `MaleText_loc5`='保護攻城器，$n!摧毀他們的城牆!', `MaleText_loc7`='¡Defiende el asedio,$n! ¡Derriba las murallas!' WHERE `ID`=33115;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음 따위가... 날 막을 순 없다.', `MaleText_loc4`='死亡……是无法阻止我的……', `MaleText_loc5`='死亡...是無法阻止我的。', `MaleText_loc7`='La muerte no me detendrá.' WHERE `ID`=33116;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='봉우리의 뿔피리를 잃어버렸어요.', `MaleText_loc4`='我把峭壁号角弄丢了。', `MaleText_loc5`='我似乎把群山號角放錯了地方。', `MaleText_loc7`='Parece que he perdido el cuerno de Las Cumbres.', `FemaleText_loc1`='봉우리의 뿔피리를 잃어버렸어요.', `FemaleText_loc4`='我把峭壁号角弄丢了。', `FemaleText_loc5`='我似乎把群山號角放錯了地方。', `FemaleText_loc7`='Parece que he perdido el cuerno de Las Cumbres.' WHERE `ID`=33117;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 귀족의 정원 축제라. 품위를 내팽개치고는 알록달록한 알을 찾아다니는 꼴을 보고 있노라면 어찌나 우스운지... 하지만, 그 알에 어딘가 마법적인 분위기가 감도는 건 사실입니다.', `MaleText_loc4`='啊，复活节。看到人们放下尊严，四处搜寻彩蛋，真是有趣啊。显然，这些彩蛋拥有某种特殊的魔力……', `MaleText_loc5`='喔，貴族花園。看到其他人拋下尊貴的身分在那邊尋找彩蛋可真精采。不過，他們確實有一種有趣的魔法光環...', `MaleText_loc7`='Ah, la celebración del Jardín Noble. Es tan divertido ver cómo los demás tiran su dignidad a la basura para encontrar huevos de colores... Y, sin embargo, hay una curiosa aura mágica en torno a ello...', `FemaleText_loc1`='아, 귀족의 정원 축제라. 품위를 내팽개치고는 알록달록한 알을 찾아다니는 꼴을 보고 있노라면 어찌나 우스운지... 하지만, 그 알에 어딘가 마법적인 분위기가 감도는 건 사실입니다.', `FemaleText_loc4`='啊，复活节。看到人们放下尊严，四处搜寻彩蛋，真是有趣啊。显然，这些彩蛋拥有某种特殊的魔力……', `FemaleText_loc5`='喔，貴族花園。看到其他人拋下尊貴的身分在那邊尋找彩蛋可真精采。不過，他們確實有一種有趣的魔法光環...', `FemaleText_loc7`='Ah, la celebración del Jardín Noble. Es tan divertido ver cómo los demás tiran su dignidad a la basura para encontrar huevos de colores... Y, sin embargo, hay una curiosa aura mágica en torno a ello...' WHERE `ID`=33118;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='귀족의 정원 축제가 돌아왔습니다! 세상의 재탄생을 가져오는 성스러운 빛에 감사드릴 시간입니다.', `MaleText_loc4`='复活节又到啦！在这个节日里，我们要感谢圣光让世界重生。', `MaleText_loc5`='又到了貴族花園的時候啦!感謝聖光讓這個世界重生。', `MaleText_loc7`='¡Ha vuelto la época de la celebración del Jardín Noble! Es el momento de agradecer a la Luz el renacer del mundo.', `FemaleText_loc1`='귀족의 정원 축제가 돌아왔군요! 세상의 재탄생을 가져오는 성스러운 빛에 감사드릴 시간입니다.', `FemaleText_loc4`='复活节又到啦！在这个节日里，我们要感谢圣光让世界重生。', `FemaleText_loc5`='又到了貴族花園的時候啦!感謝聖光讓這個世界重生。', `FemaleText_loc7`='¡Ha vuelto la época de la celebración del Jardín Noble! Es el momento de agradecer a la Luz el renacer del mundo.' WHERE `ID`=33119;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사탕이라! 바로 그겁니다. 하지만 단 것을 찾으려고 뛰어다닐 필요는 없었으면 좋겠군요!', `MaleText_loc4`='糖果！这正是我想要的；希望我不用为了找糖果而东奔西跑！', `MaleText_loc5`='糖果!這就是我說的，我真希望我不需要四處奔走找到它!', `MaleText_loc7`='¡Caramelos! A eso me refiero. ¡Ojalá no tuviera que andar correteando para encontrarlos!', `FemaleText_loc1`='사탕이라! 바로 그겁니다. 하지만 단 것을 찾으려고 뛰어다닐 필요는 없었으면 좋겠군요!', `FemaleText_loc4`='糖果！这正是我想要的；希望我不用为了找糖果而东奔西跑！', `FemaleText_loc5`='糖果!這就是我說的，我真希望我不需要四處奔走找到它!', `FemaleText_loc7`='¡Caramelos! A eso me refiero. ¡Ojalá no tuviera que andar correteando para encontrarlos!' WHERE `ID`=33120;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자연에서 당연히 일어나는 과정을 축하한다니, 바보 같아요. 우리가 축하하든 말든 벌어지는 일이잖아요! 하지만 단 걸 먹기에 좋은 핑계긴 하죠!', `MaleText_loc4`='为什么要庆祝世界的自然演变，真是可笑。无论我们庆祝与否，它都会发生呀！不过，这是一个吃糖果的好借口！', `MaleText_loc5`='慶祝自然界的正常運行真的很蠢，不管我們慶祝與否自然都會如常運行!不過，這是個滿足糖份需求的好藉口!', `MaleText_loc7`='Celebrar los procesos naturales del mundo es algo tonto... Va a ocurrir igualmente, ¡lo celebremos o no! ¡Pero es una buena excusa para tomar azúcar!', `FemaleText_loc1`='자연에서 당연히 일어나는 과정을 축하한다니, 바보 같아요. 우리가 축하하든 말든 벌어지는 일이잖아요! 하지만 단 걸 먹기에 좋은 핑계긴 하죠!', `FemaleText_loc4`='为什么要庆祝世界的自然演变，真是可笑。无论我们庆祝与否，它都会发生呀！不过，这是一个吃糖果的好借口！', `FemaleText_loc5`='慶祝自然界的正常運行真的很蠢，不管我們慶祝與否自然都會如常運行!不過，這是個滿足糖份需求的好藉口!', `FemaleText_loc7`='Celebrar los procesos naturales del mundo es algo tonto... Va a ocurrir igualmente, ¡lo celebremos o no! ¡Pero es una buena excusa para tomar azúcar!' WHERE `ID`=33121;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐요, 사람들이 알록달록한 알을 찾으러 사방을 뛰어다니며 흙 속을 뒤지고 싶다는데, 제가 뭐라 하겠어요? 어쨌든 전 물감 값으로 좀 버는 데다가 올해는 닭에도 투자했다고요.', `MaleText_loc4`='嘿，如果人们乐意四处奔走，在土堆里寻找彩蛋，我有什么好说的呀？反正我能从绘制彩蛋上赚到一笔，而且今年我还投资了养鸡场。', `MaleText_loc5`='嘿，就是有人會想要跑去爛泥裡找彩蛋，我是不評論這種事啦。反正我還可以靠這些顏料賺上一筆，我今年還在雞隻上投資了一筆。', `MaleText_loc7`='Oye, si la gente quiere corretear por ahí embadurnándose por unos huevos de colores, ¿quién soy yo para juzgarlos? Me llevo un pellizco de los beneficios de la pintura, y este año he invertido en pollos.', `FemaleText_loc1`='이봐요, 사람들이 알록달록한 알을 찾으러 사방을 뛰어다니며 흙 속을 뒤지고 싶다는데, 제가 뭐라 하겠어요? 어쨌든 전 물감 값으로 좀 버는 데다가 올해는 닭에도 투자했다고요.', `FemaleText_loc4`='嘿，如果人们乐意四处奔走，在土堆里寻找彩蛋，我有什么好说的呀？反正我能从绘制彩蛋上赚到一笔，而且今年我还投资了养鸡场。', `FemaleText_loc5`='嘿，就是有人會想要跑去爛泥裡找彩蛋，我是不評論這種事啦。反正我還可以靠這些顏料賺上一筆，我今年還在雞隻上投資了一筆。', `FemaleText_loc7`='Oye, si la gente quiere corretear por ahí embadurnándose por unos huevos de colores, ¿quién soy yo para juzgarlos? Me llevo un pellizco de los beneficios de la pintura, y este año he invertido en pollos.' WHERE `ID`=33122;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='귀족의 정원 축제라! 전 이미 알을 꽤 찾았습니다. 알 찾기에 좋은 날씨지요?', `MaleText_loc4`='复活节来啦！我找到了好多好多彩蛋。今天真是个找彩蛋的好日子呢，不是吗？', `MaleText_loc5`='貴族花園節!我已經找到了一堆蛋。狩獵的好天氣，對吧?', `MaleText_loc7`='¡Ha llegado la celebración del Jardín Noble! Yo ya he encontrado un montón de huevos. El tiempo acompaña para la búsqueda, ¿eh?', `FemaleText_loc1`='귀족의 정원 축제예요! 전 이미 알을 꽤 찾았답니다. 알 찾기에 좋은 날씨지요?', `FemaleText_loc4`='复活节来啦！我找到了好多好多彩蛋。今天真是个找彩蛋的好日子呢，不是吗？', `FemaleText_loc5`='貴族花園節!我已經找到了一堆蛋。狩獵的好天氣，對吧?', `FemaleText_loc7`='¡Ha llegado la celebración del Jardín Noble! Yo ya he encontrado un montón de huevos. El tiempo acompaña para la búsqueda, ¿eh?' WHERE `ID`=33123;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='귀족의 정원 축제는 아제로스의 드루이드들이 생명의 재탄생을 축하하는 시간이랍니다. 알은 생명의 탄생을 상징할뿐더러, 모든 이에게 축제 정신을 불러일으키기에도 제격이죠. 그렇지 않습니까?', `MaleText_loc4`='复活节是艾泽拉斯的德鲁伊们庆祝生命复苏的日子。彩蛋是繁衍的象征，同时能很好地引导大家理解灵魂的奥秘，你说是吗？', `MaleText_loc5`='貴族花園是艾澤拉斯的德魯伊慶祝生命重生的日子。蛋是繁殖的象徵，你不覺得這是個很棒方法讓大家體會節日的精神嗎?', `MaleText_loc7`='La celebración del Jardín Noble es la época en la que los druidas de Azeroth celebran el renacimiento de la vida. Los huevos son un símbolo de fertilidad y una manera excelente de contagiar a todos de ese espíritu, ¿no crees?', `FemaleText_loc1`='귀족의 정원 축제는 아제로스의 드루이드들이 생명의 재탄생을 축하하는 시간이랍니다. 알은 생명의 탄생을 상징할뿐더러, 모든 이에게 축제 정신을 불러일으키기에도 제격이죠. 그렇지 않습니까?', `FemaleText_loc4`='复活节是艾泽拉斯的德鲁伊们庆祝生命复苏的日子。彩蛋是繁衍的象征，同时能很好地引导大家理解灵魂的奥秘，你说是吗？', `FemaleText_loc5`='貴族花園是艾澤拉斯的德魯伊慶祝生命重生的日子。蛋是繁殖的象徵，你不覺得這是個很棒方法讓大家體會節日的精神嗎?', `FemaleText_loc7`='La celebración del Jardín Noble es la época en la que los druidas de Azeroth celebran el renacimiento de la vida. Los huevos son un símbolo de fertilidad y una manera excelente de contagiar a todos de ese espíritu, ¿no crees?' WHERE `ID`=33124;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 귀족의 정원 축제 기간에 봄을 기립니다. 생명의 소중함 등을 되새기는 거죠.', `MaleText_loc4`='我们会在复活节期间庆祝春天的到来。赞美生命和一切美好的事物。', `MaleText_loc5`='我們在貴族花園的時候慶祝春天。肯定生命的價值啊之類的。', `MaleText_loc7`='Durante el Jardín Noble celebramos la primavera. El fundamento de la vida y todo eso.', `FemaleText_loc1`='우리는 귀족의 정원 축제 기간에 봄을 기립니다. 생명의 소중함 등을 되새기는 거죠.', `FemaleText_loc4`='我们会在复活节期间庆祝春天的到来。赞美生命和一切美好的事物。', `FemaleText_loc5`='我們在貴族花園的時候慶祝春天。肯定生命的價值啊之類的。', `FemaleText_loc7`='Durante el Jardín Noble celebramos la primavera. El fundamento de la vida y todo eso.' WHERE `ID`=33125;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금은 생명의 탄생에 경의를 표하는 시간이랍니다. 알은 봄과 재탄생의 상징이지요. 부디 봄을 즐기길 바랍니다.', `MaleText_loc4`='此刻，我们赞美生命的诞生，而彩蛋代表着春天和复苏。愿你度过一个美好的春天。', `MaleText_loc5`='現在是我們對生命的誕生獻上敬意的日子，蛋則是象徵著春天與重生。希望你能好好享受春天。', `MaleText_loc7`='Este es el momento en que rendimos homenaje al nacimiento de la vida, y los huevos son símbolo de la primavera y del renacer. Que disfrutes de la primavera.', `FemaleText_loc1`='지금은 생명의 탄생에 경의를 표하는 시간이랍니다. 알은 봄과 재탄생의 상징이지요. 부디 봄을 즐기시길 바랍니다.', `FemaleText_loc4`='此刻，我们赞美生命的诞生，而彩蛋代表着春天和复苏。愿你度过一个美好的春天。', `FemaleText_loc5`='現在是我們對生命的誕生獻上敬意的日子，蛋則是象徵著春天與重生。希望你能好好享受春天。', `FemaleText_loc7`='Este es el momento en que rendimos homenaje al nacimiento de la vida, y los huevos son símbolo de la primavera y del renacer. Que disfrutes de la primavera.' WHERE `ID`=33126;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예, 봄과 생명을 느끼며 기뻐할 시간입니다. 알은 많이 모으셨습니까?', `MaleText_loc4`='嘿，朋友，眼下正是为生命和春天欢呼的日子。你已经收集到了不少彩蛋吧？', `MaleText_loc5`='是呀，老兄，這是生命與春天的喜悅時刻。你收集到那些蛋了沒?', `MaleText_loc7`='Sí, colee''hga, e''te é el momento de la felisidá de viví y de la primave''ra. ¿Ya has conseguío muchos huevos?', `FemaleText_loc1`='예, 봄과 생명을 느끼며 기뻐할 시간입니다. 알은 많이 모으셨나요?', `FemaleText_loc4`='嘿，朋友，眼下正是为生命和春天欢呼的日子。你已经收集到了不少彩蛋吧？', `FemaleText_loc5`='是呀，老兄，這是生命與春天的喜悅時刻。你收集到那些蛋了沒?', `FemaleText_loc7`='Sí, colee''hga, e''te é el momento de la felisidá de viví y de la primave''ra. ¿Ya has conseguío muchos huevos?' WHERE `ID`=33127;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말도 안 되는 축제입니다. 알록달록한 알에, 뭐, 생명의 소중함이요? 흥.', `MaleText_loc4`='这个节日根本毫无意义。彩蛋和所谓“生命的礼赞”，我呸。', `MaleText_loc5`='整個節日都是荒謬而愚蠢。彩蛋與「生命的肯定」，呿。', `MaleText_loc7`='"Toda esta fiesta carece de sentido. Huevos de colores y "afirmación de la vida"... buá.', `FemaleText_loc1`='말도 안 되는 축제입니다. 알록달록한 알에, 뭐, 생명의 소중함이요? 흥.', `FemaleText_loc4`='这个节日根本毫无意义。彩蛋和所谓“生命的礼赞”，我呸。', `FemaleText_loc5`='整個節日都是荒謬而愚蠢。彩蛋與「生命的肯定」，呿。', `FemaleText_loc7`='"Toda esta fiesta carece de sentido. Huevos de colores y "afirmación de la vida"... buá.' WHERE `ID`=33128;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 자신의 운명을 깨닫습니다!', `MaleText_loc4`='%s预感到自己大祸临头了！', `MaleText_loc5`='%s感受到他的命運!', `MaleText_loc7`='¡%s intuye su destino!' WHERE `ID`=33129;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부두에서 폭발물을 집어서 저 문을 파괴하세요!', `MaleText_loc4`='抓起码头上的炸药，摧毁大门！', `MaleText_loc5`='把這些甲板上的炸藥拿去那邊的門，老兄!', `MaleText_loc7`='¡Coged el explosivo de los muelles y derribad esas puertas, chicos!', `FemaleText_loc1`='부두에서 폭발물을 집어서 저 문을 파괴하세요!', `FemaleText_loc4`='抓起码头上的炸药，摧毁大门！', `FemaleText_loc5`='把這些甲板上的炸藥拿去那邊的門，老兄!', `FemaleText_loc7`='¡Coged el explosivo de los muelles y derribad esas puertas, chicos!' WHERE `ID`=33130;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부두에서 폭발물을 집어서 저 문을 파괴하게!', `MaleText_loc4`='抓起码头上的炸药，摧毁大门！', `MaleText_loc5`='把這些甲板上的炸藥拿去那邊的門，老兄!', `MaleText_loc7`='¡Coged el explosivo de los muelles y derribad esas puertas, chicos!', `FemaleText_loc1`='부두에서 폭발물을 집어서 저 문을 파괴하게!', `FemaleText_loc4`='抓起码头上的炸药，摧毁大门！', `FemaleText_loc5`='把這些甲板上的炸藥拿去那邊的門，老兄!', `FemaleText_loc7`='¡Coged el explosivo de los muelles y derribad esas puertas, chicos!' WHERE `ID`=33131;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하시오, 친구! 아제로스의 후예로서 전투에 참여하고자 왔소?', `MaleText_loc4`='嗨，朋友！你是来协助我们作战的吗？', `MaleText_loc5`='你好哇，朋友!你來替艾澤拉斯之子效力嗎?', `MaleText_loc7`='¡Saludos, $gamigo:amiga;! ¿Has venido a servir a los hijos de Azeroth en la batalla?' WHERE `ID`=33132;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음 전투는 $3975w:$3976w$3782w:$3784w$3785w후에 시작됩니다.', `MaleText_loc4`='下一场战斗将在$3975w:$3976w$3782w:$3784w$3785w内开始。', `MaleText_loc5`='下一場戰鬥將在$3975w:$3976w$3782w:$3784w$3785w後開始。', `MaleText_loc7`='La siguiente batalla comenzará en $3975w:$3976w$3782w:$3784w$3785w.', `FemaleText_loc1`='다음 전투는 $3975w:$3976w$3782w:$3784w$3785w후에 시작됩니다.', `FemaleText_loc4`='下一场战斗将在$3975w:$3976w$3782w:$3784w$3785w内开始。', `FemaleText_loc5`='下一場戰鬥將在$3975w:$3976w$3782w:$3784w$3785w後開始。', `FemaleText_loc7`='La siguiente batalla comenzará en $3975w:$3976w$3782w:$3784w$3785w.' WHERE `ID`=33133;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음 전투는 %3975w:%3976w%3782w:%3784w%3785w후에 시작됩니다.', `MaleText_loc4`='下一场战斗将在%3975w:%3976w%3782w:%3784w%3785w内开始。', `MaleText_loc5`='下一場戰鬥將在%3975w:%3976w%3782w:%3784w%3785w後開始。', `MaleText_loc7`='La siguiente batalla comenzará en %3975w:%3976w%3782w:%3784w%3785w.', `FemaleText_loc1`='다음 전투는 %3975w:%3976w%3782w:%3784w%3785w후에 시작됩니다.', `FemaleText_loc4`='下一场战斗将在%3975w:%3976w%3782w:%3784w%3785w内开始。', `FemaleText_loc5`='下一場戰鬥將在%3975w:%3976w%3782w:%3784w%3785w後開始。', `FemaleText_loc7`='La siguiente batalla comenzará en %3975w:%3976w%3782w:%3784w%3785w.' WHERE `ID`=33134;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='만나서 반갑습니다. 귀족의 정원 축제는 즐거우시겠지요? 함께 즐기는 게 어때요?', `MaleText_loc4`='你好，朋友。希望你在复活节期间玩得开心！为什么不一起狂欢呢？', `MaleText_loc5`='歡迎，朋友。希望，你能好好享受貴族花園節?何不跟我們同樂?', `MaleText_loc7`='Saludos, camarada. Espero que estés disfrutando de la celebración del Jardín Noble. ¿Por qué no te unes a la diversión?', `FemaleText_loc1`='만나서 반가워요. 귀족의 정원 축제는 즐거우시겠지요? 함께 즐기는 게 어때요?', `FemaleText_loc4`='你好，朋友。希望你在复活节期间玩得开心！为什么不一起狂欢呢？', `FemaleText_loc5`='歡迎，朋友。希望，你能好好享受貴族花園節?何不跟我們同樂?', `FemaleText_loc7`='Saludos, camarada. Espero que estés disfrutando de la celebración del Jardín Noble. ¿Por qué no te unes a la diversión?' WHERE `ID`=33135;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요, $c|1이여;여;.$B$B겨울손아귀 요새를 얼라이언스가 장악하고 있을 때는 그곳으로 가려 하는 모험가들에게 편의를 제공하고자 차원문을 열어 드립니다.$B$B현재 전투가 계속되고 있습니다. 어서 겨울손아귀로 가셔서 우리 군대를 지원하십시오!', `MaleText_loc4`='你好，$c。$B$B一旦联盟取得冬拥堡垒的控制权，我就将为想要前往那里的旅行者开启一道传送门。$B$B战斗正在进行中，赶快前往冬拥湖，支援我们的部队吧！', `MaleText_loc5`='你好，$c。$B$B當聯盟控制了冬握堡壘，我就會開啟一道傳送門，提供那些想要前來這裡的人使用。$B$B戰鬥現在正在進行中，快前往冬握湖幫助我們的部隊!', `MaleText_loc7`='Saludos, $c.$B$BCuando la Alianza controle la Fortaleza de Conquista del Invierno, abriré un portal para aquellos que deseen viajar hasta allí.$B$BLa batalla está teniendo lugar ahora. ¡Ve corriendo a Conquista del Invierno y ayuda a nuestras tropas!', `FemaleText_loc1`='안녕하세요, $c|1이여;여;.$B$B겨울손아귀 요새를 얼라이언스가 장악하고 있을 때는 그곳으로 가려 하는 모험가들에게 편의를 제공하고자 차원문을 열어 드립니다.$B$B현재 전투가 계속되고 있습니다. 어서 겨울손아귀로 가셔서 우리 군대를 지원하십시오!', `FemaleText_loc4`='你好，$c。$B$B一旦联盟取得冬拥堡垒的控制权，我就将为想要前往那里的旅行者开启一道传送门。$B$B战斗正在进行中，赶快前往冬拥湖，支援我们的部队吧！', `FemaleText_loc5`='你好，$c。$B$B當聯盟控制了冬握堡壘，我就會開啟一道傳送門，提供那些想要前來這裡的人使用。$B$B戰鬥現在正在進行中，快前往冬握湖幫助我們的部隊!', `FemaleText_loc7`='Saludos, $c.$B$BCuando la Alianza controle la Fortaleza de Conquista del Invierno, abriré un portal para aquellos que deseen viajar hasta allí.$B$BLa batalla está teniendo lugar ahora. ¡Ve corriendo a Conquista del Invierno y ayuda a nuestras tropas!' WHERE `ID`=33136;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요, $c|1이여;여;.$B$B겨울손아귀 요새를 호드가 장악하고 있을 때는 그곳으로 가려 하는 모험가들에게 편의를 제공하고자 차원문을 열어준답니다.$B$B현재 전투가 계속되고 있어요. 어서 겨울손아귀로 가셔서 우리 군대를 지원해 주세요!', `MaleText_loc4`='你好，$c。$B$B一旦部落取得冬拥堡垒的控制权，我就将为想要前往那里的旅行者开启一道传送门。$B$B战斗正在进行中，赶快前往冬拥湖，支援我们的部队吧。', `MaleText_loc5`='你好，$c。$B$B當部落控制了冬握堡壘，我就會開啟一道傳送門，提供那些想要前來這裡的人使用。$B$B戰鬥現在正在進行中，快前往冬握湖幫助我們的部隊。', `MaleText_loc7`='Saludos, $c.$B$BCuando la Horda controle la Fortaleza de Conquista del Invierno, abriré un portal para aquellos que deseen viajar hasta allí.$B$BLa batalla está teniendo lugar ahora. ¡Ve corriendo a Conquista del Invierno y ayuda a nuestras tropas!', `FemaleText_loc1`='안녕하세요, $c|1이여;여;.$B$B겨울손아귀 요새를 호드가 장악하고 있을 때는 그곳으로 가려 하는 모험가들에게 편의를 제공하고자 차원문을 열어준답니다.$B$B현재 전투가 계속되고 있어요. 어서 겨울손아귀로 가셔서 우리 군대를 지원해 주세요!', `FemaleText_loc4`='你好，$c。$B$B一旦部落取得冬拥堡垒的控制权，我就将为想要前往那里的旅行者开启一道传送门。$B$B战斗正在进行中，赶快前往冬拥湖，支援我们的部队吧。', `FemaleText_loc5`='你好，$c。$B$B當部落控制了冬握堡壘，我就會開啟一道傳送門，提供那些想要前來這裡的人使用。$B$B戰鬥現在正在進行中，快前往冬握湖幫助我們的部隊。', `FemaleText_loc7`='Saludos, $c.$B$BCuando la Horda controle la Fortaleza de Conquista del Invierno, abriré un portal para aquellos que deseen viajar hasta allí.$B$BLa batalla está teniendo lugar ahora. ¡Ve corriendo a Conquista del Invierno y ayuda a nuestras tropas!' WHERE `ID`=33137;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새로 타운카 동맹을 얻었으니, 호드는 노스렌드를 정복할 수 있을 걸세.', `MaleText_loc4`='在我们的新盟友牦牛人的帮助下，部落一定会取得诺森德的统治权。', `MaleText_loc5`='有了我們坦卡族新盟友的協助，北裂境將會屬於部落。', `MaleText_loc7`='Con la ayuda de nuestros nuevos aliados taunka, Rasganorte pertenecerá a la Horda.' WHERE `ID`=33138;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대드루이드 릴리안드라에게 돌아가고 싶습니다. 그녀에게 보내 주실 수 있나요?', `MaleText_loc4`='我要返回大德鲁伊莉琳德拉身边。你能送我过去吗？', `MaleText_loc5`='我希望回去找大德魯伊莉莉安卓。你能送我回去找她嗎?', `MaleText_loc7`='Deseo volver junto a la archidruida Lilliandra. ¿Puedes llevarme hasta ella?', `FemaleText_loc1`='대드루이드 릴리안드라에게 돌아가고 싶습니다. 그녀에게 보내 주실 수 있나요?', `FemaleText_loc4`='我要返回大德鲁伊莉琳德拉身边。你能送我过去吗？', `FemaleText_loc5`='我希望回去找大德魯伊莉莉安卓。你能送我回去找她嗎?', `FemaleText_loc7`='Deseo volver junto a la archidruida Lilliandra. ¿Puedes llevarme hasta ella?' WHERE `ID`=33139;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, $c님! 구름의 입맞춤호에 탑승한 걸 환영합니다. 노스렌드는 매우 혹독한 곳일 수 있습니다. 자신을 지킬 준비가 되셨길 바랍니다.', `FemaleText_loc4`='你好啊，$c！欢迎乘坐吻云号。诺森德的环境非常恶劣，希望你已经做好了准备。', `FemaleText_loc5`='你好，$c!歡迎登上拂雲號。北裂境可是個很艱困的地方。希望你做好準備了。', `FemaleText_loc7`='¡Saludos, $c! Te doy la bienvenida a bordo de El Besanubes. Rasganorte puede ser un lugar muy arduo. Espero que hayas hecho las preparaciones necesarias.' WHERE `ID`=33140;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자물쇠 상인', `MaleText_loc4`='锁匠', `MaleText_loc5`='鎖匠', `MaleText_loc7`='Cerrajero', `FemaleText_loc1`='자물쇠 상인', `FemaleText_loc4`='锁匠', `FemaleText_loc5`='鎖匠', `FemaleText_loc7`='Cerrajera' WHERE `ID`=33141;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 그럼 베니크 볼트쉬어를 찾아가셔야겠군요. 베니크는 드워프 지구 중심부에 대장장이들과 함께 있습니다.', `MaleText_loc4`='哦，那么你应该去找本尼克·螺剪。他就在矮人区中心的铁匠铺。', `MaleText_loc5`='你要找的是班尼克·栓剪，他就在矮人區的中心和鐵匠們在一起。', `MaleText_loc7`='Entonces querrás hablar con Benik Cortapernos. Está en el corazón del Distrito de los Enanos, junto a los herreros.', `FemaleText_loc1`='아, 그럼 베니크 볼트쉬어를 찾아가셔야겠군요. 베니크는 드워프 지구 중심부에 대장장이들과 함께 있습니다.', `FemaleText_loc4`='哦，那么你应该去找本尼克·螺剪。他就在矮人区中心的铁匠铺。', `FemaleText_loc5`='你要找的是班尼克·栓剪，他就在矮人區的中心和鐵匠們在一起。', `FemaleText_loc7`='Entonces querrás hablar con Benik Cortapernos. Está en el corazón del Distrito de los Enanos, junto a los herreros.' WHERE `ID`=33142;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='월터 소레프. 도적 지구에서 일해. 열쇠 만든다.', `MaleText_loc4`='沃特尔·索雷夫。盗贼区。他做钥匙。', `MaleText_loc5`='華特·索瑞夫。他在盜賊區工作。他會做鑰匙。', `MaleText_loc7`='Él Walter Soref. Trabajar en Distrito de los Pícaros. Él hacer llaves.', `FemaleText_loc1`='월터 소레프. 도적 지구에서 일해. 열쇠 만든다.', `FemaleText_loc4`='沃特尔·索雷夫。盗贼区。他做钥匙。', `FemaleText_loc5`='華特·索瑞夫。他在盜賊區工作。他會做鑰匙。', `FemaleText_loc7`='Él Walter Soref. Trabajar en Distrito de los Pícaros. Él hacer llaves.' WHERE `ID`=33143;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자물쇠 상인을 찾는다면 하수구로 가보셔야 할 것 같군요. 거기엔 뭐랄까... 질이 좋지 않은 자들이 많거든요.', `MaleText_loc4`='如果你要找锁匠的话，不如去下水道看看？你可以在那里找到许多……名声不太好的家伙。', `MaleText_loc5`='如果你要找個鎖匠，我建議你去下水道瞧瞧?那可以在哪裡找到一些...名聲不太高尚的人。', `MaleText_loc7`='Si estás buscando a un cerrajero, te sugiero las cloacas. Allí es donde encontrarás a más... tipos de dudosa reputación.', `FemaleText_loc1`='자물쇠 상인을 찾는다면 하수구로 가보셔야 할 것 같군요. 거기엔 뭐랄까... 질이 좋지 않은 자들이 많거든요.', `FemaleText_loc4`='如果你要找锁匠的话，不如去下水道看看？你可以在那里找到许多……名声不太好的家伙。', `FemaleText_loc5`='如果你要找個鎖匠，我建議你去下水道瞧瞧?那可以在哪裡找到一些...名聲不太高尚的人。', `FemaleText_loc7`='Si estás buscando a un cerrajero, te sugiero las cloacas. Allí es donde encontrarás más... tipos de dudosa reputación.' WHERE `ID`=33144;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자라니! 감히 내 취미 생활을 방해하는 놈들은 쓴맛을 단단히... 잠깐... 너는...', `MaleText_loc4`='入侵者！你们这些凡人竟敢坏了我的兴致，看我怎么……等等，你们……', `MaleText_loc5`='擅闖者!像你們這種膽敢干涉我好事的凡人將付出...等等--你...', `MaleText_loc7`='¡Entrometidos! Ustedes, mortales, que se atreven a interferir con mi presa pagarán... Espera; tú...' WHERE `ID`=33145;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<알린디아의 몸이 파도에 쓸려 약하게 까딱거립니다. 그녀는 얼마 전에 죽은 듯합니다.>', `MaleText_loc4`='<奥琳迪雅的身躯在海浪中微微晃动着。看样子，她死去已经有一段时间了。>', `MaleText_loc5`='<艾琳迪雅的身體輕飄飄地浮在海浪上。看來她已經死了有一斷時間了。>', `MaleText_loc7`='<El oleaje mece suavemente el cuerpo de Allyndia''s. Parece que lleva tiempo muerta.>', `FemaleText_loc1`='<알린디아의 몸이 파도에 쓸려 약하게 까딱거립니다. 그녀는 얼마 전에 죽은 듯합니다.>', `FemaleText_loc4`='<奥琳迪雅的身躯在海浪中微微晃动着。看样子，她死去已经有一段时间了。>', `FemaleText_loc5`='<艾琳迪雅的身體輕飄飄地浮在海浪上。看來她已經死了有一斷時間了。>', `FemaleText_loc7`='<El oleaje mece suavemente el cuerpo de Allyndia''s. Parece que lleva tiempo muerta.>' WHERE `ID`=33146;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<당신이 다가가자, 세렐리안이 헐떡이는 소리가 들립니다. 서둘러 구한다면, 살릴 가능성이 있어 보입니다.>', `MaleText_loc4`='<你靠近塞瑞利恩，听到他喘息的声音。看样子，如果救治及时，他应该还有机会。>', `MaleText_loc5`='<當你走近時，你聽到塞瑞利恩呼吸的喘氣聲。如果能很快獲得治療，或許還有活下來的機會。>', `MaleText_loc7`='<A medida que te acercas, escuchas cómo Cerellean intenta respirar. Si se le rescata pronto, podría sobrevivir.>', `FemaleText_loc1`='<당신이 다가가자, 세렐리안이 헐떡이는 소리가 들립니다. 서둘러 구한다면, 살릴 가능성이 있어 보입니다.>', `FemaleText_loc4`='<你靠近塞瑞利恩，听到他喘息的声音。看样子，如果救治及时，他应该还有机会。>', `FemaleText_loc5`='<當你走近時，你聽到塞瑞利恩呼吸的喘氣聲。如果能很快獲得治療，或許還有活下來的機會。>', `FemaleText_loc7`='<A medida que te acercas, escuchas cómo Cerellean intenta respirar. Si se le rescata pronto, podría sobrevivir.>' WHERE `ID`=33147;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='건방진 젖먹이 같으니... 감히 여기까지 기어올라와 내게 도전해? 내 손으로 쓸어버리겠다!', `MaleText_loc4`='狂妄的小崽子们，竟敢在我的地盘上挑战我？我要亲自碾碎你们！', `MaleText_loc5`='無禮的小輩，你竟敢在我的王座之上挑戰我?我會親手碾碎你們!', `MaleText_loc7`='Cachorros impertinentes, ¡¿se atreven a desafiarme en la cima de mi pedestal?! ¡Los aplastaré yo mismo!' WHERE `ID`=33148;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<볼코르의 몸이 움직이지 않습니다. 당신이 떠나려 하자, 뻗어온 손이 당신의 발목을 잡습니다. 볼코르가 살아 있습니다!>', `MaleText_loc4`='<沃尔科的身躯纹丝不动。当你抬脚要走开的时候，一只手抓住了你的脚踝。他还活着！>', `MaleText_loc5`='<沃科爾的身體在地上一動也不動。就在你轉身要離開時，一隻手伸出來抓住了你的腳踝。他還活著!>', `MaleText_loc7`='<El cuerpo de Volcor yace inmóvil. Cuando comienzas a alejarte, una mano te agarra el tobillo. ¡Está vivo!>', `FemaleText_loc1`='<볼코르의 몸이 움직이지 않습니다. 당신이 떠나려 하자, 뻗어온 손이 당신의 발목을 잡습니다. 볼코르가 살아 있습니다!>', `FemaleText_loc4`='<沃尔科的身躯纹丝不动。当你抬脚要走开的时候，一只手抓住了你的脚踝。他还活着！>', `FemaleText_loc5`='<沃科爾的身體在地上一動也不動。就在你轉身要離開時，一隻手伸出來抓住了你的腳踝。他還活著!>', `FemaleText_loc7`='<El cuerpo de Volcor yace inmóvil. Cuando comienzas a alejarte, una mano te agarra el tobillo. ¡Está vivo!>' WHERE `ID`=33149;
