UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<당신이 다가가자 게르샬라가 당신을 보려고 옆으로 몸을 돌립니다. 그의 얼굴에 퍼지는 희망에 찬 미소를 볼 수 있습니다.>', `MaleText_loc4`='<戈沙拉翻滚过来，看着你。你在他的脸上发现了一抹充满希望的微笑。>', `MaleText_loc5`='<當你接近時，戈薩拉滾到他那邊注視著你。你看到他臉上浮出了帶著希望的笑容。>', `MaleText_loc7`='<Gershala se pone de costado para mirarte mientras te acercas y ves una sonrisa de esperanza formarse en su cara.>', `FemaleText_loc1`='<당신이 다가가자 게르샬라가 당신을 보려고 옆으로 몸을 돌립니다. 그의 얼굴에 퍼지는 희망에 찬 미소를 볼 수 있습니다.>', `FemaleText_loc4`='<戈沙拉翻滚过来，看着你。你在他的脸上发现了一抹充满希望的微笑。>', `FemaleText_loc5`='<當你接近時，戈薩拉滾到他那邊注視著你。你看到他臉上浮出了帶著希望的笑容。>', `FemaleText_loc7`='<Gershala se pone de costado para mirarte mientras te acercas y ves una sonrisa de esperanza formarse en su cara.>' WHERE `ID`=33151;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<바리스라스의 축 늘어진 몸을 물에서 뒤집으니, 그의 머리에 있는 치명적인 상처가 왜 그가 살아남지 못했는지를 매우 분명하게 보여줍니다.>', `MaleText_loc4`='<当你将巴瑞萨斯瘫软的身体在水中翻转过来的时候，他头顶上一个可怕的伤口赫然出现在你眼前。你立刻明白了他没能撑下去的原因。>', `MaleText_loc5`='<就在你把巴瑞薩斯無生氣的身體由水中轉過來時，他頭上致命的傷口清楚讓你瞭解他為什麼沒有活下來。>', `MaleText_loc7`='<Cuando giras el débil cuerpo de Barithras en el agua, una brutal herida en su cabeza explica claramente por qué no sobrevivió.>', `FemaleText_loc1`='<바리스라스의 축 늘어진 몸을 물에서 뒤집으니, 그의 머리에 있는 치명적인 상처가 왜 그가 살아남지 못했는지를 매우 분명하게 보여줍니다.>', `FemaleText_loc4`='<当你将巴瑞萨斯瘫软的身体在水中翻转过来的时候，他头顶上一个可怕的伤口赫然出现在你眼前。你立刻明白了他没能撑下去的原因。>', `FemaleText_loc5`='<就在你把巴瑞薩斯無生氣的身體由水中轉過來時，他頭上致命的傷口清楚讓你瞭解他為什麼沒有活下來。>', `FemaleText_loc7`='<Cuando giras el débil cuerpo de Barithras en el agua, una brutal herida en su cabeza explica claramente por qué no sobrevivió.>' WHERE `ID`=33156;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<모래에 살짝 묻혀 있는 달몬드는 평화로운 듯합니다.>', `MaleText_loc4`='<达蒙德的身体埋在浅滩中，神色很安详。>', `MaleText_loc5`='<達蒙德的表情看起來還算是平靜，身體一小部份埋在沙中。>', `MaleText_loc7`='<El cuerpo de Dalmond parece casi tranquilo, ligeramente enterrado en la arena.>', `FemaleText_loc1`='<모래에 살짝 묻혀 있는 달몬드는 평화로운 듯합니다.>', `FemaleText_loc4`='<达蒙德的身体埋在浅滩中，神色很安详。>', `FemaleText_loc5`='<達蒙德的表情看起來還算是平靜，身體一小部份埋在沙中。>', `FemaleText_loc7`='<El cuerpo de Dalmond parece casi tranquilo, ligeramente enterrado en la arena.>' WHERE `ID`=33157;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<당신이 다가가자 그론달이 허무하게 당신 쪽을 바라봅니다. 하지만 그의 팔은 생명의 기운이 빠져나가는 듯 털썩 떨어집니다.>', `MaleText_loc4`='<格隆达尔无力地向你伸出手。随着他的生命迅速流逝，他的手臂瘫软了下去。>', `MaleText_loc5`='<格隆達爾無助地向正在靠近的你移動，但當生命之火熄滅時他的雙臂也垂了下來。>', `MaleText_loc7`='<Grondal intenta agarrarte inútilmente mientras te acercas, pero su brazo se desploma a medida que la vida le abandona.>', `FemaleText_loc1`='<당신이 다가가자 그론달이 허무하게 당신 쪽을 바라봅니다. 하지만 그의 팔은 생명의 기운이 빠져나가는 듯 털썩 떨어집니다.>', `FemaleText_loc4`='<格隆达尔无力地向你伸出手。随着他的生命迅速流逝，他的手臂瘫软了下去。>', `FemaleText_loc5`='<格隆達爾無助地向正在靠近的你移動，但當生命之火熄滅時他的雙臂也垂了下來。>', `FemaleText_loc7`='<Grondal intenta agarrarte inútilmente mientras te acercas, pero su brazo se desploma a medida que la vida le abandona.>' WHERE `ID`=33158;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<테렌디스의 눈이 그의 마지막 순간의 슬픔을 보여주는 듯이 멍하니 먼 곳을 응시합니다.>', `MaleText_loc4`='<特伦希斯的眼睛凝望着远方，眨也不眨，其中流露出哀伤的神情。>', `MaleText_loc5`='<特倫希斯雙眼的眨動逐漸停止，掩飾了他死前眼中所透露出的悲傷。>', `MaleText_loc7`='<Los ojos de Terenthis miran fijamente en la distancia, dejando entrever la tristeza de sus últimos momentos.>', `FemaleText_loc1`='<테렌디스의 눈이 그의 마지막 순간의 슬픔을 보여주는 듯이 멍하니 먼 곳을 응시합니다.>', `FemaleText_loc4`='<特伦希斯的眼睛凝望着远方，眨也不眨，其中流露出哀伤的神情。>', `FemaleText_loc5`='<特倫希斯雙眼的眨動逐漸停止，掩飾了他死前眼中所透露出的悲傷。>', `FemaleText_loc7`='<Los ojos de Terenthis miran fijamente en la distancia, dejando entrever la tristeza de sus últimos momentos.>' WHERE `ID`=33159;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<잔혹한 상처가 발다론의 몸에 나 있습니다. 그는 이미 죽었기 때문에 그의 맥박을 확인해 볼 필요가 없습니다.>', `MaleText_loc4`='<瓦尔达隆身上全都是可怕的伤口。你不需要检查他的脉搏就知道，他已经过世了。>', `MaleText_loc5`='<嚴重的傷口一條條布滿了瓦爾達隆的身體。你無須檢查他的脈搏也知道他已無生命跡象。>', `MaleText_loc7`='<Salvajes cortes recorren el cuerpo de Valdaron. No necesitas comprobar su pulso para saber que ya ha muerto.>', `FemaleText_loc1`='<잔혹한 상처가 발다론의 몸에 나 있습니다. 그는 이미 죽었기 때문에 그의 맥박을 확인해 볼 필요가 없습니다.>', `FemaleText_loc4`='<瓦尔达隆身上全都是可怕的伤口。你不需要检查他的脉搏就知道，他已经过世了。>', `FemaleText_loc5`='<嚴重的傷口一條條布滿了瓦爾達隆的身體。你無須檢查他的脈搏也知道他已無生命跡象。>', `FemaleText_loc7`='<Salvajes cortes recorren el cuerpo de Valdaron. No necesitas comprobar su pulso para saber que ya ha muerto.>' WHERE `ID`=33160;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<당신이 다가가자 이 나이트 엘프가 당신 쪽으로 몸을 돌려 손을 잡으려고 합니다.>

이미 늦었어요. 우린 자긍심으로 우리 운명을 결정할 자격을 얻었어요. 가세요... 다른 이들을 살릴 수 있을지 몰라요. 구할 수 있는 자들을 구해주세요.

<그녀에게서 생명이 스르르 빠져나가듯 당신을 움켜쥔 그녀의 손이 느슨해집니다.>', `MaleText_loc4`='<当你靠近这名暗夜精灵的时候，她转向你，并朝你伸出手。>

我已经救不活了。我们因为自身的骄傲而得到这样的命运。走吧……也许还有其他人值得你去救。尽量救助他们。

<随着生命的流逝，她的手又垂了下去。>', `MaleText_loc5`='<當你接近她時，夜精轉了過來抓住了你的手。>

對我來說已經太晚了。我們的榮譽刻劃了命運。去吧...可能有其他人還活著，趕快去幫他們。

<她生命結束時，握著你的手也鬆開了。>', `MaleText_loc7`='<La elfa de la noche se gira hacia ti mientras te acercas e intenta cogerte la mano.>

Es demasiado tarde para mí. Nos hemos ganado nuestro destino con orgullo. Vete... puede que otros lo hayan conseguido. Salva a quienes puedas.

<Su apretón pierde fuerza mientras la vida escapa de ella.>', `FemaleText_loc1`='<당신이 다가가자 이 나이트 엘프가 당신 쪽으로 몸을 돌려 손을 잡으려고 합니다.>

이미 늦었어요. 우린 자긍심으로 우리 운명을 결정할 자격을 얻었어요. 가세요... 다른 이들을 살릴 수 있을지 몰라요. 구할 수 있는 자들을 구해주세요.

<그녀에게서 생명이 스르르 빠져나가듯 당신을 움켜쥔 그녀의 손이 느슨해집니다.>', `FemaleText_loc4`='<当你靠近这名暗夜精灵的时候，她转向你，并朝你伸出手。>

我已经救不活了。我们因为自身的骄傲而得到这样的命运。走吧……也许还有其他人值得你去救。尽量救助他们。

<随着生命的流逝，她的手又垂了下去。>', `FemaleText_loc5`='<當你接近她時，夜精轉了過來抓住了你的手。>

對我來說已經太晚了。我們的榮譽刻劃了命運。去吧...可能有其他人還活著，趕快去幫他們。

<她生命結束時，握著你的手也鬆開了。>', `FemaleText_loc7`='<La elfa de la noche se gira hacia ti mientras te acercas e intenta cogerte la mano.>

Es demasiado tarde para mí. Nos hemos ganado nuestro destino con orgullo. Vete... puede que otros lo hayan conseguido. Salva a quienes puedas.

<Su apretón pierde fuerza mientras la vida escapa de ella.>' WHERE `ID`=33161;
