UPDATE `locales_broadcast_text` SET `MaleText_loc1`='베스프리스투스가 조련한 히포그리프가 그대를 목적지까지 신속하게 데려다 줄 겁니다.', `MaleText_loc4`='维斯派塔斯的角鹰兽可以将你快速送往目的地。', `MaleText_loc5`='維斯派塔斯的角鷹獸會帶你迅速抵達目的地。', `MaleText_loc7`='Los hipogrifos de Vesprystus te conducirán rápidamente a tu destino.', `FemaleText_loc1`='베스프리스투스가 조련한 히포그리프가 그대를 목적지까지 신속하게 데려다 줄 겁니다.', `FemaleText_loc4`='维斯派塔斯的角鹰兽可以将你快速送往目的地。', `FemaleText_loc5`='維斯派塔斯的角鷹獸會帶你迅速抵達目的地。', `FemaleText_loc7`='Los hipogrifos de Vesprystus te conducirán rápidamente a tu destino.' WHERE `ID`=33166;
