UPDATE `locales_broadcast_text` SET `MaleText_loc1`='베스프리스투스를 찾으시는군요. 그는 보통 텔드랏실 숲 속과 이곳을 오가며 히포그리프들을 보살피지요.', `MaleText_loc4`='去找维斯派塔斯吧。他负责管理在泰达希尔底部起落的角鹰兽。', `MaleText_loc5`='你要找的是維斯派塔斯。他管理整個泰達希爾來去的角鷹獸。', `MaleText_loc7`='Es a Vesprystus a quien buscas. Guarda a los hipogrifos que llegan y parten de la base de Teldrassil.', `FemaleText_loc1`='베스프리스투스를 찾으시는군요. 그는 보통 텔드랏실 숲 속과 이곳을 오가며 히포그리프들을 보살피지요.', `FemaleText_loc4`='去找维斯派塔斯吧。他负责管理在泰达希尔底部起落的角鹰兽。', `FemaleText_loc5`='你要找的是維斯派塔斯。他管理整個泰達希爾來去的角鷹獸。', `FemaleText_loc7`='Es a Vesprystus a quien buscas. Guarda a los hipogrifos que llegan y parten de la base de Teldrassil.' WHERE `ID`=33168;
