UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기서 절 좀 꺼내 주세요, 네?', `FemaleText_loc4`='让我离开这里，行吗？', `FemaleText_loc5`='把我救出這，可以嗎?', `FemaleText_loc7`='¿Me sacarás de aquí?' WHERE `ID`=33170;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저 녀석에게 열쇠가 있어요.', `FemaleText_loc4`='那个家伙有钥匙。', `FemaleText_loc5`='鑰匙在蠻卒身上。', `FemaleText_loc7`='Ese bruto tiene la llave.' WHERE `ID`=33171;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노새가 뭔가 기대하는 눈빛으로 당신을 바라봅니다.', `MaleText_loc4`='骡子充满期待地看着你。', `MaleText_loc5`='騾子帶著期望地看著你。', `MaleText_loc7`='La mula te mira expectante.' WHERE `ID`=33172;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 노새는 당신의 친구가 아닙니다.', `MaleText_loc4`='这不是你的骡子。', `MaleText_loc5`='這不是你的騾子。', `MaleText_loc7`='Esta mula no es tuya.' WHERE `ID`=33173;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대격변이 일어나 우리 고향이 파괴되었습니다!$B$B남은 생존자들 모두가 북쪽으로 이동해서 로르다넬을 꾸리고 있지요. 뒤에 남은 우리에겐 목적이 있습니다. 우리는 몸이 회복되는 대로 황혼의 망치단 놈들에게서 아우버다인 폐허를 되찾을 작정입니다!$B$B저들을 상대할 수 있도록 당신이 우리를 도와주시길 바랍니다.', `FemaleText_loc4`='我们的家园在大灾变中被摧毁了！$B$B许多幸存者向北流亡，逐步建立起新奥伯丁。而我们留在这里也是有原因的。等到我们治愈了伤口，就要从那些暮光之锤的恶棍手中夺回旧奥伯丁。$B$B希望你能在那时帮助我们消灭那些敌人。', `FemaleText_loc5`='我們的家園在大災變的時候被毀掉了!$B$B大多生還者都遷移到北方建造洛丹諾了，而我們是有原因才留在這的。等傷好了，我們會將奧伯丁廢墟從那些暮光之錘雜碎們的手中奪回來。$B$B我希望你現在能暫時幫我們對付他們一下。', `FemaleText_loc7`='¡Nuestra casa quedó destruida durante el Cataclismo!$b$bTodos los demás supervivientes se fueron al norte para construir Lor''danel, pero los que nos quedamos tenemos nuestras razones. Reclamaremos las Ruinas de Auberdine de esa escoria del Martillo Crepuscular en cuanto nos recuperemos.$b$bEspero que puedas ayudarnos a encargarnos de ellos hasta entonces.' WHERE `ID`=33174;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말퓨리온 스톰레이지 님을 찾고자 다르나서스에서 남쪽으로 날면서, 전 아우버다인 폐허에서 온 상처입은 난민들을 만났습니다.$B$B저들의 대의는 정당하기에 회복되는 걸 돕는 중입니다. 상처가 많아 회복하는 데 시간이 필요할 겁니다.$B$B그대도 저들을 도와줄 의향이 있으리라 믿습니다.', `MaleText_loc4`='在我从达纳苏斯向南方飞行，寻找玛法里奥·怒风的途中，我遇到了这些受伤的旧奥伯丁难民。$B$B我开始帮忙照料这些伤员，但他们的数量太多了，让他们完全恢复需要很长的时间。$B$B相信你也会愿意帮助他们。', `MaleText_loc5`='在我從達納蘇斯往南飛行，尋找瑪法里恩·怒風的途中，我遇見了奧伯丁廢墟受傷的難民們。$B$B他們都是正義的一方，我便停下來開始治療他們，但身上的傷實在太多，必須花上很久的時間。$B$B我相信你不會吝嗇於幫助他們。', `MaleText_loc7`='Al volar al sur desde Darnassus para buscar a Malfurion Tempestira, me encontré con estos refugiados de las Ruinas de Auberdine heridos.$B$BSu causa es justa y estoy ayudando a sanarlos, pero sus heridas son abundantes y llevará tiempo.$B$BConfío en que tú también querrás prestarles tu ayuda.' WHERE `ID`=33175;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경고: 던 아르골 안에서만 골렘을 사용할 수 있습니다!', `MaleText_loc4`='警告：魔像只能在丹厄古尔使用！', `MaleText_loc5`='警告:魔像只能在丹亞戈內使用!', `MaleText_loc7`='Atención: ¡El gólem solo se puede usar en Dun Argol!' WHERE `ID`=33176;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='수년 전, 어느 멀록들의 문제를 도우려다 비참하게 목숨을 잃고 말았어요. 하지만 저는 여신께로 가는 대신에 남아서 제 가족과 친구들을 지켜보는 걸로 만족했지요.$B$B지금은 제 가족과 친구들도 모두 없거나 죽었고 제가 남은 이유라곤 하나뿐입니다.$B$B바로 복수에요.', `FemaleText_loc4`='多年以前，我本想帮助解决本地的鱼人问题，不料却因此而悲惨地丢了性命。但值得欣慰的是我并未如其他灵魂一般前往女神身边，而是得以留在这里继续看着我的家人和朋友。$B$B现在，他们都已经离开，甚至去世了。我留在这里的理由就只剩下了一个。$B$B复仇。', `FemaleText_loc5`='許多年前，我為了解決一個當地的魚人問題而可悲的喪生了。但我決定留下來看著我的家人和朋友們，而不是去見天上的女神們。$B$B現在他們全都走了，或...死了，而我繼續留在這只剩下一個原因。$B$B復仇。', `FemaleText_loc7`='Hace muchos años, fallecí trágicamente mientras intentaba ayudar con un problema de múrlocs. Pero me decidí quedarme y cuidar de mi familia y amigos en vez de ir con la diosa.$B$BAhora ya se han ido todos, o peor, han muerto y solo tengo una razón para quedarme.$B$BVenganza.' WHERE `ID`=33177;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c님, 신발을 닦아 드릴까요?', `MaleText_loc4`='需要擦鞋吗，$c？', `MaleText_loc5`='需要擦一下鞋嗎，$c?', `MaleText_loc7`='¿Necesitas una limpieza de zapatos, $c?', `FemaleText_loc1`='$c님, 신발을 닦아 드릴까요?', `FemaleText_loc4`='需要擦鞋吗，$c？', `FemaleText_loc5`='需要擦一下鞋嗎，$c?', `FemaleText_loc7`='¿Necesitas una limpieza de zapatos, $c?' WHERE `ID`=33178;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='됐습니다. 깨끗이 신으세요, $c님.', `MaleText_loc4`='好好保养鞋子啊，$c。', `MaleText_loc5`='好好照顧擦亮的鞋子喔，$c。', `MaleText_loc7`='Mantén bien ese brillo, $c.', `FemaleText_loc1`='됐습니다. 깨끗이 신으세요, $c님.', `FemaleText_loc4`='好好保养鞋子啊，$c。', `FemaleText_loc5`='好好照顧擦亮的鞋子喔，$c。', `FemaleText_loc7`='Mantén bien ese brillo, $c.' WHERE `ID`=33179;
