UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신발을 닦아 드릴게요, $c님.', `MaleText_loc4`='让我来帮您擦擦鞋吧，$c。', `MaleText_loc5`='讓我來擦亮你的鞋子吧，$c。', `MaleText_loc7`='Deja que dé brillo a tus zapatos, $c.', `FemaleText_loc1`='신발을 닦아 드릴게요, $c님.', `FemaleText_loc4`='让我来帮您擦擦鞋吧，$c。', `FemaleText_loc5`='讓我來擦亮你的鞋子吧，$c。', `FemaleText_loc7`='Deja que dé brillo a tus zapatos, $c.' WHERE `ID`=33181;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신발이 반짝반짝!', `MaleText_loc4`='真是闪亮啊！', `MaleText_loc5`='閃亮亮!', `MaleText_loc7`='¡Brillante!', `FemaleText_loc1`='신발이 반짝반짝!', `FemaleText_loc4`='真是闪亮啊！', `FemaleText_loc5`='閃亮亮!', `FemaleText_loc7`='¡Brillante!' WHERE `ID`=33182;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신발이 반짝거리니 기분 좋으시죠? 잘 가세요, $c님!', `MaleText_loc4`='又一个体面而又快乐的人，一路顺风，$c！', `MaleText_loc5`='又一個閃亮、愉快的傢伙。小心維持啊，$c!', `MaleText_loc7`='Otra persona brillante y feliz. ¡Cuídate, $c!', `FemaleText_loc1`='신발이 반짝거리니 기분 좋으시죠? 잘 가세요, $c님!', `FemaleText_loc4`='又一个体面而又快乐的人，一路顺风，$c！', `FemaleText_loc5`='又一個閃亮、愉快的傢伙。小心維持啊，$c!', `FemaleText_loc7`='Otra persona brillante y feliz. ¡Cuídate, $c!' WHERE `ID`=33183;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이방인이여, 날 구해줘서 고맙다.', `MaleText_loc4`='感谢你救了我，陌生人。', `MaleText_loc5`='謝謝你救了我，陌生人。', `MaleText_loc7`='Gracias por salvarme.' WHERE `ID`=33184;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황혼의 망치단이 벌인 교묘한 술책의 희생자인 툰드리스 윈드위버의 시체가 큰 대자로 누워 있습니다.', `MaleText_loc4`='桑迪斯·织风的尸体倒伏在这里。这显然是暮光之锤的诡计造成的。', `MaleText_loc5`='桑迪斯·織風陳屍於此處，暮光之錘陰謀下的犧牲者。', `MaleText_loc7`='El cadáver de Thundris Tejevientos se encuentra aquí tirado, aparentemente, víctima de las maquinaciones del Martillo Crepuscular.' WHERE `ID`=33185;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='툰드리스 윈드위버의 영혼을 달랩니다.', `MaleText_loc4`='说服桑迪斯·织风的灵魂。', `MaleText_loc5`='誘哄桑迪斯·織風的靈魂。', `MaleText_loc7`='Sonsaca al espíritu de Thundris Tejevientos.', `FemaleText_loc1`='툰드리스 윈드위버의 영혼을 달랩니다.', `FemaleText_loc4`='说服桑迪斯·织风的灵魂。', `FemaleText_loc5`='誘哄桑迪斯·織風的靈魂。', `FemaleText_loc7`='Sonsaca al espíritu de Thundris Tejevientos.' WHERE `ID`=33186;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='툰드리스 윈드위버의 영혼이 달래집니다.', `MaleText_loc4`='桑迪斯·织风的灵魂被召唤出来。', `MaleText_loc5`='桑迪斯·織風的靈魂被引誘了。', `MaleText_loc7`='El espíritu de Thundris Tejevientos es sonsacado.' WHERE `ID`=33187;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알트루이스가 보호막에 둘러싸였습니다. 보호막을 없애려면 어느 편을 도울지 빨리 선택해야 합니다.', `MaleText_loc4`='阿图里斯升起了护罩。你必须迅速打断他的法术。', `MaleText_loc5`='阿楚依思受到防護。你必須要盡快選擇你的勢力以破除他的法術。', `MaleText_loc7`='Artruis está protegido. Debes decidirte rápido para romper el hechizo.' WHERE `ID`=33188;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서리 표범이 평온하게 누워 있습니다.', `MaleText_loc4`='冰霜豹已经被麻醉了，静静地躺在地上。', `MaleText_loc5`='霜豹平靜地趴在那兒。', `MaleText_loc7`='El leopardo de escarcha yace tranquilo por los efectos del sedante.' WHERE `ID`=33189;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서리 표범의 꼬리를 들춰 암컷인지 수컷인지 감별합니다.', `MaleText_loc4`='拎起冰霜豹的尾巴，检查一下它是雄性还是雌性。', `MaleText_loc5`='拉起霜豹的尾巴確認牠是公的還是母的。', `MaleText_loc7`='Levanta la cola del leopardo de escarcha para ver si es macho o hembra.', `FemaleText_loc1`='서리 표범의 꼬리를 들춰 암컷인지 수컷인지 감별합니다.', `FemaleText_loc4`='拎起冰霜豹的尾巴，检查一下它是雄性还是雌性。', `FemaleText_loc5`='拉起霜豹的尾巴確認牠是公的還是母的。', `FemaleText_loc7`='Levanta la cola del leopardo de escarcha para ver si es macho o hembra.' WHERE `ID`=33190;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성난 수컷입니다!', `MaleText_loc4`='这是一头愤怒的雄性野兽！', `MaleText_loc5`='牠是隻憤怒的雄性!', `MaleText_loc7`='¡Es un macho enfurecido!' WHERE `ID`=33191;
