UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='목마르시죠? 달콤하고 따뜻한 벌꿀술 한 병 어때요? 이리 오세요!', `FemaleText_loc4`='渴了？不如来一壶又暖又甜的蜜酒？快来尝尝吧！', `FemaleText_loc5`='渴了嗎?來點溫熱香甜的蜂蜜酒?來吧!', `FemaleText_loc7`='¿Tienes sed? ¿Te apetece un cántaro de dulce y calentito hidromiel de panal? ¡Por aquí!' WHERE `ID`=33196;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여긴 어디지? 끅!', `MaleText_loc4`='我在哪儿？嗝！', `MaleText_loc5`='我在哪裡?嗝!', `MaleText_loc7`='¿Dónde estoy? ¡Hip!' WHERE `ID`=33197;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 술병 어디 갔어? 당신 알아?', `MaleText_loc4`='我的酒瓶子呢？你看到它了吗？', `MaleText_loc5`='我的瓶子呢?你有看見嗎?', `MaleText_loc7`='¿Dónde está mi botella? ¿Tú la has visto?' WHERE `ID`=33198;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 이래 봬도 주문력이 1850이나 됐다고. 그런데 왜 이렇게 됐지?', `MaleText_loc4`='我的法术强度曾经高达1850，现在这是怎么回事？', `MaleText_loc5`='我之前有1850的法術能量，怎麼回事?', `MaleText_loc7`='Yo solía tener 1850 p. de poder con hechizos... ¿Qué ha pasado?' WHERE `ID`=33199;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='캐러웨이 화끈주 한 잔이면 뱃속이 뜨뜻하답니다. 여기서 팔아요!', `FemaleText_loc4`='没有什么能比一杯茴香烈酒更暖胃啦。来这里购买吧！', `FemaleText_loc5`='沒什麼能比香芹籽燒酒更能溫暖你的胃。這裡就有賣!', `FemaleText_loc7`='Nada como una copa de vino tostado de alcaravea para entrar en calor. ¡Adquiérelo aquí!' WHERE `ID`=33200;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='최고급 겨울자두 증류주 팔아요! 일단 한 잔 드셔보시면 그 매력을 알게 될 걸요...', `FemaleText_loc4`='甘醇的雪梅白兰地！一杯入口，回味无穷！', `FemaleText_loc5`='這裡有賣絕佳的雪李白蘭地!買一杯，體驗它的驚奇感受...', `FemaleText_loc7`='¡Se vende buen brandy de ciruela de nieve! Compra una copita y déjate llevar por sus prodigios...' WHERE `ID`=33201;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이리 오세요! 맛있는 음료 팔아요! 겨울자두 증류주에서 서부정통 버번까지 다양하답니다... 취향대로 고르세요!', `FemaleText_loc4`='美酒应有尽有！从雪梅白兰地到西部荒野威士忌，快来买啊！', `FemaleText_loc5`='賣飲料!好喝的飲料!從雪李白蘭地到西荒波本威士忌...快來喝一杯!', `FemaleText_loc7`='¡Bebidas! ¡Aquí! ¡Deliciosas bebidas! Desde brandy de ciruela de nieve hasta bourbon de los Páramos de Poniente. ¡Adquiere tus bebidas!' WHERE `ID`=33202;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기서 뭐 하시는 겁니까? 안쪽에서 푸른용군단과 싸우고 있어야 하는 거 아닌가요?!', `FemaleText_loc4`='你到外面来干什么？你应该在里面跟蓝龙军团作战！', `FemaleText_loc5`='你在外頭做什麼?你應該在裡面對抗藍龍軍團!', `FemaleText_loc7`='¿Qué haces aquí? ¡Deberías estar dentro batiéndote contra el Vuelo Azul!' WHERE `ID`=33203;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싸울 테니 안으로 들여보내 주세요!', `MaleText_loc4`='我没有在打架，所以赶紧给我找个人来打！', `MaleText_loc5`='我還沒進入戰鬥，所以快送我進去!', `MaleText_loc7`='Yo no me estoy peleando, ¡así que mándame ahí ahora!', `FemaleText_loc1`='싸울 테니 안으로 들여보내 주세요!', `FemaleText_loc4`='我没有在打架，所以赶紧给我找个人来打！', `FemaleText_loc5`='我還沒進入戰鬥，所以快送我進去!', `FemaleText_loc7`='Yo no me estoy peleando, ¡así que mándame ahí ahora!' WHERE `ID`=33204;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 네, 압니다... "하수도에서 낚시라니?!"라고 생각하시는 거죠? 하지만 여기서 뭐가 잡히는지 알면 놀라실 겁니다. 믿으실지 모르겠지만, 저는 상어를 잡았다는 얘기도 들어 봤거든요.', `MaleText_loc4`='我知道，我知道……“在下水道里钓鱼？”但是如果你知道在这里能钓到什么，一定会大吃一惊的。我还听说有人钓到过鲨鱼，你信不信？', `MaleText_loc5`='我知道，我知道...「在下水道釣魚?」你保證會被釣起來東西給嚇一跳的。如果你相信的話，我是聽過關於鯊魚的故事。', `MaleText_loc7`='Ya sé… "¿pescar en una cloaca?" Pero te sorprendería lo que puedes pescar aquí. He oído historias sobre tiburones, aunque te parezca increíble.' WHERE `ID`=33205;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마을을 집어삼킨 정령들이 벌인 살육의 희생자인 파수꾼의 몸이 여기에 쉬고 있습니다.', `FemaleText_loc4`='这名哨兵的尸体倒在地上，他显然是死在元素攻破这座城镇的战斗中。', `FemaleText_loc5`='哨兵的屍體躺在這，這次元素攻擊侵略事件的受害者。', `FemaleText_loc7`='Aquí descansa el cadáver de la centinela, al parecer víctima del ataque elemental que ha invadido el pueblo.' WHERE `ID`=33206;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파수꾼 엘리사 스타브리즈의 시체에서 나온 영혼을 달랩니다.', `MaleText_loc4`='说服那个灵魂，让它离开哨兵艾莉萨·星风的尸体。', `MaleText_loc5`='將哨兵艾麗莎·星風的靈魂從他的身體中誘哄出來。', `MaleText_loc7`='Sonsaca al espíritu del cadáver de la centinela Elissa Brisa Estelar.', `FemaleText_loc1`='파수꾼 엘리사 스타브리즈의 시체에서 나온 영혼을 달랩니다.', `FemaleText_loc4`='说服那个灵魂，让它离开哨兵艾莉萨·星风的尸体。', `FemaleText_loc5`='將哨兵艾麗莎·星風的靈魂從他的身體中誘哄出來。', `FemaleText_loc7`='Sonsaca al espíritu del cadáver de la centinela Elissa Brisa Estelar.' WHERE `ID`=33207;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탈단이 죽기 전 그의 마지막 음료를 판 곳입니다.', `MaleText_loc4`='这里是塔尔丹送上最后一杯饮料的地方。', `MaleText_loc5`='這是塔爾丹喝下他最後一杯酒的地方。', `MaleText_loc7`='Aquí es donde Taldan sirvió su última bebida.' WHERE `ID`=33208;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼이 나올 수 있도록 탈단의 시체를 달랩니다.', `MaleText_loc4`='说服塔尔丹的尸体，让他放弃自己的灵魂。', `MaleText_loc5`='誘哄塔爾丹釋放他的靈魂。', `MaleText_loc7`='Convence al cadáver de Taldan para que renuncie a su espíritu.', `FemaleText_loc1`='영혼이 나올 수 있도록 탈단의 시체를 달랩니다.', `FemaleText_loc4`='说服塔尔丹的尸体，让他放弃自己的灵魂。', `FemaleText_loc5`='誘哄塔爾丹釋放他的靈魂。', `FemaleText_loc7`='Convence al cadáver de Taldan para que renuncie a su espíritu.' WHERE `ID`=33209;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='케이레이와 그녀의 히포그리프들은 이 정령들보다 굉장히 강력했으니 뭔가 다른 것에 목숨을 잃었을 게 분명합니다.', `FemaleText_loc4`='元素没有如此巨大的力量。凯莱斯和她的角鹰兽一定是被另外某个东西打下来的。', `FemaleText_loc5`='這些元素的力量沒有那麼強大，凱萊絲和他的角鷹獸一定是被其他的東西給擊落的。', `FemaleText_loc7`='Caylais y sus hipogrifos, demasiado poderosos para estos elementales, han debido de caer ante otra cosa.' WHERE `ID`=33210;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼이 나올 수 있도록 케이레이 문페더의 시체를 달랩니다.', `MaleText_loc4`='说服那个灵魂，让它离开凯莱斯·月羽的尸体。', `MaleText_loc5`='將凱萊絲·月羽的靈魂從他僵硬的屍體中誘哄出來。', `MaleText_loc7`='Sonsaca al espíritu del cadáver de Caylais Plumalunar.', `FemaleText_loc1`='영혼이 나올 수 있도록 케이레이 문페더의 시체를 달랩니다.', `FemaleText_loc4`='说服那个灵魂，让它离开凯莱斯·月羽的尸体。', `FemaleText_loc5`='將凱萊絲·月羽的靈魂從他僵硬的屍體中誘哄出來。', `FemaleText_loc7`='Sonsaca al espíritu del cadáver de Caylais Plumalunar.' WHERE `ID`=33211;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='멍청한 녀석, 다음은 로르다넬이다. 애테리온 님께서 이 세상으로 거의 다 오셨으니, 이제부턴 시간문제일 뿐이야!', `FemaleText_loc4`='下一个牺牲品就是新奥伯丁，傻瓜。阿瑟里恩几乎已经完全进入这个世界了，一切都只是时间问题！', `FemaleText_loc5`='洛丹諾就是下一個，蠢貨。在伊瑟里奧已經快要完全進入這個世界之下，這不過是遲早的事!', `FemaleText_loc7`='Lor''danel es la siguiente, $gnecio:necia;. Ahora que Aetherion casi ha entrado del todo en este mundo, ¡es solo cuestión de tiempo!' WHERE `ID`=33212;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이곳에서의 일은 시작일 뿐이다. 너희의 피난민 야영지를 박살 내고 북쪽으로 우리 정령들을 이끌어 선두에 선 애테리온 님과 함께 로르다넬을 파괴하고 말겠다!', `FemaleText_loc4`='这个地方只是一个开端。我们会粉碎你们的难民营地，然后率领我们的元素向北，直捣新奥伯丁。阿瑟里恩将是我们的先锋！', `FemaleText_loc5`='這裡發生的只是一個開端。我們會以伊瑟里奧作為先鋒，摧毀你們的難民營後帶領我們的元素上北把洛丹諾也給夷平!', `FemaleText_loc7`='Esto solo es el principio. Aplastaremos tu campamento de refugiados, ¡y luego llevaremos nuestros elementales al norte para destruir Lor''danel con Aetherion en la vanguardia!' WHERE `ID`=33213;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='로르다넬에서 너를 보낸 걸 보니 자포자기인 게 틀림없구나. 우리가 곧 그들을 상대해 주겠다!', `FemaleText_loc4`='新奥伯丁竟然派你这样的人来,他们一定是绝望了。我们很快就会和他们开战了!', `FemaleText_loc5`='洛丹諾一定非常著急才會派你過來。我們很快就會收拾他們!', `FemaleText_loc7`='En Lor''danel tienen que estar desesperados para haberte enviado a ti. ¡Ya nos encargaremos de ellos cuando llegue el momento!' WHERE `ID`=33214;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님께서 이 세상을 산산이 파괴하고 네놈들이 아는 모든 것이 최후를 맞을 것이다. 이번 일은 앞으로 닥칠 일의 맛보기에 불과하단 말이다!', `MaleText_loc4`='我们的主人将打碎这个世界。你所熟知的一切都将终结。现在只是一个小小的开端！', `MaleText_loc5`='我們的主人將會把這個世界撕裂，所有你知道的事物都將會毀滅。現在這個只是前菜!', `MaleText_loc7`='Nuestro maestro partirá el mundo en dos y todo lo que conocéis llegará a su fin. ¡Esto solo es una muestra de lo que os espera!' WHERE `ID`=33215;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='애테리온 님을 이 세계로 모시는 마지막 의식을 막지 못할 거다. 그 광경을 살아서 보지 못할 테니 안 됐구나!', `MaleText_loc4`='你无法阻止我们将阿瑟里恩带到这个世界的最终仪式。可惜的是，你将无法活着看到这一幕！', `MaleText_loc5`='你沒有辦法阻止將伊瑟里奧帶入這個世界的最終儀式。可惜你無法活這見證這一切!', `MaleText_loc7`='No detendrás nuestro ritual definitivo para traer a Aetherion al mundo. ¡Una pena que no vayas a vivir para verlo!' WHERE `ID`=33216;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 모시는 분의 힘을 안다면, 주저 없이 내 앞에 무릎 꿇고 우리 편이 될 거다. 애석하게도 네 무지함이 네 실패를 증명해 줄 거다!', `MaleText_loc4`='如果你明白我所侍奉的是怎样的力量，你必将毫不犹豫地跪倒在我面前，加入我们的行列。可惜的是，你的傲慢只能给你带来毁灭！', `MaleText_loc5`='如果你知道我們主人的力量，你便會毫不猶豫地臣服於我和加入我們。可悲的是，你的無知即將造成你的毀滅。', `MaleText_loc7`='Si supieras a qué poder sirvo, no dudarías en arrodillarte ante mí y unirte a nuestras filas. ¡Por desgracia, tu ignorancia será tu fin!' WHERE `ID`=33217;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐 하는 거냐? 이 세계의 종말이 멀지 않았다는 걸 모르는가? 자, 내가 보여주마!', `MaleText_loc4`='你在干什么？难道你不知道世界末日就要到来了吗？来，让我展示给你看！', `MaleText_loc5`='你在幹什麼，老兄?你不知道末日已經快到了嗎?來，我讓你看看。', `MaleText_loc7`='¿Qué haces, colega? ¿Es que no sabes que eh''ta noche será el fin del mundo? Mira, ¡te lo moh''traré!' WHERE `ID`=33218;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 추추 님을 망쳐보겠다고? 애테리온 님께서 여기에 계신다는 걸 알아둬라. 너희 피난민 야영지로 쳐들어가 너희 로르다넬을 쑤셔놔 주마. 먼저 너부터 죽어야겠다!', `MaleText_loc4`='你要找祖祖的麻烦？没关系……阿瑟里恩在这里，伙计。我们要冲进你们的难民营里去，再去打破你们的新奥伯丁。但首先要死的是你！', `MaleText_loc5`='你找楚祖的麻煩?無所謂...伊瑟里奧在這了，老兄。我們會先碾過你們的難民營後在把苦難帶給洛丹諾。至於現在...你就先死吧!', `MaleText_loc7`='¿Has eh''tado moleh''tando a Tzu-Tzu? No impoh''ta… Aetherion eh''tá aquí, colega. Vamos a pasar por tu campamento de refugiados y luego llevaremos el dolor a tu Lor''danel. Pero primero, ¡muere!' WHERE `ID`=33219;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈과 놀아줄 시간일랑 없다. 애테리온 님께서 준비 중이시란 말이다!', `MaleText_loc4`='没时间和你耗了。阿瑟里恩就快要开始肆虐了！', `MaleText_loc5`='我沒空跟你玩耍。伊瑟里奧已經準備好了!', `MaleText_loc7`='No tengo tiempo para jugar contigo. ¡Aetherion eh''tá casi lih''to para pah''tir!' WHERE `ID`=33220;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 이 세계로 거의 나왔도다. 황혼의 망치단이여, 소환을 서두르지 말라, 아니면 너희도 없애 버리겠다!', `MaleText_loc4`='我就要进入这个世界了。暮光之锤，认真进行召唤仪式，否则我也把你们一并摧毁！', `MaleText_loc5`='我即將抵達。暮光之錘，別匆促地進行召喚儀式，不然我會連你們也一起摧毀!', `MaleText_loc7`='CASI HE LLEGADO. ¡MARTILLO CRESPUESCULAR, NO APRESUREN LA INVOCACIÓN O LOS DESTRUIRÉ A USTEDES TAMBIÉN!' WHERE `ID`=33221;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조그만 녀석, 네놈이 보이는구나. 할 수 있을 때 도망쳐라. 도망쳐 너희 그 애처로운 로르다넬로 가 내가 파괴하러 간다 전해라!', `MaleText_loc4`='我看到你了，爬虫。趁着还能逃跑就拼命逃跑吧。跑去告诉你们那个可怜的洛达内尔，我就要去摧毁它了！', `MaleText_loc5`='我看到你了，蟲子。跑吧，在你還可以前。跑去通知你那可悲的洛丹諾說我它馬上就會毀在我的手裡!', `MaleText_loc7`='¡TE VEO, INSECTO. CORRE MIENTRAS PUEDAS Y DI EN TU PATÉTICA LOR''DANEL QUE VOY A DESTRUIRLA!' WHERE `ID`=33222;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말퓨리온, 내 말이 들리느냐?! 엘룬의 후예들을 없애버릴 때, 내가 널 끝장낼 것이다!', `MaleText_loc4`='玛法里奥，能听到我说话吗？等到我毁灭了艾露恩的孩子们，我就会来把你了结掉！', `MaleText_loc5`='瑪法里恩，你聽的到嗎?等我消滅了伊露恩的孩子後，我就會去把你給處理掉!', `MaleText_loc7`='MALFURION, ¿ME OYES? CUANDO HAYA DESTRUIDO A LAS HIJAS DE ELUNE, ¡VENDRÉ PARA ACABAR CONTIGO!' WHERE `ID`=33223;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 주인님께서 오신다, 필멸의 존재들아! 나는 그저 사자의 군대 일원일 뿐이다. 이 세계는 너희를 끝장 낼 변화를 겪을 것이다!', `MaleText_loc4`='凡人们，我的主人来了！我只是主人大军的传令官。你们的世界将经历巨大的转变，你们全都难逃一死！', `MaleText_loc5`='我的主人快來了，凡人!我只不過是軍團的其中一個信使。你們的世界即將開始轉變，它將看著你們的毀滅!', `MaleText_loc7`='¡MI MAESTRO SE ACERCA, MORTALES! NO SOY MÁS QUE UN MIEMBRO DE UNA LEGIÓN DE HERALDOS. ¡SU MUNDO ESTÁ A PUNTO DE SUFRIR UNA TRANSFORMACIÓN QUE SERÁ SU FINAL!' WHERE `ID`=33224;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='참아내라! 이 세계로 나를 불어내는 의식은 복잡하니 서둘러서는 안 된다!', `MaleText_loc4`='耐心一些！让我进入这个世界的仪式非常复杂，绝不能有任何贸然行动！', `MaleText_loc5`='耐心點!將我帶入這個世界的儀式非常複雜，不准衝動!', `MaleText_loc7`='¡PACIENCIA! ¡EL RITUAL PARA TRAERME A ESTE MUNDO ES COMPLEJO Y NO HAY QUE IR CON PRISA!' WHERE `ID`=33225;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황혼의 망치단 일원이 되어라. 망치단에 속하지 않은 자들은 내가 이 세계로 완전히 넘어왔을 때 죽음이 따를 뿐이리라!', `MaleText_loc4`='现在，加入暮光之锤吧。当我完全进入这个世界的时候，那些不肯屈服的人只能迎来死亡！', `MaleText_loc5`='馬上加入暮光之錘。當我完全進入這個世界時，等待那些異徒的只有死亡!', `MaleText_loc7`='ÚNETE AL MARTILLO CREPUSCULAR AHORA. ¡AQUELLOS QUE NO PERTENEZCAN A ÉL CUANDO ENTRE EN EL MUNDO SOLO CONOCERÁN LA MUERTE!' WHERE `ID`=33226;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실현 가능한 결과는 하나 뿐이다. 대격변은 그저 시작일 뿐이었다. 네놈들이 아는 세계는 끝났다!', `MaleText_loc4`='最终的结局只有一个。大灾变只是一个开始。你所熟悉的这个世界终将灭亡！', `MaleText_loc5`='所有的一切只有一個結果。這場浩劫只是個開始，你認知中的這個世界即將面臨末日的到來!', `MaleText_loc7`='SOLO HAY UN DESENLACE POSIBLE. EL CATACLISMO NO FUE MÁS QUE EL PRINCIPIO. ¡EL MUNDO, TAL Y COMO LO CONOCÉIS, ESTÁ LLEGANDO A SU FIN!' WHERE `ID`=33227;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 필멸의 존재들은 원소로 만들어졌다. 어떻게 승리할 수 있다는 희망을 품을 수 있지? 너희의 진정한 본모습인 자연으로 돌아갈 준비나 해라!', `MaleText_loc4`='你们这些由元素构成的凡人，怎么能妄想反抗真正强大的存在？准备回归到你们真实、根本的状态吧！', `MaleText_loc5`='你們這些凡人不過是由元素所產量的物質所組成的。你們竟然妄想著可以獲得勝利?準備回歸於你們最原始和真實的形態吧!', `MaleText_loc7`='USTEDES, MORTALES, ESTÁN HECHOS DE LA MATERIA DE LOS ELEMENTOS. ¿CÓMO PUEDEN CREER QUE PREVALECERÁN ¡PREPARENSE PARA REGRESAR A SU VERDADERO ESTADO BÁSICO!' WHERE `ID`=33228;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 감히?! 오늘이 로르다넬이 무너지고, 말퓨리온과 네놈이 끝장나는 날이 될 거다!', `MaleText_loc4`='你怎敢如此？！今天，洛达内尔、玛法里奥和你都将彻底毁灭！', `MaleText_loc5`='你敢?!今天將是洛丹諾、瑪法里恩和你們的末日!', `MaleText_loc7`='¡¿CÓMO OSAS?! ¡HOY LLEGARÁ EL FINAL DE LOR''DANEL, DE MALFURION, Y DE TI!' WHERE `ID`=33229;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 다른 이를 키로 판단하지는 않는다, $r|1이여;여;. 중요한 건 용기와 신의이다.', `MaleText_loc4`='我不会根据他们的外表去做出判断，而是根据他们的勇气和忠诚。', `MaleText_loc5`='我不會以身高來評價別人，$r，而是以他們的勇氣與忠誠來論斷。', `MaleText_loc7`='Yo no juzgo a los demás por su estatura, $r, sino por su coraje y lealtad.' WHERE `ID`=33230;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니, 애테리온. 그런 일이 일어나게 두지는 않겠다!', `MaleText_loc4`='不，阿瑟里恩，我们不会允许这样的事情发生！', `MaleText_loc5`='不，伊瑟里奧，我們不會允許發生這種事情!', `MaleText_loc7`='¡No, Aetherion, no permitiremos que eso ocurra!' WHERE `ID`=33231;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 뭐냐? 얄다? 아하하하하하하하하, 너나 그 영혼들이 나를 막을 방법은 없다!', `MaleText_loc4`='这是什么？雅尔达？哈哈哈哈哈哈，你和其他这些灵魂不可能阻止我！', `MaleText_loc5`='什麼?雅爾達?哈哈哈哈哈哈，你們和這些靈魂無力做出任何改變!', `MaleText_loc7`='¿QUÉ ES ESTO? ¿YALDA? ¡JAAJAAAJAAAA! ¡NO HAY NADA QUE TÚ O ESTOS ESPÍRITUS PUEDAN HACER PARA DETENERME!' WHERE `ID`=33232;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두고 보면 알 것이다. 친구들이여, 저자를 약하게 만들어야 해요!', `MaleText_loc4`='走着瞧。让我们合力削弱他，朋友们！', `MaleText_loc5`='拭目以待吧。朋友們，讓我們一起削弱他的力量!', `MaleText_loc7`='Ya veremos. ¡Debilitémoslo, amigos!' WHERE `ID`=33233;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 난장판에 발을 들였지 뭐요. 안 그래도 얼음왕관의 아군과 합류할 때가 지났는데, 스컬지와 드라카리 사이에 옴짝달싹 못하게 끼여 이 난리통에 휘말리다니.$B$B대영주님께 여기 온 건 잘못된 판단이었다고 말씀드렸다오.$B$B가서 뭐 도와줄 일 없나 알아보시오.', `MaleText_loc4`='我们真是焦头烂额了。先是没能及时赶到冰冠冰川与我们的部队会合，现在又处在被天灾军团和达卡莱巨魔两面夹击的险境。$B$B我早就跟大领主说过了，来这里根本就是个错误。$B$B看看你能帮帮我们什么忙吧。', `MaleText_loc5`='我們可是把自己淌進好大的一灘渾水，沒有趕上寒冰皇冠的部隊，結果被困在這場災難中，卡在天譴軍和德拉克瑞之間。$B$B我告訴過大領主來這裡根本是個錯誤。$B$B看你能幫我們點什麼，好讓我們能脫困。', `MaleText_loc7`='Nos hemos metido en una buena. Ya tendríamos que estar con nuestras fuerzas en Corona de Hielo y ahora estamos inmiscuidos en este debacle, encerrados entre la Plaga y los Drakkari.$b$bLe dije al Alto Señor que era un error venir aquí.$b$bVe qué puedes hacer para ayudar.' WHERE `ID`=33234;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='들리는가, $c|1이여;여;? 정령들이 울부짖고 있네. 이 땅이 거의 죽어버렸기 때문이지. 드라카리는 스컬지에 맞서려고 자신들이 섬기던 여러 신을 죽여 그 힘을 훔치고 있네.$B$B근시안적인 행동이지. 결국엔 스스로의 파멸을 가져올 걸세.', `MaleText_loc4`='你听到了吗，$c？元素们哭喊着说，这片土地已经濒临死亡了。达卡莱巨魔正在窃取自己神灵的力量，用以抵御天灾军团。$B$B他们的鼠目寸光终将导致他们自身的毁灭。', `MaleText_loc5`='你聽到嗎，$c?那些元素在哭喊著這片土地幾乎要死去。德拉克瑞靠著殺死他們的神祇，竊取祂們的力量來抵抗天譴軍團。$B$B他們短視近利，總有一天會因為自取滅亡。', `MaleText_loc7`='¿Lo oyes, $c? Los elementos gritan que esta tierra está casi muerta. Los Drakkari están robando el poder de sus dioses al matarlos, solo para defenderse de la Plaga.$b$bSon unos imprudentes y al final solo conseguirán su propia perdición.' WHERE `ID`=33235;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='역병지대의 참상과 희망의 빛 예배당 전투보다도 끔찍한 꼴을 보게 되리라곤 상상도 못 했어요.$B$B그런데 제 생각이 틀렸더군요.', `FemaleText_loc4`='在目睹了瘟疫之地的凄惨和圣光之愿礼拜堂的血战之后，我以为再也看不到比那些更加恐怖的东西了。$B$B但是我错了。', `FemaleText_loc5`='自從瘟疫之地和聖光之願禮拜堂的戰鬥之後，我以為我不會目睹更可怕的景象。$B$B但是我錯了。', `FemaleText_loc7`='Después de lo de las Tierras de la Peste y de la batalla por la Capilla de la Esperanza de la Luz, jamás habría pensado que veríamos algo más horrible.$b$bMe equivocaba.' WHERE `ID`=33236;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 약해진 몸으로도 널 파괴해 버릴 수 있다!!!', `MaleText_loc4`='虽然被削弱了，我还是能摧毁你们！！！', `MaleText_loc5`='就算是這削弱的形態，我也能將你們全數消滅!!!', `MaleText_loc7`='¡INCLUSO EN ESTA FORMA DEBILITADA, LOS DESTRUIRÉ!' WHERE `ID`=33237;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='심호흡 및 준비 완료!', `MaleText_loc4`='你深深吸了一口气，可以开始了！', `MaleText_loc5`='你深吸了一口氣，準備就緒!', `MaleText_loc7`='¡Tus pulmones están llenos y estás $glisto:lista; para la acción!', `FemaleText_loc1`='심호흡 및 준비 완료!', `FemaleText_loc4`='你深深吸了一口气，可以开始了！', `FemaleText_loc5`='你深吸了一口氣，準備就緒!', `FemaleText_loc7`='¡Tus pulmones están llenos y estás $glisto:lista; para la acción!' WHERE `ID`=33238;
