UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론입니다, 프리저. 요리해 보자고요! [PH]', `MaleText_loc4`='Indeed Frizzer, shake and bake! [PH]', `MaleText_loc5`='沒錯，冰結者，搖一搖，烤一烤! [PH]', `MaleText_loc7`='Indeed Frizzer, shake and bake! [PH]', `FemaleText_loc1`='물론입니다, 프리저. 요리해 보자고요! [PH]', `FemaleText_loc4`='Indeed Frizzer, shake and bake! [PH]', `FemaleText_loc5`='沒錯，冰結者，搖一搖，烤一烤! [PH]', `FemaleText_loc7`='Indeed Frizzer, shake and bake! [PH]' WHERE `ID`=33241;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기지개 펴기 및 준비 완료!', `MaleText_loc4`='你的肌肉已经充分伸展，可以开始了！', `MaleText_loc5`='你舒展肌肉，準備就緒!', `MaleText_loc7`='¡Tus músculos están bien estirados y listos para la acción!', `FemaleText_loc1`='기지개 펴기 및 준비 완료!', `FemaleText_loc4`='你的肌肉已经充分伸展，可以开始了！', `FemaleText_loc5`='你舒展肌肉，準備就緒!', `FemaleText_loc7`='¡Tus músculos están bien estirados y listos para la acción!' WHERE `ID`=33242;
