UPDATE `locales_broadcast_text` SET `MaleText_loc1`='별이 나를 도우러 온다!', `MaleText_loc4`='群星将为我而战！', `MaleText_loc5`='繁星為我所用!', `MaleText_loc7`='¡Las estrellas vienen en mi ayuda!' WHERE `ID`=33245;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여신께서 그대를 축복하시길.', `FemaleText_loc4`='女神祝福了你。', `FemaleText_loc5`='女神祝福你。', `FemaleText_loc7`='Que la diosa te bendiga.' WHERE `ID`=33246;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='엘룬의 선물을 받아들이세요.', `FemaleText_loc4`='接受艾露恩的礼物吧。', `FemaleText_loc5`='接受伊露恩的禮物。', `FemaleText_loc7`='Acepta el regalo de Elune.' WHERE `ID`=33247;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='세렐리안! 살았군요!', `FemaleText_loc4`='塞瑞利恩！你还活着！', `FemaleText_loc5`='塞瑞利恩!你辦到了!', `FemaleText_loc7`='¡Cerellean! ¡Lo has conseguido!' WHERE `ID`=33248;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='로르다넬로 그를 데려가겠습니다. 이방인이여, 도와주셔서 고맙습니다.', `FemaleText_loc4`='我会带他回到洛达内尔。感谢你的帮助，陌生人。', `FemaleText_loc5`='我會帶他回到洛丹諾。謝謝你的幫忙，陌生人。', `FemaleText_loc7`='Lo llevaré de vuelta a Lor''danel. Gracias por tu ayuda, $gdesconocido:desconocida;.' WHERE `ID`=33249;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='엘룬께서 그대와 함께하시길.', `FemaleText_loc4`='艾露恩与你同在。', `FemaleText_loc5`='願伊露恩與你同在。', `FemaleText_loc7`='Que Elune esté contigo.' WHERE `ID`=33250;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여사제님, 감사합니다.', `MaleText_loc4`='感谢你，女祭司。', `MaleText_loc5`='謝謝你，女祭司。', `MaleText_loc7`='Gracias, sacerdotisa.', `FemaleText_loc1`='여사제님, 감사해요.', `FemaleText_loc4`='感谢你，女祭司。', `FemaleText_loc5`='謝謝你，女祭司。', `FemaleText_loc7`='Gracias, sacerdotisa.' WHERE `ID`=33251;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엘룬께 영광을!', `MaleText_loc4`='赞美艾露恩！', `MaleText_loc5`='讚美伊露恩!', `MaleText_loc7`='¡Alabada sea Elune!', `FemaleText_loc1`='엘룬께 영광을!', `FemaleText_loc4`='赞美艾露恩！', `FemaleText_loc5`='讚美伊露恩!', `FemaleText_loc7`='¡Alabada sea Elune!' WHERE `ID`=33252;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='많이 좋아졌습니다. 감사합니다.', `MaleText_loc4`='我感觉好多了，谢谢你。', `MaleText_loc5`='我感覺好多了。謝謝你。', `MaleText_loc7`='Me siento mucho mejor. Gracias.', `FemaleText_loc1`='많이 좋아졌습니다. 감사합니다.', `FemaleText_loc4`='我感觉好多了，谢谢你。', `FemaleText_loc5`='我感覺好多了。謝謝你。', `FemaleText_loc7`='Me siento mucho mejor. Gracias.' WHERE `ID`=33253;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아우버다인을 다시 찾아야 합니다!', `MaleText_loc4`='我们一定要夺回奥伯丁！', `MaleText_loc5`='我們必須奪回奧伯丁!', `MaleText_loc7`='¡Debemos recuperar Auberdine!', `FemaleText_loc1`='아우버다인을 다시 찾아야 합니다!', `FemaleText_loc4`='我们一定要夺回奥伯丁！', `FemaleText_loc5`='我們必須奪回奧伯丁!', `FemaleText_loc7`='¡Debemos recuperar Auberdine!' WHERE `ID`=33254;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황혼의 망치단은 그들이 한 짓에 대한 대가를 치러야 합니다.', `MaleText_loc4`='暮光之锤将为他们所做的一切付出代价。', `MaleText_loc5`='暮光之錘將為他們所做的付出代價。', `MaleText_loc7`='El Martillo Crepuscular pagará por lo que han hecho.', `FemaleText_loc1`='황혼의 망치단은 그들이 한 짓에 대한 대가를 치러야 합니다.', `FemaleText_loc4`='暮光之锤将为他们所做的一切付出代价。', `FemaleText_loc5`='暮光之錘將為他們所做的付出代價。', `FemaleText_loc7`='El Martillo Crepuscular pagará por lo que han hecho.' WHERE `ID`=33255;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엘룬 아도레.', `MaleText_loc4`='赞美艾露恩。', `MaleText_loc5`='願伊露恩與你同在。', `MaleText_loc7`='Elune-Adore.', `FemaleText_loc1`='엘룬 아도레.', `FemaleText_loc4`='赞美艾露恩。', `FemaleText_loc5`='願伊露恩與你同在。', `FemaleText_loc7`='Elune-Adore.' WHERE `ID`=33256;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여신의 가호가 있기를.', `FemaleText_loc4`='女神护佑着你。', `FemaleText_loc5`='願女神保佑你。', `FemaleText_loc7`='Que la diosa te proteja.' WHERE `ID`=33257;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='게르샬라... 덴타리아 님께서 그대가 살아 있는 걸 보시면 매우 기뻐하실 겁니다.', `FemaleText_loc4`='戈沙拉……德塔莉亚看到你还活着，一定会非常高兴的。', `FemaleText_loc5`='戈薩拉...丹泰莉雅看到你還活著會非常高興。', `FemaleText_loc7`='Gershala... ¡Dentaria se alegrará tanto de verte con vida!' WHERE `ID`=33258;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여사제님께 그를 데려가겠습니다. 친절에 감사드립니다.', `FemaleText_loc4`='我会把他带回到女祭司那里。衷心感谢你。', `FemaleText_loc5`='我會將他帶回女祭司那。謝謝你的仁慈。', `FemaleText_loc7`='Lo llevaré de vuelta a la sacerdotisa. Gracias por tu amabilidad.' WHERE `ID`=33259;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='샬딘이 무사히 돌아온 걸 확인하겠습니다. 영웅이여, 감사합니다.', `FemaleText_loc4`='我会将莎尔蒂安全地带回去。感谢你，英雄。', `FemaleText_loc5`='我會照顧沙爾迪恩平安的返回。謝謝你，英雄。', `FemaleText_loc7`='Me encargaré de que Shaldyn vuelva a salvo. Gracias, $ghéroe:heroína;.' WHERE `ID`=33260;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='샬딘!', `FemaleText_loc4`='莎尔蒂！', `FemaleText_loc5`='沙爾迪恩!', `FemaleText_loc7`='¡Shaldyn!' WHERE `ID`=33261;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='볼코르... 살아있는 모습을 보니 반갑습니다만, 잔혹발톱은 어디 있지요?', `FemaleText_loc4`='沃科尔……很高兴看到你还活着。但锐爪在哪里？', `FemaleText_loc5`='沃科爾...很高興看到你在這。但銳爪在哪?', `FemaleText_loc7`='Volcor... Me alegro mucho de que lo hayas conseguido. ¿Pero dónde está Zarpadura?' WHERE `ID`=33262;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잔혹발톱에 대한 걱정은 나중에 하지요. 그대를 안전한 곳으로 데려가는 게 우선입니다.', `FemaleText_loc4`='我们以后再担心他吧。现在我先要保障你的安全。', `FemaleText_loc5`='我們待會再擔心他，我必須先將你送到安全的地方。', `FemaleText_loc7`='Ya nos preocuparemos por él más tarde. Tengo que ponerte a salvo.' WHERE `ID`=33263;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='친구여, 그대의 도움에 감사드립니다. 그를 여기서 데려가겠습니다.', `FemaleText_loc4`='朋友，感谢你的帮助。这里就交给我吧。', `FemaleText_loc5`='多謝你的幫忙，朋友。之後就讓我來吧。', `FemaleText_loc7`='Gracias por tu ayuda, $gamigo mío:amiga mía;. Yo me encargo del resto.' WHERE `ID`=33264;
