UPDATE `locales_broadcast_text` SET `MaleText_loc1`='압력은 파괴전차의 속력, 공격력, 방어력을$B증가시키는 데 사용됩니다.$B|TInterface\\Icons\\INV_Gizmo_RocketBootExtreme.blp:32|t |TInterface\\Icons\\INV_Weapon_Rifle_31.blp:32|t', `MaleText_loc4`='压力可以提升攻城车的$B速度、伤害和防御能力。$B|TInterface\\Icons\\INV_Gizmo_RocketBootExtreme.blp:32|t |TInterface\\Icons\\INV_Weapon_Rifle_31.blp:32|t', `MaleText_loc5`='汽壓可以用來強化石毀車的$B速度、傷害和防禦。$B|TInterface\\Icons\\INV_Gizmo_RocketBootExtreme.blp:32|t |TInterface\\Icons\\INV_Weapon_Rifle_31.blp:32|t', `MaleText_loc7`='Se puede emplear la presión para mejorar la$Bvelocidad, daño y defensas del demoledor.$B|TInterfaceIconsINV_Gizmo_RocketBootExtreme.blp:32|t |TInterfaceIconsINV_Weapon_Rifle_31.blp:32|t', `FemaleText_loc1`='압력은 파괴전차의 속력, 공격력, 방어력을$B증가시키는 데 사용됩니다.$B|TInterface\\Icons\\INV_Gizmo_RocketBootExtreme.blp:32|t |TInterface\\Icons\\INV_Weapon_Rifle_31.blp:32|t', `FemaleText_loc4`='压力可以提升攻城车的$B速度、伤害和防御能力。$B|TInterface\\Icons\\INV_Gizmo_RocketBootExtreme.blp:32|t |TInterface\\Icons\\INV_Weapon_Rifle_31.blp:32|t', `FemaleText_loc5`='汽壓可以用來強化石毀車的$B速度、傷害和防禦。$B|TInterface\\Icons\\INV_Gizmo_RocketBootExtreme.blp:32|t |TInterface\\Icons\\INV_Weapon_Rifle_31.blp:32|t', `FemaleText_loc7`='Se puede emplear la presión para mejorar la velocidad, daño y defensas del demoledor.$B|TInterfaceIconsINV_Gizmo_RocketBootExtreme.blp:32|t |TInterfaceIconsINV_Weapon_Rifle_31.blp:32|t' WHERE `ID`=33292;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또한 DEC 기사는 스스로를 발사대에 실을 수 있으며, 파괴전차 조종사는 이를 이용해 기사를 멀리 던질 수 있습니다.$B|TInterface\\Icons\\INV_Misc_EngGizmos_27.blp:32|t', `MaleText_loc4`='操作员还可以将自己装填到装载臂中，$B让攻城车的驾驶员将其发射到远处。$B|TInterface\\Icons\\INV_Misc_EngGizmos_27.blp:32|t', `MaleText_loc5`='DEC操作者還可以把自己裝填進武器中，$B讓石毀車駕駛可以被遠距彈射。$B|TInterface\\Icons\\INV_Misc_EngGizmos_27.blp:32|t', `MaleText_loc7`='El operador de la CMD puede también emplear el brazo de carga,$b lo cual permite al conductor del demoledor lanzarlos a distancia.$B|TInterfaceIconsINV_Misc_EngGizmos_27.blp:32|t', `FemaleText_loc1`='또한 DEC 기사는 스스로를 발사대에 실을 수 있으며, 파괴전차 조종사는 이를 이용해 기사를 멀리 던질 수 있습니다.$B|TInterface\\Icons\\INV_Misc_EngGizmos_27.blp:32|t', `FemaleText_loc4`='操作员还可以将自己装填到装载臂中，$B让攻城车的驾驶员将其发射到远处。$B|TInterface\\Icons\\INV_Misc_EngGizmos_27.blp:32|t', `FemaleText_loc5`='DEC操作者還可以把自己裝填進武器中，$B讓石毀車駕駛可以被遠距彈射。$B|TInterface\\Icons\\INV_Misc_EngGizmos_27.blp:32|t', `FemaleText_loc7`='El operador de la CMD puede también emplear el brazo de carga,$b lo cual permite al conductor del demoledor lanzarlos a distancia.$B|TInterfaceIconsINV_Misc_EngGizmos_27.blp:32|t' WHERE `ID`=33293;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 식으로 파괴전차를 사용함으로써$B목숨, 사지, 수염에 입은 손상에 대해$BGG 정비회사는 |cFFFF2222책임을 지지 않습니다.|r', `MaleText_loc4`='GG工程公司对使用攻城车时$B可能造成的生命、肢体或毛发损失$B|cFFFF2222概不负责|r。', `MaleText_loc5`='GG工程公司|cFFFF2222不需要|r$B因為這樣使用石毀車$B而為許多人命喪生、斷手斷腳或時尚造型被破壞而負責。', `MaleText_loc7`='Ingenieros GG asociados |cFFFF2222no se responsabiliza|r$B de la pérdida de la vida, extremidades o vello facial$B cuando se emplee el demoledor de este modo.', `FemaleText_loc1`='이런 식으로 파괴전차를 사용함으로써$B목숨, 사지, 수염에 입은 손상에 대해$BGG 정비회사는 |cFFFF2222책임을 지지 않습니다.|r', `FemaleText_loc4`='GG工程公司对使用攻城车时$B可能造成的生命、肢体或毛发损失$B|cFFFF2222概不负责|r。', `FemaleText_loc5`='GG工程公司|cFFFF2222不需要|r$B因為這樣使用石毀車$B而為許多人命喪生、斷手斷腳或時尚造型被破壞而負責。', `FemaleText_loc7`='Ingenieros GG asociados |cFFFF2222no se responsabiliza|r$B de la pérdida de la vida, extremidades o vello facial$B cuando se emplee el demoledor de este modo.' WHERE `ID`=33294;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$B$B', `MaleText_loc4`='$B$B', `MaleText_loc5`='$B$B', `MaleText_loc7`='$B$B', `FemaleText_loc1`='$B$B', `FemaleText_loc4`='$B$B', `FemaleText_loc5`='$B$B', `FemaleText_loc7`='$B$B' WHERE `ID`=33295;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='첫 번째 얼라이언스 경비탑이 무너졌다! 세 개를 모두 무너뜨리면 적은 금세 퇴각할 것이다!', `MaleText_loc4`='联盟的第一座塔楼已经被摧毁了！只要我们扫平全部三座塔楼，敌人就不得不撤退了！', `MaleText_loc5`='聯盟的哨塔已經陷落一座了!摧毀那三座哨塔，他們將會敗退得更快!', `MaleText_loc7`='¡Ha caído la primera torre de la Alianza! ¡Destruid las tres y haremos que se apresuren hacia la retirada!' WHERE `ID`=33296;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='록타르! 두 번째 경비탑이 무너졌다! 마지막 경비탑을 파괴하면 적은 금세 퇴각할 것이다!', `MaleText_loc4`='Lok''tar！第二座塔楼已经被摧毁了！只要我们解决最后一座塔楼，敌人就不得不撤退了！', `MaleText_loc5`='為了部落!第二座哨塔陷落了!摧毀最後一座哨塔，我們就能把他們殺得棄甲而逃!', `MaleText_loc7`='¡Lok''tar! ¡La segunda torre ha caído! ¡Destruid la última torre y aceleraremos su retirada!' WHERE `ID`=33297;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스 경비탑이 모두 무너졌다! 이제 놈들은 힘을 잃었다. 잔병을 처리해라!', `MaleText_loc4`='联盟的塔楼全部被摧毁了！他们已经落败。解决残余的敌人！', `MaleText_loc5`='聯盟的哨塔全都陷落了!我們逼退那些傢伙了。把他們的剩餘部隊全解決了!', `MaleText_loc7`='¡Las torres de la Alianza han caído! No les hemos dado treguas. ¡Acabad con lo que quede de su ejército!' WHERE `ID`=33298;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='첫 번째 호드 경비탑이 무너졌다! 세 개를 모두 무너뜨리면 적은 금세 퇴각할 것이다!', `MaleText_loc4`='部落的第一座塔楼已经被摧毁了！只要我们扫平全部三座塔楼，敌人就不得不撤退了！', `MaleText_loc5`='部落的哨塔已經陷落一座了!摧毀那三座哨塔，他們將會敗退得更快!', `MaleText_loc7`='¡Ha caído la primera torre de la Horda! ¡Destruid las tres y haremos que se apresuren hacia la retirada!' WHERE `ID`=33299;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두 번째 경비탑이 무너졌다! 마지막 경비탑을 파괴하면 적은 금세 퇴각할 것이다!', `MaleText_loc4`='第二座塔楼已经被摧毁了！只要我们解决最后一座塔楼，敌人就不得不撤退了！', `MaleText_loc5`='第二座哨塔也陷落了!摧毀最後一座哨塔，我們就能把他們殺得棄甲而逃!', `MaleText_loc7`='¡La segunda torre ha caído! ¡Destruid la última torre y aceleraremos su retirada!' WHERE `ID`=33300;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드 경비탑이 모두 무너졌다! 이제 놈들은 힘을 잃었다. 잔병을 처리해라!', `MaleText_loc4`='部落的塔楼全部被摧毁了！他们已经落败。解决残余的敌人！', `MaleText_loc5`='部落的哨塔全都陷落了!我們逼退那些傢伙了。把他們的剩餘部隊全解決了!', `MaleText_loc7`='¡Las torres de la Horda han caído! No les hemos dado treguas. ¡Acabad con lo que quede de su ejército!' WHERE `ID`=33301;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비밀 암호를 입력하고 새끼 서리고룡을 받고 싶습니다.', `MaleText_loc4`='输入兑换码，领取冰龙宝宝。', `MaleText_loc5`='輸入密碼以領取寵物寒霜幼龍。', `MaleText_loc7`='Introducir código para recibir la cría de hielo.', `FemaleText_loc1`='비밀 암호를 입력하고 새끼 서리고룡을 받고 싶어요.', `FemaleText_loc4`='输入兑换码，领取冰龙宝宝。', `FemaleText_loc5`='輸入密碼以領取寵物寒霜幼龍。', `FemaleText_loc7`='Introducir código para recibir la cría de hielo.' WHERE `ID`=33302;
