UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파괴전차 기계 제어장치 v0.1 알파에 접속하셨습니다.', `MaleText_loc4`='欢迎进入攻城车机师控制台v0.1内部测试版界面。', `MaleText_loc5`='歡迎來到石毀車機械控制臺v0.1初版。', `MaleText_loc7`='$gBienvenido:Bienvenida; a la consola de mecánico del demoledor v0.1 alfa.', `FemaleText_loc1`='파괴전차 기계 제어장치 v0.1 알파에 접속하셨습니다.', `FemaleText_loc4`='欢迎进入攻城车机师控制台v0.1内部测试版界面。', `FemaleText_loc5`='歡迎來到石毀車機械控制臺v0.1初版。', `FemaleText_loc7`='$gBienvenido:Bienvenida; a la consola de mecánico del demoledor v0.1 alfa.' WHERE `ID`=33306;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 시스템을 통해 공성 기계의 탄약과 속도를$B수동으로 제어할 수 있습니다.', `MaleText_loc4`='本系统允许你手动调节$B攻城器械的弹药和速度。', `MaleText_loc5`='這個系統能夠讓你手動調整$B你攻城單位的彈藥與速度。', `MaleText_loc7`='Este sistema te permite ajustar manualmente$bla munición y velocidad de tu unidad de asedio.', `FemaleText_loc1`='이 시스템을 통해 공성 기계의 탄약과 속도를$B수동으로 제어할 수 있습니다.', `FemaleText_loc4`='本系统允许你手动调节$B攻城器械的弹药和速度。', `FemaleText_loc5`='這個系統能夠讓你手動調整$B你攻城單位的彈藥與速度。', `FemaleText_loc7`='Este sistema te permite ajustar manualmente$bla munición y velocidad de tu unidad de asedio.' WHERE `ID`=33307;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시스템을 가동한 후에는,$B 파괴전차를 적절히 관리해야 합니다.', `MaleText_loc4`='一旦启动系统，你就必须手动$B维持攻城车的运作。', `MaleText_loc5`='一旦系統啟動，你就會需要手動控制$B維持你的石毀車。', `MaleText_loc7`='Una vez activado el sistema, deberás realizar$b un mantenimiento manual del demoledor.', `FemaleText_loc1`='시스템을 가동한 후에는,$B 파괴전차를 적절히 관리해야 합니다.', `FemaleText_loc4`='一旦启动系统，你就必须手动$B维持攻城车的运作。', `FemaleText_loc5`='一旦系統啟動，你就會需要手動控制$B維持你的石毀車。', `FemaleText_loc7`='Una vez activado el sistema, deberás realizar$b un mantenimiento manual del demoledor.' WHERE `ID`=33308;
