UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주무기용 탄약은 주기적으로 재장전해야 합니다.$B|TInterface\\Icons\\INV_Misc_Ammo_Bullet_02.blp:32|t', `MaleText_loc4`='主炮必须定时装填弹药。$B|TInterface\\Icons\\INV_Misc_Ammo_Bullet_02.blp:32|t', `MaleText_loc5`='必須要定期填充彈藥。$B|TInterface\\Icons\\INV_Misc_Ammo_Bullet_02.blp:32|t', `MaleText_loc7`='Hay que recargar períodicamente la munición de la unidad principal.$B|TInterfaceIconsINV_Misc_Ammo_Bullet_02.blp:32|t', `FemaleText_loc1`='주무기용 탄약은 주기적으로 재장전해야 합니다.$B|TInterface\\Icons\\INV_Misc_Ammo_Bullet_02.blp:32|t', `FemaleText_loc4`='主炮必须定时装填弹药。$B|TInterface\\Icons\\INV_Misc_Ammo_Bullet_02.blp:32|t', `FemaleText_loc5`='必須要定期填充彈藥。$B|TInterface\\Icons\\INV_Misc_Ammo_Bullet_02.blp:32|t', `FemaleText_loc7`='Hay que recargar periódicamente la munición de la unidad principal.$B|TInterfaceIconsINV_Misc_Ammo_Bullet_02.blp:32|t' WHERE `ID`=33310;
