UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악한 자는 쉴 시간도 없다고 했다. 바로 너 말이다!', `MaleText_loc4`='俗话说狗改不了吃屎。这话说的就是你！', `MaleText_loc5`='俗話說能者多勞。那就是在指你!', `MaleText_loc7`='Dicen que los malditos no descansan. ¡Se refieren a ti!', `FemaleText_loc1`='악한 자는 쉴 시간도 없다고 했다. 바로 너 말이다!', `FemaleText_loc4`='俗话说狗改不了吃屎。这话说的就是你！', `FemaleText_loc5`='俗話說能者多勞。那就是在指你!', `FemaleText_loc7`='Dicen que los malditos no descansan. ¡Se refieren a ti!' WHERE `ID`=33316;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 일은 겁쟁이들이나 하는 일이다. 지금 얼라이언스를 공격해야 한단 말이다!', `MaleText_loc4`='这是懦夫的行为！我们应该去把联盟碾碎，就现在！', `MaleText_loc5`='這是膽小鬼的工作。我們現在應該去打爆聯盟才對!', `MaleText_loc7`='Este es un trabajo para cobardes. ¡Ahora deberíamos estar aplastando a la Alianza!', `FemaleText_loc1`='이 일은 겁쟁이들이나 하는 일이다. 지금 얼라이언스를 공격해야 한단 말이다!', `FemaleText_loc4`='这是懦夫的行为！我们应该去把联盟碾碎，就现在！', `FemaleText_loc5`='這是膽小鬼的工作。我們現在應該去打爆聯盟才對!', `FemaleText_loc7`='Este es un trabajo para cobardes. ¡Ahora deberíamos estar aplastando a la Alianza!' WHERE `ID`=33317;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엘프를 녹여버릴 물약이라고? 네놈에게는 필요할 수도 있겠군, 포세이큰 놈아. 내게는 놈들의 머리통을 으스러뜨릴 철퇴가 있다!', `MaleText_loc4`='一瓶能够溶解精灵的药剂？也许你会需要这种玩意儿，被遗忘者。而我，会用我的锤子好好的给他们上一课！', `MaleText_loc5`='可以溶化精靈們的藥水?你可能需要吧，被遺忘者。我用我的錘子敲碎他們頭骨就行了。', `MaleText_loc7`='¿Una poción para derretir a los elfos? Puede que tú la necesites, Renegado. ¡Yo tengo mi maza para aplastar sus cráneos!', `FemaleText_loc1`='엘프를 녹여버릴 물약이라고? 네놈에게는 필요할 수도 있겠군, 포세이큰 놈아. 내게는 놈들의 머리통을 으스러뜨릴 철퇴가 있다!', `FemaleText_loc4`='一瓶能够溶解精灵的药剂？也许你会需要这种玩意儿，被遗忘者。而我，会用我的锤子好好的给他们上一课！', `FemaleText_loc5`='可以溶化精靈們的藥水?你可能需要吧，被遺忘者。我用我的錘子敲碎他們頭骨就行了。', `FemaleText_loc7`='¿Una poción para derretir a los elfos? Puede que tú la necesites, Renegado. ¡Yo tengo mi maza para aplastar sus cráneos!' WHERE `ID`=33318;
