UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 빨리 일하지 않으면 헬스크림 대족장님께서 네놈의 목을 원하실 것이다!', `MaleText_loc4`='被遗忘者，如果你赶不上进度，地狱咆哮酋长一定会要了你的脑袋！', `MaleText_loc5`='你如果不加快腳步，大酋長地獄吼一定會把你的頭摘下來，被遺忘者。', `MaleText_loc7`='¡El Jefe de Guerra Grito Infernal te arrancará la cabeza si no sigues el ritmo, Renegado!', `FemaleText_loc1`='더 빨리 일하지 않으면 헬스크림 대족장님께서 네놈의 목을 원하실 것이다!', `FemaleText_loc4`='被遗忘者，如果你赶不上进度，地狱咆哮酋长一定会要了你的脑袋！', `FemaleText_loc5`='你如果不加快腳步，大酋長地獄吼一定會把你的頭摘下來，被遺忘者。', `FemaleText_loc7`='¡El Jefe de Guerra Grito Infernal te arrancará la cabeza si no sigues el ritmo, Renegado!' WHERE `ID`=33321;
