UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='토림, 나의 님이시여! 그대를 쓰러뜨릴 목적이 아니라면 왜 저들이 여기 왔겠습니까? 놈들을 막아야 합니다!', `FemaleText_loc4`='托里姆，我的陛下！这些入侵者闯入您的圣殿，除了来杀您，还会有别的意图吗？您必须阻止他们！', `FemaleText_loc5`='索林姆，吾王!這些入侵者來到你的殿堂，除了刺殺你之外還會有什麼意圖?必須阻止他們!', `FemaleText_loc7`='¡Thorim, mi señor! ¿Qué otra razón podrían tener estos invasores para venir a tu santuario que no sea asesinarte? ¡Deben ser detenidos!' WHERE `ID`=33325;
