UPDATE `locales_broadcast_text` SET `MaleText_loc1`='Zomg, 저는 완벽한 수사슴이랍니다. 제 뿔이 마음에 드시나요? 방금 손질을 끝냈거든요. (임시 텍스트)', `MaleText_loc4`='哞，我现在彻底是一头牡鹿了。你喜欢我的角吗？我刚刚把它们抛光了。', `MaleText_loc5`='Zomg, I''m totally a Stag. Do you like my antlers? I just had them polished. (Temp text)', `MaleText_loc7`='Zomg, I''m totally a Stag. Do you like my antlers? I just had them polished. (Temp text)' WHERE `ID`=33339;
