UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='숲 속에 호드가 들끓고 있습니다, $c님. 주변을 조심하십시오!', `FemaleText_loc4`='$c，这片森林里到处都是部落。一定要时刻警惕周围的动静！', `FemaleText_loc5`='森林到處都是部落，$c。隨時注意你周遭的狀況!', `FemaleText_loc7`='Este bosque está lleno de miembros de la Horda, $c. ¡Observa el entorno!' WHERE `ID`=33343;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떠한 위험이 있더라도 스승님의 명령을 수행하려고 이곳에 왔소. 어린 소녀의 목숨이 위태로운데 무슨 일이 이보다도 중요하겠소?', `MaleText_loc4`='我到这里来是为了不惜一切代价完成主人的命令。还有什么比一个命悬一线的小女孩的生命更加重要？', `MaleText_loc5`='我來這是為了完成主人給我的使命，為了成功不計任何代價。一個小女孩的生命懸掛在平衡之中，有什麼能比這更加重要?', `MaleText_loc7`='Estoy aquí para cumplir la voluntad de mi maestro cueste lo que cueste. La vida de una pequeña niña depende de ello y ¿qué podría ser más importante?' WHERE `ID`=33344;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='들쥐로 만든 스튜는 대단히 맛있다오.', `MaleText_loc4`='掘地鼠炖肉美味极了。', `MaleText_loc5`='掘地鼠能做成一道有著驚人美味的燉肉。', `MaleText_loc7`='Con las ratas de madriguera se puede hacer un estofado muy sabroso.' WHERE `ID`=33345;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바다로 돌아가리라... 파도로 돌아가리라...', `MaleText_loc4`='回到海洋中去……回到潮汐中去。', `MaleText_loc5`='回到海洋...回到浪潮。', `MaleText_loc7`='Vuelve al océano... vuelve a las mareas.' WHERE `ID`=33346;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엘룬께서 명하신 대로 파도가 일어나리라.', `MaleText_loc4`='潮汐也服从艾露恩的命令。', `MaleText_loc5`='浪潮聽候伊露恩的差遣。', `MaleText_loc7`='Las mareas hacen lo que Elune ordena.' WHERE `ID`=33347;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필멸의 존재여, 고맙다. 바다의 의지가 자유로워질 거다.', `MaleText_loc4`='感谢你，凡人。海洋的意志是自由的。', `MaleText_loc5`='我們感謝你，凡人。大海自由了。', `MaleText_loc7`='Te lo agradecemos, mortal. La voluntad del océano es ser libre.' WHERE `ID`=33348;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑습니다. 이 야영장은 제가 있던 야영장보다 훨씬 좋군요.$B$B동료가 있다는 건 참 좋은 일입니다. 그들은 제가 혼자라도 호드에 맞서 싸울 수 있도록 전투 기술을 친절하게 가르쳐주었습니다.', `MaleText_loc4`='欢迎你，$g先生:女士;。这片营地比我待过的上一个营地要好多了。$B$B很荣幸，我能够和一群出色的战友共事，他们教会了我不少战斗技巧。现在我已经能独立与部落作战了。', `MaleText_loc5`='歡迎，$g先生:我的女士;。這個營地比我之前的那個好很多。$B$B有新同伴我感到很高興。他們很好地教了我一些戰鬥技巧，讓我能保護自己免於部落的威脅。', `MaleText_loc7`='$GBienvenido señor:Bienvenida señora;. Este campamento es mucho mejor que el que solía tener.$B$BMe alegra tener compañía. Han sido amables y me han enseñado algunas de sus técnicas de lucha para que pueda aguantar contra la Horda.' WHERE `ID`=33349;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='반갑습니다, $c님. 남쪽에서 계속 늘어나는 호드 병력을 고려하면 이곳의 상황이 꽤 좋지 않은 편입니다.$B$B어떤 일이라도 도와주신다면 큰 도움이 될 것입니다.', `FemaleText_loc4`='你好，$c。我们在这里的位置已经暴露了，部落的军队正在南方集结。$B$B我们将非常感激你为我们提供的一切帮助。', `FemaleText_loc5`='你好，$c。部落在南方集結讓我們的情勢有點不利。$B$B任何小幫助我們都會非常的感謝。', `FemaleText_loc7`='Saludos, $c. Nuestra posición está algo expuesta, teniendo en cuenta el aumento de fuerzas de la Horda al sur.$b$bToda la ayuda que puedas aportarnos será bienvenida.' WHERE `ID`=33350;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑습니다, 용사 여러분! 도저히 저놈을 끌어내릴 수가 없군요. 작살포로 놈을 끌어내리게 좀 도와주세요.', `MaleText_loc4`='欢迎，勇士们。我们多次尝试击落她，但是都失败了。你们能不能来帮帮忙，用这些鱼叉炮把她打下来？', `MaleText_loc5`='歡迎，勇士們!我們所有的努力都失敗了。需要有人幫忙用這些魚叉獵槍把她給拉下來。', `MaleText_loc7`='¡Bienvenidos, campeones! Todos nuestros intentos de ponerla en tierra han fallado. Nos vendría bien una mano para bajarla con esos arpones.', `FemaleText_loc1`='반갑습니다, 용사 여러분! 도저히 저놈을 끌어내릴 수가 없군요. 작살포로 놈을 끌어내리게 좀 도와주세요.', `FemaleText_loc4`='欢迎，勇士们。我们多次尝试击落她，但是都失败了。你们能不能来帮帮忙，用这些鱼叉炮把她打下来？', `FemaleText_loc5`='歡迎，勇士們!我們所有的努力都失敗了。需要有人幫忙用這些魚叉獵槍把她給拉下來。', `FemaleText_loc7`='¡Bienvenidos, campeones! Todos nuestros intentos de ponerla en tierra han fallado. Nos vendría bien una mano para bajarla con esos arpones.' WHERE `ID`=33351;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저흰 도와드릴 준비가 됐습니다!', `MaleText_loc4`='我们这就来帮忙！', `MaleText_loc5`='我們準備好要幫忙了!', `MaleText_loc7`='¡Estamos listos para ayudar!', `FemaleText_loc1`='저흰 도와드릴 준비가 됐습니다!', `FemaleText_loc4`='我们这就来帮忙！', `FemaleText_loc5`='我們準備好要幫忙了!', `FemaleText_loc7`='¡Estamos listos para ayudar!' WHERE `ID`=33353;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='만조가 되면 공격한다. 모두 공격 준비!', `FemaleText_loc4`='做好准备。我们将在涨潮时发动攻击！', `FemaleText_loc5`='做好準備。我們在浪潮最猛的時候發動攻擊!', `FemaleText_loc7`='Preparaos. ¡Atacaremos cuando suba la marea!' WHERE `ID`=33354;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='훈련소를 건설하라. 잿빛 골짜기에서 호드나 얼라이언스의 기억조차도 다 씻어내 버릴 것이다!', `FemaleText_loc4`='召集军队。我们将从灰谷清除掉一切联盟和部落的痕迹！', `FemaleText_loc5`='集結軍隊。我們會把聯盟和部落沖出梣谷，連他們存在過的記憶一起沖掉!', `FemaleText_loc7`='Reunid a los bancos. ¡Borraremos hasta los recuerdos de la Alianza y de la Horda de la faz de Vallefresno!' WHERE `ID`=33355;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리의 위대한 여왕님께서 전진을 명하셨다. 적의 피로 바다를 붉게 물들이자!', `FemaleText_loc4`='我们的女王鼓舞我们奋勇前进。让我们将敌人打个落花流水！', `FemaleText_loc5`='我們偉大的女王呼喚著我們前進。讓我們用敵人的血將海水染成紅色!', `FemaleText_loc7`='Nuestra gran reina nos conmina a avanzar. ¡Que las aguas se vuelvan rojas con la sangre de nuestros enemigos!' WHERE `ID`=33356;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='위대한 조람을 불러일으키자! 적들을 옴짝달싹 못하게 조여 부서뜨리자! 적들에게 성난지느러미 일족과 싸우면 어떻게 되는지 가르쳐줘라!', `FemaleText_loc4`='佐拉姆的力量必将崛起！让我们的敌人在我们的触须中被碾碎！冲锋，让他们知道怒尾的强大！', `FemaleText_loc5`='讓佐拉姆的力量解放!讓我們的敵人粉碎於漩渦中!讓他們瞭解與怒尾作對的下場!', `FemaleText_loc7`='¡Que se alce el poder de Zoram! ¡Que nuestros enemigos se asfixien entre nuestras escamas! ¡Id y enseñadles lo que significa enfrentarse a los Colafuria!' WHERE `ID`=33357;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='조람가르 전초기지를 파괴하라! 검은심연 야영지도 파괴하라! 우리는 마에스트라 주둔지로 진격할 것이며, 날이 저물 때면 아스트라나르는 폐허가 되어 있을 것이다!', `FemaleText_loc4`='摧毁佐拉姆加前哨站！摧毁黑渊营地！我们要向梅伊瑟娜岗哨进军。到日落时分，阿斯特兰纳就会成为一片废墟！', `FemaleText_loc5`='摧毀佐拉姆加前哨站!摧毀黑澗營地!向邁斯特拉崗哨前進。當夜晚到來時，阿斯特蘭納將成為廢墟!', `FemaleText_loc7`='¡Destruid la Avanzada de Zoram''gar! ¡Destruid el Campamento Brazanegra! Marcharemos hacia la Atalaya de Maestra, ¡y antes de que caiga la noche Astranaar yacerá en ruinas!' WHERE `ID`=33358;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대격변은 이제 시작되었을 뿐이다. 다리 두 개 달린 자들을 그들의 피로 물든 바다에 수장시켜버리자!', `FemaleText_loc4`='大灾变只是开始。让那些两条腿的家伙们死无葬身之地！', `FemaleText_loc5`='大災變只是個開頭。讓兩隻腳的生物淹死於自己的鮮血中!', `FemaleText_loc7`='El Cataclismo solo es el principio. ¡Que los dos-patas se ahoguen en un mar de su propia sangre!' WHERE `ID`=33359;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전투 준비! 침입자들이 접근한다! 공격하라! 모두 없애버려라!', `FemaleText_loc4`='拿起武器！入侵者就在眼前！把他们彻底消灭，一个也不要留下！', `FemaleText_loc5`='拿起武器!入侵者來了!殺光他們!一個也不留!', `FemaleText_loc7`='¡A las armas! ¡Se acercan invasores! ¡Acaben con ellos! ¡Que no sobreviva nadie!' WHERE `ID`=33360;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네놈이 보이는구나, 땅을 걷는 자여. 내게 오너라... 이야기를 나누자꾸나.', `FemaleText_loc4`='你好，陆行者。过来……我们聊聊。', `FemaleText_loc5`='我看到你了，陸地人。到我這來...我們將賭一賭。', `FemaleText_loc7`='Te veo, caminante. Ven conmigo... Y hablaremos.' WHERE `ID`=33361;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그 끔찍한 저주를 영영 벗어날 수 없다고만 생각했어요. 정말 감사합니다, 이방인이여.', `FemaleText_loc4`='我还以为我永远都没有办法摆脱那个可怕的诅咒了。陌生人，谢谢你。', `FemaleText_loc5`='我以為我永遠也無法擺脫這個可怕的詛咒。我由衷地感謝你，陌生人。', `FemaleText_loc7`='Pensé que jamás me libraría de esa terrible maldición. Tienes mi gratitud, $gforastero:forastera;.' WHERE `ID`=33362;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도움이 됐다니 기쁩니다, 여신님. 한때 당신은 이름난 검을 수호했다고 들었습니다. 어디서 그 검을 찾을 수 있는지 아십니까?', `MaleText_loc4`='乐意为你效劳，女士。听说你曾是一把传说之剑的守护者。你能告诉我该去哪儿寻找这把剑吗？', `MaleText_loc5`='很榮幸能幫得上忙，女士。我聽說您曾是一柄傳說之劍的守護者。請問您知道我可以在哪裡找到它嗎?', `MaleText_loc7`='Encantado de ayudar, mi señora. Me han dicho que fuiste la guardiana de una legendaria espada. ¿Sabes dónde puedo encontrarla?', `FemaleText_loc1`='도움이 됐다니 기쁘네요, 여신님. 한때 당신은 이름난 검을 수호했다고 들었습니다. 어디서 그 검을 찾을 수 있는지 아시나요?', `FemaleText_loc4`='乐意为你效劳，女士。听说你曾是一把传说之剑的守护者。你能告诉我该去哪儿寻找这把剑吗？', `FemaleText_loc5`='很榮幸能幫得上忙，女士。我聽說您曾是一柄傳說之劍的守護者。請問您知道我可以在哪裡找到它嗎?', `FemaleText_loc7`='Encantada de ayudar, mi señora. Me han dicho que fuiste la guardiana de una legendaria espada. ¿Sabes dónde puedo encontrarla?' WHERE `ID`=33363;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제 감사와 함께 검도 받아가세요, $c님.', `FemaleText_loc4`='收下它吧。再次感谢你，$c。', `FemaleText_loc5`='就以它作為我的謝禮吧，$c。', `FemaleText_loc7`='Acéptala con mi gratitud, $c.' WHERE `ID`=33364;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더는 참아줄 수가 없구나!', `MaleText_loc4`='我的耐心已经到头了！', `MaleText_loc5`='我已經失去了耐心!', `MaleText_loc7`='¡Mi paciencia ha alcanzado su límite!' WHERE `ID`=33365;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이게 꿈이야, 생시야? 그 오랜 세월 끝에 마침내 자유라니!', `FemaleText_loc4`='这是真的吗？经历了多年的磨难，我竟然还能重获自由？', `FemaleText_loc5`='這是真的嗎?這麼多年之後重獲自由?', `FemaleText_loc7`='¿Puede ser? ¿Libre después de todos estos años?' WHERE `ID`=33366;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자, 이제 전 호수 안으로 돌아가야겠어요.', `FemaleText_loc4`='现在，我必须返回湖泊了。', `FemaleText_loc5`='現在，我得要回到湖水之中了。', `FemaleText_loc7`='Y ahora, debo regresar a las aguas del lago.' WHERE `ID`=33367;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 직접 손댈 것도 없는 하찮은 생명체입니다. 없애 버리세요!', `FemaleText_loc4`='这些可悲的凡人毫无威胁，根本不值得我动手。干掉他们！', `FemaleText_loc5`='這些可悲的凡人根本毫無威脅，不在我的考量之中。解決他們!', `FemaleText_loc7`='Estos patéticos mortales son inofensivos, por debajo de mi casta. ¡Deshazte de ellos!' WHERE `ID`=33368;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이럴 수가! 토림이시여, 제가 저들에게 싸늘한 죽음을 선사하겠나이다!', `FemaleText_loc4`='这不可能！托里姆陛下，我要让您的敌人在严寒中死去！', `FemaleText_loc5`='不可能!索林姆王，我將讓你的仇敵們在嚴寒之中死去!', `FemaleText_loc7`='¡Imposible! ¡Señor Thorim, daré a sus enemigos una muerte glacial!' WHERE `ID`=33369;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='|cFF00FFFF생명의 어머니의 선물|r이 자라기 시작합니다!', `FemaleText_loc4`='|cFF00FFFF生命缚誓者的礼物|r开始生长！', `FemaleText_loc5`='一個|cFF00FFFF生命守縛者之禮|r開始生長!', `FemaleText_loc7`='¡Un |cFF00FFFFDon de la Protectora|r comienza a crecer!' WHERE `ID`=33370;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저기요! 누구 없어요?', `FemaleText_loc4`='嗨！有人吗？', `FemaleText_loc5`='喂!那有人嗎?', `FemaleText_loc7`='¡Eh! ¿Hay alguien ahí?' WHERE `ID`=33371;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기 좀 도와주세요! 도움이 필요한 아가씨가 있어요! <흥>', `FemaleText_loc4`='有人能帮忙吗？有少女陷入了困境！<哼哼>', `FemaleText_loc5`='誰來幫個忙啊!少女有難啦!<哼>', `FemaleText_loc7`='¡Necesito ayuda! ¡Damisela en apuros! <Bufido>' WHERE `ID`=33372;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여관 꼭대기로 오세요! 저들이 절 묶어놨어요!', `FemaleText_loc4`='到旅店顶上来！他们把我锁起来了！', `FemaleText_loc5`='到旅店的上面來!他們把我鎖在這!', `FemaleText_loc7`='¡En lo alto de la posada! ¡Me tienen encadenada!' WHERE `ID`=33373;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='누가 좀 도와주세요! 저들이 절 제물로 바치기 전에 여기서 절 좀 구해주세요!', `FemaleText_loc4`='有人能救我吗？请救我出去，不要让他们把我当成祭品！', `FemaleText_loc5`='來人幫幫忙啊!在他們犧牲我之前救我出去!', `FemaleText_loc7`='¡Socorro! ¡Que alguien me saque de aquí antes de que me sacrifiquen!' WHERE `ID`=33374;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여관 이 층에 있어요! 어서요!', `FemaleText_loc4`='到旅店二楼！快！', `FemaleText_loc5`='上面這裡!旅店的二樓!快救我!', `FemaleText_loc7`='¡En el segundo piso de la posada! ¡Deprisa!' WHERE `ID`=33375;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='도와주세요! 누구 없어요? 아무나 좀 절 여기서 꺼내 주세요!', `FemaleText_loc4`='有人吗？救命！请把我救出去！', `FemaleText_loc5`='拜託!有沒有人!誰都可以!救我出去!', `FemaleText_loc7`='¡Por favor! ¡Que alguien me ayude! ¡Sáquenme de aquí!' WHERE `ID`=33376;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='세상에나! 다시 누군가를 볼 수 있으리라곤 생각도 못했어요!$B$B여기서 절 구해주세요!', `FemaleText_loc4`='天哪！真没想到我还能看到别人！$B$B请一定救我出去！', `FemaleText_loc5`='我的老天!沒想到我還能活著見到人!$B$B拜託你一定要救我出去!', `FemaleText_loc7`='¡Ay madre! ¡Pensaba que no iba a volver a ver a nadie!$b$b¡Tienes que sacarme de aquí!' WHERE `ID`=33377;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋아요! 여기서 나가죠. 전 무기가 없으니 당신이 절... 아시죠... 보호해 주시면... 정말 고맙겠는데요?', `FemaleText_loc4`='太棒了！让我们离开这里。我没有武器。所以，如果你能……你明白的，如果你能保护我，我一定会非常感激！', `FemaleText_loc5`='太棒了!我們快走吧。我沒有武器，所以如果你能...嗯...保護我的話...我會很感激的...', `FemaleText_loc7`='¡Genial! Salgamos de aquí. No tengo ningún arma, así que te agradecería mucho que... ya sabes... me protejas.' WHERE `ID`=33378;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가죠.', `FemaleText_loc4`='让我们走吧。', `FemaleText_loc5`='走吧。', `FemaleText_loc7`='Vamos.' WHERE `ID`=33379;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='피난민 야영지가 있어요!', `FemaleText_loc4`='这里是难民营地！', `FemaleText_loc5`='難民營就在那!', `FemaleText_loc7`='¡Ahí está el campamento de refugiados!' WHERE `ID`=33380;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='달리기 시합하죠!', `FemaleText_loc4`='我要和你赛跑，看谁先到！', `FemaleText_loc5`='我們來賽跑!', `FemaleText_loc7`='¡Te echo una carrera!' WHERE `ID`=33381;
