UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='엘리사! 오, 저기서 빠져나오니 아주 좋아! 아우버다인은 이교도들과 정령들의 손에 완전히 넘어갔더라고!', `FemaleText_loc4`='艾丽萨！哦，能从那里逃出来可真好！现在奥伯丁已经彻底被邪教徒和元素占领了！', `FemaleText_loc5`='艾麗莎!能逃離那真是太棒了!奧伯丁已經完全被那些教徒和元素占領了!', `FemaleText_loc7`='¡Elisa! ¡Oh, cuánto me alegro de salir de allí! ¡Auberdine está totalmente ocupada por cultores y elementales!' WHERE `ID`=33383;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='알아, 친구. 하지만 넌 이제 안전하고 친구들과 함께 있잖아? 난 네가 죽은 지 알았단 말이야!', `FemaleText_loc4`='啊，女孩，你现在安全地和朋友们在一起了。我还以为你已经死了！', `FemaleText_loc5`='我知道，姑娘，但你現在安全的跟朋友在一起了。我以為你死了!', `FemaleText_loc7`='Ya lo sé, muchacha, pero ahora estás a salvo y entre amigos. ¡Pensaba que estabas muerta!' WHERE `ID`=33384;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 부탁 좀 들어줄래? 여기 내 친구한테 선물을 좀 주지 않겠어? 돈이 없어서 말이야. 아이언포지로 돌아가면 갚을게.', `FemaleText_loc4`='请问，你能给我的这位朋友一些酬金吗？我现在没有钱。但等我回到铁炉堡，就能给你报偿。', `FemaleText_loc5`='你可以幫我個忙嗎?幫我獎勵一下我的朋友?我身上沒有任何金幣。回到鐵爐堡後我就可以還你了。', `FemaleText_loc7`='Tengo que pedirte un favor. ¿Podrías recompensar a mi $gamigo:amiga;? Puedo pagarte cuando volvamos a Forjaz.' WHERE `ID`=33386;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='물론이지. 걱정할 것 없어. 그리고 돈 갚는다는 말도 할 것 없어!', `FemaleText_loc4`='不要这样说。我不想听你说什么给我报偿之类的话！', `FemaleText_loc5`='當然，小事不足掛齒。我可不想再聽到什麼還我錢之類的話!', `FemaleText_loc7`='Pues claro, faltaría más. ¡Y no quiero ni oír hablar de devolverme el favor!' WHERE `ID`=33387;
