UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='엉망이네요. 시체가 있어 보이진 않아요.', `FemaleText_loc4`='它已经被毁坏了，但看样子，这里并没有尸体。', `FemaleText_loc5`='被破壞了，但看來似乎沒有任何的屍體。', `FemaleText_loc7`='Está destrozado, pero no parece que haya cuerpos.' WHERE `ID`=33405;
