UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음, 여기 있는 그런트 중 하나가 저쪽에 있는 놈들 좀 처리해 주면 안 되나?!', `MaleText_loc4`='嗯，你们这些乱哼哼的家伙有没有想过要对付那边的那些人？！', `MaleText_loc5`='嗯...你們其中一個蠻兵可以去解決那邊那些人嗎?!', `MaleText_loc7`='Estooo... ¿Podría alguno de tus brutos encargarse de esos tipos de allí?', `FemaleText_loc1`='음, 여기 있는 그런트 중 하나가 저쪽에 있는 놈들 좀 처리해 주면 안 되나?!', `FemaleText_loc4`='嗯，你们这些乱哼哼的家伙有没有想过 要对付那边的那些人？！', `FemaleText_loc5`='嗯...你們其中一個蠻兵可以去解決那邊那些人嗎?!', `FemaleText_loc7`='Estooo... ¿Podría alguno de tus brutos encargarse de esos tipos de allí?' WHERE `ID`=33533;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 먼저 가보겠네. 경계를 늦추지 말게나. 최대한 빨리 돌아오겠네.', `MaleText_loc4`='我走了。多加小心——我会尽快回来的。', `MaleText_loc5`='我先走了，注意安全。情況允許我馬上就會回來。', `MaleText_loc7`='Me marcho. Ten cuidado; volveré tan pronto como pueda.' WHERE `ID`=33534;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 네놈의 폭발물이 필요하다. 너를 죽이고 감사한 마음으로 가져가 주지.', `MaleText_loc4`='我们需要你的炸药。为此，我很愿意要你的命。', `MaleText_loc5`='我們需要你的炸藥。我會很高興的殺了你後再把它們拿走的。', `MaleText_loc7`='Necesitamos tus explosivos. Disfrutaré matándote para conseguirlos.' WHERE `ID`=33535;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 잘못된 일에 끼어든 거야, 오랜 친구. 이제 짐마차는 우리 것이다!', `MaleText_loc4`='老朋友们，你们站错了队。现在你们的运输队是我的了。', `MaleText_loc5`='你這次選錯邊站了，老朋友。你的商隊現在是我們的了。', `MaleText_loc7`='Esta vez están en el bando equivocado, viejos amigos. Su caravana es nuestra ahora.' WHERE `ID`=33536;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='브루터스크가 기습하며 울부짖습니다!', `MaleText_loc4`='蛮角怒吼着冲入伏兵之中！', `MaleText_loc5`='蠻獠在跳起襲擊的同時大聲的吼叫!', `MaleText_loc7`='¡Brutusk ruge y salta hacia la emboscada!' WHERE `ID`=33537;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자동 수리 절차가 시작되었습니다.', `MaleText_loc4`='已启动自动修复程序。', `MaleText_loc5`='自動修復程序展開。', `MaleText_loc7`='Secuencia de reparación automática iniciada.' WHERE `ID`=33538;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무기 시스템이 정지했습니다.', `MaleText_loc4`='已解除武器系统。', `MaleText_loc5`='武器系統斷線。', `MaleText_loc7`='Sistemas de armamento desconectados.' WHERE `ID`=33539;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 거짓과 기만을 걷어낼 수 있도록 이 수정에 빛의 힘을 불어넣겠어요.', `FemaleText_loc4`='现在，我要将圣光之力注入这块水晶，让它揭穿一切谎言与欺瞒的伪装。', `FemaleText_loc5`='現在，我將聖光之力灌注在這顆水晶中，讓它能破除謊言與欺瞞。', `FemaleText_loc7`='Ahora imbuiré este cristal con el poder de la Luz para abrir paso entre las mentiras y el engaño.' WHERE `ID`=33540;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저희에게 진실을 보는 능력을 허락하소서. 흉악한 자가 저희 사이를 배회한다면, 인도하사 정의를 찾게 하소서.', `FemaleText_loc4`='赐予我们洞悉真相的能力吧。如果凶手就在我们之中，请指引我们寻求正义的裁决。', `FemaleText_loc5`='賦予我們認清真相的能力。如果兇手就在我們之中，請在追尋正義的過程中引領我們。', `FemaleText_loc7`='Otórganos la habilidad de conocer la verdad. Si un asesino camina entre nosotros, guíanos en nuestra búsqueda de justicia.' WHERE `ID`=33541;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엘프들이 없어지기 전까지는 일하지 않을 겁니다!', `MaleText_loc4`='除非精灵滚蛋，否则我就不会工作！', `MaleText_loc5`='我在精靈走前都不工作!', `MaleText_loc7`='¡Yo no trabajar hasta que elfos irse!', `FemaleText_loc1`='엘프들이 없어지기 전까지는 일하지 않겠어요!', `FemaleText_loc4`='除非精灵滚蛋，否则我就不会工作！', `FemaleText_loc5`='我在精靈走前都不工作!', `FemaleText_loc7`='¡Yo no trabajar hasta que elfos irse!' WHERE `ID`=33542;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엘프들이 숲에 있는 일꾼들을 학살하고 있습니다. 안전해질 때까지 이곳에 있을 겁니다.', `MaleText_loc4`='精灵在森林里杀了太多的人。我们要留在这个安全的地方。', `MaleText_loc5`='精靈在森林裡殺死太多的苦工。我要坐在這，這裡安全。', `MaleText_loc7`='Elfos matar muchos peones en bosque. Yo sentar aquí a salvo.', `FemaleText_loc1`='엘프들이 숲에 있는 일꾼들을 학살하고 있어요. 안전해질 때까지 이곳에 있을 거예요.', `FemaleText_loc4`='精灵在森林里杀了太多的人。我们要留在这个安全的地方。', `FemaleText_loc5`='精靈在森林裡殺死太多的苦工。我要坐在這，這裡安全。', `FemaleText_loc7`='Elfos matar muchos peones en bosque. Yo sentar aquí a salvo.' WHERE `ID`=33543;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나무 때문에 죽고 싶지 않습니다!', `MaleText_loc4`='我可不会为一点木头丧命！', `MaleText_loc5`='我不要因為一點木頭死掉!', `MaleText_loc7`='¡Yo no morir por un poco de madera!', `FemaleText_loc1`='나무 때문에 죽고 싶지 않아요!', `FemaleText_loc4`='我可不会为一点木头丧命！', `FemaleText_loc5`='我不要因為一點木頭死掉!', `FemaleText_loc7`='¡Yo no morir por un poco de madera!' WHERE `ID`=33544;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 갑시다, 친구여. 당신이 나무를 베고 제가 엘프들을 막겠습니다. 어떻습니까?', `MaleText_loc4`='来吧，朋友。让我来保护你免受精灵的偷袭，好吗？', `MaleText_loc5`='來，朋友。你來砍...我會保護你不讓精靈傷害你，好嗎?', `MaleText_loc7`='Ven, amigo. Tú corta que yo te protejo de los elfos, ¿vale?', `FemaleText_loc1`='어서 가요, 친구여. 당신이 나무를 베고 제가 엘프들을 막을게요. 어때요?', `FemaleText_loc4`='来吧，朋友。让我来保护你免受精灵的偷袭，好吗？', `FemaleText_loc5`='來，朋友。你來砍...我會保護你不讓精靈傷害你，好嗎?', `FemaleText_loc7`='Ven, amigo. Tú corta que yo te protejo de los elfos, ¿vale?' WHERE `ID`=33545;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘했네. 배신자에게 복수가 행해져서 정말 기쁘군. 미란이 간 동쪽 길로 계속 가서 발굴조사단장 아이언밴드에게 우리는 준비가 모두 끝났다고 전해 주게. 아마 아이언밴드가 자네에게 부탁할 일도 조금 있을 것이네.', `MaleText_loc4`='干得好！那些叛徒终于得到了惩罚。这是一件大快人心的事情。沿着米兰走过的路向东方前进，让勘察员基恩萨·铁环知道我们的胜利。我相信，他也会有一些任务给你。', `MaleText_loc5`='看到叛徒得到報應的感覺真好。順著米蘭剛走過的路往東方前進，讓勘察員基恩薩·鐵環知道我們都已經搞定了。我想他一定也有工作要交代給你。', `MaleText_loc7`='¡Buen trabajo! Me alegro de que alguien se haya vengado de ese traidor. Sigue adelante y toma el mismo camino que siguió Miran, hacia el este, e informa al prospector Vetaferro que estamos listos. Estoy seguro de que tendrá algún trabajo que encargarte.' WHERE `ID`=33546;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와줘서 고맙네. 사옌이 놈들과 한편일 줄 정말 상상도 하지 못했군. 그런 일에 맞설 준비도 되어 있지 않았었고 말이네.', `MaleText_loc4`='很感谢你对我们的帮助。我们从不会认为赛恩是个有同情心的人——我们只是还没有为此做好准备。', `MaleText_loc5`='感謝你這次的幫忙。我們從沒想過賽恩會是個支持者，根本沒預料到會發生這種事情。', `MaleText_loc7`='Agradezco tu ayuda con esto. Jamás hubiéramos sospechado que Saean era un simpatizante... No estábamos preparados para esto.' WHERE `ID`=33547;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='반가워요, $c님.', `FemaleText_loc4`='你好，$c。', `FemaleText_loc5`='你好，$c。', `FemaleText_loc7`='Saludos, $c.' WHERE `ID`=33548;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠. 당신은 그다지 강해 보이지는 않습니다만... 괜찮겠군요.', `MaleText_loc4`='嗯，你看上去不是很强壮……不过应该还成。', `MaleText_loc5`='嗯。你看起來沒有很強...但還算可以。', `MaleText_loc7`='Hmm. No parecer muy duro... pero vale.', `FemaleText_loc1`='흠. 당신은 그다지 강해 보이지는 않지만... 괜찮겠어요.', `FemaleText_loc4`='嗯，你看上去不是很强壮……不过应该还成。', `FemaleText_loc5`='嗯。你看起來沒有很強...但還算可以。', `FemaleText_loc7`='Hmm. No parecer muy duro... pero vale.' WHERE `ID`=33549;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가까이 있어 주십시오, $r|1이여;여;. 엘프들이 가까이 오지 못하게 해 주십시오!', `MaleText_loc4`='别离开我，$r。别让精灵靠近我！', `MaleText_loc5`='別離我太遠，$r。不要讓精靈靠近我!', `MaleText_loc7`='Quédate cerca, $r. ¡Y no dejes que se me acerquen los elfos!', `FemaleText_loc1`='가까이 있어 주세요, $r|1이여;여;. 엘프들이 가까이 오지 못하게 해 주세요!', `FemaleText_loc4`='别离开我，$r。别让精灵靠近我！', `FemaleText_loc5`='別離我太遠，$r。不要讓精靈靠近我!', `FemaleText_loc7`='Quédate cerca, $r. ¡Y no dejes que se me acerquen los elfos!' WHERE `ID`=33550;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 죽도록 내버려 두지는 않을 거죠, 네? 그럼 됐습니다...', `MaleText_loc4`='你不会让我死吧？好吧，那么……', `MaleText_loc5`='你不會讓我被殺掉，對吧?好吧...', `MaleText_loc7`='Tú no dejar que yo morir, ¿verdad? Entonces, vale...', `FemaleText_loc1`='제가 죽도록 내버려 두지는 않을 거죠, 네? 그럼 됐어요...', `FemaleText_loc4`='你不会让我死吧？好吧，那么……', `FemaleText_loc5`='你不會讓我被殺掉，對吧?好吧...', `FemaleText_loc7`='Tú no dejar que yo morir, ¿verdad? Entonces, vale...' WHERE `ID`=33551;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밤호랑이를 타고 아스트라나르로 가고 싶습니다.', `MaleText_loc4`='哨兵，我想骑着你的一头夜刃豹去阿斯特兰纳。', `MaleText_loc5`='哨兵，我想騎你的其中一隻夜刃豹到阿斯特蘭納。', `MaleText_loc7`='Centinela, me gustaría montar en uno de tus sables de la noche para ir a Astranaar.', `FemaleText_loc1`='밤호랑이를 타고 아스트라나르로 가고 싶어요.', `FemaleText_loc4`='哨兵，我想骑着你的一头夜刃豹去阿斯特兰纳。', `FemaleText_loc5`='哨兵，我想騎你的其中一隻夜刃豹到阿斯特蘭納。', `FemaleText_loc7`='Centinela, me gustaría montar en uno de tus sables de la noche para ir a Astranaar.' WHERE `ID`=33552;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속해서 망을 보십시오! 사방에 엘프들이 들끓고 있습니다!', `MaleText_loc4`='一定要小心，$r！这里到处都是精灵！', `MaleText_loc5`='保持警戒，$r!精靈們無所不在!', `MaleText_loc7`='¡Tú vigilar, $r! ¡Los elfos estar por todas partes!', `FemaleText_loc1`='계속해서 망을 보세요! 사방에 엘프들이 들끓고 있어요!', `FemaleText_loc4`='一定要小心，$r！这里到处都是精灵！', `FemaleText_loc5`='保持警戒，$r!精靈們無所不在!', `FemaleText_loc7`='¡Tú vigilar, $r! ¡Los elfos estar por todas partes!' WHERE `ID`=33553;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 그만 죽어라.', `MaleText_loc4`='去死吧。', `MaleText_loc5`='躺下接受死亡。', `MaleText_loc7`='Túmbate y muere.' WHERE `ID`=33554;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음은 너의 삶에서 피할 수 없는 결말일 뿐이다.', `MaleText_loc4`='死亡只是你的生命的必然结果。', `MaleText_loc5`='死亡是你無法扭轉的命運。', `MaleText_loc7`='La muerte es un final inevitable para tu vida.' WHERE `ID`=33555;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈이 어디에 있든 그 밑에는 우리가 있다.', `MaleText_loc4`='我们遍布在你下方。', `MaleText_loc5`='在地下，我們無所不在。', `MaleText_loc7`='Estamos en todas partes bajo ustedes.' WHERE `ID`=33556;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이것은 새로운 시작이다. 다가오는 너의 운명을 기쁘게 맞아라.', `MaleText_loc4`='这是新的开始。为你们的末日而欣喜吧。', `MaleText_loc5`='這是個新的開始。為即將到來的毀滅歡慶吧。', `MaleText_loc7`='Este es el nuevo comienzo. Regocíjense en su final.' WHERE `ID`=33557;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지하에서 솟아오르는 촉수를 받아들여라.', `MaleText_loc4`='拥抱从深渊崛起的未来吧。', `MaleText_loc5`='擁抱由地底升起的未來。', `MaleText_loc7`='Abrazad el futuro que surge desde debajo.' WHERE `ID`=33558;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하트와이즈, 저항은 그만둬라.', `MaleText_loc4`='丛林守护者哈特维斯，停止你的反抗。', `MaleText_loc5`='守衛者智心，放棄你的抵抗。', `MaleText_loc7`='Vigilante Corazón Sabio, no opongas resistencia.' WHERE `ID`=33559;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필멸의 존재여, 네놈은 반드시 박멸되어야 할 전염병이다.', `MaleText_loc4`='凡间的生物，你们是必须被清除的害虫。', `MaleText_loc5`='凡人生物，你們是必須被淨化的病毒。', `MaleText_loc7`='Criatura mortal, tú eres la infestación que hay que purgar.' WHERE `ID`=33560;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오라, 언제든지 내게 오라. 성심껏 문제를 의논해 보자꾸나.', `MaleText_loc4`='来和我聊聊吧。让我们以文明的方式讨论一些事情。', `MaleText_loc5`='來，放輕鬆與我對話。讓我們用文明的方式來討論事情。', `MaleText_loc7`='Ven, habla conmigo cuando te convenga. Discutamos los problemas de forma civilizada.' WHERE `ID`=33561;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='있던 곳으로 되돌아가라, 사악한 괴물아!', `MaleText_loc4`='回到你原来的地方去吧，污秽的生物！', `MaleText_loc5`='回到你原來的地方去，骯髒的生物!', `MaleText_loc7`='¡Regresa al lugar del que viniste, repugnante criatura!' WHERE `ID`=33562;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끝장을 내주마!', `MaleText_loc4`='你将被摧毁！', `MaleText_loc5`='你將被摧毀!', `MaleText_loc7`='¡Te destruiré!' WHERE `ID`=33563;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뒤로 물러나라고 했다!', `MaleText_loc4`='给我回去！', `MaleText_loc5`='我說...後退!', `MaleText_loc7`='¡Digo que volváis!' WHERE `ID`=33564;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엘룬의 빛이 네놈을 없앨 것이다!', `MaleText_loc4`='艾露恩之光将击败你！', `MaleText_loc5`='伊露恩之光超渡你!', `MaleText_loc7`='¡Te destruiré!' WHERE `ID`=33565;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈이 어떤 존재인지는 모르지만, 곧 죽을 것이라는 건 안다!', `MaleText_loc4`='我不知道你是什么玩意儿，但我知道，你必死无疑！', `MaleText_loc5`='我不知道你是什麼東西，只知道你會死!', `MaleText_loc7`='¡No sé que eres, pero sé que morirás!' WHERE `ID`=33566;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엘룬의 영광으로 시들어 죽어라!', `MaleText_loc4`='在艾露恩的神恩中枯萎吧！', `MaleText_loc5`='凋零於伊露恩的仁慈之下!', `MaleText_loc7`='¡Marchítate en la gracia de Elune!' WHERE `ID`=33567;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 세계에서 네놈을 없애 주겠다!', `MaleText_loc4`='我会将你从这个世界清除掉！', `MaleText_loc5`='我會將你抹消於這世界!', `MaleText_loc7`='¡Te eliminaré de la faz de la tierra!' WHERE `ID`=33568;
