UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈의 시체는 부활하는 자들의 먹이가 될 것이다!', `MaleText_loc4`='你残破的身躯将成为新的力量崛起的养料！', `MaleText_loc5`='它甦醒後將以你的屍骸為食!', `MaleText_loc7`='¡Tus restos alimentarán a AQUEL que surge!' WHERE `ID`=33583;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 형상은 아무 의미가 없다. 우리에게 끝이란 없다.', `MaleText_loc4`='这个躯壳毫无意义。我们永无终结。', `MaleText_loc5`='這個形態沒有任何意義。我們是不滅的。', `MaleText_loc7`='Esta forma no significa nada. No tenemos fin.' WHERE `ID`=33584;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음 전투의 결말이 날 때까지 %s|1이;가; 돌로 돌아갑니다.', `MaleText_loc4`='%s变成了一尊石像，等待下一场战斗分出胜负。', `MaleText_loc5`='%s回到石頭中直到下一次變化。', `MaleText_loc7`='%s se vuelve de piedra hasta que concluya la siguiente batalla.' WHERE `ID`=33585;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 전투가 시작되려는 걸 느끼고 돌로 돌아갈 준비를 합니다.', `MaleText_loc4`='%s察觉到一场战斗即将爆发，准备变回一尊石像。', `MaleText_loc5`='%s感應到戰鬥逼近，準備變回石頭。', `MaleText_loc7`='%s percibe la batalla que se aproxima y se prepara para volverse de piedra.' WHERE `ID`=33586;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가까운 사로나이트 증기 구름이 합쳐집니다!', `MaleText_loc4`='一团萨隆邪铁蒸汽在附近聚集起来！', `MaleText_loc5`='一片薩倫煙霧在附近聚合!', `MaleText_loc7`='¡Cerca se forma una nube de vapores de saronita!' WHERE `ID`=33587;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마에스트라 주둔지로 갈 밤호랑이가 필요합니다.', `MaleText_loc4`='露亚娜，我要骑着你的一头夜刃豹去梅伊瑟娜岗哨。', `MaleText_loc5`='露兒拉，我想騎一隻你的夜刃豹到邁斯特拉崗哨。', `MaleText_loc7`='Luara, me gustaría tomar prestado uno de tus sables de la noche para ir a la Atalaya de Maestra.', `FemaleText_loc1`='마에스트라 주둔지로 갈 밤호랑이가 필요해요.', `FemaleText_loc4`='露亚娜，我要骑着你的一头夜刃豹去梅伊瑟娜岗哨。', `FemaleText_loc5`='露兒拉，我想騎一隻你的夜刃豹到邁斯特拉崗哨。', `FemaleText_loc7`='Luara, me gustaría tomar prestado uno de tus sables de la noche para ir a la Atalaya de Maestra.' WHERE `ID`=33588;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘도 날 찾아내셨군? 문제없지, 여기서 목숨을 잃으면 아무에게도 말하지 못할 테니까!', `MaleText_loc4`='终于找到我了？没关系，你不可能有机会再把这件事告诉别人了！', `MaleText_loc5`='還是讓你找到了，嗯?無所謂，反正你無法活著跟任何人說!', `MaleText_loc7`='Has conseguido encontrarme, ¿eh? ¡No importa, no vivirás para contárselo a nadie!' WHERE `ID`=33589;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어서 서두르게, $r.', `FemaleText_loc4`='快点儿，$r。', `FemaleText_loc5`='有話快說，$r。', `FemaleText_loc7`='Que sea rápido, $r.' WHERE `ID`=33590;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='서두르게! 지금 이러고 있을 시간이 없네!$b$b토막나무 주둔지는 절대로 함락당하면 안 돼!', `FemaleText_loc4`='快一点，$c！没时间磨蹭了！$b$b碎木岗哨绝不能失守。', `FemaleText_loc5`='快，$c!沒有多餘的時間可以浪費!$b$b我們不可以失去碎木!', `FemaleText_loc7`='¡Rápido, $c! ¡No hay tiempo que perder!$b$b¡El Hachazo no debe caer!' WHERE `ID`=33591;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카드라크에게 갈 준비가 됐습니다!', `MaleText_loc4`='我准备好了，戈尔卡，去找卡德拉克！', `MaleText_loc5`='我準備好了，戈爾卡。往卡德拉克前進!', `MaleText_loc7`='Estoy listo, Gorka. ¡A Kadrak!', `FemaleText_loc1`='카드라크에게 갈 준비가 됐습니다!', `FemaleText_loc4`='我准备好了，戈尔卡，去找卡德拉克！', `FemaleText_loc5`='我準備好了，戈爾卡。往卡德拉克前進!', `FemaleText_loc7`='Estoy lista, Gorka. ¡A Kadrak!' WHERE `ID`=33592;
