UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사로나이트 증기가 한 덩어리가 되어 맹렬하게 소용돌이치며, 무시무시한 형상으로 변화합니다!', `MaleText_loc4`='萨隆邪铁蒸汽剧烈地旋转着，汇集成一个畸体。', `MaleText_loc5`='薩倫煙霧聚集起來並且劇烈地旋轉，形成一個怪物般的形體!', `MaleText_loc7`='¡Los vapores de saronita se arremolinan y se unen para dar cuerpo a una forma monstruosa!' WHERE `ID`=33594;
