UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너흰 너무 멀리까지 왔어. 많은 시간을 낭비했다...', `FemaleText_loc4`='你们漂泊得太远了，浪费了太多的时间……', `FemaleText_loc5`='你們迷途已久。浪費了太多時間...', `FemaleText_loc7`='Te has desviado demasiado de tu rumbo. Has desperdiciado demasiado tiempo…' WHERE `ID`=33605;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='움직이세요! 오래 붙잡아둘 순 없을 겁니다!', `MaleText_loc4`='快一点！她马上就要挣脱了！', `MaleText_loc5`='快!她可不會在地面上待太久!', `MaleText_loc7`='¡Muévanse rápido! ¡No se quedará en el suelo por mucho tiempo!' WHERE `ID`=33606;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정신 바짝 차리세요! 곧 땅에서 굴착기가 솟아나 성가신 무쇠 드워프를 쏟아낼 겁니다!', `MaleText_loc4`='保持警惕！钻探机即将冒出地表，讨厌的铁矮人就要来了！', `MaleText_loc5`='小心戒備!那些噁心的鐵矮人一登陸，鑽地機就可能會隨時出現!', `MaleText_loc7`='¡Cuidado! Pronto saldrán a la superficie máquinas topo con esos desagradables enanos férreos a bordo!' WHERE `ID`=33607;
