UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부서뜨려 주마... 그를 부숴버렸던 것처럼!', `MaleText_loc4`='我会毁灭你……就像我毁灭了他那样！', `MaleText_loc5`='我會粉碎你的意志...就像粉碎他的一樣!', `MaleText_loc7`='¡Te destruiré... como a él!' WHERE `ID`=33609;
