UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드와 린 폐하께 영광 있으라!', `MaleText_loc4`='荣耀属于暴风城和乌瑞恩国王！', `MaleText_loc5`='榮耀歸於暴風城與烏瑞恩王!', `MaleText_loc7`='¡Gloria a Ventormenta y al rey Wrynn!' WHERE `ID`=33612;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 마상 전투를 벌일 준비가 안 되신 것 같군요.', `MaleText_loc4`='看来你还没有做好骑乘作战的准备。', `MaleText_loc5`='看來你還沒準備好騎乘戰鬥。', `MaleText_loc7`='Parece que no estabas $glisto:lista; para el combate $gmontado:montada;.', `FemaleText_loc1`='아직 마상 전투를 벌일 준비가 안 되신 것 같군요.', `FemaleText_loc4`='看来你还没有做好骑乘作战的准备。', `FemaleText_loc5`='看來你還沒準備好騎乘戰鬥。', `FemaleText_loc7`='Parece que no estabas $glisto:lista; para el combate $gmontado:montada;.' WHERE `ID`=33613;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='온종일 당신과 싸울 수는 없습니다. 기술을 좀 더 연마한 후에 다시 도전하시지요.', `MaleText_loc4`='我可没时间整天跟你打斗。等你的技能提升之后再来挑战我吧。', `MaleText_loc5`='我可沒空跟你打。等你的技巧更精進的時候再來挑戰我吧。', `MaleText_loc7`='No tengo todo el día para luchar contigo. Enfréntate a mí cuando tu habilidad haya mejorado.', `FemaleText_loc1`='온종일 당신과 싸울 수는 없어요. 기술을 좀 더 연마한 후에 다시 도전하시지요.', `FemaleText_loc4`='我可没时间整天跟你打斗。等你的技能提升之后再来挑战我吧。', `FemaleText_loc5`='我可沒空跟你打。等你的技巧更精進的時候再來挑戰我吧。', `FemaleText_loc7`='No tengo todo el día para luchar contigo. Enfréntate a mí cuando tu habilidad haya mejorado.' WHERE `ID`=33614;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='기다리게, $n! 쉬운 일이 아니야!', `FemaleText_loc4`='坚持住，$n！这可不是容易的事情！', `FemaleText_loc5`='慢點，$n!這沒那麼簡單!', `FemaleText_loc7`='¡Espera, $n! ¡Esto no va a ser fácil!' WHERE `ID`=33615;
