UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혹은, 하나의 살인.', `MaleText_loc4`='或者杀戮别人。', `MaleText_loc5`='或是成為一名兇手。', `MaleText_loc7`='O un asesinato.' WHERE `ID`=33617;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 엘프들과 그들의 동료인 드레나이들을 모조리 죽여라, 지금 당장!', `MaleText_loc4`='我希望那些精灵和他们的德莱尼朋友现在就完蛋！', `MaleText_loc5`='我要那些精靈和他們的德萊尼朋友從這世上消失，現在!', `MaleText_loc7`='Quiero ver a esos elfos y sus amigos draenei muertos... ¡Ahora!' WHERE `ID`=33618;
