UPDATE `locales_broadcast_text` SET `MaleText_loc1`='병력을 소집하라! 숲의 노래로 진군한다!', `MaleText_loc4`='召集战友！向林歌神殿进发！', `MaleText_loc5`='集結一組小隊!往林歌神殿前進!', `MaleText_loc7`='¡Reúne una compañía! ¡Marchad hacia Canción del Bosque!' WHERE `ID`=33620;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='숲을 모조리 베어 없애라! 엘프들을 몰아내라!', `MaleText_loc4`='砍倒那片森林！把精灵赶出来！', `MaleText_loc5`='把樹全砍了!把精靈逼出來!', `MaleText_loc7`='¡Talad el bosque! ¡Echad a los elfos!' WHERE `ID`=33621;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무도 살려두지 마라!', `MaleText_loc4`='不留俘虏！', `MaleText_loc5`='格殺勿論', `MaleText_loc7`='¡No toméis prisioneros!' WHERE `ID`=33622;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일을 두 배로 하지 않으면 대족장님께서 네놈의 가죽을 벗겨버리실 것이다!', `MaleText_loc4`='如果产量不能加倍，酋长一定会把我们全都剥皮的！', `MaleText_loc5`='如果生產量沒到兩倍，大酋長會把我們所有人的皮都剝了!', `MaleText_loc7`='¡El Jefe de Guerra acabará con nosotros si no doblamos la producción!' WHERE `ID`=33623;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 너, 오늘 할당된 나무와 엘프 귀걸이를 다 채웠나?!', `MaleText_loc4`='嗨，你完成今天的木材和精灵徽记定额了吗？', `MaleText_loc5`='那邊那個，你已經收集完今天該有的木材和精靈耳朵嗎?!', `MaleText_loc7`='¡Tú! ¿Has alcanzado tu cupo de madera y orejas de elfo hoy?' WHERE `ID`=33624;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 잿빛 골짜기 공격대의 핵심 전력이다. 실패는 절대 용납할 수 없다!', `MaleText_loc4`='我们是灰谷防御力量的中坚。我们绝不能失败！', `MaleText_loc5`='我們是梣谷進攻部隊的支柱，字典裡不存在失敗這兩個字!', `MaleText_loc7`='Somos la columna vertebral de la ofensiva de Vallefresno. ¡El fracaso NO es una opción!' WHERE `ID`=33625;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그곳에서 빠져나와 저 얼라이언스 추종자들을 죽여라!', `MaleText_loc4`='出来消灭那些联盟！', `MaleText_loc5`='出去殺了那些聯盟狗!', `MaleText_loc7`='¡Sal de ahí y mata a esos perros de la Alianza!' WHERE `ID`=33626;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈들의 시시한 분쟁은 나를 강하게 할 뿐... 죽음의 신께 경배하라!', `MaleText_loc4`='你们微不足道的抵抗只能让我变得更加强大……向死亡之神屈膝投降吧！', `MaleText_loc5`='你們那些瑣碎的爭執只會讓我更加強大...向死亡之神拜伏!', `MaleText_loc7`='Sus pleitos insignificantes no hacen más que fortalecerme…' WHERE `ID`=33627;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이르 은라이어스... 슐 아나그!', `MaleText_loc4`='Yrr n''lyeth... shuul anagg！', `MaleText_loc5`='(古神語)他會學會...沒有君王能夠永遠統治;只有死亡才是永恆不變!', `MaleText_loc7`='Yrr n''lyeth... ¡Shuul anagg!' WHERE `ID`=33628;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그도 깨달을 것이다... 영원한 왕 따윈 없어! 오직 죽음만이 영원하다!', `MaleText_loc4`='他会明白……没有谁可以永远坐在王位上，只有死亡才是永恒的！', `MaleText_loc5`='他會學會...沒有君王能夠永遠統治;只有死亡才是永恆不變!', `MaleText_loc7`='Aprenderá... Ningún rey reina para siempre; ¡sólo la muerte es eterna!' WHERE `ID`=33629;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 충분하다, 오크 놈아! 코도에서 내려 복종하거나 아니면 죽어라!', `MaleText_loc4`='这远远不够，兽人！下马投降，否则就是死路一条！', `MaleText_loc5`='夠了，獸人!下來投降或接受死亡!', `MaleText_loc7`='¡Ya es bastante lejos, orco! ¡Desmonta y sométete, o muere!', `FemaleText_loc1`='이제 충분하다, 오크 놈아! 코도에서 내려 복종하거나 아니면 죽어라!', `FemaleText_loc4`='这远远不够，兽人！下马投降，否则就是死路一条！', `FemaleText_loc5`='夠了，獸人!下來投降或接受死亡!', `FemaleText_loc7`='¡Ya es bastante lejos, orco! ¡Desmonta y sométete, o muere!' WHERE `ID`=33630;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='비켜라, 멍청이들아!', `FemaleText_loc4`='别挡道，蠢货！', `FemaleText_loc5`='別檔我們的路，蠢貨們!', `FemaleText_loc7`='¡Fuera de nuestro camino, necios!' WHERE `ID`=33631;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런, 이런. 울두아르를 제 두 눈으로 보게 되리라고는 꿈에도 생각 못 했답니다. 그래서 브란이 제게 이 원정을 좀 지원해달라고 했을 때 도저히 거절할 수가 없었죠!', `MaleText_loc4`='天哪，我从来没有想过能亲眼目睹泰坦之城奥杜尔。当布莱恩恳求我资助这支探险队时，我怎么能忍心拒绝呢？！', `MaleText_loc5`='噢，我的天，我沒想過我有機會親眼看見奧杜亞。布萊恩要我資助這個遠征隊的時候，我怎麼會拒絕呢?!', `MaleText_loc7`='Vaya vaya, nunca pensé que tendría la oportunidad de ver a Ulduar con mis propios ojos. Bueno, cuando Brann me pidió ayuda para organizar esta expedición, ¡¿cómo iba a negarme?!' WHERE `ID`=33632;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 습기 찬 정글을 영영 못 빠져나올 줄만 알았는데! 전 이제 이 원정대의 수석 기술자랍니다.', `MaleText_loc4`='我还以为我们没法逃出那片雾蒙蒙的丛林呢！现在，我是这支探险队的首席工程师啦。', `MaleText_loc5`='我都沒想過我們居然能逃出那片蒸汽叢林!現在我可是這次遠征隊的首席工程師了。', `MaleText_loc7`='¡Pensé que no íbamos a escapar nunca de esa jungla de vapor! Ahora soy el ingeniero jefe de esta expedición.' WHERE `ID`=33633;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공성 전차로 어떤 기술을 쓸 수 있습니까?', `MaleText_loc4`='这些攻城器械有什么用处？', `MaleText_loc5`='這些攻城機具有什麼功能?', `MaleText_loc7`='¿Qué pueden hacer estas máquinas de asedio?', `FemaleText_loc1`='공성 전차로 어떤 기술을 쓸 수 있나요?', `FemaleText_loc4`='这些攻城器械有什么用处？', `FemaleText_loc5`='這些攻城機具有什麼功能?', `FemaleText_loc7`='¿Qué pueden hacer estas máquinas de asedio?' WHERE `ID`=33634;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 예쁜 것들이 폐물처럼 보일지는 몰라도, 녀석들은 정면으로 돌진해서 적을 옆으로 날려버릴 수 있답니다. 전면에 달린 충각에는 초고용량 검전기식 축전기를 장착해서, 전기 충격을 발사할 수 있고요.$B$B심지어 포탑도 개조해서 대공 로켓을 달았지요. 저 파괴전차 나부랭이보다 훨씬 훌륭한 기계라고요.', `MaleText_loc4`='这些宝贝儿看上去跟废铁似的，但是它们可以高速前进，猛烈地撞击敌人。器械前端的撞锤加载了可以施放电能震击的高压电容器。$B$B就连炮塔也升级成了防空火箭，使它比那些破烂攻城车更具优势。', `MaleText_loc5`='這些寶貝看起來雖然很像廢鐵，但他們可以猛衝敵人，把敵人給撞飛。前方的衝角裝載了超驗電電容器，讓它可以釋放電衝波。$B$B連砲塔都用對空火箭強化過，讓它們絕對比那些破爛的石毀車更厲害。', `MaleText_loc7`='Puede que estas preciosidades parezcan chatarra, pero pueden embestir a los enemigos. El espolón central ha sido sobrecargado con un híper condensador electroscópico que le permite propinar descargas eléctricas. $b$bIncluso la torreta ha sido mejorada con cohetes antiaéreos, algo que proporciona, definitivamente, una ventaja sobre esos malditos demoledores.', `FemaleText_loc1`='이 예쁜 것들이 폐물처럼 보일지는 몰라도, 녀석들은 정면으로 돌진해서 적을 옆으로 날려버릴 수 있답니다. 전면에 달린 충각에는 초고용량 검전기식 축전기를 장착해서, 전기 충격을 발사할 수 있고요.$B$B심지어 포탑도 개조해서 대공 로켓을 달았지요. 저 파괴전차 나부랭이보다 훨씬 훌륭한 기계라고요.', `FemaleText_loc4`='这些宝贝儿看上去跟废铁似的，但是它们可以高速前进，猛烈地撞击敌人。器械前端的撞锤加载了可以施放电能震击的高压电容器。$B$B就连炮塔也升级成了防空火箭，使它比那些破烂攻城车更具优势。', `FemaleText_loc5`='這些寶貝看起來雖然很像廢鐵，但他們可以猛衝敵人，把敵人給撞飛。前方的衝角裝載了超驗電電容器，讓它可以釋放電衝波。$B$B連砲塔都用對空火箭強化過，讓它們絕對比那些破爛的石毀車更厲害。', `FemaleText_loc7`='Puede que estas preciosidades parezcan chatarra, pero pueden embestir a los enemigos. El espolón central ha sido sobrecargado con un híper condensador electroscópico que le permite propinar descargas eléctricas. $b$bIncluso la torreta ha sido mejorada con cohetes antiaéreos, algo que proporciona, definitivamente, una ventaja sobre esos malditos demoledores.' WHERE `ID`=33635;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간이 없어, 친구들! 내가 최근에 만든 기막힌 발명품을 시험하게 도와 주겠지? 자, 마음 바꿀 생각은 말라고. XT-002를 그 꼬락서니로 만들었으니, 너흰 나한테 빚진 셈이란 걸 잊지 마!', `MaleText_loc4`='我们时间不多了，朋友们！来帮忙测试一下我所发明的最新型、最强大的机体吧。在你们改变主意之前，请允许我提醒一下，你们把XT-002搞得一团糟，应该算是欠我个人情吧。', `MaleText_loc5`='我們沒有太多時間，朋友們!你們要幫我測試我最新也是最偉大的創作。在你們改變心意之前，別忘了就是你們把XT-002搞得一團糟，你們欠我一次。', `MaleText_loc7`='¡No tenemos mucho tiempo, amigos! Ustedes me ayudarán a probar mi última creación, la mejor de todas. Antes de que cambien de parecer, recuerden que su casta me lo debe después del lío que hicieron con el XT-002.' WHERE `ID`=33636;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아웃랜드 전 지역에서 가장 위대한 전승의 보고를 내가 여기에 만들었소. 심지어 실버문의 웅장한 도서관들도 따라오지 못할 정도라오.$B$B자, 부디... 둘러보시오. 마음껏 열람하고 읽으시오. 모두 체계적으로 잘 분류되어 있다오.', `MaleText_loc4`='这里汇集了外域最丰富的藏书。即便是银月城的大图书馆也要相形见绌了。$B$B请……尽情享受阅读的乐趣吧。所有的书籍都已分门别类，整理得井井有条。', `MaleText_loc5`='我所在此累積的或許是整個外域最偉大的知識寶庫。就算是銀月城的大圖書館也會相形失色。$B$B請來...看一看，讀一讀，隨意瀏覽。你會發現每樣東西都井然有序，編碼清楚。', `MaleText_loc7`='He reunido aquí lo que probablemente sea el mayor repositorio de saber de Terrallende. Incluso las grandes bibliotecas de Ciudad de Lunargenta palidecen a su lado.$b$bPor favor... observa, lee, busca cuanto te apetezca. Verás que todo está organizado y claramente etiquetado.' WHERE `ID`=33637;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멋지군! 참으로 경이적인 결과야! 차체 내구도 98.9 퍼센트라! 손상이라고 보기도 어렵지! 계속하자고.', `MaleText_loc4`='太棒了！测试结果非常好！外壳完整率百分之九十八点九！几乎没有划伤！继续。', `MaleText_loc5`='太好了!絕妙的良好結果!外殼完整度98.9%!幾乎只有一點擦痕!繼續下去。', `MaleText_loc7`='¡QUÉ MARAVILLA! ¡Qué resultados positivamente maravillosos! ¡Integridad del casco en 98.9 por ciento! ¡Apenas una abolladura! Seguimos adelante.' WHERE `ID`=33638;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='봐라! VX-001 대인 공격포의 아름다운 자태를! 아마 숨고 싶어질걸!', `MaleText_loc4`='看呀，VX-001反步兵突击炮，你们也许应该找掩护。', `MaleText_loc5`='小心了!VX-001殺傷性攻擊火砲!你們或許需要躲起來。', `MaleText_loc7`='¡Contemplen el Cañón de asalto anti-personal VX-001! Les recomiendo que se pongan a cubierto.' WHERE `ID`=33639;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그녀를 없애라!', `MaleText_loc4`='杀死她！', `MaleText_loc5`='殺死她!', `MaleText_loc7`='¡Mátala!', `FemaleText_loc1`='그녀를 없애라!', `FemaleText_loc4`='杀死她！', `FemaleText_loc5`='殺死她!', `FemaleText_loc7`='¡Mátala!' WHERE `ID`=33640;
