UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시킬 일이 있으신가요, 대장님?', `MaleText_loc4`='老大，我能为你做什么吗？', `MaleText_loc5`='有何貴幹，老大?', `MaleText_loc7`='¿Puedo hacer algo por ti, jefe?' WHERE `ID`=33680;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은창 용사의 깃발', `MaleText_loc4`='暗矛冠军的旗帜', `MaleText_loc5`='暗矛勇士錦旗', `MaleText_loc7`='Grímpola de Campeón Lanza Negra', `FemaleText_loc1`='검은창 용사의 깃발', `FemaleText_loc4`='暗矛冠军的旗帜', `FemaleText_loc5`='暗矛勇士錦旗', `FemaleText_loc7`='Grímpola de Campeón Lanza Negra' WHERE `ID`=33681;
