UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오그리마 용사의 깃발', `MaleText_loc4`='奥格瑞玛冠军的旗帜', `MaleText_loc5`='奧格瑪勇士錦旗', `MaleText_loc7`='Grímpola de Campeón de Orgrimmar', `FemaleText_loc1`='오그리마 용사의 깃발', `FemaleText_loc4`='奥格瑞玛冠军的旗帜', `FemaleText_loc5`='奧格瑪勇士錦旗', `FemaleText_loc7`='Grímpola de Campeón de Orgrimmar' WHERE `ID`=33683;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아요! 움직입시다. 차량에 올라타세요. 이제부터 무전기로 말씀드리죠.', `MaleText_loc4`='好了！我们出发吧。钻进你的战车里，我会通过无线电跟你保持联络！', `MaleText_loc5`='好啦!出發吧。爬進你的機器裡，等下我會透過無線電跟你們聯絡!', `MaleText_loc7`='¡Bien! A moverse. Entren en sus máquinas. ¡Yo les hablaré por radio desde aquí!' WHERE `ID`=33684;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실버문 용사의 깃발', `MaleText_loc4`='银月城冠军的旗帜', `MaleText_loc5`='銀月城勇士錦旗', `MaleText_loc7`='Grímpola de Campeón de Lunargenta', `FemaleText_loc1`='실버문 용사의 깃발', `FemaleText_loc4`='银月城冠军的旗帜', `FemaleText_loc5`='銀月城勇士錦旗', `FemaleText_loc7`='Grímpola de Campeón de Lunargenta' WHERE `ID`=33685;
