UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 동료는 준비를 마쳤습니다. 보호막을 걷고 길을 만드세요!', `MaleText_loc4`='我们的盟友已经准备好了。解除护盾，前进！', `MaleText_loc5`='我們的盟友準備好了。降下護盾並且讓出路來!', `MaleText_loc7`='Nuestros aliados están preparados. ¡Desactiven el escudo y abran paso!' WHERE `ID`=33687;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시험을 너무 오래 끌었군요. 당신은 용맹전사가 되기엔 아직 부족합니다.', `MaleText_loc4`='你用的时间实在是太久了。你还没有做好成为勇士的准备。', `MaleText_loc5`='這場考驗持續太久了。你還沒準備好成為一名驍士。', `MaleText_loc7`='Esta prueba ha durado demasiado. No estás $glisto:lista; para ser $gun:una; $gValeroso:Valerosa;.', `FemaleText_loc1`='시험을 너무 오래 끌었군요. 당신은 용맹전사가 되기엔 아직 부족합니다.', `FemaleText_loc4`='你用的时间实在是太久了。你还没有做好成为勇士的准备。', `FemaleText_loc5`='這場考驗持續太久了。你還沒準備好成為一名驍士。', `FemaleText_loc7`='Esta prueba ha durado demasiado. No estás $glisto:lista; para ser $gun:una; $gValeroso:Valerosa;.' WHERE `ID`=33688;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전장에 나가기엔 너무 느리군요. 기술을 좀 더 다듬으셔야 할 것 같습니다.', `MaleText_loc4`='你在对战中的反应太慢了。需要继续磨练自己的技巧。', `MaleText_loc5`='你在這場戰鬥中嚴重落後。或許你需要更進一步磨練你的技巧。', `MaleText_loc7`='Eres demasiado lent$go:a; en el campo de batalla. Quizás debas perfeccionar un poco más tus habilidades.', `FemaleText_loc1`='전장에 나가기엔 너무 느리군요. 기술을 좀 더 다듬으셔야 할 것 같습니다.', `FemaleText_loc4`='你在对战中的反应太慢了。需要继续磨练自己的技巧。', `FemaleText_loc5`='你在這場戰鬥中嚴重落後。或許你需要更進一步磨練你的技巧。', `FemaleText_loc7`='Eres demasiado lent$go:a; en el campo de batalla. Quizás debas perfeccionar un poco más tus habilidades.' WHERE `ID`=33689;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘하셨습니다! 용맹전사에 어울리는 실력을 갖추신 것 같군요!', `MaleText_loc4`='干得好！看来你完全有资格成为一名勇士！', `MaleText_loc5`='幹得好!看來你足以晉升到驍士的位階!', `MaleText_loc7`='¡Bien hecho! Parece que te mereces subir de rango y unirte al resto de Campeones.', `FemaleText_loc1`='잘하셨습니다! 용맹전사에 어울리는 실력을 갖추신 것 같군요!', `FemaleText_loc4`='干得好！看来你完全有资格成为一名勇士！', `FemaleText_loc5`='幹得好!看來你足以晉升到驍士的位階!', `FemaleText_loc7`='¡Bien hecho! Parece que te mereces subir de rango y unirte al resto de Campeones.' WHERE `ID`=33690;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='참으로 인상적인 기술이었습니다. 용맹전사가 되기에 전혀 모자람이 없어 보이는군요.', `MaleText_loc4`='你的战斗技巧令人印象深刻。我相信以你的潜力，远不止成为一名勇士那么简单。', `MaleText_loc5`='令人印象深刻的技巧。我相信你已經足以成為驍士的一員。', `MaleText_loc7`='Impresionantes habilidades, sin duda. Creo que ya estás en condiciones de ascender de rango y unirte al resto de Valerosos.', `FemaleText_loc1`='참으로 인상적인 기술이었습니다. 용맹전사가 되기에 전혀 모자람이 없어 보이는군요.', `FemaleText_loc4`='你的战斗技巧令人印象深刻。我相信以你的潜力，远不止成为一名勇士那么简单。', `FemaleText_loc5`='令人印象深刻的技巧。我相信你已經足以成為驍士的一員。', `FemaleText_loc7`='Impresionantes habilidades, sin duda. Creo que ya estás en condiciones de ascender de rango y unirte al resto de Valerosos.' WHERE `ID`=33691;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까.', `MaleText_loc4`='欢迎。', `MaleText_loc5`='你好。', `MaleText_loc7`='Saludos.' WHERE `ID`=33692;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론 군대에는 식량이 필요하죠. 하지만, 이 상황은 진짜 말도 안 돼요.', `MaleText_loc4`='我知道军队需要食物，但是这也太荒唐了。', `MaleText_loc5`='我知道部隊需要食物，但這太荒謬了。', `MaleText_loc7`='Sé que las tropas necesitan comida, pero esto es ridículo.' WHERE `ID`=33693;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 그냥 원기 회복의 식탁을 차리면 안되는 건지 아직도 이해가 안 돼요.', `MaleText_loc4`='我还是想不通，为什么不直接召唤餐桌呢。', `MaleText_loc5`='我還是不知道為什麼我們不能就召喚一個餐點桌。', `MaleText_loc7`='Sigo sin saber por qué no puedo invocar una mesa de refrigerio.' WHERE `ID`=33694;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세상에 비전 마력이 넘치고, 제가 여기 있잖아요. 음료랑 음식은 얼마든지 소환할 수 있다고요.', `MaleText_loc4`='我拥有无与伦比的奥术力量，却待在这里不停地召唤食物和水。', `MaleText_loc5`='我操控著全世界的秘法力量，但卻得在這裡召喚更多的食物和水。', `MaleText_loc7`='Todo el poder Arcano del mundo y heme aquí invocando más comida y agua.' WHERE `ID`=33695;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런데 종업원 신세라니.', `MaleText_loc4`='我变成餐厅的女招待了。', `MaleText_loc5`='我是個女侍。', `MaleText_loc7`='Soy una camarera.' WHERE `ID`=33696;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용맹전사가 될 준비를 마쳤다고 생각하십니까? 어디 한번 보지요.', `MaleText_loc4`='你确信自己已经做好成为勇士的准备了吗？我们会拭目以待的。', `MaleText_loc5`='你認為你準備好晉升驍士了?讓我們來瞧瞧。', `MaleText_loc7`='¿Crees que estás $gpreparado:preparada; para el rango de $gValeroso:Valerosa;? Ya veremos.', `FemaleText_loc1`='용맹전사가 될 준비를 마쳤다고 생각하십니까? 어디 한번 보지요.', `FemaleText_loc4`='你确信自己已经做好成为勇士的准备了吗？我们会拭目以待的。', `FemaleText_loc5`='你認為你準備好晉升驍士了?讓我們來瞧瞧。', `FemaleText_loc7`='¿Crees que estás $gpreparado:preparada; para el rango de $gValeroso:Valerosa;? Ya veremos.' WHERE `ID`=33698;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용맹전사의 자격은 쉽게 얻을 수 없습니다. 준비하세요!', `MaleText_loc4`='别以为你轻而易举就能取得勇士的头衔。做好准备吧！', `MaleText_loc5`='驍士的位階可不是個輕而易舉的目標。做好準備!', `MaleText_loc7`='El rango de $gValeroso:Valerosa; no se obtiene fácilmente. ¡Prepárate!', `FemaleText_loc1`='용맹전사의 자격은 쉽게 얻을 수 없습니다. 준비하세요!', `FemaleText_loc4`='别以为你轻而易举就能取得勇士的头衔。做好准备吧！', `FemaleText_loc5`='驍士的位階可不是個輕而易舉的目標。做好準備!', `FemaleText_loc7`='El rango de $gValeroso:Valerosa; no se obtiene fácilmente. ¡Prepárate!' WHERE `ID`=33699;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용맹전사가 되기엔 준비가 덜 된 것 같습니다. 조금 더 훈련하시는 게 좋을 듯합니다.', `MaleText_loc4`='你暂时还不能取得勇士的头衔。你可能需要更多的训练。', `MaleText_loc5`='看來你還不足以挑戰驍士的位階。你大概還需要多一些訓練。', `MaleText_loc7`='Parece que no estás en condiciones de subir de rango y unirte al resto de campeones. Puede que te venga bien entrenar un poco más.', `FemaleText_loc1`='용맹전사가 되기엔 준비가 덜 된 것 같습니다. 조금 더 훈련하시는 게 좋을 듯합니다.', `FemaleText_loc4`='你暂时还不能取得勇士的头衔。你可能需要更多的训练。', `FemaleText_loc5`='看來你還不足以挑戰驍士的位階。你大概還需要多一些訓練。', `FemaleText_loc7`='Parece que no estás en condiciones de subir de rango y unirte al resto de campeones. Puede que te venga bien entrenar un poco más.' WHERE `ID`=33700;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용맹전사가 되기에는 조금 부족해 보이는군요. 하지만 곧 충분한 실력을 갖추실 것 같습니다.', `MaleText_loc4`='恐怕你暂时还不能取得勇士的头衔。但是我相信你很快就会做好充分准备的。', `MaleText_loc5`='恐怕你還不足以成為一位驍士。但我相信你只差一步了。', `MaleText_loc7`='Me temo que no estás a punto para el rango de Valeroso. Sin embargo creo que pronto lo estarás.', `FemaleText_loc1`='용맹전사가 되기에는 조금 부족해 보이는군요. 하지만 곧 충분한 실력을 갖추실 것 같습니다.', `FemaleText_loc4`='恐怕你暂时还不能取得勇士的头衔。但是我相信你很快就会做好充分准备的。', `FemaleText_loc5`='恐怕你還不足以成為一位驍士。但我相信你只差一步了。', `FemaleText_loc7`='Me temo que no estás a punto para el rango de Valeroso. Sin embargo creo que pronto lo estarás.' WHERE `ID`=33701;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='울다만 지식의 파수꾼에 대해 들은 얘기가 있는데, 어째 당신과 대단히 비슷하군요. 혹시 같은 역할을 하시나요?', `FemaleText_loc4`='我听说过一两个关于奥达曼看门人的故事，和你的描述很像。你是否也有类似的用途呢？', `FemaleText_loc5`='我聽說過一兩個關於奧達曼博識者的故事，可能符合你的描述。你是為了類似的理由而來嗎?', `FemaleText_loc7`='He escuchado alguna historia sobre un tradicionalista en Uldaman que se ajusta a tu descripción. ¿Cumples un cometido similar?' WHERE `ID`=33702;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 이 단지와 관련된 필수적인 정보를 담는, 일종의 저장고 역할을 하도록 만들어졌습니다. 제 주요 기능에는 전방 방어 시스템의 상태 전달과, 이 단지에 수용해 두어야 하는 존재의 상태 평가가 포함되어 있습니다.', `MaleText_loc4`='我的用途就是存储这座泰坦之城的重要信息。我的主要功能包括传达前沿防御系统的状况以及评估关押在这座庞大建筑物中的实体的状态。', `MaleText_loc5`='我是製造來保存並管理封存於複合體中事物的關鍵資訊。我的首要功能是聯繫正面防禦系統的狀態，並且評估複合體所囚禁實體的狀態。', `MaleText_loc7`='Me construyeron para cumplir el rol de repositorio de información esencial sobre este complejo. Mis funciones principales incluyen la comunicación del estado de los sistemas frontales de defensa y la evaluación del estado de la entidad para cuyo cautiverio se construyó este complejo.' WHERE `ID`=33703;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전방 방어 시스템이요? 브란이 누군가를 단지 내부에 들여보내기 전에 알려줘야 할 게 있나요?', `FemaleText_loc4`='前沿防御系统？在布莱恩派人进入这座城市之前，我需要提醒他什么吗？', `FemaleText_loc5`='正面防禦系統?感覺上我好像應該在布萊恩嘗試進入複合體之前先告訴他?', `FemaleText_loc7`='¿Sistemas frontales de defensa? ¿Hay algo que debiera notificar a Brann antes de que ordene a alguien intentar entrar en el complejo?' WHERE `ID`=33704;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='단지 내부 접근은 현재 제한되어 있습니다. 주 방어 설비들이 작동 중입니다. 보조 시스템은 현재 비활성화되어 있습니다.', `MaleText_loc4`='目前，一切企图进入泰坦之城的行动都将遭到制约。主防御系统处于激活状态。次防御系统处于未激活状态。', `MaleText_loc5`='目前禁止進入複合體內部。主要防禦裝置已啟動。次要系統目前未啟動。', `MaleText_loc7`='En estos momentos el acceso al interior del complejo está restringido. Los mecanismos de defensa primarios están activos. Los mecanismos secundarios están inactivos.' WHERE `ID`=33705;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='방어 시스템이 어떤 식으로 작동하는지 자세하게 이야기해 주시겠어요?', `FemaleText_loc4`='你能详细描述一下防御系统的性能吗？', `FemaleText_loc5`='你可以說明一下防禦系統的細節嗎?', `FemaleText_loc7`='¿Puedes detallar la naturaleza de estos sistemas de defensa?' WHERE `ID`=33706;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='단지가 위험에 처해 있음이 감지되었습니다. 보안 재정의가 활성화되었습니다. 질의가 허가되었습니다.', `MaleText_loc4`='检测到威胁，已启动安全控制 － 允许查询。', `MaleText_loc5`='偵測到複合體已暴露，安全限制開啟 - 允許查詢。', `MaleText_loc7`='Detectado peligro para el complejo, activado control manual de seguridad. Petición permitida.' WHERE `ID`=33707;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='알았어요. 최소한 그 궤도적 방어 설비는 상대하지 않아도 되겠군요.', `FemaleText_loc4`='明白了。至少我们不用考虑那些轨道炮台。', `FemaleText_loc5`='瞭解。起碼我們不必應付那些環軌砲座。', `FemaleText_loc7`='Comprendo. Al menos no tenemos que encargarnos de esos mecanismos orbitales.' WHERE `ID`=33708;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='리디안, 펜타루스 대마법사님과 브란에게 이 방어 설비에 대해 당장 알리세요.', `FemaleText_loc4`='琳蒂安，请立即转告布莱恩和大法师伯塔鲁斯关于防御系统的事儿。', `FemaleText_loc5`='萊迪安，立刻讓布萊恩和大法師潘塔魯斯知道那些防禦裝置。', `FemaleText_loc7`='Rhydian, asegúrate de que Brann y el archimago Pentarus saben de esas defensas inmediatamente.' WHERE `ID`=33709;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 그리고 단지에 수용해야 하는 존재라고 하셨죠? 이 존재가 무엇이고, 현재 상태는 어떤가요?', `FemaleText_loc4`='被囚禁的实体？是什么实体？目前它处于什么样的状态？', `FemaleText_loc5`='你提到一個被囚禁的實體?這個東西的本質是什麼?它的狀態又如何?', `FemaleText_loc7`='¿Y mencionaste una entidad aprisionada? ¿Cuál es la naturaleza de esta entidad y cuál es su estatus?' WHERE `ID`=33710;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='존재 지시어. 요그사론. 보안 환경이 손상되었습니다. 감옥 관리 상황, 알 수 없음. 알림을 목적으로 감시자와 연락할 수 없습니다.', `MaleText_loc4`='个体标识：尤格-萨隆。安全受到威胁。囚犯的行动状态未知。无法联络或通知到守护者。', `MaleText_loc5`='實體稱謂:尤格薩倫。安全系統已暴露。囚犯狀態不明。無法聯繫看守者進行通知。', `MaleText_loc7`='Entidad designada: Yogg-Saron. Seguridad comprometida. Estado operativo de la prisión desconocido. Imposible contactar Vigías para notificación.' WHERE `ID`=33711;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주 방어 설비는 무쇠 피조물과, 필요에 따라 추가 무쇠 피조물을 생성하는 폭풍 봉화로 구성되어 있습니다. 보조 시스템은 궤도적 방어 설비로 구성되어 있습니다.', `MaleText_loc4`='主防御系统包括铁铸像和风暴信标，后者将不断地催生更多的构造体。辅助防御系统包括轨道防御炮台。', `MaleText_loc5`='主要防禦裝置包括了鐵之傀儡和風暴信號塔，它會視需要產生出額外的傀儡。次要系統則包含了環軌防禦裝置。', `MaleText_loc7`='Los mecanismos de defensa primarios consisten en ensamblajes férreos y balizas de tormenta que generarán ensamblajes adicionales de ser necesario. Los sistemas secundarios consisten en mecanismos de defensa orbital.' WHERE `ID`=33712;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='요그사론이 여기 있다고요? 우리 정말 바빠질 것 같네요.', `FemaleText_loc4`='尤格-萨隆被关押在这里？看来我们有得忙了。', `FemaleText_loc5`='尤格薩倫在這裡?看來我們真是麻煩大了。', `FemaleText_loc7`='¿Yogg-Saron está aquí? Entonces parece que vamos a estar ocupados.' WHERE `ID`=33713;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='곧 전투가 시작될 것 같군요. 이제 떠날 때가 된 것 같습니다. 나중에 여기 다시 들러야겠어요.', `FemaleText_loc4`='战斗即将开始，我该离开了。另找时间继续我们的谈话吧。', `FemaleText_loc5`='看來差不多要開始戰鬥了，我得先閃了。我們晚點再來拿這個。', `FemaleText_loc7`='Parece que se avecina la batalla, lo cual me dice que es hora de que marche. Tendremos que recoger esto después.' WHERE `ID`=33714;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 고개를 끄덕입니다.', `FemaleText_loc4`='%s点了点头。', `FemaleText_loc5`='%s點點頭。', `FemaleText_loc7`='%s asiente.' WHERE `ID`=33715;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 브란에게 귓속말을 합니다.', `FemaleText_loc4`='%s低声对布莱恩说着什么。', `FemaleText_loc5`='%s對布萊恩低聲了些什麼。', `FemaleText_loc7`='%s susurra algo a Brann.' WHERE `ID`=33716;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은빛 서약단에서는 이번 마상시합에 참여하는 당신을 환영하는 바입니다. 은빛십자군에서는 우리 서약단에서 이번 시합에 흥미가 있는 자들의 신청을 받고 훈련을 맡아 달라고 요청했답니다.', `MaleText_loc4`='银色盟约欢迎你参加锦标赛。银色北伐军委托我们登记并训练那些对比赛感兴趣的选手。', `MaleText_loc5`='白銀誓盟歡迎你加入聯賽。銀白十字軍請我們協助那些對參賽有興趣的人進行登記與訓練。', `MaleText_loc7`='El Pacto de Plata te da la bienvenida al torneo. La Cruzada Argenta nos ha pedido que inscribamos y entrenemos a aquellos que estén interesados en competir.' WHERE `ID`=33717;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번엔 실수해선 안 돼요! 이 공성 차량들이 전장에서 망가지는 꼴은 더는 보기 싫다고요.', `MaleText_loc4`='这次不能再出错了！我可不希望这些攻城器械在战场上抛锚。', `MaleText_loc5`='這次不容錯誤!我可不希望這些攻城機具壞在戰場上。', `MaleText_loc7`='¡Esta vez no nos podemos permitir ni un error! No quiero que ninguna de esas máquinas de asedio se averíe en el camino.' WHERE `ID`=33718;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 눈앞에서 차량이 더는 폭발하지 않게 해 주세요. 이것들을 만드는 데 돈이 얼마나 많이 들었는지 아세요?', `MaleText_loc4`='但愿这是最后一辆毁在我们手里的器械。他们可是为这些东西花了大价钱的。', `MaleText_loc5`='這最好是我眼中最後一次爆炸。他們得付出高額賠償。', `MaleText_loc7`='Mejor que sea la última que revienta en nuestro turno. Pagan una fortuna por estas cosas.' WHERE `ID`=33719;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐가 좋은 기계인지 알아보는시는군요. 놈들을 황천으로 보내버리세요!', `MaleText_loc4`='看来你在操纵器械方面很有天分。给他们点颜色瞧瞧！', `MaleText_loc5`='看來你碰上一台好機械的時候還是懂得利用嘛。給他們好看!', `MaleText_loc7`='Parece que sabes reconocer una buena máquina cuando la ves. ¡Dales duro!', `FemaleText_loc1`='뭐가 좋은 기계인지 알아보는시는군요. 놈들을 황천으로 보내버리세요!', `FemaleText_loc4`='看来你在操纵器械方面很有天分。给他们点颜色瞧瞧！', `FemaleText_loc5`='看來你碰上一台好機械的時候還是懂得利用嘛。給他們好看!', `FemaleText_loc7`='Parece que sabes reconocer una buena máquina cuando la ves. ¡Dales duro!' WHERE `ID`=33720;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 친구들이 황철석을 쏘아서 떨어뜨리거든, 잊지 말고 꼭 주우세요.', `MaleText_loc4`='如果你的朋友们能击落它，别忘记多弄点蓝铁。', `MaleText_loc5`='如果你的朋友有辦法把它射倒的話，記得多拿點黃鐵。', `MaleText_loc7`='No olvides recoger algo de pirita extra si tus amigos pueden derribarlo.', `FemaleText_loc1`='당신 친구들이 황철석을 쏘아서 떨어뜨리거든, 잊지 말고 꼭 주우세요.', `FemaleText_loc4`='如果你的朋友们能击落它，别忘记多弄点蓝铁。', `FemaleText_loc5`='如果你的朋友有辦法把它射倒的話，記得多拿點黃鐵。', `FemaleText_loc7`='No olvides recoger algo de pirita extra si tus amigos pueden derribarlo.' WHERE `ID`=33721;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저도 당신과 같이 갈 수만 있다면 얼마나 좋을까요... 깨끗이 날려버리세요!', `MaleText_loc4`='我真想跟你一起去呢。炸翻天！', `MaleText_loc5`='真希望我能跟你們一起去。把它們給炸翻!', `MaleText_loc7`='Me gustaría poder ir con ustedes ¡Denles duro!', `FemaleText_loc1`='저도 당신과 같이 갈 수만 있다면 얼마나 좋을까요... 깨끗이 날려버리세요!', `FemaleText_loc4`='我真想跟你一起去呢。炸翻天！', `FemaleText_loc5`='真希望我能跟你們一起去。把它們給炸翻!', `FemaleText_loc7`='Me gustaría poder ir con ustedes ¡Denles duro!' WHERE `ID`=33722;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 폭발을 좋아했으면 좋겠네요. 그게 제 전문이라고요.', `MaleText_loc4`='希望你喜欢炸药。这可是我的专长。', `MaleText_loc5`='希望你喜歡這些炸彈。它們可是我特製的。', `MaleText_loc7`='Espero que te gusten las explosiones. Son mi especialidad.', `FemaleText_loc1`='당신이 폭발을 좋아했으면 좋겠네요. 그게 제 전문이라고요.', `FemaleText_loc4`='希望你喜欢炸药。这可是我的专长。', `FemaleText_loc5`='希望你喜歡這些炸彈。它們可是我特製的。', `FemaleText_loc7`='Espero que te gusten las explosiones. Son mi especialidad.' WHERE `ID`=33723;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 새끼들을 험하게 다루진 않으시겠지요? 일 끝내고 기계를 돌려주실 때 흠집이라도 있으면 두고 봅시다.', `MaleText_loc4`='你会好好照顾我的宝贝儿的，对吧？战斗结束后，我可不希望在她身上看到哪怕是一块凹痕。', `MaleText_loc5`='好好對待我的寶貝，好嗎?我可不希望你在她身上留下任何凹痕。', `MaleText_loc7`='Cuidas bien a mi nena, ¿vale? No quiero ver ninguna abolladura cuando hayas terminado.', `FemaleText_loc1`='이 멋진 기계를 험하게 다루시진 않겠죠? 일 끝내고 기계를 돌려주실 때 흠집이라도 있으면 두고 보자고요.', `FemaleText_loc4`='你会好好照顾我的宝贝儿的，对吧？战斗结束后，我可不希望在她身上看到哪怕是一块凹痕。', `FemaleText_loc5`='好好對待我的寶貝，好嗎?我可不希望你在她身上留下任何凹痕。', `FemaleText_loc7`='Cuidas bien a mi nena, ¿vale? No quiero ver ninguna abolladura cuando hayas terminado.' WHERE `ID`=33724;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탑승자를 발사하는 기술도 있답니다! 친구들이 당신을 아주 예뻐해 줄걸요.', `MaleText_loc4`='试试新增的乘客抛掷功能吧！你们一定会喜欢的！', `MaleText_loc5`='現在還有全新的乘客投擲功能!我肯定你會愛上它的。', `MaleText_loc7`='¡Ahora con la facultad nueva de arrojar pasajeros! Estoy convencido de que a tus amigos les va a encantar.', `FemaleText_loc1`='탑승자를 발사하는 기술도 있답니다! 친구들이 당신을 아주 예뻐해 줄걸요.', `FemaleText_loc4`='试试新增的乘客抛掷功能吧！你们一定会喜欢的！', `FemaleText_loc5`='現在還有全新的乘客投擲功能!我肯定你會愛上它的。', `FemaleText_loc7`='¡Ahora con la facultad nueva de arrojar pasajeros! Estoy convencida de que a tus amigos les va a encantar.' WHERE `ID`=33725;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황철석 보유량엔 한계가 있습니다. 절약해서 쓰셔야 해요.', `MaleText_loc4`='蓝铁的储备有限，省着点用。', `MaleText_loc5`='我們只有很少的黃鐵存量，省著點用。', `MaleText_loc7`='Solo tenemos almacenada una cantidad de pirita limitada, úsala con cautela.', `FemaleText_loc1`='황철석 보유량엔 한계가 있습니다. 절약해서 쓰셔야 해요.', `FemaleText_loc4`='蓝铁的储备有限，省着点用。', `FemaleText_loc5`='我們只有很少的黃鐵存量，省著點用。', `FemaleText_loc7`='Solo tenemos almacenada una cantidad de pirita limitada, úsala con cautela.' WHERE `ID`=33726;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 이제 당신 차지입니다. 잘 다뤄 주세요!', `MaleText_loc4`='交给你啦。好好利用它吧！', `MaleText_loc5`='交給你啦。好好使用她!', `MaleText_loc7`='Toda tuya. ¡Úsala bien!', `FemaleText_loc1`='자, 이제 당신 차지예요. 잘 다뤄 주세요!', `FemaleText_loc4`='交给你啦。好好利用它吧！', `FemaleText_loc5`='交給你啦。好好使用她!', `FemaleText_loc7`='Toda tuya. ¡Úsala bien!' WHERE `ID`=33727;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거면 저 탑 따위 눈 깜짝할 사이에 부숴 버릴 수 있을 겁니다!', `MaleText_loc4`='这些家伙可以在一瞬间就把塔楼给砸平了！', `MaleText_loc5`='這些機具一定能很快地掃平那些高塔!', `MaleText_loc7`='¡Estas cosas debieran derribar esas torres en un instante!', `FemaleText_loc1`='이거면 저 탑 따위 눈 깜짝할 사이에 부숴 버릴 수 있을 거예요!', `FemaleText_loc4`='这些家伙可以在一瞬间就把塔楼给砸平了！', `FemaleText_loc5`='這些機具一定能很快地掃平那些高塔!', `FemaleText_loc7`='¡Estas cosas debieran derribar esas torres en un instante!' WHERE `ID`=33728;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저흰 여기에 더 두꺼운 장갑을 씌웠습니다. 이젠 좀 얻어맞아도 상관없을 거예요!', `MaleText_loc4`='我们给它们换上了更先进的装甲钢板——现在它们的抗打击能力已经很强了！', `MaleText_loc5`='我們用一些高級護甲板強化過了 - 它們現在應該能承受好些攻擊!', `MaleText_loc7`='Las hemos mejorado con algo de blindaje avanzado. ¡Ahora deberían aguantar lo suyo!', `FemaleText_loc1`='저흰 여기에 더 두꺼운 장갑을 씌웠어요. 이젠 좀 얻어맞아도 상관없을 거예요!', `FemaleText_loc4`='我们给它们换上了更先进的装甲钢板——现在它们的抗打击能力已经很强了！', `FemaleText_loc5`='我們用一些高級護甲板強化過了 - 它們現在應該能承受好些攻擊!', `FemaleText_loc7`='Las hemos mejorado con algo de blindaje avanzado. ¡Ahora deberían aguantar lo suyo!' WHERE `ID`=33729;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='출격!', `MaleText_loc4`='炸翻他们！', `MaleText_loc5`='給它們好看!', `MaleText_loc7`='¡Ponedlas en marcha!', `FemaleText_loc1`='출격!', `FemaleText_loc4`='炸翻他们！', `FemaleText_loc5`='給它們好看!', `FemaleText_loc7`='¡Ponedlas en marcha!' WHERE `ID`=33730;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대공 로켓으로 공중 수송선을 떨어뜨리면 황철석을 추가로 얻으실 수 있을 겁니다.', `MaleText_loc4`='防空火箭可以击落那些空中运输器，这样我们就能获得更多蓝铁了。', `MaleText_loc5`='防空火箭應該能有效地打下它們的空中運輸船，取得額外的黃鐵。', `MaleText_loc7`='Los cohetes antiaéreos debieran ser perfectos para derribar esos transportes aéreos y conseguir así algo de pirita extra.', `FemaleText_loc1`='대공 로켓으로 공중 수송선을 떨어뜨리면 황철석을 추가로 얻으실 수 있을 거예요.', `FemaleText_loc4`='防空火箭可以击落那些空中运输器，这样我们就能获得更多蓝铁了。', `FemaleText_loc5`='防空火箭應該能有效地打下它們的空中運輸船，取得額外的黃鐵。', `FemaleText_loc7`='Los cohetes antiaéreos debieran ser perfectos para derribar esos transportes aéreos y conseguir así algo de pirita extra.' WHERE `ID`=33731;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 이 녀석한테 베티라는 이름을 붙였답니다. 정말 예쁘죠?', `MaleText_loc4`='我管她叫贝蒂。她很漂亮吧？', `MaleText_loc5`='我叫她貝蒂。她很美，對吧?', `MaleText_loc7`='La llamo Betty. Es una belleza, ¿eh?', `FemaleText_loc1`='전 이 녀석한테 베티라는 이름을 붙였답니다. 정말 예쁘죠?', `FemaleText_loc4`='我管她叫贝蒂。她很漂亮吧？', `FemaleText_loc5`='我叫她貝蒂。她很美，對吧?', `FemaleText_loc7`='La llamo Betty. Es una belleza, ¿eh?' WHERE `ID`=33732;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='농담이 아니에요. 이걸 보면 고블린 녀석들이 질투에 불타오를 걸요. 이건 작품이라고요, 작품.', `MaleText_loc4`='相信我，它会让那些地精嫉妒死的。这简直是一件艺术品啊。', `MaleText_loc5`='相信我，這些東西一定會讓那些哥布林也會嫉妒。這是件藝術品。', `MaleText_loc7`='Créeme, esta cosa va a poner celosos a los goblins. Es una obra de arte.', `FemaleText_loc1`='농담이 아니에요. 이걸 보면 고블린 녀석들이 질투에 불타오를 걸요. 이건 작품이라고요, 작품.', `FemaleText_loc4`='相信我，它会让那些地精嫉妒死的。这简直是一件艺术品啊。', `FemaleText_loc5`='相信我，這些東西一定會讓那些哥布林也會嫉妒。這是件藝術品。', `FemaleText_loc7`='Créeme, esta cosa va a poner celosos a los goblins. Es una obra de arte.' WHERE `ID`=33733;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='브란의 기대치를 훌쩍 뛰어넘는 기계라고요. 후회하지 않으실 겁니다.', `MaleText_loc4`='它的质量远远超过了布莱恩的要求，肯定不会让你失望的。', `MaleText_loc5`='這可是遠遠超過布萊恩的計畫。你絕對不會失望的。', `MaleText_loc7`='Supera con creces las peticiones de Brann. No te decepcionará.', `FemaleText_loc1`='브란의 기대치를 훌쩍 뛰어넘는 기계라고요. 후회하지 않으실 거예요.', `FemaleText_loc4`='它的质量远远超过了布莱恩的要求，肯定不会让你失望的。', `FemaleText_loc5`='這可是遠遠超過布萊恩的計畫。你絕對不會失望的。', `FemaleText_loc7`='Supera con creces las peticiones de Brann. No te decepcionará.' WHERE `ID`=33734;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거면 무쇠 군대를 밟아줄 수 있을 겁니다. 더 좋은 건, 당신 눈앞에서 기계가 폭발하는 일은 없을 거란 거죠... 제가 그런 기계를 좀 봤거든요. 누가 만든 기계인지 따위는 알려드릴 수 없어요.', `MaleText_loc4`='这家伙能摧毁整支钢铁部队。而且它还不会突然爆炸……比我以前见过的某些机器上等多了。具体是什么机器，我就不提了。', `MaleText_loc5`='這東西應該能削弱那些鐵矮人軍隊。更棒的是，它不會在你面前炸開...不像是我碰過的某些東西。我可不是在批評什麼東西唷。', `MaleText_loc7`='Esta cosa debiera destrozar ese ejército férreo. Mejor todavía, no te explotará en la cara... como otras máquinas que he visto. No me refiero a nadie.', `FemaleText_loc1`='이거면 무쇠 군대를 밟아줄 수 있을 걸요. 더 좋은 건, 당신 눈앞에서 기계가 폭발하는 일은 없을 거란 거죠... 제가 그런 기계를 좀 봤거든요. 누가 만든 기계인지 따위는 알려드릴 수 없어요.', `FemaleText_loc4`='这家伙能摧毁整支钢铁部队。而且它还不会突然爆炸……比我以前见过的某些机器上等多了。具体是什么机器，我就不提了。', `FemaleText_loc5`='這東西應該能削弱那些鐵矮人軍隊。更棒的是，它不會在你面前炸開...不像我以前見過的那些爛東西一樣。我可沒影射任何人喔，衝扳。', `FemaleText_loc7`='Esta cosa debiera destrozar ese ejército férreo. Mejor todavía, no te explotará en la cara... como otras máquinas que he visto. No me refiero a nadie.' WHERE `ID`=33735;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='유행에 민감하신가 보군요? 당신, 취향이 괜찮네요.', `MaleText_loc4`='你也来赶时髦吗？我欣赏你的品位。', `MaleText_loc5`='想要優雅地騎上一段?我欣賞你的品味。', `MaleText_loc7`='¿Te gusta el estilo? Buen gusto.', `FemaleText_loc1`='유행에 민감하신가 봐요? 당신, 취향이 괜찮네요.', `FemaleText_loc4`='你也来赶时髦吗？我欣赏你的品位。', `FemaleText_loc5`='想要優雅地騎上一段?我欣賞你的品味。', `FemaleText_loc7`='¿Te gusta el estilo? Buen gusto.' WHERE `ID`=33736;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이걸 타면 아무도 당신을 쫓아오지 못할 겁니다!', `MaleText_loc4`='只要骑上这辆宝贝，谁也别想抓住你了！', `MaleText_loc5`='只要你有這個寶貝，沒東西能帶逮住你!', `MaleText_loc7`='¡Nada va a atraparte en esta belleza!', `FemaleText_loc1`='이걸 타면 아무도 당신을 쫓아오지 못할 걸요!', `FemaleText_loc4`='只要骑上这辆宝贝，谁也别想抓住你了！', `FemaleText_loc5`='只要你有這個寶貝，沒東西能帶逮住你!', `FemaleText_loc7`='¡Nada va a atraparte en esta belleza!' WHERE `ID`=33737;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='완전히 고쳤으니 몰고 나가셔도 됩니다. 살살 다뤄 주세요!', `MaleText_loc4`='它已经翻修一新，随时可以出发啦。要好好待它哟！', `MaleText_loc5`='她已經完全修復並且整裝待發。好好照顧她!', `MaleText_loc7`='Está lista y en perfecto estado. ¡Trátala con cariño!', `FemaleText_loc1`='완전히 고쳤으니 몰고 나가셔도 돼요. 살살 다뤄 주세요!', `FemaleText_loc4`='它已经翻修一新，随时可以出发啦。要好好待它哟！', `FemaleText_loc5`='她已經完全修復並且整裝待發。好好照顧她!', `FemaleText_loc7`='Está lista y en perfecto estado. ¡Trátala con cariño!' WHERE `ID`=33738;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='특별한 수제 경적을 여기 달았답니다. 빠라바라바라밤!', `MaleText_loc4`='我们给这些家伙装上了可爱的小喇叭。希望你会喜欢！', `MaleText_loc5`='我們裝了一些超棒的獨特號角，希望你喜歡!', `MaleText_loc7`='Construimos unos bonitos cuernos a medida para estas cosas. ¡Disfrutadlos!', `FemaleText_loc1`='특별한 수제 경적을 여기 달았다고요. 빠라바라바라밤!', `FemaleText_loc4`='我们给这些家伙装上了可爱的小喇叭。希望你会喜欢！', `FemaleText_loc5`='我們裝了一些超棒的獨特號角，希望你喜歡!', `FemaleText_loc7`='Construimos unos bonitos cuernos a medida para estas cosas. ¡Disfrutadlos!' WHERE `ID`=33739;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타르 웅덩이를 잘 써먹으세요. 당신 친구들 머리가 쓸만하다면 타르를 이용해서 적을 불태울 수 있을 겁니다.', `MaleText_loc4`='好好利用那些焦油。如果你的朋友够聪明的话，就应该知道怎么点燃它们。', `MaleText_loc5`='好好利用那些焦油池。如果夠聰明的話，你的朋友們應該知道要點燃它。', `MaleText_loc7`='Haz un buen uso de esos charcos de alquitrán. Tus amigos debieran ser capaces de hacer que prendan fuego si son inteligentes.', `FemaleText_loc1`='타르 웅덩이를 잘 써먹으세요. 당신 친구들 머리가 쓸만하다면 타르를 이용해서 적을 불태울 수 있을 거예요.', `FemaleText_loc4`='好好利用那些焦油。如果你的朋友够聪明的话，就应该知道怎么点燃它们。', `FemaleText_loc5`='好好利用那些焦油池。如果夠聰明的話，你的朋友們應該知道要點燃它。', `FemaleText_loc7`='Haz un buen uso de esos charcos de alquitrán. Tus amigos debieran ser capaces de hacer que prendan fuego si son inteligentes.' WHERE `ID`=33740;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오우, 야성적이야!', `MaleText_loc4`='天生狂野！', `MaleText_loc5`='天性狂野!!', `MaleText_loc7`='¡Nasío pa'' matar!', `FemaleText_loc1`='어쩜, 야성적이야!', `FemaleText_loc4`='天生狂野！', `FemaleText_loc5`='天性狂野!!', `FemaleText_loc7`='¡Nasío pa'' matar!' WHERE `ID`=33741;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='머리가 바람에 휘날리는 그 기분 정말 최고죠! 하지만 고글은 꼭 쓰셔야 합니다. 그놈의 무쇠 드워프들 때문에 난장판이 벌어질 테니까요.', `MaleText_loc4`='风掠过头发的感觉真是酷毙了！不过你最好戴上护目镜。我敢打赌，那些铁矮人一定会被你吓得乱作一团。', `MaleText_loc5`='沒什麼比風吹著頭髮更舒服的了!記得要帶護目鏡，我相信那些鐵矮人一定會造成不少混亂。', `MaleText_loc7`='¡Nada como sentir el viento en tu pelo! Aunque, asegúrate de que lleves puestas las gafas. Apuesto a que esos enanos férreos van a quedar hechos un asco.', `FemaleText_loc1`='머리가 바람에 휘날리는 그 기분 정말 최고죠! 하지만 고글은 꼭 쓰셔야 합니다. 그놈의 무쇠 드워프들 때문에 난장판이 벌어질 테니까요.', `FemaleText_loc4`='风掠过头发的感觉真是酷毙了！不过你最好戴上护目镜。我敢打赌，那些铁矮人一定会被你吓得乱作一团。', `FemaleText_loc5`='沒什麼比風吹著頭髮更舒服的了!記得要帶護目鏡，我相信那些鐵矮人一定會造成不少混亂。', `FemaleText_loc7`='¡Nada como sentir el viento en tu pelo! Aunque, asegúrate de que lleves puestas las gafas. Apuesto a que esos enanos férreos van a quedar hechos un asco.' WHERE `ID`=33742;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들 주위를 빙글빙글 돌면서 겁도 좀 주세요!', `MaleText_loc4`='围着他们转圈！', `MaleText_loc5`='繞著它們轉!', `MaleText_loc7`='¡Conducid en círculos a su alrededor!', `FemaleText_loc1`='놈들 주위를 빙글빙글 돌면서 겁도 좀 주세요!', `FemaleText_loc4`='围着他们转圈！', `FemaleText_loc5`='繞著它們轉!', `FemaleText_loc7`='¡Conducid en círculos a su alrededor!' WHERE `ID`=33743;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\Spell_Arcane_MindMastery.blp:24|t|cFFFF8900 이성을 2%% 상실했습니다.|r', `MaleText_loc4`='|TInterface\\Icons\\Spell_Arcane_MindMastery.blp:24|t|cFFFF8900 理智损失2%%|r', `MaleText_loc5`='|TInterface\\Icons\\Spell_Arcane_MindMastery.blp:24|t|cFFFF8900喪失2%%理智|r', `MaleText_loc7`='|TInterfaceIconsSpell_Arcane_MindMastery.blp:24|t|cFFFF8900 2%% de cordura perdida|r', `FemaleText_loc1`='|TInterface\\Icons\\Spell_Arcane_MindMastery.blp:24|t|cFFFF8900 이성을 2%% 상실했습니다.|r', `FemaleText_loc4`='|TInterface\\Icons\\Spell_Arcane_MindMastery.blp:24|t|cFFFF8900 理智损失2%%|r', `FemaleText_loc5`='|TInterface\\Icons\\Spell_Arcane_MindMastery.blp:24|t|cFFFF8900喪失2%%理智|r', `FemaleText_loc7`='|TInterfaceIconsSpell_Arcane_MindMastery.blp:24|t|cFFFF8900 2%% de cordura perdida|r' WHERE `ID`=33744;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세월에 마모되거나 부식된 흔적은 전혀 없지만, 이 조작대는 고대의 물건인 듯한 분위기를 풍깁니다. 크고 둥그런 원반이 들어갈 법한 홈이 하나 있습니다.', `MaleText_loc4`='控制台显得非常陈旧，却没有一丝破损或是荒废的迹象。上面刻有一道插槽，似乎可以放入大型的圆盘。', `MaleText_loc5`='控制臺看起來十分古老，但沒有一點破敗或腐蝕。有一個凹槽似乎可以放入一片大圓盤。', `MaleText_loc7`='La consola parece antigua, aunque no hay signo alguno de mal uso o de deterioro. Una ranura parece hecha a medida de grandes discos circulares.' WHERE `ID`=33745;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cFFCCCCCC%s|1이;가; 파괴전차의 발사대에 몸을 실었습니다.$B발사할 때까지 무기 시스템이 정지합니다.|r', `MaleText_loc4`='|cFFCCCCCC%s将自己装填进了攻城车的发射臂。$B武器系统处于离线状态，直至发射成功。|r', `MaleText_loc5`='|cFFCCCCCC%s已置入石毀車的發射臂。$B在發射完成前，武器系統將暫停。|r', `MaleText_loc7`='|cFFCCCCCCSe ha cargado a %s en el brazo lanzador de tu demoledor.$BSistemas de armamento desconectados hasta lanzamiento.|r', `FemaleText_loc1`='|cFFCCCCCC%s|1이;가; 파괴전차의 발사대에 몸을 실었습니다.$B발사할 때까지 무기 시스템이 정지합니다.|r', `FemaleText_loc4`='|cFFCCCCCC%s将自己装填进了攻城车的发射臂。$B武器系统处于离线状态，直至发射成功。|r', `FemaleText_loc5`='|cFFCCCCCC%s已置入石毀車的發射臂。$B在發射完成前，武器系統將暫停。|r', `FemaleText_loc7`='|cFFCCCCCCSe ha cargado a %s en el brazo lanzador de tu demoledor.$BSistemas de armamento desconectados hasta lanzamiento.|r' WHERE `ID`=33746;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 용맹전사와 싸울 준비가 되셨습니까?', `MaleText_loc4`='你做好和勇士战斗的准备了吗？', `MaleText_loc5`='你確定要跟驍士進行戰鬥了嗎?', `MaleText_loc7`='¿Seguro que te has preparado para luchar contra un valeroso?', `FemaleText_loc1`='정말 용맹전사와 싸울 준비가 되셨나요?', `FemaleText_loc4`='你做好和勇士战斗的准备了吗？', `FemaleText_loc5`='你確定要跟驍士進行戰鬥了嗎?', `FemaleText_loc7`='¿Seguro que te has preparado para luchar contra un valeroso?' WHERE `ID`=33747;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용맹전사와의 전투가 간단한 일이라고 생각한다면 현명하지 못할 겁니다. 준비되셨습니까?', `MaleText_loc4`='别以为你可以轻而易举地战胜一位勇士。你确定自己已经准备好了吗？', `MaleText_loc5`='認為跟一名驍士戰鬥只是小事一樁，這可是很不智的想法。你確定你準備好了嗎?', `MaleText_loc7`='No sería sensato asumir que pelear con un valeroso es tarea fácil. ¿Seguro que te has preparado?', `FemaleText_loc1`='용맹전사와의 전투가 간단한 일이라고 생각한다면 현명하지 못할 겁니다. 준비되셨나요?', `FemaleText_loc4`='别以为你可以轻而易举地战胜一位勇士。你确定自己已经准备好了吗？', `FemaleText_loc5`='認為跟一名驍士戰鬥只是小事一樁，這可是很不智的想法。你確定你準備好了嗎?', `FemaleText_loc7`='No sería sensato asumir que pelear con un valeroso es tarea fácil. ¿Seguro que te has preparado?' WHERE `ID`=33748;
