UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동료가 쓰러지는 모습을 본 %s에게 새로운 힘이 용솟음치는 것 같습니다!', `MaleText_loc4`='%s因同伴的死而震怒！', `MaleText_loc5`='當它的夥伴死去時，%s帶著力量猛衝!', `MaleText_loc7`='¡%s se alza con poder tras perecer su acompañante!', `FemaleText_loc1`='동료가 쓰러지는 모습을 본 %s에게 새로운 힘이 용솟음치는 것 같습니다!', `FemaleText_loc4`='%s因同伴的死而震怒！', `FemaleText_loc5`='當它的夥伴死去時，%s帶著力量猛衝!', `FemaleText_loc7`='¡%s se alza con poder tras perecer su acompañante!' WHERE `ID`=33770;
