UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='실버문의 이름으로 이번 마상시합에서 이기면 영예는 우리의 것입니다.', `FemaleText_loc4`='等我们以银月城的名义赢下这场锦标赛时，荣耀将属于我们。', `FemaleText_loc5`='當我們以銀月城之名贏得聯賽，榮耀將盡歸於我們。', `FemaleText_loc7`='Nuestra será la gloria cuando ganemos este torneo en nombre de Lunargenta.' WHERE `ID`=33780;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='축하합니다. 이제 이중 전문화를 배우셨습니다.', `MaleText_loc4`='你现在已经学会了双天赋专精。', `MaleText_loc5`='你學會了雙天賦專精。', `MaleText_loc7`='Acabas de aprender la doble especialización.', `FemaleText_loc1`='축하합니다. 이제 이중 전문화를 배우셨습니다.', `FemaleText_loc4`='你现在已经学会了双天赋专精。', `FemaleText_loc5`='你學會了雙天賦專精。', `FemaleText_loc7`='Acabas de aprender la doble especialización.' WHERE `ID`=33781;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용사의 자리에 오를 준비가 되었다는 걸 보여줬군요.', `MaleText_loc4`='看来你已经做好晋级为冠军的准备了。', `MaleText_loc5`='你已經證明了你足以晉升勇士的位階。', `MaleText_loc7`='Has demostrado que estás en condiciones de ascender de rango y unirte al resto de Campeones.', `FemaleText_loc1`='용사의 자리에 오를 준비가 되었다는 걸 보여줬군요.', `FemaleText_loc4`='看来你已经做好晋级为冠军的准备了。', `FemaleText_loc5`='你已經證明了你足以晉升勇士的位階。', `FemaleText_loc7`='Has demostrado que estás en condiciones de ascender de rango y unirte al resto de Campeones.' WHERE `ID`=33782;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대단히 인상적이군요. 당신은 용사의 자리를 차지할 자격이 있군요.', `MaleText_loc4`='令人印象深刻啊。你完全有资格成为冠军。', `MaleText_loc5`='令人印象深刻。你已經足以獲得勇士位階。', `MaleText_loc7`='Impresionante. Mereces subir de rango y unirte al resto de Campeones.', `FemaleText_loc1`='대단히 인상적이군요. 당신은 용사의 자리를 차지할 자격이 있군요.', `FemaleText_loc4`='令人印象深刻啊。你完全有资格成为冠军。', `FemaleText_loc5`='令人印象深刻。你已經足以獲得勇士位階', `FemaleText_loc7`='Impresionante. Mereces subir de rango y unirte al resto de Campeones.' WHERE `ID`=33783;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 은빛십자군 형제들과 나란히 명예, 명성 그리고 스컬지와 싸워야만 하는 정당성을 얻고자 경쟁을 시작했답니다.', `MaleText_loc4`='我们来到这里，为荣耀而战，为名誉而战，为获得与银色北伐军的兄弟们并肩作战的资格而战。', `MaleText_loc5`='我們為了榮譽、名聲，以及跟銀白十字軍的兄弟並肩作戰的權力而參賽。', `MaleText_loc7`='Hemos venido a competir por el honor, el renombre y el derecho a combatir la Plaga junto a los hermanos de la Cruzada Argenta.' WHERE `ID`=33784;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마그니 국왕께서는 우리에게 이번 마상시합에서 승리를 거둬 자랑으로 여길 수 있길 기대하십니다. 우린 지지 않을 겁니다.', `FemaleText_loc4`='麦格尼国王希望我们赢得锦标赛的胜利。我们绝不能失败。', `FemaleText_loc5`='麥格尼王期待我們贏得聯賽，讓他驕傲。我們絕不會失敗。', `FemaleText_loc7`='El rey Magni espera que ganemos este torneo y enorgullecerse de nosotros. No le fallaremos.' WHERE `ID`=33785;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뛰어난 놈리건의 친구들이 이번 마상시합에 참가하고 있답니다. 행운을 빌어주세요!', `MaleText_loc4`='诺莫瑞根的精英来参加锦标赛啦。祝我们好运！', `MaleText_loc5`='諾姆瑞根的精英來參加聯賽了。祝我們好運吧!', `MaleText_loc7`='Lo mejor de Gnomeregan ha venido a competir en el torneo. ¡Deséanos suerte!' WHERE `ID`=33786;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용사가 될 준비가 되었다 생각하는군요. 두고 보면 알 겁니다.', `MaleText_loc4`='你觉得自己已经做好了晋级冠军的准备？让我们拭目以待吧。', `MaleText_loc5`='你覺得自己準備好成為一位勇士。我們等著瞧。', `MaleText_loc7`='Crees que estás preparad$go:a; para convertirte en Campe$gón:ona;. Ya veremos.', `FemaleText_loc1`='용사가 될 준비가 되었다 생각하는군요. 두고 보면 알 겁니다.', `FemaleText_loc4`='你觉得自己已经做好了晋级冠军的准备？让我们拭目以待吧。', `FemaleText_loc5`='你覺得自己準備好成為一位勇士。我們等著瞧。', `FemaleText_loc7`='Crees que estás preparad$go:a; para convertirte en Campe$gón:ona;. Ya veremos.' WHERE `ID`=33787;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용사가 될 준비가 되었다고 믿는 건가요? 그럼 자신을 방어해 보시죠!', `MaleText_loc4`='你觉得自己已经做好了晋级冠军的准备？小心了！', `MaleText_loc5`='你相信自己已經準備好成為一位勇士了?證明你自己吧!', `MaleText_loc7`='¿Crees que estás preparad$go:a; para ser u$gn:na; Campe$gón:ona;? ¡Defiéndete!', `FemaleText_loc1`='용사가 될 준비가 되었다고 믿나요? 그럼 자신을 방어해 보세요!', `FemaleText_loc4`='你觉得自己已经做好了晋级冠军的准备？小心了！', `FemaleText_loc5`='你相信自己已經準備好成為一位勇士了?證明你自己吧!', `FemaleText_loc7`='¿Crees que estás preparad$go:a; para ser u$gn:na; Campe$gón:ona;? ¡Defiéndete!' WHERE `ID`=33788;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다르나서스를 대표하는 우리는 마상시합에서의 경쟁을 고대하고 있습니다.', `MaleText_loc4`='达纳苏斯的精灵们希望在锦标赛中一展身手。', `MaleText_loc5`='我們達納蘇斯引領期盼參與聯賽競技。', `MaleText_loc7`='Nosotros, los de Darnassus, ansiamos competir en el torneo.' WHERE `ID`=33789;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용사의 자리에 오르기엔 아직 준비가 안 된 것 같군요. 훈련을 좀 더 하면 도움이 될 겁니다.', `MaleText_loc4`='看来你还没有做好晋级为冠军的准备。最好多加练习。', `MaleText_loc5`='看來你還沒準備好成為一位勇士。你需要更多的訓練。', `MaleText_loc7`='Parece que no estás en condiciones de subir de rango y unirte al resto de campeones. Puede que te venga bien entrenar un poco más.', `FemaleText_loc1`='용사의 자리에 오르기엔 아직 준비가 안 된 것 같군요. 훈련을 좀 더 하면 도움이 될 겁니다.', `FemaleText_loc4`='看来你还没有做好晋级为冠军的准备。最好多加练习。', `FemaleText_loc5`='看來你還沒準備好成為一位勇士。你需要更多的訓練。', `FemaleText_loc7`='Parece que no estás en condiciones de subir de rango y unirte al resto de campeones. Puede que te venga bien entrenar un poco más.' WHERE `ID`=33790;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 졌군요. 하지만 포기하지 마세요. 언젠가 당신은 용사로서 우리 위치에 오르게 될 겁니다.', `MaleText_loc4`='你输了。不要放弃。我有预感，总有一天你会加入我们的行列，成为一名冠军。', `MaleText_loc5`='你已經被擊敗了。但並沒有放棄。我覺得你有一天會加入我們成為勇士的一份子。', `MaleText_loc7`='Te han derrotado. Pero no te rindas. Presiento que un día te unirás a nuestras filas como Campeón.', `FemaleText_loc1`='당신이 졌군요. 하지만 포기하지 마세요. 언젠가 당신은 용사로서 우리 위치에 오르게 될 겁니다.', `FemaleText_loc4`='你输了。不要放弃。我有预感，总有一天你会加入我们的行列，成为一名冠军。', `FemaleText_loc5`='你已經被擊敗了。但並沒有放棄。我覺得你有一天會加入我們成為勇士的一份子。', `FemaleText_loc7`='Te han derrotado. Pero no te rindas. Presiento que un día te unirás a nuestras filas como Campeón.' WHERE `ID`=33791;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시험을 너무 오래 끌었군요. 당신은 용사가 되기엔 아직 부족합니다.', `MaleText_loc4`='这次测试用了太久的时间。你还不足以成为一名冠军。', `MaleText_loc5`='這場考驗持續太久了。你還沒準備好成為一名勇士。', `MaleText_loc7`='Esta prueba ha durado demasiado. No estás $glisto:lista; para ser $gun:una; $gCampeón:Campeona;.', `FemaleText_loc1`='시험을 너무 오래 끌었군요. 당신은 용사가 되기엔 아직 부족합니다.', `FemaleText_loc4`='这次测试用了太久的时间。你还不足以成为一名冠军。', `FemaleText_loc5`='這場考驗持續太久了。你還沒準備好成為一名勇士。', `FemaleText_loc7`='Esta prueba ha durado demasiado. No estás $glisto:lista; para ser $gun:una; $gCampeón:Campeona;.' WHERE `ID`=33792;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분명히 당신은 지금보다 더 잘할 수 있습니다. 이번 전투로 내 시간을 허비했군요. 당신은 아직 용사가 될 준비가 안 됐습니다.', `MaleText_loc4`='你的表现应该更好才对。这场战斗简直是在浪费我的时间。你还不足以成为一名冠军。', `MaleText_loc5`='你當然可以做得更好。這場戰鬥根本在浪費我的時間。你還沒準備好成為一名勇士。', `MaleText_loc7`='Seguro que puedes hacerlo mejor. Esta lucha ha sido una pérdida de tiempo. No estás preparad$go:a; para ser $gun Campeón:una Campeona;.', `FemaleText_loc1`='분명히 당신은 지금보다 더 잘할 수 있습니다. 이번 전투로 내 시간을 허비했군요. 당신은 아직 용사가 될 준비가 안 됐습니다.', `FemaleText_loc4`='你的表现应该更好才对。这场战斗简直是在浪费我的时间。你还不足以成为一名冠军。', `FemaleText_loc5`='你當然可以做得更好。這場戰鬥根本在浪費我的時間。你還沒準備好成為一名勇士。', `FemaleText_loc7`='Seguro que puedes hacerlo mejor. Esta lucha ha sido una pérdida de tiempo. No estás preparad$go:a; para ser $gun Campeón:una Campeona;.' WHERE `ID`=33793;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마상시합이 시작되면, 모두가 포세이큰이 출전하여 승리를 거두는 모습을 보게 될 걸세.', `MaleText_loc4`='锦标赛开始后，所有人都将见证被遗忘者的胜利。', `MaleText_loc5`='等到聯賽開始，所有人都會看到被遺忘者獲得勝利。', `MaleText_loc7`='Cuando empiece el torneo, todos verán como los Renegados salen victoriosos.' WHERE `ID`=33794;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번 경쟁은 치열하겠지만 오그리마의 용사들은 우리 길을 가로막는 자들은 모두 처치할 걸세.', `MaleText_loc4`='竞争会非常激烈，但是奥格瑞玛的勇士是所向披靡的。', `MaleText_loc5`='競爭將會十分激烈，但是奧格瑪的勇士將會消滅所有阻擋我們的人。', `MaleText_loc7`='La competición será despiadada, pero los campeones de Orgrimmar harán pedazos a todo aquel que se interponga en nuestro camino.' WHERE `ID`=33795;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 영광을 얻을 뿐만 아니라 우리 조상과 백성들의 명예를 드높이고자 경쟁한답니다.', `MaleText_loc4`='我们不仅为荣耀而战，还要为我们的先祖和人民赢得光荣。', `MaleText_loc5`='我們不只是為了榮譽而參賽，更是要將光榮帶給我們的祖先與同胞。', `MaleText_loc7`='Competimos no solo por la gloria, sino para honrar a nuestros ancestros y a nuestro pueblo.' WHERE `ID`=33796;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은창 부족은 이번 경쟁과 적들에게 맞설 각오가 되었네.', `MaleText_loc4`='暗矛氏族已经做好了竞争的准备。', `MaleText_loc5`='暗矛部族已經準備好要面對競賽與敵人。', `MaleText_loc7`='Los Lanza Negra están listos para enfrentarse a la competición y al enemigo.' WHERE `ID`=33797;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선리버를 대표하여, 이번 마상시합에 참가하시는 당신을 환영하는 바입니다. 은빛십자군에서는 우리 선리버에게 이번 시합에 흥미를 가진 자들의 신청을 받고 훈련을 맡아 달라고 요청했답니다.', `MaleText_loc4`='我代表夺日者欢迎你参加锦标赛。银色北伐军委托我们登记并训练那些对比赛感兴趣的选手。', `MaleText_loc5`='以奪日者之名，我歡迎你來到聯賽。銀白十字軍請我們協助那些對參賽有興趣的人進行登記與訓練。', `MaleText_loc7`='En nombre de los Atracasol, te doy la bienvenida al torneo. La Cruzada Argenta nos ha pedido que inscribamos y entrenemos a todo aquel que esté interesado en competir.' WHERE `ID`=33798;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은빛십자군의 용맹전사와 싸울 준비가 되셨나요?', `MaleText_loc4`='你做好和银色北伐军勇士作战的准备了吗？', `MaleText_loc5`='你準備好迎戰銀白十字軍的驍士了嗎?', `MaleText_loc7`='¿Ya te has preparado para pelear contra un valeroso de la Cruzada Argenta?', `FemaleText_loc1`='은빛십자군의 용맹전사와 싸울 준비가 되셨나요?', `FemaleText_loc4`='你做好和银色北伐军勇士作战的准备了吗？', `FemaleText_loc5`='你準備好迎戰銀白十字軍的驍士了嗎?', `FemaleText_loc7`='¿Ya te has preparado para pelear contra un valeroso de la Cruzada Argenta?' WHERE `ID`=33799;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용맹전사의 자리를 위한 시험에 응할 준비가 되면, 은빛십자군 일원을 불러 드릴게요.', `MaleText_loc4`='当你准备好参加勇士的晋级测试后，我会召来一位银色北伐军的成员。', `MaleText_loc5`='等你準備好接受驍士位階的考驗，我會喚來一名銀白十字軍的成員。', `MaleText_loc7`='Cuando estés preparad$go:a; para ponerte a prueba para el rango de Valeros$go:a;, llamaré a un miembro de la Cruzada Argenta.', `FemaleText_loc1`='용맹전사의 자리를 위한 시험에 응할 준비가 되면, 은빛십자군 일원을 불러 드릴게요.', `FemaleText_loc4`='当你准备好参加勇士的晋级测试后，我会召来一位银色北伐军的成员。', `FemaleText_loc5`='等你準備好接受驍士位階的考驗，我會喚來一名銀白十字軍的成員。', `FemaleText_loc7`='Cuando estés preparad$go:a; para ponerte a prueba para el rango de Valeros$go:a;, llamaré a un miembro de la Cruzada Argenta.' WHERE `ID`=33800;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳은 용사들이 서로 겨루며 기량을 갈고 닦는 연습장입니다. 용사분들의 연습 전투에 흑기사들을 소환하는 게 제 일이지요.', `MaleText_loc4`='这座竞技场专供冠军们互相切磋之用。我负责召唤骑兵来参加战斗练习。', `MaleText_loc5`='這是勇士彼此練習對戰的競技場地。我的工作就是召喚騎士前來參加練習賽。', `MaleText_loc7`='Hay una liza en la que los campeones se enfrentan unos a otros para entrenarse. Mi trabajo es llamar a los caballeros a sus batallas de entrenamiento.' WHERE `ID`=33801;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카빈에게 흑기사를 소환해 달라고 청합니다.', `MaleText_loc4`='让加文召唤黑骑士。', `MaleText_loc5`='請凱文召喚黑騎士。', `MaleText_loc7`='Pide a Cavin que llame al Caballero Negro.', `FemaleText_loc1`='카빈에게 흑기사를 소환해 달라고 청합니다.', `FemaleText_loc4`='让加文召唤黑骑士。', `FemaleText_loc5`='請凱文召喚黑騎士。', `FemaleText_loc7`='Pide a Cavin que llame al Caballero Negro.' WHERE `ID`=33802;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 흑기사와 결투로 승부를 가리고자 도전을 청합니다!', `MaleText_loc4`='$n向黑骑士发起挑战！', `MaleText_loc5`='$n在比武審判中向黑騎士挑戰!', `MaleText_loc7`='¡$n reta al Caballero Negro a un combate!' WHERE `ID`=33803;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='행운을 빕니다, $n 님.', `MaleText_loc4`='祝你好运，$n。', `MaleText_loc5`='祝好運，$n。', `MaleText_loc7`='Buena suerte, $n.' WHERE `ID`=33804;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 분께서 도전하고 계시네요. 진행 중인 전투가 끝나면 연습장을 사용하실 수 있을 거예요.', `MaleText_loc4`='有人正在进行挑战。战斗结束后才能使用竞技场。', `MaleText_loc5`='某人正在進行挑戰。等戰鬥結束後競技場地才會空出來。', `MaleText_loc7`='Alguien ha lanzado ya un desafío. La liza estará disponible cuando termine la lucha.' WHERE `ID`=33805;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흑기사가 패했습니다!', `MaleText_loc4`='黑骑士被击败了！', `MaleText_loc5`='黑騎士被擊敗了!', `MaleText_loc7`='¡El Caballaro Negro ha sido derrotado!' WHERE `ID`=33806;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 그런 거만한 태도는 못 참겠군그래! 죽을 준비나 해라!', `MaleText_loc4`='我受够了你的傲慢！去死吧！', `MaleText_loc5`='我受夠了你的傲慢無禮!準備受死吧!', `MaleText_loc7`='¡Suficiente insolencia! ¡Prepárate a morir!' WHERE `ID`=33807;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가동 중지.', `MaleText_loc4`='正在关闭。', `MaleText_loc5`='撤銷。', `MaleText_loc7`='Desactivando.' WHERE `ID`=33808;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈은 이 지하에서 우리와 함께 영원토록 편안하고 따뜻한 안식의 시간을 보내게 될 것이다, 정말 아름답지 않은가!', `MaleText_loc4`='你可真好，美人！愿意和我们永远留在一起！', `MaleText_loc5`='你將在下面永遠跟我們幸福的生活著，太棒了!', `MaleText_loc7`='¡Preciosa, vas a estar muy cómoda y calentita si te quedas aquí abajo con nosotros, para siempre!' WHERE `ID`=33809;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑네, 친구, 아주 반갑군! 한 놈 더 죽일 시간은 언제든지 있지!', `MaleText_loc4`='欢迎，朋友，欢迎！这里永远都会为新朋友留下位置！', `MaleText_loc5`='歡迎你，朋友，歡迎!我們永遠不嫌人多!', `MaleText_loc7`='¡Bienvenido, amigo, bienvenido! ¡Siempre hay sitio para uno más!' WHERE `ID`=33810;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑군! 내 이름은 우실이다. 네놈이 죽고 나면 우리는 정말 좋은 친구가 될 것 같은데!', `MaleText_loc4`='嗨！我叫尤希尔。等你死了，我们一定能成为好朋友的！', `MaleText_loc5`='嗨!我的名字是尤希爾。你死後我們一定會變成超好的朋友!', `MaleText_loc7`='¡Hola! Me llamo Uthil. ¡Vamos a ser muy buenos amigos cuando estés $gmuerto:muerta;!' WHERE `ID`=33811;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 자라거라, 작은 친구여.', `MaleText_loc4`='生长吧，小家伙。', `MaleText_loc5`='快長大吧，小傢伙。', `MaleText_loc7`='Crece, pequeño.' WHERE `ID`=33812;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 있었구나.', `MaleText_loc4`='瞧瞧。', `MaleText_loc5`='你在這兒。', `MaleText_loc7`='Ahí estás.' WHERE `ID`=33813;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 날카로운 바람으로부터 우릴 보호하는 방패가 되어 다오, 작은 묘목아.', `MaleText_loc4`='帮我们抵御这刺骨的寒风吧，小树苗。', `MaleText_loc5`='幫我們擋一擋這刺骨的寒風，小夥子。', `MaleText_loc7`='Ayúdanos a protegernos de estos cortantes vientos, pequeño pimpollo.' WHERE `ID`=33814;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안쪽에서 여러분께 행운이 있기를 빕니다. 광장이 정리되면 저 안쪽에서 뵙지요.', `MaleText_loc4`='祝你好运。等广场清理干净后，我就到里面去跟你会合。', `MaleText_loc5`='你在這裡可真幸運。等集合場被清空之後我就會到更裡面去找你。', `MaleText_loc7`='Buena suerte ahí dentro. Intentaré encontraros en el interior cuando la explanada quede libre.' WHERE `ID`=33815;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='움직일 준비가 됐습니다. 저 드워프 놈들을 좀 막아 주세요!', `MaleText_loc4`='开始行动，别让那些矮人妨碍我们！', `MaleText_loc5`='準備出發，讓那些矮人遠離我們的後方!', `MaleText_loc7`='Listos para salir, ¡impedid que esos enanos se peguen a nuestra espalda!', `FemaleText_loc1`='움직일 준비가 됐습니다. 저 드워프 놈들을 좀 막아 주세요!', `FemaleText_loc4`='开始行动，别让那些矮人妨碍我们！', `FemaleText_loc5`='準備出發，讓那些矮人遠離我們的後方!', `FemaleText_loc7`='Listos para salir, ¡impedid que esos enanos se peguen a nuestra espalda!' WHERE `ID`=33816;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물러서거라, $n. 숲의 심장을 정화해야만 한다.', `MaleText_loc4`='后退，$n。我必须净化森林之心。', `MaleText_loc5`='後退，$n。我必須淨化森林之心。', `MaleText_loc7`='Atrás, $n. Debo purificar el corazón del bosque.' WHERE `ID`=33817;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기술자들을 잃고 말았습니다. 좋게 끝날 것 같진 않네요!', `MaleText_loc4`='我们的工程师挂掉了，事情好像要糟糕！', `MaleText_loc5`='我們失去了所有的工程師，這可不妙!', `MaleText_loc7`='Hemos perdido a nuestros ingenieros, ¡esto no acabará bien!' WHERE `ID`=33818;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 이제 숲의 심장이 정화되었다. 숲의 심장의 힘은 잿빛 골짜기를 다시 한 번 살려내리라. 영원히 갚을 수 없는 빚을 졌구나, 작은 존재여.', `MaleText_loc4`='森林之心已经被净化了。它的力量将再一次充盈灰谷。年轻人，我们将永远感激你的英勇行为。', `MaleText_loc5`='森林之心現在已經淨化好了。它的力量會再次滋潤梣谷。年輕人，我們將永遠記得這個人情。', `MaleText_loc7`='Toma, el corazón del bosque ya está purificado. Su poder volverá a inundar Vallefresno. Siempre estaremos en deuda contigo, joven.' WHERE `ID`=33819;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희에게 잠깐 포탑을 설치할 시간을 주세요.', `MaleText_loc4`='给我们一点时间，做好建筑炮台的准备。', `MaleText_loc5`='給我們一點時間來準備建造砲塔。', `MaleText_loc7`='Danos un momento para que nos preparemos para construir las torretas.', `FemaleText_loc1`='저희에게 잠깐 포탑을 설치할 시간을 주세요.', `FemaleText_loc4`='给我们一点时间，做好建筑炮台的准备。', `FemaleText_loc5`='給我們一點時間來準備建造砲塔。', `FemaleText_loc7`='Danos un momento para que nos preparemos para construir las torretas.' WHERE `ID`=33820;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불꽃이 꺼졌습니다! 포탑을 재설치합시다!', `MaleText_loc4`='火灭了！准备重建炮台！', `MaleText_loc5`='火熄了!讓我們重建砲塔!', `MaleText_loc7`='¡Llamas extintas! ¡Reconstruyamos esas torretas!', `FemaleText_loc1`='불꽃이 꺼졌어요! 포탑을 재설치합시다!', `FemaleText_loc4`='火灭了！准备重建炮台！', `FemaleText_loc5`='火熄了!讓我們重建砲塔!', `FemaleText_loc7`='¡Llamas extintas! ¡Reconstruyamos esas torretas!' WHERE `ID`=33821;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='땅이 흔들리는 건 정말 싫습니다...', `MaleText_loc4`='俺可不喜欢地面乱晃……', `MaleText_loc5`='我不喜歡地在搖...', `MaleText_loc7`='A mí no gustar que el suelo tiemble.', `FemaleText_loc1`='땅이 흔들리는 건 정말 싫어요...', `FemaleText_loc4`='俺可不喜欢地面乱晃……', `FemaleText_loc5`='我不喜歡地在搖...', `FemaleText_loc7`='A mí no gustar que el suelo tiemble.' WHERE `ID`=33822;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일이 일어난 겁니까?!', `MaleText_loc4`='出……出了什么事！？！', `MaleText_loc5`='發...發生了什麼事!?!', `MaleText_loc7`='¿Qué... qué está pasando?', `FemaleText_loc1`='무슨 일이 일어난 거죠?!', `FemaleText_loc4`='出……出了什么事！？！', `FemaleText_loc5`='發...發生了什麼事!?!', `FemaleText_loc7`='¿Qué... qué está pasando?' WHERE `ID`=33823;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='토막나무 주둔지가 공격받고 있습니다!', `MaleText_loc4`='碎木岗哨遭到了攻击！！', `MaleText_loc5`='碎木正遭受攻擊!', `MaleText_loc7`='¡Puesto del Hachazo está bajo ataque!', `FemaleText_loc1`='토막나무 주둔지가 공격받고 있어요!', `FemaleText_loc4`='碎木岗哨遭到了攻击！！', `FemaleText_loc5`='碎木正遭受攻擊!', `FemaleText_loc7`='¡Puesto del Hachazo está bajo ataque!' WHERE `ID`=33824;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='토막나무 주둔지가 포위됐습니다!', `MaleText_loc4`='碎木岗哨被包围了！', `MaleText_loc5`='碎木被包圍了!', `MaleText_loc7`='¡Puesto del Hachazo está rodeado!', `FemaleText_loc1`='토막나무 주둔지가 포위됐어요!', `FemaleText_loc4`='碎木岗哨被包围了！', `FemaleText_loc5`='碎木被包圍了!', `FemaleText_loc7`='¡Puesto del Hachazo está rodeado!' WHERE `ID`=33825;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s 주위에 공허의 보호막이 생기고, 주변에서 검은 그림자가 합쳐집니다!', `MaleText_loc4`='%s对自己施放了虚空屏障，阴影在它的周围汇聚了起来！', `MaleText_loc5`='%s以虛無屏障籠罩著自己，彷彿一層暗影包覆了周圍。', `MaleText_loc7`='¡%s se rodea de una Barrera del Vacío al tiempo que cerca se forma una oscura sombra!' WHERE `ID`=33826;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어쨌거나 우리가 여기 어떻게 올라온 거죠?', `MaleText_loc4`='我们到底是怎样到这里的？', `MaleText_loc5`='我們是怎麼到這上面的?', `MaleText_loc7`='¿Cómo hemos llegado aquí arriba?', `FemaleText_loc1`='어쨌거나 우리가 여기 어떻게 올라온 거죠?', `FemaleText_loc4`='我们到底是怎样到这里的？', `FemaleText_loc5`='我們是怎麼到這上面的?', `FemaleText_loc7`='¿Cómo hemos llegado aquí arriba?' WHERE `ID`=33827;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='땅이 어디 있는지 보세요! 제가 몰죠.', `MaleText_loc4`='看看地面在哪里！让我来驾驶。', `MaleText_loc5`='現在看看地面在哪裡!讓我來開。', `MaleText_loc7`='¡AHORA mira donde está el suelo! Déjame conducir.', `FemaleText_loc1`='땅이 어디 있는지 보세요! 제가 몰죠.', `FemaleText_loc4`='看看地面在哪里！让我来驾驶。', `FemaleText_loc5`='現在看看地面在哪裡!讓我來開。', `FemaleText_loc7`='¡AHORA mira donde está el suelo! Déjame conducir.' WHERE `ID`=33828;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가서 일하란 말이다, 하찮은 놈들아! 일이 한참 밀렸단 말이다!', `MaleText_loc4`='赶快去工作！我们的进度已经落后了！', `MaleText_loc5`='回去工作，奴犬們!我們的進度已經落後了!', `MaleText_loc7`='¡Poneos a trabajar, perros! ¡Vamos con retraso!' WHERE `ID`=33829;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파! 어서 파내란 말이야!', `MaleText_loc4`='挖！挖！挖！', `MaleText_loc5`='挖!挖!挖!', `MaleText_loc7`='¡Cavad! ¡Cavad! ¡Cavad!' WHERE `ID`=33830;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 빨리 파내란 말이다! 가만있으면 광석이 알아서 튀어나오나!', `MaleText_loc4`='快点挖！矿石不会自己蹦出来！', `MaleText_loc5`='挖快點!這個礦不會自己跳起來!', `MaleText_loc7`='¡Cavad, más deprisa! ¡Esta mena no se va a picar sola!' WHERE `ID`=33831;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쉴 시간 따위는 없다! 가서 일해!', `MaleText_loc4`='没时间休息了，快回去工作！', `MaleText_loc5`='沒時間休息!回去工作!', `MaleText_loc7`='¡No hay tiempo para descansos! ¡Volved al trabajo!' WHERE `ID`=33832;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무쇠 평의회를 쓰러뜨리고 고대 기록관을 여셨군요! 대단하십니다!', `MaleText_loc4`='你们击败了钢铁议会，打开了档案馆！干得好，伙计们！', `MaleText_loc5`='你擊敗了鐵之議會並打開了大資料庫!幹得好，小夥子!', `MaleText_loc7`='¡Han vencido al Consejo Férreo y abierto el Archivum! ¡Muy bien, muchachos!' WHERE `ID`=33833;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아하는 용사에 대한 지지를 보여주세요! 다음 시합에서 그들을 대표하는 셔츠를 입고 손님께서 누굴 좋아하는지 용사들에게 보여주시면 어떨까요!', `MaleText_loc4`='支持你最喜欢的冠军吧！下一回合时，穿上和他们的代表色一致的衣服，让大家都看看你喜欢谁！', `MaleText_loc5`='對你最喜歡的勇士表現你的支持與熱情!在下一場比賽穿著他們的代表色，讓他們知道你最愛誰!', `MaleText_loc7`='¡Muestren su apoyo a su campeón favorito! ¡Lleven sus colores en la siguiente ronda y dejen que sepa a quién adoran!' WHERE `ID`=33834;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 친구 중 한 명과 전투를 하지 않고 자신의 긍지를 보여주고 싶지 않으신가요? 손님께서 어느 도시를 응원하든지, 손님께서 원하는 건 제게 다 있습니다요!', `MaleText_loc4`='你是否已经厌倦了与野兽扭打，想要换个方式来展示自己的本事？无论你来自哪座城市，我都可以满足你的愿望！', `MaleText_loc5`='想避開那些野獸，展現你的驕傲?不管你來自哪座城市，我都有你要的東西!', `MaleText_loc7`='¿Quieres pavonearte sin ir dando saltos sobre una de esas bestias? Representes la ciudad que representes, ¡tengo lo que necesitas!' WHERE `ID`=33835;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여러분! 여기 겹셔츠 좀 보세요! 펄럭거리고 거추장스러운 휘장을 입지 않아도 응원하는 도시의 색상을 자랑할 수 있답니다!', `MaleText_loc4`='嘿！瞧瞧这些紧身衣！穿上它，既有了城市的代表色，又省去了宽松的战袍带来的麻烦事儿！', `MaleText_loc5`='嗨!瞧瞧這些窄衣!現在你可以穿上代表自己城市的顏色，而不需要忍受外袍啪啪作響，礙手礙腳!', `MaleText_loc7`='¡Hey! ¡Fíjate en estos jubones! ¡Ahora puedes mostrar los colores de tu ciudad sin un tabardo revoloteando por ahí y estorbándote!' WHERE `ID`=33836;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번 마상시합은 오랜만에 열리는 가장 큰 행사입니다요! 집에 있는 가족들에게 가져갈 기념품을 사서 아이들에게 보여주세요.', `MaleText_loc4`='本次锦标赛是数个世纪以来最盛大的赛事！买点纪念品回家送给家人和孩子吧！', `MaleText_loc5`='這場聯賽是多年來最盛大的活動!買點東西帶回家給你的家人，送給你的小孩。', `MaleText_loc7`='¡Este torneo es el mayor acontecimiento desde hace años! Compra algo que llevar a tu familia y mostrar a tus hijos.' WHERE `ID`=33837;
