UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\Spell_Arcane_MindMastery.blp:24|t|cFFFF8900 이성을 4%% 상실했습니다.|r', `MaleText_loc4`='|TInterface\\Icons\\Spell_Arcane_MindMastery.blp:24|t|cFFFF8900 理智损失4%%|r', `MaleText_loc5`='|TInterface\\Icons\\Spell_Arcane_MindMastery.blp:24|t|cFFFF8900喪失4%%理智|r', `MaleText_loc7`='|TInterfaceIconsSpell_Arcane_MindMastery.blp:24|t|cFFFF8900 4%% de cordura perdida|r', `FemaleText_loc1`='|TInterface\\Icons\\Spell_Arcane_MindMastery.blp:24|t|cFFFF8900 이성을 4%% 상실했습니다.|r', `FemaleText_loc4`='|TInterface\\Icons\\Spell_Arcane_MindMastery.blp:24|t|cFFFF8900 理智损失4%%|r', `FemaleText_loc5`='|TInterface\\Icons\\Spell_Arcane_MindMastery.blp:24|t|cFFFF8900喪失4%%理智|r', `FemaleText_loc7`='|TInterfaceIconsSpell_Arcane_MindMastery.blp:24|t|cFFFF8900 4%% de cordura perdida|r' WHERE `ID`=33854;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은빛십자군 마상시합 광장 내에 있어야 합니다.', `MaleText_loc4`='你不能离开银色锦标赛的赛场。', `MaleText_loc5`='你必須留在銀白聯賽場地內。', `MaleText_loc7`='Debes permanecer en los Campos del Torneo Argenta.', `FemaleText_loc1`='은빛십자군 마상시합 광장 내에 있어야 합니다.', `FemaleText_loc4`='你不能离开银色锦标赛的赛场。', `FemaleText_loc5`='你必須留在銀白聯賽場地內。', `FemaleText_loc7`='Debes permanecer en los Campos del Torneo Argenta.' WHERE `ID`=33855;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 고철로봇을 소비해 체력을 회복합니다!', `MaleText_loc4`='%s吞噬了一个废料机器人以进行自我修复！', `MaleText_loc5`='%s吞下一台廢料機器人來修復自己!', `MaleText_loc7`='¡%s consume un robot chatarra para repararse!' WHERE `ID`=33856;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='작살 포탑이 준비되었습니다!', `MaleText_loc4`='可以使用鱼叉炮台了！', `MaleText_loc5`='魚叉砲塔已經準備就緒!', `MaleText_loc7`='¡Torreta de arpones lista!' WHERE `ID`=33857;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='거기 계셨군요! 최대한 빠른 친구가 필요합니다. 생명이 달린 문제입니다!', `FemaleText_loc4`='就是你！我们急需有能力的人。许多人的生命都在等待你去拯救！', `FemaleText_loc5`='就是你!我們需要可以幹活的人，越快越好。這攸關性命!', `FemaleText_loc7`='¡Tú! Necesitamos manos capaces lo antes posible. ¡Hay vidas que dependen de ello!' WHERE `ID`=33858;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가장 황당무계한 꿈보다도 더 믿기 어려운 비밀이 이 전당 안에 숨어 있습니다.', `MaleText_loc4`='高墙内的秘密远远超越了我们的想象。', `MaleText_loc5`='這些廳堂內所蘊藏的秘密遠遠超過我們最狂野的夢境。', `MaleText_loc7`='Estas salas contienen secretos que van más allá de nuestros sueños más alocados.' WHERE `ID`=33859;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여사제님들, 생존자들이 더 오고 있다는 소식을 전하고자 왔습니다. 아직 살아 있는 자들을 추려내고자 모든 조치를 다하고 있으니, 지원 병력을 보내주시기 바랍니다!', `FemaleText_loc4`='女祭司，我带来了消息，现在有更多的幸存者来到这里。他们正在竭尽全力寻找还活着的人。请尽量派遣人手来帮助我们！', `FemaleText_loc5`='女祭司，我是來通報有更多的生還者要來了。他們竭盡所能的過濾了那些還活著的人，請派遣任支援前去幫忙!', `FemaleText_loc7`='Sacerdotisas, traigo la noticia de que van a venir más supervivientes. Hacen lo que pueden por encontrar a los que siguen vivos. ¡Por favor, envien toda la ayuda que puedan!' WHERE `ID`=33860;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='알겠소. 해안으로 돌아가 생존자들을 데려오는 일을 도우시오.', `FemaleText_loc4`='明白了，哨兵，回到海滩上，帮助他们将还活着的人救回来。', `FemaleText_loc5`='瞭解了，哨兵。回到海灘幫助他們將生還者帶回來。', `FemaleText_loc7`='Entendido, centinela. Vuelve a la playa y ayúdales a traer a todo aquel que quede con vida.' WHERE `ID`=33861;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다친 자들이 도착하면, 우리가 저들의 회복을 돕는 동안 여관에 묵게 할 예정이에요. 돌아오면 여관에서 저흴 찾아 주세요.', `FemaleText_loc4`='当伤员到达时，我们要将他们安置在旅店里，照料他们。你回来的时候，就请去那里找我们吧。', `FemaleText_loc5`='當傷者抵達，我們會把他們安置在旅店進行治療。你回來時可以到那找到我們。', `FemaleText_loc7`='Cuando lleguen los heridos, los alojaremos en la posada mientras velamos por su recuperación. Ve a vernos allí cuando vuelvas, por favor.' WHERE `ID`=33862;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='알겠습니다, 여사제님.', `FemaleText_loc4`='当然，女祭司。', `FemaleText_loc5`='沒問題，女祭司。', `FemaleText_loc7`='Por supuesto, sacerdotisa.' WHERE `ID`=33863;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='콜로간이 바위 손아귀를 시전합니다!', `MaleText_loc4`='科隆加恩施放了岩石之握！', `MaleText_loc5`='柯洛剛恩施展了堅石之握!', `MaleText_loc7`='¡Kologarn lanza el hechizo Agarre pétreo!' WHERE `ID`=33864;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 용사와 싸울 준비가 되셨습니까?', `MaleText_loc4`='你做好与冠军作战的准备了吗？', `MaleText_loc5`='你確定要跟勇士進行戰鬥了嗎?', `MaleText_loc7`='¿Seguro que te has preparado para luchar contra un campeón?', `FemaleText_loc1`='정말 용사와 싸울 준비가 되셨나요?', `FemaleText_loc4`='你做好与冠军作战的准备了吗？', `FemaleText_loc5`='你確定要跟勇士進行戰鬥了嗎?', `FemaleText_loc7`='¿Seguro que te has preparado para luchar contra un campeón?' WHERE `ID`=33865;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용사와의 전투가 간단한 일이라고 생각한다면 현명하지 못할 겁니다. 준비가 되셨습니까?', `MaleText_loc4`='别以为你可以轻而易举地战胜一位冠军。你确定自己已经准备好了吗？', `MaleText_loc5`='認為跟一名勇士戰鬥只是小事一樁，這可是很不智的想法。你確定你準備好了嗎?', `MaleText_loc7`='No sería sensato asumir que pelear contra un campeón es tarea fácil. ¿Seguro que te has preparado?', `FemaleText_loc1`='용사와의 전투가 간단한 일이라고 생각한다면 현명하지 못할 겁니다. 준비가 되셨나요?', `FemaleText_loc4`='别以为你可以轻而易举地战胜一位冠军。你确定自己已经准备好了吗？', `FemaleText_loc5`='認為跟一名勇士戰鬥只是小事一樁，這可是很不智的想法。你確定你準備好了嗎?', `FemaleText_loc7`='No sería sensato asumir que pelear contra un campeón es tarea fácil. ¿Seguro que te has preparado?' WHERE `ID`=33866;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 저와 싸울 준비가 되셨습니까?', `MaleText_loc4`='你做好与我交战的准备了吗？', `MaleText_loc5`='你確定要跟我一戰?', `MaleText_loc7`='¿Seguro que estás en condiciones de pelear conmigo?', `FemaleText_loc1`='정말 저와 싸울 준비가 되셨나요?', `FemaleText_loc4`='你做好与我交战的准备了吗？', `FemaleText_loc5`='你確定要跟我一戰?', `FemaleText_loc7`='¿Seguro que estás en condiciones de pelear conmigo?' WHERE `ID`=33867;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 졌군요. 멋진 시합이었습니다!', `MaleText_loc4`='我认输。打得不错！', `MaleText_loc5`='我被打敗了。打得漂亮!', `MaleText_loc7`='He sido derrotado. ¡Buena pelea!', `FemaleText_loc1`='내가 졌군요. 멋진 시합이었어요!', `FemaleText_loc4`='我认输。打得不错！', `FemaleText_loc5`='我被打敗了。打得漂亮!', `FemaleText_loc7`='He sido derrotada. ¡Buena pelea!' WHERE `ID`=33868;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 윙윙 소리를 내며 위협적으로 경적을 울립니다.', `MaleText_loc4`='%s旋转着，发出可怕的“嘟嘟”声……', `MaleText_loc5`='%s邊飛邊瘋狂地發出了嗡嗡的聲音...', `MaleText_loc7`='%s da vueltas y emite pitidos de forma amenazadora...' WHERE `ID`=33869;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연습이 더 필요한 것 같군요. 아마 다음번에는 이길 수 있을 겁니다.', `MaleText_loc4`='看来你还需要多加练习。我们还是下次再打吧。', `MaleText_loc5`='看來你還需要更多練習。也許下次吧。', `MaleText_loc7`='Parece que todavía necesitas practicar más. Quizás otra vez.', `FemaleText_loc1`='연습이 더 필요한 것 같군요. 아마 다음번에는 이길 수 있을 겁니다.', `FemaleText_loc4`='看来你还需要多加练习。我们还是下次再打吧。', `FemaleText_loc5`='看來你還需要更多練習。也許下次吧。', `FemaleText_loc7`='Parece que todavía necesitas practicar más. Quizás otra vez.' WHERE `ID`=33870;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 끝인 줄 알아라!', `MaleText_loc4`='结束这一切吧！', `MaleText_loc5`='讓這一切結束吧!', `MaleText_loc7`='¡QUE SE ACABE!' WHERE `ID`=33871;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감시자 프레이야 상태 분석을 시작합니다.', `MaleText_loc4`='开始分析守护者弗蕾亚的状态。', `MaleText_loc5`='開始進行看守者芙蕾雅狀態分析。', `MaleText_loc7`='Comenzando el análisis del vigía Freya.' WHERE `ID`=33872;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감시자의 힘은 하인 중 세 장로에 의해 증대됩니다.', `MaleText_loc4`='古树仆从的存在增强了守护者的力量。', `MaleText_loc5`='看守者的力量會隨著長者僕從的在場而獲得強化。', `MaleText_loc7`='Poderes aumentados por la presencia de siervos ancestrales.' WHERE `ID`=33873;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장로 밝은잎 강화력 분석 중... 태양 광선을 증폭하여 지속적인 광역 방어 효과를 강화합니다.', `MaleText_loc4`='正在分析明叶长老的强化效果……太阳能增效提供了永久的区域性防护力增强。', `MaleText_loc5`='分析亮葉長者的強化...宿存區域的防禦力量因太陽光而增幅。', `MaleText_loc7`='Analizando mejoras del Ancestro Hojaluminosa... Defensas de área persistentes por amplificación solar.' WHERE `ID`=33874;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장로 돌나무껍질은 마법 사용을 방해하는 음파 효과로 방어에 기여합니다.', `MaleText_loc4`='石树长老的分析结果表明，他的声波防御能力足以干扰魔法的使用。', `MaleText_loc5`='石木長者的分析顯示有一種音波防禦將會干擾魔法的施放。', `MaleText_loc7`='El Ancestro Cortezapiedra posee una defensa sónica que altera el uso de magia.' WHERE `ID`=33875;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장로 무쇠줄기 조사 결과, 식물체에 기인한 이동 불가 효과가 관찰되었습니다.', `MaleText_loc4`='铁枝长老的扫描结果显示，存在基于植物功能的移动阻碍机制。', `MaleText_loc5`='鐵枝長者的掃瞄發現植物型定身機制。', `MaleText_loc7`='El escán del Ancestro Ramaférrea reveló mecanismos vegetales de inmovilización.' WHERE `ID`=33876;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='추가로, 장로들은 각각 프레이야의 주문 공격력, 물리 공격력, 소환수 능력의 증대와 연관되어 있음이 드러났습니다.', `MaleText_loc4`='另外，我的分析表明，每位古树长老的存在都令弗蕾亚的魔法能力、物理攻击或召唤能力得到增强。', `MaleText_loc5`='除此之外，我的分析發現每一位長者會分別使芙蕾雅的法術施展、物理與召喚能力有所加強。', `MaleText_loc7`='Además, según mi análisis, cada anciano incrementa las capacidades conjurales, físicas e invocacionales de Freya.' WHERE `ID`=33877;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세 장로를 처치하면 감시자 프레이야는 강화 효과를 상실합니다. 하지만, 프레이야 자신과 그녀의 소유물인 인장에도 영구적인 피해가 생길 가능성이 매우 큽니다.', `MaleText_loc4`='摧毁古树仆从可以导致守护者弗蕾亚失去这些增强效果。但是也极可能对弗蕾亚自身及其携带的物品，包括她的守护者徽记，造成永久性的伤害。', `MaleText_loc5`='摧毀長者僕從能夠使看守者芙蕾雅失去那些強化。然而卻極有可能會對芙蕾雅本人與其所有物造成永久的損傷，包括她的符印。', `MaleText_loc7`='La destrucción de los siervos causará una pérdida en las mejoras de Freya. No obstante, daño permanente en la persona y posesiones de Freya, incluyendo su sello: altamente probable.' WHERE `ID`=33878;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감시자 토림 상태 분석을 시작합니다.', `MaleText_loc4`='开始分析守护者托里姆的状态。', `MaleText_loc5`='開始進行看守者索林姆狀態分析。', `MaleText_loc7`='Comenzando el análisis del vigía Thorim.' WHERE `ID`=33880;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='토림의 죽은 배우자, 시프의 환영으로 위장하고 있는 외부 존재가 감지되었습니다.', `MaleText_loc4`='检测到外部影响。其存在方式是伪装成托里姆已故的配偶西芙。', `MaleText_loc5`='偵測到外在影響，以幻覺偽裝成索林姆死去的伴侶，希芙。', `MaleText_loc7`='Se detecta una influencia externa bajo el aspecto ilusorio de su compañero fallecido Sif.' WHERE `ID`=33881;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='환영이 일으킨 정신 간섭은 부분적인 기억 손상을 유발할 가능성이 매우 큽니다.', `MaleText_loc4`='这一外部影响所导致的心智干扰极可能触发局部的记忆损伤。', `MaleText_loc5`='來自該存在體的心靈干擾極有可能會引發局部的記憶損傷。', `MaleText_loc7`='Peligro inminente de daño parcial de memoria por la interferencia mental de esta presencia.' WHERE `ID`=33882;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감시자 호디르 상태 분석을 시작합니다.', `MaleText_loc4`='开始分析守护者霍迪尔的状态。', `MaleText_loc5`='開始進行看守者霍迪爾狀態分析。', `MaleText_loc7`='Comenzando el análisis del vigía Hodir.' WHERE `ID`=33883;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호디르의 인장은 유물 보관함 안에 있는 것으로 보입니다.', `MaleText_loc4`='霍迪尔的徽记被放在一只用来保存神器的宝箱中。', `MaleText_loc5`='霍迪爾的符印顯示藏在一個裝滿神器的箱子中。', `MaleText_loc7`='El sello de Hodir parece estar en un depósito de artefactos.' WHERE `ID`=33884;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감시자 호디르는 쉽게 흥분하고 불안정한 행동을 하므로, 전투가 길어지면 보관함을 파괴할 가능성이 매우 큽니다.', `MaleText_loc4`='守护者霍迪尔的情绪和行为极度不稳定。如果战斗时间过长，极可能导致宝箱损毁。', `MaleText_loc5`='看守者霍迪爾的性格與行為相當的不穩定。過長的戰鬥極有可能讓他毀去箱子。', `MaleText_loc7`='La personalidad de Hodir es altamente inestable. Destrucción del depósito durante un combate prolongado: altamente probable.' WHERE `ID`=33885;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해당 전장에 있는 동료는 전력 상승과 전투 시간 최소화에 기여할 것입니다.', `MaleText_loc4`='与盟军协同作战可以提高战斗力，使战斗时长降到最短。', `MaleText_loc5`='出現在戰場中的盟友將能夠提供協助並且盡可能縮短戰鬥時間。', `MaleText_loc7`='Los aliados presentes en el combate pueden proveer sinergias y minimizar la duración del mismo.' WHERE `ID`=33886;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감시자 미미론 상태 분석을 시작합니다.', `MaleText_loc4`='开始分析守护者米米尔隆的状态。', `MaleText_loc5`='開始進行看守者彌米倫狀態分析。', `MaleText_loc7`='Comenzando el análisis del vigía Mimiron.' WHERE `ID`=33887;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감시자 미미론의 인장은 창의성의 회랑 전체에 영향을 미치는 자폭 장치와 긴밀히 연결되어 있습니다.', `MaleText_loc4`='守护者米米尔隆的徽记与一套自毁系统相关联，该系统又与发明回廊的完整性相关联。', `MaleText_loc5`='看守者彌米倫的符印連結在一具自毀裝置上，並且連接著整個巧思迴廊。', `MaleText_loc7`='El sello de Mimiron está unido a un mecanismo de autodestrucción conectado a las Galerías del Ingenio. ' WHERE `ID`=33888;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자폭 가동 장치의 코드명은 "큰 적색 단추"로서, 미미론 자신의 발명품입니다.', `MaleText_loc4`='这套自毁系统的触发装置被称为“红色大按钮”，由米米尔隆自行制造。', `MaleText_loc5`='自毀裝置的觸發器被命名為「紅色大按鈕」，彌米倫親手製作的裝置。', `MaleText_loc7`='El nombre clave del disparador del mecanismo es "El botón rojo", creado por Mimiron.' WHERE `ID`=33889;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미미론의 인장을 회수하려면 자폭 장치 가동 후 폭발 전까지 미미론을 처치하십시오.', `MaleText_loc4`='要获取米米尔隆的徽记，必须初始化自毁程序，并在流程执行完毕之前击败它。', `MaleText_loc5`='要取得彌米倫的符印，必須要啟動自毀程序然後在其完成前將彌米倫打敗。', `MaleText_loc7`='Para obtener el sello de Mimiron, inicien la autodestrucción y venzan a Mimiron antes de que se complete.' WHERE `ID`=33890;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|Tinterface\\Icons\\Spell_Arcane_MindMastery.blp:24|t|cFFFF8900 이성을 12%% 상실했습니다.|r', `MaleText_loc4`='|TInterface\\Icons\\Spell_Arcane_MindMastery.blp:24|t|cFFFF8900 理智损失12%%|r', `MaleText_loc5`='|TInterface\\Icons\\Spell_Arcane_MindMastery.blp:24|t|cFFFF8900喪失12%%理智|r', `MaleText_loc7`='|TInterfaceIconsSpell_Arcane_MindMastery.blp:24|t|cFFFF8900 12%% de cordura perdida|r', `FemaleText_loc1`='|TInterface\\Icons\\Spell_Arcane_MindMastery.blp:24|t|cFFFF8900 이성을 12%% 상실했습니다.|r', `FemaleText_loc4`='|TInterface\\Icons\\Spell_Arcane_MindMastery.blp:24|t|cFFFF8900 理智损失12%%|r', `FemaleText_loc5`='|TInterface\\Icons\\Spell_Arcane_MindMastery.blp:24|t|cFFFF8900喪失12%%理智|r', `FemaleText_loc7`='|TInterfaceIconsSpell_Arcane_MindMastery.blp:24|t|cFFFF8900 12%% de cordura perdida|r' WHERE `ID`=33891;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흐음, $c... 그게 조금... 미묘하군.', `MaleText_loc4`='嗯，$c，这很……巧妙。', `MaleText_loc5`='嗯，$c，那是蠻...隱密的。', `MaleText_loc7`='Bueno, $c, eso ha sido... sutil.' WHERE `ID`=33892;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 할 일을 계속해야 하네.', `MaleText_loc4`='我必须继续履行我的职责，$c。', `MaleText_loc5`='我必須繼續工作了，$c。', `MaleText_loc7`='Debo volver a mis labores, $c.' WHERE `ID`=33893;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='접근이 거부되었습니다. 권한이 부족합니다.', `MaleText_loc4`='拒绝登录。权限级别不足。', `MaleText_loc5`='登入拒否。存取層級不足。', `MaleText_loc7`='Acceso negado. Permiso insuficiente.' WHERE `ID`=33894;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고대 기록관 접근을 허가합니다. 접근 제한 기능을 일시 중단합니다.', `MaleText_loc4`='已获得档案馆访问权限。入侵保护机制暂停。', `MaleText_loc5`='獲得大資料庫的存取許可。中止入侵防禦機制。', `MaleText_loc7`='Acceso al Archivum concedido. Mecanismo de protección suspendido.' WHERE `ID`=33895;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='질의를 시작합니다. 비상 안전장치 알갈론은 제1관리자 활동 정지 시 자동 실행되는 위급 신호입니다.', `MaleText_loc4`='正在初始化问询。奥尔加隆保险系统是一套在首席管理官死亡时触发的自动化紧急信号系统。', `MaleText_loc5`='查詢開始。艾爾加隆故障安全防護裝置是用於首席管理官死亡後的自動緊急警報器。', `MaleText_loc7`='Buscando. El Seguro Algalon es una señal de emergencia que se autoemite al morir un Primer Designado.' WHERE `ID`=33896;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇습니다. 제1관리자 로켄의 활동 정지 접수와 동시에 이 신호가 활성화됩니다.', `MaleText_loc4`='正确。首席管理官洛肯被毁灭与信号被激活的时间戳相符。', `MaleText_loc5`='正確。首席管理官洛肯毀滅時的時間標記被認定為警報器的啟動點。', `MaleText_loc7`='Afirmativo. La fecha de destrucción del Primer Designado Loken coincide con la de la señal. ' WHERE `ID`=33897;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검색 중... 제1관리자 활동 정지는 행성 시스템의 오류를 알리는 첫 번째 신호로 간주됩니다. 이에 따라 관찰자 알갈론의 실체가 도착하여 행성 진단을 실행합니다. 도출될 수 있는 응답 신호는 두 가지로서, 응답 코드 알파는 "모두 정상" 신호, 응답 코드 오메가는 행성 재창조 신호입니다.', `MaleText_loc4`='正在搜索……首席管理官的毁灭被判定为系统级行星故障的第一道报警信息。观察者奥尔加隆抵达之后所展开的行星分析，可能产生两种回复代码中的一种。回复代码阿尔法代表“一切正常”；回复代码欧米迦代表“行星结构重组”。', `MaleText_loc5`='搜尋中...首席管理官的毀滅被認定為行星系統失控的第一道警訊。艾爾加隆觀察者的實體抵達後將展開行星判別，結果可能有兩種。回覆代碼Α，表示「情況良好」;回覆代碼Ω，表示行星需要重啟。', `MaleText_loc7`='Buscando... La destrucción del Primer Designado se considera la primera señal de fallo planetario sistémico. Tras su llegada, Algalon Observador realiza un diagnóstico planetario con dos posibles señales de respuesta. Respuesta Alfa: "Todo está bien" y Respuesta Omega: reoriginación planetaria. ' WHERE `ID`=33898;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='행성과 생명체를 해체해 금속, 암석, 기체 등의 기본적인 요소로 되돌리는 작업을 뜻합니다. 이후에, 각 요소를 초기 행성 청사진에 맞게 재구성하는 절차가 뒤따릅니다.', `MaleText_loc4`='行星自身与其所承载的生命体将解离为基础元素：金属、岩石和气体。随后，这些元素将按照最初的行星蓝图完成重组。', `MaleText_loc5`='將星球與其生命有機體分解為基本元素:金屬、岩石與氣體。之後將會經歷一段重建期，讓所有元素能重歸原始的行星藍圖。', `MaleText_loc7`='Descomposición del planeta y sus organismos en elementos básicos: metales, rocas, gases; seguido por un período de reconstitución de los elementos según el diseño planetario original.' WHERE `ID`=33899;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요청이 거부되었습니다. 응답 코드는 알갈론의 실체 안에 구성됩니다. 그는 전령이자 전갈 자체입니다.', `MaleText_loc4`='请求被拒绝。回复代码内建于奥尔加隆的躯体中。他既是信使，也是信号本身。', `MaleText_loc5`='要求拒否。回覆代碼內建於艾爾加隆觀察者實體中。他既是使者也是訊息本身。', `MaleText_loc7`='Orden negada. Respuestas incorporadas en Algaon, observador. Él es mensajero y mensaje.' WHERE `ID`=33900;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알갈론은 고대 신이 행성 중추 기능에 미친 시스템 손상 수준을 평가해 진단을 내립니다. 응답 코드 오메가를 도출할 확률은...', `MaleText_loc4`='奥尔加隆检测到了侵入关键行星功能的系统级上古之神污染。正在计算产生欧米迦回复代码的几率……', `MaleText_loc5`='艾爾加隆的判別會評估古神腐化對行星系統生命運作的危險性。計算回覆代碼Ω的機率...', `MaleText_loc7`='Algalon calcula el peligro de corrupción sistémica de Dios antiguo en las funciones vitales del planeta. Probabilidad de Respuesta Omega…' WHERE `ID`=33901;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='99.99 퍼센트입니다.', `MaleText_loc4`='百分之九十九点九九。', `MaleText_loc5`='機率為百分之九十九點九九。', `MaleText_loc7`='Noventa y nueve coma nueve, nueve porciento.' WHERE `ID`=33902;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론 순환소수입니다.', `MaleText_loc4`='小数点后无限循环。', `MaleText_loc5`='小數點要無限循環。', `MaleText_loc7`='Se repite, por supuesto.' WHERE `ID`=33903;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와... 이런 걸 바로 끝내주는 발견이라고 하죠!', `MaleText_loc4`='看哪，这就是我们所说的重大发现！', `MaleText_loc5`='啊哈，這才是我說的大發現!', `MaleText_loc7`='¡A esto le llamo un hallazgo!' WHERE `ID`=33904;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 권한을 보여주지, 이 망할 기계야. 자, 여기 노르간논의 쐐기돌이다!', `MaleText_loc4`='我叫你看看我的权限，你这烂机器。瞧好了：诺甘农的钥匙！', `MaleText_loc5`='我會給你存取許可，你這個爛機器。又登場啦:諾甘農之鑰!', `MaleText_loc7`='Vas a ver acceso, máquina infeliz. Aquí está otra vez: ¡la llave de Norgannon!' WHERE `ID`=33905;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 전에 발견한 티탄의 다른 기록관과 비슷하군요. 음... 더 낡았고... 더 크다는 점만 빼면요.', `MaleText_loc4`='看起来跟我们找到的其它泰坦档案库也没什么不同嘛，只不过旧了点……大了点。', `MaleText_loc5`='看起來就跟我和那些小夥子先前發現的泰坦資料庫差不多...只是更古老...更巨大。', `MaleText_loc7`='Es como los otros archivos titánicos que encontramos... Aunque más viejo... Y más grande.' WHERE `ID`=33906;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐, 이건 뭔가 안 좋아 보이는데! 이 깜빡이는 불빛 옆에, 알갈론이라는 신호는 뭐냐?', `MaleText_loc4`='且慢。不对啊！这个一闪一闪的信号灯……奥尔加隆是啥玩意？', `MaleText_loc5`='等等:這看起來不太對勁!那個閃光旁邊的...那這個艾爾加隆警示器又是什麼玩意兒?', `MaleText_loc7`='Un segundo: ¡esto no está bien! Al lado de esta luz... ¿Qué es esta señal de Algalon?' WHERE `ID`=33907;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제1관리자? 어디서 들은 말이지... 아! 우리 할아버지의 수염을 걸지! 로켄이 아제로스의 제1관리자야! 로켄이 죽어서 이렇게 된 거라고!', `MaleText_loc4`='首席管理官？我在哪里听过这名字来着？对了！洛肯就是艾泽拉斯的首席管理官啊。洛肯的死亡触发了这东西？', `MaleText_loc5`='首席管理官?我怎麼在哪裡聽過的感覺?我祖父的鬍子啊，洛肯就是艾澤拉斯的首席管理官。洛肯的死觸發那個東西!', `MaleText_loc7`='¿Primer Designado? ¿De dónde me suena? Por las barbas de mi abuelo, Loken es el Primer Designado de Azeroth. ¡La muerte de Loken activó esto!' WHERE `ID`=33908;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐? 신호를 받는 쪽이 누구지? 그리고 무슨 일이 벌어지나?', `MaleText_loc4`='然后呢？谁在监听这个信号？会发生什么事情吗？', `MaleText_loc5`='嗯?誰在另一邊接收警報?接下來會發生什麼事?', `MaleText_loc7`='¿Y? ¿Quién está recibiendo la señal? ¿Qué va a pasar?' WHERE `ID`=33909;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='행성 재창조가 뭐야? 알아듣게 말해라, 구닥다리 기계야!', `MaleText_loc4`='行星结构重组？把话说明白点，你这破烂！', `MaleText_loc5`='行星「重」啟?講白話一點，你這個該死機器!', `MaleText_loc7`='¿Reoriginación planetaria? ¡Sé clara, maldita máquina!' WHERE `ID`=33910;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='들었어요, 여러분? 세상이 그냥 끝난대요! 뭐 하는 거야, 이 고물 기계야? 응답 코드 ''알파''를 보내. 다 정상이야! 내가 한잔 살게!', `MaleText_loc4`='听到了吗，伙计们？我们的世界要完蛋了！你还等什么啊，破烂机器？快发送回复代码阿尔法。一切正常！尽在掌握中！', `MaleText_loc5`='聽到了嗎，小鬼?不過是世界末日嘛!還等什麼，你這生鏽的鐵罐頭?回覆代碼Α，表示情況良好!我請你喝酒!', `MaleText_loc7`='¿Oyen eso, amigos? ¡Es sólo el fin del mundo! ¿Y qué esperas, lata oxidada? Inicia la Respuesta Alfa. ¡Todo está bien! ¡Yo invito las cervezas!' WHERE `ID`=33911;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 알갈론은 어떤 식으로 진단 결과를 내지? 우린 희망이 없는 거냐?', `MaleText_loc4`='啊，这个奥尔加隆分析出了什么结果来？我们有多大的几率不被毁灭？', `MaleText_loc5`='好吧，艾爾加隆會從分析中作出什麼判斷?我們有多少機會?', `MaleText_loc7`='¿Y qué va a estar buscando en su diagnóstico Algalon? ¿Qué chances tenemos?' WHERE `ID`=33912;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='큰일 났네요. 우리 곧 싸워야 할 것 같습니다.', `MaleText_loc4`='真要命啊，伙计们。看来我们有一场硬仗要打了。', `MaleText_loc5`='該死的混蛋，小夥子。看來我們得打上一架了。', `MaleText_loc7`='¡Diablos! Parece que tenemos otra pelea por delante.' WHERE `ID`=33913;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='끙끙거리는 중', `FemaleText_loc4`='举起', `FemaleText_loc5`='舉起', `FemaleText_loc7`='Alzando' WHERE `ID`=33914;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수천의 죽음...', `MaleText_loc4`='被无情地杀戮……', `MaleText_loc5`='你要生靈塗炭...', `MaleText_loc7`='Mil muertes…' WHERE `ID`=33915;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혹은, 하나의 살인.', `MaleText_loc4`='或者杀戮别人。', `MaleText_loc5`='或是成為一名兇手。', `MaleText_loc7`='O un asesinato.' WHERE `ID`=33916;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전쟁의 피', `MaleText_loc4`='战争之血', `MaleText_loc5`='戰爭之血', `MaleText_loc7`='Sangre de guerra', `FemaleText_loc1`='전쟁의 피', `FemaleText_loc4`='战争之血', `FemaleText_loc5`='戰爭之血', `FemaleText_loc7`='Sangre de guerra' WHERE `ID`=33917;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 변위 장치는 정상적으로 작동하고 있는 듯합니다.', `MaleText_loc4`='位移石板被激活并稳定下来了。', `MaleText_loc5`='位移平台處於可啟用的穩定狀態。', `MaleText_loc7`='La plataforma de desplazamiento parece estar activa y estable.', `FemaleText_loc1`='이 변위 장치는 정상적으로 작동하고 있는 듯합니다.', `FemaleText_loc4`='位移石板被激活并稳定下来了。', `FemaleText_loc5`='位移平台處於可啟用的穩定狀態。', `FemaleText_loc7`='La plataforma de desplazamiento parece estar activa y estable.' WHERE `ID`=33918;
