UPDATE `locales_broadcast_text` SET `MaleText_loc1`='광기의 내리막길로 순간이동', `MaleText_loc4`='传送到疯狂阶梯。', `MaleText_loc5`='傳送至驟狂斜廊。', `MaleText_loc7`='Teletransporte a El Descenso a la Locura.', `FemaleText_loc1`='광기의 내리막길로 순간이동', `FemaleText_loc4`='传送到疯狂阶梯。', `FemaleText_loc5`='傳送至驟狂斜廊。', `FemaleText_loc7`='Teletransporte a El Descenso a la Locura.' WHERE `ID`=33928;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='은빛십자군을 대표해서, 은빛십자군 마상시합에 오신 그대를 환영해요.', `FemaleText_loc4`='我谨代表银色北伐军，欢迎你参加银色锦标赛。', `FemaleText_loc5`='謹代表銀白十字軍，在此歡迎各位來到銀白聯賽。', `FemaleText_loc7`='En nombre de la Cruzada Argenta, te doy la bienvenida al Torneo Argenta.' WHERE `ID`=33929;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무도 블라스트볼트 형제보다 더 빨리, 더 싸게, 더 멋있게 못 만들지!', `MaleText_loc4`='布拉斯波兄弟的建筑工程是速度最快，造价最低、质量最上乘的！', `MaleText_loc5`='沒人能比爆栓兄弟蓋得更快、更便宜，蓋得更棒!', `MaleText_loc7`='¡Nadie construye más deprisa, más barato y mejor que los hermanos Cargarrayo!' WHERE `ID`=33930;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 완전히 땅에 내려앉았습니다!', `MaleText_loc4`='%s被永久地禁锢在地面上！', `MaleText_loc5`='%s再也飛不動了!', `MaleText_loc7`='¡%s ha aterrizado permanentemente!', `FemaleText_loc1`='%s|1이;가; 완전히 땅에 내려앉았습니다!', `FemaleText_loc4`='%s被永久地禁锢在地面上！', `FemaleText_loc5`='%s再也飛不動了!', `FemaleText_loc7`='¡%s ha aterrizado permanentemente!' WHERE `ID`=33931;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새로운 명령이다! 별자리 투영관 입구를 냉큼 열어라.', `MaleText_loc4`='新的指令！打开天文馆的大门。', `MaleText_loc5`='新的命令!打開通往星穹渾天儀的入口。', `MaleText_loc7`='¡Nueva orden! Abre la entrada del Planetario Celestial.' WHERE `ID`=33932;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 감시자? 인장? 나랑 수수께끼 놀이하자는 거냐, 이 괘씸한 기계야!', `MaleText_loc4`='四位守护者？徽记？你这废铜烂铁，说话能不能别这么拐弯抹角啊？', `MaleText_loc5`='四位看守者?符印?拜託你講話可不可以別像打啞謎，該死的機器?', `MaleText_loc7`='¿Cuatro vigías? ¿Sellos? ¿Puedes ser menos críptica, condenada máquina?' WHERE `ID`=33933;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 인장은 어떻게 구하란 말이냐? 감시자한테 가서 좀 달라 그럴까?', `MaleText_loc4`='那我们怎样才能搞到他们的徽记啊？走过去跟他们好声好气地借吗？', `MaleText_loc5`='那我們要如何取得那些符印?難不成走上前，跟他們套交情嗎?', `MaleText_loc7`='¿Y cómo los obtenemos? ¿Vamos y les pedimos si por favor nos los dan?' WHERE `ID`=33934;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 손상을 되돌리는 방법을 얘기해 주겠군, 그렇지?', `MaleText_loc4`='那你倒是告诉我们怎样才能解除这种威胁啊？', `MaleText_loc5`='你是不是要告訴我們如何...「避免」符印受到威脅?', `MaleText_loc7`='Y tú vas a decirnos cómo "descomprometer" los sellos, ¿no?' WHERE `ID`=33935;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수년 동안 티탄의 전당에서 활보할 순간만을 꿈꿨는데, 티탄의 창조물 때문에 위험해질 줄이야...', `MaleText_loc4`='多少年来，我做梦都想在泰坦之城游览。没想到今天居然要跟他们创造的东西作战。', `MaleText_loc5`='多年來我一直夢想著在泰坦的殿堂中漫步。不過，我還真沒想到我最後得對抗他們的造物。', `MaleText_loc7`='Siempre soñé con andar por los salones de los titanes. Nunca creí que enfrentaría a sus creaciones.' WHERE `ID`=33936;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요청이 거부되었습니다. 네 감시자의 인장을 수동으로 확인하는 과정이 필요합니다.', `MaleText_loc4`='请求被拒绝。需要四位守护者的徽记进行权限确认。', `MaleText_loc5`='要求拒否。需要四名看守者的符印認可才能存取。', `MaleText_loc7`='Orden negada. El acceso requiere los sellos de los cuatro vigías.' WHERE `ID`=33937;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='울두아르의 네 감시자는 프레이야, 토림, 호디르, 미미론입니다. 인장은 그들의 육체와 정신에 긴밀하게 연결되어 있습니다. 별자리 투영관에 접근하려면 네 개의 인장이 모두 필요합니다.', `MaleText_loc4`='奥杜尔的四位守护者是：弗蕾亚、托里姆、霍迪尔和米米尔隆。他们的徽记与其本体及心智的完整性密切相关。要进入天文台，就必须拥有全部四枚徽记。', `MaleText_loc5`='奧杜亞的四位看守者:芙蕾雅、索林姆、霍迪爾與彌米倫。這些符印與他們的身體和心靈緊緊相連。四個符印需要全數到齊，才能進入星穹渾天儀。', `MaleText_loc7`='Los cuatro vigías de Ulduar: Freya, Thorim, Hodir y Mimiron. Los sellos están en sus integridades físicas y mentales. Se necesitan los cuatro para acceder al Planetario Celestial.' WHERE `ID`=33938;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감시자 상태를 분석합니다. 대기하십시오.', `MaleText_loc4`='正在分析守护者的状态。请稍候。', `MaleText_loc5`='分析看守者狀態。請稍等。', `MaleText_loc7`='Analizando vigías. Espere un momento.' WHERE `ID`=33939;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='손상이 발견되었습니다. 외부 존재가 감시자를 장악하고 있습니다. 인장이 손상되었습니다.', `MaleText_loc4`='检测到腐蚀。外部影响已经控制了守护者。徽记受到威胁。', `MaleText_loc5`='發現腐化。外在影響控制了看守者。符印受到了威脅。', `MaleText_loc7`='Corrupción encontrada. Influencia externa invadiendo a los vigías. Sellos comprometidos.' WHERE `ID`=33940;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무력을 충분히 행사하면 감시자 기능이 초기화되어 외부 존재의 영향을 제거할 수 있습니다.', `MaleText_loc4`='足够的冲击力可以使守护者重启动，消除外部影响。', `MaleText_loc5`='適當地運用外力將可以使看守者重置其運作，移除外在影響。', `MaleText_loc7`='Las funciones de los vigías pueden reiniciarse a la fuerza, eliminando la influencia exterior.' WHERE `ID`=33941;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 과정에서 인장을 위험으로부터 보호하는 방법에 대해서는, 각 감시자의 상태를 분석한 계산 결과를 참고하십시오.', `MaleText_loc4`='为了在这一过程中不对徽记造成损伤，我可以分析每位守护者的状态，并根据计算结果给出具体建议。', `MaleText_loc5`='為了在過程中避免危及符印，我可以分析每一位看守者的狀態，在計算完成後讓你得知這些資料。', `MaleText_loc7`='Para evitar que dañen los sellos en el proceso, puedo analizar el estado de cada vigía y facilitarles la información al completarse los cálculos.' WHERE `ID`=33942;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 나무를 베어가는 이를 공격합니다.', `MaleText_loc4`='一个%s开始攻击伐树者。', `MaleText_loc5`='%s攻擊毀樹者。', `MaleText_loc7`='Un %s ataca al matador de árboles' WHERE `ID`=33943;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼이 수정노래 떡갈나무의 복수를 하러 나타납니다!', `MaleText_loc4`='一个灵魂现身了，它要为晶歌森林橡树复仇！', `MaleText_loc5`='樹靈現身替水晶之歌橡木復仇!', `MaleText_loc7`='¡Aparece un espíritu para vengar al roble Canto de Cristal!' WHERE `ID`=33944;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 죽어가는 수정노래 떡갈나무에서 나타납니다!', `MaleText_loc4`='一个%s从濒死的晶歌森林橡树中现身了！', `MaleText_loc5`='%s從倒下的水晶之歌橡木中現身!', `MaleText_loc7`='¡Un %s emerge del roble Canto de Cristal moribundo!' WHERE `ID`=33945;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고대 울두아르 탐험에서 브란 님을 보조하다니, 참으로 영광스러운 일입니다.', `MaleText_loc4`='能协助布莱恩探索泰坦古城奥杜尔的秘密真是莫大的荣幸。', `MaleText_loc5`='能夠協助布萊恩探索上古的奧杜亞真是莫大的光榮。', `MaleText_loc7`='Es un auténtico honor poder ayudar a Brann a explorar el antiguo Ulduar.' WHERE `ID`=33946;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탐험에 대한 제 지식은 전부 브란 님께 배운 거죠.', `MaleText_loc4`='我所知道的关于探险的知识，都是布莱恩教给我的。', `MaleText_loc5`='所有我知道的探險技巧都是布萊恩教的。', `MaleText_loc7`='Brann me enseñó todo lo que sé sobre explorar.', `FemaleText_loc1`='탐험에 대한 제 지식은 전부 브란 님께 배운 거죠.', `FemaleText_loc4`='我所知道的关于探险的知识，都是布莱恩教给我的。', `FemaleText_loc5`='所有我知道的探險技巧都是布萊恩教的。', `FemaleText_loc7`='Brann me enseñó todo lo que sé sobre explorar.' WHERE `ID`=33947;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무기를 거둬라! 내가 졌다!', `MaleText_loc4`='住手！我认输了！', `MaleText_loc5`='住手!我認輸了!', `MaleText_loc7`='¡Depongan las armas! ¡Ríndanse!' WHERE `ID`=33948;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악몽에서 막 깨어난 것만 같구나. 하지만 아직 어둠이 채 가시지 않았다.', `MaleText_loc4`='我觉得自己像是从一场噩梦中惊醒过来，但是这里的阴影仍然挥之不去。', `MaleText_loc5`='我感覺好像剛從一場夢魘之中醒來，但此地的陰影卻仍揮之不去。', `MaleText_loc7`='Siento como si hubiera despertado de una pesadilla, pero las sombras de este lugar siguen merodeando.' WHERE `ID`=33949;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시프... 시프가 여기 있었나? 아니... 그녀는 내 형제의 손에 죽었다. 참으로 끔찍한 악몽이었지...', `MaleText_loc4`='西芙……西芙在这里吗？不可能——她被我的兄弟杀死了。一场黑暗的噩梦……', `MaleText_loc5`='希芙...剛才希芙在這嗎?不可能--她早已死於吾兄之手。這確實是我心中最晦暗的夢魘...', `MaleText_loc7`='Sif... ¿Sif estuvo aquí? Imposible... Murió en brazos de mi hermano. Una oscura pesadilla seguramente…' WHERE `ID`=33950;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생각할 시간이 필요하다... 원한다면, 너희의 임무에 힘을 빌려주겠다. 그만큼은 빚을 졌지. 잘 가라.', `MaleText_loc4`='我需要一些时间仔细思考……如果你们需要我的帮助，请尽管开口。这是我欠你们的人情。保重。', `MaleText_loc5`='我需要一點時間回神...如果你需要的話，我將會協助你。至少這是我所能盡的棉薄之力。再會了。', `MaleText_loc7`='Necesito tiempo para reflexionar... Te ayudaré en tu causa si te hiciera falta. Es lo mínimo que puedo hacer. Adiós.' WHERE `ID`=33951;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이놈! 넌 내 사랑이 아니야! 물러가라, 마귀여!', `MaleText_loc4`='你！你这个恶魔，你不是我的爱人！滚开！', `MaleText_loc5`='你!你這個惡魔!你不是我的摯愛!給我滾開!', `MaleText_loc7`='¡Tú! ¡Villano, tú no eres mi amada! ¡Fuera de aquí!' WHERE `ID`=33952;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='울두아르를 덮친 모든 사악함 뒤에는 보이지 않는 손이 있었다. 놈이 내 왕국을 폐허로 만들고, 내 형제를 망치고, 내 아내를 죽였지.', `MaleText_loc4`='看吧，这隐藏在一切罪恶幕后的黑手，它覆灭了奥杜尔，将我的王国夷为废墟，腐蚀了我的兄弟，杀害了我的妻子。', `MaleText_loc5`='這就是令奧杜亞淪為邪惡之都，使我的王國變成廢墟，令我兄長墮落，以及殺死我愛妻的始作俑者。', `MaleText_loc7`='Contempla la mano detrás de todo el mal que ha castigado a Ulduar, ha dejado mi reino en ruinas, corrompido a mi hermano y asesinado a mi esposa.' WHERE `ID`=33953;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 너희 몫이다, 용사들이여. 우리 모두를 대신해 복수해다오! 너희 앞에 어려운 임무가 놓여 있지만, 내가 최대한 너희를 돕겠노라. 너희는, 승리해야만 한다!', `MaleText_loc4`='现在，为我们复仇的重任落到了你们的肩膀上，勇士们。前方的路途依然无比艰险，但我会鼎力相助。你们必须取得胜利。', `MaleText_loc5`='現在替我們復仇的責任落在你的肩上了，勇士們。這是個艱鉅的任務，但我會盡可能的協助你。你必須克敵制勝。', `MaleText_loc7`='Y ahora depende de ustedes, campeones, vengarnos a todos. La tarea ante ustedes es inmensa, pero les ayudaré como me sea posible. Deben prevalecer.' WHERE `ID`=33954;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\Spell_Arcane_MindMastery.blp:24|t|cFFFF8900 이성을 100%% 상실했습니다.|r', `MaleText_loc4`='|TInterface\\Icons\\Spell_Arcane_MindMastery.blp:24|t|cFFFF8900 理智损失100%%|r', `MaleText_loc5`='|TInterface\\Icons\\Spell_Arcane_MindMastery.blp:24|t|cFFFF8900喪失100%%理智|r', `MaleText_loc7`='|TInterfaceIconsSpell_Arcane_MindMastery.blp:24|t|cFFFF8900 100%% de cordura perdida|r', `FemaleText_loc1`='|TInterface\\Icons\\Spell_Arcane_MindMastery.blp:24|t|cFFFF8900 이성을 100%% 상실했습니다.|r', `FemaleText_loc4`='|TInterface\\Icons\\Spell_Arcane_MindMastery.blp:24|t|cFFFF8900 理智损失100%%|r', `FemaleText_loc5`='|TInterface\\Icons\\Spell_Arcane_MindMastery.blp:24|t|cFFFF8900 100%% Sanity Lost|r', `FemaleText_loc7`='|TInterfaceIconsSpell_Arcane_MindMastery.blp:24|t|cFFFF8900 100%% de cordura perdida|r' WHERE `ID`=33955;
