UPDATE `locales_broadcast_text` SET `MaleText_loc1`='만나서 반갑습니다, $c님.$B$B저는 지원자들에게 마상 근접전 기술을 가르칩니다.', `MaleText_loc4`='$c，很高兴见到你。$B$B我负责向候选者传授骑乘近身战的诀窍。', `MaleText_loc5`='你好，$c。$B$B我負責訓練志士的騎乘近距戰鬥技藝。', `MaleText_loc7`='Encantado, $c.$b$bEntreno a los Aspirantes en el arte del combate con montura.' WHERE `ID`=33963;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='근접 표적으로 어떻게 훈련해야 하는지 보여주십시오.', `MaleText_loc4`='教我如何与近战目标作战吧。', `MaleText_loc5`='教我如何用近戰標靶訓練。', `MaleText_loc7`='Muéstrame cómo entrenarme con un objetivo cuerpo a cuerpo.', `FemaleText_loc1`='근접 표적으로 어떻게 훈련해야 하는지 보여주세요.', `FemaleText_loc4`='教我如何与近战目标作战吧。', `FemaleText_loc5`='教我如何用近戰標靶訓練。', `FemaleText_loc7`='Muéstrame cómo entrenarme con un objetivo cuerpo a cuerpo.' WHERE `ID`=33964;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐야, 이 조그만...$b$b아, 이런... 뭐 도와줄 거라도 있나?', `MaleText_loc4`='这是什么，小凡人……$b$b嗯……是$r？我能为你做些什么？', `MaleText_loc5`='幹什麼，弱小的凡.。$b$b呃...嗯，$r?我能為你做什麼?', `MaleText_loc7`='¿Qué ocurre, débil mort...$b$BEh... ¿Sí, $r? ¿Qué puedo hacer por ti?' WHERE `ID`=33965;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예비 시험은 이걸로 끝이다. 자, 이제부터가 진짜라고!', `MaleText_loc4`='初步测试阶段完成。真正的测试开始啦！', `MaleText_loc5`='初步測試階段完成。現在要玩真的啦!', `MaleText_loc7`='Fase de prueba preliminar completa. ¡Ahora empieza la verdadera prueba!' WHERE `ID`=33966;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일인가?', `MaleText_loc4`='$c？这是什么？', `MaleText_loc5`='是，$c?怎麼了?', `MaleText_loc7`='¿Sí, $c? ¿Qué ocurre?' WHERE `ID`=33967;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='근접 표적으로 지원자들은 마상 공격과 방어 둘 다 훈련할 수 있습니다.$B$B근접 표적에 가까이 다가가서 찌르기 공격을 하십시오. 강타한 힘 때문에 표적이 강하게 회전하여 당신이나 탈것이 다칠 수도 있습니다. 방어가 작동을 하는 시점이 바로 여기입니다.$B$B표적을 공격하기 전에 방어를 적어도 한 단계 쌓았는지 확인한 다음 훈련 연습을 하는 동안 계속해서 방어를 새로 하면서 계속 쌓아야 합니다. 그렇지 않으면, 탈것에서 떨어지니까요.$B$B실제 마상 전투에서도 마찬가지입니다. 온 힘을 다해 공격과 방어의 절묘한 조화를 이루고, 기회가 올 때마다 찌르기 공격을 하며 방어 단계를 유지해야 합니다.', `MaleText_loc4`='近战目标可以帮助候选者训练骑乘攻击与防御的技巧。$B$B你需要靠近并刺击近战目标。刺击的力量通常会令目标旋转起来，对你或你的坐骑造成伤害。因此，你需要巧妙地利用防御技能。$B$B在攻击目标之前，最好确保自己至少有一层防御效果。在接下来的战斗中，你还需要尽可能地堆叠并刷新防御效果。否则，你很快就会被打下坐骑。$B$B在骑乘实战中遵循着同样的原则：在攻击与防御之间寻求平衡，一有机会就发动刺击，并尽可能保持多层防御效果。', `MaleText_loc5`='近戰標靶能在騎乘戰鬥與防禦兩方面協助志士進行訓練。$B$B靠近近戰標靶並且對它使用戳刺攻擊。這樣攻擊的力道通常會使標靶快速旋轉對你或你的坐騎造成傷害。這時你的防禦就派上用場了。$B$B記得在你攻擊標靶前，確保你有至少一層的防禦，並且在整個練習過程中持續地堆疊與重整你的防禦。否則，你很快就發現自己被擊下坐騎。$B$B這一點與實際的騎乘戰鬥無異:在攻擊與防禦間取得平衡，每當有機會時就使用戳刺，然後盡可能地維持你的防禦層數。', `MaleText_loc7`='Los objetivos cuerpo a cuerpo entrenan a los aspirantes tanto en el ataque como en la defensa sobre montura.$b$bAcércate al objetivo cuerpo a cuerpo y golpéalo con un ataque de Estocada. La fuerza del golpe a menudo hace que el objetivo gire sobre sí mismo con suficiente fuerza para herirte a ti o a tu montura. Ahí es donde entra en juego la defensa.$b$bAsegúrate de tener al menos una capa de Defender antes de atacar al objetivo, y continúa acumulando y renovando Defender durante el ejercicio de entrenamiento.$b$bLo mismo sucede en el verdadero combate sobre montura: Mantén un balance entre defensa y ataque, lanzando Estocada cuando tengas la oportunidad y manteniendo tus capas de Defender lo mejor que puedas.' WHERE `ID`=33968;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='만나서 반갑네.$b$b모든 일이 계획대로 돼가고 있겠지?', `MaleText_loc4`='很高兴见到你，$n。$b$b一切都在按照计划进行吧？', `MaleText_loc5`='看到你真好，$n。$b$b我相信一切都照著計畫進行?', `MaleText_loc7`='Me alegro de verte, $n.$B$B¿Espero que todo vaya según lo planeado?' WHERE `ID`=33969;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='듀락, 변장 도구를 잃어버렸습니다!', `MaleText_loc4`='杜莱克，我失去了伪装！', `MaleText_loc5`='杜雷克，我的偽裝沒了!', `MaleText_loc7`='¡Durak, he perdido mi disfraz!', `FemaleText_loc1`='듀락, 변장 도구를 잃어버렸습니다!', `FemaleText_loc4`='杜莱克，我失去了伪装！', `FemaleText_loc5`='杜雷克，我的偽裝沒了!', `FemaleText_loc7`='¡Durak, he perdido mi disfraz!' WHERE `ID`=33970;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가서 일하란 말이다, 멍청한 놈들아! 일이 한참 늦어졌잖아!', `MaleText_loc4`='回去工作，废物！我们的进度已经落后了！', `MaleText_loc5`='回去工作，奴犬們!我們的進度已經落後了!', `MaleText_loc7`='¡Volved al trabajo, perros! ¡Vamos con retraso!' WHERE `ID`=33971;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='애송이 엘프 놈들이 일하는 데 공격하지 못하도록 하란 말이다!', `MaleText_loc4`='不要让小小的精灵进攻干扰你的工作！', `MaleText_loc5`='別讓一次精靈的小騷擾延誤你的工作進度!', `MaleText_loc7`='¡No permitas que un miserable ataque elfo se interponga en tu trabajo!' WHERE `ID`=33972;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 가서 광석이나 캐란 말이다! 가만있으면 광석이 혼자 튀어나오나!', `MaleText_loc4`='继续挖！矿石可不会自己蹦出来！', `MaleText_loc5`='快滾回去挖!這些礦石不會自己跳到籃子裡!', `MaleText_loc7`='¡Volved a cavar! ¡Esta mina no se va a picar sola!' WHERE `ID`=33973;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쉬는 시간 따위는 없다! 가서 일하란 말이야!', `MaleText_loc4`='没时间休息了，快回去工作！', `MaleText_loc5`='沒時間休息!回去工作!', `MaleText_loc7`='¡No hay tiempo para descansos! ¡Volved al trabajo!' WHERE `ID`=33974;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어이, 자네. 어떻게 지내나?$B$B와서 돌진 기술을 좀 배워 보는 게 어떻겠나?', `MaleText_loc4`='嗨，你好！$B$B你是来学习冲锋技巧的吗，$c？', `MaleText_loc5`='嗨，你好嗎?$B$B來學習衝鋒的技巧嗎，$c?', `MaleText_loc7`='Eh, ¿qué tal estás?$b$b¿Vienes a aprender el arte de Cargar, $c?' WHERE `ID`=33975;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌진 표적으로 어떻게 훈련해야 하는지 보여주십시오.', `MaleText_loc4`='教我如何与冲锋目标作战吧。', `MaleText_loc5`='教我如何用衝鋒標靶訓練。', `MaleText_loc7`='Muéstrame cómo entrenarme con un objetivo de carga.', `FemaleText_loc1`='돌진 표적으로 어떻게 훈련해야 하는지 보여주세요.', `FemaleText_loc4`='教我如何与冲锋目标作战吧。', `FemaleText_loc5`='教我如何用衝鋒標靶訓練。', `FemaleText_loc7`='Muéstrame cómo entrenarme con un objetivo de carga.' WHERE `ID`=33976;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알고 싶다니 말해주지! 탈것에 탄 상태로 하는 돌진은 그냥 박차를 가해 전속력을 내면서 소리지르는게 다가 아니거든... 물론 그게 ''재미있는'' 부분이긴 하지만 말이야, 하핫! 돌진 표적으로 표적을 잘 잡는 법을 알려주지.$B$B제대로 된 돌진은 거리와 절묘하게 시간을 맞추는 일에 달렸어. 너무 가까이 가면 안 돼. 그러면 충분한 속도를 낼 수 없으니까. 하지만, 너무 멀리 가서도 안 되지. 그러면 탈것이 지치거든! 다 시간 싸움이야...$B$B달려가기 전에 돌진 표적에 방어가 형성되지 않았는지 확인하는 게 좋을 거야. 방어가 있다면, 원거리 공격으로 무력화시키라고. 그러고 나서 돌진해 들어가는 거지! 실전에서도 마찬가지야. 돌진하기 전에 상대방의 방어를 누그러뜨려야해!', `MaleText_loc4`='好吧！骑乘冲锋可不仅仅是让你的坐骑高速冲刺，体验那种心飙到嗓子眼的快感……当然这的确是最有趣的部分，嘿嘿！但是冲锋目标可以帮助你掌握更多诀窍。$B$B冲锋的关键在于距离与时机。不能靠得太近，否则无法全力提速。也不能离得太远，否则坐骑就会进入疲惫状态！至于冲锋的时机……$B$B在冲锋之前，你最好确认一下冲锋目标身上是否有防御效果。如果有，你应该先使用碎盾然后再冲锋！$B$B实战中遵循着同样的原则：在冲锋前要尽可能地削弱对手的防御效果！', `MaleText_loc5`='很好!騎乘衝鋒可不只是踢踢你的坐騎讓它全速衝刺，然後從你胸膛裡大聲喊叫...雖然這真的很有趣啦，哈哈!但衝鋒標靶會教導你更好的東西。$B$B一次好的衝鋒完全取決於距離與時機。你不能太近，否則你的速度會不夠。但你也不能離太遠，否則你的坐騎會太累!至於時機嘛...$b$b你會希望確保在你衝向它時，衝鋒標靶上頭一層防禦也沒有。如果標靶上尚有防禦，就用你的破盾攻擊讓它更脆弱，然後向它衝鋒!$B$B真的上場時也一樣:盡量在衝鋒前削弱對手的防禦!', `MaleText_loc7`='El secreto de una buena carga reside en medir bien la distancia y el tiempo. No puedes estar DEMASIADO cerca, o no alcanzarás suficiente velocidad. ¡Pero tampoco puedes estar demasiado lejos o tu montura se cansará! En cuanto al tiempo...$b$bTienes que asegurarte de que el objetivo de carga no tiene una capa de Defender activa antes de avalanzarte. Si es así, emplea tu Romper escudo para hacerlo vulnerable, y ¡ENTONCES utiliza Cargar!$b$bLo mismo pasa con el combate de verdad: ¡intenta reducir las defensas de tu oponente antes de cargar!' WHERE `ID`=33977;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 물고기를 낚았습니다!', `MaleText_loc4`='%s捉住了一条鱼！', `MaleText_loc5`='%s抓到了一條魚!', `MaleText_loc7`='¡%s atrapa un pez!' WHERE `ID`=33978;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음. $C|1이;가; 또 하나 왔군. 방패 부수기 기술을 좀 배우러 왔소...?', `MaleText_loc4`='哎呀。又一位$c，你是来学习碎盾的技巧的吗……？', `MaleText_loc5`='嗯，又一個$c，來學習破盾方法的嗎...?', `MaleText_loc7`='Bien. Otr$go:a; $c. ¿Vienes a aprender Romper escudo?' WHERE `ID`=33979;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원거리 표적으로 어떻게 훈련해야 하는지 보여주십시오.', `MaleText_loc4`='教我如何与远程目标作战吧。', `MaleText_loc5`='教我如何用遠程標靶訓練。', `MaleText_loc7`='Muéstrame cómo entrenarme un objetivo a distancia.', `FemaleText_loc1`='원거리 표적으로 어떻게 훈련해야 하는지 보여주세요.', `FemaleText_loc4`='教我如何与远程目标作战吧。', `FemaleText_loc5`='教我如何用遠程標靶訓練。', `FemaleText_loc7`='Muéstrame cómo entrenarme un objetivo a distancia.' WHERE `ID`=33980;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원거리에서 공격하는 방패 부수기는 배우기 쉬워도, 완전히 터득하기는 어렵소. 그 자체만으로는 약한 기술처럼 보이나, 찌르기와 돌진과 함께 사용하면 마상 전투를 성공적으로 치를 수 있다오.$B$B원거리 표적을 찾으시오. 방패 부수기의 범위가 어느 정도 되는지 잠시 가늠하시오... 공간은 얼마나 필요한지, 창을 얼마나 멀리에서 던질 수 있는지 등등 말이오.$B$B그다음 말이오? 글쎄. 던져야 하오. 마지막 방어 단계까지 깨뜨려 약해진 대상을 관통할 때까지 멈추지마시오.$B$B이 전술은 실제 마상 전투에서도 잘 쓰일 수 있소. 적의 방어를 무너뜨린 다음... 뭉개버리면 되오!', `MaleText_loc4`='远程碎盾攻击上手容易精通难。碎盾攻击所能造成的伤害不高，但是配合刺击和冲锋使用就能发挥出完美的效果，令你在骑乘作战中所向披靡。$B$B选定一个远程目标，估算一下碎盾攻击的射程……你需要多远的距离以及你能将长枪掷多远。$B$B接下来，就开始投掷长枪吧，直到你破坏目标身上的所有防御效果。$B$B骑乘实战中遵循着同样的原则：彻底粉碎对手的防御……然后狠狠地揍他们！', `MaleText_loc5`='遠程的破盾攻擊學起來不難，但要精通可不容易。獨自使用可能看來很弱，但將破盾與戳刺和衝鋒配合無間，才能成為一個成功的騎乘競技高手。$B$B找一個遠程標靶。花點時間瞭解破盾的射程...你需要多少距離，你可以把長槍丟得多遠。$B$B在那之後?嗯。開始投擲，不要停，一直到你把對手的每一層防禦打破，並且刺穿脆弱的敵人。$B$B這種戰術在實際騎乘戰鬥時一樣有效:打破你敵人的防禦...然後打垮他們!', `MaleText_loc7`='El ataque Romper escudo a distancia es fácil de aprender pero difícil de dominar. Puede que por sí solo parezca débil, pero en conjunción con Estocada y Cargar, Romper escudo hace que ganes una justa.$b$bEncuentra un objetivo a distancia. Tómate tu tiempo para entender el alcance de Romper escudo... cuánto espacio necesitas, y a cuánta distancia puedes arrojar tu lanza.$b$b¿Después de eso? Bueno. Ponte a arrojar y no pares hasta que hayas roto hasta la última capa de Defender y tu objetivo sea vulnerable.$b$bEsta táctica te será útil en el auténtico combate sobre montura: destruye las defensas de tus oponentes... ¡y aplástalos!' WHERE `ID`=33981;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희가 브란의 전갈을 받고 미리 준비를 시작했습니다.', `MaleText_loc4`='我们收到了布莱恩的消息，已经开始着手做准备了。', `MaleText_loc5`='我們收到了布萊恩的消息，我們會開始準備。', `MaleText_loc7`='Recibimos el mensaje de Brann y ya comenzamos a prepararnos.' WHERE `ID`=33982;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달라란의 시민이여! 두 눈을 들어 하늘을 올려다보라!', `MaleText_loc4`='达拉然的公民们！抬起你们的头，仰望天空吧！', `MaleText_loc5`='達拉然的市民們!睜開你們的雙眼好好地看著天空!', `MaleText_loc7`='¡Ciudadanos de Dalaran! ¡Dirijan su vista hacia los cielos y observen!' WHERE `ID`=33983;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 우리는, 바로 우리를 창조한 존재에 맞서 세계의 파괴를 막아냈다!', `MaleText_loc4`='今天，我们所生活的这个世界，险些被它的缔造者毁灭！', `MaleText_loc5`='今天，我們所身處的世界，躲過了偉大造物主的毀滅!', `MaleText_loc7`='¡Hoy se evitó la destrucción del mundo en desafío de nuestros propios creadores!' WHERE `ID`=33984;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용감한 우리 동료가, 티탄 도시 울두아르 깊숙한 곳에서 티탄의 사자인 관찰자 알갈론을 물리쳤다!', `MaleText_loc4`='我们勇敢的伙伴们深入泰坦之城奥杜尔，击败了观察者奥尔加隆，泰坦派来的使者！', `MaleText_loc5`='『觀察者』艾爾加隆，泰坦的信使，在泰坦城市奧杜亞的深處，被我們最勇敢的同伴所擊敗。', `MaleText_loc7`='Algalon Observador, hearldo de los titanes, fue vencido por nuestros valientes camaradas en la ciudad titán de Ulduar.' WHERE `ID`=33985;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알갈론은 우리 세상의 운명을 결정하러 왔었다.', `MaleText_loc4`='奥尔加隆前来决定我们这个世界的命运。', `MaleText_loc5`='艾爾加隆被派來決定我們世界的命運。', `MaleText_loc7`='Algalon fue enviado aquí para juzgar el destino del mundo.' WHERE `ID`=33986;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그가 찾은 행성에는 티탄의 청사진을 벗어난 종족들이 살고 있었다. 그곳은 티탄의 계획과 다르게 돌아가고 있었다.', `MaleText_loc4`='他发现，在这个世界中，人们并不接受泰坦设计的蓝图。在这个世界中，并非一切都按照计划完美运行。', `MaleText_loc5`='他發現這個星球的種族早已脫離了泰坦原有的藍圖。這個星球上並非萬事萬物都照著泰坦的計畫而行。', `MaleText_loc7`='Encontró un planeta cuyas razas se habían salido de los diseños titánicos. Un planeta donde no todo salió como se planeaba.' WHERE `ID`=33987;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='차가운 논리는 이 세상을 보전할 가치가 없다고 판단했다. 그러나 차가운 논리는, 자유 의지의 힘을 간과했다! 이제 우리가 증명해야 한다. 이 세상의 가치를!', `MaleText_loc4`='冷酷的逻辑推论出：我们的世界不值得拯救。但是，它并没有考虑到自由意志的力量。我们每一个人都有责任证明，这是一个值得拯救的世界。', `MaleText_loc5`='冰冷的邏輯認定我們的世界不值得保留。冰冷的邏輯卻沒有把自由意志的力量納入考量。而證明這個世界有其存在的價值是我們每一個人的職責。', `MaleText_loc7`='La fría lógica dijo que a nuestro mundo no valía la pena salvarlo, pero la lógica no explica el poder del libre albedrío. Depende de nosotros probar que el mundo vale la pena.' WHERE `ID`=33988;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 우리의 삶이... 살 가치가 있음을.', `MaleText_loc4`='因为我们的生命……是值得延续的生命。', `MaleText_loc5`='我們的生命...是值得活下去的。', `MaleText_loc7`='Que a nuestras vidas... vale la pena vivirlas.' WHERE `ID`=33989;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 포세이큰어로 혼자 중얼거립니다.', `MaleText_loc4`='%s用被遗忘者语言自言自语着。', `MaleText_loc5`='%s自言自語地嘀咕著不死族語。', `MaleText_loc7`='%s murmura para sí mismo en renegado.' WHERE `ID`=33990;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='프레이야가 |Cff00ff00강화된 무쇠 뿌리|r를 시전합니다!', `FemaleText_loc4`='弗蕾亚施放了|cFF00FF00强化钢铁根须！|r', `FemaleText_loc5`='芙蕾雅施展了|cFF00FF00強化鐵之根鬚!|r', `FemaleText_loc7`='¡Freya lanza |cFF00FF00Raíces férreas reforzadas!|r' WHERE `ID`=33991;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 광폭해져, 모든 생명을 없앱니다!', `MaleText_loc4`='%s狂暴了，摧毁了所有生命体！', `MaleText_loc5`='%s陷入狂暴，滅絕所有生命!', `MaleText_loc7`='¡%s se pone rabioso y extingue toda la vida!' WHERE `ID`=33993;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='창조의 도구를 바라보아라!', `MaleText_loc4`='看吧，这创世的神器！', `MaleText_loc5`='瞧瞧泰坦造物的能耐吧!', `MaleText_loc7`='¡Contempla las herramientas de la creación!' WHERE `ID`=33994;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 행동은 비논리적이다. 이 전투에서 가능한 결말은 모두 계산되었다. 결과와 상관없이 판테온은 관찰자의 전갈을 받을 것이다.', `MaleText_loc4`='你们的行动不合逻辑。这场战斗所有可能产生的结果都已被计算在内。无论结果如何，万神殿都会收到观察者发出的信息。', `MaleText_loc5`='你的行為毫無意義。這場衝突的結果早已計算出來了。不論結局為何，萬神殿仍將收到觀察者的訊息。', `MaleText_loc7`='Tus acciones son ilógicas. Todos los resultados posibles de este encuentro han sido calculados. El Panteón recibirá el mensaje del Observador más allá del resultado.' WHERE `ID`=33995;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불가피한 죽음이다.', `MaleText_loc4`='生命的凋零，不可避免。', `MaleText_loc5`='生命終將殞落。', `MaleText_loc7`='Pérdida de vida inevitable.' WHERE `ID`=33996;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='의무를 다했을 뿐.', `MaleText_loc4`='我必须这么做。', `MaleText_loc5`='我只盡我的本分。', `MaleText_loc7`='Hago lo que debo hacer.' WHERE `ID`=33997;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 눈을 통해 너희 세상을 보아라. 측정할 수 없이 광활한 우주를... 너희 지성으로는 절대 이해할 수 없다.', `MaleText_loc4`='通过我的双眼来观察你们的世界吧：一个广袤无垠的宇宙，即使是你们当中最睿智的人，也无法理解这一切。', `MaleText_loc5`='從我的雙眼觀看你的世界:一個無邊無際的宇宙--連你們之中最具智慧者都無法想像的廣闊無垠。', `MaleText_loc7`='Vean su mundo a través de mis ojos: un universo tan vasto que es inconmensurable... Incomprensible aún para sus mentes más brillantes.' WHERE `ID`=33998;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심해라...', `MaleText_loc4`='当心……', `MaleText_loc5`='當心...', `MaleText_loc7`='Cuidado...' WHERE `ID`=33999;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 창조주의 불길이 씻어내린 세상을 보았다. 모두 변변히 저항도 못하고 사그라졌지. 너희 필멸자의 심장이 단 한 번 뛸 시간에 전 행성계가 탄생하고 무너졌다. 그러나 그 모든 시간 동안, 나는 공감이란 감정을... 몰랐다. 나는, 아무것도, 느끼지, 못했다. 무수한, 무수한 생명이 꺼졌다. 그들이 모두 너희처럼 강인했더냐? 그들이 모두 너희처럼 삶을 사랑했단 말이냐?', `MaleText_loc4`='我曾见证过无数个世界被造物者的烈焰吞噬，那些世界中的人们甚至来不及发出一声悲鸣就永远消逝了。整个星球从诞生到毁灭，不过是弹指一挥间。但是从始至终，我都没有为之动容……我，毫无，感觉。千亿的生命被毁灭。他们是否都像你们一样坚强？他们是否都像你们一样热爱生命？', `MaleText_loc5`='我曾經看過塵世沉浸在造物者的烈焰之中，眾生連一聲悲泣都無法呼出，就此凋零。整個星系在彈指之間歷經了毀滅與重生。然而在這段歷程之中，我的心卻無法感受到絲毫的...惻隱之念。我‧感‧受‧不‧到。成千上萬的生命就這麼消逝。他們是否擁有與你同樣堅韌的生命?他們是否與你同樣熱愛生命?', `MaleText_loc7`='He visto mundos enteros bañados en las llamas del Creador, a sus habitantes esfumarse dejando menos que un quejido. Sistemas planetarios nacen y son arrasados en lo que les lleva a sus corazones mortales dar un latido. Y aún después de todo, mi propio corazón carece de emoción... de compasión. Nunca. He. Sentido. Nada. Un millón de millones de vidas desperdiciadas. ¿Acaso todas ellas llevaban dentro tu tenacidad? ¿Todas amaban la vida como tú?' WHERE `ID`=34000;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희에겐, 시간이 없다.', `MaleText_loc4`='你们没有时间了！', `MaleText_loc5`='你的時間用盡了。', `MaleText_loc7`='Se te acabó el tiempo.' WHERE `ID`=34001;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고어백이 제게 드라카리 제국을 보여줬습니다. 당신이 그 제국을 정복할 때 돕고 싶어 몸살 날 지경입니다!', `MaleText_loc4`='高尔巴格带我游览了达卡莱帝国。我很乐意帮助你征服它！', `MaleText_loc5`='血袋向我展現了德拉克瑞帝國。我急著要協助你征服它!', `MaleText_loc7`='Bolsasangrienta me ha mostrado imperio Drakkari. ¡Estoy ansioso por ayudarte a conquistarlo!', `FemaleText_loc1`='고어백이 제게 드라카리 제국을 보여줬어요. 당신이 그 제국을 정복할 때 돕고 싶어 몸살 날 지경이에요!', `FemaleText_loc4`='高尔巴格带我游览了达卡莱帝国。我很乐意帮助你征服它！', `FemaleText_loc5`='血袋向我展現了德拉克瑞帝國。我急著要協助你征服它!', `FemaleText_loc7`='Bolsasangrienta me ha mostrado imperio Drakkari. ¡Estoy ansiosa por ayudarte a conquistarlo!' WHERE `ID`=34002;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전부 적당한 때가 언제인가에 달렸지, $r. 곧 자네가 해 줄 일이 더 있을 걸세...', `MaleText_loc4`='朋友，你来得正是时候。很快我就会给你安排更多的任务了……', `MaleText_loc5`='時機不錯，老兄。我還有更多工作等著你...', `MaleText_loc7`='Todo a su tiempo, camarada. Pronto tendré más trabajo para ti...' WHERE `ID`=34003;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 과부하되기 시작합니다!', `MaleText_loc4`='%s过载了！', `MaleText_loc5`='%s開始超載!', `MaleText_loc7`='¡%s comienza a sufrir una Sobrecarga!' WHERE `ID`=34004;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='역병 외눈깨비는 제가 따끔하게 가르쳐 놨습니다!', `MaleText_loc4`='我狠狠地教训了那些荒芜恶鬼！', `MaleText_loc5`='我給了那些荒疫魂屍一頓鞭子，讓它們好好聽話!', `MaleText_loc7`='¡He puesto en solfa a los geists de añublo!', `FemaleText_loc1`='역병 외눈깨비는 제가 따끔하게 가르쳐 놨어요!', `FemaleText_loc4`='我狠狠地教训了那些荒芜恶鬼！', `FemaleText_loc5`='我給了那些荒疫魂屍一頓鞭子，讓它們好好聽話!', `FemaleText_loc7`='¡He puesto en solfa a los geists de añublo!' WHERE `ID`=34005;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분석 완료. 행성 생명 유지 시스템이 부분적으로 손상되었을 뿐 아니라, 행성 수호 장치 대부분이 완전히 손상됐다.', `MaleText_loc4`='分析完成。这个星球的生命支持系统受到了部分腐蚀，而防御机制则完全被腐蚀了。', `MaleText_loc5`='分析完畢。整個星球的生命維護系統受到局部的腐化，同時大部份的防禦機制也已全面腐化。', `MaleText_loc7`='Análisis completo. Existe una corrupción parcial de los sistemas vitales del planeta, así como una corrupción completa en la mayor parte de los mecanismos de defensa del planeta.' WHERE `ID`=34006;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 그런 것 같군, $r. 역병 결정이 이제 거의 충분히 쌓인 듯하네!', `MaleText_loc4`='我看出来了。荒芜水晶的储量大增，很快就能满足需求了。', `MaleText_loc5`='你確實該這麼做，老兄。我們荒疫水晶的儲存量差不多足夠了!', `MaleText_loc7`='Desde luego, camarada. ¡Nuestras reservas de cristales de añublo son casi suficientes!' WHERE `ID`=34007;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다르무크를 처치했습니다! 또 해드릴 일은 없습니까?', `MaleText_loc4`='我已经击败了达穆克！你还需要我做什么吗？', `MaleText_loc5`='我擊敗了達穆克!我該如何繼續替您服務?', `MaleText_loc7`='¡He derrotado a Darmuk! ¿Qué más puedo hacer por ti?', `FemaleText_loc1`='다르무크를 처치했어요! 또 해드릴 일은 없나요?', `FemaleText_loc4`='我已经击败了达穆克！你还需要我做什么吗？', `FemaleText_loc5`='我擊敗了達穆克!我該如何繼續替您服務?', `FemaleText_loc7`='¡He derrotado a Darmuk! ¿Qué más puedo hacer por ti?' WHERE `ID`=34008;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다르무크의 무능함 때문에 우리 앞길이 막히는 일이 더는 없을 걸세! 인내심을 갖게. 자네가 할 일이 곧 더 있을 테니...', `MaleText_loc4`='达穆克这个饭桶再也不能惹麻烦了！耐心点，朋友。很快就会有更多的工作交给你做了……', `MaleText_loc5`='達穆克的無能將不會再拖延我們!耐心，老兄。還有很多別的事情等著你...', `MaleText_loc7`='¡Ya no nos estorbará más la incompetencia de Darmuk! Paciencia, camarada. Pronto habrá más que puedas hacer...' WHERE `ID`=34010;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드라카리 족장을 잡았습니다! 제게 더 시키실 일이 있으십니까?', `MaleText_loc4`='我已经俘获了达卡莱酋长！你还需要我做什么吗？', `MaleText_loc5`='我抓到了德拉克瑞酋長!您還要我做點什麼?', `MaleText_loc7`='¡Los cabecillas Drakkari han sido capturados! ¿Qué más quieres que haga?', `FemaleText_loc1`='드라카리 족장을 잡았어요! 제게 더 시키실 일이 있으신가요?', `FemaleText_loc4`='我已经俘获了达卡莱酋长！你还需要我做什么吗？', `FemaleText_loc5`='我抓到了德拉克瑞酋長!您還要我做點什麼?', `FemaleText_loc7`='¡Los cabecillas Drakkari han sido capturados! ¿Qué más quieres que haga?' WHERE `ID`=34011;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어쩌면, 너희는 자유의지를 지닌 불완전한 존재이기 때문에... 우주의 절대적인 질서에 맞설 수 있는지도 모르겠다. 티탄의 완벽한 창조물이 스러진 곳에서 너희는 번성하는구나.', `MaleText_loc4`='也许正是这种不完美，才使你们获得了自由的意志，并因此有能力改变那些看起来不可避免的必然命运。泰坦所创造的许多完美生命体都遭遇了失败，而你们仍能继续前行。', `MaleText_loc5`='或許是你們在天性上的缺陷--也因此賦予你們自由的意志--使你們得以與宇宙運行的法則所抗衡。你達成了泰坦的完美造物也無法完成的使命。', `MaleText_loc7`='Quizás sea su imperfección, ésa que les da el libre albedrío, lo que les permite perseverar contra toda probabilidad calculada cósmicamente. Ustedes prevalecen donde las propias creaciones perfectas de los titanes han fallado.' WHERE `ID`=34012;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='응답 코드를 다시 만들었다. 너희 행성은 유지될 것이다. 이제 나는 내 계산을 믿을 수가 없다.', `MaleText_loc4`='我已经修改了回复代码，你们的行星得救了。我不能再对自己的计算结果深信不疑了。', `MaleText_loc5`='我已重新設定了回覆代碼:你們的星球將獲得赦免。我再也無法信任我所計算的結果了。', `MaleText_loc7`='He reconfigurado el código-respuesta: su planeta será perdonado. Ya no puedo confiar en mis propios cálculos.' WHERE `ID`=34013;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전송 시작. 응답 코드 오메가. 행성 재창조가 요청되었다.', `MaleText_loc4`='启动上行通讯：回复代码“欧米迦”。请求启动行星组织重构。', `MaleText_loc5`='開始上傳連線:回覆代碼Ω。提出星球重啟要求。', `MaleText_loc7`='Iniciar canal de transmisión: Código-respuesta Omega. Reoriginación planetaria solicitada.' WHERE `ID`=34014;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 가라, 필멸자여. 그토록 결함이 있는 생명체치고 너희는 참으로 용감했다.', `MaleText_loc4`='再会了，凡人们。你们是不完美的生命体，但你们的勇气值得钦佩。', `MaleText_loc5`='再會了，凡人。以具有瑕疵的物種來說，你們的勇氣令人欽佩。', `MaleText_loc7`='Me despido, mortales. Su valentía es admirable, siendo criaturas tan defectuosas.' WHERE `ID`=34015;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신호를 전송할 힘이 없다. 서둘러라... 하늘 가까이에서... 힘이 깃든 장소를... 찾아라.', `MaleText_loc4`='我没有足够的力气去发射信号。你们必须……尽快……找到一处发射场……要靠近天空。', `MaleText_loc5`='我的力量已不足以傳輸信號了。你必須...盡快...找到足夠的能量...靠近穹蒼的地方。', `MaleText_loc7`='Me falta fuerza para transmitir la señal. Debes... apurarte... hallar un lugar de poder... cerca de los cielos.' WHERE `ID`=34016;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어딘지 압니다. 당신 괜찮겠어요?', `MaleText_loc4`='我知道该去哪里。你没事吧？', `MaleText_loc5`='我知道適合的地方。你還好吧?', `MaleText_loc7`='Conozco el lugar ideal. ¿Vas a estar bien?' WHERE `ID`=34017;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 운명을 걱정하지 마라, 브론젠. 시간 안에 신호를 전송하지 못하면, 재창조가 시작되고 말 것이다. 너희의 세상을... 지켜라...', `MaleText_loc4`='不用担心我的命运，布隆赞。如果信号没有及时发射出去，行星结构重组仍然会自行启动。拯救……你们的世界……', `MaleText_loc5`='別管我會如何，銅鬚。如果時限內未能將信號傳出去，星球重啟仍會如期進行。拯救...你的世界吧...', `MaleText_loc7`='No te preocupes por mi destino, Bronzen. Si las señales no se transmiten a tiempo, la reoriginación se llevará acabo de todas formas. Salva... a tu mundo…' WHERE `ID`=34018;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='족장들을 처리했으니, 공격할 준비를 해야지! 곧 말이야, $n...', `MaleText_loc4`='除掉那些酋长之后，我们就准备发动攻击了！用不了多久的，$n……', `MaleText_loc5`='沒有那些酋長阻撓我們，我們可以放手進攻!要不了多久，$n...', `MaleText_loc7`='¡Con los cabecillas fuera de circulación, estamos listos para hacer nuestro ataque! Pronto, $n...' WHERE `ID`=34019;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 엄청난 작전을 보았습니다, 드라쿠루. 언제 그 계획을 실행에 옮길 생각이십니까?', `MaleText_loc4`='达库鲁，我亲眼目睹了你精妙的部署。什么时候执行攻占达卡莱帝国的计划呢？', `MaleText_loc5`='我目睹了你巧妙的策劃，德拉庫魯。你打算何時將計畫付諸實行?', `MaleText_loc7`='He sido testigo de tu magnífica operación, Drakuru. ¿Cuándo ejecutamos nuestro plan?', `FemaleText_loc1`='당신의 엄청난 작전을 보았어요, 드라쿠루. 언제 그 계획을 실행에 옮길 생각이시죠?', `FemaleText_loc4`='达库鲁，我亲眼目睹了你精妙的部署。什么时候执行攻占达卡莱帝国的计划呢？', `FemaleText_loc5`='我目睹了你巧妙的策劃，德拉庫魯。你打算何時將計畫付諸實行?', `FemaleText_loc7`='He sido testigo de tu magnífica operación, Drakuru. ¿Cuándo ejecutamos nuestro plan?' WHERE `ID`=34020;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 모든 것을 깨달았겠지! 마음 단단히 먹게... 곧 공격을 감행할 테니!', `MaleText_loc4`='朋友，眼下的形势你已经了如指掌了！做好准备吧……我们很快就要发动攻击了！', `MaleText_loc5`='現在你知道所有事情了，老兄!做好準備...我們很快就會開始攻擊!', `MaleText_loc7`='¡Ahora ya lo sabes todo, camarada! Prepárate... ¡pronto atacaremos!' WHERE `ID`=34021;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 입을 크게 벌립니다!', `MaleText_loc4`='%s张开了大嘴！', `MaleText_loc5`='%s張大了他的嘴巴!', `MaleText_loc7`='¡%s abre bien la boca!' WHERE `ID`=34022;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s의 심장이 몸에서 분리됩니다.', `MaleText_loc4`='%s分崩离析了。', `MaleText_loc5`='%s的心從他的身體中分離出來。', `MaleText_loc7`='El corazón de %s es separado de su cuerpo.' WHERE `ID`=34023;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로데론이 무너질 때 여기에 있는 친척을 방문하던 참이었다오. 그리고 그때... 글쎄올시다. 이제 서부 몰락지대로 돌아가지는 않을 것 같소.$B$B가끔 두고온 가족들이 아직 살아 있는지 궁금하기는 하오. 그것보다 더 자주 드는 궁금증은, 왜 내가 더는 신경조차 쓰지 않는 지라오.', `MaleText_loc4`='洛丹伦沦陷时，我正在这里拜访亲戚……唉。我大概再也不能回到西部荒野了。$B$B有时我会思念家人，也不知他们是否依然健在。但是更多的时候，我的内心平静地如同一滩死水，好像没有什么能让我牵挂的了。', `MaleText_loc5`='在羅德隆陷落的時候，我曾經去探訪過親友，而他們...嗯。我猜想我大概再也不會回到西部荒野。$B$B有時候我會想不知道我的家人是不是還活著。但更多時候，我會想為什麼我已經不在乎了。', `MaleText_loc7`='Estaba aquí visitando unos parientes cuando Lordaeron cayó, y entonces... Bien. Supongo que ya no voy a regresar a los Páramos de Poniente.$b$bA veces me pregunto si mi familia sigue viva. Aunque, más a menudo me pregunto por qué ya no me importa.' WHERE `ID`=34024;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 해냈습니다! 알갈론보다 먼저 도착했다고요. 아마 시스템을 조작하면 알갈론의 분석을 방해할 수 있을...', `MaleText_loc4`='我们成功了，伙计们！终于抢在奥尔加隆前面来到了这儿……也许我们可以对系统做点手脚，改变他的分析结果……', `MaleText_loc5`='我們辦到了，小夥子!我們搶在艾爾加隆之前趕到。說不定能對系統動點手腳，影響他的分析...', `MaleText_loc7`='¡Lo hemos conseguido, chicos! Llegamos antes de la llegada de Algalon. Igual podemos entrar en el sistema e interferir sus análisis…' WHERE `ID`=34025;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='순간이동 완료. 아제로스 행성 분석 시작.', `MaleText_loc4`='迁移完成。开始对艾泽拉斯展开行星分析。', `MaleText_loc5`='傳輸完畢。進行艾澤拉斯星體分析。', `MaleText_loc7`='Desplazamiento completo. Comenzando análisis planetario de Azeroth.' WHERE `ID`=34026;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물러서라, 필멸자여. 나는 싸우러 온 것이 아니다.', `MaleText_loc4`='退后，凡人们。我不是来这里跟你们打架的。', `MaleText_loc5`='退開，凡人。我無意與你相爭。', `MaleText_loc7`='Apártense, mortales. No he venido a pelear con ustedes.' WHERE `ID`=34027;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분석 결과 시스템의 손상이 발견된다면, 이 행성을 재창조하는 것이 전 우주를 위하는 길이다. 방해하지 마라.', `MaleText_loc4`='如果我的分析结果表明确实存在系统级的污染，对这颗行星进行结构重组无疑是最妥当的方案。不要插手。', `MaleText_loc5`='如果我的分析找出系統產生了腐化，此行星就必須重啟才不會危害到整個宇宙。不要阻止此事。', `MaleText_loc7`='Es por el bien del universo reoriginar este planeta si mi análisis llegara a encontrar una corrupción sistémica. No interfieran.' WHERE `ID`=34028;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 고대 기록관으로 돌아가 신호를 방해해 볼게요. 당신들이 그를 상대하는 동안 시간을 좀 벌어 보죠.', `MaleText_loc4`='我这就回档案馆，看看能不能堵塞他的信号。在你们对付他的同时，我努力多争取一点时间。', `MaleText_loc5`='我立刻回大資料庫，看能不能中斷他的信號。或許在你們對付他時，我能爭取一點時間。', `MaleText_loc7`='Volveré al Archivum y trataré de interferir su señal. Tal vez nos de algo de tiempo mientras ustedes se ocupan de él.' WHERE `ID`=34029;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 당신 기술을 시험해 보시오.', `MaleText_loc4`='去熟悉一下技能吧。', `MaleText_loc5`='現在來試試你的技巧。', `MaleText_loc7`='Ahora pon a prueba tus habilidades.' WHERE `ID`=34031;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방어를 시전합니다.$B|Tinterface\\Icons\\Ability_Warrior_ShieldMastery.blp:32|t$B그러고 나서 근접 표적에 찌르기를 사용합니다.$B|Tinterface\\Icons\\INV_Sword_65.blp:32|t', `MaleText_loc4`='给自己加上防御。$B|TInterface\\Icons\\Ability_Warrior_ShieldMastery.blp:32|t$B然后对近战目标使用刺击。$B|TInterface\\Icons\\INV_Sword_65.blp:32|t', `MaleText_loc5`='提高防禦$B|TInterface\\Icons\\Ability_Warrior_ShieldMastery.blp:32|t$B然後對近戰標靶使用戳刺。$B|TInterface\\Icons\\INV_Sword_65.blp:32|t', `MaleText_loc7`='Activa Defender$B|TInterfaceIconsAbility_Warrior_ShieldMastery.blp:32|t$BLuego usa Estocada contra un objetivo cuerpo a cuerpo.$B|TInterfaceIconsINV_Sword_65.blp:32|t', `FemaleText_loc1`='방어를 시전합니다.$B|Tinterface\\Icons\\Ability_Warrior_ShieldMastery.blp:32|t$B그러고 나서 근접 표적에 찌르기를 사용합니다.$B|Tinterface\\Icons\\INV_Sword_65.blp:32|t', `FemaleText_loc4`='给自己加上防御。$B|TInterface\\Icons\\Ability_Warrior_ShieldMastery.blp:32|t$B然后对近战目标使用刺击。$B|TInterface\\Icons\\INV_Sword_65.blp:32|t', `FemaleText_loc5`='提高防禦$B|TInterface\\Icons\\Ability_Warrior_ShieldMastery.blp:32|t$B然後對近戰標靶使用戳刺。$B|TInterface\\Icons\\INV_Sword_65.blp:32|t', `FemaleText_loc7`='Activa Defender$B|TInterfaceIconsAbility_Warrior_ShieldMastery.blp:32|t$BLuego usa Estocada contra un objetivo cuerpo a cuerpo.$B|TInterfaceIconsINV_Sword_65.blp:32|t' WHERE `ID`=34032;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 장엄함을 느껴라! 영광을 흠뻑 취해, 아니... 영광에 취해라! 소개하마... V-07-TR-0N!', `MaleText_loc4`='庄严地注目它吧！沐浴在它的荣耀中吧！将要出场的是……V-07-TR-0N！', `MaleText_loc5`='看看它有多麼壯觀!沈浸在它的光榮中吧，呃，光輝!現在登場的是...V-07-TR-ON!', `MaleText_loc7`='¡Contemplen su magnificencia! ¡Deléitense en su gloriosa, ehm, gloria! Les presento a... ¡V-07-TR-ON!' WHERE `ID`=34033;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌진 표적에 방패 부수기를 사용합니다.$B|Tinterface\\Icons\\Ability_Warrior_ShieldBreak.blp:32|t$B표적이 무력화되었을 때 이어서 돌진으로 공격합니다.$B|Tinterface\\Icons\\Ability_Mount_Charger.blp:32|t', `MaleText_loc4`='对冲锋目标使用碎盾。$B|TInterface\\Icons\\Ability_Warrior_ShieldBreak.blp:32|t$B趁目标处于脆弱状态时立即冲锋。$B|TInterface\\Icons\\Ability_Mount_Charger.blp:32|t', `MaleText_loc5`='對衝鋒標靶使用破盾。$B|TInterface\\Icons\\Ability_Warrior_ShieldBreak.blp:32|t$B當目標脆弱的時候對它使用衝鋒。$B|TInterface\\Icons\\Ability_Mount_Charger.blp:32|t', `MaleText_loc7`='Emplea Romper escudo contra un objetivo de carga.$B|TInterfaceIconsAbility_Warrior_ShieldBreak.blp:32|t$BA continuación utiliza Cargar mientras el objetivo sea vulnerable.$B|TInterfaceIconsAbility_Mount_Charger.blp:32|t', `FemaleText_loc1`='돌진 표적에 방패 부수기를 사용합니다.$B|Tinterface\\Icons\\Ability_Warrior_ShieldBreak.blp:32|t$B표적이 무력화되었을 때 이어서 돌진으로 공격합니다.$B|Tinterface\\Icons\\Ability_Mount_Charger.blp:32|t', `FemaleText_loc4`='对冲锋目标使用碎盾。$B|TInterface\\Icons\\Ability_Warrior_ShieldBreak.blp:32|t$B趁目标处于脆弱状态时立即冲锋。$B|TInterface\\Icons\\Ability_Mount_Charger.blp:32|t', `FemaleText_loc5`='對衝鋒標靶使用破盾。$B|TInterface\\Icons\\Ability_Warrior_ShieldBreak.blp:32|t$B當目標脆弱的時候對它使用衝鋒。$B|TInterface\\Icons\\Ability_Mount_Charger.blp:32|t', `FemaleText_loc7`='Emplea Romper escudo contra un objetivo de carga.$B|TInterfaceIconsAbility_Warrior_ShieldBreak.blp:32|t$BA continuación utiliza Cargar mientras el objetivo sea vulnerable.$B|TInterfaceIconsAbility_Mount_Charger.blp:32|t' WHERE `ID`=34034;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원거리 표적에 방패 부수기를 사용합니다.$B|Tinterface\\Icons\\Ability_Warrior_ShieldBreak.blp:32|t$B표적에 방어가 사라진 동안 방패 부수기를 사용합니다.$B|Tinterface\\Icons\\Ability_Warrior_ShieldBreak.blp:32|t', `MaleText_loc4`='对远程目标使用碎盾。$B|TInterface\\Icons\\Ability_Warrior_ShieldBreak.blp:32|t$B趁目标毫无防御力时再次碎盾。$B|TInterface\\Icons\\Ability_Warrior_ShieldBreak.blp:32|t', `MaleText_loc5`='對遠程標靶使用破盾。$B|TInterface\\Icons\\Ability_Warrior_ShieldBreak.blp:32|t$B然後在標靶毫無防備的時候對它使用破盾。$B|TInterface\\Icons\\Ability_Warrior_ShieldBreak.blp:32|t', `MaleText_loc7`='Emplea Romper escudo contra un objetivo a distancia.$B|TInterfaceIconsAbility_Warrior_ShieldBreak.blp:32|t$BDespués utiliza Romper escudo mientras el objetivo esté indefenso.$B|TInterfaceIconsAbility_Warrior_ShieldBreak.blp:32|t', `FemaleText_loc1`='원거리 표적에 방패 부수기를 사용합니다.$B|TInterface\\Icons\\Ability_Warrior_ShieldBreak.blp:32|t$B표적에 방어가 사라진 동안 방패 부수기를 사용합니다.$B|Tinterface\\Icons\\Ability_Warrior_ShieldBreak.blp:32|t', `FemaleText_loc4`='对远程目标使用碎盾。$B|TInterface\\Icons\\Ability_Warrior_ShieldBreak.blp:32|t$B趁目标毫无防御力时再次碎盾。$B|TInterface\\Icons\\Ability_Warrior_ShieldBreak.blp:32|t', `FemaleText_loc5`='對遠程標靶使用破盾。$B|TInterface\\Icons\\Ability_Warrior_ShieldBreak.blp:32|t$B然後在標靶毫無防備的時候對它使用破盾。$B|TInterface\\Icons\\Ability_Warrior_ShieldBreak.blp:32|t', `FemaleText_loc7`='Emplea Romper escudo contra un objetivo a distancia.$B|TInterfaceIconsAbility_Warrior_ShieldBreak.blp:32|t$BDespués utiliza Romper escudo mientras el objetivo esté indefenso.$B|TInterfaceIconsAbility_Warrior_ShieldBreak.blp:32|t' WHERE `ID`=34035;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그릇에서 나는 강한 향은 타는 머리와 여러 향료의 혼합물과 같은 냄새입니다.', `MaleText_loc4`='这只碗里散发出强烈的气味，闻起来好象是各种草药和燃烧的毛发混合在一起。', `MaleText_loc5`='從碗中傳出來的濃濃味道聞起來就像是混合草藥和燒焦的頭髮。', `MaleText_loc7`='El fuerte aroma que sale del cuenco huele como una mezcla de varias hierbas y pelo quemado.' WHERE `ID`=34036;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s의 마음속으로 가는 차원문이 열립니다!', `MaleText_loc4`='通往%s思维的传送门打开了！', `MaleText_loc5`='傳送門開啟進入%s的心靈!', `MaleText_loc7`='¡Se abren portales a la mente de %s!' WHERE `ID`=34037;
