UPDATE `locales_broadcast_text` SET `MaleText_loc1`='함께 토막나무 주둔지로 갈 준비가 되었습니다, 카드라크!', `MaleText_loc4`='我已经准备好和你一起去碎木岗哨了，卡德拉克！', `MaleText_loc5`='我準備好跟你一起去碎木了，卡德拉克!', `MaleText_loc7`='¡Kadrak, estoy listo para acompañarte a Puesto del Hachazo!', `FemaleText_loc1`='함께 토막나무 주둔지로 갈 준비가 되었습니다, 카드라크!', `FemaleText_loc4`='我已经准备好和你一起去碎木岗哨了，卡德拉克！', `FemaleText_loc5`='我準備好跟你一起去碎木了，卡德拉克!', `FemaleText_loc7`='¡Kadrak, estoy lista para acompañarte a Puesto del Hachazo!' WHERE `ID`=34040;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감시자 분석: 토림', `MaleText_loc4`='守护者分析：托里姆', `MaleText_loc5`='看守者分析:索林姆', `MaleText_loc7`='Análisis de vigía: Thorim', `FemaleText_loc1`='감시자 분석: 토림', `FemaleText_loc4`='守护者分析：托里姆', `FemaleText_loc5`='看守者分析:索林姆', `FemaleText_loc7`='Análisis de vigía: Thorim' WHERE `ID`=34041;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감시자 분석: 미미론', `MaleText_loc4`='守护者分析：米米尔隆', `MaleText_loc5`='看守者分析:彌米倫', `MaleText_loc7`='Análisis de vigía: Mimiron', `FemaleText_loc1`='감시자 분석: 미미론', `FemaleText_loc4`='守护者分析：米米尔隆', `FemaleText_loc5`='看守者分析:彌米倫', `FemaleText_loc7`='Análisis de vigía: Mimiron' WHERE `ID`=34042;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭풍우 하수인이 에말론을 지키려 모습을 드러냅니다!', `MaleText_loc4`='一只风暴爪牙冒出来帮助埃玛尔隆作战！', `MaleText_loc5`='一個暴雨爪牙出現要保護艾瑪隆!', `MaleText_loc7`='¡Aparece un esbirro tempestuoso para defender a Emalon!' WHERE `ID`=34043;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연기를 들이마셔 거대한 동물 영의 환영을 불러냅니다.', `MaleText_loc4`='吸入这股烟雾，吸引动物巨灵的注意。', `MaleText_loc5`='吸入這個濃煙來吸引偉大的動物靈魂的注意。', `MaleText_loc7`='Respira el humo para invocar visiones de grandes espíritus de animales.', `FemaleText_loc1`='연기를 들이마셔 거대한 동물 영의 환영을 불러냅니다.', `FemaleText_loc4`='吸入这股烟雾，吸引动物巨灵的注意。', `FemaleText_loc5`='吸入這個濃煙來吸引偉大的動物靈魂的注意。', `FemaleText_loc7`='Respira el humo para invocar visiones de grandes espíritus de animales.' WHERE `ID`=34044;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조금 있다가 다시 오겠습니다, 카드라크.', `MaleText_loc4`='我很快就会回来找你的，卡德拉克！', `MaleText_loc5`='我回頭再來找你，卡德拉克。', `MaleText_loc7`='Pronto me pondré en contacto contigo, Kadrak.', `FemaleText_loc1`='조금 있다가 다시 오겠습니다, 카드라크.', `FemaleText_loc4`='我很快就会回来找你的，卡德拉克！', `FemaleText_loc5`='我回頭再來找你，卡德拉克。', `FemaleText_loc7`='Pronto me pondré en contacto contigo, Kadrak.' WHERE `ID`=34045;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='브루터스크는 지금 밖의 나무들에 물을 주러 갔네.$b$b그래도 여기서 좀 기다리게, $n. 곧 브루터스크가 우리를 토막나무 주둔지로 태우고 갈 테니까.', `MaleText_loc4`='蛮角正在外面给那些矮树丛浇水。$b$b不过不要走太远，$n。他应该很快就会为我们前往碎木岗哨的旅程做好准备。', `MaleText_loc5`='蠻獠正在外面幫灌木叢澆水。$b$b但別走太遠，$n。很快他就可以載我們到碎木了。', `MaleText_loc7`='Brutusk ha salido a regar los arbustos.$b$bPero no te alejes, $n. Estará listo para nuestro viaje al Hachazo muy pronto.' WHERE `ID`=34046;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제... 제 주인을 만난 전투코도의 강력한 힘을 느껴보게!', `MaleText_loc4`='现在……见证战斗科多兽在一位大师手中所能发挥出的力量吧！', `MaleText_loc5`='現在...見證在大師手中的戰鬥科多獸能發揮多大的力量!', `MaleText_loc7`='Ahora... ¡observa el poder de un kodo de guerra a manos de un maestro!' WHERE `ID`=34047;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; "복수하리라!"라고 외칩니다.', `MaleText_loc4`='%s高声喊道：“我会报仇的！”', `MaleText_loc5`='%s大喊:「我會報仇的!」', `MaleText_loc7`='%s grita: "¡Obtendré mi venganza!"' WHERE `ID`=34048;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='토막나무 주둔지로!', `MaleText_loc4`='前往碎木！', `MaleText_loc5`='往碎木前進!', `MaleText_loc7`='¡A Puesto del Hachazo!' WHERE `ID`=34049;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음의 군단과 마주하고는, 살아나갈 수 있을 줄 알았나?', `MaleText_loc4`='你以为自己能跟不生不死的军团抗衡？', `MaleText_loc5`='你以為對抗死亡軍團有可能僥倖存活?', `MaleText_loc7`='¿Esperabas enfrentarte a las legiones de la muerte y sobrevivir?' WHERE `ID`=34050;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저항이란... 필멸자가 지닌 결함이지.', `MaleText_loc4`='反抗……凡人性的瑕疵。', `MaleText_loc5`='反抗...凡人的缺陷。', `MaleText_loc7`='Rebeldía… un defecto de la mortalidad.' WHERE `ID`=34051;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희는 당연히 패배할 터였어.', `MaleText_loc4`='你们的失败是命中注定的。', `MaleText_loc5`='你的失敗是必然的。', `MaleText_loc7`='Tu derrota era inevitable.' WHERE `ID`=34052;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희의 파멸은 새로운 고통의 시대를 열 것이다!', `MaleText_loc4`='你们的毁灭预示着痛苦的新时代即将降临！', `MaleText_loc5`='你的毀滅將會預告一個嶄新苦難時代的來臨!', `MaleText_loc7`='¡Tu destrucción presagiará una nueva era de sufrimiento!' WHERE `ID`=34053;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 어떤 공포가 날 기다릴지...', `MaleText_loc4`='哦，真正的恐惧还在前方……', `MaleText_loc5`='噢，怎樣的驚恐在等著...', `MaleText_loc7`='Ah, los horrores que me esperan…' WHERE `ID`=34054;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요그사론의 검은 피가 내 안을 달린다! 날 멈출 수는 없어!', `MaleText_loc4`='尤格-萨隆的黑血在我的体内奔涌！我，无坚不摧！', `MaleText_loc5`='尤格薩倫的黑血在我體內流動!我‧是‧無敵的!', `MaleText_loc7`='¡La sangre negra de Yogg-Saron me recorre! SOY. ¡IMPARABLE!' WHERE `ID`=34055;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지켜보아라. 절대 공포를!', `MaleText_loc4`='看吧，绝对的恐怖！', `MaleText_loc5`='看著:絕對的恐懼!', `MaleText_loc7`='¡Contemplen el terror absoluto!' WHERE `ID`=34056;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 분노에 휩싸여 광폭해집니다!', `MaleText_loc4`='%s变得狂暴不已！', `MaleText_loc5`='%s陷入狂暴的怒火中!', `MaleText_loc7`='¡%s monta en cólera!' WHERE `ID`=34057;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분석 결과, 전방에서 투기장으로 접근한 후 두 번째 부대를 지상 측면 통로로 분리하는 전략이 도출되었습니다. 이로써 외부 존재의 정신 지배가 완료되기 전에 토림의 관람석에 도착할 확률을 극대화합니다.', `MaleText_loc4`='战术分析结果显示，最佳方案为从前方进入竞技场，同时派遣另一支分队通过位于底层的小路。要在外部影响完全控制托里姆的心智之前抵达他所在的高台，这是成功率最高的方案。', `MaleText_loc5`='戰術分析建議由正面的競技場靠近，並分出第二支隊伍通過地面的側邊走道。這樣最有可能在外在影響的心靈控制全面支配他之前抵達索林姆的瞰臺。', `MaleText_loc7`='El análisis táctico sugiere acercarse a la arena por el frente y separar una fuerza secundaria que entre por un pasaje lateral a nivel del suelo, maximizando las chances de ser vistos por Thorim antes de que la dominación mental esté completa.' WHERE `ID`=34058;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호디르의 인장을 되찾으려면 보관함을 보호해야 합니다.', `MaleText_loc4`='霍迪尔的徽记被放在一只用来保存神器的宝箱中。', `MaleText_loc5`='保護箱子是確保霍迪爾符印的關鍵。', `MaleText_loc7`='Preservar el depósito es esencial para obtener el sello de Hodir.' WHERE `ID`=34059;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠시만 기다려라.', `MaleText_loc4`='请坚持一段时间不要动。', `MaleText_loc5`='請稍等一下。', `MaleText_loc7`='No te muevas durante un momento.' WHERE `ID`=34060;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조각 분석을 진행 중입니다.', `MaleText_loc4`='正在进行碎片分析。', `MaleText_loc5`='碎片分析進行中。', `MaleText_loc7`='Análisis del fragmento iniciado.' WHERE `ID`=34061;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='개체 식별. 고대 왕의 망치, 발아니르입니다.', `MaleText_loc4`='目标确认：瓦兰奈尔，远古王者之锤。', `MaleText_loc5`='物品鑑定完成:瓦蘭尼珥，遠古諸王之錘。', `MaleText_loc7`='Identificado: Val''anyr, martillo de los reyes ancestrales.' WHERE `ID`=34062;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='티탄이 직접 창조한 발아니르는 첫 번째 토석인 왕 우렐 스톤하트에게 주어졌습니다. 스톤하트는 망치로 형제들을 창조하고 생명을 불어 넣었습니다.', `MaleText_loc4`='泰坦亲自铸造了瓦兰奈尔，并将其交给了第一位土灵之王，尤雷尔·石心。通过这柄圣锤，他可以制造新的土灵，并赐予他们生命。', `MaleText_loc5`='由泰坦所製造，瓦蘭尼珥被賜給了第一位土靈之王，厄瑞·石心。他用這把錘子創造他的同胞並且賦予他們生命。', `MaleText_loc7`='Creado por los mismos titanes, Val''anyr fue dado al primer rey terráneo, Urel Corazondepiedra, para que creara y diera vida al resto de sus hermanos.' WHERE `ID`=34063;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발아니르는 토석인과 무쇠 드워프의 첫 번째 전쟁 때 파괴되었습니다. 무기의 파편은 유실되었다고 알려졌습니다.', `MaleText_loc4`='在土灵和铁矮人之间爆发的第一次战争中，瓦兰奈尔碎裂了。据信它的残片已在战争中遗失。', `MaleText_loc5`='瓦蘭尼珥在土靈與鐵矮人的第一次戰爭時被粉碎。這柄武器的碎片據信在戰爭中失落。', `MaleText_loc7`='Val''anyr se destrozó durante la primera guerra entre los terráneos y los enanos férreos. Se creía que sus restos se habían perdido en el conflicto.' WHERE `ID`=34064;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='현재까지 알려진 일반적인 방법으로 복구에 성공할 확률은 0에 가깝습니다. 이론적인 방법이 분석될 때까지 대기하십시오.', `MaleText_loc4`='通过这个世界上实际存在的常规手段修复瓦兰奈尔的可能性趋近于零。正在分析理论上可能存在的修复方式，请稍候。', `MaleText_loc5`='要將它成功地修復到原有的模樣在這個世界中可能性趨近於零。請稍等，目前在分析假設性方法。', `MaleText_loc7`='La probabilidad de reconstrucción exitosa mediante los medios disponibles en este mundo es casi nula. Analizando medios hipotéticos.' WHERE `ID`=34065;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이론적으로 요그사론이라는 존재 내부에는 사로나이트를 액체로 변환하는 강력한 산성 물질이 수용되어 있습니다. 티탄이 만든 합금을 그 안에 담그면 금속 조직을 재결합할 수 있습니다.', `MaleText_loc4`='在名为尤格-萨隆的生物体内，理论上存在一种酸性极强的物质，可以将萨隆邪铁液化。泰坦铸成的合金可能通过浸没在此物质中重新熔合。', `MaleText_loc5`='理論上已知名為尤格薩倫的存在體身上可以取得極強的酸性物質，用來將薩鋼液化。將泰坦合金浸入這種物質中或許能使之重新融合。', `MaleText_loc7`='Hipotéticamente, el contenido ácido dentro del ser llamado Yogg-Saron causaría la licuación de la saronita. La inmersión en esta sustancia podría bastar para restaurar una aleación de origen titánico.' WHERE `ID`=34066;
