UPDATE `locales_broadcast_text` SET `MaleText_loc1`='딱 좋군요. 그럼 신호를 보내버립시다.', `MaleText_loc4`='来得正是时候。我们赶紧搞定这件事吧。', `MaleText_loc5`='剛好趕上。那麼，讓我們把這件事解決。', `MaleText_loc7`='Justo a tiempo. Veamos qué pasa.' WHERE `ID`=34084;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 우지직거리면서 정제되지 않은 에너지로 소용돌이칩니다.', `MaleText_loc4`='%s发出劈啪声，浑身涌动着原始的力量！', `MaleText_loc5`='%s發出爆裂聲並帶著沛然能量湧來!', `MaleText_loc7`='¡%s crepita y se alza con energía pura!' WHERE `ID`=34085;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 계산을 좀 잘못한 것 같군. 감옥에 갇힌 마귀가 내 마음을 타락시키고 제1지시를 재정의하고 말았다. 이제 모든 시스템이 제 기능을 찾았다. 정상이다.', `MaleText_loc4`='看起来我的计算有一点小小的偏差。监狱中的恶魔侵蚀了我的思维，篡改了我的主要指令。所有系统都已恢复正常。完毕。', `MaleText_loc5`='看來我還是產生了些許計算錯誤。任由我的心智受到囚牢中魔鬼的腐化，棄我的首要職責於不顧。所有的系統看起來都正常運作。報告完畢。', `MaleText_loc7`='Aparentemente cometí un error de cálculos. Permití que mi mente fuera corrompida por el enemigo en la prisión, descartando mi directiva primaria. Todos los sistemas parecen estar funcionando nuevamente. Cambio.' WHERE `ID`=34086;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들에게 피와 번개의 축복이 무슨 뜻인지 가르쳐주게!', `MaleText_loc4`='让他们明白鲜血与雷鸣的意义！', `MaleText_loc5`='教教他們鮮血與雷霆的含意!', `MaleText_loc7`='¡Enséñales el significado de sangre y truenos!' WHERE `ID`=34087;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끝났다. 영이 그대와 연결되었으니 어둠해안에 있는 동안에는 그대와 함께할 것이다. 자연을 잘 섬기기를.', `MaleText_loc4`='结束了。我们还需要再等待一段时间，这个祝福才能生根发芽。但只要你在黑海岸，随时都能接受这一祝福。愿你继续为自然贡献力量。', `MaleText_loc5`='完成了。魂靈已經和你綁定，只要你在黑海岸，任何時候都會與你同在。願你為自然帶來佳音。', `MaleText_loc7`='Ya está. El espíritu está vinculado a ti y lo llevarás contigo siempre que estés en Costa Oscura. Que sirvas bien a la naturaleza.' WHERE `ID`=34088;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 기술을 가르쳐 드리기에 앞서 마상시합 탈것을 타셔야 합니다.$B$B창을 착용하고 당신 진영의 막사 밖에 있는 마상시합 탈것을 찾아보세요.', `MaleText_loc4`='你必须骑上锦标赛坐骑，我才能教你如何骑乘作战。$B$B拿上一支长枪，然后从你所在阵营的兽栏中挑选一匹坐骑吧。', `MaleText_loc5`='在我開始指導你之前，你必須要先騎上一隻聯賽坐騎。$B$B裝備一把長槍並從你陣營亭閣外找到一隻聯賽坐騎。', `MaleText_loc7`='Antes de que pueda instruirte, debes montar una montura de torneo.$b$bEquipa tu lanza y busca tu montura de torneo justo frente al pabellón de tu facción.' WHERE `ID`=34089;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방어와 찌르기에 대해서 자세히 말씀해 주십시오.', `MaleText_loc4`='我想知道更多关于防御和刺击的技巧。', `MaleText_loc5`='告訴我更多關於防禦與戳刺的事情。', `MaleText_loc7`='Cuéntame más sobre Defender y Estocada.', `FemaleText_loc1`='방어와 찌르기에 대해서 자세히 말씀해 주세요.', `FemaleText_loc4`='我想知道更多关于防御和刺击的技巧。', `FemaleText_loc5`='告訴我更多關於防禦與戳刺的事情。', `FemaleText_loc7`='Cuéntame más sobre Defender y Estocada.' WHERE `ID`=34090;
