UPDATE `locales_broadcast_text` SET `MaleText_loc1`='워, 잠깐만요, $r님!$B$B아이언포지의 용사들만이 제가 보유한 물건들을 구입하실 수 있습니다.', `MaleText_loc4`='急什么呢，$r！$B$B只有铁炉堡的勇士才有资格从我这里购买物品。', `MaleText_loc5`='別急，$r!$B$B只有鐵爐堡勇士才有辦法購買我賣的東西。', `MaleText_loc7`='¡No tan deprisa, $r!$b$bSolo los Campeones de Forjaz pueden comprar lo que tengo en venta.' WHERE `ID`=34116;
