UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$r|1이여;여;, 용서하시오. 썬더 블러프의 용사들만이 내가 보유한 물건을 구입할 수 있소이다.', `MaleText_loc4`='很抱歉，$r。只有雷霆崖的勇士才有资格从我这里购买物品。', `MaleText_loc5`='抱歉，$r，只有雷霆崖的勇士才能購買我賣的東西。', `MaleText_loc7`='Disculpa, $r, pero solo los Campeones de Cima del Trueno pueden comprar lo que tengo en venta.' WHERE `ID`=34120;
