UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저리 가 주시지요, $c!$B$B언더시티의 용사들만 제가 보유한 물건을 구입하실 수 있으니까요.', `FemaleText_loc4`='走吧，$r！$B$B只有幽暗城的勇士才有资格从我这里购买物品。', `FemaleText_loc5`='一邊去，$c!$B$B只有幽暗城勇士才能購買我賣的東西。', `FemaleText_loc7`='¡Largo de aquí, $c!$b$bSolo los Campeones de Entrañas pueden comprar lo que tengo en venta.' WHERE `ID`=34122;
