UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요!$B$B죄송합니다만 놈리건의 용사들만 제가 보유한 물건을 사실 수 있답니다.', `FemaleText_loc4`='嗨，朋友！$B$B很抱歉，只有诺莫瑞根的勇士才有资格从我这里购买物品。', `FemaleText_loc5`='你好啊!$B$B抱歉，朋友，只有諾姆瑞根的勇士能買我的東西。', `FemaleText_loc7`='¡Hola!$b$bPerdona, pero solo los Campeones de Gnomeregan pueden comprar lo que tengo.' WHERE `ID`=34131;
