UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사맘바 생각으로는 당신은 잘못된 병참장교를 찾아오신 것 같군요!$B$B사맘바가 보유한 물건은 센진의 용사들만을 위한 거랍니다.', `FemaleText_loc4`='萨玛巴认为你找错了军需官！$B$B只有森金村的勇士才有资格从她这里购买物品。', `FemaleText_loc5`='沙瑪巴覺得你找錯軍需官了!$B$B她的東西只賣給森金勇士...', `FemaleText_loc7`='¡Samamba piensa que eh''táh en el lugá'' equivoca''o! $b$bLo que tiene eh'' solo p''a los Campeones de Sen''jin...' WHERE `ID`=34136;
