UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앞에 보이는 기둥 아래쪽에 있는 문에서 무쇠 드워프들이 쏟아져 나오고 있습니다! 입구를 파괴하세요. 그럼 놈들도 후퇴할 겁니다!', `MaleText_loc4`='快看你正前方那些柱子底部的掩体，铁矮人正源源不断地从里面冒出来！摧毁那些掩体，他们就不得不撤退了！', `MaleText_loc5`='鐵矮人看來是從碉堡中出現，就在你前方的支柱底部!摧毀碉堡，他們就必須要撤退!', `MaleText_loc7`='¡Los enanos férreos han emergido de los búnkeres en la base de los pilares frente a ustedes! ¡Destruyan los búnkeres y los harán replegarse!' WHERE `ID`=34145;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하세요! 정찰 편대가 보고하길 미사일 격납고 발전기에 동력이 들어오고 있다는군요!', `MaleText_loc4`='小心！我们的空中侦察人员报告说，导弹发射井的能源塔已经开始启动了！', `MaleText_loc5`='當心!我們的空中斥候回報說飛彈發射井的動力裝置已經啟動!', `MaleText_loc7`='¡Cuidado! ¡Nuestros exploradores aéreos reportan que  los silos militares se están activando!' WHERE `ID`=34146;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방어 구조물에 동력을 공급하는 네 개의 발전기가 있습니다. 그 발전기를 파괴하면 미사일 공격이 멈출 거예요!', `MaleText_loc4`='总共有四座能源塔为这些防御设施提供能量。如果你们能炸掉那些塔，导弹攻击就会立即停止！', `MaleText_loc5`='一共有四個動力裝置在提供防禦建築能量。只要你能夠破壞動力裝置，飛彈攻擊就會停止!', `MaleText_loc7`='Hay cuatro generadores que alimentan las estructuras defensivas. ¡Si sabotean los generadores detendrán a los misiles!' WHERE `ID`=34147;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 탑은 호디르의 망치에 동력을 공급하죠. 그 힘은 부대 전체를 얼려 버릴 만큼 무시무시하다고 들었습니다!', `MaleText_loc4`='这座塔为霍迪尔之锤提供能量。据说它可以把整支军队冻成冰块！', `MaleText_loc5`='這座塔提供霍迪爾之錘的能量。傳說它的威力足以將一整支軍隊變成冰塊!', `MaleText_loc7`='Esta torre alimenta el Martillo de Hodir. ¡Se dice que tiene el poder de congelar ejércitos enteros!' WHERE `ID`=34148;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='프레이야의 탑에 접근 중이시군요. 메마른 황무지라도 단 하룻밤 새에 생기 넘치는 정글로 바꿀 수 있는 힘이 그 안에 있다더군요.', `MaleText_loc4`='这就是弗蕾亚之塔。它所拥有的力量可以在一夜之间将贫瘠的荒漠变成生机盎然的丛林。', `MaleText_loc5`='你正在靠近芙蕾雅之塔。它蘊藏著能夠將荒地在一夜之間變成叢林的力量。', `MaleText_loc7`='Están acercándose a la torre de Freya. La torre tiene el poder de convertir páramos estériles en junglas llenas de vida en poco tiempo.' WHERE `ID`=34149;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 발전기는 미미론의 눈에 동력을 공급합니다. 힘이 모이게 내버려 두면 안 돼요. 순식간에 흙을 바수고 돌을 녹인다고요!', `MaleText_loc4`='这座塔为米米尔隆之眼提供能量。只要一瞬间的工夫，它就可以把大地烧成灰烬，石块熔为岩浆——绝不能让它达到最大功率！', `MaleText_loc5`='這個裝置提供彌米倫凝視的能量。它能瞬間把大地化為灰燼，把石頭變成熔岩--不能讓它完成充能!', `MaleText_loc7`='Este generador alimenta la Mirada de Mimiron. Vuelve la tierra en ceniza, la piedra en magma... ¡Que no alcance su máximo poder!' WHERE `ID`=34150;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 크롤미르의 탑입니다. 딱 한 번 토림의 힘이 사용된 적이 있는데... 대륙 하나가 그냥 먼지가 되어 버렸다고 하더군요.', `MaleText_loc4`='啊，科洛米尔之塔。据说托里姆的威力只展现过一次……结果就是整整一块陆地变成了灰尘。', `MaleText_loc5`='喔，克洛米爾之塔。傳說索林姆的力量只使用過一次...它將整個大陸化為塵土。', `MaleText_loc7`='Ah, la torre de Krolmir. Se dice que el poder de Thorim se usó sólo una vez... Y convirtió un continente entero en polvo.' WHERE `ID`=34151;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미사일 발전기를 제어하는 장치는 탑 꼭대기에 있어요. 거기 가실 수만 있으면, 직접 끄실 수도 있을 겁니다.', `MaleText_loc4`='导弹能量塔的控制器就在塔顶。如果你能想办法上去，就可以自己动手关掉它。', `MaleText_loc5`='飛彈動力裝置的控制器就在塔頂。如果你們能找到方法上去，就能自行關閉它。', `MaleText_loc7`='El control del generador de misiles está en el último piso de la torre. Si encuentran la manera de alcanzarlo pueden apagarlo ustedes mismos.' WHERE `ID`=34152;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='근처에 자동수리소가 있나 보군요! 단상 위로 탈것을 몰고 가시면 자동으로 수리가 될 겁니다.', `MaleText_loc4`='你附近似乎有一座维修站！把你的座驾开到平台上去，接受自动修理。', `MaleText_loc5`='看來你已經靠近維修站了!把你的載具開上平臺，它就會自動進行維修。', `MaleText_loc7`='¡Están cerca de una estación de reparación! Detengan su vehículo en la plataforma y se reparará automáticamente.' WHERE `ID`=34153;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해내셨군요! 울두아르의 방어선을 무너뜨렸어요! 몇 분만 지나면 우린 이제...', `MaleText_loc4`='成功了！你瓦解了奥杜尔的防御设施。用不了多久，我们就可以进入……', `MaleText_loc5`='你辦到了!你突破了奧杜亞的防護。再過一會我們就能進入...', `MaleText_loc7`='¡Lo lograron! Rompieron las defensas de Ulduar. En pocos momentos, llegaremos a…' WHERE `ID`=34154;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저건 뭐야? 조심하세요! 뭔가 다가오고 있어요!', `MaleText_loc4`='那是什么？当心！有什么东西朝你去了！', `MaleText_loc5`='那是什麼?小心!有東西向你靠近!', `MaleText_loc7`='¿Qué es eso? ¡Cuidado! ¡Algo se dirige hacia ustedes!' WHERE `ID`=34155;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빨리요! 비상 회피! 비상 회피!', `MaleText_loc4`='小心！规避动作！规避——', `MaleText_loc5`='快!快!閃避飛行!閃避飛--', `MaleText_loc7`='¡Rápido! ¡Acción evasiva! ¡Acción evasiva…' WHERE `ID`=34156;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아요! 움직입시다. 차량에 올라타세요. 이제부터 무전기로 말씀드리죠.', `MaleText_loc4`='好了！我们出发吧。钻进你的战车里，我会通过无线电跟你保持联络！', `MaleText_loc5`='好啦!出發吧。爬進你的機器裡，等下我會透過無線電跟你們聯絡!', `MaleText_loc7`='¡Venga, en marcha! A las máquinas; os hablaré por la radio.' WHERE `ID`=34157;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마을의 남동쪽에 있는 다리에 들려보시기 바랍니다. 폐허로 그대를 데려다 줄 밤호랑이들을 만날 수 있을 겁니다.', `FemaleText_loc4`='一定要到城东南的桥那里去看看。你应该能在那里得到一头夜刃豹，载你到废墟那里去。', `FemaleText_loc5`='別忘了在城鎮東南方的橋停一下。你應該可以拿到一隻夜刃豹來帶你去廢墟那。', `FemaleText_loc7`='No te olvides de parar al lado de los puentes al sureste del pueblo. Deberías poder conseguir un sable de la noche para ir hasta las ruinas.' WHERE `ID`=34158;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마을 남동쪽 다리 근처에서 우리 전초 기지에 타고 갈 이동 수단을 찾는 걸 잊지 마십시오.', `FemaleText_loc4`='不要忘记在城东南的桥附近看看，你能在那里找到坐骑，前往我们的前哨站。', `FemaleText_loc5`='到城鎮東南方的橋時別忘了注意一下，有可以帶你到我們前哨的交通工具。', `FemaleText_loc7`='Acuérdate de mirar cerca de los puentes al sureste del pueblo para encontrar una forma de ir hasta nuestra avanzada.' WHERE `ID`=34159;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대가를 치르게 해줘라, 브루터스크!', `MaleText_loc4`='蛮角，让他们付出代价！', `MaleText_loc5`='讓他們付出代價，蠻獠!', `MaleText_loc7`='¡Dales duro, Brutusk!' WHERE `ID`=34160;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 해냈습니다! 알갈론보다 먼저 도착했다고요. 아마 시스템을 조작하면 알갈론의 분석을 방해할 수 있을...', `MaleText_loc4`='我们成功了，伙计们！终于抢在奥尔加隆前面来到了这里。也许我们可以对系统做点手脚，改变他的分析结果——', `MaleText_loc5`='我們辦到了，小夥子!我們搶在艾爾加隆之前趕到。說不定能對系統動點手腳，影響他的分析--', `MaleText_loc7`='¡Lo logramos! Llegamos antes que Algalon. Tal vez podamos alterar el sistema para interferir en su análisis…' WHERE `ID`=34161;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 수호 야수를 깨우기 시작합니다!', `FemaleText_loc4`='%s激活了野性防御者！', `FemaleText_loc5`='%s開始啟動野性防衛者!', `FemaleText_loc7`='¡%s comienza a activar el Defensor feral!' WHERE `ID`=34162;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 육체를 내 놓아라!', `MaleText_loc4`='你的血肉将不再属于你！', `MaleText_loc5`='你將失去你的血肉!', `MaleText_loc7`='¡Tu carne está perdida!' WHERE `ID`=34163;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피와 번개의 축복을!', `MaleText_loc4`='鲜血与雷鸣！', `MaleText_loc5`='鮮血與雷霆!', `MaleText_loc7`='¡Sangre y truenos!', `FemaleText_loc1`='피와 번개의 축복을!', `FemaleText_loc4`='鲜血与雷鸣！', `FemaleText_loc5`='鮮血與雷霆!', `FemaleText_loc7`='¡Sangre y truenos!' WHERE `ID`=34164;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들을 몰아내라! 다르나서스로 다시 몰아내란 말이다!', `MaleText_loc4`='把他们赶回去！赶回到达纳苏斯！', `MaleText_loc5`='把他們壓回去!回到達納蘇斯!', `MaleText_loc7`='¡Recházenlos! ¡Que vuelvan a Darnassus!' WHERE `ID`=34165;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 그 가엾은 발톱으로 뒤져 찾아낸 종잇조각이라면 뭐든 봐야겠다.', `MaleText_loc4`='把你们的脏爪子翻到的任何纸片儿都送来给我过目。', `MaleText_loc5`='我要看到你們這些蠢貨的爪子所碰到的所有紙片。', `MaleText_loc7`='Quiero ver hasta el último pedazo de papel sobre el que pongáis las garras, miserables.' WHERE `ID`=34166;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='먹어치우기 전에 시체를 뒤져라!', `MaleText_loc4`='我说过了，在你吃尸体前都先给我好好搜查一下！', `MaleText_loc5`='我說了，在吃掉前先搜一下!', `MaleText_loc7`='¡He dicho que REGISTREN los cuerpos antes de COMEROSLOS!' WHERE `ID`=34167;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모든 수단을 동원해서 찾아라. 말 그대로 하란 말이다, 이 부패한 덩어리들아! 필요하다면 이 지역을 완전히 부숴버려라.', `MaleText_loc4`='要把每块石头都翻一遍。执行我的命令，不许有半点折扣，烂家伙！如果有必要，就把这个地方翻个底朝天。', `MaleText_loc5`='你們這些腐爛的東西!搜遍這所有的角落，我是認真的。把這個地方翻過來都沒關係!', `MaleText_loc7`='No dejéis ni una piedra sin levantar. ¡Lo digo literalmente, sacos de descomposición! Destrozad este lugar si es necesario.' WHERE `ID`=34168;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 말에서 내려 나와 1대 1로 싸워보자!', `MaleText_loc4`='下马来，敢不敢和我单挑！', `MaleText_loc5`='有種下馬來跟我單挑!', `MaleText_loc7`='¡Baja de ese caballo y lucha conmigo cara a cara!' WHERE `ID`=34169;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 암흑 강화를 시전하려고 합니다!', `MaleText_loc4`='%s准备施放暗影强化！', `MaleText_loc5`='%s準備釋放強能暗影!', `MaleText_loc7`='¡%s se prepara para lanzar Sombras potenciadas!' WHERE `ID`=34170;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='브루터스크... 으...아...아...아...안 돼!!', `MaleText_loc4`='蛮角……不！！！', `MaleText_loc5`='蠻獠...不要啊!!', `MaleText_loc7`='Brutusk... ¡NOOOOOO!!' WHERE `ID`=34171;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두... 즉시 토막나무 주둔지로 돌아간다!', `MaleText_loc4`='所有人……立刻返回碎木岗哨！', `MaleText_loc5`='全部人...馬上回到碎木!', `MaleText_loc7`='¡Todos! ¡Retroceded hacia Puesto del Hachazo, ahora!' WHERE `ID`=34172;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보충 차량을 준비하기가 퍽 어려웠답니다. 저희가 시간을 들인 보람이 있게 해 주세요, 그래 주실 거죠?', `MaleText_loc4`='搞到这些替换器械可不容易。别让我们白费力气，好吗？', `MaleText_loc5`='把這些備用零件弄來這兒可不容易。讓我們的努力有點價值，沒問題吧?', `MaleText_loc7`='Hacer llegar estos recambios hasta aquí no fue fácil. Haz que el esfuerzo valga la pena, ¿vale?', `FemaleText_loc1`='보충 차량을 준비하기가 퍽 어려웠답니다. 저희가 시간을 들인 보람이 있게 해 주세요, 그래 주실 거죠?', `FemaleText_loc4`='搞到这些替换器械可不容易。别让我们白费力气，好吗？', `FemaleText_loc5`='把這些備用零件弄來這兒可不容易。讓我們的努力有點價值，沒問題吧?', `FemaleText_loc7`='Hacer llegar estos recambios hasta aquí no fue fácil. Haz que el esfuerzo valga la pena, ¿vale?' WHERE `ID`=34173;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번엔 해치우실 겁니다. 봐주지 마세요!', `MaleText_loc4`='这次你一定能击溃他们。不要手软！', `MaleText_loc5`='這次一定沒問題的。別手下留情!', `MaleText_loc7`='Esta vez lo lograréis. ¡No tengáis piedad!', `FemaleText_loc1`='이번엔 해치우실 거예요. 봐주지 마세요!', `FemaleText_loc4`='这次你一定能击溃他们。不要手软！', `FemaleText_loc5`='這次一定沒問題的。別手下留情!', `FemaleText_loc7`='Esta vez lo lograréis. ¡No tengáis piedad!' WHERE `ID`=34174;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로바로 여러분의 문앞까지 배달되는 보충 공성 차량! 이보다 더한 서비스는 없을 걸요!', `MaleText_loc4`='备用攻城器械立即送货上门。还有比这更好的服务吗？', `MaleText_loc5`='備用攻城載具很快就要到你門口啦。你不能期待比這更棒的服務了!', `MaleText_loc7`='Vehículos de asedio de reemplazo entregados a domicilio en un periquete. ¡No se puede pedir mejor servicio!', `FemaleText_loc1`='바로바로 여러분의 문앞까지 배달되는 보충 공성 차량! 이보다 더한 서비스는 없을 걸요!', `FemaleText_loc4`='备用攻城器械立即送货上门。还有比这更好的服务吗？', `FemaleText_loc5`='備用攻城載具很快就要到你門口啦。你不能期待比這更棒的服務了!', `FemaleText_loc7`='Vehículos de asedio de reemplazo entregados a domicilio en un periquete. ¡No se puede pedir mejor servicio!' WHERE `ID`=34175;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지난번은 그냥 연습이었어요, 그렇지요? 이번에 힘내세요!', `MaleText_loc4`='上一轮不过是热身而已！这次你一定要成功！', `MaleText_loc5`='上次只是練習，對吧?這次要來真的啦!', `MaleText_loc7`='Esta última fue para practicar, ¿verdad? ¡Ya tienes práctica!', `FemaleText_loc1`='지난번은 그냥 연습이었어요, 그죠? 이번에 힘내세요!', `FemaleText_loc4`='上一轮不过是热身而已！这次你一定要成功！', `FemaleText_loc5`='上次只是練習，對吧?這次要來真的啦!', `FemaleText_loc7`='Esta última fue para practicar, ¿verdad? ¡Ya tienes práctica!' WHERE `ID`=34176;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='걱정하실 것 없습니다. 저희가 보충 차량을 준비해 뒀거든요. 일이 항상 처음부터 잘되란 법은 없잖아요.', `MaleText_loc4`='别担心，我们已经备好了替换器械。你也知道，这种任务很难一次成功的嘛。', `MaleText_loc5`='一點都不用擔心，我們都把備用載具都準備好了。不能老是期待一次就成功，你懂的。', `MaleText_loc7`='No te preocupes lo más mínimo, tenemos recambios preparados. No siempre puedes esperar conseguirlo a la primera, ¿sabes?', `FemaleText_loc1`='걱정하실 것 없어요. 저희가 보충 차량을 준비해 뒀답니다. 일이 항상 처음부터 잘되란 법은 없잖아요.', `FemaleText_loc4`='别担心，我们已经备好了替换器械。你也知道，这种任务很难一次成功的嘛。', `FemaleText_loc5`='一點都不用擔心，我們都把備用載具都準備好了。不能老是期待一次就成功，你懂的。', `FemaleText_loc7`='No te preocupes lo más mínimo, tenemos recambios preparados. No siempre puedes esperar conseguirlo a la primera, ¿sabes?' WHERE `ID`=34177;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와, 진짜 큰 전차던데요! 당신은 담이 참 크시군요. 행운을 빕니다!', `MaleText_loc4`='嗨，瞧这辆大型攻城坦克！你可比我厉害多了。祝你好运！', `MaleText_loc5`='哇噢，超大一台坦克!你可比我有種多了。祝你好運啦!', `MaleText_loc7`='¡Guau, eso sí que es un tanque grande! Ustedes tienen más agallas que yo. ¡Les deseo suerte!', `FemaleText_loc1`='와, 진짜 큰 전차던데요! 당신은 담이 참 크시네요. 행운을 빌어요!', `FemaleText_loc4`='嗨，瞧这辆大型攻城坦克！你可比我厉害多了。祝你好运！', `FemaleText_loc5`='哇噢，超大一台坦克!你可比我有種多了。祝你好運啦!', `FemaleText_loc7`='¡Guau, eso sí que es un tanque grande! Ustedes tienen más agallas que yo. ¡Les deseo suerte!' WHERE `ID`=34178;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여러분 뒤엔 저희가 있습니다... 고쳐야 할 수많은 차량과 함께 말이죠.', `MaleText_loc4`='我们永远支持你……唔，我们这就开始修理这成堆的攻城器械。', `MaleText_loc5`='我們在後頭支援你...而且有一大堆載具都只有表面修好。', `MaleText_loc7`='Te tenemos a ti cubierto... y, por lo visto, a un buen montón de vehículos esperando reparaciones.', `FemaleText_loc1`='여러분 뒤엔 저희가 있어요... 고쳐야 할 수많은 차량과 함께 말이죠.', `FemaleText_loc4`='我们永远支持你……唔，我们这就开始修理这成堆的攻城器械。', `FemaleText_loc5`='我們在後頭支援你...而且有一大堆載具都只有表面修好。', `FemaleText_loc7`='Te tenemos a ti cubierto... y, por lo visto, a un buen montón de vehículos esperando reparaciones.' WHERE `ID`=34179;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으아아, 살살 다뤄 달라고 부탁했잖습니까. 제 마음과 영혼이 담긴 물건이라고요, 아세요? 이번엔 부디 조심하세요.', `MaleText_loc4`='啊，我说过让你好好照顾她的。你知道我在她身上倾注了多少心血吗？这次你可得小心点。', `MaleText_loc5`='噢，我告訴過你要小心照顧她。我可是對它灌注了我的全副心靈，你懂嗎?這次小心點。', `MaleText_loc7`='Oooh, te dije que la trataras con cuidado. Me he dedicado a esa cosa en cuerpo y alma, ¿sabes? Esta vez ten más cuidado.', `FemaleText_loc1`='으아아, 살살 다뤄 달라고 부탁했잖아요. 제 마음과 영혼이 담긴 물건이라고요, 아세요? 이번엔 부디 조심하세요.', `FemaleText_loc4`='啊，我说过让你好好照顾她的。你知道我在她身上倾注了多少心血吗？这次你可得小心点。', `FemaleText_loc5`='噢，我告訴過你要小心照顧她。我可是對它灌注了我的全副心靈，你懂嗎?這次小心點。', `FemaleText_loc7`='Oooh, te dije que la trataras con cuidado. Me he dedicado a esa cosa en cuerpo y alma, ¿sabes? Esta vez ten más cuidado.' WHERE `ID`=34180;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 덤불로 슬며시 들어갑니다.', `FemaleText_loc4`='%s悄无声息地滑入了草丛中。', `FemaleText_loc5`='%s安靜地鑽進了灌叢中。', `FemaleText_loc7`='%s se oculta silenciosamente entre los arbustos.' WHERE `ID`=34181;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='포위망이 뚫렸군... 지금 당장은 말이네. 나를 따라 토막나무 주둔지로 가세.', `MaleText_loc4`='围攻被击退了……至少暂时是如此。跟随我去碎木岗哨吧。', `MaleText_loc5`='攻城行動停止了...至少目前是。跟著我到碎木崗哨。', `MaleText_loc7`='El asedio se ha roto... por el momento. Sígueme a Puesto del Hachazo.' WHERE `ID`=34182;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전혀요. 죽어라 살펴봐도 어떻게 이걸 작동시키는지 전혀 모르겠어요.', `MaleText_loc4`='不行。我完全搞不明白这玩意儿是如何运作的。', `MaleText_loc5`='一點也不。我一輩子也搞不懂這是怎麼運作的。', `MaleText_loc7`='Ni una pizca. Por más que lo intente, no puedo averiguar cómo funciona esta cosa.', `FemaleText_loc1`='전혀요. 죽어라 살펴봐도 어떻게 이걸 작동시키는지 전혀 모르겠어요.', `FemaleText_loc4`='不行。我完全搞不明白这玩意儿是如何运作的。', `FemaleText_loc5`='一點也不。我一輩子也搞不懂這是怎麼運作的。', `FemaleText_loc7`='Ni una pizca. Por más que lo intente, no puedo averiguar cómo funciona esta cosa.' WHERE `ID`=34183;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋은 소식이라도?', `MaleText_loc4`='怎么样？', `MaleText_loc5`='運氣如何?', `MaleText_loc7`='¿Ha habido suerte?', `FemaleText_loc1`='좋은 소식이라도?', `FemaleText_loc4`='怎么样？', `FemaleText_loc5`='運氣如何?', `FemaleText_loc7`='¿Ha habido suerte?' WHERE `ID`=34184;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인이시여, 당신을 실망시키지 않겠습니다!', `MaleText_loc4`='我不会让你失望的，主人！', `MaleText_loc5`='我不會令您失望的，主人!', `MaleText_loc7`='¡No te fallaré, maestro!' WHERE `ID`=34185;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래도 계속 애써 주세요. 우리 짐작대로 이게 순간이동기라면, 공격에 대단히 유용할 겁니다.', `MaleText_loc4`='别灰心。如果这确实是传送器的话，那它对我们的进攻行动会很有帮助的。', `MaleText_loc5`='維持下去。如果我們猜得沒錯，這應該是傳送器，它對我們的攻擊能有極大的幫助。', `MaleText_loc7`='Sigue en ello. Si nuestras sospechas están en lo cierto y esto es un transporte, podría resultar extremadamente útil en nuestro asalto.', `FemaleText_loc1`='그래도 계속 애써 주세요. 우리 짐작대로 이게 순간이동기라면, 공격에 대단히 유용할 겁니다.', `FemaleText_loc4`='别灰心。如果这确实是传送器的话，那它对我们的进攻行动会很有帮助的。', `FemaleText_loc5`='維持下去。如果我們猜得沒錯，這應該是傳送器，它對我們的攻擊能有極大的幫助。', `FemaleText_loc7`='Sigue en ello. Si nuestras sospechas están en lo cierto y esto es un transporte, podría resultar extremadamente útil en nuestro asalto.' WHERE `ID`=34186;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알아요, 알아요... 아직 포기한 건 아니에요. 그래도 너무 기대하지는 마세요. 여기 사용된 기술은 제 수준을 한참 뛰어넘는다고요.', `MaleText_loc4`='嗯，我知道……我会继续尝试的。不过你也别抱太大的希望，这种科技完全超越了我能理解的范围。', `MaleText_loc5`='我知道，我知道...我可還沒放棄。但也別抱著太高希望，這種科技遠遠超過我所理解。', `MaleText_loc7`='Lo sé, lo sé... Todavía no me he rendido. Aunque no os ilusionéis, esta tecnología se escapa a mi alcance.', `FemaleText_loc1`='알아요, 알아요... 아직 포기한 건 아니에요. 그래도 너무 기대하지는 마세요. 여기 사용된 기술은 제 수준을 한참 뛰어넘는다고요.', `FemaleText_loc4`='嗯，我知道……我会继续尝试的。不过你也别抱太大的希望，这种科技完全超越了我能理解的范围。', `FemaleText_loc5`='我知道，我知道...我可還沒放棄。但也別抱著太高希望，這種科技遠遠超過我所理解。', `FemaleText_loc7`='Lo sé, lo sé... Todavía no me he rendido. Aunque no os ilusionéis, esta tecnología se escapa a mi alcance.' WHERE `ID`=34187;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈들의 시시한 분쟁은 나를 강하게 할 뿐...', `MaleText_loc4`='你们微不足道的抵抗只能让我变得更加强大。', `MaleText_loc5`='你們那些瑣碎的爭執只會讓我更加強大。', `MaleText_loc7`='Estos insignificantes ataques solo me hacen más fuerte…' WHERE `ID`=34188;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 망할 기계가 드디어 작동하기 시작했어요! 이걸 이용하면 광장 끝까지 바로 가실 수 있답니다. 왜, 거대 화염전차랑 마지막으로 싸우시던 곳 있잖아요.', `MaleText_loc4`='这该死的玩意儿总算运行起来了！它可以将你传送到广场尽头，就是之前你们与烈焰巨兽战斗的地方。', `MaleText_loc5`='這些該死的東西才剛開始運作!這會立刻將你帶到集合場的盡頭，你之前和烈焰戰輪交手的地方。', `MaleText_loc7`='¡Esta maldita cosa acaba de ponerse a funcionar! Esto debiera llevaros justo al final de la explanada, donde os enfrentasteis al Leviatán de llamas por última vez.', `FemaleText_loc1`='이 망할 기계가 드디어 작동하기 시작했어요! 이걸 이용하면 광장 끝까지 바로 가실 수 있답니다. 왜, 거대 화염전차랑 마지막으로 싸우시던 곳 있잖아요.', `FemaleText_loc4`='这该死的玩意儿总算运行起来了！它可以将你传送到广场尽头，就是之前你们与烈焰巨兽战斗的地方。', `FemaleText_loc5`='這些該死的東西才剛開始運作!這會立刻將你帶到集合場的盡頭，你之前和烈焰戰輪交手的地方。', `FemaleText_loc7`='¡Esta maldita cosa acaba de ponerse a funcionar! Esto debiera llevaros justo al final de la explanada, donde os enfrentasteis al Leviatán de llamas por última vez.' WHERE `ID`=34189;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보충 차량은 이미 그쪽으로 옮겨 놨어요. 요번엔 반드시 그놈을 잡으실 거예요. 행운을 빌어요!', `MaleText_loc4`='我们把备用的攻城器械都抬上来啦，这次你一定能把那家伙打倒。祝你好运！', `MaleText_loc5`='我們已經提升了備用載具的效能，希望你們這次能擊敗那個東西。祝好運!', `MaleText_loc7`='Ya hemos llevado los vehículos de reemplazo, así que ahora podéis derrotar a esa cosa. ¡Buena suerte!', `FemaleText_loc1`='보충 차량은 이미 그쪽으로 옮겨 놨어요. 요번엔 반드시 그놈을 잡으실 거예요. 행운을 빌어요!', `FemaleText_loc4`='我们把备用的攻城器械都抬上来啦，这次你一定能把那家伙打倒。祝你好运！', `FemaleText_loc5`='我們已經提升了備用載具的效能，希望你們這次能擊敗那個東西。祝好運!', `FemaleText_loc7`='Ya hemos llevado los vehículos de reemplazo, así que ahora podéis derrotar a esa cosa. ¡Buena suerte!' WHERE `ID`=34190;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 작살 내 버리세요!', `MaleText_loc4`='把它撕成碎片吧！', `MaleText_loc5`='把它拆成碎片!', `MaleText_loc7`='¡Hazlo pedazos!', `FemaleText_loc1`='아주 작살 내 버리세요!', `FemaleText_loc4`='把它撕成碎片吧！', `FemaleText_loc5`='把它拆成碎片!', `FemaleText_loc7`='¡Hazlo pedazos!' WHERE `ID`=34191;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번 설교 시간에 참석해 주신 모든 분들께 감사드립니다. 이렇게 친근한 얼굴들을 많이 뵙게 되다니 경이롭군요!', `MaleText_loc4`='感谢大家参加此次布道会。看到这么多熟悉的面孔真是令人欣慰！', `MaleText_loc5`='感謝你們來參加這場佈道。能看見這麼多熟悉的面孔真是太好了!', `MaleText_loc7`='Gracias por asistir a este sermón. ¡Es maravilloso ver tantas caras familiares!', `FemaleText_loc1`='이번 설교 시간에 참석해 주신 모든 분들께 감사드립니다. 이렇게 친근한 얼굴들을 많이 뵙게 되다니 경이롭군요!', `FemaleText_loc4`='感谢大家参加此次布道会。看到这么多熟悉的面孔真是令人欣慰！', `FemaleText_loc5`='感謝你們來參加這場佈道。能看見這麼多熟悉的面孔真是太好了!', `FemaleText_loc7`='Gracias por asistir a este sermón. ¡Es maravilloso ver tantas caras familiares!' WHERE `ID`=34192;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘은 빛의 세 가지 덕목에 대해서 이야기해 보겠습니다.', `MaleText_loc4`='今天，我要谈谈圣光的三大美德。', `MaleText_loc5`='今天我想來談聖光的三項美德。', `MaleText_loc7`='Hoy me gustaría hablar de tres virtudes de la luz.', `FemaleText_loc1`='오늘은 빛의 세 가지 덕목에 대해서 이야기해 보겠습니다.', `FemaleText_loc4`='今天，我要谈谈圣光的三大美德。', `FemaleText_loc5`='今天我想來談聖光的三項美德。', `FemaleText_loc7`='Hoy me gustaría hablar de tres virtudes de la luz.' WHERE `ID`=34193;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 모두에게 어둡고 힘든 시기가 아닐 수 없습니다. 스컬지 군대는 남쪽에 모여들었고, 전장에서는 동료가 쓰러져 잠시 후에는 우리 적의 편이 되어 몸을 일으키고 있습니다.', `MaleText_loc4`='对我们来说，这是一个黑暗而艰苦的时代。天灾军团盘踞在南方。那些在战场上牺牲的勇士们，转瞬间就沦为了敌人的爪牙。', `MaleText_loc5`='對我們所有人來說這有過黑暗而艱困的時候。天譴軍團的大軍在南方集結。同袍在戰場上倒下，再站起來的時候卻開始替我們的敵人作戰。', `MaleText_loc7`='Estos son tiempos difíciles y oscuros para todos nosotros. El ejército de la Plaga se reúne en el sur. Los compañeros caen en el campo de batalla y se alzan momentos después para servir a nuestro enemigo.', `FemaleText_loc1`='우리 모두에게 어둡고 힘든 시기가 아닐 수 없습니다. 스컬지 군대는 남쪽에 모여들었고, 전장에서는 동료가 쓰러져 잠시 후에는 우리 적의 편이 되어 몸을 일으키고 있습니다.', `FemaleText_loc4`='对我们来说，这是一个黑暗而艰苦的时代。天灾军团盘踞在南方。那些在战场上牺牲的勇士们，转瞬间就沦为了敌人的爪牙。', `FemaleText_loc5`='對我們所有人來說這有過黑暗而艱困的時候。天譴軍團的大軍在南方集結。同袍在戰場上倒下，再站起來的時候卻開始替我們的敵人作戰。', `FemaleText_loc7`='Estos son tiempos difíciles y oscuros para todos nosotros. El ejército de la Plaga se reúne en el sur. Los compañeros caen en el campo de batalla y se alzan momentos después para servir a nuestro enemigo.' WHERE `ID`=34194;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='키니라, 보고할 게 뭔가?', `MaleText_loc4`='柯尼拉，你能告诉我些什么？', `MaleText_loc5`='你可以告訴我什麼，奇妮菈?', `MaleText_loc7`='¿Qué puedes contarme, Keynira?' WHERE `ID`=34195;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여러분 중 많은 분이 믿음의 배신을 경험해 보셨을 겁니다.', `MaleText_loc4`='你们中的大多数都体会过被背叛的苦楚。', `MaleText_loc5`='許多人都經歷這樣的信賴受到背叛。', `MaleText_loc7`='Muchos de ustedes han sufrido una traición a su confianza.', `FemaleText_loc1`='여러분 중 많은 분이 믿음의 배신을 경험해 보셨을 겁니다.', `FemaleText_loc4`='你们中的大多数都体会过被背叛的苦楚。', `FemaleText_loc5`='許多人都經歷這樣的信賴受到背叛。', `FemaleText_loc7`='Muchos de ustedes han sufrido una traición a su confianza.' WHERE `ID`=34196;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 우리 모두가 그래야 하듯이 여러분도 견뎌야 합니다. 이런 어두운 시절에는 누구도 끈기의 미덕을 모르지 않습니다. 절망과 증오와 마주 대하여 우리는 믿음과 싸워나가자는 투지를 신실함으로 계속 이어가야 합니다.', `MaleText_loc4`='但是你们坚持了下来，我们也必须这样做。在这个时代，人们不应该对坚韧这一美德感到陌生。面对绝望与仇恨，我们仍然要坚守自己的信仰并继续战斗。', `MaleText_loc5`='但你們堅持不懈，我們所有人都是。在這段日子中，沒有人對堅毅這項美德感到陌生。在面對絕望和仇恨，我們依舊真誠地擁抱我們的信仰，並且為它而戰。', `MaleText_loc7`='Aun así, perseveras, como debemos hacer todos. Hoy día nadie es ajeno a la virtud de la tenacidad. Frente al odio y a la desesperación, seguimos siendo fieles a nuestras creencias y seguimos peleando.', `FemaleText_loc1`='하지만 우리 모두가 그래야 하듯이 여러분도 견뎌야 합니다. 이런 어두운 시절에는 누구도 끈기의 미덕을 모르지 않습니다. 절망과 증오와 마주 대하여 우리는 믿음과 싸워나가자는 투지를 신실함으로 계속 이어가야 합니다.', `FemaleText_loc4`='但是你们坚持了下来，我们也必须这样做。在这个时代，人们不应该对坚韧这一美德感到陌生。面对绝望与仇恨，我们仍然要坚守自己的信仰并继续战斗。', `FemaleText_loc5`='但你們堅持不懈，我們所有人都是。在這段日子中，沒有人對堅毅這項美德感到陌生。在面對絕望和仇恨，我們依舊真誠地擁抱我們的信仰，並且為它而戰。', `FemaleText_loc7`='Aun así, perseveras, como debemos hacer todos. Hoy día nadie es ajeno a la virtud de la tenacidad. Frente al odio y a la desesperación, seguimos siendo fieles a nuestras creencias y seguimos peleando.' WHERE `ID`=34197;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한동안은 괜찮겠군. 알살락스의 탑은 어떻던가?', `MaleText_loc4`='暂时这样就可以了。那座塔呢？奥萨拉克斯怎么样了？', `MaleText_loc5`='這樣暫時就可以了。你說那個塔?奧薩拉克斯怎麼啦?', `MaleText_loc7`='Eso servirá de momento. ¿Y la torre? ¿Qué pasa con Althalaxx?' WHERE `ID`=34198;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여러분의 끈기에 대해서는 의심할 여지가 없습니다. 하지만 고려할 다른 미덕들이 있답니다.', `MaleText_loc4`='毫无疑问，你们拥有坚韧的意志……但是我们也不能忽略其它的美德。', `MaleText_loc5`='你們的堅毅無庸置疑...但還有其他美德值得考量。', `MaleText_loc7`='Nadie puede poner en duda su tenacidad... Pero hay otras virtudes que considerar.', `FemaleText_loc1`='여러분의 끈기에 대해서는 의심할 여지가 없습니다. 하지만 고려할 다른 미덕들이 있답니다.', `FemaleText_loc4`='毫无疑问，你们拥有坚韧的意志……但是我们也不能忽略其它的美德。', `FemaleText_loc5`='你們的堅毅無庸置疑...但還有其他美德值得考量。', `FemaleText_loc7`='Nadie puede poner en duda su tenacidad... Pero hay otras virtudes que considerar.' WHERE `ID`=34199;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛의 길을 함께 걷는 우리가 배우는 첫 번째 미덕은 존중입니다.', `MaleText_loc4`='尊重，是所有踏上圣光之路的人们应该首先学习的美德。', `MaleText_loc5`='尊重，是我們教給那些加入聖光之道者的第一課。', `MaleText_loc7`='El respeto es la primera virtud que se enseña a aquellos que toman el camino de la Luz.', `FemaleText_loc1`='빛의 길을 함께 걷는 우리가 배우는 첫 번째 미덕은 존중입니다.', `FemaleText_loc4`='尊重，是所有踏上圣光之路的人们应该首先学习的美德。', `FemaleText_loc5`='尊重，是我們教給那些加入聖光之道者的第一課。', `FemaleText_loc7`='El respeto es la primera virtud que se enseña a aquellos que toman el camino de la Luz.' WHERE `ID`=34200;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 복도 너머에 여러분이 적이라 부를 만한 자들을 주시하세요. 여러분을 갈라놓은 증오심에도 여러분의 적에 대해 존중할 본질이 있답니다. 그들의 용맹함은 인정받아야 하니까요.', `MaleText_loc4`='走廊对面，就是那些被你们视为敌人的家伙。尽管仇恨让彼此疏远，但是他们依然拥有值得你们尊重的品德。他们的勇气就值得钦佩。', `MaleText_loc5`='放眼望去，看看你們的敵人。儘管你對它們懷有諸多仇恨，但你的敵人依舊有著許多值得尊敬的特質。它們的無所畏懼應該要被認清。', `MaleText_loc7`='Observa en el otro lado de las gradas a aquellos a los que llamarías enemigos. A pesar del odio que os separa, hay cualidades que respetar en tu oponente. Debiera reconocerse su valía.', `FemaleText_loc1`='저 복도 너머에 여러분이 적이라 부를 만한 자들을 주시하세요. 여러분을 갈라놓은 증오심에도 여러분의 적에 대해 존중할 본질이 있답니다. 그들의 용맹함은 인정받아야 하니까요.', `FemaleText_loc4`='走廊对面，就是那些被你们视为敌人的家伙。尽管仇恨让彼此疏远，但是他们依然拥有值得你们尊重的品德。他们的勇气就值得钦佩。', `FemaleText_loc5`='放眼望去，看看你們的敵人。儘管你對它們懷有諸多仇恨，但你的敵人依舊有著許多值得尊敬的特質。它們的無所畏懼應該要被認清。', `FemaleText_loc7`='Observa en el otro lado de las gradas a aquellos a los que llamarías enemigos. A pesar del odio que os separa, hay cualidades que respetar en tu oponente. Debiera reconocerse su valía.' WHERE `ID`=34201;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기에 모인 우리는 모두 명예로운 전투의 개념을 가지고 있습니다. 명예로움을 담고 처신하며 자신이 대우받고자 하는 것처럼 자신의 적을 대우하는 일은 존중을 나타내는 길입니다.', `MaleText_loc4`='在场诸位都懂得荣誉之战的概念吧。对战时光明磊落是谓尊重，公平地对待敌人是谓尊重。', `MaleText_loc5`='所有我們在此集會的人都有著光榮戰鬥的觀念。依榮譽行事，你希望怎樣被對待，就怎樣對待你的敵手，這就是尊重。', `MaleText_loc7`='Todos los aquí reunidos apreciamos el combate honorable. Comportarse con honor y tratar a tu oponente como quisieras que te trataran es una muestra de respeto.', `FemaleText_loc1`='여기에 모인 우리는 모두 명예로운 전투의 개념을 가지고 있습니다. 명예로움을 담고 처신하며 자신이 대우받고자 하는 것처럼 자신의 적을 대우하는 일은 존중을 나타내는 길입니다.', `FemaleText_loc4`='在场诸位都懂得荣誉之战的概念吧。对战时光明磊落是谓尊重，公平地对待敌人是谓尊重。', `FemaleText_loc5`='所有我們在此集會的人都有著光榮戰鬥的觀念。依榮譽行事，你希望怎樣被對待，就怎樣對待你的敵手，這就是尊重。', `FemaleText_loc7`='Todos los aquí reunidos apreciamos el combate honorable. Comportarse con honor y tratar a tu oponente como quisieras que te trataran es una muestra de respeto.' WHERE `ID`=34202;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전장에서 맞닥뜨린 적이 형제거나 불구대천의 원수이든 아니든 존중하십시오. 자신이 진정으로 믿는 바가 무엇이든 간에, 이러한 존중은 서로 통하는 바가 있는 법입니다.', `MaleText_loc4`='在战场上，无论你的对手是兄弟还是宿敌，都要予以同样的尊重。即便你们的信仰不同，这种尊重依然能在你们之间建立某种联系……', `MaleText_loc5`='尊敬你在戰場上的敵手，不管他是你的兄弟或是你的死敵。不管你的信仰到底是什麼，這樣的尊重表現了一種連結...', `MaleText_loc7`='Respeta a tu enemigo en la liza, ya sea tu hermano o tu peor enemigo. No importa en qué se fundamenten tus creencias, este respeto es reconocer una conexión...', `FemaleText_loc1`='전장에서 맞닥뜨린 적이 형제거나 불구대천의 원수이든 아니든 존중하십시오. 자신이 진정으로 믿는 바가 무엇이든 간에, 이러한 존중은 서로 통하는 바가 있는 법입니다.', `FemaleText_loc4`='在战场上，无论你的对手是兄弟还是宿敌，都要予以同样的尊重。即便你们的信仰不同，这种尊重依然能在你们之间建立某种联系……', `FemaleText_loc5`='尊敬你在戰場上的敵手，不管他是你的兄弟或是你的死敵。不管你的信仰到底是什麼，這樣的尊重表現了一種連結...', `FemaleText_loc7`='Respeta a tu enemigo en la liza, ya sea tu hermano o tu peor enemigo. No importa en qué se fundamenten tus creencias, este respeto es reconocer una conexión...' WHERE `ID`=34203;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알아내 온 게 그게 다 인가? 난 병력, 장소, 의도를 알고 싶네. 우린 맹인이나 다름없을 정도로 정보가 부족해. 정찰 장소로 돌아가게!', `MaleText_loc4`='这就是你为我找到的？我要的是数量、地点还有目的——我们现在简直是两眼一抹黑。赶快去完成任务！', `MaleText_loc5`='你要跟我說的就這些?我要數字、地點和目的。我們現在身處於黑暗中，快給我回到戰場上!', `MaleText_loc7`='¿Eso es todo lo que tienes para mí? Quiero números, ubicaciones, intenciones... Esto no nos sirve para nada. ¡Vuelve al campo!' WHERE `ID`=34204;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 이러한 상호 존중의 마음가짐으로 서로 통하다 보면 성스러운 빛에 더 가까워질 겁니다.', `MaleText_loc4`='……而认可这种联系，你们就会更接近圣光。', `MaleText_loc5`='...在這種連結的認知中，你將更靠近聖光。', `MaleText_loc7`='...y al reconocer estas conexiones, te acercas a la Luz.', `FemaleText_loc1`='... 이러한 상호 존중의 마음가짐으로 서로 통하다 보면 성스러운 빛에 더 가까워질 겁니다.', `FemaleText_loc4`='……而认可这种联系，你们就会更接近圣光。', `FemaleText_loc5`='...在這種連結的認知中，你將更靠近聖光。', `FemaleText_loc7`='...y al reconocer estas conexiones, te acercas a la Luz.' WHERE `ID`=34205;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛의 길을 걷는 데 있어서 한 발짝 더 나아간 과정이 동정심입니다.', `MaleText_loc4`='要在圣光之路上更进一步，我们还必须学会同情。', `MaleText_loc5`='而更靠近聖光之道的下一步是:同情心。', `MaleText_loc7`='Hay un paso más en el camino hacia la Luz: la compasión.', `FemaleText_loc1`='빛의 길을 걷는 데 있어서 한 발짝 더 나아간 과정이 동정심입니다.', `FemaleText_loc4`='要在圣光之路上更进一步，我们还必须学会同情。', `FemaleText_loc5`='而更靠近聖光之道的下一步是:同情心。', `FemaleText_loc7`='Hay un paso más en el camino hacia la Luz: la compasión.' WHERE `ID`=34206;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘날에는 경쟁자들이 가득합니다. 여러분이 돌아서는 곳이라면 어디에서나 다툼을 보기 쉽습니다.', `MaleText_loc4`='我们置身于竞争与对抗的年代。无论你们走到哪里，都能看见分歧与争执。', `MaleText_loc5`='在這個時代中充滿了爭鬥。你可以輕易地看出敵我之間的不同。', `MaleText_loc7`='Hoy día abundan las rivalidades. Es fácil ver las diferencias allí donde mires.', `FemaleText_loc1`='오늘날에는 경쟁자들이 가득합니다. 여러분이 돌아서는 곳이라면 어디에서나 다툼을 보기 쉽습니다.', `FemaleText_loc4`='我们置身于竞争与对抗的年代。无论你们走到哪里，都能看见分歧与争执。', `FemaleText_loc5`='在這個時代中充滿了爭鬥。你可以輕易地看出敵我之間的不同。', `FemaleText_loc7`='Hoy día abundan las rivalidades. Es fácil ver las diferencias allí donde mires.' WHERE `ID`=34207;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 도전은 겉모습을 넘어서 우리의 유사성을 이해하는 것입니다. 이러한 이해를 통하여, 우리는 다른 이들이 겪은 상실에 대하여 동정심을 느낄 수가 있답니다.', `MaleText_loc4`='如何看透本质并寻求共同点，是我们面临的挑战。唯有理解，才能让你们对他人所遭受的痛楚产生同情……', `MaleText_loc5`='困難在於如何超脫表面的觀感，並進而瞭解我們的雷同之處。透過這樣的瞭解，你可以同情理解那些痛失所愛的人...', `MaleText_loc7`='El reto consiste en ver más allá de las apariencias y comprender nuestras similitudes. Gracias a esta comprensión puedes sentir compasión por las pérdidas que han sufrido los demás...', `FemaleText_loc1`='우리의 도전은 겉모습을 넘어서 우리의 유사성을 이해하는 것입니다. 이러한 이해를 통하여, 우리는 다른 이들이 겪은 상실에 대하여 동정심을 느낄 수가 있답니다.', `FemaleText_loc4`='如何看透本质并寻求共同点，是我们面临的挑战。唯有理解，才能让你们对他人所遭受的痛楚产生同情……', `FemaleText_loc5`='困難在於如何超脫表面的觀感，並進而瞭解我們的雷同之處。透過這樣的瞭解，你可以同情理解那些痛失所愛的人...', `FemaleText_loc7`='El reto consiste en ver más allá de las apariencias y comprender nuestras similitudes. Gracias a esta comprensión puedes sentir compasión por las pérdidas que han sufrido los demás...' WHERE `ID`=34208;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='설령 희생자가 자신과 다른 깃발을 지녔다고 하더라도 말이지요.', `MaleText_loc4`='……即使是对那些身处不同阵营的牺牲者。', `MaleText_loc5`='...不管他們是否背著不同的旌旗。', `MaleText_loc7`='...incluso si la víctima lleva otro estandarte.', `FemaleText_loc1`='설령 희생자가 자신과 다른 깃발을 지녔다고 하더라도 말이지요.', `FemaleText_loc4`='……即使是对那些身处不同阵营的牺牲者。', `FemaleText_loc5`='...不管他們是否背著不同的旌旗。', `FemaleText_loc7`='...incluso si la víctima lleva otro estandarte.' WHERE `ID`=34209;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적과 동맹을 막론하고 동정심을 이해하고 지각함으로써 여러분은 세상과의 소통을 다시 확인하는 겁니다.', `MaleText_loc4`='一旦感受并理解这种对敌对友一视同仁的同情，你们就重申了自己与世界的联系。', `MaleText_loc5`='透過感受與理解，對你的敵人與盟友同樣抱持著同情心，你會再次感覺到你與這個世界的連結。', `MaleText_loc7`='Al sentir y comprender por igual la compasión por un aliado y por un enemigo, reafirmas tu conexión con el mundo.', `FemaleText_loc1`='적과 동맹을 막론하고 동정심을 이해하고 지각함으로써 여러분은 세상과의 소통을 다시 확인하는 겁니다.', `FemaleText_loc4`='一旦感受并理解这种对敌对友一视同仁的同情，你们就重申了自己与世界的联系。', `FemaleText_loc5`='透過感受與理解，對你的敵人與盟友同樣抱持著同情心，你會再次感覺到你與這個世界的連結。', `FemaleText_loc7`='Al sentir y comprender por igual la compasión por un aliado y por un enemigo, reafirmas tu conexión con el mundo.' WHERE `ID`=34210;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이러한 교의대로 행동하는 일은 이 세상을 우리 모두가 감사할 수 있는 곳으로 만드는 데 도움을 줍니다. 명예와 정의의 세상을 말이죠.', `MaleText_loc4`='只要我们奉行这些原则与美德，这个世界就会变成彼此向往的美好世界。荣耀而正义的世界。', `MaleText_loc5`='依著這些原則，這些美德行事，能讓這個世界變成一個我們全都心懷感激的美好地方。一個充滿榮譽和公義的世界。', `MaleText_loc7`='Actuar según estos principios, estas virtudes, contribuye a hacer del mundo un lugar que todos podemos querer. Un mundo de honor y justicia.', `FemaleText_loc1`='이러한 교의대로 행동하는 일은 이 세상을 우리 모두가 감사할 수 있는 곳으로 만드는 데 도움을 줍니다. 명예와 정의의 세상을 말이죠.', `FemaleText_loc4`='只要我们奉行这些原则与美德，这个世界就会变成彼此向往的美好世界。荣耀而正义的世界。', `FemaleText_loc5`='依著這些原則，這些美德行事，能讓這個世界變成一個我們全都心懷感激的美好地方。一個充滿榮譽和公義的世界。', `FemaleText_loc7`='Actuar según estos principios, estas virtudes, contribuye a hacer del mundo un lugar que todos podemos querer. Un mundo de honor y justicia.' WHERE `ID`=34211;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 말씀드린 내용을 생각해 보세요, 형제들이여. 우리 모두를 둘러싼 어둠 속에서 여느 때보다 성스러운 빛이 더 간절하답니다.', `MaleText_loc4`='好好想想我的话吧，朋友们。黑暗笼罩着我们，人们更加需要圣光的指引。', `MaleText_loc5`='思考一下我今日所言，朋友。在黑暗包圍我們之時，我們更需要聖光的引領。', `MaleText_loc7`='Pensad en mis palabras, amigos. En la oscuridad que nos rodea a todos, necesitamos la Luz más que nunca.', `FemaleText_loc1`='제가 말씀드린 내용을 생각해 보세요, 형제들이여. 우리 모두를 둘러싼 어둠 속에서 여느 때보다 성스러운 빛이 더 간절하답니다.', `FemaleText_loc4`='好好想想我的话吧，朋友们。黑暗笼罩着我们，人们更加需要圣光的指引。', `FemaleText_loc5`='思考一下我今日所言，朋友。在黑暗包圍我們之時，我們更需要聖光的引領。', `FemaleText_loc7`='Pensad en mis palabras, amigos. En la oscuridad que nos rodea a todos, necesitamos la Luz más que nunca.' WHERE `ID`=34212;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='투석기들은 쓸 수 없는 상태였습니다. 일부를 태웠고 나머지는 묶어놨습니다.', `FemaleText_loc4`='那些投石车仍然无法使用。我已经烧毁了几辆投石车，并破坏了其余的。', `FemaleText_loc5`='投石車仍舊無法使用。我把其他的燒了和困住了。', `FemaleText_loc7`='Las catapultas siguen inhabilitadas. He quemado varias y he colocado trampas en las demás.' WHERE `ID`=34213;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자... 잘 모르겠습니다. 폐허에 움직임이 있긴 했습니다.', `FemaleText_loc4`='我……我不知道。在那片废墟里有不寻常的动静。', `FemaleText_loc5`='我...我不知道。廢墟那好像有什麼動靜。', `FemaleText_loc7`='N-no sé, hay movimiento en las ruinas.' WHERE `ID`=34214;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='쉿... 정찰 장소로 나갔을 때 제 위치를 드러내지 말아 주십시오. 마서스 님께서는 여기서 무슨 일이 벌어지는지 알고자 하시니까요.', `FemaleText_loc4`='嘘……我在战场上的时候请不要暴露我的位置。马萨斯需要知道这里发生了什么。', `FemaleText_loc5`='噓～～拜託不要曝露我在這的位置。瑪薩絲需要瞭解在這的情況。', `FemaleText_loc7`='Shhh. No descubras mi posición cuando estoy en el campo. Mathas debe saber lo que está pasando aquí.' WHERE `ID`=34215;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저와 얘기를 나누고 싶으신 분은 고해실 칸막이 뒤에서 절 만나실 수 있을 겁니다. 의심, 걱정이나 불확실한 점이라면 무엇이든지 제가 기쁜 마음으로 덜어 드리겠습니다.', `MaleText_loc4`='如果有谁想找我谈谈，我就在忏悔室的屏风后面等着你们。我很乐意为大家排解疑问、忧虑和彷徨。', `MaleText_loc5`='如果有任何人想跟我談談，我就在告解幕的後面。任何的疑惑、擔憂，任何的遲疑。我都很樂意聆聽，給你勸慰。', `MaleText_loc7`='Estaré en el confesionario si alguien desea hablar conmigo. Estaré encantado de aliviar cualquier duda, cualquier preocupación, cualquier incertidumbre.', `FemaleText_loc1`='저와 얘기를 나누고 싶으신 분은 고해실 칸막이 뒤에서 절 만나실 수 있을 겁니다. 의심, 걱정이나 불확실한 점이라면 무엇이든지 제가 기쁜 마음으로 덜어 드리겠습니다.', `FemaleText_loc4`='如果有谁想找我谈谈，我就在忏悔室的屏风后面等着你们。我很乐意为大家排解疑问、忧虑和彷徨。', `FemaleText_loc5`='如果有任何人想跟我談談，我就在告解幕的後面。任何的疑惑、擔憂，任何的遲疑。我都很樂意聆聽，給你勸慰。', `FemaleText_loc7`='Estaré en el confesionario si alguien desea hablar conmigo. Estaré encantada de aliviar cualquier duda, cualquier preocupación, cualquier incertidumbre.' WHERE `ID`=34216;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 플라스마 폭발을 시전합니다!', `MaleText_loc4`='%s开始施放等离子冲击！', `MaleText_loc5`='%s開始施展電漿衝擊!', `MaleText_loc7`='¡%s comienza a lanzar Explosión de Plasma!' WHERE `ID`=34217;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저희가 뾰족창 부족의 위험을 완전히 끝내겠습니다. 파수대, 공격하라!', `FemaleText_loc4`='让我们结束碎矛的威胁吧。哨兵，发动攻击！', `FemaleText_loc5`='讓我們跟碎矛做個了斷。哨兵，攻擊!', `FemaleText_loc7`='Pongamos fin a la amenaza Rompelanzas para siempre. ¡Centinelas, ataquen!' WHERE `ID`=34218;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저들의 우두머리를 감싼 보호막을 무너뜨렸습니다! 어서 저자를 처치하세요!', `FemaleText_loc4`='我已经粉碎了保护他们首领的护盾。赶快消灭他！', `FemaleText_loc5`='我已經打碎了保護他們首領的護盾了!快，殺了他!', `FemaleText_loc7`='¡He destruido el escudo que protege a su líder! ¡Rápido, mátalo!' WHERE `ID`=34219;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번엔 우리만 움직이는 게 아니다. 오늘 우리에게 무슨 일이 생기든, 나이트 엘프 녀석들은 무너질 것이다!', `MaleText_loc4`='我们并非孤军作战。无论今天我们有怎样的下场，暗夜精灵仍然难逃灭亡！', `MaleText_loc5`='我們並不是孤獨的。不管我們今天結果如何，夜精靈都將被消滅!', `MaleText_loc7`='No actuamos solos. Nos pase lo que nos pase hoy, los elfos de la noche caerán de todos modos.' WHERE `ID`=34220;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='최근 일어난 일들로 우리가 약하다고 생각하는 저들은 어리석었습니다. 저 트롤들에게 더는 희망이란 없습니다. 오늘 우린 끝을 볼 겁니다.', `FemaleText_loc4`='他们这群蠢货，竟然以为我们是软弱可欺的。这些巨魔已经没有希望了——今天将在我们手中结束。', `FemaleText_loc5`='因為最近的事件，他們愚蠢地認為我們是脆弱的。這些食人妖沒有任何希望了，今天將為他們劃上一個句號。', `FemaleText_loc7`='Han cometido un error al pensar que los acontecimientos recientes nos han debilitado. Ya no queda esperanza para estos trols. Esto acaba hoy.' WHERE `ID`=34221;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비됐습니다. 공격을 시작하시지요.', `MaleText_loc4`='我准备好了，开始进攻。', `MaleText_loc5`='我準備好了。開始攻擊。', `MaleText_loc7`='Estoy preparado. Que comience el ataque.', `FemaleText_loc1`='준비됐습니다. 공격을 시작하시지요.', `FemaleText_loc4`='我准备好了，开始进攻。', `FemaleText_loc5`='我準備好了。開始攻擊。', `FemaleText_loc7`='Estoy preparada. Que comience el ataque.' WHERE `ID`=34222;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='공격을 시작할 준비가 되면 제게 알려 주십시오.', `FemaleText_loc4`='准备好发动攻击之后就告诉我。', `FemaleText_loc5`='準備好進攻時便跟我說一聲。', `FemaleText_loc7`='Avísame cuando estés $glisto:lista; para comenzar el ataque.' WHERE `ID`=34223;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뾰족창 부족 우두머리가 곧 이곳에 나타날 겁니다. 공격에 가담하고 싶다면, 참고 기다리십시오.', `FemaleText_loc4`='碎矛的首领随时都有可能在这里出现。如果你想参与这次进攻，就耐心一些。', `FemaleText_loc5`='我們預估碎矛的首領隨時都會出現在這。如果你想參與攻擊就耐心的等等。', `FemaleText_loc7`='Esperamos que el líder de los Rompelanzas aparezca en cualquier momento. SI quieres unirte al ataque, ten paciencia.' WHERE `ID`=34224;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대단한 전투였죠! 보셨습니까, 리디안 님?!', `MaleText_loc4`='多么激烈的战斗啊！你瞧见了吗，琳蒂安？！', `MaleText_loc5`='真是一場大戰!你看見了嗎，萊迪安?!', `MaleText_loc7`='¡Qué batalla! ¡¿Viste eso, Rhydian?!' WHERE `ID`=34225;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럴지도 모르죠. 하지만 이제 울두아르 안에 밀고 들어가는 건 시간문제라고요. 안쪽으로 순간이동하는 방법은 찾으셨나요?', `MaleText_loc4`='或许吧，但是我们攻入奥杜尔是迟早的事。找到传送进去的办法了吗？', `MaleText_loc5`='或許吧，但早晚我們都會突圍進入奧杜亞。有找到任何傳送進去的通道嗎?', `MaleText_loc7`='Puede, pero es solo cuestión de tiempo que volvamos a irrumpir en Ulduar. ¿Ha habido suerte al buscar un teletransportador?' WHERE `ID`=34226;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 친구들이 참 잘해줬죠, 브란. 하지만 아직 끝나지 않았어요.', `FemaleText_loc4`='布莱恩，看来我们的朋友干得不错，但是事情还没有解决呢。', `FemaleText_loc5`='我們的朋友們打得很不錯，布萊恩，但我們這邊還沒完成。', `FemaleText_loc7`='Nuestros amigos lucharon bien, Brann, pero nosotros no hemos terminado todavía.' WHERE `ID`=34227;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아직요. 아무래도 그 문제는, 정찰병들이 문 바로 앞에서 발견한 거대한 기계랑 관련이 있는 것 같아요.', `FemaleText_loc4`='毫无头绪。侦察兵在奥杜尔的前厅发现了一个巨型机械构造体，我怀疑是这玩意儿在捣鬼。', `FemaleText_loc5`='完全沒有。我懷疑這可能跟斥候在大門前發現的那台巨大機械裝置有關。', `FemaleText_loc7`='En absoluto. Sospecho que tiene algo que ver con el gigantesco ensamblaje mecánico que nuestros exploradores divisaron frente a la puerta.' WHERE `ID`=34228;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇군요. 그럼 결국 그놈이랑 싸워야 하겠네요?', `MaleText_loc4`='噢。这么说，我们不得不跟那个大家伙打一架了？', `MaleText_loc5`='噢，所以我們還得對付那個東西?', `MaleText_loc7`='Bueno. Así que, al fin y al cabo, ¿tendremos que enfrentarnos a esa cosa?' WHERE `ID`=34229;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='키린 토는 그런 커다란 괴물들을 처리할 여유가 없답니다, 브란. 어쩌면 그럴 필요가 없을지도 모르고요.', `FemaleText_loc4`='肯瑞托不可能在这种大块头上浪费资源。或许我们也没有必要跟它正面冲突。', `FemaleText_loc5`='祈倫托不可能分出額外的資源來應付這種尺寸的東西。然而，我們可能不需要親自對付它。', `FemaleText_loc7`='Al Kirin Tor no le resulta posible dedicar ningún recurso adicional a enfrentarse a nada de semejante tamaño. Aunque puede que no sea necesario.' WHERE `ID`=34230;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='근처에서 발견한 무장 원시 비룡이랑 화염 거인은 어떤가요? 당신네 마법사들이 놈들을 처리해 주실 수 있나요?', `MaleText_loc4`='那附近的装甲始祖龙和火焰巨人怎么办？肯瑞托的法师们能对付得了吗？', `MaleText_loc5`='那附近偵察到的裝甲元龍跟火巨人呢?你覺得你的法師可以應付它們嗎?', `MaleText_loc7`='¿Qué pasa con ese protodraco blindado y con el gigante de fuego que avistamos cerca? ¿Crees que tus magos pueden encargarse de ellos?' WHERE `ID`=34231;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그냥 숨어들어 갈 수도 있을 것 같거든요. 문앞에 있는 저 기계만 처리하면 안쪽으로 들어가는 덴 문제없어요.', `FemaleText_loc4`='我们可以偷偷地溜过去吧。只要打倒前厅的机械构造体，就能进入奥杜尔了。', `FemaleText_loc5`='我們可以偷偷溜過去。只要我們能打倒大門前的那台裝置，我們應該就能進到裡面。', `FemaleText_loc7`='Podemos pasar de largo sin que nos vean. Mientras podamos abatir el ensamblaje frente a la puerta, debiéramos ser capaces de entrar.' WHERE `ID`=34232;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='숨어들어 가요?! 우리가 무슨 생쥡니까?', `MaleText_loc4`='溜过去？！你以为我们是什么，土拨鼠吗？', `MaleText_loc5`='偷偷溜過去?!你以為我們是啥，土撥鼠嗎?', `MaleText_loc7`='¿¡Escabullirnos!? ¿Qué crees que somos, marmotas?' WHERE `ID`=34233;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우린 고대 신을 잡으러 왔잖아요, 브란.', `FemaleText_loc4`='我们要对付的真正敌人是上古之神啊，布莱恩。', `FemaleText_loc5`='我們要是來獵殺古神，布萊恩。', `FemaleText_loc7`='Estamos dando caza a un dios antiguo, Brann.' WHERE `ID`=34234;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐, 그렇죠. 그럼 어차피 우리 동료들이 실제로 일을 처리할 테니, 진행 방식도 그들한테 맡기기로 해요.', `MaleText_loc4`='好吧。如果我们的盟友不嫌麻烦的话，就让他们来决定如何前进吧。', `MaleText_loc5`='好吧。如果我們的同伴打算要弄髒自己的手，我們只能讓他們決定要怎麼前進。', `MaleText_loc7`='Bien. Si nuestros aliados son los que van a ensuciarse las manos, dejaremos que sean ellos quienes decidan cómo proceder.' WHERE `ID`=34235;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 끔찍한 기계를 정말 잘 처리해 주셨습니다. 이제 우릴 방해하는 건 별로 없을 거예요.$B$B저쪽 끝에서 절거덕거리는 로봇만 처리하고 나면 우린 울두아르 안에 있을 겁니다.$B$B불을 뿜어대는 거대한 원시비룡과 용암거인도 발견하긴 했습니다만, 울두아르 안으로 가는 길에 있는 건 아니에요. 원한다면 놈들은 피하실 수 있습니다.', `MaleText_loc4`='你成功地击败了那只金属怪物。看来面前的障碍已经不多啦。$B$B一旦除掉前厅尽头的机器人，我们就能进入奥杜尔了。$B$B我们还发现了一头巨型喷火始祖龙和一个熔化的巨人。不过他们并没有挡住我们的去路，如果你想避开它们也没有问题。', `MaleText_loc5`='對付那個金屬巨人可真是幹得漂亮。看來我們路上剩下的阻礙沒剩幾個了。$B$B等你解決掉大廳底那個叮噹作響的機器人，我們就能進入奧杜亞了。$B$B我們還注意到有一隻龐大的噴火元龍和一隻熔火巨人。然而，他們並不會阻礙我們，如果想要你也可以避開他們。', `MaleText_loc7`='Un gran trabajo con esa monstruosidad de metal. Parece que solo quedan unos pocos obstáculos en nuestro camino.$b$bUna vez se hayan encargado de ese ruidoso robot al final de la sala estaremos dentro de Ulduar.$b$bTambién hemos detectado un enorme protodraco que escupe fuego y un gigante fundido. Aunque, si quieren sencillamente evitarlos, no están en nuestro camino.' WHERE `ID`=34236;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전장 내에 있어야 합니다.', `MaleText_loc4`='你必须待在赛场里。', `MaleText_loc5`='你必須待在戰鬥場地上。', `MaleText_loc7`='Debes permanecer en el campo de batalla.', `FemaleText_loc1`='전장 내에 있어야 합니다.', `FemaleText_loc4`='你必须待在赛场里。', `FemaleText_loc5`='你必須待在戰鬥場地上。', `FemaleText_loc7`='Debes permanecer en el campo de batalla.' WHERE `ID`=34237;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카드라크의 임무를 수행 중입니다. 어서 조람가르로 가야 합니다!', `MaleText_loc4`='我正在执行卡德拉克的任务。我必须立刻前往佐拉姆加！', `MaleText_loc5`='我正在執行卡德拉克給我的任務。我必須馬上趕到佐拉姆加!', `MaleText_loc7`='Tengo entre manos una tarea de Kadrak. ¡Tengo que llegar a Zoram''gar ahora mismo!', `FemaleText_loc1`='카드라크의 임무를 수행 중입니다. 어서 조람가르로 가야 합니다!', `FemaleText_loc4`='我正在执行卡德拉克的任务。我必须立刻前往佐拉姆加！', `FemaleText_loc5`='我正在執行卡德拉克給我的任務。我必須馬上趕到佐拉姆加!', `FemaleText_loc7`='Tengo entre manos una tarea de Kadrak. ¡Tengo que llegar a Zoram''gar ahora mismo!' WHERE `ID`=34238;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싸움을 할 줄은 아느냐?', `MaleText_loc4`='你能不能使出点真本事来？', `MaleText_loc5`='你就只有這點能耐嗎?', `MaleText_loc7`='¿Podrías al menos oponer resistencia?' WHERE `ID`=34239;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형편없군.', `MaleText_loc4`='可悲。', `MaleText_loc5`='真可悲。', `MaleText_loc7`='Patético.' WHERE `ID`=34240;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물러서지 마라! 놈들을 물리쳐라!', `MaleText_loc4`='不要退缩！干掉他们！', `MaleText_loc5`='不要退縮!消滅他們!', `MaleText_loc7`='¡No se contengan! ¡Destrúyanlos!' WHERE `ID`=34241;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마상시합에 오신 걸 환영합니다, $n.', `MaleText_loc4`='欢迎你参加锦标赛，$n。', `MaleText_loc5`='歡迎來到聯賽。$n。', `MaleText_loc7`='Bienvenid$go:a; al torneo, $n.' WHERE `ID`=34242;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이곳에서 뵙게 되니 반갑네요, $n.', `FemaleText_loc4`='很高兴能在这里见到你，$n。', `FemaleText_loc5`='真高興能在這兒見到你，$n。', `FemaleText_loc7`='Me alegro de verte, $n.' WHERE `ID`=34243;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니, 대체 왜 그런 짓을 한 게지? "누르지 마시오."라고 쓰인 경고 문구 못 봤나? 자폭 장치를 활성화해 놓으면, 도대체 어떻게 발명품을 시험하지?', `MaleText_loc4`='嘿，你们为什么要这么做啊？没看到上面写着“不要按这个按钮”吗？你们激活了自毁系统，还怎么完成测试呀？', `MaleText_loc5`='為什麼你要做出這種事?難道你沒看見標示上寫著「請勿觸碰這個按鈕!」嗎?現在自爆裝置已經啟動了，我們要怎麼完成測試呢?', `MaleText_loc7`='¿Por qué has hecho una cosa así? ¿Acaso no viste el letrero que decía "¡NO APRETAR ESTE BOTÓN!"? ¿Cómo terminaremos las pruebas con el mecanismo de autodestrucción activado?' WHERE `ID`=34244;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='낚시 훈련을 받고 싶습니다.', `MaleText_loc4`='我想接受钓鱼训练。', `MaleText_loc5`='我想要接受釣魚的訓練。', `MaleText_loc7`='Quiero instruirme en la pesca.', `FemaleText_loc1`='낚시 훈련을 받고 싶습니다.', `FemaleText_loc4`='我想接受钓鱼训练。', `FemaleText_loc5`='我想要接受釣魚的訓練。', `FemaleText_loc7`='Quiero instruirme en la pesca.' WHERE `ID`=34245;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 경쟁할 수 있을지 모르겠네요! 모두 다 너무나 크니 원!', `MaleText_loc4`='我都不知道自己有没有得打！他们的块头比我大多了！', `MaleText_loc5`='我不知道我到底能不能參賽!每個人都好大!', `MaleText_loc7`='¡No sé si puedo competir! ¡Todo el mundo es mucho más grande que yo!', `FemaleText_loc1`='내가 경쟁할 수 있을지 모르겠네요! 모두 다 너무나 크니 원!', `FemaleText_loc4`='我都不知道自己有没有得打！他们的块头比我大多了', `FemaleText_loc5`='我不知道我到底能不能參賽!每個人都好大!', `FemaleText_loc7`='¡No sé si puedo competir! ¡Todo el mundo es mucho más grande que yo!' WHERE `ID`=34246;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 성공할 가능성을 계산해 봤는데 애처로울 정도로 낮아요!', `MaleText_loc4`='我估算了一下胜出的概率，发现这种可能性低得要命！', `MaleText_loc5`='我計算我的獲勝機率，超低的!', `MaleText_loc7`='He calculado mis posibilidades de éxito, ¡y son preocupantemente bajas!', `FemaleText_loc1`='제가 성공할 가능성을 계산해 봤는데 애처로울 정도로 낮아요!', `FemaleText_loc4`='我估算了一下胜出的概率，发现这种可能性低得要命！', `FemaleText_loc5`='我計算我的獲勝機率，超低的!', `FemaleText_loc7`='He calculado mis posibilidades de éxito, ¡y son preocupantemente bajas!' WHERE `ID`=34247;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 터보타조가 돌진할 때 창을 정확한 각도로 들고, 주어진 시간 안에 방어를 최적화하기 위해 방패를 정확한 위치에 들고 있는 데 필요한 수학 공식을 정확하게 낼 수가 없어요!', `MaleText_loc4`='在让长枪保持最精确的角度并让盾牌处于任何时候都能提供最佳保护的位置的同时我还怎么算得清该为机械陆行鸟加载多大的电荷！', `MaleText_loc5`='我無法精準評估當渦輪陸行鳥在衝鋒時我的長槍應有的角度，也沒辦法同時把盾牌維持在絕佳的位置好提供最高的保護力，時間根本不夠用!', `MaleText_loc7`='¡No puedo estar evaluando adecuadamente cada segundo las matemáticas inherentes a la carga de mi turbozancudo mientras sostengo mi lanza en el ángulo preciso necesario y mantengo mi escudo en la localización exacta para maximizar la protección!', `FemaleText_loc1`='제 터보타조가 돌진할 때 창을 정확한 각도로 들고, 주어진 시간 안에 방어를 최적화하기 위해 방패를 정확한 위치에 들고 있는 데 필요한 수학 공식을 정확하게 낼 수가 없어요!', `FemaleText_loc4`='在让长枪保持最精确的角度并让盾牌处于任何时候都能提供最佳保护的位置的同时我还怎么算得清该为机械陆行鸟加载多大的电荷！', `FemaleText_loc5`='我無法精準評估當渦輪陸行鳥在衝鋒時我的長槍應有的角度，也沒辦法同時把盾牌維持在絕佳的位置好提供最高的保護力，時間根本不夠用!', `FemaleText_loc7`='¡No puedo estar evaluando adecuadamente cada segundo las matemáticas inherentes a la carga de mi turbozancudo mientras sostengo mi lanza en el ángulo preciso necesario y mantengo mi escudo en la localización exacta para maximizar la protección!' WHERE `ID`=34248;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 게다가 그런 탈것 중 일부는 절 밟아 뭉갤 수 있다고요!', `MaleText_loc4`='……而且有些坐骑可以把我踩扁！', `MaleText_loc5`='...有些坐騎可能會踩扁我!', `MaleText_loc7`='¡...y algunas de estas monturas pueden pisotearme!', `FemaleText_loc1`='... 게다가 그런 탈것 중 일부는 절 밟아 뭉갤 수 있다고요!', `FemaleText_loc4`='……而且有些坐骑可以把我踩扁！', `FemaleText_loc5`='...有些坐騎可能會踩扁我!', `FemaleText_loc7`='¡...y algunas de estas monturas pueden pisotearme!' WHERE `ID`=34249;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용기를 내십시오. 신체 조건은 중요치 않습니다만 당신이 가진 기술을 어떻게 사용하느냐가 중요하답니다.', `MaleText_loc4`='振作点。体型不是问题，关键在于你的作战技巧。', `MaleText_loc5`='要牢記在心。體型不是重點，重要的是你如何運用自己的技巧。', `MaleText_loc7`='Anímate. El tamaño no importa, sino cómo empleas las habilidades que tienes.', `FemaleText_loc1`='용기를 내십시오. 크기는 중요치 않습니다만 당신이 가진 기술을 어떻게 사용하느냐가 중요하답니다.', `FemaleText_loc4`='振作点。体型不是问题，关键在于你的作战技巧。', `FemaleText_loc5`='要牢記在心。體型不是重點，重要的是你如何運用自己的技巧。', `FemaleText_loc7`='Anímate. El tamaño no importa, sino cómo empleas las habilidades que tienes.' WHERE `ID`=34250;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 신체 조건에 부족한 점은 당신의 패기와 헌신으로 만회할 수 있답니다, 작은 친구여. 성스러운 빛이 함께하시길...', `MaleText_loc4`='体型上的劣势可以用信心和专注来弥补，小家伙。圣光与你同在。', `MaleText_loc5`='儘管在體型上輸人一截，但你可以在你的雄心壯志與專注上彌補，小傢伙。願聖光與你同行。', `MaleText_loc7`='Lo que te falta de fuerza lo tienes de ambición y dedicación, pequeñ$go:a;. Ve con la Luz.', `FemaleText_loc1`='당신의 신체 조건에 부족한 점은 당신의 패기와 헌신으로 만회할 수 있답니다, 작은 친구여. 성스러운 빛이 함께하시길...', `FemaleText_loc4`='体型上的劣势可以用信心和专注来弥补，小家伙。圣光与你同在。', `FemaleText_loc5`='儘管在體型上輸人一截，但你可以在你的雄心壯志與專注上彌補，小傢伙。願聖光與你同行。', `FemaleText_loc7`='Lo que te falta de fuerza lo tienes de ambición y dedicación, pequeñ$go:a;. Ve con la Luz.' WHERE `ID`=34251;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기로 오는 길에 펭귄 한 마리를 쥐어박았습니다.', `MaleText_loc4`='我在来这里的路上殴打了一只企鹅。', `MaleText_loc5`='我在來的路上揍了一隻企鵝。', `MaleText_loc7`='Le puse a uno un ojo morado de camino a aquí.', `FemaleText_loc1`='여기로 오는 길에 펭귄 한 마리를 쥐어박았습니다.', `FemaleText_loc4`='我在来这里的路上殴打了一只企鹅。', `FemaleText_loc5`='我在來的路上揍了一隻企鵝。', `FemaleText_loc7`='Le puse a uno un ojo morado de camino a aquí.' WHERE `ID`=34252;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아닙니다, 그런 건 아닙니다. 그저 당신 표정을 보고 싶었을 뿐입니다.', `MaleText_loc4`='哈哈，骗你的。我只是想看看你脸上的表情。', `MaleText_loc5`='喔，不是真的啦。我只是想看看你聽到的表情。', `MaleText_loc7`='No, en realidad no. Solo quería ver qué cara ponías.', `FemaleText_loc1`='아닙니다, 그렇진 않습니다. 그저 당신 표정을 보고 싶었을 뿐입니다.', `FemaleText_loc4`='哈哈，骗你的。我只是想看看你脸上的表情。', `FemaleText_loc5`='喔，不是真的啦。我只是想看看你聽到的表情。', `FemaleText_loc7`='No, en realidad no. Solo quería ver qué cara ponías.' WHERE `ID`=34253;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 이런... 적어도 양심의 가책은 느끼시지요?', `MaleText_loc4`='天哪。你连一点怜悯之心都没有吗？', `MaleText_loc5`='喔，我的天。那你最後趕到後悔了嗎?', `MaleText_loc7`='Oh, vaya. ¿No sientes remordimientos al menos?', `FemaleText_loc1`='오, 이런... 적어도 양심의 가책은 느끼시지요?', `FemaleText_loc4`='天哪。你连一点怜悯之心都没有吗？', `FemaleText_loc5`='喔，我的天。那你最後趕到後悔了嗎?', `FemaleText_loc7`='Oh, vaya. ¿No sientes remordimientos al menos?' WHERE `ID`=34254;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고해사제님, 당신에게 할 고백이 있습니다.', `MaleText_loc4`='姑娘，我要向你坦白一件事。', `MaleText_loc5`='小姑娘，我要向你告解。', `MaleText_loc7`='Colega, tengo algo que confesarte.', `FemaleText_loc1`='고해사제님, 당신에게 할 고백이 있습니다.', `FemaleText_loc4`='姑娘，我要向你坦白一件事。', `FemaleText_loc5`='小姑娘，我要向你告解。', `FemaleText_loc7`='Colega, tengo algo que confesarte.' WHERE `ID`=34255;
