UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 설교를 듣는 동안 강한 느낌을 받았습니다. 그 느낌이 날 괴롭히고 있단 말입니다!', `MaleText_loc4`='我在听你布道时，心中涌起了一股强烈的情感，我快疯掉了！', `MaleText_loc5`='在聽你佈道的時候，我感到一股強烈的情緒，它快把我給逼瘋了!', `MaleText_loc7`='Sentí algo muy fuerte mientras escuchaba tu sermón, ¡y me está volviendo loco!', `FemaleText_loc1`='당신의 설교를 듣는 동안 강한 느낌을 받았습니다. 그 느낌이 날 괴롭히고 있단 말입니다!', `FemaleText_loc4`='我在听你布道时，心中涌起了一股强烈的情感，我快疯掉了！', `FemaleText_loc5`='在聽你佈道的時候，我感到一股強烈的情緒，它快把我給逼瘋了!', `FemaleText_loc7`='Sentí algo muy fuerte mientras escuchaba tu sermón, ¡y me está volviendo loca!' WHERE `ID`=34257;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 그게 술을 마시고 싶습니다!', `MaleText_loc4`='……我想喝一杯！', `MaleText_loc5`='...我需要喝一杯!', `MaleText_loc7`='¡...NECESITO UN TRAGO!', `FemaleText_loc1`='... 그게 술을 마시고 싶습니다!', `FemaleText_loc4`='……我想喝一杯！', `FemaleText_loc5`='...我需要喝一杯!', `FemaleText_loc7`='¡...NECESITO UN TRAGO!' WHERE `ID`=34258;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇다면 적당히 드세요, 드워프 형제님. 하지만 당분간은 창과 고삐를 내려놓으셔야 할 겁니다. 성스러운 빛이 함께하시길...', `MaleText_loc4`='那就喝上几杯吧，我的矮人朋友。不过你最好先上缴你的长枪和缰绳。圣光与你同在。', `MaleText_loc5`='飲酒記得要適度，我的矮人朋友，但記得在喝酒後要把你的長槍與韁繩擺到一旁。願聖光與你同行。', `MaleText_loc7`='Bebe con moderación entonces, amig$go:a; enan$go:a;, aunque quizás quieras devolver tu lanza y tus riendas de momento. Ve con la Luz.', `FemaleText_loc1`='그렇다면 적당히 드세요, 드워프 형제님. 하지만 당분간은 창과 고삐를 내려놓으셔야 할 겁니다. 성스러운 빛이 함께하시길...', `FemaleText_loc4`='那就喝上几杯吧，我的矮人朋友。不过你最好先上缴你的长枪和缰绳。圣光与你同在。', `FemaleText_loc5`='飲酒記得要適度，我的矮人朋友，但記得在喝酒後要把你的長槍與韁繩擺到一旁。願聖光與你同行。', `FemaleText_loc7`='Bebe con moderación entonces, amig$go:a; enan$go:a;, aunque quizás quieras devolver tu lanza y tus riendas de momento. Ve con la Luz.' WHERE `ID`=34259;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 마음이 나날이 더 무겁소이다, 고해사제여.', `MaleText_loc4`='我的心情一天比一天沉重，神官。', `MaleText_loc5`='每經過一天，我的心就更沉重，告解者。', `MaleText_loc7`='Cada día que pasa mi corazón está más afligido, confesor.', `FemaleText_loc1`='내 마음이 나날이 더 무겁소이다, 고해사제여.', `FemaleText_loc4`='我的心情一天比一天沉重，神官。', `FemaleText_loc5`='每經過一天，我的心就更沉重，告解者。', `FemaleText_loc7`='Cada día que pasa mi corazón está más afligido, confesor.' WHERE `ID`=34260;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 이곳에서 할 일을 명받고 머물면서 스톰윈드의 깃발 아래 싸우고 있소. 하지만 이곳에서 내가 하는 모든 일은 공허하오.', `MaleText_loc4`='我被派来这里，以暴风城的名义作战。但是我所做的一切都毫无意义。', `MaleText_loc5`='我受命來到此地，我在暴風城的旗下作戰。但我在這裡所做的一切都毫無意義。', `MaleText_loc7`='Aquí me ordenaron venir, y aquí permanezco y lucho, bajo el estandarte de Ventormenta. Pero todo lo que aquí hago es vacuo.', `FemaleText_loc1`='난 이곳에서 할 일을 명받고 머물면서 스톰윈드의 깃발 아래 싸우고 있소. 하지만 이곳에서 내가 하는 모든 일은 공허하오.', `FemaleText_loc4`='我被派来这里，以暴风城的名义作战。但是我所做的一切都毫无意义。', `FemaleText_loc5`='我受命來到此地，我在暴風城的旗下作戰。但我在這裡所做的一切都毫無意義。', `FemaleText_loc7`='Aquí me ordenaron venir, y aquí permanezco y lucho, bajo el estandarte de Ventormenta. Pero todo lo que aquí hago es vacuo.' WHERE `ID`=34261;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이러한 견해를 넘어서서, 스컬지는 우리가 일궈낸 것을 점점 더 파괴하며 목적을 이루고자 일을 계속 벌리고 있소이다. 전투는 스컬지들이 있는 곳에서 치러야 하오. 난 그곳에 있어야 한단 말이오.', `MaleText_loc4`='在赛场之外，天灾军团仍在肆意破坏着我们的家园。那里才是真正的战场。而我，应该前往真正的战场。', `MaleText_loc5`='在此地之外，天譴軍團持續地活動，摧毀更多我們的建設。戰鬥應該要在那些地方進行。我應該要在那些地方。', `MaleText_loc7`='Más allá, la Plaga continúa su trabajo, y destruye más y más de lo que hemos construido. La lucha debería estar allí. Yo debería estar allí.', `FemaleText_loc1`='이러한 견해를 넘어서서, 스컬지는 우리가 일궈낸 것을 점점 더 파괴하며 목적을 이루고자 일을 계속 벌리고 있소이다. 전투는 스컬지들이 있는 곳에서 치러야 하오. 난 그곳에 있어야 한단 말이오.', `FemaleText_loc4`='在赛场之外，天灾军团仍在肆意破坏着我们的家园。那里才是真正的战场。而我，应该前往真正的战场。', `FemaleText_loc5`='在此地之外，天譴軍團持續地活動，摧毀更多我們的建設。戰鬥應該要在那些地方進行。我應該要在那些地方。', `FemaleText_loc7`='Más allá, la Plaga continúa su trabajo, y destruye más y más de lo que hemos construido. La lucha debería estar allí. Yo debería estar allí.' WHERE `ID`=34262;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 보호를 받지 못한 자들이 죽어가는 마당에 어찌 마상시합을 할 수 있단 말이오?', `MaleText_loc4`='我怎么能留在这里，让那些需要我来保护的人们惨死呢？', `MaleText_loc5`='如果人們因為沒有我的保護而死去，我又該怎麼評判這些馬上競技?', `MaleText_loc7`='¿Cómo puedo justificar el participar en justas mientras la gente muere sin mi protección?', `FemaleText_loc1`='내 보호를 받지 못한 자들이 죽어가는 마당에 어찌 마상시합을 할 수 있단 말이오?', `FemaleText_loc4`='我怎么能留在这里，让那些需要我来保护的人们惨死呢？', `FemaleText_loc5`='如果人們因為沒有我的保護而死去，我又該怎麼評判這些馬上競技?', `FemaleText_loc7`='¿Cómo puedo justificar el participar en justas mientras la gente muere sin mi protección?' WHERE `ID`=34263;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='근본이 착한 분이시군요. 그리고 형제께서 성스러운 빛에 헌신하고자 하시는 것도 압니다. 하지만 이런 소규모 공격 따위는 거대한 언데드 지도자에게 적은 피해만 줄 뿐입니다.', `MaleText_loc4`='你有一副好心肠，我知道你想要侍奉圣光。但是战场上的厮杀难以撼动天灾军团的首脑。', `MaleText_loc5`='你的心一直都在正確的地方，我知道你希望能替聖光服務。但這些小型的攻擊難以撼動不死大軍。', `MaleText_loc7`='Has tomado el partido correcto, y sé que quieres servir a la Luz. Pero estos pequeños ataques no hacen mella en los numerosas líneas de los no-muertos', `FemaleText_loc1`='근본이 착한 분이시군요. 그리고 형제께서 성스러운 빛에 헌신하고자 하시는 것도 압니다. 하지만 이런 소규모 공격 따위는 거대한 언데드 지도자에게 적은 피해만 줄 뿐입니다.', `FemaleText_loc4`='你有一副好心肠，我知道你想要侍奉圣光。但是战场上的厮杀难以撼动天灾军团的首脑。', `FemaleText_loc5`='你的心一直都在正確的地方，我知道你希望能替聖光服務。但這些小型的攻擊難以撼動不死大軍。', `FemaleText_loc7`='Has tomado el partido correcto, y sé que quieres servir a la Luz. Pero estos pequeños ataques no hacen mella en los numerosas líneas de los no-muertos' WHERE `ID`=34264;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번 마상시합은 분명하게 드러나진 않을지 몰라도 강하고 단합된 군대를 구성하는 데 도움을 주고 있답니다. 우리가 준비되면 은빛십자군과 용사들 모두의 주의가 얼음왕관 쪽으로 바뀔 겁니다.', `MaleText_loc4`='锦标赛的目的就是要建立一支强大而团结的军队，虽然这个目标看上去并不十分明确。待到一切准备就绪，北伐军以及麾下所有勇士的目光就会转向冰冠冰川了。', `MaleText_loc5`='這場聯賽在試圖建立一個強大而團結的部隊，或許並不顯著。等我們準備好，十字軍與所有的勇士們會將他們的目光轉向寒冰皇冠。', `MaleText_loc7`='Este torneo está contribuyendo a crear una fuerza poderosa y coordinada, aunque pueda no parecerlo. Cuando estemos preparados, las miradas de la Cruzada y las de todos sus campeones se dirigirán a Corona de Hielo.', `FemaleText_loc1`='이번 마상시합은 분명하게 드러나진 않을지 몰라도 강하고 단합된 군대를 구성하는 데 도움을 주고 있답니다. 우리가 준비되면 은빛십자군과 용사들 모두의 주의가 얼음왕관 쪽으로 바뀔 겁니다.', `FemaleText_loc4`='锦标赛的目的就是要建立一支强大而团结的军队，虽然这个目标看上去并不十分明确。待到一切准备就绪，北伐军以及麾下所有勇士的目光就会转向冰冠冰川了。', `FemaleText_loc5`='這場聯賽在試圖建立一個強大而團結的部隊，或許並不顯著。等我們準備好，十字軍與所有的勇士們會將他們的目光轉向寒冰皇冠。', `FemaleText_loc7`='Este torneo está contribuyendo a crear una fuerza poderosa y coordinada, aunque pueda no parecerlo. Cuando estemos preparados, las miradas de la Cruzada y las de todos sus campeones se dirigirán a Corona de Hielo.' WHERE `ID`=34265;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 은빛십자군은 전 종족의 힘을 리치 왕에게 이르게 할 것이며 그는 패배할 겁니다.', `MaleText_loc4`='我们将集结所有的力量向巫妖王发动攻击，而他，注定会失败。', `MaleText_loc5`='我們會集結所有種族的力量來對抗巫妖王，而他將會被打倒。', `MaleText_loc7`='Haremos caer el poder de todas las razas sobre el Rey Exánime, y será derrotado.', `FemaleText_loc1`='우리 은빛십자군은 전 종족의 힘을 리치 왕에게 이르게 할 것이며 그는 패배할 겁니다.', `FemaleText_loc4`='我们将集结所有的力量向巫妖王发动攻击，而他，注定会失败。', `FemaleText_loc5`='我們會集結所有種族的力量來對抗巫妖王，而他將會被打倒。', `FemaleText_loc7`='Haremos caer el poder de todas las razas sobre el Rey Exánime, y será derrotado.' WHERE `ID`=34266;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이러한 방법이 형제님께 분명한 길이 아닌 것 같다는 사실을 압니다만, 성스러운 빛에 더 가까이 다가가게 해 줄 겁니다. 잘 싸우세요, 형제님.', `MaleText_loc4`='我知道你对此尚有疑惑，但是这会让你更加接近圣光。战斗吧，我的兄弟。', `MaleText_loc5`='我知道這由你看來並不是一條明顯的道路，但這會引你更加靠近聖光。好好戰鬥吧，兄弟。', `MaleText_loc7`='Sé que este puede no parecerte el camino más obvio, pero te acercaré a la Luz. Pelea bien, herman$go:a;.', `FemaleText_loc1`='이러한 방법이 형제님께 분명한 길이 아닌 것 같다는 사실을 압니다만, 성스러운 빛에 더 가까이 다가가게 해 줄 겁니다. 잘 싸우세요, 형제님.', `FemaleText_loc4`='我知道你对此尚有疑惑，但是这会让你更加接近圣光。战斗吧，我的兄弟。', `FemaleText_loc5`='我知道這由你看來並不是一條明顯的道路，但這會引你更加靠近聖光。好好戰鬥吧，兄弟。', `FemaleText_loc7`='Sé que este puede no parecerte el camino más obvio, pero te acercaré a la Luz. Pelea bien, herman$go:a;.' WHERE `ID`=34267;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자폭 절차를 시작합니다.', `FemaleText_loc4`='自毁程序已经启动。', `FemaleText_loc5`='自毀程序已展開。', `FemaleText_loc7`='Fase de autodestrucción iniciada.' WHERE `ID`=34268;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 건 명예로운 전투가 아니오. 내 손에 쥔 도끼로 전투에서 적을 맞서길 고대해왔단 말이오.', `MaleText_loc4`='这根本不是荣耀之战。我渴望挥舞战斧，浴血沙场！', `MaleText_loc5`='這不是光榮的戰鬥。我渴望面對敵人時能手持我的戰斧!', `MaleText_loc7`='Esto no es combate honorable. ¡Ansío enfrentarme a mis oponentes en la batalla con un hacha en la mano!', `FemaleText_loc1`='이런 건 명예로운 전투가 아니오. 내 손에 쥔 도끼로 전투에서 적을 맞서길 고대해왔단 말이오.', `FemaleText_loc4`='这根本不是荣耀之战。我渴望挥舞战斧，浴血沙场！', `FemaleText_loc5`='這不是光榮的戰鬥。我渴望面對敵人時能手持我的戰斧!', `FemaleText_loc7`='Esto no es combate honorable. ¡Ansío enfrentarme a mis oponentes en la batalla con un hacha en la mano!' WHERE `ID`=34269;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이들은 내 적이오. 당신은 전투에서 내 적이었을 거요! 당신의 왕이란 자가 우리 종족과의 전쟁을 선언했잖소!', `MaleText_loc4`='他们都是我的敌人。在战场上，你也会是我的敌人！你们的国王已经向我族宣战了！', `MaleText_loc5`='這些都是我的敵人。你在戰場上也是我的敵人!你們的王向我的同胞宣戰!', `MaleText_loc7`='Estos son mis enemigos. ¡TÚ serías mi enemigo en la batalla! ¡Tu rey ha declarado la guerra a los míos!', `FemaleText_loc1`='이들은 내 적이오. 당신은 전투에서 내 적이었을 거요! 당신의 왕이란 자가 우리 종족과의 전쟁을 선언했잖소!', `FemaleText_loc4`='他们都是我的敌人。在战场上，你也会是我的敌人！你们的国王已经向我族宣战了！', `FemaleText_loc5`='這些都是我的敵人。你在戰場上也是我的敵人!你們的王向我的同胞宣戰!', `FemaleText_loc7`='Estos son mis enemigos. ¡TÚ serías mi enemigo en la batalla! ¡Tu rey ha declarado la guerra a los míos!' WHERE `ID`=34270;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 나는 내 형제들이 그러듯이, 내 형제들이 응당 그래야 하듯이, 싸우지 않았소. 난 길고 거대한 장창을 들었으나 휘두르지는 않은 채로 내 늑대가 시합 대상에게 돌진하게 하였소.', `MaleText_loc4`='我却不能像同胞们一样浴血奋战。我能做的，只是端着一根笨重的长枪，哄着座狼朝对手发起冲锋，根本就不是真正的攻击。', `MaleText_loc5`='我的族人理當、也應該去戰鬥，但我卻沒有。我發現自己拿著又長又笨重的木桿，誘騙我的狼向敵人衝鋒卻又不准攻擊他。', `MaleText_loc7`='Pero, en lugar de luchar como mi gente haría, como mi gente debiera, me veo con una incómoda hasta, intentando que mi lobo cargue contra mi oponente sin atacar.', `FemaleText_loc1`='하지만 나는 내 형제들이 그러듯이, 내 형제들이 응당 그래야 하듯이, 싸우지 않았소. 난 길고 거대한 장창을 들었으나 휘두르지는 않은 채로 내 늑대가 시합 대상에게 돌진하게 하였소.', `FemaleText_loc4`='我却不能像同胞们一样浴血奋战。我能做的，只是端着一根笨重的长枪，哄着座狼朝对手发起冲锋，根本就不是真正的攻击。', `FemaleText_loc5`='我的族人理當、也應該去戰鬥，但我卻沒有。我發現自己拿著又長又笨重的木桿，誘騙我的狼向敵人衝鋒卻又不准攻擊他。', `FemaleText_loc7`='Pero, en lugar de luchar como mi gente haría, como mi gente debiera, me veo con una incómoda hasta, intentando que mi lobo cargue contra mi oponente sin atacar.' WHERE `ID`=34271;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 건 오크가 싸우는 방식이 아니란 말이오! 대족장님에 대한 내 임무는 개인적인 명예를 담고 싸우는 것이오. 난 당신의 그 성스러운 빛에 아무런 믿음을 가지고 있지 않지만 조언자로 보이니 당신의 얘기를 듣고 싶소이다.', `MaleText_loc4`='这就不是兽人的作战方式！酋长的命令与个人的荣耀令我左右为难。我不信仰圣光，但是你看起来像是个不错的顾问，我想听听你的建议。', `MaleText_loc5`='這不是獸人的戰鬥!我以個人的榮譽服侍大酋長。我一點也不相信你們的聖光，但你看來像是個顧問，我想聽聽你的話。', `MaleText_loc7`='¡No es así como luchan los orcos! Mis obligaciones para con el Jefe de Guerra están en conflicto con mi honor personal. No tengo ninguna fe en tu Luz, pero, ya que pareces un consejero, escucharé tus palabras.', `FemaleText_loc1`='이런 건 오크가 싸우는 방식이 아니란 말이오! 대족장님에 대한 내 임무는 개인적인 명예를 담고 싸우는 것이오. 난 당신의 그 성스러운 빛에 아무런 믿음을 가지고 있지 않지만 조언자로 보이니 당신의 얘기를 듣고 싶소이다.', `FemaleText_loc4`='这就不是兽人的作战方式！酋长的命令与个人的荣耀令我左右为难。我不信仰圣光，但是你看起来像是个不错的顾问，我想听听你的建议。', `FemaleText_loc5`='這不是獸人的戰鬥!我以個人的榮譽服侍大酋長。我一點也不相信你們的聖光，但你看來像是個顧問，我想聽聽你的話。', `FemaleText_loc7`='¡No es así como luchan los orcos! Mis obligaciones para con el Jefe de Guerra están en conflicto con mi honor personal. No tengo ninguna fe en tu Luz, pero, ya que pareces un consejero, escucharé tus palabras.' WHERE `ID`=34272;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자폭 실행까지 남은 시간은 06분입니다.', `FemaleText_loc4`='本区域将在六分钟后自毁。', `FemaleText_loc5`='此區域將在六分鐘內自我毀滅。', `FemaleText_loc7`='Autodestrucción en SEIS minutos.' WHERE `ID`=34273;
