UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자폭 절차를 완료합니다. 이용해 주셔서 감사합니다!', `FemaleText_loc4`='自毁程序确认启动。祝你愉快！', `FemaleText_loc5`='自毀程序完成。祝您有個美好的一天!', `FemaleText_loc7`='Fase de autodestrucción terminada. ¡Buen día!' WHERE `ID`=34279;
