UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자폭 절차를 종료합니다. 재정의 코드 A-9-0-5.', `FemaleText_loc4`='自毁程序已中断。过载代码A-9-0-5。', `FemaleText_loc5`='自毀程序已終止。手控密碼A-9-0-5。', `FemaleText_loc7`='Fase de autodestrucción terminada. Código usado A-9-0-5. ' WHERE `ID`=34284;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 좌절감을 이해합니다. 당신 종족은 전투에서 사나우니 마상시합 같은 전투는 익숙하지 않은 일이겠지요.', `MaleText_loc4`='我理解你沮丧的心情。兽人作战时都非常勇猛，你一定不习惯锦标赛的方式。', `MaleText_loc5`='我瞭解你的挫折。你的族人在戰鬥中十分兇殘，但這並非你們原本的樣子。', `MaleText_loc7`='Entiendo tu frustración. Tu gente es feroz en el combate, y esto no es a lo que estás acostumbrad$go:a;.', `FemaleText_loc1`='당신의 좌절감을 이해합니다. 당신 종족은 전투에서 사나우니 마상시합 같은 전투는 익숙하지 않은 일이겠지요.', `FemaleText_loc4`='我理解你沮丧的心情。兽人作战时都非常勇猛，你一定不习惯锦标赛的方式。', `FemaleText_loc5`='我瞭解你的挫折。你的族人在戰鬥中十分兇殘，但這並非你們原本的樣子。', `FemaleText_loc7`='Entiendo tu frustración. Tu gente es feroz en el combate, y esto no es a lo que estás acostumbrad$go:a;.' WHERE `ID`=34285;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 마상시합은 다른 방식의 명예로운 전투입니다. 아마도 익숙해지려면 어렵겠지요. 하지만 당신의 무용이라면 오크족이 지닌 힘을 모두에게 보여줄 수 있을 거라 확신합니다.', `MaleText_loc4`='但是这依然是另一种形式的荣耀之战。你或许并不认可，但是我相信大家都目睹了你所表现出来的强大力量。', `MaleText_loc5`='這是另一種光榮的戰鬥。也許不容易習慣，但我確信你的英勇無畏將會向所有人展現你們族人的強大。', `MaleText_loc7`='Pero este es otro tipo de combate honorable. Quizás sea difícil adaptarse a él, pero, con tu valor, estoy seguro de que mostrarás a todo el mundo la fuerza de los tuyos.', `FemaleText_loc1`='하지만 마상시합은 다른 방식의 명예로운 전투입니다. 아마도 익숙해지려면 어렵겠지요. 하지만 당신의 무용이라면 오크족이 지닌 힘을 모두에게 보여줄 수 있을 거라 확신합니다.', `FemaleText_loc4`='但是这依然是另一种形式的荣耀之战。你或许并不认可，但是我相信大家都目睹了你所表现出来的强大力量。', `FemaleText_loc5`='這是另一種光榮的戰鬥。也許不容易習慣，但我確信你的英勇無畏將會向所有人展現你們族人的強大。', `FemaleText_loc7`='Pero este es otro tipo de combate honorable. Quizás sea difícil adaptarse a él, pero, con tu valor, estoy segura de que mostrarás a todo el mundo la fuerza de los tuyos.' WHERE `ID`=34286;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='게다가... 도끼 한 자루가 전쟁에서 유용한 도구인 한편, 창도 마찬가지로 쓸모가 있으니까요.', `MaleText_loc4`='而且……战斧的确很有杀伤力，但是长枪也不赖啊。', `MaleText_loc5`='此外...一把斧頭固然是戰場上的好夥伴，但長槍也有它的用處。', `MaleText_loc7`='Por otro lado... Aunque un hacha puede ser una valiosa herramienta en la guerra, las lanzas también tienen su utilidad.', `FemaleText_loc1`='게다가... 도끼 한 자루가 전쟁에서 유용한 도구인 한편, 창도 마찬가지로 쓸모가 있으니까요.', `FemaleText_loc4`='而且……战斧的确很有杀伤力，但是长枪也不赖啊。', `FemaleText_loc5`='此外...一把斧頭固然是戰場上的好夥伴，但長槍也有它的用處。', `FemaleText_loc7`='Por otro lado... Aunque un hacha puede ser una valiosa herramienta en la guerra, las lanzas también tienen su utilidad.' WHERE `ID`=34287;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성스러운 빛이 함께하시길, 오크여.', `MaleText_loc4`='圣光与你同在，兽人。', `MaleText_loc5`='願聖光與你同行，獸人。', `MaleText_loc7`='Ve con la Luz, orc$go:a;.', `FemaleText_loc1`='성스러운 빛이 함께하시길, 오크여.', `FemaleText_loc4`='圣光与你同在，兽人。', `FemaleText_loc5`='願聖光與你同行，獸人。', `FemaleText_loc7`='Ve con la Luz, orc$go:a;.' WHERE `ID`=34288;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 싸움은 끝이 없어요. 제가 얼마나 더 견뎌낼 수 있을지 확신할 수가 없네요.', `MaleText_loc4`='没完没了的战斗。我不知道自己还能坚持多久。', `MaleText_loc5`='這戰鬥彷彿永無止境。我不知到我還能承受幾場。', `MaleText_loc7`='Esta lucha es interminable. No estoy seguro de cuánto más podré aguantar.', `FemaleText_loc1`='이 싸움은 끝이 없어요. 제가 얼마나 더 견뎌낼 수 있을지 확신할 수가 없네요.', `FemaleText_loc4`='没完没了的战斗。我不知道自己还能坚持多久。', `FemaleText_loc5`='這戰鬥彷彿永無止境。我不知到我還能承受幾場。', `FemaleText_loc7`='Esta lucha es interminable. No estoy segura de cuánto más podré aguantar.' WHERE `ID`=34289;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 마음가짐, 시합장에서 하는 이런 무도 모든 게... 무의미한 것 같아요. 이게 다 무슨 소용이죠?', `MaleText_loc4`='赛场上这种装腔作势的打斗……根本毫无意义。有什么用呢？', `MaleText_loc5`='所有這些惺惺作態、這些在競技場中的小丑跳舞...全都毫無意義。有什麼用?', `MaleText_loc7`='Tanta postura y tanto bailar por ahí en círculos... no parece tener sentido. ¿Sirve para algo?', `FemaleText_loc1`='이런 마음가짐, 시합장에서 하는 이런 무도 모든 게... 무의미한 것 같아요. 이게 다 무슨 소용이죠?', `FemaleText_loc4`='赛场上这种装腔作势的打斗……根本毫无意义。有什么用呢？', `FemaleText_loc5`='所有這些惺惺作態、這些在競技場中的小丑跳舞...全都毫無意義。有什麼用?', `FemaleText_loc7`='Tanta postura y tanto bailar por ahí en círculos... no parece tener sentido. ¿Sirve para algo?' WHERE `ID`=34290;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='게다가 내 머리가 보호모 모양이 돼가고 있어요. 우스꽝스럽다고요!', `MaleText_loc4`='而且我的发型都被头盔压扁了。真是太滑稽了！', `MaleText_loc5`='我卻剪了一個馬桶蓋頭。這實在太滑稽了!', `MaleText_loc7`='Se me está empezando a quedar el PELO TIESO. ¡Es una aberración!', `FemaleText_loc1`='게다가 내 머리가 보호모 모양이 돼가고 있어요. 우스꽝스럽다고요!', `FemaleText_loc4`='而且我的发型都被头盔压扁了。真是太滑稽了！', `FemaleText_loc5`='我卻剪了一個馬桶蓋頭。這實在太滑稽了!', `FemaleText_loc7`='Se me está empezando a quedar el PELO TIESO. ¡Es una aberración!' WHERE `ID`=34291;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무의미해 보일 수 있습니다만, 멋진 시합에서 자긍심을 얻도록 해 보세요. 이런 연습과 경쟁 모든 게 뜻있게 쓰일 때가 올 겁니다.', `MaleText_loc4`='这看起来可能毫无意义，但是你可以试着在战斗中找到尊严。你迟早会发现这些练习的价值的。', `MaleText_loc5`='這或許看來沒有意義，但試著從一場好戰鬥中找出其尊嚴。等到時候到來，所有的練習與競賽都會展現出其中的價值。', `MaleText_loc7`='Quizás parezca que no tiene sentido, pero intento enorgullecerme de una buena pelea. Llegará el momento en que tanta práctica y competición serán de utilidad.', `FemaleText_loc1`='무의미해 보일 수 있습니다만, 멋진 시합에서 자긍심을 얻도록 해 보세요. 이런 연습과 경쟁 모든 게 뜻있게 쓰일 때가 올 겁니다.', `FemaleText_loc4`='这看起来可能毫无意义，但是你可以试着在战斗中找到尊严。你迟早会发现这些练习的价值的。', `FemaleText_loc5`='這或許看來沒有意義，但試著從一場好戰鬥中找出其尊嚴。等到時候到來，所有的練習與競賽都會展現出其中的價值。', `FemaleText_loc7`='Quizás parezca que no tiene sentido, pero intento enorgullecerme de una buena pelea. Llegará el momento en que tanta práctica y competición serán de utilidad.' WHERE `ID`=34292;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 당신 머리 모양은 멋져 보인답니다.', `MaleText_loc4`='而且你的发型看起来很棒。', `MaleText_loc5`='而且你的髮型看起來很棒!', `MaleText_loc7`='Y tu cabello tiene un aspecto maravilloso.', `FemaleText_loc1`='그리고 당신 머리 모양은 멋져 보인답니다.', `FemaleText_loc4`='而且你的发型看起来很棒。', `FemaleText_loc5`='而且你的髮型看起來很棒!', `FemaleText_loc7`='Y tu cabello tiene un aspecto maravilloso.' WHERE `ID`=34293;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='환상이 부서지며, 중앙에 있는 방으로 가는 길이 열립니다!', `MaleText_loc4`='幻象消散，通往中央房间的道路开启了！', `MaleText_loc5`='幻影粉碎，然後中央房間的道路就打開了!', `MaleText_loc7`='¡La ilusión se rompe y se abre un camino hacia la cámara central!' WHERE `ID`=34294;
