UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맹독가죽을 훈련해서 타려면 대단한 인내와 노력이 필요하지.', `MaleText_loc4`='训练并骑乘毒皮暴掠龙需要耗费大量精力。', `MaleText_loc5`='要訓練並且騎乘一隻毒皮暴掠龍需要付出大量的心血。', `MaleText_loc7`='Hace falta mucha dedicación para domar y montar un Pellejo Venenoso.' WHERE `ID`=34297;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런, 이런! 손님이 올 줄은 전혀 몰랐다고! 작업장이 이렇게 난장판인데... 아휴, 부끄러워라...', `MaleText_loc4`='哦，天哪！我没想到有人要来！工作间里真是一片狼藉。真丢人啊。', `MaleText_loc5`='噢!我的天!我沒想到會有訪客!工坊裡一團亂。真是丟臉。', `MaleText_loc7`='¡Caramba! ¡No esperaba compañía! El taller es un desorden total.  Qué vergüenza.' WHERE `ID`=34298;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='의무병!', `MaleText_loc4`='医生！', `MaleText_loc5`='醫護兵!', `MaleText_loc7`='¡MÉDICO!' WHERE `ID`=34299;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 고쳐 줄게! 아니, 안 되나? 어이구... 어찌나 난장판인지...', `MaleText_loc4`='我可以修好它……也许不行！呀，真是一团糟……', `MaleText_loc5`='我應該能修好它...也許不行!該死，這真是一團亂...', `MaleText_loc7`='Yo puedo arreglarlo... ¡O tal vez no! Caray, qué lío…' WHERE `ID`=34300;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='매혹적이야. 이런 걸 두고 한 방이라고 하지.', `MaleText_loc4`='真棒。我想他们应该是把这个叫做“完美击杀”。', `MaleText_loc5`='太屌了。我想他們把這個叫做「俐落擊殺」。', `MaleText_loc7`='Fascinante. Creo que eso se llama "ejecución impecable".' WHERE `ID`=34301;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적어놔야겠군. 대포는 살덩이에 대단히 효과적임.', `MaleText_loc4`='我得记下来：火炮对血肉之躯非常有效。', `MaleText_loc5`='要記下來:火砲對血肉極端有效。', `MaleText_loc7`='Nota mental: el cañón es altamente efectivo sobre la carne.' WHERE `ID`=34302;
