UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런, 이런! 시간이 다 된 것 같다, 친구들.', `MaleText_loc4`='哦，天哪！我们好像已经超时了，朋友们。', `MaleText_loc5`='噢，我的天!看來我們的時間用完了，我的朋友。', `MaleText_loc7`='¡Caramba! Parece que se nos acabó el tiempo, mis amigos.' WHERE `ID`=34305;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='건방진 젖먹이들이! 세상을 되찾는 데 쓸 무기를 네놈들의 피로 담금질하겠다!', `MaleText_loc4`='大胆！今天就要以尔等的鲜血，为曾用来改造这个世界的武器淬火！', `MaleText_loc5`='傲慢的小傢伙!你們的鮮血將會用來淬鍊重奪世界的武器!', `MaleText_loc7`='¡Cachorros insolentes! ¡Su sangre templará las armas usadas para reclamar este mundo!' WHERE `ID`=34306;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일어나라, 무쇠 용광로의 병사들이여! 창조주의 뜻은 이루어지리라!', `MaleText_loc4`='觉醒吧，钢铁熔炉中的兵士！执行造物者的意志！', `MaleText_loc5`='起來吧，鐵爐缸的士兵們!造物者的旨意終將實現!', `MaleText_loc7`='¡Levántense, soldados del crisol férreo! ¡Se hará la voluntad del creador!' WHERE `ID`=34307;
