UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세상에서 가장 큰 모기건 세상에서 가장 위대한 영웅이건, 너흰 어차피 필멸의 존재야.', `MaleText_loc4`='任你是天下最厉害的恶棍，还是最强大的英雄，都只不过是凡人之躯。', `MaleText_loc5`='不管你是世界第一流的小卒，或是首屈一指的英雄人物，充其量也不過是個凡人罷了。', `MaleText_loc7`='Ya seáis los mayores mequetrefes o los mayores héroes del mundo, seguís siendo mortales.' WHERE `ID`=34314;
