UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='으아아아아아! 살려주세요! 이것들 좀 떼주세요!', `FemaleText_loc4`='救命啊！别让它们靠近我！', `FemaleText_loc5`='救命!別讓他們靠近我!', `FemaleText_loc7`='¡AYÚDENME! ¡Sáquenmelos de encima, por favor!' WHERE `ID`=34342;
