UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋아요! 네! 자비를 베풀지 마세요! 쉴 새 없이 공격하세요!', `FemaleText_loc4`='对！没错！不要手下留情！不要停止攻击！', `FemaleText_loc5`='對!沒錯!別對他們手下留情!別停下你的攻擊!', `FemaleText_loc7`='¡Sí! ¡SÍ! ¡Sin misericordia! ¡No detengas tus ataques ni por un momento!' WHERE `ID`=34344;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='증오와 분노를 마음껏 터뜨리세요!', `FemaleText_loc4`='让仇恨和愤怒指引你们战斗吧！', `FemaleText_loc5`='讓仇恨與狂怒帶領你的攻擊!', `FemaleText_loc7`='¡Deja que el odio y la ira guíen tus golpes! ' WHERE `ID`=34345;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='짐승의 대장을 칠 때가 곧 다가올 거예요! 놈의 졸개들에게 노여움과 미움을 쏟아부으세요!', `FemaleText_loc4`='攻击这头野兽要害的时刻即将来临！将你们的愤怒和仇恨倾泻到它的爪牙身上！', `FemaleText_loc5`='我們即將有機會打擊怪物的首腦!現在將你的憤怒與仇恨貫注在他的爪牙上!', `FemaleText_loc7`='¡El momento de atacar la cabeza de la bestia está por llegar! ¡Enfoca tu furia y tu odio en sus lacayos!' WHERE `ID`=34346;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네 증오에 숨 막혀 버려라!', `FemaleText_loc4`='被你们自己的仇恨吞噬吧！', `FemaleText_loc5`='在你自己的仇恨中窒息吧!', `FemaleText_loc7`='¡Sofócate con tu propio odio!' WHERE `ID`=34347;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다가오는 종말 앞에 몸서리쳐라!', `FemaleText_loc4`='战栗吧，凡人们，末日就要来临了！', `FemaleText_loc5`='在即將到來的末日之前，顫抖吧，凡人。', `FemaleText_loc7`='¡Tiemblen, mortales, ante la llegada del fin!' WHERE `ID`=34348;
