UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음의 진정한 얼굴을 보아라! 다가오는 종말을 느껴라!', `MaleText_loc4`='凝视死亡的真正面孔吧，你们的末日就要来了！', `MaleText_loc5`='看看死亡的真實面貌，瞭解你們的末日降臨了!', `MaleText_loc7`='¡Mira el verdadero rostro de la muerte y sabrás que tú fin se acerca!' WHERE `ID`=34360;
