UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영원한 고통이 기다린다!', `MaleText_loc4`='永恒的痛苦在等待着你！', `MaleText_loc5`='永恆的苦難等著你!', `MaleText_loc7`='¡Te espera el sufrimiento eterno!' WHERE `ID`=34362;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너의 의지가 너를 배반한다.', `MaleText_loc4`='你的意志不属于你自己。', `MaleText_loc5`='你的意志不再屬於你自己。', `MaleText_loc7`='Tu voluntad ya no es tuya.' WHERE `ID`=34363;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들을 없애라! 네 주인이 명하노라!', `MaleText_loc4`='我的奴仆，快去毁灭他们！这是主人的命令！', `MaleText_loc5`='摧毀他們，手下們!這是你主人的命令!', `MaleText_loc7`='¡Destrúyelo, lacayo! ¡Te lo ordena tu amo!' WHERE `ID`=34364;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 운명이 결정됐다. 너희와, 이 작고 가련한 세상에 사는 모든 것들에게 마침내 종말이 닥친다. 우울위 이피스 할란 가그 에르옹그 위스...', `MaleText_loc4`='你们的命运早已注定。末日即将降临于这个可笑而渺小的世界，你们所有人都要灭亡。Uulwi ifis halahs gag erh''ongg w''ssh.', `MaleText_loc5`='你們的命運已經注定。末日到來，所有居住在這可悲幼苗上的生物將無一倖免。(古神語)寄宿在我屍體上的陰影將永世侵擾這片大地。', `MaleText_loc7`='Tu destino fue sellado. El fin de los tiempos ha llegado para ti y para TODOS los habitantes de este retoñito miserable. Uulwi ifis halahs gag erh''ongg w''ssh.' WHERE `ID`=34365;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용사들이여, 겨울의 장막이 너희를 보호하리라!', `MaleText_loc4`='寒冬将会庇护你们，勇士们！', `MaleText_loc5`='凜冬之幕將守護著你，勇士們!', `MaleText_loc7`='¡El velo del invierno los protegerá, campeones!' WHERE `ID`=34366;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이오나여, 당신의 종이 축복을 기원합니다!', `FemaleText_loc4`='艾欧娜尔，请祝福您的仆人！', `FemaleText_loc5`='伊歐娜，你的僕從請求你的祝福!', `FemaleText_loc7`='¡Eonar, tu siervo necesita de tu bendición!' WHERE `ID`=34367;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투 회로망 강화! 놀라운 속도를 즐기라고!', `MaleText_loc4`='战斗矩阵已强化。全速突击！', `MaleText_loc5`='戰鬥矩陣已經強化。瞧瞧這驚人的速度!', `MaleText_loc7`='Matriz de combate mejorada. ¡Observen la extraordinaria rapidez!' WHERE `ID`=34368;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='골가네스여, 제게 힘을 주소서! 필멸의 동료에게 번개의 힘을 나눠주소서!', `MaleText_loc4`='高戈奈斯，将您的威能赐予我！让我的战友们获得雷霆的力量！', `MaleText_loc5`='葛剛尼斯，將你的神力賜給我!賦予我的凡人盟友們雷霆的力量!', `MaleText_loc7`='¡Golganneth, dame tu fuerza! ¡Brinda a mis aliados mortales el poder del trueno!' WHERE `ID`=34369;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거대한 용암거인이 약해지자, 불길하게 느껴지는 한 마디가 천둥소리처럼 허공에 메아리칩니다. "불타라..."', `MaleText_loc4`='熔火巨人的力量逐渐被削弱，一声低沉的怒吼如闷雷般在空气中轰隆作响：“燃烧吧”。', `MaleText_loc5`='當熔火巨像衰弱時，一句不祥的話語迴盪在空氣中宛如雷鳴:「燃燒吧」', `MaleText_loc7`='Mientras el coloso fundido se debilita, una única y ominosa palabra resuena en el aire como un trueno: "ARDE"' WHERE `ID`=34370;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아스트라나르로 복귀하십시오!', `MaleText_loc4`='返回阿斯特兰纳！', `MaleText_loc5`='回到阿斯特蘭納!', `MaleText_loc7`='¡Regresa a Astranaar!' WHERE `ID`=34371;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 숲을 조심해서 지나가게. 그렇지 않으면 나무들이 마치 눈이 달린 것처럼 우리의 정체를 적에게 알릴 것이네.', `MaleText_loc4`='$c，走在这片树林里的时候一定要放轻脚步。这些树仿佛有眼睛，而且还会和我们的敌人说话。', `MaleText_loc5`='靜靜地穿過這片森林，$c。這些樹感覺就像是有眼睛和會對我們的敵人說悄悄話。', `MaleText_loc7`='Ve con pies de plomo por estos bosques, $c. Es como si los propios árboles tuvieran ojos y susurraran a nuestros enemigos.' WHERE `ID`=34372;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='몰샨의 망루로 보내주십시오.', `MaleText_loc4`='库格，送我去莫尔杉营地。', `MaleText_loc5`='送我到莫爾杉壁壘，庫爾格。', `MaleText_loc7`='Envíame a la Empalizada de Mor''shan, Kulg.', `FemaleText_loc1`='몰샨의 망루로 보내주세요.', `FemaleText_loc4`='库格，送我去莫尔杉营地。', `FemaleText_loc5`='送我到莫爾杉壁壘，庫爾格。', `FemaleText_loc7`='Envíame a la Empalizada de Mor''shan, Kulg.' WHERE `ID`=34373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대상이 당신의 돌진을 피했습니다.', `MaleText_loc4`='目标躲过了你的冲锋。', `MaleText_loc5`='你的目標閃過了你的衝鋒。', `MaleText_loc7`='Tu objetivo ha esquivado tu carga.', `FemaleText_loc1`='대상이 당신의 돌진을 피했습니다.', `FemaleText_loc4`='目标躲过了你的冲锋。', `FemaleText_loc5`='你的目標閃過了你的衝鋒。', `FemaleText_loc7`='Tu objetivo ha esquivado tu carga.' WHERE `ID`=34374;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대상이 균형 흔들기로 비틀거리며 넘어집니다.', `MaleText_loc4`='目标被打得失去了平衡。', `MaleText_loc5`='你的目標已經失去平衡。', `MaleText_loc7`='Tu objetivo ha perdido el equilibrio.', `FemaleText_loc1`='대상이 균형 흔들기로 비틀거리며 넘어집니다.', `FemaleText_loc4`='目标被打得失去了平衡。', `FemaleText_loc5`='你的目標已經失去平衡。', `FemaleText_loc7`='Tu objetivo ha perdido el equilibrio.' WHERE `ID`=34375;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대상이 창을 들고 준비 자세를 취한 당신의 돌진을 기다립니다.', `MaleText_loc4`='目标端起长枪，等待你发起冲锋。', `MaleText_loc5`='你的目標正等你以準備好的長槍對它衝鋒。', `MaleText_loc7`='Tu objetivo estaba esperando tu carga con la lanza preparada.', `FemaleText_loc1`='대상이 창을 들고 준비 자세를 취한 당신의 돌진을 기다립니다.', `FemaleText_loc4`='目标端起长枪，等待你发起冲锋。', `FemaleText_loc5`='你的目標正等你以準備好的長槍對它衝鋒。', `FemaleText_loc7`='Tu objetivo estaba esperando tu carga con la lanza preparada.' WHERE `ID`=34376;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은빛십자군 기수들은 어떻게 싸우나요?', `MaleText_loc4`='银色北伐军的骑兵是如何作战的？', `MaleText_loc5`='銀白十字軍騎士的戰鬥風格是怎樣?', `MaleText_loc7`='¿Cómo luchan los jinetes de la Cruzada Argenta?', `FemaleText_loc1`='은빛십자군 기수들은 어떻게 싸우나요?', `FemaleText_loc4`='银色北伐军的骑兵是如何作战的？', `FemaleText_loc5`='銀白十字軍騎士的戰鬥風格是怎樣?', `FemaleText_loc7`='¿Cómo luchan los jinetes de la Cruzada Argenta?' WHERE `ID`=34377;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은빛십자군 기수들은 균형과 정밀함, 공격과 방어의 절묘한 조합을 신조로 한답니다.$B$B하지만 그들은 당신을 상대로 거리를 잡느라 종종 돌진 기술에 노출될 거예요.$B$B당신이 당하기 전에 먼저 돌진해서 거리를 좁히시고, 찌르기를 위해 방향을 바꾸면서 방패 부수기를 사용하세요.', `MaleText_loc4`='银色北伐军的骑兵将攻击和防御巧妙地结合起来，在作战中实现平衡与精准。$B$B但是，由于他们需要时刻与你保持距离，因此你可以伺机冲锋。$B$B你必须抢在他们之前发起冲锋，拉近彼此的距离，接下来在围绕他们跑动的过程中使用碎盾并看准机会使用刺击。', `MaleText_loc5`='銀白十字軍以平衡與精確為信條，靈巧而熟練地交替攻擊與防禦。$B$B但是當他們想要拉開距離的時候，往往也會讓自己暴露在衝鋒的危險下。$B$B在他們來得及反應前，用衝鋒縮短距離，然後對他們使用破盾然後搭配更多的戳刺。', `MaleText_loc7`='Los jinetes de la Cruzada Argenta creen en el equilibrio y en la precisión, y combinan con destreza el ataque y la defensa.$b$bSin embargo, a menudo se expondrán a una carga al intentar tomar distancia contigo.$b$bReduce esa distancia empleando Cargar antes de que ellos hagan lo mismo, y después emplea Romper escudo mientras te das la vuelta para utilizar Estocada de nuevo.', `FemaleText_loc1`='은빛십자군 기수들은 균형과 정밀함, 공격과 방어의 절묘한 조합을 신조로 한답니다.$B$B하지만 그들은 당신을 상대로 거리를 잡느라 종종 돌진 기술에 노출될 거예요.$B$B당신이 당하기 전에 먼저 돌진해서 거리를 좁히시고, 찌르기를 위해 방향을 바꾸면서 방패 부수기를 사용하세요.', `FemaleText_loc4`='银色北伐军的骑兵将攻击和防御巧妙地结合起来，在作战中实现平衡与精准。$B$B但是，由于他们需要时刻与你保持距离，因此你可以伺机冲锋。$B$B你必须抢在他们之前发起冲锋，拉近彼此的距离，接下来在围绕他们跑动的过程中使用碎盾并看准机会使用刺击。', `FemaleText_loc5`='銀白十字軍以平衡與精確為信條，靈巧而熟練地交替攻擊與防禦。$B$B但是當他們想要拉開距離的時候，往往也會讓自己暴露在衝鋒的危險下。$B$B在他們來得及反應前，用衝鋒縮短距離，然後對他們使用破盾然後搭配更多的戳刺。', `FemaleText_loc7`='Los jinetes de la Cruzada Argenta creen en el equilibrio y en la precisión, y combinan con destreza el ataque y la defensa.$b$bSin embargo, a menudo se expondrán a una carga al intentar tomar distancia contigo.$b$bReduce esa distancia empleando Cargar antes de que ellos hagan lo mismo, y después emplea Romper escudo mientras te das la vuelta para utilizar Estocada de nuevo.' WHERE `ID`=34378;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드 기수들은 대담하고도 압도적인 돌진 기술을 자랑한답니다. 어찌나 실력이 좋고 사나운지, 돌진을 맞는 즉시 상대에게 역으로 돌진하지요.$B$B거리를 좁히고 찌르기를 노리세요. 그들이 당신과 거리를 두려고 하면, 먼저 방패 부수기로 균형 흔들기를 한 다음에 돌진하세요. 그러지 않으면 항상 그들과 맞부딪치고 말 거예요.', `MaleText_loc4`='暴风城的骑兵以其无畏而极具破坏性的冲锋为傲。即便是被对方冲锋，他们也能立即以牙还牙，这就是暴风城骑兵的可怕之处了。$B$B你要尽可能地打近身战并使用刺击，当他们试图拉开距离时，先利用碎盾令他们失去平衡，然后使用冲锋。否则，他们会不断地向你发动正面攻击。', `MaleText_loc5`='暴風城騎士以他們的無畏與破壞力極大的衝鋒而自豪。靠著他們的技巧與兇猛天性，他們在遭遇衝鋒時甚至會也跟著反衝鋒回去。$B$B試著貼近他們並利用戳刺，當他們想拉開距離時，先用破盾令其失去平衡，接著再使用衝鋒。否則，他們每次都會給你迎頭痛擊。', `MaleText_loc7`='Los jinetes de Ventormenta se enorgullecen de sus temerarias y devastadoras cargas. Es tanta su habilidad y ferocidad que, cuando reciben una carga, sencillamente la devuelven.$b$bIntenta mantenerte cerca de ellos y emplear Estocada, y cuando intenten tomar distancia, ponlos en desventaja empleando Romper escudo antes de Cargar. Si no, se abalanzarán sobre ti todo el rato.', `FemaleText_loc1`='스톰윈드 기수들은 대담하고도 압도적인 돌진 기술을 자랑한답니다. 어찌나 실력이 좋고 사나운지, 돌진을 맞는 즉시 상대에게 역으로 돌진하지요.$B$B거리를 좁히고 찌르기를 노리세요. 그들이 당신과 거리를 두려고 하면, 먼저 방패 부수기로 균형 흔들기를 한 다음에 돌진하세요. 그러지 않으면 항상 그들과 맞부딪치고 말 거예요.', `FemaleText_loc4`='暴风城的骑兵以其无畏而极具破坏性的冲锋为傲。即便是被对方冲锋，他们也能立即以牙还牙，这就是暴风城骑兵的可怕之处了。$B$B你要尽可能地打近身战并使用刺击，当他们试图拉开距离时，先利用碎盾令他们失去平衡，然后使用冲锋。否则，他们会不断地向你发动正面攻击。', `FemaleText_loc5`='暴風城騎士以他們的無畏與破壞力極大的衝鋒而自豪。靠著他們的技巧與兇猛天性，他們在遭遇衝鋒時甚至會也跟著反衝鋒回去。$B$B試著貼近他們並利用戳刺，當他們想拉開距離時，先用破盾令其失去平衡，接著再使用衝鋒。否則，他們每次都會給你迎頭痛擊。', `FemaleText_loc7`='Los jinetes de Ventormenta se enorgullecen de sus temerarias y devastadoras cargas. Es tanta su habilidad y ferocidad que, cuando reciben una carga, sencillamente la devuelven.$b$bIntenta mantenerte cerca de ellos y emplear Estocada, y cuando intenten tomar distancia, ponlos en desventaja empleando Romper escudo antes de Cargar. Si no, se abalanzarán sobre ti todo el rato.' WHERE `ID`=34379;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈리건 기수들은 균형과 정밀함, 공격과 방어의 절묘한 조합을 신조로 한답니다.$B$B하지만 그들은 당신을 상대로 거리를 잡느라 종종 돌진 기술에 노출될 거예요.$B$B당신이 당하기 전에 먼저 돌진해서 거리를 좁히시고, 찌르기를 위해 방향을 바꾸면서 방패 부수기를 사용하세요.', `MaleText_loc4`='诺莫瑞根的骑兵将攻击和防御巧妙地结合起来，在作战中实现平衡与精准。$B$B但是，由于他们需要时刻与你保持距离，因此你可以伺机冲锋。$B$B你必须抢在他们之前发起冲锋，拉近彼此的距离，接下来在围绕他们跑动的过程中使用碎盾并看准机会使用刺击。', `MaleText_loc5`='諾姆瑞根騎士以平衡與精確為信條，靈巧而熟練地交替攻擊與防禦。$B$B但是當他們想要拉開距離的時候，往往也會讓自己暴露在衝鋒的危險下。$B$B在他們來得及反應前，用衝鋒縮短距離，然後對他們使用破盾然後搭配更多的戳刺。', `MaleText_loc7`='Los jinetes de Gnomeregan creen en el equilibrio y en la precisión, y combinan con destreza el ataque y la defensa.$b$bSin embargo, a menudo se expondrán a una carga al intentar tomar distancia contigo.$b$bReduce esa distancia empleando Cargar antes de que ellos hagan lo mismo, y después emplea Romper escudo mientras te das la vuelta para utilizar Estocada de nuevo.', `FemaleText_loc1`='놈리건 기수들은 균형과 정밀함, 공격과 방어의 절묘한 조합을 신조로 한답니다.$B$B하지만 그들은 당신을 상대로 거리를 잡느라 종종 돌진 기술에 노출될 거예요.$B$B당신이 당하기 전에 먼저 돌진해서 거리를 좁히시고, 찌르기를 위해 방향을 바꾸면서 방패 부수기를 사용하세요.', `FemaleText_loc4`='诺莫瑞根的骑兵将攻击和防御巧妙地结合起来，在作战中实现平衡与精准。$B$B但是，由于他们需要时刻与你保持距离，因此你可以伺机冲锋。$B$B你必须抢在他们之前发起冲锋，拉近彼此的距离，接下来在围绕他们跑动的过程中使用碎盾并看准机会使用刺击。', `FemaleText_loc5`='諾姆瑞根騎士以平衡與精確為信條，靈巧而熟練地交替攻擊與防禦。$B$B但是當他們想要拉開距離的時候，往往也會讓自己暴露在衝鋒的危險下。$B$B在他們來得及反應前，用衝鋒縮短距離，然後對他們使用破盾然後搭配更多的戳刺。', `FemaleText_loc7`='Los jinetes de Gnomeregan creen en el equilibrio y en la precisión, y combinan con destreza el ataque y la defensa.$b$bSin embargo, a menudo se expondrán a una carga al intentar tomar distancia contigo.$b$bReduce esa distancia empleando Cargar antes de que ellos hagan lo mismo, y después emplea Romper escudo mientras te das la vuelta para utilizar Estocada de nuevo.' WHERE `ID`=34380;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다르나서스 기수들은 기술과 민첩함에 의지한 원거리 전투에 능하답니다.$B$B그들은 재빠르고 노련해서 당신의 돌진을 회피할 수 있어요. 그러니 거리를 좁혀 찌르기를 주로 사용하시면서 가끔 방패 부수기를 섞어서 쓰셔야 그들을 이기실 수 있을 거예요.', `MaleText_loc4`='达纳苏斯的骑兵以灵巧与远程攻击著称。$B$B他们敏捷的身手足以避开你的冲锋，因此你必须灵活运用近距离刺击和碎盾攻击，才有可能击败他们。', `MaleText_loc5`='達納蘇斯騎士在遠程距離仰賴他們的敏捷與技巧。$B$B他們動作迅速而靈巧，足以閃避你的衝鋒，所以試著混合近距離的戳刺，以及偶一為之的破盾來擊敗他們。', `MaleText_loc7`='Los jinetes de Darnassus cuentan con su agilidad y destreza a distancia.$b$bSon suficientemente rápidos y esquivos para evitar tu Cargar, así que intenta emplear una mezcla de Estocada y algún ocasional Romper escudo para derrotarlos.', `FemaleText_loc1`='다르나서스 기수들은 기술과 민첩함에 의지한 원거리 전투에 능하답니다.$B$B그들은 재빠르고 노련해서 당신의 돌진을 회피할 수 있어요. 그러니 거리를 좁혀 찌르기를 주로 사용하시면서 가끔 방패 부수기를 섞어서 쓰셔야 그들을 이기실 수 있을 거예요.', `FemaleText_loc4`='达纳苏斯的骑兵以灵巧与远程攻击著称。$B$B他们敏捷的身手足以避开你的冲锋，因此你必须灵活运用近距离刺击和碎盾攻击，才有可能击败他们。', `FemaleText_loc5`='達納蘇斯騎士在遠程距離仰賴他們的敏捷與技巧。$B$B他們動作迅速而靈巧，足以閃避你的衝鋒，所以試著混合近距離的戳刺，以及偶一為之的破盾來擊敗他們。', `FemaleText_loc7`='Los jinetes de Darnassus cuentan con su agilidad y destreza a distancia.$b$bSon suficientemente rápidos y esquivos para evitar tu Cargar, así que intenta emplear una mezcla de Estocada y algún ocasional Romper escudo para derrotarlos.' WHERE `ID`=34382;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이언포지 기수들은 불굴의 용사랍니다. 방어에 중점을 두면서, 맞으면 되받아치는 식으로 상대와 꼬박꼬박 공격을 주고받지요.$B$B당신의 방어를 단단히 유지하면서 돌진 기술로 그들이 지치게 하세요... 방어에서 우위를 점하고 있을 때 맞붙어서, 공격을 주고받을 때마다 그들이 더 큰 타격을 입게 하세요.', `MaleText_loc4`='铁炉堡的骑兵是一群坚韧的勇士，他们擅长防御与持久作战。$B$B你应该在维持自身防御的前提下使用冲锋把他们累得趴下……只要你能保持防御优势，他们就会在对战中承受较大的伤害。', `MaleText_loc5`='鐵爐堡騎士相當的頑強，他們的防禦堅強並且持續不斷地以一拳換一拳的方式，攻擊他們的敵手。$B$B試著靠衝鋒把他們打下馬，並且同時維持你自己防禦...盡可能讓他們處於防禦弱勢，這樣他們每次交換攻擊時才會受到更大的損失。', `MaleText_loc7`='Los jinetes de Forjaz son gente tenaz que confía mucho en su defensa y que intercambia golpes constantemente con sus oponentes.$b$bIntenta debilitarlos empleando Cargar mientras empleas Defender... Enfréntate a ellos con una ventaja defensiva de modo que reciban más daño que tú en cada intercambio.', `FemaleText_loc1`='아이언포지 기수들은 불굴의 용사랍니다. 방어에 중점을 두면서, 맞으면 되받아치는 식으로 상대와 꼬박꼬박 공격을 주고받지요.$B$B당신의 방어를 단단히 유지하면서 돌진 기술로 그들이 지치게 하세요... 방어에서 우위를 점하고 있을 때 맞붙어서, 공격을 주고받을 때마다 그들이 더 큰 타격을 입게 하세요.', `FemaleText_loc4`='铁炉堡的骑兵是一群坚韧的勇士，他们擅长防御与持久作战。$B$B你应该在维持自身防御的前提下使用冲锋把他们累得趴下……只要你能保持防御优势，他们就会在对战中承受较大的伤害。', `FemaleText_loc5`='鐵爐堡騎士相當的頑強，他們的防禦堅強並且持續不斷地以一拳換一拳的方式，攻擊他們的敵手。$B$B試著靠衝鋒把他們打下馬，並且同時維持你自己防禦...盡可能讓他們處於防禦弱勢，這樣他們每次交換攻擊時才會受到更大的損失。', `FemaleText_loc7`='Los jinetes de Forjaz son gente tenaz que confía mucho en su defensa y que intercambia golpes constantemente con sus oponentes.$b$bIntenta debilitarlos empleando Cargar mientras empleas Defender... Enfréntate a ellos con una ventaja defensiva de modo que reciban más daño que tú en cada intercambio.' WHERE `ID`=34383;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엑소다르 기수들은 특히 근접 전투에서 위력을 발휘하는 굳세고 강력한 전사들이랍니다.$B$B당신의 방어를 압도하는 그들의 찌르기 기술에 당하지 않도록, 사정거리 밖을 맴도세요. 돌진을 사용하기 전에는 먼저 방패 부수기로 상대의 방어를 무너뜨리시고요.', `MaleText_loc4`='埃索达的骑兵是魁梧而强壮的战士，近身战时能爆发出可怕的威力。$B$B他们的刺击势如破竹，你要尽量拉远彼此的距离，并在发起冲锋前使用碎盾打破他们的防御。', `MaleText_loc5`='艾克索達騎士是巨大而強壯的戰士，在近距離時非常恐怖。$B$B試著遠離他們足以粉碎防禦的戳刺攻擊，盡量用破盾破壞他們的防禦然後冒險對他們使用衝鋒。', `MaleText_loc7`='Los jinetes de El Exodar son unos combatientes enormes y poderosos, terribles cuerpo a cuerpo.$b$bIntenta mantenerte fuera del alcance de su devastadora Estocada, y destruye sus defensas con Romper escudo antes de arriesgarte a Cargar.', `FemaleText_loc1`='엑소다르 기수들은 특히 근접 전투에서 위력을 발휘하는 굳세고 강력한 전사들이랍니다.$B$B당신의 방어를 압도하는 그들의 찌르기 기술에 당하지 않도록, 사정거리 밖을 맴도세요. 돌진을 사용하기 전에는 먼저 방패 부수기로 상대의 방어를 무너뜨리시고요.', `FemaleText_loc4`='埃索达的骑兵是魁梧而强壮的战士，近身战时能爆发出可怕的威力。$B$B他们的刺击势如破竹，你要尽量拉远彼此的距离，并在发起冲锋前使用碎盾打破他们的防御。', `FemaleText_loc5`='艾克索達騎士是巨大而強壯的戰士，在近距離時非常恐怖。$B$B試著遠離他們足以粉碎防禦的戳刺攻擊，盡量用破盾破壞他們的防禦然後冒險對他們使用衝鋒。', `FemaleText_loc7`='Los jinetes de El Exodar son unos combatientes enormes y poderosos, terribles cuerpo a cuerpo.$b$bIntenta mantenerte fuera del alcance de su devastadora Estocada, y destruye sus defensas con Romper escudo antes de arriesgarte a Cargar.' WHERE `ID`=34384;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='센진 기수들은 기술과 민첩함에 의지한 원거리 전투에 능하답니다.$B$B그들은 재빠르고 노련해서 당신의 돌진을 회피할 수 있어요. 그러니 거리를 좁혀 찌르기를 주로 사용하시면서 가끔 방패 부수기를 섞어서 쓰셔야 그들을 이기실 수 있을 거예요.', `MaleText_loc4`='森金的骑兵以灵巧与远程攻击著称。$B$B他们敏捷的身手足以避开你的冲锋，因此你必须灵活运用近距离刺击和碎盾攻击，才有可能击败他们。', `MaleText_loc5`='森金騎士在遠程距離仰賴他們的敏捷與技巧。$B$B他們動作迅速而靈巧，足以閃避你的衝鋒，所以試著混合近距離的戳刺，以及偶一為之的破盾來擊敗他們。', `MaleText_loc7`='Los jinetes de Sen''jin cuentan con su agilidad y destreza a distancia.$b$bSon suficientemente rápidos y esquivos para evitar tu Cargar, así que intenta emplear una mezcla de Estocada y algún ocasional Romper escudo para derrotarlos.', `FemaleText_loc1`='센진 기수들은 기술과 민첩함에 의지한 원거리 전투에 능하답니다.$B$B그들은 재빠르고 노련해서 당신의 돌진을 회피할 수 있어요. 그러니 거리를 좁혀 찌르기를 주로 사용하시면서 가끔 방패 부수기를 섞어서 쓰셔야 그들을 이기실 수 있을 거예요.', `FemaleText_loc4`='森金的骑兵以灵巧与远程攻击著称。$B$B他们敏捷的身手足以避开你的冲锋，因此你必须灵活运用近距离刺击和碎盾攻击，才有可能击败他们。', `FemaleText_loc5`='森金騎士在遠程距離仰賴他們的敏捷與技巧。$B$B他們動作迅速而靈巧，足以閃避你的衝鋒，所以試著混合近距離的戳刺，以及偶一為之的破盾來擊敗他們。', `FemaleText_loc7`='Los jinetes de Sen''jin cuentan con su agilidad y destreza a distancia.$b$bSon suficientemente rápidos y esquivos para evitar tu Cargar, así que intenta emplear una mezcla de Estocada y algún ocasional Romper escudo para derrotarlos.' WHERE `ID`=34385;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='썬더 블러프 기수들은 특히 근접 전투에서 위력을 발휘하는 굳세고 강력한 전사들이랍니다.$B$B당신의 방어를 압도하는 그들의 찌르기 기술에 당하지 않도록, 사정거리 밖을 맴도세요. 돌진을 사용하기 전에는 먼저 방패 부수기로 상대의 방어를 무너뜨리시고요.', `MaleText_loc4`='雷霆崖的骑兵是魁梧而强壮的战士，近身战时能爆发出可怕的威力。$B$B他们的刺击势如破竹，你要尽量拉远彼此的距离，并在发起冲锋前使用碎盾打破他们的防御。', `MaleText_loc5`='雷霆崖騎士是巨大而強壯的戰士，在近距離時非常恐怖。$B$B試著遠離他們足以粉碎防禦的戳刺攻擊，盡量用破盾破壞他們的防禦然後冒險對他們使用衝鋒。', `MaleText_loc7`='Los jinetes de Cima del Trueno son unos combatientes enormes y poderosos, terribles cuerpo a cuerpo.$b$bIntenta mantenerte fuera del alcance de su devastadora Estocada, y destruye sus defensas con Romper escudo antes de arriesgarte a Cargar.', `FemaleText_loc1`='썬더 블러프 기수들은 특히 근접 전투에서 위력을 발휘하는 굳세고 강력한 전사들이랍니다.$B$B당신의 방어를 압도하는 그들의 찌르기 기술에 당하지 않도록, 사정거리 밖을 맴도세요. 돌진을 사용하기 전에는 먼저 방패 부수기로 상대의 방어를 무너뜨리시고요.', `FemaleText_loc4`='雷霆崖的骑兵是魁梧而强壮的战士，近身战时能爆发出可怕的威力。$B$B他们的刺击势如破竹，你要尽量拉远彼此的距离，并在发起冲锋前使用碎盾打破他们的防御。', `FemaleText_loc5`='雷霆崖騎士是巨大而強壯的戰士，在近距離時非常恐怖。$B$B試著遠離他們足以粉碎防禦的戳刺攻擊，盡量用破盾破壞他們的防禦然後冒險對他們使用衝鋒。', `FemaleText_loc7`='Los jinetes de Cima del Trueno son unos combatientes enormes y poderosos, terribles cuerpo a cuerpo.$b$bIntenta mantenerte fuera del alcance de su devastadora Estocada, y destruye sus defensas con Romper escudo antes de arriesgarte a Cargar.' WHERE `ID`=34386;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실버문 기수들은 균형과 정밀함, 공격과 방어의 절묘한 조합을 신조로 한답니다.$B$B하지만 그들은 당신을 상대로 거리를 잡느라 종종 돌진 기술에 노출될 거예요.$B$B당신이 당하기 전에 먼저 돌진해서 거리를 좁히시고, 찌르기를 위해 방향을 바꾸면서 방패 부수기를 사용하세요.', `MaleText_loc4`='银月城的骑兵将攻击和防御巧妙地结合起来，在作战中实现平衡与精准。$B$B但是，由于他们需要时刻与你保持距离，因此你可以伺机冲锋。$B$B你必须抢在他们之前发起冲锋，拉近彼此的距离，接下来在围绕他们跑动的过程中使用碎盾并看准机会使用刺击。', `MaleText_loc5`='銀月城騎士以平衡與精確為信條，靈巧而熟練地交替攻擊與防禦。$B$B但是當他們想要拉開距離的時候，往往也會讓自己暴露在衝鋒的危險下。$B$B在他們來得及反應前，用衝鋒縮短距離，然後對他們使用破盾然後搭配更多的戳刺。', `MaleText_loc7`='Los jinetes de Lunargenta creen en el equilibrio y en la precisión, y combinan con destreza el ataque y la defensa.$b$bSin embargo, a menudo se expondrán a una carga al intentar tomar distancia contigo.$b$bReduce esa distancia empleando Cargar antes de que ellos hagan lo mismo, y después emplea Romper escudo mientras te das la vuelta para utilizar Estocada de nuevo.', `FemaleText_loc1`='실버문 기수들은 균형과 정밀함, 공격과 방어의 절묘한 조합을 신조로 한답니다.$B$B하지만 그들은 당신을 상대로 거리를 잡느라 종종 돌진 기술에 노출될 거예요.$B$B당신이 당하기 전에 먼저 돌진해서 거리를 좁히시고, 찌르기를 위해 방향을 바꾸면서 방패 부수기를 사용하세요.', `FemaleText_loc4`='银月城的骑兵将攻击和防御巧妙地结合起来，在作战中实现平衡与精准。$B$B但是，由于他们需要时刻与你保持距离，因此你可以伺机冲锋。$B$B你必须抢在他们之前发起冲锋，拉近彼此的距离，接下来在围绕他们跑动的过程中使用碎盾并看准机会使用刺击。', `FemaleText_loc5`='銀月城騎士以平衡與精確為信條，靈巧而熟練地交替攻擊與防禦。$B$B但是當他們想要拉開距離的時候，往往也會讓自己暴露在衝鋒的危險下。$B$B在他們來得及反應前，用衝鋒縮短距離，然後對他們使用破盾然後搭配更多的戳刺。', `FemaleText_loc7`='Los jinetes de Lunargenta creen en el equilibrio y en la precisión, y combinan con destreza el ataque y la defensa.$b$bSin embargo, a menudo se expondrán a una carga al intentar tomar distancia contigo.$b$bReduce esa distancia empleando Cargar antes de que ellos hagan lo mismo, y después emplea Romper escudo mientras te das la vuelta para utilizar Estocada de nuevo.' WHERE `ID`=34387;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언더시티 기수들은 불굴의 용사랍니다. 방어에 중점을 두면서, 맞으면 되받아치는 식으로 상대와 꼬박꼬박 공격을 주고받지요.$B$B당신의 방어를 단단히 유지하면서 돌진 기술로 그들이 지치게 하세요... 방어에서 우위를 점하고 있을 때 맞붙어서, 공격을 주고받을 때마다 그들이 더 큰 타격을 입게 하세요.', `MaleText_loc4`='幽暗城的骑兵是一群坚韧的勇士，他们擅长防御与持久作战。$B$B你应该在维持自身防御的前提下使用冲锋把他们累得趴下……只要你能保持防御优势，他们就会在对战中承受较大的伤害。', `MaleText_loc5`='幽暗城騎士相當的頑強，他們的防禦堅強並且持續不斷地以一拳換一拳的方式，攻擊他們的敵手。$B$B試著靠衝鋒把他們打下馬，並且同時維持你自己防禦...盡可能讓他們處於防禦弱勢，這樣他們每次交換攻擊時才會受到更大的損失。', `MaleText_loc7`='Los jinetes de Entrañas son gente tenaz que confía mucho en su defensa y que intercambia golpes constantemente con sus oponentes.$b$bIntenta debilitarlos empleando Cargar mientras empleas Defender... Enfréntate a ellos con una ventaja defensiva de modo que reciban más daño que tú en cada intercambio.', `FemaleText_loc1`='언더시티 기수들은 불굴의 용사랍니다. 방어에 중점을 두면서, 맞으면 되받아치는 식으로 상대와 꼬박꼬박 공격을 주고받지요.$B$B당신의 방어를 단단히 유지하면서 돌진 기술로 그들이 지치게 하세요... 방어에서 우위를 점하고 있을 때 맞붙어서, 공격을 주고받을 때마다 그들이 더 큰 타격을 입게 하세요.', `FemaleText_loc4`='幽暗城的骑兵是一群坚韧的勇士，他们擅长防御与持久作战。$B$B你应该在维持自身防御的前提下使用冲锋把他们累得趴下……只要你能保持防御优势，他们就会在对战中承受较大的伤害。', `FemaleText_loc5`='幽暗城騎士相當的頑強，他們的防禦堅強並且持續不斷地以一拳換一拳的方式，攻擊他們的敵手。$B$B試著靠衝鋒把他們打下馬，並且同時維持你自己防禦...盡可能讓他們處於防禦弱勢，這樣他們每次交換攻擊時才會受到更大的損失。', `FemaleText_loc7`='Los jinetes de Entrañas son gente tenaz que confía mucho en su defensa y que intercambia golpes constantemente con sus oponentes.$b$bIntenta debilitarlos empleando Cargar mientras empleas Defender... Enfréntate a ellos con una ventaja defensiva de modo que reciban más daño que tú en cada intercambio.' WHERE `ID`=34388;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오그리마 기수들은 대담하고도 압도적인 돌진 기술을 자랑한답니다. 어찌나 실력이 좋고 사나운지, 돌진을 맞는 즉시 상대에게 역으로 돌진하지요.$B$B거리를 좁히고 찌르기를 노리세요. 그들이 당신과 거리를 두려고 하면, 먼저 방패 부수기로 균형 흔들기를 한 다음에 돌진하세요. 그러지 않으면 항상 그들과 맞부딪치고 말 거예요.', `MaleText_loc4`='奥格瑞玛的骑兵以其无畏而极具破坏性的冲锋为傲。即便是被对方冲锋，他们也能立即以牙还牙，这就是奥格瑞玛骑兵的可怕之处了。$B$B你要尽可能地打近身战并使用刺击，当他们试图拉开距离时，先利用碎盾令他们失去平衡，然后使用冲锋。否则，他们会不断地向你发动正面攻击。', `MaleText_loc5`='奧格瑪騎士以他們的無畏與破壞力極大的衝鋒而自豪。靠著他們的技巧與兇猛天性，他們在遭遇衝鋒時甚至會也跟著反衝鋒回去。$B$B試著貼近他們並利用戳刺，當他們想拉開距離時，先用破盾令其失去平衡，接著再使用衝鋒。否則，他們每次都會給你迎頭痛擊。', `MaleText_loc7`='Los jinetes de Orgrimmar se enorgullecen de sus temerarias y devastadoras cargas. Es tanta su habilidad y ferocidad que, cuando reciben una carga, sencillamente la devuelven.$b$bIntenta mantenerte cerca de ellos y emplear Estocada, y cuando intenten tomar distancia, ponlos en desventaja empleando Romper escudo antes de Cargar. Si no, se abalanzarán sobre ti todo el rato.', `FemaleText_loc1`='오그리마 기수들은 대담하고도 압도적인 돌진 기술을 자랑한답니다. 어찌나 실력이 좋고 사나운지, 돌진을 맞는 즉시 상대에게 역으로 돌진하지요.$B$B거리를 좁히고 찌르기를 노리세요. 그들이 당신과 거리를 두려고 하면, 먼저 방패 부수기로 균형 흔들기를 한 다음에 돌진하세요. 그러지 않으면 항상 그들과 맞부딪치고 말 거예요.', `FemaleText_loc4`='奥格瑞玛的骑兵以其无畏而极具破坏性的冲锋为傲。即便是被对方冲锋，他们也能立即以牙还牙，这就是奥格瑞玛骑兵的可怕之处了。$B$B你要尽可能地打近身战并使用刺击，当他们试图拉开距离时，先利用碎盾令他们失去平衡，然后使用冲锋。否则，他们会不断地向你发动正面攻击。', `FemaleText_loc5`='奧格瑪騎士以他們的無畏與破壞力極大的衝鋒而自豪。靠著他們的技巧與兇猛天性，他們在遭遇衝鋒時甚至會也跟著反衝鋒回去。$B$B試著貼近他們並利用戳刺，當他們想拉開距離時，先用破盾令其失去平衡，接著再使用衝鋒。否則，他們每次都會給你迎頭痛擊。', `FemaleText_loc7`='Los jinetes de Orgrimmar se enorgullecen de sus temerarias y devastadoras cargas. Es tanta su habilidad y ferocidad que, cuando reciben una carga, sencillamente la devuelven.$b$bIntenta mantenerte cerca de ellos y emplear Estocada, y cuando intenten tomar distancia, ponlos en desventaja empleando Romper escudo antes de Cargar. Si no, se abalanzarán sobre ti todo el rato.' WHERE `ID`=34389;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멀록 잔챙이들, 너희 보물을 훔치러 내가 왔다! 나를 막아 봐라! 어서!', `MaleText_loc4`='鱼人害虫，我要偷走你们的宝物！来阻止我吧！快一点！', `MaleText_loc5`='魚人害蟲，我來這竊取你們的寶物了!試著阻止我!快啊!', `MaleText_loc7`='¡Molestos múrlocs, he venido a robar su tesoro! ¡Intenten detenerme! ¡Rápido!' WHERE `ID`=34390;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭발 직전.', `MaleText_loc4`='即将爆炸。', `MaleText_loc5`='即將爆炸。', `MaleText_loc7`='Detonación inminente.' WHERE `ID`=34391;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성스러운 빛이 주관하시는 작은 예배당에 오신 걸 환영합니다. 자리를 잡으시고 세상의 죄악으로부터의 휴식을 누리세요.', `MaleText_loc4`='欢迎来到这座圣光礼拜堂。请坐。愿你暂时远离痛苦的尘世，享受片刻的宁静。', `MaleText_loc5`='歡迎來到我們屬於聖光的小禮拜堂。歡迎，請坐。享受這不受世界邪惡影響的短暫時光吧。', `MaleText_loc7`='Bienvenid$go:a; a nuestra pequeña capilla de la Luz. Por favor, toma asiento. Disfruta de un descanso de los males del mundo.', `FemaleText_loc1`='성스러운 빛이 주관하시는 작은 예배당에 오신 걸 환영합니다. 자리를 잡으시고 세상의 죄악으로부터의 휴식을 누리세요.', `FemaleText_loc4`='欢迎来到这座圣光礼拜堂。请坐。愿你暂时远离痛苦的尘世，享受片刻的宁静。', `FemaleText_loc5`='歡迎來到我們屬於聖光的小禮拜堂。歡迎，請坐。享受這不受世界邪惡影響的短暫時光吧。', `FemaleText_loc7`='Bienvenid$go:a; a nuestra pequeña capilla de la Luz. Por favor, toma asiento. Disfruta de un descanso de los males del mundo.' WHERE `ID`=34392;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 시작하자고.$b$b시간은 없고 할 일은 많으니까 말이네.', `MaleText_loc4`='让我们开始吧，$r。$b$b我们的时间不多了，但还有很多事要做。', `MaleText_loc5`='我們快開始吧，$r。$b$b時間很少事情卻很多。', `MaleText_loc7`='Pongámonos a ello, $r.$B$BTenemos poco tiempo y mucho que hacer.' WHERE `ID`=34394;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 오늘 우리 기수 중 한 명을 능가했으니, 난 당신의 도전을 받아들일 수 없다.', `MaleText_loc4`='今天你已经战胜了一位骑兵，我不能再接受你的挑战了。', `MaleText_loc5`='你今天已經擊敗了我們其中的一位騎士，因此我無法接受你的挑戰。', `MaleText_loc7`='Hoy ya has derrotado a uno de nuestros jinetes, así que no puedo aceptar tu desafío.', `FemaleText_loc1`='당신은 오늘 우리 기수 중 한 명을 능가했으니, 난 당신의 도전을 받아들일 수 없다.', `FemaleText_loc4`='今天你已经战胜了一位骑兵，我不能再接受你的挑战了。', `FemaleText_loc5`='你今天已經擊敗了我們其中的一位騎士，因此我無法接受你的挑戰。', `FemaleText_loc7`='Hoy ya has derrotado a uno de nuestros jinetes, así que no puedo aceptar tu desafío.' WHERE `ID`=34395;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음번에는 신호 가루를 화로에 더 넣고 싶어질 것이네. 오그리마에서 이 신호가 보이는지 확실히 모르겠으니까...', `MaleText_loc4`='下一次，你也许要在火盆里放上更多的信号火药。我不知道他们从奥格瑞玛能不能看见这里的信号……', `MaleText_loc5`='你下次應該要在火盆裡多放點信號粉末。我很懷疑他們在奧格瑪是否能看到...', `MaleText_loc7`='Quizá la próxima vez quieras poner más polvos de santo y seña en el fuego. No creo que hayan podido ver eso desde Orgrimmar...' WHERE `ID`=34396;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가방 안에 든 걸 한 번에 다 써버릴 필요는 없지 않았나, 안 그래?', `MaleText_loc4`='你不需要一次用光一口袋吧，是不是？', `MaleText_loc5`='你也不需要一次就把整袋用光吧!', `MaleText_loc7`='No tenías que usar todo el saco de golpe, ¿no?' WHERE `ID`=34397;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 일이 끝나고 나면 아마도 자네의 은신 기술을 다시 익히고 싶어질 걸세...', `MaleText_loc4`='当这里的事情结束时，你也许要磨砺一下你的秘密技巧……', `MaleText_loc5`='當這結束後，你應該要惡補一下你的隱密能力...', `MaleText_loc7`='Cuando esto acabe, quizá quieras refrescar tus habilidades para hacer las cosas en secreto...' WHERE `ID`=34398;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 진동의 포효를 내지르려 합니다!', `MaleText_loc4`='%s准备高声咆哮！', `MaleText_loc5`='%s準備釋出驚人的怒吼!', `MaleText_loc7`='¡El %s se prepara soltar un grito aturdidor!' WHERE `ID`=34399;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고해사제님의 설교를 들으러 오신 건가요? 음... 앉을 자리를 찾으실 수 있길 바랄게요.', `MaleText_loc4`='你是来听神官布道的吗？但愿你还能找到座位……', `MaleText_loc5`='你也是來這裡聽告解者的佈道嗎?祝你能找到地方坐...', `MaleText_loc7`='¿Estás aquí por el sermón de la confesora? Suerte encontrando asiento...' WHERE `ID`=34400;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수호자의 고대 관문이 열립니다!', `MaleText_loc4`='守护者的远古之门开启了！', `MaleText_loc5`='守衛者的上古之門已經打開了!', `MaleText_loc7`='¡La Puerta Antigua de los Guardianes se abre!' WHERE `ID`=34401;
