UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무언가 질질 끌리는 소리가 들리지만, 아무것도 보이지 않습니다.', `MaleText_loc4`='你听到身边传来一阵细碎的声音，却什么都没有看见。', `MaleText_loc5`='你聽到附近發出了稀疏的雜音，但沒看到任何東西。', `MaleText_loc7`='Escuchas un ruido como de movimiento, pero no ves nada.', `FemaleText_loc1`='무언가 질질 끌리는 소리가 들리지만, 아무것도 보이지 않습니다.', `FemaleText_loc4`='你听到身边传来一阵细碎的声音，却什么都没有看见。', `FemaleText_loc5`='你聽到附近發出了稀疏的雜音，但沒看到任何東西。', `FemaleText_loc7`='Escuchas un ruido como de movimiento, pero no ves nada.' WHERE `ID`=34413;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시선이 미치는 곳 밖에서 사람 모습을 한 그림자를 본 것 같은 느낌이 듭니다.', `MaleText_loc4`='你从眼角瞥到一个影子。', `MaleText_loc5`='你認為你的眼角瞄到了一個黑色的影子。', `MaleText_loc7`='Crees ver una sombría silueta por el rabillo del ojo.', `FemaleText_loc1`='시선이 미치는 곳 밖에서 사람 모습을 한 그림자를 본 것 같은 느낌이 듭니다.', `FemaleText_loc4`='你从眼角瞥到一个影子。', `FemaleText_loc5`='你認為你的眼角瞄到了一個黑色的影子。', `FemaleText_loc7`='Crees ver una sombría silueta por el rabillo del ojo.' WHERE `ID`=34414;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼도레이 암살자가 어둠 속에서 뛰어나와 $n|1을;를; 공격합니다!', `MaleText_loc4`='一名卡多雷刺客从阴影中跳出来，向$n发动了攻击！', `MaleText_loc5`='卡多雷的暗殺者從暗影中跳起攻擊$n!', `MaleText_loc7`='¡Un asesino kaldorei surge de las sombras y ataca a $n!', `FemaleText_loc1`='칼도레이 암살자가 어둠 속에서 뛰어나와 $n|1을;를; 공격합니다!', `FemaleText_loc4`='一名卡多雷刺客从阴影中跳出来，向$n发动了攻击！', `FemaleText_loc5`='卡多雷的暗殺者從暗影中跳起攻擊$n!', `FemaleText_loc7`='¡Un asesino kaldorei surge de las sombras y ataca a $n!' WHERE `ID`=34415;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님.$b$b주인님을 지켜드리지 못했습니다. 어떻게 제가 실버문으로 돌아갈 수 있겠습니까...', `MaleText_loc4`='我的女士。$b$b我没有能保护她。我又怎么能回到银月城……', `MaleText_loc5`='我的女士。$b$b我沒有能力保護她。我怎麼有臉回到銀月城...', `MaleText_loc7`='Mi señora.$b$bNo pude protegerla. ¿Cómo puedo regresar a Lunargenta...?' WHERE `ID`=34416;
