UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보조 방어 시스템을 활성화하면 권한 없는 생명체는 궤도적 방어 장치를 통해 모두 제거될 것입니다.$B$B당신은 권한 없는 생명체입니다. 확인해 주십시오.', `MaleText_loc4`='激活辅助防御系统后，轨道炮台将消灭所有未经认证的生命体。$B$B你属于未经认证的生命体。请确认。', `MaleText_loc5`='啟動次要防禦系統將會讓環軌砲塔消滅所有未經授權的生命形態。$B$B你是未經授權的生命形態。請確認。', `MaleText_loc7`='Activar los sistemas defensivos secundarios provocará el exterminio de formas de vida no autorizadas mediante mecanismos orbitales.$b$bEres una forma de vida no autorizada. Confirmación, por favor.' WHERE `ID`=34419;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보조 방어 시스템을 활성화해 주십시오.', `MaleText_loc4`='激活辅助防御系统。', `MaleText_loc5`='啟動次要防禦系統。', `MaleText_loc7`='Activad sistemas de defensa secundarios.', `FemaleText_loc1`='보조 방어 시스템을 활성화해 주세요.', `FemaleText_loc4`='激活辅助防御系统。', `FemaleText_loc5`='啟動次要防禦系統。', `FemaleText_loc7`='Activad sistemas de defensa secundarios.' WHERE `ID`=34420;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='확인했습니다.', `MaleText_loc4`='已确认。', `MaleText_loc5`='確認。', `MaleText_loc7`='Confirmado.', `FemaleText_loc1`='확인했습니다.', `FemaleText_loc4`='已确认。', `FemaleText_loc5`='確認。', `FemaleText_loc7`='Confirmado.' WHERE `ID`=34421;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보안 재정의가 허가되었습니다. 보조 방어 시스템이 활성화되었습니다.$B$B광장에 있는 각 발전기에 직접 접속함으로써 보조 시스템을 비활성화할 수 있습니다.', `MaleText_loc4`='允许安全控制。辅助防御系统已激活。$B$B可以通过广场上的独立能源塔关闭这些辅助系统。', `MaleText_loc5`='允許安全系統手控。啟動次要防禦系統。$B$B備用系統關閉，次要系統可以經由集合場的獨立動力裝置獲得能量。', `MaleText_loc7`='Permitido control manual de seguridad. Sistemas defensivos secundarios activados.$b$bPuede accederse a la desactivación de emergencia de los sistemas secundarios mediante generadores individuales ubicados en la explanada.' WHERE `ID`=34422;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번 마상시합에서 은빛십자군을 대표하게 된 건 영광이 아닐 수 없습니다.', `MaleText_loc4`='能在锦标赛中代表银色北伐军出场真是无上的荣耀。', `MaleText_loc5`='能代表銀白十字軍參加聯賽真是非常光榮。', `MaleText_loc7`='Es un honor representar a la Cruzada Argenta en este torneo.' WHERE `ID`=34423;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='단지 내부 접근은 현재 제한되어 있습니다. 주 방어 설비와 보조 방어 설비가 작동 중입니다.', `MaleText_loc4`='禁止进入泰坦之城。主要防御系统与辅助防御系统均已激活。', `MaleText_loc5`='目前禁止進入複合體內部。主要與次要防禦裝置均已啟動。', `MaleText_loc7`='En estos momentos el acceso al interior del complejo está restringido. Los mecanismos de defensa primarios y secundarios están activos.' WHERE `ID`=34424;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='희한하군요. 지난번엔 그 궤도적 방어 설비에 대해선 언급하지 않았던 것 같은데. 어떤 얼뜨기가 그걸 활성화했는지 궁금하네요.', `FemaleText_loc4`='奇怪，我记得上次根本没提到什么轨道炮台啊。是哪个蠢货把它们给激活的？', `FemaleText_loc5`='奇怪了，我並不記得上次有提到這些環軌裝置。到底是那個傻瓜啟動它們。', `FemaleText_loc7`='Qué raro, no recuerdo ninguna mención a esos mecanismo orbitales la última vez. Me pregunto qué memo los habrá activado.' WHERE `ID`=34425;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은빛십자군 마상시합이 얼음왕관의 북쪽 구역에서 시작되었습니다, $c님. 아직 그곳으로 갈 방법을 찾으신다면, 제가 알아봐 드릴 수 있답니다.$B$B우리가 마상전에 더 참여할수록, 리치 왕에 대항해 공격을 가할 때 더 강해질 겁니다.', `MaleText_loc4`='银色锦标赛在冰冠冰川的北部边界拉开了帷幕，$c。如果你不知道怎么去哪儿，我可以免费送你一程。$B$B我们积累的作战经验越多，在面对巫妖王时胜算也就更大。', `MaleText_loc5`='銀白聯賽在寒冰皇冠的北境展開，$c。如果你還不知道怎麼去那裡，我可以送你一程。$B$B我們越多人參加技擊大賽，我們對抗巫妖王的力量就會越強。', `MaleText_loc7`='El Torneo Argenta ha empezado en el extremo norte de Corona de Hielo, $c. Si todavía has de encontrar el camino al lugar, puedo pagarte el viaje.$b$bCuantos más participantes tengamos en el combate cuerpo a cuerpo, más fuertes seremos cuando ataquemos al Rey Exánime.' WHERE `ID`=34426;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리로 보내주십시오.', `MaleText_loc4`='我要飞过去。', `MaleText_loc5`='帶我飛過去吧。', `MaleText_loc7`='Tomaré el vuelo.', `FemaleText_loc1`='그리로 보내주세요.', `FemaleText_loc4`='我要飞过去。', `FemaleText_loc5`='帶我飛過去吧。', `FemaleText_loc7`='Tomaré el vuelo.' WHERE `ID`=34427;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='유후! 쏘세요!', `MaleText_loc4`='耶！来吧！', `MaleText_loc5`='呀哈!就這麼幹!', `MaleText_loc7`='¡Yuju! ¡Hagámoslo!', `FemaleText_loc1`='유후! 쏘세요!', `FemaleText_loc4`='耶！来吧！', `FemaleText_loc5`='呀哈!就這麼幹!', `FemaleText_loc7`='¡Yuju! ¡Hagámoslo!' WHERE `ID`=34428;
