UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 쓰레기한테 진정한 용자의 모습을 보여 줍시다.', `MaleText_loc4`='让这个小废物看看，什么是真正的勇气。', `MaleText_loc5`='讓那些廢料瞧瞧什麼才是真正的勇氣和毅力。', `MaleText_loc7`='Mostremos a este montón de chatarra qué es el auténtico coraje.', `FemaleText_loc1`='저 쓰레기한테 진정한 용자의 모습을 보여 줍시다.', `FemaleText_loc4`='让这个小废物看看，什么是真正的勇气。', `FemaleText_loc5`='讓那些廢料瞧瞧什麼才是真正的勇氣和毅力。', `FemaleText_loc7`='Mostremos a este montón de chatarra qué es el auténtico coraje.' WHERE `ID`=34430;
