UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='열심히 하란 말이야. 땀을 흘리지 않는 놈은 피를 흘리게 해주겠다.', `FemaleText_loc4`='我要看到些汗水。如果我还看不到汗水，我保证，我一定能看到鲜血。', `FemaleText_loc5`='我要看到汗流下來。如果我看不到汗，我保證流出來的便會是鮮血。', `FemaleText_loc7`='Quiero ver algo de sudor, ¿me oyes? Si no empiezo a ver sudor, te juro que empezaré a ver sangre.' WHERE `ID`=34443;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='더 빨리 일하란 말이다! 일꾼놈들아!... 내가 이 막대기를 쓰지 않도록 하는 게 좋을 거야.', `FemaleText_loc4`='加快脚步，苦力！……不要让我抽打你们。', `FemaleText_loc5`='加緊工作，你們這些苦工!...別逼我使用棒子。', `FemaleText_loc7`='¡Subid el ritmo, peones! ...No me hagáis sacar el bastón.' WHERE `ID`=34444;
