UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='헉... 방금 대체 무슨 짓을 한 거죠, $n 님?! 브란! 브라아아아안!', `FemaleText_loc4`='你……你刚做了什么，$n？！布莱恩！布——莱——恩——！', `FemaleText_loc5`='什麼...你剛剛做了什麼，$n?布萊恩!布萊恩恩恩恩!', `FemaleText_loc7`='¡¿Qué... Qué has hecho, $n?! ¡Brann! ¡Braaaaaannnn!' WHERE `ID`=34446;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='브란! $n|1이;가; 방금 궤도적 방어 시스템을 활성화했어요! 빨리 여기서 빠져나가지 않으면 우린 끝장날 거예요!', `FemaleText_loc4`='布莱恩！$n激活了轨道防御系统！我们必须立即离开这里，不然会被烤熟的！', `FemaleText_loc5`='布萊恩!$n剛剛啟動了環軌防禦系統!如果我們不馬上離開這裡，我們就等著變烤雞吧!', `FemaleText_loc7`='¡Brann! ¡$n acaba de activar el sistema de defensa orbital! ¡Si no nos largamos pronto de aquí, estamos fritos!' WHERE `ID`=34447;
