UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저 사악한 트롤들이 영원히 평화롭게 지낼 거란 기대를 해서는 안 되는 거였습니다. 호드와 동조하는 자들은 믿을 수 없습니다.', `FemaleText_loc4`='我不应该期待这些肮脏的巨魔永远地安于和平。同情部落者绝不能信任。', `FemaleText_loc5`='我不該期待這些骯髒的食人妖會一直安靜下去。對於可以接受部落的人不該抱有任何的信任。', `FemaleText_loc7`='No debería haber esperado que estos repugnantes trols mantuvieran la paz indefinidamente. No hay lugar para la confianza con los simpatizantes de la Horda.' WHERE `ID`=34464;
