UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피와 번개의 축복을!', `MaleText_loc4`='鲜血与雷鸣,$n!', `MaleText_loc5`='鮮血與雷霆，$n!', `MaleText_loc7`='¡Sangre y truenos, $n!' WHERE `ID`=34467;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 자폭합니다!', `MaleText_loc4`='%s开始自毁！', `MaleText_loc5`='%s開始自我毀滅!', `MaleText_loc7`='¡El %s empieza a autodestruirse!' WHERE `ID`=34468;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리에겐 직면한 위험은 많습니다만, 필요한 때에 자연이 우리를 도외시하지 않도록, 우리도 자연을 도외시하면 안 됩니다. 우린 예전에 이런 교훈을 배웠지요.', `MaleText_loc4`='我们要面对许多危险，但我们不能因此而忽视自然。这样的话，自然将会在我们有所需要时舍我们而去。我们曾经有过这样的教训。', `MaleText_loc5`='許多危機正等著我們，但我們絕不能忽略大自然，避免我們在需要它的時候拋棄我們。這是我們從過去的經驗中所學習到的。', `MaleText_loc7`='Nos enfrentamos a muchos peligros, pero no podemos descuidar la naturaleza o nos descuidará a nosotros en tiempos de necesidad. Ya hemos aprendido esta lección antes.' WHERE `ID`=34469;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자연을 훼손하는 건 이단이다. 자연의 힘이 파괴적일 때라 할지라도 말이야.$B$B어둠해안을 파괴한 힘은 자연적인 게 아니다. 난 이 땅이 산산이 흩어지도록 두지 않을 것이다.', `MaleText_loc4`='阻挡自然者即是异端，即便在自然发挥它破坏之力时亦然如此。$B$B但如今要摧毁黑海岸的并非自然的力量。我不会让这片土地分崩离析。', `MaleText_loc5`='跟自然唱反調是一種異論，就算自然所帶來的是毀滅的力量也是一樣。$B$B不過，想要摧毀黑海岸的力量不是自然之力。我絕不允許這片大地被撕裂。', `MaleText_loc7`='Interponerse en el camino de la naturaleza es herejía. Incluso cuando la fuerza de la naturaleza es destructiva.$B$BPero las fuerzas que buscan destruir Costa Oscura no son naturales. No permitiré que destruyan esta tierra.' WHERE `ID`=34470;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이그니스가 내뿜은 불길이 물에 꺼집니다!', `MaleText_loc4`='灼烧被水熄灭了！', `MaleText_loc5`='灼燒被水所澆熄!', `MaleText_loc7`='¡El agua extingue las brasas!' WHERE `ID`=34471;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요? 전 게리라고 합니다. 골볼트가 당신을 보낸거겠지요?

도와주러 이곳으로 오신 거라면, 계획은 아주 단순해요. 제가 유인 로봇을 급하게 만들었는데요. 멀록 근처에 그 작은 친구들을 풀어놓고 초읽기를 활성화해 놓았어요. 그 로봇들은 빛과 소리를 내면서 멀록들을 끌어들일 거예요. 그러고는 몇 초 지난 다음에 멀록들을 쓰러뜨리며 폭발할 거예요.

이곳에 유인 로봇이 충분히 있다면, 다시 배를 우리 손에 넣을 수 있을 거예요. 그 부분은 당신 일은 아니에요. 당신은 그냥 저 물고기 인간들이나 날려 버리세요!', `MaleText_loc4`='你好啊，我是盖瑞。相信一定是高尔博德派你来的。

如果你要来帮忙，那么你要做的事情相当简单。我装配了一些诱饵机器人。我们可以把它们放在鱼人附近，然后开启它们的倒数计时系统。它们会闪动光芒，发出声音，引诱那些鱼人过来。几秒钟之后，它们就会爆炸，把那些鱼人一并炸飞。

如果我们在那里放置足够多的诱饵机器人，我们就应该能再次进入船舱。希望这次我们的人员伤亡会少一些。当然，进入船舱的任务和你没有关系。先去炸飞那些小鱼人吧！', `MaleText_loc5`='你好嗎?我是葛瑞，一定是高爾博多叫你來的吧。

如果你是來幫忙的，計畫很簡單。我做了一些誘餌機器人。我們讓這些小東西跳到魚人附近，然後啟動它們的倒數計時。它們會發出亮光和聲音來吸引魚人，幾秒鐘後便會爆炸和那些魚人一起升天。

如果我們送了夠多個進去，我們應該就可以再次進到船艙裡。希望這次的傷亡會少一點，但這跟你沒關係，你只要把那些小魚人炸飛就好了!', `MaleText_loc7`='¿Qué tal estás? Soy Gary. Supongo que te ha enviado Gorbold.

Si has venido para ayudar, el plan es muy simple. He construido algunos bots señuelo. Soltamos a estos pequeños amigos cerca de los múrlocs y tras unos pocos segundos, explotarán llevándose a los múrlocs con ellos.

Si conseguimos infiltrar los suficientes, podríamos abrirnos camino hasta las bodegas de los barcos de nuevo. Aunque esta vez, con menos bajas. Pero esto no es tarea tuya. ¡Tú dedícate a machacar a esos pequeños hombres pez!' WHERE `ID`=34472;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정령들이 어둠해안을 산산조각내려고 온 힘을 다하는 가운데, 전 남은 야생 동물들을 보호하려고 싸우고 있어요.$B$B그대가 도와주리라 믿어도 될까요, $c?', `FemaleText_loc4`='当那些元素拼命要扯碎黑海岸的时候，我竭尽全力想要保护住剩下的自然生命。$B$B$c，我能得到你的帮助吗？', `FemaleText_loc5`='當元素盡力的在摧毀黑海岸時，我很努力的在保護剩下的野生動植物。$B$B我能夠信任你嗎，$c?', `FemaleText_loc7`='Mientras los elementos se esfuerzan por destruir Costa Oscura, hago lo que puedo por proteger la vida salvaje que queda.$b$b¿Cuento con tu ayuda, $c?' WHERE `ID`=34473;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도전이라고?! 이 땅에 네 시체를 폭발시켜 줄 테니 그대로 서 있어라.', `MaleText_loc4`='挑战？！站直了，看我把你轰成渣。', `MaleText_loc5`='一個挑戰?!站穩了你，這樣我才能把你的轟的四分五裂。', `MaleText_loc7`='¿Un reto? No te muevas para que pueda esparcir tu cadáver por todas partes.' WHERE `ID`=34474;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈이 로렌스 썬더콜 보다 더 잘할 수 있다고 생각하나? 멍청한 놈, 거기 가만 있어라. 내가 하늘 높이 날려줄 테니.', `MaleText_loc4`='你以为你能打败洛伦瑟·唤雷吗？站稳了，蠢货，看我把你拍死。', `MaleText_loc5`='你認為你可以擊敗羅倫斯·喚雷?站好，你這愚蠢的蟲子，讓我可以把你打飛。', `MaleText_loc7`='¿Crees que puedes vencer a Lorenth Invocatruenos? Quédate ahí, pulga estúpida, para que pueda aplastarte.' WHERE `ID`=34475;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조그만 여행자 녀석, 그대로 있어라. 네가 원하던 죽음을 안겨 주마.', `MaleText_loc4`='不要乱动，小冒险者。我这里有你正在寻找的死亡。', `MaleText_loc5`='別動，弱小的探險者。我可以給你你想要的死亡。', `MaleText_loc7`='Aquí es donde terminan tus aventuras. Yo tengo la muerte que buscas.' WHERE `ID`=34476;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 이 마법을 시전할 테니 거기 그대로 있어라! 그리 아프지 않을 게다.', `MaleText_loc4`='哈！在我施放这个法术的时候站在这里！不会很痛的。', `MaleText_loc5`='哈!在那站好，我要唱法術了!不會很痛的。', `MaleText_loc7`='¡Ja! ¡Quédate ahí mientras lanzo este hechizo! No te dolerá mucho.' WHERE `ID`=34477;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 녀석들! 거기 그대로 있으면 내가 열렬히 환영해 주지.', `FemaleText_loc4`='嗨！别躲起来，可爱的家伙，让我好好地欢迎你。', `FemaleText_loc5`='有人來了!別離開我的視線，甜心，這樣我才能好好的歡迎你。', `FemaleText_loc7`='¡Compañía! Quédate a la vista, cariño, para que pueda darte la bienvenida como es debido.' WHERE `ID`=34478;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='먹잇감들아! 그 기둥에서 떨어져라. 너희가 침입하면서 생긴 실수가 무엇인지 보여주겠다.', `FemaleText_loc4`='软蛋！离开那些柱子，我要让你知道，你所犯下的错误是多么严重。', `FemaleText_loc5`='獵物!別躲在那些柱子後面，讓我給你嘗嘗入侵者應得的教訓。', `FemaleText_loc7`='¡Presa! Aléjate de esas columnas para que te enseñe el error que has cometido con tu intrusión.' WHERE `ID`=34479;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어서 오너라! 부끄러워하지 말고... 네 모습을 잘 볼 수 있게 그 기둥에서 살짝 떨어져라.', `FemaleText_loc4`='欢迎！不要害羞……从那些柱子中走出来吧，这样我就能清楚地看到你了。', `FemaleText_loc5`='歡迎!別害羞...別讓那些柱子把你擋住，讓我好好看看你。', `FemaleText_loc7`='¡Hola! No temas... Aléjate de las columnas para que pueda verte bien.' WHERE `ID`=34480;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어서 와라! 그 기둥에서 한 발짝 떨어지지 못해? 내가 너희를 제대로 환영해 주지.', `FemaleText_loc4`='你好！不要不敢走出那些柱子。让我好好地欢迎你。', `FemaleText_loc5`='嗨!你最好不要給我躲到那些柱子後面。讓我給你來個盛大的歡迎。', `FemaleText_loc7`='¡Hola! Ni se te ocurra ocultarte tras esas columnas. Deja que te dé la bienvenida como es debido.' WHERE `ID`=34481;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 위에 있는 동안에는 저기 땅에 있는 트롤들 걱정은 하지 마시오. 고대 정령들의 발에 짓밟혀 버릴 테니까.', `MaleText_loc4`='不要担心脚下的那些巨魔。他们将被古树深深地踩进泥土之中。', `MaleText_loc5`='在上面時不必擔心那些礙事的食人妖，古樹的大腳會把他們給踩扁。', `MaleText_loc7`='Y no te preocupes de los trols a tus pies mientras estés allí arriba. Las zancadas de los ancestros los aplastarán.' WHERE `ID`=34482;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇게 가만히 서 있지만 말란 말이네...$b$b일은 끝내야 하잖아!', `MaleText_loc4`='不要这样傻站着，$r……$b$b还有很多工作要做呢！', `MaleText_loc5`='別只是站在那，$r...$b$b你還有活要幹!', `MaleText_loc7`='No te quedes ahí sin más, $r...$B$B¡Hay trabajo pendiente!' WHERE `ID`=34483;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='인식할 수 없는 얼굴에 나뭇가지와 촉수들이 모인 흉측한 모습을 한 생물체가 모래에 반쯤 묻혀 있습니다. 이 무시무시한 반투명 살덩이를 만질 수가 없습니다.$B$B이 괴수는 죽었지만, 물이 밀려왔다 빠지면서 형체 없는 몸이 깨끗해진 것 같습니다. 그리고 신기하게도 이 시체에는 부패의 징후 따윈 보이지 않습니다.', `MaleText_loc4`='一只怪物被半埋在这堆淤泥里，它由一堆恐怖的肢体、触须和无法辨识的面孔组成。你完全不想碰触这团半透明的怪诞血肉。$B$B虽然这只怪物已经死了。但奇怪的是，这具尸体周围的水面却丝毫没有受到污染的痕迹，尸体本身也没有任何腐烂的迹象。', `MaleText_loc5`='那有個生物被半埋在砂土中，由醜陋的四肢和觸手所組成，還有一張沒什麼特徵的臉。你不敢自己去摸這恐怖的半透明生物。$B$B這隻野獸雖然已經死了，但它無形身體周圍的水看起來卻很乾淨，屍體也令人驚訝的並沒有任何腐壞的跡象。', `MaleText_loc7`='Hay una criatura medio enterrada en el cieno, una espantosa mezcla de miembros y tentáculos en la que no se puede distinguir una cara. Es imposible tocar la espeluznante carne traslúcida. $B$BAunque la bestia está muerta, el agua que rodea el deforme cuerpo parece limpia y es curioso que el cadáver no muestre signos de descomposición.' WHERE `ID`=34484;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='작은 이여, 가만히 있으면 고대의 땅이 말하는 걸 들을 수 있다네. 고통으로 울부짖는 소리를 말이야.', `MaleText_loc4`='安静，小东西，这样你就能听到这片古老的土地在说话。它正在痛苦地呼号。', `MaleText_loc5`='靜下心來，小東西，你可以聽到這個古老大地所發出的聲音。它正因痛苦而悲鳴。', `MaleText_loc7`='Estate $gquieto, pequeño:quieta, pequeña;, y podrás escuchar a esta ancestral tierra hablar. Llora de dolor.' WHERE `ID`=34485;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고대정령 오누여, 대지의 씨앗을 어디에서 찾을 수 있을까요?', `MaleText_loc4`='古老的安努，我能在哪里找到一颗大地之种？', `MaleText_loc5`='古老的安努，請問我在哪才能找到大地種子?', `MaleText_loc7`='Ancestro Onus, ¿dónde puedo encontrar la Semilla de la Tierra?', `FemaleText_loc1`='고대정령 오누여, 대지의 씨앗을 어디에서 찾을 수 있을까요?', `FemaleText_loc4`='古老的安努，我能在哪里找到一颗大地之种？', `FemaleText_loc5`='古老的安努，請問我在哪才能找到大地種子?', `FemaleText_loc7`='Ancestro Onus, ¿dónde puedo encontrar la Semilla de la Tierra?' WHERE `ID`=34486;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠, 흠... 젊은 친구가 강력한 재료를 찾는군. 얼라이언스의 이름으로 자네는 많은 적을 처치하겠지만, 거대한 순환의 고리에서 탄생은 죽음만큼 강하다는 걸 명심하게나.$B$B<천천히 자기 머리 위로 고개를 들고 눈에 잘 안 띄는 도토리를 따더니, 느긋하고 침착하게 당신에게 팔을 내리는 오누>$B$B이 도토리는 대단히 강력하다네.$B$B뽐내는 소리로 들리길 원치 않았는데... 사과하겠네.', `MaleText_loc4`='嗯，这么年轻就拥有了如此强大的力量，这可真是惊人。你一定能以联盟的名义杀死无数敌人。但必须记住，在伟大的循环之中，生具有和死一样强大的力量。$B$B<安努缓缓地伸手到自己的头顶，摘下一颗不显眼的橡实，然后以从容不迫的姿态将手放在你面前>$B$B它有着特别的力量。$B$B……很抱歉，希望你不会认为我这是在自吹自擂。', `MaleText_loc5`='嗯..嗯。力量強大的施法材料讓如此年輕的人得到。你將以你的同盟之名殺死許多敵人。但切記...在偉大的循環中，誕生的力量與死亡是對等的。$B$B<安努慢慢地拿了一粒頭上不起眼的果實。他不急不徐地把手放在你的面前。>$B$B這粒果實的力量極為強大。$B$B...我必須道歉，我沒有想要自吹自擂的意思。', `MaleText_loc7`='Hmmm. Un componente poderoso para alguien tan joven. Matarás a muchos enemigos en el nombre de tu Alianza, pero es importante que recuerdes que en el gran círculo el nacimiento es tan poderoso como la muerte.$B$B<Onus lleva la mano lentamente hasta su cabeza y retira una discreta bellota. Baja el brazo con tranquila calma.>$B$BEsto es extremadamente potente,$B$B... Discúlpame, no quería que sonara como una fanfarronería.' WHERE `ID`=34487;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어떤 방해도 용서치 않겠다!', `FemaleText_loc4`='绝不容忍外人的打扰！', `FemaleText_loc5`='我們不可以被干擾!', `FemaleText_loc7`='¡No permitimos que nos interrumpan!' WHERE `ID`=34488;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아즈샤라 여왕께서 돌아와 너희 땅을 빼앗아 버리실 거다.', `FemaleText_loc4`='艾萨拉女王将会归来，你们将会失去一切土地。', `FemaleText_loc5`='艾薩拉女王歸來之時，就是你們的大地被沒收之時。', `FemaleText_loc7`='La reina Azshara regresará y su tierra estará perdida.' WHERE `ID`=34489;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너희에겐 되갚아야 할 시간만 있을 뿐이다. 바다가 너희를 삼켜버리리라.', `FemaleText_loc4`='你们的末日到了。海洋将会吞噬你们。', `FemaleText_loc5`='你的生命已進入倒數階段。大海將吞噬你。', `FemaleText_loc7`='Vivís de prestado. El mar os consumirá.' WHERE `ID`=34490;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나이트 엘프의 시대는 끝날 거다.', `FemaleText_loc4`='暗夜精灵的时代即将终结。', `FemaleText_loc5`='夜精靈的時代即將結束。', `FemaleText_loc7`='El tiempo de los elfos de la noche llega a su fin.' WHERE `ID`=34491;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적들이 서 있는 곳에서 놈들을 얼려버릴 수 있는지 보겠습니다.', `MaleText_loc4`='小$r，来看看我们是不是能把敌人冻住。', `MaleText_loc5`='讓我們試試把敵人冰在他們所站的地方，小$r。', `MaleText_loc7`='Veamos si podemos congelar al enemigo ahí mismo, $r.' WHERE `ID`=34492;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼어붙는 파도 정령을 이끌고 싸울 준비가 되었습니다.', `MaleText_loc4`='阿克塔努斯，我已经准备好率领你的严寒狂潮进入战场。', `MaleText_loc5`='阿克泰諾斯，我已經準備好帶領你的冰冷奔騰者加入戰場了。', `MaleText_loc7`='Arctanus, estoy listo para ponerme al frente de una de tus mareas heladas en la batalla.', `FemaleText_loc1`='얼어붙는 파도 정령을 이끌고 싸울 준비가 되었어요', `FemaleText_loc4`='阿克塔努斯，我已经准备好率领你的严寒狂潮进入战场。', `FemaleText_loc5`='阿克泰諾斯，我已經準備好帶領你的冰冷奔騰者加入戰場了。', `FemaleText_loc7`='Arctanus, estoy listo para ponerme al frente de una de tus mareas heladas en la batalla.' WHERE `ID`=34493;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 형제가 도를 넘어섰습니다. 그는 땅을 불태우고, 물을 증발시켜 버리고, 또 너무 많은 공기를 집어삼키고 있습니다.$B$B그가 균형과 조화로움을 되찾을 수 있도록 우리를 도와주십시오.', `MaleText_loc4`='我们的兄弟迷失了。他烧焦了大地，蒸发了水体，吞噬了太多空气。$B$B帮助我们让他回复平衡与和谐吧。', `MaleText_loc5`='我們的兄弟迷失了自己。他燃燒著大地，他蒸發著海水，他吞噬了太多的空氣。$B$B幫助我們引導他回來，並讓他恢復平衡和協調。', `MaleText_loc7`='Nuestro hermano se ha desviado de su camino. Abrasa la tierra, evapora el agua y devora demasiado aire.$B$BAyúdanos a traerlo de vuelta al equilibrio y la armonía.' WHERE `ID`=34494;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='휘몰아치는 소용돌이와 하나가 되어 군주 마그마타르를 물리칠 준비가 끝났습니다.', `MaleText_loc4`='我已经准备好与这盘旋的涡流融为一体，击败玛格玛萨勋爵。', `MaleText_loc5`='我準備好要成為旋風漩渦擊敗熾岩領主。', `MaleText_loc7`='Estoy listo para formar un uno con el vórtice giratorio y derrotar a Lord Magmathar.', `FemaleText_loc1`='휘몰아치는 소용돌이와 하나가 되어 군주 마그마타르를 물리칠 준비가 끝났어요.', `FemaleText_loc4`='我已经准备好与这盘旋的涡流融为一体，击败玛格玛萨勋爵。', `FemaleText_loc5`='我準備好要成為旋風漩渦擊敗熾岩領主。', `FemaleText_loc7`='Estoy lista para formar un uno con el vórtice giratorio y derrotar a Lord Magmathar.' WHERE `ID`=34495;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 이미 잠식당해 회복할 가망이 없습니다!', `MaleText_loc4`='%s已经被毁灭，无法拯救了！', `MaleText_loc5`='%s已經被吞噬無法獲得幫助了!', `MaleText_loc7`='¡%s ya ha sido $gconsumido:consunida; y no se le puede ayudar!' WHERE `ID`=34496;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 잠식당할 위험에서 보호받았습니다.', `MaleText_loc4`='%s受到了保护，不会被吞噬。', `MaleText_loc5`='%s已經被保護免於受到吞噬。', `MaleText_loc7`='%s ahora se protege de consumo.', `FemaleText_loc1`='%s|1이;가; 잠식당할 위험에서 보호받았습니다.', `FemaleText_loc4`='%s受到了保护，不会被吞噬。', `FemaleText_loc5`='%s已經被保護免於受到吞噬。', `FemaleText_loc7`='%s ahora se protege de consumo.' WHERE `ID`=34497;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 고기를 움켜쥐고는 탐욕스럽게 먹어치웁니다.', `MaleText_loc4`='%s抓住肉块，然后狼吞虎咽起来。', `MaleText_loc5`='%s接住了肉，飢餓地狼吞虎嚥。', `MaleText_loc7`='%s atrapa la carne y la engulle con ansia.' WHERE `ID`=34498;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 만족스러운 듯 그르렁거립니다.', `MaleText_loc4`='%s心满意足地呜呜叫着。', `MaleText_loc5`='%s發出滿足的低鳴。', `MaleText_loc7`='%s ronronea felizmente.' WHERE `ID`=34499;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 우주의 강타를 시전하기 시작합니다!', `MaleText_loc4`='%s开始施放宇宙重击！', `MaleText_loc5`='%s開始施展宇宙潰擊!', `MaleText_loc7`='¡%s comienza a lanzar Machaque cósmico!' WHERE `ID`=34500;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시들이가 물을 흡수하더니 원래 크기로 자랍니다.', `MaleText_loc4`='枯萎的树人将水吸入体内，恢复成原先的大小。', `MaleText_loc5`='阿萎吸收了水份後，恢復到了原來的大小。', `MaleText_loc7`='Marchituelo absorbe el agua y recupera todo su tamaño.' WHERE `ID`=34501;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도망칠 곳은 없다! 오직 내 불타는 용암만이 반겨줄 것이다!', `MaleText_loc4`='这里无路可逃！只有我的岩浆的热烈拥抱！', `MaleText_loc5`='無處可逃!等著你們的只有我的熔岩所帶來的火焰之擁!', `MaleText_loc7`='¡No hay escapatoria! ¡Solo existe el ardiente abrazo de mi lava!' WHERE `ID`=34502;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음이 지하에서 솟아올라 땅 위를 뒤덮을 것이다! 도망칠 곳은 없다!', `MaleText_loc4`='死亡从下方升起，从上面爆发！无人可以逃脱！', `MaleText_loc5`='死亡從地面升起和從天空驟降!無處可逃!', `MaleText_loc7`='¡La muerte surge desde debajo y entra en erupción desde arriba! ¡No hay escapatoria!' WHERE `ID`=34503;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='땅을 불태우고, 물을 증발시키고, 하늘을 불태워라!', `MaleText_loc4`='烧焦大地，蒸干流水，点燃天空！', `MaleText_loc5`='大地、海水和天空都被燃燒沸騰!', `MaleText_loc7`='¡Abrasar la tierra, hervir el agua y prender los cielos!' WHERE `ID`=34504;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대지 고리회는 나의 분노를 당해낼 수 없다!', `MaleText_loc4`='大地之环无法抵挡我的愤怒！', `MaleText_loc5`='陶土議會無力承受我的怒火!', `MaleText_loc7`='¡El Anillo de la Tierra no puede soportar mi furia!' WHERE `ID`=34505;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부하들아, 저들을 죽여라!', `MaleText_loc4`='我的奴仆们，毁灭他们！', `MaleText_loc5`='我的僕從們，消滅他們!', `MaleText_loc7`='¡Destrúyanlos, esbirros míos!' WHERE `ID`=34506;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대지의 속박에서 풀려났으니 다시는 돌아가지 않을 것이다!', `MaleText_loc4`='我已经挣脱了大地的束缚，我绝不会再回去！', `MaleText_loc5`='我從大地的束縛中解脫了，絕不再返回!', `MaleText_loc7`='¡Soy libre de las ataduras de la tierra y no volveré jamás!' WHERE `ID`=34507;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잿빛 골짜기는 불타오를 것이다!', `MaleText_loc4`='灰谷将陷入火海！', `MaleText_loc5`='梣谷將會燃燒殆盡!', `MaleText_loc7`='¡VALLEFRESNO ARDERÁ!' WHERE `ID`=34508;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불로 뛰어드는 불나방이나 다름없구나!', `MaleText_loc4`='就像飞蛾投火！', `MaleText_loc5`='飛蛾撲火!', `MaleText_loc7`='¡Como polillas hacia la luz!' WHERE `ID`=34509;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<*우르르*우르르*우르르*>', `MaleText_loc4`='<*轰隆*轰隆*轰隆*>', `MaleText_loc5`='<*轟隆*轟隆*轟隆>', `MaleText_loc7`='<*Estruendo*Estruendo*Estruendo*>' WHERE `ID`=34510;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 폭풍우 하수인을 과충전시킵니다!', `MaleText_loc4`='%s使一个风暴爪牙超载了！', `MaleText_loc5`='%s讓一個暴雨爪牙超載!', `MaleText_loc7`='¡%s sobrecarga un esbirro tempetuoso!' WHERE `ID`=34511;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이곳의 야생 동물들을 보호할 수 있도록 도와주셔서 감사해요. 우리가 그리 늦지 않았길 바랄 뿐입니다.', `FemaleText_loc4`='感谢你帮助我们保护这里的自然生命。希望一切都还不至于太晚。', `FemaleText_loc5`='我很感激你幫忙保護這裡的野生動植物。希望我們這樣做還不算太遲。', `FemaleText_loc7`='Aprecio tu ayuda para defender la fauna local. Espero que no sea demasiado tarde.' WHERE `ID`=34512;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='도와주셔서 감사해요, $n 님! 이 나무들은 한때 이곳에서 살았던 악마들에게서 완전히 자유롭지는 못할지도 몰라요. 하지만 제가 이곳을 지킬 수 있게 그대와 같은 영웅이 도와준다는 사실을 아니 기분이 나아지네요.', `FemaleText_loc4`='感谢你的帮助，$n！这片森林中潜藏的邪恶从没有彻底消失过，但知道有你这样的英雄帮助我守护这里，我的感觉就好多了。', `FemaleText_loc5`='謝謝你的幫忙，$n!這片森林或許永遠都會受到過去存在於此地的邪惡力量所威脅，但在知道有像你這樣的英雄幫忙，我感覺好多了。', `FemaleText_loc7`='¡Gracias por tu ayuda, $n! Puede que estos bosques nunca estén a salvo de la maldad que una vez habitó en ellos, pero saber que hay héroes como tú que me ayudan con la vigilancia hace que me sienta mejor.' WHERE `ID`=34513;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고대 신들은 누구입니까?', `MaleText_loc4`='谁是上古之神？', `MaleText_loc5`='什麼是上古之神?', `MaleText_loc7`='¿Quiénes son los Antiguos?', `FemaleText_loc1`='고대 신들은 누구인가요?', `FemaleText_loc4`='谁是上古之神？', `FemaleText_loc5`='什麼是上古之神?', `FemaleText_loc7`='¿Quiénes son los Antiguos?' WHERE `ID`=34514;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 더 말씀드릴 수 있으면 좋겠지만, 최근까지 누구도 그런 생명체가 있다고 믿지 않았어요. 티탄이 아제로스를 오늘날 우리가 아는 세계로 만들기 훨씬 이전에, 우리가 아는 생사의 순환 이전에, 고대 신들은 자신들의 악의적인 목적을 위해 쓸 정령과 타락한 피조물들을 관장했어요.$B$B여기 오누가 저에게 말해준 걸로는 티탄들은 종국에 고대 신들을 물리쳤다는군요. 물리치지 못했다고 하더라도 티탄들이 고대신을 지구 아래로 가둬놨을 거랍니다. 고대 신과 같은 존재들이 정말 죽기는 할까요? 더 알았으면 좋겠지만, 저에겐 너무나도 예전 이야기인데다가 한동안 여기저기 돌아다녀서요.$B$B그대가 믿는다면 말입니다만, 고대 신을 섬기는 자들이 있는 걸 압니다. 그런 일은 이 세계의 종말을 기도하는 것과 같아요. 그 고대 신들은 사람들을 미치게 하니까요!', `FemaleText_loc4`='希望能多告诉你一些这方面的事情。现在已经几乎没有人相信还有这种生物存在了。古久以前，泰坦将艾泽拉斯塑造成我们今天所看到的这个世界，生与死的循环于焉建立。但在此之前，统治这里的是上古之神和服从于他们的元素。为了实现邪恶的目的，他们腐蚀这里的一切造物。$B$B安努告诉我，上古之神最终被泰坦击败，被囚禁在大地之下。这样的怪物真的有可能死亡吗？我希望自己能知道得更多一些，尽管这些都已经是超越了历史的故事。为此，我做了相当长时间的研究。$B$B我知道现在存在着对上古之神的崇拜，无论这是多么难以相信的事情。那些崇拜者似乎正在祈求这个世界的毁灭。上古之神的确是能够让人们发狂！', `FemaleText_loc5`='我希望能告訴你更多，但在此之前誰都不相信這種生物是存在的。遠在泰坦塑造了我們今天所見的艾澤拉斯之前，在我們所知的自然界生死輪迴之前，上古之神為了達成他們邪惡的目地統治了元素和腐化了的生物。$B$B這裡的安努告訴了我，說泰坦們最終擊敗了上古之神，又或者是把他們囚禁在地底深淵。上古之神真的會死嗎?我自己也希望我知道。但這全都是比史前學還要久遠的史前學，而我已經算存在很久了。$B$B我知道有些相信這些歷史的人膜拜著上古之神，這與祈禱世界的毀滅沒什麼兩樣。這些古神會讓人喪失理智!', `FemaleText_loc7`='Ojalá pudiera contarte más, pero hasta hace poco nadie creía que existieran tales criaturas. Mucho antes de que los Titanes convirtieran Azeroth en el mundo que vemos hoy, antes del ciclo de la vida y la muerte tal y como lo conocemos, los Antiguos gobernaban los elementos y las creaciones corruptas para que sirvieran a sus malignos propósitos.$b$bPor lo que me cuenta Onus, los Titanes acabaron por derrotar a los Antiguos. O al menos los apresaron bajo la tierra. ¿Puede morir algo así? Me gustaría saber más, pero para mí esto es pre-prehistoria y no soy precisamente joven.$b$bSé que algunas personas adoran a los Antiguos, ¿te lo puedes creer? Es como rezar para que llegue el fin del mundo. ¡Los dioses antiguos vuelven loca a la gente!' WHERE `ID`=34515;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 허겁지겁 알을 삼킵니다.', `MaleText_loc4`='%s饥饿地吃着蛋。', `MaleText_loc5`='%s飢餓地吞下那些蛋。', `MaleText_loc7`='%s devora el huevo con ansia.' WHERE `ID`=34516;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<당신이 자기 엄마인지 아닌지 고민하는 눈초리로 쳐다보는 새끼 맹독가죽>', `MaleText_loc4`='<这只幼崽死盯着你，仿佛想分辨出你是不是它的妈妈。>', `MaleText_loc5`='<小暴掠龍看著你，似乎在想你到底是不是牠媽媽。>', `MaleText_loc7`='<La prole te mira como si intentara averiguar si eres o no su madre.>' WHERE `ID`=34517;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새끼 맹독가죽을 잃어버렸습니다. 혹시 녀석을 보셨습니까?', `MaleText_loc4`='我的毒皮暴掠幼龙走丢了。你看到它了吗？', `MaleText_loc5`='我弄丟了我的毒皮小暴掠龍。你有看到它嗎?', `MaleText_loc7`='He perdido mi prole de Pellejo Venenoso. ¿La has visto?', `FemaleText_loc1`='새끼 맹독가죽을 잃어버렸어요. 혹시 녀석을 보셨나요?', `FemaleText_loc4`='我的毒皮暴掠幼龙走丢了。你看到它了吗？', `FemaleText_loc5`='我弄丟了我的毒皮小暴掠龍。你有看到它嗎?', `FemaleText_loc7`='He perdido mi prole de Pellejo Venenoso. ¿La has visto?' WHERE `ID`=34518;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 먹이를 삼킵니다.', `MaleText_loc4`='%s大口吞咽着食物。', `MaleText_loc5`='%s吞下食物。', `MaleText_loc7`='La %s devora la comida.' WHERE `ID`=34519;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 먹이를 물더니 한 입에 꿀꺽 삼킵니다.', `MaleText_loc4`='%s抓起食物，一口吞了下去。', `MaleText_loc5`='%s用嘴接住食物，然後狼吞虎嚥地吞下。', `MaleText_loc7`='La %s atrapa la comida con la boca y se la traga de golpe.' WHERE `ID`=34520;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 튼튼한 턱으로 먹이를 마구 씹습니다.', `MaleText_loc4`='%s用它强壮的颚撕咬着食物。', `MaleText_loc5`='%s用強而有力的雙顎把食物撕成碎塊。', `MaleText_loc7`='Las fuertes fauces de la %s despedazan la comida.' WHERE `ID`=34521;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 금세 먹이를 집어삼키고는 더 없는지 주위를 둘러봅니다.', `MaleText_loc4`='%s很快就把食物吃了个干净，它焦急地四处看着，好像还没吃饱。', `MaleText_loc5`='%s飛快地吃光它的食物，四處張望著想要更多。', `MaleText_loc7`='La %s se acaba la comida enseguida y busca más con la mirada.' WHERE `ID`=34522;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발굴현장을 포기하자고요? 웃기는군요! 제가 근면하고 성실하게 일한 오랜 경력을 통틀어 현장을 포기한 적은 없습니다. 고의적으로 말이에요. 잘못 판 적은 몇 번 있을 테지만요. 근데 당신 누굽니까? 우리 여기서 뭐 하는 거죠?', `MaleText_loc4`='放弃挖掘？这太荒谬了！在我漫长而勤勉的一生中，我还从没有放弃过一个发掘点。也许我有勘探错误的时候，但从不曾有意放弃过任何值得挖掘的地方。你又是谁？我们在这里做什么？', `MaleText_loc5`='放棄挖掘?別開玩笑了!在我的專業生涯中，我從沒放棄過任何一個挖掘場，沒有故意放棄。或許有挖錯幾個點。對了，你是誰啊?我們在這幹麻?', `MaleText_loc7`='¿Dejar de cavar? ¡Qué ridículo! En mi larga y laboriosa carrera, nunca he abandonado una excavación. No intencionadamente. A lo mejor he extraviado algunas. ¿Quién decías que eras? ¿Qué estamos haciendo aquí?' WHERE `ID`=34523;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최고로군요! 힘을 비축하세요, 아무개 씨. 갈 길이 머니까요.', `MaleText_loc4`='好极了！振作起来，我们还有很长的路要走。', `MaleText_loc5`='太好了!打起精神來，叫什麼來著的。我們還有好一段路要走。', `MaleText_loc7`='¡Magnífico! Recupera las fuerzas, seas quien seas. Tenemos un largo viaje por delante.' WHERE `ID`=34524;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비됐나요? 움직입시다!', `MaleText_loc4`='准备好了？我们出发！', `MaleText_loc5`='好了嗎?我們走吧!', `MaleText_loc7`='¿$gListo:Lista;? ¡Vamos!' WHERE `ID`=34525;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 보이는 폐허는 몇 달 전에 제가 판 폐허랑 똑같아요. 근데 물에 침수되고 말았죠! 기이하죠?', `MaleText_loc4`='你在这里看见的废墟就是我在几个月以前挖掘的废墟，但它被淹没了！真是奇怪，不是么？', `MaleText_loc5`='你在這看到的遺蹟與我前幾個月所挖出來的一模一樣，但卻是被水淹沒的。很奇妙吧?', `MaleText_loc7`='¡Estas ruinas que he encontrado son IDÉNTICAS a las que acabo de abandonar! ¡Es el descubrimiento del siglo!' WHERE `ID`=34526;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 거의 다 왔군요, 아무개 씨! 제 일지를 놓고 온 야영지가 아주 가까워요!', `MaleText_loc4`='啊，清醒一点，我们就要完成了！我放置记录的那座帐篷就在附近！', `MaleText_loc5`='啊，我們就快到了，提起精神來!那個我放筆記的營地就在不遠處。', `MaleText_loc7`='¡Ya casi hemos llegado, como-te-llames! ¡El campamento en el que me dejé las notas está a un paso!' WHERE `ID`=34527;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세 망치단의 이름으로, 저걸 좀 보라고요! 폐허가 더 있어요!', `MaleText_loc4`='以三锤部族之名，你好好看看！这里只有废墟！', `MaleText_loc5`='以三錘之名，你看看!更多的遺蹟!', `MaleText_loc7`='¡Por los tres martillos, mira eso! ¡Más ruinas!' WHERE `ID`=34528;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 찾은 이 폐허들은 방금 떠나온 폐허들하고 완전히 똑같군! 일생일대의 발견이야!', `MaleText_loc4`='我找到的这座废墟就是我刚刚离开的那座废墟！看来我真的是要找一辈子了！', `MaleText_loc5`='新發現的這片遺蹟跟我剛離開的那裡一模一樣!這真是可遇不可求啊!', `MaleText_loc7`='¡Estas ruinas que he encontrado son IDÉNTICAS a las que acabo de abandonar! ¡Es el descubrimiento del siglo!' WHERE `ID`=34529;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 무지한 얼간이 친구야, 저 폐허는 똑같은 폐허란 말이야. 똑같은 곳을 뱅뱅 돌고 있었다고!', `MaleText_loc4`='你这个大笨蛋，这还是那座废墟。你只是在绕圈子。', `MaleText_loc5`='你這大笨蛋，這些都是同一座遺蹟。你這是在原地打轉。', `MaleText_loc7`='Tremendo zoquete, estas SON las mismas ruinas. Estás caminando en círculos de nuevo.' WHERE `ID`=34530;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말도 안 돼, 보라고. 이게 내 일지라고, 여기 말이야.', `MaleText_loc4`='胡说。看见了吗？这就是我的日志，就在这里。', `MaleText_loc5`='胡說。看到了嗎?我的日記在這，就在這。', `MaleText_loc7`='Tonterías. ¿Ves? Aquí está mi diario, justo aquí.' WHERE `ID`=34531;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='페르드, 지금 이 상황을 어떻게 생각하나?', `MaleText_loc4`='你是怎么做到的，费德？', `MaleText_loc5`='費德，你怎麼說?', `MaleText_loc7`='¿Qué deduces de esto, Ferd?' WHERE `ID`=34532;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 친구는 어디서 온 거지? 솔직하게 말해!', `MaleText_loc4`='说实话，这个$n是从哪里来的？', `MaleText_loc5`='這個$n是哪裡冒出來的?老實說。', `MaleText_loc7`='¿De dónde ha salido $geste:esta; $n? Ahora en serio.' WHERE `ID`=34534;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그나저나 누가 $n|1을;를; 파낸 거야?', `MaleText_loc4`='是谁把这个$n挖出来的？', `MaleText_loc5`='是誰把這個$n挖出來的，啊?', `MaleText_loc7`='¿Quién ha excavado $geste:esta; $n?' WHERE `ID`=34535;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 고대인들이 자기 도시를 $n의 옆에 지었지?', `MaleText_loc4`='这些古代先民为什么要把他们的城市建造在这些$n的旁边？', `MaleText_loc5`='為什麼古代人要把他們的城市都蓋在這些$n旁邊?', `MaleText_loc7`='¿Por qué construyeron los ancestros sus ciudades junto a todos estos $ns?' WHERE `ID`=34536;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 유물이 우리에게 뭘 알려줄지 보죠...', `MaleText_loc4`='让我们看看这件宝物会告诉我们什么……', `MaleText_loc5`='看看這件東西能為我們解答多少...', `MaleText_loc7`='Veamos qué nos cuenta este artefacto...' WHERE `ID`=34537;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이럴 줄 알았어요! 어떤 메시지를 보내는 거예요!', `MaleText_loc4`='我认识它！它正在发出一条信息！', `MaleText_loc5`='我就知道!這上面有某種訊息!', `MaleText_loc7`='¡Lo sabía! ¡Está transmitiendo un mensaje!' WHERE `ID`=34538;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저걸 없애세요!', `MaleText_loc4`='杀了它！', `MaleText_loc5`='殺死它!', `MaleText_loc7`='¡Mátalo!' WHERE `ID`=34539;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어머니?', `MaleText_loc4`='妈妈？', `MaleText_loc5`='母親?', `MaleText_loc7`='¿Madre?' WHERE `ID`=34540;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 진단... 진단... 실패.', `MaleText_loc4`='……诊断……诊断……失败。', `MaleText_loc5`='...診斷...診斷...失敗。', `MaleText_loc7`='... Diagnóstico... Diagnóstico... Fallo.' WHERE `ID`=34541;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 발굴현장은 위태롭다. 위상들께 알려야 한다.', `MaleText_loc4`='遗迹被破坏了，必须马上警告守护巨龙们。', `MaleText_loc5`='地方受到了威脅。必須讓報告給巨龍們。', `MaleText_loc7`='La zona no es segura. Se debe alertar a los Aspectos.' WHERE `ID`=34542;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대단하네요. 발굴조사단장 렘트래블 님께서 다시 일을 마쳤군요! 아이언포지에서 이 광경을 이해할지 보죠.', `MaleText_loc4`='真是令人震惊。勘察员雷塔维又成功了！我们要看看，这对铁炉堡将有什么意义。', `MaleText_loc5`='太棒了。勘察員雷姆塔維爾再次創造了奇蹟!看看鐵爐堡是否可以解讀這個。', `MaleText_loc7`='Impresionante. ¡El prospector Tripirrem lo ha vuelto a lograr! Veremos si Forjaz le encuentra sentido.' WHERE `ID`=34543;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아브루스는 그의 날카로운 발톱으로 자신의 가슴을 파헤쳐 고동치는 심장을 빼내고 유성 월장석을 가슴에 넣습니다.', `MaleText_loc4`='阿夫鲁斯用他剃刀一样锋利的爪子伸进胸口，掏出自己的内核，将它和那些落下的月亮石放在一起。', `MaleText_loc5`='使用了如剃刀般鋒利的爪子，亞弗瑞斯剖開了他的胸腔將還在跳動的心臟挖了出來，將它與隕落的月亮石放在一起。', `MaleText_loc7`='Con sus garras afiladas como cuchillas, Avrus le abre el pecho y extrae su corazón latiente. Después lo coloca junto a las piedras lunares caídas.' WHERE `ID`=34544;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놀랍게도 사티로스는 죽지 않습니다. 대신 그는 따스한 빛으로 둘러싸였습니다.', `MaleText_loc4`='不可思议的是，这只萨特并没有死，而是沐浴在一片温暖的光亮之中。', `MaleText_loc5`='薩特奇蹟似地活了下來。不但如此，還正沐浴於溫暖的光中。', `MaleText_loc7`='Milagrosamente, el sátiro no muere. Sin embargo, se sumerge en una cálida luz.' WHERE `ID`=34545;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 발굴현장은 위험해요. 탐험가 연맹에선 우리에게 가치가 있을 만한 걸 챙기고 이곳을 정리하길 바라죠. 말은 쉽지만 하긴 쉽지 않아요.', `MaleText_loc4`='我们的挖掘计划已经不可能完成了——探险者协会要我们尽量收集一切有价值的物品，然后离开。说的容易，做起来可不容易。', `MaleText_loc5`='這個挖掘場受到了威脅，探險者協會要我們馬上把值錢的東西帶上後閃人。說的比做的簡單。', `MaleText_loc7`='Esta excavación está comprometida. La Liga de Expedicionarios quiere que cojamos todo lo que quede de valor y que nos larguemos. Fácil de decir, pero no de hacer.' WHERE `ID`=34546;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s의 모습이 변했습니다!', `MaleText_loc4`='%s变形了！', `MaleText_loc5`='%s被轉換了!', `MaleText_loc7`='¡%s se transforma!' WHERE `ID`=34547;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멀록들이란, 흥!', `MaleText_loc4`='鱼人，呸！', `MaleText_loc5`='魚人。嘿!', `MaleText_loc7`='Múrlocs. ¡Bah!' WHERE `ID`=34548;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그림팽 사령관님께서 헬스크림 감시초소로 가라고 명령하셨습니다.', `MaleText_loc4`='恐牙命令我前往地狱咆哮岗哨。', `MaleText_loc5`='厲牙命令我到地獄吼守望。', `MaleText_loc7`='Colminiestro me ha destinado a la Avanzada Grito Infernal.', `FemaleText_loc1`='그림팽 사령관님께서 헬스크림 감시초소로 가라고 명령하셨습니다.', `FemaleText_loc4`='恐牙命令我前往地狱咆哮岗哨。', `FemaleText_loc5`='厲牙命令我到地獄吼守望。', `FemaleText_loc7`='Colminiestro me ha destinado a la Avanzada Grito Infernal.' WHERE `ID`=34549;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='죽은 드리아드의 시신은 그녀가 호드에게 목숨을 잃은 이곳에 누워 있어요.', `FemaleText_loc4`='这个树妖已经死亡了，显然是部落夺走了她的生命。', `FemaleText_loc5`='死去林精的屍體躺在這，她的生命是被部落奪去的。', `FemaleText_loc7`='El cuerpo de la dríada caída yace donde la Horda acabó con su vida.' WHERE `ID`=34550;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위안의 의식이 시작되었습니다. 어떻게 해서든 토템을 보호하십시오!', `MaleText_loc4`='安抚仪式已经开始。要不惜一切代价守卫住图腾！', `MaleText_loc5`='安撫儀式開始了。全力防衛圖騰!', `MaleText_loc7`='El ritual de sosiego ha comenzado. ¡Defiende el tótem cueste lo que cueste!' WHERE `ID`=34551;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 %s|1이;가; 껍질을 깨고 나옵니다!', `MaleText_loc4`='一个%s从壳中钻了出来！', `MaleText_loc5`='一個%s由殼中出現了!', `MaleText_loc7`='¡%s emerge del caparazón!' WHERE `ID`=34552;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위안의 의식이 끝났습니다.', `MaleText_loc4`='安抚仪式完成了。', `MaleText_loc5`='安撫儀式完成了。', `MaleText_loc7`='El ritual de sosiego se ha completado.' WHERE `ID`=34553;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='리치 왕의 잔인한 통치는 노스렌드 전역의 주민들에게 커다란 고통을 안겨 주었답니다. 특히 아이들에게요. 만약 당신이 숄라자르 분지에 있는 점쟁이 조합이나 광란심장 일족의 친구라면, 한 주 동안만 고아를 하나 보살펴 주는 걸 고려해 보시지요.', `FemaleText_loc4`='巫妖王的残酷统治让所有诺森德的居民们都饱受痛苦，尤其是那些孩子。如果你是索拉查盆地的狂心氏族或是神谕者的朋友，也许你会考虑抚养他们的一位孤儿，陪那个小家伙一周。', `FemaleText_loc5`='巫妖王的殘酷統治讓北裂境的所有居民都飽受苦難，尤其是孩子們。如果你是休拉薩的神諭者或狂心部族的朋友，或許你願意花上一個禮拜照顧一位孤兒。', `FemaleText_loc7`='El cruel reinado del Rey Exánime ha impuesto grandes penurias a todos los habitantes de Rasganorte, en particular a los niños. Si eres amigo de los Oráculos o de la tribu Corazón Frenético, quizás puedas considerar cuidar de un huérfano durante una semana.' WHERE `ID`=34554;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 숙성된 노른자위 먹으러 가?', `MaleText_loc4`='能给我们点陈年蛋黄吃吗？', `MaleText_loc5`='我們可以來點陳年卵黃嗎?', `MaleText_loc7`='¿Podemos tomar yema vieja?' WHERE `ID`=34555;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위대한 자들도 가방이 가득 차서 반짝이 못 주운 적 있을까?', `MaleText_loc4`='难道连造物主的包包也满了吗？', `MaleText_loc5`='諸神也會袋子不夠大，沒辦法裝完所有閃亮亮的東西嗎?', `MaleText_loc7`='¿Se quedan alguna vez los Magnos sin espacio para objetos valiosos en las bolsas?' WHERE `ID`=34556;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하룻강아지 꼬마들은 왜 만날 루가 라푸 불쌍해하느냐고 물어봐? 라푸 말 많이 하지만 루 친군데.', `MaleText_loc4`='你觉得小狗狗人为什么总追问我们是否同情拉弗乌呢？拉弗乌的确很多话，但他是我们的好朋友。', `MaleText_loc5`='為什麼小狗人的小鬼老是愛問我們是不是同情拉富?拉富雖然話很多，但他是我們的朋友。', `MaleText_loc7`='¿Por qué piensas que crías de hombres cachorro seguir preguntando si Lafoo darnos pena? Lafoo hablar mucho, pero ser nuestro amigo.' WHERE `ID`=34557;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='''수''$n, 루한테 호루라기 주면 안 돼? 호루라기 불면 달려와 줘. 응응?', `MaleText_loc4`='那么$n，你能给我们个哨子吗？这样我们想你的时候吹吹哨子就能见到你了，好吗？', `MaleText_loc5`='蘇-$n，或許你可以給我們個哨子，當我們需要找你的時候就吹哨子。好嗎?', `MaleText_loc7`='Soo-$n, quizás darnos silbato para cuando necesitar llamarte. ¿Vale?' WHERE `ID`=34558;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어쩌면, 루도 다 크면 $r 될지도 몰라. 그지?', `MaleText_loc4`='也许我们长大了会成为$r呢。是不是呀？', `MaleText_loc5`='說不定我們長大之後會長成一個$r。你覺得呢?', `MaleText_loc7`='Quizás ser $gun:una; $r cuando crecer, ¿qué te parece?' WHERE `ID`=34559;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$g형:누나; 엄마랑 아빠도 하룻강아지한테 죽었어? 그래서 혼자야?', `MaleText_loc4`='你也是因为狗狗人才变成孤儿了吗？', `MaleText_loc5`='你也是因為小狗人殺死了你爸媽所以很孤單嗎?', `MaleText_loc7`='¿Estás a solas porque hombres cachorro mataron a tus padres también?' WHERE `ID`=34560;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물범 인간 옆에 가면 안 된다. 우리 유괴당한다.', `MaleText_loc4`='你得离海象人远点。他们会弄痛你。', `MaleText_loc5`='你應該離那些海象人遠一點。他們可能會偷襲你。', `MaleText_loc7`='Deberías apartarte de los hombres morsa. Podrían raptarte.' WHERE `ID`=34561;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='케켁이 $g형:누나; 사냥에 데려가 준다. 좋은 미끼다.', `MaleText_loc4`='科科要带你去打猎。你是个不错的诱饵。', `MaleText_loc5`='恰嘎帶你打獵。你要當個好餌。', `MaleText_loc7`='Kekek llevarte a cazar. Tu ser buen cebo.' WHERE `ID`=34562;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오크는 만날 케켁 손가락질하며 웃는다. 케켁이 언젠가 복수할 거다.', `MaleText_loc4`='兽人们总是嘲笑科科，科科迟早会让他们好看。', `MaleText_loc5`='獸人總是指著恰嘎笑，不過有一天他會報仇。', `MaleText_loc7`='Orcos siempre señalar y reír de Kekek, pero él vengarse algún día.' WHERE `ID`=34563;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그거 아나? 케켁이 눈 감으면, $g형:누나; 케켁 못 본다.', `MaleText_loc4`='你知道吗？要是科科闭上眼，你就看不到他了。', `MaleText_loc5`='知道嗎?如果恰嘎閉上眼睛，你就看不到他。', `MaleText_loc7`='¿Saber qué? Si Kekek cerrar ojos, tú no poder verlo.' WHERE `ID`=34564;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='점심 먹으려고 닭 세 마리나 잡았다. $g형:누나;|1은;는; 한 마리도 못 잡을걸.', `MaleText_loc4`='抓三只小鸡来当午饭。不过我赌你连毛都碰不到。', `MaleText_loc5`='抓三隻雞來當午餐。賭你連一隻都抓不到。', `MaleText_loc7`='Atrapé tres pollos para comer. Apuesto a que tú ni uno.' WHERE `ID`=34565;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='케켁이 날름이들이 제일 좋아하는 장난감 뺏었다. $g형:누나; 밤에 잘 자게 도와줄 거다.', `MaleText_loc4`='科科带来了大舌头怪幼崽最喜欢的玩具。也许它能让你晚上睡个好觉。', `MaleText_loc5`='恰嘎拿走了大舌頭小鬼最愛的玩具。說不定這能讓你晚上睡個好覺。', `MaleText_loc7`='Kekek cogió el juguete favorito de cría de lengua-grande. Quizá ayudarte a dormir por la noche.' WHERE `ID`=34566;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고아에 대해 묻고 싶습니다.', `MaleText_loc4`='询问那些孤儿的事情。', `MaleText_loc5`='詢問關於孤兒的事。', `MaleText_loc7`='Pregunta sobre los huérfanos.', `FemaleText_loc1`='고아에 대해 묻고 싶어요.', `FemaleText_loc4`='询问那些孤儿的事情。', `FemaleText_loc5`='詢問關於孤兒的事。', `FemaleText_loc7`='Pregunta sobre los huérfanos.' WHERE `ID`=34567;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저희가 데리고 있는 고아들은 숄라자르 분지를 뒤흔든 전쟁의 희생자들입니다. 당신은 점쟁이 조합 고아나 광란심장 일족 고아 중 하나를 골라 돌보실 수 있어요. 둘 다 새 친구가 생기면 좋아라 하겠지만, 안타깝게도 당신은 한 명만 고르실 수 있답니다.', `FemaleText_loc4`='我们接收的这些孤儿都来自于被战火焚毁的索拉查盆地。你可以选择照料一个神谕者或者是一个狂心氏族的孤儿。不管怎样，他们都会为了能结识一个新朋友而高兴。但你只能照顾他们之中的一个人。', `FemaleText_loc5`='我們收容的孤兒來自戰火肆虐的休拉薩盆地。你可以選擇照顧失去父母的小神諭者或狂心小獾狼怪。他們都會很高興能認識新朋友，但你只能照顧他們其中一邊。', `FemaleText_loc7`='Los huérfanos que hemos acogido vienen de la Cuenca de Sholazar destrozada por la guerra. Puedes elegir hacerte cargo de una prole de Oráculo huérfana o de un cachorro Corazón Frenético. Ambos estarán felices de hacer $gun nuevo amigo:una nueva amiga;, pero solo podrás cuidar de uno de ellos.' WHERE `ID`=34568;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='점쟁이 고아나 울바르 고아 중 하나를 고르셔야 해요. 둘 다 돌볼 수는 없습니다.', `FemaleText_loc4`='你可以选择照料一个神谕者孤儿或者一个狼獾人孤儿，但你不能二者兼顾。', `FemaleText_loc5`='你可以選擇照顧神諭者孤兒或是獾狼怪孤兒，但你不能同時照顧他們兩個。', `FemaleText_loc7`='Puedes elegir entre hacerte cargo de un huérfano Oráculo o un huérfano wolvar, pero no podrás ayudar a ambos.' WHERE `ID`=34569;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나무를 지키기만 해서는 안 돼요. 호드는 절대 포기하지 않을 거예요.$B$B호드를 물리쳐야만 해요!', `FemaleText_loc4`='$r，我们的任务绝不止于守卫这棵树。部落不会善罢甘休。$B$B我们必须消灭他们！', `FemaleText_loc5`='我們不能只是守護著樹，$r。部落是不會投降的。$B$B我們必須摧殘他們!', `FemaleText_loc7`='No basta con que mantengamos el árbol, $r. La Horda nunca se rendirá.$b$b¡Debemos destruirlos!' WHERE `ID`=34570;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='타세요!', `FemaleText_loc4`='要坚持住！', `FemaleText_loc5`='上來吧!', `FemaleText_loc7`='¡Sube!' WHERE `ID`=34571;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미소띤 자매의 시신을 되찾겠습니다.', `MaleText_loc4`='要带回欢笑的姐妹的尸体。', `MaleText_loc5`='回收歡笑之女的屍體。', `MaleText_loc7`='Recupera el cadáver de hermana sonriente.', `FemaleText_loc1`='미소띤 자매의 시신을 되찾겠어요.', `FemaleText_loc4`='要带回欢笑的姐妹的尸体。', `FemaleText_loc5`='回收歡笑之女的屍體。', `FemaleText_loc7`='Recupera el cadáver de hermana sonriente.' WHERE `ID`=34572;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와, 다 왔다! 근데, 이게 진짜 세계수면, 이 안에 온 세상을 넣으려고 했을 때 왜 부러졌어?', `MaleText_loc4`='我们到了！如果这是世界之树，那他们把整个世界放进这里的时候，它不会被撑破吗？', `MaleText_loc5`='我們到了!只不過，如果這是世界之樹，它怎麼會因為你們試圖把整個世界放入其中而受到破壞?', `MaleText_loc7`='¡Estar aquí! Aunque, si esto ser Árbol del Mundo, ¿por qué romperse cuando intentaron meter mundo dentro?' WHERE `ID`=34576;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='꽉 잡으세요! 비행은 제가 맡을 테니, 당신은 저 아래 야생 동물들에 집중하세요.', `FemaleText_loc4`='紧紧抓住！我来负责飞行控制，你要集中精力注意下面的野生动物。', `FemaleText_loc5`='抓緊了!我會負責飛行，你專注於下面的野生動物。', `FemaleText_loc7`='¡Agárrate fuerte! Yo me encargo de volar y tú te centras en la fauna de abajo.' WHERE `ID`=34579;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하늘에서라면 그대가 한 번에 동물들 모두에게 보호의 수호물을 걸 수 있을 거예요.', `FemaleText_loc4`='在空中，你可以向下方成群的动物施放保护结界。', `FemaleText_loc5`='從上空，你應該可以一次對一整群的動物施展保護結界。', `FemaleText_loc7`='Desde el aire, deberías poder lanzar tu protección sobre grupos enteros de animales al mismo tiempo.' WHERE `ID`=34580;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아룸, 고맙다. 그리고 $n, 고맙다. 드디어... 우린 엘룬께 돌아간다.', `MaleText_loc4`='感谢你，阿隆姆。我们也要感谢$n。终于……我们找到了艾露恩。', `MaleText_loc5`='我們謝謝你，厄羅姆。我們也謝謝$n。我們...終於能回到伊露恩的身邊了。', `MaleText_loc7`='Gracias, Aroom. Y gracias a $n. Regresamos a Elune... al fin.' WHERE `ID`=34581;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='호드는 이곳에 있어요, $n! 서두르세요, 샤둠브라의 혼을 불러내야 해요!', `FemaleText_loc4`='$n，这里有部落！快一点，我们必须使用猎影之影！', `FemaleText_loc5`='部落出現了，$n!快點，我們必須召喚薩杜布拉之影!', `FemaleText_loc7`='¡La Horda ha llegado, $n! ¡Rápido, debemos invocar la sombra de Shadumbra!' WHERE `ID`=34582;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='', `MaleText_loc4`='', `MaleText_loc5`='', `MaleText_loc7`='' WHERE `ID`=34583;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 비행 조련사들을 돕고 있습니다. 이 땅이 갈가리 찢어졌을 때 기지에서 달아날 히포그리프들을 모으고 있지요. 심지어 지금도 우리 히포그리프들은 상당히 불안해하고 있답니다.', `MaleText_loc4`='当大地被撕裂之后，我一直在帮助飞行管理员寻找逃散的角鹰兽。直到现在，我们的鸟还是无法真正安定下来。', `MaleText_loc5`='我一直在大地自己裂開的時候幫助飛行管理員們集攏到處亂飛的角鷹獸。就算現在我們的鳥都還是容易受驚。', `MaleText_loc7`='He estado ayudando a los maestros de vuelo a reunir a los hipogrifos que escaparon de su puesto cuando la tierra se quebró. Incluso ahora nuestros pájaros siguen estando preocupados.' WHERE `ID`=34584;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오르세우스, 카트레나가 보내서 왔습니다. 히포그리프를 한 마리 내어주시겠어요?', `MaleText_loc4`='奥修斯，卡瑟娜派我来向你借一头角鹰兽。', `MaleText_loc5`='厄賽魯斯，卡薩蕊娜派我來向你借一頭角鷹獸。', `MaleText_loc7`='Orseus, Kathrena me envió para pedirte uno de tus hipogrifos.', `FemaleText_loc1`='오르세우스, 카트레나가 보내서 왔습니다. 히포그리프를 한 마리 내어주시겠어요?', `FemaleText_loc4`='奥修斯，卡瑟娜派我来向你借一头角鹰兽。', `FemaleText_loc5`='厄賽魯斯，卡薩蕊娜派我來向你借一頭角鷹獸。', `FemaleText_loc7`='Orseus, Kathrena me envió para pedirte uno de tus hipogrifos.' WHERE `ID`=34585;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샤둠브라의 혼을 불러낼 준비가 되었습니다.', `MaleText_loc4`='我已经准备好使用猎影之影了。', `MaleText_loc5`='我已經準備好召喚薩杜布拉之影。', `MaleText_loc7`='Estoy preparado para invocar la sombra de Shadumbra.', `FemaleText_loc1`='샤둠브라의 혼을 불러낼 준비가 되었어요.', `FemaleText_loc4`='我已经准备好使用猎影之影了。', `FemaleText_loc5`='我已經準備好召喚薩杜布拉之影。', `FemaleText_loc7`='Estoy preparado para invocar la sombra de Shadumbra.' WHERE `ID`=34586;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밖으로 나가 호드를 없애버리십시오!', `MaleText_loc4`='去摧毁部落！', `MaleText_loc5`='出去消滅部落!', `MaleText_loc7`='¡Sal afuera y destruye a la Horda!' WHERE `ID`=34587;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='레인나무 은신처로 돌아가십시오!', `MaleText_loc4`='返回林中树居！', `MaleText_loc5`='回到林中樹居!', `MaleText_loc7`='¡Regresa al Refugio de la Algaba!' WHERE `ID`=34588;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='흰꼬리사슴이 다시 전 지역에 서식하게 되었네요.', `FemaleText_loc4`='白尾鹿又开始在这个地区繁衍了。', `FemaleText_loc5`='白尾鹿正在這整個地區重新繁殖。', `FemaleText_loc7`='Los ciervos Coliblanca han estado repoblando esta zona.' WHERE `ID`=34589;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='불 때문에 일어난 상승 기류가 위험할 수 있으니 꽉 잡으세요.', `FemaleText_loc4`='稳住，火焰产生的上升气流非常猛烈。', `FemaleText_loc5`='等一下，大火的上升氣流可能會很強烈。', `FemaleText_loc7`='Cuidado, la corriente de los incendios puede ser muy fuerte.' WHERE `ID`=34590;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='달표범들이 불 때문에 쫓겨나 이 해안을 돌아다니고 있네요. 저들을 안전하게 지켜줘야 해요!', `FemaleText_loc4`='被烈火赶出家园的月夜猛虎正在这片海滩上游荡，我们需要保护它们！', `FemaleText_loc5`='月巡虎正被肆虐於這個海岸的大火吞噬，我們必須保護它們!', `FemaleText_loc7`='Los Acechalunas que han desplazado los incendios patrullan esta zona. ¡Debemos mantenerlos a salvo!' WHERE `ID`=34591;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아래를 보세요. 엉겅퀴곰 일부가 아직 잠식당하지 않았어요. 우리가 많이 늦진 않았군요.', `FemaleText_loc4`='看下面——还有一些蓟熊活着，我们来得还不算太晚。', `FemaleText_loc5`='看下面，有些薊熊還活著。我們還不算太遲。', `FemaleText_loc7`='Mira allí abajo. Todavía no se han consumido todos los osos cardos. Aún estamos a tiempo.' WHERE `ID`=34592;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='왜 누군가가 그리도 끔찍한 무언가를 파내길 원하는 거죠? 그런 일들은 이곳의 야생 동물들에게 일어나는 일과는 동떨어져 있다고 확신해요.', `FemaleText_loc4`='为什么会有人想要挖掘这么恐怖的东西？我相信就是这些东西导致了这里的动物们所遭遇的灾难。', `FemaleText_loc5`='為什麼有人要把這麼恐怖的東西挖出來?我確定那些東西一定與發生在這些動物身上的事情有關。', `FemaleText_loc7`='¿Por qué querría nadie desenterrar algo tan horrible? Estoy convencida de que esas cosas andan detrás de lo que les está sucediendo a los animales.' WHERE `ID`=34593;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘하셨어요! 한 번 더 돌아야 한다면 오르세우스에게 알려 주세요. 일을 마치셨으면 숲에서 다시 만나죠!', `FemaleText_loc4`='干得好！如果我们还需要再来一次，就去告诉奥修斯。如果不需要了，我会在那片树林中等你！', `FemaleText_loc5`='做得好!如果我們還需要轉一圈的話便跟厄賽魯斯說，不然我們就在樹林中再見!', `FemaleText_loc7`='¡Buen trabajo! Si necesitas que demos otra vuelta, díselo a Orseus. Si no, ¡te veré en la arboleda!' WHERE `ID`=34594;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='레인나무 은신처 아래에 있는 달샘을 이용하면 상처를 빠르게 회복할 수 있습니다.', `MaleText_loc4`='利用这棵树下的月亮井在离开战斗的情况下迅速恢复生命值。', `MaleText_loc5`='利用樹底的月井在非戰鬥狀態下迅速恢復生命。', `MaleText_loc7`='Usa la Poza de la Luna que hay en la base del árbol para recuperar salud rápidamente cuando estés fuera de combate.' WHERE `ID`=34595;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='감히 누가 나 아즈샤라에게 대항하느냐? 빨리 죽여달라고 애원하게 될 거다!', `FemaleText_loc4`='谁敢反对艾萨拉女王？你们很快就会求生不得，求死不能了！', `FemaleText_loc5`='誰敢反抗艾薩拉女王?你很快就會求生不得求死不能!', `FemaleText_loc7`='¿Quién osa oponerse a la reina Azshara? ¡No tardarás en suplicar por una muerte rápida!' WHERE `ID`=34596;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='포식자 요탈이 마지막 숨을 거두자 유물이 부서집니다.', `MaleText_loc4`='随着吞噬者尤萨尔呼出最后一口气，这件宝物碎裂了。', `MaleText_loc5`='神器在『吞噬者』尤薩爾咽下最後一口氣時碎裂了。', `MaleText_loc7`='El artefacto se rompe cuando Yoth''al el Devorador exhala su último aliento.' WHERE `ID`=34597;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아즈샤라, 다 끝났다! 나가를 이끌고 너희가 기어나온 바닷속 깊은 곳으로 돌아가라!', `MaleText_loc4`='都结束了，艾萨拉！带着你的纳迦回到属于你们自己的海底去。', `MaleText_loc5`='結束了，艾薩拉!妳和妳的納迦將回到屬於你們的海底深淵!', `MaleText_loc7`='¡Se acabó, Azshara! ¡Tú y tus nagas volverán al fondo de los mares adonde pertenecen!' WHERE `ID`=34598;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부하들이 위대한 소고스 님의 육신을 거의 꺼냈다. 의식은 준비됐나?', `MaleText_loc4`='发掘伟大的索苟斯的工作就要由我的人完成了。仪式已经准备好了吗？', `MaleText_loc5`='我們的人已經快將偉大的索苟斯掘出了。儀式準備好了嗎?', `MaleText_loc7`='Nuestros hombres casi han terminado de desenterrar al gran Soggoth. ¿El ritual está listo?' WHERE `ID`=34599;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아직이다. 고대 신의 사자들이 이 땅에 다시 발을 들이려면 희생의 공물이 많이 필요하다.', `FemaleText_loc4`='还没有，我们还需要大量的祭品才能让上古之神的使者重新降临这片大地。', `FemaleText_loc5`='還不太夠。我們需要更多的獻祭品讓古神的信使可以再次縱橫於這個大地。', `FemaleText_loc7`='No del todo. Necesitaremos una gran cantidad de ofrendas para el sacrificio antes de que el Heraldo de los dioses antiguos vuelva a caminar por la tierra.' WHERE `ID`=34600;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='걱정하지 마라. 내가 말했듯이 뱀신의 육신을 내 부하들이 거의 다 꺼내 가고 있다. 그들은 어울리는 곳으로 갈 거다. 게다가 자발적으로... 희생할 거고. 소고스 님께서 깨어나실 거다!', `MaleText_loc4`='别担心，就像我说的那样，我的部下即将完成伟大的深渊滑行者的挖掘工作。他们甚至可以成为最虔诚最完美的祭品。索苟斯必将崛起！', `MaleText_loc5`='別擔心。就像我所說的，我們的人再過不久就可讓巨痕者破土而出。他們將會是合適...也是自願的獻祭品。索苟斯即將降臨!', `MaleText_loc7`='No te preocupes. Como ya he dicho, nuestros hombres casi han terminado de desenterrar al serpenteante. Serán un sacrificio apropiado, incluso voluntario. ¡Soggoth se alzará!' WHERE `ID`=34601;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바람의 은총의 축복을 받고 가십시오. 알드랏실에서 더욱... 빨리 내려갈 수 있을 것입니다.', `MaleText_loc4`='接受风之拥抱的祝福吧。愿你从奥达希尔开始的旅程因这祝福而更加顺利。', `MaleText_loc5`='帶上風的祝福，接受它的擁抱。希望它能讓你啟程於奧達希爾的旅途更加的...順利。', `MaleText_loc7`='Lleva contigo la bendición del abrazo del viento. Que haga que tu descenso de Aldrassil sea más... directo.' WHERE `ID`=34602;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곰 인간이 싸워서 나무 도시 되찾은 것처럼 언젠가 케켁도 광란심장 일족 집에 데려갈 수 있을까? 케켁 우리 집 갖고 싶다. 보라색 인간들 많은 도시 말고, 날름이들 많은 정글도 말고.', `MaleText_loc4`='你相信总有一天，科科会带领狂心氏族回家，就像熊人赢得最终的胜利夺回树城那样。科科想要自己的家，而不是遍布紫人的城市，更不是大舌头怪出没的丛林。', `MaleText_loc5`='你覺得或許有一天，恰嘎會帶著狂心回到故鄉，像熊人一樣爭取他們的樹城嗎?恰嘎想要自己的家，不是有著紫色人的城市，不是有著大舌頭的叢林。', `MaleText_loc7`='¿Tú creer que algún día Kekek liderar a Corazón Frenético a casa? ¿Como hombres oso que luchan para recuperar la ciudad árbol? Kekek quiere su hogar, no una ciudad con hombres morados, ni una selva con lenguas-grandes.' WHERE `ID`=34603;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아스트라나르를 폭파해야 합니다! 대장 고가스 님께서 명령하셨습니다.', `MaleText_loc4`='我要轰炸阿斯特兰纳！这是高戈斯上尉的命令。', `MaleText_loc5`='我要轟炸阿斯特蘭納!這是戈加斯隊長的命令。', `MaleText_loc7`='¡Voy a bombardear Astranaar! Órdenes del Capitán Goggath.', `FemaleText_loc1`='아스트라나르를 폭파해야 합니다! 대장 고가스 님께서 명령하셨습니다.', `FemaleText_loc4`='我要轰炸阿斯特兰纳！这是高戈斯上尉的命令。', `FemaleText_loc5`='我要轟炸阿斯特蘭納!這是戈加斯隊長的命令。', `FemaleText_loc7`='¡Voy a bombardear Astranaar! Órdenes del Capitán Goggath.' WHERE `ID`=34604;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그나저나 우리가 왜 이런 걸 파내고 있는 거죠?', `MaleText_loc4`='头儿？为什么我们挖这种东西？', `MaleText_loc5`='話說...我們為什麼要挖這個東西，老大?', `MaleText_loc7`='De todas maneras, ¿por qué estamos excavando esta cosa, jefe?', `FemaleText_loc1`='그나저나 우리가 왜 이런 걸 파내고 있는 거죠?', `FemaleText_loc4`='头儿？为什么我们挖这种东西？', `FemaleText_loc5`='話說...我們為什麼要挖這個東西，老大?', `FemaleText_loc7`='De todas maneras, ¿por qué estamos excavando esta cosa, jefe?' WHERE `ID`=34605;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='봐봐! 저게 루야? 루 같은데... 좀 늙었다, 그치?', `MaleText_loc4`='看啊！那是我们吗？我们觉得那是我们。只是好像有一点老？', `MaleText_loc5`='看!那是我們嗎?我覺得那是我們耶。只是老了一些，對吧?', `MaleText_loc7`='¡Mira! ¿Somos nosotros? Me parece que somos nosotros. ¿Quizás algo mayores?' WHERE `ID`=34606;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위대한 자들이 루 축복해 줬나 봐! 제단이 루한테 마법 줘서 언젠가 대점쟁이 되게 해줄까? 그럴까?', `MaleText_loc4`='我们也许真的得到了造物主的祝福！也许有一天，圣坛的魔法会把我们变成大神谕者？', `MaleText_loc5`='我覺得我們受到偉大諸神的祝福了!祭壇發揮魔力，讓我們有天變成了高階神諭者?對吧?', `MaleText_loc7`='¡Parece que los Magnos bendecirnos! Los santuarios dar magia, ¿nos harán sumos Oráculos algún día? ¿Quizás?' WHERE `ID`=34607;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 벌레 같은 녀석, 그 입 조심해라. 뱀신 소고스 님을 "이런 것"이라 불러선 안 된다. 그러다가 네 심장이 저녁거리로 쓰이는 걸 보게 될 테니까 말이야.', `MaleText_loc4`='小心你的舌头，虫子。不要把伟大的索苟斯说成“东西”，否则你可要不得好死。', `MaleText_loc5`='注意你的用詞，蟲子。你要是再敢用「這個東西」來稱呼滑行者索苟斯，你就會發現晚餐吃的是你自己的心臟。', `MaleText_loc7`='Cuida esa lengua, gusano. No te referirás a Soggoth el Serpenteante como "esa cosa", o acabarás comiéndote tu propio corazón para cenar.' WHERE `ID`=34608;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 이제 다시 일하라고! 네 상관이 저 위에서 감시하고 있는데다가 일하지 않는 녀석을 그냥 놔두진 않을 테니까!', `MaleText_loc4`='赶快回去工作！大人们正在上面看着你，他们可不会对偷懒的人心慈手软！', `MaleText_loc5`='現在，回到你們的工作崗位上!你們的監督者正在上面看著，他們對偷懶的人沒有憐憫!', `MaleText_loc7`='¡Ahora vuevle al trabajo! ¡Nuestros superiores nos observan desde el mirador y no les gusta la holgazanería!' WHERE `ID`=34609;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저거 봐라! 케켁 무지 센 전사다! 보이지? 케켁이 뭐라고 하나?', `MaleText_loc4`='看啊！那一定是强大的战士科科！看到了吧？科科说什么来着。', `MaleText_loc5`='看!那一定是恰嘎成為一個偉大的戰士!看到了吧?恰嘎就跟你說嘛!', `MaleText_loc7`='¡Mira! ¡Eso tiene que ser Kekek como un poderoso guerrero! ¿Ves? ¿Qué decirte Kekek?' WHERE `ID`=34610;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='This is a temporary object, quest will use autolaunch.', `MaleText_loc4`='这是一个暂时目标。任务将自动加载。', `MaleText_loc5`='這是個臨時的物件，任務會自動啟動。', `MaleText_loc7`='This is a temporary object, quest will use autolaunch.' WHERE `ID`=34611;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='느껴지세요?$B$B망자의 날에 우리 곁으로 다가오는 영혼의 세계가 말이에요. 떠나 버린 사랑하는 이들의 무덤을 꽃과 촛불, 공물로 장식하는 이유가 바로 이거랍니다. 잠깐이라도 그들이 돌아오는 걸 축하하는 거죠.$B$B어서 오세요! 저랑 춤추시죠! 우리 곁을 떠났지만 이제 영혼이 되어 다시 나타난 이들을 추억하고 공경해요. 그들은 먹고 마시며 웃고, 우리가 그들을 사랑함을 느낄 거예요.', `FemaleText_loc4`='你能感觉到吗？$B$B灵魂世界在悼念日中距离我们更近了。所以我们要用鲜花和蜡烛装饰逝去亲友的坟墓，并告诉他们：欢迎回来，虽然只有片刻。$B$B所以，来吧！和我一起跳舞！让我们纪念那些已经和我们天人永隔的亲人。让逝者同我们一起享用美食，一起微笑。让他们知道，关爱永不逝去。', `FemaleText_loc5`='你感覺到了嗎?$B$B在亡者節的時候，靈魂的世界變得離我們更近。這也是為什麼我們要準備鮮花、蠟燭和供品，用來裝飾跟我們最親近死者的墳墓，儘管只有短短的時間，也要歡迎它們回來。$B$B來吧!跟我一起跳舞!讓我們一起榮耀死者，跟它們一起同樂，讓它們可以開懷吃喝和歡笑，讓它們知道依舊有人在愛著它們。', `FemaleText_loc7`='¿Lo notas?$b$bEl mundo de los espíritus está más cerca de nosotros durante la Festividad de los Muertos. Por eso decoramos las tumbas de aquellos que partieron y que quisimos con flores, velas y ofrendas: Para darles la bienvenida, incluso aunque regresen por un breve tiempo.$b$bAsí que, ¡vamos! ¡Baila conmigo! Mostremos a la fantasmal presencia de aquellos que hemos perdido nuestro cariño y respeto, para que puedan comer y beber y sonreír y saber que son amados.' WHERE `ID`=34612;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='망자의 날 기간에 사람들은 무덤에 모여 우리 곁을 떠난 영혼들을 기리고 추억합니다.$B$B대도시에 있는 모든 묘지에서 잔치가 열립니다. 거기서 요리하고, 춤추고, 특별한 복장을 입어 보실 수 있지요.', `MaleText_loc4`='在悼念日，人们会聚集在墓地，追忆、告慰那些逝者的亡魂。$B$B届时任何主城的墓地都会举行这个仪式，在那里有悼念日食品、舞蹈、化装聚会和其他活动。', `MaleText_loc5`='在亡者節的時候，人們聚集在墓園中慶祝，和親人的鬼魂一起同樂。$B$B你可以在各大主城的墓園發現慶典活動，你可以在那邊烹飪、跳舞、扮裝還有許許多多的活動。', `MaleText_loc7`='Durante la Festividad de los Muertos, la gente se reúne en los cementerios para rendir homenaje y mostrar afecto a los espíritus de aquellos que han partido.$b$bLas celebraciones pueden encontrarse en los cementerios de cualquier ciudad importante, donde podrás cocinar, bailar, lucir tus atuendos y más.', `FemaleText_loc1`='망자의 날 기간에 사람들은 무덤에 모여 우리 곁을 떠난 영혼들을 기리고 추억하지요.$B$B대도시에 있는 모든 묘지에서 잔치가 열린답니다. 거기서 요리하고, 춤추고, 특별한 복장을 입어 보실 수 있지요.', `FemaleText_loc4`='在悼念日，人们会聚集在墓地，追忆、告慰那些逝者的亡魂。$B$B届时任何主城的墓地都会举行这个仪式，在那里有悼念日食品、舞蹈、化装聚会和其他活动。', `FemaleText_loc5`='在亡者節的時候，人們聚集在墓園中慶祝，和親人的鬼魂一起同樂。$B$B你可以在各大主城的墓園發現慶典活動，你可以在那邊烹飪、跳舞、扮裝還有許許多多的活動。', `FemaleText_loc7`='Durante la Festividad de los Muertos, la gente se reúne en los cementerios para rendir homenaje y mostrar afecto a los espíritus de aquellos que han partido.$b$bLas celebraciones pueden encontrarse en los cementerios de cualquier ciudad importante, donde podrás cocinar, bailar, lucir tus atuendos y más.' WHERE `ID`=34613;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='악마 바위굴로 가기 전에 나무 꼭대기에 있는 탈론카이 스위프트루트와 대화해 보십시오. 탈론카이도 그대에게 부탁할 임무가 있는 것 같더군요.', `FemaleText_loc4`='在你进入地狱石之前，一定要同这棵树顶上的塔隆凯·捷根谈一谈。他也有一个任务要交给你。', `FemaleText_loc5`='在你啟程去惡魔石前，記得先跟樹頂上的塔隆凱·捷根說說話。他也有任務想拜託你。', `FemaleText_loc7`='Antes de dirigirte hacia Roca Mácula, acuérdate de hablar con Tallonkai Cruzarraíz en lo alto del árbol. También tiene una tarea que encomendarte.' WHERE `ID`=34614;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새 친구 생겼다!', `MaleText_loc4`='我们有了一个新朋友！', `MaleText_loc5`='我們有了一位新朋友!', `MaleText_loc7`='¡Hemos hecho una amistad nueva!' WHERE `ID`=34615;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우와!', `MaleText_loc4`='看！', `MaleText_loc5`='看!', `MaleText_loc7`='¡Mira!' WHERE `ID`=34616;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 재밌는 거 보여 줄까?', `MaleText_loc4`='想看看我能做些什么吗？', `MaleText_loc5`='想看看我能辦到什麼嗎?', `MaleText_loc7`='¿Quieres ver lo que sé hacer?' WHERE `ID`=34617;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='루도 춤출 줄 안다!', `MaleText_loc4`='我们也能跳舞！', `MaleText_loc5`='我們也可以跳舞!', `MaleText_loc7`='¡Nosotros también sabemos bailar!' WHERE `ID`=34618;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 같이 춤추자!', `MaleText_loc4`='一起来跳舞吧！', `MaleText_loc5`='現在一起來跳!', `MaleText_loc7`='Y ahora, ¡bailemos!' WHERE `ID`=34619;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와!', `MaleText_loc4`='看！', `MaleText_loc5`='看!', `MaleText_loc7`='¡Mira!' WHERE `ID`=34620;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제대로 맞혔다!', `MaleText_loc4`='你的样子还不错！', `MaleText_loc5`='砸到你啦!', `MaleText_loc7`='¡Te pillé!' WHERE `ID`=34621;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나도 맞혔다!', `MaleText_loc4`='你回来啦！', `MaleText_loc5`='還給你!', `MaleText_loc7`='¡Y yo a ti!' WHERE `ID`=34622;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='눈싸움 재밌었다!', `MaleText_loc4`='这场雪仗打得真精彩！', `MaleText_loc5`='精采的雪球戰!', `MaleText_loc7`='¡Buena pelea de bolas de nieve!' WHERE `ID`=34623;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하는 게 좋을걸!', `MaleText_loc4`='最好小心一些！', `MaleText_loc5`='最好當心點!', `MaleText_loc7`='¡Mejor que vigiles!' WHERE `ID`=34624;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='짐마차 코도를 방어하십시오!', `MaleText_loc4`='守卫科多兽商队！', `MaleText_loc5`='保護好商隊科多獸!', `MaleText_loc7`='¡Defiende al kodo de caravana!' WHERE `ID`=34625;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='짐마차 코도를 책임지고 지켜 주게!', `FemaleText_loc4`='领着他们！带他们出来！', `FemaleText_loc5`='保護好它們!將他們拉出去!', `FemaleText_loc7`='¡Adelante! ¡En marcha!' WHERE `ID`=34626;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 명예를 걸고 이 보급품을 십자로로 보내야만 하네. 도와주지 않을 거라면 물러나게나!', `FemaleText_loc4`='我要将这些物资运到十字路口，这事关我的荣誉。如果你不想帮忙，就站开一些。', `FemaleText_loc5`='我有責任把這些補給帶到十字路口。要不就幫我，要不就別煩我。', `FemaleText_loc7`='El honor me obliga a llevar estos suministros a El Cruce. Echa una mano o apártate.' WHERE `ID`=34627;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자, 한판 신나게 즐길 준비가 됐나, $n?', `FemaleText_loc4`='好吧，$n，准备好了吗？这可不容易啊！', `FemaleText_loc5`='很好，$n，準備好了嗎?這不是件簡單的差事!', `FemaleText_loc7`='¿Y bien, $n? ¿Estás $gpreparado:preparada;? ¡No va a ser fácil!' WHERE `ID`=34628;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 준비됐습니다. 어서 시작하죠!', `MaleText_loc4`='是的，我准备好了。让我们开始吧！', `MaleText_loc5`='是的，我準備好了。我們開始吧!', `MaleText_loc7`='Sí, lo estoy. ¡Vamos allá!', `FemaleText_loc1`='네, 준비됐습니다. 어서 시작하죠!', `FemaleText_loc4`='是的，我准备好了。让我们开始吧！', `FemaleText_loc5`='是的，我準備好了。我們開始吧!', `FemaleText_loc7`='Sí, lo estoy. ¡Vamos allá!' WHERE `ID`=34629;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어서 올라타게, $n! 날 실망시키지 말게나.', `FemaleText_loc4`='$n，上马！不要让我失望。', `FemaleText_loc5`='騎上來，$n!別讓我失望。', `FemaleText_loc7`='¡Sube, $n! No me falles.' WHERE `ID`=34630;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저게 용의 여왕님이야? 흠... 더 클 줄 알았는데. 응, 그럴 줄 알았어.', `MaleText_loc4`='她就是红龙女王？嗯……我们一直以为她应该更大一些。', `MaleText_loc5`='這就是群龍之后?嗯...我們以為她會更巨大呢。對呀，我們都這麼想。', `MaleText_loc7`='Así que, ¿esta es la reina de los dragones? Mmm... Pensábamos que sería más grande. Sí, lo pensábamos.' WHERE `ID`=34631;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 다른 용이랑 다르게 생겼어? 맘만 먹으면 크고 늙은 용으로 변신하는 거야?', `MaleText_loc4`='她怎么和其他的龙一点也不像？她真的可以变成一头巨大的龙吗？', `MaleText_loc5`='為什麼她看起來跟其他的龍不一樣?所以如果她想要的話，她也能變成一隻又大又老的龍嗎?', `MaleText_loc7`='¿Cómo es que no se parece al resto de los dragones? ¿Podría convertirse en un dragón grande y antiguo si quisiera?' WHERE `ID`=34632;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저어... 폐하, 용으로 변신해 주시면 안 돼요?', `MaleText_loc4`='嗯……尊贵的殿下，你愿意为我们变成一条龙吗？', `MaleText_loc5`='嗯...陛下，你願意為我們變成龍嗎?', `MaleText_loc7`='Um... Majestad, ¿te transformarías en dragón para nosotros?' WHERE `ID`=34633;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네... 그럼 지금은요?', `MaleText_loc4`='好啊……就现在吧？', `MaleText_loc5`='好吧...那現在呢?', `MaleText_loc7`='Bueno... ¿Qué tal ahora?' WHERE `ID`=34634;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내가 용 모습을 하고 있었다면, 비좁아서 아무도 여기 있지 못했을 거란다, 작은 자여.', `FemaleText_loc4`='如果我变回红龙形态。这里就装不下其他人了，小家伙。', `FemaleText_loc5`='如果我變回龍形，這裡恐怕就沒有空間容下其他人了，小不點。', `FemaleText_loc7`='Si estuviera en forma de dragón no habría espacio para nadie más, $gpequeño:pequeña;.' WHERE `ID`=34635;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠... 저 케켁 많이 늙었다. 광란심장 일족 지도자, 장로인가 보다. 이거 좋다. 케켁 미래 훌륭하다. 전사도 되고 지도자도 된다. 케켁 여기 데려와 줘서 행복하다. 원장 아줌마는 케켁한테 이런 거 안 해준다.', `MaleText_loc4`='嗯……那个科科已经非常老了。而狂心氏族的首领一定要更老一些。这很不错。作为战士和首领，科科有着美好的未来。科科很高兴你能带他参观这里。孤儿院的阿姨从不带科科来。', `MaleText_loc5`='嗯...那個恰嘎好老唷。一定是長老了，狂心部族的領袖。這真不賴。恰嘎在未來能成為戰士跟長老。恰嘎很高興你帶他來這裡。孤兒院女士從來都不會為恰嘎做這些。', `MaleText_loc7`='Hmm... ese Kekek muy viejo. Deber de ser anciano líder de Corazón Frenético. Kekek tener buen futuro como guerrero y líder. Kekek muy contento de que lo hayas traído aquí. Señorita de huérfanos nunca hacer eso por Kekek.' WHERE `ID`=34636;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엘룬께서 우릴 인도하시길, $c.', `MaleText_loc4`='艾露恩指引我们，$c。', `MaleText_loc5`='依露恩指引我們，$c。', `MaleText_loc7`='Que Elune nos guíe, $c.' WHERE `ID`=34637;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 적이 한 발자국이라도 전진하도록 둬서는 안 됩니다. 저들이 어둠해안을 습격하면, 바로 반격하여 놈들이 공격한 곳이 다르나서스인지 의심하게 만들어줄 겁니다.', `MaleText_loc4`='我们绝不能向敌人让出一寸土地。如果他们进攻黑海岸，我们就把他们打回去。我们要像保卫达纳苏斯一样保卫这里。', `MaleText_loc5`='我們絕對一步都不會讓。如果他們攻擊黑海岸，我們將奮力對抗，讓他們瞭解這於直接攻擊達納蘇斯沒什麼兩樣!', `MaleText_loc7`='No debemos ceder ni un poco ante el enemigo. Si atacan en Costa Oscura, lucharemos contra ellos como si hubieran atacado la propia Darnassus.' WHERE `ID`=34638;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='30초 후 전투가 시작됩니다.', `MaleText_loc4`='战斗将在30秒后开始。', `MaleText_loc5`='戰鬥將在30秒後開始。', `MaleText_loc7`='La batalla comenzará en 30 segundos.', `FemaleText_loc1`='30초 후 전투가 시작됩니다.', `FemaleText_loc4`='战斗将在30秒后开始。', `FemaleText_loc5`='戰鬥將在30秒後開始。', `FemaleText_loc7`='La batalla comenzará en 30 segundos.' WHERE `ID`=34639;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이미 늦었다... 그 유물은 우리가 얘기하는 바로 지금 아즈샤라 님께 바쳐지고 있다!', `MaleText_loc4`='你太迟了……当我们说话的时候，那件圣物已经被献给了艾萨拉！', `MaleText_loc5`='你遲了一步...在我們對話的同時聖物已經呈上去給艾薩拉了!', `MaleText_loc7`='Llegas demasiado tarde... ¡Mientras hablamos, están ofreciendo la reliquia a Azshara sobre nosotros!' WHERE `ID`=34640;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='길을 찾는 데 도움이 필요하신가요? 저는 이곳 지리를 아주 잘 알고 있답니다.', `FemaleText_loc4`='需要有人帮你找到路吗？我对这个地方可以说是了如指掌。', `FemaleText_loc5`='需要幫忙指路嗎?我對這個地方熟到不能再熟了。', `FemaleText_loc7`='¿Necesitas ayuda para encontrar el camino? Conozco este sitio como la palma de la mano.' WHERE `ID`=34641;
