UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안식의 룬은 남쪽 방 상부에 있는 다리 건너에 있습니다.', `FemaleText_loc4`='筑巢符文就在这座桥另一端，南边房间里的上层部分。', `FemaleText_loc5`='築巢符文位於橋的另一頭，南廳堂的上部區域。', `FemaleText_loc7`='La runa de nidal está al otro lado del puente, en la sección superior de la cámara sur.' WHERE `ID`=34650;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='천상의 사파이어는 북쪽 방의 아랫부분에 있는 별실에 있습니다.', `FemaleText_loc4`='天蓝之石就在北边房间里下层部分的小房间中。', `FemaleText_loc5`='天藍寶石位於另一個房間，在北廳堂的下部區域。', `FemaleText_loc7`='El zafiro de cielo se encuentra en una habitación individual en la sección inferior de la cámara norte.' WHERE `ID`=34651;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='검은 깃털은 남쪽 방의 아랫부분에 있는 경사로 밑에 있습니다.', `FemaleText_loc4`='黑色羽毛就在南边房间里下层部分的坡道尽头。', `FemaleText_loc5`='黑色羽毛位於南廳堂下部的坡道。', `FemaleText_loc7`='El cañón de pluma negra se encuentra al bajar la rampa en la sección inferior de la cámara sur.' WHERE `ID`=34652;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='까마귀 발톱 부적은 북쪽 방의 윗부분에 있는 절벽 위에 있습니다.', `FemaleText_loc4`='鸦爪神符就在北边房间里上层部分的露台上。', `FemaleText_loc5`='鴉爪咒符位於北廳堂上部的邊緣。', `FemaleText_loc7`='El dije de garra del Cuervo se encuentra en la cornisa de la sección superior de la cámara norte.' WHERE `ID`=34653;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오벤 레이지클로는 지하굴로 이어지는 복도 근처에 있는 서쪽 방의 이중 다리에 있습니다.', `FemaleText_loc4`='奥本·怒爪就在双桥之一所通向的西边房间里，靠近离开兽穴的走廊。', `FemaleText_loc5`='奧本·怒爪在西廳堂的雙重橋樑那，靠近獸穴往外的走道。', `FemaleText_loc7`='Oben Garrafuria reside en los puentes dobles de la cámara oeste, cerca del pasillo que sale del Túmulo.' WHERE `ID`=34654;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='케켁은 용의 여왕 보러 가는 줄 알았는데. 이건 그냥 웃기는 뿔 달린 엘프 여자다.', `MaleText_loc4`='科科还以为我们会看到红龙女王。但那只是个长着可爱犄角的女精灵。', `MaleText_loc5`='恰嘎覺得我們要去看龍后。就是那個頭上長著好笑尖角的精靈女士。', `MaleText_loc7`='Kekek pensar que íbamos a ver a reina de los dragones. Esto ser señora elfa con cuernos raros.' WHERE `ID`=34655;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드를 위하여!', `MaleText_loc4`='为了部落！', `MaleText_loc5`='為了部落!', `MaleText_loc7`='¡Por la Horda!', `FemaleText_loc1`='호드를 위하여!', `FemaleText_loc4`='为了部落！', `FemaleText_loc5`='為了部落!', `FemaleText_loc7`='¡Por la Horda!' WHERE `ID`=34656;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헬스크림 대족장님을 위하여!', `MaleText_loc4`='为了地狱咆哮酋长！', `MaleText_loc5`='為了大酋長地獄吼!', `MaleText_loc7`='¡Por el Jefe de Guerra Grito Infernal!', `FemaleText_loc1`='헬스크림 대족장님을 위하여!', `FemaleText_loc4`='为了地狱咆哮酋长！', `FemaleText_loc5`='為了大酋長地獄吼!', `FemaleText_loc7`='¡Por el Jefe de Guerra Grito Infernal!' WHERE `ID`=34657;
