UPDATE `locales_broadcast_text` SET `MaleText_loc1`='록타르 오가르!', `MaleText_loc4`='力量与荣耀！', `MaleText_loc5`='(獸人語)不勝即亡!', `MaleText_loc7`='¡Lok''tar ogar!', `FemaleText_loc1`='록타르 오가르!', `FemaleText_loc4`='力量与荣耀！', `FemaleText_loc5`='(獸人語)不勝即亡!', `FemaleText_loc7`='¡Lok''tar ogar!' WHERE `ID`=34661;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='골코시!', `MaleText_loc4`='以斧之名！', `MaleText_loc5`='古柯什!', `MaleText_loc7`='¡Gol''Kosh!', `FemaleText_loc1`='골코시!', `FemaleText_loc4`='以我斧头的名义！', `FemaleText_loc5`='古柯什!', `FemaleText_loc7`='¡Gol''Kosh!' WHERE `ID`=34662;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적들을 모두 죽이고 경비탑을 불태워라!', `MaleText_loc4`='把他们全干掉，烧掉他们的塔楼！', `MaleText_loc5`='殺光他們和燒毀他們的塔!', `MaleText_loc7`='¡Matadlos a todos y quemad su torre!', `FemaleText_loc1`='적들을 모두 죽이고 경비탑을 불태워라!', `FemaleText_loc4`='把他们全干掉，烧掉他们的塔楼！', `FemaleText_loc5`='殺光他們和燒毀他們的塔!', `FemaleText_loc7`='¡Matadlos a todos y quemad su torre!' WHERE `ID`=34663;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 왜? 용은 크고 강하다. 엘프 여자 약하다. 케켁은 용의 여왕 진짜 모습 보고 싶다.', `MaleText_loc4`='但这到底该怎样解释？龙巨大而强猛。精灵女士却弱不禁风。科科想要看到红龙女王真正的样貌。', `MaleText_loc5`='但為什麼?龍應該又大又強。精靈女士感覺好弱。恰嘎想看龍后真正的模樣。', `MaleText_loc7`='¿Pero por qué? Dragones grandes y poderosos. Señora elfa débil. Kekek querer ver verdadera forma de reina de los dragones.' WHERE `ID`=34664;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안심하라, 케켁. 용의 여왕이 맞다. 우리는 작은 존재를 상대할 때 종종 그들과 같은 모습을 취하기도 한다.', `MaleText_loc4`='放心吧，科科，她就是红龙女王。我们在和他们一同工作的时候，经常会变成更小的躯体。', `MaleText_loc5`='放心，恰嘎，她是群龍之后。我們常常使用較小種族的外型，尤其是我們要跟他們一起合作的時候。', `MaleText_loc7`='Puedes estar seguro, Kekek, de que ella es la reina de los dragones. A veces adoptamos la forma de seres más pequeños cuando trabajamos con ellos.' WHERE `ID`=34665;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오! 케켁 이제 알겠다. 큰 용 여자한테 깔리기 싫다. 사람 적을 때 다시 오던가 하자. 반가웠다, 용 여자.', `MaleText_loc4`='哦！现在科科明白了。科科不想被强大的女王捏扁。也许等这里不太挤的时候，科科还会回来。不管怎样，很高兴见到你，女王。', `MaleText_loc5`='喔!現在恰嘎懂了。恰嘎不想被龍女士給壓扁。也許下次沒那麼擁擠的時候再來。很高興見到你，龍女士。', `MaleText_loc7`='¡Oh! Ahora Kekek entender. No querer que gran señora dragón lo aplaste. Quizá volver otro día cuando no estar tan abarrotado. Encantado de conocer, señora dragón.' WHERE `ID`=34666;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훌륭하군! 나는 짐을 내리겠소. 어서 크라날 피스에게 보고하시오.', `MaleText_loc4`='干得好！我会负责卸货。你应该去找一趟卡纳尔·菲斯。', `MaleText_loc5`='做得太棒了!我會把物品搬下。你可以找卡納爾·菲斯登記。', `MaleText_loc7`='¡Un trabajo excelente! Yo descargaré los bienes. Deberías hablar con Kranal Fiss.' WHERE `ID`=34667;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 안개가 길을 알려줄 것입니다.', `FemaleText_loc4`='薄雾会引领道路。', `FemaleText_loc5`='迷霧將為你指路。', `FemaleText_loc7`='La niebla nos mostrará el camino.' WHERE `ID`=34668;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='출구는 북서쪽에 있습니다... 이 안개가 길을 안내해줄 것입니다.', `FemaleText_loc4`='出口在西北方……薄雾会引领道路。', `FemaleText_loc5`='出口在西北方...迷霧將會指引你。', `FemaleText_loc7`='La salida está al noroeste... La niebla nos mostrará el camino.' WHERE `ID`=34669;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='출구로 안내해 주시겠습니까?', `MaleText_loc4`='你能带我去出口吗？', `MaleText_loc5`='你可以帶我到出口嗎?', `MaleText_loc7`='¿Me puedes guiar a la salida?', `FemaleText_loc1`='출구로 안내해 주시겠어요?', `FemaleText_loc4`='你能带我去出口吗？', `FemaleText_loc5`='你可以帶我到出口嗎?', `FemaleText_loc7`='¿Me puedes guiar a la salida?' WHERE `ID`=34670;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 계속 가지 못하겠습니다... 철수해서 몸을 추슬러야겠군요.', `FemaleText_loc4`='我坚持不住了……我需要撤退，进行恢复。', `FemaleText_loc5`='我無法繼續了...我需要撤退恢復元氣。', `FemaleText_loc7`='No puedo seguir... Debo retirarme y recuperarme.' WHERE `ID`=34671;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와! 진짜 위대한 자야? 수세이가 진짜 위대한 자를 만났을 줄은 생각도 못했어!', `MaleText_loc4`='喔！真正的造物主？我们完全没有想到索乌塞遇到过一个真正的造物主！', `MaleText_loc5`='哇!一個真正的偉大之神?我們以為連蘇-楔都沒見過真正的偉大諸神!', `MaleText_loc7`='¡Guau! ¿Un Magno de verdad? Nos parece que ni Soo-pinstán se ha reunido con un Magno de verdad!' WHERE `ID`=34672;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음, 안녕하세요. 위대한 자님, 만나뵈어 영광이에요.', `MaleText_loc4`='呃，你好，造物主。见到你是我们的荣幸。', `MaleText_loc5`='嗯，你好，偉大之神先生。我們很榮幸能見到你。', `MaleText_loc7`='Um, hola, señor Magno. Es un honor.' WHERE `ID`=34673;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주무시나 봐요, 위대한 자님? 이해해요. 위대한 자님으로 저희가 바친 반짝이를 거두시려면 얼마나 피곤하시겠어요.', `MaleText_loc4`='你睡着了吗，造物主？我们知道，为了收集我们留给你的所有好东西，一定费了很大力气。', `MaleText_loc5`='或許你睡著了，偉大之神先生?我們瞭解。當個偉大之神一定是個辛苦的工作，收集那些我們獻給你的閃亮亮。', `MaleText_loc7`='¿Quizás duermes, señor Magno? Comprendemos. Ser Magno y coleccionar todos las cositas brillantes que dejamos debe ser trabajo duro.' WHERE `ID`=34674;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선물을 가져왔어요, 위대한 자님. 일어나면 보시겠지요. 저희가 만나러 온 것도 기억하시겠지요, 네?', `MaleText_loc4`='我们为你带来了一件礼物，造物主。也许你在醒来的时候会看到它。也许你会记得我们来看过你，是吗？', `MaleText_loc5`='我們帶了個禮物給你，偉大之神。說不定你醒來的時候就會看到。或許你會記得我們來看你，好嗎?', `MaleText_loc7`='Trajimos un regalo, señor Magno. Quizás lo veas cuando despiertes. Quizás recuerdes que vinimos a verte, ¿bueno?' WHERE `ID`=34675;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 납작코! 내 땅에서 떠나라!', `MaleText_loc4`='扁鼻子的垃圾！离开我的地盘！', `MaleText_loc5`='塌鼻的髒東西!滾出我的地盤!', `MaleText_loc7`='¡Alimañas de narices planas! ¡Fuera de mi propiedad!' WHERE `ID`=34676;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 탐욕스럽고 추악한 놈! 그 뒤룩뒤룩한 머리를 사과처럼 쪼개주마!', `MaleText_loc4`='该死的猪！你们的胖脑袋里只有一团肥肉！', `MaleText_loc5`='豬玀!雜碎!我會把你的肥腦像西瓜一樣打爛!', `MaleText_loc7`='¡Cerdos! ¡Escoria! ¡Rebanaré sus cabezotas como si fueran manzanas!' WHERE `ID`=34677;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 어금니를 뽑아 없애주마! 내 말 들었지??', `MaleText_loc4`='我会扯掉你们的獠牙，听到了吗？', `MaleText_loc5`='我會把你的獠牙連根拔起。你聽到了嗎?', `MaleText_loc7`='Te arrancaré los colmillos. ¿Me oyes?' WHERE `ID`=34678;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇지! 죽어라, 이 하찮은 놈! 호드가 이 일을 위해 네놈의 머리를 가져갈 것이다.', `MaleText_loc4`='没错！死吧，害虫！部落将彻底消灭你们。', `MaleText_loc5`='就是這樣!死吧，害蟲!部落會把你的頭給摘下來。', `MaleText_loc7`='¡Eso es! ¡Morid, alimañas! La Horda os arrancará la cabeza por esto.' WHERE `ID`=34679;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈을 머리부터 집어삼켜 주겠다!', `MaleText_loc4`='你们在我的手里根本不堪一击！', `MaleText_loc5`='我會扯下你的頭和嚼爛你那骯髒的臉!', `MaleText_loc7`='¡Les ARRANCARÉ las cabezas y me COMERÉ SUS SUCIAS CARAS!' WHERE `ID`=34680;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 울부짖어라, 이 벌레 같은 놈. 네놈을 죽이고 나면 내가 몸소 화장시켜 주마!', `MaleText_loc4`='没错，你们这帮只知道尖叫的害虫。我现在倒是很想吃烤猪肉！', `MaleText_loc5`='就是這樣，尖叫吧，你們這些蟲子。當我處理完後我會把你們劈成兩半然後烤成肉餅!', `MaleText_loc7`='Eso es, chillad, gusanos. ¡Os rajaré de arriba abajo, y cuando haya acabado os asaré!' WHERE `ID`=34681;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무도 내 가축을 훔칠 수 없다!', `MaleText_loc4`='没有人能偷走我的牲畜！', `MaleText_loc5`='不准偷我的家畜!', `MaleText_loc7`='¡Nadie roba mi ganado!' WHERE `ID`=34682;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도끼나 먹어라! 이 멍청한 돼지 같은 놈아!', `MaleText_loc4`='你们这些猪排原料，吃我的斧头吧！', `MaleText_loc5`='吃我的斧頭吧，你這培根腦豬排!', `MaleText_loc7`='¡Tomad hacha, jamones con cerebro de mosquito!' WHERE `ID`=34683;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='친구와 가족을 다시 만나 함께 축하하며 옛 이야기를 나누니 참 좋군요.', `MaleText_loc4`='能够再度和亲友一起欢庆，彼此分享旧日的故事，这种感觉实在太好了。', `MaleText_loc5`='能再回來看看朋友與家人真好，歡慶並且分享古老的故事。', `MaleText_loc7`='Es bueno volver a estar con los amigos y la familia, pasarlo bien y compartir historias antiguas.', `FemaleText_loc1`='친구와 가족을 다시 만나 함께 축하하며 옛 이야기를 나누니 참 좋네요.', `FemaleText_loc4`='能够再度和亲友一起欢庆，彼此分享旧日的故事，这种感觉实在太好了。', `FemaleText_loc5`='能再回來看看朋友與家人真好，歡慶並且分享古老的故事。', `FemaleText_loc7`='Es bueno volver a estar con los amigos y la familia, pasarlo bien y compartir historias antiguas.' WHERE `ID`=34684;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와아. 드디어, 케켁 헤멧 네싱워리 만났다!', `MaleText_loc4`='喔！科科终于找到赫米特·奈辛瓦里了！', `MaleText_loc5`='哇喔。恰嘎終於可以見到赫米特·奈辛瓦里了!', `MaleText_loc7`='Guau. ¡Al fin Kekek consigue conocer a Hemet Nesingwary!' WHERE `ID`=34685;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 숄라자르에 온 다음에 광란심장 일족까지도 소문이 쫙 퍼졌다. 비결이 뭔지 케켁한테 알려줘라, 응?', `MaleText_loc4`='在你来到索拉查以后，就连狂心氏族也知道了你的事情。也许你能教科科两招？', `MaleText_loc5`='就算是狂心部族也知道你來休拉薩之後的事蹟。說不定你能教教恰嘎你的技巧?', `MaleText_loc7`='Incluso los Corazón Frenético saben todo sobre ti después de que llegarás a Sholazar. A lo mejor poder enseñar tus trucos a Kekek.' WHERE `ID`=34686;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='글쎄다, 꼬마야. 먼저 ''가시덤불 골짜기의 푸른 언덕''을 읽어 보면 어떨까. 그러고 나면 우리 탐험대에 들어올 수도 있을 거야. 어때?', `MaleText_loc4`='好啊，小伙子，你可以从阅读《荆棘谷的青山》开始。然后，也许你能和我一同参加行动，你觉得如何？', `MaleText_loc5`='嗯，小夥子，你可以從讀一讀《荊棘谷的青山》開始。然後，或許你能加入我的一個狩獵隊。你意下如何?', `MaleText_loc7`='Bueno, colega, puedes empezar leyendo Las verdes colinas de Tuercespina. Luego quizás puedas venir conmigo a uno de mis safaris. ¿Qué dices?' WHERE `ID`=34687;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='읽는다고 뭐가 달라지는지 모르겠다. 케켁은 글 못 읽는데. 헤멧 네싱워리가 그렇게 말한다면, 케켁 해볼 거다.', `MaleText_loc4`='科科不知道阅读有什么用。科科不会阅读，但如果赫米特·奈辛瓦里要科科这样做，科科就会努力去做。', `MaleText_loc5`='不知道閱讀為什麼會有幫助。恰嘎一個字也不認識，不過如果赫米特·奈辛瓦里這麼說，恰嘎願意試試看。', `MaleText_loc7`='No saber para qué servir leer, pero si Hemet Nesingwary decirlo, Kekek intentar.' WHERE `ID`=34688;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아마 포기하고 동물들에게 책을 집어던지겠지만, 시도는 해본다.', `MaleText_loc4`='也许你最终会彻底放弃，但现在，你还需要坚持。', `MaleText_loc5`='說不定會放棄，然後拿書丟動物，但會試試看。', `MaleText_loc7`='Quizás rendirse y tirar libro a animales, pero probar.' WHERE `ID`=34689;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 그물을 뚫고 나옵니다.', `MaleText_loc4`='%s挣破了网子。', `MaleText_loc5`='%s掙脫了網子!', `MaleText_loc7`='%s se libera de la red.' WHERE `ID`=34690;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 그물에 걸렸습니다!', `MaleText_loc4`='%s被捉住了！', `MaleText_loc5`='%s中了陷阱!', `MaleText_loc7`='¡%s está atrapado!' WHERE `ID`=34691;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<킁킁거리며> 겁쟁이는 이렇게 싸우나, $r?', `MaleText_loc4`='<喷鼻息>懦夫就是这么战斗的吗，$r！', `MaleText_loc5`='<哼氣>這就是懦夫的戰鬥方式，$r?', `MaleText_loc7`='<Bufido> ¿Es así como luchan los cobardes, $r?' WHERE `ID`=34692;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<이 멍청이를 때립니다.>', `MaleText_loc4`='<胖揍这个蠢货。>', `MaleText_loc5`='<把這蠢蛋關起來。>', `MaleText_loc7`='<Machaca a ese bobalicón.>', `FemaleText_loc1`='<이 멍청이를 때립니다.>', `FemaleText_loc4`='<胖揍这个蠢货。>', `FemaleText_loc5`='<把這蠢蛋關起來。>', `FemaleText_loc7`='<Machaca a ese bobalicón.>' WHERE `ID`=34693;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여사냥꾼 중 한 명이 이미 바네실 지하굴로 갔으니 그 안으로 들어가면 여사냥꾼을 찾을 수 있을 것입니다. 제 옆에 있는 시타 메이플하트에게 이야기하면 바네실 지하굴로 갈 탈것을 빌릴 수 있답니다.', `FemaleText_loc4`='我们的一些女猎人已经去过班尼希尔兽穴。当你在那里的时候，她们会找到你。去和辛塔瑞谈谈，从她那里取得坐骑吧。', `FemaleText_loc5`='我們的一些女獵手已經前往班奈希爾獸穴了。他們會在裡面與你碰面。去找希塔瑞來獲得一個到那的交通工具。', `FemaleText_loc7`='Algunas de nuestras cazadoras ya han llegado al Túmulo de Ban''ethil. Te encontrarán cuando entres. No dudes en hablar con Citarre para que te lleve allí.' WHERE `ID`=34694;
