UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 땅에 쓰러져 의식을 잃습니다.', `MaleText_loc4`='%s倒在地上，昏迷不醒。', `MaleText_loc5`='%s沉到了地上失去了意識。', `MaleText_loc7`='%s cae al suelo y se queda inconsciente.' WHERE `ID`=34707;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가시멧돼지들은 항상 야영지 주변의 음식이나 보급품을 뒤지며 먹을 것을 찾아 돌아다녔지만, 그놈들이 우리 농장이나 집을 직접 공격한다고요? 최근에 무언가가 가시멧돼지들을 미쳐 날뛰게 한 거예요.', `FemaleText_loc4`='那些野猪人总是在我们的营地边缘劫掠食物和供给物资。难道他们现在竟然直接对我们的农场和家园发动攻击了？他们这种疯狂的行为一定是有原因的。', `FemaleText_loc5`='野豬人一直都在掠奪我們營地外圍的食物和補給，但現在是直接襲擊我的的農田和農莊?不知什麼東西讓他們最近變得如此狂暴。', `FemaleText_loc7`='Los jabaespines siempre husmean como carroñeros en los límites de nuestros campamentos en busca de comida y suministros, pero ¿atacar directamente nuestras granjas y haciendas? Hace poco ha tenido que suceder algo que les ha empujado a actuar.' WHERE `ID`=34708;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='토그릭, 저 포로를 다시 깨워 주겠습니까?', `MaleText_loc4`='托格莉，你能再把这名囚犯弄醒吗？', `MaleText_loc5`='托格瑞克，你可以再把囚犯叫醒一次嗎?', `MaleText_loc7`='Togrik, ¿puedes despertar al prisionero de nuevo?', `FemaleText_loc1`='토그릭, 저 포로를 다시 깨워 주겠어요?', `FemaleText_loc4`='托格莉，你能再把这名囚犯弄醒吗？', `FemaleText_loc5`='托格瑞克，你可以再把囚犯叫醒一次嗎?', `FemaleText_loc7`='Togrik, ¿puedes despertar al prisionero de nuevo?' WHERE `ID`=34709;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<구슬 같은 검은 눈동자로 당신을 응시하는 가시멧돼지>', `MaleText_loc4`='<这头野猪人用他黑珠子一样的眼睛紧盯着你。>', `MaleText_loc5`='<野豬人用他閃亮的黑眼珠丁盯著你看。>', `MaleText_loc7`='<El jabaespín fija sus ojos negros, redondos y brillantes en ti.>' WHERE `ID`=34710;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<당신에게 코를 대고 움찔거리며 킁킁거리는 가시멧돼지>', `MaleText_loc4`='<这头野猪人抽着鼻子，一边哼哼，一边嗅着你。>', `MaleText_loc5`='<野豬人向你皺起鼻子噴了噴氣。>', `MaleText_loc7`='<El jabaespín arruga el hocico y resopla.>' WHERE `ID`=34711;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일이지, $r? 괜히 애쓰지 말라고.', `MaleText_loc4`='怎么样，$r？想干什么就干吧。', `MaleText_loc5`='現在怎樣，$r?放馬過來。', `MaleText_loc7`='¿Y ahora qué, $r? Inténtalo con todas tus fuerzas.' WHERE `ID`=34712;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 전사다, $n. <킁킁거리며>대군에다가 긍지도 높다.', `MaleText_loc4`='我们是骄傲的战士，$n。<哼哼>数量还很多。', `MaleText_loc5`='我們是戰士，$n。<哼了哼>我們有榮耀。', `MaleText_loc7`='Somos guerreros, $n.<Resopla> Muchos y orgullosos.' WHERE `ID`=34713;
