UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어린이 여러분, 얌전히 있어요! 계속 그런 식으로 행동하면 아무도 데려가지 않아요!', `FemaleText_loc4`='孩子们，请注意你们的行为！如果再这样胡闹，永远也不会有人收养你们的！', `FemaleText_loc5`='孩子，注意自己的行為!如果你們繼續這樣，沒有人會想要收養你們的!', `FemaleText_loc7`='¡Niños, compórtense! ¡Nadie querrá adoptarlos si siguen portándose así!' WHERE `ID`=34715;
