UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<킁킁거리며>에이, 왜 음식을 요리해서 주는 거야? 토르터스크님이 음식은 훔쳐서 날것으로 먹는 게 가장 맛있다고 말씀하셨단 말이야.', `MaleText_loc4`='嗯，<哼哼>为什么你要把这个肉煮熟？突牙告诉我们，生肉才最好吃。', `MaleText_loc5`='嗯嗯，<哼氣>你為什麼要把這肉煮熟?突獠說剛偷來的生肉是最好吃的。', `MaleText_loc7`='Mmm, <resopla>, ¿por qué cocinas esta carne? Tordiente siempre nos dice que la carne sabe mejor cuando la robamos y además está cruda.' WHERE `ID`=34728;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 이런. 내가 너무 많이 말했군!', `MaleText_loc4`='哦，我已经说得太多了！', `MaleText_loc5`='啊，我太多話了!', `MaleText_loc7`='¡Oh! ¡He hablado demasiado!' WHERE `ID`=34729;
