UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아욱! 얼굴은 안 돼!', `MaleText_loc4`='呼呼，不要打脸！', `MaleText_loc5`='嗯哼...別打臉!', `MaleText_loc7`='Umpf. ¡En la cara no!' WHERE `ID`=34732;
