UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아으으윽! 아무것도 말 못한다!', `MaleText_loc4`='嗷喔！我什么都不说！', `MaleText_loc5`='哼..噢..嗚!我死都不說!', `MaleText_loc7`='¡Oooh-oooh! ¡Yo no hablo a cambio de nada!' WHERE `ID`=34735;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 힘만 빼는 거야! 토르터스크님은 우리를 절대로 비밀을 말하지 않는 전사로 훈련시켰으니까.', `MaleText_loc4`='你在浪费你的力气！突牙训练过我们该如何咬紧牙关。', `MaleText_loc5`='你浪費你的力氣!突獠訓練過我們這些戰士，絕對不說。', `MaleText_loc7`='¡Te esfuerzas en vano! ¡Tordiente nos enseña a los guerreros a no irnos nunca de la lengua!' WHERE `ID`=34736;
