UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하... <킁킁> 오하하하! <킁킁> 에헤헤! 안 돼! 그만해! <킁킁> 헤헤헤헤! <숨을 내쉬며> 전투모병관 토르터스크님이 간지럼 태우는 건 어떻게 참아야 하는지 안 가르쳐 주셨단 말이야!', `MaleText_loc4`='哈哈，<哼哼>哈——喝！<哼哼>哈哈哈哈哈<哼哼><费力地喘息>嗬嗬！突牙长官从没有教过我们该如何应付这个！', `MaleText_loc5`='哈哈..<哼氣>哈..嘻嘻!<哼氣>哈...快停...哈哈<大聲哼氣><喘氣>哇哈哈哈!戰鬥大師突獠從沒給我們這方面的訓練!', `MaleText_loc7`='¡Jaja...! <Resopla> ¡Ja-jejeje! <Resopla> Jaja, no, basta, jaja. <RESOPLA> <Resuella> ¡Jejeje! ¡El maestro de batalla Tordiente nunca nos preparó para eso!' WHERE `ID`=34741;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 땅은 우리의 것이다!', `MaleText_loc4`='这片土地将是我们的！', `MaleText_loc5`='這片土地將會歸我們所有!', `MaleText_loc7`='¡Estas tierras serán nuestras!' WHERE `ID`=34742;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='토르터스크가 날카롭게 외치며 꿀꿀거립니다. 그리고 분노에 가득 차 킁킁거리며 부하들에게 지시를 내립니다.', `MaleText_loc4`='突牙吼叫着，喘着粗气，哼哼着，气恼地向他的部下发号施令。', `MaleText_loc5`='突獠邊下指令給他的屬下，邊生氣的吼叫，咕噥和哼氣。', `MaleText_loc7`='Tordiente ladra, gruñe y grita dando órdenes iracundas a sus seguidores.' WHERE `ID`=34743;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 서슬갈기 일족은... 반드시... 살아남아야만 한다...', `MaleText_loc4`='我们钢鬃……必须……繁衍下去……', `MaleText_loc5`='我們剃鬃...必須...活下去...', `MaleText_loc7`='Los Crines de Acero... debemos... sobrevivir.' WHERE `ID`=34744;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 부드럽게 웃습니다.', `MaleText_loc4`='%s微微一笑。', `MaleText_loc5`='%s輕柔地笑著。', `MaleText_loc7`='%s se ríe suavemente.' WHERE `ID`=34745;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알았소, 아포니. 내 마음엔 나눌 이야기가 넉넉하다오. 달숲에 있는 엘프들과 얘기해본 적이 있소?', `MaleText_loc4`='好的，奥伯妮。我有很多事情要说。你有没有和月光林地的精灵们交谈过？', `MaleText_loc5`='好吧，阿波尼。我已經準備好要分享這些事情。你跟月光林地的精靈談過嗎?', `MaleText_loc7`='Vale, Aponi. Puedo compartir algo de lo que tengo en mente. ¿Alguna vez has hablado con los elfos de Claro de la Luna?' WHERE `ID`=34746;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엘프들도 달의 여신에 대해 이야기한다는 거 아시오? 그들도 달빛을 믿지.', `MaleText_loc4`='精灵们都在谈论一位月亮女神，你知道她吗？他们非常重视月亮发出的光芒。', `MaleText_loc5`='精靈提過一個月之女神，你知道嗎?他們非常仰賴月亮所賜予的光亮。', `MaleText_loc7`='Los elfos hablan de una diosa luna, ¿lo sabías? Dan mucho valor a la luz de la luna.' WHERE `ID`=34747;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 그렇소. 둘의 유사점이 꽤 흥미롭더군. 게다가 슈할로건 엘프건, 드루이드라면 누구나 무샤의 빛을 불러낸다는 걸 모두 알고 있지 않소.', `MaleText_loc4`='就像她一样，我听到的非常有趣。众所周知的是，所有德鲁伊，无论是舒哈鲁还是精灵，都能召唤穆萨的月光。', `MaleText_loc5`='就像她一樣。我所聽到的事情中有著相當有趣的共通性。這對德魯伊來說並不是秘密，舒哈魯或精靈都一樣，能夠呼喚姆莎之光。', `MaleText_loc7`='Justo como ella. Los paralelismos que he escuchado son interesantes. Y no es un secreto que todos los druidas, tanto Shu''halo como elfos, pueden invocar la luz de Mu''sha.' WHERE `ID`=34748;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='글쎄. 하뮬은 우리를 잘 이끌었고, 나도 그에게서 너무나 많은 것을 배웠소. 전설에 따르면 태초에 드루이드는 우리 족속이었다지...', `MaleText_loc4`='我有些奇怪。伊哈缪尔一直在以他的睿智指引着我们。我从他那里学到了许多东西。而传说告诉我，起初，我们的人民全都是德鲁伊……', `MaleText_loc5`='我想，哈繆爾將我們帶領得很好，而我也從他身上學到很多。傳說中我們同胞在天地初開時便是德魯伊...', `MaleText_loc7`='Me pregunto. Hamuul nos ha guiado bien y he aprendido mucho de él. Las leyendas dicen que nuestra gente eran druidas al principio de los tiempos...' WHERE `ID`=34749;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='...그런데 하뮬의 가르침은 엘프도 이미 아는 것들이오. 나이트 엘프 말이오. 그들은 밤의 소생으로서, 달의 여신을 굳게 믿지.', `MaleText_loc4`='……但伊哈缪尔所教导的正是精灵们熟知的东西。暗夜精灵都是夜的生物，月亮女神是他们忠贞的信仰。', `MaleText_loc5`='...但是哈繆爾教導的是精靈的知識。夜精靈的知識。因為他們是夜晚的生物，所以特別崇敬月神。', `MaleText_loc7`='... pero lo que Hamuul enseña es lo que saben los elfos. Los elfos de la noche. Como criaturas de la noche, se centran en su diosa luna.' WHERE `ID`=34750;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니오! 아니오, 그렇지 않소. 그는 합당한 장로요. 대지모신의 두 눈 중 하나인 무샤는 우리를 지켜보지. 어떤 악의도 없이.', `MaleText_loc4`='不！不，不会那样的。他是一位好长者。穆萨是大地之母的一只眼睛。她看护着我们。这不是什么坏事。', `MaleText_loc5`='不!不，不是這樣的。他有十足的理由成為一位長老，姊妹。姆莎是大地之母的一隻眼睛，她看照著我們。這可不是什麼陰謀惡意。', `MaleText_loc7`='¡No! ¡Nada de eso! Es un ancestro por algo, hermana. Mu''sha es uno de los ojos de la Madre Tierra y cuida de nosotros. Eso no es siniestro.' WHERE `ID`=34751;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='프레이야가 가까운 아군을 치유하는 이오나의 선물 정수를 흡수합니다!', `MaleText_loc4`='弗蕾亚从艾欧娜尔的礼物中汲取精华，开始治疗周围的盟友！', `MaleText_loc5`='芙蕾雅吸取伊歐娜的贈禮的精華治療附近的盟友!', `MaleText_loc7`='¡Freya drena la esencia del Don de Eonar y sana a sus aliados cercanos!', `FemaleText_loc1`='프레이야가 가까운 아군을 치유하는 이오나의 선물 정수를 흡수합니다!', `FemaleText_loc4`='弗蕾亚从艾欧娜尔的礼物中汲取精华，开始治疗周围的盟友！', `FemaleText_loc5`='芙蕾雅吸取伊歐娜的贈禮的精華治療附近的盟友!', `FemaleText_loc7`='¡Freya drena la esencia del Don de Eonar y sana a sus aliados cercanos!' WHERE `ID`=34752;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러나 우리는 무엇보다도 조화를 이루고자 애쓰는 이들이오. 우리 전사들은 필요할 때만 싸운다오. 사냥꾼들은 부족에 필요한 걸 공급하고, 나머지는 자신을 위해 쓰지. 주술사는 정령을 인도하고, 또한 정령과 우리를 이어 준다오.', `MaleText_loc4`='但如果不全力维持世界的平衡，我们就没有任何存在的意义。我们的战士只有在需要的时候才会奔赴战场。我们的猎人只猎取族人生存所必需的野兽。而且每一头猎物身上的一切都会被我们妥善利用。我们的萨满则担负着引导与调和元素之力的重任。', `MaleText_loc5`='但如果我們的人民不為了平衡而努力，那我們就什麼都不是了。我們的戰士只在需要時才戰鬥。我們的獵人只拿取部族生活所需，在行動時他們全力以赴。薩滿負責指引以及對元素之靈的溝通。', `MaleText_loc7`='Pero no somos más que gente que busca el equilibrio. Nuestros guerreros solo luchan cuando hay necesidad. Nuestros cazadores solo toman lo necesario para que vivan las tribus y, cuando lo hacen, aprovechan todo lo que pueden. El chamán es un guía y un mediador con los espíritus elementales.' WHERE `ID`=34753;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한데 자연의 수호자인 우리 드루이드는, 만물에서 조화라는 핵심적인 면을 간과하는 게 아닌지 의구심이 들 때가 있소.', `MaleText_loc4`='当我们这些德鲁伊全力守护自然的时候，我怀疑我们是否忽略了一把维持世界万物平衡的钥匙。', `MaleText_loc5`='而我們，德魯伊，是自然的守護者，我在想如果我們能在所有事物中檢視出平衡的關鍵。', `MaleText_loc7`='Y aunque nosotros, como druidas, somos los guardianes de la naturaleza; me pregunto si hemos pasado por alto un aspecto clave del equilibrio en todas las cosas.' WHERE `ID`=34754;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니오, 아니오. 친구를 대접하느라 바쁘신 분을 학생이 뜬구름 잡는 소리로 방해할 수야 없겠지.', `MaleText_loc4`='不，不。不要在他招待朋友的时候用无聊的哲学问题去打扰他。', `MaleText_loc5`='不，不。不需要為了一個學生毫無焦點的哲學空談就去打擾他，尤其是他還在招待一位朋友。', `MaleText_loc7`='No, no. No es necesario molestar con la inmóvil filosofía de un alumno mientras recibe a un amigo.' WHERE `ID`=34755;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='딱히 새로운 사상도 아니라오, 자매여.', `MaleText_loc4`='嗯，这并不算是一个新主意，姐妹。', `MaleText_loc5`='嗯，這並非是個全新的想法，姊妹。', `MaleText_loc7`='Bueno, esto no exactamente un nuevo pensamiento, hermana.' WHERE `ID`=34756;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대도 학생이었던 시절이 있을 거요, $c|1이여;여;. 스승에게 가르침을 받고, 어떤 식으로든 그 스승에게 존경심도 품었겠지. 그렇지 않소? 인간적으로 존경스러운 이가 아니었더라도, 적어도 그대보다 많이 알며 그대를 가르치고자 애쓰는 존재였으니 말이오. 그런 적이 없다면, 한번 상상해 보시오...$b$b만약 스승이 생각보다 아는 게 적을지도 모른다고 느꼈다면, 그리고 그대는 더 나은 길을 찾을 수도 있을 것 같다면 어찌하겠소?', `MaleText_loc4`='$c，在你的一生中，你肯定有过一段做学生的时光。从导师那里学习知识，并想要为导师争光，对不对？我不是指具体的某个人，但导师肯定是比你知道更多，而且愿意教导你的人。不过，要不是这样呢？想象一下……$b$b如果你发现，你的导师所知道的也许并不如你想象的那样多，你也许能找到更好的办法提升自己，你又会怎样做？', `MaleText_loc5`='我很肯定在你的一生中一定當過學生，$c。你從一位指導者身上學習，某種程度上你會尊敬他們，對吧?或許不是一個人，但最起碼，有人瞭解得比你更多，而願意教導你。如果沒有的話，你也可以運用你的想像力...$b$b如果你最後發現，你的導師並不如你所想得全知全能，或許你會想到一條更好的道路?', `MaleText_loc7`='Seguro que en algún momento de tu vida fuiste un estudiante, $c. Aprendiste de un instructor y, de algún modo, comenzaste a respetarlo, ¿verdad? Quizá no como persona, pero al menos como alguien que sabía más que tú y estaba dispuesto a enseñarte. Si no, usa tu imaginación... $B$B¿Qué harías si te dieras cuenta de que tu instructor podría no saber tanto como pensabas y que tú has encontrado un camino mejor?' WHERE `ID`=34757;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='끔찍해요! 전 이렇게 쓸모없이 앉아만 있어서는 안 됩니다. 할 일이 얼마나 많은데! 노스렌드에서 이 팔을 다치지만 않았다면... 하긴, 그런 생각에 빠져 있을 필요는 없겠죠! 당신이 상처를 꿰매고 치료해 주실 테니까요. 그동안 우리는 이 근처에 도움의 손길을 펼치겠지요. 전방에 있지 않다고 도움을 제공할 방법이 없는 건 아니니 말입니다.', `FemaleText_loc4`='这可真糟糕！我不应该无所事事地坐在这里。需要我去做的事情实在太多了！要不是我的胳膊在诺森德受了伤……但现在抱怨这种事是没用的！塔胡会帮我包扎好，并治好我。虽然有伤，但是我们还能帮上点忙。

虽然不在前线，但这并不意味着我们就要混吃等死。', `FemaleText_loc5`='這太糟糕了!我根本不應該坐在這裡，一點用都沒有，有這麼多事情等著去做!要是我的手臂沒有在北裂境受傷...待在這裡根本沒有意義!塔胡會替我好好包紮最後我會痊癒，在這段期間我們會在這裡幫忙。

我們不在前線並不表示我們沒辦法幫忙。', `FemaleText_loc7`='¡Esto es terrible! No debería estar aquí sentada, inútil, cuando hay tanto que hacer. Si no hubiera sufrido lesiones en el brazo en Rasganorte... ¡Pero no vale la pena lamentarse! Tahu me curará y seguiremos ayudando por aquí mientras.

Que no estemos en el frente no significa que no podamos ayudar de algún modo.' WHERE `ID`=34758;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우적 우적 우적 우적...', `MaleText_loc4`='不，不，不，不，不……', `MaleText_loc5`='嚼嚼嚼嚼嚼...', `MaleText_loc7`='Ñam ñam ñam...' WHERE `ID`=34759;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기력을 회복한 코도가 먼지를 털어내며 제 발로 일어섭니다.', `MaleText_loc4`='恢复活力的科多兽站起来，摇晃掉身上的泥土。', `MaleText_loc5`='恢復體力的科多獸站了起來，將身上的灰塵甩掉。', `MaleText_loc7`='El kodo revitalizado se pone de pie, sacudiéndose el polvo.' WHERE `ID`=34760;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='또 새로운 분인가요? 만나서 반갑습니다. 저는 델리라라고 합니다.', `FemaleText_loc4`='又是一张新面孔？很高兴见到你，我是德林拉尔。', `FemaleText_loc5`='另一個新面孔?很高興見到你，我是德黎菈。', `FemaleText_loc7`='¿Otra cara nueva? Me alegro de conocerte. Me llamo Dellylah.' WHERE `ID`=34761;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='말해주십시오, 타후. 무슨 얘기든지요. 뭐라도요! 미칠 것만 같습니다.', `FemaleText_loc4`='和我聊聊，塔胡。随便和我说些什么。什么事都行！我要闷得发疯了。', `FemaleText_loc5`='跟我說話，塔胡。什麼事都好!我覺得我快瘋了。', `FemaleText_loc7`='Dime algo, Tahu. Cualquier cosa. Me estoy volviendo loca del todo.' WHERE `ID`=34762;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='별로요.', `FemaleText_loc4`='不是很多。', `FemaleText_loc5`='不多。', `FemaleText_loc7`='No mucho.' WHERE `ID`=34763;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무샤 같은 존재 말이죠.', `FemaleText_loc4`='就像穆萨一样。', `FemaleText_loc5`='如同姆莎。', `FemaleText_loc7`='Como Mu''sha.' WHERE `ID`=34764;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무슨 말씀을 하시려는 건가요?', `FemaleText_loc4`='你带着这个要去哪里？', `FemaleText_loc5`='你打算這樣去哪?', `FemaleText_loc7`='¿Adónde vas con esto?' WHERE `ID`=34765;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 "그런데"가 나오겠군요.', `FemaleText_loc4`='我听出了你要说“但是”……', `FemaleText_loc5`='我聽見你語氣中的「但是」...', `FemaleText_loc7`='Puedo escuchar un "pero" en tu voz...' WHERE `ID`=34766;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그의 가르침이 틀리다고 생각하십니까?', `FemaleText_loc4`='你觉得他的教导错了吗？', `FemaleText_loc5`='你覺得他的教導是錯誤的?', `FemaleText_loc7`='¿Crees que sus enseñanzas son erróneas?' WHERE `ID`=34767;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그래서 이 문제를 장로님에게 가져갈 생각이십니까?', `FemaleText_loc4`='那么，你打算把这个交给那位长者？', `FemaleText_loc5`='所以你要去跟長老講這件事?', `FemaleText_loc7`='Entonces, ¿se lo vas a comentar al ancestro?' WHERE `ID`=34768;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그렇겠죠. 하지만, 그대가 그리 어리석은 얘기를 한 것은 아닙니다.', `FemaleText_loc4`='我是这样想的。不管你怎么说，这并不傻。', `FemaleText_loc5`='我想是吧。儘管我覺得你說的並不蠢。', `FemaleText_loc7`='Supongo. Aunque eso que has dicho no es una tontería.' WHERE `ID`=34769;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무슨 생각에 찌푸리고 계신가요, 타후.', `FemaleText_loc4`='我看见你在沉思中紧皱双眉，塔胡。', `FemaleText_loc5`='我看見那思索的皺眉，塔胡。', `FemaleText_loc7`='Veo ese ceño fruncido pensativo, Tahu.' WHERE `ID`=34770;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭔가 마음에 걸리시는 거지요?', `FemaleText_loc4`='你心里有事情，对不对？', `FemaleText_loc5`='但你心裡有事，對吧?', `FemaleText_loc7`='Pero tienes algo en mente, ¿verdad?' WHERE `ID`=34771;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그곳에 대해 무슨 생각을요?', `FemaleText_loc4`='是什么？', `FemaleText_loc5`='怎麼了?', `FemaleText_loc7`='¿Qué pasa con eso?' WHERE `ID`=34772;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런 말이 있지요... "동트기 전이 가장 어둡다." 그래도 새벽은 옵니다, 타후. 해는 늘 떠올라요. 조화로움은 반드시 제자리를 찾을 겁니다.', `FemaleText_loc4`='有一句话说……“黎明前永远都是最黑暗的时刻。”但黎明就要到了，塔胡。太阳终将升起。一切都将回复平衡。', `FemaleText_loc5`='這是一個階段...「黎明之前總是最黑暗。」但黎明依舊會到來，塔胡。太陽將會昇起。平衡將會恢復到它應有的模樣。', `FemaleText_loc7`='Hay una frase..."La noche es más oscura antes del amanecer." El amanecer llegará, Tahu. El sol brillará. El equilibrio volverá a su sitio.' WHERE `ID`=34773;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 미소 지으며 북쪽을 가리킵니다.', `FemaleText_loc4`='%s微笑着，指了指北方。', `FemaleText_loc5`='%s微笑並指向北方。', `FemaleText_loc7`='%s sonríe y señala hacia el norte.' WHERE `ID`=34774;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저 빙하 위에도, 어둠을 뚫고 태양은 솟아오르고야 맙니다. 제겐 희망이 있어요, 타후. 상황이 아무리 암울해 보이더라도 우리는 이 난관을 극복하고 말 겁니다.', `FemaleText_loc4`='即使在荒凉的冰原上，阳光还是能透过昏黑的云幕。我的希望没有泯灭，塔胡。我想，我们能够取得最终的胜利，无论挡在我们面前的敌人是多么可怕。', `FemaleText_loc5`='儘管在那冰河之地，太陽依舊試圖從黑暗中窺透。我抱持著希望，塔胡。我想我們能夠達成這件事，不管它看來有多兇險。', `FemaleText_loc7`='Incluso en el propio glaciar, el sol consigue asomar entre la penumbra. Tengo esperanza, Tahu. Creo que sobreviviremos, no importa lo terrible que parezca.' WHERE `ID`=34775;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그러나 저는 믿음으로 자신을 위로하기보다는 최전선에 서고 싶어요. 그냥 눌러앉아서 상황이 나아지기를 바라고 있을 수만은 없습니다.', `FemaleText_loc4`='与其在空洞的信仰中寻求自我安慰，我宁可冲上前线。我们不能只是坐等希望变成现实。', `FemaleText_loc5`='但我寧願在前線上協助這件事情成功，而不是在這裡靠著信念安撫我自己。我們不能只呆坐這裡，然後希望它會發生。', `FemaleText_loc7`='Pero aun así preferiría estar en las líneas de frente ayudando a que ocurra en vez de intentar apaciguarme con creencias. No podemos quedarnos aquí sentados y esperar que ocurra.' WHERE `ID`=34776;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그리고 그런 희망으로, 우리 편은 전투에서 힘을 얻겠지요?', `FemaleText_loc4`='借助这个希望来加强我们的力量？', `FemaleText_loc5`='透過希望來強化我們同伴的戰鬥嗎?', `FemaleText_loc7`='¿Y a través de esa esperanza fortalecer a nuestro bando en la lucha?' WHERE `ID`=34777;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미안하오, 자매여. 그리 염려할 바는 아니오.', `MaleText_loc4`='抱歉，姐妹。这不值得担心。', `MaleText_loc5`='抱歉，姊妹。這沒什麼好擔心的。', `MaleText_loc7`='Lo siento, hermana. No es algo por lo que preocuparse.' WHERE `ID`=34778;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='북쪽 싸움터를 생각하고 있소. 그대가 그토록 돌아가고파 하는 곳 말이오.', `MaleText_loc4`='我正在考虑关于北方前线的问题。看样子，你正急不可待地要回到那里去。', `MaleText_loc5`='我在想著北地的前線。那個你一直急著想回去的地方。', `MaleText_loc7`='Estoy pensando en el frente del norte. Ese al que tienes tantas ganas de regresar.' WHERE `ID`=34779;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아포니, 나는 그대에게 인내하라고 조언하지. 그러나 사실은 나도 그대만큼 여기 머무르는 것이 싫소. 이 어두운 시대에, 어쩌면 내가 한가하게 놀리는 이 손이 전세를 뒤집을 수도 있다고 생각하면 마음이 편치 않소.', `MaleText_loc4`='奥伯妮，我一直在劝你要保持耐心，但现在我和你一样讨厌呆在这里。这里的时光乏味无趣。这种无所事事的状态最终也许会逼迫我彻底改变这里的一切。', `MaleText_loc5`='我知道我在叫你耐心點，阿波尼，我就跟你一樣也不想待在這裡。情況越來越嚴峻，而且沒有辦法行動只讓我更加擔心，若是我沒有袖手旁觀，也許便能挽回頹勢。', `MaleText_loc7`='Sé que estoy aconsejando que seas paciente, Aponi, pero quedarme aquí me gusta tan poco como a ti. Son tiempos duros y quedarme sin hacer nada solo hace que me pregunte si mi mano inmóvil podría haber sido la que cambiara las tornas.' WHERE `ID`=34780;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만... 세상 만물은 조화를 이루는 법이오. 심지어 죽음까지도. 나는 그곳의 파괴와 죽음이 필요한 일일지도 모른다는 생각 자체가 끔찍하다오.', `MaleText_loc4`='万物皆有平衡，死亡亦然。我痛恨那种认为破坏和黑暗也是一种合理存在的想法。', `MaleText_loc5`='然而...所有事物中依舊存在著平衡，連死亡也不例外。但我只是厭惡這種「毀滅與黑暗也是必要的」的觀念。', `MaleText_loc7`='Pero aún... hay equilibrio en todas las cosas, incluso en la muerte. Es solo que odio el concepto de que tanta destrucción y oscuridad sean necesarias.' WHERE `ID`=34781;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='냠냠... 인간이 집에서 만든 음식만한 게 없지.', `MaleText_loc4`='嗯……还是人类烹调的食物好吃。', `MaleText_loc5`='嗯...沒有東西比得上家裡自己煮的人類佳餚了。', `MaleText_loc7`='Mmmmm... No hay nada como la comida casera humana.' WHERE `ID`=34782;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나도 아오, 자매여. 우리는 언젠가 싸우러 돌아갈 것이오. 그러나 지금은... 그대의 희망을 널리 전파하는 게 최선이오.', `MaleText_loc4`='我知道，姐妹，我知道。总有一天，我们会重返战场。但现在，我们最应该做的也许是将这个消息传递给其他人……让他们拥有和你一样的希望。', `MaleText_loc5`='我懂，姊妹。我懂。我們有一天會回去參戰。但只是現在，最好把這些話告訴其他人...讓他們擁有像你一樣的希望。', `MaleText_loc7`='Lo sé, hermana. Lo sé. Algún día volveremos a la lucha. Pero de momento, quizá sea mejor extender la palabra... darles la esperanza que tienes tú.' WHERE `ID`=34783;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 그거요.', `MaleText_loc4`='就是这样。', `MaleText_loc5`='就是這樣。', `MaleText_loc7`='Esa es la idea.' WHERE `ID`=34784;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사실 거짓말이오. 이 한심한 음식은 끔찍한 냄새가 나오. 하지만, 이 마을에서 풍겨올 냄새에 비하면 아무것도 아니지!', `MaleText_loc4`='我骗了你。你这烂食物正在散发着臭气。但这城市更加臭不可闻！', `MaleText_loc5`='我說謊。你那可悲的食物真是糟糕透頂，不過還沒有這個城鎮這麼臭!', `MaleText_loc7`='Mentí. Tu miserable comida apesta, ¡pero no tanto como apestará esta ciudad!' WHERE `ID`=34785;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이보시오! 도대체 무슨 생각으로 이러는 거요?', `MaleText_loc4`='嘿！你以为你在干什么？', `MaleText_loc5`='嘿!你以為你在做什麼?', `MaleText_loc7`='¡Oye! ¿Qué crees que estás haciendo?' WHERE `ID`=34786;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시는 하지 마시오!', `MaleText_loc4`='不要再这样了！', `MaleText_loc5`='別再來了!', `MaleText_loc7`='¡Otra vez no!' WHERE `ID`=34787;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그늘 협곡은 좋지 않은 일도 있지만, 이 숲으로 가는 건 마치 집으로 돌아가는 것 같습니다.$B$B언제나 평화롭고 순수하니까요.', `FemaleText_loc4`='我知道，幽影谷的状况并不好。但回到这片森林总是让我有一种回家的感觉。$B$B这里永远都是安宁而纯净的。', `FemaleText_loc5`='我知道幽影谷的情況不太好，但回到這片森林就像是回到家一樣。$B$B永恆的寧靜，永恆的純潔。', `FemaleText_loc7`='Sé que no todo va bien en Cañada Umbría, pero volver a estos bosques siempre es como volver a casa.$b$bSiempre tranquilos. Siempre puros.' WHERE `ID`=34788;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='깃발 없음', `MaleText_loc4`='清空旗帜', `MaleText_loc5`='無錦旗', `MaleText_loc7`='Ninguna grímpola', `FemaleText_loc1`='깃발 없음', `FemaleText_loc4`='清空旗帜', `FemaleText_loc5`='無錦旗', `FemaleText_loc7`='Ninguna grímpola' WHERE `ID`=34789;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호오, $n! 내 형인 발고르 휩섕크가 당신이 코도 등 뒤에서 실력발휘 좀 했다더군. 천리길 경비초소에서 이곳으로 짐마차를 무사히 호위하느라 수고했소.$B$B잘 들어보시오, 이곳 그롤돔에는 당신이 할 일이 아주 많이 있다오... 그렇지만 당신의 그 멋진 솜씨를 가진 집게손가락으로 십자로까지 나머지 호위를 부탁하겠소.$B$B준비가 되면 내게 오시오!', `MaleText_loc4`='哦，$n！我的兄弟巴尔格告诉我，你在科多兽背上的表现可谓是百发百中。这支运输队能从前沿哨所安全地来到这里，你可是立了一大功。$B$B听着，我知道你在格罗多姆还有很多工作要做……不过我更希望你能够继续护送运输队前往十字路口。$B$B做好准备以后再来找我吧！', `MaleText_loc5`='嘿，$n!我兄弟巴爾苟跟我說你對騎科多獸很有一手。把車隊從前沿哨所護送到這裡幹得太漂亮了。$B$B格羅多姆有蠻多事情可以做的...但你的板機指可以有效地幫我把剩下的東西運到十字路口。$B$B準備好了就來見我吧!', `MaleText_loc7`='¡Eh, $n! Mi hermano Balgor me dice que demuestras gran puntería desde el lomo de un kodo. Has hecho un buen trabajo al conseguir traer la caravana desde la Avanzada del Puente de una pieza.$B$BEscucha, en Grol''dom hay un montón de trabajo para ti... Pero podrían venirme bien tus ágiles dedos en el gatillo durante el resto del viaje hasta El Cruce.$B$B¡Ven a verme cuando quieras partir!' WHERE `ID`=34790;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오그리마에서 십자로로 장비와 식량을 수송하는 일은 원래 일꾼들이 하던 일이었지. 지금은 내 목이 달린 일이 되었지만 말이네.', `MaleText_loc4`='我曾经不断地将各种辎重和食物从奥格瑞玛拖送到十字路口，那可是件繁重的工作。现在我的脖子总会因为那时的劳累而隐隐作痛。', `MaleText_loc5`='把裝備和食物從奧格瑪運到十字路口曾經是苦工們做的工作。現在...我每次都必須自己來。', `MaleText_loc7`='Antes solía dedicarme a llevar equipamiento y comida desde Orgrimmar hasta El Cruce, sí, era un trabajo de peón. Ahora siempre estoy arriesgándose el cuello.' WHERE `ID`=34791;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하이잘 산 전투 이후로 우리 나이트 엘프는 많은 변화를 겪었습니다.', `MaleText_loc4`='自从海加尔山之战以来，我们的族人已经改变了许多。', `MaleText_loc5`='海加爾山戰役之後對我們的人民有很大的影響。', `MaleText_loc7`='Mucho ha cambiado para nuestra gente desde la Batalla del Monte Hyjal.' WHERE `ID`=34792;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놀드랏실의 힘은 아키몬드와 불타는 군단을 쓰러뜨리는 데 쓰였지요. 이제 놀드랏실은 옛 세계수의 희미한 그림자에 불과합니다.', `MaleText_loc4`='诺达希尔的力量曾经败过阿克蒙德，击退了燃烧军团的入侵，但它只剩下了一个苍白的影子。', `MaleText_loc5`='諾達希爾跟過去比起來只是一片白影，它的力量全被用來擊退阿克蒙德和燃燒軍團。', `MaleText_loc7`='Nordrassil no es más que una sombra de lo que era, su poder se usó para derrotar a Archimonde y hacer retroceder a la Legión Ardiente.' WHERE `ID`=34793;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 나이트 엘프는 우리 존재의 핵심인... 불사의 삶을 잃었습니다.', `MaleText_loc4`='我们的不朽力量，我们的生命的精华——已经丢失了。', `MaleText_loc5`='我們的不朽之身，我們存在的精粹!...已經消失了。', `MaleText_loc7`='Perdimos nuestra inmortalidad, la misma esencia de nuestro ser.' WHERE `ID`=34794;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배신자는 감옥에서 풀려났고, 샨도 스톰레이지는 에메랄드의 꿈속으로 자취를 감추었지요.', `MaleText_loc4`='那名叛徒已经离开了他的牢狱，大导师怒风则消失在翡翠梦境里。', `MaleText_loc5`='背叛者重獲了自由，而尊師怒風消失於翡翠夢境之中。', `MaleText_loc7`='El Traidor fue liberado de su prisión y Shand''do Tempestira desapareció en el sueño Esmeralda.' WHERE `ID`=34795;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두에게 힘든 시기입니다.', `MaleText_loc4`='这是一个黑暗的时代。', `MaleText_loc5`='所有人的黑暗時期。', `MaleText_loc7`='Tiempos oscuros para todos.' WHERE `ID`=34796;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말퓨리온 스톰레이지가 사라지면서 드루이드는 구심점을 잃었고, 새 지도자가 절실히 필요해졌습니다.', `MaleText_loc4`='随着玛法里奥·怒风的离开，德鲁伊陷入混乱，迫切需要一名新的领导者。', `MaleText_loc5`='在瑪法里恩·怒風離開之下，德魯伊們變的混亂，極度迫切需要一位新的領袖。', `MaleText_loc7`='Cuando Malfurion Tempestira desapareció, los druidas quedaron desorientados, necesitaban un nuevo líder desesperadamente.' WHERE `ID`=34797;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이때 대드루이드 판드랄 스태그헬름이 흩어진 드루이드를 규합하고, 우리 동족을 다시 일으킬 때라며 어둠해안에 있는 고대정령의 의회를 설득했지요.', `MaleText_loc4`='大德鲁伊范达尔·鹿盔唤醒了德鲁伊，并说服黑海岸的古树议会，让他们相信现在正是吾族重建之时。', `MaleText_loc5`='大德魯伊范達爾·鹿盔站了出來，說服了黑海岸的古樹議會，讓他們知道是時候讓我們的人民進行重建了。', `MaleText_loc7`='El archidruida Fandral Corzocelada despertó a los druidas y convenció al Círculo de los Ancestros de Costa Oscura de que era hora de que nuestro pueblo empezara a reconstruir.' WHERE `ID`=34798;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='의회의 허가 아래, 스태그헬름과 가장 강력한 드루이드들이 힘을 합쳐 지금 그대가 딛고 선 거대한 나무, 텔드랏실을 길러냈습니다. 불사의 삶을 되찾고자 함이었지요.', `MaleText_loc4`='为了让我族重新获得不朽，在得到议会的同意之后，鹿盔率领最强大的德鲁伊们培育出泰达希尔。你正站在它的枝干上。', `MaleText_loc5`='為了讓我們重拾不朽之身，在古樹議會的認可下，鹿盔和能力最強的德魯伊們種下了泰達希爾，也就是你腳下所支撐你的這棵樹。', `MaleText_loc7`='En un esfuerzo por recuperar la inmortalidad de nuestra gente, y con la aprobación del Círculo, Corzocelada y los druidas más poderosos cultivaron Teldrassil, sobre cuyas ramas te encuentras.' WHERE `ID`=34799;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러나 우리는 새로운 고향은 얻었지만, 불사의 삶을 되찾지는 못했습니다.', `MaleText_loc4`='虽然我们已经有了新的家园，我们不朽的生命却依然没有得到恢复。', `MaleText_loc5`='我們雖然有了新的家園，卻沒有重拾不朽之身。', `MaleText_loc7`='Aunque tenemos un nuevo hogar, no hemos recuperado nuestras vidas inmortales.' WHERE `ID`=34800;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대드루이드는 용의 위상들에게 그들이 고대에 놀드랏실에 내려주었던 축복을 부탁했습니다.', `MaleText_loc4`='大德鲁伊造访了巨龙，祈望他们的祝福新生的生命之树，就如同他们在上古时代祝福诺达希尔那样。', `MaleText_loc5`='大德魯伊去找巨龍們請求他們的祝福，就像巨龍們在遠古時期賜予了諾達希爾祝福一樣。', `MaleText_loc7`='El archidruida solicitó sus bendiciones a los dragones, porque estos se las habían otorgado a Nordrassil en el pasado.' WHERE `ID`=34801;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러나 시간의 지배자 노즈도르무는 대드루이드의 오만함을 꾸짖으며 축복을 내려주길 거부했지요.', `MaleText_loc4`='时光之王诺兹多姆拒绝给予他的祝福，并谴责了德鲁伊的傲慢。', `MaleText_loc5`='但諾茲多姆，時光之王，拒絕提供他的祝福，斥責德魯伊們的傲慢自大。', `MaleText_loc7`='Pero Nozdormu, el Señor del Tiempo, se negó a otorgar su bendición, y reprendió al druida por su arrogancia.' WHERE `ID`=34802;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알렉스트라자도 같은 이유로 스태그헬름의 부탁을 거절했고, 그녀의 축복을 받지 못한 텔드랏실은 제대로 자라나지 못했습니다.', `MaleText_loc4`='但为了遵守上古的契约，阿莱克丝塔萨也拒绝了鹿盔。没有她的祝福，泰达希尔的成长出现了无可预期的瑕疵。', `MaleText_loc5`='雅立史卓莎的看法與諾茲多姆一樣，她也同樣拒絕了鹿盔的請求。而因為沒有得到雅立史卓莎的祝福，泰達希爾的成長出現了瑕疵和未預料到的問題。', `MaleText_loc7`='De acuerdo con él, Alexstrasza también rechazó a Corzocelada y sin su bendición, el crecimiento de Teldrassil ha sido defectuoso e impredecible.' WHERE `ID`=34803;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스태그헬름은 다르나서스로 돌아올 수밖에 없었고, 이후로 그는 텔드랏실에 축복을 내리고 우리 종족의 영생을 되찾을 방법을 끊임없이 찾았습니다.', `MaleText_loc4`='鹿盔回到了他在达纳苏斯的领地里，开始寻找能够祝福泰达希尔，让我族恢复不朽的新方法。', `MaleText_loc5`='鹿盔撤回了他在達納蘇斯的營地，不斷地尋求新的方向來為泰達希爾求得祝福，重拾夜精靈的不朽之身。', `MaleText_loc7`='Corzocelada se retiró a su enclave en Darnassus, buscando una nueva forma para bendecir a Teldrassil y recuperar la inmortalidad de nuestra gente.' WHERE `ID`=34804;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세월이 흐르며 스태그헬름은 점점 더 동족과 멀어졌습니다.', `MaleText_loc4`='随着时光的推移，鹿盔只是同我们的族人变得越来越疏离。', `MaleText_loc5`='隨著時間的流逝，鹿盔與我們的距離越來越遠。', `MaleText_loc7`='Con el tiempo, Corzocelada acabó alejándose más y más de nuestra gente.' WHERE `ID`=34805;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스태그헬름이 오래전 흐르는 모래의 전쟁에서 아들을 잃은 책임을 바로 우리, 그의 동족에게 돌리고 있다는 소문도 들렸지요.', `MaleText_loc4`='有些人认为他在责怪我们，责怪他的族人。因为他在很久以前的流沙之战中失去了儿子。', `MaleText_loc5`='有些人指出他埋怨我們，埋怨他自己的族人是使他在很久以前的流沙之戰失去兒子的罪魁禍首。', `MaleText_loc7`='Algunos dicen que nos culpa a nosotros, su pueblo, por la pérdida de su hijo hace mucho tiempo en la guerra del Mar de Dunas.' WHERE `ID`=34806;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누군가는 다르나서스에 있는 빛나는 별, 우리의 지도자인 티란데 위스퍼윈드와 스태그헬름 사이에 불화가 생겨나고 있다고도 말했습니다.', `MaleText_loc4`='还有谣言说，他和我族的光芒，达纳苏斯的领袖泰兰德·语风之间出现了越来越多的矛盾。', `MaleText_loc5`='其他人則懷疑是因為他與我們族人的希望之光和領袖:泰蘭妲·語風逐漸升溫的衝突所致。', `MaleText_loc7`='Otros hablan de rumores sobre sus crecientes conflictos con Tyrande Susurravientos, la luz que brilla sobre nuestro pueblo, nuestra líder en Darnassus.' WHERE `ID`=34807;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러나 세나리온 의회의 많은 드루이드는 스태그헬름이 칼도레이에게 가장 좋은 선택을 내릴 뿐이라고 주장하며, 확고한 자세로 그를 지지했습니다.', `MaleText_loc4`='但许多塞纳里奥议会的德鲁伊仍然坚信，范达尔在全心全意为卡多雷的福祉而努力。他们全都会不惜一切代价地效忠于他。', `MaleText_loc5`='但許多塞納里奧議會的德魯伊堅信他不過是想把最好的未來帶給卡多雷，因此忠誠地跟隨著他。', `MaleText_loc7`='Pero muchos druidas del Círculo Cenarion mantienen que él solo quiere lo mejor para todos los Kaldorei y le sirven afanosamente para tal fin.' WHERE `ID`=34808;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판드랄 스태그헬름은 우리의 죄와 어리석음을 짊어지고 있습니다. 그래서 우리 모두의 존경을 받을 가치가 있지요.', `MaleText_loc4`='范达尔·鹿盔独力担负了我们的原罪和愚行，因此，他应该得到我们全体暗夜精灵的尊敬。', `MaleText_loc5`='鹿盔背負了我們的罪惡和錯誤，為此他理當獲得我們全部人的尊敬。', `MaleText_loc7`='Fandral Corzocelada soporta la carga de nuestros pecados y locuras, y por eso merece nuestro respeto.' WHERE `ID`=34809;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='몇 주 전부터, 텔드랏실에 사는 모든 이가 기억이 희미해지는 것을 깨달았습니다. 마치 시간이 삶의 일부를 빼앗아 간 것처럼요.', `MaleText_loc4`='几周前，泰达希尔上的所有生灵都发现的自己记忆开始变得模糊，仿佛时间偷走了他们的一部分生命。', `MaleText_loc5`='但是，過去這幾週，所有生活在泰達希爾上的人都感覺到他們的記憶開始模糊，就好像時間逐漸停止流動一樣。', `MaleText_loc7`='En las últimas semanas, los que viven en lo alto de Teldrassil han notado borrosos sus recuerdos, como si el propio tiempo hubiera cortado una parte de sus vidas.' WHERE `ID`=34810;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흐리멍덩한 상태를 벗어난 우리는 판드랄 스태그헬름과 그 추종자들이 한마디 말도 없이 종적을 감춘 걸 발견했습니다.', `MaleText_loc4`='迷雾终于散去之后，我们却发现范达尔·鹿盔和他的许多最亲近的追随者都在悄然间消失了。', `MaleText_loc5`='等我們發現的時候，范達爾·鹿盔和他忠實的跟隨者們都無煙無息的消失了。', `MaleText_loc7`='Al salir de esa bruma descubrimos que Fandral Corzocelada y sus seguidores más cercanos habían desaparecido sin decir palabra.' WHERE `ID`=34811;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러나 그 대신에, 샨도 스톰레이지가 꿈에서 깨어나 오랜 연인 티란데 위스퍼윈드에게 돌아왔지요.', `MaleText_loc4`='而大德鲁伊怒风已经从梦境中醒来，回到了他所钟爱的泰兰德·语风身边。', `MaleText_loc5`='這時，尊師怒風從夢中醒了過來，回到了他的愛人泰蘭妲·語風的身邊。', `MaleText_loc7`='Pero en este lugar, el Shan''do Tempestira despertó del Sueño y regresó al lado de su amada Tyrande Susurravientos.' WHERE `ID`=34812;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그가 돌아오자 알렉스트라자와 이세라가 우리가 그토록 오래 갈망했던 축복을 텔드랏실에 내려주었습니다.', `MaleText_loc4`='当他回归时，阿莱克丝塔萨和伊瑟拉也一同到来，并最终将他们的祝福赐予泰达希尔。', `MaleText_loc5`='而在他回來之後，雅立史卓莎和伊瑟拉終於將他們的祝福賜給了泰達希爾。', `MaleText_loc7`='Y con él vinieron también Alexstrasza e Ysera para, por fin, ofrecer sus bendiciones a Teldrassil.' WHERE `ID`=34813;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오염된 부분이 아직 남아 안타깝게 정화를 갈구하고 있지만, 어쨌든 텔드랏실의 큰 가지들에는 변화가 생겼습니다. 새로운 성장이 시작된 것입니다.', `MaleText_loc4`='虽然还残留有少量急需清除的腐化物，但泰达希尔似乎已经开始萌生新枝了。新生已然开始。', `MaleText_loc5`='雖然出現了些許的腐化，需要即刻被淨化，泰達希爾的樹枝卻已經開始發生了變化。成長又開始了。', `MaleText_loc7`='Aunque todavía queda una mínima corrupción que ansía desesperadamente ser purificada, las ramas de Teldrassil parecen haber cambiado. Vuelven a crecer de nuevo.' WHERE `ID`=34814;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이후에 무슨 일이 생길지는 아무도 모르나, 말퓨리온과 티란데가 재결합했으니 칼도레이에 새로운 희망이 싹텄습니다.', `MaleText_loc4`='没有人知道以后会发生什么，但随着玛法里奥和泰兰德的重新结合，卡多雷又有了新的希望。', `MaleText_loc5`='沒人知道之後會發生什麼事，但瑪法里恩和泰蘭妲的重逢讓卡多雷燃起了新的希望。', `MaleText_loc7`='Nadie sabe qué sucederá ahora, pero con la reunión de Malfurion y Tyrande, una nueva esperanza amanece sobre los Kaldorei.' WHERE `ID`=34815;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비는 다 됐소, $n?', `MaleText_loc4`='你准备好了吗，$n？', `MaleText_loc5`='你準備好要這樣做了嗎，$n?', `MaleText_loc7`='¿Estás $gpreparado:preparada; para esto, $n?' WHERE `ID`=34816;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비가 다 끝났습니다, 로코.', `MaleText_loc4`='开始吧，罗克。', `MaleText_loc5`='開始吧，洛科。', `MaleText_loc7`='Tráelo, Rocco.', `FemaleText_loc1`='준비가 다 끝났습니다, 로코.', `FemaleText_loc4`='开始吧，罗克。', `FemaleText_loc5`='開始吧，洛科。', `FemaleText_loc7`='Tráelo, Rocco.' WHERE `ID`=34817;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기 코도가 오고 있소. 어서 올라타시오!', `MaleText_loc4`='她来了，上坐骑！', `MaleText_loc5`='她來了。上坐騎!', `MaleText_loc7`='Ahí está. ¡Monta!' WHERE `ID`=34818;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 희미한 기억에 빠진 채 달샘을 응시합니다.', `MaleText_loc4`='%s凝望着月亮井，似乎是迷失在遥远的记忆中。', `MaleText_loc5`='%s往月井裡看去，迷失於過去的回憶。', `MaleText_loc7`='%s mira a la Poza de la luna y se pierde en memorias distantes.' WHERE `ID`=34819;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼도레이의 망령이 눈을 감더니 사라집니다.', `MaleText_loc4`='卡多雷的幻影闭上眼睛，渐渐消失了。', `MaleText_loc5`='卡多雷陰影闔上了它的眼後淡去了。', `MaleText_loc7`='La Sombra de los Kaldorei cierra los ojos y desaparece.' WHERE `ID`=34820;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대단한 사격 솜씨였소! 코도들은 내가 진정시켜 보겠소. 당신은 톨크에게 보고하시오. 이번 공격에 대해 알고 싶어할 테니까 말이오.', `MaleText_loc4`='真是令人难以置信的射击！我会尽量让这些科多兽平静下来。去向索克报告吧，他一定很想了解关于这次袭击的情况。', `MaleText_loc5`='驚人的準頭!我會試著讓動物們冷靜下來。報告給索克，他會想知道這次的攻擊事件。', `MaleText_loc7`='¡Un tiroteo alucinante! Voy a intentar tranquilizar a los animales. Ve a ver a Thork, querrá estar informado de este ataque.' WHERE `ID`=34821;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='손 좀 써보라고!', `MaleText_loc4`='搞定！', `MaleText_loc5`='弄好它!', `MaleText_loc7`='¡Más fuerte!' WHERE `ID`=34822;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='만들어 보라고!', `MaleText_loc4`='成功！', `MaleText_loc5`='做好它!', `MaleText_loc7`='¡Adelante!' WHERE `ID`=34823;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해 보라고!', `MaleText_loc4`='做到了！', `MaleText_loc5`='快做!', `MaleText_loc7`='¡Hazlo!' WHERE `ID`=34824;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 단단하게, 더 낫게, 더 빠르게, 그리고 더 강력하게!', `MaleText_loc4`='更坚韧，更优秀，更快，更强大！', `MaleText_loc5`='更堅硬、更棒、更快、更強大!', `MaleText_loc7`='¡Más resistente, mejor, más rápida, más fuerte!' WHERE `ID`=34825;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 모든 폭탄을 끝장내 버릴 폭탄이라고!', `MaleText_loc4`='这个炸弹能终结一切炸弹！', `MaleText_loc5`='這是炸彈中的終結者!', `MaleText_loc7`='¡Esta es la bomba que acabará con todas las bombas!' WHERE `ID`=34826;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누군가 우리에게 폭탄을 설치했어!', `MaleText_loc4`='有谁来为我们安放好这颗炸弹！', `MaleText_loc5`='誰快把炸彈設置好!', `MaleText_loc7`='¡Que alguien active la bomba!' WHERE `ID`=34827;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이걸 돌발톱 산맥까지 운반할 만큼 멍청한 친구를 누가 좀 데려와!', `MaleText_loc4`='我需要找个够蠢的家伙把这东西带进石爪去！', `MaleText_loc5`='誰找個跟這東西一樣笨的人把它移動到石爪山脈!', `MaleText_loc7`='¡Que alguien me consiga a alguien suficientemente estúpido como para llevar esta cosa a Sierra Espolón!' WHERE `ID`=34828;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더는 기다릴 수 없다고, 이걸 터뜨려야겠군, 크하하하하하하!', `MaleText_loc4`='我已经等不及了。我要把它引爆！哇哈哈哈哈哈哈哈！', `MaleText_loc5`='我等不下去了。我現在就要點燃它!哇哈哈哈哈哈!', `MaleText_loc7`='Ya no puedo esperar más. ¡Voy a activarla! ¡Jaaajaajaaa!' WHERE `ID`=34829;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 이걸 한번 써보자고...', `MaleText_loc4`='让我们对它进行测试。', `MaleText_loc5`='讓我們測試一下這東西...', `MaleText_loc7`='Probemos esta cosa...' WHERE `ID`=34830;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 약간만...', `MaleText_loc4`='只要一点……', `MaleText_loc5`='僅使用一小撮...', `MaleText_loc7`='Solo un poquito...' WHERE `ID`=34831;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 다가가자 %s|1이;가; 신비한 모습을 나타내며 인사를 합니다.', `MaleText_loc4`='随着你一步步靠近，%s变成一个具体的形态，并点头向你致意。', `MaleText_loc5`='%s在你靠近後逐漸淡去，點頭向你微微示意。', `MaleText_loc7`='%s aparece de pronto a medida que te acercas y te saluda levemente con la cabeza.' WHERE `ID`=34832;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 달샘 옆에 앉아 고요히 명상을 합니다.', `MaleText_loc4`='%s在月亮井旁边，陷入了沉思。', `MaleText_loc5`='%s安逸地靠在月亮石旁開始瞑想。', `MaleText_loc7`='%s descansa al lado de la Poza de la Luna en pacífica contemplación.' WHERE `ID`=34833;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 편안하고 사려 깊은 표정으로 달샘에 천천히 다가갑니다.', `MaleText_loc4`='%s缓步靠近月亮井，一种熟悉的，若有所思的神情出现在它的脸上。', `MaleText_loc5`='%s緩慢的走向月井，臉上帶著讓人熟悉的凝重表情。', `MaleText_loc7`='%s se acerca lentamente a la Poza de la Luna con una mirada pensativa y familiar en el rostro.' WHERE `ID`=34834;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 당신에게 다가오며 모든 걸 안다는 듯 미소 짓습니다.', `MaleText_loc4`='随着它逐渐靠近，%s向你露出了胸有成竹的微笑。', `MaleText_loc5`='隨著它的接近，%s會意地對你微笑。', `MaleText_loc7`='%s te sonríe cómplice a medida que te acercas.' WHERE `ID`=34835;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우왁!!', `MaleText_loc4`='呜哈！', `MaleText_loc5`='呀呼!!', `MaleText_loc7`='¡Yujuuuu!' WHERE `ID`=34836;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아하하하하! 내 함정에 빠졌구나, $n!', `FemaleText_loc4`='啊哈哈哈哈，你落进了我的陷阱，$n！', `FemaleText_loc5`='哈哈哈哈，你中計了，$n!', `FemaleText_loc7`='¡Jajajaaja, has caído en mi trampa, $n!' WHERE `ID`=34837;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하십시오, $n!', `MaleText_loc4`='$n，小心！', `MaleText_loc5`='小心，$n!', `MaleText_loc7`='¡Cuidado, $n!' WHERE `ID`=34838;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='볼윤, 칼리바가 아직 근처에 있습니까?', `MaleText_loc4`='波尔温，卡丽瓦还在附近吗？', `MaleText_loc5`='波爾溫，卡莉瓦還在嗎?', `MaleText_loc7`='Bolyun, ¿Kariva sigue por aquí?', `FemaleText_loc1`='볼윤, 칼리바가 아직 근처에 있나요?', `FemaleText_loc4`='波尔温，卡丽瓦还在附近吗？', `FemaleText_loc5`='波爾溫，卡莉瓦還在嗎?', `FemaleText_loc7`='Bolyun, ¿Kariva sigue por aquí?' WHERE `ID`=34839;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 뒤를 조심하십시오, $n!', `MaleText_loc4`='是的，小心背后，$n！', `MaleText_loc5`='對，小心你後面，$n!', `MaleText_loc7`='Sí, ¡mira detrás de ti, $n!' WHERE `ID`=34840;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일인가, $r 친구? 시간은 금이라고!', `MaleText_loc4`='$r，这是什么？时间就是金钱！', `MaleText_loc5`='幹麻，$r?時間就是金錢!', `MaleText_loc7`='¿Qué ocurre, $c? ¡El tiempo es oro!' WHERE `ID`=34841;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑구나, $r|1이여;여;.', `MaleText_loc4`='你好啊，$r。', `MaleText_loc5`='你好啊，$r。', `MaleText_loc7`='Buenos días, $r.' WHERE `ID`=34842;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='숲의 구원자여! 그대의 도움이 없었다면 아스트라나르와 잿빛 골짜기의 나머지 지역이 불타는 군단의 손아귀에 빠져버렸을 것이다.$B$B기분 좋은 날이 되기를 바라노라, $n!', `MaleText_loc4`='森林的拯救者！如果不是你的英勇行为，阿斯特兰纳和灰谷一定会落进燃烧军团的手中。$B$B希望你诸事顺利，$n！', `MaleText_loc5`='森林的救星!如果沒有你，阿斯特蘭納和整個梣谷一定都會落入燃燒軍團之手。$B$B我希望你能有愉快的一天，$n!', `MaleText_loc7`='¡Adalid del bosque! Si no hubiera sido por tus acciones, con toda seguridad Astranaar habría caído ante la Legión Ardiente.$B$B¡Espero que te encuentres bien, $n!' WHERE `ID`=34843;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저주에 빠지면 안 됩니다! 여러분은 한때 길니아스의 시민이었습니다... 다시 길니아스의 시민이 되어야 합니다!', `MaleText_loc4`='不要屈服于这个诅咒！你们曾是吉尔尼斯人……你们能够再次成为吉尔尼斯人！', `MaleText_loc5`='不要屈服於詛咒!你們曾是吉爾尼斯的驕傲子民...你們會再次擁有過去的身分!', `MaleText_loc7`='¡No cedáis ante la maldición! Una vez fuisteis hombres y mujeres de Gilneas... ¡podéis volver a serlo!' WHERE `ID`=34844;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='길니아스는 여러분의 도움이 필요합니다! 동물들처럼 떼를 지어서 숲 속으로 도망갈 때가 아니란 말입니다! 적과 싸워 죽을 때 죽더라도 야수가 아닌 길니아스인으로 죽읍시다!', `MaleText_loc4`='吉尔尼斯需要你们！你们不能像野兽一样逃进森林中！勇敢地面对敌人，无论生死，都要作一个吉尔尼斯人，而不是野兽！', `MaleText_loc5`='吉爾尼斯需要你!現在不是像一群野獸成群撤回森林的時候!以吉爾尼斯人的身分面對敵人，非生即死!', `MaleText_loc7`='¡Gilneas te necesita! ¡Ahora no es el momento de retirarse a los bosques como una manada de animales salvajes! ¡Enfrentaos al enemigo y vivid o morid como gilneanos, no como animales!' WHERE `ID`=34845;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여러분은 야수로 변해버린 것 같지만, 아직도 몸속에는 길니아스인의 피가 흐르고 있습니다. 호드와 싸워 우리의 고향을 지킵시다!', `MaleText_loc4`='你们也许沾染了野性，但吉尔尼斯的血仍然流动在你们的体内。对抗部落，保卫我们的家园！', `MaleText_loc5`='你們體內或許已充滿野性，但吉爾尼斯之血仍流動在你們的體內。阻止部落，防衛我們的家園!', `MaleText_loc7`='Quizá ustedes se hayan vuelto salvajes, pero la sangre gilneana todavía corre por sus venas. ¡Defiendan sus tierras de la Horda!' WHERE `ID`=34846;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명예의 들판', `MaleText_loc4`='荣耀之地', `MaleText_loc5`='榮譽原野', `MaleText_loc7`='Campos de Honor', `FemaleText_loc1`='명예의 들판', `FemaleText_loc4`='荣耀之地', `FemaleText_loc5`='榮譽原野', `FemaleText_loc7`='Campos de Honor' WHERE `ID`=34847;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세나리우스의 길', `MaleText_loc4`='塞纳留斯之路', `MaleText_loc5`='塞納留斯之徑', `MaleText_loc7`='Senda de Cenarius', `FemaleText_loc1`='세나리우스의 길', `FemaleText_loc4`='塞纳留斯之路', `FemaleText_loc5`='塞納留斯之徑', `FemaleText_loc7`='Senda de Cenarius' WHERE `ID`=34848;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오우거 종이박', `MaleText_loc4`='食人魔皮纳塔', `MaleText_loc5`='巨魔糖果玩偶', `MaleText_loc7`='Piñata ogra', `FemaleText_loc1`='오우거 종이박', `FemaleText_loc4`='食人魔皮纳塔', `FemaleText_loc5`='巨魔糖果玩偶', `FemaleText_loc7`='Piñata ogra' WHERE `ID`=34849;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법 수탉 탈것', `MaleText_loc4`='魔法公鸡坐骑', `MaleText_loc5`='魔法猛雞坐騎', `MaleText_loc7`='Montura gallo mágico', `FemaleText_loc1`='마법 수탉 탈것', `FemaleText_loc4`='魔法公鸡坐骑', `FemaleText_loc5`='魔法猛雞坐騎', `FemaleText_loc7`='Montura gallo mágico' WHERE `ID`=34850;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='콜로간이 당신에게 안광을 집중합니다!', `MaleText_loc4`='科隆加恩在注视着你！', `MaleText_loc5`='柯洛剛恩正在注視著你!', `MaleText_loc7`='¡Kologarn fija sus ojos en ti!' WHERE `ID`=34851;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어이, 친구. 어떻게 나를 찾아냈지? 더 으슥한 곳을 찾아봐야겠군.', `MaleText_loc4`='嘿，你是怎么找到我的？看来我要找一个更好的藏身地了。', `MaleText_loc5`='喂，老兄，你是怎麼找到我的?看來我必須選個更好的藏匿地點。', `MaleText_loc7`='Hey, colega, ¿cómo me has encontrado? Tengo que buscar un escondite mejor.' WHERE `ID`=34852;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 스스로 $n|1라고;이라고; 부른단 말이오? 펄볼그 이름치고는 이상한 이름이군.$B$B잿빛 골짜기 출신도 아니구려.', `MaleText_loc4`='你的名字叫做$n？这对于熊怪来说可真是个奇怪的名字。$B$B看来你不是从灰谷来的。', `MaleText_loc5`='你的名字叫...$n?這不是個常見的熊怪名字。$B$B你不是從梣谷來的。', `MaleText_loc7`='¿Te haces llamar $n? Es un nombre extraño para un fúrbolg.$B$BNo eres de Vallefresno.' WHERE `ID`=34853;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그건 지금 중요하지 않습니다, 오타 원. 제 말을 들어보십시오. 당신은 오크에 맞서 싸워야 합니다!', `MaleText_loc4`='现在这并不重要。奥塔·旺，听我说。你必须起来反抗那些兽人！', `MaleText_loc5`='那現在並不重要。歐塔·文，聽我說，你必須挺身對抗獸人。', `MaleText_loc7`='Eso no es importante ahora mismo. Ota Wen, escúchame. ¡Debes rebelarte contra los orcos!', `FemaleText_loc1`='그건 지금 중요하지 않아요, 오타 원. 제 말을 들어보세요. 당신은 오크에 맞서 싸워야 해요.', `FemaleText_loc4`='现在这并不重要。奥塔·旺，听我说。你必须起来反抗那些兽人！', `FemaleText_loc5`='那現在並不重要。歐塔·文，聽我說，你必須挺身對抗獸人。', `FemaleText_loc7`='Eso no es importante ahora mismo. Ota Wen, escúchame. ¡Debes rebelarte contra los orcos!' WHERE `ID`=34854;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<노예가 되어 이미 무감각해진 오타 원의 눈이 당신의 제안에 더욱 거슴츠레해집니다. 당신은 다르톨의 마법봉의 힘이 당신을 통해 펄볼그에게 세차게 흐르기 시작하는 것을 느낍니다.>$B$B일어나다니?', `MaleText_loc4`='<奥塔·旺的眼睛本已经因为饱受奴役而变得灰暗。听到你的方案，它们重新闪烁出光芒。你感觉到达图尔魔棒的力量通过你传到了这只熊怪的身上。>$B$B你要反抗吗？', `MaleText_loc5`='<歐塔·文的雙眼，因為被奴役而呆滯，在聽了你的建議後更加往這看來了。你感受到了達圖爾魔棒的力量開始流動和延伸去觸碰熊怪。>$B$B起來反抗?', `MaleText_loc7`='<Los ojos de Ota Wen, sin vida a causa de la esclavitud, miran más intensamente al oír tu sugerencia. Sientes el poder de la vara de Dartol que se despierta en tu interior y sale de ti para tocar al fúrbolg.>$B$B¿Rebelarme?' WHERE `ID`=34855;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 일어나야 합니다! 동료 펄볼그들에게 이 감옥을 부수고 호드를 물리치라고 말하십시오! 마법봉의 힘이 당신을 인도할 것입니다!', `MaleText_loc4`='是的，奋起反抗吧！带领你的熊怪打破牢笼，消灭部落。是那根魔杖的力量在压迫你们！', `MaleText_loc5`='是的，起來反抗吧!告訴你的熊怪同胞們逃出這個籠子，殺死部落的人。你們必須屈服於節杖的力量!', `MaleText_loc7`='¡Sí, rebelarte! ¡Diles a tus compañeros fúrbolgs que rompan esta jaula y destrocen a la Horda. ¡El poder de la vara te obliga!', `FemaleText_loc1`='네, 일어나야 해요! 동료 펄볼그들에게 이 감옥을 부수고 호드를 물리치라고 말하세요! 마법봉의 힘이 당신을 인도할 거예요!', `FemaleText_loc4`='是的，奋起反抗吧！带领你的熊怪打破牢笼，消灭部落。是那根魔杖的力量在压迫你们！', `FemaleText_loc5`='是的，起來反抗吧!告訴你的熊怪同胞們逃出這個籠子，殺死部落的人。你們必須屈服於節杖的力量!', `FemaleText_loc7`='¡Sí, rebelarte! ¡Diles a tus compañeros fúrbolgs que rompan esta jaula y destrocen a la Horda. ¡El poder de la vara te obliga!' WHERE `ID`=34856;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<오타 원이 일어서며 하늘을 향해 울부짖자 그의 눈에서 불가사의한 빛이 불타오릅니다.>$B$B그렇소! 우리는 일어날 것이오! 일어나서 우리를 가둔 자들을 파괴할 것이오!', `MaleText_loc4`='<一道奇怪的光芒在奥塔·旺的眼中闪过。他挺起身子，向天空发出咆哮。>$B$B我们会奋起抗争！摧毁我们的枷锁！', `MaleText_loc5`='<當他起身向天空咆哮時，眼中燃燒著一道奇特的光芒。>$B$B沒錯，我們將會掘起!掘起對抗和摧毀那些獄卒!', `MaleText_loc7`='<Una luz extraña se enciende en los ojos de Ota Wen mientras se levanta erguido, rugiendo hacia los cielos.>$b$b¡SÍ, NOS REBELAREMOS! ¡NOS REBELAREMOS Y DESTRUIREMOS A NUESTROS CARCELEROS!' WHERE `ID`=34857;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌발톱 산맥으로 도망칠 준비가 됐습니다!', `MaleText_loc4`='我已经准备好了奔向石爪！', `MaleText_loc5`='我準備好趕往石爪了!', `MaleText_loc7`='¡Ya estoy listo para partir hacia Sierra Espolón!', `FemaleText_loc1`='돌발톱 산맥으로 도망칠 준비가 됐습니다!', `FemaleText_loc4`='我已经准备好了奔向石爪！', `FemaleText_loc5`='我準備好趕往石爪了!', `FemaleText_loc7`='¡Ya estoy lista para partir hacia Sierra Espolón!' WHERE `ID`=34858;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이라고;라고; 알려진 자여, 우리를 가둔 자들을 곧 모두 없애버리겠소!', `MaleText_loc4`='不必再等多久了，你这个叫$n的家伙，我们很快就会消灭那些抓捕我们的混蛋！', `MaleText_loc5`='很快的，一位名為$n的人將出現。很快的，我們將摧毀俘虜我們的人!', `MaleText_loc7`='Pronto, a ti que te conocen por $n, ¡pronto, habremos destruidos a nuestros captores!' WHERE `ID`=34859;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='죽은 척하는 건 정말 쉬워요, $n. 가만히 보기만 하세요...', `FemaleText_loc4`='装死是一件超级容易的事，$n。你来看……', `FemaleText_loc5`='裝死是很簡單的一件事，$n。看...', `FemaleText_loc7`='Hacerse el muerto es súper fácil, $n. Tú observa...' WHERE `ID`=34860;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 죽은 척 기술을 보여주기 시작합니다.', `FemaleText_loc4`='%s开始装死。', `FemaleText_loc5`='%s開始裝死。', `FemaleText_loc7`='%s empieza a hacerse el muerto.' WHERE `ID`=34861;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='보셨죠?! 전혀 어렵지 않잖아요. 그렇죠? 이제 고약한 냄새 나는 늙은 오소 브램블스카와 그의 수호병을 속이는데 아무런 문제가 없을 거예요.', `FemaleText_loc4`='看到了吗？！这不难吧？现在你可以轻松地戏弄那个恶心的老奥索·棘痕和他的卫士了。', `FemaleText_loc5`='看!這不難對吧?你現在可以輕鬆的騙過老歐索·荊爪和他的守衛們。', `FemaleText_loc7`='¿Ves? No ha sido tan difícil, ¿verdad? Ahora no te costará nada engañar al viejo y apestoso Oso Rajazarza y a sus guardianes.' WHERE `ID`=34862;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='통가의 독수리가 울부짖더니 산꼭대기를 맴돕니다.', `MaleText_loc4`='图加的鹰鸣叫着，向山峰盘旋而去。', `MaleText_loc5`='圖加的老鷹發出了叫聲，然後朝向頂端旋轉飛行。', `MaleText_loc7`='El águila de Tonga grita, después vuelta en círculos hacia el pico.' WHERE `ID`=34863;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘했소, 친구여! 덕분에 이곳에서부터 대지에 관한 조사를 시작할 수 있겠군.', `MaleText_loc4`='干得好，朋友！现在我们就可以勘察这片区域了。', `MaleText_loc5`='幹得好，朋友!現在就由我們接手調查這片土地。', `MaleText_loc7`='¡Buen trabajo! Desde aquí podemos contemplar las tierras.' WHERE `ID`=34864;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대지모신이시여, 부디 자비를... 이토록 참혹하게 파괴되다니! 불모의 땅 전체가 바닷속으로 가라앉지 않은 게 다행이오.', `MaleText_loc4`='仁慈的大地母亲啊，看看这场浩劫带来的满目疮痍吧！或许我们还应该感到庆幸的是，贫瘠之地没有整个沉入海底。', `MaleText_loc5`='仁慈的大地之母，看看這毀壞的範圍啊!貧瘠之地沒有整個沉入海地已是萬幸。', `MaleText_loc7`='¡Madre Tierra misericordiosa, observa el alcance de la devastación! Tenemos suerte de que Los Baldíos al completo no estén cayéndose al mar a pedazos.' WHERE `ID`=34865;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런데, 이건 뭐지? 갈라진 대지 남쪽에선 뭔가 다른 일이 벌어지고 있소...', `MaleText_loc4`='这是什么？看来这道裂缝南边发生了另一些事情。', `MaleText_loc5`='但這是什麼?大裂縫南邊的大地發生了什麼事?', `MaleText_loc7`='¿Pero qué es esto? Algo más está ocurriendo en las tierras al sur de la fisura.' WHERE `ID`=34866;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='초목이 마구 자라나며 대지를 덮고 있군. 오아시스에서 발견한 현상과 비슷하오.', `MaleText_loc4`='实际上，这种植物不受任何限制地生长，吞噬了整片陆地。和我们在绿洲发现的非常相似。', `MaleText_loc5`='沒錯，植物在無人監管下成長，吞噬著土地。這與我們在綠洲所發現的狀況相似。', `MaleText_loc7`='Cierto, la flora crece sin control, devorando la tierra. Algo parecido a nuestros descubrimientos en los oasis.' WHERE `ID`=34867;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시는 같은 일이 생기지 않도록 최선을 다해야 하오. 오아시스를 더 자세히 조사하고, 이 현상의 근본적인 원인을 찾아서 해결해야겠군. 십자로에서 다시 만나 이야기합시다!', `MaleText_loc4`='我们必须竭尽全力阻止这种事情在这里发生。所以我们对绿洲的调查要进一步升级，从源头阻止这一现象。我们会在十字路口再谈谈！', `MaleText_loc5`='我們必須盡一切的力量阻止這裡發生一樣的事。我們必須更進一步調查綠洲，找到問題的根源後解決它。我們在十字路口再見!', `MaleText_loc7`='Debemos hacer todo lo que esté en nuestra mano para evitar que aquí ocurra lo mismo. Debemos intensificar nuestras investigaciones sobre los oasis y detener este fenómeno en su origen. ¡Hablaremos de nuevo en El Cruce!' WHERE `ID`=34868;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='숨을 깊게 들이마셔도 좋소, $c|1이여;여;. 천둥뿔 정상의 공기는 희박하지만, 산 아래의 대지를 병들게 하는 지저분한 먼지는 이곳에 없으니까 말이오.', `MaleText_loc4`='$c，深吸一口气。雷鸣峰顶的空气非常稀薄，不过这里毕竟没有下面那种呛鼻子的尘土。', `MaleText_loc5`='深呼吸，$c。雷首之巔的頂端空氣很稀薄，但不像下面有那麼多嗆人的灰塵。', `MaleText_loc7`='Respira hondo, $c. El aire en la Cima Tronatesta es muy fino, pero no está impregnado de este polvo asfixiante que estrangula las tierras de abajo.' WHERE `ID`=34869;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경로 산출 중입니다...', `MaleText_loc4`='计算路径……', `MaleText_loc5`='計算路線中...', `MaleText_loc7`='Calculando ruta...' WHERE `ID`=34870;
