UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경로 재산출이 진행 중입니다...', `MaleText_loc4`='重新计算中……', `MaleText_loc5`='重新計算中...', `MaleText_loc7`='Cálculo en proceso...' WHERE `ID`=34873;
