UPDATE `locales_broadcast_text` SET `MaleText_loc1`='운반을 시작합니다. 목적지는 칼바람 바위산입니다.', `MaleText_loc4`='开始传送，目的地，狂风峭壁。', `MaleText_loc5`='開始進行運送。目的地:狂風峭壁。', `MaleText_loc7`='Iniciando transporte. Destino, Risco Cortaviento.' WHERE `ID`=34875;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조금 도와주겠나, 작은 친구여?', `MaleText_loc4`='小朋友，能帮个忙吗？', `MaleText_loc5`='幫個忙吧，我的小隻朋友?', `MaleText_loc7`='¿Necesitas ayuda, $gpequeño amigo:pequeña amiga;?' WHERE `ID`=34876;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 그렇소 $n! 그게 바로 내가 듣고 싶었던 말이라오. 소란 좀 피워 보자고!', `MaleText_loc4`='哈，是啊，$n！这正是我想听到的。让我们弄些响动出来吧！', `MaleText_loc5`='哈，沒錯，$n!那就是我想聽到的。我們大鬧一番吧!', `MaleText_loc7`='¡Ja, sí, $n! Eso es lo que quiero oír. ¡Hagamos un poco de ruido!' WHERE `ID`=34877;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와서 덤벼 보아라, 이 말 얼굴같이 길쭉하게 생긴 벌레 놈들아!', `MaleText_loc4`='来吧，你们这些长着马脸的怪物们！', `MaleText_loc5`='來啊，你這馬臉長蛆的村夫!', `MaleText_loc7`='¡Vengan por ello, granjeros con cara de caballo!' WHERE `ID`=34878;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더... 더!', `MaleText_loc4`='再来些……多来些！', `MaleText_loc5`='更多....更多!', `MaleText_loc7`='Más... ¡Más!' WHERE `ID`=34879;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 저기 우리 목표가 있군. 여기까지 냄새가 나는걸.', `MaleText_loc4`='啊哈，这就是我们的目标了，我在这里就能闻到他的气味了。', `MaleText_loc5`='啊，我們的目標在那。我在這就可以聞到他。', `MaleText_loc7`='Oh, ahí está nuestro objetivo. Puedo olerlo desde aquí.' WHERE `ID`=34881;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='승리다!', `MaleText_loc4`='胜利！', `MaleText_loc5`='勝利!', `MaleText_loc7`='¡Victoria!' WHERE `ID`=34882;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='간단히 말해서 끝내줍니다!$B$B당신이 읽는 이 글은 "댄은 진짜 남자다!"라는 뜻이랍니다!', `MaleText_loc4`='真是令人吃惊！$B$B你读的这个东西意思就是“DAN纯爷们！”', `MaleText_loc5`='真是太驚人了!$B$B你在讀它就表示丹最棒!', `MaleText_loc7`='¡Simplemente increíble!$B$B¡Estás leyendo esto, lo que significa que DAN ES LO MÁS!' WHERE `ID`=34883;
