UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='조심해서 걸으란 말이야! 그러다가 발각될지도 몰라.', `FemaleText_loc4`='脚步放轻！你会被发现的。', `FemaleText_loc5`='放慢你的腳步，老兄!你會被發現的。', `FemaleText_loc7`='¡Deja de dar vueltas, colega! Van a veh''te.' WHERE `ID`=34890;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흥! 그냥 확 들켜버리는 게 어떨까? 숨어다니는 것도 지겹군.', `MaleText_loc4`='呸！我想要被看见？我只是努力想要藏起来。', `MaleText_loc5`='算了!或許我就是想被看到吧?我已經厭倦躲躲藏藏了。', `MaleText_loc7`='¡Bah! A lo mejor QUIERO que me vean. Estoy cansado de esconderme.' WHERE `ID`=34891;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제발 고르갈 좀 부채질하지 마십시오. 우리는 정찰하러 온 거지 난동을 피우러 온 게 아니란 말입니다.', `FemaleText_loc4`='$c，请不要刺激格高。我们应该做的是观察和报告情况，而不是引起一场骚乱。', `FemaleText_loc5`='拜託你，$c，別助長葛加爾的氣焰。我們該做的是觀察與回報，而不是造成騷動。', `FemaleText_loc7`='Por favor, $c, no animes a Gorgal. Se supone que eh''tamos aquí pa'' observar e informar, no pa'' armar jaleo.' WHERE `ID`=34892;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='슈도 이 소식을 들으면 좋아하겠지!', `MaleText_loc4`='看呼乌听到了这个消息还怎么说！', `MaleText_loc5`='看阿鞋知道了後會怎樣。', `MaleText_loc7`='Espera a que Herradura se entere de ESTO.' WHERE `ID`=34893;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 쿠락이 쓰러지자 공포에 질려 도망칩니다.', `MaleText_loc4`='当库拉克倒下时，%s惶恐地逃跑了。', `MaleText_loc5`='%s看到庫拉克倒下後恐慌地逃跑。', `MaleText_loc7`='%s huye aterrorizado cuando Kurak cae.' WHERE `ID`=34894;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살금살금 거리며 숨기나 하고 말이야. 이 고르갈로 말할 것 같으면, 난 숨어다니거나 하지는 않는단 말씀이지.', `MaleText_loc4`='偷偷摸摸，鬼鬼祟祟。让我告诉你关于格高的事：格高从来不会躲躲藏藏。', `MaleText_loc5`='鬼祟，鬼祟，鬼祟。讓我告訴你與葛加爾有關的事:葛加爾從不鬼鬼祟祟。', `MaleText_loc7`='Sigilosamente, sigilosamente, sigilosamente. Déjame que te diga algo sobre Gorgal: Gorgal nunca se mueve sigilosamente.' WHERE `ID`=34895;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하! 아주 멋지군! 지금이라도 내가 같이 싸워줄 수 있다고, $n.', `MaleText_loc4`='哈哈！这太精彩了！我随时都会和你并肩战斗，$n。', `MaleText_loc5`='哈哈!做得太棒了!我隨時都願意和你並肩作戰，$n。', `MaleText_loc7`='¡Ja, ja! ¡Eso ha sido glorioso! $n, lucharía a tu lado en cualquier circunstancia.' WHERE `ID`=34896;
