UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌발톱 산맥에 접근 중이다. 강력한 저항에 대비하라!', `MaleText_loc4`='向石爪山脉进攻。做好准备，敌人可能会发动猛烈的抵抗！', `MaleText_loc5`='接近石爪中。準備面對敵人頑強的反抗!', `MaleText_loc7`='Nos acercamos a Sierra Espolón. ¡Preparaos para una resistencia dura!' WHERE `ID`=34913;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 등껍질을 썬더 블러프로 보내 확인해야겠소. 조만간에 그대 도움을 구할 일이 또 있을 거요, 친구.', `MaleText_loc4`='我要把这些送到雷霆崖，以确认我的发现。也许我很快就将再次需要你的帮助了，朋友。', `MaleText_loc5`='我會將這些送到雷霆崖來對我的發現進行進一步的確認。我很快便再會需要你的幫忙，朋友。', `MaleText_loc7`='Enviaré estos a Cima del Trueno para confirmar mis hallazgos. Puede que pronto vuelva a necesitar tu ayuda, $gamigo:amiga;.' WHERE `ID`=34914;
