UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 차원문은 지옥불 반도에 있는 운명의 계단으로 이어지오... 그렇소, 아웃랜드 말이오.$B$B준비는 되었소...?', `MaleText_loc4`='这道传送门通向地狱火半岛的命运阶梯……绝对没错，就是外域。$B$B你准备好了吗……？', `MaleText_loc5`='這個傳送門通往地獄火半島的命運階梯...對，外域。$B$B你準備好...?', `MaleText_loc7`='Este portal lleva a Los Peldaños del Destino, en la Península del Fuego Infernal... eso es: Terrallende.$B$B¿Estás $gpreparado:preparada;...?' WHERE `ID`=34920;
