UPDATE `locales_broadcast_text` SET `MaleText_loc1`='둘이서 무슨 꿍꿍이인 거지? 그 짐을 줘 보게.', `MaleText_loc4`='你们两个在干什么？把那个包交给我。', `MaleText_loc5`='你們兩個在策劃什麼陰謀?把那包裹給我。', `MaleText_loc7`='¿Qué traman? Entrégenme ese paquete.' WHERE `ID`=34922;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장님은 언데드를 믿지 않는다는 사실을 알아야 하네. 분노의 관문에서 무슨 일이 있었는지 들어 보았나?', `MaleText_loc4`='$C，你应该知道，酋长不信任亡灵。你有没有听说过天谴之门发生的事情？', `MaleText_loc5`='$C，你應該知道大酋長不相信不死族。你沒聽說發生在憤怒之門的事件嗎?', `MaleText_loc7`='$C, deberías saber que el Jefe de Guerra no confía en los no-muertos. ¿Es que no sabes lo que ocurrió en la Puerta de Cólera?' WHERE `ID`=34923;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='목숨을 바쳐 싸우는 대의를 생각하면 더욱 잘해야만 하네, $r.', `MaleText_loc4`='你应该好好考虑一下该效忠谁，$r。', `MaleText_loc5`='你應該好好思考一下你應該對誰保持忠誠，$r。', `MaleText_loc7`='Harías bien en preguntarte dónde reside tu lealtad, $r.' WHERE `ID`=34924;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네의 그 "연구"에 대한 결과를 본 적이 있네. 연구를 위해 이 짐을 오그리마로 보내겠네.', `MaleText_loc4`='我们已经见到了你的“调查”结果。我会将这个包裹送到奥格瑞玛去进行研究。', `MaleText_loc5`='我們之前已經看過你的「研究」了。我會將這包裹送到奧格瑪進行研究。', `MaleText_loc7`='Ya hemos visto los resultados de tu ''investigación'' antes. Entregaré este paquete en Orgrimmar para que lo estudien.' WHERE `ID`=34925;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭐요? 아, 이거요? 아무것도 아니에요. 그냥... 야생동물 연구죠 뭐.', `FemaleText_loc4`='什么，这个？不是什么重要的东西，只是某种……野生物种研究。', `FemaleText_loc5`='什麼?這個?這沒什麼，不過是些...野生的研究。', `FemaleText_loc7`='¿Qué? ¿Esto? Esto no es nada. Tan solo un poco de... investigación de la fauna salvaje.' WHERE `ID`=34926;
