UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진동형 냉매 압축 밸브의 순서를 재배열하기만 하면 되는데...', `MaleText_loc4`='我要做的就是重新设定震荡冷却阀门……', `MaleText_loc5`='我只要把搖晃的冷卻壓力空閥重新排序就好了...', `MaleText_loc7`='Todo lo que tengo que hacer es volver a secuenciar las válvulas que regulan la presión oscilante del refrigerante...' WHERE `ID`=34948;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭔가? $n, 자네는 흑마법사가 아니군.$B$B자네 같은 $c에게는 내가 가르쳐 줄 것이 없네.', `MaleText_loc4`='什么？$n，你不是个术士。$B$B我不可能教导你这样的$c，$g先生:女士;。', `MaleText_loc5`='什麼?$n，你不是一個術士。$B$B像你這樣一個$c，我沒什麼可以教你的，$g先生:女士;。', `MaleText_loc7`='¿Qué? $n, no eres $gun brujo:una bruja;.$B$BNo hay nada que yo pueda enseñarle a $gun:una; $c como tú.' WHERE `ID`=34949;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 와줘서 고맙군. 자네에게 가르쳐줘야 할 기술이 몇 가지 있다네.$B$B어떻게 생각하는가?', `MaleText_loc4`='$n，很高兴你在这里。或许我能教你一两招。$B$B你觉得怎么样，$g先生:小姐;？', `MaleText_loc5`='$n，很高興看到你在這。或許我可以教你一兩件事。$B$B你意下如何?', `MaleText_loc7`='$n, me alegro de que estés aquí. ¿Quizá pueda enseñarte un par de cosas?$B$B¿Qué opinas, $gseñor:señorita;?' WHERE `ID`=34950;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게서 훈련받고 싶어하리라고 어느 정도는 예상했지. $n, 그 손가락으로 불화살을 다룰 수 있을지 모르겠어.', `MaleText_loc4`='不管怎样，我怀疑你不会想接受我的训练，$n。我不确定你的手指能不能控制好火焰箭。', `MaleText_loc5`='我有點懷疑你會想從我這裡學到什麼東西，$n。我不確定你那幾根手指是否可以掌握火焰箭。', `MaleText_loc7`='La verdad es que dudo que quieras ser entrenado por mí, $n. No estoy seguro de que esos dedos tuyos sean capaces de manejar una descarga de fuego.' WHERE `ID`=34951;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1은;는; 어떨지 잘 모르겠지만, 난 이런 섬에 영원히 고립될 생각은 전혀 없었다고!$B$B학교에 계속 다니면서 순간이동 마법을 배우기만 했더라도...', `MaleText_loc4`='我不了解你，$n，但我可不打算被永远困在这座岛上！$B$B如果我那时留在学院里，学会该如何使用传送魔法……', `MaleText_loc5`='你的話我不知道，$n，但我可不願意一輩子被孤立在這島上!$B$B要是我在學院有學一些傳送魔法就好了...', `MaleText_loc7`='No sé tú, $n, ¡pero yo no tengo intención alguna de quedarme tirado en esta isla para siempre!$B$BOjalá me hubiera quedado en la academia y hubiera aprendido cómo utilizar magia de teletransporte...' WHERE `ID`=34952;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 이런 원숭이 본 적 있어?', `MaleText_loc4`='你能相信这些猴子吗，$n？', `MaleText_loc5`='你能忍受這些猴子，$n?', `MaleText_loc7`='¿Puedes creer a estos monos, $n?' WHERE `ID`=34953;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 좋아. 앞으로 내가 정령의 대가로 키울 $g젊은이:아가씨;가 여기 왔군! 오늘은 무슨 훈련을 받고 싶으신가?', `MaleText_loc4`='哦，你来得正好……未来的元素大师！今天你想接受怎样的训练？', `MaleText_loc5`='啊哈，你來啦...我未來的元素大師!今天想要接受怎樣的訓練!', `MaleText_loc7`='Ah, bien, aquí estás... ¡$gEl:La; $gfuturo:futura; $gseñor:señora; de los elementales! ¿Qué clase de instrucción te interesa hoy?' WHERE `ID`=34954;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='헌금은 사제만 내는 것이 아니에요. 당신의 돈도 감사히 받겠어요.', `FemaleText_loc4`='即使不是牧师也可以缴纳什一税，你的金币一样受欢迎，$g先生:女士;。', `FemaleText_loc5`='你不需要成為一位牧師來繳納什一稅。你的金幣在這也是一樣受歡迎的，$g先生:女士;。', `FemaleText_loc7`='No hace falta que seas sacerdote para pagar el diezmo. Tu dinero es igual de bienvenido, $gseñor:señora;.' WHERE `ID`=34955;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='기억하세요, $n 님. 빛의 사제로서 봉사하며 생활하기 위해서는 많은 돈이 필요해요.$B$B사람들에게 기부해 달라고 부탁하실 때도 부끄러워하실 필요가 없어요.', `FemaleText_loc4`='圣光在上，记住，$n，如果你要成为一名牧师，你就需要许多金币来应付一切事务。$B$B所以千万不要羞于向凡人要求捐献。', `FemaleText_loc5`='記住，$n，如果你想成為一個光明的牧師，就需要很多金幣才能達成你的願望。$B$B千萬別害怕向別人要求贊助。', `FemaleText_loc7`='Recuerda, $n, si vas a ser un $gsacerdote:sacerdotisa; de la Luz, vas a necesitar un montón de oro para que las cosas sigan adelante sin problemas.$B$BNunca tengas miedo de pedir donaciones.' WHERE `ID`=34956;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신 같은 $c|1이;가; 나를 볼 수 있다니 놀랍군요. $n, 나는 꼼짝 않고 은신한 상태인 데 말이죠!', `FemaleText_loc4`='我很惊讶，$n，像你这样的$c竟然能看到我。我正在专心潜行呢！', `FemaleText_loc5`='$n，我很驚訝一個像你這樣的$c竟然可以看到我。我可是潛行在一根柱子上!', `FemaleText_loc7`='¡Me sorprende que $gun:una; $c como tú pueda verme, $n! ¡Estoy camuflada!' WHERE `ID`=34957;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그럼요, $n 님. 제가 훈련해 드릴게요, $n 님. 저 원숭이를 계속 지켜보기만 하세요!', `FemaleText_loc4`='当然，$n，我会训练你。但你一定要小心那些猴子！', `FemaleText_loc5`='當然，$n，我會訓練你。好好看住那些猴子們!', `FemaleText_loc7`='Claro, $n, te entrenaré, $n. ¡Tú simplemente no mires a los monos!' WHERE `ID`=34958;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로봇전사 NX-01은 현재 전원이 꺼진 상태입니다.', `MaleText_loc4`='全能战士NX-01型当前处于离线状态。', `MaleText_loc5`='自動戰士NX-01目前是關閉狀態。', `MaleText_loc7`='Guerreromática NX-01 desconectada.' WHERE `ID`=34959;
