UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리가 너무 멀리 있으면 안개가 길을 찾지 못할 때도 있습니다. 더 가까이 다가가서 다시 해보십시오.', `FemaleText_loc4`='有时候，如果我们距离太远，雾气就会让我们无法找到路径。让我们更深入一些，重试一次。', `FemaleText_loc5`='有時迷霧在我們離太遠的時候是無法找到路的。讓我們前進後再試一次。', `FemaleText_loc7`='A veces, la niebla no puede encontrar su camino si estamos demasiado lejos. Aventurémonos un poco más e intentémoslo de nuevo.' WHERE `ID`=34966;
