UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='길을 찾는 데 도움이 필요하신가요? 저는 이곳 지리에 아주 밝답니다.', `FemaleText_loc4`='需要有人帮你找到路吗？我对这个地方可以说是了如指掌。', `FemaleText_loc5`='需要幫忙指路嗎?我對這個地方熟到不能再熟了。', `FemaleText_loc7`='¿Necesitas ayuda para seguir tu camino? Conozco este lugar como la palma de mi mano.' WHERE `ID`=34984;
