UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그대가 도움이 필요할지도 모른다고 키라가 그러더군요.', `FemaleText_loc4`='凯拉说你也许需要帮助。', `FemaleText_loc5`='凱拉說你可能會需要幫忙。', `FemaleText_loc7`='Kyra dijo que quizá necesitarías ayuda.' WHERE `ID`=34987;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='거기 계셨군요! 그대가 이곳에 오기도 전에 펄볼그들에게 잡혀간 줄 알았어요.', `FemaleText_loc4`='你在这里！我还以为你被那些熊怪抓住了。', `FemaleText_loc5`='你來了!我以為你會被熊怪們抓起來到不了這邊。', `FemaleText_loc7`='¡Aquí estás! Creí que los fúrbolgs quizá te habían atrapado antes de que llegaras aquí.' WHERE `ID`=34988;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='만나서 반가워요. 동굴 전체에 놈들이 득실대니 경계를 늦추지 말아야겠어요.', `FemaleText_loc4`='很高兴见到你。他们散布在这些隧道的每一个角落里。我们必须时刻保持警惕。', `FemaleText_loc5`='很高興見到你。他們在隧道裡到處都是，我們必須提高戒備。', `FemaleText_loc7`='Me alegro de verte. Están por los túneles, debemos permanecer en guardia.' WHERE `ID`=34989;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 부상당했어요! 그냥 놓아두고 가세요.', `FemaleText_loc4`='我受伤了！不要管我，继续前进。', `FemaleText_loc5`='我受傷了!不要管我。', `FemaleText_loc7`='¡Estoy herida! Sigue adelante sin mí.' WHERE `ID`=34990;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잠깐 쉴 장소를 찾아야겠어요. 계속 가세요... 하지만 유물 없이 가시면 안 돼요.', `FemaleText_loc4`='我需要找个地方休息一下。继续吧……不要把那些圣物丢下。', `FemaleText_loc5`='我必須找個地方休息一下。繼續吧...離開時必須擁有聖物。', `FemaleText_loc7`='Necesito encontrar un lugar para descansar un rato. Continúa... No te marches sin las reliquias.' WHERE `ID`=34991;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='상처를 입었어요! 잠깐 쉬어야겠군요.', `FemaleText_loc4`='我受伤了！我需要休息一下。', `FemaleText_loc5`='我受傷了!我需要休息一下。', `FemaleText_loc7`='¡Estoy herida! Necesito descansar un poco.' WHERE `ID`=34992;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='펄볼그들이 그렇게 쉽게 타락하다니 슬픈 일이에요. 그들은 제 친구들이었으니까요.', `FemaleText_loc4`='看到那些熊怪的堕落，我感到非常伤心。他们曾经是我们的朋友。', `FemaleText_loc5`='我很難過看到這些熊怪被腐化的這麼嚴重。他們曾經是我們的朋友。', `FemaleText_loc7`='Me entristece ver que los fúrbolgs están ya tan corruptos. Solían ser amigos nuestros.' WHERE `ID`=34993;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이곳은 오염되었어요... 유물을 가지고 최대한 빨리 이곳을 벗어나야 해요.', `FemaleText_loc4`='这个地方已经遭到了污染……我们需要带着那些圣物尽快离开这里。', `FemaleText_loc5`='這個地方充滿了病菌...我們必須儘快帶著聖物離開這裡。', `FemaleText_loc7`='Este lugar está infestado... Bueno, tendremos que salir de aquí con las reliquias tan rápido como nos sea posible.' WHERE `ID`=34994;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잠자는 드루이드를 한 명도 보지 못했어요. 이곳에서 이미 납치된 게 틀림없어요.', `FemaleText_loc4`='我还没有看到那些沉眠的德鲁伊。他们一定是已经被带走了。', `FemaleText_loc5`='我沒看到任何沉睡的德魯伊。他們一定已經被帶離此地了。', `FemaleText_loc7`='No he visto a ninguno de los druidas durmientes. Ya se los habrán llevado de aquí.' WHERE `ID`=34995;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오염이 시작되는 것을 먼저 알아채야만 했어요. 한참 동안 계속해서 퍼졌는데 말이죠.', `FemaleText_loc4`='我应该预见到今天的景象。这种污染已经扩散了相当长的一段时间。', `FemaleText_loc5`='我們應該要預測到的，腐化已經擴散了一段時間了。', `FemaleText_loc7`='Deberíamos haberlo visto venir. La corrupción lleva extendiéndose bastante tiempo.' WHERE `ID`=34996;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이곳 펄볼그들이 이렇게까지 미쳐버렸다면, 텔드랏실 나머지 지역에 있는 펄볼그들은 어떻게 된 걸까요?', `FemaleText_loc4`='如果熊怪会变成今天这种样子，那么泰达希尔其余的地方又会是怎样？', `FemaleText_loc5`='如果熊怪們都可以到那麼遠，這對泰達希爾其他的地方來說代表了什麼?', `FemaleText_loc7`='Si los fúrbolgs están ya tan perdidos, ¿qué ocurrirá con el resto de Teldrassil?' WHERE `ID`=34997;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='모두 이 타락의 제물이 되기 전에 막아낼 방법이 있을 거예요.', `FemaleText_loc4`='一定有办法阻止这种污染将我们全部吞噬。', `FemaleText_loc5`='一定有什麼方法可以阻止腐化。我們必須在它吞噬我們前找到。', `FemaleText_loc7`='Tiene que haber una manera de detener la corrupción antes de que nos consuma a todos.' WHERE `ID`=34998;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='망할 판드랄! 도대체 무엇 때문에 우리가 이 저주받은 "세계수"와 힘든 상황에 빠지게 한 거지?', `FemaleText_loc4`='诅咒你，范达尔！你怎么会培育出这种受诅咒的“世界之树”？', `FemaleText_loc5`='該死的，范達爾!你因為這個腐化的「世界樹」把我們捲進了什麼樣的泥沼裡!', `FemaleText_loc7`='¡Maldito seas, Fandral! ¿Dónde nos has metido con todo eso del maldito "Árbol del Mundo"?' WHERE `ID`=34999;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야아아아!', `MaleText_loc4`='呀！！', `MaleText_loc5`='呀啊啊啊啊!', `MaleText_loc7`='¡Yaaarr!', `FemaleText_loc1`='야아!', `FemaleText_loc4`='呀！', `FemaleText_loc5`='呀啊啊!', `FemaleText_loc7`='¡Yar!' WHERE `ID`=35000;
