UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n! 제발 저 괴물 같은 무역왕이 죽었다고 말해줘!', `MaleText_loc4`='$n！请告诉我那个混蛋贸易大王已经挂了……', `MaleText_loc5`='$n!拜託你!跟我說貿易親王那個怪物已經死了!', `MaleText_loc7`='¡$n! ¡¡Por favor, dime que ese monstruo del Príncipe mercante no ha sobrevivido!!', `FemaleText_loc1`='$n! 제발 저 괴물 같은 무역왕이 죽었다고 말해주세요!', `FemaleText_loc4`='$n！请告诉我那个混蛋贸易大王已经挂了……', `FemaleText_loc5`='$n!拜託你!跟我說貿易親王那個怪物已經死了!', `FemaleText_loc7`='¡$n! ¡¡Por favor, dime que ese monstruo del Príncipe mercante no ha sobrevivido!!' WHERE `ID`=35007;
