UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리한테 포를 쏘던 얼라이언스 함선은 뭐였지? 호드 함선도 있었어?', `MaleText_loc4`='这些联盟船干嘛要向我们开火？！我好像又看见了一艘部落船？', `MaleText_loc5`='那些聯盟的船為什麼在對我們開火?!我好像還看到了部落的船?', `MaleText_loc7`='¡¿Por qué nos disparaban esos barcos de la Alianza?! ¿Es que parezco un barco de la Horda?', `FemaleText_loc1`='우리한테 포를 쏘던 얼라이언스 함선은 뭐였죠? 호드 함선도 있었나요?', `FemaleText_loc4`='这些联盟船干嘛要向我们开火？！我好像又看见了一艘部落船？', `FemaleText_loc5`='那些聯盟的船為什麼在對我們開火?!我好像還看到了部落的船?', `FemaleText_loc7`='¡¿Por qué nos disparaban esos barcos de la Alianza?! ¿Es que parezco un barco de la Horda?' WHERE `ID`=35009;
