UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<술에 취해 눈을 게슴츠레 깜빡이며 당신에게 손을 흔드는 선임기술자 풋>', `MaleText_loc4`='<那个喝醉的工程师眨着惺忪醉眼，向你挥手。>', `MaleText_loc5`='<喝醉的工程師茫茫地向你眨了眨眼和招了招手。>', `MaleText_loc7`='<El ingeniero borracho parpadea legañoso y te saluda.>' WHERE `ID`=35011;
