UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곧 귀가 먹고 말 거야. 그놈의 커다란 초록색 하피는 입을 5초도 쉬지 않을 거라고. 이 배를 어떻게 조종해야 하는 지 정도는 안다니까, 알았어? 난 바보가 아니란 말이야!', `MaleText_loc4`='如果这只绿色的大怪物在五秒钟之内不安静下来，我就要聋掉了。我知道该如何操纵这家伙。我可不是白痴！', `MaleText_loc5`='我快要聾了。那個綠色大笨鳥連閉嘴五秒鐘都不肯。我知道怎麼駕駛這個玩意兒，好嗎?我不是個笨蛋!', `MaleText_loc7`='Me estoy quedando sordo. No ha habido manera de callar a esa enorme arpía verde durante cinco segundos. Sé cómo conducir esta cosa, ¿vale? ¡No soy un idiota!' WHERE `ID`=35014;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내가 없었다면 지픽이 우리를 태우고 썬더 블러프를 곧장 들이받았을 걸세. 정말 멍청한 친구라니까.', `FemaleText_loc4`='呆子，如果不是我在这里，泽匹克会让我们直接撞上悬崖。', `FemaleText_loc5`='要是我不在這裡，齊派克會讓我們直直撞進雷霆崖。智障。', `FemaleText_loc7`='Zippik nos llevaría directos contra la cima si yo no estuviera aquí. Estúpido.' WHERE `ID`=35015;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='먼지를 마시는 것만 빼면 꽤 편안한 배랍니다.', `MaleText_loc4`='如果你不介意这些沙尘，那这就是一次很不错的旅行。', `MaleText_loc5`='如果不在意塵土的話，這倒是趟相當平穩的旅程。', `MaleText_loc7`='Es un viaje bastante tranquilo si no te molesta el polvo.', `FemaleText_loc1`='먼지를 마시는 것만 빼면 꽤 편안한 배에요..', `FemaleText_loc4`='如果你不介意这些沙尘，那这就是一次很不错的旅行。', `FemaleText_loc5`='如果不在意塵土的話，這倒是趟相當平穩的旅程。', `FemaleText_loc7`='Es un viaje bastante tranquilo si no te molesta el polvo.' WHERE `ID`=35016;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난간에서 물러나세요, 용감하신 분. 떨어지시는 건 바라지 않아요.', `MaleText_loc4`='离这道悬崖远一点，我可不想看到你摔下去。', `MaleText_loc5`='離邊緣遠一點，老大。可不希望你掉下去。', `MaleText_loc7`='Aléjate del borde, $gcampeón:campeona;. No queremos que te caigas.', `FemaleText_loc1`='난간에서 물러나세요, 용감하신 분. 떨어지시는 건 바라지 않는다고요.', `FemaleText_loc4`='离这道悬崖远一点，我可不想看到你摔下去。', `FemaleText_loc5`='離邊緣遠一點，老大。可不希望你掉下去。', `FemaleText_loc7`='Aléjate del borde, $gcampeón:campeona;. No queremos que te caigas.' WHERE `ID`=35017;
