UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<기술자의 주머니를 샅샅이 뒤집니다.>', `MaleText_loc4`='<搜一搜他的口袋。>', `MaleText_loc5`='<透過他的口袋開槍。>', `MaleText_loc7`='<Regístrale los bolsillos.>', `FemaleText_loc1`='<기술자의 주머니를 샅샅이 뒤집니다.>', `FemaleText_loc4`='<搜一搜他的口袋。>', `FemaleText_loc5`='<透過他的口袋開槍。>', `FemaleText_loc7`='<Regístrale los bolsillos.>' WHERE `ID`=35020;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거 보세요, 지금은 쉬는 시간이란 말이에요.', `MaleText_loc4`='嘿，我正在休息。', `MaleText_loc5`='嗨。我正在休息。', `MaleText_loc7`='Oye. Estoy en mi descanso.' WHERE `ID`=35021;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서풍호에 탄 여러분 모두 환영한다고. 불모의 땅을 가로지를 때 가장 편안하게 여행할 수 있는 비행선이지. 자리에 앉아서 항해를 즐기는 게 어때? 기름 냄새와 기분 좋고 건조한 공기가 이렇게 어우러지는 느낌은 어디에도 없으니까.', `MaleText_loc4`='欢迎登上西风号飞艇。搭乘它，你能以最快的速度穿越贫瘠之地。请坐下来，尽情享受飞行的乐趣吧。没有什么能比干燥的空气混合上汽油味更好闻的了。', `MaleText_loc5`='歡迎登上西風號，你將會在最舒適的情況下橫越貧瘠之地。坐下，好好享受你的飛行吧，孩子?沒有東西比乾燥而香甜的空氣混著機油的氣味更美好的了。', `MaleText_loc7`='$GBienvenido:Bienvenida; al Céfiro, el viaje más tranquilo que tendrás en Los Baldíos. Relájate y disfruta del vuelo, ¿está bien? No hay nada como el dulce aire seco mezclado con el aroma del aceite.' WHERE `ID`=35022;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='쉿! 여기 누군가가 있습니다.', `FemaleText_loc4`='嘘！有人在这里。', `FemaleText_loc5`='噓!有人來了。', `FemaleText_loc7`='¡Chist! Hay alguien aquí.' WHERE `ID`=35023;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이상한 상상은 하지 마십시오... 저는 샨도 스톰레이지 님께서 돌아오셔서 아주 기쁩니다만, 정말 이상하군요. 판드랄에게는 무슨 일이 생긴 겁니까?', `MaleText_loc4`='不要误会我的意思……我很高兴玛法里奥能回来，但这实在太令人怀疑了。范达尔出了什么事？', `MaleText_loc5`='別誤會...怒風尊師回來我很高興，但這實在事有蹊蹺。范達爾發生了什麼事?', `MaleText_loc7`='No me malinterpretes... Me alegra que Shando Tempestira esté de vuelta, pero esto es muy sospechoso. ¿Qué le ocurrió a Fandral?' WHERE `ID`=35024;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 톨위입니다. 평화를 지키며 지켜보는 게 일이지요. 그래서 저는 지켜봅니다.', `MaleText_loc4`='我是图维。我的工作就是维护这里的和平，警惕敌人的入侵。所以我一直保持着最高度的警觉。', `MaleText_loc5`='我是托威。工作就是好好地瞭望。所以我正在看。', `MaleText_loc7`='Yo ser Tolwe. Trabajar manteniendo paz y vigilando. Así que yo vigilar.' WHERE `ID`=35025;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기 새가 있습니다!', `MaleText_loc4`='那里有一只鸟！', `MaleText_loc5`='有一隻鳥!', `MaleText_loc7`='¡Ahí hay un pájaro!' WHERE `ID`=35026;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 구름은 우리 대족장님을 닮았군요.', `MaleText_loc4`='那团云看上去就像是个大酋长。', `MaleText_loc5`='那個雲看起來好像大酋長。', `MaleText_loc7`='Esa nube se parece al Jefe de Guerra.' WHERE `ID`=35027;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배가 어디 있다는 겁니까! 하피입니다! ...잠시만요, 저건 또 다른 새군요.', `MaleText_loc4`='小心那艘船！一个鹰身人！……等等，那只不过是一只鸟。', `MaleText_loc5`='船隻戒備!鷹身人來襲!...等等，看來是隻小鳥罷了。', `MaleText_loc7`='¡Cuidado con el barco! ¡Una arpía! Espera... eso es otro pájaro.' WHERE `ID`=35028;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기 벌레가 한 마리 갑니다.', `MaleText_loc4`='那里有一只虫子。', `MaleText_loc5`='有一隻蟲。', `MaleText_loc7`='¡Ahí hay un bicho!' WHERE `ID`=35029;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 오그리마야. 언제나처럼 거대하고 위협적인 모습이지. 잠시 숨을 돌려봐. 그러고 나선 다시 썬더 블러프로 돌아갈 테니!', `MaleText_loc4`='奥格瑞玛还是那么的巍峨和险峻。赶快休息一下吧，孩子，一会就要返回雷霆崖了！', `MaleText_loc5`='那就是奧格瑪，一如往常般巨大而險峻。盡快休息一下，小夥子們，讓我們快點回去雷霆崖!', `MaleText_loc7`='Y ahí está Orgrimmar, enorme y amenazadora como siempre. Tomen un breve descanso, chicos, y después volveremos a la cima.' WHERE `ID`=35030;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번에 정류할 곳은, 썬더 블러프야!', `MaleText_loc4`='下一站，雷霆崖！', `MaleText_loc5`='下一站，雷霆崖!', `MaleText_loc7`='Siguiente parada: ¡Cima del Trueno!' WHERE `ID`=35031;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='승강장과 사이가 넓으니 발이 빠지지 않게 조심해! 떨어져서 저 아래에 빈대떡이 되지 않았으면 해! 썬더 블러프에 온 모두를 환영해!', `MaleText_loc4`='小心！你应该不会想摔成一团肉酱吧。欢迎来到雷霆崖！', `MaleText_loc5`='當心你的腳步!你可不會想變成底下的一灘污漬。歡迎來到雷霆崖!', `MaleText_loc7`='¡Mira por dónde pisas! No queremos que te conviertas en una mancha allí abajo. ¡Te doy la bienvenida a Cima del Trueno!' WHERE `ID`=35032;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 모두들. 이 녀석을 타고 다시 오그리마로 가자고!', `MaleText_loc4`='好吧，孩子们，让我们飞越奥格瑞玛！', `MaleText_loc5`='好啦，小夥子們，讓這台寶貝前往奧格瑪吧!', `MaleText_loc7`='Bueno, chicos, llevemos esto a Orgrimmar.' WHERE `ID`=35033;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='조심해. 조심하라고! 방금 뭔가 떨렸는데? 네가 그 탑을 쓰러뜨릴 뻔했다고, 멍청이!', `FemaleText_loc4`='小心。小心！我已经感到颤动了！你差一点就要把那座塔撞塌了，呆子！', `FemaleText_loc5`='當心。當心!!!你沒感覺到震動嗎?你差點把塔給弄垮了，蠢貨!', `FemaleText_loc7`='Cuidado. CUIDADO. ¿Me ha dado un escalofrío? ¡Vas a tirar esa torre, zoquete!' WHERE `ID`=35034;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='예정 시간보다 늦었어! 이 뚱뚱한 녀석을 동쪽으로 돌려! 동쪽으로!', `FemaleText_loc4`='我们的进度已经落后了！转向东方！东方！', `FemaleText_loc5`='我們進度落後了!船轉向東邊!向東!', `FemaleText_loc7`='¡Vamos con retraso! ¡Mueve esta cosa hacia el este! ¡ESTE!' WHERE `ID`=35035;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바네실 지하굴로 떠날 준비가 됐습니다.', `MaleText_loc4`='我已经准备好前往班尼希尔兽穴了。', `MaleText_loc5`='我準備好前往班奈希爾獸穴了。', `MaleText_loc7`='Estoy listo para partir hacia el Túmulo de Ban''ethil.', `FemaleText_loc1`='바네실 지하굴로 떠날 준비가 됐어요.', `FemaleText_loc4`='我已经准备好前往班尼希尔兽穴了。', `FemaleText_loc5`='我準備好前往班奈希爾獸穴了。', `FemaleText_loc7`='Estoy lista para partir hacia el Túmulo de Ban''ethil.' WHERE `ID`=35036;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='움직여, 지픽! 월급은 땅 파서 나오는 줄 알아!', `FemaleText_loc4`='别傻站着，泽匹克！我们可不能把一整天的时间都花在它上面！', `FemaleText_loc5`='動作快，齊派克!我們可沒有一整天的時間可以消磨!', `FemaleText_loc7`='¡Muévete, Zippik! ¡No tenemos todo el día!' WHERE `ID`=35037;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='멋진 분, 안녕하세요. 여기에 들리는 비행선이 당신을 썬더 블러프로 곧장 모시고 갈 거예요. 공짜로요. 고블린이 여기 있는데, 누가 와이번이 필요하겠어요? 제 말이 맞죠?', `FemaleText_loc4`='嗨，甜心。停泊在这里的飞艇会把你一直送到雷霆崖，而且是免费的。有我们地精在，又会有谁想去骑双足飞龙？', `FemaleText_loc5`='嗨，甜心。這裡的飛艇將會送你直達雷霆崖，而且不收費唷。既然有我們哥布林在這裡，誰還需要那些雙足翼龍，對吧?', `FemaleText_loc7`='Hola, cariño. El zepelín que para aquí te llevará directamente a Cima del Trueno, sin coste alguno. ¿Quién necesita dracoleones, cuando nos tienen a los goblins? ¿Verdad?' WHERE `ID`=35038;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='썬더 블러프행 비행선이 도착했습니다! 불모의 땅을 가로질러 편안하게 여행하실 분은 모두 타세요!', `FemaleText_loc4`='前往雷霆崖的飞艇到达了！全体登船，我们要迅速飞越贫瘠之地！', `FemaleText_loc5`='往雷霆崖的飛艇已經抵達了!請上船來趟橫越貧瘠之地的舒適旅程!', `FemaleText_loc7`='¡El zepelín a Cima del Trueno ha llegado! ¡Todos a bordo para un suave viaje a través de Los Baldíos!' WHERE `ID`=35039;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='믿어져? 드디어 이곳에도 승강장이 세워져 비행선을 운행할 수 있다고! 이제 비행 금지 구역은 안녕이야. 내 말이 맞지? 시험 운행을 하는 동안 벼랑에 추락한 비행선은 딱 한 대뿐이었어. 왜 그렇게들 걱정하는지 이해가 안 간단 말이야.', `MaleText_loc4`='你相信吗？他们终于解除了这个地方的禁制，让我们的飞艇能够穿越这里的天空了！这里不再是飞行禁区了。毕竟，我们在测试飞行中只不过让一艘飞艇撞上了崖壁。我完全不明白他们到底在担心什么。', `MaleText_loc5`='你相信嗎?他們終於開放這個地方讓我們開飛艇經過這兒!不再有禁飛區了，對吧?我們只有在試飛的時候墜毀過一條船。我真不知道他們在擔心什麼。', `MaleText_loc7`='¿Puedes creerlo? ¡Al fin nos han permitido volar en zepelín por este lugar! Ya no es una zona prohibida al vuelo, ¿verdad? Solo estrellamos un zepelín en un montículo en el viaje de prueba. No entiendo por qué estaban tan preocupados.' WHERE `ID`=35040;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 승선해! 오그리마행 비행선이 도착했어! 듀로타로 가실 분들은 모두 타라고!', `MaleText_loc4`='做好准备！前往奥格瑞玛的飞艇已经到达！全体登船，目标杜隆塔尔！', `MaleText_loc5`='快來吧!前往奧格瑪的飛艇已經到了!上船前往杜洛塔吧!', `MaleText_loc7`='¡Vengan! ¡Ha llegado el zepelín a Orgrimmar! ¡Todos a bordo para ir a Durotar!' WHERE `ID`=35041;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흡착 폭탄 설치 완료! 남은 시간:', `MaleText_loc4`='刺贝水雷已放置就位！起爆时间：', `MaleText_loc5`='帽貝地雷安裝完成!啟動倒數:', `MaleText_loc7`='¡Bomba lapa en posición! Detonación en:' WHERE `ID`=35042;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='...5...', `MaleText_loc4`='...5...', `MaleText_loc5`='...5...', `MaleText_loc7`='...5...' WHERE `ID`=35043;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='...4...', `MaleText_loc4`='...4...', `MaleText_loc5`='...4...', `MaleText_loc7`='...4...' WHERE `ID`=35044;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='...3...', `MaleText_loc4`='...3...', `MaleText_loc5`='...3...', `MaleText_loc7`='...3...' WHERE `ID`=35045;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='...2...', `MaleText_loc4`='...2...', `MaleText_loc5`='...2...', `MaleText_loc7`='...2...' WHERE `ID`=35046;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='...1..', `MaleText_loc4`='...1...', `MaleText_loc5`='...1...', `MaleText_loc7`='...1...' WHERE `ID`=35047;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 그렇게 쳐다보고 있나? 죄수들이라도 고문하러 온 건가?', `MaleText_loc4`='你在看什么，$r？想要折磨囚犯吗？', `MaleText_loc5`='你看什麼看，$r?來打落水狗嗎?', `MaleText_loc7`='¿Qué miras, $r? ¿Has venio a atormental a los condenados?' WHERE `ID`=35048;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<쇠고랑을 들어 올리는 남작>$B$B뭘 망설이는 것이오, $c 양반. 날 믿지 않소?', `MaleText_loc4`='<巴隆举起他的镣铐。>$B$B好吧，$c。你信任我吗？', `MaleText_loc5`='<男爵舉起了他的手鏈。 >$B$B那就過來，$c。你信任我嗎?', `MaleText_loc7`='<El barón muestra sus grilletes.>$B$BEntonses, adelante, $c. ¿Confías en mí?' WHERE `ID`=35049;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절대로 안 믿는다, 이 사기꾼!', `MaleText_loc4`='绝不屈服，你这条恶狗！', `MaleText_loc5`='永不，你這不忠的狗!', `MaleText_loc7`='¡Nunca, perro taimado!', `FemaleText_loc1`='절대로 안 믿는다, 이 사기꾼!', `FemaleText_loc4`='绝不屈服，你这条恶狗！', `FemaleText_loc5`='永不，你這不忠的狗!', `FemaleText_loc7`='¡Nunca, perro taimado!' WHERE `ID`=35050;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<롱쇼어의 쇠고랑을 부수고 풀어줍니다.>', `MaleText_loc4`='<打断朗绍尔的镣铐，解救他。>', `MaleText_loc5`='<破壞朗紹爾的手鏈放他自由。>', `MaleText_loc7`='<Rompe los grilletes de Longavera y libéralo.>', `FemaleText_loc1`='<롱쇼어의 쇠고랑을 부수고 풀어줍니다.>', `FemaleText_loc4`='<打断朗绍尔的镣铐，解救他。>', `FemaleText_loc5`='<破壞朗紹爾的手鏈放他自由。>', `FemaleText_loc7`='<Rompe los grilletes de Longavera y libéralo.>' WHERE `ID`=35051;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하! 같이 일하게 돼서 영광이오, $n.', `MaleText_loc4`='哈！$n，很高兴和你做生意。', `MaleText_loc5`='哈!能與你做生意是我的榮幸，$n。', `MaleText_loc7`='¡Jarjarar! Un placel hacer negosios contigo, $n.' WHERE `ID`=35052;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻소? 보물이 어디 있는지 궁금하지 않소?', `MaleText_loc4`='怎么样？你没有脑袋可以踢，没有宝藏可以挖吗？', `MaleText_loc5`='所以呢?不是還有頭在等你去砍和寶藏等你去挖?', `MaleText_loc7`='¿Y bien? ¿No tienes cabesas que cortal y tesoros que desenterrar?' WHERE `ID`=35053;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋을 대로 하시지. 나는 보물이랑 함께 파묻힐 거니까.', `MaleText_loc4`='敬请随意，朋友。我和财宝都可以被埋起来。', `MaleText_loc5`='隨便你，老兄。我和寶藏都可以被埋起來。', `MaleText_loc7`='Tú mismo, broder. El tesoro y yo podemos ser enterraos.' WHERE `ID`=35054;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, $n 님. 요리 훈련을 받고자 하신다면, 제대로 찾아오셨습니다. 보통 순례자의 감사절 기간에는 새로 배우러 오는 학생들이 많답니다.', `MaleText_loc4`='你好，$n。如果你想要接受烹饪训练，那你就找对地方了。当感恩节进行的时候，我经常会有很多新学生。', `MaleText_loc5`='嗨，$n。如果你需要烹飪訓練，你可就找對地方了。旅人豐年祭的時候我總是會收到很多新學生。', `MaleText_loc7`='Hola, $n. Si buscas instrucción en cocina, has venido al lugar adecuado. Normalmente recibo un montón de nuevos estudiantes cuando se acerca la Generosidad del Peregrino.', `FemaleText_loc1`='안녕하세요, $n 님. 요리 훈련을 받고자 하신다면, 제대로 찾아오셨어요. 보통 순례자의 감사절 기간에는 새로 배우러 오는 학생들이 많지요.', `FemaleText_loc4`='你好，$n。如果你想要接受烹饪训练，那你就找对地方了。当感恩节进行的时候，我经常会有很多新学生。', `FemaleText_loc5`='嗨，$n。如果你需要烹飪訓練，你可就找對地方了。旅人豐年祭的時候我總是會收到很多新學生。', `FemaleText_loc7`='Hola, $n. Si buscas instrucción en cocina, has venido al lugar adecuado. Normalmente recibo un montón de nuevos estudiantes cuando se acerca la Generosidad del Peregrino.' WHERE `ID`=35055;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='객스프로켓! 이것 좀 깎아내게, 어서!', `MaleText_loc4`='加格斯普吉特！给我把这个削平——快点！', `MaleText_loc5`='加格斯普吉特!幫我刮這個，馬上!', `MaleText_loc7`='¡Dentolio! ¡Haz el favor de afeitarle por mí! ¡Ya!' WHERE `ID`=35056;
