UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐만! 내가 보물이 어디 있는지 말해준다고만 했지, 당신이 가져도 된다고는 하지 않았어!', `MaleText_loc4`='拿着它，$r！我承诺过会告诉你宝藏在哪里，但从没有承诺过会让你拥有它！', `MaleText_loc5`='慢著，$r!我答應跟你說寶藏在哪，但從沒答應你可以據為己有!', `MaleText_loc7`='¡Espera un segundo, $r! Prometí que te diría dónde está el tesoro, pero nunca te prometí que podrías quedártelo.' WHERE `ID`=35060;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전통적인 순례자의 감사절 잔치에 대해 자세히 알고자 한다면, 아무 나누미에게 물어보십시오.', `MaleText_loc4`='如果你想对感恩节的节日传统有更多了解，就和那些女侍应们聊聊天吧。', `MaleText_loc5`='如果你對學習更多傳統旅人豐年祭料理有興趣的話，可以跟任何一位女侍談談。', `MaleText_loc7`='Si te interesa saber más acerca del tradicional festín de la Generosidad del Peregrino, habla con cualquiera de las anfitrionas.' WHERE `ID`=35061;
