UPDATE `locales_broadcast_text` SET `MaleText_loc1`='냄새 나는 지방 덩어리 먹을 거 내놔라!', `MaleText_loc4`='这种臭气哄哄的肥东西却能提供食物！', `MaleText_loc5`='又香又胖的東西給食物!', `MaleText_loc7`='¡Apestosa cosa gorda dar comida!', `FemaleText_loc1`='냄새 나는 지방 덩어리 먹을 거 내놔라!', `FemaleText_loc4`='这种臭气哄哄的肥东西却能提供食物！', `FemaleText_loc5`='又香又胖的東西給食物!', `FemaleText_loc7`='¡Apestosa cosa gorda dar comida!' WHERE `ID`=35068;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리와 함께 순례자의 감사절을 즐기러 왔나?', `MaleText_loc4`='你来到这里是为了和我们一起庆祝感恩节吗？', `MaleText_loc5`='你來這裡跟我們一起慶祝旅人豐年祭嗎?', `MaleText_loc7`='¿Has venido a celebrar la Generosidad del Peregrino con nosotros?' WHERE `ID`=35069;
