UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 알리시아 커스버트는 아마 갑판 아래에 있을 겁니다. 같이 가시지요!', `MaleText_loc4`='好了，卡斯伯特应该在下面的甲板上，跟我来吧！', `MaleText_loc5`='OK，卡斯伯特可能在甲板下。老兄，跟我來!', `MaleText_loc7`='Sí, Cuthbert debería eh''tar bajo cubieh''ta. Ven conmigo, colega.' WHERE `ID`=35073;
