UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고르목의 기생충들이 더 있군요. 이놈들에게 계속 먹이를 주십시오.', `MaleText_loc4`='戈莫克还有更多的仆从。吃个饱吧。', `MaleText_loc5`='更多戈莫克的蟲子。餵飽它們。', `MaleText_loc7`='Más alimañas de Gormok. Mantenlas alimentadas.' WHERE `ID`=35075;
