UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나를 얕보지 마라.', `FemaleText_loc4`='别和我开玩笑，$r。', `FemaleText_loc5`='別跟我討價還價，$r。', `FemaleText_loc7`='No juegues conmigo, $r.' WHERE `ID`=35077;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 음모 뒤에 네놈이 있다는 걸 알았어야 했는데. 어디 덤벼 보아라, 토니! 이 배신자!', `FemaleText_loc4`='我应该知道这一切都是你在搞鬼，双齿。接受惩罚吧，叛徒！', `FemaleText_loc5`='我早該知道你是幕後黑手了，雙牙東尼。來吧，叛徒!', `FemaleText_loc7`='Debía haberme dado cuenta de que estarías detrás de esto Dos Colmillos. ¡Atrévete, traidor!' WHERE `ID`=35078;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='또 다른 반란이 제압되었다. 이제 갑판에 흘린 피나 좀 닦아라!', `FemaleText_loc4`='又镇压了一场哗变。现在，把这些血污从我的甲板上洗干净！', `FemaleText_loc5`='另一個反叛份子被收拾了。現在，快把我桌上的血跡擦乾淨!', `FemaleText_loc7`='Otro motín sofocado. ¡Ahora limpiad esa sangre de mis cubiertas!' WHERE `ID`=35079;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가비 선장님께서 곧 이 사실을 알게 되실 것이다!', `FemaleText_loc4`='嘉维伊船长会知道的！', `FemaleText_loc5`='葛瑞威船長必須被通報!', `FemaleText_loc7`='¡El capitán Garvery se enterará de esto!' WHERE `ID`=35080;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 탈 벌목기가 거의 다 준비됐네. 진짜라고!$b$b이제 거의 다 됐네... 계속 나와 연락하게!', `MaleText_loc4`='你的伐木机就要完成了，真的！$b$b随时都有可能……请再联系我！', `MaleText_loc5`='你的伐木機已經快準備好了，真的!$b$b隨時都會完成...記得經常來找我看看!', `MaleText_loc7`='¡Tu trituradora está casi a punto, de verdad!$b$bEn cualquier momento... ¡Tú pregúntame de vez en cuando!' WHERE `ID`=35081;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 나 좀 도와주게, 친구!', `MaleText_loc4`='帮我离开这里！', `MaleText_loc5`='老兄，救我出去!', `MaleText_loc7`='¡Ayúdame a sali'' de aquí, colega!' WHERE `ID`=35082;
