UPDATE `locales_broadcast_text` SET `MaleText_loc1`='랩터들을 조심하십시오. 아주 아주 똑똑하니까요.$B$B지난주에는 세 번째 놈이 나를 막대기로 때리는 동안 두 놈이 무리를 지어 도망가더라니까요.', `MaleText_loc4`='小心那些恐龙，它们可能非常非常聪明。$B$B上个星期，两头恐龙吸引了我的注意力，而第三头恐龙却用一根棒子偷袭我。', `MaleText_loc5`='小心這些迅猛龍，有些非常非常的聰明。$B$B上週我被兩隻打了一頓，第三隻還拿棒子打我。', `MaleText_loc7`='Cuigdado con los gaptores, pueden seg muy muy muy listos.$B$BLa semana pasada dos me sujetagon mientgas el tegcero me pegaba con un palo.' WHERE `ID`=35122;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멕스, 차 열쇠를 잃어버렸어요. 혹시 보셨나요?', `MaleText_loc4`='梅格斯，我把那些钥匙错放在那艘船上了。你找到它们了吗？', `MaleText_loc5`='梅格斯，我不知道把船的鑰匙放到哪了，你有找到嗎?', `MaleText_loc7`='Megs, he perdido las llaves del crucero. ¿Las has encontrado?', `FemaleText_loc1`='멕스, 차 열쇠를 잃어버렸어요. 혹시 보셨나요?', `FemaleText_loc4`='梅格斯，我把那些钥匙错放在那艘船上了。你找到它们了吗？', `FemaleText_loc5`='梅格斯，我不知道把船的鑰匙放到哪了，你有找到嗎?', `FemaleText_loc7`='Megs, he perdido las llaves del crucero. ¿Las has encontrado?' WHERE `ID`=35123;
