UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그물로 나 잡을 수 없어! 없는데... 그물로 나 잡았다.', `MaleText_loc4`='丝网拦不住我！不……网把我拦住了。', `MaleText_loc5`='網子抓不到我!不...網子逮住我了。', `MaleText_loc7`='¡La red no me parará! ¡Ninguna... red me parará!' WHERE `ID`=35158;
