UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들을 몰아내라!', `MaleText_loc4`='击退他们！', `MaleText_loc5`='把他們擊退!', `MaleText_loc7`='¡Que no avancen!' WHERE `ID`=35169;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘을 내라, 제군들! 우리의 도시를 지키자!', `MaleText_loc4`='打起精神来，战士们！我们必须保护我们的城市！', `MaleText_loc5`='大家振作!我們必須保護我們的城市!', `MaleText_loc7`='¡Ánimo, señores! ¡Protegamos nuestra ciudad!' WHERE `ID`=35170;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용사님, 어서 오십시오! 십자군의 시험장에서 도전하실 힘은 충분히 모으셨습니까?', `MaleText_loc4`='欢迎，勇士！你是否已经做好准备，打算迎接十字军的试炼的挑战了？', `MaleText_loc5`='歡迎，勇士!你召集好隊伍，準備要迎接銀白十字軍的挑戰了嗎?', `MaleText_loc7`='¡$gBienvenido:Bienvenida;, $gcampeón:campeona;! ¿Has reunido tus tropas como preparación para los retos de la Prueba del Cruzado?' WHERE `ID`=35171;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 도전할 준비가 되었습니다.', `MaleText_loc4`='是的，我们已经准备好了迎接即将到来的挑战。', `MaleText_loc5`='是。我們準備好面對接下來的挑戰了。', `MaleText_loc7`='Sí. Estamos preparados para los retos que nos aguardan.', `FemaleText_loc1`='네, 도전할 준비가 되었어요.', `FemaleText_loc4`='是的，我们已经准备好了迎接即将到来的挑战。', `FemaleText_loc5`='是。我們準備好面對接下來的挑戰了。', `FemaleText_loc7`='Sí. Estamos preparados para los retos que nos aguardan.' WHERE `ID`=35172;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='첫 번째 도전에 나설 준비는 되셨습니까?', `MaleText_loc4`='那么，你是否准备好了接受第一个挑战？', `MaleText_loc5`='你們準備好迎接第一場挑戰了嗎?', `MaleText_loc7`='Entonces, ¿están preparados para el primer reto?' WHERE `ID`=35173;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='첫 번째 도전에 나서겠습니다!', `MaleText_loc4`='开始第一场挑战吧！', `MaleText_loc5`='讓第一場挑戰開始吧!', `MaleText_loc7`='¡Adelante con el primer reto!', `FemaleText_loc1`='첫 번째 도전에 나서겠어요!', `FemaleText_loc4`='开始第一场挑战吧！', `FemaleText_loc5`='讓第一場挑戰開始吧!', `FemaleText_loc7`='¡Adelante con el primer reto!' WHERE `ID`=35174;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자비우스 경께서 오늘 잿빛 골짜기에 있는 탑으로 떠나셨다 들었습니다.', `FemaleText_loc4`='我听说萨维斯领主今天去他在灰谷的高塔了。', `FemaleText_loc5`='我聽說領主薩維斯今天離開了他在梣谷的塔。', `FemaleText_loc7`='He oído que Lord Xavius ha partido ya hacia su torre en Vallefresno.' WHERE `ID`=35175;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇습니까? 그분이 약속하셨던 더욱 큰 마력의 원천을 정말 얻을 수 있을까요?', `MaleText_loc4`='哦？你认为他真的能兑现诺言，给我们一个更强大的能量之源吗？', `MaleText_loc5`='喔?你認為他所保證的那更強大的力量之源是真的嗎?', `MaleText_loc7`='¿Oh? ¿Crees que su promesa de una fuente de poder aún mayor se volverá realidad?' WHERE `ID`=35176;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다른 이들은 실패했지만, 명가에서 가장 위대한 일원 중 한 분이니만큼 성공하시겠지요.', `FemaleText_loc4`='作为上层精灵中最强大的一员，他绝不会像别人那样惨遭失败。', `FemaleText_loc5`='作為精靈貴族裡最偉大的人，他可以成功完成其他人做不到的事。', `FemaleText_loc7`='Él es uno de los más grandes de los Altonato y tendrá éxito donde otros han fracasado.' WHERE `ID`=35177;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 아직 위험성이 신경 쓰입니다. 말퓨리온 님과 흙을 사랑하는 형제분들이 아직 상당히 화난 상태라는 점에는 동의하니, 이 살게라스 경은 다른 의제를 들고 와야 할 테지요...', `MaleText_loc4`='我仍然在为可能的风险感到担心。虽然我同意，玛法里奥和他那些喜爱泥土的兄弟们都是疯子，但这个萨格拉斯就是另一回事了……', `MaleText_loc5`='我還是擔心會有風險。雖然我同意瑪法里恩和他那些拉遢的兄弟頗為瘋狂，但這薩格拉斯領主一定有別的計畫...', `MaleText_loc7`='Todavía me preocupan los riesgos. Aunque estoy de acuerdo en que Malfurion y sus hermanos amantes del polvo están bastante locos, este tal Lord Sargeras debe de tener otros planes...' WHERE `ID`=35178;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='쉿! 그만하세요... 누군가 듣기 전에 말입니다.', `FemaleText_loc4`='嘘！安静……不要让别人听到你。', `FemaleText_loc5`='噓!小聲點...別讓人聽到了。', `FemaleText_loc7`='¡Chist! Guarda silencio... antes de que otros te oigan.' WHERE `ID`=35179;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다, $c님.', `MaleText_loc4`='谢谢你，$c。', `MaleText_loc5`='感謝你。$c。', `MaleText_loc7`='Gracias, $c.', `FemaleText_loc1`='감사해요, $c님.', `FemaleText_loc4`='谢谢你，$c。', `FemaleText_loc5`='感謝你。$c。', `FemaleText_loc7`='Gracias, $c.' WHERE `ID`=35180;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들이 갇힌 이들을 죽이고 있습니다! 서둘러 도와주십시오.', `MaleText_loc4`='他们正在屠杀囚犯！赶快行动，去援救其他人。', `MaleText_loc5`='他們正在屠殺囚犯!快點，幫幫他們!', `MaleText_loc7`='¡Están matando a los prisioneros! De prisa, ayuda a los demás.', `FemaleText_loc1`='저들이 갇힌 이들을 죽이고 있어요! 서둘러 도와주세요.', `FemaleText_loc4`='他们正在屠杀囚犯！赶快行动，去援救其他人。', `FemaleText_loc5`='他們正在屠殺囚犯!快點，幫幫他們!', `FemaleText_loc7`='¡Están matando a los prisioneros! De prisa, ayuda a los demás.' WHERE `ID`=35181;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기에서 살아서 나가리라고는 꿈에도 생각하지 못했습니다.', `MaleText_loc4`='我还以为自己再也无法活着离开这里了！', `MaleText_loc5`='我以為我永遠也沒辦法活著離開這裡。', `MaleText_loc7`='Pensé que no saldría de ahí con vida.', `FemaleText_loc1`='여기에서 살아서 나가리라고는 꿈에도 생각하지 못했어요.', `FemaleText_loc4`='我还以为自己再也无法活着离开这里了！', `FemaleText_loc5`='我以為我永遠也沒辦法活著離開這裡。', `FemaleText_loc7`='Pensé que no saldría de ahí con vida.' WHERE `ID`=35182;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기에서 죽을 줄 알았습니다!', `MaleText_loc4`='我还以为我要死在那里了！', `MaleText_loc5`='我以為我大概會死在這裡!', `MaleText_loc7`='¡Pensé que iba a morir allí!', `FemaleText_loc1`='저기에서 죽을 줄 알았답니다!', `FemaleText_loc4`='我还以为我要死在那里了！', `FemaleText_loc5`='我以為我大概會死在這裡!', `FemaleText_loc7`='¡Pensé que iba a morir allí!' WHERE `ID`=35183;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마상시합 따위에 나오지 말았어야 했습니다!', `MaleText_loc4`='我早就知道，我不应该到这场锦标赛来！', `MaleText_loc5`='我就知道我不該來參加聯賽!', `MaleText_loc7`='¡Sabía que no debía haber venido al torneo!', `FemaleText_loc1`='마상시합 따위에 나오지 말았어야 했어요!', `FemaleText_loc4`='我早就知道，我不应该到这场锦标赛来！', `FemaleText_loc5`='我就知道我不該來參加聯賽!', `FemaleText_loc7`='¡Sabía que no debía haber venido al torneo!' WHERE `ID`=35184;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='친구 여러분, 동지 여러분. 좀 진정하십시오.', `MaleText_loc4`='我的朋友们，我的同伴们，请尽管放心。', `MaleText_loc5`='我的朋友，我的工作夥伴，請你們冷靜下來。', `MaleText_loc7`='Amigos míos, colegas. Poneos cómodos.' WHERE `ID`=35185;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얘기한 대로 최근 우리 마력이 약해졌음을 확인하는 중입니다. 자비우스 경께서도 마력의 오르내림은 자연스러운 현상이라 말씀하셨지요.', `MaleText_loc4`='最近，我们的魔法能量逐渐减弱。当我们说话的时候，这一现象正在被评估。不过萨维斯大人已经说过，这种魔法能量的波动起伏是正常的。', `MaleText_loc5`='在我們說話的同時，我們最近魔力的減退也正在被調查當中。就連領主薩維斯也說這種魔力減退的現象是正常的。', `MaleText_loc7`='La reciente disminución de nuestros poderes mágicos está siendo revisada ahora mismo. Incluso Lord Xavius ha dicho que el flujo de magia es normal.' WHERE `ID`=35186;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러나 뒤틀린 황천에서 나온 새 동맹이 다른 마력의 원천과 우리 마법에서 아직 밝혀지지 않은 기술을 알려주겠다고 약속합니다. 아즈샤라 여왕께서 여러분을 믿듯이, 여러분께서도 여왕님을 계속 믿고 따르십시오.', `MaleText_loc4`='不管怎样，我们来自扭曲虚空的新盟友将为我们带来新的能量源泉和无可言喻的魔法技艺。相信艾萨拉女士吧，就如同她相信你一样。', `MaleText_loc5`='但是，我們位於扭曲虛空之中的新盟友保證了將給予我們新的力量之源，和數不清的魔法知識。對艾薩拉女士有信心，就像她一向對你們有信心一樣。', `MaleText_loc7`='Pero nuestros nuevos aliados, creados dentro de El Vacío Abisal nos han prometido nuevas Fuentes de poder y dominio sin igual de nuestra magia. Tengan fe en Lady Azshara, al igual que ella la tiene en ustedes.' WHERE `ID`=35187;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 열렬히 고개를 끄덕입니다.', `MaleText_loc4`='%s热切地点着头。', `MaleText_loc5`='%s和藹的點了點頭。', `MaleText_loc7`='%s asiente amablemente.' WHERE `ID`=35188;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 가지 말고 서류를 보여주십시오.', `MaleText_loc4`='请先让我看看你的公文。', `MaleText_loc5`='在繼續前請讓我看看你的文件。', `MaleText_loc7`='Muéstrame tus documentos antes de comenzar.' WHERE `ID`=35189;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 황천의 차원문을 엽니다!', `MaleText_loc4`='%s创造出了一个虚空传送门！', `MaleText_loc5`='%s製造了一個虛空傳送門!', `MaleText_loc7`='¡%s crea un portal abisal!' WHERE `ID`=35190;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; |cFF00FF00지옥불 화산|r을 일으킵니다!', `MaleText_loc4`='%s创造出了一个|cFF00FF00地狱火山！|r', `MaleText_loc5`='%s製造了一座|cFF00FF00煉獄火山!|r', `MaleText_loc7`='¡%s crea un |cFF00FF00Volcán infernal!|r' WHERE `ID`=35191;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여왕 폐하의 명에 따라, 도시로 들어오기 전에 모든 소지품을 검사받아야 합니다.', `MaleText_loc4`='根据女王的命令，一切物品都要经过检查才能进城。', `MaleText_loc5`='依照女王的命令，所有持有物都必須受到檢驗才允許進入城中。', `MaleText_loc7`='Por orden de la Reina, todas las posesiones han de ser investigadas antes de permitir la entrada en la ciudad.' WHERE `ID`=35192;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조금만 기다리십시오. 곧 차례가 돌아옵니다.', `MaleText_loc4`='耐心，耐心。我们很快就会加入你了。', `MaleText_loc5`='耐心點，耐心點。我們很快就會跟你碰面。', `MaleText_loc7`='Paciencia, paciencia. Pronto estaremos contigo.' WHERE `ID`=35193;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; |cFFFF0000군단 불꽃|r의 대상이 되었습니다!', `MaleText_loc4`='$n中了|cFFFF0000军团烈焰！|r', `MaleText_loc5`='$n中了|cFFFF0000軍團烈焰|r!', `MaleText_loc7`='¡$n tiene |cFFFF0000Llamas de la Legión!|r' WHERE `ID`=35194;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; |cFF00FFFF살점 소각|r에 걸렸습니다!', `MaleText_loc4`='$n受到了|cFF00FFFF血肉成灰|r效果的影响！', `MaleText_loc5`='$n中了|cFF00FFFF焚化血肉!|r', `MaleText_loc7`='¡$n tiene |cFF00FFFFIncinerar carne|r!' WHERE `ID`=35195;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놓는 중', `MaleText_loc4`='放置', `MaleText_loc5`='放置中', `MaleText_loc7`='Preparando', `FemaleText_loc1`='놓는 중', `FemaleText_loc4`='放置', `FemaleText_loc5`='放置中', `FemaleText_loc7`='Preparando' WHERE `ID`=35196;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 일리아나. 그대의 눈은 너무나도 아름답소.', `MaleText_loc4`='哦，伊琳娜，你的眼睛，它们是那样美丽。', `MaleText_loc5`='噢，伊琳娜，妳的眼睛是那麼的漂亮。', `MaleText_loc7`='Oh, Illyanna, tus ojos son preciosos.' WHERE `ID`=35197;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='맞아요. 당신 모습만 안 본다면 더 아름답게 빛나겠죠.', `FemaleText_loc4`='是的，如果没有你的影子落在它们上面，它们会更加美丽的。', `FemaleText_loc5`='嗯。如果沒有你的倒影在裡面它們會更漂亮。', `FemaleText_loc7`='Sí. Y son todavía más bonitos sin tu reflejo.' WHERE `ID`=35198;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일리아나, 왜 그리도 차갑게 구오? 그대 부탁이라면 거미로 그물 짜서 저 하늘의 태양이라도 따 올 텐데!', `MaleText_loc4`='伊琳娜，为什么你要拒绝我？只要你说一句话，我甚至能织出一张网，为你捉住太阳。', `MaleText_loc5`='伊琳娜，為什麼將我一腳踢開?妳一句話，我甚至可以拿網子把太陽套下來給妳!', `MaleText_loc7`='Illyanna, ¿por qué me rechazas? ¡Tejería una red para atrapar el sol si tú me lo pidieras!' WHERE `ID`=35199;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그러면 어서 가서 따오지 그러세요? 제 친구와 저는 좀 중요한 일이 있거든요!', `FemaleText_loc4`='那么你不赶快去做这件事？我的朋友们和我还有更重要的事要去做呢！', `FemaleText_loc5`='那你為什麼不這樣做?我和我的朋友有更重要的事要做!', `FemaleText_loc7`='Entonces, ¿por qué no vas y haces eso? ¡Mis amigos y yo tenemos cosas mejores que hacer!' WHERE `ID`=35200;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대를 이 품에 안는다면 더 바랄 게 없겠소. 이리 내려오시오. 이곳을 떠나 멀리멀리 갑시다!', `MaleText_loc4`='如果能将你揽在臂弯里，那就是我梦想成真的时刻。从那里下来吧，让我们去旅行，远远地离开这里！', `MaleText_loc5`='將你擁抱在我的懷裡是我一直以來的夢想。下來吧，讓我們一起遠離此地!', `MaleText_loc7`='Tenerte entre mis brazos haría realidad mis sueños. ¡Baja de allí y viajemos lejos de aquí!' WHERE `ID`=35201;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='먼저 이곳을 떠나 멀리멀리 가세요. 머리 좀 빗고 바로 따라갈 테니까요.', `FemaleText_loc4`='你先去旅行吧，我做好头发之后就去追你。', `FemaleText_loc5`='你自己先上路，我等晚點頭髮弄好了會趕上的。', `FemaleText_loc7`='Adelante, ponte en camino. Me reuniré contigo en cuanto termine de acicalarme el cabello.' WHERE `ID`=35202;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 일리아나. 사랑하오!', `MaleText_loc4`='哦，伊琳娜，我爱你！', `MaleText_loc5`='噢，伊琳娜，我愛妳!', `MaleText_loc7`='¡Oh, Illyanna, te amo!' WHERE `ID`=35203;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 몸서리를 칩니다.', `FemaleText_loc4`='%s打了个哆嗦。', `FemaleText_loc5`='%s發抖。', `FemaleText_loc7`='%s se estremece.' WHERE `ID`=35204;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 생애 최고의 순간이었소...', `MaleText_loc4`='这是我生命中最伟大的时刻……', `MaleText_loc5`='那是我一生中最快樂的時刻...', `MaleText_loc7`='Ese ha sido el mejor momento de mi vida...' WHERE `ID`=35205;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저리 가세요, 이 막돼먹은 불한당 같으니! 처음 봤을 때 얼굴에 던진 제 장화 맛이 기억 안 나나 보죠?', `FemaleText_loc4`='离我远点，下贱的渣滓！否则小心我的靴子踹到你的脸上！', `FemaleText_loc5`='離我遠點，低下的雜種!你大概忘了是誰讓你臉上第一次出現了鞋印。', `FemaleText_loc7`='¡Aléjate de mí, escoria de baja estofa! ¡Quizá la primera vez no notaste mi bota en tu cara!' WHERE `ID`=35206;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 키득거리며 웃습니다.', `MaleText_loc4`='%s“咯咯”地笑着。', `MaleText_loc5`='%s咯咯地笑。', `MaleText_loc7`='%s suelta una risita.', `FemaleText_loc1`='%s|1이;가; 키득거리며 웃습니다.', `FemaleText_loc4`='%s“咯咯”地笑着。', `FemaleText_loc5`='%s咯咯地笑。', `FemaleText_loc7`='%s suelta una risita.' WHERE `ID`=35207;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='쌍둥이 자매가 분노에 휩싸여 광폭해집니다!', `FemaleText_loc4`='瓦格里双子开始狂暴了！', `FemaleText_loc5`='雙子姊妹進入狂暴之怒!', `FemaleText_loc7`='¡Las hermanas muestran ira rabiosa!' WHERE `ID`=35208;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오세요, 오세요! 한 분씩 차례로요.', `FemaleText_loc4`='进来，进来！一次一个。', `FemaleText_loc5`='進來，進來!一個一個來。', `FemaleText_loc7`='¡Adelante, adelante! De uno en uno.' WHERE `ID`=35209;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마음속에 생각해 두셨던 것이 저희 물건 중에 있는지 살펴보세요. 최고급 마법부여에서 최신 유행 제품까지 모두 있답니다.', `FemaleText_loc4`='尽情观赏我的各种器具吧！从最精巧的魔法器皿，到最时髦的先锋派风格，你在这里全都能看到。', `FemaleText_loc5`='看看我讓你們心跳加快的商品!從最精細的附魔到最流行的東西，應有盡有。', `FemaleText_loc7`='¡Curiosea entre mis mercancías hasta quedar satisfecho! Aquí podrás encontrar desde los mejores encantamientos hasta lo último en moda.' WHERE `ID`=35210;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내일 일은 내일 걱정하고 오늘 지르세요. 이렇게 좋은 물건을 언제 다시 만날지 모르잖아요.', `FemaleText_loc4`='我建议你要以倾家荡产的豪情进行购买。谁能知道你在什么时候还有机会买到这么好的东西呢？', `FemaleText_loc5`='我建議你們拋下一切瘋狂地搶購。下次碰到這麼棒的折扣不知道是何年何月了!', `FemaleText_loc7`='Te recomiendo que compres como si mañana fuera a acabarse el mundo. Quién sabe cuánto tiempo tendrá que pasar hasta que encuentres chollos como los míos.' WHERE `ID`=35211;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이것만은 꼭 말씀드리고 싶은데요. 죽었다 깨나도 그렇게 유행 지난 옷은 입지 마세요!', `FemaleText_loc4`='千万不要再执迷于那些过时的风格了！', `FemaleText_loc5`='我要說的是，千萬不要做個退流行的俗氣之人。', `FemaleText_loc7`='¡Todo lo que digo es que será mejor que no te pillen muerto vestido con esas ropas pasadas de moda!' WHERE `ID`=35212;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 야수들은 굉장한 족속입니다. 저들에게 졌다고 해서 부끄러워할 필요는 없습니다.', `MaleText_loc4`='那些猛兽实在是令人惊愕。被他们打败绝不是什么羞耻的事情。', `MaleText_loc5`='那些野獸是驚人的對手。你不需要因為被他們擊敗而感到羞愧。', `MaleText_loc7`='Esas bestias son unos especímenes increíbles. No deberían avergonzarse porque los hayan derrotado.' WHERE `ID`=35213;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훌륭합니다! 다음 도전에 나설 준비가 되면 알려주십시오.', `MaleText_loc4`='你干得真漂亮！等你再次准备好以后，就立刻通知我。', `MaleText_loc5`='太棒啦!等你準備好再來一次的時候告訴我。', `MaleText_loc7`='¡Excelente! Avísenme cuando vuelvan a estar preparados.' WHERE `ID`=35214;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 야수들과 한 번 더 싸워보고 싶습니다!', `MaleText_loc4`='我们要向这些野兽再发出狠狠的一击！', `MaleText_loc5`='我們希望再度挑戰那些野獸!', `MaleText_loc7`='¡Queremos volver a intentarlo contra esas bestias!', `FemaleText_loc1`='저 야수들과 한 번 더 싸워보고 싶어요!', `FemaleText_loc4`='我们要向这些野兽再发出狠狠的一击！', `FemaleText_loc5`='我們希望再度挑戰那些野獸!', `FemaleText_loc7`='¡Queremos volver a intentarlo contra esas bestias!' WHERE `ID`=35215;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희는 준비됐습니다. 이번에는 다를 겁니다.', `MaleText_loc4`='我们已经准备好了。这一次情况就不一样了。', `MaleText_loc5`='我們準備好了。這次肯定會不一樣。', `MaleText_loc7`='Estamos preparados. Esta vez las cosas serán distintas.', `FemaleText_loc1`='저희는 준비됐어요. 이번에는 다를 거예요.', `FemaleText_loc4`='我们已经准备好了。这一次情况就不一样了。', `FemaleText_loc5`='我們準備好了。這次肯定會不一樣。', `FemaleText_loc7`='Estamos preparados. Esta vez las cosas serán distintas.' WHERE `ID`=35216;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정복의 섬에서 싸울 만큼 강하지는 않군. 가서 경험을 더 쌓고 오시오.', `MaleText_loc4`='你还不具备足够的力量来参与征服之岛的战斗。等你获得更多经验以后再回来吧。', `MaleText_loc5`='你的等級還不足以參加征服之島的戰鬥。等你獲得更多經驗的時候再回來。', `MaleText_loc7`='Todavía no eres suficientemente fuerte para luchar en la Isla de la Conquista. Vuelve cuando hayas ganado más experiencia.', `FemaleText_loc1`='정복의 섬에서 싸울 만큼 강하지는 않군요. 가서 경험을 더 쌓고 오세요.', `FemaleText_loc4`='你还不具备足够的力量来参与征服之岛的战斗。等你获得更多经验以后再回来吧。', `FemaleText_loc5`='你的等級還不足以參加征服之島的戰鬥。等你獲得更多經驗的時候再回來。', `FemaleText_loc7`='Todavía no eres suficientemente fuerte para luchar en la Isla de la Conquista. Vuelve cuando hayas ganado más experiencia.' WHERE `ID`=35217;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정복의 섬엔 호드 손에 넘겨줄 수 없는 귀중한 자원이 가득하오. 당신도 함께 싸우겠소?', `MaleText_loc4`='征服之岛上有许多非常重要的物资，我们绝不能让它落入部落的手中。你愿意加入我们的战斗吗？', `MaleText_loc5`='征服之島充滿了珍貴的資源，我們絕不能讓它落入部落之手。你願意加入戰鬥嗎?', `MaleText_loc7`='La Isla de la Conquista está repleta de valiosos recursos que no podemos permitir que caigan en manos de la Horda. ¿Te unirás a la lucha?', `FemaleText_loc1`='정복의 섬엔 호드 손에 넘겨줄 수 없는 귀중한 자원이 가득하지요. 당신도 함께 싸우시겠어요?', `FemaleText_loc4`='征服之岛上有许多非常重要的物资，我们绝不能让它落入部落的手中。你愿意加入我们的战斗吗？', `FemaleText_loc5`='征服之島充滿了珍貴的資源，我們絕不能讓它落入部落之手。你願意加入戰鬥嗎?', `FemaleText_loc7`='La Isla de la Conquista está repleta de valiosos recursos que no podemos permitir que caigan en manos de la Horda. ¿Te unirás a la lucha?' WHERE `ID`=35218;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정복의 섬엔 얼라이언스 손에 넘겨줄 수 없는 귀중한 자원이 가득하네. 자네도 함께 싸우겠나?', `MaleText_loc4`='征服之岛上有许多非常重要的物资，我们绝不能让它落入联盟的手中。你愿意加入我们的战斗吗？', `MaleText_loc5`='征服之島充滿了珍貴的資源，我們絕不能讓它落入聯盟之手。你願意加入戰鬥嗎?', `MaleText_loc7`='La Isla de la Conquista está repleta de valiosos recursos que no podemos permitir que caigan en manos de la Alianza. ¿Te unirás a la lucha?', `FemaleText_loc1`='정복의 섬엔 얼라이언스 손에 넘겨줄 수 없는 귀중한 자원이 가득하네. 자네도 함께 싸우겠나?', `FemaleText_loc4`='征服之岛上有许多非常重要的物资，我们绝不能让它落入联盟的手中。你愿意加入我们的战斗吗？', `FemaleText_loc5`='征服之島充滿了珍貴的資源，我們絕不能讓它落入聯盟之手。你願意加入戰鬥嗎?', `FemaleText_loc7`='La Isla de la Conquista está repleta de valiosos recursos que no podemos permitir que caigan en manos de la Alianza. ¿Te unirás a la lucha?' WHERE `ID`=35219;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신더브루 고글을 갖고 싶습니다.', `MaleText_loc4`='我想要一副合成酿酒护目镜。', `MaleText_loc5`='我想要一副模擬醉眼護目鏡。', `MaleText_loc7`='Quiero un par de gafas birratizadoras.', `FemaleText_loc1`='신더브루 고글을 갖고 싶어요.', `FemaleText_loc4`='我想要一副合成酿酒护目镜。', `FemaleText_loc5`='我想要一副模擬醉眼護目鏡。', `FemaleText_loc7`='Quiero un par de gafas birratizadoras.' WHERE `ID`=35220;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 모두가 가을 축제를 즐기기를 바랍니다. 몇 명이라도 가을 축제를 기억해준다면 힘이 될 거예요.$b$b이 고글을 쓰면 누구나 취한 것 같은 기분을 느낄 수 있습니다. 아무것도 안 마셔도요. 고글을 쓰기만 하면, 취한 거나 마찬가집니다! 벗으면 다시 말짱해지는 거고요!$b$b어때요, 갖고 싶지 않습니까?', `MaleText_loc4`='我们希望所有人都会在美酒节中得到乐趣。如果能让人记住它就更好了。$b$b这副眼镜能够让每一个人都体验到喝醉时的感觉，却不必喝下许多烈酒。带上这副眼镜吧，这样你就喝醉了！只要摘下它，你就能立刻恢复清醒！$b$b你对这副眼镜有兴趣吗？', `MaleText_loc5`='我們希望每個人在啤酒節都玩得開心。這也能幫助我們大家記住這個節日。$b$b這些眼鏡讓任何人都能體驗酒醉的感覺，但什麼也不需要喝。只要戴上眼鏡，你就跟喝醉了一樣!拿下來，你又清醒啦!$b$b你有興趣來一副嗎?', `MaleText_loc7`='Queremos que todo el mundo se divierta en la Fiesta de la Cerveza. También ayudaría que la gente se acordara.$B$BEstas gafas permiten que cualquiera experimente lo que es estar borracho, pero sin tener que beber. ¡Ponte las gafas y estarás $gborracho:borracha;! ¡Quítatelas y estarás $gsobrio:sobria;!$B$B¿Te interesa un par?', `FemaleText_loc1`='우리는 모두가 가을 축제를 즐기기를 바랍니다. 몇 명이라도 가을 축제를 기억해준다면 힘이 될 거예요.$b$b이 고글을 쓰면 누구나 취한 것 같은 기분을 느낄 수 있습니다. 아무것도 안 마셔도요. 고글을 쓰기만 하면, 취한 거나 마찬가집니다! 벗으면 다시 말짱해지는 거고요!$b$b어때요, 갖고 싶지 않습니까?', `FemaleText_loc4`='我们希望所有人都会在美酒节中得到乐趣。如果能让人记住它就更好了。$b$b这副眼镜能够让每一个人都体验到喝醉时的感觉，却不必喝下许多烈酒。带上这副眼镜吧，这样你就喝醉了！只要摘下它，你就能立刻恢复清醒！$b$b你对这副眼镜有兴趣吗？', `FemaleText_loc5`='我們希望每個人在啤酒節都玩得開心。這也能幫助我們大家記住這個節日。$b$b這些眼鏡讓任何人都能體驗酒醉的感覺，但什麼也不需要喝。只要戴上眼鏡，你就跟喝醉了一樣!拿下來，你又清醒啦!$b$b你有興趣來一副嗎?', `FemaleText_loc7`='Queremos que todo el mundo se divierta en la Fiesta de la Cerveza. También ayudaría que la gente se acordara.$B$BEstas gafas permiten que cualquiera experimente lo que es estar borracho, pero sin tener que beber. ¡Ponte las gafas y estarás $gborracho:borracha;! ¡Quítatelas y estarás $gsobrio:sobria;!$B$B¿Te interesa un par?' WHERE `ID`=35221;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신더브루 고글이 뭡니까?', `MaleText_loc4`='什么是合成酿酒护目镜？', `MaleText_loc5`='模擬醉眼護目鏡?', `MaleText_loc7`='¿Qué es eso de las gafas birratizadoras?', `FemaleText_loc1`='신더브루 고글이 뭔가요?', `FemaleText_loc4`='什么是合成酿酒护目镜？', `FemaleText_loc5`='模擬醉眼護目鏡?', `FemaleText_loc7`='¿Qué es eso de las gafas birratizadoras?' WHERE `ID`=35222;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이전에 하신 얘기가 뭐였습니까?', `MaleText_loc4`='你刚才说什么？', `MaleText_loc5`='你之前說什麼?', `MaleText_loc7`='¿Qué has dicho antes?', `FemaleText_loc1`='이전에 하신 얘기가 뭐였죠?', `FemaleText_loc4`='你刚才说什么？', `FemaleText_loc5`='你之前說什麼?', `FemaleText_loc7`='¿Qué has dicho antes?' WHERE `ID`=35223;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 아직 전장에 참여할 수준이 아닐세. 경험을 더 쌓은 다음에 오게나.', `MaleText_loc4`='想要踏入战场，你还没有足够的阅历。$c。等你获得更多经验以后再回来吧。', `MaleText_loc5`='你還不夠老練到足以進入一個戰場，$c。等你獲得更多經驗的時候再回來。', `MaleText_loc7`='Todavía no estás $gpreparado:preparada; para entrar en un campo de batalla, $c. Vuelve cuando hayas ganado más experiencia.', `FemaleText_loc1`='당신은 아직 전장에 참여할 수준이 아닙니다. 경험을 더 쌓은 다음에 오십시오.', `FemaleText_loc4`='想要踏入战场，你还没有足够的阅历。$c。等你获得更多经验以后再回来吧。', `FemaleText_loc5`='你還不夠老練到足以進入一個戰場，$c。等你獲得更多經驗的時候再回來。', `FemaleText_loc7`='Todavía no estás $gpreparado:preparada; para entrar en un campo de batalla, $c. Vuelve cuando hayas ganado más experiencia.' WHERE `ID`=35224;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드를 위해 싸울 준비는 됐나, $c?', `MaleText_loc4`='你是否已经准备好了为部落而战，$c？', `MaleText_loc5`='你準備好要為了部落而戰嗎，$c?', `MaleText_loc7`='¿Estás $gpreparado:preparada; para luchar por la Horda, $c?', `FemaleText_loc1`='호드를 위해 싸울 준비는 되셨습니까, $c님?', `FemaleText_loc4`='你是否已经准备好了为部落而战，$c？', `FemaleText_loc5`='你準備好要為了部落而戰嗎，$c?', `FemaleText_loc7`='¿Estás $gpreparado:preparada; para luchar por la Horda, $c?' WHERE `ID`=35225;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스를 위해 싸울 준비는 되셨습니까, $c님?', `MaleText_loc4`='你是否已经准备好了为联盟而战，$c？', `MaleText_loc5`='你準備好要為了聯盟而戰嗎，$c?', `MaleText_loc7`='¿Estás $gpreparado:preparada; para luchar por la Alianza, $c?', `FemaleText_loc1`='얼라이언스를 위해 싸울 준비는 되셨습니까, $c님?', `FemaleText_loc4`='你是否已经准备好了为联盟而战，$c？', `FemaleText_loc5`='你準備好要為了聯盟而戰嗎，$c?', `FemaleText_loc7`='¿Estás $gpreparado:preparada; para luchar por la Alianza, $c?' WHERE `ID`=35226;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 바다의 왕인 드로틴 흐로스가르에게 도전하느냐?', `MaleText_loc4`='你竟敢挑战德罗丁·洛斯加尔，诸海之王？', `MaleText_loc5`='你膽敢挑戰眾海之王多廷·赫魯斯加?', `MaleText_loc7`='¿Te atreves a retar a Drottinn Hrothgar, rey de los mares?' WHERE `ID`=35227;
