UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당당하고 힘찬 스톰윈드의 최고 용사, 작전사령관 제이콥 알레리우스에게 힘찬 박수 부탁합니다!', `MaleText_loc4`='请向骄傲而强壮的暴风城总冠军，雅克布·奥勒留斯元帅欢呼吧！', `MaleText_loc5`='輝煌而強壯，讓我們為傑科布·亞雷瑞斯元帥歡呼，暴風城大勇士!', `MaleText_loc7`='Fuerte y orgulloso, ¡aclamad al mariscal Jacob Alerius, el Gran Campeón de Ventormenta!' WHERE `ID`=35245;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 진정한 강인함이 뭔지 이 드워프가 보여 드립니다. 아이언포지의 최고 용사, 라나 스타우트해머를 소개합니다!', `MaleText_loc4`='今天，矮人的力量将在铁炉堡的总冠军，拉娜·硬锤的身上得以展现！', `MaleText_loc5`='矮人的力量今天將由鐵爐堡大勇士來展現，菈娜·頑錘!', `MaleText_loc7`='Hoy el poder de los enanos está representado por la Gran Campeona de Forjaz, Lana Martillotenaz.' WHERE `ID`=35246;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위풍당당한 엑소다르의 최고 용사, 콜로소스가 걸어나오고 있습니다!', `MaleText_loc4`='从大门中走出来的是克罗索斯，埃索达强大的总冠军！', `MaleText_loc5`='穿過大門的是克羅索斯，高大傑出的艾克索達大勇士!', `MaleText_loc7`='Colosos, el enorme Gran Campeón de El Exodar, está saliendo por la puerta.' WHERE `ID`=35247;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='작지만 무시무시한 놈리건의 최고 용사, 암브로스 볼트스파크입니다!', `MaleText_loc4`='现在出场的是矮小却极度致命的安布罗斯·雷钉，诺莫瑞根的总冠军！', `MaleText_loc5`='現在出場的是嬌小卻致命的安布羅斯·拴炫，諾姆瑞根大勇士!', `MaleText_loc7`='Aquí llega el pequeño pero mortal Ambrose Chisparrayo, Gran Campeón de Gnomeregan.' WHERE `ID`=35248;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 투기장에 다르나서스의 최고 용사이자 노련한 파수꾼인 제일린 이븐송이 들어서고 있습니다!', `MaleText_loc4`='进入竞技场的是达纳苏斯的总冠军，战技非凡的娅琳·永歌！', `MaleText_loc5`='達納蘇斯大勇士現在進入了競技場，技藝高超的哨兵潔琳·晚歌!', `MaleText_loc7`='Está entrando en la arena la Gran Campeona de Darnassus, la hábil centinela Jaelyne Unicanto.' WHERE `ID`=35249;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘하셨습니다! 저런 야수들을 상대로 멋진 전투를 벌이셨군요! 다음 도전은 훨씬 더 까다롭다고 합니다!', `MaleText_loc4`='干得好！你竟然打败了所有这些猛兽，这简直太神奇了！不过，我听说下一个挑战将更加艰难！', `MaleText_loc5`='幹得好!你和那些野獸的戰鬥非常精采!我聽說下一場挑戰將會更困難!', `MaleText_loc7`='¡Bien hecho! ¡Has luchado contra esas bestias de forma espléndida! ¡He oído que el siguiente reto será más duro!' WHERE `ID`=35250;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 도전이 저희를 기다리고 있습니까?', `MaleText_loc4`='有什么新的挑战正等待着我们？', `MaleText_loc5`='還有什麼新挑戰在等著我們?', `MaleText_loc7`='¿Qué nuevo reto nos aguarda?', `FemaleText_loc1`='어떤 도전이 저희를 기다리고 있나요?', `FemaleText_loc4`='有什么新的挑战正等待着我们？', `FemaleText_loc5`='還有什麼新挑戰在等著我們?', `FemaleText_loc7`='¿Qué nuevo reto nos aguarda?' WHERE `ID`=35251;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금은 저 뒤에서 군주 자락서스를 잡아두고는 있지만, 그렇게 오래 묶어놓을 수는 없습니다.', `MaleText_loc4`='现在我们暂时压制住了加拉克苏斯大王，但我们不可能压制住他太长时间。', `MaleText_loc5`='我們現在勉強擋住賈拉克瑟斯領主，但我們撐不了太久。', `MaleText_loc7`='De momento estamos reteniendo a Lord Jaraxxus, pero no podremos mantenerlo amarrado mucho tiempo más.' WHERE `ID`=35252;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곧 알 수 있겠지요. 다음 도전에 나설 준비는 되셨습니까?', `MaleText_loc4`='敌人将有多么强大，你很快就会知道了。现在，你是否已经准备好了迎接下一场挑战？', `MaleText_loc5`='你們很快就會知道了。準備好接受下一場挑戰了嗎?', `MaleText_loc7`='Pronto lo descubrirás. ¿Estás $gpreparado:preparada; para el siguiente reto?' WHERE `ID`=35253;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 마술을 부리는 군주와 다시 한 번 싸워 볼 준비가 되었습니다.', `MaleText_loc4`='我们已经准备好了再次同那名法师作战。', `MaleText_loc5`='我們準備好再次跟巫士一戰。', `MaleText_loc7`='Estamos preparados para luchar contra el hechicero de nuevo.', `FemaleText_loc1`='그 마술을 부리는 군주와 다시 한 번 싸워 볼 준비가 되었어요.', `FemaleText_loc4`='我们已经准备好了再次同那名法师作战。', `FemaleText_loc5`='我們準備好再次跟巫士一戰。', `FemaleText_loc7`='Estamos preparados para luchar contra el hechicero de nuevo.' WHERE `ID`=35254;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕, 자기! 이 옷 어때요?', `FemaleText_loc4`='嗨！我看起来如何？', `FemaleText_loc5`='嗨，寶貝!我看起來如何?', `FemaleText_loc7`='¡Eh, cariño! ¿Qué tal estoy?' WHERE `ID`=35255;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋습니다. 신호만 주시면 봉인을 풀겠습니다.', `MaleText_loc4`='这太好了，一定及时给我信号，让我知道该在什么时候放下那些法术。', `MaleText_loc5`='太好了，等要撤掉束縛法術的時候，給我個信號就行了。', `MaleText_loc7`='Eso es genial, tan solo hazme una señal para que detenga los hechizos que lo retienen.' WHERE `ID`=35256;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음 도전에 나설 준비가 되었습니다.', `MaleText_loc4`='我们已经准备好了迎接下一个挑战。', `MaleText_loc5`='我們準備好接受下一場挑戰了。', `MaleText_loc7`='Estamos preparados para el siguiente reto.', `FemaleText_loc1`='다음 도전에 나설 준비가 되었어요.', `FemaleText_loc4`='我们已经准备好了迎接下一个挑战。', `FemaleText_loc5`='我們準備好接受下一場挑戰了。', `FemaleText_loc7`='Estamos preparados para el siguiente reto.' WHERE `ID`=35257;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금입니다.', `MaleText_loc4`='开始。', `MaleText_loc5`='現在。', `MaleText_loc7`='Ahora.', `FemaleText_loc1`='지금이에요.', `FemaleText_loc4`='开始。', `FemaleText_loc5`='現在。', `FemaleText_loc7`='Ahora.' WHERE `ID`=35258;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대영주님, 은빛 서약단에서는 이번 행사에 참가자를 출전시킬 수 있어 기쁘게 생각합니다.', `MaleText_loc4`='银色盟约们很高兴地在此介绍他们的斗士，大领主。', `MaleText_loc5`='白銀誓盟很榮幸地介紹他們這次事件的參與者，大領主。', `MaleText_loc7`='El Pacto de Plata está encantado de presentar a sus luchadores para este evento, Alto Señor.' WHERE `ID`=35259;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선리버에서는 이 시험에서 싸울 대표단을 출전시킬 수 있어 자랑스럽습니다.', `MaleText_loc4`='夺日者们自豪地介绍他们在这场竞赛中的代表。', `MaleText_loc5`='奪日者很驕傲地介紹他們這次試煉之戰的代表。', `MaleText_loc7`='Los Atracasol están orgullosos de presentar a sus representantes en estas pruebas de combate.' WHERE `ID`=35260;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신을 향한 제 마음, 알고 계시죠?', `MaleText_loc4`='我可真喜欢你！你相信我？是吗？', `MaleText_loc5`='你太漂亮了!你相信我所說的，對吧，寶貝?', `MaleText_loc7`='¡Te adoro! Me crees, ¿verdad, cariño?' WHERE `ID`=35261;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='보고 싶었어요! 어딜 다녀온 거예요?$B$B대답 안 해요? 그냥 서 있을 건가요?', `FemaleText_loc4`='我真想念你！你到哪里去了？$B$B你真的不愿意理我吗？', `FemaleText_loc5`='我好想你!你到哪裡去了?$B$B你打算回答我的問題嗎?還是就站在那?', `FemaleText_loc7`='¡Te he echado tanto de menos! ¿Dónde has estado?$B$B¿Vas a contestarme o simplemente te vas a quedar ahí de pie?' WHERE `ID`=35262;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 옷 어때요? 파티를 위해 준비했어요. 물론 당신 카드로 계산했죠.', `FemaleText_loc4`='你喜欢我的这身打扮吗？这可是为聚会准备的。我用你的帐户买的。', `FemaleText_loc5`='你喜歡我的裝扮嗎?是買來參加派對的。我用你帳戶裡的錢買的。', `FemaleText_loc7`='¿Te gusta mi modelito? Es para la fiesta. Lo he cargado a tu cuenta.' WHERE `ID`=35263;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='방금 어떤 남자가 저한테 집적댔어요. 어떻게 감히!$B$B가서 좀 혼내주면 안 될까요, 자기? 그래 줄 거죠? 고마워요!', `FemaleText_loc4`='又有个家伙打了我。哦，这可真让人气恼！$B$B你愿意帮我打他一顿吗，甜心？谢谢，我真爱你！', `FemaleText_loc5`='又有個男生拜倒在我的石榴裙下了。噢，我的天啊!$B$B你可以幫我教訓他一下嗎，寶貝?謝謝囉，最愛你了!', `FemaleText_loc7`='Había un tío que estaba tirándome los tejos. ¡Qué sinvergüenza!$B$B¿Irás a darle una paliza por mí, cariñín? Gracias. ¡Te quiero!' WHERE `ID`=35264;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 최고의 자리에 오를 그날이 정말 기다려져요. 생각해 보세요. 전 무역왕비가 될 거예요.$B$B당연히 그동안 사고 싶었던 것들도 모두 사야죠!!!', `FemaleText_loc4`='我全心全意地期待着你晋升到顶点的那一天。想一想，那时我就是贸易大王的太太。$B$B我还能去买下我一直想买的所有东西！！！', `FemaleText_loc5`='我等不及你登上最高峰的那一天了。你想想，我可以稱自己為貿易親王夫人。$B$B更別提那些我已經渴望以久的東西了!!!', `FemaleText_loc7`='No puedo esperar a que llegue el día en el que estés en lo más alto. Piénsalo, podré hacerme llamar Señora de Príncipe mercante.$B$B¡¡Y podré comprarme todo lo que siempre he querido, o sea!!' WHERE `ID`=35265;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='밖에 나가서는 몸조심하세요. 남쪽바다 해적들이 만에 나타났다고 해요.$B$B음... 제가 직접 확인해보는 게 좋을 것 같네요...', `FemaleText_loc4`='小心。我听说这片海湾里有南海海盗。$B$B嗯，也许我应该亲自去查看一下……', `FemaleText_loc5`='路上小心。我聽說有南海海賊出現在海灣那。$B$B嗯...或許我應該自己去看看...', `FemaleText_loc7`='Ten cuidado ahí fuera. He oído que hay Piratas de los Mares del Sur en la bahía.$B$BMmm, quizá deba ir a comprobarlo yo misma...' WHERE `ID`=35266;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='카자로 산으로 멋지고 낭만적인 소풍을 가보는 건 어떨까요?$B$B좋아하는 과일 음료는 꼭 챙기시고요!', `FemaleText_loc4`='我们能在卡亚罗山的顶端渡过一个美好、浪漫的野餐日吗？$B$B一定要带我喜欢的香槟来！', `FemaleText_loc5`='我們可以到卡亞羅山享受一次美好和浪漫的野餐嗎?$B$B確保你帶的是我最喜歡的香檳!', `FemaleText_loc7`='¿Podemos ir a hacer un picnic romántico en la cumbre del Monte Kajaro?$B$B¡Asegúrate de coger mi champán favorito, o sea!' WHERE `ID`=35267;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='왜 그렇게 음흉한 눈빛을 하고 있죠? 무슨 일 있었나요, 자기?$B$B네?', `FemaleText_loc4`='你的眼睛里有一种恶作剧的意味。你想要干什么？$B$B嗯？', `FemaleText_loc5`='你的眼神中透露著淘氣的感覺。妳怎麼了啊，寶貝?$B$B感覺好嗎?', `FemaleText_loc7`='Tienes esa mirada traviesa en los ojos. ¿Qué has estado haciendo, cielo?$B$B¿Y bien?' WHERE `ID`=35268;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자기, 어디 있었던 거예요? 아무 소식도 없으면 내가 얼마나 걱정하는데요!', `MaleText_loc4`='甜心，你去哪里了？你是否知道，当我无法联系到你的时候，是多么担心吗！', `MaleText_loc5`='甜心，你到哪去了?你知道如果你不來找我我會有多擔心嗎?', `MaleText_loc7`='Cariño, ¿dónde has estado? ¡Ya sabes lo preocupado que me quedo cuando no me dices dónde andas!' WHERE `ID`=35269;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 복근 어떤가요? 방금 운동하고 오는 길이거든요.$B$B이 정도면 괜찮지 않나요?', `MaleText_loc4`='你觉得我的腹肌如何，亲爱的？我刚刚从健身馆回来。$B$B现在我够健美了吧！', `MaleText_loc5`='你覺得我的腹肌怎樣，寶貝?我剛從健身房回來。$B$B我的身材真是魔鬼!', `MaleText_loc7`='Cariño, ¿qué opinas de mis abdominales? Acabo de salir del gimnasio.$b$b¡Soy un pedazo de carne bastante potable!' WHERE `ID`=35270;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 여자들은 그냥 아는 친구일 뿐이에요, 자기.', `MaleText_loc4`='其她那些女人只是普通朋友，亲爱的。', `MaleText_loc5`='那些女人只是朋友，寶貝。', `MaleText_loc7`='Esas mujeres son solo amigas, cariño.' WHERE `ID`=35271;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='옷 멋진데요!', `MaleText_loc4`='我喜欢你的衣服！', `MaleText_loc5`='我喜歡你的穿著!', `MaleText_loc7`='¡Me gusta eso que llevas puesto!' WHERE `ID`=35272;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지난밤, 그리고 그 전날 밤에도 약속했었지만, 내일 밤에는 정말 멋진 곳에 당신을 데려갈게요!', `MaleText_loc4`='我知道，昨晚和前天晚上我都答应过你。等到明天晚上，我一定会带你去个好地方！', `MaleText_loc5`='我知道我昨晚答應你了，還有前天晚上也是，但我明天晚上會帶你到一個很棒的地方!', `MaleText_loc7`='Sé que te lo prometí ayer por la noche, y la noche anterior, ¡pero ahora te prometo que te llevaré a un sitio muy bonito mañana por la noche!' WHERE `ID`=35273;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='남쪽바다 해적들이 요전에 부두에 나타났다고들 하더군요. 마을에 내려가실 땐 조심하세요!$B$B여자 해적들도 있답니다! 음, 아무래도 제가 직접 나서는 게 좋을까요? 당신의 안전을 위해서 말이죠.', `MaleText_loc4`='听说早些时候南海海盗进入了港口。如果你要进城的话，一定要小心！$B$B那些海盗之中甚至还有女人！嗯，也许我应该亲自去查看一下？这只是为了保护你的安全，亲爱的。', `MaleText_loc5`='我聽說有些南海海賊的船稍早停港了。到城鎮上的時候要小心一點!$B$B他們甚至還有女性海賊!嗯...或許我應該自己去看看?確定你出去不會碰到危險，我的寶貝。', `MaleText_loc7`='He oído que algunos Piratas de los Mares del Sur han llegado a puerto hace poco. ¡Ten cuidado si vas a la ciudad!$B$B¡Incluso tienen mujeres pirata! Mmm, ¿quizá deba ir a comprobarlo yo mismo? Solo para asegurarme de que ahí fuera no hay peligro para ti, cariño.' WHERE `ID`=35275;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='외모와 실력을 겸비한 우리 임원님께서 오셨군요! 요새 일을 처리하시는 걸로 봐서 곧 당신을 무역여왕이라 부를 날이 머지않은 것 같아요, $n 님.$B$B어떻게 기다리죠? 체육관에서 몸 좀 만들고 수영장 옆에서 일광욕이나 해야겠어요.', `MaleText_loc4`='我热辣的公司总监女朋友今天过得如何？既然你已经在管理这么多事情。我想，我们随时都有可能会改称你为贸易女王$n了！我真期待那一天的到来！那样我就能随心所欲地在健身馆健身，在池塘边把皮肤晒成健美的褐色了。', `MaleText_loc5`='我性感的執行長女友今天如何啊?就你現在經營企業的模式，我覺得你被稱為貿易女王$n都不為過!$B$B我已經等不及了!我要到健身房的游泳池把我的皮膚曬成古銅色。', `MaleText_loc7`='¿Qué tal está hoy mi novia maciza directiva de la empresa? ¡En vista de cómo llevas las cosas por aquí, creo que cualquier día tendremos que llamarte Princesa mercante $n!$B$B¡No puedo esperar! Voy a pasar los días haciendo ejercicio en el gimnasio y trabajándome el moreno en la piscina.' WHERE `ID`=35276;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노련한 $c, 자랑스러운 $r, $n|1을;를; 여러분께 소개합니다.', `MaleText_loc4`='一个聪明的$c，一个骄傲的$r。我们非常高兴地把$n介绍给你们。', `MaleText_loc5`='一位老練的$c，值得誇耀的$r。我們很高興地向你們介紹，$n。', `MaleText_loc7`='$gUn astuto:Una astuta; $c, $gun orgulloso:una orgullosa; $r. Estamos orgullosos de presentarles a $n.' WHERE `ID`=35277;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 작업장을 공격했습니다!', `MaleText_loc4`='$n突袭了车间！', `MaleText_loc5`='$n突襲了工坊!', `MaleText_loc7`='¡$n ha atacado el Taller!' WHERE `ID`=35278;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스가 작업장을 점령했습니다!', `MaleText_loc4`='联盟夺取了车间！', `MaleText_loc5`='聯盟奪取了工坊!', `MaleText_loc7`='¡La Alianza ha tomado el Taller!' WHERE `ID`=35279;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드가 작업장을 점령했습니다!', `MaleText_loc4`='部落占领了车间！', `MaleText_loc5`='部落奪取了工坊!', `MaleText_loc7`='¡La Horda ha tomado el Taller!' WHERE `ID`=35280;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가장 맹렬하게 전장을 휘젓는 $c 중 하나인 $n|1을;를; 소개합니다.', `MaleText_loc4`='他是战场上最勇猛的$c之一，让我们来介绍$n。', `MaleText_loc5`='戰場上最勇猛的一位$c，我們向你介紹，$n。', `MaleText_loc7`='$gUno de los:Una de las; $cs más fieros en el campo de batalla, presentamos a $n.' WHERE `ID`=35281;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전장에서 $c|1이;가; 보여준 활약을 말로는 다 설명할 수 없습니다. 자랑스러운 $c, $n|1을;를; 소개합니다.', `MaleText_loc4`='任何语言都无法形容这位$c在战场上的种种功业。我们骄傲地向大家介绍$n。', `MaleText_loc5`='這位$c在戰場上的表現是言語不足以形容的。我們很驕傲地向你介紹，$n。', `MaleText_loc7`='Las palabras apenas pueden describir las hazañas que $geste:esta; $c ha realizado en el campo de batalla. Estamos orgullosos de presentar a $n.' WHERE `ID`=35282;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1을;를; 소개합니다. 전투에서 가장 뛰어난 활약을 보였던 $c 중 하나이지요.', `MaleText_loc4`='我们向大家介绍$n，他是我们至今以来见到的最优秀的$c之一。', `MaleText_loc5`='讓我們向你介紹，$n。我們在實戰中所見最優秀的$c之一。', `MaleText_loc7`='Les presentamos a $n. $gUno:Una; $c $gdigno:digna; de ser $gvisto:vista; en acción.' WHERE `ID`=35283;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 들어보신 적 없는 이름이겠지만, 이 전투가 끝나면 확실히 기억하고도 남으시리라 생각합니다. $n|1을;를; 소개합니다.', `MaleText_loc4`='如果你还不知道这个人的名字，那么你就应该好好看看他的战斗。我们在此向大家介绍$n。', `MaleText_loc5`='如果你還沒有聽過這個名字，我們肯定你一定沒參與到這些戰鬥。讓我們來歡迎，$n。', `MaleText_loc7`='Si todavía no conocen su nombre, estamos seguros de que lo harán después de estos combates. Presentamos a $n.' WHERE `ID`=35284;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새시, 카자마이트 광산까지 다시 데려다 주세요.', `MaleText_loc4`='莎希，给我另一匹坐骑，让我驰向卡亚矿吧。', `MaleText_loc5`='賽希，再帶我去卡迦邁礦場一次。', `MaleText_loc7`='Sassy, dame otra vuelta por la mina de kaja''mita.', `FemaleText_loc1`='새시, 카자마이트 광산까지 다시 데려다 주세요.', `FemaleText_loc4`='莎希，给我另一匹坐骑，让我驰向卡亚矿吧。', `FemaleText_loc5`='賽希，再帶我去卡迦邁礦場一次。', `FemaleText_loc7`='Sassy, dame otra vuelta por la mina de kaja''mita.' WHERE `ID`=35285;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 작업장을 방어했습니다!', `MaleText_loc4`='$n守住了车间！', `MaleText_loc5`='$n守住了工坊!', `MaleText_loc7`='¡$n ha defendido el Taller!' WHERE `ID`=35286;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 와! 여기 트롤 노예들이 미쳐가고 있어!$B$B그나마 카자마이트가 놈들의 우둔한 머리를 똑똑하게 만들어주지 않은 게 다행이지 않나?', `MaleText_loc4`='嗨，头儿。这批巨魔奴隶可是我见过的最糟糕的一批！$B$B幸运的是，卡亚矿石似乎并没有让他们的豆腐渣脑子变得更聪明一些，对不对？', `MaleText_loc5`='嗨，老大。這群食人妖奴隸真是有史以來最不聽話的!$B$B還好，卡迦邁礦好像沒有讓他們的笨腦袋變聰明，對吧?', `MaleText_loc7`='¡Hola $gjefe:jefa;! ¡Este envío de esclavos trols es el peor que hemos recibido hasta ahora!$B$BSuerte que la kaja''mita no ha estimulado sus blandos cerebros para hacerlos más inteligentes, ¿eh?' WHERE `ID`=35289;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='댐윅! 지금 바로 본부로 돌아가야겠어요! 당장!', `MaleText_loc4`='戴姆维克，我立马赶回总部，马上！', `MaleText_loc5`='唐威克，我需要你載我回總部，現在!', `MaleText_loc7`='¡Mechamojada, necesito una montura para regresar al cuartel general, rápido!', `FemaleText_loc1`='댐윅! 지금 바로 본부로 돌아가야겠어요! 당장!', `FemaleText_loc4`='戴姆维克，我立马赶回总部，马上！', `FemaleText_loc5`='唐威克，我需要你載我回總部，現在!', `FemaleText_loc7`='¡Mechamojada, necesito una montura para regresar al cuartel general, rápido!' WHERE `ID`=35290;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어... 쉴 수 있겠구나.', `MaleText_loc4`='终于……现在我能够休息了。', `MaleText_loc5`='終於...我得以安息。', `MaleText_loc7`='Al fin... Ahora puedo descansar.', `FemaleText_loc1`='드디어... 쉴 수 있겠어.', `FemaleText_loc4`='终于……现在我能够休息了。', `FemaleText_loc5`='終於...我得以安息。', `FemaleText_loc7`='Al fin... Ahora puedo descansar.' WHERE `ID`=35291;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마침내, 악몽이 끝난 겁니까?', `MaleText_loc4`='我的噩梦终于结束了？', `MaleText_loc5`='我的噩夢，它終於結束了嗎?', `MaleText_loc7`='Mi pesadilla... ¿ha acabado por fin?', `FemaleText_loc1`='마침내, 악몽이 끝난 건가요?', `FemaleText_loc4`='我的噩梦终于结束了？', `FemaleText_loc5`='我的噩夢，它終於結束了嗎?', `FemaleText_loc7`='Mi pesadilla... ¿ha acabado por fin?' WHERE `ID`=35292;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끔찍했습니다... 꿈에서 저는 친구들의 적이 되어 싸웠습니다.', `MaleText_loc4`='这真可怕……我梦见我正在和自己的朋友作战。', `MaleText_loc5`='這真可怕...我夢到我跟我的朋友們彼此廝殺。', `MaleText_loc7`='Fue terrible... Soñé que estaba luchando contra mis amigos.', `FemaleText_loc1`='끔찍했어요... 꿈에서 저는 친구들의 적이 되어 싸웠었어요.', `FemaleText_loc4`='这真可怕……我梦见我正在和自己的朋友作战。', `FemaleText_loc5`='這真可怕...我夢到我跟我的朋友們彼此廝殺。', `FemaleText_loc7`='Fue terrible... Soñé que estaba luchando contra mis amigos.' WHERE `ID`=35293;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사람들의 비명소리는 이제 들리지 않는군요. 이제 전부 끝난 겁니까?', `MaleText_loc4`='我听不到那些尖叫声了。一切都结束了吗？', `MaleText_loc5`='我沒有再聽見那些哀嚎了。它結束了嗎?', `MaleText_loc7`='Ya no oigo los gritos. ¿Es el fin?', `FemaleText_loc1`='사람들의 비명소리는 이제 들리지 않네요. 이제 전부 끝난 걸까요?', `FemaleText_loc4`='我听不到那些尖叫声了。一切都结束了吗？', `FemaleText_loc5`='我沒有再聽見那些哀嚎了。它結束了嗎?', `FemaleText_loc7`='Ya no oigo los gritos. ¿Es el fin?' WHERE `ID`=35294;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 지쳤습니다. 잠시 쉬도록 해주십시오.', `MaleText_loc4`='我累坏了，让我先休息一下。', `MaleText_loc5`='我好累。讓我休息一下。', `MaleText_loc7`='Estoy tan cansado. Solo déjame descansar un momento.', `FemaleText_loc1`='너무 지쳤어요. 잠시 쉬도록 해주세요.', `FemaleText_loc4`='我累坏了，让我先休息一下。', `FemaleText_loc5`='我好累。讓我休息一下。', `FemaleText_loc7`='Estoy tan cansada. Solo déjame descansar un momento.' WHERE `ID`=35295;
