UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 잡으세요!', `MaleText_loc4`='坚持住！', `MaleText_loc5`='等一下!', `MaleText_loc7`='¡Aguanta!' WHERE `ID`=35297;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오래 걸리지 않을 겁니다!', `MaleText_loc4`='这用不了太长时间。', `MaleText_loc5`='這不會花太久時間。', `MaleText_loc7`='No tardará mucho.' WHERE `ID`=35298;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='직접 모시게 되어 영광입니다!', `MaleText_loc4`='能够为你驾驶，这是我的荣幸，我可以这样说吗？', `MaleText_loc5`='我可以說做為你的司機是我的榮幸嗎?', `MaleText_loc7`='¿Debería decir que es un honor ser tu conductor?' WHERE `ID`=35299;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벌레들과 게으른 트롤들이 있지만 당신이 오신 후로 광산의 생산 효율이 최고 수준으로 올라갔답니다.', `MaleText_loc4`='在你的英明领导下，这里的采矿工作效率达到了前所未有的高峰！那些坑道虫和懒惰的巨魔也终于安分了。', `MaleText_loc5`='儘管有那些蟲子和懶惰的食人妖，在你的領導下，礦區是以最高效率在進行運作。', `MaleText_loc7`='A pesar de los gusanos y los trols vagos, las minas han alcanzado su máximo de productividad bajo tu control.' WHERE `ID`=35300;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우편 배달을 시작한지 한 달이 되어 가네요. 혹시 임원진에 빈 자리 없나요? 지금 제 이력서를 드릴 수도 있어요.', `MaleText_loc4`='现在我已经送了一个月的信。现在有什么主管的位置空缺吗？我已经把简历准备好了。', `MaleText_loc5`='我已經當了一個月的送信小弟了。現在有執行長的職缺嗎?我的履歷已經準備好了。', `MaleText_loc7`='Llevo un mes enviado cartas. ¿No hay ningún puesto de directivo? Tengo mi currículo aquí mismo.' WHERE `ID`=35301;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋은 날씨죠?', `MaleText_loc4`='好天气啊，不是吗？', `MaleText_loc5`='你也覺得天氣不錯吧?', `MaleText_loc7`='Hace buen tiempo, ¿verdad?' WHERE `ID`=35302;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='땅이 아주 뒤집어지겠어요!', `MaleText_loc4`='这些地震简直是疯了！', `MaleText_loc5`='這些地震真是瘋狂!', `MaleText_loc7`='¡Estos terremotos han sido una locura!' WHERE `ID`=35303;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 마상시합에서 용사의 반열에 올라섰습니다. 오늘 여러분께 $n|1을;를; 자랑스럽게 소개합니다.', `MaleText_loc4`='$n在我们的锦标赛中晋升到了勇士等级。今天，我们骄傲地将$g他:她;介绍给大家。', `MaleText_loc5`='$n在我們的聯賽中晉升至勇士階級。今天讓我們驕傲地向你們介紹$g他:她;。', `MaleText_loc7`='$n se ha hecho un hueco entre los campeones de nuestro torneo. Estamos orgullos de $gpresentároslo:presentárosla; hoy.' WHERE `ID`=35304;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마상시합 광장에서 용사들이 극찬하는 $c, $n|1을;를; 오늘 소개해 드립니다.', `MaleText_loc4`='这场锦标赛中的勇士们对于这名$c有着很高评价。今天，我们就向大家介绍$n。', `MaleText_loc5`='聯賽場地中的勇士們給予這位$c很高的評價。今天讓我們來介紹，$n。', `MaleText_loc7`='Los campeones en las pistas del torneo hablan maravillas de $geste:esta; $c. Hoy presentamos a $n.' WHERE `ID`=35305;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 $c보다 더 확실한 용사는 찾아보기 어려울 겁니다. 오늘 여러분께 소개해 드릴 이는 바로 $n입니다.', `MaleText_loc4`='想要找到比这位$c更强悍的勇士绝对是不容易的。今天，让我们来介绍$n。', `MaleText_loc5`='我們很難找到比這位$c更堅定的勇士。今天讓我介紹，$n。', `MaleText_loc7`='Sería difícil encontrar un campeón más inquebrantable que $geste:esta; $c. Hoy presentamos a $n.' WHERE `ID`=35306;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대단한 용사, 능력 많은 $c, 영예로운 $r|1을;를; 소개합니다. $n입니다.', `MaleText_loc4`='我们将向大家介绍一位强大的勇士，一位技艺高超的$c，一位光荣的$r，那就是$n。', `MaleText_loc5`='我們在此介紹一位強大的勇士，充滿才華的$c，可敬的$r。讓我們歡迎，$n。', `MaleText_loc7`='Ofrecemos un poderoso campeón, $gun:una; $c capaz, $gun:una; $r honorable. Presentamos a $n.' WHERE `ID`=35307;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 보여준 능력 앞에 많은 용사가 무릎을 꿇었습니다. 자랑스러운 마음으로 이 범상치 않은 $c|1을;를; 여러분께 소개합니다.', `MaleText_loc4`='许多勇士都败在了$n的手中。现在，我们将骄傲地介绍这位可怕的$c。', `MaleText_loc5`='許多勇士在技藝上輸給$n。我們很驕傲地向諸位介紹這位傑出的$c。', `MaleText_loc7`='Muchos campeones han caído ante las habilidades demostradas por $n. Estamos orgullosos de presentar a un formidable $c.' WHERE `ID`=35308;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='법정에서 보자고!', `MaleText_loc4`='等着收我的律师函吧！', `MaleText_loc5`='我的律師會找你的!', `MaleText_loc7`='¡Tendrás noticias de mi abogado!', `FemaleText_loc1`='법정에서 보자고요!', `FemaleText_loc4`='等着收我的律师函吧！', `FemaleText_loc5`='我的律師會找你的!', `FemaleText_loc7`='¡Tendrás noticias de mi abogado!' WHERE `ID`=35309;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심해!', `MaleText_loc4`='看你往哪儿开的？', `MaleText_loc5`='小心前面!', `MaleText_loc7`='¡Mira por dónde vas!', `FemaleText_loc1`='조심해요!', `FemaleText_loc4`='看你往哪儿开的？', `FemaleText_loc5`='小心前面!', `FemaleText_loc7`='¡Mira por dónde vas!' WHERE `ID`=35310;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='운전 연습부터 해, 이 미치광이야!', `MaleText_loc4`='你疯了吗！', `MaleText_loc5`='學好如何開車吧，你這瘋子!', `MaleText_loc7`='¡Aprende a conducir, loco!', `FemaleText_loc1`='운전 연습부터 해, 이 미치광이야!', `FemaleText_loc4`='你疯了吗！', `FemaleText_loc5`='學好如何開車吧，你這瘋子!', `FemaleText_loc7`='¡Aprende a conducir, loco!' WHERE `ID`=35311;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아야!', `MaleText_loc4`='哎呦！', `MaleText_loc5`='噢嗚!', `MaleText_loc7`='¡Ay!', `FemaleText_loc1`='아야!', `FemaleText_loc4`='哎呦！', `FemaleText_loc5`='噢嗚!', `FemaleText_loc7`='¡Ay!' WHERE `ID`=35312;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이고, 내 목! 고소할 테다!', `MaleText_loc4`='我的脖子！我要提出控告！', `MaleText_loc5`='我的脖子!我要告你!', `MaleText_loc7`='¡Mi cuello! ¡Pienso denunciar!', `FemaleText_loc1`='어마, 내 목! 고소하고 말거야!', `FemaleText_loc4`='我的脖子！我要提出控告！', `FemaleText_loc5`='我的脖子!我要告你!', `FemaleText_loc7`='¡Mi cuello! ¡Pienso denunciar!' WHERE `ID`=35313;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두고 보자고요, $n!', `MaleText_loc4`='我会找你的，$n！', `MaleText_loc5`='你給我等著，$n!', `MaleText_loc7`='¡Ya verás, $n!', `FemaleText_loc1`='두고 보자고요, $n!', `FemaleText_loc4`='我会找你的，$n！', `FemaleText_loc5`='你給我等著，$n!', `FemaleText_loc7`='¡Ya verás, $n!' WHERE `ID`=35314;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 사람들에게 해만 끼치죠, $n!', `MaleText_loc4`='你真是个令人讨厌的家伙，$n！', `MaleText_loc5`='你是全民公敵，$n!', `MaleText_loc7`='¡Eres un peligro público, $n!', `FemaleText_loc1`='당신은 사람들에게 해만 끼치죠, $n!', `FemaleText_loc4`='你真是个令人讨厌的家伙，$n！', `FemaleText_loc5`='你是全民公敵，$n!', `FemaleText_loc7`='¡Eres un peligro público, $n!' WHERE `ID`=35315;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무역왕에게 이 일을 알리겠습니다, $n!', `MaleText_loc4`='贸易大王会知道的，$n！', `MaleText_loc5`='我要跟貿易親王說，$n!', `MaleText_loc7`='¡El Príncipe mercante se enterará de esto, $n!', `FemaleText_loc1`='무역왕에게 이 일을 알리겠어요, $n!', `FemaleText_loc4`='贸易大王会知道的，$n！', `FemaleText_loc5`='我要跟貿易親王說，$n!', `FemaleText_loc7`='¡El Príncipe mercante se enterará de esto, $n!' WHERE `ID`=35316;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 원형경기장 벽을 들이받고 기절했습니다!', `MaleText_loc4`='%s一下撞到演武场的墙壁，晕了过去！', `MaleText_loc5`='%s撞進大競技場的牆中，並且陷入昏迷!', `MaleText_loc7`='¡%s se estrella contra la pared del Coliseo y queda aturdido!' WHERE `ID`=35317;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투에 참여한 이들을 밟아 뭉개며, %s|1이;가; 거품을 물고 분노합니다!', `MaleText_loc4`='%s爆发出狂烈的怒气，他面前的战士转眼间就被他踩在脚下！', `MaleText_loc5`='腳下踐踏著戰士，%s進入一種口吐白沫的狂暴中!', `MaleText_loc7`='¡Aplastando a los combatientes bajo sus pies, %s echa espumarajos!' WHERE `ID`=35318;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='첫 번째 도전에 나설 준비가 되셨습니까, $c님?', `MaleText_loc4`='$c，是否已经准备好了迎接第一个挑战？', `MaleText_loc5`='準備好進行第一次挑戰了嗎，$c?', `MaleText_loc7`='¿Estás $gpreparado:preparada; para tu primer reto, $c?' WHERE `ID`=35319;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비되었습니다.', `MaleText_loc4`='我准备好了。', `MaleText_loc5`='我準備好了。', `MaleText_loc7`='Estoy preparado.', `FemaleText_loc1`='준비되었어요.', `FemaleText_loc4`='我准备好了。', `FemaleText_loc5`='我準備好了。', `FemaleText_loc7`='Estoy preparada.' WHERE `ID`=35320;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오게, 용사여. 오늘, 여러 지도자와 동료 앞에서 자신이 얼마나 가치 있는 투사인지 증명할 수 있을 걸세.', `MaleText_loc4`='欢迎，勇士们。今天，在你们的领袖与族人面前，你们将证明自己强大的实力。', `MaleText_loc5`='歡迎，勇士。今天，在你的領袖與同袍眼前，你將會證明你自己是個有價值的戰士。', `MaleText_loc7`='Bienvenidos, campeones. Hoy, ante los ojos de sus líderes y coetáneos, demostrarán ser dignos luchadores.' WHERE `ID`=35321;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 이런 경기에는 별 관심이 없소, 티리온 경. 그래도... 저들이 훌륭한 모습을 보여주리라 믿소.', `MaleText_loc4`='我对这些游戏可没什么兴趣，提里奥。不过……我相信它们一定很精彩。', `MaleText_loc5`='我對這些遊戲沒興趣，提里奧。但...我相信他們會表現得很好。', `MaleText_loc7`='No me gustan estos juegos, Tirion... Aun así, estoy seguro de que su actuación será admirable.' WHERE `ID`=35322;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='물론 훌륭하게 해낼 거예요.', `FemaleText_loc4`='他们当然会的。', `FemaleText_loc5`='他們當然會。', `FemaleText_loc7`='Por supuesto que sí.' WHERE `ID`=35323;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훌륭하다고? 하하! 나약하고 초라한 그쪽 용사들이 쓰러지는 모습을 즐겁게 감상해주지.', `MaleText_loc4`='感觉如何？哈！我很喜欢看着你们这些弱小的勇士是怎样失败的，人类。', `MaleText_loc5`='很好?哈!我等著看你那些弱小的勇士落敗，人類。', `MaleText_loc7`='¿Admirable? ¡Ja! Disfrutaré viendo como fracasan tus debiluchos campeones, humano.' WHERE `ID`=35324;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가로쉬, 그만하게.', `MaleText_loc4`='加尔鲁什，够了。', `MaleText_loc5`='卡爾洛斯，夠了。', `MaleText_loc7`='Ya basta, Garrosh.' WHERE `ID`=35325;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 싸워주게, 호드여! 록타르 오가르!', `MaleText_loc4`='打得好，部落！Lok''tar Ogar！', `MaleText_loc5`='奮勇作戰，部落!(獸人語)不勝即亡!', `MaleText_loc7`='¡Luchad bien, miembros de la Horda!¡Lok''tar Ogar!' WHERE `ID`=35326;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 봐줄 만한 싸움을 하는군.', `MaleText_loc4`='终于出现了一场值得一看的战斗。', `MaleText_loc5`='終於，一場值得一看的戰鬥。', `MaleText_loc7`='Por fin una lucha digna de ser vista.' WHERE `ID`=35327;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='짐승들끼리 정신없이 서로 물고 뜯는 모습을 보러 여기 온 건 아니오, 티리온 경.', `MaleText_loc4`='我到这里来不是为了看野兽们无意义地彼此撕扯，提里奥。', `MaleText_loc5`='我可不是來看那些畜生愚蠢地彼此撕扯，提里奧。', `MaleText_loc7`='No he venido aquí para ver animales destrozarse unos a otros absurdamente, Tirion.' WHERE `ID`=35328;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다 훌륭한 투사들이에요. 이제 보시면 아실 테지요.', `FemaleText_loc4`='你将会知道，他们都是强大的战士。', `FemaleText_loc5`='他們是勇敢的戰士，你會明白的。', `FemaleText_loc7`='Verás que son luchadores dignos.' WHERE `ID`=35329;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='먼저 마상시합의 최고 용사 셋을 상대할 걸세! 이 용감무쌍한 싸움꾼들은 다른 이들을 모두 이기고 마상시합의 최고 수준에 올라선 자들일세.', `MaleText_loc4`='你首先会与这场锦标赛的三名总冠军作战。这些强大的战士已经把他们的对手都一一击败了。', `MaleText_loc5`='你們將首先面對聯賽的三位大勇士!他們是最勇猛的參賽者，擊敗了無數對手才達到馬上競技的技藝顛峰。', `MaleText_loc7`='¡Primero se enfrentarán a tres de los Grandes Campeones del torneo! Estos fieros contrincantes han derrotado a todos los demás para alcanzar la cima de la habilidad en las justas.' WHERE `ID`=35330;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시작하게!', `MaleText_loc4`='开始！', `MaleText_loc5`='開始!', `MaleText_loc7`='¡Comenzad!' WHERE `ID`=35331;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타는 법을 배우러 왔나?', `MaleText_loc4`='你要学习如何驾驭坐骑？', `MaleText_loc5`='你來學騎術?', `MaleText_loc7`='¿Vienes para aprender a montar?' WHERE `ID`=35332;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세상에서 동떨어진 이곳에서 지형을 익히며 오랜 시간을 보냈네. 마침내 나의 시대가 왔군. 오그리마에서 아즈샤라에 총력을 기울이기 시작했네. 이곳은 잿빛 골짜기로 향하는 관문이자, 나아가 이 대륙을 완전히 지배하기 위한 발판이지. 최전선에 온 것을 환영하네, $c.', `MaleText_loc4`='多年以来，我一直在这个被世界遗忘的角落里工作着，查看这里的地形，在无聊中打发时间。但我的时代终会到来的。奥格瑞玛正将全部力量转向艾萨拉，我们打开了通往灰谷的通道，并终将统治这片大陆。欢迎来到前线，$c。', `MaleText_loc5`='多年來我一直窩在這個偏僻的角落，投注所有的心力，熟悉此處的地形結構。現在我們的機會來了，奧格瑪已開始正視艾薩拉這塊地方，這裡已成了我們進攻梣谷以及佔領這塊大陸的門戶要地。歡迎來到前線，$c。', `MaleText_loc7`='Durante años he servido en este rincón remoto y olvidado del mundo, memorizando el terreno y esperando mi momento. Y por fin ha llegado. Todo el poder de Orgrimmar está concentrado ahora en Azshara, nuestra puerta de entrada a Vallefresno y al dominio de todo el continente. Te doy la bienvenida al frente, $c.' WHERE `ID`=35333;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사납기 그지없는 오그리마 최고 용사, 해골분쇄자 모크라를 소개합니다!', `MaleText_loc4`='现在请注意，强大的奥格瑞姆总冠军，碎颅者莫克拉出场！', `MaleText_loc5`='讓我們來介紹最勇猛的奧格瑪大勇士，『碎顱者』莫克拉!', `MaleText_loc7`='Presentamos al fiero Gran Campeón de Orgrimmar, ¡Mokra el Trituracráneos!' WHERE `ID`=35334;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위협적인 센진 최고 용사, 줄토어가 투기장에 들어오고 있습니다!', `MaleText_loc4`='进入竞技场的是削瘦却极度危险的祖尔托，森金村的总冠军！', `MaleText_loc5`='現在走進競技場的是精瘦而危險的祖爾拓，森金大勇士!', `MaleText_loc7`='¡Zul''tore, el Gran Campeón de Sen''jin, está entrando en la arena!' WHERE `ID`=35335;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='썬더 블러프 최고 용사, 고귀한 루노크 와일드메인이 코도를 타고 당당하게 등장합니다!', `MaleText_loc4`='高高地骑坐在科多兽上的是雷霆崖的总冠军，令人敬畏的鲁诺克·蛮鬃！', `MaleText_loc5`='高踞於他的科多獸鞍座上，這是令人尊敬的魯諾克·蠻鬃，雷霆崖大勇士!', `MaleText_loc7`='Erguido en la silla de su kodo, vemos al venerable Runok Ferocrín, Gran Campeón de Cima del Trueno.' WHERE `ID`=35336;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불굴의 포세이큰을 대표하는 언더시티 최고 용사, 죽음추적자 비세리입니다!', `MaleText_loc4`='我们现在要介绍的是幽暗城的总冠军，强韧的亡灵，死亡猎手维赛里！', `MaleText_loc5`='代表了被遺忘者的韌性，我向你們介紹幽暗城大勇士，亡靈哨兵威瑟瑞!', `MaleText_loc7`='Aquí tenemos al Gran Campeón de Entrañas, el Mortacechador Visceri, representando la tenacidad de los Renegados.' WHERE `ID`=35337;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노련한 마법사이자 실버문 최고 용사인 에레시아 돈싱어가 모습을 드러냅니다!', `MaleText_loc4`='从大门中走出来的是埃蕾希·晨歌，强大的法师！银月城总冠军！', `MaleText_loc5`='現在穿過大門的是艾瑞西雅·曦詠，技藝精湛的法師與銀月城大勇士!', `MaleText_loc7`='Saliendo por la puerta vemos a Eressea Cantoalba, habilidosa maga y Gran Campeona de Lunargenta.' WHERE `ID`=35338;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='14번째 줄 구문 오류, 생존하려면 도망쳐라. 수동 모드 가동. *딸깍*', `MaleText_loc4`='语法错误行14，序列：逃命。进入被动模式。*点击！*', `MaleText_loc5`='第14行語法錯誤，序列:逃命去。進入被動模式。*咔嚓!*', `MaleText_loc7`='Error de sintaxis línea 14, secuencia: Correr para salvar la vida. Activando modo pasivo. *¡Click!*' WHERE `ID`=35339;
