UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오세요! 여기는 빌지워터 무역회사와 남쪽 바다 상인 은행의 자회사인 케잔 일등 은행입니다.$B$B무엇을 도와드릴까요?', `MaleText_loc4`='你好，$n$g先生:女士;。欢迎来到南海第一科赞贸易与商业银行。$B$B我能为你做些什么？', `MaleText_loc5`='歡迎來到凱贊第一銀行，這是由污水貿易&南海商業銀行所獨資開設的子公司。$B$B我能為你做些什麼?', `MaleText_loc7`='Te doy la bienvenida al Primer Banco de Kezan, una filial propiedad integral del Banco Pantoque de Comerciantes y Mercaderes de los Mares del Sur.$B$B¿Qué puedo hacer por ti hoy?' WHERE `ID`=35350;
