UPDATE `locales_broadcast_text` SET `MaleText_loc1`='항상 저희 은행과 함께해 주셔서 감사합니다, $n 님.$B$B즐거운 하루 보내세요.', `MaleText_loc4`='这么多？好吧，感谢你的光顾，$n$g先生:女士;。$B$B祝你好运。', `MaleText_loc5`='交易愉快，就跟以前一樣，$g先生:女士;。$B$B祝你擁有愉快的一天。', `MaleText_loc7`='Un placer hacer negocios contigo, como siempre, $gseñor:señora; $n.$B$BQue tengas un buen día.' WHERE `ID`=35352;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보는 눈이 있으시군요.$B$B무얼 찾으시죠?', `MaleText_loc4`='呦！你看上去像是个有些品味的$g男人:女人; 。$B$B我能为你做些什么？', `MaleText_loc5`='喂!你看起來像是一個品味與眾不同的$g男人:女人;。$B$B我可以為你做些什麼?', `MaleText_loc7`='¡Oye! ¡Pareces $gun:una; $ghombre:mujer; de gustos exigentes!$B$B¿Qué puedo hacer por ti?' WHERE `ID`=35353;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가장 멋지고 근사한 반짝이로 부탁해요!', `MaleText_loc4`='把你最华丽，最耀眼的首饰都给我拿来！', `MaleText_loc5`='用最昂貴和最閃亮的玩意兒幫我打扮一下!', `MaleText_loc7`='¡Ponme la cadena de oro más gruesa y lustrosa que tengas!', `FemaleText_loc1`='가장 멋지고 근사한 반짝이로 부탁해요!', `FemaleText_loc4`='把你最华丽，最耀眼的首饰都给我拿来！', `FemaleText_loc5`='用最昂貴和最閃亮的玩意兒幫我打扮一下!', `FemaleText_loc7`='¡Ponme la cadena de oro más gruesa y lustrosa que tengas!' WHERE `ID`=35354;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 어머니처럼 아름다운 반짝이예요!', `MaleText_loc4`='这件首饰就像你的妈妈一样好！', `MaleText_loc5`='那個閃亮的玩意兒跟你媽一樣肥!', `MaleText_loc7`='¡Esa cadena de oro es tan gruesa como tu madre!' WHERE `ID`=35355;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='깜짝이야, 뭐죠? 숙련된 전문가의 반짝이를 살 만한 마카롱을 가지고 있을 것 같진 않아 보이는군요.$B$B먼저 은행에 들러보는 게 어때요?', `MaleText_loc4`='怎么了？看样子你还没有足够的杏仁币来购买我这里的首饰。$B$B你也许应该先去一趟银行？', `MaleText_loc5`='怎麼了，老闆?看來你身上的錢不夠買下這種檔次的閃亮玩意兒。$B$B你或許該去銀行跑一趟。', `MaleText_loc7`='¿Qué hay, G? No tienes el aspecto de tener suficientes macarrones como para comprar las cadenas de oro en las que estoy especializado.$B$BQuizá quieras pasarte por el banco. ¿Lo captas?' WHERE `ID`=35356;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대체 무슨 짓을 하는 게냐?', `MaleText_loc4`='你以为你在干什么？', `MaleText_loc5`='你以為你在幹什麼?', `MaleText_loc7`='¿Qué crees que estás haciendo?', `FemaleText_loc1`='대체 무슨 짓을 하는 게냐?', `FemaleText_loc4`='你以为你在干什么？', `FemaleText_loc5`='你以為你在幹什麼?', `FemaleText_loc7`='¿Qué crees que estás haciendo?' WHERE `ID`=35357;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 계획을 멈추기엔 이미 늦었어.', `MaleText_loc4`='你已经来不及阻止我的计划了。', `MaleText_loc5`='你已經來不及阻止我們的計畫了。', `MaleText_loc7`='Llegas demasiado tarde para detener nuestro plan.', `FemaleText_loc1`='우리 계획을 멈추기엔 이미 늦었어.', `FemaleText_loc4`='你已经来不及阻止我的计划了。', `FemaleText_loc5`='你已經來不及阻止我們的計畫了。', `FemaleText_loc7`='Llegas demasiado tarde para detener nuestro plan.' WHERE `ID`=35358;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 내 뒤를 밟지 못하게 해라.', `MaleText_loc4`='注意不要让我被跟踪。', `MaleText_loc5`='確保我不會被人跟蹤。', `MaleText_loc7`='Asegúrate de que nadie me siga.', `FemaleText_loc1`='누가 내 뒤를 밟지 못하게 해라.', `FemaleText_loc4`='注意不要让我被跟踪。', `FemaleText_loc5`='確保我不會被人跟蹤。', `FemaleText_loc7`='Asegúrate de que nadie me siga.' WHERE `ID`=35359;
