UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 어떻게 하는지 보라고요. 스자보는 마술도 한다니까요?$B$B<한숨짓는 스자보>$B$B네, 네. 스자보가 당신에게 해줄 것이 있어요.', `MaleText_loc4`='看看和我共事的都是什么人。苏扎博能弄出奇迹来吗？$B$B<苏扎博叹了口气>$B$B是的，是的，苏扎博认为他能为你做些事。', `MaleText_loc5`='看我必須跟什麼一起工作。薩波可以製造奇蹟?$B$B<薩波嘆了氣>$B$B是的，是的。薩波認為他可以跟你一起工作。', `MaleText_loc7`='Mira con qué tengo que trabajar. ¿Szabo sabe hacer milagros?$B$B<Szabo suspira.>$B$BSí, sí. Szabo cree que puede hacer algo contigo.' WHERE `ID`=35361;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스자보에게 일을 맡기기에는 돈이 부족하군요. 저희는 공짜로 일을 해주진 않아요, 불쌍한 친구.$B$B은행에 좀 가보시고요. 스자보에게 마카롱을 전부 가져오세요.', `MaleText_loc4`='苏扎博的服务不是你能负担得起的。我们可不提供免费服务，小家伙。$B$B还是先去银行吧。把你的杏仁币全都给苏扎博拿来。', `MaleText_loc5`='你請不起薩波的。我們工作是要收費的，小窮鬼。$B$B快回到銀行，把所有的鈔票都帶給薩波。', `MaleText_loc7`='No puedes pagar los servicios de Szabo. Nosotros no trabajamos gratis, pequeño vagabundo.$B$BLárgate al banco. Tráele a Szabo todos tus macarrones.' WHERE `ID`=35362;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스자보, 파티에서 입을 새 옷이 필요해요!', `MaleText_loc4`='苏扎博，我需要一身闪亮的新装扮，为了我即将参加的聚会！', `MaleText_loc5`='薩波，我需要一套全新，超炫的衣服，為了參加我辦的派對用的!', `MaleText_loc7`='¡Szabo, necesito un traje nuevo y a la última para la fiesta que estoy organizando!', `FemaleText_loc1`='스자보, 파티에서 입을 새 옷이 필요해요!', `FemaleText_loc4`='苏扎博，我需要一身闪亮的新装扮，为了我即将参加的聚会！', `FemaleText_loc5`='薩波，我需要一套全新，超炫的衣服，為了參加我辦的派對用的!', `FemaleText_loc7`='¡Szabo, necesito un traje nuevo y a la última para la fiesta que estoy organizando!' WHERE `ID`=35363;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 스자보의 솜씨를 좀 보세요. 작품이 따로 없죠!$B$B당신은 이런 옷에 썩 어울리진 않지만 스자보는 돈이 필요하니까요. <한숨을 쉬는 스자보>', `MaleText_loc4`='哦，看看苏扎博做了什么。真是杰作啊！$B$B说实话，你配不上这身行头，但苏扎博需要钱。<叹气>', `MaleText_loc5`='噢，你看薩波做了什麼。一個傑作!$B$B你沒有資格穿上它，但薩波需要錢。<嘆氣>', `MaleText_loc7`='Oh, mira lo que ha hecho Szabo. ¡Una obra de arte!$B$BTú no eres lo suficientemente importante como para llevarlo, pero Szabo necesita el dinero. <Suspiro.>' WHERE `ID`=35364;
