UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='모든 상표의 색안경이 다 있습니다. 그냥 말만 하시면 팔아 드립니다!', `FemaleText_loc4`='我这里有各种各样新款墨镜。你能叫出名字的，我都有的卖！', `FemaleText_loc5`='我這什麼牌子的墨鏡都有。你叫的出來，我就拿的出來!', `FemaleText_loc7`='¡Tengo todas las marcas de gafas de sol! ¡Dime cuál es la tuya y te juro que seguro que la tengo, o sea!' WHERE `ID`=35381;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭐라고요? 돈은 충분히 가지고 오셨나요?$B$B<풍선검을 터뜨리는 미사>$B$B은행에 먼저 가보셔야 할 것 같군요.', `FemaleText_loc4`='什么？你看上去没有足够的钱能买我的东西。$B$B<米萨用嘴里的泡泡糖吹了个泡泡。>$B$B也许你忘记去银行了？', `FemaleText_loc5`='嗯?你看起來不像是有足夠的錢可以跟我買任何東西。$B$B<米莎吹破了泡泡糖。>$B$B你是不是忘了去銀行一趟?', `FemaleText_loc7`='¿Sí? No tienes aspecto de que tengas la pasta suficiente para comprarme nada, o sea.$B$B<Missa hace explotar su globo de chicle.>$b$b¿Quizá has olvidado pasarte por el banco?' WHERE `ID`=35382;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='근사한 색안경이 필요합니다. 마카롱 두 다발이면 될까요?', `MaleText_loc4`='我需要一些超酷的墨镜。两捆杏仁币能为我换来什么样的货色？', `MaleText_loc5`='我需要一些拉風墨鏡。兩疊鈔票可以買到什麼?', `MaleText_loc7`='Necesito unas gafas de sol chulas. ¿Qué puedo conseguir con dos montones de macarrones?', `FemaleText_loc1`='근사한 색안경이 필요합니다. 마카롱 두 다발이면 될까요?', `FemaleText_loc4`='我需要一些超酷的墨镜。两捆杏仁币能为我换来什么样的货色？', `FemaleText_loc5`='我需要一些拉風墨鏡。兩疊鈔票可以買到什麼?', `FemaleText_loc7`='Necesito unas gafas de sol chulas. ¿Qué puedo conseguir con dos montones de macarrones?' WHERE `ID`=35383;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기 있어요. 최고급 제품이에요. 싸게 드리는 거라고요!$B$B단연 돋보일 거랍니다!', `FemaleText_loc4`='好吧，我以优惠的价格把我最好的一副遮阳镜卖给你！$B$B它一定会让你爱不释手的！', `FemaleText_loc5`='你看，這是我最上等的，便宜賣給你!$B$B你戴上後看起來一定很屌!', `FemaleText_loc7`='Aquí tienes. Mi mejor par, ¡y te las dejo a precio de ganga!$B$B¡Vas a tener una pinta supermolona con ellas puestas, o sea!' WHERE `ID`=35384;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼굴! 얼굴!', `MaleText_loc4`='狠狠打脸！狠狠打脸！', `MaleText_loc5`='臉!臉!', `MaleText_loc7`='¡A la cara! ¡A la cara!', `FemaleText_loc1`='얼굴! 얼굴!', `FemaleText_loc4`='狠狠打脸！狠狠打脸！', `FemaleText_loc5`='臉!臉!', `FemaleText_loc7`='¡A la cara! ¡A la cara!' WHERE `ID`=35385;
