UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벌써 이 섬에서 가장 멋진 반짝이를 가지고 있잖아요?', `MaleText_loc4`='$g兄弟:姐妹;你已经得到了这座岛上最好的首饰！', `MaleText_loc5`='你已經擁有島上最炫的閃亮玩意兒了，$g兄弟:姐妹;!', `MaleText_loc7`='¡Ya tienes la cadena de oro más lustrosa de la isla, $ghermano:hermana;!' WHERE `ID`=35397;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벌목기 칼날 가동.', `MaleText_loc4`='伐木机锯刃被激活了。', `MaleText_loc5`='伐木鋸刃啟動。', `MaleText_loc7`='Hoja trituradora activada.' WHERE `ID`=35398;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='구입하신 색안경 품질은 보증해 드리지 않아요!', `FemaleText_loc4`='你买的这副墨镜是没有质保的！', `FemaleText_loc5`='你買的那些墨鏡是沒有保固的!', `FemaleText_loc7`='¡Esas gafas de sol que has comprado no tienen garantía!' WHERE `ID`=35399;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스자보가 벌써 무역왕에게 어울릴 만한 새 옷을 만들어 드렸잖아요. 자, 이제 돌아가세요. 스자보의 고객들이 겁을 먹잖아요.', `MaleText_loc4`='苏扎博已经为你制作了一套配得上贸易大王的装扮。现在离开吧，你已经把苏扎博的客人都吓跑了。', `MaleText_loc5`='薩波已經為你做了一套適合貿易親王的服裝了。現在快離開，你把薩波的客人都嚇跑了。', `MaleText_loc7`='Szabo ya te ha hecho un traje digno de un Príncipe mercante. Ahora largo, estás asustando a todos los clientes de Szabo.' WHERE `ID`=35400;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='찾아 주셔서 감사합니다. 여기서 당신이 원하는 물건을 찾으실 수 있을 거예요... 그 물건이 연금술용품이기만 하다면요.', `FemaleText_loc4`='欢迎来到我的店铺。我们这里有你所需要的一切……如果你所需要的是炼金术材料……', `FemaleText_loc5`='歡迎來到我們的店。我們有所有你需要的東西...如果你需要鍊金材料的話。', `FemaleText_loc7`='$gBienvenido:Bienvenida; a nuestra tienda. Tenemos todo lo que necesitas... si necesitas suministros de alquimia.' WHERE `ID`=35401;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 직접 물건을 파는 겁니까?', `MaleText_loc4`='你真的有卖东西吗？', `MaleText_loc5`='你真的有在賣東西?', `MaleText_loc7`='¿De verdad que vendes algo?', `FemaleText_loc1`='당신이 직접 물건을 파는 건가요?', `FemaleText_loc4`='你真的有卖东西吗？', `FemaleText_loc5`='你真的有在賣東西?', `FemaleText_loc7`='¿De verdad que vendes algo?' WHERE `ID`=35402;
