UPDATE `locales_broadcast_text` SET `MaleText_loc1`='토템을 잃어버렸습니다. 절 도와주시겠어요?', `MaleText_loc4`='我把我的图腾丢掉了，你能帮助我吗？', `MaleText_loc5`='我弄丟了我的圖騰。你能幫幫我嗎?', `MaleText_loc7`='He perdido mis tótems. ¿Puedes ayudarme?', `FemaleText_loc1`='토템을 잃어버렸어요. 절 도와주시겠어요?', `FemaleText_loc4`='我把我的图腾丢掉了，你能帮助我吗？', `FemaleText_loc5`='我弄丟了我的圖騰。你能幫幫我嗎?', `FemaleText_loc7`='He perdido mis tótems. ¿Puedes ayudarme?' WHERE `ID`=35455;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좀 더 조심하시오, $n. 이 유물은 대지 고리회의 작품이며, 그대에게 드리는 우리의 선물이오.', `MaleText_loc4`='请一定更加小心，$n。这件宝物是由大地之环所创造的。它是我们赠予你的礼物。', `MaleText_loc5`='請審慎的保管它，$n。這個聖物是陶土議會所製造的，就當作是我們贈與你的禮物。', `MaleText_loc7`='Ten más cuidado, $n. El Anillo de la Tierra creó esta reliquia y nosotros te la regalamos a ti.', `FemaleText_loc1`='좀 더 조심해 주세요, $n 님. 이 유물은 대지 고리회의 작품이며, 그대에게 드리는 저희의 선물입니다.', `FemaleText_loc4`='请一定更加小心，$n。这件宝物是由大地之环所创造的。它是我们赠予你的礼物。', `FemaleText_loc5`='請審慎的保管它，$n。這個聖物是陶土議會所製造的，就當作是我們贈與你的禮物。', `FemaleText_loc7`='Ten más cuidado, $n. El Anillo de la Tierra creó esta reliquia y nosotros te la regalamos a ti.' WHERE `ID`=35456;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원소의 정령들은 현명하다오. 그들은 우리보다 훨씬 앞서 존재했으며, 우리보다 훨씬 오래도록 존재할 것이오. 그들이 말을 걸면, 우리는 귀 기울여야만 하오.', `MaleText_loc4`='元素之灵是睿智的。在我们出现之前，他们早已经存在于此，在我们尽数消失之后，他们仍然会在这里长存不息。当他们对我们说话的时候，我们必须仔细倾听。', `MaleText_loc5`='元素之靈的智慧超乎你我的想像。他們比我們更早就存於世上，並且將會存於我輩之後。當他們與我們溝通時，我們必須懂得聆聽。', `MaleText_loc7`='Los espíritus de los elementos son sabios. Estaban aquí antes que nosotros y continuarán mucho después de que nos hayamos ido. Cuando nos hablan, debemos escuchar.' WHERE `ID`=35457;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원소의 정령들이 우리를 둘러싸고 있습니다. 우리는 언제나 귀 기울여야 합니다. 그들의 경고를 무시하면 어떤 일이 벌어지는지, 저는 경험으로 잘 알고 있습니다...', `MaleText_loc4`='元素之灵就在我们身边。我们必须时刻注意倾听他们的声音。我亲眼见到过当我们忽视他们的警告时，发生了怎样的灾难……', `MaleText_loc5`='元素之靈無所不在。我們必須懂得聆聽。我曾經親眼目賭人們無視他們的警告所帶來的後果...', `MaleText_loc7`='Los espíritus de los elementos nos rodean. Debemos escuchar siempre. He visto de primera mano las consecuencias de ignorar sus avisos...' WHERE `ID`=35458;
