UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 훌륭한 파티로군요, $n 님! 음악 연주기도 감사해요!', `MaleText_loc4`='真是一场精彩的聚会，$n。迪斯科舞会更是令人兴奋！', `MaleText_loc5`='很棒的派對，$n。謝謝你的Disco舞會!', `MaleText_loc7`='Una fiesta alucinante, $n. ¡Gracias por la bola de discoteca!' WHERE `ID`=35467;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<입속에 음식물을 잔뜩 집어넣어 잘 알아들을 순 없지만 고맙다는 표현을 하는 듯한 고버>', `MaleText_loc4`='<因为大胖嘴里塞满了食物，你听不清他到底在说些什么。不过你可以确信，他一定是在感谢你。>', `MaleText_loc5`='<古柏嘴巴塞滿了東西，讓你不知道他在說什麼。不過你蠻確定他說的是謝謝。>', `MaleText_loc7`='<Con toda la comida que tiene embutida en la boca, te resulta un poco difícil distinguir lo que dice Gargajo. Sin embargo, crees casi al cien por cien que es gracias.>' WHERE `ID`=35468;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제 가장 친한 친구가 있군요! $n 님, 저희랑 같이 춤추자고요!', `FemaleText_loc4`='这是我最好的朋友！来吧，$n，和我们一起跳舞吧！', `FemaleText_loc5`='那是我最好的朋友!快來啊，$n，跟我們一起跳舞!', `FemaleText_loc7`='¡Ahí está mi mejor colega! ¡Venga $n, baila con nosotros!' WHERE `ID`=35469;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탈렌디스 고대정령이 고통스럽게 울부짖습니다!', `MaleText_loc4`='塔伦迪斯古树痛苦地吼叫着！', `MaleText_loc5`='塔倫迪斯古樹痛苦地大吼!', `MaleText_loc7`='¡El Anciano de Talrendis aúlla de dolor!' WHERE `ID`=35470;
