UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경호비는 빠지지 않고 냈는데!', `MaleText_loc4`='但我已经付过保护费了！', `MaleText_loc5`='但我的保護費已經花光了!', `MaleText_loc7`='¡Pero he pagado mi dinero de protección!' WHERE `ID`=35473;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와! 해적까지 불렀군요? 정말 멋진 파티예요! 아, 아파요! 진짜 무기잖아!!!', `MaleText_loc4`='是谁雇佣了这些海盗？这太棒了！真是精彩的聚会！哦，这很痛！他们的武器是真的！！！', `MaleText_loc5`='誰雇用海賊的?好個派對!啊嗚!那很痛啊!他們的武器不是玩具!', `MaleText_loc7`='¿Quién ha contratado a los piratas? ¡Esto es genial! ¡Menudo fiestón! ¡Auuu, eso ha dolido! ¡TIENEN ARMAS DE VERDAD!' WHERE `ID`=35474;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='월급은 얼마나 받으시나요? 제가 두 배... 세 배까지 쳐 드리죠. 아, 안돼!', `MaleText_loc4`='你的报酬是多少？我付双倍……三倍？！哦，不！', `MaleText_loc5`='他們付你多少錢?我加雙倍...三倍?!噢，不會吧!', `MaleText_loc7`='¿Cuánto os pagan? Lo doblo.. ¿Lo triplico? ¡Oh, no!' WHERE `ID`=35475;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='남쪽바다 해적단이라고? 이제 아수라장이군.', `MaleText_loc4`='南海海盗？这个地方真的要完蛋了。', `MaleText_loc5`='南海掠劫者?這個地方真的要完蛋了。', `MaleText_loc7`='¿Filibusteros de los Mares del Sur? Desde luego este lugar está verdaderamente en plena decadencia.' WHERE `ID`=35476;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 힘을 합하면 우리가 이겨요! 이야아아아!', `MaleText_loc4`='来吧！只要齐心协力，我们就能打败他们！啊！', `MaleText_loc5`='快點!如果我們合力，我們可以撂倒他們!啊啊啊啊!', `MaleText_loc7`='¡Vamos! ¡Si nos juntamos, podremos con ellos! ¡Aaaagh!' WHERE `ID`=35477;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사라져라, 벌레 같은 놈. 여긴 네가 있을 곳이 아니다. 내 분노를 일깨우지 마라.', `MaleText_loc4`='滚开，虫子。你不属于这个地方。不要激怒我。', `MaleText_loc5`='滾吧，蟲子。你不屬於這片大地。不要激怒我。', `MaleText_loc7`='Desaparece, insecto. No deberías estar en estas tierras. No provoques mi ira.' WHERE `ID`=35478;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으으이햐... 고소할 줄 알라고!', `MaleText_loc4`='你会收到我的律师函的！', `MaleText_loc5`='我的律師會找你的!', `MaleText_loc7`='¡Tendrás noticias de mi abogado!' WHERE `ID`=35479;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜, 무엇이 너를 이곳으로 이끌었느냐, 젊은 $r여? 조심해라. 우리의 적이 산속 굴로부터 동쪽으로 이동하고 있다. 그들은 우리의 땅에 돌이킬 수 없는 상처를 입혔어.', `MaleText_loc4`='你怎么会来到这里，年轻的$r？请小心，我们的敌人正在从东边山脉中的一个窟窿里源源不断地涌出来。他们对这片土地造成了严重的伤害。', `MaleText_loc5`='為什麼?是什麼將你帶到這，年輕的$r?請格外地小心，我們的敵人是從東邊一座山的洞穴中來的─他們對這片大地做出了不可修復的損害。', `MaleText_loc7`='Vaya, ¿qué te trae hasta aquí, joven $r? Por favor, ten cuidado. Nuestros enemigos emergen de un agujero en la montaña situado al este... Han dañado esta tierra de forma irreparable.' WHERE `ID`=35480;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기계를 당장 치우지 못할까, $r! 네놈들은 잡초처럼 이 땅에서 뿌리 뽑힐 것이다!', `MaleText_loc4`='别让你的机器碰到我，$r！你会像那些杂草一样从这片土地上被清除掉！', `MaleText_loc5`='把你的機械拿離我，$r!你會像雜草一樣從這世界被清除!', `MaleText_loc7`='¡Mantén tus máquinas alejadas de mí, $r! ¡Serás purificado de esta tierra como la mala hierba que eres!' WHERE `ID`=35481;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 게을러 빠진 멍청이들을 혼내 줘서 고맙네.$B$B우리들도 노예 시절에 반란을 일으켰던 일이 있으니, 이 트롤들을 너무 관대하게 대해줘선 안 될 것 같아.', `MaleText_loc4`='再次感谢你能“帮助”那些懒家伙，老板。$B$B要我说，我们既然已经不再是那些巨魔的奴隶，就不应该对那些巨魔太仁慈。', `MaleText_loc5`='再次謝謝你幫忙處理這些懶惰的蠢貨，$g老大:大姐;。$B$B如果你問我，我會說我們不應該在獲得自由，不再是他們的奴隸後還對那些食人妖那麼的仁慈。', `MaleText_loc7`='Gracias de nuevo por ayudarme con esos vagos cretinos $gjefe:jefa;.$B$BSi quieres saber mi opinión, no debimos ser tan indulgentes con los trols cuando conseguimos liberarnos de la esclavitud a la que nos tenían sometidos.' WHERE `ID`=35482;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구해주셔서 감사해요! $n 님.', `MaleText_loc4`='谢谢你救了我， $n$g先生:女士;。', `MaleText_loc5`='謝謝你救了我，$n$g先生:女士;。', `MaleText_loc7`='Gracias por salvarme, $gseñor:señora; $n.', `FemaleText_loc1`='구해주셔서 감사해요! $n 님.', `FemaleText_loc4`='谢谢你救了我， $n$g先生:女士;。', `FemaleText_loc5`='謝謝你救了我，$n$g先生:女士;。', `FemaleText_loc7`='Gracias por salvarme, $gseñor:señora; $n.' WHERE `ID`=35483;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무역왕이 왜 이런 짓을 한 겁니까?', `MaleText_loc4`='为什么贸易大王会这样做？', `MaleText_loc5`='貿易親王為什麼要這麼做?', `MaleText_loc7`='¿Por qué haría eso el Príncipe mercante?', `FemaleText_loc1`='무역왕이 왜 이런 짓을 한 거죠?', `FemaleText_loc4`='为什么贸易大王会这样做？', `FemaleText_loc5`='貿易親王為什麼要這麼做?', `FemaleText_loc7`='¿Por qué haría eso el Príncipe mercante?' WHERE `ID`=35484;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음 파티는 또 언제인가요?', `MaleText_loc4`='那么，下一次聚会在什么时候开始？', `MaleText_loc5`='所以...下個派對是什麼時候?', `MaleText_loc7`='Entonces, ¿cuándo es la próxima fiesta?', `FemaleText_loc1`='다음 파티는 또 언제인가요?', `FemaleText_loc4`='那么，下一次聚会在什么时候开始？', `FemaleText_loc5`='所以...下個派對是什麼時候?', `FemaleText_loc7`='Entonces, ¿cuándo es la próxima fiesta?' WHERE `ID`=35485;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혹시 제 애인 못 보셨나요?', `MaleText_loc4`='你看到我的女朋友了吗？', `MaleText_loc5`='你有看到我的女朋友嗎?', `MaleText_loc7`='¿Has visto a mi novia?', `FemaleText_loc1`='혹시 제 애인 못 보셨나요?', `FemaleText_loc4`='你看到我的女朋友了吗？', `FemaleText_loc5`='你有看到我的女朋友嗎?', `FemaleText_loc7`='¿Has visto a mi novio?' WHERE `ID`=35486;
