UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방문객 목록에서 제 이름은 빼주세요.', `MaleText_loc4`='请把我从你的客人名单里划去。', `MaleText_loc5`='請把我的名字從你的訪客名單中移除。', `MaleText_loc7`='Quítame de la lista de invitados.', `FemaleText_loc1`='방문객 목록에서 제 이름은 빼주세요.', `FemaleText_loc4`='请把我从你的客人名单里划去。', `FemaleText_loc5`='請把我的名字從你的訪客名單中移除。', `FemaleText_loc7`='Quítame de la lista de invitados.' WHERE `ID`=35488;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해적 복장을 하고 오는 거였나요? 안대라도 가져오는 건데!', `MaleText_loc4`='我可不知道这场聚会里还有海盗表演。我真应该把眼罩带来！', `MaleText_loc5`='我完全不知道派對會有海盜這個主題，不然我一定會把眼罩帶來。', `MaleText_loc7`='No tenía ni idea de que iba a ser una fiesta de temática pirata. ¡Me habría traído mi parche del ojo!', `FemaleText_loc1`='해적 복장을 하고 오는 거였나요? 안대라도 가져오는 건데!', `FemaleText_loc4`='我可不知道这场聚会里还有海盗表演。我真应该把眼罩带来！', `FemaleText_loc5`='我完全不知道派對會有海盜這個主題，不然我一定會把眼罩帶來。', `FemaleText_loc7`='No tenía ni idea de que iba a ser una fiesta de temática pirata. ¡Me habría traído mi parche del ojo!' WHERE `ID`=35489;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님, 화산에 무슨 문제라도 있나요?', `MaleText_loc4`='$n$G先生:女士;，那座火山发生了什么事？', `MaleText_loc5`='$n$G先生:女士;，火山出了什麼事?', `MaleText_loc7`='$gSeñor:Señora; $n, ¿qué ocurre con el volcán?', `FemaleText_loc1`='$n 님, 화산에 무슨 문제라도 있나요?', `FemaleText_loc4`='$G Mr. : Ms.; $n，那座火山发生了什么事？', `FemaleText_loc5`='$n$G先生:女士;，火山出了什麼事?', `FemaleText_loc7`='$gSeñor:Señora; $n, ¿qué ocurre con el volcán?' WHERE `ID`=35490;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 생생한 악몽을 불러일으킵니다!', `MaleText_loc4`='%s开始施放梦魇乍醒！', `MaleText_loc5`='%s開始施展清晰夢魘!', `MaleText_loc7`='¡%s comienza a invocar a la Pesadilla lúcida!', `FemaleText_loc1`='%s|1이;가; 생생한 악몽을 불러일으킵니다!', `FemaleText_loc4`='%s开始施放梦魇乍醒！', `FemaleText_loc5`='%s開始施展清晰夢魘!', `FemaleText_loc7`='¡%s comienza a invocar a la Pesadilla lúcida!' WHERE `ID`=35491;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 여기 구경 왔던 게 기억나. 그럼, 그렇고말고. 새로운 친구한테 배운 걸 잊지 마, 작은 루. 네 미래는 멋져.', `MaleText_loc4`='我们会永远记住这次拜访。绝不要忘记你从新朋友那里学到了什么，小鲁鲁。远大的未来正在前方等着你。', `MaleText_loc5`='我們記得那次拜訪，我們真的記得唷。千萬別忘了你從新朋友身上學到什麼，小阿若。你有著美好的未來。', `MaleText_loc7`='Recordaremos esta visita, sí. Nunca olvides lo que has aprendido de tu $gnuevo amigo:nueva amiga;, pequeño Lito. Te aguarda un gran futuro.' WHERE `ID`=35492;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='걱정하지 마라, 케켁. 너 큰다. 광란심장 일족 위해 강해진다. 너, 고향으로 광란심장 일족 데려간다. 거기엔 새끼 날름이들 없다.', `MaleText_loc4`='别担心，科科。你要长大，成为一名强壮的狂心者。你要率领族人返回旧日的家园。那里不会再有大舌头怪。', `MaleText_loc5`='別擔心，恰嘎。你會長大，並且為了狂心部族而茁壯。你會帶著族人回到故鄉，那裡沒有大舌頭小鬼。', `MaleText_loc7`='No preocupar, Kekek. Tú crecer, ser fuerte por Corazón Frenético. Tú liderar gente de vuelta a antiguo hogar, donde no haber bebés de lenguas-grandes.' WHERE `ID`=35493;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭발물이 든 상자에 불이 붙었습니다!', `MaleText_loc4`='那箱炸药着火了！', `MaleText_loc5`='炸藥箱著火了!', `MaleText_loc7`='¡El cajón de explosivos está ardiendo!' WHERE `ID`=35494;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와서 덤벼 봐라! 추악한 야수들아!', `MaleText_loc4`='来追我们，你们这些可恶的野兽！', `MaleText_loc5`='來抓我們啊，你們這些可惡的野獸!', `MaleText_loc7`='¡Vengan por nosotros, bestias!' WHERE `ID`=35495;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기다! 더러운 놈아!', `MaleText_loc4`='在这儿，你这跳蚤！', `MaleText_loc5`='在這啊，笨蛋!', `MaleText_loc7`='¡Aquí, pulgosos!' WHERE `ID`=35496;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절대로 우리를 잡지 못할 것이다, 빌어먹을 괴물들아!', `MaleText_loc4`='你永远抓不到我们，该死的杂种！', `MaleText_loc5`='你們抓不到我們的，該死的雜種!', `MaleText_loc7`='¡Nunca nos atraparán, perros sucios!' WHERE `ID`=35497;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='늑대인간을 최대한 많이 모아야 하오. 우리를 쫓지 않는 놈은 도망가는 생존자들을 쫓아갈 거요!', `MaleText_loc4`='让我们尽可能地把他们引过来。多一只狼人追我们就少一只狼人追杀幸存者！', `MaleText_loc5`='讓我們盡可能地吸引他們。多一個狼人追我們就少一個狼人獵殺生存者!', `MaleText_loc7`='Atraigamos todos los que podamos. ¡Cada huargen que nos persiga será uno menos tras los sobrevivientes!' WHERE `ID`=35498;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경보 발령! 경보 발령! 은신한 침입자 발견!', `MaleText_loc4`='警告！警告！发现有敌人潜入！', `MaleText_loc5`='警告!警告!偵測到潛行的入侵者!', `MaleText_loc7`='¡Alerta! ¡Alerta! ¡Intruso con sigilo detectado!' WHERE `ID`=35499;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보랏빛 요새로 가는 열쇠를 잃어버렸습니다.', `MaleText_loc4`='我丢掉了紫罗兰要塞的钥匙。', `MaleText_loc5`='我弄丟了進入紫羅蘭堡的鑰匙。', `MaleText_loc7`='He perdido mi llave de El Bastión Violeta.', `FemaleText_loc1`='보랏빛 요새로 가는 열쇠를 잃어버렸어요.', `FemaleText_loc4`='我丢掉了紫罗兰要塞的钥匙。', `FemaleText_loc5`='我弄丟了進入紫羅蘭堡的鑰匙。', `FemaleText_loc7`='He perdido mi llave de El Bastión Violeta.' WHERE `ID`=35500;
