UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소렘이 보내서 왔습니다. 퓨리엔의 용매를 불러 주십시오.', `MaleText_loc4`='苏伦命令我来这里，向你借弗瑞恩的龙鹰使用。', `MaleText_loc5`='我來是與索雷姆有關，你必須給我一隻弗里安的龍鷹。', `MaleText_loc7`='Estoy aquí por encargo de Sorrem. Tienes que llamar al dracohalcón de Furien para mí.', `FemaleText_loc1`='소렘이 보내서 왔어요. 퓨리엔의 용매를 불러 주세요.', `FemaleText_loc4`='苏伦命令我来这里，向你借弗瑞恩的龙鹰使用。', `FemaleText_loc5`='我來是與索雷姆有關，你必須給我一隻弗里安的龍鷹。', `FemaleText_loc7`='Estoy aquí por encargo de Sorrem. Tienes que llamar al dracohalcón de Furien para mí.' WHERE `ID`=35502;
