UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고블린 만능 벨트의 전지가 소진되었습니다.', `MaleText_loc4`='地精百宝腰带的电池耗光了。', `MaleText_loc5`='哥布林萬用腰帶的電池已經沒電了。', `MaleText_loc7`='La batería del cinturón goblin To-2-en-1 está agotada.', `FemaleText_loc1`='고블린 만능 벨트의 전지가 소진되었습니다.', `FemaleText_loc4`='地精百宝腰带的电池耗光了。', `FemaleText_loc5`='哥布林萬用腰帶的電池已經沒電了。', `FemaleText_loc7`='La batería del cinturón goblin To-2-en-1 está agotada.' WHERE `ID`=35504;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기 시포리움 폭탄 보이세요? 제가 공성 전차를 수리하는 동안엔 그걸 사용해서 관문을 공격하세요!', `MaleText_loc4`='看到那些爆盐炸弹了吗？在我修理这部攻城器械的时候，你要对大门使用它们！', `MaleText_loc5`='看到那些爆鹽炸彈了嗎?當我維修攻城機具的時候用它們來轟破大門!', `MaleText_loc7`='¿Ves esas bombas de seforio? Úsalas en las puertas mientras reparo la máquina de asedio.' WHERE `ID`=35505;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='편안한 여행이 되길, $c|1이여;여;.', `MaleText_loc4`='一路平安，$c。', `MaleText_loc5`='一路順風，$c。', `MaleText_loc7`='Buen viaje, $c.' WHERE `ID`=35506;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반쯤 됐어요! 호드가 절 못 때리게 해주세요. 기계공학 학교에서는 싸움은 안 가르친다고요!', `MaleText_loc4`='我就要完成了！挡住那帮部落的家伙。他们可不是在工程学校进行战斗教学！', `MaleText_loc5`='我已經修好一半了!別讓部落靠近。工程學院可沒有教我們如何作戰喔!', `MaleText_loc7`='¡Estoy a medias! Mantén a la Horda alejada de aquí. ¡En la escuela de ingeniería no enseñan a luchar!' WHERE `ID`=35507;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 최고의 작품인 듯한데요! 이제 이 공성 전차를 몰고 나가셔도 돼요!', `MaleText_loc4`='这是我最成功的作品！这部攻城器械已经准备好，随时可以使用了！', `MaleText_loc5`='我有史以來最得意的作品!這台攻城機具已經可以上場囉!', `MaleText_loc7`='¡Mi mejor obra! ¡Esta máquina de asedio está lista para la acción!' WHERE `ID`=35508;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벌써 부서졌어요?! 괜찮아요. 제가 못 고칠 정도는 아니에요.
', `MaleText_loc4`='它已经坏了？！别担心，没有我修不好的。', `MaleText_loc5`='這麼快就壞啦?!別擔心，再壞的情況我都可以修得好。', `MaleText_loc7`='¿Ya está rota? No pasa nada. No es nada que no pueda arreglar.' WHERE `ID`=35509;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파티복으로 갈아입으세요.', `MaleText_loc4`='去为聚会准备服装吧。', `MaleText_loc5`='去換上派對上要穿的衣服。', `MaleText_loc7`='Ve a prepararte para la fiesta.' WHERE `ID`=35510;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고버가 웅얼거리며 작별 인사를 합니다.', `MaleText_loc4`='大胖哼哼着道了别。', `MaleText_loc5`='古柏嘟噥著說了再見。', `MaleText_loc7`='Gargajo gruñe su adiós.' WHERE `ID`=35511;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='파티에서 만나요, 친구!', `FemaleText_loc4`='聚会上见，宝贝儿！', `FemaleText_loc5`='派對上見，寶貝!', `FemaleText_loc7`='¡Te veo en la fiesta, cielo!' WHERE `ID`=35512;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은행에 다녀오렴.', `MaleText_loc4`='前往一家银行。', `MaleText_loc5`='前往銀行。', `MaleText_loc7`='Visita un banco.', `FemaleText_loc1`='은행에 다녀오렴.', `FemaleText_loc4`='前往一家银行。', `FemaleText_loc5`='前往銀行。', `FemaleText_loc7`='Visita un banco.' WHERE `ID`=35513;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 호위병들에게 고개를 끄덕이고 제이나에게 따라오라고 손짓합니다.', `MaleText_loc4`='%s向那一排卫士点点头，招手示意吉安娜随他来。', `MaleText_loc5`='%s對著兩旁的侍衛點了點頭，並示意珍娜跟上。', `MaleText_loc7`='%s asiente a la fila de guardias y hace un gesto para que le siga Jaina.' WHERE `ID`=35514;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상인한테 다녀오렴.', `MaleText_loc4`='拜访一名商人。', `MaleText_loc5`='前往商人處。', `MaleText_loc7`='Visita a un comerciante.', `FemaleText_loc1`='상인한테 다녀오렴.', `FemaleText_loc4`='拜访一名商人。', `FemaleText_loc5`='前往商人處。', `FemaleText_loc7`='Visita a un comerciante.' WHERE `ID`=35515;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야수 우리에 다녀오렴.', `MaleText_loc4`='造访马厩。', `MaleText_loc5`='前往獸欄。', `MaleText_loc7`='Visita los establos.', `FemaleText_loc1`='야수 우리에 다녀오렴.', `FemaleText_loc4`='造访马厩。', `FemaleText_loc5`='前往獸欄。', `FemaleText_loc7`='Visita los establos.' WHERE `ID`=35516;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공성 전차를 수리하는 동안 날 좀 지켜 달라고. 필요하면 저기 있는 시포리움 폭탄을 관문에 사용해!', `MaleText_loc4`='我要处理这部攻城器械，掩护我。如果有需要，就对大门使用那些爆盐炸弹！', `MaleText_loc5`='修理攻城機具的工作就交給我，幫我看著點就夠了。如果你想要轟破大門的話，儘管把那些爆鹽炸彈拿去用吧!', `MaleText_loc7`='Trabajaré en la máquina de asedio, solo cúbreme las espaldas. ¡Usa esas bombas de seforio en las puertas si las necesitas!' WHERE `ID`=35517;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반쯤 됐다고! 얼라이언스 놈들이 가까이 못 오게 해줘. 계약서에 전투 얘긴 없었다고!', `MaleText_loc4`='我就要完成了！挡住那帮联盟的家伙，合同上没说我还得打仗！', `MaleText_loc5`='我已經修好一半了!別讓聯盟靠近 - 我的合約裡可沒有作戰這一條!', `MaleText_loc7`='¡Ya casi estoy! Mantén a la Alianza alejada... ¡Luchar no entra en mi contrato!' WHERE `ID`=35518;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 이 공성 전차를 끌고 나가도 좋아!', `MaleText_loc4`='攻城坦克已经准备好了！', `MaleText_loc5`='這台攻城機具已經可以上場啦!', `MaleText_loc7`='¡La máquina de asedio está lista para la acción!' WHERE `ID`=35519;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 부서졌다고?! 내가 고쳐 주지... 하지만 사용자 과실이니까 공짜로 해 줄 순 없다고.
', `MaleText_loc4`='它又坏了？！我会把它修好……但我可不保证它一定能好用。', `MaleText_loc5`='又壞掉了嗎?!讓我來修理吧...但別指望產品的保固會幫你支付這一切。', `MaleText_loc7`='¿Está estropeada otra vez? La arreglaré... pero no esperes que la garantía cubra esto.' WHERE `ID`=35520;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='티리온 경.', `MaleText_loc4`='提里奥。', `MaleText_loc5`='提里奧。', `MaleText_loc7`='Tirión.' WHERE `ID`=35521;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바리안 폐하. 제이나 님. 와주셔서 감사합니다. 원형경기장에 자리를 마련했습니다.', `MaleText_loc4`='瓦里安国王，吉安娜女士，欢迎你们的到来。我们恭候多时了。', `MaleText_loc5`='瓦里安國王。珍娜女士。歡迎來到聯賽。競技場的座位早已準備好了。', `MaleText_loc7`='Rey Varian. Lady Jaina. Bienvenidos al torneo. Su lugar en el coliseo los espera.' WHERE `ID`=35522;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='감사합니다. 이 정도는 해드려야죠. 우리는 힘을 합쳐야 하니까요.', `FemaleText_loc4`='谢谢，这是我唯一能做的。我们需要同心协力。', `FemaleText_loc5`='感謝你。這是我所能盡的棉薄之力;我們必須團結一致。', `FemaleText_loc7`='Gracias. Es lo mínimo que puedo hacer por esto; tenemos que ayudarnos.' WHERE `ID`=35523;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게 너무 많은 걸 바라는군. 야만스러운 놈들의 자제력 따위를 믿고 구경이나 하라니 말이오.', `MaleText_loc4`='你说个不停，提里奥。要平心静气，要相信那些野人会管住自己。', `MaleText_loc5`='你的要求太過份了，提里奧，竟要我坐視並相信那些野蠻人會安分守己。', `MaleText_loc7`='Pides demasiado, Tirión, que espere y observe, confiando en que los salvajes se contendrán.' WHERE `ID`=35524;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들이 전투 규칙을 반드시 준수하도록 지켜보겠습니다. 관람석의 두 분을 보면 모두 힘을 얻을 것입니다.', `MaleText_loc4`='我的人在这里是为了确保比赛的井然有序。最好让你的部下知道你在看着他们。', `MaleText_loc5`='我的手下將在此確保眾人遵守交戰的規定。你的子民期待著見到你。', `MaleText_loc7`='Mi pueblo está aquí para asegurarse de que honren las reglas. Será bueno para tus súbditos verte en las gradas.' WHERE `ID`=35525;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 고개를 끄덕이고 손님들에게 따라오라고 손짓합니다.', `MaleText_loc4`='%s点点头，招手示意他的客人跟上。', `MaleText_loc5`='%s點了點頭，並且示意其他的來賓跟上。', `MaleText_loc7`='%s asiente y hace un gesto para que le sigan sus invitados.' WHERE `ID`=35526;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럴지도 모르지. 이 계획이 효과 있을지 의심스럽소. 최후의 공격을 펼칠 군대를 준비하는 게 나을 텐데.', `MaleText_loc4`='也许吧。我觉得这比赛没什么意义。我们现在就应该集结大军发动总攻。', `MaleText_loc5`='或許吧。我懷疑這種犧牲能帶來多大的效益。我們寧可致力於籌備最終決戰的大軍。', `MaleText_loc7`='Tal vez. Dudo de la eficacia de esta estratagema.  Será mejor que preparemos nuestros ejércitos para el asalto final.' WHERE `ID`=35527;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 이 경기를 지켜봐야만 경의 도움을 얻을 수 있다면, 자리를 지키겠소. 당장은 말이오.', `MaleText_loc4`='但如果我出席这些比赛能换来你在战争中的协助。那我暂时，会留下来。', `MaleText_loc5`='但是如果我留在此地能獲得你的全力支援，那麼我會...暫且留下。', `MaleText_loc7`='Pero si mi presencia es requerida en este desafío para ganar tu apoyo en la batalla, me quedaré.  Por ahora.' WHERE `ID`=35528;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='스랄이 휘하에 있는 이들을 잘 통제할 거예요.', `FemaleText_loc4`='我相信萨尔会管住他的部下……', `FemaleText_loc5`='我相信索爾會讓他的子民冷靜下來...', `FemaleText_loc7`='Estoy segura de que Thrall tendrá a su gente bajo control…' WHERE `ID`=35529;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세상엔 경험치를 얻기 싫다고 생각하는 이들도 있다네. 무슨 짓을 하든, 영원히 지금의 레벨에 머무르면서 더 강해지지 않았으면 하는 이들이 있단 말일세.$B$B나는 이 소망을 현실로 이뤄줄 수 있다네... 물론 대가를 받고 말이야.$B$B하지만 기억하게. 일단 내게 비용을 지불하면, 자넨 앞으로 경험치를 얻을 수 없네. 정말일세. 눈곱만큼도 얻을 수 없지.$B$B나중에 경험치를 획득하기로 마음을 바꾸거든, 같은 비용을 지불하면 내가 원 상태로 되돌려 주겠네.', `MaleText_loc4`='的确会有人不再想获得经验。他们想永远停留在现有的水平，不再变得更强。$B$B我可以实现这一点……当然，我需要收取一些费用。$B$B但你要明白：一旦你把酬金支付给我，你就无法再获得经验了。是一直，而不是一段时间。$B$B如果你以后又改变主意，想要重新开始获取经验，也可以向我支付同样多的酬金，让我解除这一禁制。', `MaleText_loc5`='世上有些人希望他們的行為不會為自己帶來經驗值。他們希望能始終維持當前等級的力量，並且不再獲得成長。$B$B我能幫你這麼做...當然，你得花點錢。$B$B但是你要注意:一旦付了錢，『你就不再獲得任何經驗值了』。一點經驗值也得不到。$B$B要是你事後改變主意，並且想再度獲得經驗值的話，我可以用相同的費用幫你恢復正常。', `MaleText_loc7`='Hay quienes desean dejar de ganar experiencia con sus acciones, mantenerse por siempre en el nivel de fuerza en el que se encuentran ahora y no volverse más fuertes.$B$BPuedo hacerlo posible... pero tiene un precio, por supuesto.$B$BPero que quede claro: cuando me pagues, ya NO GANARÁS EXPERIENCIA. Nada. Ni un poquito.$B$BSi cambias de idea después y quieres volver a ganar experiencia de nuevo, puedo deshacer el proceso por el mismo precio.', `FemaleText_loc1`='상엔 경험치를 얻기 싫다고 생각하는 이들도 있다네. 무슨 짓을 하든, 영원히 지금의 레벨에 머무르면서 더 강해지지 않았으면 하는 이들이 있단 말일세.$B$B나는 이 소망을 현실로 이뤄줄 수 있다네... 물론 대가를 받고 말이야.$B$B하지만 기억하게. 일단 내게 비용을 지불하면, 자넨 앞으로 경험치를 얻을 수 없네. 정말일세. 눈곱만큼도 얻을 수 없지.$B$B나중에 경험치를 획득하기로 마음을 바꾸거든, 같은 비용을 지불하면 내가 원 상태로 되돌려 주겠네.', `FemaleText_loc4`='的确会有人不再想获得经验。他们想永远停留在现有的水平，不再变得更强。$B$B我可以实现这一点……当然，我需要收取一些费用。$B$B但你要明白：一旦你把酬金支付给我，你就无法再获得经验了。是一直，而不是一段时间。$B$B如果你以后又改变主意，想要重新开始获取经验，也可以向我支付同样多的酬金，让我解除这一禁制。', `FemaleText_loc5`='世上有些人希望他們的行為不會為自己帶來經驗值。他們希望能始終維持當前等級的力量，並且不再獲得成長。$B$B我能幫你這麼做...當然，你得花點錢。$B$B但是你要注意:一旦付了錢，『你就不再獲得任何經驗值了』。一點經驗值也得不到。$B$B要是你事後改變主意，並且想再度獲得經驗值的話，我可以用相同的費用幫你恢復正常。', `FemaleText_loc7`='Hay quienes desean dejar de ganar experiencia con sus acciones, mantenerse por siempre en el nivel de fuerza en el que se encuentran ahora y no volverse más fuertes.$B$BPuedo hacerlo posible... pero tiene un precio, por supuesto.$B$BPero que quede claro: cuando me pagues, ya NO GANARÁS EXPERIENCIA. Nada. Ni un poquito.$B$BSi cambias de idea después y quieres volver a ganar experiencia de nuevo, puedo deshacer el proceso por el mismo precio.' WHERE `ID`=35530;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 앞으로 경험치를 획득하지 않겠습니다.', `MaleText_loc4`='我已经不再想获得经验了。', `MaleText_loc5`='我不想再獲得任何經驗值。', `MaleText_loc7`='No deseo seguir ganando experiencia.', `FemaleText_loc1`='저는 앞으로 경험치를 획득하지 않을래요.', `FemaleText_loc4`='我已经不再想获得经验了。', `FemaleText_loc5`='我不想再獲得任何經驗值。', `FemaleText_loc7`='No deseo seguir ganando experiencia.' WHERE `ID`=35531;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 경험치를 획득하고 싶어요.', `MaleText_loc4`='我希望能再次开始获取经验。', `MaleText_loc5`='我希望再度獲得經驗值。', `MaleText_loc7`='Quiero volver a ganar experiencia de nuevo.', `FemaleText_loc1`='다시 경험치를 획득하고 싶어요.', `FemaleText_loc4`='我希望能再次开始获取经验。', `FemaleText_loc5`='我希望再度獲得經驗值。', `FemaleText_loc7`='Quiero volver a ganar experiencia de nuevo.' WHERE `ID`=35532;
