UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우체통에 다녀오렴.', `MaleText_loc4`='访问邮箱。', `MaleText_loc5`='前往郵箱。', `MaleText_loc7`='Visita un buzón.', `FemaleText_loc1`='우체통에 다녀오렴.', `FemaleText_loc4`='访问邮箱。', `FemaleText_loc5`='前往郵箱。', `FemaleText_loc7`='Visita un buzón.' WHERE `ID`=35534;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 앞으로 경험치를 획득하지 않겠나?', `MaleText_loc4`='你确定想要停止获取经验？', `MaleText_loc5`='你確定你想停止獲得經驗值嗎?', `MaleText_loc7`='¿Seguro que quieres dejar de ganar experiencia?', `FemaleText_loc1`='정말 앞으로 경험치를 획득하지 않겠나?', `FemaleText_loc4`='你确定想要停止获取经验？', `FemaleText_loc5`='你確定你想停止獲得經驗值嗎?', `FemaleText_loc7`='¿Seguro que quieres dejar de ganar experiencia?' WHERE `ID`=35535;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='인상적인 경기였습니다. 하지만 다음 도전에도 준비되셨나요?', `MaleText_loc4`='这可真是令人惊叹。那么，你准备好迎接下一个挑战了么？', `MaleText_loc5`='剛才的表現真精采。但是你準備好要接受下一個挑戰了嗎?', `MaleText_loc7`='Ha sido una demostración impresionante. Pero, ¿estás $gpreparado:preparada; para el siguiente reto?' WHERE `ID`=35536;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 보여주신 실력이 사람들에게 깊은 인상을 줬을 겁니다. 이제 모든 이에게 마상시합의 용사로 인정받을 시간이군요.', `MaleText_loc4`='今天，你在竞技场上的表现给所有人都留下了深刻的印象。现在，你将在万众瞩目下成为这次比武的冠军。', `MaleText_loc5`='你今天在競技場所展現的卓越技巧令眾人印象深刻。現在你該在眾人的面前獲得聯賽勇士的表揚。', `MaleText_loc7`='Hoy has impresionado a todo el mundo con tus habilidades en la arena. Ya es hora de que todos te conozcan como $gel campeón:la campeona; del torneo.' WHERE `ID`=35537;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음 상대에게 도전하겠습니다.', `MaleText_loc4`='我已经为下一个挑战做好了准备。', `MaleText_loc5`='我準備好要接受下一個挑戰了。', `MaleText_loc7`='Estoy preparado para el siguiente reto.', `FemaleText_loc1`='다음 상대에게 도전하겠어요.', `FemaleText_loc4`='我已经为下一个挑战做好了准备。', `FemaleText_loc5`='我準備好要接受下一個挑戰了。', `FemaleText_loc7`='Estoy preparada para el siguiente reto.' WHERE `ID`=35538;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비됐습니다.', `MaleText_loc4`='我准备好了。', `MaleText_loc5`='我準備好了。', `MaleText_loc7`='Estoy preparado.', `FemaleText_loc1`='준비됐어요.', `FemaleText_loc4`='我准备好了。', `FemaleText_loc5`='我準備好了。', `FemaleText_loc7`='Estoy preparada.' WHERE `ID`=35539;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디... 개들이 다시 돌아와 킁킁대나 보군?', `MaleText_loc4`='那些狗继续去闻味了？', `MaleText_loc5`='所以狗回來要四處嗅一嗅了?', `MaleText_loc7`='¿Así que los perros han regresado para olisquear los alrededores?' WHERE `ID`=35540;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 싸웠네! 다음 상대는 은빛십자군의 일원이라네. 그들을 상대로 자신의 무용을 증명해 보게.', `MaleText_loc4`='干得漂亮！你的下一个挑战将来自于十字军的骑士们。他们将以强大的实力对你进行测试。', `MaleText_loc5`='精采的戰鬥!你的下一個挑戰者是從十字軍中挑選出來的英勇鬥士。你將會親身面對他們超卓實力的考驗。', `MaleText_loc7`='¡Bien luchado! Su próximo reto llega de entre las filas de la propia Cruzada. Se les pondrá a prueba contra su considerable destreza.' WHERE `ID`=35541;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='투기장에 들어오는 저 성기사는 전쟁터에서도 마상시합 광장에서도 널리 알려진 인물입니다. 은빛십자군 최고 용사, 성기사 에드릭을 소개합니다!', `MaleText_loc4`='正在走进竞技场的是一位对于战场和比武场都绝不陌生的圣骑士——银色十字军的总冠军，纯洁者耶德瑞克！', `MaleText_loc5`='接著進入競技場的是，不論在戰場或聯賽場地都身經百戰的聖騎士，身為銀白十字軍的大勇士，『純淨者』埃卓克!', `MaleText_loc7`='Entrando en la arena, tenemos a un paladín que no es un extraño para los campos de batalla, ni los Campos del Torneo. ¡El gran campeón de la Cruzada Argenta, Eadric el Puro!' WHERE `ID`=35542;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음에 소개할 이분은 성스러운 빛을 섬기는 데 둘째 가라면 서러울 인물입니다! 여러분, 은빛 고해사제 페일트리스입니다!', `MaleText_loc4`='接下来出场的是圣光最忠实的追随者！银色神官帕尔崔丝！', `MaleText_loc5`='下一位對手，在追求聖光之道上無人能出其右。讓我們歡迎銀白告解者帕爾璀絲!', `MaleText_loc7`='La siguiente combatiente no tiene rival alguno en su pasión al apoyar a la Luz. ¡Les entrego a la confesora Argenta Cabelloclaro!' WHERE `ID`=35543;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘했네. 오늘 자네의 가치를 잘 보여주었...', `MaleText_loc4`='干得好，今天，你证明了自己的实力。', `MaleText_loc5`='幹得好。今天，你已證明了你自己-', `MaleText_loc7`='Bien hecho. Hoy has demostrado algo...' WHERE `ID`=35544;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기 지붕 쪽을 보십시오! 저게 누구죠?', `MaleText_loc4`='那些椽子旁边是什么？', `MaleText_loc5`='那是什麼?在樑上那邊的東西?', `MaleText_loc7`='¿Qué es eso que hay cerca de las vigas?' WHERE `ID`=35545;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='환영을 그렇게밖에 못하나. 쥐새끼 같은 놈.', `MaleText_loc4`='你搞砸了我的盛大登场，鼠辈。', `MaleText_loc5`='你破壞了我的偉大登場，鼠輩。', `MaleText_loc7`='Arruinaste mi entrada triunfal, rata.' WHERE `ID`=35546;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 대체 무슨 일이지?', `MaleText_loc4`='这是怎么回事？', `MaleText_loc5`='這一切究竟為了什麼?', `MaleText_loc7`='¿Qué significa esto?' WHERE `ID`=35547;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 리치 왕의 대리인이 이 한심하기 짝이 없는 마상시합장에서 무릎 꿇었다고 생각했나?', `MaleText_loc4`='你们真以为，巫妖王的战士会败在你们那可怜的比武场上？', `MaleText_loc5`='你真的以為巫妖王的密探會在你們如此可笑的聯賽中被擊敗嗎?', `MaleText_loc7`='¿Realmente pensaron que un agente del Rey Exánime podía llegar a perder en este torneíto patético?' WHERE `ID`=35548;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 할 일을 끝내러 왔다.', `MaleText_loc4`='我是来做个了断的。', `MaleText_loc5`='我來完成我的任務。', `MaleText_loc7`='He venido a terminar mi tarea.' WHERE `ID`=35549;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가만히 서 있지 마라! 놈을 없애!', `MaleText_loc4`='不要只是傻站在那里，干掉他！', `MaleText_loc5`='別光站著，殺了他!', `MaleText_loc7`='No se queden ahí. ¡Mátenlo!' WHERE `ID`=35550;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈을 조각내 버려!', `MaleText_loc4`='把他撕碎！', `MaleText_loc5`='撕碎他!', `MaleText_loc7`='¡Hacedlo pedazos!' WHERE `ID`=35551;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가로쉬, 여기선 자제해주기 바라네. 보랏빛 성채 때와 같은 상황을 또 만들고 싶진 않네.', `MaleText_loc4`='加尔鲁什，我希望你能控制自己。我不想紫罗兰城堡的一幕再发生。', `MaleText_loc5`='卡爾洛斯，我希望你能自制。我不希望見到紫羅蘭城塞的事件再度上演。', `MaleText_loc7`='Garrosh, espero que te puedas controlar estando aquí.  No quiero que se repita lo de la Ciudadela Violeta.' WHERE `ID`=35552;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='푸하! 그건 지도자로서 마땅히 보여줄 모습이었소. 마법사가 방해하기 전에 저 인간 녀석을 죽이지 못해서 유감이오.', `MaleText_loc4`='哼！那只是领袖在展示他的力量。我真后悔没在那个法师插手前干掉那个人类。', `MaleText_loc5`='哼!我不過是在展示領導者該有的力量。我只後悔沒在那個法師干涉之前幹掉那個人類罷了。', `MaleText_loc7`='¡Pah! Eso fue una muestra de fuerza digna de un líder. Sólo me arrepiento de no haber matado al humano antes de que interviniese el mago.' WHERE `ID`=35553;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='막대기를 들고 툭탁거리면서 무슨 명예를 얻는다는 말이오? 시간만 버릴 뿐이오.', `MaleText_loc4`='挥舞粗头棒子有什么荣誉可言？这是在浪费时间。', `MaleText_loc5`='耍耍鈍重的木棍有何榮譽可言?不過是在浪費時間。', `MaleText_loc7`='¿Qué honor hay en andar rompiendo todo a los palazos?  Esto es una pérdida de tiempo.' WHERE `ID`=35554;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 고맙지 않소, 스랄.', `MaleText_loc4`='别算上我，萨尔。', `MaleText_loc5`='我可不苟同，索爾。', `MaleText_loc7`='Habla por ti mismo, Thrall.' WHERE `ID`=35555;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바보같은 말이겠지. 호드는 당신이나 거들먹거리는 왕의 도움따위 없이도 언데드를 쓸어버릴 수 있소.', `MaleText_loc4`='一派胡言。部落杀死那只亡灵易如反掌，不需要你，更别说那个傲慢的国王。', `MaleText_loc5`='愚不可及。部落將會摧毀那些不死生物，不需要你的幫助，人類，也不需要那高傲的國王來插手。', `MaleText_loc7`='Las palabras de un tonto, querrás decir. La Horda destruirá a los no-muertos sin tu ayuda, humano, o la del pomposo rey.' WHERE `ID`=35556;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흥.', `MaleText_loc4`='呸。', `MaleText_loc5`='哼。', `MaleText_loc7`='Bah.' WHERE `ID`=35557;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 여기에 손님으로 왔네, 가로쉬. 명예롭게 행동하도록.', `MaleText_loc4`='我们是客人，加尔鲁什，你要注意你的言行。', `MaleText_loc5`='我們受邀來到這裡，卡爾洛斯，你要注意你的言行舉止。', `MaleText_loc7`='Estamos aquí como invitados, Garrosh, así que te comportarás honorablemente.' WHERE `ID`=35558;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='초대해줘서 고맙소, 티리온 대영주. 어떤 경기가 펼쳐질지 기대하고 있소.', `MaleText_loc4`='感谢您的邀请，弗丁大人。我们期待着精彩的比赛。', `MaleText_loc5`='感謝你的邀請，大領主弗丁。我們很期待賽事的發展。', `MaleText_loc7`='Gracias por la invitación, Lord Vadín. Tenemos muchos deseos de ver estos juegos.' WHERE `ID`=35559;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='현명한 말씀이오.', `MaleText_loc4`='说的好。', `MaleText_loc5`='一點都沒錯。', `MaleText_loc7`='Sabias palabras.' WHERE `ID`=35560;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가로쉬, 그만!', `MaleText_loc4`='加尔鲁什，够了！', `MaleText_loc5`='卡爾洛斯，夠了!', `MaleText_loc7`='¡Garrosh! ¡Basta!' WHERE `ID`=35561;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론이오, 티리온 경. 가로쉬의 경거망동을 사과드리오. 다시는 이런 일이 없을 것이오.', `MaleText_loc4`='当然，提里奥，我为他的莽撞向你致歉，我保证下不为例。', `MaleText_loc5`='是的，提里奧。我為他的無禮感到抱歉。我保證不會再發生了。', `MaleText_loc7`='Por supuesto, Tirion. Le pido disculpas por ese exabrupto. No se repetirá.' WHERE `ID`=35562;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 유물은 끊임없이 솟아오르는 에너지로 웅웅거리며 치직거리는 소리를 냅니다.', `MaleText_loc4`='这座纪念碑以永不消失的古老能量发出各种嗡嗡和噼啪的声音。', `MaleText_loc5`='這個古蹟不斷地發出遠古的能量。', `MaleText_loc7`='Este monumento cruje y emite un zumbido debido a perpetuas y ancestrales energías.' WHERE `ID`=35563;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소용돌이 보석이 없어진 것을 깨닫고, 하나 더 얻기 위해 마법석에 다가갑니다.', `MaleText_loc4`='你发现身上没有漩涡宝石，便将手伸到符文石中，又拿了一枚。', `MaleText_loc5`='在發現了你沒有漩渦寶石後，你到符石裡又再拿了一個。', `MaleText_loc7`='Al ver que no tienes ninguna gema de vórtice, echas mano de una piedra rúnica para conseguir otra.', `FemaleText_loc1`='소용돌이 보석이 없어진 것을 깨닫고, 하나 더 얻기 위해 마법석에 다가갑니다.', `FemaleText_loc4`='你发现身上没有漩涡宝石，便将手伸到符文石中，又拿了一枚。', `FemaleText_loc5`='在發現了你沒有漩渦寶石後，你到符石裡又再拿了一個。', `FemaleText_loc7`='Al ver que no tienes ninguna gema de vórtice, echas mano de una piedra rúnica para conseguir otra.' WHERE `ID`=35564;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세계 최고의 채굴 작업 현장에 잘 왔다고. 멍청이가 아니고서야 왜 힘들게 산 아래 굴을 뚫고 그 아래 광물을 캐겠어? 우린 산 전체를 옮겨버렸다고! 이제 값비싼 금속을 땅 밑에서 꺼내기만 하면 돼.', `MaleText_loc4`='在你眼前的是这个世界上最具艺术品位的采矿系统。只有土包子才会在山下挖隧道以获得矿石。我们则会将整座山移开！现在，我们就可以直接从地面上挖掘珍贵的金属了。', `MaleText_loc5`='你看到的是世界上最棒，等級最高的礦場運作方式。只有鄉巴佬才會花力氣去挖山洞來採集地下的礦石。我們移動了整座山!現在我們只要直接把地下寶貴的礦物給挖出來就好了。', `MaleText_loc7`='Estás observando lo último de lo último en operaciones mineras en todo el mundo. Tan solo un paleto se molestaría en excavar un túnel para llegar al mineral que se encuentra debajo. ¡Hemos movido la montaña entera! Ahora solo tenemos que extraer el mineral de la superficie de la tierra.' WHERE `ID`=35565;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='금고에 침입하여 개인 재산을 찾아와야 합니다!', `MaleText_loc4`='为了夺回你的私人财产，你要砸开保险库！', `MaleText_loc5`='你即將闖入金庫來取得你的個人財富!', `MaleText_loc7`='¡Estás a punto de irrumpir en la cámara para recuperar tus riquezas personales!' WHERE `ID`=35566;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보관 장치를 열려면 고블린 만능 허리띠의 각 장치를 사용해야 합니다.$B|Tinterface\\Icons\\INV_Misc_EngGizmos_20.blp:64|t |Tinterface\\Icons\\INV_Misc_Bomb_07.blp:64|t |Tinterface\\Icons\\INV_Misc_Ear_NightElf_02.blp:64|t |Tinterface\\Icons\\INV_Misc_EngGizmos_swissArmy.blp:64|t |Tinterface\\Icons\\INV_Weapon_ShortBlade_21.blp:64|t', `MaleText_loc4`='使用你的地精百宝腰带上必要的功能，打开这座保险库！功能具体如下：$B|TInterface\\Icons\\INV_Misc_EngGizmos_20.blp:64|t |TInterface\\Icons\\INV_Misc_Bomb_07.blp:64|t |TInterface\\Icons\\INV_Misc_Ear_NightElf_02.blp:64|t |TInterface\\Icons\\INV_Misc_EngGizmos_swissArmy.blp:64|t |TInterface\\Icons\\INV_Weapon_ShortBlade_21.blp:64|t', `MaleText_loc5`='使用你哥布林萬用腰帶裡的東東來破解這個金庫!$B|TInterface\\Icons\\INV_Misc_EngGizmos_20.blp:64|t |TInterface\\Icons\\INV_Misc_Bomb_07.blp:64|t |TInterface\\Icons\\INV_Misc_Ear_NightElf_02.blp:64|t |TInterface\\Icons\\INV_Misc_EngGizmos_swissArmy.blp:64|t |TInterface\\Icons\\INV_Weapon_ShortBlade_21.blp:64|t', `MaleText_loc7`='¡Utiliza la herramienta adecuada de tu cinturón goblin To-2-en-1 para forzar la puerta de la cámara!$B|TInterfaceIconsINV_Misc_EngGizmos_20.blp:64|t |TInterfaceIconsINV_Misc_Bomb_07.blp:64|t |TInterfaceIconsINV_Misc_Ear_NightElf_02.blp:64|t |TInterfaceIconsINV_Misc_EngGizmos_swissArmy.blp:64|t |TInterfaceIconsINV_Weapon_ShortBlade_21.blp:64|t' WHERE `ID`=35567;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cFFFF2222진행률 막대가 100퍼센트가 되면|r 보관 장치가 열립니다.$B|Tinterface\\Icons\\INV_Misc_coin_02.blp:64|t$B실수를 하면 진행률 막대가 내려갑니다.', `MaleText_loc4`='一旦|cFFFF2222保险库破坏进度条到达百分之百，保险库就会被打破！|r$B|TInterface\\Icons\\INV_Misc_coin_02.blp:64|t$B在错误的时间采取错误的行动会让进度条后退。', `MaleText_loc5`='一旦|cFFFF2222金庫開鎖進度到達百分之百|r，就可以打開金庫!$B|TInterface\\Icons\\INV_Misc_coin_02.blp:64|t$B但如果沒有及時做出正確的動作則會降低開鎖進度表的數值。', `MaleText_loc7`='¡La cámara se abrirá cuando la |cFFFF2222barra de progreso de la apertura de la cámara llegue al cien por cien!|r$B|TInterfaceIconsINV_Misc_coin_02.blp:64|t$BRealizar una acción equivocada en el momento equivocado reducirá el progreso de la barra.' WHERE `ID`=35568;
