UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cFFFF2222소리확대기|r를 사용해야 합니다!$B|Tinterface\\Icons\\INV_Misc_Ear_NightElf_02.blp:64|t', `MaleText_loc4`='使用你的|cFFFF2222顺风耳！|r$B|TInterface\\Icons\\INV_Misc_Ear_NightElf_02.blp:64|t', `MaleText_loc5`='使用你的|cFFFF2222聽診器!|r$B|TInterface\\Icons\\INV_Misc_Ear_NightElf_02.blp:64|t', `MaleText_loc7`='¡Utiliza tu |cFFFF2222Orej-O-scopio|r!$B|TInterfaceIconsINV_Misc_Ear_NightElf_02.blp:64|t' WHERE `ID`=35578;
