UPDATE `locales_broadcast_text` SET `MaleText_loc1`='때려치울 테다!', `MaleText_loc4`='我退出，我退出！', `MaleText_loc5`='我不幹了，我不幹了!', `MaleText_loc7`='Lo dejo, ¡LO DEJO!', `FemaleText_loc1`='때려치울 테다!!', `FemaleText_loc4`='我退出，我退出！', `FemaleText_loc5`='我不幹了，我不幹了!', `FemaleText_loc7`='Lo dejo, ¡LO DEJO!' WHERE `ID`=35581;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무진장 편안했는데...', `MaleText_loc4`='这里真是安静得令人惊讶。', `MaleText_loc5`='那還真是令人驚訝的平靜。', `MaleText_loc7`='¡Eso ha sido sorprendentemente apacible!', `FemaleText_loc1`='무진장 편안했는데...', `FemaleText_loc4`='这里真是安静得令人惊讶。', `FemaleText_loc5`='那還真是令人驚訝的平靜。', `FemaleText_loc7`='¡Eso ha sido sorprendentemente apacible!' WHERE `ID`=35582;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 정신을 잃고 광란 상태에 빠집니다!', `MaleText_loc4`='%s发狂了！', `MaleText_loc5`='%s發狂發瘋了!', `MaleText_loc7`='¡%s se vuelve loco!', `FemaleText_loc1`='%s|1이;가; 정신을 잃고 광란 상태에 빠집니다!', `FemaleText_loc4`='%s发狂了！', `FemaleText_loc5`='%s發狂發瘋了!', `FemaleText_loc7`='¡%s se vuelve loca!' WHERE `ID`=35583;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; $n|1을;를; 노려보며 큰 소리로 울부짖습니다.', `MaleText_loc4`='%s等着$n，发出一阵震耳欲聋的怒吼！', `MaleText_loc5`='%s怒視著$n，並發出震耳的咆哮!', `MaleText_loc7`='¡%s mira a $n y emite un bramido!' WHERE `ID`=35675;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s의 쐐기가 $n|1을;를; 쫓습니다!', `MaleText_loc4`='%s的尖刺正在追击$n！', `MaleText_loc5`='%s的尖刺追擊著$n!', `MaleText_loc7`='¡Los pinchos de %s persiguen a $n!' WHERE `ID`=35676;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시작해도 좋네!', `MaleText_loc4`='可以开始了！', `MaleText_loc5`='開始吧!', `MaleText_loc7`='¡Pueden comenzar!' WHERE `ID`=35677;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오랜 기다림 끝에 겨우 이곳에 흩어진 폐허들을 연구할 수 있게 되었습니다... 돈에 미친 이 조그만 작자들이 그곳을 망쳐 놓지만 않는다면 말이죠.', `FemaleText_loc4`='这么长时间里，我们终于有机会研究散布在这里的废墟了……希望这些财迷不会先把这个地方毁掉', `FemaleText_loc5`='我們終於有機會調查散佈在這的廢墟了...如果這些吸血鬼不離開這的話。', `FemaleText_loc7`='Después de tanto tiempo por fin tenemos una oportunidad de estudiar las ruinas salpicadas por este paisaje... Siempre y cuando esos avariciosos no hayan arrasado ya este lugar.' WHERE `ID`=35678;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주변의 폐허에 대해 말씀해주십시오.', `MaleText_loc4`='和我说说附近的那些废墟。', `MaleText_loc5`='跟我說有關附近那個廢墟的事。', `MaleText_loc7`='Háblame de las ruinas cercanas.', `FemaleText_loc1`='주변의 폐허에 대해 말씀해주십시오.', `FemaleText_loc4`='和我说说附近的那些废墟。', `FemaleText_loc5`='跟我說有關附近那個廢墟的事。', `FemaleText_loc7`='Háblame de las ruinas cercanas.' WHERE `ID`=35679;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='침입자여, 죽어라!', `FemaleText_loc4`='死吧，入侵者！', `FemaleText_loc5`='死吧，入侵者!', `FemaleText_loc7`='¡Muere, intruso!' WHERE `ID`=35680;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기는 네가 있을 곳이 아니다, $r!', `FemaleText_loc4`='你不属于这里，$r！', `FemaleText_loc5`='你不屬於這裡，$r!', `FemaleText_loc7`='¡Este no es tu lugar, $r!' WHERE `ID`=35681;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='감히 성스러운 땅을 짓밟다니!', `FemaleText_loc4`='你的脚踏在神圣的土地上，$c……', `FemaleText_loc5`='你闖入了神聖的土地!', `FemaleText_loc7`='¡Estás hollando suelo sagrado!' WHERE `ID`=35682;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너 따위가 여기서 환영받을 것 같으냐, $r!', `FemaleText_loc4`='$r，这里不欢迎你们！', `FemaleText_loc5`='$r，這裡不歡迎你和你的同類!', `FemaleText_loc7`='¡Los de tu raza no son bienvenidos aquí, $r!' WHERE `ID`=35683;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하!', `MaleText_loc4`='哈！', `MaleText_loc5`='哈!', `MaleText_loc7`='¡JA!' WHERE `ID`=35684;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그것도 도전이라고.', `MaleText_loc4`='易如反掌。', `MaleText_loc5`='毫無挑戰可言。', `MaleText_loc7`='No es ningún desafío.' WHERE `ID`=35685;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하찮은 놈 같으니.', `MaleText_loc4`='没用的东西。', `MaleText_loc5`='沒用的廢物。', `MaleText_loc7`='Maleza despreciable.' WHERE `ID`=35686;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드란 놈들은 겨우 이정도였나?', `MaleText_loc4`='这就是部落最强的战士？', `MaleText_loc5`='難道這就是部落的能耐嗎?', `MaleText_loc7`='¿Esto es lo mejor que puede ofrecer la Horda?' WHERE `ID`=35687;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드 쓰레기를 처리하는 데 악마 군주의 도움 따위는 필요 없다! 덤벼 봐라!', `MaleText_loc4`='联盟对付这些部落垃圾不需要恶魔领主的帮助！来吧，蠢货！', `MaleText_loc5`='聯盟不需要跟惡魔領主聯手對付卑賤的部落!來吧，蠢豬!', `MaleText_loc7`='¡La Alianza no necesita la ayuda de un amo demoníaco para lidiar con la Horda basura!  ¡Ven, cerdo!' WHERE `ID`=35688;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스의 영광을 위해 싸워라, 영웅들이여! 우리의 명예를 지켜라!', `MaleText_loc4`='为荣耀而战！英雄们，为国王和人民而战！', `MaleText_loc5`='為了聯盟的榮耀而戰，英雄們!讓你們的國王和人民感到驕傲吧!', `MaleText_loc7`='¡Luchen por la gloria de la Alianza, héroes! ¡Honren a su rey y a su pueblo!' WHERE `ID`=35689;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 명예는 짓밟혔다! 호드는 말도 안되는 주장을 하며 거짓으로 우리를 비난했다! 나는 정의를 원한다! 티리온 경, 나의 용사들이 그대의 기사를 대신하여 싸우게 하시오. 우리는 호드에 도전할 것이오!', `MaleText_loc4`='我们的荣耀被玷污了！他们对我们进行肆意的污蔑与诽谤。我要讨回公道！请允许我的勇士代替你的人出场，提里奥。我们要挑战部落！', `MaleText_loc5`='聯盟的榮耀蒙受了污點!他們的荒唐主張與不當指控全都衝著我方而來。我要他們得到報應!讓我的勇士代替你的騎士而戰吧，提里奧。我們與部落勢不兩立!', `MaleText_loc7`='¡Nuestro honor ha sido mancillado! Hacen alegatos descabellados y acusaciones falsas contra nosotros. ¡Demando justicia! Permite que mis campeones luchen en el lugar de tus caballeros, Tirión. ¡Desafiamos a la Horda!' WHERE `ID`=35690;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스에 영광을!', `MaleText_loc4`='荣耀属于联盟！', `MaleText_loc5`='榮耀歸於聯盟!', `MaleText_loc7`='¡GLORIA PARA LA ALIANZA!' WHERE `ID`=35691;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕의 가장 강력한 부하라도 얼라이언스에는 저항할 수 없다. 모두 승리자를 맞이하라!', `MaleText_loc4`='即使是巫妖王最强大的爪牙也无法与联盟抗衡。为胜利欢呼吧！', `MaleText_loc5`='連巫妖王最得力的爪牙也無法抵抗聯盟的力量。為我們的勇士歡呼吧!', `MaleText_loc7`='Ni los lacayos más poderosos del Rey Exánime resisten a la Alianza. ¡Salven, vencedores!' WHERE `ID`=35692;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경의 야수들은 우리 용사들의 상대가 안 되오.', `MaleText_loc4`='你的猛兽阻挡不了我的勇士！提里奥。', `MaleText_loc5`='你的野獸根本敵不過我的勇士，提里奧!', `MaleText_loc7`='¡Tus bestias serán inferiores a mis campeones, Tirión!' WHERE `ID`=35693;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='약해빠진 놈!', `MaleText_loc4`='软蛋！', `MaleText_loc5`='弱者!', `MaleText_loc7`='¡Debilucho!' WHERE `ID`=35694;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='격렬한 소용돌이 보석이 없어진 것을 깨닫고, 하나 더 얻기 위해 마법석에 다가갑니다.', `MaleText_loc4`='发现自己并没有盛怒漩涡宝石，你便伸手到符文石中，又取了一枚。', `MaleText_loc5`='你發現已經沒有狂虐漩渦寶石了，從符石裡再拿了一個。', `MaleText_loc7`='Al ver que no tienes ninguna gema de vórtice encolerizado, echas mano de una piedra rúnica para conseguir otra.', `FemaleText_loc1`='격렬한 소용돌이 보석이 없어진 것을 깨닫고, 하나 더 얻기 위해 마법석에 다가갑니다.', `FemaleText_loc4`='发现自己并没有盛怒漩涡宝石，你便伸手到符文石中，又取了一枚。', `FemaleText_loc5`='你發現已經沒有狂虐漩渦寶石了，從符石裡再拿了一個。', `FemaleText_loc7`='Al ver que no tienes ninguna gema de vórtice encolerizado, echas mano de una piedra rúnica para conseguir otra.' WHERE `ID`=35695;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한심하군.', `MaleText_loc4`='没希望了。', `MaleText_loc5`='可悲。', `MaleText_loc7`='Patético.' WHERE `ID`=35696;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맥도 못추는군...', `MaleText_loc4`='败了……', `MaleText_loc5`='退下吧...', `MaleText_loc7`='Subyugado…' WHERE `ID`=35697;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='록타르!', `MaleText_loc4`='Lok''tar！', `MaleText_loc5`='(獸人語)不勝即敗!', `MaleText_loc7`='¡Lok''tar!' WHERE `ID`=35698;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비열한 얼라이언스 놈들! 호드 전사를 상대로 악마 군주를 소환해? 당장 죽음을 안겨 주마!', `MaleText_loc4`='狡诈的联盟狗！召唤恶魔领主来对抗部落的战士？你们离死不远了。', `MaleText_loc5`='卑劣的聯盟蠢狗!你想召喚惡魔領主來對付部落的戰士?你的死亡即將來臨!', `MaleText_loc7`='¡Perros traicioneros de la Alianza! ¿Invocan a un amo demoníaco contra los guerreros de la Horda? ¡Sus muertes serán instantáneas!' WHERE `ID`=35699;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cFFFF2222놀라운 G선|r을 사용해야 합니다!$B|Tinterface\\Icons\\INV_Misc_EngGizmos_20.blp:64|t', `MaleText_loc4`='使用你的|cFFFF2222神奇地精射线！|r$B|TInterface\\Icons\\INV_Misc_EngGizmos_20.blp:64|t', `MaleText_loc5`='使用你的|cFFFF2222超級哥布林射線!|r$B|TInterface\\Icons\\INV_Misc_EngGizmos_20.blp:64|t', `MaleText_loc7`='¡Utiliza tus |cFFFF2222Rayos goblins alucinantes|r!$B|TInterfaceIconsINV_Misc_EngGizmos_20.blp:64|t' WHERE `ID`=35700;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들에게 자비란 없다, 호드 용사들이여! 록타르 오가르!', `MaleText_loc4`='不要手下留情，部落勇士们！LOK''TAR OGAR!', `MaleText_loc5`='不要手下留情，部落的勇士們!(獸人語)不勝即敗!', `MaleText_loc7`='¡Sin misericordia, campeones de la Horda! ¡LOK''TAR OGAR! ' WHERE `ID`=35701;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성공!', `MaleText_loc4`='正确！', `MaleText_loc5`='正確!', `MaleText_loc7`='¡Correcto!' WHERE `ID`=35702;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드는 정의를 원한다! 이제 얼라이언스에 도전한다! 성기사여, 우리가 그대의 기사를 대신하여 싸우도록 하라. 호드를 모욕한 대가를 이 쓰레기들에게 보여줄 테니.', `MaleText_loc4`='部落需要公正！我们向联盟挑战！请允许我们代你出战，圣骑士。我们要让那些狗知道侮辱部落的下场。', `MaleText_loc5`='部落的正義必將伸張!我們挑戰聯盟!讓我們代替你的騎士而戰吧，聖騎士。我們會讓這些蠢狗知道羞辱部落的下場。', `MaleText_loc7`='¡La Horda demanda justicia! ¡Desafiamos a la Alianza! Permítenos luchar en el lugar de tus caballeros, paladín. Les mostraremos a estos perros lo que significa insultar a la Horda.' WHERE `ID`=35703;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실패!', `MaleText_loc4`='步骤错误！', `MaleText_loc5`='錯誤!', `MaleText_loc7`='¡Incorrecto!' WHERE `ID`=35704;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앞으로 일어날 일의 맛보기일 뿐이다. 호드를 위하여!', `MaleText_loc4`='这只是一个小小的开始。为了部落！', `MaleText_loc5`='那只是讓你們知道將來必須面對的命運。為了部落!', `MaleText_loc7`='Eso es sólo una probada de lo que traerá el futuro. ¡POR LA HORDA!' WHERE `ID`=35705;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성기사여, 아직 호드의 힘에 의문을 품는가? 오는 대로 모두 상대해주겠다!', `MaleText_loc4`='圣骑士，你还在怀疑部落的力量吗？我们战无不胜！', `MaleText_loc5`='你對部落的力量還有任何疑慮嗎，聖騎士?我們將會解決每個對手!', `MaleText_loc7`='¿Aún cuestionas el poderío de la Horda, paladín? ¡Lidiaremos con lo que venga!' WHERE `ID`=35706;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피의 투기장도 이것보다는 훨씬 낫겠군. 우리 시간을 낭비하지 마라.', `MaleText_loc4`='我在鲜血之环经历过更强大的挑战。这是浪费时间，圣骑士。', `MaleText_loc5`='我在血色競技場經歷過更艱難的挑戰。你在浪費我們的時間，聖騎士。', `MaleText_loc7`='He visto desafíos más dignos en el Círculo de Sangre. Nos haces perder el tiempo, paladín.' WHERE `ID`=35707;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오게, 용사들이여! 은빛십자군의 부름에 담대히 응한 모두를 환영하네! 바로 이곳, 십자군 원형경기장에서 제군들은 엄청난 도전에 마주칠 걸세. 혹독한 원형경기장에서 살아남는 자는 은빛십자군의 일원이 되어 얼음왕관 성채로 진군해 나갈 걸세.', `MaleText_loc4`='欢迎，勇士们！你们听到了银色北伐军的号召，并勇敢地作出了响应！此时此地，就在十字军演武场，你们将面对最强大的挑战。能在这次选拔中活下来的人都将加入北伐的行列，共同进军冰冠堡垒！', `MaleText_loc5`='歡迎，勇士們!你們聽從銀白十字軍的號召前來，英勇的挺身而出。就在此地，十字軍的大競技場，你們將會面對前所未有的挑戰。通過大競技場嚴苛挑戰的人，將會加入銀白十字軍的行列，一同進軍冰冠城塞。', `MaleText_loc7`='¡Bienvenidos, campeones! ¡Han oído el llamado de la Cruzada Argenta y han respondido valerosamente! Es aquí, en el Coliseo de los Cruzados,  que enfrentarán sus más grandes desafíos. Quienes sobrevivan a los rigores del coliseo se unirán a la Cruzada Argenta en su marcha a la Ciudadela de la Corona de Hielo.' WHERE `ID`=35708;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경기를 시작하게!', `MaleText_loc4`='让游戏开始吧！', `MaleText_loc5`='讓賽事開始吧!', `MaleText_loc7`='¡Que comiencen los juegos!' WHERE `ID`=35709;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭풍우 봉우리의 가장 깊고 어두운 동굴에서 온, 꿰뚫는 자 고르목일세! 영웅들이여, 전투에 임하게!', `MaleText_loc4`='他来自风暴峭壁最幽深，最黑暗的洞穴，穿刺者戈莫克！准备战斗，英雄们！', `MaleText_loc5`='來自風暴群山最深邃，最黑暗的洞穴。歡迎『穿刺者』戈莫克!戰鬥吧，英雄們!', `MaleText_loc7`='¡De las cavernas más profundas y oscuras de las Cumbres Tormentosas: Gormok el Empalador! ¡Al combate, héroes!' WHERE `ID`=35710;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마음을 단단히 먹게, 영웅들이여. 두 배의 공포, 산성아귀와 공포비늘이 투기장으로 들어온다네!', `MaleText_loc4`='做好准备，英雄们，两头猛兽已经进入了竞技场！它们是酸喉和恐鳞！', `MaleText_loc5`='準備面對酸喉和懼鱗的雙重夢魘吧，英雄們，快就定位!', `MaleText_loc7`='¡Prepárense, héroes: los gemelos terribles, Fauceácida y Aterraescama, entran a la arena!' WHERE `ID`=35711;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음은, 소개하는 순간 공기마저 얼어붙게 하는 얼음울음일세! 죽이지 않으면 죽을 걸세, 용사들이여!', `MaleText_loc4`='当下一名斗士出场时，空气都会为之冻结！它是冰吼，胜或是死，勇士们！', `MaleText_loc5`='下一場參賽者的出場連空氣都會為之凝結:冰嚎!戰個你死我活吧，勇士們!', `MaleText_loc7`='El mismísimo aire se congela al presentar a nuestro próximo combatiente, ¡Aullahielo! ¡Maten o mueran, campeones!' WHERE `ID`=35712;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끔찍한 괴물들이 무릎을 꿇었네!', `MaleText_loc4`='这些恐怖的野兽终于被消灭了！', `MaleText_loc5`='巨獸已經被參賽者擊敗了!', `MaleText_loc7`='¡El zoológico monstruoso ha sido derrotado!' WHERE `ID`=35713;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비극이야... 저들은 용감하게 싸웠지만, 노스렌드의 야수들이 승리를 거뒀네. 쓰러진 영웅을 위해 잠시 묵념을 올리세.', `MaleText_loc4`='悲剧……他们英勇奋战，但还是没有制服诺森德的猛兽。让我们为这些死去的英雄默哀。', `MaleText_loc5`='真可惜...他們英勇的奮戰，但獲勝的是北裂境巨獸。讓我們為這些倒下的英雄們默哀片刻。', `MaleText_loc7`='Trágico... Pelearon con valentía, pero las bestias del Rasganorte triunfaron. Guardemos un momento de silencio por nuestros héroes caídos.' WHERE `ID`=35714;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대흑마법사 윌프레드 피즐뱅이 다음 상대를 소환할 걸세. 기다리고 있게나.', `MaleText_loc4`='高阶术士威尔弗雷德·菲兹班将是你们的下一个对手。等待他的上场吧。', `MaleText_loc5`='大術士威爾弗雷德·菲斯巴恩將會召喚你們的下一個挑戰者。等待他的登場吧。', `MaleText_loc7`='El Gran Brujo Wilfred Chispobang invocará a tu siguiente desafío. Espera su ingreso.' WHERE `ID`=35715;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서두르게, 영웅들이여. 악마 군주가 뒤틀린 악마 세계로 차원문을 열기 전에 처치하게!', `MaleText_loc4`='快，英雄们，消灭那只恶魔，不要让他打开通向恶魔空间的传送门！', `MaleText_loc5`='快，英雄們，在惡魔領主開啟扭曲虛空傳送門之前消滅它!', `MaleText_loc7`='¡Rápido, héroes, destruyan el amo demoníaco antes de que abra un portal de su reino retorcido!' WHERE `ID`=35716;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='윌프레드 피즐뱅을 잃은 일은 안 됐지만, 흑마법으로 장난치는 자들에게는 교훈이 되었을 걸세. 아, 자네는 승리를 거뒀으니 다음 도전을 해야겠지.', `MaleText_loc4`='很遗憾，我们失去了威尔弗雷德·菲兹班，但这也给那些胆敢研习黑暗魔法的人们敲响了警钟。唉，你胜利了。准备面对下一个挑战吧。', `MaleText_loc5`='威爾弗雷德·菲斯巴恩的死亡雖然不幸，但可讓那些鑽研黑暗魔法的人們引以為戒。你已獲勝了，現在必須面對下一個的挑戰。', `MaleText_loc7`='La pérdida de Wilfred Chispobang, si bien desafortunada, es una lección para el que se atreva a incursionar en la magia negra. La victoria es suya y ahora deben enfrentar el siguiente desafío.' WHERE `ID`=35717;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 흥분을 가라앉히고 진정하십시오! 이 경기엔 아무 음모도 없었습니다! 저 흑마법사는 얼라이언스와 상관없이 행동한 겁니다. 마상시합은 계속 진행되어야 합니다!', `MaleText_loc4`='大家冷静！不要慌乱！这并不是什么阴谋！这名术士只是在按照自己的意愿行事，并不是联盟的授意。比赛必须继续！', `MaleText_loc5`='大家冷靜!鎮定!這並不是什麼陰謀!這是術士他個人的行為，與聯盟無關。聯賽必須繼續進行!', `MaleText_loc7`='¡Cálmense todos! ¡Tranquilícense! ¡Aquí no hay ninguna conspiración! El brujo actuó por voluntad propia, libre de la influencia de la Alianza. ¡El torneo debe continuar!' WHERE `ID`=35718;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음 전투는 은빛십자군에서 가장 센 기사들을 상대해야 하네... 그들을 이겨야만 자신의 가치를 인정받을 걸세.', `MaleText_loc4`='接下来你们将面对银色北伐军最强的骑士！只有打败他们，才能证明你的价值……', `MaleText_loc5`='下一場戰鬥必須面對銀白十字軍最強大的騎士!唯有擊敗他們，才能證明你們的實力...', `MaleText_loc7`='¡La siguiente batalla será contra los caballeros más poderosos de la Cruzada Argenta! Sólo venciéndolos serán considerados dignos…' WHERE `ID`=35719;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋습니다. 그러시지요. 명예롭게 싸워 주십시오!', `MaleText_loc4`='好吧，我同意了。为荣誉而战吧！', `MaleText_loc5`='很好。我允許這麼做。懷著榮譽而戰!', `MaleText_loc7`='Muy bien. Lo permitiré. ¡Luchen con honor!' WHERE `ID`=35720;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상처뿐인 승리로군. 오늘 받은 손해로 우리 전력은 약해졌네. 이런 어리석은 짓으로 리치 왕 말고 또 누가 이득을 보겠나? 위대한 용사들이 목숨을 잃었네. 무엇을 위해서였나? 진짜 위협은 저 앞에 있네. 리치 왕이 우리 모두를 죽음 안에서 기다린다네.', `MaleText_loc4`='肤浅且可悲的胜利。今天的内耗让我们又一次被削弱了。这种愚蠢的行为只能让巫妖王受益！伟大的战士们就这样白白牺牲，而真正的威胁却步步逼近。巫妖王正计算着我们的死期。', `MaleText_loc5`='膚淺而悲痛的勝利。今天痛失的生命反而令我們更加的頹弱。除了巫妖王之外，誰還能從中獲利?偉大的戰士失去了寶貴生命。為了什麼?真正的威脅就在前方 - 巫妖王在死亡的領域中等著我們。', `MaleText_loc7`='Una victoria trágica y superficial. Nuestra integridad se vio debilitada por las pérdidas que hoy sufrimos. ¿Quién más que el Rey Exánime puede haberse beneficiado de tal insensatez? Grandes guerreros han perdido sus vidas. ¿Y para qué? La verdadera amenaza se entreteje en el futuro: el Rey Exánime nos espera en la muerte.' WHERE `ID`=35721;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='함께 힘을 모아야만 마지막 도전을 이겨낼 수 있네. 얼음왕관 심연에서 가장 강력한 스컬지 대리인 둘이 왔네. 무시무시한 발키르, 날개를 단 리치 왕의 전령일세!', `MaleText_loc4`='你们只有团结才能战胜最终的挑战。来自于冰冠冰川的深处，天灾军团最强的战将：巫妖王的双翼使者，恐怖的瓦格里！', `MaleText_loc5`='唯有同心協力，你們才能克服最後的難關。來自寒冰皇冠的深處，兩名天譴軍團最強大的副官:令人生畏的華爾琪，披著羽翼的巫妖王先驅。', `MaleText_loc7`='Sólo trabajando juntos superarán el desafío final. De las profundidades de Corona de Hielo llegan estos poderosos tenientes de la Plaga: ¡los val''kyres, heraldos alados del Rey Exánime!' WHERE `ID`=35722;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕에게 큰 타격을 주었군! 그대들은 은빛십자군의 강건한 용사임을 입증했네. 우리는 함께 얼음왕관 성채를 공격하고 남은 스컬지를 물리칠 걸세! 힘을 합친 우리가 이겨내지 못할 도전은 없네!', `MaleText_loc4`='这是对巫妖王的一次重创！你的实力绝不亚于银色北伐军的勇士。很快，我们将携手攻入冰冠堡垒，消灭天灾军团的残余！只要心齐，我们必将胜利！', `MaleText_loc5`='巫妖王遭受了迎頭痛擊!你們已經證明了你們是銀白十字軍的精銳勇士。我們將聯手攻陷冰冠城塞，並且把天譴軍團消滅殆盡!團結一心，我們將可破除所有難關。', `MaleText_loc7`='¡El Rey Exánime ha sufrido un poderoso revés! Han demostrado ser campeones dignos de la Cruzada Argenta. ¡Juntos atacaremos la Ciudadela Corona de Hielo y destruiremos lo que queda de la Plaga! ¡No existe el desafío que no podamos enfrentar unidos!' WHERE `ID`=35723;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아서스! 넌 이미 수적으로 열세다! 서리한을 내려놓아라. 합당한 죽음을 안겨주겠다.', `MaleText_loc4`='阿尔萨斯！你已经孤立无援了！放下霜之哀伤，我会让你死个痛快。', `MaleText_loc5`='阿薩斯!強弱懸殊顯而易見!放下手中的霜之哀傷，讓我賞你一個痛快。', `MaleText_loc7`='¡Arthas! ¡Tus tropas son totalmente inferiores! Depón a Agonía de Escarcha y recibirás una muerte justa.' WHERE `ID`=35724;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='십자군의 시험에 출전한 모두를 환영하네! 아제로스의 가장 강력한 투사만이 이 시험을 치를 수 있지. 자네들은 진정 가치 있는 자들일세!', `MaleText_loc4`='欢迎参加十字军的试炼！只有全艾泽拉斯最强大的斗士才能参加这次选拔。而你正是其中之一。', `MaleText_loc5`='歡迎來到十字軍的試煉!唯有艾澤拉斯最強大的戰士才能通過這個考驗。你們正是少數夠格的菁英。', `MaleText_loc7`='¡Bienvenidos a las Pruebas de los Cruzados! Sólo los combatientes más poderosos de Azeroth pueden formar parte. Se encuentran entre los pocos dignos. ' WHERE `ID`=35725;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다, 대영주님. 도전자 여러분, 소환 의식을 시작하겠어요. 이 의식이 끝나면 무시무시한 파멸의 수호병이 나타날 거예요!', `MaleText_loc4`='感谢你，大领主。挑战者们，我将开始召唤仪式。当仪式完成时，一个恐怖的末日守卫就会出现！', `MaleText_loc5`='感謝你，大領主。聽好，挑戰者，我即將施展召喚儀式。完成時，一個可怕的末日守衛將隨之現身!', `MaleText_loc7`='Gracias, Alto Señor. Ahora, retadores, comenzaré el ritual de invocación. ¡Cuando termine, un Guardia apocalíptico aparecerá!' WHERE `ID`=35726;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='눈 크게 뜨고 보세요!', `MaleText_loc4`='准备迎接末日吧！', `MaleText_loc5`='準備迎接滅亡吧!', `MaleText_loc7`='¡Prepárense para el olvido!' WHERE `ID`=35727;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='짜잔! 해냈어요! 이 엄청난 능력을 보세요! 소환의 대가, 윌프레드 피즐뱅입니다! 너는 이제 내 부하다, 악마야!', `MaleText_loc4`='啊哈！我做到了！看看召唤大师威尔弗雷德·菲兹班强大的力量吧！为我效命吧，恶魔！', `MaleText_loc5`='啊哈!我成功了!瞧瞧召喚大師，威爾弗雷德·菲斯巴恩的能耐吧!你將遵從我的約束，惡魔!', `MaleText_loc7`='¡A JÁ! ¡Lo logré! ¡Contemplen el poder absoluto de Wilfred Chispobang, amo y señor de la invocación! ¡Estás bajo mi control, demonio!' WHERE `ID`=35728;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니, 그래도 내가 불러냈잖...', `MaleText_loc4`='我才是主人……呦，哦……哦……', `MaleText_loc5`='我才是老大呀...', `MaleText_loc7`='Pero yo estoy a cargo aquí…' WHERE `ID`=35729;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보이지도 않는 노움 주제에! 그렇게 까불더니 무덤을 파는구나!', `MaleText_loc4`='渺小的侏儒！你们的傲慢将会招致灭亡！', `MaleText_loc5`='卑微的地精!你的傲慢將使你喪命!', `MaleText_loc7`='¡Gnomo insignificante! ¡Tu arrogancia será tu perdición!' WHERE `ID`=35730;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불타는 군단의 에레다르 군주, 자락서스 님이 상대해주마!', `MaleText_loc4`='面对加拉克苏斯吧，燃烧军团的艾瑞达之王！', `MaleText_loc5`='你面對的是賈拉克瑟斯，燃燒軍團的埃雷達爾領主!', `MaleText_loc7`='¡Te enfrentas a Jaraxxus, señor Eredar de la Legión Ardiente!' WHERE `ID`=35731;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시시하구나!', `MaleText_loc4`='卑微的虫子！', `MaleText_loc5`='卑賤的小蟲!', `MaleText_loc7`='¡Mosquito insignificante!' WHERE `ID`=35732;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황천으로 사라져라!', `MaleText_loc4`='被逐入虚空吧！', `MaleText_loc5`='放逐到虛空吧!', `MaleText_loc7`='¡Desterrado al Abisal!' WHERE `ID`=35733;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 누군가 날 대신하여 오리라. 그러면, 다 끝이다...', `MaleText_loc4`='会有人来代替我。而你们注定要被毁灭……', `MaleText_loc5`='有人會代替我，你的世界注定毀滅...', `MaleText_loc7`='Alguien más ocupará mi lugar. Tu mundo está condenado…' WHERE `ID`=35734;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뼈에서 살을!', `MaleText_loc4`='血肉成灰！', `MaleText_loc5`='焚肉挫骨!', `MaleText_loc7`='¡ARRANCARÉ LA CARNE!' WHERE `ID`=35735;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나오너라, 자매여! 네 주인이 부르노라!', `MaleText_loc4`='前进！这是主人的命令！', `MaleText_loc5`='來吧，姊妹!你的主人呼喚妳!', `MaleText_loc7`='¡Acércate, hermana! ¡Tu amo te llama!' WHERE `ID`=35736;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지옥불을 받아라!', `MaleText_loc4`='地狱——之火！', `MaleText_loc5`='煉獄-現世!', `MaleText_loc7`='¡IN-FIER-NO!' WHERE `ID`=35737;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어둠의 주인님을 받들어. 리치 왕을 위하여. 너희에게. 죽음을. 안기리라.', `FemaleText_loc4`='以黑暗之主的名义。为了巫妖王。你必死无疑。', `FemaleText_loc5`='以我們的黑暗君王之名。為了巫妖王。你‧得‧死。', `FemaleText_loc7`='En el nombre de nuestro amo oscuro. Por el Rey Exánime. Ustedes. Mueren. Hoy.' WHERE `ID`=35738;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='실력을 확인해보니 한참 모자라는구나.', `FemaleText_loc4`='我们确认了你的力量，知道你正是我们需要的人。', `FemaleText_loc5`='經過了估量，你還不夠格...', `FemaleText_loc7`='Has sido evaluado y determinado deficiente.' WHERE `ID`=35739;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하찮은 것!', `FemaleText_loc4`='无能！', `FemaleText_loc5`='你不配!', `FemaleText_loc7`='¡Indigno!' WHERE `ID`=35740;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='스컬지를 막을 수는 없다...', `FemaleText_loc4`='天灾军团无人可挡……', `FemaleText_loc5`='誰也阻擋不了天譴軍團...', `FemaleText_loc7`='La Plaga es imparable…' WHERE `ID`=35741;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너희는 끝장이다!', `FemaleText_loc4`='你被终结了！', `FemaleText_loc5`='你完了!', `FemaleText_loc7`='¡Estás acabado!' WHERE `ID`=35743;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='혼돈!', `FemaleText_loc4`='混乱！', `FemaleText_loc5`='混亂!', `FemaleText_loc7`='¡CAOS!' WHERE `ID`=35744;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어둠이 너희를 삼키리라!', `FemaleText_loc4`='让黑暗吞噬你！', `FemaleText_loc5`='讓黑暗吞噬你!', `FemaleText_loc7`='¡Deja que la oscuridad te consuma!' WHERE `ID`=35745;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='빛이 너희를 삼키리라!', `FemaleText_loc4`='让光明焚毁你！', `FemaleText_loc5`='讓光明吞噬你!', `FemaleText_loc7`='¡Deja que la luz te consuma!' WHERE `ID`=35746;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폴드링, 이제 네게 마땅한 도전이 있으리라.', `MaleText_loc4`='会有人战败你的，弗丁。', `MaleText_loc5`='你將會面對你的挑戰，弗丁。', `MaleText_loc7`='Tendrás tu desafío, Vadín.' WHERE `ID`=35747;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네루비안은 노스렌드의 얼어붙은 황무지 아래에 왕국을 건설했다. 그런데, 멍청하게도 넌 그 왕국 위에 이것저것 세우더군. 바로 내 왕국 위에 말이다.', `MaleText_loc4`='蛛魔在诺森德的冻土荒原地下建立了一个帝国。只有最愚蠢的人才会在这个帝国上方建起房屋。那是我的帝国！', `MaleText_loc5`='奈幽蟲族在北裂境的凍土荒原之下建立了一個帝國。一個你們愚蠢到把房舍建築於其上的帝國。我的帝國。', `MaleText_loc7`='Los nerubianos construyeron un imperio bajo los páramos congelados de Rasganorte. Un imperio sobre el que ustedes edificaron imprudentemente. MI IMPERIO.' WHERE `ID`=35748;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폴드링, 네 용사가 쓰러지면 그 영혼은 내가 취하겠다.', `MaleText_loc4`='你们死去勇士的灵魂都将属于我，弗丁。', `MaleText_loc5`='你們死去勇士的靈魂是屬於我的，弗丁。', `MaleText_loc7`='Las almas de tus campeones caídos serán mías, Vadín.' WHERE `ID`=35749;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아, 주인님께서 약속하신 대로 손님이 왔구나.', `MaleText_loc4`='啊，我们的客人到了，主人说的果然没错。', `MaleText_loc5`='啊，我們的客人到了，正如主人所預期。', `MaleText_loc7`='Aahh, han llegado nuestros invitados, como lo prometió el amo.' WHERE `ID`=35750;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기가 네 무덤이 되리라!', `MaleText_loc4`='这里将是你的葬身之地！', `MaleText_loc5`='這裡將會是你們的墳墓!', `MaleText_loc7`='¡Este lugar será su tumba!' WHERE `ID`=35751;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='프을라크 쉬얼!', `MaleText_loc4`='F-lakkh shir！', `MaleText_loc5`='(蟲族語)脆弱的肉體!', `MaleText_loc7`='¡F-lakkh shir!' WHERE `ID`=35752;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배를 채울 영혼이 또 생겼구나.', `MaleText_loc4`='又是一个献给主人的灵魂。', `MaleText_loc5`='另一個讓主人享用的靈魂。', `MaleText_loc7`='Otra alma para satisfacer al anfitrión.' WHERE `ID`=35753;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실망시켜 드렸군요, 주인님...', `MaleText_loc4`='我让您失望了，主人……', `MaleText_loc5`='我讓你失望了，主人...', `MaleText_loc7`='Le he fallado, amo…' WHERE `ID`=35754;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아움 날락크, 쉬. 일어나라, 부하들아. 먹어치워라...', `MaleText_loc4`='Auum na-l ak-k-k-k, isshhh。起来，奴仆们，吃吧……', `MaleText_loc5`='(蟲族語)靠上來，兄弟們。起來，爪牙們，吞噬...', `MaleText_loc7`='Auum na-l ak-k-k-k, isshhh. Despierten, lacayos. Devoren…' WHERE `ID`=35756;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='착취의 무리가 너희를 덮치리라!', `MaleText_loc4`='虫群会吞噬你！', `MaleText_loc5`='蟲群將會淹沒你們!', `MaleText_loc7`='¡El enjambre te alcanzará!' WHERE `ID`=35757;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='각오하십시오!', `MaleText_loc4`='做好准备！', `MaleText_loc5`='做好準備!', `MaleText_loc7`='¡Prepárense!' WHERE `ID`=35758;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신! 훈련을 더 하셔야겠군요.', `MaleText_loc4`='呃！你！回去再练练吧。', `MaleText_loc5`='你!你需要更多練習。', `MaleText_loc7`='¡Ustedes! Necesitan más práctica.' WHERE `ID`=35759;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니야, 틀렸어. 아니라니까! 아직 멀었습니다!', `MaleText_loc4`='不！不！我再说一遍，不！还不够好。', `MaleText_loc5`='不!不!我得再說一次，不行!還不夠好。', `MaleText_loc7`='¡No! ¡No! ¡Y lo repito: no! No alcanzó.' WHERE `ID`=35760;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='항복! 제가 졌습니다. 훌륭한 솜씨군요. 이제 집에 가도 되겠습니까?', `MaleText_loc4`='我认输！我投降。你做的很好。我可以走了吧？', `MaleText_loc5`='我認輸了!我投降。幹得好。我現在可以離場了嗎?', `MaleText_loc7`='¡Me rindo! Abandono. Excelente trabajo. ¿Ya me puedo ir corriendo?' WHERE `ID`=35761;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고마워요, 친절한 전령이군요. 멋진 소개였어요.', `FemaleText_loc4`='感谢你，传讯者，你的话真令我高兴。', `FemaleText_loc5`='感謝您，信使。您太客氣了。', `FemaleText_loc7`='Gracias, buen heraldo. Tus palabras son muy amables.' WHERE `ID`=35762;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 도전이 헛되지 않도록. 빛이여, 제게 힘을 주소서.', `FemaleText_loc4`='愿圣光赐我力量，让我不负众望。', `FemaleText_loc5`='願聖光賜我力量，成為挑戰者的典範。', `FemaleText_loc7`='Que la Luz me de la fuerza para brindar un reto digno.' WHERE `ID`=35763;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이번 기회에 과거의 행실을 돌아보도록 하세요.', `FemaleText_loc4`='现在，让时光在你脑中倒流。', `FemaleText_loc5`='沉浸在過往的回憶之中吧。', `FemaleText_loc7`='Aprovecha este momento para pensar en tus acciones pasadas.' WHERE `ID`=35764;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그대에게 안식을.', `FemaleText_loc4`='下去休息吧。', `FemaleText_loc5`='好好休息吧。', `FemaleText_loc7`='Descansa.' WHERE `ID`=35765;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='쉿, 잘자요.', `FemaleText_loc4`='安心的去吧。', `FemaleText_loc5`='安歇吧。', `FemaleText_loc7`='Tranquilo.' WHERE `ID`=35766;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장난은 여기까지다!', `MaleText_loc4`='这场闹剧该结束了！', `MaleText_loc5`='這場鬧劇就此結束!', `MaleText_loc7`='¡Esta farsa se termina ahora!' WHERE `ID`=35767;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한심하군.', `MaleText_loc4`='可怜。', `MaleText_loc5`='可悲。', `MaleText_loc7`='Patético.' WHERE `ID`=35768;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살점 낭비군.', `MaleText_loc4`='真是对生命的浪费。', `MaleText_loc5`='虛擲生命。', `MaleText_loc7`='Qué desperdicio de carne.' WHERE `ID`=35769;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 또 무릎 꿇을 수는... 없는데...', `MaleText_loc4`='不！我绝不能再……失败了……', `MaleText_loc5`='不!我不能再次...失敗...', `MaleText_loc7`='¡No! No debo fallar... de nuevo…' WHERE `ID`=35770;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='썩어가는 살점 따위는 방해만 될 뿐이다!', `MaleText_loc4`='我的烂肉还真碍事！', `MaleText_loc5`='我的腐爛血肉有些礙事!', `MaleText_loc7`='¡Mi piel putrefacta me estorbaba!' WHERE `ID`=35771;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈들 따위를 처리하는 데 뼈는 필요 없다!', `MaleText_loc4`='我可不需要用骨头来打败你！', `MaleText_loc5`='我不需要骸骨的協助就能幹掉你們!', `MaleText_loc7`='¡No necesito huesos para ganarte!' WHERE `ID`=35772;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간 초과!', `MaleText_loc4`='时间结束！', `MaleText_loc5`='時間到!', `MaleText_loc7`='¡Se acabó el tiempo!' WHERE `ID`=35773;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고대의 전쟁에 대해 잘 아십니까, $n 님? 만 년 전, 불타는 군단의 악마가 아제로스 세계를 처음 침략했습니다. 다른 수많은 세계처럼 여기도 집어삼키려고 말이죠. 그때를 가리켜 고대의 전쟁이라고 합니다. 한때 이곳을 지배했던 고대 도시 아즈샤라는 그 침공으로 완전히 파괴되었지요. 이 지역 어디에서나 볼 수 있는 고대의 잔해는 우리 선조의 자만을 보여주는 부서진 증거입니다.', `FemaleText_loc4`='你了解上古战争吗，$n？那是在万年以前发生的事情。那时，燃烧军团的恶魔第一次到达艾泽拉斯。他们打算将这个世界彻底吞噬，就如同他们吞噬无数个其它世界一样。在这次入侵中，这片土地曾经的心脏——艾萨拉的古老首都被夷为平地。你会在这一地区的各个角落找到古老的废墟遗迹，它们就是祖先曾经自负的证据。', `FemaleText_loc5`='你對先祖之戰瞭解嗎，$n?那是我們對一萬年前的世代的稱呼，那個燃燒軍團無數的惡魔們入侵了艾澤拉斯，想要吞噬整個世界的時代。古老的首都艾薩拉，曾經昂首立於大地的城市，在那次的侵略中被夷為平地。那些四散於附近的古老殘骸便是我們那些自大祖先曾經存在的可悲證據。', `FemaleText_loc7`='¿Has oído hablar de la guerra de los Ancestros, $n? Así es como llamamos a ese período de tiempo de hace 10,000 años, cuando los demonios de la Legión Ardiente entraron por primera vez en el reino de Azeroth e intentaron devorar todo el mundo, porque tenían muchos más. La antigua capital de Azshara, una ciudad que en otros tiempos dominaba este paisaje, fue el lugar donde comenzó la invasión. Los restos antiguos que encontrarás desperdigados por toda esta zona son el testimonio de la presunción de nuestros antepasados.' WHERE `ID`=35774;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 여기서 무엇을 하고 있습니까?', `MaleText_loc4`='你在这里干什么？', `MaleText_loc5`='你在這做什麼?', `MaleText_loc7`='¿Qué haces aquí?', `FemaleText_loc1`='당신은 여기서 무엇을 하고 있습니까?', `FemaleText_loc4`='你在这里干什么？', `FemaleText_loc5`='你在這做什麼?', `FemaleText_loc7`='¿Qué haces aquí?' WHERE `ID`=35775;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지금은 동쪽의 멘나르 호수를 둘러싼 폐허를 조사하고 있습니다. 수천 년 전, 비전 마법을 처음 연구하기 시작한 단체 중에 멘나르 학회도 있습니다. 멘나르 학회의 아름다운 건물들은 고요한 호수 주변을 빙 둘러 서 있었죠. 조용히 사색에 잠기고 연구에 몰두하기 좋은 곳이었습니다. 제 선조들이 영원의 샘에서 마법의 힘이 스며 나올 가능성을 처음 발견한 것도 바로 그곳에서 있었던 일이죠.$B$B죄송해요. 이야기가 너무 장황하죠? 수십 년간 비전 마법의 역사에 깊이 빠져들었더니, 다른 사람들이 제 열정을 이해하기 어려울 거라는 사실을 잊고 말았습니다.', `FemaleText_loc4`='我现在很关心东边门纳尔湖周围的废墟。千万年以前，门纳尔学院第一个开始研究奥术的技艺，那是一座美丽的多层建筑，环绕一座平静的湖泊，非常有利于贤者们沉思和冥想。正是在那里，我的祖先首先发现魔法能量从永恒之井中溢出。$B$B很抱歉，我的介绍是不是太过冗长了？至今为止，我沉浸在这段神秘的历史中已经有数十年之久。我忘记了，其他人并不一定有和我一样的兴趣。', `FemaleText_loc5`='我現在擔心的是我們東邊圍繞著門納爾湖的廢墟。幾千年前，門納爾學院是最早研究秘法系別魔法的學院。它曾是一個花園式的建築，環繞著平靜的湖面，一個可以潛心進行研究的地方。就在那，我的祖先發現了永恆之井所蘊藏著的魔法能量。$B$B抱歉，訊息太多一下子無法接受嗎?我已經幾世紀都沉浸在秘法的歷史研究中，忘了其他人不會像我一樣那麼的狂熱。', `FemaleText_loc7`='Mi preocupación principal ahora mismo son las ruinas que rodean el lago Mennar, al este. Hace miles de años la Academia Mennar fue una de las primeras en estudiar las artes arcanas. Era un edificio construido en terrazas, muy hermoso, que se alzaba en forma de anillo alrededor del tranquilo lago. Fue allí donde mis antepasados descubrieron el potencial de las energías mágicas que se filtraban del Pozo de la Eternidad.$B$BLo siento, ¿es demasiada información de una vez? Llevo varias décadas inmersa en la historia de lo arcano y olvido que no todo el mundo comparte mi pasión.' WHERE `ID`=35776;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아뇨, 계속하십시오.', `MaleText_loc4`='不，请继续。', `MaleText_loc5`='請繼續下去。', `MaleText_loc7`='No, continúa, por favor.', `FemaleText_loc1`='아뇨, 계속하십시오.', `FemaleText_loc4`='不，请继续。', `FemaleText_loc5`='請繼續下去。', `FemaleText_loc7`='No, continúa, por favor.' WHERE `ID`=35777;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어쨌든 학회에서는 이 새로운 힘을 사용하는 데 신중한 입장이었습니다... 남아 있는 일부 문서를 보면, 거기 있던 마법사들은 비전 마력에 중독되는 것을 우려했던 것 같습니다. 사실 저희 종족은 바로 이 문제 때문에 아직 고통받고 있죠.$B$B이러한 분위기로 말미암아 멘나르의 마법사들은 더욱 강력한 힘을 추구했던 아즈샤라 여왕과 그의 명가 추종자들과 맞서게 되었습니다. 그들은 방종에 빠져 조심성이라고는 전혀 없이 더욱 위험한 마법 속으로 깊이 파고들었습니다.', `FemaleText_loc4`='总的来说，学院对于这种新发现的力量抱着相当谨慎的态度。从那个时代留存下来所剩无几的史籍资料来看，当时的贤者法师们非常担心我们会沉迷在这种奥术能量中而无法自拔,而这正是时至今日仍困扰我族的麻烦根源。$B$B因此，门纳尔贤者们最终与艾萨拉女王和她的上层精灵仆从决裂。而艾萨拉女王和她的奴仆很快便肆无忌惮地汲取并滥用这股力量，丝毫不在意这其中蕴含的巨大危险。', `FemaleText_loc5`='足夠的證據顯示學院對這些新發現的能量非常小心。少數的報告仍舊指出法師們對沉溺於秘法能量感到憂心，這也是我們一族到現在都還會碰到的問題。$B$B這個限制使門納爾的法師們與艾薩拉女王和她的精靈貴族走狗成為了對立的形勢，艾薩拉女王擁有對力量無止境的渴望，瘋狂地放縱這方面的研究，疏忽了運用魔法所帶來的危險副作用而越陷越深。', `FemaleText_loc7`='No hace falta decir que la academia era muy cuidadosa con la aplicación de esos poderes recién descubiertos. Los pocos escritos que nos han llegado indican que los magos estaban preocupados por la adicción a lo arcano, un problema que mi raza sigue sufriendo incluso hoy en día.$B$BEsa limitación autoimpuesta puso a los magos de Mennar en contra de la reina Azshara y sus lacayos Altonato, que buscaban mayores poderes sin preocuparse por nada más, sin tomar precauciones y desarrollando incluso aplicaciones más peligrosas para las artes.' WHERE `ID`=35778;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멘나르의 마법사들에게 무슨 일이 일어났습니까?', `MaleText_loc4`='那些贤者们最后怎样了？', `MaleText_loc5`='那些法師們發生了什麼事?', `MaleText_loc7`='¿Qué pasó con los magos?', `FemaleText_loc1`='멘나르의 마법사들에게 무슨 일이 일어났습니까?', `FemaleText_loc4`='那些贤者法师们最后怎样了？', `FemaleText_loc5`='那些法師們發生了什麼事?', `FemaleText_loc7`='¿Qué pasó con los magos?' WHERE `ID`=35779;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='불타는 군단의 공격이 시작될 무렵, 멘나르 학회의 마법사들은 여왕과 완전히 등을 돌린 상태였습니다. 그때 한발 물러섰더라면 이후의 전쟁에서 강력한 병력이 될 수도 있었을 텐데, 그들은 도시 전체가 무너지는 상황에서도 물러서지 않았지요.$B$B멘나르의 마법사들은 다른 곳에서 재정비하여 침략에 맞서는 대신 도시에 남아서 마법의 장벽을 세우고, 평화로웠던 자신들의 고향을 요새화했습니다. 피난민들은 끔찍한 침공 초반기에 멘나르 학회로 모여들었고, 생존자들은 방어군을 꾸렸죠.', `FemaleText_loc4`='当燃烧军团发动攻击时，门纳尔学院的贤者法师们已经远离了艾萨拉女王。他们本应该在那场战争中发挥巨大的力量，但当精灵的都市毁灭时，他们拒绝撤退。$B$B他们没有在城外重新集结，加入到反击燃烧军团的队伍中，而是留了下来，竖起魔法屏障，将他们曾经静瑟安详的家园变成一座堡垒。在恶魔入侵刚刚开始的那段恐慌日子里，难民不断涌入门纳尔学院，幸存者们开始在那里建立防御。', `FemaleText_loc5`='當燃燒軍團開始進行侵略時，門納爾學院的法師們與女王已經形同陌路。他們在戰爭中本來會是非常強大的戰力，但他們在城市淪陷時並沒有撤退。$B$B他們並沒有在城市外聚集加入反擊戰，而是待在本來的地方，架起了一道魔法屏障將他們曾經安寧的家鄉變成了一座堡壘。難民在侵略開始的前幾天湧進了門納學院，生還者聚集了起來形成一道堅固的防護網。', `FemaleText_loc7`='Cuando la Legión Ardiente comenzó su ataque, los magos de la Academia Mennar estaban lejos de gozar del beneplácito de la reina. Habrían sido una poderosa ayuda en la guerra que estaba a punto de desatarse, pero se negaron a retirarse cuando el resto de la ciudad cayó.$B$BEn vez de reagruparse en el exterior de la ciudad para unirse al contraataque, se quedaron atrás para levantar barreras mágicas y convertir su tranquilo hogar en una fortaleza. Los refugiados acudieron en masa a la Academia Mennar en los primeros terribles días de la invasión, y los supervivientes se agruparon para montar una defensa.' WHERE `ID`=35780;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들은 저항하는 데 성공했습니까?', `MaleText_loc4`='他们挡住恶魔的进攻了吗？', `MaleText_loc5`='他們成功地堅持了下去嗎?', `MaleText_loc7`='¿Consiguieron aguantar?', `FemaleText_loc1`='그들은 저항하는 데 성공했습니까?', `FemaleText_loc4`='他们挡住恶魔的进攻了吗？', `FemaleText_loc5`='他們成功地堅持了下去嗎?', `FemaleText_loc7`='¿Consiguieron aguantar?' WHERE `ID`=35781;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저항이요? 군단의 선봉대에 맞서서요? 그럴 리 없죠!$B$B그 후로 그들이 어떻게 되었는지는 역사에도 남아 있지 않습니다... 생존자가 없었으니까요. 날뛰는 악마들이 지금 보시는 폐허만을 남겨 놓았고 학회의 비밀은 아즈샤라의 땅속에 아직 묻혀 있습니다.', `FemaleText_loc4`='挡住？面对燃烧军团先锋的全力进攻？这根本不可能！$B$B不，历史没有记录后来发生了什么……那里已经不再有幸存者了。狂暴的恶魔只留下了你今天所看到的这些废墟。学院的秘密就深埋在这片艾萨拉的泥土中。', `FemaleText_loc5`='不要屈服?在軍團先鋒部隊的全面進攻之下?不太可能!$B$B不，歷史並沒有記錄接下來會發生的事...因為完全沒有任何的生還者。狂暴的惡魔們給我們留下的就是你今天看到的這些廢墟，學院的秘密也被埋藏在艾薩拉的泥土之下。', `FemaleText_loc7`='¿Aguantar? ¿Contra un ataque frontal de la vanguardia de la Legión? ¡Desde luego que no!$B$BNo, la historia no recoge lo que ocurrió después... porque no hubo supervivientes. Los demonios furiosos no dejaron más que ruinas que puedes ver, y los secretos de la academia yacen enterrados bajo la tierra de Azshara.' WHERE `ID`=35782;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 그걸 찾아내야겠군요.', `MaleText_loc4`='我们要把他们挖出来。', `MaleText_loc5`='那我們是要把它們挖出來嗎?', `MaleText_loc7`='Y nosotros vamos a desenterrarlos.', `FemaleText_loc1`='우리가 그걸 찾아내야겠군요.', `FemaleText_loc4`='我们要把他们挖出来。', `FemaleText_loc5`='那我們是要把它們挖出來嗎?', `FemaleText_loc7`='Y nosotros vamos a desenterrarlos.' WHERE `ID`=35783;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신 사고방식이 정말 마음에 드는군요, $r|1이여;여;!$B$B얼마 전까지만 해도 학회가 있던 곳에 잠재된 마력이 푸른용군단을 끌어들이는 바람에 연구를 진행할 수가 없었습니다. 이제 용군단의 관심은 다른 곳을 향해 있지만, 더 큰 위협이 나타났어요. 작은 녹색 야만인들이 연료 보급소로 통하는 길을 내려고 폐허를 파괴한다지 뭡니까! 만 년 동안 되찾지 못한 지식이 단 며칠 안에 영원히 사라질 위기에 처했습니다. 빠르게 행동해야 합니다.', `FemaleText_loc4`='我喜欢你的想法，$r！$B$B就在不久以前，埋藏在这片废墟中的魔法能量还一直吸引着蓝龙军团的注意。所以我无法对这里进行研究。而现在，那些巨龙的注意力已经转移到别的地方去了，但一个更加可怕的威胁正在形成——那些绿色的小畜生想要把这片废墟推平，为一座燃料补给站开辟道路！用不了多久，埋藏上万年的神秘知识就将永远遗失了。我们必须尽快采取行动。', `FemaleText_loc5`='我喜歡你的思考方式，$r!$B$B就在最近，學院廢墟潛在的魔法能量吸引了藍龍軍團的注意，但我卻無法進行調查。現在，龍族已經將注意力轉移到其他的地方了，但更大的問題卻威脅著我─這些野蠻的綠色小生物想將廢墟鏟平興建燃料站!已經失去了千年的知識就要在幾天內永遠的從這世界上消失了。我們必須快點行動。', `FemaleText_loc7`='¡Me gusta tu forma de pensar, $r!$B$BHasta hace poco, las energías mágicas latentes de la tierra donde se alzaba la academia atraían la atención del Vuelo Azul y me resultaba imposible estudiarlas. Ahora la atención de los dragones está en otra parte, pero una amenaza mayor se cierne sobre el lugar... ¡Esas pequeñas bestias verdes quieren arrasar las ruinas para abrir el camino para construir un depósito de combustible! El conocimiento perdido hace diez mil años está a unos pocos días de perderse para siempre. Tenemos que actuar rápido.' WHERE `ID`=35784;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스랄 대족장님, 헬스크림 대군주님. 어서 오십시오.', `MaleText_loc4`='欢迎你们，萨尔酋长，地狱咆哮统帅。', `MaleText_loc5`='歡迎，索爾大酋長。地獄吼霸主。', `MaleText_loc7`='Bienvenido, Jefe de Guerra Thrall. Señor Supremo Grito Infernal.' WHERE `ID`=35785;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 일의 가치를 언젠가 아셨으면 합니다, 가로쉬 님. 서로 계속 싸운다면 결코 스컬지를 이길 수 없습니다.', `MaleText_loc4`='我希望你能明白现在的状况，加尔鲁什。如果再这样互相争斗，就休想战胜天灾军团。', `MaleText_loc5`='我希望你能看見這些賽事的正面意義，卡爾洛斯。如果我們仍持戈相對，將無力抵抗天譴軍團。', `MaleText_loc7`='Espero que con el tiempo comprendas el mérito del evento, Garrosh.  No podemos ganarle a la Plaga si continuamos en guerra entre nosotros.' WHERE `ID`=35786;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기에 계시는 동안, 허튼 행동은 안하리라 믿습니다.', `MaleText_loc4`='在我这里，各位，我相信你们不会乱来。', `MaleText_loc5`='在我的地盤，男士們，我相信你們會保持風度。', `MaleText_loc7`='Confío en que se comportarán estando bajo mi techo.' WHERE `ID`=35787;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼, 이쪽으로 오시지요.', `MaleText_loc4`='那就请跟我来。', `MaleText_loc5`='那麼，請跟我來吧。', `MaleText_loc7`='Entonces síganme, por favor.' WHERE `ID`=35788;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛이여, 감사합니다! 이런 미친 짓은 다시는 하지 않겠습니다!', `MaleText_loc4`='感谢圣光！我绝不会再干这种蠢事了！', `MaleText_loc5`='感謝聖光!我再也不會做這種蠢事了!', `MaleText_loc7`='¡Gracias a la Luz! ¡Jamás volveré a hacer algo tan insensato!' WHERE `ID`=35789;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들은 제단에 저를 묶어 영혼을 빨아내려던 참이었습니다. 어서 여길 빠져나갑시다!', `MaleText_loc4`='他们马上就要把我绑在祭坛上，吸取我的灵魂里。让我们赶快离开这里！', `MaleText_loc5`='他們差一點就要把我綁在那些祭壇上，然後把我的靈魂給吸乾了。我們快點離開這吧!', `MaleText_loc7`='Unos segundos más y me hubieran atado a uno de esos altares para absorber mi alma. ¡Salgamos de aquí!' WHERE `ID`=35790;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미친 이교도 놈들을 상대하게 해주십시오! 반으로 쪼개버리겠습니다!', `MaleText_loc4`='让我们狠狠地教训那些邪教疯子！我要把他们全都砍成两段！', `MaleText_loc5`='讓我來對付這些教徒!我要把他們砍成兩半!', `MaleText_loc7`='¡Déjame a esos cultores locos! ¡Los partiré en dos!' WHERE `ID`=35791;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='남은 지원자를 구출해서 돌아갑시다. 이 일이 끝나고 나면 에일을 한 주전자는 마셔야겠어요!', `MaleText_loc4`='让我们救出剩下的候选者，杀回营地去。然后我要喝下满满一桶啤酒！', `MaleText_loc5`='我們快點救出剩下的志士，然後趕回營地吧。回去後我可要來杯特大號的麥芽酒!', `MaleText_loc7`='Rescatemos a los demás aspirantes y volvamos al campamento. ¡Voy a necesitar un barril de cerveza entero después de esto!' WHERE `ID`=35792;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이교도 놈들에게 쓴맛을 보여주세요, $n 님. 이 성전사 쿨 님을 귀찮게 하면 호된 꼴을 면할 수 없지!', `MaleText_loc4`='给那些邪教徒们一个教训。$n。没有人能在惹恼了北伐军战士库尔之后全身而退！', `MaleText_loc5`='教訓一下那些教徒們，$n。招惹十字軍庫爾的人只會吃不完兜著走!', `MaleText_loc7`='Enseña una lección a esos cultores, $n. ¡Nadie se mete con el cruzado Kul y sale impune!' WHERE `ID`=35793;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘했다, 호드여!', `MaleText_loc4`='干得好，胜利属于部落！', `MaleText_loc5`='幹得好，部落!', `MaleText_loc7`='¡Bien hecho, Horda!' WHERE `ID`=35794;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 싸웠다.', `MaleText_loc4`='你打得非常英勇。', `MaleText_loc5`='精采的戰鬥。', `MaleText_loc7`='Han luchado bien.' WHERE `ID`=35795;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='축하하네, 용사들이여. 예정된 시험이든 뜻밖의 시험이든, 그대들은 모두 이겨냈군.', `MaleText_loc4`='勇士们，祝贺你们！经历过一系列计划之中和意料之外的试炼，你们终于取得了胜利。', `MaleText_loc5`='恭喜你，勇士們。儘管試煉隱藏著許多不安的變數，但你們仍然通過了考驗。', `MaleText_loc7`='Mis felicitaciones, campeones. Han triunfado a los largo de estas pruebas, tanto planeadas como inesperadas.' WHERE `ID`=35796;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이젠 가서 쉬게나. 그대들은 그럴 자격이 있네.', `MaleText_loc4`='现在去休息一下吧，辛苦了。', `MaleText_loc5`='下去休息吧;這是你應得的。', `MaleText_loc7`='Vayan y descansen; se lo han ganado.' WHERE `ID`=35797;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='|cFFFFFFFF빛|r의 손길 효과를 얻었습니다. |cFFFFFFFF빛|r의 정수로 바꾸십시오!', `FemaleText_loc4`='你获得了|cFFFFFFFF光明之触。|r转换为|cFFFFFFFF光明精粹|r！', `FemaleText_loc5`='你受到|cFFFFFFFF光明|r之觸的影響。切換成|cFFFFFFFF光明|r精華!', `FemaleText_loc7`='Tienes Toque de |cFFFFFFFFluz.|r ¡Cambia a Esencia |cFFFFFFFFde la luz|r!' WHERE `ID`=35798;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스와 호드의 투사여! 은빛십자군의 깃발 아래 모인 그대들을 환영한다.', `MaleText_loc4`='参加联盟和部落之间的战斗吧！欢迎你加入到银色十字军的麾下。', `MaleText_loc5`='聯盟與部落的戰士們!歡迎你們加入銀白十字軍的行列。', `MaleText_loc7`='¡Combatientes de la Alianza y la Horda! Son bienvenidos bajo el estandarte de la Cruzada Argenta.' WHERE `ID`=35799;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='남쪽에 우리의 목표가 있다. 우리는 그가 거하는 곳, 얼음왕관 성채로 진격해 스컬지의 심장을 도려낼 것이다.', `MaleText_loc4`='我们的目标就在南方。我们将向那座要塞进军，直捣天灾军团的心脏。', `MaleText_loc5`='我們的目標就在南方。我們將會攻陷冰冠城塞，並且將天譴軍團連根拔起。', `MaleText_loc7`='Nuestra meta se halla al sur. Marcharemos hacia la Ciudadela y acabaremos con el corazón de la Plaga en su propio hogar.' WHERE `ID`=35800;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 일을 가벼이 여겨서는 안 된다.', `MaleText_loc4`='这可不是一个轻松的任务。', `MaleText_loc5`='但這是一項艱難的任務。', `MaleText_loc7`='Pero esta tarea no debe tomarse a la ligera.' WHERE `ID`=35801;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사지 멀쩡한 이를 모두 끌고 나와 대규모 공격을 벌여 봤자, 쓸데없이 우리 용사들만 죽어나갈 뿐이다. 쓰러진 이는 적으로 되살아날 것이다. 아제로스는 언데드의 위협 앞에 속수무책이 될 것이다.', `MaleText_loc4`='一场动员所有人参加的大规模攻击只会导致本可以避免的惨重伤亡。而每一名倒下的士兵都会变成敌人再爬起来。到那时候，艾泽拉斯将再没有力量对抗亡灵怪物的威胁。', `MaleText_loc5`='若我們派出所有可用的人員展開大戰，只會造成無謂的傷亡。每倒下一名士兵，等於平白增添敵方的亡靈數量。最後艾澤拉斯只會落得無力抵禦亡靈的威脅。', `MaleText_loc7`='Un ataque masivo con todos los hombres capaces acabaría en una matanza innecesaria. Cada soldado perdido se alzaría de parte del enemigo. Azeroth quedaría indefenso contra la amenaza no-muerta.' WHERE `ID`=35802;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성공을 위해 우리에게 필요한 건 정예로만 구성된 소규모 타격 부대이다. 바로 그 때문에, 우리는 은빛십자군 마상시합을 열었다.', `MaleText_loc4`='实际上，我们需要组建一支小规模的精英力量，对敌人造成致命打击。这才是我们的取胜之道。所以我们举办了银色锦标赛。', `MaleText_loc5`='為此，我們應當派出一支精銳，集中我們的攻勢，務求一擊制勝。為了這個目的，我們舉辦了銀白聯賽。', `MaleText_loc7`='Sin embargo, necesitamos una pequeña fuerza de ataque concentrada para que el asalto tenga éxito. Por ese motivo, hemos creado el Torneo Argenta.' WHERE `ID`=35803;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='|cFF9932CD어둠|r의 손길 효과를 얻었습니다. |cFF9932CD어둠|r의 정수로 바꾸십시오!', `FemaleText_loc4`='你获得了|cFF9932CD黑暗之触。|r转换为|cFF9932CD黑暗精粹|r！', `FemaleText_loc5`='你受到|cFF9932CD黑暗|r之觸的影響。切換成|cFF9932CD黑暗|r精華!', `FemaleText_loc7`='Tienes Toque de la |cFF9932CDoscuridad.|r ¡Cambia a Esencia |cFF9932CDde la oscuridad|r!' WHERE `ID`=35804;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 벽 안에서 그대들은 시험을 받으리라. 그대들의 전투 실력이 노스렌드의 가장 무시무시한 적을 상대하기에 부족함이 없는지, 모든 지도자가 주의 깊게 지켜볼 것이다.', `MaleText_loc4`='你将在这里接受测试。你必须以自身的战斗实力来对抗诺森德最凶暴危险的力量。而你的领袖们将亲眼见证你的战斗。', `MaleText_loc5`='在場中，你們將會接受考驗。在你們領導人的注目之下，你們的戰鬥技巧將用來對抗北裂境最兇猛，也最危險的對手。', `MaleText_loc7`='Entre estas paredes, se les pondrá a prueba. Tu habilidad en el combate se enfrentará a los peligros más violentos de Rasganorte bajo la atenta mirada de tus líderes.' WHERE `ID`=35805;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대들의 힘, 기술, 무용이 모두 꼼꼼히 평가될 것이다. 이 경기는, 아제로스 최고의 용사들을 가려내는 자리이다.', `MaleText_loc4`='你们的勇敢、力量和机智都将受到万众瞩目。这些竞赛将决定谁才是艾泽拉斯最强的战士。', `MaleText_loc5`='你們的勇氣，力量，以及戰技將會展現在眾人的眼前。艾澤拉斯的菁英將會在接連的賽事中脫穎而出。', `MaleText_loc7`='Tu destreza, tu poder y tu astucia serán vigiladas de cerca. Estos juegos mostrarán que es lo mejor que puede ofrecer Azeroth.' WHERE `ID`=35806;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='승리자는 성채를 공격할 때 그에 걸맞은 자리를 얻으리라. 우리는 악에 굳건히 맞설 것이고, 아서스는 쓰러지리라!', `MaleText_loc4`='胜利者将成为进攻冰冠堡垒大军的先锋。我们将并肩对抗邪恶。阿尔萨斯必将灭亡！', `MaleText_loc5`='獲勝者將獲得參與突襲冰冠城塞的殊榮。我們將團結一致泯除惡源，迎接阿薩斯的敗亡!', `MaleText_loc7`='Los vencedores podrán ocupar el lugar que les pertenece por derecho propio en el asalto a la ciudadela. ¡Nos mantendremos unidos ante la faz del mal y Arthas CAERÁ!' WHERE `ID`=35807;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 되찾은 보물들을 자세히 살펴보더니 무언가에 시선을 고정합니다.', `FemaleText_loc4`='%s仔细察看着这些被找到的财宝，直到有什么东西吸引了她的目光。', `FemaleText_loc5`='%s正在過濾得到的寶藏，直到什麼東西吸引了她的注意。', `FemaleText_loc7`='%s registra los tesoros recuperados hasta que algo le llama la atención.' WHERE `ID`=35808;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 이 반지가 좋겠군요...', `FemaleText_loc4`='啊！这枚戒指就很不错……', `FemaleText_loc5`='啊!這個戒指我喜歡...', `FemaleText_loc7`='¡Ah! Este anillo servirá...' WHERE `ID`=35809;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바리안 린 폐하와 여군주 제이나 프라우드무어 님께서 마상시합 광장에 납셨습니다! 길을 비키십시오!', `MaleText_loc4`='瓦里安·乌瑞恩国王殿下和吉安娜·普罗德摩尔女士已经茹临比武场！让路！', `MaleText_loc5`='瓦里安·烏瑞恩國王陛下，以及珍娜·普勞德摩爾女士已經步入聯賽場地了!將走道淨空!', `MaleText_loc7`='Su Majestad, el rey Varian Wrynn y Lady Jaina Valiente han llegado a los Campos del Torneo. ¡Acérquense!' WHERE `ID`=35810;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드의 대족장이신 스랄 님과 대군주 가로쉬 헬스크림 님께서 마상시합 광장에 도착하셨습니다! 입구에 이르는 길을 비우십시오!', `MaleText_loc4`='部落的酋长萨尔和督军加尔鲁什·地狱咆哮已经来到比武场！让路！', `MaleText_loc5`='部落的大酋長，索爾以及霸主卡爾洛斯·地獄吼已經來到聯賽場地了!快淨空入口的走道!', `MaleText_loc7`='El Jefe de Guerra de la Horda, Thrall, y el Señor supremo Garrosh Grito Infernal han llegado a los Campos del Torneo. ¡Abran el camino hasta la entrada!' WHERE `ID`=35811;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대영주 티리온 폴드링께서 마상시합 광장에 모인 청중 앞에서 연설하실 겁니다! 대영주님을 위해 연단까지 길을 내십시오!', `MaleText_loc4`='大领主提里奥·弗丁已经来到台上，要向聚集在比武场上的人们讲话！来听他的演讲吧！', `MaleText_loc5`='大領主提里奧·弗丁已走向台上，準備對盛情參與聯賽場地的眾人致詞!快淨空通往舞台的走道讓大領主通過!', `MaleText_loc7`='El alto señor Tirion Vadín se acerca al escenario para dirigirse a quienes se encuentran reunidos en los Campos del Torneo. ¡Acérquense a la zona de escenario para escucharlo!' WHERE `ID`=35812;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그냥 재워 두십시오. 저희가 준비되기 전에 깨울 필요는 없으니까요.', `MaleText_loc4`='让他睡吧。在那个时刻到来之前，我们不需要唤醒他。', `MaleText_loc5`='讓他繼續睡吧，沒錯。不需要提早吵醒他。', `MaleText_loc7`='Eso es, mantenedlo dormido. No hay necesidad de despertarlo antes de tiempo.', `FemaleText_loc1`='그냥 재워 두세요. 저희가 준비되기 전에 깨울 필요는 없으니까요.', `FemaleText_loc4`='让他睡吧。在那个时刻到来之前，我们不需要唤醒他。', `FemaleText_loc5`='讓他繼續睡吧，沒錯。不需要提早吵醒他。', `FemaleText_loc7`='Eso es, mantenedlo dormido. No hay necesidad de despertarlo antes de tiempo.' WHERE `ID`=35813;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼날 같은 바람이 이 봉우리를 가로지르는 가운데, 살아 있는 것들은 대부분 이 얼음왕관 구석을 떠난 지 오랩니다. 하지만, 어떤 것이든 계속해서 달래고 어르면 돌아오는 법입니다. 그게 바로 제가 이 광장을 걷는 이유이지요. 언젠가는 이 나무들이 우리 머리 위로 우뚝 솟을 겁니다.', `MaleText_loc4`='寒风猛烈地吹过这里的峭壁，在冰冠冰川的这个角落，绝大多数生命都不会做片刻停留。不过，只需要一点耐心，生命又都会回来。所以我现在走在这片大地上。总有一天，这些树木会高过我们所有人。', `MaleText_loc5`='峭壁之上，強風依舊呼嘯而過，多年來寒冰皇冠仍是生靈避之唯恐不及之處。然而只要不輕言放棄，我們仍可奪回此地，這也是我來到這裡的原因。終有一天，此地將會百樹林立，守護著我們。', `MaleText_loc7`='El viento corta esta cima despiadadamente y la vida ha huido de este rincón de Corona de Hielo. Sin embargo, solo hará falta un poco de coacción para que regrese y por eso camino por estas tierras. Algún día, estos árboles se alzarán sobre nosotros.' WHERE `ID`=35814;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 윌프레드 피즐뱅은 이 별난 마상시합에 초청을 받고 온 몸이랍니다. 소환 마법에 대한 제 폭넓은 지식 덕분이죠. 당연한 거 아니겠어요?', `MaleText_loc4`='我，威尔弗雷德·菲兹班，被邀请到这座怪异的竞技场来，在这里施展我无穷的智慧和伟大的召唤技艺。当然，在这方面，这个世界上不会有比我更好的人选了。', `MaleText_loc5`='我，威爾弗雷德·菲斯巴恩，受邀來到這場小小的聯賽，展現我在召喚技藝上的過人天份。誰還能找到更適合的人選呢?', `MaleText_loc7`='Yo, Wilfred Chispobang, he sido invitado a este pintoresco torneo para usar mi extenso conocimiento de las artes invocatorias. ¿Quién podría hacerlo mejor?' WHERE `ID`=35815;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곧 온 세상이 윌프레드란 이름을 알 거예요!', `MaleText_loc4`='很快，全世界都将知道威尔弗雷德的名字！', `MaleText_loc5`='不久之後，威爾弗雷德這名字將為世人所周知。', `MaleText_loc7`='¡Pronto todo el mundo conocerá el nombre de Wilfred!' WHERE `ID`=35816;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피즐뱅은 곧 널리 알려진 말이 될 거예요! 엄마들은 아기한테 일찍 자라고 겁을 줄 때 그 이름을 들먹거리겠죠! "그만 침대로 가야지. 안 그러면 피즐뱅이 무서운 악마를 소환해서 한입에 삼켜버린단다!"', `MaleText_loc4`='用不了多久，菲兹班就会成为一个家喻户晓的名字。母亲会用它来吓唬不乖乖睡觉的孩子。“小心了，菲兹班会召唤一头强大的恶魔来吃掉你！”', `MaleText_loc5`='不久之後，菲斯巴恩將會成為家喻戶曉的名號，再調皮的小孩聽到之後，都會乖乖的上床睡覺!「乖乖聽話，要不然菲斯巴恩將會召喚窮兇惡極的惡魔把你吃掉!」', `MaleText_loc7`='¡No pasará mucho tiempo antes de que Chispobang sea una palabra muy conocida, que se use para asustar a los niños y que se vayan a la cama! "¡Cuidado o Chispobang invocará a un poderoso demonio para que te coma!"' WHERE `ID`=35817;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론 저는 참가자를 위해 악마를 소환하는 역할을 해요. 저는 윌프레드 피즐뱅, 소환의 대가랍니다! 악마들은 제 굳건한 의지에 속박되는 걸 상상만 해도 벌벌 떤다고요!', `MaleText_loc4`='为这些竞技选手们召唤恶魔敌人的工作当然应该由我来完成。我是威尔弗雷德·菲兹班，召唤大师！在我钢铁般意志的控制下，即使是恶魔也会瑟瑟发抖！', `MaleText_loc5`='為挑戰者召喚與其匹配的惡魔，當然非我莫屬。我可是鼎鼎大名的召喚大師，威爾弗雷德·菲斯巴恩!在我的號令之下，惡魔無不叩首拜服!', `MaleText_loc7`='Por supuesto me eligieron a mí para invocar a un demonio para los competidores. ¡Soy Wilfred Chispobang, maestro invocador! ¡Los demonios tiemblan solo de pensar en estar sometidos a mi voluntad!' WHERE `ID`=35818;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='멍청한 것들! 주인님이 눈먼 줄 알았더냐? 우리가 네놈들의 침입을 모를 줄 알았더냐? 발키르 자매가 오면, 아무도 그 분노에서 도망칠 수 없으리라!', `FemaleText_loc4`='蠢货！你以为我们的主人瞎了吗？你以为我们不知道你的闯入吗？我们的长姊们就要来了，你绝对无法逃脱她们的怒火！', `FemaleText_loc5`='蠢貨!你以為主人瞎了嗎?你以為這種侵略的行為我們毫無所覺嗎?一旦我們的遠古姐妹現身，你們都將逃不過她們的摧殘!', `FemaleText_loc7`='¡Insensatos! ¿Creían que nuestro maestro es ciego? ¿Creían que no sabíamos nada de esta intrusión? Nuestras hermanas mayores vienen y no podrán escapar a su ira.' WHERE `ID`=35819;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='발키르 자매가 붙잡혔다! 후퇴하라!', `FemaleText_loc4`='我们的姐妹被敌人捉住了！后撤！', `FemaleText_loc5`='我們的姊妹被抓了!撤退!', `FemaleText_loc7`='¡Han capturado a nuestras hermanas! ¡Retirada!' WHERE `ID`=35820;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='남동쪽에 저게 뭐지?', `MaleText_loc4`='东南方那个东西是什么？', `MaleText_loc5`='那是什麼?就在東南邊!', `MaleText_loc7`='¿Qué es eso al sudeste?', `FemaleText_loc1`='남동쪽에 저게 뭐죠?', `FemaleText_loc4`='东南方那个东西是什么？', `FemaleText_loc5`='那是什麼?就在東南邊!', `FemaleText_loc7`='¿Qué es eso al sudeste?' WHERE `ID`=35821;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발키르다! 몸을 피해라!', `MaleText_loc4`='是瓦格里！注意掩蔽！', `MaleText_loc5`='是華爾琪!快找掩護!', `MaleText_loc7`='¡Val''kyr! ¡A cubierto!', `FemaleText_loc1`='발키르잖아! 몸을 피해라!', `FemaleText_loc4`='是瓦格里！注意掩蔽！', `FemaleText_loc5`='是華爾琪!快找掩護!', `FemaleText_loc7`='¡Val''kyr! ¡A cubierto!' WHERE `ID`=35822;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죄 없는 이들을 보호하라!', `MaleText_loc4`='保护无辜者！', `MaleText_loc5`='保護婦孺!', `MaleText_loc7`='¡Proteged a los inocentes!', `FemaleText_loc1`='죄 없는 이들을 보호하라!', `FemaleText_loc4`='保护无辜者！', `FemaleText_loc5`='保護婦孺!', `FemaleText_loc7`='¡Proteged a los inocentes!' WHERE `ID`=35823;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기! 남쪽에 서리고룡이다!', `MaleText_loc4`='小心！冰霜巨龙从南边过来了！', `MaleText_loc5`='快看!冰霜巨龍從南邊來襲!', `MaleText_loc7`='¡Mirad! ¡Vermis de escarcha al sur!', `FemaleText_loc1`='저기! 남쪽에 서리고룡이다!', `FemaleText_loc4`='小心！冰霜巨龙从南边过来了！', `FemaleText_loc5`='快看!冰霜巨龍從南邊來襲!', `FemaleText_loc7`='¡Mirad! ¡Vermis de escarcha al sur!' WHERE `ID`=35824;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경계를 늦추지 마라!', `MaleText_loc4`='保持警惕！', `MaleText_loc5`='提高戒備!', `MaleText_loc7`='¡En guardia!', `FemaleText_loc1`='경계를 늦추지 마라!', `FemaleText_loc4`='保持警惕！', `FemaleText_loc5`='提高戒備!', `FemaleText_loc7`='¡En guardia!' WHERE `ID`=35825;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공격!', `MaleText_loc4`='进攻！', `MaleText_loc5`='攻擊!', `MaleText_loc7`='¡Atacad!', `FemaleText_loc1`='공격!', `FemaleText_loc4`='进攻！', `FemaleText_loc5`='攻擊!', `FemaleText_loc7`='¡Atacad!' WHERE `ID`=35826;
