UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발키르의 공격입니다! 모두 피하십시오!', `MaleText_loc4`='瓦格里来进攻了！注意掩蔽！', `MaleText_loc5`='華爾琪展開攻擊了!快找掩護!', `MaleText_loc7`='¡Las Val''kyr están atacando! ¡A cubierto!' WHERE `ID`=35828;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='땅을 조심하십시오! 서리고룡의 공격입니다!', `MaleText_loc4`='不要在地面滞留！冰霜巨龙发动攻击了！', `MaleText_loc5`='堅守聯賽場地!冰霜巨龍展開攻擊了!', `MaleText_loc7`='¡Cuidado con el suelo! ¡Están atacando las vermis de escarcha!' WHERE `ID`=35829;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고르목 탈출한다, 쥐새끼 같은 녀석들아!', `MaleText_loc4`='你们这些小个子给我听着，戈莫克一定能获得自由！', `MaleText_loc5`='戈莫克要自由啦，鼠輩!', `MaleText_loc7`='¡Gormok será libre, renacuajos!' WHERE `ID`=35830;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 풀어줘!', `MaleText_loc4`='放开我！', `MaleText_loc5`='放開我!', `MaleText_loc7`='¡Liberadme!' WHERE `ID`=35831;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그아아아!', `MaleText_loc4`='RAAAAGH!', `MaleText_loc5`='啊啊啊!', `MaleText_loc7`='¡RAAAAGH!' WHERE `ID`=35832;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안돼! 내 하인을!', `MaleText_loc4`='不！我的仆从！', `MaleText_loc5`='不!我的僕從們!', `MaleText_loc7`='¡NO! ¡Mis sirvientes!' WHERE `ID`=35833;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='검프 언니 오빠가 저더러 상점 운영을 도와달라고 했어요! 전 꽃을 정말 좋아한답니다.$B$B<갑자기 심각한 얼굴로 눈을 가늘게 뜨고 당신을 쳐다보는 어린 아델라인>$B$B꽃 좋아하세요?', `FemaleText_loc4`='那群傻瓜竟然让我帮他们管理他们的商店！而我只喜欢花。$B$B<小艾德琳突然斜眼盯着你，表情显得异常严肃>$B$B你喜欢花吗？', `FemaleText_loc5`='加姆讓我幫他們經營這間店!我愛死鮮花了。$B$B<小艾德琳瞇起了雙眼看著你，露出一派正經的表情。>$B$B你也喜歡鮮花嗎?', `FemaleText_loc7`='¡Los Gump me están dejando que les ayude con la tienda! Me encantan las flores.$B$B<De pronto, la pequeña Adeline entorna los ojos, con aspecto muy serio.>$B$B¿Te gustan las flores?' WHERE `ID`=35834;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론이지!', `MaleText_loc4`='是的，没错！', `MaleText_loc5`='是的!', `MaleText_loc7`='¡Sí!', `FemaleText_loc1`='물론이지!', `FemaleText_loc4`='是的，没错！', `FemaleText_loc5`='是的!', `FemaleText_loc7`='¡Sí!' WHERE `ID`=35835;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='유령 따윈 무섭지 않아요!', `FemaleText_loc4`='我可不怕什么鬼魂！', `FemaleText_loc5`='我才不怕什麼鬼魂!', `FemaleText_loc7`='¡No me dan miedo los fantasmas!' WHERE `ID`=35836;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='측량사 찾으셨어요? 제가 바로 측량산데! 하하!', `FemaleText_loc4`='勘测员！我可不认识她！哈哈！', `FemaleText_loc5`='勘測員?我根本不算認識她!哈哈哈!', `FemaleText_loc7`='¿Perita? ¡No llega ni a gatita! ¡Ja, JA!' WHERE `ID`=35837;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='일을 망치면 안 돼요. 연말까진 상급 측량사로 승진하고 싶다고요!', `FemaleText_loc4`='不用在乎这个了——等到今年底，我就会成为高级勘测员了。', `FemaleText_loc5`='別把這弄壞了─我的目標是在年末升為資深階級。', `FemaleText_loc7`='No lo estropees, espero un ascenso antes de que acabe el año.' WHERE `ID`=35838;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='해 보자고요.', `FemaleText_loc4`='让我们动手吧。', `FemaleText_loc5`='我們開始吧。', `FemaleText_loc7`='Vamos a ello.' WHERE `ID`=35839;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마그나타우르는 생긴 것처럼 멍청하진 않습니다. 순서가 올 때까지 고르목을 보살피는 건 퍽 어려운 일이지만, 꽉 묶어 놨으니 위험할 건 없습니다.', `MaleText_loc4`='猛犸人并不像看上去那样愚蠢。看管戈莫克就是一个非常困难的任务。但现在他已经被紧紧地捆住，应该不会有任何危险了。', `MaleText_loc5`='猛瑪象人沒有一般人想像中的蠢。在戈莫克上場前禁錮牠是件困難的工作，但我們把他牢牢地綁住了，不會有安全上的顧忌。', `MaleText_loc7`='Los magnatauros no son tan estúpidos como parecen. Retener a Gormok hasta que llegue su momento no es tarea fácil, pero está tan bien atado que no hay riesgo.' WHERE `ID`=35840;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 고르목 대신에 이 생명체들을 돌보고 있습니다. 전 이런 학살에 동의하지 않습니다만, 어쨌든 고르목은 자기가 원하는 대로 싸울 수 있을 겁니다.', `MaleText_loc4`='我帮助戈莫克照顾这些怪物。我并不完全赞同这种屠杀。但至少，他有机会进行战斗了。', `MaleText_loc5`='由於戈莫克只會濫殺無辜，因此我把他囚禁起來。我不十分贊同這種屠殺的行為，但至少他仍有一拚的機會。', `MaleText_loc7`='Yo me encargo de estas criaturas de Gormok ya que él no puede. No estoy totalmente de acuerdo con esta matanza, pero al menos tendrá la oportunidad de luchar.' WHERE `ID`=35841;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='설인은 사납고 교활한 생물이라네. 그리고 이놈은 설인 중에서도 가장 강한 놈이지. 우리는 음식에 약초를 섞어서 녀석이 계속 잠을 자게 한다네.$b$b그렇다고 이놈이 투기장에서 둔하리라 생각하지는 말게.', `MaleText_loc4`='雪人是一种凶猛而狡诈的怪物，而这头雪人又是雪人之中最强壮的一头。我们在他的食物里掺了药，让他睡着了。$b$b但你可千万别以为他在斗兽场里还会这样昏昏沉沉地酣睡。', `MaleText_loc5`='雪人是兇猛，狡詐的生物，而這一隻又是箇中的翹楚。我們在他的飲食中加入了安眠的草藥。$b$b不過別妄想他在競技場中也會昏昏欲睡。', `MaleText_loc7`='El yeti es una criatura feroz y astuta, y este es uno de los más fuertes de su especie. Lo mantenemos dormido echándole hierbas en la comida.$B$BPero no creas que estará en letargo cuando salte a la arena.' WHERE `ID`=35842;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 한동안 이 벌레들을 돌봤지. 이 단체에서 행사를 시작할 때까지 벌레들이 다 컸으면 좋겠군. 그대들은 요르문가르 하나가 아니라 둘과 맞서야 하니까 말일세.', `MaleText_loc4`='我们照顾这些虫子已经有一段时间了。我希望它们能在斗兽活动中充分发挥作用。要知道，你要打败的不是一条冰虫，而是两条。', `MaleText_loc5`='我們一直在照料這些大蟲。我希望他們來得及參與競技場的盛會。畢竟，你得面對的不只是一隻，而是兩隻蟄猛巨蟲。', `MaleText_loc7`='Hemos estado encargándonos de estos gusanos desde hace algún tiempo. Espero que estén en forma a tiempo para el evento de la arena de esta organización. Después de todo debes enfrentarte a dos jormungar, no uno.' WHERE `ID`=35843;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희는 사회의 그늘에서 움직이는 존재입니다만, 여기 최전선에서는 누구나 저희의 힘을 존중할 수밖에 없죠.', `MaleText_loc4`='我们也许只能在上流社会的阴影中做着默默无闻的事情。只有离开这里，在战争的最前线，我们的力量才能得到应有的尊重。', `MaleText_loc5`='我們的方式可能不為世俗所認可，但至少在戰鬥中，我們的能力仍會受到相當的敬重。', `MaleText_loc7`='Puede que operemos en las sombras de la sociedad educada, pero allá afuera, en el frente de batalla, nuestros poderes al fin se respetan debidamente.', `FemaleText_loc1`='저희는 사회의 그늘에서 움직이는 존재입니다만, 여기 최전선에서는 누구나 저희의 힘을 존중할 수밖에 없죠.', `FemaleText_loc4`='我们也许只能在上流社会的阴影中做着默默无闻的事情。只有离开这里，在战争的最前线，我们的力量才能得到应有的尊重。', `FemaleText_loc5`='我們的方式可能不為世俗所認可，但至少在戰鬥中，我們的能力仍會受到相當的敬重。', `FemaleText_loc7`='Puede que operemos en las sombras de la sociedad educada, pero allá afuera, en el frente de batalla, nuestros poderes al fin se respetan debidamente.' WHERE `ID`=35844;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 당신! 네, 당신 말예요!$b$b잠시 절 바라보며 이 순간을 음미하시죠. 곧 온 세상이 윌프레드 피즐뱅의 이름과 무시무시한 표정을 뇌리에 새기고 두려움에 떨 테니까요! 일단 웅장한 소환 의식을 끝내면, 아무도 제 능력을 의심하지 못할 걸요!', `MaleText_loc4`='你！好啊，就是你！$b$b好好看着我。对你来说，遇到我是你不可多得的幸运。过不了多久，全世界的人都会知道并畏惧威尔弗雷德·菲兹班的名字和我威严的面容！一旦我宏大的召唤最终完成，将没有任何人敢怀疑我的能力！', `MaleText_loc5`='你!是的，就是你!$b$b睜大雙眼看好，並且珍惜這千載難逢的機會，因為不久之後，全世界都將認識並且敬畏那威震四方的威爾弗雷德·菲斯巴恩!一旦我的華麗召喚大功告成之後，再也沒有人敢質疑我的能力啦!', `MaleText_loc7`='¡Tú! ¡Sí, tú!$B$BMírame y aprecia este momento de encuentro, pues pronto el mundo conocerá y temerá el nombre y el severo rostro de Wilfred Chispobang. ¡En cuanto mi magnífica invocación se complete, nadie dudará de mi habilidad!' WHERE `ID`=35845;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전 일에 집중해야 하니 뒤를 엄호해 주세요...', `FemaleText_loc4`='掩护我，我需要把精神集中在这上面……', `FemaleText_loc5`='保護好我，我必須要很專心...', `FemaleText_loc7`='Guárdame las espaldas, tengo que concentrarme...' WHERE `ID`=35846;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='측량표가 있군요!', `FemaleText_loc4`='这里有勘测仪！', `FemaleText_loc5`='勘測標記在那!', `FemaleText_loc7`='¡Ahí está el marcador de peritaje!' WHERE `ID`=35847;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='시작할게요. 작업하는 동안 유령이 접근하지 못하게 해주세요.', `FemaleText_loc4`='开始吧——在我工作的时候，别让那些东西碰我！', `FemaleText_loc5`='這樣就對了，我工作時讓那些東西離我遠點。', `FemaleText_loc7`='Allá vamos. ¡Aléjalos de mí mientras trabajo!' WHERE `ID`=35848;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='됐어요!', `FemaleText_loc4`='成功了！', `FemaleText_loc5`='成功了!', `FemaleText_loc7`='¡Lo tengo!' WHERE `ID`=35849;
