UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성공입니다! 개인 재산을 찾았습니다!$B$B|Tinterface\\Icons\\INV_Misc_coin_02.blp:64|t', `MaleText_loc4`='成功了！你得到了你的私人财产！$B$B|TInterface\\Icons\\INV_Misc_coin_02.blp:64|t', `MaleText_loc5`='成功!你擁有私人財富了!$B$B|TInterface\\Icons\\INV_Misc_coin_02.blp:64|t', `MaleText_loc7`='¡Éxito! ¡Tienes tus riquezas personales!$B$B|TInterfaceIconsINV_Misc_coin_02.blp:64|t' WHERE `ID`=35852;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전원, 자리를 지켜라!', `MaleText_loc4`='战士们，坚守阵地！', `MaleText_loc5`='守住陣地，士兵們!', `MaleText_loc7`='¡Muchachos, mantengan la posición!', `FemaleText_loc1`='전원, 자리를 지켜라!', `FemaleText_loc4`='战士们，坚守阵地！', `FemaleText_loc5`='守住陣地，士兵們!', `FemaleText_loc7`='¡Muchachos, mantengan la posición!' WHERE `ID`=35853;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저, 저건 대체 뭐지?!', `MaleText_loc4`='那……那是什么东西！！', `MaleText_loc5`='那...那是什麼!!', `MaleText_loc7`='¿Qué... qué es esa cosa?', `FemaleText_loc1`='저, 저건 대체 뭐지?!', `FemaleText_loc4`='那……那是什么东西！！', `FemaleText_loc5`='那...那是什麼!!', `FemaleText_loc7`='¿Qué... qué es esa cosa?' WHERE `ID`=35854;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저, 저 안에 누군가 있는 것 같아!', `MaleText_loc4`='我……我想，那东西里面应该是有人！', `MaleText_loc5`='我...我覺得有人在那東西裡面!', `MaleText_loc7`='¡C-creo que hay alguien DENTRO de esa cosa!', `FemaleText_loc1`='저, 저 안에 누군가 있는 것 같아!', `FemaleText_loc4`='我……我想，那东西里面应该是有人！', `FemaleText_loc5`='我...我覺得有人在那東西裡面!', `FemaleText_loc7`='¡C-creo que hay alguien DENTRO de esa cosa!' WHERE `ID`=35855;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 폭풍에서 멀리 떨어져라! 안 그러면 산 채로 타버릴 거다!', `MaleText_loc4`='躲开！那东西会烧死你！', `MaleText_loc5`='離它遠點!你會活活被燒死的!', `MaleText_loc7`='¡Alejaos de él! ¡Os quemará vivos!', `FemaleText_loc1`='저 폭풍에서 멀리 떨어져라! 안 그러면 산 채로 타버릴 거다!', `FemaleText_loc4`='躲开！那东西会烧死你！', `FemaleText_loc5`='離它遠點!你會活活被燒死的!', `FemaleText_loc7`='¡Alejaos de él! ¡Os quemará vivos!' WHERE `ID`=35856;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='목숨을 걸고 나이젤의 야영지를 보호하라!', `MaleText_loc4`='誓死守住尼耶尔前哨站！', `MaleText_loc5`='死也要保護好尼耶爾前哨站!', `MaleText_loc7`='¡Defiendan Punta de Nijel con sus vidas!', `FemaleText_loc1`='목숨을 걸고 나이젤의 야영지를 보호하라!', `FemaleText_loc4`='誓死守住尼耶尔前哨站！', `FemaleText_loc5`='死也要保護好尼耶爾前哨站!', `FemaleText_loc7`='¡Defiendan Punta de Nijel con sus vidas!' WHERE `ID`=35857;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳을... 떠나라...', `MaleText_loc4`='离开……这个……地方……', `MaleText_loc5`='離開...這個...地方...', `MaleText_loc7`='Abandonen... este... lugar...' WHERE `ID`=35858;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 땅은... 네 것이 아니다...', `MaleText_loc4`='这里……不是……你们的……', `MaleText_loc5`='這片土地...不是...你們的...', `MaleText_loc7`='Estas tierras... no son... suyas…' WHERE `ID`=35859;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌아가라...', `MaleText_loc4`='回……去……', `MaleText_loc5`='回...去...', `MaleText_loc7`='Den... la vuelta...' WHERE `ID`=35860;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='첫 번째 도전에 임하려면 은빛십자군 전투마에 올라야 합니다. 이 원형경기장의 벽을 따라 서 있는 은빛십자군 전투마들이 보이실 겁니다.$b$b자, 전투마에 오르세요. 그리고 제게 말을 거시면 도전을 진행할 수 있습니다.', `MaleText_loc4`='第一场挑战需要你骑上一匹银色战马。', `MaleText_loc5`='第一場挑戰賽需要你騎上銀白戰馬。你可以在大競技場的牆邊找到那些坐騎。$b$b請騎上那些戰馬，然後請告訴我，讓我們可以繼續下去。', `MaleText_loc7`='El primer reto requiere que estés montado sobre un caballo de guerra Argenta. Encontrarás estas monturas a lo largo de los muros del Coliseo.$B$BMonta el caballo de guerra, habla conmigo y entonces podremos continuar.' WHERE `ID`=35861;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='바로 그렇게 하는 거예요!', `FemaleText_loc4`='就是这样！', `FemaleText_loc5`='這就對了!', `FemaleText_loc7`='¡Así se hace!' WHERE `ID`=35862;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런 속도로 일하다간 승진은 꿈도 못 꾸겠네요...', `FemaleText_loc4`='以这样可怜的效率……我永远也没办法成为高级勘测员……', `FemaleText_loc5`='再這樣下去我永遠都無法到資深階級。', `FemaleText_loc7`='A este paso no me ascenderán nunca...' WHERE `ID`=35863;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='위험수당을 청구해야겠어요.', `FemaleText_loc4`='我要申请危险补助。', `FemaleText_loc5`='我要以這申報危險津貼。', `FemaleText_loc7`='Voy a pedir plus de peligrosidad.' WHERE `ID`=35864;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그리고 죽은 척해야죠!', `FemaleText_loc4`='……还是别活过来！', `FemaleText_loc5`='...去死吧!', `FemaleText_loc7`='¡...y permanece muerto!' WHERE `ID`=35865;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='광산을 제대로 감독하지 못했어!$B$B제발... 날 해고하지는 말아줘!', `MaleText_loc4`='我……我失去了对这些矿藏的控制！$B$B求求你，$g先生:女士;，不要解雇我！', `MaleText_loc5`='我...我的礦場失去控制了!$g先生:女士;，不要開除我!', `MaleText_loc7`='¡He... he perdido el control de las minas!$B$BPor favor, $gseñor:señora; ¡no me despidas!' WHERE `ID`=35866;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 엔진 뚜껑을 열어젖히고 기계 내부를 들쑤십니다...', `MaleText_loc4`='$n打开引擎盖，摆弄着里面的机械部件……', `MaleText_loc5`='$n打開了引擎的開口後搗亂了機械的內部結構。', `MaleText_loc7`='$n abre la escotilla del motor y trastea con las tripas de la máquina...' WHERE `ID`=35867;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 마구 흔들리며 배기관에서 녹색 녹괴물이 흘러나옵니다!', `MaleText_loc4`='%s不停地颤抖，一团绿色的软泥从排气管里涌了出来！', `MaleText_loc5`='%s一邊震動著一邊從排氣管中流出綠色的沼澤軟泥怪!', `MaleText_loc7`='¡%s se estremece cuando un montón de lodo verde sale disparado por los tubos de escape!' WHERE `ID`=35868;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겨울손아귀에 참여하고자 대기열에 들어가고 싶습니다.', `MaleText_loc4`='排队等待冬拥湖战场。', `MaleText_loc5`='加入冬握湖佇列。', `MaleText_loc7`='Hacer cola para Conquista del Invierno.', `FemaleText_loc1`='겨울손아귀에 참여하고자 대기열에 들어가고 싶습니다.', `FemaleText_loc4`='排队等待冬拥湖战场。', `FemaleText_loc5`='加入冬握湖佇列。', `FemaleText_loc7`='Hacer cola para Conquista del Invierno.' WHERE `ID`=35869;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='칼리사의 눈을 통해 세상을 봅니다...', `FemaleText_loc4`='你通过卡莱莎的眼睛看到这个世界……', `FemaleText_loc5`='你透過凱麗莎的雙眼看到了世界...', `FemaleText_loc7`='Tú ves el mundo a través de los ojos de Kalytha...' WHERE `ID`=35870;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 세계의 용사들이 도전자들과 맞서기 위해 북동쪽 얼음왕관에 있는 은빛십자군 마상시합 광장에 모여들고 있습니다.', `MaleText_loc4`='世界上最强大国家的勇士们都聚集在冰冠冰川东北部的银色比武场，准备在这里迎接各种艰难而致命的挑战。', `MaleText_loc5`='全世界各大強權的勇士們已集結在寒冰皇冠東北方的銀白聯賽場地，共同面對挑戰。', `MaleText_loc7`='Los campeones de las grandes naciones del mundo se han reunido en los Campos del Torneo Argenta al noreste de Corona de Hielo para enfrentarse a todos los contendientes.' WHERE `ID`=35871;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까. 기묘한 운명의 엇갈림으로 켈투자드의 무서운 누더기골렘인 패치워크의 잔해를 얻었습니다. 우리 연구원들이 당신 영웅 지망생 무리의 기질을 시험하고자 여러 가지 방법으로 잔해를 재조립하고 있으니 몸이 근질근질할 겁니다.

우린 당신의 공격 전담 능력을 측정하는 상대로 튼튼한 패치워크를 조립할 수 있습니다. 감히 패치워크 앞에 설 방어 전담에게 빠르고 강력한 치명타를 날릴 상대로 난폭한 패치워크를 조립할 수도 있지요. 아니면 전체 공격력을 시험해볼 만한 만능 패치워크를 조립할 수도 있고요.

어떤 패치워크를 원하시나요?', `MaleText_loc4`='你好，因为命运的多变无常，我们获得了克尔苏加德的遗物——恐怖的憎恶，帕奇维克的碎片。我们的研究人员能够用不同的方式将这些碎片重新拼合起来。如果你愿意，你们这些想要成为英雄的人可以用它来测试自己到底有多少勇气。

我们能制造一个牢固的帕奇维克测试你们造成伤害的力量；或者是制造一个凶猛的帕奇维克，看看谁能在他的强力攻击前屹立不倒。

那么，你想要什么样的战斗？', `MaleText_loc5`='嗨。在偶然的機會下，我們取得了科爾蘇加德手下，令人聞風喪膽的憎惡體縫補者的部份屍塊。我們的研究員已經懂得如何將這些屍塊以各種方式重新組合起來，如果你勇於接受挑戰的話，我們可以用來測試潛藏於你體內的英雄特質。

我們可以將其組合成一具結實的縫補者，用以測試你的傷害輸出，或者組合成一具殘暴的縫補者，對眼前所見的所有生物發動快捷無倫的強力攻擊。還是一具完整的縫補者，測試你整體的戰鬥能力。

你想接受哪種挑戰呢?', `MaleText_loc7`='Hola. Por azares de la fortuna hemos recibido los restos de la temible abominación de Kel''Thuzad, Remendejo. Nuestros investigadores pueden volver a juntarlos de varias formas para poner a prueba la entereza de tus aspirantes a héroe, si así lo deseas.  

Podemos construir un robusto Remendejo contra el que medir tu habilidad para infligir daño, o un Remendejo brutal que asestará rápidos y potentes golpes a cualquiera que se atreva a ponerse ante él.|n|n¿Cuál prefieres?' WHERE `ID`=35872;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 공격 전문 직업을 시험해 보고 싶습니다.', `MaleText_loc4`='我想测试我们的伤害输出。', `MaleText_loc5`='我想測試我們的傷害輸出。', `MaleText_loc7`='Quiero probar a los que infligen daño.', `FemaleText_loc1`='우리의 공격 전담 직업을 시험해 보고 싶습니다.', `FemaleText_loc4`='我想测试我们的伤害输出。', `FemaleText_loc5`='我想測試我們的傷害輸出。', `FemaleText_loc7`='Quiero probar a los que infligen daño.' WHERE `ID`=35873;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 방어 전담 직업을 시험해 보고 싶습니다.', `MaleText_loc4`='我想测试我们的坦克。', `MaleText_loc5`='我想測試我們的坦克。', `MaleText_loc7`='Quiero probar a nuestros tanques.', `FemaleText_loc1`='우리의 방어 전담 직업을 시험해 보고 싶습니다.', `FemaleText_loc4`='我想测试我们的坦克。', `FemaleText_loc5`='我想測試我們的坦克。', `FemaleText_loc7`='Quiero probar a nuestros tanques.' WHERE `ID`=35874;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 시험해 보지 않아도 됩니다.', `MaleText_loc4`='别玩了。', `MaleText_loc5`='我們玩夠了。', `MaleText_loc7`='Se acabó el juego.', `FemaleText_loc1`='더 시험해 보지 않아도 됩니다.', `FemaleText_loc4`='别玩了。', `FemaleText_loc5`='我們玩夠了。', `FemaleText_loc7`='Se acabó el juego.' WHERE `ID`=35875;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요, $n 님. 경매인으로서 제 도움이 필요하신가 본데, 안타깝게도 안 됩니다. 제 우수한 기능을 이용할 수 있을 만한 최소한의 지적 수준은 오직 기계공학의 거장만이 지니고 있으니까요. $b$b더 중요한 건, 왜 아직도 저에게 말을 거시는 거죠?', `MaleText_loc4`='你好，如果你需要我的拍卖服务，那么我只能遗憾地告诉你：不行。只有宗师级工程师才有足够的能力操纵我的超级功能。$b$b更重要的是，为什么你还在和我说话？', `MaleText_loc5`='你好啊，$n。如果你想要我當你的拍賣師，我只能遺憾地跟你說:不。只有宗師級的工程師才擁有能啟動我的特殊功能所需的最低專業智能。$b$b更重要的是，為什麼你還在跟我說話呢?', `MaleText_loc7`='Buenos días, $n. Si necesitas mis servicios como subastador, siento informarte de que no. Solo los grandes maestros ingenieros poseen la capacidad intelectual mínima para interactuar con mis funciones superiores.$B$BLo que es aún más importante, ¿por qué sigues hablándome?' WHERE `ID`=35876;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘은 경매장에 어떤 물건이 있습니까?', `MaleText_loc4`='今天拍卖行有什么东西？', `MaleText_loc5`='今天的拍賣場有什麼好貨嗎?', `MaleText_loc7`='¿Qué hay hoy en la casa de subastas?', `FemaleText_loc1`='오늘은 경매장에 어떤 물건이 있나요?', `FemaleText_loc4`='今天拍卖行有什么东西？', `FemaleText_loc5`='今天的拍賣場有什麼好貨嗎?', `FemaleText_loc7`='¿Qué hay hoy en la casa de subastas?' WHERE `ID`=35877;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 지나가게 두어서는 안 된다!', `MaleText_loc4`='我们绝不能让他们过去！', `MaleText_loc5`='我們絕不可讓他們通過!', `MaleText_loc7`='¡No debemos permitir que pasen!' WHERE `ID`=35878;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 있어? 대체 어디에서 튀어나오는 거지?!', `MaleText_loc4`='还有？他们都是从哪里来的！？', `MaleText_loc5`='更多?他們都是從哪冒出來的!?', `MaleText_loc7`='¿Más? ¿De dónde salen?' WHERE `ID`=35879;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들을 막아라!', `MaleText_loc4`='阻止他们！', `MaleText_loc5`='阻止他們!', `MaleText_loc7`='¡Deténganlos!' WHERE `ID`=35880;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적들이 몰아치고 있다!', `MaleText_loc4`='他们在冲击城墙！', `MaleText_loc5`='他們正在攻擊城牆!', `MaleText_loc7`='¡Están asaltando las murallas!' WHERE `ID`=35881;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 밀리고 있다!', `MaleText_loc4`='他们的数量远远超过了我们！', `MaleText_loc5`='我們被淹沒了!', `MaleText_loc7`='¡Nos están superando!' WHERE `ID`=35882;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='막아라. 어떻게든 막아내기만 해라. 대마법사님께 계획이 있다.', `MaleText_loc4`='挡住他们，一定要挡住他们。大法师已经有了计划。', `MaleText_loc5`='拖延他們─就拖延他們。大法師有個主意。', `MaleText_loc7`='Mantenedlos a raya... Tan solo aguantad. La archimaga tiene un plan.' WHERE `ID`=35883;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼리사, 아직 살아 있었구나! 숨을 곳을 찾아야 해. 이놈들... 끝이 없어!', `MaleText_loc4`='卡莱莎，你还活着！赶快找掩蔽所，这些怪物简直……无穷无尽！', `MaleText_loc5`='凱麗莎，你還活著!找個地方躲起來，那些東西源源不絕地冒出來!', `MaleText_loc7`='Kalytha, ¡todavía estás viva! Ponte a cubierto, ¡estas... cosas no se acaban nunca!' WHERE `ID`=35884;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직도 피가 흐르고 있나? 안 돼... 오래는 못 버틸 것 같아. 너 혹시 대마법사님 한 분이라도 봤어?', `MaleText_loc4`='我还在流血？我不能……不能坚持下去了。你有没有见到任何一位大法师？', `MaleText_loc5`='我還在流血嗎?我已經快...快支撐不住了。你有看到任何大法師嗎?', `MaleText_loc7`='¿Sigo sangrando? No puedo... No aguantaré mucho más. ¿Has visto a algún archimago?' WHERE `ID`=35885;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠... 아무래도 마법이 원인인 것 같군. 뿌린 대로 거두는 법이지... 엘룬이여, 힘을 주소서.', `MaleText_loc4`='嗯，我想这是魔法作用的结果。你收获了你所见到的一切……愿艾露恩保佑我们。', `MaleText_loc5`='嗯。這大概就是魔法的雙面刃。有因必有果...伊露恩救贖我們。', `MaleText_loc7`='Mmm. Supongo que la magia trae sus consecuencias. El que siembra vientos cosecha tempestades... Que Elune nos ayude a todos.' WHERE `ID`=35886;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼리사! 대마법사 셀윈 님이 널 찾으셨어. 근처 어딘가에 계실 거야...', `MaleText_loc4`='卡莱莎，大法师瑟维恩正在找你。她应该就在附近……', `MaleText_loc5`='凱麗莎!大法師賽爾溫正在找你。她應該在附近...', `MaleText_loc7`='¡Kalytha! La archimaga Selwyn te escaba buscando. Debería andar por aquí...' WHERE `ID`=35887;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 괴물들... 너무 많아. 너무 많은 목숨을 잃었어! 불타는 아즈샤라를 봐라. 명가의 일원들은 대체 무슨 짓을 저지른 거지?', `MaleText_loc4`='这些怪物……它们实在太多了。这么多人都死了！艾萨拉陷入了火海。那些上层精灵到底做了些什么？', `MaleText_loc5`='這些生物...太多了。太多死亡!看著艾薩拉燃燒吧。那些精靈貴族究竟做了什麼?', `MaleText_loc7`='Esas criaturas... Son tantas. ¡Tantos muertos! Mira cómo arde Azshara. ¿Qué han hecho los altonato?' WHERE `ID`=35888;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 왜 다른 이들과 도망가지 않은 걸까? 적들이 학회를 둘러싸고 있어. 이제 이곳에 갇혀버렸다고.', `MaleText_loc4`='为什么我没有和其他人一起逃走？他们已经将学院包围了。我们被困在了这里。', `MaleText_loc5`='我為什麼不跟其他人一起逃跑?他們已經包圍了學院，我們被困在這了。', `MaleText_loc7`='¿Por qué no he huido con los demás? Han rodeado la academia. Estamos atrapados.' WHERE `ID`=35889;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어떻게든 비전 보호막을 유지해야 해.', `FemaleText_loc4`='我维持着那些奥术结界的能量。', `FemaleText_loc5`='我必須保持秘法結界內的能量。', `FemaleText_loc7`='Tengo que mantener cargados los resguardos arcanos.' WHERE `ID`=35890;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='갈수록... 힘에... 부쳐. 칼리사, 대마법사님들께 다른 계획이 없는 건 아니겠지...', `FemaleText_loc4`='我的力量……正在……减弱。卡莱莎，请告诉我，大法师们还有备用计划……', `FemaleText_loc5`='我的力量...已經開始...衰弱了。凱麗莎，拜託你跟我說大法師們還有B計畫...', `FemaleText_loc7`='Mis fuerzas... empiezan a flaquear. Kalytha, por favor, informa a los archimagos que tengo un plan B...' WHERE `ID`=35891;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='보호막을 더는 유지할 수가 없어. 칼리사... 우리 중 누구라도 살아남을 수 있을까?', `FemaleText_loc4`='我没办法将这面护盾维持太久了。卡莱莎，我们之中能有人活过这场劫难吗？', `FemaleText_loc5`='我無法再支撐這個護盾多久了。凱麗莎，我們有人能存活下來嗎?', `FemaleText_loc7`='No puedo mantener el escudo mucho más tiempo. Kalytha, ¿alguno de nosotros sobrevivirá a esto?' WHERE `ID`=35892;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='괴물이 더 많아졌어! 대체 어디에서 온 거지? 이 도시에 무슨 일이 일어나고 있는 거야?', `FemaleText_loc4`='还有更多怪物！它们都是从哪里来的？首都现在怎么样了？', `FemaleText_loc5`='更多這種生物!他們是哪來的?市中心發生了什麼事?', `FemaleText_loc7`='¡Más criaturas de esas! ¿De dónde vienen? ¿Qué sucede en la capital?' WHERE `ID`=35893;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='칼리사! 서둘러. 대마법사 셀윈 님이 급한 일로 널 보자고 하셨어. 뭔가 좋은 방법이 있으신 거겠지?', `FemaleText_loc4`='卡莱莎！赶快，大法师瑟维恩正急着想要见你。也许我们还能渡过这个难关？', `FemaleText_loc5`='凱麗莎!快點!大法師賽爾溫要見你，她說很急!或許我們能夠勝利?', `FemaleText_loc7`='¡Kalytha! ¡Date prisa! La archimaga Selwyn quería verte, dijo que era urgente. ¿Quizá podemos ganar esta batalla?' WHERE `ID`=35894;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='보호막을 유지하기 위해 내가 할 수 있는 일은 다 했어. 대마법사님 중 하나를 찾아봐, 칼리사! 난 이제 더는 버티지 못할 것 같아...', `FemaleText_loc4`='我只能维持住这些结界。卡莱莎！赶快去找到一位大法师。我觉得我就要崩溃了……', `FemaleText_loc5`='我能做的只有維持住這個結界。凱麗莎，去找其中一位大法師!我感覺自己已經快要倒下了...', `FemaleText_loc7`='Es todo lo que puedo hacer para mantener activos los resguardos. ¡Busca a uno de los archimagos, Kalytha! Siento que estoy a punto de desmayarme...' WHERE `ID`=35895;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은빛십자군이 여는 마상시합에 여러분을 초대합니다. 다른 아제로스의 용사들과 명예로운 전투를 치르고 자신의 실력을 가늠해 보십시오.', `MaleText_loc4`='银色十字军邀请你参加银色锦标赛，在光荣的战斗中与艾泽拉斯各地的英雄们比试，并以此测试你的战斗技艺。', `MaleText_loc5`='銀白十字軍邀請你在銀白聯賽中，透過與艾澤拉斯英雄們的榮譽之戰來磨練你的戰技。', `MaleText_loc7`='La Cruzada Argenta te invita a que pongas a prueba tus habilidades en honorable combate contra otros héroes de Azeroth en el Torneo Argenta.' WHERE `ID`=35896;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='칼리사... 다 됐다. 사암 벽돌이 이미 마력으로 가득 차 차원문의 힘을 전환하고 있다. 몇 년 전부터 알던 대로 넌 아직 수영 실력이 뛰어나겠지? 악마의 무리나 저 "친애하는" 여왕께서 벽돌을 발견해서는 안 된다.$B$B호수 밑바닥으로 헤엄쳐 가라, 칼리사. 그리고 가운데 움푹한 곳 깊숙이 벽돌을 묻어라. 악마의 침략자들이 호수를 둘러싼 사원을 파괴해도 벽돌은 찾을 수 없도록 말이다. 가거라!', `FemaleText_loc4`='卡莱莎……完成了。这块岩石已经被充满能量，并开始从传送门转移能量。你的水性还和多年前一样令人惊叹吗？绝不能让恶魔或者我们“敬爱”的女王找到这块石头。$B$B游到湖底去，卡莱莎，将这块石头深埋在湖心。希望那些恶魔入侵者在摧毁湖周围的圣殿时不会发现它。去吧！', `FemaleText_loc5`='凱麗莎...完成了。薩森石已經充能完畢和開始引導傳送門的能量。你還是我多年前所認識的那個游泳好手嗎?石頭不能被惡魔或我們「親愛的」女王發現。$B$B游到湖底最深的地方，凱麗莎，然後將石頭埋在中央拱形處最深的地方。我們祈禱那些惡魔入境者在摧毀附近的神殿時不會發現它。快去!', `FemaleText_loc7`='Kalytha... Ya está hecho. La piedra sarcita está totalmente cargada y ya está desviando la energía del portal. ¿Sigues siendo esa magnífica nadadora que conocí hace tantos años? Ni los demonios ni nuestra "amada" Reina deben encontrar la piedra.$b$bNada hasta el fondo del lago, Kalytha, y entierra la piedra bajo el arco central. Con suerte, los invasores demoníacos no la descubrirán cuando asalten el templo circundante. ¡Ve!' WHERE `ID`=35897;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠습니다, 대마법사님. 벽돌을 숨기겠습니다.', `MaleText_loc4`='是的，大法师。我会藏好这块石头。', `MaleText_loc5`='是的，大法師。我會將石頭藏起來。', `MaleText_loc7`='Sí, archimaga. Esconderé la piedra.', `FemaleText_loc1`='알겠습니다, 대마법사님. 벽돌을 숨기겠습니다.', `FemaleText_loc4`='是的，大法师。我会藏好这块石头。', `FemaleText_loc5`='是的，大法師。我會將石頭藏起來。', `FemaleText_loc7`='Sí, archimaga. Esconderé la piedra.' WHERE `ID`=35898;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='<희미하게 빛나는 영혼은 당신의 존재를 눈치채지 못합니다. 그녀는 자신만의 세계에서 길을 잃고, 이미 수천 년 전에 있었던 일들에 반응하고 있습니다.>', `FemaleText_loc4`='<这个闪烁微光的身影并不知道你的出现。她迷失在自己的世界中，依旧只是关注着千万年以前发生的事情。>', `FemaleText_loc5`='<閃亮的視線並未發現你的存在。她迷失在自己的世界中，對千年前所發生的事件做出反應。>', `FemaleText_loc7`='<La visión resplandeciente no parece que te haya visto. Está perdida en su propio mundo y reacciona a eventos que sucedieron hace miles de años.>' WHERE `ID`=35902;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<영혼과 합체합니다.>', `MaleText_loc4`='<与这个灵魂融合。>', `MaleText_loc5`='<與靈魂結合。>', `MaleText_loc7`='<Fusiónate con el espíritu.>', `FemaleText_loc1`='<영혼과 합체합니다.>', `FemaleText_loc4`='<与这个灵魂融合。>', `FemaleText_loc5`='<與靈魂結合。>', `FemaleText_loc7`='<Fusiónate con el espíritu.>' WHERE `ID`=35903;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 공격을 개시할 때가 가까워졌을 때 얼음왕관 성채로의 돌격에 참여할 것이다.', `MaleText_loc4`='当进攻冰冠堡垒的战斗开始时，我一定会加入。', `MaleText_loc5`='當決戰的時刻來臨時，我將會加入冰冠城塞的突襲行動。', `MaleText_loc7`='Me uniré al asalto contra la Ciudadela de la Corona de Hielo cuando llegue el momento de atacar.' WHERE `ID`=35904;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발사 준비! 적들이 온다! 적들이 온다!!!', `MaleText_loc4`='准备武器！他们来了！他们来了！！', `MaleText_loc5`='做好準備!他們來了!他們來了!!!!', `MaleText_loc7`='¡Armas preparadas! ¡Ahí vienen! ¡AHÍ VIENEN!' WHERE `ID`=35905;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 노예들아! 더 빨리, 빨리들 움직여라!', `MaleText_loc4`='你们这些奴隶最好再卖力一些！', `MaleText_loc5`='你們這些奴隸全部給我認真點!', `MaleText_loc7`='¡Esclavos, será mejor que os deis prisa!' WHERE `ID`=35906;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어이! 거기! 그래, 너! 일하지 않고 뭐 하고 있나!', `MaleText_loc4`='你！是的，就是你！回去工作！', `MaleText_loc5`='你!別看旁邊，就是你!快回去工作!', `MaleText_loc7`='¡Tú! ¡Sí, tú! ¡Vuelve al trabajo!' WHERE `ID`=35907;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 직접 가게 만들지 않는 게 좋을걸! 짐승 같은 놈들!', `MaleText_loc4`='我可不想和这些蛮子混在一起！', `MaleText_loc5`='別逼我帶我的蠻卒進去!', `MaleText_loc7`='¡No me obliguéis a que entre ahí con mis brutos!' WHERE `ID`=35908;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 트롤들은 내가 만난 일꾼 중에 가장 형편없는 놈들이다!', `MaleText_loc4`='我发誓，你们这些巨魔是我见过的最糟糕的工人！', `MaleText_loc5`='我發誓，你們這些食人妖是我看過最爛的工人!', `MaleText_loc7`='¡Trols! ¡Os juro que sois el peor envío de trabajadores que hemos recibido nunca!' WHERE `ID`=35909;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 직접 어떻게 하는 건지 보여줘야 알겠나?', `MaleText_loc4`='难道我必须亲自告诉你该怎么做吗？！', `MaleText_loc5`='你是要我進去示範一次給你們看嗎?!', `MaleText_loc7`='¿Tengo que entrar ahí para enseñaros cómo se hace?' WHERE `ID`=35910;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쓸모없는 것들! 정말 뭣들 하는 거야! 저기 혼돈의 소용돌이에 한번 빠져봐야 정신들 차리겠어!', `MaleText_loc4`='没用的家伙！你们都是没用的家伙！我应该把你们都扔到大漩涡里去！', `MaleText_loc5`='真沒用!你們真的是太沒用了!我想我們恐怕必須把你們全丟進大漩渦裡!', `MaleText_loc7`='¡Inútiles! ¡Son todos unos inútiles! ¡Me temo que vamos a arrojarlos a todos a la Vorágine espiral!' WHERE `ID`=35911;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간이 곧 돈이다! 트롤들아!', `MaleText_loc4`='时间就是金钱，巨魔！', `MaleText_loc5`='時間就是金錢，食人妖!', `MaleText_loc7`='¡EL TIEMPO ES ORO, TROLS!' WHERE `ID`=35912;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죄다 언더마인으로 다시 보내버릴 거야!', `MaleText_loc4`='我要把你们都派回到安德麦去！', `MaleText_loc5`='你們全都會滾回幽坑城去!', `MaleText_loc7`='¡Van a regresar todos a Minahonda!' WHERE `ID`=35913;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 침입자가 없는지 잘 보도록 해. 걸리면 본때를 보여주고 말이야!', `MaleText_loc4`='你们这些笨蛋要注意外面的强盗，对付他们的时候绝对不要手软！', `MaleText_loc5`='你們這些笨蛋注意看有沒有強盜。用最極端的歧視對付他們!', `MaleText_loc7`='Muks, cuiden que no haya saqueadores. ¡Trátenlos con extremo prejuicio!' WHERE `ID`=35914;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 돈 냄새가 진하게 나는군. 빌지워터 항구의 모든 자산이 곧 내 손에 흘러들어올 것 같다고!', `MaleText_loc4`='我在远方看到了巨大的商机。整个锈水码头的资产都将流入我的腰包。', `MaleText_loc5`='我看到龐大的商機出現在眼前。整個污水港的資金都將流向我。', `MaleText_loc7`='Veo grandes ganancias en el horizonte. Todos los bienes del Puerto Pantoque fluirán hacia mí.' WHERE `ID`=35915;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카자로 산이야 폭발하든가 말든가. 중요한 건 내가 최고의 자리를 계속 지키는 거지!', `MaleText_loc4`='卡亚罗山有没有爆炸并不重要。重要的是我要继续坐在头把交椅上！', `MaleText_loc5`='就算卡亞羅山爆炸了都無所謂。重要的是我還在頂峰!', `MaleText_loc7`='No importa que el Monte Kajaro haya explotado. ¡Lo único que importa es seguir en la cima!' WHERE `ID`=35916;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐들, 내 수석 임원이 별장 근처에 얼씬도 못하게 하라고. 똑바로 지켜야 해. 알겠지?', `MaleText_loc4`='你们这些混蛋，给我听好了，绝不能让我的头号主管靠近这栋别墅。', `MaleText_loc5`='你們這些低等動物最好確定我的首席執行長不會靠近我的別墅。', `MaleText_loc7`='Ustedes brutos asegúrense de que mi ejecutivo número uno no se acerque a la villa.' WHERE `ID`=35917;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자자, 쾌속선이 준비됐다! 가장 돈 많고 힘 있는 자들만 우리와 함께 파도를 탈 자격이 있다!', `MaleText_loc4`='准备好我的游艇！我们将乘浪而行，而且我只欢迎最富有，最合适的人与我们同行！', `MaleText_loc5`='把我的遊艇準備好! 我們乘浪前進，只有最有錢和有資格的人才能一起來!', `MaleText_loc7`='¡Preparad mi yate! ¡Zarpamos con la marea y solo los más ricos y en forma serán bienvenidos a bordo!' WHERE `ID`=35918;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 머나먼 아즈샤라로 간다! 나는 그곳에 새로운 무역왕국을 세울 것이다. 스팀휘들 무역회사를 쓰러뜨릴 왕국을! 그리고 멀리 보이는 산 중턱에 내 얼굴도 하나 깎아 넣을 생각이다. 모두 내게 경의를 표하도록 말이지!', `MaleText_loc4`='我们将乘船前往遥远的艾萨拉。在那里，我会构建一个新的贸易帝国。热砂集团将被我们碾成齑粉！而且，我还会在远方土地的高山上雕刻我的巨像。到那时候，所有国家都要向我进贡！', `MaleText_loc5`='我們往遠方艾薩拉航行。我會在那裡創建一個新的貿易帝國。這個新帝國會粉碎熱砂企業!而我會把我的雕像刻在那個地方的山上!所有人都會前來朝拜我!', `MaleText_loc7`='Navegaremos a la distante Azshara. Allí, crearé un nuevo imperio comercial. ¡Que aplastará al Cártel Bonvapor! Y moldearé las montañas de esa tierra distante a mi semejanza. ¡Todos me pagarán tributo!' WHERE `ID`=35919;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음 손님!', `MaleText_loc4`='下一个请！', `MaleText_loc5`='下一位!', `MaleText_loc7`='¡Siguiente!' WHERE `ID`=35920;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까. 은빛 원형경기장에서 진영 대표 용사와 싸우고 싶으십니까?

당신은 현재 선택한 공격대 난이도에 맞는 전투를 치르게 됩니다. 이 공격대 전투는 아직 작업 중임을 기억해 주세요. 버그를 발견하면 블리자드 토론장을 통해 알려 주시기 바랍니다.

전투를 시작할까요?', `MaleText_loc4`='你好，你想要在银色演武场副本中同阵营冠军作战吗？

当你进入这一遭遇战副本时，副本的难度相当于当前你所选择的副本难度。这一遭遇战还在制作过程中，所以请在暴雪论坛上报告你所遇到的一切bug。

你是否准备好了进入这一遭遇战？', `MaleText_loc5`='嗨。你想要在銀白大競技場中跟各陣營勇士組來打上一場嗎?

你所要面對的挑戰將會取決於你目前所選擇的團隊難度。目前的挑戰賽還在調整當中。請將你所發現的問題或心得發表在暴雪討論版上。

你已經準備好要迎接挑戰了嗎?', `MaleText_loc7`='Hola. ¿Te gustaría participar en el encuentro contra los campeones de la facción para la banda del Coliseo Argenta?

Te enfrentarás a este encuentro en la versión que corresponda con la dificultad de banda actual que hayas seleccionado. Aún se está trabajando en este encuentro. Acuérdate de informar de los errores que encuentres en el foro de Blizzard.

¿Estás $gpreparado:preparada; para comenzar el encuentro?' WHERE `ID`=35921;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요, $c님.$B$B현재 호드가 겨울손아귀 요새를 점령했습니다. 겨울손아귀 요새의 전투가 시작되려고 하면 저와 대화하여 전투에 참여할 수 있습니다.$B$B다음 전투는 $4354k초 후에 시작됩니다.', `MaleText_loc4`='你好，$c。$B$B现在部落控制着冬拥堡垒。当争夺冬拥堡垒的战斗开始的时候，你和我交谈，就能加入这场战斗。$B$B这场战斗将在$4354k内开始。', `MaleText_loc5`='你好，$c。$B$B部落目前控制冬握堡壘。當戰鬥即將展開時，你可以跟我講一聲以進入戰鬥。$B$B下一場戰鬥將在$4354k後開始。', `MaleText_loc7`='Saludos, $c.$B$BActualmente la Horda controla la Fortaleza de Conquista del Invierno. Cuando la batalla esté a punto de comenzar, habla conmigo para unirte.$B$BLa siguiente batalla comenzará en $4354k.', `FemaleText_loc1`='안녕하세요, $c님.$B$B현재 호드가 겨울손아귀 요새를 점령했습니다. 겨울손아귀 요새의 전투가 시작되려고 하면 저와 대화하여 전투에 참여할 수 있습니다.$B$B다음 전투는 $4354k초 후에 시작됩니다.', `FemaleText_loc4`='你好，$c。$B$B现在部落控制着冬拥堡垒。当冬拥堡垒之战开始的时候，你和我交谈，就能加入这场战斗。$B$B这场战斗将在$4354k内开始。', `FemaleText_loc5`='你好，$c。$B$B部落目前控制冬握堡壘。當戰鬥即將展開時，你可以跟我講一聲以進入戰鬥。$B$B下一場戰鬥將在$4354k後開始。', `FemaleText_loc7`='Saludos, $c.$B$BActualmente la Horda controla la Fortaleza de Conquista del Invierno. Cuando la batalla esté a punto de comenzar, habla conmigo para unirte.$B$BLa siguiente batalla comenzará en $4354k.' WHERE `ID`=35922;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='들어라, 잊혀진 땅의 침략자여! 불타는 칼날단은 너희 모두를 제물로 바치리라!', `MaleText_loc4`='听我说，凄凉之地的入侵者们！你们全都会成为火刃的祭品！', `MaleText_loc5`='給我聽著，淒涼之地的入侵者!燃刃將拿你們作為獻祭品!', `MaleText_loc7`='¡Escuchadme, invasores de Desolace! ¡El Filo Ardiente os usará como sacrificios!', `FemaleText_loc1`='들어라, 잊혀진 땅의 침략자여! 불타는 칼날단은 너희 모두를 제물로 바치리라!', `FemaleText_loc4`='听我说，凄凉之地的入侵者们！你们全都会成为火刃的祭品！', `FemaleText_loc5`='給我聽著，淒涼之地的入侵者!燃刃將拿你們作為獻祭品!', `FemaleText_loc7`='¡Escuchadme, invasores de Desolace! ¡El Filo Ardiente os usará como sacrificios!' WHERE `ID`=35923;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑습니다, $c님.$B$B호드가 겨울손아귀 요새를 점령하고 있었습니다만, 다시 전투가 시작됐습니다. 어서 겨울손아귀로 가셔서 우리 군대를 지원해 주십시오!', `MaleText_loc4`='你好，$c。$B$B现在部落控制着冬拥堡垒。但争夺这座堡垒的战斗已经开始了。快些赶往冬拥湖，帮助我们进行这场战斗吧！', `MaleText_loc5`='你好，$c。$B$B部落目前控制冬握堡壘，但戰鬥已經開始了。快前往冬握湖支援我們的部隊!', `MaleText_loc7`='Saludos, $c.$B$BActualmente la Horda controla la Fortaleza de Conquista del Invierno, pero la batalla ha comenzado. ¡Ve corriendo a Conquista del Invierno y ayuda a nuestras tropas!', `FemaleText_loc1`='반갑습니다, $c님.$B$B호드가 겨울손아귀 요새를 점령하고 있었습니다만, 다시 전투가 시작됐습니다. 어서 겨울손아귀로 가셔서 우리 군대를 지원해 주십시오!', `FemaleText_loc4`='你好，$c。$B$B现在部落控制着冬拥堡垒。但争夺这座堡垒的战斗已经开始了。快些赶往冬拥湖，帮助我们进行这场战斗吧！', `FemaleText_loc5`='你好，$c。$B$B部落目前控制冬握堡壘，但戰鬥已經開始了。快前往冬握湖支援我們的部隊!', `FemaleText_loc7`='Saludos, $c.$B$BActualmente la Horda controla la Fortaleza de Conquista del Invierno, pero la batalla ha comenzado. ¡Ve corriendo a Conquista del Invierno y ayuda a nuestras tropas!' WHERE `ID`=35924;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='때가 가까워졌다! 우리는 이 땅을 휩쓸고, 거역하는 자는 모두 없애리라!', `MaleText_loc4`='时间就要到了！我们要横扫这片土地，让所有敢于挑战我们的生灵都成为祭品！', `MaleText_loc5`='這一天就快來了!我們將掃蕩這片大地，拿任何反抗我們的人作為祭品!', `MaleText_loc7`='¡Ya casi es la hora! ¡Barreremos esta tierra, sacrificando a todos los que nos desafíen!', `FemaleText_loc1`='때가 가까워졌다! 우리는 이 땅을 휩쓸고, 거역하는 자는 모두 없애리라!', `FemaleText_loc4`='时间就要到了！我们要横扫这片土地，让所有敢于挑战我们的生灵都成为祭品！', `FemaleText_loc5`='這一天就快來了!我們將掃蕩這片大地，拿任何反抗我們的人作為祭品!', `FemaleText_loc7`='¡Ya casi es la hora! ¡Barreremos esta tierra, sacrificando a todos los que nos desafíen!' WHERE `ID`=35925;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불타는 칼날단의 도음을 받아, 악마들이 아제로스를 지배하리라!', `MaleText_loc4`='有了火刃的帮助，恶魔将统治整个艾泽拉斯！', `MaleText_loc5`='在燃刃的幫助下，惡魔一族將會統治整個艾澤拉斯!', `MaleText_loc7`='¡Con la ayuda del Filo Ardiente, los demonios dominarán todo Azeroth!', `FemaleText_loc1`='불타는 칼날단의 도음을 받아, 악마들이 아제로스를 지배하리라!', `FemaleText_loc4`='有了火刃的帮助，恶魔将统治整个艾泽拉斯！', `FemaleText_loc5`='在燃刃的幫助下，惡魔一族將會統治整個艾澤拉斯!', `FemaleText_loc7`='¡Con la ayuda del Filo Ardiente, los demonios dominarán todo Azeroth!' WHERE `ID`=35926;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누구든지 덤벼라! 불타는 칼날단이 너희 영혼으로 잔치를 벌이리라!', `MaleText_loc4`='要战斗就过来吧！火刃氏族将饱餐你的灵魂！', `MaleText_loc5`='不滿的人儘管反抗!燃刃將以你們的靈魂為食!', `MaleText_loc7`='¡Que vengan los oponentes! ¡El Filo Ardiente se dará un festín con sus almas!', `FemaleText_loc1`='누구든지 덤벼라! 불타는 칼날단이 너희 영혼으로 잔치를 벌이리라!', `FemaleText_loc4`='要战斗就过来吧！火刃氏族将饱餐你的灵魂！', `FemaleText_loc5`='不滿的人儘管反抗!燃刃將以你們的靈魂為食!', `FemaleText_loc7`='¡Que vengan los oponentes! ¡El Filo Ardiente se dará un festín con sus almas!' WHERE `ID`=35927;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아제로스여, 준비하라! 불타는 칼날단의 시대가 온다!', `MaleText_loc4`='全体艾泽拉斯的生灵们，做好准备吧！火刃氏族的时代即将到来！', `MaleText_loc5`='艾澤拉斯所有的一切做好準備!燃刃的世代即將來臨!', `MaleText_loc7`='¡Que se prepare todo Azeroth! ¡Se acerca la hora del Filo Ardiente!', `FemaleText_loc1`='아제로스여, 준비하라! 불타는 칼날단의 시대가 온다!', `FemaleText_loc4`='全体艾泽拉斯的生灵们，做好准备吧！火刃氏族的时代即将到来！', `FemaleText_loc5`='艾澤拉斯所有的一切做好準備!燃刃的世代即將來臨!', `FemaleText_loc7`='¡Que se prepare todo Azeroth! ¡Se acerca la hora del Filo Ardiente!' WHERE `ID`=35928;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잊혀진 땅의 침략자들아, 불타는 칼날단에 투항하지 않으면 반항한 대가로 고통을 맛볼 것이다!', `MaleText_loc4`='凄凉之地的入侵者们，加入火刃，或者准备好承受与火刃对抗的后果吧！', `MaleText_loc5`='淒涼之地的入侵者們，加入燃刃的行列，或承受反抗所帶來的災難!', `MaleText_loc7`='Invasores de Desolace, ¡únanse a la Legión Ardiente o sufran las consecuencias de su desafío!', `FemaleText_loc1`='잊혀진 땅의 침략자들아, 불타는 칼날단에 투항하지 않으면 반항한 대가로 고통을 맛볼 것이다!', `FemaleText_loc4`='凄凉之地的入侵者们，加入火刃，或者准备好承受与火刃对抗的后果吧！', `FemaleText_loc5`='淒涼之地的入侵者們，加入燃刃的行列，或承受反抗所帶來的災難!', `FemaleText_loc7`='Invasores de Desolace, ¡únanse a la Legión Ardiente o sufran las consecuencias de su desafío!' WHERE `ID`=35929;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까. 은빛 원형경기장에서 발키르와 싸우고 싶으십니까?

당신은 현재 선택한 공격대 난이도에 맞는 전투를 치르게 됩니다. 이 공격대 전투는 아직 작업 중임을 기억해 주세요. 버그를 발견하면 블리자드 토론장을 통해 알려 주시기 바랍니다.

전투를 시작할까요?', `MaleText_loc4`='你好，你想要在银色竞技场副本中同瓦格里作战吗？

当你进入这一遭遇战副本时，副本的难度相当于当前你所选择的副本难度。这一遭遇战还在制作过程中，所以请在暴雪论坛上报告你所遇到的一切bug。

你是否准备好了进入这一遭遇战？', `MaleText_loc5`='嗨。你想要在銀白大競技場團隊中跟華爾琪來打上一場嗎?

你所要面對的挑戰將會取決於你目前所選擇的團隊難度。目前的挑戰賽還在調整當中。請將你所發現的問題或心得發表在暴雪討論版上。

你已經準備好要迎接挑戰了嗎?', `MaleText_loc7`='Hola. ¿Te gustaría participar en el encuentro contra las Val''kyr para la banda del Coliseo Argenta?

Te enfrentarás a este encuentro en la versión que corresponda con la dificultad de banda actual que hayas seleccionado. Aún se está trabajando en este encuentro. Acuérdate de informar de los errores que encuentres en el foro de Blizzard.

¿Estás $gpreparado:preparada; para comenzar el encuentro?' WHERE `ID`=35930;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음하하하! 너무 늦었다. 파멸의 소환이 가까웠노라!', `MaleText_loc4`='哇哈哈哈！你们太迟了。毁灭你们的力量已经受到召唤，即将降临！', `MaleText_loc5`='哇哈哈哈哈!你們已經太遲了。召喚你們末日的儀式已經快完成了!', `MaleText_loc7`='¡Juaaajajaaaa! Llegas demasiado tarde. ¡La invocación de tu perdición está casi completada!', `FemaleText_loc1`='음하하하! 너무 늦었다. 파멸의 소환이 가까웠노라!', `FemaleText_loc4`='哇哈哈哈！你们太迟了。毁灭你们的力量已经受到召唤，即将降临！', `FemaleText_loc5`='哇哈哈哈哈!你們已經太遲了。召喚你們末日的儀式已經快完成了!', `FemaleText_loc7`='¡Juaaajajaaaa! Llegas demasiado tarde. ¡La invocación de tu perdición está casi completada!' WHERE `ID`=35931;
