UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑습니다, $c님.$B$B얼라이언스가 겨울손아귀 요새를 점령하고 있었습니다만, 다시 전투가 시작됐습니다. 어서 겨울손아귀로 가셔서 우리 군대를 지원해 주십시오!', `MaleText_loc4`='你好，$c。$B$B现在联盟控制着冬拥堡垒。但争夺这座堡垒的战斗已经开始了。快些赶往冬拥湖，帮助我们进行这场战斗吧！', `MaleText_loc5`='你好，$c。$B$B聯盟目前控制冬握堡壘，但戰鬥已經開始了。快前往冬握湖支援我們的部隊!', `MaleText_loc7`='Saludos, $c.$B$BActualmente la Alianza controla la Fortaleza de Conquista del Invierno, pero la batalla ha comenzado. ¡Ve corriendo a Conquista del Invierno y ayuda a nuestras tropas!', `FemaleText_loc1`='반갑습니다, $c님.$B$B얼라이언스가 겨울손아귀 요새를 점령하고 있었습니다만, 다시 전투가 시작됐습니다. 어서 겨울손아귀로 가셔서 우리 군대를 지원해 주십시오!', `FemaleText_loc4`='你好，$c。$B$B现在联盟控制着冬拥堡垒。但争夺这座堡垒的战斗已经开始了。快些赶往冬拥湖，帮助我们进行这场战斗吧！', `FemaleText_loc5`='你好，$c。$B$B聯盟目前控制冬握堡壘，但戰鬥已經開始了。快前往冬握湖支援我們的部隊!', `FemaleText_loc7`='Saludos, $c.$B$BActualmente la Alianza controla la Fortaleza de Conquista del Invierno, pero la batalla ha comenzado. ¡Ve corriendo a Conquista del Invierno y ayuda a nuestras tropas!' WHERE `ID`=35933;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요, $c님.$B$B현재 얼라이언스가 겨울손아귀 요새를 점령했습니다. 겨울손아귀 요새의 전투가 시작되려고 하면 저와 대화하여 전투에 참여할 수 있습니다.$B$B다음 전투는 $4354k초 후에 시작됩니다.', `MaleText_loc4`='你好，$c。$B$B现在联盟控制着冬拥堡垒。当战斗就要开始的时候，你和我交谈，就能加入这场战斗。$B$B这场战斗将在$4354k内开始。', `MaleText_loc5`='你好，$c。$B$B聯盟目前控制冬握堡壘。當戰鬥即將展開時，你可以跟我講一聲以進入戰鬥。$B$B下一場戰鬥將在$4354k後開始。', `MaleText_loc7`='Saludos, $c.$B$BActualmente la Alianza controla la Fortaleza de Conquista del Invierno. Cuando la batalla esté a punto de comenzar, habla conmigo para unirte.$B$BLa siguiente batalla comenzará en $4354k.', `FemaleText_loc1`='안녕하세요, $c님.$B$B현재 얼라이언스가 겨울손아귀 요새를 점령했습니다. 겨울손아귀 요새의 전투가 시작되려고 하면 저와 대화하여 전투에 참여할 수 있습니다.$B$B다음 전투는 $4354k초 후에 시작됩니다.', `FemaleText_loc4`='你好，$c。$B$B现在联盟控制着冬拥堡垒。当战斗就要开始的时候，你和我交谈，就能加入这场战斗。$B$B这场战斗将在$4354k内开始。', `FemaleText_loc5`='你好，$c。$B$B聯盟目前控制冬握堡壘。當戰鬥即將展開時，你可以跟我講一聲以進入戰鬥。$B$B下一場戰鬥將在$4354k後開始。', `FemaleText_loc7`='Saludos, $c.$B$BActualmente la Alianza controla la Fortaleza de Conquista del Invierno. Cuando la batalla esté a punto de comenzar, habla conmigo para unirte.$B$BLa siguiente batalla comenzará en $4354k.' WHERE `ID`=35934;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겨울손아귀에 참여하고자 대기열에 들어가고 싶습니다.', `MaleText_loc4`='排队等待冬拥湖战场。', `MaleText_loc5`='加入冬握湖佇列。', `MaleText_loc7`='Hacer cola para Conquista del Invierno.', `FemaleText_loc1`='겨울손아귀에 참여하고자 대기열에 들어가고 싶습니다.', `FemaleText_loc4`='排队等待冬拥湖战场。', `FemaleText_loc5`='加入冬握湖佇列。', `FemaleText_loc7`='Hacer cola para Conquista del Invierno.' WHERE `ID`=35935;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날씨가 좋군요, $g선생님:부인;! 제가 어떻게 도와드리면 될까요?', `MaleText_loc4`='你好，$g先生:女士;！我能为你做些什么？', `MaleText_loc5`='日安，$g先生:女士;!有什麼我能幫得上忙的嗎?', `MaleText_loc7`='¡Buenos días, $gseñor:señora;! ¿En qué puedo ayudarle?' WHERE `ID`=35936;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='섬세하게 짜인 시간과 공간 사이에 난 이 틈은 불길하게 느껴집니다. 다양한 장면이 무시무시한 속도로 스쳐 지나갑니다. 진정 용감한 자만이 감히 이곳을 통과하려고 할 것입니다...', `MaleText_loc4`='在时间和空间构造上出现的这道裂痕看起来非常凶险。许多截然不同的景象从这道裂痕中以可怕的速度闪过。此时此刻，大概只有极为勇敢的人才会跳入其中……', `MaleText_loc5`='這個時間與空間的裂縫看起來相當不妙。不同的景象以一種駭人的速度閃過。一個非常勇敢的人或許能試著在正確的時間點跳過去...', `MaleText_loc7`='Esta brecha en el tejido del espacio y el tiempo no presagia nada bueno. Distintas escenas pasan a una velocidad aterradora. Puede que una persona muy valiente intente atravesarla en el momento adecuado...' WHERE `ID`=35938;
