UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밖은 안전하지 않소, $n. 너무 늦기 전에 숨을 곳을 찾아보시오.', `MaleText_loc4`='这里并不安全，$n。赶快去找避难所。', `MaleText_loc5`='這裡不安全，$n。在還來得及前尋找庇護所。', `MaleText_loc7`='Este lugar no es seguro, $n. Busca cobijo antes de que sea demasiado tarde.' WHERE `ID`=35946;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐. 구해 줘서 정말 고맙군. 원한은 없는 거지? 응?', `MaleText_loc4`='嗨，$n，真高兴是你救了我。你没生我的气吧？', `MaleText_loc5`='你好啊，$n。謝謝你救了我。咱們之間沒什麼芥蒂，對吧?', `MaleText_loc7`='Hola. Gracias por rescatarme. Sin resentimientos, ¿no?' WHERE `ID`=35947;
