UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아플 거다! 뇌!', `MaleText_loc4`='这一定很痛！脑子！', `MaleText_loc5`='那真痛!腦汁四溢!', `MaleText_loc7`='¡Eso ha tenido que doler! ¡Cerebros!' WHERE `ID`=35952;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='외딴 섬에 고립됐어요! 얼라이언스 때문에 산산조각이 난 데다 어디인지 아무도 모르는 곳 한가운데에 있는 섬에서 오도 가도 못하는 상황이라니까요?!$B$B그래도 평상시대로 지내세요. 알겠죠, $n 님?', `FemaleText_loc4`='我们孤立无援！联盟击溃了我们，让我们流落到天知道是在哪里的孤岛上！$B$B但生意还得进行，不是吗，$n？', `FemaleText_loc5`='被孤立了!被聯盟炸成了碎片後飄到了不知在什麼鬼地方的小島上?!$B$B反正都習慣了，對吧$n?', `FemaleText_loc7`='¡Abandonados! ¡Destrozados por la Alianza y varados en una isla en mitad de quién-sabe-dónde!$B$BAsí son los negocios, ¿eh, $n?' WHERE `ID`=35953;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뇌에 명중!', `MaleText_loc4`='漂亮的爆头射击！', `MaleText_loc5`='專攻腦子!', `MaleText_loc7`='¡Menudo disparo de cerebros!' WHERE `ID`=35954;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요, $c님.$B$B현재 호드가 겨울손아귀 요새를 점령했습니다만, 다음 전투가 곧 시작될 겁니다! 겨울손아귀로 가셔서 우리 군대를 지원할 채비를 갖추십시오!$B$B다음 전투는 $4354k초 후에 시작됩니다.', `MaleText_loc4`='你好，$c。$B$B现在部落控制着冬拥堡垒。但下一场争夺这座堡垒的战斗就要开始了。赶快做好准备，前往冬拥湖帮助我们作战吧！$B$B这场战斗将在$4354k内开始。', `MaleText_loc5`='你好，$c。$B$B部落目前控制冬握堡壘，但下一場戰鬥即將展開。準備好前往冬握湖支援我們的部隊!$B$B下一場戰鬥將在$4354k後開始。', `MaleText_loc7`='Saludos, $c.$B$BActualmente la Horda controla la Fortaleza de Conquista del Invierno, pero la próxima batalla comenzará pronto. ¡Prepárate para ir a Conquista del Invierno y apoyar a nuestras tropas!$B$BLa siguiente batalla comenzará en $4354k.', `FemaleText_loc1`='안녕하세요, $c님.$B$B현재 호드가 겨울손아귀 요새를 점령했습니다만, 다음 전투가 곧 시작될 겁니다! 겨울손아귀로 가셔서 우리 군대를 지원할 채비를 갖추십시오!$B$B다음 전투는 $4354k초 후에 시작됩니다.', `FemaleText_loc4`='你好，$c。$B$B现在部落控制着冬拥堡垒。但下一场争夺这座堡垒的战斗就要开始了。赶快做好准备，前往冬拥湖帮助我们作战吧！$B$B这场战斗将在$4354k内开始。', `FemaleText_loc5`='你好，$c。$B$B部落目前控制冬握堡壘，但下一場戰鬥即將展開。準備好前往冬握湖支援我們的部隊!$B$B下一場戰鬥將在$4354k後開始。', `FemaleText_loc7`='Saludos, $c.$B$BActualmente la Horda controla la Fortaleza de Conquista del Invierno, pero la próxima batalla comenzará pronto. ¡Prepárate para ir a Conquista del Invierno y apoyar a nuestras tropas!$B$BLa siguiente batalla comenzará en $4354k.' WHERE `ID`=35955;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요, $c님.$B$B현재 얼라이언스가 겨울손아귀 요새를 점령했습니다만, 다음 전투가 곧 시작될 겁니다! 겨울손아귀로 가셔서 우리 군대를 지원할 채비를 갖추십시오!$B$B다음 전투는 $4354k초 후에 시작됩니다.', `MaleText_loc4`='你好，$c。$B$B现在冬拥堡垒由联盟控制，但下一次战斗就要开始了！加入冬拥湖的战斗，帮助我们赢取胜利吧！$B$B这场战斗将在$4354k内开始。', `MaleText_loc5`='你好，$c。$B$B聯盟目前控制冬握堡壘，但下一場戰鬥即將展開。準備好前往冬握湖支援我們的部隊!$B$B下一場戰鬥將在$4354k後開始。', `MaleText_loc7`='Saludos, $c.$B$BActualmente la Alianza controla la Fortaleza de Conquista del Invierno. ¡La batalla por la Fortaleza de Conquista del Invierno está a punto de comenzar! ¿Quieres unirte a la batalla?$B$BLa siguiente batalla comenzará en $4354k.', `FemaleText_loc1`='안녕하세요, $c님.$B$B현재 얼라이언스가 겨울손아귀 요새를 점령했습니다만, 다음 전투가 곧 시작될 겁니다! 겨울손아귀로 가셔서 우리 군대를 지원할 채비를 갖추십시오!$B$B다음 전투는 $4354k초 후에 시작됩니다.', `FemaleText_loc4`='你好，$c。$B$B现在冬拥堡垒由联盟控制，但下一次战斗就要开始了！加入冬拥湖的战斗，帮助我们赢取胜利吧！$B$B这场战斗将在$4354k内开始。', `FemaleText_loc5`='你好，$c。$B$B聯盟目前控制冬握堡壘，但下一場戰鬥即將展開。準備好前往冬握湖支援我們的部隊!$B$B下一場戰鬥將在$4354k後開始。', `FemaleText_loc7`='Saludos, $c.$B$BActualmente la Alianza controla la Fortaleza de Conquista del Invierno. ¡La batalla por la Fortaleza de Conquista del Invierno está a punto de comenzar! ¿Quieres unirte a la batalla?$B$BLa siguiente batalla comenzará en $4354k.' WHERE `ID`=35956;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 밟혔습니다!', `MaleText_loc4`='$n被踏倒了！', `MaleText_loc5`='$n被踐踏了!', `MaleText_loc7`='¡$n está aplastado!', `FemaleText_loc1`='$n|1이;가; 밟혔습니다!', `FemaleText_loc4`='$n被踏倒了！', `FemaleText_loc5`='$n被踐踏了!', `FemaleText_loc7`='¡$n está aplastado!' WHERE `ID`=35957;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하시오, $c|1이여;여;.$b$b주위를 둘러보시오. 이 모든 일이 무슨 의미일까 잠시 멈춰 서서 생각해 본 적은 있소?', `MaleText_loc4`='你好，$c。$b$b看看你的周围。你有没有认真考虑过所有这些东西的意义？', `MaleText_loc5`='你好，$c。$b$b看看你的周圍。你有靜下來仔細想想這一切代表什麼嗎?', `MaleText_loc7`='Saludos, $c.$b$bMira a tu alrededor. ¿Te has detenido a pensar qué significa todo esto?' WHERE `ID`=35958;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='심판관 마리엘 트루하트 님께서 저희에게 마상시합에 부족한 점이 없도록 조치해 달라고 말씀하셨습니다. 용사의 자격을 얻은 분들, 그리고 저희에게 능력을 인정받은 분들께서는 이 임무를 도와주셨으면 합니다.', `FemaleText_loc4`='裁决者玛蕾尔·图哈特请求我们负责锦标赛所需的各项工作。而我们只会邀请那些曾经在我们面前证明过自身实力的真正勇士帮助我们完成这些工作。', `FemaleText_loc5`='審判者瑪瑞爾·真心請我們來注意聯賽中的需要。那些贏得勇士資格的人，以及向我們證明自己價值的人都被要求要來盡這些職責。', `FemaleText_loc7`='La justicar Mariel Corazón Veraz nos ha pedido que nos ocupemos del torneo. A los que se han ganado el derecho de alzarse como campeones y han demostrado su valía ante nuestros ojos se les pide que ayuden con estas tareas.' WHERE `ID`=35959;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='심판관 마리엘 트루하트 님께서 마상시합과 관련된 다양한 일을 처리해 달라는 중한 임무를 저희에게 맡기셨습니다. 안타깝게도 그분께선 선리버에도 같은 임무를 맡기셨지요. 다시 말해, 우린 그 멍청이들이 일으킨 문제를 처리하려고 두 배로 열심히 일해야 합니다!', `FemaleText_loc4`='裁决者玛蕾尔·图哈特委托我们负责锦标赛所需的各项工作。不幸的是，她把同样的工作也委托给了夺日者。那些蠢货只会给我们制造麻烦。现在我们的工作量要成倍地增加了！', `FemaleText_loc5`='審判者瑪瑞爾·真心委託我們來維護聯賽中的許多事務。不幸地，她也同要要求奪日者進行一樣的事，這表示我們得花上兩倍的努力來解決那些蠢蛋製造的問題。', `FemaleText_loc7`='La justicar Mariel Corazón Veraz nos ha confiado la tarea de supervisar muchos de los aspectos del torneo. Por desgracia les ha pedido lo mismo a los Atracasol, ¡lo que significa que tendremos que trabajar el doble para arreglar los problemas que ocasionen esos insensatos!' WHERE `ID`=35960;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='', `MaleText_loc4`='', `MaleText_loc5`='', `MaleText_loc7`='' WHERE `ID`=35961;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 고의로 방해한 거야! 난 망했어...$b$b배후에 있는 게 누구든 대가를 치러야 할 거야! 맹세코...', `MaleText_loc4`='这是破坏行为！我已经被毁了……$b$b这一切的幕后操纵者一定要付出代价！我说话算话……', `MaleText_loc5`='破壞!我完了....$b$b那個幕後黑手一定會為此付出代價!我跟你保證....', `MaleText_loc7`='¡Sabotaje! Estoy arruinado...$b$b¡Quienquiera que haya sido pagará por esto! Te lo prometo...' WHERE `ID`=35962;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n? 넌 사냥꾼이 아니라 $c|1이잖아;잖아;? 왜 날 귀찮게 하는 거야?', `MaleText_loc4`='$n? $G先生:女士;，你不是猎人，你是$c。', `MaleText_loc5`='$n?$G先生:女士;，你不是個獵人，你是個$c。', `MaleText_loc7`='¿$n? $GSeñor:Señorita;, no eres $Gun cazador:una cazadora;, eres $gun:una; $c.', `FemaleText_loc1`='$n? 당신은 사냥꾼이 아니라 $c|1이잖아요;잖아요;? 왜 날 귀찮게 하는 거죠?', `FemaleText_loc4`='$n? $G先生:女士;，你不是猎人，你是$c。', `FemaleText_loc5`='$n?$G先生:女士;，你不是個獵人，你是個$c。', `FemaleText_loc7`='¿$n? Usted no es $gun:una; $gcazador:cazadora;, sino un $c.' WHERE `ID`=35963;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 잠시 사냥꾼의 길에 대해 이야기를 나눠볼까? 즐거운 시간이 될 거야.', `MaleText_loc4`='哦，我们将一起渡过一段重要的时光。关于猎人之路，我有很多东西要教你。', `MaleText_loc5`='噢，你和我會有段美好的時光。我有很多與獵人有關的可以教你。', `MaleText_loc7`='Oh, tú y yo lo vamos a pasar genial. Tengo tanto que enseñarte sobre el arte de los cazadores.', `FemaleText_loc1`='자, 잠시 사냥꾼의 길에 대해 이야기를 나눠볼까요? 즐거운 시간이 될 거예요.', `FemaleText_loc4`='哦，我们将一起渡过一段重要的时光。关于猎人之路，我有很多东西要教你。', `FemaleText_loc5`='噢，你和我會有段美好的時光。我有很多與獵人有關的可以教你。', `FemaleText_loc7`='Oh, tú y yo nos lo vamos a pasar en grande. Tengo mucho que enseñarte acerca de cómo ser un buen cazador.' WHERE `ID`=35964;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대의 도움이 필요하오, $n. 사방에 늑대인간이 넘쳐나고 있소!', `MaleText_loc4`='我们需要你，$n！这里到处都是狼人！', `MaleText_loc5`='我們需要你，$n!狼人到處都是!', `MaleText_loc7`='¡Te necesitamos, $n! ¡Hay huargen por todas partes!' WHERE `ID`=35965;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끔찍하기 짝이 없어. 모두 죽은 것 같아.$B$B이제 카자마이트를 어떻게 캐야 하지?', `MaleText_loc4`='这太恐怖了。我怀疑他们全都死了。$B$B现在我该怎样把卡亚矿石从这里运出去？', `MaleText_loc5`='太恐怖了。我想他們全都死光了。$B$B我現在要怎樣才能把卡迦邁礦從那運出來?', `MaleText_loc7`='Es terrible. Creo que están todos muertos.$B$B¿Ahora cómo extraeré la kaja''mita?' WHERE `ID`=35966;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아악! 또야!', `MaleText_loc4`='啊！不要再搞了！', `MaleText_loc5`='呃啊!別再來了!', `MaleText_loc7`='¡Rargh! ¡Otro no!' WHERE `ID`=35967;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 땅속에서 모습을 드러냅니다!', `MaleText_loc4`='%s从地面上升起来了！', `MaleText_loc5`='%s從地底鑽出!', `MaleText_loc7`='¡%s emerge de la tierra!' WHERE `ID`=35968;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발보아를 그냥 내버려 둬, 이 벌레 같은 놈들아!', `MaleText_loc4`='不要招惹巴伯亚，你这个发光的小虫子！', `MaleText_loc5`='離巴爾玻亞遠點你這發亮的蟲子!', `MaleText_loc7`='¡Dejad en paz a Balboa, mequetrefes relucientes!' WHERE `ID`=35969;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 그런 거야?! 그만둬!', `MaleText_loc4`='这是谁干的？！停止！', `MaleText_loc5`='誰做的?!快停!', `MaleText_loc7`='¿Quién ha hecho eso? ¡Para!' WHERE `ID`=35970;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 그만! 정말 싫다고!', `MaleText_loc4`='不要再这样了！我不喜欢这样！', `MaleText_loc5`='停止!我不喜歡!', `MaleText_loc7`='¡No más! ¡Eso no gustar!' WHERE `ID`=35971;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='속삭이는 바람이 제게 $r $c|1이;가; 찾아올 것이라 일러 주었습니다. 많은 이가 해내지 못했던 일을 그분이 해주실 거라고도요.$b$b당신이 그분이십니까?', `FemaleText_loc4`='风已经悄声告诉我，一名$r$c即将到来。$g他:她;会帮助我取得成功，而不是像其他人那样只能让我尝到失败的苦果。$b$b你会是那个人吗？', `FemaleText_loc5`='風聲的細語讓我知道一個$r將會到來;$g他:她;將幫助我達成其他人無法達成的事。$b$b你是否就是我在等的人?', `FemaleText_loc7`='Los vientos susurrantes me han hecho saber que vendría $gun:una; $r $c que me ayudaría y conseguiría lo que otros no han conseguido.$b$b¿Podrías ser tú?' WHERE `ID`=35972;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 말한 위협을 볼 준비가 됐습니다, 코라.', `MaleText_loc4`='我已经准备好了解你所说的那个威胁了，库拉。', `MaleText_loc5`='我已經準備好要面對你說的那個威脅了，柯拉。', `MaleText_loc7`='Estoy listo para que me muestres esa amenaza de la que hablas, Korrah.', `FemaleText_loc1`='당신이 말한 위협을 볼 준비가 됐습니다, 코라.', `FemaleText_loc4`='我已经准备好了解你所说的那个威胁了，库拉。', `FemaleText_loc5`='我已經準備好要面對你說的那個威脅了，柯拉。', `FemaleText_loc7`='Estoy lista para que me muestres esa amenaza de la que hablas, Korrah.' WHERE `ID`=35973;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 자네를 훈련시킬 수는 없지만, 이 망할 원숭이들을 처리하는 도움은 받았으면 좋겠어!', `MaleText_loc4`='我无法对你进行任何训练，$n。但我需要你帮我对付这些该死的猴子！', `MaleText_loc5`='我無法提供你任何訓練，$n，但是我很需要你幫助我對付這些死猴子!', `MaleText_loc7`='No puedo ofrecerte instrucción, $n, ¡pero estoy seguro de que me vendría muy bien tu ayuda con esos malditos monos!' WHERE `ID`=35974;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아끼는 흑마법사가 왔군! 오늘은 어떤 어둠의 마법을 속삭여줄까?', `MaleText_loc4`='我喜欢术士！今天我能在你的耳边说一些怎样的黑暗秘密？', `MaleText_loc5`='這才是我最喜愛的術士!你今天想要聆聽何種黑暗的秘密?', `MaleText_loc7`='¡Aquí está mi camarada $gbrujo:bruja;! ¿Qué oscuros secretos puedes susurrarme al oído hoy?' WHERE `ID`=35975;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 나는 자네에게 마법의 길을 알려줄 수가 없어. 아, 이 손가락 움직이는 거 말인가? 목이나 주물러 줄까 해서...', `MaleText_loc4`='嗨，$n$g先生:女士; ，我无法传授你魔法技艺，只能教你如何用手指按摩僵硬的脖子。', `MaleText_loc5`='嗨，$n$g先生:女士;。我無法給你魔法的訓練，但我靈活的手指可以給你做一次很讚的馬殺雞。', `MaleText_loc7`='¡Eh, hola, $gseñor:señora; $n! No puedo enseñarte nada sobre los caminos de la magia, pero todo este movimiento de dedos significa que puedo dar un masaje de cuello genial.', `FemaleText_loc1`='$n, 나는 당신에게 마법의 길을 알려줄 수가 없어요. 아, 이 손가락 움직이는 거 말인가요? 목이나 주물러 줄까 해서...', `FemaleText_loc4`='嗨，$n$g先生:女士; ，我无法传授你魔法技艺，只能教你如何用手指按摩僵硬的脖子。', `FemaleText_loc5`='嗨，$n$g先生:女士;。我無法給你魔法的訓練，但我靈活的手指可以給你做一次很讚的馬殺雞。', `FemaleText_loc7`='Hola, $gSr.:Srta.; $n. No puedo enseñarte los caminos de la magia, pero estos dedos temblorosos significan que puedo darte un mal masaje de cuello.' WHERE `ID`=35976;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죄송합니다만, 다른 볼일이 있어 이 자리를 떠나야 할 듯합니다. 다음에 또 찾아 주십시오.', `MaleText_loc4`='请原谅，恐怕现在我还有别的事情必须去做。请以后再来找我。', `MaleText_loc5`='如果您允許的話，我恐怕得去處理其他事情了。請稍後再呼喚我。', `MaleText_loc7`='Si me disculpas, me temo que hay otros asuntos que debo atender. Vuelve a verme en el futuro.' WHERE `ID`=35977;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련하기에 딱 좋은 날씨군. 안 그런가, $n?', `MaleText_loc4`='这正是个传授神秘技艺的好日子。你是不是也这样想，$n$g先生:女士;？', `MaleText_loc5`='這真是適合練習神秘魔法的好天氣。你同意嗎，$n$g先生:女士;?', `MaleText_loc7`='Qué día más estupendo para emprender el estudio de las artes místicas. ¿No estás de acuerdo, $gseñor:señora; $n?', `FemaleText_loc1`='훈련하기에 딱 좋은 날씨군요. 안 그런가요, $n?', `FemaleText_loc4`='这正是个传授神秘技艺的好日子。你是不是也这样想，$n$g先生:女士;？', `FemaleText_loc5`='這真是適合練習神秘魔法的好天氣。你同意嗎，$n$g先生:女士;?', `FemaleText_loc7`='Qué día más maravilloso para entrenar las artes místicas. ¿No está usted de acuerdo, $n?' WHERE `ID`=35978;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희와 전투를 벌일 상대를 준비시키시지요.', `MaleText_loc4`='我可以给你一点时间，让你为这场战斗做好准备。', `MaleText_loc5`='讓我給您一點時間，並讓我們的對手準備好戰鬥。', `MaleText_loc7`='Dame un minuto para preparar a nuestros oponentes para la batalla.', `FemaleText_loc1`='저희와 전투를 벌일 상대를 준비시키시지요.', `FemaleText_loc4`='我可以给你一点时间，让你为这场战斗做好准备。', `FemaleText_loc5`='讓我給您一點時間，並讓我們的對手準備好戰鬥。', `FemaleText_loc7`='Dame un minuto para preparar a nuestros oponentes para la batalla.' WHERE `ID`=35979;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 일을 아주 잘한다고 하더군, $n. 계속 건투를 비네.', `MaleText_loc4`='干得漂亮，$n$g先生:女士;。保持这种高水平的发挥吧。', `MaleText_loc5`='你做的太棒了，$n$g先生:女士;。再接再勵。', `MaleText_loc7`='Estás haciendo un buen trabajo, $gseñor:señora; $n. Sigue así.' WHERE `ID`=35980;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장래 유망한 젊은이여! 무슨 도움이 필요한가?', `MaleText_loc4`='我预见到了你光辉的未来，我的孩子！今天我要教你些什么？', `MaleText_loc5`='我在你身上看到了光明的未來，孩子!你今天想學什麼?', `MaleText_loc7`='¡Veo que tendrás un futuro brillante, joven! ¿Qué debería enseñarte hoy?' WHERE `ID`=35981;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사방 천지에 폭탄 던지는 원숭이가 가득한 섬에 조난당하다니? 다음엔 또 무슨 일이 벌어질까요... 여기에도 곧 폭발할 화산이 있나요?', `FemaleText_loc4`='一座岛屿旁的失事船只上挤满了扔炸弹的猴子？那这以后又会有什么……一座即将爆炸的火山？', `FemaleText_loc5`='因為船失事來到了一座島，布滿了愛亂丟炸彈的猴子?然後是什麼?難不成還有會爆發的火山?', `FemaleText_loc7`='Naufragamos y acabamos en una isla infestada de monos que arrojan bombas. Qué será lo siguiente... ¡¿Hay algún volcán por aquí que vaya a entrar en erupción?!' WHERE `ID`=35982;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리는.. 아니,러니까 성스러운 빛께서도 골드가 많이 필요하실 거예요. 그 어느 때보다도 많이요.$B$B말이 나와서 말인데, 훈련이 필요하세요?', `FemaleText_loc4`='我们需要……呃，我是说，圣光需要许多金钱，而且现在比以往更加需要。$B$B我们说到哪里了？你需要训练吗？', `FemaleText_loc5`='我們...呃...我是說聖光將需要許多金幣，比以往都要來的多。$B$B話說回來，你需要什麼訓練嗎?', `FemaleText_loc7`='Nosotros... eh, quiero decir la Luz, va a necesitar un montón de oro, ahora más que nunca.$B$BY hablando del tema, ¿necesitas instrucción?' WHERE `ID`=35983;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 보이나요? 어떻게 절 보실 수 있죠?$B$B연구를 좀 해봐야겠군요.', `FemaleText_loc4`='你能看见我？你怎么可能看见我，老板？$B$B我正在努力提高自己的潜行技巧呢。', `FemaleText_loc5`='你看得見我?你為什麼可以看見我，老闆?$B$B我必須要找到答案。', `FemaleText_loc7`='¿Puedes verme? ¿Cómo es que puedes verme, $gjefe:jefa;?$B$BTengo que trabajar en eso.' WHERE `ID`=35984;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='훈련, 안마, 뭐든 말만 하세요. 대신 새 무역왕이 되었을 때 나 몰라라 하시면 안 돼요!', `FemaleText_loc4`='不管是训练还是按摩，我能满足你的一切需要，老板。只是当你成为新的贸易大王时不要忘记我！', `FemaleText_loc5`='訓練，按摩，任何你所需要的，老闆。只要你成為新的貿易親王那天別忘了我就好了。', `FemaleText_loc7`='Instrucción, masajes, lo que necesites, $gjefe:jefa;. ¡Tú no te olvides de mí cuando seas $gel nuevo Príncipe mercante:la nueva Princesa mercante;!' WHERE `ID`=35985;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 흑마법사가 소환한 건 파멸의 수호병이 아니군요! 다음 도전에서 여러분은 은빛십자군 기사들을 상대로 전투를 벌이게 됩니다. 도전할 준비가 되셨나요?', `MaleText_loc4`='那名术士肯定没有召唤末日守卫。你在下一场挑战中将和银色十字军作战。做好接受挑战的准备了吗？', `MaleText_loc5`='那個術士召喚的可不是末日守衛!你的下一場挑戰將會是銀白十字軍的騎士。你想要接受挑戰嗎?', `MaleText_loc7`='Está claro que ese brujo no invocó a un señor demoníaco. Su siguiente reto los llevará a luchar contra caballeros de la Cruzada Argenta. ¿Creen que están a la altura?' WHERE `ID`=35986;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론입니다!', `MaleText_loc4`='当然！', `MaleText_loc5`='當然!', `MaleText_loc7`='¡Claro!', `FemaleText_loc1`='물론이죠!', `FemaleText_loc4`='当然！', `FemaleText_loc5`='當然!', `FemaleText_loc7`='¡Claro!' WHERE `ID`=35987;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋습니다. 준비되시면 티리온 님께 신호를 보내겠습니다.', `MaleText_loc4`='好吧，你做好准备之后，我就会向提里奥发出信号。', `MaleText_loc5`='嗯，等你準備好出發的時候，我會用信號通知提里奧。', `MaleText_loc7`='Entonces daré la señal a Tirion cuando estén listos.' WHERE `ID`=35988;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신호를 보내세요! 저희는 준비됐습니다!', `MaleText_loc4`='发信号吧！我们已经准备好了！', `MaleText_loc5`='發出信號!我們準備好了!', `MaleText_loc7`='¡Da la señal! ¡Estamos preparados!', `FemaleText_loc1`='신호를 보내세요! 저희는 준비됐습니다!', `FemaleText_loc4`='发信号吧！我们已经准备好了！', `FemaleText_loc5`='發出信號!我們準備好了!', `FemaleText_loc7`='¡Da la señal! ¡Estamos preparados!' WHERE `ID`=35989;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맹렬하고도 가차없는 전투였습니다. 이렇게 치열한 전투는 오랫동안 보지 못했어요! 대단하십니다!', `MaleText_loc4`='这场战斗真是野蛮残忍至极。我已经有许多年没见到过如此大规模的战斗了！实在是令人震惊！', `MaleText_loc5`='那場戰鬥真是野蠻而暴力。我好多年沒看過這樣的技擊大賽了!真驚人!', `MaleText_loc7`='Esa lucha ha sido salvaje y brutal. ¡No he visto una gran melé como esa en muchos años! ¡Increíble!' WHERE `ID`=35990;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희가 저들에게 이기면 더욱 놀라시겠군요!', `MaleText_loc4`='等到我们将他们彻底消灭的时候，你会更吃惊的！', `MaleText_loc5`='等我們把他們全解決，你會更吃驚!', `MaleText_loc7`='¡Estarás aún más impresionado cuando acabemos con ellos!', `FemaleText_loc1`='저희가 저들에게 이기면 더욱 놀라시겠군요!', `FemaleText_loc4`='等到我们将他们彻底消灭的时候，你会更吃惊的！', `FemaleText_loc5`='等我們把他們全解決，你會更吃驚!', `FemaleText_loc7`='¡Estarás aún más impresionado cuando acabemos con ellos!' WHERE `ID`=35991;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빨리 구경하고 싶어 좀이 쑤시는군요! 저들은 다시 전투를 벌일 준비가 된 것 같으니, 여러분도 준비하십시오!', `MaleText_loc4`='我已经等不及要看到下一场战斗了！他们似乎已经做好了准备。所以，你们也赶快进行准备吧！', `MaleText_loc5`='我可等不及要看了!他們看來準備好下一輪了，所以你們也做好準備吧!', `MaleText_loc7`='¡No puedo esperar para verlo! Parecen listos para otra ronda, así que preparaos.' WHERE `ID`=35992;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희는 누구라도 상대할 준비가 되어 있습니다!', `MaleText_loc4`='我们已经做好了一切准备！', `MaleText_loc5`='我們隨時候教!', `MaleText_loc7`='¡Estamos preparados para cualquier cosa!', `FemaleText_loc1`='저희는 누구라도 상대할 준비가 되어 있어요!', `FemaleText_loc4`='我们已经做好了一切准备！', `FemaleText_loc5`='我們隨時候教!', `FemaleText_loc7`='¡Estamos preparados para cualquier cosa!' WHERE `ID`=35993;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검독수리 알이 깨졌습니다...', `MaleText_loc4`='猛鹫的蛋被毁了……', `MaleText_loc5`='猛鷲的卵已被摧毀...', `MaleText_loc7`='El huevo de aguilón está destrozado...' WHERE `ID`=35994;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 가자고. 날 호위해주는 거 맞지?', `MaleText_loc4`='好吧，我们出发。你会掩护我的，对吗？', `MaleText_loc5`='OK，我們走吧。你會掩護我，對吧?', `MaleText_loc7`='Muy bien, allá vamos. Tú me cubres, ¿no?', `FemaleText_loc1`='좋아요, 가요. 절 호위해주시는 거 맞죠?', `FemaleText_loc4`='好吧，我们出发。你会掩护我的，对吗？', `FemaleText_loc5`='OK，我們走吧。你會掩護我，對吧?', `FemaleText_loc7`='Muy bien, allá vamos. Tú me cubres, ¿no?' WHERE `ID`=35995;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 지역에서 나가의 수가 꾸준히 늘어나고 있습니다...', `FemaleText_loc4`='这里的纳迦数量正在稳定地持续增长……', `FemaleText_loc5`='納迦在此的數量持續攀升...', `FemaleText_loc7`='El número de nagas no deja de aumentar a ritmo constante...' WHERE `ID`=35996;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대격변이 이 땅을 갈라놓으면서, 나가가 육지까지 침범했지요...', `FemaleText_loc4`='大灾变撕裂了这里的陆地，让纳迦能够进入内陆……', `FemaleText_loc5`='大災變將這片大地震裂，讓納迦上了陸地...', `FemaleText_loc7`='El Cataclismo dividió la tierra en este lugar y permitió a los nagas llegar isla adentro...' WHERE `ID`=35997;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아즈샤라의 여사제라니! 그녀가 조직을 이끄는 걸까요?', `FemaleText_loc4`='一名艾萨拉的女祭司！难道是她在统率他们吗？', `FemaleText_loc5`='艾薩拉的女祭司!是否就是她帶頭的?', `FemaleText_loc7`='¡Una sacerdotisa de Azshara! ¿Acaso podría ella guiar nuestros esfuerzos?' WHERE `ID`=35998;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저들은 이 지역 전체를 샅샅이 뒤지고 있습니다. 저들이 찾는 게 무엇인지 알아내야 합니다!', `FemaleText_loc4`='他们正在这一地区横行肆虐。我们必须查清楚，他们在这里寻找什么！', `FemaleText_loc5`='他們正在搜索整個地區。我們必須查出他們在找的是什麼!', `FemaleText_loc7`='Están peinando toda la región. ¡Debemos descubrir qué es lo que buscan!' WHERE `ID`=35999;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이곳 물 자체가 일어나 저들과 맞서 싸우려고 하는데, 왜일까요? 의문은 많건만 답은 적군요...', `FemaleText_loc4`='这里的水体本身也在对抗他们。这是为什么？我们有很多问题，却只有很少的答案……', `FemaleText_loc5`='在這的海洋起身與他們對抗，這是為什麼?問題很多，但答案卻很少。', `FemaleText_loc7`='En este lugar hasta el agua misma se alza para luchar contra ellos, pero ¿por qué? Muchas preguntas y muy pocas respuestas...' WHERE `ID`=36000;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$c님, 이제 돌아오시지요. 할 일이 많답니다.', `FemaleText_loc4`='马上来找我，$c。我们还有很多事情要做。', `FemaleText_loc5`='回到我這，$c。我們還有很多事要做。', `FemaleText_loc7`='Regresa a mí, $c. Hay mucho que hacer.' WHERE `ID`=36001;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이놈들을 나한테서 떼주려고 온 거 아니야?', `MaleText_loc4`='我想你是来帮我挡住那些东西的吧？', `MaleText_loc5`='我以為你不會讓這些東西接近我?', `MaleText_loc7`='Creía que ibas a impedir que esas cosas se me echaran encima.', `FemaleText_loc1`='이놈들을 저한테서 떼주려고 오신 거 아니에요?', `FemaleText_loc4`='我想你是来帮我挡住那些东西的吧？', `FemaleText_loc5`='我以為你不會讓這些東西接近我?', `FemaleText_loc7`='Creía que ibas a impedir que esas cosas se me echaran encima.' WHERE `ID`=36002;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공격을 받는데 어떻게 캐내는 일을 할 수 있겠어?', `MaleText_loc4`='如果我遭到攻击，就没办法采矿了。', `MaleText_loc5`='我被攻擊要如何才能採完礦?', `MaleText_loc7`='¿Cómo quieres que trabaje en la mina si me están atacando?', `FemaleText_loc1`='공격을 받는데 어떻게 캐내는 일을 할 수 있겠어요?', `FemaleText_loc4`='如果我遭到攻击，就没办法采矿了。', `FemaleText_loc5`='我被攻擊要如何才能採完礦?', `FemaleText_loc7`='¿Cómo quieres que trabaje en la mina si me están atacando?' WHERE `ID`=36003;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 사람들처럼 우리도 여기에서 죽겠지. 안 그래?', `MaleText_loc4`='我们会像其他人一样死在这里，对不对？', `MaleText_loc5`='我們會像其他人一樣死在這，對嗎?', `MaleText_loc7`='Vamos a morir todos como los demás, ¿verdad?', `FemaleText_loc1`='다른 사람들처럼 우리도 여기에서 죽겠죠. 그렇죠?', `FemaleText_loc4`='我们会像其他人一样死在这里，对不对？', `FemaleText_loc5`='我們會像其他人一樣死在這，對嗎?', `FemaleText_loc7`='Vamos a morir todos como los demás, ¿verdad?' WHERE `ID`=36004;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 집에 가고 싶다고.', `MaleText_loc4`='我想回家了。', `MaleText_loc5`='我現在想回家。', `MaleText_loc7`='Ahora quiero irme a casa.', `FemaleText_loc1`='이제 집에 가고 싶어요.', `FemaleText_loc4`='我想回家了。', `FemaleText_loc5`='我現在想回家。', `FemaleText_loc7`='Ahora quiero irme a casa.' WHERE `ID`=36005;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 일을 하는데 너무 짜게 준다고. 아니지! 전혀 안 준단 말이야!', `MaleText_loc4`='要让我做这种事，他们付的酬劳还不够。等等！他们根本就没有给过我一点酬劳！', `MaleText_loc5`='他們付我太少錢了。等一下!他們根本沒有付我任何錢!', `MaleText_loc7`='No me pagan suficiente como para aguantar esto. ¡Espera un segundo! ¡Ni siquiera me están pagando!', `FemaleText_loc1`='이런 일을 하는데 너무 짜게 준다고요. 아니지! 전혀 안 준단 말이에요!', `FemaleText_loc4`='要让我做这种事，他们付的酬劳还不够。等等！他们根本就没有给过我一点酬劳！', `FemaleText_loc5`='他們付我太少錢了。等一下!他們根本沒有付我任何錢!', `FemaleText_loc7`='No me pagan suficiente como para aguantar esto. ¡Espera un segundo! ¡Ni siquiera me están pagando!' WHERE `ID`=36006;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 광석을 캐러 왔고, 당신은 싸우러 왔잖아. 가서 싸우라고!', `MaleText_loc4`='我到这里来是为了挖矿，你到这里来是为了战斗。明白了吗！', `MaleText_loc5`='我來這是挖礦的，你來這是戰鬥的，懂不懂啊!', `MaleText_loc7`='Estoy aquí para trabajar en la mina, tú estás aquí para luchar. ¡A ver si lo captas!', `FemaleText_loc1`='난 광석을 캐러 왔고, 당신은 싸우러 왔잖아요. 가서 싸워요!', `FemaleText_loc4`='我到这里来是为了挖矿，你到这里来是为了战斗。明白了吗！', `FemaleText_loc5`='我來這是挖礦的，你來這是戰鬥的，懂不懂啊!', `FemaleText_loc7`='Estoy aquí para trabajar en la mina, tú estás aquí para luchar. ¡A ver si lo captas!' WHERE `ID`=36007;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 동굴 벽화를 보면 섬뜩해지지요. 저를 죽이려는 저 원숭이는 말할 것도 없고요!', `MaleText_loc4`='这些洞里的壁画已经快把我吓跑了。更不要说那些想要杀我的猴子了！！', `MaleText_loc5`='這些洞穴中的圖像讓我毛骨聳然。更別說那些想要殺了我的猴子們!', `MaleText_loc7`='Esas pinturas rupestres me están poniendo nervioso. ¡POR NO MENCIONAR A LOS MONOS QUE ESTÁN INTENTANDO MATARME!', `FemaleText_loc1`='이 동굴 벽화를 보면 섬뜩해져요. 저를 죽이려는 저 원숭이는 말할 것도 없고요!', `FemaleText_loc4`='这些洞里的壁画已经快把我吓跑了。更不要说那些想要杀我的猴子了！！', `FemaleText_loc5`='這些洞穴中的圖像讓我毛骨聳然。更別說那些想要殺了我的猴子們!', `FemaleText_loc7`='Esas pinturas rupestres me están poniendo nerviosa. ¡POR NO MENCIONAR A LOS MONOS QUE ESTÁN INTENTANDO MATARME!' WHERE `ID`=36008;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 조상과 마찬가지로, 원숭이들도 카자마이트 때문에 지능이 높아진 게 틀림없어.', `MaleText_loc4`='我确信卡亚矿强化了那些猴子的智力，就如同它们曾经提升我们远古祖先的智力一样。', `MaleText_loc5`='我確定卡迦邁礦石同樣對這些猴子有增長智能的影響，就像它對我們古代祖先的影響一樣。', `MaleText_loc7`='Estoy seguro de que la kaja''mita tiene el mismo efecto de aumentar la inteligencia en los monos que el que tuvo en nuestros antepasados.', `FemaleText_loc1`='우리 조상과 마찬가지로, 원숭이들도 카자마이트 때문에 지능이 높아진 게 틀림없어요.', `FemaleText_loc4`='我确信卡亚矿强化了那些猴子的智力，就如同它们曾经提升我们远古祖先的智力一样。', `FemaleText_loc5`='我確定卡迦邁礦石同樣對這些猴子有增長智能的影響，就像它對我們古代祖先的影響一樣。', `FemaleText_loc7`='Estoy seguro de que la kaja''mita tiene el mismo efecto de aumentar la inteligencia en los monos que el que tuvo en nuestros antepasados.' WHERE `ID`=36009;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 가자고.', `MaleText_loc4`='我们走吧。', `MaleText_loc5`='我們繼續吧。', `MaleText_loc7`='En marcha.', `FemaleText_loc1`='자, 가요.', `FemaleText_loc4`='我们走吧。', `FemaleText_loc5`='我們繼續吧。', `FemaleText_loc7`='En marcha.' WHERE `ID`=36010;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 덩어리는 다 캤어.', `MaleText_loc4`='这块矿已经被采掘干净了。', `MaleText_loc5`='這區已經挖乾淨了。', `MaleText_loc7`='En este trozo ya no hay nada que extraer.', `FemaleText_loc1`='이 덩어리는 다 캤어요.', `FemaleText_loc4`='这块矿已经被采掘干净了。', `FemaleText_loc5`='這區已經挖乾淨了。', `FemaleText_loc7`='En este trozo ya no hay nada que extraer.' WHERE `ID`=36011;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기에선 더 건질 게 없어.', `MaleText_loc4`='我从这里面已经挖不出任何东西了。', `MaleText_loc5`='我沒有辦法從這個裡面挖出任何東西。', `MaleText_loc7`='No puedo sacar nada de este.', `FemaleText_loc1`='여기에선 더 건질 게 없네요.', `FemaleText_loc4`='我从这里面已经挖不出任何东西了。', `FemaleText_loc5`='我沒有辦法從這個裡面挖出任何東西。', `FemaleText_loc7`='No puedo sacar nada de este.' WHERE `ID`=36012;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서는 엄청나게 횡재했어!', `MaleText_loc4`='看来我们找到这地方的头等奖了！', `MaleText_loc5`='我們中獎了!', `MaleText_loc7`='¡Nos ha tocado el Gordo con este lugar!', `FemaleText_loc1`='여기서는 엄청나게 횡재했어요!', `FemaleText_loc4`='看来我们找到这地方的头等奖了！', `FemaleText_loc5`='我們中獎了!', `FemaleText_loc7`='¡Nos ha tocado el Gordo con este lugar!' WHERE `ID`=36013;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 케잔에 있을 때 중급 회계사였다는 얘기했던가? 몇 년 일했었는데. 혹시 내 이름 알아?', `MaleText_loc4`='我有没有告诉过你，我在科赞的公司里曾经是一名中级会计？我为你工作了好几年。你知道我的名字吗？', `MaleText_loc5`='我有跟你說過我在凱贊的公司裡是個中階會計師嗎?我在你下面工作了好幾年。你知道我的名字嗎?', `MaleText_loc7`='¿Te he contado ya que en Kezan yo trabajaba en la compañía como contable de nivel medio? Trabajé allí durante cuatro años. ¿Habías oído hablar de mí siquiera?', `FemaleText_loc1`='제가 케잔에 있을 때 중급 회계사였다는 얘기했던가요? 몇 년 일했었는데. 혹시 제 이름 아세요?', `FemaleText_loc4`='我有没有告诉过你，我在科赞的公司里曾经是一名中级会计？我为你工作了好几年。你知道我的名字吗？', `FemaleText_loc5`='我有跟你說過我在凱贊的公司裡是個中階會計師嗎?我在你下面工作了好幾年。你知道我的名字嗎?', `FemaleText_loc7`='¿Te he contado ya que en Kezan yo trabajaba en la compañía como contable de nivel medio? Trabajé allí durante cuatro años. ¿Habías oído hablar de mí siquiera?' WHERE `ID`=36014;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 원숭이들이 벌써 우리 카자마이트 매장량 대부분을 캐내 갔다고.', `MaleText_loc4`='那些猴子已经将这里的大部分卡亚矿都挖走了。', `MaleText_loc5`='猴子們把大部份的卡迦邁礦都從礦場中取走了。', `MaleText_loc7`='Los monos ya han extraído casi toda la kaja''mita del depósito.', `FemaleText_loc1`='저 원숭이들이 벌써 우리 카자마이트 매장량 대부분을 캐내 갔어요.', `FemaleText_loc4`='那些猴子已经将这里的大部分卡亚矿都挖走了。', `FemaleText_loc5`='猴子們把大部份的卡迦邁礦都從礦場中取走了。', `FemaleText_loc7`='Los monos ya han extraído casi toda la kaja''mita del depósito.' WHERE `ID`=36015;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 폭탄이 좀 있다면 더 바랄 게 없을 텐데.', `MaleText_loc4`='现在我还不打算进行爆破。', `MaleText_loc5`='現在有什麼是比一些炸藥來的更有用的。', `MaleText_loc7`='Lo que daría por unos cuantos explosivos ahora mismo.', `FemaleText_loc1`='지금 폭탄이 좀 있다면 더 바랄 게 없을 거예요.', `FemaleText_loc4`='现在我还不打算进行爆破。', `FemaleText_loc5`='現在有什麼是比一些炸藥來的更有用的。', `FemaleText_loc7`='Lo que daría por unos cuantos explosivos ahora mismo.' WHERE `ID`=36016;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 왜 일은 나만 하는 거지?', `MaleText_loc4`='嗨，为什么我们要在这里做这种工作？', `MaleText_loc5`='喂，為什麼都是我在工作?', `MaleText_loc7`='Oye, ¿por qué estoy haciendo yo todo el trabajo?', `FemaleText_loc1`='이봐, 왜 일은 저만 하는 거죠?', `FemaleText_loc4`='嗨，为什么我们要在这里做这种工作？', `FemaleText_loc5`='喂，為什麼都是我在工作?', `FemaleText_loc7`='Oye, ¿por qué estoy haciendo yo todo el trabajo?' WHERE `ID`=36017;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기까지면 충분해. 이제 내 힘으로 나갈게. 호위해줘서 고마워, $n.', `MaleText_loc4`='危险已经过去了。我可以自己继续前进。感谢你的护送，$n。', `MaleText_loc5`='這樣就可以了，剩下的路我可以自己走出去。謝謝你的護送，$n。', `MaleText_loc7`='Ya está bien por ahora. A partir de aquí puedo seguir solo. Gracias por escoltarme, $n.', `FemaleText_loc1`='여기까지면 충분해요. 이제 제힘으로 나갈게요. 호위해줘서 고마워요, $n 님.', `FemaleText_loc4`='危险已经过去了。我可以自己继续前进。感谢你的护送，$n。', `FemaleText_loc5`='這樣就可以了，剩下的路我可以自己走。謝謝你的護送，$n。', `FemaleText_loc7`='Ya está bien por ahora. A partir de aquí puedo seguir sola. Gracias por escoltarme, $n.' WHERE `ID`=36018;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여러분의 다음 상대를 잡느라 희생자가 많이 나왔답니다!', `MaleText_loc4`='为了抓住你就要见到的这个挑战者，我们可是蒙受了很大的伤亡！', `MaleText_loc5`='我們在擄獲你的下一場挑戰者時傷亡慘重!', `MaleText_loc7`='¡Sufrimos muchas pérdidas mientras capturábamos a tu siguiente reto!' WHERE `ID`=36019;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기, 댐윅 씨. 다른 광부가 필요합니다만...', `MaleText_loc4`='呃，戴姆维克，我还需要一个矿工……', `MaleText_loc5`='呃...唐威克，我還需要一個礦工...', `MaleText_loc7`='Ehm, Mechamojada, necesito otro minero...', `FemaleText_loc1`='저기, 댐윅 씨. 다른 광부가 필요한데요...', `FemaleText_loc4`='呃，戴姆维克，我还需要一个矿工……', `FemaleText_loc5`='呃...唐威克，我還需要一個礦工...', `FemaleText_loc7`='Ehm, Mechamojada, necesito otro minero...' WHERE `ID`=36020;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 살아남은 야수들을 보고 울부짖으며, 새로운 힘을 얻어 달려듭니다!', `MaleText_loc4`='%s看到那些存活下来的猛兽，立刻发出一声震耳欲聋的吼叫，再次发动了凶猛的攻击！', `MaleText_loc5`='%s對著倖存野獸怒吼，並且重新提振精神奮戰!', `MaleText_loc7`='¡%s ruge ante la imagen de las bestias supervivientes y lucha con vigor renovado!' WHERE `ID`=36021;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지하로...', `MaleText_loc4`='地下……', `MaleText_loc5`='地底下...', `MaleText_loc7`='Bajo tierra...', `FemaleText_loc1`='지하로...', `FemaleText_loc4`='地下……', `FemaleText_loc5`='地底下...', `FemaleText_loc7`='Bajo tierra...' WHERE `ID`=36022;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발키르 자매는 참으로 호흡이 잘 맞는군요. 저 둘을 잡는 게 왜 그렇게 어려웠는지 이제 알겠습니다.', `MaleText_loc4`='瓦格里的团队协作能力真是令人震惊。现在我终于明白，为什么只是抓住两只瓦格里就会如此困难。', `MaleText_loc5`='華爾琪的合作技巧驚人。我現在知道為什麼我們花了那麼多功夫才抓到她們。', `MaleText_loc7`='El trabajo en equipo de las Val''kyr es impresionante. Ahora entiendo por qué tuvimos tantos problemas para capturarlas.' WHERE `ID`=36023;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇게 센가요?', `MaleText_loc4`='很困难吗？', `MaleText_loc5`='這麼難，嗯?', `MaleText_loc7`='Tan duro, ¿eh?', `FemaleText_loc1`='그렇게 센가요?', `FemaleText_loc4`='很困难吗？', `FemaleText_loc5`='這麼難，嗯?', `FemaleText_loc7`='Tan duro, ¿eh?' WHERE `ID`=36024;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희도 호흡을 더 잘 맞추기만 하면 저 둘을 상대할 수 있을 겁니다.', `MaleText_loc4`='我们必须提高我们的团队协作能力，才能战胜那两个家伙。', `MaleText_loc5`='我們需要強化我們的團隊合作，好對付那兩個傢伙。', `MaleText_loc7`='Tendremos que mejorar nuestro trabajo en equipo para estar a su altura.', `FemaleText_loc1`='저희도 호흡을 더 잘 맞추기만 하면 저 둘을 상대할 수 있을 거예요.', `FemaleText_loc4`='我们必须提高我们的团队协作能力，才能战胜那两个家伙。', `FemaleText_loc5`='我們需要強化我們的團隊合作，好對付那兩個傢伙。', `FemaleText_loc7`='Tendremos que mejorar nuestro trabajo en equipo para estar a su altura.' WHERE `ID`=36025;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 말을 믿는 게 좋을 겁니다! 이번에 여러분이 상대할 자는 아서스의 가장 강한 발키르 부관 둘이라고요!', `MaleText_loc4`='你最好记住！你要面对的是阿尔萨斯最强大的两个瓦格里侍从！', `MaleText_loc5`='你最好相信這件事!你將要面對阿薩斯手下最強大的華爾琪副官!', `MaleText_loc7`='¡Será mejor que lo creas! ¡Vas a enfrentarte a dos de las tenientes Val''kyr más poderosas de Arthas!' WHERE `ID`=36026;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발키르요? 저흰 준비가 됐습니다.', `MaleText_loc4`='瓦格里？我们已经准备好和他们作战了。', `MaleText_loc5`='華爾琪?我們已經準備好對付她們了。', `MaleText_loc7`='¿Val''kyr? Estamos preparados para enfrentarnos a ellas.', `FemaleText_loc1`='발키르요? 저흰 준비가 됐습니다.', `FemaleText_loc4`='瓦格里？我们已经准备好和他们作战了。', `FemaleText_loc5`='華爾琪?我們已經準備好對付她們了。', `FemaleText_loc7`='¿Val''kyr? Estamos preparados para enfrentarnos a ellas.' WHERE `ID`=36027;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋습니다. 그새 실력이 향상되셨길 빕니다!', `MaleText_loc4`='我希望你能够迅速提高！', `MaleText_loc5`='我希望你能成長快一點!', `MaleText_loc7`='Bueno, espero que mejoréis rápido.' WHERE `ID`=36028;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그냥 놈들을 불러내고 지켜보기나 하시지요.', `MaleText_loc4`='尽管把她们带出来，然后好好看着吧。', `MaleText_loc5`='儘管把她們叫出來，然後瞧瞧。', `MaleText_loc7`='Tan solo volved a sacarlas y mirad.', `FemaleText_loc1`='그냥 놈들을 불러내고 지켜보기나 하시지요.', `FemaleText_loc4`='尽管把她们带出来，然后好好看着吧。', `FemaleText_loc5`='儘管把她們叫出來，然後瞧瞧。', `FemaleText_loc7`='Tan solo volved a sacarlas y mirad.' WHERE `ID`=36029;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='박격포를 가져왔다. 해켈, 공격을 시작해!', `MaleText_loc4`='臼炮射击准备。让他们尝尝苦头，海克尔！', `MaleText_loc5`='迫擊砲小隊來了。哈凱爾，讓他們接手!', `MaleText_loc7`='¡Les toca trabajar a los morteros! ¡Dales duro, Hackel!' WHERE `ID`=36030;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 송곳니의 다리보호구의 필요성을 깨닫습니다.', `MaleText_loc4`='%s发现他需要一些尖牙护腿。', `MaleText_loc5`='%s瞭解到他需要尖牙護腿。', `MaleText_loc7`='%s se da cuenta de que necesita algunos leotardos del Colmillo.', `FemaleText_loc1`='%s|1이;가; 송곳니의 다리보호구의 필요성을 깨닫습니다.', `FemaleText_loc4`='%s发现他需要一些尖牙护腿。', `FemaleText_loc5`='%s瞭解到他需要尖牙護腿。', `FemaleText_loc7`='%s se da cuenta de que necesita algunos leotardos del Colmillo.' WHERE `ID`=36031;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 행운의 낚시 모자를 꿈꿉니다.', `MaleText_loc4`='%s正梦想着获得一顶幸运钓鱼帽。', `MaleText_loc5`='%s空自幻想要幸運漁帽。', `MaleText_loc7`='%s sueña despierto con sombreros de pesca de la suerte.', `FemaleText_loc1`='%s|1이;가; 행운의 낚시 모자를 꿈꿉니다.', `FemaleText_loc4`='%s正梦想着获得一顶幸运钓鱼帽。', `FemaleText_loc5`='%s空自幻想要幸運漁帽。', `FemaleText_loc7`='%s sueña despierta con sombreros de pesca de la suerte.' WHERE `ID`=36032;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마상시합 사무장님께서, 이제 원형경기장이 완성되었으니 저희가 경기 진행을 함께 책임져 줬으면 한다고 말씀하셨습니다. 용사의 자격을 얻은 분들, 그리고 저희에게 능력을 인정받은 분들께서는 이 임무를 도와주셨으면 합니다.', `FemaleText_loc4`='现在，竞技场终于落成了。而锦标赛的管理者也请求我们负责管理在那里面举行的竞技活动。而我们只会邀请那些曾经在我们面前证明过自身实力的真正勇士帮助我们完成这些工作。', `FemaleText_loc5`='由於大競技場已經完工，聯賽總管要求我們分擔一些競賽流程的責任。那些贏得勇士資格的人，以及向我們證明自己價值的人都被要求要來盡這些職責。', `FemaleText_loc7`='El senescal del torneo nos ha pedido que les ayudemos con algunas de las tareas de la competición ahora que el coliseo está acabado. Se pide a los que se han alzado como campeones y han demostrado su valía ante nuestros ojos que ayuden con estas labores.' WHERE `ID`=36033;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 잃어버린 황천의 갈래 다리방어구 강화가죽을 생각하며 탄식합니다.', `MaleText_loc4`='%s因为丢失了他的虚空裂蹄护甲片而非常烦恼。', `MaleText_loc5`='%s為了他失去虛空裂蹄護腿片而感到惋惜。', `MaleText_loc7`='%s lamenta la pérdida de su armadura para pierna grieta abisal.', `FemaleText_loc1`='%s|1이;가; 잃어버린 황천의 갈래 다리방어구 강화가죽을 생각하며 탄식합니다.', `FemaleText_loc4`='%s因为丢失了他的虚空裂蹄护甲片而非常烦恼。', `FemaleText_loc5`='%s為了他失去虛空裂蹄護腿片而感到惋惜。', `FemaleText_loc7`='%s lamenta la pérdida de su armadura para pierna grieta abisal.' WHERE `ID`=36034;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='심판관 마리엘 트루하트 님께서, 이제 원형경기장이 완성되었으니 마상시합을 운영하고 지키는 걸 도와 달라고 하셨습니다. 하지만 저 무능한 은빛 서약단과 함께 일하라고 하시더군요. 녀석들이 얼마나 방해가 되는지 모릅니다.', `FemaleText_loc4`='现在，竞技场已经竣工。裁决者玛蕾尔·图哈特请求我们帮助管理锦标赛和保护赛事安全。她想让我们和那些无能的银色盟约混蛋们一同工作。但他们只会碍事。', `FemaleText_loc5`='由於大競技場完工，審判者瑪瑞爾·真心要求我們來監督並保護聯賽的進行。她要我們跟那些毫無價值的白銀誓盟無賴一起工作，但他們只會礙事。', `FemaleText_loc7`='La justicar Mariel Corazón Veraz nos ha pedido que ayudemos a administrar y defender el torneo ahora que el coliseo está completo. Quiere que trabajemos con esos despreciables chuchos de El Pacto de Plata, pero no hacen más que entorpecer todo.' WHERE `ID`=36035;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 가시덤불 골짜기 낚시 여행을 계획합니다.', `MaleText_loc4`='%s正在计划一次荆棘谷垂钓。', `MaleText_loc5`='%s計畫一趟荊棘谷釣魚之旅。', `MaleText_loc7`='%s planea un viaje a Vega de Tuercespina para pescar.', `FemaleText_loc1`='%s|1이;가; 가시덤불 골짜기 낚시 여행을 계획합니다.', `FemaleText_loc4`='%s正在计划一次荆棘谷垂钓。', `FemaleText_loc5`='%s計畫一趟荊棘谷釣魚之旅。', `FemaleText_loc7`='%s planea un viaje a Vega de Tuercespina para pescar.' WHERE `ID`=36036;
