UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽고 싶지 않습니다!', `MaleText_loc4`='我不想死！', `MaleText_loc5`='我不想死啊!', `MaleText_loc7`='¡No quiero morir!', `FemaleText_loc1`='죽고 싶지 않아요!', `FemaleText_loc4`='我不想死！', `FemaleText_loc5`='我不想死啊!', `FemaleText_loc7`='¡No quiero morir!' WHERE `ID`=36041;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오그리마에서 경비병 훈련을 받을 때, 스랄은 적과 싸울 때 인내심을 가지고 신중하게 대처해야 한다고 충고했었지.$B$B하지만 나가가 반도를 지배하려 위협하고 있고 스랄은 이제 우리 대족장이 아니야. $C|1이여;여;, 이제 피를 볼 때가 왔네.', `MaleText_loc4`='当我作为一名奥格瑞玛卫兵接受训练的时候，萨尔叮嘱我们在对敌作战的时候需要保持耐心和谨慎。$B$B但纳迦时刻都有可能完全占领这座半岛。萨尔也不再是我的酋长了。现在应该是对敌人予以痛击的时候了，$c。', `MaleText_loc5`='當我在奧格瑪接受成為守衛的訓練時，索爾跟我們強調在面對敵人時必須保持冷靜和謹慎。$B$B但大量的納迦出現威脅著這個半島，索爾也不再是我的大酋長了。該是鮮血四濺的時候了，$c。', `MaleText_loc7`='Cuando me entrené para ser guardia en Orgrimmar, Thrall nos instó a ser pacientes y cautelosos a la hora de tratar con los enemigos.$B$BPero los nagas amenazan con invadir esta península y Thrall ya no es mi jefe de guerra. Ha llegado la hora de derramar sangre, $c.' WHERE `ID`=36042;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='왜 내 일을 방해하느냐?! 무슨 일인지 말해 봐라!', `FemaleText_loc4`='为什么你要干扰我在这里的工作？给我解释清楚！', `FemaleText_loc5`='你為什麼在這干擾我的工作?!快說!', `FemaleText_loc7`='¡¿Por qué interrumpes mi trabajo?! ¡Explícate!' WHERE `ID`=36043;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내게 말을 걸다니... 마땅한 이유가 있어야 할 게다, 피라미야!', `FemaleText_loc4`='你最好想出一个接近我的好理由，小鱼！', `FemaleText_loc5`='你來找我最好是有什麼重要的事，小鯉!', `FemaleText_loc7`='¡Más te vale que tengas una buena razón para abordarme, pezqueñín!' WHERE `ID`=36044;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이건 또 뭐야? 내게 뭘 바라는 것이냐, 피라미야?', `FemaleText_loc4`='这是什么？你想要对我做什么，小鱼？', `FemaleText_loc5`='到底怎樣，小魚?你想要幹麻?', `FemaleText_loc7`='¿Qué es esto? ¿Qué quieres, pezqueñín?' WHERE `ID`=36045;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멋지군요. 여러분이 위대한 용사임을 오늘 여기서 잘 보여주셨습니다. 여러분께서 은빛십자군과 함께 싸워 주신다면, 스컬지에게 이기는 것도 식은 죽 먹기죠!', `MaleText_loc4`='太好了，今天你们证明了自己是强大的勇士。只要你们和银色十字军并肩作战，我们必将战胜天灾军团！', `MaleText_loc5`='太好了，你們今天在此證明了自己是一群偉大的勇士。有你們與銀白十字軍一同奮戰，對抗天譴軍團的戰鬥必然獲勝!', `MaleText_loc7`='Espléndido, hoy han demostrado ser grandes campeones. ¡Con ustedes luchando junto a la Cruzada Argenta, la victoria contra la Plaga es inevitable!' WHERE `ID`=36046;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칭찬의 말씀 감사합니다, 원형경기장 관리인님.', `MaleText_loc4`='感谢你的赞扬，演武场统领。', `MaleText_loc5`='感謝您的讚美，大競技場大師。', `MaleText_loc7`='Apreciamos tus palabras de alabanza, maestro del coliseo.', `FemaleText_loc1`='칭찬의 말씀 감사합니다, 원형경기장 관리인님.', `FemaleText_loc4`='感谢你的赞扬，演武场统领。', `FemaleText_loc5`='感謝您的讚美，大競技場大師。', `FemaleText_loc7`='Apreciamos tus palabras de alabanza, maestro del coliseo.' WHERE `ID`=36047;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당연히 칭송받을 일입니다. 곧 티리온 님께서도 직접 여러분을 치하하실 겁니다. 어라, 갑자기 좀 추워지는 것 같지 않나요?', `MaleText_loc4`='无论给予你怎样的赞扬都不会过份。提里奥肯定想亲自表彰你的功绩。嗨，你有没有突然觉得有些冷？', `MaleText_loc5`='這些讚譽實至名歸。提里奧很快就會想要親自讚美你。喔，你有沒有注意到這裡忽然變得有點冷?', `MaleText_loc7`='Es una alabanza bien merecida. Tirion querrá elogiarlos el mismo dentro de un rato. Oye, ¿se han dado cuenta de que de pronto hace un poco de frío?' WHERE `ID`=36048;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이상하군요...', `MaleText_loc4`='这真奇怪……', `MaleText_loc5`='這有點奇怪...', `MaleText_loc7`='Esto es extraño...', `FemaleText_loc1`='이상하군요...', `FemaleText_loc4`='这真奇怪……', `FemaleText_loc5`='這有點奇怪...', `FemaleText_loc7`='Esto es extraño...' WHERE `ID`=36049;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리를 방해하다니, 쓴맛을 볼 줄 알아라!', `MaleText_loc4`='你竟敢打扰我们，准备好付出代价吧！', `MaleText_loc5`='你要為了干擾我們而付出代價!', `MaleText_loc7`='¡Pagarás por molestarnos!' WHERE `ID`=36050;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당장 그 지긋지긋한 북소리를 멈춰 버리겠다!', `MaleText_loc4`='我要让那可恨的鼓声彻底消失！', `MaleText_loc5`='我會讓那個煉獄鼓聲永遠停止!', `MaleText_loc7`='¡Callaré ese tambor infernal de una vez por todas!' WHERE `ID`=36051;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대체 무슨 짓을 하는 게냐, 멍청아!', `MaleText_loc4`='你以为你在干什么，傻瓜？', `MaleText_loc5`='你以為你在做什麼，蠢貨?', `MaleText_loc7`='¿Qué crees que estás haciendo, $ginsensato:insensata;?' WHERE `ID`=36052;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 로켄 님의 하인을 건드리고 그냥 갈 수 있을 것 같으냐!', `MaleText_loc4`='没有人能在惹恼了洛肯的仆人之后还能全身而退的！', `MaleText_loc5`='沒有人能挑釁洛肯僕從然後拍拍屁股跑掉!', `MaleText_loc7`='¡Nadie provoca a los sirvientes de Loken y sale impune!' WHERE `ID`=36053;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼을 계속 똑바로 들고 계십시오, $n.', `MaleText_loc4`='持剑的手臂要挺直，$n。', `MaleText_loc5`='伸直你拿劍的那隻手臂，$n。', `MaleText_loc7`='Mantén el brazo de la espada recto, $n.' WHERE `ID`=36054;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대는 전사가 아니오! 경계망 안쪽의 안전한 곳으로 가시는 게 좋을 거요... 물론 악의는 없소.', `MaleText_loc4`='你不是战士！你最好回到安全的地方去……当然，我这样说不是要冒犯你。', `MaleText_loc5`='你不是個戰士!我沒惡意...但你最好回到防衛區好好躲好。', `MaleText_loc7`='¡No eres un guerrero! Será mejor que vuelvas a entrar en el perímetro, donde se está a salvo... Sin ofender.' WHERE `ID`=36055;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용사님, 진심으로 유감스럽게 생각합니다만, 십자군 사령관의 시험에 도전할 기회를 다 쓰셨습니다. 이미 아시겠지만 십자군 사령관의 시험은 일주일에 한 번만 치르실 수 있습니다. 이번 주에 얻으신 교훈이 스컬지에 대한 진정한 승리의 밑거름이 되길 빕니다!', `MaleText_loc4`='向你致以我最谦恭的道歉，勇士，但你现在已经没有机会完成这次大十字军的试炼了。不过请记住，你和你的同伴每一周都有一次机会再次开始大十字军的试炼。希望你们在这周得到的教训能够让你们向这里的最终的胜利更迈进一步，并帮助你们彻底战胜天灾军团！', `MaleText_loc5`='我致上最誠摯的歉意，勇士，但你們嘗試完成大十字軍試煉的機會已經用完了。請容我提醒，你和你的冒險夥伴每週能啟動一次大十字軍試煉。希望本週的經驗有助於讓你順利完成這裡的挑戰，以及在對抗天譴軍團時獲得最終的勝利。', `MaleText_loc7`='Mis disculpas más humildes, $gCampeón:Campeona;, pero te has quedado sin oportunidades para completar la Prueba del Gran Cruzado. Como recordatorio, tú y tus compañeros aventureros podréis comenzar la Prueba del Gran Cruzado una vez cada semana. ¡Que las lecciones que habéis aprendido esta semana os acerquen a la victoria final aquí y contra la Plaga!' WHERE `ID`=36056;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 당신의 노고는 절대로 잊히지 않을 겁니다! 제가 그렇게 만들겠습니다.', `FemaleText_loc4`='你在这里建立的功业不会被遗忘，$n！我将确保这一点。', `FemaleText_loc5`='我會確保你在這的努力不會被忘記，$n!', `FemaleText_loc7`='¡Tus hazañas no caerán en el olvido, $n! Yo me encargaré de ello.' WHERE `ID`=36057;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='옛 방식을 전수받지 않았군. 가르쳐 줄 수 있는 게 없다.', `FemaleText_loc4`='你所走的并非旧时的道路。我没有什么可以教你的，孩子。', `FemaleText_loc5`='你沒有接受過傳統的訓練。我沒有什麼可以教你的，孩子。', `FemaleText_loc7`='No estás $giniciado:iniciada; en las tradiciones. No tengo nada que enseñarte, mi $gniño:niña;.' WHERE `ID`=36058;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='늑대인간의 시간도 끝날 것이고, 우리의 시간도 끝날 것이다.$B$B오직 대지와 그 비밀만이 남을 것이야. 배울 준비가 됐나, $n?', `FemaleText_loc4`='狼人会消失。我们也会消失。$B$B只有大地和她的秘密会留存下来。你愿意学习吗，$n？', `FemaleText_loc5`='狼人會死亡。我們的生命總有終點。$B$B只有大地及其秘密會長存於世間。你願意學習嗎，$n?', `FemaleText_loc7`='Los huargen desaparecerán. Nosotros desapareceremos.$b$bSolo la tierra y sus secretos permanecerán. ¿Estás $gdispuesto:dispuesta; a aprender, $n?' WHERE `ID`=36059;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드루이드의 옛 방식을 더 배우고 싶습니다.', `MaleText_loc4`='我想接受更多关于古老的德鲁伊之道的训练。', `MaleText_loc5`='我尋求傳統的德魯伊訓練方式。', `MaleText_loc7`='Deseo recibir más instrucción en las antiguas artes de los druidas.', `FemaleText_loc1`='드루이드의 옛 방식을 더 배우고 싶어요.', `FemaleText_loc4`='我想接受更多关于古老的德鲁伊之道的训练。', `FemaleText_loc5`='我尋求傳統的德魯伊訓練方式。', `FemaleText_loc7`='Deseo recibir más instrucción en las antiguas artes de los druidas.' WHERE `ID`=36060;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마지막 오크 부대다. 눈 깜짝할 사이에 처리해주마!', `MaleText_loc4`='最后的一批兽人很快就要灭亡了！', `MaleText_loc5`='最後一群獸人。他們很快就會倒下!', `MaleText_loc7`='¡La última tanda de orcos! ¡Debería caer rápidamente!', `FemaleText_loc1`='마지막 오크 부대다. 눈 깜짝할 사이에 처리해주마!', `FemaleText_loc4`='最后的一批兽人很快就要灭亡了！', `FemaleText_loc5`='最後一群獸人。他們很快就會倒下!', `FemaleText_loc7`='¡La última tanda de orcos! ¡Debería caer rápidamente!' WHERE `ID`=36061;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽어라, 오크 쓰레기!', `MaleText_loc4`='死吧，兽人渣滓！', `MaleText_loc5`='死吧，獸人雜碎!', `MaleText_loc7`='¡Muere, escoria orca!', `FemaleText_loc1`='죽어라, 오크 쓰레기!', `FemaleText_loc4`='死吧，兽人渣滓！', `FemaleText_loc5`='死吧，獸人雜碎!', `FemaleText_loc7`='¡Muere, escoria orca!' WHERE `ID`=36062;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일단 오크부터 처리하고 그다음엔 해변 아래쪽에 있는 한심한 고블린을 처리하겠다.', `MaleText_loc4`='来到这片海岸的先是那些兽人，然后是这些可怜的地精。', `MaleText_loc5`='海岸先是出現了這些獸人，然後又是這些可悲的哥布林。', `MaleText_loc7`='Primero estos orcos y luego esos patéticos goblins de la orilla.', `FemaleText_loc1`='일단 오크부터 처리하고 그다음엔 해변 아래쪽에 있는 한심한 고블린을 처리하겠다.', `FemaleText_loc4`='来到这片海岸的先是那些兽人，然后是这些可怜的地精。', `FemaleText_loc5`='海岸先是出現了這些獸人，然後又是這些可悲的哥布林。', `FemaleText_loc7`='Primero estos orcos y luego esos patéticos goblins de la orilla.' WHERE `ID`=36063;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 처치하라!', `MaleText_loc4`='把他们全部消灭！', `MaleText_loc5`='殺光他們!', `MaleText_loc7`='¡Matadlos a todos!', `FemaleText_loc1`='모두 처치하라!', `FemaleText_loc4`='把他们全部消灭！', `FemaleText_loc5`='殺光他們!', `FemaleText_loc7`='¡Matadlos a todos!' WHERE `ID`=36064;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 이 시련을 이겨낼 것이다, $n. 이 시련을 이겨내고 나면, 야수들의 가죽으로 옷을 만들어 입고 다닐 것이다.', `MaleText_loc4`='我们会消灭他们的，$n。那些怪兽敌不过我们。', `MaleText_loc5`='我們會處理好的，$n。結束後我們將把這些野獸的皮當成衣服穿。', `MaleText_loc7`='Superaremos esto, $n. Cuando esto termine, vestiremos las pelambres de esas bestias.' WHERE `ID`=36065;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조용, 아주 조용히. 늑대인간이 사방에 있다.', `MaleText_loc4`='一定要非常、非常安静。这里到处都是狼人。', `MaleText_loc5`='要很安靜，很安靜。狼人到處都是。', `MaleText_loc7`='Estate muy, muy callado. Hay huargen por todas partes.' WHERE `ID`=36066;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 훈련받고 싶습니다.', `MaleText_loc4`='我在寻求进一步的训练。', `MaleText_loc5`='我想接受更進一步的訓練。', `MaleText_loc7`='Deseo recibir más instrucción.', `FemaleText_loc1`='더 훈련받고 싶습니다.', `FemaleText_loc4`='我在寻求进一步的训练。', `FemaleText_loc5`='我想接受更進一步的訓練。', `FemaleText_loc7`='Deseo recibir más instrucción.' WHERE `ID`=36067;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 지식을 공유해 늑대인간에게 승리할 수 있다면 물론 그렇게 해 주지.', `FemaleText_loc4`='当然，我会和你分享我的智慧。你可以借助这些智慧帮助我们击败狼人。', `FemaleText_loc5`='當然，我會把我的知識與你分享。尤其是可以幫助我們擊退那些狼人的話。', `FemaleText_loc7`='Claro que compartiré mis conocimientos contigo. Especialmente si eso nos ayuda a derrotar a los huargen.' WHERE `ID`=36068;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='널 가르치기는 힘들 것 같군. 신비로운 힘에 동화되려면 여러 해 동안 마음의 준비가 필요하니까 말이야.', `FemaleText_loc4`='教导你耗费了我很大力气。而为了让自己的心智适应奥术力量，你还需要经历许多个岁月的磨砺。', `FemaleText_loc5`='教導你是件複雜的事。一般必須花上好幾年才能擁有與秘法之力同調的精神素質。', `FemaleText_loc7`='No sería fácil enseñarte. Hacen falta años de preparación mental para encontrar la armonía con los poderes de lo arcano.' WHERE `ID`=36069;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='도움이나 조언이 필요하면 물어봐... 돈 이야기는 물어보지 말고, 응?', `FemaleText_loc4`='你可以向我寻求帮助和建议……只是别向我要钱，好吗？', `FemaleText_loc5`='可以問我的建議或要求我幫忙...但就是不要跟我提到錢，OK?', `FemaleText_loc7`='Pídeme ayuda y consejo... Pero no me pidas dinero, ¿vale?' WHERE `ID`=36070;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이건 정말 내 잘못이 아니야. 왜 그런 눈으로 나를 보는 거지?', `FemaleText_loc4`='我发誓，这不是我的错。为什么你要这样看着我？', `FemaleText_loc5`='我發誓這不是我的錯。你為什麼要這樣看我?', `FemaleText_loc7`='Te juro que no ha sido culpa mía. ¿Por qué me miras así?' WHERE `ID`=36071;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가장 어두운 시대인 지금도 빛의 가르침은 너를 이 세상으로 안내할 것이다.', `FemaleText_loc4`='即使是现在这个最黑暗的时代，圣光的教诲依旧能指引你安然无恙地穿行在这个危险的世界上。', `FemaleText_loc5`='就算在這黑暗的時代，向聖光學習還是可以引導你生存於這個世界。', `FemaleText_loc7`='Incluso ahora, en la hora más oscura, las enseñanzas de la Luz te guiarán por este mundo.' WHERE `ID`=36072;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='빛이 너와 함께하고 있다, $c. 오늘은 아무런 위험도 생기지 않을 거야.', `FemaleText_loc4`='圣光与你同在，$c。今天你必将不会受到伤害。', `FemaleText_loc5`='聖光與你同在，$c。你今天將不會受到任何傷害。', `FemaleText_loc7`='La Luz está contigo, $c. Hoy no sufrirás daño alguno.' WHERE `ID`=36073;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들을 화나게 한 것 같네.', `MaleText_loc4`='我想，我们也许已经激怒他们了。', `MaleText_loc5`='我想我們可能激怒他們了。', `MaleText_loc7`='Creo que puede que les hayamos hecho enfadar.' WHERE `ID`=36074;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 위험한 지금 이 시대에 내 금지된 지식을 기꺼이 너와 공유하겠다. 암흑의 힘이 우리를 보호할 것이다, $g형제:자매;여.', `MaleText_loc4`='很高兴在这个极其危险的时代与你分享我的禁忌知识。黑暗会保护我们，$g兄弟:姐妹;。', `MaleText_loc5`='我很願意在這非常時期和你分享我禁斷的知識。黑暗會保護我們，$g兄弟:姐妹;。', `MaleText_loc7`='Con gran satisfacción compartiré mi conocimiento prohibido contigo en esta época de grandes peligros. La oscuridad nos protegerá, $Ghermano:hermana;.' WHERE `ID`=36075;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 간직한 비밀을 아주 잠깐 경험해 보는 것만으로도 제정신이 아니게 될 수 있지, $c|1이여;여;.', `MaleText_loc4`='对于我所保藏的秘密，即使是最肤浅的一瞥，也能够让你发疯，$c。', `MaleText_loc5`='$c，你要是瞭解了藏於我手中的秘密，就算只是表面的一點點，都會使你發瘋。', `MaleText_loc7`='Incluso el más mínimo atisbo de los secretos que custodio podría hacerte perder la cabeza, $c.' WHERE `ID`=36076;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭔가, 육체의 소유자여?', `MaleText_loc4`='什么事，凡人？', `MaleText_loc5`='什麼，凡人?', `MaleText_loc7`='¿Sí, cacho de carne?' WHERE `ID`=36077;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 탈것을 이용해 크레난 아라나스를 구해 주십시오.$B|TInterface\\Icons\\inv_misc_groupneedmore.blp:64|t', `MaleText_loc4`='用你载具的能力援救克雷南·阿朗纳斯。$B|TInterface\\Icons\\inv_misc_groupneedmore.blp:64|t', `MaleText_loc5`='使用載具的能力來拯救卡瑞南·阿拉納斯。$B|TInterface\\Icons\\inv_misc_groupneedmore.blp:64|t', `MaleText_loc7`='Rescata a Krennan Aranas utilizando la habilidad de tu vehículo.$B|TInterfaceIconsinv_misc_groupneedmore.blp:64|t', `FemaleText_loc1`='당신의 탈것을 이용해 크레난 아라나스를 구해 주십시오.$B|Tinterface\\Icons\\inv_misc_groupneedmore.blp:64|t', `FemaleText_loc4`='用你载具的能力援救克雷南·阿朗纳斯。$B|TInterface\\Icons\\inv_misc_groupneedmore.blp:64|t', `FemaleText_loc5`='使用載具的能力來拯救卡瑞南·阿拉納斯。$B|TInterface\\Icons\\inv_misc_groupneedmore.blp:64|t', `FemaleText_loc7`='Rescata a Krennan Aranas utilizando la habilidad de tu vehículo.$B|TInterfaceIconsinv_misc_groupneedmore.blp:64|t' WHERE `ID`=36078;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='함께 싸울 준비가 되었습니다, 하이드로니스!', `MaleText_loc4`='我已经准备好与你并肩作战了，海卓尼斯！', `MaleText_loc5`='我準備要加入你的戰場了，海德洛尼!', `MaleText_loc7`='¡Estoy listo para unirme a ti en la batalla, Hydronis!', `FemaleText_loc1`='함께 싸울 준비가 되었어요, 하이드로니스!', `FemaleText_loc4`='我已经准备好与你并肩作战了，海卓尼斯！', `FemaleText_loc5`='我準備要加入你的戰場了，海德洛尼!', `FemaleText_loc7`='¡Estoy lista para unirme a ti en la batalla, Hydronis!' WHERE `ID`=36079;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑습니다, 용사님! 십자군 사령관의 시험에 대비해 동료를 모으셨나요? 가장 강하고 뛰어난 용사만이 이 시험에 도전할 수 있습니다. 시험을 치르고 싶으시다면, 먼저 일반 난이도에서 십자군의 시험을 통과하셔야 합니다.', `MaleText_loc4`='欢迎，勇士！你是否已经聚集起力量，做好准备，打算迎接大十字军的试炼的挑战了？只有最强大，最聪明的冒险者才能进行这样的试炼。为了参与这次试炼，你们必须首先完成普通的十字军的试炼。', `MaleText_loc5`='歡迎，勇士!你召集好隊伍，準備要迎接大十字軍試煉的挑戰了嗎?只有最強大以及最純熟的戰士才能進行這場試煉。想接受這個試煉，你必須先完成普通的十字軍試煉。', `MaleText_loc7`='¡$GBienvenido, Campeón:Bienvenida, Campeona;! ¿Has reunido tus fuerzas como preparativo para la Prueba del Gran Cruzado? Solo los combatientes más poderosos y consumados pueden participar en estas pruebas. Para participar en estas pruebas debes haber completado la Prueba del Cruzado normal.' WHERE `ID`=36080;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 십자군의 시험을 통과했습니다.', `MaleText_loc4`='我完成了十字军的试炼。', `MaleText_loc5`='我完成了十字軍試煉。', `MaleText_loc7`='He completado la Prueba del Cruzado.', `FemaleText_loc1`='저는 십자군의 시험을 통과했어요.', `FemaleText_loc4`='我完成了十字军的试炼。', `FemaleText_loc5`='我完成了十字軍試煉。', `FemaleText_loc7`='He completado la Prueba del Cruzado.' WHERE `ID`=36082;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 십자군의 시험을 통과하지 못했습니다.', `MaleText_loc4`='我还没有完成十字军的试炼。', `MaleText_loc5`='我尚未完成十字軍試煉。', `MaleText_loc7`='No he completado la Prueba del Cruzado.', `FemaleText_loc1`='저는 십자군의 시험을 통과하지 못했어요.', `FemaleText_loc4`='我还没有完成十字军的试炼。', `FemaleText_loc5`='我尚未完成十字軍試煉。', `FemaleText_loc7`='No he completado la Prueba del Cruzado.' WHERE `ID`=36083;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇다면 십자군의 시험을 통과한 후 다시 와주시기 바랍니다.', `MaleText_loc4`='当你在十字军的试炼中赢得胜利的时候再回来。', `MaleText_loc5`='等你完成十字軍試煉之後再回來。', `MaleText_loc7`='Vuelve cuando hayas tenido éxito en la Prueba del Cruzado.' WHERE `ID`=36084;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='십자군 사령관의 시험은 난이도가 더 높은 십자군의 시험이라고 할 수 있습니다. 모든 전투가 십자군의 시험 때보다 더 어려우며, 시험을 치를 수 있는 횟수도 제한되어 있습니다. 50번의 도전 기회를 다 쓰시면 일주일간 시험에 참가하실 수 없습니다. 십자군 사령관의 시험을 성공적으로 완료하시면, 추가 보상으로 공물함을 받으실 수 있고요. 시험을 치를 준비가 되셨습니까?', `MaleText_loc4`='大十字军的试炼比十字军的试炼更加困难。这里的每一个敌人都会变得更强大。而且你无法为自己挑选敌人，除非你们曾经战胜过他们。如果在这周之内，你们进行了50次不成功的尝试，就只能等到下周再继续大十字军的试炼了。在成功地完成大十字军的试炼之后，你们将获得另一个宝物匣。现在，是否已经为这一试炼做好了准备？', `MaleText_loc5`='大十字軍試煉不單只是十字軍試煉的困難版。除了遭遇更困難之外，你無法無止境地嘗試挑戰。在50次未成功的挑戰後，你本週將無法繼續進行試煉的挑戰。當你完成大十字軍試煉的挑戰，你會根據剩餘挑戰次數的數量來給予額外獎勵。你準備好了嗎?', `MaleText_loc7`='La Prueba del Gran Cruzado es una versión más difícil de la Prueba del Cruzado. Cada encuentro será más difícil que el anterior y no podrás intentar superar los encuentros un número ilimitado de veces hasta que ganes. Después de 50 intentos fallidos durante la prueba, no podrás volver a la Prueba del Cruzado esa semana. Tras completar la Prueba del Gran Cruzado con éxito, recibirás un cofre de tributo adicional con recompensas como compensación. ¿Estás a la altura de la prueba?' WHERE `ID`=36085;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죄송합니다, 여행자님. 대흑마법사 윌프레드 피즐뱅이 아직 마상시합 광장에 도착하지 않아서 다음 도전을 하실 수가 없습니다. 그는 다음 주에 올 겁니다.', `MaleText_loc4`='我道歉，冒险者。大术士威尔弗雷德·菲兹班还没有到达比武场。所以，这一试炼的下一场挑战还无法开始。我们相信他会在下个星期赶到。', `MaleText_loc5`='容我道歉，冒險者。大術士威爾弗雷德·菲斯巴恩尚未抵達聯賽場地，因此你們無法進行下一場挑戰。我期待你們下週的表現。', `MaleText_loc7`='Mis disculpas, $gaventurero:aventurera;. El gran brujo Chispobang no ha llegado a los Campos del Torneo aún, así que el siguiente reto aún no está disponible. Esperamos que venga la semana que viene.' WHERE `ID`=36086;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연기되고, 연기되고, 또 연기되는군요. 윌프레드 피즐뱅의 행동에 대한 조사가 아직 진행 중인 관계로 십자군의 시험은 연기되었습니다. 다음 주에 시험을 속개할 테니, 은빛십자군 최고의 기사들을 상대할 채비를 갖추세요!', `MaleText_loc4`='延迟，延迟，还是延迟。十字军的试炼已经陷入了停顿。只有对威尔弗雷德·菲兹班行为的研究得出结果之后，试炼才能继续进行。下一周，试炼应该能够继续，准备好在那时与银色十字军最优秀的骑士作战吧！', `MaleText_loc5`='延遲、延遲和更多的延遲。十字軍試煉目前被延後了，持續到威爾弗雷德·菲斯巴恩行動的調查結束。下週試煉將會繼續舉行，請準備對抗銀白十字軍最強的騎士!', `MaleText_loc7`='Retrasos, retrasos y más retrasos. La Prueba del Cruzado está congelada, a la espera de los resultados de la investigación acerca de las acciones de Wilfred Chispobang. La Prueba continuará la semana que viene, así que prepárate para luchar contra los mejores caballeros de la Cruzada Argenta.' WHERE `ID`=36087;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희 기사들이 아서스의 스컬지 부관들을 잡으러 급히 파견되었습니다. 시험에서 놈들을 다음 상대로 삼을 예정이거든요. 아직 기사들이 포로를 데리고 돌아오지 않았기에 다음 단계의 시험은 연기되었습니다. 다음 주에 다시 들러 주세요.', `MaleText_loc4`='我们派出一队骑士，去俘虏两名阿尔萨斯的天灾军团战将，以作为下一场试炼挑战的敌人。但骑士们并没有带着俘虏回来。所以试炼的下一个阶段也只能暂停了。下周再来看看吧。', `MaleText_loc5`='我們派出了一群騎士去俘虜阿薩斯的一對天譴軍副官，來做為試煉的下一場挑戰。但騎士尚未帶著他們的目標回來，所以下一階段的試煉暫停。請等待下週。', `MaleText_loc7`='Hemos enviado una tropa de caballeros a capturar a los tenientes de la Plaga de Arthas para que sean el siguiente reto de la Prueba. Los caballeros aún no han regresado con su presa, así que la siguiente fase de la Prueba está congelada. Vuelve la semana que viene.' WHERE `ID`=36088;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 끝내줬습니다! 믿을 수가 없어요! 잘하셨습니다! 여러분의 승리를 축하해야겠지요. 저희가 이미 준비를 시작했습니다. 다음 주면 축하연이 준비될 테니 그때 뵙지요!', `MaleText_loc4`='实在是太厉害了！真令人难以置信！干得漂亮！我们已经制定好了为你庆祝胜利的计划。等到下个星期，我们就会做好准备。那时候再见！', `MaleText_loc5`='真是太棒了!不可置信!幹得太好了!我們以經打算要慶祝你的勝利。下週會完成我們的準備，下次見!', `MaleText_loc7`='¡Eso ha sido espléndido! ¡Increíble! ¡Bien hecho! Ya estamos planeando la celebración de tu victoria. Nuestros preparativos estarán listos la semana que viene. ¡Hasta entonces!' WHERE `ID`=36089;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방벽을 사수하라! 적에게 한 치도 내주지 마라!', `MaleText_loc4`='守住工事！绝不让他们前进一寸！', `MaleText_loc5`='守住陣地!不要讓他們前進半吋!', `MaleText_loc7`='¡Cuiden las barricadas! ¡No les den ni un centímetro!' WHERE `ID`=36090;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발사!', `MaleText_loc4`='射击！', `MaleText_loc5`='開火!', `MaleText_loc7`='¡Fuego!' WHERE `ID`=36091;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들을 막아라!', `MaleText_loc4`='把他们打退！', `MaleText_loc5`='趕走他們!', `MaleText_loc7`='¡Que no avancen!' WHERE `ID`=36092;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='남쪽으로 계속 이동하는 게 계획이다. 상업 지구로 되돌아갈 수는 없어. 그곳은 안전하지 않거든.', `FemaleText_loc4`='计划是继续向南移动。我们不能回到商人区去了。那里不安全。', `FemaleText_loc5`='計畫就是繼續往南移動。我們不能回到商業廣場，那不安全。', `FemaleText_loc7`='El plan es seguir yendo al sur. No podemos volver a la Plaza de los Mercaderes. No es segura.' WHERE `ID`=36093;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭉쳐야 살 수 있다. 여러 사람이 함께 움직이도록.', `FemaleText_loc4`='我们必须团结一致才能生存下去。我们要结队行动。', `FemaleText_loc5`='我們必須團結才能生存。以小組的方式前進。', `FemaleText_loc7`='Debemos permanecer juntos para sobrevivir. Moveos en grupos.' WHERE `ID`=36094;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='거의 다 왔다. 근위병들이 우리를 지켜줄 거야.', `FemaleText_loc4`='国王的人会保护我们。再坚持一会儿。', `FemaleText_loc5`='國王的人會保護我們。我們就快到了。', `FemaleText_loc7`='Los hombres del Rey nos protegerán. Casi hemos llegado.' WHERE `ID`=36095;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 피라미들에게 한 짓을 후회하게 해 주겠다, 멍청한 놈아!', `FemaleText_loc4`='你对我的小鱼都做了些什么？！你要付出代价，傻瓜！', `FemaleText_loc5`='你將會為如何對待我的小鯉魚而付出代價，蠢貨!', `FemaleText_loc7`='¡Pagarás por lo que les has hecho a mis pezqueñines!' WHERE `ID`=36096;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<목소리를 낮추라고 손짓하는 킬라그>', `MaleText_loc4`='<基拉格示意你压低声音。>', `MaleText_loc5`='<奇拉格以手勢要你把音量降低。>', `MaleText_loc7`='<Kilag te indica con un gesto que bajes la voz.>' WHERE `ID`=36097;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 공포와 분노에 싸여 쉭쉭거립니다!', `FemaleText_loc4`='%s在惊骇和愤怒中发出“嘶嘶” 的吼声！', `FemaleText_loc5`='%s發出了恐懼和憤怒的尖叫!', `FemaleText_loc7`='¡%s suelta un bufido lleno de horror e ira!' WHERE `ID`=36098;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아라나스를 구출했다! 공격!', `MaleText_loc4`='我们救出阿朗纳斯了！任意开火！', `MaleText_loc5`='救到阿拉納斯了!自由開火!', `MaleText_loc7`='¡Tenemos a Aranas! ¡Fuego!' WHERE `ID`=36099;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='넌 넵튤론을... 지킬 수 없다!', `FemaleText_loc4`='你救不了……耐普图隆！', `FemaleText_loc5`='你無法拯救...奈普圖隆!', `FemaleText_loc7`='¡No puedes salvar... a Neptulon!' WHERE `ID`=36100;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 자신의 힘이 사라지자 날카로운 고함을 지릅니다!', `FemaleText_loc4`='当%s的力量消散时，她发出一阵能刺穿耳膜的尖叫声！', `FemaleText_loc5`='%s因為力量的消散而發出了尖銳的叫聲', `FemaleText_loc7`='¡%s emite un grito agudo y penetrante a medida que pierde su poder!' WHERE `ID`=36101;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세상에! 동굴 벽화가 전부 왜 이런 거지? 이크, 지금 원숭이 소리 나지 않았어?', `MaleText_loc4`='喔！那座洞里都画了些什么？嗯，我听到的是猴子叫声吗？！', `MaleText_loc5`='哇!這些洞穴中的塗鴉是怎麼回事?耶?我是不是聽到猴子的聲音了?', `MaleText_loc7`='¡Aaah! ¿Qué pasa con estas pinturas rupestres? Eh, ¿eso que oigo son monos?', `FemaleText_loc1`='세상에! 동굴 벽화가 전부 왜 이런가요? 이런, 지금 원숭이 소리 나지 않았나요?', `FemaleText_loc4`='喔！那座洞里都画了些什么？嗯，我听到的是猴子叫声吗？！', `FemaleText_loc5`='哇!這些洞穴中的塗鴉是怎麼回事?耶?我是不是聽到猴子的聲音了?', `FemaleText_loc7`='¡Aaah! ¿Qué pasa con estas pinturas rupestres? Eh, ¿eso que oigo son monos?' WHERE `ID`=36102;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='늑대인간의 주의가 계속해서 도시 안으로 쏠리게 해야 하네. 생존자들이 어스름 안식처로 도망치려면 말이야.', `MaleText_loc4`='我们必须在城里吸引狼人的注意。这是让幸存者逃往暮湾镇的唯一机会。', `MaleText_loc5`='我們必須讓狼人的注意力留在城裡。這是唯一讓生存者逃到暮色港的機會。', `MaleText_loc7`='Que los huargen sigan enfocados en la ciudad, Genn. Así los sobrevivientes podrán llegar a salvo al Refugio del Ocaso.' WHERE `ID`=36103;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 되네, 왕자. 부왕께서는 한쪽에만 주의를 기울여야 해. 자네가 남으면 걱정돼서 마음이 산란해질 테지.', `MaleText_loc4`='不行，孩子。吉尔尼斯的国王必须心无旁骛。不能让你的父亲分心担忧你的安危。', `MaleText_loc5`='想都別想，孩子。吉爾尼斯需要國王完整的注意力。不能讓你的父親一直猜測他孩子是否還活著。', `MaleText_loc7`='Para nada, niño. Gilneas necesitará toda la atención de su rey. No permitiré que tu padre se esté preguntando si su hijo estará vivo.' WHERE `ID`=36104;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 부하들과 함께 새벽빛 대성당 안에 매복할 걸세. 이미 명령을 내렸고, 대포도 배치하는 중이야. 피난민들을 부탁하네.', `MaleText_loc4`='我们会在圣光黎明大教堂里死守。我已下令，并布置了火炮。吉恩，好好领导人民。', `MaleText_loc5`='我和我的人會躲在聖光黎明大教堂。我已經發出命令，火砲也正在部署。好好領導我們的子民，吉恩。', `MaleText_loc7`='Mis hombres y yo nos parapetaremos en la Catedral del Alba. Ya di la orden y los cañones están en camino. Guía bien a nuestro pueblo, Genn.' WHERE `ID`=36105;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 왕실근위병과 함께 도시에 머무르겠습니다. 당연히 제가 할 일입니다.', `MaleText_loc4`='我要和皇家卫士一起留下来，父亲。这是我的责任。', `MaleText_loc5`='我會和皇家守衛一起斷後，父親。這是我對吉爾尼斯的責任。', `MaleText_loc7`='Yo me quedaré con la Guardia Real, padre. Es mi deber, por Gilneas.' WHERE `ID`=36106;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게든 관문을 지나 어스름 안식처로 가면 안전할 걸세. 동부 산맥을 지나는 건 사실상 불가능해.', `MaleText_loc4`='要是我们能通过暮湾镇的大门，我们就安全了。东边的山脉几乎是无法通行的。', `MaleText_loc5`='如果我們可以穿過大門進入暮色港，我們就安全了。東邊的山脈幾乎是無法穿越的。', `MaleText_loc7`='Si pasamos las puertas de Refugio del Ocaso estaremos a salvo. Las montañas del este son casi infranqueables.' WHERE `ID`=36107;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 칼을 맞대고 싸우다니, 큰 실수였네. 늑대인간에게 이렇게 질 리가 없는데.', `MaleText_loc4`='我们不应该愚蠢地相互残杀，达利乌斯。这些狼人原本毫无机会的。', `MaleText_loc5`='我們太傻了，居然自相殘殺，達瑞亞斯。若非如此，狼人根本沒有機會。', `MaleText_loc7`='Qué tontos fuimos al luchar entre nosotros, Darius. Podríamos haber aplastado a los huargen.' WHERE `ID`=36108;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='킬라그, 전진하겠네.', `MaleText_loc4`='我们要前进，基拉格。', `MaleText_loc5`='我們將前進，奇拉格。', `MaleText_loc7`='Nosotros avanzamos, Kilag.' WHERE `ID`=36109;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 길을 정리했네. 앞으로 가겠네.', `MaleText_loc4`='$n已经清理出一条道路。我们将继续前进。', `MaleText_loc5`='$n已經清出了一條路。我們將繼續往前。', `MaleText_loc7`='$n ha despejado un camino. Avanzamos.' WHERE `ID`=36110;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오래 기다리지 말게, 킬라그. 전방을 정찰하겠네.', `MaleText_loc4`='不要耽误时间，基拉格。我们将向前搜索。', `MaleText_loc5`='你不會等太久，奇拉格。我們會到前面偵查。', `MaleText_loc7`='No esperes demasiado, Kilag. Nos adelantaremos para explorar.' WHERE `ID`=36111;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고블린 기술은 기묘하고도 아주 효과적이라네. 내가 보장하지!', `MaleText_loc4`='地精技术真是奇异而又可怕。我赞同！', `MaleText_loc5`='哥布林的科技很詭異也很要命。我同意!', `MaleText_loc7`='La tecnología goblin es extraña y mortal. ¡Me gusta!' WHERE `ID`=36112;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전방을 정찰하면서 황량한 전망대까지 가겠네. 킬라그, 거기서 만나세.', `MaleText_loc4`='我们将要向前搜索，直到荒野瞭望台。在那里见，基拉格。', `MaleText_loc5`='我們會先去野生眺望那勘查。那裡見，奇拉格。', `MaleText_loc7`='Nos adelantaremos hasta el Mirador Salvaje para explorar. Nos encontraremos allí, Kilag.' WHERE `ID`=36113;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하게. 이 밀림에는 이런 식물보다 더 무시무시한 것들이 있으니까!', `MaleText_loc4`='小心。这片丛林中能要你性命的东西比这些树还多！', `MaleText_loc5`='注意。在這叢林裡有比這些植物更致命的東西!', `MaleText_loc7`='Cuidado. ¡En esta jungla hay cosas más mortíferas que estas plantas!' WHERE `ID`=36114;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 가야겠네. 다시 만나기를 바라네, $n.', `MaleText_loc4`='该是出发的时间了。希望我们能够再见，$n。', `MaleText_loc5`='該上路了。希望我們會再次相見，$n。', `MaleText_loc7`='Es hora de irme. Espero que volvamos a vernos, $n.' WHERE `ID`=36115;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 움직여야 하네. 황량한 전망대에서 만나세.', `MaleText_loc4`='我们现在应该出发了。在荒野瞭望台见。', `MaleText_loc5`='我們應該上路了，野生眺望再見。', `MaleText_loc7`='Deberíamos movernos ya. Te veremos en el Mirador Salvaje.' WHERE `ID`=36116;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고글 따위! 아무 소용도 없잖아!', `MaleText_loc4`='那副护目镜！根本就不管用！', `MaleText_loc5`='護目鏡!它們完全沒用!', `MaleText_loc7`='¡Las gafas! ¡No hacen nada!', `FemaleText_loc1`='고글 따위! 아무 소용도 없잖아!', `FemaleText_loc4`='那副护目镜！根本就不管用！', `FemaleText_loc5`='護目鏡!它們完全沒用!', `FemaleText_loc7`='¡Las gafas! ¡No hacen nada!' WHERE `ID`=36117;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불이다... 불!', `MaleText_loc4`='火……火！', `MaleText_loc5`='開火...開火!', `MaleText_loc7`='Fuego... ¡FUEGO!', `FemaleText_loc1`='불이다... 불!', `FemaleText_loc4`='火……火！', `FemaleText_loc5`='開火...開火!', `FemaleText_loc7`='Fuego... ¡FUEGO!' WHERE `ID`=36118;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 불 때문에 고난을 겪는군...', `MaleText_loc4`='再次伴随着火焰和痛苦。', `MaleText_loc5`='又是火焰所帶來的苦難。', `MaleText_loc7`='Y otra vez las llamas y el dolor.', `FemaleText_loc1`='또 불 때문에 고난을 겪는군...', `FemaleText_loc4`='再次伴随着火焰和痛苦。', `FemaleText_loc5`='又是火焰所帶來的苦難。', `FemaleText_loc7`='Y otra vez las llamas y el dolor.' WHERE `ID`=36119;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳 전체가 폭발해버릴 거야!', `MaleText_loc4`='这个地方就要爆炸了！', `MaleText_loc5`='這整個地方將會毀滅!', `MaleText_loc7`='¡Este sitio va a saltar por los aires!', `FemaleText_loc1`='이곳 전체가 폭발해버릴 거예요!', `FemaleText_loc4`='这个地方就要爆炸了！', `FemaleText_loc5`='這整個地方將會毀滅!', `FemaleText_loc7`='¡Este sitio va a saltar por los aires!' WHERE `ID`=36120;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 참으로 비생산적인 재해야!', `MaleText_loc4`='我们又制造了一场高投入低产出的大型灾难。', `MaleText_loc5`='這算是我們比較沒有建設性的巨大災難。', `MaleText_loc7`='Este es uno de nuestros desastres colosales menos productivos hasta el momento.', `FemaleText_loc1`='이건 참으로 비생산적인 재해예요!', `FemaleText_loc4`='我们又制造了一场高投入低产出的大型灾难。', `FemaleText_loc5`='這算是我們比較沒有建設性的巨大災難。', `FemaleText_loc7`='Este es uno de nuestros desastres colosales menos productivos hasta el momento.' WHERE `ID`=36121;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='몸에 불이 붙었어. 일지에 기록하라고!', `MaleText_loc4`='我着火了。赶快记录在日志里！', `MaleText_loc5`='我著火了，把這記錄下來!', `MaleText_loc7`='Estoy ardiendo. Apunta eso en los registros.', `FemaleText_loc1`='몸에 불이 붙었어요. 일지에 기록하라고요!', `FemaleText_loc4`='我着火了。赶快记录在日志里！', `FemaleText_loc5`='我著火了，把這記錄下來!', `FemaleText_loc7`='Estoy ardiendo. Apunta eso en los registros.' WHERE `ID`=36122;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앗, 뜨거워!', `MaleText_loc4`='我的身体！', `MaleText_loc5`='我的血肉啊!', `MaleText_loc7`='¡Mi carne!', `FemaleText_loc1`='앗, 뜨거워!', `FemaleText_loc4`='我的身体！', `FemaleText_loc5`='我的血肉啊!', `FemaleText_loc7`='¡Mi carne!' WHERE `ID`=36123;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경비병, 모두 경계 태세로! 침입자 수를 정확히는 모르나, 마루터기를 놈들에게 빼앗겼고 항구 쪽 마을로 통하는 길이 끊겼다. 적의 수가 엄청난 듯하다.', `MaleText_loc4`='准备作战，卫兵们！我们不知道入侵者的数量。但海角已经沦陷，港口城镇的联系被切断了。做好孤军奋战的准备。', `MaleText_loc5`='保持警戒，警衛們!我們不知道有多少入侵者，但是西岬已經淪陷而且我們和港鎮都失聯了。要有以寡擊眾的心理準備。', `MaleText_loc7`='¡Prepárense, guardias! No sabemos cuántos intrusos habrá, pero Los Cabos fueron arrasados y no podemos acceder a los pueblos portuarios. Seguramente ellos serán mas.' WHERE `ID`=36124;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방어선을 확실히 지키고 관문에는 경비병 두 명을 항상 배치하라. 아무도 내보내지 말고, 들이지도 말라.', `MaleText_loc4`='给我守住外围。大门始终要有两名卫兵把守。不允许任何人进出城市。', `MaleText_loc5`='我要你們控制住周圍的區域，每個城門隨時要有兩個警衛。不准進來，不准出去。', `MaleText_loc7`='Quiero el perímetro protegido y dos guardias en los portales a toda hora. Nadie entra, nadie sale.' WHERE `ID`=36125;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 스컬지의 공격을 이겨냈다. 북문 반란군의 공격도 막아냈다. 어떤 위협이 다가오든, 우리는 길니아스를 지켜낼 것이다!', `MaleText_loc4`='天灾入侵时我们守住了吉尔尼斯。北门叛乱时我们也守住了她。无论面对任何新威胁，吉尔尼斯绝不会失守。', `MaleText_loc5`='我們從天譴軍團手上保護了吉爾尼斯。我們從北門反抗軍手上保護了吉爾尼斯。我們也會從這個新威脅的手上保護吉爾尼斯。', `MaleText_loc7`='Protegimos a Gilneas de la Plaga. Protegimos a Gilneas durante la rebelión de Puerta del Norte. Protegeremos a Gilneas de cualquier amenaza que venga.' WHERE `ID`=36126;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='몇 초 후에 다음 집결지점으로 떠날 걸세.', `MaleText_loc4`='我立马就会出发去下一个集结点。', `MaleText_loc5`='再過幾秒鐘我就要前往下個集合點。', `MaleText_loc7`='En unos segundos parto hacia el siguiente punto de encuentro.' WHERE `ID`=36127;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙군, 고마워!', `MaleText_loc4`='谢谢你，谢谢你！', `MaleText_loc5`='謝謝你，謝謝你!', `MaleText_loc7`='¡Gracias, gracias!', `FemaleText_loc1`='고마워요, 고마워!', `FemaleText_loc4`='谢谢你，谢谢你！', `FemaleText_loc5`='謝謝你，謝謝你!', `FemaleText_loc7`='¡Gracias, gracias!' WHERE `ID`=36128;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용사들이여, 살아 있었군! 십자군의 시험에서 상대를 모조리 때려눕혔을 뿐 아니라, 아서스의 계획을 방해하기까지 하다니! 그대들의 노련한 솜씨는 스컬지에 대항하는 강력한 무기가 될 걸세. 잘했네! 은빛십자군 마법사가 그대들을 지상으로 보내 줄 걸세!', `MaleText_loc4`='勇士们，你们还活着！你们不仅克服了十字军试炼的每一场挑战，还直接阻挠了阿尔萨斯的计划！你们的技巧和机智在对抗天灾军团的战斗中一定能发挥极为强大的作用。干得好！请让我的一名法师将你们传送回地面吧！', `MaleText_loc5`='勇士，你們還活著!你們不單是在十字軍試煉中的每場挑戰中獲勝，還直接阻撓了阿薩斯的計畫!你的技巧與機智將會是對抗天譴軍團的利器。做得太好了!讓我的法師把你們傳送回地表!', `MaleText_loc7`='¡Campeones, están vivos! No solo han derrotado cada reto de la Prueba del Cruzado, sino que han fastidiado a Arthas directamente. Su habilidad y astucia serán una poderosa arma contra la Plaga. ¡Bien hecho! ¡Permitan a uno de mis magos que los transporte de vuelta a la superficie!' WHERE `ID`=36129;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='휴, 고마워! 이런 결과가 반복될지 모르니 한 번 확인해 봐야겠어.', `MaleText_loc4`='喔，谢谢！我要好好检查一下这些结果是不是可以重复的。', `MaleText_loc5`='哇嗚，謝了!我要去調查一下看這些結果是否可被重現。', `MaleText_loc7`='¡Fiú, gracias! Voy a ir a comprobar si podemos volver a conseguir esos resultados.', `FemaleText_loc1`='휴, 고마워요! 이런 결과가 반복될지 모르니 한 번 확인해 봐야겠어요.', `FemaleText_loc4`='喔，谢谢！我要好好检查一下这些结果是不是可以重复的。', `FemaleText_loc5`='哇嗚，謝了!我要去調查一下看這些結果是否可被重現。', `FemaleText_loc7`='¡Fiú, gracias! Voy a ir a comprobar si podemos volver a conseguir esos resultados.' WHERE `ID`=36130;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 자주 불길에 휩싸이는 일은 없어야 할 텐데 말이야.', `MaleText_loc4`='我实在是不应该那么频繁地喷出火团来。', `MaleText_loc5`='我真的應該少去碰火焰這種東西。', `MaleText_loc7`='Creo que tengo que procurar estallar en llamas de forma menos frecuente.', `FemaleText_loc1`='너무 자주 불길에 휩싸이는 일은 없어야 할 텐데 말이에요.', `FemaleText_loc4`='我实在是不应该那么频繁地喷出火团来。', `FemaleText_loc5`='我真的應該少去碰火焰這種東西。', `FemaleText_loc7`='Creo que tengo que procurar estallar en llamas de forma menos frecuente.' WHERE `ID`=36131;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기록해 둬. 심각한 화재 발생.', `MaleText_loc4`='记录：火是不好的。', `MaleText_loc5`='記錄一下:火是不好的。', `MaleText_loc7`='Notal mental: fuego malo.', `FemaleText_loc1`='기록해 두세요. 심각한 화재 발생.', `FemaleText_loc4`='记录：火是不好的。', `FemaleText_loc5`='記錄一下:火是不好的。', `FemaleText_loc7`='Notal mental: fuego malo.' WHERE `ID`=36132;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서둘러. 다른 이들도 구해줘!', `MaleText_loc4`='快，救助其他人！', `MaleText_loc5`='快!去救其他人!', `MaleText_loc7`='¡Deprisa! ¡Salva a los demás!', `FemaleText_loc1`='서둘러요. 다른 이들도 구해주세요!', `FemaleText_loc4`='快，救助其他人！', `FemaleText_loc5`='快!去救其他人!', `FemaleText_loc7`='¡Deprisa! ¡Salva a los demás!' WHERE `ID`=36133;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용사들이여, 십자군 사령관의 시험을 통과했군! 오랫동안 전투에 단련된 이들만이 이 시험을 통과할 꿈이라도 꿀 수 있는데 말일세. 그대들은 이 공물함을 받기에 딱 어울리는 이들일세! 다가오는 전투에서 얼음왕관 성채 심장부에 있는 아서스를 상대할 때, 공물함 안에 든 물건들이 유용하게 쓰였으면 좋겠군!', `MaleText_loc4`='勇士们，你们已经完成了大十字军的试炼！只有真正身经百战的冒险者才有可能完成这个试炼。我将这个嘉奖箱交给你们。这是你们应得的奖励！愿箱中的宝物在未来的战斗中能够协助你们直捣冰冠堡垒的核心，战胜阿尔萨斯！', `MaleText_loc5`='勇士，你們通過了大十字軍試煉!只有最善戰的冒險者才能完成這項試煉。讓我獻給你這個箱子，代表了你所應得的獎勵!我們接下來的戰役將要深入冰冠城塞對抗阿薩斯，希望裡面的東西能派得上用場!', `MaleText_loc7`='¡Campeones, habéis superado la Prueba del Gran Cruzado! Solo los aventureros más curtidos en la batalla podrían aspirar a completar esta prueba. Os entrego este cofre de tributo como merecida recompensa. ¡Que su contenido os sirva en la inminente campaña contra Arthas en el corazón de la Ciudadela de la Corona de Hielo!' WHERE `ID`=36134;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='십자군의 시험을 통과했으니, 이제 십자군 사령관의 시험에 참가하는 걸 고려해 보게. 가장 강한 이들만이 감히 이 시험에 도전해볼 수 있지만, 시험을 통과하면 들인 노력에 합당한 보상을 얻는다네.', `MaleText_loc4`='现在，你已经完成了十字军的试炼，你应该考虑去参加大十字军的试炼了。只有最强大的冒险者才有希望完成这一试炼。但你的努力一定能换回丰厚的报偿。', `MaleText_loc5`='現在你完成了十字軍的試煉，你應該考慮回去參加大十字軍試煉。唯有最強大的冒險者能有機會完成試煉，但你將會獲得應有的豐厚獎勵。', `MaleText_loc7`='Ahora que han completado la Prueba del Cruzado, deberán pensar en tomar parte en la Prueba del Gran Cruzado. Solo los aventureros más fuertes pueden aspirar a completar la prueba, pero sus esfuerzos serán bien recompensados.' WHERE `ID`=36135;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가서 연고 발라야겠군.', `MaleText_loc4`='我要去找些药膏来。', `MaleText_loc5`='我要去找看看藥膏。', `MaleText_loc7`='Voy a buscar una pomada.', `FemaleText_loc1`='가서 연고 발라야겠어요.', `FemaleText_loc4`='我要去找些药膏来。', `FemaleText_loc5`='我要去找看看藥膏。', `FemaleText_loc7`='Voy a buscar una pomada.' WHERE `ID`=36136;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보기보단 견딜 만해.', `MaleText_loc4`='它不像是看上去那么糟糕。', `MaleText_loc5`='看起來沒有那麼糟糕。', `MaleText_loc7`='No ha sido tan malo como parecía.', `FemaleText_loc1`='보기보단 견딜 만해요.', `FemaleText_loc4`='它不像是看上去那么糟糕。', `FemaleText_loc5`='看起來沒有那麼糟糕。', `FemaleText_loc7`='No ha sido tan malo como parecía.' WHERE `ID`=36137;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 발을 들이다니, 큰 실수를 하셨군요. 이 마상시합 광장은 신성한 빛의 요새입니다. 그대들의 힘은 비할 바가 못 돼요.', `MaleText_loc4`='你来到了这里，就是犯了一个大错。这些比武场是光明的堡垒，你的力量完全无法与之相比。', `MaleText_loc5`='來到此地，是你犯下的致命錯誤。聯賽場地乃是聖光的基地，你的力量根本不是聖光的對手。', `MaleText_loc7`='Has cometido un grave error al venir aquí. Estos Campos del Torneo son un bastión de la Luz y tu poder no puede hacerle frente.', `FemaleText_loc1`='여기 발을 들이다니, 큰 실수를 하셨군요. 이 마상시합 광장은 신성한 빛의 요새입니다. 그대들의 힘은 비할 바가 못 돼요.', `FemaleText_loc4`='你来到了这里，就是犯了一个大错。这些比武场是光明的堡垒，你的力量完全无法与之相比。', `FemaleText_loc5`='來到此地，是你犯下的致命錯誤。聯賽場地乃是聖光的基地，你的力量根本不是聖光的對手。', `FemaleText_loc7`='Has cometido un grave error al venir aquí. Estos Campos del Torneo son un bastión de la Luz y tu poder no puede hacerle frente.' WHERE `ID`=36139;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미안하지만 그대들은 여기 속한 존재가 아닙니다. 순결한 이 땅을 더럽히게 그냥 둘 수는 없어요.', `MaleText_loc4`='很抱歉，但你并不属于这里，你不能伤害这里的无辜者。', `MaleText_loc5`='我很抱歉，但你不屬於這裡，傷害場地中的無辜者是不被允許的。', `MaleText_loc7`='Lo siento, pero este no es tu lugar y no podemos permitir que hagas daño a los inocentes en los campos.', `FemaleText_loc1`='미안하지만 그대들은 여기 속한 존재가 아닙니다. 순결한 이 땅을 더럽히게 그냥 둘 수는 없어요.', `FemaleText_loc4`='很抱歉，但你并不属于这里，你不能伤害这里的无辜者。', `FemaleText_loc5`='我很抱歉，但你不屬於這裡，傷害場地中的無辜者是不被允許的。', `FemaleText_loc7`='Lo siento, pero este no es tu lugar y no podemos permitir que hagas daño a los inocentes en los campos.' WHERE `ID`=36140;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='축하합니다. 준비가 되시면 달라란으로 통하는 차원문을 이용하시죠!', `MaleText_loc4`='祝贺，请在准备好之后进入这个通向达拉然的传送门！', `MaleText_loc5`='恭喜，等你準備好的時候請通過傳送門前往達拉然。', `MaleText_loc7`='¡Enhorabuena, usa el portal a Dalaran cuando quieras!' WHERE `ID`=36141;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공물함 안에 있는 보상의 질과 양은 십자군 사령관의 시험에서 도전 기회를 몇 번이나 썼는지에 따라 다르다네. 더 적은 횟수의 도전으로 시험을 통과하면 더 좋은 보상을 얻을 수 있지.', `MaleText_loc4`='这只嘉奖箱中的奖励品数量和质量取决于你在大十字军的试炼中进行过多少次不成功的尝试。不成功的尝试越少，得到的奖励就越丰厚。', `MaleText_loc5`='獻禮箱中獎勵的質與量是取決你在大十字軍試煉中有過多少次未成功的嘗試。未成功的嘗試越少，獎勵就越好。', `MaleText_loc7`='La cantidad y calidad de las recompensas que hay en el cofre de tributo dependen del número de intentos fallidos que tengas durante la Prueba del Gran Cruzado. Cuantos menos intentos fallidos tengas, mejor será la recompensa.' WHERE `ID`=36142;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노움 기계공학 전문화를 취소하고 싶습니다!', `MaleText_loc4`='我想要忘掉侏儒工程学分支的知识！', `MaleText_loc5`='我想要遺忘我的地精工程學專精!', `MaleText_loc7`='¡Deseo olvidar mi especialización en ingeniería gnómica!', `FemaleText_loc1`='노움 기계공학 전문화를 취소하고 싶어요!', `FemaleText_loc4`='我想要忘掉侏儒工程学分支的知识！', `FemaleText_loc5`='我想要遺忘我的地精工程學專精!', `FemaleText_loc7`='¡Deseo olvidar mi especialización en ingeniería gnómica!' WHERE `ID`=36143;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노움 기계공학 전문화를 포기하면 관련된 모든 설계도를 잃어버리는데, 그래도 포기하시겠습니까?', `MaleText_loc4`='你真的想要忘掉侏儒工程学分支的知识，并失去所有与之相关的配方吗？', `MaleText_loc5`='你真的想要遺忘你的地精工程學專精，並且失去全部相關結構圖嗎?', `MaleText_loc7`='¿De verdad quieres olvidar tu especialización en ingeniería gnómica y perder todas las recetas asociadas?', `FemaleText_loc1`='노움 기계공학 전문화를 포기하면 관련된 모든 설계도를 잃어버리는데, 그래도 포기하시겠습니까?', `FemaleText_loc4`='你真的想要忘掉侏儒工程学分支的知识，并失去所有与之相关的配方吗？', `FemaleText_loc5`='你真的想要遺忘你的地精工程學專精，並且失去全部相關結構圖嗎?', `FemaleText_loc7`='¿De verdad quieres olvidar tu especialización en ingeniería gnómica y perder todas las recetas asociadas?' WHERE `ID`=36144;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고블린 기계공학 전문화를 포기하면 관련된 모든 설계도를 잃어버리는데, 그래도 포기하시겠습니까?', `MaleText_loc4`='你真的想要忘掉地精工程学分支的知识，并失去所有与之相关的配方吗？', `MaleText_loc5`='你真的想要遺忘你的哥布林工程學專精，並且失去全部相關結構圖嗎?', `MaleText_loc7`='¿De verdad quieres olvidar tu especialización en ingeniería goblin y perder todas las recetas asociadas?', `FemaleText_loc1`='고블린 기계공학 전문화를 포기하면 관련된 모든 설계도를 잃어버리는데, 그래도 포기하시겠습니까?', `FemaleText_loc4`='你真的想要忘掉地精工程学分支的知识，并失去所有与之相关的配方吗？', `FemaleText_loc5`='你真的想要遺忘你的哥布林工程學專精，並且失去全部相關結構圖嗎?', `FemaleText_loc7`='¿De verdad quieres olvidar tu especialización en ingeniería goblin y perder todas las recetas asociadas?' WHERE `ID`=36145;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고블린 기계공학 전문화를 취소하고 싶습니다!', `MaleText_loc4`='我想要忘掉地精工程学分支的知识！', `MaleText_loc5`='我想要遺忘我的哥布林工程學專精!', `MaleText_loc7`='¡Deseo olvidar mi especialización en ingeniería goblin!', `FemaleText_loc1`='고블린 기계공학 전문화를 취소하고 싶어요!', `FemaleText_loc4`='我想要忘掉地精工程学分支的知识！', `FemaleText_loc5`='我想要遺忘我的哥布林工程學專精!', `FemaleText_loc7`='¡Deseo olvidar mi especialización en ingeniería goblin!' WHERE `ID`=36146;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동료가 죽는 모습을 본 %s|1이;가; 분노합니다!', `MaleText_loc4`='看到同伴的死亡，%s被激怒了！', `MaleText_loc5`='隨著目睹同伴的死去，%s陷入暴怒!', `MaleText_loc7`='¡%s se enfurece al ver a su compañero fallecer!' WHERE `ID`=36147;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='킬라그, 저... 어, 그러니까... 음, 정찰병을 잃었습니다.', `MaleText_loc4`='基拉格，我……唔……嗯，我的斥候失踪了。', `MaleText_loc5`='奇拉格，我...呃...不知道怎的...嗯，跟丟了我的斥候。', `MaleText_loc7`='Kilag... Yo... eh, creo que... he perdido a mi explorador.', `FemaleText_loc1`='킬라그, 저... 어, 그러니까... 음, 정찰병을 잃었어요.', `FemaleText_loc4`='基拉格，我……唔……嗯，我的斥候失踪了。', `FemaleText_loc5`='奇拉格，我...呃...不知道怎的...嗯，跟丟了我的斥候。', `FemaleText_loc7`='Kilag... Yo... eh, creo que... he perdido a mi explorador.' WHERE `ID`=36148;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='둘 다 좀 더 조심하게! 우리는 수가 얼마 안 되니 말일세!', `MaleText_loc4`='你们两个要更加小心！我们的人只有这么点了！', `MaleText_loc5`='你們兩個人小心點!我們人數有限!', `MaleText_loc7`='¡Ustedes dos tengan más cuidado! ¡Tampoco somos tantos!' WHERE `ID`=36149;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐라고?! 내가 광부 뽑아내는 기계로 보여?$B$B안에 상황이 얼마나 나쁜 거야?', `MaleText_loc4`='什么？！你认为我是矿工出身？$B$B你还能有更糟糕的想法吗？', `MaleText_loc5`='什麼?!你以為我是礦工生產器嗎?$B$B裡面是能有多糟?', `MaleText_loc7`='¡¿Qué?! ¿Crees que los mineros crecen en los árboles?$b$b¿Tan malo es?' WHERE `ID`=36150;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 한 번 미안해요. 하지만 이건 그대들이 스스로 선택한 운명입니다.', `MaleText_loc4`='我再一次道歉，但这是你选择的命运。', `MaleText_loc5`='我再次致歉，但你選擇了這樣的命運。', `MaleText_loc7`='Pido perdón de nuevo, pero tú elegiste este destino.', `FemaleText_loc1`='다시 한 번 미안해요. 하지만 이건 그대들이 스스로 선택한 운명입니다.', `FemaleText_loc4`='我再一次道歉，但这是你选择的命运。', `FemaleText_loc5`='我再次致歉，但你選擇了這樣的命運。', `FemaleText_loc7`='Pido perdón de nuevo, pero tú elegiste este destino.' WHERE `ID`=36151;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='해변 저 끝에 있는 자이로헬기가 보이십니까, $n 님?', `FemaleText_loc4`='看到海滩那边的旋翼机了吗，$n？！', `FemaleText_loc5`='你看到海灘遠方那台螺旋槳機了嗎，$n?', `FemaleText_loc7`='¿Ves ese girocóptero en el extremo de la playa, $n?' WHERE `ID`=36152;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='열쇠를 들고 자이로헬기를 타게!', `MaleText_loc4`='拿上钥匙，然后到旋翼机那里去！', `MaleText_loc5`='拿到鑰匙後趕快到那台螺旋槳機那裡!', `MaleText_loc7`='¡Coge las llaves y súbete a ese girocóptero!' WHERE `ID`=36153;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어떻게 이럴 수가!!', `FemaleText_loc4`='这不可能！', `FemaleText_loc5`='這不可能!', `FemaleText_loc7`='¡No puede ser!' WHERE `ID`=36154;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='복수하고 말겠다!', `FemaleText_loc4`='我们一定会复仇的！', `FemaleText_loc5`='我們將會復仇!', `FemaleText_loc7`='¡Nos vengaremos!' WHERE `ID`=36155;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경고: 반응로 핵이 유실되었습니다!', `MaleText_loc4`='警告：反应堆核心泄露！', `MaleText_loc5`='警告:反應爐核心過熱!', `MaleText_loc7`='ALERTA: ¡Núcleo del reactor vaciado!' WHERE `ID`=36156;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐요! 제 비행기에서 손 떼시죠!', `MaleText_loc4`='嗨！离我的飞行器远点！', `MaleText_loc5`='喂!離我的飛行器遠點!', `MaleText_loc7`='¡Eh! ¡Aléjate de mi máquina voladora!' WHERE `ID`=36157;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 고글을 쓰고 있어야 한다는 거 잊지 말게, $n. 저놈들이 덤비기 전에 발견할 수 있는 유일한 방법이니까.', `MaleText_loc4`='不要忘记带上你的护目镜，$n。只有这样，我们才能在他们扑到我们身上之前发现他们。', `MaleText_loc5`='別忘了戴上你的護目鏡，$n。那是唯一能讓我們被攻擊前就先發現他們的方法。', `MaleText_loc7`='No olvides que no debes quitarte las gafas, $n. Es la única manera de que podamos verles antes de que nos caigan encima.' WHERE `ID`=36158;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='작은 수레를 밀어야 해!', `MaleText_loc4`='我们必须推动小车！', `MaleText_loc5`='我們必須推小礦車!', `MaleText_loc7`='¡Debemos empujar pequeño carrito!' WHERE `ID`=36159;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자이로헬기로 가시오! 당장!', `MaleText_loc4`='到旋翼机那里去！马上！', `MaleText_loc5`='快到螺旋槳機那!現在就去!', `MaleText_loc7`='¡Al girocóptero! ¡Ahora!' WHERE `ID`=36160;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='와, 해냈군요! 아주 잘하셨어요.', `FemaleText_loc4`='啊，你做到了！实在是漂亮。', `FemaleText_loc5`='哈，你辦到了!幹得好。', `FemaleText_loc7`='¡Ah, lo has conseguido! ¡un trabajo excelente!' WHERE `ID`=36161;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와, 그거 정제된 아즈샤리트인가?', `MaleText_loc4`='喔——这就是精炼后的艾萨莱特水晶？', `MaleText_loc5`='哇─那是精煉的艾薩拉水晶?', `MaleText_loc7`='¡Vaya! ¿Eso es... azsharita refinada?', `FemaleText_loc1`='와, 그거 정제된 아즈샤리트인가요?', `FemaleText_loc4`='喔——这就是精炼后的艾萨莱特水晶？', `FemaleText_loc5`='哇─那是精煉的艾薩拉水晶?', `FemaleText_loc7`='¡Vaya! ¿Eso es... azsharita refinada?' WHERE `ID`=36162;
