UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$r, 나는 미래를 보았다.$b$b빨리 행동에 옮기지 않으면 켄타우로스의 땅은 영원히 더럽혀질 것이다.', `MaleText_loc4`='我已经见到了未来，$r。$b$b如果我们不能迅速采取行动，半人马的土地将永远地堕落。', `MaleText_loc5`='我看到了未來，$r。$b$b如果我們不快點行動，半人馬的土地將會永遠的被腐蝕。', `MaleText_loc7`='El futuro me ha sido mostrado, $r.$b$bSi no actuamos inmediatamente, las tierras de los centauros serán presa de la corrupción para siempre.' WHERE `ID`=36164;
