UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, $n. 앉아봐. 불이 꽤 따뜻한데다 원숭이들은 불을 별로 좋아하지 않는 것 같으니 말이야.', `MaleText_loc4`='$n，坐下。火已经热了。这可不是给猴子准备的。', `MaleText_loc5`='$n，坐下來。這些猴子似乎不喜歡熱熱的火。', `MaleText_loc7`='$n, siéntate. El fuego es caliente y parece ser que a los monos no les hace gracia.' WHERE `ID`=36188;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 모든 일을 다 겪고 난 다음에 여기에서 끝이 날 줄 누가 상상이나 했겠어?', `MaleText_loc4`='谁能想到，在我们渡过那么多难关之后，却会在这里结束？', `MaleText_loc5`='誰知道在經歷過那麼多後我們最後會在這裡!', `MaleText_loc7`='¿Quién hubiera pensado que íbamos a terminar así después de todo lo que hemos pasado?' WHERE `ID`=36189;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 보라고. $n|1이야;야;!', `MaleText_loc4`='嗨，看啊，是$n！', `MaleText_loc5`='喂，大夥兒快看，是$n!', `MaleText_loc7`='¡Hey, chicos, miren, es $n!' WHERE `ID`=36190;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 꽤 곤란한 상태에 빠진 거 같은데. 여기에서 벗어나게 해줄 수 있겠어?', `MaleText_loc4`='看样子我们被困在这儿了。你能让我们从这里出去吗？', `MaleText_loc5`='看來我們的狀況不是很樂觀，你可以把我們救出去嗎?', `MaleText_loc7`='Parece que estamos un buen aprieto. ¿Crees que podrás sacarnos de esta?' WHERE `ID`=36191;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='세상에, $n 님, 우린 외딴 섬에 고립됐어요!', `FemaleText_loc4`='哦，$n，我们被困住了！', `FemaleText_loc5`='噢，$n，我們被孤立了!', `FemaleText_loc7`='¡Oh, $n, estamos abandonados en una isla!' WHERE `ID`=36192;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='케잔이 그리워요. 빌지워터 항구를 다시 볼 수 있을까요, $n 님?', `FemaleText_loc4`='我想念科赞。我们还能再看到锈水码头吗，$n？', `FemaleText_loc5`='我懷念凱贊。我們還有機會看到污水港嗎，$n?', `FemaleText_loc7`='Echo de menos Kezan. ¿Crees que volveremos a ver Puerto Pantoque, $n?' WHERE `ID`=36193;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잠깐 여기 앉아 보세요. 모닥불에 게도 굽고 노래도 부르자고요.', `FemaleText_loc4`='和我一起坐一会儿。我们可以唱唱歌，在火上烤烤螃蟹。', `FemaleText_loc5`='跟我坐一會吧。我們可以邊烤螃蟹邊唱歌。', `FemaleText_loc7`='Siéntate aquí conmigo un rato. Podemos asar cangrejos en el fuego y cantar canciones.' WHERE `ID`=36194;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 일은 전부 당신에게 맡길게요. 그런데 우리가 이 섬에서 벗어날 수 있게 무언가 하고 계신가요?', `FemaleText_loc4`='我全都指望你了，但你怎样做才能让我们离开这座岛？', `FemaleText_loc5`='我把希望都放在你身上，但你要怎樣帶我們離開這個島?', `FemaleText_loc7`='Te lo estoy dejando todo a ti, ¿pero qué estás haciendo para sacarnos de esta isla?' WHERE `ID`=36195;
